INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1, 1, 1, 1, 0, 0, 'الم', 'الفاتحۃ', 'بِسۡمِ اللّٰہِ الرَّحۡمٰنِ الرَّحِیۡمِ', 'شروع اللہ کا نام لے کر جو بڑا مہربان نہایت رحم والا ہے۔', 'شروع اللہ کے نام سے جو بڑا مہربان نہایت رحم والا ہے [۱]', 'In the Name of Allah, the Most Beneficent, the Most Merciful.', 'With the name of Allah, the All-Merciful, the Very-Merciful.'),
(2, 1, 2, 1, 0, 0, 'الم', 'الفاتحۃ', 'اَلۡحَمۡدُ لِلّٰہِ رَبِّ الۡعٰلَمِیۡنَ ۙ﴿۱﴾', 'سب طرح کی تعریف اللہ ہی  کیلئے ہے جو تمام مخلوقات کا پروردگار ہے۔', 'سب تعریفیں اللہ کے لئے ہیں [۲] جو پالنے والا سارے جہان کا [۳]', 'All the praises and thanks be to Allah, the Lord of the Alameen (mankind, jinns and all that exists).', 'Praise belongs to Allah, the Lord of all the worlds.'),
(3, 1, 3, 1, 0, 0, 'الم', 'الفاتحۃ', 'الرَّحۡمٰنِ الرَّحِیۡمِ ۙ﴿۲﴾', 'بڑا مہربان نہایت رحم والا۔', 'بےحد مہربان نہایت رحم والا', 'The Most Beneficent, the Most Merciful.', 'the All-Merciful, the Very Merciful.'),
(4, 1, 4, 1, 0, 0, 'الم', 'الفاتحۃ', 'مٰلِکِ یَوۡمِ الدِّیۡنِ ؕ﴿۳﴾', 'انصاف کے دن کا حاکم۔', 'مالک روز جزا کا [۴]', 'The Only Owner (and the Only Ruling Judge) of the Day of Recompense (i.e. the Day of Resurrection)', 'the Master of the Day of Requital.'),
(5, 1, 5, 1, 0, 0, 'الم', 'الفاتحۃ', 'اِیَّاکَ نَعۡبُدُ وَ اِیَّاکَ نَسۡتَعِیۡنُ ؕ﴿۴﴾', 'اے پروردگار ہم تیری ہی عبادت کرتے ہیں اور تجھی سے مدد مانگتے ہیں۔', 'تیری ہی ہم بندگی کرتے ہیں اور تجھی سے مدد چاہتے ہیں [۵]', 'You (Alone) we worship, and You (Alone) we ask for help (for each and everything).', 'You alone do we worship, and from You alone do we seek help.'),
(6, 1, 6, 1, 0, 0, 'الم', 'الفاتحۃ', 'اِہۡدِ نَا الصِّرَاطَ الۡمُسۡتَقِیۡمَ ۙ﴿۵﴾', 'ہم کو سیدھے رستے چلا۔', 'بتلا ہم کو راہ سیدھی', 'Guide us to the Straight Way', 'Take us on the straight path.'),
(7, 1, 7, 1, 0, 0, 'الم', 'الفاتحۃ', 'صِرَاطَ الَّذِیۡنَ اَنۡعَمۡتَ عَلَیۡہِمۡ ۙ۬ غَیۡرِ الۡمَغۡضُوۡبِ عَلَیۡہِمۡ وَ لَا الضَّآلِّیۡنَ ٪﴿۷﴾', 'ان لوگوں کے رستے جن پر تو اپنا فضل و کرم کرتا رہا نہ ان کے جن پر غصے ہوتا رہا اور نہ گمراہوں کے۔ اٰمین۔', 'راہ ان لوگوں کی جن پر تو نے فضل فرمایا [۶] جن پر نہ تیرا غصہ ہوا اور نہ وہ گمراہ ہوئے [۷]', 'The Way of those on whom You have bestowed Your Grace , not (the way) of those who earned Your Anger (such as the Jews), nor of those who went astray (such as the Christians).', 'the path of those on whom You have bestowed Your Grace, not of those who have incurred Your wrath, nor of those who have gone astray.'),
(8, 2, 1, 1, 1, 1, 'الم', 'البقرۃ', 'الٓـمّٓ ۚ﴿۱﴾', 'الم۔', 'الم [۱]', 'Alif-Lam-Meem. (These letters are one of the miracles of the Quran and none but Allah (Alone) knows their meanings).', 'Alif. Lām. Mīm.'),
(9, 2, 2, 1, 1, 1, 'الم', 'البقرۃ', 'ذٰلِکَ  الۡکِتٰبُ لَا رَیۡبَ ۚۖۛ فِیۡہِ ۚۛ ہُدًی  لِّلۡمُتَّقِیۡنَ ۙ﴿۲﴾', 'یہ کتاب یعنی قرآن مجید اس میں کچھ شک نہیں کہ اللہ کا کلام ہے پرہیزگاروں کیلئے راہنما ہے۔', 'اس کتاب میں کچھ شک نہیں [۲] راہ بتلاتی ہے [۳] ڈرنے والوں کو [۴]', 'This is the Book (the Quran), whereof there is no doubt, a guidance to those who are Al-Muttaqoon (the pious and righteous persons who fear Allah much (abstain from all kinds of sins and evil deeds which He has forbidden) and love Allah much (perform all kinds of good deeds which He has ordained)).', 'This Book has no doubt in it - a guidance for the God-fearing,'),
(10, 2, 3, 1, 1, 1, 'الم', 'البقرۃ', 'الَّذِیۡنَ یُؤۡمِنُوۡنَ بِالۡغَیۡبِ وَ یُقِیۡمُوۡنَ الصَّلٰوۃَ وَ  مِمَّا رَزَقۡنٰہُمۡ  یُنۡفِقُوۡنَ ۙ﴿۳﴾', 'جو غیب پر ایمان لاتے اور آداب کے ساتھ نماز پڑھتے اور جو کچھ ہم نے ان کو عطا فرمایا ہے اس میں سے خرچ کرتے ہیں۔', 'جو کہ یقین کرتے ہیں بن دیکھی چیزوں کا [۵] اور قائم رکھتے ہیں نماز کو [۶] اور جو ہم نے روزی دی ہے ان کو اسمیں سے خرچ کرتے ہیں [۷]', 'Who believe in the Ghaib and perform As-Salat (Iqamat-as-Salat), and spend out of what we have provided for them (i.e. give Zakat , spend on themselves, their parents, their children, their wives, etc., and also give charity to the poor and also in Allahs Cause - Jihad, etc.).', 'who believe in the Unseen, and are steadfast in Salāh (prayer), and spend out of what We have provided them;'),
(11, 2, 4, 1, 1, 1, 'الم', 'البقرۃ', 'وَ الَّذِیۡنَ یُؤۡمِنُوۡنَ بِمَاۤ  اُنۡزِلَ اِلَیۡکَ وَ مَاۤ اُنۡزِلَ مِنۡ قَبۡلِکَ ۚ وَ بِالۡاٰخِرَۃِ ہُمۡ یُوۡقِنُوۡنَ ؕ﴿۴﴾', 'اور جو کتاب اے پیغمبر تم پر نازل ہوئی اور جو کتابیں تم سے پہلے پیغمبروں پر نازل ہوئیں سب پر ایمان لاتے اور آخرت کا یقین رکھتے ہیں۔', 'اور وہ لوگ جو ایمان لائے اس پر کہ جو کچھ نازل ہوا تیری طرف اور اس پر کہ جو کچھ نازل ہوا تجھ سے پہلے اور آخرت کو وہ یقینی جانتے ہیں [۸]', 'And who believe in (the Quran and the Sunnah) which has been sent down (revealed) to you (Muhammad Peace be upon him ) and in (the Taurat (Torah) and the Injeel (Gospel), etc.) which were sent down before you and they believe with certainty in the Hereafter. (Resurrection, recompense of their good and bad deeds, Paradise and Hell, etc.).', 'and who believe in what has been revealed to you and what has been revealed before you; and they have faith in the Hereafter.'),
(12, 2, 5, 1, 1, 1, 'الم', 'البقرۃ', 'اُولٰٓئِکَ عَلٰی ہُدًی مِّنۡ رَّبِّہِمۡ ٭ وَ اُولٰٓئِکَ ہُمُ  الۡمُفۡلِحُوۡنَ ﴿۵﴾', 'یہی لوگ اپنے  پروردگار کی طرف سے آئی ہوئی ہدایت پر ہیں اور یہی لوگ کامیاب ہیں۔', 'وہی لوگ ہیں ہدایت پر اپنے پروردگار کی طرف سے اور وہی ہیں مراد کو پہنچنے والے [۹]', 'They are on (true) guidance from their Lord, and they are the successful.', 'It is these who are guided by their Lord; and it is just these who are successful.'),
(13, 2, 6, 1, 1, 1, 'الم', 'البقرۃ', 'اِنَّ الَّذِیۡنَ  کَفَرُوۡا سَوَآءٌ  عَلَیۡہِمۡ ءَاَنۡذَرۡتَہُمۡ  اَمۡ  لَمۡ  تُنۡذِرۡہُمۡ لَا یُؤۡمِنُوۡنَ ﴿۶﴾', 'جو لوگ کافر ہیں انہیں تم نصیحت کرو یا نہ کرو ان کے لئے برابر ہے۔ وہ ایمان نہیں لانے کے۔', 'بیشک جو لوگ کافر ہو چکے برابر ہے ان کو تو ڈرائے یا نہ ڈرائے وہ ایمان نہیں لائیں گے [۱۰]', 'Verily, those who disbelieve, it is the same to them whether you (O Muhammad Peace be upon him ) warn them or do not warn them, they will not believe.', 'Surely for those who have disbelieved, it is all the same whether you warn them or you warn them not: they do not believe.'),
(14, 2, 7, 1, 1, 1, 'الم', 'البقرۃ', 'خَتَمَ اللّٰہُ عَلٰی قُلُوۡبِہِمۡ وَ عَلٰی سَمۡعِہِمۡ ؕ  وَ عَلٰۤی اَبۡصَارِہِمۡ غِشَاوَۃٌ ۫ وَّ لَہُمۡ عَذَابٌ عَظِیۡمٌ ٪﴿۷﴾', 'اللہ نے ان کے دلوں اور کانوں پرمہر لگا رکھی ہے۔ اور ان کی آنکھوں پر پردہ پڑا ہوا ہےاور ان کے لئے بڑا عذاب تیار ہے۔', 'مہر کر دی اللہ نے ان کےدلوں پر اور انکے کانوں پر اور ان کی آنکھوں پر پردہ ہے [۱۱] اور ان کے لئے بڑا عذاب ہے', 'Allah has set a seal on their hearts and on their hearings, (i.e. they are closed from accepting Allahs Guidance), and on their eyes there is a covering. Theirs will be a great torment', 'Allah has set a seal on their hearts and on their hearing; and on their eyes there is a covering, and for them awaits a mighty punishment.'),
(15, 2, 8, 2, 2, 1, 'الم', 'البقرۃ', 'وَ مِنَ النَّاسِ مَنۡ یَّقُوۡلُ اٰمَنَّا بِاللّٰہِ وَ بِالۡیَوۡمِ الۡاٰخِرِ وَ مَا ہُمۡ بِمُؤۡمِنِیۡنَ ۘ﴿۸﴾', 'اور بعض لوگ ایسے ہیں جو کہتے ہیں کہ ہم اللہ پر اور روز آخر پر ایمان رکھتے ہیں حالانکہ وہ ایمان نہیں رکھتے۔', 'اور لوگوں میں کچھ ایسے بھی ہیں جو کہتے ہیں ہم ایمان لائے اللہ پر اور دن قیامت پر اور وہ ہر گز مومن نہیں [۱۲]', 'And of mankind, there are some (hypocrites) who say: \"We believe in Allah and the Last Day\" while in fact they believe not.', 'And among men there are some who say, “We believe in Allah and in the Last Day”, yet they are not believers.'),
(16, 2, 9, 2, 2, 1, 'الم', 'البقرۃ', 'یُخٰدِعُوۡنَ اللّٰہَ وَ الَّذِیۡنَ اٰمَنُوۡا ۚ وَ مَا یَخۡدَعُوۡنَ  اِلَّاۤ  اَنۡفُسَہُمۡ وَ مَا یَشۡعُرُوۡنَ ؕ﴿۹﴾', 'یہ اپنے خیال میں اللہ کو اور مومنوں کو دھوکہ دیتے ہیں مگر حقیقت میں اپنے سوا کسی کو دھوکہ نہیں دیتے اور اس سے بے خبر ہیں۔', 'دغابازی کرتے ہیں اللہ سے اور ایمان والوں سے اور دراصل کسی کو دغا نہیں دیتے مگر اپنے آپ کو اور نہیں سوچتے [۱۳]', 'They (think to) deceive Allah and those who believe, while they only deceive themselves, and perceive (it) not!', 'They try to deceive Allah and those who believe, while they are not deceiving anyone except themselves, although they are unaware of it.'),
(17, 2, 10, 2, 2, 1, 'الم', 'البقرۃ', 'فِیۡ قُلُوۡبِہِمۡ مَّرَضٌ ۙ فَزَادَہُمُ  اللّٰہُ  مَرَضًا ۚ  وَ لَہُمۡ عَذَابٌ اَلِیۡمٌۢ  ۬ۙ بِمَا کَانُوۡا یَکۡذِبُوۡنَ ﴿۱۰﴾', 'ان کے دلوں میں کفر کا مرض تھا اللہ نے ان کا مرض اور زیادہ کر دیا اور ان کے جھوٹ بو لنے کے سبب ان کو دکھ دینے والا عذاب ہوگا۔', 'ان کے دلوں میں بیماری ہے پھر بڑھا دی اللہ نے انکی بیماری [۱۴] اور ان کے لئے عذاب دردناک ہے اس بات پر کہ جھوٹ کہتےتھے[۱۵]', 'In their hearts is a disease (of doubt and hypocrisy) and Allah has increased their disease. A painful torment is theirs because they used to tell lies.', 'In their hearts there is a malady, so Allah has made them grow in their malady; and for them there is a grievous punishment, because they have been lying.'),
(18, 2, 11, 2, 2, 1, 'الم', 'البقرۃ', 'وَ اِذَا قِیۡلَ لَہُمۡ لَا تُفۡسِدُوۡا فِی الۡاَرۡضِ ۙ  قَالُوۡۤا اِنَّمَا نَحۡنُ مُصۡلِحُوۡنَ ﴿۱۱﴾', 'اور جب ان سے کہا جاتا ہے کہ زمین میں فساد نہ ڈالو تو کہتے ہیں ہم تو اصلاح کرنے والے ہیں۔', 'اور جب کہا جاتا ہے ان کو فساد نہ ڈالو ملک میں تو کہتے ہیں ہم تو اصلاح کرنے والے ہیں [۱۶]', 'And when it is said to them: \"Make not mischief on the earth,\" they say: \"We are only peacemakers.\"', 'When it is said to them, “Do not spread disorder on the earth”, they say, “We are but reformers.”'),
(19, 2, 12, 2, 2, 1, 'الم', 'البقرۃ', 'اَلَاۤ اِنَّہُمۡ ہُمُ الۡمُفۡسِدُوۡنَ وَ لٰکِنۡ لَّا یَشۡعُرُوۡنَ ﴿۱۲﴾', 'دیکھو یہ بلاشبہ مفسد ہیں لیکن خبر نہیں رکھتے۔', 'جان لو وہی ہیں خرابی کرنے والے لیکن نہیں سمجھتے [۱۷]', 'Verily! They are the ones who make mischief, but they perceive not.', 'Beware, it is, in fact, they who spread disorder, but they do not appreciate.'),
(20, 2, 13, 2, 2, 1, 'الم', 'البقرۃ', 'وَ  اِذَا قِیۡلَ لَہُمۡ اٰمِنُوۡا کَمَاۤ اٰمَنَ النَّاسُ قَالُوۡۤا اَنُؤۡمِنُ کَمَاۤ اٰمَنَ السُّفَہَآءُ ؕ اَلَاۤ اِنَّہُمۡ ہُمُ  السُّفَہَآءُ  وَ لٰکِنۡ لَّا  یَعۡلَمُوۡنَ ﴿۱۳﴾', 'اور جب ان سے کہا جاتا ہے کہ جس طرح اور لوگ ایمان لے آئے تم بھی ایمان لے آؤ تو کہتے ہیں بھلا جس طرح بیوقوف ایمان لے آئے ہیں اسی طرح ہم بھی ایمان لے آئیں؟ سن لو کہ یہی بیوقوف ہیں لیکن نہیں جانتے۔', 'اور جب کہا جاتا ہے ان کو ایمان لاؤ جس طرح ایمان لائے سب لوگ تو کہتے ہیں [۱۸]  کیا ہم ایمان لائیں جس طرح ایمان لائے بیوقوف [۱۹] جان لو وہی ہیں بیوقوف لیکن نہیں جانتے [۲۰]', 'And when it is said to them (hypocrites): \"Believe as the people (followers of Muhammad Peace be upon him , Al-Ansar and Al-Muhajiroon) have believed,\" they say: \"Shall we believe as the fools have believed?\" Verily, they are the fools, but they know not.', 'And when it is said to them, “Believe as people have believed,” they say, “Shall we believe as the fools have believed?” Beware, it is, in fact, they who are the fools, but they do not know.'),
(21, 2, 14, 2, 2, 1, 'الم', 'البقرۃ', 'وَ  اِذَا لَقُوا الَّذِیۡنَ اٰمَنُوۡا قَالُوۡۤا اٰمَنَّا ۚۖ وَ  اِذَا خَلَوۡا اِلٰی شَیٰطِیۡنِہِمۡ ۙ قَالُوۡۤا اِنَّا مَعَکُمۡ ۙ اِنَّمَا نَحۡنُ مُسۡتَہۡزِءُوۡنَ ﴿۱۴﴾', 'اور یہ لوگ جب مومنوں سے ملتے ہیں تو کہتے ہیں کہ ہم ایمان لے آئے ہیں اور جب اپنے شیطانوں میں جاتے ہیں تو ان سے کہتے ہیں کہ ہم تمہارے ساتھ ہیں اور مسلمانوں سے تو ہم ہنسی کیا کرتے ہیں۔', 'اور جب ملاقات کرتے ہیں مسلمانوں سے تو کہتے ہیں ہم ایمان لے آئے ہیں اور جب تنہا ہوتے ہیں اپنے شیطانوں کے پاس [۲۱] تو کہتےہیں کہ بیشک ہم تمہارے ساتھ ہیں [۲۲] ہم تو ہنسی کرتے ہیں [۲۳] (یعنی مسلمانوں سے )', 'And when they meet those who believe, they say: \"We believe,\" but when they are alone with their Shayatin (devils - polytheists, hypocrites, etc.), they say: \"Truly, we are with you; verily, we were but mocking.\"', 'When they meet those who believe, they say, “We have entered Faith;” but when they are alone with their satans, they say, “Indeed, we are with you; we were only mocking.”'),
(22, 2, 15, 2, 2, 1, 'الم', 'البقرۃ', 'اَللّٰہُ یَسۡتَہۡزِئُ بِہِمۡ وَ یَمُدُّہُمۡ  فِیۡ طُغۡیَانِہِمۡ یَعۡمَہُوۡنَ ﴿۱۵﴾', 'ان منافقوں سے اللہ ہنسی کرتا ہے اورانہیں مہلت دیئے جاتا ہے کہ شرارت و سرکشی میں پڑے بہک رہے ہیں۔', 'اللہ ہنسی کرتا ہے ان سے [۲۴] اور ترقی دیتا ہے انکو ان کی سرکشی میں(اور) حالت یہ ہے کہ وہ عقل کے اندھے ہیں [۲۵]', 'Allah mocks at them and gives them increase in their wrong-doings to wander blindly.', 'It is Allah who mocks at them, and lets them go on wandering blindly in their rebellion.'),
(23, 2, 16, 2, 2, 1, 'الم', 'البقرۃ', 'اُولٰٓئِکَ الَّذِیۡنَ اشۡتَرَوُا الضَّلٰلَۃَ بِالۡہُدٰی ۪  فَمَا رَبِحَتۡ تِّجَارَتُہُمۡ وَ مَا کَانُوۡا مُہۡتَدِیۡنَ ﴿۱۶﴾', 'یہ وہ لوگ ہیں جنہوں نے ہدایت چھوڑ کر گمراہی خریدی تو نہ تو انکی تجارت ہی نے کچھ نفع دیا اور نہ یہ ہدایت یاب ہی ہوئے۔', 'یہ وہی ہیں جنہوں نے مول لی گمراہی ہدایت کے بدلے سو نافع نہ ہوئی ان کی سوداگری [۲۶] اور نہ ہوئے راہ پانے والے [۲۷]', 'These are they who have purchased error for guidance, so their commerce was profitless. And they were not guided.', 'These are the people who have bought error at the price of guidance; so their trade has brought no gain, nor have they reached the right Path.'),
(24, 2, 17, 2, 2, 1, 'الم', 'البقرۃ', 'مَثَلُہُمۡ کَمَثَلِ الَّذِی اسۡتَوۡقَدَ نَارًا ۚ  فَلَمَّاۤ اَضَآءَتۡ مَا حَوۡلَہٗ ذَہَبَ اللّٰہُ بِنُوۡرِہِمۡ وَ تَرَکَہُمۡ فِیۡ ظُلُمٰتٍ لَّا یُبۡصِرُوۡنَ ﴿۱۷﴾', 'انکی مثال اس شخص کی سی ہے جس نے شب تاریک میں آگ جلائی۔ جب آگ نے اسکے اردگرد کی چیزیں روشن کیں تو اللہ نے ان لوگوں کی روشنی زائل کر دی اور انکو اندھیروں میں چھوڑ دیا کہ کچھ نہیں دیکھتے۔', 'ان کی مثال اس شخص کی سی ہے جس نے آگ جلائی پھر جب روشن کر دیا آگ نے اس کے آس پاس کو تو زائل کر دی اللہ نے ان کی روشنی اور چھوڑا ان کو اندھیروں میں کہ کچھ نہیں دیکھتے [۲۸]', 'Their likeness is as the likeness of one who kindled a fire; then, when it lighted all around him, Allah took away their light and left them in darkness. (So) they could not see.', 'Their situation is like that of a man who kindles a fire, and when it illuminates everything around him, Allah takes away their lights and leaves them in layers of darkness, so that they see nothing.'),
(25, 2, 18, 2, 2, 1, 'الم', 'البقرۃ', 'صُمٌّۢ  بُکۡمٌ عُمۡیٌ فَہُمۡ لَا یَرۡجِعُوۡنَ ﴿ۙ۱۸﴾', 'یہ بہرے ہیں گونگے ہیں اندھے ہیں کہ کسی طرح سیدھے رستے کی طرف لوٹ ہی نہیں سکتے۔', 'بہرے ہیں گونگے ہیں اندھے ہیں سو وہ نہیں لوٹیں گے [۲۹]', 'They are deaf, dumb, and blind, so they return not (to the Right Path).', 'Deaf, dumb and blind, they shall not return.'),
(26, 2, 19, 2, 2, 1, 'الم', 'البقرۃ', 'اَوۡ کَصَیِّبٍ مِّنَ السَّمَآءِ فِیۡہِ ظُلُمٰتٌ وَّ رَعۡدٌ وَّ بَرۡقٌ ۚ یَجۡعَلُوۡنَ اَصَابِعَہُمۡ فِیۡۤ  اٰذَانِہِمۡ مِّنَ الصَّوَاعِقِ حَذَرَ الۡمَوۡتِ ؕ وَ اللّٰہُ مُحِیۡطٌۢ بِالۡکٰفِرِیۡنَ ﴿۱۹﴾', 'یا انکی مثال مینہ کی سی ہے کہ آسمان سے برس رہا ہو اور اس میں اندھیرے پر اندھیرا چھا رہا ہو اور بادل گرج رہا ہو اور بجلی کوند رہی ہو تو یہ کڑک سے ڈر کر موت کے خوف سے کانوں میں انگلیاں دے لیں اور اللہ کافروں کو ہر طرف سے گھیرے ہوئے ہے۔', 'یا ان کی مثال ایسی ہے جیسے زور سے مینہ پڑ رہا ہو آسمان سے اس میں اندھیرے ہیں اور گرج اور بجلی  دیتے ہیں  انگلیاں  اپنے کانوں میں مارے کڑک کے موت کے ڈر سے اور اللہ احاطہ کرنے والا ہے کافروں کا [۳۰]', 'Or like a rainstorm from the sky, wherein is darkness, thunder, and lightning. They thrust their fingers in their ears to keep out the stunning thunderclap for fear of death. But Allah ever encompasses the disbelievers (i.e. Allah will gather them all together).', 'Or (it is) like a rainstorm from the sky, bringing darkness, thunder and lightning; they thrust their fingers in their ears against the thunderclaps for fear of death, -and Allah encompasses the disbelievers.'),
(27, 2, 20, 2, 2, 1, 'الم', 'البقرۃ', 'یَکَادُ الۡبَرۡقُ یَخۡطَفُ اَبۡصَارَہُمۡ ؕ کُلَّمَاۤ اَضَآءَ لَہُمۡ مَّشَوۡا فِیۡہِ ٭ۙ وَ اِذَاۤ اَظۡلَمَ عَلَیۡہِمۡ قَامُوۡا ؕ وَ لَوۡ شَآءَ اللّٰہُ  لَذَہَبَ بِسَمۡعِہِمۡ وَ اَبۡصَارِہِمۡ ؕ اِنَّ اللّٰہَ عَلٰی کُلِّ شَیۡءٍ قَدِیۡرٌ ﴿٪۲۰﴾', 'قریب ہے کہ بجلی کی چمک انکی آنکھوں کی بصارت کو اچک لے جائے جب بجلی چکمتی اور ان پر روشنی ڈالتی ہے تواس میں چل پڑتے ہیں اور جب اندھیرا ہو جاتا ہے تو کھڑے کے کھڑے رہ جاتے ہیں اور اگراللہ چاہتا تو ان کے کانوں کی شنوائی اور آنکھوں کی بینائی دونوں کو زائل کر دیتا۔ بلاشبہ اللہ ہر چیز پر قادر ہے۔', 'قریب ہے کہ بجلی اچک لے ان کی آنکھیں جب چمکتی ہے ان پر تو چلنے لگے ہیں اس کی روشنی میں اور جب اندھیرا ہوتا ہے تو کھڑے رہ جاتے ہیں اور اگر چاہے اللہ تو لیجائے ان کے کان  اور آنکھیں    بیشک اللہ   ہر چیز پر قادر ہے [۳۱]', 'The lightning almost snatches away their sight, whenever it flashes for them, they walk therein, and when darkness covers them, they stand still. And if Allah willed, He could have taken away their hearing and their sight. Certainly, Allah has power over all things.', 'and lightning (all but) snatches away their eyesight; every time a flash gives them light, they walk by it; and when darkness falls upon them, they stand still. And if Allah willed, He would certainly take away their hearing and their eyes: surely Allah is powerful to do anything.'),
(28, 2, 21, 3, 3, 1, 'الم', 'البقرۃ', 'یٰۤاَیُّہَا النَّاسُ اعۡبُدُوۡا رَبَّکُمُ الَّذِیۡ خَلَقَکُمۡ وَ الَّذِیۡنَ مِنۡ قَبۡلِکُمۡ لَعَلَّکُمۡ تَتَّقُوۡنَ ﴿ۙ۲۱﴾', 'لوگو! اپنے پروردگار کی عبادت کرو جس نے تم کو اور تم سے پہلے لوگوں کو پیدا کیا تا کہ تم اسکے عذاب سے بچو۔', 'اے   لوگو   بندگی کرو اپنے رب کی جس نے پیدا کیا تم کو   اور ان کو جو   تم سے پہلے تھے تاکہ تم پرہیز گار بن  جاؤ', 'O mankind! Worship your Lord (Allah), Who created you and those who were before you so that you may become Al-Muttaqoon (the pious - see V.2:2).', 'O people, worship your Lord who created you and those before you, so that you may become God-fearing.'),
(29, 2, 22, 3, 3, 1, 'الم', 'البقرۃ', 'الَّذِیۡ جَعَلَ لَکُمُ الۡاَرۡضَ فِرَاشًا وَّ السَّمَآءَ بِنَآءً ۪ وَّ اَنۡزَلَ مِنَ السَّمَآءِ مَآءً  فَاَخۡرَجَ بِہٖ مِنَ الثَّمَرٰتِ رِزۡقًا لَّکُمۡ ۚ فَلَا تَجۡعَلُوۡا لِلّٰہِ اَنۡدَادًا وَّ اَنۡتُمۡ تَعۡلَمُوۡنَ ﴿۲۲﴾', 'جس نے تمہارے لئے زمین کو بچھونا اور آسمان کو چھت بنایا اور آسمان سے مینہ برسا کر تمہارے کھانے کے لئے انواع و اقسام کے میوے پیدا کئے۔ پس کسی کو اللہ کا ہمسر نہ بناؤ۔ اور تم جانتے تو ہو۔', 'جس نے بنایا واسطے تمہارے زمین کو بچھونا اور آسمان کو چھت   اور اتار   آسمان سے پانی پھر نکالے اس سے   میوے   تمہارے کھانے کے واسطے سو نہ ٹھہراؤ کسی کو اللہ کے مقابل   اور تم تو جانتے ہو [۳۲]', 'Who has made the earth a resting place for you, and the sky as a canopy, and sent down water (rain) from the sky and brought forth therewith fruits as a provision for you. Then do not set up rivals unto Allah (in worship) while you know (that He Alone has the right to be worshipped).', 'He is the One who made the earth a bed for you, and the sky a roof, and sent down water from the sky, then brought forth with it fruits, as a provision for you. So, do not set up parallels to Allah when you know.'),
(30, 2, 23, 3, 3, 1, 'الم', 'البقرۃ', 'وَ اِنۡ کُنۡتُمۡ فِیۡ رَیۡبٍ مِّمَّا نَزَّلۡنَا عَلٰی عَبۡدِنَا فَاۡتُوۡا بِسُوۡرَۃٍ مِّنۡ مِّثۡلِہٖ ۪ وَ ادۡعُوۡا شُہَدَآءَکُمۡ مِّنۡ دُوۡنِ اللّٰہِ  اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ ﴿۲۳﴾', 'اور اگر تم کو اس کتاب میں جو ہم نے اپنے بندے پر نازل فرمائی ہے کچھ شک ہو تو اسی طرح کی ایک سورت تم بھی بنا لاؤ اور اللہ کے سوا جو تمہارے مددگار ہوں انکو بھی بلا لو اگر تم سچے ہو۔', 'اور اگر تم شک میں ہو اس کلام سےجو اتارا ہم نے اپنے بندہ پر تو لے آؤ ایک سورت اس جیسی [۳۳]   اور بلاؤ اس کو جو تمہارا مددگار ہو   اللہ کے سوا اگر    تم سچے ہو [۳۴]', 'And if you (Arab pagans, Jews, and Christians) are in doubt concerning that which We have sent down (i.e. the Quran) to Our slave (Muhammad Peace be upon him ), then produce a Soorah (chapter) of the like thereof and call your witnesses (supporters and helpers) besides Allah, if you are truthful.', 'If you are in doubt about what We have revealed to Our servant, then bring a Sūrah similar to this, and do call your supporters other than Allah, if you are true.'),
(31, 2, 24, 3, 3, 1, 'الم', 'البقرۃ', 'فَاِنۡ لَّمۡ تَفۡعَلُوۡا وَ لَنۡ تَفۡعَلُوۡا فَاتَّقُوا النَّارَ الَّتِیۡ وَقُوۡدُہَا النَّاسُ وَ الۡحِجَارَۃُ  ۚۖ اُعِدَّتۡ لِلۡکٰفِرِیۡنَ ﴿۲۴﴾', 'پھر اگر ایسا نہ کر سکو اور ہر گز نہیں کر سکو گے تو اس آگ سے ڈرو جس کا ایندھن آدمی اور پتھر ہونگے اور جو کافروں کے لئے تیار کی گئ ہے۔', 'پھر اگر ایسا نہ کرسکو  اور ہر گز نہ کر سکو گے تو پھر بچو  اس آگ سے جس کا ایندھن آدمی  اور پتھر ہیں   تیار کی ہوئی ہے کافروں کے واسطے [۳۵]', 'But if you do it not, and you can never do it, then fear the Fire (Hell) whose fuel is men and stones, prepared for the disbelievers.', 'But if you do not - and you will never be able to - then guard yourselves against the Fire, the fuel of which will be men and stones. It has been prepared for disbelievers.'),
(32, 2, 25, 3, 3, 1, 'الم', 'البقرۃ', 'وَ بَشِّرِ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ اَنَّ لَہُمۡ جَنّٰتٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ ؕ  کُلَّمَا رُزِقُوۡا مِنۡہَا مِنۡ ثَمَرَۃٍ رِّزۡقًا ۙ قَالُوۡا ہٰذَا الَّذِیۡ رُزِقۡنَا مِنۡ قَبۡلُ ۙ وَ اُتُوۡا بِہٖ مُتَشَابِہًا ؕ وَ لَہُمۡ فِیۡہَاۤ اَزۡوَاجٌ مُّطَہَّرَۃٌ ٭ۙ وَّ ہُمۡ فِیۡہَا خٰلِدُوۡنَ ﴿۲۵﴾', 'اور جو لوگ ایمان لائے اور نیک عمل کرتے رہے ان کو خوشخبری سنادو کہ انکے لئے نعمت کے باغ ہیں جنکے نیچے نہریں بہ رہی ہیں جب انہیں ان میں سےکسی قسم کا میوہ کھانے کو دیا جائے گا تو کہیں گے یہ تو وہی ہے جو ہم کو پہلے دیا گیا تھا۔ اور انکو ایک دوسرے کے ہمشکل میوے دیئے جائینگے اور وہاں انکے لئے پاک بیویاں ہونگی اور وہ بہشتوں میں ہمیشہ رہینگے۔', 'اور خوشخبری دے ان لوگوں کو جو ایمان لائے اور اچھے کام کئے  کہ ان کے واسطے باغ ہیں کہ بہتی ہیں ان کے نیچے نہریں جب ملے گا ان کو وہاں کا کوئی پھل کھانے کو تو کہیں گے یہ تو وہی ہے جو ملا تھا ہم کو اس سے پہلے اور دیئے جائیں گے ان کو پھل ایک صورت کے [۳۶] اور انکے لئے وہاں عورتیں ہوں گی پاکیزہ اور وہ وہیں ہمیشہ رہیں گے[۳۷]', 'And give glad tidings to those who believe and do righteous good deeds, that for them will be Gardens under which rivers flow (Paradise). Every time they will be provided with a fruit therefrom, they will say: \"This is what we were provided with before,\" and they will be given things in resemblance (i.e. in the same form but different in taste) and they shall have therein Azwajun Mutahharatun (purified mates or wives), (having no menses, stools, urine, etc.) and they will abide therein forever.', 'And give good news to those who believe and do righteous deeds that for them there are gardens beneath which rivers flow. Every time they are given a fruit from there to eat, they will say, “This is what we have been given before”; and they will be given (fruits) resembling one another. And for them there shall be wives purified; and there they will live forever.'),
(33, 2, 26, 3, 3, 1, 'الم', 'البقرۃ', 'اِنَّ اللّٰہَ لَا یَسۡتَحۡیٖۤ اَنۡ یَّضۡرِبَ مَثَلًا مَّا بَعُوۡضَۃً فَمَا فَوۡقَہَا ؕ فَاَمَّا الَّذِیۡنَ اٰمَنُوۡا فَیَعۡلَمُوۡنَ اَنَّہُ الۡحَقُّ مِنۡ رَّبِّہِمۡ ۚ وَ اَمَّا الَّذِیۡنَ کَفَرُوۡا فَیَقُوۡلُوۡنَ مَا ذَاۤ  اَرَادَ  اللّٰہُ بِہٰذَا مَثَلًا ۘ یُضِلُّ بِہٖ کَثِیۡرًا ۙ وَّ یَہۡدِیۡ بِہٖ کَثِیۡرًا ؕ وَ مَا یُضِلُّ بِہٖۤ  اِلَّا الۡفٰسِقِیۡنَ ﴿ۙ۲۶﴾', 'اللہ اس بات سے عار نہیں کرتا کہ مچھر یا اس سے بڑھکر کسی چیز مثلاً مکھی مکڑی وغیرہ کی مثال بیان فرمائے۔  اب جو مومن ہیں وہ یقین کرتے ہیں کہ وہ انکے پروردگار کی طرف سے سچ ہے اور جو کافر ہیں وہ کہتے ہیں کہ اس مثال سے اللہ کی مراد ہی کیا ہے اس سے اللہ بہتوں کو گمراہ کرتا ہے اور بہتوں کو ہدایت بخشتا ہے اور گمراہ بھی کرتا ہے تو نافرمانوں ہی کو۔', 'بیشک اللہ شرماتا نہیں اس بات سے کہ بیان کرے کوئی مثال مچھر کی یا اس چیز کی جو اس سے بڑھکر ہے [۳۸] سو جو لوگ مومن ہیں وہ یقینًا جانتےہیں کہ یہ مثال ٹھیک ہے جو نازل ہوئی انکے رب کی طرف سے اور جو کافر ہیں سو کہتے ہیں کیا مطلب تھا اللہ کا اس مثال سے گمراہ کرتا ہے خدائے تعالیٰ اس مثال سے بہتیروں کو اور ہدایت کرتا ہے اس سے بہتیروں کو [۳۹] اور گمراہ نہیں کرتا اس مثل سے مگر بدکاروں کو', 'Verily, Allah is not ashamed to set forth a parable even of a mosquito or so much more when it is bigger (or less when it is smaller) than it. And as for those who believe, they know that it is the Truth from their Lord, but as for those who disbelieve, they say: \"What did Allah intend by this parable?\" By it He misleads many, and many He guides thereby. And He misleads thereby only those who are Al-Fasiqoon (the rebellious, disobedient to Allah).', 'Indeed, Allah does not feel shy in citing any parable, be it that of a gnat or of something above it (in meanness). Now, as for those who believe, they know it is the truth from their Lord; while those who disbelieve say, “What could Allah have meant by this parable?” By this He lets many go astray, and by this He makes many find guidance. But He does not let anyone go astray thereby except those who are sinful'),
(34, 2, 27, 3, 3, 1, 'الم', 'البقرۃ', 'الَّذِیۡنَ یَنۡقُضُوۡنَ عَہۡدَ  اللّٰہِ مِنۡۢ بَعۡدِ مِیۡثَاقِہٖ ۪ وَ یَقۡطَعُوۡنَ مَاۤ اَمَرَ اللّٰہُ بِہٖۤ  اَنۡ یُّوۡصَلَ وَ یُفۡسِدُوۡنَ فِی الۡاَرۡضِ ؕ اُولٰٓئِکَ ہُمُ الۡخٰسِرُوۡنَ ﴿۲۷﴾', 'جو اللہ کے اقرار کو مضبوط کرنے کے بعد توڑ دیتے ہیں اور جس چیز یعنی رشتہ قرابت کے جوڑے رکھنے کا اللہ نے حکم دیا ہے اسکو قطع کئے ڈالتے ہیں اور زمین میں خرابی کرتے ہیں یہی لوگ نقصان اٹھانے والے ہیں۔', 'جو توڑتے ہیں خدا کے معاہدہ کو مضبوط کرنے کے بعد اور قطع کرتے ہیں اس چیز کو جس کو اللہ نے فرمایا ملانے کو [۴۰] اور فساد کرتے ہیں ملک میں [۴۱] وہی ہیں ٹوٹے والے [۴۲]', 'Those who break Allahs Covenant after ratifying it, and sever what Allah has ordered to be joined (as regards Allahs Religion of Islamic Monotheism, and to practise its legal laws on the earth and also as regards keeping good relations with kith and kin ), and do mischief on earth, it is they who are the losers.', '- those who break the Covenant of Allah after it has been made binding, and cut off the relations Allah has commanded to be joined, and spread disorder on the earth - it is these who are the losers.'),
(35, 2, 28, 3, 3, 1, 'الم', 'البقرۃ', 'کَیۡفَ تَکۡفُرُوۡنَ بِاللّٰہِ وَ کُنۡتُمۡ اَمۡوَاتًا فَاَحۡیَاکُمۡ ۚ ثُمَّ یُمِیۡتُکُمۡ ثُمَّ یُحۡیِیۡکُمۡ ثُمَّ  اِلَیۡہِ تُرۡجَعُوۡنَ ﴿۲۸﴾', 'کافرو تم اللہ سے کیونکر منکر ہو سکتے ہو جس حال میں کہ تم بے جان تھے تو اس نے تم کو جان بخشی پھر وہی تم کو مارتا ہے پھر وہی تم کو زندہ کرے گا پھر تم اسی کی طرف لوٹائے جاؤ گے۔', 'کس طرح کافر ہوتے ہو خدا تعالیٰ سے حالانکہ تم بیجان تھے [۴۳] پھر جلایا تم کو [۴۴] پھر مارے گا تم کو [۴۵] پھر جلائے گا تم کو [۴۶] پھر اسی کی طرف لوٹائے جاؤ گے [۴۷]', 'How can you disbelieve in Allah? Seeing that you were dead and He gave you life. Then He will give you death, then again will bring you to life (on the Day of Resurrection) and then unto Him you will return.', '“How is it that you deny Allah, while you were lifeless and He gave you life; then He will make you die, and then He will make you live again, and then to Him you will be returned?'),
(36, 2, 29, 3, 3, 1, 'الم', 'البقرۃ', 'ہُوَ الَّذِیۡ خَلَقَ لَکُمۡ مَّا فِی الۡاَرۡضِ جَمِیۡعًا ٭ ثُمَّ اسۡتَوٰۤی اِلَی السَّمَآءِ فَسَوّٰىہُنَّ سَبۡعَ سَمٰوٰتٍ ؕ وَ ہُوَ بِکُلِّ شَیۡءٍ عَلِیۡمٌ ﴿٪۲۹﴾', 'وہی تو ہے جس نے سب چیزیں جو زمین میں ہیں تمہارے لئے پیدا کیں پھر آسمانوں کی طرف متوجہ ہوا۔ تو انکو ٹھیک ٹھیک سات آسمان بنا دیا اور وہ ہر چیز سے خبردار ہے۔', 'وہی ہے جس نے پیدا کیا تمہارے واسطے جو کچھ زمین میں ہے سب پھر قصد کیا آسمان کی طرف سو ٹھیک کر دیا انکو سات آسمان اور خدا تعالیٰ ہر چیز سے خبردار ہے [۴۸]', 'He it is Who created for you all that is on earth. Then He Istawa (rose over) towards the heaven and made them seven heavens and He is the All-Knower of everything.', 'It is He who created for you all that the earth contains; then He turned to the heavens and made them seven skies - and He is the knower of all things.'),
(37, 2, 30, 4, 4, 1, 'الم', 'البقرۃ', 'وَ  اِذۡ قَالَ رَبُّکَ لِلۡمَلٰٓئِکَۃِ اِنِّیۡ جَاعِلٌ فِی الۡاَرۡضِ خَلِیۡفَۃً ؕ قَالُوۡۤا اَتَجۡعَلُ فِیۡہَا مَنۡ یُّفۡسِدُ فِیۡہَا وَ یَسۡفِکُ الدِّمَآءَ ۚ وَ نَحۡنُ نُسَبِّحُ بِحَمۡدِکَ وَ نُقَدِّسُ لَکَ ؕ قَالَ اِنِّیۡۤ اَعۡلَمُ مَا لَا تَعۡلَمُوۡنَ ﴿۳۰﴾', 'اور وہ وقت یاد کرنے کے قابل ہے جب تمہارے پروردگار نے فرشتوں سے فرمایا کہ میں زمین میں اپنا نائب بنانیوالا ہوں انہوں نے کہا کیا تو اس میں ایسے شخص کو نائب بنانا چاہتا ہے جو خرابیاں کرے اور کشت و خون کرتا پھرے اور ہم تیری تعریف کے ساتھ تسبیح و تقدیس کرتے رہتے ہیں اللہ نے فرمایا میں وہ باتیں جانتا ہوں جو تم نہیں جانتے۔', 'اور جب کہا تیرے رب نے فرشتوں کو کہ میں بنانیوالا ہوں زمین میں ایک نائب [۴۹]کہا فرشتوں نے کیا قائم کرتا ہے تو زمین میں اسکو جو فساد کرے اس میں اور خون بہائے اور ہم پڑھتے رہتے ہیں تیری خوبیاں اور یاد کرتے ہیں تیری پاک ذات کو [۵۰] فرمایا بیشک مجھ کو معلوم ہے جو تم نہیں جانتے [۵۱]', 'And (remember) when your Lord said to the angels: \"Verily, I am going to place (mankind) generations after generations on earth.\" They said: \"Will You place therein those who will make mischief therein and shed blood, - while we glorify You with praises and thanks (Exalted be You above all that they associate with You as partners) and sanctify You.\" He (Allah) said: \"I know that which you do not know.\"', '(Remember) when your Lord said to the angels, “I am going to create a deputy on the earth!” They said, “Will You create there one who will spread disorder on the earth and cause bloodshed, while we proclaim Your purity, along with your praise, and sanctify Your name?” He said, “Certainly, I know what you know not.”'),
(38, 2, 31, 4, 4, 1, 'الم', 'البقرۃ', 'وَ عَلَّمَ اٰدَمَ الۡاَسۡمَآءَ کُلَّہَا ثُمَّ عَرَضَہُمۡ عَلَی الۡمَلٰٓئِکَۃِ ۙ فَقَالَ اَنۡۢبِـُٔوۡنِیۡ بِاَسۡمَآءِ ہٰۤؤُلَآءِ اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ ﴿۳۱﴾', 'اور اس نے آدم کو سب چیزوں کے نام سکھائے پھر ان کو فرشتوں کے سامنے کیا اور فرمایا کہ اگر سچے ہو تو مجھے ان کے نام بتاؤ۔', 'اور سکھلا دیے اللہ نے آدم کو نام سب چیزوں کے پھر سامنے کیا ان سب چیزوں کو فرشتوں کے پھر فرمایا بتاؤ مجھ کو نام ان کے اگر تم سچے ہو', 'And He taught Adam all the names (of everything) , then He showed them to the angels and said, \"Tell Me the names of these if you are truthful.\"', 'And He taught ’Ādam the names, all of them; then presented them before the angels, and said, “Tell me their names, if you are right.”'),
(39, 2, 32, 4, 4, 1, 'الم', 'البقرۃ', 'قَالُوۡا سُبۡحٰنَکَ لَا عِلۡمَ لَنَاۤ اِلَّا مَا عَلَّمۡتَنَا ؕ اِنَّکَ اَنۡتَ الۡعَلِیۡمُ الۡحَکِیۡمُ ﴿۳۲﴾', 'انہوں نے کہا تو پاک ہے جتناعلم تو نے ہمیں بخشا ہے اسکے سوا ہمیں کچھ معلوم نہیں بیشک تو دانا ہے حکمت والا ہے۔', 'بولے پاک ہے تو ہم کو معلوم نہیں مگر جتنا تو نے ہم کو سکھایا بیشک تو ہی ہے اصل جاننے والا حکمت والا [۵۲]', 'They (angels) said: \"Glory be to You, we have no knowledge except what you have taught us. Verily, it is You, the All-Knower, the All-Wise.\"', 'They said, “To You belongs all purity! We have no knowledge except what You have given us. Surely, You alone are the All-knowing, All-wise.”'),
(40, 2, 33, 4, 4, 1, 'الم', 'البقرۃ', 'قَالَ یٰۤاٰدَمُ اَنۡۢبِئۡہُمۡ بِاَسۡمَآئِہِمۡ ۚ فَلَمَّاۤ اَنۡۢبَاَہُمۡ بِاَسۡمَآئِہِمۡ ۙ قَالَ اَلَمۡ اَقُلۡ لَّکُمۡ اِنِّیۡۤ  اَعۡلَمُ غَیۡبَ السَّمٰوٰتِ وَ الۡاَرۡضِ ۙ وَ اَعۡلَمُ مَا تُبۡدُوۡنَ وَ مَا کُنۡتُمۡ تَکۡتُمُوۡنَ ﴿۳۳﴾', 'تب اللہ نے آدم کو حکم دیا کہ آدم! تم ان کو ان چیزوں کے نام بتاؤ سو جب انہوں نے ان کو ان کے نام بتائے تو فرشتوں سے فرمایا کیا میں نے تم سے نہیں کہا تھا کہ میں آسمانوں اور زمین کی سب پوشیدہ باتیں جانتا ہوں اور جو تم ظاہر کرتے ہو اور جو پوشیدہ کرتے ہو سب مجھ کو معلوم ہے۔', 'فرمایا اے آدم بتا دے فرشتوں کو ان چیزوں کے نام پھر جب بتا دیے اس نے ان کے نام فرمایا کیا نہ کہا تھا میں نے تم کو کہ میں خوب جانتا ہوں چھپی ہوئی چیزیں آسمانوں کی اور زمین کی اور جانتا ہوں جو تم ظاہر کرتے ہو اور جو چھپاتے ہو [۵۳]', 'He said: \"O Adam! Inform them of their names,\" and when he had informed them of their names, He said: \"Did I not tell you that I know the Ghaib (unseen) in the heavens and the earth, and I know what you reveal and what you have been concealing?\"', 'He said, “O ’Ādam, tell them the names of all these.” When he told them their names, Allah said, “Did I not tell you that I know the secrets of the skies and of the earth, and that I know what you disclose and what you conceal.'),
(41, 2, 34, 4, 4, 1, 'الم', 'البقرۃ', 'وَ اِذۡ قُلۡنَا لِلۡمَلٰٓئِکَۃِ اسۡجُدُوۡا لِاٰدَمَ فَسَجَدُوۡۤا  اِلَّاۤ  اِبۡلِیۡسَ ؕ اَبٰی وَ اسۡتَکۡبَرَ ٭۫ وَ  کَانَ مِنَ الۡکٰفِرِیۡنَ ﴿۳۴﴾', 'اور جب ہم نے فرشتوں کو حکم دیا کہ آدم کے آگے سجدہ کرو تو وہ سب سجدے میں گر پڑے مگر شیطان نے انکار کیا اور غرور میں آکر کافر بن گیا۔', 'اور جب ہم نے حکم دیا فرشتوں کو کہ سجدہ کرو آدم کو تو سب سجدہ میں گر پڑے مگر شیطان [۵۴] اس نے نہ مانا اور تکبر کیا اور تھا وہ کافروں میں کا [۵۵]', 'And (remember) when We said to the angels: \"Prostrate yourselves before Adam.\". And they prostrated except Iblees (Satan), he refused and was proud and was one of the disbelievers (disobedient to Allah).', 'And when We said to the angels: “Prostrate yourselves before ’Ādam!” So, they prostrated themselves, all but Iblīs (Satan). He refused, and became one of the infidels.'),
(42, 2, 35, 4, 4, 1, 'الم', 'البقرۃ', 'وَ قُلۡنَا یٰۤاٰدَمُ اسۡکُنۡ اَنۡتَ وَ زَوۡجُکَ الۡجَنَّۃَ وَ کُلَا مِنۡہَا رَغَدًا حَیۡثُ شِئۡتُمَا ۪ وَ لَا تَقۡرَبَا ہٰذِہِ الشَّجَرَۃَ فَتَکُوۡنَا مِنَ الظّٰلِمِیۡنَ ﴿۳۵﴾', 'اور ہم نے کہا کہ اے آدم تم اور تمہاری بیوی بہشت میں رہو اور جہاں سے چاہو بے روک ٹوک کھاؤ پیو لیکن اس درخت کے پاس نہ جانا نہیں تو ظالموں میں ہو جاؤ گے۔', 'اور ہم نے کہا اے آدم رہا کر تو اور تیری عورت جنت میں اور کھاؤ اس میں جو چاہو جہاں کہیں سے چاہو اور پاس مت جانا اس درخت کے پھر تم ہو جاؤ گے ظالم [۵۶]', 'And We said: \"O Adam! Dwell you and your wife in the Paradise and eat both of you freely with pleasure and delight of things therein as wherever you will, but come not near this tree or you both will be of the Zalimoon (wrong-doers).\"', 'And We said, “O ’Ādam, dwell, you and your wife, in Paradise; and eat at pleasure wherever you like, but do not go near this tree, otherwise you will be (counted) among the transgressors.”'),
(43, 2, 36, 4, 4, 1, 'الم', 'البقرۃ', 'فَاَزَلَّہُمَا الشَّیۡطٰنُ عَنۡہَا فَاَخۡرَجَہُمَا مِمَّا کَانَا فِیۡہِ ۪ وَ قُلۡنَا اہۡبِطُوۡا بَعۡضُکُمۡ لِبَعۡضٍ عَدُوٌّ ۚ وَ لَکُمۡ فِی الۡاَرۡضِ مُسۡتَقَرٌّ  وَّ مَتَاعٌ اِلٰی  حِیۡنٍ ﴿۳۶﴾', 'پھر شیطان نے دونوں کو  اس طرف کے بارے میں پھسلا دیا اور جس عیش و نشاط میں تھے اس سے انکو نکلوا دیا۔ تب ہم نے حکم دیا کہ بہشت بریں سے چلے جاؤ تم ایک دوسرے کے دشمن ہو اور تمہارے لئے زمین میں ایک وقت تک ٹھکانہ اور معاش مقرر کر دیا گیا ہے۔', 'پھر ہلا دیا انکو شیطان نے اس جگہ سے پھر نکالا انکو اس عزت و راحت سے کہ جس میں تھے [۵۷] اور ہم نے کہاتم سب اترو تم ایک دوسرے کے دشمن ہو گے [۵۸] اور تمہارے واسطے زمین میں ٹھکانا ہے اور نفع اٹھانا ہے ایک وقت تک [۵۹]', 'Then the Shaitan (Satan) made them slip therefrom (the Paradise), and got them out from that in which they were. We said: \"Get you down, all, with enmity between yourselves. On earth will be a dwelling place for you and an enjoyment for a time.\"', 'Then, Satan caused them to slip from it, and brought them out of where they had been. And We said, “Go down, all of you, some of you the enemies of others; and on the earth there will be for you a dwelling place and enjoyment for a time.”'),
(44, 2, 37, 4, 4, 1, 'الم', 'البقرۃ', 'فَتَلَقّٰۤی اٰدَمُ مِنۡ رَّبِّہٖ کَلِمٰتٍ فَتَابَ عَلَیۡہِ ؕ اِنَّہٗ ہُوَ  التَّوَّابُ الرَّحِیۡمُ ﴿۳۷﴾', 'پھر آدم نے اپنے پروردگار سے کچھ کلمات سیکھے اور معافی مانگی تو اسنے انکا قصور معاف کر دیا بیشک وہ معاف کرنے والا ہے بڑا مہربان ہے۔', 'پھر سیکھ لیں آدم نے اپنے رب سے چند باتیں پھر متوجہ ہو گیا اللہ اس پر بیشک وہی ہے توبہ قبول کرنے والا مہربان [۶۰]', 'Then Adam received from his Lord Words . And his Lord pardoned him (accepted his repentance). Verily, He is the One Who forgives (accepts repentance), the Most Merciful.', 'Then ’Ādam learned certain words (to pray with) from his Lord; so, Allah accepted his repentance. No doubt, He is the Most-Relenting, the Very-Merciful.'),
(45, 2, 38, 4, 4, 1, 'الم', 'البقرۃ', 'قُلۡنَا اہۡبِطُوۡا مِنۡہَا جَمِیۡعًا ۚ فَاِمَّا یَاۡتِیَنَّکُمۡ مِّنِّیۡ ہُدًی فَمَنۡ تَبِعَ ہُدَایَ فَلَا خَوۡفٌ عَلَیۡہِمۡ  وَ لَا ہُمۡ یَحۡزَنُوۡنَ ﴿۳۸﴾', 'ہم نے فرمایا کہ تم سب یہاں سے اتر جاؤ جب تمہارے پاس میری طرف سے ہدایت پہنچے تو اسکی پیروی کرنا کہ جنہوں نے میری ہدایت کی پیروی کی انکو نہ کچھ خوف ہو گا اور نہ وہ غمناک ہوں گے۔', 'ہم نے حکم دیا نیچے جاؤ یہاں سے تم سب [۶۱] پھر اگر تم کو پہنچے میری طرف سے کوئی ہدایت تو جو چلا میری ہدایت پر نہ خوف ہو گا ان پر اور نہ وہ غمگین ہوں گے [۶۲]', 'We said: \"Get down all of you from this place (the Paradise), then whenever there comes to you Guidance from Me, and whoever follows My Guidance, there shall be no fear on them, nor shall they grieve.', 'We said, “Go down from here, all of you. Then, should some guidance come to you from Me, those who follow My guidance shall have no fear, nor shall they grieve.'),
(46, 2, 39, 4, 4, 1, 'الم', 'البقرۃ', 'وَ الَّذِیۡنَ  کَفَرُوۡا وَ کَذَّبُوۡا بِاٰیٰتِنَاۤ اُولٰٓئِکَ اَصۡحٰبُ النَّارِ ۚ ہُمۡ فِیۡہَا خٰلِدُوۡنَ ﴿٪۳۹﴾', 'اور جنہوں نے اسکو قبول نہ کیا اور ہماری آیتوں کو جھٹلایا وہ دوزخ میں جانیوالے ہیں اور وہ ہمیشہ اس میں رہیں گے۔', 'اور جو لوگ منکر ہوئے اور جھٹلایا ہماری نشانیوں کو  وہ ہیں دوزخ میں جانے والے وہ اس میں ہمیشہ رہیں گے', 'But those who disbelieve and belie Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) such are the dwellers of the Fire, they shall abide therein forever.', 'As for those who disbelieve, and deny Our signs, they are the people of the Fire. They shall dwell in it forever.”'),
(47, 2, 40, 5, 5, 1, 'الم', 'البقرۃ', 'یٰبَنِیۡۤ  اِسۡرَآءِیۡلَ اذۡکُرُوۡا نِعۡمَتِیَ الَّتِیۡۤ اَنۡعَمۡتُ عَلَیۡکُمۡ وَ اَوۡفُوۡا بِعَہۡدِیۡۤ اُوۡفِ بِعَہۡدِکُمۡ ۚ وَ اِیَّایَ فَارۡہَبُوۡنِ ﴿۴۰﴾', 'اے آل یعقوب! میرے وہ احسان یاد کرو جو میں نے تم پر کئے تھے اور اس اقرار کو پورا کرو جو تم نے مجھ سے کیا تھا میں اس اقرار کو پورا کروں گا جو میں نے تم سے کیا تھا اور مجھی سے ڈرتے رہو۔', 'اے بنی اسرائیل [۶۳] یاد کرو میرے وہ احسان جو میں نے تم پر کئے [۶۴] اور تم پورا کرو میرا اقرار تو میں پورا کروں تمہارا اقرار [۶۵] اور مجھ ہی سے ڈرو [۶۶]', 'O Children of Israel! Remember My Favour which I bestowed upon you, and fulfill (your obligations to) My Covenant (with you) so that I fulfill (My Obligations to) your covenant (with Me), and fear none but Me.', 'O Children of Isrā’īl (the Israelites), remember My blessing that I conferred upon you, and fulfill the covenant with Me, and I shall fulfill your covenant, and have awe of Me alone.'),
(48, 2, 41, 5, 5, 1, 'الم', 'البقرۃ', 'وَ اٰمِنُوۡا بِمَاۤ اَنۡزَلۡتُ مُصَدِّقًا لِّمَا مَعَکُمۡ وَ لَا تَکُوۡنُوۡۤا اَوَّلَ کَافِرٍۭ بِہٖ ۪ وَ لَا تَشۡتَرُوۡا بِاٰیٰتِیۡ ثَمَنًا قَلِیۡلًا ۫ وَّ اِیَّایَ فَاتَّقُوۡنِ ﴿۴۱﴾', 'اور جو کتاب میں نے اپنے رسول محمد ﷺ پر نازل کی ہے جو تمہاری کتاب یعنی تورات کو سچّا کہتی ہے اس پر ایمان لاؤ اور اس سے منکر اوّل نہ بنو اور میری آیتوں میں تحریف کر کے انکے بدلے تھوڑی سی قیمت یعنی دنیاوی منفعت نہ حاصل کرو اور مجھی سے خوف رکھو۔', 'اور مان لو اس کتاب کو جو میں نے اتاری ہے سچ بتانے والی ہے اس کتاب کو جو تمہارے پاس ہے [۶۷] اور مت ہو سب میں اول منکر اس کے [۶۸] اور نہ لو میری آیتوں پر مول تھوڑا اور مجھ ہی سے بچتے رہو۔', 'And believe in what I have sent down (this Quran), confirming that which is with you, (the Taurat (Torah) and the Injeel (Gospel)), and be not the first to disbelieve therein, and buy (get (ÊÇeeÐ ÇÌÑÇ)) not with My Verses (the Taurat (Torah) and the Injeel (Gospel)) a small price (i.e. getting a small gain by selling My Verses), and fear Me and Me Alone. (Tafsir At-Tabaree, Vol. I, Page 253).', 'And have faith in what I have revealed, confirming what is already with you, and do not be the first to deny it, nor take a paltry price for My verses. Fear Me alone.'),
(49, 2, 42, 5, 5, 1, 'الم', 'البقرۃ', 'وَ لَا تَلۡبِسُوا الۡحَقَّ بِالۡبَاطِلِ وَ تَکۡتُمُوا الۡحَقَّ وَ اَنۡتُمۡ تَعۡلَمُوۡنَ ﴿۴۲﴾', 'اور حق کو باطل کے ساتھ نہ ملاؤ اور سچّی بات کو جان بوجھ کر نہ چھپاؤ۔', 'اور مت لاؤ صحیح میں غلط اور مت چھپاؤ سچ کو جان بوجھ کر', 'And mix not truth with falsehood, nor conceal the truth (i.e. Muhammad Peace be upon him is Allahs Messenger and his qualities are written in your Scriptures, the Taurat (Torah) and the Injeel (Gospel)) while you know (the truth) .', 'and do not confound truth with falsehood, and do not hide the truth when you know (it).'),
(50, 2, 43, 5, 5, 1, 'الم', 'البقرۃ', 'وَ اَقِیۡمُوا الصَّلٰوۃَ وَ اٰتُوا الزَّکٰوۃَ وَ ارۡکَعُوۡا مَعَ الرّٰکِعِیۡنَ ﴿۴۳﴾', 'اورنماز پڑھا کرو اور زکوٰۃ دیا کرو اور اللہ کے آگے جھکنے والوں کے ساتھ جھکا کرو۔', 'اور قائم کرو نماز اور دیا کرو زکوٰۃ اور جھکو نماز میں جھکنے والوں کے ساتھ [۶۹]', 'And perform As-Salat (Iqamat-as-Salat), and give Zakat, and Irka (i.e. bow down or submit yourselves with obedience to Allah) along with ArRakioon.', 'And be steadfast in Salāh (prayer), and pay Zakāh, and bow down with those who bow down.'),
(51, 2, 44, 5, 5, 1, 'الم', 'البقرۃ', 'اَتَاۡمُرُوۡنَ النَّاسَ بِالۡبِرِّ وَ تَنۡسَوۡنَ اَنۡفُسَکُمۡ وَ اَنۡتُمۡ تَتۡلُوۡنَ الۡکِتٰبَ ؕ اَفَلَا تَعۡقِلُوۡنَ ﴿۴۴﴾', 'یہ کیا عقل کی بات ہے کہ تم لوگوں کو نیکی کرنے کو کہتے ہو اور اپنے تئیں فراموش کئے دیتے ہو حالانکہ تم اللہ کی کتاب بھی پڑھتے ہو کیا تم سمجھتے نہیں؟', 'کیا حکم کرتے ہو لوگوں کو نیک کام کا اور بھولتے ہو اپنے آپ کو اور تم تو پڑھتے ہو کتاب پھر کیوں نہیں سوچتے ہو [۷۰]', 'Enjoin you Al-Birr (piety and righteousness and each and every act of obedience to Allah) on the people and you forget (to practise it) yourselves, while you recite the Scripture (the Taurat (Torah))! Have you then no sense?', 'Do you enjoin righteousness upon others while you ignore your own selves, although you keep reciting the Book? Have you then no sense?'),
(52, 2, 45, 5, 5, 1, 'الم', 'البقرۃ', 'وَ اسۡتَعِیۡنُوۡا بِالصَّبۡرِ وَ الصَّلٰوۃِ ؕ وَ اِنَّہَا لَکَبِیۡرَۃٌ اِلَّا عَلَی الۡخٰشِعِیۡنَ ﴿ۙ۴۵﴾', 'اور رنج و تکلیف میں صبر اور نماز سے مدد لیا کرو اور بیشک نماز گراں ہے مگر ان لوگوں پر گراں نہیں جو عجز کرنے والے ہیں۔', 'اور مدد چاہو صبر سے اور نماز سے [۷۱] اور البتہ وہ بھاری ہے مگر انہی عاجزوں پر', 'And seek help in patience and As-Salat (the prayer) and truly it is extremely heavy and hard except for Al-Khashioon (i.e. the true believers in Allah - those who obey Allah with full submission, fear much from His Punishment, and believe in His Promise (Paradise, etc.) and in His Warnings (Hell, etc.)).', 'Seek help through patience and prayer. It is indeed exacting, but not for those who are humble in their hearts,'),
(53, 2, 46, 5, 5, 1, 'الم', 'البقرۃ', 'الَّذِیۡنَ یَظُنُّوۡنَ اَنَّہُمۡ مُّلٰقُوۡا رَبِّہِمۡ وَ اَنَّہُمۡ  اِلَیۡہِ رٰجِعُوۡنَ ﴿٪۴۶﴾', 'جو یقین کئے ہوئے ہیں کہ وہ اپنے پروردگار سے ملنے والے ہیں اور اسکی طرف لوٹ کر جانیوالے ہیں۔', 'جن کو خیال ہے کہ وہ روبرو ہونے والے ہیں اپنے رب کے اور یہ کہ انکو اسی کی طرف لوٹ کر جانا ہے [۷۲]', '(They are those) who are certain that they are going to meet their Lord, and that unto Him they are going to return.', 'who bear in mind that they are to meet their Lord, and that to Him they are to return.'),
(54, 2, 47, 6, 6, 1, 'الم', 'البقرۃ', 'یٰبَنِیۡۤ  اِسۡرَآءِیۡلَ اذۡکُرُوۡا نِعۡمَتِیَ الَّتِیۡۤ اَنۡعَمۡتُ عَلَیۡکُمۡ وَ اَنِّیۡ فَضَّلۡتُکُمۡ عَلَی الۡعٰلَمِیۡنَ ﴿۴۷﴾', 'اے یعقوب کی اولاد! میرے وہ احسان یاد کرو جو میں نے تم پر کئے تھے اور یہ کہ میں نے تم کو جہان کے لوگوں پر فضیلت بخشی تھی۔', 'اے بنی اسرائیل یاد کرو میرے احسان جو میں نے تم پر کئے اور اسکو کہ میں نے تم کو بڑائی دی تمام عالم پر [۷۳]', 'O Children of Israel! Remember My Favour which I bestowed upon you and that I preferred you to the Alameen (mankind and jinns) (of your time period, in the past).', 'O Children of Isrā’īl (Israel), remember My blessing that I conferred upon you, and that I gave you excellence over the worlds;'),
(55, 2, 48, 6, 6, 1, 'الم', 'البقرۃ', 'وَ اتَّقُوۡا یَوۡمًا لَّا تَجۡزِیۡ نَفۡسٌ عَنۡ نَّفۡسٍ شَیۡئًا وَّ لَا یُقۡبَلُ مِنۡہَا شَفَاعَۃٌ وَّ لَا یُؤۡخَذُ مِنۡہَا عَدۡلٌ وَّ لَا ہُمۡ یُنۡصَرُوۡنَ ﴿۴۸﴾', 'اوراس دن سے ڈرو جب کوئی کسی کے کچھ بھی کام نہ آئے اور نہ کسی کی سفارش منظور کی جائے اور نہ کسی سے کسی طرح کا بدلہ قبول کیا جائے اور نہ لوگ کسی اور طرح مدد حاصل کرسکیں۔', 'اور ڈرو اس دن سے کہ کام نہ آئے کوئی شخص کسی کے کچھ بھی اور قبول نہ ہو اسکی طرف سے سفارش اور نہ لیا جائے اس کی طرف سے بدلہ اور نہ ان کو مدد پہنچے [۷۴]', 'And fear a Day (of Judgement) when a person shall not avail another, nor will intercession be accepted from him nor will compensation be taken from him nor will they be helped.', 'and guard yourselves against a day when no one shall stand for anyone in anything, nor shall intercession be accepted on anyone’s behalf, nor shall ransom be taken from him, and neither shall any be given support.'),
(56, 2, 49, 6, 6, 1, 'الم', 'البقرۃ', 'وَ اِذۡ نَجَّیۡنٰکُمۡ مِّنۡ اٰلِ فِرۡعَوۡنَ یَسُوۡمُوۡنَکُمۡ سُوۡٓءَ الۡعَذَابِ یُذَبِّحُوۡنَ اَبۡنَآءَکُمۡ وَ یَسۡتَحۡیُوۡنَ نِسَآءَکُمۡ ؕ وَ فِیۡ ذٰلِکُمۡ بَلَآ ءٌ  مِّنۡ رَّبِّکُمۡ عَظِیۡمٌ ﴿۴۹﴾', 'اور ہمارے ان احسانات کو یاد کرو جب ہم نے تم کو قوم فرعون سے نجات بخشی وہ لوگ تمکو بڑا دکھ دیتے تھے تمہارے بیٹوں کو تو قتل کر ڈالتے تھے اور بیٹیوں کو زندہ رہنے دیتے تھے اور اس میں تمہارے پروردگار کی طرف سے بڑی سخت آزمائش تھی۔', 'اور یاد کرو اس وقت کو جبکہ رہائی دی ہم نے تم کو فرعون کے لوگوں سے جو کرتےتھے تم پر بڑا عذاب ذبح کرتے تھے تمہارے بیٹوں کو اور زندہ چھوڑتے تھے تمہاری عورتوں کو [۷۵] اور اس میں آزمائش تھی تمہارے رب کی طرف سے بڑی [۷۶]', 'And (remember) when We delivered you from Firauns (Pharaoh) people, who were afflicting you with a horrible torment, killing your sons and sparing your women, and therein was a mighty trial from your Lord.', '(Remember) when We delivered you from the people of Pharaoh! They had been inflicting on you grievous torment, slaughtering your sons and leaving your women alive. In all that, there was a great trial from your Lord.'),
(57, 2, 50, 6, 6, 1, 'الم', 'البقرۃ', 'وَ اِذۡ فَرَقۡنَا بِکُمُ الۡبَحۡرَ فَاَنۡجَیۡنٰکُمۡ وَ اَغۡرَقۡنَاۤ  اٰلَ فِرۡعَوۡنَ وَ اَنۡتُمۡ تَنۡظُرُوۡنَ ﴿۵۰﴾', 'اور جب ہم نے تمہارے لئے سمندر کو پھاڑ دیا پھر تم کو تو نجات دی اور فرعون کی قوم کو غرق کر دیا اور تم دیکھ رہے تھے۔', 'اور جب پھاڑ دیا ہم نے تمہاری وجہ سے دریا کو پھر بچا دیا ہم نے تم کو اور ڈبا دیا فرعون کے لوگوں کو اور تم دیکھ رہے تھے [۷۷]', 'And (remember) when We separated the sea for you and saved you and drowned Firauns (Pharaoh) people while you were looking (at them, when the sea-water covered them).', 'And (recall) when We parted the sea for you; then We saved you, and drowned the people of Pharaoh while you were looking on!'),
(58, 2, 51, 6, 6, 1, 'الم', 'البقرۃ', 'وَ اِذۡ وٰعَدۡنَا مُوۡسٰۤی اَرۡبَعِیۡنَ لَیۡلَۃً ثُمَّ اتَّخَذۡتُمُ الۡعِجۡلَ مِنۡۢ بَعۡدِہٖ وَ اَنۡتُمۡ ظٰلِمُوۡنَ ﴿۵۱﴾', 'اور جب ہم نے موسٰی سے چالیس رات کا وعدہ کیا تو تم نے ان کے پیچھے بچھڑے کو معبود مقرر کر لیا اور تم ظلم کر رہے تھے۔', 'اور جب ہم نے وعدہ کیا موسٰی سے چالیس رات کا پھر تم نے بنا لیا بچھڑا موسٰی کے بعد اور تم ظالم تھے [۷۸]', 'And (remember) when We appointed for Moosa (Moses) forty nights, and (in his absence) you took the calf (for worship), and you were Zalimoon (polytheists and wrong-doers, etc.).', 'And when We appointed forty nights for Mūsā, then you took the calf (as God) thereafter, and you were unjust.'),
(59, 2, 52, 6, 6, 1, 'الم', 'البقرۃ', 'ثُمَّ عَفَوۡنَا عَنۡکُمۡ مِّنۡۢ بَعۡدِ ذٰلِکَ لَعَلَّکُمۡ تَشۡکُرُوۡنَ ﴿۵۲﴾', 'پھر اس کے بعد ہم نے تم کو معاف کر دیا تا کہ تم شکر کرو۔', 'پھر معاف کیا ہم نے تم کو اس پر بھی تاکہ تم احسان مانو [۷۹]', 'Then after that We forgave you so that you might be grateful.', 'Yet We pardoned you, even after that, so that you may show gratitude.'),
(60, 2, 53, 6, 6, 1, 'الم', 'البقرۃ', 'وَ اِذۡ اٰتَیۡنَا مُوۡسَی الۡکِتٰبَ وَ الۡفُرۡقَانَ لَعَلَّکُمۡ تَہۡتَدُوۡنَ ﴿۵۳﴾', 'اور جب ہم نے موسٰی کو کتاب اور معجزے عنایت کئے تا کہ تم ہدایت حاصل کرو۔', 'اور جب ہم نے دی موسٰی کو کتاب اور حق کو ناحق سے جدا کرنے والے احکام تاکہ تم سیدھی راہ پاؤ [۸۰]', 'And (remember) when We gave Moosa (Moses) the Scripture (the Taurat (Torah)) and the criterion (of right and wrong) so that you may be guided aright.', 'Then We gave Mūsā the Book and the Criterion (of right and wrong), so that you may find the right path.'),
(61, 2, 54, 6, 6, 1, 'الم', 'البقرۃ', 'وَ اِذۡ قَالَ مُوۡسٰی لِقَوۡمِہٖ یٰقَوۡمِ  اِنَّکُمۡ ظَلَمۡتُمۡ اَنۡفُسَکُمۡ بِاتِّخَاذِکُمُ الۡعِجۡلَ فَتُوۡبُوۡۤا اِلٰی بَارِئِکُمۡ فَاقۡتُلُوۡۤا اَنۡفُسَکُمۡ ؕ ذٰلِکُمۡ خَیۡرٌ  لَّکُمۡ عِنۡدَ بَارِئِکُمۡ ؕ فَتَابَ عَلَیۡکُمۡ ؕ اِنَّہٗ ہُوَ التَّوَّابُ الرَّحِیۡمُ ﴿۵۴﴾', 'اور جب موسٰی نے اپنی قوم کے لوگوں سے کہا کہ بھائیو تم نے بچھڑے کو معبود ٹھہرانے میں اپنی جانوں پر ظلم کیا ہے تو اپنے پیدا کرنے والے کے آگے توبہ کرو  پھر اپنوں کو قتل کرو۔ تمہارے خالق کے نزدیک تمہارے حق میں یہی بہتر ہے پھر اس نے تمہارا قصور معاف کر دیا وہ بیشک بڑا معاف کرنے والا ہے بڑا مہربان ہے۔', 'اور جب کہا موسٰی نے اپنی قوم سے [۸۱] اے قوم تم نے نقصان کیا اپنایہ بچھڑا بنا کر سو اب توبہ کرو اپنے پیدا کرنے والے کی طرف اور مار ڈالو اپنی اپنی جان [۸۲] یہ بہتر ہے تمہارے لئے تمہارے خالق کے نزدیک پھر متوجہ ہوا تم پر [۸۳] بیشک وہی ہے معاف کرنے والا نہایت مہربان', 'And (remember) when Moosa (Moses) said to his people: \"O my people! Verily, you have wronged yourselves by worshipping the calf. So turn in repentance to your Creator and kill yourselves (the innocent kill the wrongdoers among you), that will be better for you with your Lord.\" Then He accepted your repentance. Truly, He is the One Who accepts repentance, the Most Merciful.', 'When Mūsā said to his people: “My people, you have wronged yourselves by your taking the calf (as God). So, turn in repentance to your Creator, and slay yourselves. That will be better for you in the sight of your Creator”. Then, He accepted your repentance. Indeed He is the Most-Relenting, the Very-Merciful.'),
(62, 2, 55, 6, 6, 1, 'الم', 'البقرۃ', 'وَ اِذۡ قُلۡتُمۡ یٰمُوۡسٰی لَنۡ نُّؤۡمِنَ لَکَ حَتّٰی نَرَی اللّٰہَ جَہۡرَۃً فَاَخَذَتۡکُمُ الصّٰعِقَۃُ وَ اَنۡتُمۡ تَنۡظُرُوۡنَ ﴿۵۵﴾', 'اور جب تم نے موسٰی سے کہا کہ موسٰی جب تک ہم اللہ کو سامنے نہ دیکھ لیں گے تم پر ایمان نہیں لائیں گے تو تم کو بجلی نے آ گھیرا اور تم دیکھ رہے تھے۔', 'اور جب تم نے کہا اے موسٰی ہم ہرگز یقین نہ کریں گے تیرا جب تک کہ نہ دیکھ لیں اللہ کو سامنے پھر آلیا تم کو بجلی نے اور تم دیکھ رہے تھے', 'And (remember) when you said: \"O Moosa (Moses)! We shall never believe in you till we see Allah plainly.\" But you were seized with a thunderbolt (lightning) while you were looking.', 'When you said, “Mūsā, we will never believe you till we see Allah openly!” So, the thunderbolt took you while you were looking on.'),
(63, 2, 56, 6, 6, 1, 'الم', 'البقرۃ', 'ثُمَّ بَعَثۡنٰکُمۡ مِّنۡۢ بَعۡدِ مَوۡتِکُمۡ لَعَلَّکُمۡ تَشۡکُرُوۡنَ ﴿۵۶﴾', 'پھر موت آجانے کے بعد ہم نے تم کو ازسر نو زندہ کر دیا تا کہ احسان مانو۔', 'پھر اٹھا کھڑا کیا ہم نے تم کو مر گئے پیچھے تاکہ تم احسان مانو [۸۴]', 'Then We raised you up after your death, so that you might be grateful.', 'Then, We raised you up after your death, so that you might show gratitude.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(64, 2, 57, 6, 6, 1, 'الم', 'البقرۃ', 'وَ ظَلَّلۡنَا عَلَیۡکُمُ الۡغَمَامَ وَ اَنۡزَلۡنَا عَلَیۡکُمُ الۡمَنَّ وَ السَّلۡوٰی ؕ کُلُوۡا مِنۡ طَیِّبٰتِ مَا رَزَقۡنٰکُمۡ ؕ وَ مَا ظَلَمُوۡنَا وَ لٰکِنۡ کَانُوۡۤا اَنۡفُسَہُمۡ یَظۡلِمُوۡنَ ﴿۵۷﴾', 'اور ہم نے بادل کا تم پر سایہ کئے رکھا اور تمہارے لئے من و سلوٰی اتارتے رہے کہ جو پاکیزہ چیزیں ہم نے تم کو عطا فرمائی ہیں انکو کھاؤ پیو مگر تمہارے بزرگوں نےان نعمتوں کی کچھ قدر نہ جانی اور وہ ہمارا کچھ نہیں بگاڑتے تھے بلکہ اپنا ہی نقصان کرتے تھے۔', 'اور سایہ کیا ہم نے تم پر ابر کا اور اتارا تم پر من اور سلویٰ [۸۵] کھاؤ پاکیزہ چیزیں جو ہم نے تم کو دیں [۸۶] اور انہوں نے ہمارا کچھ نقصان نہ کیا بلکہ اپنا ہی نقصان کرتے رہے [۸۷]', 'And We shaded you with clouds and sent down on you Al-Manna and the quails, (saying): \"Eat of the good lawful things We have provided for you,\" (but they rebelled). And they did not wrong Us but they wronged themselves.', 'And We made the cloud give you shade, and sent down to you Mann and Salwā: “Eat of the good things We have provided to you”. And they (by their ingratitude) did Us no harm, but were harming only themselves.'),
(65, 2, 58, 6, 6, 1, 'الم', 'البقرۃ', 'وَ  اِذۡ قُلۡنَا ادۡخُلُوۡا ہٰذِہِ الۡقَرۡیَۃَ فَکُلُوۡا مِنۡہَا حَیۡثُ شِئۡتُمۡ رَغَدًا وَّ ادۡخُلُوا الۡبَابَ سُجَّدًا وَّ قُوۡلُوۡا حِطَّۃٌ نَّغۡفِرۡ لَکُمۡ خَطٰیٰکُمۡ ؕ وَ سَنَزِیۡدُ الۡمُحۡسِنِیۡنَ ﴿۵۸﴾', 'اور جب ہم نے ان سے کہا کہ اس گاؤں میں داخل ہو جاؤ اور اس میں جہاں سے چاہو خوب کھاؤ پیو اور دیکھنا دروازے میں داخل ہونا سجدہ کرتے ہوئے اور حِطَۃٌ کہنا ہم تمہارے گناہ معاف کردیں گے اور نیکی کرنے والوں کو اور زیادہ دیں گے۔', 'اور جب ہم نے کہا داخل ہو اس شہر میں [۸۸] اور کھاتے پھرو اسمیں جہاں چاہو فراغت سے اور داخل ہو  دروازے میں سجدہ کرتے  ہوئے [۸۹] اور کہتے جاؤ بخشدے تو معاف کر دیں گے ہم تمہارے قصور اور زیادہ بھی دیں گے نیکی والوں کو [۹۰]', 'And (remember) when We said: \"Enter this town (Jerusalem) and eat bountifully therein with pleasure and delight wherever you wish, and enter the gate in prostration (or bowing with humility) and say: Forgive us, and We shall forgive you your sins and shall increase (reward) for the good-doers.\"', 'When We said, “Enter this town, and eat to your heart’s content wherever you wish in it; and enter the gate prostrating yourselves and say: HiTTah (we seek forgiveness), so that We forgive your errors. And We shall give much more to those who do good.”'),
(66, 2, 59, 6, 6, 1, 'الم', 'البقرۃ', 'فَبَدَّلَ الَّذِیۡنَ ظَلَمُوۡا قَوۡلًا غَیۡرَ الَّذِیۡ قِیۡلَ لَہُمۡ فَاَنۡزَلۡنَا عَلَی الَّذِیۡنَ ظَلَمُوۡا رِجۡزًا مِّنَ السَّمَآءِ بِمَا کَانُوۡا یَفۡسُقُوۡنَ ﴿٪۵۹﴾', 'تو جو ظالم تھے انہوں نے اس لفظ کو جس کا ان کو حکم دیا تھا بدل کر اس کی جگہ اور لفظ کہنا شروع کیا پس ہم نے ان ظالموں پر آسمان سے عذاب نازل کیا کیونکہ نافرمانیاں کئے جاتے تھے۔', 'پھر بدل ڈالا ظالموں نے بات کو خلاف اسکے جو کہہ دی گئی تھی ان سے پھر اتارا ہم نے ظالموں پر عذاب آسمان سے ان کی عدول حکمی پر [۹۱]', 'But those who did wrong changed the word from that which had been told to them for another, so We sent upon the wrong-doers Rijzan (a punishment) from the heaven because of their rebelling against Allahs Obedience. (Tafsir At-Tabaree, Vol. I, Page 305).', 'But those who were unjust substituted another word for the one that was prescribed for them. So, We sent down a scourge from heaven upon those who were unjust, because they had acted sinfully.'),
(67, 2, 60, 7, 7, 1, 'الم', 'البقرۃ', 'وَ اِذِ اسۡتَسۡقٰی مُوۡسٰی لِقَوۡمِہٖ فَقُلۡنَا اضۡرِبۡ بِّعَصَاکَ الۡحَجَرَ ؕ فَانۡفَجَرَتۡ مِنۡہُ اثۡنَتَاعَشۡرَۃَ عَیۡنًا ؕ قَدۡ عَلِمَ کُلُّ اُنَاسٍ مَّشۡرَبَہُمۡ ؕ کُلُوۡا وَ اشۡرَبُوۡا مِنۡ رِّزۡقِ اللّٰہِ وَ لَا تَعۡثَوۡا فِی الۡاَرۡضِ مُفۡسِدِیۡنَ ﴿۶۰﴾', 'اور جب موسٰی نے اپنی قوم کے لئے ہم سے پانی مانگا تو ہم نے کہا کہ اپنی لاٹھی پتھر پر مارو انہوں نے لاٹھی ماری تو اس میں سے بارہ چشمے پھوٹ نکلے اور تمام لوگوں نے اپنا اپنا گھاٹ معلوم کر کے پانی پی لیا ہم نے حکم دیا کہ اللہ کی عطا فرمائی ہوئی روزی کھاؤ اور پیو اور زمین میں فساد نہ کرتے پھرنا۔', 'اور  جب پانی مانگا موسٰی نے اپنی قوم کے واسطے تو ہم نے کہا مار اپنے عصا کو پتھر پر سو بہہ نکلے  اس سے بارہ چشمے [۹۲] پہچان لیا ہر قوم نے اپنا گھاٹ کھاؤ اور پیو اللہ کی روزی اور نہ پھرو ملک میں فساد مچاتے [۹۳]', 'And (remember) when Moosa (Moses) asked for water for his people, We said: \"Strike the stone with your stick.\" Then gushed forth therefrom twelve springs. Each (group of) people knew its own place for water. \"Eat and drink of that which Allah has provided and do not act corruptly, making mischief on the earth.\"', 'When Mūsā sought water for his people, We said, “Strike the rock with your staff,” And twelve springs gushed forth from it. Each group of people came to know their drinking place. “Eat and drink of what Allah has provided, and do not go about the earth spreading disorder.”'),
(68, 2, 61, 7, 7, 1, 'الم', 'البقرۃ', 'وَ  اِذۡ قُلۡتُمۡ یٰمُوۡسٰی لَنۡ نَّصۡبِرَ عَلٰی طَعَامٍ وَّاحِدٍ فَادۡعُ لَنَا رَبَّکَ یُخۡرِجۡ لَنَا مِمَّا تُنۡۢبِتُ الۡاَرۡضُ مِنۡۢ بَقۡلِہَا وَ قِثَّآئِہَا وَ فُوۡمِہَا وَ عَدَسِہَا وَ بَصَلِہَا ؕ قَالَ اَتَسۡتَبۡدِلُوۡنَ الَّذِیۡ ہُوَ اَدۡنٰی بِالَّذِیۡ ہُوَ خَیۡرٌ ؕ اِہۡبِطُوۡا مِصۡرًا فَاِنَّ لَکُمۡ مَّا سَاَلۡتُمۡ  ؕ وَ ضُرِبَتۡ عَلَیۡہِمُ الذِّلَّۃُ  وَ الۡمَسۡکَنَۃُ ٭ وَ بَآءُوۡ بِغَضَبٍ مِّنَ اللّٰہِ ؕ ذٰلِکَ بِاَنَّہُمۡ کَانُوۡا یَکۡفُرُوۡنَ بِاٰیٰتِ اللّٰہِ وَ یَقۡتُلُوۡنَ النَّبِیّٖنَ بِغَیۡرِ الۡحَقِّ ؕ ذٰلِکَ بِمَا عَصَوۡا وَّ کَانُوۡا یَعۡتَدُوۡنَ ﴿٪۶۱﴾', 'اور جب تم نے کہا کہ موسٰی! ہم سے ایک ہی کھانے پر صبر نہیں ہو سکتا تو اپنے پروردگار سے دعا کیجئے کہ ترکاری اور ککڑی اور گہیوں اور مسور اور پیاز وغیرہ جو نباتات زمین سے اگتی ہیں ہمارے لئے پیدا کر دے۔ انہوں نے کہا کہ عمدہ چیزیں چھوڑ کر ان کے بدلے ناقص چیزیں کیوں چاہتے ہو اگر یہی چیزیں مطلوب ہیں تو کسی شہر میں جا اترو  وہاں جو مانگتے ہو مل جائے گا اور آخرکار ذلت و رسوائی اور محتاجی و بے نوائی ان سے چمٹا دی گئ اور وہ اللہ کے غضب میں گرفتار ہو گئے۔ یہ اس لئے کہ وہ اللہ کی آیتوں سے انکار کرتے تھے اور اس کے نبیوں کو ناحق قتل کر دیتے تھے یعنی اس لئے کہ نافرمانی کئے جاتے اور حد سے بڑھے جاتے تھے۔', 'اور جب کہا تم نے اے موسٰی ہم ہر گز صبر نہ کریں گے ایک ہی کھانے پر سو دعا مانگ ہمارے واسطے اپنے پروردگار سے کہ نکال دے ہمارے واسطے جو اگتا ہے زمین سے ترکاری اور ککڑی اور گیہوں اور مسور اور پیاز [۹۴] کہا موسٰی نے کیا لینا چاہتے وہ چیز جو ادنیٰ ہے اس کے بدلہ میں جو بہتر ہے [۹۵] اترو کسی شہر میں تو تم کو ملے جو مانگتے ہو [۹۶] اور ڈالی گئ ان پر ذلت اور محتاجی اور پھرے اللہ کا غضب لے کر [۹۷] یہ اس لئے ہوا کہ نہیں مانتے تھے احکام خداوندی کو اور خون کرتے تھے پیغمبروں کا ناحق یہ اس لئے کہ نافرمان تھے اور حد پر نہ رہتے تھے [۹۸]', 'And (remember) when you said, \"O Moosa (Moses)! We cannot endure one kind of food. So invoke your Lord for us to bring forth for us of what the earth grows, its herbs, its cucumbers, its Foom (wheat or garlic), its lentils and its onions.\" He said, \"Would you exchange that which is better for that which is lower? Go you down to any town and you shall find what you want!\" And they were covered with humiliation and misery, and they drew on themselves the Wrath of Allah. That was because they used to disbelieve the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah and killed the Prophets wrongfully. That was because they disobeyed and used to transgress the bounds (in their disobedience to Allah, i.e. commit crimes and sins).', 'And when you said, “Mūsā , we will no longer confine ourselves to a single food: So, pray for us to your Lord that He may bring forth for us of what the earth grows - of its vegetable, its cucumbers, its wheat, its lentils and its onions.” He said, “Do you want to take what is inferior in exchange for what is better? Go down to a town, and you will have what you ask for.” Then they were stamped with disgrace and misery, and they returned with wrath from Allah. That was because they used to deny the signs of Allah, and would slay the prophets unjustly. That was because they disobeyed and transgressed all limits.'),
(69, 2, 62, 8, 8, 1, 'الم', 'البقرۃ', 'اِنَّ الَّذِیۡنَ اٰمَنُوۡا وَ الَّذِیۡنَ ہَادُوۡا وَ النَّصٰرٰی وَ الصّٰبِئِیۡنَ مَنۡ اٰمَنَ بِاللّٰہِ وَ الۡیَوۡمِ الۡاٰخِرِ وَ عَمِلَ صَالِحًا فَلَہُمۡ اَجۡرُہُمۡ عِنۡدَ رَبِّہِمۡ ۪ۚ وَ لَا خَوۡفٌ عَلَیۡہِمۡ وَ لَا ہُمۡ یَحۡزَنُوۡنَ ﴿۶۲﴾', 'جو لوگ مسلمان ہیں یا یہودی یا عیسائی یا ستارہ پرست یعنی کوئی شخص کسی قوم و مذہب کا ہو جو اللہ اور روز قیامت پر ایمان لائے گا اور عمل نیک کرے گا تو ایسے لوگوں کو ان کے اعمال کا صلہ اللہ کے ہاں ملے گا اور قیامت کے دن ان کو نہ کسی طرح کا خوف ہو گا اور نہ وہ غمناک ہوں گے۔', 'بیشک جو لوگ مسلمان ہوئے اور جو لوگ یہودی ہوئے اور نصاریٰ اور صائبین جو ایمان لایا (ان میں سے) اللہ پر اور روز قیامت پر اور کام کئے نیک تو انکے لئے ہے انکا ثواب انکے رب کے پاس اور نہیں ان پر کچھ خوف اور نہ وہ غمگین ہوں گے [۹۹]', 'Verily! Those who believe and those who are Jews and Christians, and Sabians, whoever believes in Allah and the Last Day and do righteous good deeds shall have their reward with their Lord, on them shall be no fear, nor shall they grieve .', 'Surely, those who believed in Allah, and those who are Jews, and Christians, and Sabians, -whosoever believes in Allah and in the Last Day, and does good deeds - all such people will have their reward with their Lord, and there will be no reason for them to fear, nor shall they grieve.'),
(70, 2, 63, 8, 8, 1, 'الم', 'البقرۃ', 'وَ اِذۡ اَخَذۡنَا مِیۡثَاقَکُمۡ وَ رَفَعۡنَا فَوۡقَکُمُ الطُّوۡرَ ؕ خُذُوۡا مَاۤ اٰتَیۡنٰکُمۡ بِقُوَّۃٍ وَّ اذۡکُرُوۡا مَا فِیۡہِ لَعَلَّکُمۡ تَتَّقُوۡنَ ﴿۶۳﴾', 'اور جب ہم نے تم سے عہد کر لیا اور کوہ طور کو تم پر اٹھا کھڑا کیا اور حکم دیا کہ جو کتاب ہم نے تم کو دی ہے اس کو زور سے پکڑے رہو اور جو اس میں لکھا ہے اسے یاد رکھو تاکہ عذاب سے محفوظ رہو۔', 'اور جب لیا ہم نے تم سے قرار اور بلند کیا تمہارے اوپر کوہ طور کو کہ پکڑو جو کتاب ہم نے تم کو دی زور سے اور یاد رکھو جو کچھ اس میں ہے تاکہ تم ڈرو [۱۰۰]', 'And (O Children of Israel, remember) when We took your covenant and We raised above you the Mount (saying): \"Hold fast to that which We have given you, and remember that which is therein so that you may become Al-Muttaqoon (the pious - see V.2:2).', 'And when We took the pledge from you, and raised high above you the (Mount of) Tūr: “Hold fast to what We have given to you, and remember what is in it, so that you may become God-fearing.”'),
(71, 2, 64, 8, 8, 1, 'الم', 'البقرۃ', 'ثُمَّ تَوَلَّیۡتُمۡ مِّنۡۢ بَعۡدِ ذٰلِکَ ۚ فَلَوۡ لَا فَضۡلُ اللّٰہِ عَلَیۡکُمۡ وَ رَحۡمَتُہٗ لَکُنۡتُمۡ مِّنَ  الۡخٰسِرِیۡنَ ﴿۶۴﴾', 'پھر تم اس کے بعد عہد سے پھر گئے سو اگر تم پر اللہ کا فضل اور اس کی مہربانی نہ ہوتی تو تم خسارے میں پڑ گئے ہوتے۔', 'پھر تم پھر گئے اس کے بعد سو اگر نہ ہوتا اللہ کا فضل تم پر اور اسکی مہربانی تو ضرور تم تباہ ہوتے [۱۰۱]', 'Then after that you turned away. Had it not been for the Grace and Mercy of Allah upon you, indeed you would have been among the losers.', 'Then even after that, you turned away. So, had it not been for the grace of Allah upon you, and His mercy, you would have been among the losers.'),
(72, 2, 65, 8, 8, 1, 'الم', 'البقرۃ', 'وَ لَقَدۡ عَلِمۡتُمُ  الَّذِیۡنَ اعۡتَدَوۡا مِنۡکُمۡ فِی السَّبۡتِ فَقُلۡنَا لَہُمۡ کُوۡنُوۡا قِرَدَۃً خٰسِئِیۡنَ ﴿ۚ۶۵﴾', 'اور تم ان لوگوں کو خوب جانتے ہو جو تم میں سے ہفتے کے دن مچھلی کا شکار کرنے میں حد سے تجاوز کر گئے تھے تو ہم نے ان سے کہا کہ ذلیل و خوار بندر ہو جاؤ۔', 'اور تم خوب جان چکے ہو جنہوں نے کہ تم میں سے زیادتی کی تھی ہفتہ کے دن میں تو ہم نے کہا ان سے ہو جاؤ بندر ذلیل [۱۰۲]', 'And indeed you knew those amongst you who transgressed in the matter of the Sabbath (i.e. Saturday). We said to them: \"Be you monkeys, despised and rejected.\"', 'Certainly you have knowledge of those among you who transgressed in (the matter of) the Sabbath. We said to them, “Become apes, abased.”'),
(73, 2, 66, 8, 8, 1, 'الم', 'البقرۃ', 'فَجَعَلۡنٰہَا نَکَالًا لِّمَا بَیۡنَ یَدَیۡہَا وَ مَا خَلۡفَہَا وَ مَوۡعِظَۃً  لِّلۡمُتَّقِیۡنَ ﴿۶۶﴾', 'اور اس قصے کو اس وقت کے لوگوں کے لئے اور جو انکے بعد آنے والے تھے عبرت اور  پرہیز گاروں کے لئے نصیحت بنا دیا۔', 'پھر کیا ہم نے اس واقعہ کو عبرت ان لوگوں کے لئے جو وہاں تھے اور جو پیچھے آنے والے تھے اور نصیحت ڈرنے والوں کے واسطے [۱۰۳]', 'So We made this punishment an example to their own and to succeeding generations and a lesson to those who are Al-Muttaqoon (the pious - see V.2:2).', 'Thus, We made it a deterrent for those around and (those who came) after them - and a lesson for the God-fearing.'),
(74, 2, 67, 8, 8, 1, 'الم', 'البقرۃ', 'وَ اِذۡ قَالَ مُوۡسٰی لِقَوۡمِہٖۤ  اِنَّ اللّٰہَ یَاۡمُرُکُمۡ اَنۡ تَذۡبَحُوۡا بَقَرَۃً ؕ قَالُوۡۤا اَتَتَّخِذُنَا ہُزُوًا ؕ قَالَ اَعُوۡذُ بِاللّٰہِ اَنۡ اَکُوۡنَ مِنَ  الۡجٰہِلِیۡنَ ﴿۶۷﴾', 'اور جب موسٰی نے اپنی قوم کے لوگوں سے کہا کہ اللہ تم کو حکم دیتا ہے کہ ایک بیل ذبح کرو۔ وہ بولے کیا تم ہم سے ہنسی کرتے ہو؟ موسٰی نے کہا کہ میں اللہ کی پناہ مانگتا ہوں کہ نادان بنوں۔', 'اور جب کہا موسٰی نے اپنی قوم سے اللہ تعالیٰ فرماتا ہے تم کو ذبح کرو ایک گائے [۱۰۴] وہ بولے کیا تو ہم سے ہنسی کرتا ہے [۱۰۵] کہا پناہ خدا کی کہ ہوں میں جاہلوں میں [۱۰۶]', 'And (remember) when Moosa (Moses) said to his people: \"Verily, Allah commands you that you slaughter a cow.\" They said, \"Do you make fun of us?\" He said, \"I take Allahs Refuge from being among Al-Jahiloon (the ignorants or the foolish).\"', 'When Mūsā said to his people, “Allah commands you to slaughter a cow”, they said, “Are you making fun of us?” He said, “I seek refuge with Allah from being one of the ignorant.”'),
(75, 2, 68, 8, 8, 1, 'الم', 'البقرۃ', 'قَالُوا ادۡعُ لَنَا رَبَّکَ یُبَیِّنۡ لَّنَا مَا ہِیَ ؕ قَالَ  اِنَّہٗ یَقُوۡلُ  اِنَّہَا بَقَرَۃٌ لَّا فَارِضٌ وَّ لَا بِکۡرٌ ؕ عَوَانٌۢ بَیۡنَ ذٰلِکَ ؕ فَافۡعَلُوۡا مَا تُؤۡمَرُوۡنَ ﴿۶۸﴾', 'انہوں نے کہا کہ اپنے پروردگار سے التجا کیجئے کہ وہ ہمیں یہ بتائے کہ وہ بیل کس طرح کا ہو۔ موسٰی نے کہا پروردگار فرماتا ہے کہ وہ بیل نہ تو بوڑھا ہو اور نہ بچھڑا بلکہ انکے درمیان یعنی جوان ہو سو جیسا تم کو حکم دیا گیا ہے ویسا کرو۔', 'بولے کہ دعا کرو ہمارے واسطے اپنے رب سے کہ بتا دے ہم کو کہ وہ گائے کیسی ہے [۱۰۷] کہا وہ فرماتا کہ وہ ایک گائے ہے نہ بوڑھی اور نہ بن بیاہی درمیان میں ہے بڑھاپے اور جوانی کے اب کر ڈالو جو تم کو حکم ملا ہے [۱۰۸]', 'They said, \"Call upon your Lord for us that He may make plain to us what it is!\" He said, \"He says, Verily, it is a cow neither too old nor too young, but (it is) between the two conditions, so do what you are commanded.\"', 'They said, “Pray for us to your Lord that He makes it clear to us what sort (of cow) should she be.” He said, “He says she should be a cow neither too old, nor too young - of some middle age in between. Now, do what you are being asked to do.”'),
(76, 2, 69, 8, 8, 1, 'الم', 'البقرۃ', 'قَالُوا ادۡعُ لَنَا رَبَّکَ یُبَیِّنۡ لَّنَا مَا لَوۡنُہَا ؕ قَالَ  اِنَّہٗ یَقُوۡلُ  اِنَّہَا بَقَرَۃٌ صَفۡرَآءُ ۙ فَاقِعٌ لَّوۡنُہَا تَسُرُّ النّٰظِرِیۡنَ ﴿۶۹﴾', 'انہوں نے کہا اپنے پروردگار سے درخواست کیجئے کہ ہم کو یہ بھی بتا دے کہ اس کا رنگ کیسا ہو۔ موسٰی نے کہا پروردگار فرماتا ہے کہ اس کا رنگ گہرا زرد ہو کہ دیکھنے والوں کے دل کو خوش کر دیتا ہو۔', 'بولے کہ دعا کر ہمارے واسطے اپنے رب سے کہ بتا دے ہم کو کیسا ہے اس کا رنگ کہا وہ فرماتا ہےکہ وہ ایک گائے ہے زرد خوب گہری ہے اس کی زردی خوش آتی ہے دیکھنے والوں کو', 'They said, \"Call upon your Lord for us to make plain to us its colour.\" He said, \"He says, It is a yellow cow, bright in its colour, pleasing to the beholders. \"', 'They said, “Pray for us to your Lord that He makes it clear to us of what colour it should be.” He said: “He says that she should be a yellow cow, rich yellow in her colour that should please the onlookers.”'),
(77, 2, 70, 8, 8, 1, 'الم', 'البقرۃ', 'قَالُوا ادۡعُ لَنَا رَبَّکَ یُبَیِّنۡ لَّنَا مَا ہِیَ ۙ اِنَّ الۡبَقَرَ تَشٰبَہَ عَلَیۡنَا ؕ وَ  اِنَّاۤ اِنۡ شَآءَ  اللّٰہُ  لَمُہۡتَدُوۡنَ ﴿۷۰﴾', 'انہوں نے کہا اب کے پروردگار سے پھر درخواست کیجئے کہ ہم کو بتا دے کہ وہ اور کس کس طرح کا ہو کیونکہ بہت سے بیل ہمیں ایک دوسرے کے مشابہ معلوم ہوتے ہیں اور اللہ نے چاہا تو ہمیں ٹھیک بات معلوم ہو جائے گی۔', 'بولے دعا کر ہمارے واسطے اپنے رب سے کہ بتا دے ہم کو کس قسم میں ہے وہ [۱۰۹] کیونکہ اس گائے میں شبہہ پڑا ہے ہم کو اور ہم اگر اللہ نے چاہا تو ضرور راہ پا لیں گے', 'They said, \"Call upon your Lord for us to make plain to us what it is. Verily to us all cows are alike, And surely, if Allah wills, we will be guided.\"', 'They said, “Pray for us to your Lord that He makes it clear to us of what sort should she be, for this cow has made us confused and, if Allah wills, We shall certainly take the right course.”'),
(78, 2, 71, 8, 8, 1, 'الم', 'البقرۃ', 'قَالَ اِنَّہٗ یَقُوۡلُ  اِنَّہَا بَقَرَۃٌ لَّا ذَلُوۡلٌ تُثِیۡرُ الۡاَرۡضَ وَ لَا تَسۡقِی الۡحَرۡثَ ۚ مُسَلَّمَۃٌ لَّا شِیَۃَ فِیۡہَا ؕ قَالُوا الۡـٰٔنَ جِئۡتَ بِالۡحَقِّ ؕ فَذَبَحُوۡہَا وَ مَا کَادُوۡا یَفۡعَلُوۡنَ ﴿٪۷۱﴾', 'موسٰی نے کہا کہ اللہ فرماتا ہے کہ وہ بیل کام میں لگا ہوا نہ ہو۔ نہ تو زمین جوتتا ہو اور نہ کھیتی کو پانی دیتا ہو بے عیب ہو اس میں کسی طرح کا داغ نہ ہو۔ کہنے لگے اب تم نے سب باتیں درست بتا دیں غرض بڑی مشکل سے انہوں نے اس بیل کو ذبح کیا جبکہ وہ ایسا کرنے والے لگتے نہ تھے۔', 'کہا وہ فرماتا ہے کہ وہ ایک گائے ہے محنت کرنے والی نہیں کہ جوتتی ہو زمین کو یا پانی دیتی ہو کھیتی کو بے عیب ہے کوئی داغ اسمیں نہیں [۱۱۰] بولے اب لایا تو ٹھیک بات پھر اس کو ذبح کیا اور وہ لگتے نہ تھے کہ ایسا کر لیں گے [۱۱۱]', 'He (Moosa (Moses)) said, \"He says, It is a cow neither trained to till the soil nor water the fields, sound, having no other colour except bright yellow. \" They said, \"Now you have brought the truth.\" So they slaughtered it though they were near to not doing it.', 'He said, “He says that it should be a cow which is not tractable for tilling the soil or in watering the fields, (and it should be) sound and without blemish.” They said, “Now, you have come up with the right description.” Then they slaughtered her, although it appeared that they would not do it.'),
(79, 2, 72, 9, 9, 1, 'الم', 'البقرۃ', 'وَ اِذۡ قَتَلۡتُمۡ نَفۡسًا فَادّٰرَءۡتُمۡ فِیۡہَا ؕ وَ اللّٰہُ مُخۡرِجٌ مَّا کُنۡتُمۡ تَکۡتُمُوۡنَ ﴿ۚ۷۲﴾', 'اور جب تم نے ایک شخص کو قتل کیا تو اس میں باہم جھگڑنے لگے۔ حالانکہ جو بات تم چھپا رہے تھے اللہ اسکو ظاہر کرنے والا تھا۔', 'اور جب مار ڈالا تھا تم نے ایک شخص کو پھر لگے ایک دوسرے پر دھرنے اور اللہ کو ظاہر کرنا تھا جو تم چھپاتے تھے [۱۱۲]', 'And (remember) when you killed a man and fell into dispute among yourselves as to the crime. But Allah brought forth that which you were hiding.', 'And when you killed a man, and started putting the blame for it on one another, while Allah was to bring forth what you were holding back.'),
(80, 2, 73, 9, 9, 1, 'الم', 'البقرۃ', 'فَقُلۡنَا اضۡرِبُوۡہُ بِبَعۡضِہَا ؕ کَذٰلِکَ یُحۡیِ اللّٰہُ  الۡمَوۡتٰی ۙ وَ یُرِیۡکُمۡ اٰیٰتِہٖ لَعَلَّکُمۡ تَعۡقِلُوۡنَ ﴿۷۳﴾', 'چنانچہ ہم نے کہا کہ اس بیل کا کوئی سا ٹکڑا مقتول کو مارو۔ اس طرح اللہ مردوں کو زندہ کرتا ہے اور تم کو اپنی قدرت کی نشانیاں دکھاتا ہے تاکہ تم سمجھو۔', 'پھر ہم نے کہا مارو اس مردہ پر اس گائے کا ایک ٹکڑا [۱۱۳] اسی طرح زندہ کرے گا اللہ مردو ں کو اور دکھاتا ہے تم کو اپنی قدرت کے نمونے تاکہ تم غور کرو [۱۱۴]', 'So We said: \"Strike him (the dead man) with a piece of it (the cow).\" Thus Allah brings the dead to life and shows you His Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) so that you may understand.', 'So, We said, “Strike him with a part of it.” This is how Allah revives the dead; and He shows you His signs, so that you may understand.'),
(81, 2, 74, 9, 9, 1, 'الم', 'البقرۃ', 'ثُمَّ قَسَتۡ قُلُوۡبُکُمۡ مِّنۡۢ بَعۡدِ ذٰلِکَ فَہِیَ کَالۡحِجَارَۃِ اَوۡ اَشَدُّ قَسۡوَۃً ؕ وَ  اِنَّ مِنَ الۡحِجَارَۃِ لَمَا یَتَفَجَّرُ  مِنۡہُ الۡاَنۡہٰرُ ؕ وَ اِنَّ مِنۡہَا لَمَا یَشَّقَّقُ فَیَخۡرُجُ مِنۡہُ الۡمَآءُ ؕ وَ اِنَّ مِنۡہَا لَمَا یَہۡبِطُ مِنۡ خَشۡیَۃِ اللّٰہِ  ؕوَ مَا اللّٰہُ بِغَافِلٍ عَمَّا تَعۡمَلُوۡنَ ﴿۷۴﴾', 'پھر اس کے بعد تمہارے دل سخت ہو گئے گویا وہ پتھر ہیں یا ان سے بھی زیادہ سخت اور پتھر تو بعضے ایسے ہوتے ہیں کہ ان میں سے چشمے پھوٹ نکلتے ہیں اور بعضے ایسے ہوتے ہیں کہ پھٹ جاتے ہیں اور ان میں سے پانی نکلنے لگتا ہے اور بعضے ایسے ہوتے ہیں کہ اللہ کے خوف سے گر پڑتے ہیں اور اللہ تمہارے کرتوتوں سے بے خبر نہیں۔', 'پھر تمہارے دل سخت ہو گئے اس سب کے بعد [۱۱۵] سو وہ ہو گئے جیسے پتھر یا ان سے بھی سخت اور پتھروں میں تو ایسے بھی ہیں جن سے جاری ہوتی ہیں نہریں اور ان میں ایسے بھی ہیں جو پھٹ جاتے ہیں اور نکلتا ہے ان سے پانی اور ان میں ایسے بھی ہیں جو گر  پڑتے ہیں اللہ کے ڈر سے اور اللہ بیخبر نہیں تمہارے کاموں سے [۱۱۶]', 'Then, after that, your hearts were hardened and became as stones or even worse in hardness. And indeed, there are stones out of which rivers gush forth, and indeed, there are of them (stones) which split asunder so that water flows from them, and indeed, there are of them (stones) which fall down for fear of Allah. And Allah is not unaware of what you do.', 'When, even after that, your hearts were hardened, as if they were rocks, or still worse in hardness. For surely among the rocks there are some from which rivers gush forth, and there are others that crack open and water flows from them, and there are still others that fall down in fear of Allah. And Allah is not unaware of what you do.'),
(82, 2, 75, 9, 9, 1, 'الم', 'البقرۃ', 'اَفَتَطۡمَعُوۡنَ اَنۡ یُّؤۡمِنُوۡا لَکُمۡ وَ قَدۡ کَانَ فَرِیۡقٌ مِّنۡہُمۡ یَسۡمَعُوۡنَ کَلٰمَ اللّٰہِ ثُمَّ یُحَرِّفُوۡنَہٗ مِنۡۢ بَعۡدِ مَا عَقَلُوۡہُ وَ ہُمۡ یَعۡلَمُوۡنَ ﴿۷۵﴾', 'مومنو کیا تم امید رکھتے ہو کہ یہ لوگ تمہارے دین کے قائل ہو جائیں گے حالانکہ ان میں سے کچھ لوگ کلام اللہ یعنی تورات کو سنتے پھر اس کے سمجھ لینے کے بعد اسکو جان بوجھ کر بدل دیتے رہے ہیں۔', 'اب کیا تم اے مسلمانوں توقع رکھتے ہو کہ وہ مانیں تمہاری بات اور ان میں ایک فرقہ تھا کہ سنتا تھا اللہ کا کلام  پھر بدل ڈالتے تھے اس کو جان بوجھ کر اور وہ جانتے تھے [۱۱۷]', 'Do you (faithful believers) covet that they will believe in your religion inspite of the fact that a party of them (Jewish rabbis) used to hear the Word of Allah (the Taurat (Torah)), then they used to change it knowingly after they understood it?', '(O Muslims) do you still fancy that they will believe you, although a group of them used to hear the word of Allah, and then, having understood it, used to distort it knowingly?'),
(83, 2, 76, 9, 9, 1, 'الم', 'البقرۃ', 'وَ اِذَا لَقُوا الَّذِیۡنَ اٰمَنُوۡا قَالُوۡۤا اٰمَنَّا   ۚۖ وَ اِذَا خَلَا بَعۡضُہُمۡ  اِلٰی بَعۡضٍ قَالُوۡۤا اَتُحَدِّثُوۡنَہُمۡ بِمَا فَتَحَ اللّٰہُ عَلَیۡکُمۡ لِیُحَآجُّوۡکُمۡ بِہٖ عِنۡدَ رَبِّکُمۡ ؕ اَفَلَا تَعۡقِلُوۡنَ ﴿۷۶﴾', 'اور یہ لوگ جب مومنوں سے ملتے ہیں تو کہتے ہیں ہم ایمان لے آئے ہیں۔ اور جس وقت تنہائی میں ایک دوسرے سے ملتے ہیں تو کہتے ہیں جو بات اللہ نے تم پر ظاہر فرمائی ہے وہ تم ان کو اس لئے بتائے دیتے ہو کہ قیامت کے دن اسی کے حوالے سے تمہارے پروردگار کے سامنے تم کو الزام دیں۔ کیا تم سمجھتے نہیں؟', 'اور جب ملتے ہیں مسلمانوں سے کہتے ہیں ہم مسلمان ہوئے اور جب تنہا ہوتے ہیں ایک دوسرے کے پاس تو کہتے ہیں تم کیوں کہہ دیتے ہو ان سے جو ظاہر کیا ہے اللہ نے تم پر تاکہ جھٹلائیں تم کو اس سے تمہارے رب کے آگے کیا تم نہیں سمجھتے [۱۱۸]', 'And when they (Jews) meet those who believe (Muslims), they say, \"We believe\", but when they meet one another in private, they say, \"Shall you (Jews) tell them (Muslims) what Allah has revealed to you (Jews, about the description and the qualities of Prophet Muhammad Peace be upon him , that which are written in the Taurat (Torah)) , that they (Muslims) may argue with you (Jews) about it before your Lord?\" Have you (Jews) then no understanding?', 'When they meet those who believe, they say, “We believe.” But when some of them meet others in private, they say, “Do you tell them (the Muslims) what Allah has disclosed to you so that they may thereby argue against you before your Lord? Will you, then, not use reason?”'),
(84, 2, 77, 9, 9, 1, 'الم', 'البقرۃ', 'اَ وَ لَا یَعۡلَمُوۡنَ اَنَّ اللّٰہَ یَعۡلَمُ مَا یُسِرُّوۡنَ وَ مَا یُعۡلِنُوۡنَ ﴿۷۷﴾', 'کیا یہ لوگ یہ نہیں جانتے کہ جو کچھ یہ چھپاتے اور جو کچھ ظاہر کرتے ہیں اللہ کو سب معلوم ہے۔', 'کیا اتنا بھی نہیں جانتے کہ اللہ کو معلوم ہے جو کچھ چھپاتے ہیں اور جو کچھ ظاہر کرتے ہیں [۱۱۹]', 'Know they (Jews) not that Allah knows what they conceal and what they reveal?', 'Are they not aware that Allah knows what they conceal and what they reveal?'),
(85, 2, 78, 9, 9, 1, 'الم', 'البقرۃ', 'وَ مِنۡہُمۡ اُمِّیُّوۡنَ لَا یَعۡلَمُوۡنَ الۡکِتٰبَ اِلَّاۤ اَمَانِیَّ وَ اِنۡ ہُمۡ  اِلَّا یَظُنُّوۡنَ ﴿۷۸﴾', 'اور بعض ان میں ان پڑھ ہیں کہ اپنی آرزؤں کے سوا اللہ کی کتاب سے واقف ہی نہیں اور وہ صرف اٹکل سے کام لیتے ہیں۔', 'اور بعض ان میں بے پڑھے ہیں کہ خبر نہیں رکھتے کتاب کی سوائے جھوٹی آرزوؤں کے اور انکے پاس کچھ نہیں مگر خیالات [۱۲۰]', 'And there are among them (Jews) unlettered people, who know not the Book, but they trust upon false desires and they but guess.', 'And some among them are illiterate who have no knowledge of the Book, but have some fancies and do nothing but conjecture.'),
(86, 2, 79, 9, 9, 1, 'الم', 'البقرۃ', 'فَوَیۡلٌ لِّلَّذِیۡنَ یَکۡتُبُوۡنَ الۡکِتٰبَ بِاَیۡدِیۡہِمۡ ٭ ثُمَّ یَقُوۡلُوۡنَ ہٰذَا مِنۡ عِنۡدِ اللّٰہِ  لِیَشۡتَرُوۡا بِہٖ ثَمَنًا قَلِیۡلًا ؕ فَوَیۡلٌ لَّہُمۡ  مِّمَّا کَتَبَتۡ اَیۡدِیۡہِمۡ وَ وَیۡلٌ لَّہُمۡ مِّمَّا یَکۡسِبُوۡنَ ﴿۷۹﴾', 'سوان لوگوں پر افسوس ہے جو اپنے ہاتھ سے کتاب لکھتے ہیں اور کہتے یہ ہیں کہ یہ اللہ کے پاس سے آئی ہے تاکہ اس کے عوض تھوڑی سی قیمت یعنی دنیوی منفعت حاصل کریں سو ان پر افسوس ہے اس لئے کہ بےاصل باتیں اپنے ہاتھ سے لکھتے ہیں اور پھر ان پر افسوس ہے اس لئے کہ ایسے کام کرتے ہیں۔', 'سو خرابی ہے ان کو جو لکھتے ہیں کتاب اپنے ہاتھ سے پھر کہہ دیتے ہیں یہ خدا کی طرف سے ہے تاکہ لیویں اس پر تھوڑا سا مول سو خرابی ہے ان کو اپنے ہاتھوں کے لکھے سے اور خرابی ہے ان کو اپنی اس کمائی سے [۱۲۱]', 'Then woe to those who write the Book with their own hands and then say, \"This is from Allah,\" to purchase with it a little price! Woe to them for what their hands have written and woe to them for that they earn thereby.', 'So, woe to those who write the Book with their hands and then say, “This is from Allah”, so that they may gain thereby a trifling price. Then, woe to them for what their hands have written, and woe to them for what they earn.'),
(87, 2, 80, 9, 9, 1, 'الم', 'البقرۃ', 'وَ قَالُوۡا لَنۡ تَمَسَّنَا النَّارُ اِلَّاۤ اَیَّامًا مَّعۡدُوۡدَۃً ؕ قُلۡ اَتَّخَذۡتُمۡ عِنۡدَ اللّٰہِ عَہۡدًا فَلَنۡ یُّخۡلِفَ اللّٰہُ عَہۡدَہٗۤ اَمۡ تَقُوۡلُوۡنَ عَلَی اللّٰہِ مَا لَا تَعۡلَمُوۡنَ ﴿۸۰﴾', 'اور کہتے ہیں کہ دوزخ کی آگ ہمیں چند روز کے سوا چھو ہی نہیں سکے گی۔ ان سے پوچھو کیا تم نے اللہ سے اقرار لے رکھا ہے کہ اللہ اپنے اقرار کے خلاف نہیں کرے گا نہیں یا تم اللہ کے بارے میں ایسی باتیں کہتے ہو جنکا تمہیں مطلق علم نہیں۔', 'اور کہتے ہیں ہم کو ہر گز آگ نہ لگے گی مگر چند روز گنے چنے [۱۲۲] کہدو کیا تم لے چکے ہو اللہ کے یہاں سے قرار کہ اب ہرگز خلاف نہ کرے گا اللہ اپنے قرار کے  یا جوڑتے ہو اللہ پر جو تم نہیں جانتے کیوں نہیں  [۱۲۳]', 'And they (Jews) say, \"The Fire (i.e. Hell-fire on the Day of Resurrection) shall not touch us but for a few numbered days.\" Say (O Muhammad Peace be upon him to them): \"Have you taken a covenant from Allah, so that Allah will not break His Covenant? Or is it that you say of Allah what you know not?\"', 'They say, “The fire shall not touch us for more than a few days.” Say, “Have you taken a pledge from Allah, and Allah will not go against His promise? Or, do you say about Allah what you do not know?”'),
(88, 2, 81, 9, 9, 1, 'الم', 'البقرۃ', 'بَلٰی مَنۡ کَسَبَ سَیِّئَۃً وَّ اَحَاطَتۡ بِہٖ خَطِیۡٓــَٔتُہٗ فَاُولٰٓئِکَ اَصۡحٰبُ النَّارِ ۚ ہُمۡ فِیۡہَا خٰلِدُوۡنَ ﴿۸۱﴾', 'ہاں کیوں نہیں جو برے کام کرے اور اس کے گناہ ہر طرف سے اس کو گھیر لیں تو ایسے لوگ دوزخ میں جانے والے ہیں اور وہ ہمیشہ اس میں جلتے رہیں گے۔', 'جس نے کمایا گناہ اور گھیر لیا اس کو اس کے گناہ نے [۱۲۴] سو وہی ہیں دوزخ کے رہنے والے وہ اسی میں ہمیشہ رہیں گے', 'Yes! Whosoever earns evil and his sin has surrounded him, they are dwellers of the Fire (i.e. Hell); they will dwell therein forever.', 'Why not? Those who commit evil and are besieged by their sins, those are people of the Fire - there they shall live forever.'),
(89, 2, 82, 9, 9, 1, 'الم', 'البقرۃ', 'وَ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ اُولٰٓئِکَ اَصۡحٰبُ الۡجَنَّۃِ ۚ ہُمۡ  فِیۡہَا خٰلِدُوۡنَ ﴿٪۸۲﴾', 'اور جو ایمان لائیں اور نیک کام کریں وہ جنت کے مالک ہوں گے اور ہمیشہ اس میں عیش کرتے رہیں گے۔', 'اور جو ایمان لائے اور عمل نیک کئے نیک وہی ہیں جنت کے رہنے والے وہ اسی میں ہمیشہ رہیں گے', 'And those who believe (in the Oneness of Allah - Islamic Monotheism) and do righteous good deeds, they are dwellers of Paradise, they will dwell therein forever.', 'As for those who believe, and do good deeds, they are the people of Paradise - there they will live forever.'),
(90, 2, 83, 10, 10, 1, 'الم', 'البقرۃ', 'وَ اِذۡ اَخَذۡنَا مِیۡثَاقَ بَنِیۡۤ اِسۡرَآءِیۡلَ لَا تَعۡبُدُوۡنَ اِلَّا اللّٰہَ ۟ وَ بِالۡوَالِدَیۡنِ اِحۡسَانًا وَّ ذِی ‌الۡقُرۡبٰی وَ الۡیَتٰمٰی وَ الۡمَسٰکِیۡنِ وَ قُوۡلُوۡا لِلنَّاسِ حُسۡنًا وَّ اَقِیۡمُوا الصَّلٰوۃَ وَ اٰتُوا الزَّکٰوۃَ ؕ ثُمَّ تَوَلَّیۡتُمۡ  اِلَّا قَلِیۡلًا مِّنۡکُمۡ وَ اَنۡتُمۡ مُّعۡرِضُوۡنَ ﴿۸۳﴾', 'اور جب ہم نے بنی اسرائیل سے عہد لیا کہ اللہ کے سوا کسی کی عبادت نہ کرنا اور ماں باپ اور رشتہ داروں اور یتیموں اور محتاجوں کے ساتھ بھلائی کرتے رہنا اور لوگوں سے اچھی باتیں کہنا اور نماز پڑھتے اور زکوٰۃ دیتے رہنا۔ تو چند آدمیوں کے سوا تم سب اس عہد سے منہ پھیر کر پلٹ گئے۔', 'اور جب ہم نے لیا قرار بنی اسرائیل سے کہ عبادت نہ کرنا مگر اللہ کی اور ماں باپ سے سلوک نیک کرنا اور کنبہ والوں سے اور یتیموں اور محتاجوں سے او رکہیو سب لوگوں سے نیک بات اور قائم رکھیو نماز اور دیتے رکھیو زکوٰۃ پھر تم پھر گئے مگر تھوڑے سے تم میں اور تم ہو ہی پھرنے والے [۱۲۵]', 'And (remember) when We took a covenant from the Children of Israel, (saying): Worship none but Allah (Alone) and be dutiful and good to parents, and to kindred, and to orphans and Al-Masakeen (the poor), (Tafsir At-Tabaree, Vol. 10, Page 158 (Verse 9:60)) and speak good to people (i.e. enjoin righteousness and forbid evil, and say the truth about Muhammad Peace be upon him ), and perform As-Salat (Iqamat-as-Salat), and give Zakat. Then you slid back, except a few of you, while you are backsliders. (Tafsir Al-Qurtubee, Vol. 2, Page 392).', '(Remember) when We took a pledge from the children of Isrā’īl (Israel): “You shall not worship anyone other than Allah; and you shall do good to the parents, and to near of kin, and to orphans and the needy. And say to the people what is good, and be steadfast in Salāh (prayer), and pay Zakāh .” Then, you went back (on your word), all but a few among you, and you are used to turning away.'),
(91, 2, 84, 10, 10, 1, 'الم', 'البقرۃ', 'وَ اِذۡ  اَخَذۡنَا مِیۡثَاقَکُمۡ لَا تَسۡفِکُوۡنَ دِمَآءَکُمۡ وَ لَا تُخۡرِجُوۡنَ اَنۡفُسَکُمۡ مِّنۡ دِیَارِکُمۡ ثُمَّ  اَقۡرَرۡتُمۡ  وَ اَنۡتُمۡ تَشۡہَدُوۡنَ ﴿۸۴﴾', 'اور جب ہم نے تم سے عہد لیا کہ آپس میں کشت و خون نہ کرنا اور اپنے کو ان کے وطن سے نہ نکالنا تو تم نے اقرار کر لیا اور تم اس بات کو مانتے بھی ہو۔', 'اور جب لیا ہم نے وعدہ تمہارا کہ نہ کرو گے خون آپس میں اور نہ نکال دو گے اپنوں کو اپنے وطن سے پھر تم نے اقرار کر لیا اور تم مانتے ہو [۱۲۶]', 'And (remember) when We took your covenant (saying): Shed not the blood of your people, nor turn out your own people from their dwellings. Then, (this) you ratified and (to this) you bear witness.', 'When We took a pledge from you: “You shall not shed the blood of one another, and you shall not drive one another out of your homes.” Then you agreed, being yourselves the witnesses.'),
(92, 2, 85, 10, 10, 1, 'الم', 'البقرۃ', 'ثُمَّ  اَنۡتُمۡ  ہٰۤـؤُلَآءِ تَقۡتُلُوۡنَ اَنۡفُسَکُمۡ  وَ تُخۡرِجُوۡنَ فَرِیۡقًا مِّنۡکُمۡ مِّنۡ دِیَارِہِمۡ ۫ تَظٰہَرُوۡنَ عَلَیۡہِمۡ بِالۡاِثۡمِ وَ الۡعُدۡوَانِ ؕ وَ اِنۡ یَّاۡتُوۡکُمۡ اُسٰرٰی تُفٰدُوۡہُمۡ  وَ ہُوَ مُحَرَّمٌ عَلَیۡکُمۡ اِخۡرَاجُہُمۡ  ؕ اَفَتُؤۡمِنُوۡنَ بِبَعۡضِ الۡکِتٰبِ وَ تَکۡفُرُوۡنَ بِبَعۡضٍ ۚ فَمَا جَزَآءُ  مَنۡ یَّفۡعَلُ ذٰلِکَ مِنۡکُمۡ اِلَّا خِزۡیٌ فِی الۡحَیٰوۃِ الدُّنۡیَا ۚ وَ یَوۡمَ الۡقِیٰمَۃِ یُرَدُّوۡنَ اِلٰۤی اَشَدِّ الۡعَذَابِ ؕ وَ مَا اللّٰہُ بِغَافِلٍ عَمَّا تَعۡمَلُوۡنَ ﴿۸۵﴾', 'پھر تم وہی ہو کہ اپنوں کو قتل بھی کردیتے ہو اور اپنے میں سے بعض لوگوں پر گناہ اور ظلم سے چڑھائی کر کے انہیں وطن سے نکال بھی دیتے ہو اور اگر وہ تمہارے پاس قید ہو کر آئیں تو بدلہ دے کر ان کو چھڑا بھی لیتے ہو حالانکہ ان کا نکال دینا ہی تم کو حرام تھا یہ کیا بات ہے کہ تم کتاب اللہ کے بعض احکام کو تو مانتے ہو اور بعض سے انکار کئے دیتے ہو تو جو تم میں سے ایسی حرکت کریں ان کی سزا اس کے سوا اور کیا ہو سکتی ہے کہ دنیا کی زندگی میں تو رسوائی ہو اور قیامت کے دن سخت سے سخت عذاب میں ڈال دئیے جائیں اور جو کام تم کرتے ہو اللہ ان سے غافل نہیں۔', 'پھر تم وہ لوگ ہو کہ ایسے ہی خون کرتے ہو آپس میں اور نکال دیتے ہو اپنے ایک فرقہ کو ان کے وطن سے چڑھائی کرتے ہو ان پر گناہ اور ظلم سے [۱۲۷] اور اگر وہی آویں تمہارے پاس کسی کے قیدی ہو کر تو ان کا بدلا دیکر چھڑاتے ہو حالانکہ حرام ہے تم پر انکا نکال دینا بھی تو کیا مانتے ہو بعض کتاب کو اور نہیں مانتے بعض کو [۱۲۸] سو کوئی سزا نہیں اس  کی جو تم میں یہ کام کرتا ہے مگر رسوائی دنیا کی زندگی میں اور قیامت کے دن پہنچائے جاویں سخت سےسخت عذاب میں اور اللہ بے خبر نہیں تمہارے کاموں سے [۱۲۹]', 'After this, it is you who kill one another and drive out a party of you from their homes, assist (their enemies) against them, in sin and transgression. And if they come to you as captives, you ransom them, although their expulsion was forbidden to you. Then do you believe in a part of the Scripture and reject the rest? Then what is the recompense of those who do so among you, except disgrace in the life of this world, and on the Day of Resurrection they shall be consigned to the most grievous torment. And Allah is not unaware of what you do.', 'Yet, here you are, killing one another, and driving a group of your own people out of their homes, supporting each other against them in sin and aggression - and if they come to you as prisoners, you would ransom them, while their very expulsion was unlawful for you! Do you, then, believe in some parts of the Book, and disbelieve in others? So, what can be the punishment of those among you who do that, except disgrace in present life? And, on the Day of Judgement, they shall be turned to the most severe punishment. And Allah is not unaware of what you do.'),
(93, 2, 86, 10, 10, 1, 'الم', 'البقرۃ', 'اُولٰٓئِکَ الَّذِیۡنَ اشۡتَرَوُا الۡحَیٰوۃَ الدُّنۡیَا بِالۡاٰخِرَۃِ ۫ فَلَا یُخَفَّفُ عَنۡہُمُ الۡعَذَابُ وَ لَا ہُمۡ یُنۡصَرُوۡنَ ﴿٪۸۶﴾', 'یہ وہ لوگ ہیں جنہوں نے آخرت کے بدلے دنیا کی زندگی خریدی۔ سو نہ تو ان سے عذاب ہی ہلکا کیا جائے گا اور نہ ان کو اور طرح کی مدد ملے گی۔', 'یہ وہی ہیں جنہوں نے مول لی دنیا کی زندگی آخرت کے بدلے سو نہ ہلکا ہو گا ان  پر عذاب اور نہ ان کو مدد پہنچے گی [۱۳۰]', 'Those are they who have bought the life of this world at the price of the Hereafter. Their torment shall not be lightened nor shall they be helped.', 'Those are the ones who bought the worldly life at the cost of the Hereafter. So, punishment shall not be lightened for them, nor shall they be helped.'),
(94, 2, 87, 11, 11, 1, 'الم', 'البقرۃ', 'وَ لَقَدۡ اٰتَیۡنَا مُوۡسَی الۡکِتٰبَ وَ قَفَّیۡنَا مِنۡۢ بَعۡدِہٖ بِالرُّسُلِ ۫ وَ اٰتَیۡنَا عِیۡسَی ابۡنَ مَرۡیَمَ الۡبَیِّنٰتِ وَ اَیَّدۡنٰہُ بِرُوۡحِ الۡقُدُسِ ؕ اَفَکُلَّمَا جَآءَکُمۡ رَسُوۡلٌۢ بِمَا لَا تَہۡوٰۤی اَنۡفُسُکُمُ اسۡتَکۡبَرۡتُمۡ ۚ  فَفَرِیۡقًا کَذَّبۡتُمۡ  ۫ وَ فَرِیۡقًا تَقۡتُلُوۡنَ ﴿۸۷﴾', 'اور ہم نے موسٰی کو کتاب عنایت کی اور ان کے پیچھے یکے بعد دیگرے پیغمبر بھیجتے رہے اور عیسٰی ابن مریم کو کھلے نشانات بخشے اور روح القدس یعنی جبرائیل سے انکو مدد دی۔ تو کیا ایسا ہے کہ جب کوئی پیغمبر تمہارے پاس ایسی باتیں لے کر آئے جنکو تمہارا جی نہیں چاہتا تھا تو تم سر کش ہو جاتے رہے اور ایک گروہ انبیاء کو تو جھٹلاتے رہے اور ایک گروہ کو قتل کرتے رہے۔', 'اور بیشک دی ہم نےموسٰی کو کتاب اور پے درپے بھیجے اس کے پیچھے رسول اور دئے ہم نے عیسیٰ مریم کے بیٹے کو معجزے صریح اور قوت دی اس کو روح پاک سے [۱۳۱] پھر بھلا کیا جب پاس لایا کوئی رسول وہ حکم جو نہ بھایا تمہارے جی کو تو تم تکبر کرنے لگے پھر ایک جماعت کو جھٹلایا [۱۳۲] اور ایک جماعت کو تم نے قتل کر دیا [۱۳۳]', 'And indeed, We gave Moosa (Moses) the Book and followed him up with a succession of Messengers. And We gave Iesa (Jesus), the son of Maryam (Mary), clear signs and supported him with Rooh-ul-Qudus (Jibrael (Gabriel) ). Is it that whenever there came to you a Messenger with what you yourselves desired not, you grew arrogant? Some, you disbelieved and some, you killed.', 'Indeed, We gave Mūsā the Book, and after him We sent messengers, one following the other; and We gave clear signs to ‘Īsā, the son of Maryam (Jesus, the son of Mary), and supported him with the Holy Spirit. Then, how is it that every time a prophet came to you with what does not meet your desires, you grew arrogant? So, you gave the lie to a group (of the messengers) and killed others.'),
(95, 2, 88, 11, 11, 1, 'الم', 'البقرۃ', 'وَ قَالُوۡا قُلُوۡبُنَا غُلۡفٌ ؕ بَلۡ لَّعَنَہُمُ اللّٰہُ بِکُفۡرِہِمۡ  فَقَلِیۡلًا مَّا یُؤۡمِنُوۡنَ ﴿۸۸﴾', 'اور کہتے ہیں ہمارے دلوں پر پردے ہیں نہیں بلکہ اللہ نے ان کے کفر کے سبب ان پر لعنت کر رکھی ہے پس یہ تھوڑے ہی پر ایمان لاتے ہیں۔', 'اور کہتے ہیں ہمارے دلوں پر غلاف ہے بلکہ لعنت کی ہے اللہ نے انکے کفر کے سبب سو بہت کم ایمان لاتے ہیں [۱۳۴]', 'And they say, \"Our hearts are wrapped (i.e. do not hear or understand Allahs Word).\" Nay, Allah has cursed them for their disbelief, so little is that which they believe.', 'And they said, “Our hearts are veiled.” Rather, Allah has cast damnation upon them for their disbelief. So, they believe just in very little things'),
(96, 2, 89, 11, 11, 1, 'الم', 'البقرۃ', 'وَ لَمَّا جَآءَہُمۡ کِتٰبٌ مِّنۡ عِنۡدِ اللّٰہِ مُصَدِّقٌ لِّمَا مَعَہُمۡ  ۙ وَ کَانُوۡا مِنۡ قَبۡلُ یَسۡتَفۡتِحُوۡنَ عَلَی الَّذِیۡنَ کَفَرُوۡا ۚۖ فَلَمَّا جَآءَہُمۡ مَّا عَرَفُوۡا کَفَرُوۡا بِہٖ ۫ فَلَعۡنَۃُ اللّٰہِ عَلَی الۡکٰفِرِیۡنَ ﴿۸۹﴾', 'اور جب اللہ کے ہاں سے ان کے پاس کتاب آئی جو ان کی آسمانی کتاب کی بھی تصدیق کرتی ہے۔ اور وہ پہلے ہمیشہ کافروں پر فتح مانگا کرتے تھے۔ پھر جس چیز کو وہ خوب پہچانتے تھے جب ان کے پاس آ پہنچی تو اس سے منکر ہو گئے پس کافروں پر اللہ کی لعنت۔', 'اور جب پہنچی انکے پاس کتاب اللہ کی طرف سے جو سچا بتاتی ہے اس کتاب کو جو انکے پاس ہے اور پہلے سے فتح مانگتے تھے کافروں پر پھر جب پہنچا ان کو جسکو  پہچان رکھا تھا تو اس سے منکر ہو گئے سو لعنت ہے اللہ کی منکروں پر [۱۳۵]', 'And when there came to them (the Jews), a Book (this Quran) from Allah confirming what is with them (the Taurat (Torah) and the Injeel (Gospel)), although aforetime they had invoked Allah (for coming of Muhammad Peace be upon him ) in order to gain victory over those who disbelieved, then when there came to them that which they had recognised, they disbelieved in it. So let the Curse of Allah be on the disbelievers.', 'And when there came to them a Book from Allah, which confirms what was with them,- while earlier, they used to seek help against those who disbelieved, - yet when there came to them that which they did recognize, they denied it. So the curse of Allah is upon the disbelievers.'),
(97, 2, 90, 11, 11, 1, 'الم', 'البقرۃ', 'بِئۡسَمَا اشۡتَرَوۡا بِہٖۤ اَنۡفُسَہُمۡ  اَنۡ یَّکۡفُرُوۡا بِمَاۤ  اَنۡزَلَ اللّٰہُ  بَغۡیًا اَنۡ یُّنَزِّلَ اللّٰہُ مِنۡ فَضۡلِہٖ عَلٰی مَنۡ یَّشَآءُ مِنۡ عِبَادِہٖ ۚ فَبَآءُوۡ بِغَضَبٍ عَلٰی غَضَبٍ ؕ وَ  لِلۡکٰفِرِیۡنَ عَذَابٌ مُّہِیۡنٌ ﴿۹۰﴾', 'جس چیز کے بدلے انہوں نے اپنے تئیں بیچ ڈالا وہ بہت بری ہے یعنی اس جلن سے کہ اللہ اپنے بندوں میں سے جس پر چاہتا ہے اپنی مہربانی سے نازل فرماتا ہے اللہ کی نازل کی ہوئی کتاب سے کفر کرنے لگے تو وہ اس کے غضب بالائے غضب میں مبتلا ہو گئے اور کافروں کے لئے ذلیل کرنے والا عذاب ہے۔', 'بری چیز ہے وہ جسکے بدلے بیچا انہوں نے اپنے آپکو کہ منکر ہوئے اس چیز کے جو اتاری اللہ نے اس ضد پر کہ اتارے اللہ اپنے فضل سے جس پر چاہے اپنے بندوں میں سے [۱۳۶] سو کما لائے غصہ پر غصہ [۱۳۷] اور کافروں کے واسطے عذاب ہے ذلت کا [۱۳۸]', 'How bad is that for which they have sold their ownselves, that they should disbelieve in that which Allah has revealed (the Quran), grudging that Allah should reveal of His Grace unto whom He will of His slaves. So they have drawn on themselves wrath upon wrath. And for the disbelievers, there is disgracing torment.', 'Vile is that for which they have sold out their selves: that they should deny what Allah has revealed, grudging that Allah should send down some of His bounty to whomsoever He wills from among His servants. So, they came out with wrath upon wrath. And for the unbelievers, there is humiliating punishment.'),
(98, 2, 91, 11, 11, 1, 'الم', 'البقرۃ', 'وَ اِذَا قِیۡلَ لَہُمۡ  اٰمِنُوۡا بِمَاۤ اَنۡزَلَ اللّٰہُ قَالُوۡا نُؤۡمِنُ بِمَاۤ  اُنۡزِلَ عَلَیۡنَا وَ یَکۡفُرُوۡنَ بِمَا وَرَآءَہٗ ٭ وَ ہُوَ الۡحَقُّ مُصَدِّقًا لِّمَا مَعَہُمۡ  ؕ قُلۡ فَلِمَ تَقۡتُلُوۡنَ اَنۡۢبِیَآءَ اللّٰہِ مِنۡ قَبۡلُ اِنۡ کُنۡتُمۡ مُّؤۡمِنِیۡنَ ﴿۹۱﴾', 'اور جب ان سے کہا جاتا ہے کہ جو کتاب اللہ نے اب نازل فرمائی ہے اس کو مانو تو کہتے ہیں کہ جو کتاب ہم پر پہلے نازل ہو چکی ہے ہم تو اسی کو مانتے ہیں یعنی یہ اس کے سوا اور کتاب کو نہیں مانتے حالانکہ وہ سرا سر سچّی ہے اور جو ان کی آسمانی کتاب ہے اس کی بھی تصدیق کرتی ہے ان سے کہہ دو کہ اگر تم صاحب ایمان ہوتے تو اللہ کے پیغمبروں کو پہلے ہی کیوں قتل کیا کرتے تھے۔', 'اور جب کہا جاتا ہے ان سے مانو اس کو جو اللہ نے بھیجا ہے تو کہتے ہیں ہم مانتے ہیں جو اترا ہے ہم پر اور نہیں مانتے اس کو جو سوا اس کے ہے حالانکہ وہ کتاب سچی ہے تصدیق کرتی ہے اس کتاب کی جو انکے پاس ہے [۱۳۹] کہدو پھر کیوں قتل کرتے رہے ہو اللہ کے پیغمبروں کو پہلے سے اگر تم ایمان رکھتے تھے [۱۴۰]', 'And when it is said to them (the Jews), \"Believe in what Allah has sent down,\" they say, \"We believe in what was sent down to us.\" And they disbelieve in that which came after it, while it is the truth confirming what is with them. Say (O Muhammad Peace be upon him to them): \"Why then have you killed the Prophets of Allah aforetime, if you indeed have been believers?\"', 'When it is said to them, “Believe in what Allah has revealed,” they say, “We believe in what has been revealed to us” - and they deny what is beyond it, whereas that is the truth which confirms what is with them. Say, “Why then have you been slaying the prophets of Allah earlier, if you were believers?”'),
(99, 2, 92, 11, 11, 1, 'الم', 'البقرۃ', 'وَ لَقَدۡ جَآءَکُمۡ مُّوۡسٰی بِالۡبَیِّنٰتِ ثُمَّ اتَّخَذۡتُمُ الۡعِجۡلَ مِنۡۢ بَعۡدِہٖ وَ اَنۡتُمۡ ظٰلِمُوۡنَ ﴿۹۲﴾', 'اور موسٰی تمہارے پاس کھلے ہوئے معجزات لے کر آئے پھر تم ان کے کوہ طور پر جانے کے بعد بچھڑے کو معبود بنا بیٹھے اور تم اپنے ہی حق میں ظلم کرتے تھے۔', 'اور آچکا تمہارے پاس موسٰی صریح معجزے لیکر  پھر بنا لیا تم نے بچھڑا اس کے گئے پیچھے اور تم ظالم ہو [۱۴۱]', 'And indeed Moosa (Moses) came to you with clear proofs, yet you worshipped the calf after he left, and you were Zalimoon (polytheists and wrong-doers).', 'And certainly Mūsā came to you with clear signs, then you adopted the calf (as god) after his departure (to the mount of Tūr) - and you were transgressors.'),
(100, 2, 93, 11, 11, 1, 'الم', 'البقرۃ', 'وَ اِذۡ اَخَذۡنَا مِیۡثَاقَکُمۡ وَ رَفَعۡنَا فَوۡقَکُمُ الطُّوۡرَ ؕ خُذُوۡا مَاۤ اٰتَیۡنٰکُمۡ بِقُوَّۃٍ وَّ اسۡمَعُوۡا ؕ قَالُوۡا سَمِعۡنَا وَ عَصَیۡنَا ٭ وَ اُشۡرِبُوۡا فِیۡ قُلُوۡبِہِمُ الۡعِجۡلَ بِکُفۡرِہِمۡ ؕ قُلۡ بِئۡسَمَا یَاۡمُرُکُمۡ بِہٖۤ  اِیۡمَانُکُمۡ   اِنۡ  کُنۡتُمۡ مُّؤۡمِنِیۡنَ ﴿۹۳﴾', 'اور جب ہم نے تم لوگوں سے پختہ عہد لیا اور کوہ طور کو تم پر اٹھا کھڑا کیا اور حکم دیا کہ جو کتاب ہم نے تم کو دی ہے اس کو زور سے پکڑو اور جو تمہیں حکم ہوتا ہے اس کو سنو تو وہ جو تمہارے بڑے تھے کہنے لگے کہ ہم نے سن تو لیا لیکن مانتے نہیں اور ان کے کفر کے سبب بچھڑا گویا ان کے دلوں میں رچ گیا تھا اے پیغمبر ان سے کہہ دو کہ اگر تم مومن ہو تو تمہارا ایمان تم کو بری بات بتاتا ہے۔', 'اور جب ہم نے لیا قرار تمہارا اور بلند کیا تمہارے اوپر کوہ طور کو پکڑو جو ہم نے تم کو دیا زور سے اور سنو بولے سنا ہم نے اور نہ مانا اور پلائی گئ انکے دلوں میں محبت اسی بچھڑے کی بسبب انکے کفر کے [۱۴۲] کہدے کہ بری باتیں سکھاتا ہے تم کو ایمان تمہارا اگر تم ایمان والے ہو', 'And (remember) when We took your covenant and We raised above you the Mount (saying), \"Hold firmly to what We have given you and hear (Our Word). They said, \"We have heard and disobeyed.\" And their hearts absorbed (the worship of) the calf because of their disbelief. Say: \"Worst indeed is that which your faith enjoins on you if you are believers.\"', 'And when We took a pledge from you, and raised high the (mount of) Tūr above you: “Hold fast to what We have given you, and listen”! They said, “We have heard and disobeyed.” And, on account of their denial, they were soaked with love for the calf in their hearts. Say: “Evil is that which your faith enjoins upon you, if you are believers.”'),
(101, 2, 94, 11, 11, 1, 'الم', 'البقرۃ', 'قُلۡ  اِنۡ کَانَتۡ لَکُمُ الدَّارُ الۡاٰخِرَۃُ عِنۡدَ اللّٰہِ خَالِصَۃً مِّنۡ دُوۡنِ النَّاسِ فَتَمَنَّوُا الۡمَوۡتَ اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ ﴿۹۴﴾', 'کہہ دو کہ اگر آخرت کا گھر اور لوگوں یعنی مسلمانوں کیلئے نہیں اور اللہ کے نزدیک تمہارے ہی لئے مخصوص ہے تو اگر سچّے ہو تو موت کی آرزو تو کرو۔', 'کہدے کہ اگر ہے تمہارے واسطے آخرت کا گھر اللہ کے ہاں تنہا سوا اور لوگوں کے تو تم مرنے کی آرزو کرو اگر تم سچ کہتے ہو [۱۴۳]', 'Say to (them): \"If the home of the Hereafter with Allah is indeed for you specially and not for others, of mankind, then long for death if you are truthful.\"', 'Say: “If the Last Abode near Allah is purely for you, to the exclusion of all people, then make a wish for death, if you are true.”'),
(102, 2, 95, 11, 11, 1, 'الم', 'البقرۃ', 'وَ لَنۡ یَّتَمَنَّوۡہُ اَبَدًۢا بِمَا قَدَّمَتۡ اَیۡدِیۡہِمۡ ؕ وَ اللّٰہُ عَلِیۡمٌۢ بِالظّٰلِمِیۡنَ ﴿۹۵﴾', 'اور ان اعمال کی وجہ سے جو ان کے ہاتھ آگے بھیج چکے ہیں یہ کبھی اس کی آرزو نہیں کریں گے اور اللہ ظالموں سے خوب واقف ہے۔', 'اور ہر گز آرزو نہ کریں گے موت کی کبھی بسبب ان گناہوں کے کہ بھیج چکے ہیں انکے ہاتھ اور اللہ خوب جانتا ہے گنہگاروں کو', 'But they will never long for it because of what their hands have sent before them (i.e. what they have done). And Allah is All-Aware of the Zalimoon (polytheists and wrong-doers).', 'But they will never wish for it because of what their hands have sent ahead. Allah is All-Aware of the unjust.'),
(103, 2, 96, 11, 11, 1, 'الم', 'البقرۃ', 'وَ لَتَجِدَنَّہُمۡ اَحۡرَصَ النَّاسِ عَلٰی حَیٰوۃٍ  ۚۛ وَ مِنَ الَّذِیۡنَ اَشۡرَکُوۡا  ۚۛ یَوَدُّ  اَحَدُہُمۡ لَوۡ یُعَمَّرُ اَلۡفَ سَنَۃٍ ۚ وَ مَا ہُوَ بِمُزَحۡزِحِہٖ مِنَ الۡعَذَابِ اَنۡ یُّعَمَّرَ ؕ وَ اللّٰہُ  بَصِیۡرٌۢ بِمَا یَعۡمَلُوۡنَ ﴿٪۹۶﴾', 'اور ان کو تم اور لوگوں سے زیادہ زندگی کے حریص دیکھو گے یہاں تک کے مشرکوں سے بھی بڑھ کر۔ ان میں سے ہر ایک یہی خواہش کرتا ہے کہ کاش وہ ہزار برس جیتا رہے مگر اتنی لمبی عمر اس کو مل بھی جائے تو اسے عذاب سے تو نہیں چھڑا سکتی اور جو کام یہ کرتے ہیں اللہ ان کو دیکھ رہا ہے۔', 'اور تو دیکھے گا ان کو سب لوگوں سے زیادہ حریص زندگی پر اور زیادہ حریص مشرکوں سے بھی چاہتا ہے ایک ایک ان میں کا کہ عمر پاوے ہزار برس اور نہیں اس کو بچانے والا عذاب سے اس قدر جینا اور اللہ دیکھتا ہے جو کچھ وہ کرتے ہیں [۱۴۴]', 'And verily, you will find them (the Jews) the greediest of mankind for life and (even greedier) than those who - ascribe partners to Allah (and do not believe in Resurrection - Magians, pagans, and idolaters, etc.). Everyone of them wishes that he could be given a life of a thousand years. But the grant of such life will not save him even a little from (due) punishment. And Allah is All-Seer of what they do.', 'You shall surely find them the more avid, for life than all other men - even more than the polytheists. Every one of them would love that his life is prolonged for one thousand years. But it will not take him away from punishment that his life is (so) prolonged, and Allah is watchful of what they do.'),
(104, 2, 97, 12, 12, 1, 'الم', 'البقرۃ', 'قُلۡ مَنۡ کَانَ عَدُوًّا لِّجِبۡرِیۡلَ فَاِنَّہٗ نَزَّلَہٗ عَلٰی قَلۡبِکَ بِاِذۡنِ اللّٰہِ مُصَدِّقًا لِّمَا بَیۡنَ یَدَیۡہِ وَ ہُدًی وَّ بُشۡرٰی لِلۡمُؤۡمِنِیۡنَ ﴿۹۷﴾', 'کہہ دو کہ جو شخص جبرائیل کا دشمن ہو اس کو غصے میں مر جانا چاہیے کیونکہ اس نے تو یہ کتاب اللہ کے حکم سے تمہارے دل پر نازل کی ہے جو  پہلی کتابوں کی تصدیق کرتی ہے اور ایمان والوں کے لئے ہدایت اور بشارت ہے۔', 'تو کہدے جو کوئی ہووے دشمن جبریل کا سو اس نے تو اتارا ہے یہ کلام تیرے دل پر اللہ کے حکم سے کہ سچا بتانے والا ہے اس کلام کو جو اسکے پہلے ہے اور  راہ دکھاتا ہے اور خوش خبری سناتا ہے ایمان والوں کو', 'Say (O Muhammad Peace be upon him ): \"Whoever is an enemy to Jibrael (Gabriel) (let him die in his fury), for indeed he has brought it (this Quran) down to your heart by Allahs Permission, confirming what came before it (i.e. the Taurat (Torah) and the Injeel (Gospel)) and guidance and glad tidings for the believers.', 'Say, if someone is an enemy to Jibra’īl (Gabriel) (it can by no means degrade him for) it is he who has brought it (the Qur’ān) down upon your heart by the permission of Allah, confirming what has been before it, and a guidance and good tidings to the believers.'),
(105, 2, 98, 12, 12, 1, 'الم', 'البقرۃ', 'مَنۡ کَانَ عَدُوًّا  لِّلّٰہِ وَ مَلٰٓئِکَتِہٖ وَ رُسُلِہٖ وَ جِبۡرِیۡلَ وَ مِیۡکٰىلَ فَاِنَّ اللّٰہَ عَدُوٌّ  لِّلۡکٰفِرِیۡنَ ﴿۹۸﴾', 'جو شخص اللہ کا اور اس کے فرشتوں کا اور اس کے پیغمبروں کا اور جبرائیل اور میکا ئیل کا دشمن ہو تو ایسے کافروں کا اللہ دشمن ہے۔', 'جو کوئی ہووے دشمن اللہ کا اور اسکے فرشتوں کا اور اسکے پیغمبروں کا اور جبریل اور میکائیل کا تو اللہ دشمن ہے ان کافروں کا [۱۴۵]', '\"Whoever is an enemy to Allah, His Angels, His Messengers, Jibrael (Gabriel) and Mikael (Michael), then verily, Allah is an enemy to the disbelievers.\"', 'If someone is an enemy to Allah, His angels, and His messengers, and to Jibra’īl (Gabriel) and Mīka’īl (Michael), then Allah is enemy to the disbelievers.'),
(106, 2, 99, 12, 12, 1, 'الم', 'البقرۃ', 'وَ لَقَدۡ اَنۡزَلۡنَاۤ اِلَیۡکَ اٰیٰتٍۭ بَیِّنٰتٍ ۚ وَ مَا یَکۡفُرُ بِہَاۤ  اِلَّا الۡفٰسِقُوۡنَ ﴿۹۹﴾', 'اور ہم نے تمہارے پاس سلجھی ہوئی آیتیں ارسال فرمائی ہیں اور ان سے انکار وہی کرتے ہیں جو بدکردار ہیں۔', 'اور ہم نے اتاریں تیری طرف آیتیں روشن اور انکار نہ کریں گے ان کا مگر  وہی جو نافرمان ہیں', 'And indeed We have sent down to you manifest Ayat (these Verses of the Quran which inform in detail about the news of the Jews and their secret intentions, etc.), and none disbelieve in them but Fasiqoon (those who rebel against Allahs Command).', 'And certainly We have revealed to you clear signs. And no one denies them except the sinful.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(107, 2, 100, 12, 12, 1, 'الم', 'البقرۃ', 'اَوَ کُلَّمَا عٰہَدُوۡا عَہۡدًا نَّبَذَہٗ فَرِیۡقٌ مِّنۡہُمۡ ؕ بَلۡ اَکۡثَرُہُمۡ  لَا یُؤۡمِنُوۡنَ ﴿۱۰۰﴾', 'ان لوگوں نے جب جب اللہ سے کوئی عہد کیا تو ان میں سے ایک فریق نے اس کو کسی چیز کی طرح پھینک دیا۔ حقیقت یہ ہے کہ ان میں اکثر بے ایمان ہیں۔', 'کیا جب کبھی باندھیں گے کوئی قرار تو پھینک دے گی اس کو ایک جماعت ان میں سے بلکہ ان میں اکثر یقین نہیں کرتے [۱۴۶]', 'Is it not (the case) that every time they make a covenant, some party among them throw it aside? Nay! the truth is most of them believe not.', 'Would it always be that every time they enter into a pact, a group from among them should throw it aside? In fact, most of them do not believe.'),
(108, 2, 101, 12, 12, 1, 'الم', 'البقرۃ', 'وَ لَمَّا جَآءَہُمۡ  رَسُوۡلٌ مِّنۡ عِنۡدِ اللّٰہِ مُصَدِّقٌ لِّمَا مَعَہُمۡ نَبَذَ فَرِیۡقٌ مِّنَ الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ ٭ۙ کِتٰبَ اللّٰہِ وَرَآءَ  ظُہُوۡرِہِمۡ کَاَنَّہُمۡ لَا  یَعۡلَمُوۡنَ ﴿۱۰۱﴾۫', 'اور جب ان کے پاس اللہ کی طرف سے پیغمبر آخرالزمان آئے اور وہ ان کی آسمانی کتاب کی تصدیق بھی کرتے ہیں تو جن لوگوں کو کتاب دی گئ تھی ان میں سے ایک جماعت نے اللہ کی کتاب کو پیٹھ پیچھے پھینک دیا گویا وہ جانتے ہی نہیں۔', 'اور جب پہنچا انکے پاس رسول اللہ کی طرف سے تصدیق کرنے والا اس کتاب کی جو انکے پاس ہے تو پھینک دیا ایک جماعت نے اہل کتاب سے کتاب اللہ کو اپنی پیٹھ کے پیچھے گویا کہ وہ جانتے ہی نہیں [۱۴۷]', 'And when there came to them a Messenger from Allah (i.e. Muhammad Peace be upon him ) confirming what was with them, a party of those who were given the Scripture threw away the Book of Allah behind their backs as if they did not know!', 'And when a messenger from Allah came to them, confirming what was already with them, some from among the people of the Book threw the Book of Allah behind their backs, as if they did not know.'),
(109, 2, 102, 12, 12, 1, 'الم', 'البقرۃ', 'وَ اتَّبَعُوۡا مَا تَتۡلُوا الشَّیٰطِیۡنُ عَلٰی مُلۡکِ سُلَیۡمٰنَ ۚ وَ مَا کَفَرَ سُلَیۡمٰنُ وَ لٰکِنَّ الشَّیٰطِیۡنَ کَفَرُوۡا یُعَلِّمُوۡنَ النَّاسَ السِّحۡرَ ٭ وَ مَاۤ اُنۡزِلَ عَلَی الۡمَلَکَیۡنِ بِبَابِلَ ہَارُوۡتَ  وَ مَارُوۡتَ ؕ وَ مَا یُعَلِّمٰنِ مِنۡ اَحَدٍ حَتّٰی یَقُوۡلَاۤ اِنَّمَا نَحۡنُ فِتۡنَۃٌ فَلَا تَکۡفُرۡ ؕ فَیَتَعَلَّمُوۡنَ مِنۡہُمَا مَا یُفَرِّقُوۡنَ بِہٖ بَیۡنَ الۡمَرۡءِ  وَ زَوۡجِہٖ ؕ وَ مَا ہُمۡ  بِضَآرِّیۡنَ بِہٖ مِنۡ اَحَدٍ  اِلَّا بِاِذۡنِ اللّٰہِ ؕ وَ یَتَعَلَّمُوۡنَ مَا یَضُرُّہُمۡ  وَ لَا یَنۡفَعُہُمۡ  ؕ وَ لَقَدۡ عَلِمُوۡا لَمَنِ اشۡتَرٰىہُ مَا لَہٗ فِی الۡاٰخِرَۃِ مِنۡ خَلَاقٍ ۟ؕ وَ لَبِئۡسَ مَا شَرَوۡا بِہٖۤ  اَنۡفُسَہُمۡ  ؕ لَوۡ کَانُوۡا یَعۡلَمُوۡنَ ﴿۱۰۲﴾', 'اور ان چیزوں کے پیچھے لگ گئے جو سلیمان کے عہد سلطنت میں شیاطین پڑھا کرتے تھے اور سلیمان نے مطلق کفر کی بات نہیں کی بلکہ شیطان ہی کفر کرتے تھے کہ لوگوں کو جادو سکھاتے تھے اور وہ یعنی بنی اسرائیل ان باتوں کے بھی پیچھے لگ گئے جو شہر بابل میں دو فرشتوں یعنی ہاروت اور ماروت پر اتری تھیں۔ اور وہ دونوں کسی کو کچھ نہیں سکھاتے تھے جب تک یہ نہ کہہ دیتے کہ ہم تو ذریعہ آزمائش ہیں۔ تم کفر میں نہ پڑھو۔ غرض لوگ ان سے وہ چیز سیکھتے جس سے میاں بیوی میں جدائی ڈالدیں۔ اور اللہ کے حکم کے سوا وہ اس چیز سے کسی کا کچھ بھی نہیں بگاڑ سکتے تھے۔ اور کچھ ایسے منتر سیکھتے جو انکو نقصان ہی پہنچاتے اور فائدہ کچھ نہ دیتے اور وہ جانتے تھے کہ جو شخص ایسی چیزوں یعنی سحر اور منتر وغیرہ کا خریدار ہو گا اس کا آخرت میں کچھ حصّہ نہیں اور جس چیز کے عوض انہوں نے اپنی جانوں کو بیچ ڈالا وہ بری تھی۔ کیا اچھا ہوتا جو وہ اس بات کو جانتے۔', 'اور پیچھے ہو لئے اس علم کے جو پڑتے تھے شیطان سلیمان کی بادشاہت کے وقت [۱۴۸] اور کفر نہیں کیا سلیمان نے لیکن شیطانوں نے کفر کیا کہ سکھلاتے تھے لوگوں کو جادو اور اس علم کے پیچھے ہو لئے جو اترا دو فرشتوں پر شہر بابل میں جن کا نام ہاروت اور ماروت ہے اور نہیں سکھاتے تھے وہ دونوں فرشتے کسی کو جب تک یہ نہ کہدیتے کہ ہم تو آزمائش کے لئے ہیں سو تو کافر مت ہو پھر ان سے سیکھتے وہ جادو جس سے جدائی ڈالتے ہیں مرد میں اور اسکی عورت میں اور وہ اس سے نقصان نہیں کر سکتے کس کا بغیر حکم اللہ کے اور سیکھتے ہیں وہ چیز جو نقصان کرے ان کا اور فائدہ نہ کرے اور وہ خوب جان چکے ہیں کہ جس نے اختیار کیا جادو کو نہیں اس کے لئے آخرت میں کچھ حصہ اور بہت ہی بری چیز ہے جسکے بدلے بیچا انہوں نے اپنے آپکو اگر ان  کو سمجھ ہوتی', 'They followed what the Shayatin (devils) gave out (falsely of the magic) in the lifetime of Sulaiman (Solomon). Sulaiman did not disbelieve, but the Shayatin (devils) disbelieved, teaching men magic and such things that came down at Babylon to the two angels, Haroot and Maroot, but neither of these two (angels) taught anyone (such things) till they had said, \"We are only for trial, so disbelieve not (by learning this magic from us).\" And from these (angels) people learn that by which they cause separation between man and his wife, but they could not thus harm anyone except by Allahs Leave. And they learn that which harms them and profits them not. And indeed they knew that the buyers of it (magic) would have no share in the Hereafter. And how bad indeed was that for which they sold their ownselves, if they but knew.', 'They followed what the devils used to recite in the reign of Sulaimān (Solomon); and it was not Sulaimān who became an infidel, but the devils did become infidels, teaching people magic, and what had been sent down to the two angels, Hārūt and Mārūt, in Babylon. And these two did not teach anyone without first having said (to him), “We are but a trial, so do not go infidel.” Then, they used to learn from them that with which they could cause separation between a man and his wife. But they were not to bring harm through it to anyone without the will of Allah.They used to learn what harmed them and did no good to them; and they certainly knew that he who buys it has no share in the Hereafter. And, indeed, vile is the thing for which they sold themselves away. If only they knew!'),
(110, 2, 103, 12, 12, 1, 'الم', 'البقرۃ', 'وَ لَوۡ اَنَّہُمۡ اٰمَنُوۡا وَ اتَّقَوۡا لَمَثُوۡبَۃٌ مِّنۡ عِنۡدِ اللّٰہِ خَیۡرٌ ؕ  لَوۡ کَانُوۡا یَعۡلَمُوۡنَ ﴿۱۰۳﴾٪', 'اور اگر وہ ایمان لاتے اور پرہیزگاری کرتے تو اللہ کے ہاں سے بہت اچھا صلہ ملتا۔ کیا اچھا ہوتا جو وہ اس سے واقف ہوتے۔', 'اور اگر وہ ایمان لاتے اور تقویٰ کرتے تو بدلا پاتے اللہ کے ہاں سے بہتر اگر ان کو سمجھ ہوتی [۱۴۹]', 'And if they had believed, and guarded themselves from evil and kept their duty to Allah, far better would have been the reward from their Lord, if they but knew!', 'And had they accepted the faith, and been God-fearing, the reward from Allah would have always been far better. If only they knew!'),
(111, 2, 104, 13, 13, 1, 'الم', 'البقرۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَقُوۡلُوۡا رَاعِنَا وَ قُوۡلُوا انۡظُرۡنَا وَ اسۡمَعُوۡا ؕ  وَ لِلۡکٰفِرِیۡنَ عَذَابٌ اَلِیۡمٌ ﴿۱۰۴﴾', 'اے اہل ایمان گفتگو کے وقت پیغمبر ﷺ سے راعنا نہ کہا کرو۔ انظرنا کہا کرو۔ اور خوب سن رکھو اور کافروں کے لئے دکھ دینے والا عذاب ہے۔', 'اے ایمان والو تم نہ کہو راعنا اور کہو انظرنا اور سنتے رہو اور کافروں کو عذاب ہے دردناک [۱۵۰]', 'O you who believe! Say not (to the Messenger Peace be upon him ) Raina but say Unzurna (Do make us understand) and hear. And for the disbelievers there is a painful torment. (See Verse 4:46)', 'O you who believe, do not say Rā‘inā, but say UnZurnā, and listen, as there is a grievous punishment for the unbelievers.'),
(112, 2, 105, 13, 13, 1, 'الم', 'البقرۃ', 'مَا یَوَدُّ الَّذِیۡنَ کَفَرُوۡا مِنۡ اَہۡلِ الۡکِتٰبِ وَ لَا الۡمُشۡرِکِیۡنَ اَنۡ یُّنَزَّلَ عَلَیۡکُمۡ مِّنۡ خَیۡرٍ مِّنۡ رَّبِّکُمۡ ؕ وَ اللّٰہُ یَخۡتَصُّ بِرَحۡمَتِہٖ مَنۡ یَّشَآءُ ؕ وَ اللّٰہُ ذُو الۡفَضۡلِ الۡعَظِیۡمِ ﴿۱۰۵﴾', 'جو لوگ کافر ہیں اہل کتاب یا مشرک وہ اس بات کو پسند نہیں کرتے کہ تم لوگوں پر تمہارے پروردگار کی طرف سے خیروبرکت نازل ہو اور اللہ تو جس کو چاہتا ہے اپنی رحمت کے ساتھ خاص کر لیتا ہے اور اللہ بڑے فضل کا مالک ہے۔', 'دل نہیں چاہتا ان لوگوں کا جو کافر ہیں اہل کتاب میں اور نہ مشرکوں میں اس بات کو کہ اترے تم پر کوئی نیک بات تمہارے رب کی طرف سے اور اللہ خاص کر لیتا ہے اپنی رحمت کے ساتھ جسکو چاہے اور اللہ بڑے فضل والا ہے [۱۵۱]', 'Neither those who disbelieve among the people of the Scripture (Jews and Christians) nor Al-Mushrikoon (the disbelievers in the Oneness of Allah, idolaters, polytheists, pagans, etc.) like that there should be sent down unto you any good from your Lord. But Allah chooses for His Mercy whom He wills. And Allah is the Owner of Great Bounty.', 'Those who disbelieve from among the people of the Book and the idolaters do not like that any good should come to you from your Lord. But Allah chooses for His grace whomsoever He wills, and Allah is the Lord of great bounty.'),
(113, 2, 106, 13, 13, 1, 'الم', 'البقرۃ', 'مَا نَنۡسَخۡ مِنۡ اٰیَۃٍ اَوۡ نُنۡسِہَا نَاۡتِ بِخَیۡرٍ مِّنۡہَاۤ  اَوۡ مِثۡلِہَا ؕ اَلَمۡ تَعۡلَمۡ اَنَّ اللّٰہَ عَلٰی کُلِّ شَیۡءٍ  قَدِیۡرٌ ﴿۱۰۶﴾', 'ہم جس آیت کو منسوخ کردیتے ہیں یا اسے فراموش کرا دیتے ہیں تو اس سے بہتر یا ویسی ہی اور آیت بھیج دیتے ہیں کیا تم نہیں جانتے کہ اللہ ہر بات پر قادر ہے۔', 'جو منسوخ کرتے ہیں ہم کوئی آیت یا بھلا دیتے ہیں تو بھیج دیتے ہیں اس سے بہتر یا اسکے برابر کیا تجھکو معلوم نہیں کہ اللہ ہر چیز پر قادر ہے [۱۵۲]', 'Whatever a Verse (revelation) do We abrogate or cause to be forgotten, We bring a better one or similar to it. Know you not that Allah is able to do all things?', 'Whenever We abrogate a verse or cause it to be forgotten, We bring one better than it or one equal to it. Do you not know that Allah is powerful over everything?'),
(114, 2, 107, 13, 13, 1, 'الم', 'البقرۃ', 'اَلَمۡ تَعۡلَمۡ اَنَّ اللّٰہَ لَہٗ  مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ مَا لَکُمۡ مِّنۡ دُوۡنِ اللّٰہِ مِنۡ وَّلِیٍّ وَّ لَا نَصِیۡرٍ ﴿۱۰۷﴾', 'کیا تمہیں معلوم نہیں کہ آسمانوں اور زمین کی سلطنت اللہ ہی کی ہے اور اللہ کے سوا تمہارا کوئی دوست اور مددگار نہیں۔', 'کیا تجھ کو معلوم نہیں کہ اللہ ہی کے لئے ہے سلطنت آسمان اور زمین کی اور نہیں تمہارے واسطے اللہ کے سوا کوئی حمایتی اور نہ مددگار [۱۵۳]', 'Know you not that it is Allah to Whom belongs the dominion of the heavens and the earth? And besides Allah you have neither any Walee (protector or guardian) nor any helper.', 'Do you not know that to Allah alone belongs the kingdom of the heavens and the earth? Other than Allah, you have neither a patron, nor a helper.'),
(115, 2, 108, 13, 13, 1, 'الم', 'البقرۃ', 'اَمۡ  تُرِیۡدُوۡنَ اَنۡ تَسۡـَٔلُوۡا رَسُوۡلَکُمۡ کَمَا سُئِلَ مُوۡسٰی مِنۡ قَبۡلُ ؕ وَ مَنۡ یَّتَبَدَّلِ الۡکُفۡرَ بِالۡاِیۡمَانِ فَقَدۡ ضَلَّ سَوَآءَ  السَّبِیۡلِ ﴿۱۰۸﴾', 'مسلمانو کیا تم یہ چاہتے ہو کہ اپنے پیغمبر ﷺ سے اسی طرح کے سوال کرو جس طرح کے سوال پہلے موسٰی سے کئے گئے تھے۔ اور جس شخص نے ایمان چھوڑ کر اس کے بدلے کفر لیا تو یقینًا وہ سیدھے رستے سے بھٹک گیا۔', 'کیا تم مسلمان بھی چاہتے ہو کہ سوال کرو اپنے رسول سے جیسے سوال ہو چکے ہیں موسٰی سے اس سے پہلے اور جو کوئی کفر لیوے بدلے ایمان کے تو وہ بہکا سیدھی راہ سے [۱۵۴]', 'Or do you want to ask your Messenger (Muhammad Peace be upon him ) as Moosa (Moses) was asked before (i.e. show us openly our Lord?) And he who changes Faith for disbelief, verily, he has gone astray from the right way.', 'Or, do you rather want to question your Prophet as Mūsā was questioned earlier? And whoever takes infidelity in exchange for faith has certainly missed the straight path.'),
(116, 2, 109, 13, 13, 1, 'الم', 'البقرۃ', 'وَدَّ کَثِیۡرٌ مِّنۡ اَہۡلِ الۡکِتٰبِ لَوۡ یَرُدُّوۡنَکُمۡ مِّنۡۢ بَعۡدِ اِیۡمَانِکُمۡ کُفَّارًا ۚۖ حَسَدًا مِّنۡ عِنۡدِ اَنۡفُسِہِمۡ مِّنۡۢ بَعۡدِ مَا تَبَیَّنَ لَہُمُ الۡحَقُّ ۚ فَاعۡفُوۡا وَ اصۡفَحُوۡا حَتّٰی یَاۡتِیَ اللّٰہُ بِاَمۡرِہٖ ؕ اِنَّ اللّٰہَ عَلٰی کُلِّ شَیۡءٍ قَدِیۡرٌ ﴿۱۰۹﴾', 'بہت سے اہل کتاب اپنے دل کی جلن سے یہ چاہتے ہیں کہ ایمان لا چکنے کے بعد تم کو پھر کافر بنا دیں حالانکہ ان پر حق ظاہر ہو چکا ہے۔ تو تم معاف کر دو اور درگذر کرو۔ یہاں تک کہ اللہ اپنا دوسرا حکم بھیجے۔ بیشک اللہ ہر بات پر قادر ہے۔', 'دل چاہتا ہے بہت سے اہل کتاب کا کہ کسی طرح تم کو پھیر کر مسلمان ہوئے پیچھے کافر بنا دیں بسبب اپنے دلی حسد کے بعد اس کے کہ ظاہر ہو چکا ان پر حق [۱۵۵] سو تم در گذر کرو اور خیال میں نہ لاؤ جبتک بھیجے اللہ اپنا حکم [۱۵۶] بیشک اللہ ہر چیز پر قادر ہے [۱۵۷]', 'Many of the people of the Scripture (Jews and Christians) wish that if they could turn you away as disbelievers after you have believed, out of envy from their ownselves, even, after the truth (that Muhammad Peace be upon him is Allahs Messenger) has become manifest unto them. But forgive and overlook, till Allah brings His Command. Verily, Allah is Able to do all things.', '(O Muslims,) many among the people of the Book desire to turn you, after your accepting the faith, back into disbelievers - all out of envy on their part, even after the truth has become clear to them. So, forgive and overlook till Allah brings out His command. Certainly, Allah is powerful over everything.'),
(117, 2, 110, 13, 13, 1, 'الم', 'البقرۃ', 'وَ اَقِیۡمُوا الصَّلٰوۃَ وَ اٰتُوا الزَّکٰوۃَ ؕ وَ مَا تُقَدِّمُوۡا لِاَنۡفُسِکُمۡ مِّنۡ خَیۡرٍ تَجِدُوۡہُ عِنۡدَ اللّٰہِ ؕ اِنَّ اللّٰہَ بِمَا تَعۡمَلُوۡنَ بَصِیۡرٌ ﴿۱۱۰﴾', 'اور نماز ادا کرتے رہو اور زکوٰۃ دیتے رہو۔ اور جو بھلائی اپنے لئے آگے بھیج رکھو گے اس کو اللہ کے ہاں پا لو گے۔ کچھ شک نہیں کہ اللہ تمارے سب کاموں کو دیکھ رہا ہے۔', 'اور قائم رکھو نماز اور دیتے رہو زکوٰۃ اور جو کچھ آگے بھیج دو گے اپنے واسطے بھلائی پاؤ گے اس کو اللہ کے پاس بیشک اللہ جو کچھ تم کرتے ہو سب دیکھتا ہے [۱۵۸]', 'And perform As-Salat (Iqamat-as-Salat), and give Zakat, and whatever of good (deeds that Allah loves) you send forth for yourselves before you, you shall find it with Allah. Certainly, Allah is All-Seer of what you do.', 'And be steadfast in Salāh (prayer), and give Zakāh. Whatever good you send forth for yourselves, you will find it with Allah. Certainly, Allah is watchful of what you do.'),
(118, 2, 111, 13, 13, 1, 'الم', 'البقرۃ', 'وَ قَالُوۡا لَنۡ یَّدۡخُلَ الۡجَنَّۃَ اِلَّا مَنۡ کَانَ ہُوۡدًا اَوۡ نَصٰرٰی ؕ تِلۡکَ اَمَانِیُّہُمۡ ؕ قُلۡ ہَاتُوۡا بُرۡہَانَکُمۡ  اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ ﴿۱۱۱﴾', 'اور یہودی اور عیسائی کہتے ہیں کہ یہودیوں اور عیسائیوں کے سوا کوئی بہشت میں نہیں جانے کا یہ ان لوگوں کے خیالات باطل ہیں اے پیغمبر ان سے کہہ دو کہ اگر سچّے ہو تو دلیل پیش کرو۔', 'اور کہتے ہیں کہ ہرگز نہ جاویں گے جنت میں مگر جو ہوں گے یہودی یا نصرانی [۱۵۹] یہ آرزؤیں باندھ لی ہیں انہوں نے کہدے لے آؤ سند اپنی اگر تم سچے ہو', 'And they say, \"None shall enter Paradise unless he be a Jew or a Christian.\" These are their own desires. Say (O Muhammad Peace be upon him ), \"Produce your proof if you are truthful.\"', 'They say that no one shall ever enter Paradise unless he is a Jew, or a Christian. These are their fancies. Say, “Bring your proof, if you are truthful.”'),
(119, 2, 112, 13, 13, 1, 'الم', 'البقرۃ', 'بَلٰی ٭  مَنۡ اَسۡلَمَ وَجۡہَہٗ  لِلّٰہِ وَ ہُوَ  مُحۡسِنٌ فَلَہٗۤ اَجۡرُہٗ عِنۡدَ رَبِّہٖ ۪ وَ لَا خَوۡفٌ عَلَیۡہِمۡ  وَ لَا ہُمۡ  یَحۡزَنُوۡنَ ﴿۱۱۲﴾٪', 'ہاں کیوں نہیں جو شخص اللہ کے آگے گردن جھکا دے یعنی ایمان لے آئے اور وہ نیکوکار بھی ہو تو اس کا صلہ اس کے پروردگار کے پاس ہے اور ایسے لوگوں کو قیامت کے دن نہ کسی طرح کا خوف ہو گا اور نہ وہ غمناک ہوں گے۔', 'کیوں نہیں جس نے تابع کر دیا منہ اپنا اللہ کے اور وہ نیک کام کرنے والا ہےتو اس کے لئے ہے ثواب اس کا اپنے رب کے پاس اور نہ ڈر ہے ان پر اور نہ وہ غمگین ہو نگے [۱۶۰]', 'Yes, but whoever submits his face (himself) to Allah (i.e. follows Allahs Religion of Islamic Monotheism) and he is a Muhsin (good-doer i.e. performs good deeds totally for Allahs sake only without any show off or to gain praise or fame, etc., and in accordance with the Sunnah of Allahs Messenger Muhammad Peace be upon him ) then his reward is with his Lord (Allah), on such shall be no fear, nor shall they grieve. (See Tafsir Ibn Katheer, Vol.1, Page 154).', 'Of course, whosoever submits his face to Allah, and is good in deeds, will have his reward with his Lord, and there shall be no fear for such people, nor shall they grieve.'),
(120, 2, 113, 14, 14, 1, 'الم', 'البقرۃ', 'وَ قَالَتِ الۡیَہُوۡدُ  لَیۡسَتِ النَّصٰرٰی عَلٰی شَیۡءٍ ۪ وَّ قَالَتِ النَّصٰرٰی لَیۡسَتِ الۡیَہُوۡدُ عَلٰی شَیۡءٍ ۙ وَّ ہُمۡ یَتۡلُوۡنَ الۡکِتٰبَ ؕ کَذٰلِکَ قَالَ الَّذِیۡنَ لَا یَعۡلَمُوۡنَ مِثۡلَ قَوۡلِہِمۡ ۚ فَاللّٰہُ یَحۡکُمُ بَیۡنَہُمۡ یَوۡمَ الۡقِیٰمَۃِ فِیۡمَا کَانُوۡا فِیۡہِ یَخۡتَلِفُوۡنَ ﴿۱۱۳﴾', 'اور یہودی کہتے ہیں کہ عیسائی رستے پر نہیں اور عیسائی کہتے ہیں کہ یہودی رستے پر نہیں حالانکہ وہ کتاب الٰہی پڑھتے ہیں۔ اسی طرح بالکل انہی کی سی بات وہ لوگ کہتے ہیں جو کچھ نہیں جانتے یعنی مشرک تو جس بات میں یہ لوگ اختلاف کر رہے ہیں اللہ قیامت کے دن اس کا ان میں فیصلہ کر دے گا۔', 'اور یہود تو کہتے ہیں کہ نصاریٰ نہیں کسی راہ پر اور نصاریٰ کہتے ہیں کہ یہود نہیں کسی راہ پر باوجودیکہ وہ سب پڑھتے ہیں کتاب [۱۶۱] اسی طرح کہا ان لوگوں نے جو جاہل ہیں ان ہی کی سی بات اب اللہ حکم کرے گا ان میں قیامت کے دن جس بات میں جھگڑتے تھے [۱۶۲]', 'The Jews said that the Christians follow nothing (i.e. are not on the right religion); and the Christians said that the Jews follow nothing (i.e. are not on the right religion); though they both recite the Scripture. Like unto their word, said (the pagans) who know not. Allah will judge between them on the Day of Resurrection about that wherein they have been differing.', 'The Jews say: “The Christians have nothing to stand on” and the Christians say “The Jews have nothing to stand on” while they both read the Book! Similarly, those who do not know have said like they (the Jews and the Christians) say. So, Allah will judge between them on the Day of Resurrection in what they used to dispute.'),
(121, 2, 114, 14, 14, 1, 'الم', 'البقرۃ', 'وَ مَنۡ اَظۡلَمُ  مِمَّنۡ مَّنَعَ مَسٰجِدَ اللّٰہِ اَنۡ یُّذۡکَرَ فِیۡہَا اسۡمُہٗ وَ سَعٰی فِیۡ خَرَابِہَا ؕ اُولٰٓئِکَ مَا کَانَ لَہُمۡ اَنۡ یَّدۡخُلُوۡہَاۤ اِلَّا خَآئِفِیۡنَ ۬ؕ لَہُمۡ  فِی الدُّنۡیَا خِزۡیٌ وَّ لَہُمۡ فِی الۡاٰخِرَۃِ عَذَابٌ عَظِیۡمٌ ﴿۱۱۴﴾', 'اور اس سے بڑھ کر ظالم کون جو اللہ کی مسجدوں میں اللہ کے نام کا ذکر کئے جانے کو منع کرے اور ان کی ویرانی  کیلئے کوشش کرے۔ ان لوگوں کو کچھ حق نہیں کہ مسجدوں میں داخل ہوں مگر ڈرتے ہوئے ان کے لئے دنیا میں رسوائی ہے اور آخرت میں بڑا عذاب۔', 'اور اس سے بڑا ظالم کون جس نے منع کیا اللہ کی مسجدوں میں کہ لیا جاوے وہاں نام اس کا اور کوشش کی انکے اجاڑنے میں [۱۶۳] ایسوں کو لائق نہیں کہ داخل ہوں ان میں مگر ڈرتے ہوئے [۱۶۴] انکے لئےدنیا میں ذلت ہے [۱۶۵] اور ان کے لئے آخرت میں بڑا عذاب ہے', 'And who is more unjust than those who forbid that Allahs Name be glorified and mentioned much (i.e. prayers and invocations, etc.) in Allahs Mosques and strive for their ruin? It was not fitting that such should themselves enter them (Allahs Mosques) except in fear. For them there is disgrace in this world, and they will have a great torment in the Hereafter.', 'Who is more cruel than the one who prevents the mosques of Allah from His name being recited therein, and strives for their destruction? It was not for such men to enter them except in awe. For them there is disgrace in this world, and for them there is a mighty punishment in the other world.'),
(122, 2, 115, 14, 14, 1, 'الم', 'البقرۃ', 'وَ  لِلّٰہِ الۡمَشۡرِقُ وَ الۡمَغۡرِبُ ٭ فَاَیۡنَمَا تُوَلُّوۡا فَثَمَّ وَجۡہُ اللّٰہِ ؕ اِنَّ اللّٰہَ وَاسِعٌ عَلِیۡمٌ ﴿۱۱۵﴾', 'اور مشرق اور مغرب سب اللہ ہی کا ہے۔ تو جدھر بھی تم رخ کرو ادھر ہی اللہ کی ذات ہے۔ بیشک اللہ صاحب وسعت ہے باخبر ہے۔', 'اور اللہ ہی کا ہے مشرق اور مغرب سو جس طرف تم منہ کرو وہاں ہی متوجہ ہے اللہ [۱۶۶] بیشک اللہ بے انتہا بخشش کرنے والا سب کچھ جاننے والا ہے [۱۶۷]', 'And to Allah belong the east and the west, so wherever you turn yourselves or your faces there is the Face of Allah (and He is High above, over His Throne). Surely! Allah is All-Sufficient for His creatures needs, All-Knowing.', 'To Allah belongs the East and the West. So, whichever way you turn, there is the Face of Allah. Indeed, Allah is All-Embracing, All-Knowing.'),
(123, 2, 116, 14, 14, 1, 'الم', 'البقرۃ', 'وَ قَالُوا اتَّخَذَ اللّٰہُ وَلَدًا ۙ سُبۡحٰنَہٗ ؕ بَلۡ لَّہٗ مَا فِی السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ کُلٌّ لَّہٗ قٰنِتُوۡنَ ﴿۱۱۶﴾', 'اور یہ لوگ اس بات کے قائل ہیں کہ اللہ اولاد رکھتا ہے نہیں وہ پاک ہے بلکہ جو کچھ آسمانوں اور زمین میں ہے سب اسی کا ہے اور سب اس کے فرمانبردار ہیں۔', 'اور کہتے ہیں کہ اللہ رکھتا ہے اولاد وہ تو سب باتوں سے پاک ہے بلکہ اسی کا ہے جو کچھ ہے آسمان اور زمین میں سب اسی کے تابعدار ہیں', 'And they (Jews, Christians and pagans) say: Allah has begotten a son (children or offspring). Glory be to Him (Exalted be He above all that they associate with Him). Nay, to Him belongs all that is in the heavens and on earth, and all surrender with obedience (in worship) to Him.', 'They say: “Allah has got a son.” Pure is He. Instead, to Him belongs all that there is in the heavens and the earth. All stand obedient to Him.'),
(124, 2, 117, 14, 14, 1, 'الم', 'البقرۃ', 'بَدِیۡعُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ  اِذَا قَضٰۤی اَمۡرًا فَاِنَّمَا یَقُوۡلُ لَہٗ  کُنۡ فَیَکُوۡنُ ﴿۱۱۷﴾', 'وہی آسمانوں اور زمین کا پیدا کرنے والا ہے اور جب کوئی کام کرنا چاہتا ہے تو اس کو ارشاد فرما دیتا ہے کہ ہو جا تو وہ ہو جاتا ہے۔', 'نیا پیدا کرنے والا ہے آسمان اور زمین کا اور جب حکم کرتا ہے کسی کام کو تو یہی فرماتا ہے اس کو کہ ہو جا پس وہ ہو جاتا ہے [۱۶۸]', 'The Originator of the heavens and the earth. When He decrees a matter, He only says to it : \"Be!\" - and it is.', '(He is the) Originator of the heavens and the earth. When He decides a matter, He simply says to it: “Be”, and it comes to be.'),
(125, 2, 118, 14, 14, 1, 'الم', 'البقرۃ', 'وَ قَالَ الَّذِیۡنَ لَا یَعۡلَمُوۡنَ لَوۡ لَا یُکَلِّمُنَا اللّٰہُ  اَوۡ تَاۡتِیۡنَاۤ  اٰیَۃٌ  ؕ کَذٰلِکَ قَالَ الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ  مِّثۡلَ قَوۡلِہِمۡ  ؕ تَشَابَہَتۡ قُلُوۡبُہُمۡ ؕ قَدۡ بَیَّنَّا الۡاٰیٰتِ لِقَوۡمٍ  یُّوۡقِنُوۡنَ ﴿۱۱۸﴾', 'اور جو لوگ کچھ نہیں جانتے یعنی مشرک وہ کہتے ہیں کہ اللہ ہم سے کلام کیوں نہیں کرتا یا ہمارے پاس کوئی نشانی کیوں نہیں آتی۔ اسی طرح جو لوگ ان سے پہلے تھے وہ بھی انہی کی سی باتیں کیا کرتے تھے ان لوگوں کے دل آپس میں ملتے جلتے ہیں جو لوگ صاحب یقین ہیں ان کے سمجھانے کے لئے ہم نے نشانیاں بیان کر دی ہیں۔', 'اور کہتے ہیں وہ لوگ جو کچھ نہیں جانتے کیوں نہیں بات کرتا ہم سے اللہ یا کیوں نہیں آتی ہمارے پاس کوئی آیت [۱۶۹] اسی طرح کہ چکے ہیں وہ لوگ جو ان سے پہلے تھے انہی کی سی بات ایک سے ہیں دل ان کے بیشک ہم نے بیان کر دیں نشانیاں ان لوگوں کے واسطے جو یقین لاتے ہیں [۱۷۰]', 'And those who have no knowledge say: \"Why does not Allah speak to us (face to face) or why does not a sign come to us?\" So said the people before them words of similar import. Their hearts are alike, We have indeed made plain the signs for people who believe with certainty', 'Those who do not know say: “Why is it that Allah does not speak to us, nor does a sign come to us?” So spoke those before them as these people do. Their hearts resemble each other. We have indeed made the signs clear for the people who have certitude.'),
(126, 2, 119, 14, 14, 1, 'الم', 'البقرۃ', 'اِنَّاۤ اَرۡسَلۡنٰکَ بِالۡحَقِّ بَشِیۡرًا وَّ نَذِیۡرًا ۙ وَّ لَا  تُسۡئَلُ عَنۡ  اَصۡحٰبِ  الۡجَحِیۡمِ ﴿۱۱۹﴾', 'اے  پیغمبر ہم نے تم کو سچائی کے ساتھ خوشخبری سنانے والا اور ڈرانے والا بنا کر بھیجا ہے اور اہل دوزخ کے بارے میں تم سے کچھ پرسش نہیں ہو گی۔', 'بیشک ہم نے تجھ کو بھیجا ہے سچا دین دیکر خوشخبری دینے والا اور ڈرانے والا اور تجھ سے پوچھ نہیں دوزخ میں رہنے والوں کی [۱۷۱]', 'Verily, We have sent you (O Muhammad Peace be upon him ) with the truth (Islam), a bringer of glad tidings (for those who believe in what you brought, that they will enter Paradise) and a warner (for those who disbelieve in what you brought, they will enter the Hell-fire). And you will not be asked about the dwellers of the blazing Fire.', 'Surely, We have sent you with the truth, as a bearer of good tidings, and a warner, and you will not be asked about the people of Hell.'),
(127, 2, 120, 14, 14, 1, 'الم', 'البقرۃ', 'وَ لَنۡ تَرۡضٰی عَنۡکَ الۡیَہُوۡدُ وَ لَا النَّصٰرٰی حَتّٰی تَتَّبِعَ مِلَّتَہُمۡ ؕ قُلۡ اِنَّ ہُدَی اللّٰہِ ہُوَ  الۡہُدٰی ؕ وَ لَئِنِ اتَّبَعۡتَ اَہۡوَآءَہُمۡ بَعۡدَ الَّذِیۡ جَآءَکَ مِنَ الۡعِلۡمِ ۙ مَا لَکَ مِنَ اللّٰہِ مِنۡ وَّلِیٍّ وَّ لَا نَصِیۡرٍ ﴿۱۲۰﴾ؔ', 'اور تم سے نہ تو یہودی کبھی خوش ہوں گے اور نہ عیسائی یہاں تک کہ ان کے مذہب کی پیروی اختیار کر لو ان سے کہہ دو کہ اللہ کی ہدایت یعنی دین اسلام ہی ہدایت ہے اور اے پیغمبر اگر تم اپنے پاس علم یعنی وحی الٰہی کے آ جانے پر بھی ان کی خواہشوں پر چلو گے تو تم کو اللہ کی پکڑ سے بچانے والا نہ کوئی دوست ہو گا نہ کوئی مددگار۔', 'اور ہر گرز راضی نہ ہوں گے تجھ سے یہود او ر نصاریٰ جب تک تو تابع نہ ہو ان کے دین کا [۱۷۲] تو کہدے جو راہ اللہ بتلاوے وہی راہ سیدھی ہے [۱۷۳] اور اگر بالفرض تو تابعداری کرے انکی خواہشوں کی بعد اس علم کے جو تجھ کو پہنچا تو تیرا کوئی نہیں اللہ کے ہاتھ سے حمایت کرنے والا اور نہ مددگار [۱۷۴]', 'Never will the Jews nor the Christians be pleased with you (O Muhammad Peace be upon him ) till you follow their religion. Say: \"Verily, the Guidance of Allah (i.e. Islamic Monotheism) that is the (only) Guidance. And if you (O Muhammad Peace be upon him ) were to follow their (Jews and Christians) desires after what you have received of Knowledge (i.e. the Quran), then you would have against Allah neither any Walee (protector or guardian) nor any helper.', 'The Jews will never be pleased with you, nor will the Christians, unless you follow their faith. Say: “Guidance of Allah is, indeed, the guidance.” Were you to follow their desires despite the knowledge that has come to you, there shall be no friend for you against Allah, nor a helper.'),
(128, 2, 121, 14, 14, 1, 'الم', 'البقرۃ', 'اَلَّذِیۡنَ اٰتَیۡنٰہُمُ الۡکِتٰبَ یَتۡلُوۡنَہٗ حَقَّ تِلَاوَتِہٖ ؕ اُولٰٓئِکَ یُؤۡمِنُوۡنَ بِہٖ ؕ وَ مَنۡ یَّکۡفُرۡ بِہٖ فَاُولٰٓئِکَ ہُمُ  الۡخٰسِرُوۡنَ ﴿۱۲۱﴾٪', 'جن لوگوں کو ہم نے کتاب عنایت کی ہے وہ اس کو ایسا پڑھتے ہیں جیسا اس کے پڑھنے کا حق ہے۔ یہی لوگ اس پر ایمان رکھتے ہیں اور جو اس کو نہیں مانتے وہی خسارہ پانے والے ہیں۔', 'وہ لوگ جن کو دی ہم نے کتاب وہ اسکو پڑھتے ہیں جو حق ہے اسکے پڑھنے کا وہی اس پر یقین لاتے ہیں اور جو کوئی منکر ہو گا اس سے تو وہی لوگ نقصان پانے والے ہیں [۱۷۵]', 'Those (who embraced Islam from Banee Israel) to whom We gave the Book (the Taurat (Torah)) (or those (Muhammads Peace be upon him companions) to whom We have given the Book (the Quran)) recite it (i.e. obey its orders and follow its teachings) as it should be recited (i.e. followed), they are the ones that believe therein. And whoso disbelieves in it (the Quran), those are they who are the losers. (Tafsir Al-Qurtubee. Vol. 2, Page 95).', 'Those to whom We have given the Book and they recite it observing the rights of its recitation - they are the ones who believe in it. And those who disbelieve in it, they are the losers.'),
(129, 2, 122, 15, 15, 1, 'الم', 'البقرۃ', 'یٰبَنِیۡۤ  اِسۡرَآءِیۡلَ اذۡکُرُوۡا نِعۡمَتِیَ الَّتِیۡۤ  اَنۡعَمۡتُ عَلَیۡکُمۡ وَ اَنِّیۡ فَضَّلۡتُکُمۡ عَلَی الۡعٰلَمِیۡنَ ﴿۱۲۲﴾', 'اے بنی اسرائیل میرے وہ احسان یاد کرو جو میں نے تم پر کئے اور یہ کہ میں نے تم کو اہل عالم پر فضیلت بخشی۔', 'اے بنی اسرائیل یاد کرو احسان ہمارے جو ہم نے تم پر کئے اور اس کو  کہ ہم نے تم کو بڑائی دی اہل عالم پر', 'O Children of Israel! Remember My Favour which I bestowed upon you and that I preferred you to the Alameen (mankind and jinns) (of your time-period, in the past).', 'O children of Isrā’īl (Israel), remember My blessing that I conferred upon you, and that I gave you excellence over the worlds.'),
(130, 2, 123, 15, 15, 1, 'الم', 'البقرۃ', 'وَ اتَّقُوۡا یَوۡمًا لَّا تَجۡزِیۡ نَفۡسٌ عَنۡ نَّفۡسٍ شَیۡئًا وَّ لَا یُقۡبَلُ مِنۡہَا عَدۡلٌ وَّ لَا تَنۡفَعُہَا شَفَاعَۃٌ  وَّ لَا ہُمۡ یُنۡصَرُوۡنَ ﴿۱۲۳﴾', 'اور اس دن سے ڈرو جب کوئی شخص کسی شخص کے کچھ کام نہ آئے اور نہ اس سے بدلہ قبول کیا جائے اور نہ اسکو کسی کی سفارش کچھ فائدہ دے اور نہ لوگوں کو کسی اور طرح کی مدد مل سکے۔', 'اور ڈرو اس دن سے کہ نہ کام آوے کوئی شخص کسی کی طرف سے ذرا بھی اور نہ قبول کیا جاوے گا اس کی طرف سے بدلہ اور نہ کام آوے اس کو سفارش اور نہ ان کو مدد پہنے [۱۷۶]', 'And fear the Day (of Judgement) when no person shall avail another, nor shall compensation be accepted from him, nor shall intercession be of use to him, nor shall they be helped.', 'And guard yourselves against a day when no one shall stand for anyone for anything, nor shall ransom be accepted from anyone, nor shall intercession be of benefit to him, nor shall any support be given to such people.'),
(131, 2, 124, 15, 15, 1, 'الم', 'البقرۃ', 'وَ اِذِ ابۡتَلٰۤی  اِبۡرٰہٖمَ  رَبُّہٗ بِکَلِمٰتٍ فَاَتَمَّہُنَّ ؕ قَالَ اِنِّیۡ جَاعِلُکَ لِلنَّاسِ  اِمَامًا ؕ قَالَ وَ مِنۡ ذُرِّیَّتِیۡ ؕ قَالَ لَا یَنَالُ عَہۡدِی الظّٰلِمِیۡنَ ﴿۱۲۴﴾', 'اور جب ابراہیم کی اسکے پروردگار نے چند باتوں میں آزمائش کی تو وہ ان میں پورے اترے۔ فرمایا کہ میں تم کو لوگوں کا پیشوا بناؤں گا۔ انہوں نے کہا کہ پروردگار میری اولاد میں سے بھی پیشوا بنائیو فرمایا کہ میرا قول و قرار ظالموں کے لئے نہیں ہوا کرتا۔', 'اور جب آزمایا ابراہیم کو اسکے رب نے کئ باتوں میں [۱۷۷] پھر اسنے وہ پوری کیں تب فرمایا میں تجھ کو کروں گا سب لوگوں کا پیشوا [۱۷۸] بولا اور میری اولاد میں سے بھی فرمایا نہیں پہنچے گا میرا قرار ظالموں کو [۱۷۹]', 'And (remember) when the Lord of Ibrahim (Abraham) (i.e., Allah) tried him with (certain) Commands, which he fulfilled. He (Allah) said (to him), \"Verily, I am going to make you a leader (Prophet) of mankind.\" (Ibrahim (Abraham)) said, \"And of my offspring (to make leaders).\" (Allah) said, \"My Covenant (Prophethood, etc.) includes not Zalimoon (polytheists and wrong-doers).\"', 'When his Lord put Ibrāhīm to a test with certain Words, and he fulfilled them, He said, “I am going to make you an Imām for the people.”He said, “And from among my progeny?” He replied, “My promise does not extend to the unjust.”'),
(132, 2, 125, 15, 15, 1, 'الم', 'البقرۃ', 'وَ اِذۡ جَعَلۡنَا الۡبَیۡتَ مَثَابَۃً لِّلنَّاسِ وَ اَمۡنًا ؕ وَ اتَّخِذُوۡا مِنۡ مَّقَامِ اِبۡرٰہٖمَ مُصَلًّی ؕ وَ عَہِدۡنَاۤ اِلٰۤی اِبۡرٰہٖمَ  وَ اِسۡمٰعِیۡلَ اَنۡ طَہِّرَا بَیۡتِیَ  لِلطَّآئِفِیۡنَ وَ الۡعٰکِفِیۡنَ وَ الرُّکَّعِ  السُّجُوۡدِ ﴿۱۲۵﴾', 'اور جب ہم نے خانہ کعبہ کو لوگوں کے لئے جمع ہونے اور امن پانے کی جگہ مقرر کیا اور حکم دیا کہ جس مقام پر ابراہیم کھڑے ہوتے تھے اس کو نماز کی جگہ بنا لو۔ اور ابراہیم اور اسمٰعیل کو حکم بھیجا کہ طواف کرنے والوں اور اعتکاف کرنے والوں اور رکوع کرنے والوں اور سجدہ کرنے والوں کے لئے میرے گھر کو پاک صاف رکھا کرو۔', 'اور جب مقرر کیا ہم نے خانہ کعبہ کو اجتماع کی جگہ لوگوں کے واسطے اور جگہ امن کی [۱۸۰] اور بناؤ ابراہیم کے کھڑے ہونے کی جگہ کو نماز کی جگہ [۱۸۱] اور حکم کیا ہم نے ابراہیم اور اسمٰعیل کو کہ پاک کر رکھو میرے گھر کو [۱۸۲] واسطے طواف کرنے والوں کے اور اعتکاف کرنے والوں کے اور رکوع او رسجدہ کرنے والوں کے', 'And (remember) when We made the House (the Kabah at Makkah) a place of resort for mankind and a place of safety. And take you (people) the Maqam (place) of Ibrahim (Abraham) (or the stone on which Ibrahim (Abraham) stood while he was building the Kabah) as a place of prayer (for some of your prayers, e.g. two Rakat after the Tawaf of the Kabah at Makkah), and We commanded Ibrahim (Abraham) and Ismail (Ishmael) that they should purify My House (the Kabah at Makkah) for those who are circumambulating it, or staying (Itikaf), or bowing or prostrating themselves (there, in prayer).', 'When We made the House (Ka‘bah of Makkah) a frequented place for men, and a place of peace! Make from the Station of Ibrāhīm a place of prayer. We gave the (following directive) to Ibrāhīm and Ismā‘īl (Ishmael): “Purify My House for those who are to circumambulate (make Tawāf) and those who stay in I‘tikāf, and those who bow down or prostrate themselves (in prayers).'),
(133, 2, 126, 15, 15, 1, 'الم', 'البقرۃ', 'وَ اِذۡ قَالَ  اِبۡرٰہٖمُ  رَبِّ اجۡعَلۡ ہٰذَا بَلَدًا اٰمِنًا وَّ ارۡزُقۡ اَہۡلَہٗ مِنَ الثَّمَرٰتِ مَنۡ اٰمَنَ مِنۡہُمۡ بِاللّٰہِ وَ الۡیَوۡمِ الۡاٰخِرِ ؕ قَالَ وَ مَنۡ کَفَرَ فَاُمَتِّعُہٗ قَلِیۡلًا ثُمَّ  اَضۡطَرُّہٗۤ اِلٰی عَذَابِ النَّارِ ؕ وَ بِئۡسَ الۡمَصِیۡرُ ﴿۱۲۶﴾', 'اور جب ابراہیم نے دعا کی کہ اے پروردگار اس جگہ کو امن کا شہر بنا اور اس کے رہنے والوں میں سے جو اللہ پر اور روز آخر پر ایمان لائیں ان کے کھانے کو میوے عطا فرما۔ تو اللہ نے فرمایا کہ جو کافر ہو گا میں اس کو بھی کچھ مدت تک  سامان زندگی دوں گا مگر پھر اس کو عذاب دوزخ کے بھگتنے کے لئے مجبور کر دوں گا اور وہ بری جگہ ہے۔', 'اور جب کہا ابراہیم نے اے میرے رب بنا اس کو شہر امن کا [۱۸۳] اور روزی دے اسکے رہنے والوں کو میوے جو کوئی ان میں سے ایمان لاوے اللہ پر اور قیامت کے دن پر [۱۸۴] فرمایا اور جو کفر کریں اس کو بھی نفع پہنچاؤں گا تھوڑے دنوں پھر اسکو جبرًا بلاؤں گا دوزخ کے عذاب میں اور وہ بری جگہ ہے رہنے کی [۱۸۵]', 'And (remember) when Ibrahim (Abraham) said, \"My Lord, make this city (Makkah) a place of security and provide its people with fruits, such of them as believe in Allah and the Last Day.\" He (Allah) answered: \"As for him who disbelieves, I shall leave him in contentment for a while, then I shall compel him to the torment of the Fire, and worst indeed is that destination!\"', '(Recall) when Ibrāhīm said, “My Lord, make this a city of peace, and provide its people with fruits - those of them who believe in Allah and the Last Day.” He (Allah) said, “As for the one who disbelieves, I shall let him enjoy a little, then I shall drag him to the punishment of the Fire. How evil an end it is!'),
(134, 2, 127, 15, 15, 1, 'الم', 'البقرۃ', 'وَ اِذۡ یَرۡفَعُ  اِبۡرٰہٖمُ  الۡقَوَاعِدَ مِنَ الۡبَیۡتِ وَ اِسۡمٰعِیۡلُ ؕ رَبَّنَا تَقَبَّلۡ مِنَّا ؕ اِنَّکَ اَنۡتَ السَّمِیۡعُ الۡعَلِیۡمُ ﴿۱۲۷﴾', 'اور جب ابراہیم اور اسمٰعیل بیت اللہ کی بنیادیں اونچی کر رہے تھے تو دعا کئے جاتے تھے کہ اے ہمارے پروردگار ہم سے یہ خدمت قبول فرما بیشک تو سننے والا ہے جاننے والا ہے۔', 'اور یاد کرو جب اٹھاتے تھے ابراہیم بنیادیں خانہ کعبہ کی اور اسمٰعیل اور دعا کرتے تھے اے پروردگار ہمارے قبول کر ہم سے بیشک تو ہی ہے سننے والا جاننے والا [۱۸۶]', 'And (remember) when Ibrahim (Abraham) and (his son) Ismail (Ishmael) were raising the foundations of the House (the Kabah at Makkah), (saying), \"Our Lord! Accept (this service) from us. Verily! You are the All-Hearer, the All-Knower.\"', 'When Ibrāhīm was raising up the foundations of the House, along with Ismā‘īl (Ishmael) (supplicating): “Our Lord accept (this service) from us! Indeed, You - and You alone - are the All-Hearing, the All-Knowing!'),
(135, 2, 128, 15, 15, 1, 'الم', 'البقرۃ', 'رَبَّنَا وَ اجۡعَلۡنَا مُسۡلِمَیۡنِ لَکَ وَ مِنۡ ذُرِّیَّتِنَاۤ اُمَّۃً مُّسۡلِمَۃً  لَّکَ ۪ وَ اَرِنَا مَنَاسِکَنَا وَ تُبۡ عَلَیۡنَا ۚ اِنَّکَ اَنۡتَ التَّوَّابُ الرَّحِیۡمُ ﴿۱۲۸﴾', 'اے پروردگار ہم کو اپنا فرمانبردار بنائے رکھیو۔ اور ہماری اولاد میں سے بھی ایک گروہ کو اپنا حکم بردار بنائیو اور پروردگار ہمیں ہمارے طریق عبادت بتا اور ہمارے حال پر رحم کے ساتھ توجہ فرما۔ بیشک تو ہی توجہ فرمانے والا ہے  مہربان ہے۔', 'اے پروردگار ہمارے اور کر ہم کو حکم بردار اپنا اور ہماری اولاد میں بھی کر ایک جماعت فرمانبردار اپنی اور بتلا ہم کو قاعدے حج کرنے کے اور ہم کو معاف کر بیشک تو ہی ہے توبہ قبول کرنے والا مہربان', '\"Our Lord! And make us submissive unto You and of our offspring a nation submissive unto You, and show us our Manasik (all the ceremonies of pilgrimage - Hajj and Umrah, etc.), and accept our repentance. Truly, You are the One Who accepts repentance, the Most Merciful.', 'Our Lord, make us both submissive to You, and (make) of our progeny as well, a people submissive to You and show us our ways of Pilgrimage and accept our repentance. Indeed, You - and You alone - are the Most-Relenting, the Very-Merciful.'),
(136, 2, 129, 15, 15, 1, 'الم', 'البقرۃ', 'رَبَّنَا وَ ابۡعَثۡ فِیۡہِمۡ رَسُوۡلًا مِّنۡہُمۡ یَتۡلُوۡا عَلَیۡہِمۡ اٰیٰتِکَ وَ یُعَلِّمُہُمُ الۡکِتٰبَ وَ الۡحِکۡمَۃَ وَ یُزَکِّیۡہِمۡ ؕ اِنَّکَ اَنۡتَ الۡعَزِیۡزُ الۡحَکِیۡمُ ﴿۱۲۹﴾٪', 'اے پروردگار ان لوگوں میں انہیں میں سے ایک پیغمبر مبعوث کیجیو جو ان کو تیری آیتیں پڑھ پڑھ کر سنایا کرے۔ اور کتاب اور دانائی سکھایا کرے اور ان کے دلوں کو پاک صاف کیا کرے بیشک تو غالب ہے صاحب حکمت ہے۔', 'اے پروردگار ہمارے اور بھیج ان میں ایک رسول انہی میں کا کہ پڑھے ان پر تیری آیتیں اور سکھلاوے ان کو کتاب اور تہ کی باتیں اور پاک کرے ان کو بیشک تو ہی ہے بہت زبردست بڑی حکمت والا [۱۸۷]', '\"Our Lord! Send amongst them a Messenger of their own (and indeed Allah answered their invocation by sending Muhammad Peace be upon him ), who shall recite unto them Your Verses and instruct them in the Book (this Quran) and Al-Hikmah (full knowledge of the Islamic laws and jurisprudence or wisdom or Prophethood, etc.), and sanctify them. Verily! You are the All-Mighty, the All-Wise.\"', 'And, our Lord, raise in their midst a Messenger from among them, who should recite to them Your verses, and teach them the Book and the wisdom, and cleanse them of all impurities. Indeed You, and You alone, are the All-Mighty, the All-Wise.”'),
(137, 2, 130, 16, 16, 1, 'الم', 'البقرۃ', 'وَ مَنۡ یَّرۡغَبُ عَنۡ مِّلَّۃِ  اِبۡرٰہٖمَ  اِلَّا مَنۡ سَفِہَ نَفۡسَہٗ ؕ وَ لَقَدِ اصۡطَفَیۡنٰہُ فِی الدُّنۡیَا ۚ وَ اِنَّہٗ فِی الۡاٰخِرَۃِ  لَمِنَ الصّٰلِحِیۡنَ ﴿۱۳۰﴾', 'اور ابراہیم کے دین سے کون روگردانی کر سکتا ہے بجز اس کے جو نہایت نادان ہو اور ہم نے ان کو دنیا میں بھی منتخب کیا تھا۔ اور آخرت میں بھی وہ نیک لوگوں  میں ہوں گے۔', 'اور کون ہے جو پھرے ابراہیم کے مذہب سے مگر  وہی کہ جس نے احمق بنایا اپنے آپ کو اور بیشک ہم نےانکو منتخب کیا دنیا میں اور وہ آخرت میں نیکوں میں ہیں', 'And who turns away from the religion of Ibrahim (Abraham) (i.e. Islamic Monotheism) except him who befools himself? Truly, We chose him in this world and verily, in the Hereafter he will be among the righteous.', 'Who can turn away from the faith of Ibrāhīm except the one who has debased himself in folly? Indeed We have chosen him in this world. And he is certainly among the righteous in the Hereafter.'),
(138, 2, 131, 16, 16, 1, 'الم', 'البقرۃ', 'اِذۡ قَالَ لَہٗ رَبُّہٗۤ  اَسۡلِمۡ ۙ قَالَ اَسۡلَمۡتُ لِرَبِّ الۡعٰلَمِیۡنَ ﴿۱۳۱﴾', 'جب ان سے ان کے پروردگار نے فرمایا کہ میرے فرمانبردار ہو جاؤ تو انہوں نے عرض کی کہ میں رب العالمین کا فرمانبردار ہو گیا۔', 'یاد کرو جب اس کو کہا اس کے رب نے کہ حکم برداری کر تو بولا کہ میں حکم بردار ہوں تمام عالم کے پروردگار کا', 'When his Lord said to him, \"Submit (i.e. be a Muslim)!\" He said, \"I have submitted myself (as a Muslim) to the Lord of the Alameen (mankind, jinns and all that exists).\"', 'When his Lord said to him, “Submit!” He said, “I submit myself to the Lord of all the worlds.”'),
(139, 2, 132, 16, 16, 1, 'الم', 'البقرۃ', 'وَ وَصّٰی بِہَاۤ اِبۡرٰہٖمُ  بَنِیۡہِ وَ یَعۡقُوۡبُ ؕ یٰبَنِیَّ  اِنَّ اللّٰہَ اصۡطَفٰی لَکُمُ الدِّیۡنَ فَلَا تَمُوۡتُنَّ  اِلَّا وَ اَنۡتُمۡ  مُّسۡلِمُوۡنَ ﴿۱۳۲﴾ؕ', 'اور ابراہیم نے اپنے بیٹوں کو اسی بات کی وصیّت کی اور یعقوب نے بھی اپنے فرزندوں سے یہی کہا کہ اے میرے بیٹو اللہ نے تمہارے لئے یہی دین پسند فرمایا ہے تو مرنا تو مسلمان ہی مرنا۔', 'اور یہی وصیت کر گیا ابراہیم اپنے بیٹوں کو اور یعقوب بھی کہ اے بیٹو بیشک اللہ نے چن کر دیا ہے تم کو دین سو تم ہرگز نہ مرنا مگر مسلمان [۱۸۸]', 'And this (submission to Allah, Islam) was enjoined by Ibrahim (Abraham) upon his sons and by Yaqoob (Jacob), (saying), \"O my sons! Allah has chosen for you the (true) religion, then die not except in the Faith of Islam (as Muslims - Islamic Monotheism).\"', 'And Ibrāhīm exhorted the same to his sons, and so did Ya‘qūb (Jacob): “My sons, Allah has certainly chosen for you the Faith. So, let not death overtake you but as Muslims.”'),
(140, 2, 133, 16, 16, 1, 'الم', 'البقرۃ', 'اَمۡ کُنۡتُمۡ  شُہَدَآءَ  اِذۡ حَضَرَ یَعۡقُوۡبَ الۡمَوۡتُ ۙ اِذۡ  قَالَ لِبَنِیۡہِ مَا تَعۡبُدُوۡنَ مِنۡۢ بَعۡدِیۡ ؕ قَالُوۡا نَعۡبُدُ اِلٰہَکَ وَ اِلٰـہَ اٰبَآئِکَ اِبۡرٰہٖمَ  وَ  اِسۡمٰعِیۡلَ وَ  اِسۡحٰقَ  اِلٰـہًا وَّاحِدًا ۚۖ وَّ نَحۡنُ لَہٗ مُسۡلِمُوۡنَ ﴿۱۳۳﴾', 'جس وقت یعقوب وفات پانے لگے تو کیا تم اس وقت موجود تھے۔ جب انہوں نے اپنے بیٹوں سے پوچھا کہ میرے بعد تم کس کی عبادت کرو گے۔ تو انہوں نے کہا کہ آپ کے معبود اور آپ کے باپ دادا ابراہیم اور اسمٰعیل اور اسحٰق کے معبود کی عبادت کریں گے جو معبود یکتا ہے اور ہم اسی کے حکم بردار ہیں۔', 'کیا تم موجود تھے جس وقت قریب آئی یعقوب کے موت جب کہا اپنے بیٹوں کو تم کس کی عبادت کرو گے میرے بعد بولے ہم بندگی کریں گے تیرے رب کی اور تیرے باپ دادوں کے رب کی جو کہ ابراہیم اور اسمٰعیل اور اسحٰق ہیں وہی ایک معبود ہے اور ہم سب اسی کے فرمانبردار ہیں [۱۸۹]', 'Or were you witnesses when death approached Yaqoob (Jacob)? When he said unto his sons, \"What will you worship after me?\" They said, \"We shall worship your Ilah (God - Allah), the Ilah (God) of your fathers, Ibrahim (Abraham), Ismail (Ishmael), Ishaque (Isaac), One Ilah (God), and to Him we submit (in Islam).\"', 'Is it that you were present when death approached Ya‘qūb, when he said to his sons: “What will you worship after me”? They said, “We will worship your God and the God of your fathers, Ibrāhīm, Ismā‘īl (Ishmael) and IsHāq (Isaac), the one God, and to Him we submit ourselves.”'),
(141, 2, 134, 16, 16, 1, 'الم', 'البقرۃ', 'تِلۡکَ اُمَّۃٌ قَدۡ خَلَتۡ ۚ لَہَا مَا کَسَبَتۡ وَ لَکُمۡ مَّا کَسَبۡتُمۡ ۚ وَ لَا تُسۡـَٔلُوۡنَ عَمَّا  کَانُوۡا یَعۡمَلُوۡنَ ﴿۱۳۴﴾', 'یہ جماعت گذر چکی ان کو ان کے اعمال کا بدلہ ملے گا اور تم کو تمہارے اعمال کا اور جو عمل وہ کرتے تھے ان کی پرسش تم سے نہیں ہو گی۔', 'وہ ایک جماعت تھی جو گذر چکی انکے واسطے ہے جو انہوں نے کیا اور تمہارے واسطے ہے جو تم نے کیا اور تم سے پوچھ نہیں ان کے کاموں کی [۱۹۰]', 'That was a nation who has passed away. They shall receive the reward of what they earned and you of what you earn. And you will not be asked of what they used to do.', 'Those are a people who have passed away. For them is what they earned, and for you is what you earned. Nor shall you be questioned as to what they have been doing.'),
(142, 2, 135, 16, 16, 1, 'الم', 'البقرۃ', 'وَ قَالُوۡا کُوۡنُوۡا ہُوۡدًا اَوۡ نَصٰرٰی تَہۡتَدُوۡا ؕ قُلۡ بَلۡ مِلَّۃَ  اِبۡرٰہٖمَ  حَنِیۡفًا ؕ وَ مَا کَانَ مِنَ الۡمُشۡرِکِیۡنَ ﴿۱۳۵﴾', 'اور یہودی اور عیسائی کہتے ہیں کہ یہودی یا عیسائی ہو جاؤ تو سیدھے رستے پر لگ جاؤ گے اے پیغمبر ان سے کہہ دو نہیں بلکہ ہم دین ابراہیم اختیار کئے ہوئے ہیں جو ایک اللہ کے ہو رہے تھے اور مشرکوں میں سے نہ تھے۔', 'اور کہتے ہیں کہ ہو جاؤ یہودی یا نصرانی تو تم پالو گے راہ راست [۱۹۱] کہدے کہ ہر گز نہیں بلکہ ہم نے اختیار کی راہ ابراہیم کی جو ایک ہی طرف کا تھا اور نہ تھا شرک کرنے والوں میں [۱۹۲]', 'And they say, \"Be Jews or Christians, then you will be guided.\" Say (to them, O Muhammad Peace be upon him ), \"Nay, (We follow) only the religion of Ibrahim (Abraham), Hanifa (Islamic Monotheism, i.e. to worship none but Allah (Alone)), and he was not of Al-Mushrikoon (those who worshipped others along with Allah - see V.2:105).\"', 'They said, “Become Jews or Christians, and you will find the right path.” Say: “Instead, (we follow) the faith of Ibrāhīm, the upright, - and he was not one of those who associate partners with Allah.”'),
(143, 2, 136, 16, 16, 1, 'الم', 'البقرۃ', 'قُوۡلُوۡۤا اٰمَنَّا بِاللّٰہِ وَ مَاۤ اُنۡزِلَ اِلَیۡنَا وَ مَاۤ اُنۡزِلَ  اِلٰۤی  اِبۡرٰہٖمَ  وَ  اِسۡمٰعِیۡلَ وَ  اِسۡحٰقَ وَ یَعۡقُوۡبَ وَ الۡاَسۡبَاطِ وَ مَاۤ اُوۡتِیَ مُوۡسٰی وَ عِیۡسٰی وَ مَاۤ اُوۡتِیَ النَّبِیُّوۡنَ مِنۡ  رَّبِّہِمۡ ۚ  لَا نُفَرِّقُ بَیۡنَ اَحَدٍ مِّنۡہُمۡ ۫ۖ وَ نَحۡنُ لَہٗ مُسۡلِمُوۡنَ ﴿۱۳۶﴾', 'مسلمانو کہو کہ ہم اللہ پر ایمان لائے اور جو کتاب ہم پر اتری اس پر اور جو صحیفے ابراہیم اور اسمٰعیل اور اسحٰق اور یعقوب اور ان کی اولاد پر نازل ہوئے ان پر اور جو کتابیں موسٰی اور عیسٰی کو عطا ہوئیں ان پر اور جو دوسرے پیغمبروں کو انکے پروردگار کی طرف سے ملیں ان پر سب پر ایمان لائے ہم ان پیغمبروں میں سے کسی میں کچھ فرق نہیں کرتے اور ہم اسی معبود واحد کے فرمانبردار ہیں۔', 'تم کہہ دو کہ ہم ایمان لائے اللہ پر اور جو اترا ہم پر اور جو اترا ابراہیم اور اسمٰعیل اور اسحٰق اور یعقوب اور اس کی اولاد پر اور جو ملا موسٰی کو اور عیسٰی کو اور جو ملا دوسرے پیغمبروں کو انکے رب کی طرف سے ہم فرق نہیں کرتے ان سب میں سے ایک میں بھی اور ہم اسی پروردگار کے فرمانبردار ہیں [۱۹۳]', 'Say (O Muslims), \"We believe in Allah and that which has been sent down to us and that which has been sent down to Ibrahim (Abraham), Ismail (Ishmael), Ishaque (Isaac), Yaqoob (Jacob), and to Al-Asbat (the twelve sons of Yaqoob (Jacob)), and that which has been given to Moosa (Moses) and Iesa (Jesus), and that which has been given to the Prophets from their Lord. We make no distinction between any of them, and to Him we have submitted (in Islam).\"', 'Say (O, Muslims): “We believe in Allah, and in what has been revealed to us, and in what has been revealed to Ibrāhīm, Ismā‘īl (Ishmael), IsHāq (Isaac), Ya‘qūb and his children, and in what has been given to Mūsā and ‘Īsā (Jesus) and what has been given to the prophets from their Lord: We make no difference between any of them, and to Him we submit ourselves.”'),
(144, 2, 137, 16, 16, 1, 'الم', 'البقرۃ', 'فَاِنۡ اٰمَنُوۡا بِمِثۡلِ مَاۤ  اٰمَنۡتُمۡ  بِہٖ فَقَدِ اہۡتَدَوۡا ۚ وَ اِنۡ تَوَلَّوۡا فَاِنَّمَا ہُمۡ فِیۡ شِقَاقٍ ۚ فَسَیَکۡفِیۡکَہُمُ اللّٰہُ ۚ وَ ہُوَ السَّمِیۡعُ  الۡعَلِیۡمُ ﴿۱۳۷﴾ؕ', 'پھر اگر یہ لوگ بھی اسی طرح ایمان لے آئیں جس طرح تم ایمان لے آئے ہو تو ہدایت یاب ہو جائیں اور اگر منہ پھیر لیں اور نہ مانیں تو وہ تمہارے مخالف ہیں۔ اور انکے مقابلے میں تمہیں اللہ کافی ہے اور وہ سننے والا ہے جاننے والا ہے۔', 'سو اگر وہ ابھی ایمان لاویں جس طرح پر تم ایمان لائے ہدایت پائی انہوں نے بھی اور اگر پھر جاویں تو پھر وہی ہیں ضد پر سو اب کافی ہے تیری طرف سے ان کو اللہ اور وہی ہے سننے والا جاننے والا [۱۹۴]', 'So if they believe in the like of that which you believe, then they are rightly guided, but if they turn away, then they are only in opposition. So Allah will suffice you against them. And He is the All-Hearer, the All-Knower.', 'So, if they believe in the same way as you believe, they will have certainly found the right path, and if they turn away, then the fact is that they are in antagonism. Then Allah will suffice you against them, and He is the All-Hearing, the All-Knowing.'),
(145, 2, 138, 16, 16, 1, 'الم', 'البقرۃ', 'صِبۡغَۃَ اللّٰہِ ۚ وَ مَنۡ اَحۡسَنُ مِنَ اللّٰہِ صِبۡغَۃً  ۫ وَّ نَحۡنُ لَہٗ عٰبِدُوۡنَ ﴿۱۳۸﴾', 'کہہ دو کہ ہم نے اللہ کا رنگ اختیار کر لیا ہے اور اللہ سے بہتر رنگ کس کا ہو سکتا ہے۔ اور ہم اسی کی عبادت کرنے والے ہیں۔', 'ہم نے قبول کر لیا رنگ اللہ کا اور کس کا رنگ بہتر ہے اللہ کے رنگ سے اور ہم اسی کی بندگی کرتے ہیں [۱۹۵]', '(Our Sibghah (religion) is) the Sibghah (Religion) of Allah (Islam) and which Sibghah (religion) can be better than Allahs? And we are His worshippers. (Tafsir Ibn Katheer.)', '(We dye ourselves with) the colouring of Allah! For who is better in colouring than Allah? We are to worship none but Him.'),
(146, 2, 139, 16, 16, 1, 'الم', 'البقرۃ', 'قُلۡ اَتُحَآجُّوۡنَنَا فِی اللّٰہِ وَ ہُوَ رَبُّنَا وَ رَبُّکُمۡ ۚ وَ لَنَاۤ اَعۡمَالُنَا وَ لَکُمۡ اَعۡمَالُکُمۡ ۚ وَ نَحۡنُ لَہٗ  مُخۡلِصُوۡنَ ﴿۱۳۹﴾ۙ', 'ان سے کہو کیا تم اللہ کے بارے میں ہم سے جھگڑتے ہو حالانکہ وہی ہمارا اور تمہارا پروردگار ہے اور ہم کو ہمارے اعمال کا بدلہ ملے گا اور تم کو تمہارے اعمال کا اور ہم خاص اسی کی عبادت کرنے والے ہیں۔', 'کہدے کیا تم جھگڑا کرتے ہو ہم سے اللہ کی نسبت حالانکہ وہی ہےرب ہمارا اور رب تمہارا اور ہمارےلئے ہیں عمل ہمارے اور تمہارے لئے ہیں عمل تمہارے اور ہم تو خالص اسی کے ہیں [۱۹۶]', 'Say (O Muhammad Peace be upon him to the Jews and Christians), \"Dispute you with us about Allah while He is our Lord and your Lord? And we are to be rewarded for our deeds and you for your deeds. And we are sincere to Him in worship and obedience (i.e. we worship Him Alone and none else, and we obey His Orders).\"', 'Say: “Would you argue with us about Allah, when He is our Lord as well as your Lord? For us our deeds, and for you your deeds! And we are faithful to Him.'),
(147, 2, 140, 16, 16, 1, 'الم', 'البقرۃ', 'اَمۡ  تَقُوۡلُوۡنَ  اِنَّ  اِبۡرٰہٖمَ  وَ اِسۡمٰعِیۡلَ وَ اِسۡحٰقَ وَ یَعۡقُوۡبَ وَ الۡاَسۡبَاطَ کَانُوۡا ہُوۡدًا اَوۡ نَصٰرٰی ؕ قُلۡ ءَاَنۡتُمۡ  اَعۡلَمُ اَمِ اللّٰہُ ؕ وَ مَنۡ اَظۡلَمُ مِمَّنۡ کَتَمَ شَہَادَۃً عِنۡدَہٗ مِنَ اللّٰہِ ؕ وَ مَا اللّٰہُ بِغَافِلٍ عَمَّا تَعۡمَلُوۡنَ ﴿۱۴۰﴾', 'اے یہود و نصارٰی کیا تم اس بات کے قائل ہو کہ ابراہیم اور اسمٰعیل اور اسحٰق اور یعقوب اور ان کی اولاد  یہودی یا عیسائی تھے اے پیغمبر ان سے کہو کہ بھلا تم زیادہ جانتے ہو یا اللہ؟ اور اس سے بڑھ کر ظالم کون جو اللہ کی شہادت کو جو اس کے پاس کتاب میں موجود ہے چھپائے اور جو کچھ تم لوگ کر رہے ہو اللہ اس سے غافل نہیں۔', 'کیا تم کہتے ہو کہ ابراہیم اور اسمٰعیل اور اسحٰق او ریعقوب اور اس کی اولاد تو یہودی تھے یا نصرانی کہدے کہ تم کو زیادہ خبر ہے یا اللہ کو اور اس سے بڑا ظالم کون جس نے چھپائی وہ گواہی جو ثابت ہو چکی اس کو اللہ کی طرف سے اور اللہ بیخبر نہیں تمہارے کاموں سے [۱۹۷]', 'Or say you that Ibrahim (Abraham), Ismail (Ishmael), Ishaque (Isaac), Yaqoob (Jacob) and Al-Asbat (the twelve sons of Yaqoob (Jacob)) were Jews or Christians? Say, \"Do you know better or does Allah (knows better… that they all were Muslims)? And who is more unjust than he who conceals the testimony (i.e. to believe in Prophet Muhammad Peace be upon him when he comes, written in their Books. (See Verse 7:157)) he has from Allah? And Allah is not unaware of what you do.\"', 'Or, would you say that Ibrāhīm, Ismā‘īl, IsHāq, Ya‘qūb and their children were Jews or Christians?” Say: “Do you know better or does Allah?” Who can be more unjust than the one who conceals the testimony he has from Allah? Allah is not unaware of what you do.'),
(148, 2, 141, 16, 16, 1, 'الم', 'البقرۃ', 'تِلۡکَ اُمَّۃٌ  قَدۡ خَلَتۡ ۚ لَہَا مَا کَسَبَتۡ وَ لَکُمۡ مَّا کَسَبۡتُمۡ ۚ وَ لَا تُسۡـَٔلُوۡنَ عَمَّا  کَانُوۡا  یَعۡمَلُوۡنَ ﴿۱۴۱﴾٪', 'یہ انبیاء کی جماعت گذر چکی۔ ان کو وہ ملے گا جو انہوں نے کیا اور تم کو وہ جو تم نے کیا اور جو عمل وہ کرتے تھے ان کی پرسش تم سے نہیں ہو گی۔', 'وہ ایک جماعت تھی جو گذر چکی ان کے واسطے ہے جو انہوں نے کیا اور تمہارے واسطے ہے جو تم نے کیا اور تم سے کچھ پوچھ نہیں ان کے کاموں کی [۱۹۸]', 'That was a nation who has passed away. They shall receive the reward of what they earned, and you of what you earn. And you will not be asked of what they used to do.', 'Those are a people who have passed away. For them is what they earned, and for you is what you earned, and you shall not be questioned about what they have been doing.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(149, 2, 142, 17, 1, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'سَیَقُوۡلُ السُّفَہَآءُ مِنَ النَّاسِ مَا وَلّٰىہُمۡ عَنۡ قِبۡلَتِہِمُ الَّتِیۡ کَانُوۡا عَلَیۡہَا ؕ قُلۡ لِّلّٰہِ الۡمَشۡرِقُ وَ الۡمَغۡرِبُ ؕ یَہۡدِیۡ مَنۡ  یَّشَآءُ  اِلٰی صِرَاطٍ مُّسۡتَقِیۡمٍ ﴿۱۴۲﴾', 'احمق لوگ کہیں گے کہ مسلمان جس قبلے پر  پہلے سے چلے آتے تھے اب اس سے کیوں منہ پھیر بیٹھے تم کہہ دو کہ مشرق اور مغرب سب اللہ ہی کا ہے وہ جس کو چاہتا ہے سیدھے رستے پر چلاتا ہے۔', 'اب کہیں گے بیوقوف لوگ کہ کس چیز نے پھیر دیا مسلمانوں کو انکے قبلہ سےجس پر وہ تھے [۱۹۹] تو کہہ اللہ ہی کا ہے مشرق اور مغرب چلائے جس کو چاہے سیدھی راہ [۲۰۰]', 'The fools (pagans, hypocrites, and Jews) among the people will say, \"What has turned them (Muslims) from their Qiblah (prayer direction (towards Jerusalem)) to which they were used to face in prayer.\" Say, (O Muhammad SAW) \"To Allah belong both, east and the west. He guides whom He wills to a Straight Way.\"', 'The foolish among the people will say: “What has turned them away from their Qiblah which they used to observe?” Say: “To Allah belong the East and the West. He guides whom He wills to a straight path.”'),
(150, 2, 143, 17, 1, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ کَذٰلِکَ جَعَلۡنٰکُمۡ اُمَّۃً وَّسَطًا لِّتَکُوۡنُوۡا شُہَدَآءَ عَلَی النَّاسِ وَ یَکُوۡنَ الرَّسُوۡلُ عَلَیۡکُمۡ شَہِیۡدًا ؕ وَ مَا جَعَلۡنَا الۡقِبۡلَۃَ الَّتِیۡ کُنۡتَ عَلَیۡہَاۤ  اِلَّا لِنَعۡلَمَ مَنۡ یَّتَّبِعُ الرَّسُوۡلَ مِمَّنۡ یَّنۡقَلِبُ عَلٰی عَقِبَیۡہِ ؕ وَ اِنۡ کَانَتۡ لَکَبِیۡرَۃً  اِلَّا عَلَی الَّذِیۡنَ ہَدَی اللّٰہُ  ؕ وَ مَا کَانَ اللّٰہُ لِیُضِیۡعَ اِیۡمَانَکُمۡ ؕ اِنَّ اللّٰہَ بِالنَّاسِ لَرَءُوۡفٌ رَّحِیۡمٌ ﴿۱۴۳﴾', 'اسی طرح ہم نے تم کو امت معتدل بنایا ہے تاکہ تم لوگوں پر گواہ بنو اور پیغمبر آخرالزماں ﷺ تم پر گواہ بنیں۔ اور جس قبلے پر تم پہلے تھے اس کو ہم نے اس لئے مقرر کیا تھا کہ معلوم کریں کہ کون ہمارے پیغمبر کا تابع رہتا ہے اور کون الٹے پاؤں پھر جاتا ہے۔ اور یہ بات یعنی تحویل قبلہ لوگوں کو گراں معلوم ہوئی مگر جنکو اللہ نے ہدایت بخشی ہے وہ اسے گراں نہیں سمجھتے اور اللہ ایسا نہیں کہ تمہارے ایمان کو یونہی ضائع دے۔ اللہ تو لوگوں پر بڑا مہربان ہے صاحب رحمت ہے۔', 'اور اسی طرح کیا ہم نے تم کو امت معتدل تاکہ ہو تم گواہ لوگوں پر اور ہو رسول تم پر گواہی دینے والا [۲۰۱] اور نہیں مقرر کیا تھا ہم نے وہ قبلہ کہ جس پر تو پہلے تھا مگر اس واسطے کہ معلوم کریں کون تابع رہے گا رسول کا اور کون پھر جائے گا الٹے پاؤں [۲۰۲] اور بیشک یہ بات بھاری ہوئی مگر ان پر جن کو راہ دکھائی اللہ نے [۲۰۳] اور اللہ ایسا نہیں کہ ضائع کرے تمہارا ایمان بیشک اللہ لوگوں پر بہت شفیق نہایت مہربان ہے [۲۰۴]', 'Thus We have made you (true Muslims - real believers of Islamic Monotheism, true followers of Prophet Muhammad SAW and his Sunnah (legal ways)), a Wasat (just) (and the best) nation, that you be witnesses over mankind and the Messenger (Muhammad SAW) be a witness over you. And We made the Qiblah (prayer direction towards Jerusalem) which you used to face, only to test those who followed the Messenger (Muhammad SAW) from those who would turn on their heels (i.e. disobey the Messenger). Indeed it was great (heavy) except for those whom Allah guided. And Allah would never make your faith (prayers) to be lost (i.e. your prayers offered towards Jerusalem). Truly, Allah is full of kindness, the Most Merciful towards mankind.', 'In the same way We made you a moderate Ummah (community), so that you should be witnesses over the people, and the Messenger a witness to you.And We did not prescribe the Qiblah which you used to observe except to know the one who follows the Messenger as distinct from the one who turns on his heels. It was burdensome indeed, but not on those whom Allah guided. Allah will not allow your faith go to waste. Certainly Allah is very kind, very merciful to the people.'),
(151, 2, 144, 17, 1, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'قَدۡ نَرٰی تَقَلُّبَ وَجۡہِکَ فِی السَّمَآءِ ۚ فَلَنُوَلِّیَنَّکَ قِبۡلَۃً  تَرۡضٰہَا  ۪  فَوَلِّ وَجۡہَکَ شَطۡرَ الۡمَسۡجِدِ الۡحَرَامِ ؕ  وَ حَیۡثُ مَا کُنۡتُمۡ   فَوَلُّوۡا  وُجُوۡہَکُمۡ شَطۡرَہٗ ؕ وَ  اِنَّ الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ لَیَعۡلَمُوۡنَ اَنَّہُ  الۡحَقُّ مِنۡ رَّبِّہِمۡ ؕ وَ مَا اللّٰہُ بِغَافِلٍ عَمَّا یَعۡمَلُوۡنَ ﴿۱۴۴﴾', 'اے پیغمبر ﷺ ہم تمہارا آسمان کی طرف منہ اٹھانا دیکھ رہے ہیں سو ہم تم کو اسی قبلے کی طرف جس کو تم پسند کرتے ہو منہ کرنے کا حکم دیں گے تو اپنا منہ مسجد حرام یعنی خانہ کعبہ کی طرف پھیر لو۔ اور تم لوگ جہاں ہوا کرو نماز پڑھنے کے وقت اسی مسجد کی طرف منہ کر لیا کرو اور جن لوگوں کو کتاب دی گئ ہے وہ خوب جانتے ہیں کہ یہ نیا قبلہ انکے پروردگار کی طرف سے حق ہے۔ اور جو کام یہ لوگ کرتے ہیں اللہ ان سے بے خبر نہیں۔', 'بیشک ہم دیکھتے ہیں باربار اٹھنا تیرے منہ کا آسمان کی طرف سو البتہ پھیر یں گے ہم تجھ کو جس قبلہ کی طرف تو راضی ہے [۲۰۵] اب پھیر منہ اپنا طرف مسجد الحرام کے [۲۰۶] اور جس جگہ تم ہوا کرو پھیرو منہ اسی کی طرف [۲۰۷] اور جن کو ملی ہے کتاب البتہ جانتے ہیں کہ یہ ہی ٹھیک ہے انکے رب کی طرف سے اور اللہ بے خبر نہیں ان کاموں سے جو وہ کرتے ہیں [۲۰۸]', 'Verily! We have seen the turning of your (Muhammads SAW) face towards the heaven. Surely, We shall turn you to a Qiblah (prayer direction) that shall please you, so turn your face in the direction of Al-Masjid- al-Haram (at Makkah). And wheresoever you people are, turn your faces (in prayer) in that direction. Certainly, the people who were given the Scriptures (i.e. Jews and the Christians) know well that, that (your turning towards the direction of the Kabah at Makkah in prayers) is the truth from their Lord. And Allah is not unaware of what they do.', 'We have been seeing you turning your face to the heavens. So, We will certainly assign to you a Qiblah that you would like. Now, turn your face in the direction of the Sacred Mosque (Al-Masjid-ul-Harām), and (O Muslims), wherever you are, turn your faces in its direction. Even those who have been given the Book know well that it is the truth from their Lord, and Allah is not unaware of what they do.'),
(152, 2, 145, 17, 1, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ لَئِنۡ اَتَیۡتَ الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ بِکُلِّ اٰیَۃٍ مَّا تَبِعُوۡا قِبۡلَتَکَ ۚ وَ مَاۤ اَنۡتَ بِتَابِعٍ قِبۡلَتَہُمۡ ۚ وَ مَا بَعۡضُہُمۡ  بِتَابِعٍ قِبۡلَۃَ بَعۡضٍ ؕ وَ لَئِنِ اتَّبَعۡتَ اَہۡوَآءَہُمۡ مِّنۡۢ بَعۡدِ مَا جَآءَکَ مِنَ الۡعِلۡمِ  ۙ اِنَّکَ اِذًا  لَّمِنَ الظّٰلِمِیۡنَ ﴿۱۴۵﴾ۘ', 'اور اگر تم ان اہل کتاب کے پاس تمام نشانیاں بھی لے کر آؤ تو بھی یہ تمہارے قبلے کی پیروی نہ کریں اور تم بھی ان کے قبلے کی پیروی کرنے والے نہیں ہو۔ اور ان میں سے بھی بعض بعض کے قبلے کے پیرو نہیں۔ اور اگر تم باوجود اس کے کہ تمہارے پاس علم یعنی اللہ کا حکم آ چکا  ہے ان کی خواہشوں کے پیچھے چلو گے تو ظالموں میں ہو جاؤ گے۔', 'اور اگر تو لائے اہل کتاب کےپاس ساری نشانیاں تو بھی نہ مانیں گے تیرے قبلہ کو اور نہ تو مانے ان کا قبلہ اور نہ ان میں ایک مانتا ہے دوسرے کا قبلہ [۲۰۹] اور اگر تو چلا ان کی خواہشوں پر بعد اس علم کے جو تجھ کو پہنچا تو بیشک تو بھی ہوا بے انصافوں میں [۲۱۰]', 'And even if you were to bring to the people of the Scripture (Jews and Christians) all the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), they would not follow your Qiblah (prayer direction), nor are you going to follow their Qiblah (prayer direction). And they will not follow each others Qiblah (prayer direction). Verily, if you follow their desires after that which you have received of knowledge (from Allah), then indeed you will be one of the Zalimoon (polytheists, wrong-doers, etc.).', 'Even if you bring every sign to those who have been given the Book, they would not follow your Qiblah, and you are not to follow their Qiblah, nor are they to follow each other’s Qiblah. If you were to follow their desires despite the knowledge that has come to you, you will then certainly be among the unjust.'),
(153, 2, 146, 17, 1, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اَلَّذِیۡنَ اٰتَیۡنٰہُمُ الۡکِتٰبَ یَعۡرِفُوۡنَہٗ کَمَا یَعۡرِفُوۡنَ اَبۡنَآءَہُمۡ ؕ وَ اِنَّ فَرِیۡقًا مِّنۡہُمۡ لَیَکۡتُمُوۡنَ الۡحَقَّ وَ ہُمۡ یَعۡلَمُوۡنَ ﴿۱۴۶﴾ؔ', 'جن لوگوں کو ہم نے کتاب دی ہے وہ ان پیغمبر آخرالزماں ﷺ کو اس طرح پہچانتے ہیں جس طرح اپنے بیٹوں کو پہچانا کرتے ہیں مگر ایک فریق ان میں سے سچّی بات کو جان بوجھ کر چھپا رہا ہے۔', 'جن کو ہم نے دی ہے کتاب پہچانتے ہیں اس کو جیسے پہچانتے ہیں اپنے بیٹوں کو اور بیشک ایک فرقہ ان میں سے البتہ چھپاتے ہیں حق کو جان کر', 'Those to whom We gave the Scripture (Jews and Christians) recognise him (Muhammad SAW or the Kabah at Makkah) as they recongise their sons. But verily, a party of them conceal the truth while they know it - (i.e. the qualities of Muhammad SAW which are written in the Taurat (Torah) and the Injeel (Gospel)).', 'Those whom We have given the Book recognize him (the Holy Prophet) as they recognize their own sons. In fact, a group of them conceals the truth, while they know (it).'),
(154, 2, 147, 17, 1, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اَلۡحَقُّ  مِنۡ رَّبِّکَ فَلَا تَکُوۡنَنَّ مِنَ الۡمُمۡتَرِیۡنَ ﴿۱۴۷﴾٪', 'اے پیغمبر ﷺ یہ نیا قبلہ تمہارے پروردگار کی طرف سے حق ہے تو تم ہر گز شک کرنے والوں میں نہ ہونا۔', 'حق تو وہی ہے جو تیرا رب کہے پھر تو نہ ہو شک لانے والا [۲۱۱]', 'This is) the truth from your Lord. So be you not one of those who doubt.', 'The truth is from your Lord. So, never be among those who doubt (it).”'),
(155, 2, 148, 18, 2, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ  لِکُلٍّ وِّجۡہَۃٌ ہُوَ مُوَلِّیۡہَا فَاسۡتَبِقُوا الۡخَیۡرٰتِ ؕ؃ اَیۡنَ مَا تَکُوۡنُوۡا یَاۡتِ بِکُمُ اللّٰہُ جَمِیۡعًا ؕ اِنَّ اللّٰہَ عَلٰی کُلِّ شَیۡءٍ قَدِیۡرٌ ﴿۱۴۸﴾', 'اور ہر ایک شخص کے لئے ایک سمت مقرر ہے جدھر وہ عبادت کے وقت منہ کیا کرتا ہے تو تم نیکیوں میں سبقت حاصل کرو۔ تم جہاں ہو گے اللہ تم سب کو جمع کرے گا بیشک اللہ ہر چیز پر قادر ہے۔', 'اور ہر کسی کے واسطے ایک جانب ہے یعنی قبلہ کہ وہ منہ کرتا ہے اس طرف سو تم سبقت کرو نیکیوں میں جہاں کہیں تم ہو گے کر لائے گا تم کو اللہ اکٹھا بیشک اللہ ہر چیز کر سکتا ہے [۲۱۲]', 'For every nation there is a direction to which they face (in their prayers). So hasten towards all that is good. Wheresoever you may be, Allah will bring you together (on the Day of Resurrection). Truly, Allah is Able to do all things.', 'For everyone there is a direction to which he turns his face. Strive, then, to excel each other in good deeds. Wherever you are, Allah will bring you all together. Allah is certainly powerful over everything.'),
(156, 2, 149, 18, 2, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ مِنۡ حَیۡثُ خَرَجۡتَ فَوَلِّ وَجۡہَکَ شَطۡرَ الۡمَسۡجِدِ الۡحَرَامِ ؕ وَ اِنَّہٗ  لَلۡحَقُّ مِنۡ رَّبِّکَ ؕ وَ مَا اللّٰہُ بِغَافِلٍ عَمَّا تَعۡمَلُوۡنَ ﴿۱۴۹﴾', 'اور تم جہاں سے نکلو نماز میں اپنا منہ مسجد حرام کی طرف کر لیا کرو۔ بے شبہ  یہ تمہارے پروردگار کی طرف سے حق ہے۔ اور تم لوگ جو کچھ کرتے ہو اللہ اس سے بے خبر نہیں۔', 'اور جس جگہ سے تو نکلے سو منہ کر اپنا مسجدالحرام کی طرف اور بیشک یہ حق ہے تیرے رب کی طرف سے اور اللہ بیخبر نہیں تمہارےکاموں سے', 'And from wheresoever you start forth (for prayers), turn your face in the direction of Al-Masjid-al-Haram (at Makkah), that is indeed the truth from your Lord. And Allah is not unaware of what you do.', 'From wherever you set out, turn your face in the direction of the Sacred Mosque (Al-Masjid-ul-Harām). That, indeed, is the truth from your Lord, and Allah is not unaware of what you do.'),
(157, 2, 150, 18, 2, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ مِنۡ حَیۡثُ خَرَجۡتَ فَوَلِّ وَجۡہَکَ شَطۡرَ الۡمَسۡجِدِ الۡحَرَامِ ؕ وَ حَیۡثُ مَا کُنۡتُمۡ  فَوَلُّوۡا وُجُوۡہَکُمۡ شَطۡرَہٗ  ۙ لِئَلَّا یَکُوۡنَ  لِلنَّاسِ عَلَیۡکُمۡ حُجَّۃٌ ٭ۙ اِلَّا الَّذِیۡنَ ظَلَمُوۡا مِنۡہُمۡ ٭ فَلَا تَخۡشَوۡہُمۡ وَ اخۡشَوۡنِیۡ ٭ وَ لِاُتِمَّ  نِعۡمَتِیۡ عَلَیۡکُمۡ وَ لَعَلَّکُمۡ تَہۡتَدُوۡنَ ﴿۱۵۰﴾ۙۛ', 'اور تم جہاں سے نکلو مسجد حرام کی طرف منہ کر کے نماز پڑھا کرو۔ اور مسلمانو تم جہاں ہوا کرو اسی مسجد کی طرف رخ کیا کرو یہ تاکید اس لئے کی گئ ہے کہ لوگ تم کو کسی طرح کا الزام نہ دے سکیں۔ مگر ان میں سے جو ظالم ہیں وہ الزام دیں تو دیں سو ان سے مت ڈرنا اور مجھی سے ڈرتے رہنا۔ اور یہ بھی مقصود ہے کہ میں تم کو اپنی تمام نعمتیں بخشوں اور یہ بھی کہ تم راہ راست پر چلو۔', 'اور جہاں سے تو نکلے منہ کر اپنا مسجدالحرام کی طرف اور جس جگہ تم ہوا کرو منہ کرو اسی کی طرف [۲۱۳] تاکہ نہ رہے لوگوں کو تم سے جگھڑنے کا موقع مگر جو ان میں بے انصاف ہیں سو ان سے [یعنی انکے اعتراضوں سے] مت ڈرو  اور مجھ سے ڈرو [۲۱۴] اور اس واسطے کہ کامل کروں تم پر فضل اپنا اور تاکہ تم پاؤ راہ سیدھی [۲۱۵]', 'And from wheresoever you start forth (for prayers), turn your face in the direction of Al-Masjid-al-Haram (at Makkah), and wheresoever you are, turn your faces towards, it (when you pray) so that men may have no argument against you except those of them that are wrong-doers, so fear them not, but fear Me! - And so that I may complete My Blessings on you and that you may be guided.', 'And from wherever you set out, turn your face in the direction of the Sacred Mosque (Al-Masjid-ul-Harām), and (O Muslims), wherever you are, turn your faces in its direction, so that people should have no argument against you, except for those among them who are unjust,- do not fear them, but fear Me-, and so that I should perfect My blessings upon you, and that you may take the right path.'),
(158, 2, 151, 18, 2, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'کَمَاۤ  اَرۡسَلۡنَا فِیۡکُمۡ رَسُوۡلًا مِّنۡکُمۡ یَتۡلُوۡا عَلَیۡکُمۡ  اٰیٰتِنَا وَ یُزَکِّیۡکُمۡ وَ یُعَلِّمُکُمُ الۡکِتٰبَ وَ الۡحِکۡمَۃَ وَ یُعَلِّمُکُمۡ مَّا لَمۡ تَکُوۡنُوۡا تَعۡلَمُوۡنَ ﴿۱۵۱﴾ؕۛ', 'جس طرح منجملہ اور نعمتوں کے ہم نے تم میں تمہیں میں سے ایک رسول بھیجے ہیں جو تم کو ہماری آیتیں پڑھ پڑھ کے سناتے اور تمہیں پاک بناتے اور کتاب یعنی قرآن اور دانائی سکھاتے ہیں اور ایسی باتیں بتاتے ہیں جو تم پہلے نہیں جانتے تھے۔', 'جیسا کہ بھیجا ہم نے تم میں رسول تم ہی میں کا پڑھتا ہے تمہارے آگے آیتیں ہماری اور پاک کرتا ہے تم کو اور سکھلاتا ہے تم کو کتاب اور اس کے اسرار اور  سکھلاتا ہے تم کو جو تم نہ جانتے تھے [۲۱۶]', 'Similarly (to complete My Blessings on you) We have sent among you a Messenger (Muhammad SAW) of your own, reciting to you Our Verses (the Quran) and sanctifying you, and teaching you the Book (the Quran) and the Hikmah (i.e. Sunnah, Islamic laws and Fiqh - jurisprudence), and teaching you that which you used not to know.', 'As also We have sent in your midst a messenger from among you, who recites to you Our verses, and purifies you, and teaches you the Book and the wisdom, and teaches you what you did not know.'),
(159, 2, 152, 18, 2, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'فَاذۡکُرُوۡنِیۡۤ اَذۡکُرۡکُمۡ  وَ اشۡکُرُوۡا لِیۡ وَ لَا تَکۡفُرُوۡنِ ﴿۱۵۲﴾٪', 'سو تم مجھے یاد کیا کرو میں تمہیں یاد کیا کروں گا اور میرا احسان مانتے رہنا اور میری نا شکری نہ کرنا۔', 'سو تم یاد رکھو مجھ کو میں یاد رکھوں تم کو اور احسان مانو میرا اور ناشکری مت کرو [۲۱۷]', 'Therefore remember Me (by praying, glorifying, etc.). I will remember you, and be grateful to Me (for My countless Favours on you) and never be ungrateful to Me.', 'So Remember Me, and I will remember you, and be thankful to Me, and be not ungrateful to Me.'),
(160, 2, 153, 19, 3, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوا اسۡتَعِیۡنُوۡا بِالصَّبۡرِ وَ الصَّلٰوۃِ ؕ اِنَّ اللّٰہَ مَعَ الصّٰبِرِیۡنَ ﴿۱۵۳﴾', 'اے ایمان والو صبر اور نماز سے مدد لیا کرو۔ بیشک اللہ صبر کرنے والوں کے ساتھ ہے۔', 'اے مسلمانو مدد لو صبر اور نماز سے بیشک اللہ صبر کرنے والوں کے ساتھ ہے [۲۱۸]', 'O you who believe! Seek help in patience and As-Salat (the prayer). Truly! Allah is with As-Sabirin (the patient ones, etc.).', 'O you who believe, seek help through patience and prayer. Surely, Allah is with those who are patient.'),
(161, 2, 154, 19, 3, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ لَا تَقُوۡلُوۡا لِمَنۡ یُّقۡتَلُ فِیۡ سَبِیۡلِ اللّٰہِ اَمۡوَاتٌ ؕ بَلۡ اَحۡیَآءٌ وَّ لٰکِنۡ لَّا تَشۡعُرُوۡنَ ﴿۱۵۴﴾', 'اور جو لوگ اللہ کی راہ میں مارے جائیں ان کی نسبت یہ نہ کہنا کہ وہ مرے ہوئے ہیں وہ مردہ نہیں بلکہ زندہ ہیں لیکن تم کو شعور نہیں۔', 'اور نہ کہو ان کو جو مارے گئے خدا کی راہ میں کہ مردے ہیں بلکہ وہ زندے ہیں لیکن تم کو خبر نہیں [۲۱۹]', 'And say not of those who are killed in the Way of Allah, \"They are dead.\" Nay, they are living, but you perceive (it) not.', 'Do not say of those who are slain in the way of Allah that they are dead. Instead, they are alive, but you do not perceive.'),
(162, 2, 155, 19, 3, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ لَنَبۡلُوَنَّکُمۡ بِشَیۡءٍ مِّنَ الۡخَوۡفِ وَ الۡجُوۡعِ وَ نَقۡصٍ مِّنَ الۡاَمۡوَالِ وَ الۡاَنۡفُسِ وَ الثَّمَرٰتِ ؕ وَ بَشِّرِ الصّٰبِرِیۡنَ ﴿۱۵۵﴾ۙ', 'اور ہم کسی قدر خوف اور بھوک اور مال اور جانوں اور میووں کے نقصان سے تمہاری آزمائش کریں گے اور صبر کرنے والوں کو بشارت سنا دو۔', 'اور البتہ ہم آزمائیں گے تم کو تھوڑے سے ڈر سے اور بھوک سے اور نقصان سے مالوں کے اور جانوں کے اور میووں کے [۲۲۰] اور خوشخبری دے ان صبر کرنے والوں کو', 'And certainly, We shall test you with something of fear, hunger, loss of wealth, lives and fruits, but give glad tidings to As-Sabirin (the patient ones, etc.).', 'Surely We will test you with a bit of fear and hunger, and loss in wealth and lives and fruits, and give good tidings to the patient.'),
(163, 2, 156, 19, 3, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'الَّذِیۡنَ اِذَاۤ  اَصَابَتۡہُمۡ مُّصِیۡبَۃٌ  ۙ قَالُوۡۤا اِنَّا لِلّٰہِ وَ  اِنَّاۤ اِلَیۡہِ رٰجِعُوۡنَ ﴿۱۵۶﴾ؕ', 'کہ ان لوگوں پر جب کوئی مصیبت واقع ہوتی ہے تو کہتے ہیں کہ ہم اللہ ہی کا مال ہیں اور اسی کی طرف لوٹ کر جانے والے ہیں۔', 'کہ جب پہنچے ان کو کچھ مصیبت تو  کہیں ہم تو اللہ ہی کا مال ہیں اور ہم اسی کی طرف لوٹ کر جانے والے ہیں', 'Who, when afflicted with calamity, say: \"Truly! To Allah we belong and truly, to Him we shall return.\"', 'who, when a suffering visits them, say: “We certainly belong to Allah, and to Him we are bound to return.”'),
(164, 2, 157, 19, 3, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اُولٰٓئِکَ عَلَیۡہِمۡ صَلَوٰتٌ مِّنۡ رَّبِّہِمۡ وَ رَحۡمَۃٌ ۟ وَ اُولٰٓئِکَ ہُمُ الۡمُہۡتَدُوۡنَ ﴿۱۵۷﴾', 'یہی لوگ ہیں جن پر انکے پروردگار کی عنائتیں ہیں اور خصوصی رحمت بھی ہے اور یہی سیدھے رستے پر ہیں۔', 'ایسے ہی لوگوں پر عنایتیں ہیں اپنے رب کی اور مہربانی اور وہی ہیں سیدھی راہ پر [۲۲۱]', 'They are those on whom are the Salawat (i.e. blessings, etc.) (i.e. who are blessed and will be forgiven) from their Lord, and (they are those who) receive His Mercy, and it is they who are the guided-ones.', 'Those are the ones upon whom there are blessings from their Lord, and mercy as well; and those are the ones who are on the right path.'),
(165, 2, 158, 19, 3, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اِنَّ الصَّفَا وَ الۡمَرۡوَۃَ مِنۡ شَعَآئِرِ اللّٰہِ ۚ فَمَنۡ حَجَّ الۡبَیۡتَ اَوِ اعۡتَمَرَ فَلَا جُنَاحَ عَلَیۡہِ اَنۡ یَّطَّوَّفَ بِہِمَا ؕ وَ مَنۡ تَطَوَّعَ خَیۡرًا  ۙ فَاِنَّ اللّٰہَ شَاکِرٌ  عَلِیۡمٌ ﴿۱۵۸﴾', 'بیشک کوہ صفا اور مروہ اللہ کی نشانیوں میں سے ہیں۔ تو جو شخص خانہ کعبہ کا حج یا عمرہ کرے اس پر کچھ گناہ نہیں کہ دونوں کے درمیان چکر لگائے بلکہ یہ  ایک نیک کام ہے اور جو کوئی نیک کام کرے تو اللہ قدردان ہے دانا ہے۔', 'بیشک صفا اور مروہ نشانیوں میں سے ہیں اللہ کی [۲۲۲] سو جو کوئی حج کرے بیت اللہ کا یا عمرہ تو کچھ گناہ نہیں اس کو کہ طواف کرے ان دونوں میں اور جو کوئی اپنی خوشی سےکرےکچھ نیکی تو اللہ قدردان ہے سب کچھ جاننے والا [۲۲۳]', 'Verily! As-Safa and Al-Marwah (two mountains in Makkah) are of the Symbols of Allah. So it is not a sin on him who perform Hajj or Umrah (pilgrimage) of the House (the Kabah at Makkah) to perform the going (Tawaf) between them (As-Safa and Al-Marwah). And whoever does good voluntarily, then verily, Allah is All-Recogniser, All-Knower.', 'Indeed Safā and Marwah are among the marks of Allah.So whoever comes to the House for Hajj or performs ‘Umrah, there is no sin for him if he makes rounds between them; whoever comes up with good on his own, then Allah is Appreciating, All-Knowing.'),
(166, 2, 159, 19, 3, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اِنَّ الَّذِیۡنَ یَکۡتُمُوۡنَ مَاۤ اَنۡزَلۡنَا مِنَ الۡبَیِّنٰتِ وَ الۡہُدٰی مِنۡۢ بَعۡدِ مَا بَیَّنّٰہُ لِلنَّاسِ فِی الۡکِتٰبِ  ۙ  اُولٰٓئِکَ یَلۡعَنُہُمُ اللّٰہُ  وَ  یَلۡعَنُہُمُ  اللّٰعِنُوۡنَ ﴿۱۵۹﴾ۙ', 'جو لوگ ہمارے حکموں کو اور ہدایتوں کو جو ہم نے نازل کی ہیں کسی غرض فاسد سے چھپاتے ہیں باوجودیکہ ہم نے ان کو لوگوں کے سمجھانے کے لئے اپنی کتاب میں کھول کھول کر بیان کر دیا ہے ایسوں پر اللہ اور تمام لعنت کرنے والے لعنت کرتے ہیں۔', 'بیشک جو لوگ چھپاتے ہیں جو کچھ ہم نے اتارے صاف حکم اور ہدایت کی باتیں بعد اس کے کہ ہم انکو کھول چکے لوگوں کے واسطے کتاب میں [۲۲۴] ان پر لعنت کرتا ہے اللہ اور لعنت کرتے ہیں ان پر لعنت کرنے والے [۲۲۵]', 'Verily, those who conceal the clear proofs, evidences and the guidance, which We have sent down, after We have made it clear for the people in the Book, they are the ones cursed by Allah and cursed by the cursers.', 'Surely, those who conceal the clear signs and the guidance We have revealed, even after We have explained them for people in the Book, upon them Allah casts damnation, and they are cursed by all those who curse.'),
(167, 2, 160, 19, 3, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اِلَّا الَّذِیۡنَ تَابُوۡا وَ اَصۡلَحُوۡا وَ بَیَّنُوۡا فَاُولٰٓئِکَ اَتُوۡبُ عَلَیۡہِمۡ ۚ وَ اَنَا التَّوَّابُ الرَّحِیۡمُ ﴿۱۶۰﴾', 'ہاں جو توبہ کرتے ہیں اور اپنی حالت درست کر لیتے اور احکام الٰہی کو صاف صاف بیان کر دیتے ہیں تو میں ان کے قصور معاف کر دیتا ہوں اور میں بڑا معاف کرنے والا  بڑا مہربان ہوں۔', 'مگر جنہوں نے توبہ کی اور درست کیا اپنے کام کو اور بیان کر دیا حق بات کو تو انکو معاف کرتا ہوں [۲۲۶] اور میں ہوں بڑا معاف کرنے والا نہایت مہربان', 'Except those who repent and do righteous deeds, and openly declare (the truth which they concealed). These, I will accept their repentance. And I am the One Who accepts repentance, the Most Merciful.', 'Yet, those who repent and correct and declare (what they used to conceal), their repentance is accepted by Me. I am the Most-Relenting, the Most-Merciful.'),
(168, 2, 161, 19, 3, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اِنَّ الَّذِیۡنَ کَفَرُوۡا وَ مَاتُوۡا وَ ہُمۡ کُفَّارٌ اُولٰٓئِکَ عَلَیۡہِمۡ لَعۡنَۃُ اللّٰہِ وَ الۡمَلٰٓئِکَۃِ وَ النَّاسِ اَجۡمَعِیۡنَ ﴿۱۶۱﴾ۙ', 'جو لوگ کافر ہوئے اور کافر ہی مرے ایسوں پر اللہ کی اور فرشتوں کی اور انسانوں کی سب کی لعنت۔', 'بیشک جو لوگ کافر ہوئے اور مر گئے کافر ہی انہی پر لعنت ہے اللہ کی اور فرشتوں کی اور لوگوں کی سب کی [۲۲۷]', 'Verily, those who disbelieve, and die while they are disbelievers, it is they on whom is the Curse of Allah and of the angels and of mankind, combined.', 'Indeed, those who disbelieved and died while they were disbelievers, upon them is the curse of Allah, and of angels, and of all human beings together,'),
(169, 2, 162, 19, 3, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'خٰلِدِیۡنَ فِیۡہَا ۚ لَا یُخَفَّفُ عَنۡہُمُ الۡعَذَابُ وَ لَا ہُمۡ یُنۡظَرُوۡنَ ﴿۱۶۲﴾', 'وہ ہمیشہ اسی لعنت میں گرفتار رہیں گے ان سے نہ تو عذاب ہلکا ہی کیا جائے گا اور نہ انہیں کچھ مہلت ملے گی۔', 'ہمیشہ رہیں گے اسی لعنت میں نہ ہلکا ہو گا ان پر سے عذاب اور نہ انکو مہلت ملے گی [۲۲۸]', 'They will abide therein (under the curse in Hell), their punishment will neither be lightened, nor will they be reprieved.', 'in a way that they will remain in it forever. Neither the punishment will be lightened for them, nor will they be given respite.'),
(170, 2, 163, 19, 3, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ اِلٰـہُکُمۡ  اِلٰہٌ  وَّاحِدٌ ۚ لَاۤ اِلٰہَ اِلَّا ہُوَ الرَّحۡمٰنُ  الرَّحِیۡمُ ﴿۱۶۳﴾٪', 'اور لوگو تمہارا معبود ایک ہی معبود ہے۔ اس بڑے مہربان اور رحم والے کے سوا کوئی عبادت کے لائق نہیں۔', 'اور معبود تم سب کا ایک ہی معبود ہے کوٹی معبود نہیں اس کے سوا بڑا مہربان ہے نہایت رحم والا [۲۲۹]', 'And your Ilah (God) is One Ilah (God - Allah), La ilaha illa Huwa (there is none who has the right to be worshipped but He), the Most Beneficent, the Most Merciful.', 'Your god is one God: There is no god but He, the All-Merciful, the Very-Merciful.'),
(171, 2, 164, 20, 4, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اِنَّ فِیۡ خَلۡقِ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ اخۡتِلَافِ الَّیۡلِ وَ النَّہَارِ وَ الۡفُلۡکِ الَّتِیۡ تَجۡرِیۡ فِی الۡبَحۡرِ  بِمَا یَنۡفَعُ النَّاسَ وَ مَاۤ اَنۡزَلَ اللّٰہُ مِنَ السَّمَآءِ مِنۡ مَّآءٍ فَاَحۡیَا بِہِ الۡاَرۡضَ بَعۡدَ مَوۡتِہَا وَ بَثَّ فِیۡہَا مِنۡ کُلِّ دَآبَّۃٍ  ۪ وَّ تَصۡرِیۡفِ الرِّیٰحِ وَ السَّحَابِ الۡمُسَخَّرِ بَیۡنَ السَّمَآءِ وَ الۡاَرۡضِ لَاٰیٰتٍ لِّقَوۡمٍ  یَّعۡقِلُوۡنَ ﴿۱۶۴﴾', 'بیشک آسمانوں اور زمین کے پیدا کرنے میں اور رات اور دن کے ایک دوسرے کے پیچھے آنے جانے میں اور کشتیوں اور جہازوں میں جو سمندر میں لوگوں کے فائدے  کے لئے رواں ہیں اور مینہ میں جس کو اللہ آسمان سے برساتا اور اس سے زمین کو  اسکے مردہ ہو جانے کے بعد زندہ یعنی خشک ہو جانے کے بعد سرسبز کر دیتا ہے اور زمین پر ہر قسم کے جانور پھیلانے میں اور ہواؤں کے چلانے میں اور بادلوں میں جو آسمان اور زمین کے درمیان گھرے رہتے ہیں عقلمندوں کے لئے اللہ کی قدرت کی نشانیاں ہیں۔', 'بیشک آسمان اور زمین کے پیدا کرنے میں اور رات اور دن کے بدلتے رہنے میں اور کشتیوں میں جو کہ لے کر چلتی ہیں دریا میں لوگوں کے کام کی چیزیں اور پانی میں جس کو کہ اتارا اللہ نے آسمان سے پھر جلایا اس سے زمین کو اس کے مر گئے پیچھے اور پھیلائے اس میں سب قسم کے جانور اور ہواؤں کے بدلنے میں اور بادل میں جو کہ تابعدار ہے اس کے حکم کا درمیان آسمان و زمین کے بیشک ان سب چیزوں میں نشانیاں ہیں عقلمندوں کے لئے [۲۳۰]', 'Verily! In the creation of the heavens and the earth, and in the alternation of night and day, and the ships which sail through the sea with that which is of use to mankind, and the water (rain) which Allah sends down from the sky and makes the earth alive therewith after its death, and the moving (living) creatures of all kinds that He has scattered therein, and in the veering of winds and clouds which are held between the sky and the earth, are indeed Ayat (proofs, evidences, signs, etc.) for people of understanding.', 'Surely, in the creation of heavens and earth, and the alternation of night and day, and the ships that sail in the sea, carrying that which benefits men, and in the water Allah sent down from the sky, then revived with it the earth after it was dead, and in every creature He has scattered on it, and in turning of winds, and in the clouds employed to serve between heaven and earth, there are signs for those who have sense.'),
(172, 2, 165, 20, 4, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ مِنَ النَّاسِ مَنۡ یَّتَّخِذُ مِنۡ دُوۡنِ اللّٰہِ اَنۡدَادًا یُّحِبُّوۡنَہُمۡ کَحُبِّ اللّٰہِ ؕ وَ الَّذِیۡنَ اٰمَنُوۡۤا اَشَدُّ حُبًّا  لِّلّٰہِ ؕوَ لَوۡ  یَرَی الَّذِیۡنَ ظَلَمُوۡۤا اِذۡ یَرَوۡنَ الۡعَذَابَ  ۙ اَنَّ الۡقُوَّۃَ لِلّٰہِ جَمِیۡعًا  ۙ وَّ اَنَّ اللّٰہَ شَدِیۡدُ الۡعَذَابِ ﴿۱۶۵﴾', 'اور بعض لوگ ایسے ہیں جو غیر اللہ کو اللہ کا شریک بناتے اور ان سے اللہ کی سی محبت کرتے ہیں لیکن جو ایمان والے ہیں وہ تو اللہ ہی کے سب سے زیادہ دوستدار ہیں اور اے کاش ظالم لوگ جو بات عذاب کے وقت دیکھیں گے اب دیکھ لیتے کہ سب طرح کی طاقت اللہ ہی کو ہے اور یہ کہ اللہ سخت عذاب کرنے والا ہے۔', 'اور بعضے لوگ  وہ ہیں جو بناتے ہیں اللہ کے برابر اوروں کو [۲۳۱] انکی محبت ایسی رکھتے ہیں جیسی محبت اللہ کی [۲۳۲] اور ایمان والوں کو اس سے زیادہ تر ہے محبت اللہ کی [۲۳۳] اور اگر دیکھ لیں یہ ظالم اس وقت کو جبکہ دیکھیں گے عذاب کہ قوۃ ساری اللہ ہی کے لئے ہے اور یہ کہ اللہ کا عذاب سخت ہے [۲۳۴]', 'And of mankind are some who take (for worship) others besides Allah as rivals (to Allah). They love them as they love Allah. But those who believe, love Allah more (than anything else). If only, those who do wrong could see, when they will see the torment, that all power belongs to Allah and that Allah is Severe in punishment.', 'Among the people there are some who set up co-gods beside Allah whom they love like the love due to Allah. But those who believe are most firm in their love for Allah. Would that the unjust people could perceive - when they see the torment (i.e. any calamity in this world) - that all power belongs to Allah alone, and that Allah is severe in punishment!'),
(173, 2, 166, 20, 4, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اِذۡ  تَبَرَّاَ الَّذِیۡنَ اتُّبِعُوۡا مِنَ الَّذِیۡنَ اتَّبَعُوۡا  وَ رَاَوُا  الۡعَذَابَ وَ تَقَطَّعَتۡ بِہِمُ الۡاَسۡبَابُ ﴿۱۶۶﴾', 'اس دن کفر کے پیشوا اپنے پیروؤں سے بیزاری ظاہر کریں گے اور دونوں عذاب الٰہی دیکھ لیں گے اور ان کے آپس کے تعلقات منقطع ہو جائیں گے۔', 'جبکہ بیزار ہو جاویں گے وہ کہ جن کی پیروی کی تھی ان سے کہ جو انکے پیرو ہوٹے تھے اور دیکھیں گے عذاب اور منقطع ہو جائیں گے ان کے سب علاقے [۲۳۵]', 'When those who were followed, disown (declare themselves innocent of) those who followed (them), and they see the torment, then all their relations will be cut off from them.', '(Imagine the time) when those who were followed will disown their followers, and they (all) will see the punishment, and the bonds between them will be cut asunder,'),
(174, 2, 167, 20, 4, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ قَالَ الَّذِیۡنَ اتَّبَعُوۡا لَوۡ  اَنَّ لَنَا کَرَّۃً فَنَتَبَرَّاَ مِنۡہُمۡ کَمَا تَبَرَّءُوۡا مِنَّا ؕ کَذٰلِکَ یُرِیۡہِمُ اللّٰہُ  اَعۡمَالَہُمۡ حَسَرٰتٍ عَلَیۡہِمۡ ؕ وَ مَا ہُمۡ  بِخٰرِجِیۡنَ مِنَ النَّارِ ﴿۱۶۷﴾٪', 'یہ حال دیکھ کر پیروی کرنے والے حسرت سے کہیں گے کہ اے کاش ہمیں پھر دنیا میں جانا نصیب ہو۔ تاکہ جس طرح یہ ہم سے بیزار ہو رہے ہیں اسی طرح ہم بھی ان سے بیزار ہوں۔ اس طرح اللہ ان کے اعمال حسرت بنا کر دکھائے گا اور وہ دوزخ سے نکل نہیں سکیں گے۔', 'اور کہیں گے پیرو کیا اچھا ہوتا جو ہم کو دنیا کی طرف لوٹ جانا مل جاتا تو پھر ہم بھی بیزار ہو جاتے ان سے جیسے یہ ہم سے بیزار ہو گئے [۲۳۶] اسی طرح پر  دکھلائے گا اللہ ان کو ان کے کام حسرت دلانے کو اور وہ ہرگز نکلنے والے نہیں مار سے [۲۳۷]', 'And those who followed will say: \"If only we had one more chance to return (to the worldly life), we would disown (declare ourselves as innocent from) them as they have disowned (declared themselves as innocent from) us.\" Thus Allah will show them their deeds as regrets for them. And they will never get out of the Fire .', 'and those who followed will say, “We wish we had another (chance to) return (to the world), so that we may disown them as they had disowned us.” Thus Allah will show them that their deeds were (nothing but) causes of remorse for them, and they are not to come out of the Fire.'),
(175, 2, 168, 21, 5, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'یٰۤاَیُّہَا النَّاسُ کُلُوۡا مِمَّا فِی الۡاَرۡضِ حَلٰلًا طَیِّبًا ۫ۖ وَّ لَا تَتَّبِعُوۡا خُطُوٰتِ الشَّیۡطٰنِ ؕ اِنَّہٗ لَکُمۡ عَدُوٌّ مُّبِیۡنٌ ﴿۱۶۸﴾', 'لوگو جو چیزیں زمین میں حلال طیّب ہیں وہ کھاؤ۔ اور شیطان کے قدموں پر نہ چلو وہ تمہارا کھلا دشمن ہے۔', 'اے لوگو کھاؤ زمین کی چیزوں میں سے حلال پاکیزہ اور پیروی نہ کرو شیطان کی [۲۳۸] بیشک وہ تمہارا دشمن ہے صریح', 'O mankind! Eat of that which is lawful and good on the earth, and follow not the footsteps of Shaitan (Satan). Verily, he is to you an open enemy.', 'O people, eat permissible good things out of what lies in the earth, and do not follow the footsteps of ShaiTān (Satan); indeed, he is an open enemy for you.'),
(176, 2, 169, 21, 5, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اِنَّمَا یَاۡمُرُکُمۡ بِالسُّوۡٓءِ وَ الۡفَحۡشَآءِ وَ اَنۡ تَقُوۡلُوۡا عَلَی اللّٰہِ مَا لَا تَعۡلَمُوۡنَ ﴿۱۶۹﴾', 'وہ تو تم کر برائی اور بے حیائی ہی کے کام کرنے کو کہتا ہے اور یہ بھی کہتا ہے کہ اللہ کی نسبت ایسی باتیں کہو جنکا تمہیں کچھ بھی علم نہیں۔', 'وہ تو یہی حکم کرے گا تم کو کہ برے کام اور بیحیائی کرو اور جھوٹ لگاؤ اللہ پر وہ باتیں جنکو تم نہیں جانتے [۲۳۹]', '(Shaitan (Satan)) commands you only what is evil and Fahsha (sinful), and that you should say against Allah what you know not.', 'He orders you only to (do) evil and immodest acts, and that you ascribe to Allah what you do not know.'),
(177, 2, 170, 21, 5, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ اِذَا قِیۡلَ لَہُمُ  اتَّبِعُوۡا مَاۤ اَنۡزَلَ اللّٰہُ قَالُوۡا بَلۡ نَتَّبِعُ مَاۤ اَلۡفَیۡنَا عَلَیۡہِ اٰبَآءَنَا ؕ اَوَ لَوۡ کَانَ اٰبَآؤُہُمۡ لَا یَعۡقِلُوۡنَ شَیۡئًا وَّ لَا  یَہۡتَدُوۡنَ ﴿۱۷۰﴾', 'اور جب ان لوگوں سے کہا جاتا ہے کہ جو کتاب اللہ نے نازل فرمائی ہے اس کی پیروی کرو تو کہتے ہیں نہیں بلکہ ہم تو اسی چیز کی پیروی کریں گے جس پر ہم نے اپنے باپ دادا کو پایا۔ بھلا اگرچہ ان کے باپ دادا نہ کچھ سمجھتے ہوں اور نہ سیدھے رستے پر ہوں تب بھی وہ انہی کی تقلید کئے جائیں گے۔', 'اور جب کوئی ان سےکہے کہ تابعداری کرو اس حکم کی جو کہ نازل فرمایا اللہ نے تو کہتے ہیں ہرگز نہیں ہم تو تابعداری کریں گے اس کی جس پر دیکھا ہم نے اپنے باپ دادوں کو بھلا اگرچہ ان کے باپ دادے نہ سمجھتے ہوں کچھ ہی اور نہ جانتے ہوں سیدھی راہ [۲۴۰/۱]', 'When it is said to them: \"Follow what Allah has sent down.\" They say: \"Nay! We shall follow what we found our fathers following.\" (Would they do that!) Even though their fathers did not understand anything nor were they guided?', 'When it is said to them: “Follow what Allah has sent down,” they say: “Instead, we would follow that (religion) on which we have found our fathers.” Is it so, even though their fathers had no understanding at all, nor had they been on the right path?'),
(178, 2, 171, 21, 5, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ مَثَلُ الَّذِیۡنَ کَفَرُوۡا کَمَثَلِ الَّذِیۡ یَنۡعِقُ بِمَا لَا یَسۡمَعُ اِلَّا دُعَآءً  وَّ  نِدَآءً ؕ صُمٌّۢ  بُکۡمٌ عُمۡیٌ  فَہُمۡ  لَا  یَعۡقِلُوۡنَ ﴿۱۷۱﴾', 'جو لوگ کافر ہیں ان کی مثال اس شخص کی سی ہے جو کسی ایسی چیز کو آواز دے جو پکار اور آواز کے سوا کچھ سن نہ سکے یہ بہرے ہیں گونگے ہیں اندھے ہیں کہ کچھ سمجھ ہی نہیں سکتے۔', 'اور مثال ان کافروں کی ایسی ہے جیسے پکارے کوئی شخص ایک چیز کو جو کچھ نہ سنے سوا پکارنے اور چلانے کے [۲۴۰/۲] بہرے گونگے اندھے ہیں سو وہ کچھ نہیں سمجھتے [۲۴۱]', 'And the example of those who disbelieve, is as that of him who shouts to the (flock of sheep) that hears nothing but calls and cries. (They are) deaf, dumb and blind. So they do not understand.', 'The example of (calling) those who disbelieve is such as someone is shouting at an animal that hears nothing but a call and cry. They are deaf, dumb and blind, so they do not understand'),
(179, 2, 172, 21, 5, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا کُلُوۡا مِنۡ طَیِّبٰتِ مَا رَزَقۡنٰکُمۡ وَ اشۡکُرُوۡا لِلّٰہِ  اِنۡ  کُنۡتُمۡ اِیَّاہُ  تَعۡبُدُوۡنَ ﴿۱۷۲﴾', 'اے اہل ایمان جو پاکیزہ چیزیں ہم نے تم کو عطا فرمائی ہیں ان کو کھاؤ اور اگر اللہ ہی کے بندے ہو تو اس کی نعمتوں کا شکر بھی ادا کرو۔', 'اے ایمان والو کھاؤ پاکیزہ چیزیں جو روزی دی ہم نے تم کو اور شکر کرو اللہ کا اگر تم اسی کےبندے ہو [۲۴۲]', 'O you who believe (in the Oneness of Allah - Islamic Monotheism)! Eat of the lawful things that We have provided you with, and be grateful to Allah, if it is indeed He Whom you worship.', 'O you who believe, eat of the good things We have provided to you and be grateful to Allah, if it is He whom you worship (in real terms).'),
(180, 2, 173, 21, 5, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اِنَّمَا حَرَّمَ عَلَیۡکُمُ الۡمَیۡتَۃَ وَ الدَّمَ وَ لَحۡمَ الۡخِنۡزِیۡرِ وَ مَاۤ  اُہِلَّ بِہٖ لِغَیۡرِ اللّٰہِ ۚ فَمَنِ اضۡطُرَّ غَیۡرَ بَاغٍ وَّ لَا عَادٍ فَلَاۤ اِثۡمَ عَلَیۡہِ ؕ اِنَّ اللّٰہَ  غَفُوۡرٌ  رَّحِیۡمٌ ﴿۱۷۳﴾', 'اس نے تو تم پر مرا ہوا جانور اور لہو اور سور کا گوشت اور جس چیز پر اللہ کے سوا کسی اور کا نام پکارا جائے حرام کر دیا ہے۔ ہاں جو مجبور ہو جائے بشرطیکہ اللہ کی نافرمانی نہ کرے اور حد ضرورت سے باہر نہ نکل جائے اس پر کچھ گناہ نہیں بیشک اللہ بخشنے والا ہے رحم کرنے والا ہے۔', 'اس نے تو تم پر یہی حرام کیا ہے مردہ جانور [۲۴۳] اور لہو [۲۴۴] اور گوشت سور کا [۲۴۵] اور جس جانور پر نام پکارا جائے اللہ کے سوا کسی اور کا [۲۴۶] پھر جو کوئی بے اختیار ہو جائے نہ تو نافرمانی کرے اور نہ زیادتی تو اس پر کچھ گناہ نہیں [۲۴۷] بیشک اللہ ہے بڑا بخشنے والا نہایت مہربان [۲۴۸]', 'He has forbidden you only the Maytatah (dead animals), and blood, and the flesh of swine, and that which is slaughtered as a scrifice for others than Allah (or has been slaughtered for idols, etc., on which Allahs Name has not been mentioned while slaughtering). But if one is forced by necessity without wilful disobedience nor transgressing due limits, then there is no sin on him. Truly, Allah is Oft-Forgiving, Most Merciful.', 'He has only prohibited for you carrion, blood, the flesh of swine and that upon which a name of someone other than ‘Allah’ has been invoked. Then, whoever is compelled by necessity, neither seeking pleasure nor transgressing, there is no sin on him. Verily, Allah is Most-Forgiving, Very-Merciful.'),
(181, 2, 174, 21, 5, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اِنَّ الَّذِیۡنَ یَکۡتُمُوۡنَ مَاۤ  اَنۡزَلَ اللّٰہُ مِنَ الۡکِتٰبِ وَ یَشۡتَرُوۡنَ بِہٖ ثَمَنًا قَلِیۡلًا  ۙ اُولٰٓئِکَ مَا یَاۡکُلُوۡنَ فِیۡ بُطُوۡنِہِمۡ  اِلَّا النَّارَ وَ لَا یُکَلِّمُہُمُ اللّٰہُ یَوۡمَ الۡقِیٰمَۃِ وَ لَا  یُزَکِّیۡہِمۡ ۚۖ وَ لَہُمۡ عَذَابٌ اَلِیۡمٌ ﴿۱۷۴﴾', 'جو لوگ اللہ کی کتاب سے ان آیتوں کو اور ہدایتوں کو جو اس نے نازل فرمائی ہیں چھپاتے اور ان کے بدلے تھوڑی سی قیمت یعنی دنیاوی منفعت حاصل کرتے ہیں وہ اپنے پیٹوں میں محض آگ بھرتے ہیں ایسے لوگوں سے اللہ قیامت کے دن نہ کلام کرے گا اور نہ ان کو گناہوں سے پاک کرے گا اور ان کے لئے دکھ دینے والا عذاب ہے۔', 'بیشک جو لوگ چھپاتے ہیں جو کچھ کیا نازل اللہ نے کتاب [۲۴۹] اور لیتے ہیں اس پر تھوڑا سا مول [۲۵۰] وہ نہیں بھرتے اپنے پیٹ میں مگر آگ [۲۵۱] اور نہ بات کرے گا ان سے اللہ قیامت کے دن [۲۵۲] اور نہ پاک کرے گا ان کو [۲۵۳] اور انکے لئے ہے عذاب دردناک [۲۵۴]', 'Verily, those who conceal what Allah has sent down of the Book, and purchase a small gain therewith (of worldly things), they eat into their bellies nothing but fire. Allah will not speak to them on the Day of Resurrection, nor purify them, and theirs will be a painful torment.', 'Verily, those who conceal the Book Allah has revealed, and earn thereby a small price, they eat nothing into their bellies but fire, and Allah will not speak to them on the Day of Judgment, nor will He purify them, and for them there is painful punishment.'),
(182, 2, 175, 21, 5, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اُولٰٓئِکَ الَّذِیۡنَ اشۡتَرَوُا الضَّلٰلَۃَ بِالۡہُدٰی وَ الۡعَذَابَ بِالۡمَغۡفِرَۃِ ۚ فَمَاۤ اَصۡبَرَہُمۡ عَلَی النَّارِ ﴿۱۷۵﴾', 'یہ وہ لوگ ہیں جنہوں نے ہدایت چھوڑ کر گمراہی اور بخشش چھوڑ کر عذاب خرید لیا۔ یہ آتش جہنم کی کیسی برداشت کرنے والے ہیں۔', 'یہی ہیں جنہوں نے خریدا گمراہی کو بدلے ہدایت کے اور عذاب بدلے بخشش کے [۲۵۴/۱] سو کس قدر صبر کرنے والے ہیں وہ دوزخ پر [۲۵۴/۲]', 'Those are they who have purchased error at the price of Guidance, and torment at the price of Forgiveness. So how bold they are (for evil deeds which will push them) to the Fire.', 'They are those who have bought the wrong way at the price of the right way, and punishment at the price of pardon. How well they endure the Fire!'),
(183, 2, 176, 21, 5, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'ذٰلِکَ بِاَنَّ اللّٰہَ نَزَّلَ الۡکِتٰبَ بِالۡحَقِّ ؕ وَ اِنَّ الَّذِیۡنَ اخۡتَلَفُوۡا فِی الۡکِتٰبِ لَفِیۡ شِقَاقٍۭ بَعِیۡدٍ ﴿۱۷۶﴾٪', 'یہ اس لئے کہ اللہ نے کتاب سچّائی کے ساتھ نازل فرمائی۔ اور جن لوگوں نے اس کتاب میں اختلاف کیا وہ ضد میں آ کر نیکی سے دور ہو گئے ہیں۔', 'یہ اس واسطے کہ اللہ نے نازل فرمائی کتاب سچی اور جنہوں نے اختلاف ڈالا کتاب میں وہ بیشک ضد میں دور جا پڑے [۲۵۵]', 'That is because Allah has sent down the Book (the Quran) in truth. And verily, those who disputed as regards the Book are far away in opposition.', 'All that is because Allah revealed the Book with the truth. Yet, those who have opted for dissension about the Book are in extreme division (among themselves)'),
(184, 2, 177, 22, 6, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'لَیۡسَ الۡبِرَّ اَنۡ تُوَلُّوۡا وُجُوۡہَکُمۡ  قِبَلَ الۡمَشۡرِقِ وَ الۡمَغۡرِبِ وَ لٰکِنَّ الۡبِرَّ مَنۡ اٰمَنَ بِاللّٰہِ وَ الۡیَوۡمِ الۡاٰخِرِ وَ الۡمَلٰٓئِکَۃِ وَ الۡکِتٰبِ وَ النَّبِیّٖنَ ۚ وَ اٰتَی الۡمَالَ عَلٰی حُبِّہٖ ذَوِی الۡقُرۡبٰی وَ الۡیَتٰمٰی وَ الۡمَسٰکِیۡنَ  وَ ابۡنَ السَّبِیۡلِ  ۙ وَ السَّآئِلِیۡنَ وَ فِی الرِّقَابِ ۚ وَ اَقَامَ الصَّلٰوۃَ وَ اٰتَی الزَّکٰوۃَ ۚ وَ الۡمُوۡفُوۡنَ بِعَہۡدِہِمۡ  اِذَا عٰہَدُوۡا ۚ وَ الصّٰبِرِیۡنَ فِی الۡبَاۡسَآءِ وَ الضَّرَّآءِ  وَ حِیۡنَ الۡبَاۡسِ ؕ اُولٰٓئِکَ الَّذِیۡنَ صَدَقُوۡا ؕ وَ اُولٰٓئِکَ ہُمُ الۡمُتَّقُوۡنَ ﴿۱۷۷﴾', 'نیکی یہی نہیں کہ تم مشرق و مغرب کو قبلہ سمجھ کر ان کی طرف منہ کر لو بلکہ نیکی یہ ہے کہ لوگ اللہ پر اور روز آخر پر اور فرشتوں پر اور اللہ کی کتاب پر اور پیغمبروں پر ایمان لائیں۔ اور مال باوجود عزیز رکھنے کے رشتہ داروں اور یتیموں اور محتاجوں اور مسافروں اور مانگنے والوں کو دیں اور گردنوں کے چھڑانے میں خرچ کریں اور نماز پڑھیں اور زکوٰۃ دیں اور جب عہد کرلیں تو اس کو پورا کریں اور سختی اور تکلیف میں اور جنگ کے وقت ثابت قدم رہیں۔ یہی لوگ ہیں جو ایمان میں سچّے ہیں اور یہی ہیں جو اللہ سے ڈرنے والے ہیں۔', 'نیکی کچھ یہی نہیں کہ منہ کرو اپنا مشرق کی طرف یا مغرب کی [۲۵۶] لیکن بڑی نیکی تو یہ ہے جو کوئی ایمان لائے اللہ پر اور قیامت کے دن پر اور فرشتوں پر اور سب کتابوں پر اور پیغمبروں پر اور دے مال اس کی محبت پر رشتہ داروں کو اور یتیموں کو اور محتاجوں کو اور مسافروں کو اور مانگنے والوں کو اور گردنیں چھڑانے میں اور قائم رکھے نماز اور دیا کرے زکوٰۃ اور پورا کرنے والے اپنے اقرار کو جب عہد کریں اور صبر کرنے والے سختی میں اور تکلیف میں اور لڑائی کے وقت [۲۵۷] یہی لوگ ہیں سچے اور یہی ہیں پرہیزگار [۲۵۸]', 'It is not Al-Birr (piety, righteousness, and each and every act of obedience to Allah, etc.) that you turn your faces towards east and (or) west (in prayers); but Al-Birr is (the quality of) the one who believes in Allah, the Last Day, the Angels, the Book, the Prophets and gives his wealth, in spite of love for it, to the kinsfolk, to the orphans, and to Al-Masakin (the poor), and to the wayfarer, and to those who ask, and to set slaves free, performs As-Salat (Iqamat-as-Salat), and gives the Zakat, and who fulfill their covenant when they make it, and who are As-Sabirin (the patient ones, etc.) in extreme poverty and ailment (disease) and at the time of fighting (during the battles). Such are the people of the truth and they are AlMuttaqoon (pious - see V.2:2).', 'Righteousness is not (merely) that you turn your faces to the East and the West; but righteousness is that one believes in Allah and the Last Day and the angels and the Book and the Prophets, and gives wealth, despite (his) love for it, to relatives, and to orphans, the helpless,the wayfarer, and to those who ask, and (spends) in (freeing) slaves and observes the Salāh (prayers) and pays Zakah-and (the act of) those who fulfill their covenant when they enter into a covenant, and, of course, those who are patient in hardship and suffering and when in battle! Those are the ones who are truthful, and those are the God - fearing.'),
(185, 2, 178, 22, 6, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا کُتِبَ عَلَیۡکُمُ الۡقِصَاصُ فِی الۡقَتۡلٰی ؕ اَلۡحُرُّ بِالۡحُرِّ وَ الۡعَبۡدُ بِالۡعَبۡدِ وَ الۡاُنۡثٰی بِالۡاُنۡثٰی ؕ فَمَنۡ عُفِیَ لَہٗ مِنۡ اَخِیۡہِ شَیۡءٌ فَاتِّبَاعٌۢ بِالۡمَعۡرُوۡفِ وَ اَدَآءٌ اِلَیۡہِ بِاِحۡسَانٍ ؕ ذٰلِکَ تَخۡفِیۡفٌ مِّنۡ رَّبِّکُمۡ وَ رَحۡمَۃٌ ؕ فَمَنِ اعۡتَدٰی بَعۡدَ ذٰلِکَ فَلَہٗ عَذَابٌ  اَلِیۡمٌ ﴿۱۷۸﴾', 'مومنو! تم کو مقتولوں کے بارے میں قصاص یعنی خون کے بدلے خون کا حکم دیا جاتا ہے اس طرح پر کہ آزاد کے بدلے آزاد مارا جائے اور غلام کے بدلے غلام اور عورت کے بدلے عورت۔ اور اگر قاتل کو اس کے مقتول بھائی کے قصاص میں سے کچھ معاف کر دیا جائے تو وارث مقتول کو پسندیدہ طریق سے قرارداد کی پیروی یعنی مطالبہ خون بہا کرنا اور قاتل کو خوش خوئی کے ساتھ ادا کرنا چاہیے۔ یہ تمہارے پروردگار کی طرف سے تمہارے لئے آسانی اور مہربانی ہے اب جو اس کے بعد زیادتی کرے اس کے لئے دکھ کا عذاب ہے۔', 'اے ایمان والو فرض ہوا تم پر [قصاص] برابری کرنا مقتولوں میں [۲۵۹] آزاد کے بدلے آزاد [۲۶۰] اور غلام کے بدلے غلام [۲۶۱] اور عورت کےبدلے عورت [۲۶۲] پھر جس کو معاف کیا جائے اس کے بھائی کی طرف سے کچھ بھی تو تابعداری کرنی چاہیئے موافق دستور کے اور ادا کرنا چاہئے اس کو خوبی کے ساتھ [۲۶۳] یہ آسانی ہوئی تمہارے رب کی طرف سے اور مہربانی [۲۶۴] پھر جو زیادتی کرے اس فیصلہ کے بعد تو اس کے لئے ہے عذاب دردناک [۲۶۵]', 'O you who believe! Al-Qisas (the Law of Equality in punishment) is prescribed for you in case of murder: the free for the free, the slave for the slave, and the female for the female. But if the killer is forgiven by the brother (or the relatives, etc.) of the killed against blood money, then adhering to it with fairness and payment of the blood money, to the heir should be made in fairness. This is an alleviation and a mercy from your Lord. So after this whoever transgresses the limits (i.e. kills the killer after taking the blood money), he shall have a painful torment.', 'O you who believe, QiSāS has been prescribed for you in the case of murdered people: The freeman (will be killed) for the freeman, the slave for the slave, and the female for the female. However, if one is somewhat forgiven by his brother, the recourse (of the latter) is to pursue the former (for blood money) with fairness, and the obligation (of the former) is to pay (it) to the latter in a nice way. That is a relief from your Lord, and a mercy. So, whoever transgresses after all that will have a painful punishment.'),
(186, 2, 179, 22, 6, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ لَکُمۡ فِی الۡقِصَاصِ حَیٰوۃٌ یّٰۤاُولِی الۡاَلۡبَابِ لَعَلَّکُمۡ تَتَّقُوۡنَ ﴿۱۷۹﴾', 'اور اے اہل عقل حکم قصاص میں تمہاری زندگانی ہے کہ تم قتل و خونریزی سے بچو۔', 'اور تمہارے واسطے قصاص میں بڑی زندگی ہے اے عقلمندو [۲۶۶] تاکہ تم بچتے رہو [۲۶۷]', 'And there is (a saving of) life for you in Al-Qisas (the Law of Equality in punishment), O men of understanding, that you may become Al-Muttaqoon (the pious - see V.2:2).', 'There is life for you in QiSāS, O people of wisdom, so that you may refrain (from killing).'),
(187, 2, 180, 22, 6, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'کُتِبَ عَلَیۡکُمۡ  اِذَا حَضَرَ اَحَدَکُمُ الۡمَوۡتُ اِنۡ تَرَکَ خَیۡرَۨا ۚۖ  الۡوَصِیَّۃُ لِلۡوَالِدَیۡنِ وَ الۡاَقۡرَبِیۡنَ بِالۡمَعۡرُوۡفِ ۚ حَقًّا عَلَی الۡمُتَّقِیۡنَ ﴿۱۸۰﴾ؕ', 'تم پر فرض کیا جاتا ہے کہ جب تم میں سے کسی کو موت کا وقت آجائے تو اگر وہ کچھ مال چھوڑ جانے والا ہو تو ماں باپ اور رشتہ داروں کے لئے دستور کے مطابق وصیّت کر جائے اللہ سے ڈرنے والوں پر یہ ایک حق ہے۔', 'فرض کر دیا گیا تم پر جب حاضر ہو کسی کو تم میں موت بشرطیکہ چھوڑے کچھ مال وصیت کرنا ماں باپ کے واسطے اور رشتہ داروں کےلئے انصاف کے ساتھ یہ حکم لازم ہے  پرہیز گاروں پر [۲۶۸]', 'It is prescribed for you, when death approaches any of you, if he leaves wealth, that he make a bequest to parents and next of kin, according to reasonable manners. (This is) a duty upon Al-Muttaqoon (the pious - see V.2:2).', 'It is enjoined upon you, when death approaches any one of you and he leaves some wealth, that he must bequeath for the parents and the nearest of kin in the approved manner, being an obligation on the God-fearing.'),
(188, 2, 181, 22, 6, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'فَمَنۡۢ بَدَّلَہٗ بَعۡدَ مَا سَمِعَہٗ فَاِنَّمَاۤ اِثۡمُہٗ عَلَی الَّذِیۡنَ یُبَدِّلُوۡنَہٗ ؕ اِنَّ اللّٰہَ سَمِیۡعٌ عَلِیۡمٌ ﴿۱۸۱﴾ؕ', 'پھر جو شخص وصّیت کو سننے کے بعد اسکو بدل ڈالے تو اس کے بدلنے کا گناہ انہیں لوگوں پر ہے جو اس کو بدلیں اور بیشک اللہ سنتا جانتا ہے۔', 'پھر جو کوئی بدل ڈالے وصیت کو بعد اس کے جو سن چکا تو اس کا گناہ انہی پر جنہوں نے اس کو بدلا بیشک اللہ سننے والا جاننے والا ہے [۲۶۹]', 'Then whoever changes the bequest after hearing it, the sin shall be on those who make the change. Truly, Allah is All-Hearer, All-Knower.', 'Then, whoever changes it after he has heard it, its sin will only be on those who change it. Surely, Allah is All-hearing, All-knowing.'),
(189, 2, 182, 22, 6, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'فَمَنۡ خَافَ مِنۡ مُّوۡصٍ جَنَفًا اَوۡ اِثۡمًا فَاَصۡلَحَ  بَیۡنَہُمۡ فَلَاۤ  اِثۡمَ عَلَیۡہِ ؕ اِنَّ اللّٰہَ غَفُوۡرٌ رَّحِیۡمٌ ﴿۱۸۲﴾٪', 'اب اگر کسی کو وصّیت کرنے والے کی طرف سے کسی وارث کی طرفداری یا حق تلفی کا اندیشہ ہو تو اگر وہ وصّیت کو بدل کر وارثوں میں صلح کرا دے تو اس پر کچھ گناہ نہیں بیشک اللہ بخشنے والا ہے رحم والا ہے۔', 'پھر جو کوئی خوف کرے وصیت کرنے والے سے طرفداری کا یا گناہ کا پھر ان میں باہم صلح کرا دے تو اس پر کچھ گناہ نہیں [۲۷۰] بیشک اللہ بڑا بخشنے والا نہایت مہربان ہے[۲۷۱]', 'But he who fears from a testator some unjust act or wrong-doing, and thereupon he makes peace between the parties concerned, there shall be no sin on him. Certainly, Allah is Oft-Forgiving, Most Merciful.', 'But, whoever apprehends a mistake (unintentional) or a sin (intentional) from a testator, and puts things right between them, then there is no sin on him. Surely, Allah is Forgiving, Merciful.'),
(190, 2, 183, 23, 7, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا کُتِبَ عَلَیۡکُمُ الصِّیَامُ کَمَا کُتِبَ عَلَی الَّذِیۡنَ مِنۡ قَبۡلِکُمۡ لَعَلَّکُمۡ تَتَّقُوۡنَ ﴿۱۸۳﴾ۙ', 'مومنو! تم پر روزے فرض کئے گئے ہیں جس طرح تم سے پہلے لوگوں پر فرض کئے گئے تھے تا کہ تم پرہیز گار بنو۔', 'اے ایمان والو فرض کیا گیا تم پر روزہ جیسے فرض کیا گیا تھا تم سے اگلوں پر [۲۷۲] تاکہ تم پرہیز گار ہو جاؤ [۲۷۳]', 'O you who believe! Observing As-Saum (the fasting) is prescribed for you as it was prescribed for those before you, that you may become Al-Muttaqoon (the pious - see V.2:2).', 'O you who believe, the fasts have been enjoined upon you as they were enjoined upon those before you, so that you may be God-fearing,'),
(191, 2, 184, 23, 7, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اَیَّامًا مَّعۡدُوۡدٰتٍ ؕ فَمَنۡ کَانَ مِنۡکُمۡ مَّرِیۡضًا اَوۡ عَلٰی سَفَرٍ فَعِدَّۃٌ مِّنۡ اَیَّامٍ اُخَرَ ؕ وَ عَلَی الَّذِیۡنَ یُطِیۡقُوۡنَہٗ فِدۡیَۃٌ طَعَامُ مِسۡکِیۡنٍ ؕ فَمَنۡ تَطَوَّعَ خَیۡرًا فَہُوَ خَیۡرٌ لَّہٗ ؕ وَ اَنۡ تَصُوۡمُوۡا خَیۡرٌ لَّکُمۡ   اِنۡ کُنۡتُمۡ  تَعۡلَمُوۡنَ ﴿۱۸۴﴾', 'روزوں کے دن گنتی کے چند روز ہیں تو جو شخص تم میں سے بیمار ہو یا سفر میں ہو تو دوسرے دنوں میں روزوں کا شمار پورا کر لے اور جو لوگ روزہ رکھنے کی طاقت رکھیں لیکن رکھیں نہیں وہ روزے کے بدلے محتاج کو کھانا کھلا دیں۔ اور جو کوئی اپنی مرضی سے زیادہ نیکی کرے تو اس کے حق میں زیادہ اچھا ہے اور اگر سمجھو تو روزہ رکھنا ہی تمہارے حق میں بہتر ہے۔', 'چند روز ہیں گنتی کے [۲۷۴] پھر جو کوئی تم میں سے بیمار ہو یا مسافر تو اس پر ان کی گنتی ہے اور دنوں سے [۲۷۵] اور جن کو طاقت ہے روزہ کی انکے ذمہ بدلا ہے ایک فقیر کا کھانا [۲۷۶] پھر جو کوئی خوشی سے کرے نیکی تو اچھا ہےاسکے واسطے [۲۷۷] اور روزہ رکھو تو بہتر ہے تمہارے لئے اگر تم سمجھ رکھتے ہو [۲۷۸]', '(Observing Saum (fasts)) for a fixed number of days, but if any of you is ill or on a journey, the same number (should be made up) from other days. And as for those who can fast with difficulty, (e.g. an old man, etc.), they have (a choice either to fast or) to feed a Miskeen (poor person) (for every day). But whoever does good of his own accord, it is better for him. And that you fast, it is better for you if only you know', 'for days few in number. However, should any one of you be sick or on a journey, then (he should fast) a number of other days (equal to the missed ones); and those who have the strength, (still, they do not opt for fasting,) on them there is a fidyah (compensation), that is, the feeding of a poor person.Then whoever does good voluntarily, that is better for him. However, that you fast is better for you, if you only knew.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(192, 2, 185, 23, 7, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'شَہۡرُ رَمَضَانَ الَّذِیۡۤ اُنۡزِلَ فِیۡہِ الۡقُرۡاٰنُ ہُدًی لِّلنَّاسِ وَ بَیِّنٰتٍ مِّنَ الۡہُدٰی وَ الۡفُرۡقَانِ ۚ فَمَنۡ شَہِدَ مِنۡکُمُ الشَّہۡرَ فَلۡیَصُمۡہُ ؕ وَ مَنۡ کَانَ مَرِیۡضًا اَوۡ عَلٰی سَفَرٍ فَعِدَّۃٌ مِّنۡ اَیَّامٍ اُخَرَ ؕ یُرِیۡدُ اللّٰہُ بِکُمُ الۡیُسۡرَ وَ لَا یُرِیۡدُ بِکُمُ الۡعُسۡرَ ۫ وَ لِتُکۡمِلُوا الۡعِدَّۃَ وَ لِتُکَبِّرُوا اللّٰہَ عَلٰی مَا ہَدٰىکُمۡ وَ لَعَلَّکُمۡ تَشۡکُرُوۡنَ ﴿۱۸۵﴾', 'روزوں کا مہینہ رمضان کا مہینہ ہے جس میں قرآن اوّل اوّل نازل ہوا جو لوگوں کا راہنما ہے اور جس میں ہدایت کی کھلی نشانیاں ہیں اور جو حق و باطل کو الگ الگ کرنے والا ہے تو جو کوئی تم میں سے اس مہینے میں موجود ہو چاہیے کہ پورے مہینے کے روزے رکھے اور جو بیمار ہو یا سفر میں ہو تو دوسرے دنوں میں روزے رکھ کر ان کا شمار پورا کر لے اللہ تمہارے حق میں آسانی چاہتا ہے اور سختی نہیں چاہتا۔ اور یہ آسانی کا حکم اس لئے دیا گیا ہے کہ تم روزوں کا شمار پورا کر لو اور اس احسان کے بدلے کہ اللہ نے تم کو ہدایت بخشی ہے تم اس کو بزرگی سے یاد کرو اور اس کا شکر کرو۔', 'مہینہ رمضان کا ہے جس میں نازل ہوا قرآن ہدایت ہے واسطے لوگوں کو اور دلیلیں روشن راہ پانے کی اور حق کو باطل سے جدا کرنے کی [۲۷۹] سو جو کوئی پائے تم میں سے اس مہینہ کو تو ضرور روزے رکھے اسکے [۲۸۰] اور جو کوئی ہو بیمار یا مسافر تو اس کو گنتی پوری کرنی چاہیئے اور دنوں سے [۲۸۱] اللہ چاہتا ہے تم پر آسانی اور نہیں چاہتا تم پر دشواری اور اس واسطے کہ تم پوری کرو گنتی اور تاکہ بڑائی کرو اللہ کی اس بات پر کہ تم کو ہدایت کی اور تاکہ تم احسان مانو [۲۸۲]', 'The month of Ramadan in which was revealed the Quran, a guidance for mankind and clear proofs for the guidance and the criterion (between right and wrong). So whoever of you sights (the crescent on the first night of) the month (of Ramadan i.e. is present at his home), he must observe Saum (fasts) that month, and whoever is ill or on a journey, the same number (of days which one did not observe Saum (fasts) must be made up) from other days. Allah intends for you ease, and He does not want to make things difficult for you. (He wants that you) must complete the same number (of days), and that you must magnify Allah (i.e. to say Takbeer (Allahu-Akbar; Allah is the Most Great) on seeing the crescent of the months of Ramadan and Shawwal) for having guided you so that you may be grateful to Him.', 'The month of Ramadan is the one in which the Qur’ān was revealed as guidance for mankind, and as clear signs that show the right way and distinguish between right and wrong. So those of you who witness the month must fast in it. But the one who is sick, or is on a journey (should fast) as much from other days (as he missed). Allah intends (to provide) ease for you and does not intend (to create) hardship for you. All this is so that you may complete the number (of fasts as prescribed) and proclaim the Takbīr of Allah for having guided you, and (so) that you may be grateful.'),
(193, 2, 186, 23, 7, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ اِذَا سَاَلَکَ عِبَادِیۡ عَنِّیۡ فَاِنِّیۡ قَرِیۡبٌ ؕ اُجِیۡبُ دَعۡوَۃَ الدَّاعِ  اِذَا دَعَانِ  ۙ فَلۡیَسۡتَجِیۡبُوۡا لِیۡ وَ لۡیُؤۡمِنُوۡا بِیۡ  لَعَلَّہُمۡ  یَرۡشُدُوۡنَ ﴿۱۸۶﴾', 'اور اے پیغمبر جب تم سے میرے بندے میرے بارے میں دریافت کریں انہیں معلوم ہو کہ میں تو تمہارے پاس ہی ہوں۔ جب کوئی پکارنے والا مجھے پکارتا ہے تو میں اس کی دعا قبول کرتا ہوں تو ان کو چاہیے کہ میرے حکموں کو مانیں اور مجھ پر ایمان رکھیں تا کہ نیک رستہ پائیں۔', 'اور جب تجھ سے پوچھیں میرے بندے مجھ کو سو میں تو قریب ہوں قبول کرتا ہوں دعا مانگنے والے کی دعا کو جب مجھ سے دعا مانگے تو چاہئے کہ وہ حکم مانیں میرا اور یقین لائیں مجھ پر تاکہ نیک راہ پر آئیں [۲۸۳]', 'And when My slaves ask you (O Muhammad SAW) concerning Me, then (answer them), I am indeed near (to them by My Knowledge). I respond to the invocations of the supplicant when he calls on Me (without any mediator or intercessor). So let them obey Me and believe in Me, so that they may be led aright.', 'When My servants ask you about Me, then (tell them that) I am near. I respond to the call of one when he prays to Me; so they should respond to Me, and have faith in Me, so that they may be on the right path.'),
(194, 2, 187, 23, 7, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اُحِلَّ لَکُمۡ لَیۡلَۃَ الصِّیَامِ الرَّفَثُ اِلٰی نِسَآئِکُمۡ ؕ ہُنَّ لِبَاسٌ لَّکُمۡ وَ اَنۡتُمۡ لِبَاسٌ لَّہُنَّ ؕ عَلِمَ اللّٰہُ  اَنَّکُمۡ کُنۡتُمۡ تَخۡتَانُوۡنَ اَنۡفُسَکُمۡ فَتَابَ عَلَیۡکُمۡ وَ عَفَا عَنۡکُمۡ ۚ فَالۡـٰٔنَ بَاشِرُوۡہُنَّ وَ ابۡتَغُوۡا مَا کَتَبَ اللّٰہُ  لَکُمۡ  ۪ وَ کُلُوۡا وَ اشۡرَبُوۡا حَتّٰی یَتَبَیَّنَ لَکُمُ الۡخَیۡطُ الۡاَبۡیَضُ مِنَ الۡخَیۡطِ الۡاَسۡوَدِ  مِنَ الۡفَجۡرِ۪ ثُمَّ   اَتِمُّوا الصِّیَامَ اِلَی الَّیۡلِ ۚ وَ لَا تُبَاشِرُوۡہُنَّ وَ اَنۡتُمۡ عٰکِفُوۡنَ  ۙ فِی الۡمَسٰجِدِ ؕ تِلۡکَ حُدُوۡدُ  اللّٰہِ فَلَا تَقۡرَبُوۡہَا ؕ کَذٰلِکَ یُبَیِّنُ اللّٰہُ  اٰیٰتِہٖ لِلنَّاسِ لَعَلَّہُمۡ  یَتَّقُوۡنَ ﴿۱۸۷﴾', 'روزوں کی راتوں میں تمہارے لئے اپنی عورتوں کے پاس جانا جائز کر دیا گیا ہے وہ تمہاری پوشاک ہیں اور تم ان کی پوشاک ہو۔ اللہ کو معلوم ہے کہ تم ان کے پاس جانے سے اپنے حق میں خیانت کرتے تھے سو اس نے تم پر مہربانی کی اور تمہاری حرکات سے درگذر فرمائی۔ تو اب تم کو اختیار ہے کہ ان سے مباشرت کرو۔ اور اللہ نے جو چیز تمہارے لئے لکھ رکھی ہے یعنی اولاد اس کو اللہ سے طلب کرو اور کھاؤ اور پیو یہاں تک کہ صبح کی سفید دھاری رات کی سیاہ دھاری سے الگ نظر آنے لگے پھر روزہ رکھ کر رات تک پورا کرو۔ اور جب تم مسجدوں میں اعتکاف بیٹھتے ہو تو ان سے مباشرت نہ کرو۔ یہ اللہ کی حدیں ہیں ان کے پاس نہ جانا۔ اسی طرح اللہ اپنی آیتیں لوگوں کے سمجھانے کے لئے کھول کھول کر بیان فرماتا ہے تاکہ وہ پرہیز گار بنیں۔', 'حلال ہوا تم کو روزہ کی رات میں بے حجاب ہونا اپنی عورتوں سے [۲۸۴] وہ پوشاک ہیں تمہاری اور تم پوشاک ہو انکی [۲۸۵] اللہ کو معلوم ہے کہ تم خیانت کرتے تھے اپنی جانوں سے [۲۸۶] سو معاف کیا تم کو اور درگذر کی تم سے پھر ملو اپنی عورتوں سے اور طلب کرو اس کو جو لکھ دیا ہے اللہ نے تمہارے لئے [۲۸۷] اور کھاؤ اور پیو جب تک کہ صاف نظر آئے تم کو دھاری سفید صبح کی جدا دھاری سیاہ سے [۲۸۸] پھر پورا کرو روزہ کو رات تک [۲۸۹] اور نہ ملو عورتوں سے جب تک تم اعتکاف کرو مسجدوں میں [۲۹۰] یہ حدیں باندھی ہوئی ہیں اللہ کی سو انکے نزدیک نہ جاؤ اسی طرح بیان فرماتا ہے اللہ اپنی آیتیں لوگوں کے واسطے تاکہ وہ بچتے رہیں [۲۹۱]', 'It is made lawful for you to have sexual relations with your wives on the night of As-Saum (the fasts). They are Leebas (i.e. body cover, or screen, or Sakan, (i.e. you enjoy the pleasure of living with her - as in Verse 7:189) Tafsir At-Tabaree), for you and you are the same for them. Allah knows that you used to deceive yourselves, so He turned to you (accepted your repentance) and forgave you. So now have sexual relations with them and seek that which Allah has ordained for you (offspring), and eat and drink until the white thread (light) of dawn appears to you distinct from the black thread (darkness of night), then complete your Saum (fast) till the nightfall. And do not have sexual relations with them (your wives) while you are in Itikaf (i.e. confining oneself in a mosque for prayers and invocations leaving the worldly activities) in the mosques. These are the limits (set) by Allah, so approach them not. Thus does Allah make clear His Ayat (proofs, evidences, lessons, signs, revelations, verses, laws, legal and illegal things, Allahs set limits, orders, etc.) to mankind that they may become Al-Muttaqoon (the pious - see V.2:2).', 'It is made lawful for you, in the nights of fasts, to have sex with your women. They are apparel for you, and you are apparel for them. Allah knows that you have been betraying yourselves, so He relented towards you and pardoned you. So now you can have sexual intimacy with them and seek what Allah has destined for you and eat and drink until the white thread of the dawn becomes distinct from the black thread; then complete the fast up to the night. But do not have sexual intimacy with them while you are staying in mosques for I‘tikāf. These are the limits set by Allah, so do not go near them. Thus Allah manifests His signs to the people, so that they may be God-fearing.'),
(195, 2, 188, 23, 7, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ لَا تَاۡکُلُوۡۤا اَمۡوَالَکُمۡ بَیۡنَکُمۡ بِالۡبَاطِلِ وَ تُدۡلُوۡا بِہَاۤ اِلَی الۡحُکَّامِ لِتَاۡکُلُوۡا فَرِیۡقًا مِّنۡ اَمۡوَالِ النَّاسِ بِالۡاِثۡمِ وَ اَنۡتُمۡ  تَعۡلَمُوۡنَ ﴿۱۸۸﴾٪', 'اور آپس میں ایک دوسرے کا مال ناحق نہ کھاؤ اور نہ اس کو رشوۃً حاکموں کے پاس پہنچاؤ تا کہ لوگوں کے مال کا کچھ حصہ ناجائز طور پر کھا جاؤ اور اسے تم جانتے بھی ہو۔', 'اور نہ کھاؤ مال ایک دوسرے کا آپس میں ناحق [۲۹۲] اور نہ پہنچاؤ انکو حاکموں تک کہ کھا جاؤ کوئی حصہ لوگوں کےمال میں سے ظلم کر کے [ناحق] اور تم کو معلوم ہے [۲۹۳]', 'And eat up not one anothers property unjustly (in any illegal way e.g. stealing, robbing, deceiving, etc.), nor give bribery to the rulers (judges before presenting your cases) that you may knowingly eat up a part of the property of others sinfully.', 'Do not eat up each other’s property by false means, nor approach with it the authorities to eat up a portion of the property of the people sinfully, while you know (that you are unjust in doing so).'),
(196, 2, 189, 24, 8, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'یَسۡـَٔلُوۡنَکَ عَنِ الۡاَہِلَّۃِ ؕ قُلۡ ہِیَ مَوَاقِیۡتُ لِلنَّاسِ وَ الۡحَجِّ ؕ وَ لَیۡسَ الۡبِرُّ بِاَنۡ تَاۡتُوا الۡبُیُوۡتَ مِنۡ ظُہُوۡرِہَا وَ لٰکِنَّ الۡبِرَّ مَنِ اتَّقٰیۚ وَ اۡتُوا الۡبُیُوۡتَ مِنۡ اَبۡوَابِہَا ۪ وَ اتَّقُوا اللّٰہَ لَعَلَّکُمۡ تُفۡلِحُوۡنَ ﴿۱۸۹﴾', 'اے پیغمبر لوگ تم سے نئے چاند کے بارے میں دریافت کرتے ہیں کہ گھٹتا بڑھتا کیوں ہے کہہ دو کہ وہ لوگوں کے کاموں کی میعادیں اور حج کے وقت معلوم ہونے کا ذریعہ ہے۔ اور نیکی اس بات میں نہیں کہ احرام کی حالت میں گھروں میں ان کے پچھواڑے کی طرف سے آؤ بلکہ نیکوکار وہ ہے جو پرہیز گار ہو۔ اور گھروں میں ان کے دروازوں سے آیا کرو۔ اور اللہ سے ڈرتے رہو تاکہ کامیابی پاؤ۔', 'تجھ سے پوچھتےہیں حال نئے چاند کا [۲۹۴] کہہ دے کہ یہ اوقات مقررہ ہیں لوگوں کے واسطے اور حج کے واسطے [۲۹۵] اور نیکی یہ نہیں کہ گھروں میں آؤ انکی پشت کی طرف سے اور لیکن نیکی یہ ہے کہ جو کوئی ڈرے اللہ سے اور گھروں میں آؤ دروازوں سے اور اللہ سے ڈرتے رہو تاکہ تم اپنی مراد کو پہنچو [۲۹۶]', 'They ask you (O Muhammad SAW) about the new moons. Say: These are signs to mark fixed periods of time for mankind and for the pilgrimage. It is not Al-Birr (piety, righteousness, etc.) that you enter the houses from the back but Al-Birr (is the quality of the one) who fears Allah. So enter houses through their proper doors, and fear Allah that you may be successful.', 'They ask you about the new moons. Say: They are indicative of time for the people, and of the Hajj. It is not righteousness that you come into your houses from their backs, but righteousness is that one fears Allah. So come into houses through their doors; and fear Allah so that you may be successful.'),
(197, 2, 190, 24, 8, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ قَاتِلُوۡا فِیۡ سَبِیۡلِ اللّٰہِ الَّذِیۡنَ یُقَاتِلُوۡنَکُمۡ وَ لَا تَعۡتَدُوۡا ؕ اِنَّ اللّٰہَ  لَا یُحِبُّ الۡمُعۡتَدِیۡنَ ﴿۱۹۰﴾', 'اور جو لوگ تم سے لڑتے ہیں تم بھی اللہ کی راہ میں ان سے لڑو۔ مگر زیادتی نہ کرنا کہ اللہ زیادتی کرنے والوں کو دوست نہیں رکھتا۔', 'اور لڑو اللہ کی راہ میں ان لگوں سے جو لڑتے ہیں تم سے [۲۹۷] اور کسی پر زیادتی مت کرو [۲۹۸] بیشک اللہ تعالیٰ ناپسند کرتا ہے زیادتی کرنے والوں کو', 'And fight in the Way of Allah those who fight you, but transgress not the limits. Truly, Allah likes not the transgressors. (This Verse is the first one that was revealed in connection with Jihad, but it was supplemented by another (V.9:36)).', 'Fight in the way of Allah against those who fight you, and do not transgress. Verily, Allah does not like the transgressors.'),
(198, 2, 191, 24, 8, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ اقۡتُلُوۡہُمۡ حَیۡثُ ثَقِفۡتُمُوۡہُمۡ وَ اَخۡرِجُوۡہُمۡ مِّنۡ حَیۡثُ اَخۡرَجُوۡکُمۡ وَ الۡفِتۡنَۃُ اَشَدُّ مِنَ الۡقَتۡلِ ۚ وَ لَا تُقٰتِلُوۡہُمۡ عِنۡدَ الۡمَسۡجِدِ الۡحَرَامِ حَتّٰی یُقٰتِلُوۡکُمۡ فِیۡہِ ۚ فَاِنۡ قٰتَلُوۡکُمۡ فَاقۡتُلُوۡہُمۡ ؕ  کَذٰلِکَ جَزَآءُ الۡکٰفِرِیۡنَ ﴿۱۹۱﴾', 'اور ان کو جہاں پاؤ قتل کر دو۔ اور جہاں سے انہوں نے تم کو نکالا ہے۔ یعنی مکے سے وہاں سے تم بھی ان کو نکال دو۔ اور دین سے گمراہ کرنے کا فساد قتل و خونریزی سے کہیں بڑھ کر ہے اور جب تک وہ تم سے مسجد حرام یعنی خانہ کعبہ کے پاس نہ لڑیں تم بھی وہاں ان سے نہ لڑنا۔ ہاں اگر وہ تم سے لڑیں تو تم ان کو قتل کر ڈالو۔ کافروں کی یہی سزا ہے۔', 'اور مار ڈالو ان کو جس جگہ پاؤ اور نکال دو ان کو جہاں سے انہوں نے تم کو نکالا [۲۹۹] اور دین سے بچلانا مار ڈالنے سے بھی زیادہ سخت ہے [۳۰۰] اور نہ لڑو ان سے مسجدالحرام کے پاس جب تک کہ وہ نہ لڑیں تم سے اس جگہ پھر اگر وہ خود ہی لڑیں تم سےتو ان کو مارو یہی ہے سزا کافروں کی [۳۰۱]', 'And kill them wherever you find them, and turn them out from where they have turned you out. And Al-Fitnah is worse than killing. And fight not with them at Al-Masjid-al-Haram (the sanctuary at Makkah), unless they (first) fight you there. But if they attack you, then kill them. Such is the recompense of the disbelievers.', 'Kill them wherever you find them, and drive them out from where they drove you out, as Fitnah (to create disorder) is more severe than killing. However, do not fight them near Al-Masjid-ul-Harām (the Sacred Mosque in Makkah) unless they fight you there. However, if they fight you (there) you may kill them. Such is the reward of the disbelievers.'),
(199, 2, 192, 24, 8, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'فَاِنِ انۡتَہَوۡا فَاِنَّ اللّٰہَ غَفُوۡرٌ رَّحِیۡمٌ ﴿۱۹۲﴾', 'پھر اور اگر وہ باز آجائیں تو اللہ بخشنے والا ہے رحم کرنے والا ہے۔', 'پھر اگر وہ باز آئیں تو بیشک اللہ بہت بخشنے والا نہایت مہربان ہے [۳۰۲]', 'But if they cease, then Allah is Oft-Forgiving, Most Merciful.', 'But if they desist, then indeed, Allah is Most-Forgiving, Very- Merciful.'),
(200, 2, 193, 24, 8, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ قٰتِلُوۡہُمۡ حَتّٰی لَا تَکُوۡنَ فِتۡنَۃٌ وَّ یَکُوۡنَ الدِّیۡنُ  لِلّٰہِ ؕ فَاِنِ انۡتَہَوۡا فَلَا عُدۡوَانَ  اِلَّا عَلَی الظّٰلِمِیۡنَ ﴿۱۹۳﴾', 'اور ان سے اس وقت تک لڑتے رہنا کہ فساد نابود ہو جائے اور ملک میں اللہ ہی کا دین  غالب ہو جائے۔ پھر اگر وہ فساد سے باز آجائیں تو ظالموں کے سوا کسی پر زیادتی نہیں کرنی چاہیے۔', 'اور لڑو ان سے یہاں تک کہ نہ باقی رہے فساد اور حکم رہے خدا تعالیٰ ہی کا پھر اگر وہ باز آئیں تو کسی پر زیادتی نہیں مگر ظالموں پر [۳۰۳]', 'And fight them until there is no more Fitnah (disbelief and worshipping of others along with Allah) and (all and every kind of) worship is for Allah (Alone). But if they cease, let there be no transgression except against Az-Zalimoon (the polytheists, and wrong-doers, etc.)', 'Fight them until there is no Fitnah any more, and obedience remains for Allah. But, if they desist, then aggression is not allowed except against the transgressors.'),
(201, 2, 194, 24, 8, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اَلشَّہۡرُ الۡحَرَامُ  بِالشَّہۡرِ الۡحَرَامِ وَ الۡحُرُمٰتُ قِصَاصٌ ؕ فَمَنِ اعۡتَدٰی عَلَیۡکُمۡ فَاعۡتَدُوۡا عَلَیۡہِ بِمِثۡلِ مَا اعۡتَدٰی عَلَیۡکُمۡ  ۪ وَ اتَّقُوا اللّٰہَ وَ اعۡلَمُوۡۤا  اَنَّ اللّٰہَ مَعَ  الۡمُتَّقِیۡنَ ﴿۱۹۴﴾', 'ادب کا مہینہ ادب کے مہینے کے مقابل ہے اور ادب کی چیزیں ایک دوسرے کا بدلہ ہیں۔ پس اگر کوئی تم پر زیادتی کرے تو جیسی زیادتی وہ تم پر کرے ویسی ہی تم اس پر کرو۔ اور اللہ سے ڈرتے رہو اور جان رکھو کہ اللہ ڈرنے والوں کے ساتھ ہے۔', 'حرمت والا مہینہ بدلا (مقابل) ہے حرمت والے مہینے کا اور ادب رکھنے میں بدلا ہے پھر جس نے تم پر زیادتی کی تم اس پر زیادتی کرو جیسی اس نے زیادتی کی تم پر اور ڈرتے رہو اللہ سے اور جان لو کہ اللہ ساتھ ہے پرہیزگاروں کے [۳۰۴]', 'The sacred month is for the sacred month, and for the prohibited things, there is the Law of Equality (Qisas). Then whoever transgresses the prohibition against you, you transgress likewise against him. And fear Allah, and know that Allah is with Al-Muttaqoon (the pious - see V.2:2) .', 'The holy month for the holy month, and the sanctities are subject to retribution. So when anyone commits aggression against you, be aggressive against him in the like manner as he did against you, and fear Allah, and be sure that Allah is with the God-fearing.'),
(202, 2, 195, 24, 8, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ اَنۡفِقُوۡا فِیۡ سَبِیۡلِ اللّٰہِ وَ لَا تُلۡقُوۡا بِاَیۡدِیۡکُمۡ  اِلَی التَّہۡلُکَۃِ ۚۖۛ وَ اَحۡسِنُوۡا ۚۛ اِنَّ اللّٰہَ یُحِبُّ الۡمُحۡسِنِیۡنَ ﴿۱۹۵﴾', 'اور اللہ کی راہ میں مال خرچ کرو اور اپنے آپ کو ہلاکت میں نہ ڈالو اور نیکی کرو۔ بیشک اللہ نیکی کرنے والوں کو دوست رکھتا ہے۔', 'اور خرچ کرو اللہ کی راہ میں اور نہ ڈالو اپنی جان کو ہلاکت میں [۳۰۵] اور نیکی کرو بیشک اللہ دوست رکھتا ہے نیکی کرنے والوں کو', 'And spend in the Cause of Allah (i.e. Jihad of all kinds, etc.) and do not throw yourselves into destruction (by not spending your wealth in the Cause of Allah), and do good. Truly, Allah loves Al-Muhsinoon (the good-doers).', 'Spend in the way of Allah and do not put yourselves into destruction, and do good. Of course, Allah loves those who do good.'),
(203, 2, 196, 24, 8, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ اَتِمُّوا الۡحَجَّ وَ الۡعُمۡرَۃَ  لِلّٰہِ ؕ فَاِنۡ اُحۡصِرۡتُمۡ  فَمَا اسۡتَیۡسَرَ مِنَ الۡہَدۡیِ ۚ وَ لَا تَحۡلِقُوۡا رُءُوۡسَکُمۡ حَتّٰی یَبۡلُغَ الۡہَدۡیُ  مَحِلَّہٗ ؕ فَمَنۡ کَانَ مِنۡکُمۡ مَّرِیۡضًا اَوۡ بِہٖۤ اَذًی مِّنۡ رَّاۡسِہٖ فَفِدۡیَۃٌ مِّنۡ صِیَامٍ اَوۡ صَدَقَۃٍ اَوۡ نُسُکٍ ۚ فَاِذَاۤ  اَمِنۡتُمۡ ٝ فَمَنۡ تَمَتَّعَ بِالۡعُمۡرَۃِ  اِلَی الۡحَجِّ فَمَا اسۡتَیۡسَرَ مِنَ الۡہَدۡیِ ۚ فَمَنۡ لَّمۡ  یَجِدۡ فَصِیَامُ ثَلٰثَۃِ اَیَّامٍ فِی الۡحَجِّ وَ سَبۡعَۃٍ اِذَا  رَجَعۡتُمۡ ؕ تِلۡکَ عَشَرَۃٌ کَامِلَۃٌ  ؕ ذٰلِکَ لِمَنۡ لَّمۡ یَکُنۡ اَہۡلُہٗ حَاضِرِی الۡمَسۡجِدِ الۡحَرَامِ ؕ وَ اتَّقُوا اللّٰہَ وَ اعۡلَمُوۡۤا  اَنَّ اللّٰہَ  شَدِیۡدُ  الۡعِقَابِ ﴿۱۹۶﴾٪', 'اور اللہ کی خوشنودی کے لئے حج اور عمرے کو پورا کرو۔ اور اگر راستے میں روک لئے جاؤ تو جیسی قربانی میّسر ہو کر دو اور جب تک قربانی اپنے مقام پر نہ پہنچ جائے سر نہ منڈاؤ۔ اور اگر کوئی تم میں بیمار ہو یا اس کے سر میں کسی طرح کی تکلیف ہو۔ تو اگر وہ سر منڈوا لے تو اس کے بدلے روزے رکھے یا صدقہ دے یا قربانی کرے۔ پھر جب تکلیف دور ہو کر تم مطمئن ہو جاؤ۔ تو جو تم میں حج کے وقت تک عمرے سے فائدہ اٹھانا چاہے وہ جیسی قربانی میّسر ہو کرے۔ اور جس کو قربانی نہ ملے وہ تین روزے ایام حج میں رکھے اور سات جب واپس ہو۔ یہ پورے دس ہوئے۔ یہ حکم اس شخص کے لئے  ہے جس کے اہل و عیال مکے میں نہ رہتے ہوں اور اللہ سے ڈرتے رہو اور جان رکھو کہ اللہ سخت عذاب دینے والا ہے۔', 'اورپورا کرو حج اور عمرہ اللہ کے واسطے [۳۰۶] پھر اگر تم روک دیے جاؤ تو تم پر ہے جو کچھ کہ میسر ہو قربانی سے اور حجامت نہ کرو اپنے سروں کی جب تک پہنچ نہ چکے قربانی اپنے ٹھکانے پر [۳۰۷] پھر جو کوئی تم میں سے بیمار ہو یا اس کو تکلیف ہو سر کی تو بدلا دیوے روزے یا خیرات یا قربانی[۳۰۸] پھر جب تمہاری خاطر جمع ہو تو جو کوئی فائدہ اٹھائے عمرہ کو ملا کر حج کے ساتھ تو اس پر ہے جو کچھ میسر ہو قربانی سے [۳۰۹] پھر جس کو قربانی نہ ملے تو روزے رکھے تین حج کےدنوں میں اور سات روزے جب لوٹو یہ دس روزےہو ئے پورے [۳۱۰] یہ حکم اس کے لئے ہے جسکے گھر والے نہ رہتے ہوں مسجد الحرام کے پاس [۳۱۱] اور ڈرتے رہو اللہ سے اور جان لو کہ بیشک اللہ کا عذاب سخت ہے', 'And perform properly (i.e. all the ceremonies according to the ways of Prophet Muhammad SAW), the Hajj and Umrah (i.e. the pilgrimage to Makkah) for Allah. But if you are prevented (from completing them), sacrifice a Hady (animal, i.e. a sheep, a cow, or a camel, etc.) such as you can afford, and do not shave your heads until the Hady reaches the place of sacrifice. And whosoever of you is ill or has an ailment in his scalp (necessitating shaving), he must pay a Fidyah (ransom) of either observing Saum (fasts) (three days) or giving Sadaqah (charity - feeding six poor persons) or offering sacrifice (one sheep). Then if you are in safety and whosoever performs the Umrah in the months of Hajj, before (performing) the Hajj, (i.e. Hajj-at-Tamattu and Al-Qiran), he must slaughter a Hady such as he can afford, but if he cannot afford it, he should observe Saum (fasts) three days during the Hajj and seven days after his return (to his home), making ten days in all. This is for him whose family is not present at Al-Masjid-al-Haram (i.e. non-resident of Makkah). And fear Allah much and know that Allah is Severe in punishment.', 'Accomplish the Hajj and the ‘Umrah for Allah, but if you are restricted, then (sacrifice) whatever animal of offering is available, and do not shave your heads until the offering reaches its place. But if anyone of you is ill, or has some trouble with his scalp, then there is a ransom through fasting or alms giving.And when you are safe, then, whoever avails the advantage of the ‘Umrah along with the Hajj shall make an offering of whatever animal is available. However, any one who finds none shall fast for three days during Hajj, and for seven days when you return; thus they are ten in all. This is for him whose family folk are not residents of Al-Masjid-ul-Harām. Fear Allah and be aware that Allah is severe in punishment.'),
(204, 2, 197, 25, 9, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اَلۡحَجُّ اَشۡہُرٌ مَّعۡلُوۡمٰتٌ ۚ فَمَنۡ فَرَضَ فِیۡہِنَّ الۡحَجَّ فَلَا رَفَثَ وَ لَا فُسُوۡقَ  ۙ وَ لَا جِدَالَ فِی الۡحَجِّ ؕ وَ مَا تَفۡعَلُوۡا مِنۡ خَیۡرٍ  یَّعۡلَمۡہُ اللّٰہُ  ؕؔ وَ تَزَوَّدُوۡا فَاِنَّ خَیۡرَ الزَّادِ التَّقۡوٰی ۫ وَ اتَّقُوۡنِ یٰۤاُولِی الۡاَلۡبَابِ ﴿۱۹۷﴾', 'حج کے مہینے معین ہیں جو معلوم ہیں۔ تو جو شخص ان مہینوں میں حج کی نیّت کر لے تو حج کے دنوں میں نہ عورتوں سے اختلاط کرے نہ کوئی برا کام کرے اور نہ کسی سے جھگڑے۔ اور جو نیک کام تم کرو گے وہ اللہ کو معلوم ہو جائے گا۔ اور زاد راہ یعنی رستے کا خرچ ساتھ لے جاؤ کیونکہ بہترین زاد راہ پرہیزگاری ہے۔ اور اے اہل عقل مجھی سے ڈرتے رہو۔', 'حج کے چند مہینے ہیں معلوم [۳۱۲] پھر جس نے لازم کر لیا ان میں حج تو بے حجاب ہونا جائز نہیں عورت سے اور نہ گناہ کرنا اور نہ جھگڑا کرنا حج کے زمانہ میں اور جو کچھ تم کرتے ہو نیکی اللہ اس کو جانتا ہے [۲۱۳] اور زاد راہ لے لیا کرو کہ بیشک بہتر فائدہ زاد راہ کا بچنا ہے سوال سے اور مجھ سے ڈرتے رہو اے عقلمندو [۳۱۴]', 'The Hajj (pilgrimage) is (in) the well-known (lunar year) months (i.e. the 10th month, the 11th month and the first ten days of the 12th month of the Islamic calendar, i.e. two months and ten days). So whosoever intends to perform Hajj therein by assuming Ihram), then he should not have sexual relations (with his wife), nor commit sin, nor dispute unjustly during the Hajj. And whatever good you do, (be sure) Allah knows it. And take a provision (with you) for the journey, but the best provision is At-Taqwa (piety, righteousness, etc.). So fear Me, O men of understanding!', 'The Hajj is (to be performed in) the months that are well-known. So whoever undertakes Hajj in them, there should be no obscenity, no sin, no quarrel in the Hajj. Whatever good you do, Allah will know it. Take provisions along, for the merit of (having) provision is to abstain (from begging), and fear Me, O men of understanding!'),
(205, 2, 198, 25, 9, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'لَیۡسَ عَلَیۡکُمۡ جُنَاحٌ اَنۡ تَبۡتَغُوۡا فَضۡلًا مِّنۡ رَّبِّکُمۡ ؕ فَاِذَاۤ اَفَضۡتُمۡ مِّنۡ عَرَفٰتٍ فَاذۡکُرُوا اللّٰہَ عِنۡدَ الۡمَشۡعَرِ الۡحَرَامِ ۪ وَ اذۡکُرُوۡہُ  کَمَا ہَدٰىکُمۡ ۚ وَ اِنۡ  کُنۡتُمۡ مِّنۡ قَبۡلِہٖ  لَمِنَ الضَّآلِّیۡنَ ﴿۱۹۸﴾', 'اس کا تمہیں کچھ گناہ نہیں کہ حج کے دنوں میں بذریعہ تجارت اپنے پروردگار سے روزی طلب کرو اور جب عرفات سے واپس ہونے لگو تو مشعر حرام یعنی مزدلفہ میں اللہ کا ذکر کرو اور اس طرح ذکر کرو جس طرح اس نے تمکو سکھایا اور اس سے پیشتر تم لوگ ان طریقوں سے محض ناواقف تھے۔', 'کچھ گناہ نہیں تم پر کہ تلاش کرو فضل اپنے رب کا [۳۱۵] پھر جب طواف کے لئے لوٹو عرفات سے تو یاد کرو اللہ کو نزدیک مشعر الحرام کے [۳۱۶] اور اس کو یاد کرو جس طرح تم کو سکھلایا اور بیشک تم تھے اس سے پہلے ناواقف[۳۱۷]', 'There is no sin on you if you seek the Bounty of your Lord (during pilgrimage by trading, etc.). Then when you leave Arafat, remember Allah (by glorifying His Praises, i.e. prayers and invocations, etc.) at the Mashar-il-Haram. And remember Him (by invoking Allah for all good, etc.) as He has guided you, and verily, you were, before, of those who were astray.', 'There is no sin on you that you seek the grace of your Lord (by trading). Later, when you flow down from ‘Arafāt, recite the name of Allah near Al-Mash‘ar-ul-Harām (the Sacred Monument), and recite His name as He has guided you, while before it, you were among the astray.'),
(206, 2, 199, 25, 9, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'ثُمَّ  اَفِیۡضُوۡا مِنۡ حَیۡثُ اَفَاضَ النَّاسُ وَ اسۡتَغۡفِرُوا اللّٰہَ  ؕ اِنَّ اللّٰہَ غَفُوۡرٌ رَّحِیۡمٌ ﴿۱۹۹﴾', 'پھر جہاں سے اور لوگ واپس ہوں وہیں سے تم بھی واپس ہو اور اللہ سے بخشش مانگو۔ بیشک اللہ بخشنے والا ہے رحمت کرنے والا ہے۔', 'پھر طواف کے لئے پھرو جہاں سے سب لوگ پھریں اور مغفرت چاہو اللہ سے بیشک اللہ تعالیٰ بخشنے والا ہے مہربان [۳۱۸]', 'Then depart from the place whence all the people depart and ask Allah for His Forgiveness. Truly, Allah is Oft-Forgiving, Most-Merciful.', 'Then flow down from where the people flow, and seek forgiveness from Allah. Certainly Allah is Most-Forgiving, Very-Merciful.'),
(207, 2, 200, 25, 9, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'فَاِذَا قَضَیۡتُمۡ مَّنَاسِکَکُمۡ فَاذۡکُرُوا اللّٰہَ  کَذِکۡرِکُمۡ اٰبَآءَکُمۡ اَوۡ اَشَدَّ ذِکۡرًا ؕ فَمِنَ النَّاسِ مَنۡ یَّقُوۡلُ رَبَّنَاۤ  اٰتِنَا فِی الدُّنۡیَا وَ مَا لَہٗ فِی الۡاٰخِرَۃِ  مِنۡ خَلَاقٍ ﴿۲۰۰﴾', 'پھر جب حج کے تمام ارکان پورے کر چکو تو منٰی میں اللہ کو یاد کرو جس طرح اپنے باپ دادا کو یاد کیا کرتے تھے بلکہ اس سے بھی زیادہ۔ اور بعض لوگ ایسے ہیں جو اللہ سے التجا کرتے ہیں کہ اے پروردگار ہم کو جو دینا ہے دنیا ہی میں دیدے اور ایسے لوگوں کا آخرت میں کچھ حصّہ نہیں۔', 'پھر جب پورے کر چکو اپنے حج کے کام کو تو یاد کرو اللہ کو جیسے تم یاد کرتے تھے اپنے باپ دادوں کو بلکہ اس سے بھی زیادہ یاد کرو [۳۱۹] پھر کوئی آدمی تو کہتا ہے اے رب ہمارے دے ہم کو دنیا میں اور اس کے لئے آخرت میں کچھ حصہ نہیں', 'So when you have accomplished your Manasik ((i.e. Ihram, Tawaf of the Kabah and As-Safa and Al-Marwah), stay at Arafat, Muzdalifah and Mina, Ramy of Jamarat, (stoning of the specified pillars in Mina) slaughtering of Hady (animal, etc.)). Remember Allah as you remember your forefathers or with a far more remembrance. But of mankind there are some who say: \"Our Lord! Give us (Your Bounties) in this world!\" and for such there will be no portion in the Hereafter.', 'Once you have fulfilled your modes of worship in Hajj, recite the name of Allah, as you would speak of your forefathers or even with greater fervor. Now among the people there is one who says: “Our Lord, give to us in this world...” and he has no share in the Hereafter.'),
(208, 2, 201, 25, 9, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ مِنۡہُمۡ مَّنۡ یَّقُوۡلُ رَبَّنَاۤ  اٰتِنَا فِی الدُّنۡیَا حَسَنَۃً  وَّ فِی الۡاٰخِرَۃِ حَسَنَۃً  وَّ قِنَا عَذَابَ النَّارِ ﴿۲۰۱﴾', 'اور بعض ایسے ہیں کہ دعا کرتے ہیں کہ پروردگار ہم کو دنیا میں بھی نعمت عطا فرما اور آخرت میں بھی نعمت بخشیو اور دوزخ کے عذاب سے محفوظ رکھیو۔', 'اور کوئی ان میں کہتا ہے اے رب ہمارے دے ہم کو دنیا میں خوبی اور آخرت میں خوبی اور بچا لے ہم کو دوزخ کے عذاب سے', 'And of them there are some who say: \"Our Lord! Give us in this world that which is good and in the Hereafter that which is good, and save us from the torment of the Fire!\"', 'Yet there is another among them who says: “Our Lord, give us good in this world and good in the Hereafter, and save us from the punishment of Fire.”'),
(209, 2, 202, 25, 9, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اُولٰٓئِکَ لَہُمۡ نَصِیۡبٌ مِّمَّا کَسَبُوۡا ؕ وَ اللّٰہُ  سَرِیۡعُ  الۡحِسَابِ ﴿۲۰۲﴾', 'یہی لوگ ہیں جن کے لئے ان کے کاموں کا حصّہ یعنی اجر نیک تیار ہے اور اللہ جلد حساب لینے والا ہے۔', 'انہی لوگوں کے واسطے حصہ ہے اپنی کمائی سے [۳۲۰] اور اللہ جلد حساب لینے والا ہے [۳۲۱]', 'For them there will be alloted a share for what they have earned. And Allah is Swift at reckoning.', 'For them there is a share of what they have earned; and Allah is swift at reckoning.'),
(210, 2, 203, 25, 9, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ اذۡکُرُوا اللّٰہَ فِیۡۤ  اَیَّامٍ  مَّعۡدُوۡدٰتٍ ؕ فَمَنۡ تَعَجَّلَ فِیۡ یَوۡمَیۡنِ فَلَاۤ اِثۡمَ عَلَیۡہِ ۚ وَ مَنۡ تَاَخَّرَ فَلَاۤ اِثۡمَ عَلَیۡہِ  ۙ لِمَنِ اتَّقٰی ؕ وَ اتَّقُوا اللّٰہَ وَ اعۡلَمُوۡۤا اَنَّکُمۡ  اِلَیۡہِ تُحۡشَرُوۡنَ ﴿۲۰۳﴾', 'اور قیام منٰی کے دنوں میں جو گنتی کے دن ہیں اللہ کو یاد کرو۔ اگر کوئی جلدی کرے اور دو ہی دن میں چل دے تو اس پر بھی کچھ گناہ نہیں۔ اور جو بعد تک ٹھہرا رہے اس پر بھی کچھ گناہ نہیں۔ یہ باتیں اس شخص کے لئے ہیں جو اللہ سے ڈرے اور تم لوگ اللہ سے ڈرتے رہو اور جان رکھو کہ تم سب اس کے پاس جمع کئے جاؤ گے۔', 'اور یاد کرو اللہ کو گنتی کے چند دنوں میں [۳۲۲] پھر جو کوئی جلد چلا گیا دو ہی دن میں تو اس پر گناہ نہیں اور جو کوئی رہ گیا تو اس پر بھی گناہ نہیں جو کہ ڈرتا ہے [۳۲۳] اور ڈرتے رہو اللہ سے اور جان لو بیشک تم سب اسکے پاس جمع ہو گے [۳۲۴]', 'And remember Allah during the appointed Days. But whosoever hastens to leave in two days, there is no sin on him and whosoever stays on, there is no sin on him, if his aim is to do good and obey Allah (fear Him), and know that you will surely be gathered unto Him.', 'Recite the name of Allah during the given number of days. Then whoever is early in leaving after two days, there is no sin on him, and whoever leaves later, there is no sin on him, if he is God-fearing. Fear Allah and be sure that you are going to be gathered before Him.'),
(211, 2, 204, 25, 9, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ مِنَ النَّاسِ مَنۡ یُّعۡجِبُکَ قَوۡلُہٗ فِی الۡحَیٰوۃِ الدُّنۡیَا وَ یُشۡہِدُ اللّٰہَ عَلٰی مَا فِیۡ  قَلۡبِہٖ  ۙ وَ ہُوَ  اَلَدُّ  الۡخِصَامِ ﴿۲۰۴﴾', 'اور کوئی شخص تو ایسا ہے جس کی گفتگو دنیا کی زندگی میں تم کو دلکش معلوم ہوتی ہو اور  وہ اپنے مافی الضمیر پر یعنی اس بات پر جو اسکے دل میں ہے اللہ کو گواہ بناتا ہے حالانکہ وہ سخت جھگڑالو ہے۔', 'اور بعضا آدمی وہ ہے کہ پسند آتی ہے تجھ کو اس کی بات دنیا کی زندگانی کے کاموں میں اور گواہ کرتا ہے اللہ کو اپنے دل کی بات پر اور وہ سخت جھگڑالو ہے', 'And of mankind there is he whose speech may please you (O Muhammad SAW), in this worldly life, and he calls Allah to witness as to that which is in his heart, yet he is the most quarrelsome of the opponents.', 'Among men there is one whose speech, in this life, attracts you; he even makes Allah his witness on what is in his heart, while he is extremely quarrelsome.'),
(212, 2, 205, 25, 9, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ اِذَا تَوَلّٰی سَعٰی فِی الۡاَرۡضِ لِیُفۡسِدَ فِیۡہَا وَ یُہۡلِکَ الۡحَرۡثَ وَ النَّسۡلَ ؕ وَ اللّٰہُ  لَا  یُحِبُّ الۡفَسَادَ ﴿۲۰۵﴾', 'اور جب پیٹھ پھیر کر چلا جاتا ہے تو زمین میں دوڑتا پھرتا ہے تا کہ اس میں فتنہ انگیزی کرے۔ اور کھیتی کو برباد اور انسانوں اور حیوانوں کی نسل کو نابود کر دے اور اللہ فتنہ انگیزی کو پسند نہیں کرتا۔', 'اور جب پھرے تیرے پاس سے تو دوڑتا پھرے ملک میں تاکہ اس میں خرابی ڈالے اور تباہ کرے کھیتیاں اور جانیں اور اللہ ناپسند کرتا ہے فساد کو', 'And when he turns away (from you \"O Muhammad SAW \"), his effort in the land is to make mischief therein and to destroy the crops and the cattle, and Allah likes not mischief.', 'Once he turns back, he moves about in the land trying to spread disorder in it, and to destroy the tillage and the stock; and Allah does not like disorder.'),
(213, 2, 206, 25, 9, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ اِذَا قِیۡلَ لَہُ  اتَّقِ اللّٰہَ اَخَذَتۡہُ الۡعِزَّۃُ بِالۡاِثۡمِ فَحَسۡبُہٗ جَہَنَّمُ ؕ وَ لَبِئۡسَ الۡمِہَادُ ﴿۲۰۶﴾', 'اور جب اس سے کہا جاتا ہے کہ اللہ سے خوف کر تو غرور اس کو گناہ میں پھنسا دیتا ہے سو اس کو جہنم کافی ہے اور وہ بہت برا ٹھکانہ ہے۔', 'اور جب اس سے کہا جائے کہ اللہ سے ڈرو تو آمادہ کرےاس کو غرور گناہ پر سو کافی ہے اس کو دوزخ اور وہ بیشک برا ٹھکانہ ہے [۳۲۵]', 'And when it is said to him, \"Fear Allah\", he is led by arrogance to (more) crime. So enough for him is Hell, and worst indeed is that place to rest!', 'When it is said to him, “Fear Allah”, he is tempted by arrogance to (commit) sin. Hell is then enough for him, and it is indeed an evil bed to rest.'),
(214, 2, 207, 25, 9, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ مِنَ النَّاسِ مَنۡ یَّشۡرِیۡ نَفۡسَہُ ابۡتِغَآءَ مَرۡضَاتِ اللّٰہِ ؕ وَ اللّٰہُ  رَءُوۡفٌۢ بِالۡعِبَادِ ﴿۲۰۷﴾', 'اور کوئی شخص ایسا ہے کہ اللہ کی خوشنودی حاصل کرنے کے لئے اپنی جان بیچ ڈالتا ہے۔ اور اللہ بندوں پر بہت مہربان ہے۔', 'اور لوگوں میں ایک شخص وہ ہے کہ بیچتا ہے اپنی جان کو اللہ کی رضا جوئی میں [۳۲۶] اور اللہ نہایت مہربان ہے اپنے بندوں پر [۳۲۷]', 'And of mankind is he who would sell himself, seeking the Pleasure of Allah. And Allah is full of Kindness to (His) slaves.', 'And among men there is one who sells his very soul to seek the pleasure of Allah, and Allah is Very-Kind to His servants.'),
(215, 2, 208, 25, 9, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوا ادۡخُلُوۡا فِی السِّلۡمِ  کَآفَّۃً  ۪ وَ لَا تَتَّبِعُوۡا خُطُوٰتِ الشَّیۡطٰنِ ؕ اِنَّہٗ لَکُمۡ عَدُوٌّ مُّبِیۡنٌ ﴿۲۰۸﴾', 'مومنو! اسلام میں پورے پورے داخل ہو جاؤ اور شیطان کے پیچھے نہ چلو۔ وہ تو تمہارا کھلا دشمن ہے۔', 'اے ایمان والو داخل ہو جاؤ اسلام میں پورے [۲۲۸] اور مت چلو قدموں پر شیطان کے بیشک وہ تمہارا صریح دشمن ہے [۳۲۹]', 'O you who believe! Enter perfectly in Islam (by obeying all the rules and regulations of the Islamic religion) and follow not the footsteps of Shaitan (Satan). Verily! He is to you a plain enemy.', 'O you who believe, enter Islam completely, and do not follow the footsteps of Satan. Surely, he is an open enemy for you;'),
(216, 2, 209, 25, 9, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'فَاِنۡ زَلَلۡتُمۡ  مِّنۡۢ بَعۡدِ مَا جَآءَتۡکُمُ الۡبَیِّنٰتُ فَاعۡلَمُوۡۤا اَنَّ اللّٰہَ عَزِیۡزٌ حَکِیۡمٌ ﴿۲۰۹﴾', 'پھر اگر تم احکام روشن پہنچ جانے کے بعد لڑکھڑا جاؤ تو جان رکھو کہ اللہ غالب ہے حکمت والا ہے۔', 'پھر اگر تم بچلنے لگو اس کے بعد اس کہ پہنچ چکے تم کو صاف حکم تو جان رکھو کہ بیشک اللہ زبردست ہے حکمت والا [۳۳۰]', 'Then if you slide back after the clear signs (Prophet Muhammad SAW and this Quran, and Islam) have come to you, then know that Allah is All-Mighty, All-Wise.', 'and if you slip, even after clear signs have come to you, then you must know that Allah is Mighty, Wise.'),
(217, 2, 210, 25, 9, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'ہَلۡ یَنۡظُرُوۡنَ  اِلَّاۤ  اَنۡ یَّاۡتِیَہُمُ اللّٰہُ فِیۡ ظُلَلٍ مِّنَ الۡغَمَامِ وَ الۡمَلٰٓئِکَۃُ وَ قُضِیَ الۡاَمۡرُ ؕ وَ  اِلَی اللّٰہِ تُرۡجَعُ  الۡاُمُوۡرُ ﴿۲۱۰﴾٪', 'کیا یہ لوگ اسی بات کے منتظر ہیں کہ ان پر اللہ کا عذاب بادل کے سائبانوں میں آ نازل ہو اور فرشتے بھی اتر آئیں اور کام تمام کر دیا جائے۔ اور سب کاموں کا رجوع اللہ ہی کی طرف ہے۔', 'کیا وہ اسی کی راہ دیکھتے ہیں کہ آوے ان پر اللہ ابر کے سائبانوں میں اور فرشتے اور طے ہو جاوے قصہ اور اللہ ہی کی طرف لوٹیں گے سب کام [۳۳۱]', 'Do they then wait for anything other than that Allah should come to them in the shadows of the clouds and the angels? (Then) the case would be already judged. And to Allah return all matters (for decision).', 'They are looking for nothing (to accept the truth) but that Allah (Himself) comes upon them in canopies of cloud with angels, and the matter is closed. To Allah shall all matters be returned.'),
(218, 2, 211, 26, 10, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'سَلۡ بَنِیۡۤ  اِسۡرَآءِیۡلَ  کَمۡ اٰتَیۡنٰہُمۡ مِّنۡ اٰیَۃٍۭ بَیِّنَۃٍ ؕ وَ مَنۡ یُّبَدِّلۡ نِعۡمَۃَ اللّٰہِ مِنۡۢ بَعۡدِ مَا جَآءَتۡہُ فَاِنَّ اللّٰہَ شَدِیۡدُ الۡعِقَابِ ﴿۲۱۱﴾', 'اے پیغمبر بنی اسرائیل سے پوچھو کہ ہم نے ان کو کتنی کھلی نشانیاں دیں اور جو شخص اللہ کی نعمت کو اپنے پاس آنے کے بعد بدل دے تو اللہ سخت عذاب کرنے والا ہے۔', 'پوچھ بنی اسرائیل سے کس قدر عنایت کیں ہم نے انکو نشانیاں کھلی ہوئیں [۳۳۲] اور جو کوئی بدل ڈالے اللہ کی نعمت بعد اس کے کہ پہنچ چکی ہو وہ نعمت اس کو تو اللہ کا عذاب سخت ہے [۳۳۳]', 'Ask the Children of Israel how many clear Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) We gave them. And whoever changes Allahs Favour after it had come to him, (e.g. renounces the Religion of Allah (Islam) and accepts Kufr (disbelief),) then surely, Allah is Severe in punishment.', 'Ask the Children of Isrā’īl (Israel) how many a clear sign We have given to them; and whoever changes the blessing of Allah after it has come to him, then Allah is severe in punishment.'),
(219, 2, 212, 26, 10, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'زُیِّنَ لِلَّذِیۡنَ کَفَرُوا الۡحَیٰوۃُ الدُّنۡیَا وَ یَسۡخَرُوۡنَ مِنَ الَّذِیۡنَ اٰمَنُوۡا ۘ وَ الَّذِیۡنَ اتَّقَوۡا فَوۡقَہُمۡ یَوۡمَ الۡقِیٰمَۃِ ؕ وَ اللّٰہُ یَرۡزُقُ مَنۡ یَّشَآءُ بِغَیۡرِ حِسَابٍ ﴿۲۱۲﴾', 'اور جو کافر ہیں ان کے لئے دنیا کی زندگی خوشنما کر دی گئ ہے اور وہ مومنوں سے تمسخر کرتے ہیں لیکن جو پرہیزگار ہیں وہ قیامت کے دن ان سے اوپر ہوں گے اور اللہ جس کو چاہتا ہے بے حساب رزق دیتا ہے۔', 'فریفتہ کا ہے کافروں کو دنیا کی زندگی پر اور ہنستے ہیں ایمان والوں کو [۳۳۴] اور جو پرہیزگار ہیں وہ ان کافروں سے بالاتر ہو ں گے قیامت کے دن اور اللہ روزی دیتا ہے جس کو چاہے بے شمار [۲۳۵]', 'Beautified is the life of this world for those who disbelieve, and they mock at those who believe. But those who obey Allahs Orders and keep away from what He has forbidden, will be above them on the Day of Resurrection. And Allah gives (of His Bounty, Blessings, Favours, Honours, etc. on the Day of Resurrection) to whom He wills without limit.', 'Adorned is the present life for those who disbelieve, and they laugh at those who believe, while those who fear Allah shall be above them on the Day of Resurrection. Allah gives provision to whom He wills without measure.'),
(220, 2, 213, 26, 10, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'کَانَ النَّاسُ اُمَّۃً  وَّاحِدَۃً ۟ فَبَعَثَ اللّٰہُ النَّبِیّٖنَ مُبَشِّرِیۡنَ وَ مُنۡذِرِیۡنَ  ۪ وَ اَنۡزَلَ مَعَہُمُ  الۡکِتٰبَ بِالۡحَقِّ لِیَحۡکُمَ بَیۡنَ النَّاسِ فِیۡمَا اخۡتَلَفُوۡا فِیۡہِ ؕ وَ مَا اخۡتَلَفَ فِیۡہِ اِلَّا الَّذِیۡنَ اُوۡتُوۡہُ مِنۡۢ بَعۡدِ مَا جَآءَتۡہُمُ الۡبَیِّنٰتُ بَغۡیًۢا بَیۡنَہُمۡ ۚ فَہَدَی اللّٰہُ الَّذِیۡنَ اٰمَنُوۡا لِمَا اخۡتَلَفُوۡا فِیۡہِ مِنَ الۡحَقِّ بِاِذۡنِہٖ ؕ وَ اللّٰہُ  یَہۡدِیۡ مَنۡ یَّشَآءُ  اِلٰی صِرَاطٍ مُّسۡتَقِیۡمٍ ﴿۲۱۳﴾', 'پہلے تو سب لوگوں کا ایک ہی مذہب تھا لیکن وہ آپس میں اختلاف کرنے لگے تو اللہ نے ان کی طرف بشارت دینے والے اور ڈر سنانے والے پیغمبر بھیجے اور ان پر سچائی کے ساتھ کتابیں نازل کیں تا کہ جن امور میں لوگ اختلاف کرتے تھے ان کا ان میں فیصلہ کر دے۔ اور اس میں اختلاف بھی انہیں لوگوں نے کیا جن کو کتاب دی گئ تھی باوجودیکہ ان کے پاس کھلے ہوئے احکام آ چکے تھے اور یہ اختلاف انہوں نے صرف آپس کی ضد سے کیا تو جس امر حق میں وہ اختلاف کرتے تھے اللہ نے اپنی مہربانی سے مومنوں کو اس کی راہ دکھا دی اور اللہ جس کو چاہتا ہے سیدھا رستہ دکھا دیتا ہے۔', 'تھے سب لوگو ایک دین پر پھر بھیجے اللہ نے پیغمبر خوشخبری سنانے والے اور ڈرانے والے اور اتاری انکےساتھ کتاب سچی کہ فیصلہ کرے لوگوں میں جس بات میں وہ جھگڑا کریں اور نہیں جھگڑا ڈالا کتاب میں مگر انہی لوگوں نے جن کو کتاب ملی تھی اس کے بعد کہ ان کو پہنچ چکے صاف حکم آپس کی ضد سے پھر اب ہدایت کی اللہ نے ایمان والوں کو اس سچی بات کی جس میں وہ جھگڑ رہے تھے اپنے حکم سے اور اللہ بتلاتا ہے جس کو چاہے سیدھا راستہ [۳۳۶]', 'Mankind were one community and Allah sent Prophets with glad tidings and warnings, and with them He sent the Scripture in truth to judge between people in matters wherein they differed. And only those to whom (the Scripture) was given differed concerning it after clear proofs had come unto them through hatred, one to another. Then Allah by His Leave guided those who believed to the truth of that wherein they differed. And Allah guides whom He wills to a Straight Path.', 'All men used to be a single ’Ummah (i.e. on a single faith). Then (after they differed in matters of faith), Allah sent prophets carrying good news and warning, and sent down with them the Book with Truth to judge between people in matters of their dispute. But it was no other than those to whom it (the Book) was given who, led by envy against each other, disputed it after the clear signs had come to them. Then Allah, by His will, guided those who believed to the truth over which they disputed; and Allah guides whom He wills to the straight path.'),
(221, 2, 214, 26, 10, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اَمۡ حَسِبۡتُمۡ  اَنۡ تَدۡخُلُوا الۡجَنَّۃَ وَ لَمَّا یَاۡتِکُمۡ مَّثَلُ الَّذِیۡنَ خَلَوۡا مِنۡ قَبۡلِکُمۡ ؕ مَسَّتۡہُمُ الۡبَاۡسَآءُ  وَ الضَّرَّآءُ وَ زُلۡزِلُوۡا حَتّٰی یَقُوۡلَ الرَّسُوۡلُ وَ الَّذِیۡنَ اٰمَنُوۡا مَعَہٗ مَتٰی نَصۡرُ  اللّٰہِ ؕ اَلَاۤ اِنَّ نَصۡرَ اللّٰہِ  قَرِیۡبٌ ﴿۲۱۴﴾', 'کیا تم یہ خیال کرتے ہو کہ یونہی بہشت میں داخل ہو جاؤ گے اور ابھی تم کو پہلے لوگوں کی سی مشکلیں تو پیش آئی ہی نہیں۔ ان کو بڑی بڑی سختیاں اور تکلیفیں پہنچیں اور وہ صعوبتوں میں ہلا ہلا دئیے گئے۔ یہاں تک کہ پیغمبر اور مومن لوگ جو ان کے ساتھ تھے سب پکار اٹھے کہ کب اللہ کی مدد آئے گی۔ دیکھو اللہ کی مدد عنقریب آیا چاہتی ہے۔', 'کیا تم کو یہ خیال ہے کہ جنت میں چلے جاؤ گے حالانکہ تم پر نہیں گذرے حالات ان لوگوں جیسے جو  ہو چکے تم سے پہلے کہ پہنچی انکو سختی اور تکلیف اور جھڑ جھڑائے گئے یہاں تک کہ کہنے لگا رسول اور جو اس کے ساتھ ایمان لائے کب آوے گی اللہ کی مدد سن رکھو اللہ کی مدد قریب ہے [۳۳۷]', 'Or think you that you will enter Paradise without such (trials) as came to those who passed away before you? They were afflicted with severe poverty and ailments and were so shaken that even the Messenger and those who believed along with him said, \"When (will come) the Help of Allah?\" Yes! Certainly, the Help of Allah is near!', 'Do you think that you will enter Paradise while you have not yet been visited by (difficult) circumstances like those that were faced by the people who passed away before you? They were afflicted by hardship and suffering, and were so shaken down that the prophet, and those who believed with him, started saying: “When (will come) the help of Allah?” (Then, they were comforted by the Prophet who said to them) ‘Behold, the help of Allah is near.’'),
(222, 2, 215, 26, 10, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'یَسۡـَٔلُوۡنَکَ مَا ذَا یُنۡفِقُوۡنَ ۬ؕ قُلۡ مَاۤ اَنۡفَقۡتُمۡ  مِّنۡ خَیۡرٍ فَلِلۡوَالِدَیۡنِ وَ الۡاَقۡرَبِیۡنَ وَ الۡیَتٰمٰی وَ الۡمَسٰکِیۡنِ وَ ابۡنِ‌السَّبِیۡلِ ؕ وَ مَا تَفۡعَلُوۡا مِنۡ خَیۡرٍ فَاِنَّ اللّٰہَ بِہٖ عَلِیۡمٌ ﴿۲۱۵﴾', 'اے نبی لوگ تم سے پوچھتے ہیں کہ اللہ کی راہ میں کس طرح کا مال خرچ کریں۔ کہہ دو کہ جو چاہو خرچ کرو لیکن جو مال خرچ کرنا چاہو وہ درجہ بدرجہ اہل استحقاق یعنی ماں باپ کو اور قریب کے رشتہ داروں کو اور یتیموں کو اور محتاجوں کو اور مسافروں کو سب کو دو اور جو بھلائی تم کرو گے اللہ اس کو جانتا ہے۔', 'تجھ سے پوچھتے ہیں کہ کیا چیز خرچ کریں [۳۳۸] کہہ دو کہ جو کچھ تم خرچ کرو مال سو ماں باپ کے لئے اور قرابت والوں کے اور یتیموں کے اور محتاجوں کے اور مسافروں کے اور جو کچھ کرو گے تم بھلائی سو وہ بیشک اللہ کو خوب معلوم ہے [۳۳۹]', 'They ask you (O Muhammad SAW) what they should spend. Say: Whatever you spend of good must be for parents and kindred and orphans and AlMasakin (the poor) and the wayfarers, and whatever you do of good deeds, truly, Allah knows it well.', 'They ask you as to what they should spend. Say: “Whatever good you spend should be for parents, kinsmen, orphans, the needy and the wayfarer; and whatever good you do, Allah is all-aware of it.”'),
(223, 2, 216, 26, 10, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'کُتِبَ عَلَیۡکُمُ الۡقِتَالُ وَ ہُوَ کُرۡہٌ لَّکُمۡ ۚ وَ عَسٰۤی اَنۡ تَکۡرَہُوۡا شَیۡئًا وَّ ہُوَ خَیۡرٌ لَّکُمۡ ۚ وَ عَسٰۤی اَنۡ تُحِبُّوۡا شَیۡئًا وَّ ہُوَ شَرٌّ لَّکُمۡ ؕ وَ اللّٰہُ یَعۡلَمُ  وَ اَنۡتُمۡ  لَا تَعۡلَمُوۡنَ ﴿۲۱۶﴾٪', 'مسلمانو تم پر اللہ کے رستے میں لڑنا فرض کر دیا گیا ہے اور وہ تمہیں ناگوار تو ہو گا مگر عجب نہیں کہ ایک چیز تم کو بری لگے اور وہ تمہارے حق میں بھلی ہو۔ اور عجب نہیں کہ ایک چیز تم کو بھلی لگے اور وہ تمہارے لئے مضر ہو اور ان باتوں کو اللہ ہی بہتر جانتا ہے اور تم نہیں جانتے۔', 'فرض ہوئی تم پر لڑائی [۳۴۰] اور وہ بری لگتی ہے تم کو [۳۴۱] اور شاید کہ تم کو بری لگے ایک چیز اور وہ بہتر ہو تمہارے حق میں اور شاید تم کو بھلی لگے ایک چیز اور وہ بری ہو تمہارے حق میں اور اللہ جانتا ہے اور تم نہیں جانتے [۳۴۲]', 'Jihad (holy fighting in Allahs Cause) is ordained for you (Muslims) though you dislike it, and it may be that you dislike a thing which is good for you and that you like a thing which is bad for you. Allah knows but you do not know.', 'Fighting is enjoined upon you, while it is hard on you. It could be that you dislike something, when it is good for you; and it could be that you like something when it is bad for you. Allah knows, and you do not know.'),
(224, 2, 217, 27, 11, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'یَسۡـَٔلُوۡنَکَ عَنِ الشَّہۡرِ الۡحَرَامِ  قِتَالٍ فِیۡہِ ؕ قُلۡ قِتَالٌ فِیۡہِ کَبِیۡرٌ ؕ وَ صَدٌّ عَنۡ سَبِیۡلِ اللّٰہِ وَ کُفۡرٌۢ بِہٖ وَ الۡمَسۡجِدِ الۡحَرَامِ ٭ وَ  اِخۡرَاجُ اَہۡلِہٖ مِنۡہُ اَکۡبَرُ عِنۡدَ  اللّٰہِ ۚ وَ  الۡفِتۡنَۃُ  اَکۡبَرُ مِنَ الۡقَتۡلِ ؕ وَ لَا یَزَالُوۡنَ یُقَاتِلُوۡنَکُمۡ حَتّٰی یَرُدُّوۡکُمۡ عَنۡ دِیۡنِکُمۡ   اِنِ  اسۡتَطَاعُوۡا ؕ وَ مَنۡ یَّرۡتَدِدۡ مِنۡکُمۡ عَنۡ دِیۡنِہٖ فَیَمُتۡ وَ ہُوَ کَافِرٌ فَاُولٰٓئِکَ حَبِطَتۡ اَعۡمَالُہُمۡ  فِی الدُّنۡیَا وَ الۡاٰخِرَۃِ ۚ وَ اُولٰٓئِکَ اَصۡحٰبُ النَّارِ ۚ ہُمۡ   فِیۡہَا خٰلِدُوۡنَ ﴿۲۱۷﴾', 'اے پیغمبر لوگ تم سے عزّت والے مہینوں میں لڑائی کرنے کے بارے میں دریافت کرتے ہیں۔ کہہ دو کہ ان میں لڑنا بڑا گناہ ہے۔ اور اللہ کی راہ سے روکنا اور اس سے کفر کرنا اور مسجد حرام  یعنی خانہ کعبہ میں جانے سے بند کرنا اور اہل مسجد کو اس میں سے نکال دینا جو یہ کفار کرتے ہیں اللہ کے نزدیک اس سے بھی زیادہ گناہ ہے۔ اور فتنہ انگیزی خونریزی سے بھی بڑھ کر ہے۔ اور یہ لوگ ہمیشہ تم سے لڑتے رہیں گے یہاں تک کہ اگر مقدور رکھیں تو تم کو تمہارے دین سے پھیر دیں اور جو کوئی تم میں سے اپنے دین سے پھر کر کافر ہو جائے گا اور کافر ہی مرے گا تو ایسے لوگوں کے اعمال دنیا اور آخرت دونوں میں برباد ہو جائیں گے اور یہی لوگ دوزخ میں جانے والے ہیں جس میں ہمیشہ رہیں گے۔', 'تجھ سے پوچھتے ہیں مہینہ حرام کو کہ اس میں لڑنا کیسا [۲۴۳] کہہ دے لڑائی اس میں بڑا گناہ ہے [۳۴۴] اور روکنا اللہ کی راہ سے اور اس کو نہ ماننا اور مسجد الحرام سے روکنا اور نکال دینا اسکے لوگوں کو وہاں سے اس سے بھی زیادہ گناہ ہے اللہ کے نزدیک [۳۴۵] اور لوگوں کو دین سے بچلانا قتل سے بھی بڑھ کر ہے [۳۴۶] اور کفار تو ہمیشہ تم سے لڑتے ہی رہیں گے یہاں تک کہ تم کو پھیر دیں تمہارے دین سے اگر قابو پاویں [۳۴۷] اور جو کوئی پھرے تم میں سے اپنے دین سے پھر مر جاوے حالت کفر ہی میں تو ایسوں کے ضائع ہوئے عمل دنیا اور آخرت میں اور وہ لوگ رہنے والے ہیں دوزخ میں وہ اس میں ہمیشہ رہیں گے [۳۴۸]', 'They ask you concerning fighting in the Sacred Months (i.e. 1st, 7th, 11th and 12th months of the Islamic calendar). Say, \"Fighting therein is a great (transgression) but a greater (transgression) with Allah is to prevent mankind from following the Way of Allah, to disbelieve in Him, to prevent access to Al-Masjid-al-Haram (at Makkah), and to drive out its inhabitants, and Al-Fitnah is worse than killing. And they will never cease fighting you until they turn you back from your religion (Islamic Monotheism) if they can. And whosoever of you turns back from his religion and dies as a disbeliever, then his deeds will be lost in this life and in the Hereafter, and they will be the dwellers of the Fire. They will abide therein forever.\"', 'They ask you about the Sacred Month, that is, about fighting in it. Say, “Fighting in it is something grave, but it is much more grave, in the sight of Allah, to prevent (people) from the path of Allah, to disbelieve in Him, and in Al-Masjid-ul-Harām, and to expel its people from there, and Fitnah (to create disorder) is more grave than killing.” They will go on fighting you until they turn you away from your faith if they could, while whoever of you turns away from his faith and dies an infidel, such people are those whose deeds will go to waste in this world and in the Hereafter, and they are people of the Fire. They shall be there forever'),
(225, 2, 218, 27, 11, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اِنَّ الَّذِیۡنَ اٰمَنُوۡا وَ الَّذِیۡنَ  ہَاجَرُوۡا وَ جٰہَدُوۡا فِیۡ سَبِیۡلِ اللّٰہِ  ۙ اُولٰٓئِکَ یَرۡجُوۡنَ  رَحۡمَتَ اللّٰہِ ؕ وَ اللّٰہُ غَفُوۡرٌ رَّحِیۡمٌ ﴿۲۱۸﴾', 'اور جو لوگ ایمان لائے اور اللہ کے لئے وطن چھوڑ گئے اور کفار سے جنگ کرتے رہے وہی اللہ کی رحمت کے امیدوار ہیں اور اللہ بخشنے والا ہے رحمت کرنے والا ہے۔', 'بیشک جو لوگ ایمان لائے اور جنہوں نے ہجرت کی اور لڑے اللہ کی راہ میں وہ امیدوار ہیں اللہ کی رحمت کے اور اللہ بخشنے والا مہربان ہے [۳۴۹]', 'Verily, those who have believed, and those who have emigrated (for Allahs Religion) and have striven hard in the Way of Allah, all these hope for Allahs Mercy. And Allah is Oft-Forgiving, Most-Merciful.', 'As for those who believed and those who migrated and carried out Jihād in the way of Allah, they hope for Allah’s mercy: and Allah is Forgiving, Very-Merciful.'),
(226, 2, 219, 27, 11, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'یَسۡـَٔلُوۡنَکَ عَنِ الۡخَمۡرِ وَ الۡمَیۡسِرِؕ قُلۡ فِیۡہِمَاۤ اِثۡمٌ  کَبِیۡرٌ  وَّ مَنَافِعُ  لِلنَّاسِ ۫ وَ اِثۡمُہُمَاۤ  اَکۡبَرُ مِنۡ نَّفۡعِہِمَا ؕ وَ یَسۡـَٔلُوۡنَکَ مَا ذَا یُنۡفِقُوۡنَ ۬ؕ قُلِ الۡعَفۡوَؕ کَذٰلِکَ یُبَیِّنُ اللّٰہُ  لَکُمُ الۡاٰیٰتِ لَعَلَّکُمۡ تَتَفَکَّرُوۡنَ ﴿۲۱۹﴾ۙ', 'اے پیغمبر لوگ تم سے شراب اور جوئے کا حکم دریافت کرتے ہیں کہہ دو کہ ان میں گناہ بڑے ہیں اور لوگوں کے لئے کچھ فائدے بھی ہیں مگر ان کے گناہ فائدوں سے کہیں زیادہ ہیں۔ اور یہ بھی تم سے پوچھتے ہیں کہ اللہ کی راہ میں کونسا مال خرچ کریں کہہ دو کہ جو ضرورت سے زیادہ ہو۔ اس طرح اللہ تمہارے لئے اپنے احکام کھول کھول کر بیان فرماتا ہے تا کہ تم سوچو۔', 'تجھ سے پوچھتے ہیں حکم شراب کا اور جوئے کا [۳۵۰] کہدے ان دونوں میں بڑا گناہ ہے اور فائدے بھی ہیں لوگوں کو اور ان کا گناہ بہت بڑا ہے ان کے فائدے سے [۳۵۱] اور تجھ سے پوچھتے ہیں کہ کیا خرچ کریں کہدے جو بچے اپنے خرچ سے [۳۵۲] اسی طرح بیان کرتا ہے اللہ تمہارے واسطے حکم تا کہ تم فکر کرو', 'They ask you (O Muhammad SAW) concerning alcoholic drink and gambling. Say: \"In them is a great sin, and (some) benefit for men, but the sin of them is greater than their benefit.\" And they ask you what they ought to spend. Say: \"That which is beyond your needs.\" Thus Allah makes clear to you His Laws in order that you may give thought.\"', 'They ask you about wine and gambling. Say, “In both there is great sin, and some benefits for people. And their sin is greater than their benefit.” And they ask you as to what they should spend. Say, “The surplus”. This is how Allah makes His verses clear to you, so that you may ponder');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(227, 2, 220, 27, 11, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'فِی الدُّنۡیَا وَ الۡاٰخِرَۃِ ؕ وَ یَسۡـَٔلُوۡنَکَ عَنِ الۡیَتٰمٰی ؕ قُلۡ  اِصۡلَاحٌ لَّہُمۡ خَیۡرٌ ؕ وَ اِنۡ تُخَالِطُوۡہُمۡ  فَاِخۡوَانُکُمۡ ؕ وَ اللّٰہُ یَعۡلَمُ الۡمُفۡسِدَ مِنَ الۡمُصۡلِحِ ؕ وَ لَوۡ شَآءَ اللّٰہُ  لَاَعۡنَتَکُمۡ ؕ اِنَّ  اللّٰہَ عَزِیۡزٌ حَکِیۡمٌ ﴿۲۲۰﴾', 'یعنی دنیا اور آخرت کی باتوں میں غور کرو اور تم سے یتیموں کے بارے میں بھی دریافت کرتے ہیں کہہ دو کہ ان کی حالت کی اصلاح بہت اچھا کام ہے اور اگر تم ان سے مل جل کر رہنا یعنی خرچ اکٹھا رکھنا چاہو تو وہ تمہارے بھائی ہیں اور اللہ خوب جانتا ہے کہ خرابی کرنے والا کون ہے اور اصلاح کرنے والا کون اور اگر اللہ چاہتا تو تم کو تکلیف میں ڈال دیتا۔ بیشک اللہ غالب ہے حکمت والا ہے۔', 'دنیا و آخرت کی باتوں میں [۳۵۳] اور تجھ سے پوچھتے ہیں یتیموں کا حکم [۳۵۴] کہدے سنوارنا ان کے کام کا بہتر ہے اور اگر ان کا خرچ ملا لو تو وہ تمہارے بھائی ہیں اور اللہ جانتا ہے خرابی کرنے والے اور سنوارنے والے کو [۳۵۵] اور اگر اللہ چاہتا تو تم پر مشقت ڈالتا [۳۵۶] بیشک اللہ زبردست ہے تدبیر والا [۳۵۷]', 'In (to) this worldly life and in the Hereafter. And they ask you concerning orphans. Say: \"The best thing is to work honestly in their property, and if you mix your affairs with theirs, then they are your brothers. And Allah knows him who means mischief (e.g. to swallow their property) from him who means good (e.g. to save their property). And if Allah had wished, He could have put you into difficulties. Truly, Allah is All-Mighty, All-Wise.\"', 'on this world and the Hereafter. They ask you about the orphans. Say, “To work for their good is good. And if you live with them jointly, they are, after all, your brethren.”; and Allah knows the one who makes mischief, as distinct from the one who promotes good. And if Allah had wished, He would have put you in trouble. Surely, Allah is Mighty, Wise.'),
(228, 2, 221, 27, 11, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ لَا تَنۡکِحُوا الۡمُشۡرِکٰتِ حَتّٰی یُؤۡمِنَّ ؕ وَ لَاَمَۃٌ مُّؤۡمِنَۃٌ  خَیۡرٌ مِّنۡ مُّشۡرِکَۃٍ  وَّ لَوۡ اَعۡجَبَتۡکُمۡ ۚ وَ لَا تُنۡکِحُوا الۡمُشۡرِکِیۡنَ حَتّٰی یُؤۡمِنُوۡا ؕ وَ لَعَبۡدٌ مُّؤۡمِنٌ خَیۡرٌ مِّنۡ مُّشۡرِکٍ وَّ لَوۡ اَعۡجَبَکُمۡ ؕ اُولٰٓئِکَ یَدۡعُوۡنَ  اِلَی النَّارِ ۚۖ وَ اللّٰہُ  یَدۡعُوۡۤا اِلَی الۡجَنَّۃِ وَ الۡمَغۡفِرَۃِ  بِاِذۡنِہٖ ۚ وَ یُبَیِّنُ  اٰیٰتِہٖ لِلنَّاسِ لَعَلَّہُمۡ  یَتَذَکَّرُوۡنَ ﴿۲۲۱﴾٪', 'اور مومنو مشرک عورتوں سے جب تک وہ ایمان نہ لائیں نکاح نہ کرنا۔ کیونکہ مشرک عورت خواہ تم کو کیسی ہی بھلی لگے اس سے مومن لونڈی بہتر ہے۔ اور اسی طرح مشرک مرد جب تک ایمان نہ لائیں مومن عورتوں کو ان کی زوجیت میں نہ دینا۔ کیونکہ مشرک مرد سے خواہ وہ تم کو کیسا ہی بھلا لگے مومن غلام بہتر ہے۔ یہ مشرک لوگوں کو دوزخ کی طرف بلاتے ہیں۔ اور اللہ اپنی مہربانی سے بہشت اور بخشش کی طرف بلاتا ہے اور اپنے حکم لوگوں سے کھول کھول کر بیان کرتا ہے تاکہ نصیحت حاصل کریں۔', 'اور نکاح مت کرو مشرک عورتوں سے جب تک ایمان نہ لے آئیں اور البتہ لونڈی مسلمان بہتر ہے مشرک بی بی سے اگرچہ وہ تم کو بھلی لگے اور نکاح نہ کر دو مشرکین سے جب تک وہ ایمان نے لے آویں اور البتہ غلام مسلمان بہتر ہے مشرک سے اگرچہ وہ تم کو بھلا لگے [۳۵۸] وہ بلاتےہیں دوزخ کی طرف [۳۵۹] اور اللہ بلاتا ہے جنت کی اور بخشش کی طرف اپنے حکم سے اور بتلاتا ہے اپنے حکم لوگوں کو تاکہ وہ نصیحت قبول کریں', 'And do not marry Al-Mushrikat (idolatresses, etc.) till they believe (worship Allah Alone). And indeed a slave woman who believes is better than a (free) Mushrikah (idolatress, etc.), even though she pleases you. And give not (your daughters) in marriage to Al-Mushrikoon till they believe (in Allah Alone) and verily, a believing slave is better than a (free) Mushrik (idolater, etc.), even though he pleases you. Those (Al-Mushrikoon) invite you to the Fire, but Allah invites (you) to Paradise and Forgiveness by His Leave, and makes His Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) clear to mankind that they may remember.', 'Do not marry the polytheist women, unless they come to believe (in Islam); a Muslim slave-girl is better than a polytheist woman, even though she may attract you; and do not give (your women) in marriage to polytheist men, unless they come to believe; a Muslim slave is better than a polytheist, even though he may attract you. They invite to the Fire when Allah invites, by His will, to Paradise, and to forgiveness. He makes His verses clear to the people, so that they may heed the advice.'),
(229, 2, 222, 28, 12, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ یَسۡـَٔلُوۡنَکَ عَنِ الۡمَحِیۡضِ ؕ قُلۡ ہُوَ اَذًی  ۙ فَاعۡتَزِلُوا النِّسَآءَ فِی الۡمَحِیۡضِ  ۙ وَ لَا تَقۡرَبُوۡہُنَّ حَتّٰی یَطۡہُرۡنَ ۚ فَاِذَا تَطَہَّرۡنَ  فَاۡتُوۡہُنَّ مِنۡ حَیۡثُ اَمَرَکُمُ اللّٰہُ  ؕ اِنَّ اللّٰہَ یُحِبُّ التَّوَّابِیۡنَ  وَ یُحِبُّ الۡمُتَطَہِّرِیۡنَ ﴿۲۲۲﴾', 'اور تم سے حیض کے بارے میں دریافت کرتے ہیں کہہ دو وہ تو نجاست ہے سو ایّام حیض میں عورتوں سے کنارہ کش رہو۔ اور جب تک وہ پاک نہ ہو جائیں ان سے مقاربت نہ کرو۔ ہاں جب وہ پاک ہو جائیں تو جس طریق سے اللہ نے تمہیں ارشاد فرمایا ہے ان کے پاس جاؤ کچھ شک نہیں کہ اللہ توبہ کرنے والوں اور پاک صاف رہنے والوں کو دوست رکھتا ہے۔', 'اور تجھ سے پوچھتے ہیں حکم حیض کا کہدے وہ گندگی ہے سو تم الگ رہو عورتوں سے حیض کے وقت [۳۶۰] اور نزدیک نہ ہو ان کے جب تک پاک نہ ہوویں [۳۶۱] پھر جب خوب پاک ہو جاویں تو جاؤ ان کے پاس جہاں سے حکم دیا تم کو اللہ نے [۳۶۲] بیشک اللہ کو پسند آتے ہیں توبہ کرنے والے اور پسند آتے ہیں گندگی سے بچنے والے [۳۶۳]', 'They ask you concerning menstruation. Say: that is an Adha (a harmful thing for a husband to have a sexual intercourse with his wife while she is having her menses), therefore keep away from women during menses and go not unto them till they have purified (from menses and have taken a bath). And when they have purified themselves, then go in unto them as Allah has ordained for you (go in unto them in any manner as long as it is in their vagina). Truly, Allah loves those who turn unto Him in repentance and loves those who purify themselves (by taking a bath and cleaning and washing thoroughly their private parts, bodies, for their prayers, etc.).', 'They ask you about menstruation. Say: “It is an impurity. So, keep away from women during menstruation; and do not have intimacy with them until they are cleansed. But when they are cleansed, then go to them from where Allah has commanded you. Surely Allah loves those who are most repenting, and loves those who keep themselves pure.'),
(230, 2, 223, 28, 12, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'نِسَآؤُکُمۡ حَرۡثٌ لَّکُمۡ  ۪ فَاۡتُوۡا حَرۡثَکُمۡ اَنّٰی شِئۡتُمۡ ۫ وَ قَدِّمُوۡا لِاَنۡفُسِکُمۡ ؕ وَ اتَّقُوا اللّٰہَ وَ اعۡلَمُوۡۤا اَنَّکُمۡ  مُّلٰقُوۡہُ  ؕ وَ بَشِّرِ الۡمُؤۡمِنِیۡنَ ﴿۲۲۳﴾', 'تمہاری عورتیں تمہاری کھیتی ہیں تو اپنی کھیتی میں جس طرح چاہو جاؤ۔ اور اپنے لئے نیک عمل آگے بھیجو۔ اور اللہ سے ڈرتے رہو اور جان رکھو کہ ایک دن تمہیں اس کے روبرو حاضر ہونا ہے اور اے پیغمبر ایمان والوں کو بشارت سنا دو۔', 'تمہاری عورتیں تمہاری کھیتی ہیں سو جاؤ اپنی کھیتی میں جہاں سے چاہو [۳۶۴] اور آگے کی تدبیر کرو اپنے واسطے [۳۶۵] اور ڈرتے رہو اللہ سے اور جان رکھو کہ تم کو اس سے ملنا ہے اور خوشخبری سنا ایمان والوں کو', 'Your wives are a tilth for you, so go to your tilth (have sexual relations with your wives in any manner as long as it is in the vagina and not in the anus), when or how you will, and send (good deeds, or ask Allah to bestow upon you pious offspring) before you for your ownselves. And fear Allah, and know that you are to meet Him (in the Hereafter), and give good tidings to the believers (O Muhammad SAW).', 'Your women are tillage for you to cultivate. So, come to your tillage from where you wish, and advance something for yourselves, and fear Allah, and know that you are to meet Him, and give good news to the believers.”'),
(231, 2, 224, 28, 12, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ لَا تَجۡعَلُوا اللّٰہَ عُرۡضَۃً  لِّاَیۡمَانِکُمۡ اَنۡ تَبَرُّوۡا وَ تَتَّقُوۡا وَ تُصۡلِحُوۡا بَیۡنَ النَّاسِ ؕ وَ اللّٰہُ  سَمِیۡعٌ  عَلِیۡمٌ ﴿۲۲۴﴾', 'اور اللہ کے نام کو اس بات کا حیلہ نہ بنانا کہ اس کی قسمیں کھا کھا کر سلوک کرنے اور پرہیزگاری کرنے اور لوگوں میں صلح و سازگاری کرانے سے رک جاؤ۔ اور اللہ سب کچھ سنتا ہے جانتا ہے۔', 'اور مت بناؤ اللہ کے نام کو نشانہ اپنی قسمیں کھانے کے لئے کہ سلوک کرنے سے اور پرہیزگاری سے اور لوگوں میں صلح کرانے سے بچ جاؤ [۳۶۶] اور اللہ سب کچھ سنتا جانتا ہے [۳۶۷]', 'And make not Allahs (Name) an excuse in your oaths against your doing good and acting piously, and making peace among mankind. And Allah is All-Hearer, All-Knower (i.e. do not swear much and if you have sworn against doing something good then give an expiation for the oath and do good).', 'Do not make (the name of) Allah the subject of your oaths against your doing good, fearing Allah and setting things right between people. Allah is All-Hearing, All-Knowing.'),
(232, 2, 225, 28, 12, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'لَا  یُؤَاخِذُکُمُ  اللّٰہُ بِاللَّغۡوِ فِیۡۤ  اَیۡمَانِکُمۡ وَ لٰکِنۡ یُّؤَاخِذُکُمۡ  بِمَا کَسَبَتۡ قُلُوۡبُکُمۡ ؕ وَ اللّٰہُ غَفُوۡرٌ  حَلِیۡمٌ ﴿۲۲۵﴾', 'اللہ تمہاری لغو قسموں پر تم سے مواخذہ نہیں کرے گا۔ لیکن جو قسمیں تم قصد دلی سے کھاؤ گے ان پر مواخذہ کرے گا اور اللہ بخشنے والا ہے بردبار ہے۔', 'نہیں پکڑتا تم کو اللہ بیہودہ قسموں پر تمہاری [۳۶۸] لیکن پکڑتا ہے تم کو ان قسموں پر کہ جن کا قصد کیا تمہارے دلوں نے [۳۶۹] اور اللہ بخشنے والا تحمل کرنے والا ہے [۳۷۰]', 'Allah will not call you to account for that which is unintentional in your oaths, but He will call you to account for that which your hearts have earned. And Allah is Oft-Forgiving, Most-Forbearing.', 'Allah does not hold you accountable for what is laghw (ineffectual) in your oaths, but He holds you accountable for what your hearts have produced. Allah is Forgiving, Forbearing.'),
(233, 2, 226, 28, 12, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'لِلَّذِیۡنَ یُؤۡلُوۡنَ مِنۡ نِّسَآئِہِمۡ تَرَبُّصُ اَرۡبَعَۃِ اَشۡہُرٍ ۚ فَاِنۡ فَآءُوۡ فَاِنَّ اللّٰہَ غَفُوۡرٌ  رَّحِیۡمٌ ﴿۲۲۶﴾', 'جو لوگ اپنی عورتوں کے پاس جانے کی قسم کھا لیں ان کو چار مہینے تک انتظار کرنا چاہیے اگر اس عرصے میں قسم سے رجوع کر لیں تو اللہ بخشنے والا ہے مہربان ہے۔', 'جو لوگ قسم کھا لیتے ہیں اپنی عورتوں کے پاس جانے سے انکے لئے مہلت ہے چار مہینے کی پھر اگر باہم مل گئے تو اللہ بخشنے والا مہربان ہے', 'Those who take an oath not to have sexual relation with their wives must wait four months, then if they return (change their idea in this period), verily, Allah is Oft-Forgiving, Most Merciful.', 'Those who swear to abstain from their wives have four months of waiting. Therefore, if they revert back, Allah is Most-Forgiving, Very-Merciful,'),
(234, 2, 227, 28, 12, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ اِنۡ عَزَمُوا الطَّلَاقَ فَاِنَّ اللّٰہَ سَمِیۡعٌ عَلِیۡمٌ ﴿۲۲۷﴾', 'اور اگر طلاق کا ارادہ کر لیں تو بھی اللہ سنتا ہے جانتا ہے۔', 'اور اگر ٹھہرا لیا چھوڑ دینے کو تو بیشک اللہ سننے والا جاننے والا ہے [۳۷۱]', 'And if they decide upon divorce, then Allah is All-Hearer, All-Knower', 'and if they resolve to divorce, Allah is All-Hearing, All-Knowing.'),
(235, 2, 228, 28, 12, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ الۡمُطَلَّقٰتُ یَتَرَبَّصۡنَ بِاَنۡفُسِہِنَّ ثَلٰثَۃَ قُرُوۡٓءٍ ؕ وَ لَا یَحِلُّ لَہُنَّ اَنۡ یَّکۡتُمۡنَ مَا خَلَقَ اللّٰہُ فِیۡۤ  اَرۡحَامِہِنَّ  اِنۡ  کُنَّ یُؤۡمِنَّ بِاللّٰہِ وَ الۡیَوۡمِ  الۡاٰخِرِ ؕ وَ بُعُوۡلَتُہُنَّ اَحَقُّ بِرَدِّہِنَّ فِیۡ ذٰلِکَ اِنۡ اَرَادُوۡۤا اِصۡلَاحًا ؕ وَ لَہُنَّ مِثۡلُ الَّذِیۡ عَلَیۡہِنَّ بِالۡمَعۡرُوۡفِ  ۪ وَ لِلرِّجَالِ عَلَیۡہِنَّ دَرَجَۃٌ ؕ وَ اللّٰہُ عَزِیۡزٌ حَکِیۡمٌ ﴿۲۲۸﴾٪', 'اور طلاق والی عورتیں تین حیض تک اپنے تئیں روکے رہیں اور اگر وہ اللہ اور روز قیامت پر ایمان رکھتی ہیں تو ان کو جائز نہیں کہ اللہ نے جو کچھ ان کے شکم میں پیدا کیا ہے اس کو چھپائیں اور ان کے خاوند اگر پھر موافقت چاہیں تو اس مدّت میں وہ ان کو اپنی زوجیت میں لے لینے کے زیادہ حقدار ہیں اور عورتوں کا حق مردوں پر ویسا ہی ہے جیسے دستور کے مطابق مردوں کا حق عورتوں پر ہے البتہ مردوں کو عورتوں پر ایک درجہ فضیلت ہے اور اللہ غالب ہے صاحب حکمت ہے۔', 'اور طلاق والی عورتیں انتظار میں رکھیں اپنے آپ کو تین حیض تک اور ان کو حلال نہیں کہ چھپا رکھیں جو پیدا کیا اللہ نے ان کے پیٹ میں اگر وہ ایمان رکھتی ہیں اللہ پر اور پچھلے دن پر [۳۷۲] اور ان کے خاوند حق رکھتے ہیں انکے لوٹا لینے کا اس مدت میں اگر چاہیں سلوک سے رہنا [۳۷۳] اور عورتوں کا بھی حق ہے جیسا کہ مردوں کا ان پر حق ہے دستور کے موافق اور مردوں کو عورتوں پر فضیلت ہے [۳۷۴] اور اللہ زبردست ہے تدبیر والا', 'And divorced women shall wait (as regards their marriage) for three menstrual periods, and it is not lawful for them to conceal what Allah has created in their wombs, if they believe in Allah and the Last Day. And their husbands have the better right to take them back in that period, if they wish for reconciliation. And they (women) have rights (over their husbands as regards living expenses, etc.) similar (to those of their husbands) over them (as regards obedience and respect, etc.) to what is reasonable, but men have a degree (of responsibility) over them. And Allah is All-Mighty, All-Wise.', 'Divorced women shall keep themselves waiting for three periods, and it is not permissible for them to conceal what Allah has created in their wombs, if they believe in Allah and in the Last Day. Their husbands are best entitled to take them back in the meantime, if they want a settlement. Women have rights similar to what they owe in recognized manner though for men there is a step above them. Allah is Mighty, Wise.'),
(236, 2, 229, 29, 13, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اَلطَّلَاقُ مَرَّتٰنِ۪ فَاِمۡسَاکٌۢ بِمَعۡرُوۡفٍ اَوۡ تَسۡرِیۡحٌۢ بِاِحۡسَانٍ ؕ وَ لَا  یَحِلُّ  لَکُمۡ اَنۡ تَاۡخُذُوۡا مِمَّاۤ  اٰتَیۡتُمُوۡہُنَّ شَیۡئًا اِلَّاۤ اَنۡ یَّخَافَاۤ  اَلَّا یُقِیۡمَا حُدُوۡدَ اللّٰہِ ؕ فَاِنۡ خِفۡتُمۡ  اَلَّا یُقِیۡمَا حُدُوۡدَ اللّٰہِ  ۙ فَلَا جُنَاحَ عَلَیۡہِمَا فِیۡمَا افۡتَدَتۡ بِہٖ ؕ تِلۡکَ حُدُوۡدُ اللّٰہِ فَلَا تَعۡتَدُوۡہَا ۚ وَ مَنۡ یَّتَعَدَّ حُدُوۡدَ اللّٰہِ فَاُولٰٓئِکَ ہُمُ الظّٰلِمُوۡنَ ﴿۲۲۹﴾', 'طلاق صرف دو بار ہے یعنی جب دو دفعہ طلاق دے دی جائے تو پھر عورتوں کو یا تو بطریق شائستہ نکاح میں رہنے دینا ہے یا بھلائی کے ساتھ چھوڑ دینا۔ اور یہ جائز نہیں کہ جو مہر تم ان کو دے چکے ہو اس میں سے کچھ واپس لے لو۔ ہاں اگر زن و شوہر کو خوف ہو کہ وہ اللہ کی حدوں کو قائم نہیں رکھ سکیں گے تو اگر عورت خاوند کے ہاتھ سے رہائی پانے کے بدلے میں کچھ دے ڈالے تو دونوں پر کچھ گناہ نہیں یہ اللہ کی مقرر کی ہوئی حدیں ہیں ان سے باہر نہ نکلنا۔ اور جو لوگ اللہ کی حدوں سے باہر نکل جائیں گے وہ گنہگار ہوں گے۔', 'طلاق رجعی ہے دو بار تک اسکے بعد رکھ لینا موافق دستور کے یا چھوڑ دینا بھلی طرح سے [۳۷۵] اور تم کو روا نہیں کہ لے لو کچھ اپنا دیا ہوا عورتوں سے مگر جبکہ خاوند عورت دونوں ڈریں اس بات سے کہ قائم نہ رکھ سکیں گے حکم اللہ کا [۳۷۶] پھر اگر تم لوگ ڈرو اس بات سے کہ وہ دونوں قائم نہ رکھ سکیں گے اللہ کا حکم تو کچھ گناہ نہیں دونوں پر اس میں کہ عورت بدلہ دیکر چھوٹ جاوے [۳۷۷] یہ اللہ کی باندھی ہوئی حدیں ہیں سو ان سے آگے مت بڑھو اور جو کوئی بڑھ چلے اللہ کی باندھی ہوئی حدوں سےسو وہی لوگ ہیں ظالم [۳۷۸]', 'The divorce is twice, after that, either you retain her on reasonable terms or release her with kindness. And it is not lawful for you (men) to take back (from your wives) any of your Mahr (bridal money given by the husband to his wife at the time of marriage) which you have given them, except when both parties fear that they would be unable to keep the limits ordained by Allah (e.g. to deal with each other on a fair basis). Then if you fear that they would not be able to keep the limits ordained by Allah, then there is no sin on either of them if she gives back (the Mahr or a part of it) for her Al-Khul (divorce). These are the limits ordained by Allah, so do not transgress them. And whoever transgresses the limits ordained by Allah, then such are the Zalimoon (wrong-doers, etc.).', 'Divorce is twice; then either to retain in all fairness, or to release nicely. It is not lawful for you to take back anything from what you have given them, unless both apprehend that they would not be able to maintain the limits set by Allah. Now, if you apprehend that they would not maintain the limits set by Allah, then, there is no sin on them in what she gives up to secure her release. These are the limits set by Allah. Therefore, do not exceed them. Whosoever exceeds the limits set by Allah, then, those are the transgressors.'),
(237, 2, 230, 29, 13, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'فَاِنۡ طَلَّقَہَا فَلَا تَحِلُّ لَہٗ مِنۡۢ بَعۡدُ حَتّٰی تَنۡکِحَ زَوۡجًا غَیۡرَہٗ ؕ فَاِنۡ طَلَّقَہَا فَلَا جُنَاحَ عَلَیۡہِمَاۤ  اَنۡ یَّتَرَاجَعَاۤ  اِنۡ ظَنَّاۤ  اَنۡ یُّقِیۡمَا حُدُوۡدَ اللّٰہِ ؕ وَ تِلۡکَ حُدُوۡدُ اللّٰہِ یُبَیِّنُہَا لِقَوۡمٍ  یَّعۡلَمُوۡنَ ﴿۲۳۰﴾', 'پھر اگر شوہر دو طلاقوں کے بعد تیسری طلاق عورت کو دے دے تو اس کے بعد جب تک عورت کسی دوسرے شخص سے نکاح نہ کر لے اس پہلے شوہر  پر حلال نہ ہو گی۔ ہاں اگر دوسرا خاوند بھی طلاق دے دے اور عورت اور پہلا خاوند پھر ایک دوسرے کی طرف رجوع کر لیں تو ان پر کچھ گناہ نہیں بشرطیکہ دونوں یقین کریں کہ اللہ کی حدوں کو قائم رکھ سکیں گے اور یہ اللہ کی حدیں ہیں ان کو وہ ان لوگوں کے لئے بیان فرماتا ہے جو علم رکھتے ہیں۔', 'پھر اگر اس عورت کو طلاق دی یعنی تیسری بار تو اب حلال نہیں اس کو وہ عورت اس کے بعد جب تک نکاح نہ کرے کسی خاوند سے اسکے سوا پھر اگر طلاق دیدے دوسرا خاوند تو کچھ گناہ نہیں ان دونوں پر کہ پھر باہم مل جاویں اگر خیال کریں کہ قائم رکھیں گے اللہ کا حکم اور یہ حدیں باندھی ہوئی ہیں اللہ کی بیان فرماتا ہے ان کو واسطے جاننے والوں کے [۳۷۹]', 'And if he has divorced her (the third time), then she is not lawful unto him thereafter until she has married another husband. Then, if the other husband divorces her, it is no sin on both of them that they reunite, provided they feel that they can keep the limits ordained by Allah. These are the limits of Allah, which He makes plain for the people who have knowledge.', 'Thereafter, if he divorces her, she shall no longer remain lawful for him unless she marries a man other than him. Should he too divorce her, then there is no sin on them in their returning to each other, if they think they would maintain the limits set by Allah. These are the limits set by Allah that He makes clear to a people who know (that Allah is alone capable of setting these limits).'),
(238, 2, 231, 29, 13, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ اِذَا طَلَّقۡتُمُ النِّسَآءَ فَبَلَغۡنَ اَجَلَہُنَّ فَاَمۡسِکُوۡہُنَّ بِمَعۡرُوۡفٍ اَوۡ سَرِّحُوۡہُنَّ بِمَعۡرُوۡفٍ  ۪ وَ لَا تُمۡسِکُوۡہُنَّ ضِرَارًا لِّتَعۡتَدُوۡا ۚ وَ مَنۡ یَّفۡعَلۡ ذٰلِکَ فَقَدۡ  ظَلَمَ نَفۡسَہٗ ؕ وَ لَا تَتَّخِذُوۡۤا اٰیٰتِ اللّٰہِ ہُزُوًا ۫ وَّ اذۡکُرُوۡا نِعۡمَتَ اللّٰہِ عَلَیۡکُمۡ وَ مَاۤ  اَنۡزَلَ عَلَیۡکُمۡ مِّنَ الۡکِتٰبِ وَ الۡحِکۡمَۃِ یَعِظُکُمۡ  بِہٖ ؕ وَ اتَّقُوا اللّٰہَ وَ اعۡلَمُوۡۤا  اَنَّ اللّٰہَ بِکُلِّ شَیۡءٍ عَلِیۡمٌ ﴿۲۳۱﴾٪', 'اور جب تم عورتوں کو دو دفعہ طلاق دے چکو اور ان کی عدّت پوری ہو جائے تو انہیں یا تو حسن سلوک سے نکاح میں رہنے دو یا بطریق شائستہ رخصت کر دو اور اس نیت سے ان کو نکاح میں نہ رہنے دینا چاہیے کہ انہیں تکلیف دو اور ان پر زیادتی کرو۔ اور جو ایسا کرے گا وہ اپنا ہی نقصان کرے گا اور اللہ کے احکام کو ہنسی اور کھیل نہ بناؤ اور اللہ نے تم کو جو نعمتیں بخشی ہیں اور تم پر جو کتاب اور دانائی کی باتیں نازل کی ہیں جن سے وہ تمہیں نصیحت فرماتا ہے ان کو یاد کرو۔ اور اللہ سے ڈرتے رہو اور جان رکھو کہ اللہ ہر چیز سے واقف ہے۔', 'اور جب طلاق دی تم نے عورتوں کو پھر پہنچیں اپنی عدت تک [۳۸۰] تو رکھ لو ان کو موافق دستور کے یا چھوڑ دو ان کو بھلی طرف سے اور نہ روکے رکھو ان کو ستانے کے لئے تاکہ ان پر زیادتی کرو [۳۸۱] اور جو ایسا کرے گا وہ بیشک اپنا ہی نقصان کرے گا اور مت ٹھہراؤ اللہ کے احکام کو ہنسی اور یاد کرو اللہ کا احسان جو تم پر ہے اور اس کو کہ جو اتاری تم پر کتاب اور علم کی باتیں کہ تم کو نصیحت کرتا ہے اسکے ساتھ اور ڈرتے رہو اللہ سے اور جان رکھو کہ اللہ سب کچھ جانتا ہے [۳۸۲]', 'And when you have divorced women and they have fulfilled the term of their prescribed period, either take them back on reasonable basis or set them free on reasonable basis. But do not take them back to hurt them, and whoever does that, then he has wronged himself. And treat not the Verses (Laws) of Allah as a jest, but remember Allahs Favours on you (i.e. Islam), and that which He has sent down to you of the Book (i.e. the Quran) and Al-Hikmah (the Prophets Sunnah - legal ways - Islamic jurisprudence, etc.) whereby He instructs you. And fear Allah, and know that Allah is All-Aware of everything.', 'When you have divorced women, and they have approached (the end of) their waiting periods, then, either retain them with fairness or release them with fairness. Do not retain them with wrongful intent, resulting in cruelty on your part, and whoever does this, actually wrongs himself. Do not take the verses of Allah in jest, and remember the grace of Allah on you and what He has revealed to you of the Book and the wisdom, giving you good counsel thereby, and fear Allah, and be sure that Allah is the One who knows everything.'),
(239, 2, 232, 30, 14, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ اِذَا طَلَّقۡتُمُ النِّسَآءَ فَبَلَغۡنَ اَجَلَہُنَّ فَلَا تَعۡضُلُوۡہُنَّ اَنۡ یَّنۡکِحۡنَ اَزۡوَاجَہُنَّ  اِذَا تَرَاضَوۡا بَیۡنَہُمۡ بِالۡمَعۡرُوۡفِ ؕ ذٰلِکَ یُوۡعَظُ بِہٖ مَنۡ کَانَ مِنۡکُمۡ  یُؤۡمِنُ بِاللّٰہِ وَ الۡیَوۡمِ  الۡاٰخِرِ ؕ ذٰلِکُمۡ اَزۡکٰی لَکُمۡ وَ اَطۡہَرُ ؕ وَ اللّٰہُ یَعۡلَمُ  وَ اَنۡتُمۡ  لَا  تَعۡلَمُوۡنَ ﴿۲۳۲﴾', 'اور جب تم عورتوں کو طلاق دے چکو اور ان کی عدّت پوری ہو جائے تو ان کو اپنے شوہروں کے ساتھ جب وہ آپس میں جائز طور پر راضی ہو جائیں نکاح کرنے سے مت روکو۔ اس حکم سے اس شخص کو نصیحت کی جاتی ہے جو تم میں اللہ اور روز آخر پر یقین رکھتا ہے۔ یہ تمہارے لیے نہایت خوب اور بہت پاکیزگی کی بات ہے۔ اور اللہ جانتا ہے اور تم نہیں جانتے۔', 'اور جب طلاق دی تم نے عورتوں کو پھر پورا کر چکیں اپنی عدت کو تو آپ نہ روکو ان کو اس سے کہ نکاح کر لیں اپنے انہی خاوندوں سے جبکہ راضی ہو جاویں آپس میں موافق دستور کے [۳۸۳] یہ نصیحت اس کو کی جاتی ہے جو کہ تم میں سے ایمان رکھتا ہے اللہ پر اور قیامت کے دن پر [۳۸۴] اس میں تمہارے واسطے بڑی ستھرائی ہے اور بہت پاکیزگی اور اللہ جانتا ہے اور تم نہیں جانتے [۳۸۵]', 'And when you have divorced women and they have fulfilled the term of their prescribed period, do not prevent them from marrying their (former) husbands, if they mutually agree on reasonable basis. This (instruction) is an admonition for him among you who believes in Allah and the Last Day. That is more virtuous and purer for you. Allah knows and you know not.', 'When you have divorced women, and they have reached (the end of) their waiting period, do not prevent them from marrying their husbands when they mutually agree with fairness. Thus the advice is given to everyone of you who believes in Allah and in the Hereafter. This is more pure and clean for you. Allah knows and you do not know.'),
(240, 2, 233, 30, 14, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ الۡوَالِدٰتُ یُرۡضِعۡنَ اَوۡلَادَہُنَّ حَوۡلَیۡنِ کَامِلَیۡنِ لِمَنۡ اَرَادَ  اَنۡ یُّتِمَّ الرَّضَاعَۃَ ؕ وَ عَلَی الۡمَوۡلُوۡدِ لَہٗ رِزۡقُہُنَّ وَ کِسۡوَتُہُنَّ بِالۡمَعۡرُوۡفِ ؕ لَا تُکَلَّفُ نَفۡسٌ اِلَّا وُسۡعَہَا ۚ لَا تُضَآرَّ وَالِدَۃٌۢ بِوَلَدِہَا وَ لَا مَوۡلُوۡدٌ لَّہٗ بِوَلَدِہٖ ٭ وَ عَلَی الۡوَارِثِ مِثۡلُ ذٰلِکَ ۚ فَاِنۡ اَرَادَا فِصَالًا عَنۡ تَرَاضٍ مِّنۡہُمَا وَ تَشَاوُرٍ فَلَا جُنَاحَ عَلَیۡہِمَا ؕ وَ اِنۡ اَرَدۡتُّمۡ اَنۡ تَسۡتَرۡضِعُوۡۤا اَوۡلَادَکُمۡ فَلَا جُنَاحَ عَلَیۡکُمۡ  اِذَا سَلَّمۡتُمۡ مَّاۤ  اٰتَیۡتُمۡ  بِالۡمَعۡرُوۡفِ ؕ وَ اتَّقُوا اللّٰہَ وَ اعۡلَمُوۡۤا اَنَّ اللّٰہَ بِمَا تَعۡمَلُوۡنَ بَصِیۡرٌ ﴿۲۳۳﴾', 'اور مائیں اپنے بچوں کو پورے دو سال  دودھ پلائیں یہ حکم اس شخص کے لئے ہے جو پوری مدّت تک دودھ پلوانا چاہے اور دودھ پلانے والی ماؤں کا کھانا اور کپڑا دستور کے مطابق باپ کے ذمّے ہو گا۔ کسی شخص کو اس کی طاقت سے زیادہ تکلیف نہیں دی جاتی تو یاد رکھو کہ نہ تو ماں کو اس کے بچے کے سبب نقصان پہنچایا جائے اور نہ باپ کو اس کی اولاد کی وجہ سے نقصان پہنچایا جائے۔ اور اسی طرح نان نفقہ بچے کے وارث کے ذمّے ہے۔ اور اگر دونوں یعنی ماں باپ آپس کی رضامندی اور صلاح سے بچے کا دودھ چھڑانا چاہیں تو ان پر کچھ گناہ نہیں۔ اور اگر تم اپنی اولاد کو دودھ پلوانا چاہو تو تم پر کچھ گناہ نہیں بشرطیکہ تم دودھ پلانے والیوں کو دستور کے مطابق ان کا حق جو تم نے دینا کیا تھا دے دو۔ اور اللہ سے ڈرتے رہو اور جان رکھو کہ جو کچھ تم کرتے ہو اللہ اس کو دیکھ رہا ہے۔', 'اور بچے والی عورتیں دودھ پلاویں اپنے بچوں کو دو برس پوری جو کوئی چاہے کہ پوری کرے دودھ کی مدت [۳۸۶] اور لڑکے والے یعنی باپ پر ہے کھانا اور کپڑا ان عورتوں کا موافق دستور کے تکلیف نہیں دی جاتی کسی کو مگر اس کی گنجائش کے موافق نہ نقصان دیا جاوے ماں کو اس کے بچہ کی وجہ سے اور نہ اس کو کہ جس کا وہ بچہ ہے یعنی باپ کو اسکے بچہ کی وجہ سے [۳۸۷] اور وارثوں پر بھی یہ لازم ہے [۳۸۸] پھر اگر ماں باپ چاہیں کہ دودھ چھڑا لیں یعنی دو برس کے اندر ہی اپنی رضا اور مشورہ سے تو ان پر کچھ گناہ نہیں [۳۸۹] اور اگر تم لوگ چاہو کہ دودھ پلواؤ کسی دایہ سے اپنی اولاد کو تو بھی تم پر کچھ گناہ نہیں جبکہ حوالہ کر دو جو تم نے دینا ٹھہرایا تھا موافق دستور کے [۳۹۰] اور ڈرو اللہ سے اور جان رکھو کہ اللہ تمہارے سب کاموں کو خوب دیکھتا ہے', 'The mothers shall give suck to their children for two whole years, (that is) for those (parents) who desire to complete the term of suckling, but the father of the child shall bear the cost of the mothers food and clothing on a reasonable basis. No person shall have a burden laid on him greater than he can bear. No mother shall be treated unfairly on account of her child, nor father on account of his child. And on the (fathers) heir is incumbent the like of that (which was incumbent on the father). If they both decide on weaning, by mutual consent, and after due consultation, there is no sin on them. And if you decide on a foster suckling-mother for your children, there is no sin on you, provided you pay (the mother) what you agreed (to give her) on reasonable basis. And fear Allah and know that Allah is All-Seer of what you do.', 'Mothers (should) suckle their children for two full years, for one who wants to complete the (period of) suckling. It is the obligation of the one to whom the child belongs that he provides food and clothing for them (the mothers) with fairness. Nobody is obligated beyond his capacity. No mother shall be made to suffer on account of her child, nor the man to whom the child belongs, on account of his child. Likewise responsibility (of suckling) lies on the (one who may become an) heir (of the child). Now, if they want to wean, with mutual consent and consultation, there is no sin on them. And If you want to get your children suckled (by a wet-nurse), there is no sin on you when you pay off what you are to give with fairness, and fear Allah, and be assured that Allah is watchful of what you do.'),
(241, 2, 234, 30, 14, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ الَّذِیۡنَ یُتَوَفَّوۡنَ مِنۡکُمۡ وَ یَذَرُوۡنَ اَزۡوَاجًا یَّتَرَبَّصۡنَ بِاَنۡفُسِہِنَّ اَرۡبَعَۃَ اَشۡہُرٍ وَّ عَشۡرًا ۚ فَاِذَا بَلَغۡنَ اَجَلَہُنَّ فَلَا جُنَاحَ عَلَیۡکُمۡ فِیۡمَا فَعَلۡنَ فِیۡۤ  اَنۡفُسِہِنَّ بِالۡمَعۡرُوۡفِ ؕ وَ اللّٰہُ بِمَا تَعۡمَلُوۡنَ  خَبِیۡرٌ ﴿۲۳۴﴾', 'اور جو لوگ تم میں سے مر جائیں اور عورتیں چھوڑ جائیں تو عورتیں چار مہینے اور دس دن اپنے آپ کو روکے رہیں اور جب یہ عدّت پوری کر چکیں اور اپنے حق میں پسندیدہ کام یعنی نکاح کر لیں تو تم پر کچھ گناہ نہیں۔ اور اللہ تمہارے سب کاموں سے واقف ہے۔', 'اور جو لوگ مر جاویں تم میں سے اور چھوڑ جاویں اپنی عورتیں تو چاہئے کہ وہ عورتیں انتظار میں رکھیں اپنے آپ کو چار مہینے اور دس دن [۳۹۱] پھر جب پورا کر چکیں اپنی عدت کو تو تم پر کچھ گناہ نہیں اس بات میں کہ کریں وہ اپنے حق میں قاعدہ کے موافق [۳۹۲] اور اللہ کو تمہارے تمام کاموں کی خبر ہے', 'And those of you who die and leave wives behind them, they (the wives) shall wait (as regards their marriage) for four months and ten days, then when they have fulfilled their term, there is no sin on you if they (the wives) dispose of themselves in a just and honourable manner (i.e. they can marry). And Allah is Well-Acquainted with what you do.', 'Those among you who pass away and leave wives behind, their wives keep themselves waiting for four months and ten days. So, when they have reached (the end of) their waiting period, there is no sin on you in what they do for themselves in recognized manner. Allah is All-Aware of what you do.'),
(242, 2, 235, 30, 14, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ لَا جُنَاحَ عَلَیۡکُمۡ فِیۡمَا عَرَّضۡتُمۡ بِہٖ مِنۡ خِطۡبَۃِ النِّسَآءِ اَوۡ اَکۡنَنۡتُمۡ فِیۡۤ  اَنۡفُسِکُمۡ ؕ عَلِمَ اللّٰہُ  اَنَّکُمۡ سَتَذۡکُرُوۡنَہُنَّ وَ لٰکِنۡ لَّا تُوَاعِدُوۡہُنَّ سِرًّا اِلَّاۤ اَنۡ تَقُوۡلُوۡا قَوۡلًا مَّعۡرُوۡفًا  ۬ؕ وَ لَا تَعۡزِمُوۡا عُقۡدَۃَ النِّکَاحِ حَتّٰی یَبۡلُغَ الۡکِتٰبُ اَجَلَہٗ ؕ وَ اعۡلَمُوۡۤا اَنَّ اللّٰہَ یَعۡلَمُ مَا فِیۡۤ اَنۡفُسِکُمۡ فَاحۡذَرُوۡہُ ۚ وَ اعۡلَمُوۡۤا اَنَّ اللّٰہَ غَفُوۡرٌ حَلِیۡمٌ ﴿۲۳۵﴾٪', 'اگر تم اشارے کنائے کی باتوں میں عورتوں کو نکاح کا پیغام بھیجو یا نکاح کی خواہش کو اپنے دلوں میں مخفی رکھو تو تم پر کچھ گناہ نہیں۔ اللہ کو معلوم ہے کہ تم ان سے نکاح کا ذکر کرو گے۔ مگر ایّام عدّت میں اس کے سوا کہ دستور کے مطابق کوئی بات کہہ دو پوشیدہ طور پر ان سے قول و قرار نہ کرنا اور جب تک عدّت پوری نہ ہو لے نکاح کا پختہ ارادہ نہ کرنا اور جان رکھو کہ جو کچھ تمہارے دلوں میں ہے اللہ کو سب معلوم ہے تو اس سے ڈرتے رہو اور جان رکھو کہ اللہ بخشنے والا ہے حلم والا ہے۔', 'اور کچھ گناہ نہیں تم پر اس میں کہ اشارہ میں کہو پیغام نکاح ان عورتوں کا یا پوشیدہ رکھو اپنے دل میں اللہ کو معلوم ہے کہ تم البتہ ان عورتوں کا ذکر کرو گے لیکن ان سے نکاح کا وعدہ نہ کر رکھو چھپ کر مگر  یہی کہ کہدو کوئی بات رواج شریعت کے موافق اور نہ ارادہ کرو نکاح کا یہاں تک کہ پہنچ جاوے عدت مقررہ اپنی انتہا کو [۳۹۳] اور جان رکھو کہ اللہ کو معلوم ہے جو کچھ تمہارے دل میں ہے سو اس سے ڈرتے رہو اور جان رکھو کہ اللہ بخشنے والا اور تحمل کرنے والا ہے[۳۹۴]', 'And there is no sin on you if you make a hint of betrothal or conceal it in yourself, Allah knows that you will remember them, but do not make a promise of contract with them in secret except that you speak an honourable saying according to the Islamic law (e.g. you can say to her, \"If one finds a wife like you, he will be happy\"). And do not consummate the marriage until the term prescribed is fulfilled. And know that Allah knows what is in your minds, so fear Him. And know that Allah is Oft-Forgiving, Most Forbearing.', 'There is no sin on you if you hint as a proposal to the women, or conceal it in your hearts. Allah knows that you will make mention of them. But do not make a promise to them secretly, except that you speak in a recognized manner. Nor resolve upon a contract of marriage until the prescribed time is reached. Be assured that Allah knows what is in your hearts. So, fear Him and be assured that Allah is most Forgiving, Forbearing.'),
(243, 2, 236, 31, 15, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'لَا جُنَاحَ عَلَیۡکُمۡ  اِنۡ طَلَّقۡتُمُ النِّسَآءَ مَا لَمۡ تَمَسُّوۡہُنَّ اَوۡ تَفۡرِضُوۡا لَہُنَّ فَرِیۡضَۃً ۚۖ وَّ مَتِّعُوۡہُنَّ ۚ عَلَی الۡمُوۡسِعِ قَدَرُہٗ  وَ عَلَی الۡمُقۡتِرِ قَدَرُہٗ ۚ مَتَاعًۢا بِالۡمَعۡرُوۡفِ ۚ حَقًّا عَلَی الۡمُحۡسِنِیۡنَ ﴿۲۳۶﴾', 'اور اگر تم عورتوں کو ان کے پاس جانے یا ان کا مہر مقرر کرنے سے پہلے طلاق دے دو تو تم پر کچھ گناہ نہیں۔ ہاں ان کو دستور کے مطابق کچھ خرچ ضرور دو یعنی مقدور والا اپنے مقدور کے مطابق دے اور تنگدست اپنی حیثیت کے مطابق نیک لوگوں پر یہ ایک طرح کا حق ہے۔', 'کچھ گناہ نہیں تم پر اگر طلاق دو تم عورتوں کو اس وقت کہ ان کو ہاتھ بھی نہ لگایا ہو اور نہ مقرر کیا ہو ان کے لئے کچھ مہر اور ان کو کچھ خرچ دو مقدور والے پر اس کے موافق ہے اور تنگی والے پر اس کے موافق جو خرچ کہ قاعدہ کے موافق ہے لازم ہے نیکی کرنے والوں پر [۳۹۵]', 'There is no sin on you, if you divorce women while yet you have not touched (had sexual relation with) them, nor appointed unto them their Mahr (bridal money given by the husband to his wife at the time of marriage). But bestow on them ( a suitable gift), the rich according to his means, and the poor according to his means, a gift of reasonable amount is a duty on the doers of good.', 'There is no liability (of dower) on you if you divorce women when you have not yet touched them, nor fixed for them an amount. So, give them mut‘ah (a gift), a rich man according to his means and a poor one according to his means - a benefit in the recognized manner, an obligation on the virtuous.'),
(244, 2, 237, 31, 15, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ اِنۡ طَلَّقۡتُمُوۡہُنَّ مِنۡ قَبۡلِ اَنۡ تَمَسُّوۡہُنَّ وَ قَدۡ فَرَضۡتُمۡ لَہُنَّ فَرِیۡضَۃً فَنِصۡفُ مَا فَرَضۡتُمۡ  اِلَّاۤ  اَنۡ یَّعۡفُوۡنَ اَوۡ یَعۡفُوَا الَّذِیۡ بِیَدِہٖ عُقۡدَۃُ النِّکَاحِ ؕ وَ اَنۡ تَعۡفُوۡۤا اَقۡرَبُ لِلتَّقۡوٰی ؕ وَ لَا تَنۡسَوُا الۡفَضۡلَ بَیۡنَکُمۡ ؕ اِنَّ اللّٰہَ بِمَا تَعۡمَلُوۡنَ بَصِیۡرٌ ﴿۲۳۷﴾', 'اور اگر تم عورتوں کو ان کے پاس جانے سے پہلے طلاق دے دو لیکن مہر مقرر کرچکے ہو تو آدھا مہر دینا ہو گا۔ ہاں اگر عورتیں مہر بخش دیں۔ یا مرد جن کے ہاتھ میں عقد نکاح ہے اپنا حق چھوڑ دیں اور پورا مہر دے دیں تو ان کو اختیار ہے اور اگر تم مرد لوگ ہی اپنا حق چھوڑ دو تو یہ پرہیزگاری کی بات ہے اور آپس میں بھلائی کرنے کو فراموش نہ کرنا۔ کچھ شک نہیں کہ اللہ تمہارے سب کاموں کو دیکھ رہا ہے۔', 'اور اگر طلاق دو ان کو ہاتھ لگانے سے پہلے اور ٹھہرا چکے تھے تم ان کے لئے مہر تو لازم ہوا آدھا اس کا کہ تم مقرر کر چکے تھے مگر یہ کہ درگذر کریں عورتیں یا درگذر کرے وہ شخص کہ اس کے اختیار میں ہے گرہ نکاح کی یعنی خاوند اور تم مرد درگذر کرو تو قریب ہے پرہیزگاری سے اور نہ بھلا دو احسان کرنا آپس میں بیشک اللہ جو کچھ تم کرتے ہو خوب دیکھتا ہے [۳۹۶]', 'And if you divorce them before you have touched (had a sexual relation with) them, and you have appointed unto them the Mahr (bridal money given by the husbands to his wife at the time of marriage), then pay half of that (Mahr), unless they (the women) agree to forego it, or he (the husband), in whose hands is the marriage tie, agrees to forego and give her full appointed Mahr. And to forego and give (her the full Mahr) is nearer to At-Taqwa (piety, right-eousness, etc.). And do not forget liberality between yourselves. Truly, Allah is All-Seer of what you do.', 'If you divorce them before you have touched them, while you have already fixed for them an amount (of dower), then there is one half of what you have fixed, unless they (the women) forgive, or forgives the one in whose hand lies the marriage tie, and it is closer to Taqwā (righteousness) that you forgive, and do not forget to be graceful to one another. Surely, Allah is watchful of what you do.'),
(245, 2, 238, 31, 15, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'حٰفِظُوۡا عَلَی الصَّلَوٰتِ وَ الصَّلٰوۃِ الۡوُسۡطٰی ٭ وَ قُوۡمُوۡا لِلّٰہِ  قٰنِتِیۡنَ ﴿۲۳۸﴾', 'مسلمانو سب نمازیں خصوصاً بیچ کی نماز یعنی نماز عصر پورے اہتمام کے ساتھ ادا کرتے رہو اور اللہ کے آگے ادب سے کھڑے رہا کرو۔', 'خبردار  رہو سب نمازوں سے اور بیچ والی نماز سے اور کھڑے رہو اللہ کے آگے ادب سے [۳۹۷]', 'Guard strictly (five obligatory) AsSalawat (the prayers) especially the middle Salat (i.e. the best prayer Asr). And stand before Allah with obedience (and do not speak to others during the Salat (prayers)).', 'Take due care of all the prayers, and the middle prayer, and stand before Allah in total devotion.'),
(246, 2, 239, 31, 15, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'فَاِنۡ خِفۡتُمۡ  فَرِجَالًا اَوۡ  رُکۡبَانًا ۚ فَاِذَاۤ اَمِنۡتُمۡ  فَاذۡکُرُوا اللّٰہَ  کَمَا عَلَّمَکُمۡ مَّا لَمۡ تَکُوۡنُوۡا تَعۡلَمُوۡنَ ﴿۲۳۹﴾', 'پھر اگر تم خوف کی حالت میں ہو تو پیادے یا سوار جس حال میں ہو نماز پڑھ لو پھر جب امن و اطمینان ہو جائے تو جس طریق سے اللہ نے تم کو سکھایا ہے جو تم پہلے نہیں جانتے تھے اللہ کو یاد کرو۔', 'پھر اگر تم کو ڈر ہو کسی کا تو پیادہ پڑھ لو یا سوار پھر جس وقت تم امن پاؤ تو یاد کرو اللہ کو جس طرح کہ تم کو سکھایا ہے جس کو تم نہ جانتےتھے [۳۹۸]', 'And if you fear (an enemy), perfrom Salat (pray) on foot or riding. And when you are in safety, offer the Salat (prayer) in the manner He has taught you, which you knew not (before).', 'But if you are in fear, then (pray) on foot or riding. But when you are in peace, recite Allah’s name as He has taught you what you did not know.'),
(247, 2, 240, 31, 15, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ الَّذِیۡنَ یُتَوَفَّوۡنَ مِنۡکُمۡ وَ یَذَرُوۡنَ اَزۡوَاجًا ۚۖ وَّصِیَّۃً  لِّاَزۡوَاجِہِمۡ مَّتَاعًا اِلَی الۡحَوۡلِ غَیۡرَ   اِخۡرَاجٍ ۚ فَاِنۡ  خَرَجۡنَ فَلَا جُنَاحَ عَلَیۡکُمۡ فِیۡ مَا فَعَلۡنَ فِیۡۤ  اَنۡفُسِہِنَّ مِنۡ مَّعۡرُوۡفٍ ؕ وَ اللّٰہُ عَزِیۡزٌ حَکِیۡمٌ ﴿۲۴۰﴾', 'اور جو لوگ تم میں سے مر جائیں اور عورتیں چھوڑ جائیں وہ اپنی عورتوں کے حق میں وصیّت کر جائیں کہ ان کو ایک سال تک خرچ دیا جائے اور گھر سے نہ نکالی جائیں۔ ہاں اگر وہ خود گھر سے چلی جائیں اور اپنے حق میں پسندیدہ کام یعنی نکاح کر لیں تو تم پر کچھ گناہ نہیں اور اللہ زبردست ہے حکمت والا ہے۔', 'اور جو لوگ تم میں سے مر جاویں اور چھوڑ جاویں اپنی عورتیں تو وہ وصیت کر دیں اپنی عورتوں کے واسطے خرچ دینا ایک برس تک بغیر نکالنے کے گھر سے [۳۹۹] پھر اگر وہ عورتیں آپ نکل جاویں تو کچھ گناہ نہیں تم پر اس میں کہ کریں وہ عورتیں اپنے حق میں بھلی بات اور اللہ زبردست ہے حکمت والا [۴۰۰]', 'And those of you who die and leave behind wives should bequeath for their wives a years maintenance and residence without turning them out, but if they (wives) leave, there is no sin on you for that which they do of themselves, provided it is honourable (e.g. lawful marriage). And Allah is All-Mighty, All-Wise. (The order of this Verse has been cancelled (abrogated) by Verse 4:12).', 'Those among you who pass away and leave wives behind are (commanded) to make a will in favour of their wives to be maintained for one year without being expelled (from husband’s home). Then, if they move out, there is no sin on you in what they have done for themselves according to the fair practice. Allah is Mighty, Wise.'),
(248, 2, 241, 31, 15, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ لِلۡمُطَلَّقٰتِ مَتَاعٌۢ بِالۡمَعۡرُوۡفِ ؕ حَقًّا عَلَی  الۡمُتَّقِیۡنَ ﴿۲۴۱﴾', 'اور مطلّقہ عورتوں کو بھی دستور کے مطابق نان و نفقہ دینا چاہیے پرہیزگاروں پر یہ بھی حق ہے۔', 'اور طلاق دی ہوئی عورتوں کے واسطے خرچ دینا ہے قاعدہ کے موافق لازم ہے پرہیزگاروں پر [۴۰۱]', 'And for divorced women, maintenance (should be provided) on reasonable (scale). This is a duty on Al-Muttaqoon (the pious - see V.2:2).', 'The divorced women deserve a benefit according to the fair practice, being an obligation on the God-fearing.'),
(249, 2, 242, 31, 15, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'کَذٰلِکَ یُبَیِّنُ اللّٰہُ لَکُمۡ اٰیٰتِہٖ لَعَلَّکُمۡ تَعۡقِلُوۡنَ ﴿۲۴۲﴾٪', 'اسی طرح اللہ اپنے احکام تمہارے لیے بیان فرماتا ہے تاکہ تم سمجھو۔', 'اسی طرح بیان فرماتا ہے اللہ تمہارے واسطے اپنے حکم تاکہ تم سمجھ لو [۴۰۲]', 'Thus Allah makes clear His Ayat (Laws) to you, in order that you may understand.', 'This is how Allah makes His verses clear to you, so that you may understand.'),
(250, 2, 243, 32, 16, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اَلَمۡ تَرَ  اِلَی الَّذِیۡنَ خَرَجُوۡا مِنۡ دِیَارِہِمۡ وَ ہُمۡ اُلُوۡفٌ حَذَرَ الۡمَوۡتِ  ۪ فَقَالَ لَہُمُ اللّٰہُ  مُوۡتُوۡا ۟ ثُمَّ  اَحۡیَاہُمۡ  ؕ اِنَّ اللّٰہَ لَذُوۡ فَضۡلٍ عَلَی النَّاسِ وَ لٰکِنَّ  اَکۡثَرَ  النَّاسِ لَا یَشۡکُرُوۡنَ ﴿۲۴۳﴾', 'بھلا تم نے ان لوگوں کو نہیں دیکھا جو شمار میں ہزاروں ہی تھے اور موت کے ڈر سے اپنے گھروں سے نکل بھاگے تھے تو اللہ نے ان کو حکم دیا کہ مر جاؤ پھر ان کو زندہ بھی کر دیا۔ کچھ شک نہیں کہ اللہ لوگوں پر مہربانی رکھتا ہے لیکن اکثر لوگ شکر نہیں کرتے۔', 'کیا نہ دیکھا تو نے ان لوگوں کو جو کہ نکلے اپنے گھروں سے اور وہ ہزاروں تھے موت کے ڈر سے پھر فرمایا ان کو اللہ نے کہ مر جاؤ پھر ان کو زندہ کر دیا بیشک اللہ فضل کرنے والا ہے لوگوں پر لیکن اکثر لوگ شکر نہیں کرتے [۴۰۳]', 'Did you (O Muhammad SAW) not think of those who went forth from their homes in thousands, fearing death? Allah said to them, \"Die\". And then He restored them to life. Truly, Allah is full of Bounty to mankind, but most men thank not.', 'Have you not seen those who left their homes, while they were in thousands, to escape death? So, Allah said to them, “Be dead.” Then He raised them alive. Surely, Allah is gracious to people, but most of the people are not grateful.'),
(251, 2, 244, 32, 16, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ قَاتِلُوۡا فِیۡ سَبِیۡلِ اللّٰہِ وَ اعۡلَمُوۡۤا اَنَّ اللّٰہَ سَمِیۡعٌ عَلِیۡمٌ ﴿۲۴۴﴾', 'اور مسلمانو اللہ کی راہ میں جہاد کرو اور جان رکھو کہ اللہ سب کچھ سنتا ہے سب کچھ جانتا ہے۔', 'اور لڑو اللہ کی راہ میں اور جان لو کہ اللہ بیشک خوب سنتا جانتا ہے', 'And fight in the Way of Allah and know that Allah is All-Hearer, All-Knower.', 'Fight in the way of Allah, and know that Allah is All-Hearing, All-Knowing.'),
(252, 2, 245, 32, 16, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'مَنۡ ذَا الَّذِیۡ یُقۡرِضُ اللّٰہَ  قَرۡضًا حَسَنًا فَیُضٰعِفَہٗ لَہٗۤ اَضۡعَافًا کَثِیۡرَۃً ؕ وَ اللّٰہُ یَقۡبِضُ وَ یَبۡصُۜطُ  ۪ وَ اِلَیۡہِ  تُرۡجَعُوۡنَ ﴿۲۴۵﴾', 'کون ہے کہ اللہ کو قرض حسنہ دے کہ وہ اس کے بدلے اس کو کئ گنا زیادہ دے گا۔ اور اللہ ہی روزی کو تنگ کرتا اور وہی اسے کشادہ کرتا ہے اور تم اسی کی طرف لوٹ کر جاؤ گے۔', 'کو ن شخص ہے ایسا جو کہ قرض دے اللہ کو اچھا قرض پھر دوگنا کر دے اللہ اس کو کئ گنا اور اللہ ہی تنگی کردیتا ہے اور وہی کشائش کرتا ہے اور اسی کی طرف تم لوٹائے جاؤ گے [۴۰۴]', 'Who is he that will lend to Allah a goodly loan so that He may multiply it to him many times? And it is Allah that decreases or increases (your provisions), and unto Him you shall return.', 'Who is the one who would give Allah a good loan so that Allah multiplies it for him many times? Allah withholds and extends, and to Him you are to be returned.'),
(253, 2, 246, 32, 16, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'اَلَمۡ تَرَ  اِلَی الۡمَلَاِ مِنۡۢ بَنِیۡۤ  اِسۡرَآءِیۡلَ مِنۡۢ بَعۡدِ مُوۡسٰی ۘ اِذۡ  قَالُوۡا لِنَبِیٍّ لَّہُمُ ابۡعَثۡ لَنَا مَلِکًا نُّقَاتِلۡ فِیۡ سَبِیۡلِ اللّٰہِ ؕ قَالَ ہَلۡ عَسَیۡتُمۡ  اِنۡ کُتِبَ عَلَیۡکُمُ الۡقِتَالُ اَلَّا تُقَاتِلُوۡا ؕ قَالُوۡا وَ مَا لَنَاۤ  اَلَّا نُقَاتِلَ فِیۡ سَبِیۡلِ اللّٰہِ وَ قَدۡ اُخۡرِجۡنَا مِنۡ دِیَارِنَا وَ اَبۡنَآئِنَا ؕ فَلَمَّا کُتِبَ عَلَیۡہِمُ الۡقِتَالُ تَوَلَّوۡا اِلَّا قَلِیۡلًا مِّنۡہُمۡ ؕ وَ اللّٰہُ عَلِیۡمٌۢ  بِالظّٰلِمِیۡنَ ﴿۲۴۶﴾', 'بھلا تم نے بنی اسرائیل کی ایک جماعت کو نہیں دیکھا جس نے موسٰی کے بعد اپنے پیغمبر سے کہا کہ آپ ہمارے لئے ایک بادشاہ مقرر کر دیں تا کہ ہم اللہ کی راہ میں جہاد کریں۔ پیغمبر نے کہا کہ اگر تم کو جہاد کا حکم دیا جائے تو ایسا تو نہیں کہ لڑنے سے پہلوتہی کرو۔ وہ کہنے لگے کہ ہم  اللہ کی راہ میں کیوں نہ لڑیں گے۔ جب کہ ہم وطن سے خارج اور بال بچّوں سے جدا کر دئیے گئے۔ پھر جب ان کو جہاد کا حکم دیا گیا تو چند اشخاص کے سوا سب پھر گئے۔ اور اللہ ظالموں سے خوب واقف ہے۔', 'کیا نہ دیکھا تو نے ایک جماعت بنی اسرائیل کو موسٰیؑ کے بعد [۴۰۵] جب انہوں نےکہا اپنےنبی سے مقرر کر دو ہمارے لئے ایک بادشاہ تا کہ ہم لڑیں اللہ کی راہ میں پیغمبر نے کہا کیا تم سے یہ بھی توقع ہے کہ اگر حکم ہو تم کو لڑائی کا تو تم اس وقت نہ لڑو وہ بولے ہم کو کیا ہوا کہ ہم نہ لڑیں اللہ کی راہ میں اور ہم تو نکال دیے گئے اپنےگھروں سے اور بیٹوں سے پھر جب حکم ہوا ان کو لڑائی کا تو وہ سب پھر گئے مگر تھوڑے سے ان میں کے اور اللہ تعالیٰ خوب جانتا ہےگنہگاروں کو [۴۰۶]', 'Have you not thought about the group of the Children of Israel after (the time of) Musa (Moses)? When they said to a Prophet of theirs, \"Appoint for us a king and we will fight in Allahs Way.\" He said, \"Would you then refrain from fighting, if fighting was prescribed for you?\" They said, \"Why should we not fight in Allahs Way while we have been driven out of our homes and our children (families have been taken as captives)?\" But when fighting was ordered for them, they turned away, all except a few of them. And Allah is All-Aware of the Zalimoon (polytheists and wrong-doers).', 'Did you not see a group from the children of Isrā’īl (Israel), after (the time of) Mūsā when they said to their prophet: “Appoint for us a king, so that we may fight in the way of Allah.”He said: “Is it (not) likely, if fighting is enjoined upon you, that you would not fight.” They said: “What is wrong with us that we would not fight while we have been driven away from our homes and our sons?” But, when fighting was enjoined upon them, they turned away, except a few of them, and Allah is Aware of the unjust.'),
(254, 2, 247, 32, 16, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ قَالَ لَہُمۡ نَبِیُّہُمۡ  اِنَّ اللّٰہَ قَدۡ بَعَثَ لَکُمۡ طَالُوۡتَ مَلِکًا ؕ قَالُوۡۤا  اَنّٰی یَکُوۡنُ لَہُ الۡمُلۡکُ عَلَیۡنَا وَ نَحۡنُ اَحَقُّ بِالۡمُلۡکِ مِنۡہُ وَ لَمۡ یُؤۡتَ سَعَۃً مِّنَ الۡمَالِ ؕ قَالَ  اِنَّ اللّٰہَ  اصۡطَفٰىہُ عَلَیۡکُمۡ وَ زَادَہٗ بَسۡطَۃً فِی الۡعِلۡمِ وَ الۡجِسۡمِ ؕ وَ اللّٰہُ یُؤۡتِیۡ مُلۡکَہٗ مَنۡ یَّشَآءُ ؕ وَ اللّٰہُ  وَاسِعٌ عَلِیۡمٌ ﴿۲۴۷﴾', 'اور پیغمبر نے ان سے یہ بھی کہا کہ اللہ نے تم پر طالوت کو بادشاہ مقرر فرمایا ہے۔ وہ بولے کہ اسے ہم پر بادشاہی کا حق کیونکر ہو سکتا ہے۔ اس سے بڑھ کر بادشاہی کے مستحق تو ہم ہیں اور اس کے پاس تو بہت سی دولت بھی نہیں۔ پیغمبر نے کہا کہ اللہ نے اس کو تم پر فضیلت دی ہے اور بادشاہی کے لئے منتخب فرمایا ہے اس نے اسے علم بھی بہت سا بخشا ہے اور تن و توش بھی بڑا عطا کیا ہے اور اللہ کو اختیار ہے جسے چاہے بادشاہی بخشے۔ وہ بڑا کشائش والا ہے اور دانا ہے۔', 'اور فرمایا ان سے ان کے نبی نے بیشک اللہ نے مقرر فرما دیا تمہارے لئے طالوت کو بادشاہ کہنےلگے کیونکر ہو سکتی ہے اس کو حکومت ہم پر اور ہم زیادہ مستحق ہیں سلطنت کے اس سے اور اس کو نہیں ملی کشائش مال میں پیغمبر نے کہا بیشک اللہ نے پسند فرمایا اس کو تم پر اور زیادہ فراخی دی اس کو علم اور جسم میں اور اللہ دیتا ہے ملک اپنا جس کو چاہے اور اللہ ہے فضل کرنے والا سب کچھ جاننے والا [۴۰۷]', 'And their Prophet (Samuel ) said to them, \"Indeed Allah has appointed Taloot (Saul) as a king over you.\" They said, \"How can he be a king over us when we are better fitted than him for the kingdom, and he has not been given enough wealth.\" He said: \"Verily, Allah has chosen him above you and has increased him abundantly in knowledge and stature. And Allah grants His Kingdom to whom He wills. And Allah is All-Sufficient for His creatures needs, All-Knower.\"', 'Their prophet said to them: “Allah has appointed Tālūt as a king for you.” They said: “How could he have kingship over us when we are more entitled to the kingship than him? He has not been given affluence in wealth.” He said: “Allah has chosen him over you and has increased his stature in knowledge and physique, and Allah gives His kingship to whom He wills. Allah is All-Embracing, All-Knowing.’'),
(255, 2, 248, 32, 16, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ قَالَ لَہُمۡ نَبِیُّہُمۡ اِنَّ اٰیَۃَ مُلۡکِہٖۤ اَنۡ یَّاۡتِیَکُمُ التَّابُوۡتُ فِیۡہِ سَکِیۡنَۃٌ مِّنۡ رَّبِّکُمۡ وَ بَقِیَّۃٌ   مِّمَّا تَرَکَ اٰلُ مُوۡسٰی وَ اٰلُ ہٰرُوۡنَ تَحۡمِلُہُ الۡمَلٰٓئِکَۃُ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیَۃً لَّکُمۡ  اِنۡ  کُنۡتُمۡ مُّؤۡمِنِیۡنَ ﴿۲۴۸﴾٪', 'اور پیغمبر نے ان سے کہا کہ ان کی یعنی طالوت کی بادشاہی کی نشانی یہ ہے کہ تمہارے پاس وہ صندوق آئے گا جس کو فرشتے اٹھائے ہوئے ہوں گے اس میں تمہارے پروردگار کی طرف سے تسلّی بخشنے والی چیز ہو گی اور کچھ اور چیزیں بھی ہوں گی جو موسٰی اور ہارون چھوڑ گئے تھے۔ اگر تم ایمان رکھتے ہو تو یہ تمہارے لئے ایک بڑی نشانی ہے۔', 'اور کہا بنی اسرائیل سے ان کے نبی نے کہ طالوت کی سلطنت کی نشانی یہ ہے کہ آوے تمہارےپاس ایک صندوق کہ جس میں تسلی خاطر ہے تمہارے رب کی طرف سے اور کچھ بچی ہوئی چیزیں ہیں ان میں سے جو چھوڑ گئ تھی موسٰیؑ اور ہارونؑ کی اولاد اٹھا لاویں گے اس صندوق کو فرشتے بیشک اس میں پوری نشانی ہے تمہارے واسطے اگر تم یقین رکھتے ہو [۴۰۸]', 'And their Prophet (Samuel ) said to them: Verily! The sign of His Kingdom is that there shall come to you At-Taboot (a wooden box), wherein is Sakinah (peace and reassurance) from your Lord and a remnant of that which Musa (Moses) and Haroon (Aaron) left behind, carried by the angels. Verily, in this is a sign for you if you are indeed believers.', 'Their prophet said to them: “The sign of his kingship is that the Ark shall come to you, carried by the angels, having therein tranquillity from your Lord, and the remains of what the House of Mūsā and the House of Hārūn (Aaron) had left. Surely, in it there is a sign for you, if you are believers.”'),
(256, 2, 249, 33, 17, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'فَلَمَّا فَصَلَ طَالُوۡتُ بِالۡجُنُوۡدِ  ۙ قَالَ  اِنَّ اللّٰہَ مُبۡتَلِیۡکُمۡ بِنَہَرٍ ۚ فَمَنۡ شَرِبَ مِنۡہُ فَلَیۡسَ مِنِّیۡ ۚ وَ مَنۡ لَّمۡ یَطۡعَمۡہُ فَاِنَّہٗ مِنِّیۡۤ  اِلَّا مَنِ اغۡتَرَفَ غُرۡفَۃًۢ بِیَدِہٖ ۚ فَشَرِبُوۡا مِنۡہُ اِلَّا قَلِیۡلًا مِّنۡہُمۡ ؕ فَلَمَّا جَاوَزَہٗ ہُوَ وَ الَّذِیۡنَ اٰمَنُوۡا مَعَہٗ  ۙ قَالُوۡا لَا طَاقَۃَ لَنَا الۡیَوۡمَ بِجَالُوۡتَ وَ جُنُوۡدِہٖ ؕ قَالَ الَّذِیۡنَ یَظُنُّوۡنَ اَنَّہُمۡ مُّلٰقُوا اللّٰہِ  ۙ  کَمۡ مِّنۡ فِئَۃٍ قَلِیۡلَۃٍ غَلَبَتۡ فِئَۃً  کَثِیۡرَۃًۢ بِاِذۡنِ  اللّٰہِ ؕ وَ اللّٰہُ مَعَ  الصّٰبِرِیۡنَ ﴿۲۴۹﴾', 'غرض جب طالوت فوجیں لے کر روانہ ہوا تو اس نے ان سے کہا کہ اللہ ایک نہر سے تمہاری آزمائش کرنے والا ہے۔ جو شخص اس میں سے پانی پی لے گا اس کی نسبت تصّور کیا جائے گا کہ وہ میرا نہیں۔ اور جو نہ پئے گا وہ سمجھا جائے گا کہ میرا ہے۔ ہاں اگر کوئی ہاتھ سے چلو بھر پانی لے لے تو خیر جب وہ لوگ جب نہر پر پہنچے تو چند آدمیوں کے سوا سب نے پانی پی لیا۔ پھر جب طالوت اور مومن لوگ جو اس کے ساتھ تھے نہر کے پار ہو گئے تو کہنے لگے  کہ آج ہم میں جالوت اور اسکے لشکر سے مقابلہ کرنے کی طاقت نہیں جو لوگ یقین رکھتے تھے کہ انکو اللہ کے روبرو حاضر ہونا ہے وہ کہنے لگے کہ بسا اوقات تھوڑی سی جماعت نے اللہ کے حکم سے بڑی جماعت پر فتح حاصل کی ہے اور اللہ ثابت قدم رہنے والوں کے ساتھ ہے۔', 'پھر جب باہر نکلا طالوت فوجیں لے کر کہا بیشک اللہ تمہاری آزمائش کرتا ہے ایک نہر سے سو جس نے پانی پیا اس نہر کا تو وہ میرا نہیں اور جس نے اس کو نہ چکھا تو وہ بیشک میرا ہے مگر جو کوئی بھرےایک چلو اپنے ہاتھ سے پھر پی لیا سب نے اس کا پانی مگر تھوڑوں نے ان میں سے پھر جب پار ہوا طالوت اور ایمان والے ساتھ اس کے تو کہنےلگے طاقت نہیں ہم کو آج جالوت اور اس کے لشکروں سے لڑنے کی کہنے لگے وہ لوگ جن کو خیال تھا کہ ان کو اللہ سےملنا ہے بارہا تھوڑی جماعت غالب ہوئی ہے بڑی جماعت پر اللہ کے حکم سے اور اللہ صبر کرنے والوں کے ساتھ ہے [۴۰۹]', 'Then when Taloot (Saul) set out with the army, he said: \"Verily! Allah will try you by a river. So whoever drinks thereof, he is not of me, and whoever tastes it not, he is of me, except him who takes (thereof) in the hollow of his hand.\" Yet, they drank thereof, all, except a few of them. So when he had crossed it (the river), he and those who believed with him, they said: \"We have no power this day against Jaloot (Goliath) and his hosts.\" But those who knew with certainty that they were to meet their Lord, said: \"How often a small group overcame a mighty host by Allahs Leave?\" And Allah is with As-Sabirin (the patient ones, etc.).', 'So, when Tālūt set out along with the troops, he said: “Allah is going to test you by a river, so, whoever drinks from it is not my man, and whoever does not taste it is surely a man of mine, except the one who scoops a little with his hand.” Then they drank from it, except a few of them. So, when it (the river) was crossed by him and by those who believed with him, they said: “There is no strength with us today against Jālūt and his troops.” Said those who believed in their having to meet Allah: “How many small groups have overcome large groups by the will of Allah. Allah is with those who remain patient.”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(257, 2, 250, 33, 27, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'وَ لَمَّا بَرَزُوۡا لِجَالُوۡتَ وَ جُنُوۡدِہٖ قَالُوۡا رَبَّنَاۤ  اَفۡرِغۡ عَلَیۡنَا صَبۡرًا وَّ ثَبِّتۡ اَقۡدَامَنَا وَ انۡصُرۡنَا عَلَی الۡقَوۡمِ الۡکٰفِرِیۡنَ ﴿۲۵۰﴾ؕ', 'اور جب وہ لوگ جالوت اور اس کے لشکر کے مقابل میں آئے تو اللہ سے دعا کی کہ اے پروردگار ہم پر صبر کے دہانے کھول دے اور ہمیں لڑائی میں ثابت قدم رکھ اور لشکر کفار پر فتحیاب کر۔', 'اور جب سامنے ہوئے جالوت کے اور اس کی فوجوں کے تو بولے اے رب ہمارےڈال دے ہمارے دلوں میں صبر اور جمائے رکھ ہمارے پاؤں اور مدد کر ہماری اس کافر قوم پر', 'And when they advanced to meet Jaloot (Goliath) and his forces, they invoked: \"Our Lord! Pour forth on us patience and make us victorious over the disbelieving people.\"', 'And when they faced Jālūt and his troops, they said: “Our Lord, pour out endurance on us, make firm our feet and help us against the disbelieving people.”'),
(258, 2, 251, 33, 18, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'فَہَزَمُوۡہُمۡ  بِاِذۡنِ اللّٰہِ ۟ۙ وَ قَتَلَ دَاوٗدُ جَالُوۡتَ وَ اٰتٰىہُ اللّٰہُ  الۡمُلۡکَ وَ الۡحِکۡمَۃَ وَ عَلَّمَہٗ مِمَّا یَشَآءُ ؕ وَ لَوۡ لَا دَفۡعُ اللّٰہِ النَّاسَ بَعۡضَہُمۡ بِبَعۡضٍ ۙ لَّفَسَدَتِ الۡاَرۡضُ وَ لٰکِنَّ اللّٰہَ ذُوۡ فَضۡلٍ عَلَی الۡعٰلَمِیۡنَ ﴿۲۵۱﴾', 'تو طالوت کی فوج نے اللہ کے حکم سے ان کو شکست دیدی اور داؤد نے جالوت کو قتل کر ڈالا۔ اور اللہ نے ان کو بادشاہی اور دانائی بخشی اور جو کچھ چاہا سکھایا۔ اور اگر اللہ لوگوں کو ایک دوسرے پر چڑھائی اور حملہ کرنے سے نہ ہٹاتا رہتا تو کرہ ارض تباہ ہو جاتا لیکن اللہ اہل عالم پر بڑا مہربان ہے۔', 'پھر شکست دی مومنوں نے جالوت کے لشکر کو اللہ کے حکم سے اور مار ڈالا داؤد نے جالوت کو اور دی داؤد کو اللہ نے سلطنت اور حکمت اور سکھایا ان کو جو چاہاا اور اگر نہ ہوتا دفع کرا دینا اللہ کا ایک کو دوسرے سے تو خراب ہو جاتا ملک لیکن اللہ بہت مہربان ہے جہان کے لوگوں پر [۴۱۰]', 'So they routed them by Allahs Leave and Dawood (David) killed Jaloot (Goliath), and Allah gave him (Dawood (David)) the kingdom (after the death of Taloot (Saul) and Samuel) and AlHikmah (Prophethood), and taught him of that which He willed. And if Allah did not check one set of people by means of another, the earth would indeed be full of mischief. But Allah is full of Bounty to the Alameen (mankind, jinns and all that exists).', 'So, they defeated them by the will of Allah, and Dāwūd (David) killed Jālūt, and Allah gave him the kingdom and the wisdom and taught him what He willed. Had Allah not been pushing back some people by means of others, the earth would have been spoiled. But Allah is All-Gracious to all the worlds.'),
(259, 2, 252, 33, 0, 2, 'سَیَقُوۡلُ ', 'البقرۃ', 'تِلۡکَ اٰیٰتُ اللّٰہِ نَتۡلُوۡہَا عَلَیۡکَ بِالۡحَقِّ ؕ وَ  اِنَّکَ لَمِنَ الۡمُرۡسَلِیۡنَ ﴿۲۵۲﴾', 'یہ اللہ کی آیتیں ہیں جو ہم تم کو سچّائی کے ساتھ پڑھ کر سناتے ہیں اور اے محمد ﷺ تم بلاشبہ پیغمبروں میں سے ہو۔', 'یہ آیتیں اللہ کی ہیں ہم تجھ کو سناتے ہیں ٹھیک ٹھیک اور تو بیشک ہمارے رسولوں میں ہے [۴۱۱]', 'These are the Verses of Allah, We recite them to you (O Muhammad SAW) in truth, and surely, you are one of the Messengers (of Allah).', 'These are the verses of Allah that We recite to you (O Prophet), with all veracity, and certainly you are among the Messengers.'),
(260, 2, 253, 33, 1, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'تِلۡکَ الرُّسُلُ  فَضَّلۡنَا بَعۡضَہُمۡ عَلٰی بَعۡضٍ ۘ مِنۡہُمۡ مَّنۡ کَلَّمَ اللّٰہُ وَ رَفَعَ بَعۡضَہُمۡ  دَرَجٰتٍ ؕ وَ اٰتَیۡنَا عِیۡسَی  ابۡنَ مَرۡیَمَ الۡبَیِّنٰتِ وَ اَیَّدۡنٰہُ بِرُوۡحِ الۡقُدُسِ ؕ وَ لَوۡ شَآءَ اللّٰہُ مَا اقۡتَتَلَ الَّذِیۡنَ مِنۡۢ بَعۡدِہِمۡ مِّنۡۢ بَعۡدِ مَا جَآءَتۡہُمُ الۡبَیِّنٰتُ وَ لٰکِنِ اخۡتَلَفُوۡا فَمِنۡہُمۡ مَّنۡ اٰمَنَ وَ مِنۡہُمۡ مَّنۡ  کَفَرَ ؕ وَ لَوۡ شَآءَ اللّٰہُ  مَا اقۡتَتَلُوۡا ۟ وَ لٰکِنَّ اللّٰہَ یَفۡعَلُ  مَا یُرِیۡدُ ﴿۲۵۳﴾٪', 'یہ پیغمبر جو ہم وقتاً فوقتاً بھیجتے رہے ہیں ان میں سے ہم نے بعض کو بعض پر فضیلت دی ہے۔ بعض ایسے ہیں جن سے اللہ نے گفتگو کی اور بعض کے دوسرے امور میں مرتبے بلند کئے۔ اور عیسٰی ابن مریم کو ہم نے کھلی ہوئی نشانیاں عطا کیں۔ اور روح القدس سے ان کو مدد دی۔ اور اگر اللہ چاہتا تو ان سے پچھلے لوگ اپنے پاس کھلی نشانیاں آنے کے بعد آپس میں نہ لڑتے لیکن انہوں نے اختلاف کیا تو ان میں سے بعض تو ایمان لے آئے اور بعض کافر ہی رہے اور اگر اللہ چاہتا تو یہ لوگ باہم جنگ و قتال نہ کرتے۔ لیکن اللہ جو چاہتا ہے کرتا ہے۔', 'یہ سب رسول فضیلت دی ہم نے ان میں بعض کو بعض سے کوئی تو وہ ہے کہ کلام فرمایا اس سے اللہ نے اور بلند کئے بعضوں کے درجے اور دیے ہم نے عیسٰیؑ مریم کے بیٹے کو معجزے صریح اور قوت دی اس کو روح القدس یعنی جبریل سے [۴۱۲] اور اگر اللہ چاہتا تو نہ لڑتے وہ لوگ جو ہوئے ان پیغمبروں کے پیچھے بعد اس کے کہ پہنچ  چکے ان کے پاس صاف حکم لیکن ان میں اختلاف پڑ گیا پھر کوئی تو ان میں ایمان لایا اور کوئی کافر رہا اور اگر چاہتا اللہ تو وہ باہم نہ لڑتے لیکن اللہ کرتا ہے جو چاہے [۴۱۳]', 'Those Messengers! We preferred some to others; to some of them Allah spoke (directly); others He raised to degrees (of honour); and to Iesa (Jesus), the son of Maryam (Mary), We gave clear proofs and evidences, and supported him with Rooh-ul-Qudus (Jibrael (Gabriel)). If Allah had willed, succeeding generations would not have fought against each other, after clear Verses of Allah had come to them, but they differed - some of them believed and others disbelieved. If Allah had willed, they would not have fought against one another, but Allah does what He likes.', 'Those are the messengers some of whom We have given excellence over some others. Among them there are ones to whom Allah spoke (directly) and He raised some of them steps higher (in other respects), and We gave clear signs to ‘Īsā (Jesus), the son of Maryam (Mary) and supported him with the Holy Spirit. If Allah so willed, those succeeding him would have not fought against each other after clear signs had come to them.But they disagreed among themselves. So, there were some who believed and there were some who disbelieved, and if Allah so willed, they would have not fought against each other. But Allah does what He intends'),
(261, 2, 254, 34, 2, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اَنۡفِقُوۡا مِمَّا رَزَقۡنٰکُمۡ مِّنۡ قَبۡلِ اَنۡ یَّاۡتِیَ یَوۡمٌ لَّا بَیۡعٌ فِیۡہِ وَ لَا خُلَّۃٌ وَّ لَا شَفَاعَۃٌ ؕ وَ الۡکٰفِرُوۡنَ ہُمُ  الظّٰلِمُوۡنَ ﴿۲۵۴﴾', 'اے ایمان والو جو مال ہم نے تم کو دیا ہے اس میں سے اس دن کے آنے سے پہلے پہلے خرچ کر لو جس میں نہ اعمال کا سودا ہو۔ اور نہ دوستی اور سفارش ہو سکے۔ اور کفر کرنے والے لوگ ظالم ہیں۔', 'اے ایمان والو خرچ کرو اس میں سے جو ہم نے تم کو روزی دی پہلے اس دن کے آنے سے کہ جس میں نہ خرید و فرخت ہے اور نہ آشنائی اور نہ سفارش [۴۱۴] اور جو کافر ہیں وہی ہیں ظالم [۴۱۵]', 'O you who believe! Spend of that with which We have provided for you, before a Day comes when there will be no bargaining, nor friendship, nor intercession. And it is the disbelievers who are the Zalimoon (wrong-doers, etc.).', 'O you who believe! Spend from what We have given to you before a day comes when there will be no trading, no friendship and no intercession, and it is the disbelievers who are unjust.'),
(262, 2, 255, 34, 2, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'اَللّٰہُ لَاۤ اِلٰہَ اِلَّا ہُوَۚ اَلۡحَیُّ الۡقَیُّوۡمُ ۬ۚ لَا تَاۡخُذُہٗ سِنَۃٌ وَّ لَا نَوۡمٌ ؕ لَہٗ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ؕ مَنۡ ذَا الَّذِیۡ یَشۡفَعُ  عِنۡدَہٗۤ  اِلَّا بِاِذۡنِہٖ ؕ یَعۡلَمُ مَا بَیۡنَ اَیۡدِیۡہِمۡ وَ مَا خَلۡفَہُمۡ  ۚ وَ لَا یُحِیۡطُوۡنَ بِشَیۡءٍ مِّنۡ عِلۡمِہٖۤ اِلَّا بِمَا شَآءَ ۚ وَسِعَ کُرۡسِیُّہُ السَّمٰوٰتِ وَ الۡاَرۡضَ ۚ وَ لَا یَـُٔوۡدُہٗ حِفۡظُہُمَا ۚ وَ ہُوَ الۡعَلِیُّ  الۡعَظِیۡمُ ﴿۲۵۵﴾', 'خدا وہ معبود برحق ہے کہ اس کے سوا کوئی عبادت کے لائق نہیں زندہ ہے سب کو تھامنے والا اسے نہ اونگھ آتی ہے نہ نیند جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب  اسی کا ہے۔ کون ہے کہ اس کی اجازت کے بغیر اس سے کسی کی سفارش کر سکے۔ جو کچھ لوگوں کے روبرو ہو رہا ہے اور جو کچھ ان کے پیچھے ہو چکا ہے اسے سب معلوم ہے اور لوگ اس کی معلومات میں سے کسی چیز پر دسترس حاصل نہیں کر سکتے ہاں جس قدر وہ چاہتا ہے اسی قدر معلوم کرا دیتا ہے اس کی بادشاہی اور علم آسمان اور زمین سب پر حاوی ہے۔ اور اسے انکی حفاظت کچھ بھی دشوار نہیں وہ بڑا عالی رتبہ ہے جلیل القدر ہے۔', 'اللہ اس کے سوا کوئی معبود نہں زندہ ہے سب کا تھامنے والا [۴۱۶] نہیں پکڑ سکتی اس کو اونگھ اور نہ نیند اسی کا ہے جو کچھ آسمانوں اور زمین میں ہے ایسا کون ہے جو سفارش کرے اس کے پاس مگر اجازت سے جانتا ہے جو کچھ خلقت کے روبرو ہے اور جو کچھ انکے پیچھے ہے اور وہ سب احاطہ نہیں کر سکتے کسی چیز کا اس کی معلومات میں سے مگر جتنا کہ وہی چاہے گنجائش ہے اس کی کرسی میں تمام آسمانوں اور زمین کو اور گراں نہیں اس کو تھامنا ان کا اور وہی ہے سب سے برتر عظمت والا [۴۱۷]', 'Allah! La ilaha illa Huwa (none has the right to be worshipped but He), the Ever Living, the One Who sustains and protects all that exists. Neither slumber, nor sleep overtake Him. To Him belongs whatever is in the heavens and whatever is on earth. Who is he that can intercede with Him except with His Permission? He knows what happens to them (His creatures) in this world, and what will happen to them in the Hereafter . And they will never compass anything of His Knowledge except that which He wills. His Kursee extends over the heavens and the earth, and He feels no fatigue in guarding and preserving them. And He is the Most High, the Most Great. (This Verse 2:255 is called Ayat-ul-Kursee.)', 'Allah: There is no god but He, the Living, the All-Sustaining. Neither dozing overtakes Him nor sleep. To Him belongs all that is in the heavens and all that is on the earth. Who can intercede with Him without His permission? He knows what is before them and what is behind them; while they encompass nothing of His knowledge, except what He wills. His Kursiyy (Chair) extends to the Heavens and to the Earth, and it does not weary Him to look after them. He is the All-High, the Supreme.'),
(263, 2, 256, 34, 2, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'لَاۤ اِکۡرَاہَ فِی الدِّیۡنِ ۟ۙ قَدۡ تَّبَیَّنَ الرُّشۡدُ مِنَ الۡغَیِّ ۚ فَمَنۡ یَّکۡفُرۡ بِالطَّاغُوۡتِ وَ یُؤۡمِنۡۢ بِاللّٰہِ فَقَدِ اسۡتَمۡسَکَ بِالۡعُرۡوَۃِ الۡوُثۡقٰی ٭ لَا انۡفِصَامَ  لَہَا ؕ وَ اللّٰہُ سَمِیۡعٌ عَلِیۡمٌ ﴿۲۵۶﴾', 'دین اسلام میں کوئی زبردستی نہیں ہے۔ ہدایت صاف طور پر ظاہر اور گمراہی سے الگ ہو چکی ہے۔ تو جو شخص بتوں سے اعتقاد نہ رکھے اور اللہ پر ایمان لائے اس نے ایسی مضبوط رسّی ہاتھ میں پکڑ لی ہے جو کبھی ٹوٹنے والی نہیں اور اللہ سب کچھ سنتا ہے سب کچھ جانتا ہے۔', 'زبردستی نہں دین کے معاملہ میں بیشک جدا ہو چکی ہے ہدیات گمراہی سے [۴۱۸] اب جو کوئی نہ مانےگمراہ کرنےوالوں کو اور یقین لاوےاللہ پر تو اس نے پکڑ لیا حلقہ مضبوط جو ٹوٹنے والا نہیں اور اللہ سب کچھ سنتا جانتا ہے [۴۱۹]', 'There is no compulsion in religion. Verily, the Right Path has become distinct from the wrong path. Whoever disbelieves in Taghoot and believes in Allah, then he has grasped the most trustworthy handhold that will never break. And Allah is All-Hearer, All-Knower.', 'There is no compulsion in Faith. The correct way has become distinct from the erroneous. Now, whoever rejects the Tāghūt (the Rebel, the Satan) and believes in Allah has a firm grasp on the strongest ring that never breaks. Allah is All-Hearing, All-Knowing.'),
(264, 2, 257, 34, 2, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'اَللّٰہُ وَلِیُّ الَّذِیۡنَ اٰمَنُوۡا ۙ یُخۡرِجُہُمۡ مِّنَ الظُّلُمٰتِ اِلَی النُّوۡرِ۬ؕ وَ الَّذِیۡنَ کَفَرُوۡۤا اَوۡلِیٰٓـُٔہُمُ الطَّاغُوۡتُ ۙ یُخۡرِجُوۡنَہُمۡ مِّنَ النُّوۡرِ اِلَی الظُّلُمٰتِ ؕ اُولٰٓئِکَ اَصۡحٰبُ النَّارِ ۚ ہُمۡ  فِیۡہَا خٰلِدُوۡنَ ﴿۲۵۷﴾٪', 'جو لوگ ایمان لائے ہیں ان کا دوست اللہ ہے کہ اندھیرے سے نکال کر روشنی میں لے جاتا ہے اور جو کافر ہیں ان کے دوست شیطان ہیں کہ ان کو روشنی سے نکال کر اندھیرے میں لے جاتے ہیں۔ یہی لوگ اہل دوزخ ہیں کہ اس میں ہمیشہ رہیں گے۔', 'اللہ مددگار ہے ایمان والوں کا نکالتا ہے ان کو اندھیروں سے روشنی کی طرف اور جو لوگ کافر ہوئے ان کے رفیق ہیں شیطان نکالتے ہیں ان کو روشنی سے اندھیروں کی طرف یہی لوگ ہیں دوزخ میں رہنے والے وہ اسی میں ہمیشہ رہیں گے', 'Allah is the Walee (Protector or Guardian) of those who believe. He brings them out from darkness into light. But as for those who disbelieve, their Auliya (supporters and helpers) are Taghoot (false deities and false leaders, etc.), they bring them out from light into darkness. Those are the dwellers of the Fire, and they will abide therein forever.', 'Allah is the Protector of those who believe. He brings them out of the depths of darkness into the light. As for those who disbelieve, their friends are the Rebels. They bring them out from the light into the depths of darkness. Those are people of the Fire. There they will remain forever.'),
(265, 2, 258, 35, 3, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'اَلَمۡ تَرَ اِلَی الَّذِیۡ حَآجَّ اِبۡرٰہٖمَ فِیۡ رَبِّہٖۤ اَنۡ اٰتٰىہُ اللّٰہُ الۡمُلۡکَ ۘ اِذۡ  قَالَ اِبۡرٰہٖمُ رَبِّیَ الَّذِیۡ یُحۡیٖ وَ یُمِیۡتُ ۙ قَالَ اَنَا اُحۡیٖ وَ اُمِیۡتُ ؕ قَالَ اِبۡرٰہٖمُ  فَاِنَّ اللّٰہَ یَاۡتِیۡ بِالشَّمۡسِ مِنَ الۡمَشۡرِقِ فَاۡتِ بِہَا مِنَ الۡمَغۡرِبِ فَبُہِتَ الَّذِیۡ کَفَرَ ؕ وَ اللّٰہُ لَا یَہۡدِی الۡقَوۡمَ الظّٰلِمِیۡنَ ﴿۲۵۸﴾ۚ', 'بھلا تم نے اس شخص کو نہیں دیکھا جو اس غرور کے سبب سے کہ اللہ نے اس کو سلطنت بخشی تھی ابراہیم سے اپنے پروردگار کے بارے میں جھگڑنے لگا جب ابراہیم نے کہا میرا پروردگار تو وہ ہے جو زندگی دیتا ہے اور موت دیتا ہے وہ بولا کہ زندگی اور موت تو میں بھی دے سکتا ہوں۔ ابراہیم نے کہا کہ اللہ تو سورج کو مشرق سے نکالتا ہے آپ اسے مغرب سے نکال دیجئے یہ سن کر وہ کافر ہکا بکا رہ گیا۔ اور اللہ بے انصافوں کو ہدایت نہیں دیا کرتا۔', 'کیا نہ دیکھا تو نے اس شخص کو جس نے جھگڑا کیا ابراہیم سے اس کے رب کی بابت اسی وجہ سے کہ دی تھی اللہ نے اس کو سلطنت جب کہا ابراہیم نے میرا رب وہ ہے جو زندہ کرتا ہے اور مارتا ہے وہ بولا میں بھی جلاتا اور مارتا ہوں کہا ابراہیم نے کہ بیشک اللہ تو لاتا ہے سورج کو مشرق سے اب تو لے آ اس کو مغرب کی طرف سے تب حیران رہ گیا وہ کافر اور اللہ سیدھی راہ نہیں دکھاتا بے انصافوں کو [۴۲۰]', 'Have you not looked at him who disputed with Ibrahim (Abraham) about his Lord (Allah), because Allah had given him the kingdom? When Ibrahim (Abraham) said (to him): \"My Lord (Allah) is He Who gives life and causes death.\" He said, \"I give life and cause death.\" Ibrahim (Abraham) said, \"Verily! Allah causes the sun to rise from the east; then cause it you to rise from the west.\" So the disbeliever was utterly defeated. And Allah guides not the people, who are Zalimoon (wrong-doers, etc.).', 'Do you not know the one who argued with Ibrāhīm about his Lord, because Allah had given him kingship? When Ibrāhīm said: “My Lord is the One Who gives life and brings death,” he said: “I give life and I bring death.” Said Ibrāhīm: “Allah brings the sun out from the East; now, you bring it out from the West.” Here, baffled was the one who disbelieved, and Allah does not bring the wrongdoers to the right path.'),
(266, 2, 259, 35, 3, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'اَوۡ کَالَّذِیۡ مَرَّ عَلٰی قَرۡیَۃٍ وَّ ہِیَ خَاوِیَۃٌ عَلٰی عُرُوۡشِہَا ۚ قَالَ اَنّٰی یُحۡیٖ ہٰذِہِ  اللّٰہُ بَعۡدَ مَوۡتِہَا ۚ فَاَمَاتَہُ اللّٰہُ مِائَۃَ عَامٍ ثُمَّ بَعَثَہٗ ؕ قَالَ کَمۡ لَبِثۡتَ ؕ قَالَ لَبِثۡتُ یَوۡمًا اَوۡ بَعۡضَ یَوۡمٍ ؕ قَالَ بَلۡ لَّبِثۡتَ مِائَۃَ عَامٍ فَانۡظُرۡ  اِلٰی طَعَامِکَ وَ شَرَابِکَ لَمۡ یَتَسَنَّہۡ ۚ وَ انۡظُرۡ اِلٰی حِمَارِکَ وَ لِنَجۡعَلَکَ اٰیَۃً لِّلنَّاسِ وَ انۡظُرۡ اِلَی الۡعِظَامِ کَیۡفَ نُنۡشِزُہَا ثُمَّ نَکۡسُوۡہَا لَحۡمًا ؕ فَلَمَّا تَبَیَّنَ لَہٗ ۙ قَالَ اَعۡلَمُ  اَنَّ اللّٰہَ  عَلٰی کُلِّ شَیۡءٍ قَدِیۡرٌ ﴿۲۵۹﴾', 'یا اسی طرح اس شخص کو نہیں دیکھا جس کا ایک بستی پر جو اپنی چھتوں پر گری پڑی تھی گذر ہوا تو اس نے کہا کہ اللہ اس کے باشندوں کو مرنے کے بعد کیونکر زندہ کرے گا۔ تو اللہ نے اس کی روح قبض کر لی اور سو برس تک اس کو مردہ رکھا پھر اس کوجِلا اٹھایا اور پوچھا تم کتنا عرصہ مرےپڑے رہے ہو۔ اس نے جواب دیا کہ ایک دن یا اس سے بھی کم۔ اللہ نے فرمایا نہیں بلکہ سو برس مرے رہے ہو۔ اور اپنے کھانے پینے کی چیزوں کو دیکھو کہ اتنی مدّت میں مطلق سڑی بسی نہیں اور اپنے گدھے کو بھی دیکھو جو مرا پڑا ہے غرض ان باتوں سے یہ ہے کہ ہم تم کو لوگوں کے لئے اپنی قدرت کی نشانی بنائیں اور ہاں گدھے کی ہڈیوں کو دیکھو کہ ہم ان کو کسطرح جوڑے دیتے اور ان پر کس طرح گوشت پوست چڑھائے دیتے ہیں۔ جب یہ واقعات اس کے مشاہدے میں آئے تو بول اٹھا کہ میں یقین کرتا ہوں کہ اللہ ہر چیز پر قادر ہے۔', 'یا نہ دیکھا تو نے اس شخص کو کہ گذرا وہ ایک شہر پر اور وہ گرا پڑا تھا اپنی چھتوں پر بولا کیونکر زندہ کرے گا اس کو اللہ مر گئے پیچھے پھر مردہ رکھا اس شخص کو اللہ نے سو برس پھر اٹھایا اس کو [۴۲۱] کہا تو کتنی دیر یہاں رہا بولا میں رہا ایک دن یا ایک دن سے کچھ کم [۴۲۲] کہا نہیں بلکہ تو رہا سو برس اب دیکھ اپنا کھانا اور پینا سڑ نہیں گیا اور دیکھ اپنے گدھے کو اور ہم نے تجھ کو نمونہ بنانا چاہا لوگوں کے واسطے اور دیکھ ہڈیوں کی طرف کہ ہم ان کو کس طرح ابھار کر جوڑ دیتےہیں پھر ان پر پہناتے ہیں گوشت [۴۲۳] پھر جب اس پر ظاہر ہوا یہ حال تو کہہ اٹھا کہ مجھ کو معلوم ہے کہ بیشک اللہ ہر چیز پر قادر ہے [۴۲۴]', 'Or like the one who passed by a town and it had tumbled over its roofs. He said: \"Oh! How will Allah ever bring it to life after its death?\" So Allah caused him to die for a hundred years, then raised him up (again). He said: \"How long did you remain (dead)?\" He (the man) said: \"(Perhaps) I remained (dead) a day or part of a day\". He said: \"Nay, you have remained (dead) for a hundred years, look at your food and your drink, they show no change; and look at your donkey! And thus We have made of you a sign for the people. Look at the bones, how We bring them together and clothe them with flesh\". When this was clearly shown to him, he said, \"I know (now) that Allah is Able to do all things.\"', 'Or, (do you not know) the example of the one who passed through a town that had collapsed on its roofs. He said: “How shall Allah revive this after it is dead?” So, Allah made him dead for a hundred years, then raised him saying: “How long did you remain (in this state)?” He said: “I remained for a day or part of a day”. Said He: “Rather, you remained (dead) for a hundred years. Just look at your food and your drink; it has not spoiled. Now look at your donkey. (We did) this to make you a sign for people! Look at the bones, how We raise them, then dress them with flesh.” So, when it was clear to him, he said: “I know that Allah is Powerful over everything.”'),
(267, 2, 260, 35, 3, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'وَ اِذۡ قَالَ اِبۡرٰہٖمُ  رَبِّ اَرِنِیۡ  کَیۡفَ تُحۡیِ الۡمَوۡتٰی ؕ  قَالَ اَوَ لَمۡ تُؤۡمِنۡ ؕ قَالَ بَلٰی وَ لٰکِنۡ لِّیَطۡمَئِنَّ قَلۡبِیۡ ؕ قَالَ فَخُذۡ اَرۡبَعَۃً مِّنَ الطَّیۡرِ فَصُرۡہُنَّ اِلَیۡکَ ثُمَّ اجۡعَلۡ عَلٰی کُلِّ جَبَلٍ مِّنۡہُنَّ جُزۡءًا ثُمَّ ادۡعُہُنَّ یَاۡتِیۡنَکَ سَعۡیًا ؕ وَ اعۡلَمۡ اَنَّ اللّٰہَ عَزِیۡزٌ  حَکِیۡمٌ ﴿۲۶۰﴾٪', 'اور جب ابراہیم نے اللہ سے عرض کیا کہ اے پروردگار مجھے دکھا کہ تو مردوں کو کیونکر زندہ کرے گا۔ اللہ نے فرمایا کیا تم نے اس بات کا یقین نہیں کیا۔ انہوں نے کہا کیوں نہیں لیکن میں دیکھنا اس لئے چاہتا ہوں کہ میرا دل اطمینان کامل حاصل کر لے فرمایا کہ چار پرندے لے لو پھر انکو اپنے سے ہلا لو اور انکے ٹکڑے ٹکڑے کر دو پھر ان کا ایک ایک ٹکڑا ہر ایک پہاڑ پر رکھ دو پھر ان کو بلاؤ تو وہ تمہارے پاس دوڑتے چلے آئیں گے اور جان رکھو کہ اللہ غالب ہے صاحب حکمت ہے۔', 'اور یاد کر جب کہا ابراہیم نے اے پروردگار میرے دکھلا دے مجھ کو کہ کیونکر زندہ کرے گا تو مردے فرمایا کیا تو نے یقین نہیں کیا کہا کیوں نہیں لیکن اس واسطے چاہتا ہوں کہ تسکین ہو جاوے میرے دل کو [۴۲۵] فرمایا تو پکڑ لے چار جانور اڑنے والے پھر انکو ہلا لے اپنے ساتھ پھر رکھ دے ہر پہاڑ پر ان کے بدن کا ایک ایک ٹکڑا پھر ان کو بلا چلے آویں گے تیرے پاس دوڑتے [۴۲۶] اور جان لے کہ بیشک اللہ زبردست ہے حکمت والا [۴۲۷]', 'And (remember) when Ibrahim (Abraham) said, \"My Lord! Show me how You give life to the dead.\" He (Allah) said: \"Do you not believe?\" He (Ibrahim (Abraham)) said: \"Yes (I believe), but to be stronger in Faith.\" He said: \"Take four birds, then cause them to incline towards you (then slaughter them, cut them into pieces), and then put a portion of them on every hill, and call them, they will come to you in haste. And know that Allah is All-Mighty, All-Wise.\"', '(Remember) when Ibrāhīm said: “My Lord, show me how You give life to the dead.” He said: “Is it that you do not believe?’’ He said: “Of course, I do, but it is just to make my heart at peace.’’ He said: “Then take four birds and tame them to your call, then put on every mountain a part from them, then give them a call, and they shall come to you rushing, and know that Allah is Mighty, Wise.’’'),
(268, 2, 261, 36, 4, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'مَثَلُ الَّذِیۡنَ یُنۡفِقُوۡنَ اَمۡوَالَہُمۡ فِیۡ سَبِیۡلِ اللّٰہِ کَمَثَلِ حَبَّۃٍ اَنۡۢبَتَتۡ سَبۡعَ سَنَابِلَ فِیۡ کُلِّ سُنۡۢبُلَۃٍ مِّائَۃُ حَبَّۃٍ ؕ وَ اللّٰہُ یُضٰعِفُ لِمَنۡ یَّشَآءُ ؕ وَ اللّٰہُ  وَاسِعٌ عَلِیۡمٌ ﴿۲۶۱﴾', 'جو لوگ اپنا مال اللہ کی راہ میں خرچ کرتے ہیں ان کے مال کی مثال اس دانے کی سی ہے جس سے سات بالیں اگیں اور ہر ایک بال میں سو سو دانے ہوں۔ اور اللہ جسکے اجر کو چاہتا ہے اور زیادہ کرتا ہے اور اللہ کشائش والا ہے سب کچھ جاننے والا ہے۔', 'مثال ان لوگوں کی جو خرچ کرتے ہیں اپنے مال اللہ کی راہ میں ایسی ہے کہ جیسے ایک دانہ اس سے اگیں سات بالیں ہر بال میں سو سو دانے اور اللہ بڑھاتا ہے جس کے واسطے چاہے اور اللہ بینہایت بخشش کرنے والا ہے سب کچھ جانتا ہے [۴۲۸]', 'The likeness of those who spend their wealth in the Way of Allah, is as the likeness of a grain (of corn); it grows seven ears, and each ear has a hundred grains. Allah gives manifold increase to whom He pleases. And Allah is All-Sufficient for His creatures needs, All-Knower.', 'The example of those who spend in the way of Allah is just like a grain that produced seven ears, each ear having a hundred grains, and Allah multiplies (the reward) for whom He wills. Allah is All-Embracing, All-Knowing.'),
(269, 2, 262, 36, 4, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'اَلَّذِیۡنَ یُنۡفِقُوۡنَ اَمۡوَالَہُمۡ فِیۡ سَبِیۡلِ اللّٰہِ ثُمَّ لَا یُتۡبِعُوۡنَ مَاۤ  اَنۡفَقُوۡا مَنًّا وَّ لَاۤ  اَذًی ۙ لَّہُمۡ اَجۡرُہُمۡ عِنۡدَ رَبِّہِمۡ ۚ وَ لَا خَوۡفٌ عَلَیۡہِمۡ  وَ لَا ہُمۡ  یَحۡزَنُوۡنَ ﴿۲۶۲﴾', 'جو لوگ اپنا مال اللہ کے رستے میں صرف کرتے ہیں پھر اس کے بعد نہ اس خرچ کا کسی پر احسان رکھتے ہیں اور نہ کسی کو تکلیف دیتے ہیں۔ ان کا صلہ ان کے پروردگار کے پاس تیار ہے اور قیامت کے روز نہ ان کو کچھ خوف ہو گا اور نہ وہ غمگین ہوں گے۔', 'جو لوگ خرچ کرتے ہیں اپنے مال اللہ کی راہ میں پھر خرچ کرنے کے بعد نہ احسان رکھتے ہیں اور نہ ستاتے ہیں انہی کے لئے ہے ثواب ان کا اپنے رب کے یہاں اور نہ ڈر ہے ان پر اور نہ غمگین ہوں گے [۴۲۹]', 'Those who spend their wealth in the Cause of Allah, and do not follow up their gifts with reminders of their generosity or with injury, their reward is with their Lord. On them shall be no fear, nor shall they grieve.', 'Those who spend their wealth in the way of Allah, then do not make their spending followed by boasting about favour, or with causing hurt,- they have their reward with their Lord and there is no fear for them nor shall they grieve.'),
(270, 2, 263, 36, 4, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'قَوۡلٌ مَّعۡرُوۡفٌ وَّ مَغۡفِرَۃٌ خَیۡرٌ مِّنۡ صَدَقَۃٍ یَّتۡبَعُہَاۤ  اَذًی ؕ وَ اللّٰہُ غَنِیٌّ حَلِیۡمٌ ﴿۲۶۳﴾', 'جس خیرات دینے کے بعد لینے والے کو ایذا دی جائے اس سے تو نرم بات کہہ دینی اور درگذر کرنا بہتر ہے اور اللہ بے نیاز ہے بردبار ہے۔', 'جواب دینا نرم اور درگذر کرنا بہتر ہے اس خیرات سے جس کے پیچھے ہو ستانا اور اللہ بے پروا ہے نہایت تحمل والا [۴۳۰]', 'Kind words and forgiving of faults are better than Sadaqah (charity) followed by injury. And Allah is Rich (Free of all wants) and He is Most-Forbearing.', 'A graceful word and forgiving is better than charity followed by causing hurt. Allah is All-Independent, Forbearing.'),
(271, 2, 264, 36, 4, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تُبۡطِلُوۡا صَدَقٰتِکُمۡ بِالۡمَنِّ وَ الۡاَذٰی ۙ کَالَّذِیۡ یُنۡفِقُ مَالَہٗ رِئَآءَ النَّاسِ وَ لَا یُؤۡمِنُ بِاللّٰہِ وَ الۡیَوۡمِ الۡاٰخِرِؕ فَمَثَلُہٗ  کَمَثَلِ صَفۡوَانٍ عَلَیۡہِ تُرَابٌ فَاَصَابَہٗ وَابِلٌ فَتَرَکَہٗ صَلۡدًا ؕ لَا  یَقۡدِرُوۡنَ عَلٰی شَیۡءٍ مِّمَّا کَسَبُوۡا ؕ وَ اللّٰہُ  لَا یَہۡدِی الۡقَوۡمَ الۡکٰفِرِیۡنَ ﴿۲۶۴﴾', 'مومنو! اپنے صدقات و خیرات احسان رکھنے اور ایذا دینے سے اس شخص کی طرح برباد نہ کر دینا جو لوگوں کو دکھاوے کے لئے مال خرچ کرتا ہے اور اللہ اور روز آخر پر ایمان نہیں رکھتا تو اس کے مال کی مثال اس چٹان کی سی ہے جس پر تھوڑی سی مٹی پڑی ہو اور اس پر زور کا مینہ برس کر اسے صاف کر ڈالے۔ اسی طرح یہ ریاکار لوگ اپنے اعمال کا کچھ بھی صلہ حاصل نہیں کر سکیں گے۔ اور اللہ ایسے ناشکروں کو ہدایت نہیں دیا کرتا۔', 'اے ایمان والو مت ضائع کرو اپنی خیرات احسان رکھ کر اور ایذا دے کر اس شخص کی طرح جو خرچ کرتا ہے اپنا مال لوگوں کے دکھانے کو اور یقین نہیں رکھتا ہے اللہ پر اور قیامت کے دن پر [۴۳۱] سو اس کی مثال ایسی ہے جیسے صاف پتھر کہ اس پر پڑی ہے کچھ مٹی پھر برسا اس پر زور کا مینہ تو کر چھوڑا  اس کو بالکل صاف کچھ ہاتھ نہیں لگتا ایسے لوگوں کے ثواب اس چیز کا جو انہوں نےکمایا اور اللہ نہیں دکھاتا سیدھی راہ کافروں کو [۴۳۲]', 'O you who believe! Do not render in vain your Sadaqah (charity) by reminders of your generosity or by injury, like him who spends his wealth to be seen of men, and he does not believe in Allah, nor in the Last Day. His likeness is the likeness of a smooth rock on which is a little dust; on it falls heavy rain which leaves it bare. They are not able to do anything with what they have earned. And Allah does not guide the disbelieving people.', 'O you who believe, do not nullify your acts of charity by boasting about (doing people a) favour and by causing (them) hurt, like the one who spends his wealth to show off before peopleand does not believe in Allah and in the Last Day. So, his example is like a rock on which there is dust, then a heavy rain came over it and left it barren. They have no ability to gain anything out of what they have done, and Allah does not give guidance to the people who disbelieve.'),
(272, 2, 265, 36, 4, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'وَ مَثَلُ الَّذِیۡنَ یُنۡفِقُوۡنَ اَمۡوَالَہُمُ ابۡتِغَآءَ مَرۡضَاتِ اللّٰہِ وَ تَثۡبِیۡتًا مِّنۡ اَنۡفُسِہِمۡ کَمَثَلِ جَنَّۃٍۭ بِرَبۡوَۃٍ اَصَابَہَا وَابِلٌ فَاٰتَتۡ اُکُلَہَا ضِعۡفَیۡنِ ۚ فَاِنۡ لَّمۡ یُصِبۡہَا وَابِلٌ فَطَلٌّ ؕ وَ اللّٰہُ بِمَا تَعۡمَلُوۡنَ  بَصِیۡرٌ ﴿۲۶۵﴾', 'اور جو لوگ اللہ کی خوشنودی حاصل کرنے کے لئے اور خلوص نیت سے اپنا مال خرچ کرتے ہیں ان کی مثال ایک باغ کی سی ہے جو اونچی جگہ پر واقع ہو جب اس پر زور کا مینہ پڑے تو دگنا پھل لائے پھر اگر مینہ نہ بھی پڑے تو خیر پھوار ہی سہی اور اللہ تمہارے کاموں کو دیکھ رہا ہے۔', 'اور مثال ان کی جو خرچ کرتے ہیں اپنے مال اللہ کی خوشی حاصل کرنے کو اور اپنے دلوں کو ثابت کر کر ایسی ہے جیسے ایک باغ ہے بلند زمین پر اس پر پڑا زور کا مینہ تو لایا وہ باغ اپنا پھل دو چند اور اگر نہ پڑا اس پر مینہ تو پھورا ہی کافی ہے اور اللہ تمہارے کاموں کو خوب دیکھتا ہے [۴۳۳]', 'And the likeness of those who spend their wealth seeking Allahs Pleasure while they in their ownselves are sure and certain that Allah will reward them (for their spending in His Cause), is the likeness of a garden on a height; heavy rain falls on it and it doubles its yield of harvest. And if it does not receive heavy rain, light rain suffices it. And Allah is All-Seer of (knows well) what you do.', 'The example of those who spend their wealth to seek the pleasure of Allah and to make firm (their faith) from (the depths of) their souls is like a garden on a foothill on which came a heavy rain, and it yielded its produce twofold. Even if a heavy rain does not come to it, a light drizzle is enough, and Allah is watchful of what you do.'),
(273, 2, 266, 36, 4, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'اَیَوَدُّ اَحَدُکُمۡ اَنۡ تَکُوۡنَ لَہٗ جَنَّۃٌ مِّنۡ نَّخِیۡلٍ وَّ اَعۡنَابٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ ۙ لَہٗ فِیۡہَا مِنۡ کُلِّ الثَّمَرٰتِ ۙ وَ اَصَابَہُ الۡکِبَرُ وَ لَہٗ ذُرِّیَّۃٌ ضُعَفَآءُ ۪ۖ فَاَصَابَہَاۤ اِعۡصَارٌ فِیۡہِ نَارٌ فَاحۡتَرَقَتۡ ؕ  کَذٰلِکَ یُبَیِّنُ اللّٰہُ لَکُمُ الۡاٰیٰتِ لَعَلَّکُمۡ تَتَفَکَّرُوۡنَ ﴿۲۶۶﴾٪', 'بھلا تم میں کوئی یہ چاہتا ہے کہ اس کا کھجوروں اور انگوروں کا باغ ہو جس میں نہریں بہ رہی ہوں اور اس میں اس کے لئے ہر قسم کے میوے موجود ہوں اور اسے بڑھاپا آ پکڑے اور اس کے ننّھے ننّھے بچے بھی ہوں تو ناگہاں اس باغ پر آگ کا بھرا ہوا بگولا چلے پس وہ جل جائے اس طرح اللہ تم سے اپنی آیتیں کھول کھول کر بیان فرماتا ہے تا کہ تم سوچو اور سمجھو۔', 'کیا پسند آتا ہے تم میں سے کسی کو یہ کہ ہووے اس کا ایک باغ کھجور اور انگور کا بہتی ہوں نیچے اس کے نہریں اس کو اس باغ میں اور بھی سب طرح کا میوہ حاصل ہو اور آ گیا اس پر بڑھاپا اور اس کی اولاد ہیں ضعیف تب آ پڑا اس باغ پر ایک بگولا جس میں آگ تھی جس سے وہ باغ جل گیا یوں سمجھاتا ہے تم کو اللہ آیتیں تاکہ تم غور کرو [۴۳۴]', 'Would any of you wish to have a garden with date-palms and vines, with rivers flowing underneath, and all kinds of fruits for him therein, while he is striken with old age, and his children are weak (not able to look after themselves), then it is struck with a fiery whirlwind, so that it is burnt? Thus does Allah make clear His Ayat (proofs, evidences, verses) to you that you may give thought.', 'Would any of you wish to have a garden of dates and grapes, with rivers flowing beneath it, in which there are all kinds of fruit for him, and old age befalls him, and he has children who are (too) weak (to earn livelihood), then a whirlwind comes upon it with fire in it, and it is all burnt? This is how Allah makes the signs clear to you, so that you may ponder.'),
(274, 2, 267, 37, 5, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اَنۡفِقُوۡا مِنۡ طَیِّبٰتِ مَا کَسَبۡتُمۡ وَ مِمَّاۤ اَخۡرَجۡنَا لَکُمۡ مِّنَ الۡاَرۡضِ ۪ وَ لَا تَیَمَّمُوا الۡخَبِیۡثَ مِنۡہُ تُنۡفِقُوۡنَ وَ لَسۡتُمۡ بِاٰخِذِیۡہِ اِلَّاۤ اَنۡ تُغۡمِضُوۡا فِیۡہِ ؕ وَ اعۡلَمُوۡۤا  اَنَّ اللّٰہَ غَنِیٌّ حَمِیۡدٌ ﴿۲۶۷﴾', 'مومنو! جو پاکیزہ اور عمدہ مال تم کماتے ہو اور جو چیزیں ہم تمہارے لئے زمین سے نکالتے ہیں ان میں سے اللہ کی راہ میں بھی خرچ کرو۔ اور بری اور ناپاک چیزیں دینےکا قصد نہ کرنا کہ اگر وہ چیزیں تمہیں دی جائیں تو بجز اس کے کہ لیتے وقت آنکھیں بند کر لو ان کو کبھی نہ لو۔ اور جان رکھو کہ اللہ بے نیاز ہے خوبیوں والا ہے۔', 'اے ایمان والو خرچ کرو ستھری چیزیں اپنی کمائی میں سے اور اس چیز میں سے کہ جو ہم نے پیدا کیا تمہارے واسطے زمین سے اور قصد نہ کرو گندی چیز کا اس میں سے کہ اس کو خرچ کرو حالانکہ تم اس کو کبھی نہ لو گے مگر یہ کہ چشم پوشی کر جاؤ اور جان رکھو کہ اللہ بے پروا ہے خوبیوں والا [۴۳۵]', 'O you who believe! Spend of the good things which you have (legally) earned, and of that which We have produced from the earth for you, and do not aim at that which is bad to spend from it, (though) you would not accept it save if you close your eyes and tolerate therein. And know that Allah is Rich (Free of all wants), and Worthy of all praise.', 'O you who believe, spend of the good things you have earned, and of what We have brought forth for you from the earth, and do not opt for a bad thing, spending only from it, while you are not going to accept it (if such a thing is offered to you), unless you close your eyes to it, and know well that Allah is All-Independent, Ever-Praised.'),
(275, 2, 268, 37, 5, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'اَلشَّیۡطٰنُ یَعِدُکُمُ الۡفَقۡرَ وَ یَاۡمُرُکُمۡ بِالۡفَحۡشَآءِ ۚ وَ اللّٰہُ یَعِدُکُمۡ مَّغۡفِرَۃً مِّنۡہُ  وَ فَضۡلًا ؕ وَ اللّٰہُ وَاسِعٌ عَلِیۡمٌ ﴿۲۶۸﴾ۖۙ', 'شیطان تمہیں تنگدستی کا خوف دلاتا اور بے حیائی کے کام کرنے کو کہتا ہے اور اللہ تم سے اپنی بخشش اور رحمت کا وعدہ کرتا ہے۔ اور اللہ کشائش والا ہے سب کچھ جاننے والا ہے۔', 'شیطان وعدہ دیتا ہے تم کو تنگدستی کا اور حکم کرتا ہے بے حیائی کا اور اللہ وعدہ دیتا ہے تم کو اپنی بخشش اور فضل کا اور اللہ بہت کشائش والا ہے سب کچھ جانتا ہے [۴۳۶]', 'Shaitan (Satan) threatens you with poverty and orders you to commit Fahsha (evil deeds, illegal sexual intercourse, sins etc.); whereas Allah promises you Forgiveness from Himself and Bounty, and Allah is All-Sufficient for His creatures needs, All-Knower.', 'Satan frightens you with poverty, and bids you to commit indecency, and Allah promises you forgiveness from Him, and grace as well. And Allah is All-Embracing, All-Knowing.'),
(276, 2, 269, 37, 5, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'یُّؤۡتِی الۡحِکۡمَۃَ مَنۡ یَّشَآءُ ۚ وَ مَنۡ یُّؤۡتَ الۡحِکۡمَۃَ فَقَدۡ اُوۡتِیَ خَیۡرًا کَثِیۡرًا ؕ وَ مَا یَذَّکَّرُ  اِلَّاۤ  اُولُوا الۡاَلۡبَابِ ﴿۲۶۹﴾', 'وہ جسکو چاہتا ہے دانائی بخشتا ہے اور جسکو دانائی ملی بیشک اسکو بڑی نعمت ملی۔ اور نصیحت تو وہی لوگ قبول کرتے ہیں جو عقلمند ہیں۔', 'عنایت کرتا ہے سمجھ جس کسی کو چاہے اور جس کو سمجھ ملی اس کو بڑی خوبی ملی اور نصیحت وہی قبول کرتے ہیں جو عقل والے ہیں [۴۳۷]', 'He grants Hikmah to whom He pleases, and he, to whom Hikmah is granted, is indeed granted abundant good. But none remember (will receive admonition) except men of understanding.', 'He gives wisdom to whom He wills, and whoever is given wisdom is certainly given a lot of good. Only the people of understanding observe the advice.'),
(277, 2, 270, 37, 5, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'وَ مَاۤ اَنۡفَقۡتُمۡ مِّنۡ نَّفَقَۃٍ اَوۡ نَذَرۡتُمۡ مِّنۡ نَّذۡرٍ فَاِنَّ اللّٰہَ یَعۡلَمُہٗ ؕ وَ مَا لِلظّٰلِمِیۡنَ مِنۡ  اَنۡصَارٍ ﴿۲۷۰﴾', 'اور تم اللہ کی راہ میں جس طرح کا خرچ کرو یا کوئی نذر مانو۔ اللہ اس کو جانتا ہے اور ظالموں کا کوئی مددگار نہ ہو گا۔', 'اور جو خرچ کرو گے تم خیرات یا قبول کرو گے کو ئی منت تو بیشک اللہ کو سب معلوم ہے اور ظالموں کا کوئی مدگار نہیں [۴۳۸]', 'And whatever you spend for spendings (e.g., in Sadaqah - charity, etc. for Allahs Cause) or whatever vow you make, be sure Allah knows it all. And for the Zalimoon (wrong-doers, etc.) there are no helpers.', 'Whatever expenditure you spend and whatever vow you make, Allah knows all of it, and for the unjust, there are no supporters.'),
(278, 2, 271, 37, 5, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'اِنۡ تُبۡدُوا الصَّدَقٰتِ فَنِعِمَّا ہِیَ ۚ وَ اِنۡ تُخۡفُوۡہَا وَ تُؤۡتُوۡہَا الۡفُقَرَآءَ فَہُوَ خَیۡرٌ لَّکُمۡ ؕ وَ یُکَفِّرُ عَنۡکُمۡ مِّنۡ سَیِّاٰتِکُمۡ ؕ وَ اللّٰہُ بِمَا تَعۡمَلُوۡنَ خَبِیۡرٌ ﴿۲۷۱﴾', 'اگر تم خیرات ظاہر کر کے دو تو وہ بھی خوب ہے اور اگر پوشیدہ دو اور دو بھی ضرورت مندوں کو تو یہ تمہارے لئے بہتر ہے اور اس طرح کا دینا تمہارے گناہوں کو بھی دور کرے گا۔ اور اللہ کو تمہارے سب کاموں کی خبر ہے۔', 'اگر ظاہر کر کے دو خیرات تو کیا اچھی بات اور اگر اس کو چھپاؤ اور فقیروں کو پہنچاؤ تو وہ بہتر ہے تمہارے حق میں اور دور کرے گا کچھ گناہ تمہارے اور اللہ تمہارے کاموں سے خوب خبردار ہے [۴۳۹]', 'If you disclose your Sadaqat (alms-giving), it is well, but if you conceal it, and give it to the poor, that is better for you. (Allah) will forgive you some of your sins. And Allah is Well-Acquainted with what you do.', 'If you make Sadaqāt (alms) openly, it is good enough, and if you keep it secret and give it to the needy, it is much better for you, and this will write off part of your sins. Allah is All-Aware of what you do.'),
(279, 2, 272, 37, 5, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'لَیۡسَ عَلَیۡکَ ہُدٰىہُمۡ وَ لٰکِنَّ اللّٰہَ یَہۡدِیۡ مَنۡ یَّشَآءُ ؕ وَ مَا تُنۡفِقُوۡا مِنۡ خَیۡرٍ فَلِاَنۡفُسِکُمۡ ؕ وَ مَا تُنۡفِقُوۡنَ اِلَّا ابۡتِغَآءَ وَجۡہِ اللّٰہِ ؕ وَ مَا تُنۡفِقُوۡا مِنۡ خَیۡرٍ یُّوَفَّ اِلَیۡکُمۡ وَ اَنۡتُمۡ لَا تُظۡلَمُوۡنَ ﴿۲۷۲﴾', 'اے نبی ﷺ تم ان لوگوں کی ہدایت کے ذمہ دار نہیں ہو بلکہ اللہ ہی جسکو چاہتا ہے ہدایت بخشتا ہے۔ اور مومنو! تم جو مال خرچ کرو گے تو اس کا فائدہ تمہی کو ہے۔ اور تم تو جو خرچ کرو گے اللہ کی خوشنودی کے لئے کرو گے۔ اور جو مال تم خرچ کرو گے وہ تمہیں پورا پورا دے دیا جائے گا۔ اور تمہارا کچھ نقصان نہیں کیا جائے گا۔', 'تیرا ذمہ نہیں انکو راہ پر لانا اور لیکن اللہ راہ پر لاوے جس کو چاہے اور جو کچھ خرچ کرو گے تم مال سو اپنے ہی واسطے جب تک کہ خرچ کرو گے اللہ ہی کی رضاجوئی میں اور جو کچھ خرچ کرو گے خیرات سو پوری ملے  گی تم کو اور تمہارا حق نہ رہے گا [۴۴۰]', 'Not upon you (Muhammad SAW) is their guidance, but Allah guides whom He wills. And whatever you spend in good, it is for yourselves, when you spend not except seeking Allahs Countenance. And whatever you spend in good, it will be repaid to you in full, and you shall not be wronged.', 'It is not for you to put them on the right path. Rather, Allah puts on the right path whom He wills. Whatever good you spend is for your own selves, and you shall not spend but to seek the pleasure of Allah, and whatever good thing you spend shall be repaid to you in full, and you shall not be wronged.'),
(280, 2, 273, 37, 5, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'لِلۡفُقَرَآءِ الَّذِیۡنَ اُحۡصِرُوۡا فِیۡ سَبِیۡلِ اللّٰہِ لَا یَسۡتَطِیۡعُوۡنَ ضَرۡبًا فِی الۡاَرۡضِ ۫ یَحۡسَبُہُمُ الۡجَاہِلُ اَغۡنِیَآءَ مِنَ التَّعَفُّفِ ۚ تَعۡرِفُہُمۡ بِسِیۡمٰہُمۡ ۚ لَا یَسۡـَٔلُوۡنَ النَّاسَ اِلۡحَافًا ؕ وَ مَا تُنۡفِقُوۡا مِنۡ خَیۡرٍ فَاِنَّ اللّٰہَ بِہٖ عَلِیۡمٌ ﴿۲۷۳﴾٪', 'اور ہاں تم جو خرچ کرو گے تو ان حاجت مندوں کے لئے جو اللہ کی راہ میں رکے بیٹھے ہیں اور ملک میں کسی طرف جانے کی طاقت نہیں رکھتے اور مانگنے سے عار رکھتے ہیں یہاں تک کہ نہ مانگنے کی وجہ سے ناواقف شخص ان کو تونگر خیال کرتا ہے اور تم قیافے سے ان کو صاف پہچان لو کہ حاجت مند ہیں اور شرم کے سبب لوگوں سے منہ پھوڑ کر اور لپٹ کر نہیں مانگ سکتے اور تم جو مال خرچ کرو گے کچھ شک نہیں کہ اللہ اسکو جانتا ہے۔', 'خیرات ان فقیروں کے لئے ہے جو رکے ہوئے ہیں اللہ کی راہ میں چل پھر نہیں سکتے ملک میں سمجھے ان کو ناواقف مالدار ان کے سوال نہ کرنے سے تو پہچانتا ہے ان کو انکے چہرہ سے نہیں سوال کرتے لوگوں سے لپٹ کر [۴۴۱] اور جو کچھ خرچ کرو گے کام کی چیز وہ بیشک اللہ کو معلوم ہے [۴۴۲]', '(Charity is) for Fuqara (the poor), who in Allahs Cause are restricted (from travel), and cannot move about in the land (for trade or work). The one who knows them not, thinks that they are rich because of their modesty. You may know them by their mark, they do not beg of people at all. And whatever you spend in good, surely Allah knows it well.', '(Your charities should be preferably meant) for the needy who are confined in the way of Allah, unable to travel in the land.An ignorant person takes them as free of need because of their abstinence. You know them by their appearance (from begging). They do not beg people importunately, and whatever good thing you spend, Allah is All-Aware of it.'),
(281, 2, 274, 38, 6, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'اَلَّذِیۡنَ یُنۡفِقُوۡنَ اَمۡوَالَہُمۡ بِالَّیۡلِ وَ النَّہَارِ سِرًّا وَّ عَلَانِیَۃً فَلَہُمۡ اَجۡرُہُمۡ عِنۡدَ رَبِّہِمۡ ۚ وَ لَا خَوۡفٌ عَلَیۡہِمۡ وَ لَا ہُمۡ یَحۡزَنُوۡنَ ﴿۲۷۴﴾ؔ', 'جو لوگ اپنا مال رات اور دن اور پوشیدہ اور ظاہر اللہ کی راہ میں خرچ کرتے رہتے ہیں ان کا صلہ انکے پروردگار کے پاس ہے۔ اور ان کو قیامت کے دن نہ کسی طرح کا خوف ہو گا اور نہ غم۔', 'جو لوگ خرچ کرتے ہیں اپنے مال اللہ کی راہ میں رات کو اور دن کو چھپا کر اور ظاہر میں تو انکے لئے ہے ثواب ان کا اپنے رب کے پاس اور نہ ڈر ہے ان پر اور نہ وہ غمگین ہوں گے [۴۴۳]', 'Those who spend their wealth (in Allahs Cause) by night and day, in secret and in public, they shall have their reward with their Lord. On them shall be no fear, nor shall they grieve.', 'Those who spend their wealth night and day, secretly and openly,- they have their reward with their Lord, and there is no fear for them, nor shall they grieve.'),
(282, 2, 275, 38, 6, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'اَلَّذِیۡنَ یَاۡکُلُوۡنَ الرِّبٰوا لَا یَقُوۡمُوۡنَ اِلَّا کَمَا یَقُوۡمُ الَّذِیۡ یَتَخَبَّطُہُ الشَّیۡطٰنُ مِنَ الۡمَسِّ ؕ ذٰلِکَ بِاَنَّہُمۡ قَالُوۡۤا اِنَّمَا الۡبَیۡعُ مِثۡلُ الرِّبٰوا ۘ وَ اَحَلَّ اللّٰہُ الۡبَیۡعَ وَ حَرَّمَ الرِّبٰوا ؕ فَمَنۡ جَآءَہٗ مَوۡعِظَۃٌ مِّنۡ رَّبِّہٖ فَانۡتَہٰی فَلَہٗ مَا سَلَفَ ؕ وَ اَمۡرُہٗۤ اِلَی اللّٰہِ ؕ وَ مَنۡ عَادَ فَاُولٰٓئِکَ اَصۡحٰبُ النَّارِ ۚ ہُمۡ فِیۡہَا خٰلِدُوۡنَ ﴿۲۷۵﴾', 'جو لوگ سود کھاتے ہیں وہ قبروں سے اس طرح حواس باختہ اٹھیں گے جیسے کسی کو جن نے لپٹ کر دیوانہ بنا دیا ہو۔ یہ اس لئے کہ وہ کہتے ہیں کہ سودا بیچنا بھی تو نفع کے لحاظ سے ویسا ہی ہے جیسے سود لینا حالانکہ سودے کو اللہ نے حلال کیا ہے اور سود کو حرام تو جس شخص کے پاس اللہ کی نصیحت پہنچی اور وہ سود لینے سے باز آگیا تو جو پہلے ہو چکا وہ اس کا۔ اور قیامت میں اس کا معاملہ اللہ کے سپرد۔ اور جو پھر لینے لگا تو ایسے لوگ دوزخی ہیں کہ ہمیشہ دوزخ میں جلتے رہیں گے۔', 'جو لوگ کھاتےہیں سود نہیں اٹھیں گے قیامت کو مگر جس طرح اٹھتا ہے وہ شخص کہ جس کے حواس کھو دیے ہوں جن نے لپٹ کر یہ حالت انکی اس واسطے ہو گی کہ انہوں نے کہا کہ سوداگری  بھی تو ایسی ہی ہے جیسے سود لینا حالانکہ اللہ نے حلال کیا ہے سوداگری اور حرام کیا ہے سود کو [۴۴۴] پھر جس کو پہنچی نصیحت اپنے رب کی طرف سے اور وہ باز آ گیا تو اس کے واسطے ہے جو پہلے ہو چکا اور معاملہ اس کا اللہ کے حوالہ ہے اور جو کوئی پھر سود لیوے تو وہی لوگ ہیں دوزخ والے وہ اس میں ہمیشہ رہیں گے [۴۴۵]', 'Those who eat Riba (usury) will not stand (on the Day of Resurrection) except like the standing of a person beaten by Shaitan (Satan) leading him to insanity. That is because they say: \"Trading is only like Riba (usury),\" whereas Allah has permitted trading and forbidden Riba (usury). So whosoever receives an admonition from his Lord and stops eating Riba (usury) shall not be punished for the past; his case is for Allah (to judge); but whoever returns (to Riba (usury)), such are the dwellers of the Fire - they will abide therein.', 'Those who take ribā (usury or interest) will not stand but as stands the one whom the demon has driven crazy by his touch. That is because they have said: “Sale is but like ribā.’’, while Allah has permitted sale, and prohibited ribā. So, whoever receives an advice from his Lord and desists (from indulging in ribā), then what has passed is allowed for him, and his matter is up to Allah. As for the ones who revert back, those are the people of Fire. There they will remain forever.'),
(283, 2, 276, 38, 6, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'یَمۡحَقُ اللّٰہُ الرِّبٰوا وَ یُرۡبِی الصَّدَقٰتِ ؕ وَ اللّٰہُ  لَا یُحِبُّ کُلَّ  کَفَّارٍ اَثِیۡمٍ ﴿۲۷۶﴾', 'اللہ سود کو نابود یعنی بے برکت کرتا اور خیرات کی برکت کو بڑھاتا ہے اور اللہ کسی ناشکرے گناہگار کو دوست نہیں رکھتا۔', 'مٹاتا ہے اللہ سود کو اور بڑھاتا ہے خیرات کو [۴۴۶] اور اللہ خوش نہیں کسی نا شکر گنہگار سے [۴۴۷]', 'Allah will destroy Riba (usury) and will give increase for Sadaqat (deeds of charity, alms, etc.) And Allah likes not the disbelievers, sinners.', 'Allah destroys ribā and nourishes charities, and Allah does not like any sinful disbeliever.'),
(284, 2, 277, 38, 6, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'اِنَّ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ وَ اَقَامُوا الصَّلٰوۃَ وَ اٰتَوُا الزَّکٰوۃَ لَہُمۡ اَجۡرُہُمۡ عِنۡدَ رَبِّہِمۡ ۚ وَ لَا خَوۡفٌ عَلَیۡہِمۡ وَ لَا ہُمۡ  یَحۡزَنُوۡنَ ﴿۲۷۷﴾', 'جو لوگ ایمان لائے اور نیک عمل کرتے اور نماز پڑھتے اور زکوٰۃ دیتے رہے ان کو ان کے کاموں کا صلہ اللہ کے ہاں ملے گا اور قیامت کے دن ان کو نہ کچھ خوف ہو گا اور نہ وہ غمناک ہوں گے۔', 'جو لوگ ایمان لائے اور عمل نیک کئے اور قائم رکھا نماز کو اور دیتے رہے زکوٰۃ انکے لئے ہے ثواب ان  کا اپنے رب کے پاس اور نہ ان کو خوف ہے اور نہ وہ غمگین ہوں گے [۴۴۸]', 'Truly those who believe, and do deeds of righteousness, and perform As-Salat (Iqamat-as-Salat), and give Zakat, they will have their reward with their Lord. On them shall be no fear, nor shall they grieve.', 'Surely those who believe and do good deeds, and establish Salāh (prayer) and pay Zakāh will have their reward with their Lord, and there is no fear for them, nor shall they grieve.'),
(285, 2, 278, 38, 6, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوا اتَّقُوا اللّٰہَ وَ ذَرُوۡا مَا بَقِیَ مِنَ الرِّبٰۤوا اِنۡ کُنۡتُمۡ مُّؤۡمِنِیۡنَ ﴿۲۷۸﴾', 'مومنو! اللہ سے ڈرو اور اگر ایمان رکھتے ہو تو جتنا سود باقی رہ گیا ہے اس کو چھوڑ دو۔', 'اے ایمان والو ڈرو اللہ سے اور چھوڑ دو جو کچھ باقی رہ گیا ہے سود اگر تم کو یقین ہے اللہ کے فرمانے کا [۴۴۹]', 'O you who believe! Be afraid of Allah and give up what remains (due to you) from Riba (usury) (from now onward), if you are (really) believers.', 'O you who believe, fear Allah and give up what still remains of ribā, if you are believers.'),
(286, 2, 279, 38, 6, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'فَاِنۡ لَّمۡ تَفۡعَلُوۡا فَاۡذَنُوۡا بِحَرۡبٍ مِّنَ اللّٰہِ وَ رَسُوۡلِہٖ ۚ وَ  اِنۡ تُبۡتُمۡ  فَلَکُمۡ رُءُوۡسُ اَمۡوَالِکُمۡ ۚ لَا تَظۡلِمُوۡنَ وَ لَا تُظۡلَمُوۡنَ ﴿۲۷۹﴾', 'پھر اگر ایسا نہ کرو گے تو تم اللہ اور اسکے رسول کی طرف سے اعلان جنگ سن لو اور اگر توبہ کر لو گے اور سود چھوڑ دو گے تو تم کو اپنی اصل رقم لینے کا حق ہے جس میں نہ اوروں کا نقصان اور نہ تمہارا نقصان۔', 'پھر اگر نہیں چھوڑتے تو تیار ہو جاؤ لڑنے کو اللہ سے اور اس کے رسول سے اور اگر توبہ کرتے ہو تو تمہارے واسطے ہے اصل مال تمہارا نہ تم کسی پر ظلم کرو اور نہ کوئی تم پر [۴۵۰]', 'And if you do not do it, then take a notice of war from Allah and His Messenger but if you repent, you shall have your capital sums. Deal not unjustly (by asking more than your capital sums), and you shall not be dealt with unjustly (by receiving less than your capital sums).', 'But if you do not (give it up), then listen to the declaration of war from Allah and His Messenger. However, If you repent, yours is your principal. Neither wrong, nor be wronged.'),
(287, 2, 280, 38, 6, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'وَ اِنۡ کَانَ ذُوۡ عُسۡرَۃٍ فَنَظِرَۃٌ اِلٰی مَیۡسَرَۃٍ ؕ وَ اَنۡ تَصَدَّقُوۡا خَیۡرٌ لَّکُمۡ اِنۡ  کُنۡتُمۡ تَعۡلَمُوۡنَ ﴿۲۸۰﴾', 'اور اگر قرض لینے والا تنگدست ہو تو اسے کشائش کے حاصل ہونے تک مہلت دو اور اگر زر قرض بخش دو تو وہ تمہارے لئے زیادہ اچھا ہے بشرطیکہ سمجھو۔', 'اور اگر ہے تنگدست تو مہلت دینی چاہیئے کشائش ہونے تک اور بخش دو تو بہت بہتر ہے تمہارے لئے اگر تم کو سمجھ ہو [۴۵۱]', 'And if the debtor is in a hard time (has no money), then grant him time till it is easy for him to repay, but if you remit it by way of charity, that is better for you if you did but know.', 'If there is one in misery, then (the creditor should allow) deferment till (his) ease, and that you forgo it as alms is much better for you, if you really know.'),
(288, 2, 281, 38, 6, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'وَ اتَّقُوۡا یَوۡمًا تُرۡجَعُوۡنَ فِیۡہِ  اِلَی اللّٰہِ ٭۟ ثُمَّ تُوَفّٰی کُلُّ نَفۡسٍ مَّا کَسَبَتۡ وَ ہُمۡ لَا  یُظۡلَمُوۡنَ ﴿۲۸۱﴾٪', 'اور اس دن سے ڈرو جبکہ تم اللہ کے حضور میں لوٹ کر جاؤ گے اور ہر شخص اپنے اعمال کا پورا پورا بدلہ پائے گا اور کسی کو کچھ نقصان نہ ہو گا۔', 'اور ڈرتے رہو اس دن سے کہ جس دن لوٹائے جاؤ گے اللہ کی طرف پھر پورا دیا جائے گا ہر شخص کو جو کچھ اس نےکمایا اور ان پر ظلم نہ ہو گا [۴۵۲]', 'And be afraid of the Day when you shall be brought back to Allah. Then every person shall be paid what he earned, and they shall not be dealt with unjustly.', 'Be fearful of a day when you shall be returned to Allah, then every person shall be paid, in full, what he has earned, and they shall not be wronged.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(289, 2, 282, 39, 7, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اِذَا تَدَایَنۡتُمۡ بِدَیۡنٍ اِلٰۤی اَجَلٍ مُّسَمًّی فَاکۡتُبُوۡہُ ؕ وَ لۡیَکۡتُبۡ بَّیۡنَکُمۡ کَاتِبٌۢ بِالۡعَدۡلِ ۪ وَ لَا یَاۡبَ کَاتِبٌ اَنۡ یَّکۡتُبَ کَمَا عَلَّمَہُ اللّٰہُ فَلۡیَکۡتُبۡ ۚ وَ لۡیُمۡلِلِ الَّذِیۡ عَلَیۡہِ الۡحَقُّ وَ لۡیَتَّقِ اللّٰہَ رَبَّہٗ وَ لَا یَبۡخَسۡ مِنۡہُ شَیۡئًا ؕ فَاِنۡ کَانَ الَّذِیۡ عَلَیۡہِ الۡحَقُّ سَفِیۡہًا اَوۡ ضَعِیۡفًا اَوۡ لَا یَسۡتَطِیۡعُ اَنۡ یُّمِلَّ ہُوَ  فَلۡیُمۡلِلۡ وَلِیُّہٗ بِالۡعَدۡلِ ؕ وَ اسۡتَشۡہِدُوۡا شَہِیۡدَیۡنِ مِنۡ رِّجَالِکُمۡ ۚ فَاِنۡ لَّمۡ یَکُوۡنَا رَجُلَیۡنِ فَرَجُلٌ وَّ امۡرَاَتٰنِ مِمَّنۡ تَرۡضَوۡنَ مِنَ الشُّہَدَآءِ اَنۡ تَضِلَّ اِحۡدٰىہُمَا فَتُذَکِّرَ اِحۡدٰىہُمَا الۡاُخۡرٰی ؕ وَ لَا یَاۡبَ الشُّہَدَآءُ اِذَا مَا دُعُوۡا ؕ وَ لَا تَسۡـَٔمُوۡۤا اَنۡ تَکۡتُبُوۡہُ صَغِیۡرًا اَوۡ کَبِیۡرًا اِلٰۤی اَجَلِہٖ ؕ ذٰلِکُمۡ اَقۡسَطُ عِنۡدَ اللّٰہِ وَ اَقۡوَمُ لِلشَّہَادَۃِ وَ اَدۡنٰۤی اَلَّا تَرۡتَابُوۡۤا اِلَّاۤ اَنۡ تَکُوۡنَ تِجَارَۃً حَاضِرَۃً  تُدِیۡرُوۡنَہَا بَیۡنَکُمۡ فَلَیۡسَ عَلَیۡکُمۡ جُنَاحٌ اَلَّا تَکۡتُبُوۡہَا ؕ وَ اَشۡہِدُوۡۤا اِذَا تَبَایَعۡتُمۡ ۪ وَ لَا یُضَآرَّ کَاتِبٌ وَّ لَا شَہِیۡدٌ ۬ؕ وَ  اِنۡ تَفۡعَلُوۡا فَاِنَّہٗ فُسُوۡقٌۢ بِکُمۡ ؕ وَ اتَّقُوا اللّٰہَ ؕ وَ یُعَلِّمُکُمُ اللّٰہُ ؕ وَ اللّٰہُ بِکُلِّ شَیۡءٍ  عَلِیۡمٌ ﴿۲۸۲﴾', 'مومنو! جب تم آپس میں کسی معیاد معین کے لئے قرض کا معاملہ کرنے لگو تو اسکو لکھ لیا کرو اور لکھنے والا تم میں کسی کا نقصان نہ کرے بلکہ انصاف سے لکھے نیز لکھنے والا جیسا اللہ نے اسے سکھایا ہے لکھنے سے انکار بھی نہ کرے اور دستاویز لکھ دے۔ اور جو شخص قرض لے وہی دستاویز کا مضمون بول کر لکھوائے اور اللہ سے کہ اس کا مالک ہے خوف کرے اور زر قرض میں سے کچھ کم نہ لکھوائے اور اگر قرض لینے والا کم عقل یا ضعیف ہو یا مضمون لکھوانے کی قابلیت نہ رکھتا ہو تو جو اس کا ولی ہو وہ انصاف کے ساتھ مضمون لکھوائے اور اپنے میں سے دو مردوں کو ایسے معاملے کے گواہ کر لیا کرو۔ اور اگر دو مرد نہ ہوں تو ایک مرد اور دو عورتیں جن کو تم گواہ پسند کرو کافی ہیں کہ اگر ان میں سے ایک بھول جائے گی تو دوسری اسے یاد دلا دے گی۔ اور جب گواہ گواہی کے لئے طلب کئے جائیں تو انکار نہ کریں۔ اور قرض تھوڑا ہو یا بہت اس کی دستاویز کے لکھنے لکھانے میں سستی نہ کرنا یہ بات اللہ کے نزدیک نہایت قرین انصاف ہے اور شہادت کے لئے بھی یہ بہت درست طریقہ ہے اس سے تم کو کسی طرح کا شک و شبہ بھی نہیں پڑے گا ہاں اگر سودا دست بدست ہو جو تم آپس میں لیتے دیتے ہو تو اگر ایسے معاملے کی دستاویز نہ لکھو تو تم پر کچھ گناہ نہیں۔ اور جب خرید و فروخت کیا کرو مثلاً زمین جائیداد کی تو بھی گواہ کر لیا کرو۔ اور کاتب دستاویز اور گواہ معاملہ کرنے والوں کا کسی طرح کا نقصان نہ کریں۔ اگر تم لوگ ایسا کرو تو یہ تمہارے لئے گناہ کی بات ہےاور اللہ سے ڈرو اور دیکھو کہ وہ تم کو کیسی مفید باتیں سکھاتا ہے۔ اور اللہ ہر چیز سے واقف ہے۔', 'اے ایمان والو جب تم آپس میں معاملہ کرو ادھار کا کسی وقت مقرر تک تو اس کو لکھ لیا کرو اور چاہئے کہ لکھ دے تمہارے درمیان کوئی لکھنے والا انصاف سے اور انکار نہ کرے لکھنے والا اس سے کہ لکھ دیوے جیسا سکھایا اس کو اللہ نے سو اس کو چاہئے کہ لکھ دے اور بتلاتا جاوے وہ شخص کہ جس پر قرض ہے اور ڈرے اللہ سے جو اس کا رب ہے اور کم نہ کرے اس میں سےکچھ [۴۵۳] پھر اگر وہ شخص کہ جس پر قرض ہے بے عقل ہے یا ضعیف ہے یا آپ نہیں بتلا سکتا تو بتلاوے کارگذار اس کا انصاف سے [۴۵۴] اور گواہ کرو دو شاہد اپنے مردوں میں سے پھر اگر نہ ہوں دو مرد تو ایک مرد اور دو عورتیں ان لوگوں میں سے کہ جن کو تم پسند کرتے ہو گواہوں میں تاکہ اگر بھول جائے ایک ان میں سے تو یاد دلاوے اس کو وہ دوسری [۴۵۵] اور انکار نہ کریں گواہ جس وقت بلائے جاویں اور کاہلی نہ کرو اس کے لکھنے سے چھوٹا ہو معاملہ یا بڑا اس کی میعاد تک اس میں پورا انصاف ہے اللہ کے نزدیک اور بہت درست رکھنے والا ہے گواہی کو اور نزدیک ہے کہ شبہ میں نہ پڑو [۴۵۶] مگر یہ کہ سودا ہو ہاتھوں ہاتھ لیتے دیتے ہو اس کو آپس میں تو تم پر کچھ گناہ نہیں اگر اس کو نہ لکھو اور گواہ کر لیا کرو جب تم سودا کرو اور نقصان نہ کرےلکھنے والا اور نہ گواہ [۴۵۷] اور اگر ایسا کرو تو یہ گناہ کی بات ہے تمہارے اندر اور ڈرتے رہو اللہ سے اور اللہ تم کو سکھلاتا ہے اور اللہ ہر ایک چیز کو جانتا ہے', 'O you who believe! When you contract a debt for a fixed period, write it down. Let a scribe write it down in justice between you. Let not the scribe refuse to write as Allah has taught him, so let him write. Let him (the debtor) who incurs the liability dictate, and he must fear Allah, his Lord, and diminish not anything of what he owes. But if the debtor is of poor understanding, or weak, or is unable himself to dictate, then let his guardian dictate in justice. And get two witnesses out of your own men. And if there are not two men (available), then a man and two women, such as you agree for witnesses, so that if one of them (two women) errs, the other can remind her. And the witnesses should not refuse when they are called on (for evidence). You should not become weary to write it (your contract), whether it be small or big, for its fixed term, that is more just with Allah; more solid as evidence, and more convenient to prevent doubts among yourselves, save when it is a present trade which you carry out on the spot among yourselves, then there is no sin on you if you do not write it down. But take witnesses whenever you make a commercial contract. Let neither scribe nor witness suffer any harm, but if you do (such harm), it would be wickedness in you. So be afraid of Allah; and Allah teaches you. And Allah is the All-Knower of each and everything.', 'O you who believe, when you transact a debt payable at a specified time, put it in writing, and let a scribe write it between you with fairness. A scribe should not refuse to write as Allah has educated him. He, therefore, should write. The one who owes something should get it written, but he must fear Allah, his Lord, and he should not omit anything from it.If the one who owes is feeble-minded or weak or cannot dictate himself, then his guardian should dictate with fairness. Have two witnesses from among your men, and if two men are not there, then one man and two women from those witnesses whom you like, so that if one of the two women errs, the other woman may remind her. The witnesses should not refuse when summoned. And do not be weary of writing it down, along with its due date, no matter whether the debt is small or large. That is more equitable in Allah’s sight, and more supportive as evidence, and more likely to make you free of doubt. However, if it is a spot transaction you are effecting between yourselves, there is no sin on you, should you not write it. Have witnesses when you transact a sale. Neither a scribe should be made to suffer, nor a witness. If you do (something harmful to them), it is certainly a sin on your part, and fear Allah. Allah educates you, and Allah is All-Knowing in respect of everything.'),
(290, 2, 283, 39, 7, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'وَ اِنۡ کُنۡتُمۡ عَلٰی سَفَرٍ وَّ لَمۡ تَجِدُوۡا کَاتِبًا فَرِہٰنٌ مَّقۡبُوۡضَۃٌ ؕ فَاِنۡ اَمِنَ بَعۡضُکُمۡ بَعۡضًا فَلۡیُؤَدِّ الَّذِی اؤۡتُمِنَ اَمَانَتَہٗ وَ لۡیَتَّقِ اللّٰہَ رَبَّہٗ ؕ وَ لَا تَکۡتُمُوا الشَّہَادَۃَ ؕ وَ مَنۡ یَّکۡتُمۡہَا فَاِنَّہٗۤ اٰثِمٌ قَلۡبُہٗ ؕ وَ اللّٰہُ بِمَا تَعۡمَلُوۡنَ عَلِیۡمٌ ﴿۲۸۳﴾٪', 'اور اگر تم سفر پر ہو اور دستاویز لکھنے والا نہ مل سکے تو کوئی چیز رہن با قبضہ رکھ کر قرض لے لو اور اگر تم میں سے کوئی دوسرے کو امین سمجھے یعنی رہن کے بغیر قرض دیدے تو امانتدار کو چاہیے کہ صاحب امانت کی امانت ادا کر دے اور اللہ سے جو اس کا پروردگار ہے ڈرے۔ اور دیکھنا شہادت کو مت چھپانا جو اس کو چھپائے گا وہ دل کا گناہگار ہو گا۔ اور اللہ تمہارے سب کاموں سے واقف ہے۔', 'اور اگر تم سفر میں ہو اور نہ پاؤ کوئی لکھنے والا تو گرو ہاتھ میں رکھنی چاہیئے پھر اگر اعتبار کرے ایک دوسرے کا تو چاہئے کہ پورا ادا کرے وہ شخص کہ جس پر اعتبار کیا اپنی امانت کو اور ڈرتا رہے اللہ سے جو رب ہے اس کا اور مت چھپاؤ گواہی کو اور جو شخص اس کو چھپاوے تو بیشک گنہگار ہے دل اس کا اور اللہ تمہارے کاموں کو خوب جانتا ہے [۴۵۸]', 'And if you are on a journey and cannot find a scribe, then let there be a pledge taken (mortgaging); then if one of you entrust the other, let the one who is entrusted discharge his trust (faithfully), and let him be afraid of Allah, his Lord. And conceal not the evidence for he, who hides it, surely his heart is sinful. And Allah is All-Knower of what you do.', 'If you are on a journey, and find no scribe, then (you may have resort to holding something as) mortgage, taken into possession. However, if one of you trusts the other, then the one who has been trusted should fulfill his trust, and should fear Allah, his Lord. Do not conceal testimony. Whoever conceals it, his heart is surely, sinful. Allah is All-Aware of what you do.'),
(291, 2, 284, 40, 8, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'لِلّٰہِ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ؕ وَ اِنۡ تُبۡدُوۡا مَا فِیۡۤ  اَنۡفُسِکُمۡ اَوۡ تُخۡفُوۡہُ یُحَاسِبۡکُمۡ بِہِ  اللّٰہُ ؕ فَیَغۡفِرُ   لِمَنۡ یَّشَآءُ  وَ یُعَذِّبُ مَنۡ یَّشَآءُ ؕ وَ اللّٰہُ عَلٰی کُلِّ شَیۡءٍ  قَدِیۡرٌ ﴿۲۸۴﴾', 'جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب اللہ ہی کا ہے۔ تم اپنے دلوں کی بات کو ظاہر کرو گے تو اور چھپاؤ گے تو اللہ تم سے اس کا حساب لے گا۔ پھر وہ جسے چاہے مغفرت کرے اور جسے چاہے عذاب دے۔ اور اللہ ہر چیز پر قادر ہے۔', 'اللہ ہی کا ہے جو کچھ کہ آسمانوں اور زمین میں ہے اور اگر ظاہر کرو گے اپنے جی کی بات یا چھپاؤ گے اس کو حساب لے گا اس کا تم سے اللہ پھر بخشے گا جس کو چاہے اور عذاب کرے گا جس کو چاہے اور اللہ ہر چیز پر قادر ہے [۴۵۹]', 'To Allah belongs all that is in the heavens and all that is on the earth, and whether you disclose what is in your ownselves or conceal it, Allah will call you to account for it. Then He forgives whom He wills and punishes whom He wills. And Allah is Able to do all things.', 'To Allah belongs what is in the heavens and what is in the earth. If you disclose what is in your hearts or conceal it, Allah shall hold you accountable for it, then He will forgive whom He wills and punish whom He wills. Allah is powerful over everything.'),
(292, 2, 285, 40, 8, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'اٰمَنَ الرَّسُوۡلُ بِمَاۤ  اُنۡزِلَ اِلَیۡہِ مِنۡ رَّبِّہٖ وَ الۡمُؤۡمِنُوۡنَ ؕ کُلٌّ اٰمَنَ بِاللّٰہِ وَ مَلٰٓئِکَتِہٖ وَ کُتُبِہٖ وَ رُسُلِہٖ ۟ لَا نُفَرِّقُ بَیۡنَ  اَحَدٍ مِّنۡ رُّسُلِہٖ ۟ وَ قَالُوۡا سَمِعۡنَا وَ اَطَعۡنَا ٭۫ غُفۡرَانَکَ رَبَّنَا وَ اِلَیۡکَ الۡمَصِیۡرُ ﴿۲۸۵﴾', 'رسول اللہ ﷺ اس کتاب پر جو ان کے پروردگار کی طرف سے ان پر نازل ہوئی ایمان رکھتے ہیں اور مومن بھی۔ سب اللہ پر اور اس کے فرشتوں پر اور اس کی کتابوں پر اور اس کے پیغمبروں پر ایمان رکھتے ہیں اور کہتے ہیں کہ ہم اس کے پیغمبروں سے کسی میں کچھ فرق نہیں کرتے اور وہ اللہ سے عرض کرتے ہیں کہ ہم نے تیرا حکم سنا اور قبول کیا۔ اے پروردگار ہم تیری بخشش مانگتے ہیں اور تیری ہی طرف لوٹ کر جانا ہے۔', 'مان لیا رسول نے جو کچھ اترا اس پر اس کے رب کی طرف سے اور مسلمانوں نے بھی سب نے مانا اللہ کو اور اس کے فرشتوں کو اور اس کی کتابوں کو اور اس کے رسولوں کو کہتے ہیں کہ ہم جدا نہیں کرتے کسی کو اس کے پیغمبروں میں سے اور کہہ اٹھے کہ ہم نےسنا اور قبول کیا تیری بخشش چاہتے ہیں اے ہمارے رب اور تیری ہی طرف لوٹ کر جانا ہے [۴۶۰]', 'The Messenger (Muhammad SAW) believes in what has been sent down to him from his Lord, and (so do) the believers. Each one believes in Allah, His Angels, His Books, and His Messengers. They say, \"We make no distinction between one another of His Messengers\" - and they say, \"We hear, and we obey. (We seek) Your Forgiveness, our Lord, and to You is the return (of all).\"', 'The Messenger has believed in what has been revealed to him from his Lord, and the believers as well. All have believed in Allah and His angels and His Books and His Messengers. “We make no division between any of His Messengers,” and they have said: “We have listened, and obeyed. Our Lord, (we seek) Your pardon! And to You is the return.”'),
(293, 2, 286, 40, 8, 3, 'تِلۡکَ الرُّسُلُ', 'البقرۃ', 'لَا یُکَلِّفُ اللّٰہُ نَفۡسًا اِلَّا وُسۡعَہَا ؕ لَہَا مَا کَسَبَتۡ وَ عَلَیۡہَا مَا اکۡتَسَبَتۡ ؕ رَبَّنَا لَا تُؤَاخِذۡنَاۤ  اِنۡ نَّسِیۡنَاۤ  اَوۡ اَخۡطَاۡنَا ۚ رَبَّنَا وَ لَا  تَحۡمِلۡ عَلَیۡنَاۤ  اِصۡرًا کَمَا حَمَلۡتَہٗ عَلَی الَّذِیۡنَ مِنۡ قَبۡلِنَا ۚ رَبَّنَا وَ لَا  تُحَمِّلۡنَا مَا لَا طَاقَۃَ لَنَا بِہٖ ۚ وَ اعۡفُ عَنَّا ٝ وَ اغۡفِرۡ لَنَا ٝ وَ ارۡحَمۡنَا ٝ اَنۡتَ مَوۡلٰىنَا فَانۡصُرۡنَا عَلَی الۡقَوۡمِ الۡکٰفِرِیۡنَ ﴿۲۸۶﴾٪', 'اللہ کسی شخص کو اس کی طاقت سے زیادہ کا ذمہ دار نہیں بناتا اچھے کام کرے گا تو اس کو ان کا فائدہ ملے گا برے کرے گا تو اسے انکا نقصان پہنچے گا۔ اے پروردگار اگر ہم سے بھول یا چوک ہو گئ ہو تو ہم سے مواخذہ نہ کیجیو۔ اے پروردگار ہم پر ایسا بوجھ نہ ڈالیو جیسا تو نے ہم سے پہلے لوگوں پر ڈالا تھا۔ اے پروردگار جتنا بوجھ اٹھانے کی ہم میں طاقت نہیں اتنا بوجھ ہم پر نہ رکھیو۔ اور اے پروردگار ہمارے گناہوں سے درگذر کر۔ اور ہمیں بخش دے اور ہم پر رحم فرما۔ تو ہی ہمارا مددگار ہے۔ سو ہم کو کافروں پر غالب کر۔', 'اللہ تکلیف نہیں دیتا کسی کو مگر جس قدر اس کی گنجائش ہے اس کو ملتا ہے جو اس نے کمایا اور اسی پر پڑتا ہے جو اس نے کیا اے رب ہمارے نہ پکڑ ہم کو اگر ہم بھولیں یا چوکیں اے رب ہمارے اور نہ رکھ ہم پر بوجھ بھاری جیسا رکھا تھا ہم سے اگلے لوگوں پر اے رب ہمارے اور نہ اٹھوا ہم سے وہ بوجھ کہ جس کی ہم کو طاقت نہیں اور درگذر کر ہم سے اور بخش ہم کو اور رحم کر ہم پر تو ہی ہمارا رب ہے مدد کر ہماری کافروں پر [۴۶۱]', 'Allah burdens not a person beyond his scope. He gets reward for that (good) which he has earned, and he is punished for that (evil) which he has earned. \"Our Lord! Punish us not if we forget or fall into error, our Lord! Lay not on us a burden like that which You did lay on those before us (Jews and Christians); our Lord! Put not on us a burden greater than we have strength to bear. Pardon us and grant us Forgiveness. Have mercy on us. You are our Maula (Patron, Suppor-ter and Protector, etc.) and give us victory over the disbelieving people.\"', 'Allah does not obligate anyone beyond his capacity. For him is what he has earned, and on him what he has incurred.“Our Lord, do not hold us accountable, if we forget or make a mistake, and, Our Lord, do not place on us such a burden as You have placed on those before us, and, Our Lord, do not make us bear a burden for which we have no strength. And pardon us, and grant us forgiveness, and have mercy on us. You are our Lord. So then help us against the disbelieving people.”'),
(294, 3, 1, 1, 9, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'الٓمَّٓ  ۙ﴿۱﴾', 'الم۔', 'الم', 'Alif-Lam-Meem. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings).', 'Alif. Lām. Mīm.'),
(295, 3, 2, 1, 9, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اللّٰہُ  لَاۤ اِلٰہَ  اِلَّا ہُوَ ۙ الۡحَیُّ الۡقَیُّوۡمُ ؕ﴿۲﴾', 'اللہ جو معبود برحق ہے اس کے سوا کوئی عبادت کے لائق نہیں زندہ ہے سب کو تھامنے والا۔', 'اللہ اس کے سوا کوئی معبود نہیں زندہ ہے سب کا تھامنے والا [۱]', 'Allah! La ilaha illa Huwa (none has the right to be worshipped but He), the Ever Living, the One Who sustains and protects all that exists.', 'Allah: There is no god but He, the Alive, the All-Sustaining.'),
(296, 3, 3, 1, 9, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'نَزَّلَ عَلَیۡکَ الۡکِتٰبَ بِالۡحَقِّ مُصَدِّقًا لِّمَا بَیۡنَ یَدَیۡہِ وَ اَنۡزَلَ التَّوۡرٰىۃَ وَ الۡاِنۡجِیۡلَ ۙ﴿۳﴾', 'اس نے اے نبی تم پر سچی کتاب نازل کی جو پہلی آسمانی کتابوں کی تصدیق کرتی ہے اور اسی نے تورات اور انجیل نازل کی تھی۔', 'اتاری تجھ پر کتاب سچی [۲] تصدیق کرتی ہے اگلی کتابوں کی اور اتارا توریت اور انجیل کو', 'It is He Who has sent down the Book (the Quran) to you (Muhammad SAW) with truth, confirming what came before it. And he sent down the Taurat (Torah) and the Injeel (Gospel).', 'He has revealed to you the Book with the truth, confirming what has been before it, and has sent down the Torah and the Injīl'),
(297, 3, 4, 1, 9, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'مِنۡ قَبۡلُ ہُدًی لِّلنَّاسِ وَ اَنۡزَلَ الۡفُرۡقَانَ ۬ؕ اِنَّ الَّذِیۡنَ کَفَرُوۡا بِاٰیٰتِ اللّٰہِ لَہُمۡ عَذَابٌ شَدِیۡدٌ ؕ وَ اللّٰہُ عَزِیۡزٌ ذُو انۡتِقَامٍ ﴿۴﴾', 'یہ دو کتابیں اس نے پہلے نازل کی تھیں لوگوں کی ہدایت کے لئے اور پھر قرآن جو حق اور باطل کو الگ الگ کر دینے والا ہے نازل کیا۔ جو لوگ اللہ کی آیتوں کا انکار کرتے ہیں انکو سخت عذاب ہو گا۔ اور اللہ زبردست ہے بدلہ لینے والا ہے۔', 'اس کتاب سے پہلے لوگوں کی ہدایت کے لئے [۳] اور اتارے فیصلے [۴] بیشک جو منکر ہوئے اللہ کی آیتوں سے انکے واسطے سخت عذاب ہے اور اللہ زبردست ہے بدلا لینے والا [۵]', 'Aforetime, as a guidance to mankind, And He sent down the criterion (of judgement between right and wrong (this Quran)). Truly, those who disbelieve in the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah, for them there is a severe torment; and Allah is All-Mighty, All-Able of Retribution.', 'earlier to give guidance to mankind, and has sent down the Furqān (the Criterion of right and wrong). Surely, those who have rejected the verses of Allah, for them there is severe punishment. Allah is Mighty, the Lord of Retribution.'),
(298, 3, 5, 1, 9, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اِنَّ اللّٰہَ  لَا  یَخۡفٰی عَلَیۡہِ شَیۡءٌ  فِی الۡاَرۡضِ وَ لَا فِی السَّمَآءِ ؕ﴿۵﴾', 'اللہ ایسا خبیر و بصیر ہے کہ کوئی چیز اس سے پوشیدہ نہیں نہ زمین میں اور نہ آسمان میں۔', 'اللہ پر چھپی نہیں کوئی چیز زمین میں اور نہ آسمان میں [۶]', 'Truly, nothing is hidden from Allah, in the earth or in the heavens.', 'Surely, Allah is such that nothing is hidden from Him, neither in the earth nor in the sky.'),
(299, 3, 6, 1, 9, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'ہُوَ  الَّذِیۡ یُصَوِّرُکُمۡ  فِی الۡاَرۡحَامِ  کَیۡفَ یَشَآءُ ؕ لَاۤ اِلٰہَ  اِلَّا ہُوَ الۡعَزِیۡزُ الۡحَکِیۡمُ ﴿۶﴾', 'وہی تو ہے جو ماں کے پیٹ میں جیسی چاہتا ہے تمہاری صورتیں بناتا ہے۔ اس غالب حکمت والے کے سوا کوئی عبادت کے لائق نہیں۔', 'وہی تمہارا نقشہ بناتا ہے ماں کے پیٹ میں جس طرح چاہے کسی کی بندگی نہیں اسکے سوا زبردست ہے حکمت والا [۷]', 'He it is Who shapes you in the wombs as He pleases. La ilaha illa Huwa (none has the right to be worshipped but He), the All-Mighty, the All-Wise.', 'He is the One Who shapes you in the wombs as He likes. There is no god but He, the Mighty, the Wise.'),
(300, 3, 7, 1, 9, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'ہُوَ الَّذِیۡۤ اَنۡزَلَ عَلَیۡکَ الۡکِتٰبَ مِنۡہُ اٰیٰتٌ مُّحۡکَمٰتٌ ہُنَّ اُمُّ  الۡکِتٰبِ وَ اُخَرُ مُتَشٰبِہٰتٌ ؕ فَاَمَّا الَّذِیۡنَ فِیۡ قُلُوۡبِہِمۡ زَیۡغٌ فَیَتَّبِعُوۡنَ مَا تَشَابَہَ مِنۡہُ ابۡتِغَآءَ الۡفِتۡنَۃِ وَ ابۡتِغَآءَ تَاۡوِیۡلِہٖ ۚ؃ وَ مَا یَعۡلَمُ  تَاۡوِیۡلَہٗۤ  اِلَّا اللّٰہُ  ۘؔ وَ الرّٰسِخُوۡنَ فِی الۡعِلۡمِ یَقُوۡلُوۡنَ اٰمَنَّا بِہٖ ۙ کُلٌّ  مِّنۡ عِنۡدِ رَبِّنَا ۚ وَ مَا یَذَّکَّرُ  اِلَّاۤ اُولُوا الۡاَلۡبَابِ ﴿۷﴾', 'اے پیغمبر وہی تو ہے جس نے تم پر کتاب نازل کی جس کی بعض آیتیں محکم ہیں اور وہی اصل کتاب ہیں اور بعض دوسری متشابہ ہیں تو جن لوگوں کے دلوں میں کجی ہے و متشابہات کا اتباع کرتے ہیں تاکہ فتنہ برپا کریں اور مراد اصلی کا پتہ لگائیں حالانکہ مراد اصلی اللہ کے سوا کوئی نہیں جانتا اور جو لوگ علم میں گہری نظر رکھتے ہیں وہ یہ کہتے ہیں کہ ہم ان پر ایمان لائے۔ یہ سب آیات ہمارے پروردگار کی طرف سے ہیں۔ اور نصیحت تو عقلمند ہی قبول کرتے ہیں۔', 'وہی ہے جس نے اتاری تجھ پر کتاب اس میں بعض آیتیں ہیں محکم یعنی انکے معنیٰ واضح ہیں وہ اصل ہیں کتاب کی اور دوسری ہیں متشابہ یعنی جنکے معنیٰ معلوم یا معین نہیں سو جن کے دلوں میں کجی ہے وہ پیروی کرتے ہیں متشابہات کی گمراہی پھیلانے کی غرض سے اور مطلب معلوم کرنے کی وجہ سے اور ان کا مطلب کوئی نہیں جانتا سوا اللہ کے اور مضبوط علم والے کہتےہیں ہم اس پر یقین لائے سب ہمارے رب کی طرف سے اتری ہیں اور سمجھانے سے وہی سمجھتے ہیں جن کو عقل ہے [۸]', 'It is He Who has sent down to you (Muhammad SAW) the Book (this Quran). In it are Verses that are entirely clear, they are the foundations of the Book (and those are the Verses of Al-Ahkam (commandments, etc.), Al-Faraid (obligatory duties) and Al-Hudud (legal laws for the punishment of thieves, adulterers, etc.)); and others not entirely clear. So as for those in whose hearts there is a deviation (from the truth) they follow that which is not entirely clear thereof, seeking Al-Fitnah (polytheism and trials, etc.), and seeking for its hidden meanings, but none knows its hidden meanings save Allah. And those who are firmly grounded in knowledge say: \"We believe in it; the whole of it (clear and unclear Verses) are from our Lord.\" And none receive admonition except men of understanding. (Tafsir At-Tabaree).', 'He is the One who has revealed to you the Book (the Qur’ān). Out of it there are verses that are MuHkamāt (of established meaning), which are the principal verses of the Book, and some others are Mutashābihāt (whose definite meanings are unknown). Now those who have perversity in their hearts go after such part of it as is mutashābih, seeking (to create) discord, and searching for its interpretation (that meets their desires), while no one knows its interpretation except Allah; and those well-grounded in knowledge say: “We believe therein; all is from our Lord.” Only the men of understanding observe the advice.'),
(301, 3, 8, 1, 9, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'رَبَّنَا لَا تُزِغۡ قُلُوۡبَنَا بَعۡدَ  اِذۡ ہَدَیۡتَنَا وَ ہَبۡ لَنَا مِنۡ لَّدُنۡکَ رَحۡمَۃً ۚ اِنَّکَ اَنۡتَ الۡوَہَّابُ ﴿۸﴾', 'اے پروردگار جب تو نے ہمیں ہدایت بخشی ہے تو اس کے بعد ہمارے دلوں میں کجی نہ پیدا کر دیجیو اور ہمیں اپنے ہاں سے نعمت عطا فرما تو تو بڑا عطا فرمانے والا ہے۔', 'اے رب نہ پھیر ہمارے دلوں کو جب تو ہم کو ہدایت کر چکا اور عنایت کر ہم کو اپنے پاس سے رحمت تو ہی ہے سب کچھ دینے والا [۹]', '(They say): \"Our Lord! Let not our hearts deviate (from the truth) after You have guided us, and grant us mercy from You. Truly, You are the Bestower.\"', '“Our Lord, do not let our hearts deviate from the right path after You have given us guidance, and bestow upon us mercy from Your own. Surely, You, and You alone, are the One who bestows in abundance.'),
(302, 3, 9, 1, 9, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'رَبَّنَاۤ اِنَّکَ جَامِعُ النَّاسِ لِیَوۡمٍ لَّا رَیۡبَ فِیۡہِ ؕ اِنَّ اللّٰہَ  لَا یُخۡلِفُ الۡمِیۡعَادَ ٪﴿۹﴾', 'اے پروردگار تو اس روز جس کے آنے میں کچھ بھی شک نہیں سب لوگوں کو اپنے حضور میں جمع کر لے گا بیشک اللہ خلاف وعدہ نہیں کرتا۔', 'اے رب تو جمع کرنے والا ہے لوگوں کو ایک دن جس میں کچھ شبہ نہیں بیشک اللہ خلاف نہیں کرتا اپنا وعدہ [۱۰]', 'Our Lord! Verily, it is You Who will gather mankind together on the Day about which there is no doubt. Verily, Allah never breaks His Promise\".', 'Our Lord, You are going to assemble all the people on a day in (the occurrence of) which there is no doubt. Verily, Allah does not back out of His promise.”'),
(303, 3, 10, 2, 10, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اِنَّ الَّذِیۡنَ کَفَرُوۡا لَنۡ تُغۡنِیَ عَنۡہُمۡ اَمۡوَالُہُمۡ  وَ لَاۤ  اَوۡلَادُہُمۡ  مِّنَ اللّٰہِ شَیۡئًا ؕ وَ اُولٰٓئِکَ ہُمۡ  وَقُوۡدُ  النَّارِ ﴿ۙ۱۰﴾', 'جو لوگ کافر ہوئے اس دن نہ تو ان کا مال ہی اللہ کےعذاب سے ان کو بچا سکے گا اور نہ ان کی اولاد ہی کچھ کام آئے گی اور یہ لوگ آتش جہنم کا ایندھن ہونگے۔', 'بیشک جو لوگ کافر ہیں ہر گز کام نہ آویں گے ان کو ان کے مال اور نہ ان کی اولاد اللہ کے سامنے کچھ اور وہی ہیں ایندھن دوزخ کے [۱۱]', 'Verily, those who disbelieve, neither their properties nor their offspring will avail them whatsoever against Allah; and it is they who will be fuel of the Fire.', 'Surely, those who disbelieve, their wealth and their children shall not suffice them in the least against Allah. Those are the fuel of the Fire'),
(304, 3, 11, 2, 10, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'کَدَاۡبِ اٰلِ فِرۡعَوۡنَ ۙ وَ الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ ؕ  کَذَّبُوۡا بِاٰیٰتِنَا ۚ فَاَخَذَہُمُ اللّٰہُ بِذُنُوۡبِہِمۡ ؕ وَ اللّٰہُ شَدِیۡدُ الۡعِقَابِ ﴿۱۱﴾', 'ان کا حال بھی فرعونیوں اور ان سے پہلے لوگوں کا سا ہوگا جنہوں نے ہماری آیتوں کی تکذیب کی تھی تو اللہ نے ان کو ان کے گناہوں کے سبب عذاب میں پکڑ لیا تھا اور اللہ سخت عذاب کرنے والا ہے۔', 'جیسے دستور فرعون والوں کا اور جو ان سے پہلے تھے جھٹلایا انہوں نے ہماری آیتوں کو پھر پکڑا ان کو اللہ نے ان کے گناہوں پر اور اللہ کا عذاب سخت ہے [۱۲]', 'Like the behaviour of the people of Firaun (Pharaoh) and those before them; they belied Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), so Allah seized (destroyed) them for their sins. And Allah is Severe in punishment.', 'a case similar to that of the House of Pharaoh and those before them. They denied our signs. So, Allah seized them for their sins. Allah is severe in punishment.'),
(305, 3, 12, 2, 10, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'قُلۡ لِّلَّذِیۡنَ کَفَرُوۡا سَتُغۡلَبُوۡنَ وَ تُحۡشَرُوۡنَ اِلٰی جَہَنَّمَ ؕ وَ بِئۡسَ الۡمِہَادُ ﴿۱۲﴾', 'اے پیغمبر کافروں سے کہدو کہ تم دنیا میں بھی عنقریب مغلوب ہو جاؤ گے اور آخرت میں جہنم کی طرف اکٹھا کئے جاؤ گے اور وہ بری جگہ ہے۔', 'کہہ دے کافروں کو کہ اب تم مغلوب ہو گے اور ہانکے جاؤ گے دوزخ کی طرف اور کیا برا ٹھکانہ ہے [۱۳]', 'Say (O Muhammad SAW) to those who disbelieve: \"You will be defeated and gathered together to Hell, and worst indeed is that place to rest.\"', 'Say to those who disbelieve: “You shall soon be overcome and shall be gathered into Hell. Indeed, it is an evil bed (in which) to rest.”'),
(306, 3, 13, 2, 10, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'قَدۡ کَانَ لَکُمۡ اٰیَۃٌ فِیۡ فِئَتَیۡنِ الۡتَقَتَا ؕ فِئَۃٌ تُقَاتِلُ فِیۡ سَبِیۡلِ اللّٰہِ وَ اُخۡرٰی کَافِرَۃٌ یَّرَوۡنَہُمۡ مِّثۡلَیۡہِمۡ رَاۡیَ الۡعَیۡنِ ؕ وَ اللّٰہُ یُؤَیِّدُ بِنَصۡرِہٖ مَنۡ یَّشَآءُ ؕ اِنَّ فِیۡ ذٰلِکَ لَعِبۡرَۃً   لِّاُولِی الۡاَبۡصَارِ ﴿۱۳﴾', 'تمہارے لئے دو گروہوں میں جو جنگ بدر کے دن آپس میں بھڑ گئے قدرت الٰہی کی عظیم الشان نشانی تھی ایک گروہ مسلمانوں کا تھا وہ اللہ کی راہ میں لڑ رہا تھا۔ اور دوسرا گروہ کافروں کا تھا وہ ان کو اپنی آنکھوں سے اپنے سے دوگنا مشاہدہ کر رہا تھا۔ اور اللہ اپنی نصرت سے جس کو چاہتا ہے مدد دیتا ہے جو اہل بصارت ہیں ان کے لئے اس واقعے میں بڑی عبرت ہے۔', 'ابھی گذر چکا ہے تمہارے سامنے ایک نمونہ دو فوجوں میں جن میں مقابلہ ہوا ایک فوج ہے کہ لڑتی ہے اللہ کی راہ میں اور دوسری فوج کافروں کی ہے  دیکھتے ہیں یہ ان کو اپنے سے دو چند صریح آنکھوں سے اور اللہ زور دیتا ہے اپنی مدد کا جس کو چاہے اسی میں عبرت ہے دیکھنے والوں کو [۱۴]', 'There has already been a sign for you (O Jews) in the two armies that met (in combat i.e. the battle of Badr): One was fighting in the Cause of Allah, and as for the other (they) were disbelievers. They (the believers) saw them (the disbelievers) with their own eyes twice their number (although they were thrice their number). And Allah supports with His Victory whom He pleases. Verily, in this is a lesson for those who understand. (See Verse 8:44). (Tafsir At-Tabaree)', '“There was a sign for you in the two groups who confronted each other: One group fighting in the way of Allah, and the other disbelieving, seeing themselves as twice their number, with open eyes. And Allah gives strength with His help to whomsoever He wills. Indeed, there is a lesson therein for those who have eyes.”'),
(307, 3, 14, 2, 10, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'زُیِّنَ لِلنَّاسِ حُبُّ الشَّہَوٰتِ مِنَ النِّسَآءِ وَ الۡبَنِیۡنَ وَ الۡقَنَاطِیۡرِ الۡمُقَنۡطَرَۃِ مِنَ الذَّہَبِ وَ الۡفِضَّۃِ وَ الۡخَیۡلِ الۡمُسَوَّمَۃِ وَ الۡاَنۡعَامِ وَ الۡحَرۡثِ ؕ ذٰلِکَ مَتَاعُ  الۡحَیٰوۃِ الدُّنۡیَا ۚ وَ اللّٰہُ عِنۡدَہٗ حُسۡنُ الۡمَاٰبِ ﴿۱۴﴾', 'لوگوں کو ان کی خواہشوں کی چیزیں یعنی عورتیں اور بیٹے اور سونے اور چاندی کے بڑے بڑے ڈھیر اور نشان لگے ہوئے گھوڑے اور مویشی اور کھیتی بڑی زینت دار معلوم ہوتی ہیں مگر یہ سب دنیا ہی کی زندگی کے سامان ہیں۔ اور اللہ کے پاس بہت اچھا ٹھکانہ ہے۔', 'فریفتہ کیا ہے لوگوں کو مرغوب چیزوں کی محبت نے جیسے عورتیں [۱۵] اور بیٹے اور خزانے جمع کئے ہوئے سونے اور چاندی کے اور گھوڑے نشان لگائے ہوئے [۱۶] اور مویشی اور کھیتی یہ فائدہ اٹھانا ہے دنیا کی زندگی میں اور اللہ ہی کے پاس ہے اچھا ٹھکانہ [۱۷]', 'Beautified for men is the love of things they covet; women, children, much of gold and silver (wealth), branded beautiful horses, cattle and well-tilled land. This is the pleasure of the present worlds life; but Allah has the excellent return (Paradise with flowing rivers, etc.) with Him.', 'It has been made attractive for people to love the desired things; that is, women, children, hoarded heaps of gold and silver, branded horses, cattle and tillage. That is an enjoyment of the worldly life; but with Allah lies the beauty of the final resort.'),
(308, 3, 15, 2, 10, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'قُلۡ اَؤُنَبِّئُکُمۡ بِخَیۡرٍ مِّنۡ ذٰلِکُمۡ ؕ لِلَّذِیۡنَ اتَّقَوۡا عِنۡدَ رَبِّہِمۡ جَنّٰتٌ  تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَا وَ اَزۡوَاجٌ مُّطَہَّرَۃٌ وَّ رِضۡوَانٌ مِّنَ اللّٰہِ ؕ وَ اللّٰہُ بَصِیۡرٌۢ  بِالۡعِبَادِ ﴿ۚ۱۵﴾', 'اے پیغمبر ان سے کہو کہ بھلا میں تم کو ایسی چیز بتاؤں جو ان چیزوں سے کہیں اچھی ہو سنو جو لوگ پرہیزگار ہیں ان کے لئے اللہ کے ہاں باغات بہشت ہیں جن کے نیچے نہریں بہ رہی ہیں ان میں وہ ہمیشہ رہیں گے۔ اور پاکیزہ بیویاں ہیں اور سب سے بڑھ کر اللہ کی خوشنودی۔ اور اللہ اپنے سب بندوں کو دیکھ رہا ہے۔', 'کہدے کیا بتاؤں میں تمکو اس سے بہتر پرہیزگاروں کے لئے اپنے رب کے ہاں باغ ہیں جن کے نیچے جاری ہیں نہریں ہمیشہ رہیں گے ان میں اور عورتیں ہیں ستھری [۱۸] اور رضامندی اللہ کی [۱۹] اور اللہ کی نگاہ میں ہیں بندے [۲۰]', 'Say: \"Shall I inform you of things far better than those? For Al-Muttaqoon (the pious - see V.2:2) there are Gardens (Paradise) with their Lord, underneath which rivers flow. Therein (is their) eternal (home) and Azwajun Mutahharatun (purified mates or wives) (i.e. they will have no menses, urine, or stool, etc.), And Allah will be pleased with them. And Allah is All-Seer of the (His) slaves\".', 'Say: “Shall I tell you what is far better than that? For those who fear (Allah), there are gardens with their Lord, beneath which rivers flow, where they shall live forever, with purified wives, and approval from Allah. Allah is watchful over His servants”.'),
(309, 3, 16, 2, 10, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اَلَّذِیۡنَ یَقُوۡلُوۡنَ رَبَّنَاۤ اِنَّنَاۤ اٰمَنَّا فَاغۡفِرۡ لَنَا ذُنُوۡبَنَا وَ قِنَا عَذَابَ النَّارِ ﴿ۚ۱۶﴾', 'جو اللہ سے التجا کرتے ہیں کہ اے پروردگار ہم ایمان لے آئے سو ہم کو ہمارے گناہ معاف فرما اور ہم کو دوزخ کے عذاب سے محفوظ رکھ۔', 'وہ جو کہتے ہیں اے رب ہمارے ہم ایمان لائے ہیں سو بخش دے ہم کو گناہ ہمارے اور بچا ہم کو دوزخ کے عذب سے [۲۱]', 'Those who say: \"Our Lord! We have indeed believed, so forgive us our sins and save us from the punishment of the Fire.\"', 'Those (are the ones) who say: “Our Lord, surely we have believed, so forgive us our sins and save us from the punishment of the Fire,”'),
(310, 3, 17, 2, 10, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اَلصّٰبِرِیۡنَ وَ الصّٰدِقِیۡنَ وَ الۡقٰنِتِیۡنَ وَ الۡمُنۡفِقِیۡنَ وَ الۡمُسۡتَغۡفِرِیۡنَ بِالۡاَسۡحَارِ ﴿۱۷﴾', 'یہ وہ لوگ ہیں جو مشکلات میں صبر کرتے اور سچ بولتے اور عبادت میں لگے رہتے اور نیکی میں خرچ کرتے اور اوقات سحر میں گناہوں کی معافی مانگا کرتے ہیں۔', 'وہ صبر کرنے والے ہیں اور سچے اور حکم بجا لانے والے اور خرچ کرنے والے اور گناہ بخشوانے والے پچھلی رات میں [۲۲]', '(They are) those who are patient ones, those who are true (in Faith, words, and deeds), and obedient with sincere devotion in worship to Allah. Those who spend (give the Zakat and alms in the Way of Allah) and those who pray and beg Allahs Pardon in the last hours of the night.', '(and those who are) the patient, the truthful and the devout, who spend (in Allah’s way) and who seek forgiveness in pre-dawn hours.”'),
(311, 3, 18, 2, 10, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'شَہِدَ اللّٰہُ  اَنَّہٗ  لَاۤ  اِلٰہَ  اِلَّا ہُوَ ۙ وَ الۡمَلٰٓئِکَۃُ وَ اُولُوا الۡعِلۡمِ قَآئِمًۢا بِالۡقِسۡطِ ؕ لَاۤ  اِلٰہَ  اِلَّا ہُوَ الۡعَزِیۡزُ الۡحَکِیۡمُ ﴿ؕ۱۸﴾', 'اللہ تو اس بات کی گواہی دیتا ہے کہ اس کے سوا کوئی معبود نہیں اس حال میں کہ  وہ انصاف کا حاکم ہے اور فرشتے اور علم والے بھی گواہی دیتے ہیں کہ اس غالب حکمت والے کے سوا کوئی لائق عبادت نہیں۔', 'اللہ نے گواہی دی کہ کسی کی بندگی نہیں اس کے سوا [۲۳] اور فرشتوں نے [۲۴] اور علم والوں نے بھی [۲۵] وہی حاکم انصاف کا ہے کسی کی بندگی نہیں سوا اس کے زبردست ہے حکمت والا [۲۶]', 'Allah bears witness that La ilaha illa Huwa (none has the right to be worshipped but He), and the angels, and those having knowledge (also give this witness); (He is always) maintaining His creation in Justice. La ilah illa Huwa (none has the right to be worshipped but He), the All-Mighty, the All-Wise.', 'Allah bears witness that there is no god but He - and (so do) the angels and the men of knowledge - being the One who maintains equity. There is no god but He, the Mighty, the Wise.'),
(312, 3, 19, 2, 10, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اِنَّ الدِّیۡنَ عِنۡدَ اللّٰہِ الۡاِسۡلَامُ ۟ وَ مَا اخۡتَلَفَ الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ اِلَّا مِنۡۢ بَعۡدِ مَا جَآءَہُمُ الۡعِلۡمُ بَغۡیًۢا بَیۡنَہُمۡ ؕ وَ مَنۡ یَّکۡفُرۡ بِاٰیٰتِ اللّٰہِ فَاِنَّ اللّٰہَ سَرِیۡعُ  الۡحِسَابِ ﴿۱۹﴾', 'دین تو اللہ کے نزدیک اسلام ہی ہے۔ اور اہل کتاب نے جو اس دین سے اختلاف کیا تو علم حاصل ہونے کے بعد آپس کی ضد سے کیا۔ اور جو شخص اللہ کی آیتوں کو نہ مانے تو اللہ جلد حساب لینے والا ہے۔', 'بیشک دین جو ہے اللہ کے ہاں سو یہی مسلمانی حکمبرداری ہے [۲۷] اور مخالف نہیں ہوئے کتاب والے مگر جب ان کو معلوم ہو چکا آپس کی ضد اور حسد سے [۲۸] اور جو کوئی انکار کرے اللہ کے حکموں کا تو اللہ جلدی حساب لینے والا ہے [۲۹]', 'Truly, the religion with Allah is Islam. Those who were given the Scripture (Jews and Christians) did not differ except, out of mutual jealousy, after knowledge had come to them. And whoever disbelieves in the Ayat (proofs, evidences, verses, signs, revelations, etc.) of Allah, then surely, Allah is Swift in calling to account.', 'Truly, the (recognized) religion in the sight of Allah is Islām . Those who have been given the Book did not differ (among themselves) until after the knowledge had come to them, (and all this) due to envy against each other. Whoever denies the verses of Allah, then, Allah is swift at reckoning.'),
(313, 3, 20, 2, 10, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'فَاِنۡ حَآجُّوۡکَ فَقُلۡ اَسۡلَمۡتُ وَجۡہِیَ لِلّٰہِ وَ مَنِ اتَّبَعَنِ ؕ وَ قُلۡ لِّلَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ وَ الۡاُمِّیّٖنَ ءَاَسۡلَمۡتُمۡ ؕ فَاِنۡ اَسۡلَمُوۡا فَقَدِ اہۡتَدَوۡا ۚ وَ اِنۡ تَوَلَّوۡا فَاِنَّمَا عَلَیۡکَ الۡبَلٰغُ ؕ وَ اللّٰہُ بَصِیۡرٌۢ بِالۡعِبَادِ ﴿٪۲۰﴾', 'اے پیغمبر پس اگر یہ لوگ تم سے جھگڑنے لگیں تو کہنا کہ میں اور میرے پیرو تو اللہ کے فرمانبردار ہو چکے۔ اور اہل کتاب اور ان پڑھ لوگوں سے کہو کہ کیا تم بھی اللہ کے فرمانبردار بنتے اور اسلام لاتے ہو؟ پس اگر یہ لوگ اسلام لے آئیں تو بے شک ہدایت پا لیں اور اگر تمہارا کہا نہ مانیں تو تمہارا کام صرف اللہ کا پیغام پہنچا دینا ہے۔ اور اللہ اپنے بندوں کو دیکھ رہا ہے۔', 'پھر بھی اگر تجھ سے جھگڑیں تو کہہ دے میں نے تابع کیا اپنا منہ اللہ کے حکم پر اور انہوں نے بھی کہ جو میرے ساتھ ہیں [۳۰] اور کہہ دے کتاب والوں کو اور ان پڑھوں کو کہ تم بھی تابع ہوتے ہو پھر اگر وہ تابع ہوئے تو انہوں نے راہ پائی سیدھی اور اگر منہ پھریں تو تیرے ذمہ صرف پہنچا دینا ہے اور اللہ کی نگاہ میں ہیں بندے [۳۱]', 'So if they dispute with you (Muhammad SAW) say: \"I have submitted myself to Allah (in Islam), and (so have) those who follow me.\" And say to those who were given the Scripture (Jews and Christians) and to those who are illiterates (Arab pagans): \"Do you (also) submit yourselves (to Allah in Islam)?\" If they do, they are rightly guided; but if they turn away, your duty is only to convey the Message; and Allah is All-Seer of (His ) slaves.', 'Then, if they argue with you, say: “I have submitted myself to Allah, and (so did) those who have followed me.” And say to those who have been given the Book, and to the unlettered: “Do you submit?” If they submit, they will be on the right path. Yet, if they turn back, then you have only to convey the message. Allah is watchful over (all of) His servants.'),
(314, 3, 21, 3, 11, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اِنَّ الَّذِیۡنَ یَکۡفُرُوۡنَ بِاٰیٰتِ اللّٰہِ وَ یَقۡتُلُوۡنَ النَّبِیّٖنَ بِغَیۡرِ حَقٍّ ۙ  وَّ یَقۡتُلُوۡنَ الَّذِیۡنَ یَاۡمُرُوۡنَ بِالۡقِسۡطِ مِنَ النَّاسِ ۙ فَبَشِّرۡہُمۡ  بِعَذَابٍ اَلِیۡمٍ ﴿۲۱﴾', 'جو لوگ اللہ کی آیتوں کو نہیں مانتے اور انبیاء کو ناحق قتل کرتے رہے ہیں اور جو انصاف کرنے کا حکم دیتے ہیں انہیں بھی مار ڈالتے ہیں ان کو دکھ دینے والے عذاب کی خوشخبری سنا دو۔', 'جو لوگ انکار کرتے ہیں اللہ کے حکموں کا اور قتل کرتے ہیں پیغمبروں کو ناحق اور قتل کرتے ہیں ان کو جو حکم کرتے ہیں انصاف کرنے کا لوگوں میں سے سو خوشخبری سنا دے انکو عذاب دردناک کی', 'Verily! Those who disbelieve in the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah and kill the Prophets without right, and kill those men who order just dealings, … announce to them a painful torment.', 'Surely, those who reject the verses of Allah and slay the prophets unjustly, and slay those of the people who bid justice, give them ‘the good news’ of a painful punishment.'),
(315, 3, 22, 3, 11, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اُولٰٓئِکَ الَّذِیۡنَ حَبِطَتۡ اَعۡمَالُہُمۡ فِی الدُّنۡیَا وَ الۡاٰخِرَۃِ ۫ وَ مَا لَہُمۡ مِّنۡ نّٰصِرِیۡنَ ﴿۲۲﴾', 'یہ ایسے لوگ ہیں جن کے اعمال دنیا اور آخرت دونوں میں برباد ہیں اور ان کا کوئی مددگار نہیں ہو گا۔', 'یہی ہیں جن کی محنت ضائع ہوئی دنیا میں اور آخرت میں اور کوئی نہیں ان کا مددگار [۳۲]', 'They are those whose works will be lost in this world and in the Hereafter, and they will have no helpers.', 'Those are the ones whose deeds have gone to waste in this world and in the Hereafter. For them there are no helpers.'),
(316, 3, 23, 3, 11, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اَلَمۡ تَرَ اِلَی الَّذِیۡنَ اُوۡتُوۡا نَصِیۡبًا مِّنَ الۡکِتٰبِ یُدۡعَوۡنَ  اِلٰی کِتٰبِ اللّٰہِ لِیَحۡکُمَ بَیۡنَہُمۡ ثُمَّ یَتَوَلّٰی فَرِیۡقٌ مِّنۡہُمۡ وَ ہُمۡ مُّعۡرِضُوۡنَ ﴿۲۳﴾', 'بھلا تم نے ان لوگوں کو نہیں دیکھا جنکو کتاب یعنی تورات سے حصہ دیا گیا اور وہ اس کتاب اللہ یعنی قرآن کی طرف بلا ئے جاتے ہیں تا کہ یہ ان کے تنازعات کا ان میں فیصلہ کر دے تو ایک فریق ان میں سے پھر جاتا ہے اور منہ پھیر لیتا ہے۔', 'کیا نہ دیکھا تو نے ان لوگوں کو جن کو ملا کچھ ایک حصہ کتاب کا [۳۳] ان کو بلاتے ہیں اللہ کی کتاب کی طرف تاکہ وہ کتاب ان میں حکم کرے پھر منہ پھیرتےہیں بعضے ان میں سےتغافل کر کے [۳۴]', 'Have you not seen those who have been given a portion of the Scripture? They are being invited to the Book of Allah to settle their dispute, then a party of them turn away, and they are averse.', 'Did you not observe those who have been given a share from the Book? They are invited to the Book of Allah, so that it may decide between them. Then, a group from them goes back, turning their faces away.'),
(317, 3, 24, 3, 11, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'ذٰلِکَ بِاَنَّہُمۡ قَالُوۡا لَنۡ تَمَسَّنَا النَّارُ اِلَّاۤ اَیَّامًا مَّعۡدُوۡدٰتٍ ۪ وَ غَرَّہُمۡ فِیۡ دِیۡنِہِمۡ مَّا  کَانُوۡا یَفۡتَرُوۡنَ ﴿۲۴﴾', 'یہ اس لئے کہ یہ اس بات کے قائل ہیں کہ دوزخ کی آگ ہمیں چند روز کے سوا چھو ہی نہیں سکے گی۔ اور جو کچھ یہ دین کے بارے میں بہتان باندھتے رہے ہیں اس نے ان کو دھوکے میں ڈال رکھا ہے۔', 'یہ اس واسطے کہ کہتے ہیں وہ ہم کو ہرگز نہ لگے گی آگ دوزخ کی مگر چند دن گنتی کے اور بہکے ہیں اپنے دین میں اپنی بنائی باتوں پر [۳۵]', 'This is because they say: \"The Fire shall not touch us but for a number of days.\" And that which they used to invent regarding their religion has deceived them.', 'That is because they have said: “The Fire shall not touch us except for a few days.” Thus they are deceived in their faith by what they themselves used to invent.'),
(318, 3, 25, 3, 11, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'فَکَیۡفَ اِذَا جَمَعۡنٰہُمۡ لِیَوۡمٍ لَّا رَیۡبَ فِیۡہِ ۟ وَ وُفِّیَتۡ کُلُّ نَفۡسٍ مَّا کَسَبَتۡ وَ ہُمۡ لَا یُظۡلَمُوۡنَ ﴿۲۵﴾', 'تو اس وقت کیا حال ہو گا جب ہم ان کو جمع کریں گے یعنی اس روز جس کے آنے میں کچھ بھی شک نہیں اور ہر نفس اپنے اعمال کا پورا پورا بدلہ پائے گا اور ان پر ظلم نہیں کیا جائے گا۔', 'پھر کیا ہو گا حال جب ہم انکو جمع کریں گے ایک دن کہ اسکے آنے میں کچھ شبہ نہیں اور پورا پاوے گا ہر کوئی اپنا کیا [۳۶] اور انکی حق تلفی نہ ہو گی[۳۷]', 'How (will it be) when We gather them together on the Day about which there is no doubt (i.e. the Day of Resurrection). And each person will be paid in full what he has earned? And they will not be dealt with unjustly.', 'Then, how (will it be) when We will gather them together on a day about which there is no doubt, and everybody will be paid in full for what he has earned, and they shall not be wronged?'),
(319, 3, 26, 3, 11, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'قُلِ اللّٰہُمَّ مٰلِکَ الۡمُلۡکِ تُؤۡتِی الۡمُلۡکَ مَنۡ تَشَآءُ وَ تَنۡزِعُ الۡمُلۡکَ مِمَّنۡ تَشَآءُ ۫ وَ تُعِزُّ مَنۡ تَشَآءُ وَ تُذِلُّ مَنۡ تَشَآءُ ؕ بِیَدِکَ الۡخَیۡرُ ؕ اِنَّکَ عَلٰی کُلِّ شَیۡءٍ قَدِیۡرٌ ﴿۲۶﴾', 'کہو کہ اے اللہ اے بادشاہی کے مالک تو جسکو چاہے بادشاہی بخشے اور جس سے چاہے بادشاہی چھین لے اور جس کو چاہے عزت دے اور جسے چاہے ذلیل کرے ہر طرح کی بھلائی تیرے ہی ہاتھ ہے اور بےشک تو ہر چیز پر قادر ہے۔', 'تو کہہ یا اللہ مالک سلطنت کے تو سلطنت دیوے جس کو چاہے اور سلطنت چھین لیوے جس سے چاہے اور عزت دیوے جس کو چاہے اور ذلیل کرے جس کو چاہے تیرے ہاتھ ہے سب خوبی بیشک تو ہر چیز پر قادر ہے [۳۸]', 'Say (O Muhammad SAW): \"O Allah! Possessor of the kingdom, You give the kingdom to whom You will, and You take the kingdom from whom You will, and You endue with honour whom You will, and You humiliate whom You will. In Your Hand is the good. Verily, You are Able to do all things.', 'Say: “O Allah, O Lord of the Kingdom, You give kingdom to whom You will, and take kingdom away from whom You will; and You bestow honor on whom You will, and bring disgrace to whom You will. In your hand lies the betterment (of everyone). You are surely powerful over everything.'),
(320, 3, 27, 3, 11, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'تُوۡلِجُ الَّیۡلَ فِی النَّہَارِ وَ تُوۡلِجُ النَّہَارَ فِی الَّیۡلِ ۫ وَ تُخۡرِجُ الۡحَیَّ مِنَ الۡمَیِّتِ وَ تُخۡرِجُ الۡمَیِّتَ مِنَ الۡحَیِّ ۫ وَ تَرۡزُقُ مَنۡ تَشَآءُ بِغَیۡرِ  حِسَابٍ ﴿۲۷﴾', 'تو ہی رات کو دن میں داخل کرتا اور تو ہی دن کو رات میں داخل کرتا ہے تو ہی بےجان سے جاندار پیدا کرتا ہے اور تو ہی جاندار سے بےجان پیدا کرتا ہے اور تو ہی جسکو چاہتا ہے بے حساب رزق بخشتا ہے۔', 'تو داخل کرتا ہے رات کو دن میں اور داخل کرے دن کو رات میں [۳۹] اور تو نکالے زندہ مردہ سے اور نکالے مردہ زندہ سے [۴۰] اور تو رزق دے جس کو چاہے بے شمار [۴۱]', 'You make the night to enter into the day, and You make the day to enter into the night (i.e. increase and decrease in the hours of the night and the day during winter and summer), You bring the living out of the dead, and You bring the dead out of the living. And You give wealth and sustenance to whom You will, without limit (measure or account).', 'You make the night enter into the day, and make the day enter into the night; and You bring the living out from the dead, and bring the dead out from the living, and You give to whom You will beyond measure.”'),
(321, 3, 28, 3, 11, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'لَا یَتَّخِذِ الۡمُؤۡمِنُوۡنَ الۡکٰفِرِیۡنَ اَوۡلِیَآءَ مِنۡ دُوۡنِ الۡمُؤۡمِنِیۡنَ ۚ وَ مَنۡ یَّفۡعَلۡ ذٰلِکَ فَلَیۡسَ مِنَ اللّٰہِ  فِیۡ شَیۡءٍ اِلَّاۤ  اَنۡ تَتَّقُوۡا مِنۡہُمۡ تُقٰىۃً ؕ وَ یُحَذِّرُکُمُ اللّٰہُ نَفۡسَہٗ ؕ وَ اِلَی اللّٰہِ الۡمَصِیۡرُ ﴿۲۸﴾', 'مومنوں کو چاہیے کے مومنوں کے سوا کافروں کو دوست نہ بنائیں۔ اور جو ایسا کرے گا اس سے اللہ کا کچھ عہد نہیں۔ ہاں اگر اس طریق سے تم ان کے شر سے بچاؤ کی صورت پیدا کرو تو مضائقہ نہیں اور اللہ تم کو اپنے غضب سے ڈراتا ہے۔ اور اللہ ہی کی طرف تم کو لوٹ کر جانا ہے۔', 'نہ بناویں مسلمان کافروں کو دوست مسلمانوں کو چھوڑ کر اور جو کوئی یہ کام کرے تو نہیں اس کو اللہ سے کوئی تعلق مگر اس حالت میں کہ کرنا چاہو تم ان سے بچاؤ [۴۲] اور اللہ تم کو ڈراتا ہے اپنے سے اور اللہ ہی کی طرف لوٹ کر جانا ہے [۴۳]', 'Let not the believers take the disbelievers as Auliya (supporters, helpers, etc.) instead of the believers, and whoever does that will never be helped by Allah in any way, except if you indeed fear a danger from them. And Allah warns you against Himself (His Punishment), and to Allah is the final return.', 'The believers must not take the disbelievers as friends instead of the believers.And whoever does that has no relation with Allah whatsoever, unless you (do so) as a protective measure (in order to) save yourself from them. Allah warns you of Himself, for unto Allah is the return.'),
(322, 3, 29, 3, 11, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'قُلۡ اِنۡ تُخۡفُوۡا مَا فِیۡ صُدُوۡرِکُمۡ اَوۡ تُبۡدُوۡہُ یَعۡلَمۡہُ اللّٰہُ ؕ وَ یَعۡلَمُ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ؕ وَ اللّٰہُ عَلٰی کُلِّ شَیۡءٍ قَدِیۡرٌ ﴿۲۹﴾', 'اے پیغمبر لوگوں سے کہدو کہ کوئی بات تم اپنے دلوں میں مخفی رکھو یا اسے ظاہر کرو اللہ اس کو جانتا ہے اور جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے اس کو سب کی خبر ہے اور وہ ہر چیز پر قادر ہے۔', 'تو کہہ اگر تم چھپاؤ گے اپنے جی کی بات یا اسے ظاہر کرو گے جانتا ہے اس کو اللہ [۴۴] اور اس کو معلوم ہے جو کچھ کہ ہے آسمانوں میں اور جو کچھ ہے زمین میں اور اللہ ہر چیز پر قادر ہے [۴۵]', 'Say (O Muhammad SAW): \"Whether you hide what is in your breasts or reveal it, Allah knows it, and He knows what is in the heavens and what is in the earth. And Allah is Able to do all things.\"', 'Say: “Whether you conceal what is in your hearts or reveal it, Allah will know it.” He knows what is in the heavens and what is in the earth. Allah is powerful over everything.'),
(323, 3, 30, 3, 11, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'یَوۡمَ تَجِدُ کُلُّ نَفۡسٍ مَّا عَمِلَتۡ مِنۡ خَیۡرٍ مُّحۡضَرًا ۚۖۛ وَّ مَا عَمِلَتۡ مِنۡ سُوۡٓءٍ ۚۛ تَوَدُّ لَوۡ اَنَّ بَیۡنَہَا وَ بَیۡنَہٗۤ اَمَدًۢا بَعِیۡدًا ؕ وَ یُحَذِّرُکُمُ اللّٰہُ نَفۡسَہٗ ؕ وَ اللّٰہُ رَءُوۡفٌۢ بِالۡعِبَادِ ﴿٪۳۰﴾', 'جس دن ہر شخص اپنی کی ہوئی نیکی کو موجود پا لے گا اور اپنی برائی کو بھی دیکھ لے گا تو آرزو کرے گا کہ اے کاش اس میں اور اس برائی میں دور کی مسافت ہو جاتی۔ اور اللہ تمکو اپنے غضب سے ڈراتا ہے۔ اور اللہ اپنے بندوں پر نہایت مہربان ہے۔', 'جس دن موجود پاوے گا ہر شخص جو کچھ کہ کی ہے اس نے نیکی اپنےسامنے اور جو کچھ کہ کی ہے اس نے برائی آرزو کرے گا کہ مجھ میں اور اس میں فرق پڑ جاوے دور کا [۴۶] اور اللہ ڈراتا ہے تم کو اپنے سے اور اللہ بہت مہربان ہے بندوں پر [۴۷]', 'On the Day when every person will be confronted with all the good he has done, and all the evil he has done, he will wish that there were a great distance between him and his evil. And Allah warns you against Himself (His Punishment) and Allah is full of Kindness to the (His) slaves.', 'On the day when everybody shall find present before him whatever good he did and whatever evil he wrought, he will wish there would have been a wide space between him and that (day). Allah warns you of Himself, and Allah is compassionate to (His) servants.'),
(324, 3, 31, 4, 12, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'قُلۡ  اِنۡ کُنۡتُمۡ تُحِبُّوۡنَ اللّٰہَ فَاتَّبِعُوۡنِیۡ یُحۡبِبۡکُمُ اللّٰہُ وَ یَغۡفِرۡ لَکُمۡ ذُنُوۡبَکُمۡ ؕ وَ اللّٰہُ غَفُوۡرٌ  رَّحِیۡمٌ ﴿۳۱﴾', 'اے پیغمبر ﷺ لوگوں سے کہدو کہ اگر تم اللہ کو دوست رکھتے ہو تو میری پیروی کرو اللہ بھی تمہیں دوست رکھے گا اور تمہارے گناہ معاف کر دے گا اور اللہ بخشنے والا ہے مہربان ہے۔', 'تو کہہ اگر تم محبت رکھتے ہو اللہ کی تو میری راہ چلو تاکہ محبت کرے تم سے اللہ اور بخشے گناہ تمہارے اور اللہ بخشنے والا مہربان ہے [۴۸]', 'Say (O Muhammad SAW to mankind): \"If you (really) love Allah then follow me (i.e. accept Islamic Monotheism, follow the Quran and the Sunnah), Allah will love you and forgive you of your sins. And Allah is Oft-Forgiving, Most Merciful.\"', 'Say (O Prophet): “If you really love Allah, then follow me, and Allah shall love you and forgive you your sins. Allah is Most-Forgiving, Very-Merciful.”'),
(325, 3, 32, 4, 12, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'قُلۡ اَطِیۡعُوا اللّٰہَ وَ الرَّسُوۡلَ ۚ فَاِنۡ تَوَلَّوۡا فَاِنَّ اللّٰہَ  لَا یُحِبُّ الۡکٰفِرِیۡنَ ﴿۳۲﴾', 'کہدو کہ اللہ اور اس کے رسول کا حکم مانو۔ پس اگر وہ نہ مانیں تو اللہ بھی کافروں کو دوست نہیں رکھتا۔', 'تو کہہ حکم مانو اللہ کا اور رسول کا پھر اگر اعراض کریں تو اللہ کو محبت نہیں ہے کافروں سے [۴۹]', 'Say (O Muhammad SAW): \"Obey Allah and the Messenger (Muhammad SAW).\" But if they turn away, then Allah does not like the disbelievers.', 'Say: “Obey Allah and the Messenger.” Then, should they turn back, Allah does not love the disbelievers.”'),
(326, 3, 33, 4, 12, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اِنَّ اللّٰہَ اصۡطَفٰۤی اٰدَمَ وَ نُوۡحًا وَّ اٰلَ اِبۡرٰہِیۡمَ  وَ اٰلَ عِمۡرٰنَ عَلَی الۡعٰلَمِیۡنَ ﴿ۙ۳۳﴾', 'اللہ نے آدم اور نوح اور خاندان ابراہیم اور خاندان عمران کو تمام جہان کے لوگوں میں سے منتخب فرمایا تھا۔', 'بیشک اللہ نے پسند کیا آدم کو اور نوح کو اور ابراہیم کے گھر کو اور عمران کے گھر کو [۵۰] سارے جہان سے', 'Allah chose Adam, Nooh (Noah), the family of Ibrahim (Abraham) and the family of Imran above the Alameen (mankind and jinns) (of their times).', 'Verily, Allah has chosen ’Ādam and NūH (Noah) and the House of Ibrāhīm and the House of ‘Imrān over all the worlds'),
(327, 3, 34, 4, 12, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'ذُرِّیَّۃًۢ بَعۡضُہَا مِنۡۢ بَعۡضٍ ؕ وَ اللّٰہُ سَمِیۡعٌ  عَلِیۡمٌ ﴿ۚ۳۴﴾', 'ان میں سے بعض بعض کی اولاد تھے۔ اور اللہ سننے والا ہے جاننے والا ہے۔', 'جو اولاد تھے ایک دوسرے کی [۵۱] اور اللہ سننے والا جاننے والا ہے [۵۲]', 'Offspring, one of the other, and Allah is the All-Hearer, All-Knower.', '- a progeny some of whom resembles the others (in faith). Allah is All-Hearing, All-Knowing.'),
(328, 3, 35, 4, 12, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اِذۡ  قَالَتِ امۡرَاَتُ عِمۡرٰنَ رَبِّ اِنِّیۡ نَذَرۡتُ لَکَ مَا فِیۡ بَطۡنِیۡ مُحَرَّرًا فَتَقَبَّلۡ مِنِّیۡ ۚ اِنَّکَ اَنۡتَ السَّمِیۡعُ الۡعَلِیۡمُ ﴿۳۵﴾', 'وہ وقت یاد کرنے کے لائق ہے جب عمران کی بیوی نے کہا کہ اے پروردگار جو بچہ میرے پیٹ میں ہے میں اس کو تیری نذر کرتی ہوں اسے دنیا کے کاموں سے آزاد رکھوں گی تو اسے میری طرف سے قبول فرما تو تو سننے والا ہے جاننے والا ہے۔', 'جب کہا عمران کی عورت نے کہ اے رب میں نے نذر کیا تیرے جو کچھ میرے پیٹ میں ہے سب سے آزاد رکھ کر سو تو مجھ سے قبول کر بیشک تو ہی ہے اصل سننے والا جاننے والا [۵۳]', '(Remember) when the wife of Imran said: \"O my Lord! I have vowed to You what (the child that) is in my womb to be dedicated for Your services (free from all worldly work; to serve Your Place of worship), so accept this, from me. Verily, You are the All-Hearer, the All-Knowing.\"', '(Remember) when ‘Imrān’s wife said: “O my Lord, I have vowed that what is in my womb will be devoted exclusively for You. So, accept (it) from me. You, certainly You, are the All-Hearing, the All-Knowing.”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(329, 3, 36, 4, 12, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'فَلَمَّا وَضَعَتۡہَا قَالَتۡ رَبِّ اِنِّیۡ وَضَعۡتُہَاۤ  اُنۡثٰی ؕ وَ اللّٰہُ اَعۡلَمُ بِمَا وَضَعَتۡ ؕ وَ لَیۡسَ الذَّکَرُ  کَالۡاُنۡثٰی ۚ وَ اِنِّیۡ سَمَّیۡتُہَا مَرۡیَمَ وَ اِنِّیۡۤ  اُعِیۡذُہَا بِکَ وَ ذُرِّیَّتَہَا مِنَ الشَّیۡطٰنِ  الرَّجِیۡمِ ﴿۳۶﴾', 'پھر جب ان کے ہاں بچہ پیدا ہوا تو کہنے لگیں کہ پروردگار! میرے تو لڑکی ہوئی ہے جبکہ اللہ خوب جانتا تھا جو انکے ہاں ولادت ہوئی تھی اور نہ ہوتا لڑکا مانند اس لڑکی کے اور کہنے لگیں میں  نے اس کا نام مریم رکھا ہے اور میں اس کو اور اس کی اولاد کو شیطان مردود سے تیری پناہ میں دیتی ہوں۔', 'پھر جب اس کو جنا بولی اے رب میں نے تو اس کو لڑکی جنی [۵۴] اور اللہ کو خوب معلوم ہے جو کچھ اس نے جنا اور بیٹا نہ ہو جیسی وہ بیٹی [۵۵] اور میں نے اس کا نام رکھا مریم اور میں تیری پناہ میں دیتی ہوں اس کو اور اس کی اولاد کو شیطان مردود سے [۵۶]', 'Then when she delivered her (child Maryam (Mary)), she said: \"O my Lord! I have delivered a female child,\" - and Allah knew better what she delivered, - \"And the male is not like the female, and I have named her Maryam (Mary), and I seek refuge with You (Allah) for her and for her offspring from Shaitan (Satan), the outcast.\"', 'So, when she delivered her, she said: “O my Lord, I have delivered her, a female child.”-And Allah knew better what she had delivered, and the male was not like the female -” I have named her Maryam, and I place her and her progeny under Your shelter against Satan, the rejected.”'),
(330, 3, 37, 4, 12, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'فَتَقَبَّلَہَا رَبُّہَا بِقَبُوۡلٍ حَسَنٍ وَّ اَنۡۢبَتَہَا نَبَاتًا حَسَنًا ۙ وَّ کَفَّلَہَا زَکَرِیَّا ۚؕ کُلَّمَا دَخَلَ عَلَیۡہَا زَکَرِیَّا الۡمِحۡرَابَ ۙ وَجَدَ عِنۡدَہَا رِزۡقًا ۚ قَالَ یٰمَرۡیَمُ اَنّٰی لَکِ ہٰذَا ؕ قَالَتۡ ہُوَ مِنۡ عِنۡدِ اللّٰہِ ؕ اِنَّ اللّٰہَ یَرۡزُقُ مَنۡ یَّشَآءُ بِغَیۡرِ حِسَابٍ ﴿۳۷﴾', 'تو اسکے پروردگار نے اس کو پسندیدگی کے ساتھ قبول فرمایا اور اسے اچھی طرح پرورش کیا اور زکریا کو اس کا کفیل بنایا۔ زکریا جب کبھی عبادت گاہ میں اس کے پاس جاتے تو اسکے پاس کھانا پاتے یہ کیفیت دیکھ کر ایک دن مریم سے پوچھنے لگے کہ مریم یہ کھانا تمہارے پاس کہاں سے آتا ہے۔ وہ بولیں کہ اللہ کے ہاں سے آتا ہے بیشک اللہ جسے چاہتا ہے بے حساب رزق دیتا ہے۔', 'پھر قبول کیا اس کو اس کے رب نے اچھی طرح کا قبول اور بڑھایا ا سکو اچھی طرح بڑھانا اور سپرد کی زکریا کو [۵۷] جس وقت آتے اس کے پاس زکریا حجرے میں پاتے اس کے پاس کچھ کھانا [۵۸] کہا اے مریم کہاں سے آیا تیرے پاس یہ کہنے لگی یہ اللہ کے پاس سے آتا ہے اللہ رزق دیتا ہے جس کو چاہے بے قیاس [۵۹]', 'So her Lord (Allah) accepted her with goodly acceptance. He made her grow in a good manner and put her under the care of Zakariya (Zachariya). Every time he entered Al-Mihrab to (visit) her , he found her supplied with sustenance. He said: \"O Maryam (Mary)! From where have you got this?\" She said, \"This is from Allah.\" Verily, Allah provides sustenance to whom He wills, without limit.\"', 'So, her Lord accepted her, a good acceptance, and made her grow, a good growth, and made Zakariyyā her guardian. Whenever Zakariyyā visited her at the place of worship, he found food with her. He said: “Maryam, from where did you have this?” She said: “It is from Allah. Surely, Allah gives whom He wills without measure.”'),
(331, 3, 38, 4, 12, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'ہُنَالِکَ دَعَا زَکَرِیَّا رَبَّہٗ ۚ قَالَ رَبِّ ہَبۡ لِیۡ مِنۡ لَّدُنۡکَ ذُرِّیَّۃً طَیِّبَۃً ۚ اِنَّکَ سَمِیۡعُ  الدُّعَآءِ ﴿۳۸﴾', 'اس وقت زکریا نے اپنے پروردگار کو پکارا عرض کی کہ پروردگار مجھے اپنی طرف سے اولاد صالح عطا فرما۔ تو بےشک دعا سننے والا ہے۔', 'وہیں دعا کی زکریا نے اپنے رب سے کہا اے رب میرے عطا کر مجھ کو اپنے پاس سے اولاد پاکیزہ بیشک تو سننے والا ہے دعا کا [۶۰]', 'At that time Zakariya (Zachariya) invoked his Lord, saying: \"O my Lord! Grant me from You, a good offspring. You are indeed the All-Hearer of invocation.\"', 'Thereupon, Zakariyyā prayed to his Lord. He said: “O my Lord, grant me from Your own (power) a goodly progeny. Verily, You are the One who listens to the prayer.”'),
(332, 3, 39, 4, 12, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'فَنَادَتۡہُ  الۡمَلٰٓئِکَۃُ وَ ہُوَ قَآئِمٌ یُّصَلِّیۡ فِی الۡمِحۡرَابِ ۙ اَنَّ اللّٰہَ یُبَشِّرُکَ بِیَحۡیٰی مُصَدِّقًۢا بِکَلِمَۃٍ مِّنَ اللّٰہِ وَ سَیِّدًا وَّ حَصُوۡرًا وَّ نَبِیًّا مِّنَ الصّٰلِحِیۡنَ ﴿۳۹﴾', 'چنانچہ ابھی عبادت گاہ میں کھڑے نماز ہی پڑھ رہے تھے کہ فرشتوں نے آواز دی کہ زکریا اللہ تمہیں یحیٰی کی بشارت دیتا ہے جو کلمۃ اللہ یعنی عیسٰی کی تصدیق کریں گے اور سردار ہونگے اور عورتوں سے رغبت نہ رکھنے والے اور ایک پیغمبر یعنی نیکو کاروں میں ہونگے۔', 'پھر اس کو آواز دی فرشتوں نے جب وہ کھڑے تھے نماز میں حجرے کے اندر کہ اللہ تجھکو خوشخبری دیتا ہے یحیٰی کی [۶۱] جو گواہی دے گا اللہ کے ایک حکم کی [۶۲] اور سردار ہو گا اور عورت کے پاس نہ جائے گا [۶۳] اور نبی ہو گا صالحین سے [۶۴]', 'Then the angels called him, while he was standing in prayer in Al-Mihrab (a praying place or a private room), (saying): \"Allah gives you glad tidings of Yahya (John), confirming (believing in) the Word from Allah (i.e. the creation of Iesa (Jesus) , the Word from Allah (\"Be!\" - and he was!)), noble, keeping away from sexual relations with women, a Prophet, from among the righteous.\"', 'So then, when he stood praying in the place of worship, the angels called out to him saying: “Allah gives you the good news of YaHyā who shall come to confirm a word of Allah and shall be a chief, abstinent (from women), a prophet and one of the righteous.”'),
(333, 3, 40, 4, 12, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'قَالَ رَبِّ اَنّٰی یَکُوۡنُ لِیۡ غُلٰمٌ  وَّ قَدۡ بَلَغَنِیَ الۡکِبَرُ وَ امۡرَاَتِیۡ عَاقِرٌ ؕ قَالَ کَذٰلِکَ اللّٰہُ  یَفۡعَلُ مَا یَشَآءُ ﴿۴۰﴾', 'زکریا نے کہا اے پروردگار میرے ہاں لڑکا کیونکر پیدا ہو گا کہ میں تو بڈھا ہو گیا ہوں اور میری بیوی بانجھ ہے فرمایا اسی طرح اللہ جو چاہتا ہے کرتا ہے۔', 'کہا اے رب کہاں سے ہو گا میرے لڑکا اور پہنچ چکا مجھ کو بڑھاپا اور عورت میری بانجھ ہے فرمایا اسی طرح اللہ کرتا ہے جو چاہے [۶۵]', 'He said: \"O my Lord! How can I have a son when I am very old, and my wife is barren?\" Allah said: \"Thus Allah does what He wills.\"', 'He said: “O my Lord, how shall I have a boy when old age has come upon me and my wife is barren?” Said He: “That is how Allah does what He wills.”'),
(334, 3, 41, 4, 12, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'قَالَ رَبِّ اجۡعَلۡ لِّیۡۤ  اٰیَۃً ؕ قَالَ اٰیَتُکَ  اَلَّا تُکَلِّمَ النَّاسَ ثَلٰثَۃَ اَیَّامٍ  اِلَّا رَمۡزًا ؕ وَ اذۡکُرۡ رَّبَّکَ کَثِیۡرًا وَّ سَبِّحۡ بِالۡعَشِیِّ وَ الۡاِبۡکَارِ ﴿٪۴۱﴾', 'زکریا نے کہا کہ پروردگار میرے لئے کوئی نشانی مقرر فرما دے فرمایا نشانی یہ ہے کہ تم لوگوں سے تین دن اشارے کے سوا بات نہ کر سکو گے تو ان دنوں میں اپنے پروردگار کی کثرت سے یاد اور صبح و شام اس کی تسبیح کرنا۔', 'کہا اے رب مقرر کر میرے لئے کچھ نشانی [۶۶] فرمایا نشانی تیرے لئے یہ ہے کہ نہ بات کرے گا تو لوگوں سے تین دن مگراشارہ سے [۶۷] اور یاد کر اپنے رب کو بہت اور تسبیح کر شام اور صبح [۶۸]', 'He said: \"O my Lord! Make a sign for me.\" Allah said: \"Your sign is that you shall not speak to mankind for three days except with signals. And remember your Lord much (by praising Him again and again), and glorify (Him) in the afternoon and in the morning.\"', 'He said: “O my Lord, set for me a sign.” Said He: “Your sign is that you shall not be able to speak to people for three days except through gestures. Remember your Lord much; and proclaim His purity in the evening and the morning.”'),
(335, 3, 42, 5, 13, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'وَ اِذۡ قَالَتِ الۡمَلٰٓئِکَۃُ یٰمَرۡیَمُ اِنَّ اللّٰہَ اصۡطَفٰکِ وَ طَہَّرَکِ وَ اصۡطَفٰکِ عَلٰی نِسَآءِ  الۡعٰلَمِیۡنَ ﴿۴۲﴾', 'اور جب فرشتوں نے مریم سے کہا کہ مریم! اللہ نے تم کو برگزیدہ کیا ہے اور تمہیں پاک بنایا ہے اور دنیا جہان کی عورتوں میں سے تم کو منتخب کیا ہے۔', 'اور جب فرشتے بولے اے مریم اللہ نے تجھ کو پسند کیا اور ستھرا بنایا اور پسند کیا تجھ کو سب جہان کی عورتوں پر [۶۹]', 'And (remember) when the angels said: \"O Maryam (Mary)! Verily, Allah has chosen you, purified you (from polytheism and disbelief), and chosen you above the women of the Alameen (mankind and jinns) (of her lifetime).\"', 'And when the angels said: “O Maryam, Allah has chosen you and purified you and chosen you over the women of all the worlds.'),
(336, 3, 43, 5, 13, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'یٰمَرۡیَمُ اقۡنُتِیۡ لِرَبِّکِ وَ اسۡجُدِیۡ وَ ارۡکَعِیۡ مَعَ  الرّٰکِعِیۡنَ ﴿۴۳﴾', 'اے مریم اپنے پروردگار کی فرمانبرداری کرنا اور سجدہ کرنا اور رکوع کرنے والوں کے ساتھ رکوع کرنا۔', 'اے مریم بندگی کر اپنے رب کی اور سجدہ کر [۷۰] اور رکوع کر ساتھ رکوع کرنےوالوں کے [۷۱]', 'O Mary! \"Submit yourself with obedience to your Lord (Allah, by worshipping none but Him Alone) and prostrate yourself, and Irkai (bow down etc.) along with Ar-Rakioon (those who bow down etc.).\"', 'O Maryam, stand in devotion to your Lord and prostrate yourself and bow down in Rukū‘ with those who bow.”'),
(337, 3, 44, 5, 13, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'ذٰلِکَ مِنۡ اَنۡۢبَآءِ الۡغَیۡبِ نُوۡحِیۡہِ اِلَیۡکَ ؕ وَ مَا کُنۡتَ لَدَیۡہِمۡ  اِذۡ  یُلۡقُوۡنَ اَقۡلَامَہُمۡ اَیُّہُمۡ یَکۡفُلُ مَرۡیَمَ ۪ وَ مَا کُنۡتَ لَدَیۡہِمۡ  اِذۡ  یَخۡتَصِمُوۡنَ ﴿۴۴﴾', 'اے نبی یہ باتیں اخبار غیب میں سے ہیں جو ہم تمہارے پاس بھیجتے ہیں۔ اور جب وہ لوگ اپنے قلم بطور قرعہ ڈال رہے تھے کہ مریم کا کفیل کون بنے تو تم ان کے پاس نہیں تھے۔ اور نہ اس وقت ہی ان کے پاس تھے جب وہ آپس میں جھگڑ رہے تھے۔', 'یہ خبریں غیب کی ہیں جو ہم بھیجتے ہیں تجھکو [۷۲] اور تو نہ تھا ان کے پاس جب ڈالنے لگے اپنے قلم کہ کون پرورش میں لے مریم کو اور تو نہ تھا ان کے پاس جب وہ جھگڑتے تھے [۷۳]', 'This is a part of the news of the Ghaib (unseen, i.e. the news of the past nations of which you have no knowledge) which We inspire you with (O Muhammad SAW). You were not with them, when they cast lots with their pens as to which of them should be charged with the care of Maryam (Mary); nor were you with them when they disputed.', 'This is a part of the news of the unseen We reveal to you (O Prophet!). You were not with them when they were casting their pens (to decide) who, from among them, should be the guardian of Maryam, nor were you with them when they were quarrelling.'),
(338, 3, 45, 5, 13, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اِذۡ قَالَتِ الۡمَلٰٓئِکَۃُ یٰمَرۡیَمُ اِنَّ اللّٰہَ یُبَشِّرُکِ بِکَلِمَۃٍ مِّنۡہُ ٭ۖ اسۡمُہُ الۡمَسِیۡحُ عِیۡسَی ابۡنُ مَرۡیَمَ وَجِیۡہًا فِی الدُّنۡیَا وَ الۡاٰخِرَۃِ  وَ مِنَ الۡمُقَرَّبِیۡنَ ﴿ۙ۴۵﴾', 'وہ وقت بھی یاد کرنے کے لائق ہے جب فرشتوں نے مریم سے کہا کہ مریم اللہ تم کو اپنی طرف سے ایک کلمہ کی بشارت دیتا ہے جس کا نام مسیح اور مشہور عیسٰی ابن مریم ہو گا اور جو دنیا اور آخرت میں آبرومند اور مقربین میں سے ہو گا۔', 'جب کہا فرشتوں نے اے مریم اللہ تجھ کو بشارت دیتا ہے ایک اپنے حکم کی جس کا نام مسیح ہے عیسیٰ مریم کا بیٹا مرتبہ والا دنیا میں اور آخرت میں اور اللہ کے مقربوں میں [۷۴]', '(Remember) when the angels said: \"O Maryam (Mary)! Verily, Allah gives you the glad tidings of a Word (\"Be!\" - and he was! i.e. Iesa (Jesus) the son of Maryam (Mary)) from Him, his name will be the Messiah Iesa (Jesus), the son of Maryam (Mary), held in honour in this world and in the Hereafter, and will be one of those who are near to Allah.\"', '(Remember the time) when the angels said: “O Maryam, Allah gives you the good news of a Word from Him whose name is MasīH ‘Īsā , the son of Maryam (the Messiah, Jesus, son of Mary) a man of status in this world and in the Hereafter, and one of those who are near (to Allah).'),
(339, 3, 46, 5, 13, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'وَ یُکَلِّمُ النَّاسَ فِی الۡمَہۡدِ وَ کَہۡلًا  وَّ مِنَ  الصّٰلِحِیۡنَ ﴿۴۶﴾', 'اور ماں کی گود میں اور بڑی عمر کا ہو کر دونوں حالتوں میں لوگوں سے یکساں گفتگو کرے گا اور نیکوکاروں میں ہو گا۔', 'اور باتیں کرے گا لوگوں سے جبکہ ماں کی گود میں ہو گا اور جبکہ پوری عمر کا ہو گا اور نیک بختوں میں ہے [۷۵]', '\"He will speak to the people in the cradle and in manhood, and he will be one of the righteous.\"', 'He shall speak to people while (he is still) in the cradle, and also later, when he is of mature age; and he shall be one of the righteous.”'),
(340, 3, 47, 5, 13, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'قَالَتۡ رَبِّ اَنّٰی یَکُوۡنُ لِیۡ وَلَدٌ وَّ لَمۡ یَمۡسَسۡنِیۡ بَشَرٌ ؕ قَالَ کَذٰلِکِ اللّٰہُ یَخۡلُقُ مَا  یَشَآءُ ؕ اِذَا قَضٰۤی اَمۡرًا فَاِنَّمَا یَقُوۡلُ لَہٗ  کُنۡ فَیَکُوۡنُ ﴿۴۷﴾', 'مریم نے کہا کہ پروردگار میرے ہاں بچہ کیونکر ہوگا کہ کسی انسان نے مجھے ہاتھ تک تو لگایا نہیں فرمایا کہ اللہ اسی طرح جو چاہتا ہے پیدا کرتا ہے۔ جب وہ کوئی کام کرنا چاہتا ہے تو ارشاد فرما دیتا ہے کہ ہو جا تو وہ ہو جاتا ہے۔', 'بولی اے رب کہاں سے ہو گا میرے لڑکا اور مجھ کو ہاتھ نہیں لگایا کسی آدمی نے [۷۶] فرمایا اسی طرح اللہ پیدا کرتا ہے جو چاہے جب ارادہ کرتا ہے کسی کام کا تو یہی کہتا ہے اس کو کہ ہو جا سو وہ ہو جاتا ہے [۷۷]', 'She said: \"O my Lord! How shall I have a son when no man has touched me.\" He said: \"So (it will be) for Allah creates what He wills. When He has decreed something, He says to it only: \"Be!\" and it is.', 'She said: “O my Lord, how shall I have a son while no human has ever touched me?” Said He: “That is how Allah creates what He wills. When He decides a matter, He simply says to it ‘Be’, and it comes to be.'),
(341, 3, 48, 5, 13, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'وَ یُعَلِّمُہُ الۡکِتٰبَ وَ الۡحِکۡمَۃَ وَ التَّوۡرٰىۃَ  وَ الۡاِنۡجِیۡلَ ﴿ۚ۴۸﴾', 'اور وہ اسے کتاب و حکمت اور تورات اور انجیل کا علم عطا کرے گا۔', 'اور سکھاوےگا اس کو کتاب اور تہ کی باتیں اور تورات اور انجیل [۷۸]', 'And He (Allah) will teach him (Iesa (Jesus)) the Book and Al-Hikmah (i.e. the Sunnah, the faultless speech of the Prophets, wisdom, etc.), (and) the Taurat (Torah) and the Injeel (Gospel).', 'He shall teach him the Book and the Wisdom, and the Torah and the Injīl,'),
(342, 3, 49, 5, 13, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'وَ رَسُوۡلًا اِلٰی بَنِیۡۤ  اِسۡرَآءِیۡلَ ۬ۙ اَنِّیۡ قَدۡ جِئۡتُکُمۡ بِاٰیَۃٍ مِّنۡ رَّبِّکُمۡ ۙ اَنِّیۡۤ  اَخۡلُقُ لَکُمۡ مِّنَ الطِّیۡنِ کَہَیۡـَٔۃِ الطَّیۡرِ فَاَنۡفُخُ فِیۡہِ فَیَکُوۡنُ طَیۡرًۢا بِاِذۡنِ اللّٰہِ ۚ وَ اُبۡرِیُٔ الۡاَکۡمَہَ وَ الۡاَبۡرَصَ وَ اُحۡیِ الۡمَوۡتٰی بِاِذۡنِ اللّٰہِ ۚ  وَ اُنَبِّئُکُمۡ بِمَا تَاۡکُلُوۡنَ وَ مَا تَدَّخِرُوۡنَ ۙ فِیۡ بُیُوۡتِکُمۡ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیَۃً لَّکُمۡ اِنۡ کُنۡتُمۡ مُّؤۡمِنِیۡنَ ﴿ۚ۴۹﴾', 'اور عیسٰی بنی اسرائیل کی طرف پیغمبر ہو کر جائیں گے اور کہیں گے کہ میں تمہارے پاس تمہارے پروردگار کی طرف سے نشانی لے کر آیا ہوں۔ وہ یہ کہ تمہارے سامنے مٹی سے پرندے کی صورت بناتا ہوں پھر اس میں پھونک مارتا ہوں تو وہ اللہ کے حکم سے سچ مچ پرندہ ہو جاتا ہے۔ اور پیدائشی اندھے اور ابرص کو تندرست کر دیتا ہوں۔ اور اللہ کے حکم سے مردوں کو زندہ کر دیتا ہوں۔ اور جو کچھ تم کھا کر آتے ہو اور جو اپنے گھروں میں جمع کر رکھتے ہو سب تم کو بتا دیتا ہوں اگر تم صاحب ایمان ہو تو ان باتوں میں تمہارے لئے نشانی ہے۔', 'اور کرے گا اس کو پیغمبر بنی اسرائیل کی طرف بیشک میں آیا ہوں تمہارےپاس نشانیاں لے کر تمہارے رب کی طرف سے [۷۹] کہ میں بنا دیتا ہوں تم کو گارے سے پرندہ کی شکل پھر اس میں پھونک مارتا ہوں تو ہو جاتا ہے وہ اڑتا جانور اللہ کے حکم سے [۸۰] اور اچھا کرتا ہوں مادر زاد اندھے کو اور کوڑھی کو اور جلاتا ہوں مردے اللہ کے حکم سے [۸۱] اور بتا دیتا ہوں تم کو جو کھا کر آؤ اور جو رکھ آؤ اپنے گھر میں [۸۲] اس میں نشانی پوری ہے تم کو اگر تم یقین رکھتے ہو', 'And will make him (Iesa (Jesus)) a Messenger to the Children of Israel (saying): \"I have come to you with a sign from your Lord, that I design for you out of clay, as it were, the figure of a bird, and breathe into it, and it becomes a bird by Allahs Leave; and I heal him who was born blind, and the leper, and I bring the dead to life by Allahs Leave. And I inform you of what you eat, and what you store in your houses. Surely, therein is a sign for you, if you believe.', 'and (shall make him) a messenger to the Children of Isrā’īl (who will say to them): “I have come to you with a sign from your Lord, that is, I create for you from clay something in the shape of a bird, then I blow in it, and it becomes a living bird by the will of Allah; and I cure the born-blind and the leper, and I cause the dead to become alive by the will of Allah; and I inform you of what you eat and what you store in your homes. In this there is surely a sign for you, if you are (truly) believers.'),
(343, 3, 50, 5, 13, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'وَ مُصَدِّقًا لِّمَا بَیۡنَ یَدَیَّ مِنَ التَّوۡرٰىۃِ وَ لِاُحِلَّ لَکُمۡ بَعۡضَ الَّذِیۡ حُرِّمَ عَلَیۡکُمۡ وَ جِئۡتُکُمۡ بِاٰیَۃٍ مِّنۡ  رَّبِّکُمۡ ۟ فَاتَّقُوا اللّٰہَ وَ اَطِیۡعُوۡنِ ﴿۵۰﴾', 'اور مجھ سے پہلے جو تورات نازل ہوئی تھی اس کی تصدیق بھی کرتا ہوں اور میں اس لئے بھی آیا ہوں کہ بعض چیزیں جو تم پر حرام تھیں ان کو تمہارے لئے حلال کردوں اور میں تو تمہارے پروردگار کی طرف سے نشانی لے کر آیا ہوں تو اللہ سے ڈرو اور میرا کہا مانو۔', 'اور سچا بتاتا ہوں اپنےسے پہلی کتاب کو جو توریت ہے اور اس واسطے کہ حلال کر دوں تم کو بعضی وہ چیزیں جو حرام تھیں تم پر [۸۳] اور آیا ہوں تمہارے پاس نشانی لے کر تمہارے رب کی سو ڈرو اللہ سے اور میرا کہا مانو [۸۴]', 'And I have come confirming that which was before me of the Taurat (Torah), and to make lawful to you part of what was forbidden to you, and I have come to you with a proof from your Lord. So fear Allah and obey me.', '(I have come to you) confirming that (book) which is (sent down) prior to me, that is, the Torah, and to make permissible for you some of what was prohibited to you. I have come to you with a sign from your Lord. So, fear Allah and obey me.'),
(344, 3, 51, 5, 13, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اِنَّ اللّٰہَ رَبِّیۡ وَ رَبُّکُمۡ فَاعۡبُدُوۡہُ ؕ ہٰذَا صِرَاطٌ  مُّسۡتَقِیۡمٌ ﴿۵۱﴾', 'کچھ شک نہیں کہ اللہ ہی میرا اور تمہارا پروردگار ہے تو اسی کی عبادت کرو یہی سیدھا رستہ ہے۔', 'بیشک اللہ ہے رب میرا اور رب تمہارا سو اس کی بندگی کرو یہی راہ سیدھی ہے [۸۵]', 'Truly! Allah is my Lord and your Lord, so worship Him (Alone). This is the Straight Path.', 'Allah is surely my Lord and your Lord. So, worship Him. This is the straight path.”'),
(345, 3, 52, 5, 13, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'فَلَمَّاۤ  اَحَسَّ عِیۡسٰی مِنۡہُمُ الۡکُفۡرَ قَالَ مَنۡ اَنۡصَارِیۡۤ اِلَی اللّٰہِ ؕ قَالَ الۡحَوَارِیُّوۡنَ نَحۡنُ اَنۡصَارُ اللّٰہِ ۚ اٰمَنَّا بِاللّٰہِ ۚ وَ اشۡہَدۡ بِاَنَّا مُسۡلِمُوۡنَ ﴿۵۲﴾', 'پھر جب عیسٰی نے انکی طرف سے انکار اور نافرمانی ہی دیکھی تو کہنے لگے کہ کوئی ہے جو اللہ کا طرفدار اور میرا مددگار ہو۔ حواری بولے کہ ہم اللہ کے طرفدار اور آپ کے مددگار ہیں ہم اللہ پر ایمان لائے اور آپ گواہ رہیں کہ ہم فرمانبردار ہیں۔', 'پھر جب معلوم کیا عیسٰی نے بنی اسرائیل کا کفر [۸۶] بولا کون ہے کہ میری مدد کرے اللہ کی راہ میں [۸۷] کہا حواریوں نے ہم ہیں مدد کرنے والے اللہ کی [۸۸] ہم یقین لائے اللہ پر اور تو گواہ رہ کہ ہم نے حکم قبول کیا [۸۹]', 'Then when Iesa (Jesus) came to know of their disbelief, he said: \"Who will be my helpers in Allahs Cause?\" Al-Hawarioon (the disciples) said: \"We are the helpers of Allah; we believe in Allah, and bear witness that we are Muslims (i.e. we submit to Allah).\"', 'So, when ‘Īsā sensed disbelief in them, he said: “Who are my helpers in the way of Allah?” The disciples said: “We are helpers of Allah. We believe in Allah; so be our witness that we are Muslims.”'),
(346, 3, 53, 5, 13, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'رَبَّنَاۤ  اٰمَنَّا بِمَاۤ اَنۡزَلۡتَ وَ اتَّبَعۡنَا الرَّسُوۡلَ فَاکۡتُبۡنَا مَعَ الشّٰہِدِیۡنَ ﴿۵۳﴾', 'اے پروردگار جو کتاب تو نے نازل فرمائی ہے ہم اس پر ایمان لے آئے اور تیرے پیغمبر کے متبع ہو چکے تو ہم کو ماننے والوں میں لکھ رکھ۔', 'اے رب ہم نے یقین کیا اس چیز کا جو تو نے اتاری اور ہم تابع ہوئے رسول کے سو تو لکھ لے ہم کو ماننے والوں میں [۹۰]', 'Our Lord! We believe in what You have sent down, and we follow the Messenger (Iesa (Jesus)); so write us down among those who bear witness (to the truth i.e. La ilaha ill-Allah - none has the right to be worshipped but Allah).', '“Our Lord, we have believed in what You have revealed, and we have followed the messenger. So, record us with those who bear witness (to the Truth).”'),
(347, 3, 54, 5, 13, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'وَ مَکَرُوۡا وَ مَکَرَ اللّٰہُ ؕ وَ اللّٰہُ خَیۡرُ الۡمٰکِرِیۡنَ ﴿٪۵۴﴾', 'اور وہ یعنی یہود قتل عیسٰی کے بارے میں ایک چال چلے اور اللہ نے بھی عیسٰی کو بچانے کے لئے تدبیر کی اور اللہ بہترین تدبیر کرنے والا ہے۔', 'اور مکر کیا ان کافروں نے اور مکر کیا اللہ نے اور اللہ کا داؤ سب سے بہتر ہے [۹۱]', 'And they (disbelievers) plotted (to kill Iesa (Jesus) ), and Allah planned too. And Allah is the Best of the planners.', 'They (the opponents of ‘Īsā) devised a plan, and Allah devised a plan. And Allah is the best of all planners.'),
(348, 3, 55, 6, 14, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اِذۡ قَالَ اللّٰہُ یٰعِیۡسٰۤی اِنِّیۡ مُتَوَفِّیۡکَ وَ رَافِعُکَ اِلَیَّ وَ مُطَہِّرُکَ مِنَ الَّذِیۡنَ کَفَرُوۡا  وَ جَاعِلُ الَّذِیۡنَ اتَّبَعُوۡکَ فَوۡقَ الَّذِیۡنَ کَفَرُوۡۤا اِلٰی یَوۡمِ الۡقِیٰمَۃِ ۚ ثُمَّ  اِلَیَّ مَرۡجِعُکُمۡ فَاَحۡکُمُ بَیۡنَکُمۡ فِیۡمَا کُنۡتُمۡ  فِیۡہِ  تَخۡتَلِفُوۡنَ ﴿۵۵﴾', 'اس وقت اللہ نے فرمایا کہ عیسٰی! میں تمہاری دنیا میں رہنے کی مدت پوری کر کے تم کو اپنی طرف اٹھا لوں گا اور تمہیں کافروں کی صحبت سے پاک کر دوں گا۔ اور جو لوگ تمہاری پیروی کریں گے ان کو کافروں پر قیامت تک فائق و غالب رکھوں گا پھر تم سب میرے پاس لوٹ کر آؤ گے تو جن باتوں میں تم اختلاف کرتے رہے اس دن تم میں ان کا فیصلہ کر دوں گا۔', 'جس وقت کہا اللہ نے اے عیسٰی میں لے لوں گا تجھ کو اور اٹھا لوں گا اپنی طرف اور پاک کروں گا تجھ کو کافروں سے اور رکھوں گا ان کو جو تیرے تابع ہیں غالب ان سے جو انکار کرتے ہیں قیامت کے دن تک پھر میری طرف ہے تم سب کو پھر آنا پھر فیصلہ کر دوں گا تم میں جس بات میں تم جھگڑتے تھے', 'And (remember) when Allah said: \"O Iesa (Jesus)! I will take you and raise you to Myself and clear you (of the forged statement that Iesa (Jesus) is Allahs son) of those who disbelieve, and I will make those who follow you (Monotheists, who worship none but Allah) superior to those who disbelieve (in the Oneness of Allah, or disbelieve in some of His Messengers, e.g. Muhammad SAW, Iesa (Jesus), Moosa (Moses), etc., or in His Holy Books, e.g. the Taurat (Torah), the Injeel (Gospel), the Quran) till the Day of Resurrection. Then you will return to Me and I will judge between you in the matters in which you used to dispute.\"', 'When Allah said: “O ‘Īsā , I am to take you in full and to raise you towards Myself, and to cleanse you of those who disbelieve, and to place those who follow you above those who disbelieve up to the Day of Doom. Then to Me is your return, whereupon I shall judge between you in that over which you have differed.'),
(349, 3, 56, 6, 14, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'فَاَمَّا الَّذِیۡنَ کَفَرُوۡا فَاُعَذِّبُہُمۡ عَذَابًا شَدِیۡدًا فِی الدُّنۡیَا وَ الۡاٰخِرَۃِ ۫ وَ مَا لَہُمۡ مِّنۡ نّٰصِرِیۡنَ ﴿۵۶﴾', 'اب جو کافر ہوئے ان کو دنیا اور آخرت دونوں میں سخت عذاب دوں گا اور ان کا کوئی مددگار نہ ہو گا۔', 'سو وہ لوگ جو کافر ہوئے ان کو عذاب کروں گا سخت عذاب دنیا میں اور آخرت میں اور کوئی نہیں ان کا مددگار', '\"As to those who disbelieve, I will punish them with a severe torment in this world and in the Hereafter, and they will have no helpers.\"', 'As for those who disbelieve, I shall punish them a severe punishment in this world and in the Hereafter; and for them there are no helpers.”'),
(350, 3, 57, 6, 14, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'وَ اَمَّا الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ فَیُوَفِّیۡہِمۡ اُجُوۡرَہُمۡ ؕ وَ اللّٰہُ لَا یُحِبُّ الظّٰلِمِیۡنَ ﴿۵۷﴾', 'اور جو لوگ ایمان لائے اور عمل نیک کرتے رہے ان کو اللہ پورا پورا صلہ دے گا اور اللہ ظالموں کو دوست نہیں رکھتا۔', 'اور وہ لوگ جو ایمان لائے اور کام نیک کئے سو انکو پورا دے گا ان کا حق اور اللہ کو خوش نہیں آتے بے انصاف [۹۲]', 'And as for those who believe (in the Oneness of Allah) and do righteous good deeds, Allah will pay them their reward in full. And Allah does not like the Zalimoon (polytheists and wrong-doers).', 'As for those who believe and do good deeds, He (Allah) will give them their rewards in full. Allah does not like transgressors.'),
(351, 3, 58, 6, 14, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'ذٰلِکَ نَتۡلُوۡہُ عَلَیۡکَ مِنَ الۡاٰیٰتِ وَ الذِّکۡرِ الۡحَکِیۡمِ ﴿۵۸﴾', 'اے نبی یہ ہم تم کو اللہ کی آیتیں اور حکمت بھری نصیحتیں پڑھ پڑھ کر سناتے ہیں۔', 'یہ پڑھ کو سناتے ہیں ہم تجھ کو آیتیں اور بیان تحقیقی', 'This is what We recite to you (O Muhammad SAW) of the Verses and the Wise Reminder (i.e. the Quran).', 'This We recite to you of the Verses and the Message that is full of wisdom.'),
(352, 3, 59, 6, 14, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اِنَّ مَثَلَ عِیۡسٰی عِنۡدَ اللّٰہِ کَمَثَلِ اٰدَمَ ؕ خَلَقَہٗ مِنۡ تُرَابٍ ثُمَّ قَالَ لَہٗ  کُنۡ فَیَکُوۡنُ ﴿۵۹﴾', 'عیسٰی کا حال اللہ کے نزدیک آدم کا سا ہے کہ اس نے پہلے مٹی سے انکو بنایا پھر فرمایا باشعور انسان ہو جا تو وہ ویسے ہی گئے۔', 'بیشک عیسٰی کی مثال اللہ کے نزدیک جیسے مثال آدم کی بنایا اس کو مٹی سے پھر کہا اس کو کہ ہو جا وہ ہو گیا [۹۳]', 'Verily, the likeness of Iesa (Jesus) before Allah is the likeness of Adam. He created him from dust, then (He) said to him: \"Be!\" - and he was.', 'Surely, the case of ‘Īsā , in the sight of Allah, is like the case of ’Edam . He created him from dust, then He said to him, “Be”, and he came to be.'),
(353, 3, 60, 6, 14, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اَلۡحَقُّ مِنۡ رَّبِّکَ فَلَا تَکُنۡ مِّنَ الۡمُمۡتَرِیۡنَ ﴿۶۰﴾', 'یہ بات تمہارے پروردگار کی طرف سے حق ہے تو تم ہر گز شک کرنے والوں میں نہ ہونا۔', 'حق وہ ہے جو تیرا رب کہے پھر تو مت رہ شک لانے والوں سے [۹۴]', '(This is) the truth from your Lord, so be not of those who doubt.', 'The truth is from your Lord. So, do not be of those who doubt.'),
(354, 3, 61, 6, 14, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'فَمَنۡ حَآجَّکَ فِیۡہِ مِنۡۢ بَعۡدِ مَا جَآءَکَ مِنَ الۡعِلۡمِ فَقُلۡ تَعَالَوۡا نَدۡعُ اَبۡنَآءَنَا وَ اَبۡنَآءَکُمۡ وَ نِسَآءَنَا وَ نِسَآءَکُمۡ وَ اَنۡفُسَنَا وَ اَنۡفُسَکُمۡ ۟ ثُمَّ نَبۡتَہِلۡ فَنَجۡعَلۡ لَّعۡنَتَ اللّٰہِ عَلَی الۡکٰذِبِیۡنَ ﴿۶۱﴾', 'پھر اگر یہ لوگ عیسٰی کے بارے میں تم سے جھگڑا کریں اسکے بعد کہ تم کو حقیقت معلوم ہو ہی چلی ہے تو ان سے کہنا کہ آؤ ہم اپنے بیٹوں اور بیٹیوں کو بلائیں تم اپنے بیٹوں اور بیٹیوں کو بلاؤ اور ہم خود بھی آئیں اور تم خود بھی آؤ پھر دونوں فریق اللہ سے دعا و التجا کریں اس طرح جھوٹوں پر اللہ کی لعنت بھیجیں۔', 'پھر جو کوئی جھگڑا کرے تجھ سے اس قصہ میں بعد اس کے کہ آ چکی تیرے پاس خبر سچی تو تو کہدے آؤ بلادیں ہم اپنے بیٹے اور تمہارے بیٹے اور اپنی عورتیں اور تمہاری عورتیں اور اپنی جان اور تمہاری جان پھر التجا کریں ہم سب اور لعنت کریں اللہ کی ان پر کہ جو جھوٹے ہیں [۹۵]', 'Then whoever disputes with you concerning him (Iesa (Jesus)) after (all this) knowledge that has come to you, (i.e. Iesa (Jesus)) being a slave of Allah, and having no share in Divinity) say: (O Muhammad SAW) \"Come, let us call our sons and your sons, our women and your women, ourselves and yourselves - then we pray and invoke (sincerely) the Curse of Allah upon those who lie.\"', 'If someone argues with you (O Prophet) over this after the knowledge that has come to you, say (to him), “Come, let us call our sons and your sons, our women and your women, ourselves and yourselves, then (let us) pray and invoke the curse of Allah upon the liars.”'),
(355, 3, 62, 6, 14, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اِنَّ ہٰذَا لَہُوَ الۡقَصَصُ الۡحَقُّ ۚ وَ مَا مِنۡ  اِلٰہٍ  اِلَّا اللّٰہُ ؕ وَ اِنَّ اللّٰہَ لَہُوَ الۡعَزِیۡزُ الۡحَکِیۡمُ ﴿۶۲﴾', 'یہ تمام بیانات صحیح ہیں۔ اور اللہ کے سوا کو ئی معبود نہیں۔ اور بے شک اللہ غالب ہے صاحب حکمت ہے۔', 'بیشک یہی ہے بیان سچا اور کسی کی بندگی نہیں ہے سوا اللہ کے [۹۶] اور اللہ جو ہے وہی ہے زبردست حکمت والا [۹۷]', 'Verily! This is the true narrative (about the story of Iesa (Jesus)), and, La ilaha ill-Allah (none has the right to be worshipped but Allah, the One and the Only True God, Who has neither a wife nor a son). And indeed, Allah is the All-Mighty, the All-Wise.', 'This is, indeed, the true narration. There exists no god but Allah. Allah is surely the Almighty, the All-Wise.'),
(356, 3, 63, 6, 14, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'فَاِنۡ تَوَلَّوۡا فَاِنَّ اللّٰہَ عَلِیۡمٌۢ  بِالۡمُفۡسِدِیۡنَ ﴿٪۶۳﴾', 'پس اگر یہ لوگ پھر جائیں تو اللہ مفسدوں کو خوب جانتا ہے۔', 'پھر اگر قبول نہ کریں تو اللہ کو معلوم ہے فساد کرنے والے [۹۸]', 'And if they turn away (and do not accept these true proofs and evidences), then surely, Allah is All-Aware of those who do mischief.', 'So, should they turn back, Allah is fully aware of the mischievous people.'),
(357, 3, 64, 7, 15, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'قُلۡ یٰۤاَہۡلَ الۡکِتٰبِ تَعَالَوۡا اِلٰی کَلِمَۃٍ سَوَآءٍۢ  بَیۡنَنَا وَ بَیۡنَکُمۡ اَلَّا نَعۡبُدَ اِلَّا اللّٰہَ وَ لَا نُشۡرِکَ بِہٖ شَیۡئًا وَّ لَا یَتَّخِذَ بَعۡضُنَا بَعۡضًا اَرۡبَابًا مِّنۡ دُوۡنِ اللّٰہِ ؕ فَاِنۡ تَوَلَّوۡا فَقُوۡلُوا اشۡہَدُوۡا بِاَنَّا مُسۡلِمُوۡنَ ﴿۶۴﴾', 'کہدو کہ اے اہل کتاب جو بات ہمارے اور تمہارے دونوں کے درمیان یکساں تسلیم کی گئ ہے اس کی طرف آؤ وہ یہ کہ اللہ کے سوا ہم کسی کی عبادت نہ کریں۔ اور اس کے ساتھ کسی چیز کو شریک نہ بنائیں اور ہم میں کوئی کسی کو اللہ کے سوا اپنا کارساز نہ سمجھے۔ پھر اگر یہ لوگ اس بات کو نہ مانیں تو ان سے کہدو کہ تم گواہ رہو کہ ہم اللہ کے فرمانبردار ہیں۔', 'تو کہہ اے اہل کتاب آؤ ایک بات کی طرف جو برابر ہے ہم میں اور تم میں کہ بندگی نہ کریں ہم مگر اللہ کی اور شریک نہ ٹھہراویں اس کا کسی کو اور نہ بناوے کوئی کسی کو رب سوا اللہ کے [۹۹] پھر اگر وہ قبول نہ کریں تو کہہ دو گواہ رہو کہ ہم تو حکم کے تابع ہیں [۱۰۰]', 'Say (O Muhammad SAW): \"O people of the Scripture (Jews and Christians): Come to a word that is just between us and you, that we worship none but Allah, and that we associate no partners with Him, and that none of us shall take others as lords besides Allah. Then, if they turn away, say: \"Bear witness that we are Muslims.\"', 'Say, “O people of the Book, come to a word common between us and between you, that we worship none but Allah, that we associate nothing with Him and that some of us do not take others as Lords instead of Allah.” Then, should they turn back, say, “Bear witness that we are Muslims.”'),
(358, 3, 65, 7, 15, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'یٰۤاَہۡلَ الۡکِتٰبِ لِمَ تُحَآجُّوۡنَ فِیۡۤ اِبۡرٰہِیۡمَ وَ مَاۤ اُنۡزِلَتِ التَّوۡرٰىۃُ وَ الۡاِنۡجِیۡلُ  اِلَّا مِنۡۢ بَعۡدِہٖ ؕ اَفَلَا  تَعۡقِلُوۡنَ ﴿۶۵﴾', 'اے اہل کتاب تم ابراہیم کے بارے میں کیوں  جھگڑتے ہو حالانکہ تورات اور انجیل ان کے بعد اتری ہیں اور وہ پہلے ہو چکے تو کیا تم عقل نہیں رکھتے۔', 'اے اہل کتاب کیوں جھگڑتے ہو ابراہیم کی بابت اور توریت اور انجیل تو اتریں اس کے بعد کیا تم کو عقل نہیں', 'O people of the Scripture (Jews and Christians)! Why do you dispute about Ibrahim (Abraham), while the Taurat (Torah) and the Injeel (Gospel) were not revealed till after him? Have you then no sense?', 'O people of the Book, why do you argue about Ibrāhīm, while the Torah and the Injīl were not revealed until after him? Have you, then, no sense?'),
(359, 3, 66, 7, 15, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'ہٰۤاَنۡتُمۡ  ہٰۤؤُلَآءِ  حَاجَجۡتُمۡ فِیۡمَا لَکُمۡ بِہٖ عِلۡمٌ فَلِمَ تُحَآجُّوۡنَ فِیۡمَا لَیۡسَ لَکُمۡ بِہٖ عِلۡمٌ ؕ وَ اللّٰہُ یَعۡلَمُ وَ اَنۡتُمۡ لَا تَعۡلَمُوۡنَ ﴿۶۶﴾', 'دیکھو ایسی بات میں تو تم نے جھگڑا کیا ہی تھا جس کا تمہیں کچھ علم تھا بھی۔ مگر ایسی بات میں کیوں جھگڑتے ہو جس کا تم کو کچھ بھی علم نہیں۔ اور اللہ جانتا ہے اور تم نہیں جانتے۔', 'سنتے ہو تم لوگ جھگڑ چکے جس بات میں تم کو کچھ خبر تھی اب کیوں جھگڑتے ہو جس بات میں تم کو کچھ خبر نہیں اور اللہ جانتا ہے اور تم نہیں جانتے [۱۰۱]', 'Verily, you are those who have disputed about that of which you have knowledge. Why do you then dispute concerning that which you have no knowledge? It is Allah Who knows, and you know not.', 'Look, this is what you are - you have already argued about matters concerning which you have knowledge; why then do you argue about matters of which you have no knowledge? Allah knows and you do not know.'),
(360, 3, 67, 7, 15, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'مَا کَانَ  اِبۡرٰہِیۡمُ یَہُوۡدِیًّا وَّ لَا نَصۡرَانِیًّا وَّ لٰکِنۡ کَانَ حَنِیۡفًا مُّسۡلِمًا ؕ وَ مَا کَانَ مِنَ الۡمُشۡرِکِیۡنَ ﴿۶۷﴾', 'ابراہیم نہ تو یہودی تھے اور نہ عیسائی بلکہ سب سے بے تعلق ہو کر ایک اللہ کے ہو رہے تھے اور اسی کے فرمانبردار تھے اور مشرکوں میں نہ تھے۔', 'نہ تھا ابراہیم یہودی اور نہ تھا نصرانی لیکن تھا حنیف یعنی سب جھوٹے مذہبوں سے بیزار اور حکم بردار اور نہ تھا مشرک [۱۰۲]', 'Ibrahim (Abraham) was neither a Jew nor a Christian, but he was a true Muslim Hanifa (Islamic Monotheism - to worship none but Allah Alone) and he was not of Al-Mushrikoon (See V.2:105).', 'Ibrāhīm was neither a Jew nor a Christian. But he was upright, a Muslim, and was not one of those who associate partners with Allah.'),
(361, 3, 68, 7, 15, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اِنَّ اَوۡلَی النَّاسِ بِاِبۡرٰہِیۡمَ لَلَّذِیۡنَ اتَّبَعُوۡہُ وَ ہٰذَا النَّبِیُّ وَ الَّذِیۡنَ  اٰمَنُوۡا ؕ وَ اللّٰہُ وَلِیُّ  الۡمُؤۡمِنِیۡنَ ﴿۶۸﴾', 'ابراہیم سے زیادہ قرب رکھنے والے تو وہ لوگ ہیں جو ان کی پیروی کرتے رہے اور یہ پیغمبر آخرالزماں ﷺ اور وہ لوگ جو ایمان لائے ہیں۔ اور اللہ مومنوں کا کارساز ہے۔', 'لوگوں میں زیادہ مناسبت ابراہیم سے ان کو تھی جو ساتھ اس کے تھے اور اس نبی کو اور جو ایمان لائے اس نبی پر [۱۰۳] اور اللہ والی ہے مسلمانوں کا [۱۰۴]', 'Verily, among mankind who have the best claim to Ibrahim (Abraham) are those who followed him, and this Prophet (Muhammad SAW) and those who have believed (Muslims). And Allah is the Walee (Protector and Helper) of the believers.', 'The closest of people to Ibrāhīm are those who followed him, and this prophet, and those who believe; and Allah is the Guardian of all believers.'),
(362, 3, 69, 7, 15, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'وَدَّتۡ طَّآئِفَۃٌ مِّنۡ اَہۡلِ الۡکِتٰبِ لَوۡ یُضِلُّوۡنَکُمۡ ؕ وَ مَا یُضِلُّوۡنَ  اِلَّاۤ اَنۡفُسَہُمۡ  وَ مَا یَشۡعُرُوۡنَ ﴿۶۹﴾', 'اے اہل اسلام بعضے اہل کتاب اس بات کی خواہش رکھتے ہیں کہ کسی طرح تم کو گمراہ کر دیں۔ حالانکہ یہ تم کو کیا گمراہ کریں گے اپنے آپ کو ہی گمراہ کر رہے ہیں اور نہیں جانتے۔', 'آرزو ہے بعضے اہل کتاب کو کہ کسی طرح گمراہ کریں تم کو اور گمراہ نہیں کرتے مگر اپنے آپ کو اور نہیں سمجھتے [۱۰۵]', 'A party of the people of the Scripture (Jews and Christians) wish to lead you astray. But they shall not lead astray anyone except themselves, and they perceive not.', 'A group from the people of the Book loves to mislead you, while they mislead none but themselves, and they do not realize.'),
(363, 3, 70, 7, 15, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'یٰۤاَہۡلَ الۡکِتٰبِ لِمَ تَکۡفُرُوۡنَ بِاٰیٰتِ اللّٰہِ  وَ اَنۡتُمۡ  تَشۡہَدُوۡنَ ﴿۷۰﴾', 'اے اہل کتاب تم اللہ کی آیتوں سے کیوں انکار کرتے ہو اور تم تورات کو مانتے تو ہو۔', 'اے اہل کتاب کیوں انکار کرتے ہو اللہ کے کلام کا اور تم قائل ہو [۱۰۶]', 'O people of the Scripture! (Jews and Christians): \"Why do you disbelieve in the Ayat of Allah, (the Verses about Prophet Muhammad SAW present in the Taurat (Torah) and the Injeel (Gospel)) while you (yourselves) bear witness (to their truth).\"', 'O people of the Book, why do you disbelieve in the verses of Allah (revealed in the former Scriptures to foretell about the advent of the Holy Prophet ?) while you are yourselves witnesses (to those verses)?'),
(364, 3, 71, 7, 15, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'یٰۤاَہۡلَ الۡکِتٰبِ لِمَ تَلۡبِسُوۡنَ الۡحَقَّ بِالۡبَاطِلِ وَ تَکۡتُمُوۡنَ الۡحَقَّ وَ اَنۡتُمۡ تَعۡلَمُوۡنَ ﴿٪۷۱﴾', 'اے اہل کتاب تم سچ کو جھوٹ کے ساتھ خلط ملط کیوں کرتے ہو اور حق کو کیوں چھپاتے ہو جبکہ تم جانتے بھی ہو۔', 'اے اہل کتاب کیوں ملاتے ہو سچ میں جھوٹ اور چھپاتے ہو سچی بات جان کر [۱۰۷]', 'O people of the Scripture (Jews and Christians): \"Why do you mix truth with falsehood and conceal the truth while you know?\"', 'O People of the Book, why do you confound the truth with falsehood, and conceal the truth when you know (the reality)?'),
(365, 3, 72, 8, 16, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'وَ قَالَتۡ طَّآئِفَۃٌ مِّنۡ اَہۡلِ الۡکِتٰبِ اٰمِنُوۡا بِالَّذِیۡۤ اُنۡزِلَ عَلَی الَّذِیۡنَ اٰمَنُوۡا وَجۡہَ النَّہَارِ وَ اکۡفُرُوۡۤا اٰخِرَہٗ  لَعَلَّہُمۡ  یَرۡجِعُوۡنَ ﴿ۚۖ۷۲﴾', 'اور اہل کتاب ایک گروہ اپنے آدمیوں سے کہتا ہے کہ جو کتاب مومنوں پر نازل ہوئی ہے اس پر دن کے شروع میں تو ایمان لے آیا کرو اور اس کے آخر میں انکار کر دیا کرو تا کہ وہ اسلام سے برگشتہ ہو جائیں۔', 'اور کہا بعضے اہل کتاب نے مان لو جو کچھ اترا مسلمانوں پر دن چڑھے اور منکر ہو جاؤ آخر دن میں شاید وہ پھر جاویں [۱۰۸]', 'And a party of the people of the Scripture say: \"Believe in the morning in that which is revealed to the believers (Muslims), and reject it at the end of the day, so that they may turn back.', 'And a group from the people of the Book said (to their people), “Believe in what has been revealed to the believers in the early part of the day, and disbelieve at the end of it, so that they may turn back.'),
(366, 3, 73, 8, 16, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'وَ لَا تُؤۡمِنُوۡۤا اِلَّا لِمَنۡ تَبِعَ دِیۡنَکُمۡ ؕ قُلۡ  اِنَّ الۡہُدٰی ہُدَی اللّٰہِ ۙ اَنۡ یُّؤۡتٰۤی اَحَدٌ مِّثۡلَ مَاۤ اُوۡتِیۡتُمۡ اَوۡ یُحَآجُّوۡکُمۡ عِنۡدَ رَبِّکُمۡ ؕ قُلۡ  اِنَّ الۡفَضۡلَ بِیَدِ اللّٰہِ ۚ یُؤۡتِیۡہِ مَنۡ یَّشَآءُ ؕ وَ اللّٰہُ وَاسِعٌ عَلِیۡمٌ ﴿ۚۙ۷۳﴾', 'اور اپنے دین کے پیرو کے سوا کسی اور کی بات کا یقین نہ کر لینا اے پیغمبر کہدو کہ ہدایت تو اللہ ہی کی ہدایت ہے وہ یہ بھی کہتے ہیں یہ بھی نہ ماننا کہ جو چیز تم کو ملی ہے ویسی کسی اور کو بھی مل سکتی ہے ورنہ وہ تم پر تمہارے رب کے روبرو حجت قائم کر دیں گے اے پیغمبر کہدو کہ بزرگی اللہ ہی کے ہاتھ میں ہے وہ جسے چاہتا ہے دیتا ہے اور اللہ کشائش والا ہے علم والا ہے۔', 'اور نہ مانیو مگر اسی کی جو چلے تمہارےدین پر [۱۰۹] کہدے کہ بیشک ہدایت وہی ہے جو اللہ ہدایت کرے [۱۱۰] اور یہ سب کچھ اس لئے ہے کہ اور کسی کو بھی کیوں مل گیا جسیا کچھ تم کو ملا تھا یا وہ غالب کیوں آ گئے تم پر تمہارے رب کے آگے [۱۱۱] تو کہہ بڑائی اللہ کے ہاتھ میں ہے دیتا ہے جس کو چاہے اور اللہ بہت گنجائش والا ہے خبردار', 'And believe no one except the one who follows your religion. Say (O Muhammad SAW): \"Verily! Right guidance is the Guidance of Allah\" and do not believe that anyone can receive like that which you have received (of Revelation) except when he follows your religion, otherwise they would engage you in argument before your Lord. Say (O Muhammad SAW): \"All the bounty is in the Hand of Allah; He grants to whom He wills. And Allah is All-Sufficient for His creatures needs, the All-Knower.\"', 'But do not believe (for real) except in those who follow your faith.” Say, “(Real) guidance is the guidance of Allah.” (But all that you do is due to your envy) that someone is given what is similar to that which you have been given, or that they argue against you before your Lord.” Say, “The bounty is in the hands of Allah. He gives it to whom He wills. Allah is All-Embracing, All-Knowing.'),
(367, 3, 74, 8, 16, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'یَّخۡتَصُّ بِرَحۡمَتِہٖ مَنۡ  یَّشَآءُ ؕ وَ اللّٰہُ ذُو الۡفَضۡلِ الۡعَظِیۡمِ ﴿۷۴﴾', 'وہ اپنی رحمت سے جس کو چاہتا ہے خاص کر لیتا ہے اور اللہ بڑے فضل کا مالک ہے۔', 'خاص کرتا ہے اپنی مہربانی جس پر چاہے اور اللہ کا فضل بڑا ہے [۱۱۲]', 'He selects for His Mercy (Islam and the Quran with Prophethood) whom He wills and Allah is the Owner of Great Bounty.', 'He chooses for His grace whom He wills. Allah is the Lord of great bounty.”'),
(368, 3, 75, 8, 16, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'وَ مِنۡ اَہۡلِ الۡکِتٰبِ مَنۡ  اِنۡ تَاۡمَنۡہُ بِقِنۡطَارٍ یُّؤَدِّہٖۤ  اِلَیۡکَ ۚ وَ مِنۡہُمۡ مَّنۡ  اِنۡ تَاۡمَنۡہُ بِدِیۡنَارٍ لَّا یُؤَدِّہٖۤ  اِلَیۡکَ اِلَّا مَادُمۡتَ عَلَیۡہِ قَآئِمًا ؕ ذٰلِکَ بِاَنَّہُمۡ قَالُوۡا لَیۡسَ عَلَیۡنَا فِی الۡاُمِّیّٖنَ سَبِیۡلٌ ۚ وَ یَقُوۡلُوۡنَ عَلَی اللّٰہِ الۡکَذِبَ وَ ہُمۡ  یَعۡلَمُوۡنَ ﴿۷۵﴾', 'اور اہل کتاب میں سے کوئی تو ایسا ہے کہ اگر تم اس کے پاس دیناروں کا ڈھیر امانت رکھ دو تو تم کو فوراً واپس دیدے اور کوئی اس طرح کا ہے کہ اگر اس کے پاس ایک دینار بھی امانت رکھو تو جب تک اس کے سر پر ہر وقت کھڑے نہ رہو تمہیں دے ہی نہیں یہ اس لئے کہ وہ کہتے ہیں کہ اُمّیوں کے بارے میں ہم سے مواخذہ نہیں ہو گا۔ یہ اللہ پر محض جھوٹ بولتے ہیں اور اس بات کو جانتے بھی ہیں۔', 'اور بعضے اہل کتاب میں وہ ہیں کہ اگر تو ان کے پاس امانت رکھے ڈھیر مال کا تو ادا کر دیں تجھ کو اور بعضے ان میں وہ ہیں کہ اگر تو انکے پاس امانت رکھے ایک اشرفی تو ادا نہ کریں تجھ کو  مگر جب تک کہ تو رہے اس کے سر پر کھڑا [۱۱۳] یہ اس واسطے کہ انہوں کے کہہ رکھا ہے کہ نہیں ہے ہم پر امی لوگوں کے حق لینے میں کچھ گناہ [۱۱۴] اور جھوٹ بولتے ہیں اللہ پر اور وہ جانتے ہیں [۱۱۵]', 'Among the people of the Scripture (Jews and Christians) is he who, if entrusted with a Cantar (a great amount of wealth, etc.), will readily pay it back; and among them there is he who, if entrusted with a single silver coin, will not repay it unless you constantly stand demanding, because they say: \"There is no blame on us to betray and take the properties of the illiterates (Arabs).\" But they tell a lie against Allah while they know it.', 'Among the people of the Book there is one who, if you entrust him with a heap (of gold or silver), will give it back to you; and among them there is one who, if you entrust him with a single dīnār (a coin of gold), he will not give it back to you, unless you keep standing over him. This is because they have said, “There is no way we can be blamed in the matter of the unlettered.”And they tell lies about Allah knowingly.'),
(369, 3, 76, 8, 16, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'بَلٰی مَنۡ اَوۡفٰی بِعَہۡدِہٖ وَ اتَّقٰی فَاِنَّ اللّٰہَ یُحِبُّ الۡمُتَّقِیۡنَ ﴿۷۶﴾', 'ہاں کیوں نہیں جو شخص اپنے اقرار کو پورا کرے اور پرہیزگار بنا رہے تو اللہ بھی پرہیزگاروں کو دوست رکھتا ہے۔', 'کیوں نہیں جو کوئی پورا کرے اپنا قرار اور پرہیز گار ہے تو اللہ کو محبت ہے  پرہیزگاروں سے [۱۱۶]', 'Yes, whoever fulfils his pledge and fears Allah much; verily, then Allah loves those who are Al-Muttaqoon (the pious - see V.2:2).', 'Why (will they) not (be blamed)? Whoever fulfils his pledge and fears Allah, then, Allah loves the God-fearing.'),
(370, 3, 77, 8, 16, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اِنَّ الَّذِیۡنَ یَشۡتَرُوۡنَ بِعَہۡدِ اللّٰہِ وَ اَیۡمَانِہِمۡ ثَمَنًا قَلِیۡلًا  اُولٰٓئِکَ لَا خَلَاقَ لَہُمۡ فِی الۡاٰخِرَۃِ وَ لَا یُکَلِّمُہُمُ اللّٰہُ وَ لَا یَنۡظُرُ اِلَیۡہِمۡ یَوۡمَ الۡقِیٰمَۃِ وَ لَا یُزَکِّیۡہِمۡ ۪ وَ لَہُمۡ عَذَابٌ اَلِیۡمٌ ﴿۷۷﴾', 'جو لوگ اللہ کے اقراروں اور اپنی قسموں کو بیچ ڈالتے ہیں اور ان کے عوض تھوڑی سی قیمت حاصل کرتے ہیں ان کا آخرت میں کچھ حصہ نہیں۔ ان سے اللہ نہ تو کلام کرے گا اور نہ قیامت کے روز ان کی طرف دیکھے گا اور نہ ان کو پاک کرے گا اور ان کو دکھ دینے والا عذاب ہو گا۔', 'جو لوگ مول لیتے ہیں اللہ کے قرار پر اور اپنی قسموں پر تھوڑا سا مول [۱۱۷] ان کا کچھ حصہ نہیں آخرت میں اور نہ بات کرے گا ان سے اللہ اور نہ نگاہ کرے گا انکی طرف قیامت کے دن اور نہ پاک کرے گا ان کو اور انکے واسطے  عذاب ہے دردناک [۱۱۸]', 'Verily, those who purchase a small gain at the cost of Allahs Covenant and their oaths, they shall have no portion in the Hereafter (Paradise). Neither will Allah speak to them, nor look at them on the Day of Resurrection, nor will He purify them, and they shall have a painful torment.', 'Surely, those who take a small price by (breaking) the covenant of Allah and their oaths, for them there is no share in the Hereafter, and Allah will neither speak to them, nor will He look towards them on the Day of Judgment, nor will He purify them. For them there is a painful punishment.'),
(371, 3, 78, 8, 16, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'وَ اِنَّ مِنۡہُمۡ لَفَرِیۡقًا یَّلۡوٗنَ اَلۡسِنَتَہُمۡ بِالۡکِتٰبِ لِتَحۡسَبُوۡہُ مِنَ الۡکِتٰبِ وَ مَا ہُوَ مِنَ الۡکِتٰبِ ۚ وَ یَقُوۡلُوۡنَ ہُوَ مِنۡ عِنۡدِ اللّٰہِ  وَ مَا ہُوَ  مِنۡ عِنۡدِ اللّٰہِ ۚ وَ یَقُوۡلُوۡنَ عَلَی اللّٰہِ الۡکَذِبَ وَ ہُمۡ  یَعۡلَمُوۡنَ ﴿۷۸﴾', 'اور ان اہل کتاب میں بعض ایسے ہیں کہ کتاب یعنی تورات کو زبان مروڑ مروڑ کر پڑھتے ہیں تا کہ تم سمجھو کہ جو کچھ وہ پڑھتے ہیں کتاب میں سے ہے حالانکہ وہ کتاب میں سے نہیں ہوتا اور کہتے ہیں کہ وہ اللہ کی طرف سے نازل ہوا ہے حالانکہ وہ اللہ کی طرف سے نہیں ہوتا اور اللہ پر جھوٹ بولتے ہیں اور یہ بات جانتے بھی ہیں۔', 'اور ان میں ایک فریق ہے کہ زبان مڑوڑ کر پڑھتے ہیں کتاب تاکہ تم جانو کہ وہ کتاب میں ہے اور وہ نہیں کتاب میں اور کہتے ہیں وہ اللہ کا کہا ہے اور وہ نہیں اللہ کا کہا [۱۱۹] اور اللہ پر جھوٹ بولتے ہیں جان کر', 'And verily, among them is a party who distort the Book with their tongues (as they read), so that you may think it is from the Book, but it is not from the Book, and they say: \"This is from Allah,\" but it is not from Allah; and they speak a lie against Allah while they know it.', 'Among them there is indeed a group who twist their tongues while (reading) the Book, so that you may deem it to be from the Book, while it is not from the Book. They say, “It is from Allah”, while it is not from Allah; and they tell lies about Allah knowingly.'),
(372, 3, 79, 8, 16, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'مَا کَانَ لِبَشَرٍ اَنۡ یُّؤۡتِیَہُ اللّٰہُ الۡکِتٰبَ وَ الۡحُکۡمَ وَ النُّبُوَّۃَ ثُمَّ یَقُوۡلَ لِلنَّاسِ کُوۡنُوۡا عِبَادًا لِّیۡ مِنۡ دُوۡنِ اللّٰہِ وَ لٰکِنۡ کُوۡنُوۡا رَبّٰنِیّٖنَ بِمَا کُنۡتُمۡ تُعَلِّمُوۡنَ الۡکِتٰبَ وَ بِمَا کُنۡتُمۡ  تَدۡرُسُوۡنَ ﴿ۙ۷۹﴾', 'کسی آدمی کو شایاں نہیں کہ اللہ اسے کتاب اور حکومت اور نبوت عطا فرمائے پھر وہ لوگوں سے کہے کہ اللہ کو چھوڑ کر میرے بندے ہو جاؤ۔ بلکہ اس کو یہ کہنا چاہئے کہ اے اہل کتاب تم ربانی ہو جاؤ کیونکہ تم کتاب کی تعلیم بھی دیتے ہو اور کیونکہ پڑھتے پڑھاتے رہتے ہو۔', 'کسی بشر کا کام نہیں کہ اللہ اس کو دیوے کتاب اور حکمت اور پیغمبر کرے پھر وہ کہے لوگوں کو کہ تم میرے بندے ہو جاؤ اللہ کو چھوڑ کر [۱۲۰] لیکن یوں کہے کہ تم اللہ والے ہو جاؤ جیسے کہ تم سکھلاتے تھے کتاب اور جیسے کہ تم آپ بھی پڑھتے تھے اسے [۱۲۱]', 'It is not (possible) for any human being to whom Allah has given the Book and Al-Hukma (the knowledge and understanding of the laws of religion, etc.) and Prophethood to say to the people: \"Be my worshippers rather than Allahs.\" On the contrary (he would say): \"Be you Rabbaniyun (learned men of religion who practise what they know and also preach others), because you are teaching the Book, and you are studying it.\"', 'It is not (possible) for a man that Allah gives him the Book, the wisdom and the prophethood, then he starts saying to the people “Become my worshippers, aside from Allah” rather, (he would say), “Be men of the Lord; as you have been teaching the Book, and as you have been learning it.”'),
(373, 3, 80, 8, 16, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'وَ لَا یَاۡمُرَکُمۡ اَنۡ تَتَّخِذُوا الۡمَلٰٓئِکَۃَ وَ النَّبِیّٖنَ اَرۡبَابًا ؕ اَیَاۡمُرُکُمۡ بِالۡکُفۡرِ بَعۡدَ اِذۡ اَنۡتُمۡ مُّسۡلِمُوۡنَ ﴿٪۸۰﴾', 'اور اس کو یہ بھی نہیں کہنا چاہیے کہ تم فرشتوں اور پیغمبروں کو معبود بنا لو۔ بھلا جب تم مسلمان ہو چکے تو کیا وہ تمہیں کافر ہونے کو کہے گا۔', 'اور نہ یہ کہے تم کو کہ ٹھہرا لو فرشتوں کو اور نبیوں کو رب [۱۲۲] کیا تم کو کفر سکھائے گا بعد اس کے کہ تم مسلمان ہو چکے ہو [۱۲۳]', 'Nor would he order you to take angels and Prophets for lords (gods). Would he order you to disbelieve after you have submitted to Allahs Will? (Tafsir At-Tabaree).', 'Nor is it (possible for him) that he bids you to hold the angels and the prophets as Lords. Shall he bid you to disbelieve, after your having become Muslims?'),
(374, 3, 81, 9, 17, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'وَ اِذۡ اَخَذَ اللّٰہُ مِیۡثَاقَ النَّبِیّٖنَ لَمَاۤ اٰتَیۡتُکُمۡ مِّنۡ کِتٰبٍ وَّ حِکۡمَۃٍ ثُمَّ جَآءَکُمۡ رَسُوۡلٌ مُّصَدِّقٌ لِّمَا مَعَکُمۡ لَتُؤۡمِنُنَّ بِہٖ وَ لَتَنۡصُرُنَّہٗ ؕ قَالَ ءَاَقۡرَرۡتُمۡ وَ اَخَذۡتُمۡ عَلٰی ذٰلِکُمۡ اِصۡرِیۡ ؕ قَالُوۡۤا اَقۡرَرۡنَا ؕ قَالَ فَاشۡہَدُوۡا وَ اَنَا مَعَکُمۡ مِّنَ  الشّٰہِدِیۡنَ ﴿۸۱﴾', 'اور جب اللہ نے پیغمبروں سے عہد لیا کہ جب میں تم کو کتاب اور دانائی عطا کروں پھر تمہارے پاس کوئی پیغمبر آئے جو تمہاری کتاب کی تصدیق کرے تو تمہیں ضرور اس پر ایمان لانا ہو گا اور ضرور اس کی مدد کرنی ہوگی۔  اور عہد لینے کے بعد پوچھا کہ بھلا تم نے اقرار کیا اور اس اقرار پر میرا ذمہ لیا یعنی مجھے ضامن ٹھہرایا انہوں نے کہا ہاں ہم نے اقرار کیا۔ فرمایا کہ تم اس عہدوپیمان کے گواہ رہو اور میں بھی تمہارے ساتھ گواہ ہوں۔', 'اور جب لیا اللہ نے عہد نبیوں سے کہ جو کچھ میں نے تم کو دیا کتب اور علم پھر آوے تمہارے پاس کوئی رسول کہ سچا بتاوے تمہارے پاس والی کتاب کو تو اس رسول پر ایمان لاؤ گے اور اس کی مدد کرو گے فرمایا کہ کیا تم نے اقرار کیا اور اس شرط پر میرا عہد قبول کیا بولے ہم نے اقرار کیا [۱۲۴] فرمایا تو اب گواہ رہو اور میں بھی تمہارے ساتھ گواہ ہوں [۱۲۵]', 'And (remember) when Allah took the Covenant of the Prophets, saying: \"Take whatever I gave you from the Book and Hikmah (understanding of the Laws of Allah, etc.), and afterwards there will come to you a Messenger (Muhammad SAW) confirming what is with you; you must, then, believe in him and help him.\" Allah said: \"Do you agree (to it) and will you take up My Covenant (which I conclude with you)?\" They said: \"We agree.\" He said: \"Then bear witness; and I am with you among the witnesses (for this).\"', 'When Allah made the prophets enter into a covenant: (saying) “If I give you a book and wisdom, then comes to you a messenger verifying what is with you, you shall have to believe in him, and you shall have to support him.” He said, “Do you affirm and accept my covenant in this respect?” They said, “We affirm.” He said, “Then, bear witness, and I am with you among the witnesses.”'),
(375, 3, 82, 9, 17, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'فَمَنۡ تَوَلّٰی بَعۡدَ ذٰلِکَ فَاُولٰٓئِکَ ہُمُ الۡفٰسِقُوۡنَ ﴿۸۲﴾', 'اب جو لوگ اس کے بعد پھر جائیں تو وہی بدکردار ہیں۔', 'پھر جو کوئی پھر جاوے اس کے بعد تو وہی لوگ ہیں نافرمان [۱۲۶]', 'Then whoever turns away after this, they are the Fasiqoon (rebellious: those who turn away from Allahs Obedience).', 'Then those who turn back after this, they are the sinful.'),
(376, 3, 83, 9, 17, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اَفَغَیۡرَ دِیۡنِ اللّٰہِ یَبۡغُوۡنَ وَ لَہٗۤ  اَسۡلَمَ  مَنۡ فِی السَّمٰوٰتِ وَ الۡاَرۡضِ طَوۡعًا وَّ کَرۡہًا وَّ اِلَیۡہِ یُرۡجَعُوۡنَ ﴿۸۳﴾', 'پھر کیا یہ کافر اللہ کے دین کے سوا کسی اور دین کے طالب ہیں حالانکہ سب اہل آسمان و زمین خوشی یا ناخوشی سے اللہ کے فرمانبردار ہیں اور اسی کی طرف لوٹ کر جانے والے ہیں۔', 'اب کوئی اور دین ڈھونڈھتے ہیں سوا دین اللہ کے اور اسی کے حکم میں ہے جو کوئی آسمان اور زمین میں ہے خوشی سے یا لاچاری سے [۱۲۷] اور اسی کی طرف سب پھر جاویں گے [۱۲۸]', 'Do they seek other than the religion of Allah (the true Islamic Monotheism worshipping none but Allah Alone), while to Him submitted all creatures in the heavens and the earth, willingly or unwillingly. And to Him shall they all be returned.', 'Are they, then, seeking a religion other than that of Allah, while to Him alone submit all those in the heavens and the earth, willingly or unwilling, and to Him they shall be returned?');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(377, 3, 84, 9, 17, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'قُلۡ اٰمَنَّا بِاللّٰہِ وَ مَاۤ  اُنۡزِلَ عَلَیۡنَا وَ مَاۤ اُنۡزِلَ عَلٰۤی اِبۡرٰہِیۡمَ وَ اِسۡمٰعِیۡلَ وَ اِسۡحٰقَ وَ یَعۡقُوۡبَ وَ الۡاَسۡبَاطِ وَ مَاۤ اُوۡتِیَ مُوۡسٰی وَ عِیۡسٰی وَ النَّبِیُّوۡنَ مِنۡ رَّبِّہِمۡ ۪ لَا نُفَرِّقُ بَیۡنَ اَحَدٍ مِّنۡہُمۡ ۫ وَ نَحۡنُ لَہٗ مُسۡلِمُوۡنَ ﴿۸۴﴾', 'کہو کہ ہم اللہ پر ایمان لائے اور جو کتاب ہم پر نازل ہوئی اور جو صحیفے ابراہیم اور اسمٰعیل اور اسحٰق اور یعقوب اور ان کی اولاد پر اترے اور جو کتابیں موسٰی اور عیسٰی اور دوسرے انبیاء کو پروردگار کی طرف سے ملیں سب پر ایمان لائے۔ ہم ان پیغمبروں میں سے کسی میں کچھ فرق نہیں کرتے اور ہم اسی اللہ کے فرماں بردار ہیں۔', 'تو کہہ ہم ایمان لائے اللہ پر اور جو کچھ اترا ہم پر اور جو کچھ اترا ابراہیم پر اور اسمٰعیل پر اور اسحٰق پر اور یعقوب پر اور اس کی اولاد پر اور جو ملا موسٰی کو اور عیسٰی کو اور جو ملا سب نبیوں کو انکے پروردگار کی طرف سے ہم جدا نہیں کرتے ان میں کسی کو اور ہم اسی کے فرمانبردار ہیں [۱۲۹]', 'Say (O Muhammad SAW): \"We believe in Allah and in what has been sent down to us, and what was sent down to Ibrahim (Abraham), Ismail (Ishmael), Ishaque (Isaac), Yaqoob (Jacob) and Al-Asbat (the twelve sons of Yaqoob (Jacob)) and what was given to Moosa (Moses), Iesa (Jesus) and the Prophets from their Lord. We make no distinction between one another among them and to Him (Allah) we have submitted (in Islam).\"', 'Say, “We believe in Allah and in what has been revealed to us and in what was revealed to Ibrāhīm, Ismā‘īl, IsHāq , Ya‘qūb and the descendants, and in what has been given to Mūsā, ‘Īsā and the prophets, from their Lord: We do not differentiate between any of them; and to Him we submit ourselves.”'),
(378, 3, 85, 9, 17, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'وَ مَنۡ یَّبۡتَغِ غَیۡرَ الۡاِسۡلَامِ دِیۡنًا فَلَنۡ یُّقۡبَلَ مِنۡہُ ۚ وَ ہُوَ فِی الۡاٰخِرَۃِ مِنَ الۡخٰسِرِیۡنَ ﴿۸۵﴾', 'اور جو شخص اسلام کے سوا کسی اور دین کا طالب ہو گا وہ اس سے ہر گز قبول نہیں کیا جائے گا اور ایسا شخص آخرت میں نقصان اٹھانے والوں میں ہو گا۔', 'اور جو کوئی چاہے سوا دین اسلام کے اور کوئی دین سو اس سے ہر گز قبول نہ ہو گا [۱۳۰] اور وہ آخرت میں خراب ہے [۱۳۱]', 'And whoever seeks a religion other than Islam, it will never be accepted of him, and in the Hereafter he will be one of the losers.', 'Whoever seeks a faith other than Islam, it will never be accepted from him, and he, in the Hereafter, will be among the losers.'),
(379, 3, 86, 9, 17, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'کَیۡفَ یَہۡدِی اللّٰہُ  قَوۡمًا کَفَرُوۡا بَعۡدَ اِیۡمَانِہِمۡ وَ شَہِدُوۡۤا اَنَّ الرَّسُوۡلَ حَقٌّ وَّ جَآءَہُمُ الۡبَیِّنٰتُ ؕ وَ اللّٰہُ  لَا یَہۡدِی الۡقَوۡمَ الظّٰلِمِیۡنَ ﴿۸۶﴾', 'اللہ ایسے لوگوں کو کیونکر ہدایت دے جو ایمان لانے کے بعد کافر ہو گئے اور پہلے اس بات کی گواہی دے چکے کہ یہ پیغمبر برحق ہے اور ان کے پاس دلائل بھی آ گئے اور اللہ بے انصافوں کو ہدایت نہیں دیتا۔', 'کیونکر راہ دے گا للہ ایسے لوگوں کو کہ کافر ہو گئے ایمان لا کر اور گواہی دے کر کہ بیشک رسول سچا ہے اور آئیں ان کے پاس نشانیاں روشن اور اللہ راہ نہیں دیتا ظالم لوگوں کو [۱۳۲]', 'How shall Allah guide a people who disbelieved after their belief and after they bore witness that the Messenger (Muhammad SAW) is true and after clear proofs had come unto them? And Allah guides not the people who are Zalimoon (polytheists and wrong-doers).', 'How shall Allah give guidance to a people who disbelieved after they had accepted Faith and testified that the Prophet is true and the clear signs had come to them? Allah does not give guidance to the unjust people.'),
(380, 3, 87, 9, 17, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اُولٰٓئِکَ جَزَآؤُہُمۡ  اَنَّ عَلَیۡہِمۡ لَعۡنَۃَ اللّٰہِ وَ الۡمَلٰٓئِکَۃِ وَ النَّاسِ اَجۡمَعِیۡنَ ﴿ۙ۸۷﴾', 'ان لوگوں کی سزا یہ ہے کہ ان پر اللہ کی اور فرشتوں کی اور انسانوں کی سب کی لعنت ہے۔', 'ایسے لوگوں کی سزا یہ ہے کہ ان پر لعنت ہے اللہ کی اور فرشتوں کی اور لوگوں کی سب کی [۱۳۳]', 'They are those whose recompense is that on them (rests) the Curse of Allah, of the angels, and of all mankind.', 'The punishment of such people is that upon them is the curse of Allah, of the angels and of the human beings altogether.'),
(381, 3, 88, 9, 17, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'خٰلِدِیۡنَ فِیۡہَا ۚ لَا یُخَفَّفُ عَنۡہُمُ الۡعَذَابُ وَ لَا  ہُمۡ  یُنۡظَرُوۡنَ ﴿ۙ۸۸﴾', 'ہمیشہ اس لعنت میں گرفتار رہیں گے ان سے نہ تو عذاب ہلکا کیا جائے گا اور نہ انہیں مہلت دی جائے گی۔', 'ہمیشہ رہیں گے اس میں [۱۳۴] نہ ہلکا ہو گا ان سے عذاب اور نہ ان کو فرصت ملے [۱۳۵]', 'They will abide therein (Hell). Neither will their torment be lightened, nor will it be delayed or postponed (for a while).', 'They will remain under it forever. Neither will the punishment be lightened for them, nor will they be given respite,'),
(382, 3, 89, 9, 17, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اِلَّا الَّذِیۡنَ تَابُوۡا مِنۡۢ بَعۡدِ ذٰلِکَ وَ اَصۡلَحُوۡا ۟ فَاِنَّ اللّٰہَ  غَفُوۡرٌ  رَّحِیۡمٌ ﴿۸۹﴾', 'ہاں جنہوں نے اس کے بعد توبہ کی اور اپنی حالت درست کر لی تو اللہ بخشنے والا مہربان ہے۔', 'مگر جنہوں نے توبہ کی اس کےبعد اور نیک کام کئے تو بیشک اللہ غفور رحیم ہے [۱۳۶]', 'Except for those who repent after that and do righteous deeds. Verily, Allah is Oft-Forgiving, Most Merciful.', 'except those who repent afterwards and mend their ways. Then, Allah is All-Forgiving, Very-Merciful.'),
(383, 3, 90, 9, 17, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اِنَّ الَّذِیۡنَ کَفَرُوۡا بَعۡدَ اِیۡمَانِہِمۡ ثُمَّ ازۡدَادُوۡا کُفۡرًا  لَّنۡ تُقۡبَلَ تَوۡبَتُہُمۡ ۚ وَ اُولٰٓئِکَ ہُمُ  الضَّآلُّوۡنَ ﴿۹۰﴾', 'جو لوگ ایمان لانے کے بعد کافر ہو گئے پھر کفر میں بڑھتے گئے۔ ایسوں کی توبہ ہر گز قبول نہیں ہو گی اور یہ لوگ گمراہ ہیں۔', 'جو لوگ منکر ہوئے مان کر پھر بڑھتے رہے انکار میں ہر گز قبول نہ ہوگی ان کی توبہ اور وہی ہیں گمراہ [۱۳۷]', 'Verily, those who disbelieved after their Belief and then went on increasing in their disbelief (i.e. disbelief in the Quran and in Prophet Muhammad SAW) - never will their repentance be accepted (because they repent only by their tongues and not from their hearts). And they are those who are astray.', 'Those who disbelieve after having accepted Faith and then increase in disbelief, their repentance shall never be accepted. They are the ones who have lost the right path.'),
(384, 3, 91, 9, 17, 3, 'تِلۡکَ الرُّسُلُ', 'آل عمران', 'اِنَّ الَّذِیۡنَ کَفَرُوۡا وَ مَاتُوۡا وَ ہُمۡ کُفَّارٌ فَلَنۡ یُّقۡبَلَ مِنۡ اَحَدِہِمۡ مِّلۡءُ  الۡاَرۡضِ ذَہَبًا وَّلَوِ افۡتَدٰی بِہٖ ؕ اُولٰٓئِکَ لَہُمۡ عَذَابٌ اَلِیۡمٌ  وَّ مَا لَہُمۡ  مِّنۡ  نّٰصِرِیۡنَ ﴿٪۹۱﴾', 'جو لوگ کافر ہوئے اور کفر ہی کی حالت میں مر گئے وہ اگر نجات حاصل کرنی چاہیں اور بدلے میں زمین بھر سونا دیں تو ہر گز قبول نہیں کیا جائے گا۔ ان لوگوں کو دکھ دینے والا عذاب ہوگا۔ اور ان کا کوئی مددگار نہیں ہو گا۔', 'جو لوگ کافر ہوئے اور مر گئے کافر ہی تو ہر گز قبول نہ ہوگا کسی ایسے سے زمین بھر کو سونا [۱۳۸] اور اگرچہ بدلا دیوے اس قدر سونا ان کو عذاب دردناک ہے اور کوئی نہیں ان کا مددگار [۱۳۹]', 'Verily, those who disbelieved, and died while they were disbelievers, the (whole) earth full of gold will not be accepted from anyone of them even if they offered it as a ransom. For them is a painful torment and they will have no helpers.', 'Those who disbelieve and die as disbelievers, even an Earth-full of gold shall never be accepted from any of them, even if one were to offer it as ransom. They are the ones for whom there is a painful punishment, and for them there are no helpers.'),
(385, 3, 92, 10, 1, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'لَنۡ تَنَالُوا الۡبِرَّ حَتّٰی تُنۡفِقُوۡا مِمَّا تُحِبُّوۡنَ ۬ؕ وَ مَا تُنۡفِقُوۡا مِنۡ شَیۡءٍ فَاِنَّ اللّٰہَ بِہٖ  عَلِیۡمٌ ﴿۹۲﴾', 'مومنو! جب تک تم ان چیزوں میں سے جو تمہیں عزیز ہیں اللہ کی راہ میں خرچ نہ کرو گے کبھی نیکی حاصل نہ کر سکو گے اور جو چیز تم خرچ کرو گے اللہ اس کو جانتا ہے۔', 'ہر گز حاصل نہ کر سکو گے نیکی میں کمال جب تک نہ خرچ کرو اپنی پیاری چیز سے کچھ اور جو چیز خرچ کرو گے سو اللہ کو معلوم ہے [۱۴۰]', 'By no means shall you attain Al-Birr (piety, righteousness, etc., it means here Allahs Reward, i.e. Paradise), unless you spend (in Allahs Cause) of that which you love; and whatever of good you spend, Allah knows it well.', 'You shall never attain righteousness unless you spend from what you love. Whatsoever you spend, Allah is fully aware of it.'),
(386, 3, 93, 10, 1, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'کُلُّ الطَّعَامِ کَانَ حِلًّا  لِّبَنِیۡۤ  اِسۡرَآءِیۡلَ اِلَّا مَا حَرَّمَ  اِسۡرَآءِیۡلُ  عَلٰی  نَفۡسِہٖ مِنۡ قَبۡلِ اَنۡ تُنَزَّلَ التَّوۡرٰىۃُ ؕ قُلۡ فَاۡتُوۡا بِالتَّوۡرٰىۃِ فَاتۡلُوۡہَاۤ  اِنۡ  کُنۡتُمۡ صٰدِقِیۡنَ ﴿۹۳﴾', 'بنی اسرائیل کے لئے تورات کے نازل ہونے سے پہلے کھانے کی تمام چیزیں حلال تھیں بجز ان کے جو یعقوب نے خود اپنے اوپر حرام کر لی تھیں کہدو کہ اگر سچے ہو تو تورات لاؤ اور اسے پڑھو یعنی دلیل پیش کرو۔', 'سب کھانے کی چیزیں حلال تھیں بنی اسرائیل کو مگر وہ جو حرام کر لی تھی اسرائیل نے اپنے اوپر توریت نازل ہونے سے پہلے [۱۴۱] تو کہہ لاؤ توریت اور پڑھو اگر سچے ہو [۱۴۲]', 'All food was lawful to the Children of Israel, except what Israel made unlawful for himself before the Taurat (Torah) was revealed. Say (O Muhammad SAW): \"Bring here the Taurat (Torah) and recite it, if you are truthful.\"', 'Every (kind of) food was lawful for the children of Isrā’īl, except what Isrā’īl had made unlawful for himself, well before the Torah was revealed. Say, “Then, bring the Torah and recite it, if you are true.”'),
(387, 3, 94, 10, 1, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'فَمَنِ افۡتَرٰی عَلَی اللّٰہِ الۡکَذِبَ مِنۡۢ بَعۡدِ ذٰلِکَ  فَاُولٰٓئِکَ ہُمُ  الظّٰلِمُوۡنَ ﴿؃۹۴﴾', 'اب جو اس کے بعد بھی اللہ پر جھوٹے افتراء کریں تو ایسے لوگ ہی بے انصاف ہیں۔', 'پھر جو کوئی جوڑے اللہ پر جھوٹ اس کے بعد تو وہی ہیں بڑے بے انصاف [۱۴۳]', 'Then after that, whosoever shall invent a lie against Allah, … such shall indeed be the Zalimoon (disbelievers).', 'Then those who forge the lie against Allah, after all this,- they are the transgressors.'),
(388, 3, 95, 10, 1, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'قُلۡ صَدَقَ اللّٰہُ  ۟ فَاتَّبِعُوۡا مِلَّۃَ  اِبۡرٰہِیۡمَ حَنِیۡفًا ؕ وَ مَا کَانَ مِنَ الۡمُشۡرِکِیۡنَ ﴿۹۵﴾', 'کہدو کہ اللہ نے سچ فرما دیا پس دین ابراہیم کی پیروی کرو جو سب سے بے تعلق ہو کر ایک اللہ کے ہو رہے تھے اور مشرکوں میں سے نہ تھے۔', 'تو کہہ سچ فرمایا اللہ نے اب تابع ہو جاؤ دین ابراہیم کے جو ایک ہی کا ہو رہا تھا اور نہ تھا شرک کرنے والا [۱۴۴]', 'Say (O Muhammad SAW): \"Allah has spoken the truth; follow the religion of Ibrahim (Abraham) Hanifa (Islamic Monotheism, i.e. he used to worship Allah Alone), and he was not of Al-Mushrikoon.\" (See V.2:105)', 'Say, “Allah has told the truth. So, follow the Faith of Ibrāhīm, the upright one. He was not one of those who ascribe partners to Allah.”'),
(389, 3, 96, 10, 1, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اِنَّ اَوَّلَ بَیۡتٍ وُّضِعَ لِلنَّاسِ لَلَّذِیۡ بِبَکَّۃَ مُبٰرَکًا  وَّ ہُدًی  لِّلۡعٰلَمِیۡنَ ﴿ۚ۹۶﴾', 'سب سے پہلا گھر جو لوگوں کے عبادت کرنے کے لئے مقرر کیا گیا تھا وہی ہے جو مکے میں ہے۔ بابرکت اور جہان والوں کے لئے موجب ہدایت۔', 'بیشک سب سے پہلا گھر جو مقرر ہوا لوگوں کے واسطے یہی ہے جو مکہ میں ہے [۱۴۵] برکت والا اور ہدایت جہان کے لوگوں کو', 'Verily, the first House (of worship) appointed for mankind was that at Bakkah (Makkah), full of blessing, and a guidance for Al-Alameen (the mankind and jinns).', 'The first house set up for the people is surely the one in Makkah having blessings and guidance for all the worlds.'),
(390, 3, 97, 10, 1, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'فِیۡہِ اٰیٰتٌۢ بَیِّنٰتٌ مَّقَامُ  اِبۡرٰہِیۡمَ ۬ۚ وَ مَنۡ دَخَلَہٗ کَانَ اٰمِنًا ؕ وَ لِلّٰہِ عَلَی النَّاسِ حِجُّ الۡبَیۡتِ مَنِ اسۡتَطَاعَ اِلَیۡہِ سَبِیۡلًا ؕ وَ مَنۡ  کَفَرَ فَاِنَّ اللّٰہَ غَنِیٌّ عَنِ  الۡعٰلَمِیۡنَ ﴿۹۷﴾', 'اس میں کھلی ہوئی نشانیاں ہیں جن میں سے ایک ابراہیم کے کھڑے ہونے کی جگہ ہے۔ جو شخص اس مبارک گھر میں داخل ہوا اس نے امن پا لیا۔ اور لوگوں پر اللہ کا حق یعنی فرض ہے کہ جو اس گھر تک جانے کا مقدور رکھے وہ اس کا حج کرے۔ اور جو اس حکم کی تعمیل نہ کرے گا تو اللہ بھی اہل عالم سے بے نیاز ہے۔', 'اس میں نشانیاں ہیں ظاہر جیسے مقام ابراہیم اور جو اس کے اندر آیا اس کو امن ملا [۱۴۶] اور اللہ کا حق ہے لوگوں پر حج کرنا اس گھر کا جو شخص قدرت رکھتا ہو اسکی طرف راہ چلنے کی اور جو نہ مانے تو پھر اللہ پروا نہیں رکھتا جہان کے لوگوں کی [۱۴۷]', 'In it are manifest signs (for example), the Maqam (place) of Ibrahim (Abraham); whosoever enters it, he attains security. And Hajj (pilgrimage to Makkah) to the House (Kabah) is a duty that mankind owes to Allah, those who can afford the expenses (for ones conveyance, provision and residence); and whoever disbelieves (i.e. denies Hajj (pilgrimage to Makkah), then he is a disbeliever of Allah), then Allah stands not in need of any of the Alameen (mankind and jinns).', 'In it there are clear signs: The Station of Ibrāhīm! Whoever enters it is secure. As a right of Allah, it is obligatory on the people to perform Hajj of the House - on everyone who has the ability to manage (his) way to it. If one disbelieves, then Allah is independant of all the worlds.'),
(391, 3, 98, 10, 1, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'قُلۡ یٰۤاَہۡلَ الۡکِتٰبِ لِمَ تَکۡفُرُوۡنَ بِاٰیٰتِ اللّٰہِ ٭ۖ وَ اللّٰہُ شَہِیۡدٌ عَلٰی مَا تَعۡمَلُوۡنَ ﴿۹۸﴾', 'کہو کہ اے اہل کتاب! تم اللہ کی آیتوں سے کیوں کفر کرتے ہو جبکہ اللہ تمہارے سب اعمال سے باخبر ہے۔', 'تو کہہ اے اہل کتاب کیوں منکر ہوتے ہو اللہ کے کلام سے اور اللہ کے روبرو ہے جو تم کرتے ہو [۱۴۸]', 'Say: \"O people of the Scripture (Jews and Christians)! Why do you reject the Ayat of Allah (proofs, evidences, verses, lessons, signs, revelations, etc.) while Allah is Witness to what you do?\"', 'Say, “O people of the Book, why do you reject the verses of Allah while Allah is witness to what you do?”'),
(392, 3, 99, 10, 1, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'قُلۡ یٰۤاَہۡلَ  الۡکِتٰبِ لِمَ تَصُدُّوۡنَ عَنۡ سَبِیۡلِ اللّٰہِ مَنۡ اٰمَنَ تَبۡغُوۡنَہَا عِوَجًا وَّ اَنۡتُمۡ شُہَدَآءُ ؕ وَ مَا اللّٰہُ بِغَافِلٍ عَمَّا تَعۡمَلُوۡنَ ﴿۹۹﴾', 'کہو کہ اے اہل کتاب تم مومنوں کو اللہ کے رستے سے کیوں روکتے ہو اور باوجودیکہ تم اس سے واقف ہو اس میں کجی نکالتے ہو اور اللہ تمہارے کرتوتوں سے بے خبر نہیں۔', 'تو کہہ اے اہل کتاب کیوں روکتے ہو اللہ کی راہ سے ایمان لانے والوں کو کہ ڈھونڈتے ہو اس میں عیب اور تم خود جانتے ہو اور اللہ بے خبر نہیں تمہارے کام سے [۱۴۹]', 'Say: \"O people of the Scripture (Jews and Christians)! Why do you stop those who have believed, from the Path of Allah, seeking to make it seem crooked, while you (yourselves) are witnesses (to Muhammad SAW as a Messenger of Allah and Islam (Allahs Religion, i.e. to worship none but Him Alone))? And Allah is not unaware of what you do.\"', 'Say, “O people of the Book, why do you hinder the believers from the way of Allah, trying to create crookedness in it, while you yourselves are witnesses (to its being the right way)? Allah is not oblivious of what you do.”'),
(393, 3, 100, 10, 1, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اِنۡ تُطِیۡعُوۡا فَرِیۡقًا مِّنَ الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ یَرُدُّوۡکُمۡ  بَعۡدَ اِیۡمَانِکُمۡ  کٰفِرِیۡنَ ﴿۱۰۰﴾', 'مومنو! اگر تم اہل کتاب کے کسی فریق کا کہا مان لو گے تو وہ تمہیں ایمان لانے کے بعد کافر بنا دیں گے۔', 'اے ایمان والو اگر تم کہا مانو گے بعضے اہل کتاب کا تو پھر کر دیں گے وہ تم کو ایمان لائے پیچھے کافر [۱۵۰]', 'O you who believe! If you obey a group of those who were given the Scripture (Jews and Christians), they would (indeed) render you disbelievers after you have believed!', 'O you who believe, if you obey a group from those who have been given the Book (i.e. the Christians and the Jews), they will turn you into infidels after you have embraced the faith.'),
(394, 3, 101, 10, 1, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ کَیۡفَ تَکۡفُرُوۡنَ وَ اَنۡتُمۡ تُتۡلٰی عَلَیۡکُمۡ اٰیٰتُ اللّٰہِ وَ فِیۡکُمۡ رَسُوۡلُہٗ ؕ وَ مَنۡ یَّعۡتَصِمۡ بِاللّٰہِ فَقَدۡ ہُدِیَ  اِلٰی صِرَاطٍ مُّسۡتَقِیۡمٍ  ﴿۱۰۱﴾٪', 'اور تم کیوں کر کفر کرو گے جبکہ تم کو اللہ کی آیتیں پڑھ پڑھ کر سنائی جاتی ہیں اور تم میں اس کے پیغمبر موجود ہیں اور جس نے اللہ کی رسی کو مضبوط پکڑ لیا وہ سیدھے رستے لگ گیا۔', 'اور تم کس طرح کافر ہوتے ہو اور تم پر پڑھی جاتی ہیں آیتیں اللہ کی اور تم میں اس کا رسول ہے اور جو کوئی مضبوط پکڑے اللہ کو تو اس کو ہدایت ہوئی سیدھے رستہ کی [۱۵۱]', 'And how would you disbelieve, while unto you are recited the Verses of Allah, and among you is His Messenger (Muhammad SAW)? And whoever holds firmly to Allah, (i.e. follows Islam Allahs Religion, and obeys all that Allah has ordered, practically), then he is indeed guided to a Right Path.', 'How could you disbelieve while you are the ones to whom the verses of Allah are recited, and present amidst you is His Messenger? Whoever holds on to Allah, is surely led to the straight path.'),
(395, 3, 102, 11, 2, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوا اتَّقُوا اللّٰہَ حَقَّ تُقٰتِہٖ وَ لَا تَمُوۡتُنَّ  اِلَّا وَ اَنۡتُمۡ  مُّسۡلِمُوۡنَ ﴿۱۰۲﴾', 'مومنو! اللہ سے ڈرو جیسا کہ اس سے ڈرنے کا حق ہے اور مرنا تو مسلمان ہی مرنا۔', 'اے ایمان والو ڈرتے رہو اللہ سے جیسا چاہیئے اس سے ڈرنا اور نہ مریو مگر مسلمان [۱۵۲]', 'O you who believe! Fear Allah (by doing all that He has ordered and by abstaining from all that He has forbidden) as He should be feared. (Obey Him, be thankful to Him, and remember Him always), and die not except in a state of Islam (as Muslims) with complete submission to Allah.', 'O you who believe, fear Allah, as He should be feared, and let not yourself die save as Muslims.'),
(396, 3, 103, 11, 2, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ اعۡتَصِمُوۡا بِحَبۡلِ اللّٰہِ جَمِیۡعًا وَّ لَا تَفَرَّقُوۡا ۪ وَ اذۡکُرُوۡا نِعۡمَتَ اللّٰہِ عَلَیۡکُمۡ  اِذۡ  کُنۡتُمۡ اَعۡدَآءً فَاَلَّفَ بَیۡنَ قُلُوۡبِکُمۡ فَاَصۡبَحۡتُمۡ بِنِعۡمَتِہٖۤ اِخۡوَانًا ۚ وَ کُنۡتُمۡ عَلٰی شَفَا حُفۡرَۃٍ مِّنَ النَّارِ فَاَنۡقَذَکُمۡ مِّنۡہَا ؕ کَذٰلِکَ یُبَیِّنُ اللّٰہُ لَکُمۡ اٰیٰتِہٖ  لَعَلَّکُمۡ  تَہۡتَدُوۡنَ ﴿۱۰۳﴾', 'اور سب مل کر اللہ کی ہدایت کی رسی کو مضبوط پکڑے رہنا اور فرقے فرقے نہ ہو جانا۔ اور اپنے اوپر اللہ کی اس مہربانی کو یاد رکھنا جب تم ایک دوسرے کے دشمن تھے تو اس نے تمہارے دلوں میں الفت ڈال دی اور تم اس کی مہربانی سے بھائی بھائی ہو گئے اور تم آگ کے گڑھے کے کنارے تک پہنچ چکے تھے تو اس نے تم کو اس سے بچا لیا۔ اس طرح اللہ تم کو اپنی آیتیں کھول کھول کر سناتا ہے تاکہ تم راہ راست پر رہو۔', 'اور مضبوط پکڑو رسی اللہ کی سب مل کر اور پھوٹ نہ ڈالو [۱۵۳] اور  یاد کرو احسان اللہ کا اپنے اوپر جب کہ تھے تم آپس میں دشمن پھر الفت دی تمہارے دلوں میں اب ہو گئے اس کے فضل سے بھائی [۱۵۴] اور تم تھے کنارے پر ایک آگ کے گڑھے کے پھر تم کو اس سے نجات دی [۱۵۵] اسی طرح کھولتا ہے اللہ تم پر آیتیں تاکہ تم راہ پاؤ [۱۵۶]', 'And hold fast, all of you together, to the Rope of Allah (i.e. this Quran), and be not divided among yourselves, and remember Allahs Favour on you, for you were enemies one to another but He joined your hearts together, so that, by His Grace, you became brethren (in Islamic Faith), and you were on the brink of a pit of Fire, and He saved you from it. Thus Allah makes His Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.,) clear to you, that you may be guided.', 'Hold fast, all of you, to the cord of Allah, and be not divided. Remember the blessing of Allah upon you: When you were enemies to each other, and He brought your hearts together, so that, you became brothers through His blessing. You were at the brink of a pit of Fire, then He saved you from it. This is how Allah makes His signs clear to you, so that you may take the right path.'),
(397, 3, 104, 11, 2, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَلۡتَکُنۡ مِّنۡکُمۡ اُمَّۃٌ یَّدۡعُوۡنَ اِلَی الۡخَیۡرِ وَ یَاۡمُرُوۡنَ بِالۡمَعۡرُوۡفِ وَ یَنۡہَوۡنَ عَنِ الۡمُنۡکَرِ ؕ وَ اُولٰٓئِکَ ہُمُ  الۡمُفۡلِحُوۡنَ ﴿۱۰۴﴾', 'اور تم میں ایک جماعت ایسی ہونی چاہیے جو لوگوں کو نیکی کی طرف بلائے اور اچھے کام کرنے کا حکم دے اور برے کاموں سے منع کرے یہی لوگ ہیں جو کامیاب ہیں۔', 'اور چاہیئے کہ رہے تم میں ایک جماعت ایسی جو بلاتی رہے نیک کام کی طرف اور حکم کرتی رہے اچھے کاموں کا اور منع کریں برائی سے اور وہی پہنچے اپنی مراد کو [۱۵۷]', 'Let there arise out of you a group of people inviting to all that is good (Islam), enjoining Al-Maroof (i.e. Islamic Monotheism and all that Islam orders one to do) and forbidding Al-Munkar (polytheism and disbelief and all that Islam has forbidden). And it is they who are the successful.', 'There has to be a group of people from among you who call towards the good, and bid the Fair and forbid the Unfair. And it is these who are successful.'),
(398, 3, 105, 11, 2, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ لَا تَکُوۡنُوۡا کَالَّذِیۡنَ تَفَرَّقُوۡا وَ اخۡتَلَفُوۡا مِنۡۢ بَعۡدِ مَا جَآءَہُمُ الۡبَیِّنٰتُ ؕ وَ اُولٰٓئِکَ لَہُمۡ عَذَابٌ عَظِیۡمٌ ﴿۱۰۵﴾ۙ', 'اور ان لوگوں کی طرح نہ ہونا جو متفرق ہو گئے اور صاف احکام آنے کے بعد ایک دوسرے سے اختلاف کرنے لگے یہ وہ لوگ ہیں جنکو قیامت کے دن بڑا عذاب ہو گا۔', 'اور مت ہو ان کی طرح جو متفرق ہو گئے اور اختلاف کرنے لگے بعد اس کے کہ پہنچ چکے ان کو حکم صاف اور ان کو بڑا عذاب ہے [۱۵۸]', 'And be not as those who divided and differed among themselves after the clear proofs had come to them. It is they for whom there is an awful torment.', 'Do not be like those who became divided and fell into disputes after the clear signs had come to them. Those are the ones for whom there is a grave punishment'),
(399, 3, 106, 11, 2, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'یَّوۡمَ تَبۡیَضُّ وُجُوۡہٌ  وَّ تَسۡوَدُّ وُجُوۡہٌ ۚ فَاَمَّا الَّذِیۡنَ اسۡوَدَّتۡ وُجُوۡہُہُمۡ ۟ اَکَفَرۡتُمۡ بَعۡدَ اِیۡمَانِکُمۡ فَذُوۡقُوا الۡعَذَابَ بِمَا کُنۡتُمۡ تَکۡفُرُوۡنَ ﴿۱۰۶﴾', 'جس دن بہت سے منہ سفید ہوں گے اور بہت سے سیاہ۔ تو جن لوگوں کے منہ سیاہ ہوں گے ان سے اللہ فرمائے گا کیا تم ایمان لا کر کافر ہو گئے تھے؟ سو اب اس کفر کے بدلے عذاب کے مزے چکھو۔', 'جس دن کہ سفید ہوں گے بعضے منہ اور سیاہ ہوں گے بعضے منہ [۱۵۹] سو وہ لوگ کہ سیاہ ہوئے منہ ان کے ان سے کہا جائے گا کیا تم کافر ہو گئے ایمان لا کر [۱۶۰] اب چکھو عذاب بدلا اس کفر کرنے کا', 'On the Day (i.e. the Day of Resurrection) when some faces will become white and some faces will become black; as for those whose faces will become black (to them will be said): \"Did you reject Faith after accepting it? Then taste the torment (in Hell) for rejecting Faith.\"', 'on a day when some faces shall turn bright, and some faces shall turn dark. As for those whose faces turn dark, (they shall be questioned): “Did you disbelieve after you had accepted the Faith? Now taste the punishment, because you used to disbelieve.”'),
(400, 3, 107, 11, 2, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ اَمَّا الَّذِیۡنَ ابۡیَضَّتۡ وُجُوۡہُہُمۡ فَفِیۡ رَحۡمَۃِ اللّٰہِ ؕ ہُمۡ  فِیۡہَا خٰلِدُوۡنَ ﴿۱۰۷﴾', 'اور جن لوگوں کے منہ سفید ہوں گے وہ اللہ کی رحمت کے باغوں میں ہوں گے اور ان میں ہمیشہ رہیں گے۔', 'اور وہ لوگ کہ سفید ہوئے منہ ان کے سو رحمت میں ہیں اللہ کی وہ اس میں ہمیشہ رہیں گے [۱۶۱]', 'And for those whose faces will become white, they will be in Allahs Mercy (Paradise), therein they shall dwell forever.', 'As for those whose faces turn bright, they will rest in Allah’s mercy. They will live there forever.'),
(401, 3, 108, 11, 2, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'تِلۡکَ اٰیٰتُ اللّٰہِ نَتۡلُوۡہَا عَلَیۡکَ بِالۡحَقِّ ؕ وَ مَا اللّٰہُ یُرِیۡدُ  ظُلۡمًا لِّلۡعٰلَمِیۡنَ ﴿۱۰۸﴾', 'یہ اللہ کی آیتیں ہیں جو ہم تم کو ٹھیک ٹھیک پڑھ کر سناتے ہیں۔ اور اللہ اہل عالم پر ظلم نہیں کرنا چاہتا۔', 'یہ حکم ہیں اللہ کے ہم سناتے ہیں تجھ کو ٹھیک ٹھیک اور اللہ ظلم کرنا نہیں چاہتا خلقت پر [۱۶۲]', 'These are the Verses of Allah: We recite them to you (O Muhammad SAW) in truth, and Allah wills no injustice to the Alameen (mankind and jinns).', 'These are the verses of Allah We recite to you with all veracity. Allah does not intend to do injustice to (anyone in) the worlds.'),
(402, 3, 109, 11, 2, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ لِلّٰہِ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ؕ وَ  اِلَی اللّٰہِ  تُرۡجَعُ  الۡاُمُوۡرُ  ﴿۱۰۹﴾٪', 'اور جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب اللہ ہی کا ہے اور سب کاموں کا انجام اللہ ہی کی طرف ہے۔', 'اور اللہ ہی کا ہے جو کچھ کہ ہے آسمانوں میں اور جو کچھ کہ ہے زمین میں اور اللہ کی طرف رجوع ہے ہر کام کا [۱۶۳]', 'And to Allah belongs all that is in the heavens and all that is in the earth. And all matters go back (for decision) to Allah.', 'To Allah belongs what is in the heavens and what is in the earth. To Allah all matters are returned.'),
(403, 3, 110, 12, 3, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'کُنۡتُمۡ خَیۡرَ اُمَّۃٍ اُخۡرِجَتۡ لِلنَّاسِ تَاۡمُرُوۡنَ بِالۡمَعۡرُوۡفِ وَ تَنۡہَوۡنَ عَنِ الۡمُنۡکَرِ وَ تُؤۡمِنُوۡنَ بِاللّٰہِ ؕ وَ لَوۡ اٰمَنَ اَہۡلُ  الۡکِتٰبِ لَکَانَ خَیۡرًا لَّہُمۡ ؕ مِنۡہُمُ الۡمُؤۡمِنُوۡنَ وَ اَکۡثَرُہُمُ الۡفٰسِقُوۡنَ ﴿۱۱۰﴾', 'مومنو! تم بہترین امت ہو جسے لوگوں کی ہدایت کیلئے میدان میں لایا گیا ہے کہ تم نیک کام کرنے کو کہتے ہو اور برے کاموں سے منع کرتے ہو اور اللہ پر ایمان رکھتے ہو اور اگر اہل کتاب بھی ایمان لے آتے تو ان کے لئے بہت اچھا ہوتا۔ ان میں ایمان لانے والے بھی ہیں لیکن تھوڑے اور اکثر نافرمان ہیں۔', 'تم ہو بہتر سب امتوں سے جو بھیجی گئ عالم میں [۱۶۴] حکم کرتے ہو اچھے کاموں کا اور منع کرتے ہو برے کاموں سے [۱۶۵] اور ایمان لاتے ہو اللہ پر [۱۶۶] اور اگر ایمان لاتے اہل کتاب تو ان کے لئے بہتر تھا کچھ تو ان میں سے ہیں ایمان پر اور اکثر ان میں نافرمان ہیں [۱۶۷]', 'You (true believers in Islamic Monotheism, and real followers of Prophet Muhammad SAW and his Sunnah (legal ways, etc.)) are the best of peoples ever raised up for mankind; you enjoin Al-Maroof (i.e. Islamic Monotheism and all that Islam has ordained) and forbid Al-Munkar (polytheism, disbelief and all that Islam has forbidden), and you believe in Allah. And had the people of the Scripture (Jews and Christians) believed, it would have been better for them; among them are some who have faith, but most of them are Al-Fasiqoon (disobedient to Allah - and rebellious against Allahs Command).', 'You are the best ‘Ummah ever raised for mankind. You bid the Fair and forbid the Unfair, and you believe in Allah. If the people of the Book had believed, it would have been better for them. Among them, there are believers, while most of them are sinners.'),
(404, 3, 111, 12, 3, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'لَنۡ یَّضُرُّوۡکُمۡ  اِلَّاۤ اَذًی ؕ وَ اِنۡ  یُّقَاتِلُوۡکُمۡ   یُوَلُّوۡکُمُ الۡاَدۡبَارَ ۟ ثُمَّ لَا  یُنۡصَرُوۡنَ ﴿۱۱۱﴾', 'یہ تمہیں خفیف سی تکلیف کے سوا کچھ نقصان نہیں پہنچا سکیں گے اور اگر تم سے لڑیں گے تو پیٹھ پھیر کر بھاگ جائیں گے۔ پھر ان کو مدد بھی کہیں سے نہیں ملے گی۔', 'وہ کچھ نہ بگاڑ سکیں گے تمہارا مگر ستانا زبان سے اور اگر تم سے لڑیں گے تو پیٹھ دیں گے پھر ان کی مدد نہ ہو گی [۱۶۸]', 'They will do you no harm, barring a trifling annoyance; and if they fight against you, they will show you their backs, and they will not be helped.', 'They shall never (be able to) cause you any harm except a little hurt. If they fight you, they will turn their backs on you, then they shall not be helped.'),
(405, 3, 112, 12, 3, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'ضُرِبَتۡ عَلَیۡہِمُ الذِّلَّۃُ  اَیۡنَ مَا ثُقِفُوۡۤا اِلَّا بِحَبۡلٍ مِّنَ اللّٰہِ وَ حَبۡلٍ مِّنَ النَّاسِ وَ بَآءُوۡ بِغَضَبٍ مِّنَ اللّٰہِ وَ ضُرِبَتۡ عَلَیۡہِمُ الۡمَسۡکَنَۃُ ؕ ذٰلِکَ بِاَنَّہُمۡ کَانُوۡا یَکۡفُرُوۡنَ بِاٰیٰتِ اللّٰہِ وَ یَقۡتُلُوۡنَ الۡاَنۡۢبِیَآءَ بِغَیۡرِ حَقٍّ ؕ ذٰلِکَ بِمَا عَصَوۡا وَّ کَانُوۡا یَعۡتَدُوۡنَ ﴿۱۱۲﴾٭', 'یہ جہاں نظر آئیں گے تم دیکھو گے کہ ذلت ان سے چمٹ رہی ہے۔ بجز اس کے کہ یہ اللہ کی پناہ میں یا مسلمان لوگوں کی پناہ میں آجائیں اور یہ لوگ اللہ کے غضب میں گرفتار ہیں اور ناداری ان سے لپٹ رہی ہے۔ یہ اس لئے کہ اللہ کی آیتوں سے انکار کرتے تھے اور اس کے پیغمبروں کو ناحق قتل کر دیتے تھے۔ یہ اس لئے کہ یہ نافرمانی کئے جاتے اور حد سے بڑھے جاتے تھے۔', 'ماری گئ ان پر ذلت جہاں دیکھے جائیں سوائے دست آویز اللہ کے اور دست آویز لوگوں کے [۱۶۹] اور کمایا انہوں نے غصہ اللہ کا اور لازم کر دی گئ انکے اوپر حاجت مندی یہ اس واسطے کہ وہ انکار کرتے رہے ہیں اللہ کی آیتوں سے اور قتل کرتے رہے ہیں پیغمبروں کو ناحق یہ اس واسطے کہ نافرمانی کی انہوں نے اور حد سے نکل گئے [۱۷۰]', 'Indignity is put over them wherever they may be, except when under a covenant (of protection) from Allah, and from men; they have drawn on themselves the Wrath of Allah, and destruction is put over them. This is because they disbelieved in the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah and killed the Prophets without right. This is because they disobeyed (Allah) and used to transgress beyond bounds (in Allahs disobedience, crimes and sins).', 'Disgrace has been stamped over them wherever they are found, unless (saved) through a source from Allah and through a source from men, and they have returned with wrath from Allah, and misery has been stamped over them. All this is because they used to deny the signs of Allah, and to slay the prophets unjustly. All this is because they disobeyed and transgressed the limits.'),
(406, 3, 113, 12, 3, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'لَیۡسُوۡا سَوَآءً ؕ مِنۡ اَہۡلِ الۡکِتٰبِ اُمَّۃٌ قَآئِمَۃٌ یَّتۡلُوۡنَ اٰیٰتِ اللّٰہِ اٰنَآءَ الَّیۡلِ  وَ ہُمۡ  یَسۡجُدُوۡنَ ﴿۱۱۳﴾', 'یہ بھی سب ایک جیسے نہیں ہیں۔ ان اہل کتاب میں کچھ اچھے لوگ بھی ہیں۔ جو رات کے وقت اللہ کی آیتیں پڑھتے اور اس کے آگے سجدے کرتے ہیں۔', 'وہ سب برابر نہیں اہل کتاب میں ایک فرقہ ہے سیدھی راہ پر پڑھتے ہیں آیتیں اللہ کی راتوں کے وقت اور وہ سجدے کرتے ہیں', 'Not all of them are alike; a party of the people of the Scripture stand for the right, they recite the Verses of Allah during the hours of the night, prostrating themselves in prayer.', 'Not all of them are alike: Among the people of the Book there are those who are steadfast; they recite the verses of Allah in the night hours, and they prostrate themselves;'),
(407, 3, 114, 12, 3, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'یُؤۡمِنُوۡنَ بِاللّٰہِ وَ الۡیَوۡمِ الۡاٰخِرِ وَ یَاۡمُرُوۡنَ بِالۡمَعۡرُوۡفِ وَ یَنۡہَوۡنَ عَنِ الۡمُنۡکَرِ وَ یُسَارِعُوۡنَ فِی الۡخَیۡرٰتِ ؕ وَ اُولٰٓئِکَ مِنَ  الصّٰلِحِیۡنَ ﴿۱۱۴﴾', 'وہ اللہ پر اور روز آخر پر ایمان رکھتے اور اچھے کام کرنے کو کہتے اور بری باتوں سے منع کرتے اور نیکیوں پر لپکتے ہیں اور یہی لوگ نیکوکار ہیں۔', 'ایمان لاتے ہیں اللہ پر اور قیامت کے دن پر اور حکم کرتے ہیں اچھی بات کا اور منع کرتے ہیں برے کاموں سے اور دوڑتے ہیں نیک کاموں پر اور وہی لوگ نیک بخت ہیں [۱۷۱]', 'They believe in Allah and the Last Day; they enjoin Al-Maroof (Islamic Monotheism, and following Prophet Muhammad SAW) and forbid Al-Munkar (polytheism, disbelief and opposing Prophet Muhammad SAW); and they hasten in (all) good works; and they are among the righteous.', 'they believe in Allah and the Hereafter, and bid the Fair and forbid the Unfair, and hasten towards good deeds. They are among the righteous.'),
(408, 3, 115, 12, 3, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ مَا یَفۡعَلُوۡا مِنۡ خَیۡرٍ فَلَنۡ یُّکۡفَرُوۡہُ ؕ وَ اللّٰہُ  عَلِیۡمٌۢ  بِالۡمُتَّقِیۡنَ ﴿۱۱۵﴾', 'اور یہ جس طرح کی نیکی کریں گے اس کی ناقدری نہیں کی جائے گی اور اللہ پرہیزگاروں کو خوب جانتا ہے۔', 'اور جو کچھ کریں گے وہ لوگ نیک کام اس کی ہرگز ناقدری نہ ہو گی [۱۷۲] اور اللہ کو خبر ہے پرہیزگاروں کی [۱۷۳]', 'And whatever good they do, nothing will be rejected of them; for Allah knows well those who are Al-Muttaqoon (the pious - see V.2:2).', 'Whatever good they do, they shall never go unappreciated for it. Allah is All-Aware of the God-fearing.'),
(409, 3, 116, 12, 3, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اِنَّ الَّذِیۡنَ کَفَرُوۡا لَنۡ تُغۡنِیَ عَنۡہُمۡ اَمۡوَالُہُمۡ وَ لَاۤ اَوۡلَادُہُمۡ مِّنَ اللّٰہِ شَیۡـًٔا ؕ وَ اُولٰٓئِکَ اَصۡحٰبُ النَّارِ ۚ ہُمۡ فِیۡہَا خٰلِدُوۡنَ  ﴿۱۱۶﴾', 'جو لوگ کافر ہیں ان کے مال اور اولاد اللہ کے مقابلہ میں انکے ہرگز کام نہ آئیں گے۔ اور یہ لوگ اہل دوزخ ہیں کہ ہمیشہ اسی میں رہیں گے۔', 'وہ لوگ جو کافر ہیں ہرگز کام نہ آویں گے ان کو ان کےمال اور نہ اولاد اللہ کے آگے کچھ اور وہی لوگ رہنے والے ہیں آگ میں دوزخ کی وہ اس آگ میں ہمیشہ رہیں گے', 'Surely, those who reject Faith (disbelieve in Muhammad SAW as being Allahs Prophet and in all that which he has brought from Allah), neither their properties, nor their offspring will avail them aught against Allah. They are the dwellers of the Fire, therein they will abide. (Tafsir AtTabaree, Vol. 4, Page 58).', 'Surely, those who disbelieve, neither their wealth nor their children shall help them against Allah; and they are the people of the Fire. They shall be there forever.'),
(410, 3, 117, 12, 3, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'مَثَلُ مَا یُنۡفِقُوۡنَ فِیۡ ہٰذِہِ الۡحَیٰوۃِ الدُّنۡیَا کَمَثَلِ رِیۡحٍ فِیۡہَا صِرٌّ اَصَابَتۡ حَرۡثَ قَوۡمٍ ظَلَمُوۡۤا اَنۡفُسَہُمۡ فَاَہۡلَکَتۡہُ ؕ وَ مَا ظَلَمَہُمُ اللّٰہُ وَ لٰکِنۡ  اَنۡفُسَہُمۡ  یَظۡلِمُوۡنَ ﴿۱۱۷﴾', 'یہ لوگ جو مال دنیا کی زندگی میں خرچ کرتے ہیں اس کی مثال آندھی کی سی ہے جس میں سخت سردی ہو اور وہ ایسے لوگوں کی کھیتی پر جو اپنے آپ پر ظلم کرتے تھے چلے اور اسے تباہ کر دے اور اللہ نے ان پر کچھ ظلم نہیں کیا بلکہ یہ خود اپنے اوپر ظلم کر رہے ہیں۔', 'جو کچھ خرچ کرتے ہیں اس دنیا کی زندگی میں اس کی مثال جیسے ایک ہوا کہ اس میں ہو پالا جا لگی کھیتی کو اس قوم کی کہ انہوں نے اپنے حق میں برا کیا تھا پھر اس کو نابود کر گئ [۱۷۴] اور اللہ نے ان پر ظلم نہیں کیا لیکن وہ اپنے اوپر ظلم کرتے ہیں [۱۷۵]', 'The likeness of what they spend in this world is the likeness of a wind which is extremely cold; it struck the harvest of a people who did wrong aginst themselves and destroyed it, (i.e. the good deed of a person is only accepted if he is a monotheist and believes in all the Prophets of Allah, including Christ and Muhammad SAW). Allah wronged them not, but they wronged themselves.', 'The example of what they spend in this worldly life is just like a wind that, having chill within, struck the tillage of those who wronged themselves, and destroyed it. Allah has not wronged them; rather, they did wrong to themselves.'),
(411, 3, 118, 12, 3, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَتَّخِذُوۡا بِطَانَۃً مِّنۡ دُوۡنِکُمۡ لَا یَاۡلُوۡنَکُمۡ خَبَالًا ؕ وَدُّوۡا مَا عَنِتُّمۡ ۚ قَدۡ بَدَتِ الۡبَغۡضَآءُ مِنۡ اَفۡوَاہِہِمۡ ۚۖ وَ مَا تُخۡفِیۡ صُدُوۡرُہُمۡ اَکۡبَرُ ؕ قَدۡ بَیَّنَّا لَکُمُ الۡاٰیٰتِ  اِنۡ  کُنۡتُمۡ تَعۡقِلُوۡنَ ﴿۱۱۸﴾', 'مومنو! کسی غیر مذہب کے آدمی کو اپنا رازدار نہ بنانا یہ لوگ تمہاری خرابی میں کسی طرح کی کوتاہی نہیں کرتے اور چاہتے ہیں کہ جس طرح ہو تمہیں تکلیف پہنچے۔ ان کی زبانوں سے تو دشمنی ظاہر ہو ہی چکی ہے۔ اور جو کینے ان کے سینوں میں مخفی ہیں وہ کہیں زیادہ ہیں۔ اگر تم عقل رکھتے ہو تو ہم نے تم کو اپنی آیتیں کھول کھول کر سنا دی ہیں۔', 'اے ایمان والو نہ بناؤ بھیدی کسی کو اپنوں کےسوا وہ کمی نہیں کرتےتمہاری خرابی میں انکی خوشی ہےتم جس قدر تکلیف میں رہو نکلی پڑتی ہےدشمنی انکی زبان سےاور جو کچھ مخفی ہے انکے جی میں وہ اس سے بہت زیادہ ہے ہم نےبتا دیےتم کو پتے اگر تم کو عقل ہے [۱۷۶]', 'O you who believe! Take not as (your) Bitanah (advisors, consultants, protectors, helpers, friends, etc.) those outside your religion (pagans, Jews, Christians, and hypocrites) since they will not fail to do their best to corrupt you. They desire to harm you severely. Hatred has already appeared from their mouths, but what their breasts conceal is far worse. Indeed We have made plain to you the Ayat (proofs, evidences, verses) if you understand.', 'O you who believe, do not take anyone as an insider but those from among your own selves. They would spare no effort to do you mischief. They want you to be in trouble. Malice has come out of their mouths while what is concealed in their hearts is still worse. We have made the signs clear to you, if only you understand.'),
(412, 3, 119, 12, 3, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'ہٰۤاَنۡتُمۡ اُولَآءِ تُحِبُّوۡنَہُمۡ وَ لَا یُحِبُّوۡنَکُمۡ وَ تُؤۡمِنُوۡنَ بِالۡکِتٰبِ کُلِّہٖ ۚ وَ اِذَا لَقُوۡکُمۡ قَالُوۡۤا اٰمَنَّا ۚ٭ۖ  وَ اِذَا خَلَوۡا عَضُّوۡا عَلَیۡکُمُ  الۡاَنَامِلَ مِنَ الۡغَیۡظِ ؕ قُلۡ مُوۡتُوۡا بِغَیۡظِکُمۡ ؕ اِنَّ اللّٰہَ عَلِیۡمٌۢ بِذَاتِ الصُّدُوۡرِ ﴿۱۱۹﴾', 'دیکھو تم ایسے صاف دل لوگ ہو کہ ان لوگوں سے دوستی رکھتے ہو حالانکہ یہ تم سے دوستی نہیں رکھتے اور تم سب کتابوں پر ایمان رکھتے ہو اور یہ تمہاری کتاب کو نہیں مانتے اور جب تم سے ملتے ہیں تو کہتے ہیں۔ ہم ایمان لے آئے ہیں اور جب تنہا ہوتے ہیں تو تم پر غصے کے سبب انگلیاں کاٹ کاٹ کھاتے ہیں ان سے کہدو کہ اپنے غصے میں مر جاؤ۔ اللہ تمہارے دلوں کی باتوں سے خوب واقف ہے۔', 'سن لو تم لوگ ان کے دوست ہو اور وہ تمہارےدوست نہیں اور تم سب کتابوں کو مانتے ہو [۱۷۷] اور جب تم سے ملتے ہیں کہتے ہیں ہم مسلمان ہیں [۱۷۸] اور جب اکیلے ہوتے ہیں تو کاٹ کاٹ کھاتے ہیں تم پر انگلیاں غصہ سے [۱۷۹] تو کہہ مرو تم اپنے غصہ میں [۱۸۰] اللہ کو خوب معلوم ہیں دلوں کی باتیں [۱۸۱]', 'Lo! You are the ones who love them but they love you not, and you believe in all the Scriptures (i.e. you believe in the Taurat (Torah) and the Injeel (Gospel), while they disbelieve in your Book, the Quran). And when they meet you, they say, \"We believe\". But when they are alone, they bite the tips of their fingers at you in rage. Say: \"Perish in your rage. Certainly, Allah knows what is in the breasts (all the secrets).\"', 'Look, you are the ones who love them and they do not love you. You believe in all the books; (On the other hand,) when they meet you, they say, “We believe”, and when they are alone, they bite their finger-tips out of rage against you. Say, “May you perish in your rage.” Surely, Allah is All-Aware of what lies in the hearts.'),
(413, 3, 120, 12, 3, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اِنۡ تَمۡسَسۡکُمۡ حَسَنَۃٌ تَسُؤۡہُمۡ ۫ وَ اِنۡ تُصِبۡکُمۡ سَیِّئَۃٌ یَّفۡرَحُوۡا بِہَا ؕ وَ اِنۡ تَصۡبِرُوۡا وَ تَتَّقُوۡا لَا یَضُرُّکُمۡ کَیۡدُہُمۡ شَیۡـًٔا ؕ اِنَّ اللّٰہَ بِمَا یَعۡمَلُوۡنَ مُحِیۡطٌ ﴿۱۲۰﴾٪', 'اگر تمہیں آسودگی حاصل ہو تو ان کو بری لگتی ہے اور اگر تمہیں رنج پہنچے تو خوش ہوتے ہیں اور اگر تم تکلیفوں کی برداشت اور نافرمانی سے کنارہ کشی کرتے رہو گے تو ان کا فریب تمہیں کچھ بھی نقصان نہ پہنچا سکے گا۔ یہ جو کچھ کرتے ہیں اللہ اس کا احاطہ کئے ہوئے ہے۔', 'اگر تم کو ملے کچھ بھلائی تو بری لگی ہے ان کو اور اگر تم پر پہنچے کوئی برائی تو خوش ہو ں اس سے [۱۸۲] اور اگر تم صبر کرو اور بچتے رہو تو کچھ نہ بگڑے گا تمہارا ان کے فریب سے بیشک جو کچھ وہ کرتے ہیں سب اللہ کے بس میں ہے [۱۸۳]', 'If a good befalls you, it grieves them, but if some evil overtakes you, they rejoice at it. But if you remain patient and become Al-Muttaqoon (the pious - see V.2:2), not the least harm will their cunning do to you. Surely, Allah surrounds all that they do.', 'If something good happens to you, it annoys them, and if something evil befalls you, they are delighted with it. If you keep patience and fear Allah, their cunning shall not harm you at all. Allah is All-Encompassing of what they do.'),
(414, 3, 121, 13, 4, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ اِذۡ غَدَوۡتَ مِنۡ اَہۡلِکَ تُبَوِّیُٔ الۡمُؤۡمِنِیۡنَ مَقَاعِدَ لِلۡقِتَالِ ؕ وَ اللّٰہُ سَمِیۡعٌ عَلِیۡمٌ ﴿۱۲۱﴾ۙ', 'اور اس وقت کو یاد کرو جب تم صبح کو اپنے گھر سے روانہ ہو کر ایمان والوں کو لڑائی کے لئے مورچوں پر موقع بہ موقع متعین کرنے لگے اور اللہ سب کچھ سنتا ہے جانتا ہے۔', 'اور جب صبح کو نکلا تو اپنے گھر سے بٹھلانے لگا مسلمانوں کو لڑائی کے ٹھکانوں پر اور اللہ سب کچھ سنتا جانتا ہے', 'And (remember) when you (Muhammad SAW) left your household in the morning to post the believers at their stations for the battle (of Uhud). And Allah is All-Hearer, All-Knower.', 'Recall the time when you left your house in the morning in order to place the believers in positions for fighting. Allah is All-Hearing, All-Knowing.'),
(415, 3, 122, 13, 4, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اِذۡ ہَمَّتۡ طَّآئِفَتٰنِ مِنۡکُمۡ اَنۡ تَفۡشَلَا ۙ وَ اللّٰہُ وَلِیُّہُمَا ؕ وَ عَلَی اللّٰہِ فَلۡیَتَوَکَّلِ الۡمُؤۡمِنُوۡنَ ﴿۱۲۲﴾', 'اس وقت تم میں سے دو جماعتوں نے جی چھوڑ دینا چاہا۔ مگر اللہ ان کا مددگار تھا۔ اور مومنوں کو تو اللہ ہی پر بھروسا کرنا چاہیے۔', 'جب قصد کیا دو فرقوں نے تم میں سے کہ نامردی کریں اور اللہ مددگار تھا ان کا اور اللہ ہی پر چاہیئے بھروسہ کریں مسلمان', 'When two parties from among you were about to lose heart, but Allah was their Walee (Supporter and Protector). And in Allah should the believers put their trust.', 'When two of your groups were about to lose heart, while Allah was their guardian! It is in Allah alone that the believers must place their trust.'),
(416, 3, 123, 13, 4, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ لَقَدۡ نَصَرَکُمُ اللّٰہُ بِبَدۡرٍ وَّ اَنۡتُمۡ اَذِلَّۃٌ ۚ فَاتَّقُوا اللّٰہَ  لَعَلَّکُمۡ  تَشۡکُرُوۡنَ ﴿۱۲۳﴾', 'اور اللہ نے جنگ بدر میں بھی تمہاری مدد کی تھی جبکہ اس وقت بھی تم بے سروسامان تھے۔ پس اللہ کی نافرمانی سے بچو تاکہ شکزگذار بن جاؤ۔', 'اور تمہاری مدد کر چکا ہے اللہ بدر کی لڑائی میں اور تم کمزور تھے سو ڈرتے رہو اللہ سے تاکہ تم احسان مانو [۱۸۴]', 'And Allah has already made you victorious at Badr, when you were a weak little force. So fear Allah much (abstain from all kinds of sins and evil deeds which He has forbidden and love Allah much, perform all kinds of good deeds which He has ordained) that you may be grateful.', 'Allah certainly supported you at Badr when you were weak. So, fear Allah that you may be grateful'),
(417, 3, 124, 13, 4, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اِذۡ تَقُوۡلُ لِلۡمُؤۡمِنِیۡنَ اَلَنۡ یَّکۡفِیَکُمۡ اَنۡ یُّمِدَّکُمۡ رَبُّکُمۡ بِثَلٰثَۃِ اٰلٰفٍ مِّنَ الۡمَلٰٓئِکَۃِ  مُنۡزَلِیۡنَ ﴿۱۲۴﴾ؕ', 'جب تم مومنوں سے یہ کہہ کر ان کے دل بڑھا رہے تھے کہ کیا تم کو یہ کافی نہیں کہ پروردگار تین ہزار فرشتے نازل کر کے تمہیں مدد دے۔', 'جب تو کہنے لگا مسلمانوں کو کیا تم کو کافی نہیں کہ تمہاری مدد کو بھیجے رب تمہارا تین ہزار فرشتے آسمان سے اترنے والے [۱۸۵]', '(Remember) when you (Muhammad SAW) said to the believers, \"Is it not enough for you that your Lord (Allah) should help you with three thousand angels; sent down?\"', 'When you were saying to the believers, “Shall it not suffice you that your Lord should help you with three thousand of the angels sent down (for you)?”'),
(418, 3, 125, 13, 4, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'بَلٰۤی ۙ اِنۡ  تَصۡبِرُوۡا وَ تَتَّقُوۡا وَ یَاۡتُوۡکُمۡ مِّنۡ فَوۡرِہِمۡ ہٰذَا یُمۡدِدۡکُمۡ رَبُّکُمۡ بِخَمۡسَۃِ اٰلٰفٍ مِّنَ الۡمَلٰٓئِکَۃِ مُسَوِّمِیۡنَ ﴿۱۲۵﴾', 'ہاں کیوں نہیں اگر تم دل کو مضبوط رکھو۔ اور نافرمانی سے بچتے رہو اور کافر تم پر جوش کے ساتھ دفعتًہ حملہ کر دیں تو تمہارا پروردگار پانچ ہزار فرشتے جن پر نشان ہوں گے تمہاری مدد کو بھیجے گا۔', 'البتہ اگر تم صبر کرو اور بچتے رہو اور وہ آئیں تم پر اسی دم تو مدد بھیجے تمہارا رب پانچ ہزار فرشتے نشان دار گھوڑوں پر [۱۸۶]', '\"Yes, if you hold on to patience and piety, and the enemy comes rushing at you; your Lord will help you with five thousand angels having marks (of distinction).\"', 'Of course, if you stay patient and fear Allah, and they come upon you even in this heat of theirs, your Lord will reinforce you with five thousand of the angels, each having distinct marks.'),
(419, 3, 126, 13, 4, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ مَا جَعَلَہُ اللّٰہُ  اِلَّا بُشۡرٰی لَکُمۡ وَ لِتَطۡمَئِنَّ قُلُوۡبُکُمۡ بِہٖ ؕ وَ مَا النَّصۡرُ اِلَّا  مِنۡ  عِنۡدِ اللّٰہِ الۡعَزِیۡزِ  الۡحَکِیۡمِ ﴿۱۲۶﴾ۙ', 'اور اس مدد کو تو اللہ نے تمہارے لئے ذریعہ بشارت بنایا یعنی اس لئے کہ تمہارے دلوں کو اس سے اطمینان حاصل ہو ورنہ مدد تو اللہ ہی کی طرف سے ہوتی ہے۔ جو غالب ہے حکمت والا ہے۔', 'اور یہ تو اللہ نے تمہارےدل کی خوشی کی اور تاکہ تسکین ہو تمہارے دلوں کو اس سے اور مدد ہے صرف اللہ ہی کی طرف سے جو کہ زبردست ہے حکمت والا [۱۸۷]', 'Allah made it not but as a message of good news for you and as an assurance to your hearts. And there is no victory except from Allah, the All-Mighty, the All-Wise.', 'And Allah did this solely to make it a good news for you, and so that your hearts may be at rest with it. Otherwise, victory is from none but Allah, the All-Powerful, the All-Wise.'),
(420, 3, 127, 13, 4, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'لِیَقۡطَعَ طَرَفًا مِّنَ الَّذِیۡنَ کَفَرُوۡۤا اَوۡ یَکۡبِتَہُمۡ فَیَنۡقَلِبُوۡا خَآئِبِیۡنَ ﴿۱۲۷﴾', 'یہ اللہ نے اس لئے کیا کہ کافروں کی ایک جماعت کو ہلاک کر دے یا انہیں ذلیل و مغلوب کر دے کہ ناکام واپس جائیں۔', 'تاکہ ہلاک کرے بعضے کافروں کو یا انکو ذلیل کرے تو پھر جاویں محروم ہو کر [۱۸۸]', 'That He might cut off a part of those who disbelieve, or expose them to infamy, so that they retire frustrated.', '(Allah helped you) so that He may cut off a flank of disbelievers or throw them down in disgrace, and they go back frustrated.'),
(421, 3, 128, 13, 4, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'لَیۡسَ لَکَ مِنَ الۡاَمۡرِ شَیۡءٌ اَوۡ یَتُوۡبَ عَلَیۡہِمۡ  اَوۡ  یُعَذِّبَہُمۡ فَاِنَّہُمۡ ظٰلِمُوۡنَ ﴿۱۲۸﴾', 'اے پیغمبر اس کام میں تمہارا کچھ اختیار نہیں اب دو صورتیں ہیں یا اللہ ان کے حال پر مہربانی کرے یا انہیں عذاب دے کہ یہ ظالم لوگ ہیں۔', 'تیرا اختیار کچھ نہیں یا انکو توبہ دیوے خدائے تعالیٰ یا انکو عذاب کرے کہ وہ ناحق پر ہیں [۱۸۹]', 'Not for you (O Muhammad SAW, but for Allah) is the decision; whether He turns in mercy to (pardons) them or punishes them; verily, they are the Zalimoon (polytheists, disobedients, and wrong-doers, etc.).', 'You have no authority in the matter, unless Allah forgives them or punishes them, as they are unjust.'),
(422, 3, 129, 13, 4, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ لِلّٰہِ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ؕ یَغۡفِرُ لِمَنۡ یَّشَآءُ وَ یُعَذِّبُ مَنۡ یَّشَآءُ ؕ وَ اللّٰہُ غَفُوۡرٌ  رَّحِیۡمٌ ﴿۱۲۹﴾٪', 'اور جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے سب اللہ ہی کا ہے۔ وہ جسے چاہے بخش دے اور جسے چاہے عذاب کرے۔ اور اللہ بخشنے والا مہربان ہے۔', 'اور اللہ ہی کا مال ہے جو کچھ آسمانوں میں ہے اور جو کچھ کہ زمین میں ہے بخش دے جس کو چاہے اور عذاب کرے جس کو چاہے اور اللہ بخشنے والا مہربان ہے [۱۹۰]', 'And to Allah belongs all that is in the heavens and all that is in the earth. He forgives whom He wills, and punishes whom He wills. And Allah is Oft-Forgiving, Most Merciful.', 'To Allah belongs what is in the heavens and what is in the earth. He forgives whomsoever He wills and punishes whomsoever He wills. Allah is Most-Forgiving, Very-Merciful.'),
(423, 3, 130, 14, 5, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَاۡکُلُوا الرِّبٰۤوا اَضۡعَافًا مُّضٰعَفَۃً  ۪ وَ اتَّقُوا اللّٰہَ لَعَلَّکُمۡ  تُفۡلِحُوۡنَ ﴿۱۳۰﴾ۚ', 'اے ایمان والو! دگنا چوگنا سود نہ کھاؤ اور اللہ سے ڈرو تا کہ کامیاب ہو جاؤ۔', 'اے ایمان والو مت کھاؤ سود [۱۹۱] دونے پر دونا [۱۹۲] اور ڈرو اللہ سے تاکہ تمہارا بھلا ہو [۱۹۳]', 'O you who believe! Eat not Riba (usury) doubled and multiplied, but fear Allah that you may be successful.', 'O you who believe, do not eat up the amounts acquired through Ribā (interest), doubled and multiplied. Fear Allah, so that you may be successful,'),
(424, 3, 131, 14, 5, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ اتَّقُوا النَّارَ الَّتِیۡۤ  اُعِدَّتۡ لِلۡکٰفِرِیۡنَ ﴿۱۳۱﴾ۚ', 'اور دوزخ کی آگ سے بچو جو کافروں کے لئے تیار کی گئ ہے۔', 'اور بچو اس آگ سے جو تیار ہوئی کافروں کے واسطے [۱۹۴]', 'And fear the Fire, which is prepared for the disbelievers.', 'and fear the Fire that has been prepared for the disbelievers.'),
(425, 3, 132, 14, 5, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ اَطِیۡعُوا اللّٰہَ وَ الرَّسُوۡلَ لَعَلَّکُمۡ تُرۡحَمُوۡنَ ﴿۱۳۲﴾ۚ', 'اور اللہ اور اس کے رسول کی اطاعت کرو تا کہ تم پر رحمت کی جائے۔', 'اور حکم مانو اللہ کا اور رسول کا تاکہ تم پر رحم ہو [۱۹۵]', 'And obey Allah and the Messenger (Muhammad SAW) that you may obtain mercy.', 'Obey Allah and the Messenger, so that you may be blessed.'),
(426, 3, 133, 14, 5, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ سَارِعُوۡۤا اِلٰی مَغۡفِرَۃٍ  مِّنۡ رَّبِّکُمۡ وَ جَنَّۃٍ عَرۡضُہَا السَّمٰوٰتُ وَ الۡاَرۡضُ ۙ اُعِدَّتۡ  لِلۡمُتَّقِیۡنَ ﴿۱۳۳﴾ۙ', 'اور اپنے پروردگار کی بخشش اور اس بہشت کی طرف لپکو جس کا عرض آسمان اور زمین کے برابر ہے اور جو پرہیزگاروں کے لئے تیار کی گئ ہے۔', 'اور دوڑو بخشش کی طرف اپنے رب کی اور جنت کی طرف [۱۹۶] جس کا عرض ہے آسمان اور زمین [۱۹۷] تیار ہوئی ہے واسطے پرہیزگاروں کے', 'And march forth in the way (which leads to) forgiveness from your Lord, and for Paradise as wide as are the heavens and the earth, prepared for Al-Muttaqoon (the pious - see V.2:2).', 'Race with one another towards Forgiveness from your Lord and towards a paradise the width of which spans the heavens and the earth. It has been prepared for the God-fearing,'),
(427, 3, 134, 14, 5, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'الَّذِیۡنَ یُنۡفِقُوۡنَ فِی السَّرَّآءِ وَ الضَّرَّآءِ وَ الۡکٰظِمِیۡنَ الۡغَیۡظَ وَ الۡعَافِیۡنَ عَنِ النَّاسِ ؕ وَ اللّٰہُ یُحِبُّ الۡمُحۡسِنِیۡنَ ﴿۱۳۴﴾ۚ', 'جو آسودگی اور تنگی میں اپنا مال اللہ کی راہ میں خرچ کرتے ہیں اور غصے کو روکتے اور لوگوں کے قصور معاف کرتے ہیں۔ اور اللہ نیکوکاروں کو دوست رکھتا ہے۔', 'جو خرچ کئے جاتے ہیں خوشی میں اور تکلیف میں [۱۹۸] اور دبا لیتےہیں غصہ اور معاف کرتے ہیں لوگوں کو اور اللہ چاہتا ہے نیکی کرنے والوں کو [۱۹۹]', 'Those who spend (in Allahs Cause - deeds of charity, alms, etc.) in prosperity and in adversity, who repress anger, and who pardon men; verily, Allah loves Al-Muhsinoon (the gooddoers).', '-the ones who spend (for Allah’s sake) in prosperity and adversity, and those who control anger and forgive people. And Allah loves those who are good in their deeds,'),
(428, 3, 135, 14, 5, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ الَّذِیۡنَ  اِذَا فَعَلُوۡا فَاحِشَۃً اَوۡ ظَلَمُوۡۤا اَنۡفُسَہُمۡ ذَکَرُوا  اللّٰہَ  فَاسۡتَغۡفَرُوۡا لِذُنُوۡبِہِمۡ ۪ وَ مَنۡ یَّغۡفِرُ الذُّنُوۡبَ اِلَّا اللّٰہُ ۪۟ وَ لَمۡ یُصِرُّوۡا عَلٰی مَا فَعَلُوۡا وَ ہُمۡ یَعۡلَمُوۡنَ ﴿۱۳۵﴾', 'اور وہ کہ جب کوئی کھلا گناہ یا اپنے حق میں کوئی اور برائی کر بیٹھتے ہیں تو اللہ کو یاد کرتے اور اپنے گناہوں کی بخشش مانگتے ہیں اور اللہ کے سوا گناہ بخش بھی کون سکتا ہے؟ اور جان بوجھ کر اپنے افعال پر اڑے نہیں رہتے۔', 'اور وہ لوگ کہ جب کر بیٹھیں کچھ کھلا گناہ یا برا کام کریں اپنے حق میں [۲۰۰] تو یاد کریں اللہ کو اور بخشش مانگیں اپنے گناہوں کی اور کون ہے گناہ بخشنے والا سوا اللہ کے اور اڑتے نہیں اپنے کئے پر اور وہ جانتے ہیں', 'And those who, when they have committed Fahishah (illegal sexual intercourse etc.) or wronged themselves with evil, remember Allah and ask forgiveness for their sins; - and none can forgive sins but Allah - And do not persist in what (wrong) they have done, while they know.', '-and those who, when they happen to commit a shameful act or wrong themselves, remember Allah, then, seek forgiveness for their sins-and who is there to forgive sins except Allah?-and do not persist in what they have done, knowingly.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(429, 3, 136, 14, 5, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اُولٰٓئِکَ جَزَآؤُہُمۡ مَّغۡفِرَۃٌ مِّنۡ رَّبِّہِمۡ وَ جَنّٰتٌ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَا ؕ وَ نِعۡمَ اَجۡرُ  الۡعٰمِلِیۡنَ ﴿۱۳۶﴾ؕ', 'ایسے ہی لوگوں کا صلہ انکے پروردگار کی طرف سے بخشش اور باغ ہیں۔ جن کے نیچے نہریں بہ رہی ہیں اور وہ ان میں ہمیشہ بستے رہیں گے۔ اور اچھے کام کرنے والوں کا بدلہ بہت اچھا ہے۔', 'انہی کی جزاء ہے بخشش ان کے رب کی اور باغ جن کے نیچے نہریں بہتی ہیں ہمیشہ رہیں گے وہ لوگ ان باغوں میں اور کیا خوب مزدوری ہے کام کرنے والوں کی [۲۰۱]', 'For such, the reward is Forgiveness from their Lord, and Gardens with rivers flowing underneath (Paradise), wherein they shall abide forever. How excellent is this reward for the doers (who do righteous deeds according to Allahs Orders).', 'Their reward is forgiveness from their Lord and gardens beneath which rivers flow where they shall live forever. And excellent is the reward of those who work.'),
(430, 3, 137, 14, 5, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'قَدۡ خَلَتۡ مِنۡ قَبۡلِکُمۡ سُنَنٌ ۙ فَسِیۡرُوۡا فِی الۡاَرۡضِ فَانۡظُرُوۡا کَیۡفَ کَانَ عَاقِبَۃُ الۡمُکَذِّبِیۡنَ ﴿۱۳۷﴾', 'تم لوگوں سے پہلے بھی بہت سے واقعات گذر چکے ہیں۔ تو تم زمین میں سیر کر کے دیکھ لو کہ جھٹلانے والوں کا کیسا انجام ہوا۔', 'ہو چکے ہیں تم سے پہلے واقعات سو پھرو زمین میں اور دیکھو کہ کیا ہوا انجام جھٹلانے والوں کا [۲۰۲]', 'Many similar ways (and mishaps of life) were faced by nations (believers and disbelievers) that have passed away before you (as you have faced in the battle of Uhud), so travel through the earth, and see what was the end of those who disbelieved (in the Oneness of Allah, and disobeyed Him and His Messengers).', 'Many patterns of behavior have passed before you. So, traverse the land and see what was the fate of those who rejected (the prophets).'),
(431, 3, 138, 14, 5, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'ہٰذَا بَیَانٌ لِّلنَّاسِ وَ ہُدًی وَّ مَوۡعِظَۃٌ لِّلۡمُتَّقِیۡنَ ﴿۱۳۸﴾', 'یہ قرآن لوگوں کے لئے صاف پیغام اور اہل تقوٰی کے لئے ہدایت اور نصیحت ہے۔', 'یہ بیان ہے لوگوں کے واسطے اور ہدایت اور نصیحت ہے ڈرنے والوں کو [۲۰۳]', 'This (the Quran) is a plain statement for mankind, a guidance and instruction to those who are Al-Muttaqoon (the pious - see V.2:2).', 'This is a declaration for mankind, and guidance, and a lesson for the God-fearing.'),
(432, 3, 139, 14, 5, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ لَا تَہِنُوۡا وَ لَا تَحۡزَنُوۡا وَ اَنۡتُمُ الۡاَعۡلَوۡنَ  اِنۡ  کُنۡتُمۡ مُّؤۡمِنِیۡنَ ﴿۱۳۹﴾', 'اور بد دل نہ ہونا اور نہ غم کرنا اگر تم سچے مومن ہو تو تم ہی غالب رہو گے۔', 'اور سست نہ رہو اور نہ غم کھاؤ اور تم ہی غالب رہو گے اگر تم ایمان رکھتے ہو [۲۰۴]', 'So do not become weak (against your enemy), nor be sad, and you will be superior (in victory) if you are indeed (true) believers.', 'Do not lose heart and do not grieve, and you are the upper-most if you are believers.'),
(433, 3, 140, 14, 5, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اِنۡ یَّمۡسَسۡکُمۡ قَرۡحٌ فَقَدۡ مَسَّ الۡقَوۡمَ قَرۡحٌ مِّثۡلُہٗ ؕ وَ تِلۡکَ الۡاَیَّامُ نُدَاوِلُہَا بَیۡنَ النَّاسِ ۚ وَ لِیَعۡلَمَ اللّٰہُ الَّذِیۡنَ اٰمَنُوۡا وَ یَتَّخِذَ مِنۡکُمۡ  شُہَدَآءَ ؕ وَ اللّٰہُ  لَا یُحِبُّ الظّٰلِمِیۡنَ ﴿۱۴۰﴾ۙ', 'اگر تمہیں زخم شکست لگا ہے تو ان لوگوں کو بھی ایسا زخم لگ چکا ہے۔ اور یہ ایام زمانہ ہیں کہ ہم ان کو لوگوں میں بدلتے رہتے ہیں۔ اور اس سے یہ بھی مقصود تھا کہ اللہ ایمان والوں کو جدا کر دے اور تم میں سے بعض کو شہید بنائے اور اللہ بے انصافوں کو پسند نہیں کرتا۔', 'اگر پہنچا تم کو زخم تو پہنچ چکا ہے ان کو بھی زخم ایسا ہی اور یہ دن باری باری بدلتے رہتے ہیں ہم ان کو لوگوں میں [۲۰۵] اور اس لئے کہ معلوم کرے اللہ جن کو ایمان ہے [۲۰۶] اور کرے تم میں سےشہید اور اللہ کو محبت نہیں ظلم کرنے والوں سے [۲۰۷]', 'If a wound (and killing) has touched you, be sure a similar wound (and killing) has touched the others. And so are the days (good and not so good), We give to men by turns, that Allah may test those who believe, and that He may take martyrs from among you. And Allah likes not the Zalimoon (polytheists and wrongdoers).', 'If you have received a wound, they have received a similar wound. Such days We rotate among the people, so that Allah may know those who believe and let some of you be martyrs - and Allah does not like the unjust'),
(434, 3, 141, 14, 5, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ لِیُمَحِّصَ اللّٰہُ الَّذِیۡنَ اٰمَنُوۡا وَ یَمۡحَقَ الۡکٰفِرِیۡنَ ﴿۱۴۱﴾', 'اور یہ بھی مقصود تھا کہ اللہ ایمان والوں کو پاک صاف بنا دے اور کافروں کو نابود کردے۔', 'اور اس واسطے کہ پاک صاف کرے اللہ ایمان والوں کو اور مٹا دیوے کافروں کو [۲۰۸]', 'And that Allah may test (or purify) the believers (from sins) and destroy the disbelievers.', '- and so that Allah may purify those who believe and eradicate the disbelievers.'),
(435, 3, 142, 14, 5, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اَمۡ حَسِبۡتُمۡ اَنۡ تَدۡخُلُوا الۡجَنَّۃَ وَ لَمَّا یَعۡلَمِ اللّٰہُ الَّذِیۡنَ جٰہَدُوۡا مِنۡکُمۡ وَ یَعۡلَمَ الصّٰبِرِیۡنَ ﴿۱۴۲﴾', 'کیا تم یہ سمجھتے ہو کہ بے آزمائش بہشت میں جا داخل ہو گے حالانکہ ابھی اللہ نے تم میں سے جہاد کرنے والوں کو تو اچھی طرح معلوم کیا ہی نہیں اور یہ بھی مقصود ہے کہ وہ ثابت قدم رہنے والوں کو معلوم کرے۔', 'کیا تم کو خیال ہے کہ داخل ہو جاؤ گے جنت میں اور ابھی تک معلوم نہیں کیا اللہ نے جو لڑنے والے ہیں تم میں اور معلوم نہیں کیا ثابت رہنے والوں کو [۲۰۹]', 'Do you think that you will enter Paradise before Allah tests those of you who fought (in His Cause) and (also) tests those who are As-Sabirin (the patient ones, etc.)?', 'Do you think that you shall enter Paradise even before Allah knows those of you who carry out Jihād and those who are steadfast.'),
(436, 3, 143, 14, 5, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ لَقَدۡ کُنۡتُمۡ تَمَنَّوۡنَ الۡمَوۡتَ مِنۡ قَبۡلِ اَنۡ تَلۡقَوۡہُ ۪ فَقَدۡ رَاَیۡتُمُوۡہُ وَ اَنۡتُمۡ تَنۡظُرُوۡنَ ﴿۱۴۳﴾٪', 'اور تم موت شہادت کے آنے سے پہلے اس کی تمنا کیا کرتے تھے سو تم نے اس کو آنکھوں سے دیکھ لیا۔', 'اور تم تو آرزو کرتے تھے مرنے کی اس کی ملاقات سے پہلے سو اب دیکھ لیا تم نے اس کو آنکھوں کے سامنے [۲۱۰]', 'You did indeed wish for death (AshShahadah - martyrdom) before you met it. Now you have seen it openly with your own eyes.', 'You had longed for death before you faced it. Now, you have seen it with your eyes wide open.'),
(437, 3, 144, 15, 6, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ مَا مُحَمَّدٌ اِلَّا رَسُوۡلٌ ۚ قَدۡ خَلَتۡ مِنۡ قَبۡلِہِ الرُّسُلُ ؕ اَفَا۠ئِنۡ مَّاتَ اَوۡ قُتِلَ انۡقَلَبۡتُمۡ عَلٰۤی اَعۡقَابِکُمۡ ؕ وَ مَنۡ یَّنۡقَلِبۡ عَلٰی عَقِبَیۡہِ فَلَنۡ یَّضُرَّ اللّٰہَ شَیۡئًا ؕ وَ سَیَجۡزِی اللّٰہُ  الشّٰکِرِیۡنَ ﴿۱۴۴﴾', 'اور محمد ﷺ ایک پیغمبر ہی تو ہیں۔ ان سے پہلے بھی بہت سے پیغمبر ہو گذرے ہیں۔ بھلا اگر یہ مر جائیں یا مارے جائیں تو تم الٹے پاؤں پھر جاؤ گے؟ اور جو الٹے پاؤں پھر جائے گا تو اللہ کا کچھ نقصان نہیں کر سکے گا اور اللہ شکرگذاروں کو بڑا ثواب دے گا۔', 'اور محمد تو ایک رسول ہے ہو چکے اس سے پہلے بہت رسول پھر کیا اگر وہ مر گیا یا مارا گیا تو تم پھر جاؤ گے الٹے پاؤں اور جو کوئی پھر جائے گا الٹے پاؤں تو ہر گز نہ بگاڑے گا اللہ کا کچھ اور اللہ ثواب دے گا شکر گذاروں کو [۲۱۱]', 'Muhammad (SAW) is no more than a Messenger, and indeed (many) Messengers have passed away before him. If he dies or is killed, will you then turn back on your heels (as disbelievers)? And he who turns back on his heels, not the least harm will he do to Allah, and Allah will give reward to those who are grateful.', 'MuHammad is but a messenger, there have been messengers before him. So, if he dies or is killed, would you turn back on your heels? Whoever turns back on his heels can never harm Allah in the least. Allah shall soon reward the grateful.'),
(438, 3, 145, 15, 6, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ مَا کَانَ لِنَفۡسٍ اَنۡ تَمُوۡتَ اِلَّا بِاِذۡنِ اللّٰہِ کِتٰبًا مُّؤَجَّلًا ؕ وَ مَنۡ یُّرِدۡ ثَوَابَ الدُّنۡیَا نُؤۡتِہٖ مِنۡہَا ۚ وَ مَنۡ یُّرِدۡ  ثَوَابَ الۡاٰخِرَۃِ نُؤۡتِہٖ مِنۡہَا ؕ وَ سَنَجۡزِی الشّٰکِرِیۡنَ ﴿۱۴۵﴾', 'اور کسی شخص میں طاقت نہیں کہ اللہ کے حکم کے بغیر مر جائے اس نے موت کا وقت مقرر کر کے لکھ رکھا ہے اور جو شخص دنیا میں اپنے اعمال کا بدلہ چاہے اس کو ہم یہیں بدلہ دے دیں گے اور جو آخرت میں طالب ثواب ہو اس کو وہاں اجر عطا کریں گے اور ہم شکرگذاروں کو عنقریب بہت اچھا صلہ دیں گے۔', 'اور کوئی مر نہیں سکتا بغیر حکم اللہ کے لکھا ہوا ہے ایک وقت مقرر [۲۱۲] اور جو کوئی چاہے گا بدلہ دنیا کا دیویں گے ہم اس کو دنیا ہی سے [۲۱۳] اور جو کوئی چاہے گا بدلہ آخرت کا اس میں سےدیویں گے ہم اسکو [۲۱۴] اور ہم ثواب دیں گے احسان ماننے والوں کو [۲۱۵]', 'And no person can ever die except by Allahs Leave and at an appointed term. And whoever desires a reward in (this) world, We shall give him of it; and whoever desires a reward in the Hereafter, We shall give him thereof. And We shall reward the grateful.', 'It is not the choice of a person to die without the will of Allah, death being a time-bound destiny. Whoever seeks a reward in this world, We shall give him out of it, and whoever seeks a reward in the Hereafter, We shall give him out of it. We shall soon reward the grateful.'),
(439, 3, 146, 15, 6, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ کَاَیِّنۡ مِّنۡ نَّبِیٍّ قٰتَلَ ۙ مَعَہٗ رِبِّیُّوۡنَ کَثِیۡرٌ ۚ فَمَا وَہَنُوۡا لِمَاۤ اَصَابَہُمۡ فِیۡ سَبِیۡلِ اللّٰہِ وَ مَا ضَعُفُوۡا وَ مَا اسۡتَکَانُوۡا ؕ وَ اللّٰہُ  یُحِبُّ الصّٰبِرِیۡنَ ﴿۱۴۶﴾', 'اور بہت سے نبی ہوئے ہیں جن کے ساتھ ہو کر اکثر اہل اللہ کے دشمنوں سے لڑے ہیں۔ تو جو مصیبتیں ان پر اللہ کی راہ میں واقع ہوئیں ان کے سبب انہوں نے نہ تو ہمت ہاری اور نہ بزدلی کی نہ کافروں سے دبے اور اللہ استقلال رکھنے والوں کو دوست رکھتا ہے۔', 'اور بہت نبی ہیں جن کے ساتھ ہو کر لڑے ہیں بہت خدا کے طالب پھر نہ ہارے ہیں کچھ تکلیف پہنچنے سے اللہ کی راہ میں اور نہ سست ہوئے ہیں اور نہ دب گئے ہیں اور اللہ محبت کرتا ہے ثابت قدم رہنے والوں سے [۲۱۶]', 'And many a Prophet (i.e. many from amongst the Prophets) fought (in Allahs Cause) and along with him (fought) large bands of religious learned men. But they never lost heart for that which did befall them in Allahs Way, nor did they weaken nor degrade themselves. And Allah loves As-Sabirin (the patient ones, etc.).', 'There have been many prophets with whom many men of Allah have fought; they did not lose heart for what they suffered in the way of Allah, nor did they become weak, nor did they yield. Allah loves the steadfast.'),
(440, 3, 147, 15, 6, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ مَا کَانَ قَوۡلَہُمۡ اِلَّاۤ اَنۡ قَالُوۡا رَبَّنَا اغۡفِرۡ لَنَا ذُنُوۡبَنَا وَ اِسۡرَافَنَا فِیۡۤ  اَمۡرِنَا وَ ثَبِّتۡ اَقۡدَامَنَا وَ انۡصُرۡنَا عَلَی الۡقَوۡمِ الۡکٰفِرِیۡنَ ﴿۱۴۷﴾', 'اور اس حالت میں ان کے منہ سے کوئی بات نکلتی تو یہی کہ اے پروردگار ہمارے گناہ اور زیادتیاں جو ہم اپنے کاموں میں کرتے رہے ہیں معاف فرما۔ اور ہم کو ثابت قدم رکھ اور کافروں پر فتح عنایت کر۔', 'اور کچھ نہیں بولے مگر یہی کہا کہ اے رب ہمارےبخش ہمارے گناہ اور جو ہم سےزیادتی ہوئی ہمارےکام میں اور ثابت رکھ قدم ہمارے اور مدد دے ہم کو قوم کفار پر [۲۱۷]', 'And they said nothing but: \"Our Lord! Forgive us our sins and our transgressions (in keeping our duties to You), establish our feet firmly, and give us victory over the disbelieving folk.\"', 'They had nothing else to say except that they said: “Our Lord, forgive us our sins and our excesses in our conduct, make firm our feet and help us against the disbelieving people.”'),
(441, 3, 148, 15, 6, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'فَاٰتٰىہُمُ اللّٰہُ ثَوَابَ الدُّنۡیَا وَ حُسۡنَ ثَوَابِ الۡاٰخِرَۃِ ؕ وَ اللّٰہُ یُحِبُّ الۡمُحۡسِنِیۡنَ ﴿۱۴۸﴾٪', 'تو اللہ نے ان کو دنیا میں بھی بدلہ دیا اور آخرت میں بھی بہت اچھا بدلہ دے گا اور اللہ نیکوکاروں کو دوست رکھتا ہے۔', 'پھر دیا اللہ نے ان کو ثواب دنیا کا اور خوب ثواب آخرت کا اور اللہ محبت رکھتا ہے نیک کام کرنے والوں سے [۲۱۸]', 'So Allah gave them the reward of this world, and the excellent reward of the Hereafter. And Allah loves Al-Muhsinoon (the gooddoers - see the footnote of V.3:134).', 'So, Allah gave them the return in this world and also the better rewards in the Hereafter. Allah loves those who do good.'),
(442, 3, 149, 16, 7, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اِنۡ تُطِیۡعُوا الَّذِیۡنَ کَفَرُوۡا یَرُدُّوۡکُمۡ عَلٰۤی اَعۡقَابِکُمۡ فَتَنۡقَلِبُوۡا خٰسِرِیۡنَ ﴿۱۴۹﴾', 'مومنو! اگر تم کافروں کا کہا مان لو گے تو وہ تم کو الٹے پاؤں پھیر کر مرتد کر دیں گے پھر تم بڑے خسارے میں پڑ جاؤ گے۔', 'اے ایمان والو اگر تم کہا مانو گے کافروں کا تو وہ تم کو پھیر دیں گے الٹے پاؤں پھر جا پڑو گے تم نقصان میں [۲۱۹]', 'O you who believe! If you obey those who disbelieve, they will send you back on your heels, and you will turn back (from Faith) as losers.', 'O you who believe, if you obey those who disbelieve, they will make you turn back on your heels, then you shall turn into losers.'),
(443, 3, 150, 16, 7, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'بَلِ اللّٰہُ مَوۡلٰىکُمۡ ۚ وَ ہُوَ خَیۡرُ النّٰصِرِیۡنَ ﴿۱۵۰﴾', 'یہ تمہارے مددگار نہیں ہیں بلکہ اللہ تمہارا مددگار ہے اور وہ سب سے بہتر مددگار ہے۔', 'بلکہ اللہ تمہارا مددگار ہے اور اس کی مدد سب سے بہتر ہے [۲۲۰]', 'Nay, Allah is your Maula (Patron, Lord, Helper and Protector, etc.), and He is the Best of helpers.', 'Instead, Allah is your Lord, and He is the best of all helpers.'),
(444, 3, 151, 16, 7, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'سَنُلۡقِیۡ فِیۡ قُلُوۡبِ الَّذِیۡنَ  کَفَرُوا الرُّعۡبَ بِمَاۤ اَشۡرَکُوۡا بِاللّٰہِ مَا لَمۡ یُنَزِّلۡ بِہٖ سُلۡطٰنًا ۚ وَ مَاۡوٰىہُمُ النَّارُ ؕ وَ بِئۡسَ مَثۡوَی الظّٰلِمِیۡنَ ﴿۱۵۱﴾', 'ہم عنقریب کافروں کے دلوں میں رعب بٹھا دیں گے کیونکہ یہ اللہ کے ساتھ شرک کرتے ہیں جس کی اس نے کوئی بھی دلیل نازل نہیں کی۔ اور ان کا ٹھکانہ دوزخ ہے وہ ظالموں کا بہت برا ٹھکانہ ہے۔', 'اب ڈالیں گے ہم کافروں کے دل میں ہیبت اس واسطے کہ انہوں نے شریک ٹھہرایا اللہ کا جس کی اس نے کوئی سند نہیں اتاری اور ان کا ٹھکانہ دوزخ ہے اور وہ برا ٹھکانا ہے ظالموں کا [۲۲۱]', 'We shall cast terror into the hearts of those who disbelieve, because they joined others in worship with Allah, for which He had sent no authority; their abode will be the Fire and how evil is the abode of the Zalimoon (polytheists and wrongdoers).', 'We shall put awe into the hearts of those who disbelieve, since they have associated with Allah something for which He has not sent any authority. Their ultimate place is the Fire; and evil is the abode of the unjust.'),
(445, 3, 152, 16, 7, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ لَقَدۡ صَدَقَکُمُ اللّٰہُ وَعۡدَہٗۤ  اِذۡ تَحُسُّوۡنَہُمۡ بِاِذۡنِہٖ ۚ حَتّٰۤی  اِذَا فَشِلۡتُمۡ وَ تَنَازَعۡتُمۡ فِی الۡاَمۡرِ وَ عَصَیۡتُمۡ مِّنۡۢ بَعۡدِ مَاۤ اَرٰىکُمۡ مَّا تُحِبُّوۡنَ ؕ مِنۡکُمۡ مَّنۡ یُّرِیۡدُ الدُّنۡیَا وَ مِنۡکُمۡ مَّنۡ یُّرِیۡدُ الۡاٰخِرَۃَ ۚ  ثُمَّ صَرَفَکُمۡ عَنۡہُمۡ لِیَبۡتَلِیَکُمۡ ۚ وَ لَقَدۡ عَفَا عَنۡکُمۡ  ؕ وَ اللّٰہُ ذُوۡ فَضۡلٍ عَلَی الۡمُؤۡمِنِیۡنَ ﴿۱۵۲﴾', 'اور اللہ نے تم سے اپنا وعدہ سچا کردیا یعنی اس وقت جب کہ تم کافروں کو اس کے حکم سے قتل کر رہے تھے۔ یہاں تک کہ جو تم چاہتے تھے اللہ نے تم کو دکھا دیا۔ اس کے بعد تم نے ہمت ہار دی اور پیغمبر کے حکم کی تعمیل میں جھگڑا کرنے لگے اور تم نے اس کی نافرمانی کی۔ بعض تو تم میں سے دنیا کے طلبگار تھے اور بعض آخرت کے طالب۔ اس وقت اللہ نے تم کو ان کے سامنے سے ہٹا دیا تا کہ تمہاری آزمائش کرے اور اس نے تمہارا قصور معاف کر دیا۔ اور اللہ مومنوں پر بڑا فضل کرنے والا ہے۔', 'اور اللہ تو سچا کر چکا تم سے اپنا وعدہ جب تم قتل کرنے لگے انکو اسکے حکم سے [۲۲۲] یہاں تک کہ جب تم نے نامردی کی اور کام میں جھگڑا ڈالا اور نافرمانی کی [۲۲۳] بعد اس کے کہ تم کو دکھا چکا تمہاری خوشی کی چیز کوئی تم میں سے چاہتا تھا دنیا اور کوئی تم میں چاہتا تھا آخرت [۲۲۴] پھر تم کو الٹ دیا ان پر سے تاکہ تم کو آزماوے [۲۲۵] اور وہ تو تم کو معاف کر چکا [۲۲۶] اور اللہ کا فضل ہے ایمان والوں پر [۲۲۷]', 'And Allah did indeed fulfil His Promise to you when you were killing them (your enemy) with His Permission; until (the moment) you lost your courage and fell to disputing about the order, and disobeyed after He showed you (of the booty) which you love. Among you are some that desire this world and some that desire the Hereafter. Then He made you flee from them (your enemy), that He might test you. But surely, He forgave you, and Allah is Most Gracious to the believers.', 'Allah has surely fulfilled His promise to you when you, with His will, were killing them off, until you showed weakness and disputed in the matter and disobeyed after He had shown you what you liked.Among you there were some who were seeking the mundane, and among you there were others who were seeking the Hereafter. After that, He reversed your position against them, so that He may test you. Of course, He has forgiven you. Allah is All-Gracious to the believers.'),
(446, 3, 153, 16, 7, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اِذۡ تُصۡعِدُوۡنَ وَ لَا تَلۡوٗنَ عَلٰۤی اَحَدٍ وَّ الرَّسُوۡلُ یَدۡعُوۡکُمۡ فِیۡۤ  اُخۡرٰىکُمۡ فَاَثَابَکُمۡ غَمًّۢا بِغَمٍّ لِّکَیۡلَا تَحۡزَنُوۡا عَلٰی مَا فَاتَکُمۡ وَ لَا مَاۤ  اَصَابَکُمۡ ؕ وَ اللّٰہُ خَبِیۡرٌۢ  بِمَا تَعۡمَلُوۡنَ ﴿۱۵۳﴾', 'وہ وقت بھی یاد کرنے کے لائق ہے جب تم لوگ دور بھاگے جاتے تھے اور کسی کو پیچھے پھر کر نہیں دیکھتے تھے اور رسول اللہ ﷺ تم کو تمہارے پیچھے کھڑے بلا رہے تھے تو اللہ نے تم کو غم پر غم پہنچایا تا کہ جو چیز تمہارے ہاتھ سے جاتی رہی یا جو مصیبت تم پر واقع ہوئی ہے اس سے تم غمگین نہ ہو اور اللہ تمہارے سب اعمال سے خبردار ہے۔', 'جب تم چڑھے چلے جاتے تھے اور پیچھے پھر کر نہ دیکھتے تھے کسی کو اور رسول پکارتا تھا تم کو تمہارے پیچھے سے [۲۲۸] پھرپہنچا تم کو غم عوض میں غم کے تاکہ تم غم نہ کیا کرو اس پر جو ہاتھ سے نکل جاوے اور نہ اس پر کہ جو کچھ پیش آ جاوے [۲۲۹] اور اللہ کو خبر ہے تمہارے کام کی [۲۳۰]', '(And remember) when you ran away (dreadfully) without even casting a side glance at anyone, and the Messenger (Muhammad SAW) was in your rear calling you back. There did Allah give you one distress after another by way of requital to teach you not to grieve for that which had escaped you, nor for that which had befallen you. And Allah is WellAware of all that you do.', 'When you were going away, not even turning to look at anyone, and the Messenger was calling you from behind you. He awarded you sorrow for sorrow, so that you should not grieve (in future) over what you lost, or for what you suffered. Allah is All-Aware of what you do.'),
(447, 3, 154, 16, 7, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'ثُمَّ اَنۡزَلَ عَلَیۡکُمۡ مِّنۡۢ بَعۡدِ الۡغَمِّ اَمَنَۃً نُّعَاسًا یَّغۡشٰی طَآئِفَۃً مِّنۡکُمۡ ۙ وَ طَآئِفَۃٌ قَدۡ اَہَمَّتۡہُمۡ  اَنۡفُسُہُمۡ  یَظُنُّوۡنَ بِاللّٰہِ غَیۡرَ الۡحَقِّ ظَنَّ الۡجَاہِلِیَّۃِ ؕ یَقُوۡلُوۡنَ ہَلۡ لَّنَا مِنَ الۡاَمۡرِ  مِنۡ شَیۡءٍ ؕ قُلۡ   اِنَّ الۡاَمۡرَ  کُلَّہٗ  لِلّٰہِ ؕ یُخۡفُوۡنَ فِیۡۤ اَنۡفُسِہِمۡ مَّا لَا یُبۡدُوۡنَ لَکَ ؕ یَقُوۡلُوۡنَ لَوۡ کَانَ لَنَا مِنَ الۡاَمۡرِ شَیۡءٌ مَّا قُتِلۡنَا ہٰہُنَا ؕ قُلۡ لَّوۡ کُنۡتُمۡ فِیۡ بُیُوۡتِکُمۡ لَبَرَزَ الَّذِیۡنَ کُتِبَ عَلَیۡہِمُ الۡقَتۡلُ اِلٰی مَضَاجِعِہِمۡ ۚ وَ لِیَبۡتَلِیَ اللّٰہُ مَا فِیۡ صُدُوۡرِکُمۡ وَ لِیُمَحِّصَ مَا فِیۡ قُلُوۡبِکُمۡ ؕ وَ اللّٰہُ عَلِیۡمٌۢ بِذَاتِ الصُّدُوۡرِ ﴿۱۵۴﴾', 'پھر اللہ نے اس پریشانی کے بعد تم پر تسلی نازل فرمائی۔ ( یعنی ) نیند کہ تم میں سے ایک جماعت پر طاری ہو گئ اور کچھ لوگ جنکو جان کے لالے پڑ رہے تھے اللہ کے بارے میں ناحق ایّام کفر کے سے گمان کرتے تھے۔ اور کہتے تھے بھلا ہمارے اختیار کی کچھ بات ہے؟ تم کہدو کہ بیشک سب باتیں اللہ ہی کے اختیار میں ہیں۔ یہ لوگ بہت سی باتیں دلوں میں مخفی رکھتے ہیں جو تم پر ظاہر نہیں کرتے تھے۔ کہتے تھے کہ ہمارے بس کی بات ہوتی تو ہم یہاں قتل ہی نہ کئے جاتے۔  کہدو کہ اگر تم اپنے گھروں میں بھی ہوتے تو جنکی تقدیر میں مارا جانا لکھا تھا وہ اپنی اپنی قتل گاہوں کی طرف ضرور نکل آتے۔ اس سے غرض یہ تھی کہ اللہ تمہارے سینوں کی باتوں کو آزمائے اور جو کچھ تمہارے دلوں میں ہے اس کو صاف کر دے۔ اور اللہ دلوں کی باتوں سے خوب واقف ہے۔', 'پھر تم پر اتارا تنگی کے بعد امن کو جو اونگھ تھی کہ ڈھانک لیا اس اونگھ نے بعضوں کو تم میں سے [۲۳۱] اور بعضوں کو فکر پڑ رہا تھا اپنی جان کا [۲۳۲] خیال کرتےتھے اللہ پر جھوٹے خیال جاہلوں جیسے [۲۳۳] کہتے تھے کچھ بھی کام ہے ہمارے ہاتھ میں [۲۳۴] تو کہہ سب کام ہے اللہ کے ہاتھ [۲۳۵] وہ اپنے جی میں چھپاتے ہیں جو تجھ سے ظاہر نہیں کرتے کہتے ہیں اگر کچھ کام ہوتا ہمارے ہاتھ تو ہم مارےنہ جاتے اس جگہ [۲۳۶] تو کہہ اگر تم ہوتے اپنے گھروں میں البتہ باہر نکلتےجن پر لکھ دیا تھا مارا جانا اپنے پڑاؤ پر [۲۳۷] اور اللہ کو آزمانا تھا جو کچھ تمہارےجی میں ہے اور صاف کرنا تھا اس کا جو تمہارے دل میں ہے اور اللہ جانتا ہے دلوں کے بھید [۲۳۸]', 'Then after the distress, He sent down security for you. Slumber overtook a party of you, while another party was thinking about themselves (as how to save their ownselves, ignoring the others and the Prophet SAW) and thought wrongly of Allah - the thought of ignorance. They said, \"Have we any part in the affair?\" Say you (O Muhammad SAW): \"Indeed the affair belongs wholly to Allah.\" They hide within themselves what they dare not reveal to you, saying: \"If we had anything to do with the affair, none of us would have been killed here.\" Say: \"Even if you had remained in your homes, those for whom death was decreed would certainly have gone forth to the place of their death,\" but that Allah might test what is in your breasts; and to Mahis that which was in your hearts (sins), and Allah is AllKnower of what is in (your) breasts.', 'Then, after the grief, He poured tranquility upon you - a drowsiness overtaking a group of you. Another group was worrying about their own selves, harboring thoughts about Allah that were untrue - thoughts of ignorance. They were saying, “Is there anything in our hands?” Say, “The whole thing belongs to Allah.” They conceal in their hearts what they do not disclose to you.They say, “If we had any say in the matter, we would not have been killed here.”Say, “If you were in your homes, those destined to be killed would have come out all the way to their (final) resting -places.” (All this was done) so that Allah may test your inner qualities and may purify what is in your hearts. Allah is All-Aware of what lies in the hearts.'),
(448, 3, 155, 16, 7, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اِنَّ الَّذِیۡنَ تَوَلَّوۡا مِنۡکُمۡ یَوۡمَ الۡتَقَی الۡجَمۡعٰنِ ۙ اِنَّمَا اسۡتَزَلَّہُمُ الشَّیۡطٰنُ بِبَعۡضِ مَا کَسَبُوۡا ۚ وَ لَقَدۡ عَفَا اللّٰہُ عَنۡہُمۡ ؕ اِنَّ اللّٰہَ  غَفُوۡرٌ  حَلِیۡمٌ ﴿۱۵۵﴾٪', 'جو لوگ تم میں سے احد کے دن جبکہ مومنوں اور کافروں کی دو جماعتیں ایک دوسرے سے گتھ گئیں جنگ سے بھاگ گئے تو ان کے بعض افعال کے سبب شیطان نے ان کو پھسلا دیا تھا۔ مگر اللہ نے ان کا قصور معاف کر دیا۔ بیشک اللہ بخشنے والا ہے بردبار ہے۔', 'جو لوگ تم میں سے ہٹ گئے جس دن لڑیں دو فوجیں سو انکو بہکا دیا شیطان نے ان کے گناہ کی شامت سے اور ان کو بخش چکا اللہ اللہ بخشنے والا ہے تحمل کرنے والا[۲۳۹]', 'Those of you who turned back on the day the two hosts met (i.e. the battle of Uhud), it was Shaitan (Satan) who caused them to backslide (run away from the battlefield) because of some (sins) they had earned. But Allah, indeed, has forgiven them. Surely, Allah is OftForgiving, Most Forbearing.', 'Surely, those of you who turned back on the day when the two troops faced each other, Satan had but made them slip for some of their deeds. Of course, Allah has forgiven them. Certainly, Allah is Most-Forgiving, Very-Forbearing.'),
(449, 3, 156, 17, 8, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَکُوۡنُوۡا کَالَّذِیۡنَ کَفَرُوۡا وَ قَالُوۡا لِاِخۡوَانِہِمۡ اِذَا ضَرَبُوۡا فِی الۡاَرۡضِ اَوۡ کَانُوۡا غُزًّی لَّوۡ کَانُوۡا عِنۡدَنَا مَا مَاتُوۡا وَ مَا قُتِلُوۡا ۚ لِیَجۡعَلَ اللّٰہُ ذٰلِکَ حَسۡرَۃً فِیۡ قُلُوۡبِہِمۡ ؕ وَ اللّٰہُ یُحۡیٖ وَ یُمِیۡتُ ؕ وَ اللّٰہُ بِمَا تَعۡمَلُوۡنَ  بَصِیۡرٌ ﴿۱۵۶﴾', 'مومنو! ان لوگوں جیسے نہ ہونا جو کفر کرتے ہیں اور ان کے مسلمان بھائی جب اللہ کی راہ میں سفر کریں اور مرجائیں یا جہاد کو نکلیں اور مارے جائیں تو ان کی نسبت کہتے ہیں کہ اگر وہ ہمارے پاس رہتے تو نہ مرتے اور نہ مارے جاتے یہ اسلئے کہ اللہ ان لوگوں کے دلوں میں افسوس پیدا کر دے۔ اور زندگی اور موت تو اللہ ہی دیتا ہے اور اللہ تمہارے سب کاموں کو دیکھ رہا ہے۔', 'اے ایمان والو تم نہ ہو ان کی طرح جو کافر ہوئے [۲۴۰] اور کہتےہیں اپنے بھائیوں کو [۲۴۱] جب وہ سفر کو نکلیں ملک میں یا ہوں جہاد میں اگر رہتے ہمارے پاس تو نہ مرتے اور نہ مارے جاتے تاکہ اللہ ڈالے اس گمان سے افسوس ان کے دلوں میں [۲۴۲] اور اللہ ہی جلاتا ہے اور مارتا ہے [۲۴۳] اور اللہ تمہارے سب کام دیکھتا ہے [۲۴۴]', 'O you who believe! Be not like those who disbelieve (hypocrites) and who say to their brethren when they travel through the earth or go out to fight: \"If they had stayed with us, they would not have died or been killed,\" so that Allah may make it a cause of regret in their hearts. It is Allah that gives life and causes death. And Allah is AllSeer of what you do.', 'O you who believe, do not be like those who disbelieved and said about their brethren while they travelled on the earth or had to fight, “Had they been with us, they would have not died, nor would they have been killed.” The result is that Allah makes it a remorse resting in their hearts. Allah gives life and brings death; Allah is watchful of what you do.'),
(450, 3, 157, 17, 8, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ لَئِنۡ قُتِلۡتُمۡ فِیۡ سَبِیۡلِ اللّٰہِ اَوۡ مُتُّمۡ لَمَغۡفِرَۃٌ مِّنَ اللّٰہِ وَ رَحۡمَۃٌ خَیۡرٌ مِّمَّا یَجۡمَعُوۡنَ ﴿۱۵۷﴾', 'اور اگر تم اللہ کے رستے میں مارے جاؤ یا مر جاؤ تو جو مال و متاع لوگ جمع کرتے ہیں اس سے اللہ کی بخشش اور رحمت کہیں بہتر ہے۔', 'اور اگر تم مارے گئے اللہ کی راہ میں یا مر گئے [۲۴۵] تو بخشش اللہ کی اور مہربانی اسکی بہتر ہے اس چیز سے جو وہ جمع کرتے ہیں', 'And if you are killed or die in the Way of Allah, forgiveness and mercy from Allah are far better than all that they amass (of worldly wealths, etc.).', 'If you are killed in the way of Allah or die, the forgiveness from Allah and the mercy is far better than what they accumulate'),
(451, 3, 158, 17, 8, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ لَئِنۡ مُّتُّمۡ اَوۡ قُتِلۡتُمۡ لَاِالَی اللّٰہِ تُحۡشَرُوۡنَ ﴿۱۵۸﴾', 'اور اگر تم مر جاؤ یا مارے جاؤ تو اللہ کے حضور میں ضرور اکٹھے کئے جاؤ گے۔', 'اور اگر تم مر گئے یا مارے گئے تو البتہ اللہ ہی کے آگے اکٹھے ہو گے تم سب [۲۴۶]', 'And whether you die, or are killed, verily, unto Allah you shall be gathered.', 'If you die or get killed, it is towards Allah that you shall be gathered.'),
(452, 3, 159, 17, 8, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'فَبِمَا رَحۡمَۃٍ مِّنَ اللّٰہِ لِنۡتَ لَہُمۡ ۚ وَ لَوۡ کُنۡتَ فَظًّا غَلِیۡظَ الۡقَلۡبِ لَانۡفَضُّوۡا مِنۡ حَوۡلِکَ ۪ فَاعۡفُ عَنۡہُمۡ وَ اسۡتَغۡفِرۡ لَہُمۡ وَ شَاوِرۡہُمۡ فِی الۡاَمۡرِ ۚ فَاِذَا عَزَمۡتَ فَتَوَکَّلۡ عَلَی اللّٰہِ ؕ اِنَّ اللّٰہَ یُحِبُّ الۡمُتَوَکِّلِیۡنَ ﴿۱۵۹﴾', 'پھر اے نبی اللہ کی مہربانی سے تم ان لوگوں کے لئے نرم مزاج واقع ہوئے ہو اور اگر تم بدخو اور سخت دل ہوتے تو یہ تمہارے پاس سے بھاگ کھڑے ہوتے۔  سو ان کو معاف کر دو اور ان کے لئے اللہ سے مغفرت مانگو اور اپنے کاموں میں ان سے مشورت لیا کرو۔ اور جب کسی کام کا پختہ ارادہ کر لو تو اللہ پر بھروسہ رکھو۔ بیشک اللہ بھروسہ رکھنے والوں کو دوست رکھتا ہے۔', 'سو کچھ اللہ ہی کی رحمت ہے جو تو نرم دل مل گیا ان کو اور اگر تو ہوتا تندخو سخت دل تو متفرق ہو جاتے تیرے پاس سے سو تو ان کو معاف کر اور ان کے واسطے بخشش مانگ اور ان سے مشورہ لے کام میں پھر جب قصد کر چکا تو اس کام کا تو پھر بھروسہ کر اللہ پر اللہ کو محبت ہے توکل والوں سے [۲۴۷]', 'And by the Mercy of Allah, you dealt with them gently. And had you been severe and harshhearted, they would have broken away from about you; so pass over (their faults), and ask (Allahs) Forgiveness for them; and consult them in the affairs. Then when you have taken a decision, put your trust in Allah, certainly, Allah loves those who put their trust (in Him).', 'So, (O Prophet) it is through mercy from Allah that you are gentle to them. Had you been rough and hard-hearted, they would have dispersed from around you. So, pardon them, and seek Forgiveness for them. Consult them in the matter and, once you have taken a decision, place your trust in Allah. Surely, Allah loves those who place their trust in Him.'),
(453, 3, 160, 17, 8, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اِنۡ یَّنۡصُرۡکُمُ اللّٰہُ فَلَا غَالِبَ لَکُمۡ ۚ وَ اِنۡ یَّخۡذُلۡکُمۡ فَمَنۡ ذَا الَّذِیۡ یَنۡصُرُکُمۡ مِّنۡۢ بَعۡدِہٖ ؕ وَ عَلَی اللّٰہِ فَلۡیَتَوَکَّلِ الۡمُؤۡمِنُوۡنَ ﴿۱۶۰﴾', 'اگر اللہ تمہارا مددگار ہے تو تم پر کوئی غالب نہیں آ سکتا اور اگر وہ تمہیں چھوڑ دے تو پھر کون ہے اسکے بعد تمہاری مدد کرے اور مومنوں کو تو چاہیے کہ اللہ ہی پر بھروسہ رکھیں۔', 'اگر اللہ تمہاری مدد کرے گا تو کوئی تم پر غالب نہ ہو سکے گا اور اگر مدد نہ کرے تمہاری تو پھر ایسا کون ہے جو مدد کر سکے تمہاری اس کے بعد اور اللہ ہی پر بھروسا چاہئے مسلمانوں کو [۲۴۸]', 'If Allah helps you, none can overcome you; and if He forsakes you, who is there after Him that can help you? And in Allah (Alone) let believers put their trust.', 'If Allah helps you, there is none to overcome you. And if He abandons you, then, who is there to help you after that? In Allah the believers should place their trust.'),
(454, 3, 161, 17, 8, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ مَا کَانَ لِنَبِیٍّ اَنۡ یَّغُلَّ ؕ وَ مَنۡ یَّغۡلُلۡ یَاۡتِ بِمَا غَلَّ  یَوۡمَ الۡقِیٰمَۃِ ۚ ثُمَّ  تُوَفّٰی کُلُّ نَفۡسٍ مَّا کَسَبَتۡ وَ ہُمۡ لَا یُظۡلَمُوۡنَ ﴿۱۶۱﴾', 'اور کبھی نہیں ہو سکتا کہ کوئی پیغمبر خیانت کرے۔ اور خیانت کرنے والوں کو قیامت کے دن خیانت کی ہوئی چیز اللہ کے روبرو لا حاضر کرنی ہو گی۔ پھر ہر شخص کو اس کے اعمال کا پورا پورا بدلہ دیا جائے گا اور انکے ساتھ بے انصافی نہیں کی جائے گی۔', 'اور نبی کا کام نہیں کہ کچھ چھپا رکھے اور جو کوئی چھپاوے گا وہ لائے گا اپنی چھپائی چیز دن قیامت کے پھر پورا پاوے گا ہر کوئی جو اس نے کمایا اور ان پر ظلم نہ ہو گا [۲۴۹]', 'It is not for any Prophet to take illegally a part of booty (Ghulul), and whosoever deceives his companions as regards the booty, he shall bring forth on the Day of Resurrection that which he took (illegally). Then every person shall be paid in full what he has earned, - and they shall not be dealt with unjustly.', 'It is not conceivable from a prophet to misappropriate the spoils. Whoever misappropriates shall bring forth, on Doomsday, what he misappropriated. Then, everybody shall be paid, in full, for what he has earned, and they shall not be wronged.'),
(455, 3, 162, 17, 8, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اَفَمَنِ اتَّبَعَ رِضۡوَانَ اللّٰہِ کَمَنۡۢ بَآءَ بِسَخَطٍ مِّنَ اللّٰہِ وَ مَاۡوٰىہُ جَہَنَّمُ ؕ وَ بِئۡسَ الۡمَصِیۡرُ  ﴿۱۶۲﴾', 'بھلا جو شخص اللہ کی خوشنودی کا تابع ہو وہ اس شخص کی طرح ہو سکتا ہے جو اللہ کی ناخوشی میں گرفتار ہو اور جس کا ٹھکانہ دوزخ ہے اور وہ برا ٹھکانہ ہے۔', 'کیا ایک شخص جو تابع ہے اللہ کی مرضی کا برابر ہو سکتا ہے اسکے جس نے کمایا غصہ اللہ کا اور اس کا ٹھکانا دوزخ ہے اور کیا ہی بری جگہ پہنچا [۲۵۰]', 'Is then one who follows (seeks) the good Pleasure of Allah (by not taking illegally a part of the booty) like the one who draws on himself the Wrath of Allah (by taking a part of the booty illegally - Ghulul)? - his abode is Hell, - and worst, indeed is that destination!', 'How then, could one who submits to the pleasure of Allah be equal to him who returns with displeasure from Allah? His ultimate place is the Fire; and what an evil end it is!'),
(456, 3, 163, 17, 8, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'ہُمۡ دَرَجٰتٌ عِنۡدَ اللّٰہِ ؕ وَ اللّٰہُ بَصِیۡرٌۢ  بِمَا یَعۡمَلُوۡنَ ﴿۱۶۳﴾', 'سب لوگوں کے اللہ کے ہاں مختلف درجے ہیں اور اللہ ان کے سب اعمال دیکھ رہا ہے۔', 'لوگوں کے مختلف درجے ہیں اللہ کے ہاں اور اللہ دیکھتا ہے جو کچھ کرتے ہیں [۲۵۱]', 'They are in varying grades with Allah, and Allah is AllSeer of what they do.', 'They are of various ranks with Allah. Allah is watchful of what they do.'),
(457, 3, 164, 17, 8, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'لَقَدۡ مَنَّ اللّٰہُ عَلَی الۡمُؤۡمِنِیۡنَ اِذۡ بَعَثَ فِیۡہِمۡ رَسُوۡلًا مِّنۡ اَنۡفُسِہِمۡ یَتۡلُوۡا عَلَیۡہِمۡ اٰیٰتِہٖ وَ یُزَکِّیۡہِمۡ وَ یُعَلِّمُہُمُ الۡکِتٰبَ وَ الۡحِکۡمَۃَ ۚ وَ  اِنۡ کَانُوۡا مِنۡ قَبۡلُ لَفِیۡ ضَلٰلٍ مُّبِیۡنٍ ﴿۱۶۴﴾', 'اللہ نے مومنوں پر یقینًا احسان کیا ہے کہ ان میں انہیں میں سے ایک پیغمبر بھیجے جو ان کو اللہ کی آیتیں پڑھ پڑھ کو سناتے اور ان کو پاک کرتے اور انہیں کتاب و حکمت کی تعلیم دیتے ہیں۔ اور پہلے تو یہ لوگ کھلی گمراہی میں تھے۔', 'اللہ نے احسان کیا ایمان والوں پر جو بھیجا ان میں رسول انہی میں کا [۲۵۲] پڑھتا ہے ان پر آیتیں اس کی اور پاک کرتا ہے انکو یعنی شرک وغیرہ سے اور سکھلاتا ہے انکو کتاب اور کام کی بات اور وہ تو پہلے سے صریح گمراہی میں تھے [۲۵۳]', 'Indeed Allah conferred a great favour on the believers when He sent among them a Messenger (Muhammad SAW) from among themselves, reciting unto them His Verses (the Quran), and purifying them (from sins by their following him), and instructing them (in) the Book (the Quran) and AlHikmah (the wisdom and the Sunnah of the Prophet SAW (i.e. his legal ways, statements, acts of worship, etc.)), while before that they had been in manifest error.', 'Allah has surely conferred favor on the believers when He raised in their midst a messenger from among themselves who recites to them His verses and makes them pure and teaches them the Book and the Wisdom, while earlier, they were in open error.'),
(458, 3, 165, 17, 8, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اَوَ لَمَّاۤ اَصَابَتۡکُمۡ مُّصِیۡبَۃٌ قَدۡ اَصَبۡتُمۡ مِّثۡلَیۡہَا ۙ قُلۡتُمۡ اَنّٰی ہٰذَا ؕ قُلۡ ہُوَ مِنۡ عِنۡدِ اَنۡفُسِکُمۡ ؕ اِنَّ اللّٰہَ عَلٰی کُلِّ شَیۡءٍ  قَدِیۡرٌ ﴿۱۶۵﴾', 'بھلا یہ کیا بات ہے کہ جب احد کے دن کفار کے ہاتھ سے تم پر مصیبت واقع ہوئی حالانکہ جنگ بدر میں اس سے دگنی مصیبت تمہارے ہاتھ سے ان پر پڑ چکی ہے تو تم کہنے لگے کہ یہ آفت ہم پر کہاں سے آپڑی کہدو کہ یہ تمہاری ہی شامت اعمال ہے کہ تم نے پیغمبر کے حکم کے خلاف کیا بیشک اللہ ہر چیز پر قادر ہے۔', 'کیا جس وقت پہنچی تم کو ایک تکلیف کہ تم پہنچا چکے ہو اس سے دوچند تو کہتے ہو یہ کہاں سے آئی [۲۵۴] تو کہہ دے یہ تکلیف تم کو پہنچی تمہاری ہی طرف سے [۲۵۵] بیشک اللہ ہر چیز پر قادر ہے', '(What is the matter with you?) When a single disaster smites you, although you smote (your enemies) with one twice as great, you say: \"From where does this come to us?\" Say (to them), \"It is from yourselves (because of your evil deeds).\" And Allah has power over all things.', 'How is it that, when you suffered a hardship the twice of which you had inflicted upon them, you say, “Where did this come from?” Say, “This is from your own selves. Allah is surely Powerful over everything.”'),
(459, 3, 166, 17, 8, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ مَاۤ اَصَابَکُمۡ یَوۡمَ الۡتَقَی الۡجَمۡعٰنِ فَبِاِذۡنِ اللّٰہِ وَ لِیَعۡلَمَ الۡمُؤۡمِنِیۡنَ ﴿۱۶۶﴾ۙ', 'اور جو مصیبت تم پر دونوں جماعتوں کے مقابلے کے دن واقع ہوئی سو اللہ کے حکم سے واقع ہوئی اور اس سے یہ مقصود تھا کہ اللہ مومنوں کو اچھی طرح معلوم کر لے۔', 'اور جو کچھ تم کو پیش آیا اس دن کہ ملیں دو فوجیں سو اللہ کے حکم سے اور اس واسطے کہ معلوم کرے ایمان والوں کو', 'And what you suffered (of the disaster) on the day (of the battle of Uhud when) the two armies met, was by the leave of Allah, in order that He might test the believers.', 'Whatever you suffered on the day when the two troops faced each other was by the will of Allah, and in order to know the believers,'),
(460, 3, 167, 17, 8, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ لِیَعۡلَمَ الَّذِیۡنَ نَافَقُوۡا ۚۖ وَ قِیۡلَ لَہُمۡ تَعَالَوۡا قَاتِلُوۡا فِیۡ سَبِیۡلِ اللّٰہِ اَوِ ادۡفَعُوۡا ؕ قَالُوۡا لَوۡ نَعۡلَمُ قِتَالًا لَّا تَّبَعۡنٰکُمۡ ؕ ہُمۡ  لِلۡکُفۡرِ یَوۡمَئِذٍ اَقۡرَبُ مِنۡہُمۡ لِلۡاِیۡمَانِ ۚ یَقُوۡلُوۡنَ بِاَفۡوَاہِہِمۡ مَّا لَیۡسَ فِیۡ قُلُوۡبِہِمۡ ؕ وَ اللّٰہُ اَعۡلَمُ  بِمَا یَکۡتُمُوۡنَ ﴿۱۶۷﴾ۚ', 'اور منافقوں کو بھی معلوم کر لے اور جب ان سے کہا گیا کہ آؤ اللہ کے رستے میں جنگ کرو یا کافروں کے حملوں کو روکو۔ تو کہنے لگے کہ اگر ہم کو لڑائی کی خبر ہوتی تو ہم ضرور تمہارے ساتھ رہتے۔ یہ اس دن ایمان کی نسبت کفر سے زیادہ قریب تھے۔ منہ سے وہ باتیں کہتے ہیں جو ان کے دل میں نہیں ہیں۔ اور جو کچھ یہ چھپاتے ہیں اللہ اس سے خوب واقف ہے۔', 'اور تاکہ معلوم کرے ان کو جو منافق تھے [۲۵۶] اور کہا گیا ان کو کہ آؤ لڑو اللہ کی راہ میں یا دفع کرو دشمن کو [۲۵۷] بولے اگر ہم کو معلوم ہو لڑائی تو البتہ تمہارےساتھ رہیں [۲۵۸] وہ لوگ اس دن کفر کے قریب ہیں بہ نسبت ایمان کے [۲۵۹] کہتےہیں اپنے منہ سے جو نہیں ان کے دل میں اور اللہ خوب جانتا ہے جو کچھ چھپاتے ہیں [۲۶۰]', 'And that He might test the hypocrites, it was said to them: \"Come, fight in the Way of Allah or (at least) defend yourselves.\" They said: \"Had we known that fighting will take place, we would certainly have followed you.\" They were that day, nearer to disbelief than to Faith, saying with their mouths what was not in their hearts. And Allah has full knowledge of what they conceal.', 'and in order to know those who are hypocrites. It was said to them, “Come on, fight in the way of Allah, or defend.” They said, “Had we known it to be a fight we would have certainly followed you.” That day, they were nearer to disbelief than they were to Belief. They utter from their mouths what is not in their hearts. Allah knows well what they conceal.'),
(461, 3, 168, 17, 8, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اَلَّذِیۡنَ قَالُوۡا لِاِخۡوَانِہِمۡ وَ قَعَدُوۡا لَوۡ اَطَاعُوۡنَا مَا قُتِلُوۡا ؕ قُلۡ فَادۡرَءُوۡا عَنۡ اَنۡفُسِکُمُ الۡمَوۡتَ اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ  ﴿۱۶۸﴾', 'یہ خود تو جنگ سے بچکر بیٹھ ہی رہے تھے مگر جنہوں نےاللہ کی راہ میں جانیں قربان کر دیں اپنے ان بھائیوں کے بارے میں بھی کہتے ہیں کہ اگر ہمارا کہا مانتے تو قتل نہ ہوتے کہدو کہ اگر سچے ہو تو اپنے اوپر سے موت کو ٹال دینا۔', 'وہ لوگ ہیں جو کہتے ہیں اپنے بھائیوں کو اور آپ بیٹھ رہے ہیں اگر وہ ہماری بات مانتے تو مارے نہ جاتے [۲۶۱] تو کہہ دے اب ہٹا دیجو اپنے اوپر سے موت کو اگر تم سچے ہو [۲۶۲]', '(They are) the ones who said about their killed brethren while they themselves sat (at home): \"If only they had listened to us, they would not have been killed.\" Say: \"Avert death from your ownselves, if you speak the truth.\"', 'Those who said about their brethren, while themselves sitting, “Had they obeyed us, they would have not been killed.” Say, “Then avert death from yourselves if you are true.”'),
(462, 3, 169, 17, 8, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ لَا تَحۡسَبَنَّ الَّذِیۡنَ قُتِلُوۡا فِیۡ سَبِیۡلِ اللّٰہِ اَمۡوَاتًا ؕ بَلۡ اَحۡیَآءٌ عِنۡدَ رَبِّہِمۡ یُرۡزَقُوۡنَ ﴿۱۶۹﴾ۙ', 'جو لوگ اللہ کی راہ میں مارے گئے ان کو مرے ہوئے نہ سمجھنا وہ مرے ہوئے نہیں ہیں بلکہ اللہ کے نزدیک زندہ ہیں اور ان کو رزق مل رہا ہے۔', 'اور تو نہ سمجھ ان لوگوں کو جو مارے گئے اللہ کی راہ میں مردے بلکہ وہ زندہ ہیں اپنے رب کے پاس کھاتے پیتے', 'Think not of those who are killed in the Way of Allah as dead. Nay, they are alive, with their Lord, and they have provision.', 'Never take those killed in the way of Allah as dead. Rather, they are alive with their Lord, well-provided,'),
(463, 3, 170, 17, 8, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'فَرِحِیۡنَ بِمَاۤ  اٰتٰہُمُ اللّٰہُ مِنۡ فَضۡلِہٖ ۙ وَ یَسۡتَبۡشِرُوۡنَ بِالَّذِیۡنَ لَمۡ یَلۡحَقُوۡا بِہِمۡ مِّنۡ خَلۡفِہِمۡ ۙ اَلَّا خَوۡفٌ عَلَیۡہِمۡ وَ لَا ہُمۡ یَحۡزَنُوۡنَ ﴿۱۷۰﴾ۘ', 'جو کچھ اللہ نے ان کو اپنے فضل سے بخش رکھا ہے اس میں خوش ہیں اور جو لوگ ان کے پیچھے رہ گئے اور شہید ہو کر ان میں شامل نہیں ہو سکے ان کی نسبت خوشیاں منا رہے ہیں کہ قیامت کے دن ان کو بھی نہ کچھ خوف ہو گا اور نہ وہ غمناک ہوں گے۔', 'خوشی کرتے ہیں اس پر جو دیا ان کو اللہ نے اپنے فضل سے اور خوش وقت ہوتے ہیں انکی طرف سے جو ابھی تک نہیں پہنچے ان کے پاس ان کے پیچھے سے اس واسطے کہ نہ ڈر ہے ان پر اور نہ انکو غم', 'They rejoice in what Allah has bestowed upon them of His Bounty, rejoicing for the sake of those who have not yet joined them, but are left behind (not yet martyred) that on them no fear shall come, nor shall they grieve.', 'happy with what Allah has given them of His grace; and they feel pleased with the good news, about those left behind them who could not join them, that there shall be no fear for them nor shall they grieve.'),
(464, 3, 171, 17, 8, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'یَسۡتَبۡشِرُوۡنَ بِنِعۡمَۃٍ مِّنَ اللّٰہِ وَ فَضۡلٍ ۙ وَّ اَنَّ اللّٰہَ لَا یُضِیۡعُ اَجۡرَ الۡمُؤۡمِنِیۡنَ   ﴿۱۷۱﴾ۚ٪ۛ', 'اور اللہ کے انعامات اور فضل سے خوش ہو رہے ہیں اور اس سے کہ اللہ مومنوں کا اجر ضائع نہیں کرتا۔', 'خوش وقت ہوتے ہیں اللہ کی نعمت اور فضل سے اور اس بات سے کہ اللہ ضائع نہیں کرتا مزدوری ایمان والوں کی [۲۶۳]', 'They rejoice in a Grace and a Bounty from Allah, and that Allah will not waste the reward of the believers.', 'They feel pleased with blessing from Allah, and grace, and with the fact that Allah would not let the reward of the believers be lost.'),
(465, 3, 172, 18, 9, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اَلَّذِیۡنَ اسۡتَجَابُوۡا لِلّٰہِ وَ الرَّسُوۡلِ مِنۡۢ بَعۡدِ مَاۤ  اَصَابَہُمُ الۡقَرۡحُ ؕۛ لِلَّذِیۡنَ اَحۡسَنُوۡا مِنۡہُمۡ وَ اتَّقَوۡا اَجۡرٌ  عَظِیۡمٌ  ﴿۱۷۲﴾ۚ', 'جنہوں نے باوجود زخم کھانے کے اللہ اور رسول کے حکم کو قبول کیا۔ جو لوگ ان میں نیکوکار اور پرہیزگار ہیں ان کے لئے بڑا ثواب ہے۔', 'جن لوگوں نے حکم مانا اللہ کا اور رسول کا بعد اس کے کہ پہنچ چکے تھے ان کو زخم جو ان میں نیک ہیں اور پرہیزگار ان کو ثواب بڑا ہے', 'Those who answered (the Call of) Allah and the Messenger (Muhammad SAW) after being wounded; for those of them who did good deeds and feared Allah, there is a great reward.', 'Those who responded to the call of Allah and the Messenger, even after they had received the wound, for those of them who did good deeds and feared Allah there is a great reward'),
(466, 3, 173, 18, 9, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اَلَّذِیۡنَ  قَالَ لَہُمُ النَّاسُ  اِنَّ النَّاسَ قَدۡ جَمَعُوۡا لَکُمۡ فَاخۡشَوۡہُمۡ فَزَادَہُمۡ اِیۡمَانًا ٭ۖ وَّ قَالُوۡا حَسۡبُنَا اللّٰہُ وَ نِعۡمَ الۡوَکِیۡلُ ﴿۱۷۳﴾', 'جب ان سے لوگوں نے آ کر بیان کیا کہ کفار نے تمہارے مقابلے کے لئے لشکر کثیر جمع کیا ہے تو ان سے ڈرو۔ تو ان کا ایمان اور زیادہ ہو گیا۔ اور کہنے لگے ہم کو اللہ کافی ہے اور وہ بہت اچھا کارساز ہے۔', 'جن کو کہا لوگوں نے کہ مکہ والے آدمیوں نے جمع کیا ہے سامان تمہارے مقابلہ کو سو تم ان سے ڈرو تو اور زیادہ ہوا ان کا ایمان اور بولے کافی ہے ہم کو اللہ اور کیا خوب کارساز ہے [۲۶۴]', 'Those (i.e. believers) unto whom the people (hypocrites) said, \"Verily, the people (pagans) have gathered against you (a great army), therefore, fear them.\" But it (only) increased them in Faith, and they said: \"Allah (Alone) is Sufficient for us, and He is the Best Disposer of affairs (for us).\"', '- (that is) those to whom people said, “The people have gathered against you; so, fear them.” It increased them in Faith and they said, “Allah is fully sufficient for us, and the best One in whom to trust.”'),
(467, 3, 174, 18, 9, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'فَانۡقَلَبُوۡا بِنِعۡمَۃٍ مِّنَ اللّٰہِ وَ فَضۡلٍ لَّمۡ یَمۡسَسۡہُمۡ سُوۡٓءٌ ۙ وَّ اتَّبَعُوۡا رِضۡوَانَ اللّٰہِ ؕ وَ اللّٰہُ ذُوۡ فَضۡلٍ  عَظِیۡمٍ ﴿۱۷۴﴾', 'پھر وہ اللہ کی نعمتوں اور اس کے فضل کے ساتھ خوش و خرم واپس آئے ان کو کسی طرح کا ضرر نہ پہنچا اور وہ اللہ کی خوشنودی کے تابع رہے اور اللہ بڑے فضل کا مالک ہے۔', 'پھر چلے آئے مسلمان اللہ کے احسان اور فضل کے ساتھ کچھ نہ پہنچی ان کو برائی اور تابع ہوئے اللہ کی مرضی کے اور اللہ کا فضل بڑا ہے [۲۶۵]', 'So they returned with Grace and Bounty from Allah. No harm touched them; and they followed the good Pleasure of Allah. And Allah is the Owner of Great Bounty.', 'So, they returned with bounty from Allah, and grace, with no evil having even touched them, and submitted to the pleasure of Allah. Allah is the Lord of great bounty.'),
(468, 3, 175, 18, 9, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اِنَّمَا ذٰلِکُمُ الشَّیۡطٰنُ یُخَوِّفُ اَوۡلِیَآءَہٗ ۪ فَلَا تَخَافُوۡہُمۡ وَ خَافُوۡنِ  اِنۡ کُنۡتُمۡ  مُّؤۡمِنِیۡنَ  ﴿۱۷۵﴾', 'یہ خوف دلانے والا تو شیطان ہے جو اپنے دوستوں سے ڈراتا ہے۔ تو اگر تم مومن ہو تو ان سے مت ڈرنا اور مجھی سے ڈرتے رہنا۔', 'یہ جو ہے سو شیطان ہے کہ ڈراتا ہے اپنے دوستوں سے سو تم ان سے مت ڈرو اور مجھ سے ڈرو اگر ایمان رکھتے ہو [۲۶۶]', 'It is only Shaitan (Satan) that suggests to you the fear of his Auliya (supporters and friends (polytheists, disbelievers in the Oneness of Allah and in His Messenger, Muhammad SAW)), so fear them not, but fear Me, if you are (true) believers.', 'It is none but Satan who frightens (you) of his friends. So, do not fear them; but fear Me, if you are believers.'),
(469, 3, 176, 18, 9, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ لَا یَحۡزُنۡکَ الَّذِیۡنَ یُسَارِعُوۡنَ فِی الۡکُفۡرِ ۚ اِنَّہُمۡ لَنۡ یَّضُرُّوا اللّٰہَ شَیۡئًا ؕ یُرِیۡدُ اللّٰہُ اَلَّا یَجۡعَلَ لَہُمۡ حَظًّا فِی الۡاٰخِرَۃِ ۚ وَ لَہُمۡ عَذَابٌ عَظِیۡمٌ ﴿۱۷۶﴾', 'اور جو لوگ کفر میں جلدی کرتے ہیں ان کی وجہ سے غمگین نہ ہونا۔ یہ اللہ کا کچھ نقصان نہیں کر سکتے اللہ چاہتا ہے کہ آخرت میں ان کو کچھ حصہ نہ دے اور ان کے لئے بڑا عذاب تیار ہے۔', 'اور غم میں نہ ڈالیں تجھ کو وہ لوگ جو دوڑتے ہیں کفر کی طرف وہ نہ بگاڑیں گے اللہ کا کچھ اللہ چاہتا ہے کہ ان کو فائدہ نہ دے آخرت میں اور ان کے لئے عذاب ہے بڑا [۲۶۷]', 'And let not those grieve you (O Muhammad SAW) who rush with haste to disbelieve; verily, not the least harm will they do to Allah. It is Allahs Will to give them no portion in the Hereafter. For them there is a great torment.', 'Those who hasten towards disbelief should not make you grieve. They cannot harm Allah at all. Allah intends not to spare for them any share in the Hereafter. For them there is a mighty punishment.'),
(470, 3, 177, 18, 9, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اِنَّ الَّذِیۡنَ اشۡتَرَوُا الۡکُفۡرَ بِالۡاِیۡمَانِ لَنۡ یَّضُرُّوا اللّٰہَ شَیۡئًا ۚ وَ لَہُمۡ عَذَابٌ اَلِیۡمٌ ﴿۱۷۷﴾', 'جن لوگوں نے ایمان کے بدلے کفر خریدا وہ اللہ کا کچھ نہیں بگاڑ سکتے اور ان کو دکھ دینے والا عذاب ہو گا۔', 'جنہوں نے مول لیا کفر کو ایمان کے بدلے وہ نہ بگاڑیں گے اللہ کا کچھ اور انکے لئے عذاب ہے دردناک [۲۶۸]', 'Verily, those who purchase disbelief at the price of Faith, not the least harm will they do to Allah. For them, there is a painful torment.', 'Certainly, those who bought disbelief in exchange for Belief cannot harm Allah at all. For them there is a painful punishment.'),
(471, 3, 178, 18, 9, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ لَا یَحۡسَبَنَّ الَّذِیۡنَ کَفَرُوۡۤا اَنَّمَا نُمۡلِیۡ لَہُمۡ خَیۡرٌ لِّاَنۡفُسِہِمۡ ؕ اِنَّمَا نُمۡلِیۡ لَہُمۡ لِیَزۡدَادُوۡۤا اِثۡمًا ۚ وَ لَہُمۡ عَذَابٌ مُّہِیۡنٌ ﴿۱۷۸﴾', 'اور کافر لوگ یہ نہ خیال کریں کہ ہم جو ان کو مہلت دئیے جاتے ہیں تو یہ ان کے حق میں اچھا ہے نہیں بلکہ ہم انکو اس لئے مہلت دیتے ہیں کہ اور گناہ کر لیں آخر کار ان کو ذلیل کرنے والا عذاب ہو گا۔', 'اور یہ نہ سمجھیں کافر کہ ہم جو مہلت دیتے ہیں ان کو کچھ بھلا ہے ان کے حق میں ہم تو مہلت دیتے ہیں ان کو تاکہ ترقی کریں وہ گناہ میں اور ان کے لئے عذاب ہے خوار کرنے والا [۲۶۹]', 'And let not the disbelievers think that Our postponing of their punishment is good for them. We postpone the punishment only so that they may increase in sinfulness. And for them is a disgracing torment.', 'Those who disbelieve should not think that the respite We give them is good for them. In fact, We give them respite only that they may increase in sin, and for them there is a humiliating punishment.'),
(472, 3, 179, 18, 9, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'مَا  کَانَ اللّٰہُ لِیَذَرَ الۡمُؤۡمِنِیۡنَ عَلٰی مَاۤ  اَنۡتُمۡ عَلَیۡہِ حَتّٰی یَمِیۡزَ  الۡخَبِیۡثَ مِنَ الطَّیِّبِ ؕ وَ مَا کَانَ اللّٰہُ لِیُطۡلِعَکُمۡ عَلَی الۡغَیۡبِ وَ لٰکِنَّ اللّٰہَ یَجۡتَبِیۡ مِنۡ رُّسُلِہٖ مَنۡ یَّشَآءُ ۪ فَاٰمِنُوۡا بِاللّٰہِ وَ رُسُلِہٖ ۚ وَ  اِنۡ تُؤۡمِنُوۡا وَ تَتَّقُوۡا فَلَکُمۡ  اَجۡرٌ  عَظِیۡمٌ ﴿۱۷۹﴾', 'لوگو جب تک اللہ ناپاک کو پاک سے الگ نہ کر دے گا مومنوں کو اس حال میں جس میں تم ہو ہرگز نہیں رہنے دے گا۔ اور اللہ تم کو غیب کی باتوں سے بھی مطلع نہیں کرے گا۔ البتہ اللہ اپنے پیغمبروں میں سے جسے چاہتا ہے منتخب کر لیتا ہے سو تم اللہ پر اور اس کے رسولوں پر ایمان رکھو۔ اور اگر ایمان  پر قائم رہو گے اور پرہیزگاری کرو گے تو تم کو اجر عظیم ملے گا۔', 'اللہ وہ نہیں کہ چھوڑ دےمسلمانوں کو اس حالت پر جس پر تم ہو جب تک کہ جدا نہ کر دے ناپاک کو پاک سے اور اللہ نہیں ہے کہ تم کو خبر دے غیب کی لیکن اللہ چھانٹ لیتا ہے اپنے رسولوں میں جس کو چاہے [۲۷۰] سو تم یقین لاؤ اللہ پر اور اسکے رسولوں پر اور اگر تم یقین پر رہو اور پرہیزگاری پر تو تم کو بڑا ثواب ہے [۲۷۱]', 'Allah will not leave the believers in the state in which you are now, until He distinguishes the wicked from the good. Nor will Allah disclose to you the secrets of the Ghaib (unseen), but Allah chooses of His Messengers whom He pleases. So believe in Allah and His Messengers. And if you believe and fear Allah, then for you there is a great reward.', 'Allah is not to leave the believers in the state you are in, unless He separates the impure from the pure. Allah is not to inform you of the Unseen. But Allah selects from His messengers whom He wills. So, believe in Allah and His messengers. If you believe, and fear Allah, you will deserve a great reward.'),
(473, 3, 180, 18, 9, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ لَا یَحۡسَبَنَّ الَّذِیۡنَ یَبۡخَلُوۡنَ بِمَاۤ اٰتٰہُمُ اللّٰہُ مِنۡ فَضۡلِہٖ ہُوَ خَیۡرًا لَّہُمۡ ؕ بَلۡ ہُوَ شَرٌّ  لَّہُمۡ ؕ سَیُطَوَّقُوۡنَ مَا بَخِلُوۡا بِہٖ یَوۡمَ الۡقِیٰمَۃِ ؕ وَ لِلّٰہِ مِیۡرَاثُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ اللّٰہُ بِمَا تَعۡمَلُوۡنَ خَبِیۡرٌ ﴿۱۸۰﴾٪', 'جو لوگ مال میں جو اللہ نے اپنے فضل سے ان کو عطا فرمایا ہے بخل کرتے ہیں وہ اس بخل کو اپنے حق میں اچھا نہ سمجھیں وہ اچھا نہیں بلکہ ان کے لئے برا ہے وہ جس مال میں بخل کرتے ہیں قیامت کے دن اس کا طوق بنا کر ان کی گردنوں میں ڈالا جائے گا اور آسمانوں اور زمین کا وارث اللہ ہی ہے اور جو عمل تم کرتے ہو اللہ کو معلوم ہے۔', 'اور نہ خیال کریں وہ لوگ جو بخل کرتے ہیں اس چیز پر جو اللہ نے انکو دی ہے اپنے فضل سے کہ یہ بخل بہتر ہے انکے حق میں بلکہ یہ بہت برا ہے انکے حق میں طوق بنا کر ڈالا جائے گا انکے گلوں میں وہ مال جس میں بخل کیا تھا قیامت کے دن [۲۷۲] اور اللہ وارث ہے آسمان اور زمین کا [۲۷۳] اور اللہ جو کرتے ہو سو جانتا ہے [۲۷۴]', 'And let not those who covetously withhold of that which Allah has bestowed on them of His Bounty (Wealth) think that it is good for them (and so they do not pay the obligatory Zakat). Nay, it will be worse for them; the things which they covetously withheld shall be tied to their necks like a collar on the Day of Resurrection. And to Allah belongs the heritage of the heavens and the earth; and Allah is WellAcquainted with all that you do.', 'Those who withhold in miserliness what Allah has given them out of His grace should not take it as good for them. Instead, it is bad for them. They shall be forced, on the Doomsday, to put on what they withheld, as iron-collars round their necks. To Allah belongs the inheritance of the heavens and the earth. Allah is All-Aware of what you do.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(474, 3, 181, 19, 10, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'لَقَدۡ سَمِعَ اللّٰہُ قَوۡلَ الَّذِیۡنَ قَالُوۡۤا اِنَّ اللّٰہَ فَقِیۡرٌ وَّ نَحۡنُ اَغۡنِیَآءُ ۘ سَنَکۡتُبُ مَا قَالُوۡا وَ قَتۡلَہُمُ الۡاَنۡۢبِیَآءَ بِغَیۡرِ حَقٍّ ۙ وَّ نَقُوۡلُ ذُوۡقُوۡا عَذَابَ الۡحَرِیۡقِ ﴿۱۸۱﴾', 'اللہ نے ان لوگوں کا قول سن لیا ہے جو کہتے ہیں کہ اللہ فقیر ہے اور ہم مالدار ہیں۔ یہ جو کچھ کہتے ہیں ہم اس کو لکھ لیں گے اور پیغمبروں کو جو یہ ناحق قتل کرتے رہے ہیں اس کو بھی قلمبند کر رکھیں گے اور قیامت کے روز کہیں گے کہ سخت جلن والی آگ کے عذاب کے مزے چکھتے رہو۔', 'بیشک اللہ نے سنی ان کی بات جنہوں نے کہا کہ اللہ فقیر ہے اور ہم مالدار [۲۷۵] اب لکھ رکھیں گے ہم انکی بات اور جو خون کئے ہیں انہوں نے انبیاء کے ناحق اور کہیں گے چکھو عذاب جلتی آگ کا [۲۷۶]', 'Indeed, Allah has heard the statement of those (Jews) who say: \"Truly, Allah is poor and we are rich!\" We shall record what they have said and their killing of the Prophets unjustly, and We shall say: \"Taste you the torment of the burning (Fire).\"', 'Allah has surely heard the words of those who said, “Allah is poor, and we are rich.”We shall write down what they said, and their killing of the prophets unjustly; and We shall say, “Taste the punishment of the flaming fire.'),
(475, 3, 182, 19, 10, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'ذٰلِکَ بِمَا قَدَّمَتۡ اَیۡدِیۡکُمۡ وَ اَنَّ اللّٰہَ لَیۡسَ بِظَلَّامٍ  لِّلۡعَبِیۡدِ  ﴿۱۸۲﴾ۚ', 'یہ ان کاموں کی سزا ہے جو تمہاے ہاتھ آگے بھیجتے رہے ہیں اور اللہ تو بندوں پر مطلق ظلم نہیں کرتا۔', 'یہ بدلہ اس کا ہے جو تم نے اپنے ہاتھوں آگے بھیجا اور اللہ ظلم نہیں کرتا بندوں پر [۲۷۷]', 'This is because of that (evil) which your hands have sent before you. And certainly, Allah is never unjust to (His) slaves.', 'This is due to what your hands sent ahead and that Allah is not cruel to His servants.”'),
(476, 3, 183, 19, 10, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اَلَّذِیۡنَ قَالُوۡۤا اِنَّ اللّٰہَ عَہِدَ اِلَیۡنَاۤ اَلَّا نُؤۡمِنَ لِرَسُوۡلٍ حَتّٰی یَاۡتِیَنَا بِقُرۡبَانٍ تَاۡکُلُہُ النَّارُ ؕ قُلۡ قَدۡ جَآءَکُمۡ رُسُلٌ مِّنۡ قَبۡلِیۡ بِالۡبَیِّنٰتِ وَ بِالَّذِیۡ قُلۡتُمۡ فَلِمَ قَتَلۡتُمُوۡہُمۡ  اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ ﴿۱۸۳﴾', 'جو لوگ کہتے ہیں کہ اللہ نے ہمیں حکم بھیجا کہ جب تک کوئی پیغمبر ہمارے پاس ایسی نیاز لے کر نہ آئے جس کو آگ آ کر کھا جائے تب تک ہم اس پر ایمان نہ لائیں گے اے پیغمبر ان سے کہدو کہ مجھ سے پہلے کئ پیغمبر تمہارے پاس کھلی ہو ئی نشانیاں لے کر آئے اور وہ معجزہ بھی لائے جو تم کہتے ہو تو اگر سچے ہو تو تم نے ان کو کیوں قتل کیا؟', 'وہ لوگ جو کہتے ہیں کہ اللہ نے ہم کو کہہ رکھا ہے کہ یقین نہ کریں کسی رسول کا جب تک نہ لاوے ہمارے پاس قربانی کہ کھا جائے اس کو آگ [۲۷۸] تو کہہ تم میں آ چکے کتنے رسول مجھ سے پہلے نشانیاں لے کر اور یہ بھی جو تم نے کہا پھر ان کو کیوں قتل کیا تم نے اگر تم سچے ہو [۲۷۹]', 'Those (Jews) who said: \"Verily, Allah has taken our promise not to believe in any Messenger unless he brings to us an offering which the fire (from heaven) shall devour.\" Say: \"Verily, there came to you Messengers before me, with clear signs and even with what you speak of; why then did you kill them, if you are truthful?\"', '(There are) those who have said, “Allah has directed us that we should not believe in a messenger unless he comes to us with an offering to be eaten up by the fire.”Say, “A number of messengers have come to you, before me, with clear signs and with what you have said. So, why did you kill them, if you are true?'),
(477, 3, 184, 19, 10, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'فَاِنۡ کَذَّبُوۡکَ فَقَدۡ کُذِّبَ رُسُلٌ مِّنۡ قَبۡلِکَ جَآءُوۡ بِالۡبَیِّنٰتِ وَ الزُّبُرِ وَ الۡکِتٰبِ  الۡمُنِیۡرِ ﴿۱۸۴﴾', 'پھر اگر یہ لوگ تم کو جھٹلا رہے ہیں تو تم سے پہلے بہت سے پیغمبر کھلی ہوئی نشانیاں اور صحیفے اور روشن کتابیں لے کر آ چکے ہیں کہ انکو بھی جھٹلایا گیا تھا۔', 'پھر اگر یہ تجھ کو جھٹلاویں تو پہلے تجھ سے جھٹلائے گئے بہت  رسول جو لائے نشانیاں اور صحیفے اور کتاب روشن [۲۸۰]', 'Then if they reject you (O Muhammad SAW), so were Messengers rejected before you, who came with Al-Baiyinat (clear signs, proofs, evidences) and the Scripture and the Book of Enlightenment.', 'Then if they reject you, then messengers have been rejected before you. They came with clear signs and the Scriptures and the enlightening Book.'),
(478, 3, 185, 19, 10, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'کُلُّ نَفۡسٍ ذَآئِقَۃُ الۡمَوۡتِ ؕ وَ اِنَّمَا تُوَفَّوۡنَ اُجُوۡرَکُمۡ یَوۡمَ الۡقِیٰمَۃِ ؕ فَمَنۡ زُحۡزِحَ عَنِ النَّارِ وَ اُدۡخِلَ الۡجَنَّۃَ فَقَدۡ فَازَ ؕ وَ مَا الۡحَیٰوۃُ الدُّنۡیَاۤ اِلَّا مَتَاعُ  الۡغُرُوۡرِ ﴿۱۸۵﴾', 'ہر متنفس کو موت کا مزا چکھنا ہے۔ اور تم کو قیامت کے دن تمہارے اعمال کا پورا پورا بدلہ دیا جائے گا تو جو شخص دوزخ سے دور رکھا گیا اور بہشت میں داخل کیا گیا وہ مراد کو پہنچ گیا۔ اور دنیا کی زندگی تو دھوکے کا سامان ہے۔', 'ہر جی کو چکھنی ہے موت اور تم کو پورے بدلے ملیں گے قیامت کے دن [۲۸۱] پھر جو کوئی دور کیا گیا دوزخ سے اور داخل کیا گیا جنت میں اس کا کام تو بن گیا اور نہیں زندگانی دنیا کی مگر پونجی دھوکے کی [۲۸۲]', 'Everyone shall taste death. And only on the Day of Resurrection shall you be paid your wages in full. And whoever is removed away from the Fire and admitted to Paradise, he indeed is successful. The life of this world is only the enjoyment of deception (a deceiving thing).', 'Every soul has to taste death. It is on the Day of Judgement that you shall be paid your rewards in full. So, whoever has been kept away from the Fire and admitted to Paradise has really succeeded. The worldly life is nothing but an illusionary enjoyment.'),
(479, 3, 186, 19, 10, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'لَتُبۡلَوُنَّ فِیۡۤ اَمۡوَالِکُمۡ وَ اَنۡفُسِکُمۡ ۟ وَ لَتَسۡمَعُنَّ مِنَ الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ مِنۡ قَبۡلِکُمۡ وَ مِنَ الَّذِیۡنَ اَشۡرَکُوۡۤا اَذًی کَثِیۡرًا ؕ وَ اِنۡ تَصۡبِرُوۡا وَ تَتَّقُوۡا فَاِنَّ ذٰلِکَ مِنۡ عَزۡمِ الۡاُمُوۡرِ ﴿۱۸۶﴾', 'اے اہل ایمان تمہارے مال و جان میں تمہاری آزمائش ضرور کی جائے گی اور تم اہل کتاب سے اور ان لوگوں سے جو مشرک ہیں بہت سی ایذا کی باتیں سنو گے۔ تو اگر صبر اور پرہیز گاری کرتے رہو گے۔ تو یہ بڑی ہمت کے کام ہیں۔', 'البتہ تمہاری آزمائش ہو گی مالوں میں اور جانوں میں اور البتہ سنو گے تم اگلی کتاب والوں سے اور مشرکوں سے بدگوئی بہت اور اگر تم صبر کرو اور پرہیزگاری کرو تو یہ ہمت کے کام ہیں [۲۸۳]', 'You shall certainly be tried and tested in your wealth and properties and in your personal selves, and you shall certainly hear much that will grieve you from those who received the Scripture before you (Jews and Christians) and from those who ascribe partners to Allah, but if you persevere patiently, and become Al-Muttaqoon (the pious - see V.2:2) then verily, that will be a determining factor in all affairs, and that is from the great matters, (which you must hold on with all your efforts).', 'Of course, you shall be tested in your wealth and yourselves; and, of course, you shall hear hurting statements from those who have been given the Book before you, and from those who associate (others with Allah in His divinity). If you observe patience and fear Allah, then this (observance) is among the matters of firm resolution.'),
(480, 3, 187, 19, 10, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ اِذۡ اَخَذَ اللّٰہُ مِیۡثَاقَ الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ لَتُبَیِّنُنَّہٗ لِلنَّاسِ وَ لَا تَکۡتُمُوۡنَہٗ ۫ فَنَبَذُوۡہُ  وَرَآءَ ظُہُوۡرِہِمۡ وَ اشۡتَرَوۡا بِہٖ ثَمَنًا قَلِیۡلًا ؕ فَبِئۡسَ مَا یَشۡتَرُوۡنَ ﴿۱۸۷﴾', 'اور جب اللہ نے ان لوگوں سے جنکو کتاب عنایت کی گئ تھی اقرار لیا کہ اس میں جو کچھ لکھا ہے اسے لوگوں سے صاف صاف بیان کرتے رہنا اور اس کی کسی بات کو نہ چھپانا تو انہوں نے اس کو پس پشت پھینک دیا اور اسکے بدلے تھوڑی سی قیمت حاصل کی۔ یہ جو کچھ حاصل کرتے ہیں برا ہے۔', 'اور جب اللہ نے عہد لیا کتاب والوں سے کہ اس کو بیان کرو گے لوگوں سے اور نہ چھپاؤ گے پھر پھینک دیا انہوں نے وہ عہد اپنی پیٹھ کے پیچھے اور خرید کیا اس کے بدلے تھوڑا سا مول سو کیا برا ہے جو خریدتے ہیں [۲۸۴]', '(And remember) when Allah took a covenant from those who were given the Scripture (Jews and Christians) to make it (the news of the coming of Prophet Muhammad SAW and the religious knowledge) known and clear to mankind, and not to hide it, but they threw it away behind their backs, and purchased with it some miserable gain! And indeed worst is that which they bought.', 'When Allah took a pledge from those who were given the Book: “You shall make it known to people, and you shall not conceal it,” they threw it away behind their backs, and acquired a small price for it. So, evil is what they acquire.'),
(481, 3, 188, 19, 10, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'لَا تَحۡسَبَنَّ الَّذِیۡنَ یَفۡرَحُوۡنَ بِمَاۤ اَتَوۡا وَّ یُحِبُّوۡنَ اَنۡ یُّحۡمَدُوۡا بِمَا لَمۡ یَفۡعَلُوۡا فَلَا تَحۡسَبَنَّہُمۡ بِمَفَازَۃٍ مِّنَ الۡعَذَابِ ۚ وَ لَہُمۡ عَذَابٌ اَلِیۡمٌ ﴿۱۸۸﴾', 'جو لوگ اپنے کئے ہوئے کاموں سے خوش ہوتے ہیں اور وہ کام جو کرتے نہیں ان کیلئے چاہتے ہیں کہ ان کی تعریف کی جائے ان کی نسبت خیال نہ کرنا کہ وہ عذاب سے چھٹکارا پائیں گے۔ اور انہیں درد دینے والا عذاب ہو گا۔', 'تو نہ سمجھ کہ جو لوگ خوش ہوتے ہیں اپنے کئے پر اور تعریف چاہتے ہیں بن کئے پر سو مت سمجھ ان کو کہ چھوٹ گئے عذاب سے اور ان کے لئےعذاب ہے دردناک [۲۸۵]', 'Think not that those who rejoice in what they have done (or brought about), and love to be praised for what they have not done,- think not you that they are rescued from the torment, and for them is a painful torment.', 'Do not think of those who are delighted with what they did, and love to be praised for what they never did - do not think they are secure from the punishment. For them there is a painful punishment.'),
(482, 3, 189, 19, 10, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ لِلّٰہِ مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ اللّٰہُ عَلٰی کُلِّ شَیۡءٍ  قَدِیۡرٌ ﴿۱۸۹﴾٪', 'اور آسمانوں اور  زمین کی بادشاہی اللہ ہی کو ہے اور اللہ ہر چیز پر قادر ہے۔', 'اور اللہ ہی کے لئے ہے سلطنت آسمان اور زمین کی اور اللہ ہر چیز پر قادر ہے [۲۸۶]', 'And to Allah belongs the dominion of the heavens and the earth, and Allah has power over all things.', 'To Allah belongs the Kingdom of the heavens and the earth. Allah is powerful to do every thing.'),
(483, 3, 190, 20, 11, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'اِنَّ فِیۡ خَلۡقِ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ اخۡتِلَافِ الَّیۡلِ وَ النَّہَارِ لَاٰیٰتٍ  لِّاُولِی الۡاَلۡبَابِ ﴿۱۹۰﴾ۚۙ', 'بیشک آسمانوں اور زمین کی پیدائش اور رات اور دن کے بدل بدل کر آنے جانے میں عقل والوں کے لئے نشانیاں ہیں۔', 'بیشک آسمان اور زمین کا بنانا اور رات اور دن کا آنا جانا اس میں نشانیاں ہیں عقل والوں کو [۲۸۷]', 'Verily! In the creation of the heavens and the earth, and in the alternation of night and day, there are indeed signs for men of understanding.', 'Surely, in the creation of the heavens and the earth, and in the alternation of night and day, there are signs for the people of wisdom,'),
(484, 3, 191, 20, 11, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'الَّذِیۡنَ یَذۡکُرُوۡنَ اللّٰہَ  قِیٰمًا وَّ قُعُوۡدًا وَّ عَلٰی جُنُوۡبِہِمۡ وَ یَتَفَکَّرُوۡنَ فِیۡ خَلۡقِ السَّمٰوٰتِ وَ الۡاَرۡضِ ۚ رَبَّنَا مَا خَلَقۡتَ ہٰذَا بَاطِلًا ۚ سُبۡحٰنَکَ فَقِنَا عَذَابَ النَّارِ ﴿۱۹۱﴾', 'جو کھڑے اور بیٹھے اور لیٹے ہر حال میں اللہ کو یاد کرتے اور آسمان اور زمین کی پیدائش میں غور کرتے اور کہتے ہیں کہ اے پروردگار تو نے اس کائنات کو بے فائدہ نہیں پیدا کیا۔ تو پاک ہے۔ تو قیامت کے دن ہمیں دوزخ کے عذاب سے بچائیو۔', 'وہ جو یاد کرتے ہیں اللہ کو کھڑے اور بیٹھے اور کروٹ پر لیٹے [۲۸۸] اور فکر کرتے ہیں آسمان اور زمین کی پیدائش میں کہتے ہیں اے رب ہمارے تو نے یہ عبث نہیں بنایا تو پاک ہے سب عیبوں سے ہم کو بچا دوزخ کے عذاب سے [۲۸۹]', 'Those who remember Allah (always, and in prayers) standing, sitting, and lying down on their sides, and think deeply about the creation of the heavens and the earth, (saying): \"Our Lord! You have not created (all) this without purpose, glory to You! (Exalted be You above all that they associate with You as partners). Give us salvation from the torment of the Fire.', 'who remember Allah standing and sitting, and (lying) on their sides, and ponder on the creation of the heavens and the earth (and say) “Our Lord, You have not created all this in vain. We proclaim Your purity. So, save us from the punishment of Fire.'),
(485, 3, 192, 20, 11, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'رَبَّنَاۤ اِنَّکَ مَنۡ تُدۡخِلِ النَّارَ فَقَدۡ اَخۡزَیۡتَہٗ ؕ وَ مَا لِلظّٰلِمِیۡنَ مِنۡ اَنۡصَارٍ ﴿۱۹۲﴾', 'اے پروردگار جس کو تو نے دوزخ میں ڈالا۔ اسے رسوا کیا اور ظالموں کا کوئی مددگار نہیں ہو گا۔', 'اے رب ہمارے جس کو تو نے دوزخ میں ڈالا سو اس کو رسوا کر دیا [۲۹۰] اور نہیں کوئی گنہگاروں کا مددگار [۲۹۱]', '\"Our Lord! Verily, whom You admit to the Fire, indeed, You have disgraced him, and never will the Zalimoon (polytheists and wrong-doers) find any helpers.', 'Our Lord, whomsoever You admit into the Fire, he is disgraced by You indeed, and for the unjust there are no supporters.'),
(486, 3, 193, 20, 11, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'رَبَّنَاۤ اِنَّنَا سَمِعۡنَا مُنَادِیًا یُّنَادِیۡ لِلۡاِیۡمَانِ اَنۡ اٰمِنُوۡا بِرَبِّکُمۡ  فَاٰمَنَّا ٭ۖ رَبَّنَا فَاغۡفِرۡ لَنَا ذُنُوۡبَنَا وَ کَفِّرۡ عَنَّا سَیِّاٰتِنَا وَ تَوَفَّنَا مَعَ  الۡاَبۡرَارِ ﴿۱۹۳﴾ۚ', 'اے پروردگار ہم نے ایک پکار کرنے والے کو سنا کہ ایمان کے لئے پکار رہا تھا کہ اپنے پروردگار پر ایمان لاؤ تو ہم ایمان لے آئے سو اے پروردگار ہمارے گناہ معاف فرما۔ اور ہماری برائیوں کو ہم سے دور کر دے اور ہم کو دنیا سے نیک بندوں کے ساتھ اٹھائیو۔', 'اے رب ہمارے ہم نے سنا کہ ایک پکارنے والا پکارتا ہے ایمان لانے کو کہ ایمان لاؤ اپنے رب پر [۲۹۲] سو ہم ایمان لے آئے [۲۹۳] اے رب ہمارے اب بخش دے گناہ ہمارے اور دور کر دے ہم سے برائیاں ہماری اور موت دے ہم کو نیک لوگوں کے ساتھ [۲۹۴]', '\"Our Lord! Verily, we have heard the call of one (Muhammad SAW) calling to Faith: Believe in your Lord, and we have believed. Our Lord! Forgive us our sins and remit from us our evil deeds, and make us die in the state of righteousness along with Al-Abrar (those who are obedient to Allah and follow strictly His Orders).', 'Our Lord, We heard a herald calling towards Faith: ‘Believe in your Lord.’ So we believed.Our Lord, forgive us, then, our sins, and write off our evil deeds, and make us die only when we have joined the righteous.'),
(487, 3, 194, 20, 11, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'رَبَّنَا وَ اٰتِنَا مَا وَعَدۡتَّنَا عَلٰی رُسُلِکَ وَ لَا تُخۡزِنَا یَوۡمَ الۡقِیٰمَۃِ ؕ اِنَّکَ لَا تُخۡلِفُ الۡمِیۡعَادَ ﴿۱۹۴﴾', 'اے پرودگار تو نے جن جن چیزوں کے ہم سے اپنے پیغمبروں کے واسطے سے وعدے کئے ہیں وہ ہمیں عطا فرما اور قیامت کے دن ہمیں رسوا نہ کیجیو کچھ شک نہیں کہ تو خلاف وعدہ نہیں کرے گا۔', 'اے رب ہمارے اور دے ہم کو جو وعدہ کیا تو نے ہم سے اپنے رسولوں کے واسطہ سے اور رسوا نہ کر ہم کو قیامت کے دن [۲۹۵] بیشک تو وعدہ کے خلاف نہیں کرتا [۲۹۶]', '\"Our Lord! Grant us what You promised unto us through Your Messengers and disgrace us not on the Day of Resurrection, for You never break (Your) Promise.\"', 'Our Lord, give us what You have promised us through Your messengers, and do not put us to disgrace on the Day of Judgement. Surely you do not go back on Your promise.”'),
(488, 3, 195, 20, 11, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'فَاسۡتَجَابَ لَہُمۡ رَبُّہُمۡ اَنِّیۡ لَاۤ اُضِیۡعُ عَمَلَ عَامِلٍ مِّنۡکُمۡ مِّنۡ ذَکَرٍ اَوۡ اُنۡثٰی ۚ بَعۡضُکُمۡ مِّنۡۢ  بَعۡضٍ ۚ فَالَّذِیۡنَ ہَاجَرُوۡا وَ اُخۡرِجُوۡا مِنۡ دِیَارِہِمۡ وَ اُوۡذُوۡا فِیۡ سَبِیۡلِیۡ وَ قٰتَلُوۡا وَ قُتِلُوۡا لَاُکَفِّرَنَّ عَنۡہُمۡ سَیِّاٰتِہِمۡ وَ لَاُدۡخِلَنَّہُمۡ جَنّٰتٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ ۚ ثَوَابًا مِّنۡ عِنۡدِ اللّٰہِ ؕ وَ اللّٰہُ عِنۡدَہٗ حُسۡنُ الثَّوَابِ ﴿۱۹۵﴾', 'تو ان کے پروردگار نے ان کی دعا قبول کر لی اور فرمایا کہ میں کسی عمل کرنے والے کے عمل کو مرد ہو یا عورت ضائع نہیں کرتا۔ تم ایک دوسرے کے ہم جنس ہو۔ تو جو لوگ میرے لئے وطن چھوڑ گئے اور اپنے گھروں سے نکالے گئے اور ستائے گئے اور لڑے اور قتل کئے گئے میں ان کے گناہ دور کر دوں گا اور ان کو بہشتوں میں داخل کروں گا جن کے نیچے نہریں بہ رہی ہیں۔ یہ اللہ کے ہاں سے بدلہ ہے اور اللہ کے ہاں اچھا بدلہ ہے۔', 'پھر قبول کی ان کی دعا انکے رب نے کہ میں ضائع نہیں کرتا محنت کسی محنت کرنے والے کی تم میں سے مرد ہو یا عورت تم آپس میں ایک ہو [۲۹۷] پھر وہ لوگ کہ ہجرت کی انہوں نے اور نکالے گئے اپنے گھروں سے اور ستائے گئے میری راہ میں اور لڑے اور مارے گئے البتہ دور کروں  گا میں ان سے برائیاں ان کی اور داخل کروں گا ان کو باغوں میں جن کے نیچے بہتی ہیں نہریں [۲۹۸] یہ بدلہ ہے اللہ کےہاں سے اور اللہ کے ہاں ہے اچھا بدلہ [۲۹۹]', 'So their Lord accepted of them (their supplication and answered them), \"Never will I allow to be lost the work of any of you, be he male or female. You are (members) one of another, so those who emigrated and were driven out from their homes, and suffered harm in My Cause, and who fought, and were killed (in My Cause), verily, I will remit from them their evil deeds and admit them into Gardens under which rivers flow (in Paradise); a reward from Allah, and with Allah is the best of rewards.\"', 'So, their Lord answered their prayer: “I do not allow the labour of any worker from among you, male or female, to go to waste. You are similar to one another. So, those who emigrated, and were expelled from their homes, and were tortured in My way, and fought, and were killed, I shall certainly write off their evil deeds, and shall certainly admit them into gardens beneath which rivers flow, as a reward from Allah. It is Allah with Whom lies the beauty of the reward.'),
(489, 3, 196, 20, 11, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'لَا یَغُرَّنَّکَ تَقَلُّبُ الَّذِیۡنَ کَفَرُوۡا فِی الۡبِلَادِ  ﴿۱۹۶﴾ؕ', 'اے پیغمبر کافروں کا شہروں میں ٹھاٹ سے گھومنا تمہیں دھوکا نہ دے۔', 'تجھ کو دھوکا نہ دے چلنا پھرنا کافروں کا شہروں میں', 'Let not the free disposal (and affluence) of the disbelievers throughout the land deceive you.', 'The strutting of the disbelievers about the land should not deceive you.'),
(490, 3, 197, 20, 11, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'مَتَاعٌ قَلِیۡلٌ ۟ ثُمَّ مَاۡوٰىہُمۡ جَہَنَّمُ ؕ وَ بِئۡسَ الۡمِہَادُ ﴿۱۹۷﴾', 'یہ دنیا کا تھوڑا سا فائدہ ہے۔ پھر آخرت میں تو ان کا ٹھکانہ دوزخ ہے۔ اور وہ بری جگہ ہے۔', 'یہ فائدہ ہے تھوڑا سا پھر ان کا ٹھکانا دوزخ ہے اور وہ بہت برا ٹھکانا ہے [۳۰۰]', 'A brief enjoyment; then, their ultimate abode is Hell; and worst indeed is that place for rest.', 'It is just a little enjoyment. After that, their resort is Hell; and it is an evil abode.'),
(491, 3, 198, 20, 11, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'لٰکِنِ الَّذِیۡنَ اتَّقَوۡا رَبَّہُمۡ لَہُمۡ جَنّٰتٌ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَا نُزُلًا مِّنۡ عِنۡدِ اللّٰہِ ؕ وَ مَا عِنۡدَ اللّٰہِ خَیۡرٌ  لِّلۡاَبۡرَارِ ﴿۱۹۸﴾', 'لیکن جو لوگ اپنے پروردگار سے ڈرتے رہے ان کے لئے باغ ہیں جن کے نیچے نہریں بہ رہی ہیں اور وہ ان میں ہمیشہ رہیں گے یہ اللہ کے ہاں سے ان کی مہمانی ہے اور جو کچھ اللہ کے ہاں ہے وہ نیکوکاروں کے لئے بہت اچھا ہے۔', 'لیکن جو لوگ ڈرتے رہے اپنے رب سے انکے لئے باغ ہیں جن کے نیچے بہتی ہیں نہریں ہمیشہ رہیں گے ان میں [۳۰۱] مہمانی ہے اللہ کے ہاں سے [۳۰۲] اور جو اللہ کے ہاں ہے سو بہتر ہے نیک بختوں کے واسطے', 'But, for those who fear their Lord, are Gardens under which rivers flow (in Paradise); therein are they to dwell (for ever), an entertainment from Allah; and that which is with Allah is the Best for AlAbrar (those who are obedient to Allah and follow strictly His Orders).', 'But those who fear their Lord, for them there are Gardens beneath which rivers flow, where they will live forever - as hospitality from Allah. What is with Allah is best for the righteous.'),
(492, 3, 199, 20, 11, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'وَ اِنَّ مِنۡ اَہۡلِ  الۡکِتٰبِ لَمَنۡ یُّؤۡمِنُ بِاللّٰہِ وَ مَاۤ اُنۡزِلَ اِلَیۡکُمۡ وَ مَاۤ  اُنۡزِلَ اِلَیۡہِمۡ خٰشِعِیۡنَ  لِلّٰہِ ۙ لَا  یَشۡتَرُوۡنَ بِاٰیٰتِ اللّٰہِ ثَمَنًا قَلِیۡلًا ؕ اُولٰٓئِکَ لَہُمۡ اَجۡرُہُمۡ عِنۡدَ رَبِّہِمۡ ؕ اِنَّ اللّٰہَ سَرِیۡعُ الۡحِسَابِ ﴿۱۹۹﴾', 'اور بعض اہل کتاب ایسے بھی ہیں جو اللہ پر اور اس کتاب پر جو تم پر نازل ہوئی اور اس پر جو ان پر نازل ہوئی ایمان رکھتے ہیں اور اللہ کے آگے عاجزی کرتے ہیں اور اللہ کی آیتوں کے بدلے تھوڑی سی قیمت نہیں لیتے۔ یہی لوگ ہیں جنکا صلہ ان کے پروردگار کے ہاں تیار ہے اور اللہ جلد حساب لینے والا ہے۔', 'اور کتاب والوں میں بعضے وہ بھی ہیں جو ایمان لاتے ہیں اللہ پر اور جو اترا تمہاری طرف اور جو اترا انکی طرف عاجزی کرتےہیں اللہ کے آگے نہیں خریدتے اللہ کی آیتوں پر مول تھوڑا یہی ہیں جن کے لئے مزدوری ہے ان کے رب کے ہاں [۳۰۳] بیشک اللہ جلد لیتا ہے حساب [۳۰۴]', 'And there are, certainly, among the people of the Scripture (Jews and Christians), those who believe in Allah and in that which has been revealed to you, and in that which has been revealed to them, humbling themselves before Allah. They do not sell the Verses of Allah for a little price, for them is a reward with their Lord. Surely, Allah is Swift in account.', 'Surely, among the people of the Book there are those who believe in Allah, and in what has been sent down to you and what has been sent down to them, humbling themselves before Allah. They do not barter away the verses of Allah for paltry (worldly) gains. They have their reward with their Lord. Surely, Allah is swift at reckoning.'),
(493, 3, 200, 20, 11, 4, 'لَنۡ تَنَالُوا', 'آل عمران', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوا اصۡبِرُوۡا وَ صَابِرُوۡا وَ رَابِطُوۡا ۟ وَ اتَّقُوا اللّٰہَ لَعَلَّکُمۡ  تُفۡلِحُوۡنَ ﴿۲۰۰﴾٪', 'اے اہل ایمان کفار کے مقابلے میں ثابت قدم رہو اور استقامت رکھو اور مورچوں پر جمے رہو۔ اور اللہ سے ڈرو۔ تاکہ مراد حاصل کرو۔', 'اے ایمان والو صبر کرو اور مقابلہ میں مضبوط رہو اور لگے رہو اور ڈرتے رہو اللہ سے تاکہ تم اپنی مراد کو پہنچو [۳۰۵]', 'O you who believe! Endure and be more patient (than your enemy), and guard your territory by stationing army units permanently at the places from where the enemy can attack you, and fear Allah, so that you may be successful.', 'O you who believe, be patient, compete with each other in patience, and guard your frontiers and fear Allah, so that you may be successful.'),
(494, 4, 1, 1, 12, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'یٰۤاَیُّہَا النَّاسُ اتَّقُوۡا رَبَّکُمُ الَّذِیۡ خَلَقَکُمۡ مِّنۡ نَّفۡسٍ وَّاحِدَۃٍ وَّ خَلَقَ مِنۡہَا زَوۡجَہَا وَ بَثَّ مِنۡہُمَا رِجَالًا کَثِیۡرًا وَّ نِسَآءً ۚ وَ اتَّقُوا اللّٰہَ الَّذِیۡ تَسَآءَلُوۡنَ بِہٖ وَ الۡاَرۡحَامَ ؕ اِنَّ اللّٰہَ کَانَ عَلَیۡکُمۡ  رَقِیۡبًا ﴿۱﴾', 'لوگو اپنے پروردگار سے ڈرو جس نے تم کو ایک شخص سے پیدا کیا یعنی اوّل اس سے اس کا جوڑا بنایا پھر ان دونوں سے کثرت سے مرد و عورت پیدا کر کے روئے زمین پر پھیلا دئیے۔ اور اللہ سے ڈرو جس کے واسطے سے تم ایک دوسرے سے حقوق کا مطالبہ کرتے ہو اور قطع رحمی سے بچو کچھ شک نہیں کہ اللہ تمہیں دیکھ رہا ہے۔', 'اے لوگو ڈرتے رہو اپنے رب سے جس نے پیدا کیا تم کو ایک جان سے اور اسی سے پیدا کیا اس کا جوڑا اور  پھیلائے ان دونوں سے بہت مرد اور عورتیں [۱] اور ڈرتے رہو اللہ سے جس کے واسطے سے سوال کرتے ہو آپس میں اور خبردار رہو قرابت والوں سے [۲] بیشک اللہ تم پر نگہبان ہے [۳]', 'O mankind! Be dutiful to your Lord, Who created you from a single person (Adam), and from him (Adam) He created his wife (Hawwa (Eve)), and from them both He created many men and women and fear Allah through Whom you demand your mutual (rights), and (do not cut the relations of) the wombs (kinship). Surely, Allah is Ever an AllWatcher over you.', 'O men, fear your Lord who created you from a single soul, and from it created its match, and spread many men and women from the two. Fear Allah in whose name you ask each other (for your rights), and fear (the violation of the rights of) the womb-relations. Surely, Allah is watchful over you.'),
(495, 4, 2, 1, 12, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'وَ اٰتُوا الۡیَتٰمٰۤی اَمۡوَالَہُمۡ وَ لَا تَتَبَدَّلُوا الۡخَبِیۡثَ بِالطَّیِّبِ ۪ وَ لَا تَاۡکُلُوۡۤا اَمۡوَالَہُمۡ  اِلٰۤی اَمۡوَالِکُمۡ ؕ اِنَّہٗ کَانَ حُوۡبًا کَبِیۡرًا ﴿۲﴾', 'اور یتیموں کا مال جو تمہاری تحویل میں ہو ان کے حوالے کر دو اور ان کے پاکیزہ اور عمدہ مال کو اپنے ناقص اور برے مال سے نہ بدلو اور نہ ان کا مال اپنے مال میں ملا کر کھاؤ۔ کہ یہ بڑا سخت گناہ ہے۔', 'اور دے ڈالو یتیموں کو ان کا مال اور بدل نہ لو برے مال کو اچھے مال سے اور نہ کھاؤ ان کے مال اپنے مالوں کے ساتھ یہ ہے بڑا وبال [۴]', 'And give unto orphans their property and do not exchange (your) bad things for (their) good ones; and devour not their substance (by adding it) to your substance. Surely, this is a great sin.', 'Give the orphans their property, and do not substitute what is bad for what is good, and do not eat up their property along with your own. It is, surely, a great sin.'),
(496, 4, 3, 1, 12, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'وَ اِنۡ خِفۡتُمۡ اَلَّا تُقۡسِطُوۡا فِی الۡیَتٰمٰی فَانۡکِحُوۡا مَا طَابَ لَکُمۡ مِّنَ النِّسَآءِ مَثۡنٰی وَ ثُلٰثَ وَ رُبٰعَ ۚ فَاِنۡ خِفۡتُمۡ اَلَّا تَعۡدِلُوۡا فَوَاحِدَۃً اَوۡ مَا مَلَکَتۡ اَیۡمَانُکُمۡ ؕ ذٰلِکَ اَدۡنٰۤی اَلَّا تَعُوۡلُوۡا ؕ﴿۳﴾', 'اور اگر تم کو اس بات کو خوف ہو کہ یتیم لڑکیوں کے بارے میں انصاف نہ کر سکو گے تو ان کے سوا جو عورتیں تم کو پسند ہوں دو دو یا تین تین یا چار چار ان سے نکاح کر لو اور اگر اس بات کا اندیشہ ہو کہ کئ عورتوں سے انصاف نہ کر سکو گے تو ایک ہی عورت سے نکاح کرو یا باندی سے تعلق رکھو جس کے تم مالک ہو اس طرح تم بے انصافی سے بچ جاؤ گے۔', 'اور اگر ڈرو کہ انصاف نہ کر سکو گے یتیم لڑکیوں کے حق میں تو نکاح کر لو جو اور عورتیں تم کو خوش آویں دو دو تین تین چار چار [۵] پھر اگر ڈرو کہ ان میں انصاف نہ کر سکو گے تو ایک ہی نکاح کرو یا لونڈی جو اپنا مال ہے [۶] اس میں امید ہے کہ ایک طرف نہ جھک پڑو گے[۷]', 'And if you fear that you shall not be able to deal justly with the orphangirls, then marry (other) women of your choice, two or three, or four but if you fear that you shall not be able to deal justly (with them), then only one or (the captives and the slaves) that your right hands possess. That is nearer to prevent you from doing injustice.', 'If you fear that you will not do justice to the orphans, then, marry the women you like, in twos, in threes and in fours. But, if you fear that you will not maintain equity, then (keep to) one woman, or bondwomen you own. It will be closer to abstaining from injustice.'),
(497, 4, 4, 1, 12, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'وَ اٰتُوا النِّسَآءَ صَدُقٰتِہِنَّ نِحۡلَۃً ؕ فَاِنۡ طِبۡنَ لَکُمۡ عَنۡ شَیۡءٍ مِّنۡہُ نَفۡسًا فَکُلُوۡہُ ہَنِیۡٓــًٔا مَّرِیۡٓــًٔا ﴿۴﴾', 'اور عورتوں کو ان کے مہر خوشی سے دے دیا کرو ہاں اگر وہ اپنی خوشی سے اس میں سے کچھ تم کو چھوڑ دیں تو اسے مزے سے کھا لو۔', 'اور دے ڈالو عورتوں کو مہر ان کے خوشی سے [۸] پھر اگر وہ اس میں سے کچھ چھوڑ دیں تم کو اپنی خوشی سے تو اس کو کھاؤ رچتا پچتا [۹]', 'And give to the women (whom you marry) their Mahr (obligatory bridal money given by the husband to his wife at the time of marriage) with a good heart, but if they, of their own good pleasure, remit any part of it to you, take it, and enjoy it without fear of any harm (as Allah has made it lawful).', 'Give women their dower in good cheer. Then, if they forego some of it, of their own will, you may have it as pleasant and joyful.'),
(498, 4, 5, 1, 12, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'وَ لَا تُؤۡتُوا السُّفَہَآءَ اَمۡوَالَکُمُ الَّتِیۡ جَعَلَ اللّٰہُ لَکُمۡ قِیٰمًا وَّ ارۡزُقُوۡہُمۡ فِیۡہَا وَ اکۡسُوۡہُمۡ وَ قُوۡلُوۡا لَہُمۡ قَوۡلًا مَّعۡرُوۡفًا ﴿۵﴾', 'اور کم عقلوں کو ان کا مال جسے اللہ نے تم لوگوں کے لئے سبب معیشت بنایا ہے مت دو ہاں اس میں سے ان کو کھلاتے اور پہناتے رہو اور ان سے معقول بات کہتے رہو۔', 'اور مت پکڑا دو بے عقلوں کو اپنے وہ مال جن کو بنایا ہے اللہ نے تمہارےگذران کا سبب اور ان کو اس میں سے کھلاتے اور پہناتے رہو اور کہو ان سے بات معقول [۱۰]', 'And give not unto the foolish your property which Allah has made a means of support for you, but feed and clothe them therewith, and speak to them words of kindness and justice.', 'Do not give the feeble-minded your property that Allah has made a means of support for you, and do feed them from it, and clothe them, and speak to them in fair words.'),
(499, 4, 6, 1, 12, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'وَ ابۡتَلُوا الۡیَتٰمٰی حَتّٰۤی  اِذَا بَلَغُوا النِّکَاحَ ۚ فَاِنۡ اٰنَسۡتُمۡ مِّنۡہُمۡ رُشۡدًا فَادۡفَعُوۡۤا اِلَیۡہِمۡ اَمۡوَالَہُمۡ ۚ وَ لَا تَاۡکُلُوۡہَاۤ اِسۡرَافًا وَّ بِدَارًا اَنۡ یَّکۡبَرُوۡا ؕ وَ مَنۡ کَانَ غَنِیًّا فَلۡیَسۡتَعۡفِفۡ ۚ وَ مَنۡ کَانَ فَقِیۡرًا فَلۡیَاۡکُلۡ بِالۡمَعۡرُوۡفِ ؕ فَاِذَا دَفَعۡتُمۡ  اِلَیۡہِمۡ اَمۡوَالَہُمۡ فَاَشۡہِدُوۡا عَلَیۡہِمۡ ؕ وَ کَفٰی بِاللّٰہِ حَسِیۡبًا ﴿۶﴾', 'اور یتیموں کو بالغ ہونے تک کام کاج میں مصروف رکھو اور جانچتے رہو پھر بالغ ہونے پر اگر ان میں عقل کی پختگی دیکھو تو ان کا مال ان کے حوالے کر دو اور اس خوف سے کہ وہ بڑے ہو جائیں گے۔ یعنی بڑے ہو کر تم سے اپنا مال واپس لے لیں گے اس کو فضول خرچی اور جلدی میں نہ اڑا دینا۔ اور جو شخص آسودہ حال ہو اس کو ایسے مال سے قطعی طور پر پرہیز رکھنا چاہیے اور جو ضرورت مند ہو وہ مناسب طور پر یعنی بقدر خدمت کچھ لے لے۔ اور جب ان کا مال ان کے حوالے کرنے لگو تو گواہ کر لیا کرو اور حقیقت میں تو اللہ ہی گواہ اور حساب لینے والا کافی ہے۔', 'اور سدھاتے رہو یتیموں کو جب تک پہنچیں نکاح کی عمر کو پھر اگر دیکھو ان میں ہوشیاری تو حوالہ کر دو ان کے مال ان کو [۱۱] اور کھا نہ جاؤ یتیموں کا مال ضرورت سے زیادہ اور حاجت سے پہلے کہ یہ بڑے نہ ہو جائیں [۱۲] اور جس کو حاجت نہ ہو تو مال یتیم سے بچتا رہے اور جو کوڑی محتاج ہو تو کھاوے موافق دستور کے [۱۳] پھر جب ان کو حوالہ کرو ان کے مال تو گواہ کر لو اس پر اور اللہ کافی ہے حساب لینے کو [۱۴]', 'And try orphans (as regards their intelligence) until they reach the age of marriage; if then you find sound judgement in them, release their property to them, but consume it not wastefully, and hastily fearing that they should grow up, and whoever amongst guardians is rich, he should take no wages, but if he is poor, let him have for himself what is just and reasonable (according to his work). And when you release their property to them, take witness in their presence; and Allah is AllSufficient in taking account.', 'Test the orphans until they reach the marriageable age. Then, if you perceive in them proper understanding, hand their property over to them, and do not consume it extravagantly and hastily, lest they should grow up. Whoever is rich should abstain (from using it for himself), and whoever is poor may have from it (to the extent of his necessary need) with fairness. So, when you hand their property over to them, make witnesses upon them. Allah is sufficient for reckoning'),
(500, 4, 7, 1, 12, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'لِلرِّجَالِ نَصِیۡبٌ مِّمَّا تَرَکَ الۡوَالِدٰنِ وَ الۡاَقۡرَبُوۡنَ ۪ وَ لِلنِّسَآءِ نَصِیۡبٌ مِّمَّا تَرَکَ الۡوَالِدٰنِ وَ الۡاَقۡرَبُوۡنَ مِمَّا قَلَّ مِنۡہُ اَوۡ کَثُرَ ؕ نَصِیۡبًا مَّفۡرُوۡضًا ﴿۷﴾', 'جو مال ماں باپ اور رشتے دار چھوڑ مریں تھوڑا ہو یا بہت اس میں مردوں کا بھی حصہ ہے اور عورتوں کا بھی۔ یہ حصے اللہ کے مقرر کئے ہوئے ہیں۔', 'مردوں کا بھی حصہ ہے اس میں جو چھوڑ مریں ماں باپ او رقرابت والے اور عورتوں کا بھی حصہ ہے اس میں جو چھوڑ مریں ماں باپ اور قرابت والے تھوڑا ہو یا بہت ہو حصہ مقرر کیا ہوا ہے [۱۵]', 'There is a share for men and a share for women from what is left by parents and those nearest related, whether, the property be small or large - a legal share.', 'For men there is a share in what the parents and the nearest of kin have left. And for women there is a share in what the parents and the nearest of kin have left, be it small or large-a determined share.'),
(501, 4, 8, 1, 12, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'وَ  اِذَا حَضَرَ الۡقِسۡمَۃَ  اُولُوا الۡقُرۡبٰی وَ الۡیَتٰمٰی وَ الۡمَسٰکِیۡنُ فَارۡزُقُوۡہُمۡ  مِّنۡہُ وَ قُوۡلُوۡا لَہُمۡ  قَوۡلًا مَّعۡرُوۡفًا ﴿۸﴾', 'اور جب میراث کی تقسیم کے وقت غیر وارث رشتہ دار اور یتیم اور نادار لوگ آ جائیں تو ان کو بھی اس میں سے کچھ دے دو۔ اور ان سے معقول بات کہو۔', 'اور جب حاضر ہوں تقسیم کے وقت رشتہ دار اور یتیم اور محتاج تو ان کو کچھ کھلا دو اس میں سے اور کہہ دو ان کو بات معقول [۱۶]', 'And when the relatives and the orphans and AlMasakin (the poor) are present at the time of division, give them out of the property, and speak to them words of kindness and justice.', 'If the relatives (who are not heirs) and the orphans and the needy are present at the time of distribution, give them some of it, and speak to them in fair words.'),
(502, 4, 9, 1, 12, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'وَ لۡیَخۡشَ الَّذِیۡنَ لَوۡ تَرَکُوۡا مِنۡ خَلۡفِہِمۡ ذُرِّیَّۃً ضِعٰفًا خَافُوۡا عَلَیۡہِمۡ ۪ فَلۡیَتَّقُوا اللّٰہَ وَ لۡیَقُوۡلُوۡا قَوۡلًا سَدِیۡدًا ﴿۹﴾', 'اور ایسے لوگوں کو ڈرنا چاہیے جو ایسی حالت میں ہوں کہ اپنے بعد ننھے ننھے بچے چھوڑ جائیں اور ان کو ان کی نسبت خوف ہو کہ ہمارے مرنے کے بعد ان بیچاروں کا کیا ہو گا پس چاہیے کہ یہ لوگ اللہ سے ڈریں اور درست بات کہیں۔', 'اور چاہئے کہ ڈریں وہ لوگ کہ اگر چھوڑی ہے اپنے پیچھے اولاد ضعیف تو ان پر اندیشہ کریں یعنی ہمارے پیچھے ایسا ہی حال انکا ہو گا تو چاہئے کہ ڈریں اللہ سے اور کہیں بات سیدھی [۱۷]', 'And let those (executors and guardians) have the same fear in their minds as they would have for their own, if they had left weak offspring behind. So let them fear Allah and speak right words.', 'Those people should be fearful (in their behavior towards orphans) who, if they leave behind some helpless children, would remain anxious for them. So, they should fear Allah and say what is right.'),
(503, 4, 10, 1, 12, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'اِنَّ الَّذِیۡنَ یَاۡکُلُوۡنَ اَمۡوَالَ الۡیَتٰمٰی ظُلۡمًا اِنَّمَا یَاۡکُلُوۡنَ فِیۡ بُطُوۡنِہِمۡ نَارًا ؕ وَ سَیَصۡلَوۡنَ  سَعِیۡرًا ﴿٪۱۰﴾', 'جو لوگ یتیموں کا مال ناجائز طور پر کھاتے ہیں وہ اپنے پیٹ میں آگ بھرتے ہیں۔ اور ضرور دوزخ میں ڈالے جائیں گے۔', 'جو لوگ کہ کھاتے ہیں مال یتیموں کا ناحق وہ لوگ اپنے پیٹوں میں آگ ہی بھر رہے ہیں اور عنقریب داخل ہوں گے آگ میں [۱۸]', 'Verily, those who unjustly eat up the property of orphans, they eat up only a fire into their bellies, and they will be burnt in the blazing Fire!', 'Surely, those who unjustly devour the property of the orphans do nothing but devour fire into their bellies, and soon they shall enter a blazing Hell.'),
(504, 4, 11, 2, 13, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'یُوۡصِیۡکُمُ اللّٰہُ فِیۡۤ  اَوۡلَادِکُمۡ ٭ لِلذَّکَرِ مِثۡلُ حَظِّ الۡاُنۡثَیَیۡنِ ۚ فَاِنۡ کُنَّ نِسَآءً فَوۡقَ اثۡنَتَیۡنِ فَلَہُنَّ ثُلُثَا مَا تَرَکَ ۚ وَ اِنۡ کَانَتۡ وَاحِدَۃً  فَلَہَا النِّصۡفُ ؕ وَ لِاَبَوَیۡہِ لِکُلِّ وَاحِدٍ مِّنۡہُمَا السُّدُسُ مِمَّا تَرَکَ اِنۡ کَانَ لَہٗ  وَلَدٌ ۚ فَاِنۡ لَّمۡ  یَکُنۡ لَّہٗ وَلَدٌ وَّ وَرِثَہٗۤ اَبَوٰہُ فَلِاُمِّہِ الثُّلُثُ ۚ فَاِنۡ کَانَ لَہٗۤ  اِخۡوَۃٌ فَلِاُمِّہِ السُّدُسُ مِنۡۢ بَعۡدِ وَصِیَّۃٍ یُّوۡصِیۡ بِہَاۤ اَوۡ دَیۡنٍ ؕ اٰبَآؤُکُمۡ وَ اَبۡنَآؤُکُمۡ لَا تَدۡرُوۡنَ اَیُّہُمۡ اَقۡرَبُ  لَکُمۡ نَفۡعًا ؕ فَرِیۡضَۃً مِّنَ  اللّٰہِ ؕ اِنَّ اللّٰہَ کَانَ عَلِیۡمًا حَکِیۡمًا ﴿۱۱﴾', 'اللہ تمہاری اولاد کے بارے میں تم کو ارشاد فرماتا ہے کہ ایک لڑکے کا حصہ دو لڑکیوں کے حصے کے برابر ہے۔ اور اگر اولاد میت صرف لڑکیاں ہی ہوں یعنی دو یا دو سے زیادہ تو کل ترکے میں ان کا دو تہائی ہے۔ اور اگر صرف ایک لڑکی ہو تو اس کا نصف ہے۔ اور میت کے ماں باپ کا یعنی دونوں میں سے ہر ایک کا ترکے میں چھٹا حصہ ہے۔ بشرطیکہ میت کے اولاد ہو اور اگر اولاد نہ ہو اور صرف ماں باپ ہی اس کے وارث ہوں تو ایک تہائی ماں کا حصہ ہے۔ اور اگر میت کے بھائی بھی ہوں تو ماں کا چھٹا حصہ ہو گا اور یہ تقسیم ترکہ میت کی وصیت کی تعمیل کے بعد جو اس نے کی ہو یا قرض کے ادا ہونے کے بعد جو اس کے ذمہ ہو عمل میں آئے گی تم کو معلوم نہیں کہ تمہارے باپ دادوں اور بیٹوں پوتوں میں سے فائدے کے لحاظ سے کون تم سے زیادہ قریب ہے یہ حصے اللہ کے مقرر کئے ہوئے ہیں اور اللہ سب کچھ جاننے والا ہے حکمت والا ہے۔', 'حکم کرتا ہے تم کو اللہ تمہاری اولاد کے حق میں کہ ایک مرد کا حصہ ہے برابر ہے دو عورتوں کے [۱۹] پھر اگر صرف عورتیں ہی ہوں دو سے زیادہ تو ان کے لئے ہے دو تہائی اس مال سےجو چھوڑ مرا اور اگر ایک ہی ہو تو اس کے لئے آدھا ہے [۲۰] اور میت کے ماں باپ کو ہر ایک کے لئے دونوں میں سے چھٹا حصہ ہے اس مال سے جو کہ چھوڑ مرا اگر میت کے اولاد ہے [۲۱] اور اگر اس کے اولاد نہیں اور وارث ہیں اسکے ماں باپ تو اس کی ماں کا ہے تہائی [۲۲] پھر اگر میت کے کئ بھائی ہیں تو اس کی ماں کا ہے چھٹا حصہ [۲۳] بعد وصیت کے جو کر مرا یا بعد ادائے قرض کے [۲۴] تمہارے باپ اور بیٹے تم کو معلوم نہیں کون نفع پہنچائے تم کو زیادہ حصہ مقرر کیا ہوا اللہ کا ہے بیشک اللہ خبردار ہے حکمت والا [۲۵]', 'Allah commands you as regards your childrens (inheritance); to the male, a portion equal to that of two females; if (there are) only daughters, two or more, their share is two thirds of the inheritance; if only one, her share is half. For parents, a sixth share of inheritance to each if the deceased left children; if no children, and the parents are the (only) heirs, the mother has a third; if the deceased left brothers or (sisters), the mother has a sixth. (The distribution in all cases is) after the payment of legacies he may have bequeathed or debts. You know not which of them, whether your parents or your children, are nearest to you in benefit, (these fixed shares) are ordained by Allah. And Allah is Ever AllKnower, AllWise.', 'Allah directs you concerning your children: for a male there is a share equal to that of two females. But, if they are (only) women, more than two, then they get two-thirds of what one leaves behind. If she is one, she gets one-half. As for his parents, for each of them, there is one-sixth of what he leaves in case he has a child. But, if he has no child and his parents have inherited him, then his mother gets one-third. If he has some brothers (or sisters), his mother gets one-sixth, all after (settling) the will he might have made, or a debt. You do not know who, out of your fathers and your sons, is closer to you in benefiting (you). All this is determined by Allah. Surely, Allah is All-Knowing, All-Wise.'),
(505, 4, 12, 2, 13, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'وَ لَکُمۡ نِصۡفُ مَا تَرَکَ اَزۡوَاجُکُمۡ   اِنۡ لَّمۡ یَکُنۡ لَّہُنَّ وَلَدٌ ۚ فَاِنۡ کَانَ لَہُنَّ وَلَدٌ فَلَکُمُ الرُّبُعُ  مِمَّا تَرَکۡنَ مِنۡۢ بَعۡدِ وَصِیَّۃٍ یُّوۡصِیۡنَ بِہَاۤ اَوۡ دَیۡنٍ ؕ وَ لَہُنَّ الرُّبُعُ مِمَّا تَرَکۡتُمۡ  اِنۡ لَّمۡ یَکُنۡ لَّکُمۡ وَلَدٌ ۚ فَاِنۡ کَانَ لَکُمۡ وَلَدٌ فَلَہُنَّ الثُّمُنُ مِمَّا تَرَکۡتُمۡ مِّنۡۢ بَعۡدِ وَصِیَّۃٍ تُوۡصُوۡنَ بِہَاۤ  اَوۡ دَیۡنٍ ؕ وَ  اِنۡ کَانَ رَجُلٌ یُّوۡرَثُ  کَلٰلَۃً اَوِ امۡرَاَۃٌ  وَّ لَہٗۤ  اَخٌ  اَوۡ اُخۡتٌ فَلِکُلِّ وَاحِدٍ مِّنۡہُمَا السُّدُسُ ۚ فَاِنۡ  کَانُوۡۤا  اَکۡثَرَ مِنۡ ذٰلِکَ فَہُمۡ شُرَکَآءُ فِی الثُّلُثِ مِنۡۢ بَعۡدِ وَصِیَّۃٍ یُّوۡصٰی بِہَاۤ اَوۡ دَیۡنٍ ۙ غَیۡرَ مُضَآرٍّ ۚ وَصِیَّۃً  مِّنَ اللّٰہِ ؕ وَ اللّٰہُ  عَلِیۡمٌ حَلِیۡمٌ ﴿ؕ۱۲﴾', 'اور جو مال تمہاری بیویاں چھوڑ مریں۔ اگر ان کے اولاد نہ ہو تو اس میں سے نصف حصہ تمہارا ہے۔  پھر اگر انکے اولاد ہو تو ترکے میں تمہارا حصہ چوتھائی ہے لیکن یہ تقسیم وصیت کی تعمیل کے بعد جو انہوں نے کی ہو یا قرض کے ادا ہونے کے بعد جو ان کے ذمے ہو۔ کی جائے گی اور جو مال تم مرد چھوڑ مرو۔ اگر تمہارے اولاد نہ ہو تو تمہاری بیویوں کا اس میں چوتھا حصہ ہے۔ پھر اگر تمہاری اولاد ہو تو ان کا آٹھواں حصہ ہے یہ حصے تمہاری وصیت کی تعمیل کے بعد جو تم نے کی ہو۔ اور ادائے قرض کے بعد تقسیم کئے جائیں گے اور اگر ایسے مرد یا عورت کی میراث ہو جس کے نہ باپ ہو نہ بیٹا مگر اس کے بھائی یا بہن ہو تو ان میں سے ہر ایک کا چھٹا حصہ ہے اور اگر ایک سے زیادہ ہوں تو سب ایک تہائی میں شریک ہوں گے یہ حصے بھی بعد ادائے وصیت و قرض بشرطیکہ ان سے میت نے کسی کا نقصان نہ کیا ہو تقسیم کئے جائیں گے۔ یہ اللہ کا فرمان ہے۔ اور اللہ نہایت علم والا ہے بردبار ہے۔', 'اور تمہارا ہے آدھا مال جو کہ چھوڑ مریں تمہاری عورتیں اگر نہ ہو ان کے اولاد اور اگر ان کےاولاد ہے تو تمہارے واسطے چوتھائی ہے اس میں سے جو چھوڑ گئیں بعد وصیت کے جو کر گئیں یا بعد قرض کے [۲۶] اور عورتوں کے لئے چوتھائی مال ہے اس میں سے جو چھوڑ مرو تم اگر نہ ہو تمہارے اولاد اور اگر تمہارے اولاد ہے تو ان کے لئے آٹھواں حصہ ہے اس میں سے کہ جو کچھ تم نے چھوڑا بعد وصیت کے جو تم کر مرو یا قرض کے [۲۷] اور اگر وہ مرد کہ جس کی میراث ہے باپ بیٹا کچھ نہیں رکھتا یا عورت ہو ایسی ہی اور اس میت کے ایک بھائی ہے یا بہن ہے تودونوں میں سے ہر ایک کا چھٹا حصہ ہے [۲۸] اور اگر زیادہ ہوں اس سے تو سب شریک ہیں ایک تہائی میں بعد وصیت کے جو ہو چکی ہے یا قرض کے جب اوروں کا نقصان نہ کیا ہو [۲۹] یہ حکم ہے اللہ کا اور اللہ ہی سب کچھ جاننے والا تحمل کرنے والا [۳۰]', 'In that which your wives leave, your share is a half if they have no child; but if they leave a child, you get a fourth of that which they leave after payment of legacies that they may have bequeathed or debts. In that which you leave, their (your wives) share is a fourth if you leave no child; but if you leave a child, they get an eighth of that which you leave after payment of legacies that you may have bequeathed or debts. If the man or woman whose inheritance is in question has left neither ascendants nor descendants, but has left a brother or a sister, each one of the two gets a sixth; but if more than two, they share in a third; after payment of lagacies he (or she) may have bequeathed or debts, so that no loss is caused (to anyone). This is a Commandment from Allah; and Allah is Ever AllKnowing, MostForbearing.', 'For you there is one-half of what your wives leave behind, in case they have no child. But, if they have a child, you get one-fourth of what they leave, after (settling) the will they might have made, or a debt. For them (the wives) there is one-fourth of what you leave behind, in case you have no child. But, if you have a child, they get one eighth of what you leave, after (settling) the will you might have made, or a debt. And if a man or a woman is Kalālah (i.e. has neither parents alive, nor children) and has a brother or a sister, then each one of them will get one-sixth. However, if they are more than that, they will be sharers in one-third, after (settling) the will that might have been made, or a debt, provided that the will must not be intended to harm anyone. This is a direction from Allah. Allah is All-Knowing, Forbearing.'),
(506, 4, 13, 2, 13, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'تِلۡکَ حُدُوۡدُ اللّٰہِ ؕ وَ مَنۡ یُّطِعِ اللّٰہَ وَ رَسُوۡلَہٗ یُدۡخِلۡہُ جَنّٰتٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَا ؕ وَ ذٰلِکَ الۡفَوۡزُ  الۡعَظِیۡمُ ﴿۱۳﴾', 'یہ تمام احکام اللہ کی حدیں ہیں اور جو شخص اللہ اور اس کے پیغمبر کی فرمانبرداری کرے گا اللہ اس کو بہشتوں میں داخل کرے گا جن میں نہریں بہ رہی ہیں۔ وہ ان میں ہمیشہ رہیں گے اور یہ بڑی کامیابی ہے۔', 'یہ حدیں باندھی ہوئی اللہ کی ہیں اور جو کوئی حکم پر چلے اللہ کے اور سول کے اس کو داخل کرے گا جنتوں میں جن کے نیچے بہتی ہیں نہریں ہمیشہ رہیں گے ان میں اور یہ ہے بڑی مراد ملنی', 'These are the limits (set by) Allah (or ordainments as regards laws of inheritance), and whosoever obeys Allah and His Messenger (Muhammad SAW) will be admitted to Gardens under which rivers flow (in Paradise), to abide therein, and that will be the great success.', 'These are the limits set by Allah. Whoever obeys Allah and His Messenger, He will admit him to gardens beneath which rivers flow, where he will live forever. That is a great success.'),
(507, 4, 14, 2, 13, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'وَ مَنۡ یَّعۡصِ اللّٰہَ  وَ رَسُوۡلَہٗ وَ یَتَعَدَّ حُدُوۡدَہٗ یُدۡخِلۡہُ نَارًا خَالِدًا فِیۡہَا ۪ وَ لَہٗ عَذَابٌ مُّہِیۡنٌ ﴿٪۱۴﴾', 'اور جو اللہ اور اس کے رسول کی نافرمانی کرے گا اور اس کی حدوں سے نکل جائے گا اس کو اللہ دوزخ میں ڈالے گا جہاں وہ ہمیشہ رہے گا اور اس کو ذلت کا عذاب ہو گا۔', 'اور جو کوئی نافرمانی کرے اللہ کی اور اسکے رسول کی اور نکل جاوے اس کی حدوں سے ڈالے گا اس کو آگ میں ہمیشہ رہے گا اس میں اور اس کے لئے ذلت کا عذاب ہے [۳۱]', 'And whosoever disobeys Allah and His Messenger (Muhammad SAW), and transgresses His limits, He will cast him into the Fire, to abide therein; and he shall have a disgraceful torment.', 'Whoever disobeys Allah and His Messenger and transgresses the limits set by Him, He shall admit him to the Fire, where he will remain forever. For him there is a humiliating punishment.'),
(508, 4, 15, 3, 14, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'وَ الّٰتِیۡ یَاۡتِیۡنَ الۡفَاحِشَۃَ مِنۡ نِّسَآئِکُمۡ فَاسۡتَشۡہِدُوۡا عَلَیۡہِنَّ اَرۡبَعَۃً مِّنۡکُمۡ ۚ فَاِنۡ شَہِدُوۡا فَاَمۡسِکُوۡ ہُنَّ فِی الۡبُیُوۡتِ حَتّٰی یَتَوَفّٰہُنَّ الۡمَوۡتُ اَوۡ یَجۡعَلَ اللّٰہُ  لَہُنَّ  سَبِیۡلًا ﴿۱۵﴾', 'مسلمانو! تمہاری عورتوں میں جو بدکاری کا ارتکاب کر بیٹھیں ان پر اپنے لوگوں میں سے چار شخصوں کی شہادت لو اگر وہ ان کی بدکاری کی گواہی دیں تو ان عورتوں کو گھروں میں بند رکھو یہاں تک کہ موت ان کا کام تمام کردے یا اللہ ان کے لئے کوئی اور سبیل پیدا کرے۔', 'اور جو کوئی بدکاری کرے تمہاری عورتوں میں سے تو گواہ لاؤ ان پر چار مرد اپنوں میں سے پھر اگر وہ گواہی دے دیویں تو بند رکھو ان عورتوں کو گھروں میں یہاں تک کہ اٹھا لیوے ان کو موت یا مقرر کر دے اللہ ان کے لئے کوئی راہ [۳۲]', 'And those of your women who commit illegal sexual intercourse, take the evidence of four witnesses from amongst you against them; and if they testify, confine them (i.e. women) to houses until death comes to them or Allah ordains for them some (other) way.', 'Those of your women who commit the shameful act, have four witnesses (against them) from among you. So, if they testify, then confine those women to their homes until death overcomes them, or Allah prescribes a way for them.'),
(509, 4, 16, 3, 14, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'وَ الَّذٰنِ یَاۡتِیٰنِہَا مِنۡکُمۡ  فَاٰذُوۡہُمَا ۚ فَاِنۡ تَابَا وَ اَصۡلَحَا فَاَعۡرِضُوۡا عَنۡہُمَا ؕ اِنَّ اللّٰہَ کَانَ تَوَّابًا رَّحِیۡمًا ﴿۱۶﴾', 'اور جو دو مرد تم میں سے بدکاری کریں تو ان کو ایذا دو پھر اگر وہ توبہ کر لیں اور نیکوکار ہو جائیں تو ان کا پیچھا چھوڑ دو۔ بیشک اللہ توبہ قبول کرنے والا ہے مہربان ہے۔', 'اور جو دو مرد کریں تم میں سے وہی بدکاری تو ان کو ایذا دو [۳۳] پھر اگر وہ دونوں توبہ کریں اور اپنی اصلاح کر لیں تو ان کا خیال چھوڑ دو بیشک اللہ توبہ قبول کرنے والا مہربان ہے [۳۴]', 'And the two persons (man and woman) among you who commit illegal sexual intercourse, punish them both. And if they repent (promise Allah that they will never repeat, i.e. commit illegal sexual intercourse and other similar sins) and do righteous good deeds, leave them alone. Surely, Allah is Ever the One Who accepts repentance, (and He is) Most Merciful.', 'Those two of you who commit it, chastise both of them. However, if they repent and make amends, then, overlook them. Surely, Allah is Most-Relenting, Very-Merciful.'),
(510, 4, 17, 3, 14, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'اِنَّمَا التَّوۡبَۃُ عَلَی اللّٰہِ لِلَّذِیۡنَ یَعۡمَلُوۡنَ السُّوۡٓءَ بِجَہَالَۃٍ ثُمَّ  یَتُوۡبُوۡنَ مِنۡ قَرِیۡبٍ فَاُولٰٓئِکَ یَتُوۡبُ اللّٰہُ عَلَیۡہِمۡ ؕ وَ کَانَ اللّٰہُ  عَلِیۡمًا  حَکِیۡمًا ﴿۱۷﴾', 'اللہ انہی لوگوں کی توبہ قبول فرماتا ہے جو نادانی سے بری حرکت کر بیٹھتے ہیں پھر جلد توبہ کر لیتے ہیں پس ایسے لوگوں پر اللہ توجہ کرتا ہے اور وہ سب کچھ جاننے والا ہے حکمت والا ہے۔', 'توبہ قبول کرنی اللہ کو ضرور تو انکی ہے جو کرتے ہیں برا کام جہالت سے پھر توبہ کرتے ہیں جلدی سے تو ان کو اللہ معاف کر دیتا ہے اور اللہ سب کچھ جاننے والا ہے حکمت والا [۳۵]', 'Allah accepts only the repentance of those who do evil in ignorance and foolishness and repent soon afterwards; it is they to whom Allah will forgive and Allah is Ever AllKnower, AllWise.', 'The relenting taken by Allah upon Himself is for those who do evil in ignorance, then repent shortly thereafter. So, Allah relents towards them. Allah is All-Knowing, All-Wise.'),
(511, 4, 18, 3, 14, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'وَ لَیۡسَتِ التَّوۡبَۃُ لِلَّذِیۡنَ یَعۡمَلُوۡنَ السَّیِّاٰتِ ۚ حَتّٰۤی  اِذَا حَضَرَ اَحَدَہُمُ الۡمَوۡتُ قَالَ  اِنِّیۡ تُبۡتُ الۡـٰٔنَ  وَ لَا الَّذِیۡنَ یَمُوۡتُوۡنَ وَ ہُمۡ کُفَّارٌ ؕ اُولٰٓئِکَ اَعۡتَدۡنَا لَہُمۡ عَذَابًا  اَلِیۡمًا ﴿۱۸﴾', 'اور ایسے لوگوں کی توبہ قبول نہیں ہوتی جو ساری عمر برے کام کرتے رہیں یہاں تک کہ جب ان میں سے کسی کی موت آ موجود ہو تو اس وقت کہنے لگے کہ اب میں توبہ کرتا ہوں اور نہ ان کی توبہ قبول ہوتی ہے جو کفر کی حالت میں مریں ایسے لوگوں کے لئے ہم نے دردناک عذاب تیار کر رکھا ہے۔', 'اور ایسوں کی توبہ نہیں جو کئے جاتے ہیں برے کام یہاں تک کہ جب سامنے آ جائے ان میں سے کسی کے موت تو کہنے لگا میں توبہ کرتا ہوں اب اور نہ ایسوں کی توبہ جو کہ مرتے ہیں حالت کفر میں ان کے لئے تو ہم نے تیار کیا ہے عذاب دردناک [۳۶]', 'And of no effect is the repentance of those who continue to do evil deeds until death faces one of them and he says: \"Now I repent;\" nor of those who die while they are disbelievers. For them We have prepared a painful torment.', 'The relenting is not for those who do the evil deeds, until when the time of death approaches one of them, he says, “Now I repent”, nor for those who die while they are still disbelievers. For them We have prepared a painful punishment'),
(512, 4, 19, 3, 14, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا یَحِلُّ لَکُمۡ اَنۡ تَرِثُوا النِّسَآءَ کَرۡہًا ؕ وَ لَا تَعۡضُلُوۡہُنَّ لِتَذۡہَبُوۡا بِبَعۡضِ مَاۤ اٰتَیۡتُمُوۡہُنَّ  اِلَّاۤ اَنۡ یَّاۡتِیۡنَ بِفَاحِشَۃٍ مُّبَیِّنَۃٍ ۚ وَ عَاشِرُوۡہُنَّ بِالۡمَعۡرُوۡفِ ۚ فَاِنۡ کَرِہۡتُمُوۡہُنَّ فَعَسٰۤی اَنۡ تَکۡرَہُوۡا شَیۡئًا وَّ یَجۡعَلَ اللّٰہُ فِیۡہِ خَیۡرًا کَثِیۡرًا ﴿۱۹﴾', 'مومنو! تم کو جائز نہیں کہ زبردستی عورتوں کے وارث بن جاؤ۔ اور دیکھنا اس نیت سے کہ جو کچھ تم نے ان کو دیا ہے اس میں سے کچھ لے لو انہیں گھروں میں مت روک رکھنا ہاں اگر وہ کھلے طور پر بدکاری کی مرتکب ہوں تو اور بات ہے اور ان کے ساتھ اچھی طرح سے رہو سہو۔ پھر اگر وہ تم کو ناپسند ہوں تو عجب نہیں کہ تم کسی چیز کو ناپسند کرو اور اللہ اس میں بہت سی بھلائی پیدا کر دے۔', 'اے ایمان والو حلال نہیں تم کو کہ میراث میں لے لو عورتوں کو زبردستی اور نہ روکے رکھو ان کو اس واسطے کہ لے لو ان سے کچھ اپنا دیا ہوا مگر کہ وہ کریں بے حیائی صریح [۳۷] اور گذران کرو عورتوں کے ساتھ اچھی طرح پھر اگر وہ تم کو نہ بھاویں تو شاید تم کو پسند نہ آوے ایک چیز اور اللہ نے رکھی ہو اس میں بہت خوبی [۳۸]', 'O you who believe! You are forbidden to inherit women against their will, and you should not treat them with harshness, that you may take away part of the Mahr you have given them, unless they commit open illegal sexual intercourse. And live with them honourably. If you dislike them, it may be that you dislike a thing and Allah brings through it a great deal of good.', 'O you who believe, it is not lawful for you that you should forcibly take women as inheritance. Do not hold on to them so that you may take away some of what you have given them, unless they commit a clearly shameful act. Live with them in the recognized manner. If you dislike them, then it is quite likely that you dislike something and Allah has placed a lot of good in it.'),
(513, 4, 20, 3, 14, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'وَ اِنۡ اَرَدۡتُّمُ اسۡتِبۡدَالَ زَوۡجٍ مَّکَانَ زَوۡجٍ ۙ وَّ اٰتَیۡتُمۡ  اِحۡدٰہُنَّ قِنۡطَارًا فَلَا تَاۡخُذُوۡا مِنۡہُ شَیۡئًا ؕ اَتَاۡخُذُوۡنَہٗ بُہۡتَانًا وَّ  اِثۡمًا مُّبِیۡنًا ﴿۲۰﴾', 'اور اگر تم ایک عورت کو چھوڑ کر دوسری عورت کرنی چاہو اور پہلی عورت کو ڈھیر سا مال دے چکے ہو تو اس میں سے کچھ مت لینا۔ بھلا تم بہتان لگا کر اور کھلا گناہ کر کے اپنا مال اس سے واپس لو گے۔', 'اور اگر بدلنا چاہو ایک عورت کی جگہ دوسری عورت کو اور دے چکے ہو ایک کو بہت سا مال تو مت پھیر لو اس میں سے کچھ کیا لیا چاہتے ہو اس کو ناحق اور صریح گناہ سے [۳۹]', 'But if you intend to replace a wife by another and you have given one of them a Cantar (of gold i.e. a great amount) as Mahr, take not the least bit of it back; would you take it wrongfully without a right and (with) a manifest sin?', 'If you want to take a wife in place of the one (you have), and you have given her plenty of wealth, then do not take any of it back. Would you take it through imputation and open sin?');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(514, 4, 21, 3, 14, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'وَ کَیۡفَ تَاۡخُذُوۡنَہٗ وَ قَدۡ  اَفۡضٰی بَعۡضُکُمۡ  اِلٰی بَعۡضٍ وَّ اَخَذۡنَ مِنۡکُمۡ مِّیۡثَاقًا غَلِیۡظًا ﴿۲۱﴾', 'اور تم دیا ہوا مال کیونکر واپس لے سکتے ہو جبکہ تم ایک دوسرے کے ساتھ صحبت کر چکے ہو اور وہ تم سے پختہ عہد بھی لے چکی ہیں۔', 'اور کیونکہ اس کو لے سکتے ہو اور پہنچ چکا ہے تم میں کا ایک دوسرے تک اور لے چکیں وہ عورتیں تم سے عہد پختہ [۴۰]', 'And how could you take it (back) while you have gone in unto each other, and they have taken from you a firm and strong covenant?', 'How can you take it when you have had access to each other and they have taken a firm covenant from you?'),
(515, 4, 22, 3, 14, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'وَ لَا تَنۡکِحُوۡا مَا نَکَحَ اٰبَآؤُکُمۡ مِّنَ النِّسَآءِ  اِلَّا مَا قَدۡ سَلَفَ ؕ اِنَّہٗ کَانَ فَاحِشَۃً وَّ مَقۡتًا ؕ وَ سَآءَ  سَبِیۡلًا ﴿٪۲۲﴾', 'اور جن عورتوں سے تمہارے باپ دادا نے نکاح کیا ہو ان سے نکاح نہ کرنا مگر جاہلیت میں جو ہو چکا سو ہو چکا یہ نہایت بےحیائی اور اللہ کی ناخوشی کی بات تھی۔ اور بہت برا دستور تھا۔', 'اور نکاح میں نہ لاؤ جن عورتوں کو نکاح میں لائے تمہارے باپ مگر جو پہلے ہو چکا یہ بے حیائی ہے اور کام ہے غضب کا اور برا چلن ہے [۴۱]', 'And marry not women whom your fathers married, except what has already passed; indeed it was shameful and most hateful, and an evil way.', 'Do not marry those women whom your fathers had married except what has passed. It is indeed shameful and detestable, and it is an evil practice.'),
(516, 4, 23, 4, 1, 4, 'لَنۡ تَنَالُوا', 'النسآء', 'حُرِّمَتۡ عَلَیۡکُمۡ اُمَّہٰتُکُمۡ وَ بَنٰتُکُمۡ وَ اَخَوٰتُکُمۡ وَ عَمّٰتُکُمۡ وَ خٰلٰتُکُمۡ وَ بَنٰتُ الۡاَخِ وَ بَنٰتُ الۡاُخۡتِ وَ اُمَّہٰتُکُمُ الّٰتِیۡۤ  اَرۡضَعۡنَکُمۡ وَ اَخَوٰتُکُمۡ مِّنَ الرَّضَاعَۃِ  وَ اُمَّہٰتُ نِسَآئِکُمۡ  وَ رَبَآئِبُکُمُ الّٰتِیۡ فِیۡ  حُجُوۡرِکُمۡ مِّنۡ نِّسَآئِکُمُ الّٰتِیۡ دَخَلۡتُمۡ بِہِنَّ ۫ فَاِنۡ  لَّمۡ تَکُوۡنُوۡا دَخَلۡتُمۡ بِہِنَّ فَلَا جُنَاحَ عَلَیۡکُمۡ ۫ وَ حَلَآئِلُ اَبۡنَآئِکُمُ الَّذِیۡنَ مِنۡ اَصۡلَابِکُمۡ ۙ  وَ اَنۡ تَجۡمَعُوۡا بَیۡنَ الۡاُخۡتَیۡنِ اِلَّا مَا قَدۡ سَلَفَ ؕ اِنَّ اللّٰہَ کَانَ  غَفُوۡرًا  رَّحِیۡمًا ﴿ۙ۲۳﴾', 'تم پر تمہاری مائیں اور بیٹیاں اور بہنیں اور پھوپھیاں اور خالائیں اور بھتیجیاں اور بھانجیاں اور وہ مائیں جنہوں نے تم کو دودھ پلایا ہو اور رضاعی بہنیں اور ساسیں حرام کر دی گئ ہیں اور جن عورتوں سے تم خلوت کر چکے ہو ان کی لڑکیاں جنہیں تم پرورش کرتے ہو وہ بھی تم پر حرام ہیں ہاں اگر ان کے ساتھ تم نے خلوت نہ کی ہو تو ان کی لڑکیوں کے ساتھ نکاح کر لینے میں تم پر کچھ گناہ نہیں۔ اور تمہارے صلبی بیٹوں کی عورتیں بھی۔ اور دو بہنوں کا اکٹھا کرنا بھی حرام ہے مگر جو ہو چکا سو ہو چکا بے شک اللہ بخشنے والا ہے بڑا مہربان ہے۔', 'حرام ہوئی ہیں تم پر تمہاری مائیں اور بیٹیاں اور بہنیں اور پھوپھیاں اور خالائیں اور بیٹیاں بھائی کی اور بہن کی [۴۲] اور جن ماؤں نے تم کو دودھ پلایا اور دودھ کی بہنیں [۴۳] اور تمہاری عورتوں کی مائیں اور ان کی بیٹیاں جو تمہاری پرورش میں ہیں جن کو کہ جنا ہے تمہاری ان عورتوں نے جن سے تم نے صحبت کی اور اگر تم نے ان سے صحبت نہیں کی تو تم پر کچھ گناہ نہیں اس نکاح میں اور عورتیں تمہارے بیٹوں کی جو تمہاری پشت سے ہیں اور یہ کہ اکٹھا کرو دو بہنوں کو مگر جو پہلے ہو چکا بیشک اللہ بخشنے والا مہربان ہے [۴۴]', 'Forbidden to you (for marriage) are: your mothers, your daughters, your sisters, your fathers sisters, your mothers sisters, your brothers daughters, your sisters daughters, your foster mother who gave you suck, your foster milk suckling sisters, your wives mothers, your step daughters under your guardianship, born of your wives to whom you have gone in - but there is no sin on you if you have not gone in them (to marry their daughters), - the wives of your sons who (spring) from your own loins, and two sisters in wedlock at the same time, except for what has already passed; verily, Allah is OftForgiving, Most Merciful.', 'Prohibited for you are your mothers, your daughters, your sisters, your paternal aunts, your maternal aunts, daughters of brother, daughters of sister, your mothers who suckled you, your sisters through suckling,mothers of your wives and your step-daughters under your care who are born of your women with whom you have had intercourse,-though if you have not had intercourse with them, there is no sin on you,-and the wives of your sons from your loins, and that you combine two sisters (in wedlock), except what has passed. Surely, Allah is Most-Forgiving, Very-Merciful.'),
(517, 4, 24, 4, 1, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَّ الۡمُحۡصَنٰتُ مِنَ النِّسَآءِ  اِلَّا مَا مَلَکَتۡ اَیۡمَانُکُمۡ ۚ کِتٰبَ اللّٰہِ عَلَیۡکُمۡ ۚ وَ اُحِلَّ لَکُمۡ مَّا وَرَآءَ ذٰلِکُمۡ اَنۡ تَبۡتَغُوۡا بِاَمۡوَالِکُمۡ مُّحۡصِنِیۡنَ غَیۡرَ مُسٰفِحِیۡنَ ؕ فَمَا اسۡتَمۡتَعۡتُمۡ بِہٖ مِنۡہُنَّ فَاٰتُوۡہُنَّ اُجُوۡرَہُنَّ فَرِیۡضَۃً ؕ وَ لَا جُنَاحَ عَلَیۡکُمۡ فِیۡمَا تَرٰضَیۡتُمۡ بِہٖ مِنۡۢ بَعۡدِ الۡفَرِیۡضَۃِ ؕ اِنَّ اللّٰہَ کَانَ عَلِیۡمًا حَکِیۡمًا ﴿۲۴﴾', 'اور شوہر والی عورتیں بھی تم پر حرام ہیں مگر وہ جو قید ہو کر باندیوں کے طور پر تمہارے قبضے میں آ جائیں یہ حکم اللہ نے تم کو لکھ دیا ہے۔ اور ان محرمات کے سوا دوسری عورتیں تم کو حلال ہیں اس طرح سے کہ مال خرچ کر کے ان سے نکاح کر لو بشرطیکہ نکاح سے مقصود عفت قائم رکھنا ہو نہ  کہ شہوت پرستی۔ تو جن عورتوں سے تم لطف اندوز ہوئے ان کا مہر جو مقرر کیا ہو ادا کر دو اور اگر مقرر کرنے کے بعد آپس کی رضامندی سے مہر میں کمی بیشی کر لو تو تم پر کچھ گناہ نہیں۔ بیشک اللہ سب کچھ جاننے والا ہے حکمت والا ہے۔', 'اور خاوند والی عورتیں مگر جن کےمالک ہو جائیں تمہارے ہاتھ حکم ہوا اللہ کا تم پر [۴۵] اور حلال ہیں تم کو سب عورتیں ان کےسوا بشرطیکہ طلب کرو انکو اپنے مال کے بدلے قید میں لانے کو نہ مستی نکالنے کو [۴۶] پھر جس کو کام میں لائے تم ان عورتوں میں سے تو ان کو دو ان کے حق جو مقرر ہوئے [۴۷] اور گناہ نہیں تم کو اس بات میں کہ ٹھہرا لو تم دونوں آپس کی رضا سے مقرر کیے پیچھے بیشک اللہ ہے خبردار حکمت والا [۴۸]', 'Also (forbidden are) women already married, except those (captives and slaves) whom your right hands possess. Thus has Allah ordained for you. All others are lawful, provided you seek (them in marriage) with Mahr (bridal money given by the husband to his wife at the time of marriage) from your property, desiring chastity, not committing illegal sexual intercourse, so with those of whom you have enjoyed sexual relations, give them their Mahr as prescribed; but if after a Mahr is prescribed, you agree mutually (to give more), there is no sin on you. Surely, Allah is Ever AllKnowing, AllWise.', '(Also prohibited are) the women already bound in marriage, except the bondwomen you come to own. It has been written by Allah for you. All (women), except these, have been permitted for you to seek (to marry) through your wealth, binding yourself, (in marriage) and not only for lust. So, to those of them whose company you have enjoyed, give their dues (dower) as obligated. There is no sin on you in what you mutually agree upon after the (initial) agreement. Surely, Allah is All-Knowing, All-Wise.'),
(518, 4, 25, 4, 1, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ مَنۡ لَّمۡ یَسۡتَطِعۡ مِنۡکُمۡ طَوۡلًا اَنۡ یَّنۡکِحَ الۡمُحۡصَنٰتِ الۡمُؤۡمِنٰتِ فَمِنۡ مَّا مَلَکَتۡ اَیۡمَانُکُمۡ مِّنۡ فَتَیٰتِکُمُ الۡمُؤۡمِنٰتِ ؕ وَ اللّٰہُ اَعۡلَمُ  بِاِیۡمَانِکُمۡ ؕ بَعۡضُکُمۡ مِّنۡۢ بَعۡضٍ ۚ فَانۡکِحُوۡہُنَّ بِاِذۡنِ اَہۡلِہِنَّ وَ اٰتُوۡہُنَّ اُجُوۡرَہُنَّ بِالۡمَعۡرُوۡفِ مُحۡصَنٰتٍ غَیۡرَ مُسٰفِحٰتٍ وَّ لَا مُتَّخِذٰتِ اَخۡدَانٍ ۚ فَاِذَاۤ   اُحۡصِنَّ فَاِنۡ اَتَیۡنَ بِفَاحِشَۃٍ فَعَلَیۡہِنَّ نِصۡفُ مَا عَلَی الۡمُحۡصَنٰتِ مِنَ الۡعَذَابِ ؕ ذٰلِکَ لِمَنۡ خَشِیَ الۡعَنَتَ مِنۡکُمۡ ؕ وَ اَنۡ تَصۡبِرُوۡا خَیۡرٌ  لَّکُمۡ ؕ وَ اللّٰہُ  غَفُوۡرٌ رَّحِیۡمٌ ﴿٪۲۵﴾', 'اور جو شخص تم میں سے مومن آزاد عورتوں سے نکاح کرنے کا مقدور نہ رکھے تو مومن باندیوں ہی سے جو تمہارے قبضے میں آ گئ ہوں نکاح کر لے اور اللہ تمہارے ایمان کو اچھی طرح جانتا ہے تم آپس میں ایک دوسرے کے ہم جنس ہو۔ پھر ان لونڈیوں کے ساتھ ان کے مالکوں سے اجازت حاصل کر کے نکاح کر لو۔ اور دستور کے مطابق ان کا مہر بھی ادا کر دو بشرطیکہ وہ پاکدامن ہوں۔ نہ ایسی کہ کھلم کھلا بدکاری کریں اور نہ درپردہ دوستی کرنا چاہیں۔ پھر اگر وہ نکاح میں آ کر بدکاری کا ارتکاب کر بیٹھیں تو جو سزا آزاد عورتوں کے لئے ہے اس کی آدھی ان کو دی جائے۔ یہ باندی کے ساتھ نکاح کرنے کی اجازت اس شخص کو ہے جسے گناہ کر بیٹھنے کا اندیشہ ہو۔ اور یہ بات کہ صبر کرو تمہارے لئے بہتر ہے اور اللہ بخشنے والا ہے مہربان ہے۔', 'اور جو کوئی نہ رکھے تم میں مقدور اس کا کہ نکاح میں لائے بیبیاں مسلمان تو نکاح کر لے ان سے جو تمہارے ہاتھ کا مال ہیں جو کہ تمہارے آپس کی لونڈیاں ہیں مسلمان [۴۹] اور اللہ کو خوب معلوم ہے تمہاری مسلمانی تم آپس میں ایک ہو [۵۰] سو ان سے نکاح کرو ان کے مالکوں کی اجازت سے اور دو ان کے مہر موافق دستور کے قید میں آنے والیاں ہوں نہ مستی نکالنے والیاں اور نہ چھپی یاری کرنے والیاں [۵۱] پھر جب قید نکاح میں آ چکیں تو اگر کریں بے حیائی کا کام تو ان پر آدھی سزا ہے بیبیوں کی سزا سے [۵۲] یہ اس کے واسطے ہے جو کوئی تم میں ڈرے تکلیف میں پڑنے سے اور صبر کرو تو بہتر ہے تمہارے حق میں اور اللہ بخشنے والا مہربان ہے [۵۳]', 'And whoever of you have not the means wherewith to wed free, believing women, they may wed believing girls from among those (captives and slaves) whom your right hands possess, and Allah has full knowledge about your Faith, you are one from another. Wed them with the permission of their own folk (guardians, Auliya or masters) and give them their Mahr according to what is reasonable; they (the above said captive and slave-girls) should be chaste, not adulterous, nor taking boy-friends. And after they have been taken in wedlock, if they commit illegal sexual intercourse, their punishment is half that for free (unmarried) women. This is for him among you who is afraid of being harmed in his religion or in his body; but it is better for you that you practise selfrestraint, and Allah is OftForgiving, Most Merciful.', 'If one cannot afford to marry the free Muslim women, then (he may marry) the one you people own of your Muslim girls. Allah knows best about your faith. You are similar to each other.So, marry them with the permission of their masters, and give them their dues, as recognized, they being bound in marriage, not going for lust, nor having paramours. So, once they have been bound in marriage, then, if they commit a shameful act, they shall be liable to half of the punishment prescribed for the free women. That is for those of you who apprehend to indulge in sin. But that you be patient is better for you. Allah is Most-Forgiving, Very-Merciful.'),
(519, 4, 26, 5, 2, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'یُرِیۡدُ اللّٰہُ لِیُبَیِّنَ لَکُمۡ وَ یَہۡدِیَکُمۡ سُنَنَ الَّذِیۡنَ مِنۡ قَبۡلِکُمۡ وَ یَتُوۡبَ عَلَیۡکُمۡ ؕ وَ اللّٰہُ  عَلِیۡمٌ  حَکِیۡمٌ ﴿۲۶﴾', 'اللہ چاہتا ہے کہ اپنی آیتیں تم سے کھول کھول کر بیان فرمائے اور تم کو اگلے لوگوں کے طریقے بتائے۔ اور تم پر مہربانی کرے۔ اور اللہ جاننے والا ہے حکمت والا ہے۔', 'اللہ چاہتا ہے کہ بیان کرے تمہارے واسطے اور چلائے تم کو پہلوں کی راہ اور معاف کرے تم کو اور اللہ جاننے والا ہے حکمت والا [۵۴]', 'Allah wishes to make clear (what is lawful and what is unlawful) to you, and to show you the ways of those before you, and accept your repentance, and Allah is AllKnower, AllWise.', 'Allah intends (through this Qur’ān) to explain to you (the rules) and to guide you to the ways of those (prophets who passed) before you, and to turn graciously towards you. Allah is All-Knowing, All-Wise.'),
(520, 4, 27, 5, 2, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ اللّٰہُ یُرِیۡدُ اَنۡ یَّتُوۡبَ عَلَیۡکُمۡ ۟ وَ یُرِیۡدُ الَّذِیۡنَ یَتَّبِعُوۡنَ الشَّہَوٰتِ اَنۡ تَمِیۡلُوۡا مَیۡلًا عَظِیۡمًا ﴿۲۷﴾', 'اور اللہ تو چاہتا ہے کہ تم پر مہربانی کرے۔ اور جو لوگ اپنی خواہشوں کے پیچھے چلتے ہیں وہ چاہتے ہیں کہ تم سیدھے رستے سے بھٹک کر دور جا پڑو۔', 'اور اللہ چاہتا ہے کہ تم پر متوجہ ہووے اور چاہتے ہیں وہ لوگ جو لگے ہوئے ہیں اپنے مزوں کے پیچھے کہ تم پھر جاؤ راہ سے بہت دور [۵۵]', 'Allah wishes to accept your repentance, but those who follow their lusts, wish that you (believers) should deviate tremendously away from the Right Path.', 'Allah intends to turn graciously towards you, while those who follow desires want you to deviate (from the right path), a huge deviation.'),
(521, 4, 28, 5, 2, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'یُرِیۡدُ اللّٰہُ اَنۡ یُّخَفِّفَ عَنۡکُمۡ ۚ وَ خُلِقَ الۡاِنۡسَانُ ضَعِیۡفًا ﴿۲۸﴾', 'اللہ چاہتا ہے کہ تم پر سے بوجھ ہلکا کرے اور انسان طبعًا کمزور پیدا ہوا ہے۔', 'اللہ چاہتا ہے کہ تم  سے بوجھ ہلکا کرے اور انسان بنا ہے کمزور [۵۶]', 'Allah wishes to lighten (the burden) for you; and man was created weak (cannot be patient to leave sexual intercourse with woman).', 'Allah intends to make things easy on you. And man has been created weak.'),
(522, 4, 29, 5, 2, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَاۡکُلُوۡۤا اَمۡوَالَکُمۡ بَیۡنَکُمۡ بِالۡبَاطِلِ اِلَّاۤ اَنۡ تَکُوۡنَ تِجَارَۃً عَنۡ تَرَاضٍ مِّنۡکُمۡ ۟ وَ لَا تَقۡتُلُوۡۤا اَنۡفُسَکُمۡ ؕ اِنَّ اللّٰہَ کَانَ بِکُمۡ رَحِیۡمًا ﴿۲۹﴾', 'مومنو! ایک دوسرے کا مال ناحق نہ کھاؤ ہاں اگر آپس کی رضامندی سے تجارت کا لین دین ہو اور اس سے مالی فائدہ حاصل ہو جائے تو وہ جائز ہے اور اپنے آپ کو ہلاک نہ کرو۔ کچھ شک نہیں کہ اللہ تم پر مہربان ہے۔', 'اے ایمان والو نہ کھاؤ مال ایک دوسرے کے آپس میں ناحق مگر یہ کہ تجارت ہو آپس کی خوشی سے [۵۷] اور نہ خون کرو آپس میں بیشک اللہ تم پر مہربان ہے [۵۸]', 'O you who believe! Eat not up your property among yourselves unjustly except it be a trade amongst you, by mutual consent. And do not kill yourselves (nor kill one another). Surely, Allah is Most Merciful to you.', 'O you who believe, do not devour each other’s property by false means, unless it is trade conducted with your mutual consent. Do not kill one another. Indeed, Allah has been Very-Merciful to you.'),
(523, 4, 30, 5, 2, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ مَنۡ یَّفۡعَلۡ ذٰلِکَ عُدۡوَانًا وَّ ظُلۡمًا فَسَوۡفَ نُصۡلِیۡہِ نَارًا ؕ وَ کَانَ ذٰلِکَ عَلَی اللّٰہِ  یَسِیۡرًا ﴿۳۰﴾', 'اور جو  زیادتی کرتے ہوئے اور ظلم سے ایسا کرے گا تو ہم اس کو عنقریب جہنم میں داخل کریں گے۔ اور یہ اللہ کو آسان ہے۔', 'اور جو کوئی یہ کام کرے تعدی سے اور ظلم سے تو ہم اس کو ڈالیں گے آگ میں اور یہ اللہ پر آسان ہے [۵۹]', 'And whoever commits that through aggression and injustice, We shall cast him into the Fire, and that is easy for Allah.', 'Whoever does that out of aggression and injustice, We shall cast him into the Fire. This is an easy thing for Allah.'),
(524, 4, 31, 5, 2, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اِنۡ تَجۡتَنِبُوۡا کَبَآئِرَ مَا تُنۡہَوۡنَ عَنۡہُ نُکَفِّرۡ عَنۡکُمۡ سَیِّاٰتِکُمۡ وَ نُدۡخِلۡکُمۡ  مُّدۡخَلًا کَرِیۡمًا ﴿۳۱﴾', 'اگر تم بڑے بڑے گناہوں سے جن سے تم کو منع کیا جاتا ہے پرہیز کرو گے تو ہم تمہارے چھوٹے چھوٹے گناہ معاف کر دیں گے۔ اور تمہیں عزت کے مکانوں میں داخل کریں گے۔', 'اگر تم بچتے رہو گے ان چیزوں سے جو گناہوں میں بڑی ہیں تو ہم معاف کر دیں گے تم سے چھوٹے گناہ تمہارے اور داخل کریں گے تم کو عزت کے مقام میں [۶۰]', 'If you avoid the great sins which you are forbidden to do, We shall remit from you your (small) sins, and admit you to a Noble Entrance (i.e. Paradise).', 'If you abstain from the major (sins) out of what you have been forbidden from, We shall write off your minor sins, and shall admit you to a noble entrance.'),
(525, 4, 32, 5, 2, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ لَا تَتَمَنَّوۡا مَا فَضَّلَ اللّٰہُ بِہٖ بَعۡضَکُمۡ عَلٰی بَعۡضٍ ؕ لِلرِّجَالِ نَصِیۡبٌ مِّمَّا اکۡتَسَبُوۡا ؕ وَ لِلنِّسَآءِ نَصِیۡبٌ مِّمَّا اکۡتَسَبۡنَ ؕ وَ سۡئَلُوا اللّٰہَ مِنۡ فَضۡلِہٖ ؕ اِنَّ اللّٰہَ کَانَ بِکُلِّ شَیۡءٍ عَلِیۡمًا ﴿۳۲﴾', 'اور جس چیز میں اللہ نے تم میں سے بعض کو بعض پر فضیلت دی ہے اس کی تمنا مت کرو۔ مردوں کو ان کاموں کا ثواب ہے جو انہوں نے کئے۔ اور عورتوں کو ان کاموں کا ثواب ہے جو انہوں نے کئے اور اللہ سے اس کا فضل و کرم مانگتے رہو کچھ شک نہیں کہ اللہ ہر چیز سے واقف ہے۔', 'اور ہوس مت کرو جس چیز میں بڑائی دی اللہ نے ایک کو ایک پر [۶۱] مردوں کو حصہ ہے اپنی کمائی سے اور عورتوں کو حصہ ہے اپنی کمائی سے اور مانگو اللہ سے اس کا فضل بیشک اللہ کو ہر چیز معلوم ہے [۶۲]', 'And wish not for the things in which Allah has made some of you to excel others. For men there is reward for what they have earned, (and likewise) for women there is reward for what they have earned, and ask Allah of His Bounty. Surely, Allah is Ever AllKnower of everything.', 'Do not covet something in which Allah has made some of you superior to others. For men there is a share of what they earned, and for women, a share of what they earned. Pray to Allah for His grace. Surely, Allah is All-Aware of everything.'),
(526, 4, 33, 5, 2, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ لِکُلٍّ جَعَلۡنَا مَوَالِیَ  مِمَّا تَرَکَ الۡوَالِدٰنِ وَ الۡاَقۡرَبُوۡنَ ؕ وَ الَّذِیۡنَ عَقَدَتۡ اَیۡمَانُکُمۡ فَاٰتُوۡہُمۡ نَصِیۡبَہُمۡ ؕ اِنَّ اللّٰہَ کَانَ عَلٰی کُلِّ شَیۡءٍ  شَہِیۡدًا ﴿٪۳۳﴾', 'اور جو مال ماں باپ اور رشتہ دار چھوڑ مریں تو حقداروں میں تقسیم کر دو کہ ہم نے ہر ایک کے حقدار مقرر کر دیئے ہیں۔ اور جن لوگوں سے تم عہد کر چکے ہو ان کو بھی ان کا حصہ دو۔ بیشک اللہ ہر چیز پر نگران ہے۔', 'اور ہر کسی کے لئے ہم نے مقرر کر دیے ہیں وارث اس مال کے کہ چھوڑ مریں ماں باپ اور قرابت والے اور جن سے معاہدہ ہوا تمہارا ان کو دے دو ان کا حصہ بیشک اللہ کے روبرو ہے ہر چیز [۶۳]', 'And to everyone, We have appointed heirs of that (property) left by parents and relatives. To those also with whom you have made a pledge (brotherhood), give them their due portion (by Wasiya wills, etc.). Truly, Allah is Ever a Witness over all things.', 'For everyone We have made heirs in what the parents and the nearest of kin have left. As for those with whom you have made a pledge, give them their shares. Surely, Allah is Witness over everything.'),
(527, 4, 34, 6, 3, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اَلرِّجَالُ قَوّٰمُوۡنَ عَلَی النِّسَآءِ بِمَا فَضَّلَ اللّٰہُ بَعۡضَہُمۡ عَلٰی بَعۡضٍ وَّ بِمَاۤ اَنۡفَقُوۡا مِنۡ اَمۡوَالِہِمۡ ؕ فَالصّٰلِحٰتُ قٰنِتٰتٌ حٰفِظٰتٌ لِّلۡغَیۡبِ بِمَا حَفِظَ اللّٰہُ ؕ وَ الّٰتِیۡ تَخَافُوۡنَ نُشُوۡزَہُنَّ فَعِظُوۡہُنَّ وَ اہۡجُرُوۡہُنَّ فِی الۡمَضَاجِعِ وَ اضۡرِبُوۡہُنَّ ۚ فَاِنۡ اَطَعۡنَکُمۡ فَلَا تَبۡغُوۡا عَلَیۡہِنَّ سَبِیۡلًا ؕ اِنَّ اللّٰہَ کَانَ عَلِیًّا کَبِیۡرًا ﴿۳۴﴾', 'مرد عورتوں پر حاکم ہیں اس لئے کہ اللہ نے بعض کو بعض سے افضل بنایا ہے اور اس لئے بھی کہ مرد اپنا مال خرچ کرتے ہیں۔ تو جو نیک بیبیاں ہیں وہ فرمانبردار ہوتی ہیں اور ان کی پیٹھ پیچھے اللہ کی حفاظت میں مال و آبرو کی خبرداری کرتی ہیں اور جن عورتوں کی نسبت تمہیں معلوم ہو کہ سرکشی اور بدخوئی کرنے لگی ہیں تو پہلے ان کو زبانی سمجھاؤ اگر نہ سمجھیں تو پھر ان کے ساتھ سونا ترک کر دو اگر اس پر بھی باز نہ آئیں تو زدوکوب کرو۔ پھر اگر تمہارا کہنا مان لیں تو پھر ان کو ایذا دینے کا کوئی بہانہ مت ڈھونڈو۔ بیشک اللہ بہت اونچا ہے بڑا ہے۔', 'مرد حاکم ہیں عورتوں پر اس واسطے کہ بڑائی دی اللہ نے ایک کو ایک پر اور اس واسطے کہ خرچ کیے انہوں نے اپنے مال [۶۴] پھر جو عورتیں نیک ہیں سو تابعدار ہیں نگہبانی کرتی ہیں پیٹھ پیچھے اللہ کی حفاظت سے [۶۵] اور جن کی بدخوئی کا ڈر ہو تم کو تو ان کو سمجھاؤ اور جدا کرو سونے میں اور مارو [۶۶] پھر اگر کہا مانیں تمہارا تو مت تلاش کرو ان پر راہ الزام کی بیشک اللہ ہے سب سے اوپر بڑا [۶۷]', 'Men are the protectors and maintainers of women, because Allah has made one of them to excel the other, and because they spend (to support them) from their means. Therefore the righteous women are devoutly obedient (to Allah and to their husbands), and guard in the husbands absence what Allah orders them to guard (e.g. their chastity, their husbands property, etc.). As to those women on whose part you see illconduct, admonish them (first), (next), refuse to share their beds, (and last) beat them (lightly, if it is useful), but if they return to obedience, seek not against them means (of annoyance). Surely, Allah is Ever Most High, Most Great.', 'Men are caretakers of women, since Allah has made some of them excel the others, and because of the wealth they have spent. So, the righteous women are obedient, (and) guard (the property and honor of their husbands) in (their) absence with the protection given by Allah. As for women of whom you fear rebellion, convince them, and leave them apart in beds, and beat them. Then, if they obey you, do not seek a way against them. Surely, Allah is the Highest, the Greatest.'),
(528, 4, 35, 6, 3, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ اِنۡ خِفۡتُمۡ شِقَاقَ بَیۡنِہِمَا فَابۡعَثُوۡا حَکَمًا مِّنۡ اَہۡلِہٖ وَ حَکَمًا مِّنۡ اَہۡلِہَا ۚ اِنۡ یُّرِیۡدَاۤ  اِصۡلَاحًا یُّوَفِّقِ اللّٰہُ بَیۡنَہُمَا ؕ اِنَّ اللّٰہَ کَانَ عَلِیۡمًا خَبِیۡرًا ﴿۳۵﴾', 'اور اگر تم لوگوں کو معلوم ہو کہ میاں بیوی میں ان بن ہے تو ایک منصف مرد کے خاندان میں سے اور ایک منصف عورت کے خاندان میں سے مقرر کرو۔ وہ اگر صلح کرا دینی چاہیں گے تو اللہ ان میں موافقت پیدا کر دے گا۔ کچھ شک نہیں کہ اللہ سب کچھ جانتا ہے سب باتوں سے خبردار ہے۔', 'اور اگر تم ڈرو کہ وہ دونوں آپس میں ضد رکھتے ہیں تو کھڑ اکرو ایک منصف مرد والوں میں سے اور ایک منصف عورت والوں میں سے [۶۸] اگر یہ دونوں چاہیں گے کہ صلح کرا دیں تو اللہ موافقت کر دے گا ان دونوں میں بیشک اللہ سب کچھ جاننے والا خبردار ہے [۶۹]', 'If you fear a breach between them twain (the man and his wife), appoint (two) arbitrators, one from his family and the other from hers; if they both wish for peace, Allah will cause their reconciliation. Indeed Allah is Ever AllKnower, WellAcquainted with all things.', 'If you fear a split between them (the spouses), send one arbitrator from his people and one from her people. If they desire to set things right, Allah shall bring about harmony between them. Surely, Allah is All-Knowing, All-Aware'),
(529, 4, 36, 6, 3, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ اعۡبُدُوا  اللّٰہَ وَ لَا تُشۡرِکُوۡا بِہٖ شَیۡئًا وَّ بِالۡوَالِدَیۡنِ  اِحۡسَانًا وَّ بِذِی الۡقُرۡبٰی وَ الۡیَتٰمٰی وَ الۡمَسٰکِیۡنِ وَ الۡجَارِ ذِی الۡقُرۡبٰی وَ الۡجَارِ الۡجُنُبِ وَ الصَّاحِبِ بِالۡجَنۡۢبِ وَ ابۡنِ السَّبِیۡلِ ۙ وَ مَا مَلَکَتۡ اَیۡمَانُکُمۡ ؕ اِنَّ اللّٰہَ لَا یُحِبُّ مَنۡ  کَانَ  مُخۡتَالًا  فَخُوۡرَا ﴿ۙ۳۶﴾', 'اور اللہ ہی کی عبادت کرو اور اس کے ساتھ کسی چیز کو شریک نہ بناؤ اور ماں باپ اور قرابت والوں اور یتیموں اور ناداروں اور رشتہ دار ہمسایوں اور اجنبی ہمسایوں اور پاس بیٹھنے والوں اور مسافروں اور جو لوگ تمہارے قبضے میں ہوں سب کے ساتھ حسن سلوک کرو بیشک اللہ تکبر کرنے والے بڑائی مارنے والے کو دوست نہیں رکھتا۔', 'اور بندگی کرو اللہ کی اور شریک نہ کرو اس کا کسی کو [۷۰] اور ماں باپ کے ساتھ نیکی کرو اور قرابت والوں کے ساتھ اور یتیموں اور فقیروں اور ہمسایہ قریب اور ہمسایہ اجنبی اور پاس بیٹھنے والےاور مسافر کے ساتھ اور اپنے ہاتھ کے مال یعنی غلام باندیوں کے ساتھ بیشک اللہ کو پسند نہیں آتا اترانے والا بڑائی کرنے والا [۷۱]', 'Worship Allah and join none with Him in worship, and do good to parents, kinsfolk, orphans, Al-Masakin (the poor), the neighbour who is near of kin, the neighbour who is a stranger, the companion by your side, the wayfarer (you meet), and those (slaves) whom your right hands possess. Verily, Allah does not like such as are proud and boastful;', 'Worship Allah, and do not associate with Him anything, and be good to parents and to kinsmen and orphans and the needy and the close neighbor and the distant neighbor and the companion at your side and the wayfarer and to those (slaves who are) owned by you. Surely, Allah does not like those who are arrogant, proud,'),
(530, 4, 37, 6, 3, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'ۣالَّذِیۡنَ یَبۡخَلُوۡنَ وَ یَاۡمُرُوۡنَ النَّاسَ بِالۡبُخۡلِ وَ یَکۡتُمُوۡنَ مَاۤ اٰتٰہُمُ اللّٰہُ مِنۡ فَضۡلِہٖ ؕ وَ اَعۡتَدۡنَا لِلۡکٰفِرِیۡنَ  عَذَابًا مُّہِیۡنًا ﴿ۚ۳۷﴾', 'جو خود بھی بخل کریں اور لوگوں کو بھی بخل سکھائیں اور جو مال اللہ نے ان کو اپنے فضل سے عطا فرمایا ہے اسے چھپا چھپا کے رکھیں اور ہم نے کافروں کے لئے ذلت کا عذاب تیار کر رکھا ہے۔', 'جو کہ بخل کرتے ہیں اور سکھاتے ہیں لوگوں کو بخل اور چھپاتے ہیں جو ان کو دیا اللہ نے اپنے فضل سے اور تیار کر رکھا ہے ہم نے کافروں کے لئے عذاب ذلت کا [۷۲]', 'Those who are miserly and enjoin miserliness on other men and hide what Allah has bestowed upon them of His Bounties. And We have prepared for the disbelievers a disgraceful torment.', '-those who are miserly and bid people to be miserly, and conceal what Allah has given them of His grace - and We have prepared for the disbelievers a humiliating punishment,'),
(531, 4, 38, 6, 3, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ الَّذِیۡنَ یُنۡفِقُوۡنَ اَمۡوَالَہُمۡ رِئَآءَ النَّاسِ وَ لَا یُؤۡمِنُوۡنَ بِاللّٰہِ وَ لَا بِالۡیَوۡمِ الۡاٰخِرِ ؕ وَ مَنۡ  یَّکُنِ  الشَّیۡطٰنُ  لَہٗ  قَرِیۡنًا فَسَآءَ  قَرِیۡنًا ﴿۳۸﴾', 'اور جو خرچ بھی کریں تو اللہ کے لئے نہیں بلکہ لوگوں کے دکھانے کو۔ اور ایمان نہ اللہ پر لائیں نہ روز آخر پر اور جس کا ساتھی شیطان ہوا تو کچھ شک نہیں کہ وہ برا ساتھی ہے۔', 'اور وہ لوگ جو کہ خرچ کرتے ہیں اپنے مال لوگوں کے دکھانے کو اور ایمان نہیں لاتے اللہ پر اور نہ قیامت کے دن پر اور جس کا ساتھی ہوا شیطان تو وہ بہت برا ساتھی ہے [۷۳]', 'And (also) those who spend of their substance to be seen of men, and believe not in Allah and the Last Day (they are the friends of Shaitan (Satan)), and whoever takes Shaitan (Satan) as an intimate; then what a dreadful intimate he has!', 'and (for) those who spend their wealth only to show people, and do not believe in Allah and the Last Day. Anyone for whom Satan is companion, evil he is as a companion.'),
(532, 4, 39, 6, 3, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ مَاذَا عَلَیۡہِمۡ لَوۡ اٰمَنُوۡا بِاللّٰہِ وَ الۡیَوۡمِ الۡاٰخِرِ وَ اَنۡفَقُوۡا مِمَّا رَزَقَہُمُ اللّٰہُ ؕ وَ کَانَ اللّٰہُ  بِہِمۡ  عَلِیۡمًا ﴿۳۹﴾', 'اور اگر یہ لوگ اللہ پر اور روز قیامت پر ایمان لاتے اور جو کچھ اللہ نے ان کو دیا تھا اس میں سے خرچ کرتے۔ تو ان پر کیا مصیبت آ پڑتی اور اللہ ان کو خوب جانتا ہے۔', 'اور کیا نقصان تھا ان کا اگر ایمان لاتے اللہ پر اور قیامت کے دن پر اور خرچ کرتے اللہ کے دیے ہوئے میں سے اور اللہ کو ان کی خوب خبر ہے [۷۴]', 'And what loss have they if they had believed in Allah and in the Last Day, and they spend out of what Allah has given them for sustenance? And Allah is Ever AllKnower of them.', 'What harm was there for them if they had believed in Allah and the Last Day, and spent out of what Allah had given them. Allah knows all about them.'),
(533, 4, 40, 6, 3, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اِنَّ اللّٰہَ لَا یَظۡلِمُ مِثۡقَالَ ذَرَّۃٍ ۚ وَ اِنۡ تَکُ حَسَنَۃً  یُّضٰعِفۡہَا وَ یُؤۡتِ مِنۡ لَّدُنۡہُ  اَجۡرًا عَظِیۡمًا ﴿۴۰﴾', 'اللہ کسی کی ذرا بھر بھی حق تلفی نہیں کرتا اور اگر کسی نے نیکی کی ہو گی تو اس کو کئ گنا کر دے گا۔ اور اپنے ہاں سے اجر عظیم بخشے گا۔', 'بیشک اللہ حق نہیں رکھتا کسی کا ایک ذرہ برابر اور اگر نیکی ہو تو اس کو دونا کر دیتا ہے اور دیتا ہے اپنے پاس سے بڑا ثواب [۷۵]', 'Surely! Allah wrongs not even of the weight of an atom (or a small ant), but if there is any good (done), He doubles it, and gives from Him a great reward.', 'Surely, Allah does not wrong (anyone), even to the measure of a particle. If it is a good deed, He multiplies it, and gives a great reward out of His Own pleasure.'),
(534, 4, 41, 6, 3, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'فَکَیۡفَ اِذَا جِئۡنَا مِنۡ کُلِّ اُمَّۃٍۭ بِشَہِیۡدٍ وَّ جِئۡنَا بِکَ عَلٰی ہٰۤؤُلَآءِ شَہِیۡدًا ﴿ؕ؃۴۱﴾', 'بھلا اس دن کیا حال ہو گا جب ہم ہر امت میں سے احوال بتانے والے کو بلائیں گے اور تم کو اے نبی ﷺ ان لوگوں کا حال بتانے کو بطور گواہ طلب کریں گے۔', 'پھر کیا حال ہو گا جب بلاویں گے ہم ہر امت میں سے احوال کہنے والا اور بلاویں گے تجھ کو ان لوگوں پر احوال بتانے والا [۷۶]', 'How (will it be) then, when We bring from each nation a witness and We bring you (O Muhammad SAW) as a witness against these people?', 'Then, how (awful a spectacle) would it be when We shall bring a witness from every community, and shall bring you over them as a witness.'),
(535, 4, 42, 6, 3, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'یَوۡمَئِذٍ یَّوَدُّ الَّذِیۡنَ کَفَرُوۡا وَ عَصَوُا الرَّسُوۡلَ لَوۡ تُسَوّٰی بِہِمُ الۡاَرۡضُ ؕ وَ لَا یَکۡتُمُوۡنَ اللّٰہَ  حَدِیۡثًا ﴿٪۴۲﴾', 'اس روز کافر اور پیغمبر کے نافرمان آرزو کریں گے کہ کاش ان کو دھنسا کر زمین برابر کر دی جاتی۔ اور وہ اللہ سے کوئی بات چھپا نہیں سکیں گے۔', 'اس دن آرزو کریں گے وہ لوگ جو کافر ہوئے تھے اور رسول کی نافرمانی کی تھی کہ برابر ہو جاویں زمین کے اور نہ چھپا سکیں گے اللہ سے کوئی بات [۷۷]', 'On that day those who disbelieved and disobeyed the Messenger (Muhammad SAW) will wish that they were buried in the earth, but they will never be able to hide a single fact from Allah.', 'On that Day, those who have disbelieved and disobeyed the Messenger shall wish that the earth were leveled with them. They shall not (be able to) conceal anything from Allah.'),
(536, 4, 43, 7, 4, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَقۡرَبُوا الصَّلٰوۃَ وَ اَنۡتُمۡ سُکٰرٰی حَتّٰی تَعۡلَمُوۡا مَا تَقُوۡلُوۡنَ وَ لَا جُنُبًا اِلَّا عَابِرِیۡ سَبِیۡلٍ حَتّٰی تَغۡتَسِلُوۡا ؕ وَ اِنۡ کُنۡتُمۡ مَّرۡضٰۤی اَوۡ عَلٰی سَفَرٍ اَوۡ جَآءَ اَحَدٌ مِّنۡکُمۡ مِّنَ الۡغَآئِطِ اَوۡ لٰمَسۡتُمُ النِّسَآءَ فَلَمۡ تَجِدُوۡا مَآءً فَتَیَمَّمُوۡا صَعِیۡدًا طَیِّبًا فَامۡسَحُوۡا بِوُجُوۡہِکُمۡ وَ اَیۡدِیۡکُمۡ ؕ اِنَّ اللّٰہَ  کَانَ عَفُوًّا غَفُوۡرًا ﴿۴۳﴾', 'مومنو! جب تم نشے کی حالت میں ہو تو جب تک ان الفاظ کو جو منہ سے کہو سمجھنے نہ لگو۔ نماز کے پاس نہ جاؤ۔ اور جنابت کی حالت میں بھی نماز کے پاس نہ جاؤ یہاں تک کہ کہ غسل کر لو۔ ہاں اگر بحالت سفر رستے چلے جا رہے ہو اور پانی نہ ملنے کے سبب غسل نہ کر سکو تو تیمم کر کے نماز پڑھ لو اور اگر تم بیمار ہو یا سفر میں ہو یا کوئی تم میں سے بیت الخلاء سے ہو کر آیا ہو یا تم نے عورتوں سے مقاربت کی ہو اور تمہیں پانی نہ ملے تو پاک مٹی لو اور منہ اور ہاتھوں کا مسحح کر کے تیمم کر لو۔ بیشک اللہ معاف کرنے والا ہے بخشنے والا ہے۔', 'اے ایمان والو نزدیک نہ جاؤ نماز کے جس وقت کہ تم نشہ میں ہو یہاں تک کہ سمجھنے لگو جو کہتے ہو اور نہ اس وقت کہ غسل کی حاجت ہو مگر راہ چلتے ہوئے یہاں تک کہ غسل کر لو [۷۸] اور اگر تم مریض ہو یا سفر میں یا آیا ہے کوئی شخص جائے ضرور سے یا پاس گئے ہو عورتوں کے پھر نہ ملا تم کو پانی تو ارادہ کرو زمین پاک کا پھر ملو اپنے منہ کو اور ہاتھوں کو [۷۹] بیشک اللہ ہے معاف کرنے والا بخشنے والا [۸۰]', 'O you who believe! Approach not AsSalat (the prayer) when you are in a drunken state until you know (the meaning) of what you utter, nor when you are in a state of Janaba, (i.e. in a state of sexual impurity and have not yet taken a bath) except when travelling on the road (without enough water, or just passing through a mosque), till you wash your whole body. And if you are ill, or on a journey, or one of you comes after answering the call of nature, or you have been in contact with women (by sexual relations) and you find no water, perform Tayammum with clean earth and rub therewith your faces and hands (Tayammum). Truly, Allah is Ever OftPardoning, OftForgiving.', 'O you who believe! Do not go near Salāh when you are intoxicated, until you know what you say, nor in a state of ‘major impurity’.,-save when you are traversing a way-until you take a bath. If you are sick, or in travel, or if one of you has come after relieving himself, or you have had contact with women, and you find no water, go for some clean dust and wipe your faces and hands (with it). Surely, Allah is Most-Pardoning, Most-Forgiving.'),
(537, 4, 44, 7, 4, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اَلَمۡ تَرَ اِلَی الَّذِیۡنَ اُوۡتُوۡا نَصِیۡبًا مِّنَ الۡکِتٰبِ یَشۡتَرُوۡنَ الضَّلٰلَۃَ وَ یُرِیۡدُوۡنَ اَنۡ تَضِلُّوا السَّبِیۡلَ ﴿ؕ۴۴﴾', 'بھلا تم نے ان لوگوں کو نہیں دیکھا جنکو کتاب سے حصہ دیا گیا تھا کہ وہ گمراہی کو خریدتے ہیں اور چاہتے ہیں کہ تم بھی رستے سے بھٹک جاؤ۔', 'کیا تو نے نہ دیکھا ان کو جن کو ملا ہے کچھ حصہ کتاب سے خرید کرتے ہیں گمراہی اور چاہتے ہیں کہ تم بھی بہک جاؤ اپنی راہ سے', 'Have you not seen those who were given a portion of the book (the Jews), purchasing the wrong path, and wish that you should go astray from the Right Path.', 'Have you not observed those who have been given a share from the Book? They buy misguidance and wish that you (too) lose the way.'),
(538, 4, 45, 7, 4, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ اللّٰہُ اَعۡلَمُ بِاَعۡدَآئِکُمۡ ؕ وَ کَفٰی بِاللّٰہِ وَلِیًّا ٭۫  وَّ کَفٰی  بِاللّٰہِ نَصِیۡرًا ﴿۴۵﴾', 'اور اللہ تمہارے دشمنوں سے خوب واقف ہے۔ اور اللہ ہی کافی کارساز ہے اور اللہ ہی کافی مددگار ہے۔', 'اور اللہ خوب جانتا ہے تمہارے دشمنوں کو اور اللہ کافی ہے حمایتی اور اللہ کافی ہے مددگار [۸۱]', 'Allah has full knowledge of your enemies, and Allah is Sufficient as a Walee (Protector), and Allah is Sufficient as a Helper.', 'But Allah knows your enemies very well. Allah is enough as a friend, and Allah is enough as a supporter.'),
(539, 4, 46, 7, 4, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'مِنَ الَّذِیۡنَ ہَادُوۡا یُحَرِّفُوۡنَ الۡکَلِمَ  عَنۡ مَّوَاضِعِہٖ وَ یَقُوۡلُوۡنَ سَمِعۡنَا وَ عَصَیۡنَا وَ اسۡمَعۡ غَیۡرَ مُسۡمَعٍ وَّ رَاعِنَا لَـیًّۢا بِاَلۡسِنَتِہِمۡ وَ طَعۡنًا فِی الدِّیۡنِ ؕ وَ لَوۡ اَنَّہُمۡ قَالُوۡا سَمِعۡنَا وَ اَطَعۡنَا وَ اسۡمَعۡ وَ انۡظُرۡنَا لَکَانَ خَیۡرًا لَّہُمۡ وَ اَقۡوَمَ ۙ وَ لٰکِنۡ لَّعَنَہُمُ اللّٰہُ بِکُفۡرِہِمۡ  فَلَا  یُؤۡمِنُوۡنَ  اِلَّا  قَلِیۡلًا ﴿۴۶﴾', 'اور یہ جو یہودی ہیں ان میں کچھ لوگ ایسے بھی ہیں کہ کتاب اللہ کے کلمات کو ان کے مقامات سے ہٹا دیتے ہیں اور کہتے ہیں کہ ہم نے سن لیا اور نہیں مانا اور کہتے ہیں سنو نہ سنوائے جاؤ اور زبان کو مروڑ کر اور دین میں طعن کی راہ سے تم سے گفتگو کے وقت راعنا کہتے ہیں۔ اور اگر یوں کہتے کہ ہم نے سن لیا اور مان لیا اور صرف اسمع اور راعنا کی جگہ انظرنا کہتے تو ان کے حق میں بہتر ہوتا اور بات بھی بہت درست ہوتی لیکن اللہ نے ان کے کفر کے سبب ان پر لعنت کر رکھی ہے تو یہ کچھ تھوڑے ہی ایمان لاتے ہیں۔', 'بعضے لوگ یہودی پھیرتے ہیں بات کو اس کے ٹھکانے سے [۸۲] اور کہتے ہیں ہم نے سنا اور نہ مانا [۸۳] اور کہتے ہیں کہ سن نہ سنایا جائیو [۸۴] اور کہتے ہیں راعنا [۸۵] موڑ کر اپنی زبان کو اور عیب لگانے کو دین میں [۸۶] اور اگر وہ کہتے ہم نے سنا اور مانا اور سن اور ہم پر نظر کر تو بہتر ہوتا ان کے حق میں اور درست لیکن لعنت کی ان پر اللہ نے ان کے کفر کے سبب سو وہ ایمان نہیں لاتے مگر بہت کم [۸۷]', 'Among those who are Jews, there are some who displace words from (their) right places and say: \"We hear your word (O Muhammad SAW ) and disobey,\" and \"Hear and let you (O Muhammad SAW) hear nothing.\" And Raina with a twist of their tongues and as a mockery of the religion (Islam). And if only they had said: \"We hear and obey\", and \"Do make us understand,\" it would have been better for them, and more proper, but Allah has cursed them for their disbelief, so they believe not except a few.', 'Among the Jews there are some who distort the words against their contexts, and say, “We hear and disobey,” and “Hear. May you not be made to hear,” and “Rā‘inā”, twisting their tongues and maligning the Faith.If they had said, “We hear and obey,” and “Hear,” and “Look after us,” it would have been better for them, and more proper, but Allah has cast His curse on them due to their disbelief. So, they do not believe except a few.'),
(540, 4, 47, 7, 4, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'یٰۤاَیُّہَا الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ اٰمِنُوۡا بِمَا نَزَّلۡنَا مُصَدِّقًا لِّمَا مَعَکُمۡ مِّنۡ قَبۡلِ اَنۡ نَّطۡمِسَ وُجُوۡہًا فَنَرُدَّہَا عَلٰۤی اَدۡبَارِہَاۤ اَوۡ نَلۡعَنَہُمۡ کَمَا لَعَنَّاۤ اَصۡحٰبَ السَّبۡتِ ؕ وَ کَانَ اَمۡرُ اللّٰہِ مَفۡعُوۡلًا ﴿۴۷﴾', 'اے کتاب والو! قبل اس کے کہ ہم کچھ چہروں کو مٹا دیں اور پھر ان کی پیٹھ کی طرف پھیر دیں یا ان پر اس طرح لعنت کریں جس طرح ہفتے والوں پر لعنت کی تھی ہماری نازل فرمائی ہوئی کتاب پر جو تمہاری کتاب کی بھی تصدیق کرتی ہے ایمان لے آؤ۔ اور اللہ نے جو حکم فرمایا سو سمجھ لو کہ ہو چکا۔', 'اے کتاب  والو ایمان لاؤ اس پر جو ہم نے نازل کیا تصدیق کرتا ہے اس کتاب کی جو تمہارے پاس ہے پہلے اس سے کہ ہم مٹا ڈالیں بہت سے چہروں کو پھر الٹ دیں انکو پیٹھ کی طرف یا لعنت کریں ان پر جیسے ہم نےلعنت کی ہفتہ کے دن والوں پر اور اللہ کا حکم تو ہو کر ہی رہتا ہے [۸۸]', 'O you who have been given the Scripture (Jews and Christians)! Believe in what We have revealed (to Muhammad SAW) confirming what is (already) with you, before We efface faces (by making them like the back of necks; without nose, mouth, eyes, etc.) and turn them hindwards, or curse them as We cursed the Sabbathbreakers. And the Commandment of Allah is always executed.', 'O you who have been given the Book, believe in what We have revealed confirming what is with you, before We rub off faces and turn them shaped like their backs, or lay a curse upon them, as We cursed the People of the Sabbath. Whatever Allah orders is destined to occur.'),
(541, 4, 48, 7, 4, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اِنَّ اللّٰہَ لَا یَغۡفِرُ اَنۡ یُّشۡرَکَ بِہٖ وَ یَغۡفِرُ  مَا دُوۡنَ ذٰلِکَ لِمَنۡ یَّشَآءُ ۚ وَ مَنۡ یُّشۡرِکۡ بِاللّٰہِ فَقَدِ افۡتَرٰۤی  اِثۡمًا عَظِیۡمًا ﴿۴۸﴾', 'اللہ اس گناہ کو نہیں بخشے گا کہ کسی کو اس کا شریک بنایا جائے اور اس کے سوا اور گناہ جس کو چاہے معاف کر دے۔ اور جس نے اللہ کا شریک مقرر کیا اس نے بڑا بہتان باندھا۔', 'بیشک اللہ نہیں بخشتا اس کو جو اس کا شریک کرے اور بخشتا ہے اس سے نیچے کے گناہ جس کے چاہے اور جس نے شریک ٹھہرایا اللہ کا اس نے بڑا طوفان باندھا [۸۹]', 'Verily, Allah forgives not that partners should be set up with him in worship, but He forgives except that (anything else) to whom He pleases, and whoever sets up partners with Allah in worship, he has indeed invented a tremendous sin.', 'Surely, Allah does not forgive that a partner is ascribed to Him, and He forgives anything short of that for whomsoever He wills. Whoever ascribes a partner to Allah commits a terrible sin.'),
(542, 4, 49, 7, 4, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اَلَمۡ تَرَ  اِلَی الَّذِیۡنَ یُزَکُّوۡنَ اَنۡفُسَہُمۡ ؕ بَلِ اللّٰہُ یُزَکِّیۡ مَنۡ یَّشَآءُ وَ لَا یُظۡلَمُوۡنَ فَتِیۡلًا ﴿۴۹﴾', 'کیا تم نے ان لوگوں کو نہیں دیکھا جو اپنے آپ کو پاکیزہ کہتے ہیں نہیں بلکہ اللہ ہی جسکو چاہتا ہے پاکیزہ کرتا ہے۔ اور ان پر دھاگے برابر بھی ظلم نہیں ہو گا۔', 'کیا تو نے نہ دیکھا ان کو جو اپنے آپ کو پاکیزہ کہتے ہیں بلکہ اللہ ہی پاکیزہ کرتا ہے جس کو چاہے اور ان پر ظلم نہ ہو گا تاگے برابر [۹۰]', 'Have you not seen those who claim sanctity for themselves. Nay - but Allah sanctifies whom He pleases, and they will not be dealt with injustice even equal to the extent of a Fatila (A scalish thread in the long slit of a datestone).', 'Have you not seen those who claim sanctity for themselves? In fact, Allah sanctifies whom He wills, and they shall not be wronged even to the measure of a thread of a date-stone.'),
(543, 4, 50, 7, 4, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اُنۡظُرۡ کَیۡفَ یَفۡتَرُوۡنَ عَلَی اللّٰہِ الۡکَذِبَ ؕ وَ کَفٰی بِہٖۤ   اِثۡمًا مُّبِیۡنًا ﴿٪۵۰﴾', 'دیکھو یہ اللہ پر کیسا جھوٹ طوفان باندھتے ہیں۔ اور یہی کھلا گناہ کافی ہے۔', 'دیکھ کیسا باندھتے ہیں اللہ پر جھوٹ اور کافی ہے یہی گناہ صریح [۹۱]', 'Look, how they invent a lie against Allah, and enough is that as a manifest sin.', 'See how they fabricate a lie against Allah, and it is enough to be an open sin.'),
(544, 4, 51, 8, 5, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اَلَمۡ تَرَ اِلَی الَّذِیۡنَ اُوۡتُوۡا نَصِیۡبًا مِّنَ الۡکِتٰبِ یُؤۡمِنُوۡنَ بِالۡجِبۡتِ وَ الطَّاغُوۡتِ وَ یَقُوۡلُوۡنَ لِلَّذِیۡنَ کَفَرُوۡا ہٰۤؤُلَآءِ اَہۡدٰی مِنَ الَّذِیۡنَ اٰمَنُوۡا سَبِیۡلًا ﴿۵۱﴾', 'بھلا تم نے ان لوگوں کو نہیں دیکھا جنکو کتاب سے حصہ دیا گیا ہے کہ بتوں اور شیطان کو مانتے ہیں اور کفار کے بارے میں کہتے ہیں کہ یہ لوگ مومنوں کی نسبت سیدھے رستے پر ہیں۔', 'کیا تو نے نہ دیکھا ان کو جن کو ملا ہے کچھ حصہ کتاب کا جو مانتے ہیں بتوں کو اور شیطان کو اور کہتے ہیں کافروں کو کہ یہ لوگ زیادہ راہ راست پر ہیں مسلمانوں سے [۹۲]', 'Have you not seen those who were given a portion of the Scripture? They believe in Jibt and Taghoot and say to the disbelievers that they are better guided as regards the way than the believers (Muslims).', 'Have you not seen those who have been given a share from the Book? They believe in Jibt and Tāghūt and say concerning those who disbelieve, “They are better guided in their way than those who believe.”'),
(545, 4, 52, 8, 5, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اُولٰٓئِکَ الَّذِیۡنَ لَعَنَہُمُ اللّٰہُ ؕ وَ مَنۡ یَّلۡعَنِ اللّٰہُ  فَلَنۡ تَجِدَ  لَہٗ  نَصِیۡرًا ﴿ؕ۵۲﴾', 'یہی لوگ ہیں جن پر اللہ نے لعنت کی ہے۔ اور جس پر اللہ لعنت کرے تو تم اس کا کسی کو مددگار نہ پاؤ گے۔', 'یہ وہی ہیں جن پر لعنت کی ہے اللہ نے اور جس پر لعنت کرے اللہ نہ پاوے گا تو اس کا کوئی مددگار [۹۳]', 'They are those whom Allah has cursed, and he whom Allah curses, you will not find for him (any) helper,', 'Those are the ones whom Allah has cursed, and the one whom Allah has cursed, for him you shall find no helper.'),
(546, 4, 53, 8, 5, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اَمۡ لَہُمۡ نَصِیۡبٌ مِّنَ الۡمُلۡکِ فَاِذًا لَّا یُؤۡتُوۡنَ النَّاسَ نَقِیۡرًا ﴿ۙ۵۳﴾', 'کیا انکے پاس بادشاہی کا کچھ حصہ ہے اس صورت میں تو یہ لوگوں کو تِل برابر بھی نہ دیں گے۔', 'کیا ان کا کچھ حصہ ہےسلطنت میں پھر تو یہ نہ دیں گے لوگوں کو ایک تل برابر [۹۴]', 'Or have they a share in the dominion? Then in that case they would not give mankind even a Naqeera (speck on the back of a date-stone).', 'Is it that they have a share in the kingdom? If so, they would give nothing to the people, not even to the measure of a tiny pit on the back of a date-stone?'),
(547, 4, 54, 8, 5, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اَمۡ یَحۡسُدُوۡنَ النَّاسَ عَلٰی مَاۤ اٰتٰہُمُ اللّٰہُ مِنۡ فَضۡلِہٖ ۚ فَقَدۡ اٰتَیۡنَاۤ اٰلَ  اِبۡرٰہِیۡمَ الۡکِتٰبَ وَ الۡحِکۡمَۃَ وَ اٰتَیۡنٰہُمۡ مُّلۡکًا عَظِیۡمًا ﴿۵۴﴾', 'یا جو اللہ نے لوگوں کو اپنے فضل سے دے رکھا ہے اس کا حسد کرتے ہیں تو ہم نے خاندان ابراہیم کو کتاب اور دانائی عنایت فرمائی تھی اور سلطنت عظیم بھی بخشی تھی۔', 'یا حسد کرتے ہیں لوگوں کا اس پر جو دیا ہے انکو اللہ نے اپنے فضل سےسو ہم نے تو دی ہے ابراہیم کے خاندان میں کتاب اور علم اور انکو دی ہے ہم نے بڑی سلطنت [۹۵]', 'Or do they envy men (Muhammad SAW and his followers) for what Allah has given them of His Bounty? Then We had already given the family of Ibrahim (Abraham) the Book and AlHikmah (AsSunnah - Divine Inspiration to those Prophets not written in the form of a book), and conferred upon them a great kingdom.', 'Or, is it that they are jealous of people over what Allah has given them of His bounty, while We have given to the House of Ibrāhīm the Book and the wisdom, and We have given to them a great kingdom?'),
(548, 4, 55, 8, 5, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'فَمِنۡہُمۡ مَّنۡ اٰمَنَ بِہٖ وَ مِنۡہُمۡ مَّنۡ صَدَّ عَنۡہُ ؕ وَ کَفٰی  بِجَہَنَّمَ  سَعِیۡرًا ﴿۵۵﴾', 'پھر لوگوں میں سے کسی نے تو اس کتاب کو مانا اور کوئی اس سے رکا رہا تو ان نہ ماننے والوں کے لئے دوزخ کی جلتی ہوئی آگ کافی ہے۔', 'پھر ان میں سے کسی نے اس کو مانا اور کوئی اس سے ہٹا رہا اور کافی ہے دوزخ کی بھڑکتی آگ [۹۶]', 'Of them were (some) who believed in him (Muhammad SAW), and of them were (some) who averted their faces from him (Muhammad SAW); and enough is Hell for burning (them).', 'So, there were some among them who believed in it, and there were others among them who turned away from it. Enough (for the latter) is Jahannam, a fire ablaze!'),
(549, 4, 56, 8, 5, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اِنَّ الَّذِیۡنَ کَفَرُوۡا بِاٰیٰتِنَا سَوۡفَ نُصۡلِیۡہِمۡ نَارًا ؕ کُلَّمَا نَضِجَتۡ جُلُوۡدُہُمۡ بَدَّلۡنٰہُمۡ جُلُوۡدًا غَیۡرَہَا لِیَذُوۡقُوا الۡعَذَابَ ؕ اِنَّ اللّٰہَ کَانَ عَزِیۡزًا حَکِیۡمًا ﴿۵۶﴾', 'جن لوگوں نے ہماری آیتوں سے کفر کیا ان کو ہم عنقریب آگ میں داخل کریں گے۔ جب کبھی ان کی کھالیں گل جائیں گی تو ہم انکو اور کھالیں بدل کر دیں گے تاکہ ہمیشہ عذاب کا مزہ چکھتے رہیں۔ بیشک اللہ غالب ہے حکمت والا ہے۔', 'بیشک جو منکر ہوئے ہماری آیتوں سے ان کو ہم ڈالیں گے آگ میں [۹۷] جس وقت جل جائے گی کھال ان کی تو ہم بدل دیویں گے ان کو اور کھال تاکہ چکھتے رہیں عذاب [۹۸] بیشک اللہ ہے زبردست حکمت والا [۹۹]', 'Surely! Those who disbelieved in Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) We shall burn them in Fire. As often as their skins are roasted through, We shall change them for other skins that they may taste the punishment. Truly, Allah is Ever Most Powerful, AllWise.', 'Those who have disbelieved in Our verses, We shall certainly make them enter a fire. Whenever their skins are burnt out, We shall give them other skins in their place, so that they may taste the punishment. Surely, Allah is All-Mighty, All-Wise.'),
(550, 4, 57, 8, 5, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ سَنُدۡخِلُہُمۡ جَنّٰتٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَاۤ  اَبَدًا ؕ لَہُمۡ  فِیۡہَاۤ اَزۡوَاجٌ مُّطَہَّرَۃٌ ۫ وَّ نُدۡخِلُہُمۡ ظِلًّا ظَلِیۡلًا ﴿۵۷﴾', 'اور جو لوگ ایمان لائے اور عمل نیک کرتے رہے ان کو ہم بہشتوں میں داخل کریں گے جن کے نیچے نہریں بہ رہی ہیں وہ ان میں ہمیشہ ہمیشہ رہیں گے۔ وہاں ان کے لئے پاک بیبیاں ہیں۔ اور ان کو ہم گھنے سائے میں داخل کریں گے۔', 'اور جو لوگ ایمان لائے اور کام کئے نیک البتہ انکو ہم داخل کریں گے باغوں میں جن کے نیچے بہتی ہیں نہریں رہا کریں ان میں ہمیشہ ان کے لئے وہاں عورتیں ہیں ستھری اور انکو ہم داخل کریں گے گھنی چھاؤں میں [۱۰۰]', 'But those who believe (in the Oneness of Allah - Islamic Monotheism) and do deeds of righteousness, We shall admit them to Gardens under which rivers flow (Paradise), abiding therein forever. Therein they shall have Azwajun Mutahharatun (purified mates or wives (having no menses, stools, urine, etc.)) and We shall admit them to shades wide and ever deepening (Paradise).', 'As for those who have believed and have done good deeds, We shall admit them to gardens beneath which rivers flow, where they will live forever. For them there are wives purified. We shall admit them to an umbrageous shade.'),
(551, 4, 58, 8, 5, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اِنَّ اللّٰہَ یَاۡمُرُکُمۡ اَنۡ تُؤَدُّوا الۡاَمٰنٰتِ اِلٰۤی اَہۡلِہَا ۙ وَ اِذَا حَکَمۡتُمۡ بَیۡنَ النَّاسِ اَنۡ تَحۡکُمُوۡا بِالۡعَدۡلِ ؕ اِنَّ اللّٰہَ نِعِمَّا یَعِظُکُمۡ بِہٖ ؕ اِنَّ اللّٰہَ کَانَ سَمِیۡعًۢا بَصِیۡرًا ﴿۵۸﴾', 'مسلمانو اللہ تم کو حکم دیتا ہے کہ امانت والوں کی امانتیں ان کے حوالے کر دیا کرو۔ اور جب لوگوں میں فیصلہ کرنے لگو تو انصاف سے فیصلہ کیا کرو۔ اللہ تمہیں بہت خوب نصیحت کرتا ہے۔ بیشک اللہ سنتا ہے دیکھتا ہے۔', 'بیشک اللہ تم کو فرماتا ہے کہ پہنچا دو امانتیں امانت والوں کو اور جب فیصلہ کرنے لگو لوگوں میں تو فیصلہ کرو انصاف سے [۱۰۱] اللہ اچھی نصیحت کرتا ہے تم کو بیشک اللہ ہے سننے والا دیکھنے والا [۱۰۲]', 'Verily! Allah commands that you should render back the trusts to those, to whom they are due; and that when you judge between men, you judge with justice. Verily, how excellent is the teaching which He (Allah) gives you! Truly, Allah is Ever AllHearer, AllSeer.', 'Surely, Allah commands you to deliver trusts to those entitled to them, and that, when you judge between people, judge with justice. Surely, excellent is the exhortation Allah gives you. Surely, Allah is All-Hearing, All-Seeing.'),
(552, 4, 59, 8, 5, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اَطِیۡعُوا اللّٰہَ وَ اَطِیۡعُوا الرَّسُوۡلَ وَ اُولِی الۡاَمۡرِ مِنۡکُمۡ ۚ فَاِنۡ تَنَازَعۡتُمۡ فِیۡ شَیۡءٍ فَرُدُّوۡہُ اِلَی اللّٰہِ وَ الرَّسُوۡلِ  اِنۡ کُنۡتُمۡ تُؤۡمِنُوۡنَ بِاللّٰہِ وَ الۡیَوۡمِ الۡاٰخِرِ ؕ ذٰلِکَ خَیۡرٌ  وَّ  اَحۡسَنُ  تَاۡوِیۡلًا ﴿٪۵۹﴾', 'مومنو! اللہ اور اس کے رسول کی فرمانبرداری کرو اور جو تم میں سے صاحب حکومت ہیں ان کی بھی۔  پھر اگر کسی بات میں تم میں اختلاف واقع ہو تو اگر اللہ اور روز آخر پر ایمان رکھتے ہو تو اس میں اللہ اور اس کے رسول کے حکم کی طرف رجوع کرو۔ یہ بہت اچھی بات ہے اور اس کا انجام بھی اچھا ہے۔', 'اے ایمان والو حکم مانو اللہ کا اور حکم مانو رسول کا اور حاکموں کا جو تم میں سے ہوں [۱۰۳] پھر اگر جھگڑ پڑو کسی چیز میں تو اس کو رجوع کرو طرف اللہ کے اور رسول کے اگر یقین رکھتے ہو اللہ پر اور قیامت کے دن پر [۱۰۴] یہ بات اچھی ہے اور بہت بہتر ہے اس کا انجام [۱۰۵]', 'O you who believe! Obey Allah and obey the Messenger (Muhammad SAW), and those of you (Muslims) who are in authority. (And) if you differ in anything amongst yourselves, refer it to Allah and His Messenger (SAW), if you believe in Allah and in the Last Day. That is better and more suitable for final determination.', 'O you who believe, obey Allah and obey the Messenger and those in authority among you. Then, if you quarrel about something, revert it back to Allah and the Messenger, if you believe in Allah and the Last Day. That is good, and the best at the end.'),
(553, 4, 60, 9, 6, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اَلَمۡ تَرَ  اِلَی الَّذِیۡنَ یَزۡعُمُوۡنَ اَنَّہُمۡ اٰمَنُوۡا بِمَاۤ  اُنۡزِلَ اِلَیۡکَ وَ مَاۤ  اُنۡزِلَ مِنۡ قَبۡلِکَ یُرِیۡدُوۡنَ اَنۡ یَّتَحَاکَمُوۡۤا اِلَی الطَّاغُوۡتِ وَ قَدۡ اُمِرُوۡۤا اَنۡ یَّکۡفُرُوۡا بِہٖ ؕ وَ یُرِیۡدُ الشَّیۡطٰنُ اَنۡ یُّضِلَّہُمۡ ضَلٰلًۢا بَعِیۡدًا ﴿۶۰﴾', 'کیا تم نے ان لوگوں کو نہیں دیکھا جو دعوٰی تو یہ کرتے ہیں کہ جو کتاب تم پر نازل ہوئی اور جو کتابیں تم سے پہلے نازل ہوئیں ان سب پر ایمان رکھتے ہیں۔ اور چاہتے یہ ہیں کہ اپنا مقدمہ اللہ کے باغی کے پاس لیجا کر فیصل کرائیں حالانکہ ان کو حکم دیا گیا تھا کہ اس کو نہ مانیں اور شیطان تو یہ چاہتا ہے کہ انکو بہکا کر رستے سے دور ڈال دے۔', 'کیا تو نے نہ دیکھا ان کو جو دعویٰ کرتے ہیں کہ ایمان لائے ہیں اس پر جو اترا تیری طرف اور جو اترا تجھ سے پہلے چاہتے ہیں کہ قضیہ لے جائیں شیطان کی طرف اور حکم ہو چکا ہے انکو کہ اس کو نہ مانیں اور چاہتا ہےشیطان کہ ان کو بہلا کر دور جا ڈالے [۱۰۶]', 'Have you seen those (hyprocrites) who claim that they believe in that which has been sent down to you, and that which was sent down before you, and they wish to go for judgement (in their disputes) to the Taghoot (false judges, etc.) while they have been ordered to reject them. But Shaitan (Satan) wishes to lead them far astray.', 'Have you not seen those who claim that they have believed in what was revealed to you and what was revealed before you? They want to take their disputes to the Tāghūt, while they were ordered to reject it. Satan wants to mislead them to a remote wrong way.'),
(554, 4, 61, 9, 6, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ  اِذَا قِیۡلَ لَہُمۡ تَعَالَوۡا اِلٰی مَاۤ  اَنۡزَلَ اللّٰہُ وَ اِلَی الرَّسُوۡلِ رَاَیۡتَ الۡمُنٰفِقِیۡنَ یَصُدُّوۡنَ عَنۡکَ  صُدُوۡدًا ﴿ۚ۶۱﴾', 'اور جب ان سے کہا جاتا ہے کہ جو حکم اللہ نے نازل فرمایا اس کی طرف رجوع کرو اور پیغمبر کی طرف آؤ تو تم منافقوں کو دیکھتے ہو کہ تم سے گریز کرتے اور رکے جاتے ہیں۔', 'اور جب ان کو کہے کہ آؤ اللہ کے حکم کی طرف جو اس نے اتارا اور رسول کی طرف تو دیکھے تو منافقوں کو کہ ہٹتے ہیں تجھ سے رک کر [۱۰۷]', 'And when it is said to them: \"Come to what Allah has sent down and to the Messenger (Muhammad SAW),\" you (Muhammad SAW) see the hypocrites turn away from you (Muhammad SAW) with aversion.', 'When it is said to them, “Come to what Allah has revealed and to the Messenger,” you will see the hypocrites turning away from you in aversion.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(555, 4, 62, 9, 6, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'فَکَیۡفَ اِذَاۤ  اَصَابَتۡہُمۡ مُّصِیۡبَۃٌۢ بِمَا قَدَّمَتۡ اَیۡدِیۡہِمۡ ثُمَّ جَآءُوۡکَ یَحۡلِفُوۡنَ ٭ۖ بِاللّٰہِ  اِنۡ اَرَدۡنَاۤ اِلَّاۤ اِحۡسَانًا وَّ تَوۡفِیۡقًا ﴿۶۲﴾', 'پھر کیسی ندامت کی بات ہے کہ جب ان کے اعمال کی شامت سے ان پر کوئی مصیبت واقع ہوتی ہے تو تمہارے پاس بھاگے آتے ہیں اور قسمیں کھاتے ہیں کہ واللہ ہمارا مقصود تو بھلائی اور مصالحت تھا۔', 'پھر کیا ہو کہ جب ان کو پہنچے مصیبت اپنے ہاتھوں کے کئے ہوئے سے پھر آویں تیرے پاس قسمیں کھاتے ہوئے اللہ کی کہ ہم کو غرض نہ تھی مگر بھلائی اور ملاپ [۱۰۸]', 'How then, when a catastrophe befalls them because of what their hands have sent forth, they come to you swearing by Allah, \"We meant no more than goodwill and conciliation!\"', 'But, how (apologetic) they are when they suffer a calamity because of the acts of their own hands, and they come to you swearing by Allah, “We meant nothing but to promote good and bring about harmony.”'),
(556, 4, 63, 9, 6, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اُولٰٓئِکَ الَّذِیۡنَ یَعۡلَمُ اللّٰہُ مَا فِیۡ قُلُوۡبِہِمۡ ٭ فَاَعۡرِضۡ عَنۡہُمۡ وَ عِظۡہُمۡ وَ قُلۡ لَّہُمۡ  فِیۡۤ  اَنۡفُسِہِمۡ  قَوۡلًۢا  بَلِیۡغًا ﴿۶۳﴾', 'ان لوگوں کے دلوں میں جو جو کچھ ہے اللہ اس کو خوب جانتا ہے تم ان کی باتوں کا کچھ خیال نہ کرو۔ اور انہیں نصیحت کرو اور ان سے ایسی باتیں کہو جو ان کے دلوں میں اثر کر جائیں۔', 'یہ وہ لوگ ہیں کہ اللہ جانتا ہے جو ان کے دل میں ہے سو تو ان سے تغافل کر اور ان کو نصیحت کر اور ان سےکہہ ان کے حق میں بات کام کی [۱۰۹]', 'They (hypocrites) are those of whom Allah knows what is in their hearts; so turn aside from them (do not punish them) but admonish them, and speak to them an effective word (i.e. to believe in Allah, worship Him, obey Him, and be afraid of Him) to reach their innerselves.', 'Those are the ones Allah knows what is in their hearts. So, ignore them, and give them good counsel, and speak to them about themselves in appealing words.'),
(557, 4, 64, 9, 6, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ مَاۤ اَرۡسَلۡنَا مِنۡ رَّسُوۡلٍ اِلَّا لِیُطَاعَ بِاِذۡنِ اللّٰہِ ؕ وَ لَوۡ اَنَّہُمۡ اِذۡ ظَّلَمُوۡۤا اَنۡفُسَہُمۡ جَآءُوۡکَ فَاسۡتَغۡفَرُوا اللّٰہَ وَ اسۡتَغۡفَرَ لَہُمُ الرَّسُوۡلُ لَوَجَدُوا اللّٰہَ تَوَّابًا  رَّحِیۡمًا ﴿۶۴﴾', 'اور ہم نے جو پیغمبر بھی بھیجا ہے اسی لئے بھیجا ہے کہ اللہ کے فرمان کے مطابق اس کا حکم مانا جائے۔ اور یہ لوگ جب اپنے حق میں ظلم کر بیٹھے تھے اگر تمہارے پاس آتے اور اللہ سے بخشش مانگتے اور پیغمبر بھی ان کے لئے بخشش طلب کرتے تو اللہ کو معاف کرنے والا بڑا مہربان پاتے۔', 'اور ہم نے کوئی رسول نہیں بھیجا مگر اسی واسطے کہ اس کا حکم مانیں اللہ کے فرمانے سے اور اگر وہ لوگ جس وقت انہوں نے اپنا برا کیا تھا آتے تیرے پاس پھر اللہ سے معافی چاہتے اور رسول بھی ان کو بخشواتا تو البتہ اللہ کو پاتے معاف کرنے والا مہربان [۱۱۰]', 'We sent no Messenger, but to be obeyed by Allahs Leave. If they (hypocrites), when they had been unjust to themselves, had come to you (Muhammad SAW) and begged Allahs Forgiveness, and the Messenger had begged forgiveness for them: indeed, they would have found Allah All-Forgiving (One Who accepts repentance), Most Merciful.', 'We did not send any Messenger but to be obeyed by the leave of Allah. Had they, after having wronged themselves, come to you and sought forgiveness from Allah, and had the Messenger prayed for their forgiveness, they would certainly have found Allah Most-Relenting, Very-Merciful.'),
(558, 4, 65, 9, 6, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'فَلَا وَ رَبِّکَ لَا یُؤۡمِنُوۡنَ حَتّٰی  یُحَکِّمُوۡکَ فِیۡمَا شَجَرَ  بَیۡنَہُمۡ ثُمَّ  لَا  یَجِدُوۡا فِیۡۤ  اَنۡفُسِہِمۡ حَرَجًا  مِّمَّا قَضَیۡتَ  وَ یُسَلِّمُوۡا  تَسۡلِیۡمًا ﴿۶۵﴾', 'پس تمہارے پروردگار کی قسم یہ لوگ جب تک اپنے تنازعات میں تمہیں منصف نہ بنائیں۔ اور جو فیصلہ تم کر دو اس سے اپنے دل میں تنگ بھی نہ ہوں بلکہ اس کو خوشی سے مان لیں تب تک مومن نہیں ہونگے۔', 'سو قسم ہے تیرے رب کی وہ مومن نہ ہوں گے یہاں تک کہ تجھ کو ہی منصف جانیں اس جھگڑے میں جو ان میں اٹھے پھر نہ پاویں اپنے جی میں تنگی تیرے فیصلہ سے اور قبول کریں خوشی سے [۱۱۱]', 'But no, by your Lord, they can have no Faith, until they make you (O Muhammad SAW) judge in all disputes between them, and find in themselves no resistance against your decisions, and accept (them) with full submission.', 'So, never by your Lord! Never shall they become believers, unless they make you the judge in the disputes that arise between them, then find no discomfort in their hearts against what you have decided, and surrender to it in total submission.'),
(559, 4, 66, 9, 6, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ لَوۡ اَنَّا کَتَبۡنَا عَلَیۡہِمۡ اَنِ اقۡتُلُوۡۤا اَنۡفُسَکُمۡ اَوِ اخۡرُجُوۡا مِنۡ دِیَارِکُمۡ مَّا فَعَلُوۡہُ  اِلَّا قَلِیۡلٌ مِّنۡہُمۡ ؕ وَ لَوۡ اَنَّہُمۡ فَعَلُوۡا مَا یُوۡعَظُوۡنَ بِہٖ لَکَانَ خَیۡرًا لَّہُمۡ  وَ اَشَدَّ  تَثۡبِیۡتًا ﴿ۙ۶۶﴾', 'اور اگر ہم ان پر فرض کر دیتے کہ اپنے آپ کو قتل کر ڈالو یا اپنے گھر چھوڑ کر نکل جاؤ تو ان میں سے تھوڑے ہی لوگ ایسا کرتے۔ اور اگر یہ اس نصیحت پر کاربند ہوتے جو انکو کی جاتی ہے تو ان کے حق میں بہتر اور دین میں زیادہ ثابت قدمی کا موجب ہوتا۔', 'اور اگر ہم ان پر حکم کرتے کہ ہلاک کرو اپنی جان یا چھوڑ نکلو اپنے گھر تو ایسا نہ کرتے مگر تھوڑے ان میں سے اور اگر یہ لوگ کریں وہ جو ان کو نصیحت کی جاتی ہے تو البتہ انکے حق میں بہتر ہو اور زیادہ ثبات رکھنے والا ہو دین میں', 'And if We had ordered them (saying), \"Kill yourselves (i.e. the innnocent ones kill the guilty ones) or leave your homes,\" very few of them would have done it; but if they had done what they were told, it would have been better for them, and would have strengthened their (Faith);', 'If We had prescribed for them that they should kill themselves or that they should migrate from their homeland, they would have not done it, except a few of them. If they had done what they were advised to do, it would have been better for them, and more effective in making (them) firm.'),
(560, 4, 67, 9, 6, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَّ اِذًا لَّاٰتَیۡنٰہُمۡ مِّنۡ لَّدُنَّـاۤ اَجۡرًا عَظِیۡمًا ﴿ۙ۶۷﴾', 'اوراس صورت میں ہم ان کو اپنے ہاں سے اجر عظیم بھی عطا فرماتے۔', 'اور اس وقت البتہ دیں ہم انکو اپنے پاس سے بڑا ثواب', 'And indeed We should then have bestowed upon them a great reward from Ourselves.', 'In that case, We would certainly have given them a great reward.'),
(561, 4, 68, 9, 6, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَّ لَہَدَیۡنٰہُمۡ صِرَاطًا مُّسۡتَقِیۡمًا ﴿۶۸﴾', 'اور انکو سیدھا رستہ بھی دکھاتے۔', 'اور چلاویں ان کو سیدھی راہ [۱۱۲]', 'And indeed We should have guided them to a Straight Way.', 'and we would certainly have led them to a straight path.'),
(562, 4, 69, 9, 6, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ مَنۡ یُّطِعِ اللّٰہَ وَ الرَّسُوۡلَ فَاُولٰٓئِکَ مَعَ الَّذِیۡنَ اَنۡعَمَ اللّٰہُ عَلَیۡہِمۡ مِّنَ النَّبِیّٖنَ وَ الصِّدِّیۡقِیۡنَ وَ الشُّہَدَآءِ وَ الصّٰلِحِیۡنَ ۚ وَ حَسُنَ اُولٰٓئِکَ رَفِیۡقًا ﴿ؕ۶۹﴾', 'اور جو لوگ اللہ اور اس کے رسول کی اطاعت کرتے ہیں وہ قیامت کے روز ان لوگوں کے ساتھ ہوں گے جن پر اللہ نے بڑا فضل کیا یعنی انبیاء اور صدیق اور شہید اور صالحین اور ان لوگوں کی رفاقت بہت ہی خوب ہے۔', 'اور جو کوئی حکم مانے اللہ کا اور اس کے رسول کا سو وہ ان کے ساتھ ہیں جن پر اللہ نے انعام کیا کہ وہ نبی اور صدیق اور شہید اور نیک بخت ہیں اور اچھی ہے ان کی رفاقت [۱۱۳]', 'And whoso obeys Allah and the Messenger (Muhammad SAW), then they will be in the company of those on whom Allah has bestowed His Grace, of the Prophets, the Siddiqoon (those followers of the Prophets who were first and foremost to believe in them, like Abu Bakr AsSiddiq ÑÖì ), the martyrs, and the righteous. And how excellent these companions are!', 'Those who obey Allah and the Messenger are with those whom Allah has blessed, namely, the prophets, the Siddiqīn, the Shuhadā’ and the righteous. And excellent are they as companions.'),
(563, 4, 70, 9, 6, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'ذٰلِکَ الۡفَضۡلُ مِنَ اللّٰہِ ؕ وَ کَفٰی بِاللّٰہِ عَلِیۡمًا ﴿٪۷۰﴾', 'یہ اللہ کا فضل ہے۔ اور اللہ جاننے والا کافی ہے۔', 'یہ فضل ہے اللہ کی طرف سے اور اللہ کافی ہے جاننے والا [۱۱۴]', 'Such is the Bounty from Allah, and Allah is Sufficient as AllKnower.', 'That grace is from Allah; and Allah is sufficient as being the One who knows.'),
(564, 4, 71, 10, 7, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا خُذُوۡا حِذۡرَکُمۡ فَانۡفِرُوۡا ثُبَاتٍ اَوِ انۡفِرُوۡا جَمِیۡعًا ﴿۷۱﴾', 'مومنو! جہاد کے لئے ہتھیار لے لیا کرو پھر یا تو جماعت جماعت ہو کر نکلا کرو یا سب اکٹھے کوچ کیا کرو۔', 'اے ایمان والو لے لو اپنے ہتھیار پھر نکلو جدی جدی فوج ہو کر یا سب اکھٹے [۱۱۵]', 'O you who believe! Take your precautions, and either go forth (on an expedition) in parties, or go forth all together.', 'O you who believe, be on your guard, and march in groups, or march all together.'),
(565, 4, 72, 10, 7, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ اِنَّ مِنۡکُمۡ لَمَنۡ لَّیُبَطِّئَنَّ ۚ فَاِنۡ اَصَابَتۡکُمۡ مُّصِیۡبَۃٌ قَالَ قَدۡ اَنۡعَمَ اللّٰہُ عَلَیَّ اِذۡ لَمۡ اَکُنۡ مَّعَہُمۡ شَہِیۡدًا ﴿۷۲﴾', 'اور تم میں کوئی ایسا بھی ہے کہ خواہ مخواہ دیر لگاتا ہے اور پیچھے رہ جاتا ہے۔ پھر اگر تم پر کوئی مصیبت پڑ جائے تو کہتا ہے کہ اللہ نے مجھ پر بڑی مہربانی کی کہ میں ان میں موجود نہ تھا۔', 'اور تم میں بعضا ایسا ہے کہ البتہ دیر لگا دے گا [۱۱۶] پھر اگر تم کو کوئی مصیبت پہنچے تو کہے اللہ نے مجھ پر فضل کیا کہ میں نہ ہوا ان کے ساتھ [۱۱۷]', 'There is certainly among you he who would linger behind (from fighting in Allahs Cause). If a misfortune befalls you, he says, \"Indeed Allah has favoured me in that I was not present among them.\"', 'Among you there is one who shall invariably fall back; then, if some calamity befalls you, he would say, “Allah has shown His favor to me, as I was not present with them.”'),
(566, 4, 73, 10, 7, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ لَئِنۡ اَصَابَکُمۡ فَضۡلٌ مِّنَ اللّٰہِ لَیَقُوۡلَنَّ کَاَنۡ لَّمۡ تَکُنۡۢ بَیۡنَکُمۡ وَ بَیۡنَہٗ مَوَدَّۃٌ یّٰلَیۡتَنِیۡ کُنۡتُ مَعَہُمۡ فَاَفُوۡزَ فَوۡزًا عَظِیۡمًا ﴿۷۳﴾', 'اور اگر اللہ تم پر فضل کرے تو اس طرح سے کہ گویا تم میں اس میں دوستی تھی ہی نہیں افسوس کرتا اور کہتا ہے کہ کاش میں بھی ان کے ساتھ ہوتا تو مقصد عظیم حاصل ہوتا۔', 'اور اگر تم کو پہنچا فضل اللہ کی طرف سے تو اس طرح کہنے لگے گا کہ گویا نہ تھی تم میں اور اس میں کچھ دوستی اے کاش کہ میں ہوتا انکے ساتھ تو پاتا بڑی مراد [۱۱۸]', 'But if a bounty (victory and booty) comes to you from Allah, he would surely say - as if there had never been ties of affection between you and him - \"Oh! I wish I had been with them; then I would have achieved a great success ( a good share of booty).\"', 'And if some bounty comes to you from Allah, he will certainly say,-as if there was no friendship between you and him- “Oh, would that I had been with them; then I would have secured a handsome gain.”'),
(567, 4, 74, 10, 7, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'فَلۡیُقَاتِلۡ فِیۡ سَبِیۡلِ اللّٰہِ الَّذِیۡنَ یَشۡرُوۡنَ الۡحَیٰوۃَ الدُّنۡیَا بِالۡاٰخِرَۃِ ؕ وَ مَنۡ یُّقَاتِلۡ فِیۡ سَبِیۡلِ اللّٰہِ فَیُقۡتَلۡ اَوۡ یَغۡلِبۡ فَسَوۡفَ نُؤۡتِیۡہِ اَجۡرًا عَظِیۡمًا ﴿۷۴﴾', 'اب جو لوگ آخرت کو خریدتے اور اس کے بدلے دنیا کی زندگی کو بیچنا چاہتے ہیں ان کو چاہیے کہ اللہ کی راہ میں جنگ کریں۔ اور جو شخص اللہ کی راہ میں جنگ کرے پھر شہید ہو جائے یا غلبہ پائے ہم عنقریب اس کو بڑا ثواب دیں گے۔', 'سو چاہئے لڑیں اللہ کی راہ میں وہ لوگ جو بیچتے ہیں دنیا کی زندگی آخرت کے بدلے اور جو کوئی لڑے اللہ کی راہ میں پھر مارا جاوے یا غالب ہووے تو ہم دیں گے اس کو بڑا ثواب [۱۱۹]', 'Let those (believers) who sell the life of this world for the Hereafter fight in the Cause of Allah, and whoso fights in the Cause of Allah, and is killed or gets victory, We shall bestow on him a great reward.', 'So, those who sell the worldly life for the Hereafter should fight in the way of Allah. Whoever fights in the way of Allah, then gets killed or prevails, We shall give a great reward to him.'),
(568, 4, 75, 10, 7, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ مَا لَکُمۡ لَا تُقَاتِلُوۡنَ فِیۡ سَبِیۡلِ اللّٰہِ وَ الۡمُسۡتَضۡعَفِیۡنَ مِنَ الرِّجَالِ وَ النِّسَآءِ وَ الۡوِلۡدَانِ الَّذِیۡنَ یَقُوۡلُوۡنَ رَبَّنَاۤ اَخۡرِجۡنَا مِنۡ ہٰذِہِ الۡقَرۡیَۃِ الظَّالِمِ اَہۡلُہَا ۚ وَ اجۡعَلۡ لَّنَا مِنۡ لَّدُنۡکَ وَلِیًّا ۚۙ وَّ اجۡعَلۡ لَّنَا مِنۡ لَّدُنۡکَ نَصِیۡرًا ﴿ؕ۷۵﴾', 'اور تم کو کیا ہوا ہے کہ اللہ کی راہ میں اور ان بے بس مردوں اور عورتوں اور بچوں کی خاطر نہیں لڑتے جو دعائیں کیا کرتے ہیں کہ اے  پروردگار ہم کو اس شہر سے جسکے رہنے والے ظالم ہیں نکال کر کہیں اور لیجا۔ اور اپنی طرف سے کسی کو ہمارا حامی بنا۔ اور اپنی ہی طرف سے کسی کو ہمارا مددگار مقرر فرما۔', 'اور تم کو کیا ہوا کہ نہیں لڑتے اللہ کی راہ میں اور ان کے واسطے جو مغلوب ہیں مرد اور عورتیں اور بچے جو کہتے ہیں اے رب ہمارے نکال ہم کو اس بستی سے کہ ظالم ہیں یہاں کےلوگ اور کر دے ہمارے واسطے اپنے پاس سےکوئی حمایتی اور کر دے ہمارے واسطے اپنے پاس سے مددگار [۱۲۰]', 'And what is wrong with you that you fight not in the Cause of Allah, and for those weak, illtreated and oppressed among men, women, and children, whose cry is: \"Our Lord! Rescue us from this town whose people are oppressors; and raise for us from You one who will protect, and raise for us from You one who will help.\"', 'What has happened to you that you do not fight in the way of Allah, and for the oppressed among men, women and children who say, “Our Lord, take us out from this town whose people are cruel, and make for us a supporter from Your own, and make for us a helper from Your own.”'),
(569, 4, 76, 10, 7, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اَلَّذِیۡنَ اٰمَنُوۡا یُقَاتِلُوۡنَ فِیۡ سَبِیۡلِ اللّٰہِ ۚ وَ الَّذِیۡنَ کَفَرُوۡا یُقَاتِلُوۡنَ فِیۡ سَبِیۡلِ الطَّاغُوۡتِ فَقَاتِلُوۡۤا اَوۡلِیَآءَ الشَّیۡطٰنِ ۚ اِنَّ کَیۡدَ الشَّیۡطٰنِ کَانَ ضَعِیۡفًا ﴿٪۷۶﴾', 'جو مومن ہیں وہ تو اللہ کی راہ میں لڑتے ہیں اور جو کافر ہیں وہ  شیطان کی راہ میں لڑتے ہیں سو تم شیطان کے مددگاروں سے لڑو اور ڈرو مت کیونکہ شیطان کا داؤ کمزور ہوتا ہے۔', 'جو لوگ ایمان والے ہیں سو لڑتے ہیں اللہ کی راہ میں اور جو کافر ہیں سو لڑتے ہیں شیطان کی راہ میں سو لڑو تم شیطان کے حمایتیوں سے بیشک فریب شیطان کا سست ہے [۱۲۱]', 'Those who believe, fight in the Cause of Allah, and those who disbelieve, fight in the cause of Taghoot (Satan, etc.). So fight you against the friends of Shaitan (Satan); Ever feeble indeed is the plot of Shaitan (Satan).', 'The believers fight in the way of Allah, and the disbelievers fight in the way of Tāghūt. So, fight the friends of Satan. No doubt, the guile of Satan is feeble.'),
(570, 4, 77, 11, 8, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اَلَمۡ تَرَ اِلَی الَّذِیۡنَ قِیۡلَ لَہُمۡ کُفُّوۡۤا اَیۡدِیَکُمۡ وَ اَقِیۡمُوا الصَّلٰوۃَ  وَ اٰتُوا الزَّکٰوۃَ ۚ فَلَمَّا کُتِبَ عَلَیۡہِمُ الۡقِتَالُ اِذَا فَرِیۡقٌ مِّنۡہُمۡ یَخۡشَوۡنَ النَّاسَ  کَخَشۡیَۃِ  اللّٰہِ اَوۡ اَشَدَّ خَشۡیَۃً ۚ وَ قَالُوۡا رَبَّنَا لِمَ کَتَبۡتَ عَلَیۡنَا الۡقِتَالَ ۚ لَوۡ لَاۤ اَخَّرۡتَنَاۤ اِلٰۤی اَجَلٍ قَرِیۡبٍ ؕ قُلۡ مَتَاعُ الدُّنۡیَا قَلِیۡلٌ ۚ وَ الۡاٰخِرَۃُ خَیۡرٌ  لِّمَنِ  اتَّقٰی ۟ وَ لَا تُظۡلَمُوۡنَ  فَتِیۡلًا ﴿۷۷﴾', 'بھلا تم نے ان لوگوں کو نہیں دیکھا جنکو پہلے یہ حکم دیا گیا تھا کہ اپنے ہاتھوں کو جنگ سے روکے رہو اور نماز پڑھتے اور زکوٰۃ دیتے رہو۔ پھر جب ان پر جہاد فرض کر دیا گیا تو بعض لوگ ان میں سے لوگوں سے یوں ڈرنے لگے جیسے اللہ سے ڈرا کرتے ہیں۔ بلکہ اس سے بھی زیادہ۔ اور کہنے لگے کہ اے اللہ تو نے ہم پر جہاد جلد کیوں فرض کر دیا۔ تھوڑی مدت اور ہمیں کیوں مہلت نہ دی اے پیغمبر ان سے کہہ دو کہ دنیا کا فائدہ بہت تھوڑا ہے اور بہت اچھی چیز تو پرہیزگار کے لئے نجات آخرت ہے اور تم پر دھاگے برابر بھی ظلم نہیں کیا جائے گا۔', 'کیا تو نے نہ دیکھا ان لوگوں کو جن کو حکم ہوا تھا کہ اپنے ہاتھ تھامے رکھو اور قائم رکھو نماز اور  دیتے رہو زکوٰۃ [۱۲۲] پھر جب حکم ہوا ان پر لڑائی کا اسی وقت ان میں ایک جماعت ڈرنےلگی لوگوں سے جیسا ڈر ہو اللہ کا یا اس سے بھی زیادہ ڈر اور کہنے لگے اے رب ہمارے کیوں فرض کی ہم پر لڑائی کیوں نہ چھوڑے رکھا ہم کو تھوڑی مدت تک [۱۲۳] کہہ دےکہ فائدہ دنیا کا تھوڑا ہے اور آخرت بہتر ہے پرہیزگار کو اور تمہارا حق نہ رہے گا ایک تاگے برابر [۱۲۴]', 'Have you not seen those who were told to hold back their hands (from fighting) and perform As-Salat (IqamatasSalat), and give Zakat, but when the fighting was ordained for them, behold! a section of them fear men as they fear Allah or even more. They say: \"Our Lord! Why have you ordained for us fighting? Would that you had granted us respite for a short period?\" Say: \"Short is the enjoyment of this world. The Hereafter is (far) better for him who fears Allah, and you shall not be dealt with unjustly even equal to the Fatila (a scalish thread in the long slit of a datestone).', 'Have you not seen those to whom it was said, “Hold your hands (from fighting) and be steadfast in Salāh and pay Zakāh.” However, when fighting is enjoined upon them, then surprisingly, a group from them starts fearing people, as one would fear Allah, or fearing even more.They say, “Our Lord, why have you enjoined fighting upon us? Would you have not spared us for a little more time?” Say, “The enjoyment of the world is but a little, and the Hereafter is far better for the one who fears Allah, and you shall not be wronged, even to the measure of a fiber.'),
(571, 4, 78, 11, 8, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اَیۡنَ مَا تَکُوۡنُوۡا یُدۡرِکۡکُّمُ الۡمَوۡتُ وَ لَوۡ کُنۡتُمۡ  فِیۡ  بُرُوۡجٍ مُّشَیَّدَۃٍ ؕ وَ  اِنۡ تُصِبۡہُمۡ حَسَنَۃٌ  یَّقُوۡلُوۡا ہٰذِہٖ مِنۡ عِنۡدِ اللّٰہِ ۚ وَ اِنۡ تُصِبۡہُمۡ سَیِّئَۃٌ یَّقُوۡلُوۡا ہٰذِہٖ مِنۡ عِنۡدِکَ ؕ قُلۡ کُلٌّ مِّنۡ عِنۡدِ اللّٰہِ ؕ فَمَالِ ہٰۤؤُلَآءِ الۡقَوۡمِ لَا یَکَادُوۡنَ یَفۡقَہُوۡنَ حَدِیۡثًا ﴿۷۸﴾', 'اے جہاد سے ڈرنے والو تم کہیں رہو موت تو تمہیں آ کر رہے گی خواہ مضبوط قلعوں میں رہو۔ اور ان لوگوں کو اگر کوئی فائدہ پہنچتا ہے تو کہتے ہیں یہ اللہ کی طرف سے ہے اور اگر کوئی مصیبت پہنچتی ہے تو اے پیغمبر تم سے کہتے ہیں کہ یہ آپ کی وجہ سے ہمیں پہنچی ہے۔ کہہ دو کہ رنج و راحت سب اللہ ہی کی طرف سے ہے۔ ان لوگوں کو کیا ہو گیا ہے کہ بات بھی نہیں سمجھ سکتے۔', 'جہاں کہیں تم ہو گے موت تم کو آ پکڑے گی اگرچہ تم ہو مضبوط قلعوں میں [۱۲۵] اور اگر پہنچے لوگوں کو کچھ بھلائی تو کہیں یہ اللہ کی طرف سے ہے اور اگر ان کو پہنچے کچھ برائی تو کہیں یہ تیری طرف سے ہے [۱۲۶] کہدے کہ سب اللہ کی طرف سے ہے سو کیا حال ہے ان لوگوں کا ہرگز نہیں لگتے کہ سمجھیں کوئی بات [۱۲۷]', '\"Wheresoever you may be, death will overtake you even if you are in fortresses built up strong and high!\" And if some good reaches them, they say, \"This is from Allah,\" but if some evil befalls them, they say, \"This is from you (O Muhammad SAW).\" Say: \"All things are from Allah,\" so what is wrong with these people that they fail to understand any word?', 'Wherever you will be, Death will overtake you, even though you are in fortified castles.” If some good comes to them, they say, “This is from Allah.” But if some evil visits them, they say, “This is from you.” Say, “All is from Allah.” So, what is wrong with these people, they do not seem to understand anything?'),
(572, 4, 79, 11, 8, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'مَاۤ  اَصَابَکَ مِنۡ حَسَنَۃٍ  فَمِنَ اللّٰہِ ۫ وَ مَاۤ اَصَابَکَ مِنۡ سَیِّئَۃٍ  فَمِنۡ نَّفۡسِکَ ؕ وَ اَرۡسَلۡنٰکَ لِلنَّاسِ رَسُوۡلًا ؕ وَ کَفٰی بِاللّٰہِ شَہِیۡدًا ﴿۷۹﴾', 'اے آدم زاد تجھ کو جو فائدہ پہنچے وہ اللہ کی طرف سے ہے۔ اور جو نقصان پہنچے وہ تیری ہی شامت اعمال کی وجہ سے ہے۔ اور اے نبی ہم نے تم کو لوگوں کی ہدایت کے لئے پیغمبر بنا کر بھیجا ہے اور اس بات کا اللہ ہی گواہ کافی ہے۔', 'جو پہنچے تجھ کو کوئی بھلائی سو اللہ کی طرف سے ہے اور جو تجھ کو برائی پہنچے سو تیرے نفس کی طرف سے ہے [۱۲۸] اور ہم نے تجھ کو بھیجا پیغام پہنچانے والا لوگوں کو اور اللہ کافی ہے سامنے دیکھنے والا [۱۲۹]', 'Whatever of good reaches you, is from Allah, but whatever of evil befalls you, is from yourself. And We have sent you (O Muhammad SAW) as a Messenger to mankind, and Allah is Sufficient as a Witness.', 'Whatever good comes to you, it is from Allah and whatever evil visits you, it comes from your own selves. We have sent you to be a Messenger for the people. Allah is enough to be a witness.'),
(573, 4, 80, 11, 8, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'مَنۡ یُّطِعِ الرَّسُوۡلَ فَقَدۡ اَطَاعَ اللّٰہَ ۚ وَ مَنۡ تَوَلّٰی  فَمَاۤ  اَرۡسَلۡنٰکَ عَلَیۡہِمۡ حَفِیۡظًا  ﴿ؕ۸۰﴾', 'جو شخص رسول کی فرمانبرداری کرتا ہے تو بیشک اس نے اللہ کی فرمانبرداری کی اور جو نافرمانی کرے تو اے پیغمبر تمہیں ہم نے ان کا نگہبان بنا کر نہیں بھیجا۔', 'جس نے حکم مانا رسول کا اس نے حکم مانا اللہ کا اور جو الٹا پھرا تو ہم نے تجھ نہیں بھیجا ان پر نگہبان [۱۳۰]', 'He who obeys the Messenger (Muhammad SAW), has indeed obeyed Allah, but he who turns away, then we have not sent you (O Muhammad SAW) as a watcher over them.', 'Whoever obeys the Messenger obeys Allah, and whoever turns away, then, We did not send you to stand guard over them.'),
(574, 4, 81, 11, 8, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ یَقُوۡلُوۡنَ طَاعَۃٌ ۫ فَاِذَا بَرَزُوۡا مِنۡ عِنۡدِکَ بَیَّتَ طَآئِفَۃٌ مِّنۡہُمۡ غَیۡرَ الَّذِیۡ تَقُوۡلُ ؕ وَ اللّٰہُ یَکۡتُبُ مَا یُبَیِّتُوۡنَ ۚ فَاَعۡرِضۡ عَنۡہُمۡ وَ تَوَکَّلۡ عَلَی اللّٰہِ ؕ وَ کَفٰی بِاللّٰہِ  وَکِیۡلًا ﴿۸۱﴾', 'اور یہ لوگ منہ سے تو کہتے ہیں کہ آپ کی فرمانبرداری دل سے منظور ہے لیکن جب تمہارے پاس سے چلے جاتے ہیں تو ان میں سے بعض لوگ رات کو تمہاری باتوں کے خلاف مشورے کرتے ہیں اور جو مشورے یہ کرتے ہیں اللہ ان کو لکھ لیتا ہے۔ سو انکا کچھ خیال نہ کرو۔ اور اللہ پر بھروسا رکھو اور اللہ ہی کافی کارساز ہے۔', 'اور کہتے ہیں کہ قبول ہے پھر جب باہر گئے تیرے پاس سے تو مشورہ کرتے ہیں بعضے بعضے ان میں سے رات کو اس کےخلاف جو تجھ سےکہہ چکے تھے اور اللہ لکھتا ہے جو وہ مشورہ کرتے ہیں سو تو تغافل کر ان سے اور بھرسہ کر اللہ پر اور اللہ کافی ہے کارساز [۱۳۱]', 'They say: \"We are obedient,\" but when they leave you (Muhammad SAW), a section of them spend all night in planning other than what you say. But Allah records their nightly (plots). So turn aside from them (do not punish them), and put your trust in Allah. And Allah is Ever AllSufficient as a Disposer of affairs.', 'They say, “Obedience (we observe).” But when they go away from you, a group of them conspires at night contrary to what they say. Allah records what they conspire. So ignore them and put your trust in Allah. Allah is enough to trust in.'),
(575, 4, 82, 11, 8, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اَفَلَا یَتَدَبَّرُوۡنَ الۡقُرۡاٰنَ ؕ وَ لَوۡ  کَانَ مِنۡ عِنۡدِ غَیۡرِ اللّٰہِ لَوَجَدُوۡا فِیۡہِ اخۡتِلَافًا کَثِیۡرًا ﴿۸۲﴾', 'بھلا یہ قرآن میں غور کیوں نہیں کرتے۔ اگر یہ اللہ کے سوا کسی اور کا کلام ہوتا تو اس میں وہ بہت سا اختلاف پاتے۔', 'کیا غور نہیں کرتے قرآن میں اور اگر یہ ہوتا کسی اور کا سوائے اللہ کے تو ضرور پاتےاس میں بہت تفاوت [۱۳۲]', 'Do they not then consider the Quran carefully? Had it been from other than Allah, they would surely have found therein much contradictions.', 'Do they not, then, ponder about the Qur’ān? Had it been from someone other than Allah, they would have found in it a great deal of discrepancy.'),
(576, 4, 83, 11, 8, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ  اِذَا جَآءَہُمۡ  اَمۡرٌ مِّنَ الۡاَمۡنِ اَوِ  الۡخَوۡفِ اَذَاعُوۡا بِہٖ ؕ وَ لَوۡ رَدُّوۡہُ  اِلَی الرَّسُوۡلِ وَ اِلٰۤی اُولِی الۡاَمۡرِ مِنۡہُمۡ لَعَلِمَہُ الَّذِیۡنَ یَسۡتَنۡۢبِطُوۡنَہٗ مِنۡہُمۡ ؕ وَ لَوۡ لَا فَضۡلُ اللّٰہِ عَلَیۡکُمۡ وَ رَحۡمَتُہٗ لَاتَّبَعۡتُمُ الشَّیۡطٰنَ  اِلَّا  قَلِیۡلًا ﴿۸۳﴾', 'اور جب ان کے پاس امن یا خوف کی کوئی خبر پہنچتی ہے تو اسے مشہور کر دیتے ہیں۔ حالانکہ اسکو اگر پیغمبر اور اپنے ذمہ داروں کے پاس پہنچاتے تو تحقیق کرنے والے اس کی تحقیق کر لیتے۔ اور اگر تم پر اللہ کا فضل اور اس کی مہربانی نہ ہوتی تو چند آدمیوں کے سوا تم سب شیطان کے پیرو ہو جاتے۔', 'اور جب ان کے پاس پہنچتی ہے کوئی خبر امن کی یا ڈر کی تو اسکو مشہور کر دیتے ہیں [۱۳۳] اور اگر اسکو پہنچا دیتے رسول تک اور اپنے حکموں تک تو تحقیق کرتے اس کو جو ان میں تحقیق کرنے والے ہیں اس کی [۱۳۴] اور اگر نہ ہوتا فضل اللہ کا تم پر اور اس کی مہربانی تو البتہ تم پیچھے ہو لیتے شیطان کے مگر تھوڑے [۱۳۵]', 'When there comes to them some matter touching (public) safety or fear, they make it known (among the people), if only they had referred it to the Messenger or to those charged with authority among them, the proper investigators would have understood it from them (directly). Had it not been for the Grace and Mercy of Allah upon you, you would have followed Shaitan (Satan), save a few of you.', 'When news concerning peace or fear comes to them, they go about spreading it. Had they referred it to the Messenger and to those having authority among them, the truth of the matter would have come to the knowledge of those of them who are able to investigate. But for Allah’s grace upon you, and mercy, you would have followed the Satan, save a few.'),
(577, 4, 84, 11, 8, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'فَقَاتِلۡ فِیۡ سَبِیۡلِ اللّٰہِ ۚ لَا تُکَلَّفُ اِلَّا نَفۡسَکَ وَ حَرِّضِ الۡمُؤۡمِنِیۡنَ ۚ عَسَی اللّٰہُ اَنۡ یَّکُفَّ بَاۡسَ الَّذِیۡنَ کَفَرُوۡا ؕ وَ اللّٰہُ اَشَدُّ  بَاۡسًا وَّ اَشَدُّ تَنۡکِیۡلًا ﴿۸۴﴾', 'سو اے پیغمبر تم اللہ کی راہ میں لڑو۔ تم اپنے سوا کسی کے ذمے دار نہیں ہو۔ اور مومنوں کو بھی ترغیب دو۔ قریب ہے کہ اللہ کافروں کی لڑائی کو بند کر دے۔ اور اللہ شدید ترین جنگ کرنے والا ہے اور سزا دینے کہ لحاظ سے بھی بہت سخت ہے۔', 'سو تو لڑ اللہ کی راہ میں تو ذمہ دار نہیں مگر اپنی جان کا اور تاکید کر مسلمانوں کو قریب ہے کہ اللہ بند کر دے لڑائی کافروں کی [۱۳۶] اور اللہ بہت سخت ہے لڑائی میں اور بہت سخت ہے سزا دینے میں [۱۳۷]', 'Then fight (O Muhammad SAW) in the Cause of Allah, you are not tasked (held responsible) except for yourself, and incite the believers (to fight along with you), it may be that Allah will restrain the evil might of the disbelievers. And Allah is Stronger in Might and Stronger in punishing.', 'So, fight in the way of Allah. You are not responsible but for yourself, and persuade the believers (to fight in Allah’s way). It is likely that Allah will prevent the mischief of those who disbelieve. Allah is the strongest in power and the mightiest in punishing.'),
(578, 4, 85, 11, 8, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'مَنۡ یَّشۡفَعۡ شَفَاعَۃً حَسَنَۃً یَّکُنۡ لَّہٗ نَصِیۡبٌ مِّنۡہَا ۚ وَ مَنۡ یَّشۡفَعۡ شَفَاعَۃً سَیِّئَۃً یَّکُنۡ لَّہٗ کِفۡلٌ مِّنۡہَا ؕ وَ کَانَ اللّٰہُ  عَلٰی کُلِّ  شَیۡءٍ  مُّقِیۡتًا ﴿۸۵﴾', 'جو شخص نیک بات کی سفارش کرے تو اس کو اس کے ثواب میں سے حصہ ملے گا۔ اور جو بری بات کی سفارش کرے اس کو اس کے عذاب میں سے حصہ ملے گا۔ اور اللہ ہر چیز پر قدرت رکھتا ہے۔', 'جو کوئی سفارش کرے نیک بات میں اس کو بھی ملے گا اس میں سے ایک حصہ اور جو کوئی سفارش کرے بری بات میں اس پر بھی ہے ایک بوجھ اس میں سے [۱۳۸] اور اللہ ہے ہر چیز پر قدرت رکھنے والا [۱۳۹]', 'Whosoever intercedes for a good cause will have the reward thereof, and whosoever intercedes for an evil cause will have a share in its burden. And Allah is Ever All-Able to do (and also an All-Witness to) everything.', 'Whoever makes a good recommendation, there shall be for him a share from it (in the Hereafter), and whoever makes a bad recommendation, there shall be for him a share from it. Allah is powerful over everything.'),
(579, 4, 86, 11, 8, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ اِذَا حُیِّیۡتُمۡ بِتَحِیَّۃٍ فَحَیُّوۡا بِاَحۡسَنَ مِنۡہَاۤ  اَوۡ رُدُّوۡہَا ؕ اِنَّ اللّٰہَ کَانَ عَلٰی کُلِّ  شَیۡءٍ  حَسِیۡبًا ﴿۸۶﴾', 'اور جب تم کو کوئی دعا دے تو جواب میں تم اس سے بہتر کلمے سے اسے دعا دو یا انہیں لفظوں سے دعا دو۔ بیشک اللہ ہر چیز کا حساب لینے والا ہے۔', 'اور جب تم کو دعا دیوے کوئی تو تم بھی دعا دو اس سے بہتر یا وہی کہو الٹ کر بیشک اللہ ہے ہر چیز کا حساب کرنے والا [۱۴۰]', 'When you are greeted with a greeting, greet in return with what is better than it, or (at least) return it equally. Certainly, Allah is Ever a Careful Account Taker of all things.', 'When you are greeted with a salutation, greet with one better than it, or return the same. Surely, Allah is the One who takes account of everything.'),
(580, 4, 87, 11, 8, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اَللّٰہُ لَاۤ اِلٰہَ  اِلَّا ہُوَ ؕ لَیَجۡمَعَنَّکُمۡ اِلٰی یَوۡمِ الۡقِیٰمَۃِ لَا رَیۡبَ فِیۡہِ ؕ وَ مَنۡ اَصۡدَقُ مِنَ  اللّٰہِ  حَدِیۡثًا ﴿٪۸۷﴾', 'اللہ وہ معبود برحق ہے کہ اسکے سوا کوئی عبادت کے لائق نہیں۔ وہ قیامت کے دن تم سب کو ضرور جمع کرے گا اور اللہ سے بڑھ کر بات کا سچّا کون ہو گا؟', 'اللہ کے سوا کسی کی بندگی نہیں بیشک تم کو جمع کرے گا قیامت کے دن اس میں کچھ شبہ نہیں اور اللہ سے سچی کس کی بات [۱۴۱]', 'Allah! La ilaha illa Huwa (none has the right to be worshipped but He). Surely, He will gather you together on the Day of Resurrection about which there is no doubt. And who is truer in statement than Allah?', 'Allah: There is no god but He. He shall certainly gather you towards the Day of Doom. There is no doubt about it. Who is more truthful in his word than Allah?'),
(581, 4, 88, 12, 9, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'فَمَا  لَکُمۡ فِی الۡمُنٰفِقِیۡنَ فِئَتَیۡنِ وَ اللّٰہُ اَرۡکَسَہُمۡ بِمَا کَسَبُوۡا ؕ اَتُرِیۡدُوۡنَ اَنۡ تَہۡدُوۡا مَنۡ اَضَلَّ اللّٰہُ ؕ وَ مَنۡ یُّضۡلِلِ اللّٰہُ فَلَنۡ تَجِدَ لَہٗ سَبِیۡلًا ﴿۸۸﴾', 'اب کیا سبب ہے کہ مسلمانو تم منافقوں کے بارے میں دو گروہ بن گئے ہو حالانکہ اللہ نے ان کو ان کے کرتوتوں کے سبب اوندھا کر دیا ہے۔ کیا تم چاہتے ہو کہ جس شخص کو اللہ نے گمراہ رہنے دیا ہے اسکو رستے پر لے آؤ۔ اور جس شخص کو اللہ گمراہ  رہنے دے تم اسکے لئے کبھی بھی رستہ نہیں پاؤ گے۔', 'پھر تم کو کیا ہوا کہ منافقوں کے معاملہ میں دو فریق ہو رہے ہو اور اللہ نے انکو الٹ دیا بسبب ان کے اعمال کے کیا تم چاہتے ہو کہ راہ پر لاؤ جس کو گمراہ کیا اللہ نے اور جس کو گمراہ کرےاللہ ہر گز نہ پاوے گا تو اس کے لئے کوئی راہ [۱۴۲]', 'Then what is the matter with you that you are divided into two parties about the hypocrites? Allah has cast them back (to disbelief) because of what they have earned. Do you want to guide him whom Allah has made to go astray? And he whom Allah has made to go astray, you will never find for him any way (of guidance).', 'So, what is the matter with you that you have become two groups about the hypocrites, while Allah has reverted them because of what they did. Do you want to guide the one whom Allah has let go astray? The one whom Allah lets go astray, you shall never find a way for him.'),
(582, 4, 89, 12, 9, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَدُّوۡا لَوۡ تَکۡفُرُوۡنَ کَمَا کَفَرُوۡا فَتَکُوۡنُوۡنَ سَوَآءً  فَلَا تَتَّخِذُوۡا مِنۡہُمۡ اَوۡلِیَآءَ حَتّٰی یُہَاجِرُوۡا فِیۡ سَبِیۡلِ اللّٰہِ ؕ فَاِنۡ تَوَلَّوۡا فَخُذُوۡہُمۡ وَ اقۡتُلُوۡہُمۡ حَیۡثُ وَجَدۡتُّمُوۡہُمۡ ۪ وَ لَا تَتَّخِذُوۡا مِنۡہُمۡ  وَلِیًّا وَّ لَا  نَصِیۡرًا ﴿ۙ۸۹﴾', 'وہ تو یہ چاہتے ہیں کہ جس طرح وہ خود کافر ہیں اسی طرح تم بھی کافر ہو کر سب برابر ہو جاؤ تو جب تک وہ اللہ کی راہ میں وطن نہ چھوڑ جائیں ان میں سے کسی کو دوست نہ بنانا۔ اگر ترک وطن کو قبول نہ کریں تو انکو پکڑ لو اور جہاں پاؤ قتل کر دو۔ اور ان میں سے کسی کو اپنا رفیق اور مددگار نہ بناؤ۔', 'چاہتے  ہیں کہ تم بھی کافر ہو جاؤ جیسے وہ کافر ہوئے تو پھر تم سب برابر ہو جاؤ سو تم ان میں سےکسی کو دوست مت بناؤ یہاں تک کہ وطن چھوڑ آویں اللہ کی راہ میں پھر اگر اس کو قبول نہ کریں تو ان کو پکڑو اور مار ڈالو جہاں پاؤ اور نہ بناؤ ان میں سے کسی کو دوست اور نہ مددگار [۱۴۳]', 'They wish that you reject Faith, as they have rejected (Faith), and thus that you all become equal (like one another). So take not Auliya (protectors or friends) from them, till they emigrate in the Way of Allah (to Muhammad SAW). But if they turn back (from Islam), take (hold) of them and kill them wherever you find them, and take neither Auliya (protectors or friends) nor helpers from them.', 'They wish that you should disbelieve, as they have disbelieved, and thus you become all alike. So, do not take friends from among them unless they migrate in the way of Allah. Then, if they turn away, seize them, and kill them wherever you find them, and do not take from among them a friend or helper.'),
(583, 4, 90, 12, 9, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اِلَّا الَّذِیۡنَ یَصِلُوۡنَ اِلٰی قَوۡمٍۭ بَیۡنَکُمۡ وَ بَیۡنَہُمۡ مِّیۡثَاقٌ اَوۡ جَآءُوۡکُمۡ حَصِرَتۡ صُدُوۡرُہُمۡ اَنۡ یُّقَاتِلُوۡکُمۡ اَوۡ یُقَاتِلُوۡا قَوۡمَہُمۡ ؕ وَ لَوۡ شَآءَ اللّٰہُ لَسَلَّطَہُمۡ عَلَیۡکُمۡ فَلَقٰتَلُوۡکُمۡ ۚ فَاِنِ اعۡتَزَلُوۡکُمۡ فَلَمۡ یُقَاتِلُوۡکُمۡ  وَ اَلۡقَوۡا اِلَیۡکُمُ السَّلَمَ ۙ فَمَا جَعَلَ اللّٰہُ لَکُمۡ عَلَیۡہِمۡ  سَبِیۡلًا ﴿۹۰﴾', 'مگر جو لوگ ایسے لوگوں سے جا ملے ہوں جن میں اور تم میں صلح کا عہد ہو یا اس حال میں کہ ان کے دل تمہارے ساتھ یا اپنی قوم کے ساتھ لڑنے سے بھنچ رہے ہوں تمہارے پاس آ جائیں تو اور بات ہے اور اگر اللہ چاہتا تو ان کو تم پر غالب کر دیتا تو وہ تم سے ضرور لڑتے۔ پھر اگر وہ تم سے کنارہ کشی کریں یعنی تم سے نہ لڑیں اور تمہاری طرف صلح کا پیغام بھیجیں تو اللہ نے تمہارے لئے ان پر زبردستی کرنے کی کوئی سبیل مقرر نہیں کی۔', 'مگر وہ لوگ جو ملاپ رکھتے ہیں ایک قوم سے کہ تم میں اور ان میں عہد ہے یا آئے ہیں تمہارے پاس کہ تنگ ہو گئے ہیں دل ان کے تمہاری لڑائی سے اور اپنی قوم کی لڑائی سے بھی اور اگر اللہ چاہتا تو ان کو تم پر زور دے دیتا تو ضرور لڑتے تم سےسو اگر یکسو رہیں وہ تم سے پھر تم سے نہ لڑیں اور پیش کریں تم پر صلح تو اللہ نے نہیں دی تم کو ان پر راہ [۱۴۴]', 'Except those who join a group, between you and whom there is a treaty (of peace), or those who approach you with their breasts restraining from fighting you as well as fighting their own people. Had Allah willed, indeed He would have given them power over you, and they would have fought you. So if they withdraw from you, and fight not against you, and offer you peace, then Allah has opened no way for you against them', 'Except those who join a group between whom and you there is a treaty, or who come to you with their hearts feeling discomfort in fighting either against you or against their own people. If Allah had so willed, He would have given them power over you, then they would have fought you - so, if they stay away from you, and do not fight you and offer you peace, then Allah has not given you any authority against them.'),
(584, 4, 91, 12, 9, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'سَتَجِدُوۡنَ اٰخَرِیۡنَ یُرِیۡدُوۡنَ اَنۡ یَّاۡمَنُوۡکُمۡ وَ یَاۡمَنُوۡا قَوۡمَہُمۡ ؕ کُلَّمَا رُدُّوۡۤا  اِلَی الۡفِتۡنَۃِ  اُرۡکِسُوۡا فِیۡہَا ۚ فَاِنۡ لَّمۡ یَعۡتَزِلُوۡکُمۡ وَ یُلۡقُوۡۤا اِلَیۡکُمُ السَّلَمَ وَ یَکُفُّوۡۤا اَیۡدِیَہُمۡ فَخُذُوۡہُمۡ وَ اقۡتُلُوۡہُمۡ حَیۡثُ ثَقِفۡتُمُوۡہُمۡ ؕ وَ اُولٰٓئِکُمۡ جَعَلۡنَا لَکُمۡ عَلَیۡہِمۡ سُلۡطٰنًا مُّبِیۡنًا ﴿٪۹۱﴾', 'تم کچھ اور لوگ ایسے بھی پاؤ گے جو یہ چاہتے ہیں کہ تم سے بھی امن میں رہیں اور اپنی قوم سے بھی امن میں رہیں۔ لیکن جب فتنہ انگیزی کو بلائے جائیں تو اس میں اوندھے منہ گر پڑیں تو ایسے لوگ اگر تم سے لڑنے سے کنارہ کشی نہ کریں اور نہ تمہاری طرف پیغام صلح بھیجیں اور نہ اپنے ہاتھوں کو روکیں تو ان کو پکڑ لو اور جہاں پاؤ قتل کردو۔ اور انہی لوگوں کے مقابلے میں ہم نے تمہیں کھلی چھوٹ دے دی ہے۔', 'اب تم دیکھو گے ایک اور قوم کو جو چاہتے ہیں کہ امن میں رہیں تم سے بھی اور اپنی قوم سے بھی جب کبھی لوٹائے جاتے ہیں وہ فساد کی طرف تو اسکی طرف لوٹ جاتے ہیں پھر اگر وہ تم سے یکسو نہ رہیں اور نہ پیش کریں تم پر صلح اور اپنے ہاتھ نہ روکیں تو ان کو پکڑو اور مار ڈالو جہاں پاؤ اور ان پر ہم نے تم کو دی ہے کھلی سند [۱۴۵]', 'You will find others that wish to have security from you and security from their people. Every time they are sent back to temptation, they yield thereto. If they withdraw not from you, nor offer you peace, nor restrain their hands, take (hold) of them and kill them wherever you find them. In their case, We have provided you with a clear warrant against them.', 'You will find others who want to be secure from you, and secure from their own people. (But) whenever they are called back to the mischief, they are plunged into it. So, if they do not stay away from you, and do not offer peace to you, and do not restrain their hands, then seize them, and kill them wherever you find them, and, We have given you an open authority against them.'),
(585, 4, 92, 13, 10, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ مَا کَانَ لِمُؤۡمِنٍ اَنۡ یَّقۡتُلَ مُؤۡمِنًا اِلَّا خَطَـًٔا ۚ وَ مَنۡ قَتَلَ مُؤۡمِنًا خَطَـًٔا فَتَحۡرِیۡرُ رَقَبَۃٍ مُّؤۡمِنَۃٍ وَّ دِیَۃٌ مُّسَلَّمَۃٌ اِلٰۤی اَہۡلِہٖۤ  اِلَّاۤ اَنۡ یَّصَّدَّقُوۡا ؕ فَاِنۡ کَانَ مِنۡ قَوۡمٍ عَدُوٍّ لَّکُمۡ وَ ہُوَ مُؤۡمِنٌ فَتَحۡرِیۡرُ رَقَبَۃٍ مُّؤۡمِنَۃٍ ؕ وَ اِنۡ کَانَ مِنۡ قَوۡمٍۭ بَیۡنَکُمۡ وَ بَیۡنَہُمۡ مِّیۡثَاقٌ فَدِیَۃٌ مُّسَلَّمَۃٌ اِلٰۤی اَہۡلِہٖ وَ تَحۡرِیۡرُ رَقَبَۃٍ مُّؤۡمِنَۃٍ ۚ فَمَنۡ لَّمۡ  یَجِدۡ فَصِیَامُ شَہۡرَیۡنِ مُتَتَابِعَیۡنِ ۫ تَوۡبَۃً مِّنَ  اللّٰہِ ؕ وَ کَانَ اللّٰہُ  عَلِیۡمًا حَکِیۡمًا ﴿۹۲﴾', 'اور کسی مومن کو شایاں نہیں کہ دوسرے مومن کو مار ڈالے مگر غلطی سے ایسا کر بیٹھے۔ اور جو غلطی سے بھی مومن کو مار ڈالے تو وہ ایک تو ایک مسلمان غلام آزاد کر دے اور مقتول کے وارثوں کو خون بہا دے۔ مگر یہ کہ وہ معاف کر دیں پھر اگر مقتول تمہارے دشمنوں کی جماعت میں سے ہو اور وہ خود مومن ہو تو صرف ایک مسلمان غلام آزاد کرنا چاہیے اور اگر مقتول ایسے لوگوں میں سے ہو جن میں اور تم میں صلح کا عہد ہو تو وارثان مقتول کو خون بہا دینا اور ایک مسلمان غلام آزاد کرنا چاہیے اور جس کو یہ میّسر نہ ہو وہ متواتر دو مہینے کے روزے رکھے یہ کفارہ اللہ کی طرف سے قبول توبہ کے لئے ہے اور اللہ سب کچھ جانتا ہے بڑی حکمت والا ہے۔', 'اور مسلمان کا کام نہیں کہ قتل کرے مسلمان کو مگر غلطی سے [۱۴۶] اور جو قتل کرے مسلمان کو غلطی سے تو آزاد کرے گردن ایک مسلمان کی اور خون بہا پہنچائے اسکے گھر والوں کو مگر یہ کہ وہ معاف کر دیں پھر اگر مقتول تھا ایسی قوم میں سےکہ وہ تمہارے دشمن ہیں اور خود وہ مسلمان تھا تو آزاد کرے گردن ایک مسلمان کی اور اگر وہ تھا ایسی قوم میں سےکہ تم میں اور ان میں عہد ہے تو خون بہا پہنچائے اس کےگھر والوں کو اور آزاد کرے گردن ایک مسلمان کی پھر جس کو میسر نہ ہو تو روزے رکھے دو مہینے کے برابر گناہ بخشوانے کو اللہ سے اور اللہ جاننے والا حکمت والا ہے  [۱۴۷]', 'It is not for a believer to kill a believer except (that it be) by mistake, and whosoever kills a believer by mistake, (it is ordained that) he must set free a believing slave and a compensation (blood money, i.e Diya) be given to the deceaseds family, unless they remit it. If the deceased belonged to a people at war with you and he was a believer; the freeing of a believing slave (is prescribed), and if he belonged to a people with whom you have a treaty of mutual alliance, compensation (blood money - Diya) must be paid to his family, and a believing slave must be freed. And whoso finds this (the penance of freeing a slave) beyond his means, he must fast for two consecutive months in order to seek repentance from Allah. And Allah is Ever AllKnowing, AllWise.', 'It is not for a believer (Muslim) to kill any believer, except by mistake. Whoever kills a believer by mistake, then, a believing slave has to be freed, and the blood money must be paid to his family, unless they forgo it.If he (the victim) belongs to a people hostile to you and is a believer, then, a believing slave has to be freed. If he (the victim) belongs to a people between whom and you there is treaty, then, blood money is to be paid to his family, and a believing slave to be freed. Whoever does not find one has to fast for two consecutive months. This is repentance prescribed from Allah’s side. Allah is All-Knowing, All-Wise.'),
(586, 4, 93, 13, 10, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ مَنۡ یَّقۡتُلۡ مُؤۡمِنًا مُّتَعَمِّدًا فَجَزَآؤُہٗ جَہَنَّمُ خٰلِدًا فِیۡہَا وَ غَضِبَ اللّٰہُ عَلَیۡہِ وَ لَعَنَہٗ وَ اَعَدَّ  لَہٗ عَذَابًا عَظِیۡمًا ﴿۹۳﴾', 'اور جو شخص کسی مسلمان کو قصداً مار ڈالے گا تو اسکی سزا دوزخ ہے جس میں وہ ہمیشہ جلتا رہے گا اور اللہ اس پر غضبناک ہوگا اور اس پر لعنت کرے گا اور ایسے شخص کے لئے اس نے بڑا سخت عذاب تیار کر رکھا ہے۔', 'اور جو کوئی قتل کرے مسلمان کو جان کر تو اس کی سزا دوزخ ہے پڑا رہے گا اسی میں اور اللہ کا اس پر غضب ہوا اور اس کو لعنت کی اور اسکے واسطے تیار کیا بڑا عذاب [۱۴۸]', 'And whoever kills a believer intentionally, his recompense is Hell to abide therein, and the Wrath and the Curse of Allah are upon him, and a great punishment is prepared for him.', 'Whoever kills a believer deliberately, his reward is Jahannam (Hell) where he shall remain forever, and Allah shall be angry with him and shall cast curse upon him, and He has prepared for him a mighty punishment.'),
(587, 4, 94, 13, 10, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اِذَا ضَرَبۡتُمۡ فِیۡ سَبِیۡلِ اللّٰہِ فَتَبَیَّنُوۡا وَ لَا تَقُوۡلُوۡا لِمَنۡ اَلۡقٰۤی اِلَیۡکُمُ السَّلٰمَ لَسۡتَ مُؤۡمِنًا ۚ تَبۡتَغُوۡنَ عَرَضَ الۡحَیٰوۃِ الدُّنۡیَا ۫ فَعِنۡدَ اللّٰہِ مَغَانِمُ کَثِیۡرَۃٌ ؕ کَذٰلِکَ کُنۡتُمۡ مِّنۡ قَبۡلُ فَمَنَّ اللّٰہُ عَلَیۡکُمۡ فَتَبَیَّنُوۡا ؕ اِنَّ اللّٰہَ کَانَ بِمَا تَعۡمَلُوۡنَ خَبِیۡرًا ﴿۹۴﴾', 'مومنو! جب تم اللہ کی راہ میں باہر نکلا کرو تو تحقیق سے کام لیا کرو اور جو شخص تم کو سلام کرے اس سے یہ نہ کہو کہ تم مومن نہیں ہو۔ کہ اس سے تمہاری غرض یہ ہو کہ دنیا کی زندگی کا فائدہ حاصل کرو۔ سو اللہ کے پاس بہت سی غنیمتیں ہیں تم بھی تو پہلے ایسے ہی تھے۔ پھر اللہ نے تم پر احسان کیا چنانچہ آئندہ تحقیق کر لیا کرو۔ بیشک جو عمل تم کرتے ہو اللہ کو سب کی خبر ہے۔', 'اے ایمان والو جب سفر کرو اللہ کی راہ میں تو تحقیق کر لیا کرو اور مت کہو اس شخص کو جو تم سے سلام علیک کرے کہ تو مسلمان نہیں تم چاہتے ہو اسباب دنیا کی زندگی کا سو اللہ کے ہاں بہت غنیمتیں ہیں [۱۴۹] تم بھی تو ایسے ہی تھے اس سے پہلے پھر اللہ نے تم پر فضل کیا سو اب تحقیق کر لو [۱۵۰] بیشک اللہ تمہارے کاموں سے خبردار ہے  [۱۵۱]', 'O you who believe! When you go (to fight) in the Cause of Allah, verify (the truth), and say not to anyone who greets you (by embracing Islam): \"You are not a believer\"; seeking the perishable goods of the worldly life. There are much more profits and booties with Allah. Even as he is now, so were you yourselves before till Allah conferred on you His Favours (i.e. guided you to Islam), therefore, be cautious in discrimination. Allah is Ever WellAware of what you do.', 'O you who believe, when you go out in the way of Allah, be careful, and do not say to the one who offers you the Salām (salutation), “You are not a believer” to seek stuff of the worldly life. So, with Allah there are spoils in abundance. In the same state you were before; then Allah favored you. So, be careful. Surely, Allah is All-Aware of what you do.'),
(588, 4, 95, 13, 10, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'لَا یَسۡتَوِی الۡقٰعِدُوۡنَ مِنَ الۡمُؤۡمِنِیۡنَ غَیۡرُ اُولِی الضَّرَرِ وَ الۡمُجٰہِدُوۡنَ فِیۡ سَبِیۡلِ اللّٰہِ بِاَمۡوَالِہِمۡ وَ اَنۡفُسِہِمۡ ؕ فَضَّلَ اللّٰہُ الۡمُجٰہِدِیۡنَ بِاَمۡوَالِہِمۡ وَ اَنۡفُسِہِمۡ عَلَی الۡقٰعِدِیۡنَ دَرَجَۃً ؕ وَ کُلًّا وَّعَدَ اللّٰہُ الۡحُسۡنٰی ؕ وَ فَضَّلَ اللّٰہُ الۡمُجٰہِدِیۡنَ عَلَی الۡقٰعِدِیۡنَ اَجۡرًا عَظِیۡمًا ﴿ۙ۹۵﴾', 'جو مسلمان گھروں میں بیٹھ رہتے اور لڑنے سے جی چراتے ہیں اور کوئی عذر نہیں رکھتے وہ اور جو اللہ کی راہ میں اپنے مال اور جان سے جہاد کرنے والے دونوں برابر نہیں ہو سکتے۔ مال اور جان سے جہاد کرنے والوں کو بیٹھ رہنے والوں پر اللہ نے درجے میں فضیلت بخشی ہے۔ اور بہترین انجام کا وعدہ اللہ نے سب سے کیا ہے اور اجر عظیم کے لحاظ سے اللہ نے جہاد کرنے والوں کو بیٹھ رہنے والوں پر کہیں فضیلت بخشی ہے۔', 'برابر نہیں بیٹھ رہنے والے مسلمان جن کو کوئی عذر نہیں اور وہ مسلمان جو لڑنے والے ہیں اللہ کی راہ میں اپنے مال سے اور جان سے اللہ نے بڑھا دیا لڑنے والوں کا اپنے مال اور جان سے بیٹھ رہنے والوں پر درجہ اور ہر ایک سے وعدہ کیا اللہ نے بھلائی کا اور زیادہ کیا اللہ نے لڑنے والوں کو بیٹھ رہنے والوں سے اجر عظیم میں', 'Not equal are those of the believers who sit (at home), except those who are disabled (by injury or are blind or lame, etc.), and those who strive hard and fight in the Cause of Allah with their wealth and their lives. Allah has preferred in grades those who strive hard and fight with their wealth and their lives above those who sit (at home). Unto each, Allah has promised good (Paradise), but Allah has preferred those who strive hard and fight, above those who sit (at home) by a huge reward;', 'Those among the believers who sit back, except the handicapped, are not equal to those who fight in the way of Allah with their riches and their lives.Allah has raised the rank of those who fight with their riches and their lives, over those who sit; and to each, Allah has promised good. Allah has given precedence to those who fight over those who sit in giving them a great reward'),
(589, 4, 96, 13, 10, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'دَرَجٰتٍ مِّنۡہُ وَ مَغۡفِرَۃً وَّ رَحۡمَۃً ؕ وَ کَانَ اللّٰہُ  غَفُوۡرًا  رَّحِیۡمًا ﴿٪۹۶﴾', 'یعنی اللہ کی طرف سے درجات میں اور بخشش میں اور رحمت میں۔ اور اللہ بڑا بخشنے والا ہے بڑا مہربان ہے۔', 'جو کہ درجے ہیں اللہ کی طرف سے اور بخشش ہے اور مہربانی ہے [۱۵۲] اور اللہ ہے بخشنے والا مہربان [۱۵۳]', 'Degrees of (higher) grades from Him, and Forgiveness and Mercy. And Allah is Ever OftForgiving, Most Merciful.', '- high ranks from Him and forgiveness and mercy. Allah is Most-Forgiving, Very-Merciful.'),
(590, 4, 97, 14, 11, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اِنَّ الَّذِیۡنَ تَوَفّٰہُمُ الۡمَلٰٓئِکَۃُ ظَالِمِیۡۤ اَنۡفُسِہِمۡ قَالُوۡا فِیۡمَ کُنۡتُمۡ ؕ قَالُوۡا کُنَّا مُسۡتَضۡعَفِیۡنَ فِی الۡاَرۡضِ ؕ قَالُوۡۤا اَلَمۡ تَکُنۡ اَرۡضُ اللّٰہِ وَاسِعَۃً فَتُہَاجِرُوۡا فِیۡہَا ؕ فَاُولٰٓئِکَ مَاۡوٰىہُمۡ جَہَنَّمُ ؕ وَ سَآءَتۡ مَصِیۡرًا ﴿ۙ۹۷﴾', 'جو لوگ اپنی جانوں پر ظلم کرتے ہیں جب فرشتے ان کی جان قبض کرنے لگتے ہیں تو ان سے پوچھتے ہیں کہ تم کس حال میں تھے۔ وہ کہتے ہیں کہ ہم ملک میں عاجز و ناتواں تھے۔ فرشتے کہتے ہیں کیا اللہ کا ملک فراخ نہیں تھا کہ تم اس میں ہجرت کر جاتے۔ پس ایسے لوگوں کا ٹھکانہ دوزخ ہے اور وہ بری جگہ ہے لوٹنے کی۔', 'وہ لوگ کہ جن کی جان نکالتے ہیں فرشتے اس حالت میں کہ وہ برا کر رہے ہیں اپنا کہتے ہیں ان سے فرشتے تم کس حال میں تھے وہ کہتے ہیں ہم تھے بے بس اس ملک میں کہتے ہیں فرشتے کیا نہ تھی زمین اللہ کی کشادہ جو چلے جاتے وطن چھوڑ کر وہاں سو ایسوں کا ٹھکانا ہے دوزخ اور وہ بہت بری جگہ پہنچے', 'Verily! As for those whom the angels take (in death) while they are wronging themselves (as they stayed among the disbelievers even though emigration was obligatory for them), they (angels) say (to them): \"In what (condition) were you?\" They reply: \"We were weak and oppressed on earth.\" They (angels) say: \"Was not the earth of Allah spacious enough for you to emigrate therein?\" Such men will find their abode in Hell - What an evil destination!', 'Those whose souls the angels take while they had wronged themselves, the angels say (to them), “In what business were you (involved)?” They say, “We were oppressed in the earth.” They say, “Was not the earth of Allah wide enough for you to emigrate to it?” Those people are such that their refuge is Jahannam . It is an evil place to return;'),
(591, 4, 98, 14, 11, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اِلَّا الۡمُسۡتَضۡعَفِیۡنَ مِنَ الرِّجَالِ وَ النِّسَآءِ وَ الۡوِلۡدَانِ لَا یَسۡتَطِیۡعُوۡنَ حِیۡلَۃً  وَّ لَا  یَہۡتَدُوۡنَ سَبِیۡلًا ﴿ۙ۹۸﴾', 'ہاں جو مرد اور عورتیں اور بچے بےبس ہیں کہ نہ تو کوئی تدبیر کر سکتے ہیں اور نہ رستہ ہی جانتے ہیں۔', 'مگر جو ہیں بےبس مردوں اور عورتوں اور بچوں میں سے جو نہیں کر سکتے کوئی تدبیر اور نہ جانتےہیں کہیں کا راستہ', 'Except the weak ones among men, women and children who cannot devise a plan, nor are they able to direct their way', 'except the oppressed men and women and children, who cannot have means (to emigrate), nor can find a way.'),
(592, 4, 99, 14, 11, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'فَاُولٰٓئِکَ عَسَی اللّٰہُ اَنۡ یَّعۡفُوَ عَنۡہُمۡ ؕ وَ کَانَ اللّٰہُ عَفُوًّا غَفُوۡرًا ﴿۹۹﴾', 'تو قریب ہے کہ اللہ ایسوں کو معاف کر دے۔ اور اللہ بڑا معاف کرنے والا ہے  بڑا بخشنے والا ہے۔', 'سو ایسوں کو امید ہے کہ اللہ معاف کرے اور اللہ ہے معاف کرنے والا بخشنے والا [۱۵۴]', 'For these there is hope that Allah will forgive them, and Allah is Ever Oft Pardoning, Oft-Forgiving.', 'As for such, it is likely that Allah would pardon them. Allah is Most-Pardoning, Most-Forgiving.'),
(593, 4, 100, 14, 11, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ مَنۡ یُّہَاجِرۡ فِیۡ سَبِیۡلِ اللّٰہِ یَجِدۡ فِی الۡاَرۡضِ مُرٰغَمًا کَثِیۡرًا وَّ سَعَۃً ؕ وَ مَنۡ یَّخۡرُجۡ مِنۡۢ بَیۡتِہٖ مُہَاجِرًا  اِلَی اللّٰہِ وَ رَسُوۡلِہٖ ثُمَّ  یُدۡرِکۡہُ الۡمَوۡتُ فَقَدۡ وَقَعَ اَجۡرُہٗ عَلَی اللّٰہِ ؕ وَ کَانَ اللّٰہُ غَفُوۡرًا رَّحِیۡمًا ﴿۱۰۰﴾٪', 'اور جو شخص اللہ کی راہ میں گھر بار چھوڑ جائے وہ زمین میں بہت سی رہنے کی جگہ اور کشائش پائے گا۔ اور جو شخص اللہ اور اسکے رسول کی طرف ہجرت کر کے گھر سے نکل جائے پھر اس کو موت آ پکڑے۔ تو اسکا ثواب اللہ کے ذمے ہو چکا۔ اور اللہ بڑا بخشنے والا ہے بڑا مہربان ہے۔', 'اور جو کوئی وطن چھوڑے اللہ کی راہ میں پاوے گا اس کے مقابلہ میں جگہ بہت اور کشائش اور جو کوئی نکلے اپنے گھر سے ہجرت کر کے اللہ اور رسول کی طرف پھر آ پکڑے اس کو موت تو مقرر ہو چکا اس کا ثواب اللہ کے ہاں اور ہے اللہ بخشنے والا مہربان [۱۵۵]', 'He who emigrates (from his home) in the Cause of Allah, will find on earth many dwelling places and plenty to live by. And whosoever leaves his home as an emigrant unto Allah and His Messenger, and death overtakes him, his reward is then surely incumbent upon Allah. And Allah is Ever OftForgiving, Most Merciful.', 'Whoever migrates in the way of Allah shall find on the earth many a place to settle, and a wide dimension (of resources). Whoever leaves his home migrating for the sake of Allah and His Messenger, and death overtakes him, then, his reward is established with Allah. Allah is Most-Forgiving, Very-Merciful.'),
(594, 4, 101, 15, 12, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ اِذَا ضَرَبۡتُمۡ فِی الۡاَرۡضِ فَلَیۡسَ عَلَیۡکُمۡ جُنَاحٌ اَنۡ تَقۡصُرُوۡا مِنَ الصَّلٰوۃِ ٭ۖ اِنۡ خِفۡتُمۡ اَنۡ یَّفۡتِنَکُمُ الَّذِیۡنَ کَفَرُوۡا ؕ اِنَّ الۡکٰفِرِیۡنَ کَانُوۡا لَکُمۡ عَدُوًّا مُّبِیۡنًا ﴿۱۰۱﴾', 'اور جب تم سفر کو جاؤ تو تم پر کچھ گناہ نہیں کہ نماز کو کم کر کے پڑھو۔ بشرطیکہ تم کو خوف ہو کہ کافر لوگ تم کو ستائیں گے۔ بیشک کافر تمہارے کھلے دشمن ہیں۔', 'اور جب تم سفر کرو ملک میں تو تم پر گناہ نہیں کہ کچھ کم کرو نماز میں سےاگر تم کو ڈر ہو کہ ستاویں گے تم کو کافر البتہ کافر تمہارے صریح دشمن ہیں [۱۵۶]', 'And when you (Muslims) travel in the land, there is no sin on you if you shorten your Salat (prayer) if you fear that the disbelievers may attack you, verily, the disbelievers are ever unto you open enemies.', 'When you travel on the earth, there is no sin on you in shortening your Salāh, if you fear that the disbelievers would put you in trouble. Surely, the disbelievers are an open enemy for you.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(595, 4, 102, 15, 12, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ اِذَا کُنۡتَ فِیۡہِمۡ فَاَقَمۡتَ لَہُمُ الصَّلٰوۃَ فَلۡتَقُمۡ طَآئِفَۃٌ مِّنۡہُمۡ مَّعَکَ وَ لۡیَاۡخُذُوۡۤا اَسۡلِحَتَہُمۡ ۟ فَاِذَا سَجَدُوۡا فَلۡیَکُوۡنُوۡا مِنۡ وَّرَآئِکُمۡ ۪ وَ لۡتَاۡتِ طَآئِفَۃٌ اُخۡرٰی لَمۡ یُصَلُّوۡا فَلۡیُصَلُّوۡا مَعَکَ وَ لۡیَاۡخُذُوۡا حِذۡرَہُمۡ وَ اَسۡلِحَتَہُمۡ ۚ وَدَّ الَّذِیۡنَ کَفَرُوۡا لَوۡ تَغۡفُلُوۡنَ عَنۡ اَسۡلِحَتِکُمۡ وَ اَمۡتِعَتِکُمۡ فَیَمِیۡلُوۡنَ عَلَیۡکُمۡ مَّیۡلَۃً وَّاحِدَۃً ؕ وَ لَا جُنَاحَ عَلَیۡکُمۡ اِنۡ کَانَ بِکُمۡ اَذًی مِّنۡ مَّطَرٍ اَوۡ کُنۡتُمۡ مَّرۡضٰۤی اَنۡ تَضَعُوۡۤا اَسۡلِحَتَکُمۡ ۚ وَ خُذُوۡا حِذۡرَکُمۡ ؕ اِنَّ اللّٰہَ اَعَدَّ لِلۡکٰفِرِیۡنَ عَذَابًا مُّہِیۡنًا ﴿۱۰۲﴾', 'اور اے پیغمبر جب تم ان مجاہدین کے لشکر میں ہو اور ان کو نماز پڑھانے لگو تو چاہیے کہ ان کی ایک جماعت تمہارے ساتھ مسلح ہو کر کھڑی رہے۔ جب وہ سجدہ کر چکیں تو تم سے پیچھے چلے جائیں اور دوسری جماعت جس نے نماز نہیں پڑھی ان کی جگہ آئے اور ہوشیار اور مسلح ہو کر تمہارے ساتھ نماز ادا کرے۔ کافر تو چاہتے ہی ہیں کہ تم ذرا اپنے ہتھیاروں اور سامان سے غافل ہو جاؤ کہ تم پر یکبارگی حملہ کر دیں۔اور اگر تم بارش کے سبب تکلیف میں ہو یا بیمار ہو تو تم پر کچھ گناہ نہیں کہ ہتھیار اتار رکھو مگر اپنا بچاؤ ضرور کر رکھو۔ اللہ نے کافروں کیلئے ذلت کا عذاب تیار کر رکھا ہے۔', 'اور جب تو ان میں موجود ہو پھر نماز میں کھڑا کرے تو چاہئے ایک جماعت ان کی کھڑی ہو تیرے ساتھ اور ساتھ لے لیویں اپنے ہتھیار پھر جب یہ سجدہ کریں تو ہٹ جاویں تیرے پاس سے اور آوے دوسری جماعت جس نے نماز نہیں پڑھی وہ نماز پڑھیں تیرے ساتھ اور ساتھ لیویں اپنا بچاؤ اور ہتھیار کافر چاہتے ہیں کسی طرح تم بے خبر ہو اپنے ہتھیاروں سے اور اسباب سے تاکہ تم پر حملہ کریں یکبارگی [۱۵۷] اور تم پر کچھ گناہ نہیں اگر تم کو تکلیف ہو مینہ سے یا تم بیمار ہو کہ اتار رکھو اپنے ہتھیار اور ساتھ لے لو اپنا بچاؤ [۱۵۸] بیشک اللہ نے تیار کر رکھا ہے کافروں کے واسطے عذاب ذلت کا [۱۵۹]', 'When you (O Messenger Muhammad SAW) are among them, and lead them in As-Salat (the prayer), let one party of them stand up (in Salat (prayer)) with you taking their arms with them; when they finish their prostrations, let them take their positions in the rear and let the other party come up which has not yet prayed, and let them pray with you taking all the precautions and bearing arms. Those who disbelieve wish, if you were negligent of your arms and your baggage, to attack you in a single rush, but there is no sin on you if you put away your arms because of the inconvenience of rain or because you are ill, but take every precaution for yourselves. Verily, Allah has prepared a humiliating torment for the disbelievers.', 'When you (O prophet) are in their midst, and arrange for them the Salāh, then, a party from them should stand with you, and should take their arms along. Then, once they performed Sajdah, they should move away from you, and the other party, that has not yet performed Salāh, should come and perform Salāh with you, and should take their precautionary measures and their arms. Those who disbelieve would want you to become heedless to your arms and your belongings, so that they come down upon you in a single move. There is no sin on you, if you have some inconvenience due to rain, or you are sick, in putting your arms aside, but take your precautionary measures. Surely, Allah has prepared for the disbelievers a humiliating punishment.'),
(596, 4, 103, 15, 12, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'فَاِذَا قَضَیۡتُمُ الصَّلٰوۃَ فَاذۡکُرُوا اللّٰہَ قِیٰمًا وَّ قُعُوۡدًا وَّ عَلٰی جُنُوۡبِکُمۡ ۚ فَاِذَا اطۡمَاۡنَنۡتُمۡ فَاَقِیۡمُوا الصَّلٰوۃَ ۚ اِنَّ الصَّلٰوۃَ  کَانَتۡ عَلَی الۡمُؤۡمِنِیۡنَ  کِتٰبًا مَّوۡقُوۡتًا ﴿۱۰۳﴾', 'پھر جب تم یہ نماز تمام کر چکو تو کھڑے اور بیٹھے اور لیٹے ہر حالت میں اللہ کو یاد کرو۔ پھر جب تم مطمئن ہو جاؤ تو پورے آداب کے ساتھ نماز پڑھو بیشک نماز کا مومنوں پر اوقات مقررہ میں ادا کرنا فرض ہے۔', 'پھر جن تم نماز پڑھ چکو تو یاد کرو اللہ کو کھڑے اور بیٹھے اور لیٹے [۱۶۰]  پھر جب خوف جاتا رہے تو درست کرو نماز کو بیشک نماز مسلمانوں پر فرض ہے اپنے مقررہ وقتوں میں [۱۶۱]', 'When you have finished As-Salat (the prayer - congregational), remember Allah standing, sitting down, and lying down on your sides, but when you are free from danger, perform As-Salat (Iqamatas Salat). Verily, the prayer is enjoined on the believers at fixed hours.', 'Once you have finished your Salāh, then, remember Allah while standing, sitting and reclining. As soon as you are secure, perform Salāh as due. Surely, Salāh is an obligation on the believers that is tied up with time.'),
(597, 4, 104, 15, 12, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ لَا تَہِنُوۡا فِی ابۡتِغَآءِ الۡقَوۡمِ ؕ اِنۡ تَکُوۡنُوۡا تَاۡلَمُوۡنَ فَاِنَّہُمۡ یَاۡلَمُوۡنَ کَمَا تَاۡلَمُوۡنَ ۚ وَ تَرۡجُوۡنَ مِنَ اللّٰہِ مَا لَا یَرۡجُوۡنَ ؕ وَ کَانَ اللّٰہُ  عَلِیۡمًا  حَکِیۡمًا ﴿۱۰۴﴾٪', 'اور ان کفار کا پیچھا کرنے میں سستی نہ کرنا۔ اگر تم بےآرام ہوتے ہو تو جس طرح تم بےآرام ہوتے ہو اسی طرح وہ بھی بےآرام ہوتے ہیں اور تم تو اللہ سے ایسی ایسی امیدیں رکھتے ہو جو وہ نہیں رکھتے اور اللہ سب کچھ جانتا ہے بڑی حکمت والا ہے۔', 'اور ہمت نہ ہارو ان کا پیچھا کرنے سے اگر تم بے آرام ہوتے ہو تو وہ بھی بے آرام ہوتے ہیں جس طرح تم ہوتے ہو اور تم کو اللہ سے امید ہے جو ان کو نہیں اور اللہ سب کچھ جاننے والا حکمت والا ہے [۱۶۲]', 'And dont be weak in the pursuit of the enemy; if you are suffering (hardships) then surely, they (too) are suffering (hardships) as you are suffering, but you have a hope from Allah (for the reward, i.e. Paradise) that for which they hope not, and Allah is Ever AllKnowing, AllWise.', 'Do not show weakness in pursuing these people. If you are suffering, they are suffering as you are suffering, while you hope from Allah what they do not hope. Allah is All-Knowing, All-Wise.'),
(598, 4, 105, 16, 13, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اِنَّاۤ اَنۡزَلۡنَاۤ اِلَیۡکَ الۡکِتٰبَ بِالۡحَقِّ لِتَحۡکُمَ بَیۡنَ النَّاسِ بِمَاۤ  اَرٰىکَ اللّٰہُ ؕ وَ لَا تَکُنۡ  لِّلۡخَآئِنِیۡنَ خَصِیۡمًا ﴿۱۰۵﴾ۙ', 'اے پیغمبر ہم نے تم پر سچّی کتاب نازل کی ہے تا کہ اللہ کی ہدایات کے مطابق لوگوں کے مقدمات فیصل کرو اور دیکھو دغابازوں کی حمایت میں کبھی بحث نہ کرنا۔', 'بیشک ہم نے اتاری تیری طرف کتاب سچی کہ تو انصاف کرے لوگوں میں جو کچھ سمجھاوے تجھ کو اللہ اور تو مت ہو دغابازوں کی طرف سے جھگڑنے والا [۱۶۳]', 'Surely, We have sent down to you (O Muhammad SAW) the Book (this Quran) in truth that you might judge between men by that which Allah has shown you (i.e. has taught you through Divine Inspiration), so be not a pleader for the treacherous.', 'Surely, We have revealed to you the Book with the truth, so that you may judge between people according to what Allah has shown you. Do not be an advocate for those who breach trust.'),
(599, 4, 106, 16, 13, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَّ اسۡتَغۡفِرِ اللّٰہَ ؕ اِنَّ اللّٰہَ کَانَ غَفُوۡرًا رَّحِیۡمًا ﴿۱۰۶﴾ۚ', 'اور اللہ سے بخشش مانگتے رہو۔ بیشک اللہ بخشنے والا ہے بڑا مہربان ہے۔', 'اور بخشش مانگ اللہ سے بیشک اللہ بخشنے والا مہربان ہے [۱۶۴]', 'And seek the Forgiveness of Allah, certainly, Allah is Ever OftForgiving, Most Merciful.', 'Seek forgiveness from Allah. Surely, Allah is All-Forgiving, Very-Merciful.'),
(600, 4, 107, 16, 13, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ لَا تُجَادِلۡ عَنِ الَّذِیۡنَ یَخۡتَانُوۡنَ اَنۡفُسَہُمۡ ؕ اِنَّ اللّٰہَ  لَا یُحِبُّ مَنۡ کَانَ خَوَّانًا اَثِیۡمًا ﴿۱۰۷﴾ۚۙ', 'اور جو لوگ اپنے ہم جنسوں کی خیانت کرتے ہیں انکی طرف سے بحث نہ کرنا کیونکہ اللہ دغاباز اور گناہگار کو دوست نہیں رکھتا۔', 'اور مت جھگڑ ان کی طرف سے جو اپنے جی میں دغا رکھتے ہیں اللہ کو پسند نہیں جو کوئی ہو دغاباز گنہگار', 'And argue not on behalf of those who deceive themselves. Verily, Allah does not like anyone who is a betrayer of his trust, and indulges in crime.', 'Do not argue on behalf of those who betray themselves. Surely, Allah does not like anyone who is a sinful betrayer.'),
(601, 4, 108, 16, 13, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'یَّسۡتَخۡفُوۡنَ مِنَ النَّاسِ وَ لَا یَسۡتَخۡفُوۡنَ مِنَ اللّٰہِ وَ ہُوَ  مَعَہُمۡ  اِذۡ  یُبَیِّتُوۡنَ مَا لَا یَرۡضٰی مِنَ الۡقَوۡلِ ؕ وَ کَانَ اللّٰہُ بِمَا یَعۡمَلُوۡنَ  مُحِیۡطًا ﴿۱۰۸﴾', 'یہ لوگوں سے تو چھپتے ہیں اور اللہ سے نہیں چھپتے حالانکہ جب یہ راتوں کو ایسی باتوں کے مشورے کیا کرتے ہیں جنکو وہ پسند نہیں کرتا تو وہ انکے ساتھ ہوا کرتا ہے۔ اور اللہ انکے تمام کاموں کا احاطہ کئے ہوئے ہے۔', 'شرماتےہیں لوگوں سے اور نہیں شرماتے اللہ سے اور وہ انکے ساتھ ہے جبکہ مشورہ کرتے ہیں رات کو اس بات کا جس سے اللہ راضی نہیں اور جو کچھ وہ کرتے ہیں سب اللہ کے قابو میں ہے [۱۶۵]', 'They may hide (their crimes) from men, but they cannot hide (them) from Allah, for He is with them (by His Knowledge), when they plot by night in words that He does not approve, And Allah ever encompasses what they do.', 'They feel shy before people, but do not feel shy before Allah. He (Allah) is with them when they make plans at night to give a statement He (Allah) does not like. Allah encompasses whatever they do.'),
(602, 4, 109, 16, 13, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'ہٰۤاَنۡتُمۡ ہٰۤؤُلَآءِ جٰدَلۡتُمۡ عَنۡہُمۡ فِی الۡحَیٰوۃِ الدُّنۡیَا ۟ فَمَنۡ یُّجَادِلُ اللّٰہَ عَنۡہُمۡ یَوۡمَ الۡقِیٰمَۃِ  اَمۡ مَّنۡ یَّکُوۡنُ عَلَیۡہِمۡ  وَکِیۡلًا ﴿۱۰۹﴾', 'بھلا تم لوگ دنیا کی زندگی میں تو ان کی طرف سے بحث کر لیتے ہو۔ سو قیامت کے دن انکی طرف سے اللہ کے ساتھ کون بحث کرے گا اور کون ان کا وکیل بنے گا۔', 'سنتے ہو تم لوگ جھگڑا کرتے ہو ان کی طرف سے دنیا کی زندگی میں پھر کون جھگڑا کرے گا ان کے بدلے اللہ سے قیامت کے دن یا کون ہو گا ان کا کارساز [۱۶۶]', 'Lo! You are those who have argued for them in the life of this world, but who will argue for them on the Day of Resurrection against Allah, or who will then be their defender?', 'Look, this is what you are! You have argued for them in the worldly life, but who shall argue for them with Allah on the Day of Judgement, or who shall be their defender?'),
(603, 4, 110, 16, 13, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ مَنۡ یَّعۡمَلۡ سُوۡٓءًا اَوۡ یَظۡلِمۡ  نَفۡسَہٗ ثُمَّ یَسۡتَغۡفِرِ اللّٰہَ یَجِدِ اللّٰہَ غَفُوۡرًا رَّحِیۡمًا ﴿۱۱۰﴾', 'اور جو شخص کوئی برا کام کر بیٹھے یا اپنے حق میں ظلم کر لے پھر اللہ سے بخشش مانگے تو اللہ کو بڑا بخشنے والا بڑا مہربان پائے گا۔', 'اور جو کوئی کرے گناہ یا اپنا برا کرے پھر اللہ سے بخشوا دے تو پاوے اللہ کو بخشنے والا مہربان [۱۶۷]', 'And whoever does evil or wrongs himself but afterwards seeks Allahs Forgiveness, he will find Allah OftForgiving, Most Merciful.', 'Whoever acts evil or wrongs himself, then seeks forgiveness from Allah, shall find Allah Most-Forgiving, Very-Merciful.'),
(604, 4, 111, 16, 13, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ مَنۡ یَّکۡسِبۡ اِثۡمًا فَاِنَّمَا یَکۡسِبُہٗ عَلٰی نَفۡسِہٖ ؕ وَ کَانَ اللّٰہُ عَلِیۡمًا حَکِیۡمًا ﴿۱۱۱﴾', 'اور جو کوئی گناہ کرتا ہے تو اس کا وبال اسی پر ہے اور اللہ سب کچھ جاننے والا ہے حکمت والا ہے۔', 'اور جو کوئی کرے گناہ سو کرتا ہے اپنے ہی حق میں اور اللہ سب کچھ جاننے والا حکمت والا ہے [۱۶۸]', 'And whoever earns sin, he earns it only against himself. And Allah is Ever AllKnowing, AllWise.', 'Whoever commits a sin, commits it only against himself. Allah is All-Knowing, All-Wise.'),
(605, 4, 112, 16, 13, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ مَنۡ یَّکۡسِبۡ خَطِیۡٓىـَٔۃً اَوۡ اِثۡمًا ثُمَّ یَرۡمِ بِہٖ بَرِیۡٓــًٔا فَقَدِ احۡتَمَلَ بُہۡتَانًا وَّ اِثۡمًا مُّبِیۡنًا ﴿۱۱۲﴾٪', 'اور جو شخص کوئی قصور یا گناہ تو خود کرے لیکن اس کا الزام کسی بے گناہ پر ڈال دے تو اس نے بہتان اور کھلے گناہ کا بوجھ اپنے سر پر رکھا۔', 'اور جو کوئی کرے خطا یا گناہ پھر تمہت لگاوے کسی بے گناہ پر تو اس نے اپنے سر دھرا طوفان اور گناہ صریح [۱۶۹]', 'And whoever earns a fault or a sin and then throws it on to someone innocent, he has indeed burdened himself with falsehood and a manifest sin.', 'Whoever commits a vice or a sin, then shifts its blame to an innocent person, he indeed takes the burden of a false imputation and a glaring sin.'),
(606, 4, 113, 17, 14, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ لَوۡ لَا فَضۡلُ اللّٰہِ عَلَیۡکَ وَ رَحۡمَتُہٗ لَہَمَّتۡ طَّآئِفَۃٌ مِّنۡہُمۡ اَنۡ یُّضِلُّوۡکَ ؕ وَ مَا یُضِلُّوۡنَ  اِلَّاۤ اَنۡفُسَہُمۡ وَ مَا یَضُرُّوۡنَکَ مِنۡ شَیۡءٍ ؕ وَ اَنۡزَلَ اللّٰہُ عَلَیۡکَ الۡکِتٰبَ وَ الۡحِکۡمَۃَ وَ عَلَّمَکَ مَا لَمۡ تَکُنۡ تَعۡلَمُ ؕ وَ کَانَ فَضۡلُ اللّٰہِ عَلَیۡکَ عَظِیۡمًا ﴿۱۱۳﴾', 'اور اے نبی اگر تم پر اللہ کا فضل اور اسکی مہربانی نہ ہوتی تو ان میں سے ایک جماعت تم کو بہکانے کا قصد کر ہی چکی تھی۔ اور یہ اپنے سوا کسی کو بہکا نہیں سکتے اور نہ تمہارا کچھ بگاڑ سکتے ہیں۔ اور اللہ نے تم پر کتاب اور حکمت نازل فرمائی ہے اور تمہیں وہ باتیں سکھائی ہیں جو تم جانتے نہیں تھے اور تم پر تو اللہ کا بڑا فضل رہا ہے۔', 'اور اگر نہ ہوتا تجھ پر اللہ کا فضل اور اس کی رحمت تو قصد کر ہی چکی تھی ان میں ایک جماعت کہ تجھ کو بہکاویں اور بہکا نہیں سکتے مگر اپنے آپ کو اور تیرا کچھ نہیں بگاڑ سکتے اور اللہ نےاتاری تجھ پر کتاب اور حکمت اور تجھ کو سکھائیں وہ باتیں جو تو نہ جانتا تھا اور اللہ کا فضل تجھ پر بہت بڑا ہے [۱۷۰]', 'Had not the Grace of Allah and His Mercy been upon you (O Muhammad SAW), a party of them would certainly have made a decision to mislead you, but (in fact) they mislead none except their own selves, and no harm can they do to you in the least. Allah has sent down to you the Book (The Quran), and AlHikmah (Islamic laws, knowledge of legal and illegal things i.e. the Prophets Sunnah - legal ways), and taught you that which you knew not. And Ever Great is the Grace of Allah unto you (O Muhammad SAW).', 'If the grace of Allah and His mercy had not been with you, a group from them had resolved to mislead you, while they mislead none but themselves; and they can do you no harm. Allah has revealed to you the Book and the wisdom, and has taught you what you did not know. The grace of Allah on you has always been great.'),
(607, 4, 114, 17, 14, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'لَا  خَیۡرَ  فِیۡ  کَثِیۡرٍ  مِّنۡ نَّجۡوٰىہُمۡ  اِلَّا مَنۡ اَمَرَ بِصَدَقَۃٍ اَوۡ مَعۡرُوۡفٍ اَوۡ اِصۡلَاحٍۭ  بَیۡنَ النَّاسِ ؕ وَ مَنۡ یَّفۡعَلۡ ذٰلِکَ ابۡتِغَآءَ مَرۡضَاتِ اللّٰہِ فَسَوۡفَ نُؤۡتِیۡـہِ اَجۡرًا عَظِیۡمًا ﴿۱۱۴﴾', 'ان لوگوں کی بہت سی سرگوشیاں اچھی نہیں ہاں اس شخص کی سرگوشی اچھی ہو سکتی ہے جو خیرات یا نیک بات یا لوگوں میں صلح کرنے کو کہے۔ اور جو ایسے کام اللہ کی خوشنودی حاصل کرنے کے لئے کرے گا تو ہم اس کو بڑا ثواب دیں گے۔', 'کچھ اچھے نہیں ان کےاکثر مشورے مگر جو کوئی کہ کہے صدقہ کرنے کو یا نیک کام کو یا صلح کرانے کو لوگوں میں اور جو کوئی یہ کام کرے اللہ کی خوشی کے لئے تو ہم اس کو دیں گے بڑا ثواب [۱۷۱]', 'There is no good in most of their secret talks save (in) him who orders Sadaqah (charity in Allahs Cause), or Maroof (Islamic Monotheism and all the good and righteous deeds which Allah has ordained), or conciliation between mankind, and he who does this, seeking the good Pleasure of Allah, We shall give him a great reward.', 'There is no good in most of their whisperings, unless one bids charity or a fair action, or reconciliation between people. The one who does this, to seek Allah’s pleasure, We shall give him a great reward.'),
(608, 4, 115, 17, 14, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ مَنۡ یُّشَاقِقِ الرَّسُوۡلَ مِنۡۢ بَعۡدِ مَا تَبَیَّنَ لَہُ الۡہُدٰی وَ یَتَّبِعۡ غَیۡرَ  سَبِیۡلِ الۡمُؤۡمِنِیۡنَ نُوَلِّہٖ مَا تَوَلّٰی وَ نُصۡلِہٖ جَہَنَّمَ ؕ وَ سَآءَتۡ مَصِیۡرًا ﴿۱۱۵﴾٪', 'اور جو شخص سیدھا رستہ معلوم ہونے کے بعد پیغمبر کی مخالفت کرے اور مومنوں کے رستے کے سوا کسی اور رستے پر چلے تو جدھر وہ چلتا ہے ہم اسے ادھر ہی چلا دیں گے اور قیامت کے دن اسے جہنم میں داخل کریں گے۔ اور وہ بری جگہ ہے۔', 'اور جو کوئی مخالفت کرے رسول کی جبکہ کھل چکی اس پر سیدھی راہ اور چلے سب مسلمانوں کے رستہ کے خلاف تو ہم حوالہ کریں گے اس کو وہی طرف جو اس نے اختیار کی اور ڈالیں گے ہم اس کو دوزخ میں اور وہ بہت بری جگہ پہنچا [۱۷۲]', 'And whoever contradicts and opposes the Messenger (Muhammad SAW) after the right path has been shown clearly to him, and follows other than the believers way. We shall keep him in the path he has chosen, and burn him in Hell - what an evil destination.', 'Whoever breaks away with the Messenger after the right path has become clear to him, and follows what is not the way of the believers, We shall let him have what he chose, and We shall admit him to Jahannam, which is an evil place to return.'),
(609, 4, 116, 18, 15, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اِنَّ اللّٰہَ لَا یَغۡفِرُ اَنۡ یُّشۡرَکَ بِہٖ وَ یَغۡفِرُ مَا دُوۡنَ ذٰلِکَ لِمَنۡ یَّشَآءُ ؕ وَ مَنۡ یُّشۡرِکۡ بِاللّٰہِ فَقَدۡ  ضَلَّ  ضَلٰلًۢا  بَعِیۡدًا ﴿۱۱۶﴾', 'اللہ اس گناہ کو نہیں بخشے گا کہ کسی کو اسکا شریک بنایا جائے اور اسکے سوا اور گناہ جس کو چاہے گا بخش دے گا۔ اور جس نے اللہ کے ساتھ شریک بنایا تو بیشک وہ رستے سے دور جا پڑا۔', 'بیثک اللہ نہیں بخشتا اس کو جو اس کا شریک کرے کسی کو اور بخشتا ہے اس کے سوا جس کو چاہے [۱۷۳] اور جس نے شریک ٹھرایا اللہ کا وہ بہک کر دور جا پڑا [۱۷۴]', 'Verily! Allah forgives not (the sin of) setting up partners in worship with Him, but He forgives whom he pleases sins other than that, and whoever sets up partners in worship with Allah, has indeed strayed far away.', 'Surely, Allah does not forgive that a partner is ascribed to Him, and forgives anything short of that for whomsoever He wills. Whoever ascribes a partner to Allah has indeed gone far astray.'),
(610, 4, 117, 18, 15, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اِنۡ یَّدۡعُوۡنَ مِنۡ دُوۡنِہٖۤ  اِلَّاۤ اِنٰثًا ۚ وَ اِنۡ یَّدۡعُوۡنَ  اِلَّا شَیۡطٰنًا مَّرِیۡدًا ﴿۱۱۷﴾ۙ', 'یہ لوگ اللہ کے سوا جو پرستش کرتے ہیں تو کچھ دیویوں کی۔ اور پکارتے بھی ہیں تو شیطان سرکش ہی کو۔', 'اللہ کے سوا نہیں پکارتے مگر عورتوں کو اور نہیں پکارتے مگر شیطان سرکش کو', 'They (all those who worship others than Allah) invoke nothing but female deities besides Him (Allah), and they invoke nothing but Shaitan (Satan), a persistent rebel!', 'They invoke none, besides Him, but feminine objects; and they invoke none but Satan, the rebel'),
(611, 4, 118, 18, 15, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'لَّعَنَہُ اللّٰہُ ۘ وَ قَالَ لَاَتَّخِذَنَّ مِنۡ عِبَادِکَ نَصِیۡبًا مَّفۡرُوۡضًا ﴿۱۱۸﴾ۙ', 'جس پر اللہ نے لعنت کی ہے اور وہ اللہ سے کہنے لگا میں تیرے بندوں سے غیر اللہ کی نیاز دلوا کر مال کا ایک مقرر حصہ لے لیا کروں گا۔', 'جس پر لعنت کی اللہ نے [۱۷۵] اور کہا شیطان نے کہ میں البتہ لوں گا تیرے بندوں سےحصہ مقررہ [۱۷۶]', 'Allah cursed him. And he (Shaitan (Satan)) said: \"I will take an appointed portion of your slaves;', 'whom Allah has cursed. He (the Satan) said, “Surely I will take an appointed share from Your slaves,'),
(612, 4, 119, 18, 15, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَّ لَاُضِلَّنَّہُمۡ وَ لَاُمَنِّیَنَّہُمۡ وَ لَاٰمُرَنَّہُمۡ فَلَیُبَتِّکُنَّ اٰذَانَ الۡاَنۡعَامِ وَ لَاٰمُرَنَّہُمۡ فَلَیُغَیِّرُنَّ خَلۡقَ اللّٰہِ ؕ وَ مَنۡ یَّتَّخِذِ الشَّیۡطٰنَ وَلِیًّا مِّنۡ دُوۡنِ اللّٰہِ فَقَدۡ خَسِرَ  خُسۡرَانًا مُّبِیۡنًا  ﴿۱۱۹﴾ؕ', 'اور ان کو گمراہ کرتا اور انہیں امیدیں دلاتا رہوں گا اور یہ سکھاتا رہوں گا کہ جانوروں کے کان چیرتے رہیں اور انہیں سمجھاتا رہوں گا تو وہ اللہ کی بنائی ہوئی صورتوں کو بگاڑتے رہیں گے۔ اور جس شخص نے اللہ کو چھوڑ کر شیطان کو دوست بنایا وہ صاف صاف گھاٹے میں رہا۔', 'اور انکو بہکاؤں گا اور انکو امیدیں دلاؤں گا اور انکو سکھلاؤں گا کہ چیریں جانوروں کے کان اور انکو سکھلاؤں گا کہ بدلیں صورتیں بنائی ہوئی اللہ کی [۱۷۷] اور جو کوئی بناوے شیطان کو دوست اللہ کو چھوڑ کر تو وہ پڑا صریح نقصان میں', 'Verily, I will mislead them, and surely, I will arouse in them false desires; and certainly, I will order them to slit the ears of cattle, and indeed I will order them to change the nature created by Allah.\" And whoever takes Shaitan (Satan) as a Walee (protector or helper) instead of Allah, has surely suffered a manifest loss.', 'and I will lead them astray, and I will tempt them with false hopes, and I will command them, whereby they shall slit the ears of cattle, and I will command them, whereby they shall alter the creation of Allah.” Whoever takes the Satan for friend, instead of Allah, incurs an obvious loss.'),
(613, 4, 120, 18, 15, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'یَعِدُہُمۡ وَ یُمَنِّیۡہِمۡ ؕ وَ مَا یَعِدُہُمُ الشَّیۡطٰنُ  اِلَّا  غُرُوۡرًا ﴿۱۲۰﴾', 'وہ انکو وعدے دیتا ہے اور امیدیں دلاتا ہے اور جو کچھ شیطان انہیں وعدے دیتا ہے وہ دھوکا ہی دھوکا ہے۔', 'انکو وعدہ دیتا ہے اور انکو امیدیں دلاتا ہے اور جو کچھ وعدہ دیتا ہے انکو شیطان سو سب فریب ہے', 'He (Shaitan (Satan)) makes promises to them, and arouses in them false desires; and Shaitans (Satan) promises are nothing but deceptions.', 'He (the Satan) makes promises to them, and he tempts them with hopes. The Satan does not make a promise to them but to deceive.'),
(614, 4, 121, 18, 15, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اُولٰٓئِکَ مَاۡوٰىہُمۡ جَہَنَّمُ ۫ وَ لَا یَجِدُوۡنَ عَنۡہَا  مَحِیۡصًا ﴿۱۲۱﴾', 'ایسے لوگوں کا ٹھکانہ جہنم ہے اور وہ وہاں سے کوئی راہ فرار نہیں پا سکیں گے۔', 'ایسوں کا ٹھکانا ہے دوزخ اور نہ پاویں گے وہاں سے کہیں بھاگنے کو جگہ [۱۷۸]', 'The dwelling of such (people) is Hell, and they will find no way of escape from it.', 'As for such people, their refuge is Jahannam, and they shall find no escape from it.'),
(615, 4, 122, 18, 15, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ سَنُدۡخِلُہُمۡ جَنّٰتٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَاۤ  اَبَدًا ؕ وَعۡدَ اللّٰہِ حَقًّا ؕ وَ مَنۡ اَصۡدَقُ مِنَ اللّٰہِ قِیۡلًا ﴿۱۲۲﴾', 'اور جو لوگ ایمان لائے اور نیک کام کرتے رہے انکو ہم بہشتوں میں داخل کریں گے جن کے نیچے نہریں جاری ہیں۔ وہ ہمیشہ ہمیشہ ان میں رہیں گے۔ یہ اللہ کا سچّا وعدہ ہے اور اللہ سے زیادہ بات کا سچّا کون ہو سکتا ہے۔', 'اور جو لوگ ایمان لائے اور عمل کئے اچھے انکو ہم داخل کریں گے باغوں میں کہ جن کے نیچے بہتی ہیں نہریں رہا کریں ان میں ہی ہمیشہ وعدہ ہے اللہ کا سچا اور اللہ سےسچا کون ہے [۱۷۹]', 'But those who believe (in the Oneness of Allah - Islamic Monotheism) and do deeds of righteousness, We shall admit them to the Gardens under which rivers flow (i.e. in Paradise) to dwell therein forever. Allahs Promise is the Truth, and whose words can be truer than those of Allah? (Of course, none).', 'Those who believe and do good deeds, We shall admit them to the gardens beneath which rivers flow. They shall live there forever, it being a real promise from Allah; and who is more truthful than Allah in his word?'),
(616, 4, 123, 18, 15, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'لَیۡسَ بِاَمَانِیِّکُمۡ وَ لَاۤ اَمَانِیِّ اَہۡلِ الۡکِتٰبِ ؕ مَنۡ یَّعۡمَلۡ سُوۡٓءًا یُّجۡزَ  بِہٖ ۙ وَ لَا یَجِدۡ لَہٗ مِنۡ دُوۡنِ اللّٰہِ وَلِیًّا وَّ لَا نَصِیۡرًا ﴿۱۲۳﴾', 'مسلمانو نجات نہ تو تمہاری آرزوؤں پر ہے۔ اور نہ اہل کتاب کی آرزوؤں پر۔ جو شخص برائی کرے گا اسے اسی طرح کا بدلہ دیا جائے گا اور وہ اللہ کے سوا نہ کسی کو حمایتی پائے گا اور نہ مددگار۔', 'نہ تمہاری امیدوں پر مدار ہے اور نہ اہل کتاب کی امیدوں پر جو کوئی برا کام کرے گا اس کی سزا پاوے گا اور نہ پاوے گا اللہ کے سوا اپنا کوئی حمایتی اور نہ کوئی مددگار', 'It will not be in accordance with your desires (Muslims), nor those of the people of the Scripture (Jews and Christians), whosoever works evil, will have the recompense thereof, and he will not find any protector or helper besides Allah.', 'This is not (a matter of) your fancies or the fancies of the People of the Book. Whoever does evil shall be requited for it, and he shall find neither a friend for himself, besides Allah, nor a helper.'),
(617, 4, 124, 18, 15, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ مَنۡ یَّعۡمَلۡ مِنَ الصّٰلِحٰتِ مِنۡ ذَکَرٍ اَوۡ اُنۡثٰی وَ ہُوَ مُؤۡمِنٌ فَاُولٰٓئِکَ یَدۡخُلُوۡنَ الۡجَنَّۃَ  وَ لَا  یُظۡلَمُوۡنَ  نَقِیۡرًا ﴿۱۲۴﴾', 'اور جو نیک کام کرے گا مرد ہو یا عورت جبکہ وہ صاحب ایمان بھی ہو گا تو ایسے لوگ بہشت میں داخل ہوں گے اور انکی تِل برابر بھی حق تلفی نہ کی جائے گی۔', 'اور جو کوئی کام کرے اچھے مرد ہو یا عورت اور وہ ایمان رکھتا ہو سو وہ لوگ داخل ہوں گے جنت میں اور ان کا حق ضائع نہ ہو گا تل بھر [۱۸۰]', 'And whoever does righteous good deeds, male or female, and is a true believer in the Oneness of Allah (Muslim), such will enter Paradise and not the least injustice, even to the size of a Naqeera (speck on the back of a datestone), will be done to them.', 'Whoever, male or female, does good deeds and is a believer, then such people shall enter Paradise, and they shall not be wronged in the least.'),
(618, 4, 125, 18, 15, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ مَنۡ اَحۡسَنُ دِیۡنًا مِّمَّنۡ اَسۡلَمَ  وَجۡہَہٗ لِلّٰہِ وَ ہُوَ مُحۡسِنٌ وَّ اتَّبَعَ مِلَّۃَ اِبۡرٰہِیۡمَ حَنِیۡفًا ؕ وَ اتَّخَذَ اللّٰہُ اِبۡرٰہِیۡمَ خَلِیۡلًا ﴿۱۲۵﴾', 'اور اس شخص سے اچھا کس کا دین ہو سکتا ہے جس نے اللہ کے آگے سر جھکا دیا اور وہ نیکوکار بھی ہے اور ابراہیم کے دین کا پیرو ہے جو یکسو یعنی ایک اللہ کے ہو رہے تھے اور اللہ نے ابراہیم کو اپنا دوست بنایا تھا۔', 'اور اس سے بہتر کس کا دین ہو گا جس نے پیشانی رکھی اللہ کے حکم پر اور نیک کاموں میں لگا ہوا ہے اور چلا دین ابراہیم پر جو ایک ہی طرف کا تھا اور اللہ نے بنا لیا ابراہیم کو خالص دوست [۱۸۱]', 'And who can be better in religion than one who submits his face (himself) to Allah (i.e. follows Allahs Religion of Islamic Monotheism); and he is a Muhsin (a good-doer - see V.2:112). And follows the religion of Ibrahim (Abraham) Hanifa (Islamic Monotheism - to worship none but Allah Alone). And Allah did take Ibrahim (Abraham) as a Khalil (an intimate friend).', 'Who is better in Faith than one who has surrendered his self to Allah and is good in deeds, and has followed the creed of Ibrāhīm, the upright. Allah has made Ibrāhīm a friend.'),
(619, 4, 126, 18, 15, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ لِلّٰہِ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ؕ وَ کَانَ اللّٰہُ بِکُلِّ شَیۡءٍ  مُّحِیۡطًا ﴿۱۲۶﴾٪', 'اور آسمان اور زمین میں جو کچھ ہے سب اللہ ہی کا ہے اور اللہ ہر چیز کا احاطہ کئے ہوئے ہے۔', 'اور اللہ ہی کا ہے جو کچھ ہے آسمانوں میں اور زمین میں اور سب چیزیں اللہ کے قابو میں ہیں [۱۸۲]', 'And to Allah belongs all that is in the heavens and all that is in the earth. And Allah is Ever Encompassing all things.', 'To Allah belongs what is in the heavens and what is in the earth. Allah encompasses every thing.'),
(620, 4, 127, 19, 16, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ یَسۡتَفۡتُوۡنَکَ فِی النِّسَآءِ ؕ قُلِ اللّٰہُ یُفۡتِیۡکُمۡ فِیۡہِنَّ ۙ وَ مَا یُتۡلٰی عَلَیۡکُمۡ فِی الۡکِتٰبِ فِیۡ یَتٰمَی النِّسَآءِ الّٰتِیۡ لَاتُؤۡ تُوۡنَہُنَّ مَا کُتِبَ لَہُنَّ وَ تَرۡغَبُوۡنَ  اَنۡ تَنۡکِحُوۡہُنَّ وَ الۡمُسۡتَضۡعَفِیۡنَ مِنَ الۡوِلۡدَانِ ۙ وَ اَنۡ تَقُوۡمُوۡا لِلۡیَتٰمٰی بِالۡقِسۡطِ ؕ وَ مَا تَفۡعَلُوۡا مِنۡ خَیۡرٍ فَاِنَّ اللّٰہَ کَانَ بِہٖ عَلِیۡمًا ﴿۱۲۷﴾', 'اے پیغمبر لوگ تم سے یتیم عورتوں کے بارے میں فتوٰی طلب کرتے ہیں۔ کہہ دو کہ اللہ تم کو انکے ساتھ نکاح کرنے کے معاملے میں اجازت دیتا ہے اور جو حکم اس کتاب میں پہلے دیا گیا ہے وہ ان یتیم عورتوں کے بارے میں ہے جنکو تم ان کا حق تو دیتے نہیں اور خواہش رکھتے ہو کہ ان کے ساتھ نکاح کر لو اور نیز بیچارے بے کس بچوں کے بارے میں۔ اور یہ بھی حکم دیتا ہے کہ یتیموں کے بارے میں انصاف پر قائم رہو۔ اور جو بھلائی تم کرو گے تو بیشک اللہ اس کو جانتا ہے۔', 'اور تجھ سے رخصت مانگے ہیں عورتوں کے نکاح کی کہہ دے اللہ تم کو اجازت دیتا ہے ان کی اور وہ جو تم کو سنایا جاتا ہے قرآن میں سو حکم ہے ان یتیم عورتوں کا جن کو تم نہیں دیتے جو ان کے لئے مقرر کیا ہے اور چاہتے ہو کہ ان کو نکاح میں لے آؤ اور حکم ہے ناتوان لڑکوں کا اور یہ کہ قائم رہو یتیموں کےحق میں انصاف پر [۱۸۳] اور جو کرو گے بھلائی سو وہ اللہ کو معلوم ہے [۱۸۴]', 'They ask your legal instruction concerning women, say: Allah instructs you about them, and about what is recited unto you in the Book concerning the orphan girls whom you give not the prescribed portions (as regards Mahr and inheritance) and yet whom you desire to marry, and (concerning) the children who are weak and oppressed, and that you stand firm for justice to orphans. And whatever good you do, Allah is Ever AllAware of it.', 'They ask you about women. Say, “Allah answers you about them, and so does what is recited to you from the Book regarding orphaned women whom you do not give what is prescribed for them and tend to marry them, and regarding the weak from the children, and that you should maintain justice for the orphans. Whatever good you do Allah is aware of it.'),
(621, 4, 128, 19, 16, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ اِنِ امۡرَاَۃٌ خَافَتۡ مِنۡۢ بَعۡلِہَا نُشُوۡزًا اَوۡ اِعۡرَاضًا فَلَا جُنَاحَ عَلَیۡہِمَاۤ  اَنۡ یُّصۡلِحَا بَیۡنَہُمَا صُلۡحًا ؕ وَ الصُّلۡحُ  خَیۡرٌ ؕ وَ اُحۡضِرَتِ الۡاَنۡفُسُ الشُّحَّ ؕ وَ اِنۡ تُحۡسِنُوۡا وَ تَتَّقُوۡا فَاِنَّ اللّٰہَ کَانَ بِمَا تَعۡمَلُوۡنَ  خَبِیۡرًا ﴿۱۲۸﴾', 'اور اگر کسی عورت کو اپنے خاوند کی طرف سے زیادتی یا بے رخی کا اندیشہ ہو تو میاں بیوی پر کچھ گناہ نہیں کہ آپس میں کسی قرارداد پر صلح کر لیں۔ اور صلح خوب چیز ہے اور طبعیتیں تو خود غرضی کی طرف مائل ہوتی ہی ہیں۔ اور اگر تم نیکوکاری اور پرہیزگاری کرو گے تو اللہ تمہارے سب کاموں سے واقف ہے۔', 'اور اگر کوئی عورت ڈرے اپنے خاوند کے لڑنے سے یا جی پھر جانے سو تو کچھ گناہ نہیں دونوں پر کہ کر لیں آپس میں کسی طرح صلح اور صلح خوب چیز ہے [۱۸۵] اور دلوں کے سامنے موجود ہے حرص [۱۸۶] اور اگر تم نیکی کرو اور پرہیزگاری کرو تو اللہ کو تمہارے سب کاموں کی خبر ہے [۱۸۷]', 'And if a woman fears cruelty or desertion on her husbands part, there is no sin on them both if they make terms of peace between themselves; and making peace is better. And human inner-selves are swayed by greed. But if you do good and keep away from evil, verily, Allah is Ever WellAcquainted with what you do.', 'If a woman fears ill treatment or aversion from her husband, then, there is no sin on them in entering into a compromise between them. Compromise is better. Avarice is made to be present in human souls. If you do good and fear Allah, then, Allah is All-Aware of what you do.'),
(622, 4, 129, 19, 16, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ لَنۡ تَسۡتَطِیۡعُوۡۤا اَنۡ تَعۡدِلُوۡا بَیۡنَ النِّسَآءِ وَ لَوۡ حَرَصۡتُمۡ فَلَا تَمِیۡلُوۡا کُلَّ الۡمَیۡلِ فَتَذَرُوۡہَا کَالۡمُعَلَّقَۃِ ؕ وَ اِنۡ تُصۡلِحُوۡا وَ تَتَّقُوۡا فَاِنَّ اللّٰہَ کَانَ غَفُوۡرًا رَّحِیۡمًا ﴿۱۲۹﴾', 'اور تم خواہ کتنا ہی چاہو بیویوں میں ہرگز عدل نہیں کر سکو گے تو ایسا بھی نہ کرنا کہ ایک ہی کی طرف ڈھل جاؤ۔ اور دوسری کو ایسی حالت میں چھوڑ دو کہ گویا ادھر میں لٹک رہی ہے۔ اور اگر آپس میں مصالحت کر لو اور پرہیزگاری کرو تو اللہ بخشنے والا ہے بڑا مہربان ہے۔', 'اور تم ہرگز برابر نہ رکھ سکو گے عورتوں کو اگرچہ اس کی حرص کرو سو بالکل پھر بھی نہ جاؤ کہ ڈال رکھو ایک عورت کو جیسے ادھر میں لٹکتی [۱۸۸] اور اگر اصلاح کرتے رہو اور پرہیزگاری کرتے رہو تو للہ بخشنے والا مہربان [۱۸۹]', 'You will never be able to do perfect justice between wives even if it is your ardent desire, so do not incline too much to one of them (by giving her more of your time and provision) so as to leave the other hanging (i.e. neither divorced nor married). And if you do justice, and do all that is right and fear Allah by keeping away from all that is wrong, then Allah is Ever OftForgiving, Most Merciful.', 'You shall never be able to maintain real equality between wives, even though you are eager to. So, do not lean totally (towards one) and leave the other as suspended. If you act righteously and fear Allah, then, Allah is Most-Forgiving, Very-Merciful.'),
(623, 4, 130, 19, 16, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ  اِنۡ یَّتَفَرَّقَا یُغۡنِ اللّٰہُ  کُلًّا مِّنۡ سَعَتِہٖ ؕ وَ کَانَ اللّٰہُ  وَاسِعًا حَکِیۡمًا ﴿۱۳۰﴾', 'اور اگر میاں بیوی ایک دوسرے سے جدا ہو جائیں تو اللہ ہر ایک کو اپنی وسعت سے غنی کر دے گا اور اللہ کشائش والا ہے حکمت والا ہے۔', 'اور اگر دونوں جدا ہو جاویں تو اللہ ہر ایک کو بے پروا کر دے گا اپنی کشائش سے اور اللہ کشائش والا تدبیر جاننے والا ہے [۱۹۰]', 'But if they separate (by divorce), Allah will provide abundance for everyone of them from His Bounty. And Allah is Ever AllSufficient for His creatures need, AllWise.', 'If they separate, Allah shall, through His capacity, make each of them need-free (of the other). Allah is All-Embracing, All-Wise.'),
(624, 4, 131, 19, 16, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ لِلّٰہِ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ؕ وَ لَقَدۡ وَصَّیۡنَا الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ مِنۡ قَبۡلِکُمۡ وَ اِیَّاکُمۡ اَنِ اتَّقُوا اللّٰہَ ؕ وَ اِنۡ تَکۡفُرُوۡا فَاِنَّ لِلّٰہِ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ؕ وَ کَانَ اللّٰہُ غَنِیًّا حَمِیۡدًا ﴿۱۳۱﴾', 'اور جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے سب اللہ ہی کا ہے اور جن لوگوں کو تم سے پہلے کتاب دی گئ تھی ان کو بھی اور اے نبی تم کو بھی ہم نے حکم تاکیدی کیا ہے کہ اللہ سے ڈرتے رہو۔ اور اگر تم لوگ کفر کرو گے تو سمجھ رکھو کہ جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب اللہ ہی کا ہے اور اللہ بے نیاز ہے لائق حمد و ثنا ہے۔', 'اور اللہ کا ہے جو کچھ ہے آسمانوں میں اور جو کچھ ہے زمین میں اور ہم نے حکم دیا ہے پہلے کتاب والوں کو اور تم کو کہ ڈرتے رہو اللہ سے اور اگر نہ مانو گے تو اللہ کا ہے جو کچھ ہے آسمانوں میں اور جو کچھ کہ ہے زمین میں اور اللہ ہے بے پروا سب خوبیوں والا', 'And to Allah belongs all that is in the heavens and all that is in the earth. And verily, We have recommended to the people of the Scripture before you, and to you (O Muslims) that you (all) fear Allah, and keep your duty to Him, But if you disbelieve, then unto Allah belongs all that is in the heavens and all that is in the earth, and Allah is Ever Rich (Free of all wants), Worthy of all praise.', 'To Allah belongs what is in the heavens and what is in the earth. We have ordered those who were given the Book before you, and (ordered) you yourselves to fear Allah. If you disbelieve, then, surely to Allah belongs what is in the heavens and what is in the earth. Allah is All-Independent, Ever-Praised.'),
(625, 4, 132, 19, 16, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ لِلّٰہِ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ؕ وَ کَفٰی بِاللّٰہِ وَکِیۡلًا ﴿۱۳۲﴾', 'اور پھر سن رکھو کہ جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب اللہ ہی کا ہے اور اللہ ہی کارساز کافی ہے۔', 'اور اللہ کا ہے جو کچھ ہے آسمانوں میں اور جو کچھ ہے زمین میں اور اللہ کافی ہے کارساز [۱۹۱]', 'And to Allah belongs all that is in the heavens and all that is in the earth. And Allah is Ever AllSufficient as a Disposer of affairs.', 'To Allah belongs what is in the heavens and what is in the earth, and Allah is enough to trust in.'),
(626, 4, 133, 19, 16, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اِنۡ یَّشَاۡ یُذۡہِبۡکُمۡ اَیُّہَا النَّاسُ وَ یَاۡتِ بِاٰخَرِیۡنَ ؕ وَ کَانَ اللّٰہُ عَلٰی ذٰلِکَ قَدِیۡرًا ﴿۱۳۳﴾', 'لوگو اگر وہ چاہے تو تم کو فنا کر دے اور تمہاری جگہ اور لوگوں کو پیدا کر دے۔ اور اللہ اس بات پر پوری طرح قادر ہے۔', 'اگر چاہے تو تم کو دور کر دے اے لوگو اور لے آئے اور لوگوں کو اور اللہ کو یہ قدرت ہے [۱۹۲]', 'If He wills, He can take you away, O people, and bring others. And Allah is Ever AllPotent over that.', 'If He so wills, He can remove you, O men, and bring others (in your place). Allah has the power to do that.'),
(627, 4, 134, 19, 16, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'مَنۡ کَانَ یُرِیۡدُ ثَوَابَ الدُّنۡیَا فَعِنۡدَ اللّٰہِ ثَوَابُ الدُّنۡیَا وَ الۡاٰخِرَۃِ  ؕ وَ کَانَ اللّٰہُ  سَمِیۡعًۢا بَصِیۡرًا ﴿۱۳۴﴾٪', 'جو شخص دنیا ہی کے ثواب کا طالب ہو تو اسے معلوم ہو کہ اللہ کے پاس دنیا اور آخرت دونوں کا ثواب موجود ہے اور اللہ سنتا ہے دیکھتا ہے۔', 'جو کوئی چاہتا ہو ثواب دنیا کا سو اللہ کے یہاں ہے ثواب دنیا کا اور آخرت کا [۱۹۳] اور اللہ سب کچھ سنتا دیکھتا ہے [۱۹۴]', 'Whoever desires a reward in this life of the world, then with Allah (Alone and none else) is the reward of this worldly life and of the Hereafter. And Allah is Ever AllHearer, AllSeer.', 'Whoever seeks the reward of this world, then, with Allah is the reward of this world and of the Hereafter. Allah is All-Hearing, All-Seeing.'),
(628, 4, 135, 20, 17, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا کُوۡنُوۡا قَوّٰمِیۡنَ بِالۡقِسۡطِ شُہَدَآءَ  لِلّٰہِ وَ لَوۡ عَلٰۤی اَنۡفُسِکُمۡ اَوِ الۡوَالِدَیۡنِ وَ الۡاَقۡرَبِیۡنَ ۚ اِنۡ یَّکُنۡ غَنِیًّا اَوۡ فَقِیۡرًا فَاللّٰہُ اَوۡلٰی بِہِمَا ۟ فَلَا تَتَّبِعُوا الۡہَوٰۤی اَنۡ تَعۡدِلُوۡا ۚ وَ اِنۡ تَلۡوٗۤا اَوۡ تُعۡرِضُوۡا فَاِنَّ اللّٰہَ  کَانَ بِمَا تَعۡمَلُوۡنَ خَبِیۡرًا ﴿۱۳۵﴾', 'اے ایمان والو! انصاف پر قائم رہو اور اللہ کے لئے سچّی گواہی دو خواہ یہ تمہارے اپنے  خلاف یا تمہارے ماں باپ اور رشتہ داروں  کے خلاف ہی ہو۔ اگر کوئی امیر ہے یا فقیر تو اللہ ان دونوں کا زیادہ خیرخواہ ہے۔ پس تم خواہش نفس کے پیچھے چل کر عدل کو نہ چھوڑ دینا۔ اگر تم لگی لپٹی بات کہو گے یا سچائی سے پہلوتہی کرو گے تو جان رکھو اللہ تمہارے سب کاموں سے واقف ہے۔', 'اے ایمان والو قائم رہو انصاف پر گواہی دو اللہ کی طرف کی اگرچہ نقصان ہو تمہارا یا ماں باپ کا یا قرابت والوں کا [۱۹۵] اگر کوئی مالدار ہے یا محتاج ہے تو اللہ ان کا خیرخواہ تم سے زیادہ ہے سو تم پیروی نہ کرو دل کی خواہش کی انصاف کرنے میں [۱۹۶] اور اگر تم زبان ملو گے یا بچا جاؤ گے تو اللہ تمہاے سب کاموں سے واقف ہے [۱۹۷]', 'O you who believe! Stand out firmly for justice, as witnesses to Allah, even though it be against yourselves, or your parents, or your kin, be he rich or poor, Allah is a Better Protector to both (than you). So follow not the lusts (of your hearts), lest you may avoid justice, and if you distort your witness or refuse to give it, verily, Allah is Ever WellAcquainted with what you do.', 'O you who believe, be upholders of justice - witnesses for Allah, even though against (the interest of) your selves or the parents, and the kinsmen. One may be rich or poor, Allah is better caretaker of both. So do not follow desires, lest you should swerve. If you twist or avoid (the evidence), then, Allah is all-aware of what you do.'),
(629, 4, 136, 20, 17, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اٰمِنُوۡا بِاللّٰہِ وَ رَسُوۡلِہٖ وَ الۡکِتٰبِ الَّذِیۡ نَزَّلَ عَلٰی رَسُوۡلِہٖ وَ الۡکِتٰبِ الَّذِیۡۤ اَنۡزَلَ مِنۡ قَبۡلُ ؕ وَ مَنۡ یَّکۡفُرۡ بِاللّٰہِ وَ مَلٰٓئِکَتِہٖ وَ کُتُبِہٖ وَ رُسُلِہٖ وَ الۡیَوۡمِ الۡاٰخِرِ فَقَدۡ ضَلَّ  ضَلٰلًۢا  بَعِیۡدًا ﴿۱۳۶﴾', 'مومنو! اللہ پر اور اسکے رسول پر اور جو کتاب اس نے اپنے اس پیغمبر پر نازل کی ہے اور جو کتابیں اس سے پہلے نازل کی تھیں سب پر ایمان رکھو۔ اور جو شخص اللہ اور اسکے فرشتوں اور اسکی کتابوں اور اسکے پیغمبروں اور روز قیامت سے کفر کرے وہ رستے سے بھٹک کر دور جا پڑا۔', 'ایمان والو یقین لاؤ اللہ پر اور اسکے رسول پر اور اس کتاب پر جو نازل کی ہے اپنے رسول پر اور اس کتاب پر جو نازل کی تھی پہلے اور جو کوئی یقین نہ رکھے اللہ پر اور اسکے فرشتوں پر اور کتابوں پر اور رسولوں پر اور قیامت کےدن پر وہ بہک کر دور جا پڑا [۱۹۸]', 'O you who believe! Believe in Allah, and His Messenger (Muhammad SAW), and the Book (the Quran) which He has sent down to His Messenger, and the Scripture which He sent down to those before (him), and whosoever disbelieves in Allah, His Angels, His Books, His Messengers, and the Last Day, then indeed he has strayed far away.', 'O you who believe, do believe in Allah and His Messenger and in the Book He has revealed to His Messenger and in the Books He has revealed earlier. Whoever disbelieves in Allah and His angels and His Books and His Messengers and the Last Day has indeed gone far astray.'),
(630, 4, 137, 20, 17, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اِنَّ الَّذِیۡنَ اٰمَنُوۡا ثُمَّ  کَفَرُوۡا ثُمَّ  اٰمَنُوۡا ثُمَّ  کَفَرُوۡا ثُمَّ  ازۡدَادُوۡا کُفۡرًا لَّمۡ  یَکُنِ اللّٰہُ لِیَغۡفِرَ لَہُمۡ وَ لَا لِیَہۡدِیَہُمۡ سَبِیۡلًا ﴿۱۳۷﴾ؕ', 'جو لوگ ایمان لائے پھر کافر ہو گئے۔ پھر ایمان لائے پھر کافر ہو گئے پھر کفر میں بڑھتے گئے انکو اللہ نہ تو بخشے گا اور نہ انہیں سیدھا رستہ دکھا ئے گا۔', 'جو لوگ مسلمان ہوئے پھر کافر ہو گئے پھر مسلمان ہوئے پھر کافر ہو گئے پھر بڑھتے رہے کفر میں تو اللہ ان کو ہرگز بخشنے والا نہیں اور نہ دکھلاوے ان کو راہ [۱۹۹]', 'Verily, those who believe, then disbelieve, then believe (again), and (again) disbelieve, and go on increasing in disbelief; Allah will not forgive them, nor guide them on the (Right) Way.', 'Surely, those who believed and then disbelieved, believed again and then disbelieved, then went on increasing in their disbelief - Allah is not to forgive them nor lead them on the path.'),
(631, 4, 138, 20, 17, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'بَشِّرِ الۡمُنٰفِقِیۡنَ بِاَنَّ لَہُمۡ عَذَابًا اَلِیۡمَۨا ﴿۱۳۸﴾ۙ', 'اے پیغمبر منافقوں یعنی دورخے لوگوں کو بشارت سنا دو کہ ان کے لئے دکھ دینے والا عذاب تیار ہے۔', 'خوشخبری سنا دے منافقوں کو کہ ان کے واسطے ہے عذاب دردناک', 'Give to the hypocrites the tidings that there is for them a painful torment.', 'Give the hypocrites the ‘good news’ that for them there is a painful punishment'),
(632, 4, 139, 20, 17, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'الَّذِیۡنَ یَتَّخِذُوۡنَ الۡکٰفِرِیۡنَ اَوۡلِیَآءَ مِنۡ دُوۡنِ الۡمُؤۡمِنِیۡنَ ؕ اَیَبۡتَغُوۡنَ عِنۡدَہُمُ الۡعِزَّۃَ فَاِنَّ الۡعِزَّۃَ لِلّٰہِ جَمِیۡعًا ﴿۱۳۹﴾ؕ', 'وہ جو مومنوں کو چھوڑ کر کافروں کو دوست بناتے ہیں۔ کیا یہ ان کے ہاں عزت حاصل کرنی چاہتے ہیں سو عزت تو سب اللہ ہی کی ہے۔', 'وہ جو بناتے ہیں کافروں کو اپنارفیق مسلمانوں کو چھوڑ کر کیا ڈھونڈھتے ہیں ان کے پاس عزت سو عزت تو اللہ ہی کے واسطے ہے ساری [۲۰۰]', 'Those who take disbelievers for Auliya (protectors or helpers or friends) instead of believers, do they seek honour, power and glory with them? Verily, then to Allah belongs all honour, power and glory.', '- those who take the disbelievers for friends rather than the believers. Are they seeking honor in their company? But, indeed, all honor belongs to Allah,'),
(633, 4, 140, 20, 17, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'وَ قَدۡ نَزَّلَ عَلَیۡکُمۡ  فِی الۡکِتٰبِ اَنۡ  اِذَا سَمِعۡتُمۡ اٰیٰتِ اللّٰہِ یُکۡفَرُ بِہَا وَ یُسۡتَہۡزَاُ بِہَا فَلَا تَقۡعُدُوۡا مَعَہُمۡ حَتّٰی یَخُوۡضُوۡا فِیۡ حَدِیۡثٍ غَیۡرِہٖۤ  ۫ۖ اِنَّکُمۡ  اِذًا مِّثۡلُہُمۡ ؕ اِنَّ اللّٰہَ جَامِعُ الۡمُنٰفِقِیۡنَ وَ الۡکٰفِرِیۡنَ فِیۡ جَہَنَّمَ جَمِیۡعَۨا ﴿۱۴۰﴾ۙ', 'اور اللہ نے تم مومنوں پر اپنی کتاب میں یہ حکم نازل فرمایا ہے کہ جب تم کہیں سنو کہ اللہ کی آیتوں سے انکار ہو رہا ہے اور انکی ہنسی اڑائی جا رہی ہے تو جب تک وہ لوگ اور باتیں نہ کرنے لگیں انکے پاس مت بیٹھو ورنہ تم بھی انہی جیسے  شمار ہو گے۔ کچھ شک نہیں کہ اللہ منافقوں اور کافروں سب کو دوزخ میں اکٹھا کرنے والا ہے۔', 'اور حکم اتار چکا تم پر قرآن میں کہ جب سنو اللہ کی آیتوں پر انکار ہوتے اور ہنسی ہوتے تو نہ بیٹھو ان کےساتھ یہاں تک کہ مشغول ہوں کسی دوسری بات میں نہیں تو تم بھی انہی جیسے ہو گئے اللہ اکٹھا کرے گا منافقوں کو اور کافروں کو دوزخ میں ایک جگہ [۲۰۱]', 'And it has already been revealed to you in the Book (this Quran) that when you hear the Verses of Allah being denied and mocked at, then sit not with them, until they engage in a talk other than that; (but if you stayed with them) certainly in that case you would be like them. Surely, Allah will collect the hypocrites and disbelievers all together in Hell,', 'and He has revealed to you in the Book that when you hear the verses of Allah being disbelieved and ridiculed, you should not sit with them unless they enter into some other discourse. You, in that case, would be like them. Surely, Allah is to gather all hypocrites and disbelievers in Jahannam .'),
(634, 4, 141, 20, 17, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'الَّذِیۡنَ یَتَرَبَّصُوۡنَ بِکُمۡ ۚ فَاِنۡ کَانَ لَکُمۡ فَتۡحٌ مِّنَ اللّٰہِ قَالُوۡۤا اَلَمۡ نَکُنۡ مَّعَکُمۡ ۫ۖ وَ اِنۡ کَانَ لِلۡکٰفِرِیۡنَ نَصِیۡبٌ ۙ قَالُوۡۤا اَلَمۡ نَسۡتَحۡوِذۡ عَلَیۡکُمۡ وَ نَمۡنَعۡکُمۡ مِّنَ الۡمُؤۡمِنِیۡنَ ؕ فَاللّٰہُ یَحۡکُمُ بَیۡنَکُمۡ یَوۡمَ الۡقِیٰمَۃِ ؕ وَ لَنۡ یَّجۡعَلَ اللّٰہُ لِلۡکٰفِرِیۡنَ عَلَی الۡمُؤۡمِنِیۡنَ  سَبِیۡلًا ﴿۱۴۱﴾٪', 'جو تم کو دیکھتے رہتے ہیں۔ پھر اگر اللہ کی طرف سے تم کو فتح ملے تو کہتے ہیں کیا ہم تمہارے ساتھ نہ تھے۔ اور اگر کافروں کو فتح نصیب ہو۔ تو ان سے کہتے ہیں کہ کیا ہم تم پر غالب نہیں تھے اور تم کو مسلمانوں کے ہاتھ سے بچایا نہیں اب تم سب میں قیامت کے دن فیصلہ کر دے گا اور اللہ کافروں کو مومنوں پر ہرگز غلبہ نہیں دے گا۔', 'وہ منافق جو تمہاری تاک میں ہیں پھر اگر تم کو فتح ملے اللہ کی طرف سے تو کہیں کیا ہم نہ تھےتمہارے ساتھ اور اگر نصیب ہو کافروں کو تو کہیں کیا ہم نےگھیر نہ لیا تھا تم کو اور بچا دیا تم کو مسلمانوں سے [۲۰۲] سو اللہ فیصلہ کرے گا تم میں قیامت کےدن اور ہرگز نہ دے گا اللہ کافروں کو مسلمانوں پر غلبہ کی راہ [۲۰۳]', 'Those (hyprocrites) who wait and watch about you; if you gain a victory from Allah, they say: \"Were we not with you,\" but if the disbelievers gain a success, they say (to them): \"Did we not gain mastery over you and did we not protect you from the believers?\" Allah will judge between you (all) on the Day of Resurrection. And never will Allah grant to the disbelievers a way (to triumph) over the believers.', '- those who look for (a misfortune for) you, so, if there is a victory for you, they say, “Were we not with you?” But if there is a gain for the disbelievers, they say (to them), “Had we not overpowered you, still protected you from the believers?” So, Allah will decide between you on the Doomsday. Allah shall never give the disbelievers a way against the believers.'),
(635, 4, 142, 21, 0, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اِنَّ الۡمُنٰفِقِیۡنَ یُخٰدِعُوۡنَ اللّٰہَ وَ ہُوَ خَادِعُہُمۡ ۚ وَ اِذَا قَامُوۡۤا اِلَی الصَّلٰوۃِ قَامُوۡا کُسَالٰی ۙ یُرَآءُوۡنَ النَّاسَ وَ لَا  یَذۡکُرُوۡنَ اللّٰہَ  اِلَّا  قَلِیۡلًا ﴿۱۴۲﴾۫ۙ', 'منافق ان چالوں سے اپنے نزدیک اللہ کو دھوکا دیتے ہیں۔ یہ اس کو کیا دھوکا دیں گے وہ انہیں کو دھوکے میں ڈالنے والا ہے۔ اور جب یہ نماز کو کھڑے ہوتے ہیں تو سست اور کاہل ہو کر صرف لوگوں کے دکھانے کو اور اللہ کو یاد ہی نہیں کرتے مگر بہت کم۔', 'البتہ منافق دغابازی کرتےہیں اللہ سے اور وہی ان کو دغا دے گا [۲۰۴] اور جب کھڑے ہوں نماز کو تو کھڑے ہوں ہارے جی سے لوگوں کے دکھانے کو اور یاد نہ کریں اللہ کو مگر تھوڑا سا [۲۰۵]', 'Verily, the hypocrites seek to deceive Allah, but it is He Who deceives them. And when they stand up for As-Salat (the prayer), they stand with laziness and to be seen of men, and they do not remember Allah but little.', 'Surely, the hypocrites (try to) deceive Allah while He is the One who leaves them in deception. And when they stand for Salāh, they stand up lazily, only to show people, and do not remember Allah but a little,'),
(636, 4, 143, 21, 0, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'مُّذَبۡذَبِیۡنَ بَیۡنَ ذٰلِکَ ٭ۖ لَاۤ اِلٰی ہٰۤؤُلَآءِ وَ لَاۤ اِلٰی ہٰۤؤُلَآءِ ؕ وَ مَنۡ یُّضۡلِلِ اللّٰہُ فَلَنۡ تَجِدَ  لَہٗ  سَبِیۡلًا ﴿۱۴۳﴾', 'ڈانواں ڈول ہو رہے ہیں نہ ان کی طرف ہوتے ہیں نہ ان کی طرف۔ اور جس کو اللہ بھٹکائے تو تم اس کے لئے کبھی بھی رستہ نہ پاؤ گے۔', 'ادھر میں لٹکتے ہیں دونوں کے بیچ نہ ان کی طرف اور نہ اُن کی طرف اور جس کو گمراہ کرے اللہ تو ہر گز نہ پاوے گا تو اسکے واسطے کہیں راہ [۲۰۶]', '(They are) swaying between this and that, belonging neither to these nor to those, and he whom Allah sends astray, you will not find for him a way (to the truth - Islam).', 'wavering between (this and) that, neither here nor there. Whomsoever Allah lets go astray, you shall never find a way for him.'),
(637, 4, 144, 21, 0, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَتَّخِذُوا الۡکٰفِرِیۡنَ اَوۡلِیَآءَ مِنۡ دُوۡنِ الۡمُؤۡمِنِیۡنَؕ اَتُرِیۡدُوۡنَ اَنۡ  تَجۡعَلُوۡا لِلّٰہِ عَلَیۡکُمۡ  سُلۡطٰنًا مُّبِیۡنًا ﴿۱۴۴﴾', 'اے اہل ایمان مومنوں کے سوا کافروں کو دوست نہ بناؤ۔ کیا تم چاہتے ہو کہ اپنے اوپر اللہ کا صریح الزام لو۔', 'اے ایمان والو نہ بناؤ کافروں کو اپنا رفیق مسلمانوں کو چھوڑ کر کیا لیا چاہتے ہو اپنے اوپر اللہ کا الزام صریح', 'O you who believe! Take not for Auliya (protectors or helpers or friends) disbelievers instead of believers. Do you wish to offer Allah a manifest proof against yourselves?', 'O you who believe, do not take the disbelievers for friends instead of the believers. Do you want to produce before Allah a clear evidence against yourselves?'),
(638, 4, 145, 21, 0, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اِنَّ الۡمُنٰفِقِیۡنَ فِی الدَّرۡکِ الۡاَسۡفَلِ مِنَ النَّارِ ۚ وَ لَنۡ  تَجِدَ لَہُمۡ  نَصِیۡرًا ﴿۱۴۵﴾ۙ', 'کچھ شک نہیں کہ منافق لوگ دوزخ کے سب سے نچلے درجے میں ہوں گے اور تم ان کا کسی کو مددگار نہ پاؤ گے۔', 'بیشک منافق ہیں سب سے نیچے درجہ میں دوزخ کے اور ہر گز نہ پاوے گا تو ان کے واسطے کوئی مددگار [۲۰۷]', 'Verily, the hyprocrites will be in the lowest depths (grade) of the Fire; no helper will you find for them.', 'Surely, the hypocrites are in the lowest level of the Fire, and you shall never find for them a helper'),
(639, 4, 146, 21, 0, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'اِلَّا الَّذِیۡنَ تَابُوۡا وَ اَصۡلَحُوۡا وَ اعۡتَصَمُوۡا بِاللّٰہِ وَ اَخۡلَصُوۡا دِیۡنَہُمۡ  لِلّٰہِ فَاُولٰٓئِکَ مَعَ الۡمُؤۡمِنِیۡنَ ؕ وَ سَوۡفَ یُؤۡتِ اللّٰہُ الۡمُؤۡمِنِیۡنَ اَجۡرًا عَظِیۡمًا ﴿۱۴۶﴾', 'ہاں جنہوں نے توبہ کی اور اپنی حالت کو درست کر لیا اور اللہ کی رسی کو مضبوط پکڑ لیا اور خاص اللہ کے حکم بردار ہو گئے تو ایسے لوگ مومنوں کے ساتھ ہوں گے اور اللہ عنقریب مومنوں کو بڑا ثواب دے گا۔', 'مگر جنہوں نے توبہ کی اور اپنی اصلاح کی اور مضبوط پکڑا اللہ کو اور خالص حکم بردار ہوئے اللہ کے سو وہ ہیں ایمان والوں کےساتھ اور جلد دے گا اللہ ایمان والوں کو بڑا ثواب [۲۰۸]', 'Except those who repent (from hypocrisy), do righteous good deeds, hold fast to Allah, and purify their religion for Allah (by worshipping none but Allah, and do good for Allahs sake only, not to show-off), then they will be with the believers. And Allah will grant to the believers a great reward.', '- except those who repent and correct themselves and hold on to Allah and make their Faith pure for Allah. So, those are with the believers, and Allah will give the believers a great reward.'),
(640, 4, 147, 21, 0, 5, 'وَّ الۡمُحۡصَنٰتُ', 'النسآء', 'مَا یَفۡعَلُ اللّٰہُ بِعَذَابِکُمۡ  اِنۡ شَکَرۡتُمۡ وَ اٰمَنۡتُمۡ ؕ وَ کَانَ اللّٰہُ شَاکِرًا عَلِیۡمًا ﴿۱۴۷﴾', 'اگر تم لوگ اللہ کے شکرگذار ہو اور اس پر ایمان لے آؤ تو اللہ تم کو عذاب دے کر کیا کرے گا۔ اور اللہ تو قدرشناس ہے اور دانا ہے۔', 'کیا کرے گا اللہ تم کو عذاب کر کے اگر تم حق کو مانو اور یقین رکھو اور اللہ قدردان ہے سب کچھ جاننے والا [۲۰۹]', 'Why should Allah punish you if you have thanked (Him) and have believed in Him. And Allah is Ever AllAppreciative (of good), AllKnowing.', 'What would Allah get by punishing you, if you are grateful and believe? Allah is Appreciating, All-Knowing.'),
(641, 4, 148, 21, 1, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'لَا یُحِبُّ اللّٰہُ  الۡجَہۡرَ  بِالسُّوۡٓءِ مِنَ الۡقَوۡلِ اِلَّا مَنۡ ظُلِمَ ؕ وَ کَانَ اللّٰہُ سَمِیۡعًا عَلِیۡمًا ﴿۱۴۸﴾', 'اللہ اس بات کو پسند نہیں فرماتا کہ کوئی کسی کو اعلانیہ برا کہے مگر وہ جو مظلوم ہو۔ اور اللہ سب کچھ سنتا ہے جانتا ہے۔', 'اللہ کو پسند نہیں کسی کی بری بات کا ظاہر کرنا مگر جس پر ظلم ہوا ہو اور اللہ ہے سننے والا جاننے والا [۲۱۰]', 'Allah does not like that the evil should be uttered in public except by him who has been wronged. And Allah is Ever AllHearer, AllKnower.', 'Allah does not like the evil words to be said openly except from anyone wronged. Allah is All-Hearing, All-Knowing.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(642, 4, 149, 21, 1, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'اِنۡ تُبۡدُوۡا خَیۡرًا اَوۡ تُخۡفُوۡہُ اَوۡ تَعۡفُوۡا عَنۡ سُوۡٓءٍ فَاِنَّ اللّٰہَ کَانَ عَفُوًّا قَدِیۡرًا ﴿۱۴۹﴾', 'اگر تم لوگ بھلائی کھلم کھلا کرو گے یا چھپا کر یا برائی سے درگذر کرو گے تو اللہ بھی معاف کرنے والا ہے صاحب قدرت ہے۔', 'اگر تم کھول کر کرو کوئی بھلائی یا اسکو چھپاؤ یا معاف کرو برائی کو تو اللہ بھی معاف کرنے  والا بڑی قدرت والا ہے[۲۱۱]', 'Whether you (mankind) disclose (by good words of thanks) a good deed (done to you in the form of a favour by someone), or conceal it, or pardon an evil, … verily, Allah is Ever OftPardoning, AllPowerful.', 'If you do a good act openly or do it in secret, or forgive an evil deed, then, Allah is All-Forgiving, All-Powerful.'),
(643, 4, 150, 21, 1, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'اِنَّ الَّذِیۡنَ یَکۡفُرُوۡنَ بِاللّٰہِ وَ رُسُلِہٖ وَ یُرِیۡدُوۡنَ اَنۡ یُّفَرِّقُوۡا بَیۡنَ اللّٰہِ وَ رُسُلِہٖ وَ یَقُوۡلُوۡنَ نُؤۡمِنُ بِبَعۡضٍ وَّ نَکۡفُرُ بِبَعۡضٍ ۙ وَّ یُرِیۡدُوۡنَ اَنۡ یَّتَّخِذُوۡا بَیۡنَ ذٰلِکَ  سَبِیۡلًا ﴿۱۵۰﴾ۙ', 'جو لوگ اللہ سے اور اس کے پیغمبروں سے کفر کرتے ہیں اور اللہ اور اس کے پیغمبروں میں فرق کرنا چاہتے ہیں اور کہتے ہیں کہ ہم بعض کو مانتے ہیں اور بعض کو نہیں مانتے۔ اور ایمان اور کفر کے بیچ میں ایک راہ نکالنی چاہتے ہیں۔', 'جو لوگ منکر ہیں اللہ سے اور اسکے رسولوں سے اور چاہتے ہیں کہ فرق نکالیں اللہ میں اور اسکے رسولوں میں اور کہتے ہیں ہم مانتے ہیں بعضوں کو اور نہیں مانتے بعضوں کو اور چاہتے ہیں کہ نکالیں اس کے بیچ میں ایک راہ', 'Verily, those who disbelieve in Allah and His Messengers and wish to make distinction between Allah and His Messengers (by believing in Allah and disbelieving in His Messengers) saying, \"We believe in some but reject others,\" and wish to adopt a way in between.', 'Surely those who disbelieve in Allah and His Messengers, and wish to make division between Allah and His Messengers, and say, “We believe in some (messengers) and disbelieve in some others” and wish to take a way in between that,-'),
(644, 4, 151, 21, 1, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'اُولٰٓئِکَ ہُمُ الۡکٰفِرُوۡنَ حَقًّا ۚ وَ اَعۡتَدۡنَا لِلۡکٰفِرِیۡنَ عَذَابًا مُّہِیۡنًا ﴿۱۵۱﴾', 'وہ یقینًا کافر ہیں اور کافروں کے لئے ہم نے ذلت کا عذاب تیار کر رکھا ہے۔', 'ایسے لوگ وہی ہیں اصل کافر اور ہم نےتیار کر رکھا ہے کافروں کے واسطے ذلت کا عذاب[۲۱۲]', 'They are in truth disbelievers. And We have prepared for the disbelievers a humiliating torment.', '- those are the disbelievers in reality, and We have prepared a humiliating punishment for the disbelievers.'),
(645, 4, 152, 21, 1, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'وَ الَّذِیۡنَ اٰمَنُوۡا بِاللّٰہِ وَ رُسُلِہٖ وَ لَمۡ یُفَرِّقُوۡا بَیۡنَ اَحَدٍ مِّنۡہُمۡ اُولٰٓئِکَ سَوۡفَ یُؤۡتِیۡہِمۡ اُجُوۡرَہُمۡ ؕ وَ کَانَ اللّٰہُ غَفُوۡرًا رَّحِیۡمًا ﴿۱۵۲﴾٪', 'اور جو لوگ اللہ اور اس کے پیغمبروں پر ایمان لائے اور ان میں سے کسی میں فرق نہ کیا یعنی سب کو مانا ایسے لوگوں کو وہ عنقریب ان کی نیکیوں کے صلے عطا فرمائے گا۔ اور اللہ بخشنے والا ہے بڑا مہربان ہے۔', 'اور جو لوگ ایمان لائے اللہ پر اور اسکے رسولوں پر اور جدا نہ کیا ان میں سے کسی کو ان کو جلد دے گا انکے ثواب اور اللہ ہے بخشنے والا مہربان [۲۱۳]', 'And those who believe in Allah and His Messengers and make no distinction between any of them (Messengers), We shall give them their rewards, and Allah is Ever OftForgiving, Most Merciful.', 'Those who have believed in Allah and His Messengers, and have made no division between any of them, to them He will give their rewards. Allah is Most-Forgiving, Very-Merciful.'),
(646, 4, 153, 22, 2, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'یَسۡـَٔلُکَ اَہۡلُ الۡکِتٰبِ اَنۡ تُنَزِّلَ عَلَیۡہِمۡ کِتٰبًا مِّنَ السَّمَآءِ فَقَدۡ سَاَلُوۡا مُوۡسٰۤی اَکۡبَرَ مِنۡ ذٰلِکَ فَقَالُوۡۤا اَرِنَا اللّٰہَ جَہۡرَۃً فَاَخَذَتۡہُمُ الصّٰعِقَۃُ بِظُلۡمِہِمۡ ۚ ثُمَّ اتَّخَذُوا الۡعِجۡلَ مِنۡۢ بَعۡدِ مَا جَآءَتۡہُمُ الۡبَیِّنٰتُ فَعَفَوۡنَا عَنۡ ذٰلِکَ ۚ وَ اٰتَیۡنَا مُوۡسٰی سُلۡطٰنًا مُّبِیۡنًا ﴿۱۵۳﴾', 'اے پیغمبر اہل کتاب تم سے درخواست کرتے ہیں کہ تم ان پر ایک لکھی ہوئی کتاب آسمان سے اتار لاؤ تو یہ موسٰی سے تو اس سے بھی بڑی بڑی درخواستیں کر چکے ہیں ان سے کہتے تھے ہمیں اللہ کو ظاہر یعنی آمنے سامنے دکھا دو سو ان کے گناہ کی وجہ سے انکو بجلی نے آ پکڑا پھر کھلی نشانیاں آ جانے کے بعد بچھڑے کو معبود بنا بیٹھے تو اس سے بھی ہم نے درگذر کی۔ اور موسٰی کو ہم نے کھلی سند دی تھی۔', 'تجھ سےدرخواست کرتے ہیں اہل کتاب کہ تو ان پر اتار لاوے لکھی ہوئی کتاب آسمان سے سو مانگ چکے ہیں موسٰی سے اس سے بھی بڑی چیز اور کہا ہم کو دکھا دے اللہ کو بالکل سامنے سو آ پڑی ان پر بجلی انکے گناہ کے باعث پھر بنا لیا بچھڑےکو بہت کچھ نشانیاں پہنچ چکنے کے بعد پھر ہم نے وہ بھی معاف کیا [۲۱۴] اور دیا ہم نے موسٰی کو غلبہ صریح [۲۱۵]', 'The people of the Scripture (Jews) ask you to cause a book to descend upon them from heaven. Indeed they asked Moosa (Moses) for even greater than that, when they said: \"Show us Allah in public,\" but they were struck with thunder clap and lightning for their wickedness. Then they worshipped the calf even after clear proofs, evidences, and signs had come to them. (Even) so We forgave them. And We gave Moosa (Moses) a clear proof of authority.', 'The People of the Book ask you to bring down upon them a Book from the heavens, (which is not strange,) as they had asked Mūsā something greater than that when they said, “Make us see Allah openly.” So, the thunderbolt took them for the wrong they did. Later, they took to themselves the calf, even after the clear signs had come to them. Then, We forgave them, and gave Mūsā an open authority.'),
(647, 4, 154, 22, 2, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'وَ رَفَعۡنَا فَوۡقَہُمُ الطُّوۡرَ بِمِیۡثَاقِہِمۡ وَ قُلۡنَا لَہُمُ ادۡخُلُوا الۡبَابَ سُجَّدًا وَّ قُلۡنَا لَہُمۡ لَا تَعۡدُوۡا فِی السَّبۡتِ وَ اَخَذۡنَا مِنۡہُمۡ مِّیۡثَاقًا غَلِیۡظًا ﴿۱۵۴﴾', 'اور ان سے عہد لینے کو ہم نے ان پر کوہ طور اٹھا کھڑا کیا اور انہیں حکم دیا کہ شہر کے دروازے میں داخل ہونا تو سجدہ کرتے ہوئے داخل ہونا اور یہ بھی حکم دیا کہ ہفتے کے دن مچھلیاں پکڑنے میں تجاوز یعنی حکم کے خلاف نہ کرنا۔ غرض ہم نے ان سے مضبوط عہد لیا۔', 'اور ہم نے اٹھایا ان پر پہاڑ قرار لینے کے واسطے [۲۱۶] اور ہم نے کہا داخل ہو دروازہ میں سجدہ کرتے ہوئے [۲۱۷] اور ہم نے کہا کہ زیادتی مت کرو ہفتہ کے دن میں اور ہم نے ان سے لیا قول مضبوط [۲۱۸]', 'And for their covenant, We raised over them the Mount and (on the other occasion) We said: \"Enter the gate prostrating (or bowing) with humility;\" and We commanded them: \"Transgress not (by doing worldly works on) the Sabbath (Saturday).\" And We took from them a firm covenant.', 'We raised the (Mount of) Tūr high over them for binding them to the pledge, and We said to them, “Do not transgress in (the matter of) the Sabbath.” We took from them a firm pledge.'),
(648, 4, 155, 22, 2, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'فَبِمَا نَقۡضِہِمۡ مِّیۡثَاقَہُمۡ وَ کُفۡرِہِمۡ بِاٰیٰتِ اللّٰہِ وَ قَتۡلِہِمُ الۡاَنۡۢبِیَآءَ بِغَیۡرِ حَقٍّ وَّ قَوۡلِہِمۡ قُلُوۡبُنَا غُلۡفٌ ؕ بَلۡ طَبَعَ اللّٰہُ عَلَیۡہَا بِکُفۡرِہِمۡ فَلَا یُؤۡمِنُوۡنَ  اِلَّا قَلِیۡلًا ﴿۱۵۵﴾۪', 'لیکن انہوں نے عہد کو توڑ ڈالا تو انکے عہد توڑ دینے اور اللہ کی آیتوں سے کفر کرنے اور انبیاء کو ناحق مار ڈالنے اور یہ کہنے کے سبب کہ ہمارے دلوں پر پردے پڑے ہوئے ہیں اللہ نے انکو مردود کر دیا۔ اور انکے دلوں پر پردے نہیں ہیں بلکہ انکے کفر کے سبب اللہ نے ان پر مہر کر دی ہے تو یہ کم ہی ایمان لاتے ہیں۔', 'ان کو جو سزا ملی سو ان کی عہد شکنی پر اور منکر ہونے پر اللہ کی آیتوں سے اور خون کرنے پر پیغمبروں کا ناحق اور اس کہنے پر کہ ہمارے دل پر غلاف ہے سو یہ نہیں بلکہ اللہ نے مہر کر دی انکے دل پر کفر کے سبب سو ایمان نہیں لاتے مگر کم [۲۱۹]', 'Because of their breaking the covenant, and of their rejecting the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah, and of their killing the Prophets unjustly, and of their saying: \"Our hearts are wrapped (with coverings, i.e. we do not understand what the Messengers say)\" - nay, Allah has set a seal upon their hearts because of their disbelief, so they believe not but a little.', 'So, (they met their fate) for breaking their pledge, and for their disbelief in the verses of Allah, and for their slaying of the prophets unjustly, and for their saying, “Our hearts are sealed” - rather, Allah has set a seal over them for their disbelief, so they do not believe but a little'),
(649, 4, 156, 22, 2, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'وَّ بِکُفۡرِہِمۡ وَ قَوۡلِہِمۡ عَلٰی مَرۡیَمَ  بُہۡتَانًا عَظِیۡمًا ﴿۱۵۶﴾ۙ', 'اور انکے کفر کے سبب اور مریم پر ایک بہتان عظیم باندھنے کے سبب۔', 'اور ان کے کفر پر اور مریم پر بڑا طوفان باندھنے پر', 'And because of their (Jews) disbelief and uttering against Maryam (Mary Ç ) a grave false charge (that she has committed illegal sexual intercourse);', '- and for their disbelief and for what they said against Maryam as a grim imputation,'),
(650, 4, 157, 22, 2, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'وَّ قَوۡلِہِمۡ اِنَّا قَتَلۡنَا الۡمَسِیۡحَ عِیۡسَی ابۡنَ مَرۡیَمَ رَسُوۡلَ اللّٰہِ ۚ وَ مَا قَتَلُوۡہُ وَ مَا صَلَبُوۡہُ وَ لٰکِنۡ شُبِّہَ لَہُمۡ ؕ وَ  اِنَّ الَّذِیۡنَ اخۡتَلَفُوۡا فِیۡہِ لَفِیۡ شَکٍّ مِّنۡہُ ؕ مَا لَہُمۡ بِہٖ مِنۡ عِلۡمٍ  اِلَّا اتِّبَاعَ الظَّنِّ ۚ وَ مَا قَتَلُوۡہُ  یَقِیۡنًۢا ﴿۱۵۷﴾ۙ', 'اور یہ کہنے کے سبب کہ ہم نے مریم کے بیٹے عیسٰی مسیح کو جو اللہ کے پیغمبر کہلاتے تھے قتل کر دیا ہے اللہ نے انکو ملعون کر دیا حالانکہ انہوں نے عیسٰی کو قتل نہیں کیا اور نہ انہیں سولی پر چڑھا پائے لیکن ان لوگوں کو انکی سی صورت معلوم ہوئی۔ اور جو لوگ انکے بارے میں اختلاف کرتے ہیں وہ انکے حال سے شک میں پڑے ہوئے ہیں۔ اور گمان پر چلنے کے سوا انکو اسکا مطلق علم نہیں۔ اور انہوں نے عیسٰی کو یقیناً قتل نہیں کیا۔', 'اور انکے اس کہنے پر کہ ہم نے قتل کیا مسیح عیسٰی مریم کے بیٹے کو جو رسول تھا اللہ کا [۲۲۰] اور انہوں نے نہ اس کو مارا اور نہ سولی پر چڑھایا و لیکن وہی صورت بن گئ انکے آگے اور جو لوگ اس میں مختلف باتیں کرتے ہیں تو وہ لوگ اس جگہ شبہ میں پڑے ہوئے ہیں کچھ نہیں ان کو اس کی خبر صرف اٹکل پر چل رہے ہیں اور اس کو قتل نہیں کیا بیشک', 'And because of their saying (in boast), \"We killed Messiah Iesa (Jesus), son of Maryam (Mary), the Messenger of Allah,\" - but they killed him not, nor crucified him, but the resemblance of Iesa (Jesus) was put over another man (and they killed that man), and those who differ therein are full of doubts. They have no (certain) knowledge, they follow nothing but conjecture. For surely; they killed him not (i.e. Iesa (Jesus), son of Maryam (Mary) ):', 'and for their saying, “We have certainly killed the MasīH ‘Īsā the son of Maryam, the Messenger of Allah”, while in fact they did neither kill him, nor crucify him, but they were deluded by resemblance.Those who disputed in this matter are certainly in doubt about it. They have no knowledge of it, but they follow whims. It is absolutely certain that they did not kill him,'),
(651, 4, 158, 22, 2, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'بَلۡ رَّفَعَہُ اللّٰہُ اِلَیۡہِ ؕ وَ کَانَ اللّٰہُ عَزِیۡزًا حَکِیۡمًا ﴿۱۵۸﴾', 'بلکہ اللہ نے انکو اپنی طرف اٹھا لیا۔ اور اللہ غالب ہے حکمت والا ہے۔', 'بلکہ اس کو اٹھا لیا اللہ نے اپنی طرف اور اللہ ہے زبردست حکمت والا [۲۲۱]', 'But Allah raised him (Iesa (Jesus)) up (with his body and soul) unto Himself (and he is in the heavens). And Allah is Ever AllPowerful, AllWise.', 'but Allah lifted him towards Himself. Allah is All-Mighty, All-Wise.'),
(652, 4, 159, 22, 2, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'وَ اِنۡ مِّنۡ اَہۡلِ الۡکِتٰبِ اِلَّا لَیُؤۡمِنَنَّ بِہٖ قَبۡلَ مَوۡتِہٖ ۚ وَ یَوۡمَ الۡقِیٰمَۃِ  یَکُوۡنُ عَلَیۡہِمۡ  شَہِیۡدًا ﴿۱۵۹﴾ۚ', 'اور اہل کتاب میں سے کوئی نہیں ہو گا مگر انکی موت سے پہلے ان پر ایمان لے آئے گا اور وہ قیامت کے دن ان پر گواہ ہوں گے۔', 'اور جتنے فرقے ہیں اہل کتاب کے سو عیسٰی پر یقین لاویں گے اس کی موت سے پہلے اور قیامت کے دن ہو گا ان پر گواہ [۲۲۲]', 'And there is none of the people of the Scripture (Jews and Christians), but must believe in him (Iesa (Jesus), son of Maryam (Mary), as only a Messenger of Allah and a human being), before his (Iesa (Jesus) or a Jews or a Christians) death (at the time of the appearance of the angel of death). And on the Day of Resurrection, he (Iesa (Jesus)) will be a witness against them.', 'No one will remain from among the People of the Book but will certainly believe in him before he dies, and on the Day of Doom, he shall be a witness against them.'),
(653, 4, 160, 22, 2, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'فَبِظُلۡمٍ مِّنَ الَّذِیۡنَ ہَادُوۡا حَرَّمۡنَا عَلَیۡہِمۡ طَیِّبٰتٍ اُحِلَّتۡ لَہُمۡ وَ بِصَدِّہِمۡ عَنۡ سَبِیۡلِ اللّٰہِ  کَثِیۡرًا ﴿۱۶۰﴾ۙ', 'پس ہم نے یہودیوں کے ظلموں کے سبب بہت سی پاکیزہ چیزیں جو انکو حلال تھیں ان پر حرام کر دیں۔ اور اس سبب سے بھی کہ وہ اکثر اللہ کے رستے سے لوگوں کو روکتے تھے۔', 'سو یہود کے گناہوں کی وجہ سے ہم نے حرام کیں ان پربہت سے پاک چیزیں جو ان پر حلال تھیں اور اس وجہ سے کہ روکتے تھے اللہ کی راہ سے بہت', 'For the wrongdoing of the Jews, We made unlawful to them certain good foods which has been lawful to them, and for their hindering many from Allahs Way;', 'So, because of the transgression of those who became Jews, We prohibited for them good things which were made lawful for them earlier and for their preventing (people), very often, from the way of Allah,'),
(654, 4, 161, 22, 2, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'وَّ اَخۡذِہِمُ الرِّبٰوا وَ قَدۡ نُہُوۡا عَنۡہُ وَ اَکۡلِہِمۡ اَمۡوَالَ النَّاسِ بِالۡبَاطِلِ ؕ وَ اَعۡتَدۡنَا لِلۡکٰفِرِیۡنَ مِنۡہُمۡ عَذَابًا اَلِیۡمًا ﴿۱۶۱﴾', 'اور اس سبب سے بھی کہ باوجود منع کئے جانے کے سود لیتے تھے اور اس سبب سے بھی کہ لوگوں کا مال ناحق کھاتے تھے۔ اور ان میں سے جو کافر ہیں ان کے لئے ہم نے درد دینے والا عذاب تیار کر رکھا ہے۔', 'اور اس وجہ سے کہ سود لیتے تھے اور ان کو اس کی ممانعت ہو چکی تھی اور اس وجہ سے کہ لوگوں کا مال کھاتے تھے ناحق اور  تیار کر رکھا ہے ہم نے کافروں کے واسطے جو ان میں ہیں عذاب دردناک [۲۲۳]', 'And their taking of Riba (usury) though they were forbidden from taking it and their devouring of mens substance wrongfully (bribery, etc.). And We have prepared for the disbelievers among them a painful torment.', 'and for their charging Ribā (usury or interest) while they were forbidden from it, and for their devouring of the properties of the people by false means. We have prepared, for the disbelievers among them, a painful punishment.'),
(655, 4, 162, 22, 2, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'لٰکِنِ الرّٰسِخُوۡنَ فِی الۡعِلۡمِ مِنۡہُمۡ وَ الۡمُؤۡمِنُوۡنَ یُؤۡمِنُوۡنَ بِمَاۤ اُنۡزِلَ اِلَیۡکَ وَ مَاۤ اُنۡزِلَ مِنۡ قَبۡلِکَ وَ الۡمُقِیۡمِیۡنَ الصَّلٰوۃَ وَ الۡمُؤۡتُوۡنَ الزَّکٰوۃَ وَ الۡمُؤۡمِنُوۡنَ بِاللّٰہِ وَ الۡیَوۡمِ الۡاٰخِرِ ؕ اُولٰٓئِکَ سَنُؤۡتِیۡہِمۡ اَجۡرًا عَظِیۡمًا ﴿۱۶۲﴾٪', 'لیکن جو لوگ ان میں سے علم میں پکے ہیں اور جو مومن ہیں وہ اس کتاب پر جو تم پر نازل ہوئی اور جو کتابیں تم سے پہلے نازل ہوئیں سب پر ایمان رکھتے ہیں اور نماز پڑھتے ہیں اور زکوٰۃ دیتے ہیں اور اللہ اور روز آخر کو مانتے ہیں۔ تو ان کو ہم عنقریب اجر عظیم دیں گے۔', 'لیکن جو پختہ ہیں علم میں ان میں اور ایمان والے سو مانتے ہیں اسکو جو نازلہوا تجھ پر اور جو نازل ہوا تجھ سے پہلےاور آفریں ہے نماز پر قائم رہنے والوں کو اور جو دینے والے ہیں زکوٰۃ کے اور یقین رکھنے والے ہیں اللہ پر اور قیامت کے دن پر سو ایسوں کو ہم دیں گے بڑا ثواب [۲۲۴]', 'But those among them who are well-grounded in knowledge, and the believers, believe in what has been sent down to you (Muhammad SAW) and what was sent down before you, and those who perform AsSalat (Iqamat-as-Salat), and give Zakat and believe in Allah and in the Last Day, it is they to whom We shall give a great reward.', 'But those well-grounded in knowledge among them, and the believers, believe in what has been revealed to you and what has been revealed before you, -as well as those observing Salāh and paying Zakāh, and those believing in Allah and the Last Day. To them we shall give a great reward.'),
(656, 4, 163, 23, 3, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'اِنَّاۤ اَوۡحَیۡنَاۤ اِلَیۡکَ کَمَاۤ اَوۡحَیۡنَاۤ اِلٰی نُوۡحٍ وَّ النَّبِیّٖنَ مِنۡۢ بَعۡدِہٖ ۚ وَ اَوۡحَیۡنَاۤ اِلٰۤی اِبۡرٰہِیۡمَ وَ اِسۡمٰعِیۡلَ وَ اِسۡحٰقَ وَ یَعۡقُوۡبَ وَ الۡاَسۡبَاطِ وَ عِیۡسٰی وَ اَیُّوۡبَ وَ یُوۡنُسَ وَ ہٰرُوۡنَ وَ سُلَیۡمٰنَ ۚ وَ اٰتَیۡنَا دَاوٗدَ  زَبُوۡرًا ﴿۱۶۳﴾ۚ', 'اے محمد ﷺ ہم نے تمہاری طرف اسی طرح وحی بھیجی ہے جس طرح نوح  اور انکے بعد والے پیغمبروں کی طرف بھیجی تھی۔ اور ابراہیم اور اسمٰعیل اور اسحٰق اور یعقوب اور اولاد یعقوب اورعیسٰی اور ایوب اور یونس اور ہارون اور سلیمان کی طرف بھی ہم نے وحی بھیجی تھی اور داؤد کو ہم نے زبور بھی عنایت کی تھی۔', 'ہم نے وحی بھیجی تیری طرف [۲۲۵] جیسے وحی بھیجی نوح پر اور ان نبیوں پر جو اسکے بعد ہوئے [۲۲۶] اور وحی بھیجی ابراہیم پر اور اسمٰعیل پر اور اسحٰق پر اور یعقوب پر اور اسکی اولاد پراور عیسٰی پر اور ایوب پر اور یونس پر اور ہارون پر اور سلیمان پر اور ہم نے دی داؤد کو زبور', 'Verily, We have inspired you (O Muhammad SAW) as We inspired Nooh (Noah) and the Prophets after him; We (also) inspired Ibrahim (Abraham), Ismail (Ishmael), Ishaque (Isaac), Yaqoob (Jacob), and AlAsbat (the twelve sons of Yaqoob (Jacob)), Iesa (Jesus), Ayub (Job), Yoonus (Jonah), Haroon (Aaron), and Sulaiman (Solomon), and to Dawood (David) We gave the Zaboor (Psalms).', 'Surely, We have revealed to you as We have revealed to NūH and to the prophets after him; and We have revealed to Ibrāhīm, Ismā‘īl, IsHāq, Ya‘qūb and their children, and to ‘Īsā, Ayyūb, Yūnus, Hārūn and Sulaimān, and We have given Zabūr to Dawūd .'),
(657, 4, 164, 23, 3, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'وَ رُسُلًا قَدۡ قَصَصۡنٰہُمۡ عَلَیۡکَ مِنۡ قَبۡلُ وَ رُسُلًا لَّمۡ نَقۡصُصۡہُمۡ عَلَیۡکَ ؕ وَ کَلَّمَ اللّٰہُ مُوۡسٰی تَکۡلِیۡمًا ﴿۱۶۴﴾ۚ', 'اور بہت سے پیغمبر ہیں کہ جن کے حالات ہم تم سے پیشتر بیان کر چکے ہیں اور بہت سے پیغمبر ہیں جن کے حالات ہم نے تم سے بیان نہیں کئے۔ اور موسٰی سے تو اللہ نے خود کلام فرمایا۔', 'اور بھیجے ایسے رسول کہ جن کا احوال ہم نے سنایا تجھ کو اس سے پہلےاور ایسے رسول جن کا احوال نہیں سنایا تجھ کو اور بایتں کیں اللہ نے موسٰی سے بول کر [۲۲۷]', 'And Messengers We have mentioned to you before, and Messengers We have not mentioned to you, - and to Moosa (Moses) Allah spoke directly.', '(We have sent) some Messengers We have already told you about, and some other Messengers We did not tell you about, and Allah has spoken to Mūsā verbally'),
(658, 4, 165, 23, 3, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'رُسُلًا مُّبَشِّرِیۡنَ وَ مُنۡذِرِیۡنَ لِئَلَّا یَکُوۡنَ لِلنَّاسِ عَلَی اللّٰہِ حُجَّۃٌۢ بَعۡدَ الرُّسُلِ ؕ وَ کَانَ اللّٰہُ عَزِیۡزًا  حَکِیۡمًا ﴿۱۶۵﴾', 'سب پیغمبروں کو اللہ نے خوشخبری سنانے والے اور ڈرانے والے بنا کر بھیجا تھا تاکہ پیغمبروں کے آنے کے بعد لوگوں کو اللہ کے خلاف کوئی حجت نہ ملے اور اللہ غالب ہے حکمت والا ہے۔', 'بھیجے پیغمبر خوشخبری اور ڈر سنانے والے تاکہ باقی نہ رہے لوگوں کو اللہ پر الزام کا موقع رسولوں کے بعد اور اللہ زبردست ہے حکمت والا [۲۲۸]', 'Messengers as bearers of good news as well as of warning in order that mankind should have no plea against Allah after the Messengers. And Allah is Ever AllPowerful, AllWise.', '- Messengers giving good tidings and warning, so that people may have no plea against Allah after the Messengers (have come). Allah is All-Mighty, All-Wise.'),
(659, 4, 166, 23, 3, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'لٰکِنِ اللّٰہُ یَشۡہَدُ بِمَاۤ اَنۡزَلَ اِلَیۡکَ اَنۡزَلَہٗ بِعِلۡمِہٖ ۚ وَ الۡمَلٰٓئِکَۃُ  یَشۡہَدُوۡنَ ؕ وَ کَفٰی بِاللّٰہِ  شَہِیۡدًا ﴿۱۶۶﴾ؕ', 'لیکن اللہ نے جو کتاب تم پر نازل کی ہے اسکی نسبت اللہ گواہی دیتا ہے کہ اس نے اپنے علم سے نازل کی ہے اور فرشتے بھی گواہی دیتے ہیں۔ اور گواہ تو اللہ ہی کافی ہے۔', 'لیکن اللہ شاہد ہے اس پر جو تجھ پر نازل یا کہ یہ نازل کیا ہے اپنے علم کے ساتھ اور فرشتے بھی گواہ ہیں اور اللہ کافی ہےحق ظاہر کرنے والا [۲۲۹]', 'But Allah bears witness to that which He has sent down (the Quran) unto you (O Muhammad SAW), He has sent it down with His Knowledge, and the angels bear witness. And Allah is All-Sufficient as a Witness.', 'But Allah bears witness that what He has revealed to you, has revealed it with His knowledge. The angels too, bear witness, (though) Allah is sufficient as witness.'),
(660, 4, 167, 23, 3, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'اِنَّ الَّذِیۡنَ کَفَرُوۡا وَ صَدُّوۡا عَنۡ سَبِیۡلِ اللّٰہِ  قَدۡ ضَلُّوۡا ضَلٰلًۢا  بَعِیۡدًا ﴿۱۶۷﴾', 'جن لوگوں نے کفر کیا اور لوگوں کو اللہ کے رستے سے روکا وہ رستے سے بھٹک کر دور جا پڑے۔', 'جو لوگ کافر ہوئے اور روکا اللہ کی راہ سے وہ بہک کر دور جا پڑے', 'Verily, those who disbelieve (by concealing the truth about Prophet Muhammad SAW and his message of true Islamic Monotheism written with them in the Taurat (Torah) and the Injeel (Gospel)) and prevent (mankind) from the Path of Allah (Islamic Monotheism), they have certainly strayed far away. (Tafsir Al-Qurtubee). (See V.7:157)', 'Surely, those who disbelieved and prevented (people) from the way of Allah have gone far astray.'),
(661, 4, 168, 23, 3, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'اِنَّ الَّذِیۡنَ کَفَرُوۡا وَ ظَلَمُوۡا لَمۡ  یَکُنِ اللّٰہُ لِیَغۡفِرَ لَہُمۡ  وَ لَا  لِیَہۡدِیَہُمۡ  طَرِیۡقًا ﴿۱۶۸﴾ۙ', 'جو لوگ کافر ہوئے اور ظلم کرتے رہے اللہ انکو بخشنے والا نہیں اور نہ انہیں رستہ ہی دکھائے گا۔', 'جو لوگ کافر ہوئے اور حق دبا رکھا ہر گز اللہ بخشنے والا نہیں ان کو اور نہ دکھلا دے گا ان کو سیدھی راہ', 'Verily, those who disbelieve and did wrong (by concealing the truth about Prophet Muhammad SAW and his message of true Islamic Monotheism written with them in the Taurat (Torah) and the Injeel (Gospel)), Allah will not forgive them, nor will He guide them to any way, - (Tafsir Al-Qurtubee).', 'Surely, those who disbelieved and transgressed, Allah is not going to forgive them, nor to lead them to a way'),
(662, 4, 169, 23, 3, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'اِلَّا طَرِیۡقَ جَہَنَّمَ خٰلِدِیۡنَ فِیۡہَاۤ  اَبَدًا ؕ وَ کَانَ ذٰلِکَ عَلَی اللّٰہِ  یَسِیۡرًا ﴿۱۶۹﴾', 'ہاں سوائے دوزخ کے رستے کے جس میں وہ ہمیشہ ہمیشہ رہیں گے اور یہ بات اللہ کو آسان ہے۔', 'مگر راہ دوزخ کی رہا کریں اس میں ہمیشہ اور یہ اللہ پر آسان ہے [۲۳۰]', 'Except the way of Hell, to dwell therein forever, and this is ever easy for Allah.', 'other than the way of Jahannam where they are to remain for ever. That is easy for Allah.'),
(663, 4, 170, 23, 3, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'یٰۤاَیُّہَا النَّاسُ قَدۡ جَآءَکُمُ الرَّسُوۡلُ بِالۡحَقِّ مِنۡ رَّبِّکُمۡ فَاٰمِنُوۡا خَیۡرًا لَّکُمۡ ؕ وَ اِنۡ تَکۡفُرُوۡا فَاِنَّ لِلّٰہِ مَا فِی السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ کَانَ اللّٰہُ عَلِیۡمًا حَکِیۡمًا ﴿۱۷۰﴾', 'لوگو! یہ پیغمبر تمہارے پاس تمہارے پروردگار کی طرف سے حق بات لیکر آئے ہیں تو ان پر ایمان لاؤ یہی تمہارے حق میں بہتر ہے۔ اور اگر کفر کرو گے تو جان رکھو کہ جو کچھ آسمانوں اور زمین میں ہے سب اللہ ہی کا ہے۔ اور اللہ سب کچھ جاننے والا ہے حکمت والا ہے۔', 'اے لوگو تمہارے پاس رسول آ چکا ٹھیک بات لیکر تمہارے رب کی سو مان لو تاکہ بھلا ہو تمہارا اور اگر نہ مانو گے تو اللہ کا ہے جو کچھ ہے آسمانوں میں اور زمین میں اور ہے اللہ سب کچھ جاننے والا حکمت  والا [۲۳۱]', 'O mankind! Verily, there has come to you the Messenger (Muhammad SAW) with the truth from your Lord, so believe in him, it is better for you. But if you disbelieve, then certainly to Allah belongs all that is in the heavens and the earth. And Allah is Ever AllKnowing, AllWise.', 'O people, the Messenger has come to you with the truth from your Lord. So, believe. That is good for you. If you disbelieve, then, to Allah belongs what is in the heavens and the earth. Allah is All-Knowing, All-Wise.'),
(664, 4, 171, 23, 3, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'یٰۤاَہۡلَ الۡکِتٰبِ لَا تَغۡلُوۡا فِیۡ دِیۡنِکُمۡ وَ لَا تَقُوۡلُوۡا عَلَی اللّٰہِ  اِلَّا الۡحَقَّ ؕ اِنَّمَا الۡمَسِیۡحُ عِیۡسَی ابۡنُ مَرۡیَمَ رَسُوۡلُ اللّٰہِ وَ کَلِمَتُہٗ ۚ اَلۡقٰہَاۤ اِلٰی مَرۡیَمَ وَ رُوۡحٌ مِّنۡہُ ۫ فَاٰمِنُوۡا بِاللّٰہِ وَ رُسُلِہٖ ۚ۟ وَ لَا تَقُوۡلُوۡا ثَلٰثَۃٌ ؕ اِنۡتَہُوۡا خَیۡرًا  لَّکُمۡ ؕ اِنَّمَا اللّٰہُ اِلٰہٌ وَّاحِدٌ ؕ سُبۡحٰنَہٗۤ اَنۡ یَّکُوۡنَ لَہٗ  وَلَدٌ ۘ لَہٗ  مَا  فِی السَّمٰوٰتِ وَ مَا  فِی  الۡاَرۡضِ ؕ وَ کَفٰی بِاللّٰہِ  وَکِیۡلًا ﴿۱۷۱﴾٪', 'اے اہل کتاب اپنے دین کی بات میں حد سے نہ بڑھو اور اللہ کے بارے میں حق کے سوا کچھ نہ کہو۔ مسیح یعنی مریم کے بیٹے عیسٰی بس اللہ کے رسول ہی تھے اور اس کا خاص حکم تھے جو اس نے مریم کی طرف بھیجا تھا اور اس کی طرف سے ایک روح تھے۔ تو اللہ اور اسکے رسولوں پر ایمان لاؤ۔ اور یہ نہ کہو کہ خدا تین ہیں اس اعتقاد سے باز آؤ کہ ایسا کرنا تمہارے حق میں بہتر ہے۔ اللہ ہی معبود واحد ہے۔ اور اس سے پاک ہے کہ اسکے اولاد ہو۔ جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب اسی کا ہے۔ اور اللہ ہی کارساز کافی ہے۔', 'اے کتاب والو مت مبالغہ کرو اپنے دین کی بات میں اور مت کہو اللہ کی شان میں مگر پکی بات بیشک مسیح جو ہے عیسٰی مریم کا بیٹا وہ رسول ہے اللہ کا اور اس کا کلام ہے جس کو ڈالا مریم کی طرف اور روح ہے اس کے ہاں کی سو مانو اللہ کو اور اسکے رسولوں کو اور نہ کہو کہ خدا تین ہیں اس بات کو چھوڑ دو بہتر ہو گا تمہارے واسطے بیشک اللہ معبود ہے اکیلا اسکے لائق نہیں ہے کہ اس کے اولاد ہو ]۲۳۲] اسی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے اور کافی ہے اللہ کارساز [۲۳۳]', 'O people of the Scripture (Jews and Christians)! Do not exceed the limits in your religion, nor say of Allah aught but the truth. The Messiah Iesa (Jesus), son of Maryam (Mary), was (no more than) a Messenger of Allah and His Word, (\"Be!\" - and he was) which He bestowed on Maryam (Mary) and a spirit (Rooh) created by Him; so believe in Allah and His Messengers. Say not: \"Three (trinity)!\" Cease! (it is) better for you. For Allah is (the only) One Ilah (God), Glory be to Him (Far Exalted is He) above having a son. To Him belongs all that is in the heavens and all that is in the earth. And Allah is AllSufficient as a Disposer of affairs.', 'O people of the Book, be not excessive in your Faith, and do not say about Allah anything but the truth.The MasīH ‘Īsā, the son of Maryam, is only a Messenger of Allah, and His Word that He had delivered to Maryam, and a spirit from Him. So, believe in Allah and His Messengers. Do not say “Three”. Stop it. That is good for you. Allah is the only One God. He is far too pure to have a son. To Him belongs what is in the heavens and what is in the earth. And Allah is enough to trust in.'),
(665, 4, 172, 24, 4, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'لَنۡ یَّسۡتَنۡکِفَ الۡمَسِیۡحُ اَنۡ یَّکُوۡنَ عَبۡدًا لِّلّٰہِ وَ لَا الۡمَلٰٓئِکَۃُ الۡمُقَرَّبُوۡنَ ؕ وَ مَنۡ یَّسۡتَنۡکِفۡ عَنۡ عِبَادَتِہٖ وَ یَسۡتَکۡبِرۡ فَسَیَحۡشُرُہُمۡ  اِلَیۡہِ جَمِیۡعًا ﴿۱۷۲﴾', 'مسیح اس بات سے عار نہیں رکھتے کہ اللہ کے بندے ہوں اور نہ مقرب فرشتے عار رکھتے ہیں اور جو شخص اللہ کا بندہ ہونے کو موجب عار سمجھے اور سرکشی کرے تو اللہ سب لوگوں کو اپنے پاس جمع کر لے گا۔', 'مسیح کو اس سے ہرگز عار نہیں کہ وہ بندہ ہو اللہ کا اور نہ فرشتوں کو جو مقرب ہیں [۲۳۴] اور جس کو عار آوے اللہ کی بندگی سے اور تکبر کرے سو وہ جمع کرے گا ان سب کو اپنے پاس اکٹھا', 'The Messiah will never be proud to reject to be a slave to Allah, nor the angels who are near (to Allah). And whosoever rejects His worship and is proud, then He will gather them all together unto Himself.', 'The MasīH shall never spurn to be a slave of Allah, nor shall the angels who are stationed near to Him. And whoever spurns to worship Him, and shows arrogance,-then, He shall gather all of them before Himself.'),
(666, 4, 173, 24, 4, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'فَاَمَّا الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ فَیُوَفِّیۡہِمۡ اُجُوۡرَہُمۡ وَ یَزِیۡدُہُمۡ مِّنۡ فَضۡلِہٖ ۚ وَ اَمَّا الَّذِیۡنَ اسۡتَنۡکَفُوۡا وَ اسۡتَکۡبَرُوۡا فَیُعَذِّبُہُمۡ  عَذَابًا اَلِیۡمًا ۬ۙ وَّ لَا یَجِدُوۡنَ لَہُمۡ مِّنۡ دُوۡنِ اللّٰہِ  وَلِیًّا وَّ لَا نَصِیۡرًا ﴿۱۷۳﴾', 'اب جو لوگ ایمان لائے اور نیک کام کرتے رہے وہ ان کو ان کا پورا پورا بدلہ دے گا اور اپنے فضل سے کچھ زیادہ بھی عنایت کرے گا۔ اور جنہوں نے بندہ ہونے سے عار و انکار اور تکبر کیا تو ان کو وہ تکلیف دینے والا عذاب دے گا۔ اور وہ اللہ کے سوا اپنا حامی اور مددگار نہ پائیں گے۔', 'پھر جو لوگ ایمان لائے اور عمل کئے انہوں نے اچھے تو انکو پورا دے گا ان کا ثواب اور زیادہ دے گا اپنے فضل سے اور جنہوں نے عار کی اور تکبر کیا سو انکو عذاب دے گا عذاب دردناک اور نہ پاویں گے اپنے واسطے اللہ کے سوا کوئی حمایتی اور نہ مددگار [۲۳۵]', 'So, as for those who believed (in the Oneness of Allah - Islamic Monotheism) and did deeds of righteousness, He will give their (due) rewards, and more out of His Bounty. But as for those who refuse His worship and were proud, He will punish them with a painful torment . And they will not find for themselves besides Allah any protector or helper.', 'As for those who believe and do good deeds, He shall give them their reward in full, and give them more out of His grace. But, to those who spurn and show arrogance, He shall give a painful punishment, and they shall find for themselves neither a friend other than Allah, nor a helper.'),
(667, 4, 174, 24, 4, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'یٰۤاَیُّہَا النَّاسُ قَدۡ جَآءَکُمۡ  بُرۡہَانٌ مِّنۡ رَّبِّکُمۡ وَ اَنۡزَلۡنَاۤ اِلَیۡکُمۡ نُوۡرًا مُّبِیۡنًا ﴿۱۷۴﴾', 'لوگو تمہارے پروردگار کی طرف سے تمہارے پاس ایک بڑی دلیل آ چکی ہے اور ہم نے کفر اور ضلالت کا اندھیرا دور کرنے کو تمہاری طرف راہ روشن کر دینے والا نور بھیج دیا ہے۔', 'اے لوگو تمہارے پاس پہنچ چکی تمہارے رب کی طرف سےسند اور اتاری ہم نے تم پر روشنی واضح', 'O mankind! Verily, there has come to you a convincing proof (Prophet Muhammad SAW) from your Lord, and We sent down to you a manifest light (this Quran).', 'O people, a proof has come to you from your Lord, and We have sent down to you a vivid light.'),
(668, 4, 175, 24, 4, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'فَاَمَّا الَّذِیۡنَ اٰمَنُوۡا بِاللّٰہِ وَ اعۡتَصَمُوۡا بِہٖ  فَسَیُدۡخِلُہُمۡ  فِیۡ  رَحۡمَۃٍ مِّنۡہُ وَ فَضۡلٍ ۙ وَّ یَہۡدِیۡہِمۡ  اِلَیۡہِ صِرَاطًا  مُّسۡتَقِیۡمًا ﴿۱۷۵﴾ؕ', 'پس جو لوگ اللہ پر ایمان لائے اور اس کے دین کی رسی کو مضبوط پکڑے رہے ان کو وہ اپنی رحمت اور فضل کی بہشتوں میں داخل کرے گا اور اپنی طرف پہنچنے کا سیدھا رستہ دکھائے گا۔', 'سو جو لوگ ایمان لائے اللہ پر اور اس کو مضبوط پکڑا تو ان کو داخل کرے گا اپنی رحمت میں اور فضل میں اور پہنچاوے گا ان کو اپنی طرف سیدھے راستہ پر [۲۳۶]', 'So, as for those who believed in Allah and held fast to Him, He will admit them to His Mercy and Grace (i.e. Paradise), and guide them to Himself by a Straight Path.', 'Now those who believe in Allah and hold on to Him - He shall admit them into Mercy from Him, and Grace, and shall lead them to Himself through a straight path.'),
(669, 4, 176, 24, 4, 6, 'لَا یُحِبُّ اللّٰہُ ', 'النسآء', 'یَسۡتَفۡتُوۡنَکَ ؕ قُلِ اللّٰہُ یُفۡتِیۡکُمۡ فِی الۡکَلٰلَۃِ ؕ اِنِ امۡرُؤٌا ہَلَکَ لَیۡسَ لَہٗ  وَلَدٌ وَّ لَہٗۤ اُخۡتٌ فَلَہَا نِصۡفُ مَا تَرَکَ ۚ وَ ہُوَ یَرِثُہَاۤ اِنۡ لَّمۡ یَکُنۡ لَّہَا وَلَدٌ ؕ فَاِنۡ کَانَتَا اثۡنَتَیۡنِ فَلَہُمَا الثُّلُثٰنِ مِمَّا تَرَکَ ؕ وَ  اِنۡ کَانُوۡۤا اِخۡوَۃً رِّجَالًا وَّ  نِسَآءً فَلِلذَّکَرِ مِثۡلُ حَظِّ الۡاُنۡثَیَیۡنِ ؕ یُبَیِّنُ اللّٰہُ  لَکُمۡ اَنۡ تَضِلُّوۡا ؕ وَ اللّٰہُ بِکُلِّ شَیۡءٍ عَلِیۡمٌ ﴿۱۷۶﴾٪', 'اے پیغمبر لوگ تم سے کلالہ کے بارے میں حکم دریافت کرتے ہیں۔ کہہ دو کہ اللہ کلالہ کے بارے میں یہ حکم دیتا ہے کہ اگر کوئی ایسا مرد مر جائے جسکے اولاد نہ ہو اور نہ ماں باپ اور اسکی ایک بہن ہو تو اسکو بھائی کے ترکے میں سے آدھا حصہ ملے گا۔ اور اگر بہن مر جائے اور اسکے اولاد نہ ہو تو اسکے تمام مال کا وارث بھائی ہو گا۔ اور اگر مرنے والے بھائی کی دو بہنیں ہوں تو دونوں کو بھائی کے ترکے میں سے دو تہائی۔ اور اگر بھائی اور بہن یعنی مرد اور عورتیں ملے جلے وارث ہوں تو مرد کا حصہ دو عورتوں کے حصے کے برابر ہے یہ احکام اللہ تم سے اسلئے بیان فرماتا ہے کہ بھٹکتے نہ پھرو اور اللہ ہر چیز سے خوب واقف ہے۔', 'حکم پوچھتے ہیں تجھ سے سو کہہ دے اللہ حکم بتاتا ہے تم کو کلالہ کا [۲۳۷] اگر کوئی مرد مر گیا اور اس کے بیٹا نہیں اور اس کے ایک بہن ہے تو اس کو پہنچے آدھا اس کا جو چھوڑ مرا [۲۳۸] اور وہ بھائی وارث ہے اس بہن کا اگر نہ ہو اس کے بیٹا [۲۳۹] پھر اگر بہنیں دو ہوں تو انکو پہنچے دو تہائی اس مال کا جو چھوڑ مرا [۲۴۰] اور اگر کئ شخص ہوں اسی رشتہ کے کچھ مرد اور کچھ عورتیں تو ایک مرد کا حصہ ہے برابر دو عورتوں کے [۲۴۱] بیان کرتا ہے اللہ تمہارے واسطے تاکہ تم گمراہ نہ ہو [۲۴۲] اور اللہ ہر چیز سےواقف ہے [۲۴۳]', 'They ask you for a legal verdict. Say: \"Allah directs (thus) about AlKalalah (those who leave neither descendants nor ascendants as heirs). If it is a man that dies, leaving a sister, but no child, she shall have half the inheritance. If (such a deceased was) a woman, who left no child, her brother takes her inheritance. If there are two sisters, they shall have two-thirds of the inheritance; if there are brothers and sisters, the male will have twice the share of the female. (Thus) does Allah makes clear to you (His Law) lest you go astray. And Allah is the All-Knower of everything.\"', 'They seek a ruling from you. Say, “Allah gives you the ruling concerning Kalālah . If a person dies having no son, but he does have a sister, then, she will get one half of what he leaves. (On the other hand) He will inherit her if she has no child. If they are two (sisters), they will get two third of what he leaves. If they are brothers and sisters, both male and female, then, the male will get a share equal to that of two females.” Allah explains to you, lest you should go astray. Allah has full knowledge of everything.'),
(670, 5, 1, 1, 5, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اَوۡفُوۡا بِالۡعُقُوۡدِ ۬ؕ اُحِلَّتۡ لَکُمۡ بَہِیۡمَۃُ الۡاَنۡعَامِ  اِلَّا مَا یُتۡلٰی عَلَیۡکُمۡ غَیۡرَ مُحِلِّی الصَّیۡدِ وَ اَنۡتُمۡ حُرُمٌ ؕ اِنَّ اللّٰہَ  یَحۡکُمُ مَا یُرِیۡدُ ﴿۱﴾', 'اے ایمان والو اپنے معاہدوں کو پورا کرو۔ تمہارے لئے چرنے والے مویشی حلال کر دیئے گئے ہیں۔ بجز انکے جو تمہیں پڑھ کر سنائے جاتے ہیں۔ مگر حالت احرام میں شکار کو حلال نہ جاننا۔ اللہ جیسا چاہتا ہے حکم دیتا ہے۔', 'اے ایمان والو پورا کرو عہدوں کو [۱] حلا ل ہوئے تمہارے لئے چوپائے مویشی [۲] سو اے انکے جو تم کو آگے سنائےجاویں گے [۳] مگر حلال نہ جانو شکار کو احرام کی حالت میں [۴] اللہ حکم کرتا ہے جو چاہے [۵]', 'O you who believe! Fulfill (your) obligations. Lawful to you (for food) are all the beasts of cattle except that which will be announced to you (herein), game (also) being unlawful when you assume Ihram for Hajj or Umrah (pilgrimage). Verily, Allah commands that which He wills.', 'O you who believe, fulfill the contracts. The animals from the cattle have been made lawful for you, except that which shall be read over to you, provided that you do not treat hunting as lawful while you are in IHrām. Surely, Allah ordains what He wills.'),
(671, 5, 2, 1, 5, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تُحِلُّوۡا شَعَآئِرَ اللّٰہِ وَ لَا الشَّہۡرَ الۡحَرَامَ وَ لَا الۡہَدۡیَ وَ لَا الۡقَلَآئِدَ وَ لَاۤ  آٰمِّیۡنَ الۡبَیۡتَ الۡحَرَامَ یَبۡتَغُوۡنَ فَضۡلًا مِّنۡ رَّبِّہِمۡ وَ رِضۡوَانًا ؕ وَ اِذَا حَلَلۡتُمۡ فَاصۡطَادُوۡا ؕ وَ لَا یَجۡرِمَنَّکُمۡ شَنَاٰنُ قَوۡمٍ اَنۡ صَدُّوۡکُمۡ عَنِ الۡمَسۡجِدِ الۡحَرَامِ اَنۡ تَعۡتَدُوۡا ۘ وَ تَعَاوَنُوۡا عَلَی الۡبِرِّ وَ التَّقۡوٰی ۪ وَ لَا تَعَاوَنُوۡا عَلَی الۡاِثۡمِ وَ الۡعُدۡوَانِ ۪ وَ اتَّقُوا اللّٰہَ ؕ اِنَّ اللّٰہَ  شَدِیۡدُ الۡعِقَابِ ﴿۲﴾', 'مومنو! اللہ کے نام کی چیزوں کی بیحرمتی نہ کرنا اور نہ ادب کے مہینے کی اور نہ قربانی کے جانوروں کی اور نہ ان جانوروں کی جو اللہ کی نذر کر دیئے گئے ہوں کہ جن کے گلوں میں پٹے پڑے ہوں اور نہ ان لوگوں کی جو حرمت والے گھر یعنی بیت اللہ کو جارہے ہوں اپنے پروردگار کے فضل اور اسکی خوشنودی کے طلبگار بنے ہوئے۔ اور جب احرام اتار دو تو پھر اختیار ہے کہ شکار کرو۔ اور کچھ لوگوں کی دشمنی اس وجہ سے کہ انہوں نے تمکو مسجد حرام سے روکا تھا تمہیں اس بات پر آمادہ نہ کر دے کہ تم زیادتی کرنے لگو۔ اور دیکھو نیکی اور پرہیزگاری کے کاموں میں ایک دوسرے کی مدد کیا کرو۔ اور گناہ اور ظلم کی باتوں میں کسی کے ساتھ تعاون نہ کرو اور اللہ سے ڈرتے رہو۔ کچھ شک نہیں کہ اللہ کا عذاب سخت ہے۔', 'اے ایمان والو حلال نہ سمجھو اللہ کی نشانیوں کو [۶] اور نہ ادب والے مہینہ کو [۷] اور نہ اس جانور کو جو نیاز کعبہ کی ہو اور نہ جنکے گلے میں پٹا ڈال کر لیجاویں کعبہ کو [۸] اور نہ آنے والوں کو حرمت والے گھر کی طرف جو ڈھونڈتے ہیں فضل اپنے رب کا اور اسکی خوشی [۹] اور جب احرام سے نکلو تو شکار کر لو [۱۰] اور باعث نہ ہو تم کو اس قوم کی دشمنی جو کہ تم کو روکتی تھی حرمت والی مسجد سے اس پر کہ زیادتی کرنے لگو [۱۱] اور آپس میں مدد کرو نیک کام پر اور پرہیزگاری پر اور مدد نہ کرو گناہ پر اور ظلم پر [۱۲] اور ڈرتے رہو اللہ سے بیشک اللہ کا عذاب سخت ہے [۱۳]', 'O you who believe! Violate not the sanctity of the Symbols of Allah, nor of the Sacred Month, nor of the animals brought for sacrifice, nor the garlanded people or animals, etc. (Marked by the garlands on their necks made from the outer part of the treestems (of Makkah) for their security), nor the people coming to the Sacred House (Makkah), seeking the bounty and good pleasure of their Lord. But when you finish the Ihram (of Hajj or Umrah), you may hunt, and let not the hatred of some people in (once) stopping you from AlMasjidalHaram (at Makkah) lead you to transgression (and hostility on your part). Help you one another in AlBirr and AtTaqwa (virtue, righteousness and piety); but do not help one another in sin and transgression. And fear Allah. Verily, Allah is Severe in punishment.', 'O you who believe, do not violate (the sanctity) of the Marks of Allah, nor of the sacred month, nor of the sacrificial animal, nor of the garlands, 6 nor of those proceeding to the Sacred House, seeking the grace of their Lord and (His) Pleasure. When you are out of IHrām, you may hunt. Malice against a people for their having prevented you from Al-Masjid-ul-Harām, should not cause you to cross the limits. Help each other in righteousness and piety, and do not help each other in sin and aggression. Fear Allah. Surely, Allah is severe at punishment.'),
(672, 5, 3, 1, 5, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'حُرِّمَتۡ عَلَیۡکُمُ الۡمَیۡتَۃُ وَ الدَّمُ وَ لَحۡمُ الۡخِنۡزِیۡرِ وَ مَاۤ اُہِلَّ لِغَیۡرِ اللّٰہِ بِہٖ وَ الۡمُنۡخَنِقَۃُ وَ الۡمَوۡقُوۡذَۃُ وَ الۡمُتَرَدِّیَۃُ وَ النَّطِیۡحَۃُ وَ مَاۤ اَکَلَ السَّبُعُ اِلَّا مَا ذَکَّیۡتُمۡ ۟ وَ مَا ذُبِحَ عَلَی النُّصُبِ وَ اَنۡ تَسۡتَقۡسِمُوۡا بِالۡاَزۡلَامِ ؕ ذٰلِکُمۡ فِسۡقٌ ؕ اَلۡیَوۡمَ  یَئِسَ الَّذِیۡنَ  کَفَرُوۡا مِنۡ دِیۡنِکُمۡ فَلَا تَخۡشَوۡہُمۡ وَ اخۡشَوۡنِ ؕ اَلۡیَوۡمَ اَکۡمَلۡتُ لَکُمۡ دِیۡنَکُمۡ وَ اَتۡمَمۡتُ عَلَیۡکُمۡ نِعۡمَتِیۡ وَ رَضِیۡتُ لَکُمُ الۡاِسۡلَامَ دِیۡنًا ؕ فَمَنِ اضۡطُرَّ فِیۡ مَخۡمَصَۃٍ غَیۡرَ   مُتَجَانِفٍ لِّاِثۡمٍ ۙ فَاِنَّ اللّٰہَ غَفُوۡرٌ  رَّحِیۡمٌ ﴿۳﴾', 'تم پر مرا ہوا جانور اور بہتا لہو اور سور کا گوشت اور جس چیز پر اللہ کے سوا کسی اور کا نام پکارا جائے اور جو جانور گلا گھٹ کر مر جائے اور جو چوٹ لگ کر مر جائے اور جو گر کر مر جائے اور جو سینگ لگ کر مر جائے یہ سب حرام ہیں اور وہ جانور بھی جس کو درندے پھاڑ کھائیں۔ مگر جس کو تم مرنے سے پہلے ذبح کر لو اور وہ جانور بھی جو غیر اللہ کے آستانے پر ذبح کیا جائے اور یہ بھی کہ پاسوں سے قسمت معلوم کرو یہ سب گناہ کے کام ہیں آج کافر تمہارے دین سے ناامید ہو گئے ہیں تو ان سے مت ڈرو اور مجھی سے ڈرتے رہو۔ آج میں نے تمہارے لئے تمہارا دین کامل کر دیا ہے اور اپنی نعمتیں تم پر پوری کر دیں اور تمہارے لئے اسلام کو بطور دین پسند کر لیا ہاں جو شخص بھوک میں ناچار ہو جائے بشرطیکہ گناہ کی طرف مائل نہ ہو تو اللہ بخشنے ہے والا بڑا مہربان ہے۔', 'حرام ہوا تم پر مردہ جانور [۱۴] اور لہو [۱۵] اور گوشت سور کا اور جس جانور پر نام پکارا جائے اللہ کے سوا کسی اور کا اور جو مر گیا ہو گلا گھونٹنے سے یاچوٹ سے یا اونچے سے گر کر یا سینگ مارنے سے اور جس کو کھایا ہو درندہ نے مگر جس کو تم نےذبح کر لیا اور حرام ہے جو ذبح ہوا کسی تھان پر [۱۶] اور یہ کہ تقسیم کرو جوئے کے تیروں سے [۱۷] یہ گناہ کا کام ہے آج ناامید ہو گئے  کافر تمہارے دین سے سو ان سے مت ڈرو اور مجھ سے ڈرو [۱۸] آج میں پورا کر چکا تمہارے لئے دین تمہارا [۱۹] اور پورا کیا تم پر میں نے احسان اپنا [۲۰] اور پسند کیا میں نے تمہارے واسطےاسلام کو دین [۲۱] پھر جو کوئی لاچار ہو جاوے بھوک میں لیکن گناہ پر مائل نہ ہو تو اللہ بخشنے والا مہربان ہے [۲۲]', 'Forbidden to you (for food) are: Al-Maytatah (the dead animals - cattle-beast not slaughtered), blood, the flesh of swine, and the meat of that which has been slaughtered as a sacrifice for others than Allah, or has been slaughtered for idols, etc., or on which Allahs Name has not been mentioned while slaughtering, and that which has been killed by strangling, or by a violent blow, or by a headlong fall, or by the goring of horns - and that which has been (partly) eaten by a wild animal - unless you are able to slaughter it (before its death) and that which is sacrificed (slaughtered) on AnNusub (stone altars). (Forbidden) also is to use arrows seeking luck or decision, (all) that is Fisqun (disobedience of Allah and sin). This day, those who disbelieved have given up all hope of your religion, so fear them not, but fear Me. This day, I have perfected your religion for you, completed My Favour upon you, and have chosen for you Islam as your religion. But as for him who is forced by severe hunger, with no inclination to sin (such can eat these above-mentioned meats), then surely, Allah is OftForgiving, Most Merciful.', 'Prohibited for you are: carrion, blood, the flesh of swine, and those upon which (a name) other than that of Allah has been invoked (at the time of slaughter), animal killed by strangulation, or killed by a blow, or by a fall, or by goring, or that which is eaten by a beast unless you have properly slaughtered it; and that which has been slaughtered before the idols, and that you determine shares through the arrows. (All of) this is sin. Today those who disbelieve have lost all hope of (damaging) your faith. So, do not fear them, and fear Me. Today, I have perfected your religion for you, and have completed My blessing upon you, and chosen Islam as Dīn (religion and a way of life) for you. But whoever is compelled by extreme hunger, having no inclination towards sin, then Allah is Most-Forgiving, Very-Merciful.'),
(673, 5, 4, 1, 5, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یَسۡـَٔلُوۡنَکَ مَاذَاۤ  اُحِلَّ لَہُمۡ ؕ قُلۡ اُحِلَّ لَکُمُ الطَّیِّبٰتُ ۙ وَ مَا عَلَّمۡتُمۡ مِّنَ الۡجَوَارِحِ مُکَلِّبِیۡنَ تُعَلِّمُوۡنَہُنَّ مِمَّا عَلَّمَکُمُ اللّٰہُ ۫ فَکُلُوۡا مِمَّاۤ  اَمۡسَکۡنَ عَلَیۡکُمۡ وَ اذۡکُرُوا اسۡمَ اللّٰہِ عَلَیۡہِ ۪ وَ اتَّقُوا اللّٰہَ ؕ اِنَّ اللّٰہَ سَرِیۡعُ  الۡحِسَابِ ﴿۴﴾', 'اے نبی تم سے پوچھتے ہیں کہ کون کونسی چیزیں ان کے لئے حلال ہیں ان سے کہہ دو کہ سب پاکیزہ چیزیں تم کو حلال ہیں اور وہ شکار بھی حلال ہے جو تمہارے لئے ان شکاری جانوروں نے پکڑا ہو جنکو تم نے سدھا رکھا ہو اور جس طریق سے اللہ نے تمہیں شکار کرنا سکھایا ہے اس طریق سے تم نے انکو سکھایا ہو تو جو شکار وہ تمہارے لئے پکڑ رکھیں اسکو کھا لیا کرو اور شکاری جانوروں کے چھوڑتے وقت اللہ کا نام  لے لیا کرو اور اللہ سے ڈرتے رہو۔ بیشک اللہ جلد حساب لینے والا ہے۔', 'تجھ سے پوچھتے ہیں کہ کیا چیز ان کےلئے حلال ہے کہہ دے تم کو حلال ہیں ستھری چیزیں [۲۳] اور جو سدھاؤ شکاری جانور شکار پر دوڑانے کو کہ ان کو سکھاتے ہو اس میں سےجو اللہ نے تم کو سکھایا ہے سو کھاؤ اس میں سے جو پکڑ رکھیں تمہارےواسطے اور اللہ کا نام لو اس پر [۲۴] اور ڈرتے رہو اللہ سے بیشک اللہ جلد لینے والا ہے حساب [۲۵]', 'They ask you (O Muhammad SAW) what is lawful for them (as food ). Say: \"Lawful unto you are AtTayyibat (all kind of Halal (lawfulgood) foods which Allah has made lawful (meat of slaughtered eatable animals, milk products, fats, vegetables and fruits, etc.)). And those beasts and birds of prey which you have trained as hounds, training and teaching them (to catch) in the manner as directed to you by Allah; so eat of what they catch for you, but pronounce the Name of Allah over it, and fear Allah. Verily, Allah is Swift in reckoning.\"', 'They ask you as to what has been made lawful for them. Say, “Made lawful for you are good things, and (hunting through) birds and beasts of prey that you train, teaching them out of what Allah has taught you. So, eat of what they hold for you, and recite the name of Allah upon it.” Fear Allah. Surely, Allah is swift at reckoning.'),
(674, 5, 5, 1, 5, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'اَلۡیَوۡمَ اُحِلَّ لَکُمُ الطَّیِّبٰتُ ؕ وَ طَعَامُ الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ حِلٌّ لَّکُمۡ ۪ وَ طَعَامُکُمۡ حِلٌّ لَّہُمۡ ۫ وَ الۡمُحۡصَنٰتُ مِنَ الۡمُؤۡمِنٰتِ وَ الۡمُحۡصَنٰتُ مِنَ الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ مِنۡ قَبۡلِکُمۡ اِذَاۤ اٰتَیۡتُمُوۡہُنَّ اُجُوۡرَہُنَّ مُحۡصِنِیۡنَ غَیۡرَ مُسٰفِحِیۡنَ وَ لَا مُتَّخِذِیۡۤ اَخۡدَانٍ ؕ وَ مَنۡ یَّکۡفُرۡ بِالۡاِیۡمَانِ فَقَدۡ حَبِطَ عَمَلُہٗ ۫ وَ ہُوَ فِی الۡاٰخِرَۃِ  مِنَ  الۡخٰسِرِیۡنَ ٪﴿۵﴾', 'آج تمہارے لئے سب پاکیزہ چیزیں حلال کر دی گئیں اور اہل کتاب کا کھانا بھی تم کو حلال ہے اور تمہارا کھانا انکو حلال ہے۔ اور پاکدامن مومن عورتیں اور پاکدامن اہل کتاب عورتیں بھی حلال ہیں جبکہ ان کا مہر انہیں دے دو۔ اور نکاح سے عفت قائم رکھنی مقصود ہو نہ کہ کھلی بدکاری کرنی اور نہ چھپی دوستی کرنی۔ اور جو شخص ایمان کا منکر ہوا اس کے عمل ضائع ہو گئے۔ اور وہ آخرت میں نقصان پانے والوں میں ہو گا۔', 'آج حلال ہوئیں تم کو سب ستھری چیزیں [۲۶] اور اہل کتاب کا کھانا تم کو حلال ہے [۲۷] اور تمہارا کھانا ان کو حلال ہے [۲۸] اور حلال ہیں تم کو پاکدامن عورتیں مسلمان [۲۹] اور پاکدامن عورتیں ان میں سےجن کو دی گئ کتاب [۳۰] تم سے پہلےجب دو ان کو مہر ان کے قید میں لانے کو [۳۱] نہ مستی نکالنے کو اور نہ چھپی آشنائی کرنے کو [۳۲] اور جو منکر ہوا ایمان سے تو ضائع ہوئی محنت اس کی اور آخرت میں وہ ٹوٹے والوں میں ہے [۳۳]', 'Made lawful to you this day are AtTayyibat (all kinds of Halal (lawful) foods, which Allah has made lawful (meat of slaughtered eatable animals, etc., milk products, fats, vegetables and fruits, etc.). The food (slaughtered cattle, eatable animals, etc.) of the people of the Scripture (Jews and Christians) is lawful to you and yours is lawful to them. (Lawful to you in marriage) are chaste women from the believers and chaste women from those who were given the Scripture (Jews and Christians) before your time, when you have given their due Mahr (bridal money given by the husband to his wife at the time of marriage), desiring chastity (i.e. taking them in legal wedlock) not committing illegal sexual intercourse, nor taking them as girl-friends. And whosoever disbelieves in the Oneness of Allah and in all the other Articles of Faith (i.e. His (Allahs), Angels, His Holy Books, His Messengers, the Day of Resurrection and AlQadar (Divine Preordainments)), then fruitless is his work, and in the Hereafter he will be among the losers.', 'This day, good things have been made lawful for you. The food of the people of the Book is lawful for you, and your food is lawful for them, and good women from among believers, and good women from among those who were given the Book before you, provided you give them their dowers, binding yourself in marriage, neither going for lust, nor having paramours. Whoever rejects Faith, his effort will go to waste and, in the Hereafter, he will be among the losers.'),
(675, 5, 6, 2, 6, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اِذَا قُمۡتُمۡ  اِلَی الصَّلٰوۃِ فَاغۡسِلُوۡا وُجُوۡہَکُمۡ وَ اَیۡدِیَکُمۡ  اِلَی الۡمَرَافِقِ وَ امۡسَحُوۡا بِرُءُوۡسِکُمۡ وَ اَرۡجُلَکُمۡ  اِلَی الۡکَعۡبَیۡنِ ؕ وَ اِنۡ کُنۡتُمۡ جُنُبًا فَاطَّہَّرُوۡا ؕ وَ اِنۡ کُنۡتُمۡ مَّرۡضٰۤی اَوۡ عَلٰی سَفَرٍ  اَوۡ جَآءَ  اَحَدٌ مِّنۡکُمۡ  مِّنَ الۡغَآئِطِ اَوۡ لٰمَسۡتُمُ النِّسَآءَ  فَلَمۡ  تَجِدُوۡا مَآءً فَتَیَمَّمُوۡا صَعِیۡدًا طَیِّبًا فَامۡسَحُوۡا بِوُجُوۡہِکُمۡ وَ اَیۡدِیۡکُمۡ مِّنۡہُ ؕ مَا یُرِیۡدُ اللّٰہُ لِیَجۡعَلَ عَلَیۡکُمۡ مِّنۡ حَرَجٍ وَّ لٰکِنۡ یُّرِیۡدُ لِیُطَہِّرَکُمۡ وَ لِیُتِمَّ نِعۡمَتَہٗ عَلَیۡکُمۡ لَعَلَّکُمۡ تَشۡکُرُوۡنَ ﴿۶﴾', 'مومنو! جب تم نماز پڑھنے کا قصد کیا کرو تو اپنے منہ اور کہنیوں تک ہاتھ دھو لیا کرو اور سر کا مسحح کر لیا کرو۔ اور ٹخنوں تک پاؤں دھو لیا کرو اور اگر جنابت کی حالت میں ہو تو نہا کر پاک ہو جایا کرو۔ اور اگر بیمار ہو یا سفر میں ہو یا کوئی تم میں سے بیت الخلا سے ہو کر آیا ہو یا تم نے عورتوں سے مقاربت کی ہو پھر تمہیں پانی نہ مل سکے تو پاک مٹی لو اور اس سے منہ اور ہاتھوں کا مسح یعنی تیمم کر لو۔ اللہ تم پر کسی طرح کی تنگی نہیں کرنا چاہتا بلکہ یہ چاہتا ہے کہ تمہیں پاک کرے اور اپنی نعمتیں تم پر پوری کرے تا کہ تم شکر کرو۔', 'اے ایمان والو [۳۴] جب تم اٹھو [۳۵] نماز کو تو دھو لو اپنے منہ اور ہاتھ کہنیوں تک اور مل لو اپنے سر کو [۳۶] اور پاؤں ٹخنوں تک [۳۷] اور اگر تم کو جنابت ہو تو خوب طرح پاک ہو [۳۸] اور اگر تم بیمار ہو یا سفر میں یا کوئی تم میں آیا ہے جائے ضرور سے یا پاس گئے ہو عورتوں کے پھر نہ پاؤ تم پانی تو قصد کرو مٹی پاک کا اور مل لو اپنے منہ اور ہاتھ اس سے [۳۹] اللہ نہیں چاہتا کہ تم پر تنگی کرے [۴۰] لیکن چاہتا ہے کہ تم کو پاک کرے [۴۱] اور پورا کرے اپنا احسان تم پر تاکہ تم احسان مانو [۴۲]', 'O you who believe! When you intend to offer As-Salat (the prayer), wash your faces and your hands (forearms) up to the elbows, rub (by passing wet hands over) your heads, and (wash) your feet up to ankles. If you are in a state of Janaba (i.e. had a sexual discharge), purify yourself (bathe your whole body). But if you are ill or on a journey or any of you comes from answering the call of nature, or you have been in contact with women (i.e. sexual intercourse) and you find no water, then perform Tayammum with clean earth and rub therewith your faces and hands. Allah does not want to place you in difficulty, but He wants to purify you, and to complete His Favour on you that you may be thankful.', 'O you who believe, when you rise for Salāh, (prayer) wash your faces and your hands up to the elbows, and make MasH (wiping by hands) of your heads and (wash) your feet up to the ankles. If you are in a state of major impurity, cleanse yourselves well (by taking bath). If you are sick, or on a journey, or if one of you has come after relieving himself, or you have had sexual contact with women, and you find no water, then, go for some clean dust and wipe your faces and hands with it. Allah does not like to impose a problem on you; He, rather likes to cleanse you and to complete His favour upon you, so that you may be grateful.'),
(676, 5, 7, 2, 6, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ اذۡکُرُوۡا نِعۡمَۃَ اللّٰہِ عَلَیۡکُمۡ وَ مِیۡثَاقَہُ الَّذِیۡ وَاثَقَکُمۡ  بِہٖۤ ۙ اِذۡ  قُلۡتُمۡ سَمِعۡنَا وَ اَطَعۡنَا ۫ وَ اتَّقُوا اللّٰہَ ؕ اِنَّ  اللّٰہَ عَلِیۡمٌۢ  بِذَاتِ الصُّدُوۡرِ ﴿۷﴾', 'اور اللہ نے جو تم پر احسان کئے ہیں ان کو یاد رکھو اور اس عہد کو بھی جس کا تم سے قول لیا تھا یعنی جب تم نے کہا تھا کہ ہم نے اللہ کا حکم سن لیا اور قبول کیا۔ اور اللہ سے ڈرو۔ کچھ شک نہیں کہ اللہ دلوں کی باتوں تک سے واقف ہے۔', 'اور یاد کرو احسان اللہ کا اپنے اوپر اور عہد اس کا جو تم سے ٹھہرایا تھا جب تم نے کہا تھا کہ ہم نے سنا اور مانا [۴۳] اور ڈرتے رہو اللہ سے اللہ خوب جانتا ہے دلوں کی بات [۴۴]', 'And remember Allahs Favour upon you and His Covenant with which He bound you when you said: \"We hear and we obey.\" And fear Allah. Verily, Allah is AllKnower of the secrets of (your) breasts.', 'Remember Allah’s favour upon you and His covenant that He has taken from you when you said, “We have listened and obeyed.” Fear Allah. Allah is all-Aware of what lies in the hearts.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(677, 5, 8, 2, 6, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا کُوۡنُوۡا قَوّٰمِیۡنَ لِلّٰہِ شُہَدَآءَ  بِالۡقِسۡطِ ۫ وَ لَا  یَجۡرِمَنَّکُمۡ شَنَاٰنُ قَوۡمٍ عَلٰۤی اَلَّا تَعۡدِلُوۡا ؕ اِعۡدِلُوۡا ۟ ہُوَ  اَقۡرَبُ لِلتَّقۡوٰی ۫ وَ اتَّقُوا اللّٰہَ ؕ اِنَّ  اللّٰہَ  خَبِیۡرٌۢ  بِمَا تَعۡمَلُوۡنَ ﴿۸﴾', 'اے ایمان والو! اللہ کے لئے انصاف کی گواہی دینے کے لئے کھڑے ہو جایا کرو۔ اور کچھ لوگوں کی دشمنی تم کو اس بات پر آمادہ نہ کر دے کہ انصاف ہی نہ کرو۔ انصاف کیا کرو کہ یہی پرہیزگاری کی بات ہے اور اللہ سے ڈرتے رہو۔ کچھ شک نہیں کہ اللہ تمہارے سب اعمال سے خبردار ہے۔', 'اے ایمان والو کھڑے ہو جایا کرو اللہ کے واسطے گواہی دینے کو انصاف کی [۴۵] اور کسی قوم کی دشمنی کے باعث انصاف کو ہر گز نہ چھوڑو [۴۶] عدل کرو یہ بات زیادہ نزدیک ہے تقویٰ سے [۴۷] اور ڈرتے رہو اللہ سے اللہ کو خوب خبر ہے جو تم کرتے ہو [۴۸]', 'O you who believe! Stand out firmly for Allah and be just witnesses and let not the enmity and hatred of others make you avoid justice. Be just: that is nearer to piety, and fear Allah. Verily, Allah is WellAcquainted with what you do.', 'O you who believe, be steadfast for (obeying the commands of) Allah, (and) witnesses for justice. Malice against a people should not prompt you to avoid doing justice. Do justice. That is nearer to Taqwā. Fear Allah. Surely, Allah is All-Aware of what you do.'),
(678, 5, 9, 2, 6, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَعَدَ اللّٰہُ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ ۙ لَہُمۡ مَّغۡفِرَۃٌ وَّ اَجۡرٌ عَظِیۡمٌ ﴿۹﴾', 'جو لوگ ایمان لائے اور نیک کام کرتے رہے ان سے اللہ نے وعدہ فرمایا ہے کہ انکے لئے بخشش اور اجر عظیم ہے۔', 'وعدہ کیا اللہ نے ایمان والوں سے اور جو نیک عمل کرتے ہیں کہ انکے واسطے بخشش اور بڑا ثواب ہے [۴۹]', 'Allah has promised those who believe (in the Oneness of Allah - Islamic Monotheism) and do deeds of righteousness, that for them there is forgiveness and a great reward (i.e. Paradise).', 'Allah has promised those who believe and do good deeds: For them there is forgiveness and a great reward.'),
(679, 5, 10, 2, 6, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ الَّذِیۡنَ کَفَرُوۡا وَ کَذَّبُوۡا بِاٰیٰتِنَاۤ  اُولٰٓئِکَ  اَصۡحٰبُ  الۡجَحِیۡمِ ﴿۱۰﴾', 'اور جنہوں نے کفر کیا اور ہماری آیتوں کو جھٹلایا وہ جہنمی ہیں۔', 'اور جن لوگوں نے کفر کیا اور جھٹلائیں ہماری آیتیں وہ ہیں دوزخ والے [۵۰]', 'They who disbelieve and deny our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) are those who will be the dwellers of the Hellfire.', 'Those who disbelieve and deny Our signs - they are the people of the Fire.'),
(680, 5, 11, 2, 6, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوا اذۡکُرُوۡا نِعۡمَتَ اللّٰہِ عَلَیۡکُمۡ اِذۡ ہَمَّ قَوۡمٌ اَنۡ یَّبۡسُطُوۡۤا اِلَیۡکُمۡ  اَیۡدِیَہُمۡ فَکَفَّ اَیۡدِیَہُمۡ عَنۡکُمۡ ۚ وَ اتَّقُوا اللّٰہَ ؕ وَ عَلَی اللّٰہِ فَلۡیَتَوَکَّلِ الۡمُؤۡمِنُوۡنَ ﴿٪۱۱﴾', 'اے ایمان والو! اللہ نے جو تم پر احسان کیا ہے اسکو یاد کرو۔ جب کچھ لوگوں نے ارادہ کیا کہ تم پر دست درازی کریں تو اس نے ان کے ہاتھ تم سے روک دیئے اور اللہ سے ڈرتے رہو۔ اور مومنوں کو تو اللہ ہی پر بھروسہ رکھنا چاہیے۔', 'اے ایمان والو یاد رکھو احسان اللہ کا اپنے اوپر جب قصد کیا لوگوں نے کہ تم پر ہاتھ چلاویں پھر روک دیے تم سے ان کے ہاتھ اور ڈرتے رہو اللہ سے اور اللہ ہی پر چاہئے بھروسہ ایمان والوں کو [۵۱]', 'O you who believe! Remember the Favour of Allah unto you when some people desired (made a plan) to stretch out their hands against you, but (Allah) withheld their hands from you. So fear Allah. And in Allah let believers put their trust.', 'O you who believe, remember Allah’s favour upon you, when some people planned to lay their hands on you, and He kept their hands away from you. Fear Allah; and in Allah the believers should place their trust.'),
(681, 5, 12, 3, 7, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ لَقَدۡ اَخَذَ اللّٰہُ مِیۡثَاقَ بَنِیۡۤ  اِسۡرَآءِیۡلَ ۚ وَ بَعَثۡنَا مِنۡہُمُ اثۡنَیۡ عَشَرَ نَقِیۡبًا ؕ وَ قَالَ اللّٰہُ  اِنِّیۡ مَعَکُمۡ ؕ لَئِنۡ اَقَمۡتُمُ الصَّلٰوۃَ وَ اٰتَیۡتُمُ الزَّکٰوۃَ  وَ اٰمَنۡتُمۡ بِرُسُلِیۡ وَ عَزَّرۡتُمُوۡہُمۡ وَ اَقۡرَضۡتُمُ اللّٰہَ قَرۡضًا حَسَنًا لَّاُکَفِّرَنَّ عَنۡکُمۡ سَیِّاٰتِکُمۡ وَ لَاُدۡخِلَنَّکُمۡ جَنّٰتٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ ۚ فَمَنۡ کَفَرَ بَعۡدَ ذٰلِکَ مِنۡکُمۡ  فَقَدۡ ضَلَّ سَوَآءَ  السَّبِیۡلِ ﴿۱۲﴾', 'اور اللہ نے بنی اسرائیل سے اقرار لیا تھا اور ان میں ہم نے بارہ سردار مقرر کئے تھے۔ اور اللہ نے فرمایا کہ میں تمہارے ساتھ ہوں۔ اگر تم نماز پڑھتے اور زکوٰۃ دیتے رہو گے اور میرے پیغمبروں پر ایمان رکھو گے اور ان کی مدد کرتے رہو گے اور اللہ کو قرض حسن دو گے تو میں تم سے تمہارے گناہ دور کر دوں گا اور تم کو بہشتوں میں داخل کروں گا جن کے نیچے نہریں بہ رہی ہیں۔ پھر جس نے اسکے بعد تم میں سے کفر کیا تو وہ سیدھے رستے سے بھٹک گیا۔', 'اور لے چکا ہے اللہ عہد بنی اسرائیل سے [۵۲] اور مقرر کئے ہم نے ان میں بارہ سردار [۵۳] اور کہا اللہ نے میں تمہارے ساتھ ہو [۵۴] اگر تم قائم رکھو گے نماز اور دیتے رہو گے زکوٰۃ اور یقین لاؤ گے میرے رسولوں پر اور مدد کرو گے ان کی [۵۵] اور قرض دو گے اللہ کو [۵۶] اچھی طرح کا قرض [۵۷] تو البتہ دور کروں گا میں تم سے گناہ تمہارے اور داخل کروں گا تم کو باغوں میں کہ جن کے نیچے بہتی ہیں نہریں [۵۸] پھر جو کوئی کافر رہا تم میں سے اس کے بعد تو وہ بیشک گمراہ ہوا سیدھے راستہ سے [۵۹]', 'Indeed Allah took the covenant from the Children of Israel (Jews), and We appointed twelve leaders among them. And Allah said: \"I am with you if you perform As-Salat (Iqamat-as-Salat) and give Zakat and believe in My Messengers; honour and assist them, and lend to Allah a good loan. Verily, I will remit your sins and admit you to Gardens under which rivers flow (in Paradise). But if any of you after this, disbelieved, he has indeed gone astray from the Straight Path.\"', 'Allah has made the Children of Israel take a pledge. We appointed twelve chiefs from among them. Allah said, “I am surely with you. If you establish Salāh, and pay Zakāh, and believe in My Messengers, and hold them in reverence, and advance to Allah a goodly loan, I shall certainly write off your evil deeds, and I shall certainly admit you into Gardens beneath which rivers flow. So, whoever from you disbelieves after that has lost the straight path.”'),
(682, 5, 13, 3, 7, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'فَبِمَا نَقۡضِہِمۡ مِّیۡثَاقَہُمۡ لَعَنّٰہُمۡ وَ جَعَلۡنَا قُلُوۡبَہُمۡ قٰسِیَۃً ۚ یُحَرِّفُوۡنَ الۡکَلِمَ عَنۡ مَّوَاضِعِہٖ ۙ وَ نَسُوۡا حَظًّا مِّمَّا ذُکِّرُوۡا بِہٖ ۚ وَ لَا تَزَالُ تَطَّلِعُ عَلٰی خَآئِنَۃٍ مِّنۡہُمۡ اِلَّا قَلِیۡلًا مِّنۡہُمۡ فَاعۡفُ عَنۡہُمۡ وَ اصۡفَحۡ ؕ اِنَّ اللّٰہَ یُحِبُّ الۡمُحۡسِنِیۡنَ ﴿۱۳﴾', 'پس ان لوگوں کے عہد توڑ دینے کے سبب ہم نے ان پر لعنت کی اور ان کے دلوں کو سخت کر دیا۔ یہ لوگ کلمات کتاب کو اپنے مقامات سے بدل دیتے ہیں۔ اور جن باتوں کی ان کو نصیحت کی گئ تھی ان کا بھی ایک حصہ فراموش کر بیٹھے اور تھوڑے آدمیوں کے سوا ہمیشہ تم ان کی ایک نہ ایک خیانت کی خبر پاتے رہتے ہو۔  سو انہیں معاف رکھو اور ان سے درگذر کرو اللہ احسان کرنے والوں کو دوست رکھتا ہے۔', 'سو ان کے عہد توڑنے پر ہم نے ان پر لعنت کی [۶۰] اور کر دیا ہم نے ان کے دلوں کو سخت پھیرتے ہیں کلام کو اسکے ٹھکانے سے [۶۱] اور بھول گئے نفع اٹھانا اس نصیحت سے جو انکو کی گئ تھی [۶۲] اور ہمیشہ تو مطلع ہوتا رہتا ہے ان کی کسی دغا پر [۶۳] مگر تھوڑے لوگ ان میں سے [۶۴] سو معاف کر اور درگذر کر ان سے اللہ دوست رکھتا ہے احسان کرنے والوں کو [۶۵]', 'So because of their breach of their covenant, We cursed them, and made their hearts grow hard. They change the words from their (right) places and have abandoned a good part of the Message that was sent to them. And you will not cease to discover deceit in them, except a few of them. But forgive them, and overlook (their misdeeds). Verily, Allah loves AlMuhsinoon (gooddoers - see V.2:112).', 'So, because they broke their pledge, We cursed them and made their hearts hardened. They change words from their places, and they have overlooked a good deal of the Advice they were given. Every now and then you come across a certain treachery from all of them, except a few. So, forgive them and forego. Indeed, Allah loves those who are good in deeds.'),
(683, 5, 14, 3, 7, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ مِنَ الَّذِیۡنَ قَالُوۡۤا اِنَّا نَصٰرٰۤی اَخَذۡنَا مِیۡثَاقَہُمۡ فَنَسُوۡا حَظًّا مِّمَّا ذُکِّرُوۡا بِہٖ ۪ فَاَغۡرَیۡنَا بَیۡنَہُمُ الۡعَدَاوَۃَ وَ الۡبَغۡضَآءَ اِلٰی یَوۡمِ الۡقِیٰمَۃِ ؕ وَ سَوۡفَ یُنَبِّئُہُمُ اللّٰہُ  بِمَا  کَانُوۡا یَصۡنَعُوۡنَ ﴿۱۴﴾', 'اور جو لوگ کہتے ہیں کہ ہم نصارٰی ہیں ہم نے ان سے بھی عہد لیا تھا مگر انہوں نے بھی اس نصیحت کا جو انکو کی گئ تھی ایک حصہ فراموش کر دیا تو ہم نے ان میں قیامت تک کے لئے دشمنی اور کینہ ڈال دیا۔ اور جو کچھ وہ کرتے رہے اللہ عنقریب انکو اس سے آگاہ کر دے گا۔', 'اور وہ جو کہتے ہیں اپنے کو نصاریٰ [۶۶] ان سے بھی لیا تھا ہم نے عہد ان کا پھر بھول گئے نفعع اٹھانا اس نصیحت سے جو انکو کی گئ تھی [۶۷] پھر ہم نے لگا دی آپس میں انکی دشمنی اور کینہ [۶۸] قیامت کے دن تک [۶۹] اور آخر جتا دے گا ان کو اللہ جو کچھ کرتے تھے [۷۰]', 'And from those who call themselves Christians, We took their covenant, but they have abandoned a good part of the Message that was sent to them. So We planted amongst them enmity and hatred till the Day of Resurrection (when they discarded Allahs Book, disobeyed Allahs Messengers and His Orders and transgressed beyond bounds in Allahs disobedience), and Allah will inform them of what they used to do.', 'And from those who say, “We are Christians,” We took a pledge. So, they have overlooked a good deal of the Advice they were given. So, We had them stuck with enmity and malice among them right through the Day of Doom, and (then) Allah will tell them what they were doing.'),
(684, 5, 15, 3, 7, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یٰۤاَہۡلَ الۡکِتٰبِ قَدۡ جَآءَکُمۡ  رَسُوۡلُنَا یُبَیِّنُ لَکُمۡ کَثِیۡرًا مِّمَّا کُنۡتُمۡ تُخۡفُوۡنَ مِنَ الۡکِتٰبِ وَ یَعۡفُوۡا عَنۡ کَثِیۡرٍ ۬ؕ قَدۡ جَآءَکُمۡ  مِّنَ اللّٰہِ  نُوۡرٌ وَّ کِتٰبٌ مُّبِیۡنٌ ﴿ۙ۱۵﴾', 'اے اہل کتاب تمہارے پاس ہمارے پیغمبر آخرالزماں آ گئے ہیں کہ جو کچھ تم کتاب الہٰی میں سے چھپاتے تھے وہ اس میں سے بہت کچھ تمہیں کھول کھول کر بتا دیتے ہیں۔ اور تمہارے بہت سے قصور معاف کر دیتے ہیں۔ بیشک تمہارے پاس اللہ کی طرف سے نور اور روشن کتاب آ چکی ہے۔', 'اے کتاب والو تحقیق آیا ہے تمہارے پاس رسول ہمارا ظاہر کرتا ہے تم پر بہت سی چیزیں جن کو تم چھپاتے تھے کتاب میں سے اور درگزر کرتا ہے بہت چیزوں سے [۷۱] بیشک تمہارے پاس آئی ہے اللہ کی طرف سے روشنی اور کتاب ظاہر کرنے والی', 'O people of the Scripture (Jews and Christians)! Now has come to you Our Messenger (Muhammad SAW) explaining to you much of that which you used to hide from the Scripture and passing over (i.e. leaving out without explaining) much. Indeed, there has come to you from Allah a light (Prophet Muhammad SAW ) and a plain Book (this Quran).', 'O people of the Book, there has come to you Our Messenger disclosing to you much of what you have been concealing of the Book, while He overlooks much. There has come to you, from Allah, a Light and a clear Book;'),
(685, 5, 16, 3, 7, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یَّہۡدِیۡ بِہِ اللّٰہُ مَنِ اتَّبَعَ رِضۡوَانَہٗ سُبُلَ السَّلٰمِ  وَ یُخۡرِجُہُمۡ مِّنَ الظُّلُمٰتِ اِلَی النُّوۡرِ بِاِذۡنِہٖ وَ یَہۡدِیۡہِمۡ  اِلٰی  صِرَاطٍ مُّسۡتَقِیۡمٍ ﴿۱۶﴾', 'جس سے اللہ اپنی رضا پر چلنے والوں کو سلامتی کے رستے دکھاتا ہے اور اپنے حکم سے انہیں اندھیرے سے نکال کر روشنی کی طرف لے جاتا اور ان کو سیدھے رستے پر چلاتا ہے۔', 'جس سے اللہ ہدایت کرتا ہے اس کو جو تابع ہوا اسکی رضا کا سلامتی کی راہیں اور ان کو نکالتا ہے اندھیروں سے روشنی میں اپنے حکم سے اور ان کو چلاتا ہے سیدھی راہ [۷۲]', 'Wherewith Allah guides all those who seek His Good Pleasure to ways of peace, and He brings them out of darkness by His Will unto light and guides them to a Straight Way (Islamic Monotheism).', 'with it Allah guides those who follow His pleasure to the pathways of peace, and brings them out, by His will, from the depths of darkness into the light, and guides them to a straight path.'),
(686, 5, 17, 3, 7, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'لَقَدۡ کَفَرَ الَّذِیۡنَ قَالُوۡۤا اِنَّ اللّٰہَ ہُوَ الۡمَسِیۡحُ ابۡنُ مَرۡیَمَ ؕ قُلۡ  فَمَنۡ یَّمۡلِکُ مِنَ اللّٰہِ شَیۡئًا اِنۡ اَرَادَ  اَنۡ  یُّہۡلِکَ الۡمَسِیۡحَ ابۡنَ مَرۡیَمَ وَ اُمَّہٗ وَ مَنۡ فِی الۡاَرۡضِ جَمِیۡعًا ؕ وَ لِلّٰہِ مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ مَا بَیۡنَہُمَا ؕ یَخۡلُقُ مَا یَشَآءُ ؕ وَ اللّٰہُ  عَلٰی  کُلِّ  شَیۡءٍ  قَدِیۡرٌ ﴿۱۷﴾', 'جو لوگ کہتے ہیں کہ اللہ جو ہے وہی مسیح ابن مریم ہے وہ بیشک کافر ہیں۔ ان سے کہدو کہ اگر اللہ عیسٰی ابن مریم کو اور ان کی والدہ کو اور جتنے لوگ زمین میں ہیں سب کو ہلاک کرنا چاہے تو اسکے آگے کس کی پیش چل سکتی ہے؟ اور آسمان اور زمین اور جو کچھ ان دونوں کے درمیان ہے سب پر اللہ ہی کی حکومت ہے وہ جو چاہتا ہے پیدا کرتا ہے اور اللہ ہر چیز پر پورا قادر ہے۔', 'بیشک کافر ہوئے جنہوں نے کہا کہ اللہ تو وہی مسیح ہے مریم کا بیٹا [۷۳] تو کہہ دے پھر کس کا بس چل سکتا ہے اللہ کے آگے اگر وہ چاہے کہ ہلاک کرے مسیح مریم کے بیٹے کو اور اس کی ماں کو اور جتنے لوگ ہیں زمین میں سب کو [۷۴] اور اللہ ہی کے واسطے ہے سلطنت آسمانوں اور زمین کی اور جو کچھ درمیان ان دونوں کے ہے پیدا کرتا ہے جو چاہے [۷۵] اور اللہ ہر چیز پر قادر ہے [۷۶]', 'Surely, in disbelief are they who say that Allah is the Messiah, son of Maryam (Mary). Say (O Muhammad SAW): \"Who then has the least power against Allah, if He were to destroy the Messiah, son of Maryam (Mary), his mother, and all those who are on the earth together?\" And to Allah belongs the dominion of the heavens and the earth, and all that is between them. He creates what He wills. And Allah is Able to do all things.', 'Certainly, infidels are those who say, “God is the MasīH, son of Maryam (Jesus son of Mary).” Say, “Who then has the power to do anything against Allah, if He wills to eliminate the MasīH son of Maryam and his mother and all those on earth?” Unto Allah belongs the kingdom of the heavens and the earth and what lies between them. He creates what He wills. Allah is powerful over everything.'),
(687, 5, 18, 3, 7, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ قَالَتِ الۡیَہُوۡدُ  وَ النَّصٰرٰی  نَحۡنُ اَبۡنٰٓؤُا اللّٰہِ وَ اَحِبَّآؤُہٗ ؕ قُلۡ فَلِمَ یُعَذِّبُکُمۡ  بِذُنُوۡبِکُمۡ ؕ بَلۡ  اَنۡتُمۡ  بَشَرٌ مِّمَّنۡ خَلَقَ ؕ یَغۡفِرُ لِمَنۡ یَّشَآءُ وَ یُعَذِّبُ مَنۡ یَّشَآءُ ؕ وَ لِلّٰہِ مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ مَا بَیۡنَہُمَا ۫ وَ اِلَیۡہِ الۡمَصِیۡرُ ﴿۱۸﴾', 'اور یہود اور نصارٰی کہتے ہیں کہ ہم اللہ کے بیٹے اور اسکے پیارے ہیں۔ کہو کہ پھر وہ تمہارے گناہوں کے سبب تمہیں عذاب کیوں دیتا ہے نہیں بلکہ تم اسکی مخلوقات میں دوسروں کی طرح کے انسان ہو۔ وہ جسے چاہے بخشے اور جسے چاہے عذاب دے۔ اور آسمان اور زمین اور جو کچھ ان دونوں کے درمیان ہے سب پر اللہ ہی کی حکومت ہے اور سب کو اسی کی طرف لوٹ کر جانا ہے۔', 'اور کہتے ہیں یہود اور نصاریٰ ہم بیٹے ہیں اللہ کے اور اسکے پیارے [۷۷] تو کہہ پھر کیوں عذاب کرتا ہے تم کو تمہارے گناہوں پر [۷۸] کوئی نہیں بلکہ تم بھی ایک آدمی ہو اسکی مخلوق میں [۷۹] بخشے جس کو چاہے اور عذاب کرے جس کو چاہے [۸۰] اور اللہ ہی کے لئے ہے سلطنت آسمان اور زمین کی اور جو کچھ دونوں کے بیچ میں ہے اور اسکی کی طرف لوٹ کر جانا ہے [۸۱]', 'And (both) the Jews and the Christians say: \"We are the children of Allah and His loved ones.\" Say: \"Why then does He punish you for your sins?\" Nay, you are but human beings, of those He has created, He forgives whom He wills and He punishes whom He wills. And to Allah belongs the dominion of the heavens and the earth and all that is between them, and to Him is the return (of all).', 'The Jews and the Christians say, “We are the sons of Allah and His favourites.” Say, “Why then would He punish you for your sins? In fact, you are just human, among those He has created. He forgives whom He wills and punishes whom He wills.” Unto Allah belongs the kingdom of the heavens and the earth and what lies between them, and unto Him is the return.'),
(688, 5, 19, 3, 7, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یٰۤاَہۡلَ الۡکِتٰبِ قَدۡ جَآءَکُمۡ  رَسُوۡلُنَا یُبَیِّنُ لَکُمۡ عَلٰی  فَتۡرَۃٍ  مِّنَ الرُّسُلِ اَنۡ تَقُوۡلُوۡا مَا جَآءَنَا مِنۡۢ بَشِیۡرٍ وَّ لَا نَذِیۡرٍ ۫ فَقَدۡ جَآءَکُمۡ بَشِیۡرٌ وَّ نَذِیۡرٌ ؕ وَ اللّٰہُ  عَلٰی  کُلِّ  شَیۡءٍ  قَدِیۡرٌ ﴿٪۱۹﴾', 'اے اہل کتاب پیغمبروں کے آنے کا سلسلہ جو ایک عرصے تک منقطع رہا تو اب تمہارے پاس ہمارے پیغمبر آ گئے ہیں جو تم سے ہمارے احکام بیان کرتے ہیں۔ تاکہ تم یہ نہ کہو کہ ہمارے پاس کوئی خوشخبری یا ڈر سنانے والا نہیں آیا۔ سو اب تمہارے پاس خوشخبری اور ڈر سنانے والے آ گئے ہیں اور اللہ ہر چیز پر قادر ہے۔', 'اے کتاب والو آیا ہے تمہارے پاس رسول ہمارا کھولتا ہے تم پر [۸۲] رسولوں کے انقطاع کے بعد کبھی تم کہنے لگو کہ ہمارے پاس نہ آیا کوئی خوشی یا ڈر سنانے والا سو آ چکا تمہارے پاس خوشی اور ڈر سنانے والا [۸۳] اور اللہ ہر چیز پر قادر ہے [۸۴]', 'O people of the Scripture (Jews and Christians)! Now has come to you Our Messenger (Muhammad SAW) making (things) clear unto you, after a break in (the series of) Messengers, lest you say: \"There came unto us no bringer of glad tidings and no warner.\" But now has come unto you a bringer of glad tidings and a warner. And Allah is Able to do all things.', 'O people of the Book, Our Messenger has come to you making things clear to you after a gap between Messengers, lest you were to say, “There has not come to us a bearer of good news, and a warner.” So, now there has come to you a bearer of good news, and a warner. Allah is powerful over everything.'),
(689, 5, 20, 4, 8, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ  اِذۡ قَالَ مُوۡسٰی لِقَوۡمِہٖ یٰقَوۡمِ اذۡکُرُوۡا نِعۡمَۃَ اللّٰہِ عَلَیۡکُمۡ اِذۡ جَعَلَ فِیۡکُمۡ اَنۡۢبِیَآءَ وَ جَعَلَکُمۡ مُّلُوۡکًا ٭ۖ وَّ اٰتٰىکُمۡ مَّا لَمۡ یُؤۡتِ اَحَدًا مِّنَ الۡعٰلَمِیۡنَ  ﴿۲۰﴾', 'اور جب موسیٰ نے اپنی قوم سے کہا کہ بھائیو تم پر اللہ نے جو احسان کئے ہیں ان کو یاد کرو کہ اس نے تم میں پیغمبر پیدا کئے اور تمہیں بادشاہ بنایا اور تم کو اتنا کچھ عنایت کیا کہ اہل عالم میں سے کسی کو نہیں دیا۔', 'اور جب کہا موسٰی نے اپنی قوم کو اے قوم یاد کرو احسان اللہ کا اپنے اوپر [۸۵] جب پیدا کئے تم میں نبی [۸۶] اور کر دیا تم کو بادشاہ [۸۷] اور دیا تم کو جو نہیں دیا تھا کسی کو جہان میں [۸۸]', 'And (remember) when Moosa (Moses) said to his people: \"O my people! Remember the Favour of Allah to you, when He made Prophets among you, made you kings, and gave you what He had not given to any other among the Alameen (mankind and jinns, in the past).\"', '(Recall) when Mūsā said to his people, “O my people, remember the blessing of Allah upon you when He made prophets from among you, made you kings and gave you what He did not give to anyone in the worlds.'),
(690, 5, 21, 4, 8, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یٰقَوۡمِ ادۡخُلُوا الۡاَرۡضَ الۡمُقَدَّسَۃَ الَّتِیۡ  کَتَبَ اللّٰہُ لَکُمۡ وَ لَا تَرۡتَدُّوۡا عَلٰۤی  اَدۡبَارِکُمۡ فَتَنۡقَلِبُوۡا خٰسِرِیۡنَ ﴿۲۱﴾', 'اے بھائیو تم ارض مقدس یعنی ملک شام میں جسے اللہ نے تمہارے لئے لکھ رکھا ہے داخل ہو چلو اور دیکھنا مقابلے کے وقت پیٹھ نہ پھیر دینا ورنہ نقصان میں پڑ جاؤ گے۔', 'اے قوم داخل ہو زمین پاک میں جو مقرر کر دی ہے اللہ نے تمہارے واسطے [۸۹] اور نہ لوٹو اپنی پیٹھ کی طرف پھر جا پڑو گے نقصان میں [۹۰]', '\"O my people! Enter the holy land (Palestine) which Allah has assigned to you, and turn not back (in flight) for then you will be returned as losers.\" \n \n \n 22. They said: \"O Moosa (Moses)! In it (this holy', 'O my people, enter the Holy Land which Allah has destined for you, and do not turn back, lest you should turn losers.”'),
(691, 5, 22, 4, 8, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'قَالُوۡا یٰمُوۡسٰۤی اِنَّ فِیۡہَا قَوۡمًا جَبَّارِیۡنَ ٭ۖ وَ اِنَّا لَنۡ نَّدۡخُلَہَا حَتّٰی یَخۡرُجُوۡا مِنۡہَا ۚ فَاِنۡ  یَّخۡرُجُوۡا مِنۡہَا فَاِنَّا دٰخِلُوۡنَ ﴿۲۲﴾', 'وہ کہنے لگے کہ موسٰی وہاں تو بڑے زبردست لوگ رہتے ہیں۔ اور جب تک وہ اس سرزمین سے نکل نہ جائیں ہم وہاں جا نہیں سکتے ہاں اگر وہ وہاں سے نکل جائیں تو ہم جا داخل ہوں گے۔', 'بولے اے موسٰی وہاں ایک قوم ہے زبردست [۹۱] اور ہم ہر گز وہاں نہ جاویں گے یہاں تک کہ وہ نکل جاویں اس میں سے پھر اگر وہ نکل جاویں گے اس میں سےتو ہم ضرور داخل ہوں گے [۹۲]', 'They said: \"O Moosa (Moses)! In it (this holy land) are a people of great strength, and we shall never enter it, till they leave it; when they leave, then we will enter.\"', 'They said, “O Mūsā, there is a nation of tyrants over there, and we shall never enter it until they get out of it. If they do get out of it, we are ready to go in.”'),
(692, 5, 23, 4, 8, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'قَالَ رَجُلٰنِ مِنَ الَّذِیۡنَ یَخَافُوۡنَ اَنۡعَمَ اللّٰہُ  عَلَیۡہِمَا ادۡخُلُوۡا عَلَیۡہِمُ  الۡبَابَ ۚ فَاِذَا دَخَلۡتُمُوۡہُ  فَاِنَّکُمۡ غٰلِبُوۡنَ ۬ۚ وَ عَلَی اللّٰہِ  فَتَوَکَّلُوۡۤا اِنۡ کُنۡتُمۡ  مُّؤۡمِنِیۡنَ ﴿۲۳﴾', 'جو لوگ اللہ سے ڈرتے تھے ان میں سے دو شخص جن پر اللہ کی عنایت تھی کہنے لگے کہ ان لوگوں پر دروازے کے رستے سے حملہ کر دو۔ پھرجب تم دروازے میں داخل ہو گئے تو فتح تمہاری ہے۔ اور اللہ ہی پر بھروسہ رکھو اگر تم واقعی ایمان والے ہو۔', 'کہا دو مردوں نے اللہ سے ڈرنے والوں میں سے کہ خدا کی نوازش تھی ان دو پر [۹۳] گھس جاؤ ان پرحملہ کر کے دروازہ میں پھر جب تم اس میں گھس جاؤ گے تو تم ہی غالب ہو گے [۹۴] اور اللہ پر بھروسہ کرو اگر یقین رکھتے ہو [۹۵]', 'Two men of those who feared (Allah and) on whom Allah had bestowed His Grace (they were íæÔÚ æ ßÇáÈ Yoosha (Joshua) and Kalab (Caleb)) said: \"Assault them through the gate, for when you are in, victory will be yours, and put your trust in Allah if you are believers indeed.\"', 'Said two men from among the God-fearing, on whom Allah had bestowed His favour, “Enter the gate (charging) upon them. Once you have entered it, you will be the ones who will prevail. In Allah you must place your trust, if you are believers.”'),
(693, 5, 24, 4, 8, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'قَالُوۡا یٰمُوۡسٰۤی اِنَّا لَنۡ  نَّدۡخُلَہَاۤ  اَبَدًا مَّا دَامُوۡا فِیۡہَا فَاذۡہَبۡ اَنۡتَ وَ رَبُّکَ فَقَاتِلَاۤ  اِنَّا ہٰہُنَا قٰعِدُوۡنَ ﴿۲۴﴾', 'وہ بولے کہ موسٰی جب تک وہ لوگ وہاں ہیں ہم کبھی وہاں نہیں جانے کے اگر لڑنا ہی ضرور ہے تو تم اور تمہارا رب دونوں جاؤ اور لڑو۔ ہم تو یہیں بیٹھے رہیں گے۔', 'بولے اے موسٰی ہم ہرگز نہ جاویں گے ساری عمر جب تک وہ رہیں گے اس میں سو تو جا اور تیرا رب اور تم دونوں لڑو ہم تو یہیں بیٹھے ہیں [۹۶]', 'They said: \"O Moosa (Moses)! We shall never enter it as long as they are there. So go you and your Lord and fight you two, we are sitting right here.\"', 'They said, “O Mūsā, we shall never enter it, in any case, so long as they are there. So go, you and your Lord, and fight. As for us, we are sitting right here.”'),
(694, 5, 25, 4, 8, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'قَالَ رَبِّ اِنِّیۡ  لَاۤ  اَمۡلِکُ اِلَّا نَفۡسِیۡ وَ اَخِیۡ فَافۡرُقۡ بَیۡنَنَا وَ بَیۡنَ الۡقَوۡمِ الۡفٰسِقِیۡنَ ﴿۲۵﴾', 'موسٰی نے اللہ سے التجا کی کہ پروردگار میں اپنے اور اپنے بھائی کے سوا اور کسی پر اختیار نہیں رکھتا۔ سو تو ہم میں اور ان نافرمان لوگوں میں جدائی کردے۔', 'بولا اے رب میرے میرے اختیار میں نہیں مگر میری جان اور میرا بھائی [۹۷] سو جدائی کر دے تو ہم میں اور اس نافرمان قوم میں [۹۸]', 'He (Moosa (Moses)) said: \"O my Lord! I have power only over myself and my brother, so separate us from the people who are the Fasiqoon (rebellious and disobedient to Allah)!\"', 'He said, “O my Lord, I have no control except over myself and my brother. So, make a distinction between us and the sinning people.”'),
(695, 5, 26, 4, 8, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'قَالَ فَاِنَّہَا مُحَرَّمَۃٌ عَلَیۡہِمۡ اَرۡبَعِیۡنَ سَنَۃً ۚ یَتِیۡہُوۡنَ فِی الۡاَرۡضِ ؕ فَلَا تَاۡسَ عَلَی الۡقَوۡمِ الۡفٰسِقِیۡنَ ﴿٪۲۶﴾', 'اللہ نے فرمایا کہ وہ ملک ان پر چالیس برس تک کیلئے حرام کر دیا گیا کہ وہاں جانے نہ پائیں گے یہ اسی علاقے میں جہاں اب ہیں سرگرداں پھرتے رہیں گے تو ان نافرمان لوگوں کے حال پر افسوس نہ کرو۔', 'فرمایا تحقیق وہ زمین حرام کی گئ ہے ان پر چالیس برس سر مارتے پھریں گے ملک میں سو تو افسوس نہ کر نافرمان لوگوں پر', '(Allah) said: \"Therefore it (this holy land) is forbidden to them for forty years; in distraction they will wander through the land. So be not sorrowful over the people who are the Fasiqoon (rebellious and disobedient to Allah).\"', 'He (Allah) said, “This (land) is prohibited to them for forty years. They shall be wandering around the earth. So, do not grieve for the sinning people.”'),
(696, 5, 27, 5, 9, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ اتۡلُ عَلَیۡہِمۡ  نَبَاَ ابۡنَیۡ اٰدَمَ  بِالۡحَقِّ ۘ اِذۡ قَرَّبَا قُرۡبَانًا فَتُقُبِّلَ مِنۡ اَحَدِہِمَا وَ لَمۡ یُتَقَبَّلۡ مِنَ الۡاٰخَرِ ؕ قَالَ لَاَقۡتُلَنَّکَ ؕ قَالَ  اِنَّمَا یَتَقَبَّلُ  اللّٰہُ مِنَ  الۡمُتَّقِیۡنَ ﴿۲۷﴾', 'اور اے نبی انکو آدم کے دو بیٹوں ہابیل اور قابیل کے حالات جو بالکل سچّے ہیں پڑھ کر سنا دو کہ جب ان دونوں نے بارگاہ الٰہی میں ایک ایک نیاز پیش کی تو ایک کی نیاز تو قبول ہو گئ اور دوسرے کی قبول نہ ہوئی اب قابیل ہابیل سے کہنے لگا کہ میں تجھے قتل کر دوں گا اس نے کہا کہ اللہ پرہیزگاروں ہی کی نیاز قبول فرمایا کرتا ہے۔', 'اور سنا ان کو حال واقعی آدم کے دو بیٹوں کا [۹۹] جب نیاز کی دونوں نے کچھ نیاز اور مقبول ہوئی ایک کی اور نہ مقبول ہوئی دوسرے کی [۱۰۰] کہا میں تجھ کو مار ڈالوں گا [۱۰۱] وہ بولا اللہ قبول کرتا ہے تو پرہیزگاروں سے [۱۰۲]', 'And (O Muhammad SAW) recite to them (the Jews) the story of the two sons of Adam (Habil (Abel) and Qabil (Cain)) in truth; when each offered a sacrifice (to Allah), it was accepted from the one but not from the other. The latter said to the former: \"I will surely kill you.\" The former said: \"Verily, Allah accepts only from those who are Al-Muttaqoon (the pious - see V.2:2).\"', 'And recite to them the story of the two sons of ’Ādam rightly: When both of them offered a sacrifice, it was accepted from one of them, and was not accepted from the other. He said, “I will kill you.” He said, “Allah accepts only from the God-fearing.'),
(697, 5, 28, 5, 9, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'لَئِنۡۢ بَسَطۡتَّ اِلَیَّ یَدَکَ لِتَقۡتُلَنِیۡ مَاۤ   اَنَا بِبَاسِطٍ یَّدِیَ اِلَیۡکَ لِاَقۡتُلَکَ ۚ اِنِّیۡۤ  اَخَافُ اللّٰہَ  رَبَّ  الۡعٰلَمِیۡنَ ﴿۲۸﴾', 'اگر تو مجھے قتل کرنے کے لئے مجھ پر ہاتھ چلائے گا تو میں تجھکو قتل کرنے کے لئے تجھ پر ہاتھ نہیں چلاؤں گا۔ مجھے تو اللہ رب العالمین سے ڈر لگتا ہے۔', 'اگر تو ہاتھ چلادے گا مجھ پر مارنے کو میں نہ ہاتھ چلاؤں گا تجھ پر مارنے کو [۱۰۳] میں ڈرتا ہوں اللہ سے جو پروردگار ہے سب جہان کا [۱۰۴]', '\"If you do stretch your hand against me to kill me, I shall never stretch my hand against you to kill you, for I fear Allah; the Lord of the Alameen (mankind, jinns, and all that exists).\"', 'If you stretch your hand towards me to kill me, I am not going to stretch my hand towards you to kill you. Indeed, I fear Allah, the Lord of the worlds.'),
(698, 5, 29, 5, 9, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'اِنِّیۡۤ  اُرِیۡدُ اَنۡ تَبُوۡٓاَ بِاِثۡمِیۡ وَ اِثۡمِکَ فَتَکُوۡنَ مِنۡ اَصۡحٰبِ النَّارِ ۚ وَ ذٰلِکَ جَزٰٓؤُا الظّٰلِمِیۡنَ ﴿ۚ۲۹﴾', 'میں چاہتا ہوں کہ تو میرے گناہ کو بھی سمیٹ لے اور اپنے گناہ کو بھی پھر تو اہل دوزخ میں سے ہو جائے اور ظالموں کی یہی سزا ہے۔', 'میں چاہتا ہوں کہ تو حاصل کرے میرا گناہ اور اپنا گناہ [۱۰۵] پھر ہو جاوے تو دوزخ والوں میں اور یہی ہے سزا ظالموں کی [۱۰۶]', '\"Verily, I intend to let you draw my sin on yourself as well as yours, then you will be one of the dwellers of the Fire, and that is the recompense of the Zalimoon (polytheists and wrongdoers).\"', 'I would rather let you bear my sin and your sin, and then become one of the people of the Fire. That is the punishment of the unjust.”'),
(699, 5, 30, 5, 9, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'فَطَوَّعَتۡ  لَہٗ نَفۡسُہٗ  قَتۡلَ اَخِیۡہِ فَقَتَلَہٗ  فَاَصۡبَحَ  مِنَ  الۡخٰسِرِیۡنَ ﴿۳۰﴾', 'آخر اسکے یعنی قابیل کے نفس نے اسکو اپنے بھائی کے قتل ہی کی ترغیب دی تو اس نے اسے قتل کر دیا پھر خسارہ پانے والوں میں ہو گیا۔', 'پھر اس کو راضی کیا اسکے نفس نے خون پر اپنے بھائی کے [۱۰۷] پھر اسکو مار ڈالا سو ہو گیا نقصان اٹھانے والوں میں [۱۰۸]', 'So the Nafs (self) of the other (latter one) encouraged him and made fairseeming to him the murder of his brother; he murdered him and became one of the losers.', 'His self, however, prompted him to kill his brother, so he killed him and became one of the losers.'),
(700, 5, 31, 5, 9, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'فَبَعَثَ اللّٰہُ غُرَابًا یَّبۡحَثُ فِی الۡاَرۡضِ لِیُرِیَہٗ کَیۡفَ یُوَارِیۡ سَوۡءَۃَ اَخِیۡہِ ؕ قَالَ یٰوَیۡلَتٰۤی اَعَجَزۡتُ اَنۡ  اَکُوۡنَ مِثۡلَ  ہٰذَا الۡغُرَابِ فَاُوَارِیَ سَوۡءَۃَ اَخِیۡ ۚ فَاَصۡبَحَ  مِنَ  النّٰدِمِیۡنَ ﴿ۚۛۙ۳۱﴾', 'اب اللہ نے ایک کوابھیجا جو زمین کریدنے لگا تاکہ اسے دکھائے کہ اپنے بھائی کی لاش کو کیسے چھپائے کہنے لگا ہائے کمبختی مجھ سے اتنا بھی نہ ہو سکا کہ اس کوے جیسا ہی ہوتا کہ اپنے بھائی کی لاش چھپا دیتا۔ پھر وہ پشیمان گیا۔', 'پھر بھیجا اللہ نے ایک کوا جو کریدتا تھا زمین کو  تاکہ اس کو دکھلا دے کس طرح چھپاتا ہے لاش اپنے بھائی کی بولا اے افسوس مجھ سے اتنا نہ ہو سکا کہ ہوں برابر اس کوے کی کہ میں چھپاؤں لاش اپنے بھائی کی [۱۰۹] پھر لگا پچتانے [۱۱۰]', 'Then Allah sent a crow who scratched the ground to show him to hide the dead body of his brother. He (the murderer) said: \"Woe to me! Am I not even able to be as this crow and to hide the dead body of my brother?\" Then he became one of those who regretted.', 'Then, Allah sent a crow that scratched the earth to show him how he should conceal the corpse of his brother. He said, “Alas! Was I not even able to be like this crow so that I could conceal the corpse of my brother? So, he stood regretful.'),
(701, 5, 32, 5, 9, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'مِنۡ اَجۡلِ ذٰلِکَ ۚۛؔ کَتَبۡنَا عَلٰی بَنِیۡۤ اِسۡرَآءِیۡلَ اَنَّہٗ مَنۡ قَتَلَ نَفۡسًۢا بِغَیۡرِ نَفۡسٍ اَوۡ فَسَادٍ فِی الۡاَرۡضِ فَکَاَنَّمَا قَتَلَ النَّاسَ جَمِیۡعًا ؕ وَ مَنۡ  اَحۡیَاہَا فَکَاَنَّمَاۤ اَحۡیَا النَّاسَ جَمِیۡعًا ؕ وَ لَقَدۡ جَآءَتۡہُمۡ رُسُلُنَا بِالۡبَیِّنٰتِ ۫ ثُمَّ  اِنَّ کَثِیۡرًا مِّنۡہُمۡ بَعۡدَ ذٰلِکَ فِی الۡاَرۡضِ لَمُسۡرِفُوۡنَ ﴿۳۲﴾', 'اس قتل کی وجہ سے ہم نے بنی اسرائیل کے ذمے یہ بات لکھ دی کہ جو شخص کسی کو ناحق قتل کرے گا یعنی بغیر اسکے کہ جان کا بدلہ لیا جائے یا ملک میں خرابی کرنے کی سزا دی جائے تو اس نے گویا تمام انسانوں کو قتل کیا اور جو ایک انسان کی جان بچا لے تو گویا اس نے سارے انسانوں کو زندگی دیدی۔ اور ان لوگوں کے پاس ہمارے پیغمبر روشن دلیلیں لا چکے پھر اسکے بعد بھی ان میں بہت سے لوگ ملک میں زیادتیاں کرنے والے ہیں۔', 'اسی سبب سے لکھا ہم نے [۱۱۱] بنی اسرائیل پر کہ جو کوئی قتل کرے ایک جان کو بلاعوض جان کے یا بغیر فساد کرنے کے ملک میں [۱۱۲] تو گویا قتل کر ڈالا اس نے سب لوگوں کو اور جس نے زندہ رکھا ایک جان کو تو گویا زندہ کر دیا سب لوگوں کو [۱۱۳] اور لا چکے ہیں انکے پاس رسول ہمارے کھلے ہوئے حکم [۱۱۴] پھر بہت لوگ ان میں سے اس پر بھی ملک میں دست درازی کرتے ہیں [۱۱۵]', 'Because of that We ordained for the Children of Israel that if anyone killed a person not in retaliation of murder, or (and) to spread mischief in the land - it would be as if he killed all mankind, and if anyone saved a life, it would be as if he saved the life of all mankind. And indeed, there came to them Our Messengers with clear proofs, evidences, and signs, even then after that many of them continued to exceed the limits (e.g. by doing oppression unjustly and exceeding beyond the limits set by Allah by committing the major sins) in the land!.', 'For this reason, We decreed for the children of Isrā’īl that whoever kills a person not in retaliation for a person killed, nor (as a punishment) for spreading disorder on the earth, is as if he has killed the whole of humankind, and whoever saves the life of a person is as if he has saved the life of the whole of humankind. Certainly, Our messengers have come to them with clear signs. Then, after all that, many of them are there to commit excesses on the earth.'),
(702, 5, 33, 5, 9, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'اِنَّمَا جَزٰٓؤُا الَّذِیۡنَ یُحَارِبُوۡنَ اللّٰہَ وَ رَسُوۡلَہٗ وَ یَسۡعَوۡنَ فِی الۡاَرۡضِ فَسَادًا اَنۡ یُّقَتَّلُوۡۤا اَوۡ یُصَلَّبُوۡۤا اَوۡ تُقَطَّعَ اَیۡدِیۡہِمۡ وَ اَرۡجُلُہُمۡ مِّنۡ خِلَافٍ اَوۡ یُنۡفَوۡا مِنَ  الۡاَرۡضِ ؕ ذٰلِکَ لَہُمۡ خِزۡیٌ فِی الدُّنۡیَا وَ لَہُمۡ فِی الۡاٰخِرَۃِ عَذَابٌ عَظِیۡمٌ ﴿ۙ۳۳﴾', 'جو لوگ اللہ اور اسکے رسول سے لڑائی کریں اور ملک میں فساد کرنے کو دوڑتے پھریں ان کی یہی سزا ہے کہ بری طرح  قتل کر دیئے جائیں یا سولی چڑھا دیئے جائیں یا ان کے ایک ایک طرف کے ہاتھ اور ایک ایک طرف کے پاؤں کاٹ دیئے جائیں یا ملک سے غائب کر دیئے جائیں۔ یہ تو دنیا میں انکی رسوائی ہے اور آخرت میں ان کے لئے بڑا بھاری عذاب تیار ہے۔', 'یہی سزا ہے ان کی جو لڑائی کرتے ہیں اللہ سے اور اسکے رسول سے اور دوڑتے ہیں ملک میں فساد کرنے کو [۱۱۶] ان کو قتل کیا جائےیا سولی چڑھائے جاویں یا کاٹے جاویں ان کے ہاتھ اور پاؤں مخالف جانب سے [۱۱۷] یا دور کر دیے جاویں اس جگہ سے [۱۱۸] یہ ان کی رسوائی ہے دنیا میں اور ان کے لئے آخرت میں بڑا عذاب ہے [۱۱۹]', 'The recompense of those who wage war against Allah and His Messenger and do mischief in the land is only that they shall be killed or crucified or their hands and their feet be cut off on the opposite sides, or be exiled from the land. That is their disgrace in this world, and a great torment is theirs in the Hereafter.', 'Those who fight against Allah and His Messenger and run about trying to spread disorder on the earth, their punishment is no other than that they shall be killed, or be crucified, or their hands and legs be cut off from different sides, or they be kept away from the land (they live in). That is a humiliation for them in this world, and for them there is a great punishment in the Hereafter;'),
(703, 5, 34, 5, 9, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'اِلَّا الَّذِیۡنَ تَابُوۡا مِنۡ قَبۡلِ اَنۡ تَقۡدِرُوۡا عَلَیۡہِمۡ ۚ فَاعۡلَمُوۡۤا اَنَّ اللّٰہَ غَفُوۡرٌ رَّحِیۡمٌ ﴿٪۳۴﴾', 'ہاں جن لوگوں نے اس سے پیشتر کہ تمہارے قابو آ جائیں توبہ کر لی تو جان رکھو کہ اللہ بخشنے والا ہے مہربان ہے۔', 'مگر جنہوں نے توبہ کی تمہارے قابو پانے سے پہلے تو جان لو کہ اللہ بخشنے والا مہربان ہے [۱۲۰]', 'Except for those who (having fled away and then) came back (as Muslims) with repentance before they fall into your power; in that case, know that Allah is OftForgiving, Most Merciful.', 'except those who repent before you overpower them. Then, be sure that Allah is Most-Forgiving, Very-Merciful.'),
(704, 5, 35, 6, 10, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوا اتَّقُوا اللّٰہَ وَ ابۡتَغُوۡۤا اِلَیۡہِ الۡوَسِیۡلَۃَ وَ جَاہِدُوۡا فِیۡ سَبِیۡلِہٖ  لَعَلَّکُمۡ  تُفۡلِحُوۡنَ ﴿۳۵﴾', 'اے ایمان والو! اللہ سے ڈرتے رہو اور اس کا قرب تلاش کرتے رہو اور اسکے رستے میں جہاد کرو تا کہ کامیاب ہو جاؤ۔', 'اے ایمان والو ڈرتے رہو اللہ سے اور ڈھونڈو اس تک وسیلہ [۱۲۱] اور جہاد کرو اس کی راہ میں تاکہ تمہارا بھلا ہو [۱۲۲]', 'O you who believe! Do your duty to Allah and fear Him. Seek the means of approach to Him, and strive hard in His Cause as much as you can. So that you may be successful.', 'O you who believe, fear Allah and seek means of nearness to Him, and carry out Jihād in His way, so that you may succeed.'),
(705, 5, 36, 6, 10, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'اِنَّ الَّذِیۡنَ کَفَرُوۡا لَوۡ اَنَّ لَہُمۡ مَّا فِی الۡاَرۡضِ جَمِیۡعًا وَّ مِثۡلَہٗ مَعَہٗ لِیَفۡتَدُوۡا بِہٖ مِنۡ عَذَابِ یَوۡمِ الۡقِیٰمَۃِ مَا تُقُبِّلَ مِنۡہُمۡ ۚ وَ لَہُمۡ عَذَابٌ  اَلِیۡمٌ ﴿۳۶﴾', 'جو لوگ کافر ہیں اگر ان کے پاس روئے زمین  کا سب مال و متاع ہو اور اسکے ساتھ اسی قدر اور بھی ہو تاکہ قیامت کے روز عذاب سے رستگاری حاصل کرنے کا بدلہ دیں تو ان سے قبول نہیں کیا جائے گا اور ان کو درد دینے والا عذاب ہو گا۔', 'جو لوگ کافر ہیں اگر ان کے پاس ہو جو کچھ زمین میں ہے سارا اور اس کے ساتھ اتنا ہی اور ہو تاکہ بدلہ میں دیں اپنے قیامت کے عذاب سے تو ان سےقبول نہ ہو گا اور ان کے واسطے عذاب دردناک ہے [۱۲۳]', 'Verily, those who disbelieve, if they had all that is in the earth, and as much again therewith to ransom themselves thereby from the torment on the Day of Resurrection, it would never be accepted of them, and theirs would be a painful torment.', 'Surely, if the disbelievers have all that is in the earth, and more as much besides it, to pay it as ransom against the punishment of the Day of Judgment, it shall not be accepted from them, and they will have a painful punishment.'),
(706, 5, 37, 6, 10, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یُرِیۡدُوۡنَ اَنۡ یَّخۡرُجُوۡا مِنَ النَّارِ وَ مَا ہُمۡ بِخٰرِجِیۡنَ مِنۡہَا ۫ وَ لَہُمۡ عَذَابٌ مُّقِیۡمٌ ﴿۳۷﴾', 'وہ ہرچند چاہیں گے کہ آگ سے نکل جائیں مگر اس سے نہیں نکل سکیں گے اور ان کے لئے ہمیشہ کا عذاب ہے۔', 'چاہیں گے کہ نکل جاویں آگ سے اور وہ اس سے نکلنے والے نہیں اور ان کے لئے عذاب دائمی ہے [۱۲۴]', 'They will long to get out of the Fire, but never will they get out therefrom, and theirs will be a lasting torment.', 'They will wish to come out of the Fire, but they will not be able to come out from there. For them there will be a lasting punishment.'),
(707, 5, 38, 6, 10, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ السَّارِقُ وَ السَّارِقَۃُ فَاقۡطَعُوۡۤا اَیۡدِیَہُمَا جَزَآءًۢ بِمَا کَسَبَا نَکَالًا مِّنَ  اللّٰہِ ؕ وَ اللّٰہُ عَزِیۡزٌ  حَکِیۡمٌ ﴿۳۸﴾', 'اور چوری کرنے والا مرد اور چوری کرنے والی عورت ان کا ایک ایک ہاتھ کاٹ دو۔ یہ ان کے  کرتوتوں کی سزا اور اللہ کی طرف سے عبرت کے طور پر ہے۔ اور اللہ زبردست ہے صاحب حکمت ہے۔', 'اور چوری کرنے والا مرد اور چوری کرنے والی عورت کاٹ ڈالو انکے ہاتھ [۱۲۵] سزا میں ان کی کمائی کی تنبیہ ہے اللہ کی طرف سے [۱۲۶] اور اللہ غالب ہے حکمت والا [۱۲۷]', 'Cut off (from the wrist joint) the (right) hand of the thief, male or female, as a recompense for that which they committed, a punishment by way of example from Allah. And Allah is AllPowerful, AllWise.', 'As for a man or a woman who commits theft, cut off the hands of both to punish them for what they earned,-a deterrent punishment from Allah. Allah is Mighty, Wise.'),
(708, 5, 39, 6, 10, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'فَمَنۡ تَابَ مِنۡۢ بَعۡدِ ظُلۡمِہٖ وَ اَصۡلَحَ  فَاِنَّ اللّٰہَ یَتُوۡبُ عَلَیۡہِ ؕ اِنَّ اللّٰہَ غَفُوۡرٌ رَّحِیۡمٌ ﴿۳۹﴾', 'پھر جو شخص گناہ کے بعد توبہ کر لے اور نیکوکار ہو جائے تو اللہ اسکو معاف کر دے گا۔ کچھ شک نہیں کہ اللہ بڑا بخشنے والا ہے بڑا مہربان ہے۔', 'پھر جس نے توبہ کہ اپنے ظلم کے پیچھے اور اصلاح کی تو اللہ قبول کرتا ہے اس کی توبہ بیشک اللہ بخشنے والا مہربان ہے [۱۲۸]', 'But whosoever repents after his crime and does righteous good deeds (by obeying Allah), then verily, Allah will pardon him (accept his repentance). Verily, Allah is OftForgiving, Most Merciful.', 'Whoever repents after his transgression and corrects himself, then Allah shall relent towards him. Surely, Allah is Most-Forgiving, Very-Merciful.'),
(709, 5, 40, 6, 10, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'اَلَمۡ تَعۡلَمۡ اَنَّ اللّٰہَ لَہٗ مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ یُعَذِّبُ مَنۡ یَّشَآءُ  وَ یَغۡفِرُ لِمَنۡ یَّشَآءُ ؕ وَ اللّٰہُ عَلٰی کُلِّ شَیۡءٍ قَدِیۡرٌ ﴿۴۰﴾', 'کیا تم کو معلوم نہیں کہ آسمانوں اور زمین میں اللہ ہی کی سلطنت ہے۔ جسکو چاہے عذاب کرے اور جسے چاہے بخش دے۔ اور اللہ ہر چیز پر پوری طرح قادر ہے۔', 'تجھ کو معلوم نہیں کہ اللہ ہی کے واسطے ہے سلطنت آسمان اور زمین کی عذاب کرے جس کو چاہے اور بخشے جس کو چاہے اور اللہ سب چیز پر قادر ہے [۱۲۹]', 'Know you not that to Allah (Alone) belongs the dominion of the heavens and the earth! He punishes whom He wills and He forgives whom He wills. And Allah is Able to do all things.', 'Do you not know that to Allah alone belongs the kingdom of the heavens and the earth? He punishes whomsoever He wills and forgives whomsoever He wills. Allah is powerful over everything.'),
(710, 5, 41, 6, 10, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یٰۤاَیُّہَا الرَّسُوۡلُ لَا یَحۡزُنۡکَ الَّذِیۡنَ یُسَارِعُوۡنَ فِی الۡکُفۡرِ مِنَ الَّذِیۡنَ قَالُوۡۤا اٰمَنَّا بِاَفۡوَاہِہِمۡ وَ لَمۡ تُؤۡمِنۡ قُلُوۡبُہُمۡ ۚۛ وَ مِنَ الَّذِیۡنَ ہَادُوۡا ۚۛ سَمّٰعُوۡنَ لِلۡکَذِبِ سَمّٰعُوۡنَ لِقَوۡمٍ اٰخَرِیۡنَ ۙ  لَمۡ  یَاۡتُوۡکَ ؕ یُحَرِّفُوۡنَ الۡکَلِمَ مِنۡۢ بَعۡدِ مَوَاضِعِہٖ ۚ یَقُوۡلُوۡنَ اِنۡ اُوۡتِیۡتُمۡ ہٰذَا فَخُذُوۡہُ وَ اِنۡ لَّمۡ تُؤۡتَوۡہُ فَاحۡذَرُوۡا ؕ وَ مَنۡ یُّرِدِ اللّٰہُ فِتۡنَتَہٗ فَلَنۡ تَمۡلِکَ لَہٗ  مِنَ اللّٰہِ  شَیۡئًا ؕ اُولٰٓئِکَ الَّذِیۡنَ لَمۡ یُرِدِ اللّٰہُ اَنۡ یُّطَہِّرَ قُلُوۡبَہُمۡ ؕ لَہُمۡ فِی الدُّنۡیَا خِزۡیٌ ۚۖ وَّ لَہُمۡ فِی الۡاٰخِرَۃِ  عَذَابٌ  عَظِیۡمٌ ﴿۴۱﴾', 'اے پیغمبر جو لوگ کفر میں جلدی کرتے ہیں کچھ تو ان میں  لوگوں سے وہ ہیں جو منہ سے کہتے ہیں کہ ہم مومن ہیں لیکن ان کے دل مومن نہیں ہیں اور کچھ ان میں سے جو یہودی ہیں ان کی وجہ سے غمناک نہ ہونا یہ لوگ جھوٹی باتیں بنانے کے لئے جاسوسی کرتے پھرتے ہیں اور ان دوسرے لوگوں کے لئے جاسوس بنے ہیں جو ابھی تمہارے پاس نہیں آئے باتوں کو ان کے مقامات میں ثابت ہونے کے بعد دور لیجاتے ہیں لوگوں سے کہتے ہیں کہ اگر تم کو یہی حکم ملے تو اسے قبول کر لینا اور اگر یہ نہ ملے تو اس سے بچنا کرنا اور جسکو اللہ گمراہ کرنا چاہے تو اسکے لئے تم اللہ کی طرف سے ہدایت کا کچھ بھی اختیار نہیں رکھتے۔ یہ وہ لوگ ہیں جن کے دلوں کو اللہ نے پاک کرنا نہیں چاہا۔ انکے لئے دنیا میں ذلت ہے اور آخرت میں بڑا عذاب ہے۔', 'اے رسول غم نہ کر ان کو جو دوڑ کر گرتے ہیں کفر میں[۱۳۰] وہ لوگ جو کہتے ہیں ہم مسلمان ہیں اپنے منہ سے اور ان کے دل مسلمان نہیں اور وہ جو یہودی ہیں [۱۳۱] جاسوسی کرتے ہیں جھوٹ بولنے کے لئے وہ جاسوس ہیں دوسری جماعت کے جو تجھ تک نہیں آئے [۱۳۲] بدل ڈالتے ہیں بات کو اس کا ٹھکانہ چھوڑ کر [۱۳۳] کہتے ہیں اگر تم کو یہ حکم ملے تو قبول کر لینا اور یہ حکم نہ ملے تو بچتے رہنا [۱۳۴] اور جس اللہ نے گمراہ کرنا چاہا سو تو اس کے لئے کچھ نہیں کر سکتا اللہ کے ہاں [۱۳۵] یہ وہی لوگ ہیں جن کو اللہ نےنہ چاہا کہ دل پاک کرےان کے [۱۳۶] ان کو دنیا میں ذلت ہے اور ان کو آخرت میں بڑا عذاب ہے', 'O Messenger (Muhammad SAW)! Let not those who hurry to fall into disbelief grieve you, of such who say: \"We believe\" with their mouths but their hearts have no faith. And of the Jews are men who listen much and eagerly to lies - listen to others who have not come to you. They change the words from their places; they say, \"If you are given this, take it, but if you are not given this, then beware!\" And whomsoever Allah wants to put in AlFitnah (error, because of his rejecting the Faith), you can do nothing for him against Allah. Those are the ones whose hearts Allah does not want to purify (from disbelief and hypocrisy); for them there is a disgrace in this world, and in the Hereafter a great torment.', 'O Messenger, those who race towards disbelief should not be a cause of grief for you, be they from those who say with their mouths, “We believe”, while their hearts do not believe, or from those who are (pronounced) Jews. They are listeners to the fallacy, listeners to other people who did not come to you. They distort the words after they had been properly placed. They say, “If you are given this, take it, and if you are not given this, then avoid it.” The one whom Allah wills to put to trial, you cannot do anything for him against Allah. They are the ones whose hearts Allah did not intend to purify. For them there is humiliation in this world, and for them there is a great punishment in the Hereafter.'),
(711, 5, 42, 6, 10, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'سَمّٰعُوۡنَ لِلۡکَذِبِ اَکّٰلُوۡنَ لِلسُّحۡتِ ؕ فَاِنۡ جَآءُوۡکَ فَاحۡکُمۡ بَیۡنَہُمۡ اَوۡ اَعۡرِضۡ عَنۡہُمۡ ۚ وَ اِنۡ تُعۡرِضۡ عَنۡہُمۡ فَلَنۡ یَّضُرُّوۡکَ شَیۡئًا ؕ وَ اِنۡ حَکَمۡتَ فَاحۡکُمۡ بَیۡنَہُمۡ بِالۡقِسۡطِ ؕ اِنَّ اللّٰہَ یُحِبُّ الۡمُقۡسِطِیۡنَ ﴿۴۲﴾', 'یہ جھوٹی باتیں بنانے کیلئے جاسوسی کرنے والے۔ اور رشوت کا حرام مال کھانے والے ہیں۔ اگر یہ تمہارے پاس کوئی مقدمہ فیصل کرانے کو آئیں تو تم ان میں فیصلہ کر دینا یا روگردانی کر لینا۔ اور اگر ان سے روگردانی کرو گے تو وہ تمہارا کچھ بھی نہیں بگاڑ سکیں گے۔ اور اگر فیصلہ کرنا چاہو تو انصاف کا فیصلہ کرنا کہ اللہ انصاف کرنے والوں کو دوست رکھتا ہے۔', 'جاسوسی کرنے والے جھوٹ بولنے کے لئے اور بڑے حرام کھانے والے سو اگر آویں وہ تیرے پاس تو فیصلہ کر دے ان میں یا منہ پھیر لے ان سے [۱۳۷] اور اگر تو منہ پھیر لے گا ان سے تو وہ تیرا کچھ نہ بگاڑ سکیں گے اور اگر تو فیصلہ کرے تو فیصلہ کر ان میں انصاف سے بیشک اللہ دوست رکھتا ہے انصاف کرنے والوں کو [۱۳۸]', '(They like to) listen to falsehood, to devour anything forbidden. So if they come to you (O Muhammad SAW), either judge between them, or turn away from them. If you turn away from them, they cannot hurt you in the least. And if you judge, judge with justice between them. Verily, Allah loves those who act justly.', 'They are listeners to the fallacy, devourers of the unlawful. So, if they come to you, judge between them or turn away from them. If you turn away from them, they can do you no harm. But if you judge, judge between them with justice. Surely, Allah loves those who do justice.'),
(712, 5, 43, 6, 10, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ کَیۡفَ یُحَکِّمُوۡنَکَ وَ عِنۡدَہُمُ  التَّوۡرٰىۃُ فِیۡہَا حُکۡمُ اللّٰہِ ثُمَّ یَتَوَلَّوۡنَ مِنۡۢ بَعۡدِ ذٰلِکَ ؕ وَ مَاۤ  اُولٰٓئِکَ بِالۡمُؤۡمِنِیۡنَ ﴿٪۴۳﴾', 'اور یہ تم سے اپنے مقدمات کیونکر فیصل کرائیں گے۔ جب کہ خود انکے پاس تورات موجود ہے جسمیں اللہ کا حکم لکھا ہوا ہے یہ اسے جانتے ہیں پھر اسکے بعد اس سے پھر جاتے ہیں اور یہ لوگ ایمان ہی نہیں رکھتے۔', 'اور وہ تجھ کو کس طرح منصف بنائیں گے اور ان کے پاس تو توریت ہے جس میں حکم ہے اللہ کا پھر اس کے پیچھے پھرے جاتے ہیں اور وہ ہر گز ماننے والے نہیں ہیں [۱۳۹]', 'But how do they come to you for decision while they have the Taurat (Torah), in which is the (plain) Decision of Allah; yet even after that, they turn away. For they are not (really) believers.', 'How do they ask you to judge while the Torah is with them, having the ruling of Allah? Still, they turn away, after all that. They are no believers.'),
(713, 5, 44, 7, 11, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'اِنَّاۤ  اَنۡزَلۡنَا التَّوۡرٰىۃَ فِیۡہَا ہُدًی وَّ نُوۡرٌ ۚ یَحۡکُمُ بِہَا النَّبِیُّوۡنَ الَّذِیۡنَ اَسۡلَمُوۡا لِلَّذِیۡنَ ہَادُوۡا وَ الرَّبّٰنِیُّوۡنَ وَ الۡاَحۡبَارُ بِمَا اسۡتُحۡفِظُوۡا مِنۡ کِتٰبِ اللّٰہِ وَ کَانُوۡا عَلَیۡہِ شُہَدَآءَ ۚ فَلَا تَخۡشَوُا النَّاسَ وَ اخۡشَوۡنِ  وَ لَا  تَشۡتَرُوۡا بِاٰیٰتِیۡ ثَمَنًا قَلِیۡلًا ؕ وَ مَنۡ لَّمۡ یَحۡکُمۡ بِمَاۤ اَنۡزَلَ اللّٰہُ فَاُولٰٓئِکَ ہُمُ الۡکٰفِرُوۡنَ ﴿۴۴﴾', 'بیشک ہم نے تورات نازل فرمائی جسمیں ہدایت اور روشنی ہے۔ اسی کے مطابق انبیاء جو اللہ کے فرمانبردار تھے یہودیوں کو حکم دیتے رہے ہیں۔ اور مشائخ اور علماء بھی کیونکہ وہ اللہ کی کتاب کے نگہبان مقرر کئے گئے تھے اور اس پر گواہ تھے یعنی حکم الہٰی کا یقین رکھتے تھے سو تم لوگوں سے مت ڈرنا اور مجھی سے ڈرتے رہنا اور میری آیتوں کے بدلے تھوڑی سی قیمت نہ لینا۔ اور جو اللہ کے نازل فرمائے ہوئے احکام کے مطابق حکم نہ دے تو ایسے ہی لوگ کافر ہیں۔', 'ہم نےنازل کی توریت کہ اس میں ہدایت اور روشنی ہے [۱۴۰] اس پر حکم کرتے تھے پیغمبر جو کہ حکم بردار تھے اللہ کے یہود کو اور حکم کرتے تھے درویش اور عالم [۱۴۱] اس واسطے کہ وہ نگہبان ٹھہرائے گئے تھے اللہ کی کتاب پر اور اس کی خبر گیری پر مقرر تھے [۱۴۲] سو تم نہ ڈرو لوگوں سے اور مجھ سے ڈرو اور مت خریدو میری آیتوں پر مول تھوڑا [۱۴۳] اور جو کوئی حکم نہ کرے اس کے موافق جو کہ اللہ نے اتارا سو وہی لوگ ہیں کافر [۱۴۴]', 'Verily, We did send down the Taurat (Torah) (to Moosa (Moses)), therein was guidance and light, by which the Prophets, who submitted themselves to Allahs Will, judged the Jews. And the rabbis and the priests (too judged the Jews by the Taurat (Torah) after those Prophets) for to them was entrusted the protection of Allahs Book, and they were witnesses thereto. Therefore fear not men but fear Me (O Jews) and sell not My Verses for a miserable price. And whosoever does not judge by what Allah has revealed, such are the Kafiroon (i.e. disbelievers - of a lesser degree as they do not act on Allahs Laws).', 'Surely We have sent down the Torah, in which there was guidance and light by which the prophets, who submitted themselves to Allah, used to judge for the Jews, and (so did) the Men of Allah and the Men of knowledge, because they were ordained to protect the Book of Allah, and they stood guard over it. So, (O Jews of today,) do not fear people. Fear Me, and do not take a paltry price for My verses. Those who do not judge according to what Allah has sent down are the disbelievers.'),
(714, 5, 45, 7, 11, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ کَتَبۡنَا عَلَیۡہِمۡ فِیۡہَاۤ  اَنَّ النَّفۡسَ بِالنَّفۡسِ ۙ وَ الۡعَیۡنَ بِالۡعَیۡنِ وَ الۡاَنۡفَ بِالۡاَنۡفِ وَ الۡاُذُنَ بِالۡاُذُنِ وَ السِّنَّ بِالسِّنِّ ۙ وَ الۡجُرُوۡحَ قِصَاصٌ ؕ فَمَنۡ تَصَدَّقَ بِہٖ فَہُوَ کَفَّارَۃٌ  لَّہٗ  ؕ وَ مَنۡ لَّمۡ یَحۡکُمۡ بِمَاۤ اَنۡزَلَ اللّٰہُ فَاُولٰٓئِکَ ہُمُ الظّٰلِمُوۡنَ ﴿۴۵﴾', 'اور ہم نے ان لوگوں کے لئے تورات میں یہ حکم لکھ دیا تھا کہ جان کے بدلے جان اور آنکھ کے بدلے آنکھ اور ناک کے بدلے ناک اور کان کے بدلے کان اور دانت کے بدلے دانت اور سب زخموں کا اسی طرح بدلہ ہے اب جو شخص بدلہ معاف کر دے وہ اسکے لئے کفارہ ہو گا اور جو اللہ کے نازل فرمائے ہوئے احکام کے مطابق حکم نہ دے تو ایسے ہی لوگ بے انصاف ہیں۔', 'اور لکھ دیا ہم نے ان پر اس کتاب میں کہ جی کے بدلے جی اور آنکھ کے بدلے آنکھ اور ناک کے بدلے ناک اور کان کے بدلے کان اور دانت کے بدلے دانت اور زخموں کا بدلا انکے برابر [۱۴۵] پھر جس نے معاف کر دیا تو وہ گناہ سے پاک ہو گیا [۱۴۶] اور جو کوئی حکم نہ کرے اس کے موافق جو کہ اللہ نے اتارا سو وہی لوگ ہیں ظالم [۱۴۷]', 'And We ordained therein for them: \"Life for life, eye for eye, nose for nose, ear for ear, tooth for tooth, and wounds equal for equal.\" But if anyone remits the retaliation by way of charity, it shall be for him an expiation. And whosoever does not judge by that which Allah has revealed, such are the Zalimoon (polytheists and wrongdoers - of a lesser degree).', 'We prescribed for them therein: A life for a life, an eye for an eye, a nose for a nose, an ear for an ear and a tooth for a tooth; and for wounds, an equal retaliation. Then, if one forgives it, that will be expiation for him. Those who do not judge according to what Allah has sent down, they are the unjust.'),
(715, 5, 46, 7, 11, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ قَفَّیۡنَا عَلٰۤی اٰثَارِہِمۡ بِعِیۡسَی ابۡنِ مَرۡیَمَ مُصَدِّقًا لِّمَا بَیۡنَ یَدَیۡہِ مِنَ التَّوۡرٰىۃِ ۪ وَ اٰتَیۡنٰہُ الۡاِنۡجِیۡلَ فِیۡہِ ہُدًی وَّ نُوۡرٌ ۙ وَّ مُصَدِّقًا لِّمَا بَیۡنَ  یَدَیۡہِ مِنَ التَّوۡرٰىۃِ وَ ہُدًی وَّ مَوۡعِظَۃً  لِّلۡمُتَّقِیۡنَ ﴿ؕ۴۶﴾', 'اور ان پیغمبروں کے بعد انہی کے قدموں پر ہم نے عیسٰی ابن مریم کو بھیجا جو اپنے سے پہلے کی کتاب تورات کی تصدیق کرتے تھے اور انکو انجیل عنایت کی جسمیں ہدایت اور نور ہے اور تورات کی جو اس سے پہلی کتاب ہے تصدیق کرتی ہے اور پرہیزگاروں کو راہ بتاتی اور نصیحت کرتی ہے۔', 'اور پیچھے بھیجا ہم نے انہی کےقدموں پر عیسٰی مریم کے بیٹے کو [۱۴۸] تصدیق کرنے والا توریت کی جو آگے سے تھے اور اس کو دی ہم نے انجیل جس میں ہدایت اور روشنی تھی اور تصدیق کرتی تھی اپنے سے اگلی کتاب توریت کی اور راہ بتلانے والی اور نصیحت تھی ڈرنے والوں کو [۱۴۹]', 'And in their footsteps, We sent Iesa (Jesus), son of Maryam (Mary), confirming the Taurat (Torah) that had come before him, and We gave him the Injeel (Gospel), in which was guidance and light and confirmation of the Taurat (Torah) that had come before it, a guidance and an admonition for Al-Muttaqoon (the pious - see V.2:2).', 'We sent ‘Īsā son of Maryam after those prophets, confirming the Torah that was (revealed) before him, and We gave him the Injīl having guidance and light therein, and confirming the Torah that was (revealed) before it; a guidance and a lesson for the God-fearing.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(716, 5, 47, 7, 11, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ لۡیَحۡکُمۡ اَہۡلُ  الۡاِنۡجِیۡلِ بِمَاۤ  اَنۡزَلَ اللّٰہُ فِیۡہِ ؕ وَ مَنۡ لَّمۡ یَحۡکُمۡ بِمَاۤ اَنۡزَلَ اللّٰہُ فَاُولٰٓئِکَ ہُمُ  الۡفٰسِقُوۡنَ ﴿۴۷﴾', 'اور اہل انجیل کو چاہیے کہ جو احکام اللہ نے اس میں نازل فرمائے ہیں اسکے مطابق حکم دیا کریں۔ اور جو اللہ کے نازل کئے ہوئے احکام کے مطابق حکم نہ دے گا تو ایسے لوگ نافرمان ہیں۔', 'اور چاہئے کہ حکم کریں انجیل والے موافق اس کے جو کہ اتارا اللہ نے اس میں اور جو کوئی حکم نہ کرے موافق اس کے جو کہ اتارا اللہ نےسو وہی لوگ ہیں نافرمان [۱۵۰]', 'Let the people of the Injeel (Gospel) judge by what Allah has revealed therein. And whosoever does not judge by what Allah has revealed (then) such (people) are the Fasiqoon (the rebellious i.e. disobedient (of a lesser degree) to Allah.', 'And the people of the Injīl must judge according to what Allah has sent down therein. Those who do not judge according to what Allah has sent down, they are the sinners.'),
(717, 5, 48, 7, 11, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ اَنۡزَلۡنَاۤ اِلَیۡکَ الۡکِتٰبَ بِالۡحَقِّ مُصَدِّقًا لِّمَا بَیۡنَ یَدَیۡہِ مِنَ الۡکِتٰبِ وَ مُہَیۡمِنًا عَلَیۡہِ فَاحۡکُمۡ  بَیۡنَہُمۡ بِمَاۤ اَنۡزَلَ اللّٰہُ وَ لَا تَتَّبِعۡ اَہۡوَآءَہُمۡ عَمَّا جَآءَکَ مِنَ الۡحَقِّ ؕ لِکُلٍّ جَعَلۡنَا مِنۡکُمۡ شِرۡعَۃً وَّ مِنۡہَاجًا ؕ وَ لَوۡ  شَآءَ اللّٰہُ لَجَعَلَکُمۡ اُمَّۃً وَّاحِدَۃً  وَّ لٰکِنۡ  لِّیَبۡلُوَکُمۡ فِیۡ مَاۤ اٰتٰىکُمۡ فَاسۡتَبِقُوا الۡخَیۡرٰتِ ؕ اِلَی اللّٰہِ مَرۡجِعُکُمۡ جَمِیۡعًا فَیُنَبِّئُکُمۡ بِمَا کُنۡتُمۡ  فِیۡہِ  تَخۡتَلِفُوۡنَ ﴿ۙ۴۸﴾', 'اور اے پیغمبر ہم نے تم پر سچّی کتاب نازل کی ہے جو اپنے سے پہلی کتابوں کی تصدیق کرتی ہے اور ان سب پر نگہبان ہے تو جو حکم اللہ نے نازل فرمایا ہے اسکے مطابق ان کا فیصلہ کرنا اور حق جو تمہارے پاس آ چکا ہے اسکو چھوڑ کر انکی خواہشوں کی پیروی نہ کرنا۔ ہم نے تم میں سے ہر ایک ملت کے لئے ایک دستور اور ایک طریقہ مقرر کیا ہے۔ اور اگر اللہ چاہتا تو تم سب کو ایک ہی شریعت پر کر دیتا مگر جو حکم اس نے تم کو دیئے ہیں ان میں وہ تمہاری آزمائش کرنی چاہتا ہے۔ سو نیک کاموں میں آگے بڑھو تم سب کو اللہ کی طرف لوٹ کر جانا ہے پھر جن باتوں میں تم کو اختلاف تھا وہ تم کو بتا دے گا۔', 'اور تجھ پر اتاری ہم نے کتاب سچی تصدیق کرنے والی سابقہ کتابوں کی اور ان کے مضامیں پر نگہبان [۱۵۱] سو تو حکم کر ان میں موافق اسکے جو کہ اتارا اللہ نے [۱۵۲] اور انکی خوشی پر مت چل چھوڑ کر سیدھا راستہ جو تیرے پاس آیا [۱۵۳] ہر ایک کو تم میں سے دیا ہم نے ایک دستور اور راہ [۱۵۴] اور اللہ چاہتا تو تم کو ایک دین پر کر دیتا لیکن تم کو آزمانا چاہتا ہے اپنے دیے ہوئے حکموں میں [۱۵۵] سو تم دوڑ کر لو خوبیاں [۱۵۶] اللہ کے پاس تم سب کو پہنچنا ہے پھر جتا دے گا جس بات میں تم کو اختلاف تھا [۱۵۷]', 'And We have sent down to you (O Muhammad SAW) the Book (this Quran) in truth, confirming the Scripture that came before it and Mohayminan (trustworthy in highness and a witness) over it (old Scriptures). So judge between them by what Allah has revealed, and follow not their vain desires, diverging away from the truth that has come to you. To each among you, We have prescribed a law and a clear way. If Allah willed, He would have made you one nation, but that (He) may test you in what He has given you; so strive as in a race in good deeds. The return of you (all) is to Allah; then He will inform you about that in which you used to differ.', 'We have sent down to you the Book with truth, confirming the Book before it, and a protector for it. So, judge between them according to what Allah has sent down, and do not follow their desires against the truth that has come to you. For each of you We have made a law and a method. Had Allah willed, He would have made a single community of people, but (He did not), so that He may test you in what He has given to you. Strive, then, to excel each other in good deeds. To Allah is the return for all of you. Then Allah shall tell you about that in which you disputed.'),
(718, 5, 49, 7, 11, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ اَنِ احۡکُمۡ بَیۡنَہُمۡ  بِمَاۤ اَنۡزَلَ اللّٰہُ  وَ لَا تَتَّبِعۡ اَہۡوَآءَہُمۡ وَ احۡذَرۡہُمۡ اَنۡ یَّفۡتِنُوۡکَ عَنۡۢ بَعۡضِ مَاۤ اَنۡزَلَ اللّٰہُ اِلَیۡکَ ؕ فَاِنۡ تَوَلَّوۡا فَاعۡلَمۡ اَنَّمَا یُرِیۡدُ اللّٰہُ اَنۡ یُّصِیۡبَہُمۡ بِبَعۡضِ ذُنُوۡبِہِمۡ ؕ وَ اِنَّ  کَثِیۡرًا مِّنَ  النَّاسِ  لَفٰسِقُوۡنَ ﴿۴۹﴾', 'اور ہم پھر تاکید کرتے ہیں کہ جو حکم اللہ نے نازل فرمایا ہے اسی کے مطابق ان میں فیصلہ کرنا اور انکی خواہشوں کی پیروی نہ کرنا اور ان سے محتاط رہنا کہ کسی حکم سے جو اللہ نے تم پر نازل فرمایا ہے یہ کہیں تم کو بہکا نہ دیں۔ اب اگر یہ نہ مانیں تو جان لو کہ اللہ چاہتا ہے کہ انکے بعض گناہوں کے سبب ان پر مصیبت نازل کرے اور اکثر لوگ تو نافرمان ہیں ہی۔', 'اور یہ فرمایا کہ حکم کر ان میں موافق اس کے جو کہ اتارا اللہ نے اور مت چل ان کی خوشی پر اور بچتا رہ ان سے کہ تجھ کو بہکا نہ دیں کسی اسےحکم سے جو اللہ نے اتارا تجھ پر [۱۵۸] پھر اگر نہ مانیں تو جان لے کہ اللہ نے یہی چاہا ہے کہ پہنچا دے انکو کچھ سزا ان کے گناہوں کی [۱۵۹] اور لوگوں میں بہت ہیں نافرمان [۱۶۰]', 'And so judge (you O Muhammad SAW) between them by what Allah has revealed and follow not their vain desires, but beware of them lest they turn you (O Muhammad SAW) far away from some of that which Allah has sent down to you. And if they turn away, then know that Allahs Will is to punish them for some sins of theirs. And truly, most of men are Fasiqoon (rebellious and disobedient to Allah).', 'We order you to judge between them according to what Allah has sent down. Do not follow their desires, and beware of them, lest they should turn you away from some of what Allah has sent down to you. If they turn away, be assured that Allah intends to make them suffer for some of their sins. Surely, many of the people are sinners.'),
(719, 5, 50, 7, 11, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'اَفَحُکۡمَ الۡجَاہِلِیَّۃِ یَبۡغُوۡنَ ؕ وَ مَنۡ اَحۡسَنُ مِنَ اللّٰہِ حُکۡمًا لِّقَوۡمٍ یُّوۡقِنُوۡنَ ﴿٪۵۰﴾', 'پس کیا یہ زمانہ جاہلیت کے سے فیصلے کے خواہشمند ہیں۔ اور جو  لوگ یقین رکھتے ہیں ان کے لئے اللہ سے اچھا فیصلہ کس کا ہو گا۔', 'اب کیا حکم چاہتے ہیں کفر کے وقت کا اور اللہ سے بہتر کون ہے حکم کرنے والا یقین کرنے والوں کے واسطے [۱۶۱]', 'Do they then seek the judgement of (the Days of) Ignorance? And who is better in judgement than Allah for a people who have firm Faith.', 'Is it, then, the judgement of (the days of) Ignorance that they seek? Who is better in judgement than Allah, for a people who believe?'),
(720, 5, 51, 8, 12, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَتَّخِذُوا الۡیَہُوۡدَ وَ النَّصٰرٰۤی اَوۡلِیَآءَ ۘؔ بَعۡضُہُمۡ اَوۡلِیَآءُ بَعۡضٍ ؕ وَ مَنۡ  یَّتَوَلَّہُمۡ  مِّنۡکُمۡ فَاِنَّہٗ  مِنۡہُمۡ ؕ اِنَّ اللّٰہَ  لَا یَہۡدِی الۡقَوۡمَ  الظّٰلِمِیۡنَ ﴿۵۱﴾', 'اے ایمان والو! یہود اور نصارٰی کو دوست نہ بناؤ یہ ایک دوسرے کے دوست ہیں اور جو شخص تم میں سے انکو دوست بنائے گا وہ بھی انہیں میں شمار ہو گا۔ بیشک اللہ ظالم لوگوں کو ہدایت نہیں دیتا۔', 'اے ایمان والو مت بناؤ یہود اور نصاریٰ کو دوست [۱۶۲] وہ آپس میں دوست ہیں ایک دوسرے کے [۱۶۳] اور جو کوئی تم میں سے دوستی کرے ان سے تو وہ انہی میں ہے [۱۶۴] اللہ ہدایت نہیں کرتا ظالم لوگوں کو [۱۶۵]', 'O you who believe! Take not the Jews and the Christians as Auliya (friends, protectors, helpers, etc.), they are but Auliya to one another. And if any amongst you takes them as Auliya, then surely he is one of them. Verily, Allah guides not those people who are the Zalimoon (polytheists and wrongdoers and unjust).', 'O you who believe, do not take the Jews and the Christians for intimate friends. They are friends to each other. Whoever takes them as intimate friends is one of them. Surely, Allah does not take the unjust people to the right path.'),
(721, 5, 52, 8, 12, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'فَتَرَی الَّذِیۡنَ فِیۡ قُلُوۡبِہِمۡ مَّرَضٌ یُّسَارِعُوۡنَ فِیۡہِمۡ یَقُوۡلُوۡنَ نَخۡشٰۤی اَنۡ تُصِیۡبَنَا دَآئِرَۃٌ ؕ فَعَسَی اللّٰہُ اَنۡ یَّاۡتِیَ بِالۡفَتۡحِ اَوۡ اَمۡرٍ مِّنۡ عِنۡدِہٖ فَیُصۡبِحُوۡا عَلٰی  مَاۤ  اَسَرُّوۡا  فِیۡۤ   اَنۡفُسِہِمۡ نٰدِمِیۡنَ ﴿ؕ۵۲﴾', 'تو جن لوگوں کے دلوں میں نفاق کا مرض ہے تم ان کو دیکھو گے کہ وہ ان میں دوڑ دوڑ کے ملے جاتے ہیں کہتے ہیں کہ ہمیں خوف ہے کہ کہیں ہم پر زمانے کی گردش نہ آ جائے سو قریب ہے کہ اللہ فتح بھیجے یا اپنے ہاں سے کوئی اور امر نازل فرمائے پھر یہ اپنے دل کی باتوں پر جو چھپایا کرتے تھے پشیمان ہو کر رہ جائیں گے۔', 'اب تو دیکھے گا ان کو جن کے دل میں بیماری ہے دوڑ کر ملتے ہیں ان میں کہتے ہیں کہ ہم کو ڈر ہے کہ نہ آجائے ہم پر گردش زمانہ کی [۱۶۶] سو قریب ہے کہ اللہ جلد ظاہر فرماوے فتح یا کوئی حکم اپنے پاس سے تو لگیں اپنے جی کی چھپی بات پر پچتانے [۱۶۷]', 'And you see those in whose hearts there is a disease (of hypocrisy), they hurry to their friendship, saying: \"We fear lest some misfortune of a disaster may befall us.\" Perhaps Allah may bring a victory or a decision according to His Will. Then they will become regretful for what they have been keeping as a secret in themselves.', 'Now, you see those who have disease in their hearts race towards them saying, “We apprehend that some misfortune may overtake us.”So, it is likely that Allah may bring victory or something else from His own side, whereupon they will become regretful over what they concealed in their hearts.'),
(722, 5, 53, 8, 12, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ یَقُوۡلُ الَّذِیۡنَ اٰمَنُوۡۤا اَہٰۤؤُلَآءِ الَّذِیۡنَ اَقۡسَمُوۡا بِاللّٰہِ جَہۡدَ اَیۡمَانِہِمۡ ۙ اِنَّہُمۡ لَمَعَکُمۡ ؕ حَبِطَتۡ اَعۡمَالُہُمۡ فَاَصۡبَحُوۡا خٰسِرِیۡنَ ﴿۵۳﴾', 'اور اس وقت مسلمان تعجب سے کہیں گے کہ کیا یہ وہی ہیں جو اللہ کی سخت سخت قسمیں کھایا کرتے تھے کہ ہم تمہارے ساتھ ہیں۔ ان کے عمل اکارت گئے سو وہ خسارے میں پڑ گئے۔', 'اور کہتے ہیں مسلمان کیا یہ وہی لوگ ہیں جو قسمیں کھاتے تھے اللہ کی تاکید سے کہ ہم تمہارے ساتھ ہیں برباد گئے ان کےعمل پھر رہ گئے نقصان میں', 'And those who believe will say: \"Are these the men (hypocrites) who swore their strongest oaths by Allah that they were with you (Muslims)?\" All that they did has been in vain (because of their hypocrisy), and they have become the losers.', 'Those who believe will say, “Are these the ones who swore their solemn oaths by Allah that they were with you?” Their deeds have gone to waste, and they became losers.'),
(723, 5, 54, 8, 12, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا مَنۡ یَّرۡتَدَّ مِنۡکُمۡ عَنۡ دِیۡنِہٖ فَسَوۡفَ یَاۡتِی اللّٰہُ بِقَوۡمٍ یُّحِبُّہُمۡ وَ یُحِبُّوۡنَہٗۤ ۙ اَذِلَّۃٍ عَلَی الۡمُؤۡمِنِیۡنَ اَعِزَّۃٍ عَلَی الۡکٰفِرِیۡنَ ۫ یُجَاہِدُوۡنَ فِیۡ سَبِیۡلِ اللّٰہِ وَ لَا  یَخَافُوۡنَ لَوۡمَۃَ لَآئِمٍ ؕ ذٰلِکَ فَضۡلُ اللّٰہِ یُؤۡتِیۡہِ مَنۡ  یَّشَآءُ ؕ وَ اللّٰہُ  وَاسِعٌ  عَلِیۡمٌ ﴿۵۴﴾', 'اے ایمان والو! اگر کوئی تم میں سے اپنے دین سے پھر جائے گا تو اللہ ایسے لوگ پیدا کر دے گا جنکو وہ دوست رکھے اور اسے وہ دوست رکھیں اور جو مومنوں پر نرمی کرنے والے اور کافروں پر سختی کرنے والے ہوں۔ اللہ کی راہ میں جہاد کریں اور کسی ملامت کرنے والے کی ملامت سے نہ ڈریں۔ یہ اللہ کا فضل ہے۔ وہ جسے چاہتا ہے دیتا ہے۔ اور اللہ بڑی کشائش والا ہے سب کچھ جاننے والا ہے۔', 'اے ایمان والو جو کوئی تم میں پھرے گا اپنے دین سے تو اللہ عنقریب لاوے گا ایسی قوم کو کہ اللہ انکو چاہتا ہے اور وہ اس کو چاہتے ہیں نرم دل ہیں مسلمانوں پر زبردست ہیں کافروں پر لڑتے ہیں اللہ کی راہ میں اور ڈرتے نہیں کسی کے الزام سے [۱۶۸] یہ فضل ہے اللہ کا دے گا جس کو چاہے اور اللہ کشائش والا ہے خبردار [۱۶۹]', 'O you who believe! Whoever from among you turns back from his religion (Islam), Allah will bring a people whom He will love and they will love Him; humble towards the believers, stern towards the disbelievers, fighting in the Way of Allah, and never afraid of the blame of the blamers. That is the Grace of Allah which He bestows on whom He wills. And Allah is AllSufficient for His creatures needs, AllKnower.', 'O you who believe, if anyone from you turns back from his Faith, then Allah will bring a people whom He loves and who love Him, humble toward the believers, hard on the disbelievers, who fight in the way of Allah and are not afraid of the reproach of any critic. That is a grace of Allah. He confers it on whom He wills. Allah is All-Embracing, All-Knowing'),
(724, 5, 55, 8, 12, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'اِنَّمَا وَلِیُّکُمُ اللّٰہُ وَ رَسُوۡلُہٗ وَ الَّذِیۡنَ اٰمَنُوا الَّذِیۡنَ یُقِیۡمُوۡنَ الصَّلٰوۃَ وَ یُؤۡتُوۡنَ  الزَّکٰوۃَ  وَ ہُمۡ  رٰکِعُوۡنَ ﴿۵۵﴾', 'مسلمانو تمہارے دوست تو اللہ اور اسکے پیغمبر اور وہ مومن ہی ہیں جو نماز پڑھتے اور زکوٰۃ دیتے اور اللہ کے آگے جھکتے ہیں۔', 'تمہارا رفیق تو وہی اللہ ہے اور اس کا رسول اور جو ایمان والے ہیں جو کہ قائم ہیں نماز پر اور دیتے ہیں زکوٰۃ اور وہ عاجزی کرنے والے ہیں [۱۷۰]', 'Verily, your Walee (Protector or Helper) is Allah, His Messenger, and the believers, - those who perform As-Salat (Iqamat-as-Salat), and give Zakat, and they bow down (submit themselves with obedience to Allah in prayer).', 'Your only friend is Allah, then His Messenger and those who believe, who establish Salāh and pay Zakāh and bow before Allah.'),
(725, 5, 56, 8, 12, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ مَنۡ یَّتَوَلَّ اللّٰہَ وَ رَسُوۡلَہٗ وَ الَّذِیۡنَ اٰمَنُوۡا فَاِنَّ حِزۡبَ اللّٰہِ ہُمُ الۡغٰلِبُوۡنَ ﴿٪۵۶﴾', 'اور جو شخص اللہ اور اسکے پیغمبر اور مومنوں سے دوستی کرے گا تو وہ اللہ کی جماعت میں سے ہوگا اور اللہ کی جماعت ہی غلبہ پانے والی ہے۔', 'اور جو کوئی دوست رکھے اللہ کو اور اس کے رسول کو اور ایمان والوں کو تو اللہ کی جماعت وہی سب پر غالب ہے [۱۷۱]', 'And whosoever takes Allah, His Messenger, and those who have believed, as Protectors, then the party of Allah will be the victorious.', 'Whoever maintains friendship with Allah and His Messenger and those who believe (must know that) it is the (members of the) Party of Allah that are the triumphant.'),
(726, 5, 57, 9, 13, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا  تَتَّخِذُوا الَّذِیۡنَ اتَّخَذُوۡا دِیۡنَکُمۡ ہُزُوًا وَّ لَعِبًا مِّنَ الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ مِنۡ قَبۡلِکُمۡ وَ الۡکُفَّارَ اَوۡلِیَآءَ ۚ وَ اتَّقُوا  اللّٰہَ  اِنۡ  کُنۡتُمۡ  مُّؤۡمِنِیۡنَ ﴿۵۷﴾', 'اے ایمان والو! جن لوگوں کو تم سے پہلے کتابیں دی گئ تھیں انکو اور کافروں کو جنہوں نے تمہارے دین کو ہنسی اور کھیل بنا رکھا ہے دوست نہ بناؤ اور مومن ہو تو اللہ ہی سے ڈرتے رہو۔', 'اے ایمان والو مت بناؤ ان لوگوں کو جو ٹھہراتے ہیں تمہارے دین کو ہنسی اور کھیل وہ لوگ جو کتاب دیے گئے تم سے پہلے اور نہ کافروں کو [۱۷۲] اپنا دوست اور ڈرو اللہ سے اگر ہو تم ایمان والے [۱۷۳]', 'O you who believe! Take not for Auliya (protectors and helpers) those who take your religion for a mockery and fun from among those who received the Scripture (Jews and Christians) before you, nor from among the disbelievers; and fear Allah if you indeed are true believers.', 'O you who believe, do not take those who have taken your Faith in jest and fun for friends from those who have been given the Book prior to you, and the disbelievers. Fear Allah, if you are believers.'),
(727, 5, 58, 9, 13, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ اِذَا نَادَیۡتُمۡ  اِلَی الصَّلٰوۃِ  اتَّخَذُوۡہَا ہُزُوًا وَّ لَعِبًا ؕ ذٰلِکَ بِاَنَّہُمۡ قَوۡمٌ لَّا یَعۡقِلُوۡنَ ﴿۵۸﴾', 'اور جب تم لوگ نماز کے لئے اذان دیتے ہو تو یہ اسے بھی ہنسی اور کھیل بناتے ہیں یہ اس لئے کہ سمجھ نہیں رکھتے۔', 'اور جب تم پکارتے ہو نماز کے لئے تو وہ ٹھہراتے ہیں اس کو ہنسی اور کھیل یہ اس واسطے کہ وہ لوگ بے عقل ہیں [۱۷۴]', 'And when you proclaim the call for As-Salat (call for the prayer (Adhan)), they take it (but) as a mockery and fun; that is because they are a people who understand not.', 'When you call for Salāh, they take it in jest and fun. That is because they are a people who do not understand'),
(728, 5, 59, 9, 13, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'قُلۡ یٰۤاَہۡلَ الۡکِتٰبِ ہَلۡ تَنۡقِمُوۡنَ مِنَّاۤ اِلَّاۤ اَنۡ اٰمَنَّا بِاللّٰہِ وَ مَاۤ  اُنۡزِلَ اِلَیۡنَا وَ مَاۤ  اُنۡزِلَ مِنۡ قَبۡلُ ۙ وَ اَنَّ  اَکۡثَرَکُمۡ  فٰسِقُوۡنَ ﴿۵۹﴾', 'کہو کہ اے اہل کتاب تم ہم میں برائی ہی کیا دیکھتے ہو سوائے اسکے کہ ہم اللہ پر اور جو کتاب ہم پر نازل ہوئی اس پر اور جو کتابیں پہلے نازل ہوئیں ان سب پر ایمان لائے ہیں۔ اور یہ کہ تم میں اکثر بدکردار ہیں۔', 'تو کہہ اے کتاب والو کیا ضد ہے تم کو ہم سے مگر یہی کہ ہم ایمان لائے اللہ پر اور جو نازل ہوا ہم پر اور جو نازل ہو چکا پہلے اور یہی کہ تم میں اکثر نافرمان ہیں [۱۷۵]', 'Say: \"O people of the Scripture (Jews and Christians)! Do you criticize us for no other reason than that we believe in Allah, and in (the revelation) which has been sent down to us and in that which has been sent down before (us), and that most of you are Fasiqoon (rebellious and disobedient (to Allah))?\"', 'Say, “O People of the Book, do you accuse us of anything else except that we have believed in Allah and in what has been sent down to us and what has been sent down earlier while most of you are sinners (and we do not follow you in your sins)'),
(729, 5, 60, 9, 13, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'قُلۡ ہَلۡ اُنَبِّئُکُمۡ بِشَرٍّ مِّنۡ ذٰلِکَ مَثُوۡبَۃً عِنۡدَ اللّٰہِ ؕ مَنۡ لَّعَنَہُ اللّٰہُ وَ غَضِبَ عَلَیۡہِ وَ جَعَلَ مِنۡہُمُ الۡقِرَدَۃَ  وَ الۡخَنَازِیۡرَ وَ عَبَدَ الطَّاغُوۡتَ ؕ اُولٰٓئِکَ شَرٌّ مَّکَانًا وَّ  اَضَلُّ  عَنۡ  سَوَآءِ السَّبِیۡلِ ﴿۶۰﴾', 'کہو کیا کہ میں تمہیں بتاؤں کہ اللہ کے ہاں اس سے بھی بدتر جزا پانے والے کون ہیں؟ وہ لوگ ہیں جن پر اللہ نے لعنت کی اور جن  پر وہ غضبناک ہوا اور جن کو ان میں سے بندر اور سور بنا دیا اور جنہوں نے شیطان کی پرستش کی ایسے لوگوں کا برا ٹھکانہ ہے اور وہ سیدھے رستے سے بہت دور ہیں۔', 'تو کہہ میں تم کو بتلاؤں ان میں کس کی بری جزا ہے اللہ کے ہاں وہی جس پر اللہ نے لعنت کی اور اس پر غضب نازل کیا اور ان میں سے بعضوں کو بندر کر دیا اور بعضوں کو سور اور جنہوں نے بندگی کی شیطان کی وہی لوگ بدتر ہیں درجہ میں اور بہت بہکے ہوئے ہیں سیدھی راہ سے [۱۷۶]', 'Say (O Muhammad SAW to the people of the Scripture): \"Shall I inform you of something worse than that, regarding the recompense from Allah: those (Jews) who incurred the Curse of Allah and His Wrath, those of whom (some) He transformed into monkeys and swines, those who worshipped Taghoot (false deities); such are worse in rank (on the Day of Resurrection in the Hellfire), and far more astray from the Right Path (in the life of this world).\"', 'Say, “Shall I tell you about the ones whose retribution with Allah is worse than that (which you deem bad)? They are those whom Allah has subjected to His curse and to His wrath; and He has turned some of them into apes and swine, those who worshipped Tāghūt (Satan, the Rebel). Those are worse in their situation, and far more astray from the straight path.”'),
(730, 5, 61, 9, 13, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ اِذَا جَآءُوۡکُمۡ قَالُوۡۤا اٰمَنَّا وَ قَدۡ دَّخَلُوۡا بِالۡکُفۡرِ  وَ ہُمۡ  قَدۡ خَرَجُوۡا بِہٖ ؕ وَ اللّٰہُ  اَعۡلَمُ  بِمَا کَانُوۡا یَکۡتُمُوۡنَ ﴿۶۱﴾', 'اور جب یہ لوگ تمہارے پاس آتے ہیں تو کہتے ہیں کہ ہم ایمان لے آئے حالانکہ کفر لے کر آتے ہیں اور اسی کو لے کر جاتے ہیں۔ اور جن باتوں کو یہ چھپاتے ہیں ہیں اللہ انکو خوب جانتا ہے۔', 'اور جب تمہارے پاس آتے ہیں تو کہتے ہیں ہم ایمان لائے اور حالت یہ ہے کہ کافر ہی آئے تھے اور کافر ہی چلے گئے اور اللہ خوب جانتا ہے جو کچھ چھپائے ہوئے تھے [۱۷۷]', 'When they come to you, they say: \"We believe.\" But in fact they enter with (an intention of) disbelief and they go out with the same. And Allah knows all what they were hiding.', 'When they come to you, they say, “We believe”, while with disbelief they came in, and with the same (disbelief) they went out. Allah knows best what they used to conceal.'),
(731, 5, 62, 9, 13, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ تَرٰی کَثِیۡرًا مِّنۡہُمۡ یُسَارِعُوۡنَ فِی الۡاِثۡمِ وَ الۡعُدۡوَانِ وَ اَکۡلِہِمُ السُّحۡتَ ؕ لَبِئۡسَ مَا کَانُوۡا یَعۡمَلُوۡنَ ﴿۶۲﴾', 'اور تم دیکھو گے کہ ان میں اکثر گناہ اور زیادتی اور حرام کھانے میں جلدی کر رہے ہیں۔ بیشک یہ جو کچھ کرتے ہیں برا کرتے ہیں۔', 'اور تو دیکھے گا بہتوں کو ان میں سے کہ دوڑتے ہیں گناہ پر اور ظلم اور حرام کھانے پر بہت  برے کام ہیں جو کر رہے ہیں [۱۷۸]', 'And you see many of them (Jews) hurrying for sin and transgression, and eating illegal things (as bribes and Riba (usury), etc.). Evil indeed is that which they have been doing.', 'You will see many of them rushing towards sin and aggression, and (towards) devouring what is unlawful. Evil indeed is what they have been doing.'),
(732, 5, 63, 9, 13, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'لَوۡ لَا یَنۡہٰہُمُ الرَّبّٰنِیُّوۡنَ وَ الۡاَحۡبَارُ عَنۡ قَوۡلِہِمُ الۡاِثۡمَ وَ اَکۡلِہِمُ السُّحۡتَ ؕ لَبِئۡسَ مَا  کَانُوۡا  یَصۡنَعُوۡنَ ﴿۶۳﴾', 'بھلا ان کے مشائخ اور علماء انہیں گناہ کی باتیں کہنے اور حرام کھانے سے منع کیوں نہیں کرتے؟ بلاشبہ وہ بھی برا کرتے ہیں۔', 'کیوں نہیں منع کرتے انکے درویش اور علماء گناہ کی بات کہنے سے اور حرام کھانے سے بہت ہی برے عمل ہیں جو کر رہے ہیں [۱۷۹]', 'Why do not the rabbis and the religious learned men forbid them from uttering sinful words and from eating illegal things. Evil indeed is that which they have been performing.', 'Why do the Men of Allah and the Men of Knowledge not forbid them from saying what is sinful and devouring what is unlawful? Evil indeed is what they have been working.'),
(733, 5, 64, 9, 13, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ قَالَتِ الۡیَہُوۡدُ یَدُ اللّٰہِ مَغۡلُوۡلَۃٌ ؕ غُلَّتۡ اَیۡدِیۡہِمۡ وَ لُعِنُوۡا بِمَا قَالُوۡا ۘ بَلۡ یَدٰہُ مَبۡسُوۡطَتٰنِ ۙ یُنۡفِقُ  کَیۡفَ یَشَآءُ ؕ وَ لَیَزِیۡدَنَّ کَثِیۡرًا مِّنۡہُمۡ مَّاۤ  اُنۡزِلَ  اِلَیۡکَ مِنۡ رَّبِّکَ طُغۡیَانًا وَّ کُفۡرًا ؕ وَ اَلۡقَیۡنَا بَیۡنَہُمُ الۡعَدَاوَۃَ وَ الۡبَغۡضَآءَ  اِلٰی یَوۡمِ الۡقِیٰمَۃِ ؕ کُلَّمَاۤ  اَوۡقَدُوۡا  نَارًا لِّلۡحَرۡبِ اَطۡفَاَہَا اللّٰہُ ۙ وَ یَسۡعَوۡنَ فِی الۡاَرۡضِ فَسَادًا ؕ وَ اللّٰہُ  لَا یُحِبُّ الۡمُفۡسِدِیۡنَ ﴿۶۴﴾', 'اور یہود کہتے ہیں کہ اللہ کا ہاتھ بندھا ہوا ہے یعنی اللہ بخیل ہے انہیں کے ہاتھ باندھے جائیں اور ایسا کہنے کے سبب ان پر لعنت ہو اصل یہ ہے کہ اسکے دونوں ہاتھ کھلے ہیں۔ وہ جس طرح اور جتنا چاہتا ہے خرچ کرتا ہے اور اے نبی یہ کتاب جو تمہارے پروردگار کی طرف سے تم پر نازل ہوئی اس سے ان میں سے اکثر کی شرارت اور انکار اور بڑھے گا۔ اور ہم نے ان کے درمیان عداوت اور دشمنی قیامت کے دن تک ڈال دی ہے۔ جب کبھی انہوں نے لڑائی کی آگ جلائی اللہ نے اسکو بھجا دیا۔ اور یہ ملک میں فساد کے لئے دوڑتے پھرتے ہیں۔ اور اللہ فساد کرنے والوں کو دوست نہیں رکھتا۔', 'اور یہود کہتے ہیں اللہ کا ہاتھ بند ہو گیا [۱۸۰] انہی کے ہاتھ بند ہو جاویں [۱۸۱] اور لعنت ہےانکو اس کہنے پر بلکہ اس کے تو دونوں ہاتھ کھلے ہوئے ہیں [۱۸۲] خرچ کرتا ہے جس طرح چاہے [۱۸۳] اور ان میں بہتوں کو بڑھے گی اس کلام سے جو تجھ پر اترا تیرے رب کی طرف سے شرارت اور انکار [۱۸۴] اور ہم نے ڈال رکھی ہے ان میں دشمنی اور بیر قیامت کے دن تک [۱۸۵] جب کبھی آگ سلگاتے ہیں لڑائی کے لئے اللہ اس کو بجھا دیتا ہے اور دوڑتے ہیں ملک میں فساد کرتے ہوئے اور اللہ پسند نہیں کرتا فساد کرنے والوں کو [۱۸۶]', 'The Jews say: \"Allahs Hand is tied up (i.e. He does not give and spend of His Bounty).\" Be their hands tied up and be they accursed for what they uttered. Nay, both His Hands are widely outstretched. He spends (of His Bounty) as He wills. Verily, the Revelation that has come to you from Allah increases in most of them their obstinate rebellion and disbelief. We have put enmity and hatred amongst them till the Day of Resurrection. Every time they kindled the fire of war, Allah extinguished it; and they (ever) strive to make mischief on earth. And Allah does not like the Mufsidoon (mischiefmakers).', 'The Jews said, “Allah’s hand is fettered.” Fettered are their own hands, and cursed are they for what they said. In fact, His hands are outspread. He spends as He wills. What has been sent down to you from your Lord shall certainly increase many of them in rebellion and disbelief. We have put enmity and hatred amongst them lasting to the Day of Doom. Whenever they lit the flame of war, Allah puts it out. They run about on the earth spreading mischief, and Allah does not like the mischief-makers.'),
(734, 5, 65, 9, 13, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ لَوۡ  اَنَّ  اَہۡلَ الۡکِتٰبِ اٰمَنُوۡا وَ اتَّقَوۡا لَکَفَّرۡنَا عَنۡہُمۡ سَیِّاٰتِہِمۡ وَ لَاَدۡخَلۡنٰہُمۡ  جَنّٰتِ النَّعِیۡمِ ﴿۶۵﴾', 'اور اگر اہل کتاب ایمان لاتے اور پرہیزگاری کرتے تو ہم ان سے ان کے گناہ دور کر دیتے اور انکو نعمت کے باغوں میں داخل کرتے۔', 'اور اگر اہل کتاب ایمان لاتے اور ڈرتے تو ہم دور کر دیتے ان سے ان کی برائیاں اور ان کو داخل کرتے نعمت کے باغوں میں [۱۸۷]', 'And if only the people of the Scripture (Jews and Christians) had believed (in Muhammad SAW) and warded off evil (sin, ascribing partners to Allah) and had become AlMuttaqoon (the pious - see V.2:2) We would indeed have blotted out their sins and admitted them to Gardens of pleasure (in Paradise).', 'If the People of the Book had believed and feared Allah, We would have written off their evil deeds and would have surely admitted them to the Gardens of Bliss.'),
(735, 5, 66, 9, 13, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ لَوۡ اَنَّہُمۡ اَقَامُوا التَّوۡرٰىۃَ وَ الۡاِنۡجِیۡلَ وَ مَاۤ  اُنۡزِلَ اِلَیۡہِمۡ  مِّنۡ رَّبِّہِمۡ لَاَکَلُوۡا مِنۡ فَوۡقِہِمۡ وَ مِنۡ تَحۡتِ اَرۡجُلِہِمۡ ؕ مِنۡہُمۡ اُمَّۃٌ  مُّقۡتَصِدَۃٌ ؕ وَ کَثِیۡرٌ  مِّنۡہُمۡ سَآءَ مَا یَعۡمَلُوۡنَ ﴿٪۶۶﴾', 'اور اگر وہ تورات اور انجیل کو اور جو اور کتابیں ان کے پروردگار کی طرف سے ان پر نازل ہوئیں ان کو قائم کرتے تو ان پر رزق مینہ کی طرح برستا کہ اپنے اوپر سے اور پاؤں کے نیچے سے کھاتے۔ ان میں کچھ لوگ میانہ رو ہیں اور بہت سے ایسے ہیں جن کے اعمال برے ہیں۔', 'اور اگر وہ قائم رکھتے توریت اور انجیل کو اور اس کو جو کہ نازل ہوا ان پر انکے رب کی طرف سے [۱۸۸] تو کھاتے اپنے اوپر سے اور اپنے پاؤں کے نیچے سے [۱۸۹] کچھ لوگ ان میں ہیں سیدھی راہ پر [۱۹۰] اور بہت سے ان میں برے کام کر رہے ہیں', 'And if only they had acted according to the Taurat (Torah), the Injeel (Gospel), and what has (now) been sent down to them from their Lord (the Quran), they would surely have gotten provision from above them and from underneath their feet. There are from among them people who are on the right course (i.e. they act on the revelation and believe in Prophet Muhammad SAW like Abdullah bin Salam ÑÖì ), but many of them do evil deeds.', 'If they had upheld the Torah and the Injīl and what had been sent down to them from their Lord, they would surely have had plenty to eat from above them and from beneath them. Among them are moderate people. As for most of them, evil is what they do.'),
(736, 5, 67, 10, 14, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'یٰۤاَیُّہَا الرَّسُوۡلُ بَلِّغۡ  مَاۤ اُنۡزِلَ اِلَیۡکَ  مِنۡ رَّبِّکَ ؕ وَ  اِنۡ لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَہٗ ؕ وَ اللّٰہُ یَعۡصِمُکَ مِنَ النَّاسِ ؕ اِنَّ اللّٰہَ  لَا یَہۡدِی الۡقَوۡمَ الۡکٰفِرِیۡنَ ﴿۶۷﴾', 'اے پیغمبر جو ارشادات اللہ کی طرف سے تم پر نازل ہوئے ہیں سب لوگوں کو پہنچا دو۔ اور اگر ایسا نہ کیا تو تم اللہ کے پیغام پہنچانے میں قاصر رہے اور اللہ تم کو لوگوں سے بچائے رکھے گا۔ بیشک اللہ منکروں کو ہدایت نہیں کرتا۔', 'اے رسول پہنچا دے جو تجھ پر اترا تیرے رب کی طرف سے اور اگر ایسا نہ کیا تو تو نے کچھ نہ پہنچایا اس کا پیغام اور اللہ تجھ کو بچا لے گا لوگوں سے بیشک اللہ راستہ نہیں دکھلاتا قوم کفار کو [۱۹۱]', 'O Messenger (Muhammad SAW)! Proclaim (the Message) which has been sent down to you from your Lord. And if you do not, then you have not conveyed His Message. Allah will protect you from mankind. Verily, Allah guides not the people who disbelieve.', 'O Messenger, convey all that has been sent down to you from your Lord. If you do not, then you shall not have conveyed His message (at all). Allah shall protect you from the people. Surely, Allah does not lead the disbelieving people to the right path.'),
(737, 5, 68, 10, 14, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'قُلۡ یٰۤاَہۡلَ الۡکِتٰبِ لَسۡتُمۡ عَلٰی شَیۡءٍ حَتّٰی تُقِیۡمُوا التَّوۡرٰىۃَ وَ الۡاِنۡجِیۡلَ وَ مَاۤ  اُنۡزِلَ اِلَیۡکُمۡ مِّنۡ رَّبِّکُمۡ ؕ وَ لَیَزِیۡدَنَّ  کَثِیۡرًا مِّنۡہُمۡ مَّاۤ  اُنۡزِلَ  اِلَیۡکَ مِنۡ رَّبِّکَ طُغۡیَانًا وَّ کُفۡرًا ۚ فَلَا تَاۡسَ عَلَی الۡقَوۡمِ  الۡکٰفِرِیۡنَ ﴿۶۸﴾', 'کہو کہ اے اہل کتاب جب تک تم تورات اور انجیل کو اور جو اور کتابیں تمہارے پروردگار کی طرف سے تم لوگوں پر نازل ہوئیں انکو قائم نہ رکھو گے کسی بھی راہ پر نہیں ہو سکتے اور یہ قرآن جو تمہارے پروردگار کی طرف سے تم پر نازل ہوا ہے اس سے ان میں سے اکثر کی سرکشی اور کفر اور بڑھے گا تو تم قوم کفار پر افسوس نہ کرو۔', 'کہہ دے اے کتاب والو تم کسی راہ پر نہیں جب تک نہ قائم کرو توریت اور انجیل کو اور جو تم پر اترا تمہارےرب کی طرف سے [۱۹۲] اور ان میں بہتوں کو بڑھے گی اس کلام سے جو تجھ پر اترا تیرے رب کی طرف سے شرارت اور کفر سو تو افسوس نہ کر اس قوم کفار پر [۱۹۳]', 'Say (O Muhammad SAW) \"O people of the Scripture (Jews and Christians)! You have nothing (as regards guidance) till you act according to the Taurat (Torah), the Injeel (Gospel), and what has (now) been sent down to you from your Lord (the Quran).\" Verily, that which has been sent down to you (Muhammad SAW) from your Lord increases in many of them their obstinate rebellion and disbelief. So be not sorrowful over the people who disbelieve.', 'Say, “O people of the Book, you have nothing to stand on, unless you uphold the Torah and the Injīl and what has been sent down to you from your Lord.” What has been sent down to you from your Lord will certainly make many of them more persistent in rebellion and disbelief. So, do not grieve over the disbelieving people.'),
(738, 5, 69, 10, 14, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'اِنَّ الَّذِیۡنَ اٰمَنُوۡا وَ الَّذِیۡنَ ہَادُوۡا وَ الصّٰبِـُٔوۡنَ وَ النَّصٰرٰی مَنۡ اٰمَنَ بِاللّٰہِ وَ الۡیَوۡمِ الۡاٰخِرِ  وَ عَمِلَ صَالِحًا فَلَا خَوۡفٌ عَلَیۡہِمۡ  وَ لَا  ہُمۡ  یَحۡزَنُوۡنَ ﴿۶۹﴾', 'جو لوگ اللہ پر اور روز آخر پر ایمان لائیں اور عمل نیک کریں خواہ وہ مسلمان ہوں یا یہودی یا ستارہ پرست یا عیسائی ان کو قیامت کے دن نہ کچھ خوف ہو گا اور نہ وہ غمناک ہوں گے۔', 'بیشک جو مسلمان ہیں اور جو یہودی ہیں اور فرقہ صابی اور نصاریٰ جو کوئی ایمان لاوے اللہ پر اور روز قیامت پر اور عمل کرے نیک نہ ان پر ڈر ہے نہ وہ غمگین ہوں گے [۱۹۴]', 'Surely, those who believe (in the Oneness of Allah, in His Messenger Muhammad SAW and all that was revealed to him from Allah), those who are the Jews and the Sabians and the Christians, - whosoever believed in Allah and the Last Day, and worked righteousness, on them shall be no fear, nor shall they grieve.', 'Surely, those who believe, and those who are Jews, and the Sabians, and the Christians - whoever believes in Allah and the Last Day, and acts righteously, shall have no fear, nor shall such people grieve.'),
(739, 5, 70, 10, 14, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'لَقَدۡ اَخَذۡنَا مِیۡثَاقَ بَنِیۡۤ  اِسۡرَآءِیۡلَ وَ اَرۡسَلۡنَاۤ  اِلَیۡہِمۡ رُسُلًا ؕ کُلَّمَا جَآءَہُمۡ رَسُوۡلٌۢ بِمَا لَا تَہۡوٰۤی اَنۡفُسُہُمۡ ۙ فَرِیۡقًا کَذَّبُوۡا وَ فَرِیۡقًا یَّقۡتُلُوۡنَ ﴿٭۷۰﴾', 'ہم نے بنی اسرائیل سے عہد بھی لیا اور انکی طرف پیغمبر بھی بھیجے لیکن جب کوئی پیغمبر انکے پاس ایسی باتیں لے کر آتا جنکو ان کے دل نہیں چاہتے تھے تو وہ انبیاء کی ایک جماعت کو تو جھٹلا دیتے اور ایک جماعت کو قتل کر دیتے تھے۔', 'ہم نے لیا تھا پختہ قول بنی اسرائیل سے [۱۹۵] اور بھیجے ان کی طرف رسول جب لایا ان کے پاس کوئی رسول وہ حکم جو خوش نہ آیا ان کے جی کو تو بہتوں کو جھٹلایا اور بہتوں کو قتل کر ڈالتےتھے [۱۹۶]', 'Verily, We took the covenant of the Children of Israel and sent them Messengers. Whenever there came to them a Messenger with what they themselves desired not - a group of them they called liars, and others among them they killed.', 'Certainly We took a pledge from the children of Isrā’īl and sent Messengers to them. Whenever a Messenger went to them with what did not meet their desires, they cried lie to some, and killed others.'),
(740, 5, 71, 10, 14, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ حَسِبُوۡۤا اَلَّا تَکُوۡنَ فِتۡنَۃٌ فَعَمُوۡا وَ صَمُّوۡا ثُمَّ تَابَ اللّٰہُ عَلَیۡہِمۡ ثُمَّ عَمُوۡا وَ صَمُّوۡا کَثِیۡرٌ مِّنۡہُمۡ ؕ وَ اللّٰہُ بَصِیۡرٌۢ بِمَا یَعۡمَلُوۡنَ ﴿۷۱﴾', 'اور یہ خیال کرتے تھے کہ اس سے ان پر کوئی آفت نہیں آنے کی تو وہ اندھے اور بہرے ہو گئے پھر اللہ نے ان پر مہربانی فرمائی لیکن پھر ان میں سے بہت سے اندھے اور بہرے ہو گئے۔ اور اللہ انکے سب کاموں کو دیکھ رہا ہے۔', 'اور خیال کیا کہ کچھ خرابی نہ ہو گی سو وہ اندھے ہو گئے اور بہرے پھر توبہ قبول کی اللہ نے ان کی پھر اندھے اور بہرے ہوئے ان میں سےبہت [۱۹۷] اور اللہ دیکھتا ہے جو کچھ وہ کرتے ہیں [۱۹۸]', 'They thought there will be no Fitnah (trial or punishment), so they became blind and deaf; after that Allah turned to them (with Forgiveness); yet again many of them became blind and deaf. And Allah is the AllSeer of what they do.', 'They thought that no harm would follow. Therefore, they became blind and deaf. Then, Allah accepted their repentance, but again they turned blind and deaf, many of them. Allah is watchful of what they do.'),
(741, 5, 72, 10, 14, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'لَقَدۡ کَفَرَ الَّذِیۡنَ قَالُوۡۤا اِنَّ اللّٰہَ ہُوَ الۡمَسِیۡحُ ابۡنُ مَرۡیَمَ ؕ وَ قَالَ الۡمَسِیۡحُ یٰبَنِیۡۤ  اِسۡرَآءِیۡلَ اعۡبُدُوا اللّٰہَ رَبِّیۡ وَ رَبَّکُمۡ ؕ اِنَّہٗ مَنۡ یُّشۡرِکۡ بِاللّٰہِ فَقَدۡ حَرَّمَ اللّٰہُ عَلَیۡہِ الۡجَنَّۃَ وَ مَاۡوٰىہُ النَّارُ ؕ وَ مَا لِلظّٰلِمِیۡنَ مِنۡ اَنۡصَارٍ ﴿۷۲﴾', 'وہ لوگ بے شبہ کافر ہیں جو کہتے ہیں کہ اللہ مسیح ابن مریم ہی تو ہے۔ حالانکہ مسیح یہود سے یہ کہا کرتے تھے کہ اے بنی اسرائیل اللہ ہی کی عبادت کرو جو میرا بھی پروردگار ہے اور تمہارا بھی اور جان رکھو کہ جو شخص اللہ کے ساتھ شرک کرے گا۔ اللہ اس پر بہشت کو حرام کر دے گا۔ اور اس کا ٹھکانہ دوزخ ہے اور ظالموں کا کوئی مددگار نہیں ہو گا۔', 'بیشک کافر ہوئے جنہوں نے کہا اللہ وہی مسیح ہے مریم کا بیٹا اور میسح نے کہا ہے کہ اے بنی اسرائیل بندگی کرو اللہ کی رب ہے میرا اور تمہارا بیشک جس نے شریک ٹھہرایا اللہ کا سو حرام کی اللہ نے اس پر جنت اور اس کا ٹھکانہ دوزخ ہے اور کوئی نہیں گنہگاروں کی مدد کرنے والا [۱۹۹]', 'Surely, they have disbelieved who say: \"Allah is the Messiah (Iesa (Jesus)), son of Maryam (Mary).\" But the Messiah (Iesa (Jesus)) said: \"O Children of Israel! Worship Allah, my Lord and your Lord.\" Verily, whosoever sets up partners in worship with Allah, then Allah has forbidden Paradise for him, and the Fire will be his abode. And for the Zalimoon (polytheists and wrongdoers) there are no helpers.', 'Surely, disbelievers are those who say, “Allah is the MasīH, son of Maryam” while the MasīH had said, “O children of Isrā’īl , worship Allah, my Lord and your Lord.” In fact, whoever ascribes any partner to Allah, Allah has prohibited for him the Jannah (the Paradise), and his shelter is the Fire, and there will be no supporters for the unjust.'),
(742, 5, 73, 10, 14, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'لَقَدۡ کَفَرَ الَّذِیۡنَ قَالُوۡۤا اِنَّ اللّٰہَ ثَالِثُ ثَلٰثَۃٍ ۘ وَ مَا مِنۡ  اِلٰہٍ  اِلَّاۤ اِلٰہٌ  وَّاحِدٌ ؕ وَ اِنۡ لَّمۡ یَنۡتَہُوۡا عَمَّا یَقُوۡلُوۡنَ لَیَمَسَّنَّ الَّذِیۡنَ  کَفَرُوۡا مِنۡہُمۡ  عَذَابٌ اَلِیۡمٌ ﴿۷۳﴾', 'وہ لوگ بھی کافر ہیں جو اس بات کے قائل ہیں کہ اللہ تین میں کا تیسرا ہے۔ حالانکہ اس معبود یکتا کے سوا کوئی عبادت کے لائق نہیں۔ اگر یہ لوگ ایسے اقوال و عقائد سے باز نہیں آئیں گے تو ان میں جو کافر ہوئے ہیں وہ تکلیف دینے والا عذاب پائیں گے۔', 'بیشک کافر ہوئے جنہوں نے کہا اللہ ہے تین میں کا ایک [۲۰۰] حالانکہ کوئی معبود نہیں بجز ایک معبود کے اور اگر نہ باز آویں گے اس بات سے کہ کہتے ہیں تو بیشک پہنچے گا ان میں سےکفر پر قائم رہنے والوں کو عذاب دردناک', 'Surely, disbelievers are those who said: \"Allah is the third of the three (in a Trinity).\" But there is no ilah (god) (none who has the right to be worshipped) but One Ilah (God -Allah). And if they cease not from what they say, verily, a painful torment will befall the disbelievers among them.', 'Surely, disbelievers are those who say, “Allah is the third of the three” while there is no god but One God. If they do not desist from what they say, a painful punishment shall certainly befall such disbelievers.'),
(743, 5, 74, 10, 14, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'اَفَلَا یَتُوۡبُوۡنَ اِلَی اللّٰہِ وَ یَسۡتَغۡفِرُوۡنَہٗ ؕ وَ اللّٰہُ غَفُوۡرٌ  رَّحِیۡمٌ ﴿۷۴﴾', 'تو یہ کیوں اللہ کے آگے توبہ نہیں کرتے اور اس سے گناہوں کی معافی نہیں مانگتے اور اللہ تو بخشنے والا ہے مہربان ہے۔', 'کیوں نہیں توبہ کرتے اللہ کے آگے اور گناہ بخشواتے اس سے اور اللہ ہے بخشنے والا مہربان [۲۰۱]', 'Will they not repent to Allah and ask His Forgiveness? For Allah is OftForgiving, Most Merciful.', 'Why then do they not turn to Allah in repentance and seek His forgiveness, while Allah is most forgiving, very merciful?'),
(744, 5, 75, 10, 14, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'مَا الۡمَسِیۡحُ ابۡنُ مَرۡیَمَ  اِلَّا رَسُوۡلٌ ۚ قَدۡ خَلَتۡ مِنۡ قَبۡلِہِ الرُّسُلُ ؕ وَ اُمُّہٗ صِدِّیۡقَۃٌ ؕ کَانَا یَاۡکُلٰنِ الطَّعَامَ ؕ اُنۡظُرۡ کَیۡفَ نُبَیِّنُ لَہُمُ الۡاٰیٰتِ ثُمَّ انۡظُرۡ اَنّٰی یُؤۡفَکُوۡنَ ﴿۷۵﴾', 'مسیح ابن مریم تو ایک پیغمبر ہی تھے۔ ان سے پہلے بھی بہت سے رسول گذر چکے تھے اور انکی والدہ مریم اللہ کی ولی اور سچی فرمانبردار تھیں۔ دونوں انسان تھے اور کھانا بھی کھاتے تھے دیکھو ہم ان لوگوں کے لئے اپنی آیتیں کس طرح کھول کھول کر بیان کرتے ہیں پھر یہ دیکھو کہ یہ کدھر الٹے جا رہے ہیں۔', 'نہیں ہے مسیح مریم کا بیٹا مگر رسول گذر چکے اس سے پہلے بہت رسول [۲۰۲] اور اسکی ماں ولی ہے [۲۰۳] دونوں کھاتےتھے کھانا دیکھ ہم کیسے بتلاتے ہیں ان کو دلیلیں پھر دیکھ وہ کہاں الٹے جارہے ہیں [۲۰۴]', 'The Messiah (Iesa (Jesus)), son of Maryam (Mary), was no more than a Messenger; many were the Messengers that passed away before him. His mother (Maryam (Mary)) was a Siddiqah (i.e. she believed in the words of Allah and His Books (see Verse 66:12)). They both used to eat food (as any other human being, while Allah does not eat). Look how We make the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) clear to them, yet look how they are deluded away (from the truth).', 'The MasīH, son of Maryam, is no more than a Messenger. There have been messengers before him. His mother was very truthful. Both of them used to eat food. Look how We explain signs to them, then see how far they are turned away.'),
(745, 5, 76, 10, 14, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'قُلۡ اَتَعۡبُدُوۡنَ مِنۡ دُوۡنِ اللّٰہِ مَا لَا یَمۡلِکُ لَکُمۡ ضَرًّا وَّ لَا  نَفۡعًا ؕ وَ اللّٰہُ ہُوَ  السَّمِیۡعُ  الۡعَلِیۡمُ ﴿۷۶﴾', 'کہو کہ تم اللہ کے سوا ایسی چیز کی کیوں پرستش کرتے ہو جسکو تمہارے نفع اور نقصان کا کچھ بھی اختیار نہیں اور اللہ ہی سب کچھ سنتا ہے جانتا ہے۔', 'تو کہہ دے کیا تم ایسی چیز کی بندگی کرتے ہو اللہ کو چھوڑ کر جو مالک نہیں تمہارے برے کی اور نہ بھلے کی اور اللہ وہی ہے سننے والا جاننے والا [۲۰۵]', 'Say (O Muhammad SAW to mankind): \"How do you worship besides Allah something which has no power either to harm or to benefit you? But it is Allah Who is the AllHearer, AllKnower.\"', 'Say, “Do you worship, besides Allah, what has no power to do you harm or bring you benefit?” Allah is the All-Hearing, the All-Knowing.'),
(746, 5, 77, 10, 14, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'قُلۡ یٰۤاَہۡلَ الۡکِتٰبِ لَا تَغۡلُوۡا فِیۡ دِیۡنِکُمۡ غَیۡرَ  الۡحَقِّ وَ لَا  تَتَّبِعُوۡۤا اَہۡوَآءَ قَوۡمٍ قَدۡ ضَلُّوۡا مِنۡ قَبۡلُ وَ اَضَلُّوۡا کَثِیۡرًا وَّ ضَلُّوۡا عَنۡ سَوَآءِ السَّبِیۡلِ ﴿٪۷۷﴾', 'کہو کہ اے اہل کتاب اپنے دین کی بات میں ناحق مبالغہ نہ کرو اور ایسے لوگوں کی خواہشوں کے پیچھے نہ چلو جو خود بھی پہلے گمراہ ہوئے اور بھی اکثروں کو گمراہ کر گئے اور سیدھے رستے سے بھٹک گئے۔', 'تو کہہ اے اہل کتاب مت مبالغہ کرو اپنے دین کی بات میں ناحق کا [۲۰۶] اور مت چلو خیالات پر ان لوگوں کے جو گمراہ ہو چکے پہلے اور گمراہ کر گئے بہتوں کو اور بہک گئے سیدھی راہ سے [۲۰۷]', 'Say (O Muhammad SAW): \"O people of the Scripture (Jews and Christians)! Exceed not the limits in your religion (by believing in something) other than the truth, and do not follow the vain desires of people who went astray in times gone by, and who misled many, and strayed (themselves) from the Right Path.\"', 'Say, O people of the Book, be not excessive in your religion unjustly, and do not follow the desires of a people who have already gone astray, misled many and lost the right path.'),
(747, 5, 78, 11, 0, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'لُعِنَ الَّذِیۡنَ کَفَرُوۡا مِنۡۢ بَنِیۡۤ  اِسۡرَآءِیۡلَ عَلٰی لِسَانِ دَاوٗدَ  وَ عِیۡسَی ابۡنِ مَرۡیَمَ ؕ ذٰلِکَ بِمَا عَصَوۡا وَّ کَانُوۡا یَعۡتَدُوۡنَ ﴿۷۸﴾', 'جو لوگ بنی اسرائیل میں کافر ہوئے ان پر داؤد اور عیسٰی ابن مریم کی زبان سے لعنت کی گئ۔ یہ اس لئے کہ نافرمانی کرتے تھے اور حد سے تجاوز کئے جاتے تھے۔', 'ملعون ہوئے کافر بنی اسرائیل میں کے داؤد کی زبان پر اور عیسٰی بیٹے مریم کے یہ اس لئے کہ وہ نافرمان تھے اور حد سے گذر گئےتھے [۲۰۸]', 'Those among the Children of Israel who disbelieved were cursed by the tongue of Dawood (David) and Iesa (Jesus), son of Maryam (Mary). That was because they disobeyed (Allah and the Messengers) and were ever transgressing beyond bounds.', 'On those who disbelieve from among the children of Isrā’īl , a curse was pronounced by Dawūd and ‘Īsā, Son of Maryam. All this because they disobeyed and used to cross the limits'),
(748, 5, 79, 11, 0, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'کَانُوۡا لَا یَتَنَاہَوۡنَ عَنۡ مُّنۡکَرٍ فَعَلُوۡہُ ؕ لَبِئۡسَ مَا کَانُوۡا یَفۡعَلُوۡنَ ﴿۷۹﴾', 'اور برے کاموں سے جو وہ کرتے تھے ایک دوسرے کو روکتے نہیں تھے۔ بلاشبہ وہ برا کرتے تھے۔', 'آپس میں منع نہ کرتے برے کام سے جو وہ کر رہے تھے [۲۰۹] کیا ہی برا کام ہے جو کرتے تھے', 'They used not to forbid one another from the Munkar (wrong, evildoing, sins, polytheism, disbelief, etc.) which they committed. Vile indeed was what they used to do.', 'They did not forbid each other from any evil they committed. Evil indeed is what they have been doing.'),
(749, 5, 80, 11, 0, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'تَرٰی کَثِیۡرًا مِّنۡہُمۡ یَتَوَلَّوۡنَ الَّذِیۡنَ کَفَرُوۡا ؕ لَبِئۡسَ مَا قَدَّمَتۡ لَہُمۡ اَنۡفُسُہُمۡ اَنۡ سَخِطَ اللّٰہُ عَلَیۡہِمۡ وَ فِی الۡعَذَابِ ہُمۡ خٰلِدُوۡنَ ﴿۸۰﴾', 'تم ان میں سے بہتوں کو دیکھو گے کہ کافروں سے دوستی رکھتے ہیں۔ انہوں نے جو کچھ آگے بھیجا ہے برا ہے۔ وہ یہ کہ اللہ ان سے ناخوش ہوا اور وہ ہمیشہ عذاب میں مبتلا رہیں گے۔', 'تو دیکھتا ہے ان میں کہ بہت سے لوگ دوستی کرتے ہیں کافروں سے [۲۱۰] کیا ہی برا سامان بھیجا انہوں نے اپنے واسطے وہ یہ کہ اللہ کا غضب ہوا ان پر اور وہ ہمیشہ عذاب میں رہنے والے ہیں [۲۱۱]', 'You see many of them taking the disbelievers as their Auliya (protectors and helpers). Evil indeed is that which their ownselves have sent forward before them, for that (reason) Allahs Wrath fell upon them and in torment they will abide.', 'You see many of them take the infidels (the pagans) for friends. Indeed, evil is what they have sent ahead for themselves, for Allah is angry with them, and they are to remain in torment for ever.'),
(750, 5, 81, 11, 0, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'وَ لَوۡ کَانُوۡا یُؤۡمِنُوۡنَ بِاللّٰہِ وَ النَّبِیِّ  وَ مَاۤ اُنۡزِلَ اِلَیۡہِ مَا اتَّخَذُوۡہُمۡ اَوۡلِیَآءَ وَ لٰکِنَّ  کَثِیۡرًا  مِّنۡہُمۡ  فٰسِقُوۡنَ ﴿۸۱﴾', 'اور اگر وہ اللہ پر اور پیغمبر پر اور جو کتاب ان پر نازل ہوئی تھی اس پر یقین رکھتے تو ان لوگوں کو دوست نہ بناتے لیکن ان میں اکثر بدکردار ہیں۔', 'اور اگر وہ یقین رکھتے اللہ پر اور نبی پر اور جو نبی پر اترا تو کافروں کو دوست نہ بناتے [۲۱۲] لیکن ان میں بہت سے لوگ نافرمان ہیں [۲۱۳]', 'And had they believed in Allah, and in the Prophet (Muhammad SAW) and in what has been revealed to him, never would they have taken them (the disbelievers) as Auliya (protectors and helpers), but many of them are the Fasiqoon (rebellious, disobedient to Allah).', 'If they believed in Allah, in the prophet, and in what had been sent down to him, they would have not taken them (the pagans) for friends, but many of them are sinners.'),
(751, 5, 82, 11, 0, 6, 'لَا یُحِبُّ اللّٰہُ ', 'المآئدۃ', 'لَتَجِدَنَّ اَشَدَّ النَّاسِ عَدَاوَۃً لِّلَّذِیۡنَ اٰمَنُوا الۡیَہُوۡدَ وَ الَّذِیۡنَ اَشۡرَکُوۡا ۚ وَ لَتَجِدَنَّ  اَقۡرَبَہُمۡ مَّوَدَّۃً  لِّلَّذِیۡنَ اٰمَنُوا الَّذِیۡنَ قَالُوۡۤا اِنَّا نَصٰرٰی ؕ ذٰلِکَ بِاَنَّ مِنۡہُمۡ قِسِّیۡسِیۡنَ وَ رُہۡبَانًا وَّ اَنَّہُمۡ لَا یَسۡتَکۡبِرُوۡنَ ﴿۸۲﴾', 'اے پیغمبر تم دیکھو گے کہ مومنوں کے ساتھ سب سے زیادہ دشمنی کرنے والے یہودی اور مشرک ہیں۔ اور دوستی کے لحاظ سے مومنوں سے قریب تر ان لوگوں کو پاؤ گے جو کہتے ہیں کہ ہم نصارٰی ہیں۔ یہ اس لئے کہ ان میں عالم بھی ہیں اور مشائخ بھی اور یہ کہ یہ تکبر نہیں کرتے۔', 'تو پاوے گا سب لگوں سے زیادہ دشمن مسلمانوں کا یہودیوں کو اور مشرکوں کو اور تو پاوے گا سب سے نزدیک محبت میں مسلمانوں کے ان لوگوں کو جو کہتے ہیں کہ ہم نصاریٰ ہیں یہ اس واسطے کہ نصاریٰ میں عالم ہیں اور درویش ہیں اور اس واسطے کہ وہ تکبر نہیں کرتے', 'Verily, you will find the strongest among men in enmity to the believers (Muslims) the Jews and those who are Al-Mushrikoon (see V.2:105), and you will find the nearest in love to the believers (Muslims) those who say: \"We are Christians.\" That is because amongst them are priests and monks, and they are not proud.', 'And you will certainly find that the people most hostile against the believers are the Jews and the ones who ascribe partners to Allah. You will certainly find that the closest of them in friendship with the believers are those who say, “We are Christians.”That is because among them there are priests and monks,46 and because they are not arrogant.'),
(752, 5, 83, 11, 1, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'وَ  اِذَا سَمِعُوۡا مَاۤ  اُنۡزِلَ  اِلَی الرَّسُوۡلِ تَرٰۤی اَعۡیُنَہُمۡ تَفِیۡضُ مِنَ  الدَّمۡعِ مِمَّا عَرَفُوۡا مِنَ الۡحَقِّ ۚ یَقُوۡلُوۡنَ رَبَّنَاۤ  اٰمَنَّا فَاکۡتُبۡنَا مَعَ الشّٰہِدِیۡنَ ﴿۸۳﴾', 'اور جب اس کتاب کو سنتے ہیں جو اس پیغمبر محمد ﷺ پر نازل ہوئی تو تم دیکھتے ہو کہ انکی آنکھوں سے آنسو جاری ہو جاتے ہیں اسلئے کہ انہوں نے حق بات پہچان لی۔ اور یہ اللہ کی جناب میں عرض کرتے ہیں کہ اے پروردگار ہم ایمان لے آئے سو تو ہم کو ماننے والوں میں لکھ لے۔', 'اور جب سنتے ہیں اس کو جو اترا رسول پر تو دیکھے تو ان کی آنکھوں کو کہ ابلتی ہیں آنسوؤں سے اس وجہ سے کہ انہوں نے پہچان لیا حق بات کو کہتے ہیں اے رب ہمارے ہم ایمان لائے سو تو لکھ ہم کو ماننے والوں کے ساتھ', 'And when they (who call themselves Christians) listen to what has been sent down to the Messenger (Muhammad SAW), you see their eyes overflowing with tears because of the truth they have recognised. They say: \"Our Lord! We believe; so write us down among the witnesses.', 'When they hear what has been sent down to the Messenger, you will see their eyes overflowing with tears because of the truth they have recognized. They say, “Our Lord, we have come to believe. So, record us along with those who bear witness.'),
(753, 5, 84, 11, 1, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'وَ مَا لَنَا لَا نُؤۡمِنُ بِاللّٰہِ وَ مَا جَآءَنَا مِنَ الۡحَقِّ ۙ وَ نَطۡمَعُ اَنۡ  یُّدۡخِلَنَا رَبُّنَا مَعَ  الۡقَوۡمِ الصّٰلِحِیۡنَ ﴿۸۴﴾', 'اور ہمیں کیا ہوا ہے کہ اللہ پر اور حق بات پر جو ہمارے پاس آئی ہے ایمان نہ لائیں۔ اور ہم امید رکھتے ہیں کہ ہمارا پروردگار ہم کو نیک بندوں کے ساتھ بہشت میں داخل کرے گا۔', 'اور ہم کو کیا ہوا کہ یقین نہ لاویں اللہ پر اور اس چیز پر جو پہنچی ہم کو حق سےاور توقع رکھیں اسکی کہ داخل کرے ہم کو رب ہمارا ساتھ نیک بختوں کے', '\"And why should we not believe in Allah and in that which has come to us of the truth (Islamic Monotheism)? And we wish that our Lord will admit us (in Paradise on the Day of Resurrection) along with the righteous people (Prophet Muhammad SAW and his Companions ÑÖì ã).\"', 'What excuse do we have if we do not believe in Allah and in the truth that has come to us, while we hope that our Lord will admit us to the company of the righteous people?”'),
(754, 5, 85, 11, 1, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'فَاَثَابَہُمُ اللّٰہُ بِمَا قَالُوۡا جَنّٰتٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَا ؕ وَ ذٰلِکَ  جَزَآءُ   الۡمُحۡسِنِیۡنَ ﴿۸۵﴾', 'پس اللہ نے انکو اس کہنے کے سبب بہشت کے باغ عطا فرمائے جن کے نیچے نہریں بہ رہی ہیں یہ ہمیشہ ان میں رہیں گے۔ اور نیکوکاروں کا یہی صلہ ہے۔', 'پھر انکو بدلے میں دیے اللہ نے اس کہنے پر ایسے باغ کہ جن کے نیچے بہتی ہیں نہریں رہا کریں ان میں ہی اور یہ ہے بدلا نیکی کرنے والوں کا', 'So because of what they said, Allah rewarded them Gardens under which rivers flow (in Paradise), they will abide therein forever. Such is the reward of gooddoers.', 'So, because of what they said, Allah has awarded them gardens beneath which rivers flow, wherein they will live forever. That is the reward of those who are good in their deeds.'),
(755, 5, 86, 11, 1, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'وَ الَّذِیۡنَ کَفَرُوۡا وَ کَذَّبُوۡا بِاٰیٰتِنَاۤ  اُولٰٓئِکَ  اَصۡحٰبُ  الۡجَحِیۡمِ ﴿٪۸۶﴾', 'اور جن لوگوں نے کفر کیا اور ہماری آیتوں کو جھٹلایا وہ جہنمی ہیں۔', 'اور جو لوگ منکر ہوئے اور جھٹلانےلگے ہمای آیتوں کو وہ ہیں دوزخ کے رہنے والے [۲۱۴]', 'But those who disbelieved and belied Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), they shall be the dwellers of the (Hell) Fire.', 'But those who disbelieved and denied Our signs, they are the people of the Fire.'),
(756, 5, 87, 12, 2, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تُحَرِّمُوۡا طَیِّبٰتِ مَاۤ  اَحَلَّ اللّٰہُ لَکُمۡ وَ لَا تَعۡتَدُوۡا ؕ اِنَّ اللّٰہَ لَا  یُحِبُّ الۡمُعۡتَدِیۡنَ ﴿۸۷﴾', 'مومنو! جو پاکیزہ چیزیں اللہ نے تمہارے لئے حلال کی ہیں انکو حرام نہ کرو اور حد سے نہ بڑھو کہ اللہ حد سے بڑھنے والوں کو دوست نہیں رکھتا۔', 'اے ایمان والو مت حرام ٹھہراؤ وہ لذیذ چیزیں جو اللہ نے تمہارے لئےحلال کردیں اور حد سے نہ بڑھو بیشک اللہ پسند نہیں کرتا حد سے بڑھنے والوں کو', 'O you who believe! Make not unlawful the Taiyibat (all that is good as regards foods, things, deeds, beliefs, persons, etc.) which Allah has made lawful to you, and transgress not. Verily, Allah does not like the transgressors.', 'O you who believe, do not hold as unlawful the good things that Allah has made lawful for you, and do not transgress. Verily, Allah does not like the transgressors.'),
(757, 5, 88, 12, 2, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'وَ کُلُوۡا مِمَّا رَزَقَکُمُ اللّٰہُ حَلٰلًا طَیِّبًا ۪ وَّ اتَّقُوا اللّٰہَ الَّذِیۡۤ اَنۡتُمۡ بِہٖ مُؤۡمِنُوۡنَ ﴿۸۸﴾', 'اور جو حلال  و طیب روزی اللہ نے تم کو دی ہے اسے کھاؤ اور اللہ سے جس پر ایمان رکھتے ہو ڈرتے رہو۔', 'اور کھاؤ اللہ کے دیے ہوئے میں سے جو چیز حلال پاکیزہ ہو اور ڈرتے رہو اللہ سے جس پر تم ایمان رکھتے ہو [۲۱۵]', 'And eat of the things which Allah has provided for you, lawful and good, and fear Allah in Whom you believe.', 'Eat from what Allah has provided you as good and lawful, and fear Allah in whom you believe.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(758, 5, 89, 12, 2, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'لَا یُؤَاخِذُکُمُ اللّٰہُ بِاللَّغۡوِ فِیۡۤ  اَیۡمَانِکُمۡ وَ لٰکِنۡ یُّؤَاخِذُکُمۡ بِمَا عَقَّدۡتُّمُ الۡاَیۡمَانَ ۚ فَکَفَّارَتُہٗۤ  اِطۡعَامُ عَشَرَۃِ مَسٰکِیۡنَ مِنۡ اَوۡسَطِ مَا تُطۡعِمُوۡنَ اَہۡلِیۡکُمۡ  اَوۡ  کِسۡوَتُہُمۡ اَوۡ تَحۡرِیۡرُ  رَقَبَۃٍ ؕ فَمَنۡ لَّمۡ یَجِدۡ فَصِیَامُ ثَلٰثَۃِ اَیَّامٍ ؕ ذٰلِکَ کَفَّارَۃُ  اَیۡمَانِکُمۡ  اِذَا حَلَفۡتُمۡ ؕ وَ احۡفَظُوۡۤا اَیۡمَانَکُمۡ ؕ کَذٰلِکَ یُبَیِّنُ اللّٰہُ لَکُمۡ  اٰیٰتِہٖ لَعَلَّکُمۡ  تَشۡکُرُوۡنَ ﴿۸۹﴾', 'اللہ تمہاری بے ارادہ قسموں پر تم سے مواخذہ نہیں کرے گا لیکن پختہ قسموں پر جن کے خلاف کرو گے مواخذہ کرے گا تو اس کا کفارہ دس ناداروں کو اوسط درجے کا کھانا کھلانا ہے جو تم اپنے اہل و عیال کو کھلاتے ہو یا انکو کپڑے دینا یا ایک غلام آزاد کرنا۔ اور جس کو یہ میسر نہ ہو وہ تین روزے رکھے۔ یہ تمہاری قسموں کا کفارہ ہے جب تم قسم کھا لو اور اسے توڑ دو اور اپنی قسموں کی حفاظت کرو اس طرح اللہ تمہارے سمجھانے کے لئے اپنی آیتیں کھول کھول کر بیان فرماتا ہے۔ تاکہ تم شکر کرو۔', 'نہیں پکڑتا اللہ تم کو تمہاری بیہودہ قسموں پر [۲۱۶] لیکن پکڑتا ہے اس پر جس قسم کو تم نے مضبوط باندھا سو اس کا کفارہ کھانا دینا ہے دس محتاجوں کو اوسط درجہ کا کھانا جو دیتے ہو اپنے گھر والوں کو [۲۱۷] یا کپڑا پہنا دینا دس محتاجوں کو [۲۱۸] یا ایک گردن آزاد کرنی [۲۱۹] پھر جس کو میسر نہ ہوتو روزے رکھنے ہیں تین دن کے [۲۲۰] یہ کفارہ ہے تمہاری قسموں کا جب قسم کھا بیٹھو اور حفاطت رکھو اپنی قسموں کی [۲۲۱] اسی طرح بیان کرتا ہے اللہ تمہارے لئے اپنے حکم تاکہ تم احسان مانو [۲۲۲]', 'Allah will not punish you for what is uninentional in your oaths, but He will punish you for your deliberate oaths; for its expiation (a deliberate oath) feed ten Masakin (poor persons), on a scale of the average of that with which you feed your own families; or clothe them; or manumit a slave. But whosoever cannot afford (that), then he should fast for three days. That is the expiation for the oaths when you have sworn. And protect your oaths (i.e. do not swear much). Thus Allah make clear to you His Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) that you may be grateful.', 'Allah does not hold you accountable for your laghw (ineffectual) oaths, but He does hold you accountable for the oath with which you have bound yourself. Its expiation is to feed ten poor persons at an average of what you feed your family with, or to clothe them, or to free a slave. However, if someone cannot afford, he has to fast for three days. That is expiation for the oaths that you have sworn. Take care of your oaths. That is how Allah makes His signs clear to you, so that you may be grateful.'),
(759, 5, 90, 12, 2, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اِنَّمَا الۡخَمۡرُ وَ الۡمَیۡسِرُ وَ الۡاَنۡصَابُ وَ الۡاَزۡلَامُ رِجۡسٌ مِّنۡ  عَمَلِ الشَّیۡطٰنِ فَاجۡتَنِبُوۡہُ  لَعَلَّکُمۡ  تُفۡلِحُوۡنَ ﴿۹۰﴾', 'اے ایمان والو! شراب اور جوا اور بت اور پانسے یہ سب ناپاک کام اعمال شیطان سے ہیں سو ان سے بچتے رہنا تاکہ تم کامیاب ہو جاؤ۔', 'اے ایمان والو یہ جو ہے شراب اور جوا اور بت اور پانسے [۲۲۳] سب گندے کام ہیں شیطان کے سو ان سے بچتے رہو تاکہ تم نجات پاؤ [۲۲۴]', 'O you who believe! Intoxicants (all kinds of alcoholic drinks), gambling, AlAnsab, and AlAzlam (arrows for seeking luck or decision) are an abomination of Shaitans (Satan) handiwork. So avoid (strictly all) that (abomination) in order that you may be successful.', 'O you who believe! Wine, gambling, altars and divining arrows are filth, made up by Satan. Therefore, refrain from it, so that you may be successful.'),
(760, 5, 91, 12, 2, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'اِنَّمَا یُرِیۡدُ الشَّیۡطٰنُ اَنۡ  یُّوۡقِعَ  بَیۡنَکُمُ الۡعَدَاوَۃَ  وَ الۡبَغۡضَآءَ  فِی الۡخَمۡرِ وَ الۡمَیۡسِرِ وَ یَصُدَّکُمۡ عَنۡ ذِکۡرِ اللّٰہِ وَ عَنِ الصَّلٰوۃِ ۚ فَہَلۡ اَنۡتُمۡ مُّنۡتَہُوۡنَ ﴿۹۱﴾', 'شیطان تو یہ چاہتا ہے کہ شراب اور جوئے کے سبب تمہارے آپس میں دشمنی اور رنجش ڈلوا دے اور تمہیں اللہ کی یاد سے اور نماز سے روک دے تو کیا تم لوگ ان کاموں سے باز آؤ گے۔', 'شیطان تو یہی چاہتا ہے کہ ڈالے تم میں دشمنی اور بیر بذریعہ شراب اور جوئے کے اور روکےتم کو اللہ کی یاد سے اور نماز سے سو اب بھی تم باز آؤ گے [۲۲۵]', 'Shaitan (Satan) wants only to excite enmity and hatred between you with intoxicants (alcoholic drinks) and gambling, and hinder you from the remembrance of Allah and from As-Salat (the prayer). So, will you not then abstain?', 'Satan wishes only to plant enmity and malice between you through wine and gambling, and to prevent you from the remembrance of Allah and from Salāh. Would you, then, abstain?'),
(761, 5, 92, 12, 2, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'وَ اَطِیۡعُوا اللّٰہَ وَ اَطِیۡعُوا الرَّسُوۡلَ وَ احۡذَرُوۡا ۚ فَاِنۡ تَوَلَّیۡتُمۡ فَاعۡلَمُوۡۤا اَنَّمَا عَلٰی  رَسُوۡلِنَا الۡبَلٰغُ  الۡمُبِیۡنُ ﴿۹۲﴾', 'اور اللہ کی فرمانبرداری اور رسول کی اطاعت کرتے رہو اور ڈرتے رہو۔ اب اگر منہ پھیرو گے تو جان رکھو کہ ہمارے پیغمبر کے ذمے تو صرف پیغام کا کھول کر پہنچا دینا ہے۔', 'اور حکم مانو اللہ کا اور حکم مانو رسول کا اور بچتے رہو پھر اگر تم پھر جاؤ گے تو جان لو کہ ہمارے رسول کا ذمہ صرف پہنچا دینا ہے کھول کر [۲۲۶]', 'And obey Allah and the Messenger (Muhammad SAW), and beware (of even coming near to drinking or gambling or AlAnsab, or AlAzlam, etc.) and fear Allah. Then if you turn away, you should know that it is Our Messengers duty to convey (the Message) in the clearest way.', 'Obey Allah, obey the Messenger, and be heedful. If you still turn back, be assured that the duty of Our Messenger is only to convey the Message clearly.'),
(762, 5, 93, 12, 2, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'لَیۡسَ عَلَی الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ جُنَاحٌ فِیۡمَا طَعِمُوۡۤا اِذَا مَا اتَّقَوۡا وَّ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ ثُمَّ اتَّقَوۡا وَّ اٰمَنُوۡا ثُمَّ اتَّقَوۡا وَّ اَحۡسَنُوۡا ؕ وَ اللّٰہُ یُحِبُّ الۡمُحۡسِنِیۡنَ ﴿٪۹۳﴾', 'جو لوگ ایمان لائے اور نیک عمل کرتے رہے ان پر ان چیزوں کا کچھ گناہ نہیں جو وہ کھا چکے۔ جبکہ انہوں نے پرہیز کیا اور ایمان لائے اور نیک کام کیا۔ پھر پرہیز کیا اور ایمان لائے پھر پرہیز کیا اور نیکوکاری کی۔ اور اللہ نیکوکاروں کو دوست رکھتا ہے۔', 'جو لوگ ایمان لائے اور کام نیک کئے ان پر گناہ نہیں اس میں جو کچھ پہلے کھا چکے جب کہ آئندہ کو ڈر گئے اور ایمان لائے اور عمل نیک کئے پھر ڈرتے رہے اور یقین کیا پھر ڈرتے رہے اور نیکی کی اور اللہ دوست رکھتا ہےنیکی کرنے والوں کو [۲۲۷]', 'Those who believe and do righteous good deeds, there is no sin on them for what they ate (in the past), if they fear Allah (by keeping away from His forbidden things), and believe and do righteous good deeds, and again fear Allah and believe, and once again fear Allah and do good deeds with Ihsan (perfection). And Allah loves the gooddoers.', 'There is no sin, for those who believe and do good deeds, in what they might have partaken earlier, if they fear Allah, and believe, and do good deeds; and again fear Allah, and believe, and still again fear Allah and do good deeds. Allah loves those who are good in their deeds.'),
(763, 5, 94, 13, 3, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا  لَیَبۡلُوَنَّکُمُ  اللّٰہُ بِشَیۡءٍ مِّنَ الصَّیۡدِ تَنَالُہٗۤ  اَیۡدِیۡکُمۡ وَ رِمَاحُکُمۡ لِیَعۡلَمَ اللّٰہُ مَنۡ یَّخَافُہٗ بِالۡغَیۡبِ ۚ فَمَنِ اعۡتَدٰی بَعۡدَ ذٰلِکَ فَلَہٗ عَذَابٌ اَلِیۡمٌ ﴿۹۴﴾', 'مومنو! کسی قدر شکار سے جنکو تم ہاتھوں اور نیزوں سے حاصل کر سکو اللہ تمہاری آزمائش کرے گا یعنی حالت احرام میں شکار کی ممانعت سے تاکہ معلوم کرے کہ اس سے غائبانہ کون ڈرتا ہے سو جو اسکے بعد زیادتی کرے تو اسکے لئے دکھ دینے والا عذاب تیار ہے۔', 'اے ایمان والو البتہ تم کو آزماوے گا اللہ ایک بات سے اس شکار میں کہ جس پر پہنچے ہیں ہاتھ تمہارے اور نیزےتمہارے [۲۲۸] تاکہ معلوم کرے اللہ کون اس سے ڈرتا ہے بن دیکھے [۲۲۹] پھر جس نے زیادتی کی اس کے بعد تو اس کے لئے عذاب دردناک ہے', 'O you who believe! Allah will certainly make a trial of you with something in (the matter of) the game that is well within reach of your hands and your lances, that Allah may test who fears Him unseen. Then whoever transgresses thereafter, for him there is a painful torment.', 'O you who believe, Allah shall certainly test you with some of the game coming in the range of your hands and spears, so that Allah may know those who fear Him, even though He is Unseen. Whoever transgresses the limit after all this, for him there is a painful punishment.'),
(764, 5, 95, 13, 3, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَقۡتُلُوا الصَّیۡدَ وَ اَنۡتُمۡ حُرُمٌ ؕ وَ مَنۡ قَتَلَہٗ مِنۡکُمۡ مُّتَعَمِّدًا فَجَزَآءٌ  مِّثۡلُ  مَا قَتَلَ مِنَ النَّعَمِ یَحۡکُمُ بِہٖ ذَوَا عَدۡلٍ مِّنۡکُمۡ ہَدۡیًۢا بٰلِغَ الۡکَعۡبَۃِ  اَوۡ کَفَّارَۃٌ  طَعَامُ مَسٰکِیۡنَ اَوۡ عَدۡلُ ذٰلِکَ صِیَامًا لِّیَذُوۡقَ وَبَالَ اَمۡرِہٖ ؕ عَفَا اللّٰہُ عَمَّا سَلَفَ ؕ وَ مَنۡ عَادَ فَیَنۡتَقِمُ اللّٰہُ مِنۡہُ ؕ وَ اللّٰہُ  عَزِیۡزٌ  ذُو انۡتِقَامٍ ﴿۹۵﴾', 'مومنو! جب تم احرام کی حالت میں ہو تو شکار کے جانور نہ مارنا۔ اور جو تم میں سے جان بوجھ کر اسے مارے تو یا تو اس کا بدلہ دے اور وہ یہ ہے کہ اسی طرح کا چوپایہ جسے تم میں سے دو معتبر شخص مقرر کر دیں قربانی کرے اور یہ قربانی کعبے پہنچائی جائے یا کفارہ دے اور وہ مسکینوں کو کھانا کھلانا ہے یا اسکے برابر روزے رکھے تاکہ اپنے کام کی سزا کا مزا چکھے اور جو پہلے ہو چکا وہ اللہ نے معاف کر دیا اور جو پھر ایسا کام کرے گا تو اللہ اس سے انتقام لے گا۔ اور اللہ غالب ہے انتقام لینے والا ہے۔', 'اے ایمان والو نہ مارو شکار جس وقت تم ہو احرام میں [۲۳۰] اور جو کوئی تم میں اس کو مارے جان کر [۲۳۱] تو اس پر بدلا ہے اس مارے ہوئے کے برابر مویشی میں سے جو تجویز کریں دو آدمی معتبر تم میں سے اس طرح سے کہ وہ جانور بدلے کا بطور نیاز پہنچایا جاوے کعبہ تک یا اس پر کفارہ ہے چند محتاجوں کو کھلانا یا اس کےبرابر روزے تاکہ چکھے سزا اپنے کام کی [۲۳۲] اللہ نے معاف کیا جو کچھ ہو چکا [۲۳۳] اور جو کوئی پھر کرے گا اس سے بدلا لے گا اللہ اور اللہ زبردست ہے بدلا لینے والا [۲۳۴]', 'O you who believe! Kill not game while you are in a state of Ihram for Hajj or Umrah (pilgrimage), and whosoever of you kills it intentionally, the penalty is an offering, brought to the Kabah, of an eatable animal (i.e. sheep, goat, cow, etc.) equivalent to the one he killed, as adjudged by two just men among you; or, for expiation, he should feed Masakin (poor persons), or its equivalent in Saum (fasting), that he may taste the heaviness (punishment) of his deed. Allah has forgiven what is past, but whosoever commits it again, Allah will take retribution from him. And Allah is AllMighty, All-Able of Retribution.', 'O you who believe, do not kill game when you are in IHrām (state of consecration for Hajj or ‘Umrah). If someone from among you kills it deliberately, then compensation (will be required) from cattle equal to what one has killed, according to the judgement of two just men from among you, as an offering due to reach the Ka’bah, or an expiation, that is, to feed the poor, or its equal in fasts, so that he may taste the punishment of what he did. Allah has forgiven what has passed, but whoever does it again, Allah shall subject him to retribution. Allah is Mighty, Lord of Retribution.'),
(765, 5, 96, 13, 3, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'اُحِلَّ لَکُمۡ صَیۡدُ الۡبَحۡرِ وَ طَعَامُہٗ مَتَاعًا لَّکُمۡ وَ لِلسَّیَّارَۃِ ۚ وَ حُرِّمَ عَلَیۡکُمۡ صَیۡدُ الۡبَرِّ مَا دُمۡتُمۡ حُرُمًا ؕ وَ اتَّقُوا  اللّٰہَ الَّذِیۡۤ  اِلَیۡہِ  تُحۡشَرُوۡنَ ﴿۹۶﴾', 'تمہارے لئے دریا کی چیزوں کا شکار اور ان کا کھانا حلال کر دیا گیا ہے یعنی تمہارے اور مسافروں کے فائدے کے لئے اور جنگل کی چیزوں کا شکار جب تک تم احرام کی حالت میں ہو تم پر حرام ہے اور اللہ سے جسکے پاس تم سب جمع کئے جاؤ گے ڈرتے رہو۔', 'حلال ہوا تمہارے لئے دریا کا شکار اور دریا کا کھانا تمہارے فائدہ کے واسطے اور سب مسافروں کے اور حرام ہوا تم پر جنگل کا شکار جب تک تم احرام میں رہو اور ڈرتے رہو اللہ سےجس کے پاس تم جمع ہو گے [۲۳۵]', 'Lawful to you is (the pursuit of) watergame and its use for food - for the benefit of yourselves and those who travel, but forbidden is (the pursuit of) landgame as long as you are in a state of Ihram (for Hajj or Umrah). And fear Allah to Whom you shall be gathered back.', 'Made lawful for you is the game of the sea and eating thereof, as a benefit for you and for travellers. But the game of the land has been made unlawful for you as long as you are in the state of IHrām. Fear Allah (the One) towards Whom you are to be brought together.'),
(766, 5, 97, 13, 3, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'جَعَلَ اللّٰہُ الۡکَعۡبَۃَ الۡبَیۡتَ الۡحَرَامَ  قِیٰمًا لِّلنَّاسِ وَ الشَّہۡرَ الۡحَرَامَ وَ الۡہَدۡیَ وَ الۡقَلَآئِدَ ؕ ذٰلِکَ  لِتَعۡلَمُوۡۤا  اَنَّ اللّٰہَ یَعۡلَمُ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ  وَ  اَنَّ اللّٰہَ بِکُلِّ  شَیۡءٍ عَلِیۡمٌ ﴿۹۷﴾', 'اللہ نے عزت کے گھر یعنی کعبے کو لوگوں کے لئے موجب قیام بنایا ہے اور عزت  کے مہینے کو اور قربانی کے جانور کو اور ان جانوروں کو جن کے گلے میں پٹے بندھے ہوں۔ یہ اس لئے کہ تم جان لو کہ جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے اللہ سب کو جانتا ہے اور یہ کہ اللہ کو ہر چیز کا علم ہے۔', 'اللہ نے کر دیا کعبہ کو جو کہ گھر ہے بزرگی والا قیام کا باعث لوگوں کے لئے اور بزرگی والے مہینوں کو اور قربانی کو جو نیاز کعبہ کی ہو اور جنکے گلے میں پٹہ ڈال کر لیجاویں کعبہ کو [۲۳۶] یہ اس لئے کہ تم جان لو کہ بیشک اللہ کو معلوم ہے جو کچھ کہ ہے آسمان اور زمین میں اور اللہ ہر چیز سے خوب واقف ہے [۲۳۷]', 'Allah has made the Kabah, the Sacred House, an asylum of security and Hajj and Umrah (pilgrimage) for mankind, and also the Sacred Month and the animals of offerings and the garlanded (people or animals, etc. marked with the garlands on their necks made from the outer part of the stem of the Makkah trees for their security), that you may know that Allah has knowledge of all that is in the heavens and all that is in the earth, and that Allah is the AllKnower of each and everything.', 'Allah has made the Ka’bah, the Sacred House, a source of stability for people, and also the sacred month and the sacrificial animal and the garlands. All this is because you may learn that Allah knows what is in the heavens and what is in the earth. Allah is All-Knowing in respect of everything.'),
(767, 5, 98, 13, 3, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'اِعۡلَمُوۡۤا اَنَّ اللّٰہَ شَدِیۡدُ الۡعِقَابِ وَ اَنَّ اللّٰہَ غَفُوۡرٌ  رَّحِیۡمٌ ﴿ؕ۹۸﴾', 'جان رکھو کہ اللہ سخت عذاب دینے والا ہے اور یہ کہ اللہ بخشنے والا ہے مہربان بھی ہے۔', 'جان لو کہ بیشک اللہ کا عذاب سخت ہے اور بیشک اللہ بخشنے والا مہربان ہے [۲۳۸]', 'Know that Allah is Severe in punishment and that Allah is OftForgiving, Most Merciful.', 'Be sure that Allah is severe in punishment and that Allah is Very-Forgiving, Very-Merciful.'),
(768, 5, 99, 13, 3, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'مَا عَلَی الرَّسُوۡلِ  اِلَّا الۡبَلٰغُ ؕ وَ اللّٰہُ یَعۡلَمُ  مَا تُبۡدُوۡنَ وَ مَا تَکۡتُمُوۡنَ ﴿۹۹﴾', 'پیغمبر کے ذمے تو صرف پیغام پہنچا دینا ہے اور جو کچھ تم ظاہر کرتے ہو اور جو کچھ مخفی کرتے ہو اللہ کو سب معلوم ہے۔', 'رسول کے ذمہ نہیں مگر پہنچا دینا اور اللہ کو معلوم ہے جو تم ظاہر میں کرتے ہو اور جو چھپا کر کرتے ہو [۲۳۹]', 'The Messengers duty (i.e. Our Messenger Muhammad SAW whom We have sent to you, (O mankind)) is but to convey (the Message). And Allah knows all that you reveal and all that you conceal.', 'The duty of Our Messenger is only to convey the Message. Allah knows what you disclose and what you conceal.'),
(769, 5, 100, 13, 3, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'قُلۡ لَّا یَسۡتَوِی الۡخَبِیۡثُ وَ الطَّیِّبُ وَ لَوۡ اَعۡجَبَکَ کَثۡرَۃُ الۡخَبِیۡثِ ۚ فَاتَّقُوا اللّٰہَ یٰۤاُولِی الۡاَلۡبَابِ لَعَلَّکُمۡ تُفۡلِحُوۡنَ ﴿۱۰۰﴾٪', 'کہدو کہ ناپاک چیزیں اور پاک چیزیں برابر نہیں ہوتیں گو ناپاک چیزوں کی کثرت تمہیں اچھی ہی لگے۔ تو عقل والو اللہ سے ڈرتے رہو تاکہ کامیاب ہو جاؤ۔', 'تو کہہ دے کہ برابر نہیں ناپاک اور پاک اگرچہ تجھ کو بھلی لگے ناپاک کی کثرت سو ڈرتے رہو اللہ سے اے عقلمندو تاکہ تمہاری نجات ہو [۲۴۰]', 'Say (O Muhammad SAW): \"Not equal are AlKhabeeth (all that is evil and bad as regards things, deeds, beliefs, persons, foods, etc.) and AtTaiyib (all that is good as regards things, deeds, beliefs, persons, foods, etc.), even though the abundance of Al-Khabeeth (evil) may please you.\" So fear Allah much ((abstain from all kinds of sins and evil deeds which He has forbidden) and love Allah much (perform all kinds of good deeds which He has ordained)), O men of understanding in order that you may be successful.', 'Say, “The evil and the good are not equal, even though the abundance of (what is) evil may attract you. So, fear Allah, O people of understanding, so that you may be successful.”'),
(770, 5, 101, 14, 4, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَسۡـَٔلُوۡا عَنۡ اَشۡیَآءَ  اِنۡ تُبۡدَ لَکُمۡ  تَسُؤۡکُمۡ ۚ وَ  اِنۡ تَسۡـَٔلُوۡا عَنۡہَا حِیۡنَ یُنَزَّلُ الۡقُرۡاٰنُ تُبۡدَ لَکُمۡ ؕ عَفَا اللّٰہُ عَنۡہَا ؕ وَ اللّٰہُ غَفُوۡرٌ حَلِیۡمٌ ﴿۱۰۱﴾', 'مومنو! ایسی چیزوں کے بارے میں مت سوال کرو کہ اگر ان کی حقیقتیں تم پر ظاہر کر دی جائیں تو تمہیں بری لگیں۔ اور اگر قرآن کے نازل ہونے کے ایام میں ایسی باتیں پوچھو گے تو تم پر ظاہر بھی کر دی جائیں گی اب تو اللہ نے ایسی باتوں کے پوچھنے سے درگذر فرمایا ہے اور اللہ بخشنے والا ہے بردبار ہے۔', 'اے ایمان والو مت پوچھو ایسی باتیں کہ اگر تم پر کھولی جاویں تو تم کو بری لگیں اور اگر پوچھو گے یہ باتیں ایسے وقت میں کہ قرآن نازل ہو رہا ہے تو تم پر ظاہر کر دی جاویں گی [۲۴۱] اللہ نے ان سے درگذر کی ہے [۲۴۲] اور اللہ بخشنے والا تحمل والا ہے', 'O you who believe! Ask not about things which, if made plain to you, may cause you trouble. But if you ask about them while the Quran is being revealed, they will be made plain to you. Allah has forgiven that, and Allah is OftForgiving, Most Forbearing.', 'O you who believe, do not ask about things which, if disclosed, would displease you. If you ask about them while the Qur’ān is being revealed, they will be disclosed to you. Allah has pardoned you for it. Allah is Most-Forgiving, Forbearing.'),
(771, 5, 102, 14, 4, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'قَدۡ سَاَلَہَا قَوۡمٌ مِّنۡ قَبۡلِکُمۡ ثُمَّ اَصۡبَحُوۡا بِہَا کٰفِرِیۡنَ ﴿۱۰۲﴾', 'اس طرح کی باتیں تم سے پہلے لوگوں نے بھی پوچھی تھیں مگر جب بتائی گئیں تو پھر وہ ان سے منکر ہو گئے۔', 'ایسی باتیں پوچھ چکی ہے ایک جماعت تم سے پہلے پھر ہو گئے ان باتوں سے منکر [۲۴۳]', 'Before you, a community asked such questions, then on that account they became disbelievers.', 'People before you asked such questions, and then, as a result, became disbelievers.'),
(772, 5, 103, 14, 4, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'مَا جَعَلَ اللّٰہُ مِنۡۢ بَحِیۡرَۃٍ  وَّ لَا سَآئِبَۃٍ  وَّ لَا وَصِیۡلَۃٍ وَّ لَا حَامٍ ۙ وَّ لٰکِنَّ الَّذِیۡنَ کَفَرُوۡا یَفۡتَرُوۡنَ عَلَی اللّٰہِ الۡکَذِبَ ؕ وَ اَکۡثَرُہُمۡ لَا یَعۡقِلُوۡنَ ﴿۱۰۳﴾', 'اللہ نے نہ تو کوئی بحیرہ مقرر کیا ہے اور نہ کوئی سائبہ اور نہ کوئی وصیلہ اور نہ کوئی حامی لیکن کافر اللہ پر جھوٹ باندھتے ہیں۔ اور یہ اکثر عقل سے کام نہیں لیتے۔', 'نہیں مقرر کیا اللہ نے بحیرہ اور نہ سائبہ اور نہ وصیلہ اور نہ حامی و لیکن کافر باندھتے ہیں اللہ پر بہتان اور ان میں اکثروں کو عقل نہیں [۲۴۴]', 'Allah has not instituted things like Baheerah (a shecamel whose milk was spared for the idols and nobody was allowed to milk it) or a Saibah (a shecamel let loose for free pasture for their false gods, e.g. idols, etc., and nothing was allowed to be carried on it), or a Waseelah (a shecamel set free for idols because it has given birth to a shecamel at its first delivery and then again gives birth to a shecamel at its second delivery) or a Ham (a stallioncamel freed from work for their idols, after it had finished a number of copulations assigned for it, all these animals were liberated in honour of idols as practised by pagan Arabs in the preIslamic period). But those who disbelieve invent lies against Allah, and most of them have no understanding.', 'Allah has made no BaHīrah, no Sā’ibah, no WaSīlah and no Hāmī (names of animals dedicated to idols on different grounds). But those who disbelieve coin a lie against Allah, and most of them do not understand.'),
(773, 5, 104, 14, 4, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'وَ اِذَا قِیۡلَ لَہُمۡ تَعَالَوۡا  اِلٰی  مَاۤ اَنۡزَلَ اللّٰہُ وَ اِلَی الرَّسُوۡلِ قَالُوۡا حَسۡبُنَا مَا وَجَدۡنَا عَلَیۡہِ اٰبَآءَنَا ؕ اَوَ  لَوۡ کَانَ اٰبَآؤُہُمۡ لَا یَعۡلَمُوۡنَ شَیۡئًا وَّ لَا یَہۡتَدُوۡنَ ﴿۱۰۴﴾', 'اور جب ان لوگوں سے کہا جاتا ہے کہ جو کتاب اللہ نے نازل فرمائی ہے اسکی طرف اور پیغمبر کی طرف رجوع کرو تو کہتے ہیں کہ جس طریق پر ہم نے اپنے باپ دادا کو پایا ہے وہی ہمیں کافی ہے۔ بھلا اگر ان کے باپ دادا نہ تو کچھ جانتے ہوں اور نہ سیدھے رستے پر ہوں تب بھی؟', 'اور جب کہا جاتا ہے ان کو آؤ اسکی طرف جو کہ اللہ نے نازل کیا اور رسول کی طرف تو کہتے ہیں ہم کو کافی ہے وہ جس پر پایا ہم نے اپنے باپ دادوں کو بھلا اگر انکے باپ دادے نہ کچھ علم رکھتے ہوں اور نہ راہ جانتے ہوں تو بھی ایسا ہی کریں گے [۲۴۵]', 'And when it is said to them: \"Come to what Allah has revealed and unto the Messenger (Muhammad SAW for the verdict of that which you have made unlawful).\" They say: \"Enough for us is that which we found our fathers following,\" even though their fathers had no knowledge whatsoever and no guidance.', 'When it is said to them, “Come to what Allah has sent down, and to the Messenger;” they say, “Sufficient for us is that on which we have found our forefathers.” Is it so, even though their forefathers knew nothing, and had no guidance either?'),
(774, 5, 105, 14, 4, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا عَلَیۡکُمۡ اَنۡفُسَکُمۡ ۚ  لَا یَضُرُّکُمۡ مَّنۡ ضَلَّ  اِذَا اہۡتَدَیۡتُمۡ ؕ اِلَی اللّٰہِ مَرۡجِعُکُمۡ  جَمِیۡعًا فَیُنَبِّئُکُمۡ بِمَا کُنۡتُمۡ تَعۡمَلُوۡنَ ﴿۱۰۵﴾', 'اے ایمان والو! اپنے آپ کو سنبھالے رہو۔ جب تم ہدایت پر ہو تو کوئی گمراہ تمہارا کچھ بگاڑ نہیں سکتا تم سب کو اللہ کی طرف لوٹ کر جانا ہے اس وقت وہ تم کو تمہارے سب کاموں سے جو دنیا میں کئے تھے آگاہ کرے گا اور ان کا بدلہ دے گا۔', 'اے ایمان والو تم پر لازم ہے فکر اپنی جان کا تمہارا کچھ نہیں بگاڑتا جو کوئی گمراہ ہوا جبکہ تم ہوئے راہ پر [۲۴۶] اللہ کے پاس لوٹ کر جانا ہے تم سب کو پھر وہ جتلاوے گا تمکو جو کچھ تم کرتےتھے [۲۴۷]', 'O you who believe! Take care of your ownselves, (do righteous deeds, fear Allah much (abstain from all kinds of sins and evil deeds which He has forbidden) and love Allah much (perform all kinds of good deeds which He has ordained)). If you follow the right guidance and enjoin what is right (Islamic Monotheism and all that Islam orders one to do) and forbid what is wrong (polytheism, disbelief and all that Islam has forbidden) no hurt can come to you from those who are in error. The return of you all is to Allah, then He will inform you about (all) that which you used to do.', 'O you who believe, take care of your own selves. The one who has gone astray cannot harm you, if you are on the right path. To Allah all of you have to return. Then He will tell you what you have been doing.'),
(775, 5, 106, 14, 4, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا شَہَادَۃُ بَیۡنِکُمۡ اِذَا حَضَرَ اَحَدَکُمُ الۡمَوۡتُ حِیۡنَ الۡوَصِیَّۃِ اثۡنٰنِ ذَوَا عَدۡلٍ مِّنۡکُمۡ  اَوۡ اٰخَرٰنِ مِنۡ غَیۡرِکُمۡ  اِنۡ اَنۡتُمۡ ضَرَبۡتُمۡ فِی الۡاَرۡضِ فَاَصَابَتۡکُمۡ مُّصِیۡبَۃُ الۡمَوۡتِ ؕ تَحۡبِسُوۡنَہُمَا مِنۡۢ بَعۡدِ الصَّلٰوۃِ  فَیُقۡسِمٰنِ بِاللّٰہِ  اِنِ ارۡتَبۡتُمۡ لَا نَشۡتَرِیۡ بِہٖ ثَمَنًا وَّ لَوۡ  کَانَ ذَا قُرۡبٰی ۙ وَ لَا نَکۡتُمُ شَہَادَۃَ ۙ اللّٰہِ  اِنَّاۤ  اِذًا لَّمِنَ الۡاٰثِمِیۡنَ ﴿۱۰۶﴾', 'مومنو! جب تم میں سے کسی کی موت آ موجود ہو تو شہادت کا نصاب یہ ہے کہ وصیت کے وقت تم مسلمانوں میں سے دو مرد عادل یعنی صاحب اعتبار گوا ہ ہوں۔ یا اگر مسلمان نہ ملیں اور تم سفر کر رہے ہو اور اس وقت تم پر موت کی مصیبت واقع ہو تو کسی دوسرے مذہب کے دو شخصوں کو گواہ کر لو اگر تم کو ان گواہوں کی نسبت کچھ شک ہو تو انکو عصر کی نماز کے بعد کھڑا کرو اور دونوں اللہ کی قسمیں کھائیں کہ ہم شہادت کا کچھ عوض نہیں لیں گے گو ہمارا رشتہ دار ہی ہو۔ اور نہ ہم اللہ کی شہادت کو چھپائیں گے اگر ایسا کرینگے تو گناہگار ہونگے۔', 'اے ایمان والو گواہ درمیان تمہارے جبکہ پہنچے کسی کو تم میں موت وصیت کے وقت دو شخص معتبر ہونے چاہئیں [۲۴۸] تم میں سے [۲۴۹] یا دو شاہد اور ہوں تمہارے سوا [۲۵۰] اگر تم نے سفر کیا ہو ملک میں پھرپہنچے تم کو مصیبت موت کی تو کھڑا کرو ان دونوں کو بعد نماز کے [۲۵۱] وہ دونوں قسم کھاویں اللہ کی اگر تم کو شبہ پڑے کہیں کہ ہم نہیں لیتے قسم کے بدلے مال اگرچہ کسی کو ہم سے قرابت بھی ہو اور ہم نہیں چھپاتے اللہ کی گواہی نہیں تو ہم بیشک گنہگار ہیں [۲۵۲]', 'O you who believe! When death approaches any of you, and you make a bequest, then take the testimony of two just men of your own folk or two others from outside, if you are travelling through the land and the calamity of death befalls you. Detain them both after As-Salat (the prayer), (then) if you are in doubt (about their truthfulness), let them both swear by Allah (saying): \"We wish not for any worldly gain in this, even though he (the beneficiary) be our near relative. We shall not hide Testimony of Allah, for then indeed we should be of the sinful.\"', 'O you who believe, when death draws near one of you, that is, at the time of making a will, the evidence (recognized) between you shall be of two witnesses from among you, or of two others not from you, if you are travelling on the earth and the trauma of death visits you. (Then) you shall detain them after the prayer, if you have some doubt, and they shall swear by Allah, “We shall not take a price for it, even if there be a relative; and we shall not conceal the evidence (as due) of Allah, otherwise we should certainly be among the sinners.”'),
(776, 5, 107, 14, 4, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'فَاِنۡ عُثِرَ عَلٰۤی اَنَّہُمَا اسۡتَحَقَّاۤ اِثۡمًا فَاٰخَرٰنِ یَقُوۡمٰنِ مَقَامَہُمَا مِنَ  الَّذِیۡنَ اسۡتَحَقَّ عَلَیۡہِمُ الۡاَوۡلَیٰنِ فَیُقۡسِمٰنِ بِاللّٰہِ لَشَہَادَتُنَاۤ  اَحَقُّ مِنۡ شَہَادَتِہِمَا وَ مَا اعۡتَدَیۡنَاۤ ۫ۖ اِنَّاۤ اِذًا لَّمِنَ الظّٰلِمِیۡنَ ﴿۱۰۷﴾', 'پھر اگر معلوم ہو جائے کہ ان دونوں نے جھوٹ بول کر گناہ حاصل کیا تو جن لوگوں کا انہوں نے حق مارنا چاہا تھا ان میں سے ان کی جگہ اور دو آدمی کھڑے ہوں جو میت سے قرابت قریبہ رکھتے ہوں۔ پھر وہ اللہ کی قسمیں کھائیں کہ ہماری شہادت انکی شہادت سے زیادہ سچی ہے اور ہم نے کوئی زیادتی نہیں کی۔ ایسا کیا ہو تو ہم بے انصاف ہیں۔', 'پھر اگر خبر ہو جاوے کہ وہ دونوں حق بات دبا گئے تو دو گواہ اور کھڑے ہوں ان کی جگہ [۲۵۳] ان میں سے کہ جن کا حق دبا ہے جو سب سے زیادہ قریب ہوں میت کے پھر قسم کھاویں اللہ کی کہ ہماری گواہی تحقیقی ہے پہلوں کی گواہی سے اور ہم نے زیادتی نہیں کی نہیں تو ہم بیشک ظالم ہیں [۲۵۴]', 'If then it gets known that these two had been guilty of sin, let two others stand forth in their places, nearest in kin from among those who claim a lawful right. Let them swear by Allah (saying): \"We affirm that our testimony is truer than that of both of them, and that we have not trespassed (the truth), for then indeed we should be of the wrongdoers.\"', 'Then, if it is discovered that the two had rendered themselves liable to a sin, then, in their place shall stand two others, closest of those whose right has been taken away, and they shall swear by Allah, “Our evidence is more truthful than their evidence, and we have not transgressed; otherwise we should be among the unjust.”'),
(777, 5, 108, 14, 4, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'ذٰلِکَ اَدۡنٰۤی اَنۡ یَّاۡتُوۡا بِالشَّہَادَۃِ عَلٰی وَجۡہِہَاۤ  اَوۡ  یَخَافُوۡۤا  اَنۡ  تُرَدَّ  اَیۡمَانٌۢ  بَعۡدَ اَیۡمَانِہِمۡ ؕ وَ اتَّقُوا اللّٰہَ وَ اسۡمَعُوۡا ؕ وَ اللّٰہُ   لَا یَہۡدِی الۡقَوۡمَ  الۡفٰسِقِیۡنَ ﴿۱۰۸﴾٪', 'اس طریق سے بہت قریب ہے کہ یہ لوگ صحیح صحیح شہادت دیں یا اس بات سے خوف کریں کہ ہماری قسمیں بھی انکی قسموں کے بعد رد کر دی جائیں گی اور اللہ سے ڈرو اور اسکے احکام کو توجہ سے سنو اور اللہ نافرمان لوگوں کو ہدایت نہیں دیتا۔', 'اس میں امید ہے کہ ادا کریں شہادت کو ٹھیک طرح پر اور ڈریں کہ الٹی پڑے گی قسم ہماری ان کی قسم کے  بعد [۲۵۵] اور ڈرتے رہو اللہ سے اور سن رکھو اور اللہ نہیں چلاتا سیدھی راہ پر نافرمانوں کو [۲۵۶]', 'That should make it closer (to the fact) that their testimony would be in its true nature and shape (and thus accepted), or else they would fear that (other) oaths would be admitted after their oaths. And fear Allah and listen ( with obedience to Him). And Allah guides not the people who are Al-Fasiqoon (the rebellious and disobedient).', 'Thus, it is more likely that the former people (i.e. the executors of the bequest) will bear witness in its proper way, or they will fear that oaths will be taken in rebuttal of their oaths. Fear Allah and listen. Allah does not lead sinning people to the right path.'),
(778, 5, 109, 15, 5, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'یَوۡمَ یَجۡمَعُ اللّٰہُ الرُّسُلَ فَیَقُوۡلُ مَا ذَاۤ اُجِبۡتُمۡ ؕ قَالُوۡا لَا عِلۡمَ  لَنَا ؕ اِنَّکَ اَنۡتَ عَلَّامُ  الۡغُیُوۡبِ ﴿۱۰۹﴾', 'وہ دن یاد رکھنے کے لائق ہے جس دن اللہ پیغمبروں کو جمع کرے گا پھر ان سے پوچھے گا کہ تمہیں کیا جواب ملا تھا وہ عرض کریں گے کہ ہمیں کچھ معلوم نہیں۔ تو ہی غیب کی باتوں سے واقف ہے۔', 'جس دن اللہ جمع کرے گا سب پیغمبروں کو پھر کہے گا تم کو کیا جواب ملا تھا [۲۵۷] وہ کہیں گے ہم کو خبر نہیں [۲۵۸] تو ہی ہے چھپی باتوں کو جاننے والا', 'On the Day when Allah will gather the Messengers together and say to them: \"What was the response you received (from men to your teaching)? They will say: \"We have no knowledge, verily, only You are the AllKnower of all that is hidden (or unseen, etc.).\"', '(Be mindful of) the day when Allah will assemble the messengers and will say to them, “How were you responded to?” They will say, “We have no knowledge. Surely You alone have the full knowledge of all that is unseen.”'),
(779, 5, 110, 15, 5, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'اِذۡ قَالَ اللّٰہُ یٰعِیۡسَی ابۡنَ مَرۡیَمَ اذۡکُرۡ نِعۡمَتِیۡ عَلَیۡکَ وَ عَلٰی وَالِدَتِکَ ۘ اِذۡ اَیَّدۡتُّکَ بِرُوۡحِ الۡقُدُسِ ۟ تُکَلِّمُ  النَّاسَ فِی الۡمَہۡدِ وَ کَہۡلًا ۚ وَ اِذۡ عَلَّمۡتُکَ الۡکِتٰبَ وَ الۡحِکۡمَۃَ وَ التَّوۡرٰىۃَ وَ الۡاِنۡجِیۡلَ ۚ وَ اِذۡ تَخۡلُقُ مِنَ الطِّیۡنِ کَہَیۡـَٔۃِ الطَّیۡرِ بِاِذۡنِیۡ فَتَنۡفُخُ فِیۡہَا فَتَکُوۡنُ طَیۡرًۢا بِاِذۡنِیۡ وَ تُبۡرِیُٔ الۡاَکۡمَہَ وَ الۡاَبۡرَصَ بِاِذۡنِیۡ ۚ وَ اِذۡ تُخۡرِجُ الۡمَوۡتٰی بِاِذۡنِیۡ ۚ وَ اِذۡ کَفَفۡتُ بَنِیۡۤ  اِسۡرَآءِیۡلَ عَنۡکَ اِذۡ جِئۡتَہُمۡ بِالۡبَیِّنٰتِ فَقَالَ الَّذِیۡنَ کَفَرُوۡا مِنۡہُمۡ  اِنۡ ہٰذَاۤ  اِلَّا سِحۡرٌ مُّبِیۡنٌ ﴿۱۱۰﴾', 'جب اللہ عیسٰی سے فرمائے گا کہ اے عیسٰی ابن مریم! میرے ان احسانوں کو یاد کرو جو میں نے تم پر اور تمہاری والدہ پر کئے جب میں نے روح القدس یعنی جبرئیل سے تمہاری مدد کی۔ تم گود میں اور جوان ہو کر بھی ایک ہی نسق پر لوگوں سے گفتگو کرتے تھے۔ اور جب میں نے تم کو کتاب اور دانائی اور تورات اور انجیل سکھائی اور جب تم میرے حکم سے مٹی کے پرندے کی شکل بناتے پھر اس میں پھونک مار دیتے تھے تو وہ میرے حکم سے سچ مچ کا پرندہ بن جاتا تھا اور پیدائشی اندھے کو اور برص کی بیماری والے کو میرے حکم سے اچھا کر دیتے تھے اور مردوں کو زندہ کر کے قبر سے نکال کھڑا کرتے تھے۔ اور جب میں نے بنی اسرائیل کے ہاتھوں کو تم سے روک دیا جب تم ان کے پاس کھلے ہوئے نشان لے کر آئے تو جو ان میں سے کافر تھے کہنے لگے کہ یہ تو کھلا جادو ہے۔', 'جب کہے گا اللہ [۲۵۹] اے عیسٰی مریم کے بیٹے یاد کر میرا احسان جو ہوا ہے تجھ پر اور تیری ماں پر [۲۶۰] جب مدد کی میں نے تیری روح پاک سے تو کلام کرتا تھا لوگوں سے گود میں اور بڑی عمر میں اور جب سکھائی میں نے تجھ کو کتاب اور تہہ کی باتیں اور توریت اور انجیل اور جب تو بناتا تھا گارے سے جانور کی صورت میرے حکم سے پھر پھونک مارتا تھا اسمیں تو ہو جاتا اڑنے والا میرے حکم سے اور اچھا کرتا تھا مادرزاد اندھے کو اور کوڑھی کو میرے حکم سے او رجب نکال کھڑا کرتا تھا مردوں کو میرے حکم سے [۲۶۱] اور جب روکا میں نے بنی اسرائیل کو تجھ سے جب تو لے کر آیا انکے پاس نشانیاں تو کہنے لگے جو کافر تھے ان میں اور کچھ نہیں یہ تو جادو ہے صریح [۲۶۲]', '(Remember) when Allah will say (on the Day of Resurrection). \"O Iesa (Jesus), son of Maryam (Mary)! Remember My Favour to you and to your mother when I supported you with RoohulQudus (Jibrael (Gabriel)) so that you spoke to the people in the cradle and in maturity; and when I taught you writing, AlHikmah (the power of understanding), the Taurat (Torah) and the Injeel (Gospel); and when you made out of the clay, as it were, the figure of a bird, by My Permission, and you breathed into it, and it became a bird by My Permission, and you healed those born blind, and the lepers by My Permission, and when you brought forth the dead by My Permission; and when I restrained the Children of Israel from you (when they resolved to kill you) since you came unto them with clear proofs, and the disbelievers among them said: This is nothing but evident magic. \"', '(Call to mind the time) when Allah will say, “O ‘Īsā, son of Maryam, remember My blessing upon you and upon your mother; when I supported you with the Holy Spirit. You spoke to people while you were still in the cradle and when you grew to middle age. I taught you the Book and the Wisdom, the Torah and the Injīl. You created from clay something in the shape of a bird, then you blew on it, and it became a bird by My leave. You cured those born blind and lepers by My leave.You raised the dead by My leave. I kept the children of Isrā’īl away from you when you came to them with clear signs, and the disbelievers among them said, “This is nothing but a clear magic.”'),
(780, 5, 111, 15, 5, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'وَ  اِذۡ  اَوۡحَیۡتُ اِلَی الۡحَوَارِیّٖنَ اَنۡ اٰمِنُوۡا بِیۡ  وَ بِرَسُوۡلِیۡ ۚ قَالُوۡۤا اٰمَنَّا وَ اشۡہَدۡ  بِاَنَّنَا مُسۡلِمُوۡنَ ﴿۱۱۱﴾', 'اور جب میں نے حواریوں کی طرف حکم بھیجا کہ مجھ پر اور میرے پیغمبر پر ایمان لاؤ۔ وہ کہنے لگے کہ پروردگار ہم ایمان لائے تو شاہد رہیو کہ ہم فرمانبردار ہیں۔', 'اور جب میں نے دل میں ڈال دیا حواریوں کے کہ ایمان لاؤ مجھ پر اور میرے رسول پر تو کہنے لگے ہم ایمان لائے اور تو گواہ رہ کہ ہم فرمانبردار ہیں', 'And when I (Allah) put in the hearts of Al-Hawareeeen (the disciples) (of Iesa (Jesus)) to believe in Me and My Messenger, they said: \"We believe. And bear witness that we are Muslims.\"', 'When I enjoined upon the disciples (of ‘Īsā ), “Believe in Me and in My Messenger,” they said, “We believed. Bear witness that we are the submitting ones.”'),
(781, 5, 112, 15, 5, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'اِذۡ   قَالَ الۡحَوَارِیُّوۡنَ یٰعِیۡسَی ابۡنَ  مَرۡیَمَ ہَلۡ یَسۡتَطِیۡعُ رَبُّکَ اَنۡ یُّنَزِّلَ عَلَیۡنَا مَآئِدَۃً مِّنَ السَّمَآءِ ؕ قَالَ اتَّقُوا اللّٰہَ اِنۡ  کُنۡتُمۡ  مُّؤۡمِنِیۡنَ ﴿۱۱۲﴾', 'وہ قصہ بھی یاد کرو جب حواریوں نے کہا کہ اے عیسٰی ابن مریم! کیا آپ کا پروردگار ایسا کر سکتا ہے کہ ہم پر آسمان سے کھانے کا خوان نازل کرے؟ فرمایا کہ اگر ایمان رکھتے ہو تو اللہ سے ڈرو۔', 'جب کہا حواریوں نے اے عیسٰی مریم کے بیٹے تیرا رب کر سکتا ہے [۲۶۳] کہ اتارے ہم پر خوان بھرا ہوا آسمان سے [۲۶۴] بولا ڈرو اللہ سے اگر ہو تم ایمان والے [۲۶۵]', '(Remember) when Al-Hawareeoon (the disciples) said: \"O Iesa (Jesus), son of Maryam (Mary)! Can your Lord send down to us a table spread (with food) from heaven?\" Iesa (Jesus) said: \"Fear Allah, if you are indeed believers.\"', 'When the disciples said, “O ‘Īsā, son of Maryam, can your Lord send down to us a repast from the heavens?” He said, “Fear Allah if you are believers.”'),
(782, 5, 113, 15, 5, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'قَالُوۡا نُرِیۡدُ اَنۡ  نَّاۡکُلَ  مِنۡہَا وَ تَطۡمَئِنَّ قُلُوۡبُنَا وَ نَعۡلَمَ اَنۡ قَدۡ صَدَقۡتَنَا وَ نَکُوۡنَ عَلَیۡہَا مِنَ الشّٰہِدِیۡنَ ﴿۱۱۳﴾', 'وہ بولے کہ ہماری یہ خواہش ہے کہ ہم اس میں سے کھائیں اور ہمارے دل تسلی پائیں اور ہم جان لیں کہ آپ نے ہم سے سچ کہا ہے اور ہم اس خوان کے نزول پر گواہ رہیں۔', 'بولے کہ ہم چاہتے ہیں کہ کھاویں اس میں سے اور مطمئن ہو جاویں ہمارے دل اور جان لیں کہ تو نے ہم سے سچ کہا او رہیں ہم اس پر گواہ [۲۶۶]', 'They said: \"We wish to eat thereof and to be stronger in Faith, and to know that you have indeed told us the truth and that we ourselves be its witnesses.\"', 'They said, “We wish that we eat from it, and our hearts be satisfied, and we may know for sure that you have told us the truth, and we may become witnesses to it.”'),
(783, 5, 114, 15, 5, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'قَالَ عِیۡسَی ابۡنُ مَرۡیَمَ اللّٰہُمَّ رَبَّنَاۤ اَنۡزِلۡ عَلَیۡنَا مَآئِدَۃً مِّنَ السَّمَآءِ تَکُوۡنُ لَنَا عِیۡدًا لِّاَوَّلِنَا وَ اٰخِرِنَا وَ اٰیَۃً مِّنۡکَ ۚ وَ ارۡزُقۡنَا وَ اَنۡتَ خَیۡرُ الرّٰزِقِیۡنَ ﴿۱۱۴﴾', 'تب عیسٰی ابن مریم نے دعا کی کہ اے ہمارے پروردگار ہم پر آسمان سے خوان نازل فرما کہ ہمارے لئے وہ دن عید قرار پائے یعنی ہمارے اگلوں اور پچھلوں سب کے لئے۔ اور وہ تیری طرف سے نشانی ہو اور ہمیں رزق دے اور تو بہترین رزق دینے والا ہے۔', 'کہا عیسٰی مریم کے بیٹے نے اے اللہ رب ہمارے اتار ہم پر خوان بھرا ہوا آسمان سے کہ وہ دن عید رہے ہماری پہلوں او رپچھلوں کے واسطے [۲۶۷] اور نشانی ہو تیری طرف سے [۲۶۸] اور روزی دے ہم کو اور تو ہی ہے سب سے بہتر روزی دینے والا [۲۶۹]', 'Iesa (Jesus), son of Maryam (Mary), said: \"O Allah, our Lord! Send us from heaven a table spread (with food) that there may be for us - for the first and the last of us - a festival and a sign from You; and provide us sustenance, for You are the Best of sustainers.\"', '‘Īsā son of Maryam said, “O Allah, our Lord, send down to us a repast from heaven which may be a happy occasion for us, for all our generations present and future, and a sign from You, and give us provisions. You are the best Giver of Provisions.”'),
(784, 5, 115, 15, 5, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'قَالَ اللّٰہُ اِنِّیۡ مُنَزِّلُہَا عَلَیۡکُمۡ ۚ فَمَنۡ یَّکۡفُرۡ بَعۡدُ مِنۡکُمۡ فَاِنِّیۡۤ  اُعَذِّبُہٗ عَذَابًا  لَّاۤ   اُعَذِّبُہٗۤ  اَحَدًا مِّنَ الۡعٰلَمِیۡنَ ﴿۱۱۵﴾٪', 'اللہ نے فرمایا میں تم پر ضرور خوان نازل فرماؤں گا مگر جو اسکے بعد تم میں سے کفر کرے گا اسے ایسا عذاب دوں گا کہ اہل عالم میں کسی کو ایسا عذاب نہ دوں گا۔', 'کہا اللہ نے میں بیشک اتاروں گا وہ خوان تم پر پھر جو کوئی تم میں ناشکری کرے گا اس کے بعد تو میں اس کو وہ عذاب دوں گا جو کسی کو نہ دوں گا جہان میں [۲۷۰]', 'Allah said: \"I am going to send it down unto you, but if any of you after that disbelieves, then I will punish him with a torment such as I have not inflicted on anyone among (all) the Alameen (mankind and jinns).\"', 'Allah said, “I am going to send it down to you; but whoever among you disbelieves after that, I shall give him such a punishment as I shall not give to anyone else in all the worlds.”'),
(785, 5, 116, 16, 6, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'وَ  اِذۡ قَالَ اللّٰہُ یٰعِیۡسَی ابۡنَ مَرۡیَمَ  ءَاَنۡتَ قُلۡتَ لِلنَّاسِ اتَّخِذُوۡنِیۡ وَ اُمِّیَ  اِلٰہَیۡنِ مِنۡ دُوۡنِ اللّٰہِ ؕ قَالَ سُبۡحٰنَکَ مَا یَکُوۡنُ لِیۡۤ  اَنۡ اَقُوۡلَ مَا لَیۡسَ لِیۡ ٭ بِحَقٍّ ؕ؃ اِنۡ کُنۡتُ قُلۡتُہٗ فَقَدۡ عَلِمۡتَہٗ ؕ تَعۡلَمُ  مَا فِیۡ نَفۡسِیۡ وَ لَاۤ اَعۡلَمُ مَا فِیۡ نَفۡسِکَ ؕ اِنَّکَ اَنۡتَ عَلَّامُ  الۡغُیُوۡبِ ﴿۱۱۶﴾', 'اور اس وقت کو بھی یاد رکھو جب اللہ فرمائے گا کہ اے عیسٰی ابن مریم! کیا تم نے لوگوں سے کہا تھا کہ اللہ کے سوا مجھے اور میری والدہ کو معبود مقرر کرو؟ وہ کہیں گے کہ تو پاک ہے مجھے کب شایاں تھا کہ میں ایسی بات کہتا جس کا مجھے کچھ حق نہیں۔ اگر میں نے ایسا کہا ہو گا تو تجھ کو معلوم ہو گا کیونکہ جو بات میرے جی میں ہے تو اسے جانتا ہے اور جو تیرے جی میں ہے اسے میں نہیں جانتا۔ بیشک تو علام الغیوب ہے۔', 'اور جب کہے گا اللہ اے عیسٰی مریم کے بیٹے تو نے کہا لوگوں کو کہ ٹھہرا لو مجھ کو اور میری ماں کو دو معبود سوا اللہ کے [۲۷۱] کہا تو پاک ہے مجھ کو لائق نہیں کہ کہوں ایسی بات جس کا مجھ کو حق نہیں اگر میں نے یہ کہا ہوگا تو تجھ کو ضرور معلوم ہو گا تو جانتا ہے جو میرے جی میں ہے اور میں نہیں جانتا جو تیرے جی میں ہے بیشک تو ہی ہے جاننے والا چھپی باتوں کا [۲۷۲]', 'And (remember) when Allah will say (on the Day of Resurrection): \"O Iesa (Jesus), son of Maryam (Mary)! Did you say unto men: Worship me and my mother as two gods besides Allah? \" He will say: \"Glory be to You! It was not for me to say what I had no right (to say). Had I said such a thing, You would surely have known it. You know what is in my innerself though I do not know what is in Yours, truly, You, only You, are the AllKnower of all that is hidden and unseen.', 'And when Allah said, “O ‘Īsā, son of Maryam, did you say to the people: ‘Take me and my mother as gods beside Allah?” He said, “Pure are You, it does not behoove me to say what is not right for me. Had I said it, You would have known it. You know what is in my heart, and I do not know what is in Your’s. You alone have full knowledge of all that is unseen.'),
(786, 5, 117, 16, 6, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'مَا قُلۡتُ لَہُمۡ اِلَّا مَاۤ اَمَرۡتَنِیۡ بِہٖۤ اَنِ اعۡبُدُوا اللّٰہَ رَبِّیۡ وَ رَبَّکُمۡ ۚ وَ کُنۡتُ عَلَیۡہِمۡ  شَہِیۡدًا مَّا دُمۡتُ فِیۡہِمۡ ۚ فَلَمَّا تَوَفَّیۡتَنِیۡ  کُنۡتَ اَنۡتَ الرَّقِیۡبَ عَلَیۡہِمۡ ؕ وَ  اَنۡتَ عَلٰی کُلِّ  شَیۡءٍ  شَہِیۡدٌ ﴿۱۱۷﴾', 'میں نے ان سے کچھ نہیں کہا بجز اسکے جس کا تو نے مجھے حکم دیا وہ یہ کہ تم اللہ کی عبادت کرو جو میرا اور تمہارا سب کا پروردگار ہے۔ اور جب تک میں ان میں رہا ان کے حالات کی خبر رکھتا رہا پھر جب تو نے مجھے دنیا سے اٹھا لیا تو تُو ہی انکا نگران تھا اور تو ہر چیز سے خبردار ہے۔', 'میں نے کچھ نہیں کہا انکو مگر جو تو نے حکم کیا کہ بندگی کرو اللہ کی جو رب ہے میرا اور تمہارا [۲۷۳] اور میں ان سے خبردار تھا جب تک ان میں رہا پھر جب تو نے مجھ کو اٹھا لیا تو تو ہی تھا خبر رکھنے والا ان  کی اور تو ہر چیز سے خبردار ہے [۲۷۴]', '\"Never did I say to them aught except what You (Allah) did command me to say: Worship Allah, my Lord and your Lord. And I was a witness over them while I dwelt amongst them, but when You took me up, You were the Watcher over them, and You are a Witness to all things. (This is a great admonition and warning to the Christians of the whole world).', 'I have not said to them anything but what You have ordered me to say, that is, ‘Worship Allah, my Lord and your Lord’ and I was a witness over them as long as I was with them. But when You recalled me, You were the One watching over them. You are a witness over everything.'),
(787, 5, 118, 16, 6, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'اِنۡ تُعَذِّبۡہُمۡ فَاِنَّہُمۡ عِبَادُکَ ۚ وَ اِنۡ تَغۡفِرۡ لَہُمۡ فَاِنَّکَ اَنۡتَ الۡعَزِیۡزُ الۡحَکِیۡمُ ﴿۱۱۸﴾', 'اگر تو انکو عذاب دے تو یہ تیرے بندے ہیں۔ اور اگر انہیں بخش دے تو تیری مہربانی اسلئے کہ تو ہی غالب ہے حکمت والا ہے۔', 'اگر تو انکو عذاب دے تو وہ بندے ہیں تیرے اور اگر تو ان کو معاف کر دے تو تو ہی ہے زبردست حکمت والا [۲۷۵]', '\"If You punish them, they are Your slaves, and if You forgive them, verily You, only You are the AllMighty, the AllWise.\"', 'If You punish them, they are Your slaves after all, but if You forgive them, You are the Mighty, the Wise.”'),
(788, 5, 119, 16, 6, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'قَالَ اللّٰہُ ہٰذَا یَوۡمُ یَنۡفَعُ الصّٰدِقِیۡنَ صِدۡقُہُمۡ ؕ لَہُمۡ جَنّٰتٌ تَجۡرِیۡ مِنۡ  تَحۡتِہَا الۡاَنۡہٰرُ  خٰلِدِیۡنَ  فِیۡہَاۤ  اَبَدًا ؕ رَضِیَ اللّٰہُ عَنۡہُمۡ وَ رَضُوۡا عَنۡہُ ؕ ذٰلِکَ الۡفَوۡزُ الۡعَظِیۡمُ ﴿۱۱۹﴾', 'اللہ فرمائے گا کہ آج وہ دن ہے کہ سچوں کو انکی سچائی ہی فائدہ دے گی۔ ان کے لئے باغ ہیں جن کے نیچے نہریں بہ رہی ہیں ہمیشہ ہمیشہ وہ ان میں بستے رہیں گے۔ اللہ ان سے خوش ہے اور وہ اللہ سے خوش ہیں۔ یہی بڑی کامیابی ہے۔', 'فرمایا اللہ نے یہ دن ہے کہ کام آوے گا سچوں کے ان کا سچ [۲۷۶] انکے لئے ہیں باغ جن کے نیچے بہتی ہیں نہریں رہا کریں گے انہی میں ہمیشہ اللہ راضی ہوا ان سے اور وہ راضی ہوئے اس سے یہی ہے بڑی کامیابی [۲۷۷]', 'Allah will say: \"This is a Day on which the truthful will profit from their truth: theirs are Gardens under which rivers flow (in Paradise) - they shall abide therein forever. Allah is pleased with them and they with Him. That is the great success (Paradise).', 'Allah will say, “This is a day on which the truth of the truthful shall benefit them. For them there are gardens beneath which rivers flow, where they will live forever. Allah is well-pleased with them and they are well-pleased with Him. That is the great achievement.'),
(789, 5, 120, 16, 6, 7, 'وَ  اِذَا سَمِعُوۡا', 'المآئدۃ', 'لِلّٰہِ مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ مَا فِیۡہِنَّ ؕ وَ ہُوَ  عَلٰی  کُلِّ  شَیۡءٍ  قَدِیۡرٌ ﴿۱۲۰﴾٪', 'آسمان اور زمین اور جو کچھ ان دونوں میں ہے سب پر اللہ ہی کی بادشاہی ہے۔ اور وہ ہر چیز پر قادر ہے۔', 'اللہ ہی کے لئے سلطنت ہے آسمانوں کی اور زمین کی اور جو کچھ ان کے بیچ میں ہے اور وہ ہر چیز پر قادر ہے [۲۷۸]', 'To Allah belongs the dominion of the heavens and the earth and all that is therein, and He is Able to do all things.', 'To Allah belongs the kingdom of the heavens and the earth and of whatever lies therein, and He is powerful over everything.'),
(790, 6, 1, 1, 7, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'اَلۡحَمۡدُ لِلّٰہِ الَّذِیۡ خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ وَ جَعَلَ الظُّلُمٰتِ وَ النُّوۡرَ ۬ؕ ثُمَّ  الَّذِیۡنَ  کَفَرُوۡا بِرَبِّہِمۡ  یَعۡدِلُوۡنَ  ﴿۱﴾', 'ہر طرح کی تعریف اللہ ہی کیلئے ہے جس نے آسمانوں اور زمین کو پیدا کیا اور اندھیرے اور روشنی بنائی پھر بھی کافر دوسری ہستیوں کو اپنے پروردگار کے برابر ٹھیراتے ہیں۔', '[۱] سب تعریفیں اللہ کےلئے ہیں جس نے پیدا کئے آسمان اور زمین اور بنایا اندھیرا اور اجالا پھر بھی یہ کافر اپنے رب کےساتھ اوروں کو برابر کئے دیتے ہیں [۲]', 'All praises and thanks be to Allah, Who (Alone) created the heavens and the earth, and originated the darkness and the light, yet those who disbelieve hold others as equal with their Lord.', 'All praise belongs to Allah who created the heavens and the earth, and made darkness and light; yet those who disbelieve equate (others) with their Lord.'),
(791, 6, 2, 1, 7, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'ہُوَ الَّذِیۡ خَلَقَکُمۡ مِّنۡ طِیۡنٍ ثُمَّ  قَضٰۤی اَجَلًا ؕ وَ اَجَلٌ مُّسَمًّی عِنۡدَہٗ  ثُمَّ  اَنۡتُمۡ تَمۡتَرُوۡنَ ﴿۲﴾', 'وہی تو ہے جس نے تم کو مٹی سے پیدا کیا پھر مرنے کا ایک وقت مقرر کر دیا۔ اور ایک مدت اسکے ہاں اور مقرر ہے۔ پھر بھی اے کافرو تم اس بارے میں شک کرتے ہو۔', 'وہی ہے جس نے پیدا کیا تم کو مٹی سے پھر مقرر کر دیا ایک وقت اور ایک مدت مقرر ہے اللہ کے نزدیک پھر بھی تم شک کرتے ہو [۳]', 'He it is Who has created you from clay, and then has decreed a stated term (for you to die). And there is with Him another determined term (for you to be resurrected), yet you doubt (in the Resurrection).', 'He is the One who created you from clay, then destined a term. The fixed term lies with Him, yet you are in doubt.'),
(792, 6, 3, 1, 7, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ ہُوَ اللّٰہُ فِی السَّمٰوٰتِ وَ فِی الۡاَرۡضِ ؕ یَعۡلَمُ سِرَّکُمۡ وَ جَہۡرَکُمۡ وَ یَعۡلَمُ مَا تَکۡسِبُوۡنَ ﴿۳﴾', 'اور آسمان اور زمین میں وہی اللہ تو ہے۔ وہ تمہاری پوشیدہ اور ظاہر سب باتیں جانتا ہے اور تم جو کام کرتے ہو وہ سب سے واقف ہے۔', 'اور وہی ہے اللہ آسمانوں میں اور زمین میں [۴] جانتا ہے تمہارا چھپا اور کھلا اور جانتا ہے جو کچھ تم کرتے ہو [۵]', 'And He is Allah (to be worshipped Alone) in the heavens and on the earth, He knows what you conceal and what you reveal, and He knows what you earn (good or bad).', 'He is the true God in the heavens and the earth. He knows what you conceal and what you reveal, and He knows what you earn.'),
(793, 6, 4, 1, 7, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ مَا تَاۡتِیۡہِمۡ مِّنۡ اٰیَۃٍ مِّنۡ اٰیٰتِ رَبِّہِمۡ  اِلَّا  کَانُوۡا عَنۡہَا مُعۡرِضِیۡنَ ﴿۴﴾', 'اور اللہ کی نشانیوں میں سے کوئی نشانی ان لوگوں کے پاس نہیں آتی مگر یہ اس سے منہ پھیر لیتے ہیں۔', 'اور نہیں آتی انکے پاس کوئی نشانی ان کے رب کی نشانیوں میں سے مگر کرتے ہیں اس سے تغافل [۶]', 'And never an Ayah (sign) comes to them from the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of their Lord, but that they have been turning away from it.', 'Yet whenever a sign from the signs of their Lord comes to them, they do nothing but turn away from it.'),
(794, 6, 5, 1, 7, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'فَقَدۡ  کَذَّبُوۡا بِالۡحَقِّ  لَمَّا جَآءَہُمۡ ؕ فَسَوۡفَ یَاۡتِیۡہِمۡ اَنۡۢبٰٓؤُا مَا کَانُوۡا بِہٖ یَسۡتَہۡزِءُوۡنَ ﴿۵﴾', 'جب انکے پاس حق آیا تو اسکو بھی انہوں جھٹلا دیا۔ سو انکو ان چیزوں کا جن سے یہ ہنسی کرتے ہیں عنقریب انجام معلوم ہو جائے گا۔', 'سو بیشک جھٹلایا انہوں نے حق کو جب ان تک پہنچا سو اب آئی جاتی ہے انکے آگے حقیقت اس بات کی جس پر ہنستے تھے [۷]', 'Indeed, they rejected the truth (the Quran and Muhammad SAW) when it came to them, but there will come to them the news of that (the torment) which they used to mock at.', 'So they rejected the truth when it came to them.Now there shall come to them a full account of what they used to ridicule.'),
(795, 6, 6, 1, 7, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'اَلَمۡ یَرَوۡا کَمۡ اَہۡلَکۡنَا مِنۡ قَبۡلِہِمۡ مِّنۡ قَرۡنٍ مَّکَّنّٰہُمۡ فِی الۡاَرۡضِ مَا لَمۡ نُمَکِّنۡ لَّکُمۡ وَ اَرۡسَلۡنَا السَّمَآءَ عَلَیۡہِمۡ مِّدۡرَارًا ۪ وَّ جَعَلۡنَا الۡاَنۡہٰرَ تَجۡرِیۡ مِنۡ تَحۡتِہِمۡ فَاَہۡلَکۡنٰہُمۡ بِذُنُوۡبِہِمۡ وَ اَنۡشَاۡنَا مِنۡۢ بَعۡدِہِمۡ  قَرۡنًا اٰخَرِیۡنَ ﴿۶﴾', 'کیا انہوں نے نہیں دیکھا کہ ہم نے ان سے پہلے کتنی امتوں کو ہلاک کر دیا جن کے پاؤں ملک میں ایسے جما دیئے تھے کہ تمہارے پاؤں بھی ایسے نہیں جمائے اور ان پر آسمان سے لگاتار مینہ برسایا اور نہریں بنا دیں جو ان کے مکانوں کے نیچے بہ رہی تھیں پھر ان کو ان کے گناہوں کے سبب ہلاک کر دیا اور ان کے بعد اور امتیں پیدا کر دیں۔', 'کیا دیکھتے نہیں کہ کتنی ہلاک کر دیں ہم نے ان سے پہلے امتیں جن کو جما دیا تھا ہم نے ملک میں اتنا کہ جتنا تم کو نہیں جمایا اور چھوڑ دیا ہم نے  ان پر آسمان کو لگاتار برستا ہوا اور بنا دیں ہم نے نہریں بہتی ہوئی ان کے نیچے پھر ہلاک کیا ہم نے انکو انکے گناہوں پر اور پیدا کیا ہم نے ان کے بعد اور امتوں کو [۸]', 'Have they not seen how many a generation before them We have destroyed whom We had established on the earth such as We have not established you? And We poured out on them rain from the sky in abundance, and made the rivers flow under them. Yet We destroyed them for their sins, and created after them other generations.', 'Have they not seen how many generations We have destroyed prior to them-those whom We had given such a strong position in the land as We did not give to you, and We poured on them abundant rains from the sky, and made rivers flow beneath them? Then We destroyed them because of their sins, and raised up another generation after them.'),
(796, 6, 7, 1, 7, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ لَوۡ نَزَّلۡنَا عَلَیۡکَ کِتٰبًا فِیۡ قِرۡطَاسٍ فَلَمَسُوۡہُ بِاَیۡدِیۡہِمۡ لَقَالَ الَّذِیۡنَ  کَفَرُوۡۤا اِنۡ ہٰذَاۤ  اِلَّا  سِحۡرٌ  مُّبِیۡنٌ ﴿۷﴾', 'اور اے پیغمبر اگر ہم تم پر کاغذوں پر لکھی ہوئی کوئی تحریر نازل کرتے اور یہ اسے اپنے ہاتھوں سے ٹٹول بھی لیتے۔ تو جو کافر ہیں وہ یہی کہہ دیتے کہ یہ تو صاف صاف جادو ہے۔', 'اور اگر اتاریں ہم تجھ پر لکھا ہوا کاغذ میں پھر چھو لیویں وہ اس کو اپنے ہاتھوں سے البتہ کہیں گے کافر یہ نہیں ہے مگر صریح جادو [۹]', 'And even if We had sent down unto you (O Muhammad SAW) a Message written on paper so that they could touch it with their hands, the disbelievers would have said: \"This is nothing but obvious magic!\"', 'If We had sent down to you something written on paper, and they had even touched it with their hands, still the disbelievers would have said, “This is nothing but obvious magic.”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(797, 6, 8, 1, 7, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ قَالُوۡا لَوۡ لَاۤ اُنۡزِلَ عَلَیۡہِ مَلَکٌ ؕ وَ لَوۡ اَنۡزَلۡنَا مَلَکًا لَّقُضِیَ الۡاَمۡرُ ثُمَّ لَا یُنۡظَرُوۡنَ ﴿۸﴾', 'اور کہتے ہیں کہ ان پیغمبر پر فرشتہ کیوں نازل نہ ہوا؟ جو انکی تصدیق کرتا اور اگر ہم فرشتہ نازل کرتے تو کام ہی فیصل ہو جاتا پھر انہیں مہلت بھی نہ دی جاتی۔', 'اور کہتے ہیں کیوں نہیں اترا اس پر کوئی فرشتہ [۱۰] اور اگر ہم اتاریں فرشتہ تو طے ہو جاوے قصہ پھر ان کو مہلت بھی نہ ملے [۱۱]', 'And they say: \"Why has not an angel been sent down to him?\" Had We sent down an angel, the matter would have been judged at once, and no respite would be granted to them.', 'They say, “Why is it that an angel has not been sent down to him?” Had We sent down an angel, the whole matter would have been closed, and thereafter no further time would have been allowed to them.'),
(798, 6, 9, 1, 7, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ لَوۡ جَعَلۡنٰہُ مَلَکًا لَّجَعَلۡنٰہُ رَجُلًا وَّ لَلَبَسۡنَا عَلَیۡہِمۡ  مَّا یَلۡبِسُوۡنَ ﴿۹﴾', 'نیز اگر ہم کسی فرشتے کو بھیجتے تو اسے مرد کی صورت میں ہی بھیجتے اور جو شبہ یہ اب کرتے ہیں اسی شبہے میں انہیں ڈال دیتے۔', 'اور اگر ہم رسول بنا کر بھیجتے کسی فرشتہ کو تو وہ بھی آدمی ہی کی صورت میں ہوتا اور انکو اسی شبہہ میں ڈالتے جس میں اب پڑ رہے ہیں [۱۲]', 'And had We appointed him an angel, We indeed would have made him a man, and We would have certainly caused them confusion in a matter which they have already covered with confusion (i.e. the Message of Prophet Muhammad SAW).', 'If We had made him an angel, We would have obviously made him a man, and would have caused them the same confusion they are causing now.'),
(799, 6, 10, 1, 7, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ لَقَدِ اسۡتُہۡزِیَٔ بِرُسُلٍ مِّنۡ قَبۡلِکَ فَحَاقَ بِالَّذِیۡنَ سَخِرُوۡا مِنۡہُمۡ مَّا کَانُوۡا بِہٖ  یَسۡتَہۡزِءُوۡنَ ﴿٪۱۰﴾', 'اور تم سے پہلے بھی پیغمبروں کے ساتھ ہنسی ہوتی رہی ہے پھر جو لوگ ان میں سے ہنسی کیا کرتے تھے انکو ہنسی کرنے کی سزا نے آ گھیرا۔', 'اور بلاشبہہ ہنسی کرتے رہے ہیں رسولوں سے تجھ سے پہلے پھرگھیر لیا ان سے ہنسی کرنے والوں کو اس چیز نے کہ جس پر ہنسا کرتے تھے [۱۳]', 'And indeed (many) Messengers were mocked before you, but their scoffers were surrounded by the very thing that they used to mock at.', 'Even before you (O Prophet,) many messengers were ridiculed. Those who laughed at them were, then, besieged by what they used to ridicule.'),
(800, 6, 11, 2, 8, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قُلۡ سِیۡرُوۡا فِی الۡاَرۡضِ ثُمَّ انۡظُرُوۡا کَیۡفَ کَانَ عَاقِبَۃُ  الۡمُکَذِّبِیۡنَ ﴿۱۱﴾', 'کہو کہ ملک میں چلو پھرو۔ پھر دیکھو کہ جھٹلانے والوں کا کیا انجام ہوا۔', 'تو کہہ دے کہ سیر کرو ملک میں پھر دیکھو کیا انجام ہوا جھٹلانے والوں کا [۱۴]', 'Say (O Muhammad SAW): \"Travel in the land and see what was the end of those who rejected truth.\"', 'Say, “Go about the earth, and see what was the fate of those who rejected (the prophets).”'),
(801, 6, 12, 2, 8, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قُلۡ لِّمَنۡ مَّا فِی السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ قُلۡ لِّلّٰہِ ؕ کَتَبَ عَلٰی نَفۡسِہِ الرَّحۡمَۃَ ؕ لَیَجۡمَعَنَّکُمۡ  اِلٰی یَوۡمِ الۡقِیٰمَۃِ  لَا  رَیۡبَ فِیۡہِ ؕ اَلَّذِیۡنَ خَسِرُوۡۤا اَنۡفُسَہُمۡ فَہُمۡ لَا یُؤۡمِنُوۡنَ ﴿۱۲﴾', 'کہو کہ آسمان اور زمین میں جو کچھ ہے کس کا ہے کہدو اللہ کا۔ اس نے اپنی ذات پاک پر رحمت کو لازم کر لیا ہے۔ وہ تم سب کو قیامت کے دن جس میں کچھ بھی شک نہیں ضرور جمع کرے گا جن لوگوں نے اپنے آپکو نقصان میں ڈال رکھا ہے وہ ایمان نہیں لاتے۔', 'پوچھ کہ کس کا ہے جو کچھ کہ ہے آسمانوں اور زمین میں کہہ دے اللہ کا ہے اس نے لکھی ہے اپنے ذمہ مہربانی البتہ تم کو اکٹھا کر دے گا قیامت کے دن تک کہ اس میں کچھ شک نہیں جو لوگ نقصان میں ڈال چکے اپنی جانوں کو وہی ایمان نہیں لاتے [۱۵]', 'Say (O Muhammad SAW): \"To whom belongs all that is in the heavens and the earth?\" Say: \"To Allah. He has prescribed Mercy for Himself. Indeed He will gather you together on the Day of Resurrection, about which there is no doubt. Those who destroy themselves will not believe (in Allah as being the only Ilah (God), and Muhammad SAW as being one of His Messengers, and in Resurrection, etc.).', 'Say, “To whom belongs all that is in the heavens and on the earth?” Say, “To Allah.” He has prescribed Mercy for Himself. He will surely gather you on the Day of Resurrection in which there is no doubt.Those who have brought loss to themselves are not going to believe.'),
(802, 6, 13, 2, 8, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ لَہٗ مَا سَکَنَ فِی الَّیۡلِ وَ النَّہَارِ ؕ وَ ہُوَ السَّمِیۡعُ  الۡعَلِیۡمُ ﴿۱۳﴾', 'اور جو مخلوق رات اور دن میں بستی ہے سب اسی کی ہے۔ اور وہ سنتا ہے جانتا ہے۔', 'اور اللہ ہی کا ہے جو کچھ کہ آرام پکڑتا ہے رات میں اور دن میں اور وہی ہے سب کچھ سننے والا جاننے والا', 'And to Him belongs whatsoever exists in the night and the day, and He is the AllHearing, the AllKnowing.\"', 'To Him belongs all that dwells in the night and the day. He is All-Hearing, All-Knowing.'),
(803, 6, 14, 2, 8, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قُلۡ اَغَیۡرَ اللّٰہِ اَتَّخِذُ وَلِیًّا  فَاطِرِ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ ہُوَ یُطۡعِمُ وَ لَا یُطۡعَمُ ؕ قُلۡ  اِنِّیۡۤ   اُمِرۡتُ اَنۡ اَکُوۡنَ اَوَّلَ مَنۡ اَسۡلَمَ وَ لَا تَکُوۡنَنَّ مِنَ الۡمُشۡرِکِیۡنَ ﴿۱۴﴾', 'کہو۔ کیا میں اللہ کو چھوڑ کر کسی اور کو مددگار بناؤں۔ کہ وہی تو آسمانوں اور زمین کا پیدا کرنے والا ہے اور وہی سب کو کھانا دیتا ہے اور خود کسی سے کھانا نہیں لیتا یہ بھی کہدو کہ مجھے یہ حکم ہوا ہے کہ میں سب سے پہلا فرمانبردار بنوں اور یہ کہ اے پیغمبر تم مشرکوں میں نہ ہونا۔', 'تو کہہ دے کیا اور کسی کو بناؤں اپنا مددگار اللہ کے سوا جو بنانے والا ہے آسمانوں اور زمین کا [۱۶] اور وہ سب کو کھلاتا ہے اور اسکو کوئی نہیں کھلاتا [۱۷] کہہ دے مجھ کو حکم ہوا ہے کہ سب سے پہلے حکم مانوں [۱۸] اور تو ہرگز نہ ہو شرک والا', 'Say (O Muhammad SAW): \"Shall I take as a Walee (helper, protector, etc.) any other than Allah, the Creator of the heavens and the earth? And it is He Who feeds but is not fed.\" Say: \"Verily, I am commanded to be the first of those who submit themselves to Allah (as Muslims).\" And be not you (O Muhammad SAW) of the Mushrikoon (polytheists, pagans, idolaters and disbelievers in the Oneness of Allah).', 'Say, “Would I take as guardian someone other than Allah Who is the Creator of the heavens and the earth, and Who feeds others, and is not fed by anyone?” Say, “I have been asked to be the first to submit (to Him) and never to be one of those who ascribe partners to Allah.”'),
(804, 6, 15, 2, 8, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قُلۡ  اِنِّیۡۤ  اَخَافُ اِنۡ عَصَیۡتُ رَبِّیۡ عَذَابَ  یَوۡمٍ عَظِیۡمٍ ﴿۱۵﴾', 'یہ بھی کہہ دو کہ اگر میں اپنے پروردگار کی نافرمانی کروں تو مجھے بڑے دن کے عذاب کا خوف ہے۔', 'تو کہہ میں ڈرتا ہوں اگر نافرمانی کروں اپنے رب کی ایک بڑے دن کے عذاب سے [۱۹]', 'Say: \"I fear, if I disobey my Lord, the torment of a Mighty Day.\"', 'Say, “If I disobey my Lord, I fear the punishment of a momentous day.”'),
(805, 6, 16, 2, 8, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'مَنۡ  یُّصۡرَفۡ عَنۡہُ یَوۡمَئِذٍ فَقَدۡ رَحِمَہٗ ؕ وَ ذٰلِکَ  الۡفَوۡزُ  الۡمُبِیۡنُ ﴿۱۶﴾', 'جس شخص سے اس روز عذاب ٹال دیا گیا اس پر اللہ نے بڑی مہربانی فرمائی۔ اور یہی کھلی کامیابی ہے۔', 'جس پر سے ٹل گیا وہ عذاب اس دن تو اس پر رحم کر دیا اللہ نے اور یہی ہے بڑی کامیابی [۲۰]', 'Who is averted from (such a torment) on that Day, (Allah) has surely been Merciful to him. And that would be the obvious success.', 'Whoever is spared from it (the punishment of that day) is, indeed, blessed with His mercy. That is the manifest achievement.'),
(806, 6, 17, 2, 8, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ اِنۡ یَّمۡسَسۡکَ اللّٰہُ بِضُرٍّ فَلَا کَاشِفَ لَہٗۤ  اِلَّا ہُوَ ؕ وَ  اِنۡ یَّمۡسَسۡکَ بِخَیۡرٍ فَہُوَ  عَلٰی کُلِّ شَیۡءٍ  قَدِیۡرٌ ﴿۱۷﴾', 'اور اگر اللہ تم کو کوئی سختی پہنچائے تو اسکے سوا اسکو کوئی دور کرنے والا نہیں اور اگر نعمت و راحت عطا کرے تو کوئی اسکو روکنے والا نہیں وہ ہر چیز پر قادر ہے۔', 'اور اگر پہنچاوے تجھ کو اللہ کچھ سختی تو کوئی اسکو دور کرنے والا نہیں سوا اسکے اور اگر تجھ کو پہنچاوےبھلائی تو وہ ہر چیز پر قادر ہے', 'And if Allah touches you with harm, none can remove it but He, and if He touches you with good, then He is Able to do all things.', 'If Allah causes you harm, there is no one to remove it except He Himself; and if He causes you good, then He is powerful over everything.'),
(807, 6, 18, 2, 8, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ ہُوَ الۡقَاہِرُ فَوۡقَ عِبَادِہٖ ؕ وَ ہُوَ الۡحَکِیۡمُ  الۡخَبِیۡرُ ﴿۱۸﴾', 'اور وہ اپنے بندوں پر غالب ہے۔ اور وہ دانا ہے خبردار ہے۔', 'اور اسی کا زور ہے اپنے بندوں پر اور وہی ہے بڑی حکمت والا سب کی خبر رکھنے  والا [۲۱]', 'And He is the Irresistible, above His slaves, and He is the All-Wise, WellAcquainted with all things.', 'He is Dominant over His servants, and He is the All-Wise, the All-Aware.'),
(808, 6, 19, 2, 8, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قُلۡ اَیُّ شَیۡءٍ اَکۡبَرُ شَہَادَۃً ؕ قُلِ اللّٰہُ ۟ۙ شَہِیۡدٌۢ بَیۡنِیۡ وَ  بَیۡنَکُمۡ ۟ وَ اُوۡحِیَ   اِلَیَّ  ہٰذَا الۡقُرۡاٰنُ لِاُنۡذِرَکُمۡ بِہٖ وَ مَنۡۢ بَلَغَ ؕ اَئِنَّکُمۡ  لَتَشۡہَدُوۡنَ اَنَّ مَعَ  اللّٰہِ اٰلِہَۃً  اُخۡرٰی ؕ قُلۡ  لَّاۤ  اَشۡہَدُ ۚ قُلۡ  اِنَّمَا ہُوَ اِلٰہٌ وَّاحِدٌ وَّ اِنَّنِیۡ بَرِیۡٓءٌ مِّمَّا تُشۡرِکُوۡنَ ﴿ۘ۱۹﴾', 'ان سے پوچھو کہ سب سے بڑھ کر قرین انصاف کس کی شہادت ہے کہہ دو کہ اللہ ہی مجھ میں اور تم میں گواہ ہے۔ اور یہ قرآن مجھ پر اسلئے اتارا گیا ہے کہ اسکے ذریعے سے تم کو اور جس شخص تک وہ پہنچ سکے آگاہ کر دوں۔ کیا تم لوگ اس بات کی شہادت دیتے ہو کہ اللہ کے ساتھ اور بھی معبود ہیں اے پیغمبر کہہ دو کہ میں تو ایسی شہادت نہیں دیتا۔ کہہ دو کہ صرف وہی ایک معبود ہے اور جنکو تم لوگ شریک بناتے ہو میں ان سے بیزار ہوں۔', 'تو پوچھ سب سے بڑا کون ہے کہہ دے اللہ گواہ ہے میرے اور تمہارے درمیان [۲۲] اور اترا ہے مجھ پر یہ قرآن تاکہ تم کو اس سے خبردار کر دوں اور جس کو یہ پہنچے کیا تم گواہی دیتے ہو کہ اللہ کے ساتھ معبود اور بھی ہیں تو کہہ دے میں تو گواہی نہ دوں گا کہہ دے وہی ہے معبود ایک اور میں بیزار ہوں تمہارے شرک سے [۲۳]', 'Say (O Muhammad SAW): \"What thing is the most great in witness?\" Say: \"Allah (the Most Great!) is Witness between me and you; this Quran has been revealed to me that I may therewith warn you and whomsoever it may reach. Can you verily bear witness that besides Allah there are other aliha (gods)?\" Say \"I bear no (such) witness!\" Say: \"But in truth He (Allah) is the only one Ilah (God). And truly I am innocent of what you join in worship with Him.\"', 'Say, “Whose testimony is the greatest?” Say, “Allah is the witness between me and you, and this Qur’ān has been revealed to me so that I should thereby warn you, and whomsoever it may reach. Do you really bear witness that there are other gods along with Allah?” Say, “I bear no such witness.” Say, “In fact, He is one God. I disown what you associate (with Him).”'),
(809, 6, 20, 2, 8, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'اَلَّذِیۡنَ اٰتَیۡنٰہُمُ الۡکِتٰبَ یَعۡرِفُوۡنَہٗ کَمَا یَعۡرِفُوۡنَ اَبۡنَآءَہُمۡ ۘ اَلَّذِیۡنَ خَسِرُوۡۤا اَنۡفُسَہُمۡ  فَہُمۡ  لَا  یُؤۡمِنُوۡنَ ﴿٪۲۰﴾', 'جن لوگوں کو ہم نے کتاب دی ہے وہ ان کو یعنی ہمارے پیغمبر کو اس طرح پہچانتے ہیں جس طرح اپنے بیٹوں کو پہچانا کرتے ہیں جنہوں نے اپنے آپ کو نقصان میں ڈال رکھا ہے وہ ایمان نہیں لاتے۔', 'جن کو ہم نے دی ہے کتاب وہ پہچانتے ہیں اسکو جیسے پہچانتے ہیں اپنے بیٹوں کو جو لوگ نقصان میں ڈال چکے اپنی جانوں کو  وہی ایمان نہیں لاتے [۲۴]', 'Those to whom We have given the Scripture (Jews and Christians) recognize him (i.e. Muhammad SAW as a Messenger of Allah, and they also know that there is no Ilah (God) but Allah and Islam is Allahs Religion), as they recognize their own sons. Those who destroy themselves will not believe. (Tafsir At-Tabaree)', 'Those to whom We have given the Book recognize him (the Messenger) as (certainly as) they would recognize their sons. Those who have brought loss to themselves, they are not going to believe.'),
(810, 6, 21, 3, 9, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ مَنۡ اَظۡلَمُ  مِمَّنِ افۡتَرٰی عَلَی اللّٰہِ  کَذِبًا اَوۡ  کَذَّبَ بِاٰیٰتِہٖ ؕ اِنَّہٗ لَا  یُفۡلِحُ  الظّٰلِمُوۡنَ ﴿۲۱﴾', 'اور اس شخص سے زیادہ کون ظالم ہے جس نے اللہ پر جھوٹ باندھا یا اسکی آیتوں کو جھٹلایا کچھ شک نہیں کہ ظالم لوگ کامیاب نہیں ہوں گے۔', 'اور اس سے زیادہ ظالم کون جو بہتان باندھے اللہ پر یا جھٹلا دے اسکی آیتوں کو بلاشک بھلائی نصیب نہیں ہوتی ظالموں کو [۲۵]', 'And who does more wrong than he who invents a lie against Allah or rejects His Ayat (proofs, evidences, verses, lessons, revelations, etc.)? Verily, the Zalimoon (polytheists and wrongdoers, etc.) shall never be successful.', 'Who is more unjust than one who invents a lie against Allah or rejects His signs? Beware, the unjust shall not prosper.'),
(811, 6, 22, 3, 9, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ یَوۡمَ نَحۡشُرُہُمۡ جَمِیۡعًا ثُمَّ نَقُوۡلُ لِلَّذِیۡنَ اَشۡرَکُوۡۤا اَیۡنَ شُرَکَآؤُکُمُ الَّذِیۡنَ کُنۡتُمۡ  تَزۡعُمُوۡنَ ﴿۲۲﴾', 'اور جس دن ہم سب لوگوں کو جمع کریں گے پھر مشرکوں سے پوچھیں گے کہ آج وہ تمہارے شریک کہاں ہیں جنکا تمہیں دعوٰی تھا۔', 'اور جس دن ہم جمع کریں گے ان سب کو پھر کہیں گے ان لوگوں کو جنہوں نے شرک کیا تھا کہاں ہیں شریک تمہارے جن کا تم کو دعویٰ تھا [۲۶]', 'And on the Day when We shall gather them all together, We shall say to those who joined partners in worship (with Us): \"Where are your partners (false deities) whom you used to assert (as partners in worship with Allah)?\"', '(Be mindful of) the Day We shall gather them together, then We will say to those who associated partners with Allah, “Where are those you claimed to be partners of Allah?”'),
(812, 6, 23, 3, 9, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'ثُمَّ لَمۡ تَکُنۡ فِتۡنَتُہُمۡ  اِلَّاۤ  اَنۡ قَالُوۡا وَ اللّٰہِ  رَبِّنَا مَا کُنَّا مُشۡرِکِیۡنَ ﴿۲۳﴾', 'تو ان سےکچھ عذر نہ بن پڑے گا اور بجز اسکے کچھ چارہ نہ ہوگا کہ کہیں اللہ کی قسم جو ہمارا پروردگار ہے ہم شریک نہیں بناتے تھے۔', 'پھر نہ رہے گا انکے پاس کوئی فریب مگر  یہی کہ کہیں گے قسم ہے اللہ کی جو ہمارا رب ہے ہم نہ تھے شرک کرنے والے [۲۷]', 'There will then be (left) no Fitnah (excuses or statements or arguments) for them but to say: \"By Allah, our Lord, we were not those who joined others in worship with Allah.\"', 'Then, they will have no other mischievous move but that they will say, “By Allah, our Lord, we ascribed no partners to Allah.”'),
(813, 6, 24, 3, 9, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'اُنۡظُرۡ  کَیۡفَ کَذَبُوۡا عَلٰۤی اَنۡفُسِہِمۡ  وَ ضَلَّ عَنۡہُمۡ  مَّا  کَانُوۡا یَفۡتَرُوۡنَ ﴿۲۴﴾', 'دیکھو انہوں نے اپنے اوپر کیسا جھوٹ بولا اور جو کچھ یہ افترا کیا کرتے تھے سب ان سے جاتا رہا۔', 'دیکھو تو کیسا جھوٹ بولے اپنے اوپر اور کھوئی گئیں ان سے وہ باتیں جو بنایا کرتے تھے [۲۸]', 'Look! How they lie against themselves! But the (lie) which they invented will disappear from them.', 'See how they will lie about themselves, and all that they used to forge will vanish from them.'),
(814, 6, 25, 3, 9, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ  مِنۡہُمۡ مَّنۡ  یَّسۡتَمِعُ  اِلَیۡکَ ۚ وَ جَعَلۡنَا عَلٰی قُلُوۡبِہِمۡ  اَکِنَّۃً  اَنۡ یَّفۡقَہُوۡہُ  وَ فِیۡۤ  اٰذَانِہِمۡ  وَقۡرًا  ؕ وَ  اِنۡ  یَّرَوۡا کُلَّ  اٰیَۃٍ  لَّا یُؤۡمِنُوۡا بِہَا ؕ حَتّٰۤی  اِذَا جَآءُوۡکَ یُجَادِلُوۡنَکَ یَقُوۡلُ  الَّذِیۡنَ کَفَرُوۡۤا اِنۡ ہٰذَاۤ  اِلَّاۤ  اَسَاطِیۡرُ الۡاَوَّلِیۡنَ ﴿۲۵﴾', 'اور ان میں بعض ایسے ہیں کہ تمہاری باتوں کی طرف کان دھرتے ہیں اور ہم نے ان کے دلوں پر تو پردے ڈال دیئے ہیں کہ انکو سمجھ نہ سکیں اور کانوں میں بوجھ ڈال دیا ہے کہ سن نہ سکیں اور اگر یہ تمام نشانیاں بھی دیکھ لیں تب بھی ان پر ایمان نہ لائیں یہاں تک کہ جب تمہارے پاس تم سے بحث کرنے کو آتے ہیں تو جو کافر ہیں کہتے ہیں یہ قرآن اور کچھ بھی نہیں صرف پہلے لوگوں کی کہانیاں ہیں۔', 'اور بعضے ان میں کان لگائے رہتے ہیں تیری طرف اور ہم نے ان کے دلوں پر ڈال رکھے ہیں پردے تاکہ اس کو نہ سمجھیں اور رکھ دیا انکےکانوں میں بوجھ اور اگر دیکھ لیں تمام نشانیاں تو بھی ایمان نہ لاویں ان پر [۲۹] یہاں تک کہ جب آتے ہیں تیرے پاس تجھ سےجھگڑنے کو تو کہتے ہیں وہ کافر نہیں ہے یہ مگر کہانیاں پہلے لوگوں کی', 'And of them there are some who listen to you; but We have set veils on their hearts, so they understand it not, and deafness in their ears; if they see every one of the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) they will not believe therein; to the point that when they come to you to argue with you, the disbelievers say: \"These are nothing but tales of the men of old.\"', 'There are those among them who (apparently) listen to you, but We have put coverings on their hearts, so that they do not understand, and heaviness in their ears. If they were to see all the signs, they would still not believe in them, so much so that, when they come to quarrel with you, the disbelievers say (of the Qur’ān), “It is nothing but tales of the ancients.”'),
(815, 6, 26, 3, 9, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ ہُمۡ یَنۡہَوۡنَ عَنۡہُ  وَ یَنۡـَٔوۡنَ عَنۡہُ ۚ وَ اِنۡ یُّہۡلِکُوۡنَ  اِلَّاۤ  اَنۡفُسَہُمۡ وَ مَا یَشۡعُرُوۡنَ ﴿۲۶﴾', 'وہ اس سے اوروں کو بھی روکتے ہیں اور خود بھی پرے رہتے ہیں۔ مگر ان باتوں سے اپنے آپ ہی کو ہلاک کرتے ہیں اور اس بات سے بےخبر ہیں۔', 'اور یہ لوگ روکتے ہیں اس سے اور بھاگتے ہیں اس سے اور نہیں ہلاک کرتے مگر اپنے آپ کو اور نہیں سمجھتے [۳۰]', 'And they prevent others from him (from following Prophet Muhammad SAW) and they themselves keep away from him, and (by doing so) they destroy not but their ownselves, yet they perceive (it) not.', 'From it (the Qur’ān) they prevent others, and from it they keep themselves away. They ruin none but their own selves, while they do not realize it.'),
(816, 6, 27, 3, 9, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ لَوۡ تَرٰۤی  اِذۡ  وُقِفُوۡا عَلَی النَّارِ فَقَالُوۡا یٰلَیۡتَنَا نُرَدُّ  وَ لَا  نُکَذِّبَ بِاٰیٰتِ رَبِّنَا وَ نَکُوۡنَ  مِنَ  الۡمُؤۡمِنِیۡنَ ﴿۲۷﴾', 'کاش تم ان کو اس وقت دیکھو جب یہ دوزخ کے کنارے کھڑے کئے جائیں گے اور کہیں گے کہ اے کاش ہم پھر دنیا میں لوٹا دیئے جائیں تاکہ اپنے پروردگار کی آیتوں کی تکذیب نہ کریں اور مومن ہو جائیں۔', 'اور اگر تو دیکھے جس وقت کہ کھڑے کئے جاویں گے وہ دوزخ پر پس کہیں گے اے کاش ہم پھر بھیجدئے جاویں اور ہم نہ جھٹلائیں اپنے رب کی آیتوں کو اور ہو جاویں ہم ایمان والوں میں [۳۱]', 'If you could but see when they will be held over the (Hell) Fire! They will say: \"Would that we were but sent back (to the world)! Then we would not deny the Ayat (proofs, evidences, verses, lessons, revelations, etc.) of our Lord, and we would be of the believers!\"', 'If only you could (be there to) see when they will be made to stand by the Fire, and they will say, “Would that we were sent back, then we would not reject the signs of our Lord, and would join the believers.”'),
(817, 6, 28, 3, 9, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'بَلۡ بَدَا لَہُمۡ مَّا کَانُوۡا یُخۡفُوۡنَ مِنۡ  قَبۡلُ ؕ وَ لَوۡ رُدُّوۡا لَعَادُوۡا لِمَا نُہُوۡا عَنۡہُ وَ اِنَّہُمۡ  لَکٰذِبُوۡنَ ﴿۲۸﴾', 'ہاں یہ جو کچھ پہلے چھپایا کرتے تھے آج ان پر ظاہر ہو گیا ہے اور اگر یہ دنیا میں لوٹائے بھی جائیں تو جن کاموں سے ان کو منع کیا گیا تھا وہی پھر کرنے لگیں کچھ شک نہیں کہ یہ جھوٹے ہیں۔', 'کوئی نہیں بلکہ ظاہر ہو گیا جو چھپاتے تھے پہلے [۳۲] اور اگر پھر بھیجے جاویں تو پھر بھی وہی کام کریں جس سے منع کئے گئے تھے اور وہ بیشک جھوٹے ہیں [۳۳]', 'Nay, it has become manifest to them what they had been concealing before. But if they were returned (to the world), they would certainly revert to that which they were forbidden. And indeed they are liars.', 'In fact, what they were concealing earlier will become clear to them. If they were sent back, they would again go for what they were forbidden from, as they are sheer liars.'),
(818, 6, 29, 3, 9, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ قَالُوۡۤا اِنۡ ہِیَ  اِلَّا حَیَاتُنَا الدُّنۡیَا وَ مَا نَحۡنُ بِمَبۡعُوۡثِیۡنَ ﴿۲۹﴾', 'اور کہتے ہیں کہ ہماری جو دنیا کی زندگی ہے بس یہی زندگی ہے اور ہم مرنے کے بعد پھر زندہ نہیں کئے جائیں گے۔', 'اور کہتے ہیں ہمارےلئے زندگی نہیں مگر یہی دنیا کی اور ہم کو پھر نہیں زندہ ہونا [۳۴]', 'And they said: \"There is no (other life) but our (present) life of this world, and never shall we be resurrected (on the Day of Resurrection).\"', 'They say, “There is nothing but this worldly life of ours, and we are not going to be raised again.”'),
(819, 6, 30, 3, 9, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ لَوۡ تَرٰۤی اِذۡ  وُقِفُوۡا عَلٰی رَبِّہِمۡ ؕ قَالَ اَلَیۡسَ ہٰذَا بِالۡحَقِّ ؕ قَالُوۡا بَلٰی وَ رَبِّنَا ؕ قَالَ فَذُوۡقُوا الۡعَذَابَ بِمَا کُنۡتُمۡ تَکۡفُرُوۡنَ ﴿٪۳۰﴾', 'اور کاش تم انکو اس وقت دیکھو جب یہ اپنے پروردگار کے سامنے کھڑے کئے جائیں گے وہ فرمائے گا کیا یہ دوبارہ زندہ ہونا برحق نہیں تو کہیں گے کیوں نہیں ہمارے پروردگار کی قسم بالکل برحق ہے اللہ فرمائے گا اب کفر کے بدلے جو دنیا میں کرتے تھے عذاب کے مزے چکھو۔', 'اور کاش کہ تو دیکھے جس وقت وہ کھڑے کئے جاویں گے اپنے رب کے سامنے فرمائے  گا کیا یہ سچ نہیں کہیں گے کیوں نہیں قسم ہے اپنے رب کی فرمائے گا تو چکھو عذاب بدلے میں اپنے کفر کے [۳۵]', 'If you could but see when they will be held (brought and made to stand) in front of their Lord! He will say: \"Is not this (Resurrection and the taking of the accounts) the truth?\" They will say: \"Yes, by our Lord!\" He will then say: \"So taste you the torment because you used not to believe.\"', 'If only you could see when they will be made to stand before their Lord! He will say, “Is this not true?” They will say, “Of course, by our Lord, it is.” He will say, “Then, taste the punishment, for you used to disbelieve.”'),
(820, 6, 31, 4, 10, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قَدۡ خَسِرَ الَّذِیۡنَ کَذَّبُوۡا بِلِقَآءِ اللّٰہِ ؕ حَتّٰۤی  اِذَا جَآءَتۡہُمُ السَّاعَۃُ  بَغۡتَۃً  قَالُوۡا یٰحَسۡرَتَنَا عَلٰی مَا فَرَّطۡنَا فِیۡہَا ۙ وَ ہُمۡ یَحۡمِلُوۡنَ اَوۡزَارَہُمۡ عَلٰی ظُہُوۡرِہِمۡ ؕ اَلَا سَآءَ  مَا یَزِرُوۡنَ ﴿۳۱﴾', 'جن لوگوں نے اللہ کے روبرو حاضر ہونے کو جھوٹ سمجھا وہ گھاٹے میں آ گئے۔ یہاں تک کہ جب ان پر قیامت ناگہاں آ موجود ہو گی تو بول اٹھیں گے کہ ہائے اس کوتاہی پر افسوس ہے جو ہم نے قیامت کے بارے میں کی۔ اور وہ اپنے اعمال کے بوجھ اپنی پیٹھوں پر اٹھائے ہوئے ہونگے۔ دیکھو جو بوجھ یہ اٹھا رہے ہیں بہت برا ہے۔', 'تباہ ہوئے وہ لوگ جنہوں نے جھوٹ جانا ملنا اللہ کا یہاں تک کہ جب آ پہنچے گی ان پر قیامت اچانک تو کہیں گے اے افسوس کیسی کوتاہی ہم نے اس میں کی اور وہ اٹھاویں گے اپنے بوجھ اپنی پیٹھوں پر خبردار ہو جاؤ کہ برا بوجھ ہے جس کو وہ اٹھاویں گے [۳۶]', 'They indeed are losers who denied their Meeting with Allah, until all of a sudden, the Hour (signs of death) is on them, and they say: \"Alas for us that we gave no thought to it,\" while they will bear their burdens on their backs; and evil indeed are the burdens that they will bear!', 'Losers indeed are those who deny that they will ever face Allah, until when the Hour will come upon them suddenly, they will say, “Alas! We have been negligent about it.” They shall carry their burdens on their backs. Beware! Evil is the burden they carry.'),
(821, 6, 32, 4, 10, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ مَا الۡحَیٰوۃُ  الدُّنۡیَاۤ  اِلَّا  لَعِبٌ وَّ لَہۡوٌ ؕ وَ  لَلدَّارُ الۡاٰخِرَۃُ  خَیۡرٌ  لِّلَّذِیۡنَ  یَتَّقُوۡنَ ؕ اَفَلَا  تَعۡقِلُوۡنَ ﴿۳۲﴾', 'اور دنیا کی زندگی تو ایک کھیل اور مشغلہ ہے۔ اور بہت اچھا گھر تو آخرت کا گھر ہے یعنی انکے لئے جو اللہ سے ڈرتے ہیں۔ کیا تم سمجھتے نہیں۔', 'اور نہیں ہے زندگانی دنیا کی مگر کھیل اور جی بھلانا اور آخرت کا گھر بہتر ہے پرہیزگاروں کے لئے کیا تم نہیں سمجھتے [۳۷]', 'And the life of this world is nothing but play and amusement. But far better is the house in the Hereafter for those who are AlMuttaqoon (the pious - see V.2:2). Will you not then understand?', 'The worldly life is nothing but a game and fun, and the last abode is surely much better for those who fear Allah. Would you still not understand?'),
(822, 6, 33, 4, 10, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قَدۡ نَعۡلَمُ  اِنَّہٗ  لَیَحۡزُنُکَ الَّذِیۡ یَقُوۡلُوۡنَ فَاِنَّہُمۡ لَا یُکَذِّبُوۡنَکَ وَ لٰکِنَّ الظّٰلِمِیۡنَ  بِاٰیٰتِ  اللّٰہِ  یَجۡحَدُوۡنَ ﴿۳۳﴾', 'ہم کو معلوم ہے اے نبی کہ ان کافروں کی باتیں تمہیں رنج پہنچاتی ہیں مگر یہ تمہاری تکذیب نہیں کرتے بلکہ ظالم اللہ کی آیتوں سے انکار کرتے ہیں۔', 'ہم کو معلوم ہے کہ تجھ کو غم میں ڈالتی ہیں ان کی باتیں سو وہ تجھ کو نہیں جھٹلاتے لیکن یہ ظالم تو اللہ کی آیتوں کا انکار کرتے ہیں', 'We know indeed the grief which their words cause you (O Muhammad SAW): it is not you that they deny, but it is the Verses (the Quran) of Allah that the Zalimoon (polytheists and wrongdoers) deny.', 'Indeed We know that what they say makes you sad, because it is not you whom they reject, but the transgressors actually deny the signs of Allah.'),
(823, 6, 34, 4, 10, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ  لَقَدۡ  کُذِّبَتۡ رُسُلٌ مِّنۡ قَبۡلِکَ فَصَبَرُوۡا عَلٰی مَا کُذِّبُوۡا وَ اُوۡذُوۡا حَتّٰۤی اَتٰہُمۡ  نَصۡرُنَا ۚ وَ لَا مُبَدِّلَ  لِکَلِمٰتِ اللّٰہِ ۚ وَ لَقَدۡ جَآءَکَ مِنۡ نَّبَاِی الۡمُرۡسَلِیۡنَ ﴿۳۴﴾', 'اور تم سے پہلے بھی پیغمبر جھٹلائے جاتے رہے۔ تو وہ تکذیب اور ایذا پر صبر کرتے رہے یہاں تک کہ ان کے پاس ہماری مدد پہنچتی رہی۔ اور اللہ کی باتوں کو کوئی بھی بدلنے والا نہیں۔ اور تمکو پیغمبروں کے احوال کی خبریں پہنچ چکی ہیں تو تم بھی صبر سے کام لو۔', 'اور جھٹلائے گئے ہیں بہت سے رسول تجھ سے پہلے پس صبر کرتے رہے جھٹلانے پر اور ایذا پر یہاں تک کہ پہنچی ان کو مدد ہماری اور کوئی نہیں بدل سکتا للہ کی باتیں اور تجھ کو پہنچ چکے ہیں کچھ حالات رسولوں کے [۳۸]', 'Verily, (many) Messengers were denied before you (O Muhammad SAW), but with patience they bore the denial, and they were hurt, till Our Help reached them, and none can alter the Words (Decisions) of Allah. Surely there has reached you the information (news) about the Messengers (before you).', 'Indeed, many messengers have been rejected before you, but they stood patient against their rejection, and they were persecuted until Our help came to them. No one can change the words of Allah, and of course, some accounts of the messengers have already come to you.'),
(824, 6, 35, 4, 10, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ اِنۡ کَانَ  کَبُرَ عَلَیۡکَ اِعۡرَاضُہُمۡ فَاِنِ اسۡتَطَعۡتَ اَنۡ تَبۡتَغِیَ نَفَقًا فِی الۡاَرۡضِ اَوۡ  سُلَّمًا فِی السَّمَآءِ  فَتَاۡتِیَہُمۡ  بِاٰیَۃٍ ؕ وَ لَوۡ شَآءَ اللّٰہُ  لَجَمَعَہُمۡ عَلَی الۡہُدٰی فَلَا تَکُوۡنَنَّ مِنَ  الۡجٰہِلِیۡنَ ﴿۳۵﴾', 'اور اگر ان کی روگردانی تم پر شاق گذرتی ہے تو اگر طاقت ہو تو زمین میں کوئی سرنگ ڈھونڈ نکالو یا آسمان میں سیڑھی تلاش کرو پھر ان کے پاس کوئی معجزہ لاؤ۔ اور اگر اللہ چاہتا تو سب کو ہدایت پر جمع کر دیتا۔ پس تم ہر گز نادانوں میں نہ ہونا۔', 'اور اگر تجھ پر گراں ہے ان کا منہ پھیرنا تو اگر تجھ سے ہو سکے کہ ڈھونڈ نکالے کوئی سرنگ زمین میں یا کوئی سیڑھی آسمان میں پھر لاوے انکے پاس ایک معجزہ اور اگر اللہ چاہتا تو جمع کر دیتا سب کو سیدھی راہ پر سو تو مت ہو نادانوں میں [۳۹]', 'If their aversion (from you, O Muhammad SAW and from that with which you have been sent) is hard on you, (and you cannot be patient from their harm to you), then if you were able to seek a tunnel in the ground or a ladder to the sky, so that you may bring them a sign (and you cannot do it, so be patient). And had Allah willed, He could have gathered them together (all) unto true guidance, so be not you one of those who are Al-Jahiloon (the ignorant).', 'If their aversion is too hard on you, then seek, if you can, a tunnel into the earth or a ladder unto the sky in order to bring them a sign. Had Allah so willed, He would have brought all of them to the right path. So, never be one of the ignorant.'),
(825, 6, 36, 4, 10, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'اِنَّمَا یَسۡتَجِیۡبُ الَّذِیۡنَ یَسۡمَعُوۡنَ  ؕؔ وَ الۡمَوۡتٰی یَبۡعَثُہُمُ اللّٰہُ  ثُمَّ  اِلَیۡہِ یُرۡجَعُوۡنَ ﴿؃ ۳۶﴾', 'بات یہ ہے کہ حق کو قبول وہی کرتے ہیں جو سنتے بھی ہیں۔ اور مردوں کو تو اللہ قیامت ہی کو اٹھائے گا پھر اسی کی طرف لوٹ کر جائیں گے۔', 'مانتے وہی ہیں جو سنتے ہیں اور مردوں کو زندہ کرے گا اللہ پھر اسکی طرف لائے جاویں گے [۴۰]', 'It is only those who listen (to the Message of Prophet Muhammad SAW), will respond (benefit from it), but as for the dead (disbelievers), Allah will raise them up, then to Him they will be returned (for their recompense).', 'Only those respond who listen (to seek the truth). As for the dead, Allah shall raise them, after which they shall be returned to Him.'),
(826, 6, 37, 4, 10, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ قَالُوۡا لَوۡ لَا نُزِّلَ عَلَیۡہِ  اٰیَۃٌ  مِّنۡ رَّبِّہٖ ؕ قُلۡ  اِنَّ اللّٰہَ  قَادِرٌ عَلٰۤی  اَنۡ یُّنَزِّلَ  اٰیَۃً  وَّ لٰکِنَّ  اَکۡثَرَ ہُمۡ  لَا  یَعۡلَمُوۡنَ ﴿۳۷﴾', 'اور کہتے ہیں کہ ان پر ان کے پروردگار کے پاس سے کوئی نشانی کیوں نازل نہیں ہوئی۔ کہدو کہ اللہ نشانی اتارنے پر قادر ہے لیکن اکثر لوگ نہیں جانتے۔', 'اور کہتےہیں کیوں نہیں اتری اس پر کوئی نشانی اسکے رب کی طرف سے [۴۱] کہہ دے کہ اللہ کو قدرت ہے اس بات پر کہ اتارے نشانی لیکن ان میں اکثر نہیں جانتے [۴۲]', 'And they said: \"Why is not a sign sent down to him from his Lord?\" Say: \"Allah is certainly Able to send down a sign, but most of them know not.\"', 'They say, “Why is it that no sign (of our choice) has been sent down to him from his Lord?” Say, “Allah is surely powerful enough to send down a sign.” But most of them do not know.'),
(827, 6, 38, 4, 10, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ مَا مِنۡ  دَآبَّۃٍ  فِی الۡاَرۡضِ وَ لَا طٰٓئِرٍ یَّطِیۡرُ  بِجَنَاحَیۡہِ  اِلَّاۤ  اُمَمٌ  اَمۡثَالُکُمۡ ؕ مَا فَرَّطۡنَا فِی الۡکِتٰبِ مِنۡ شَیۡءٍ  ثُمَّ   اِلٰی رَبِّہِمۡ  یُحۡشَرُوۡنَ ﴿۳۸﴾', 'اور زمین میں جو چلنے پھرنے والا حیوان یا اپنے پروں سے اڑنے والا پرندہ ہے انکی بھی تم لوگوں کی طرح جماعتیں ہیں۔ ہم نے کتاب یعنی لوح محفوظ میں کسی چیز کے لکھنے میں کوتاہی نہیں کی پھر سب اپنے پروردگار کی طرف جمع کئے جائیں گے۔', 'اور نہیں ہے کوئی چلنے والا زمین میں اور نہ کوئی پرندہ کہ اڑتا ہے اپنے دو بازوؤں سے مگر ہر ایک امت ہے تمہاری طرح ہم نےنہیں چھوڑی لکھنے میں کوئی چیز پھر سب اپنے رب کے سامنے جمع ہوں گے [۴۳]', 'There is not a moving (living) creature on earth, nor a bird that flies with its two wings, but are communities like you. We have neglected nothing in the Book, then unto their Lord they (all) shall be gathered.', 'There is no creature moving on the earth, nor a bird flying on its two wings, but they are all communities like you. We have not missed anything in the Book. Then, to their Lord all of them shall be gathered.'),
(828, 6, 39, 4, 10, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ الَّذِیۡنَ کَذَّبُوۡا بِاٰیٰتِنَا صُمٌّ  وَّ بُکۡمٌ  فِی الظُّلُمٰتِ ؕ مَنۡ  یَّشَاِ اللّٰہُ  یُضۡلِلۡہُ ؕ وَ مَنۡ یَّشَاۡ  یَجۡعَلۡہُ  عَلٰی  صِرَاطٍ مُّسۡتَقِیۡمٍ ﴿۳۹﴾', 'اور جن لوگوں نے ہماری آیتوں کو جھٹلایا وہ بہرے اور گونگے ہیں اسکے علاوہ اندھیروں میں پڑے ہوئے جسکو اللہ چاہے گمراہ رہنے دے اور جسے چاہے سیدھے رستے پر چلا دے۔', 'اور جو جھٹلاتے ہیں ہماری آیتوں کو وہ بہرے اور گونگے ہیں اندھیروں میں [۴۴] جسکو چاہے اللہ گمراہ کرے [۴۵] اور جس کو چاہے ڈال دے سیدھی راہ پر', 'Those who reject Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) are deaf and dumb in darkness. Allah sends astray whom He wills and He guides on the Straight Path whom He wills.', 'Those who gave the lie to Our signs are deaf and dumb, in layers of darkness. He lets whomsoever He wills go astray, and brings whomsoever He wills on the straight path.'),
(829, 6, 40, 4, 10, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قُلۡ  اَرَءَیۡتَکُمۡ   اِنۡ  اَتٰىکُمۡ عَذَابُ اللّٰہِ اَوۡ اَتَتۡکُمُ السَّاعَۃُ  اَغَیۡرَ اللّٰہِ تَدۡعُوۡنَ ۚ اِنۡ  کُنۡتُمۡ  صٰدِقِیۡنَ ﴿۴۰﴾', 'کہو کافرو بھلا دیکھو تو اگر تم پر اللہ کا عذاب آ جائے یا قیامت آ موجود ہو۔ تو کیا تم ایسی حالت میں اللہ کے سوا کسی اور کو پکارو گے؟ اگر سچے ہو تو بتاؤ۔', 'تو کہہ دیکھو تو اگر آوے تم پر عذاب اللہ کا یا آوے تم پر قیامت کیا اللہ کے سوا کسی اور کو پکارو گے بتاؤ اگر تم سچے ہو', 'Say (O Muhammad SAW): \"Tell me if Allahs Torment comes upon you, or the Hour comes upon you, would you then call upon any one other than Allah? (Reply) if you are truthful!\"', 'Say, “Tell me if the punishment of Allah comes to you or the Hour befalls you, would you call someone other than Allah, if you are truthful?”'),
(830, 6, 41, 4, 10, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'بَلۡ اِیَّاہُ  تَدۡعُوۡنَ فَیَکۡشِفُ مَا تَدۡعُوۡنَ اِلَیۡہِ  اِنۡ شَآءَ وَ تَنۡسَوۡنَ مَا تُشۡرِکُوۡنَ ﴿٪۴۱﴾', 'نہیں بلکہ مصیبت کے وقت تم اسی کو پکارتے ہو تو جس دکھ کے لئے اسے پکارتے ہو وہ اگر چاہتا ہے تو اسکو دور کر دیتا ہے اور جنکو تم شریک بناتے ہو اس وقت انہیں بھول جاتے ہو۔', 'بلکہ اسی کو پکارتے ہو پھر دور کر دیتا ہے اس مصیبت کو جس کے لئے اسکو پکارتے ہو اگر چاہتا ہے اور تم بھول جاتے ہو جنکو شریک کرتے تھے [۴۶]', 'Nay! To Him Alone you call, and, if He will, He would remove that (distress) for which you call upon Him, and you forget at that time whatever partners you joined with Him (in worship)!', 'Rather, Him alone you will call and He, if He wills, shall remove what you call Him for, and you will forget those you associate with Him.'),
(831, 6, 42, 5, 11, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ لَقَدۡ اَرۡسَلۡنَاۤ  اِلٰۤی  اُمَمٍ مِّنۡ قَبۡلِکَ فَاَخَذۡنٰہُمۡ بِالۡبَاۡسَآءِ وَ الضَّرَّآءِ لَعَلَّہُمۡ یَتَضَرَّعُوۡنَ ﴿۴۲﴾', 'اور ہم نے تم سے پہلے بہت سی امتوں کی طرف پیغمبر بھیجے۔ پھر ان کی نافرمانیوں کے سبب ہم انہیں سختیوں اور تکلیفوں میں پکڑتے رہے تاکہ عاجزی کریں۔', 'اور ہم نے رسول بھیجے  تھے بہت سی امتوں پر تجھ سے پہلے پھر ان کو پکڑا ہم نے سختی میں اور تکلیف میں تاکہ وہ گڑگڑاویں', 'Verily, We sent (Messengers) to many nations before you (O Muhammad SAW). And We seized them with extreme poverty (or loss in wealth) and loss in health with calamities so that they might believe with humility.', 'We did send messengers to communities before you and put them to hardships and sufferings, so that they may supplicate in humility.'),
(832, 6, 43, 5, 11, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'فَلَوۡلَاۤ  اِذۡ جَآءَہُمۡ بَاۡسُنَا تَضَرَّعُوۡا وَ لٰکِنۡ  قَسَتۡ قُلُوۡبُہُمۡ وَ زَیَّنَ لَہُمُ الشَّیۡطٰنُ  مَا  کَانُوۡا  یَعۡمَلُوۡنَ ﴿۴۳﴾', 'تو جب ان پر ہمارا عذاب آتا رہا وہ کیوں نہیں عاجزی کرتے رہے۔ مگر ان کے تو دل ہی سخت ہو گئے تھے اور جو کام وہ کرتے تھے شیطان ان کو ان کی نظروں میں آراستہ کر دکھاتا تھا۔', 'پھر کیوں نہ گڑگڑائے جب آیا ان پر عذاب ہمارا لیکن سخت ہو گئے دل انکے اور بھلے کر دکھلائے ان کو شیطان نے جو کام وہ کر رہے تھے', 'When Our Torment reached them, why then did they not believe with humility? But their hearts became hardened, and Shaitan (Satan) made fairseeming to them that which they used to do.', 'Why then, did they not supplicate in humility when a calamity from Us came upon them? Instead, their hearts were hardened and Satan adorned for them what they were doing.'),
(833, 6, 44, 5, 11, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'فَلَمَّا نَسُوۡا مَا  ذُکِّرُوۡا بِہٖ  فَتَحۡنَا عَلَیۡہِمۡ  اَبۡوَابَ کُلِّ شَیۡءٍ ؕ حَتّٰۤی  اِذَا فَرِحُوۡا بِمَاۤ  اُوۡتُوۡۤا اَخَذۡنٰہُمۡ بَغۡتَۃً  فَاِذَا ہُمۡ مُّبۡلِسُوۡنَ ﴿۴۴﴾', 'پھر جب انہوں نے اس نصیحت کو جو انکو کی گئ تھی فراموش کر دیا تو ہم نے ان پر ہر چیز کے دروازے کھول دیئے یہاں تک کہ جب ان چیزوں سے جو انکو دی گئ تھیں خوب خوش ہو گئے تو ہم نے انکو ناگہاں پکڑ لیا اور وہ اس وقت مایوس ہو کر رہ گئے۔', 'پھر جب وہ بھول گئے اس نصیحت کو جو انکو کی گئ تھی کھول دیے ہم نے ان پر دروازے ہر چیز کے یہاں تک کہ جب وہ خوش ہوئے ان چیزوں پر جو انکو دی گئیں پکڑ لیا ہم نے انکو اچانک پس اس وقت وہ رہ گئے نا امید [۴۷]', 'So, when they forgot (the warning) with which they had been reminded, We opened to them the gates of every (pleasant) thing, until in the midst of their enjoyment in that which they were given, all of a sudden, We took them to punishment, and lo! They were plunged into destruction with deep regrets and sorrows.', 'Thereafter, when they forgot the advice they were given, We opened for them doors of everything, so that when they became proud of what they were given, We seized them suddenly and they were left in despair.'),
(834, 6, 45, 5, 11, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'فَقُطِعَ   دَابِرُ الۡقَوۡمِ الَّذِیۡنَ ظَلَمُوۡا ؕ وَ الۡحَمۡدُ  لِلّٰہِ  رَبِّ الۡعٰلَمِیۡنَ ﴿۴۵﴾', 'غرض ظالم لوگوں کی جڑ کاٹ دی گئ اور سب تعریف اللہ رب العالمین ہی کیلئے ہے۔', 'پھر کٹ گئ جڑ ان ظالموں کی اور سب تعریفیں اللہ ہی کے لئے ہیں جو پالنے والا ہے سارے جہان کا [۴۸]', 'So the roots of the people who did wrong were cut off. And all the praises and thanks be to Allah, the Lord of the Alameen (mankind, jinns, and all that exists).', 'Thus, the people who did wrong were uprooted to the last man; Praise be to Allah, the Lord of the worlds.'),
(835, 6, 46, 5, 11, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قُلۡ  اَرَءَیۡتُمۡ  اِنۡ  اَخَذَ اللّٰہُ سَمۡعَکُمۡ وَ اَبۡصَارَکُمۡ  وَ خَتَمَ عَلٰی قُلُوۡبِکُمۡ مَّنۡ  اِلٰہٌ  غَیۡرُ  اللّٰہِ  یَاۡتِیۡکُمۡ  بِہٖ ؕ اُنۡظُرۡ  کَیۡفَ نُصَرِّفُ الۡاٰیٰتِ ثُمَّ ہُمۡ یَصۡدِفُوۡنَ ﴿۴۶﴾', 'ان کافروں سے کہو کہ بھلا دیکھو تو اگر اللہ تمہارے کان اور آنکھیں چھین لے اور تمہارے دلوں پر مہر لگا دے تو اللہ کے سوا کونسا معبود ہے جو تمہیں یہ نعمتیں پھر بخشے؟ دیکھو ہم کس کس طرح اپنی آیتیں بیان کرتے ہیں۔ پھر بھی یہ لوگ روگردانی کئے جاتے ہیں۔', 'تو کہہ دیکھو تو اگر چھین لے اللہ تمہارےکان اور آنکھیں اور مہر کر دے تمہارے دلوں پر [۴۹] تو کون ایسا رب ہے اللہ کے سوا جو تم کو یہ چیزیں لا دیوے [۵۰] دیکھ ہم کیونکر طرح طرح سے بیان کرتے ہیں باتیں پھر بھی وہ کنارہ کرتے ہیں', 'Say (to the disbelievers): \"Tell me, if Allah took away your hearing and your sight, and sealed up your hearts, who is there - an ilah (a god) other than Allah who could restore them to you?\" See how variously We explain the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), yet they turn aside.', 'Say, “Tell me, if Allah takes away your hearing and your sights and sets a seal on your hearts, which god other than Allah can bring these back to you?” See how We put forth Our verses in various forms? Yet, still they turn away.'),
(836, 6, 47, 5, 11, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قُلۡ  اَرَءَیۡتَکُمۡ   اِنۡ  اَتٰىکُمۡ عَذَابُ اللّٰہِ بَغۡتَۃً  اَوۡ جَہۡرَۃً  ہَلۡ یُہۡلَکُ  اِلَّا الۡقَوۡمُ  الظّٰلِمُوۡنَ ﴿۴۷﴾', 'کہو کہ بھلا بتاؤ تو اگر تم پر اللہ کا عذاب بیخبری میں یا خبر آنیکے بعد آئے تو کیا ظالم لوگوں کے سوا کوئی اور بھی ہلاک ہو گا؟', 'تو کہہ دیکھو تو اگر آوے تم پر عذاب اللہ کا اچانک [۵۱] یا ظاہر ہو کر تو کون ہلاک ہو گا ظالم لوگوں کےسوا [۵۲]', 'Say: \"Tell me, if the punishment of Allah comes to you suddenly (during the night), or openly (during the day), will any be destroyed except the Zalimoon (polytheists and wrong-doing people)?\"', 'Say, “Tell me if the punishment of Allah comes upon you whether suddenly or openly, shall any people be destroyed except the unjust?’'),
(837, 6, 48, 5, 11, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ مَا نُرۡسِلُ الۡمُرۡسَلِیۡنَ  اِلَّا مُبَشِّرِیۡنَ وَ مُنۡذِرِیۡنَ ۚ فَمَنۡ اٰمَنَ وَ اَصۡلَحَ فَلَا خَوۡفٌ عَلَیۡہِمۡ  وَ لَا  ہُمۡ  یَحۡزَنُوۡنَ ﴿۴۸﴾', 'اور ہم جو پیغمبروں کو بھیجتے رہے ہیں تو خوشخبری سنانے اور ڈرانے کو پھر جو شخص ایمان لائے اور نیکوکار ہو جائے تو ایسے لوگوں کو نہ کچھ خوف ہو گا اور نہ وہ غمگین ہوں گے۔', 'اور ہم رسول نہیں بھیجتے مگر خوشی اور ڈر سنانے کو پھر جو کوئی ایمان لایا اور سنور گیا تو نہ ڈر ہے ان پر اور نہ وہ غمگین ہوں', 'And We send not the Messengers but as givers of glad tidings and as warners. So whosoever believes and does righteous good deeds, upon such shall come no fear, nor shall they grieve.', 'We do not send the messengers but as bearers of good tidings and as warners. So, those who believe and correct themselves, there will be no fear for them, nor shall they grieve,'),
(838, 6, 49, 5, 11, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ الَّذِیۡنَ کَذَّبُوۡا بِاٰیٰتِنَا یَمَسُّہُمُ الۡعَذَابُ بِمَا  کَانُوۡا یَفۡسُقُوۡنَ ﴿۴۹﴾', 'اور جنہوں نے ہماری آیتوں کو جھٹلایا ان کی نافرمانیوں کے سبب انہیں عذاب  پہنچے گا۔', 'اور جنہوں نے جھٹلایا ہماری آیتوں کو انکو پہنچے گا عذاب اس لئے کہ وہ نافرمانی کرتے تھے  [۵۳]', 'But those who reject Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), the torment will touch them for their disbelief (and for their belying the Message of Muhammad SAW). (Tafsir Al-Qurtubee).', 'whereas those who have rejected Our signs, torment shall afflict them, because they used to commit sins.'),
(839, 6, 50, 5, 11, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قُلۡ  لَّاۤ  اَقُوۡلُ لَکُمۡ عِنۡدِیۡ خَزَآئِنُ اللّٰہِ وَ لَاۤ  اَعۡلَمُ الۡغَیۡبَ وَ لَاۤ  اَقُوۡلُ لَکُمۡ  اِنِّیۡ مَلَکٌ ۚ اِنۡ  اَتَّبِعُ  اِلَّا مَا یُوۡحٰۤی  اِلَیَّ ؕ قُلۡ ہَلۡ  یَسۡتَوِی الۡاَعۡمٰی وَ الۡبَصِیۡرُ ؕ اَفَلَا  تَتَفَکَّرُوۡنَ ﴿٪۵۰﴾', 'کہہ دو کہ میں تم سے یہ نہیں کہتا کہ میرے پاس اللہ تعالیٰ کے خزانے ہیں اور نہ یہ کہ میں غیب جانتا ہوں اور نہ تم سے یہ کہتا ہوں کہ میں فرشتہ ہوں۔ میں تو صرف اس حکم پر چلتا ہوں جو مجھے اللہ کی طرف سے آتا ہے۔ کہہ دو کہ بھلا اندھا اور آنکھ والا برابر ہوتے ہیں؟ تو پھر تم غور کیوں نہیں کرتے؟', 'تو کہہ میں نہیں کہتا تم سے کہ میرے پاس ہیں خزانے اللہ کے اور نہ میں جانوں غیب کی بات اور نہ میں کہوں تم سے کہ میں فرشتہ ہوں [۵۴] میں تو اسی پر چلتا ہوں جو میرے پاس اللہ کا حکم آتا ہے تو کہہ دے کب برابر ہو سکتا ہے اندھا اور دیکھنے والا سو کیا تم غور نہیں کرتے [۵۵]', 'Say (O Muhammad SAW): \"I dont tell you that with me are the treasures of Allah, nor (that) I know the unseen; nor I tell you that I am an angel. I but follow what is revealed to me by inspiration.\" Say: \"Are the blind and the one who sees equal? will you not then take thought?\"', 'Say, “I do not say to you that I have the treasures of Allah, nor do I have the knowledge of the Unseen, nor do I say to you that I am an angel. I only follow what is revealed to me.” Say, “Are the blind and the seeing alike? Do you, then, not reflect?”'),
(840, 6, 51, 6, 12, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ اَنۡذِرۡ بِہِ الَّذِیۡنَ یَخَافُوۡنَ  اَنۡ یُّحۡشَرُوۡۤا  اِلٰی رَبِّہِمۡ لَیۡسَ لَہُمۡ مِّنۡ دُوۡنِہٖ وَلِیٌّ  وَّ لَا شَفِیۡعٌ  لَّعَلَّہُمۡ  یَتَّقُوۡنَ ﴿۵۱﴾', 'اور جو لوگ خوف رکھتے ہیں کہ اپنے پروردگار کے روبرو حاضر کئے جائیں گے اور جانتے ہیں کہ اسکے سوا نہ تو ان کا کوئی دوست ہو گا اور نہ سفارش کرنے والا۔ انکو اس قرآن کے ذریعے سے نصیحت کرو تاکہ پرہیزگار بنیں۔', 'اور خبردار کر دے اس قرآن سے ان لوگوں کو جنکو ڈر ہے اسکا کہ وہ جمع ہونگے اپنے رب کے سامنے اس طرح پر کہ اللہ کے سوا نہ کوئی انکا حمایتی ہو گا اور نہ سفارش کرنے والا [۵۶] تاکہ وہ بچتے رہیں [۵۷]', 'And warn therewith (the Quran) those who fear that they will be gathered before their Lord, when there will be neither a protector nor an intercessor for them besides Him, so that they may fear Allah and keep their duty to Him (by abstaining from committing sins and by doing all kinds of good deeds which He has ordained).', 'Warn, with it, those who have the fear of being gathered before their Lord, with no one other than Him to support or to intercede. Maybe they become God-fearing.'),
(841, 6, 52, 6, 12, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ لَا تَطۡرُدِ الَّذِیۡنَ یَدۡعُوۡنَ رَبَّہُمۡ بِالۡغَدٰوۃِ  وَ الۡعَشِیِّ  یُرِیۡدُوۡنَ وَجۡہَہٗ ؕ مَا عَلَیۡکَ مِنۡ  حِسَابِہِمۡ  مِّنۡ شَیۡءٍ  وَّ مَا مِنۡ حِسَابِکَ عَلَیۡہِمۡ  مِّنۡ  شَیۡءٍ فَتَطۡرُدَہُمۡ  فَتَکُوۡنَ  مِنَ الظّٰلِمِیۡنَ ﴿۵۲﴾', 'اور جو لوگ صبح  شام اپنے پروردگار سے دعا کرتے ہیں اور اسکی توجہ کے طالب ہیں انکو اپنے پاس سے مت نکالو۔ انکے حساب اعمال کی جوابدہی تم پر کچھ نہیں اور تمہارے حساب کی جوابدہی ان پر کچھ نہیں۔ پس ایسا نہ کرنا اگر انکو نکالو گے تو ظالموں میں ہو جاؤ گے۔', 'اور مت دور کر ان لوگوں کو جو پکارتے ہیں اپنے رب کو صبح اور شام اور چاہتے ہیں اسی کی رضا [۵۸] تجھ پر نہیں ہے ان کے حساب میں سے کچھ اور نہ تیرے حساب میں سے ان پر ہے کچھ کہ تو ان کو دور کرنے لگے پس ہو جاوے گا تو بے انصافوں میں [۵۹]', 'And turn not away those who invoke their Lord, morning and afternoon seeking His Face. You are accountable for them in nothing, and they are accountable for you in nothing, that you may turn them away, and thus become of the Zalimoon (unjust).', 'Do not expel those who call out to their Lord morning and evening seeking His pleasure. You are not responsible for anything in their account, and they are not responsible for anything in your account, that you should expel them, and thus become one of the unjust.'),
(842, 6, 53, 6, 12, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ کَذٰلِکَ فَتَنَّا بَعۡضَہُمۡ بِبَعۡضٍ لِّیَقُوۡلُوۡۤا اَہٰۤؤُلَآءِ مَنَّ اللّٰہُ عَلَیۡہِمۡ مِّنۡۢ بَیۡنِنَا ؕ اَلَیۡسَ اللّٰہُ  بِاَعۡلَمَ بِالشّٰکِرِیۡنَ ﴿۵۳﴾', 'اور اسی طرح ہم نے بعض لوگوں کی بعض سے آزمائش کی ہے کہ جو دولتمند ہیں وہ غریبوں کی نسبت کہتے ہیں کیا یہی لوگ ہیں جن پر اللہ نے ہم میں سے فضل کیا ہے کیا اللہ شکر کرنے والوں سے واقف نہیں؟', 'اور اسی طرح ہم نے آزمایا ہے بعضے لوگوں کو بعضوں سے تاکہ کہیں کیا یہی لوگ ہیں جن پر اللہ نے فضل کیا ہم سب میں کیا نہیں ہے اللہ خوب جاننے والا شکر کرنے والوں کو [۶۰]', 'Thus We have tried some of them with others, that they might say: \"Is it these (poor believers) that Allah has favoured from amongst us?\" Does not Allah know best those who are grateful?', 'Thus We have tested some of them through others, so that they should say, “Are these the ones among all of us whom Allah has chosen for His favour?” Yes, does Allah not know well who are the grateful?'),
(843, 6, 54, 6, 12, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ  اِذَا جَآءَکَ الَّذِیۡنَ یُؤۡمِنُوۡنَ بِاٰیٰتِنَا فَقُلۡ سَلٰمٌ عَلَیۡکُمۡ  کَتَبَ رَبُّکُمۡ عَلٰی نَفۡسِہِ  الرَّحۡمَۃَ ۙ اَنَّہٗ  مَنۡ  عَمِلَ  مِنۡکُمۡ سُوۡٓءًۢ ابِجَہَالَۃٍ  ثُمَّ تَابَ مِنۡۢ  بَعۡدِہٖ  وَ  اَصۡلَحَ  فَاَنَّہٗ  غَفُوۡرٌ  رَّحِیۡمٌ ﴿۵۴﴾', 'اور جب تمہارے پاس ایسے لوگ آیا کریں جو ہماری آیتوں پر ایمان لاتے ہیں تو ان سے کہو سلام علیکم تمہارے رب نے اپنی ذات پاک پر رحمت کو لازم کر لیا ہے کہ جو کوئی تم میں سے نادانی سے کوئی بری حرکت کر بیٹھے پھر اس کے بعد توبہ کر لے اور نیکوکار ہو جائے تو وہ بخشنے والا ہے مہربان ہے۔', 'اور جب آویں تیرے پاس ہماری آیتوں کے ماننے والے تو کہہ دے تو سلام ہے تم پر لکھ لیا ہے تمہارے رب نے اپنے اوپر رحمت کو کہ جو کوئی کرے تم میں سے برائی ناواقفیت سے پھر اس کے  بعد توبہ کر لے اور نیک ہو جائے تو بات یہ ہےکہ وہ ہے بخشنے والا مہربان', 'When those who believe in Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) come to you, say: \"Salamun Alaikum\" (peace be on you); your Lord has written Mercy for Himself, so that, if any of you does evil in ignorance, and thereafter repents and does righteous good deeds (by obeying Allah), then surely, He is OftForgiving, Most Merciful.', 'When those who believe in Our verses come to you, say to them, “Peace on you. Your Lord has prescribed for Himself mercy, so that if any one of you does an evil deed out of ignorance and thereafter repents and mends his ways, then (you will see that) He is Most-Forgiving, Very-Merciful.'),
(844, 6, 55, 6, 12, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ کَذٰلِکَ نُفَصِّلُ الۡاٰیٰتِ وَ لِتَسۡتَبِیۡنَ سَبِیۡلُ  الۡمُجۡرِمِیۡنَ ﴿٪۵۵﴾', 'اور اسی طرح ہم اپنی آیتیں کھول کھول کر بیان کرتے ہیں تاکہ تم لوگ ان پر عمل کرو اور اس لئے کہ گناہگاروں کا رستہ ظاہر ہو جائے۔', 'اور اسی طرح ہم تفصیل سے بیان کرتے ہیں آیتوں کو اور تاکہ کھل جاوےطریقہ گنہگاروں کا [۶۱]', 'And thus do We explain the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) in detail, that the way of the Mujrimoon (criminals, polytheists, sinners), may become manifest.', 'This is how We explain the verses in detail, so that the way of the guilty may become exposed.'),
(845, 6, 56, 7, 13, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قُلۡ  اِنِّیۡ نُہِیۡتُ اَنۡ اَعۡبُدَ الَّذِیۡنَ تَدۡعُوۡنَ مِنۡ دُوۡنِ اللّٰہِ ؕ قُلۡ  لَّاۤ  اَتَّبِعُ  اَہۡوَآءَکُمۡ ۙ  قَدۡ ضَلَلۡتُ اِذًا وَّ مَاۤ  اَنَا مِنَ  الۡمُہۡتَدِیۡنَ ﴿۵۶﴾', 'اے پیغمبر کفار سے کہدو کہ جنکو تم اللہ کے سوا پکارتے ہو مجھے ان کی عبادت سے منع کیا گیا ہے یہ بھی کہدو کہ میں تمہاری خواہشوں کی پیروی نہیں کرونگا ایسا کروں تو گمراہ ہو جاؤں اور ہدایت یافتہ لوگوں میں نہ رہوں۔', 'تو کہہ دے مجھ کو روکا گیا ہے اس سے کہ بندگی کروں انکی جن کو تم پکارتے ہو اللہ کے سوا تو کہہ میں نہیں چلتا تمہاری خوشی پر بیشک اب تو میں بہک جاؤں گا اور نہ رہوں گا ہدایت پانے والوں میں [۶۲]', 'Say (O Muhammad SAW): \"I have been forbidden to worship those whom you invoke (worship) besides Allah.\" Say: \"I will not follow your vain desires. If I did, I would go astray, and I would not be one of the rightly guided.\"', 'Say, “I have been forbidden from worshiping those whom you invoke beside Allah.” Say, “I do not follow your desires, because if I were to do that, I would be going astray and would no more be of those on the right path.”'),
(846, 6, 57, 7, 13, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قُلۡ  اِنِّیۡ عَلٰی بَیِّنَۃٍ  مِّنۡ رَّبِّیۡ وَ  کَذَّبۡتُمۡ  بِہٖ ؕ مَا عِنۡدِیۡ مَا تَسۡتَعۡجِلُوۡنَ بِہٖ ؕ اِنِ الۡحُکۡمُ  اِلَّا لِلّٰہِ ؕ یَقُصُّ الۡحَقَّ وَ ہُوَ  خَیۡرُ الۡفٰصِلِیۡنَ ﴿۵۷﴾', 'کہدو کہ میں تو اپنے پروردگار کی دلیل روشن پر ہوں اور تم اسکی تکذیب کرتے ہو۔ جس چیز یعنی عذاب کے لئے تم جلدی کر رہے ہو۔ وہ میرے پاس نہیں ہے ایسا حکم اللہ ہی کے اختیار میں ہے وہ سچی بات بیان فرماتا ہے اور وہ سب سے بہتر فیصلہ کرنے والا ہے۔', 'تو کہہ دے کہ مجھ کو شہادت پہنچی میرے رب کی اور تم نے اسکو جھٹلایا [۶۳] میرے پاس نہیں جس چیز کی تم جلدی کر رہے ہو [۶۴] حکم کسی کا نہیں سوا اللہ کے بیان کرتا ہے حق بات اور وہ سب سے اچھا فیصلہ کرنے والا ہے', 'Say (O Muhammad SAW): \"I am on clear proof from my Lord (Islamic Monotheism), but you deny (the truth that has come to me from Allah). I have not gotten what you are asking for impatiently (the torment). The decision is only for Allah, He declares the truth, and He is the Best of judges.\"', 'Say, “I am on clear guidance from my Lord, and you have cried lies to it. That which you demand to be hastened is not up to me. The Decision belongs to none but Allah. He relates the Truth and He is the best of all judges.'),
(847, 6, 58, 7, 13, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قُلۡ لَّوۡ اَنَّ عِنۡدِیۡ مَا تَسۡتَعۡجِلُوۡنَ بِہٖ لَقُضِیَ الۡاَمۡرُ بَیۡنِیۡ وَ بَیۡنَکُمۡ ؕ وَ اللّٰہُ اَعۡلَمُ  بِالظّٰلِمِیۡنَ ﴿۵۸﴾', 'کہدو کہ جس چیز کے لئے تم جلدی کر رہے ہو اگر وہ میرے اختیار میں ہوتی تو مجھ میں اور تم میں فیصلہ ہو چکا ہوتا اور اللہ ظالموں سے خوب واقف ہے۔', 'تو کہہ اگر ہوتی میرے پاس وہ چیز جس کی تم جلدی کر رہے ہو تو طے ہو چکا ہوتا جھگڑا درمیان میرے اور درمیان تمہارے [۶۵] اور اللہ خوب جانتا ہے ظالموں کو', 'Say: \"If I had that which you are asking for impatiently (the torment), the matter would have been settled at once between me and you, but Allah knows best the Zalimoon (polytheists and wrongdoers, etc.).\"', 'Say, “If what you demand to be hastened were up to me, the matter between me and you would have been over. Allah well knows who the wrongdoers are.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(848, 6, 59, 7, 13, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ عِنۡدَہٗ مَفَاتِحُ الۡغَیۡبِ لَا  یَعۡلَمُہَاۤ  اِلَّا ہُوَ ؕ وَ یَعۡلَمُ مَا فِی الۡبَرِّ  وَ الۡبَحۡرِ ؕ وَ مَا تَسۡقُطُ مِنۡ وَّرَقَۃٍ  اِلَّا یَعۡلَمُہَا وَ لَا حَبَّۃٍ  فِیۡ ظُلُمٰتِ الۡاَرۡضِ وَ لَا رَطۡبٍ وَّ لَا یَابِسٍ  اِلَّا فِیۡ  کِتٰبٍ مُّبِیۡنٍ ﴿۵۹﴾', 'اور اسی کے پاس غیب کی کنجیاں ہیں جنکو اسکے سوا کوئی نہیں جانتا اور اسے جنگلوں اور دریاؤں کی سب چیزوں کا علم ہے اور کوئی پتا نہیں جھڑتا مگر وہ اسکو جانتا ہے اور زمین کے اندھیروں میں کوئی دانہ اور کوئی ہری یا سوکھی چیز نہیں ہے مگر کتاب روشن میں لکھی ہوئی ہے۔', 'اور اُسی کے پاس کنجیاں ہیں غیب کی کہ انکو کوئی نہیں جانتا اسکے سوا اور وہ جانتا ہے جو کچھ جنگل اور دریا میں ہے اور نہیں جھڑتا کوئی پتا مگر وہ جانتا ہے اسکو اور نہیں گرتا کوئی دانہ زمین کے اندھیروں میں اور نہ کوئی ہری چیز اور نہ کوئی سوکھی چیز مگر وہ سب کتاب مبین میں ہے [۶۶]', 'And with Him are the keys of the Ghaib (all that is hidden), none knows them but He. And He knows whatever there is in (or on) the earth and in the sea; not a leaf falls, but he knows it. There is not a grain in the darkness of the earth nor anything fresh or dry, but is written in a Clear Record.', 'With Him are the keys of the Unseen. No one knows them but He. He knows what is in the land and the sea. No leaf ever falls but that He knows about it, and there is no grain in the dark layers of the earth, or anything fresh or dry that is not recorded in a manifest book.'),
(849, 6, 60, 7, 13, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ ہُوَ الَّذِیۡ یَتَوَفّٰىکُمۡ بِالَّیۡلِ وَ یَعۡلَمُ مَا جَرَحۡتُمۡ بِالنَّہَارِ ثُمَّ یَبۡعَثُکُمۡ فِیۡہِ لِیُقۡضٰۤی  اَجَلٌ مُّسَمًّی ۚ ثُمَّ  اِلَیۡہِ مَرۡجِعُکُمۡ  ثُمَّ یُنَبِّئُکُمۡ بِمَا کُنۡتُمۡ تَعۡمَلُوۡنَ ﴿٪۶۰﴾', 'اور وہی تو ہے جو رات کو سونے کی حالت میں تمہاری روح قبض کر لیتا ہے اور جو کچھ تم دن میں کرتے ہو اس سے خبر رکھتا ہے پھر تمہیں دن کو اٹھا دیتا ہے تاکہ یہی سلسلہ جاری رکھ کر زندگی کی مدت معین پوری کر دی جائے پھر تم سب کو اسی کی طرف لوٹ کر جانا ہے پھر وہ تم کو تمہارے عمل جو تم کرتے رہتے ہو ایک ایک کر کے بتائے گا۔', 'اور وہ ہی ہے کہ قبضہ میں لے لیتا ہے تم کو رات میں [۶۷] اور جانتا ہے جو کچھ کہ تم کر چکے ہو دن میں [۶۸] پھر تم کو اٹھا دیتا ہے اُس میں تاکہ پورا ہو وہ وعدہ جو مقرر ہو چکا ہے [۶۹] پھر اسی کی طرف تم لوٹائے جاؤ گے پھر خبر دے گا تم کو اس کی جو کچھ تم کرتے ہو [۷۰]', 'It is He, Who takes your souls by night (when you are asleep), and has knowledge of all that you have done by day, then he raises (wakes) you up again that a term appointed (your life period) be fulfilled, then in the end unto Him will be your return. Then He will inform you what you used to do.', 'He is the One who recalls your souls by night, and knows what you do by day; then He makes you rise up therein, so that a fixed term may be fulfilled. Thereafter, to Him are you to return; then He will tell you what you have been doing.'),
(850, 6, 61, 8, 14, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ ہُوَ الۡقَاہِرُ فَوۡقَ عِبَادِہٖ وَ یُرۡسِلُ عَلَیۡکُمۡ حَفَظَۃً ؕ حَتّٰۤی  اِذَا جَآءَ  اَحَدَکُمُ  الۡمَوۡتُ  تَوَفَّتۡہُ  رُسُلُنَا وَ ہُمۡ لَا  یُفَرِّطُوۡنَ ﴿۶۱﴾', 'اور وہ اپنے بندوں پر غالب ہے اور تم پر نگہبان مقرر کئے رکھتا ہے یہانتک کہ جب تم میں سے کسی کی موت آتی ہے تو ہمارے فرشتے اسکی روح قبض کر لیتے ہیں اور کسی طرح کی کوتاہی نہیں کرتے۔', 'اور وہی غالب ہے اپنے بندوں پر اور بھیجتا ہے تم پر نگہبان [۷۱] یہاں تک کہ جب آپہنچے تم میں سے کسی کو موت تو قبضہ میں لے لیتے ہیں اسکو ہمارے بھیجے ہوئےفرشتے [۷۲] اور وہ کوتاہی نہیں کرتے [۷۳]', 'He is the Irresistible, Supreme over His slaves, and He sends guardians (angels guarding and writing all of ones good and bad deeds) over you, until when death approaches one of you, Our Messengers (angel of death and his assistants) take his soul, and they never neglect their duty.', 'He is Dominant over His slaves, and He sends guardians over you until when death comes upon one of you, Our deputies take his soul in full, and they neglect nothing (from their duties).'),
(851, 6, 62, 8, 14, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'ثُمَّ  رُدُّوۡۤا  اِلَی اللّٰہِ مَوۡلٰىہُمُ  الۡحَقِّ ؕ اَلَا لَہُ  الۡحُکۡمُ ۟ وَ ہُوَ  اَسۡرَعُ  الۡحٰسِبِیۡنَ ﴿۶۲﴾', 'پھر قیامت کے دن تمام لوگ اپنے مالک برحق اللہ تعالٰی کے پاس واپس بلائے جائیں گے۔ سن لو کہ حکم اسی کا ہے اور وہ نہایت جلد حساب لینے والا ہے۔', 'پھر پہنچائے جاویں گے اللہ کی طرف جو مالک انکا ہے سچا سن رکھو حکم اسی کا ہے اور وہ بہت جلد حساب لینے والا ہے [۷۴]', 'Then they are returned to Allah, their Maula (True Master (God), the Just Lord (to reward them)). Surely, His is the judgement and He is the Swiftest in taking account.', 'Then all of them will be returned to Allah, their real Master. Behold, His is the judgement, and He is the swiftest of those who take account.'),
(852, 6, 63, 8, 14, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قُلۡ مَنۡ یُّنَجِّیۡکُمۡ مِّنۡ ظُلُمٰتِ الۡبَرِّ وَ الۡبَحۡرِ تَدۡعُوۡنَہٗ  تَضَرُّعًا وَّ  خُفۡیَۃً ۚ لَئِنۡ اَنۡجٰىنَا مِنۡ ہٰذِہٖ  لَنَکُوۡنَنَّ مِنَ الشّٰکِرِیۡنَ ﴿۶۳﴾', 'کہو بھلا تم کو جنگلوں اور دریاؤں کے اندھیروں سے کون نکال لاتا ہے جب کہ تم اسے عاجزی سے اور چپکے چپکے پکارتے ہو اور کہتے ہو اگر اللہ ہم کو اس تنگی سے نجات بخشے تو ہم اسکے بہت شکر گذار ہوں۔', 'تو کہہ کون تم کو بچا لاتا ہے جنگل کے اندھیروں سے اور دریا کے اندھیروں سے اس وقت میں کہ پکارتے ہو تم اسکو گڑا گڑا کر اور چپکے سے کہ اگر ہم کو بچا لیوے اس بلا سے تو البتہ ہم ضرور احسان مانیں گے', 'Say (O Muhammad SAW): \"Who rescues you from the darkness of the land and the sea (dangers like storms), when you call upon Him in humility and in secret (saying): If He (Allah) only saves us from this (danger), we shall truly be grateful.\"', 'Say, “Who is the One who delivers you from the darkness of the land and the sea when you supplicate Him in humility and in low tones (promising): ‘If He delivers us from this, We shall truly become grateful?’”'),
(853, 6, 64, 8, 14, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قُلِ اللّٰہُ یُنَجِّیۡکُمۡ مِّنۡہَا وَ مِنۡ کُلِّ کَرۡبٍ ثُمَّ  اَنۡتُمۡ  تُشۡرِکُوۡنَ ﴿۶۴﴾', 'کہو کہ اللہ ہی تم کو اس تنگی سے اور ہر سختی سے نجات بخشتا ہے پھر بھی تم اسکے ساتھ شرک کرتے ہو۔', 'تو کہہ دے اللہ تم کو بچاتا ہے اس سے اور ہر سختی سے پھر بھی تم شرک کرتے ہو [۷۵]', 'Say (O Muhammad SAW): \"Allah rescues you from it and from all (other) distresses, and yet you worship others besides Allah.\"', 'Say, “Allah delivers you from it and from every pain; Yet still, you associate partners with Him.”'),
(854, 6, 65, 8, 14, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قُلۡ ہُوَ  الۡقَادِرُ عَلٰۤی  اَنۡ یَّبۡعَثَ عَلَیۡکُمۡ عَذَابًا مِّنۡ فَوۡقِکُمۡ اَوۡ مِنۡ تَحۡتِ اَرۡجُلِکُمۡ اَوۡ یَلۡبِسَکُمۡ شِیَعًا وَّ یُذِیۡقَ بَعۡضَکُمۡ بَاۡسَ بَعۡضٍ ؕ اُنۡظُرۡ کَیۡفَ نُصَرِّفُ الۡاٰیٰتِ لَعَلَّہُمۡ یَفۡقَہُوۡنَ ﴿۶۵﴾', 'کہدو کہ وہ اس پر بھی قدرت رکھتا ہے کہ تم پر اوپر کی طرف سے یا تمہارے پاؤں کے نیچے سے عذاب بھیجے یا تمہیں فرقہ فرقہ کر دے اور ایک کو دوسرے سے بھڑا کر آپس کی لڑائی کا مزہ چکھا دے۔ دیکھو ہم اپنی آیتوں کو کس کس طرح بیان کرتے ہیں تاکہ یہ لوگ سمجھیں۔', 'تو کہہ اسی کو قدرت ہے اس پر کہ بھیجے تم پر عذاب [۷۶] اوپر سے یا تمہارے پاؤں کے نیچے سے یا بھڑا دے تم کو مختلف فرقے کر کے اور چکھاوے ایک کو لڑائی ایک کی [۷۷] دیکھ کس کس طرح ہم بیان کرتے ہیں آیتوں کو تاکہ وہ سمجھ جاویں [۷۸]', 'Say: \"He has power to send torment on you from above or from under your feet, or to cover you with confusion in party strife, and make you to taste the violence of one another.\" See how variously We explain the Ayat (proofs, evidences, lessons, signs, revelations, etc.), so that they may understand.', 'Say, “He is fully capable that He should send a punishment from above you or from beneath your feet, or to put you in confusion through divisions, and make some of you taste troubles through some others.”18 See how We bring forth explaining verses from different angles, so that they may understand.'),
(855, 6, 66, 8, 14, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ کَذَّبَ بِہٖ قَوۡمُکَ وَ ہُوَ الۡحَقُّ ؕ قُلۡ لَّسۡتُ عَلَیۡکُمۡ  بِوَکِیۡلٍ ﴿ؕ۶۶﴾', 'اور اس قرآن کو تمہاری قوم نے جھٹلایا حالانکہ یہ سراسر حق ہے کہدو کہ میں تمہارا داروغہ نہیں ہوں۔', 'اور اسکو جھوٹ بتلایا تیری قوم نے حالانکہ وہ حق ہے تو کہہ دے کہ میں نہیں تم پر داروغہ', 'But your people (O Muhammad SAW) have denied it (the Quran) though it is the truth. Say: \"I am not responsible for your affairs.\"', 'Your people have rejected it (the Qur’ān) while it is the whole truth. Say, “I am not appointed as a taskmaster over you.'),
(856, 6, 67, 8, 14, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'لِکُلِّ نَبَاٍ  مُّسۡتَقَرٌّ ۫ وَّ سَوۡفَ تَعۡلَمُوۡنَ ﴿۶۷﴾', 'ہر خبر کے لئے ایک وقت مقرر ہے اور تم کو عنقریب معلوم ہو جائے گا۔', 'ہر ایک خبر کا ایک وقت مقرر ہے اور قریب ہے کہ اس کو جان لو گے [۷۹]', 'For every news there is a fact, i.e. for everything there is an appointed term (and it is also said that for every deed there is a recompense) and you will come to know.', 'For every event there is a point (of time and place) to occur, and you will soon know (it).”'),
(857, 6, 68, 8, 14, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ اِذَا  رَاَیۡتَ الَّذِیۡنَ  یَخُوۡضُوۡنَ فِیۡۤ  اٰیٰتِنَا فَاَعۡرِضۡ عَنۡہُمۡ حَتّٰی یَخُوۡضُوۡا فِیۡ حَدِیۡثٍ غَیۡرِہٖ ؕ وَ اِمَّا یُنۡسِیَنَّکَ الشَّیۡطٰنُ  فَلَا تَقۡعُدۡ بَعۡدَ  الذِّکۡرٰی  مَعَ الۡقَوۡمِ  الظّٰلِمِیۡنَ ﴿۶۸﴾', 'اور جب تم ایسے لوگوں کو دیکھو جو ہماری آیتوں کے بارے میں بیہودہ بکواس کر رہے ہوں تو ان سے الگ ہو جاؤ۔ یہاں تک کہ وہ اور باتوں میں مصروف ہو جائیں۔ اور اگر یہ بات شیطان تمہیں بھلا دے تو یاد آنے پر ظالم لوگوں کے ساتھ نہ بیٹھے رہو۔', 'اور جب تو دیکھے ان لوگوں کہ کہ جھگڑتے ہیں ہماری آیتوں میں تو ان سے کنارہ کر یہاں تک کہ مشغول ہو جاویں کسی اور بات میں اور اگر بھلا دے تجھ کو شیطان تو مت بیٹھ یاد آجانے کے بعد ظالموں کےساتھ [۸۰]', 'And when you (Muhammad SAW) see those who engage in a false conversation about Our Verses (of the Quran) by mocking at them, stay away from them till they turn to another topic. And if Shaitan (Satan) causes you to forget, then after the remembrance sit not you in the company of those people who are the Zalimoon (polytheists and wrongdoers, etc.).', 'When you see those who indulge in (blaspheming) Our verses, turn away from them until they become occupied with some other discourse. If Satan should cause you to forget (this instruction), then do not sit with the unjust people after recollection.'),
(858, 6, 69, 8, 14, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ  مَا عَلَی الَّذِیۡنَ یَتَّقُوۡنَ مِنۡ حِسَابِہِمۡ مِّنۡ شَیۡءٍ وَّ لٰکِنۡ ذِکۡرٰی لَعَلَّہُمۡ یَتَّقُوۡنَ ﴿۶۹﴾', 'اور پرہیزگاروں پر ان لوگوں کے حساب کی کچھ بھی جوابدہی نہیں۔ ہاں نصیحت تاکہ وہ بھی پرہیزگار ہوں۔', 'اور پرہیزگاروں پر نہیں ہے جھگڑنے والوں کے حساب میں سے کوئی چیز لیکن انکے ذمہ نصیحت کرنی ہے تاکہ وہ ڈریں [۸۱]', 'Those who fear Allah, keep their duty to Him and avoid evil are not responsible for them (the disbelievers) in any case, but (their duty) is to remind them, that they may avoid that (mockery at the Quran). (The order of this Verse was cancelled (abrogated) by the Verse 4:140).', 'Those who fear Allah are not responsible for any (evil) act in the account of these (infidels), except for advising them, so that they may be careful.'),
(859, 6, 70, 8, 14, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ ذَرِ الَّذِیۡنَ اتَّخَذُوۡا دِیۡنَہُمۡ لَعِبًا وَّ لَہۡوًا وَّ غَرَّتۡہُمُ الۡحَیٰوۃُ  الدُّنۡیَا وَ ذَکِّرۡ بِہٖۤ  اَنۡ تُبۡسَلَ نَفۡسٌۢ بِمَا کَسَبَتۡ ٭ۖ  لَیۡسَ لَہَا مِنۡ  دُوۡنِ اللّٰہِ وَلِیٌّ  وَّ لَا شَفِیۡعٌ ۚ وَ اِنۡ تَعۡدِلۡ کُلَّ عَدۡلٍ لَّا یُؤۡخَذۡ مِنۡہَا ؕ اُولٰٓئِکَ  الَّذِیۡنَ  اُبۡسِلُوۡا بِمَا کَسَبُوۡا ۚ لَہُمۡ شَرَابٌ مِّنۡ حَمِیۡمٍ  وَّ عَذَابٌ اَلِیۡمٌۢ بِمَا کَانُوۡا یَکۡفُرُوۡنَ ﴿٪۷۰﴾', 'اور جن لوگوں نے اپنے دین کو کھیل اور تماشا بنا رکھا ہے اور دنیا کی زندگی نے انکو دھوکے میں ڈال رکھا ہے ان سے کچھ کام نہ رکھو۔ ہاں اس قرآن کے ذریعے سے نصیحت کرتے رہو تاکہ قیامت کے دن کوئی اپنے اعمال کی سزا میں ہلاکت میں نہ ڈالا جائے اس روز اللہ کے سوا نہ تو کوئی اس کا دوست ہوگا اور نہ سفارش کرنے والا۔ اور اگر وہ ہر چیز جو روئے زمین پر ہے بطور معاوضہ دینا چاہے تو وہ اس سے قبول نہ ہو۔ یہی لوگ ہیں کہ اپنے اعمال کے وبال میں ہلاکت میں ڈالے گئے سو انکے لئے پینے کو کھولتا ہوا پانی اور دکھ دینے والا عذاب ہے اس لئے کہ کفر کرتے تھے۔', 'اور چھوڑ دے انکو جنہوں نے بنا رکھا ہے اپنے دین کو کھیل اور تماشا [۸۲] اور دھوکا دیا انکو دنیا کی زندگی نے [۸۳] اور نصیحت کر انکو قرآن سے تاکہ گرفتار نہ ہو جاوے کوئی اپنے کئے میں کہ نہ ہو اس کے لئے اللہ کے سوا کوئی حمایتی اور نہ سفارش کرنے والا اور اگر بدلے میں دے سارے بدلے تو قبول نہ ہوں اس سے [۸۴] وہی لوگ ہیں جو گرفتار ہوئے اپنے کئے میں انکو پینا ہے گرم پانی اور عذاب ہے دردناک بدلے میں کفر کے [۸۵]', 'And leave alone those who take their religion as play and amusement, and are deceived by the life of this world. But remind (them) with it (the Quran) lest a person be given up to destruction for that which he has earned, when he will find for himself no protector or intercessor besides Allah, and even if he offers every ransom, it will not be accepted from him. Such are they who are given up to destruction because of that which they have earned. For them will be a drink of boiling water and a painful torment because they used to disbelieve.', 'Avoid those who have taken their faith as fun and games. The worldly life has deceived them. Preach with it (the Qur’ān), lest one should be seized for what he did, in a way that he should have neither a helper besides Allah, nor an intercessor. Should he offer every (sort of) ransom, it will not be accepted from him. Those are the ones who are seized for what they themselves earned. For them there is a drink of boiling water, and a painful punishment, because they used to disbelieve.'),
(860, 6, 71, 9, 15, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قُلۡ  اَنَدۡعُوۡا  مِنۡ دُوۡنِ اللّٰہِ مَا لَا یَنۡفَعُنَا وَ لَا یَضُرُّنَا وَ نُرَدُّ عَلٰۤی اَعۡقَابِنَا بَعۡدَ اِذۡ ہَدٰىنَا اللّٰہُ کَالَّذِی اسۡتَہۡوَتۡہُ الشَّیٰطِیۡنُ فِی الۡاَرۡضِ حَیۡرَانَ ۪ لَہٗۤ  اَصۡحٰبٌ یَّدۡعُوۡنَہٗۤ  اِلَی الۡہُدَی ائۡتِنَا ؕ قُلۡ  اِنَّ ہُدَی اللّٰہِ ہُوَ الۡہُدٰی ؕ وَ اُمِرۡنَا لِنُسۡلِمَ لِرَبِّ الۡعٰلَمِیۡنَ ﴿ۙ۷۱﴾', 'کہو۔ کیا ہم اللہ کے سوا ایسی چیز کو پکاریں جو نہ ہمارا بھلا کرسکے نہ برا۔ اور جب ہم کو اللہ نے سیدھا رستہ دکھا دیا تو کیا ہم الٹے پاؤں پھر جائیں؟ پھر تو ہماری ایسی مثال ہو جیسے کسی کو جنات نے جنگل میں بھلا دیا ہو اور وہ حیران ہو رہا ہو اور اسکے کچھ رفیق ہوں جو اسکو رستے کی طرف بلائیں کہ ہمارے پاس چلا آ۔ کہدو کہ رستہ تو وہی ہے جو اللہ نے بتایا ہے اور ہمیں تو یہ حکم ملا ہے کہ ہم اللہ رب العالمین کے فرمانبردار بنیں۔', 'تو کہہ دے کیا ہم پکاریں اللہ کےسوا ان کو جو نہ نفع پہنچا سکیں ہم کو اور نہ نقصان اور کیا پھر جاویں ہم الٹے پاؤں اسکے بعد کہ اللہ سیدھی راہ دکھا چکا ہم کو مثل اس شخص کے کہ رستہ بھلا دیا ہو اسکو جنوں نے جنگل میں جبکہ وہ حیران ہے اس کے رفیق بلاتے ہیں اسکو رستہ کی طرف کہ چلا آ ہمارے پاس [۸۶] تو کہہ دے کہ اللہ نے جو راہ بتلائی وہی سیدھی راہ ہے [۸۷] اور ہم کو حکم ہوا ہے کہ تابع رہیں پروردگار عالم کے', 'Say (O Muhammad SAW): \"Shall we invoke others besides Allah (false deities), that can do us neither good nor harm, and shall we turn on our heels after Allah has guided us (to true Monotheism)? - like one whom the Shayatin (devils) have made to go astray, confused (wandering) through the earth, his companions calling him to guidance (saying): Come to us. \" Say: \"Verily, Allahs Guidance is the only guidance, and we have been commanded to submit (ourselves) to the Lord of the Alameen (mankind, jinns and all that exists);', 'Say, “Should we invoke, besides Allah, something that can neither benefit us nor harm us? Should we turn back on our heels after Allah has guided us? (If we do so, we will be) like the one whom the devils have abducted to a far off land, leaving him bewildered, even though he has friends who call him to the right path (saying), “Come to us.” Say, “Allah’s guidance is the guidance, and we have been ordered to submit to the Lord of the worlds,'),
(861, 6, 72, 9, 15, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ اَنۡ  اَقِیۡمُوا الصَّلٰوۃَ وَ اتَّقُوۡہُ ؕ وَ ہُوَ الَّذِیۡۤ  اِلَیۡہِ تُحۡشَرُوۡنَ ﴿۷۲﴾', 'اور یہ بھی کہ نماز پڑھتے رہو اور اس سے ڈرتے رہو۔ اور وہی تو ہے جس کے پاس تم جمع کئے جاؤ گے۔', 'اور یہ کہ قائم رکھو نماز کو اور ڈرتے رہو اللہ سے اور  وہی ہے جس کے سامنے تم سب اکھٹے ہو گے', 'And to perform As-Salat (Iqamat-as-Salat)\", and to be obedient to Allah and fear Him, and it is He to Whom you shall be gathered.', 'and establish Salāh, and heed Him. He is the One before whom you are to be gathered.'),
(862, 6, 73, 9, 15, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ ہُوَ الَّذِیۡ خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ بِالۡحَقِّ ؕ وَ یَوۡمَ یَقُوۡلُ  کُنۡ فَیَکُوۡنُ ۬ؕ قَوۡلُہُ  الۡحَقُّ ؕ وَ لَہُ  الۡمُلۡکُ یَوۡمَ  یُنۡفَخُ فِی الصُّوۡرِ ؕ عٰلِمُ  الۡغَیۡبِ وَ الشَّہَادَۃِ ؕ وَ ہُوَ الۡحَکِیۡمُ  الۡخَبِیۡرُ ﴿۷۳﴾', 'اور وہی تو ہے جس نے آسمانوں اور زمین کو تدبیر سے پیدا کیا ہے اور جس دن وہ فرمائے گا کہ ہوجا تو حشر برپا ہو جائے گا۔ اس کا ارشاد برحق ہے اور جس دن صور پھونکا جائے گا۔ اس دن اسی کی بادشاہت ہو گی۔ وہی پوشیدہ اور ظاہر سب کا جاننے والا ہے اور وہی دانا ہے خبردار ہے۔', 'اور وہی ہے جس نے پیدا کیا آسمانوں اور زمین کو ٹھیک طور پر اور جس دن کہے گا کہ ہو جا [۸۸] تو وہ ہو جائے گا اسی کی بات سچی ہے اور اسی کی سلطنت ہے جس دن پھونکا جائے گا صور [۸۹] جاننے والا چھپی اور کھلی باتوں کا اور وہی ہے حکمت والا جاننے والا [۹۰]', 'It is He Who has created the heavens and the earth in truth, and on the Day (i.e. the Day of Resurrection) He will say: \"Be!\", - and it shall become. His Word is the truth. His will be the dominion on the Day when the trumpet will be blown. AllKnower of the unseen and the seen. He is the AllWise, Well-Aware (of all things).', 'He is the One who created the heavens and the earth with purpose. On the day He says “Be”, it (the Resurrection) will come to be. His word is the truth, and His is the kingdom on the day the Horn shall be blown. He is the Knower of the Unseen and the Seen. He is the Wise, the All-Aware.'),
(863, 6, 74, 9, 15, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ اِذۡ  قَالَ  اِبۡرٰہِیۡمُ لِاَبِیۡہِ  اٰزَرَ اَتَتَّخِذُ  اَصۡنَامًا  اٰلِہَۃً ۚ اِنِّیۡۤ   اَرٰىکَ وَ قَوۡمَکَ فِیۡ ضَلٰلٍ مُّبِیۡنٍ ﴿۷۴﴾', 'اور وہ وقت بھی یاد کرنے کے لائق ہے جب ابراہیم نے اپنے باپ آزر سے کہا تھا تم کیا بتوں کو معبود بناتے ہو۔ میں دیکھتا ہوں کہ تم اور تمہاری قوم کھلی گمراہی میں ہو۔', 'اور یاد کرو جب کہا ابراہیم نے [۹۱] اپنے باپ آزر کو [۹۲] تو کیا مانتا ہے بتوں کو خدا میں دیکھتا ہوں کہ تو اور تیری قوم صریح گمراہ ہیں [۹۳]', 'And (remember) when Ibrahim (Abraham) said to his father Azar: \"Do you take idols as aliha (gods)? Verily, I see you and your people in manifest error.\"', '(Remember) when Ibrāhīm said to his father, ’Āzar: “Do you take idols for gods? I see you and your people in manifest error.”'),
(864, 6, 75, 9, 15, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ کَذٰلِکَ نُرِیۡۤ  اِبۡرٰہِیۡمَ مَلَکُوۡتَ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ لِیَکُوۡنَ مِنَ الۡمُوۡقِنِیۡنَ ﴿۷۵﴾', 'اور ہم اس طرح ابراہیم کو آسمانوں اور زمین کے عجائبات دکھانے لگے تاکہ وہ خوب یقین کرنے والوں میں ہو جائیں۔', 'اور اسی طرح ہم دکھانے لگے ابراہیم کو عجائبات آسمانوں اور زمینوں کے اور تاکہ اس کو یقین آ جاوے [۹۴]', 'Thus did we show Ibrahim (Abraham) the kingdom of the heavens and the earth that he be one of those who have Faith with certainty.', 'Thus We showed Ibrāhīm the kingdom of the heavens and the earth, so that he might be firm in belief.'),
(865, 6, 76, 9, 15, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'فَلَمَّا جَنَّ عَلَیۡہِ الَّیۡلُ  رَاٰ کَوۡکَبًا ۚ قَالَ ہٰذَا  رَبِّیۡ ۚ فَلَمَّاۤ  اَفَلَ  قَالَ لَاۤ  اُحِبُّ  الۡاٰفِلِیۡنَ ﴿۷۶﴾', 'یعنی جب رات نے انکو پردہ تاریکی سے ڈھانپ لیا تو آسمان میں ایک ستارہ نظر پڑا کہنے لگے یہ میرا پروردگار ہے۔ جب وہ غائب ہو گیا تو کہنے لگے کہ مجھے غائب ہو جانے والے تو پسند نہیں۔', 'پھر جب اندھیرا کر لیا اس پر رات نے دیکھا اس نے ایک ستارہ بولا یہ ہے رب میرا پھر جب وہ غائب ہو گیا تو بولا میں پسند نہیں کرتا غائب ہو جانے والوں کو [۹۵]', 'When the night covered him over with darkness he saw a star. He said: \"This is my lord.\" But when it set, he said: \"I like not those that set.\"', 'So, when the night enveloped him, he saw a star. He said, “This is my Lord.” But, when it vanished, he said, “I do not like those who vanish.”'),
(866, 6, 77, 9, 15, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'فَلَمَّا رَاَ  الۡقَمَرَ بَازِغًا  قَالَ ہٰذَا رَبِّیۡ ۚ فَلَمَّاۤ  اَفَلَ قَالَ  لَئِنۡ  لَّمۡ  یَہۡدِنِیۡ رَبِّیۡ لَاَکُوۡنَنَّ مِنَ  الۡقَوۡمِ  الضَّآلِّیۡنَ ﴿۷۷﴾', 'پھر جب چاند کو دیکھا کہ چمک رہا ہے تو کہنے لگے یہ میرا پروردگار ہے۔ لیکن جب وہ بھی چھپ گیا تو بول اٹھے کہ اگر میرا پروردگار مجھے سیدھا رستہ نہیں دکھائے گا تو میں ان لوگوں میں ہو جاؤں گا جو بھٹک رہے ہیں۔', 'پھر جب دیکھا چاند چمکتا ہوا بولا یہ ہے رب میرا پھر جب وہ غائب ہو گیا بولا اگر نہ ہدایت کرے گا مجھ کو رب میرا تو بیشک میں رہوں گا گمراہ لوگوں میں [۹۶]', 'When he saw the moon rising up, he said: \"This is my lord.\" But when it set, he said: \"Unless my Lord guides me, I shall surely be among the erring people.\"', 'Later, when he saw the moon rising, he said, “This is my Lord.” But, when it vanished, he said, “Had my Lord not guided me, I would have been among those gone astray.”'),
(867, 6, 78, 9, 15, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'فَلَمَّا رَاَ الشَّمۡسَ بَازِغَۃً  قَالَ ہٰذَا رَبِّیۡ ہٰذَاۤ  اَکۡبَرُ ۚ فَلَمَّاۤ  اَفَلَتۡ قَالَ یٰقَوۡمِ  اِنِّیۡ بَرِیۡٓءٌ  مِّمَّا تُشۡرِکُوۡنَ ﴿۷۸﴾', 'پھر جب سورج کو دیکھا کہ جگمگا رہا ہے تو کہنے لگے میرا پروردگار یہ ہے یہ سب سے بڑا ہے۔ مگر جب وہ بھی غروب ہو گیا تو کہنے لگے لوگو جن چیزوں کو تم اللہ کا شریک بناتے ہو میں ان سے بیزار ہوں۔', 'پھر جب دیکھا سورج جھلکھتا ہوا بولا یہ ہے رب میرا یہ سب سے بڑا ہے [۹۷] پھر جب وہ غائب ہو گیا بولا اے میری قوم میں بیزار ہوں ان سے جن کو تم شریک کرتے ہو [۹۸]', 'When he saw the sun rising up, he said: \"This is my lord. This is greater.\" But when it set, he said: \"O my people! I am indeed free from all that you join as partners in worship with Allah.', 'Thereafter, when he saw the sun rising, he said, “This is my Lord. This is greater.” Again, when it vanished, he said, “O my people, I disown whatever you associate with Allah'),
(868, 6, 79, 9, 15, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'اِنِّیۡ وَجَّہۡتُ وَجۡہِیَ لِلَّذِیۡ فَطَرَ السَّمٰوٰتِ وَ الۡاَرۡضَ حَنِیۡفًا وَّ مَاۤ  اَنَا مِنَ  الۡمُشۡرِکِیۡنَ ﴿ۚ۷۹﴾', 'میں نے سب سے یکسو ہو کر اپنے آپ کو اسی ذات کی طرف متوجہ کیا جس نے آسمانوں اور زمین کو پیدا کیا ہے اور میں مشرکوں میں سے نہیں ہوں۔', 'میں نے متوجہ کر لیا اپنے منہ کو اسی کی طرف جس نے بنائے آسمان اور زمین سب سے یکسو ہو کر اور میں نہیں ہوں شرک کرنے والا [۹۹]', 'Verily, I have turned my face towards Him Who has created the heavens and the earth Hanifa (Islamic Monotheism, i.e. worshipping none but Allah Alone) and I am not of Al-Mushrikoon (see V.2:105)\".', 'I have, indeed, turned my face straight towards the One who created the heavens and the earth, and I am not one of those who associate partners with Allah.”'),
(869, 6, 80, 9, 15, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ حَآجَّہٗ  قَوۡمُہٗ ؕ قَالَ  اَتُحَآجُّوۡٓنِّیۡ  فِی اللّٰہِ وَ قَدۡ ہَدٰىنِ ؕ وَ لَاۤ  اَخَافُ مَا تُشۡرِکُوۡنَ بِہٖۤ  اِلَّاۤ  اَنۡ یَّشَآءَ رَبِّیۡ شَیۡئًا ؕ وَسِعَ رَبِّیۡ کُلَّ شَیۡءٍ عِلۡمًا ؕ اَفَلَا تَتَذَکَّرُوۡنَ ﴿۸۰﴾', 'اور انکی قوم ان سے بحث کرنے لگی تو انہوں نے کہا کہ تم مجھ سے اللہ کے بارے میں کیا بحث کرتے ہو۔ اس نے تو مجھے سیدھا رستہ دکھا دیا ہے اور جن چیزوں کو تم اس کا شریک بناتے ہو میں ان سے نہیں ڈرتا۔ ہاں جو میرا پروردگار کچھ چاہے۔ میرا پروردگار اپنے علم سے ہر چیز کا احاطہ کئے ہوئے ہے۔ کیا تم خیال نہیں کرتے؟', 'اور اس سے  جھگڑا کیا اسکی قوم نے بولا کیا تم مجھ سے جھگڑا کرتے ہو اللہ کے ایک ہونے میں اور وہ مجھ کو سمجھا چکا [۱۰۰] اور میں ڈرتا نہیں ہوں ان سے جنکو تم شریک کرتے ہو اس کا مگر یہ کہ میرا رب ہی کوئی تکلیف پہنچانی چاہے احاطہ کر لیا ہے میرے رب کے علم نے سب چیزوں کا کیا تم نہیں سوچتے [۱۰۱]', 'His people disputed with him. He said: \"Do you dispute with me concerning Allah while He has guided me, and I fear not those whom you associate with Allah in worship. (Nothing can happen to me) except when my Lord (Allah) wills something. My Lord comprehends in His Knowledge all things. Will you not then remember?', 'His people argued with him. He said, “Do you argue with me about Allah while He has already led me to the right path? I do not fear that which you associate with Him, (because it cannot harm me), unless, of course, something is willed by my Lord. My Lord encompasses everything with His knowledge. Would you, then, take no lesson?'),
(870, 6, 81, 9, 15, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ کَیۡفَ اَخَافُ مَاۤ  اَشۡرَکۡتُمۡ وَ لَا  تَخَافُوۡنَ  اَنَّکُمۡ  اَشۡرَکۡتُمۡ بِاللّٰہِ مَا لَمۡ یُنَزِّلۡ بِہٖ عَلَیۡکُمۡ سُلۡطٰنًا ؕ فَاَیُّ الۡفَرِیۡقَیۡنِ  اَحَقُّ  بِالۡاَمۡنِ ۚ اِنۡ  کُنۡتُمۡ  تَعۡلَمُوۡنَ ﴿ۘ۸۱﴾', 'بھلا میں ان چیزوں سے جنکو تم اللہ کا شریک بناتے ہو۔ کیونکر ڈروں جبکہ تم اس  بات سے نہیں ڈرتے کہ اللہ کے ساتھ شریک بناتے ہو جسکی اس نے کوئی سند نازل نہیں کی۔ اب دونوں فریق میں سے کونسا فریق امن و بے خوفی کا زیاد حقدار ہے اگر سمجھ رکھتے ہو تو بتاؤ۔', 'اور میں کیونکر ڈروں تمہارے شریکوں سے اور تم نہیں ڈرتے اس بات سے کہ شریک کرتے ہو اللہ کا انکو جسکی نہیں اتاری اس نے تم پر کوئی دلیل [۱۰۲] اب دونوں فرقوں میں کون مستحق ہے دل جمعی کا بولو اگر تم سمجھ رکھتے ہو', 'And how should I fear those whom you associate in worship with Allah (though they can neither benefit nor harm), while you fear not that you have joined in worship with Allah things for which He has not sent down to you any authority. (So) which of the two parties has more right to be in security? If you but know.\"', 'How can I fear that which you associate with Him, while you do not fear (the evil fate of) your having associated with Allah something for which He did not send down to you any authority? Now, which of the two parties has more right to be in peace? (Tell me) if you know.'),
(871, 6, 82, 9, 15, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'اَلَّذِیۡنَ اٰمَنُوۡا وَ لَمۡ یَلۡبِسُوۡۤا اِیۡمَانَہُمۡ بِظُلۡمٍ  اُولٰٓئِکَ لَہُمُ الۡاَمۡنُ وَ ہُمۡ مُّہۡتَدُوۡنَ ﴿٪۸۲﴾', 'جو لوگ ایمان لائے اور انہوں نے اپنے ایمان کو شرک کے ظلم سے ملوث نہیں کیا انکے لئے امن و بے خوفی ہے اور وہی ہدایت پانے والے ہیں۔', 'جو لوگ یقین لے آئے اور نہیں ملا دیا انہوں نے اپنے یقین میں کوئی نقصان انہی کے واسطے ہے دل جمعی اور وہی ہیں سیدھی راہ پر [۱۰۳]', 'It is those who believe (in the Oneness of Allah and worship none but Him Alone) and confuse not their belief with Zulm (wrong i.e. by worshipping others besides Allah), for them (only) there is security and they are the guided.', 'Those who have believed and have not mixed their faith with injustice are the ones who deserve peace, and it is they who are on the right path.'),
(872, 6, 83, 10, 16, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ تِلۡکَ حُجَّتُنَاۤ  اٰتَیۡنٰہَاۤ  اِبۡرٰہِیۡمَ عَلٰی قَوۡمِہٖ ؕ نَرۡفَعُ دَرَجٰتٍ مَّنۡ نَّشَآءُ ؕ اِنَّ رَبَّکَ حَکِیۡمٌ  عَلِیۡمٌ ﴿۸۳﴾', 'اور یہ ہماری دلیل تھی جو ہم نے ابراہیم کو انکی قوم کے مقابلے میں عطا کی تھی۔ ہم جسکے چاہتے ہیں درجے بلند کر دیتے ہیں۔ بیشک تمہارا پروردگار دانا ہے خبردار ہے۔', 'اور یہ ہماری دلیل ہے کہ ہم نے دی تھی ابراہیم کو اس کی قوم کے مقابلہ میں درجے بلندکرتے ہیں ہم جس کے چاہیں تیرا رب حکمت والا ہے جاننے والا [۱۰۴]', 'And that was Our Proof which We gave Ibrahim (Abraham) against his people. We raise whom We will in degrees. Certainly your Lord is AllWise, AllKnowing.', 'That is the decisive argument from Us that We gave to Ibrāhīm against his people. We raise in ranks whomsoever We will. Surely, your Lord is Wise, Knowing.'),
(873, 6, 84, 10, 16, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ وَہَبۡنَا لَہٗۤ  اِسۡحٰقَ وَ یَعۡقُوۡبَ ؕ کُلًّا ہَدَیۡنَا ۚ وَ نُوۡحًا ہَدَیۡنَا مِنۡ قَبۡلُ وَ مِنۡ ذُرِّیَّتِہٖ دَاوٗدَ  وَ سُلَیۡمٰنَ وَ اَیُّوۡبَ وَ یُوۡسُفَ وَ مُوۡسٰی وَ ہٰرُوۡنَ ؕ وَ کَذٰلِکَ نَجۡزِی الۡمُحۡسِنِیۡنَ ﴿ۙ۸۴﴾', 'اور ہم نے انکو اسحٰق اور یعقوب بخشے اور سب کو ہدایت دی۔ اور پہلے نوح کو بھی ہدایت دی تھی اور انکی اولاد میں سے داؤد اور سلیمان اور ایوب اور یوسف اور موسٰی اور ہارون کو بھی۔ اور ہم نیک لوگوں کو ایسا ہی بدلہ دیا کرتے ہیں۔', 'اور بخشا ہم نے ابراہیم کو اسحٰق اور یعقوب سب کو ہم نے ہدایت دی [۱۰۵] اور نوح کو ہدایت کی ہم نے ان سب سے پہلے [۱۰۶] اور اسکی اولاد میں سے داؤد اور سلیمان کو اور ایوب اور یوسف کو اور موسٰی اور ہارون کو [۱۰۷] اور ہم اسی طرح بدلہ دیا کرتےہیں نیک کام والوں کو', 'And We bestowed upon him Ishaque (Isaac) and Yaqoob (Jacob), each of them We guided, and before him, We guided Nooh (Noah), and among his progeny Dawood (David), Sulaiman (Solomon), Ayub (Job), Yoosuf (Joseph), Moosa (Moses), and Haroon (Aaron). Thus do We reward the gooddoers.', 'We bestowed upon him IsHāq and Ya‘qūb . Each one of them We guided to the right path. Earlier, We guided NūH and, of his progeny, (We guided) Dawūd and Sulaimān and Ayyūb and Yūsuf (Joseph) and Mūsā and Hārūn.-Thus We reward those who are good in deeds-'),
(874, 6, 85, 10, 16, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ زَکَرِیَّا وَ یَحۡیٰی وَ عِیۡسٰی وَ اِلۡیَاسَ ؕ کُلٌّ  مِّنَ الصّٰلِحِیۡنَ ﴿ۙ۸۵﴾', 'اور زکریا اور یحیٰی اور عیسٰی اور الیاس کو بھی۔ یہ سب نیکوکار تھے۔', 'اور زکریا اور یحیٰی اور عیسٰی اور الیاس کو سب ہیں نیک بختوں میں', 'And Zakariya (Zachariya), and Yahya (John) and Iesa (Jesus) and Iliyas (Elias), each one of them was of the righteous.', 'and (We guided) Zakariyyā and YaHyā and ‘Īsā and Ilyās -each one of them was of the righteous-'),
(875, 6, 86, 10, 16, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ اِسۡمٰعِیۡلَ وَ الۡیَسَعَ وَ یُوۡنُسَ وَ لُوۡطًا ؕ وَ کُلًّا فَضَّلۡنَا عَلَی  الۡعٰلَمِیۡنَ ﴿ۙ۸۶﴾', 'اور اسمٰعیل اور الیسع اور یونس اور لوط کو بھی۔ اور ان سب کو دنیا جہاں کے لوگوں پر فضیلت بخشی تھی۔', 'اور اسمٰعیل اور الیسع کو اور یونس کو اور لوط کو اور سب کو ہم نے بزرگی دی سارے جہان والوں پر [۱۰۸]', 'And Ismail (Ishmael) and Al-Yasa (Elisha), and Yoonus (Jonah) and Lout (Lot), and each one of them We preferred above the Alameen (mankind and jinns) (of their times).', '-and Ismā‘īl and Yasa‘ and Yūnus and LūT, and all of them We made to excel over all the people of the world (in their respective times).'),
(876, 6, 87, 10, 16, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ مِنۡ اٰبَآئِہِمۡ وَ ذُرِّیّٰتِہِمۡ وَ  اِخۡوَانِہِمۡ ۚ وَ اجۡتَبَیۡنٰہُمۡ وَ ہَدَیۡنٰہُمۡ  اِلٰی صِرَاطٍ مُّسۡتَقِیۡمٍ ﴿۸۷﴾', 'اور بعض بعض کو ان کے باپ دادوں اور اولاد اور بھائیوں میں سے بھی۔ اور ان کو برگزیدہ بھی کیا تھا اور سیدھا رستہ بھی دکھایا تھا۔', 'اور ہدایت کی ہم نے بعضوں کو انکے باپ دادوں میں سے اور انکی اولاد میں سےاور بھائیوں میں سے اور انکو ہم نے پسند کیا اور سیدھی راہ چلایا', 'And also some of their fathers and their progeny and their brethren, We chose them, and We guided them to a Straight Path.', 'We guided many among their fathers and their children and their brothers, and We chose them and led them on to the straight path.'),
(877, 6, 88, 10, 16, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'ذٰلِکَ ہُدَی اللّٰہِ یَہۡدِیۡ بِہٖ مَنۡ یَّشَآءُ مِنۡ عِبَادِہٖ ؕ وَ لَوۡ اَشۡرَکُوۡا لَحَبِطَ عَنۡہُمۡ  مَّا  کَانُوۡا  یَعۡمَلُوۡنَ ﴿۸۸﴾', 'یہ اللہ کی ہدایت ہے اس پر اپنے بندوں میں سے جسے چاہے چلائے اور اگر وہ لوگ شرک کرتے تو جو اعمال وہ کرتے تھے سب ضائع ہو جاتے۔', 'یہ اللہ کی ہدایت ہے اس پر چلاتا ہے جسکو چاہے اپنے بندوں میں سے [۱۰۹] اور اگر یہ لوگ شرک کرتے تو البتہ ضائع ہو جاتا جو کچھ انہوں نے کیا تھا [۱۱۰]', 'This is the Guidance of Allah with which He guides whomsoever He will of His slaves. But if they had joined in worship others with Allah, all that they used to do would have been of no benefit to them.', 'That is Allah’s guidance. He guides with it whomsoever He wills from among His servants. Had they associated partners with Him, all they did would have been nullified for them.'),
(878, 6, 89, 10, 16, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'اُولٰٓئِکَ الَّذِیۡنَ اٰتَیۡنٰہُمُ الۡکِتٰبَ وَ الۡحُکۡمَ وَ النُّبُوَّۃَ ۚ فَاِنۡ یَّکۡفُرۡ بِہَا ہٰۤؤُلَآءِ  فَقَدۡ وَکَّلۡنَا بِہَا قَوۡمًا لَّیۡسُوۡا بِہَا بِکٰفِرِیۡنَ ﴿۸۹﴾', 'یہ وہ لوگ تھے جنکو ہم نے کتاب اور حکم شریعت اور نبوت عطا فرمائی تھی۔ اگر یہ کفار ان باتوں سے انکار کریں تو ہم نے ان پر ایمان لانے کے لئے ایسے لوگ مقرر کر دیئے ہیں کہ وہ ان سے کبھی انکار کرنے والے نہیں۔', 'یہ لوگ تھے جن کو دی ہم نے کتاب اور شریعت اور نبوت پھر اگر ان باتوں کو نہ مانیں مکہ والے تو ہم نے ان باتوں کے لئے مقرر کر دیے ہیں ایسے لوگ جو ان سے منکر نہیں [۱۱۱]', 'They are those whom We gave the Book, AlHukm (understanding of the religious laws), and Prophethood. But if these disbelieve therein (the Book, AlHukm and Prophethood), then, indeed We have entrusted it to a people (such as the Companions of Prophet Muhammad SAW) who are not disbelievers therein.', 'They are those whom We have given the Book and wisdom and prophethood. So, if these people disbelieve this (concept of Prophet-hood), then (be not grieved, because) We have deputed for (believing in) it a people who do not reject it.'),
(879, 6, 90, 10, 16, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'اُولٰٓئِکَ الَّذِیۡنَ ہَدَی اللّٰہُ  فَبِہُدٰىہُمُ اقۡتَدِہۡ ؕ قُلۡ  لَّاۤ  اَسۡـَٔلُکُمۡ عَلَیۡہِ  اَجۡرًا ؕ اِنۡ  ہُوَ   اِلَّا  ذِکۡرٰی لِلۡعٰلَمِیۡنَ ﴿٪۹۰﴾', 'یہ وہ لوگ ہیں جنکو اللہ نے ہدایت دی تھی تو تم انہیں کی ہدایت کی پیروی کرو۔ کہدو کہ میں تم سے اس کا کوئی صلہ نہیں مانگتا۔ یہ تو  دنیا جہان کے لوگوں کے لئے محض نصیحت ہے۔', 'یہ وہ لوگ تھے جن کو ہدایت کی اللہ نے سو تو چل ان کے طریقہ پر [۱۱۲] تو کہہ دے کہ میں نہیں مانگتا تم سے اس پر کچھ مزدوری یہ تو محض نصیحت ہے جہان کے لوگوں کو [۱۱۳]', 'They are those whom Allah had guided. So follow their guidance. Say: \"No reward I ask of you for this (the Quran). It is only a reminder for the Alameen (mankind and jinns).\"', 'Those are the people whom Allah has guided. So, it is their guidance that you should follow. Say, “I ask you no reward for it. It is nothing but an advice for all the worlds.”'),
(880, 6, 91, 11, 17, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ مَا  قَدَرُوا اللّٰہَ حَقَّ قَدۡرِہٖۤ  اِذۡ قَالُوۡا مَاۤ اَنۡزَلَ اللّٰہُ  عَلٰی بَشَرٍ مِّنۡ  شَیۡءٍ ؕ قُلۡ مَنۡ اَنۡزَلَ  الۡکِتٰبَ الَّذِیۡ جَآءَ بِہٖ مُوۡسٰی نُوۡرًا وَّ  ہُدًی لِّلنَّاسِ تَجۡعَلُوۡنَہٗ قَرَاطِیۡسَ تُبۡدُوۡنَہَا وَ تُخۡفُوۡنَ  کَثِیۡرًا ۚ وَ  عُلِّمۡتُمۡ  مَّا لَمۡ تَعۡلَمُوۡۤا  اَنۡتُمۡ وَ لَاۤ  اٰبَآؤُکُمۡ ؕ قُلِ  اللّٰہُ ۙ ثُمَّ  ذَرۡہُمۡ  فِیۡ  خَوۡضِہِمۡ  یَلۡعَبُوۡنَ  ﴿۹۱﴾', 'اور ان لوگوں نے اللہ کی قدر جیسی جاننی چاہیے تھی نہ جانی۔ جب انہوں نے کہا کہ اللہ نے کسی انسان پر وحی اور کتاب وغیرہ کچھ بھی نازل نہیں کیا۔ کہو کہ جو کتاب موسٰی لے کر آئے تھے اسے کس نے نازل کیا تھا؟ جو لوگوں کے لئے نور اور ہدایت تھی اور جسے تم نے علیحدہ علیحدہ اوراق پر نقل کر رکھا ہے۔ کہ ان کے کچھ حصے کو تو ظاہر کرتے ہو اور اکثر کو چھپاتے ہو۔ اور تم کو وہ باتیں سکھائی گئیں جنکو نہ تم جانتے تھے اور نہ تمہارے باپ دادا۔ کہدو اس کتاب کو اللہ ہی نے نازل کیا تھا پھر انکو چھوڑ دو کہ اپنی بیہودہ بکواس میں کھیلتے رہیں۔', 'اور نہیں پہچانا انہوں نے اللہ کو پورا پہچاننا جب کہنے لگے کہ نہیں اتاری اللہ نے کسی انسان پر کوئی چیز [۱۱۴] پوچھ تو کس نے اتاری وہ کتاب جو موسٰی لے کر آیا تھا روشن تھی اور ہدایت تھی لوگوں کے واسطے جس کو تم نے ورق ورق کر کے لوگوں کو دکھلایا اور بہت سی باتوں کو تم نے چھپا رکھا اور تم کو سکھلا دیں جن کو نہ جانتے تھے تم اور نہ تمہارے باپ دادے [۱۱۵] تو کہہ دے کہ اللہ نےاتاری پھر چھوڑ دے ان کو اپنی خرافات میں کھیلتے رہیں [۱۱۶]', 'They (the Jews, Quraish pagans, idolaters, etc.) did not estimate Allah with an estimation due to Him when they said: \"Nothing did Allah send down to any human being (by inspiration).\" Say (O Muhammad SAW): \"Who then sent down the Book which Moosa (Moses) brought, a light and a guidance to mankind which you (the Jews) have made into (separate) papersheets, disclosing (some of it) and concealing (much). And you (believers in Allah and His Messenger Muhammad SAW), were taught (through the Quran) that which neither you nor your fathers knew.\" Say: \"Allah (sent it down).\" Then leave them to play in their vain discussions. (Tafsir Al-Qurtubee, Vol.7, Page 37).', 'They did not hold Allah in due esteem when they said, “Allah has not sent down anything to a human being.” Say, “Who has sent down the Book brought by Mūsā as a light and a guidance for people, which you keep in various sheets (some of which) you disclose, and a lot of which you conceal, and (by which) you were taught what you did not know, neither you nor your fathers?” Say, “Allah.” Then leave them to play with whatever they indulge in.'),
(881, 6, 92, 11, 17, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ ہٰذَا کِتٰبٌ اَنۡزَلۡنٰہُ  مُبٰرَکٌ مُّصَدِّقُ الَّذِیۡ  بَیۡنَ  یَدَیۡہِ  وَ لِتُنۡذِرَ اُمَّ الۡقُرٰی وَ مَنۡ حَوۡلَہَا ؕ وَ الَّذِیۡنَ یُؤۡمِنُوۡنَ بِالۡاٰخِرَۃِ  یُؤۡمِنُوۡنَ بِہٖ وَ ہُمۡ عَلٰی صَلَاتِہِمۡ  یُحَافِظُوۡنَ ﴿۹۲﴾', 'اور ویسی ہی یہ کتاب جسے ہم نے نازل کیا ہے بابرکت جو اپنے سے پہلی کتابوں کی تصدیق کرتی ہے اور جو اس لئے نازل کی گئ ہے کہ اے نبی تم مکے اور اسکے آس پاس کے لوگوں کو آگاہ کردو۔ اور جو لوگ آخرت پر ایمان رکھتے ہیں وہ اس کتاب پر بھی ایمان رکھتے ہیں اور وہ اپنی نمازوں کی پوری خبر رکھتے ہیں۔', 'اور یہ قرآن وہ کتاب ہے جو کہ ہم نے اتاری برکت والی تصدیق کرنے والی ان کی جو اس سے پہلی ہیں [۱۱۷] اور تاکہ تو ڈرا دے مکہ والوں کو اور اس کے آس پاس والوں کو [۱۱۸] اور جن کو یقین ہے آخرت کا وہ اس پر ایمان لاتے ہیں اور وہ ہیں اپنی نماز سے خبردار [۱۱۹]', 'And this (the Quran) is a blessed Book which We have sent down, confirming (the revelations) which came before it, so that you may warn the Mother of Towns (i.e. Makkah) and all those around it. Those who believe in the Hereafter believe in (the Quran), and they are constant in guarding their Salat (prayers).', 'This is indeed a Blessed Book We have sent down, confirming what was (revealed) before it, so that you may warn the town which is the Mother of All Towns, (i.e. Makkah) and those around it. Those who believe in the Hereafter believe in it, and they take due care of their prayers.'),
(882, 6, 93, 11, 17, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ مَنۡ اَظۡلَمُ مِمَّنِ افۡتَرٰی عَلَی اللّٰہِ  کَذِبًا اَوۡ قَالَ اُوۡحِیَ  اِلَیَّ  وَ لَمۡ  یُوۡحَ  اِلَیۡہِ شَیۡءٌ وَّ  مَنۡ قَالَ سَاُنۡزِلُ مِثۡلَ مَاۤ  اَنۡزَلَ اللّٰہُ ؕ وَ لَوۡ تَرٰۤی  اِذِ الظّٰلِمُوۡنَ فِیۡ غَمَرٰتِ الۡمَوۡتِ وَ الۡمَلٰٓئِکَۃُ بَاسِطُوۡۤا  اَیۡدِیۡہِمۡ ۚ اَخۡرِجُوۡۤا اَنۡفُسَکُمۡ ؕ اَلۡیَوۡمَ تُجۡزَوۡنَ عَذَابَ الۡہُوۡنِ بِمَا کُنۡتُمۡ تَقُوۡلُوۡنَ عَلَی اللّٰہِ غَیۡرَ الۡحَقِّ وَ کُنۡتُمۡ عَنۡ اٰیٰتِہٖ تَسۡتَکۡبِرُوۡنَ  ﴿۹۳﴾', 'اور اس سے بڑھ کر ظالم کون ہو گا جو اللہ پر جھوٹ باندھے یا یہ کہے کہ مجھ پر وحی آئی ہے حالانکہ اس پر کچھ بھی وحی نہ آئی ہو۔ اور جو یہ کہے کہ جس طرح کی کتاب اللہ نے نازل کی ہے اسی طرح کی میں بھی بنا لیتا ہوں اور کاش تم ان ظالم یعنی مشرک لوگوں کو اس وقت دیکھو جب موت کی سختیوں میں مبتلا ہوں اور فرشتے انکی طرف ہاتھ بڑھا رہے ہوں کہ نکالو اپنی جانیں۔ آج تم کو ذلت کے عذاب کی سزا دی جائے گی اس لئے کہ تم اللہ پر جھوٹ بولا کرتے تھے اور اسکی آیتوں سے سرکشی کرتے تھے۔', 'اور اس سے زیادہ ظالم کون جو باندھے اللہ پر بہتان یا کہے مجھ پر وحی اتری اور اس پر وحی نہیں اتری کچھ بھی اور جو کہے کہ میں بھی اتارتا ہوں مثل اسکے جو اللہ نے اتارا [۱۲۰] اور اگر تو دیکھے جس وقت کہ ظالم ہوں موت کی سختیوں میں [۱۲۱] اور فرشتے اپنے ہاتھ بڑھا رہے ہیں کہ نکالو اپنی جانیں [۱۲۲] آج تم کو بدلے میں ملے گا ذلت کا عذاب [۱۲۳] اس سبب سے کہ تم کہتےتھے اللہ پر جھوٹی باتیں اور اس کی آیتوں سے تکبر کرتے تھے [۱۲۴]', 'And who can be more unjust than he who invents a lie against Allah, or says: \"I have received inspiration,\" whereas he is not inspired in anything; and who says, \"I will reveal the like of what Allah has revealed.\" And if you could but see when the Zalimoon (polytheists and wrongdoers, etc.) are in the agonies of death, while the angels are stretching forth their hands (saying): \"Deliver your souls! This day you shall be recompensed with the torment of degradation because of what you used to utter against Allah other than the truth. And you used to reject His Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) with disrespect!\"', 'Who is more unjust than the one who fabricates a lie against Allah or says, “Revelation has been sent to me”, whereas no revelation has been sent to him, and the one who says, “I would produce the like of what Allah has revealed.” If only you could witness when the unjust are in the throes of death, and the angels stretch their hands (and say), “Out with your souls. Today, you shall have your punishment, a punishment of humiliation, because you have been saying about Allah what is not true, and have been showing arrogance against His verses.”'),
(883, 6, 94, 11, 17, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ لَقَدۡ جِئۡتُمُوۡنَا فُرَادٰی کَمَا خَلَقۡنٰکُمۡ  اَوَّلَ مَرَّۃٍ  وَّ تَرَکۡتُمۡ مَّا خَوَّلۡنٰکُمۡ  وَرَآءَ  ظُہُوۡرِکُمۡ ۚ وَ مَا نَرٰی مَعَکُمۡ شُفَعَآءَکُمُ  الَّذِیۡنَ زَعَمۡتُمۡ  اَنَّہُمۡ فِیۡکُمۡ شُرَکٰٓؤُا ؕ  لَقَدۡ تَّقَطَّعَ بَیۡنَکُمۡ  وَ ضَلَّ عَنۡکُمۡ  مَّا کُنۡتُمۡ تَزۡعُمُوۡنَ ﴿٪۹۴﴾', 'اور جیسا ہم نے تم لوگوں کو پہلی بار پیدا کیا تھا ایسا ہی آج اکیلے اکیلے تم ہمارے پاس آ گئے۔ اور جو مال و متاع ہم نے تمہیں عطا فرمایا تھا وہ سب اپنی پیٹھ پیچھے چھوڑ آئے اور ہم تمہارے ساتھ تمہارے سفارشیوں کو بھی نہیں دیکھتے جنکی نسبت تم خیال کرتے تھے کہ وہ تمہارے سفارشی اور ہمارے شریک ہیں آج تمہارے آپس کے سب تعلقات منقطع ہو گئے اور جو دعوے تم کیا کرتے تھے سب جاتے رہے۔', 'اور البتہ تم ہمارے پاس آ گئے ایک ایک ہو کر جیسے ہم نے پیدا کیا تھا تم کو پہلی بار اور چھوڑ آئے تم جو کچھ اسباب ہم نے تم کو دیا تھا اپنی پیٹھ کے پیچھے [۱۲۵] اور ہم نہیں دیکھتے تمہارے ساتھ سفارش والوں کو جن کو تم بتلایا کرتے تھے کہ ان کا تم میں ساجھا ہے البتہ منقطع ہو گیا تمہاا علاقہ اور جاتے رہے جو دعوے کہ تم کیا کرتے تھے [۱۲۶]', 'And truly you have come unto Us alone (without wealth, companions or anything else) as We created you the first time. You have left behind you all that which We had bestowed on you. We see not with you your intercessors whom you claimed to be partners with Allah. Now all relations between you and them have been cut off, and all that you used to claim has vanished from you.', 'You have come to Us all alone, just as We had first created you, and you have left behind you what We had bestowed on you, and We do not see your intercessors with you - those whom you claimed to be (Our) partners in (managing) your matters. In fact, all ties between you are now severed, and all that you presumed has totally failed you.'),
(884, 6, 95, 12, 18, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'اِنَّ  اللّٰہَ  فَالِقُ الۡحَبِّ وَ النَّوٰی ؕ یُخۡرِجُ الۡحَیَّ مِنَ الۡمَیِّتِ وَ مُخۡرِجُ الۡمَیِّتِ مِنَ الۡحَیِّ ؕ ذٰلِکُمُ اللّٰہُ  فَاَنّٰی تُؤۡفَکُوۡنَ ﴿۹۵﴾', 'بیشک اللہ ہی دانے اور گٹھلی کو پھاڑ کر ان سے درخت وغیرہ اگا تا ہے وہی جاندار کو بےجان سے نکالتا ہے اور وہی بےجان کا جاندار سے نکالنے والا ہے۔ یہی تو اللہ ہے پھر تم کہاں بہکے پھرتے ہو؟', 'اللہ ہے کہ پھوڑ نکالتا ہے دانہ اور گٹھلی نکالتا ہے مردہ سے زندہ اور نکالنے والا ہے زندہ سے مردہ یہ ہے اللہ پھر تم کدھر بہکے جاتے ہو [۱۲۷]', 'Verily! It is Allah Who causes the seedgrain and the fruitstone (like datestone, etc.) to split and sprout. He brings forth the living from the dead, and it is He Who brings forth the dead from the living. Such is Allah, then how are you deluded away from the truth?', 'Surely, Allah is the one who splits the grain and the date-stone (for sprouting). He brings forth the living from the dead, and He is the One who brings forth the dead from the living. That is Allah! To where, then, are you being turned away (by your desires)?'),
(885, 6, 96, 12, 18, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'فَالِقُ الۡاِصۡبَاحِ ۚ وَ  جَعَلَ الَّیۡلَ سَکَنًا وَّ الشَّمۡسَ وَ الۡقَمَرَ حُسۡبَانًا ؕ ذٰلِکَ تَقۡدِیۡرُ الۡعَزِیۡزِ  الۡعَلِیۡمِ ﴿۹۶﴾', 'وہی رات کے اندھیرے سے صبح کی روشنی پھاڑ نکالتا ہے اور اسی نے رات کو موجب آرام ٹھہرایا اور سورج اور چاند کو حساب کا ذریعہ بنا دیا یہ اللہ کے مقرر کئے ہوئے اندازے ہیں جو غالب ہے علم والا ہے۔', 'پھوڑ نکالنے والا صبح کی روشنی کا [۱۲۸] اور اسی نے رات بنائی آرام کو اور سورج اور چاند حساب کے لئے یہ اندازہ رکھا ہوا ہے زورآور خبردار کا [۱۲۹]', '(He is the) Cleaver of the daybreak. He has appointed the night for resting, and the sun and the moon for reckoning. Such is the measuring of the AllMighty, the AllKnowing.', '(He is) the One who causes the dawn to break. He has made the night for rest, and the sun and the moon for reckoning. This is a measure set by the All-Mighty, the All-Knowing.'),
(886, 6, 97, 12, 18, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ ہُوَ الَّذِیۡ جَعَلَ لَکُمُ النُّجُوۡمَ لِتَہۡتَدُوۡا بِہَا فِیۡ  ظُلُمٰتِ الۡبَرِّ  وَ الۡبَحۡرِ ؕ قَدۡ فَصَّلۡنَا الۡاٰیٰتِ لِقَوۡمٍ یَّعۡلَمُوۡنَ ﴿۹۷﴾', 'اور وہی تو ہے جس نے تمہارے لئے ستارے بنائے تاکہ جنگلوں اور دریاؤں کے اندھیروں میں ان سے رستے معلوم کرو۔ عقل والوں کے لئے ہم نے اپنی آیتیں کھول کھول کر بیان کر دی ہیں۔', 'اور اسی نے بنا دیے تمہارے واسطے ستارے کہ انکے وسیلہ سے راستے معلوم کرو اندھیروں میں جنگل اور دریا کے [۱۳۰] البتہ ہم نے کھول کر بیان کر دیے پتے ان لوگوں کے لئے جو جانتے ہیں', 'It is He Who has set the stars for you, so that you may guide your course with their help through the darkness of the land and the sea. We have (indeed) explained in detail Our Ayat (proofs, evidences, verses, lessons, signs, Revelations, etc.) for people who know.', 'He is the One who made for you the stars, so that you may be guided by them in darkness of the land and the sea. We have elaborated the signs for the people who know.'),
(887, 6, 98, 12, 18, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ ہُوَ الَّذِیۡۤ  اَنۡشَاَکُمۡ مِّنۡ نَّفۡسٍ وَّاحِدَۃٍ  فَمُسۡتَقَرٌّ وَّ مُسۡتَوۡدَعٌ ؕ قَدۡ فَصَّلۡنَا الۡاٰیٰتِ لِقَوۡمٍ  یَّفۡقَہُوۡنَ ﴿۹۸﴾', 'اور وہی تو ہے جس نے تم کو ایک شخص سے پیدا کیا پھر تمہارے لئے ایک ٹھہرنے کی جگہ ہے اور ایک سپرد ہونے کی۔ سمجھنے والوں کے لئے ہم نے اپنی آیتیں کھول کھول کر بیان کر دی ہیں۔', 'اور وہی ہے جس نے تم کو سب کو پیدا کیا ایک شخص سے [۱۳۱] پھر ایک تو تمہارا ٹھکانہ ہے اور ایک امانت رکھے جانے کی جگہ [۱۳۲] البتہ ہم نے کھول کر سنا دیے پتے اس کو جو سوچتے ہیں', 'It is He Who has created you from a single person (Adam), and has given you a place of residing (on the earth or in your mothers wombs) and a place of storage (in the earth (in your graves) or in your fathers loins). Indeed, We have explained in detail Our revelations (this Quran) for people who understand.', 'He is the One who created you from one person, then, you have a place to dwell and a place to sojourn. We have elaborated the signs for the people who understand.'),
(888, 6, 99, 12, 18, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ ہُوَ الَّذِیۡۤ  اَنۡزَلَ مِنَ السَّمَآءِ مَآءً ۚ فَاَخۡرَجۡنَا بِہٖ  نَبَاتَ کُلِّ شَیۡءٍ فَاَخۡرَجۡنَا مِنۡہُ خَضِرًا نُّخۡرِجُ مِنۡہُ حَبًّا مُّتَرَاکِبًا ۚ وَ مِنَ النَّخۡلِ مِنۡ طَلۡعِہَا قِنۡوَانٌ دَانِیَۃٌ  وَّ جَنّٰتٍ مِّنۡ اَعۡنَابٍ وَّ الزَّیۡتُوۡنَ  وَ الرُّمَّانَ  مُشۡتَبِہًا وَّ غَیۡرَ مُتَشَابِہٍ ؕ اُنۡظُرُوۡۤا اِلٰی ثَمَرِہٖۤ  اِذَاۤ  اَثۡمَرَ  وَ یَنۡعِہٖ ؕ اِنَّ  فِیۡ ذٰلِکُمۡ  لَاٰیٰتٍ  لِّقَوۡمٍ  یُّؤۡمِنُوۡنَ ﴿۹۹﴾', 'اور وہی تو ہے جو آسمان سے مینہ برساتا ہے۔ پھر ہم ہی جو مینہ برساتے ہیں اس سے ہر طرح کی نباتات اگاتے ہیں۔ پھر اس میں سے سبز سبز  پودے نکالتے ہیں اور ان پودوں سے ایک دوسرے کے ساتھ جڑے ہوئے دانے نکالتے ہیں۔ اور کھجور کے گابھے میں سے لٹکتے ہوئے گچھے اور انگوروں کے باغ اور زیتون اور انار جو ایک دوسرے سے ملتے جلتے بھی ہیں اور نہیں بھی ملتے یہ چیزیں جب پھلتی ہیں تو ان کے پھلوں پر اور جب پکتی ہیں تو ان کے پکنے پر نظر کرو۔ ان میں ان لوگوں کے لئے جو ایمان لاتے ہیں اللہ کی قدرت کی بہت سی نشانیاں ہیں۔', 'اور اسی نے اتارا آسمان سے پانی پھر نکالی ہم نے اس سے اگنے والی ہر چیز [۱۳۳] پھر نکالی اس میں سے سبز کھیتی جس سے ہم نکالتے ہیں دانے ایک پر ایک چڑھا ہوا اور کھجور کے گابھے میں سے پھل کے گچھے جھکے ہوئے [۱۳۴] اور باغ انگور کے اور زیتون کے اور انار کے آپس میں ملتے جلتے اور جدا جدا بھی [۱۳۵] دیکھو ہر ایک درخت کے پھل کو جب وہ پھل لاتا ہے اور اسکے پکنے کو [۱۳۶] ان چیزوں میں نشانیاں ہیں واسطے ایمان والوں کے [۱۳۷]', 'It is He Who sends down water (rain) from the sky, and with it We bring forth vegetation of all kinds, and out of it We bring forth green stalks, from which We bring forth thick clustered grain. And out of the datepalm and its spathe come forth clusters of dates hanging low and near, and gardens of grapes, olives and pomegranates, each similar (in kind) yet different (in variety and taste). Look at their fruits when they begin to bear, and the ripeness thereof. Verily! In these things there are signs for people who believe.', 'He is the One who sent down water from the heavens. Then We brought forth with it vegetation of all kinds. Then from it We brought grains set upon one another. From the palm-trees, from their spathes, come forth the low hanging bunches. (We produce) vineyards and the olive and the pomegranate, either similar or not similar to each other. Look at its fruit when it bears fruit, and at its ripening. Surely, in all this there are signs for the people who believe.'),
(889, 6, 100, 12, 18, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ جَعَلُوۡا لِلّٰہِ شُرَکَآءَ الۡجِنَّ وَ خَلَقَہُمۡ وَ خَرَقُوۡا لَہٗ  بَنِیۡنَ وَ بَنٰتٍۭ بِغَیۡرِ عِلۡمٍ ؕ سُبۡحٰنَہٗ وَ تَعٰلٰی عَمَّا یَصِفُوۡنَ ﴿۱۰۰﴾٪', 'اور ان لوگوں نے جنوں کو اللہ کا شریک ٹھہرایا حالانکہ انکو بھی اسی نے پیدا کیا۔ اور بے سمجھے جھوٹ بہتان اسکے لئے بیٹے اور بیٹیاں بنا کھڑی کیں۔ وہ ان باتوں سے جو اسکی نسبت بیان کرتے ہیں پاک ہے اور اسکی شان ان باتوں سے بلند ہے۔', 'اور ٹھہراتے ہیں اللہ کے شریک جنوں کو حالانکہ اس نے انکو پیدا کیا ہے [۱۳۸] اور تراشتے ہیں اسکے واسطے بیٹے اور بیٹیاں جہالت سے [۱۳۹] وہ پاک ہے اور بہت دور ہے ان باتوں سے جو یہ لوگ بیان کرتے ہیں [۱۴۰]', 'Yet, they join the jinns as partners in worship with Allah, though He has created them (the jinns), and they attribute falsely without knowledge sons and daughters to Him. Be He Glorified and Exalted above (all) that they attribute to Him.', 'They have invented the Jinns as partners with Allah, while He has created them; and they have fabricated for Him sons and daughters without any knowledge. Pure is He, and far more higher than what they describe.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(890, 6, 101, 13, 19, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'بَدِیۡعُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ اَنّٰی  یَکُوۡنُ  لَہٗ  وَلَدٌ وَّ لَمۡ تَکُنۡ لَّہٗ صَاحِبَۃٌ ؕ وَ خَلَقَ کُلَّ  شَیۡءٍ ۚ وَ ہُوَ بِکُلِّ شَیۡءٍ عَلِیۡمٌ ﴿۱۰۱﴾', 'وہی آسمانوں اور زمین کا پیدا کرنے والا ہے اسکے اولاد کہاں سے ہو جبکہ اسکی بیوی ہی نہیں اور اس نے ہر چیز کو پیدا کیا ہے اور وہ ہر چیز سے باخبر ہے۔', 'نئی طرح پر بنانے والا آسمان اور زمین کا [۱۴۱] کیونکر ہو سکتا ہے اسکے بیٹا حالانکہ اس کی کوئی عورت نہیں اور اس نے بنائی ہر چیز اور وہ ہر چیز سے واقف ہے [۱۴۲]', 'He is the Originator of the heavens and the earth. How can He have children when He has no wife? He created all things and He is the All-Knower of everything.', '(He is) the Originator of the heavens and the earth. How can He have a son when He never had a wife? He created everything, and He knows everything.'),
(891, 6, 102, 13, 19, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'ذٰلِکُمُ اللّٰہُ رَبُّکُمۡ ۚ  لَاۤ  اِلٰہَ  اِلَّا ہُوَ ۚ خَالِقُ کُلِّ شَیۡءٍ  فَاعۡبُدُوۡہُ ۚ  وَ  ہُوَ  عَلٰی کُلِّ  شَیۡءٍ   وَّکِیۡلٌ ﴿۱۰۲﴾', 'یہی اوصاف رکھنے والا اللہ تمہارا پررودگار ہے اسکے سوا کوئی معبود نہیں وہی ہر چیز کا پیدا کرنے والا ہے تو اسی کی عبادت کرو اور وہ ہر چیز کا نگران ہے۔', 'یہ اللہ تمہارا رب ہے نہیں ہے کوئی معبود سوا اسکے پیدا کرنے والا ہر چیز کا سو تم اسی کی عبادت کرو اور وہ ہرچیز پر کارساز ہے [۱۴۳]', 'Such is Allah, your Lord! La ilaha illa Huwa (none has the right to be worshipped but He), the Creator of all things. So worship Him (Alone), and He is the Wakeel (Trustee, Disposer of affairs, Guardian, etc.) over all things.', 'This is Allah: your Lord, there is no God but He, the Creator of everything; so, worship Him. He is Guardian over everything.'),
(892, 6, 103, 13, 19, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'لَا تُدۡرِکُہُ  الۡاَبۡصَارُ ۫ وَ ہُوَ یُدۡرِکُ الۡاَبۡصَارَ ۚ وَ  ہُوَ  اللَّطِیۡفُ الۡخَبِیۡرُ ﴿۱۰۳﴾', 'وہ ایسا ہے کہ نگاہیں اس کا ادراک نہیں کر سکتیں جبکہ وہ نگاہوں کا ادراک کر لیتا ہے۔ اور وہ بھید جاننے والا ہے خبردار ہے۔', 'نہیں پا سکتیں اس کو آنکھیں اور وہ پا سکتا ہے آنکھوں کو اور وہ نہایت لطیف اور خبردار ہے [۱۴۴]', 'No vision can grasp Him, but His Grasp is over all vision. He is the Most Subtle and Courteous, WellAcquainted with all things.', 'No vision can comprehend Him, and He comprehends all visions, and He is Absolutely Subtle, All-Aware.'),
(893, 6, 104, 13, 19, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'قَدۡ جَآءَکُمۡ بَصَآئِرُ مِنۡ رَّبِّکُمۡ ۚ فَمَنۡ اَبۡصَرَ فَلِنَفۡسِہٖ ۚ وَ مَنۡ عَمِیَ  فَعَلَیۡہَا ؕ وَ مَاۤ   اَنَا عَلَیۡکُمۡ  بِحَفِیۡظٍ ﴿۱۰۴﴾', 'اے  پیغمبر ان سے کہدو کہ تمہارے پاس تمہارے پروردگار کی طرف سے روشن دلیلیں پہنچ چکی ہیں تو جس نے ان کو آنکھ کھول کر دیکھا اس نے اپنا بھلا کیا اور جو اندھا بنا رہا اس نے اپنے حق میں برا کیا اور میں تمہارا نگہبان نہیں ہوں۔', 'تمہارے پاس آ چکیں نشانیاں تمہارے رب کی طرف سے پھر جس نے دیکھ لیا سو اپنے واسطے اور جو اندھا رہا سو اپنے نقصان کو اور میں نہیں تم پر نگہبان [۱۴۵]', 'Verily, proofs have come to you from your Lord, so whosoever sees, will do so for (the good of) his ownself, and whosoever blinds himself, will do so to his own harm, and I (Muhammad SAW) am not a watcher over you.', '(Say, O Prophet :) There have come to you insights from your Lord. Now, whoever uses his sight, does so for his own self, and whoever remains blind does so against his own self. I do not stand guard over you.'),
(894, 6, 105, 13, 19, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ کَذٰلِکَ نُصَرِّفُ الۡاٰیٰتِ وَ لِیَقُوۡلُوۡا دَرَسۡتَ وَ لِنُبَیِّنَہٗ  لِقَوۡمٍ یَّعۡلَمُوۡنَ ﴿۱۰۵﴾', 'اور ہم اسی طرح اپنی آیتیں پھیر پھیر کر بیان کرتے ہیں تاکہ کافر یہ نہ کہیں کہ تم یہ باتیں اہل کتاب سے سیکھے ہوئے ہو اور تاکہ ہم سمجھنے والے لوگوں کے لئے تشریح کر دیں۔', 'اور یوں طرح طرح سے سمجھاتے ہیں ہم آیتیں اور تاکہ وہ کہیں کہ تو نے کسی سے پڑھا ہے اور تاکہ واضح کر دیں ہم اسکو واسطے سمجھ والوں کے [۱۴۶]', 'Thus We explain variously the Verses so that they (the disbelievers) may say: \"You have studied (the Books of the people of the Scripture and brought this Quran from that)\" and that We may make the matter clear for the people who have knowledge.', 'This is how We bring the verses in diverse ways, so that they say, “you have been tutored”, and so that We may explain it to people who have knowledge.'),
(895, 6, 106, 13, 19, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'اِتَّبِعۡ مَاۤ  اُوۡحِیَ  اِلَیۡکَ مِنۡ رَّبِّکَ ۚ لَاۤ  اِلٰہَ  اِلَّا ہُوَ ۚ وَ اَعۡرِضۡ عَنِ الۡمُشۡرِکِیۡنَ ﴿۱۰۶﴾', 'اور جو حکم تمہارے پروردگار کی طرف سے تمہارے پاس آتا ہے اسی کی پیروی کرو اس پروردگار کے سوا کوئی معبود نہیں۔ اور مشرکوں سے کنارہ کر لو۔', 'تو چل اس پر جو حکم تجھ کو آوے تیرے رب کا کوئی معبود نہیں سوا اسکے اور منہ پھیر لے مشرکوں سے [۱۴۷]', 'Follow what has been inspired to you (O Muhammad SAW) from your Lord, La ilaha illa Huwa (none has the right to be worshipped but He) and turn aside from Al-Mushrikoon.', 'Follow what has been revealed to you from your Lord. There is no god but He; and turn away from those who associate partners with Allah.'),
(896, 6, 107, 13, 19, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ لَوۡ شَآءَ اللّٰہُ مَاۤ  اَشۡرَکُوۡا ؕ وَ مَا جَعَلۡنٰکَ عَلَیۡہِمۡ حَفِیۡظًا ۚ وَ مَاۤ  اَنۡتَ عَلَیۡہِمۡ  بِوَکِیۡلٍ ﴿۱۰۷﴾', 'اور اگر اللہ چاہتا تو یہ لوگ شرک نہ کرتے۔ اور اے پیغمبر ہم نے تمکو ان پر نگہبان مقرر نہیں کیا۔ اور نہ تم ان کے داروغہ ہو۔', 'اور اگر اللہ چاہتا تو وہ لوگ شرک نہ کرتے [۱۴۸] اور ہم نے نہیں کیا تجھ کو ان پر نگہبان اور نہیں ہے تو ان پر داروغہ [۱۴۹]', 'Had Allah willed, they would not have taken others besides Him in worship. And We have not made you a watcher over them nor are you set over them to dispose of their affairs.', 'If Allah willed, they would not have associated. We have not appointed you as a guard over them, nor are you a taskmaster for them.'),
(897, 6, 108, 13, 19, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ لَا تَسُبُّوا الَّذِیۡنَ یَدۡعُوۡنَ مِنۡ دُوۡنِ اللّٰہِ فَیَسُبُّوا اللّٰہَ عَدۡوًۢا بِغَیۡرِ عِلۡمٍ ؕ کَذٰلِکَ زَیَّنَّا لِکُلِّ  اُمَّۃٍ  عَمَلَہُمۡ ۪ ثُمَّ   اِلٰی رَبِّہِمۡ مَّرۡجِعُہُمۡ فَیُنَبِّئُہُمۡ بِمَا کَانُوۡا یَعۡمَلُوۡنَ ﴿۱۰۸﴾', 'اور جن لوگوں کو یہ مشرک اللہ کے سوا پکارتے ہیں ان کو برا نہ کہنا کہ یہ بھی کہیں اللہ کو بے ادبی سے بے سمجھے برا نہ کہہ بیٹھیں۔ اس طرح ہم نے ہر ایک امت کے اعمال انکی نظروں میں اچھے کر دکھائے ہیں۔ پھر انکو اپنے پروردگار کی طرف لوٹ کر جانا ہے تب وہ انکو بتائے گا کہ وہ کیا کیا کیا کرتے تھے۔', 'اور تم لوگو برا نہ کہو ان کو جنکی یہ پرستش کرتے ہیں اللہ کے سوا پس وہ برا کہنے لگیں گے اللہ کو بے ادبی سے بدون سمجھے [۱۵۰] اسی طرح ہم نے مزین کر دیا ہر ایک فرقہ کی نظر میں انکے اعمال کو پھر ان سب کو اپنے رب کے پاس پہنچنا ہے تب وہ جتلاوے گا انکو جو کچھ وہ کرتے تھے [۱۵۱]', 'And insult not those whom they (disbelievers) worship besides Allah, lest they insult Allah wrongfully without knowledge. Thus We have made fairseeming to each people its own doings; then to their Lord is their return and He shall then inform them of all that they used to do.', 'Do not revile those whom they invoke other than Allah, lest they should revile Allah in transgression without having knowledge. This is how We have made the deeds of every community attractive in their sight. Then, to their Lord is their return, after which He shall tell them what they have been doing.'),
(898, 6, 109, 13, 19, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ اَقۡسَمُوۡا بِاللّٰہِ جَہۡدَ  اَیۡمَانِہِمۡ لَئِنۡ جَآءَتۡہُمۡ  اٰیَۃٌ  لَّیُؤۡمِنُنَّ بِہَا ؕ قُلۡ  اِنَّمَا الۡاٰیٰتُ عِنۡدَ اللّٰہِ وَ مَا یُشۡعِرُکُمۡ ۙ اَنَّہَاۤ اِذَا جَآءَتۡ  لَا  یُؤۡمِنُوۡنَ ﴿۱۰۹﴾', 'اور یہ لوگ اللہ کی سخت سخت قسمیں کھاتے ہیں کہ اگر ان کے پاس کوئی نشانی آئے تو اس پر ضرور ایمان لے آئیں۔ کہدو کہ نشانیاں تو سب اللہ ہی کے پاس ہیں اور مومنو! تمہیں کیا معلوم ہے یہ تو ایسے بدبخت ہیں کہ انکے پاس نشانیاں آ بھی جائیں تب بھی ایمان نہ لائیں۔', 'اور وہ قسمیں کھاتےہیں اللہ کی تاکید سے کہ اگر آوے انکے پاس کوئی نشانی تو ضرور اس پر ایمان لاویں گے [۱۵۲] تو کہہ دے کہ نشانیاں تو اللہ کے پاس ہیں اور تم کو اے مسلمانو کیا خبر ہے کہ وہ نشانیاں آئیں گی تو یہ لوگ ایمان لے ہی آویں گے [۱۵۳]', 'And they swear their strongest oaths by Allah, that if there came to them a sign, they would surely believe therein. Say: \"Signs are but with Allah and what will make you (Muslims) perceive that (even) if it (the sign) came, they will not believe?\"', 'They have sworn forceful oaths by Allah that if a sign comes to them, they will surely believe in it. Say, “Signs are in Allah’s power alone.” What will make you realize that even when they (the signs) come, they will not believe?'),
(899, 6, 110, 13, 19, 7, 'وَ  اِذَا سَمِعُوۡا', 'الانعام', 'وَ نُقَلِّبُ اَفۡـِٕدَتَہُمۡ وَ اَبۡصَارَہُمۡ کَمَا لَمۡ یُؤۡمِنُوۡا بِہٖۤ  اَوَّلَ مَرَّۃٍ  وَّ نَذَرُہُمۡ فِیۡ طُغۡیَانِہِمۡ یَعۡمَہُوۡنَ ﴿۱۱۰﴾٪', 'اور ہم انکے دلوں اور آنکھوں کو الٹ دیں گے تو جیسے یہ اس قرآن پر پہلی دفعہ ایمان نہیں لائے ویسے پھر نہ لائیں گے اور ہم انکو چھوڑ دیں گے کہ اپنی سرکشی میں بہکتے رہیں۔', 'اور ہم الٹ دیں گے ان کے دل اور ان کی آنکھیں جیسے کہ ایمان نہیں لائے نشانیوں پر پہلی بار اور ہم چھوڑے رکھیں گے انکو انکی سرکشی میں بہکتے ہوئے [۱۵۴]', 'And We shall turn their hearts and their eyes away (from guidance), as they refused to believe therein for the first time, and We shall leave them in their trespass to wander blindly.', 'We will upset their hearts and sights, as they did not believe in them at the first instance, and We will leave them wandering blindly in their rebellion.'),
(900, 6, 111, 14, 1, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ لَوۡ اَنَّنَا نَزَّلۡنَاۤ  اِلَیۡہِمُ الۡمَلٰٓئِکَۃَ وَ کَلَّمَہُمُ الۡمَوۡتٰی وَ حَشَرۡنَا عَلَیۡہِمۡ کُلَّ شَیۡءٍ قُبُلًا مَّا کَانُوۡا لِیُؤۡمِنُوۡۤا اِلَّاۤ  اَنۡ یَّشَآءَ اللّٰہُ وَ لٰکِنَّ اَکۡثَرَہُمۡ یَجۡہَلُوۡنَ ﴿۱۱۱﴾', 'اور اگر ہم ان پر فرشتے بھی اتار دیتے اور مردے بھی ان سے گفتگو کرنے لگتے اور ہم سب چیزوں کو ان کے سامنے لا موجود بھی کر دیتے تو بھی یہ ایمان لانے والے نہ تھے۔ مگر یہ کہ اللہ چاہے۔ بات یہ ہے کہ یہ اکثر نادان ہیں۔', 'اور اگر ہم اتاریں ان پر فرشتے اور باتیں کریں ان سے مردے اور زندہ کر دیں ہم ہر چیز کو ان کےسامنے تو بھی یہ لوگ ہرگز ایمان لانےوالے نہیں مگر یہ کہ چاہے اللہ لیکن ان میں اکثر جاہل ہیں [۱۵۵]', 'And even if We had sent down unto them angels, and the dead had spoken unto them, and We had gathered together all things before their very eyes, they would not have believed, unless Allah willed, but most of them behave ignorantly.', 'If We had sent down to them the angels, and the dead had spoken to them, and (even if) We had gathered everything before them face to face, still, they were not to believe, unless Allah would have so willed. But, most of them adopt the way of ignorance.'),
(901, 6, 112, 14, 1, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ کَذٰلِکَ جَعَلۡنَا لِکُلِّ نَبِیٍّ عَدُوًّا شَیٰطِیۡنَ الۡاِنۡسِ وَ  الۡجِنِّ  یُوۡحِیۡ بَعۡضُہُمۡ اِلٰی بَعۡضٍ زُخۡرُفَ الۡقَوۡلِ غُرُوۡرًا ؕ وَ لَوۡ شَآءَ رَبُّکَ مَا فَعَلُوۡہُ فَذَرۡہُمۡ وَ مَا یَفۡتَرُوۡنَ ﴿۱۱۲﴾', 'اور اسی طرح ہم نے شیطان سیرت انسانوں اور جنوں کو ہر پیغمبر کا دشمن بنا دیا تھا۔ وہ دھوکا دینے کے لئے ایک دوسرے کے دل میں ملمع کی ہوئی باتیں ڈالتے رہتے تھے اور اگر تمہارا پروردگار چاہتا تو وہ ایسا نہ کرتے سو ان کو اور جو کچھ یہ افترا کرتے ہیں اسے چھوڑ دو۔', 'اور اسی طرح کر دیا ہم نے [۱۵۶] ہر نبی کے لئے دشمن شریر آدمیوں کو اور جنوں کو جو کہ سکھلاتے ہیں ایک دوسرے کو ملمع کی ہوئی باتیں فریب دینے کے لئے اور اگر تیرا رب چاہتا تو وہ لوگ یہ کام نہ کرتے سو تو چھوڑ دے وہ جانیں اور انکا جھوٹ [۱۵۷]', 'And so We have appointed for every Prophet enemies - Shayatin (devils) among mankind and jinns, inspiring one another with adorned speech as a delusion (or by way of deception). If your Lord had so willed, they would not have done it, so leave them alone with their fabrications. (Tafseer Qurtubi, Vol.7, Page 67)', 'So it is that, for every prophet, We have set up enemies,-the devils of mankind and jinn-who seduce one another with alluring rhetoric in order to deceive-Had Allah willed, they would have not done it. So, leave them alone with what they forge-'),
(902, 6, 113, 14, 1, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ لِتَصۡغٰۤی اِلَیۡہِ اَفۡـِٕدَۃُ الَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِالۡاٰخِرَۃِ وَ لِیَرۡضَوۡہُ وَ لِیَقۡتَرِفُوۡا  مَا  ہُمۡ  مُّقۡتَرِفُوۡنَ ﴿۱۱۳﴾', 'اور وہ ایسے کام اس لئے بھی کرتے تھے کہ جو لوگ آخرت پر ایمان نہیں رکھتے ان کے دل ان کی باتوں پر مائل ہوں اور وہ انہیں پسند کریں اور جو کام وہ کرتے تھے وہی کرنے لگیں۔', 'اور اس لئے کہ مائل ہوں ان کی ملمع کی باتوں کی طرف ان لوگوں کے دل جنکو  یقین نہیں آخرت کا اور وہ اسکو پسند بھی کر لیں اور کئے جاویں جو کچھ برے کام کر رہے ہیں [۱۵۸]', '(And this is in order) that the hearts of those who disbelieve in the Hereafter may incline to such (deceit), and that they may remain pleased with it, and that they may commit what they are committing (all kinds of sins and evil deeds, etc.).', '-and (they seduce one another) in order that the hearts of those who do not believe in the Hereafter may incline to it, and that they may be well pleased with it, and so that they commit what those (seducers) are used to commit.'),
(903, 6, 114, 14, 1, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'اَفَغَیۡرَ اللّٰہِ اَبۡتَغِیۡ حَکَمًا وَّ ہُوَ الَّذِیۡۤ اَنۡزَلَ  اِلَیۡکُمُ الۡکِتٰبَ مُفَصَّلًا ؕ وَ الَّذِیۡنَ اٰتَیۡنٰہُمُ الۡکِتٰبَ یَعۡلَمُوۡنَ اَنَّہٗ مُنَزَّلٌ مِّنۡ رَّبِّکَ بِالۡحَقِّ فَلَا تَکُوۡنَنَّ  مِنَ الۡمُمۡتَرِیۡنَ ﴿۱۱۴﴾', 'کہو کیا میں اللہ کے سوا اور منصف تلاش کروں حالانکہ اس نے تمہاری طرف صاف مضامین والی کتاب بھیجی ہے۔ اور جن لوگوں کو ہم نے کتاب یعنی تورات دی ہے وہ جانتے ہیں کہ یہ تمہارے پروردگار کی طرف سے برحق نازل ہوئی ہے سو تم ہر گز شک کرنے والوں میں نہ ہونا۔', 'سو کیا اب اللہ کے سوا کسی اور کو منصف بناؤں حالانکہ اسی نے اتاری تم پر کتاب واضح اور جن لوگوں کو ہم نے کتاب دی ہے وہ جانتے ہیں کہ یہ نازل ہوئی ہے تیرے رب کی طرف سے ٹھیک سو تو مت ہو شک کرنے والوں میں سے', '(Say (O Muhammad SAW)) \"Shall I seek a judge other than Allah while it is He Who has sent down unto you the Book (The Quran), explained in detail.\" Those unto whom We gave the Scripture (the Taurat (Torah) and the Injeel (Gospel)) know that it is revealed from your Lord in truth. So be not you of those who doubt.', 'So, should I seek someone other than Allah as judge, while it is He who has sent down to you the Book in details? Those We have given the Book know that it is revealed from your Lord with the truth. So, never be one of those who are in suspicion.'),
(904, 6, 115, 14, 1, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ تَمَّتۡ  کَلِمَتُ رَبِّکَ صِدۡقًا وَّ عَدۡلًا ؕ لَا مُبَدِّلَ لِکَلِمٰتِہٖ ۚ وَ ہُوَ السَّمِیۡعُ الۡعَلِیۡمُ ﴿۱۱۵﴾', 'اور تمہارے پروردگار کی باتیں سچائی اور انصاف میں پوری ہیں اسکی باتوں کو کوئی بدلنے والا نہیں اور وہ سنتا ہے جانتا ہے۔', 'اور تیرے رب کی بات پوری سچی ہے اور انصاف کی کوئی بدلنے والا نہیں اس کی بات کو اور وہی ہے سننے والا جاننے والا [۱۵۹]', 'And the Word of your Lord has been fulfilled in truth and in justice. None can change His Words. And He is the AllHearer, the AllKnower.', 'The Word of your Lord is perfect in truth and justice. None is there to change His words, and He is All-Hearing, All-Knowing.'),
(905, 6, 116, 14, 1, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ اِنۡ تُطِعۡ  اَکۡثَرَ مَنۡ  فِی الۡاَرۡضِ یُضِلُّوۡکَ عَنۡ سَبِیۡلِ اللّٰہِ ؕ اِنۡ یَّتَّبِعُوۡنَ اِلَّا الظَّنَّ  وَ اِنۡ  ہُمۡ  اِلَّا یَخۡرُصُوۡنَ ﴿۱۱۶﴾', 'اور اکثر لوگ جو زمین پر آباد ہیں گمراہ ہیں اگر تم ان کا کہا مان لو گے تو وہ تمہیں اللہ کا رستہ بھلا دیں گے۔ یہ محض گمان کے پیچھے چلتے اور نرے اٹکل کے تیر چلاتے ہیں۔', 'اور اگر تو کہنا مانے گا ان لوگوں کا جو دنیا میں ہیں تو تجھ کو بہکا دیں گے اللہ کی راہ سے وہ سب تو چلتے ہیں اپنے خیال پر اور سب اٹکل ہی دوڑاتے ہیں [۱۶۰]', 'And if you obey most of those on earth, they will mislead you far away from Allahs Path. They follow nothing but conjectures, and they do nothing but lie.', 'If you obey the majority of those on earth, they will make you lose the way of Allah. They follow nothing but whims, and they do nothing but make conjectures.'),
(906, 6, 117, 14, 1, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'اِنَّ  رَبَّکَ ہُوَ اَعۡلَمُ مَنۡ یَّضِلُّ عَنۡ سَبِیۡلِہٖ ۚ وَ ہُوَ اَعۡلَمُ بِالۡمُہۡتَدِیۡنَ ﴿۱۱۷﴾', 'تمہارا پروردگار ان لوگوں کو خوب جانتا ہے جو اس کے رستے سے بھٹکے ہوئے ہیں اور ان سے بھی خوب واقف ہے جو رستے پر چل رہے ہیں۔', 'تیرا رب خوب جاننے والا ہے اس کو جو بہکتا ہے اس کی راہ سے اور وہی خوب جاننے والا ہے انکو جو اس کی راہ پر ہیں', 'Verily, your Lord! It is He Who knows best who strays from His Way, and He knows best the rightly guided ones.', 'Surely, your Lord is best aware of those who go astray from His way, and He is best aware of those who are on the right path.'),
(907, 6, 118, 14, 1, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'فَکُلُوۡا مِمَّا ذُکِرَ اسۡمُ اللّٰہِ عَلَیۡہِ  اِنۡ کُنۡتُمۡ  بِاٰیٰتِہٖ  مُؤۡمِنِیۡنَ ﴿۱۱۸﴾', 'سو جس چیز پر ذبح کے وقت اللہ کا نام لیا جائے اگر تم اسکی آیتوں پر ایمان رکھتے ہو تو اسے کھا لیا کرو۔', 'سو تم کھاؤ اس جانور میں سے جس پر نام لیا گیا ہے اللہ کا اگر تم کو اس کے حکموں پر ایمان ہے [۱۶۱]', 'So eat of that (meat) on which Allahs Name has been pronounced (while slaughtering the animal), if you are believers in His Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.).', 'So, eat (the flesh) of that (animal) upon which the name of Allah has been invoked (when slaughtering), if you do believe in His verses.'),
(908, 6, 119, 14, 1, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ مَا لَکُمۡ  اَلَّا تَاۡکُلُوۡا مِمَّا ذُکِرَ اسۡمُ اللّٰہِ عَلَیۡہِ  وَ قَدۡ فَصَّلَ لَکُمۡ مَّا حَرَّمَ عَلَیۡکُمۡ اِلَّا مَا اضۡطُرِرۡتُمۡ  اِلَیۡہِ ؕ وَ اِنَّ کَثِیۡرًا لَّیُضِلُّوۡنَ بِاَہۡوَآئِہِمۡ بِغَیۡرِ عِلۡمٍ ؕ اِنَّ رَبَّکَ ہُوَ اَعۡلَمُ  بِالۡمُعۡتَدِیۡنَ ﴿۱۱۹﴾', 'اور سبب کیا ہے کہ جس چیز پر اللہ کا نام لیا جائے تم اسے نہ کھاؤ حالانکہ جو چیزیں اس نے تمہارے لئے حرام ٹھیرا دی ہیں وہ ایک ایک کر کے بیان کر دی ہیں بیشک انکو نہیں کھانا چاہیے مگر اس صورت میں کہ انکے کھانے کے لئے ناچار ہو جاؤ۔ اور بہت سے لوگ بے سمجھے بوجھے اپنے نفس کی خواہشوں سے لوگوں کو بہکا رہے ہیں کچھ شک نہیں کہ ایسے لوگوں کو جو اللہ کی مقرر کی ہوئی حد سے باہر نکل جاتے ہیں تمہارا پروردگار خوب جانتا ہے۔', 'اور کیا سبب کہ تم نہیں کھاتے اس جانور میں سے کہ جس پر نام لیا گیا ہے اللہ کا اور وہ واضح کر چکا ہے جو کچھ کہ اس نے تم پر حرام کیا ہے مگر جب کہ مجبور ہو جاؤ اسکے کھانے پر [۱۶۲] اور بہت لوگ بہکاتے پھرتے ہیں اپنے خیالات پر بغیر تحقیق تیرا رب ہی خوب جانتا ہے حد سے بڑھنے والوں کو [۱۶۳]', 'And why should you not eat of that (meat) on which Allahs Name has been pronounced (at the time of slaughtering the animal), while He has explained to you in detail what is forbidden to you, except under compulsion of necessity? And surely many do lead (mankind) astray by their own desires through lack of knowledge. Certainly your Lord knows best the transgressors.', 'What should cause you to avoid eating of that upon which the name of Allah has been invoked, while He has spelled out to you all that He has made unlawful for you, except that to which you are compelled by extreme necessity? Surely, there are many who misguide people on the basis of their desires without having knowledge. Surely, your Lord is the best knower of those who cross the limits.'),
(909, 6, 120, 14, 1, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ ذَرُوۡا ظَاہِرَ الۡاِثۡمِ وَ بَاطِنَہٗ ؕ اِنَّ الَّذِیۡنَ یَکۡسِبُوۡنَ الۡاِثۡمَ  سَیُجۡزَوۡنَ بِمَا کَانُوۡا  یَقۡتَرِفُوۡنَ ﴿۱۲۰﴾', 'اور ظاہری اور پوشیدہ ہر طرح کا گناہ ترک کر دو۔ جو لوگ گناہ کرتے ہیں وہ عنقریب اپنے کئے کی سزا پائیں گے۔', 'اور چھوڑ دو کھلا ہوا گناہ اور چھپا ہوا جو لوگ گناہ کرتے ہیں عنقریب سزا پاویں گے اپنے کئے کی [۱۶۴]', 'Leave (O mankind, all kinds of) sin, open and secret. Verily, those who commit sin will get due recompense for that which they used to commit.', 'Leave outward sin and inward sin. Surely, those who commit sin shall be punished for what they used to commit.'),
(910, 6, 121, 14, 1, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ لَا تَاۡکُلُوۡا مِمَّا لَمۡ یُذۡکَرِ اسۡمُ اللّٰہِ عَلَیۡہِ  وَ اِنَّہٗ لَفِسۡقٌ ؕ وَ  اِنَّ الشَّیٰطِیۡنَ لَیُوۡحُوۡنَ اِلٰۤی اَوۡلِیٰٓئِہِمۡ لِیُجَادِلُوۡکُمۡ ۚ وَ اِنۡ  اَطَعۡتُمُوۡہُمۡ  اِنَّکُمۡ  لَمُشۡرِکُوۡنَ ﴿۱۲۱﴾٪', 'اور جس چیز پر اللہ کا نام نہ لیا جائے اسے مت کھاؤ کہ اسکا کھانا گناہ ہے اور شیطان لوگ اپنے رفیقوں کے دلوں میں یہ بات ڈالتے ہیں کہ تم سے جھگڑا کریں اور اگر تم لوگ ان کے کہے پر چلے تو بیشک تم بھی مشرک ہوئے۔', 'اور اس میں سے نہ کھاؤ جس پر نام نہیں لیا گیا اللہ کا [۱۶۵] اور یہ کھانا گناہ ہے اور شیطان دل میں ڈالتے ہیں اپنے رفیقوں کے تاکہ وہ تم سے جھگڑا کریں اور اگر تم نے انکا کہا مانا تو تم بھی مشرک ہوئے [۱۶۶]', 'Eat not (O believers) of that (meat) on which Allahs Name has not been pronounced (at the time of the slaughtering of the animal), for sure it is Fisq (a sin and disobedience of Allah). And certainly, the Shayatin (devils) do inspire their friends (from mankind) to dispute with you, and if you obey them (by making AlMaytatah (a dead animal) legal by eating it), then you would indeed be Mushrikoon (polytheists) (because they (devils and their friends) made lawful to you to eat that which Allah has made unlawful to eat and you obeyed them by considering it lawful to eat, and by doing so you worshipped them, and to worship others besides Allah is polytheism).', 'Do not eat that (meat) over which the name of Allah has not been pronounced. This is surely a sin. The satans inspire their friends to dispute with you. If you were to obey them, you would be Mushriks.'),
(911, 6, 122, 15, 2, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'اَوَ مَنۡ کَانَ مَیۡتًا فَاَحۡیَیۡنٰہُ وَ جَعَلۡنَا لَہٗ نُوۡرًا یَّمۡشِیۡ بِہٖ فِی النَّاسِ کَمَنۡ مَّثَلُہٗ فِی الظُّلُمٰتِ لَیۡسَ بِخَارِجٍ مِّنۡہَا ؕ کَذٰلِکَ زُیِّنَ لِلۡکٰفِرِیۡنَ مَا کَانُوۡا یَعۡمَلُوۡنَ ﴿۱۲۲﴾', 'بھلا جو پہلے مردہ تھا پھر ہم نے اسکو زندہ کیا اور اسکے لئے روشنی کر دی جس کے ذریعے سے وہ لوگوں میں چلتا پھرتا ہے کہیں اس شخص جیسا ہو سکتا ہے جو اندھیرے میں پڑا ہوا ہو اور اس سے نکل ہی نہ سکے۔ اسی طرح کافر جو عمل کر رہے ہیں وہ انہیں اچھے معلوم ہو تے ہیں۔', 'بھلا ایک شخص جو کہ مردہ تھا پھر ہم نے اس کو زندہ کر دیا اور ہم نے اس کو دی روشنی کہ لئے پھرتا ہے اس کو لوگوں میں برابر ہو سکتا ہےاسکے کہ جس کا حال یہ ہے کہ پڑا ہے اندھیروں میں وہاں سے نکل نہیں سکتا اسی طرح مزین کر دیے کافروں کی نگاہ میں ان کے کام [۱۶۷]', 'Is he who was dead (without Faith by ignorance and disbelief) and We gave him life (by knowledge and Faith) and set for him a light (of Belief) whereby he can walk amongst men, like him who is in the darkness (of disbelief, polytheism and hypocrisy) from which he can never come out? Thus it is made fairseeming to the disbelievers that which they used to do.', 'Is it (conceivable) that the one who was dead and to whom We gave life, and set for him a light with which he walks among men, (is held to) be like the one whose condition is such that he is in total darkness, never coming out of it? This is how their deeds appear beautified to the disbelievers.'),
(912, 6, 123, 15, 2, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ کَذٰلِکَ جَعَلۡنَا فِیۡ کُلِّ قَرۡیَۃٍ اَکٰبِرَ مُجۡرِمِیۡہَا لِیَمۡکُرُوۡا فِیۡہَا ؕ وَ مَا یَمۡکُرُوۡنَ  اِلَّا بِاَنۡفُسِہِمۡ وَ مَا یَشۡعُرُوۡنَ ﴿۱۲۳﴾', 'اور اسی طرح ہم نے ہر بستی میں بڑے بڑے مجرموں کو موقع دیا کہ اس میں مکاریاں کرتے رہیں۔ اور جو مکاریاں یہ کرتے ہیں ان کا نقصان انہیں کو ہے اور اس سے بے خبر ہیں۔', 'اور اسی طرح کئے ہیں ہم نے ہر بستی میں گنہگاروں کے سردار کہ حیلے کیا کریں وہاں اور جو حیلہ کرتے ہیں سو اپنی ہی جان پر اور نہیں سوچتے [۱۶۸]', 'And thus We have set up in every town great ones of its wicked people to plot therein. But they plot not except against their ownselves, and they perceive (it) not.', 'In a similar way, in every town We caused its chief sinners to commit mischief in it. And they do not commit mischief but against themselves, while they do not realize it.'),
(913, 6, 124, 15, 2, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ اِذَا جَآءَتۡہُمۡ اٰیَۃٌ  قَالُوۡا لَنۡ نُّؤۡمِنَ حَتّٰی نُؤۡتٰی مِثۡلَ مَاۤ اُوۡتِیَ رُسُلُ اللّٰہِ ؕۘؔ اَللّٰہُ اَعۡلَمُ حَیۡثُ یَجۡعَلُ رِسَالَتَہٗ ؕ سَیُصِیۡبُ الَّذِیۡنَ اَجۡرَمُوۡا صَغَارٌ عِنۡدَ اللّٰہِ وَ عَذَابٌ شَدِیۡدٌۢ بِمَا کَانُوۡا یَمۡکُرُوۡنَ ﴿۱۲۴﴾', 'اور جب انکے پاس کوئی آیت آتی ہے تو کہتے ہیں کہ جس طرح کی رسالت اللہ کے پیغمبروں کو ملی ہے جب تک اسی طرح کی رسالت ہم کو نہ ملے ہم ہرگز ایمان نہیں لائیں گے اسکو اللہ ہی خوب جانتا ہے کہ رسالت کا کونسا موقع ہے اور وہ اپنی پیغمبری کسے عنایت فرمائے۔ جو لوگ جرم کرتے ہیں انکو اللہ کے ہاں ذلت نصیب ہو گی اور عذاب شدید ہوگا اس لئے کہ مکاریاں کرتے تھے۔', 'اور جب آتی ہے انکے پاس کوئی آیت تو کہتے ہیں کہ ہم ہرگز نہ مانیں گےجب تک کہ نہ دیا جاوے ہم کو جیسا کچھ کہ دیا گیا ہے اللہ کے رسولوں کو اللہ خوب جانتا ہے اس موقع کو کہ جہاں بھیجے اپنے پیغام عنقریب پہنچے گی گنہگاروں کو ذلت اللہ کے ہاں اور عذاب سخت اس وجہ سےکہ وہ مکر کرتے تھے [۱۶۹]', 'And when there comes to them a sign (from Allah) they say: \"We shall not believe until we receive the like of that which the Messengers of Allah had received.\" Allah knows best with whom to place His Message. Humiliation and disgrace from Allah and a severe torment will overtake the criminals (polytheists, sinners, etc.) for that which they used to plot.', 'When a sign comes to them, they say, “We shall never come to believe unless we are given the like of what was given to the messengers of Allah.” Allah knows best where to place His message. Those who committed sin shall soon suffer from disgrace before Allah and face severe punishment for the mischief they have been making.'),
(914, 6, 125, 15, 2, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'فَمَنۡ یُّرِدِ اللّٰہُ اَنۡ یَّہۡدِیَہٗ یَشۡرَحۡ صَدۡرَہٗ لِلۡاِسۡلَامِ ۚ وَ مَنۡ یُّرِدۡ  اَنۡ یُّضِلَّہٗ یَجۡعَلۡ صَدۡرَہٗ ضَیِّقًا حَرَجًا کَاَنَّمَا یَصَّعَّدُ فِی السَّمَآءِ ؕ کَذٰلِکَ یَجۡعَلُ اللّٰہُ الرِّجۡسَ عَلَی الَّذِیۡنَ لَا  یُؤۡمِنُوۡنَ ﴿۱۲۵﴾', 'تو جس شخص کو اللہ چاہتا ہے کہ ہدایت بخشے اس کا سینہ اسلام کے لئے کھول دیتا ہے اور جسے چاہتا ہے کہ گمراہ کرے اس کا سینہ تنگ اور گھٹا ہوا کر دیتا ہے۔ گویا وہ آسمان پر چڑھ رہا ہے۔ اس طرح اللہ ان لوگوں پر جو ایمان نہیں لاتے عذاب بھیجتا ہے۔', 'سو جس کو اللہ چاہتا ہے کہ ہدایت کرے تو کھول دیتا ہے اسکے سینہ کو واسطے قبول کرنے اسلام کے اور جس کو چاہتا ہے کہ گمراہ کرے کر دیتا ہے اس کےسینہ کو تنگ بے نہایت تنگ گویا وہ زور سے چڑھتا ہے آسمان پر [۱۷۰] اسی طرح ڈالے گا اللہ عذاب کو ایمان نہ لانے والوں پر', 'And whomsoever Allah wills to guide, He opens his breast to Islam, and whomsoever He wills to send astray, He makes his breast closed and constricted, as if he is climbing up to the sky. Thus Allah puts the wrath on those who believe not.', 'So, whomsoever Allah wills to guide, He makes his heart wide open for Islam, and whomsoever He wills to let go astray, He makes his heart strait and constricted, (and he feels embracing Islam as difficult) as if he were climbing to the sky. In this way, Allah lays abomination on those who do not believe.'),
(915, 6, 126, 15, 2, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ ہٰذَا صِرَاطُ رَبِّکَ مُسۡتَقِیۡمًا ؕ قَدۡ فَصَّلۡنَا الۡاٰیٰتِ  لِقَوۡمٍ  یَّذَّکَّرُوۡنَ ﴿۱۲۶﴾', 'اور یہی تمہارے پروردگار کا سیدھا رستہ ہے جو لوگ غور کرنے والے ہیں ان کے لئے ہم نے اپنی آیتیں کھول کھول کر بیان کر دی ہیں۔', 'اور یہ رستہ ہے تیرے رب کا سیدھا ہم نے واضح کر دیا نشانیوں کو غور کرنے والوں کے واسطے [۱۷۱]', 'And this is the Path of your Lord (the Quran and Islam) leading Straight. We have detailed Our Revelations for a people who take heed.', 'This is the path of your Lord, a straight path. We have made the verses elaborate for people who accept the advice.'),
(916, 6, 127, 15, 2, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'لَہُمۡ دَارُ السَّلٰمِ عِنۡدَ رَبِّہِمۡ وَ ہُوَ وَلِیُّہُمۡ  بِمَا  کَانُوۡا  یَعۡمَلُوۡنَ ﴿۱۲۷﴾', 'ان کے لئے ان کے اعمال کے صلے میں پروردگار کے ہاں سلامتی کا گھر ہے۔ اور وہی انکا دوست ہے۔', 'انہی کے لئےہے سلامتی کا گھر اپنے رب کے ہاں اور وہ انکا مددگار ہے بسبب انکے اعمال کے [۱۷۲]', 'For them will be the home of peace (Paradise) with their Lord. And He will be their Walee (Helper and Protector) because of what they used to do.', 'For them there is the Abode of Peace with their Lord, and He is their Guardian by virtue of what they used to do.'),
(917, 6, 128, 15, 2, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ  یَوۡمَ یَحۡشُرُہُمۡ جَمِیۡعًا ۚ یٰمَعۡشَرَ   الۡجِنِّ قَدِ اسۡتَکۡثَرۡتُمۡ مِّنَ الۡاِنۡسِ ۚ وَ قَالَ اَوۡلِیٰٓؤُہُمۡ مِّنَ الۡاِنۡسِ رَبَّنَا اسۡتَمۡتَعَ بَعۡضُنَا بِبَعۡضٍ وَّ بَلَغۡنَاۤ  اَجَلَنَا الَّذِیۡۤ  اَجَّلۡتَ لَنَا ؕ قَالَ النَّارُ مَثۡوٰىکُمۡ خٰلِدِیۡنَ فِیۡہَاۤ اِلَّا مَا شَآءَ اللّٰہُ ؕ اِنَّ رَبَّکَ حَکِیۡمٌ  عَلِیۡمٌ ﴿۱۲۸﴾', 'اور جس دن وہ سب جن و انس کو جمع کرے گا اور فرمائے گا کہ اے گروہ جنات تم نے انسانوں سے بہت فائدے حاصل کئے۔ تو جو انسانوں میں انکے  دوست ہوں گے وہ کہیں گے کہ پروردگار ہم ایک دوسرے سے فائدہ حاصل کرتے رہے۔ اور آخر اس وقت کو پہنچ گئے جو تو نے ہمارے لئے مقرر کیا تھا۔ اللہ فرمائے گا اب تمہارا ٹھکانہ دوزخ ہے ہمیشہ اس میں جلتے رہو گے مگر جو اللہ چاہے۔ بیشک تمہارا پروردگار دانا ہے خبردار ہے۔', 'اور جس دن جمع کرے گا ان سب کو فرمائے گا اے جماعت جنات کی تم نے بہت کچھ تابع کر لئے اپنے آدمیوں میں سے [۱۷۳]  اور کہیں گے ان کے دوستدار آدمیوں میں سے اے رب ہمارے کام نکالا ہم میں ایک نے دوسرے سے اور ہم پہنچے اپنے اس وعدہ کو جو تو نے ہمارے لئے مقرر کیا تھا [۱۷۴] فرماوے گا آگ ہے گھر تمہارا رہا کرو گے اسی میں مگر جب چاہے اللہ [۱۷۵] البتہ تیرا رب حکمت والا خبردار ہے [۱۷۶]', 'And on the Day when He will gather them (all) together (and say): \"O you assembly of jinns! Many did you mislead of men,\" and their Auliya (friends and helpers, etc.) amongst men will say: \"Our Lord! We benefited one from the other, but now we have reached our appointed term which You did appoint for us.\" He will say: \"The Fire be your dwellingplace, you will dwell therein forever, except as Allah may will. Certainly your Lord is AllWise, AllKnowing.\"', 'The day He will assemble all of them together, (Allah will say to Jinn) “O species of Jinns, you have done too much against mankind.” Their friends from among the human beings will say, “Our Lord, some of us have benefited from others, and we have reached our term that You had appointed for us.” He will say, “The Fire is your Abode wherein you will remain for ever, unless Allah wills (otherwise). Surely, your Lord is All-Wise, All-Knowing.”'),
(918, 6, 129, 15, 2, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ  کَذٰلِکَ نُوَلِّیۡ بَعۡضَ الظّٰلِمِیۡنَ بَعۡضًۢا بِمَا  کَانُوۡا  یَکۡسِبُوۡنَ ﴿۱۲۹﴾٪', 'اور اسی طرح ہم ظالموں کو ان کے اعمال کے سبب جو وہ کرتے تھے ایک دوسرے کے قریب کر دیں گے۔', 'اور اسی طرح ہم ساتھ ملاویں گے گنہگاروں کو ایک کو دوسرے سے ان کے اعمال کے سبب [۱۷۷]', 'And thus We do make the Zalimoon (polytheists and wrongdoers, etc.) Auliya (supporters and helpers) one to another (in committing crimes etc.), because of that which they used to earn.', 'Thus We will make some wrongdoers companions of others (in the Hereafter) because of what they used to commit.'),
(919, 6, 130, 16, 3, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'یٰمَعۡشَرَ الۡجِنِّ وَ الۡاِنۡسِ اَلَمۡ یَاۡتِکُمۡ رُسُلٌ مِّنۡکُمۡ  یَقُصُّوۡنَ عَلَیۡکُمۡ  اٰیٰتِیۡ  وَ یُنۡذِرُوۡنَکُمۡ  لِقَآءَ  یَوۡمِکُمۡ ہٰذَا ؕ قَالُوۡا شَہِدۡنَا عَلٰۤی اَنۡفُسِنَا وَ غَرَّتۡہُمُ الۡحَیٰوۃُ الدُّنۡیَا  وَ شَہِدُوۡا عَلٰۤی اَنۡفُسِہِمۡ  اَنَّہُمۡ  کَانُوۡا کٰفِرِیۡنَ ﴿۱۳۰﴾', 'اے جنوں اور انسانوں کی جماعت کیا تمہارے پاس تم ہی میں سے پیغمبر نہیں آتے رہے جو میری آیتیں تم کو پڑھ پڑھ کر سناتے اور تمہارے اس دن کے سامنے آ موجود ہونے سے ڈراتے تھے۔ وہ کہیں گے کہ پروردگار ہمیں اپنے گناہوں کا اقرار ہے۔ اور ان لوگوں کو دنیا کی زندگی نے دھوکے میں ڈال رکھا تھا۔ اور اب خود انہوں نے اپنے اوپر گواہی دی کہ کفر کرتے تھے۔', 'اے جماعت جنوں کی اور انسانوں کی کیا نہیں پہنچے تھے تمہارے پاس رسول تمہی میں سے کہ سناتے تھے تم کو میرے حکم اور ڈراتے تھے تم کو اس دن کے پیش آنے سے [۱۷۸] کہیں گے کہ ہم نے اقرار کر لیا اپنے گناہ کا اور ان کو دھوکا دیا دنیا کی زندگی نے [۱۷۹] اور قائل ہو گئے اپنے اوپر اس بات کے کہ وہ کافر تھے [۱۸۰]', 'O you assembly of jinns and mankind! \"Did not there come to you Messengers from amongst you, reciting unto you My Verses and warning you of the meeting of this Day of yours?\" They will say: \"We bear witness against ourselves.\" It was the life of this world that deceived them. And they will bear witness against themselves that they were disbelievers.', '“O species of Jinn and mankind, had the messengers not come to you, from among yourselves, who used to relate My verses to you, and used to warn you of the encounter of this your day?” They will say, “We testify against ourselves.” The worldly life had deceived them, and they will testify against themselves that they were disbelievers.'),
(920, 6, 131, 16, 3, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'ذٰلِکَ اَنۡ لَّمۡ یَکُنۡ رَّبُّکَ مُہۡلِکَ الۡقُرٰی بِظُلۡمٍ   وَّ  اَہۡلُہَا غٰفِلُوۡنَ ﴿۱۳۱﴾', 'اے نبی یہ جو پیغمبر آتے رہے اور کتابیں نازل ہوتی رہیں تو اس لئے کہ تمہارا پروردگار ایسا نہیں کہ بستیوں کو ظلم سے ہلاک کر دے اور وہاں کے رہنے والوں کو کچھ بھی خبر نہ ہو۔', 'یہ اس واسطے کہ تیرا رب ہلاک کرنے والا نہیں بستیوں کو انکے ظلم پر اور وہاں کے لوگ بے خبر ہوں', 'This is because your Lord would not destroy the (populations of) towns for their wrongdoing (i.e. associating others in worship along with Allah) while their people were unaware (so the Messengers were sent).', 'That (Allah sends messengers) is because your Lord is not to destroy any towns on account of any wrongdoing, while their people are unaware.'),
(921, 6, 132, 16, 3, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ لِکُلٍّ دَرَجٰتٌ مِّمَّا عَمِلُوۡا ؕ وَ مَا رَبُّکَ بِغَافِلٍ عَمَّا  یَعۡمَلُوۡنَ ﴿۱۳۲﴾', 'اور سب لوگوں کے بلحاظ اعمال درجے مقرر ہیں اور جو کام یہ لوگ کرتے ہیں اللہ ان سے بیخبر نہیں۔', 'اور ہر ایک کے لئے درجے ہیں انکے عمل کے اور تیرا رب بیخبر نہیں ان کے کام سے [۱۸۱]', 'For all there will be degrees (or ranks) according to what they did. And your Lord is not unaware of what they do.', 'For all people, there are ranks according to what they did, and your Lord is not unaware of what they do.'),
(922, 6, 133, 16, 3, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ رَبُّکَ الۡغَنِیُّ ذُو الرَّحۡمَۃِ ؕ اِنۡ یَّشَاۡ یُذۡہِبۡکُمۡ وَ یَسۡتَخۡلِفۡ مِنۡۢ بَعۡدِکُمۡ  مَّا یَشَآءُ  کَمَاۤ   اَنۡشَاَکُمۡ  مِّنۡ ذُرِّیَّۃِ  قَوۡمٍ اٰخَرِیۡنَ ﴿۱۳۳﴾ؕ', 'اور تمہارا پروردگار تو بے نیاز ہے صاحب رحمت ہے۔ اگر چاہے تو اے بندو تمہیں نابود کر دے اور تمہارے بعد جن لوگوں کو چاہے تمہارا جانشین بنا دے جیسا تم کو بھی دوسرے لوگوں کی نسل سے پیدا کیا ہے۔', 'اور تیرا رب بے پروا ہے رحمت والا اگر چاہے تو تم کو لے جاوے اور تمہارے پیچھے قائم کر دے جس کو چاہے جیسا تم کو پیدا کیا اوروں کی اولاد سے', 'And your Lord is Rich (Free of all wants), full of Mercy, if He will, He can destroy you, and in your place make whom He will as your successors, as He raised you from the seed of other people.', 'Your Lord is the All-Independent, the Lord of Mercy. If He so wills, He can take you away and cause whomsoever He wills to succeed you, just as He has raised you from the progeny of other people.'),
(923, 6, 134, 16, 3, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'اِنَّ مَا تُوۡعَدُوۡنَ لَاٰتٍ ۙ وَّ مَاۤ  اَنۡتُمۡ بِمُعۡجِزِیۡنَ ﴿۱۳۴﴾', 'کچھ شک نہیں کہ جو وعدہ تم سے کیا جاتا ہے وہ پورا ہونے والا ہے۔ اور تم اللہ کو عاجز نہیں کر سکتے۔', 'جس چیز کا تم سے وعدہ کیا جاتا ہے وہ ضرور آنے والا ہے اور تم عاجز نہیں کر سکتے [۱۸۲]', 'Surely, that which you are promised will verily come to pass, and you cannot escape (from the Punishment of Allah).', 'Surely what you are promised is bound to come, and you cannot frustrate (it).'),
(924, 6, 135, 16, 3, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'قُلۡ یٰقَوۡمِ اعۡمَلُوۡا عَلٰی مَکَانَتِکُمۡ  اِنِّیۡ عَامِلٌ ۚ فَسَوۡفَ تَعۡلَمُوۡنَ ۙ مَنۡ تَکُوۡنُ لَہٗ عَاقِبَۃُ الدَّارِ ؕ اِنَّہٗ  لَا یُفۡلِحُ الظّٰلِمُوۡنَ ﴿۱۳۵﴾', 'کہدو کہ لوگو تم اپنی جگہ عمل کئے جاؤ میں اپنی جگہ عمل کئے جاتا ہوں۔ عنقریب تم کو معلوم ہو جائے گا کہ آخرت میں بہشت کس کا گھر ہو گا۔ کچھ شک نہیں کہ مشرک کامیاب نہیں ہوں گے۔', 'تو کہہ دے اے لوگو تم کام کرتے رہو اپنی جگہ پر میں بھی کام کرتا ہوں سو عنقریب جان لو گے تم کہ کس کو ملتا ہے عاقبت کا گھر بالیقین بھلا نہ ہوگا ظالموں کا [۱۸۳]', 'Say (O Muhammad SAW): \"O my people! Work according to your way, surely, I too am working (in my way), and you will come to know for which of us will be the (happy) end in the Hereafter. Certainly the Zalimoon (polytheists and wrongdoers, etc.) will not be successful.\"', 'Say, “O my people, do at your place (whatever you do.) I have to do (in my way). So, you will know for whom is the ultimate abode. Surely, the wrongdoers will not be successful.”'),
(925, 6, 136, 16, 3, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ جَعَلُوۡا لِلّٰہِ مِمَّا ذَرَاَ مِنَ الۡحَرۡثِ وَ الۡاَنۡعَامِ نَصِیۡبًا فَقَالُوۡا ہٰذَا لِلّٰہِ بِزَعۡمِہِمۡ وَ ہٰذَا لِشُرَکَآئِنَا ۚ فَمَا کَانَ لِشُرَکَآئِہِمۡ  فَلَا یَصِلُ اِلَی اللّٰہِ ۚ وَ مَا کَانَ لِلّٰہِ  فَہُوَ  یَصِلُ  اِلٰی  شُرَکَآئِہِمۡ ؕ سَآءَ مَا  یَحۡکُمُوۡنَ ﴿۱۳۶﴾', 'اور یہ لوگ اللہ ہی کی پیدا کی ہوئی چیزوں یعنی کھیتی اور مویشیوں میں اللہ کا بھی ایک حصہ مقرر کرتے ہیں اور اپنے خیال باطل سے کہتے ہیں کہ یہ حصہ تو اللہ کا اور یہ ہمارے شریکوں یعنی بتوں کا۔ تو جو حصہ انکے شریکوں کا ہوتا ہے وہ تو اللہ کی طرف نہیں جا سکتا۔ اور جو حصہ اللہ کا ہوتا ہے وہ انکے شریکوں کی طرف جا سکتا ہے۔ کیا برا حکم لگاتے ہیں۔', 'اور ٹھہراتے ہیں اللہ کا اس کی پیدا کی ہوئی کھیتی او رمواشی میں ایک حصہ پھر کہتے ہیں یہ حصہ اللہ کا ہے اپنے خیال میں اور یہ ہمارے شریکوں کا ہے سو جو حصہ ان کے شریکوں کا ہے وہ تو نہیں پہنچتا اللہ کی طرف اور جو اللہ کا ہے وہ پہنچ جاتا ہے ان کے شریکوں کی طرف کیا ہی برا انصاف کرتے ہیں [۱۸۴]', 'And they assign to Allah a share of the tilth and cattle which He has created, and they say: \"This is for Allah according to their pretending, and this is for our (Allahs socalled) partners.\" But the share of their (Allahs socalled) \"partners\" reaches not Allah, while the share of Allah reaches their (Allahs socalled) \"partners\"! Evil is the way they judge!', 'They have assigned a portion for Allah from the tillage and the cattle created by Him, and then said, “This is for Allah”, so they claim, “And this is for our associate-gods.” Then, that which is allocated for their associate-gods never reaches Allah, while that which is allocated for Allah does reach their associate-gods. Evil is what they judge.'),
(926, 6, 137, 16, 3, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ  کَذٰلِکَ  زَیَّنَ  لِکَثِیۡرٍ مِّنَ الۡمُشۡرِکِیۡنَ قَتۡلَ اَوۡلَادِہِمۡ شُرَکَآؤُہُمۡ لِیُرۡدُوۡہُمۡ وَ  لِیَلۡبِسُوۡا عَلَیۡہِمۡ  دِیۡنَہُمۡ ؕ وَ لَوۡ شَآءَ اللّٰہُ مَا فَعَلُوۡہُ فَذَرۡہُمۡ وَ مَا یَفۡتَرُوۡنَ ﴿۱۳۷﴾', 'اسی طرح بہت سے مشرکوں کو ان کے شریکوں یعنی شیطانوں نے ان کے بچوں کو جان سے مار ڈالنا اچھا کر دکھایا ہے تاکہ انہیں ہلاکت میں ڈال دیں اور ان کے دین کو ان پر خلط ملط کر دیں۔ اور اگر اللہ چاہتا تو وہ ایسا نہ کرتے سو ان کو چھوڑ دو کہ وہ جانیں اور ان کا جھوٹ۔', 'اور اسی طرح مزین کر دیا بہت سے مشرکوں کی نگاہ میں ان کی اولاد کے قتل کو انکے شریکوں نے تاکہ ان کو ہلاک کریں اور رلا ملا دیں ان پر انکے دین کو [۱۸۵] اور اللہ چاہتا تو وہ یہ کام نہ کرتے سو چھوڑ دے وہ جانیں اور انکا جھوٹ [۱۸۶]', 'And so to many of the Mushrikoon (polytheists - see V.2:105) their (Allahs socalled) \"partners\" have made fair-seeming the killing of their children, in order to lead them to their own destruction and cause confusion in their religion. And if Allah had willed they would not have done so. So leave them alone with their fabrications.', 'Similarly, their associate-gods have made the killing of their children seem fair to many mushriks (idolators), so that they may ruin them and may confuse their faith for them. Had Allah so willed, they would not have done that. So, leave them alone with what they fabricate.'),
(927, 6, 138, 16, 3, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ قَالُوۡا ہٰذِہٖۤ  اَنۡعَامٌ  وَّ  حَرۡثٌ حِجۡرٌ ٭ۖ لَّا یَطۡعَمُہَاۤ اِلَّا مَنۡ نَّشَآءُ بِزَعۡمِہِمۡ وَ اَنۡعَامٌ حُرِّمَتۡ ظُہُوۡرُہَا وَ اَنۡعَامٌ لَّا یَذۡکُرُوۡنَ اسۡمَ اللّٰہِ عَلَیۡہَا افۡتِرَآءً عَلَیۡہِ ؕ سَیَجۡزِیۡہِمۡ بِمَا کَانُوۡا یَفۡتَرُوۡنَ ﴿۱۳۸﴾', 'اور اپنے خیال سے یہ بھی کہتے ہیں کہ یہ مویشی اور کھیتی منع ہے۔ اسے اس شخص کے سوا جسے ہم چاہیں کوئی نہ کھائے اور بعض مویشی ایسے ہیں کہ انکی پیٹھ پر چڑھنا منع کر دیا گیا ہے۔ اور بعض مویشی ایسے ہیں جن پر ذبح کرتے وقت اللہ کا نام نہیں لیتے۔ یہ سب اللہ پر جھوٹ ہے۔ وہ عنقریب ان کو ان کے جھوٹ کا بدلہ دے گا۔', 'اور کہتے ہیں کہ یہ مواشی اور کھیتی ممنوع ہے اس کو کوئی نہ کھاوے مگر جس کو ہم چاہیں انکے خیال کے موافق اور بعضے مواشی کی پیٹھ پر چڑھنا حرام کیا اور بعض مواشی کے ذبح کے وقت نام نہیں لیتے اللہ کا اللہ پر بہتان باندھ کر عنقریب وہ سزا دے گا انکو اس جھوٹ کی [۱۸۷]', 'And according to their pretending, they say that such and such cattle and crops are forbidden, and none should eat of them except those whom we allow. And (they say) there are cattle forbidden to be used for burden or any other work, and cattle on which (at slaughtering) the Name of Allah is not pronounced; lying against Him (Allah). He will recompense them for what they used to fabricate.', 'They say, “These are prohibited cattle and produce; none can eat them except those whom we wish” - so they claimed - “and there are cattle whose backs are prohibited (for riding or loading)”, and there are cattle over which they do not pronounce the name of Allah,-all being fabrications against Him. He will soon punish them for what they have been fabricating.'),
(928, 6, 139, 16, 3, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ قَالُوۡا مَا فِیۡ بُطُوۡنِ ہٰذِہِ الۡاَنۡعَامِ خَالِصَۃٌ  لِّذُکُوۡرِنَا وَ مُحَرَّمٌ عَلٰۤی اَزۡوَاجِنَا ۚ وَ  اِنۡ یَّکُنۡ  مَّیۡتَۃً فَہُمۡ فِیۡہِ  شُرَکَآءُ ؕ سَیَجۡزِیۡہِمۡ  وَصۡفَہُمۡ ؕ اِنَّہٗ حَکِیۡمٌ  عَلِیۡمٌ ﴿۱۳۹﴾', 'اور یہ بھی کہتے ہیں کہ جو بچہ ان مویشیوں کے پیٹ میں ہے وہ صرف ہمارے مردوں کے لئے ہے۔ اور ہماری عورتوں کو اس کا کھانا حرام ہے۔ اور اگر وہ بچہ مرا ہوا ہو تو سب اس میں شریک ہیں یعنی اسے مرد اور عورتیں سب کھائیں عنقریب اللہ انہیں انکی اس تجویز پر سزا دے گا۔ بیشک وہ حکمت والا ہے خبردار ہے۔', 'اور کہتے ہیں جو بچہ ان مویشی کے پیٹ میں ہے اس کو تو خاص ہمارے مرد ہی کھاویں اور وہ حرام ہے ہماری عورتوں پر اور جو بچہ مردہ ہو تو اس کے کھانے میں سب برابر ہیں وہ سزا دے گا ان کو ان تقریروں کی وہ حکمت والا جاننے والا ہے [۱۸۸]', 'And they say: \"What is in the bellies of such and such cattle (milk or foetus) is for our males alone, and forbidden to our females (girls and women), but if it is born dead, then all have shares therein.\" He will punish them for their attribution (of such false orders to Allah). Verily, He is AllWise, AllKnower. (Tafsir AtTabaree, Vol. 8, Page 49).', 'They say, “Whatever is in the wombs of these cattle is purely for our males, and forbidden to our wives.” If it be born dead, then all of them share in it. Soon, He will punish them for what they attribute. Surely, He is All-Wise, All-Knowing.'),
(929, 6, 140, 16, 3, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'قَدۡ خَسِرَ الَّذِیۡنَ قَتَلُوۡۤا  اَوۡلَادَہُمۡ سَفَہًۢا بِغَیۡرِ عِلۡمٍ وَّ حَرَّمُوۡا مَا رَزَقَہُمُ اللّٰہُ افۡتِرَآءً  عَلَی اللّٰہِ ؕ قَدۡ ضَلُّوۡا وَ  مَا کَانُوۡا  مُہۡتَدِیۡنَ ﴿۱۴۰﴾٪', 'جن لوگوں نے اپنی اولاد کو بیوقوفی سے ناسمجھی سے قتل کیا اور اللہ پر افترا کر کے اسکی عطا فرمائی ہوئی روزی کو حرام ٹھہرایا وہ گھاٹے میں پڑ گئے۔ وہ بلا شبہ گمراہ ہیں اور ہدایت یافتہ نہیں ہیں۔', 'بیشک خراب ہوئے جنہوں نے قتل کیا اپنی اولاد کو نادانی سے بغیر سمجھے اور حرام ٹھہرا لیا اس رزق کو جو اللہ نے انکو دیا بہتان باندھ کر اللہ پر بیشک وہ گمراہ ہوئے اور نہ آئے سیدھی راہ پر [۱۸۹]', 'Indeed lost are they who have killed their children, from folly, without knowledge, and have forbidden that which Allah has provided for them, inventing a lie against Allah. They have indeed gone astray and were not guided.', 'Losers are those who kill their children foolishly, without knowledge, and hold as prohibited what Allah has provided them, falsely ascribing it to Allah. They have gone astray, and they are not on the right path.'),
(930, 6, 141, 17, 4, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ ہُوَ الَّذِیۡۤ اَنۡشَاَ جَنّٰتٍ مَّعۡرُوۡشٰتٍ وَّ غَیۡرَ مَعۡرُوۡشٰتٍ وَّ النَّخۡلَ وَ الزَّرۡعَ مُخۡتَلِفًا اُکُلُہٗ  وَ الزَّیۡتُوۡنَ وَ الرُّمَّانَ مُتَشَابِہًا وَّ غَیۡرَ  مُتَشَابِہٍ ؕ کُلُوۡا  مِنۡ ثَمَرِہٖۤ  اِذَاۤ  اَثۡمَرَ وَ اٰتُوۡا حَقَّہٗ یَوۡمَ حَصَادِہٖ ۫ۖ وَ لَا تُسۡرِفُوۡا ؕ اِنَّہٗ لَا یُحِبُّ الۡمُسۡرِفِیۡنَ ﴿۱۴۱﴾ۙ', 'اور اللہ ہی تو ہے جس نے باغ پیدا کئے چھتریوں پر چڑھائے ہوئے بھی اور جو چھتریوں پر نہیں چڑھائے ہوئے وہ بھی۔ اور کھجور اور کھیتی جنکے طرح طرح کے پھل ہوتے ہیں اور زیتون اور انار جو بعض باتوں میں ایکدوسرے سے ملتے جلتے ہیں اور بعض باتوں میں نہیں بھی ملتے جب یہ چیزیں پھلیں تو انکے پھل کھاؤ اور جسدن پھل توڑو اور کھیتی کاٹو تو اس کا حق بھی اس میں سے ادا کرو اور بیجا نہ اڑانا کہ اللہ بیجا اڑانے والوں کو دوست نہیں رکھتا۔', 'اور اسی نے پیدا کئے باغ جو ٹٹیوں پر چڑھائے جاتے ہیں اور جو ٹٹیوں پر نہیں چڑھائے جاتے [۱۹۰] اور کھجور کے درخت اور کھیتی کہ مختلف ہیں انکے پھل اور پیدا کیا زیتون کو اور انار کو ایک دوسرے کے مشابہ اور جدا جدا بھی [۱۹۱] کھاؤ انکے پھل میں سے جس وقت پھل لاویں اور ادا کرو ان کا حق جس دن ان کو کاٹو اور بیجا خرچ نہ کرو اس کو خوش نہیں آتے بیجا خرچ کرنے والے [۱۹۲]', 'And it is He Who produces gardens trellised and untrellised, and datepalms, and crops of different shape and taste (its fruits and its seeds) and olives, and pomegranates, similar (in kind) and different (in taste). Eat of their fruit when they ripen, but pay the due thereof (its Zakat, according to Allahs Orders 1/10th or 1/20th) on the day of its harvest, and waste not by extravagance. Verily, He likes not Al-Musrifoon (those who waste by extravagance),', 'He is the One who has created gardens, trellised and untrellised, and date-palms and crops with a variety of edibles, and the olive and the pomegranate, (some) similar to one another, and (some) dissimilar. Eat of its fruit when it bears fruits, and pay its due on the day of harvest, and do not be extravagant. Surely, Allah does not like the extravagant'),
(931, 6, 142, 17, 4, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ مِنَ الۡاَنۡعَامِ حَمُوۡلَۃً  وَّ فَرۡشًا ؕ کُلُوۡا مِمَّا رَزَقَکُمُ اللّٰہُ وَ لَا تَتَّبِعُوۡا خُطُوٰتِ الشَّیۡطٰنِ ؕ اِنَّہٗ لَکُمۡ عَدُوٌّ مُّبِیۡنٌ ﴿۱۴۲﴾ۙ', 'اور مویشیوں میں بوجھ اٹھانے والے یعنی بڑے بڑے بھی پیدا کئے اور زمین سے لگے ہوئے یعنی چھوٹے چھوٹے بھی پس اللہ کا دیا ہوا رزق کھاؤ اور شیطان کے قدموں پر نہ چلو۔ وہ تمہارا کھلا دشمن ہے۔', 'اور پیدا کئے مواشی میں بوجھ اٹھانے والے اور زمین سے لگے ہوئے [۱۹۳] کھاؤ اللہ کے رزق میں سے اور مت چلو شیطان کے قدموں پر وہ تمہارا دشمن ہے صریح [۱۹۴]', 'And of the cattle (are some) for burden (like camels etc.) and (some are) small (unable to carry burden like sheep, goats etc. for food, meat, milk, wool etc.). Eat of what Allah has provided for you, and follow not the footsteps of Shaitan (Satan). Surely he is to you an open enemy.', 'Among cattle (He has created) those fit for loading and those fit for laying on the floor. Eat of what Allah has provided you, and do not follow the footsteps of Satan. Surely, he is an open enemy to you.'),
(932, 6, 143, 17, 4, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'ثَمٰنِیَۃَ اَزۡوَاجٍ ۚ مِنَ الضَّاۡنِ اثۡنَیۡنِ وَ مِنَ الۡمَعۡزِ اثۡنَیۡنِ ؕ   قُلۡ ءٰٓالذَّکَرَیۡنِ حَرَّمَ  اَمِ الۡاُنۡثَیَیۡنِ اَمَّا اشۡتَمَلَتۡ عَلَیۡہِ  اَرۡحَامُ الۡاُنۡثَیَیۡنِ ؕ نَبِّـُٔوۡنِیۡ بِعِلۡمٍ   اِنۡ  کُنۡتُمۡ  صٰدِقِیۡنَ ﴿۱۴۳﴾ۙ', 'یہ بڑے چھوٹے مویشی آٹھ قسم کے ہیں دو دو بھیڑوں میں سے اور دو دو بکریوں میں سے یعنی ایک ایک نر اور ایک ایک مادہ اے پیغمبر ان سے پوچھو کہ اللہ نے دونوں کے نروں کو حرام کیا ہے یا دونوں کی ماداؤں کو یا جو بچہ ماداؤں کے پیٹ میں ہے اسے اگر سچے ہو تو مجھے سند سے بتاؤ۔', 'پیدا کئے آٹھ نر اور مادہ بھیڑ میں سے دو [۱۹۵] اور بکری میں سے دو پوچھ تو کہ دونوں نر اللہ نے حرام کئے ہیں یا دونوں مادہ یا وہ بچہ کہ اس پر مشتمل ہیں بچہ دان دونوں مادہ کے بتلاؤ مجھ کو سند اگر تم سچے ہو [۱۹۶]', 'Eight pairs; of the sheep two (male and female), and of the goats two (male and female). Say: \"Has He forbidden the two males or the two females, or (the young) which the wombs of the two females enclose? Inform me with knowledge if you are truthful.\"', '(Allah has created) eight pairs: two of sheep and two of goats. Say, “Is it the two males that He has prohibited or the two females, or whatever the wombs of the two females contain? Tell me on the basis of knowledge if you are true.”'),
(933, 6, 144, 17, 4, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ مِنَ الۡاِبِلِ اثۡنَیۡنِ وَ مِنَ الۡبَقَرِ اثۡنَیۡنِ ؕ قُلۡ ءٰٓالذَّکَرَیۡنِ حَرَّمَ  اَمِ الۡاُنۡثَیَیۡنِ اَمَّا اشۡتَمَلَتۡ عَلَیۡہِ اَرۡحَامُ  الۡاُنۡثَیَیۡنِ ؕ اَمۡ  کُنۡتُمۡ  شُہَدَآءَ اِذۡ  وَصّٰکُمُ اللّٰہُ بِہٰذَا ۚ فَمَنۡ اَظۡلَمُ مِمَّنِ افۡتَرٰی عَلَی اللّٰہِ کَذِبًا لِّیُضِلَّ النَّاسَ بِغَیۡرِ  عِلۡمٍ ؕ اِنَّ اللّٰہَ لَا یَہۡدِی الۡقَوۡمَ  الظّٰلِمِیۡنَ ﴿۱۴۴﴾٪', 'اور دو دو اونٹوں میں سے اور دو دو گایوں میں سے انکے بارے میں بھی ان سے پوچھو کہ اللہ نے دونوں کے نروں کر حرام کیا ہے یا دونوں کی ماداؤں کو یا جو بچہ ماداؤں کے پیٹ میں ہے اس کو۔ بھلا جس وقت اللہ نے تم کو اس کا حکم دیا تھا تم اس وقت موجود تھے؟ اب اس شخص سے زیادہ کون ظالم ہے جو اللہ پر جھوٹ باندھے تاکہ بے جانے بوجھے لوگوں کو گمراہ کرے۔ کچھ شک نہیں کہ اللہ ظالم لوگوں کو ہدایت نہیں دیتا۔', 'اور پیدا کئے اونٹ میں سے دو اور گائے میں سے دو پوچھ تو دونوں نر حرام کئے ہیں یا دونوں مادہ یا وہ بچہ کہ اس پر مشتمل ہیں بچہ دان دونوں مادہ کے کیا تم حاضر تھے جس وقت تم کو اللہ نے یہ حکم دیا تھا پھر اس سے زیادہ ظالم کون جو بہتان باندھے اللہ پر جھوٹا تاکہ لوگوں کو گمراہ کرے بلاتحقیق بیشک اللہ ہدایت نہیں کرتا ظالم لوگوں کو [۱۹۷]', 'And of the camels two (male and female), and of oxen two (male and female). Say: \"Has He forbidden the two males or the two females or (the young) which the wombs of the two females enclose? Or were you present when Allah ordered you such a thing? Then who does more wrong than one who invents a lie against Allah, to lead mankind astray without knowledge. Certainly Allah guides not the people who are Zalimoon (polytheists and wrongdoers, etc.).\"', 'And (He has created) two of camels and two of oxen. Say, “Is it the two males that He has prohibited or the two females or whatever the wombs of the two females contain? Or were you present when Allah has advised you of this?” So, who is more unjust than the one who fabricates a lie against Allah in order to misguide people without knowledge? Surely, Allah gives no guidance to an unjust people.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(934, 6, 145, 18, 5, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'قُلۡ لَّاۤ  اَجِدُ فِیۡ مَاۤ   اُوۡحِیَ  اِلَیَّ  مُحَرَّمًا عَلٰی طَاعِمٍ یَّطۡعَمُہٗۤ اِلَّاۤ  اَنۡ یَّکُوۡنَ مَیۡتَۃً اَوۡ دَمًا مَّسۡفُوۡحًا اَوۡ لَحۡمَ  خِنۡزِیۡرٍ فَاِنَّہٗ رِجۡسٌ اَوۡ فِسۡقًا اُہِلَّ لِغَیۡرِ اللّٰہِ  بِہٖ ۚ فَمَنِ اضۡطُرَّ غَیۡرَ بَاغٍ  وَّ لَا عَادٍ  فَاِنَّ رَبَّکَ غَفُوۡرٌ  رَّحِیۡمٌ ﴿۱۴۵﴾', 'کہو کہ جو احکام مجھ پر نازل ہوئے ہیں میں ان میں کوئی چیز جسے کھانے والا کھائے حرام نہیں پاتا۔ بجز اسکے کہ وہ مرا ہوا جانور ہو یا بہتا لہو یا سور کا گوشت کہ یہ سب ناپاک ہیں یا کوئی گناہ کی چیز ہو کہ اس پر اللہ کے سوا کسی اور کا نام لیا گیا ہو۔ اور اگر کوئی مجبور ہو جائے لیکن نہ تو نافرمانی کرے اور نہ حد سے باہر نکل جائے تو تمہارا پروردگار بخشنے والا ہے مہربان ہے۔', 'تو کہہ دے کہ میں نہیں پاتا اس وحی میں کہ مجھ کو پہنچی ہے کسی چیز کو حرام کھانے والے پر جو اس کو کھاوے مگر یہ کہ وہ چیز مردار ہو یا بہتا ہوا خون یا گوشت سور کا کہ وہ ناپاک ہے یا ناجائز ذبیحہ جس پر نام پکارا جاوے اللہ کے سوا کسی اور کا پھر جو کوئی بھوک سے بے اختیار ہو جاوے نہ نافرمانی کرے اور نہ زیادتی تو تیرا رب بڑا معاف کرنے والا ہے نہایت مہربان [۱۹۸]', 'Say (O Muhammad SAW): \"I find not in that which has been inspired to me anything forbidden to be eaten by one who wishes to eat it, unless it be Maytatah (a dead animal) or blood poured forth (by slaughtering or the like), or the flesh of swine (pork, etc.) for that surely is impure, or impious (unlawful) meat (of an animal) which is slaughtered as a sacrifice for others than Allah (or has been slaughtered for idols, etc., or on which Allahs Name has not been mentioned while slaughtering). But whosoever is forced by necessity without wilful disobedience, nor transgressing due limits, (for him) certainly, your Lord is OftForgiving, Most Merciful.\"', 'Say, “I do not find, in what has been revealed to me, anything (out of the cattle under discussion) prohibited for anyone who eats it, unless it be carrion or blood that pours forth, or flesh of swine - because it is impure - or there be an animal slaughtered sinfully by invoking on it the name of someone other than Allah. However, if anyone is compelled by necessity, neither seeking pleasure nor crossing the limit, then your Lord is Most-Forgiving, Very-Merciful.”'),
(935, 6, 146, 18, 5, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ عَلَی الَّذِیۡنَ ہَادُوۡا حَرَّمۡنَا کُلَّ ذِیۡ ظُفُرٍ ۚ وَ مِنَ الۡبَقَرِ وَ الۡغَنَمِ حَرَّمۡنَا عَلَیۡہِمۡ شُحُوۡمَہُمَاۤ اِلَّا مَا حَمَلَتۡ ظُہُوۡرُہُمَاۤ  اَوِ الۡحَوَایَاۤ  اَوۡ مَا اخۡتَلَطَ بِعَظۡمٍ ؕ ذٰلِکَ جَزَیۡنٰہُمۡ  بِبَغۡیِہِمۡ ۫ۖ وَ  اِنَّا لَصٰدِقُوۡنَ ﴿۱۴۶﴾', 'اور یہودیوں پر ہم نے سب ناخن والے جانور حرام کر دیئے تھے۔ اور گایوں اور بھیڑ بکریوں سے انکی چربی ان پر حرام کر دی تھی۔ سوائے اسکے جو انکی پیٹھ پر لگی ہو یا آنتوں میں لگی ہو یا ہڈی سے ملی ہو۔ یہ سزا ہم نے انکو انکی شرارت کے سبب دی تھی اور ہم یقینًا سچ کہنے والے ہیں۔', 'اور یہود پر ہم نے حرام کیا تھا ہر ایک ناخن والا جانور اور گائے اور بکری میں سے حرام کی تھی ان کی چربی مگر جو لگی ہو پشت پر یا انتڑیوں پر یا جو چربی کہ ملی ہو ہڈی کے ساتھ یہ ہم نے انکو سزا دی تھی انکی شرارت پر اور ہم سچ کہتے ہیں [۱۹۹]', 'And unto those who are Jews, We forbade every (animal) with undivided hoof, and We forbade them the fat of the ox and the sheep except what adheres to their backs or their entrails, or is mixed up with a bone. Thus We recompensed them for their rebellion (committing crimes like murdering the Prophets, eating of Riba (usury), etc.). And verily, We are Truthful.', 'For those who are Jews We prohibited all that has claws. Of cows and goats, We prohibited for them their fats, except that which is borne by their backs or the entrails, or what is attached to a bone. Thus We recompensed them for their transgression. We are definitely truthful.'),
(936, 6, 147, 18, 5, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'فَاِنۡ کَذَّبُوۡکَ فَقُلۡ رَّبُّکُمۡ ذُوۡ رَحۡمَۃٍ وَّاسِعَۃٍ ۚ وَ لَا یُرَدُّ بَاۡسُہٗ عَنِ الۡقَوۡمِ الۡمُجۡرِمِیۡنَ ﴿۱۴۷﴾', 'اب اگر یہ لوگ تمہاری تکذیب کریں تو اے پیغمبر کہدو تمہارا پروردگار بڑی رحمت والا ہے۔ اور اسکا عذاب بھی گنہگار لوگوں سے نہیں ٹلے گا۔', 'پھر اگر تجھ کو جھٹلاویں تو کہہ دے کہ تمہارے رب کی رحمت میں بڑی وسعت ہے اور نہیں ٹلے گا اس کا عذاب گنہگار لوگوں سے [۲۰۰]', 'If they (Jews) belie you (Muhammad SAW) say you: \"Your Lord is the Owner of Vast Mercy, and never will His Wrath be turned back from the people who are Mujrimoon (criminals, polytheists, sinners, etc.).\"', 'Then, if they give the lie to you, say, “Your Lord is the Lord of all-embracing mercy, and His punishment cannot be averted from the sinning people.”'),
(937, 6, 148, 18, 5, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'سَیَقُوۡلُ الَّذِیۡنَ اَشۡرَکُوۡا لَوۡ شَآءَ  اللّٰہُ مَاۤ اَشۡرَکۡنَا وَ لَاۤ  اٰبَآؤُنَا وَ لَا حَرَّمۡنَا مِنۡ شَیۡءٍ ؕ  کَذٰلِکَ  کَذَّبَ الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ حَتّٰی ذَاقُوۡا بَاۡسَنَا ؕ قُلۡ ہَلۡ عِنۡدَکُمۡ مِّنۡ عِلۡمٍ فَتُخۡرِجُوۡہُ  لَنَا ؕ اِنۡ  تَتَّبِعُوۡنَ اِلَّا الظَّنَّ وَ  اِنۡ  اَنۡتُمۡ   اِلَّا  تَخۡرُصُوۡنَ ﴿۱۴۸﴾', 'جو لوگ شرک کرتے ہیں وہ کہیں گے کہ اگر اللہ چاہتا تو ہم شرک نہ کرتے اور نہ ہمارے باپ دادا شرک کرتے اور نہ ہم کسی چیز کو حرام ٹھیراتے۔ اسی طرح ان لوگوں نے تکذیب کی تھی جو ان سے پہلے تھے یہاں تک کہ ہمارے عذاب کا مزہ چکھ کر رہے کہدو کیا تمہارے پاس کوئی سند ہے اگر ہے تو اسے ہمارے سامنے لاؤ۔ تم لوگ تو بس گمان کے پیچھے چلتے اور اٹکل کے تیر چلاتے ہو۔', 'اب کہیں گے مشرک اگر اللہ چاہتا تو شرک نہ کرتے ہم اور نہ ہمارےباپ دادے اور نہ ہم حرام کر لیتے کوئی چیز اسی طرح جھٹلایا کئے ان سےاگلے یہاں تک کہ انہوں نے چکھا ہمارا عذاب تو کہہ کچھ علم بھی ہے تمہارے پاس کہ اس کو ہمارے آگے ظاہر کرو تم تو نری اٹکل پر چلتے ہو اور صرف تخمینے ہی کرتے ہو', 'Those who took partners (in worship) with Allah will say: \"If Allah had willed, we would not have taken partners (in worship) with Him, nor would our fathers, and we would not have forbidden anything (against His Will).\" Likewise belied those who were before them, (they argued falsely with Allahs Messengers), till they tasted of Our Wrath. Say: \"Have you any knowledge (proof) that you can produce before us? Verily, you follow nothing but guess and you do nothing but lie.\"', 'Those who associate partners with Allah will say, “Had Allah willed, we would have not associated (partners with Him), nor our fathers, nor would we have made anything prohibited.” In the same way those who went before them gave the lie to (the truth) until they tasted Our punishment. Say, “Do you have any sure knowledge that you may produce to us? You follow nothing but whims, and do nothing but make conjectures.'),
(938, 6, 149, 18, 5, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'قُلۡ فَلِلّٰہِ الۡحُجَّۃُ الۡبَالِغَۃُ ۚ فَلَوۡ شَآءَ لَہَدٰىکُمۡ  اَجۡمَعِیۡنَ ﴿۱۴۹﴾', 'کہدو کہ اللہ ہی کی حجت غالب ہے پھر وہ چاہتا تو تم سب کو ہدایت دے دیتا۔', 'تو کہہ دے بس اللہ کا الزام پورا ہے سو اگر وہ چاہتا تو ہدایت کر دیتا تم سب کو [۲۰۱]', 'Say: \"With Allah is the perfect proof and argument, (i.e. the Oneness of Allah, the sending of His Messengers and His Holy Books, etc. to mankind), had He so willed, He would indeed have guided you all.\"', 'Say, “Then, Allah’s is the conclusive proof. So, had He willed, He would have brought all of you on the right path”.'),
(939, 6, 150, 18, 5, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'قُلۡ ہَلُمَّ  شُہَدَآءَکُمُ  الَّذِیۡنَ یَشۡہَدُوۡنَ اَنَّ اللّٰہَ  حَرَّمَ  ہٰذَا ۚ فَاِنۡ شَہِدُوۡا فَلَا تَشۡہَدۡ مَعَہُمۡ ۚ وَ لَا تَتَّبِعۡ  اَہۡوَآءَ  الَّذِیۡنَ کَذَّبُوۡا بِاٰیٰتِنَا وَ الَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِالۡاٰخِرَۃِ وَ ہُمۡ بِرَبِّہِمۡ یَعۡدِلُوۡنَ ﴿۱۵۰﴾٪', 'کہو کہ اپنے گواہوں کو لاؤ جو بتائیں کہ اللہ نے یہ چیزیں حرام کی ہیں۔ پھر اگر وہ آ کر گواہی دیں تو تم ان کے ساتھ گواہی نہ دینا اور نہ ان کی خواہشوں کی پیروی کرنا جو ہماری آیتوں کو جھٹلاتے ہیں اور جو آخرت پر ایمان نہیں لاتے اور بتوں کو اپنے پروردگار کے برابر ٹھہراتے ہیں۔', 'تو کہہ کہ لاؤ اپنے گواہ جو گواہی دیں اس بات کی اللہ نے حرام کیا ہے ان چیزوں کو پھر اگر وہ ایسی گواہی دیں بھی تو تو نہ اعتبار کر ان کا اور نہ چل ان کی خوشی پر جنہوں نے جھٹلایا ہمارے حکموں کو اور جو یقین نہینں کرتے آخرت کا اور وہ اپنے رب کے  برابر کرتے ہیں اوروں کو [۲۰۲]', 'Say: \"Bring forward your witnesses, who can testify that Allah has forbidden this. Then if they testify, testify not you (O Muhammad SAW) with them. And you should not follow the vain desires of such as treat Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) as falsehoods, and such as believe not in the Hereafter, and they hold others as equal (in worship) with their Lord.\"', 'Say, “Bring your witnesses who testify that Allah has prohibited this.” Then, if they testify, (O prophet), do not be a witness to them, and do not follow the desires of those who have given the lie to Our signs and those who do not believe in the Hereafter, and who equate others with their Lord.'),
(940, 6, 151, 19, 6, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'قُلۡ تَعَالَوۡا اَتۡلُ مَا حَرَّمَ  رَبُّکُمۡ عَلَیۡکُمۡ  اَلَّا تُشۡرِکُوۡا بِہٖ شَیۡئًا وَّ بِالۡوَالِدَیۡنِ اِحۡسَانًا ۚ وَ لَا تَقۡتُلُوۡۤا اَوۡلَادَکُمۡ   مِّنۡ  اِمۡلَاقٍ ؕ نَحۡنُ  نَرۡزُقُکُمۡ وَ اِیَّاہُمۡ ۚ وَ لَا تَقۡرَبُوا الۡفَوَاحِشَ مَا ظَہَرَ  مِنۡہَا وَ مَا بَطَنَ ۚ وَ لَا تَقۡتُلُوا النَّفۡسَ الَّتِیۡ حَرَّمَ اللّٰہُ  اِلَّا بِالۡحَقِّ ؕ ذٰلِکُمۡ وَصّٰکُمۡ بِہٖ لَعَلَّکُمۡ تَعۡقِلُوۡنَ ﴿۱۵۱﴾', 'کہو کہ لوگو آؤ میں تمہیں وہ چیزیں پڑھ کو سناؤں جو تمہارے پروردگار نے تم پر حرام کر دی ہیں انکی نسبت اس نے اس طرح ارشاد فرمایا ہے کہ کسی چیز کو اللہ کا شریک نہ بنانا۔ اور ماں باپ سے بدسلوکی نہ کرنا بلکہ حسن سلوک کرتے رہنا اور ناداری کے اندیشے سے اپنی اولاد کو قتل نہ کرنا کیونکہ تم کو اور انکو ہم ہی رزق دیتے ہیں۔ اور بے حیائی کے کام ظاہر ہوں یا پوشیدہ انکے پاس نہ پھٹکنا۔ اور کسی شخص کو جسکے قتل کو اللہ نے حرام کر دیا ہے قتل نہ کرنا۔ مگر جائز طور پر یعنی جس کا شریعت حکم دے ان باتوں کی وہ تمہیں تاکید کرتا ہے تاکہ تم سمجھو۔', 'تو کہہ تم آؤ میں سنا دوں جو حرام کیا ہے تم پر تمہارے رب نے کہ شریک نہ کرو اسکے ساتھ کسی چیز کو اور ماں باپ کے ساتھ نیکی کرو اور مار نہ ڈالو اپنی اولاد کو مفلسی سے ہم رزق دیتے ہیں تم کو اور ان کو [۲۰۳] اور پاس نہ جاؤ بیحیائی کے کام کے جو ظاہر ہو اس میں سے اور جو پوشیدہ ہو [۲۰۴] اور مار نہ ڈالو اس جان کو جس کو حرام کیا ہے اللہ نے مگر حق پر [۲۰۵] تم کو یہ حکم کیا ہے تاکہ تم سمجھو [۲۰۶]', 'Say (O Muhammad SAW): \"Come, I will recite what your Lord has prohibited you from: Join not anything in worship with Him; be good and dutiful to your parents; kill not your children because of poverty - We provide sustenance for you and for them; come not near to Al-Fawahish (shameful sins, illegal sexual intercourse, etc.) whether committed openly or secretly, and kill not anyone whom Allah has forbidden, except for a just cause (according to Islamic law). This He has commanded you that you may understand.', 'Say (O Prophet to the infidels), “Come, and I shall recite what your Lord has prohibited for you: Do not associate anything with Him (as His partner); and be good to parents, and do not kill your children because of poverty - We will give provision to you, and to them as well - and do not go near shameful acts, whether they are open or secret; and do not kill a person whom Allah has given sanctity, except rightfully. This He has enjoined upon you, so that you may understand.'),
(941, 6, 152, 19, 6, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ لَا تَقۡرَبُوۡا مَالَ الۡیَتِیۡمِ  اِلَّا بِالَّتِیۡ  ہِیَ اَحۡسَنُ حَتّٰی یَبۡلُغَ اَشُدَّہٗ ۚ وَ اَوۡفُوا الۡکَیۡلَ وَ الۡمِیۡزَانَ بِالۡقِسۡطِ ۚ لَا نُکَلِّفُ نَفۡسًا اِلَّا وُسۡعَہَا ۚ وَ اِذَا قُلۡتُمۡ فَاعۡدِلُوۡا وَ لَوۡ کَانَ ذَا قُرۡبٰی ۚ وَ بِعَہۡدِ اللّٰہِ اَوۡفُوۡا ؕ ذٰلِکُمۡ  وَصّٰکُمۡ بِہٖ لَعَلَّکُمۡ  تَذَکَّرُوۡنَ ﴿۱۵۲﴾ۙ', 'اور یتیم کے مال کے پاس بھی نہ جانا مگر ایسے طریق سے کہ بہت ہی پسندیدہ ہو۔ یہاں تک کہ وہ جوانی کو پہنچ جائے۔ اور ناپ اور تول انصاف کے ساتھ پوری پوری کیا کرو۔ ہم کسی کو ذمہ دار نہیں بناتے مگر اسکی طاقت کے مطابق۔ اور جب کسی کی نسبت کوئی بات کہو تو انصاف سے کہو گو کہ وہ تمہارا رشتہ دار ہی ہو اور اللہ کے عہد کو پورا کرو ان باتوں کا اللہ تمہیں حکم دیتا ہے تاکہ تم نصیحت قبول کرو۔', 'اور پاس نہ جاؤ یتیم کے مال کے مگر اس طرح سے کہ بہتر ہو یہاں تک کہ پہنچ جاوے اپنی جوانی کو [۲۰۷] اور پورا کرو ماپ اور تول کو انصاف سے ہم کسی کے ذمہ وہی چیز لازم کرتے ہیں جسکی اسکو طاقت ہو [۲۰۸] اور جب بات کہو تو حق کی کہو اگرچہ وہ اپنا قریب ہی ہو [۲۰۹] اور اللہ کا عہد پورا کرو [۲۱۰] تم کو یہ حکم کر دیا ہے تاکہ تم نصیحت پکڑو', '\"And come not near to the orphans property, except to improve it, until he (or she) attains the age of full strength; and give full measure and full weight with justice. We burden not any person, but that which he can bear. And whenever you give your word (i.e. judge between men or give evidence, etc.), say the truth even if a near relative is concerned, and fulfill the Covenant of Allah, This He commands you, that you may remember.', 'Do not approach the property of the orphan, except with the best possible conduct, until he reaches maturity. Give full measure and full weight in all fairness- We do not obligate anyone beyond his capacity - and be just when you speak, even though the one (against whom you are speaking) is a relative; and fulfill the covenant of Allah. This is what He has enjoined upon you, so that you may observe the advice.'),
(942, 6, 153, 19, 6, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ  اَنَّ  ہٰذَا صِرَاطِیۡ مُسۡتَقِیۡمًا فَاتَّبِعُوۡہُ ۚ وَ لَا تَتَّبِعُوا السُّبُلَ  فَتَفَرَّقَ  بِکُمۡ عَنۡ سَبِیۡلِہٖ ؕ ذٰلِکُمۡ  وَصّٰکُمۡ بِہٖ لَعَلَّکُمۡ تَتَّقُوۡنَ ﴿۱۵۳﴾', 'اور یہ کہ میرا سیدھا رستہ یہی ہے تو تم اسی پر چلنا اور دوسرے رستوں پر نہ چلنا کہ ان پر چل کر اللہ کے رستے سے الگ ہو جاؤ گے ان باتوں کا اللہ تمہیں حکم دیتا ہے تاکہ تم پرہیزگار بنو۔', 'اور حکم کیا کہ یہ راہ ہے میری سیدھی سو اس پر چلو اور مت چلو اور رستوں پر کہ وہ تم کو جدا کر دیں گے اللہ کے راستہ سے [۲۱۱] یہ حکم کر دیا ہے تم کو تاکہ تم بچتے رہو', '\"And verily, this (i.e. Allahs Commandments mentioned in the above two Verses 151 and 152) is my Straight Path, so follow it, and follow not (other) paths, for they will separate you away from His Path. This He has ordained for you that you may become Al-Muttaqoon (the pious - see V.2:2).\"', 'And: This is My path that is straightforward. So, follow it, and do not follow the (other) ways, lest they should make you deviate from His way. This is what He has enjoined upon you, so that you may be God-fearing.”'),
(943, 6, 154, 19, 6, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'ثُمَّ اٰتَیۡنَا مُوۡسَی الۡکِتٰبَ تَمَامًا عَلَی الَّذِیۡۤ اَحۡسَنَ وَ تَفۡصِیۡلًا لِّکُلِّ شَیۡءٍ وَّ ہُدًی وَّ رَحۡمَۃً  لَّعَلَّہُمۡ بِلِقَآءِ  رَبِّہِمۡ یُؤۡمِنُوۡنَ ﴿۱۵۴﴾٪', 'ہاں پھر سن لو کہ ہم نے موسٰی کو کتاب عنایت کی تھی تاکہ ہم ان لوگوں پر جو نیکوکار ہیں نعمت پوری کر دیں اور اس میں ہر چیز کا بیان ہے اور ہدایت ہے اور رحمت ہے تاکہ انکی امت کے لوگ اپنے پروردگار کے روبرو حاضر ہونے کا یقین کریں۔', 'پھر دی ہم نے موسٰی کو کتاب واسطے پورا کرنے نعمت کے نیک کام والوں پر اور واسطے تفصیل ہر شے کے اور ہدایت اور رحمت کے لئے تاکہ وہ لوگ اپنے رب کے ملنے کا یقین کریں [۲۱۲]', 'Then, We gave Moosa (Moses) the Book (the Taurat (Torah)), to complete (Our Favour) upon those who would do right, and explaining all things in detail and a guidance and a mercy that they might believe in the meeting with their Lord.', 'Then We gave Mūsā the Book, perfect for the one who does good, and explaining everything in detail, and a guidance and mercy, so that they may believe in meeting their Lord.'),
(944, 6, 155, 20, 7, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ ہٰذَا کِتٰبٌ اَنۡزَلۡنٰہُ مُبٰرَکٌ فَاتَّبِعُوۡہُ وَ اتَّقُوۡا لَعَلَّکُمۡ تُرۡحَمُوۡنَ ﴿۱۵۵﴾ۙ', 'اور اے کفر کرنے والو یہ کتاب بھی ہمی نے اتاری ہے برکت والی۔ تو اسکی پیروی کرو اور اللہ سے ڈرو تاکہ تم پر مہربانی کی جائے۔', 'اور ایک یہ کتاب ہے کہ ہم نے اتاری برکت والی سو اس پر چلو اور ڈرتے رہو تاکہ تم پر رحمت ہو [۲۱۳]', 'And this is a blessed Book (the Quran) which We have sent down, so follow it and fear Allah (i.e. do not disobey His Orders), that you may receive mercy (i.e. saved from the torment of Hell).', 'And this (Qur’ān) is a blessed Book We have sent down. So follow it and fear Allah, so that you may be favored with mercy.'),
(945, 6, 156, 20, 7, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'اَنۡ تَقُوۡلُوۡۤا اِنَّمَاۤ  اُنۡزِلَ الۡکِتٰبُ عَلٰی طَآئِفَتَیۡنِ مِنۡ قَبۡلِنَا ۪ وَ  اِنۡ  کُنَّا عَنۡ دِرَاسَتِہِمۡ  لَغٰفِلِیۡنَ ﴿۱۵۶﴾ۙ', 'اور اس لئے اتاری ہے کہ تم یوں نہ کہو کہ ہم سے پہلے دو ہی گروہوں پر کتابیں اتری ہیں اور ہم انکے پڑھنے سے بیخبر تھے۔', 'اس واسطے کہ کبھی تم کہنے لگو کہ کتاب جو اتری تھی سو ان ہی دو فرقوں پر جو ہم سے پہلے تھے اور ہم کو تو ان کے پڑھنے پڑھانے کی خبر ہی نہ تھی [۲۱۴]', 'Lest you (pagan Arabs) should say: \"The Book was only sent down to two sects before us (the Jews and the Christians), and for our part, we were in fact unaware of what they studied.\"', '(Had We not sent this book,) you would (have an excuse to) say, “The Book was sent down only upon two groups before us, (i.e. the Jews and the Christians) and we were unaware of what they read.”'),
(946, 6, 157, 20, 7, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'اَوۡ تَقُوۡلُوۡا لَوۡ اَنَّاۤ  اُنۡزِلَ عَلَیۡنَا الۡکِتٰبُ لَکُنَّاۤ  اَہۡدٰی مِنۡہُمۡ ۚ فَقَدۡ جَآءَکُمۡ بَیِّنَۃٌ مِّنۡ  رَّبِّکُمۡ   وَ ہُدًی وَّ رَحۡمَۃٌ ۚ فَمَنۡ  اَظۡلَمُ  مِمَّنۡ  کَذَّبَ بِاٰیٰتِ اللّٰہِ وَ صَدَفَ عَنۡہَا ؕ سَنَجۡزِی الَّذِیۡنَ یَصۡدِفُوۡنَ عَنۡ اٰیٰتِنَا سُوۡٓءَ الۡعَذَابِ  بِمَا  کَانُوۡا  یَصۡدِفُوۡنَ ﴿۱۵۷﴾', 'یا یہ نہ کہو کہ اگر ہم پر بھی کتاب نازل ہوتی تو ہم ان لوگوں کی نسبت کہیں سیدھے رستے پر ہوتے۔ سو اب تو تمہارے پاس تمہارے پروردگار کی طرف سے دلیل اور ہدایت اور رحمت آ گئ ہے۔ تو اس سے بڑھ کر ظالم کون ہو گا جو اللہ کی آیتوں کی تکذیب کرے اور ان سے لوگوں کو پھیرے جو لوگ ہماری آیتوں سے پھیرتے ہیں اس پھیرنے کے سبب ہم انکو برے عذاب کی سزا دیں گے۔', 'یا کہنے لگو کہ اگر ہم پر اترتی کتاب تو ہم تو راہ پر چلتے ان سے بہتر سو آ چکی تمہارے پاس حجت تمہارے رب کی طرف سے اور ہدایت اور رحمت [۲۱۵] اب اس سے زیادہ ظالم کون جو جھٹلاوے اللہ کی آیتوں کو اور ان سے کتراوے ہم سزا دیں گے ان کو جو ہماری آیتوں سے کتراتے ہیں برا عذاب بدلے میں اس کترانے کے [۲۱۶]', 'Or lest you (pagan Arabs) should say: \"If only the Book had been sent down to us, we would surely have been better guided than they (Jews and Christians).\" So now has come unto you a clear proof (the Quran) from your Lord, and a guidance and a mercy. Who then does more wrong than one who rejects the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah and turns away therefrom? We shall requite those who turn away from Our Ayat with an evil torment, because of their turning away (from them). (Tafsir At-Tabari, Vol. 8, Page 95)', 'Or you would say, “If the Book had been sent down to us, we would have been more adhering to the right path than they are.”Now there has come to you a clear sign from your Lord, and a guidance and mercy. So, who is more unjust than the one who gives the lie to the verses of Allah and turns away from them? We will recompense those who turn away from Our verses with an evil punishment, because of their turning away.'),
(947, 6, 158, 20, 7, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'ہَلۡ یَنۡظُرُوۡنَ  اِلَّاۤ  اَنۡ تَاۡتِیَہُمُ الۡمَلٰٓئِکَۃُ اَوۡ  یَاۡتِیَ  رَبُّکَ اَوۡ  یَاۡتِیَ بَعۡضُ اٰیٰتِ رَبِّکَ ؕ یَوۡمَ  یَاۡتِیۡ  بَعۡضُ اٰیٰتِ  رَبِّکَ لَا یَنۡفَعُ نَفۡسًا اِیۡمَانُہَا لَمۡ تَکُنۡ اٰمَنَتۡ مِنۡ قَبۡلُ اَوۡ کَسَبَتۡ فِیۡۤ  اِیۡمَانِہَا خَیۡرًا ؕ قُلِ انۡتَظِرُوۡۤا  اِنَّا مُنۡتَظِرُوۡنَ ﴿۱۵۸﴾', 'یہ اسکے سوا اور کس بات کے منتظر ہیں کہ ان کے پاس فرشتے آئیں یا خود تمہارا پروردگار آئے یا تمہارے پروردگار کی کوئی خاص نشانی آ جائے جس روز تمہارے پروردگار کی خاص نشانی آ جائے گی تو جو شخص پہلے ایمان نہیں لایا ہوگا اس وقت اسے ایمان لانا کچھ فائدہ نہیں دے گا یا جس نے اپنے ایمان کی حالت میں نیک عمل نہیں کئے ہوں گے تو گناہوں سے توبہ کرنا مفید نہ ہوگا اے پیغمبر ان سے کہدو کہ تم بھی انتظار کرو ہم بھی انتظار کرتے ہیں۔', 'کاہے کی راہ دیکھتے ہیں لوگ مگر یہی کہ ان پر آئیں فرشتے یا آئے تیرا رب یا آئے کوئی نشانی تیرے رب کی جس دن آئے گی ایک نشانی تیرے رب کی کام نہ آئے گا کسی کے اس کا ایمان لانا جو کہ پہلے سے ایمان نہ لایاتھا یا اپنے ایمان میں کچھ نیکی نہ کی تھی تو کہہ دے تم راہ دیکھو ہم بھی راہ دیکھتے ہیں [۲۱۷]', 'Do they then wait for anything other than that the angels should come to them, or that your Lord should come, or that some of the Signs of your Lord should come (i.e. portents of the Hour e.g., arising of the sun from the west)! The day that some of the Signs of your Lord do come, no good will it do to a person to believe then, if he believed not before, nor earned good (by performing deeds of righteousness) through his Faith. Say: \"Wait you! we (too) are waiting.\"', 'They are waiting for nothing less than that the angels should come to them, or your Lord or some signs of your Lord should come. The day some signs of your Lord will come, the believing of a person shall be of no use to him who had never believed before, or had not earned some good through his faith. Say, “Wait. Of course, we are waiting.”'),
(948, 6, 159, 20, 7, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'اِنَّ الَّذِیۡنَ فَرَّقُوۡا دِیۡنَہُمۡ  وَ کَانُوۡا  شِیَعًا لَّسۡتَ مِنۡہُمۡ فِیۡ شَیۡءٍ ؕ اِنَّمَاۤ  اَمۡرُہُمۡ  اِلَی اللّٰہِ ثُمَّ یُنَبِّئُہُمۡ بِمَا کَانُوۡا یَفۡعَلُوۡنَ ﴿۱۵۹﴾', 'جن لوگوں نے اپنے دین کے حصے بخرے کر لئے اور خود بھی کئ کئ فرقے ہو گئے ان سے تم کو کچھ کام نہیں ان کا کام اللہ کے حوالے پھر جو جو کچھ وہ کرتے رہے ہیں وہ ان کو سب بتائے گا۔', 'جنہوں نے راہیں نکالیں اپنے دین میں اور ہو گئے بہت سے فرقے تجھ کو ان سےکچھ سروکار نہیں ان کا کام اللہ ہی کے حوالے ہے پھر وہی جتلائے گا ان کو جو کچھ وہ کرتے تھے [۲۱۸]', 'Verily, those who divide their religion and break up into sects (all kinds of religious sects), you (O Muhammad SAW) have no concern in them in the least. Their affair is only with Allah, Who then will tell them what they used to do.', 'Surely, those who have made divisions in their religion and turned into factions, you have nothing to do with them. Their case rests with Allah alone; then He will tell them what they have been doing.'),
(949, 6, 160, 20, 7, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'مَنۡ جَآءَ بِالۡحَسَنَۃِ فَلَہٗ عَشۡرُ اَمۡثَالِہَا ۚ وَ مَنۡ جَآءَ بِالسَّیِّئَۃِ فَلَا یُجۡزٰۤی اِلَّا مِثۡلَہَا وَ ہُمۡ لَا یُظۡلَمُوۡنَ ﴿۱۶۰﴾', 'جو کوئی اللہ کے حضور نیکی لے کر آئے گا اسکو ویسی دس نیکیاں ملیں گی۔ اور جو برائی لائے گا تو اسے سزا اس جیسی ہی ملے گی اور ان پر ظلم نہیں کیا جائے گا۔', 'جو کوئی لاتا ہے ایک نیکی تو اسکے لئے اس کا دس گنا ہے اور جو کوئی لاتا ہے ایک برائی سو سزا پائے گا اسی کے برابر اور ان پر ظلم نہ ہو گا [۲۱۹]', 'Whoever brings a good deed (Islamic Monotheism and deeds of obedience to Allah and His Messenger SAW) shall have ten times the like thereof to his credit, and whoever brings an evil deed (polytheism, disbelief, hypocrisy, and deeds of disobedience to Allah and His Messenger SAW) shall have only the recompense of the like thereof, and they will not be wronged.', 'Whoever comes with a good deed will receive ten times as much, and whoever comes with an evil deed will be requited with no more than the like of it, and they shall not be wronged.'),
(950, 6, 161, 20, 7, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'قُلۡ  اِنَّنِیۡ ہَدٰىنِیۡ رَبِّیۡۤ  اِلٰی صِرَاطٍ مُّسۡتَقِیۡمٍ ۬ۚ دِیۡنًا قِیَمًا مِّلَّۃَ  اِبۡرٰہِیۡمَ حَنِیۡفًا ۚ وَ مَا کَانَ مِنَ الۡمُشۡرِکِیۡنَ ﴿۱۶۱﴾', 'کہدو کہ مجھے میرے پروردگار نے سیدھا رستہ دکھا دیا ہے یعنی دین صحیح طریقہ ابراہیم کا جو ایک اللہ ہی کے ہو رہے تھے۔  اور مشرکوں میں سے نہ تھے۔', 'تو کہہ دے مجھ کو سجھائی میرے رب نے راہ سیدھی دین صحیح ملت ابراہیم کی جو ایک ہی طرف کا تھا [۲۲۰] اور نہ تھا شرک والوں میں [۲۲۱]', 'Say (O Muhammad SAW): \"Truly, my Lord has guided me to a Straight Path, a right religion, the religion of Ibrahim (Abraham), Hanifa (i.e. the true Islamic Monotheism - to believe in One God (Allah i.e. to worship none but Allah, Alone)) and he was not of Al-Mushrikoon (see V.2:105).\"', 'Say, “As for me, my Lord has guided me to a straight path, the straight religion, the faith of Ibrāhīm who was upright and was not of those who associate partners with Allah.'),
(951, 6, 162, 20, 7, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'قُلۡ  اِنَّ صَلَاتِیۡ  وَ نُسُکِیۡ وَ مَحۡیَایَ وَ مَمَاتِیۡ   لِلّٰہِ   رَبِّ  الۡعٰلَمِیۡنَ ﴿۱۶۲﴾ۙ', 'یہ بھی کہدو کہ میری نماز اور میری قربانی اور میرا جینا اور میرا مرنا سب اللہ رب العالمین ہی کے لئے ہے۔', 'تو کہہ کہ میری نماز اور میری قربانی اور میرا جینا اور مرنا اللہ ہی کے لئے ہے جو پالنے والا سارے جہان کا ہے', 'Say (O Muhammad SAW): \"Verily, my Salat (prayer), my sacrifice, my living, and my dying are for Allah, the Lord of the Alameen (mankind, jinns and all that exists).', 'Say, “My prayer, my offering, my life and my death are for Allah, the Lord of all the worlds.'),
(952, 6, 163, 20, 7, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'لَا شَرِیۡکَ لَہٗ ۚ وَ بِذٰلِکَ اُمِرۡتُ وَ اَنَا  اَوَّلُ الۡمُسۡلِمِیۡنَ ﴿۱۶۳﴾', 'جس کا کوئی شریک نہیں اور مجھ کو اسی بات کا حکم ملا ہے اور میں سب سے اول فرمانبردار ہوں۔', 'کوئی نہیں اس کا شریک [۲۲۲] اور یہی مجھ کو حکم ہوا اور میں سب سے پہلے فرمانبردار ہوں [۲۲۳]', '\"He has no partner. And of this I have been commanded, and I am the first of the Muslims.\"', 'For Him there is no partner. And thus I have been commanded, and I am the first one to submit.”'),
(953, 6, 164, 20, 7, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'قُلۡ اَغَیۡرَ اللّٰہِ اَبۡغِیۡ رَبًّا وَّ ہُوَ رَبُّ کُلِّ شَیۡءٍ ؕ وَ لَا تَکۡسِبُ کُلُّ نَفۡسٍ  اِلَّا عَلَیۡہَا ۚ وَ لَا تَزِرُ وَازِرَۃٌ  وِّزۡرَ  اُخۡرٰی ۚ ثُمَّ اِلٰی رَبِّکُمۡ مَّرۡجِعُکُمۡ فَیُنَبِّئُکُمۡ بِمَا کُنۡتُمۡ  فِیۡہِ  تَخۡتَلِفُوۡنَ ﴿۱۶۴﴾', 'کہو کیا میں اللہ کے سوا کوئی اور آقا تلاش کروں۔ جبکہ وہی تو ہر چیز کا مالک ہے اور جو کوئی برا کام کرتا ہے تو اسکا ضرر اسی کو ہوتا ہے اور کوئی شخص کسی دوسرے کے گناہ کا بوجھ نہیں اٹھائے گا۔ پھر تم سب کو اپنے پروردگار کی طرف لوٹ کر جانا ہے تو جن جن باتوں میں تم اختلاف کیا کرتے تھے وہ تم کو بتائے گا۔', 'تو کہہ کیا اب میں اللہ کے سوا تلاش کروں کوئی رب اور وہی ہے رب ہر چیز کا [۲۲۴] اور جو کوئی گناہ کرتا ہے سو وہ اس کے ذمہ پر ہے اور بوجھ نہ اٹھائے گا ایک شخص دوسرے کا پھر تمہارے رب کے پاس ہی تم سب کو لوٹ کر جانا ہے سو وہ جتلائے گا جس بات میں تم جھگڑتے تھے [۲۲۵]', 'Say: \"Shall I seek a lord other than Allah, while He is the Lord of all things? No person earns any (sin) except against himself (only), and no bearer of burdens shall bear the burden of another. Then unto your Lord is your return, so He will tell you that wherein you have been differing.\"', 'Say, “Should I seek a lord other than Allah while He is the Lord of everything? And nobody does anything but to his own account, and no bearer of burden shall bear the burden of another. Then to your Lord is your return. Then He will let you know what you were disputing about.”'),
(954, 6, 165, 20, 7, 8, 'وَ لَوۡ اَنَّنَا', 'الانعام', 'وَ ہُوَ الَّذِیۡ جَعَلَکُمۡ خَلٰٓئِفَ الۡاَرۡضِ وَ رَفَعَ بَعۡضَکُمۡ فَوۡقَ بَعۡضٍ دَرَجٰتٍ لِّیَبۡلُوَکُمۡ فِیۡ مَاۤ  اٰتٰکُمۡ ؕ اِنَّ رَبَّکَ سَرِیۡعُ  الۡعِقَابِ ۫ۖ وَ  اِنَّہٗ  لَغَفُوۡرٌ  رَّحِیۡمٌ ﴿۱۶۵﴾٪', 'اور وہی تو ہے جس نے زمین میں تم کو اپنا نائب بنایا اور ایک کے دوسرے پر درجے بلند کئے تاکہ جو کچھ اس نے تمہیں بخشا ہے اس میں تمہاری آزمائش کرے بیشک تمہارا پروردگار جلد عذاب دینے والا ہے اور بیشک وہ بخشنے والا ہے مہربان بھی ہے۔', 'اور اسی نے تم کو نائب کیا ہے زمین میں [۲۲۶] اور بلند کر دیے تم میں درجے ایک کے ایک پر [۲۲۷] تاکہ آزمائے تم کو اپنی دیئے ہوئے حکموں میں تیرا رب جلد عذاب کرنے والا ہے اور وہی بخشنے والا مہربان ہے [۲۲۸]', 'And it is He Who has made you generations coming after generations, replacing each other on the earth. And He has raised you in ranks, some above others that He may try you in that which He has bestowed on you. Surely your Lord is Swift in retribution, and certainly He is OftForgiving, Most Merciful.', 'It is He who made you the vicegerents of the earth and raised some of you in ranks over others, so that He may test you in what He has given you. Surely, your Lord is swift in punishing, and surely He is Most-Forgiving, Very-Merciful.'),
(955, 7, 1, 1, 8, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'الٓـمّٓصٓ ۚ﴿۱﴾', 'المص۔', 'المص', 'AlifLamMeemSad. (These letters are one of the miracles of the Quran and none but Allah (Alone) knows their meanings).', 'Alif, Lām, Mīm, Sād.'),
(956, 7, 2, 1, 8, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'کِتٰبٌ اُنۡزِلَ  اِلَیۡکَ  فَلَا  یَکُنۡ فِیۡ صَدۡرِکَ حَرَجٌ مِّنۡہُ لِتُنۡذِرَ بِہٖ وَ ذِکۡرٰی لِلۡمُؤۡمِنِیۡنَ ﴿۲﴾', 'اے نبی یہ کتاب جو تم پر نازل ہوئی ہے۔ اس سے تمہیں تنگدل نہیں ہونا چاہیے یہ نازل اس لئے ہوئی ہے کہ تم اس کے ذریعے سے لوگوں کو ڈر سناؤ اور یہ ایمان والوں کے لئے نصیحت ہے۔', 'یہ کتاب اتری ہے تجھ پر سو چاہئے کہ تیرا جی تنگ نہ ہو اس کے پہنچانے سے [۱] تاکہ تو ڈرائے اس سے اور نصیحت ہو ایمان والوں کو [۲]', '(This is the) Book (the Quran) sent down unto you (O Muhammad SAW), so let not your breast be narrow therefrom, that you warn thereby, and a reminder unto the believers.', '(This is) a book sent down to you. Therefore, your heart must not be straitened because of it. (It is revealed to you) so that you may warn through it, and it may be an advice for the believers.'),
(957, 7, 3, 1, 8, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'اِتَّبِعُوۡا مَاۤ  اُنۡزِلَ  اِلَیۡکُمۡ  مِّنۡ  رَّبِّکُمۡ  وَ لَا تَتَّبِعُوۡا مِنۡ دُوۡنِہٖۤ  اَوۡلِیَآءَ ؕ قَلِیۡلًا مَّا  تَذَکَّرُوۡنَ ﴿۳﴾', 'لوگو جو کتاب تم پر تمہارے پروردگار کے ہاں سے نازل ہوئی ہے اسکی پیروی کرو۔ اور اسکے سوا اور رفیقوں کی پیروی نہ کرو اور تم کم ہی نصیحت قبول کرتے ہو۔', 'چلو اسی پر جو اترا تم پر تمہارے رب کی طرف سے اور نہ چلو اسکے سوا اور رفیقوں کے پیچھے تم بہت کم دھیان کرتے ہو [۳]', 'Say (O Muhammad SAW) to these idolaters (pagan Arabs) of your folk:) Follow what has been sent down unto you from your Lord (the Quran and Prophet Muhammads Sunnah), and follow not any Auliya (protectors and helpers, etc. who order you to associate partners in worship with Allah), besides Him (Allah). Little do you remember!', '(O humankind,) follow what has been sent down to you from your Lord, and do not follow any masters other than Him. Little you heed to advice!'),
(958, 7, 4, 1, 8, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ کَمۡ مِّنۡ قَرۡیَۃٍ اَہۡلَکۡنٰہَا فَجَآءَہَا بَاۡسُنَا  بَیَاتًا  اَوۡ  ہُمۡ  قَآئِلُوۡنَ ﴿۴﴾', 'اور کتنی ہی بستیاں ہیں کہ ہم نے تباہ کر ڈالیں جن پر ہمارا عذاب یا تو رات میں آتا تھا جبکہ وہ سوتے تھے یا دن کو جب وہ قیلولہ یعنی دوپہر کو آرام کرتے تھے۔', 'اور کتنی بستیاں ہم نے ہلاک کر دیں کہ پہنچا ان پر ہمارا عذاب راتوں رات یا دوپہر کو سوتے ہوئے', 'And a great number of towns (their population) We destroyed (for their crimes). Our torment came upon them (suddenly) by night or while they were sleeping for their afternoon rest.', 'How many a town We have destroyed! Our punishment came upon them at night or when they were having a nap at midday.'),
(959, 7, 5, 1, 8, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'فَمَا کَانَ دَعۡوٰىہُمۡ اِذۡ  جَآءَہُمۡ  بَاۡسُنَاۤ  اِلَّاۤ  اَنۡ  قَالُوۡۤا  اِنَّا کُنَّا ظٰلِمِیۡنَ ﴿۵﴾', 'تو جس وقت ان پر عذاب آتا تھا انکے منہ سے یہی نکلتا تھا کہ ہائے ہم اپنے اوپر ظلم کرتے رہے۔', 'پھر یہی تھی ان کی پکار جس وقت کہ پہنچا ان پر ہمارا عذاب کہ کہنے لگے بیشک ہمی تھے گنہگار [۴]', 'No cry did they utter when Our Torment came upon them but this: \"Verily, we were Zalimoon (polytheists and wrongdoers, etc.)\".', 'So, when Our punishment came upon them, they could say nothing but cry, “We were wrongdoers indeed.”'),
(960, 7, 6, 1, 8, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'فَلَنَسۡـَٔلَنَّ الَّذِیۡنَ اُرۡسِلَ اِلَیۡہِمۡ وَ لَنَسۡـَٔلَنَّ  الۡمُرۡسَلِیۡنَ ۙ﴿۶﴾', 'تو جن لوگوں کی طرف پیغمبر بھیجے گئے ہم ان سے بھی پرسش کریں گے اور پیغمبروں سے بھی پوچھیں گے۔', 'سو ہم کو ضرور پوچھنا ہے ان سے جن کے پاس رسول بھیجے گئے تھے اور ہم کو ضرور پوچھنا ہے رسولوں سے [۵]', 'Then surely, We shall question those (people) to whom it (the Book) was sent and verily, We shall question the Messengers.', 'So, We shall ask those to whom the messengers were sent, and We shall ask the messengers (how they conveyed the message).'),
(961, 7, 7, 1, 8, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'فَلَنَقُصَّنَّ عَلَیۡہِمۡ بِعِلۡمٍ  وَّ مَا کُنَّا غَآئِبِیۡنَ ﴿۷﴾', 'پھر اپنے علم سے ان کے حالات بیان کریں گے اور ہم کہیں غائب تو نہیں تھے۔', 'پھر ہم انکو احوال سنائیں گے اپنے علم سے اور ہم کہیں غائب نہ تھے [۶]', 'Then surely, We shall narrate unto them (their whole story) with knowledge, and indeed We were not absent.', 'Then, having full knowledge, We shall tell them the whole story, as We were never far from them.'),
(962, 7, 8, 1, 8, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ الۡوَزۡنُ یَوۡمَئِذِ ۣالۡحَقُّ ۚ فَمَنۡ ثَقُلَتۡ مَوَازِیۡنُہٗ  فَاُولٰٓئِکَ  ہُمُ  الۡمُفۡلِحُوۡنَ ﴿۸﴾', 'اور اس روز اعمال کا تلنا برحق ہے۔ تو جن لوگوں کی تولیں بھاری ہوں گی وہ تو کامیاب ہیں۔', 'اور تول اس دن ٹھیک ہو گی پھر جس کی تولیں بھاری ہوئیں سو  وہی ہیں نجات پانے والے', 'And the weighing on that day (Day of Resurrection) will be the true (weighing). So as for those whose scale (of good deeds) will be heavy, they will be the successful (by entering Paradise).', 'The Weighing (of deeds) on that day is definite. As for those whose scales are heavy, they will be the successful ones.'),
(963, 7, 9, 1, 8, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ مَنۡ خَفَّتۡ مَوَازِیۡنُہٗ فَاُولٰٓئِکَ الَّذِیۡنَ خَسِرُوۡۤا اَنۡفُسَہُمۡ بِمَا کَانُوۡا بِاٰیٰتِنَا یَظۡلِمُوۡنَ ﴿۹﴾', 'اور جنکی تولیں ہلکی ہوں گی تو یہی لوگ ہیں جنہوں نے اپنے آپکو خسارے میں ڈالا اس لئے کہ ہماری آیتوں کے بارے میں بے انصافی کرتے تھے۔', 'اور جس کی تولیں ہلکی ہوئیں سو وہی ہیں جنہوں نے اپنا نقصان کیا [۷] اس واسطے کہ ہماری آیتوں کا انکار کرتے تھے [۸]', 'And as for those whose scale will be light, they are those who will lose their ownselves (by entering Hell) because they denied and rejected Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.).', 'But those whose scales are light, they are the ones who have brought loss to themselves, because they did not do justice to Our verses.'),
(964, 7, 10, 1, 8, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ لَقَدۡ مَکَّنّٰکُمۡ فِی الۡاَرۡضِ وَ جَعَلۡنَا لَکُمۡ فِیۡہَا مَعَایِشَ ؕ قَلِیۡلًا  مَّا تَشۡکُرُوۡنَ ﴿٪۱۰﴾', 'اور ہم ہی نے زمین میں تمہارا ٹھکانہ بنایا اور اس میں تمہارے لئے اسباب معیشت پیدا کئے مگر تم کم ہی شکر کرتے ہو۔', 'اور ہم نے تم کو جگہ دی زمین میں اور مقرر کر دیں اس میں تمہارے لئے روزیاں تم بہت کم شکر کرتے ہو [۹]', 'And surely, We gave you authority on the earth and appointed for you therein provisions (for your life). Little thanks do you give.', 'We established you on earth, and created in it means of living for you. Little you appreciate.'),
(965, 7, 11, 2, 9, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ لَقَدۡ خَلَقۡنٰکُمۡ ثُمَّ صَوَّرۡنٰکُمۡ ثُمَّ قُلۡنَا لِلۡمَلٰٓئِکَۃِ اسۡجُدُوۡا  لِاٰدَمَ ٭ۖ فَسَجَدُوۡۤا  اِلَّاۤ  اِبۡلِیۡسَ ؕ لَمۡ  یَکُنۡ مِّنَ السّٰجِدِیۡنَ ﴿۱۱﴾', 'اور ہم ہی نے تم کو ابتدا میں مٹی سے پیدا کیا پھر تمہاری شکل و صورت بنائی پھر فرشتوں کو حکم دیا کہ آدم کے آگے سجدہ کرو تو سب نے سجدہ کیا۔ لیکن ابلیس۔ کہ وہ سجدہ کرنے والوں میں شامل نہ ہوا۔', 'اور ہم نے تم کو پیدا کیا پھر صورتیں بنائیں تمہاری پھر حکم کیا فرشتوں کو کہ سجدہ کرو آدم کو پس سجدہ کیا سب نے مگر ابلیس نہ تھا سجدہ والوں میں', 'And surely, We created you (your father Adam) and then gave you shape (the noble shape of a human being), then We told the angels, \"Prostrate to Adam\", and they prostrated, except Iblees (Satan), he refused to be of those who prostrate.', 'We created you, then gave you a shape, then We said to the angels, “Prostrate yourselves before ’Ādam.” So, they all prostrated themselves, except Iblīs (Satan). He did not join those who fell prostrate.'),
(966, 7, 12, 2, 9, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَ مَا مَنَعَکَ  اَلَّا  تَسۡجُدَ   اِذۡ   اَمَرۡتُکَ ؕ قَالَ  اَنَا خَیۡرٌ  مِّنۡہُ ۚ خَلَقۡتَنِیۡ مِنۡ نَّارٍ  وَّ  خَلَقۡتَہٗ  مِنۡ  طِیۡنٍ ﴿۱۲﴾', 'اللہ نے فرمایا جب میں نے تجھ کو بھی حکم دیا تھا تو کس چیز نے تجھے سجدہ کرنے سے باز رکھا اس نے کہا کہ میں اس سے افضل ہوں۔ مجھے تو نے آگ سے پیدا کیا ہے اور اسے مٹی سے بنایا ہے۔', 'کہا تجھ کو کیا مانع تھا کہ تو نے سجدہ نہ کیا جب میں نے حکم دیا بولا میں اس سے بہتر ہوں مجھ کو تو نے بنایا آگ سے اور اس کو بنایا مٹی سے', '(Allah) said: \"What prevented you (O Iblees) that you did not prostrate, when I commanded you?\" Iblees said: \"I am better than him (Adam), You created me from fire, and him You created from clay.\"', 'Allah said, “What has prevented you from prostrating when I ordered you?” He said, “I am better than him. You have created me of fire, and created him of clay.”'),
(967, 7, 13, 2, 9, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَ فَاہۡبِطۡ مِنۡہَا فَمَا یَکُوۡنُ لَکَ اَنۡ تَتَکَبَّرَ فِیۡہَا فَاخۡرُجۡ  اِنَّکَ مِنَ الصّٰغِرِیۡنَ ﴿۱۳﴾', 'فرمایا تو بہشت سے اتر جا تجھے شایاں نہیں کہ یہاں تکبر کرے پس نکل جا۔ کہ تو ذلیل لوگوں میں سے ہے۔', 'کہا تو اتر یہاں سے [۱۰] تو اس لائق نہیں کہ تکبر کرے یہاں پس باہر نکل تو ذلیل ہے [۱۱]', '(Allah) said: \"(O Iblees) get down from this (Paradise), it is not for you to be arrogant here. Get out, for you are of those humiliated and disgraced.\"', 'He said, “Then, get you down from here, it is not for you to show arrogance here. So, get out. You are one of the degraded.'),
(968, 7, 14, 2, 9, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَ  اَنۡظِرۡنِیۡۤ   اِلٰی  یَوۡمِ  یُبۡعَثُوۡنَ ﴿۱۴﴾', 'اس نے کہا کہ مجھے اس دن تک مہلت عطا فرما جس دن لوگ قبروں سے اٹھائے جائیں گے۔', 'بولا کہ مجھے مہلت دے اس دن تک کہ لوگ قبروں سے اٹھائے جائیں', '(Iblees) said: \"Allow me respite till the Day they are raised up (i.e. the Day of Resurrection).\"', 'He said, “Then give me respite until a day when all will be resurrected.'),
(969, 7, 15, 2, 9, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَ   اِنَّکَ  مِنَ  الۡمُنۡظَرِیۡنَ ﴿۱۵﴾', 'فرمایا اچھا تجھ کو مہلت دی جاتی ہے۔', 'فرمایا تجھ کو مہلت دی گئ [۱۲]', '(Allah) said: \"You are of those allowed respite.\"', 'He (Allah) said, “You are granted respite’’.'),
(970, 7, 16, 2, 9, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَ فَبِمَاۤ  اَغۡوَیۡتَنِیۡ لَاَقۡعُدَنَّ  لَہُمۡ صِرَاطَکَ  الۡمُسۡتَقِیۡمَ ﴿ۙ۱۶﴾', 'بولا کہ مجھے تو تو نے گمراہ کیا ہی ہے میں بھی تیرے سیدھے رستے پر ان کو گمراہ کرنے کے لئے بیٹھوں گا۔', 'بولا تو جیسا تو نے مجھے گمراہ کیا ہے میں بھی ضرور بیٹھوں گا انکی تاک میں تیری سیدھی راہ پر [۱۳]', '(Iblees) said: \"Because You have sent me astray, surely I will sit in wait against them (human beings) on Your Straight Path.', 'He said, “Now that You have led me astray, I will certainly sit for them (in ambush) on Your straight path.'),
(971, 7, 17, 2, 9, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'ثُمَّ لَاٰتِیَنَّہُمۡ مِّنۡۢ بَیۡنِ اَیۡدِیۡہِمۡ وَ مِنۡ خَلۡفِہِمۡ  وَ عَنۡ اَیۡمَانِہِمۡ وَ عَنۡ شَمَآئِلِہِمۡ ؕ وَ لَا  تَجِدُ اَکۡثَرَہُمۡ شٰکِرِیۡنَ ﴿۱۷﴾', 'پھر ان کے آگے سے اور پیچھے سے دائیں سے اور بائیں سے غرض ہر طرف سے آؤں گا اور تو ان میں سے اکثر کو شکرگذار نہیں پائے گا۔', 'پھر ان پر آؤں گا ان کے آگے سے اور پیچھے سے اور دائیں سے اور بائیں سے [۱۴] اور نہ پائے گا تو اکثروں کو ان میں شکرگذار [۱۵]', 'Then I will come to them from before them and behind them, from their right and from their left, and You will not find most of them as thankful ones (i.e. they will not be dutiful to You).\"', 'Then I will come upon them from their front side and from their behind, and from their right and from their left. You will not find most of them grateful.'),
(972, 7, 18, 2, 9, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَ اخۡرُجۡ مِنۡہَا مَذۡءُوۡمًا مَّدۡحُوۡرًا ؕ لَمَنۡ تَبِعَکَ مِنۡہُمۡ لَاَمۡلَـَٔنَّ جَہَنَّمَ  مِنۡکُمۡ  اَجۡمَعِیۡنَ ﴿۱۸﴾', 'اللہ نے فرمایا نکل جا یہاں سے پاجی۔ مردود جو لوگ ان میں سے تیری پیروی کریں گے میں ان کو اور تجھ کو جہنم میں ڈال کر تم سب سے جہنم کو بھر دوں گا۔', 'کہا نکل یہاں سے برے حال سے مردود ہو کر جو کوئی ان میں سے تیری راہ پر چلے گا تو میں ضرور بھر دوں گا دوزخ کو تم سب سے [۱۶]', '(Allah) said (to Iblees) \"Get out from this (Paradise) disgraced and expelled. Whoever of them (mankind) will follow you, then surely I will fill Hell with you all.\"', 'He (Allah) said, “Get out of here, condemned, rejected. Indeed, whosoever will follow you from among them, I will fill Hell with all of you together.'),
(973, 7, 19, 2, 9, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ یٰۤاٰدَمُ  اسۡکُنۡ اَنۡتَ وَ زَوۡجُکَ الۡجَنَّۃَ فَکُلَا مِنۡ حَیۡثُ شِئۡتُمَا وَ لَا تَقۡرَبَا ہٰذِہِ الشَّجَرَۃَ  فَتَکُوۡنَا مِنَ  الظّٰلِمِیۡنَ ﴿۱۹﴾', 'اور اے آدم  تم اور تمہاری بیوی بہشت میں رہو سہو اور جہاں سے چاہو اور جو چاہو نوش جان کرو مگر اس درخت کے پاس نہ جانا۔ ورنہ گناہگار ہو جاؤ گے۔', 'اور اے آدم رہ تو اور تیری عورت جنت میں پھر کھاؤ جہاں سے چاہو اور پاس نہ جاؤ اس درخت کے پھر تم ہو جاؤ گے گنہگار [۱۷]', '\"And O Adam! Dwell you and your wife in Paradise, and eat thereof as you both wish, but approach not this tree otherwise you both will be of the Zalimoon (unjust and wrongdoers).\"', 'O ’Ādam, dwell, you and your wife, in Paradise, and eat from wherever you like, but do not go near this tree, otherwise you shall join the transgressors.”'),
(974, 7, 20, 2, 9, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'فَوَسۡوَسَ لَہُمَا الشَّیۡطٰنُ لِیُبۡدِیَ لَہُمَا مَا وٗرِیَ عَنۡہُمَا مِنۡ سَوۡاٰتِہِمَا وَ قَالَ مَا نَہٰکُمَا رَبُّکُمَا عَنۡ ہٰذِہِ الشَّجَرَۃِ  اِلَّاۤ اَنۡ  تَکُوۡنَا مَلَکَیۡنِ اَوۡ تَکُوۡنَا مِنَ  الۡخٰلِدِیۡنَ ﴿۲۰﴾', 'تو شیطان دونوں کو بہکانے لگا تاکہ انکی شرمگاہیں جو ان سے پوشیدہ تھیں ان پر کھول دے اور کہنے لگا کہ تم کو تمہارے پروردگار نے اس درخت سے صرف اس لئے منع کیا ہے کہ تم فرشتے نہ بن جاؤ یا ہمیشہ جیتے نہ رہو۔', 'پھر بہکایا ان کو شیطان نے تاکہ کھول دے ان پر وہ چیز کہ انکی نظر سے پوشیدہ تھی انکی شرمگاہوں سے اور وہ بولا کہ تم کو نہیں روکا تمہارے رب نے اس درخت سے مگر اسی لئے کہ کبھی تم ہو جاؤ فرشتہ یا ہو جاؤ ہمیشہ رہنے والے', 'Then Shaitan (Satan) whispered suggestions to them both in order to uncover that which was hidden from them of their private parts (before); he said: \"Your Lord did not forbid you this tree save you should become angels or become of the immortals.\"', 'Then Satan whispered to them, so that he might expose to them their shame that was hidden from them; and said, “Your Lord has not prohibited this tree for you, but to avoid your becoming angels or your becoming eternal.”'),
(975, 7, 21, 2, 9, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ قَاسَمَہُمَاۤ  اِنِّیۡ لَکُمَا لَمِنَ النّٰصِحِیۡنَ ﴿ۙ۲۱﴾', 'اور ان سے قسم کھا کر کہا کہ میں تو تمہارا خیرخواہ ہوں۔', 'اور انکے آگے قسم کھائی کہ میں البتہ تمہارا دوست ہوں', 'And he (Shaitan (Satan)) swore by Allah to them both (saying): \"Verily, I am one of the sincere wellwishers for you both.\"', 'He swore an oath, “I am one of your well-wishers.”'),
(976, 7, 22, 2, 9, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'فَدَلّٰىہُمَا بِغُرُوۡرٍ ۚ فَلَمَّا ذَاقَا الشَّجَرَۃَ بَدَتۡ لَہُمَا سَوۡاٰتُہُمَا وَ طَفِقَا یَخۡصِفٰنِ عَلَیۡہِمَا مِنۡ وَّرَقِ الۡجَنَّۃِ ؕ وَ نَادٰىہُمَا رَبُّہُمَاۤ  اَلَمۡ اَنۡہَکُمَا عَنۡ تِلۡکُمَا الشَّجَرَۃِ  وَ اَقُلۡ لَّکُمَاۤ  اِنَّ الشَّیۡطٰنَ لَکُمَا عَدُوٌّ مُّبِیۡنٌ ﴿۲۲﴾', 'غرض مردود نے دھوکا دے کر انکو معصیت کی طرف کھینچ ہی لیا سو جب انہوں نے اس درخت کے پھل کو کھالیا تو انکی شرمگاہیں کھل گئیں اور وہ بہشت کے درختوں کے پتے توڑ توڑ کر اپنے اوپر چپکانے اور ستر چھپانے لگے اور انکے پروردگار نے انکو پکارا کہ کیا میں نے تم کو اس درخت کے پاس جانے سے منع نہیں کیا تھا اور جتا نہیں دیا تھا کہ شیطان تمہارا کھلم کھلا دشمن ہے۔', 'پھر مائل کر لیا انکو فریب سے [۱۸] پھر جب چکھا ان دونوں نے درخت کو تو کھل گئیں ان پر شرمگاہیں انکی [۱۹] اور لگے جوڑنے اپنے اوپر بہشت کے پتے [۲۰] اور پکارا انکو انکے رب نے کیا میں نے منع نہ کیا تھا تم کو اس درخت سے اور نہ کہہ دیا تھا تم کو کہ شیطان تمہارا کھلا دشمن ہے', 'So he misled them with deception. Then when they tasted of the tree, that which was hidden from them of their shame (private parts) became manifest to them and they began to stick together the leaves of Paradise over themselves (in order to cover their shame). And their Lord called out to them (saying): \"Did I not forbid you that tree and tell you: Verily, Shaitan (Satan) is an open enemy unto you?\"', 'Thus, he cast both of them down by deception. When they tasted (the fruit of) the tree, their shame was exposed to them, and they began to patch together some leaves of Paradise upon themselves, and their Lord called them, “Did I not forbid you from that tree? Did I not tell you that Satan is your declared enemy?”'),
(977, 7, 23, 2, 9, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَا رَبَّنَا ظَلَمۡنَاۤ  اَنۡفُسَنَا ٜ وَ  اِنۡ  لَّمۡ تَغۡفِرۡ لَنَا وَ تَرۡحَمۡنَا لَنَکُوۡنَنَّ مِنَ الۡخٰسِرِیۡنَ ﴿۲۳﴾', 'دونوں عرض کرنے لگے کہ پروردگار ہم نے اپنی جانوں پر ظلم کیا اور اگر تو ہمیں نہیں بخشے گا اور ہم پر رحم نہیں کرے گا تو ہم تباہ ہو جائیں گے۔', 'بولے وہ دونوں اے رب ہمارے ظلم کیا ہم نے اپنی جان پر اور اگر تو ہم کو نہ بخشے اور ہم پر رحم نہ کرے تو ہم ضرور ہو جائیں گے تباہ', 'They said: \"Our Lord! We have wronged ourselves. If You forgive us not, and bestow not upon us Your Mercy, we shall certainly be of the losers.\"', 'They said, “Our Lord, we have wronged ourselves, and if You do not forgive us and do not bless us with mercy, we shall, indeed, be among the losers.'),
(978, 7, 24, 2, 9, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَ اہۡبِطُوۡا بَعۡضُکُمۡ  لِبَعۡضٍ عَدُوٌّ ۚ وَ لَکُمۡ فِی الۡاَرۡضِ مُسۡتَقَرٌّ  وَّ مَتَاعٌ اِلٰی  حِیۡنٍ ﴿۲۴﴾', 'فرمایا تم سب بہشت سے اتر جاؤ اب سے تم ایک دوسرے کے دشمن ہو اور تمہارے لئے ایک وقت خاص تک زمین میں ٹھکانہ اور زندگی کا سامان کر دیا گیا ہے۔', 'فرمایا تم اترو تم ایک دوسرے کے دشمن ہو گے [۲۱] اور تمہارے واسطے زمین میں ٹھکانا اور نفع اٹھانا ہے ایک وقت تک', '(Allah) said: \"Get down, one of you an enemy to the other (i.e. Adam, Hawwa (Eve), and Shaitan (Satan), etc.). On earth will be a dwellingplace for you and an enjoyment, - for a time.\"', 'He said, “Go down, some of you enemies of some; and for you on the earth there will be a dwelling place and enjoyment for a time.”'),
(979, 7, 25, 2, 9, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَ فِیۡہَا تَحۡیَوۡنَ وَ فِیۡہَا تَمُوۡتُوۡنَ وَ مِنۡہَا  تُخۡرَجُوۡنَ ﴿٪۲۵﴾', 'فرمایا کہ اسی میں تمہارا جینا ہوگا اور اسی میں مرنا اور اسی میں سے قیامت کو زندہ کر کے نکالے جاؤ گے۔', 'فرمایا اسی میں تم زندہ رہو گے [۲۲] اور اسی میں تم مرو گے اور اسی سے تم نکالے جاؤ گے', 'He said: \"Therein you shall live, and therein you shall die, and from it you shall be brought out (i.e.resurrected).\"', '(Further) He said, “There you shall live and there you shall die, and from there you shall be raised again.”'),
(980, 7, 26, 3, 10, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'یٰبَنِیۡۤ  اٰدَمَ  قَدۡ  اَنۡزَلۡنَا عَلَیۡکُمۡ  لِبَاسًا یُّوَارِیۡ سَوۡاٰتِکُمۡ وَ رِیۡشًا ؕ وَ لِبَاسُ التَّقۡوٰی ۙ ذٰلِکَ خَیۡرٌ ؕ ذٰلِکَ مِنۡ اٰیٰتِ اللّٰہِ  لَعَلَّہُمۡ  یَذَّکَّرُوۡنَ ﴿۲۶﴾', 'اے بنی آدم ہم نے تم پر پوشاک اتاری کہ تمہاری شرمگاہوں کو چھپائے اور تمہارے بدن کو زینت دے اور جو پرہیزگاری کا لباس ہے وہ سب سے اچھا ہے یہ اللہ کی نشانیاں ہیں تاکہ لوگ نصیحت حاصل کریں۔', 'اےاولاد آدم کی ہم نے اتاری تم پر پوشاک جو ڈھانکے تمہاری شرمگاہیں اور اتارے آرائش کے کپڑے [۲۳] اور لباس پرہیزگاری کا وہ سب سے بہتر ہے [۲۴] یہ نشانیاں ہیں اللہ کی قدرت کی تاکہ وہ لوگ غور کریں [۲۵]', 'O Children of Adam! We have bestowed raiment upon you to cover yourselves (screen your private parts, etc.) and as an adornment, and the raiment of righteousness, that is better. Such are among the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah, that they may remember (i.e. leave falsehood and follow truth).', 'O children of ’Ādam, We have sent down to you the dress that covers your shame and provides adornment. As for the dress of Taqwā (piety), that is the best. That is one of the signs of Allah, so that they may learn a lesson.'),
(981, 7, 27, 3, 10, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'یٰبَنِیۡۤ  اٰدَمَ  لَا یَفۡتِنَنَّکُمُ الشَّیۡطٰنُ کَمَاۤ اَخۡرَجَ  اَبَوَیۡکُمۡ  مِّنَ الۡجَنَّۃِ یَنۡزِعُ عَنۡہُمَا لِبَاسَہُمَا لِیُرِیَہُمَا سَوۡاٰتِہِمَا ؕ اِنَّہٗ یَرٰىکُمۡ ہُوَ وَ قَبِیۡلُہٗ مِنۡ حَیۡثُ لَا تَرَوۡنَہُمۡ ؕ اِنَّا جَعَلۡنَا الشَّیٰطِیۡنَ اَوۡلِیَآءَ  لِلَّذِیۡنَ لَا یُؤۡمِنُوۡنَ ﴿۲۷﴾', 'اے بنی آدم دیکھنا کہیں شیطان تمہیں بہکا نہ دے جس طرح تمہارے ماں باپ کو بہکا کر بہشت سے نکلوا دیا اور ان سے ان کے کپڑے اتروا دیئے تاکہ ان کے ستر انکو کھول کر دکھا دے۔ وہ اور اسکے بھائی بند تم کو ایسی جگہ سے دیکھتے رہتے ہیں جہاں سے تم انکو نہیں دیکھ سکتے ہم نے شیطانوں کو انہی لوگوں کا رفیق بنایا ہے جو ایمان نہیں رکھتے۔', 'اے اولاد آدم کی نہ بہکائے تم کو شیطان جیسا کہ اس نے نکال دیا تمہارے ماں باپ کو بہشت سے اتروائے ان سے ان کے کپڑے [۲۶] تاکہ دکھلائے انکو شرمگاہیں انکی وہ دیکھتا ہے تم کو اور اسکی قوم جہاں سے تم انکو نہیں دیکھتے [۲۷] ہم نےکر دیا شیطانوں کو رفیق ان لوگوں کا جو ایمان نہیں لاتے [۲۸]', 'O Children of Adam! Let not Shaitan (Satan) deceive you, as he got your parents (Adam and Hawwa (Eve)) out of Paradise, stripping them of their raiments, to show them their private parts. Verily, he and Qabeeluhu (his soldiers from the jinns or his tribe) see you from where you cannot see them. Verily, We made the Shayatin (devils) Auliya (protectors and helpers) for those who believe not.', 'O children of ’Ādam, “Do not let Satan put you in trouble the way he had your parents expelled from Paradise, having their dress removed from them, so that he could show them their shame. Indeed, he sees you - he and his company - from where you do not see them. Surely, We have made the devils friends to those who do not believe.'),
(982, 7, 28, 3, 10, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ اِذَا فَعَلُوۡا فَاحِشَۃً  قَالُوۡا وَجَدۡنَا عَلَیۡہَاۤ  اٰبَآءَنَا وَ اللّٰہُ اَمَرَنَا بِہَا ؕ قُلۡ اِنَّ اللّٰہَ  لَا  یَاۡمُرُ  بِالۡفَحۡشَآءِ ؕ اَتَقُوۡلُوۡنَ عَلَی اللّٰہِ  مَا  لَا  تَعۡلَمُوۡنَ ﴿۲۸﴾', 'اور یہ لوگ جب کوئی بے حیائی کا کام کرتے ہیں تو کہتے ہیں کہ ہم نے اپنے بزرگوں کو اسی طرح کرتے دیکھا ہے اور اللہ نے بھی ہم کو یہی حکم دیا ہے کہدو کہ اللہ بے حیائی کے کام کرنے کا تو حکم نہیں دیتا کیا تم اللہ کی نسبت ایسی بات کہتے ہو جس کا تمہیں علم نہیں۔', 'اور جب کرتے ہیں کوئی برا کام تو کہتے ہیں کہ ہم نے دیکھا اسی طرح کرتے اپنے باپ دادوں کو اور اللہ نے بھی ہم کو یہ حکم کیا ہے تو کہہ دے کہ اللہ حکم نہیں کرتا برے کام کا کیوں لگاتے ہو  اللہ کے ذمہ وہ باتیں جو تم کو معلوم نہیں [۲۹]', 'And when they commit a Fahisha (evil deed, going round the Kabah in naked state, every kind of unlawful sexual intercourse, etc.), they say: \"We found our fathers doing it, and Allah has commanded us of it.\" Say: \"Nay, Allah never commands of Fahisha. Do you say of Allah what you know not?', 'When they do a shameful act, they say, “We have found our fathers doing it, and Allah has ordered us to do so.” Say, “Allah never orders anything shameful. Do you say about Allah what you do not know?”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(983, 7, 29, 3, 10, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قُلۡ اَمَرَ رَبِّیۡ  بِالۡقِسۡطِ ۟ وَ اَقِیۡمُوۡا وُجُوۡہَکُمۡ عِنۡدَ کُلِّ مَسۡجِدٍ  وَّ ادۡعُوۡہُ مُخۡلِصِیۡنَ لَہُ  الدِّیۡنَ ۬ؕ کَمَا بَدَاَکُمۡ تَعُوۡدُوۡنَ ﴿ؕ۲۹﴾', 'کہدو کہ میرے پروردگار نے تو انصاف کرنے کا حکم دیا ہے اور یہ کہ ہر نماز کے وقت سیدھا قبلے کی طرف رخ کیا کرو۔ اور صرف اسی کی عبادت کرو اور اسی کو پکارو۔ اس نے جس طرح تم کو ابتدا میں پیدا کیا تھا اسی طرح تم پھر پیدا ہو گے۔', 'تو کہہ دے کہ میرے رب نے حکم کر دیا ہے انصاف کا [۳۰] اور سیدھے کرو اپنے منہ ہر نماز کے وقت اور پکارو اسکو خالص اس کے فرمانبردار ہو کر [۳۱] جیسا تم کو پہلے پیدا کیا دوسری بار بھی پیدا ہو گے [۳۲]', 'Say (O Muhammad SAW): My Lord has commanded justice and (said) that you should face Him only (i.e. worship none but Allah and face the Qiblah, i.e. the Kabah at Makkah during prayers) in each and every place of worship, in prayers (and not to face other false deities and idols), and invoke Him only making your religion sincere to Him by not joining in worship any partner to Him and with the intention that you are doing your deeds for Allahs sake only. As He brought you (into being) in the beginning, so shall you be brought into being (on the Day of Resurrection) (in two groups, one as a blessed one (believers), and the other as a wretched one (disbelievers)).', 'Say, “My Lord has ordered me to do justice.”Set your faces aright on each occasion of prostration, and pray to Him with pure faith in Him. Just as He has originated you, so you will be raised again.'),
(984, 7, 30, 3, 10, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'فَرِیۡقًا ہَدٰی وَ فَرِیۡقًا حَقَّ عَلَیۡہِمُ الضَّلٰلَۃُ ؕ اِنَّہُمُ اتَّخَذُوا الشَّیٰطِیۡنَ اَوۡلِیَآءَ مِنۡ دُوۡنِ اللّٰہِ وَ یَحۡسَبُوۡنَ  اَنَّہُمۡ مُّہۡتَدُوۡنَ ﴿۳۰﴾', 'ایک فریق کو تو اس نے ہدایت دی اور ایک فریق پر گمراہی ثابت ہو چکی۔ ان لوگوں نے اللہ کو چھوڑ کر شیطانوں کو رفیق بنا لیا اور سمجھتے یہ ہیں کہ ہدایت یاب ہیں۔', 'ایک فرقہ کو ہدایت کی اور ایک فرقہ پر مقرر ہو چکی گمراہی انہوں نے بنایا شیطانوں کو رفیق اللہ کو چھوڑ کر اور سمجھتے ہیں کہ وہ ہدایت پر ہیں [۳۳]', 'A group He has guided, and a group deserved to be in error; (because) surely they took the Shayatin (devils) as Auliya (protectors and helpers) instead of Allah, and consider that they are guided.', 'He has led a group to guidance; and established for another group is misguidance. Indeed, they have taken the devils for their friends, instead of Allah, and they think that they are on the right path.'),
(985, 7, 31, 3, 10, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'یٰبَنِیۡۤ  اٰدَمَ خُذُوۡا زِیۡنَتَکُمۡ عِنۡدَ کُلِّ مَسۡجِدٍ  وَّ کُلُوۡا وَ اشۡرَبُوۡا وَ لَا  تُسۡرِفُوۡا ۚ اِنَّہٗ لَا  یُحِبُّ الۡمُسۡرِفِیۡنَ ﴿٪۳۱﴾', 'اے بنی آدم! ہر نماز کے وقت اپنے آپکو مزین کیا کرو اور کھاؤ اور پیئو اور بے جا نہ اڑاؤ کہ اللہ بے جا اڑانے والوں کو دوست نہیں رکھتا۔', 'اے اولاد آدم کی لے لو اپنی آرائش ہر نماز کے وقت اور کھاؤ اور پیئو اور بیجا خرچ نہ کرو اس کو خوش نہیں آتے بیجا خرچ کرنے والے [۳۴]', 'O Children of Adam! Take your adornment (by wearing your clean clothes), while praying and going round (the Tawaf of ) the Kabah, and eat and drink but waste not by extravagance, certainly He (Allah) likes not Al-Musrifoon (those who waste by extravagance).', 'O children of ’Ādam, take on your adornment at every mosque. Eat and drink and do not be extravagant. Surely, He does not like the extravagant.'),
(986, 7, 32, 4, 11, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قُلۡ مَنۡ حَرَّمَ زِیۡنَۃَ اللّٰہِ الَّتِیۡۤ  اَخۡرَجَ لِعِبَادِہٖ  وَ الطَّیِّبٰتِ مِنَ الرِّزۡقِ ؕ قُلۡ ہِیَ لِلَّذِیۡنَ اٰمَنُوۡا فِی الۡحَیٰوۃِ الدُّنۡیَا خَالِصَۃً  یَّوۡمَ الۡقِیٰمَۃِ ؕ  کَذٰلِکَ  نُفَصِّلُ الۡاٰیٰتِ  لِقَوۡمٍ  یَّعۡلَمُوۡنَ ﴿۳۲﴾', 'پوچھو تو کہ جو زینت و آرائش اور کھانے پینے کی پاکیزہ چیزیں اللہ نے اپنے بندوں کے لئے پیدا کی ہیں ان کو حرام کس نے کیا ہے؟ کہدو کہ یہ چیزیں دنیا کی زندگی میں بھی ایمان والوں کے لئے ہیں اور قیامت کے دن صرف انہی کا حصہ ہوں گی۔ اسی طرح اللہ اپنی آیتیں سمجھنے والوں کے لئے کھول کھول کر بیان فرماتا ہے۔', 'تو کہہ کس نے حرام کیا اللہ کی زینت کو جو اس نے پیدا کی اپنے بندوں کے واسطے اور ستھری چیزیں کھانے کی تو کہہ یہ نعمتیں اصل میں ایمان والوں کے واسطے ہیں دنیا کی زندگی میں خالص انہی کے واسطے ہیں قیامت کے دن اسی طرح مفصل بیان کرتے ہیں ہم آیتیں انکے لئے جو سمجھتے ہیں [۳۵]', 'Say (O Muhammad SAW): \"Who has forbidden the adoration with clothes given by Allah, which He has produced for his slaves, and At-Taiyibat (all kinds of Halal (lawful) things) of food?\" Say: \"They are, in the life of this world, for those who believe, (and) exclusively for them (believers) on the Day of Resurrection (the disbelievers will not share them).\" Thus We explain the Ayat (Islamic laws) in detail for people who have knowledge.', 'Say, “Who has prohibited the adornment Allah has brought forth for His servants, and the wholesome things of sustenance?”Say, “They are for the believers during this worldly life (though shared by others), while they are purely for them on the day of Resurrection. This is how We elaborate the verses for people who understand.”'),
(987, 7, 33, 4, 11, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قُلۡ  اِنَّمَا حَرَّمَ رَبِّیَ الۡفَوَاحِشَ مَا ظَہَرَ  مِنۡہَا وَ  مَا بَطَنَ وَ الۡاِثۡمَ وَ الۡبَغۡیَ بِغَیۡرِ الۡحَقِّ وَ اَنۡ تُشۡرِکُوۡا بِاللّٰہِ مَا لَمۡ یُنَزِّلۡ بِہٖ سُلۡطٰنًا وَّ اَنۡ تَقُوۡلُوۡا عَلَی  اللّٰہِ  مَا لَا  تَعۡلَمُوۡنَ ﴿۳۳﴾', 'کہدو کہ میرے پروردگار نے تو بے حیائی کی باتوں کو ظاہر ہوں یا پوشیدہ اور گناہ کو اور ناحق زیادتی کرنے کو حرام کیا ہے۔ اور اسکو بھی کہ تم کسی کو اللہ کا شریک بناؤ جسکی اس نے کوئی سند نازل نہیں کی اور اسکو بھی کہ اللہ کے بارے میں ایسی باتیں کہو جنکا تمہیں کچھ علم نہیں۔', 'تو کہہ دے میرے رب نے حرام کیا ہے صرف بیحیائی کی باتوں کو جو ان میں کھلی ہوئی ہیں اور جو چھپی ہوئی ہیں اور گناہ کو [۳۶] اور ناحق زیادتی کو اور اس بات کو کہ شریک کرو اللہ کا ایسی چیز کو کہ جس کی اس نے سند نہیں اتاری اور اس بات کو کہ لگاؤ اللہ کے ذمہ وہ باتیں جو تم کو معلوم نہیں [۳۷]', 'Say (O Muhammad SAW): \"(But) the things that my Lord has indeed forbidden are AlFawahish (great evil sins, every kind of unlawful sexual intercourse, etc.) whether committed openly or secretly, sins (of all kinds), unrighteous oppression, joining partners (in worship) with Allah for which He has given no authority, and saying things about Allah of which you have no knowledge.\"', 'Say, “My Lord has prohibited only the shameful acts, whether open or secret, and (every) sinful act, and unjust aggression, and that you associate with Allah anything for which He has not sent any authority, and that you attribute to Allah any thing about which you do not have sure knowledge.'),
(988, 7, 34, 4, 11, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ لِکُلِّ اُمَّۃٍ  اَجَلٌ ۚ فَاِذَا  جَآءَ  اَجَلُہُمۡ  لَا یَسۡتَاۡخِرُوۡنَ سَاعَۃً  وَّ لَا یَسۡتَقۡدِمُوۡنَ ﴿۳۴﴾', 'اور ہر ایک امت کے لئے موت کا ایک وقت مقرر ہے۔ جب وہ آ جاتا ہے تو نہ تو ایک گھڑی دیر کر سکتے ہیں اور نہ جلدی ہی کر سکتے ہیں۔', 'اور ہر فرقےکے واسطے ایک وعدہ ہے پھر جب آ پہنچے گا ان کا وعدہ نہ پیچھے سرک سکیں گے ایک گھڑی اور نہ آگے سرک سکیں گے [۳۸]', 'And every nation has its appointed term; when their term is reached, neither can they delay it nor can they advance it an hour (or a moment).', 'For every people there is an appointed time. So, when their appointed time will come, they cannot be late for a moment, nor will they get ahead.'),
(989, 7, 35, 4, 11, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'یٰبَنِیۡۤ  اٰدَمَ  اِمَّا یَاۡتِیَنَّکُمۡ رُسُلٌ مِّنۡکُمۡ یَقُصُّوۡنَ عَلَیۡکُمۡ اٰیٰتِیۡ ۙ فَمَنِ اتَّقٰی وَ اَصۡلَحَ فَلَا خَوۡفٌ عَلَیۡہِمۡ وَ لَا ہُمۡ یَحۡزَنُوۡنَ ﴿۳۵﴾', 'اے بنی آدم ہم تم کو یہ نصیحت ہمیشہ کرتے رہے ہیں کہ جب ہمارے پیغمبر تمہارے پاس آیا کریں اور ہماری آیتیں تم کو سنایا کریں تو ان پر ایمان لایا کرو کہ اب جو شخص ان پر ایمان لا کر اللہ سے ڈرتا رہے گا اور اپنی حالت درست رکھے گا تو ایسے لوگوں کو نہ کچھ خوف ہو گا اور نہ وہ غمناک ہوں گے۔', 'اے اولاد آدم کی اگر آئیں تمہارے پاس رسول تم میں کے کہ سنائیں تم کو آیتیں میری تو جو کوئی ڈرے اور نیکی پکڑے تو نہ خوف ہو گا ان پر اور نہ وہ غمگین ہوں گے', 'O Children of Adam! If there come to you Messengers from amongst you, reciting to you, My Verses, then whosoever becomes pious and righteous, on them shall be no fear, nor shall they grieve.', 'O children of ’Ādam, if messengers from among you come to you conveying My verses to you, then, those who fear Allah and correct themselves will have no fear, nor shall they grieve.'),
(990, 7, 36, 4, 11, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ الَّذِیۡنَ کَذَّبُوۡا بِاٰیٰتِنَا وَ اسۡتَکۡبَرُوۡا عَنۡہَاۤ  اُولٰٓئِکَ اَصۡحٰبُ النَّارِ ۚ ہُمۡ فِیۡہَا خٰلِدُوۡنَ ﴿۳۶﴾', 'اور جنہوں نے ہماری آیتوں کو جھٹلایا اور ان سے سرتابی کی وہی دوزخی ہیں کہ ہمیشہ اس میں جلتے رہیں گے۔', 'اور جنہوں نے جھٹلایا ہماری آیتوں کو اور تکبر کیا ان سے وہی ہیں دوزخ میں رہنے والے وہ اسی میں ہمیشہ رہیں گے [۳۹]', 'But those who reject Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) and treat them with arrogance, they are the dwellers of the (Hell) Fire, they will abide therein forever.', 'Those who reject Our verses and stand arrogant against them, - they are the inmates of the Fire. There they shall live forever.'),
(991, 7, 37, 4, 11, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'فَمَنۡ اَظۡلَمُ مِمَّنِ افۡتَرٰی عَلَی اللّٰہِ  کَذِبًا اَوۡ کَذَّبَ بِاٰیٰتِہٖ ؕ اُولٰٓئِکَ یَنَالُہُمۡ نَصِیۡبُہُمۡ مِّنَ الۡکِتٰبِ ؕ حَتّٰۤی  اِذَا جَآءَتۡہُمۡ  رُسُلُنَا یَتَوَفَّوۡنَہُمۡ ۙ قَالُوۡۤا اَیۡنَ مَا  کُنۡتُمۡ تَدۡعُوۡنَ مِنۡ دُوۡنِ اللّٰہِ ؕ قَالُوۡا ضَلُّوۡا عَنَّا وَ شَہِدُوۡا عَلٰۤی اَنۡفُسِہِمۡ  اَنَّہُمۡ  کَانُوۡا کٰفِرِیۡنَ ﴿۳۷﴾', 'پس اس سے زیادہ ظالم کون جو اللہ پر جھوٹ باندھے یا اسکی آیتوں کو جھٹلائے۔ انکو ان کے نصیب کا لکھا ملتا ہی رہے گا۔ یہاں تک کہ جب انکے پاس ہمارے بھیجے ہوئے فرشتے جان نکالنے آئیں گے۔ تو کہیں گے کہ جنکو تم اللہ کے سوا پکارا کرتے تھے۔ وہ اب کہاں ہیں؟ وہ کہیں گے کہ وہ ہم سے گم ہو گئے اور اقرار کریں گے کہ بیشک وہ کافر تھے۔', 'پھر اس سے زیادہ ظالم کون جو بہتان باندھے اللہ پر جھوٹا یا جھٹلائے اسکے حکموں کو [۴۰] وہ لوگ ہیں کہ ملے گا ان کو جو انکا حصہ لکھا ہوا ہے کتاب میں [۴۱] یہاں تک کہ جب پہنچیں ان کے پاس ہمارے بھیجے ہوئے انکی جان لینے کو تو کہیں کیا ہوئے وہ جن کو تم پکارا کرتے تھے سوا اللہ کے بولیں گے وہ ہم سےکھوئے گئے اور اقرار کر لیں گے اپنے اوپر کہ بیشک وہ کافر تھے [۴۲]', 'Who is more unjust than one who invents a lie against Allah or rejects His Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.)? For such their appointed portion (good things of this worldly life and their period of stay therein) will reach them from the Book (of Decrees) until, when Our Messengers (the angel of death and his assistants) come to them to take their souls, they (the angels) will say: \"Where are those whom you used to invoke and worship besides Allah,\" they will reply, \"They have vanished and deserted us.\" And they will bear witness against themselves, that they were disbelievers.', 'So, who is more unjust than the one who coins a lie against Allah or rejects His signs? They shall receive their share from that (sustenance) which is written (for them in their destiny) until, when Our envoys (angels) shall come to them to take their souls away, they (the angels) will say, “Where are those (so-called gods) whom you used to invoke besides Allah?” They (the unbelievers) will say, “They all have vanished from us”, and they shall testify against themselves that they were unbelievers.'),
(992, 7, 38, 4, 11, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَ ادۡخُلُوۡا فِیۡۤ  اُمَمٍ قَدۡ خَلَتۡ مِنۡ قَبۡلِکُمۡ مِّنَ الۡجِنِّ وَ الۡاِنۡسِ فِی النَّارِ ؕ کُلَّمَا دَخَلَتۡ اُمَّۃٌ  لَّعَنَتۡ اُخۡتَہَا ؕ حَتّٰۤی اِذَا ادَّارَکُوۡا فِیۡہَا جَمِیۡعًا ۙ قَالَتۡ اُخۡرٰىہُمۡ  لِاُوۡلٰىہُمۡ رَبَّنَا ہٰۤؤُلَآءِ اَضَلُّوۡنَا فَاٰتِہِمۡ عَذَابًا ضِعۡفًا مِّنَ النَّارِ ۬ؕ قَالَ لِکُلٍّ ضِعۡفٌ وَّ لٰکِنۡ  لَّا  تَعۡلَمُوۡنَ ﴿۳۸﴾', 'تو اللہ فرمائے گا کہ جنوں اور انسانوں کی جو جماعتیں تم سے پہلے ہو گذری ہیں ان ہی کے ساتھ تم بھی داخل جہنم ہو جاؤ۔ جب ایک جماعت وہاں جا داخل ہو گی تو اپنے جیسی دوسری جماعت پر لعنت کریگی۔ یہاں تک کہ جب سب اس میں داخل ہو جائیں گے تو پچھلی جماعت پہلی کی نسبت کہے گی کہ اے پروردگار ان ہی لوگوں نے ہم کو گمراہ کیا تھا تو انکو آتش جہنم کا دگنا عذاب دے اللہ فرمائے گا کہ تم سب کو دگنا عذاب دیا جائے گا مگر تم نہیں جانتے۔', 'فرمائے گا داخل ہو جاؤ ہمراہ اور امتوں کے جو تم سے پہلے ہو چکی ہیں جن اور آدمیوں میں سے دوزخ کے اندر [۴۳] جب داخل ہو گی ایک امت تو لعنت کرے گی دوسری امت کو [۴۴] یہاں تک کہ جب گر چکیں گے اس میں سارے تو کہیں گے انکے پچھلے پہلوں کو اے رب ہمارے ہم کو انہی نے گمراہ کیا سو تو انکو دے دونا عذاب آگ کا فرمائے گا کہ دونوں کو دو گنا ہے لیکن تم نہیں جانتے [۴۵]', '(Allah) will say: \"Enter you in the company of nations who passed away before you, of men and jinns, into the Fire.\" Every time a new nation enters, it curses its sister nation (that went before), until they will be gathered all together in the Fire. The last of them will say to the first of them: \"Our Lord! These misled us, so give them a double torment of the Fire.\" He will say: \"For each one there is double (torment), but you know not.\"', 'He (Allah) will say, “Enter the Fire along with the peoples who passed before you from the Jinn and the human beings.” Whenever a group will enter it, they will curse their fellows, until when all of them will have joined each other in it, the latter ones will say about the former ones “Our Lord, they misguided us; so, give them a double punishment of the Fire.” He will say, “For each there is a double, but you do not know.”'),
(993, 7, 39, 4, 11, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ قَالَتۡ اُوۡلٰىہُمۡ لِاُخۡرٰىہُمۡ فَمَا کَانَ لَکُمۡ عَلَیۡنَا مِنۡ فَضۡلٍ فَذُوۡقُوا الۡعَذَابَ بِمَا کُنۡتُمۡ تَکۡسِبُوۡنَ ﴿٪۳۹﴾', 'اور پہلی جماعت پچھلی سے کہے گی کہ تم کو ہم پر کچھ بھی فضیلت نہ ہوئی تو جو عمل تم کیا کرتے تھے اسکے بدلے میں عذاب کے مزے چکھو۔', 'اور کہیں گے ان کے پہلے پچھلوں کو پس کچھ نہ ہوئی تم کو ہم پر بڑائی اب چکھو عذاب بسبب اپنی کمائی کے [۴۶]', 'The first of them will say to the last of them: \"You were not better than us, so taste the torment for what you used to earn.\"', 'The former ones will say to the latter ones, “So, you have no privilege against us. Now, taste the punishment for what you have been earning.”'),
(994, 7, 40, 5, 12, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'اِنَّ الَّذِیۡنَ  کَذَّبُوۡا بِاٰیٰتِنَا وَ اسۡتَکۡبَرُوۡا عَنۡہَا لَا تُفَتَّحُ لَہُمۡ  اَبۡوَابُ السَّمَآءِ  وَ لَا یَدۡخُلُوۡنَ الۡجَنَّۃَ حَتّٰی یَلِجَ الۡجَمَلُ فِیۡ سَمِّ الۡخِیَاطِ ؕ وَ کَذٰلِکَ نَجۡزِی الۡمُجۡرِمِیۡنَ ﴿۴۰﴾', 'جن لوگوں نے ہماری آیتوں کو جھٹلایا اور ان سے سرتابی کی ان کے لئے نہ آسمان کے دروازے کھولے جائیں گے اور نہ وہ بہشت میں داخل ہوں گے یہاں تک کہ اونٹ سوئی کے ناکے میں سے نکل جائے اور گنہگاروں کو ہم ایسی ہی سزا دیا کرتے ہیں۔', 'بیشک جنہوں نے جھٹلایا ہماری آیتوں کو اور ان کے مقابلہ میں تکبر کیا نہ کھولے جائیں گے انکے لئےدروازے آسمان کے [۴۷] اور نہ داخل ہوں گے جنت میں یہاں تک کہ گھس جائے اونٹ سوئی کے ناکے میں [۴۸] اور ہم یوں بدلا دیتے ہیں گنہگاروں کو', 'Verily, those who belie Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) and treat them with arrogance, for them the gates of heaven will not be opened, and they will not enter Paradise until the camel goes through the eye of the needle (which is impossible). Thus do We recompense the Mujrimoon (criminals, polytheists, sinners, etc.).', 'Surely, those who have rejected Our signs and stood arrogant against them, the gates of the heavens shall not be opened for them, and they shall not enter Paradise unless a camel passes through the eye of a needle. This is how We recompense the sinners.'),
(995, 7, 41, 5, 12, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'لَہُمۡ مِّنۡ جَہَنَّمَ مِہَادٌ  وَّ مِنۡ فَوۡقِہِمۡ غَوَاشٍ ؕ وَ کَذٰلِکَ نَجۡزِی الظّٰلِمِیۡنَ ﴿۴۱﴾', 'ایسے لوگوں کے لئے نیچے بچھونا بھی آتش جہنم کا ہوگا اور اوپر سے اوڑھنا بھی اسی کا اور ظالموں کو ہم ایسی ہی سزا دیا کرتے ہیں۔', 'انکے واسطے دوزخ کا بچھونا ہے اور اوپر سے اوڑھنا [۴۹] اور ہم یوں بدلا دیتے ہیں ظالموں کو', 'Theirs will be a bed of Hell (Fire), and over them coverings (of Hell-fire). Thus do We recompense the Zalimoon (polytheists and wrongdoers, etc.).', 'For them there is a bed from the Jahannam, and over them there are coverings. This is how We recompense the transgressors.'),
(996, 7, 42, 5, 12, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ لَا نُکَلِّفُ نَفۡسًا اِلَّا وُسۡعَہَاۤ ۫ اُولٰٓئِکَ اَصۡحٰبُ  الۡجَنَّۃِ ۚ ہُمۡ   فِیۡہَا خٰلِدُوۡنَ ﴿۴۲﴾', 'اور جو لوگ ایمان لائے اور عمل نیک کرتے رہے اور ہم کسی شخص کو اسکی طاقت سے زیادہ ذمہ دار بناتے ہی نہیں ایسے ہی لوگ اہل بہشت ہیں کہ اس میں ہمیشہ رہیں گے۔', 'اور جو ایمان لائے اور کیں نیکیاں ہم بوجھ نہیں رکھتے کسی پر مگر اس کی طاقت کے موافق وہی ہیں جنت میں رہنے والے وہ اسی میں ہمیشہ رہیں گے [۵۰]', 'But those who believed (in the Oneness of Allah - Islamic Monotheism), and worked righteousness - We tax not any person beyond his scope, such are the dwellers of Paradise. They will abide therein.', 'Those who believe and do good deeds,-We do not obligate anyone beyond his capacity-they are the people of Paradise; they shall remain there for ever.'),
(997, 7, 43, 5, 12, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ نَزَعۡنَا مَا فِیۡ صُدُوۡرِہِمۡ مِّنۡ غِلٍّ تَجۡرِیۡ مِنۡ تَحۡتِہِمُ الۡاَنۡہٰرُ ۚ وَ قَالُوا الۡحَمۡدُ لِلّٰہِ الَّذِیۡ ہَدٰىنَا لِہٰذَا ۟ وَ مَا کُنَّا لِنَہۡتَدِیَ لَوۡ لَاۤ  اَنۡ ہَدٰىنَا اللّٰہُ ۚ لَقَدۡ جَآءَتۡ رُسُلُ رَبِّنَا بِالۡحَقِّ ؕ وَ نُوۡدُوۡۤا اَنۡ تِلۡکُمُ الۡجَنَّۃُ  اُوۡرِثۡتُمُوۡہَا بِمَا کُنۡتُمۡ تَعۡمَلُوۡنَ ﴿۴۳﴾', 'اور جو کینے انکے سینوں میں ہوں گے ہم سب نکال ڈالیں گے ان کے محلوں کے نیچے نہریں بہ رہی ہوں گی اور کہیں گے کہ اللہ کا شکر ہے جس نے ہم کو یہاں کا رستہ دکھایا اور اگر اللہ ہم کو رستہ نہ دکھاتا تو ہم رستہ نہ پاسکتے۔ بیشک ہمارے پروردگار کے رسول حق بات لے کر آئے تھے۔ اور اس روز منادی کر دی جائے گی کہ تم ان اعمال کے صلے میں جو دنیا میں کرتے تھے اس بہشت کے مالک بنا دیئے گئے ہو۔', 'اور نکال لیں گے ہم جو کچھ ان کے دلوں میں خفگی تھی [۵۱] بہتی ہوں گی ان کے نیچے نہریں اور وہ کہیں گے شکر اللہ کا جس نے ہم کو یہاں تک پہنچا دیا اور ہم نہ تھے راہ پانے والے اگر نہ ہدایت کرتا ہم کو اللہ بیشک لائے تھے رسول ہمارے رب کے سچی بات [۵۲] اور آواز آئے گی کہ یہ جنت ہے وارث ہوئے تم اس کے بدلے میں اپنے اعمال کے [۵۳]', 'And We shall remove from their breasts any (mutual) hatred or sense of injury (which they had, if at all, in the life of this world); rivers flowing under them, and they will say: \"All the praises and thanks be to Allah, Who has guided us to this, never could we have found guidance, were it not that Allah had guided us! Indeed, the Messengers of our Lord did come with the truth.\" And it will be cried out to them: \"This is the Paradise which you have inherited for what you used to do.\"', 'We will remove whatever amount of malice they had in their hearts. Rivers will flow beneath them, and they will say, “All praise is to Allah who has guided us to this. We would not have been able to find the way, had Allah not guided us. Surely, the messengers of our Lord came with the truth.” Then they will receive a call, “Here is the Paradise which you have been made to inherit because of the deeds you have been doing.”'),
(998, 7, 44, 5, 12, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ نَادٰۤی  اَصۡحٰبُ الۡجَنَّۃِ اَصۡحٰبَ النَّارِ اَنۡ قَدۡ وَجَدۡنَا مَا وَعَدَنَا رَبُّنَا حَقًّا فَہَلۡ وَجَدۡتُّمۡ مَّا وَعَدَ رَبُّکُمۡ حَقًّا ؕ قَالُوۡا نَعَمۡ ۚ فَاَذَّنَ مُؤَذِّنٌۢ بَیۡنَہُمۡ اَنۡ لَّعۡنَۃُ  اللّٰہِ  عَلَی  الظّٰلِمِیۡنَ ﴿ۙ۴۴﴾', 'اور اہل بہشت دوزخیوں سے پکار کر کہیں گے کہ جو وعدہ ہمارے پروردگار نے ہم سے کیا تھا ہم نے تو اسے سچا پالیا۔ بھلا جو وعدہ تمہارے پروردگار نے تم سے کیا تھا تم نے بھی اسے سچا پایا؟ وہ کہیں گے ہاں۔ تو اس وقت ان میں ایک پکارنے والا پکار دے گا کہ بے انصافوں پر اللہ کی لعنت۔', 'اور پکاریں گے جنت والے دوزخ  والوں کو کہ ہم نے پایا جو ہم سے وعدہ کیا تھا ہمارے رب نے سچا سو تم نے بھی پایا اپنے رب کے وعدہ کو سچا وہ کہیں گے کہ ہاں پھر پکارے گا ایک پکارنے والا انکے بیچ میں کہ لعنت ہے اللہ کی ان ظالموں پر', 'And the dwellers of Paradise will call out to the dwellers of the Fire (saying): \"We have indeed found true what our Lord had promised us; have you also found true, what your Lord promised (warnings, etc.)?\" They shall say: \"Yes.\" Then a crier will proclaim between them: \"The Curse of Allah is on the Zalimoon (polytheists and wrongdoers, etc.),\"', 'The inmates of Paradise will call out to the inmates of the Fire: “We have found true what our Lord had promised to us. Have you, too, found true what your Lord had promised?” They will say, “Yes.” Then, an announcer between them will call out, “The curse of Allah is on the wrongdoers'),
(999, 7, 45, 5, 12, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'الَّذِیۡنَ یَصُدُّوۡنَ عَنۡ سَبِیۡلِ اللّٰہِ وَ یَبۡغُوۡنَہَا عِوَجًا ۚ وَ ہُمۡ بِالۡاٰخِرَۃِ کٰفِرُوۡنَ ﴿ۘ۴۵﴾', 'جو اللہ کی راہ سے روکتے اور اس میں کجی ڈھونڈتے اور آخرت سے انکار کرتے تھے۔', 'جو روکتے تھے اللہ کی راہ سے اور ڈھونڈتے تھے اس میں کجی اور وہ آخرت سے منکر تھے [۵۴]', 'Those who hindered (men) from the Path of Allah, and would seek to make it crooked, and they were disbelievers in the Hereafter.', 'who used to turn themselves away from the way of Allah, seeking to make it crooked, while they were the deniers of the Hereafter.”'),
(1000, 7, 46, 5, 12, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ بَیۡنَہُمَا حِجَابٌ ۚ وَ عَلَی الۡاَعۡرَافِ رِجَالٌ یَّعۡرِفُوۡنَ کُلًّۢا بِسِیۡمٰہُمۡ ۚ وَ  نَادَوۡا اَصۡحٰبَ الۡجَنَّۃِ  اَنۡ سَلٰمٌ  عَلَیۡکُمۡ ۟  لَمۡ یَدۡخُلُوۡہَا وَ  ہُمۡ  یَطۡمَعُوۡنَ ﴿۴۶﴾', 'ان دونوں یعنی بہشت اور دوزخ کے درمیان اعراف نام کی ایک دیوار ہو گی اور اعراف پر کچھ آدمی ہوں گے جو سب کو انکی صورتوں سے پہچان لیں گے اور وہ اہل بہشت کو پکار کر کہیں گے کہ تم پر سلامتی ہو یہ لوگ ابھی بہشت میں داخل تو نہیں ہوئے ہونگے مگر امید رکھتے ہوں گے۔', 'اور دونوں کے بیچ میں ہو گی ایک دیوار [۵۵] اور اعراف کے اوپر مرد ہوں گے کہ پہچان لیں گے ہر ایک کو اس کی نشانی سے اور وہ پکاریں گے جنت والوں کو کہ سلامتی ہے تم پر وہ ابھی جنت میں داخل نہیں ہوئے اور وہ امیدوار ہیں [۵۶]', 'And between them will be a barrier screen and on AlAraf (a wall with elevated places) will be men (whose good and evil deeds would be equal in scale), who would recognise all (of the Paradise and Hell people), by their marks (the dwellers of Paradise by their white faces and the dwellers of Hell by their black faces), they will call out to the dwellers of Paradise, \"Salamun Alaikoom\" (peace be on you), and at that time they (men on Al-Araf) will not yet have entered it (Paradise), but they will hope to enter (it) with certainty.', 'Between the two groups there will be a barrier. And on A‘rāf (the Heights) there shall be people who will recognize each group through their signs, and they will call out to the people of Paradise, “Peace on you.” They will not have entered it, yet they will hope to.'),
(1001, 7, 47, 5, 12, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ اِذَا صُرِفَتۡ اَبۡصَارُہُمۡ تِلۡقَآءَ اَصۡحٰبِ النَّارِ ۙ قَالُوۡا رَبَّنَا لَا تَجۡعَلۡنَا مَعَ الۡقَوۡمِ  الظّٰلِمِیۡنَ ﴿٪۴۷﴾', 'اور جب انکی نگاہیں پلٹ کر اہل دوزخ کی طرف جائیں گی تو عرض کریں گے کہ اے ہمارے پروردگار ہم کو ظالم لوگوں کے ساتھ شامل نہ کیجیو۔', 'اور جب پھرے گی ان کی نگاہ دوزخ والوں کی طرف تو کہیں گے اے رب ہمارے مت کر ہم کو گنہگار لوگوں کے ساتھ [۵۷]', 'And when their eyes will be turned towards the dwellers of the Fire, they will say: \"Our Lord! Place us not with the people who are Zalimoon (polytheists and wrongdoers).\"', 'When their eyes will be turned to the people of the Fire, they will say, “Our Lord, do not join us with the unjust people.”'),
(1002, 7, 48, 6, 13, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ نَادٰۤی اَصۡحٰبُ الۡاَعۡرَافِ رِجَالًا یَّعۡرِفُوۡنَہُمۡ بِسِیۡمٰہُمۡ قَالُوۡا مَاۤ  اَغۡنٰی عَنۡکُمۡ جَمۡعُکُمۡ وَ مَا کُنۡتُمۡ تَسۡتَکۡبِرُوۡنَ ﴿۴۸﴾', 'اور اہل اعراف کافر لوگوں کو جنہیں انکی صورتوں سے شناخت کرتے ہونگے پکاریں گے اور کہیں گے کہ آج نہ تو تمہاری جماعت ہی تمہارے کچھ کام آئی اور نہ تمہارا  تکبر ہی سود مند ہوا۔', 'اور پکاریں گے اعراف والے ان لوگوں کو کہ انکو پہچانتے ہیں انکی نشانی سے [۵۸] کہیں گے نہ کام آئی تمہارے جماعت تمہاری اور جو تم تکبر کیا کرتے تھے [۵۹]', 'And the men on AlAraf (the wall) will call unto the men whom they would recognise by their marks, saying: \"Of what benefit to you were your great numbers (and hoards of wealth), and your arrogance against Faith?\"', 'The people of A‘rāf will call out to the people (of Fire) whom they will recognize through their signs: “Your masses were not of any help to you, nor was the arrogance you used to show.'),
(1003, 7, 49, 6, 13, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'اَہٰۤؤُلَآءِ  الَّذِیۡنَ  اَقۡسَمۡتُمۡ  لَا  یَنَالُہُمُ اللّٰہُ بِرَحۡمَۃٍ ؕ اُدۡخُلُوا الۡجَنَّۃَ  لَا خَوۡفٌ عَلَیۡکُمۡ  وَ لَاۤ  اَنۡتُمۡ  تَحۡزَنُوۡنَ ﴿۴۹﴾', 'پھر مومنوں کی طرف اشارہ کر کے کہیں گے کیا یہ وہی لوگ ہیں جنکے بارے میں تم قسمیں کھایا کرتے تھے کہ اللہ اپنی رحمت سے انکی دستگیری نہ کرے گا تو مومنو تم بہشت میں داخل ہو جاؤ تمہیں کچھ خوف نہیں اور نہ تم کو کچھ رنج و غم ہو گا۔', 'اب یہ وہی ہیں کہ تم قسم کھایا کرتے تھے کہ نہ پہنچے گی ان کو اللہ کی رحمت چلے جاؤ جنت میں نہ ڈر ہےتم پر اور نہ تم غمگین ہو گے [۶۰]', 'Are they those, of whom you swore that Allah would never show them mercy. (Behold! It has been said to them): \"Enter Paradise, no fear shall be on you, nor shall you grieve.\"', 'Is it these (people of Paradise) about whom you swore that Allah would not allow His mercy to reach them?” (It will be said to such people,) “Enter Paradise; there will be no fear for you, nor shall you grieve.”'),
(1004, 7, 50, 6, 13, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ نَادٰۤی اَصۡحٰبُ النَّارِ  اَصۡحٰبَ الۡجَنَّۃِ اَنۡ اَفِیۡضُوۡا عَلَیۡنَا مِنَ الۡمَآءِ اَوۡ مِمَّا رَزَقَکُمُ  اللّٰہُ ؕ قَالُوۡۤا  اِنَّ اللّٰہَ حَرَّمَہُمَا عَلَی الۡکٰفِرِیۡنَ ﴿ۙ۵۰﴾', 'اور دوزخی بہشتیوں سے گڑگڑا کر کہیں گے کہ کسی قدر ہم پر پانی بہاؤ یا جو رزق اللہ نے تمہیں عنایت فرمایا ہے اس میں سے کچھ ہمیں بھی دو وہ جواب دیں گے کہ اللہ نے یہ دونوں نعمتیں کافروں پر حرام کر دی ہیں۔', 'اور پکاریں گے دوزخ والے جنت والوں کو کہ بہاؤ ہم پر تھوڑا سا پانی یا کچھ اس میں سے جو روزی تم کو دی اللہ نےکہیں گے اللہ نے ان دونوں کو روک دیا ہے کافروں سے', 'And the dwellers of the Fire will call to the dwellers of Paradise: \"Pour on us some water or anything that Allah has provided you with.\" They will say: \"Both (water and provision) Allah has forbidden to the disbelievers.\"', 'The people of the Fire will call out to the people of Paradise, “Pour on us some water, or some of what Allah has provided you.” They will say, “Allah has prohibited these for disbelievers,'),
(1005, 7, 51, 6, 13, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'الَّذِیۡنَ اتَّخَذُوۡا دِیۡنَہُمۡ لَہۡوًا وَّ لَعِبًا وَّ غَرَّتۡہُمُ الۡحَیٰوۃُ الدُّنۡیَا ۚ فَالۡیَوۡمَ نَنۡسٰہُمۡ  کَمَا نَسُوۡا لِقَآءَ یَوۡمِہِمۡ ہٰذَا ۙ وَ مَا  کَانُوۡا بِاٰیٰتِنَا  یَجۡحَدُوۡنَ ﴿۵۱﴾', 'جنہوں نے اپنے دین کو تماشا اور کھیل بنا رکھا تھا اور دنیا کی زندگی نے انکو دھوکے میں ڈال رکھا تھا۔ تو جس طرح یہ لوگ اپنے اس دن کے آنے کو بھولے ہوئے اور ہماری آیتوں سے منکر ہو رہے تھے اسی طرح آج ہم بھی انہیں بھلا دیں گے۔', 'جنہوں نے ٹھہرایا اپنا دین تماشا اور کھیل اور دھوکے میں ڈالا ان کو دنیا کی زندگی نے سو آج ہم انکو بھلا دیں گے جیسا انہوں نے بھلا دیا اس دن کے ملنے کو اور جیسا کہ وہ ہماری آیتوں سےمنکر تھے [۶۱]', '\"Who took their religion as an amusement and play, and the life of the world deceived them.\" So this Day We shall forget them as they forgot their meeting of this Day, and as they used to reject Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.).', 'who had taken their faith as play and a game, and the worldly life had deceived them.” So, We shall forget them today, as they had forgotten to face this day of theirs, and as they used to deny Our signs.'),
(1006, 7, 52, 6, 13, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ لَقَدۡ جِئۡنٰہُمۡ بِکِتٰبٍ فَصَّلۡنٰہُ عَلٰی عِلۡمٍ ہُدًی وَّ رَحۡمَۃً  لِّقَوۡمٍ  یُّؤۡمِنُوۡنَ ﴿۵۲﴾', 'اور ہم نے انکے پاس کتاب پہنچا دی ہے جسکو علم و دانش کے ساتھ کھول کھول کر بیان کر دیا ہے اور وہ مومن لوگوں کے لئے ہدایت اور رحمت ہے۔', 'اور ہم نے ان لوگوں کے پاس پہنچا دی ہے کتاب جس کو مفصل بیان کیا ہے ہم نے خبرداری سے راہ دکھانے والی اور رحمت ہے ایمان والوں کے لئے [۶۲]', 'Certainly, We have brought to them a Book (the Quran) which We have explained in detail with knowledge, - a guidance and a mercy to a people who believe.', 'Surely We have brought them a book that We have elaborated with knowledge, as guidance and mercy for a people who believe.'),
(1007, 7, 53, 6, 13, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'ہَلۡ یَنۡظُرُوۡنَ  اِلَّا تَاۡوِیۡلَہٗ ؕ یَوۡمَ یَاۡتِیۡ تَاۡوِیۡلُہٗ یَقُوۡلُ الَّذِیۡنَ نَسُوۡہُ مِنۡ قَبۡلُ قَدۡ جَآءَتۡ رُسُلُ رَبِّنَا بِالۡحَقِّ ۚ فَہَلۡ لَّنَا مِنۡ شُفَعَآءَ  فَیَشۡفَعُوۡا  لَنَاۤ  اَوۡ  نُرَدُّ فَنَعۡمَلَ غَیۡرَ الَّذِیۡ کُنَّا نَعۡمَلُ ؕ قَدۡ خَسِرُوۡۤا اَنۡفُسَہُمۡ وَ ضَلَّ عَنۡہُمۡ مَّا کَانُوۡا  یَفۡتَرُوۡنَ ﴿٪۵۳﴾', 'کیا یہ لوگ اسکے مضمون ظاہر ہونے کے منتظر ہیں۔ جس دن اس کا مضمون ظاہر ہو جائے گا۔ تو جو لوگ اسکو پہلے سے بھولے ہوئے ہونگے وہ بول اٹھیں گے کہ بیشک ہمارے پروردگار کے رسول حق لے کر آئے تھے بھلا آج ہمارے کوئی سفارشی ہیں کہ ہماری سفارش کریں یا ہم دنیا میں پھر لوٹا دیئے جائیں کہ جو عمل بد ہم پہلے کرتے تھے۔ وہ نہ کریں بلکہ انکے سوا دوسرے عمل کریں۔ بیشک ان لوگوں نے اپنا نقصان کیا اور جو کچھ یہ افترا کیا کرتے تھے ان سے سب جاتا رہا۔', 'کیا اب اسی کے منتظر ہیں کہ اس کا مضمون ظاہر ہو جائے جس دن ظاہر ہو جائے گا اس کا مضمون کہنے لگیں گے وہ لوگ جو اس کو بھول رہے تھے پہلےسے بیشک لائے تھے ہمارے رب کے رسول سچی بات سو اب کوئی ہماری سفارش والے ہیں تو ہماری سفارش کریں یا ہم لوٹا دیے جائیں تو ہم عمل کریں خلاف اس کےجو ہم کر رہے تھے بیشک تباہ کیا انہوں نے اپنے آپ کو اور گم ہو جائے گا ان  سے جو وہ افترا کیا کرتے تھے [۶۳]', 'Await they just for the final fulfillment of the event? On the Day the event is finally fulfilled (i.e. the Day of Resurrection), those who neglected it before will say: \"Verily, the Messengers of our Lord did come with the truth, now are there any intercessors for us that they might intercede on our behalf? Or could we be sent back (to the first life of the world) so that we might do (good) deeds other than those (evil) deeds which we used to do?\" Verily, they have lost their ownselves (i.e. destroyed themselves) and that which they used to fabricate (invoking and worshipping others besides Allah) has gone away from them.', 'They are waiting for nothing but its final result (i.e. the punishment promised in the Qur’ān). The day when its final result will come, those who had ignored it earlier will say, “Surely, the messengers of our Lord had come with truth. So, are there any intercessors for us who could intercede in our favor? Or, could we be sent back, so that we might do contrary to what we used to do?” Indeed, they have put their selves to loss, and vanished from them all that they used to fabricate.'),
(1008, 7, 54, 7, 14, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'اِنَّ رَبَّکُمُ اللّٰہُ الَّذِیۡ خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ فِیۡ سِتَّۃِ اَیَّامٍ ثُمَّ اسۡتَوٰی عَلَی الۡعَرۡشِ ۟ یُغۡشِی الَّیۡلَ النَّہَارَ یَطۡلُبُہٗ حَثِیۡثًا ۙ وَّ الشَّمۡسَ وَ الۡقَمَرَ وَ النُّجُوۡمَ مُسَخَّرٰتٍۭ بِاَمۡرِہٖ ؕ اَلَا لَہُ  الۡخَلۡقُ وَ الۡاَمۡرُ ؕ تَبٰرَکَ اللّٰہُ رَبُّ الۡعٰلَمِیۡنَ ﴿۵۴﴾', 'کچھ شک نہیں کہ تمہارا پروردگار اللہ ہی ہے جس نے آسمانوں اور زمین کو چھ دن میں پیدا کیا پھر عرش پر جلوہ افروز ہوا وہی رات کو دن کا لباس پہناتا ہے کہ وہ اسکے پیچھے دوڑتا چلا آتا ہے اور اسی نے سورج اور چاند اور ستاروں کو پیدا کیا سب اسکے حکم کے مطابق کام میں لگے ہوئے ہیں۔ دیکھو سب مخلوق بھی اسی کی ہے اور حکم بھی اسی کا ہے اللہ رب العالمین بڑی برکت والا ہے۔', 'بیشک تمہارا رب اللہ ہے جس نے پیدا کئے آسمان اور زمین [۶۴] چھ دن میں [۶۵] پھر قرار پکڑا عرش پر [۶۶] اوڑھاتا ہے رات پر دن کہ وہ اسکے پیچھے لگا آتا ہے دوڑتا ہوا اور پیدا کئے سورج اور چاند اور تارے [۶۷] تابعدار اپنے حکم کے [۶۸] سن لو اسی کا کام ہے پیدا کرنا اور حکم فرمانا بڑی برکت والا ہے اللہ جو رب ہے سارے جہان کا [۶۹]', 'Indeed your Lord is Allah, Who created the heavens and the earth in Six Days, and then He Istawa (rose over) the Throne (really in a manner that suits His Majesty). He brings the night as a cover over the day, seeking it rapidly, and (He created) the sun, the moon, the stars subjected to His Command. Surely, His is the Creation and Commandment. Blessed be Allah, the Lord of the Alameen (mankind, jinns and all that exists)!', 'Surely, your Lord is Allah who created the heavens and the earth in six days, then He positioned himself on the Throne. He covers the day with the night that pursues it swiftly. (He created) the sun and the moon and the stars, subjugated to His command. Lo! To Him alone belong the creation and the command. Glorious is Allah, the Lord of all the worlds.'),
(1009, 7, 55, 7, 14, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'اُدۡعُوۡا رَبَّکُمۡ  تَضَرُّعًا  وَّ خُفۡیَۃً ؕ اِنَّہٗ  لَا یُحِبُّ  الۡمُعۡتَدِیۡنَ ﴿ۚ۵۵﴾', 'لوگو اپنے پروردگار سے عاجزی سے اور چپکے چپکے دعائیں مانگا کرو وہ حد سے بڑھنے والوں کو دوست نہیں رکھتا۔', 'پکارو اپنے رب کو گڑگڑا کر اور چپکے چپکے [۷۰] اس کو خوش نہیں آتے حد سے بڑھنے والے [۷۱]', 'Invoke your Lord with humility and in secret. He likes not the aggressors.', 'Supplicate to your Lord humbly and secretly. Surely, He does not like those who cross the limits.'),
(1010, 7, 56, 7, 14, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ لَا تُفۡسِدُوۡا فِی الۡاَرۡضِ بَعۡدَ اِصۡلَاحِہَا وَ ادۡعُوۡہُ خَوۡفًا وَّ طَمَعًا ؕ اِنَّ رَحۡمَتَ اللّٰہِ قَرِیۡبٌ مِّنَ الۡمُحۡسِنِیۡنَ ﴿۵۶﴾', 'اور ملک میں اصلاح کے بعد خرابی نہ کرنا اور اللہ سے خوف رکھتے ہوئے اور امید رکھ کر دعائیں مانگتے رہنا۔ کچھ شک نہیں کہ اللہ کی رحمت نیکی کرنے والوں سے قریب ہے۔', 'اور مت خرابی ڈالو زمین میں اس کی اصلاح کے بعد اور پکارو اس کو ڈر اور توقع سے [۷۲] بیشک اللہ کی رحمت نزدیک ہے نیک کام کرنے والوں سے', 'And do not do mischief on the earth, after it has been set in order, and invoke Him with fear and hope; Surely, Allahs Mercy is (ever) near unto the gooddoers.', 'Do not make mischief on the earth after it has been set in order. Supplicate Him in fear and hope. Surely, the mercy of Allah is close to those who are good in their deeds.'),
(1011, 7, 57, 7, 14, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ ہُوَ الَّذِیۡ یُرۡسِلُ الرِّیٰحَ بُشۡرًۢا بَیۡنَ یَدَیۡ رَحۡمَتِہٖ ؕ حَتّٰۤی  اِذَاۤ   اَقَلَّتۡ  سَحَابًا ثِقَالًا سُقۡنٰہُ لِبَلَدٍ مَّیِّتٍ فَاَنۡزَلۡنَا بِہِ الۡمَآءَ فَاَخۡرَجۡنَا بِہٖ مِنۡ کُلِّ الثَّمَرٰتِ ؕ کَذٰلِکَ نُخۡرِجُ الۡمَوۡتٰی لَعَلَّکُمۡ  تَذَکَّرُوۡنَ ﴿۵۷﴾', 'اور وہی تو ہے جو اپنی رحمت یعنی بارش سے پہلے ہواؤں کو خوشخبری بنا کر بھیجتا ہے۔ یہاں تک کہ جب وہ بھاری بھاری بادلوں کو اٹھا لاتی ہیں تو ہم اس کو ایک مری ہوئی بستی کی طرف ہانک دیتے ہیں۔ پھر بادل سے بارش برساتے ہیں پھر بارش سے ہر طرح کے پھل پیدا کرتے ہیں اسی طرح ہم مردوں کو زمین سے زندہ کر کے باہر نکالیں گے۔ یہ آیات اس لئے بیان کی جاتی ہیں تاکہ تم نصیحت حاصل کرو۔', 'اور وہی ہے کہ چلاتا ہے ہوائیں خوشخبری لانے والی مینہ سے پہلے یہاں تک کہ جب وہ ہوائیں اٹھا لاتی ہیں بھاری بادلوں کو تو ہانک دیتے ہیں ہم اس بادل کو ایک شہر مردہ کی طرف پھر ہم اتارتے ہیں اس بادل سے پانی پھر اس سے نکالتے ہیں سب طرح کے پھل اسی طرح ہم نکالیں گے مردوں کو تاکہ تم غور کرو', 'And it is He Who sends the winds as heralds of glad tidings, going before His Mercy (rain). Till when they have carried a heavyladen cloud, We drive it to a land that is dead, then We cause water (rain) to descend thereon. Then We produce every kind of fruit therewith. Similarly, We shall raise up the dead, so that you may remember or take heed.', 'He is the One who sends the winds carrying good news before His blessings, until when they lift up the heavy clouds, We drive them to a dead land. Then, there We pour down water. Then, We bring forth with it all sorts of fruits. In similar way, We will bring forth all the dead. (All this is being explained to you), so that you may learn a lesson.'),
(1012, 7, 58, 7, 14, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ الۡبَلَدُ الطَّیِّبُ یَخۡرُجُ نَبَاتُہٗ بِاِذۡنِ رَبِّہٖ ۚ وَ الَّذِیۡ خَبُثَ لَا یَخۡرُجُ  اِلَّا نَکِدًا ؕ کَذٰلِکَ نُصَرِّفُ الۡاٰیٰتِ لِقَوۡمٍ یَّشۡکُرُوۡنَ ﴿٪۵۸﴾', 'اور جو زمین پاکیزہ ہے اس میں سے سبزہ بھی پروردگار کے حکم سے نفیس ہی نکلتا ہے اور جو خراب ہے اس میں سے جو کچھ نکلتا ہے ناقص ہوتا ہے۔ اسی طرح ہم آیتوں کو شکرگذار لوگوں کے لئے پھیر پھیر کر بیان کرتے ہیں۔', 'اور جو شہر پاکیزہ ہے اس کا سبزہ نکلتا ہے اس کے رب کے حکم سے اور جو خراب ہے اس میں نہیں نکلتا مگر ناقص یوں پھیر پھیر کر بتلاتے ہیں ہم آیتیں حق ماننے والے لوگوں کو [۷۳]', 'The vegetation of a good land comes forth (easily) by the Permission of its Lord, and that which is bad, brings forth nothing but a little with difficulty. Thus do We explain variously the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) for a people who give thanks.', 'As for a good land, its vegetation comes out with the permission of its Lord. But that which is bad does not grow except what is bad. Thus We alternate the verses in various ways for a people who pay gratitude.'),
(1013, 7, 59, 8, 15, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'لَقَدۡ اَرۡسَلۡنَا نُوۡحًا اِلٰی قَوۡمِہٖ فَقَالَ یٰقَوۡمِ اعۡبُدُوا اللّٰہَ مَا  لَکُمۡ مِّنۡ  اِلٰہٍ غَیۡرُہٗ ؕ اِنِّیۡۤ   اَخَافُ عَلَیۡکُمۡ  عَذَابَ یَوۡمٍ عَظِیۡمٍ ﴿۵۹﴾', 'ہم نے نوح کو انکی قوم کی طرف بھیجا۔ تو انہوں نے ان سے کہا اے میری برادری کے لوگو اللہ کی عبادت کرو اسکے سوا تمہارا کوئی معبود نہیں مجھے تمہارے بارے میں بڑے دن کے عذاب کا بہت ہی ڈر ہے۔', 'بیشک بھیجا ہم نے نوح کو اس کی قوم کی طرف پس اس نے کہا اے میری قوم بندگی کرو اللہ کی کوئی نہیں تمہارا معبود اس کے سوا میں خوف کرتا ہوں تم پر ایک بڑے دن کے عذاب سے', 'Indeed, We sent Nooh (Noah) to his people and he said: \"O my people! Worship Allah! You have no other Ilah (God) but Him. (La ilaha ill-Allah: none has the right to be worshipped but Allah). Certainly, I fear for you the torment of a Great Day!\"', 'Surely We sent NūH to his people. So he said, “O my people, worship Allah. You have no god other than Him. I fear for you the punishment of a great Day.”'),
(1014, 7, 60, 8, 15, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَ الۡمَلَاُ مِنۡ قَوۡمِہٖۤ  اِنَّا لَنَرٰىکَ فِیۡ ضَلٰلٍ  مُّبِیۡنٍ ﴿۶۰﴾', 'تو جو انکی قوم میں سردار تھے وہ کہنے لگے کہ ہم تمہیں کھلی گمراہی میں مبتلا دیکھتے ہیں۔', 'بولے سردار اس کی قوم کے ہم دیکھتے ہیں تجھ کو صریح بہکا ہوا [۷۴]', 'The leaders of his people said: \"Verily, we see you in plain error.\"', 'The chiefs of his people said, “Indeed we see you in an obvious error.”'),
(1015, 7, 61, 8, 15, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَ یٰقَوۡمِ لَیۡسَ بِیۡ ضَلٰلَۃٌ  وَّ لٰکِنِّیۡ رَسُوۡلٌ  مِّنۡ  رَّبِّ  الۡعٰلَمِیۡنَ ﴿۶۱﴾', 'فرمایا اے قوم مجھ میں کسی طرح کی گمراہی نہیں ہے بلکہ میں پروردگار عالم کا پیغمبر ہوں۔', 'بولا اے میری قوم میں ہرگز بہکا نہیں و لیکن میں بھیجا ہوا ہوں جہان کے پروردگار کا', '(Nooh (Noah)) said: \"O my people! There is no error in me, but I am a Messenger from the Lord of the Alameen (mankind, jinns and all that exists)!', 'He said, “O my people, there is no error in me, but I am a messenger from the Lord of all the worlds.'),
(1016, 7, 62, 8, 15, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'اُبَلِّغُکُمۡ رِسٰلٰتِ رَبِّیۡ وَ اَنۡصَحُ لَکُمۡ وَ اَعۡلَمُ مِنَ اللّٰہِ  مَا  لَا  تَعۡلَمُوۡنَ ﴿۶۲﴾', 'تمہیں اپنے  پروردگار کے پیغام پہنچاتا ہوں اور تمہاری خیرخواہی کرتا ہوں اور مجھ کو اللہ کی طرف سے ایسی باتیں معلوم ہیں جن سے تم بے خبر ہو۔', 'پہنچاتا ہوں تم کو پیغام اپنے رب کے اور نصیحت کرتا ہوں تمکو اور جانتا ہوں اللہ کی طرف سے وہ باتیں جو تم نہیں جانتے [۷۵]', '\"I convey unto you the Messages of my Lord and give sincere advice to you. And I know from Allah what you know not.', 'I convey to you the messages of my Lord and wish your betterment, and I know from Allah what you do not know.'),
(1017, 7, 63, 8, 15, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'اَوَ عَجِبۡتُمۡ اَنۡ جَآءَکُمۡ ذِکۡرٌ  مِّنۡ رَّبِّکُمۡ عَلٰی رَجُلٍ مِّنۡکُمۡ لِیُنۡذِرَکُمۡ وَ لِتَتَّقُوۡا وَ لَعَلَّکُمۡ  تُرۡحَمُوۡنَ ﴿۶۳﴾', 'کیا تم کو اس بات سے تعجب ہوا ہے کہ تم میں سے ایک شخص کے ذریعے تمہارے پروردگار کی طرف سے تمہارے پاس نصیحت آئی تاکہ وہ تم کو ڈرائے اور تاکہ تم پرہیزگار بنو اور تاکہ تم پر رحم کیا جائے۔', 'کیا تم کو تعجب ہوا کہ آئی تمہارے پاس نصیحت تمہارے رب کی طرف سے ایک مرد کی زبانی جو تم ہی میں سے  ہے تاکہ وہ تم کو ڈرائے اور تاکہ تم بچو اور تاکہ تم پر رحم ہو [۷۶]', '\"Do you wonder that there has come to you a Reminder from your Lord through a man from amongst you, that he may warn you, so that you may fear Allah and that you may receive (His) Mercy?\"', 'Do you wonder that an advice from your Lord has come to you through a man from among you, so that he may warn you and that you may fear Allah, and that you may be blessed with mercy?”'),
(1018, 7, 64, 8, 15, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'فَکَذَّبُوۡہُ  فَاَنۡجَیۡنٰہُ وَ الَّذِیۡنَ مَعَہٗ فِی الۡفُلۡکِ وَ اَغۡرَقۡنَا الَّذِیۡنَ کَذَّبُوۡا بِاٰیٰتِنَا ؕ اِنَّہُمۡ  کَانُوۡا  قَوۡمًا  عَمِیۡنَ ﴿٪۶۴﴾', 'مگر ان لوگوں نے انکی تکذیب کی۔ تو ہم نے نوح کو اور جو انکے ساتھ کشتی میں سوار تھے انکو تو بچا لیا اور جن لوگوں نے ہماری آیتوں کو جھٹلایا تھا انہیں غرق کر دیا کچھ شک نہیں کہ وہ عقل کے اندھے لوگ تھے۔', 'پھر انہوں نے اس کو جھٹلایا پھر ہم نے بچا لیا اسکو اور انکو کہ جو اسکے ساتھ تھے کشتی میں اور غرق کر دیا انکو جو جھٹلاتے تھے ہماری آیتوں کو بیشک وہ لوگ تھے اندھے [۷۷]', 'But they belied him, so We saved him and those along with him in the ship, and We drowned those who belied Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.). They were indeed a blind people.', 'Then, they accused him of falsehood; so We saved him, and those with him in the Ark, and drowned those who rejected Our signs. Certainly, they were a blind people.'),
(1019, 7, 65, 9, 16, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ اِلٰی عَادٍ  اَخَاہُمۡ ہُوۡدًا ؕ قَالَ یٰقَوۡمِ اعۡبُدُوا اللّٰہَ مَا  لَکُمۡ  مِّنۡ  اِلٰہٍ  غَیۡرُہٗ ؕ اَفَلَا  تَتَّقُوۡنَ ﴿۶۵﴾', 'اور اسی طرح قوم عاد کی طرف انکے بھائی ہود کو بھیجا انہوں نے کہا کہ بھائیو اللہ ہی کی عبادت کرو۔ اسکے سوا تمہارا کوئی معبود نہیں کیا تم ڈرتے نہیں؟', 'اور قوم عاد کی طرف بھیجا انکے بھائی ہود کو [۷۸] بولا اے میری قوم بندگی کرو اللہ کی کوئی نہیں تمہارا معبود اسکے سوا سو کیا تم ڈرتے نہیں [۷۹]', 'And to Ad (people, We sent) their brother Hood. He said: \"O my people! Worship Allah! You have no other Ilah (God) but Him. (La ilaha ill-Allah: none has the right to be worshipped but Allah). Will you not fear (Allah)?\"', 'To ‘Ād, We sent their brother Hūd. He said, “O my people, worship Allah; you have no god other than Him. So, will you not fear Allah?”'),
(1020, 7, 66, 9, 16, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَ الۡمَلَاُ الَّذِیۡنَ  کَفَرُوۡا مِنۡ قَوۡمِہٖۤ  اِنَّا لَنَرٰىکَ فِیۡ سَفَاہَۃٍ  وَّ اِنَّا لَنَظُنُّکَ مِنَ الۡکٰذِبِیۡنَ ﴿۶۶﴾', 'تو انکی قوم کے سردار جو کافر تھے کہنے لگے کہ تم ہمیں احمق نظر آتے ہو اور ہم تمہیں جھوٹا خیال کرتے ہیں۔', 'بولے سردار جو کافر تھے اس کی قوم میں ہم تو دیکھتے ہیں تجھ کو عقل نہیں اور ہم تو تجھ کو جھوٹا گمان کرتے ہیں [۸۰]', 'The leaders of those who disbelieved among his people said: \"Verily, we see you in foolishness, and verily, we think you are one of the liars.\"', 'Said the chiefs of his people who disbelieved, “Indeed, we see you in folly, and we believe you are one of the liars.”'),
(1021, 7, 67, 9, 16, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَ یٰقَوۡمِ لَیۡسَ بِیۡ سَفَاہَۃٌ   وَّ لٰکِنِّیۡ رَسُوۡلٌ مِّنۡ  رَّبِّ  الۡعٰلَمِیۡنَ ﴿۶۷﴾', 'فرمایا اے میری قوم! مجھ میں حماقت کی کوئی بات نہیں ہے بلکہ میں رب العالمین کا پیغمبر ہوں۔', 'بوالا اے میری قوم میں کچھ بےعقل نہیں لیکن میں بھیجا ہوا ہوں پروردگار عالم کا', '(Hood) said: \"O my people! There is no foolishness in me, but (I am) a Messenger from the Lord of the Alameen (mankind, jinns and all that exists)!', 'He said, “O my people, there is no folly in me, but I am a messenger from the Lord of all the worlds.'),
(1022, 7, 68, 9, 16, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'اُبَلِّغُکُمۡ رِسٰلٰتِ رَبِّیۡ وَ اَنَا لَکُمۡ نَاصِحٌ  اَمِیۡنٌ ﴿۶۸﴾', 'میں تمہیں اللہ کے پیغام پہنچاتا ہوں اور تمہارا امانتدار خیرخواہ ہوں۔', 'پہنچاتا ہوں تم کو پیغام اپنے رب کے اور میں تمہارا خیرخواہ ہوں اور اطمینان کے لائق [۸۱]', '\"I convey unto you the Messages of my Lord, and I am a trustworthy adviser (or wellwisher) for you.', 'I convey to you the messages of my Lord; and I am an honest well-wisher for you.'),
(1023, 7, 69, 9, 16, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'اَوَ عَجِبۡتُمۡ اَنۡ جَآءَکُمۡ ذِکۡرٌ مِّنۡ رَّبِّکُمۡ عَلٰی رَجُلٍ مِّنۡکُمۡ لِیُنۡذِرَکُمۡ ؕ وَ اذۡکُرُوۡۤا  اِذۡ  جَعَلَکُمۡ  خُلَفَآءَ مِنۡۢ بَعۡدِ قَوۡمِ نُوۡحٍ وَّ زَادَکُمۡ فِی الۡخَلۡقِ بَصۜۡطَۃً ۚ فَاذۡکُرُوۡۤا اٰلَآءَ اللّٰہِ لَعَلَّکُمۡ تُفۡلِحُوۡنَ ﴿۶۹﴾', 'اور کیا تم کو اس بات سے تعجب ہوا ہے کہ تم میں سے ایک شخص کے ذریعے تمہارے پروردگار کی طرف سے تمہارے پاس نصیحت آئی تاکہ وہ تمہیں ڈرائے۔ اور یاد تو کرو جب اس نے تم کو قوم نوح کے بعد جانشین بنایا اور تم کو پھیلاؤ زیادہ دیا۔ پس اللہ کی نعمتوں کو یاد کرو تاکہ کامیاب ہو جاؤ۔', 'کیا تم کو تعجب ہوا کہ آئی تمہارے پاس نصیحت تمہارے رب کی طرف سے ایک مرد کی زبانی جو تم ہی میں سے ہے تاکہ تمکو ڈرائے اور یاد کرو جبکہ تم کو سردار کر دیا پیچھے قوم نوح کے [۸۲] اور زیادہ کر دیا تمہارے بدن کا پھیلاؤ [۸۳] سو یاد کرو اللہ کےاحسان تاکہ تمہارا بھلا ہو [۸۴]', '\"Do you wonder that there has come to you a Reminder (and an advice) from your Lord through a man from amongst you that he may warn you? And remember that He made you successors after the people of Nooh (Noah), and increased you amply in stature. So remember the graces (bestowed upon you) from Allah, so that you may be successful.\"', 'Do you wonder that an advice from your Lord has come to you through a man from among you, so that he may warn you? And remember when He made you successors after the people of NūH and gave you increased strength in physique. So, be mindful of the bounties of Allah, so that you may be successful.”'),
(1024, 7, 70, 9, 16, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالُوۡۤا اَجِئۡتَنَا لِنَعۡبُدَ اللّٰہَ وَحۡدَہٗ وَ نَذَرَ مَا کَانَ یَعۡبُدُ اٰبَآؤُنَا ۚ فَاۡتِنَا بِمَا تَعِدُنَاۤ  اِنۡ  کُنۡتَ  مِنَ  الصّٰدِقِیۡنَ ﴿۷۰﴾', 'وہ کہنے لگے کیا تم ہمارے پاس اس لئے آئے ہو کہ ہم اکیلے اللہ ہی کی عبادت کریں اور جنکو ہمارے باپ دادا پوجتے چلے آئے ہیں انکو چھوڑ دیں؟ تو اگر سچے ہو تو جس چیز سے ہمیں ڈراتے ہو اسے لے آؤ۔', 'بولےکیا تو اس واسطے ہمارے پاس آیا کہ ہم بندگی کریں اللہ اکیلے کی اور چھوڑ دیں جن کو پوجتے رہے ہمارے باپ دادےپس تو لے آ ہمارے پاس جس چیز سے تو ہم کو ڈراتا ہے اگر تو سچا ہے [۸۵]', 'They said: \"You have come to us that we should worship Allah Alone and forsake that which our fathers used to worship. So bring us that wherewith you have threatened us if you are of the truthful.\"', 'They said, “Have you come to us that we should worship Allah alone and give up what our fathers used to worship? Now, bring upon us that (scourge) with which you threaten us if you are one of the truthful.”'),
(1025, 7, 71, 9, 16, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَ قَدۡ وَقَعَ عَلَیۡکُمۡ مِّنۡ رَّبِّکُمۡ رِجۡسٌ وَّ غَضَبٌ ؕ اَتُجَادِلُوۡنَنِیۡ فِیۡۤ  اَسۡمَآءٍ سَمَّیۡتُمُوۡہَاۤ  اَنۡتُمۡ  وَ اٰبَآؤُکُمۡ مَّا نَزَّلَ اللّٰہُ بِہَا مِنۡ سُلۡطٰنٍ ؕ فَانۡتَظِرُوۡۤا  اِنِّیۡ مَعَکُمۡ  مِّنَ الۡمُنۡتَظِرِیۡنَ ﴿۷۱﴾', 'ہود نے کہا کہ تمہارے پروردگار کی طرف سے تم پر عذاب اور غضب کا نازل ہونا مقرر ہو چکا ہے۔ کیا تم مجھ سے چند ناموں کے بارے میں جھگڑتے ہو جو تم نے اور تمہارے باپ دادا نے اپنی طرف سے رکھ لئے ہیں۔ جنکی اللہ نے کوئی سند نازل نہیں کی۔ تو تم بھی انتظار کرو میں بھی تمہارے ساتھ انتظار کرتا ہوں۔', 'کہا تم پر واقع ہو چکا ہے تمہارے رب کی طرف سے عذاب اور غصہ [۸۶] کیوں جھگڑتے ہو مجھ سے ان ناموں پر کہ رکھ لئے ہیں تم نے اور تمہارے باپ دادوں نے نہیں اتاری اللہ نے ان کی کوئی سند سو منتظر رہو میں بھی تمہارے ساتھ منتظر ہوں [۸۷]', '(Hood) said: \"Torment and wrath have already fallen on you from your Lord. Dispute you with me over names which you have named - you and your fathers, with no authority from Allah? Then wait, I am with you among those who wait.\"', 'He said, “The punishment and the anger from your Lord have fallen upon you. Do you quarrel with me about mere names that you and your fathers have concocted and for which Allah has sent down no authority? So, wait. I am one of those waiting with you.”'),
(1026, 7, 72, 9, 16, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'فَاَنۡجَیۡنٰہُ وَ الَّذِیۡنَ مَعَہٗ بِرَحۡمَۃٍ مِّنَّا وَ قَطَعۡنَا دَابِرَ الَّذِیۡنَ کَذَّبُوۡا بِاٰیٰتِنَا وَ مَا  کَانُوۡا مُؤۡمِنِیۡنَ ﴿٪۷۲﴾', 'پھر ہم نے ہود کو اور جو لوگ انکے ساتھ تھے انکو اپنی مہربانی سے نجات بخشی اور جنہوں نے ہماری آیتوں کو جھٹلایا تھا انکی جڑ کاٹ دی۔ اور وہ ایمان لانے والے تھے ہی نہیں۔', 'پھر ہم نے بچا لیا اس کو اور جو اس کےساتھ تھے اپنی رحمت سے اور جڑ کاٹی ان کی جو جھٹلاتے تھے ہماری آیتوں کو او رنہیں مانتے تھے [۸۸]', 'So We saved him and those who were with him by a Mercy from Us, and We cut the roots of those who belied Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), and they were not believers.', 'So, We saved him and those with him out of mercy from Us, and We eradicated those who rejected Our signs. They were not believers.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1027, 7, 73, 10, 17, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ  اِلٰی ثَمُوۡدَ  اَخَاہُمۡ  صٰلِحًا ۘ قَالَ یٰقَوۡمِ اعۡبُدُوا اللّٰہَ  مَا  لَکُمۡ  مِّنۡ  اِلٰہٍ غَیۡرُہٗ ؕ قَدۡ جَآءَتۡکُمۡ  بَیِّنَۃٌ مِّنۡ رَّبِّکُمۡ ؕ ہٰذِہٖ نَاقَۃُ اللّٰہِ لَکُمۡ اٰیَۃً فَذَرُوۡہَا تَاۡکُلۡ فِیۡۤ  اَرۡضِ اللّٰہِ وَ لَا تَمَسُّوۡہَا بِسُوۡٓءٍ فَیَاۡخُذَکُمۡ عَذَابٌ اَلِیۡمٌ ﴿۷۳﴾', 'اور قوم ثمود کی طرف انکے بھائی صالح کو بھیجا تو صالح نے کہا کہ اے قوم! اللہ ہی کی عبادت کرو اسکے سوا تمہارا کوئی معبود نہیں۔ تمہارے پاس تمہارے پروردگار کی طرف سے ایک معجزہ آ چکا ہے یعنی یہی اللہ کی اونٹنی تمہارے لئے معجزہ ہے۔ تو اسے آزاد چھوڑ دو کہ اللہ کی زمین میں چرتی پھرے اور تم اسے بری نیت سے ہاتھ بھی نہ لگانا۔ ورنہ عذاب الیم تمہیں پکڑ لے گا۔', 'اور ثمود کی طرف بھیجا انکے بھائی صالح کو بولا اے میری قوم بندگی کرو اللہ کی کوئی نہیں تمہارا معبود اسکے سوا تم کو پہنچ چکی ہے دلیل تمہارے رب کی طرف سے [۸۹] یہ اونٹنی اللہ کی ہے تمہارے لئے نشانی سو اس کو چھوڑ دو کہ کھائے اللہ کی زمین میں اور اس کو ہاتھ نہ لگاؤ بری طرح پھر تم کو پکڑے گا عذاب دردناک [۹۰]', 'And to Thamood (people, We sent) their brother Salih (Saleh). He said: \"O my people! Worship Allah! You have no other Ilah (God) but Him. (La ilaha ill-Allah: none has the right to be worshipped but Allah). Indeed there has come to you a clear sign (the miracle of the coming out of a huge shecamel from the midst of a rock) from your Lord. This shecamel of Allah is a sign unto you; so you leave her to graze in Allahs earth, and touch her not with harm, lest a painful torment should seize you.', 'To Thamūd, (We sent) their brother, SāliH. He said, “O my people, worship Allah. You have no god other than Him. There has come to you a clear sign from your Lord. This is the she-camel of Allah, a sign for you. So, leave her to eat on the earth of Allah, and do not touch her with mischief, lest a painful punishment should seize you.'),
(1028, 7, 74, 10, 17, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ اذۡکُرُوۡۤا اِذۡ جَعَلَکُمۡ خُلَفَآءَ مِنۡۢ بَعۡدِ عَادٍ  وَّ بَوَّاَکُمۡ فِی الۡاَرۡضِ تَتَّخِذُوۡنَ مِنۡ سُہُوۡلِہَا قُصُوۡرًا وَّ تَنۡحِتُوۡنَ الۡجِبَالَ بُیُوۡتًا ۚ فَاذۡکُرُوۡۤا اٰلَآءَ اللّٰہِ وَ لَا تَعۡثَوۡا فِی الۡاَرۡضِ مُفۡسِدِیۡنَ ﴿۷۴﴾', 'اور یاد تو کرو جب اس نے تم کو قوم عاد کے بعد سردار بنایا اور زمین پر آباد کیا۔ کہ نرم زمین میں محل تعمیر کرتے ہو اور پہاڑوں کر تراش تراش کر گھر بناتے ہو۔ پس اللہ کی نعمتوں کو یاد کرو اور زمین میں فساد نہ کرتے پھرو۔', 'اور یاد کرو جبکہ تم کو سردار کر دیا عاد کے پیچھے اور ٹھکانہ دیا تم کو زمین میں کہ بناتے ہو نرم زمین میں محل اور تراشتے ہو پہاڑوں کے گھر سو یاد کرو احسان اللہ کے اور مت مچاتے پھرو زمین میں فساد [۹۱]', '\"And remember when He made you successors after Ad (people) and gave you habitations in the land, you build for yourselves palaces in plains, and carve out homes in the mountains. So remember the graces (bestowed upon you) from Allah, and do not go about making mischief on the earth.\"', 'Remember when He made you successors after ‘Ād and lodged you on earth (whereby) you make castles in its plains and hew out the mountains to build houses. So be mindful of the bounties of Allah, and do not go about the earth spreading disorder.”'),
(1029, 7, 75, 10, 17, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَ الۡمَلَاُ الَّذِیۡنَ اسۡتَکۡبَرُوۡا مِنۡ قَوۡمِہٖ لِلَّذِیۡنَ اسۡتُضۡعِفُوۡا لِمَنۡ اٰمَنَ مِنۡہُمۡ اَتَعۡلَمُوۡنَ اَنَّ  صٰلِحًا  مُّرۡسَلٌ  مِّنۡ رَّبِّہٖ ؕ قَالُوۡۤا اِنَّا بِمَاۤ  اُرۡسِلَ بِہٖ مُؤۡمِنُوۡنَ ﴿۷۵﴾', 'تو انکی قوم میں سردار لوگ جو تکبر رکھتے تھے غریب لوگوں سے جو ان میں سے ایمان لے آئے تھے کہنے لگے بھلا تم یقین کرتے ہو کہ صالح اپنے پروردگار کی طرف سے بھیجے گئے ہیں؟ انہوں نے کہا ہاں جو چیز وہ دے کر بھیجے گئے ہیں ہم اس پر بلاشبہ ایمان رکھتے ہیں۔', 'کہنے لگے سردار جو متکبر تھے اس کی قوم میں غریب لوگوں کو کہ جو ان میں ایمان لا چکے تھے کیا تم کو یقین ہے کہ صالح کو بھیجا ہے اس کے رب نے بولے ہم کو تو جو وہ لے کر آیا اس پر یقین ہے', 'The leaders of those who were arrogant among his people said to those who were counted weak - to such of them as believed: \"Know you that Salih (Saleh) is one sent from his Lord.\" They said: \"We indeed believe in that with which he has been sent.\"', 'The haughty chiefs of his people said to those of the oppressed who had believed (in the Messenger), “Do you know for sure that SāliH is a messenger from his Lord?” They said, “Of course, we believe in what he has been sent with.”'),
(1030, 7, 76, 10, 17, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'قَالَ الَّذِیۡنَ اسۡتَکۡبَرُوۡۤا اِنَّا بِالَّذِیۡۤ اٰمَنۡتُمۡ  بِہٖ  کٰفِرُوۡنَ ﴿۷۶﴾', 'تو سرداران مغرور کہنے لگے کہ جس چیز پر تم ایمان لائے ہو ہم تو اسکو نہیں مانتے۔', 'کہنے لگے وہ لوگ جو متکبر تھے جس پر تم کو یقین ہے ہم اسکو نہیں مانتے [۹۲]', 'Those who were arrogant said: \"Verily, we disbelieve in that which you believe in.\"', 'The haughty people said, “As for us, we disbelieve in what you believe.”'),
(1031, 7, 77, 10, 17, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'فَعَقَرُوا النَّاقَۃَ  وَ عَتَوۡا عَنۡ  اَمۡرِ  رَبِّہِمۡ وَ قَالُوۡا یٰصٰلِحُ ائۡتِنَا بِمَا تَعِدُنَاۤ  اِنۡ  کُنۡتَ مِنَ  الۡمُرۡسَلِیۡنَ ﴿۷۷﴾', 'آخر انہوں نے اس اونٹنی کو مار ڈالا اور اپنے پروردگار کے حکم سے سرکشی کی اور کہنے لگے کہ صالح جس چیز سے تم ہمیں ڈراتے تھے اگر تم اللہ کے پیغمبر ہو تو اسے ہم پر لے آؤ۔', 'پھر انہوں نے کاٹ ڈالا اونٹنی کو اور پھر گئے اپنے رب کے حکم سے [۹۳] اور بولے اے صالح لے آ ہم پر جس سے تو ہم کو ڈراتا تھا اگر تو رسول ہے [۹۴]', 'So they killed the shecamel and insolently defied the Commandment of their Lord, and said: \"O Salih (Saleh)! Bring about your threats if you are indeed one of the Messengers (of Allah).\"', 'Then they slaughtered the she-camel and defied the command of their Lord and said, “O SāliH, bring to us what you threaten us with, if you are one of the messengers.'),
(1032, 7, 78, 10, 17, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'فَاَخَذَتۡہُمُ الرَّجۡفَۃُ فَاَصۡبَحُوۡا فِیۡ  دَارِہِمۡ  جٰثِمِیۡنَ ﴿۷۸﴾', 'پس انکو زلزلے نے آ پکڑا سو وہ اپنے گھروں میں اوندھے پڑے رہ گئے۔', 'پس آ پکڑا انکو زلزلہ نے پھر صبح کو رہ گئے اپنے گھر میں اندھے پڑے [۹۵]', 'So the earthquake seized them, and they lay (dead), prostrate in their homes.', 'So, the earthquake seized them, and they were (found dead) in their homes, fallen on their faces.'),
(1033, 7, 79, 10, 17, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'فَتَوَلّٰی عَنۡہُمۡ وَ قَالَ یٰقَوۡمِ لَقَدۡ اَبۡلَغۡتُکُمۡ رِسَالَۃَ رَبِّیۡ وَ نَصَحۡتُ لَکُمۡ  وَ لٰکِنۡ لَّا  تُحِبُّوۡنَ النّٰصِحِیۡنَ ﴿۷۹﴾', 'پھر صالح ان سے ناامید ہو کر پھرے اور کہا کہ میری قوم! میں نے تم کو اللہ کا پیغام پہنچا دیا اور تمہاری خیرخواہی کی مگر تم ایسے ہو کہ خیرخواہوں کو دوست ہی نہیں رکھتے۔', 'پھر صالح الٹا پھرا ان سے اور بولا اے میری قوم میں پہنچا چکا تم کو پیغام اپنے رب کا اور خیرخواہی کی تمہاری لیکن تمکو محبت نہیں خیرخواہوں سے [۹۶]', 'Then he (Salih (Saleh)) turned from them, and said: \"O my people! I have indeed conveyed to you the Message of my Lord, and have given you good advice but you like not good advisers.\"', 'So, he turned away from them and said, “O my people, indeed I have delivered to you the message of my Lord, and wished you betterment, but you do not like the well-wishers.”'),
(1034, 7, 80, 10, 17, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ لُوۡطًا اِذۡ قَالَ لِقَوۡمِہٖۤ اَتَاۡتُوۡنَ الۡفَاحِشَۃَ مَا سَبَقَکُمۡ بِہَا مِنۡ اَحَدٍ مِّنَ  الۡعٰلَمِیۡنَ ﴿۸۰﴾', 'اور اسی طرح جب ہم نے لوط کو پیغمبر بنا کر بھیجا تو اس وقت انہوں نے اپنی قوم سے کہا کہ تم ایسی بے حیائی کا کام کیوں کرتے ہو کہ تم سے پہلے اہل عالم میں سے کسی نے اس طرح کا کام نہیں کیا۔', 'اور بھیجا لوط کو جب کہا اس نے اپنی قوم کو کیا تم کرتے ہو ایسی بے حیائی کہ تم سے پہلے نہیں کیا اس کو کسی نے جہان میں [۹۷]', 'And (remember) Lout (Lot), when he said to his people: \"Do you commit the worst sin such as none preceding you has committed in the Alameen (mankind and jinns)?', 'And (We sent) LūT (Lot) when he said to his people, “Do you commit the shameful act in which nobody in the world has ever preceded you?'),
(1035, 7, 81, 10, 17, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'اِنَّکُمۡ لَتَاۡتُوۡنَ الرِّجَالَ شَہۡوَۃً مِّنۡ دُوۡنِ النِّسَآءِ ؕ بَلۡ  اَنۡتُمۡ  قَوۡمٌ  مُّسۡرِفُوۡنَ ﴿۸۱﴾', 'یعنی خواہش نفسانی پورا کرنے کے لئے عورتوں کو چھوڑ کر مردوں کے پاس آتے ہو۔ حقیقت یہ ہے کہ تم لوگ حد سے نکل جانے والے ہو۔', 'تم تو دوڑتے ہو مردوں پر شہوت کے مارے عورتوں کو چھوڑ کر بلکہ تم لوگ ہو حد سے گذرنے والے [۹۸]', '\"Verily, you practise your lusts on men instead of women. Nay, but you are a people transgressing beyond bounds (by committing great sins).\"', 'You come to men lustfully instead of women. No, you are a people who cross the limits.”'),
(1036, 7, 82, 10, 17, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ مَا کَانَ جَوَابَ قَوۡمِہٖۤ  اِلَّاۤ اَنۡ قَالُوۡۤا اَخۡرِجُوۡہُمۡ مِّنۡ قَرۡیَتِکُمۡ ۚ اِنَّہُمۡ  اُنَاسٌ یَّتَطَہَّرُوۡنَ ﴿۸۲﴾', 'اور ان سے اسکا جواب کچھ نہ بن پڑا اور بولے تو یہ بولے کہ ان لوگوں یعنی لوط اور اسکے گھر والوں کو اپنے گاؤں سے نکال دو کہ یہ لوگ پاک بننا چاہتے ہیں۔', 'اور کچھ جواب نہ دیا اس کی قوم نے مگر یہی کہا کہ نکالو ان کو اپنے شہر سے یہ لوگ بہت ہی پاک رہنا چاہتے ہیں', 'And the answer of his people was only that they said: \"Drive them out of your town, these are indeed men who want to be pure (from sins)!\"', 'The answer of his people was no other than to say, “Expel them from your town. They are a people who pretend too much purity.”'),
(1037, 7, 83, 10, 17, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'فَاَنۡجَیۡنٰہُ وَ اَہۡلَہٗۤ  اِلَّا امۡرَاَتَہٗ ۫ۖ کَانَتۡ مِنَ  الۡغٰبِرِیۡنَ ﴿۸۳﴾', 'تو ہم نے انکو اور انکے گھر والوں کو بچا لیا مگر انکی بیوی نہ بچی کہ وہ پیچھے رہنے والوں میں ہو گئ۔', 'پھر بچا دیا ہم نے اس کو اور اسکے گھر والوں کو مگر اس کی عورت کہ رہ گئ وہاں کے رہنے والوں میں [۹۹]', 'Then We saved him and his family, except his wife; she was of those who remained behind (in the torment).', 'So, We saved him and his family, except his wife. She was one of those who remained behind.'),
(1038, 7, 84, 10, 17, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ  اَمۡطَرۡنَا عَلَیۡہِمۡ  مَّطَرًا ؕ فَانۡظُرۡ  کَیۡفَ کَانَ عَاقِبَۃُ  الۡمُجۡرِمِیۡنَ ﴿٪۸۴﴾', 'اور ہم نے ان پر پتھروں کی بارش برسائی سو دیکھ لو کہ گنہگاروں کا کیسا انجام ہوا۔', 'اور برسایا ہم نے انکے اوپر مینہ یعنی پتھروں کا [۱۰۰] پھر دیکھ کیا ہوا انجام گنہگاروں کا [۱۰۱]', 'And We rained down on them a rain (of stones). Then see what was the end of the Mujrimoon (criminals, polytheists, sinners, etc.).', 'And We rained down upon them a rain. So, look! How was the fate of the sinners!'),
(1039, 7, 85, 11, 0, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ اِلٰی مَدۡیَنَ اَخَاہُمۡ شُعَیۡبًا ؕ قَالَ یٰقَوۡمِ اعۡبُدُوا اللّٰہَ مَا  لَکُمۡ مِّنۡ  اِلٰہٍ غَیۡرُہٗ ؕ قَدۡ جَآءَتۡکُمۡ بَیِّنَۃٌ مِّنۡ رَّبِّکُمۡ فَاَوۡفُوا الۡکَیۡلَ وَ الۡمِیۡزَانَ وَ لَا تَبۡخَسُوا النَّاسَ اَشۡیَآءَہُمۡ وَ لَا تُفۡسِدُوۡا فِی الۡاَرۡضِ بَعۡدَ  اِصۡلَاحِہَا ؕ ذٰلِکُمۡ خَیۡرٌ لَّکُمۡ  اِنۡ کُنۡتُمۡ مُّؤۡمِنِیۡنَ ﴿ۚ۸۵﴾', 'اور مدین کی طرف انکے بھائی شعیب کو بھیجا تو انہوں نے کہا اے قوم! اللہ ہی کی عبادت کرو اسکے سوا تمہار کوئی معبود نہیں۔ تمہارے پاس تمہارے پروردگار کی طرف سے نشانی آچکی ہے تو تم ناپ اور تول پوری کیا کرو اور لوگوں کو چیزیں کم نہ دیا کرو اور زمین میں اصلاح کے بعد خرابی نہ کرو اگر تم صاحب ایمان ہو تو سمجھ لو کہ یہ بات تمہارے حق میں بہتر ہے۔', 'اور مدین کی طرف بھیجا ان کےبھائی شعیب کو [۱۰۲] بولا اے میری قوم بندگی کرو اللہ کی کوئی نہیں تمہارا معبود اسکے سوا تمہارے پاس پہنچ چکی ہے دلیل تمہارے رب کی طرف سے [۱۰۳] سو پوری کرو ماپ اور تول اور مت گھٹا کر دو لوگوں کو ان کی چیزیں اور مت خرابی ڈالو زمین میں اس کی اصلاح کے بعد یہ بہتر ہےتمہارےلئے اگر تم ایمان والے ہو [۱۰۴]', 'And to (the people of) Madyan (Midian), (We sent) their brother Shuaib. He said: \"O my people! Worship Allah! You have no other Ilah (God) but Him. (La ilaha ill-Allah (none has the right to be worshipped but Allah)).\" Verily, a clear proof (sign) from your Lord has come unto you; so give full measure and full weight and wrong not men in their things, and do not mischief on the earth after it has been set in order, that will be better for you, if you are believers.', 'And to Madyan (We sent) their brother Shu‘aib. He said, “O my people, worship Allah. You have no god other than Him. There has come to you a clear sign from your Lord. Give the measure and weight in full, and do not make people short of their things, and do not make mischief on the earth after it has been set in order. That is good for you, if you are believers.'),
(1040, 7, 86, 11, 0, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ لَا تَقۡعُدُوۡا بِکُلِّ صِرَاطٍ تُوۡعِدُوۡنَ وَ تَصُدُّوۡنَ عَنۡ  سَبِیۡلِ اللّٰہِ  مَنۡ  اٰمَنَ بِہٖ وَ تَبۡغُوۡنَہَا عِوَجًا ۚ وَ اذۡکُرُوۡۤا اِذۡ کُنۡتُمۡ قَلِیۡلًا فَکَثَّرَکُمۡ ۪ وَ انۡظُرُوۡا کَیۡفَ  کَانَ عَاقِبَۃُ  الۡمُفۡسِدِیۡنَ ﴿۸۶﴾', 'اور ہر رستے پر مت بیٹھا کرو کہ جو شخص اللہ پر ایمان لاتا ہے اسے تم ڈراتے اور اللہ کی راہ سے روکتے اور اس میں کجی ڈھونڈتے ہو اور اس وقت کو یاد کرو جب تم تھوڑے سے تھے تو اللہ نے تم کو جماعت کثیر کر دیا اور دیکھ لو کہ خرابی کرنے والوں کا انجام کیسا ہوا۔', 'اور مت بیٹھو راستوں پر کہ ڈراؤ اور روکو اللہ کے راستہ سے اس کو جو کہ ایمان لائے اس پر اور ڈھونڈو اس میں عیب [۱۰۵] اور یاد کرو جبکہ تھے تم بہت تھوڑے پھر تم کو بڑھا دیا اور دیکھو کیا ہوا انجام فساد کرنے والوں کا [۱۰۶]', '\"And sit not on every road, threatening, and hindering from the Path of Allah those who believe in Him. and seeking to make it crooked. And remember when you were but few, and He multiplied you. And see what was the end of the Mufsidoon (mischief-makers, corrupts, liars).', 'Do not sit in every path threatening and preventing from the way of Allah the people who believe in Him, and seeking a twist in it. Remember the time when you were few, then He increased you in number. Consider the fate of those who used to make mischief.'),
(1041, 7, 87, 11, 0, 8, 'وَ لَوۡ اَنَّنَا', 'الاعراف', 'وَ اِنۡ کَانَ طَآئِفَۃٌ  مِّنۡکُمۡ اٰمَنُوۡا بِالَّذِیۡۤ اُرۡسِلۡتُ بِہٖ وَ طَآئِفَۃٌ  لَّمۡ یُؤۡمِنُوۡا فَاصۡبِرُوۡا حَتّٰی یَحۡکُمَ اللّٰہُ بَیۡنَنَا ۚ وَ ہُوَ  خَیۡرُ  الۡحٰکِمِیۡنَ ﴿۸۷﴾', 'اور اگر تم میں سے ایک جماعت میری رسالت پر ایمان لے آئی ہے اور ایک جماعت ایمان نہیں لائی تو صبر کئے رہو یہاں تک کہ اللہ ہمارے تمہارے درمیان فیصلہ کر دے۔ اور وہ سب سے بہتر فیصلہ کرنے والا ہے۔', 'اور اگر تم میں سے ایک فرقہ ایمان لایا اس پر جو میرے ہاتھ بھیجا گیا اور ایک فرقہ ایمان نہیں لایا تو صبر کرو جب تک اللہ فیصلہ کرے درمیان ہمارے اور وہ سب سے بہتر فیصلہ کرنے والا ہے [۱۰۷]', '\"And if there is a party of you who believes in that with which I have been sent and a party who do not believe, so be patient until Allah judges between us, and He is the Best of judges.\"', 'If a group from among you has believed in what I have been sent with, and another group has not believed, then keep patience until Allah decides between us. He is the best of all judges.”'),
(1042, 7, 88, 11, 1, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قَالَ الۡمَلَاُ الَّذِیۡنَ اسۡتَکۡبَرُوۡا مِنۡ قَوۡمِہٖ لَنُخۡرِجَنَّکَ یٰشُعَیۡبُ وَ الَّذِیۡنَ اٰمَنُوۡا مَعَکَ مِنۡ قَرۡیَتِنَاۤ  اَوۡ  لَتَعُوۡدُنَّ فِیۡ مِلَّتِنَا ؕ قَالَ اَوَ لَوۡ  کُنَّا کٰرِہِیۡنَ ﴿۟۸۸﴾', 'تو انکی قوم میں جو لوگ سردار تھے جو تکبر کرتے تھے وہ کہنے لگے۔ کہ شعیب یا تو ہم تم کو اور جو لوگ تمہارے ساتھ ایمان لائے ہیں ان کو اپنے شہر سے نکال دیں گے۔ یا تم ہمارے مذہب میں واپس آ جاؤ۔ انہوں نے کہا خواہ ہم تمہارے دین سے بیزار ہی ہوں تو بھی؟', 'بولے سردار جو متکبر تھے اس کی قوم میں ہم ضرور نکال دیں گے اے شعیب تجھ کو اور ان کو جو کہ ایمان لائے تیرےساتھ اپنے شہر سے یا یہ کہ تم لوٹ آؤ ہمارے دین میں [۱۰۸] بولا کیا ہم بیزار ہوں تو بھی [۱۰۹]', 'The chiefs of those who were arrogant among his people said: \"We shall certainly drive you out, O Shuaib, and those who have believed with you from our town, or else you (all) shall return to our religion.\" He said: \"Even though we hate it!', 'The chiefs of his people, who were arrogant, said, “O Shu‘aib, we will expel you and those who believe with you from our town, or you shall have to turn to our faith.” He said, “Even if we hate it?'),
(1043, 7, 89, 11, 1, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قَدِ افۡتَرَیۡنَا عَلَی اللّٰہِ  کَذِبًا اِنۡ عُدۡنَا فِیۡ مِلَّتِکُمۡ  بَعۡدَ  اِذۡ  نَجّٰنَا اللّٰہُ مِنۡہَا ؕ وَ مَا یَکُوۡنُ  لَنَاۤ  اَنۡ نَّعُوۡدَ  فِیۡہَاۤ  اِلَّاۤ  اَنۡ یَّشَآءَ اللّٰہُ رَبُّنَا ؕ وَسِعَ رَبُّنَا کُلَّ شَیۡءٍ عِلۡمًا ؕ عَلَی اللّٰہِ تَوَکَّلۡنَا ؕ رَبَّنَا افۡتَحۡ بَیۡنَنَا وَ بَیۡنَ قَوۡمِنَا بِالۡحَقِّ وَ اَنۡتَ خَیۡرُ  الۡفٰتِحِیۡنَ ﴿۸۹﴾', 'اگر ہم اسکے بعد کہ اللہ ہمیں اس سے نجات بخش چکا ہے تمہارے مذہب میں لوٹ جائیں تو بیشک ہم نے اللہ پر جھوٹ باندھا اور ہمیں شایاں نہیں کہ ہم اس میں لوٹ جائیں ہاں اللہ جو ہمارا پروردگار ہے وہ چاہے تو ہم مجبور ہیں ہمارے پروردگار کا علم ہر چیز کا احاطہ کئے ہوئے ہے۔ ہمارا اللہ ہی پر بھروسہ ہے اے پروردگار ہم میں اور ہماری قوم میں انصاف کے ساتھ فیصلہ کر دے اور تو سب سے بہتر فیصلہ کرنے والا ہے۔', 'بیشک ہم نے بہتان باندھا اللہ پر جھوٹا اگر لوٹ آئیں تمہارے دین میں [۱۱۰] بعد اس کی کہ نجات دے چکا ہم کو اللہ اس سے [۱۱۱] اور ہمارا کام نہیں کہ لوٹ آئیں اس میں مگر یہ کہ چاہے اللہ رب ہمارا گھیرے ہوئے ہے ہمارا پروردگار سب چیزوں کو اپنے علم میں اللہ ہی پر ہم نے بھروسا کیا اے ہمارے رب فیصلہ کر ہم میں اور ہماری قوم میں انصاف کے ساتھ اور تو سب سےبہتر فیصلہ کرنے والا ہے [۱۱۲]', '\"We should have invented a lie against Allah if we returned to your religion, after Allah has rescued us from it. And it is not for us to return to it unless Allah, our Lord, should will. Our Lord comprehends all things in His Knowledge. In Allah (Alone) we put our trust. Our Lord! Judge between us and our people in truth, for You are the Best of those who give judgment.\"', 'We will be forging a lie against Allah, if we were to turn to your faith after Allah has saved us from it. It is not for us that we turn to it unless Allah, our Lord, so wills. Our Lord has encompassed everything with His knowledge. In Allah we place our trust. -Our Lord, decide between us and our people, with truth, and You are the best of all judges.”'),
(1044, 7, 90, 11, 1, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ قَالَ الۡمَلَاُ الَّذِیۡنَ  کَفَرُوۡا مِنۡ قَوۡمِہٖ لَئِنِ اتَّبَعۡتُمۡ شُعَیۡبًا اِنَّکُمۡ  اِذًا لَّخٰسِرُوۡنَ ﴿۹۰﴾', 'اور انکی قوم میں سے سردار لوگ جو کافر تھے کہنے لگے کہ بھائیو اگر تم نے شعیب کی پیروی کی تو بیشک تم خسارے میں پڑ گئے۔', 'اور بولے سردار جو کافر تھے اس کی قوم میں اگر پیروی کرو گے تم شعیب کی تو تم بیشک خراب ہو گے [۱۱۳]', 'The chiefs of those who disbelieved among his people said (to their people): \"If you follow Shuaib, be sure then you will be the losers!\"', 'The chiefs of his people who disbelieved said, “If you are to follow Shu‘aib, then you will be utter losers.”'),
(1045, 7, 91, 11, 1, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'فَاَخَذَتۡہُمُ الرَّجۡفَۃُ فَاَصۡبَحُوۡا فِیۡ دَارِہِمۡ جٰثِمِیۡنَ ﴿ۚۖۛ۹۱﴾', 'تو انکو زلزلے نے آ پکڑا اور وہ اپنے گھروں میں اوندھے پڑے رہ گئے۔', 'پھر آ پکڑا ان کو زلزلہ نے پس صبح کو رہ گئے اپنے گھروں کے اندر اوندھے پڑے [۱۱۴]', 'So the earthquake seized them and they lay (dead), prostrate in their homes.', 'So, the earthquake seized them, and they were (found dead) in their homes, fallen on their faces.'),
(1046, 7, 92, 11, 1, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'الَّذِیۡنَ کَذَّبُوۡا شُعَیۡبًا کَاَنۡ  لَّمۡ  یَغۡنَوۡا فِیۡہَا ۚۛ اَلَّذِیۡنَ  کَذَّبُوۡا شُعَیۡبًا  کَانُوۡا ہُمُ الۡخٰسِرِیۡنَ ﴿۹۲﴾', 'یہ لوگ جنہوں نے شعیب کی تکذیب کی تھی ایسے برباد ہوئے تھے کہ گویا وہ ان میں کبھی آباد ہی نہیں ہوئے تھے غرض جنہوں نے شعیب کو جھٹلایا وہ خسارے میں پڑ گئے۔', 'جنہوں نے جھٹلایا شعیب کو گویا کبھی بسے ہی نہ تھے وہاں جنہوں نے جھٹلایا شعیب کو وہی ہوئے خراب [۱۱۵]', 'Those who belied Shuaib, became as if they had never dwelt there (in their homes). Those who belied Shuaib, they were the losers.', 'Those who rejected Shu‘aib became as if they never dwelt there. Those who rejected Shu‘aib were themselves the losers.'),
(1047, 7, 93, 11, 1, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'فَتَوَلّٰی عَنۡہُمۡ وَ قَالَ یٰقَوۡمِ لَقَدۡ اَبۡلَغۡتُکُمۡ رِسٰلٰتِ رَبِّیۡ وَ نَصَحۡتُ لَکُمۡ ۚ فَکَیۡفَ  اٰسٰی عَلٰی قَوۡمٍ کٰفِرِیۡنَ ﴿٪۹۳﴾', 'پھر شعیب ان میں سے نکل آئے اور کہا کہ بھائیو میں نے تم کو اپنے پروردگار کے پیغام پہنچا دیئے اور تمہاری خیرخواہی کی تھی تو میں کافروں پر عذاب نازل ہونے سے رنج و غم کیوں کروں۔', 'پھر الٹا پھر ان لوگوں سے اور بولا اے میری قوم میں پہنچا چکا تم کو پیغام اپنے رب کے اور خیر خواہی کر چکا تمہاری اب کیا افسوس کروں کافروں پر [۱۱۶]', 'Then he (Shuaib) turned from them and said: \"O my people! I have indeed conveyed my Lords Messages unto you and I have given you good advice. Then how can I sorrow for the disbelieving peoples (destruction).\"', 'So, he turned away from them and said, “O my people, I have surely delivered to you the message of my Lord, and wished your betterment. How, then, should I grieve over a disbelieving people?”'),
(1048, 7, 94, 12, 2, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ مَاۤ  اَرۡسَلۡنَا فِیۡ  قَرۡیَۃٍ  مِّنۡ نَّبِیٍّ  اِلَّاۤ اَخَذۡنَاۤ  اَہۡلَہَا بِالۡبَاۡسَآءِ  وَ الضَّرَّآءِ لَعَلَّہُمۡ  یَضَّرَّعُوۡنَ ﴿۹۴﴾', 'اور ہم نے کسی شہر میں کوئی پیغمبر نہیں بھیجا۔ مگر وہاں کے رہنے والوں کو جو ایمان نہ لائے دکھوں اور مصیبتوں میں مبتلا کیا تاکہ وہ عاجزی اور زاری کریں۔', 'اور نہیں بھیجا ہم نے کسی بستی میں کوئی نبی کہ نہ پکڑا ہو ہم نے وہاں کےلوگوں کو سختی اور تکلیف میں تاکہ وہ گڑگڑائیں', 'And We sent no Prophet unto any town (and they denied him), but We seized its people with suffering from extreme poverty (or loss in wealth) and loss of health and calamities, so that they might humiliate themselves (and repent to Allah).', 'We did not send any prophet to a town, but We seized its people with hardship and suffering, so that they may turn humble.'),
(1049, 7, 95, 12, 2, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'ثُمَّ بَدَّلۡنَا مَکَانَ السَّیِّئَۃِ الۡحَسَنَۃَ حَتّٰی عَفَوۡا وَّ قَالُوۡا قَدۡ مَسَّ اٰبَآءَنَا الضَّرَّآءُ وَ السَّرَّآءُ  فَاَخَذۡنٰہُمۡ  بَغۡتَۃً   وَّ ہُمۡ  لَا  یَشۡعُرُوۡنَ ﴿۹۵﴾', 'پھر ہم نے تکلیف کو آسودگی سے بدل دیا یہاں تک کہ وہ مال و اولاد میں زیادہ ہوگئے تو کہنے لگے کہ اسی طرح کا رنج و راحت ہمارے بڑوں کو بھی پہنچتا رہا ہے تو ہم نے انکو ناگہاں پکڑ لیا اور وہ اپنے حال میں بیخبر تھے۔', 'پھر بدل دی ہم نے برائی کی جگہ بھلائی یہاں تک کہ وہ بڑھ گئے اور کہنے لگے کہ پہنچتی رہی ہے ہمارےباپ دادوں کو بھی تکلیف اورخوشی پھر پکڑا ہم نے ان کو ناگہاں اور ان کو خبر نہ تھی [۱۱۷]', 'Then We changed the evil for the good, until they increased in number and in wealth, and said: \"Our fathers were touched with evil (loss of health and calamities) and with good (prosperity, etc.).\" So We seized them of a sudden while they were unaware.', 'Thereafter, We substituted good in place of evil until they increased, and said, “Hardship and prosperity came to our fathers (too).” Then We seized them suddenly while they were not aware.'),
(1050, 7, 96, 12, 2, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ لَوۡ اَنَّ  اَہۡلَ الۡقُرٰۤی اٰمَنُوۡا  وَ اتَّقَوۡا لَفَتَحۡنَا عَلَیۡہِمۡ بَرَکٰتٍ مِّنَ السَّمَآءِ وَ الۡاَرۡضِ وَ لٰکِنۡ  کَذَّبُوۡا فَاَخَذۡنٰہُمۡ بِمَا  کَانُوۡا  یَکۡسِبُوۡنَ ﴿۹۶﴾', 'اور اگر ان بستیوں کے لوگ ایمان لے آتے اور پرہیزگار ہو جاتے تو ہم ان پر آسمان اور زمین کی برکات کے دروازے کھول دیتے مگر انہوں نے تو تکذیب کی۔ سو انکے اعمال کی سزا میں ہم نے انکو پکڑ لیا۔', 'اور اگر بستیوں والے ایمان لاتے اور پرہیزگاری کرتے تو ہم کھول دیتے ان پر نعمتیں آسمان اور زمین سے لیکن جھٹلایا انہوں نے پس پکڑا ہم نے ان کو ان کے اعمال کےبدلے [۱۱۸]', 'And if the people of the towns had believed and had the Taqwa (piety), certainly, We should have opened for them blessings from the heaven and the earth, but they belied (the Messengers). So We took them (with punishment) for what they used to earn (polytheism and crimes, etc.).', 'If the people of the towns believed and feared Allah, We would have opened for them blessings from the heavens and the earth, but they disbelieved. So, We seized them because of what they used to earn for themselves.'),
(1051, 7, 97, 12, 2, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'اَفَاَمِنَ اَہۡلُ الۡقُرٰۤی اَنۡ  یَّاۡتِیَہُمۡ  بَاۡسُنَا بَیَاتًا  وَّ ہُمۡ  نَآئِمُوۡنَ ﴿ؕ۹۷﴾', 'کیا بستیوں میں رہنے والے اس سے بے خوف ہیں۔ کہ ان پر ہمارا عذاب رات کو واقع ہو اور وہ بیخبر سو رہے ہوں۔', 'اب کیا بے ڈر ہیں بستیوں والے اس سے کہ آ پہنچے ان پر آفت ہماری راتوں رات جب سوتے ہوں', 'Did the people of the towns then feel secure against the coming of Our Punishment by night while they are asleep?', 'So, do the people of the towns feel themselves immune from Our punishment that may befall them at night while they are asleep?'),
(1052, 7, 98, 12, 2, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'اَوَ  اَمِنَ  اَہۡلُ الۡقُرٰۤی اَنۡ یَّاۡتِیَہُمۡ بَاۡسُنَا ضُحًی  وَّ ہُمۡ  یَلۡعَبُوۡنَ ﴿۹۸﴾', 'اور کیا اہل شہر اس سے نڈر ہیں کہ ان پر ہمارا عذاب دن چڑھے آ نازل ہو اور وہ کھیل رہے ہوں۔', 'یا بے ڈر ہیں بستیوں والے اس بات سے کہ آ پہنچے ان پر عذاب ہمارا دن چڑھے جب کھیلتے ہوں [۱۱۹]', 'Or, did the people of the towns then feel secure against the coming of Our Punishment in the forenoon while they play?', 'Or do the people of the towns feel themselves immune from Our punishment that may befall them in broad daylight while they are at play?'),
(1053, 7, 99, 12, 2, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'اَفَاَمِنُوۡا مَکۡرَ اللّٰہِ ۚ فَلَا  یَاۡمَنُ مَکۡرَ اللّٰہِ   اِلَّا الۡقَوۡمُ  الۡخٰسِرُوۡنَ ﴿٪۹۹﴾', 'کیا یہ لوگ اللہ کے داؤں کا ڈر نہیں رکھتے سن لو کہ اللہ کے داؤں سے وہی لوگ نڈر ہوتے ہیں جو خسارہ پانے والے ہیں۔', 'یا بے ڈر ہو گئے اللہ کے داؤ سے سو بے ڈر نہیں ہوتے اللہ کے داؤ سےمگر خرابی میں پڑنے والے [۱۲۰]', 'Did they then feel secure against the Plan of Allah. None feels secure from the Plan of Allah except the people who are the losers.', 'Do they feel secure from Allah’s plan? None can feel secure from Allah’s plan except the people who are losers.'),
(1054, 7, 100, 13, 3, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'اَوَ لَمۡ  یَہۡدِ  لِلَّذِیۡنَ یَرِثُوۡنَ الۡاَرۡضَ مِنۡۢ  بَعۡدِ  اَہۡلِہَاۤ  اَنۡ  لَّوۡ نَشَآءُ  اَصَبۡنٰہُمۡ بِذُنُوۡبِہِمۡ ۚ وَ نَطۡبَعُ عَلٰی قُلُوۡبِہِمۡ  فَہُمۡ  لَا  یَسۡمَعُوۡنَ ﴿۱۰۰﴾', 'کیا ان لوگوں کو جو اہل زمین کے مر جانے کے بعد زمین کے مالک ہوتے ہیں یہ امر موجب ہدایت نہیں ہوا کہ اگر ہم چاہیں تو ان کے گناہوں کے سبب ان پر مصیبت ڈال دیں اور ان کے دلوں پر مہر لگا دیں کہ کچھ سن ہی نہ سکیں۔', 'کیا نہیں ظاہر ہوا ان لوگوں پر جو وارث ہوئے زمین کے وہاں کے لوگوں کے ہلاک ہونے کے بعد کہ اگر ہم چاہیں تو ان کو پکڑ لیں ان کے گناہوں پر [۱۲۱] اور ہم نے مہر کر دی ہے انکے دلوں پر سو وہ نہیں سنتے', 'Is it not clear to those who inherit the earth in succession from its (previous) possessors, that had We willed, We would have punished them for their sins. And We seal up their hearts so that they hear not?', 'Have all these events still not taught a lesson to those who inherit the land after its (former) inhabitants, that if We so willed, We could afflict them for their sins? But We seal their hearts, so that they do not listen.'),
(1055, 7, 101, 13, 3, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'تِلۡکَ الۡقُرٰی نَقُصُّ عَلَیۡکَ مِنۡ اَنۡۢبَآئِہَا ۚ  وَ لَقَدۡ جَآءَتۡہُمۡ رُسُلُہُمۡ بِالۡبَیِّنٰتِ ۚ فَمَا کَانُوۡا لِیُؤۡمِنُوۡا بِمَا کَذَّبُوۡا مِنۡ قَبۡلُ ؕ کَذٰلِکَ یَطۡبَعُ اللّٰہُ عَلٰی قُلُوۡبِ  الۡکٰفِرِیۡنَ ﴿۱۰۱﴾', 'یہ بستیاں ہیں جن کے کچھ حالات ہم تم کو سناتے ہیں اور ان کے پاس انکے پیغمبر نشانیاں لے کر آئے۔ مگر وہ ایسے نہیں تھے کہ جس چیز کو پہلے جھٹلا چکے ہوں اسے مان لیں اسی طرح اللہ کافروں کے دلوں پر مہر لگا دیتا ہے۔', 'یہ بستیاں ہیں کہ سناتے ہیں ہم تجھ کو ان کے کچھ حالات اور بیشک ان کے پاس پہنچ چکے ان کے رسول نشانیاں لے کر پھر ہرگز نہ ہوا کہ ایمان لائیں اس بات پر جس کو پہلے جھٹلا چکے تھے یوں مہر کر دیتا ہے اللہ کافروں کے دلوں پر [۱۲۲]', 'Those were the towns whose story We relate unto you (O Muhammad SAW). And there came indeed to them their Messengers with clear proofs, but they were not such as to believe in that which they had rejected before. Thus Allah does seal up the hearts of the disbelievers (from each and every kind of religious guidance).', 'Those are the towns We narrate to you their important events. Surely their messengers came to them with clear signs, but they were not able to believe in what they had rejected earlier. This is how Allah seals the hearts of the disbelievers.'),
(1056, 7, 102, 13, 3, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ مَا  وَجَدۡنَا  لِاَکۡثَرِہِمۡ  مِّنۡ عَہۡدٍ ۚ وَ  اِنۡ  وَّجَدۡنَاۤ   اَکۡثَرَہُمۡ  لَفٰسِقِیۡنَ ﴿۱۰۲﴾', 'اور ہم نے ان میں سے اکثر لوگوں میں عہد کا پاس نہیں دیکھا۔ اور ان میں اکثروں کو دیکھا تو بدکار ہی دیکھا۔', 'اور نہ پایا ان کے اکثر لوگوں میں ہم نے عہد کا نباہ اور اکثر ان میں پائےنافرمان [۱۲۳]', 'And most of them We found not (true) to their covenant, but most of them We found indeed Fasiqoon (rebellious, disobedient to Allah).', 'We did not find with most of them any covenant (unbroken), and surely We have found most of them sinners.'),
(1057, 7, 103, 13, 3, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'ثُمَّ بَعَثۡنَا مِنۡۢ بَعۡدِہِمۡ مُّوۡسٰی بِاٰیٰتِنَاۤ  اِلٰی فِرۡعَوۡنَ وَ مَلَا۠ئِہٖ فَظَلَمُوۡا بِہَا ۚ فَانۡظُرۡ  کَیۡفَ کَانَ عَاقِبَۃُ الۡمُفۡسِدِیۡنَ ﴿۱۰۳﴾', 'پھر ان پیغمبروں کے بعد ہم نے موسٰی کو نشانیاں دے کر فرعون اور اسکے درباریوں کے پاس بھیجا۔ تو انہوں نے انکے ساتھ کفر کیا سو دیکھ لو کہ خرابی کرنے والوں کا انجام کیا ہوا۔', 'پھر بھیجا ہم نے ان کے پیچھے [۱۲۴] موسٰی کو اپنی نشانیاں دے کر فرعون اور اسکےسرداروں کے پاس پس کفر کیا انہوں نےانکے مقابلہ میں سو دیکھ کیا انجام ہوا مفسدوں کا [۱۲۵]', 'Then after them We sent Moosa (Moses) with Our Signs to Firaun (Pharaoh) and his chiefs, but they wrongfully rejected them. So see how was the end of the Mufsidoon (mischief-makers, corrupts, etc.).', 'After them, We sent Mūsā with Our signs to Pharaoh and his chiefs. But they did injustice to them. So, consider the fate of the mischief-makers.'),
(1058, 7, 104, 13, 3, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ قَالَ مُوۡسٰی یٰفِرۡعَوۡنُ  اِنِّیۡ  رَسُوۡلٌ مِّنۡ رَّبِّ  الۡعٰلَمِیۡنَ ﴿۱۰۴﴾ۙ', 'اور موسٰی نے کہا کہ اے فرعون میں رب العالمین کا پیغمبر ہوں۔', 'اور کہا موسٰی نے اے فرعون میں رسول ہوں پروردگار عالم کا', 'And Moosa (Moses) said: \"O Firaun (Pharaoh)! I am a Messenger from the Lord of the Alameen (mankind, jinns and all that exists).', 'Mūsā said, “O Pharaoh, I am a messenger from the Lord of all the worlds;'),
(1059, 7, 105, 13, 3, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'حَقِیۡقٌ عَلٰۤی اَنۡ  لَّاۤ  اَقُوۡلَ عَلَی اللّٰہِ  اِلَّا الۡحَقَّ ؕ قَدۡ جِئۡتُکُمۡ بِبَیِّنَۃٍ مِّنۡ رَّبِّکُمۡ فَاَرۡسِلۡ مَعِیَ بَنِیۡۤ  اِسۡرَآءِیۡلَ ﴿۱۰۵﴾ؕ', 'مجھ پر واجب ہے کہ اللہ کی طرف سے جو کچھ کہوں سچ ہی کہوں۔ میں تمہارے پاس تمہارے پروردگار کی طرف سے نشانی لے کر آیا ہوں سو بنی اسرائیل کو میرے ساتھ جانے کی رخصت دے دیجئے۔', 'قائم ہوں اس بات پر کہ نہ کہوں اللہ کی طرف سے مگر جو سچ ہے لایا ہوں تمہارے پاس نشانی تمہارے رب کی [۱۲۶] سو بھیجدے میرےساتھ بنی اسرائیل کو [۱۲۷]', '\"Proper it is for me that I say nothing concerning Allah but the truth. Indeed I have come unto you from your Lord with a clear proof. So let the Children of Israel depart along with me.\"', 'it befits me not to say anything about Allah except the truth. I have come to you with a clear sign from your Lord. So, let the children of Isrā’īl go with me.”'),
(1060, 7, 106, 13, 3, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قَالَ  اِنۡ کُنۡتَ جِئۡتَ بِاٰیَۃٍ  فَاۡتِ بِہَاۤ  اِنۡ  کُنۡتَ  مِنَ  الصّٰدِقِیۡنَ ﴿۱۰۶﴾', 'فرعون نے کہا اگر تم نشانی لے کر آئے ہو تو اگر سچے ہو تو لاؤ دکھاؤ۔', 'بولا اگر تو آیا ہے کوئی نشانی لے کر تو لا اس کو اگر تو سچا ہے', '(Firaun (Pharaoh)) said: \"If you have come with a sign, show it forth, - if you are one of those who tell the truth.\"', 'He said, “If you have come with a sign, then bring it forth, if you are really truthful.”'),
(1061, 7, 107, 13, 3, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'فَاَلۡقٰی عَصَاہُ  فَاِذَا ہِیَ ثُعۡبَانٌ  مُّبِیۡنٌ ﴿۱۰۷﴾ۚۖ', 'موسٰی نے اپنی لاٹھی زمین پر ڈال دی تو وہ اسی وقت ایک بڑا اژدھا بن گیا۔', 'تب ڈال دیا اس نے اپنا عصا تو اسی وقت ہو گیا اژدھا صریح [۱۲۸]', 'Then (Moosa (Moses)) threw his stick and behold! it was a serpent, manifest!', 'So he threw down his staff, and in no time it was a vivid serpent;'),
(1062, 7, 108, 13, 3, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَّ نَزَعَ یَدَہٗ  فَاِذَا ہِیَ بَیۡضَآءُ  لِلنّٰظِرِیۡنَ ﴿۱۰۸﴾٪', 'اور اپنا ہاتھ گریبان سے نکالا تو اسی دم دیکھنے والوں کی نگاہوں میں سفید براق یعنی روشن ہو گیا۔', 'اور نکالا اپنا ہاتھ تو اسی وقت وہ سفید نظر آنے لگا دیکھنے والوں کو [۱۲۹]', 'And he drew out his hand, and behold! it was white (with radiance) for the beholders.', 'and he drew out his hand, and it was luminous for the onlookers.'),
(1063, 7, 109, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قَالَ الۡمَلَاُ مِنۡ  قَوۡمِ  فِرۡعَوۡنَ   اِنَّ ہٰذَا لَسٰحِرٌ  عَلِیۡمٌ ﴿۱۰۹﴾ۙ', 'تو قوم فرعون میں جو سردار تھے وہ کہنے لگے کہ یہ بڑا ماہر جادوگر ہے۔', 'بولے سردار فرعون کی قوم کے یہ تو کوئی بڑا واقف جادوگر ہے [۱۳۰]', 'The chiefs of the people of Firaun (Pharaoh) said: \"This is indeed a well-versed sorcerer;', 'The chiefs of the people of Pharaoh said, “This man is certainly a sorcerer of great knowledge.'),
(1064, 7, 110, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'یُّرِیۡدُ  اَنۡ یُّخۡرِجَکُمۡ مِّنۡ  اَرۡضِکُمۡ ۚ فَمَا ذَا  تَاۡمُرُوۡنَ ﴿۱۱۰﴾', 'اس کا ارادہ یہ ہے کہ تم کو تمہارے ملک سے نکال دے۔ بھلا تمہاری کیا صلاح ہے؟', 'نکالنا چاہتا ہےتم کو تمہارےملک سے اب تمہاری کیا صلاح ہے [۱۳۱]', '\"He wants to get you out of your land, so what do you advise?\"', 'He wants to expel you from your land. So, what do you suggest?”'),
(1065, 7, 111, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قَالُوۡۤا اَرۡجِہۡ  وَ اَخَاہُ  وَ اَرۡسِلۡ فِی الۡمَدَآئِنِ  حٰشِرِیۡنَ ﴿۱۱۱﴾ۙ', 'انہوں نے فرعون  سے کہا کہ فی الحال موسٰی اور اسکے بھائی کے معاملے کو موقوف رکھئے اور شہروں میں نقیب روانہ کر دیجئے۔', 'بولےڈھیل دے اس کو اور اسکے بھائی کو اور بھیج پرگنوں میں جمع کرنے والوں کو', 'They said: \"Put him and his brother off (for a time), and send callers (men) to the cities to collect (and) -', 'They said, “leave him and his brother alone for a while, and send (your) men to the cities to collect'),
(1066, 7, 112, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'یَاۡتُوۡکَ  بِکُلِّ  سٰحِرٍ  عَلِیۡمٍ ﴿۱۱۲﴾', 'کہ تمام ماہر جادوگروں کو آپ کے پاس لے آئیں۔', 'کہ جمع کر لائیں تیرے پاس جو ہو کامل جادوگر [۱۳۲]', '\"That they bring up to you all well-versed sorcerers.\"', 'and bring to you every expert sorcerer (who could defeat him).”'),
(1067, 7, 113, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ  جَآءَ  السَّحَرَۃُ  فِرۡعَوۡنَ  قَالُوۡۤا اِنَّ  لَنَا  لَاَجۡرًا  اِنۡ  کُنَّا نَحۡنُ الۡغٰلِبِیۡنَ ﴿۱۱۳﴾', 'چنانچہ ایسا ہی کیا گیا اور جادوگر فرعون کے پاس آ پہنچے اور کہنے لگے کہ اگر ہم جیت گئے تو ہمیں صلہ تو عطا کیجئے گا ناں۔', 'اور آئےجادوگر فرعون کے پاس بولے ہمارے لئے کچھ مزدوری ہے اگر ہم غالب ہوئے [۱۳۳]', 'And so the sorcerers came to Firaun (Pharaoh). They said: \"Indeed there will be a (good) reward for us if we are the victors.\"', 'The sorcerers came to Pharaoh. They said, “There must be a reward for us, if we are the victors.”'),
(1068, 7, 114, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قَالَ  نَعَمۡ  وَ  اِنَّکُمۡ لَمِنَ الۡمُقَرَّبِیۡنَ ﴿۱۱۴﴾', 'فرعون نے کہا ہاں ضرور اور اسکے علاوہ تم مقربوں میں داخل کر لئے جاؤ گے۔', 'بولا ہاں اور بیشک تم مقرب ہو جاؤ گے [۱۳۴]', 'He said: \"Yes, and moreover you will (in that case) be of the nearest (to me).\"', 'He said, “Yes, and of course, you will be among the closer ones (to me).”'),
(1069, 7, 115, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قَالُوۡا یٰمُوۡسٰۤی  اِمَّاۤ  اَنۡ تُلۡقِیَ وَ  اِمَّاۤ  اَنۡ نَّکُوۡنَ  نَحۡنُ الۡمُلۡقِیۡنَ ﴿۱۱۵﴾', 'جب فریقین روز مقررہ پر جمع ہوئے تو جادوگروں نے کہا کہ موسٰی یا تو تم جادو کی چیز ڈالو یا ہم ڈالتے ہیں۔', 'بولے اے موسٰی یا تو تو ڈال اور یا ہم ڈالتے ہیں [۱۳۵]', 'They said: \"O Moosa (Moses)! Either you throw (first), or shall we have the (first) throw?\"', 'They said, “O Mūsā, would you throw (first) or are we to throw?”'),
(1070, 7, 116, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قَالَ  اَلۡقُوۡا ۚ فَلَمَّاۤ  اَلۡقَوۡا سَحَرُوۡۤا  اَعۡیُنَ النَّاسِ وَ اسۡتَرۡہَبُوۡہُمۡ  وَ جَآءُوۡ  بِسِحۡرٍ عَظِیۡمٍ ﴿۱۱۶﴾', 'موسٰی نے فرمایا تم ہی ڈالو۔ سو جب انہوں نے جادو کی چیزیں ڈالیں تو لوگوں کی آنکھوں پر جادو کر دیا یعنی نظربندی کر دی اور لاٹھیوں اور رسیوں کے سانپ بنا بنا کر انہیں ڈرا ڈرا دیا اور بہت بڑا جادو دکھایا۔', 'کہا ڈالو [۱۳۶] پھر اجب انہوں نےڈالا باندھ دیا لوگوں کی آنکھوں کو اور ان کو ڈرا دیا اور لائے بڑا جادو [۱۳۷]', 'He (Moosa (Moses)) said: \"Throw you (first).\" So when they threw, they bewitched the eyes of the people, and struck terror into them, and they displayed a great magic.', 'He said, “You throw.” So when they threw, they bewitched the eyes of the people, and made them frightened, and produced great sorcery.'),
(1071, 7, 117, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اَوۡحَیۡنَاۤ  اِلٰی مُوۡسٰۤی اَنۡ اَلۡقِ عَصَاکَ ۚ فَاِذَا  ہِیَ تَلۡقَفُ  مَا  یَاۡفِکُوۡنَ ﴿۱۱۷﴾ۚ', 'اور اس وقت ہم نے موسٰی کی طرف وحی بھیجی کہ تم بھی اپنی لاٹھی ڈال دو تب وہ فوراً سانپ بن کر جادگروں کے بنائے ہوئے سانپوں کو ایک ایک کر کے نگل جائے گی۔', 'اور ہم نے حکم بھیجا موسٰی کو کہ ڈال دے اپنا عصا سو وہ جبہی لگا نگلنے جو سانگ انہوں نے بنایا تھا', 'And We inspired Moosa (Moses) (saying): \"Throw your stick,\" and behold! It swallowed up straight away all the falsehoods which they showed.', 'We revealed to Mūsā, “Throw your staff.” Then of a sudden, it began to swallow all that they had concocted.'),
(1072, 7, 118, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'فَوَقَعَ الۡحَقُّ وَ بَطَلَ مَا کَانُوۡا یَعۡمَلُوۡنَ ﴿۱۱۸﴾ۚ', 'آخر حق ثابت ہو گیا اور جو کچھ وہ لوگ کرتے تھے باطل ہو گیا۔', 'پس ظاہر ہو گیا حق اور غلط ہو گیا جو کچھ انہوں نے کیا تھا', 'Thus truth was confirmed, and all that they did was made of no effect.', 'Thus the truth prevailed, and what they were doing became a nullity.'),
(1073, 7, 119, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'فَغُلِبُوۡا ہُنَالِکَ وَ انۡقَلَبُوۡا صٰغِرِیۡنَ ﴿۱۱۹﴾ۚ', 'چنانچہ اس موقع پر وہ مغلوب ہو گئے اور ذلیل ہو کر رہ گئے۔', 'پس ہار گئے اس جگہ اور لوٹ گئے ذلیل ہو کر', 'So they were defeated there and then, and were returned disgraced.', 'So, they were overcome then and there and turned humiliated.'),
(1074, 7, 120, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اُلۡقِیَ  السَّحَرَۃُ  سٰجِدِیۡنَ ﴿۱۲۰﴾ۚۖ', 'اور یہ کیفیت دیکھ کر جادوگر سجدے میں گر پڑے۔', 'اور گر پڑے جادوگر سجدہ میں [۱۳۸]', 'And the sorcerers fell down prostrate.', 'The sorcerers could not but fall in prostration.'),
(1075, 7, 121, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قَالُوۡۤا  اٰمَنَّا  بِرَبِّ الۡعٰلَمِیۡنَ ﴿۱۲۱﴾ۙ', 'کہنے لگے کہ ہم سب جہانوں کے پروردگار پر ایمان لائے۔', 'بولے ہم ایمان لائے پروردگار عالم پر', 'They said: \"We believe in the Lord of the Alameen (mankind, jinns and all that exists).', 'They said, “We believe in the Lord of the worlds,'),
(1076, 7, 122, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'رَبِّ  مُوۡسٰی  وَ ہٰرُوۡنَ ﴿۱۲۲﴾', 'یعنی موسٰی اور ہارون کے پروردگار پر۔', 'جو رب ہے موسٰی اور ہارون کا [۱۳۹]', '\"The Lord of Moosa (Moses) and Haroon (Aaron).\"', 'the Lord of Mūsā and Hārūn.”'),
(1077, 7, 123, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قَالَ فِرۡعَوۡنُ اٰمَنۡتُمۡ بِہٖ قَبۡلَ اَنۡ اٰذَنَ لَکُمۡ ۚ اِنَّ ہٰذَا لَمَکۡرٌ  مَّکَرۡتُمُوۡہُ فِی الۡمَدِیۡنَۃِ  لِتُخۡرِجُوۡا مِنۡہَاۤ  اَہۡلَہَا ۚ فَسَوۡفَ تَعۡلَمُوۡنَ ﴿۱۲۳﴾', 'فرعون نے کہا پیشتر اسکے کہ میں تمہیں اجازت دوں تم اس پر ایمان لے آئے؟ بیشک یہ فریب ہے جو تم نے مل کر شہر میں کیا ہے تاکہ اہل شہر کو یہاں سے نکال دو۔ سو عنقریب اس کا نتیجہ معلوم کر لو گے۔', 'بولا فرعون کیا تم ایمان لے آئے اس پر میری اجازت سے پہلے یہ تو مکر ہے جو بنایا تم سب نے اس شہر میں تاکہ نکال دو اس شہر سے اسکے رہنے والوں کو سو اب تم کو معلوم ہو جائے گا [۱۴۰]', 'Firaun (Pharaoh) said: \"You have believed in him (Moosa (Moses)) before I give you permission. Surely, this is a plot which you have plotted in the city to drive out its people, but you shall come to know.', 'Pharaoh said, “You have believed in him before my permission. Undoubtedly, this is a plot you have designed in the city, so that you may expel its people from it. Now you shall know (its end).'),
(1078, 7, 124, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'لَاُقَطِّعَنَّ اَیۡدِیَکُمۡ وَ اَرۡجُلَکُمۡ مِّنۡ خِلَافٍ ثُمَّ لَاُصَلِّبَنَّکُمۡ اَجۡمَعِیۡنَ ﴿۱۲۴﴾', 'میں پہلے تو تمہارے ایک طرف کے ہاتھ اور دوسری طرف کے پاؤں کاٹ دوں گا پھر تم سب کو سولی چڑھا دوں گا۔', 'میں ضرور کاٹوں گا تمہارے ہاتھ اور دوسری طرف کے پاؤں پھر سولی پر چڑھاؤں گا تم سب کو', '\"Surely, I will cut off your hands and your feet on opposite sides, then I will crucify you all.\"', 'I will cut off your hands and your legs from opposite sides. Then I will crucify you all together.”'),
(1079, 7, 125, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قَالُوۡۤا اِنَّاۤ  اِلٰی رَبِّنَا مُنۡقَلِبُوۡنَ ﴿۱۲۵﴾ۚ', 'وہ بولے کہ ہم تو اپنے پروردگار کی طرف لوٹ کر جانے والے ہیں۔', 'وہ بولے ہم کو تو اپنے رب کی طرف لوٹ کر جانا ہی ہے [۱۴۱]', 'They said: \"Verily, we are returning to our Lord.', 'They said, “We have surely to return to our Lord.'),
(1080, 7, 126, 14, 4, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ مَا تَنۡقِمُ مِنَّاۤ  اِلَّاۤ  اَنۡ  اٰمَنَّا بِاٰیٰتِ رَبِّنَا لَمَّا جَآءَتۡنَا ؕ رَبَّنَاۤ  اَفۡرِغۡ عَلَیۡنَا صَبۡرًا  وَّ تَوَفَّنَا مُسۡلِمِیۡنَ ﴿۱۲۶﴾٪', 'اور اسکے سوا تجھ کو ہماری کون سی بات بری لگی ہے کہ جب ہمارے پروردگار کی نشانیاں ہمارے پاس آگئیں تو ہم ان پر ایمان لے آئے۔ اے پروردگار ہم پر صبر و استقامت کے دہانے کھولدے اور ہمیں فرمانبرداروں کی حالت میں وفات دیجئو۔', 'اور تجھ کو ہم سے یہی دشمنی ہے کہ مان لیا ہم نے اپنے رب کی نشانیوں کو جب وہ ہم تک پہنچیں اے ہمارے رب دہانے کھول دے ہم پرصبر کے اور ہم کو مار مسلمان [۱۴۲]', '\"And you take vengeance on us only because we believed in the Ayat (proofs, evidences, lessons, signs, etc.) of our Lord when they reached us! Our Lord! pour out on us patience, and cause us to die as Muslims.\"', 'For what fault would you punish us except that we have believed in the signs of our Lord when they appeared to us? O our Lord, pour out patience upon us, and cause us to die as Muslims (those who submit to you.)”'),
(1081, 7, 127, 15, 5, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ قَالَ الۡمَلَاُ مِنۡ قَوۡمِ فِرۡعَوۡنَ اَتَذَرُ مُوۡسٰی وَ قَوۡمَہٗ  لِیُفۡسِدُوۡا فِی الۡاَرۡضِ وَ یَذَرَکَ  وَ اٰلِہَتَکَ ؕ قَالَ سَنُقَتِّلُ اَبۡنَآءَہُمۡ وَ نَسۡتَحۡیٖ نِسَآءَہُمۡ ۚ وَ اِنَّا فَوۡقَہُمۡ  قٰہِرُوۡنَ ﴿۱۲۷﴾', 'اور قوم فرعون میں جو سردار تھے کہنے لگے کہ کیا آپ موسٰی اور اسکی قوم کو چھوڑ دیجئے گا کہ ملک میں خرابی کریں اور آپ کو اور آپ کے معبودوں کو چھوڑ دیں۔ اس نے کہا کہ ہم ان کے لڑکوں کو تو قتل کر ڈالیں گے اور لڑکیوں کو زندہ رہنے دیں گے اور بلاشبہ ہم ان پر غالب ہیں۔', 'اور بولے سردار قوم فرعون کےکیوں چھوڑتا ہے تو موسٰی کو اور اسکی قوم کو کہ اودھم مچائیں ملک میں [۱۴۳] اور موقوف کر دے تجھ کو اور تیرے بتوں کو [۱۴۴] بولا اب ہم مار ڈالیں گے انکے بیٹوں کو اور زندہ رکھیں گے انکی عورتوں کو اور ہم ان پر زور آور ہیں [۱۴۵]', 'The chiefs of Firauns (Pharaoh) people said: \"Will you leave Moosa (Moses) and his people to spread mischief in the land, and to abandon you and your gods?\" He said: \"We will kill their sons, and let live their women, and we have indeed irresistible power over them.\"', 'The chiefs of the people of Pharaoh said, “Shall you leave Mūsā and his people free to spread disorder in the land and to abandon you and your gods?” He said, “We shall slaughter their sons and let their women remain alive. We have full power over them.”'),
(1082, 7, 128, 15, 5, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قَالَ مُوۡسٰی  لِقَوۡمِہِ اسۡتَعِیۡنُوۡا بِاللّٰہِ وَ اصۡبِرُوۡا ۚ اِنَّ  الۡاَرۡضَ  لِلّٰہِ ۟ۙ یُوۡرِثُہَا مَنۡ یَّشَآءُ مِنۡ عِبَادِہٖ ؕ وَ الۡعَاقِبَۃُ  لِلۡمُتَّقِیۡنَ ﴿۱۲۸﴾', 'موسٰی نے اپنی قوم سے کہا کہ اللہ سے مدد مانگو اور ثابت قدم رہو زمین تو اللہ کی ہے۔ وہ اپنے بندوں میں سے جسے چاہتا ہے اسکا مالک بناتا ہے۔ اور انجام تو پرہیزگاروں ہی کا بھلا ہوتا ہے۔', 'موسٰی نے کہا اپنی قوم سے مدد مانگو اللہ سے اور صبر کرو بیشک زمین ہے اللہ کی اس کا وارث کر دے جسکو وہ چاہے اپنے بندوں میں اور آخر میں بھلائی ہے ڈرنے والوں کے لئے [۱۴۶]', 'Moosa (Moses) said to his people: \"Seek help in Allah and be patient. Verily, the earth is Allahs. He gives it as a heritage to whom He will of His slaves, and the (blessed) end is for the Muttaqoon (pious - see V.2:2).\"', 'Mūsā said to his people, “Seek help from Allah and be patient. Surely, the land belongs to Allah. He lets whomsoever He wills inherit it from among His servants; and the end-result is in favor of the God-fearing.”'),
(1083, 7, 129, 15, 5, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قَالُوۡۤا اُوۡذِیۡنَا مِنۡ قَبۡلِ اَنۡ تَاۡتِیَنَا وَ مِنۡۢ بَعۡدِ مَا جِئۡتَنَا ؕ قَالَ عَسٰی رَبُّکُمۡ اَنۡ یُّہۡلِکَ عَدُوَّکُمۡ وَ یَسۡتَخۡلِفَکُمۡ  فِی الۡاَرۡضِ فَیَنۡظُرَ  کَیۡفَ تَعۡمَلُوۡنَ ﴿۱۲۹﴾٪', 'وہ بولے کہ تمہارے آنے سے پہلے بھی ہم کو اذیتیں پہنچتی رہیں اور تمہارے آنے کے بعد بھی موسٰی نے کہا کہ قریب ہے کہ تمہارا پروردگار تمہارے دشمن کو ہلاک کر دے اور تمہیں زمین میں خلیفہ بنائے پھر دیکھے کہ تم کیسے عمل کرتے ہو۔', 'وہ بولے ہم پر تکلیفیں رہیں تیرے آنے سے پہلے اور تیرے آنے کے بعد [۱۴۷] کہا نزدیک ہے کہ رب تمہارا ہلاک کر دے تمہارے دشمن کو اور خلیفہ کر دے تم کو ملک میں پھر دیکھے تم کیسے کام کرتے ہو [۱۴۸]', 'They said: \"We (Children of Israel) had suffered troubles before you came to us, and since you have come to us.\" He said: \"It may be that your Lord will destroy your enemy and make you successors on the earth, so that He may see how you act?\"', 'They said, “We were persecuted before you came to us and after you have come to us.” He said, “Hopefully your Lord will destroy your enemy and make you successors in the land, then He will see how you act.”'),
(1084, 7, 130, 16, 6, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ لَقَدۡ اَخَذۡنَاۤ  اٰلَ فِرۡعَوۡنَ بِالسِّنِیۡنَ وَ نَقۡصٍ مِّنَ الثَّمَرٰتِ لَعَلَّہُمۡ یَذَّکَّرُوۡنَ ﴿۱۳۰﴾', 'اور ہم نے فرعونیوں کو خشک سالیوں اور میووں کے نقصان میں پکڑا تاکہ وہ نصیحت حاصل کریں۔', 'اور ہم نے پکڑ لیا فرعون والوں کو قحطوں میں اور میوؤں کے نقصان میں تاکہ وہ نصیحت مانیں', 'And indeed We punished the people of Firaun (Pharaoh) with years of drought and shortness of fruits (crops, etc.), that they might remember (take heed).', 'And We seized the people of Pharaoh with years of famine and poor production of fruits, so that they may learn a lesson.'),
(1085, 7, 131, 16, 6, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'فَاِذَا جَآءَتۡہُمُ الۡحَسَنَۃُ  قَالُوۡا  لَنَا ہٰذِہٖ ۚ وَ  اِنۡ  تُصِبۡہُمۡ سَیِّئَۃٌ  یَّطَّیَّرُوۡا بِمُوۡسٰی وَ مَنۡ مَّعَہٗ ؕ اَلَاۤ  اِنَّمَا طٰٓئِرُہُمۡ عِنۡدَ اللّٰہِ وَ لٰکِنَّ  اَکۡثَرَہُمۡ  لَا یَعۡلَمُوۡنَ ﴿۱۳۱﴾', 'سو جب ان کو آسائش حاصل ہوتی تو کہتے کہ ہم اسکے مستحق ہیں اور اگر سختی پہنچتی تو اسے موسٰی اور انکے رفیقوں کی بدشگونی بتاتے دیکھو ان کی بدشگونی اللہ کے ہاں مقدر ہے لیکن ان میں سے اکثر نہیں جانتے۔', 'پھر جب پہنچی انکو بھلائی کہنے لگے یہ ہے ہمارے لائق اور اگر پہنچی برائی تو نحوست بتلاتے موسٰی کی اور اسکے ساتھ والوں کی سن لو ان کی شومی تو اللہ کے پاس ہے پر اکثر لوگ نہیں جانتے [۱۴۹]', 'But whenever good came to them, they said: \"Ours is this.\" And if evil afflicted them, they ascribed it to evil omens connected with Moosa (Moses) and those with him. Be informed! Verily, their evil omens are with Allah but most of them know not.', 'When good times came to them, they said, “This is our right.” And if an evil touched them, they took it as an ill omen of Mūsā and those with him. Listen, their ill omen lies with Allah only, but most of them do not know.'),
(1086, 7, 132, 16, 6, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ قَالُوۡا مَہۡمَا تَاۡتِنَا بِہٖ مِنۡ اٰیَۃٍ لِّتَسۡحَرَنَا بِہَا ۙ فَمَا نَحۡنُ لَکَ بِمُؤۡمِنِیۡنَ ﴿۱۳۲﴾', 'اور کہنے لگے کہ تم ہمارے پاس خواہ کوئی بھی نشانی لاؤ تاکہ اس سے ہم پر جادو کرو۔ مگر ہم تم پر ایمان لانے والے نہیں ہیں۔', 'اور کہنے لگے جو کچھ تو لائے گا ہمارے پاس نشانی کہ ہم پر اسکی وجہ سے جادو کرے سو ہم ہرگز تجھ پر ایمان نہ لائیں گے [۱۵۰]', 'They said (to Moosa (Moses)): \"Whatever Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) you may bring to us, to work therewith your sorcery on us, we shall never believe in you.\"', 'They said, “Whatever sign you bring to us to enchant us with, we are not going to believe in you.”'),
(1087, 7, 133, 16, 6, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'فَاَرۡسَلۡنَا عَلَیۡہِمُ الطُّوۡفَانَ وَ الۡجَرَادَ وَ الۡقُمَّلَ وَ الضَّفَادِعَ وَ الدَّمَ  اٰیٰتٍ مُّفَصَّلٰتٍ ۟ فَاسۡتَکۡبَرُوۡا وَ کَانُوۡا  قَوۡمًا مُّجۡرِمِیۡنَ ﴿۱۳۳﴾', 'تو ہم نے ان پر طوفان اور ٹڈیاں اور جوئیں اور مینڈک اور خون کتنی کھلی ہوئی نشانیاں بھیجیں مگر وہ تکبر ہی کرتے رہے اور وہ لوگ تھے ہی گناہگار۔', 'پھر ہم نے بھیجا ان پر طوفان [۱۵۱] اور ٹڈی اور چچڑی [۱۵۲] اور مینڈک اور خون بہت سی نشانیاں جدی جدی پھر بھی تکبر کرتے رہے اور تھے وہ لوگ گنہگار [۱۵۳]', 'So We sent on them: the flood, the locusts, the lice, the frogs, and the blood: (as a succession of) manifest signs, yet they remained arrogant, and they were of those people who were Mujrimoon (criminals, polytheists, sinners, etc.).', 'So We sent upon them the storm and locusts and lice and frogs and blood, as signs distinct from each other. Yet they showed arrogance, and they were a guilty people.'),
(1088, 7, 134, 16, 6, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ لَمَّا وَقَعَ عَلَیۡہِمُ  الرِّجۡزُ  قَالُوۡا یٰمُوۡسَی ادۡعُ لَنَا رَبَّکَ بِمَا عَہِدَ عِنۡدَکَ ۚ  لَئِنۡ کَشَفۡتَ عَنَّا الرِّجۡزَ لَنُؤۡمِنَنَّ  لَکَ  وَ لَنُرۡسِلَنَّ  مَعَکَ  بَنِیۡۤ اِسۡرَآءِیۡلَ ﴿۱۳۴﴾ۚ', 'اور جب ان پر عذاب واقع ہوتا تو کہتے کہ موسٰی ہمارے لئے اپنے پروردگار سے دعا کرو۔ جیسا اس نے تم سے عہد کر رکھا ہے اگر تم ہم سے عذاب کو ٹال دو گے تو ہم تم پر ایمان بھی لے آئیں گے اور بنی اسرائیل کو بھی تمہارے ساتھ جانے کی اجازت دینگے۔', 'اور جب پڑتا ان پر کوئی عذاب تو کہتے اے موسٰی دعا کر ہمارے واسطے اپنے رب سے جیسا کہ اس نے بتلا رکھا ہے تجھ کو [۱۵۴] اگر تو نے دور کر دیا ہم سے یہ عذاب تو بیشک ہم ایمان لے آئیں گے تجھ پر اور جانے دیں گے تیرے ساتھ بنی اسرائیل کو', 'And when the punishment fell on them they said: \"O Moosa (Moses)! Invoke your Lord for us because of His Promise to you. If you will remove the punishment from us, we indeed shall believe in you, and we shall let the Children of Israel go with you.\"', 'Whenever a scourge befell them, they said, “O Mūsā, pray for us to your Lord by the covenant He has made with you. If you remove the scourge from us, we will truly believe in you, and will send the children of Isrā’īl with you.”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1089, 7, 135, 16, 6, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'فَلَمَّا کَشَفۡنَا عَنۡہُمُ الرِّجۡزَ اِلٰۤی اَجَلٍ ہُمۡ  بٰلِغُوۡہُ  اِذَا ہُمۡ  یَنۡکُثُوۡنَ ﴿۱۳۵﴾', 'پھر جب ہم ایک مدت کے لئے جس تک ان کو پہنچنا تھا ان سے عذاب دور کر دیتے تو وہ فورًا عہد کو توڑ ڈالتے۔', 'پھر جب ہم نے اٹھا لیا ان سےعذاب ایک مدت تک کہ ان کو اس مدت تک پہنچنا تھا اسی وقت عہد توڑ ڈالتے [۱۵۵]', 'But when We removed the punishment from them to a fixed term, which they had to reach, behold! They broke their word!', 'But when We removed the scourge from them for a term they had to reach, in no time they started to break their promise.'),
(1090, 7, 136, 16, 6, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'فَانۡتَقَمۡنَا مِنۡہُمۡ فَاَغۡرَقۡنٰہُمۡ  فِی الۡیَمِّ بِاَنَّہُمۡ کَذَّبُوۡا بِاٰیٰتِنَا وَ کَانُوۡا عَنۡہَا غٰفِلِیۡنَ ﴿۱۳۶﴾', 'تو ہم نے ان سے بدلہ لے کر ہی چھوڑا کہ انکو سمندر میں ڈبو دیا اس لئے کہ وہ ہماری آیتوں کو جھٹلاتے۔ اور ان سے بے پروائی کرتے تھے۔', 'پھر ہم نے بدلہ لیا ان سے سو ڈبو دیا ہم نے انکو دریا میں اس وجہ سے کہ انہوں نے جھٹلایا ہماری آیتوں کو اور ان سے تغافل کرتے تھے [۱۵۶]', 'So We took retribution from them. We drowned them in the sea, because they belied Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) and were heedless about them.', 'Then We subjected them to retribution, and drowned them in the sea, because they rejected Our signs, and were neglectful of them.'),
(1091, 7, 137, 16, 6, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اَوۡرَثۡنَا الۡقَوۡمَ  الَّذِیۡنَ کَانُوۡا یُسۡتَضۡعَفُوۡنَ  مَشَارِقَ  الۡاَرۡضِ وَ مَغَارِبَہَا الَّتِیۡ  بٰرَکۡنَا فِیۡہَا ؕ وَ تَمَّتۡ کَلِمَتُ رَبِّکَ الۡحُسۡنٰی عَلٰی بَنِیۡۤ اِسۡرَآءِیۡلَ ۬ۙ بِمَا صَبَرُوۡا ؕ وَ دَمَّرۡنَا مَا کَانَ یَصۡنَعُ فِرۡعَوۡنُ وَ قَوۡمُہٗ  وَ مَا کَانُوۡا  یَعۡرِشُوۡنَ ﴿۱۳۷﴾', 'اور جو لوگ کمزور بنائے جاتے رہے انکو ہم نے زمین شام کے مشرق و مغرب کا جس میں ہم نے برکت دی تھی وارث کر دیا اور بنی اسرائیل کے بارے میں ان کے صبر کی وجہ سے تمہارے پروردگار کا وعدہ نیک پورا ہوا اور فرعون اور قوم فرعون جو محل بناتے اور انگور کے باغ جو چھتریوں پر چڑھاتے تھے سب کو ہم نے تباہ کر دیا۔', 'اور وارث کر دیا ہم نے ان لوگوں کو جو کمزور سمجھے جاتے تھے [۱۵۷] اس زمین کے مشرق او رمغرب کا کہ جس میں برکت رکھی ہے ہم نے [۱۵۸] اور پورا ہو گیا نیکی کا وعدہ تیرے رب کا بنی اسرائیل پر بسبب انکے صبر کرنے کے اور خراب کر دیا ہم نے جو کچھ بنایا تھا فرعون اور اسکی قوم نے اور جو اونچا کر کے چھایا تھا [۱۵۹]', 'And We made the people who were considered weak to inherit the eastern parts of the land and the western parts thereof which We have blessed. And the fair Word of your Lord was fulfilled for the Children of Israel, because of their endurance. And We destroyed completely all the great works and buildings which Firaun (Pharaoh) and his people erected.', 'We caused those people who were deemed to be weak (the Israelites) to inherit the East and West of the land that We had blessed. And the sublime word of your Lord was fulfilled for the children of Isrā’īl, because they stood patient; and We destroyed what Pharaoh and his people used to build and what they used to raise high.'),
(1092, 7, 138, 16, 6, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ جٰوَزۡنَا بِبَنِیۡۤ  اِسۡرَآءِیۡلَ الۡبَحۡرَ فَاَتَوۡا عَلٰی قَوۡمٍ یَّعۡکُفُوۡنَ عَلٰۤی  اَصۡنَامٍ لَّہُمۡ ۚ قَالُوۡا یٰمُوۡسَی اجۡعَلۡ لَّنَاۤ  اِلٰـہًا کَمَا لَہُمۡ  اٰلِـہَۃٌ ؕ قَالَ  اِنَّکُمۡ  قَوۡمٌ  تَجۡہَلُوۡنَ ﴿۱۳۸﴾', 'اور ہم نے بنی اسرائیل کو سمندر کے پار اتارا تو وہ ایسے لوگوں کے پاس جا پہنچے جو اپنے بتوں کی عبادت کے لئے بیٹھے رہتے تھے۔ بنی اسرائیل کہنے لگے کہ موسٰی جیسے ان لوگوں کے معبود ہیں ہمارے لئے بھی ایک معبود بنا دو۔ فرمایا کہ تم بڑے ہی جاہل لوگ ہو۔', 'اور پار اتار دیا ہم نے بنی اسرائیل کو دریا سےتو پہنچے ایک قوم پر جو پوجنے میں لگے رہتے تھے اپنے بتوں کے [۱۶۰] کہنے لگے اے موسٰی بنا دے ہماری عبادت کے لئے بھی ایک بت جیسے ان کے بت ہیں کہا تم لوگ تو جہل کرتے ہو [۱۶۱]', 'And We brought the Children of Israel (with safety) across the sea, and they came upon a people devoted to some of their idols (in worship). They said: \"O Moosa (Moses)! Make for us an ilahan (a god) as they have aliha (gods).\" He said: \"Verily, you are a people who know not (the Majesty and Greatness of Allah and what is obligatory upon you, i.e. to worship none but Allah Alone, the One and the Only God of all that exists).\"', 'We made the children of Isrā’īl cross the sea, then they came across a people sitting in devotion before their idols. They (the Israelites) said, “O Mūsā, make a god for us like they have gods.” He said, “You are really an ignorant people.'),
(1093, 7, 139, 16, 6, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'اِنَّ  ہٰۤؤُلَآءِ  مُتَبَّرٌ  مَّا ہُمۡ  فِیۡہِ  وَ  بٰطِلٌ مَّا  کَانُوۡا  یَعۡمَلُوۡنَ ﴿۱۳۹﴾', 'یہ لوگ جس شغل میں پھنسے ہوئے ہیں وہ برباد ہونے والا ہے اور جو کام یہ کرتے ہیں سب بیہودہ ہیں۔', 'یہ لوگ تباہ ہونے والی ہے وہ چیز جس میں وہ لگے ہوئے ہیں اور غلط ہے جو وہ کر رہے ہیں [۱۶۲]', '(Moosa (Moses) added:) \"Verily, these people will be destroyed for that which they are engaged in (idols-worship). And all that they are doing is in vain.\"', 'What these people are engaged in is sure to be destroyed; and false is what they are doing.”'),
(1094, 7, 140, 16, 6, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قَالَ  اَغَیۡرَ اللّٰہِ  اَبۡغِیۡکُمۡ  اِلٰـہًا وَّ ہُوَ فَضَّلَکُمۡ  عَلَی  الۡعٰلَمِیۡنَ ﴿۱۴۰﴾', 'فرمایا کیا میں اللہ کے سوا تمہارے لئے کوئی اور معبود تلاش کروں حالانکہ اس نے تمکو تمام اہل عالم پر فضیلت بخشی ہے۔', 'کہا کیا اللہ کےسوا ڈھونڈوں تمہارے واسطے کوئی اور معبود حالانکہ اس نے تمکو بڑائی دی تمام جہان پر [۱۶۳]', 'He said: \"Shall I seek for you an Ilahan (a God) other than Allah, while He has given you superiority over the Alameen (mankind and jinns of your time).\"', 'He said, “Shall I seek any one other than Allah as God for you, while He has given you excellence over the (people of all the) worlds.”'),
(1095, 7, 141, 16, 6, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اِذۡ  اَنۡجَیۡنٰکُمۡ مِّنۡ اٰلِ فِرۡعَوۡنَ یَسُوۡمُوۡنَکُمۡ  سُوۡٓءَ  الۡعَذَابِ ۚ یُقَتِّلُوۡنَ اَبۡنَآءَکُمۡ  وَ یَسۡتَحۡیُوۡنَ نِسَآءَکُمۡ ؕ وَ فِیۡ ذٰلِکُمۡ  بَلَآءٌ  مِّنۡ  رَّبِّکُمۡ   عَظِیۡمٌ ﴿۱۴۱﴾٪', 'اور ہمارے ان احسانوں کو یاد کرو جب ہم نے تمکو فرعونیوں کے ہاتھ سے نجات بخشی وہ لوگ تم کو بڑا دکھ دیتے تھے۔ تمہارے بیٹوں کو تو قتل کر ڈالتے تھے اور بیٹیوں کو زندہ رہنے دیتے تھے اور اس میں تمہارے پروردگار کی طرف سے بڑی آزمائش تھی۔', 'اور وہ وقت یاد کرو جب نجات دی ہم نے تم کو فرعون والوں سے کہ دیتے تھے تم کو برا عذاب کہ مار ڈالتے تھے تمہارے بیٹوں کو اور جیتا رکھتے تھے تمہاری عورتوں کو اور اس میں احسان ہے تمہارے رب کا بڑا [۱۶۴]', 'And (remember) when We rescued you from Firauns (Pharaoh) people, who were afflicting you with the worst torment, killing your sons and letting your women live. And in that was a great trial from your Lord.', '(Remember) when We delivered you from the people of Pharaoh who inflicted grievous torment upon you, slaughtered your sons and left your women alive. In all that there was a great trial from your Lord.'),
(1096, 7, 142, 17, 7, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ وٰعَدۡنَا  مُوۡسٰی ثَلٰثِیۡنَ  لَیۡلَۃً وَّ اَتۡمَمۡنٰہَا بِعَشۡرٍ فَتَمَّ  مِیۡقَاتُ رَبِّہٖۤ اَرۡبَعِیۡنَ  لَیۡلَۃً ۚ وَ قَالَ مُوۡسٰی  لِاَخِیۡہِ ہٰرُوۡنَ  اخۡلُفۡنِیۡ  فِیۡ  قَوۡمِیۡ وَ اَصۡلِحۡ  وَ لَا تَتَّبِعۡ  سَبِیۡلَ  الۡمُفۡسِدِیۡنَ ﴿۱۴۲﴾', 'اور ہم نے موسٰی سے تیس رات کی معیاد مقرر کی اور دس راتیں اور ملا کر اسے پورا چلہ کر دیا تو اسکے پروردگار کی چالیس رات کی معیاد پوری ہو گئ۔ اور موسٰی نے اپنی بھائی ہارون سے کہا کہ میرے کوہ طور پر جانے کے بعد تم میری قوم میں میرے جانشین ہو۔ اور ان کی اصلاح کرتے رہنا اور شریروں کے رستے پر نہ چلنا۔', 'اور وعدہ کیا ہم نےموسٰی سے تیس رات کا اور پورا کیا ان کو اور دس سے پس پوری ہو گئ مدت تیرے رب کی چالیس راتیں [۱۶۵] اور کہا موسٰی نے اپنے بھائی ہارون سےکہ میرا خلیفہ رہ میری قوم میں اور اصلاح کرتے رہنا اور مت چلنا مفسدوں کی راہ [۱۶۶]', 'And We appointed for Moosa (Moses) thirty nights and added (to the period) ten (more), and he completed the term, appointed by his Lord, of forty nights. And Moosa (Moses) said to his brother Haroon (Aaron): \"Replace me among my people, act in the Right Way (by ordering the people to obey Allah and to worship Him Alone) and follow not the way of the Mufsidoon (mischief-makers).\"', 'And We made an appointment with Mūsā for thirty nights, then We supplemented them with another ten. So, the total period fixed by his Lord was forty nights. Mūsā said to his brother Hārūn, “Take my place among my people and keep things right, and do not follow the way of mischief makers.”'),
(1097, 7, 143, 17, 7, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ لَمَّا جَآءَ مُوۡسٰی لِمِیۡقَاتِنَا وَ کَلَّمَہٗ رَبُّہٗ ۙ قَالَ رَبِّ اَرِنِیۡۤ   اَنۡظُرۡ   اِلَیۡکَ ؕ قَالَ لَنۡ تَرٰىنِیۡ  وَ لٰکِنِ  انۡظُرۡ  اِلَی  الۡجَبَلِ فَاِنِ اسۡتَقَرَّ مَکَانَہٗ فَسَوۡفَ تَرٰىنِیۡ ۚ فَلَمَّا تَجَلّٰی رَبُّہٗ  لِلۡجَبَلِ جَعَلَہٗ  دَکًّا وَّ خَرَّ مُوۡسٰی صَعِقًا ۚ فَلَمَّاۤ  اَفَاقَ قَالَ سُبۡحٰنَکَ تُبۡتُ  اِلَیۡکَ  وَ اَنَا  اَوَّلُ الۡمُؤۡمِنِیۡنَ ﴿۱۴۳﴾', 'اور جب موسٰی ہمارے مقرر کئے ہوئے وقت پر کوہ طور پر پہنچے اور ان کے پروردگار نے ان سے کلام کیا۔ تو کہنے لگے کہ اے پروردگار مجھے اپنا جلوہ دکھا کہ میں تیرا دیدار کروں فرمایا کہ تم مجھے ہرگز نہ دیکھ سکو گے۔ ہاں پہاڑ کی طرف دیکھتے رہو اگر یہ اپنی جگہ پر قائم رہا تو تم مجھ کو دیکھ سکو گے۔ پھر جب انکے پروردگار نے پہاڑ پر تجلی کی تو اسکو ریزہ ریزہ کر دیا۔ اور موسٰی بے ہوش ہو کر گر پڑے۔ پھر جب ہوش میں آئے تو کہنے لگے کہ تیری ذات پاک ہے اور میں تیرے حضور میں توبہ کرتا ہوں اور جو ایمان لانے والے ہیں ان میں سب سے اول ہوں۔', 'اور جب پہنچا موسٰی ہمارے وعدہ پر اور کلام کیا اس سے اسکے رب نے بولا اے میرے رب تو مجھ کو دکھا کہ میں تجھ کو دیکھوں [۱۶۷] فرمایا تو مجھ کو ہر گز نہ دیکھے گا [۱۶۸] لیکن تو دیکھتا رہ پہاڑ کی طرف اگر وہ اپنی جگہ ٹھہرا رہا تو تو مجھ کو دیکھ لے گا [۱۶۹] پھر جب تجلی کی اسکے رب نے پہاڑ کی طرف کر دیا اس کو ڈھا کر برابر اور گر پڑ اموسٰی بےہوش ہو کر [۱۷۰] پھر جب ہوش میں آیا بولا تیری ذات پاک ہے میں نے توبہ کی تیری طرف اور میں سب سے پہلے یقین لایا [۱۷۱]', 'And when Moosa (Moses) came at the time and place appointed by Us, and his Lord spoke to him, he said: \"O my Lord! Show me (Yourself), that I may look upon You.\" Allah said: \"You cannot see Me, but look upon the mountain if it stands still in its place then you shall see Me.\" So when his Lord appeared to the mountain, He made it collapse to dust, and Moosa (Moses) fell down unconscious. Then when he recovered his senses he said: \"Glory be to You, I turn to You in repentance and I am the first of the believers.\"', 'When Mūsā came at Our appointed time and his Lord spoke to him, he said, “My Lord, show (Yourself) to me that I may look at You.” He said: “You shall never see Me. But look at the mount. If it stays at its place, you will see Me.” So when his Lord appeared to the Mount, He made it smashed, and Mūsā fell down unconscious. When he recovered, he said: “Pure are You. I repent to You, and I am the first to believe (that no one can see You in this world.)”'),
(1098, 7, 144, 17, 7, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قَالَ یٰمُوۡسٰۤی  اِنِّی  اصۡطَفَیۡتُکَ عَلَی النَّاسِ بِرِسٰلٰتِیۡ  وَ بِکَلَامِیۡ ۫ۖ فَخُذۡ مَاۤ اٰتَیۡتُکَ  وَ  کُنۡ  مِّنَ  الشّٰکِرِیۡنَ ﴿۱۴۴﴾', 'فرمایا اے موسٰی میں نے تم کو اپنے پیغام اور اپنے کلام سے نواز کر لوگوں سے ممتاز کیا ہے۔ تو جو میں نے تم کو عطا کیا ہے اسے تھامے رکھو اور میرا شکر بجا لاؤ۔', 'فرمایا اے موسٰی میں نے تجھ کو امتیاز دیا لوگوں سے اپنے پیغام بھیجنے کا اور اپنے کلام کرنے کا سو لے جو میں نے تجھ کو دیا اور شاکر رہ [۱۷۲]', '(Allah) said: \"O Moosa (Moses) I have chosen you above men by My Messages, and by My speaking (to you). So hold that which I have given you and be of the grateful.\"', 'He said, “Mūsā, I have chosen you above all men for my messages and for My speaking (to you). So, take what I have given to you, and be among the grateful.”'),
(1099, 7, 145, 17, 7, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ کَتَبۡنَا لَہٗ  فِی الۡاَلۡوَاحِ  مِنۡ کُلِّ شَیۡءٍ مَّوۡعِظَۃً  وَّ تَفۡصِیۡلًا  لِّکُلِّ شَیۡءٍ ۚ فَخُذۡہَا بِقُوَّۃٍ  وَّ اۡمُرۡ قَوۡمَکَ یَاۡخُذُوۡا بِاَحۡسَنِہَا ؕ سَاُورِیۡکُمۡ  دَارَ الۡفٰسِقِیۡنَ ﴿۱۴۵﴾', 'اور ہم نے تورات کی تختیوں میں انکے لئے ہر قسم کی نصیحت اور ہر چیز کی تفصیل لکھ دی پھر ارشاد فرمایا کہ اسے مضبوطی سے تھامے رہو اور اپنی قوم سے بھی کہہ دو کہ ان باتوں پر بہت اچھی طرح عمل کریں میں عنقریب تم کو نافرمان لوگوں کا گھر دکھاؤں گا۔', 'اور لکھ دی ہم نے اس کو تختیوں پر ہر قسم کی نصیحت اور تفصیل ہر چیز کی [۱۷۳] سو پکڑ لے انکو زور سے اور حکم کر اپنی قوم کو کہ پکڑے رہیں اس کی بہتر باتیں عنقریب میں تم کو دکھلاؤں گا گھر نافرمانوں کا [۱۷۴]', 'And We wrote for him on the Tablets the lesson to be drawn from all things and the explanation of all things (and said): Hold unto these with firmness, and enjoin your people to take the better therein. I shall show you the home of Al-Fasiqoon (the rebellious, disobedient to Allah).', 'We wrote for him on the Tablets advice of every kind, and explanations of all (needful) things. “So hold it firm, and ask your people to hold on to the best things in it. I shall show you the house of the sinners.'),
(1100, 7, 146, 17, 7, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'سَاَصۡرِفُ عَنۡ اٰیٰتِیَ الَّذِیۡنَ یَتَکَبَّرُوۡنَ فِی الۡاَرۡضِ بِغَیۡرِ الۡحَقِّ ؕ وَ  اِنۡ یَّرَوۡا کُلَّ اٰیَۃٍ  لَّا یُؤۡمِنُوۡا بِہَا ۚ وَ اِنۡ یَّرَوۡا سَبِیۡلَ الرُّشۡدِ لَا یَتَّخِذُوۡہُ سَبِیۡلًا ۚ وَ اِنۡ  یَّرَوۡا سَبِیۡلَ الۡغَیِّ یَتَّخِذُوۡہُ سَبِیۡلًا ؕ ذٰلِکَ بِاَنَّہُمۡ کَذَّبُوۡا بِاٰیٰتِنَا وَ کَانُوۡا عَنۡہَا غٰفِلِیۡنَ ﴿۱۴۶﴾', 'جو لوگ زمین میں ناحق تکبر کرتے ہیں انکو اپنی آیتوں سے پھیر دوں گا۔ اگر یہ سب نشانیاں بھی دیکھ لیں تب بھی ان پر ایمان نہ لائیں اور اگر بھلائی کا رستہ دیکھیں تو اسے اپنا رستہ نہ بنائیں۔ اور اگر برائی کی راہ دیکھیں تو اسے رستہ بنا لیں۔ یہ اس لئے کہ انہوں نے ہماری آیات کو جھٹلایا اور ان سے غفلت کرتے رہے۔', 'میں پھیر دوں گا اپنی آیتوں سے انکو جو تکبر کرتے ہیں زمین میں ناحق اور اگر دیکھ لیں ساری نشانیاں ایمان نہ لائیں ان پر اور اگر دیکھیں رستہ ہدایت کا تو نہ ٹھہرائیں اس کو راہ اور اگر دیکھیں رستہ گمراہی کا تو اس کو ٹھہرا لیں راہ یہ اس لئے کہ انہوں نے جھوٹ جانا ہماری آیتوں کو اور رہے ان سے بے خبر [۱۷۵]', 'I shall turn away from My Ayat (verses of the Quran) those who behave arrogantly on the earth, without a right, and (even) if they see all the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), they will not believe in them. And if they see the way of righteousness (monotheism, piety, and good deeds), they will not adopt it as the Way, but if they see the way of error (polytheism, crimes and evil deeds), they will adopt that way, that is because they have rejected Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) and were heedless (to learn a lesson) from them.', 'I shall keep away from My verses those who show arrogance on the earth with no right to do so. Even if they were to see every sign, they would not believe in it; and if they see the Path of guidance, they do not take it as their way; and if they see the path of misguidance, they would take it as their way. That is because they have rejected Our signs, and have been neglectful of them.'),
(1101, 7, 147, 17, 7, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ الَّذِیۡنَ  کَذَّبُوۡا بِاٰیٰتِنَا وَ  لِقَآءِ  الۡاٰخِرَۃِ حَبِطَتۡ اَعۡمَالُہُمۡ ؕ ہَلۡ  یُجۡزَوۡنَ  اِلَّا  مَا  کَانُوۡا  یَعۡمَلُوۡنَ ﴿۱۴۷﴾٪', 'اور جن لوگوں نے ہماری آیتوں اور آخرت کی پیشی کو جھٹلایا انکے اعمال ضائع ہو جائیں گے۔ یہ جیسے عمل کرتے ہیں ویسا ہی انکو بدلہ ملے گا۔', 'اور جنہوں نے جھوٹ جانا ہماری آیتوں کو اور آخرت کی ملاقات کو برباد ہوئیں ان کی محنتیں وہی بدلا پائیں گے جو کچھ عمل کرتے تھے [۱۷۶]', 'Those who deny Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) and the Meeting in the Hereafter (Day of Resurrection,), vain are their deeds. Do they expect to be rewarded with anything except what they used to do?', 'Gone to waste are the deeds of those who have rejected Our signs and the meeting of the Hereafter. They will be recompensed only for what they have been doing.'),
(1102, 7, 148, 18, 8, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اتَّخَذَ قَوۡمُ  مُوۡسٰی مِنۡۢ بَعۡدِہٖ مِنۡ حُلِیِّہِمۡ عِجۡلًا جَسَدًا لَّہٗ خُوَارٌ ؕ اَلَمۡ یَرَوۡا اَنَّہٗ  لَا یُکَلِّمُہُمۡ وَ لَا یَہۡدِیۡہِمۡ سَبِیۡلًا ۘ اِتَّخَذُوۡہُ   وَ کَانُوۡا ظٰلِمِیۡنَ ﴿۱۴۸﴾', 'اور موسٰی کے بعد انکی قوم نے اپنے زیور سے ایک بچھڑا بنا لیا وہ ایک جسم تھا جس میں سے بیل کی آواز نکلتی تھی۔ ان لوگوں نے یہ نہ دیکھا کہ وہ نہ ان سے بات کر سکتا ہے اور نہ انکو رستہ دکھا سکتا ہے۔ اسکو انہوں نے معبود بنا لیا اور اپنے حق میں ظلم کیا۔', 'اور بنا لیا موسٰی کی قوم نے اس کے پیچھے اپنے زیور سے بچھڑا [۱۷۷] ایک بدن کہ اسمیں گائے کی آواز تھی کیا انہوں نے یہ نہ دیکھا کہ وہ ان سے بات بھی نہیں کرتاا ور نہیں بتلاتا رستہ معبود بنا لیا اس کو اور وہ تھے ظالم [۱۷۸]', 'And the people of Moosa (Moses) made in his absence, out of their ornaments, the image of a calf (for worship). It had a sound (as if it was mooing). Did they not see that it could neither speak to them nor guide them to the way? They took it for worship and they were Zalimoon (wrong-doers).', 'And in the absence of Mūsā, his people made a calf from their ornaments, which was merely a sculpture with a moaning sound. Did they not see that it neither talked to them nor could it guide them to any way? They adopted it (as god), and were so unjust.'),
(1103, 7, 149, 18, 8, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ لَمَّا سُقِطَ فِیۡۤ  اَیۡدِیۡہِمۡ وَ رَاَوۡا اَنَّہُمۡ قَدۡ ضَلُّوۡا ۙ قَالُوۡا لَئِنۡ لَّمۡ  یَرۡحَمۡنَا رَبُّنَا وَ یَغۡفِرۡ لَنَا لَنَکُوۡنَنَّ مِنَ الۡخٰسِرِیۡنَ ﴿۱۴۹﴾', 'اور جب وہ نادم ہوئے اور دیکھا کہ گمراہ ہو گئے ہیں تو کہنے لگے کہ اگر ہمارا پروردگار ہم پر رحم نہیں کرے گا اور ہم کو معاف نہیں فرمائے گا تو ہم برباد ہو جائیں گے۔', 'اور جب پچتائے اور سمجھے کہ ہم بیشک گمراہ ہو گئے تو کہنے لگے اگر نہ رحم کرے ہم پر ہمارا رب اور نہ بخشے ہم کو تو بیشک ہم تباہ ہوں گے [۱۷۹]', 'And when they regretted and saw that they had gone astray, they (repented and) said: \"If our Lord have not mercy upon us and forgive us, we shall certainly be of the losers.\"', 'When they became remorseful and saw that they had gone astray, they said, “If Allah shows no mercy to us, and does not forgive us, we shall certainly be among the losers.”'),
(1104, 7, 150, 18, 8, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ لَمَّا رَجَعَ مُوۡسٰۤی اِلٰی قَوۡمِہٖ غَضۡبَانَ اَسِفًا ۙ قَالَ بِئۡسَمَا خَلَفۡتُمُوۡنِیۡ  مِنۡۢ بَعۡدِیۡ ۚ اَعَجِلۡتُمۡ اَمۡرَ رَبِّکُمۡ ۚ وَ اَلۡقَی الۡاَلۡوَاحَ وَ اَخَذَ بِرَاۡسِ اَخِیۡہِ یَجُرُّہٗۤ اِلَیۡہِ ؕ قَالَ ابۡنَ اُمَّ  اِنَّ  الۡقَوۡمَ اسۡتَضۡعَفُوۡنِیۡ  وَ کَادُوۡا یَقۡتُلُوۡنَنِیۡ ۫ۖ فَلَا تُشۡمِتۡ بِیَ الۡاَعۡدَآءَ وَ لَا تَجۡعَلۡنِیۡ مَعَ  الۡقَوۡمِ  الظّٰلِمِیۡنَ ﴿۱۵۰﴾', 'اور جب موسٰی اپنی قوم میں نہایت غصے اور افسوس کی حالت میں واپس آئے تو کہنے لگے کہ تم نے میرے بعد بہت ہی برا کام کیا۔ کیا تم نے اپنے پروردگار کا حکم جلد چاہا یہ کہا اور شدت غضب سے تورات کی تختیاں ڈالدیں اور اپنے بھائی کا سر پکڑ کر اپنی طرف کھینچنے لگے۔ انہوں نے کہا کہ بھائی جان لوگ تو مجھے کمزور سمجھتے تھے اور قریب تھا کہ قتل کر دیں۔ تو ایسا کام نہ کیجئے کہ دشمن مجھ پر ہنسیں اور مجھے ظالم لوگوں میں شامل نہ سمجھئے۔', 'اور جب لوٹ آیا موسٰی اپنی قوم میں غصہ میں بھرا ہوا افسوسناک [۱۸۰] بولا کیا بری نیابت کی تم نے میری میرےبعد [۱۸۱] کیوں جلدی کی تم نےاپنے رب کےحکم سے [۱۸۲] اور ڈالدیں وہ تختیاں اور پکڑا سر اپنے بھائی کا لگا کھینچنے اس کو اپنی طرف [۱۸۳] وہ بولا کہ اے میری ماں کے جنے لوگوں نے مجھ کو کمزور سمجھا اور قریب تھے کہ مجھ کو مار ڈالیں سو مت ہنسا مجھ پر دشمنوں کو اور نہ ملا مجھ کو گنہگار لوگوں میں [۱۸۴]', 'And when Moosa (Moses) returned to his people, angry and grieved, he said: \"What an evil thing is that which you have done (i.e. worshipping the calf) during my absence. Did you hasten and go ahead as regards the matter of your Lord (you left His worship)?\" And he threw down the Tablets and seized his brother by (the hair of) his head and dragged him towards him. Haroon (Aaron) said: \"O son of my mother! Indeed the people judged me weak and were about to kill me, so make not the enemies rejoice over me, nor put me amongst the people who are Zalimoon (wrong-doers).\"', 'When Mūsā returned to his people, angry and sad, he said, “How bad is the thing you have done in my absence! How did you act in haste against the command of your Lord?” He dropped down the Tablets, and grabbed the head of his brother, pulling him towards himself. He (Hārūn) said, “My mother’s son, the people took me as weak and were about to kill me. So do not let the enemies laugh at me, and do not count me with the wrong-doers.”'),
(1105, 7, 151, 18, 8, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قَالَ رَبِّ اغۡفِرۡ لِیۡ وَ لِاَخِیۡ وَ اَدۡخِلۡنَا فِیۡ رَحۡمَتِکَ ۫ۖ وَ اَنۡتَ اَرۡحَمُ الرّٰحِمِیۡنَ ﴿۱۵۱﴾٪', 'انہوں نے دعا کی کہ اے پروردگار مجھے اور میرے بھائی کو معاف کر دے اور ہمیں اپنی رحمت میں داخل کر تو سب سے بڑھ کر رحم کرنے والا ہے۔', 'بولا اے میرے رب معاف کر مجھ کو اور میرے بھائی کو اور داخل کر ہم کو اپنی رحمت میں اور تو سب سے زیادہ رحم کرنے والا ہے [۱۸۵]', 'Moosa (Moses) said: \"O my Lord! Forgive me and my brother, and make us enter into Your Mercy, for you are the Most Merciful of those who show mercy.\"', 'He said, “My Lord! Forgive me and my brother, and admit us into Your mercy. You are the most Merciful of all the merciful.”'),
(1106, 7, 152, 19, 9, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'اِنَّ الَّذِیۡنَ اتَّخَذُوا الۡعِجۡلَ سَیَنَالُہُمۡ غَضَبٌ مِّنۡ رَّبِّہِمۡ وَ ذِلَّۃٌ فِی الۡحَیٰوۃِ الدُّنۡیَا ؕ وَ کَذٰلِکَ نَجۡزِی الۡمُفۡتَرِیۡنَ ﴿۱۵۲﴾', 'جن لوگوں نے بچھڑے کو معبود بنا لیا تھا ان پر انکے پروردگار کا غضب واقع ہو گا اور دنیا کی زندگی میں ذلت نصیب ہوگی اور ہم افتراپردازوں کو ایسا ہی بدلہ دیا کرتے ہیں۔', 'البتہ جنہوں نے بچھڑے کو معبود بنا لیا ان کو پہنچے گا غصہ ان کے رب کا اور ذلت دنیا کی زندگی میں اور یہی سزا دیتے ہیں ہم بہتان باندھنے والوں کو [۱۸۶]', 'Certainly, those who took the calf (for worship), wrath from their Lord and humiliation will come upon them in the life of this world. Thus do We recompense those who invent lies.', 'Surely, those who have taken the calf (as god) shall be seized by Allah’s wrath and by humiliation in the worldly life. That is how we recompense the fabricators.'),
(1107, 7, 153, 19, 9, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ الَّذِیۡنَ عَمِلُوا السَّیِّاٰتِ ثُمَّ  تَابُوۡا مِنۡۢ بَعۡدِہَا وَ اٰمَنُوۡۤا ۫ اِنَّ رَبَّکَ مِنۡۢ بَعۡدِہَا لَغَفُوۡرٌ رَّحِیۡمٌ ﴿۱۵۳﴾', 'اور جنہوں نے برے کام کئے پھر اسکے بعد توبہ کر لی اور ایمان لے آئے۔ تو کچھ شک نہیں کہ تمہارا پروردگار اس کے بعد بخش دے گا کہ وہ بخشنے والا مہربان ہے۔', 'اور جنہوں نے کئے برے کام پھر توبہ کی اس کے بعد اور ایمان لائے تو بیشک تیرا رب توبہ کے پیچھے البتہ بخشنے والا مہربان ہے [۱۸۷]', 'But those who committed evil deeds and then repented afterwards and believed, verily, your Lord after (all) that is indeed Oft-Forgiving, Most Merciful.', 'As for those who do evil, and repent thereafter, and embrace faith, your Lord is then most forgiving, very merciful (for them).'),
(1108, 7, 154, 19, 9, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ لَمَّا سَکَتَ عَنۡ  مُّوۡسَی الۡغَضَبُ  اَخَذَ الۡاَلۡوَاحَ ۚۖ وَ فِیۡ نُسۡخَتِہَا ہُدًی وَّ رَحۡمَۃٌ  لِّلَّذِیۡنَ ہُمۡ  لِرَبِّہِمۡ یَرۡہَبُوۡنَ ﴿۱۵۴﴾', 'اور جب موسٰی کا غصہ ٹھنڈا ہوا تو تورات کی تختیاں اٹھا لیں۔ اور جو کچھ ان میں لکھا تھا وہ ان لوگوں کے لئے جو اپنے پروردگار سے ڈرتے ہیں ہدایت اور رحمت تھی۔', 'اور جب تھم گیا موسٰی کا غصہ تو اس نے اٹھا لیا تختیوں کو اور جو ان میں لکھا ہوا تھا اس میں ہدایت اور رحمت تھی ان کے واسطے جو اپنے رب سے ڈرتے ہیں', 'And when the anger of Moosa (Moses) was appeased, he took up the Tablets, and in their inscription was guidance and mercy for those who fear their Lord.', 'When the fury of Mūsā calmed down, he picked up the Tablets, and in its contents there was guidance, and mercy for those who are fearful before their Lord.'),
(1109, 7, 155, 19, 9, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اخۡتَارَ مُوۡسٰی قَوۡمَہٗ سَبۡعِیۡنَ رَجُلًا لِّمِیۡقَاتِنَا ۚ فَلَمَّاۤ  اَخَذَتۡہُمُ الرَّجۡفَۃُ قَالَ رَبِّ لَوۡ شِئۡتَ اَہۡلَکۡتَہُمۡ مِّنۡ قَبۡلُ وَ اِیَّایَ ؕ اَتُہۡلِکُنَا بِمَا فَعَلَ السُّفَہَآءُ مِنَّا ۚ اِنۡ ہِیَ  اِلَّا فِتۡنَتُکَ ؕ تُضِلُّ بِہَا مَنۡ تَشَآءُ وَ تَہۡدِیۡ مَنۡ تَشَآءُ ؕ اَنۡتَ وَلِیُّنَا فَاغۡفِرۡ لَنَا وَ ارۡحَمۡنَا وَ  اَنۡتَ  خَیۡرُ  الۡغٰفِرِیۡنَ ﴿۱۵۵﴾', 'اور موسٰی نے اس معیاد پر جو ہم نے مقرر کی تھی اپنی قوم کے ستر آدمی منتخب کر کے کوہ طور پر حاضر کئے۔ پھر جب انکو زلزلے نے آ پکڑا تو موسٰی نے کہا کہ اے پروردگار اگر تو چاہتا تو ان کو اور مجھ کو پہلے ہی سے ہلاک کر دیتا۔ کیا تو اس فعل کی سزا میں جو ہم میں سے بے عقل لوگوں نے کیا ہے ہمیں ہلاک کر دے گا یہ تو تیری آزمائش ہے اس سے تو جس کو چاہے گمراہ رہنے دے اور جسے چاہے ہدایت بخشے تو ہی ہمارا کارساز ہے سو ہمیں ہمارے گناہ بخش دے اور ہم پر رحم کر اور تو سب سے بہتر بخشنے والا ہے۔', 'اور چن لئے موسٰی نے اپنی قوم میں سے ستر مرد ہمارے وعدہ کے وقت پر لانے کو پھر جب ان کو زلزلہ نے پکڑا تو بولا اے رب میرے اگر تو چاہتا تو پہلے ہی ہلاک کر دیتا انکو اور مجھ کو کیا ہم کو ہلاک کرتا ہے اس کام پر جو کیا ہماری قوم کے احمقوں نے یہ سب تیری آزمائش ہے بچلا دے اس میں جسکو تو چاہے اور سیدھا رکھے جس کو چاہے تو ہی ہے ہمارا تھامنے والا سو بخش دے ہم کو اور رحمت کر ہم پر اور تو سب سے بہتر بخشنے والا ہے [۱۸۸]', 'And Moosa (Moses) chose out of his people seventy (of the best) men for Our appointed time and place of meeting, and when they were seized with a violent earthquake, he said: \"O my Lord, if it had been Your Will, You could have destroyed them and me before; would You destroy us for the deeds of the foolish ones among us? It is only Your Trial by which You lead astray whom You will, and keep guided whom You will. You are our Walee (Protector), so forgive us and have Mercy on us, for You are the Best of those who forgive.', 'And Mūsā selected seventy men from his people for Our appointment. Later when the earthquake seized them, he said, “My Lord, had it been Your will, You could have destroyed them earlier, and me too. Would You destroy us for what the foolish among them have done? It is nothing but a trial from You, wherewith you let go astray whom You will, and give guidance to whom You will. You are our protector, so forgive us, and have mercy on us, and You are the best among those who forgive.'),
(1110, 7, 156, 19, 9, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اکۡتُبۡ لَنَا فِیۡ ہٰذِہِ الدُّنۡیَا حَسَنَۃً  وَّ  فِی الۡاٰخِرَۃِ   اِنَّا ہُدۡنَاۤ   اِلَیۡکَ ؕ قَالَ عَذَابِیۡۤ  اُصِیۡبُ  بِہٖ  مَنۡ  اَشَآءُ ۚ وَ رَحۡمَتِیۡ وَسِعَتۡ کُلَّ شَیۡءٍ ؕ فَسَاَکۡتُبُہَا لِلَّذِیۡنَ یَتَّقُوۡنَ وَ یُؤۡتُوۡنَ الزَّکٰوۃَ وَ الَّذِیۡنَ ہُمۡ بِاٰیٰتِنَا یُؤۡمِنُوۡنَ ﴿۱۵۶﴾ۚ', 'اور ہمارے لئے اس دنیا میں بھی بھلائی لکھ دے اور آخرت میں بھی۔ ہم تیری طرف رجوع ہو چکے۔ فرمایا کہ جو میرا عذاب ہے اسے تو جس پر چاہتا ہوں نازل کرتا ہوں اور جو میری رحمت ہے وہ ہر چیز کو شامل ہے۔ میں اسکو ان لوگوں کے لئے لکھ دوں گا جو پرہیزگاری کرتے اور زکوٰۃ دیتے اور ہماری آیتوں پر ایمان رکھتے ہیں۔', 'اور لکھ دے ہمارےلئے اس دنیا میں بھلائی اور آخرت میں ہم نے رجوع کیا تیری طرف فرمایا میرا عذاب ڈالتا ہوں میں اسکو جس پر چاہوں اور میری رحمت شامل ہے ہر چیز کو سو اس کو لکھ دوں گا ان کے لئے جو ڈر  رکھتے ہیں اور دیتے ہیں زکوٰۃ اور جو ہماری باتوں پر یقین رکھتے ہیں [۱۸۹]', 'And ordain for us good in this world, and in the Hereafter. Certainly we have turned unto You.\" He said: (As to) My Punishment I afflict therewith whom I will and My Mercy embraces all things. That (Mercy) I shall ordain for those who are the Muttaqoon (pious - see V.2:2), and give Zakat; and those who believe in Our Ayat (proofs, evidences, verses, lessons, signs and revelations, etc.);', 'And write for us good in this world and in the Hereafter. We turn to You in repentance.” He (Allah) said, “As for My punishment, I afflict with it whom I will. And My mercy extends to everything. So, I shall write it for those who guard themselves against evil, and pay Zakāh, and those who do believe in Our verses,'),
(1111, 7, 157, 19, 9, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'اَلَّذِیۡنَ یَتَّبِعُوۡنَ الرَّسُوۡلَ النَّبِیَّ الۡاُمِّیَّ الَّذِیۡ یَجِدُوۡنَہٗ مَکۡتُوۡبًا عِنۡدَہُمۡ فِی التَّوۡرٰىۃِ وَ الۡاِنۡجِیۡلِ ۫ یَاۡمُرُہُمۡ بِالۡمَعۡرُوۡفِ وَ یَنۡہٰہُمۡ عَنِ الۡمُنۡکَرِ وَ یُحِلُّ لَہُمُ الطَّیِّبٰتِ وَ یُحَرِّمُ عَلَیۡہِمُ الۡخَبٰٓئِثَ وَ یَضَعُ عَنۡہُمۡ اِصۡرَہُمۡ وَ الۡاَغۡلٰلَ الَّتِیۡ کَانَتۡ عَلَیۡہِمۡ ؕ فَالَّذِیۡنَ اٰمَنُوۡا بِہٖ  وَ عَزَّرُوۡہُ وَ نَصَرُوۡہُ  وَ اتَّبَعُوا النُّوۡرَ الَّذِیۡۤ اُنۡزِلَ مَعَہٗۤ ۙ اُولٰٓئِکَ  ہُمُ  الۡمُفۡلِحُوۡنَ ﴿۱۵۷﴾٪', 'وہ لوگ جو اس رسول یعنی نبی امّی کی پیروی کرتے ہیں جنکے اوصاف کو وہ اپنے ہاں تورات اور انجیل میں لکھا ہوا پاتے ہیں۔ وہ انہیں نیک کام کا حکم دیتے ہیں۔ اور برے کام سے روکتے ہیں۔ اور پاک چیزوں کو انکے لئے حلال کرتے ہیں اور ناپاک چیزوں کو ان پر حرام ٹھیراتے ہیں اور ان پر سے بوجھ اور طوق جو انکے سر پر اور گلے میں تھے اتارتے ہیں۔ تو جو لوگ ان پر ایمان لائے اور ان کی رفاقت کی اور انہیں مدد دی اور جو نور ان کے ساتھ نازل ہوا ہے اسکی پیروی کی وہی مراد پانے والے ہیں۔', 'وہ لوگ جو پیروی کرتے ہیں اس رسول کی جو نبی امی ہے [۱۹۰] کہ جس کو پاتے ہیں لکھا ہوا اپنے پاس توریت اور انجیل میں [۱۹۱] وہ حکم کرتا ہے ان کو نیک کام کا اور منع کرتا ہے برے کام سے اور حلال کرتا ہے انکے لئے سب پاک چیزیں اور حرام کرتا ہے ان پر ناپاک چیزیں اور اتارتا ہے ان پر سے ان کے بوجھ اور وہ قیدیں جو ان پر تھیں [۱۹۲] سو جو لوگ اس پر ایمان لائے اور اسکی رفاقت کی اور اس کی مدد کی اور تابع ہوئے اس نور کے جو اسکے ساتھ اترا ہے [۱۹۳] وہی لوگ پہنچے اپنی مراد کو', 'Those who follow the Messenger, the Prophet who can neither read nor write (i.e.Muhammad SAW) whom they find written with them in the Taurat (Torah) (Deut, xviii, 15) and the Injeel (Gospel) (John xiv, 16), - he commands them for Al-Maroof (i.e. Islamic Monotheism and all that Islam has ordained); and forbids them from Al-Munkar (i.e. disbelief, polytheism of all kinds, and all that Islam has forbidden); he allows them as lawful At-Taiyibat ((i.e. all good and lawful) as regards things, deeds, beliefs, persons, foods, etc.), and prohibits them as unlawful Al-Khabaith (i.e. all evil and unlawful as regards things, deeds, beliefs, persons, foods, etc.), he releases them from their heavy burdens (of Allahs Covenant), and from the fetters (bindings) that were upon them. So those who believe in him (Muhammad SAW), honour him, help him, and follow the light (the Quran) which has been sent down with him, it is they who will be successful.', 'those who follow the Messenger, the Ummiyy (unlettered) prophet whom they find written with them in the Torah and the Injīl , and who bids them what is fair and forbids what is unfair, and makes lawful for them good things, and makes unlawful for them impure things, and relieves them of their burden, and of the shackles that were upon them. So, those who believe in him and support him, and help him and follow the light sent down with him, - those are the ones who are successful.”'),
(1112, 7, 158, 20, 10, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قُلۡ یٰۤاَیُّہَا النَّاسُ اِنِّیۡ رَسُوۡلُ اللّٰہِ اِلَیۡکُمۡ جَمِیۡعَۨا الَّذِیۡ لَہٗ  مُلۡکُ السَّمٰوٰتِ  وَ الۡاَرۡضِ ۚ لَاۤ اِلٰہَ  اِلَّا ہُوَ یُحۡیٖ وَ یُمِیۡتُ ۪ فَاٰمِنُوۡا  بِاللّٰہِ وَ رَسُوۡلِہِ النَّبِیِّ  الۡاُمِّیِّ  الَّذِیۡ یُؤۡمِنُ بِاللّٰہِ وَ کَلِمٰتِہٖ وَ اتَّبِعُوۡہُ  لَعَلَّکُمۡ تَہۡتَدُوۡنَ ﴿۱۵۸﴾', 'اے نبی کہدو کہ لوگو میں تم سب کی طرف اس اللہ کا بھیجا ہوا ہوں جو آسمانوں اور زمین کا بادشاہ ہے۔ اسکے سوا کوئی معبود نہیں وہی زندگانی بخشتا ہے اور وہی موت دیتا ہے۔ تو اللہ پر اور اسکے رسول پیغمبر امی پر جو اللہ پر اور اسکے تمام کلام پر ایمان رکھتے ہیں ایمان لاؤ اور انکی پیروی کرو تاکہ ہدایت پاؤ۔', 'تو کہہ اے لوگو میں رسول ہوں اللہ کا تم سب کی طرف جس کی حکومت ہے آسمانوں اور زمین میں کسی کی بندگی نہیں اسکےسوا وہی جلاتا ہے اور مارتا ہے سو ایمان لاؤ اللہ پر اور اس کے بھیجے ہوئے نبی امی پر جو کہ یقین رکھتا ہے اللہ پر اور اسکے سب کلاموں پر اور اسکی پیروی کرو تاکہ تم راہ پاؤ [۱۹۴]', 'Say (O Muhammad SAW): \"O mankind! Verily, I am sent to you all as the Messenger of Allah - to Whom belongs the dominion of the heavens and the earth. La ilaha illa Huwa (none has the right to be worshipped but He); It is He Who gives life and causes death. So believe in Allah and His Messenger (Muhammad SAW), the Prophet who can neither read nor write (i.e. Muhammad SAW) who believes in Allah and His Words ((this Quran), the Taurat (Torah) and the Injeel (Gospel) and also Allahs Word: \"Be!\" - and he was, i.e. Iesa (Jesus) son of Maryam (Mary), Ç ), and follow him so that you may be guided.\"', '(O Prophet Muhammad) Say, “O people, I am a messenger of Allah (sent) to you from the One to whom belongs the kingdom of the heavens and the earth. There is no god but He. He gives life and brings death. So, believe in Allah and His Messenger, the Ummiyy (unlettered) prophet, who believes in Allah and in His words, and follow him, so that you may find the right path.”'),
(1113, 7, 159, 20, 10, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ  مِنۡ قَوۡمِ مُوۡسٰۤی اُمَّۃٌ یَّہۡدُوۡنَ بِالۡحَقِّ وَ بِہٖ  یَعۡدِلُوۡنَ ﴿۱۵۹﴾', 'اور قوم موسٰی میں کچھ لوگ ایسے بھی ہیں جو حق کا رستہ بتاتے ہیں اور اسی کے مطابق انصاف کرتے ہیں۔', 'اور موسٰی کی قوم میں ایک گروہ ہے جو راہ بتلاتے ہیں حق کی اور اسی کے موافق انصاف کرتے ہیں [۱۹۵]', 'And of the people of Moosa (Moses) there is a community who lead (the men) with truth and establish justice therewith (i.e. judge men with truth and justice).', 'Among the community of Mūsā there are people who guide with truth and do justice thereby.'),
(1114, 7, 160, 20, 10, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ قَطَّعۡنٰہُمُ اثۡنَتَیۡ عَشۡرَۃَ  اَسۡبَاطًا اُمَمًا ؕ وَ  اَوۡحَیۡنَاۤ  اِلٰی مُوۡسٰۤی  اِذِ  اسۡتَسۡقٰىہُ قَوۡمُہٗۤ  اَنِ اضۡرِبۡ بِّعَصَاکَ الۡحَجَرَ ۚ فَانۡۢبَجَسَتۡ مِنۡہُ اثۡنَتَا عَشۡرَۃَ عَیۡنًا ؕ قَدۡ عَلِمَ کُلُّ اُنَاسٍ مَّشۡرَبَہُمۡ ؕ وَ ظَلَّلۡنَا عَلَیۡہِمُ الۡغَمَامَ وَ اَنۡزَلۡنَا عَلَیۡہِمُ الۡمَنَّ وَ السَّلۡوٰی ؕ کُلُوۡا مِنۡ طَیِّبٰتِ مَا رَزَقۡنٰکُمۡ ؕ وَ مَا ظَلَمُوۡنَا وَ لٰکِنۡ  کَانُوۡۤا  اَنۡفُسَہُمۡ یَظۡلِمُوۡنَ ﴿۱۶۰﴾', 'اور ہم نے انکو یعنی بنی اسرائیل کو الگ الگ کر کے بارہ قبیلے اور بڑی بڑی جماعتیں بنا دیا اور جب موسٰی سے انکی قوم نے پانی طلب کیا تو ہم نے ان کی طرف وحی بھیجی کہ اپنی لاٹھی پتھر پر مار دو۔ تو اس میں سے بارہ چشمے پھوٹ نکلے اور سب لوگوں نے اپنا اپنا گھاٹ معلوم کر لیا۔ اور ہم نے ان کے سروں پر بادل کو سائبان بنائے رکھا اور ان پر من و سلوٰی اتارتے رہے۔ اور ان سے کہا کہ جو پاکیزہ چیزیں ہم تمہیں دیتے ہیں انہیں کھاؤ۔ اور ان لوگوں نے ہمارا کچھ نقصان نہیں کیا بلکہ جو نقصان کیا اپنا ہی کیا۔', 'اور جدا جدا کر دیئے ہم نے ان کو بارہ دادوں کی اولاد بڑی بڑی جماعتیں [۱۹۶] اور حکم بھیجا ہم نے موسٰی کو جب پانی مانگا اس سے اس کی قوم نے کہ مار اپنی لاٹھی اس پتھر پر تو پھوٹ نکلے اس سے بارہ چشمے پہچان لیا ہر قبیلہ نے اپنا گھاٹ اور سایہ کیا ہم نے ان پر ابر کا اور اتارا ہم نے ان پر من اور سلویٰ کھاؤ ستھری چیزیں جو ہم نے روزی دی تم کو اور انہوں نے ہمارا کچھ نہ بگاڑا لیکن اپنا ہی نقصان کرتے رہے', 'And We divided them into twelve tribes (as distinct) nations. We directed Moosa (Moses) by inspiration, when his people asked him for water, (saying): \"Strike the stone with your stick\", and there gushed forth out of it twelve springs: each group knew its own place for water. We shaded them with the clouds and sent down upon them Al-Manna and the quails (saying): \"Eat of the good things with which We have provided you.\" They harmed Us not but they used to harm themselves.', 'And We divided them into twelve tribes, as separate communities, and We revealed to Mūsā when his people asked him for water, “Strike the rock with your staff.” Then twelve springs gushed forth from it. Each tribe came to know their drinking place. We shaded them with the shadow of the clouds. And We sent down to them Mann and Salwā (saying), “Eat of the good things we have provided you.” And they did us no harm, rather they have been harming their own selves.'),
(1115, 7, 161, 20, 10, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اِذۡ قِیۡلَ لَہُمُ اسۡکُنُوۡا ہٰذِہِ الۡقَرۡیَۃَ وَ کُلُوۡا مِنۡہَا حَیۡثُ شِئۡتُمۡ وَ قُوۡلُوۡا حِطَّۃٌ وَّ ادۡخُلُوا الۡبَابَ سُجَّدًا نَّغۡفِرۡ لَکُمۡ خَطِیۡٓـٰٔتِکُمۡ ؕ سَنَزِیۡدُ الۡمُحۡسِنِیۡنَ ﴿۱۶۱﴾', 'اور یاد کرو جب ان سے کہا گیا کہ اس شہر میں سکونت اختیار کر لو اور اس میں جہاں سے جی چاہے کھانا پینا اور ہاں شہر میں جانا تو حِطَّۃٌ کہنا اور دروازے میں داخل ہونا تو سجدہ کرتے ہوئے۔ تو ہم تمہارے گناہ معاف کردیں گے اور نیکی کرنے والوں کو اور زیادہ دیں گے۔', 'اور جب حکم ہوا ان کو کہ بسو اس شہر میں [۱۹۷] اور کھاؤ اس میں جہاں سے چاہو اور کہو ہم کو بخش دے اور داخل ہو دروازہ میں سجدہ کرتے ہوئے تو بخشدیں گے ہم تمہاری خطائیں البتہ زیادہ دیں گے ہم نیکی کرنے والوں کو [۱۹۸]', 'And (remember) when it was said to them: \"Dwell in this town (Jerusalem) and eat therefrom wherever you wish, and say, (O Allah) forgive our sins; and enter the gate prostrate (bowing with humility). We shall forgive you your wrong-doings. We shall increase (the reward) for the good-doers.\"', '(Recall) when it was said to them, “Live in this town and eat therefrom anywhere you like, and say, HiTTah (we seek forgiveness) and enter the gate prostrating yourselves, so that We forgive your errors. We shall give much more to those who are good in their deeds.”'),
(1116, 7, 162, 20, 10, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'فَبَدَّلَ الَّذِیۡنَ ظَلَمُوۡا مِنۡہُمۡ  قَوۡلًا غَیۡرَ الَّذِیۡ قِیۡلَ لَہُمۡ فَاَرۡسَلۡنَا عَلَیۡہِمۡ رِجۡزًا مِّنَ السَّمَآءِ بِمَا کَانُوۡا یَظۡلِمُوۡنَ ﴿۱۶۲﴾٪', 'مگر جو ان میں ظالم تھے انہوں نے اس لفظ کو جس کا انکو حکم دیا گیا تھا بدل کر اسکی جگہ اور لفظ کہنا شروع کیا تو ہم نے ان پر آسمان سے عذاب بھیجا اس لئے کہ وہ ظلم کرتے تھے۔', 'سو بدل ڈالا ظالموں نے ان میں سے دوسرا لفظ اسکے سوا جو ان سے کہہ دیا گیا تھا پھر بھیجا ہم نے ان پر عذاب آسمان سے بسبب ان کی شرارت کے [۱۹۹]', 'But those among them who did wrong changed the word that had been told to them. So We sent on them a torment from heaven in return for their wrong-doings.', 'But those of them who were unjust substituted another word for the one that was said to them. So, We sent down upon them a scourge from the heavens, because they had been transgressing.'),
(1117, 7, 163, 21, 11, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ سۡـَٔلۡہُمۡ عَنِ الۡقَرۡیَۃِ  الَّتِیۡ کَانَتۡ حَاضِرَۃَ  الۡبَحۡرِ ۘ اِذۡ یَعۡدُوۡنَ فِی السَّبۡتِ اِذۡ تَاۡتِیۡہِمۡ حِیۡتَانُہُمۡ یَوۡمَ سَبۡتِہِمۡ شُرَّعًا وَّ یَوۡمَ لَا یَسۡبِتُوۡنَ ۙ لَا  تَاۡتِیۡہِمۡ ۚۛ کَذٰلِکَ ۚۛ نَبۡلُوۡہُمۡ بِمَا کَانُوۡا یَفۡسُقُوۡنَ ﴿۱۶۳﴾', 'اور ان سے اس گاؤں کا حال تو پوچھو جو لب دریا واقع تھا۔ جب وہ لوگ ہفتے کے دن کے بارے میں حد سے تجاوز کرنے لگے جبکہ انکے تعطیل کے دن یعنی سنیچر کو مچھلیاں انکے سامنے پانی کے اوپر آتیں اور جب ہفتے کا دن نہ ہوتا تو نہ آتیں۔ اسی طرح ہم ان لوگوں کو انکی نافرمانیوں کے سبب آزمائش میں ڈالنے لگے۔', 'اور پوچھ ان سےحال اس بستی کا جو تھی دریا کے کنارے [۲۰۰] جب حد سے بڑھنے لگے ہفتہ کے حکم میں جب آنے لگیں انکے پاس مچھلیاں ہفتہ کے دن پانی کے اوپر اور جس دن ہفتہ نہ ہو تو نہ آتی تھیں اس طرح ہم نے ان کو آزمایا اس لئے کہ وہ نافرمان تھے [۲۰۱]', 'And ask them (O Muhammad SAW) about the town that was by the sea, when they transgressed in the matter of the Sabbath (i.e. Saturday): when their fish came to them openly on the Sabbath day, and did not come to them on the day they had no Sabbath. Thus We made a trial of them for they used to rebel (see the Quran: V.4:154).', 'Ask them about the town situated by the sea, when they used to transgress in the matter of Sabbath, when their fish came to them openly on the Sabbath, and did not come when they did not have Sabbath. In this way, We put them to a test, because they used to act sinfully.'),
(1118, 7, 164, 21, 11, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اِذۡ قَالَتۡ اُمَّۃٌ مِّنۡہُمۡ لِمَ تَعِظُوۡنَ قَوۡمَۨا ۙ اللّٰہُ مُہۡلِکُہُمۡ اَوۡ مُعَذِّبُہُمۡ عَذَابًا شَدِیۡدًا ؕ قَالُوۡا مَعۡذِرَۃً  اِلٰی رَبِّکُمۡ  وَ لَعَلَّہُمۡ  یَتَّقُوۡنَ ﴿۱۶۴﴾', 'اور جب ان میں سے ایک جماعت نے کہا کہ تم ایسے لوگوں کو کیوں نصیحت کرتے ہو جنکو اللہ ہلاک کرنے والا یا سخت عذاب دینے والا ہے تو انہوں نے کہا اس لئے کہ تمہارے پروردگار کے سامنے معذرت کر سکیں اور عجب نہیں کہ وہ پرہیزگاری اختیار کریں۔', 'اور جب بولا ان میں سے ایک فرقہ کیوں نصیحت کرتے ہو ان لوگوں کو جنکو اللہ چاہتا ہےکہ ہلاک کرے یا ان کو عذاب دے سخت [۲۰۲] وہ بولے الزام اتارنے کی غرض سے تمہارے رب کے آگے اور اسلئے کہ شاید وہ ڈریں [۲۰۳]', 'And when a community among them said: \"Why do you preach to a people whom Allah is about to destroy or to punish with a severe torment?\" (The preachers) said: \"In order to be free from guilt before your Lord (Allah), and perhaps they may fear Allah.\"', 'When a group of them said, “Why do you exhort a people whom Allah is going to destroy or chastise with a severe punishment?” They said, “To absolve ourselves before your Lord, and in order that they may fear Allah.”'),
(1119, 7, 165, 21, 11, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'فَلَمَّا نَسُوۡا مَا ذُکِّرُوۡا بِہٖۤ اَنۡجَیۡنَا الَّذِیۡنَ یَنۡہَوۡنَ عَنِ السُّوۡٓءِ وَ اَخَذۡنَا الَّذِیۡنَ ظَلَمُوۡا بِعَذَابٍۭ بَئِیۡسٍۭ بِمَا کَانُوۡا  یَفۡسُقُوۡنَ ﴿۱۶۵﴾', 'پھر جب انہوں نے ان باتوں کر فراموش کر دیا جنکی انکو نصیحت کی گئ تھی تو جو لوگ برائی سے منع کرتے تھے انکو ہم نے نجات دی اور جو ظلم کرتے تھے انکو برے عذاب میں پکڑ لیا کہ نافرمانی کئے جاتے تھے۔', 'پھر جب  وہ بھول گئے اس کو جو انکو سمجھایا تھا تو نجات دی ہم نے ان کو جو منع کرتے تھے برے کام سے اور پکڑا گنہگاروں کو  برے عذاب میں بسبب ان کی نافرمانی کے [۲۰۴]', 'So when they forgot the remindings that had been given to them, We rescued those who forbade evil, but We seized those who did wrong with a severe torment because they used to rebel (disobey Allah).', 'So, when they forgot the advice they were given, We saved those who used to forbid evil and seized those who transgressed with a bitter punishment, because they had been disobeying.'),
(1120, 7, 166, 21, 11, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'فَلَمَّا عَتَوۡا عَنۡ مَّا نُہُوۡا عَنۡہُ قُلۡنَا لَہُمۡ   کُوۡنُوۡا  قِرَدَۃً  خٰسِئِیۡنَ ﴿۱۶۶﴾', 'غرض جن اعمال بد سے انکو منع کیا گیا تھا جب وہ ان پر اصرار اور سرکشی کرنے لگے تو ہم نے انکو حکم دیا کہ ذلیل بندر ہو جاؤ۔', 'پھر جب بڑھنےلگےاس کام میں جس سے وہ روکے گئے تھے تو ہم نے حکم کیا کہ ہو جاؤ بندر ذلیل [۲۰۵]', 'So when they exceeded the limits of what they were prohibited, We said to them: \"Be you monkeys, despised and rejected.\" (It is a severe warning to the mankind that they should not disobey what Allah commands them to do, and be far away from what He prohibits them).', 'When they persisted in doing what they were forbidden from, We said to them, “Become apes debased.”'),
(1121, 7, 167, 21, 11, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اِذۡ تَاَذَّنَ رَبُّکَ لَیَبۡعَثَنَّ عَلَیۡہِمۡ اِلٰی یَوۡمِ الۡقِیٰمَۃِ مَنۡ یَّسُوۡمُہُمۡ سُوۡٓءَ الۡعَذَابِ ؕ اِنَّ  رَبَّکَ  لَسَرِیۡعُ  الۡعِقَابِ ۚۖ وَ  اِنَّہٗ  لَغَفُوۡرٌ  رَّحِیۡمٌ ﴿۱۶۷﴾', 'اور اس وقت کو یاد کرو جب تمہارے پروردگار نے یہود کو آگاہ کر دیا تھا کہ وہ ان پر قیامت تک ایسے شخص کو مسلط رکھے گا جو انکو بری بری تکلیفیں دیتا رہے۔ بیشک تمہارا پروردگار جلد عذاب کرنے والا ہے اور وہ بخشنے والا مہربان بھی ہے۔', 'اور اس وقت کو یاد کرو جب خبر کر دی تھی تیرے رب نے کہ ضرور بھیجتا رہے گا یہود پر قیامت کے دن تک ایسے شخص کو کہ دیا کرے ان کو برا عذاب [۲۰۶] بیشک تیرا رب جلد عذاب کرنے والا ہے اور وہ بخشنے والا مہربان ہے [۲۰۷]', 'And (remember) when your Lord declared that He would certainly keep on sending against them (i.e. the Jews), till the Day of Resurrection, those who would afflict them with a humiliating torment. Verily, your Lord is Quick in Retribution (for the disobedient, wicked) and certainly He is OftForgiving, Most Merciful (for the obedient and those who beg Allahs Forgiveness).', 'Recall) when your Lord declared that He would surely keep sending, till the Day of Judgment, those who inflict on them evil chastisement. Certainly, your Lord is swift in punishing, and certainly He is the Most-forgiving, Very Merciful.'),
(1122, 7, 168, 21, 11, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ قَطَّعۡنٰہُمۡ فِی الۡاَرۡضِ اُمَمًا ۚ مِنۡہُمُ الصّٰلِحُوۡنَ وَ مِنۡہُمۡ دُوۡنَ ذٰلِکَ ۫ وَ بَلَوۡنٰہُمۡ بِالۡحَسَنٰتِ وَ السَّیِّاٰتِ لَعَلَّہُمۡ یَرۡجِعُوۡنَ ﴿۱۶۸﴾', 'اور ہم نے انکو جماعت جماعت کر کے ملک میں منتشر کر دیا۔ بعض ان میں سے نیکوکار ہیں اور بعض اور طرح کے یعنی بدکار اور ہم آسائشوں اور تکلیفوں دونوں سے انکی آزمائش کرتے رہے تاکہ ہماری طرف رجوع کریں۔', 'اور متفرق کر دیا ہم نے ان کو ملک میں فرقے فرقے [۲۰۸] بعضے ان میں نیک اور بعضے اور طرح کے اور ہم نے انکی آزمائش کی خوبیوں میں او ربرائیوں میں تاکہ وہ پھر آئیں [۲۰۹]', 'And We have broken them (i.e. the Jews) up into various separate groups on the earth, some of them are righteous and some are away from that. And We tried them with good (blessings) and evil (calamities) in order that they might turn (to Allahs Obedience).', 'We divided them on the earth as separate communities. Some of them were righteous, while some others were otherwise. We tested them with good and bad times, so that they might return.'),
(1123, 7, 169, 21, 11, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'فَخَلَفَ مِنۡۢ بَعۡدِہِمۡ خَلۡفٌ وَّرِثُوا الۡکِتٰبَ یَاۡخُذُوۡنَ عَرَضَ ہٰذَا الۡاَدۡنٰی وَ یَقُوۡلُوۡنَ سَیُغۡفَرُ لَنَا ۚ وَ اِنۡ یَّاۡتِہِمۡ عَرَضٌ مِّثۡلُہٗ یَاۡخُذُوۡہُ ؕ اَلَمۡ یُؤۡخَذۡ عَلَیۡہِمۡ مِّیۡثَاقُ الۡکِتٰبِ اَنۡ لَّا یَقُوۡلُوۡا عَلَی اللّٰہِ  اِلَّا الۡحَقَّ وَ دَرَسُوۡا مَا فِیۡہِ  ؕ وَ الدَّارُ  الۡاٰخِرَۃُ  خَیۡرٌ لِّلَّذِیۡنَ  یَتَّقُوۡنَ ؕ اَفَلَا  تَعۡقِلُوۡنَ ﴿۱۶۹﴾', 'پھر انکے بعد ناخلف انکے قائم مقام ہوئے جو کتاب کے وارث بنے یہ لوگ اس حقیر دنیا کا مال و متاع لے لیتے ہیں اور کہتے ہیں کہ ہم بخش دیئے جائیں گے۔ اور اگر انکے سامنے بھی ویسا ہی مال آ جاتا ہے تو وہ بھی اسے لے لیتے ہیں۔ کیا ان سے کتاب کی نسبت عہد نہیں لیا گیا تھا کہ اللہ پر سچ کے سوا اور کچھ نہیں کہیں گے۔ اور جو کچھ اس کتاب میں ہے اسکو انہوں نے پڑھ بھی لیا ہے۔ اور آخرت کا گھر پرہیزگاروں کے لئے بہتر ہے کیا تم سمجھتے نہیں۔', 'پھر ان کے پیچھے آئے ناخلف جو وارث بنے کتاب کے لے لیتے ہیں اسباب اس ادنیٰ زندگانی کا اور کہتے ہیں کہ ہم کو معاف ہو جائے گا اور اگر ایسا ہی اسباب انکے سامنے پھر آئے تو اسکو لے لیویں [۲۱۰] کیا ان سے کتاب میں عہد نہیں لیا گیا کہ نہ بولیں اللہ پر سوا سچ کے اور انہوں نے پڑھا ہے جو کچھ اسمیں لکھا ہے اور آخرت کا گھر بہتر ہے ڈرنے والوں کے لئے کیا تم سمجھتے نہیں [۲۱۱]', 'Then after them succeeded an (evil) generation, which inherited the Book, but they chose (for themselves) the goods of this low life (evil pleasures of this world) saying (as an excuse): \"(Everything) will be forgiven to us.\" And if (again) the offer of the like (evil pleasures of this world) came their way, they would (again) seize them (would commit those sins). Was not the covenant of the Book taken from them that they would not say about Allah anything but the truth? And they have studied what is in it (the Book). And the home of the Hereafter is better for those who are Al-Muttaqoon (the pious - see V.2:2). Do not you then understand?', 'Then, after them, came a generation that inherited the Book, opting for the mundane stuff of this world and saying, “We shall be forgiven.” But if there comes to them similar stuff, they would opt for it (again). Was not the covenant of the Book taken from them that they should not say anything but the truth about Allah? They learnt what it contained. Certainly, the Last Abode is better for those who fear Allah. Have you then, no sense?'),
(1124, 7, 170, 21, 11, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ الَّذِیۡنَ یُمَسِّکُوۡنَ بِالۡکِتٰبِ وَ اَقَامُوا الصَّلٰوۃَ ؕ اِنَّا لَا نُضِیۡعُ اَجۡرَ الۡمُصۡلِحِیۡنَ ﴿۱۷۰﴾', 'اور جو لوگ کتاب کو مضبوط پکڑے ہوئے ہیں اور نماز کا اہتمام کرتے ہیں انکو ہم اجر دیں گے کہ ہم نیکوکاروں کا اجر ضائع نہیں کرتے۔', 'اور جو لوگ خوب پکڑ رہے ہیں کتاب کو اور قائم رکھتے ہیں نماز کو بیشک ہم ضائع نہ کریں گے ثواب نیکی والوں کا [۲۱۲]', 'And as to those who hold fast to the Book (i.e. act on its teachings) and perform As-Salat (Iqamat-as-Salat), certainly, We shall never waste the reward of those who do righteous deeds.', 'Those who hold fast to the Book and establish Salāh, We shall never let the reward of (such) righteous people to go to waste.'),
(1125, 7, 171, 21, 11, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اِذۡ نَتَقۡنَا الۡجَبَلَ فَوۡقَہُمۡ کَاَنَّہٗ ظُلَّۃٌ وَّ ظَنُّوۡۤا اَنَّہٗ وَاقِعٌۢ بِہِمۡ ۚ خُذُوۡا مَاۤ اٰتَیۡنٰکُمۡ بِقُوَّۃٍ وَّ اذۡکُرُوۡا مَا فِیۡہِ لَعَلَّکُمۡ  تَتَّقُوۡنَ ﴿۱۷۱﴾٪', 'اور جب ہم نے ان کے سروں پر پہاڑ اٹھا کھڑا کیا گویا وہ سائبان تھا اور انہوں نے خیال کیا کہ وہ ان پر گرتا ہے۔ تو ہم نے کہا کہ جو ہم نے تمہیں دیا ہے اسے زور سے پکڑے رہو اور جو اس میں لکھا ہے اسے یاد رکھو تاکہ پرہیزگار بن جاؤ۔', 'اور جس وقت اٹھایا ہم نے پہاڑ ان کے اوپر مثل سائبان کے اور ڈرے کہ وہ ان پر گرے گا ہم نے کہا پکڑو جو ہم نے تم کو دیا ہے زور سے اور یاد رکھو جو اس میں ہے تاکہ تم بچتے رہو [۲۱۳]', 'And (remember) when We raised the mountain over them as if it had been a canopy, and they thought that it was going to fall on them. (We said): \"Hold firmly to what We have given you (i.e. the Taurat (Torah)), and remember that which is therein (act on its commandments), so that you may fear Allah and obey Him.\"', 'When We raised the mountain over them as though it were a canopy, and they thought it was falling upon them, (We said,) “Adhere firmly to what We have given you and remember what is therein, so that you may become God-fearing.”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1126, 7, 172, 22, 12, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اِذۡ اَخَذَ رَبُّکَ مِنۡۢ بَنِیۡۤ اٰدَمَ مِنۡ ظُہُوۡرِہِمۡ ذُرِّیَّتَہُمۡ وَ اَشۡہَدَہُمۡ عَلٰۤی اَنۡفُسِہِمۡ ۚ اَلَسۡتُ بِرَبِّکُمۡ ؕ قَالُوۡا بَلٰی ۚۛ شَہِدۡنَا ۚۛ اَنۡ تَقُوۡلُوۡا یَوۡمَ  الۡقِیٰمَۃِ  اِنَّا کُنَّا عَنۡ  ہٰذَا غٰفِلِیۡنَ ﴿۱۷۲﴾ۙ', 'اور جب تمہارے پروردگار نے بنی آدم سے یعنی انکی پیٹھوں سے انکی اولاد نکالی تو ان سے خود انکے مقابلے میں اقرار کرا لیا یعنی ان سے پوچھا کیا میں تمہارا پروردگار نہیں ہوں۔ وہ کہنے لگے کیوں نہیں ہم گواہ ہیں کہ تو ہمارا پروردگار ہے یہ اقرار اس لئے کرایا تھا کہ قیامت کے دن کہیں یوں نہ کہنے لگو کہ ہم کو تو اسکی خبر ہی نہ تھی۔', 'اور جب نکالا تیرے رب نے بنی آدم کی پیٹھوں سے ان کی اولاد کو اور اقرار کرایا ان سے ان کی جانوں پر کیا میں نہیں ہوں تمہارا رب بولے ہاں ہے ہم اقرار کرتے ہیں کبھی کہنے لگو قیامت کے دن ہم کو  تو اس کی خبر نہ تھی', 'And (remember) when your Lord brought forth from the Children of Adam, from their loins, their seed (or from Adams loin his offspring) and made them testify as to themselves (saying): \"Am I not your Lord?\" They said: \"Yes! We testify,\" lest you should say on the Day of Resurrection: \"Verily, we have been unaware of this.\"', '(Recall) when your Lord brought forth their progeny from the loins of the children of ’Ādam, and made them testify about themselves (by asking them,) “Am I not your Lord?” They said, “Of course, You are. We testify.” (We did so) lest you should say on the Day of Judgment, “We were unaware of this,”'),
(1127, 7, 173, 22, 12, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'اَوۡ تَقُوۡلُوۡۤا  اِنَّمَاۤ  اَشۡرَکَ  اٰبَآؤُنَا مِنۡ  قَبۡلُ وَ کُنَّا ذُرِّیَّۃً مِّنۡۢ بَعۡدِہِمۡ ۚ اَفَتُہۡلِکُنَا بِمَا فَعَلَ الۡمُبۡطِلُوۡنَ ﴿۱۷۳﴾', 'یا یہ نہ کہو کہ شرک تو پہلے ہمارے بڑوں نے کیا تھا اور ہم تو انکی اولاد تھے جو ان کے بعد پیدا ہوئے تو کیا جو کام اہل باطل کرتے رہے اسکے بدلے تو ہمیں ہلاک کرتا ہے؟', 'یا کہنے لگو کہ شرک تو نکالا تھا ہمارے باپ دادوں نے ہم سے پہلے اور ہم ہوئے انکی اولاد ان کے پیچھے تو کیا تو ہم کو ہلاک کرتا ہے اس کام پر جو کیا گمراہوں نے [۲۱۴]', 'Or lest you should say: \"It was only our fathers afortime who took others as partners in worship along with Allah, and we were (merely their) descendants after them; will You then destroy us because of the deeds of men who practised Al-Batil (i.e. polytheism and committing crimes and sins, invoking and worshipping others besides Allah)?\" (Tafsir At-Tabaree).', 'or you should say, “It was our forefathers who associated partners with Allah, and we were their progeny after them; would you then destroy us on account of what the erroneous did?”'),
(1128, 7, 174, 22, 12, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ کَذٰلِکَ نُفَصِّلُ الۡاٰیٰتِ وَ لَعَلَّہُمۡ یَرۡجِعُوۡنَ ﴿۱۷۴﴾', 'اور اسی طرح ہم اپنی آیتیں کھول کھول کر بیان کرتے ہیں تاکہ یہ رجوع کریں۔', 'اور یوں ہم کھول کر بیان کرتے ہیں باتیں تاکہ وہ پھر آئیں [۲۱۵]', 'Thus do We explain the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) in detail, so that they may turn (unto the truth).', 'This is how We elaborate the verses, so that they may return.'),
(1129, 7, 175, 22, 12, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اتۡلُ عَلَیۡہِمۡ  نَبَاَ الَّذِیۡۤ  اٰتَیۡنٰہُ  اٰیٰتِنَا فَانۡسَلَخَ مِنۡہَا فَاَتۡبَعَہُ الشَّیۡطٰنُ فَکَانَ مِنَ  الۡغٰوِیۡنَ ﴿۱۷۵﴾', 'اور انکو اس شخص کا حال پڑھ کر سنا دو جسکو ہم نے اپنی آیتیں عطا فرمائیں اور اسکو علم کے لبادے سے آراستہ کیا تو اس نے اسکو اتار پھینکا پھر شیطان اسکے پیچھے لگا تو وہ گمراہوں میں ہو گیا۔', 'اور سنا دے ان کو حال اس شخص کا جسکو ہم نے دی تھیں اپنی آیتیں پھر وہ انکو چھوڑ نکلا پھر اس کے پیچھےلگا شیطان تو وہ ہو گیا گمراہوں میں', 'And recite (O Muhammad SAW) to them the story of him to whom We gave Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), but he threw them away, so Shaitan (Satan) followed him up, and he became of those who went astray.', 'Recite to them the story of the one whom We gave Our verses, then he wriggled out from them, so Satan pursued him and he became one of the perverted.'),
(1130, 7, 176, 22, 12, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ لَوۡ شِئۡنَا لَرَفَعۡنٰہُ بِہَا وَ لٰکِنَّہٗۤ اَخۡلَدَ اِلَی الۡاَرۡضِ وَ اتَّبَعَ ہَوٰىہُ ۚ فَمَثَلُہٗ  کَمَثَلِ الۡکَلۡبِ ۚ اِنۡ  تَحۡمِلۡ عَلَیۡہِ یَلۡہَثۡ اَوۡ تَتۡرُکۡہُ یَلۡہَثۡ ؕ ذٰلِکَ مَثَلُ الۡقَوۡمِ الَّذِیۡنَ کَذَّبُوۡا بِاٰیٰتِنَا ۚ فَاقۡصُصِ الۡقَصَصَ لَعَلَّہُمۡ یَتَفَکَّرُوۡنَ ﴿۱۷۶﴾', 'اور اگر ہم چاہتے تو ان آیتوں سے اس کے درجے کو بلند کر دیتے۔ مگر وہ تو پستی کی طرف مائل ہو گیا اور اپنی خواہش کے پیچھے چل پڑا۔ تو اسکی مثال کتے کی سی ہو گئ کہ اگر اس پر حملہ کرو زبان نکالے رہے یا اسے یونہی چھوڑ دو تو بھی زبان نکالے رہے۔ یہی مثال ان لوگوں کی ہے جنہوں نے ہماری آیتوں کو جھٹلایا تو ان سے یہ قصہ بیان کر دو۔ تاکہ وہ فکر کریں۔', 'اور ہم چاہتے تو بلند کرتے اس کا رتبہ ان آیتوں کی بدولت لیکن وہ تو ہو رہا زمین کا اور پیچھے ہو لیا اپنی خواہش کے تو اس کا حال ایسا جیسے کتا اس پر تو بوجھ لادے تو ہانپے اور چھوڑ دے تو ہانپے یہ مثال ہے ان لوگوں کی جنہوں نے جھٹلایا ہماری آیتوں کو سو بیان کر یہ احوال تاکہ وہ دھیان کریں [۲۱۶]', 'And had We willed, We would surely have elevated him therewith but he clung to the earth and followed his own vain desire. So his description is the description of a dog: if you drive him away, he lolls his tongue out, or if you leave him alone, he (still) lolls his tongue out. Such is the description of the people who reject Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.). So relate the stories, perhaps they may reflect.', 'If We so willed, We would have elevated him thereby; but he clung to the earth and followed his desires. So, his example is like the example of a dog, if you attack him, he pants with his tongue protruding, and if you leave him alone he still pants with his tongue protruding. That is the example of those who rejected Our signs. So, relate the chronicles, so that they may ponder.'),
(1131, 7, 177, 22, 12, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'سَآءَ مَثَلَاۨ الۡقَوۡمُ الَّذِیۡنَ کَذَّبُوۡا بِاٰیٰتِنَا وَ اَنۡفُسَہُمۡ کَانُوۡا یَظۡلِمُوۡنَ ﴿۱۷۷﴾', 'جن لوگوں نے ہماری آیتوں کی تکذیب کی انکی مثال بری ہے اور انہوں نے نقصان کیا تو اپنا ہی کیا۔', 'بری مثال ہے ان لوگوں کی کہ جھٹلایا انہوں نے ہماری آیتوں کو اور وہ اپنا ہی نقصان کرتے رہے [۲۱۷]', 'Evil is the likeness of the people who reject Our Ayat (proofs, evidences, verses and signs, etc.), and used to wrong their ownselves.', 'Evil is the example of those who have rejected Our signs and have been doing wrong to themselves.'),
(1132, 7, 178, 22, 12, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'مَنۡ یَّہۡدِ اللّٰہُ فَہُوَ الۡمُہۡتَدِیۡ ۚ وَ مَنۡ یُّضۡلِلۡ  فَاُولٰٓئِکَ  ہُمُ  الۡخٰسِرُوۡنَ ﴿۱۷۸﴾', 'جسکو اللہ ہدایت دے وہی راہ یاب ہے۔ اور جسکو گمراہ رہنے دے تو ایسے ہی لوگ نقصان اٹھانے والے ہیں۔', 'جس کو اللہ رستہ دے وہی رستہ پاوے اور جس کو وہ بچلا دے سو وہی ہیں ٹوٹے میں [۲۱۸]', 'Whomsoever Allah guides, he is the guided one, and whomsoever He sends astray, those! They are the losers.', 'The one whom Allah gives guidance is the one on the right path. As for those whom Allah lets go astray, those are the losers.'),
(1133, 7, 179, 22, 12, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ لَقَدۡ ذَرَاۡنَا لِجَہَنَّمَ کَثِیۡرًا مِّنَ الۡجِنِّ وَ الۡاِنۡسِ ۫ۖ  لَہُمۡ قُلُوۡبٌ لَّا یَفۡقَہُوۡنَ بِہَا ۫ وَ لَہُمۡ اَعۡیُنٌ لَّا یُبۡصِرُوۡنَ بِہَا ۫ وَ لَہُمۡ اٰذَانٌ لَّا یَسۡمَعُوۡنَ بِہَا ؕ اُولٰٓئِکَ کَالۡاَنۡعَامِ بَلۡ ہُمۡ اَضَلُّ ؕ اُولٰٓئِکَ ہُمُ الۡغٰفِلُوۡنَ ﴿۱۷۹﴾', 'اور ہم نے بہت سے جن اور انسان دوزخ کے لئے پیدا کئے ہیں۔ انکے دل ہیں لیکن ان سے سمجھتے نہیں اور انکی آنکھیں ہیں مگر ان سے دیکھتے نہیں۔ اور ان کے کان ہیں پر ان سے سنتے نہیں۔ یہ لوگ بالکل چوپایوں کی طرح ہیں بلکہ ان سے بھی زیادہ بھٹکے ہوئے۔ یہی وہ ہیں جو غفلت میں پڑے ہوئے ہیں۔', 'اور ہم نے پیدا کئے دوزخ کے واسطے بہت سے جن اور آدمی [۲۱۹] انکے دل ہیں کہ ان سے سمجھتے نہیں  اور آنکھیں ہیں کہ ان سے دیکھتے نہیں اور کان ہیں کہ ان سےسنتے نہیں وہ ایسے ہیں جیسے چوپائے بلکہ ان سے بھی زیادہ بیراہ وہی لوگ ہیں غافل [۲۲۰]', 'And surely, We have created many of the jinns and mankind for Hell. They have hearts wherewith they understand not, they have eyes wherewith they see not, and they have ears wherewith they hear not (the truth). They are like cattle, nay even more astray; those! They are the heedless ones.', 'Surely We have created for Hell a lot of people from among Jinn and mankind. They have hearts wherewith they do not understand, eyes wherewith they do not see, and ears wherewith they do not hear. They are like cattle. Rather, they are much more astray. They are the heedless.'),
(1134, 7, 180, 22, 12, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ لِلّٰہِ الۡاَسۡمَآءُ الۡحُسۡنٰی فَادۡعُوۡہُ بِہَا ۪ وَ ذَرُوا الَّذِیۡنَ یُلۡحِدُوۡنَ فِیۡۤ  اَسۡمَآئِہٖ ؕ سَیُجۡزَوۡنَ مَا کَانُوۡا یَعۡمَلُوۡنَ ﴿۱۸۰﴾', 'اور اللہ کے سب نام اچھے ہی اچھے ہیں تو اسکو انہی ناموں سے پکارا کرو اور جو لوگ اسکے ناموں میں کجی اختیار کرتے ہیں انکو چھوڑ دو۔ وہ جو کچھ کر رہے ہیں عنقریب اسکی سزا پائیں گے۔', 'اور اللہ کےلئے ہیں سب نام اچھے سو اسکو پکارو وہی نام کہہ کر اور چھوڑ دو انکو جو کج راہ چلتے ہیں اس کے ناموں میں وہ بدلہ پا رہیں گے اپنے کئے کا [۲۲۱]', 'And (all) the Most Beautiful Names belong to Allah, so call on Him by them, and leave the company of those who belie or deny (or utter impious speech against) His Names. They will be requited for what they used to do.', 'For Allah there are the most beautiful names. So, call Him by them, and leave those who deviate in (the matter of) His names. They shall be recompensed for what they have been doing.'),
(1135, 7, 181, 22, 12, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ مِمَّنۡ خَلَقۡنَاۤ  اُمَّۃٌ یَّہۡدُوۡنَ بِالۡحَقِّ وَ بِہٖ  یَعۡدِلُوۡنَ ﴿۱۸۱﴾٪', 'اور ہماری مخلوقات میں سے وہ لوگ بھی ہیں جو حق کا رستہ بتاتے ہیں اور اسی کے مطابق انصاف کرتے ہیں۔', 'اور ان لوگوں میں کہ جنکو ہم نے پیدا کیا ہے ایک جماعت ہے کہ راہ بتلاتے ہیں سچی اور اسی کے موافق انصاف کرتےہیں [۲۲۲]', 'And of those whom We have created, there is a community who guides (others) with the truth, and establishes justice therewith.', 'Among those whom We have created there are people who guide with truth and do justice thereby.'),
(1136, 7, 182, 23, 13, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ الَّذِیۡنَ کَذَّبُوۡا بِاٰیٰتِنَا سَنَسۡتَدۡرِجُہُمۡ مِّنۡ حَیۡثُ لَا  یَعۡلَمُوۡنَ ﴿۱۸۲﴾ۚۖ', 'اور جن لوگوں نے ہماری آیتوں کو جھٹلایا انکو ہم بتدریج اس طرح پکڑیں گے کہ انکو معلوم ہی نہیں ہو گا۔', 'اور جنہوں نے جھٹلایا ہماری آیتوں کو ہم ان کو آہستہ آہستہ پکڑیں گے ایسی جگہ سےجہاں سے انکو خبر بھی نہ ہو گی', 'Those who reject Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), We shall gradually seize them with punishment in ways they perceive not.', 'As for those who reject Our signs, We will lead them gradually (towards their punishment) in a way that they do not know.'),
(1137, 7, 183, 23, 13, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ  اُمۡلِیۡ   لَہُمۡ ؕ۟ اِنَّ  کَیۡدِیۡ مَتِیۡنٌ ﴿۱۸۳﴾', 'اور میں انکو مہلت دیئے جاتا ہوں۔ میری تدبیر بڑی مضبوط ہے۔', 'اور میں انکو ڈھیل دوں گا بیشک میرا داؤ پکا ہے [۲۲۳]', 'And I respite them; certainly My Plan is strong.', 'I give them respite. Surely My plan is firm.'),
(1138, 7, 184, 23, 13, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'اَوَ لَمۡ  یَتَفَکَّرُوۡا ٜ مَا بِصَاحِبِہِمۡ مِّنۡ جِنَّۃٍ ؕ اِنۡ ہُوَ  اِلَّا  نَذِیۡرٌ  مُّبِیۡنٌ  ﴿۱۸۴﴾', 'کیا انہوں نے غور نہیں کیا کہ انکے رفیق یعنی پیغمبر کو کسی طرح کا بھی جنون نہیں ہے۔ وہ تو صاف صاف خبردار کرنے والے ہیں۔', 'کیا انہوں نے دھیان نہیں کیا کہ ان کے رفیق کو کچھ بھی جنون نہیں وہ تو ڈرانے والا ہے صاف', 'Do they not reflect? There is no madness in their companion (Muhammad SAW). He is but a plain warner.', 'Have they not reflected that their fellow (i.e. the Holy Prophet) does not suffer from any madness? He is but a plain warner.'),
(1139, 7, 185, 23, 13, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'اَوَ لَمۡ یَنۡظُرُوۡا فِیۡ مَلَکُوۡتِ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ مَا خَلَقَ اللّٰہُ مِنۡ شَیۡءٍ ۙ وَّ اَنۡ عَسٰۤی اَنۡ یَّکُوۡنَ قَدِ اقۡتَرَبَ اَجَلُہُمۡ ۚ فَبِاَیِّ  حَدِیۡثٍۭ  بَعۡدَہٗ  یُؤۡمِنُوۡنَ ﴿۱۸۵﴾', 'کیا انہوں نے آسمان اور زمین کی بادشاہت میں اور جو چیزیں اللہ نے پیدا کی ہیں ان پر نظر نہیں کی۔ اور اس بات پر خیال نہیں کیا کہ عجب نہیں کہ انکی موت کا وقت نزدیک پہنچ گیا ہو۔ تو اسکے بعد وہ اور کس بات پر ایمان لائیں گے؟', 'کیا انہوں نے نظر نہیں کی سلطنت میں آسمان اور زمین کی اور جو کچھ پیدا کیا ہے اللہ نے ہر چیز سے اور اس میں کہ شاید قریب آ گیا ہو ان کا وعدہ [۲۲۴] سو اس کے پیچھے کس بات پر ایمان لائیں گے [۲۲۵]', 'Do they not look in the dominion of the heavens and the earth and all things that Allah has created, and that it may be that the end of their lives is near. In what message after this will they then believe?', 'Have they not looked into the kingdom of the heavens and the earth, and into the things Allah has created, and into the fact that their time might have possibly drawn near? In which other discourse, then, shall they believe after this?'),
(1140, 7, 186, 23, 13, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'مَنۡ یُّضۡلِلِ اللّٰہُ فَلَا ہَادِیَ لَہٗ  ؕ وَ یَذَرُہُمۡ  فِیۡ  طُغۡیَانِہِمۡ  یَعۡمَہُوۡنَ ﴿۱۸۶﴾', 'جس شخص کو اللہ گمراہ رہنے دے اسکو کوئی ہدایت دینے والا نہیں۔ اور وہ ان گمراہوں کو چھوڑے رکھتا ہے کہ اپنی سرکشی میں پڑے بہکتے رہیں۔', 'جس کو اللہ بچلائے اس کو کوئی نہیں راہ دکھلانے والا اور اللہ چھوڑے رکھتا ہے انکو ان کی شرارت میں سرگرداں [۲۲۶]', 'Whomsoever Allah sends astray, none can guide him; and He lets them wander blindly in their transgressions.', 'For those whom Allah lets go astray, there is no one to guide, and He leaves them wandering blindly in their rebellion.'),
(1141, 7, 187, 23, 13, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'یَسۡـَٔلُوۡنَکَ عَنِ السَّاعَۃِ اَیَّانَ مُرۡسٰہَا ؕ قُلۡ اِنَّمَا عِلۡمُہَا عِنۡدَ رَبِّیۡ ۚ لَا یُجَلِّیۡہَا لِوَقۡتِہَاۤ اِلَّا ہُوَ ؕۘؔ ثَقُلَتۡ فِی السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ لَا تَاۡتِیۡکُمۡ  اِلَّا بَغۡتَۃً ؕ یَسۡـَٔلُوۡنَکَ کَاَنَّکَ حَفِیٌّ عَنۡہَا ؕ قُلۡ اِنَّمَا عِلۡمُہَا عِنۡدَ اللّٰہِ وَ لٰکِنَّ اَکۡثَرَ  النَّاسِ لَا  یَعۡلَمُوۡنَ ﴿۱۸۷﴾', 'یہ لوگ تم سے قیامت کے بارے میں پوچھتے ہیں کہ اسکے واقع ہونے کا وقت کب ہے کہدو کہ اس کا علم تو میرے پروردگار ہی کو ہے۔ وہی اسے اسکے وقت پر ظاہر کر دے گا۔ وہ آسمان اور زمین میں ایک بھاری بات ہوگی۔ اور ناگہاں تم پر آ جائے گی۔ یہ تم سے اس طرح دریافت کرتے ہیں کہ گویا تم اس سے بخوبی واقف ہو۔ کہو کہ اس کا علم تو اللہ ہی کو ہے لیکن اکثر لوگ یہ نہیں جانتے۔', 'تجھ سے پوچھتے ہیں قیامت کو کہ کب ہے اسکے قائم ہونے کا وقت تو کہہ اسکی خبر تو میرے رب ہی کے پاس ہے وہی کھول دکھائے گا اس کو اسکے وقت پر وہ بھاری بات ہے آسمانوں اور زمین میں جب تم پر آئے گی تو بیخبر آئے گی [۲۲۷] تجھ سے پوچھنے لگتے ہیں کہ گویا تو اسکی تلاش میں لگا ہوا ہے تو کہہ دے اس کی خبر ہے خاص اللہ کے پاس لیکن اکثر لوگ نہیں سمجھتے [۲۲۸]', 'They ask you about the Hour (Day of Resurrection): \"When will be its appointed time?\" Say: \"The knowledge thereof is with my Lord (Alone). None can reveal its time but He. Heavy is its burden through the heavens and the earth. It shall not come upon you except all of a sudden.\" They ask you as if you have a good knowledge of it. Say: \"The knowledge thereof is with Allah (Alone) but most of mankind know not.\"', 'They ask you about the Hour (i.e. the Doomsday), “When is it due to happen?” Say, “Its knowledge is only with my Lord. No one can unfold it except He at its time. It shall weigh heavy in the heavens and the earth. It shall not come upon you but suddenly.” They ask you as if you were aware of it. Say, “Its knowledge is only with Allah, but most of the people do not know.”'),
(1142, 7, 188, 23, 13, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'قُلۡ لَّاۤ  اَمۡلِکُ  لِنَفۡسِیۡ  نَفۡعًا وَّ لَا  ضَرًّا  اِلَّا مَا شَآءَ اللّٰہُ ؕ وَ لَوۡ کُنۡتُ اَعۡلَمُ الۡغَیۡبَ لَاسۡتَکۡثَرۡتُ مِنَ الۡخَیۡرِۚۖۛ وَ مَا مَسَّنِیَ  السُّوۡٓءُ ۚۛ اِنۡ  اَنَا  اِلَّا  نَذِیۡرٌ وَّ بَشِیۡرٌ  لِّقَوۡمٍ  یُّؤۡمِنُوۡنَ ﴿۱۸۸﴾٪', 'کہدو کہ میں اپنے فائدے اور نقصان کا کچھ بھی اختیار نہیں رکھتا مگر وہ جو اللہ چاہے اور اگر میں غیب کی باتیں جانتا ہوتا تو بہت سے فائدے جمع کر لیتا اور مجھ کو کوئی تکلیف نہ پہنچتی۔ میں تو مومنوں کو ڈر اور خوشخبری سنانے والا ہوں۔', 'تو کہہ دے کہ میں مالک نہیں اپنی جان کے بھلے کا اور نہ برے کا مگر جو اللہ چاہے اور اگر میں جان لیا کرتا غیب کی بات تو بہت کچھ بھلائیاں حاصل کر لیتا اور مجھ کو برائی کبھی نہ پہنچتی [۲۲۹] میں تو بس ڈر اور خوشخبری سنانے والا ہوں ایماندار لوگوں کو', 'Say (O Muhammad SAW): \"I possess no power of benefit or hurt to myself except as Allah wills. If I had the knowledge of the Ghaib (unseen), I should have secured for myself an abundance of wealth, and no evil should have touched me. I am but a warner, and a bringer of glad tidings unto people who believe.\"', 'Say, “I have no power to bring a benefit or a harm to myself, except that which Allah wills. If I had the knowledge of the Unseen, I would have accumulated a lot of good things, and no evil would have ever touched me. I am but a warner, and a herald of good news for a people who believe.”'),
(1143, 7, 189, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'ہُوَ الَّذِیۡ خَلَقَکُمۡ مِّنۡ نَّفۡسٍ وَّاحِدَۃٍ وَّ جَعَلَ مِنۡہَا زَوۡجَہَا لِیَسۡکُنَ اِلَیۡہَا ۚ فَلَمَّا تَغَشّٰہَا حَمَلَتۡ حَمۡلًا خَفِیۡفًا فَمَرَّتۡ بِہٖ ۚ فَلَمَّاۤ  اَثۡقَلَتۡ دَّعَوَا اللّٰہَ رَبَّہُمَا لَئِنۡ اٰتَیۡتَنَا صَالِحًا  لَّنَکُوۡنَنَّ  مِنَ  الشّٰکِرِیۡنَ ﴿۱۸۹﴾', 'وہ اللہ ہی تو ہے جس نے تم کو ایک شخص سے پیدا کیا۔ اور اس سے اس کا جوڑا بنایا تاکہ اس سے راحت حاصل کرے سو جب وہ اسکے پاس جاتا ہے تو اسے ہلکا سا حمل رہ جاتا ہے اور وہ اسکے ساتھ چلتی پھرتی ہے۔ پھر جب وہ بوجھ محسوس کرتی ہے یعنی بچہ پیٹ میں بڑا ہوتا ہے تو دونوں میاں بیوی اپنے پروردگار اللہ سے التجا کرتے ہیں کہ اگر تو ہمیں صحیح و سالم بچہ دے گا تو ہم تیرے شکرگذار ہوں گے۔', 'وہی ہے جس نے تم کو پیدا کیا ایک جان سے اور اسی سے بنایا اس کا جوڑا تاکہ اسکے پاس آرام پکڑے پھر جب مرد نے عورت کو ڈھانکا حمل رہا ہلکا سا حمل تو چلتی پھرتی رہی اسکے ساتھ پھر جب بوجھل ہو گئ تو دونوں نے پکارا اللہ اپنے رب کو کہ اگر تو ہم کو بخشے چنگا بھلا تو ہم تیرا شکر کریں', 'It is He Who has created you from a single person (Adam), and (then) He has created from him his wife (Hawwa (Eve)), in order that he might enjoy the pleasure of living with her. When he had sexual relation with her, she became pregnant and she carried it about lightly. Then when it became heavy, they both invoked Allah, their Lord (saying): \"If You give us a Salih (good in every aspect) child, we shall indeed be among the grateful.\"', 'He is the One who has created you from a single soul, and out of him created his wife, so that he may find comfort in her. So when he covers her with himself, she carries a light burden and moves about with it. Thereafter, when she grows heavy, they both pray to Allah, their Lord, “If You bless us with a perfect child, we shall be grateful.”'),
(1144, 7, 190, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'فَلَمَّاۤ  اٰتٰہُمَا صَالِحًا جَعَلَا لَہٗ  شُرَکَآءَ فِیۡمَاۤ  اٰتٰہُمَا ۚ فَتَعٰلَی اللّٰہُ عَمَّا یُشۡرِکُوۡنَ ﴿۱۹۰﴾', 'پھر جب وہ انکو صحیح و سالم بچہ دیتا ہے تو اس بچے میں جو وہ ان کو دیتا ہے اس کا شریک مقرر کرتے ہیں۔ سو جو شرک وہ کرتے ہیں اللہ کا رتبہ اس سے بلند ہے۔', 'پھر جب ان کو دیا چنگا بھلا تو بنانے لگے اسکے لئے شریک اسکی بخشی ہوئی چیز میں سو اللہ برتر ہے انکے شریک بنانے سے [۲۳۰]', 'But when He gave them a Salih (good in every aspect) child, they ascribed partners to Him (Allah) in that which He has given to them. High be Allah, Exalted above all that they ascribe as partners to Him. (Tafsir At-Tabaree, Vol.9, Page 148).', 'But when We bless them with a perfect child, they ascribe partners to Him in what He blessed them with. Indeed Allah is much higher than what they associate with Him.'),
(1145, 7, 191, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'اَیُشۡرِکُوۡنَ مَا لَا یَخۡلُقُ شَیۡئًا وَّ ہُمۡ یُخۡلَقُوۡنَ ﴿۱۹۱﴾۫ۖ', 'کیا وہ ایسوں کو شریک بناتے ہیں جو کچھ بھی پیدا نہیں کر سکتے اور خود پیدا کئے جاتے ہیں۔', 'کیا شریک بناتے ہیں ایسوں کو جو پیدا نہ کریں ایک چیز بھی اور وہ پیدا ہوئے ہیں [۲۳۱]', 'Do they attribute as partners to Allah those who created nothing but they themselves are created?', 'Do they associate those with Allah who do not create any thing, rather, they are created (themselves)?'),
(1146, 7, 192, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ لَا یَسۡتَطِیۡعُوۡنَ لَہُمۡ نَصۡرًا وَّ لَاۤ اَنۡفُسَہُمۡ  یَنۡصُرُوۡنَ  ﴿۱۹۲﴾', 'اور نہ انکی مدد کی طاقت رکھتے ہیں اور نہ اپنی ہی مدد کر سکتے ہیں۔', 'اور نہیں کر سکتے ہیں ان کی مدد اور نہ اپنی مدد کریں', 'No help can they give them, nor can they help themselves.', 'And they (the alleged partners) cannot extend to them any help, nor can they help themselves.'),
(1147, 7, 193, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اِنۡ تَدۡعُوۡہُمۡ اِلَی الۡہُدٰی لَا یَتَّبِعُوۡکُمۡ ؕ سَوَآءٌ عَلَیۡکُمۡ اَدَعَوۡتُمُوۡہُمۡ  اَمۡ  اَنۡتُمۡ  صَامِتُوۡنَ ﴿۱۹۳﴾', 'اور اگر تم انکو سیدھے رستے کی طرف بلاؤ تو تمہارا کہا نہ مانیں۔ تمہارے لئے برابر ہے کہ تم انکو بلاؤ یا چپکے ہو رہو۔', 'اور اگر تم ان کو پکارو رستہ کی طرف تو نہ چلیں تمہاری پکار پر برابر ہے تم پر کہ ان کو پکارو یا چپکے رہو', 'And if you call them to guidance, they follow you not. It is the same for you whether you call them or you keep silent.', 'If you call them to the right path, they will not follow you. It is all the same for them whether you call them or remain silent.'),
(1148, 7, 194, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'اِنَّ الَّذِیۡنَ تَدۡعُوۡنَ مِنۡ دُوۡنِ اللّٰہِ عِبَادٌ اَمۡثَالُکُمۡ فَادۡعُوۡہُمۡ فَلۡیَسۡتَجِیۡبُوۡا لَکُمۡ  اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ ﴿۱۹۴﴾', 'مشرکو جنکو تم اللہ کے سوا پکارتے ہو تمہاری طرح کے بندے ہی ہیں اچھا تم انکو پکارو اگر سچے ہو تو چاہیے کہ وہ تم کو جواب بھی دیں۔', 'جن کو تم پکارتے ہو اللہ کے سوا وہ بندے ہیں تم جیسے بھلا پکارو تو ان کو پس چاہیئے کہ وہ قبول کریں تمہارے پکارنے کو اگر تم سچے ہو', 'Verily, those whom you call upon besides Allah are slaves like you. So call upon them and let them answer you if you are truthful.', 'Surely, those whom you invoke beside Allah are slaves (of Allah) like you. So, call them, and they should respond to you if you are true.'),
(1149, 7, 195, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'اَلَہُمۡ  اَرۡجُلٌ  یَّمۡشُوۡنَ  بِہَاۤ  ۫ اَمۡ  لَہُمۡ  اَیۡدٍ یَّبۡطِشُوۡنَ بِہَاۤ  ۫ اَمۡ  لَہُمۡ اَعۡیُنٌ یُّبۡصِرُوۡنَ  بِہَاۤ  ۫ اَمۡ  لَہُمۡ اٰذَانٌ یَّسۡمَعُوۡنَ بِہَا ؕ قُلِ ادۡعُوۡا شُرَکَآءَکُمۡ ثُمَّ   کِیۡدُوۡنِ  فَلَا  تُنۡظِرُوۡنِ ﴿۱۹۵﴾', 'بھلا انکے پاؤں ہیں جن سے چلیں یا ہاتھ ہیں جن سے پکڑیں یا آنکھیں ہیں جن سے دیکھیں یا کان ہیں جن سے سنیں؟ کہدو کہ اپنے شریکوں کو بلا لو اور میرے بارے میں جو تدبیر کرنی ہو کر لو اور مجھے کچھ مہلت بھی نہ دو پھر دیکھو کہ وہ میرا کیا کر سکتے ہیں۔', 'کیا انکے پاؤں ہیں جن سے چلتے ہیں یا ان کے ہاتھ ہیں جن سے پکڑتے ہیں یا ان کے آنکھیں ہیں جن سے دیکھتے ہیں یا ان کے کان ہیں جن سے سنتے ہیں تو کہہ دے کہ پکارو اپنے شریکوں کو پھر برائی کرو میرے حق میں اور مجھ کو ڈھیل نہ دو [۲۳۲]', 'Have they feet wherewith they walk? Or have they hands wherewith they hold? Or have they eyes wherewith they see? Or have they ears wherewith they hear? Say (O Muhammad SAW): \"Call your (so-called) partners (of Allah) and then plot against me, and give me no respite!', 'Do they have legs to walk with? Or do they have hands to grasp with? Or do they have eyes to see with or do they have ears to hear with? Say, “Call to your associate-gods, then, plot against me and allow me no respite.'),
(1150, 7, 196, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'اِنَّ  وَلِیَِّۧ اللّٰہُ الَّذِیۡ نَزَّلَ الۡکِتٰبَ ۫ۖ وَ ہُوَ  یَتَوَلَّی  الصّٰلِحِیۡنَ ﴿۱۹۶﴾', 'میرا مددگار تو اللہ ہی ہے جس نے کتاب برحق نازل کی اور وہ نیک لوگوں کو دوست رکھتا ہے۔', 'میرا حمایتی تو اللہ ہے جس نے اتاری کتاب اور وہ حمایت کرتا ہے نیک بندوں کی [۲۳۳]', '\"Verily, my Walee (Protector, Supporter, and Helper, etc.) is Allah Who has revealed the Book (the Quran), and He protects (supports and helps) the righteous.', 'Surely, my protector is Allah who has revealed the Book and who does protect the righteous.”'),
(1151, 7, 197, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ الَّذِیۡنَ تَدۡعُوۡنَ مِنۡ دُوۡنِہٖ لَا یَسۡتَطِیۡعُوۡنَ نَصۡرَکُمۡ وَ لَاۤ  اَنۡفُسَہُمۡ یَنۡصُرُوۡنَ ﴿۱۹۷﴾', 'اور جنکو تم اللہ کے سوا پکارتے ہو وہ نہ تمہاری مدد کی طاقت رکھتے ہیں اور نہ خود اپنی ہی مدد کر سکتے ہیں۔', 'اور جن کو تم پکارتے ہو اس کے سوا وہ نہیں کر سکتے تمہاری مدد اور نہ اپنی جان بچا سکیں', '\"And those whom you call upon besides Him (Allah) cannot help you nor can they help themselves.\"', 'Those whom you call beside Him cannot help you, nor can they help themselves.'),
(1152, 7, 198, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ  اِنۡ تَدۡعُوۡہُمۡ  اِلَی الۡہُدٰی لَا یَسۡمَعُوۡا ؕ وَ تَرٰىہُمۡ یَنۡظُرُوۡنَ  اِلَیۡکَ وَ ہُمۡ لَا یُبۡصِرُوۡنَ ﴿۱۹۸﴾', 'اور اگر تم انکو سیدھے رستے کی طرف بلاؤ تو سن نہ سکیں اور تم انہیں دیکھتے ہو کہ بظاہر آنکھیں کھولے تمہاری طرف دیکھ رہے ہیں مگر فی الواقع کچھ نہیں دیکھتے۔', 'اور اگر تم ان کو پکارو رستہ کی طرف تو کچھ نہ سنیں اور تو دیکھتا ہے انکو کہ تک رہے ہیں تیری طرف اور وہ کچھ نہیں دیکھتے [۲۳۴]', 'And if you call them to guidance, they hear not and you will see them looking at you, yet they see not.', 'If you call them for guidance, they shall not hear. You see them as if they are looking at you, while they cannot see.'),
(1153, 7, 199, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'خُذِ الۡعَفۡوَ وَ اۡمُرۡ بِالۡعُرۡفِ وَ اَعۡرِضۡ عَنِ  الۡجٰہِلِیۡنَ ﴿۱۹۹﴾', 'اے نبی عفو و درگذر اختیار کرو اور نیک کام کرنے کا حکم دو اور جاہلوں سے کنارہ کر لو۔', 'عادت کر درگذر کی اور حکم کر نیک کام کرنے کا اور کنارہ کر جاہلوں سے', 'Show forgiveness, enjoin what is good, and turn away from the foolish (i.e. dont punish them).', '(O Prophet,) take forgiveness (as your habit), enjoin virtue, and ignore the ignorant.'),
(1154, 7, 200, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اِمَّا یَنۡزَغَنَّکَ مِنَ الشَّیۡطٰنِ نَزۡغٌ فَاسۡتَعِذۡ  بِاللّٰہِ ؕ اِنَّہٗ  سَمِیۡعٌ  عَلِیۡمٌ ﴿۲۰۰﴾', 'اور اگر شیطان کی طرف سے تمہارے دل میں کسی طرح کا وسوسہ پیدا ہو تو اللہ سے پناہ مانگو۔ بیشک وہ سننے والا ہے سب کچھ جاننے والا ہے۔', 'اور اگر ابھارے تجھ کو شیطان کی چھیڑ تو پناہ مانگ اللہ سے وہی ہےسننے والا جاننے والا [۲۳۵]', 'And if an evil whisper comes to you from Shaitan (Satan) then seek refuge with Allah. Verily, He is All-Hearer, All-Knower.', 'Should a stroke from the Satan strike you, seek refuge with Allah. Surely, He is All-Hearing, All-Knowing.'),
(1155, 7, 201, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'اِنَّ الَّذِیۡنَ اتَّقَوۡا اِذَا مَسَّہُمۡ طٰٓئِفٌ مِّنَ الشَّیۡطٰنِ تَذَکَّرُوۡا فَاِذَا ہُمۡ مُّبۡصِرُوۡنَ ﴿۲۰۱﴾ۚ', 'جو لوگ پرہیزگار ہیں جب انکو شیطان کی طرف سے کوئی وسوسہ پیدا ہوتا ہے تو چونک پڑتے ہیں اور دل کی آنکھیں کھول کر دیکھنے لگتے ہیں۔', 'جن کے دل میں ڈر ہے جہاں پڑ گیا ان پر شیطان کا گذر چونک گئے پھر اسی وقت ان کو سوجھ آ جاتی ہے', 'Verily, those who are Al-Muttaqoon (the pious - see V.2:2), when an evil thought comes to them from Shaitan (Satan), they remember (Allah), and (indeed) they then see (aright).', 'Surely when the God-fearing are touched by any instigation from Satan, they become conscious (of Allah), and at once they discern (the reality).'),
(1156, 7, 202, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اِخۡوَانُہُمۡ یَمُدُّوۡنَہُمۡ فِی الۡغَیِّ ثُمَّ لَا یُقۡصِرُوۡنَ ﴿۲۰۲﴾', 'اور ان کفار کے بھائی انہیں گمراہی میں کھینچے جاتے ہیں پھر اس میں کسی طرح کی کوتاہی نہیں کرتے۔', 'اور جو شیطانوں کے بھائی ہیں وہ انکو کھینچتے چلے جاتے ہیں گمراہی میں پھر وہ کمی نہیں کرتے [۲۳۶]', 'But (as for) their brothers (the devils) they (i.e. the devils) plunge them deeper into error, and they never stop short.', 'As for the brethren of satans, they are dragged by them on into the error, and they do not desist.'),
(1157, 7, 203, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اِذَا لَمۡ تَاۡتِہِمۡ بِاٰیَۃٍ قَالُوۡا لَوۡ لَا اجۡتَبَیۡتَہَا ؕ قُلۡ  اِنَّمَاۤ  اَتَّبِعُ  مَا یُوۡحٰۤی اِلَیَّ مِنۡ رَّبِّیۡ ۚ ہٰذَا بَصَآئِرُ  مِنۡ رَّبِّکُمۡ وَ ہُدًی وَّ رَحۡمَۃٌ   لِّقَوۡمٍ  یُّؤۡمِنُوۡنَ ﴿۲۰۳﴾', 'اور جب تم انکے پاس کچھ دنوں تک کوئی آیت نہیں لاتے تو کہتے ہیں کہ تم نے اپنی طرف سے کیوں نہیں بنا لی۔ کہدو کہ میں تو اسی حکم کی پیروی کرتا ہوں جو میرے پروردگار کی طرف سے میرے پاس آتا ہے یہ قرآن تمہارے پروردگار کی جانب سے دانش و بصیرت اور مومنوں کے لئے ہدایت اور رحمت ہے۔', 'اور جب تو لیکر نہ جائے انکے پاس کوئی نشانی تو کہتے ہیں کیوں نہ چھانٹ لایا تو کچھ اپنی طرف سے تو کہہ دے میں تو چلتا ہوں اس پر جو حکم آئے میری طرف میرے رب سے یہ سوجھ کی باتیں ہیں تمہارے رب کی طرف سے اور ہدایت اور رحمت ہے ان لوگوں کو جو مومن ہیں [۲۳۷]', 'And if you do not bring them a miracle (according to their (i.e. Quraish-pagans) proposal), they say: \"Why have you not brought it?\" Say: \"I but follow what is revealed to me from my Lord. This (the Quran) is nothing but evidences from your Lord, and a guidance and a mercy for a people who believe.\"', 'When you do not bring them a sign, they say, “Could you not make up one?”Say, “I only follow what is revealed to me from my Lord.” This is (a Book of) insights from your Lord and a guidance and mercy for a people who believe.'),
(1158, 7, 204, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اِذَا قُرِیَٔ الۡقُرۡاٰنُ فَاسۡتَمِعُوۡا لَہٗ وَ اَنۡصِتُوۡا  لَعَلَّکُمۡ  تُرۡحَمُوۡنَ ﴿۲۰۴﴾', 'اور جب قرآن پڑھا جائے تو توجہ سے سنا کرو۔ اور خاموش رہا کرو۔ تاکہ تم پر رحم کیا جائے۔', 'اور جب قرآن پڑھا جائے تو اس کی طرف کان لگائے رہو اور چپ رہو تاکہ تم پر رحم ہو [۲۳۸]', 'So, when the Quran is recited, listen to it, and be silent that you may receive mercy. (i.e. during the compulsory congregational prayers when the Imam (of a mosque) is leading the prayer (except Soorat Al-Fatiha), and also when he is delivering the Friday-prayer Khutbah). (Tafsir At-Tabari, Vol.9, Pages 162-4)', 'When the Qur’ān is recited, listen to it and be silent, so that you may be blessed.'),
(1159, 7, 205, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'وَ اذۡکُرۡ رَّبَّکَ فِیۡ نَفۡسِکَ تَضَرُّعًا وَّ  خِیۡفَۃً وَّ دُوۡنَ الۡجَہۡرِ مِنَ الۡقَوۡلِ بِالۡغُدُوِّ وَ الۡاٰصَالِ  وَ لَا  تَکُنۡ  مِّنَ  الۡغٰفِلِیۡنَ ﴿۲۰۵﴾', 'اور اپنے پروردگار کو دل ہی دل میں عاجزی اور خوف سے اور پست آواز سے صبح و شام یاد کرتے رہو اور دیکھنا غافل نہ ہونا۔', 'اور یاد کرتا رہ اپنے رب کو اپنے دل میں گڑگڑاتا ہوا اور ڈرتا ہوا اور ایسی آواز سے جو کہ پکار کر بولنے سے کم ہو [۲۳۹] صبح کے وقت اور شام کے وقت اور مت رہ بے خبر', 'And remember your Lord by your tongue and within yourself, humbly and with fear without loudness in words in the mornings, and in the afternoons and be not of those who are neglectful.', 'Remember your Lord in your heart with humility and awe, and without speaking loudly, in mornings and evenings, and do not be among the heedless.'),
(1160, 7, 206, 24, 14, 9, 'قَالَ الۡمَلَاُ', 'الاعراف', 'اِنَّ  الَّذِیۡنَ عِنۡدَ رَبِّکَ لَا یَسۡتَکۡبِرُوۡنَ عَنۡ عِبَادَتِہٖ وَ یُسَبِّحُوۡنَہٗ وَ لَہٗ یَسۡجُدُوۡنَ ﴿۲۰۶﴾٪ٛ', 'جو لوگ تمہارے پروردگار کے پاس ہیں وہ اسکی عبادت سے روگردانی نہیں کرتے۔ اور اس پاک ذات کو یاد کرتے اور اسکے آگے سجدے کرتے رہتے ہیں۔', 'بیشک جو تیرے رب کے نزدیک ہیں وہ تکبر نہیں کرتے اس کی بندگی سے اور یاد کرتے ہیں اسکی پاک ذات کو اور اسی کو سجدہ کرتے ہیں [۲۴۰]', 'Surely, those who are with your Lord (angels) are never too proud to perform acts of worship to Him, but they glorify His Praise and prostrate before Him.', 'Surely, those who are with your Lord (i.e. the angels) are not arrogant against His worship, and they proclaim His purity, and before Him they prostrate themselves.'),
(1161, 8, 1, 1, 15, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'یَسۡـَٔلُوۡنَکَ عَنِ الۡاَنۡفَالِ ؕ قُلِ الۡاَنۡفَالُ لِلّٰہِ وَ الرَّسُوۡلِ ۚ فَاتَّقُوا اللّٰہَ وَ اَصۡلِحُوۡا ذَاتَ بَیۡنِکُمۡ ۪ وَ اَطِیۡعُوا اللّٰہَ وَ رَسُوۡلَہٗۤ  اِنۡ   کُنۡتُمۡ  مُّؤۡمِنِیۡنَ ﴿۱﴾', 'اے نبی مجاہد لوگ تم سے غنیمت کے مال کے بارے میں دریافت کرتے ہیں کہ کیا حکم ہے کہدو کہ غنیمت اللہ اور اسکے رسول کا مال ہے۔ تو اللہ سے ڈرو اور آپس میں صلح رکھو اور اگر ایمان رکھتے ہو تو اللہ اور اسکے رسول کے حکم پر چلو۔', '[۱] تجھ سے پوچھتے ہیں حکم غنیمت کا تو کہہ دے کے مال غنیمت اللہ کا ہے اور رسول کا سو ڈرو اللہ سے اور صلح کرو آپس میں اور حکم مانو اللہ کا اور اسکے رسول کا اگر تم ایمان رکھتے ہو', 'They ask you (O Muhammad SAW) about the spoils of war. Say: \"The spoils are for Allah and the Messenger.\" So fear Allah and adjust all matters of difference among you, and obey Allah and His Messenger (Muhammad SAW), if you are believers.', 'They ask you about the spoils. Say, “The spoils are for Allah and the Messenger.” So, fear Allah, and set your relations right, and obey Allah and His Messenger, if you are believers.'),
(1162, 8, 2, 1, 15, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'اِنَّمَا الۡمُؤۡمِنُوۡنَ الَّذِیۡنَ اِذَا ذُکِرَ اللّٰہُ وَجِلَتۡ قُلُوۡبُہُمۡ وَ اِذَا تُلِیَتۡ عَلَیۡہِمۡ اٰیٰتُہٗ زَادَتۡہُمۡ  اِیۡمَانًا وَّ عَلٰی رَبِّہِمۡ یَتَوَکَّلُوۡنَ ۚ﴿ۖ۲﴾', 'مومن تو وہ ہیں کہ جب اللہ کا ذکر کیا جاتا ہے تو انکے دل ڈر جاتے ہیں اور جب انہیں اسکی آیتیں پڑھ کر سنائی جاتی ہیں تو ان کا ایمان اور بڑھ جاتا ہے۔ اور وہ اپنے پروردگار پر بھروسہ رکھتے ہیں۔', 'ایمان والے وہی ہیں کہ جب نام آئے اللہ کا تو ڈر جائیں ان کے دل اور جب پڑھا جائے ان پر اس کا کلام تو زیادہ ہو جاتا ہےان کا ایمان اور وہ اپنے رب پر بھروسا رکھتے ہیں', 'The believers are only those who, when Allah is mentioned, feel a fear in their hearts and when His Verses (this Quran) are recited unto them, they (i.e. the Verses) increase their Faith; and they put their trust in their Lord (Alone);', 'Certainly, the believers are those whose hearts are filled with awe when (the name of) Allah is mentioned; and when His verses are recited to them, it makes them more developed in faith; and in their Lord they place their trust.'),
(1163, 8, 3, 1, 15, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'الَّذِیۡنَ یُقِیۡمُوۡنَ الصَّلٰوۃَ وَ مِمَّا رَزَقۡنٰہُمۡ  یُنۡفِقُوۡنَ ؕ﴿۳﴾', 'اور وہ جو نماز قائم کرتے ہیں اور جو مال ہم نے انکو دیا ہے اس میں سے نیک کاموں میں خرچ کرتے ہیں۔', 'وہ لوگ جو کہ قائم رکھتے ہیں نماز کو اور ہم نے جو انکو روزی دی ہے اس میں سے خرچ کرتے ہیں', 'Who perform As-Salat (IqamatasSalat) and spend out of that We have provided them.', '(They are) those who establish Salāh, and give away from what We have given to them.'),
(1164, 8, 4, 1, 15, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'اُولٰٓئِکَ ہُمُ الۡمُؤۡمِنُوۡنَ حَقًّا ؕ لَہُمۡ دَرَجٰتٌ عِنۡدَ رَبِّہِمۡ وَ مَغۡفِرَۃٌ وَّ رِزۡقٌ کَرِیۡمٌ ۚ﴿۴﴾', 'یہی سچے مومن ہیں اور انکے لئے انکے پروردگار کے ہاں بڑے بڑے درجے ہیں اور بخشش اور عزت کی روزی ہے۔', 'وہی ہیں سچے ایمان والے انکے لئے درجے ہیں اپنے رب کے پاس اور معافی اور روزی عزت کی [۲]', 'It is they who are the believers in truth. For them are grades of dignity with their Lord, and Forgiveness and a generous provision (Paradise).', 'Those are the believers in reality. For them there are high ranks with their Lord, and forgiveness, and dignified provision.'),
(1165, 8, 5, 1, 15, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'کَمَاۤ اَخۡرَجَکَ رَبُّکَ مِنۡۢ بَیۡتِکَ بِالۡحَقِّ ۪ وَ اِنَّ فَرِیۡقًا مِّنَ الۡمُؤۡمِنِیۡنَ لَکٰرِہُوۡنَ ۙ﴿۵﴾', 'ان لوگوں کو اپنے گھروں سے اسی طرح نکلنا چاہیے تھا جس طرح تمہارے پروردگار نے تم کو تدبیر کے ساتھ اپنے گھر سے نکالا اور اس وقت مومنوں کی ایک جماعت ناخوش تھی۔', 'جیسے نکالا تجھ کو تیرے رب نے تیرے گھر سے حق کام کے واسطے اور ایک جماعت اہل ایمان کی راضی نہ تھی', 'As your Lord caused you (O Muhammad SAW) to go out from your home with the truth, and verily, a party among the believers disliked it;', 'It is like when your Lord made you leave your home for the sake of truth, while a group from the believers were averse to it;'),
(1166, 8, 6, 1, 15, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'یُجَادِلُوۡنَکَ فِی الۡحَقِّ بَعۡدَ مَا تَبَیَّنَ کَاَنَّمَا یُسَاقُوۡنَ اِلَی الۡمَوۡتِ وَ ہُمۡ یَنۡظُرُوۡنَ ؕ﴿۶﴾', 'وہ لوگ حق بات میں اسکے ظاہر ہونے کے بعد تم سے جھگڑنے لگے گویا موت کی طرف ہانکے جاتے ہیں اور اسے دیکھ رہے ہیں۔', 'وہ تجھ سے جھگڑتے تھے حق بات میں اسکے ظاہر ہو چکنے کے بعد گویا وہ ہانکے جاتے ہیں موت کی طرف آنکھوں دیکھتے [۳]', 'Disputing with you concerning the truth after it was made manifest, as if they were being driven to death, while they were looking (at it).', 'they were disputing with you about the truth after it became clear, as if they were being driven to death being seen by them.'),
(1167, 8, 7, 1, 15, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'وَ اِذۡ یَعِدُکُمُ اللّٰہُ اِحۡدَی الطَّآئِفَتَیۡنِ اَنَّہَا لَکُمۡ وَ تَوَدُّوۡنَ اَنَّ غَیۡرَ ذَاتِ الشَّوۡکَۃِ تَکُوۡنُ لَکُمۡ  وَ یُرِیۡدُ  اللّٰہُ  اَنۡ یُّحِقَّ الۡحَقَّ بِکَلِمٰتِہٖ وَ یَقۡطَعَ دَابِرَ الۡکٰفِرِیۡنَ ۙ﴿۷﴾', 'اور اس وقت کو یاد کرو جب اللہ تم سے وعدہ کرتا تھا کہ ابوسفیان اور ابوجہل کے دو گروہوں میں سے ایک گروہ تمہارے لئے مغلوب ہو جائے گا۔ اور تم چاہتے تھے کہ جو قافلہ بے شان و شوکت یعنی بے ہتھیار ہے وہ تمہارے ہاتھ آ جائے اور اللہ چاہتا تھا کہ اپنے فرمان سے حق کو قائم رکھے اور کافروں کی جڑ کاٹ دے۔', 'اور جس وقت تم سے وعدہ کرتا تھا اللہ دو جماعتوں میں سے ایک کا کہ وہ تمہارے ہاتھ لگے گی اور تم چاہتے تھے کہ جس میں کانٹا نہ لگے وہ تم کو ملے اور اللہ چاہتا تھا کہ سچا کر دے سچ کو اپنے کلاموں سے اور کاٹ ڈالے جڑ کافروں کی', 'And (remember) when Allah promised you (Muslims) one of the two parties (of the enemy i.e. either the army or the caravan) that it should be yours, you wished that the one not armed (the caravan) should be yours, but Allah willed to justify the truth by His Words and to cut off the roots of the disbelievers (i.e. in the battle of Badr).', 'And recall when Allah was promising you that one of the two groups would become yours, and you were wishing that the one without strength should fall to you. And Allah wanted to establish the truth through His words and to cut off the very root of the disbelievers,'),
(1168, 8, 8, 1, 15, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'لِیُحِقَّ الۡحَقَّ وَ یُبۡطِلَ الۡبَاطِلَ وَ لَوۡ  کَرِہَ الۡمُجۡرِمُوۡنَ ۚ﴿۸﴾', 'تاکہ سچ کو سچ اور جھوٹ کو جھوٹ کر دے۔ گو مشرک ناخوش ہی ہوں۔', 'تاکہ سچا کرے سچ کو اور جھوٹا کر دے جھوٹ کو اور اگرچہ ناراض ہوں گنہگار [۴]', 'That He might cause the truth to triumph and bring falsehood to nothing, even though the Mujrimoon (disbelievers, polytheists, sinners, criminals, etc.) hate it.', 'so that He proves the truth to be true and the falsehood to be false, even though the sinners might dislike it.'),
(1169, 8, 9, 1, 15, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'اِذۡ تَسۡتَغِیۡثُوۡنَ رَبَّکُمۡ فَاسۡتَجَابَ لَکُمۡ اَنِّیۡ مُمِدُّکُمۡ بِاَلۡفٍ مِّنَ الۡمَلٰٓئِکَۃِ  مُرۡدِفِیۡنَ ﴿۹﴾', 'جب تم لوگ اپنے پروردگار سے فریاد کرتے تھے تو اس نے تمہاری دعا قبول کر لی اور فرمایا کہ تسلی رکھو ہم ہزار فرشتوں سے جو ایکدوسرے کے پیچھے آتے جائیں گے تمہاری مدد کریں گے۔', 'جب تم لگے فریاد کرنے اپنے رب سے تو وہ پہنچا تمہاری فریاد کو کہ میں مدد بھیجوں گا تمہاری ہزار فرشتے لگاتار آنے والے', '(Remember) when you sought help of your Lord and He answered you (saying): \"I will help you with a thousand of the angels each behind the other (following one another) in succession.\"', 'When you were calling your Lord for help, so He responded to you (saying): “I am going to support you with one thousand of the angels, one following the other.”'),
(1170, 8, 10, 1, 15, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'وَ مَا جَعَلَہُ اللّٰہُ  اِلَّا بُشۡرٰی وَ لِتَطۡمَئِنَّ بِہٖ قُلُوۡبُکُمۡ ۚ وَ مَا النَّصۡرُ اِلَّا مِنۡ عِنۡدِ اللّٰہِ ؕ اِنَّ  اللّٰہَ  عَزِیۡزٌ  حَکِیۡمٌ ﴿٪۱۰﴾', 'اور اس مدد کو اللہ نے محض بشارت بنایا تھا کہ تمہارے دل اس سے اطمینان حاصل کریں۔ اور مدد تو اللہ ہی کی طرف سے ہے۔ بیشک اللہ غالب ہے حکمت والا ہے۔', 'اور یہ تو دی اللہ نے فقط خوشخبری اور تاکہ مطمئن ہو جائیں اس سے تمہارےدل اور مدد نہیں مگر اللہ کی طرف سے بیشک اللہ زورآور ہے حکمت والا [۵]', 'Allah made it only as glad tidings, and that your hearts be at rest therewith. And there is no victory except from Allah. Verily, Allah is All-Mighty, All-Wise.', 'And Allah has made it (the promise) merely to give you a good news, and so that your hearts might be at rest thereby. And the help is from none but Allah. Surely, Allah is Mighty, Wise.'),
(1171, 8, 11, 2, 16, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'اِذۡ یُغَشِّیۡکُمُ النُّعَاسَ اَمَنَۃً مِّنۡہُ وَ یُنَزِّلُ عَلَیۡکُمۡ مِّنَ السَّمَآءِ مَآءً  لِّیُطَہِّرَکُمۡ بِہٖ وَ یُذۡہِبَ عَنۡکُمۡ رِجۡزَ الشَّیۡطٰنِ وَ لِیَرۡبِطَ عَلٰی قُلُوۡبِکُمۡ وَ یُثَبِّتَ بِہِ  الۡاَقۡدَامَ ﴿ؕ۱۱﴾', 'جب اس نے تمہاری تسکین کے لئے اپنی طرف سے تمہیں نیند کی چادر اوڑھا دی اور تم پر آسمان سے پانی برسا دیا تاکہ تم کو اس سے نہلا کر پاک کر دے۔ اور شیطانی نجاست کو تم سے دور کر دے اور اس لئے بھی کہ تمہارے دلوں کو مضبوط کر دے اور اس سے تمہارے پاؤں جمائے رکھے۔', 'جس وقت کہ ڈالدی اس نے تم پر اونگھ اپنی طرف سے تسکین کے واسطے اور اتارا تم پر آسمان سے پانی کہ اس سے تم کو پاک کر دے اور دور کر دے تم سے شیطان کی نجاست اور مضبوط کر دے تمہارے دلوں کو اور جما دے اس سے تمہارے قدم [۶]', '(Remember) when He covered you with a slumber as a security from Him, and He caused water (rain) to descend on you from the sky, to clean you thereby and to remove from you the Rijz (whispering, evil-suggestions, etc.) of Shaitan (Satan), and to strengthen your hearts, and make your feet firm thereby.', 'When He covered you with drowsiness, as tranquility (descending) from Him and sent down upon you water from the heavens, so that He might purify you with it, and remove from you the impurity of Satan, and so that He might strengthen your hearts and make (your) feet firm therewith.'),
(1172, 8, 12, 2, 16, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'اِذۡ یُوۡحِیۡ رَبُّکَ اِلَی الۡمَلٰٓئِکَۃِ اَنِّیۡ مَعَکُمۡ فَثَبِّتُوا الَّذِیۡنَ اٰمَنُوۡا ؕ سَاُلۡقِیۡ فِیۡ قُلُوۡبِ الَّذِیۡنَ  کَفَرُوا الرُّعۡبَ فَاضۡرِبُوۡا فَوۡقَ الۡاَعۡنَاقِ وَ اضۡرِبُوۡا مِنۡہُمۡ  کُلَّ  بَنَانٍ ﴿ؕ۱۲﴾', 'جب تمہارا پروردگار فرشتوں کو ارشاد فرماتا تھا کہ میں تمہارے ساتھ ہوں تم مومنوں کو تسلی دو کہ ثابت قدم رہیں۔ میں ابھی کافروں کے دلوں میں رعب و ہیبت ڈالے دیتا ہوں سو انکی گردنیں اڑا دو۔ اور انکی پور پور توڑ دو۔', 'جب حکم بھیجا تیرے رب نے فرشتوں کو کہ میں ساتھ ہوں تمہارے سو تم دل ثابت رکھو مسلمانوں کے میں ڈال دوں گا دل میں کافروں کے دہشت سو مارو گردنوں پر اور کاٹو ان کی پور پور', '(Remember) when your Lord inspired the angels, \"Verily, I am with you, so keep firm those who have believed. I will cast terror into the hearts of those who have disbelieved, so strike them over the necks, and smite over all their fingers and toes.\"', 'When your Lord revealed to the angels: “I am with you. So, make firm the feet of those who believe. I shall cast awe into the hearts of those who disbelieve. So, strike at the necks, and strike at every finger-joint of theirs.”'),
(1173, 8, 13, 2, 16, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'ذٰلِکَ بِاَنَّہُمۡ شَآقُّوا اللّٰہَ  وَ رَسُوۡلَہٗ ۚ وَ مَنۡ یُّشَاقِقِ اللّٰہَ وَ رَسُوۡلَہٗ  فَاِنَّ اللّٰہَ شَدِیۡدُ الۡعِقَابِ  ﴿۱۳﴾', 'یہ سزا اس لئے دی گئ کہ انہوں نے اللہ اور اسکے رسول کی مخالفت کی اور جو شخص اللہ اور اسکے رسول کی مخالفت کرتا ہے تو اللہ بھی سخت عذاب دینے والا ہے۔', 'یہ اس واسطے ہے کہ وہ مخالف ہوئے اللہ کے اور اسکے رسول کے اور جو کوئی مخالف ہوا اللہ کا اور اس کے رسول کا تو بیشک اللہ کا عذاب سخت ہے', 'This is because they defied and disobeyed Allah and His Messenger. And whoever defies and disobeys Allah and His Messenger, then verily, Allah is Severe in punishment.', 'That is because they were hostile to Allah and His Messenger; and whoever becomes hostile to Allah and His Messenger, then, Allah is severe at punishment.'),
(1174, 8, 14, 2, 16, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'ذٰلِکُمۡ فَذُوۡقُوۡہُ وَ اَنَّ لِلۡکٰفِرِیۡنَ عَذَابَ النَّارِ ﴿۱۴﴾', 'یہ مزہ تو یہاں چکھو اور یہ سمجھ لو کہ کافروں کے لئے آخرت میں دوزخ کا عذاب بھی تیار ہے۔', 'یہ تو تم چکھ لو اور جان رکھو کہ کافروں کے لئے ہے عذاب دوزخ کا [۷]', 'This is the torment, so taste it, and surely for the disbelievers is the torment of the Fire.', 'That is what you have to taste, and for the disbelievers is the (further) punishment of the Fire.'),
(1175, 8, 15, 2, 16, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا  اِذَا لَقِیۡتُمُ  الَّذِیۡنَ کَفَرُوۡا  زَحۡفًا  فَلَا  تُوَلُّوۡہُمُ  الۡاَدۡبَارَ ﴿ۚ۱۵﴾', 'اے اہل ایمان جب میدان جنگ میں کفار سے تمہارا مقابلہ ہو تو ان سے پیٹھ نہ پھیرنا۔', 'اے ایمان والو جب بھڑو تم کافروں سے میدان جنگ میں تو مت پھیرو ان سے پیٹھ [۸]', 'O you who believe! When you meet those who disbelieve, in a battle-field, never turn your backs to them.', 'O you who believe, when you face the disbelievers in a battle, do not turn your backs to them.'),
(1176, 8, 16, 2, 16, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'وَ مَنۡ یُّوَلِّہِمۡ یَوۡمَئِذٍ دُبُرَہٗۤ  اِلَّا مُتَحَرِّفًا لِّقِتَالٍ اَوۡ مُتَحَیِّزًا اِلٰی فِئَۃٍ فَقَدۡ بَآءَ بِغَضَبٍ مِّنَ اللّٰہِ وَ مَاۡوٰىہُ جَہَنَّمُ ؕ وَ بِئۡسَ  الۡمَصِیۡرُ ﴿۱۶﴾', 'اور جو شخص جنگ کے روز اس صورت کے سوا کہ لڑائی کے لئے کنارے کنارے چلے یعنی حکمت عملی سے دشمن کو مارے یا اپنی فوج میں جا ملنا چاہے ان سے پیٹھ پھیرے گا تو سمجھو کہ وہ اللہ کے غضب میں گرفتار ہو گیا اور اس کا ٹھکانہ دوزخ ہے اور وہ بہت ہی بری جگہ ہے۔', 'اور جو کوئی ان سے پھیرے پیٹھ اس دن مگر یہ کہ ہنر کرتا ہو لڑائی کا یا جا ملتا ہو فوج میں سو وہ پھرا اللہ کا غضب لے کر اور اس کا ٹھکانہ دوزخ ہے اور وہ کیا برا ٹھکانہ ہے [۹]', 'And whoever turns his back to them on such a day - unless it be a stratagem of war, or to retreat to a troop (of his own), - he indeed has drawn upon himself wrath from Allah. And his abode is Hell, and worst indeed is that destination!', 'Whoever turns his back to them on such a day,- unless it is for a tactic in the battle, or to join a company,-turns with wrath from Allah, and his abode is Jahannam (Hell), and it is an evil place to return.'),
(1177, 8, 17, 2, 16, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'فَلَمۡ تَقۡتُلُوۡہُمۡ وَلٰکِنَّ اللّٰہَ  قَتَلَہُمۡ ۪ وَ مَا رَمَیۡتَ اِذۡ رَمَیۡتَ وَ لٰکِنَّ اللّٰہَ رَمٰی ۚ وَ لِیُبۡلِیَ  الۡمُؤۡمِنِیۡنَ  مِنۡہُ  بَلَآءً  حَسَنًا ؕ اِنَّ اللّٰہَ  سَمِیۡعٌ  عَلِیۡمٌ ﴿۱۷﴾', 'پس تم لوگوں نے ان کفار کو قتل نہیں کیا بلکہ اللہ نے انہیں قتل کیا۔ اور اے نبی جس وقت تم نے کنکریاں پھینکی تھیں تو وہ تم نے نہیں پھینکی تھیں بلکہ اللہ نے پھینکی تھیں اس سے یہ غرض تھی کو مومنوں کو اپنے احسانوں سے اچھی طرح آزما لے بیشک اللہ سنتا ہے جانتا ہے۔', 'سو تم نے ان کو نہیں مارا لیکن اللہ نے ان کو مارا اور تو نے نہینں پھینکی مٹھی خا ک کی جس وقت کہ پھینکی تھی لیکن اللہ نے پھینکی اور تاکہ کرے ایمان والوں پر اپنی طرف سے خوب احسان بیشک اللہ ہے سننے والا جاننے والا [۱۰]', 'You killed them not, but Allah killed them. And you (Muhammad SAW) threw not when you did throw but Allah threw, that He might test the believers by a fair trial from Him. Verily, Allah is All-Hearer, All-Knower.', 'So, it is not you who killed them, but in fact Allah killed them. And you did not throw when you threw but Allah did throw, so that He might bless the believers with a good favour. Surely, Allah is All-Hearing, All-Knowing.'),
(1178, 8, 18, 2, 16, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'ذٰلِکُمۡ وَ اَنَّ اللّٰہَ  مُوۡہِنُ کَیۡدِ الۡکٰفِرِیۡنَ ﴿۱۸﴾', 'ہوا بھی یوں ہی اور کچھ شک نہیں کہ اللہ کافروں کی تدبیر کو کمزور کر دینے والا ہے۔', 'یہ تو ہو چکا اور جان رکھو کہ اللہ سست کر دے گا تدبیر کافروں کی [۱۱]', 'This (is the fact) and surely, Allah weakens the deceitful plots of the disbelievers.', 'Apart from that, Allah is the One who frustrates the device of the disbelievers.'),
(1179, 8, 19, 2, 16, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'اِنۡ تَسۡتَفۡتِحُوۡا فَقَدۡ جَآءَکُمُ الۡفَتۡحُ ۚ وَ اِنۡ تَنۡتَہُوۡا فَہُوَ خَیۡرٌ  لَّکُمۡ ۚ وَ اِنۡ تَعُوۡدُوۡا نَعُدۡ ۚ وَ لَنۡ تُغۡنِیَ عَنۡکُمۡ فِئَتُکُمۡ شَیۡئًا وَّ لَوۡ  کَثُرَتۡ ۙ وَ اَنَّ اللّٰہَ مَعَ  الۡمُؤۡمِنِیۡنَ ﴿٪۱۹﴾', 'کافرو اگر تم فیصلہ چاہتے ہو تو تمہارے پاس فیصلہ آ چکا اگر تم اپنے افعال سے باز آجاؤ تو تمہارے حق میں بہتر ہے اور اگر پھر نافرمانی کرو گے تو ہم بھی پھر تمہیں عذاب کریں گے۔ اور تمہاری جماعت خواہ کتنی ہی بڑی ہو تمہارے کچھ بھی کام نہ آئے گی اور اللہ تو مومنوں کے ساتھ ہے۔', 'اگر تم چاہتے ہو فیصلہ تو پہنچ چکا تمہارے پاس فیصلہ اور اگر باز آؤ تو تمہارے لئے بہتر ہے اور اگر پھر یہی کرو گے تو ہم بھی پھر یہی کریں گے اور کچھ کام نہ آئے گا تمہارے تمہارا جتھا اگرچہ بہت ہوں اور جان لو کہ اللہ ایمان والوں کے ساتھ ہے [۱۲]', '(O disbelievers) if you ask for a judgement, now has the judgement come unto you and if you cease (to do wrong), it will be better for you, and if you return (to the attack), so shall We return, and your forces will be of no avail to you, however numerous it be, and verily, Allah is with the believers.', '(O unbelievers,) if you were looking for a decision, the ‘decision’ has come upon you. And if you give up, it is better for you. And if you repeat, We shall repeat. And your people shall not suffice you at all, even though they are many in number; and Allah is with the believers.'),
(1180, 8, 20, 3, 17, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اَطِیۡعُوا اللّٰہَ وَ رَسُوۡلَہٗ  وَ لَا تَوَلَّوۡا عَنۡہُ وَ اَنۡتُمۡ تَسۡمَعُوۡنَ ﴿ۚۖ۲۰﴾', 'اے ایمان والو اللہ اور اسکے رسول کے حکم پر چلو اور اس سے روگردانی نہ کرو جبکہ تم سنتے بھی ہو۔', 'اے ایمان والو حکم مانو اللہ کا اور اسکے رسول کا اور اس سے مت پھرو سن کر [۱۳]', 'O you who believe! Obey Allah and His Messenger, and turn not away from him (i.e. Messenger Muhammad SAW) while you are hearing.', 'O you who believe, obey Allah and His Messenger, and do not turn away from Him when you listen (to him).'),
(1181, 8, 21, 3, 17, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'وَ لَا تَکُوۡنُوۡا کَالَّذِیۡنَ قَالُوۡا سَمِعۡنَا وَ ہُمۡ لَا  یَسۡمَعُوۡنَ ﴿۲۱﴾', 'اور ان لوگوں جیسے نہ ہونا جو کہتے ہیں ہم نے سن لیا مگر حقیقت میں نہیں سنتے۔', 'اور ان جیسے مت ہو جنہوں نے کہا ہم نے سن لیا اور وہ سنتے نہیں [۱۴]', 'And be not like those who say: \"We have heard,\" but they hear not.', 'And do not be like those who say, “We have listened” while they do not listen.'),
(1182, 8, 22, 3, 17, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'اِنَّ شَرَّ الدَّوَآبِّ عِنۡدَ اللّٰہِ الصُّمُّ الۡبُکۡمُ  الَّذِیۡنَ  لَا  یَعۡقِلُوۡنَ ﴿۲۲﴾', 'کچھ شک نہیں کہ اللہ کے نزدیک تمام جانداروں میں بدترین وہ بہرے گونگے لوگ ہیں جو عقل سے کام نہیں لیتے۔', 'بیشک سب جانداروں میں بدتر اللہ کے نزدیک وہی بہرےگونگے ہیں جو نہیں سمجھتے [۱۵]', 'Verily! The worst of (moving) living creatures with Allah are the deaf and the dumb, those who understand not (i.e. the disbelievers).', 'Surely, the worst of all animals in the sight of Allah are the deaf and the dumb who do not understand.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1183, 8, 23, 3, 17, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'وَ لَوۡ عَلِمَ اللّٰہُ  فِیۡہِمۡ خَیۡرًا لَّاَسۡمَعَہُمۡ ؕ وَ لَوۡ  اَسۡمَعَہُمۡ  لَتَوَلَّوۡا  وَّ ہُمۡ  مُّعۡرِضُوۡنَ ﴿۲۳﴾', 'اور اگر اللہ ان میں خیر کی طلب دیکھتا تو انکو سننے کی توفیق بخشتا اور اگر یونہی انہیں سنوا دیتا تو وہ منہ پھیر کر بھاگ جاتے۔', 'اور  اگر اللہ جانتا ان میں کچھ بھلائی تو ان کو سنا دیتا اور اگر ان کو اب سنا دے تو ضرور بھاگیں گے منہ پھیر کر [۱۶]', 'Had Allah known of any good in them, He would indeed have made them listen, and even if He had made them listen, they would but have turned away, averse (to the truth).', 'Had Allah seen in them some good, He would have made them listen (as due). But if He makes them listen (now), they will turn away paying no heed.'),
(1184, 8, 24, 3, 17, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوا اسۡتَجِیۡبُوۡا لِلّٰہِ وَ لِلرَّسُوۡلِ  اِذَا دَعَاکُمۡ  لِمَا یُحۡیِیۡکُمۡ ۚ وَ اعۡلَمُوۡۤا اَنَّ اللّٰہَ یَحُوۡلُ بَیۡنَ الۡمَرۡءِ وَ قَلۡبِہٖ  وَ اَنَّہٗۤ   اِلَیۡہِ  تُحۡشَرُوۡنَ ﴿۲۴﴾', 'مومنو! اللہ اور اسکے رسول کا حکم قبول کرو جبکہ رسول تمہیں ایسے کام کے لئے بلاتے ہیں جو تم کو زندگی جاوداں بخشتا ہے اور جان رکھو کہ اللہ آدمی اور اسکے دل کے درمیان حائل ہو جاتا ہے اور یہ بھی کہ تم سب اسکے روبرو جمع کئے جاؤ گے۔', 'اے ایمان والو حکم مانو اللہ کا اور رسول کا جس وقت بلائے تم کو اس کام کی طرف جس میں تمہاری زندگی ہے [۱۷] اور جان لو کہ اللہ روک لیتا ہے آدمی سے اس کے دل کو اور یہ کہ اسی کے پاس تم جمع ہو گے [۱۸]', 'O you who believe! Answer Allah (by obeying Him) and (His) Messenger when he (SAW) calls you to that which will give you life, and know that Allah comes in between a person and his heart (i.e. He prevents an evil person to decide anything). And verily to Him you shall (all) be gathered.', 'O you who believe, respond to Allah and the Messenger when He calls you to what gives you life, and be sure that Allah intervenes between man and his heart, and that to Him you shall be gathered.'),
(1185, 8, 25, 3, 17, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'وَ اتَّقُوۡا فِتۡنَۃً لَّا تُصِیۡبَنَّ الَّذِیۡنَ ظَلَمُوۡا مِنۡکُمۡ خَآصَّۃً ۚ وَ اعۡلَمُوۡۤا  اَنَّ اللّٰہَ  شَدِیۡدُ  الۡعِقَابِ ﴿۲۵﴾', 'اور اس فتنے سے ڈرو جو خصوصیت کے ساتھ انہی لوگوں پر واقع نہ ہو گا جو تم میں گناہگار ہیں اور جان رکھو کہ اللہ سخت عذاب دینے والا ہے۔', 'اور بچتے رہو اس فساد سے کہ نہیں پڑے گا تم میں سے خاص ظالموں ہی پر اور جان لو کہ اللہ کا عذاب سخت ہے [۱۹]', 'And fear the Fitnah (affliction and trial, etc.) which affects not in particular (only) those of you who do wrong (but it may afflict all the good and the bad people), and know that Allah is Severe in punishment.', 'And beware of a scourge that shall not fall only on the wrongdoers from among you, and know well that Allah is severe at punishment'),
(1186, 8, 26, 3, 17, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'وَ اذۡکُرُوۡۤا اِذۡ  اَنۡتُمۡ  قَلِیۡلٌ  مُّسۡتَضۡعَفُوۡنَ فِی الۡاَرۡضِ تَخَافُوۡنَ  اَنۡ  یَّتَخَطَّفَکُمُ النَّاسُ فَاٰوٰىکُمۡ وَ اَیَّدَکُمۡ بِنَصۡرِہٖ وَ رَزَقَکُمۡ مِّنَ الطَّیِّبٰتِ لَعَلَّکُمۡ تَشۡکُرُوۡنَ ﴿۲۶﴾', 'اور اس وقت کو یاد کرو جب تم زمین مکہ میں قلیل اور ضعیف سمجھے جاتے تھے اور ڈرتے رہتے تھے کہ لوگ تمہیں اڑا نہ لے جائیں یعنی ختم نہ کر دیں تو اس نے تم کو جگہ دی اور اپنی مدد سے تم کو تقویت بخشی اور پاکیزہ چیزیں کھانے کو دیں تاکہ اس کا شکر کرو۔', 'اور یاد کرو جس وقت تم تھوڑے تھے مغلوب پڑے ہوئے ملک میں ڈرتے تھے کہ اچک لیں تم کو لوگ پھر اس نے تم کو ٹھکانہ دیا اور قوت دی تم کو اپنی مدد سے اور روزی دی تم کو ستھری چیزیں تاکہ تم شکر کرو [۲۰]', 'And remember when you were few and were reckoned weak in the land, and were afraid that men might kidnap you, but He provided a safe place for you, strengthened you with His Help, and provided you with good things so that you might be grateful.', 'Recall when you were few in number, oppressed on the earth, fearing that the people would snatch you away. Then, He gave you shelter and fortified you with His support and provided you with good things, so that you may be grateful.'),
(1187, 8, 27, 3, 17, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَخُوۡنُوا اللّٰہَ وَ الرَّسُوۡلَ وَ تَخُوۡنُوۡۤا اَمٰنٰتِکُمۡ وَ اَنۡتُمۡ تَعۡلَمُوۡنَ ﴿۲۷﴾', 'اے ایمان والو! نہ تو اللہ اور رسول سے خیانت کرو اور نہ اپنی امانتوں میں خیانت کرو اور تم ان باتوں کو جانتے ہو۔', 'اے ایمان والو خیانت نہ کرو اللہ سے اور رسول سے اور خیانت نہ کرو آپس کی امانتوں میں جان کر [۲۱]', 'O you who believe! Betray not Allah and His Messenger, nor betray knowingly your Amanat (things entrusted to you, and all the duties which Allah has ordained for you).', 'O you who believe, do not betray the trust of Allah and the Messenger-, and do not betray your mutual trusts, while you know.'),
(1188, 8, 28, 3, 17, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'وَ اعۡلَمُوۡۤا  اَنَّمَاۤ   اَمۡوَالُکُمۡ  وَ اَوۡلَادُکُمۡ  فِتۡنَۃٌ ۙ وَّ اَنَّ اللّٰہَ عِنۡدَہٗۤ  اَجۡرٌ  عَظِیۡمٌ ﴿٪۲۸﴾', 'اور جان رکھو کہ تمہارا مال اور اولاد بڑی آزمائش ہے اور یہ کہ اللہ کے پاس نیکیوں کا بڑا ثواب ہے۔', 'اور جان لو کہ بیشک تمہارےمال اور اولاد خرابی میں ڈالنے والے ہیں اور یہ کہ اللہ کے پاس بڑا ثواب ہے [۲۲]', 'And know that your possessions and your children are but a trial and that surely with Allah is a mighty reward.', 'Be aware that your wealth and your children are but a trial and that with Allah there is a great reward.'),
(1189, 8, 29, 4, 18, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اِنۡ تَتَّقُوا اللّٰہَ یَجۡعَلۡ لَّکُمۡ فُرۡقَانًا وَّ یُکَفِّرۡ عَنۡکُمۡ سَیِّاٰتِکُمۡ وَ یَغۡفِرۡ لَکُمۡ ؕ وَ اللّٰہُ  ذُو الۡفَضۡلِ  الۡعَظِیۡمِ ﴿۲۹﴾', 'مومنو! اگر تم اللہ سے ڈرو گے تو وہ تمہارے لئے حق و باطل کا فرق ظاہر کر دے گا اور  تمہارے گناہ مٹا دے گا اور تمہیں بخش دے گا اور اللہ بڑے فضل والا ہے۔', 'اے ایمان والو اگر تم ڈرتے رہو گے اللہ سے تو کر دے گا تم میں فیصلہ [۲۳] اور دور کر دے گا تم سے تمہارے گناہ اور تم کو بخش دے گا اور اللہ کا فضل بڑا ہے', 'O you who believe! If you obey and fear Allah, He will grant you Furqan a criterion ((to judge between right and wrong), or (Makhraj, i.e. making a way for you to get out from every difficulty)), and will expiate for you your sins, and forgive you, and Allah is the Owner of the Great Bounty.', 'O you who believe, if you fear Allah, He will provide you with a criterion (to distinguish between right and wrong) and will write off your evil deeds and will forgive you. Allah is the Lord of great bounty.'),
(1190, 8, 30, 4, 18, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'وَ اِذۡ یَمۡکُرُ بِکَ الَّذِیۡنَ کَفَرُوۡا لِیُثۡبِتُوۡکَ اَوۡ یَقۡتُلُوۡکَ اَوۡ یُخۡرِجُوۡکَ ؕ وَ یَمۡکُرُوۡنَ وَ یَمۡکُرُ  اللّٰہُ  ؕ وَ اللّٰہُ خَیۡرُ الۡمٰکِرِیۡنَ ﴿۳۰﴾', 'اور اس وقت کو یاد کرو جب کافر لوگ تمہارے بارے میں چال چل رہے تھے کہ تم کو قید کر دیں یا جان سے مار دیں یا وطن سے نکال دیں تو ادھر تو وہ چال چل رہے تھے اور ادھر اللہ تدبیر کر رہا تھا اور اللہ بہترین تدبیر کرنے والا ہے۔', 'اور جب فریب کرتے تھے کافر کہ تجھ کو قید میں کر دیں یا مار ڈالیں یا نکال دیں اور وہ بھی داؤ کرتے تھے اور اللہ بھی داؤ کرتا تھا اور اللہ کا داؤ سب سے بہتر ہے [۲۴]', 'And (remember) when the disbelievers plotted against you (O Muhammad SAW) to imprison you, or to kill you, or to get you out (from your home, i.e. Makkah); they were plotting and Allah too was planning, and Allah is the Best of the planners.', 'And (recall) when the disbelievers were conspiring against you to hold you as a captive, or to kill you, or to expel you. They were planning, and Allah was planning, and Allah is the best planner.'),
(1191, 8, 31, 4, 18, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'وَ اِذَا تُتۡلٰی عَلَیۡہِمۡ اٰیٰتُنَا قَالُوۡا قَدۡ سَمِعۡنَا لَوۡ  نَشَآءُ   لَقُلۡنَا مِثۡلَ  ہٰذَاۤ  ۙ اِنۡ  ہٰذَاۤ   اِلَّاۤ   اَسَاطِیۡرُ  الۡاَوَّلِیۡنَ ﴿۳۱﴾', 'اور جب انکو ہماری آیتیں پڑھ کر سنائی جاتی ہیں۔ تو کہتے ہیں یہ کلام ہم نے سن لیا ہے اگر ہم چاہیں تو اسی طرح کا کلام ہم بھی کہدیں اور یہ ہے ہی کیا صرف اگلے لوگوں کی حکایتیں ہیں۔', 'اور جب کوئی پڑھے ان پر ہماری آیتیں تو کہیں ہم سن چکے اگر ہم چاہیں تو ہم بھی کہہ لیں ایسا یہ تو کچھ بھی نہیں مگر احوال ہیں اگلوں کے [۲۵]', 'And when Our Verses (of the Quran) are recited to them, they say: \"We have heard this (the Quran); if we wish we can say the like of this. This is nothing but the tales of the ancients.\"', 'When Our verses are recited to them, they say, “We have heard; if we wish, we can compose a discourse like this. It is nothing but the tales of the ancient people.”'),
(1192, 8, 32, 4, 18, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'وَ  اِذۡ  قَالُوا اللّٰہُمَّ  اِنۡ کَانَ ہٰذَا ہُوَ الۡحَقَّ مِنۡ عِنۡدِکَ فَاَمۡطِرۡ عَلَیۡنَا حِجَارَۃً مِّنَ السَّمَآءِ اَوِ ائۡتِنَا بِعَذَابٍ اَلِیۡمٍ ﴿۳۲﴾', 'اور جب انہوں نے کہا کہ اے اللہ اگر یہ قرآن تیری طرف سے برحق ہے تو ہم پر آسمان سے پتھر برسا یا کوئی اور تکلیف دینے والا عذاب بھیج دے۔', 'اور جب وہ کہنے لگے کہ یا اللہ اگر یہی دین حق ہے تیری طرف سے تو ہم پر برسا دے پتھر آسمان سے یا لا ہم پر کوئی عذاب دردناک [۲۶]', 'And (remember) when they said: \"O Allah! If this (the Quran) is indeed the truth (revealed) from You, then rain down stones on us from the sky or bring on us a painful torment.\"', 'And (recall) when they said, “O Allah, if this is indeed the truth (revealed) from You, then, rain down stones upon us from the heavens, or bring upon us a painful punishment.”'),
(1193, 8, 33, 4, 18, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'وَ مَا کَانَ اللّٰہُ  لِیُعَذِّبَہُمۡ  وَ اَنۡتَ فِیۡہِمۡ ؕ وَ مَا کَانَ اللّٰہُ مُعَذِّبَہُمۡ وَ ہُمۡ یَسۡتَغۡفِرُوۡنَ ﴿۳۳﴾', 'اور اللہ ایسا نہ تھا کہ جب تک اے پیغمبر تم ان میں تھے انہیں عذاب دیتا اور نہ ایسا ہے کہ وہ تو بخشش مانگیں اور اللہ انہیں عذاب دے۔', 'اور اللہ ہر گز نہ عذاب کرتا ان پر جب تک تو رہتا ان میں [۲۷] اور اللہ ہرگز نہ عذاب کرے گا ان پر جب تک وہ معافی مانگتے رہیں گے [۲۸]', 'And Allah would not punish them while you (Muhammad SAW) are amongst them, nor will He punish them while they seek (Allahs) Forgiveness.', 'And Allah was not to send scourge upon them while you (O Prophet), were in their midst, nor would Allah send scourge upon them while they are seeking forgiveness.'),
(1194, 8, 34, 4, 18, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'وَ مَا لَہُمۡ  اَلَّا یُعَذِّبَہُمُ اللّٰہُ  وَ ہُمۡ  یَصُدُّوۡنَ عَنِ الۡمَسۡجِدِ الۡحَرَامِ وَ مَا کَانُوۡۤا اَوۡلِیَآءَہٗ ؕ اِنۡ  اَوۡلِیَآؤُہٗۤ  اِلَّا الۡمُتَّقُوۡنَ وَ لٰکِنَّ  اَکۡثَرَہُمۡ  لَا  یَعۡلَمُوۡنَ ﴿۳۴﴾', 'اور اب ان کے لئے کونسی وجہ ہے کہ وہ انہیں عذاب نہ دے جب کہ وہ مسجد حرام میں نماز پڑھنے سے روکتے ہیں جب کہ وہ اس مسجد کے متولی بھی نہیں ہیں۔ اسکے متولی تو صرف پرہیزگار ہیں لیکن ان میں کے اکثر نہیں جانتے۔', 'اور ان میں کیا بات ہے کہ عذاب نہ کرے ان پر اللہ اور وہ تو روکتے ہیں مسجد حرام سے اور وہ اس کے اختیار والے نہیں اس کے اختیار والے تو وہی ہیں جو پرہیزگار ہیں لیکن ان میں اکثروں کو اس کی خبر نہیں [۲۹]', 'And why should not Allah punish them while they stop (men) from Al-Masjid-al-Haram, and they are not its guardians? None can be its guardian except Al-Muttaqoon (the pious - see V.2:2), but most of them know not.', 'And what privilege do they have that Allah should not punish them, while they prevent (people) from Al-Masjid-ul-Harām (the Sacred Mosque), even though they are not (competent to be) its custodians? Its (competent) custodians are none but the God-fearing, but most of them do not know.'),
(1195, 8, 35, 4, 18, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'وَ مَا کَانَ صَلَاتُہُمۡ عِنۡدَ الۡبَیۡتِ اِلَّا مُکَآءً   وَّ تَصۡدِیَۃً ؕ فَذُوۡقُوا الۡعَذَابَ بِمَا کُنۡتُمۡ  تَکۡفُرُوۡنَ ﴿۳۵﴾', 'اور ان لوگوں کی نماز خانہ کعبہ کے پاس سیٹیاں اور تالیاں بجانے کے سوا کچھ نہ تھی۔ تو تم جو کفر کرتے تھے اب اسکے بدلے عذاب کا مزہ چکھو۔', 'اور ان کی نماز نہیں تھی کعبہ کے پاس مگر سیٹیاں بجانی اور تالیاں سو چکھو عذاب بدلا اپنے کفر کا [۳۰]', 'Their Salat (prayer) at the House (of Allah, i.e. the Kabah at Makkah) was nothing but whistling and clapping of hands. Therefore taste the punishment because you used to disbelieve.', 'And their prayer near the House was not more than whistling and clapping. So, taste the punishment, because you used to disbelieve.'),
(1196, 8, 36, 4, 18, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'اِنَّ الَّذِیۡنَ کَفَرُوۡا یُنۡفِقُوۡنَ اَمۡوَالَہُمۡ لِیَصُدُّوۡا عَنۡ سَبِیۡلِ اللّٰہِ ؕ فَسَیُنۡفِقُوۡنَہَا ثُمَّ تَکُوۡنُ عَلَیۡہِمۡ حَسۡرَۃً  ثُمَّ یُغۡلَبُوۡنَ ۬ؕ وَ الَّذِیۡنَ  کَفَرُوۡۤا اِلٰی  جَہَنَّمَ  یُحۡشَرُوۡنَ ﴿ۙ۳۶﴾', 'جو لوگ کافر ہیں اپنا مال خرچ کرتے ہیں کہ لوگوں کو اللہ کے رستے سے روکیں۔ سو ابھی اور خرچ کریں گے۔ مگر آخر وہ خرچ کرنا انکے لئے موجب افسوس ہو گا اور وہ مغلوب ہو جائیں گے۔ اور کافر لوگ دوزخ کی طرف ہانکے جائیں گے۔', 'بیشک جو لوگ کافر ہیں وہ خرچ کرتے ہیں اپنے مال تاکہ روکیں اللہ کی راہ سے [۳۱] سو ابھی اور خرچ کریں گے پھر آخر ہو گا وہ ان پر افسوس اور آخر مغلوب ہوں گے اور جو کافر ہیں وہ دوزخ کی طرف ہانکے جائیں گے [۳۲]', 'Verily, those who disbelieve spend their wealth to hinder (men) from the Path of Allah, and so will they continue to spend it; but in the end it will become an anguish for them. Then they will be overcomed. And those who disbelieve will be gathered unto Hell.', 'Surely, those who disbelieve spend their wealth to prevent (people) from the way of Allah. So, they shall spend it, then it will become remorse for them, then they shall be overpowered, and those who disbelieve shall be gathered into Jahannam ,'),
(1197, 8, 37, 4, 18, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'لِیَمِیۡزَ اللّٰہُ  الۡخَبِیۡثَ مِنَ الطَّیِّبِ وَ یَجۡعَلَ الۡخَبِیۡثَ بَعۡضَہٗ عَلٰی بَعۡضٍ فَیَرۡکُمَہٗ جَمِیۡعًا فَیَجۡعَلَہٗ  فِیۡ جَہَنَّمَ ؕ اُولٰٓئِکَ  ہُمُ  الۡخٰسِرُوۡنَ ﴿٪۳۷﴾', 'تاکہ اللہ پاک سے ناپاک کو الگ کر دے اور ناپاک کو ایک دوسرے پر رکھ کر ایک ڈھیر بنا دے۔ پھر اسکو دوزخ میں ڈال دے یہی لوگ خسارہ پانے والے ہیں۔', 'تاکہ جدا کر دے اللہ ناپاک کو پاک سے اور رکھے ناپاک کو ایک کو ایک پر پھر اس کو ڈھیر کر دے اکٹھا پھر ڈالدے اسکو دوزخ میں [۳۳] وہی لوگ ہیں نقصان میں [۳۴]', 'In order that Allah may distinguish the wicked (disbelievers, polytheists and doers of evil deeds) from the good (believers of Islamic Monotheism and doers of righteous deeds), and put the wicked (disbelievers, polytheists and doers of evil deeds) one on another, heap them together and cast them into Hell. Those! it is they who are the losers.', 'so that Allah may separate the wicked from the good people, and join the wicked with each other, and heaps them all together, and puts them into Jahannam . Those are the losers.'),
(1198, 8, 38, 5, 0, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'قُلۡ  لِّلَّذِیۡنَ  کَفَرُوۡۤا  اِنۡ یَّنۡتَہُوۡا یُغۡفَرۡ لَہُمۡ مَّا قَدۡ سَلَفَ ۚ وَ اِنۡ یَّعُوۡدُوۡا فَقَدۡ مَضَتۡ سُنَّتُ  الۡاَوَّلِیۡنَ ﴿۳۸﴾', 'اے پیغمبر کفار سے کہدو کہ اگر وہ اپنے افعال سے باز آجائیں تو جو ہو چکا وہ انہیں معاف کر دیا جائے گا اور اگر پھر وہی حرکات کرنے لگیں گے تو اگلے لوگوں کا جو طریقہ جاری ہو چکا ہے وہی ان کے حق میں بھی برتا جائے گا۔', 'تو کہہ دے کافروں کو کہ اگر  وہ باز آ جائیں تو معاف ہو ان کو جو کچھ ہو چکا [۳۵] اور اگر پھر بھی وہی کریں گے تو پڑ چکی ہے راہ اگلوں کی [۳۶]', 'Say to those who have disbelieved, if they cease (from disbelief) their past will be forgiven. But if they return (thereto), then the examples of those (punished) before them have already preceded (as a warning).', 'Say to those who disbelieve that if they desist (from infidelity), they shall be forgiven for what has passed (of their sins), and if they repeat, then, the precedent of the earlier people is already established (that the infidels are punished).'),
(1199, 8, 39, 5, 0, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'وَ قَاتِلُوۡہُمۡ حَتّٰی لَا تَکُوۡنَ فِتۡنَۃٌ وَّ یَکُوۡنَ الدِّیۡنُ کُلُّہٗ  لِلّٰہِ ۚ  فَاِنِ انۡتَہَوۡا فَاِنَّ اللّٰہَ  بِمَا یَعۡمَلُوۡنَ  بَصِیۡرٌ ﴿۳۹﴾', 'اور ان لوگوں سے لڑتے رہو یہاں تک کہ فتنہ یعنی کفر کا فساد باقی نہ رہے اور دین سب اللہ ہی کا ہو جائے اور اگر وہ باز آ جائیں تو اللہ انکے کاموں کو دیکھ رہا ہے۔', 'اور لڑتے رہو ان سے یہاں تک کہ نہ رہے فساد [۳۷] اور ہو جائے حکم سب اللہ کا [۳۸] پھر اگر وہ باز آ جائیں تو اللہ ان کے کام کو دیکھتا ہے [۳۹]', 'And fight them until there is no more Fitnah (disbelief and polytheism: i.e. worshipping others besides Allah) and the religion (worship) will all be for Allah Alone (in the whole of the world). But if they cease (worshipping others besides Allah), then certainly, Allah is All-Seer of what they do.', 'And fight them until there is no Fitnah (mischief), and total obedience becomes for Allah. So, if they desist, then, Allah is indeed watchful over what they do.'),
(1200, 8, 40, 5, 0, 9, 'قَالَ الۡمَلَاُ', 'الانفال', 'وَ  اِنۡ تَوَلَّوۡا  فَاعۡلَمُوۡۤا  اَنَّ اللّٰہَ مَوۡلٰىکُمۡ ؕ نِعۡمَ  الۡمَوۡلٰی  وَ نِعۡمَ النَّصِیۡرُ ﴿۴۰﴾', 'اور اگر روگردانی کریں تو جان رکھو کہ اللہ تمہارا حمایتی ہے اور وہ خوب حمایتی اور خوب مددگار ہے۔', 'اور اگر وہ نہ مانیں تو جان لو کہ اللہ تمہارا حمایتی ہے کیا خوب حمایتی ہے اور کیا خوب مددگار [۴۰]', 'And if they turn away, then know that Allah is your Maula (Patron, Lord, Protector and Supporter, etc.), (what) an Excellent Maula, and (what) an Excellent Helper!', 'And if they turn away, then, rest assured that Allah is your protector. So excellent a protector is He, and so excellent a supporter.'),
(1201, 8, 41, 5, 1, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'وَ اعۡلَمُوۡۤا اَنَّمَا غَنِمۡتُمۡ مِّنۡ شَیۡءٍ فَاَنَّ لِلّٰہِ خُمُسَہٗ وَ لِلرَّسُوۡلِ وَ لِذِی الۡقُرۡبٰی وَ الۡیَتٰمٰی وَ الۡمَسٰکِیۡنِ  وَ  ابۡنِ السَّبِیۡلِ ۙ اِنۡ  کُنۡتُمۡ  اٰمَنۡتُمۡ بِاللّٰہِ وَ مَاۤ  اَنۡزَلۡنَا عَلٰی عَبۡدِنَا یَوۡمَ الۡفُرۡقَانِ  یَوۡمَ الۡتَقَی الۡجَمۡعٰنِ ؕ وَ اللّٰہُ عَلٰی کُلِّ شَیۡءٍ قَدِیۡرٌ ﴿۴۱﴾', 'اور جان رکھو کہ جو مال غنیمت تم کفار سے حاصل کرو اس میں سے پانچواں حصہ اللہ کا اور اسکے رسول کا اور اہل قرابت اور یتیموں کا اور محتاجوں کا اور مسافروں کا ہے۔ اگر تم اللہ پر اور اس نصرت پر ایمان رکھتے ہو جو حق و باطل میں فرق کرنے کے دن یعنی جنگ بدر میں جس دن دونوں فوجوں میں مڈبھیڑ ہو گئ۔ ہم نے اپنے محبوب بندے محمد ﷺ پر نازل فرمائی۔ اور اللہ ہر چیز پر قادر ہے۔', 'اور جان رکھو کہ جو کچھ تم کو غنیمت ملے کسی چیز سے سو اللہ کے واسطے ہے اس میں سے پانچواں حصہ اور رسول کے واسطے اور اسکے قرابت والوں کے واسطے اور یتیموں اور محتاجوں اور مسافروں کے واسطے [۴۱] اگر تم کو یقین ہے اللہ پر اور اس چیز پر جو ہم نے اتاری اپنے بندے پر فیصلہ کے دن [۴۲] جس دن بھڑ گئیں دونوں فوجیں اور اللہ ہر چیز پر قادر ہے [۴۳]', 'And know that whatever of war-booty that you may gain, verily one-fifth (1/5th) of it is assigned to Allah, and to the Messenger, and to the near relatives (of the Messenger (Muhammad SAW)), (and also) the orphans, Al-Masakin (the poor) and the wayfarer, if you have believed in Allah and in that which We sent down to Our slave (Muhammad SAW) on the Day of criterion (between right and wrong), the Day when the two forces met (the battle of Badr) - And Allah is Able to do all things.', 'And know that whatever spoils you receive, its one fifth is for Allah and for His Messenger, and for kinsmen and orphans and the needy and the wayfarer, if you do believe in Allah and in what We have sent down upon Our Servant on the decisive day, the day when the two forces encountered each other. And Allah is powerful over everything.'),
(1202, 8, 42, 5, 1, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'اِذۡ اَنۡتُمۡ بِالۡعُدۡوَۃِ الدُّنۡیَا وَ ہُمۡ  بِالۡعُدۡوَۃِ الۡقُصۡوٰی وَ الرَّکۡبُ اَسۡفَلَ  مِنۡکُمۡ ؕ وَ لَوۡ  تَوَاعَدۡتُّمۡ  لَاخۡتَلَفۡتُمۡ  فِی الۡمِیۡعٰدِ ۙ وَ لٰکِنۡ لِّیَقۡضِیَ اللّٰہُ اَمۡرًا کَانَ مَفۡعُوۡلًا ۬ۙ لِّیَہۡلِکَ مَنۡ ہَلَکَ عَنۡۢ بَیِّنَۃٍ وَّ یَحۡیٰی مَنۡ حَیَّ عَنۡۢ  بَیِّنَۃٍ ؕ وَ اِنَّ اللّٰہَ  لَسَمِیۡعٌ  عَلِیۡمٌ ﴿ۙ۴۲﴾', 'جس وقت تم مدینے سے قریب کے ناکے پر تھے اور کافر دور کے ناکے پر اور قافلہ تم سے نیچے اتر گیا تھا۔ اور اگر تم جنگ کے لئے آپس میں قرارداد کر لیتے تو وقت معین پر جمع ہونے میں تقدیم و تاخیر ہو جاتی لیکن اللہ کو منظور تھا کہ جو کام ہو کر رہنے والا تھا اسے کر ہی ڈالے تاکہ جو مرے بصیرت پر یعنی یقین جان کر مرے اور جو جیتا رہے وہ بھی بصیرت پر یعنی حق پہچان کر جیتا رہے۔ اور کچھ شک نہیں کہ اللہ سنتا ہے جانتا ہے۔', 'جس وقت تم تھے ورلے کنارہ پر اور وہ پرلے کنارہ پر [۴۴] اور قافلہ نیچے اتر گیا تھا تم سے [۴۵] اور اگر تم آپس میں وعدہ کرتےتو نہ پہنچتے وعدہ پر ایک ساتھ [۴۶] لیکن اللہ کو کر ڈالنا تھا ایک کام کو جو مقرر ہو چکا تھا تاکہ مرے جس کو مرنا ہے قیام حجت کےبعد اور جیوے جس کو جینا ہے قیام حجت کے بعد [۴۷] اور بیشک اللہ سننے والا جاننے والا ہے [۴۸]', '(And remember) when you (the Muslim army) were on the near side of the valley, and they on the farther side, and the caravan on the ground lower than you. Even if you had made a mutual appointment to meet, you would certainly have failed in the appointment, but (you met) that Allah might accomplish a matter already ordained (in His Knowledge); so that those who were to be destroyed (for their rejecting the Faith) might be destroyed after a clear evidence, and those who were to live (i.e. believers) might live after a clear evidence. And surely, Allah is All-Hearer, All-Knower.', '(Remember) when you were on the nearest end of the valley, and they were on the farthest one, and the caravan was downwards from you. Had you made an appointment with each other, you would have disagreed about the appointment. But (it happened like this) so that Allah might accomplish what was destined to be done, so that whoever is going to perish may perish knowingly, and whoever is going to live may live knowingly. Allah is indeed All-Hearing, All-Knowing.'),
(1203, 8, 43, 5, 1, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'اِذۡ یُرِیۡکَہُمُ اللّٰہُ فِیۡ مَنَامِکَ قَلِیۡلًا ؕ وَ لَوۡ اَرٰىکَہُمۡ کَثِیۡرًا لَّفَشِلۡتُمۡ وَ لَتَنَازَعۡتُمۡ فِی الۡاَمۡرِ وَ لٰکِنَّ اللّٰہَ سَلَّمَ ؕ اِنَّہٗ  عَلِیۡمٌۢ  بِذَاتِ  الصُّدُوۡرِ ﴿۴۳﴾', 'اس وقت اللہ نے تمہیں خواب میں کافروں کو تھوڑی تعداد میں دکھایا تھا اور اگر بہت کر کے دکھاتا تو تم لوگ جی چھوڑ دیتے اور جو کام درپیش تھا اس میں جھگڑنے لگتے لیکن اللہ نے تمہیں اس سے بچا لیا بیشک وہ سینوں کی باتوں تک سے واقف ہے۔', 'جب اللہ نے وہ کافر دکھلائے تجھ کو تیری خواب میں تھوڑے [۴۹] اور اگر تجھ کو بہت دکھلا دیتا تو تم لوگ نامردی کرتے اور جھگرا ڈالتے کام میں لیکن اللہ نے بچا لیا اس کو خوب معلوم ہے جو بات ہے دلوں میں [۵۰]', '(And remember) when Allah showed them to you as few in your (i.e. Muhammads SAW) dream, if He had shown them to you as many, you would surely have been discouraged, and you would surely have disputed in making a decision. But Allah saved (you). Certainly, He is the All-Knower of what is in the breasts.', '(Recall) when in your dream, Allah showed them to you few in number. And if He had shown them to you many in number, you would have been demoralized and would have disputed in the matter, but Allah saved (you). Surely, Allah is fully aware of what lies in the hearts.'),
(1204, 8, 44, 5, 1, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'وَ اِذۡ یُرِیۡکُمُوۡہُمۡ  اِذِ الۡتَقَیۡتُمۡ فِیۡۤ اَعۡیُنِکُمۡ قَلِیۡلًا وَّ یُقَلِّلُکُمۡ فِیۡۤ  اَعۡیُنِہِمۡ لِیَقۡضِیَ اللّٰہُ اَمۡرًا کَانَ مَفۡعُوۡلًا ؕ وَ  اِلَی اللّٰہِ تُرۡجَعُ الۡاُمُوۡرُ ﴿٪۴۴﴾', 'اور اس وقت جب تم ایک دوسرے کے مقابل ہوئے تو کافروں کو تمہاری نظروں میں تھوڑا کر کے دکھاتا تھا اور تم کو انکی نگاہوں میں تھوڑا کر کے دکھاتا تھا تاکہ اللہ کو جو کام کرنا منظور تھا اسے کر ڈالے اور سب کاموں کا رجوع اللہ ہی کی طرف ہے۔', 'اور جب تم کو دکھلائی وہ فوج مقابلہ کے وقت تمہاری آنکھوں میں تھوڑی اور تم کو تھوڑا دکھلایا ان کی آنکھوں میں تاکہ کر ڈالے اللہ ایک کام جو مقرر ہو چکا تھا اور اللہ تک پہنچتا ہے ہر کام [۵۱]', 'And (remember) when you met (the army of the disbelievers on the Day of the battle of Badr), He showed them to you as few in your eyes and He made you appear as few in their eyes, so that Allah might accomplish a matter already ordained (in His Knowledge), and to Allah return all matters (for decision).', 'And when, at the time you met each other, He showed them to you few in number in your eyes, and reduced your number in their eyes, so that Allah might accomplish what was destined to be done. And to Allah all matters are returned.'),
(1205, 8, 45, 6, 2, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اِذَا لَقِیۡتُمۡ فِئَۃً فَاثۡبُتُوۡا وَ اذۡکُرُوا اللّٰہَ کَثِیۡرًا لَّعَلَّکُمۡ  تُفۡلِحُوۡنَ ﴿ۚ۴۵﴾', 'مومنو! جب کفار کی کسی جماعت سے تمہارا مقابلہ ہو تو ثابت قدم رہو اور اللہ کو بہت بہت یاد کرو تاکہ مراد حاصل کر لو۔', 'اے ایمان والو جب بھڑو کسی فوج سے تو ثابت قدم رہو اور اللہ کو بہت یاد کرو [۵۲] تاکہ تم مراد پاؤ', 'O you who believe! When you meet (an enemy) force, take a firm stand against them and remember the Name of Allah much (both with tongue and mind), so that you may be successful.', 'O you who believe, when you face a group (in battle), stand firm and remember Allah abundantly, so that you may be successful.'),
(1206, 8, 46, 6, 2, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'وَ اَطِیۡعُوا اللّٰہَ  وَ رَسُوۡلَہٗ  وَ لَا  تَنَازَعُوۡا فَتَفۡشَلُوۡا  وَ تَذۡہَبَ رِیۡحُکُمۡ وَ اصۡبِرُوۡا ؕ اِنَّ  اللّٰہَ  مَعَ  الصّٰبِرِیۡنَ ﴿ۚ۴۶﴾', 'اور اللہ اور اسکے رسول کے حکم پر چلو اور آپس میں جھگڑا نہ کرنا کہ ایسا کرو گے تو تم بزدل ہو جاؤ گے اور تمہاری ہوا اکھڑ جائے گی اور صبر سے کام لو کہ اللہ صبر کرنے والوں کا مددگار ہے۔', 'اور حکم مانو اللہ کا اور اسکے رسول کا اور آپس میں نہ جھگڑو پس نامرد ہو جاؤ گے اور جاتی رہے گی تمہاری ہوا [۵۳] اور صبر کرو بیشک اللہ ساتھ ہے صبر والوں کے [۵۴]', 'And obey Allah and His Messenger, and do not dispute (with one another) lest you lose courage and your strength depart, and be patient. Surely, Allah is with those who are As-Sabirin (the patient ones, etc.).', 'Obey Allah and His Messenger, and do not quarrel with each other, lest you should lose courage, and your prowess should evaporate; and be patient. Surely, Allah is with the patient.'),
(1207, 8, 47, 6, 2, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'وَ لَا تَکُوۡنُوۡا کَالَّذِیۡنَ خَرَجُوۡا مِنۡ دِیَارِہِمۡ بَطَرًا وَّ رِئَآءَ النَّاسِ وَ یَصُدُّوۡنَ عَنۡ سَبِیۡلِ اللّٰہِ ؕ وَ اللّٰہُ بِمَا یَعۡمَلُوۡنَ  مُحِیۡطٌ ﴿۴۷﴾', 'اور ان لوگوں جیسے نہ ہونا جو اتراتے ہوئے یعنی حق کا مقابلہ کرنے کے لئے اور لوگوں کو دکھانے کے لئے گھروں سے نکل آئے اور لوگوں کو اللہ کی راہ سے روکتے ہیں۔ اور جو اعمال یہ کرتے ہیں اللہ ان کا احاطہ کئے ہوئے ہے۔', 'اور نہ ہو جاؤ ان جیسے جو کہ نکلے اپنے گھروں سے اتراتے ہوئے اور لوگوں کے دکھانے کو اور روکتے تھے اللہ کی راہ سے اور اللہ کے قابو میں ہے جو کچھ وہ کرتے ہیں [۵۵]', 'And be not like those who come out of their homes boastfully and to be seen of men, and hinder (men) from the Path of Allah. and Allah is Muheetun (encircling and thoroughly comprehending) all that they do.', 'And do not be like those who set forth from their homes waxing proud and showing off to people, preventing (people) from the way of Allah. Allah is All-Encompassing of what they do.'),
(1208, 8, 48, 6, 2, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'وَ اِذۡ زَیَّنَ لَہُمُ الشَّیۡطٰنُ اَعۡمَالَہُمۡ  وَ قَالَ لَا غَالِبَ لَکُمُ  الۡیَوۡمَ مِنَ النَّاسِ  وَ اِنِّیۡ جَارٌ لَّکُمۡ ۚ فَلَمَّا تَرَآءَتِ الۡفِئَتٰنِ نَکَصَ عَلٰی عَقِبَیۡہِ وَ قَالَ اِنِّیۡ بَرِیۡٓءٌ مِّنۡکُمۡ  اِنِّیۡۤ  اَرٰی مَا لَا تَرَوۡنَ  اِنِّیۡۤ  اَخَافُ اللّٰہَ ؕ وَ اللّٰہُ شَدِیۡدُ الۡعِقَابِ ﴿٪۴۸﴾', 'اور جب شیطان نے انکے اعمال انکو آراستہ کر دکھائے اور کہا کہ آج کے دن لوگوں میں سے کوئی تم پر غالب نہ ہوگا۔ اور میں تمہارا رفیق ہوں لیکن جب دونوں فوجیں ایک دوسرے کے مقابل صف آرا ہوئیں تو پسپا ہو کر چل دیا۔ اور کہنے لگا کہ مجھے تم سے کوئی واسطہ نہیں۔ میں تو ایسی چیزیں دیکھ رہا ہوں جو تم نہیں دیکھ سکتے مجھے تو اللہ سے ڈر لگتا ہے۔ اور اللہ سخت عذاب کرنے والا ہے۔', 'اور جس وقت خوشنما کر دیا شیطان نے انکی نظروں میں ان کے عملوں کو اور بولا کہ کوئی بھی غالب نہ ہوگا تم پر آج کے دن لوگوں میں سے اور میں تمہارا حمایتی ہوں پھر جب سامنے ہوئیں دونوں فوجیں تو وہ الٹا پھرا اپنی ایڑیوں پر اور بولا میں تمہارے ساتھ نہیں ہو ں میں دیکھتا ہوں جو تم نہیں دیکھتے میں ڈرتا ہوں اللہ سے اور اللہ کا عذاب سخت ہے [۵۶]', 'And (remember) when Shaitan (Satan) made their (evil) deeds seem fair to them and said, \"No one of mankind can overcome you this Day (of the battle of Badr) and verily, I am your neighbour (for each and every help).\" But when the two forces came in sight of each other, he ran away and said \"Verily, I have nothing to do with you. Verily! I see what you see not. Verily! I fear Allah for Allah is Severe in punishment.\"', 'When the Satan made their deeds look beautiful to their eyes, and said, “None of the people can overpower you today, and I am a protector for you.” But, when the two groups faced each other, he turned back on his heels and said, “I am quit of you. I am seeing what you do not see. I am scared of Allah, and Allah is severe in punishment.”'),
(1209, 8, 49, 7, 3, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'اِذۡ یَقُوۡلُ الۡمُنٰفِقُوۡنَ وَ الَّذِیۡنَ فِیۡ قُلُوۡبِہِمۡ مَّرَضٌ غَرَّہٰۤؤُ لَآءِ دِیۡنُہُمۡ ؕ وَ مَنۡ یَّتَوَکَّلۡ عَلَی اللّٰہِ فَاِنَّ اللّٰہَ عَزِیۡزٌ حَکِیۡمٌ ﴿۴۹﴾', 'اس وقت منافق اور کافر جن کے دلوں میں بیماری تھی کہتے تھے کہ ان لوگوں کو ان کے دین نے مغرور کر رکھا ہے۔ اور جو شخص اللہ پر بھروسہ رکھتا ہے تو اللہ غالب ہے حکمت والا ہے۔', 'جب کہنے لگے منافق اور جن کےدلوں میں بیماری ہے یہ لوگ مغرور ہیں اپنے دین پر اور جو کوئی بھروسہ کرے اللہ پر تو اللہ زبردست ہے حکمت والا [۵۷]', 'When the hypocrites and those in whose hearts was a disease (of disbelief) said: \"These people (Muslims) are deceived by their religion.\" But whoever puts his trust in Allah, then surely, Allah is All-Mighty, All-Wise.', 'When the hypocrites and those who have a malady in their hearts said, “The belief of these people has deluded them.” And whoever places his trust in Allah (becomes victorious, because) Allah is Mighty, Wise.'),
(1210, 8, 50, 7, 3, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'وَ لَوۡ تَرٰۤی اِذۡ یَتَوَفَّی الَّذِیۡنَ کَفَرُوا ۙ الۡمَلٰٓئِکَۃُ یَضۡرِبُوۡنَ  وُجُوۡہَہُمۡ وَ اَدۡبَارَہُمۡ ۚ وَ ذُوۡقُوۡا  عَذَابَ الۡحَرِیۡقِ ﴿۵۰﴾', 'اور کاش تم اس وقت کی کیفیت دیکھو جب فرشتے کافروں کی جانیں نکالتے ہیں کہ ان کے چہروں اور پیٹھوں پر مارتے جاتے ہیں اور کہتے ہیں اب آگ کے عذاب کا مزا چکھو۔', 'اور اگر تو دیکھے جس وقت جان قبض کرتے ہیں کافروں کی فرشتے مارتے ہیں ان کے منہ پر اور ان کے پیچھے اور کہتے ہیں چکھو عذاب جلنے کا [۵۸]', 'And if you could see when the angels take away the souls of those who disbelieve (at death), they smite their faces and their backs, (saying): \"Taste the punishment of the blazing Fire.\"', 'Only if you were to see (them) when the angels take out the souls of those who disbelieve, beating their faces and their backs, and (saying) “Taste the punishment of the flaming Fire.'),
(1211, 8, 51, 7, 3, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'ذٰلِکَ بِمَا قَدَّمَتۡ اَیۡدِیۡکُمۡ وَ اَنَّ اللّٰہَ لَیۡسَ  بِظَلَّامٍ   لِّلۡعَبِیۡدِ ﴿ۙ۵۱﴾', 'یہ ان اعمال کی سزا ہے جو تمہارے ہاتھوں نے آگے بھیجے ہیں۔ اور یہ جان رکھو کہ اللہ بندوں پر ظلم نہیں کرتا۔', 'یہ بدلا ہے اسی کا جو تم نے آگے بھیجا اپنے ہاتھوں اور اس واسطے کہ اللہ ظلم نہیں کرتا بندوں پر [۵۹]', '\"This is because of that which your hands had forwarded. And verily, Allah is not unjust to His slaves.\"', 'That is due to what your hands sent ahead, and that Allah is not cruel to (His) servants.”'),
(1212, 8, 52, 7, 3, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'کَدَاۡبِ اٰلِ فِرۡعَوۡنَ ۙ وَ الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ ؕ  کَفَرُوۡا بِاٰیٰتِ اللّٰہِ  فَاَخَذَہُمُ اللّٰہُ  بِذُنُوۡبِہِمۡ ؕ اِنَّ اللّٰہَ  قَوِیٌّ شَدِیۡدُ الۡعِقَابِ ﴿۵۲﴾', 'جیسا حال فرعونیوں اور ان سے پہلے لوگوں کا ہوا تھا ویسا ہی ان کا ہوا کہ انہوں نے اللہ کی آیتوں سے کفر کیا تو اللہ نے انکے گناہوں کی سزا میں انکو پکڑ لیا بیشک اللہ زبردست ہے سخت عذاب دینے والا ہے۔', 'جیسے دستور فرعون والوں کا اور جو ان سے پہلے تھے کہ منکر ہوئے اللہ کی باتوں سے سو پکڑا ان کو اللہ نے ان کے گناہوں پر بیشک اللہ زور آور ہے سخت عذاب کرنے والا [۶۰]', 'Similar to the behaviour of the people of Firaun (Pharaoh), and of those before them; they rejected the Ayat (proofs, verses, etc.) of Allah, so Allah punished them for their sins. Verily, Allah is All-Strong, Severe in punishment.', '(Their way is) like the way of the people of Pharaoh and of those before them. They rejected the signs of Allah; so Allah seized them for their sins. Surely, Allah is strong, severe in punishment.'),
(1213, 8, 53, 7, 3, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'ذٰلِکَ بِاَنَّ  اللّٰہَ  لَمۡ یَکُ مُغَیِّرًا  نِّعۡمَۃً اَنۡعَمَہَا عَلٰی قَوۡمٍ حَتّٰی یُغَیِّرُوۡا مَا بِاَنۡفُسِہِمۡ ۙ وَ اَنَّ  اللّٰہَ  سَمِیۡعٌ  عَلِیۡمٌ ﴿ۙ۵۳﴾', 'یہ اس لئے کہ جو نعمت اللہ کسی قوم کو دیا کرتا ہے جب تک وہ خود اپنے دلوں کی حالت نہ بدل ڈالیں اللہ اسے نہیں بدلا کرتا اور اس لئے کہ اللہ سنتا جانتا ہے۔', 'اس کا سبب یہ ہے کہ اللہ ہر گز بدلنے والا نہیں اس نعمت کو جو دی تھی اس نے کسی قوم کو جب تک وہی نہ بدل ڈالیں اپنے جیوں کی بات اور یہ کہ اللہ سننے والا جاننے والا ہے [۶۱]', 'That is so because Allah will never change a grace which He has bestowed on a people until they change what is in their ownselves. And verily, Allah is All-Hearer, All-Knower.', 'All this is because Allah is not the one who may change a favour He has conferred on a people unless they change their own condition, and that Allah is All-Hearing, All-Knowing.'),
(1214, 8, 54, 7, 3, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'کَدَاۡبِ اٰلِ فِرۡعَوۡنَ ۙ وَ الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ ؕ کَذَّبُوۡا بِاٰیٰتِ رَبِّہِمۡ فَاَہۡلَکۡنٰہُمۡ بِذُنُوۡبِہِمۡ وَ اَغۡرَقۡنَاۤ  اٰلَ فِرۡعَوۡنَ ۚ وَ کُلٌّ  کَانُوۡا ظٰلِمِیۡنَ ﴿۵۴﴾', 'جیسا حال فرعونیوں اور ان سے پہلے لوگوں کا ہوا تھا ویسا ہی ان کا ہوا انہوں نے اپنے پروردگار کی آیتوں کو جھٹلایا تو ہم نے انکو ان کے گناہوں کے سبب ہلاک کر ڈالا اور فرعونیوں کو ڈبو دیا۔ اور وہ سب ظالم تھے۔', 'جیسے دستور فرعون والوں کا اور جو ان سے پہلے تھے کہ انہوں نے جھٹلائیں باتیں اپنے رب کی پھر ہلاک کر دیا ہم نے انکو انکے گناہوں پر اور ڈبو دیا ہم نے فرعون والوں کو اور سارے ظالم تھے [۶۲]', 'Similar to the behaviour of the people of Firaun (Pharaoh), and those before them. They belied the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), of their Lord, so We destroyed them for their sins, and We drowned the people of Firaun (Pharaoh) for they were all Zalimoon (polytheists and wrong-doers, etc.).', 'Their practice is like that of the people of Pharaoh and those before them. They rejected the signs of their Lord. So, We destroyed them for their sins and drowned the people of Pharaoh; and all of them were wrongdoers.'),
(1215, 8, 55, 7, 3, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'اِنَّ شَرَّ الدَّوَآبِّ عِنۡدَ اللّٰہِ الَّذِیۡنَ کَفَرُوۡا  فَہُمۡ  لَا  یُؤۡمِنُوۡنَ ﴿ۖۚ۵۵﴾', 'جانداروں میں سب سے بدتر اللہ کے نزدیک وہ لوگ ہیں جو کافر ہیں سو وہ ایمان نہیں لاتے۔', 'بدتر سب جانداروں میں اللہ کے ہاں وہ ہیں جو منکر ہوئے پھر وہ نہیں ایمان لاتے', 'Verily, The worst of moving (living) creatures before Allah are those who disbelieve, - so they shall not believe.', 'Surely, the worst of all the moving creatures, in the sight of Allah, are those who reject Faith and do not believe'),
(1216, 8, 56, 7, 3, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'اَلَّذِیۡنَ عٰہَدۡتَّ مِنۡہُمۡ ثُمَّ یَنۡقُضُوۡنَ عَہۡدَہُمۡ  فِیۡ  کُلِّ  مَرَّۃٍ   وَّ ہُمۡ لَا یَتَّقُوۡنَ ﴿۵۶﴾', 'جن لوگوں سے تم نے صلح کا عہد کیا ہے پھر وہ ہر بار اپنے عہد کو توڑ ڈالتے ہیں اور اللہ سے نہیں ڈرتے۔', 'جن سے تو نے معاہدہ کیا ہے ان میں سے پھر وہ توڑتے ہیں اپنا عہد ہر بار اور وہ ڈر نہیں رکھتے [۶۳]', 'They are those with whom you made a covenant, but they break their covenant every time and they do not fear Allah.', '-those with whom you have entered into a treaty, then they break their treaty each time, and they do not fear Allah.'),
(1217, 8, 57, 7, 3, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'فَاِمَّا تَثۡقَفَنَّہُمۡ فِی الۡحَرۡبِ فَشَرِّدۡ بِہِمۡ مَّنۡ  خَلۡفَہُمۡ  لَعَلَّہُمۡ  یَذَّکَّرُوۡنَ ﴿۵۷﴾', 'اگر تم ان کو لڑائی میں پاؤ تو انہیں ایسی سزا دو کہ جو لوگ ان کے پس پشت ہوں وہ انکو دیکھ کر بھاگ جائیں عجب نہیں کہ انکو اس سے عبرت ہو۔', 'سو اگر کبھی تو پائے ان کو لڑائی میں تو انکو ایسی سزا دے کہ دیکھ کر بھاگ جائیں ان کے پچھلے تاکہ ان کو عبرت ہو', 'So if you gain the mastery over them in war, punish them severely in order to disperse those who are behind them, so that they may learn a lesson.', 'So, if you find them in war, deal with them in a way that those behind them have to disperse fearfully, so that they take a lesson.'),
(1218, 8, 58, 7, 3, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'وَ  اِمَّا  تَخَافَنَّ مِنۡ قَوۡمٍ خِیَانَۃً  فَانۡۢبِذۡ اِلَیۡہِمۡ عَلٰی سَوَآءٍ ؕ اِنَّ اللّٰہَ  لَا یُحِبُّ الۡخَآئِنِیۡنَ ﴿٪۵۸﴾', 'اور اگر تم کو کسی قوم سے دغابازی کا خوف ہو تو ان کا عہد انہیں کی طرف پھینک دو کہ اسطرح تم سب برابر ہو جاؤ کچھ شک نہیں کہ اللہ دغابازوں کو دوست نہیں رکھتا۔', 'اور اگر تجھ کو ڈر ہو کسی قوم سےدغا کا تو پھینک دے انکا عہد انکی طرف ایسی طرح پر کہ ہو جاؤ تم اور وہ برابر بیشک اللہ کو خوش نہیں آتے دغاباز [۶۴]', 'If you (O Muhammad SAW) fear treachery from any people throw back (their covenant) to them (so as to be) on equal terms (that there will be no more covenant between you and them). Certainly Allah likes not the treacherous.', 'And if you apprehend a breach from a people, then, throw (the treaty) towards them in straight-forward terms. Surely, Allah does not like those who breach the trust.'),
(1219, 8, 59, 8, 4, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'وَ لَا یَحۡسَبَنَّ الَّذِیۡنَ کَفَرُوۡا سَبَقُوۡا ؕ اِنَّہُمۡ  لَا  یُعۡجِزُوۡنَ ﴿۵۹﴾', 'اور کافر یہ خیال ہرگز نہ کریں کہ وہ آگے نکل گئے ہیں وہ ہمیں عاجز نہیں کر سکتے۔', 'اور یہ نہ سمجھیں کافر لوگ کہ وہ بھاگ نکلے وہ ہرگز تھکا نہ سکیں گے ہم کو [۶۵]', 'And let not those who disbelieve think that they can outstrip (escape from the punishment). Verily, they will never be able to save themselves (from Allahs Punishment).', 'The disbelievers should never think that they have surpassed (the divine punishment). Surely, they cannot frustrate (the Divine will).'),
(1220, 8, 60, 8, 4, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'وَ اَعِدُّوۡا لَہُمۡ مَّا اسۡتَطَعۡتُمۡ مِّنۡ قُوَّۃٍ وَّ مِنۡ رِّبَاطِ الۡخَیۡلِ تُرۡہِبُوۡنَ بِہٖ عَدُوَّ اللّٰہِ وَ عَدُوَّکُمۡ  وَ اٰخَرِیۡنَ مِنۡ دُوۡنِہِمۡ ۚ لَا تَعۡلَمُوۡنَہُمۡ ۚ اَللّٰہُ یَعۡلَمُہُمۡ ؕ وَ مَا تُنۡفِقُوۡا مِنۡ شَیۡءٍ  فِیۡ  سَبِیۡلِ  اللّٰہِ  یُوَفَّ اِلَیۡکُمۡ  وَ  اَنۡتُمۡ  لَا  تُظۡلَمُوۡنَ ﴿۶۰﴾', 'اور جہاں تک ہو سکے فوج کی جمعیت کے زور سے اور گھوڑوں کے تیار رکھنے سے انکے مقابلے کے لئے مستعد رہو کہ اس سے اللہ کے دشمنوں اور تمہارے دشمنوں اور انکے سوا اور لوگوں پر جنکو تم نہیں جانتے اور اللہ جانتا ہے ہیبت بیٹھی رہے گی۔ اور تم جو کچھ اللہ کی راہ میں خرچ کرو گے اس کا ثواب تم کو پورا پورا دیا جائے گا اور تمہارا ذرا نقصان نہ کیا جائے گا۔', 'اور تیار کرو انکی لڑائی کے واسطے جو کچھ جمع کر سکو قوت سے اور پلے ہوئے گھوڑوں سے [۶۶] کہ اس سے دھاک پڑے اللہ کے دشمنوں پر اور تمہارے دشمنوں پر اور دوسروں پر ان کےسوا جن کو تم نہیں جانتے اللہ ان کو جانتا ہے [۶۷] اور جو کچھ تم خرچ کرو گے اللہ کی راہ میں وہ پورا ملے گا تم کو اور تمہار حق نہ رہ جائے گا [۶۸]', 'And make ready against them all you can of power, including steeds of war (tanks, planes, missiles, artillery, etc.) to threaten the enemy of Allah and your enemy, and others besides whom, you may not know but whom Allah does know. And whatever you shall spend in the Cause of Allah shall be repaid unto you, and you shall not be treated unjustly.', 'Prepare against them whatever force you can, and the trained horses whereby you frighten Allah’s enemy and your own enemy and others besides them whom you do not know. Allah knows them. Whatever thing you spend in the way of Allah, it will be paid to you in full, and you shall not be wronged.'),
(1221, 8, 61, 8, 4, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'وَ اِنۡ جَنَحُوۡا لِلسَّلۡمِ فَاجۡنَحۡ لَہَا وَ تَوَکَّلۡ عَلَی اللّٰہِ ؕ اِنَّہٗ ہُوَ السَّمِیۡعُ الۡعَلِیۡمُ ﴿۶۱﴾', 'اور اگر یہ لوگ صلح کی طرف مائل ہوں تو تم بھی اس کی طرف مائل ہو جاؤ اور اللہ پر بھروسہ رکھو۔ کچھ شک نہیں کہ وہ سب کچھ سنتا ہے جانتا ہے۔', 'اور اگر وہ جھکیں صلح کی طرف تو تو بھی جھک اسی طرف اور بھروسہ کر اللہ پر بیشک وہی ہے سننے والا جاننے والا [۶۹]', 'But if they incline to peace, you also incline to it, and (put your) trust in Allah. Verily, He is the All-Hearer, the All-Knower.', 'And if they tilt towards peace, you too should tilt towards it, and place your trust in Allah. Surely, He is the All-Hearing, the All-Knowing.'),
(1222, 8, 62, 8, 4, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'وَ اِنۡ یُّرِیۡدُوۡۤا اَنۡ یَّخۡدَعُوۡکَ فَاِنَّ حَسۡبَکَ اللّٰہُ ؕ ہُوَ  الَّذِیۡۤ   اَیَّدَکَ  بِنَصۡرِہٖ وَ بِالۡمُؤۡمِنِیۡنَ ﴿ۙ۶۲﴾', 'اور اگر یہ چاہیں کہ تم کو فریب دیں تو اللہ تمہیں کفایت کرے گا۔ وہی تو ہے جس نے تم کو اپنی مدد سے اور مسلمانوں کی جمعیت سے تقویت بخشی۔', 'اور اگر وہ چاہیں کہ تجھ کو دغا دیں تو تجھ کو کافی ہے اللہ اسی نے تجھ کو زور دیا اپنی مدد کا اور مسلمانوں کا [۷۰]', 'And if they intend to deceive you, then verily, Allah is All-Sufficient for you. He it is Who has supported you with His Help and with the believers.', 'If they intend to deceive you, then, Allah is all-sufficient for you. He is the One who supported you with His help and with the believers,'),
(1223, 8, 63, 8, 4, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'وَ اَلَّفَ بَیۡنَ قُلُوۡبِہِمۡ ؕ لَوۡ اَنۡفَقۡتَ مَا فِی الۡاَرۡضِ جَمِیۡعًا مَّاۤ  اَلَّفۡتَ بَیۡنَ قُلُوۡبِہِمۡ وَ لٰکِنَّ اللّٰہَ  اَلَّفَ بَیۡنَہُمۡ ؕ اِنَّہٗ  عَزِیۡزٌ  حَکِیۡمٌ ﴿۶۳﴾', 'اور انکے دلوں میں الفت پیدا کر دی۔ اور اگر تم دنیا بھر کی دولت خرچ کرتے تب بھی انکے دلوں میں الفت پیدا نہ کر سکتے۔ مگر اللہ ہی نے ان میں الفت ڈال دی بیشک وہ زبردست ہے حکمت والا ہے۔', 'اور الفت ڈالی انکے دلوں میں اگر تو خرچ کر دیتا جو کچھ زمین میں ہے سارا نہ الفت ڈال سکتا ان کے دلوں میں لیکن اللہ نے الفت ڈالی ان میں بیشک وہ زورآور ہے حکمت والا [۷۱]', 'And He has united their (i.e. believers) hearts. If you had spent all that is in the earth, you could not have united their hearts, but Allah has united them. Certainly He is All-Mighty, All-Wise.', 'and united their hearts. Had you spent all that is on earth, you could not have united their hearts. But Allah did unite their hearts. Surely, He is All-Mighty, All-Wise.'),
(1224, 8, 64, 8, 4, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'یٰۤاَیُّہَا النَّبِیُّ حَسۡبُکَ اللّٰہُ وَ مَنِ اتَّبَعَکَ  مِنَ  الۡمُؤۡمِنِیۡنَ ﴿٪۶۴﴾', 'اے نبی! اللہ تم کو اور مومنوں کو جو تمہارے پیرو ہیں کافی ہے۔', 'اے نبی کافی ہے تجھ کو اللہ اور جتنے تیرے ساتھ ہیں مسلمان [۷۲]', 'O Prophet (Muhammad SAW)! Allah is Sufficient for you and for the believers who follow you.', 'O Prophet, Allah is sufficient for you, and the believers who followed you.'),
(1225, 8, 65, 9, 5, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'یٰۤاَیُّہَا النَّبِیُّ حَرِّضِ الۡمُؤۡمِنِیۡنَ عَلَی الۡقِتَالِ ؕ اِنۡ یَّکُنۡ مِّنۡکُمۡ عِشۡرُوۡنَ صٰبِرُوۡنَ یَغۡلِبُوۡا مِائَتَیۡنِ ۚ وَ اِنۡ  یَّکُنۡ مِّنۡکُمۡ  مِّائَۃٌ  یَّغۡلِبُوۡۤا اَلۡفًا مِّنَ الَّذِیۡنَ  کَفَرُوۡا بِاَنَّہُمۡ قَوۡمٌ لَّا یَفۡقَہُوۡنَ ﴿۶۵﴾', 'اے نبی! مسلمانوں کو جہاد کی ترغیب دو۔ اگر تم میں بیس آدمی ثابت قدم رہنے والے ہوں گے تو دو سو کافروں پر غالب رہیں گے۔ اور اگر سو ایسے ہوں گے تو ہزار پر غالب رہیں گے۔ اس لئے کہ کافر ایسے لوگ ہیں کہ کچھ بھی سمجھ نہیں رکھتے۔', 'اے نبی شوق دلا مسلمانوں کو لڑائی کا اگر ہوں تم میں بیس شخص ثابت قدم رہنے والے تو غالب ہوں دو سو پر اور اگر ہوں تم میں سو شخص تو غالب ہوں ہزار کافروں پر اس واسطے کہ وہ لوگ سمجھ نہیں رکھتے [۷۳]', 'O Prophet (Muhammad SAW)! Urge the believers to fight. If there are twenty steadfast persons amongst you, they will overcome two hundred, and if there be a hundred steadfast persons they will overcome a thousand of those who disbelieve, because they (the disbelievers) are people who do not understand.', 'O Prophet, rouse the believers to fighting. If there are twenty among you, who are patient, they will overcome two hundred; and if there are one hundred among you, they will overcome one thousand of those who disbelieve, because they are a people who do not understand.'),
(1226, 8, 66, 9, 5, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'اَلۡـٰٔنَ خَفَّفَ اللّٰہُ عَنۡکُمۡ وَ عَلِمَ اَنَّ فِیۡکُمۡ ضَعۡفًا ؕ فَاِنۡ یَّکُنۡ مِّنۡکُمۡ مِّائَۃٌ صَابِرَۃٌ  یَّغۡلِبُوۡا مِائَتَیۡنِ ۚ وَ اِنۡ یَّکُنۡ مِّنۡکُمۡ اَلۡفٌ یَّغۡلِبُوۡۤا اَلۡفَیۡنِ بِاِذۡنِ اللّٰہِ ؕ وَ اللّٰہُ  مَعَ  الصّٰبِرِیۡنَ ﴿۶۶﴾', 'اب اللہ نے تم پر سے بوجھ ہلکا کر دیا اور معلوم کر لیا کہ ابھی تم میں کسی قدر کمزوری ہے۔ پس اگر تم میں ایک سو ثابت قدم رہنے والے ہوں گے تو وہ دو سو پر غالب رہیں گے اور اگر ایک ہزار ہوں گے تو اللہ کے حکم سے دو ہزار پر غالب رہیں گے اور اللہ ثابت قدم رہنے والوں کا مددگار ہے۔', 'اب بوجھ ہلکا کر دیا اللہ نے تم پر سے اور جانا کہ تم میں سستی ہےسو اگر ہوں تم میں سو شخص ثابت قدم رہنے والے تو غالب ہوں دو سو پر اور اگر ہوں تم میں ہزار تو غالب ہوں دو ہزار پر اللہ کے حکم سے اور اللہ ساتھ ہے ثابت قدم رہنے والوں کے [۷۴]', 'Now Allah has lightened your (task), for He knows that there is weakness in you. So if there are of you a hundred steadfast persons, they shall overcome two hundred, and if there are a thousand of you, they shall overcome two thousand with the Leave of Allah. And Allah is with As-Sabirin (the patient ones, etc.).', 'Now Allah has lightened your burden, and He knew that there is weakness in you. So, if there are one hundred among you, who are patient, they will overcome two hundred; and if there are one thousand among you, they will overcome two thousand by the will of Allah. Allah is with the patient.'),
(1227, 8, 67, 9, 5, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'مَا  کَانَ  لِنَبِیٍّ  اَنۡ  یَّکُوۡنَ  لَہٗۤ  اَسۡرٰی حَتّٰی یُثۡخِنَ فِی الۡاَرۡضِ ؕ تُرِیۡدُوۡنَ عَرَضَ الدُّنۡیَا ٭ۖ وَ اللّٰہُ  یُرِیۡدُ  الۡاٰخِرَۃَ ؕ وَ اللّٰہُ  عَزِیۡزٌ  حَکِیۡمٌ ﴿۶۷﴾', 'پیغمبر کو شایاں نہیں کہ اس کے قبضے میں قیدی رہیں جب تک کافروں کو قتل کر کے زمین میں کثرت سے خون نہ بہا دے۔ تم لوگ دنیا کے مال کے طالب ہو اور اللہ آخرت کی بھلائی چاہتا ہے اور اللہ غالب ہے حکمت والا ہے۔', 'نبی کو نہیں چاہئے کہ اپنے ہاں رکھے قیدیوں کو جب تک خوب خونریزی نہ کر لے ملک میں تم چاہتے ہو اسباب دنیا اور اور اللہ کے ہاں چاہئے آخرت اور اللہ زور آور ہے حکمت والا [۷۵]', 'It is not for a Prophet that he should have prisoners of war (and free them with ransom) until he had made a great slaughter (among his enemies) in the land. You desire the good of this world (i.e. the money of ransom for freeing the captives), but Allah desires (for you) the Hereafter. And Allah is All-Mighty, All-Wise.', 'It is not befitting a prophet that he has captives with him unless he has subdued the enemy by shedding blood in the land. You intend to have the stuff of this world, while Allah intends the Hereafter (for you). And Allah is All-Mighty, All-Wise.'),
(1228, 8, 68, 9, 5, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'لَوۡ لَا کِتٰبٌ مِّنَ اللّٰہِ سَبَقَ لَمَسَّکُمۡ فِیۡمَاۤ  اَخَذۡتُمۡ  عَذَابٌ  عَظِیۡمٌ ﴿۶۸﴾', 'اگر اللہ کا حکم پہلے نہ ہو چکا ہوتا تو جو فدیہ تم نے لیا ہے اسکے بدلے تم پر بڑا عذاب نازل ہوتا۔', 'اگر نہ ہوتی ایک بات جس کو لکھ چکا اللہ پہلے سے تو تم کو پہنچتا اس لینے میں بڑا عذاب [۷۶]', 'Were it not a previous ordainment from Allah, a severe torment would have touched you for what you took.', 'Had there not been a decree from Allah that came earlier, a great punishment would have overtaken you because of what you have taken.'),
(1229, 8, 69, 9, 5, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'فَکُلُوۡا مِمَّا غَنِمۡتُمۡ حَلٰلًا طَیِّبًا ۫ۖ وَّ اتَّقُوا  اللّٰہَ ؕ اِنَّ  اللّٰہَ  غَفُوۡرٌ  رَّحِیۡمٌ ﴿٪۶۹﴾', 'اب  جو مال غنیمت تمہیں ملا ہے اسے کھاؤ کہ وہ تمہارے لئے حلال طیب ہے اور اللہ سے ڈرتے رہو بیشک اللہ بخشنے والا ہے مہربان ہے۔', 'سو کھاؤ جو تم کو غنیمت میں ملا حلال ستھرا اور ڈرتے رہو اللہ سے بیشک اللہ ہے بخشنے والا مہربان [۷۷]', 'So enjoy what you have gotten of booty in war, lawful and good, and be afraid of Allah. Certainly, Allah is Oft-Forgiving, Most Merciful.', 'So, eat of the spoils you have got, lawful and pure, and fear Allah. Surely, Allah is Most-Forgiving, Very-Merciful.'),
(1230, 8, 70, 10, 6, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'یٰۤاَیُّہَا النَّبِیُّ  قُلۡ  لِّمَنۡ فِیۡۤ  اَیۡدِیۡکُمۡ  مِّنَ الۡاَسۡرٰۤی ۙ اِنۡ یَّعۡلَمِ اللّٰہُ فِیۡ  قُلُوۡبِکُمۡ خَیۡرًا یُّؤۡتِکُمۡ  خَیۡرًا  مِّمَّاۤ  اُخِذَ مِنۡکُمۡ وَ  یَغۡفِرۡ لَکُمۡ ؕ وَ اللّٰہُ غَفُوۡرٌ رَّحِیۡمٌ ﴿۷۰﴾', 'اے پیغمبر جو قیدی تمہارے قبضے میں یعنی گرفتار ہیں ان سے کہدو کہ اگر اللہ تمہارے دلوں میں نیکی معلوم کرے گا تو جو مال تم سے چھن گیا ہے اس سے بہتر تمہیں عنایت فرمائے گا اور تمہارے گناہ بھی معاف کر دے گا۔ اور اللہ بخشنے والا ہے مہربان ہے۔', 'اے نبی کہہ دے ان سے جو تمہارے ہاتھ میں ہیں قیدی اگر جانے گا اللہ تمہارے دلوں میں کچھ نیکی تو دے گا تم کو بہتر اس سے جو تم سے چھن گیا اور تم کو بخشے گا اور اللہ ہے بخشنے والا مہربان', 'O Prophet! Say to the captives that are in your hands: \"If Allah knows any good in your hearts, He will give you something better than what has been taken from you, and He will forgive you, and Allah is Oft-Forgiving, Most Merciful.\"', 'O Prophet, say to the prisoners in your hands, “If Allah knows any goodness in your hearts, He will give you something better than what has been taken from you, and will forgive you. Allah is Most-Forgiving, Very-Merciful.”'),
(1231, 8, 71, 10, 6, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'وَ اِنۡ یُّرِیۡدُوۡا خِیَانَتَکَ فَقَدۡ خَانُوا اللّٰہَ مِنۡ قَبۡلُ فَاَمۡکَنَ مِنۡہُمۡ ؕ وَ اللّٰہُ عَلِیۡمٌ  حَکِیۡمٌ ﴿۷۱﴾', 'اور اگر یہ لوگ تم سے دغا کرنا چاہیں گے تو یہ پہلے ہی اللہ سے دغا کر چکے ہیں تو اس نے انکو تمہارے قبضے میں کر دیا۔ اور اللہ دانا ہے حکمت والا ہے۔', 'اور اگر چاہیں گے تجھ سے دغا کرنی سو وہ دغا کر چکے ہیں اللہ سے اس سے پہلے پھر اس نے انکو پکڑوا دیا اور اللہ سب کچھ جاننے والا حکمت والا ہے [۷۸]', 'But if they intend to betray you (O Muhammad SAW), they have already betrayed Allah before. So He gave (you) power over them. And Allah is All-Knower, All-Wise.', 'And if they intend to commit treachery against you, then, they have already committed treachery against Allah, and in turn Allah has given you full control over them. And Allah is All-Knowing, Wise.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1232, 8, 72, 10, 6, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'اِنَّ الَّذِیۡنَ اٰمَنُوۡا وَ ہَاجَرُوۡا وَ جٰہَدُوۡا بِاَمۡوَالِہِمۡ وَ اَنۡفُسِہِمۡ فِیۡ سَبِیۡلِ اللّٰہِ وَ الَّذِیۡنَ اٰوَوۡا وَّ نَصَرُوۡۤا اُولٰٓئِکَ بَعۡضُہُمۡ اَوۡلِیَآءُ بَعۡضٍ ؕ وَ الَّذِیۡنَ اٰمَنُوۡا وَ لَمۡ یُہَاجِرُوۡا مَا لَکُمۡ مِّنۡ وَّلَایَتِہِمۡ مِّنۡ شَیۡءٍ حَتّٰی یُہَاجِرُوۡا ۚ وَ اِنِ اسۡتَنۡصَرُوۡکُمۡ فِی الدِّیۡنِ فَعَلَیۡکُمُ النَّصۡرُ  اِلَّا عَلٰی قَوۡمٍۭ بَیۡنَکُمۡ وَ بَیۡنَہُمۡ مِّیۡثَاقٌ ؕ وَ اللّٰہُ بِمَا تَعۡمَلُوۡنَ  بَصِیۡرٌ ﴿۷۲﴾', 'جو لوگ ایمان لائے اور جنہوں نے ہجرت کی اور اللہ کی راہ میں اپنے مال اور جان سے لڑے۔ وہ اور جنہوں نے ہجرت کرنے والوں کو جگہ دی اور انکی مدد کی وہ آپس میں ایک دوسرے کے رفیق ہیں اور جو لوگ ایمان تو لے آئے لیکن ہجرت نہیں کی تو جب تک وہ ہجرت نہ کریں تم کو انکی رفاقت سے کچھ سروکار نہیں۔ اور اگر وہ تم سے دین کے معاملات میں مدد طلب کریں تو تم کو مدد کرنی لازم ہے۔ مگر ان لوگوں کے مقابلے میں کہ تم میں اور ان میں صلح کا عہد ہو مدد نہیں کرنی چاہیے اور اللہ تمہارے سب کاموں کو دیکھ رہا ہے۔', 'جو لوگ ایمان لائے اور گھر چھوڑا اور لڑے اپنے مال اور جان سے اللہ کی راہ میں اور جن لوگوں نے جگہ دی اور مدد کی وہ ایک دوسرے کے رفیق ہیں اور جو ایمان لائے اور گھر نہیں چھوڑا تم کو ان کی رفاقت سے کچھ کام نہیں جب تک وہ گھر نہ چھوڑ آئیں اور اگر وہ تم سے مدد چاہیں دین میں تو تم کو لازم ہے انکی مدد کرنی مگر مقابلہ میں ان لوگوں کے کہ ان میں اور تم میں عہد ہو اور اللہ جو تم کرتے ہو اس کو دیکھتا ہے [۷۹]', 'Verily, those who believed, and emigrated and strove hard and fought with their property and their lives in the Cause of Allah as well as those who gave (them) asylum and help, - these are (all) allies to one another. And as to those who believed but did not emigrate (to you O Muhammad SAW), you owe no duty of protection to them until they emigrate, but if they seek your help in religion, it is your duty to help them except against a people with whom you have a treaty of mutual alliance, and Allah is the All-Seer of what you do.', 'Surely those who believed and emigrated and carried out Jihād in the way of Allah with their wealth and lives, and those who gave refuge and help (to the emigrants), both are close friends to each other. And those who believed and did not emigrate, you have no friendship with them at all, unless they emigrate. However, if they seek your help in the matter of faith, then, you are bound to help, except against a people with whom you have a treaty. Allah is watchful over what you do.'),
(1233, 8, 73, 10, 6, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'وَ الَّذِیۡنَ  کَفَرُوۡا  بَعۡضُہُمۡ  اَوۡلِیَآءُ  بَعۡضٍ ؕ اِلَّا تَفۡعَلُوۡہُ  تَکُنۡ فِتۡنَۃٌ  فِی الۡاَرۡضِ وَ فَسَادٌ    کَبِیۡرٌ ﴿ؕ۷۳﴾', 'اور جو لوگ کافر ہیں وہ بھی ایک دوسرے کے رفیق ہیں۔ تو مومنو اگر تم یہ کام نہ کرو گے تو ملک میں فتنہ برپا ہو جائے گا اور بڑا فساد مچے گا۔', 'اور جو لوگ کافر ہیں وہ ایک دوسرے کے رفیق ہیں اگر تم یوں نہ کرو گے تو فتنہ پھیلے گا ملک میں اور بڑی خرابی ہو گی [۸۰]', 'And those who disbelieve are allies to one another, (and) if you (Muslims of the whole world collectively) do not do so (i.e. become allies, as one united block with one Khalifah - chief Muslim ruler for the whole Muslim world to make victorious Allahs Religion of Islamic Monotheism), there will be Fitnah (wars, battles, polytheism, etc.) and oppression on earth, and a great mischief and corruption (appearance of polytheism).', 'And those who disbelieve are friends to each other. If you do not do so, there shall be disorder on the earth, and a great corruption.'),
(1234, 8, 74, 10, 6, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'وَ الَّذِیۡنَ اٰمَنُوۡا وَ ہَاجَرُوۡا وَ جٰہَدُوۡا فِیۡ سَبِیۡلِ اللّٰہِ وَ الَّذِیۡنَ اٰوَوۡا وَّ نَصَرُوۡۤا اُولٰٓئِکَ ہُمُ الۡمُؤۡمِنُوۡنَ حَقًّا ؕ لَہُمۡ مَّغۡفِرَۃٌ   وَّ رِزۡقٌ  کَرِیۡمٌ ﴿۷۴﴾', 'اور جو لوگ ایمان لائے اور وطن سے ہجرت کر گئے اور اللہ کی راہ میں جہاد کرتے رہے اور جنہوں نے ہجرت کرنے والوں کو جگہ دی اور ان کی مدد کی یہی لوگ سچے مسلمان ہیں ان کے لئے اللہ کے ہاں بخشش اور عزت کی روزی ہے۔', 'اور جو لوگ ایمان لائے اور اپنے گھر چھوڑے اور لڑے اللہ کی راہ میں اور جن لوگوں نے ان کو جگہ دی اور انکی مدد کی وہی ہیں سچے مسلمان انکے لئے بخشش ہے اور روزی عزت کی [۸۱]', 'And those who believed, and emigrated and strove hard in the Cause of Allah (Al-Jihad), as well as those who gave (them) asylum and aid; - these are the believers in truth, for them is forgiveness and Rizqun Kareem (a generous provision i.e. Paradise).', 'Those who have believed and emigrated and carried out Jihād in the way of Allah, and those who gave refuge and help, both are the believers in truth. For them there is forgiveness and a respectful provision.'),
(1235, 8, 75, 10, 6, 10, 'وَ اعۡلَمُوۡۤا', 'الانفال', 'وَ الَّذِیۡنَ اٰمَنُوۡا مِنۡۢ بَعۡدُ وَ ہَاجَرُوۡا وَ جٰہَدُوۡا مَعَکُمۡ فَاُولٰٓئِکَ مِنۡکُمۡ ؕ وَ اُولُوا الۡاَرۡحَامِ بَعۡضُہُمۡ اَوۡلٰی بِبَعۡضٍ فِیۡ  کِتٰبِ اللّٰہِ ؕ اِنَّ اللّٰہَ بِکُلِّ شَیۡءٍ عَلِیۡمٌ ﴿٪۷۵﴾', 'اور جو لوگ بعد میں ایمان لائے اور وطن سے ہجرت کر گئے اور تمہارے ساتھ ہو کر جہاد کرتے رہے وہ بھی تم ہی میں سے ہیں اور رشتہ دار اللہ کے حکم کی رو سے ایک دوسرے کے زیادہ حقدار ہیں کچھ شک نہیں کہ اللہ ہر چیز سے واقف ہے۔', 'اور جو ایمان لائے اسکے بعد اور گھر چھوڑ آئے اور لڑے تمہارے ساتھ ہو کر سو وہ لوگ بھی تمہی میں ہیں اور رشتہ دار آپس میں حقدار زیادہ ہیں ایک دوسرے کے اللہ کے حکم میں [۸۲] تحقیق اللہ ہر چیز سے خبردار ہے [۸۳]', 'And those who believed afterwards, and emigrated and strove hard along with you, (in the Cause of Allah) they are of you. But kindred by blood are nearer to one another regarding inheritance in the decree ordained by Allah. Verily, Allah is the All-Knower of everything', 'Those who believed later on and emigrated and carried out Jihād alongwith you, then, they are joined with you. As for the womb-relatives, they are closer to one another according to the Book of Allah. Surely, Allah is aware of every thing.'),
(1236, 9, 1, 1, 7, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'بَرَآءَۃٌ  مِّنَ اللّٰہِ وَ رَسُوۡلِہٖۤ  اِلَی الَّذِیۡنَ عٰہَدۡتُّمۡ  مِّنَ  الۡمُشۡرِکِیۡنَ ؕ﴿۱﴾', '(اس سورت کے شروع میں بسم اللہ نہیں لکھی گئ اس کے مختلف اسباب بیان کئے گئے ہیں) اے اہل اسلام اب اللہ اور اسکے رسول کی طرف سے ان مشرکوں سے جن سے تم نے عہد کر رکھا تھا بیزاری اور جنگ کی تیاری ہے۔', '(اس سورت کے شروع میں بسم اللہ نہیں لکھی گئ اس کے مختلف اسباب بیان کئے گئے ہیں) [۱] صاف جواب ہے اللہ کی طرف سے اور اسکے رسول کی ان مشرکوں کو جن سے تمہارا عہد ہوا تھا', 'Freedom from (all) obligations (is declared) from Allah and His Messenger (SAW) to those of the Mushrikoon (polytheists, pagans, idolaters, disbelievers in the Oneness of Allah), with whom you made a treaty.', 'Here is a disavowal (proclaimed) by Allah and His Messenger against the Mushriks (polytheists) with whom you have a treaty.'),
(1237, 9, 2, 1, 7, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'فَسِیۡحُوۡا فِی الۡاَرۡضِ اَرۡبَعَۃَ  اَشۡہُرٍ وَّ اعۡلَمُوۡۤا  اَنَّکُمۡ غَیۡرُ مُعۡجِزِی اللّٰہِ ۙ وَ اَنَّ  اللّٰہَ  مُخۡزِی  الۡکٰفِرِیۡنَ ﴿۲﴾', 'سو مشرکو تم زمین میں چار مہینے چل پھر لو اور جان رکھو کہ تم اللہ کو عاجز نہ کر سکو گے۔ اور یہ بھی کہ اللہ کافروں کو رسوا کرنے والا ہے۔', 'سو پھر لو اس ملک میں چار مہینے اور جان لو کہ تم نہ تھکا سکو گے اللہ کو اور یہ کہ اللہ رسوا کرنے والا ہے کافروں کو [۲]', 'So travel freely (O Mushrikoon - see V.2:105) for four months (as you will) throughout the land, but know that you cannot escape (from the Punishment of) Allah, and Allah will disgrace the disbelievers.', 'So, move in the land freely for four months, and be aware that you can never frustrate Allah, and that Allah is going to disgrace the disbelievers.'),
(1238, 9, 3, 1, 7, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ اَذَانٌ مِّنَ اللّٰہِ وَ رَسُوۡلِہٖۤ  اِلَی النَّاسِ یَوۡمَ الۡحَجِّ الۡاَکۡبَرِ اَنَّ اللّٰہَ  بَرِیۡٓءٌ  مِّنَ الۡمُشۡرِکِیۡنَ ۬ۙ وَ رَسُوۡلُہٗ ؕ فَاِنۡ تُبۡتُمۡ فَہُوَ خَیۡرٌ لَّکُمۡ ۚ وَ اِنۡ تَوَلَّیۡتُمۡ فَاعۡلَمُوۡۤا اَنَّکُمۡ غَیۡرُ مُعۡجِزِی اللّٰہِ ؕ وَ بَشِّرِ الَّذِیۡنَ  کَفَرُوۡا  بِعَذَابٍ  اَلِیۡمٍ ۙ﴿۳﴾', 'اور حج اکبر کے دن اللہ اور اسکے رسول کی طرف سے لوگوں کو آگاہ کیا جاتا ہے کہ اللہ مشرکوں سے بیزار ہے اور اس کا رسول بھی اب اگر تم توبہ کر لو تو تمہارے حق میں بہتر ہے اور اگر نہ مانو تو جان رکھو کہ تم اللہ کو ہرا نہیں سکو گے۔ اور اے پیغمبر کافروں کو دکھ دینے والے عذاب کی خبر سنا دو۔', 'اور سنا دینا ہے اللہ کی طرف سے اور اس کے رسول کی لوگوں کو دن بڑے حج کے [۳] کہ اللہ الگ ہے مشرکوں سے اور اس کا رسول سو اگر تم توبہ کرو تو تمہارے لئے بہتر ہے اور اگر نہ مانو تو جان لو کہ تم ہرگز نہ تھکا سکو گے اللہ کو اور خوشخبری سنادے کافروں کو عذاب دردناک کی [۴]', 'And a declaration from Allah and His Messenger to mankind on the greatest day (the 10th of Dhul-Hijjah - the 12th month of Islamic calendar) that Allah is free from (all) obligations to the Mushrikoon (see V.2:105) and so is His Messenger. So if you (Mushrikoon) repent, it is better for you, but if you turn away, then know that you cannot escape (from the Punishment of) Allah. And give tidings (O Muhammad SAW) of a painful torment to those who disbelieve.', 'And here is an announcement, from Allah and His Messenger, to the people on the day of the greater Hajj, that Allah is free from (any commitment to) the Mushriks, and so is His Messenger. Now, if you repent, it is good for you. And if you turn away, then be aware that you can never frustrate Allah. And give those who disbelieve the ‘good’ news of a painful punishment.'),
(1239, 9, 4, 1, 7, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اِلَّا الَّذِیۡنَ عٰہَدۡتُّمۡ  مِّنَ الۡمُشۡرِکِیۡنَ ثُمَّ لَمۡ یَنۡقُصُوۡکُمۡ شَیۡئًا وَّ لَمۡ یُظَاہِرُوۡا عَلَیۡکُمۡ اَحَدًا فَاَتِمُّوۡۤا اِلَیۡہِمۡ عَہۡدَہُمۡ اِلٰی مُدَّتِہِمۡ ؕ اِنَّ اللّٰہَ یُحِبُّ  الۡمُتَّقِیۡنَ ﴿۴﴾', 'البتہ جن مشرکوں کے ساتھ تم نے عہد کیا ہو اور انہوں نے تمہارا کسی طرح کا قصور نہ کیا ہو اور نہ تمہارے مقابلے میں کسی کی مدد کی ہو تو جس مدت تک انکے ساتھ عہد کیا ہو اسے پورا کرو کہ اللہ پرہیزگاروں کو دوست رکھتا ہے۔', 'مگر جن مشرکوں سے تم نے عہد کیا تھا پھر انہوں نے کچھ قصور نہ کیا تمہارے ساتھ اور مدد نہ کی تمہارے مقابلہ میں کسی کی سو ان سے پورا کر دو ان کا عہد ان کے وعدہ تک بیشک اللہ کو پسند ہیں احتیاط والے [۵]', 'Except those of the Mushrikoon with whom you have a treaty, and who have not subsequently failed you in aught, nor have supported anyone against you. So fulfill their treaty to them to the end of their term. Surely Allah loves Al- Mattaqoon (the pious - see V.2:2).', 'Except those of the Mushriks with whom you have a treaty, and they were not deficient (in fulfilling the treaty) with you, and did not back up any one against you. So fulfill the treaty with them up to their term. Surely, Allah loves the God-fearing.'),
(1240, 9, 5, 1, 7, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'فَاِذَا انۡسَلَخَ الۡاَشۡہُرُ الۡحُرُمُ  فَاقۡتُلُوا الۡمُشۡرِکِیۡنَ حَیۡثُ وَجَدۡتُّمُوۡہُمۡ وَ خُذُوۡہُمۡ وَ احۡصُرُوۡہُمۡ وَ اقۡعُدُوۡا لَہُمۡ کُلَّ مَرۡصَدٍ ۚ فَاِنۡ تَابُوۡا وَ اَقَامُوا الصَّلٰوۃَ وَ اٰتَوُا الزَّکٰوۃَ  فَخَلُّوۡا سَبِیۡلَہُمۡ ؕ اِنَّ اللّٰہَ  غَفُوۡرٌ  رَّحِیۡمٌ ﴿۵﴾', 'پس جب عزت کے مہینے گزر جائیں تو مشرکوں کو جہاں پاؤ قتل کردو۔ اور انکو پکڑ لو۔ اور گھیر لو۔ اور ہر گھات کی جگہ انکی طاق میں بیٹھے رہو۔ پھر اگر وہ توبہ کر لیں اور نماز قائم کرنے اور زکوٰۃ دینے لگیں تو ان کا رستہ چھوڑ دو۔ بیشک اللہ بخشنے والا ہے مہربان ہے۔', 'پھر جب گذر جائیں مہینے پناہ کے تو مارو مشرکوں کو جہاں پاؤ اور پکڑو اور گھیرو اور بیٹھو ہر جگہ ان کی تاک میں پھر اگر وہ توبہ کریں اور قائم رکھیں نماز اور دیا کریں زکوٰۃ تو چھوڑ دو ان کا رستہ بیشک اللہ ہے بخشنے والا مہربان [۶]', 'Then when the Sacred Months (the Ist, 7th, 11th, and 12th months of the Islamic calendar) have passed, then kill the Mushrikoon (see V.2:105) wherever you find them, and capture them and besiege them, and prepare for them each and every ambush. But if they repent and perform As-Salat (Iqamat-as-Salat), and give Zakat, then leave their way free. Verily, Allah is Oft-Forgiving, Most Merciful.', 'So, when the sacred months expire, kill the Mushriks wherever you find them, and catch them and besiege them and sit in ambush for them everywhere. Then, if they repent and establish Salāh and pay Zakāh, leave their way. Surely, Allah is most Forgiving, Very-Merciful.'),
(1241, 9, 6, 1, 7, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ اِنۡ  اَحَدٌ مِّنَ الۡمُشۡرِکِیۡنَ اسۡتَجَارَکَ فَاَجِرۡہُ حَتّٰی یَسۡمَعَ کَلٰمَ اللّٰہِ ثُمَّ اَبۡلِغۡہُ مَاۡمَنَہٗ ؕ ذٰلِکَ بِاَنَّہُمۡ قَوۡمٌ لَّا یَعۡلَمُوۡنَ ٪﴿۶﴾', 'اور اگر کوئی مشرک تم سے پناہ کا خواستگار ہو تو اسکو پناہ دیدو یہاں تک کہ وہ کلام اللہ کو سننے لگے۔ پھر اسکو امن کی جگہ واپس پہنچا دو اس لئے کہ یہ بیخبر لوگ ہیں۔', 'اور اگر کوئی مشرک تجھ سے پناہ مانگے تو اس کو پنادہ دیدے یاں تک کہ وہ سن لے کلام اللہ کا پھر پہنچا دے اسکو اسکی امن کی جگہ یہ اس واسطے کہ وہ لوگ علم نہیں رکھتے [۷]', 'And if anyone of the Mushrikoon (polytheists, idolaters, pagans, disbelievers in the Oneness of Allah) seeks your protection then grant him protection, so that he may hear the Word of Allah (the Quran), and then escort him to where he can be secure, that is because they are men who know not.', 'And if any one of the Mushriks seeks your protection, give him protection until he listens to the Word of Allah, then let him reach his place of safety. That is because they are a people who do not know.'),
(1242, 9, 7, 2, 8, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'کَیۡفَ یَکُوۡنُ لِلۡمُشۡرِکِیۡنَ عَہۡدٌ عِنۡدَ اللّٰہِ  وَ عِنۡدَ رَسُوۡلِہٖۤ  اِلَّا الَّذِیۡنَ عٰہَدۡتُّمۡ  عِنۡدَ  الۡمَسۡجِدِ  الۡحَرَامِ ۚ فَمَا اسۡتَقَامُوۡا لَکُمۡ فَاسۡتَقِیۡمُوۡا لَہُمۡ ؕ اِنَّ اللّٰہَ  یُحِبُّ  الۡمُتَّقِیۡنَ ﴿۷﴾', 'بھلا مشرکوں کے لئے جنہوں نے عہد توڑ ڈالا اللہ اور اسکے رسول کے نزدیک عہد کیسے قائم رہ سکتا ہے۔ ہاں جن لوگوں کے ساتھ تم نے مسجد حرام یعنی خانہ کعبہ کے نزدیک عہد کیا ہے اگر وہ اپنے عہد پر قائم رہیں تو تم بھی اپنے قول و قرار پر قائم رہو۔ بیشک اللہ پرہیزگاروں کو دوست رکھتا ہے۔', 'کیونکر ہووے مشرکوں کے لئے عہد اللہ کے نزدیک اور اسکے رسول کے نزدیک مگر جن لوگوں سے تم نے عہد کیا تھا مسجد حرام کے پاس سو جب تک وہ تم سے سیدھے رہیں تم ان سے سیدھے رہو بیشک اللہ کو پسند ہیں احتیاط والے', 'How can there be a covenant with Allah and with His Messenger for the Mushrikoon (polytheists, idolaters, pagans, disbelievers in the Oneness of Allah) except those with whom you made a covenant near Al-Masjid-al-Haram (at Makkah)? So long, as they are true to you, stand you true to them. Verily, Allah loves Al-Muttaqoon (the pious - see V.2:2).', 'How can the Mushriks have a treaty with Allah and His Messenger? Except those with whom you made a treaty near Al-Masjid-ul-Harām . Then, as long as they remain straight with you, you too remain straight with them. Surely, Allah loves the God-fearing.'),
(1243, 9, 8, 2, 8, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'کَیۡفَ وَ  اِنۡ  یَّظۡہَرُوۡا عَلَیۡکُمۡ  لَا یَرۡقُبُوۡا فِیۡکُمۡ  اِلًّا وَّ لَا ذِمَّۃً  ؕ یُرۡضُوۡنَکُمۡ  بِاَفۡوَاہِہِمۡ وَ تَاۡبٰی  قُلُوۡبُہُمۡ ۚ وَ اَکۡثَرُہُمۡ  فٰسِقُوۡنَ ۚ﴿۸﴾', 'بھلا ان سے عہد کیونکر پورا کیا جائے جب ان کا یہ حال ہے کہ اگر تم پر غلبہ پالیں تو نہ قرابت کا لحاظ کریں نہ عہد کا۔ یہ منہ سے تو تمہیں خوش کر دیتے ہیں لیکن انکے دل ان باتوں کو قبول نہیں کرتے اور ان میں اکثر نافرمان ہیں۔', 'کیونکر رہے صلح اور اگر وہ تم پر قابو پائیں تو نہ لحاظ کریں تمہاری قرابت کا اور نہ عہد کا تم کو راضی کر دیتے ہیں اپنے منہ کی بات سے اور انکے دل نہیں مانتے اور اکثر ان میں بد عہد ہیں [۸]', 'How (can there be such a covenant with them) that when you are overpowered by them, they regard not the ties, either of kinship or of covenant with you? With (good words from) their mouths they please you, but their hearts are averse to you, and most of them are Fasiqoon (rebellious, disobedient to Allah).', 'How (can they have a treaty) while if they overcome you, they will not observe any bond or treaty with you. They want to please you with (words of) their mouths, but their hearts refuse. Most of them are sinners.'),
(1244, 9, 9, 2, 8, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اِشۡتَرَوۡا بِاٰیٰتِ اللّٰہِ ثَمَنًا قَلِیۡلًا فَصَدُّوۡا عَنۡ سَبِیۡلِہٖ ؕ اِنَّہُمۡ سَآءَ مَا کَانُوۡا  یَعۡمَلُوۡنَ ﴿۹﴾', 'یہ اللہ کی آیتوں کے عوض تھوڑا سا فائدہ حاصل کرتے اور لوگوں کو اللہ کے رستے سے روکتے ہیں کچھ شک نہیں کہ جو کام یہ کرتے ہیں برے ہیں۔', 'بیچ ڈالے انہوں نے اللہ کے حکم تھوڑی قیمت پر پھر روکا اس کے رستہ سے برے کام ہیں جو وہ لوگ کر رہے ہیں [۹]', 'They have purchased with the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah a little gain, and they hindered men from His Way; evil indeed is that which they used to do.', 'They have taken a paltry price for the verses of Allah, so they have prevented (people) from His path. Indeed, evil is what they have been doing.'),
(1245, 9, 10, 2, 8, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'لَا یَرۡقُبُوۡنَ فِیۡ مُؤۡمِنٍ اِلًّا وَّ لَا ذِمَّۃً ؕ وَ اُولٰٓئِکَ  ہُمُ  الۡمُعۡتَدُوۡنَ ﴿۱۰﴾', 'یہ لوگ کسی مومن کے حق میں نہ تو رشتہ داری کا پاس کرتے ہیں نہ عہد کا اور یہ حد سے تجاوز کرنے والے ہیں۔', 'نہیں لحاظ کرتے کسی مسلمان کے حق میں قرابت کا اور نہ عہد کا اور وہی ہیں زیادتی پر [۱۰]', 'With regard to a believer, they respect not the ties, either of kinship or of covenant! It is they who are the transgressors.', 'They do not observe any bond or treaty with a believer; and they are the transgressors.'),
(1246, 9, 11, 2, 8, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'فَاِنۡ تَابُوۡا وَ اَقَامُوا الصَّلٰوۃَ وَ اٰتَوُا الزَّکٰوۃَ  فَاِخۡوَانُکُمۡ فِی الدِّیۡنِ ؕ وَ نُفَصِّلُ  الۡاٰیٰتِ  لِقَوۡمٍ  یَّعۡلَمُوۡنَ  ﴿۱۱﴾', 'اب اگر یہ توبہ کر لیں اور نماز پڑھنے اور زکوٰۃ دینے لگیں تو دین میں تمہارے بھائی ہیں اور سمجھنے والے لوگوں کے لئے ہم اپنی آیتیں کھول کھول کر بیان کرتے ہیں۔', 'سو اگر توبہ کریں اور قائم رکھیں نماز اور دیتے رہیں زکوٰۃ تو تمہارے بھائی ہیں حکم شریعت میں [۱۱] اور ہم کھول کر بیان کرتے ہیں حکموں کو جاننے والے لوگوں کے واسطے', 'But if they repent, perform As-Salat (Iqamat-as-Salat) and give Zakat, then they are your brethren in religion. (In this way) We explain the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) in detail for a people who know.', 'Then, if they repent and establish Salāh and pay Zakāh, they are your brothers in faith. We elaborate the verses for a people who understand.'),
(1247, 9, 12, 2, 8, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ  اِنۡ نَّکَثُوۡۤا اَیۡمَانَہُمۡ  مِّنۡۢ بَعۡدِ عَہۡدِہِمۡ وَ طَعَنُوۡا فِیۡ دِیۡنِکُمۡ  فَقَاتِلُوۡۤا اَئِمَّۃَ الۡکُفۡرِ ۙ اِنَّہُمۡ لَاۤ اَیۡمَانَ لَہُمۡ لَعَلَّہُمۡ  یَنۡتَہُوۡنَ ﴿۱۲﴾', 'اور اگر عہد کرنے کے بعد اپنی قسموں کو توڑ ڈالیں اور تمہارے دین میں طعنہ زنی کرنے لگیں تو ان کفر کے پیشواؤں سے جنگ کرو انکی قسموں کا کچھ اعتبار نہیں ہے۔ عجب نہیں کہ اپنی حرکات سے باز آجائیں۔', 'اور اگر وہ توڑ دیں اپنی قسمیں عہد کرنے کے بعد اور عیب لگائیں تمہارے دین میں تو لڑو کفر کے سرداروں سے بیشک انکی قسمیں کچھ نہیں تاکہ وہ باز آئیں [۲۱]', 'But if they violate their oaths after their covenant, and attack your religion with disapproval and criticism then fight (you) the leaders of disbelief (chiefs of Quraish - pagans of Makkah) - for surely their oaths are nothing to them - so that they may stop (evil actions).', 'And if they break their oaths after they have made a covenant, and speak evil of your Faith, then fight the leaders of infidelity,-since their oaths are nothing,-so that they may desist,'),
(1248, 9, 13, 2, 8, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اَلَا تُقَاتِلُوۡنَ قَوۡمًا نَّکَثُوۡۤا اَیۡمَانَہُمۡ وَ ہَمُّوۡا بِاِخۡرَاجِ الرَّسُوۡلِ وَ ہُمۡ بَدَءُوۡکُمۡ اَوَّلَ مَرَّۃٍ ؕ اَتَخۡشَوۡنَہُمۡ ۚ فَاللّٰہُ  اَحَقُّ اَنۡ تَخۡشَوۡہُ  اِنۡ  کُنۡتُمۡ  مُّؤۡمِنِیۡنَ ﴿۱۳﴾', 'بھلا تم ایسے لوگوں سے کیوں نہ لڑو جنہوں نے اپنی قسموں کو توڑ ڈالا اور پیغمبر کو وطن سے نکالنے کا ارادہ کر لیا اور انہوں نے تم سے عہد شکنی کی ابتداء کی۔ کیا تم ایسے لوگوں سے ڈرتے ہو سو ڈرنے کے لائق تو اللہ ہے اگر تم ایمان والے ہو۔', 'کیا نہیں لڑتے ایسے لوگوں سے جو توڑیں اپنی قسمیں اور فکر میں رہیں کہ رسول کو نکال دیں اور انہوں نے پہلے چھیڑ کی تم سے کیا تم ان سے ڈرتے ہو سو اللہ کا ڈر چاہئے تم کو زیادہ اگر تم ایمان رکھتے ہو [۱۳]', 'Will you not fight a people who have violated their oaths (pagans of Makkah) and intended to expel the Messenger, while they did attack you first? Do you fear them? Allah has more right that you should fear Him, if you are believers.', 'Would you not fight a people who broke their oaths and conspired to expel the Messenger, and it was they who started (fighting) against you for the first time? Do you fear them? But Allah has greater right that you fear Him, if you are believers.'),
(1249, 9, 14, 2, 8, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'قَاتِلُوۡہُمۡ یُعَذِّبۡہُمُ اللّٰہُ بِاَیۡدِیۡکُمۡ وَ یُخۡزِہِمۡ وَ یَنۡصُرۡکُمۡ عَلَیۡہِمۡ وَ یَشۡفِ صُدُوۡرَ  قَوۡمٍ  مُّؤۡمِنِیۡنَ ﴿ۙ۱۴﴾', 'ان سے خوب لڑو۔ اللہ انکو تمہارے ہاتھوں سے عذاب میں ڈالے گا اور انہیں رسوا کرے گا اور تم کو ان پر غلبہ دے گا اور مومن لوگوں کے سینوں کو شفا بخشے گا۔', 'لڑو ان سے تا عذاب دے اللہ انکو تمہارے ہاتھوں اور رسوا کرے اور تم کو ان پر غالب کرے اور ٹھنڈے کرے دل مسلمانوں کے', 'Fight against them so that Allah will punish them by your hands and disgrace them and give you victory over them and heal the breasts of a believing people,', 'Fight them, so that Allah should punish them at your hands and disgrace them, and help you win against them and bring relief to bosoms of the believing people,'),
(1250, 9, 15, 2, 8, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ یُذۡہِبۡ غَیۡظَ قُلُوۡبِہِمۡ ؕ وَ یَتُوۡبُ اللّٰہُ عَلٰی مَنۡ  یَّشَآءُ ؕ وَ اللّٰہُ عَلِیۡمٌ  حَکِیۡمٌ ﴿۱۵﴾', 'اور انکے دلوں سے غصہ دور کرے گا اور اللہ جس پر چاہے گا توجہ فرمائے گا۔ اور اللہ سب کچھ جانتا ہے حکمت والا ہے۔', 'اور نکالے ان کے دل کی جلن اور اللہ توبہ نصیب کرے گا جس کو چاہے گا [۱۴] اور اللہ سب کچھ جاننے والا حکمت والا ہے [۱۵]', 'And remove the anger of their (believers) hearts. Allah accepts the repentance of whom He wills. Allah is All-Knowing, All-Wise.', 'and remove the rage of their hearts. And Allah relents to whomsoever He wills. Allah is (All-) Knowing, (All-) Wise.'),
(1251, 9, 16, 2, 8, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اَمۡ حَسِبۡتُمۡ  اَنۡ تُتۡرَکُوۡا وَ لَمَّا یَعۡلَمِ اللّٰہُ الَّذِیۡنَ جٰہَدُوۡا مِنۡکُمۡ وَ لَمۡ یَتَّخِذُوۡا مِنۡ دُوۡنِ اللّٰہِ وَ لَا رَسُوۡلِہٖ وَ لَا الۡمُؤۡمِنِیۡنَ  وَلِیۡجَۃً ؕ وَ اللّٰہُ  خَبِیۡرٌۢ  بِمَا تَعۡمَلُوۡنَ ﴿٪۱۶﴾', 'کیا تم لوگ یہ خیال کرتے ہو کہ بے آزمائش چھوڑ دیئے جاؤ گے اور ابھی تو اللہ نے تم میں سے ایسے لوگوں کو پرکھا ہی نہیں جنہوں نے جہاد کیا اور اللہ اور اسکے رسول اور مومنوں کے سوا کسی کو دلی دوست نہیں بنایا۔ اور اللہ تمہارے سب کاموں سے واقف ہے۔', 'کیا تم یہ گمان کرتے ہو کہ چھوٹ جاؤ گے اور حالانکہ ابھی معلوم نہیں کیا اللہ نے تم میں سے ان لوگوں کو جنہوں نے جہاد کیا ہے اور نہیں پکڑا انہوں نے سوا اللہ کے اور اسکے رسول کے اور مسلمانوں کے کسی کو بھیدی اور اللہ کو خبر ہے جو تم کر رہے ہو [۱۶]', 'Do you think that you shall be left alone while Allah has not yet tested those among you who have striven hard and fought and have not taken Waleejah ((Batanah - helpers, advisors and consultants from disbelievers, pagans, etc.) giving openly to them their secrets) besides Allah and His Messenger, and the believers. Allah is Well-Acquainted with what you do.', 'Do you think that you will be left alone (without being tested), while Allah has not yet seen those of you who struggle in Jihād and never take anyone as their confidant other than Allah and His Messenger and the believers? Allah is fully aware of what you do.'),
(1252, 9, 17, 3, 9, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'مَا کَانَ لِلۡمُشۡرِکِیۡنَ اَنۡ یَّعۡمُرُوۡا مَسٰجِدَ اللّٰہِ شٰہِدِیۡنَ عَلٰۤی اَنۡفُسِہِمۡ بِالۡکُفۡرِ ؕ اُولٰٓئِکَ حَبِطَتۡ اَعۡمَالُہُمۡ ۚۖ وَ فِی النَّارِ ہُمۡ  خٰلِدُوۡنَ ﴿۱۷﴾', 'مشرکوں کا کام نہیں کہ اللہ کی مسجدوں کو آباد کریں جب کہ وہ اپنے آپ پر کفر کی گواہی دے رہے ہوں۔ ان لوگوں کے سب اعمال بےکار ہیں۔ اور وہ ہمیشہ دوزخ میں رہیں گے۔', 'مشرکوں کا کام نہیں کہ آباد کریں اللہ کی مسجدیں اور تسلیم کر رہے ہوں اپنے اوپر کفر کو وہ لوگ خراب گئے ان کےعمل اور آگ میں رہیں گے وہ ہمیشہ', 'It is not for the Mushrikoon (polytheists, idolaters, pagans, disbelievers in the Oneness of Allah), to maintain the Mosques of Allah (i.e. to pray and worship Allah therein, to look after their cleanliness and their building, etc.), while they witness against their ownselves of disbelief. The works of such are in vain and in Fire shall they abide.', 'It is not for the Mushriks to build up the mosques of Allah while they are witnesses of their own infidelity. Those are the ones whose deeds have gone to waste; and in the Fire they shall remain forever.'),
(1253, 9, 18, 3, 9, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اِنَّمَا یَعۡمُرُ مَسٰجِدَ اللّٰہِ مَنۡ اٰمَنَ بِاللّٰہِ وَ الۡیَوۡمِ الۡاٰخِرِ وَ اَقَامَ الصَّلٰوۃَ  وَ اٰتَی الزَّکٰوۃَ وَ لَمۡ یَخۡشَ اِلَّا اللّٰہَ فَعَسٰۤی اُولٰٓئِکَ اَنۡ یَّکُوۡنُوۡا مِنَ الۡمُہۡتَدِیۡنَ ﴿۱۸﴾', 'اللہ کی مسجدوں کو تو وہ لوگ آباد کرتے ہیں جو اللہ پر اور روز قیامت پر ایمان لاتے اور نماز پڑھتے اور زکوٰۃ دیتے ہیں اور اللہ کے سوا کسی سے نہیں ڈرتے یہی لوگ امید ہے کہ ہدایت یافتہ لوگوں میں سے ہوں۔', 'وہی آباد کرتا ہے مسجدیں اللہ کی جو یقین لایا اللہ پر اور آخرت کے دن پر اور قائم کیا نماز کو اور دیتا رہا زکوٰۃ اور نہ ڈرا سوائے اللہ کے کسی سے سو امیدوار ہیں وہ لوگ کہ ہوویں ہدایت والوں میں [۱۷]', 'The Mosques of Allah shall be maintained only by those who believe in Allah and the Last Day; perform As-Salat (Iqamat-as-Salat), and give Zakat and fear none but Allah. It is they who are expected to be on true guidance.', 'In fact, the mosques of Allah are built-up only by those who believe in Allah and the Last Day and those who establish Salāh and pay Zakāh and who fear none but Allah. So, it is hoped that they are to be among those on the right path.'),
(1254, 9, 19, 3, 9, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اَجَعَلۡتُمۡ سِقَایَۃَ الۡحَآجِّ وَ عِمَارَۃَ الۡمَسۡجِدِ الۡحَرَامِ کَمَنۡ اٰمَنَ بِاللّٰہِ وَ الۡیَوۡمِ الۡاٰخِرِ  وَ جٰہَدَ  فِیۡ سَبِیۡلِ اللّٰہِ ؕ لَا  یَسۡتَوٗنَ عِنۡدَ اللّٰہِ ؕ وَ اللّٰہُ  لَا  یَہۡدِی الۡقَوۡمَ  الظّٰلِمِیۡنَ ﴿ۘ۱۹﴾', 'کیا تم نے حاجیوں کو پانی پلانا اور مسجد حرام یعنی خانہ کعبہ کو آباد کرنا اس شخص کے اعمال جیسا خیال کیا ہے۔ جو اللہ اور روز آخر پر ایمان رکھتا ہے اور اللہ کی راہ میں جہاد کرتا ہے؟ یہ لوگ اللہ کے نزدیک برابر نہیں ہیں۔ اور اللہ ظالم لوگوں کو ہدایت نہیں دیا کرتا۔', 'کیا تم نے کر دیا حاجیوں کا پانی پلانا اور مسجد الحرام کا بسانا برابر اس کے جو یقین لایا اللہ پر اور آخرت کےدن پر اور لڑا اللہ کی راہ میں یہ برابر نہیں ہیں اللہ کے نزدیک اور اللہ رستہ نہیں دیتا ظالم لوگوں کو [۱۸]', 'Do you consider the providing of drinking water to the pilgrims and the maintenance of Al-Masjid-al-Haram (at Makkah) as equal to the worth of those who believe in Allah and the Last Day, and strive hard and fight in the Cause of Allah? They are not equal before Allah. And Allah guides not those people who are the Zalimoon (polytheists and wrong-doers).', 'Have you taken the serving of water to the pilgrims and the maintenance of Al-Masjid-ul-Harām as equal to (the acts) of one who believes in Allah and in the Last Day, and carries out Jihād in the way of Allah? They are not equal in the sight of Allah. Allah does not lead the wrongdoing people to the right path.'),
(1255, 9, 20, 3, 9, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اَلَّذِیۡنَ  اٰمَنُوۡا وَ ہَاجَرُوۡا وَ جٰہَدُوۡا  فِیۡ سَبِیۡلِ اللّٰہِ بِاَمۡوَالِہِمۡ وَ اَنۡفُسِہِمۡ ۙ اَعۡظَمُ  دَرَجَۃً  عِنۡدَ  اللّٰہِ ؕ وَ اُولٰٓئِکَ ہُمُ  الۡفَآئِزُوۡنَ ﴿۲۰﴾', 'جو لوگ ایمان لائے اور وطن چھوڑ گئے اور اللہ کی راہ میں مال اور جان سے جہاد کرتے رہے اللہ کے ہاں انکے درجات بہت بڑے ہیں۔ اور وہی مراد کو پہنچنے والے ہیں۔', 'جو ایمان لائے اور گھر چھوڑ آئے اور لڑے اللہ کی راہ میں اپنے مال اور جان سے ان کے لئے بڑا درجہ ہے اللہ کے ہاں اور وہی مراد کو پہنچنے والے ہیں', 'Those who believed (in the Oneness of Allah - Islamic Monotheism) and emigrated and strove hard and fought in Allahs Cause with their wealth and their lives are far higher in degree with Allah. They are the successful.', 'Those who believed and emigrated and carried out Jihād in the way of Allah with their wealth and lives are greater in rank in the sight of Allah, and it is they who are the successful.'),
(1256, 9, 21, 3, 9, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'یُبَشِّرُہُمۡ رَبُّہُمۡ بِرَحۡمَۃٍ مِّنۡہُ وَ رِضۡوَانٍ وَّ جَنّٰتٍ  لَّہُمۡ  فِیۡہَا نَعِیۡمٌ مُّقِیۡمٌ ﴿ۙ۲۱﴾', 'ان کا پروردگار ان کو اپنی رحمت کی اور خوشنودی کی اور بہشتوں کی خوشخبری دیتا ہے جن میں انکے لئے ابدی نعمت ہے۔', 'خوشخبری دیتا ہے انکو پروردگار انکا اپنی طرف سے مہربانی کی اور ضامندی کی اور باغوں کی کہ جن میں انکو آرام ہے ہمیشہ کا', 'Their Lord gives them glad tidings of a Mercy from Him, and that He is pleased (with them), and of Gardens (Paradise) for them wherein are everlasting delights.', 'Their Lord gives them the happy news of Mercy from Him, and of (His) Pleasure, and of Gardens having an everlasting bliss for them,'),
(1257, 9, 22, 3, 9, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'خٰلِدِیۡنَ فِیۡہَاۤ  اَبَدًا ؕ اِنَّ اللّٰہَ عِنۡدَہٗۤ  اَجۡرٌ  عَظِیۡمٌ ﴿۲۲﴾', 'اور وہ ان میں ہمیشہ ہمیشہ رہیں گے۔ کچھ شک نہیں کہ اللہ کے ہاں بڑا صلہ تیار ہے۔', 'رہا کریں ان میں مدام بیشک اللہ پاس بڑا ثواب ہے [۱۹]', 'They will dwell therein forever. Verily, with Allah is a great reward.', 'where they shall dwell forever. Surely, it is Allah with whom lies a great reward.'),
(1258, 9, 23, 3, 9, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَتَّخِذُوۡۤا اٰبَآءَکُمۡ وَ اِخۡوَانَکُمۡ اَوۡلِیَآءَ اِنِ اسۡتَحَبُّوا الۡکُفۡرَ عَلَی الۡاِیۡمَانِ ؕ وَ مَنۡ یَّتَوَلَّہُمۡ مِّنۡکُمۡ فَاُولٰٓئِکَ ہُمُ الظّٰلِمُوۡنَ ﴿۲۳﴾', 'اے اہل ایمان! اگر تمہارے ماں باپ اور بہن بھائی ایمان کے مقابل کفر کو پسند کریں تو ان سے دوستی نہ رکھو۔ اور جو ان سے دوستی رکھیں گے وہ ظالم ہیں۔', 'اےایمان والو مت پکڑو اپنے باپوں کو اور بھائیوں کو رفیق اگر وہ عزیز رکھیں کفر کو ایمان سے اور جو تم میں انکی رفاقت کرے سو وہی لوگ ہیں گنہگار [۲۰]', 'O you who believe! Take not for Auliya (supporters and helpers) your fathers and your brothers if they prefer disbelief to Belief. And whoever of you does so, then he is one of the Zalimoon (wrong-doers, etc.).', 'O you who believe, do not take your fathers and your brothers as your friends, if they prefer infidelity to Faith. Those of you who have friendship with them are the wrongdoers.'),
(1259, 9, 24, 3, 9, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'قُلۡ اِنۡ کَانَ اٰبَآؤُکُمۡ وَ اَبۡنَآؤُکُمۡ وَ اِخۡوَانُکُمۡ وَ اَزۡوَاجُکُمۡ  وَ عَشِیۡرَتُکُمۡ وَ اَمۡوَالُۨ  اقۡتَرَفۡتُمُوۡہَا وَ تِجَارَۃٌ تَخۡشَوۡنَ  کَسَادَہَا وَ مَسٰکِنُ  تَرۡضَوۡنَہَاۤ  اَحَبَّ  اِلَیۡکُمۡ مِّنَ اللّٰہِ وَ رَسُوۡلِہٖ  وَ جِہَادٍ فِیۡ سَبِیۡلِہٖ فَتَرَبَّصُوۡا حَتّٰی یَاۡتِیَ اللّٰہُ بِاَمۡرِہٖ ؕ وَ اللّٰہُ  لَا یَہۡدِی الۡقَوۡمَ  الۡفٰسِقِیۡنَ ﴿٪۲۴﴾', 'کہدو کہ اگر تمہارے باپ اور بیٹے اور بھائی اور بیویاں اور خاندان والے اور مال جو تم کماتے ہو اور تجارت جس میں مندی سے ڈرتے ہو اور مکانات جنکو پسند کرتے ہو اللہ اور اسکے رسول سے اور اللہ کی راہ میں جہاد کرنے سے تمہیں زیادہ عزیز ہوں تو ٹھیرے رہو یہاں تک کہ اللہ اپنا حکم یعنی عذاب بھیجے۔ اور اللہ نافرمان لوگوں کو ہدایت نہیں دیا کرتا۔', 'تو کہہ دے اگر تمہارے باپ اور بیٹے اور بھائی اور عورتیں اور برادری اور مال جو تم نے کمائے ہیں اور سوداگری جسکے بند ہونے سے تم ڈرتے ہو اور حویلیاں جنکو پسند کرتے ہو تم کو زیادہ پیاری ہیں اللہ سے اور اسکے رسول سے اور لڑنے سے اسکی راہ میں تو انتظار کرو یہاں تک کہ بھیجے اللہ اپنا حکم اور اللہ رستہ نہیں دیتا نافرمان لوگوں کو [۲۱]', 'Say: If your fathers, your sons, your brothers, your wives, your kindred, the wealth that you have gained, the commerce in which you fear a decline, and the dwellings in which you delight … are dearer to you than Allah and His Messenger, and striving hard and fighting in His Cause, then wait until Allah brings about His Decision (torment). And Allah guides not the people who are Al-Fasiqoon (the rebellious, disobedient to Allah).', 'Say, “If your fathers and your sons and your brothers and your spouses and your clan and the wealth you have earned and the trade you apprehend will recede and the homes you like are dearer to you than Allah and His Messenger and Jihād in His way, then, wait until Allah comes with His command. Allah does not lead the sinning people to the right path.”'),
(1260, 9, 25, 4, 10, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'لَقَدۡ نَصَرَکُمُ اللّٰہُ فِیۡ مَوَاطِنَ کَثِیۡرَۃٍ ۙ وَّ یَوۡمَ حُنَیۡنٍ ۙ اِذۡ  اَعۡجَبَتۡکُمۡ  کَثۡرَتُکُمۡ فَلَمۡ تُغۡنِ عَنۡکُمۡ شَیۡئًا وَّ ضَاقَتۡ عَلَیۡکُمُ الۡاَرۡضُ بِمَا رَحُبَتۡ ثُمَّ وَلَّیۡتُمۡ  مُّدۡبِرِیۡنَ ﴿ۚ۲۵﴾', 'اللہ نے بہت سے موقعوں  پر تم کو مدد دی ہے اور جنگ حنین کے دن جب کہ تم کو اپنی جماعت کی کثرت پر غرہ تھا تو وہ تمہارے کچھ بھی کام نہ آئی اور زمین باوجود اپنی فراخی کے تم پر تنگ ہو گئ۔ پھر تم پیٹھ پھیر گئے۔', 'مدد کر چکا ہے اللہ تمہاری بہت میدانوں میں اور حنین کے دن جب خوش ہوئے تم اپنی کثرت پر پھر وہ کچھ کام نہ آئی تمہارے اور تنگ ہو گئی تم پر زمین باوجود اپنی فراخی کے پھر ہٹ گئے تم پیٹھ دے کر', 'Truly Allah has given you victory on many battle fields, and on the Day of Hunain (battle) when you rejoiced at your great number but it availed you naught and the earth, vast as it is, was straitened for you, then you turned back in flight.', 'Allah has surely blessed you with His help on many battlefields, and on the day of Hunain, when you were proud of your great number, then it did not help you at all, and the earth was straitened for you despite all its vastness, then you turned back on your heels.'),
(1261, 9, 26, 4, 10, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'ثُمَّ اَنۡزَلَ اللّٰہُ سَکِیۡنَتَہٗ عَلٰی رَسُوۡلِہٖ وَ عَلَی الۡمُؤۡمِنِیۡنَ وَ اَنۡزَلَ جُنُوۡدًا لَّمۡ تَرَوۡہَا وَ عَذَّبَ الَّذِیۡنَ  کَفَرُوۡا ؕ وَ ذٰلِکَ جَزَآءُ  الۡکٰفِرِیۡنَ ﴿۲۶﴾', 'پھر اللہ نے اپنے پیغمبر پر اور مومنوں پر اپنی طرف سے تسکین نازل فرمائی اور تمہاری مدد کو فرشتوں کے لشکر جو تمہیں نظر نہیں آتے تھے آسمان سے اتارے اور کافروں کو عذاب دیا اور کفر کرنے والوں کی یہی سزا ہے۔', 'پھر اتاری اللہ نے اپنی طرف سے تسکین اپنے رسول پر اور ایمان والوں پر اور اتاریں فوجیں کہ جنکو تم نے نہیں دیکھا اور عذاب دیا کافروں کو اور یہ سزا ہے منکروں کی [۲۲]', 'Then Allah did send down His Sakeenah (calmness, tranquillity and reassurance, etc.) on the Messenger (Muhammad SAW), and on the believers, and sent down forces (angels) which you saw not, and punished the disbelievers. Such is the recompense of disbelievers.', 'Then Allah sent down His tranquility upon His Messenger and upon the believers, and sent down troops that you did not see, and punished those who disbelieved. That is the recompense of the disbelievers.'),
(1262, 9, 27, 4, 10, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'ثُمَّ  یَتُوۡبُ اللّٰہُ مِنۡۢ  بَعۡدِ ذٰلِکَ عَلٰی مَنۡ یَّشَآءُ ؕ وَ اللّٰہُ  غَفُوۡرٌ  رَّحِیۡمٌ ﴿۲۷﴾', 'پھر اللہ اس کے بعد جس پر چاہے مہربانی سے توجہ فرمائے اور اللہ بخشنے والا ہے مہربان ہے۔', 'پھر توبہ نصیب کرے گا اللہ اس کے بعد جس کو چاہے اور اللہ بخشنے والا مہربان ہے [۲۳]', 'Then after that Allah will accept the repentance of whom He will. And Allah is Oft-Forgiving, Most Merciful.', 'Yet Allah relents, after that, to whomsoever He wills. Allah is Most-Forgiving, Very-Merciful.'),
(1263, 9, 28, 4, 10, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اِنَّمَا الۡمُشۡرِکُوۡنَ نَجَسٌ فَلَا یَقۡرَبُوا الۡمَسۡجِدَ الۡحَرَامَ بَعۡدَ عَامِہِمۡ ہٰذَا ۚ وَ اِنۡ خِفۡتُمۡ عَیۡلَۃً فَسَوۡفَ یُغۡنِیۡکُمُ اللّٰہُ مِنۡ فَضۡلِہٖۤ  اِنۡ شَآءَ ؕ اِنَّ  اللّٰہَ  عَلِیۡمٌ  حَکِیۡمٌ ﴿۲۸﴾', 'مومنو! مشرک تو پلید ہیں تو اس برس کے بعد وہ مسجد حرام خانہ کعبہ کے پاس نہ جانے پائیں اور اگر تم کو مفلسی کا خوف ہو تو اللہ چاہے گا تو تم کو اپنے فضل سے غنی کر دے گا۔ بیشک اللہ سب کچھ جانتا ہے حکمت والا ہے۔', 'اے ایمان والو مشرک جو ہیں سو پلید ہیں سو نزدیک نہ آنے پائیں مسجدالحرام کے اس برس کے بعد [۲۴] اور اگر تم ڈرتے ہو فقر سے تو آئندہ غنی کر دے گا تم کو اللہ اپنے فضل سے اگر چاہے بیشک اللہ سب کچھ جاننے والا حکمت والا ہے [۲۵]', 'O you who believe (in Allahs Oneness and in His Messenger (Muhammad SAW)! Verily, the Mushrikoon (polytheists, pagans, idolaters, disbelievers in the Oneness of Allah, and in the Message of Muhammad SAW) are Najasun (impure). So let them not come near Al-Masjid-al-Haram (at Makkah) after this year, and if you fear poverty, Allah will enrich you if He will, out of His Bounty. Surely, Allah is All-Knowing, All-Wise.', 'O you who believe, the Mushriks are impure indeed, so let them not approach Al-Masjid-ul-Harām after this year. And if you apprehend poverty, then, Allah shall, if He wills, make you self-sufficient with His grace. Surely, Allah is All-Knowing, All-Wise.'),
(1264, 9, 29, 4, 10, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'قَاتِلُوا الَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِاللّٰہِ وَ لَا بِالۡیَوۡمِ  الۡاٰخِرِ وَ لَا یُحَرِّمُوۡنَ مَا حَرَّمَ  اللّٰہُ  وَ رَسُوۡلُہٗ  وَ لَا  یَدِیۡنُوۡنَ دِیۡنَ  الۡحَقِّ مِنَ الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ  حَتّٰی یُعۡطُوا  الۡجِزۡیَۃَ  عَنۡ ‌یَّدٍ  وَّ ہُمۡ  صٰغِرُوۡنَ ﴿٪۲۹﴾', 'جو لوگ اہل کتاب میں سے اللہ پر ایمان نہیں لاتے اور نہ روز آخر پر یقین رکھتے ہیں اور نہ ان چیزوں کو حرام سمجھتے ہیں جو اللہ اور اسکے رسول نے حرام کی ہیں اور نہ دین حق کو قبول کرتے ہیں ان سے جنگ کرو یہاں تک کہ ذلیل ہو کر اپنے ہاتھ سے جزیہ دینے لگیں۔', 'لڑو ان لوگوں سے جو ایمان نہیں لاتے اللہ پر اور نہ آخرت کے دن پر اور نہ حرام جانتے ہیں اسکو جس کو حرام کیا اللہ نے اور اسکے رسول نے اور نہ قبول کرتے ہیں دین سچا ان لوگوں میں سے جو کہ اہل کتاب ہیں یہاں تک کہ وہ جزیہ دیں اپنے ہاتھ سے ذلیل ہو کر [۲۶]', 'Fight against those who (1) believe not in Allah, (2) nor in the Last Day, (3) nor forbid that which has been forbidden by Allah and His Messenger (4) and those who acknowledge not the religion of truth (i.e. Islam) among the people of the Scripture (Jews and Christians), until they pay the Jizyah with willing submission, and feel themselves subdued.', 'Fight those People of the Book who do not believe in Allah, nor in the Last Day, and do not take as unlawful what Allah and His Messenger have declared as unlawful, and do not profess the Faith of Truth; (fight them) until they pay jizyah with their own hands while they are subdued.'),
(1265, 9, 30, 5, 11, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ قَالَتِ الۡیَہُوۡدُ عُزَیۡرُۨ  ابۡنُ اللّٰہِ وَ قَالَتِ النَّصٰرَی الۡمَسِیۡحُ  ابۡنُ  اللّٰہِ ؕ ذٰلِکَ قَوۡلُہُمۡ بِاَفۡوَاہِہِمۡ ۚ یُضَاہِـُٔوۡنَ  قَوۡلَ الَّذِیۡنَ کَفَرُوۡا مِنۡ قَبۡلُ ؕ قٰتَلَہُمُ اللّٰہُ ۚ۫ اَنّٰی  یُؤۡفَکُوۡنَ ﴿۳۰﴾', 'اور یہود کہتے ہیں کہ عزیر اللہ کے بیٹے ہیں۔ اور عیسائی کہتے ہیں کہ مسیح اللہ کے بیٹے ہیں۔ یہ انکے منہ کی باتیں ہیں۔ پہلے کافر بھی اسی طرح کی باتیں کہا کرتے تھے یہ بھی انہی کی ریس کرنے لگے ہیں اللہ ان کو ہلاک کرے۔ یہ کہاں بہکے پھرتے ہیں۔', 'اور یہود نے کہا کہ عزیر اللہ کا بیٹا ہے [۲۷] اور نصاریٰ نے کہا کہ مسیح اللہ کا بیٹا ہے یہ باتیں کہتے ہیں اپنے منہ سے ریس کرنے لگے اگلے کافروں کی بات کی [۲۸] ہلاک کرے ان کو اللہ کہاں سے پھرے جاتے ہیں [۲۹]', 'And the Jews say: Uzair (Ezra) is the son of Allah, and the Christians say: Messiah is the son of Allah. That is a saying from their mouths. They imitate the saying of the disbelievers of old. Allahs Curse be on them, how they are deluded away from the truth!', 'The Jews say, “ ‘Uzair (Ezra) is the Son of Allah” and the Christians say, “MasīH (the Christ) is the Son of Allah.” That is their oral statement. They imitate the saying of the earlier disbelievers. May Allah ruin them, how far they are turned back from the truth!'),
(1266, 9, 31, 5, 11, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اِتَّخَذُوۡۤا اَحۡبَارَہُمۡ وَ رُہۡبَانَہُمۡ اَرۡبَابًا مِّنۡ دُوۡنِ اللّٰہِ وَ الۡمَسِیۡحَ ابۡنَ مَرۡیَمَ ۚ وَ مَاۤ  اُمِرُوۡۤا  اِلَّا  لِیَعۡبُدُوۡۤا  اِلٰـہًا  وَّاحِدًا ۚ لَاۤ اِلٰہَ  اِلَّا ہُوَ ؕ سُبۡحٰنَہٗ عَمَّا یُشۡرِکُوۡنَ ﴿۳۱﴾', 'انہوں نے اپنے علماء اور مشائخ اور مسیح ابن مریم کو اللہ کے سوا معبود بنا لیا حالانکہ انکو یہ حکم دیا گیا تھا کہ معبود واحد کے سوا کسی کی عبادت نہ کریں اسکے سوا کوئی معبود نہیں اور وہ ان لوگوں کے شریک مقرر کرنے سے پاک ہے۔', 'ٹھہرا لیا اپنے عالموں اور درویشوں کو خدا اللہ کو چھوڑ کر [۳۰] اور مسیح مریم کے بیٹے کو بھی اور انکو حکم یہی ہوا تھا کہ بندگی کریں ایک معبود کی کسی کی بندگی نہیں اسکے سوا وہ پاک ہے ان کے شریک بتلانے سے', 'They (Jews and Christians) took their rabbis and their monks to be their lords besides Allah (by obeying them in things which they made lawful or unlawful according to their own desires without being ordered by Allah), and (they also took as their Lord) Messiah, son of Maryam (Mary), while they (Jews and Christians) were commanded (in the Taurat (Torah) and the Injeel (Gospel)) to worship none but One Ilah (God - Allah) La ilaha illa Huwa (none has the right to be worshipped but He). Praise and glory be to Him, (far above is He) from having the partners they associate (with Him).\"', 'They have taken their rabbis and their monks as gods beside Allah, and also (they have taken) MasīH the son of Maryam (as god). And they were not commanded but to worship only One God. There is no god but He. Pure is He from what they associate with Him.'),
(1267, 9, 32, 5, 11, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'یُرِیۡدُوۡنَ  اَنۡ یُّطۡفِـُٔوۡا نُوۡرَ اللّٰہِ بِاَفۡوَاہِہِمۡ وَ یَاۡبَی اللّٰہُ  اِلَّاۤ  اَنۡ  یُّتِمَّ  نُوۡرَہٗ وَ لَوۡ  کَرِہَ  الۡکٰفِرُوۡنَ ﴿۳۲﴾', 'یہ چاہتے ہیں کہ اللہ کے نور کو اپنے منہ سے پھونک مار کر بجھا دیں۔ اور اللہ اپنے نور کو پورا کئے بغیر رہنے کا نہیں۔ اگرچہ کافروں کو برا ہی لگے۔', 'چاہتے ہیں کہ بھجا دیں روشنی اللہ کی اپنے منہ سے اور اللہ نہ رہے گا بدون پورا کئے اپنی روشنی کے اور پڑے برا مانیں کافر [۳۱]', 'They (the disbelievers, the Jews and the Christians) want to extinguish Allahs Light (with which Muhammad SAW has been sent - Islamic Monotheism) with their mouths, but Allah will not allow except that His Light should be perfected even though the Kafiroon (disbelievers) hate (it).', 'They wish to blow out the Light of Allah with their mouths, and Allah rejects everything short of making His light perfect, no matter how the disbelievers may hate it.'),
(1268, 9, 33, 5, 11, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'ہُوَ الَّذِیۡۤ  اَرۡسَلَ رَسُوۡلَہٗ  بِالۡہُدٰی وَ دِیۡنِ الۡحَقِّ لِیُظۡہِرَہٗ عَلَی الدِّیۡنِ کُلِّہٖ ۙ وَ لَوۡ کَرِہَ  الۡمُشۡرِکُوۡنَ ﴿۳۳﴾', 'وہی تو ہے جس نے اپنے پیغمبر کو ہدایت اور دین حق دے کر بھیجا تاکہ اس دین کو دنیا کے تمام دینوں پر غالب کرے اگرچہ کافر ناخوش ہی ہوں۔', 'اسی نے بھیجا اپنے رسول کو ہدایت اور سچا دین دے کر تاکہ اس کو غلبہ دے ہر دین پر اور پڑے برا مانیں مشرک [۳۲]', 'It is He Who has sent His Messenger (Muhammad SAW) with guidance and the religion of truth (Islam), to make it superior over all religions even though the Mushrikoon (polytheists, pagans, idolaters, disbelievers in the Oneness of Allah) hate (it).', 'He is the One who has sent down His Messenger with guidance and the Faith of Truth, so that He makes it prevail over every faith, no matter how the Mushriks may hate it.'),
(1269, 9, 34, 5, 11, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اِنَّ کَثِیۡرًا مِّنَ الۡاَحۡبَارِ وَ الرُّہۡبَانِ  لَیَاۡکُلُوۡنَ اَمۡوَالَ النَّاسِ بِالۡبَاطِلِ وَ یَصُدُّوۡنَ عَنۡ سَبِیۡلِ اللّٰہِ ؕ وَ الَّذِیۡنَ یَکۡنِزُوۡنَ الذَّہَبَ وَ الۡفِضَّۃَ وَ لَا یُنۡفِقُوۡنَہَا فِیۡ سَبِیۡلِ اللّٰہِ ۙ فَبَشِّرۡہُمۡ  بِعَذَابٍ اَلِیۡمٍ ﴿ۙ۳۴﴾', 'مومنو! اہل کتاب کے بہت سے عالم اور مشائخ لوگوں کا مال ناحق کھاتے اور ان کو اللہ کی راہ سے روکتے ہیں اور جو لوگ سونا اور چاندی جمع کرتے ہیں اور اسکو اللہ کے رستے میں خرچ نہیں کرتے انکو اس دن کے عذاب الیم کی خبر سنا دو۔', 'اے ایمان والو بہت سے عالم اور درویش اہل کتاب کے کھاتے ہیں مال لوگوں کے ناحق اور روکتے ہیں اللہ کی راہ سے [۳۳] اور جو لوگ گاڑھ کر رکھتے ہیں سونا اور چاندی اور اسکو خرچ نہیں کرتے اللہ کی راہ میں سو انکو خوشخبری سنا دے عذاب دردناک کی [۳۴]', 'O you who believe! Verily, there are many of the (Jewish) rabbis and the (Christian) monks who devour the wealth of mankind in falsehood, and hinder (them) from the Way of Allah (i.e. Allahs Religion of Islamic Monotheism). And those who hoard up gold and silver (Al-Kanz: the money, the Zakat of which has not been paid), and spend it not in the Way of Allah, -announce unto them a painful torment.', 'O you who believe, many of the rabbis and the monks do eat up the wealth of the people by false means and prevent (them) from the way of Allah. As for those who accumulate gold and silver and do not spend it in the way of Allah, give them the ‘good’ news of a painful punishment,'),
(1270, 9, 35, 5, 11, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'یَّوۡمَ یُحۡمٰی عَلَیۡہَا فِیۡ نَارِ جَہَنَّمَ فَتُکۡوٰی بِہَا جِبَاہُہُمۡ وَ جُنُوۡبُہُمۡ وَ ظُہُوۡرُہُمۡ ؕ ہٰذَا مَا  کَنَزۡتُمۡ  لِاَنۡفُسِکُمۡ فَذُوۡقُوۡا  مَا کُنۡتُمۡ  تَکۡنِزُوۡنَ ﴿۳۵﴾', 'جس دن وہ مال دوزخ کی آگ میں خوب گرم کیا جائے گا۔ پھر اس سے ان بخیلوں کی پیشانیاں اور پہلو اور پیٹھیں داغی جائیں گی اور کہا جائے گا کہ یہ وہی ہے جو تم نے اپنے لئے جمع کیا تھا سو جو تم جمع کرتے تھے اب اس کا مزہ چکھو۔', 'جس دن کہ آگ دہکائیں گے اس مال پر دوزخ کی پھر داغیں گے اس سے ان کے ماتھے اور کروٹیں اور پیٹھیں (کہا جائے گا) یہ ہے جو تم نے گاڑھ کر رکھا تھا اپنے واسطے اب چکھو مزا اپنے گاڑھنے کا [۳۵]', 'On the Day when that (Al-Kanz: money, gold and silver, etc., the Zakat of which has not been paid) will be heated in the Fire of Hell and with it will be branded their foreheads, their flanks, and their backs, (and it will be said unto them):-\"This is the treasure which you hoarded for yourselves. Now taste of what you used to hoard.\"', 'on the day it (the wealth) will be heated up in the fire of Jahannam, then their foreheads and their sides and their backs shall be branded with it: “This is what you had accumulated for yourselves. So, taste what you have been accumulating.”'),
(1271, 9, 36, 5, 11, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اِنَّ عِدَّۃَ الشُّہُوۡرِ عِنۡدَ اللّٰہِ اثۡنَا عَشَرَ شَہۡرًا فِیۡ  کِتٰبِ اللّٰہِ یَوۡمَ خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ مِنۡہَاۤ  اَرۡبَعَۃٌ  حُرُمٌ ؕ ذٰلِکَ الدِّیۡنُ الۡقَیِّمُ ۬ۙ  فَلَا تَظۡلِمُوۡا فِیۡہِنَّ اَنۡفُسَکُمۡ وَ قَاتِلُوا الۡمُشۡرِکِیۡنَ کَآفَّۃً کَمَا یُقَاتِلُوۡنَکُمۡ کَآفَّۃً ؕ وَ اعۡلَمُوۡۤا اَنَّ  اللّٰہَ  مَعَ الۡمُتَّقِیۡنَ ﴿۳۶﴾', 'اللہ کے نزدیک مہینے گنتی میں بارہ ہیں اس روز سے کہ اس نے آسمانوں اور زمین کو پیدا کیا۔ اللہ کی کتاب میں سال کے بارہ مہینے لکھے ہوئے ہیں ان میں سے چار مہینے ادب کے ہیں یہی دین کا سیدھا رستہ ہے تو ان مہینوں میں قتال ناحق سے اپنے آپ پر ظلم نہ کرنا۔ اور تم سب کے سب مشرکوں سے لڑو جیسے وہ سب کے سب تم سے لڑتے ہیں۔ اور جان رکھو کہ اللہ پرہیزگاروں کے ساتھ ہے۔', 'مہینوں کی گنتی اللہ کے نزدیک بارہ مہینے ہیں اللہ کےحکم میں جس دن اس نے پیدا کئے تھے آسمان اور زمین ان میں چار مہینے ہیں ادب کے یہی ہے سیدھا دین [۳۶] سو ان میں ظلم مت کرو اپنے اوپر اور لڑو سب مشرکوں سے ہر حال میں جیسے وہ لڑتے ہیں تم سب سے ہر حال میں اور جان لو کہ اللہ ساتھ ہے ڈرنے والوں کے [۳۷]', 'Verily, the number of months with Allah is twelve months (in a year), so was it ordained by Allah on the Day when He created the heavens and the earth; of them four are Sacred, (i.e. the 1st, the 7th, the 11th and the 12th months of the Islamic calendar). That is the right religion, so wrong not yourselves therein, and fight against the Mushrikoon (polytheists, pagans, idolaters, disbelievers in the Oneness of Allah) collectively, as they fight against you collectively. But know that Allah is with those who are Al-Muttaqoon (the pious - see V.2:2).', 'Surely, the number of months according to Allah is twelve (as written) in the Book of Allah on the day He created the heavens and the Earth, of which there are Four Sacred Months. That is the right faith. So, do not wrong yourself therein. And fight the Mushriks all together, as they fight you all together, and be sure that Allah is with the God-fearing.'),
(1272, 9, 37, 5, 11, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اِنَّمَا النَّسِیۡٓءُ زِیَادَۃٌ فِی الۡکُفۡرِ  یُضَلُّ بِہِ الَّذِیۡنَ کَفَرُوۡا یُحِلُّوۡنَہٗ عَامًا وَّ یُحَرِّمُوۡنَہٗ عَامًا لِّیُوَاطِـُٔوۡا عِدَّۃَ مَا حَرَّمَ اللّٰہُ فَیُحِلُّوۡا مَا حَرَّمَ اللّٰہُ ؕ زُیِّنَ لَہُمۡ سُوۡٓءُ  اَعۡمَالِہِمۡ ؕ وَ اللّٰہُ  لَا یَہۡدِی الۡقَوۡمَ  الۡکٰفِرِیۡنَ ﴿٪۳۷﴾', 'ادب کے کسی مہینے کو ہٹا کر آگے پیچھے کر دینا کفر میں بڑھ جانا ہے اس سے کافر گمراہی میں پڑے رہتے ہیں۔ ایک سال تو اسکو حلال سمجھ لیتے ہیں اور دوسرے سال حرام تاکہ ادب کے مہینوں کی جو اللہ نے مقرر کئے ہیں گنتی پوری کر لیں۔ اور جو اللہ نے منع کیا ہے اسکو جائز کر لیں۔ انکے برے اعمال انکو بھلے دکھائی دیتے ہیں اور اللہ کافر لوگوں کو ہدایت نہیں دیا کرتا۔', 'یہ جو مہینہ ہٹا دینا ہے سو بڑھائی ہوئی بات ہے کفر کےعہد میں گمراہی میں پڑتے ہیں اس سے کافر حلال کر لیتے ہیں اُس مہینہ کو ایک برس اور حرام رکھتے ہیں دوسرے برس تاکہ پوری کر لیں گنتی ان مہینوں کی جو اللہ نے ادب کے لئے رکھے ہیں پھر حلال کر لیتے ہیں جو مہینہ کہ اللہ نے حرام کیا بھلے کر دیئے گئے انکی نظر میں ان کے برے کام اور اللہ راستہ نہیں دیتا کافر لوگوں کو [۳۸]', 'The postponing (of a Sacred Month) is indeed an addition to disbelief: thereby the disbelievers are led astray, for they make it lawful one year and forbid it another year in order to adjust the number of months forbidden by Allah, and make such forbidden ones lawful. The evil of their deeds seems pleasing to them. And Allah guides not the people, who disbelieve.', 'Nasī’ (i.e. postponement of months) is nothing but a further excess in infidelity, whereby the disbelievers are misguided. They allow it one year and disallow it another year, so that they may conform (only) to the number of what Allah has sanctified, and allow what Allah has disallowed. The evil of their deeds has been beautified for them (by Satan). And Allah does not lead the disbelieving people to the right path.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1273, 9, 38, 6, 12, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا مَا لَکُمۡ  اِذَا قِیۡلَ لَکُمُ انۡفِرُوۡا فِیۡ سَبِیۡلِ اللّٰہِ اثَّاقَلۡتُمۡ  اِلَی الۡاَرۡضِ ؕ اَرَضِیۡتُمۡ بِالۡحَیٰوۃِ الدُّنۡیَا مِنَ الۡاٰخِرَۃِ ۚ فَمَا مَتَاعُ الۡحَیٰوۃِ الدُّنۡیَا فِی الۡاٰخِرَۃِ  اِلَّا قَلِیۡلٌ ﴿۳۸﴾', 'مومنو! تمہیں کیا ہوا ہے کہ جب تم سے کہا جاتا ہے کہ اللہ کی راہ میں جہاد کے لئے نکلو تو تم زمین سے چپکے جاتے ہو یعنی گھروں سے نکلنا نہیں چاہتے کیا تم آخرت کی نعمتوں کو چھوڑ کر دنیا کی زندگی پر خوش ہو بیٹھے ہو۔ سو دنیا کی زندگی کے فائدے تو آخرت کے مقابل بہت ہی کم ہیں۔', 'اے ایمان والو تم کو کیا ہوا جب تم سے کہا جاتا ہے کہ کوچ کرو اللہ کی راہ میں تو گرے جاتے ہو زمین پر کیا خوش ہو گئے دنیا کی زندگی پر آخرت کو چھوڑ کر سو کچھ نہیں نفع اٹھانا دنیا کی زندگی کا آخرت کے مقابلہ میں مگر بہت تھوڑا [۳۹]', 'O you who believe! What is the matter with you, that when you are asked to march forth in the Cause of Allah (i.e. Jihad) you cling heavily to the earth? Are you pleased with the life of this world rather than the Hereafter? But little is the enjoyment of the life of this world as compared with the Hereafter.', 'O you who believe, what is wrong with you that when it is said to you, “Come out in the way of Allah,” you turn heavy (and cling) to the ground. Have you become happy with the worldly life instead of the Hereafter? So, (remember that) the enjoyment of the worldly life is but trivial in (comparison with) the Hereafter.'),
(1274, 9, 39, 6, 12, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اِلَّا تَنۡفِرُوۡا یُعَذِّبۡکُمۡ عَذَابًا اَلِیۡمًا ۬ۙ  وَّ یَسۡتَبۡدِلۡ قَوۡمًا غَیۡرَکُمۡ وَ لَا تَضُرُّوۡہُ شَیۡئًا ؕ وَ اللّٰہُ  عَلٰی  کُلِّ  شَیۡءٍ  قَدِیۡرٌ ﴿۳۹﴾', 'اگر تم نہ نکلو گے تو اللہ تم کو بڑی تکلیف کا عذاب دے گا۔ اور تمہاری جگہ اور لوگ پیدا کر دے گا اور تم اسکو کچھ نقصان نہ پہنچا سکو گے اور اللہ ہر چیز پر قدرت رکھتا ہے۔', 'اگر تم نہ نکلو گے تو دے گا تم کو عذاب دردناک اور بدلے میں لائے گا اور لوگ تمہارے سوا اور کچھ نہ بگاڑ سکو گے تم اس کا اور اللہ سب چیز پر قادر ہے [۴۰]', 'If you march not forth, He will punish you with a painful torment and will replace you by another people, and you cannot harm Him at all, and Allah is Able to do all things.', 'If you do not march forth (in the way of Allah), He will chastise you with a painful punishment and will replace you with another nation, and you can do Him no harm at all. Allah is powerful to do anything.'),
(1275, 9, 40, 6, 12, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اِلَّا تَنۡصُرُوۡہُ فَقَدۡ  نَصَرَہُ  اللّٰہُ  اِذۡ اَخۡرَجَہُ الَّذِیۡنَ  کَفَرُوۡا ثَانِیَ اثۡنَیۡنِ اِذۡ ہُمَا فِی الۡغَارِ اِذۡ یَقُوۡلُ لِصَاحِبِہٖ لَا تَحۡزَنۡ اِنَّ اللّٰہَ مَعَنَا ۚ فَاَنۡزَلَ اللّٰہُ سَکِیۡنَتَہٗ عَلَیۡہِ وَ اَیَّدَہٗ  بِجُنُوۡدٍ لَّمۡ تَرَوۡہَا وَ جَعَلَ کَلِمَۃَ  الَّذِیۡنَ کَفَرُوا السُّفۡلٰی ؕ وَ کَلِمَۃُ  اللّٰہِ ہِیَ الۡعُلۡیَا ؕ وَ اللّٰہُ  عَزِیۡزٌ  حَکِیۡمٌ  ﴿۴۰﴾', 'اگر تم پیغمبر کی مدد نہ کرو گے تو اللہ ان کا مددگار ہے وہ وقت تم کو یاد ہو گا جب ان کو کافروں نے گھر سے نکال دیا اس وقت دو ہی شخص تھے جن میں ایک ابوبکر تھے اور دوسرے ہمارے پیغمبر ﷺ جب وہ دونوں غار ثور میں تھے اس وقت پیغمبر اپنے رفیق کو تسلی دیتے تھے کہ غم نہ کرو اللہ ہمارے ساتھ ہے۔ تو اللہ نے ان پر تسکین نازل فرمائی اور انکو ایسے لشکروں سے مدد دی جو تمکو نظر نہیں آتے تھے اور کافروں کی بات کو پست کر دیا اور بات تو اللہ ہی کی بلند ہے۔ اور اللہ زبردست ہے حکمت والا ہے۔', 'اگر تم نہ مدد کرو گے رسول کی تو اس کی مدد کی ہے اللہ نے جس وقت اس کو نکالا تھا کافروں نے کہ وہ دوسرا تھا دو میں کا جب وہ دونوں تھے غار میں جب وہ کہہ رہا تھا اپنے رفیق سے تو غم نہ کھا بیشک اللہ ہمارے ساتھ ہے پھر اللہ نے اتاری اپنی طرف سے اس پر تسکین اور اسکی مدد کو وہ فوجیں بھیجیں کہ تم نے نہیں دیکھیں اور نیچے ڈالی کافروں کی اور اللہ کی بات ہمیشہ اوپر ہے اور اللہ زبردست ہے حکمت والا [۴۱]', 'If you help him (Muhammad SAW) not (it does not matter), for Allah did indeed help him when the disbelievers drove him out, the second of two, when they (Muhammad SAW and Abu Bakr ÑÖì ) were in the cave, and he (SAW) said to his companion (Abu Bakr ÑÖì ): \"Be not sad (or afraid), surely Allah is with us.\" Then Allah sent down His Sakeenah (calmness, tranquillity, peace, etc.) upon him, and strengthened him with forces (angels) which you saw not, and made the word of those who disbelieved the lowermost, while it was the Word of Allah that became the uppermost, and Allah is All-Mighty, All-Wise.', 'If you do not help him, (it makes no difference to the Prophet, because) Allah has already helped him when the disbelievers expelled him, and he was the second of the two, when they were in the cave, and he was saying to his companion, “Do not grieve. Allah is surely with us.”So, Allah caused His tranquility to descend on him,and supported him with troops that you did not see, and rendered the word of the disbelievers humiliated. And the word of Allah is the uppermost. Allah is Mighty, Wise.'),
(1276, 9, 41, 6, 12, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اِنۡفِرُوۡا خِفَافًا وَّ ثِقَالًا وَّ جَاہِدُوۡا بِاَمۡوَالِکُمۡ وَ اَنۡفُسِکُمۡ فِیۡ سَبِیۡلِ اللّٰہِ ؕ ذٰلِکُمۡ خَیۡرٌ لَّکُمۡ اِنۡ  کُنۡتُمۡ تَعۡلَمُوۡنَ ﴿۴۱﴾', 'تم ہتھیار تھوڑے رکھتے ہو یا بہت گھروں سے نکل آؤ اور اللہ کے رستے میں مال اور جان سے جہاد کرو۔ یہی تمہارے حق میں بہتر ہے۔ بشرطیکہ سمجھو۔', 'نکلو ہلکے اور بوجھل [۴۲] اور لڑو اپنے مال سے اور جان سے اللہ کی راہ میں یہ بہتر ہے تمہارے حق میں اگر تم کو سمجھ ہے [۴۳]', 'March forth, whether you are light (being healthy, young and wealthy) or heavy (being ill, old and poor), strive hard with your wealth and your lives in the Cause of Allah. This is better for you, if you but knew.', 'March forth (in the way of Allah), no matter whether you are light or heavy, and carry out Jihād (struggle) in the way of Allah with your wealth and lives. That is good for you, if you were to realize.'),
(1277, 9, 42, 6, 12, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'لَوۡ کَانَ عَرَضًا قَرِیۡبًا وَّ سَفَرًا قَاصِدًا لَّاتَّبَعُوۡکَ وَ لٰکِنۡۢ بَعُدَتۡ عَلَیۡہِمُ الشُّقَّۃُ ؕ وَ سَیَحۡلِفُوۡنَ بِاللّٰہِ لَوِ اسۡتَطَعۡنَا لَخَرَجۡنَا مَعَکُمۡ ۚ یُہۡلِکُوۡنَ اَنۡفُسَہُمۡ ۚ وَ اللّٰہُ یَعۡلَمُ   اِنَّہُمۡ لَکٰذِبُوۡنَ ﴿٪۴۲﴾', 'اگر مال غنیمت آسانی سے حاصل ہونے والا اور سفر بھی ہلکا ہوتا تو یہ تمہارے ساتھ شوق سے چل دیتے لیکن مسافت انکو دور دراز نظر آئی تو عذر کریں گے اور اللہ کی قسمیں کھائیں گے کہ اگر ہم طاقت رکھتے تو آپ کے ساتھ ضرور نکل پڑتے یہ اسطرح اپنے آپکو ہلاک کر رہے ہیں اور اللہ جانتا ہے کہ یہ جھوٹے ہیں۔', 'اگر مال ہو تا نزدیک اور سفر ہلکا تو وہ لوگ ضرور تیرے ساتھ ہو لیتے لیکن لمبی نظر آئی ان کو مسافت [۴۴] اور اب قسمیں کھائیں گے اللہ کی کہ اگر ہم سے ہو سکتا تو ہم ضرور چلتے تمہارے ساتھ وبال میں ڈالتے ہیں اپنی جانوں کو اور اللہ جانتا ہےکہ وہ جھوٹے ہیں [۴۵]', 'Had it been a near gain (booty in front of them) and an easy journey, they would have followed you, but the distance (Tabuk expedition) was long for them, and they would swear by Allah, \"If we only could, we would certainly have come forth with you.\" They destroy their ownselves, and Allah knows that they are liars.', 'Had it been a gain at hand or an average journey, they would have certainly followed you, but the distance seemed too far to them. They will swear by Allah: “We would have certainly set out with you, if we were able to.” They are putting themselves to ruin.16 Allah knows that they are liars.'),
(1278, 9, 43, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'عَفَا اللّٰہُ عَنۡکَ ۚ لِمَ اَذِنۡتَ لَہُمۡ حَتّٰی یَتَبَیَّنَ لَکَ الَّذِیۡنَ صَدَقُوۡا وَ تَعۡلَمَ الۡکٰذِبِیۡنَ ﴿۴۳﴾', 'اللہ تمہیں معاف کرے تم نے پیشتر اسکے کہ تم پر وہ لوگ بھی ظاہر ہو جاتے جو سچے ہیں اور وہ بھی تمہیں معلوم ہو جاتے جو جھوٹے ہیں انکو اجازت کیوں دی؟', 'اللہ بخشے تجھ کو کیوں رخصت دے دی تو نے انکو  یہاں تک کہ ظاہر ہو جاتے تجھ پر سچ کہنے والے اور جان لیتا تو جھوٹوں کو [۴۶]', 'May Allah forgive you (O Muhammad SAW). Why did you grant them leave (for remaining behind, you should have persisted as regards your order to them to proceed on Jihad), until those who told the truth were seen by you in a clear light, and you had known the liars?', '(O Prophet,) Allah has forgiven you; why did you permit them (to stay in Madīnah) before the truthful ones could become distinct to you, and you could be sure of the liars.'),
(1279, 9, 44, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'لَا یَسۡتَاۡذِنُکَ الَّذِیۡنَ یُؤۡمِنُوۡنَ بِاللّٰہِ وَ الۡیَوۡمِ الۡاٰخِرِ  اَنۡ  یُّجَاہِدُوۡا  بِاَمۡوَالِہِمۡ وَ  اَنۡفُسِہِمۡ ؕ وَ اللّٰہُ  عَلِیۡمٌۢ بِالۡمُتَّقِیۡنَ ﴿۴۴﴾', 'جو لوگ اللہ پر اور روز آخر پر ایمان رکھتے ہیں وہ تو تم سے اجازت نہیں مانگتے کہ پیچھے رہ جائیں بلکہ چاہتے ہیں کہ اپنے مال اور جان سے جہاد کریں اور اللہ پرہیزگاروں سے واقف ہے۔', 'نہیں رخصت مانگتے تجھ سے وہ لوگ جو ایمان لائے اللہ پر اور آخرت کے دن پر اس سے کہ لڑیں اپنے مال اور جان سے اور اللہ خوب جانتا ہے ڈر  والوں کو', 'Those who believe in Allah and the Last Day would not ask your leave to be exempted from fighting with their properties and their lives, and Allah is the All-Knower of Al-Muttaqoon (the pious - see V.2:2).', 'Those who believe in Allah and in the Last Day do not ask you to excuse them from Jihād with their wealth and lives. Allah is aware of the God-fearing.'),
(1280, 9, 45, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اِنَّمَا یَسۡتَاۡذِنُکَ الَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِاللّٰہِ وَ الۡیَوۡمِ الۡاٰخِرِ وَ ارۡتَابَتۡ قُلُوۡبُہُمۡ  فَہُمۡ  فِیۡ  رَیۡبِہِمۡ  یَتَرَدَّدُوۡنَ ﴿۴۵﴾', 'اجازت وہی لوگ مانگتے ہیں جو اللہ پر اور روز آخر پر ایمان نہیں رکھتے اور انکے دل شک میں پڑے ہوئے ہیں۔ سو وہ اپنے شک میں ڈانواں ڈول ہو رہے ہیں۔', 'رخصت وہی مانگتے ہیں تجھ سے جو نہیں ایمان لائے اللہ پر اور آخرت کے دن پر اور شک میں پڑے ہیں دل ان کے سو وہ اپنے شک ہی میں بھٹک رہے ہیں [۴۷]', 'It is only those who believe not in Allah and the Last Day and whose hearts are in doubt that ask your leave (to be exempted from Jihad). So in their doubts they waver.', 'Only those people ask you to be excused who do not believe in Allah and in the Last Day and whose hearts are in doubt; so they are wavering in their doubt.'),
(1281, 9, 46, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ لَوۡ  اَرَادُوا الۡخُرُوۡجَ لَاَعَدُّوۡا  لَہٗ  عُدَّۃً وَّ لٰکِنۡ  کَرِہَ  اللّٰہُ  انۡۢبِعَاثَہُمۡ  فَثَبَّطَہُمۡ وَ قِیۡلَ  اقۡعُدُوۡا مَعَ  الۡقٰعِدِیۡنَ ﴿۴۶﴾', 'اور اگر وہ نکلنے کا ارادہ کرتے تو اسکے لئے سامان تیار کرتے لیکن اللہ نے ان کا اٹھنا اور نکلنا پسند ہی نہ کیا تو انکو ہلنے جلنے ہی نہ دیا اور ان سے کہہ دیا گیا کہ جہاں معذور بیٹھے ہیں تم بھی انکے ساتھ بیٹھے رہو۔', 'اور اگر وہ چاہتے نکلنا تو ضرور تیار کرتے کچھ سامان اس کا لیکن پسند نہ کیا اللہ نے ان کا اٹھنا سو روک دیا انکو اور حکم ہوا کہ بیٹھے رہو ساتھ بیٹھنے والوں کے [۴۸]', 'And if they had intended to march out, certainly, they would have made some preparation for it, but Allah was averse to their being sent forth, so He made them lag behind, and it was said (to them), \"Sit you among those who sit (at home).\"', 'Had they wished to set out, they would have made some preparation for it, but Allah disliked their going forth, so He made them lag behind, and it was said to them, “Stay back with those who are staying back.”'),
(1282, 9, 47, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'لَوۡ خَرَجُوۡا فِیۡکُمۡ مَّا زَادُوۡکُمۡ  اِلَّا خَبَالًا وَّ لَا۠اَوۡضَعُوۡا خِلٰلَکُمۡ یَبۡغُوۡنَکُمُ الۡفِتۡنَۃَ ۚ وَ فِیۡکُمۡ سَمّٰعُوۡنَ لَہُمۡ ؕ وَ اللّٰہُ  عَلِیۡمٌۢ   بِالظّٰلِمِیۡنَ ﴿۴۷﴾', 'اگر وہ تم میں شامل ہو کر نکل بھی کھڑے ہوتے تو تمہارے درمیان شرارت کرتے اور تم میں فساد ڈلوانے کی غرض سے دوڑے دوڑے پھرتے۔ اور تم میں انکے جاسوس بھی ہیں اور اللہ ظالموں کو خوب جانتا ہے۔', 'اگر نکلتےتم میں تو کچھ نہ بڑھاتے تمہارے لئے مگر خرابی اور گھوڑے دوڑاتے تمہارے اندر بگاڑ کروانے کی تلاش میں [۴۹] اور تم میں بعضے جاسوس ہیں انکے اور اللہ خوب جانتا ہے ظالموں کو [۵۰]', 'Had they marched out with you, they would have added to you nothing except disorder, and they would have hurried about in your midst (spreading corruption) and sowing sedition among you, and there are some among you who would have listened to them. And Allah is the All-Knower of the Zalimoon (polytheists and wrong-doers, etc.).', 'And had they set out with you, they would have added nothing for you but trouble, and would have run around in your midst seeking mischief against you. Still, among you there are those who spy for them. Allah is aware of the wrongdoers.'),
(1283, 9, 48, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'لَقَدِ ابۡتَغَوُا الۡفِتۡنَۃَ  مِنۡ  قَبۡلُ وَ قَلَّبُوۡا لَکَ الۡاُمُوۡرَ حَتّٰی جَآءَ الۡحَقُّ وَ ظَہَرَ  اَمۡرُ  اللّٰہِ  وَ ہُمۡ   کٰرِہُوۡنَ ﴿۴۸﴾', 'یہ پہلے بھی طالب فساد رہے ہیں اور بہت سی باتوں میں تمہارے لئے الٹ پھیر کرتے رہے ہیں یہاں تک کہ حق آ پہنچا اور اللہ کا حکم غالب ہوا اور وہ برا مانتے ہی رہ گئے۔', 'وہ تلاش کرتے رہے ہیں بگاڑ کی پہلے سے اور الٹتے رہے ہیں تیرے کام یہاں تک کہ آ پہنچا سچا وعدہ اور غالب  رہا حکم اللہ کا اور وہ ناخوش ہی رہے [۵۱]', 'Verily, they had plotted sedition before, and had upset matters for you, - until the truth (victory) came and the Decree of Allah (His Religion, Islam) became manifest though they hated it.', 'They sought mischief even earlier and tried to upset matters for you, until the Truth arrived and the will of Allah prevailed, though they disliked it.'),
(1284, 9, 49, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ مِنۡہُمۡ مَّنۡ یَّقُوۡلُ ائۡذَنۡ لِّیۡ وَ لَا تَفۡتِنِّیۡ ؕ اَلَا فِی الۡفِتۡنَۃِ سَقَطُوۡا ؕ وَ  اِنَّ جَہَنَّمَ  لَمُحِیۡطَۃٌۢ  بِالۡکٰفِرِیۡنَ ﴿۴۹﴾', 'اور ان میں کوئی ایسا بھی ہے جو کہتا ہے کہ مجھے تو اجازت ہی دیجئے۔ اور آفت میں نہ ڈالئے۔ دیکھو یہ آفت میں پڑ گئے ہیں اور دوزخ سب کافروں کو گھیرے ہوئے ہے۔', 'اور بعضے ان میں کہتے ہیں مجھ کو رخصت دے اور گمراہی میں نہ ڈال سنتا ہے وہ تو گمراہی میں پڑ چکے ہیں اور بیشک دوزخ گھیر رہی ہے کافروں کو [۵۲]', 'And among them is he who says:\"Grant me leave (to be exempted from Jihad) and put me not into trial.\" Surely, they have fallen into trial. And verily, Hell is surrounding the disbelievers.', 'And among them there is one who says, “Allow me (to stay behind) and do not expose me to an ordeal.”Look! They have already fallen into an ordeal, and certainly Jahannam (the Hell) has the disbelievers encircled.'),
(1285, 9, 50, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اِنۡ تُصِبۡکَ حَسَنَۃٌ تَسُؤۡہُمۡ ۚ وَ اِنۡ تُصِبۡکَ مُصِیۡبَۃٌ یَّقُوۡلُوۡا قَدۡ اَخَذۡنَاۤ اَمۡرَنَا مِنۡ قَبۡلُ وَ یَتَوَلَّوۡا  وَّ ہُمۡ  فَرِحُوۡنَ ﴿۵۰﴾', 'اے پیغمبر اگر تم کو آسائش حاصل ہوتی ہے تو انکو بری لگتی ہے اور اگر تم پر کوئی مشکل آ پڑتی ہے تو کہتے ہیں کہ ہم نے اپنا کام پہلے ہی درست کر لیا تھا۔ اور خوشیاں مناتے لوٹ جاتے ہیں۔', 'اگر تجھ کو پہنچے کوئی خوبی تو وہ بری لگتی ہے انکو اور اگر پہنچے کوئی سختی تو کہتےہیں ہم نے تو سنبھال لیا تھا اپنا کام پہلے ہی اور پھر کر جائیں خوشیاں کرتے [۵۳]', 'If good befalls you (O Muhammad SAW), it grieves them, but if a calamity overtakes you, they say: \"We took our precaution beforehand,\" and they turn away rejoicing.', 'If some good comes to you, it annoys them, and if hardship befalls you, they say, “We had already taken care of our problem”, and they go their way delighted.'),
(1286, 9, 51, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'قُلۡ لَّنۡ یُّصِیۡبَنَاۤ اِلَّا مَا کَتَبَ اللّٰہُ  لَنَا ۚ ہُوَ مَوۡلٰىنَا ۚ وَ عَلَی اللّٰہِ  فَلۡیَتَوَکَّلِ  الۡمُؤۡمِنُوۡنَ ﴿۵۱﴾', 'کہدو کہ ہم کو کوئی مصیبت نہیں پہنچ سکتی بجز اسکے جو اللہ نے ہمارے لئے لکھ دی ہو وہی ہمارا کارساز ہے اور مومنوں کو تو اللہ ہی پر بھروسہ رکھنا چاہیے۔', 'تو کہہ دے ہم کو ہر گز نہ پہنچے گا مگر وہی جو لکھ دیا اللہ نے ہمارے لئے وہی ہے کارساز ہمارا اور اللہ ہی پر چاہئے کہ بھروسہ کریں مسلمان', 'Say: \"Nothing shall ever happen to us except what Allah has ordained for us. He is our Maula (Lord, Helper and Protector).\" And in Allah let the believers put their trust.', 'Say, “Nothing can ever reach us except what Allah has destined for us. He is our Master. And in Allah alone the believers must place their trust.”'),
(1287, 9, 52, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'قُلۡ ہَلۡ تَرَبَّصُوۡنَ بِنَاۤ اِلَّاۤ اِحۡدَی الۡحُسۡنَیَیۡنِ ؕ وَ نَحۡنُ نَتَرَبَّصُ بِکُمۡ  اَنۡ یُّصِیۡبَکُمُ اللّٰہُ بِعَذَابٍ مِّنۡ عِنۡدِہٖۤ  اَوۡ بِاَیۡدِیۡنَا ۫ۖ فَتَرَبَّصُوۡۤا اِنَّا مَعَکُمۡ مُّتَرَبِّصُوۡنَ ﴿۵۲﴾', 'کہدو کہ تم ہمارے حق میں دو بھلائیوں میں سے ایک کے منتظر ہو اور ہم تمہارے حق میں اس بات کے منتظر ہیں کہ اللہ یا تو اپنے پاس سے تم پر کوئی عذاب نازل کرے یا ہمارے ہاتھوں سے تمہیں عذاب دلوائے سو تم بھی انتظار کرو۔ ہم بھی تمہارے ساتھ انتظار کرتے ہیں۔', 'تو کہہ دے تم کیا امید کرو گے ہمارے حق میں مگر دو خوبیوں میں سے ایک کی اور ہم امیدوار ہیں تمہارے حق میں کہ ڈالے تم پر اللہ کوئی عذاب اپنے پاس سے یا ہمارے ہاتھوں سو منتظر رہو ہم بھی تمہارے ساتھ منتظر ہیں [۵۴]', 'Say: \"Do you wait for us (anything) except one of the two best things (martyrdom or victory); while we await for you either that Allah will afflict you with a punishment from Himself or at our hands. So wait, we too are waiting with you.\"', 'Say, “What you are expecting for us is nothing but one of the two good things (martyrdom or victory). And we are expecting for you that Allah sends to you a punishment from Himself or at our hands. So, wait. Of course, we are waiting with you.”'),
(1288, 9, 53, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'قُلۡ اَنۡفِقُوۡا طَوۡعًا اَوۡ کَرۡہًا لَّنۡ یُّتَقَبَّلَ مِنۡکُمۡ ؕ اِنَّکُمۡ کُنۡتُمۡ قَوۡمًا فٰسِقِیۡنَ ﴿۵۳﴾', 'کہدو کہ تم مال خوشی سے خرچ کرو یا ناخوشی سے تم سے ہرگز قبول نہیں کیا جائے گا۔ تم نافرمان لوگ ہو۔', 'کہہ دے کہ مال خرچ کرو خوشی سے یا ناخوشی سے ہر گز قبول نہ ہوگا تم سے بیشک تم نافرمان لوگ ہو [۵۵]', 'Say: \"Spend (in Allahs Cause) willingly or unwillingly, it will not be accepted from you. Verily, you are ever a people who are Fasiqoon (rebellious, disobedient to Allah).\"', 'Say, “Spend, willingly or unwillingly, it will never be accepted from you. You have been a sinning people.”'),
(1289, 9, 54, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ مَا مَنَعَہُمۡ  اَنۡ تُقۡبَلَ مِنۡہُمۡ نَفَقٰتُہُمۡ   اِلَّاۤ   اَنَّہُمۡ کَفَرُوۡا بِاللّٰہِ وَ بِرَسُوۡلِہٖ وَ لَا یَاۡتُوۡنَ الصَّلٰوۃَ  اِلَّا وَ ہُمۡ کُسَالٰی وَ لَا یُنۡفِقُوۡنَ  اِلَّا وَ ہُمۡ کٰرِہُوۡنَ ﴿۵۴﴾', 'اور انکے خرچ کئے ہوئے مالوں کے قبول ہونے سے کوئی چیز مانع نہیں ہوتی سوائے اسکے کہ انہوں نے اللہ سے اور اسکے رسول سے کفر کیا اور نماز کو آتے ہیں تو سست و کاہل ہو کر اور خرچ کرتے ہیں تو ناخوشی سے۔', 'اور موقوف نہیں ہوا قبول ہونا ان کے خرچ کا مگر اسی بات پر کہ وہ منکر ہوئے اللہ سے اور اسکے رسول سے اور نہیں آتے نماز کو مگر ہارے جی سے اور خرچ نہیں کرتے مگر برے دل سے [۵۶]', 'And nothing prevents their contributions from being accepted from them except that they disbelieved in Allah and in His Messenger (Muhammad SAW); and that they came not to As-Salat (the prayer) except in a lazy state; and that they offer not contributions but unwillingly.', 'Nothing has prevented their spending from being accepted from them but that they have disbelieved in Allah and in His Messenger, and they do not come to the Salāh but lazily, and do not spend but without volition.'),
(1290, 9, 55, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'فَلَا تُعۡجِبۡکَ اَمۡوَالُہُمۡ وَ لَاۤ  اَوۡلَادُہُمۡ ؕ اِنَّمَا یُرِیۡدُ اللّٰہُ  لِیُعَذِّبَہُمۡ بِہَا فِی الۡحَیٰوۃِ الدُّنۡیَا وَ تَزۡہَقَ اَنۡفُسُہُمۡ وَ ہُمۡ کٰفِرُوۡنَ ﴿۵۵﴾', 'پس تم انکے مال اور اولاد سے تعجب نہ کرنا۔ اللہ چاہتا کہ ان چیزوں سے دنیا کی زندگی میں انکو عذاب دے اور جب انکی جان نکلے تو اس وقت بھی یہ کافر ہی ہوں۔', 'سو تو تعجب نہ کر ان کے مال اور اولاد سے یہی چاہتا ہے اللہ کہ انکو عذاب میں رکھے ان چیزوں کی وجہ دنیا کی زندگی میں اور نکلے ان کی جان اور وہ اس وقت تک کافر ہی رہیں [۵۷]', 'So let not their wealth or their children amaze you (O Muhammad SAW); in reality Allahs Plan is to punish them with these things in the life of the this world, and that their souls shall depart (die) while they are disbelievers.', 'So, their wealth and their children should not attract you. In fact, Allah intends to punish them with these in this lowly life and that their souls should depart while they are disbelievers.'),
(1291, 9, 56, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ یَحۡلِفُوۡنَ بِاللّٰہِ  اِنَّہُمۡ  لَمِنۡکُمۡ ؕ وَ مَا ہُمۡ مِّنۡکُمۡ  وَ  لٰکِنَّہُمۡ  قَوۡمٌ  یَّفۡرَقُوۡنَ ﴿۵۶﴾', 'اور اللہ کی قسمیں کھاتے ہیں کہ وہ  تمہی میں سے ہیں حالانکہ وہ تم میں سے نہیں ہیں۔ اصل یہ ہے کہ وہ ڈرپوک لوگ ہیں۔', 'اور قسمیں کھاتے ہیں اللہ کی کہ وہ بیشک تم میں ہیں اور وہ تم میں نہیں و لیکن وہ لوگ ڈرتے ہیں تم سے', 'They swear by Allah that they are truly of you while they are not of you, but they are a people (hypocrites) who are afraid (that you may kill them).', 'They swear by Allah that they are from among you, whereas they are not from among you, but they are a people in fear.'),
(1292, 9, 57, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'لَوۡ  یَجِدُوۡنَ مَلۡجَاً  اَوۡ مَغٰرٰتٍ اَوۡ  مُدَّخَلًا لَّوَلَّوۡا  اِلَیۡہِ  وَ ہُمۡ  یَجۡمَحُوۡنَ ﴿۵۷﴾', 'اگر انکو کوئی بچاؤ کی جگہ جیسے قلعہ یا غار یا زمین کے اندر گھسنے کی جگہ مل جائے تو اسی طرح رسیاں تڑاتے ہوئے بھاگ جائیں۔', 'اگر وہ پائیں کوئی پناہ کی جگہ یا غار یا سر گھسانے کو جگہ تو الٹے بھاگیں اسی طرف رسیاں تڑاتے [۵۸]', 'Should they find a refuge, or caves, or a place of concealment, they would turn straightway thereto with a swift rush.', 'If they find a place of refuge or caves or any place to enter, they will turn towards it running (as) unbridled (horses).'),
(1293, 9, 58, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ مِنۡہُمۡ مَّنۡ یَّلۡمِزُکَ فِی الصَّدَقٰتِ ۚ فَاِنۡ اُعۡطُوۡا مِنۡہَا رَضُوۡا وَ اِنۡ لَّمۡ یُعۡطَوۡا مِنۡہَاۤ   اِذَا  ہُمۡ  یَسۡخَطُوۡنَ ﴿۵۸﴾', 'اور ان میں بعض ایسے بھی ہیں کہ تقسیم صدقات میں تم پر طعنہ زنی کرتے ہیں۔ اب اگر انکو اس میں سے خاطر خواہ مل جائے تو خوش رہیں اور اگر اس قدر نہ ملے تو جھٹ خفا ہو جائیں۔', 'اور بعضے ان میں وہ ہیں کہ تجھ کو طعن دیتےہیں خیرات بانٹنے میں سو اگر ان کو ملے اس میں سے تو راضی ہوں اور اگر نہ ملے تو جبہی وہ ناخوش ہو جائیں [۵۹]', 'And of them are some who accuse you (O Muhammad SAW) in the matter of (the distribution of) the alms. If they are given part thereof, they are pleased, but if they are not given thereof, behold! They are enraged!', 'And among them there are those who find fault with you in (the distribution of) Sadaqāt (alms). So, if they are given something out of it, they are quite happy, and if they are given nothing from it, they at once get annoyed.'),
(1294, 9, 59, 7, 13, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ لَوۡ اَنَّہُمۡ رَضُوۡا مَاۤ  اٰتٰىہُمُ اللّٰہُ وَ رَسُوۡلُہٗ ۙ وَ قَالُوۡا حَسۡبُنَا اللّٰہُ سَیُؤۡتِیۡنَا اللّٰہُ مِنۡ فَضۡلِہٖ وَ رَسُوۡلُہٗۤ  ۙ اِنَّاۤ  اِلَی  اللّٰہِ  رٰغِبُوۡنَ ﴿٪۵۹﴾', 'اور اگر وہ اس پر خوش رہتے جو اللہ اور اسکے رسول نے ان کو دیا تھا اور کہتے کہ ہمیں اللہ کافی ہے اور اللہ اپنے فضل سے اور اسکے پیغمبر اپنی مہربانی سے ہمیں پھر دے دیں گے اور ہمیں تو اللہ ہی کی رضا مطلوب ہے تو انکے حق میں بہتر ہوتا۔', 'اور کیا اچھا ہوتا اگر وہ راضی ہو جاتے اسی پر جو دیا انکو اللہ نے اور اسکے رسول نے اور کہتے کافی ہے ہم کو اللہ وہ دے گا ہم کو اپنے فضل سے اور اس کا رسول ہم کو تو اللہ ہی چاہیئے [۶۰]', 'Would that they were contented with what Allah and His Messenger (SAW) gave them and had said: \"Allah is Sufficient for us. Allah will give us of His Bounty, and (also) His Messenger (from alms, etc.). We implore Allah (to enrich us).\"', 'Would that they were content with what Allah and His Messenger had given to them, and were to say, “Allah is sufficient for us; Allah and His Messenger will give us (more) out of His grace (when they so will). Indeed, we crave for (the pleasure of) Allah alone.”'),
(1295, 9, 60, 8, 14, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اِنَّمَا الصَّدَقٰتُ لِلۡفُقَرَآءِ وَ الۡمَسٰکِیۡنِ وَ  الۡعٰمِلِیۡنَ عَلَیۡہَا وَ الۡمُؤَلَّفَۃِ قُلُوۡبُہُمۡ وَ فِی الرِّقَابِ وَ الۡغٰرِمِیۡنَ وَ فِیۡ سَبِیۡلِ اللّٰہِ وَ ابۡنِ السَّبِیۡلِ ؕ فَرِیۡضَۃً مِّنَ  اللّٰہِ ؕ وَ اللّٰہُ  عَلِیۡمٌ  حَکِیۡمٌ ﴿۶۰﴾', 'صدقات یعنی زکوٰۃ و خیرات تو مفلسوں اور ناداروں اور کارکنان صدقات کا حق ہے اور ان لوگوں کا جنکے دل جیتنا منظور ہے اور غلاموں کے آزاد کرانے اور قرضداروں کے قرض ادا کرنے میں اور اللہ کی راہ میں اور مسافروں کی مدد میں بھی یہ مال خرچ کرنا چاہیے یہ مصارف اللہ کی طرف سے مقرر کر دیئے گئے ہیں اور اللہ جاننے والا ہے حکمت والا ہے۔', 'زکوٰۃ جو ہے سو وہ حق ہے مفلسوں کا اور محتاجوں کا اور زکوٰۃ کے کام پر جانے والوں کا اور جن کا دل پرچانا منظور ہے اور گردنوں کے چھڑانے میں اور جو تاوان بھریں اور اللہ کے رستہ میں اور راہ کے مسافر کو ٹھہرایا ہوا ہے اللہ کا اور اللہ سب کچھ جاننے والا حکمت والا ہے [۶۱]', 'As-Sadaqat (here it means Zakat) are only for the Fuqara (poor), and Al-Masakin (the poor) and those employed to collect (the funds); and for to attract the hearts of those who have been inclined (towards Islam); and to free the captives; and for those in debt; and for Allahs Cause (i.e. for Mujahidoon - those fighting in the holy wars), and for the wayfarer (a traveller who is cut off from everything); a duty imposed by Allah. And Allah is All-Knower, All-Wise.', 'The Sadaqāt (prescribed alms) are (meant) only to be given to the poor, the needy, to those employed to collect them, to those whose hearts are to be won, in the cause of the slaves and those encumbered with debt, in the way of Allah and to a wayfarer. This is an obligation prescribed by Allah. Allah is All-Knowing, Wise.'),
(1296, 9, 61, 8, 14, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ مِنۡہُمُ الَّذِیۡنَ یُؤۡذُوۡنَ النَّبِیَّ وَ یَقُوۡلُوۡنَ ہُوَ اُذُنٌ ؕ قُلۡ اُذُنُ خَیۡرٍ لَّکُمۡ یُؤۡمِنُ بِاللّٰہِ  وَ یُؤۡمِنُ لِلۡمُؤۡمِنِیۡنَ وَ رَحۡمَۃٌ  لِّلَّذِیۡنَ اٰمَنُوۡا مِنۡکُمۡ ؕ وَ الَّذِیۡنَ یُؤۡذُوۡنَ رَسُوۡلَ اللّٰہِ لَہُمۡ عَذَابٌ  اَلِیۡمٌ ﴿۶۱﴾', 'اور ان میں بعض ایسے ہیں جو پیغمبر کو ایذا دیتے ہیں اور کہتے ہیں کہ یہ شخص نرا کان ہے ان سے کہدو کہ وہ کان ہے تو تمہاری بھلائی کے لئے۔ وہ اللہ کا اور مومنوں کی بات کا یقین رکھتا ہے۔ اور جو لوگ تم میں ایمان لائے ہیں ان کے لئے رحمت ہے اور جو لوگ اللہ کے رسول کو رنج پہنچاتے ہیں انکے لئے عذاب الیم تیار ہے۔', 'اور بعضے ان میں بدگوئی کرتے ہیں نبی کی اور کہتے ہیں کہ یہ شخص تو کان ہے تو کہہ کان ہے تمہارے بھلے کے واسطے یقین رکھتا ہے اللہ پر اور یقین کرتا ہے مسلمانوں کی بات کا اور رحمت ہے ایمان والوں کے حق میں تم میں سے اور جو لوگ بدگوئی کرتے ہیں اللہ کے رسول کی ان کے لئے عذاب ہے دردناک [۶۲]', 'And among them are men who hurt the Prophet (Muhammad SAW) and say: \"He is (lending his) ear (to every news).\" Say: \"He listens to what is best for you; he believes in Allah; has faith in the believers; and is a mercy to those of you who believe.\" But those who hurt Allahs Messenger (Muhammad SAW) will have a painful torment.', 'And among them (the hypocrites) there are those who hurt the Prophet and say, “He is just an ear” (that is, he hears and believes everything). Say, “He gives ear to that which is good for you; he believes in Allah and trusts the believers and is a mercy for those of you who (pretend to) believe.” And those who hurt the Messenger of Allah, for them there is a painful punishment.'),
(1297, 9, 62, 8, 14, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'یَحۡلِفُوۡنَ بِاللّٰہِ لَکُمۡ لِیُرۡضُوۡکُمۡ ۚ وَ اللّٰہُ وَ رَسُوۡلُہٗۤ  اَحَقُّ اَنۡ یُّرۡضُوۡہُ  اِنۡ کَانُوۡا  مُؤۡمِنِیۡنَ ﴿۶۲﴾', 'مومنو! یہ لوگ تمہارے سامنے اللہ کی قسمیں کھاتے ہیں تاکہ تم کو خوش کر دیں۔ حالانکہ اگر یہ دل سے مومن ہوتے تو اللہ اور اسکے پیغمبر اس بات کے زیادہ حقدار ہیں کہ یہ انہیں خوش کریں۔', 'قسمیں کھاتے ہیں اللہ کی تمہارےآگے تاکہ تم کر راضی کریں اور اللہ کو اور اسکے رسول کو بہت ضرور ہے راضی کرنا اگر وہ ایمان رکھتے ہیں [۶۳]', 'They swear by Allah to you (Muslims) in order to please you, but it is more fitting that they should please Allah and His Messenger (Muhammad SAW), if they are believers.', '(O believers,) they swear by Allah before you, so that they may please you, whereas Allah, as well as His Messenger, has greater right that they should please Him, if they are (true) believers.'),
(1298, 9, 63, 8, 14, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اَلَمۡ یَعۡلَمُوۡۤا اَنَّہٗ مَنۡ یُّحَادِدِ اللّٰہَ وَ رَسُوۡلَہٗ  فَاَنَّ لَہٗ  نَارَ جَہَنَّمَ خَالِدًا فِیۡہَا ؕ ذٰلِکَ  الۡخِزۡیُ  الۡعَظِیۡمُ ﴿۶۳﴾', 'کیا ان لوگوں کو معلوم نہیں کہ جو شخص اللہ اور اسکے رسول سے مقابلہ کرتا ہے تو اس کے لئے جہنم کی آگ تیار ہے جسمیں وہ ہمیشہ جلتا رہے گا۔ یہ بڑی رسوائی ہے۔', 'کیا وہ جان نہیں چکے کہ جو کوئی مقابلہ کرے اللہ سے اور اسکے رسول سے تو اسکے واسطے ہے دوزخ کی آگ سدا رہے اس میں یہی ہے بڑی رسوائی [۶۴]', 'Know they not that whoever opposes and shows hostility to Allah (ÚÒ æ Ìá) and His Messenger (SAW), certainly for him will be the Fire of Hell to abide therein. That is extreme disgrace.', 'Have they not come to know that whoever opposes Allah and His Messenger, definite for him is the fire of Jahannam (Hell) wherein he will remain forever. That is the extreme disgrace.'),
(1299, 9, 64, 8, 14, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'یَحۡذَرُ الۡمُنٰفِقُوۡنَ اَنۡ تُنَزَّلَ عَلَیۡہِمۡ سُوۡرَۃٌ  تُنَبِّئُہُمۡ بِمَا فِیۡ قُلُوۡبِہِمۡ ؕ قُلِ اسۡتَہۡزِءُوۡا ۚ اِنَّ اللّٰہَ  مُخۡرِجٌ مَّا تَحۡذَرُوۡنَ ﴿۶۴﴾', 'منافق ڈرتے رہتے ہیں کہ انکے بارے میں کہیں کوئی ایسی سورت نہ اتر آئے کہ انکی دل کی باتوں کو ان مسلمانوں پر ظاہر کر دے۔ کہدو کہ ہنسی کئے جاؤ۔ جس بات سے تم ڈرتے ہو اللہ اسکو ضرور ظاہر کر دے گا۔', 'ڈرا کرتے ہیں منافق اس بات سے کہ نازل ہو مسلمانوں پر ایسی سورت کہ جتا دے انکو جو انکے دل میں ہے تو کہہ دے ٹھٹھے کرتے رہو اللہ کھول کر رہے گا اس چیز کو جس کا تم کو ڈر ہے [۶۵]', 'The hypocrites fear lest a Soorah (chapter of the Quran) should be revealed about them, showing them what is in their hearts. Say: \"(Go ahead and) mock! But certainly Allah will bring to light all that you fear.\"', 'The hypocrites are afraid that a Sūrah (a chapter of the Holy Qur’ān) may be sent down about them, which tells them what lies in their hearts. Say, “Go on mocking. Allah is surely to bring out what you are afraid of.”'),
(1300, 9, 65, 8, 14, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ لَئِنۡ سَاَلۡتَہُمۡ لَیَقُوۡلُنَّ اِنَّمَا کُنَّا نَخُوۡضُ وَ نَلۡعَبُ ؕ قُلۡ اَ بِاللّٰہِ وَ اٰیٰتِہٖ وَ رَسُوۡلِہٖ  کُنۡتُمۡ  تَسۡتَہۡزِءُوۡنَ ﴿۶۵﴾', 'اور اگر تم ان سے اس بارے میں دریافت کرو تو کہیں گے کہ ہم تو یونہی بات چیت اور دل لگی کرتے تھے۔ کہو کیا تم اللہ اور اسکی آیتوں اور اسکے رسول سے دل لگی کرتے تھے؟', 'اور اگر تو ان سے پوچھے تو وہ کہیں گے ہم تو بات چیت کرتےتھے اور دل لگی [۶۶] تو کہہ کیا اللہ سے اور اسکے حکموں سے اور اسکے رسول سے تم ٹھٹھے کرتے تھے [۶۷]', 'If you ask them (about this), they declare: \"We were only talking idly and joking.\" Say: \"Was it at Allah (ÚÒ æ Ìá), and His Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) and His Messenger (SAW) that you were mocking?\"', 'And if you ask them, they will say, “We were just chatting and having fun.” Say, “Is it of Allah and His verses and His Messenger that you were making fun?”'),
(1301, 9, 66, 8, 14, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'لَا تَعۡتَذِرُوۡا قَدۡ کَفَرۡتُمۡ  بَعۡدَ  اِیۡمَانِکُمۡ ؕ اِنۡ نَّعۡفُ عَنۡ طَآئِفَۃٍ مِّنۡکُمۡ نُعَذِّبۡ طَآئِفَۃًۢ  بِاَنَّہُمۡ  کَانُوۡا  مُجۡرِمِیۡنَ ﴿٪۶۶﴾', 'عذر مت پیش کرو تم ایمان لانے کے بعد کافر ہو چکے ہو اگر ہم تم میں سے ایک جماعت کو معاف کر دیں تو دوسری جماعت کو سزا بھی دیں گے کیونکہ وہ گناہ کرتے رہے ہیں۔', 'بہانے مت بناؤ تم تو کافر ہو گئے اظہار ایمان کے پیچھے اگر ہم معاف کر دیں گے تم میں سے بعضوں کو تو البتہ عذاب بھی دیں گے بعضوں کو اس سبب سےکہ وہ گنہگار تھے [۶۸]', 'Make no excuse; you have disbelieved after you had believed. If We pardon some of you, We will punish others amongst you because they were Mujrimoon (disbelievers, polytheists, sinners, criminals, etc.).', 'Make no excuses. You became disbelievers (by mocking at Allah and His Messenger) after you had professed Faith. If We forgive some of you (who repent and believe), We shall punish others (who carry on their hypocrisy), because they were guilty.'),
(1302, 9, 67, 9, 15, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اَلۡمُنٰفِقُوۡنَ وَ الۡمُنٰفِقٰتُ بَعۡضُہُمۡ مِّنۡۢ بَعۡضٍ ۘ یَاۡمُرُوۡنَ بِالۡمُنۡکَرِ وَ یَنۡہَوۡنَ عَنِ الۡمَعۡرُوۡفِ وَ یَقۡبِضُوۡنَ اَیۡدِیَہُمۡ ؕ نَسُوا اللّٰہَ  فَنَسِیَہُمۡ ؕ اِنَّ  الۡمُنٰفِقِیۡنَ ہُمُ  الۡفٰسِقُوۡنَ ﴿۶۷﴾', 'منافق مرد اور منافق عورتیں ایک دوسرے کے ہم جنس یعنی ایک ہی طرح کے ہیں کہ برا کام کرنے کو کہتے اور نیک کاموں سے منع کرتے اور خرچ کرنے سے ہاتھ بند کئے رہتے ہیں۔ انہوں نے اللہ کو بھلا دیا تو اللہ نے انکو بھلا دیا۔ بیشک منافق نافرمان ہیں۔', 'منافق مرد اور منافق عورتیں سب کی ایک چال ہے سکھائیں بات بری اور چھڑائیں بات بھلی اوربند رکھیں اپنی مٹھی بھول گئے اللہ کو سو وہ بھول گیا انکو تحقیق منافق وہی ہیں نافرمان [۶۹]', 'The hypocrites, men and women, are from one another, they enjoin (on the people) Al-Munkar (i.e. disbelief and polytheism of all kinds and all that Islam has forbidden), and forbid (people) from Al-Maroof (i.e. Islamic Monotheism and all that Islam orders one to do), and they close their hands (from giving (spending in Allahs Cause) alms, etc.). They have forgotten Allah, so He has forgotten them. Verily, the hypocrites are the Fasiqoon (rebellious, disobedient to Allah).', 'The hypocrites, males and females, are all alike. They bid vice and forbid virtue and withhold their hands (from spending in Allah’s way). They forgot Allah, so He forgot them. Surely, the hypocrites are the sinners.'),
(1303, 9, 68, 9, 15, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَعَدَ اللّٰہُ الۡمُنٰفِقِیۡنَ وَ الۡمُنٰفِقٰتِ وَ الۡکُفَّارَ نَارَ جَہَنَّمَ خٰلِدِیۡنَ فِیۡہَا ؕ ہِیَ حَسۡبُہُمۡ ۚ وَ لَعَنَہُمُ اللّٰہُ ۚ وَ لَہُمۡ عَذَابٌ  مُّقِیۡمٌ ﴿ۙ۶۸﴾', 'اللہ نے منافق مردوں اور منافق عورتوں اور کافروں سے آتش جہنم کا وعدہ کیا ہے جسمیں وہ ہمیشہ جلتے رہیں گے وہی انکو کافی ہے اور اللہ نے ان پر لعنت کر دی ہے اور انکے لئے ہمیشہ کا عذاب تیار ہے۔', 'وعدہ دیا ہے اللہ نے منافق مرد اور منافق عورتوں کو اور کافروں کو دوزخ کی آگ کا پڑے رہیں گے اس میں وہی بس ہے انکو [۷۰] اور اللہ نے انکو پھٹکار دیا اور انکے لئے عذاب ہے برقرار رہنے والا [۷۱]', 'Allah has promised the hypocrites; men and women, and the disbelievers, the Fire of Hell, therein shall they abide. It will suffice them. Allah has cursed them and for them is the lasting torment.', 'Allah has promised the fire of Jahannam to the hypocrites, men and women, and to the disbelievers who shall live there forever. It is adequate for them. Allah has put His curse on them, and for them there is a lasting punishment.'),
(1304, 9, 69, 9, 15, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'کَالَّذِیۡنَ مِنۡ قَبۡلِکُمۡ کَانُوۡۤا اَشَدَّ مِنۡکُمۡ  قُوَّۃً  وَّ اَکۡثَرَ اَمۡوَالًا وَّ اَوۡلَادًا ؕ فَاسۡتَمۡتَعُوۡا بِخَلَاقِہِمۡ فَاسۡتَمۡتَعۡتُمۡ بِخَلَاقِکُمۡ  کَمَا اسۡتَمۡتَعَ الَّذِیۡنَ مِنۡ قَبۡلِکُمۡ بِخَلَاقِہِمۡ وَ خُضۡتُمۡ کَالَّذِیۡ خَاضُوۡا ؕ اُولٰٓئِکَ حَبِطَتۡ اَعۡمَالُہُمۡ  فِی الدُّنۡیَا وَ الۡاٰخِرَۃِ ۚ وَ اُولٰٓئِکَ ہُمُ  الۡخٰسِرُوۡنَ ﴿۶۹﴾', 'تم منافق لوگ ان لوگوں کی طرح ہو جو تم سے پہلے ہو چکے ہیں۔ وہ تم سے زیادہ طاقتور اور مال و اولاد میں کہیں زیادہ تھے تو وہ اپنے حصے سے فائدہ اٹھا چکے سو جس طرح تم سے پہلے لوگ اپنے حصے سے فائدہ اٹھا چکے ہیں اسی طرح تم نے اپنے حصے سے فائدہ اٹھا لیا۔ اور جس طرح وہ باطل میں ڈوبے رہے اسی طرح تم باطل میں ڈوبے رہے یہ وہ لوگ ہیں جنکے اعمال دنیا اور آخرت میں ضائع ہو گئے اور یہی نقصان اٹھانے والے ہیں۔', 'جس طرح تم سے اگلے لوگ زیادہ تھے تم سے زور میں اور زیادہ رکھتے تھے مال اور اولاد پھر فائدہ اٹھا گئے اپنے حصہ سے [۷۲] پھر فائدہ اٹھایا تم نے اپنے حصہ سے جیسے فائدہ اٹھا گئے تم سے اگلے اپنے حصہ سے اور تم بھی چلتے ہو انہی کی سی چال [۷۳] وہ لوگ مٹ گئے ان کے عمل دنیا میں اور آخرت میں اور وہی لوگ پڑے نقصان میں [۷۴]', 'Like those before you, they were mightier than you in power, and more abundant in wealth and children. They had enjoyed their portion awhile, so enjoy your portion awhile as those before you enjoyed their portion awhile; and you indulged in play and pastime (and in telling lies against Allah and His Messenger Muhammad SAW) as they indulged in play and pastime. Such are they whose deeds are in vain in this world and in the Hereafter. Such are they who are the losers.', '(You are) like those who were before you. They were stronger than you in power, and richer in wealth and children. So, they enjoyed their share (from the pleasures of this world), then you enjoyed your share as those before you enjoyed their share, and you indulged (in evils) as they indulged. They are the ones whose deeds have gone to waste in this world and in the Hereafter, and they are the losers.'),
(1305, 9, 70, 9, 15, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اَلَمۡ  یَاۡتِہِمۡ نَبَاُ الَّذِیۡنَ مِنۡ  قَبۡلِہِمۡ  قَوۡمِ نُوۡحٍ وَّ عَادٍ وَّ ثَمُوۡدَ ۬ۙ وَ قَوۡمِ  اِبۡرٰہِیۡمَ  وَ اَصۡحٰبِ  مَدۡیَنَ  وَ الۡمُؤۡتَفِکٰتِ ؕ اَتَتۡہُمۡ رُسُلُہُمۡ بِالۡبَیِّنٰتِ ۚ فَمَا کَانَ اللّٰہُ  لِیَظۡلِمَہُمۡ  وَ لٰکِنۡ  کَانُوۡۤا اَنۡفُسَہُمۡ  یَظۡلِمُوۡنَ ﴿۷۰﴾', 'کیا انکو ان لوگوں کے حالات کی خبر نہیں پہنچی جو ان سے پہلے تھے یعنی نوح اور عاد اور ثمود کی قوم اور ابراہیم کی قوم اور مدین والے اور الٹی ہوئی بستیوں والے۔ انکے پاس پیغمبر نشانیاں لے کر آئے۔ اور اللہ تو ایسا نہ تھا کہ ان پر ظلم کرتا لیکن وہی اپنے آپ پر ظلم کرتے تھے۔', 'کیا پہنچی نہیں انکو خبر ان لوگوں کی جو ان سے پہلے تھے قوم نوح کی اور عاد کی اور ثمود کی اور قوم ابراہیم کی اور مدین والوں کی اور ان بستیوں کی خبر جو الٹ دی گئ تھیں [۷۵] پہنچے انکے پاس انکے رسول صاف حکم لے کر سو اللہ تو ایسا نہ تھا کہ ان پر ظلم کرتا لیکن وہ اپنے اوپر آپ ظلم کرتے تھے [۷۶]', 'Has not the story reached them of those before them? - The people of Nooh (Noah), Ad, and Thamood, the people of Ibraheem (Abraham), the dwellers of Madyan (Midian) and the cities overthrown (i.e. the people to whom Lout (Lot) preached), to them came their Messengers with clear proofs. So it was not Allah Who wronged them, but they used to wrong themselves.', 'Has there not reached them the news of those before them, the people of NūH and ‘Ād and Thamūd and the people of Ibrāhīm and the people of Madyan, and (the news) of the towns overturned? Their messengers came to them with clear signs; so, Allah was not such as would wrong them, but they have been doing wrong to their own selves.'),
(1306, 9, 71, 9, 15, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ الۡمُؤۡمِنُوۡنَ وَ الۡمُؤۡمِنٰتُ بَعۡضُہُمۡ اَوۡلِیَآءُ بَعۡضٍ ۘ یَاۡمُرُوۡنَ بِالۡمَعۡرُوۡفِ وَ یَنۡہَوۡنَ عَنِ الۡمُنۡکَرِ وَ یُقِیۡمُوۡنَ الصَّلٰوۃَ  وَ یُؤۡتُوۡنَ الزَّکٰوۃَ وَ یُطِیۡعُوۡنَ اللّٰہَ وَ رَسُوۡلَہٗ ؕ اُولٰٓئِکَ سَیَرۡحَمُہُمُ اللّٰہُ ؕ اِنَّ اللّٰہَ عَزِیۡزٌ  حَکِیۡمٌ ﴿۷۱﴾', 'اور مومن مرد اور مومن عورتیں ایک دوسرے کے دوست ہیں کہ اچھے کام کرنے کو کہتے اور بری باتوں سے منع کرتے اور نماز پڑھتے اور زکوٰۃ دیتے اور اللہ اور اسکے پیغمبر کی اطاعت کرتے ہیں۔ یہی لوگ ہیں جن پر اللہ رحم کرے گا بیشک اللہ غالب ہے حکمت والا ہے۔', 'اور ایمان والے مرد اور ایمان والی عورتیں ایک دوسرے کی مددگار ہیں سکھلاتے ہیں نیک بات اور منع کرتے ہیں بری بات سے اور قائم رکھتے ہیں نماز اور دیتے ہیں زکوٰۃ اور حکم پر چلتے ہیں اللہ کے اور اسکے رسول کے وہی لوگ ہیں جن پر رحم کرے گا اللہ بیشک اللہ زبردست ہے حکمت والا [۷۷]', 'The believers, men and women, are Auliya (helpers, supporters, friends, protectors) of one another, they enjoin (on the people) Al-Maroof (i.e. Islamic Monotheism and all that Islam orders one to do), and forbid (people) from Al-Munkar (i.e. polytheism and disbelief of all kinds, and all that Islam has forbidden); they perform As-Salat (Iqamat-as-Salat) and give the Zakat, and obey Allah and His Messenger. Allah will have His Mercy on them. Surely Allah is All-Mighty, All-Wise.', 'The believers, male and female, are friends to each other. They bid virtue and forbid vice and establish Salāh and pay Zakāh and obey Allah and His Messenger. Those are the ones whom Allah will bless with mercy. Surely, Allah is Powerful, Wise.'),
(1307, 9, 72, 9, 15, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَعَدَ اللّٰہُ الۡمُؤۡمِنِیۡنَ وَ الۡمُؤۡمِنٰتِ جَنّٰتٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَا وَ مَسٰکِنَ طَیِّبَۃً فِیۡ جَنّٰتِ عَدۡنٍ ؕ وَ رِضۡوَانٌ مِّنَ اللّٰہِ اَکۡبَرُ ؕ ذٰلِکَ ہُوَ  الۡفَوۡزُ  الۡعَظِیۡمُ ﴿٪۷۲﴾', 'اللہ نے مومن مردوں اور مومن عورتوں سے بہشتوں کا وعدہ کیا ہے جنکے نیچے نہریں بہ رہی ہیں وہ ان میں ہمیشہ رہیں گے اور ابدی بہشتوں میں نفیس مکانات کا وعدہ کیا ہے اور اللہ کی رضامندی تو سب سے بڑھ کر نعمت ہے یہی بڑی کامیابی ہے۔', 'وعدہ دیا ہے اللہ نے ایمان والے مردوں اور ایمان والی عورتوں کو باغوں کا کہ بہتی ہیں نیچے ان کے نہریں رہا کریں انہی میں اور ستھرے مکانوں کا رہنے کے باغوں میں اور رضامندی اللہ کی ان سب سے بڑی ہے یہی ہے بڑی کامیابی [۷۸]', 'Allah has promised to the believers -men and women, - Gardens under which rivers flow to dwell therein forever, and beautiful mansions in Gardens of Adn (Eden Paradise). But the greatest bliss is the Good Pleasure of Allah. That is the supreme success.', 'Allah has promised to the believers, male and female, gardens beneath which rivers flow, where they shall live forever, and good homes in gardens of eternity. And Allah’s pleasure is above all. That is the supreme success.'),
(1308, 9, 73, 10, 16, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'یٰۤاَیُّہَا النَّبِیُّ جَاہِدِ الۡکُفَّارَ وَ الۡمُنٰفِقِیۡنَ وَ اغۡلُظۡ عَلَیۡہِمۡ ؕ وَ مَاۡوٰىہُمۡ جَہَنَّمُ ؕ وَ بِئۡسَ الۡمَصِیۡرُ ﴿۷۳﴾', 'اے پیغمبر کافروں اور منافقوں سے جہاد کرو۔ اور ان پر سختی کرو۔ اور ان کا ٹھکانہ دوزخ ہے۔ اور وہ بری جگہ ہے۔', 'اے نبی لڑائی کر کافروں سے اور منافقوں سے اور تندخوئی کر ان پر اور ان کا ٹھکانہ دوزخ ہے اور وہ برا ٹھکانہ ہے [۷۹]', 'O Prophet (Muhammad SAW)! Strive hard against the disbelievers and the hypocrites, and be harsh against them, their abode is Hell, - and worst indeed is that destination.', 'O Prophet, carry out Jihād (struggle) against the disbelievers and hypocrites, and be strict with them. And their abode is Jahannam (Hell), and it is an evil terminus.'),
(1309, 9, 74, 10, 16, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'یَحۡلِفُوۡنَ بِاللّٰہِ مَا قَالُوۡا ؕ وَ لَقَدۡ قَالُوۡا کَلِمَۃَ  الۡکُفۡرِ وَ کَفَرُوۡا بَعۡدَ اِسۡلَامِہِمۡ وَ ہَمُّوۡا بِمَا لَمۡ  یَنَالُوۡا ۚ وَ مَا نَقَمُوۡۤا  اِلَّاۤ   اَنۡ اَغۡنٰہُمُ اللّٰہُ وَ رَسُوۡلُہٗ  مِنۡ فَضۡلِہٖ ۚ فَاِنۡ یَّتُوۡبُوۡا یَکُ خَیۡرًا لَّہُمۡ ۚ وَ اِنۡ یَّتَوَلَّوۡا یُعَذِّبۡہُمُ اللّٰہُ عَذَابًا اَلِیۡمًا ۙ فِی الدُّنۡیَا وَ الۡاٰخِرَۃِ ۚ وَ مَا لَہُمۡ فِی الۡاَرۡضِ  مِنۡ  وَّلِیٍّ  وَّ لَا  نَصِیۡرٍ ﴿۷۴﴾', 'یہ اللہ کی قسمیں کھاتے ہیں کہ انہوں نے تو کچھ نہیں کہا حالانکہ انہوں نے کفر کا کلمہ کہا ہے اور یہ اسلام لانے کے بعد کافر ہو گئے ہیں اور ایسی بات کا قصد کر چکے ہیں جس پر قدرت نہیں پا سکے۔ اور انہوں نے مسلمانوں میں عیب ہی کونسا دیکھا ہے سوائے اسکے کہ اللہ نے اپنے فضل سے اور اسکے پیغمبر نے اپنی مہربانی سے ان کو دولت مند کر دیا ہے۔ سو اگر یہ لوگ توبہ کر لیں تو انکے حق میں بہتر ہو گا اور اگر منہ پھیر لیں تو اللہ انکو دنیا اور آخرت میں دکھ دینے والا عذاب دے گا۔ اور زمین میں ان کا کوئی دوست اور مددگار نہ ہوگا۔', 'قسمیں کھاتے ہیں اللہ کی کہ ہم نے نہیں کہا اور بیشک کہا ہے انہوں نے لفظ کفر کا اور منکر ہو گئے مسلمان ہو کر [۸۰] اور قصد کیا تھا اس چیز کا جو ان کو نہ ملی [۸۱] اور یہ سب کچھ اسی کا بدلہ تھا کہ دولتمند کر دیا ان کو اللہ نے اور اسکے رسول نے اپنے فضل سےسو اگر توبہ کر لیں تو بھلا ہے ان کے حق میں اور اگر نہ مانیں گے تو عذاب دے گا انکو اللہ عذاب دردناک دنیا اور آخرت میں اور نہیں ان کا روئے زمین پر کوئی حمایتی اور نہ مددگار [۸۲]', 'They swear by Allah that they said nothing (bad), but really they said the word of disbelief, and they disbelieved after accepting Islam, and they resolved that (plot to murder Prophet Muhammad SAW) which they were unable to carry out, and they could not find any cause to do so except that Allah and His Messenger had enriched them of His Bounty. If then they repent, it will be better for them, but if they turn away, Allah will punish them with a painful torment in this worldly life and in the Hereafter. And there is none for them on earth as a Walee (supporter, protector) or a helper.', 'They swear by Allah that they said nothing, while indeed, they had said the word of infidelity and had disbelieved after having accepted Islam, and had intended what they could not achieve. And they have reacted for nothing but that Allah and His Messenger have enriched them with His grace.So, if they repent, it will be good for them, and if they turn away, Allah will chastise them with a painful punishment in this world and the Hereafter, and for them there is neither a friend on the Earth, nor a helper.'),
(1310, 9, 75, 10, 16, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ مِنۡہُمۡ مَّنۡ عٰہَدَ اللّٰہَ  لَئِنۡ اٰتٰىنَا مِنۡ فَضۡلِہٖ  لَنَصَّدَّقَنَّ وَ لَنَکُوۡنَنَّ مِنَ الصّٰلِحِیۡنَ ﴿۷۵﴾', 'اور ان میں بعض ایسے ہیں جنہوں نے اللہ سے عہد کیا تھا کہ اگر وہ ہم کو اپنی مہربانی سے مال عطا فرمائے گا تو ہم ضرور خیرات کیا کریں گے اور نیکوکاروں میں ہو جائیں گے۔', 'اور بعضے ان میں وہ ہیں کہ عہد کیا تھا اللہ سے اگر دیوے ہم کو اپنے فضل سے تو ہم ضرور خیرات کریں اور ہو رہیں ہم نیکی والوں میں', 'And of them are some who made a covenant with Allah (saying): \"If He bestowed on us of His Bounty, we will verily, give Sadaqah (Zakat and voluntary charity in Allahs Cause) and will be certainly among those who are righteous.\"', 'And among them there are those who made a pledge with Allah: “If He gives us (wealth) out of His grace, then, surely we shall give alms and shall be among the righteous.”'),
(1311, 9, 76, 10, 16, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'فَلَمَّاۤ  اٰتٰہُمۡ مِّنۡ  فَضۡلِہٖ بَخِلُوۡا بِہٖ وَ تَوَلَّوۡا وَّ ہُمۡ  مُّعۡرِضُوۡنَ ﴿۷۶﴾', 'لیکن جب اللہ نے انکو اپنے فضل سے مال دیا تو اس میں بخل کرنے لگے اور اپنے عہد سے روگردانی کر کے پھر بیٹھے۔', 'پھر جب دیا انکو اپنے فضل سے تو اس میں بخل کیا اور پھر گئے ٹلا کر [۸۳]', 'Then when He gave them of His Bounty, they became niggardly (refused to pay the Sadaqah (Zakat or voluntary charity)), and turned away, averse.', 'But when He gave them (wealth) out of His grace, they became stingy about it, and went back turning their faces away.'),
(1312, 9, 77, 10, 16, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'فَاَعۡقَبَہُمۡ نِفَاقًا فِیۡ قُلُوۡبِہِمۡ اِلٰی یَوۡمِ یَلۡقَوۡنَہٗ  بِمَاۤ  اَخۡلَفُوا اللّٰہَ مَا وَعَدُوۡہُ وَ بِمَا  کَانُوۡا  یَکۡذِبُوۡنَ ﴿۷۷﴾', 'تو اللہ نے اس کا انجام یہ کیا کہ اس روز تک کے لئے جسمیں یہ اللہ کے روبرو حاضر ہوں گے انکے دلوں میں نفاق ڈال دیا اس لئے کہ انہوں نے اللہ سے جو وعدہ کیا تھا اسکے خلاف کیا اور اس لئے کہ یہ جھوٹ بولتے تھے۔', 'پھر اس کا اثر رکھ دیا نفاق انکے دلوں میں جس دن تک کہ وہ اس سے ملیں گے اس وجہ سے کہ انہوں نے خلاف کیا اللہ سے جو وعدہ اس سے کیا تھا اور اس وجہ سے کہ بولتے تھے جھوٹ [۸۴]', 'So He punished them by putting hypocrisy into their hearts till the Day whereon they shall meet Him, because they broke that (covenant with Allah) which they had promised Him and because they used to tell lies.', 'So Allah, in turn, put hypocrisy in their hearts till the day they shall meet Him, because they broke their promise with Allah, and because they have been telling lies.'),
(1313, 9, 78, 10, 16, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اَلَمۡ یَعۡلَمُوۡۤا اَنَّ اللّٰہَ یَعۡلَمُ سِرَّہُمۡ وَ نَجۡوٰىہُمۡ  وَ  اَنَّ اللّٰہَ  عَلَّامُ الۡغُیُوۡبِ ﴿ۚ۷۸﴾', 'کیا انکو معلوم نہیں کہ اللہ انکے بھیدوں اور مشوروں تک سے واقف ہے اور یہ کہ اللہ غیب کی باتیں جاننے والا ہے۔', 'کیا وہ جان نہیں چکے کہ اللہ جانتا ہے ان کا بھید اور ان کا مشورہ اور یہ کہ اللہ خوب جانتا ہے سب چھپی باتوں کو [۸۵]', 'Know they not that Allah knows their secret ideas, and their Najwa (secret counsels), and that Allah is the All-Knower of the unseen.', 'Do they not know that Allah knows what they conceal and what they whisper, and that Allah is well aware of all the Unseen?'),
(1314, 9, 79, 10, 16, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اَلَّذِیۡنَ یَلۡمِزُوۡنَ الۡمُطَّوِّعِیۡنَ مِنَ الۡمُؤۡمِنِیۡنَ فِی الصَّدَقٰتِ وَ الَّذِیۡنَ لَا یَجِدُوۡنَ  اِلَّا جُہۡدَہُمۡ فَیَسۡخَرُوۡنَ مِنۡہُمۡ ؕ سَخِرَ  اللّٰہُ  مِنۡہُمۡ ۫ وَ لَہُمۡ عَذَابٌ  اَلِیۡمٌ ﴿۷۹﴾', 'جو مسلمان دل کھول کر خیرات کرتے ہیں اور جو بیچارے غریب صرف اتنا ہی کما سکتے ہیں جتنی مزدوری کرتے اور تھوڑی سی کمائی میں سے بھی خرچ کرتے ہیں ان پر جو منافق طعن کرتے اور ہنستے ہیں اللہ ان پر ہنستا ہے اور ان کے لئے تکلیف دینے والا عذاب تیار ہے۔', 'وہ لوگ جو طعن کرتے ہیں ان مسلمانوں پر جو دل کھول کر خیرات کرتے ہیں اور ان پر جو نہیں رکھتے مگر اپنی محنت کا پھر ان پر ٹھٹھے کرتے ہیں اللہ نے ان سے ٹھٹھا کیا ہے اور ان کے لئے عذاب دردناک ہے [۸۶]', 'Those who defame such of the believers who give charity (in Allahs Cause) voluntarily, and those who could not find to give charity (in Allahs Cause) except what is available to them, so they mock at them (believers), Allah will throw back their mockery on them, and they shall have a painful torment.', '(Among the hypocrites, there are) those who taunt the believers who voluntarily give alms and have nothing but their hard earnings; still they mock at such people. Allah mocks at them, and for them there is a painful punishment.'),
(1315, 9, 80, 10, 16, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اِسۡتَغۡفِرۡ لَہُمۡ اَوۡ لَا تَسۡتَغۡفِرۡ لَہُمۡ ؕ اِنۡ تَسۡتَغۡفِرۡ لَہُمۡ سَبۡعِیۡنَ مَرَّۃً  فَلَنۡ یَّغۡفِرَ اللّٰہُ  لَہُمۡ ؕ ذٰلِکَ بِاَنَّہُمۡ کَفَرُوۡا بِاللّٰہِ وَ رَسُوۡلِہٖ ؕ وَ اللّٰہُ  لَا یَہۡدِی الۡقَوۡمَ الۡفٰسِقِیۡنَ ﴿٪۸۰﴾', 'تم انکے لئے بخشش مانگو یا نہ مانگو برابر ہے اگر انکے لئے ستر دفعہ بھی بخشش مانگو گے تو بھی اللہ انکو نہیں بخشے گا یہ اس لئے کہ انہوں نے اللہ اور اسکے رسول سے کفر کیا۔ اور اللہ نافرمان لوگوں کو ہدایت نہیں دیتا۔', 'تو انکے لئے بخشش مانگ یا نہ مانگ اگر ان کے لئےستر بار بخشش مانگے تو بھی ہرگز نہ بخشے گا انکو اللہ یہ اس واسطے کہ وہ منکر ہوئے اللہ سے اور اس کے رسول سے اور اللہ رستہ نہیں دیتا نافرمان لوگوں کو [۸۷]', 'Whether you (O Muhammad SAW) ask forgiveness for them (hypocrites) or ask not forgiveness for them … (and even) if you ask seventy times for their forgiveness … Allah will not forgive them, because they have disbelieved in Allah and His Messenger (Muhammad SAW). And Allah guides not those people who are Fasiqoon (rebellious, disobedient to Allah).', '(It is all equal whether you) ask pardon for them or do not ask pardon for them. Even if you ask pardon for them seventy times, Allah will never pardon them. That is because they disbelieved in Allah and His Messenger. Allah does not lead the sinning people to the right path.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1316, 9, 81, 11, 17, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'فَرِحَ الۡمُخَلَّفُوۡنَ بِمَقۡعَدِہِمۡ خِلٰفَ رَسُوۡلِ اللّٰہِ وَ کَرِہُوۡۤا اَنۡ یُّجَاہِدُوۡا بِاَمۡوَالِہِمۡ وَ اَنۡفُسِہِمۡ فِیۡ سَبِیۡلِ اللّٰہِ وَ قَالُوۡا لَا تَنۡفِرُوۡا فِی الۡحَرِّ ؕ قُلۡ نَارُ جَہَنَّمَ اَشَدُّ حَرًّا ؕ لَوۡ کَانُوۡا یَفۡقَہُوۡنَ ﴿۸۱﴾', 'جو لوگ غزوہ تبوک میں پیچھے رہ گئے وہ اللہ کے پیغمبر کی مرضی کے برخلاف بیٹھ رہنے سے خوش ہوئے اور اس بات کو ناپسند کیا کہ اللہ کی راہ میں اپنے مال اور جان سے جہاد کریں۔ اور دوسروں سے بھی کہنے لگے کہ گرمی میں مت نکلنا ان سے کہہ دو کہ دوزخ کی آگ اس سے کہیں زیادہ گرم ہے کاش یہ اس بات کو سمجھتے۔', 'خوش ہو گئے پیچھے رہنے والے اپنے بیٹھ رہنے سے جدا ہو کر رسول اللہ سے اور گھبرائے اس سے کہ لڑیں اپنے مال سےاور جان سے اللہ کی راہ میں [۸۸] اور بولے کہ مت کوچ کرو گرمی میں [۸۹] تو کہہ دوزخ کی آگ سخت گرم ہے اگر ان کو سمجھ ہوتی [۹۰]', 'Those who stayed away (from Tabuk expedition) rejoiced in their staying behind the Messenger of Allah; they hated to strive and fight with their properties and their lives in the Cause of Allah, and they said: \"March not forth in the heat.\" Say: \"The Fire of Hell is more intense in heat\", if only they could understand!', 'Those who were left behind were happy with their sitting back to the displeasure of the Messenger of Allah, and they disliked carrying out Jihād in the way of Allah with their wealth and lives, and they said, “Do not march in this hot weather.” Say, “The fire of Jahannam is much more intense in heat,” only if they could understand.'),
(1317, 9, 82, 11, 17, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'فَلۡیَضۡحَکُوۡا قَلِیۡلًا وَّ لۡیَبۡکُوۡا کَثِیۡرًا ۚ جَزَآءًۢ بِمَا کَانُوۡا یَکۡسِبُوۡنَ ﴿۸۲﴾', 'یہ دنیا میں تھوڑا سا ہنس لیں اور آخرت میں انکو انکے اعمال کے بدلے جو یہ کرتے رہے ہیں بہت سا رونا ہو گا۔', 'سو وہ ہنس لیویں تھوڑ ا اور روویں بہت سا بدلا اس کا جو وہ کماتے تھے [۹۱]', 'So let them laugh a little and (they will) cry much as a recompense of what they used to earn (by committing sins).', 'So, let them laugh a little, and weep a lot, this being a reward of what they used to earn.'),
(1318, 9, 83, 11, 17, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'فَاِنۡ رَّجَعَکَ اللّٰہُ اِلٰی طَآئِفَۃٍ مِّنۡہُمۡ فَاسۡتَاۡذَنُوۡکَ لِلۡخُرُوۡجِ فَقُلۡ لَّنۡ تَخۡرُجُوۡا مَعِیَ اَبَدًا وَّ لَنۡ تُقَاتِلُوۡا مَعِیَ عَدُوًّا ؕ اِنَّکُمۡ رَضِیۡتُمۡ بِالۡقُعُوۡدِ اَوَّلَ مَرَّۃٍ   فَاقۡعُدُوۡا  مَعَ  الۡخٰلِفِیۡنَ ﴿۸۳﴾', 'پھر اگر اللہ تم کو ان میں سے کسی گروہ کی طرف لے جائے اور وہ تم سے نکلنے کی اجازت طلب کریں تو کہدینا کہ تم میرے ساتھ ہر گز نہیں نکلو گے اور نہ میرے ساتھ مددگار ہو کر دشمن سے جنگ کرو گے۔ تم پہلی دفعہ بیٹھ رہنے سے خوش ہوئے تو اب بھی پیچھے رہنے والوں کے ساتھ بیٹھے رہو۔', 'سو اگر پھر لے جائے تجھ کو اللہ کسی فرقہ کی طرف ان میں سے [۹۲] پھر اجازت چاہیں تجھ سے نکلنے کی تو تو کہہ دینا کہ تم ہرگز نہ نکلو گے میرے ساتھ کبھی اور نہ لڑو گے میرے ساتھ ہو کر کسی دشمن سے تم کو پسند آیا بیٹھ رہنا پہلی بار سو بیٹھے رہو پیچھے رہنے والوں کے ساتھ [۹۳]', 'If Allah brings you back to a party of them (the hypocrites), and they ask your permission to go out (to fight), say: \"Never shall you go out with me, nor fight an enemy with me; you agreed to sit inactive on the first occasion, then you sit (now) with those who lag behind.\"', 'Then, if Allah brings you back to a group of them and they seek your permission to march, say to them, “You shall never march with me ever after, and shall never fight an enemy in my company. You were happy with sitting back the first time; now, sit with those remaining behind”.'),
(1319, 9, 84, 11, 17, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ لَا تُصَلِّ عَلٰۤی اَحَدٍ مِّنۡہُمۡ مَّاتَ اَبَدًا وَّ لَا تَقُمۡ عَلٰی قَبۡرِہٖ ؕ اِنَّہُمۡ کَفَرُوۡا بِاللّٰہِ وَ رَسُوۡلِہٖ  وَ مَا تُوۡا وَ ہُمۡ  فٰسِقُوۡنَ ﴿۸۴﴾', 'اور اے پیغمبر ان میں سے کوئی مر جائے تو کبھی اسکے جنازے پر نماز نہ پڑھنا اور نہ اسکی قبر پر جا کر کھڑے ہونا۔ یہ اللہ اور اسکے رسول کے ساتھ کفر کرتے رہے اور مرے بھی تو نافرمان ہی مرے۔', 'اور نماز نہ پڑھ ان میں سے کسی پر جو مر جائے کبھی اور نہ کھڑا ہو اس کی قبر پر [۹۴] وہ منکر ہوئے اللہ سے اور اسکے رسول سے اور  وہ مر گئے نافرمان [۹۵]', 'And never (O Muhammad SAW) pray (funeral prayer) for any of them (hypocrites) who dies, nor stand at his grave. Certainly they disbelieved in Allah and His Messenger, and died while they were Fasiqoon (rebellious, - disobedient to Allah and His Messenger SAW).', 'And never offer a prayer on any one of them who dies, and do not stand by his grave. They disbelieved in Allah and His Messenger and died while they were sinners.'),
(1320, 9, 85, 11, 17, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ لَا تُعۡجِبۡکَ اَمۡوَالُہُمۡ  وَ اَوۡلَادُہُمۡ ؕ اِنَّمَا یُرِیۡدُ اللّٰہُ  اَنۡ یُّعَذِّبَہُمۡ بِہَا فِی الدُّنۡیَا وَ تَزۡہَقَ  اَنۡفُسُہُمۡ  وَ ہُمۡ کٰفِرُوۡنَ ﴿۸۵﴾', 'اور انکے مال اور اولاد سے تعجب نہ کرنا۔ ان چیزوں سے اللہ یہ چاہتا ہے کہ انکو دنیا میں عذاب کرے۔ اور جب انکی جان نکلے تو اس وقت بھی یہ کافر ہی ہوں۔', 'اور تعجب نہ کر ان کے مال اور اولاد سے اللہ تو یہی چاہتا ہے کہ عذاب میں رکھے انکو ان چیزوں کے باعث دنیا میں اور نکلے ان کی جان اور وہ اس وقت تک کافر ہی رہیں [۹۶]', 'And let not their wealth or their children amaze you. Allahs Plan is to punish them with these things in this world, and that their souls shall depart (die) while they are disbelievers.', 'Their wealth and children should not attract you. Allah only wills to punish them with these in this world and that their souls depart while they are disbelievers.'),
(1321, 9, 86, 11, 17, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ اِذَاۤ  اُنۡزِلَتۡ سُوۡرَۃٌ  اَنۡ اٰمِنُوۡا بِاللّٰہِ وَ جَاہِدُوۡا مَعَ  رَسُوۡلِہِ  اسۡتَاۡذَنَکَ اُولُوا الطَّوۡلِ  مِنۡہُمۡ وَ قَالُوۡا ذَرۡنَا نَکُنۡ  مَّعَ  الۡقٰعِدِیۡنَ ﴿۸۶﴾', 'اور جب کوئی سورت نازل ہوتی ہے کہ اللہ پر ایمان لاؤ اور اسکے رسول کے ساتھ ہو کر جہاد کرو تو جو ان میں دولت مند ہیں وہ تم سے اجازت طلب کرتے ہیں اور کہتے ہیں کہ ہمیں تو رہنے ہی دیجئے کہ ہم بیٹھ رہنے والوں کے ساتھ ہو جائیں۔', 'اور جب نازل ہوتی ہے کوئی سورت کہ ایمان لاؤ اللہ پر اور لڑائی کرو اسکے رسول کے ساتھ ہو کر جو تجھ سے رخصت مانگتے ہیں مقدور والے انکے اور کہتے ہیں ہم کو چھوڑ دے کہ رہ جائیں ساتھ بیٹھنے والوں کے', 'And when a Soorah (chapter from the Quran) is revealed, enjoining them to believe in Allah and to strive hard and fight along with His Messenger, the wealthy among them ask your leave to exempt them (from Jihad) and say, \"Leave us (behind), we would be with those who sit (at home).\"', 'When a Sūrah is revealed (saying), “Believe in Allah and carry out Jihād in the company of His Messenger” the capable ones from them seek your permission and say, “Let us remain with those sitting back.”'),
(1322, 9, 87, 11, 17, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'رَضُوۡا بِاَنۡ یَّکُوۡنُوۡا مَعَ الۡخَوَالِفِ وَ طُبِعَ  عَلٰی  قُلُوۡبِہِمۡ فَہُمۡ لَا یَفۡقَہُوۡنَ ﴿۸۷﴾', 'یہ اس بات سے خوش ہیں کہ عورتوں کے ساتھ جو پیچھے رہ جاتی ہیں گھروں میں بیٹھ رہیں انکے دلوں پر مہر لگا دی گئ ہے سو یہ سمجھتے ہی نہیں۔', 'خوش ہوئے کہ رہ جائیں پیچھے رہنے والی عورتوں کے ساتھ [۹۷] اور مہر کر دی گئی ان کے دل پر سو وہ نہیں سمجھتے [۹۸]', 'They are content to be with those (the women) who sit behind (at home). Their hearts are sealed up (from all kinds of goodness and right guidance), so they understand not.', 'They are happy to be with women who sit back, and their hearts are sealed; so they do not understand.'),
(1323, 9, 88, 11, 17, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'لٰکِنِ الرَّسُوۡلُ وَ الَّذِیۡنَ اٰمَنُوۡا مَعَہٗ جٰہَدُوۡا بِاَمۡوَالِہِمۡ وَ اَنۡفُسِہِمۡ ؕ وَ اُولٰٓئِکَ لَہُمُ الۡخَیۡرٰتُ ۫ وَ اُولٰٓئِکَ ہُمُ الۡمُفۡلِحُوۡنَ ﴿۸۸﴾', 'لیکن پیغمبر اور جو لوگ انکے ساتھ ایمان لائے سب اپنے مال اور جان سے لڑے۔ انہی لوگوں کے لئے بھلائیاں ہیں اور یہی مراد پانے والے ہیں۔', 'لیکن رسول اور جو لوگ ایمان لائے ہیں ساتھ اسکے وہ لڑے ہیں اپنے مال اور جان سے اور انہی کے لئے ہیں خوبیاں اور وہی ہیں مراد کو پہنچنے والے', 'But the Messenger (Muhammad SAW) and those who believed with him (in Islamic Monotheism) strove hard and fought with their wealth and their lives (in Allahs Cause). Such are they for whom are the good things, and it is they who will be successful.', 'But the Messenger and the believers in his company have carried out Jihād with their wealth and lives, and for them there are the good things, and they are the successful.'),
(1324, 9, 89, 11, 17, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اَعَدَّ اللّٰہُ  لَہُمۡ  جَنّٰتٍ تَجۡرِیۡ مِنۡ  تَحۡتِہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَا ؕ ذٰلِکَ الۡفَوۡزُ الۡعَظِیۡمُ ﴿٪۸۹﴾', 'اللہ نے انکے لئے باغات تیار کر رکھے ہیں جنکے نیچے نہریں بہ رہی ہیں ہمیشہ ان میں رہیں گے یہی بڑی کامیابی ہے۔', 'تیار کر رکھے ہیں اللہ نےانکے واسطے باغ کہ بہتی ہیں نیچے انکے نہریں رہا کریں ان میں یہی ہے بڑی کامیابی [۹۹]', 'For them Allah has got ready Gardens (Paradise) under which rivers flow, to dwell therein forever. That is the supreme success.', 'Allah has prepared for them gardens beneath which rivers flow where they will live forever. That is the supreme achievement.'),
(1325, 9, 90, 12, 0, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَ جَآءَ الۡمُعَذِّرُوۡنَ مِنَ الۡاَعۡرَابِ لِیُؤۡذَنَ لَہُمۡ وَ قَعَدَ الَّذِیۡنَ  کَذَبُوا اللّٰہَ وَ رَسُوۡلَہٗ ؕ سَیُصِیۡبُ الَّذِیۡنَ کَفَرُوۡا مِنۡہُمۡ  عَذَابٌ  اَلِیۡمٌ ﴿۹۰﴾', 'اور صحرا نشینوں میں سے بھی کچھ لوگ عذر کرتے ہوئے تمہارے پاس آئے کہ انکو بھی اجازت دی جائے۔ اور جنہوں نے اللہ اور اسکے رسول سے جھوٹ بولا وہ گھر میں بیٹھ رہے۔ سو جو لوگ ان میں سے کافر ہوئے ہیں انکو دکھ دینے والا عذاب پہنچے گا۔', 'اور آئے بہانہ کرنے والے گنوار تاکہ انکو رخصت مل جائے اور بیٹھ رہے جنہوں نے جھوٹ بولا تھا اللہ سے اور اسکے رسول سے اب پہنچے گا انکو جو کافر ہیں ان میں عذاب دردناک [۱۰۰]', 'And those who made excuses from the bedouins came (to you, O Prophet SAW) asking your permission to exempt them (from the battle), and those who had lied to Allah and His Messenger sat at home (without asking the permission for it); a painful torment will seize those of them who disbelieve.', 'And the excuse-makers from the Bedouins came, so that they might be allowed (to stay behind), while those who were false to Allah and His Messengers (just) stayed behind (without seeking permission). A painful punishment is about to fall upon those of them who disbelieve.'),
(1326, 9, 91, 12, 0, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'لَیۡسَ عَلَی الضُّعَفَآءِ وَ لَا عَلَی الۡمَرۡضٰی وَ لَا عَلَی الَّذِیۡنَ لَا  یَجِدُوۡنَ  مَا یُنۡفِقُوۡنَ حَرَجٌ  اِذَا نَصَحُوۡا لِلّٰہِ وَ رَسُوۡلِہٖ ؕ مَا عَلَی الۡمُحۡسِنِیۡنَ مِنۡ سَبِیۡلٍ ؕ وَ اللّٰہُ  غَفُوۡرٌ   رَّحِیۡمٌ ﴿ۙ۹۱﴾', 'نہ تو ضعیفوں پر کچھ گناہ ہے اور نہ بیماروں پر اور نہ ان پر جنکے پاس خرچ موجود نہیں کہ شریک جہاد ہوں یعنی جبکہ اللہ اور کے رسول سے مخلص ہوں۔ نیکوکاروں پر کسی طرح کا الزام نہیں ہے اور اللہ بخشنے والا ہے مہربان ہے۔', 'نہیں ہے ضعیفوں پر اور نہ مریضوں پر اور نہ ان لوگوں پر جنکے پاس نہیں ہے خرچ کرنے کو کچھ گناہ جبکہ دل سےصاف ہوں اللہ اور اسکے رسول کے ساتھ  نہیں ہے نیکی والوں پر الزام کی کوئی راہ [۱۰۱] اور اللہ بخشنے والا مہربان ہے [۱۰۲]', 'There is no blame on those who are weak or ill or who find no resources to spend (in holy fighting (Jihad)), if they are sincere and true (in duty) to Allah and His Messenger. No ground (of complaint) can there be against the Muhsinoon (good-doers - see the footnote of V.9:120). And Allah is Oft-Forgiving, Most Merciful.', 'There is no blame on the weak, or on the sick, or on those who have nothing to spend, if they are sincere to Allah and His Messenger. There is no way against those who are good in deeds. Allah is most Forgiving, Very Merciful.'),
(1327, 9, 92, 12, 0, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'وَّ لَا عَلَی الَّذِیۡنَ  اِذَا  مَاۤ   اَتَوۡکَ  لِتَحۡمِلَہُمۡ قُلۡتَ لَاۤ  اَجِدُ مَاۤ  اَحۡمِلُکُمۡ  عَلَیۡہِ ۪ تَوَلَّوۡا  وَّ  اَعۡیُنُہُمۡ تَفِیۡضُ مِنَ  الدَّمۡعِ حَزَنًا  اَلَّا  یَجِدُوۡا  مَا  یُنۡفِقُوۡنَ ﴿ؕ۹۲﴾', 'اور نہ ان بے سروسامان لوگوں پر الزام ہے کہ جو تمہارے پاس آئے کہ انکو سواری دو اور تم نے کہا کہ میرے پاس کوئی ایسی چیز نہیں کہ جس پر تم کو سوار کروں تو وہ لوٹ گئے اور اس غم سے کہ انکے پاس خرچ موجود نہ تھا انکی آنکھوں سے آنسو بہ رہے تھے۔', 'اور نہ ان لوگوں پر کہ جب تیرے پاس آئے تاکہ تو ان کو سواری دے تو نے کہا میرے پاس کوئ چیز نہیں کہ تم کو اس پر سوار کر دوں تو الٹے پھرے اور انکی آنکھوں سے بہتے تھے آنسو اس غم میں کہ نہیں پاتے وہ چیز جو خرچ کریں [۱۰۳]', 'Nor (is there blame) on those who came to you to be provided with mounts, and when you said: \"I can find no mounts for you,\" they turned back, while their eyes overflowing with tears of grief that they could not find anything to spend (for Jihad).', 'Nor (is there any blame) on those who, when they came to you so that you might provide them with a carrier (that they could ride for Jihād ) and you said (to them), “I find no carrier to give to you”, went back with their eyes flowing with tears in grief, because they had nothing to spend.'),
(1328, 9, 93, 12, 0, 10, 'وَ اعۡلَمُوۡۤا', 'التوبۃ', 'اِنَّمَا السَّبِیۡلُ عَلَی الَّذِیۡنَ یَسۡتَاۡذِنُوۡنَکَ وَ ہُمۡ اَغۡنِیَآءُ ۚ رَضُوۡا بِاَنۡ یَّکُوۡنُوۡا مَعَ الۡخَوَالِفِ ۙ وَ طَبَعَ اللّٰہُ  عَلٰی قُلُوۡبِہِمۡ  فَہُمۡ  لَا  یَعۡلَمُوۡنَ ﴿۹۳﴾', 'الزام تو ان لوگوں پر ہے جو دولت مند ہیں اور پھر تم سے اجازت طلب کرتے ہیں یعنی اس بات سے خوش ہیں کہ عورتوں کے ساتھ جو پیچھے رہ جاتی ہیں گھروں میں بیٹھ رہیں۔ اللہ نے انکے دلوں پر مہر کر دی ہے۔ پس وہ سمجھتے ہی نہیں۔', 'راہ الزام کی تو ان پر ہے جو رخصت مانگتے ہیں تجھ سے اور وہ مالدار ہیں خوش ہوئے اس بات سے کہ رہ جائیں ساتھ پیچھے رہنے والیوں کے اور مہر کر دی اللہ نے انکے دلوں پر سو وہ نہیں جانتے [۱۰۴]', 'The ground (of complaint) is only against those who are rich, and yet ask exemption. They are content to be with (the women) who sit behind (at home) and Allah has sealed up their hearts (from all kinds of goodness and right guidance) so that they know not (what they are losing).', 'Blame lies, in fact, on those who ask you permission despite being rich. They are happy being with women who sit back. Allah has sealed their hearts; so they do not know.'),
(1329, 9, 94, 12, 1, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'یَعۡتَذِرُوۡنَ  اِلَیۡکُمۡ   اِذَا رَجَعۡتُمۡ  اِلَیۡہِمۡ ؕ قُلۡ لَّا تَعۡتَذِرُوۡا لَنۡ  نُّؤۡمِنَ  لَکُمۡ  قَدۡ نَبَّاَنَا اللّٰہُ مِنۡ  اَخۡبَارِکُمۡ ؕ وَ سَیَرَی اللّٰہُ عَمَلَکُمۡ  وَ رَسُوۡلُہٗ  ثُمَّ تُرَدُّوۡنَ  اِلٰی عٰلِمِ الۡغَیۡبِ وَ الشَّہَادَۃِ فَیُنَبِّئُکُمۡ بِمَا کُنۡتُمۡ تَعۡمَلُوۡنَ ﴿۹۴﴾', 'جب تم انکے پاس جاؤ گے تو تم سے عذر کریں گے تم کہنا کہ عذر مت کرو ہم ہر گز تمہاری بات نہیں مانیں گے اللہ نے ہم کو تمہارے سب حالات بتا دیئے ہیں۔ اور ابھی اللہ اور اس کا رسول تمہارے عمل کو دیکھیں گے پھر تم غائب و حاضر کے جاننے والے کی طرف لوٹائے جاؤگے تو جو عمل تم کرتے رہے ہو وہ سب تمہیں بتائے گا۔', 'بہانے لائیں گے تمہارے پاس جب تم پھر کر جاؤ گے ان کی طرف تو کہہ بہانے مت بناؤ ہم ہر گز نہ مانیں گے تمہاری بات ہم کو بتا چکا ہے اللہ تمہارے احوال اور ابھی دیکھے گا اللہ تمہارےکام اور اس کا رسول پھر تم لوٹائے جاؤ گے طرف اس جاننے والے چھپے اور کھلے کی سو وہ بتائے گا تم کو جو تم کر رہے تھے [۱۰۵]', 'They (the hypocrites) will present their excuses to you (Muslims), when you return to them. Say (O Muhammad SAW) \"Present no excuses, we shall not believe you. Allah has already informed us of the news concerning you. Allah and His Messenger will observe your deeds. In the end you will be brought back to the All-Knower of the unseen and the seen, then He (Allah) will inform you of what you used to do.\" (Tafsir At-Tabari)', 'They will make excuses to you when you return to them. Say, “Do not make excuses. We shall never believe you. Allah has told us the facts about you. Allah will see what you do, and His Messenger as well. Then you shall be returned to the Knower of the Seen and the Unseen, and He will tell you what you have been doing.”'),
(1330, 9, 95, 12, 1, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'سَیَحۡلِفُوۡنَ بِاللّٰہِ لَکُمۡ اِذَا انۡقَلَبۡتُمۡ اِلَیۡہِمۡ لِتُعۡرِضُوۡا عَنۡہُمۡ ؕ فَاَعۡرِضُوۡا عَنۡہُمۡ ؕ اِنَّہُمۡ  رِجۡسٌ ۫ وَّ مَاۡوٰىہُمۡ  جَہَنَّمُ ۚ جَزَآءًۢ  بِمَا کَانُوۡا یَکۡسِبُوۡنَ ﴿۹۵﴾', 'جب تم انکے پاس لوٹ کر جاؤ گے تو تمہارے روبرو اللہ کی قسمیں کھائیں گے تاکہ تم ان سے درگذر کرو سو انکی طرف توجہ نہ دینا یہ ناپاک ہیں اور جو کام یہ کرتے رہے ہیں انکے بدلے ان کا ٹھکانہ دوزخ ہے۔', 'اب قسمیں کھائیں گے اللہ کی تمہارے سامنے جب تم پھر کر جاؤ گے ان کی طرف تاکہ ان سے درگذر کرو سو تم درگذر کرو ان سے بیشک وہ لوگ پلید ہیں اور ان کا ٹھکانہ دوزخ ہے بدلا ان کے کاموں کا [۱۰۶]', 'They will swear by Allah to you (Muslims) when you return to them, that you may turn away from them. So turn away from them. Surely, they are Rijsun (i.e. Najasun (impure) because of their evil deeds), and Hell is their dwelling place, - a recompense for that which they used to earn.', 'They will swear by Allah before you when you will go back to them, so that you may ignore their misdeeds. So, just ignore them. They are filth, and their abode is Jahannam, a recompense for what they used to do.'),
(1331, 9, 96, 12, 1, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'یَحۡلِفُوۡنَ لَکُمۡ  لِتَرۡضَوۡا عَنۡہُمۡ ۚ فَاِنۡ تَرۡضَوۡا عَنۡہُمۡ فَاِنَّ اللّٰہَ  لَا  یَرۡضٰی عَنِ الۡقَوۡمِ  الۡفٰسِقِیۡنَ ﴿۹۶﴾', 'یہ تمہارے آگے قسمیں کھائیں گے تاکہ تم ان سے خوش ہو جاؤ لیکن اگر تم ان سے خوش ہو بھی جاؤ گے تو بھی اللہ نافرمان لوگوں سے خوش نہیں ہوتا۔', 'وہ لوگ قسمیں کھائیں گے تمہارے سامنے تاکہ تم ان سے راضی ہو جاؤ سو اگر تم راضی ہو گئے ان سے تو اللہ راضی نہیں ہوتا نافرمان لوگوں سے [۱۰۷]', 'They (the hypocrites) swear to you (Muslims) that you may be pleased with them, but if you are pleased with them, certainly Allah is not pleased with the people who are Al-Fasiqoon (rebellious, disobedient to Allah).', 'They swear before you, so that you may be pleased with them. So, even if you are pleased with them, Allah will not be pleased with the sinning people.'),
(1332, 9, 97, 12, 1, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'اَلۡاَعۡرَابُ اَشَدُّ کُفۡرًا وَّ نِفَاقًا وَّ اَجۡدَرُ اَلَّا یَعۡلَمُوۡا حُدُوۡدَ  مَاۤ  اَنۡزَلَ اللّٰہُ عَلٰی رَسُوۡلِہٖ ؕ وَ اللّٰہُ  عَلِیۡمٌ  حَکِیۡمٌ ﴿۹۷﴾', 'دیہاتی لوگ  پکے کافر اور پکے منافق ہیں اور ایسے ہیں کہ جو احکام شریعت اللہ نے اپنے رسول پر نازل فرمائے ہیں ان سے واقف ہی نہ ہو پائیں۔ اور اللہ جاننے والا ہے حکمت والا ہے۔', 'گنوار بہت سخت ہیں کفر میں اور نفاق میں اور اسی لائق ہیں کہ نہ سیکھیں وہ قاعدے جو نازل کئے اللہ نے اپنے رسول پر [۱۰۸] اور اللہ سب کچھ جاننے والا حکمت والا ہے [۱۰۹]', 'The bedouins are the worst in disbelief and hypocrisy, and more likely to be in ignorance of the limits (Allahs Commandments and His Legal Laws, etc.) which Allah has revealed to His Messenger. And Allah is All-Knower, All-Wise.', 'The Bedouins are often more strict in disbelief and hypocrisy, and are most likely to be ignorant of the limits of what Allah has sent down to His Messenger. Allah is All-Knowing, All-Wise.'),
(1333, 9, 98, 12, 1, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'وَ مِنَ الۡاَعۡرَابِ مَنۡ یَّتَّخِذُ مَا یُنۡفِقُ مَغۡرَمًا وَّ یَتَرَبَّصُ بِکُمُ الدَّوَآئِرَ ؕ عَلَیۡہِمۡ دَآئِرَۃُ  السَّوۡءِ ؕ وَ اللّٰہُ سَمِیۡعٌ عَلِیۡمٌ ﴿۹۸﴾', 'اور بعض دیہاتی ایسے ہیں کہ جو کچھ خرچ کرتے ہیں اسے تاوان سمجھتے ہیں اور تمہارے حق میں مصیبتوں کے منتظر ہیں۔ انہی پر بری مصیبت واقع ہو۔ اور اللہ سننے والا ہے جاننے والا ہے۔', 'اور بعضے گنوار ایسے ہیں کہ شمار کرتے ہیں اپنے خرچ کرنے کو تاوان اور انتظار کرتے ہیں تم پر زمانہ کی گردشوں کا ان ہی پر آئے گردش بری اور اللہ سننے والا جاننے والا ہے [۱۱۰]', 'And of the bedouins there are some who look upon what they spend (in Allahs Cause) as a fine and watch for calamities for you, on them be the calamity of evil. And Allah is All-Hearer, All-Knower.', 'And among the Bedouins there are those who take what they spend as a fine, and they look forward to the cycles of time to turn against you. Upon those is the evil cycle. And Allah is All-Hearing, All-Knowing.'),
(1334, 9, 99, 12, 1, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'وَ مِنَ الۡاَعۡرَابِ مَنۡ یُّؤۡمِنُ بِاللّٰہِ وَ الۡیَوۡمِ الۡاٰخِرِ  وَ یَتَّخِذُ مَا یُنۡفِقُ قُرُبٰتٍ عِنۡدَ اللّٰہِ وَ صَلَوٰتِ الرَّسُوۡلِ ؕ اَلَاۤ اِنَّہَا قُرۡبَۃٌ  لَّہُمۡ ؕ سَیُدۡخِلُہُمُ اللّٰہُ  فِیۡ رَحۡمَتِہٖ ؕ اِنَّ اللّٰہَ  غَفُوۡرٌ  رَّحِیۡمٌ  ﴿٪۹۹﴾', 'اور بعض دیہاتی ایسے ہیں کہ اللہ پر اور روز آخر پر ایمان رکھتے ہیں اور جو کچھ خرچ کرتے ہیں اسکو اللہ کے قرب اور پیغمبر کی دعاؤں کا ذریعہ سمجھتے ہیں۔ دیکھو یہ بات بلاشبہ انکے لئے موجب قرب ہے۔ اللہ انکو عنقریب اپنی رحمت میں داخل کرے گا۔ بیشک اللہ بخشنے  والا ہے مہربان ہے۔', 'اور بعضے گنوار وہ ہیں کہ ایمان لاتے ہیں اللہ پر اور قیامت کے دن پر اور شمار کرتے ہیں اپنے خرچ کرنے کو نزدیک ہونا اللہ سے اور دعا لینی رسول کی سنتا ہے وہ ان کے حق میں نزدیکی ہے داخل کرے گا انکو اللہ اپنی رحمت میں بیشک اللہ بخشننے والا مہربان ہے [۱۱۱]', 'And of the bedouins there are some who believe in Allah and the Last Day, and look upon what they spend in Allahs Cause as approaches to Allah, and a cause of receiving the Messengers invocations. Indeed these (spendings in Allahs Cause) are an approach for them. Allah will admit them to His Mercy. Certainly Allah is Oft-Forgiving, Most Merciful.', 'And among the Bedouins there are others who believe in Allah and in the Last Day and take what they spend as a source of nearness to Allah and of prayers from the Messenger. It is indeed a source of nearness for them. Allah will admit them to His mercy. Surely, Allah is Most Forgiving, Very Merciful.'),
(1335, 9, 100, 13, 2, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'وَ السّٰبِقُوۡنَ الۡاَوَّلُوۡنَ  مِنَ الۡمُہٰجِرِیۡنَ وَ الۡاَنۡصَارِ وَ الَّذِیۡنَ اتَّبَعُوۡہُمۡ بِاِحۡسَانٍ ۙ رَّضِیَ اللّٰہُ عَنۡہُمۡ وَ رَضُوۡا عَنۡہُ وَ اَعَدَّ لَہُمۡ جَنّٰتٍ تَجۡرِیۡ تَحۡتَہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَاۤ  اَبَدًا ؕ ذٰلِکَ الۡفَوۡزُ الۡعَظِیۡمُ ﴿۱۰۰﴾', 'جن لوگوں نے سبقت کی یعنی سب سے پہلے ایمان لائے مہاجرین میں سے بھی اور انصار میں سے بھی اور جنہوں نے نیکوکاری کے ساتھ انکی پیروی کی اللہ ان سے خوش ہے اور وہ اللہ سے خوش ہیں اور اس نے انکے لئے باغات تیار کئے ہیں جنکے نیچے نہریں بہ رہی ہیں  وہ ہمیشہ ان میں رہیں گے۔ یہی بڑی کامیابی ہے۔', 'اور جو لوگ قدیم ہیں سب سے پہلے ہجرت کرنے والے اور مدد کرنے والے اور جو انکے پیرو ہوئے نیکی کے ساتھ اللہ راضی ہوا ان سے اور وہ راضی ہوئے اس سے اور تیار کر رکھے ہیں واسطے انکے باغ کہ بہتی ہیں نیچے ان کےنہریں رہا کریں انہی میں ہمیشہ یہی ہے بڑی کامیابی [۱۱۲]', 'And the first to embrace Islam of the Muhajiroon (those who migrated from Makkah to Al-Madinah) and the Ansar (the citizens of Al-Madinah who helped and gave aid to the Muhajiroon) and also those who followed them exactly (in Faith). Allah is well-pleased with them as they are well-pleased with Him. He has prepared for them Gardens under which rivers flow (Paradise), to dwell therein forever. That is the supreme success.', 'As for the first and foremost of the Emigrants (Muhājirīn) and the Supporters (AnSār) and those who followed them in goodness, Allah is pleased with them and they are pleased with Allah, and He has prepared for them gardens beneath which rivers flow, where they will live for ever. That is the supreme achievement.'),
(1336, 9, 101, 13, 2, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'وَ مِمَّنۡ حَوۡلَکُمۡ مِّنَ الۡاَعۡرَابِ مُنٰفِقُوۡنَ ؕۛ وَ مِنۡ اَہۡلِ الۡمَدِیۡنَۃِ ۟ۛؔ مَرَدُوۡا عَلَی النِّفَاقِ ۟ لَا  تَعۡلَمُہُمۡ ؕ نَحۡنُ نَعۡلَمُہُمۡ ؕ سَنُعَذِّبُہُمۡ مَّرَّتَیۡنِ ثُمَّ  یُرَدُّوۡنَ  اِلٰی  عَذَابٍ  عَظِیۡمٍ ﴿۱۰۱﴾ۚ', 'اور تمہارے گردونواح کے بعض دیہاتی بھی منافق ہیں اور بعض مدینے والے بھی نفاق پر اڑے ہوئے ہیں تم انہیں نہیں جانتے ہم جانتے ہیں۔ ہم انکو دہرا عذاب دیں گے۔ پھر وہ بڑے عذاب کی طرف لوٹائے جائیں گے۔', 'اور بعضے تمہارے گرد کے گنوار منافق ہیں اور بعضے لوگ مدینہ والے اڑ رہے ہیں نفاق پر تو انکو نہیں جانتا ہم کو وہ معلوم ہیں [۱۱۳] انکو ہم عذاب دیں گے دو بار پھر وہ لوٹائے جائیں گے بڑے عذاب کی طرف [۱۱۴]', 'And among the bedouins round about you, some are hypocrites, and so are some among the people of Al-Madinah, they exaggerate and persist in hypocrisy, you (O Muhammad SAW) know them not, We know them. We shall punish them twice, and thereafter they shall be brought back to a great (horrible) torment.', 'And among those Bedouins who are around you there are hypocrites, and among the people of Madīnah as well. They are adamant on hypocrisy. You do not know them. We know them. We will chastise them twice, then they shall be driven to a terrible punishment (in the Hereafter).'),
(1337, 9, 102, 13, 2, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'وَ اٰخَرُوۡنَ اعۡتَرَفُوۡا بِذُنُوۡبِہِمۡ خَلَطُوۡا عَمَلًا صَالِحًا وَّ اٰخَرَ  سَیِّئًا ؕ عَسَی اللّٰہُ اَنۡ یَّتُوۡبَ عَلَیۡہِمۡ ؕ اِنَّ اللّٰہَ غَفُوۡرٌ رَّحِیۡمٌ ﴿۱۰۲﴾', 'اور کچھ دوسرے لوگ ہیں کہ اپنے گناہوں کا صاف اقرار کرتے ہیں۔ انہوں نے اچھے اور برے عملوں کو ملا جلا دیا تھا۔ قریب ہے کہ اللہ ان پر مہربانی سے توجہ فرمائے۔ بیشک اللہ بخشنے والا ہے مہربان ہے۔', 'اور بعضے لوگ ہیں کہ اقرار کیا انہوں نے اپنے گناہوں کا ملایا انہوں نے ایک کام نیک اور دوسرا بد قریب ہے کہ اللہ معاف کرے انکو بیشک اللہ بخشنے والا مہربان ہے [۱۱۵]', 'And (there are) others who have acknowledged their sins, they have mixed a deed that was righteous with another that was evil. Perhaps Allah will turn unto them in forgiveness. Surely, Allah is Oft-Forgiving, Most Merciful.', 'And there are others who admitted their sins while they had mixed a good deed with an evil one. It is likely that Allah will relent towards them. Surely, Allah is Most-Forgiving, Very-Merciful.'),
(1338, 9, 103, 13, 2, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'خُذۡ مِنۡ اَمۡوَالِہِمۡ صَدَقَۃً  تُطَہِّرُہُمۡ وَ تُزَکِّیۡہِمۡ بِہَا وَ صَلِّ عَلَیۡہِمۡ ؕ اِنَّ صَلٰوتَکَ سَکَنٌ لَّہُمۡ ؕ وَ اللّٰہُ سَمِیۡعٌ عَلِیۡمٌ ﴿۱۰۳﴾', 'انکے مال میں سے زکوٰۃ قبول کر لو کہ اس سے تم انکو ظاہر میں بھی پاک اور باطن میں بھی پاکیزہ کرتے ہو اور انکے حق میں دعائے خیر کرو کہ تمہاری دعا انکے لئے موجب تسکین ہے اور اللہ سننے والا ہے جاننے والا ہے۔', 'لے انکے مال میں سے زکوٰۃ [۱۱۶] کہ پاک کرے تو انکو اور بابرکت کرے تو انکو اسکی وجہ سے اور دعا دے انکو بیشک تیری دعا ان کے لئے تسکین ہے اور اللہ سب کچھ سنتا جانتا ہے [۱۱۷]', 'Take Sadaqah (alms) from their wealth in order to purify them and sanctify them with it, and invoke Allah for them. Verily! Your invocations are a source of security for them, and Allah is All-Hearer, All-Knower.', 'Take Sadaqah (obligatory alms) out of their wealth through which you may cleanse and purify them, and pray for them. Indeed, your prayer is a source of peace for them. And Allah is (All-) Hearing, (All-) Knowing.'),
(1339, 9, 104, 13, 2, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'اَلَمۡ  یَعۡلَمُوۡۤا اَنَّ اللّٰہَ ہُوَ  یَقۡبَلُ التَّوۡبَۃَ عَنۡ عِبَادِہٖ وَ یَاۡخُذُ الصَّدَقٰتِ وَ اَنَّ اللّٰہَ ہُوَ  التَّوَّابُ  الرَّحِیۡمُ ﴿۱۰۴﴾', 'کیا یہ لوگ نہیں جانتے کہ اللہ ہی اپنے بندوں سے توبہ قبول فرماتا ہے اور صدقات و خیرات لیتا ہے اور یہ کہ اللہ ہی توبہ قبول کرنے والا ہے مہربان ہے۔', 'کیا وہ جان نہیں چکے کہ اللہ آپ قبول کرتا ہے توبہ اپنے بندوں سے اور لیتا ہے زکوٰتیں اور یہ کہ اللہ ہی توبہ قبول کرنے والا مہربان ہے [۱۱۸]', 'Know they not that Allah accepts repentance from His slaves and takes the Sadaqat (alms, charities) and that All&achrc;h Alone is the One Who forgives and accepts repentance, Most Merciful?', 'Have they not come to know that Allah is He who accepts repentance from His slaves and accepts Sadaqāt, and that Allah is Most-Relenting, Very-Merciful.'),
(1340, 9, 105, 13, 2, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'وَ قُلِ اعۡمَلُوۡا فَسَیَرَی اللّٰہُ عَمَلَکُمۡ وَ رَسُوۡلُہٗ  وَ الۡمُؤۡمِنُوۡنَ ؕ وَ سَتُرَدُّوۡنَ  اِلٰی عٰلِمِ الۡغَیۡبِ وَ الشَّہَادَۃِ فَیُنَبِّئُکُمۡ بِمَا کُنۡتُمۡ  تَعۡمَلُوۡنَ ﴿۱۰۵﴾ۚ', 'اور ان سے کہہ دو کہ عمل کئے جاؤ۔ اللہ اور اس کا رسول اور مومن سب تمہارے عمل کو دیکھ لیں گے۔ اور تم غائب و حاضر کے جاننے والے کی طرف لوٹائے جاؤ گے۔ پھر جو کچھ تم کرتے رہے ہو وہ سب تم کو بتا دے گا۔', 'اور کہہ کہ عمل کئے جاؤ پھر آگے دیکھ لے گا اللہ تمہارے کام کو اور اس کا رسول اور مسلمان اور تم جلد لوٹائے جاؤ گے اسکے پاس جو تمام چھپی اور کھلی چیزوں سے واقف ہے پھر وہ جتا دے گا تم کو جو کچھ تم کرتے تھے [۱۱۹]', 'And say (O Muhammad SAW) \"Do deeds! Allah will see your deeds, and (so will) His Messenger and the believers. And you will be brought back to the All-Knower of the unseen and the seen. Then He will inform you of what you used to do.\"', 'Say, “Do (what you do); Allah will see your deed, as will the Messenger and the believers. And you shall be returned to the Knower of the Seen and the Unseen, then He will tell you what you have been doing.”'),
(1341, 9, 106, 13, 2, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'وَ اٰخَرُوۡنَ مُرۡجَوۡنَ لِاَمۡرِ اللّٰہِ اِمَّا یُعَذِّبُہُمۡ وَ اِمَّا یَتُوۡبُ عَلَیۡہِمۡ ؕ وَ اللّٰہُ عَلِیۡمٌ  حَکِیۡمٌ ﴿۱۰۶﴾', 'اور کچھ دوسرے لوگ ہیں جنکا کام اللہ کے حکم پر موقوف ہے۔ چاہے وہ انکو عذاب دے اور چاہے معاف کر دے۔ اور اللہ جاننے والا ہے حکمت والا ہے۔', 'اور بعضے اور لوگ ہیں کہ انکا کام ڈھیل میں ہے حکم پر اللہ کے یا وہ انکو عذاب دے اور یا انکو معاف کرے اور اللہ سب کچھ جاننے والا حکمت والا ہے [۱۲۰]', 'And others await Allahs Decree, whether He will punish them or will forgive them. And Allah is All-Knowing, All-Wise.', 'And there are others whose matter is deferred till the command of Allah (comes): either He would punish them or relent towards them. Allah is All-Knowing, All-Wise.'),
(1342, 9, 107, 13, 2, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'وَ الَّذِیۡنَ اتَّخَذُوۡا مَسۡجِدًا ضِرَارًا وَّ کُفۡرًا وَّ تَفۡرِیۡقًۢا بَیۡنَ الۡمُؤۡمِنِیۡنَ وَ اِرۡصَادًا لِّمَنۡ حَارَبَ اللّٰہَ وَ رَسُوۡلَہٗ  مِنۡ قَبۡلُ ؕ وَ لَیَحۡلِفُنَّ اِنۡ اَرَدۡنَاۤ اِلَّا الۡحُسۡنٰی ؕ وَ اللّٰہُ یَشۡہَدُ  اِنَّہُمۡ  لَکٰذِبُوۡنَ ﴿۱۰۷﴾', 'اور ان میں ایسے بھی ہیں جنہوں نے اس غرض سے مسجد بنائی ہے کہ ضرر پہنچائیں اور کفر کریں اور مومنوں میں تفرقہ ڈالیں اور جو لوگ اللہ اور اسکے رسول سے اس سے پہلے جنگ کر چکے ہیں انکے لئے گھات کی جگہ بنائیں۔ اور قسمیں کھائیں گے کہ ہمارا مقصود تو صرف بھلائی تھا مگر اللہ گواہی دیتا ہے کہ یہ جھوٹے ہیں۔', 'اور جنہوں نے بنائی ہے ایک مسجد ضد پر اور کفر پر اور پھوٹ ڈالنے کو مسلمانوں میں اور گھات لگانے کو اس شخص کی جو لڑ رہا ہے اللہ سے اور اسکے رسول سے پہلے سے اور وہ قسمیں کھائیں گے کہ ہم نے تو بھلائی ہی چاہی تھی اور اللہ گواہ ہے کہ وہ جھوٹے ہیں [۱۲۱]', 'And as for those who put up a mosque by way of harming and disbelief, and to disunite the believers, and as an outpost for those who warred against Allah and His Messenger (Muhammad SAW) aforetime, they will indeed swear that their intention is nothing but good. Allah bears witness that they are certainly liars.', 'And (there are) those who have built a mosque to cause harm (to Islam) and to promote infidelity and to create dissention among the believers and to provide a station for one who has been at war with Allah and His Messenger even before. They will certainly swear (and say), “We intended to do nothing but good.” Allah testifies that they are liars'),
(1343, 9, 108, 13, 2, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'لَا تَقُمۡ  فِیۡہِ اَبَدًا ؕ لَمَسۡجِدٌ اُسِّسَ عَلَی التَّقۡوٰی مِنۡ اَوَّلِ  یَوۡمٍ اَحَقُّ  اَنۡ تَقُوۡمَ فِیۡہِ ؕ فِیۡہِ  رِجَالٌ یُّحِبُّوۡنَ اَنۡ یَّتَطَہَّرُوۡا ؕ وَ اللّٰہُ یُحِبُّ الۡمُطَّہِّرِیۡنَ ﴿۱۰۸﴾', 'تم اس مسجد میں کبھی جا کر کھڑے بھی نہ ہونا۔ البتہ وہ مسجد جسکی بنیاد پہلے دن سے تقوٰی پر رکھی گئ ہے اس قابل ہے کہ اس میں جایا اور نماز پڑھایا کرو اس میں ایسے لوگ ہیں جو پاک رہنے کو پسند کرتے ہیں اور اللہ پاک رہنے والوں کو پسند کرتا ہے۔', 'تو نہ کھڑا ہو اس میں کبھی البتہ وہ مسجد جسکی بنیاد دھری گئ پرہیزگاری پر اول دن سے وہ لائق ہے کہ تو کھڑا ہو اسمیں اس میں ایسےلوگ ہیں جو دوست رکھتے ہیں پاک رہنے کو اور اللہ دوست رکھتا ہے پاک رہنے والوں کو [۱۲۲]', 'Never stand you therein. Verily, the mosque whose foundation was laid from the first day on piety is more worthy that you stand therein (to pray). In it are men who love to clean and to purify themselves. And Allah loves those who make themselves clean and pure (i.e. who clean their private parts with dust (i.e. to be considered as soap) and water from urine and stools, after answering the call of nature).', 'Do not ever stand there (in prayer). In fact, the mosque that was founded on Taqwā (piety) from the very first day has greater right that you stand in it. In it there are people who like to observe purity; and Allah loves those observing purity.'),
(1344, 9, 109, 13, 2, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'اَفَمَنۡ اَسَّسَ بُنۡیَانَہٗ عَلٰی تَقۡوٰی مِنَ اللّٰہِ وَ رِضۡوَانٍ خَیۡرٌ اَمۡ مَّنۡ اَسَّسَ بُنۡیَانَہٗ عَلٰی شَفَا جُرُفٍ ہَارٍ فَانۡہَارَ بِہٖ فِیۡ نَارِ جَہَنَّمَ ؕ وَ اللّٰہُ  لَا یَہۡدِی الۡقَوۡمَ  الظّٰلِمِیۡنَ ﴿۱۰۹﴾', 'بھلا جس شخص نے اپنی عمارت کی بنیاد اللہ کے خوف اور اسکی رضامندی پر رکھی وہ اچھا ہے یا وہ جس نے اپنی عمارت کی بنیاد ایک کھائی کے گرنے والے کنارے پر رکھی پھر وہ اسکو دوزخ کی آگ میں لے گرا۔ اور اللہ ظالم لوگوں کو ہدایت نہیں دیتا۔', 'بھلا جس نے بنیاد رکھی اپنی عمارت کی اللہ سے ڈرنے پر اور اسکی رضامندی پر وہ بہتر یا جس نے بنیاد رکھی اپنی عمارت کی کنارہ پر ایک کھائی کے جو گرنے کو ہے پھر اسکو لیکر ڈھے پڑا دوزخ کی آگ میں [۱۲۳] اور اللہ راہ نہیں دیتا ظالم لوگوں کو [۱۲۴]', 'Is it then he, who laid the foundation of his building on piety to Allah and His Good Pleasure, better, or he who laid the foundation of his building on an undetermined brink of a precipice ready to crumble down, so that it crumbled to pieces with him into the Fire of Hell. And Allah guides not the people who are the Zalimoon (cruel, violent, proud, polytheist and wrong-doer).', 'Then tell me, which one is better, whether the one who has founded his building on fear of Allah and on search of His pleasure, or the one who has founded his building on the edge of an abyss that is about to collapse, then it did collapse with him into the fire of Jahannam ? Allah does not give guidance to the unjust people.'),
(1345, 9, 110, 13, 2, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'لَا یَزَالُ بُنۡیَانُہُمُ الَّذِیۡ بَنَوۡا رِیۡبَۃً  فِیۡ قُلُوۡبِہِمۡ  اِلَّاۤ  اَنۡ تَقَطَّعَ قُلُوۡبُہُمۡ ؕ وَ اللّٰہُ عَلِیۡمٌ  حَکِیۡمٌ ﴿۱۱۰﴾٪', 'یہ عمارت جو انہوں نے بنائی ہے ہمیشہ انکے دلوں میں موجب تردد رہے گی مگر یہ کہ انکے دل پاش پاش ہو جائیں اور اللہ جاننے والا ہے حکمت والا ہے۔', 'ہمیشہ رہے گا اس عمارت سے جو انہوں نے بنائی تھی شبہ انکے دلوں میں مگر جب ٹکڑے ہو جائیں انکے دل کے اور اللہ سب کچھ جاننے والا حکمت والا ہے [۱۲۵]', 'The building which they built will never cease to be a cause of hypocrisy and doubt in their hearts, unless their hearts are cut to pieces. (i.e. till they die). And Allah is All-Knowing, All-Wise.', 'The building they had built shall always remain a source of unrest in their hearts, unless their hearts are cut into pieces. Allah is All-Knowing, All-Wise.'),
(1346, 9, 111, 14, 3, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'اِنَّ اللّٰہَ اشۡتَرٰی مِنَ الۡمُؤۡمِنِیۡنَ اَنۡفُسَہُمۡ وَ اَمۡوَالَہُمۡ بِاَنَّ لَہُمُ الۡجَنَّۃَ ؕ یُقَاتِلُوۡنَ فِیۡ سَبِیۡلِ اللّٰہِ فَیَقۡتُلُوۡنَ وَ یُقۡتَلُوۡنَ ۟ وَعۡدًا عَلَیۡہِ حَقًّا فِی التَّوۡرٰىۃِ وَ الۡاِنۡجِیۡلِ وَ الۡقُرۡاٰنِ ؕ وَ مَنۡ اَوۡفٰی بِعَہۡدِہٖ مِنَ اللّٰہِ فَاسۡتَبۡشِرُوۡا بِبَیۡعِکُمُ الَّذِیۡ بَایَعۡتُمۡ بِہٖ ؕ وَ  ذٰلِکَ ہُوَ الۡفَوۡزُ  الۡعَظِیۡمُ ﴿۱۱۱﴾', 'اللہ نے مومنوں سے انکی جانیں اور ان کے مال خرید لئے ہیں اور اسکے عوض انکے لئے بہشت تیار کی ہے۔ یہ لوگ اللہ کی راہ میں لڑتے ہیں تو مارتے بھی ہیں اور مارے بھی جاتے ہیں۔ یہ تورات اور انجیل اور قرآن میں سچا وعدہ ہے جس کا پورا کرنا اسے ضرور ہے اور اللہ سے زیادہ وعدہ پورا کرنے والا کون ہے؟ تو جو سودا تم نے اس سے کیا ہے اس سے خوش رہو۔ اور یہی بڑی کامیابی ہے۔', 'اللہ نے خرید لی مسلمانوں سے ان کی جان اور ان کا مال اس قیمت پر کہ انکے لئے جنت ہے لڑتے ہیں اللہ کی راہ میں پھر مارتے ہیں اور مرتے ہیں وعدہ ہو چکا اسکے ذمہ پر سچا توریت اور انجیل اور قرآن میں اور کون ہے قول کا پورا اللہ سے زیادہ سو خوشیاں کرو اس معاملہ پر جو تم نے کیا ہے اس سے اور یہ یہی ہے بڑی کامیابی [۱۲۶]', 'Verily, Allah has purchased of the believers their lives and their properties; for the price that theirs shall be the Paradise. They fight in Allahs Cause, so they kill (others) and are killed. It is a promise in truth which is binding on Him in the Taurat (Torah) and the Injeel (Gospel) and the Quran. And who is truer to his covenant than Allah? Then rejoice in the bargain which you have concluded. That is the supreme success.', 'Surely, Allah has bought their lives and their wealth from the believers, in exchange of (a promise) that Paradise shall be theirs. They fight in the way of Allah, and kill and are killed, on which there is a true promise (as made) in the Torah and the Injīl and the Qur’ān. And who can be more faithful to his covenant than Allah? So, rejoice in the deal you have made, and that is the great achievement.'),
(1347, 9, 112, 14, 3, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'اَلتَّآئِبُوۡنَ الۡعٰبِدُوۡنَ الۡحٰمِدُوۡنَ السَّآئِحُوۡنَ الرّٰکِعُوۡنَ السّٰجِدُوۡنَ الۡاٰمِرُوۡنَ بِالۡمَعۡرُوۡفِ وَ النَّاہُوۡنَ عَنِ الۡمُنۡکَرِ وَ الۡحٰفِظُوۡنَ لِحُدُوۡدِ اللّٰہِ ؕ وَ بَشِّرِ  الۡمُؤۡمِنِیۡنَ ﴿۱۱۲﴾', 'توبہ کرنے والے۔ عبادت کرنے والے۔ حمد کرنے والے۔ روزہ رکھنے والے۔ رکوع کرنے والے۔ سجدہ کرنے والے۔ نیک کاموں کا امر کرنے والے اور بری باتوں سے منع کرنے والے۔ اللہ کی حدوں کی حفاظت کرنے والے۔ یہی مومن لوگ ہیں اور اے پیغمبر مومنوں کو بہشت کی خوشخبری سنا دو۔', 'وہ توبہ کرنے والے ہیں بندگی کرنے والے شکر کرنے والے بے تعلق رہنے والے [۱۲۷] رکوع کرنے والے سجدہ کرنے والے حکم کرنے والے نیک بات کا اور منع کرنے والے بری بات سے [۱۲۸] اور حفاظت کرنے والے ان حدود کی جو باندھی اللہ نے اور خوشخبری سنا دے ایمان والوں کو [۱۲۹]', '(The believers whose lives Allah has purchased are) those who repent to Allah (from polytheism and hypocrisy, etc.), who worship Him, who praise Him, who fast (or go out in Allahs Cause), who bow down (in prayer), who prostrate themselves (in prayer), who enjoin (people) for Al-Maroof (i.e. Islamic Monotheism and all what Islam has ordained) and forbid (people) from Al-Munkar (i.e. disbelief, polytheism of all kinds and all that Islam has forbidden), and who observe the limits set by Allah (do all that Allah has ordained and abstain from all kinds of sins and evil deeds which Allah has forbidden). And give glad tidings to the believers.', '(They are) those who repent, those who worship, those who praise (Allah), those who journey (in Allah’s way), those who bow in Rukū‘, those who prostrate in sajdah, those who bid the Fair and forbid the Unfair and those who preserve the limits prescribed by Allah. And give the good news to the believers.'),
(1348, 9, 113, 14, 3, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'مَا کَانَ لِلنَّبِیِّ وَ الَّذِیۡنَ اٰمَنُوۡۤا اَنۡ یَّسۡتَغۡفِرُوۡا لِلۡمُشۡرِکِیۡنَ وَ لَوۡ  کَانُوۡۤا  اُولِیۡ  قُرۡبٰی مِنۡۢ بَعۡدِ مَا تَبَیَّنَ لَہُمۡ اَنَّہُمۡ اَصۡحٰبُ  الۡجَحِیۡمِ ﴿۱۱۳﴾', 'پیغمبر اور مسلمانوں کو شایاں نہیں کہ جب ان پر ظاہر ہو گیا کہ مشرک اہل دوزخ ہیں تو انکے لئے بخشش مانگیں گو وہ انکے قرابت دار ہی ہوں۔', 'لائق نہیں نبی کو اور مسلمانوں کو کہ بخشش چاہیں مشرکوں کی اور اگرچہ وہ ہوں قرابت والے جب کہ کھل چکا ان پر کہ وہ ہیں دوزخ والے [۱۳۰]', 'It is not (proper) for the Prophet and those who believe to ask Allahs Forgiveness for the Mushrikoon (polytheists, idolaters, pagans, disbelievers in the Oneness of Allah) even though they be of kin, after it has become clear to them that they are the dwellers of the Fire (because they died in a state of disbelief).', 'It is not (permissible) for the Prophet and the believers to seek forgiveness for the Mushriks, even if they are kinsmen, after it became clear to them that they are the people of hell.'),
(1349, 9, 114, 14, 3, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'وَ مَا کَانَ اسۡتِغۡفَارُ  اِبۡرٰہِیۡمَ لِاَبِیۡہِ  اِلَّا عَنۡ مَّوۡعِدَۃٍ  وَّعَدَہَاۤ اِیَّاہُ ۚ فَلَمَّا تَبَیَّنَ لَہٗۤ  اَنَّہٗ عَدُوٌّ  لِّلّٰہِ  تَبَرَّاَ  مِنۡہُ ؕ اِنَّ اِبۡرٰہِیۡمَ  لَاَوَّاہٌ  حَلِیۡمٌ ﴿۱۱۴﴾', 'اور ابراہیم کا اپنے باپ کے لئے بخشش مانگنا تو ایک وعدے کے سبب تھا جو وہ اس سے کر چکے تھے لیکن جب انکو معلوم ہو گیا کہ وہ اللہ کا دشمن ہے تو اس سے بیزار ہو گئے۔ کچھ شک نہیں کہ ابراہیم بڑے نرم دل اور متحمل تھے۔', 'اور بخشش مانگنا ابراہیم کا اپنے باپ کے واسطے سو نہ تھا مگر وعدہ کے سبب  کہ وعدہ کر چکا تھا اس سے پھر جب کھل گیا ابراہیم پر کہ وہ دشمن ہے اللہ کا تو اس سے بیزار ہو گیا بیشک ابراہیم بڑا نرم دل تھا تحمل کرنے والا [۱۳۱]', 'And (Ibraheems (Abraham)) invoking (of Allah) for his fathers forgiveness was only because of a promise he (Ibraheem (Abraham)) had made to him (his father). But when it became clear to him (Ibraheem (Abraham)) that he (his father) is an enemy to Allah, he dissociated himself from him. Verily Ibraheem (Abraham) was Al-Awwah (has fifteen different meanings but the correct one seems to be that he used to invoke Allah with humility, glorify Him and remember Him much), and was forbearing. (Tafsir Al-Qurtubee).', 'As for the prayer of Ibrāhīm for the forgiveness of his father, it was only due to a promise he had made to him. Later, when it became clear to him that he was an enemy of Allah, he withdrew himself from him. Indeed, Ibrāhīm was very tender-hearted, very forbearing.'),
(1350, 9, 115, 14, 3, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'وَ مَا کَانَ اللّٰہُ لِیُضِلَّ قَوۡمًۢا بَعۡدَ اِذۡ ہَدٰىہُمۡ حَتّٰی  یُبَیِّنَ  لَہُمۡ مَّا یَتَّقُوۡنَ ؕ اِنَّ  اللّٰہَ  بِکُلِّ  شَیۡءٍ عَلِیۡمٌ ﴿۱۱۵﴾', 'اور اللہ ایسا نہیں کہ کسی قوم کو ہدایت دینے کے بعد گمراہ کر دے جب تک ان کو وہ چیز نہ بتا دے جس سے وہ پرہیز کریں۔ بیشک اللہ ہر چیز سے واقف ہے۔', 'اور اللہ ایسا نہیں کہ گمراہ کرے کسی قوم کو جبکہ ان کو راہ پر لا چکا جب تک کھول نہ دے ان پر جس سے انکو بچنا چاہئے بیشک اللہ ہر چیز سے واقف ہے [۱۳۲]', 'And Allah will never lead a people astray after He has guided them until He makes clear to them as to what they should avoid. Verily, Allah is the All-Knower of everything.', 'Allah is not such as He makes a people go astray after He has given them guidance, unless He explains to them what they should avoid. Indeed, Allah is fully aware of every thing.'),
(1351, 9, 116, 14, 3, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'اِنَّ اللّٰہَ لَہٗ  مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ یُحۡیٖ وَ یُمِیۡتُ ؕ وَ مَا لَکُمۡ مِّنۡ دُوۡنِ اللّٰہِ  مِنۡ  وَّلِیٍّ  وَّ لَا  نَصِیۡرٍ ﴿۱۱۶﴾', 'اللہ ہی ہے جسکے لئے آسمانوں اور زمین کی بادشاہت ہے وہی زندگانی بخشتا وہی موت دیتا ہے اور اللہ کے سوا تمہارا کوئی دوست اور مددگار نہیں ہے۔', 'اللہ ہی کی ہے سلطنت ہے آسمانوں اور زمین میں جلاتا ہے اور مارتا ہے اور تمہارا کوئی نہیں اللہ کے سوا حمایتی اور نہ مددگار [۱۳۳]', 'Verily, Allah! Unto Him belongs the dominion of the heavens and the earth, He gives life and He causes death. And besides Allah you have neither any Walee (protector or guardian) nor any helper.', 'Surely, to Allah alone belongs the kingdom of the heavens and the earth. He gives life and brings death. And, other than Allah, you have neither a supporter, nor a helper.'),
(1352, 9, 117, 14, 3, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'لَقَدۡ تَّابَ اللّٰہُ عَلَی النَّبِیِّ وَ الۡمُہٰجِرِیۡنَ وَ الۡاَنۡصَارِ الَّذِیۡنَ اتَّبَعُوۡہُ فِیۡ سَاعَۃِ الۡعُسۡرَۃِ مِنۡۢ بَعۡدِ مَا کَادَ یَزِیۡغُ قُلُوۡبُ فَرِیۡقٍ مِّنۡہُمۡ ثُمَّ  تَابَ عَلَیۡہِمۡ ؕ اِنَّہٗ بِہِمۡ رَءُوۡفٌ  رَّحِیۡمٌ ﴿۱۱۷﴾ۙ', 'بیشک اللہ نے پیغمبر پر مہربانی کی اور مہاجرین اور انصار پر جو باوجود اسکے کہ ان میں سے بعضوں کے دل پھر جانے کو تھے مشکل کی گھڑی میں پیغمبر کے ساتھ رہے۔ پھر اللہ نے ان پر مہربانی فرمائی۔ بیشک وہ ان پر نہایت شفقت کرنے والا ہے بڑا مہربان ہے۔', 'اللہ مہربان ہوا نبی پر اور مہاجرین اور انصار پر جو ساتھ رہے نبی کے مشکل کی گھڑی میں [۱۳۴] بعد اسکے کہ قریب تھا کہ دل پھر جائیں بعضوں کے ان میں سے پھر مہربان ہوا ان پر بیشک وہ ان پر مہربان ہے رحم کرنے والا [۱۳۵]', 'Allah has forgiven the Prophet (SAW), the Muhajiroon (Muslim emigrants who left their homes and came to Al-Madinah) and the Ansar (Muslims of Al-Madinah) who followed him (Muhammad SAW) in the time of distress (Tabook expedition, etc.), after the hearts of a party of them had nearly deviated (from the Right Path), but He accepted their repentance. Certainly, He is unto them full of Kindness, Most Merciful.', 'Surely, Allah has relented towards the Prophet and the Emigrants (Muhajirīn) and the Supporters (the AnSār) who followed him in the hour of hardship after the hearts of a group of them were about to turn crooked, then He relented towards them. Surely, to them He is Very-Kind, Very-Merciful.'),
(1353, 9, 118, 14, 3, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'وَّ عَلَی الثَّلٰثَۃِ الَّذِیۡنَ خُلِّفُوۡا ؕ حَتّٰۤی اِذَا ضَاقَتۡ عَلَیۡہِمُ الۡاَرۡضُ بِمَا رَحُبَتۡ وَ ضَاقَتۡ عَلَیۡہِمۡ اَنۡفُسُہُمۡ وَ ظَنُّوۡۤا اَنۡ لَّا مَلۡجَاَ مِنَ اللّٰہِ  اِلَّاۤ  اِلَیۡہِ ؕ ثُمَّ تَابَ عَلَیۡہِمۡ لِیَتُوۡبُوۡا ؕ اِنَّ اللّٰہَ ہُوَ التَّوَّابُ  الرَّحِیۡمُ ﴿۱۱۸﴾٪', 'اور ان تینوں پر بھی جنکا معاملہ ملتوی کیا گیا تھا۔ یہاں تک کہ جب زمین باوجود فراخی کے ان پر تنگ ہو گئ اور ان کی جانیں بھی ان پر دوبھر ہو گئیں اور انہوں نے جان لیا کہ اللہ کی گرفت سے بچنے کیلئے کوئی جائے پناہ نہیں مگر اسی کی طرف رجوع کرنا۔ پھر اللہ نے ان پر مہربانی کی تاکہ توبہ کریں۔ بیشک اللہ توبہ قبول کرنے ہے والا مہربان ہے۔', 'اور ان تین شخصوں پر جن کو پیچھے رکھا تھا [۱۳۶] یہاں تک کہ جب تنگ ہو گئی ان پر زمین باوجود کشادہ ہونے کے اور تنگ ہو گئیں ان پر ان کی جانیں اور سمجھ گئے کہ کہیں پناہ نہیں اللہ سے مگر اس کی طر ف پھر مہربان ہوا ان پر تاکہ وہ پھر آئیں بیشک اللہ ہی ہے مہربان رحم والا [۱۳۷]', 'And (He did forgive also) the three (who did not join the Tabook expedition (whom the Prophet SAW)) left (i.e. he did not give his judgement in their case, and their case was suspended for Allahs Decision) till for them the earth, vast as it is, was straitened and their ownselves were straitened to them, and they perceived that there is no fleeing from Allah, and no refuge but with Him. Then, He accepted their repentance, that they might repent (unto Him). Verily, Allah is the One Who accepts repentance, Most Merciful.', 'And (He relented) towards the three whose matter was deferred until when the earth was straitened for them despite all its vastness, and even their own souls were straitened for them, and they realized that there is no refuge from Allah, except in Him, then He turned towards them, so that they may repent. Surely, Allah is the Most-Relenting, the Very Merciful.'),
(1354, 9, 119, 15, 4, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوا اتَّقُوا اللّٰہَ وَ کُوۡنُوۡا مَعَ  الصّٰدِقِیۡنَ ﴿۱۱۹﴾', 'اے اہل ایمان اللہ سے ڈرتے رہو اور راستبازوں کے ساتھ رہو۔', 'اے ایمان والو ڈرتے رہو اللہ سے اور رہو ساتھ سچوں کے [۱۳۸]', 'O you who believe! Be afraid of Allah, and be with those who are true (in words and deeds).', 'O you who believe, fear Allah, and be in the company of the truthful.'),
(1355, 9, 120, 15, 4, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'مَا کَانَ لِاَہۡلِ الۡمَدِیۡنَۃِ وَ مَنۡ حَوۡلَہُمۡ مِّنَ الۡاَعۡرَابِ اَنۡ یَّتَخَلَّفُوۡا عَنۡ رَّسُوۡلِ اللّٰہِ  وَ لَا یَرۡغَبُوۡا بِاَنۡفُسِہِمۡ عَنۡ نَّفۡسِہٖ ؕ  ذٰلِکَ بِاَنَّہُمۡ لَا یُصِیۡبُہُمۡ ظَمَاٌ وَّ لَا نَصَبٌ وَّ لَا مَخۡمَصَۃٌ  فِیۡ سَبِیۡلِ اللّٰہِ وَ لَا یَطَـُٔوۡنَ مَوۡطِئًا یَّغِیۡظُ الۡکُفَّارَ وَ لَا یَنَالُوۡنَ مِنۡ عَدُوٍّ نَّیۡلًا اِلَّا کُتِبَ لَہُمۡ بِہٖ عَمَلٌ صَالِحٌ ؕ اِنَّ اللّٰہَ  لَا یُضِیۡعُ  اَجۡرَ  الۡمُحۡسِنِیۡنَ ﴿۱۲۰﴾ۙ', 'اہل مدینہ کو اور جو انکے آس پاس دیہاتی رہتے ہیں انکو شایاں نہ تھا کہ اللہ کے پیغمبر سے پیچھے رہ جائیں اور نہ یہ کہ اپنی جانوں کو انکی جان سے زیادہ عزیز رکھیں۔ یہ اس لئے کہ انہیں اللہ کی راہ میں جو تکلیف پہنچتی ہے پیاس کی یا محنت کی یا بھوک کی یا وہ ایسی جگہ چلتے ہیں کہ کافروں کو غصہ آئے یا دشمنوں سے کوئی چیز لیتے ہیں تو ہر بات پر انکے لئے عمل نیک لکھا جاتا ہے۔ کچھ شک نہیں کہ اللہ نیکوکاروں کا اجر ضائع نہیں کرتا۔', 'نہ چاہئے مدینہ والوں کو اور انکے گرد کے گنواروں کو کہ پیچھے رہ جائیں رسول اللہ کے ساتھ سے اور نہ یہ کہ اپنی جان کو چاہیں زیادہ رسول کی جان سے [۱۳۹] یہ اس واسطے کہ جہاد کرنے والے نہیں پہنچتی انکو پیاس اور نہ محنت اور نہ بھوک اللہ کی راہ میں اور نہیں قدم رکھتے کہیں جس سے کہ خفا ہوں کافر اور نہ چھینتے ہیں دشمن سے کوئی چیز مگر لکھا جاتا ہے ان کے واسطے اسکے بدلے نیک عمل بیشک اللہ نہیں ضائع کرتا حق نیکی کرنے والوں کا [۱۴۰]', 'It was not becoming of the people of Al-Madinah and the bedouins of the neighbourhood to remain behind Allahs Messenger (Muhammad SAW when fighting in Allahs Cause) and (it was not becoming of them) to prefer their own lives to his life. That is because they suffer neither thirst nor fatigue, nor hunger in the Cause of Allah, nor they take any step to raise the anger of disbelievers nor inflict any injury upon an enemy but is written to their credit as a deed of righteousness. Surely, Allah wastes not the reward of the Muhsinoon', 'It was not (permissible) for the people of Madīnah and for those around them of the Bedouins to stay behind abandoning the Messenger of Allah, nor to prefer their own lives to his life. That is because whatever thirst or fatigue or hunger strikes them in the way of Allah, and whenever they step into a place which infuriates the infidels, and whenever they make a gain from an enemy, a virtuous deed is credited to their account. Surely, Allah does not nullify the reward of the virtuous.'),
(1356, 9, 121, 15, 4, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'وَ لَا یُنۡفِقُوۡنَ نَفَقَۃً صَغِیۡرَۃً وَّ لَا کَبِیۡرَۃً  وَّ لَا یَقۡطَعُوۡنَ وَادِیًا اِلَّا کُتِبَ لَہُمۡ لِیَجۡزِیَہُمُ اللّٰہُ  اَحۡسَنَ مَا کَانُوۡا یَعۡمَلُوۡنَ ﴿۱۲۱﴾', 'اور اسی طرح وہ جو خرچ کرتے ہیں تھوڑا یا بہت یا کوئی میدان طے کرتے ہیں تو یہ سب کچھ ان کے لئے اعمال صالحہ میں لکھ لیا جاتا ہے تاکہ اللہ انکو انکے اعمال کا بہت اچھا بدلہ دے۔', 'اور نہ خرچ کرتے ہیں کوئی خرچ چھوٹا اور نہ بڑا اور نہ طے کرتے ہیں کوئی میدان مگر لکھ لیا جاتا ہے انکے واسطے [۱۴۱] تاکہ بدلا دے ان کو اللہ بہتر اس کام کا جو کرتے تھے [۱۴۲]', 'Nor do they spend anything (in Allahs Cause) - small or great - nor cross a valley, but is written to their credit, that Allah may recompense them with the best of what they used to do (i.e. Allah will reward their good deeds according to the reward of their best deeds which they did in the most perfect manner).', 'Whatever they spend, be it less or more, and whenever they cross a valley, is all written down for them, so that Allah may give them the best reward for what they used to do.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1357, 9, 122, 15, 4, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'وَ مَا کَانَ الۡمُؤۡمِنُوۡنَ  لِیَنۡفِرُوۡا کَآفَّۃً ؕ فَلَوۡ لَا نَفَرَ مِنۡ کُلِّ فِرۡقَۃٍ مِّنۡہُمۡ طَآئِفَۃٌ  لِّیَتَفَقَّہُوۡا فِی الدِّیۡنِ وَ لِیُنۡذِرُوۡا قَوۡمَہُمۡ اِذَا رَجَعُوۡۤا اِلَیۡہِمۡ لَعَلَّہُمۡ  یَحۡذَرُوۡنَ ﴿۱۲۲﴾٪', 'اور یہ تو ہو نہیں سکتا کہ مومن سب کے سب نکل آئیں تو یوں کیوں نہ کیا کہ ہر ایک جماعت میں سے چند اشخاص نکل جاتے تاکہ دین کا علم سیکھتے اور اس میں سمجھ پیدا کرتے۔ اور جب اپنی قوم کی طرف واپس آتے تو انکو ڈر سناتے تاکہ وہ بھی محتاط ہو جاتے۔', 'اور ایسے تو نہیں مسلمان کہ کوچ کریں سارے سو کیوں نہ نکلا ہر فرقہ میں سے ان کا ایک حصہ تاکہ سمجھ پیدا کریں دین میں اور تاکہ خبر پہنچائیں اپنی قوم کو جب کہ لوٹ کر آئیں ان کی طرف تاکہ وہ بچتے رہیں [۱۴۳]', 'And it is not (proper) for the believers to go out to fight (Jihad) all together. Of every troop of them, a party only should go forth, that they (who are left behind) may get instructions in (Islamic) religion, and that they may warn their people when they return to them, so that they may beware (of evil).', 'It is not (necessary) for all the believers to go forth.’; So, why should it not be that a group from every section of them goes forth, so that they may acquire perfect understanding of the Faith, and so that they may warn their people when they return to them, so that they may take due care (of the rules of Sharī‘ah ).'),
(1358, 9, 123, 16, 5, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا قَاتِلُوا الَّذِیۡنَ یَلُوۡنَکُمۡ مِّنَ الۡکُفَّارِ وَ لۡیَجِدُوۡا فِیۡکُمۡ  غِلۡظَۃً ؕ وَ اعۡلَمُوۡۤا  اَنَّ اللّٰہَ  مَعَ الۡمُتَّقِیۡنَ ﴿۱۲۳﴾', 'اے اہل ایمان! اپنے نزدیک کے رہنے والے کافروں سے جنگ کرو۔ اور چاہیے کہ وہ تم میں سختی پائیں۔ اور جان رکھو کہ اللہ پرہیزگاروں کے ساتھ ہے۔', 'اے ایمان والو لڑتے جاؤ اپنے نزدیک کے کافروں سے [۱۴۴] اور چاہئے کہ ان پر معلوم ہو تمہارے اندر سختی [۱۴۵] اور جانو کہ اللہ ساتھ ہے ڈر والوں کے [۱۴۶]', 'O you who believe! Fight those of the disbelievers who are close to you, and let them find harshness in you, and know that Allah is with those who are the Al-Muttaqoon (the pious - see V.2:2).', 'O you who believe, fight those disbelievers who are near you, and let them find severity in you. Know well that Allah is with the God-fearing.'),
(1359, 9, 124, 16, 5, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'وَ اِذَا مَاۤ  اُنۡزِلَتۡ سُوۡرَۃٌ  فَمِنۡہُمۡ مَّنۡ یَّقُوۡلُ اَیُّکُمۡ زَادَتۡہُ ہٰذِہٖۤ  اِیۡمَانًا ۚ فَاَمَّا الَّذِیۡنَ  اٰمَنُوۡا  فَزَادَتۡہُمۡ   اِیۡمَانًا وَّ ہُمۡ  یَسۡتَبۡشِرُوۡنَ ﴿۱۲۴﴾', 'اور جب کوئی سورت نازل ہوتی ہے تو بعض منافق پوچھتے ہیں کہ اس سورت نے تم میں سے کس کا ایمان زیادہ کیا ہے۔ سو جو ایمان والے ہیں ان کا تو ایمان زیادہ کیا اور وہ خوش ہوتے ہیں۔', 'اور جب نازل ہوتی ہے کوئی سورت تو بعضے ان میں کہتے ہیں کس کا تم میں سے زیادہ کر دیا اس سورت نے ایمان سو جو لوگ ایمان رکھتے ہیں ان کا زیادہ کر دیا اس سورت نے ایمان اور  وہ خوش وقت ہوتے ہیں', 'And whenever there comes down a Soorah (chapter from the Quran), some of them (hypocrites) say: \"Which of you has had his Faith increased by it?\" As for those who believe, it has increased their Faith, and they rejoice.', 'When a Sūrah is sent down, some of them (the hypocrites) say, “Whose faith from among you has been increased by this?” So far as the believers are concerned, it has certainly increased their faith, and they are quite happy.'),
(1360, 9, 125, 16, 5, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'وَ اَمَّا الَّذِیۡنَ فِیۡ قُلُوۡبِہِمۡ مَّرَضٌ فَزَادَتۡہُمۡ رِجۡسًا اِلٰی رِجۡسِہِمۡ وَ مَا تُوۡا وَ ہُمۡ کٰفِرُوۡنَ ﴿۱۲۵﴾', 'اور جن کے دلوں میں بیماری ہے تو انکی خباثت کو اور بڑھا دیا۔ اور وہ مرے بھی تو کافر کے کافر۔', 'اور جنکے دل میں مرض ہے سو انکے لئے بڑھا دی گندگی پر گندگی اور وہ مرنے تک کافر ہی رہے [۱۴۷]', 'But as for those in whose hearts is a disease (of doubt, disbelief and hypocrisy), it will add suspicion and doubt to their suspicion, disbelief and doubt, and they die while they are disbelievers.', 'As for those who have malady in their hearts, it adds further impurity to their (initial) impurity, and they die infidels.'),
(1361, 9, 126, 16, 5, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'اَوَ لَا  یَرَوۡنَ اَنَّہُمۡ یُفۡتَنُوۡنَ فِیۡ  کُلِّ عَامٍ مَّرَّۃً  اَوۡ مَرَّتَیۡنِ ثُمَّ لَا یَتُوۡبُوۡنَ وَ لَا ہُمۡ یَذَّکَّرُوۡنَ ﴿۱۲۶﴾', 'کیا یہ دیکھتے نہیں کہ یہ ہر سال ایک یا دو بار بلا میں پھنسا دیئے جاتے ہیں پھر بھی توبہ نہیں کرتے اور نہ نصیحت حاصل کرتے ہیں۔', 'کیا نہیں دیکھتے کہ وہ آزمائے جاتے ہیں ہر برس میں ایک بار یا دو بار پھر بھی توبہ نہیں کرتے اور نہ وہ نصیحت پکڑتے ہیں [۱۴۸]', 'See they not that they are tried once or twice every year (with different kinds of calamities, disease, famine, etc.)? Yet, they turn not in repentance, nor do they learn a lesson (from it).', 'Do they not see that they are put to trial every year once or twice; still they neither repent, nor do they take lesson?'),
(1362, 9, 127, 16, 5, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'وَ  اِذَا مَاۤ  اُنۡزِلَتۡ سُوۡرَۃٌ  نَّظَرَ  بَعۡضُہُمۡ اِلٰی بَعۡضٍ ؕ ہَلۡ یَرٰىکُمۡ مِّنۡ اَحَدٍ ثُمَّ انۡصَرَفُوۡا ؕ صَرَفَ اللّٰہُ  قُلُوۡبَہُمۡ بِاَنَّہُمۡ قَوۡمٌ  لَّا یَفۡقَہُوۡنَ ﴿۱۲۷﴾', 'اور جب کوئی سورت نازل ہوتی ہے تو ایک دوسرے کی طرف دیکھنے لگتے ہیں اور پوچھتے ہیں کہ بھلا تمہیں کوئی دیکھتا ہے؟ پھر پیٹھ پھیر جاتے ہیں۔ اللہ نے انکے دلوں کو پھیر رکھا ہے کیونکہ یہ ایسے لوگ ہیں کہ سمجھ سے کام نہیں لیتے۔', 'اور جب نازل ہوتی ہے کوئی سورت تو دیکھنے لگتا ہے ان میں ایک دوسرے کی طرف کہ کیا دیکھتا ہے تم کو کوئی مسلمان پھر چل دیتےہیں [۱۴۹] پھیر دیے ہیں اللہ نے دل ان کے اس واسطے کہ وہ لوگ ہیں کہ سمجھ نہیں رکھتے [۱۵۰]', 'And whenever there comes down a Soorah (chapter from the Quran), they look at one another (saying): \"Does any one see you?\" Then they turn away. Allah has turned their hearts (from the light) because they are a people that understand not.', 'And when a Sūrah is sent down, they look at each other (as if saying): “Is there someone watching you?” Then they turn away. Allah has turned their hearts, because they are a people who do not understand.'),
(1363, 9, 128, 16, 5, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'لَقَدۡ جَآءَکُمۡ رَسُوۡلٌ مِّنۡ اَنۡفُسِکُمۡ عَزِیۡزٌ عَلَیۡہِ مَا عَنِتُّمۡ حَرِیۡصٌ عَلَیۡکُمۡ بِالۡمُؤۡمِنِیۡنَ رَءُوۡفٌ رَّحِیۡمٌ ﴿۱۲۸﴾', 'لوگو تمہارے پاس تم ہی میں سے ایک پیغمبر آئے ہیں۔ تمہاری تکلیف انکو گراں معلوم ہوتی ہے اور وہ تمہاری بھلائی کے بہت خواہشمند ہیں۔ اور مومنوں پر نہایت شفقت کرنے والے ہیں مہربان ہیں۔', 'آیا ہے تمہارے پاس رسول تم میں کا [۱۵۱] بھاری ہے اس پر جو تم کو تکلیف پہنچے [۱۵۲] حریص ہے تمہارے بھلائی پر [۱۵۳] ایمان والوں پر نہایت شفیق مہربان ہے [۱۵۴]', 'Verily, there has come unto you a Messenger (Muhammad SAW) from amongst yourselves (i.e. whom you know well). It grieves him that you should receive any injury or difficulty. He (Muhammad SAW) is anxious over you (to be rightly guided, to repent to Allah, and beg Him to pardon and forgive your sins, in order that you may enter Paradise and be saved from the punishment of the Hell-fire), for the believers (he SAW is) full of pity, kind, and merciful.', 'Surely, there has come to you, from your midst, a Messenger who feels it very hard on him if you face a hardship, who is very anxious for your welfare, and for the believers he is very kind, very merciful.'),
(1364, 9, 129, 16, 5, 11, 'یَعۡتَذِرُوۡنَ', 'التوبۃ', 'فَاِنۡ تَوَلَّوۡا فَقُلۡ حَسۡبِیَ اللّٰہُ ۫٭ۖ لَاۤ  اِلٰہَ  اِلَّا ہُوَ ؕ عَلَیۡہِ  تَوَکَّلۡتُ وَ ہُوَ رَبُّ الۡعَرۡشِ  الۡعَظِیۡمِ ﴿۱۲۹﴾٪', 'سو اگر یہ لوگ پھر جائیں اور نہ مانیں تو کہدو کہ اللہ مجھے کفایت کرتا ہے اسکے سوا کوئی معبود نہیں۔ اسی پر میرا بھروسہ ہے اور وہی عرش عظیم کا مالک ہے۔', 'پھر بھی اگر منہ پھیریں تو کہہ دے کہ کافی ہے مجھ کو اللہ کسی کی بندگی نہیں اسکے سوا اسی پر میں نے بھروسہ کیا اور وہی مالک ہے عرش عظیم کا [۱۵۵]', 'But if they turn away, say (O Muhammad SAW): \"Allah is sufficient for me. La ilaha illa Huwa (none has the right to be worshipped but He), in Him I put my trust and He is the Lord of the Mighty Throne.\"', 'So, if they turn away, say (O Messenger,) “Enough for me is Allah. There is no god but He. In Him I have placed my trust, and He is the Lord of the Great Throne.”'),
(1365, 10, 1, 1, 6, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'الٓرٰ ۟ تِلۡکَ اٰیٰتُ الۡکِتٰبِ  الۡحَکِیۡمِ ﴿۱﴾', 'الٓرا ۔ یہ حکمت والی کتاب کی آیتیں ہیں۔', 'یہ آیتیں ہیں پکی کتاب کی [۱]', 'Alif-Lam-Ra. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings). These are the Verses of the Book (the Quran) Al-Hakeem (showing lawful and unlawful things, explaining Allahs (Divine) Laws for mankind, leading them to eternal happiness by ordering them to follow the true Islamic Monotheism, - worshipping none but Allah Alone - that will guide them to Paradise and save them from Hell).', 'Alif, Lām, Rā . These are verses of the Wise Book.'),
(1366, 10, 2, 1, 6, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'اَکَانَ لِلنَّاسِ عَجَبًا اَنۡ اَوۡحَیۡنَاۤ  اِلٰی رَجُلٍ مِّنۡہُمۡ اَنۡ اَنۡذِرِ النَّاسَ وَ بَشِّرِ الَّذِیۡنَ اٰمَنُوۡۤا اَنَّ لَہُمۡ قَدَمَ صِدۡقٍ عِنۡدَ  رَبِّہِمۡ ؕؔ قَالَ الۡکٰفِرُوۡنَ  اِنَّ ہٰذَا لَسٰحِرٌ  مُّبِیۡنٌ ﴿۲﴾', 'کیا لوگوں کو تعجب ہوا کہ ہم نے انہی میں سے ایک شخص کو حکم بھیجا کہ لوگوں کو ڈر سنا دو اور ایمان لانے والوں کو خوشخبری دے دو کہ انکے پروردگار کے ہاں ان کا سچا درجہ ہے ایسے شخص کی نسبت کافر کہتے ہیں کہ یہ تو کھلا جادوگر ہے۔', 'کیا لوگوں کو تعجب ہوا کہ وحی بھیجی ہم نے ایک مرد پر ان میں سے  یہ کہ ڈر سنا دے لوگوں کو اور خوشخبری سنا دے ایمان لانے والوں کو کہ ان کے لئے پایہ سچا ہے اپنے رب کے یہاں [۲] کہنے لگے منکر بیشک یہ تو جادوگر ہے صریح [۳]', 'Is it wonder for mankind that We have sent Our Inspiration to a man from among themselves (i.e. Prophet Muhammad SAW) (saying): \"Warn mankind (of the coming torment in Hell), and give good news to those who believe (in the Oneness of Allah and in His Prophet Muhammad SAW) that they shall have with their Lord the rewards of their good deeds?\" (But) the disbelievers say: \"This is indeed an evident sorcerer (i.e. Prophet Muhammad SAW and the Quran)!', 'Is it surprising for the people that We have sent the divine revelation to a man from among them to direct him that he should warn the people (who are heedless), and give happy news to those who believe that they will have a truly excellent footing at a place near their Lord? The disbelievers said, “Surely, he is an open sorcerer.”'),
(1367, 10, 3, 1, 6, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'اِنَّ رَبَّکُمُ اللّٰہُ الَّذِیۡ خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ فِیۡ سِتَّۃِ اَیَّامٍ ثُمَّ اسۡتَوٰی عَلَی الۡعَرۡشِ یُدَبِّرُ الۡاَمۡرَ ؕ مَا مِنۡ شَفِیۡعٍ اِلَّا مِنۡۢ بَعۡدِ اِذۡنِہٖ ؕ ذٰلِکُمُ اللّٰہُ رَبُّکُمۡ فَاعۡبُدُوۡہُ ؕ اَفَلَا تَذَکَّرُوۡنَ ﴿۳﴾', 'تمہارا پروردگار تو اللہ ہی ہے جس نے آسمان اور زمین چھ دن میں بنائے پھر عرش پر جلوہ افروز ہوا وہی ہر ایک کام کا انتظام کرتا ہے۔ کوئی اسکے پاس اسکی اجازت حاصل کئے بغیر کسی کی سفارش نہیں کر سکتا۔ یہی اللہ تمہارا پروردگار ہے تو اسی کی عبادت کرو۔ بھلا تم غور کیوں نہیں کرتے۔', 'تحقیق تمہارا رب اللہ ہے جس نے بنائے آسمان اور زمین چھ دن میں [۴] پھر قائم ہوا عرش پر [۵] تدبیر کرتا ہے کام کی [۶] کوئی سفارش نہیں کر سکتا مگر اس کی اجازت کے بعد [۷] وہ اللہ ہے رب تمہارا سو اسکی بندگی کرو کیا تم دھیان نہیں کرتے [۸]', 'Surely, your Lord is Allah Who created the heavens and the earth in six Days and then Istawa (rose over) the Throne (really in a manner that suits His Majesty), disposing the affair of all things. No intercessor (can plead with Him) except after His Leave. That is Allah, your Lord; so worship Him (Alone). Then, will you not remember?', 'Surely, your Lord is Allah, the One who created the heavens and the earth in six days, and then He positioned Himself on the Throne. He governs all affairs (of His creation). There is no one who could intercede before Him, except after His permission. That is Allah, your Lord. So, worship Him. Would you still pay no heed?'),
(1368, 10, 4, 1, 6, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'اِلَیۡہِ مَرۡجِعُکُمۡ جَمِیۡعًا ؕ وَعۡدَ اللّٰہِ حَقًّا ؕ اِنَّہٗ یَبۡدَؤُا الۡخَلۡقَ ثُمَّ یُعِیۡدُہٗ لِیَجۡزِیَ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ بِالۡقِسۡطِ ؕ وَ الَّذِیۡنَ کَفَرُوۡا لَہُمۡ شَرَابٌ مِّنۡ حَمِیۡمٍ وَّ عَذَابٌ اَلِیۡمٌۢ بِمَا  کَانُوۡا  یَکۡفُرُوۡنَ ﴿۴﴾', 'اسی کے پاس تم سب کو لوٹ کر جانا ہے۔ اللہ کا وعدہ سچا ہے۔ وہی خلقت کو پہلی بار پیدا کرتا ہے پھر وہی اسکو دوبارہ پیدا کرے گا۔ تاکہ ایمان والوں اور نیک کام کرنے والوں کو انصاف کے ساتھ بدلہ دے اور جو کافر ہیں انکے لئے پینے کو نہایت کھولتا پانی اور درد دینے والا عذاب ہوگا کیونکہ وہ کفر کرتے تھے۔', 'اسی کی طرف لوٹ کر جانا ہے تم سب کو [۹] وعدہ ہے اللہ کا سچا وہی پیدا کرتا ہے اول بار پھر دوبارہ کرے گا اس کو تاکہ بدلا دے انکو جو ایمان لائے تھے اور کئے تھے کام نیک انصاف کے ساتھ [۱۰] اور جو کافر ہوئے ان کو پینا ہے کھولتا پانی اور عذاب ہے دردناک اس لئے کہ کفر کرتے تھے', 'To Him is the return of all of you. The Promise of Allah is true. It is He Who begins the creation and then will repeat it, that He may reward with justice those who believed (in the Oneness of Allah - Islamic Monotheism) and did deeds of righteousness. But those who disbelieved will have a drink of boiling fluids and painful torment because they used to disbelieve.', 'Towards Him all of you have to return, this being a true promise from Allah. Surely, He originates the creation; then He will bring it again, so that He may justly reward those who believe and do good deeds. As for those who disbelieve, for them there is a drink of boiling water and a painful punishment, because they used to be infidels.'),
(1369, 10, 5, 1, 6, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'ہُوَ الَّذِیۡ جَعَلَ الشَّمۡسَ ضِیَآءً وَّ الۡقَمَرَ نُوۡرًا وَّ قَدَّرَہٗ  مَنَازِلَ  لِتَعۡلَمُوۡا عَدَدَ السِّنِیۡنَ وَ الۡحِسَابَ ؕ مَا خَلَقَ اللّٰہُ  ذٰلِکَ اِلَّا بِالۡحَقِّ ۚ یُفَصِّلُ الۡاٰیٰتِ لِقَوۡمٍ  یَّعۡلَمُوۡنَ ﴿۵﴾', 'وہی تو ہے جس نے سورج کو خوب روشن اور چاند کو بھی منور بنایا اور چاند کی منزلیں مقرر کیں تاکہ تم برسوں کا شمار اور کاموں کا حساب معلوم کرو یہ سب کچھ اللہ نے تدبیر سے پیدا کیا ہے سمجھنے والوں کے لئے وہ اپنی آیتیں کھول کھول کر بیان فرماتا ہے۔', 'وہی ہے جس نے بنایا سورج کو چمک (چمکتا) اور چاند کو چاندنا [۱۱] اور مقرر کیں اسکے لئے منزلیں [۱۲] تاکہ پہچانو گنتی برسوں کی اور حساب [۱۳] یوں ہی نہیں بنایا اللہ نے یہ سب کچھ مگر تدبیر سے [۱۴] ظاہر کرتا ہے نشانیاں ان لوگوں کے لئے جن کو سمجھ ہے [۱۵]', 'It is He Who made the sun a shining thing and the moon as a light and measured out its (their) stages, that you might know the number of years and the reckoning. Allah did not create this but in truth. He explains the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) in detail for people who have knowledge.', 'He is the One who has made the sun a glow, and the moon a light, and determined for it stages, so that you may learn the number of the years, and the calculation (of time). Allah has not created all this but for a rightful purpose. He elaborates the signs for a people who understand.'),
(1370, 10, 6, 1, 6, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'اِنَّ فِی اخۡتِلَافِ الَّیۡلِ وَ النَّہَارِ وَ مَا خَلَقَ اللّٰہُ فِی السَّمٰوٰتِ وَ الۡاَرۡضِ لَاٰیٰتٍ  لِّقَوۡمٍ  یَّتَّقُوۡنَ ﴿۶﴾', 'رات اور دن کے ایک دوسرے کے پیچھے آنے جانے میں اور جو چیزیں اللہ نے آسمان اور زمین میں پیدا کی ہیں سب میں ڈرنے والوں کے لئے نشانیاں ہیں۔', 'البتہ بدلنے میں رات اور دن کے اور جو کچھ پیدا کیا ہے اللہ نے آسمانوں اور زمین میں نشانیاں ہیں ان لوگوں کو جو ڈرتے ہیں [۱۶]', 'Verily, in the alternation of the night and the day and in all that Allah has created in the heavens and the earth are Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) for those people who keep their duty to Allah, and fear Him much.', 'Surely, in the alternation of night and day and in what Allah has created in the heavens and the earth, there are signs for a people who are God-fearing.'),
(1371, 10, 7, 1, 6, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'اِنَّ الَّذِیۡنَ لَا یَرۡجُوۡنَ لِقَآءَنَا وَ رَضُوۡا بِالۡحَیٰوۃِ الدُّنۡیَا وَ اطۡمَاَنُّوۡا بِہَا وَ الَّذِیۡنَ  ہُمۡ عَنۡ  اٰیٰتِنَا غٰفِلُوۡنَ ۙ﴿۷﴾', 'جن لوگوں کو ہم سے ملنے کی توقع نہیں اور دنیا کی زندگی سے خوش اور اسی پر مطمئن ہو بیٹھے اور ہماری نشانیوں سے غافل ہو رہے ہیں۔', 'البتہ جو لوگ امید نہیں رکھتے ہمارے ملنے کی اور خوش ہوئے دنیا کی زندگی پر اور اسی پر مطمئن ہو گئے اور جو لوگ ہماری نشانیوں (قدرتوں) سے بے خبر ہیں [۱۷]', 'Verily, those who hope not for their meeting with Us, but are pleased and satisfied with the life of the present world, and those who are heedless of Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.),', 'As for those who do not believe in meeting Us and are quite happy with the life of this world and are content with it, and those who are heedless to Our signs,'),
(1372, 10, 8, 1, 6, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'اُولٰٓئِکَ مَاۡوٰىہُمُ النَّارُ بِمَا کَانُوۡا یَکۡسِبُوۡنَ ﴿۸﴾', 'ان کا ٹھکانہ ان اعمال کے سبب جو وہ کرتے ہیں دوزخ ہے۔', 'ایسوں کا ٹھکانا ہے آگ بدلا اس کا جو کماتے تھے [۱۸]', 'Those, their abode will be the Fire, because of what they used to earn.', 'they are the ones whose abode is the Fire, because of what they used to earn for themselves.'),
(1373, 10, 9, 1, 6, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'اِنَّ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ یَہۡدِیۡہِمۡ رَبُّہُمۡ بِاِیۡمَانِہِمۡ ۚ تَجۡرِیۡ مِنۡ تَحۡتِہِمُ  الۡاَنۡہٰرُ  فِیۡ  جَنّٰتِ  النَّعِیۡمِ ﴿۹﴾', 'اور جو لوگ ایمان لائے اور نیک کام کرتے رہے انکو انکا پروردگار انکے ایمان کی وجہ سے جنتوں میں پہنچا دے گا انکے نیچے نعمت کے باغوں میں نہریں بہ رہی ہوں گی۔', 'البتہ جو لوگ ایمان لائے اور کام کئے اچھے ہدایت کرے گا انکو رب ان کا ان کے ایمان سے [۱۹] بہتی ہیں ان کے نیچے نہریں باغوں میں آرام کے', 'Verily, those who believe (in the Oneness of Allah along with the six articles of Faith, i.e. to believe in Allah, His Angels, His Books, His Messengers, Day of Resurrection, and Al-Qadar (Divine Preordainments) - Islamic Monotheism), and do deeds of righteousness, their Lord will guide them through their Faith; under them will flow rivers in the Gardens of delight (Paradise).', 'As for those who believe and do good deeds, their Lord will guide them by virtue of their belief; rivers will be flowing beneath them in the Gardens of Bliss.'),
(1374, 10, 10, 1, 6, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'دَعۡوٰىہُمۡ فِیۡہَا سُبۡحٰنَکَ اللّٰہُمَّ وَ تَحِیَّتُہُمۡ فِیۡہَا سَلٰمٌ ۚ وَ اٰخِرُ  دَعۡوٰىہُمۡ اَنِ  الۡحَمۡدُ  لِلّٰہِ  رَبِّ  الۡعٰلَمِیۡنَ ﴿٪۱۰﴾', 'جب وہ ان میں انکی نعمتوں کو دیکھیں گے تو بیساختہ کہیں گے سبحان اللہ۔ اور آپس میں انکی دعا سلام علیکم ہو گی۔ اور ان کا آخری قول یہ ہوگا کہ اللہ رب العالمین کی حمد اور اس کا شکر ہے۔', 'ان کی دعا اس جگہ یہ کہ پاک ذات ہے تیری یا اللہ [۲۰] اور ملاقات ان کی سلام [۲۱] اور خاتمہ انکی دعا کا اس پر کہ سب خوبی اللہ کو جو پروردگار سارے جہان کا [۲۲]', 'Their way of request therein will be Subhanaka Allahumma (Glory to You, O Allah!) and Salam (peace, safe from each and every evil) will be their greetings therein (Paradise)! and the close of their request will be: Al-Hamdu Lillahi Rabbil-Alameen (All the praises and thanks are to Allah, the Lord of Alameen (mankind, jinns and all that exists)).', 'Their call therein will be, “Pure are You, O Allah” and their greeting therein will be Salām . And the end of their call will be, “Praise be to Allah, the Lord of all the worlds.”'),
(1375, 10, 11, 2, 7, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ لَوۡ یُعَجِّلُ اللّٰہُ لِلنَّاسِ الشَّرَّ اسۡتِعۡجَالَہُمۡ بِالۡخَیۡرِ لَقُضِیَ اِلَیۡہِمۡ اَجَلُہُمۡ ؕ فَنَذَرُ الَّذِیۡنَ لَا یَرۡجُوۡنَ لِقَآءَنَا فِیۡ  طُغۡیَانِہِمۡ  یَعۡمَہُوۡنَ ﴿۱۱﴾', 'اور اگر اللہ لوگوں کی برائی میں جلدی کرتا جس طرح وہ طلب خیر میں جلدی کرتے ہیں تو انکی عمر کی معیاد پوری ہو چکی ہوتی۔ سو جن لوگوں کو ہم سے ملنے کی توقع نہیں انہیں ہم چھوڑے رکھتے ہیں کہ اپنی سرکشی میں بہکتے رہیں۔', 'اور اگر جلدی پہنچا دے اللہ لوگوں کو برائی جیسے کہ جلدی مانگتے ہیں وہ بھلائی تو ختم کر دی جائے انکی عمر سو ہم چھوڑے رکھتے ہیں انکو جن کو امید نہیں ہماری ملاقات کی انکی شرارت میں سرگرداں [۲۳]', 'And were Allah to hasten for mankind the evil (they invoke for themselves and for their children, etc. while in a state of anger) as He hastens for them the good (they invoke) then they would have been ruined. So We leave those who expect not their meeting with Us, in their trespasses, wandering blindly in distraction. (Tafsir At-Tabaree; Vol. 11, Page 91)', 'And if Allah were to hasten in sending evil to the people, as they hasten in seeking good, their time would have been all over. So, We leave alone those who do not believe in meeting Us to wander blindly in their rebellion.'),
(1376, 10, 12, 2, 7, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ اِذَا مَسَّ الۡاِنۡسَانَ الضُّرُّ دَعَانَا لِجَنۡۢبِہٖۤ اَوۡ قَاعِدًا اَوۡ قَآئِمًا ۚ فَلَمَّا کَشَفۡنَا عَنۡہُ ضُرَّہٗ  مَرَّ کَاَنۡ  لَّمۡ  یَدۡعُنَاۤ  اِلٰی ضُرٍّ مَّسَّہٗ ؕ  کَذٰلِکَ زُیِّنَ  لِلۡمُسۡرِفِیۡنَ مَا  کَانُوۡا  یَعۡمَلُوۡنَ ﴿۱۲﴾', 'اور جب انسان کو تکلیف پہنچتی ہے تو لیٹا اور بیٹھا اور کھڑا ہر حال میں ہمیں پکارتا ہے۔ پھر جب ہم اس تکلیف کو اس سے دور کر دیتے ہیں تو بے لحاظ ہو جاتا اور اس طرح گزر جاتا ہے کہ گویا کسی تکلیف کے پہنچنے پر ہمیں کبھی پکارا ہی نہ تھا۔ اسی طرح حد سے نکل جانے والوں کو انکے اعمال آراستہ کر کے دکھائے گئے ہیں۔', 'اور جب پہنچے انسان کو تکلیف پکارے ہم کو پڑا ہوا یا بیٹھا یا کھڑا پھر جب ہم کھول دیں اس سے وہ تکلیف چلا جائے گویا کبھی نہ پکارا تھا ہم کو کسی تکلیف پہنچنے پر اسی طرح پسند آیا ہے بیباک لوگوں کو جو کچھ کر رہے ہیں [۲۴]', 'And when harm touches man, he invokes Us, lying down on his side, or sitting or standing. But when We have removed his harm from him, he passes on his way as if he had never invoked Us for a harm that touched him! Thus it seems fair to the Musrifoon that which they used to do.', 'When man is afflicted by a hardship, he prays to Us (at all times), when reclining or sitting or standing. But when We remove his hardship, he just takes his way as though he had never prayed to Us in any hardship that afflicted him. This is how their deeds appear beautified to the transgressors.'),
(1377, 10, 13, 2, 7, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ لَقَدۡ اَہۡلَکۡنَا الۡقُرُوۡنَ مِنۡ قَبۡلِکُمۡ لَمَّا ظَلَمُوۡا ۙ وَ جَآءَتۡہُمۡ رُسُلُہُمۡ بِالۡبَیِّنٰتِ وَ مَا کَانُوۡا لِیُؤۡمِنُوۡا ؕ کَذٰلِکَ نَجۡزِی الۡقَوۡمَ الۡمُجۡرِمِیۡنَ ﴿۱۳﴾', 'اور تم سے ہم پہلے کئ امتوں کو جب انہوں نے ظلم کیا ہلاک کر چکے ہیں۔ اور ان کے پاس پیغمبر کھلی نشانیاں لے کر آئے۔ مگر وہ ایسے نہ تھے کہ ایمان لاتے۔ ہم گناہگاروں کو اسی طرح بدلہ دیا کرتے ہیں۔', 'اور البتہ ہم ہلاک کر چکے ہیں جماعتوں کو تم سے پہلے جب ظالم ہو گئے حالانکہ لائے تھے انکے پاس رسول انکے کھلی نشانیاں اور ہرگز نہ تھے ایمان لانے والے یوں ہی سزا دیتے ہیں ہم قوم گنہگاروں کو [۲۵]', 'And indeed, We destroyed generations before you, when they did wrong while their Messengers came to them with clear proofs, but they were not such as to believe! Thus do We requite the people who are Mujrimoon (disbelievers, polytheists, sinners, criminals, etc.).', 'Indeed We have destroyed generations before you when they transgressed, and their Messengers had come to them with clear signs, but they were not the ones who would believe. This is how We punish the guilty people.'),
(1378, 10, 14, 2, 7, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'ثُمَّ  جَعَلۡنٰکُمۡ  خَلٰٓئِفَ فِی الۡاَرۡضِ مِنۡۢ بَعۡدِہِمۡ  لِنَنۡظُرَ کَیۡفَ تَعۡمَلُوۡنَ ﴿۱۴﴾', 'پھر ہم نے انکے بعد تم لوگوں کو ملک میں خلیفہ بنایا تاکہ دیکھیں کہ تم کیسے کام کرتے ہو۔', 'پھر تم کو ہم نے ناٹب کیا زمین میں ان کے بعد تاکہ دیکھیں تم کیا کرتے ہو [۲۶]', 'Then We made you follow after them, generations after generations in the land, that We might see how you would work!', 'Then We made you (their) successors in the land, so that We see how you would act.'),
(1379, 10, 15, 2, 7, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ  اِذَا تُتۡلٰی عَلَیۡہِمۡ  اٰیَاتُنَا بَیِّنٰتٍ ۙ قَالَ الَّذِیۡنَ لَا یَرۡجُوۡنَ لِقَآءَنَا ائۡتِ بِقُرۡاٰنٍ غَیۡرِ  ہٰذَاۤ  اَوۡ بَدِّلۡہُ ؕ قُلۡ مَا یَکُوۡنُ لِیۡۤ اَنۡ اُبَدِّلَہٗ  مِنۡ تِلۡقَآیِٔ  نَفۡسِیۡ ۚ اِنۡ  اَتَّبِعُ اِلَّا مَا یُوۡحٰۤی اِلَیَّ ۚ اِنِّیۡۤ  اَخَافُ اِنۡ عَصَیۡتُ رَبِّیۡ  عَذَابَ  یَوۡمٍ  عَظِیۡمٍ ﴿۱۵﴾', 'اور جب انکو ہماری آیتیں پڑھ کر سنائی جاتی ہیں تو جن لوگوں کو ہم سے ملنے کی امید نہیں وہ کہتے ہیں کہ یا تو اسکے سوا کوئی اور قرآن بنا لاؤ یا اسکو بدل دو۔ کہدو کہ مجھ کو اختیار نہیں ہے کہ اسے اپنی طرف سے بدل دوں۔ میں تو اسی حکم کا تابع ہوں جو میری طرف آتا ہے۔ اگر میں اپنے پروردگار کی نافرمانی کروں تو مجھے بڑے سخت دن کے عذاب سے خوف آتا ہے۔', 'اور جب پڑھی جاتی ہیں ان کے سامنے آیتیں ہماری واضح کہتے ہیں وہ لوگ جن کو امید نہیں ہم سے ملاقات کی لے آ کوئی قرآن اس کے سوا یا اس کو بدل ڈال [۲۷] تو کہہ دے میرا کام نہیں کہ اس کو بدل ڈالوں اپنی طرف سے میں تابعداری کرتا ہوں اسی کی جو حکم آئے میری طرف میں ڈرتا ہوں اگر نافرمانی کروں اپنے رب کی بڑے دن کے عذاب سے [۲۸]', 'And when Our Clear Verses are recited unto them, those who hope not for their meeting with Us, say: Bring us a Quran other than this, or change it.\"Say (O Muhammad SAW): \"It is not for me to change it on my own accord; I only follow that which is revealed unto me. Verily, I fear if I were to disobey my Lord, the torment of the Great Day (i.e. the Day of Resurrection).\"', 'When Our verses are recited to them in all their clarity, say those who do not believe in meeting Us, “Bring a Qur’ān other than this, or make changes in it (to suit our fancies)”. Say, “It is not possible for me to make changes in it on my own. I follow nothing but what is revealed to me. If I disobey my Lord, I fear the punishment of a terrible day.”'),
(1380, 10, 16, 2, 7, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'قُلۡ لَّوۡ شَآءَ اللّٰہُ مَا تَلَوۡتُہٗ عَلَیۡکُمۡ  وَ لَاۤ اَدۡرٰىکُمۡ بِہٖ ۫ۖ فَقَدۡ لَبِثۡتُ فِیۡکُمۡ عُمُرًا مِّنۡ  قَبۡلِہٖ ؕ اَفَلَا  تَعۡقِلُوۡنَ ﴿۱۶﴾', 'یہ بھی کہدو کہ اگر اللہ چاہتا تو نہ میں ہی یہ کتاب تم کر پڑھ کر سناتا اور نہ وہی تمہیں اس سے واقف کرتا۔ پس میں اس سے پہلے تم میں ایک عمر رہا ہوں اور کبھی ایک جملہ بھی اس طرح کا نہیں کہا بھلا تم سمجھتے نہیں۔', 'کہہ دے کہ اگر اللہ چاہتا تو میں نہ پڑھتا اس کو تمہارے سامنے اور نہ وہ تم کو خبر کرتا اسکی کیونکہ میں رہ چکا ہوں تم میں ایک عمر اس سے پہلے کیا پھر تم نہیں سوچتے [۲۹]', 'Say (O Muhammad SAW): \"If Allah had so willed, I should not have recited it to you nor would He have made it known to you. Verily, I have stayed amongst you a life time before this. Have you then no sense?\"', 'Say, “Had Allah so willed, I would have not recited it to you, nor would He have let you know it. Then, I have lived among you for years before it. Have you, then, no sense?”'),
(1381, 10, 17, 2, 7, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'فَمَنۡ  اَظۡلَمُ  مِمَّنِ افۡتَرٰی عَلَی اللّٰہِ  کَذِبًا اَوۡ کَذَّبَ بِاٰیٰتِہٖ ؕ اِنَّہٗ  لَا یُفۡلِحُ الۡمُجۡرِمُوۡنَ ﴿۱۷﴾', 'تو اس سے بڑھ کو ظالم کون ہو گا جو اللہ پر جھوٹ باندھے یا اسکی آیتوں کو جھٹلائے؟ بیشک گناہگار فلاح نہیں پائیں گے۔', 'پھر اس سے بڑا ظالم کون جو باندھے اللہ پر بہتان یا جھٹلائے اس کی آیتوں کو بیشک بھلا نہیں ہوتا گنہگاروں کا [۳۰]', 'So who does more wrong than he who forges a lie against Allah or denies His Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.)? Surely, the Mujrimoon (criminals, sinners, disbelievers and polytheists) will never be successful!', 'So, who is more unjust than the one who forges a lie against Allah or gives the lie to His signs? Indeed (such) guilty people shall not achieve success.'),
(1382, 10, 18, 2, 7, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ یَعۡبُدُوۡنَ مِنۡ دُوۡنِ اللّٰہِ مَا لَا یَضُرُّہُمۡ وَ لَا یَنۡفَعُہُمۡ وَ یَقُوۡلُوۡنَ ہٰۤؤُلَآءِ شُفَعَآؤُنَا عِنۡدَ اللّٰہِ ؕ قُلۡ اَتُنَبِّـُٔوۡنَ اللّٰہَ بِمَا  لَا یَعۡلَمُ فِی السَّمٰوٰتِ وَ لَا فِی الۡاَرۡضِ ؕ سُبۡحٰنَہٗ  وَ  تَعٰلٰی عَمَّا یُشۡرِکُوۡنَ ﴿۱۸﴾', 'اور یہ لوگ اللہ کے سوا ایسی چیزوں کی پرستش کرتے ہیں۔ جو نہ ان کا کچھ بگاڑ ہی سکتیں ہیں اور نہ کچھ بھلا ہی کر سکتی ہیں۔ اور کہتے ہیں کہ یہ اللہ کے پاس ہماری سفارش کرنے والے ہیں۔ کہدو کیا تم اللہ کو ایسی چیز بتاتے ہو جس کا وجود اسے نہ آسمانوں میں معلوم ہوتا ہے اور نہ زمین میں وہ پاک ہے اور اسکی شان انکے شرک کرنے سے بہت بلند ہے۔', 'اور پرستش کرتے ہیں اللہ کےسوا اس چیز کی جو نہ نقصان پہنچا سکے ان کو نہ نفع اور کہتے ہیں یہ تو ہمارے سفارشی ہیں اللہ کے پاس [۳۱] تو کہہ کیا تم اللہ کو بتلاتے ہو جو اسکو معلوم نہیں آسمانوں میں اور نہ زمین میں وہ پاک ہے اور برتر ہے اس سے جسکو شریک کرتے ہیں [۳۲]', 'And they worship besides Allah things that hurt them not, nor profit them, and they say: \"These are our intercessors with Allah.\" Say: \"Do you inform Allah of that which He knows not in the heavens and on the earth?\" Glorified and Exalted be He above all that which they associate as partners with Him!', 'Beside Allah, they worship those who can neither harm nor benefit them, and they say, “These are our intercessors with Allah.” Say, “Are you informing Allah of what He does not know as existing in the heavens or on the earth?” Pure is He, and far higher than what they associate with Him.'),
(1383, 10, 19, 2, 7, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ مَا کَانَ النَّاسُ اِلَّاۤ  اُمَّۃً  وَّاحِدَۃً فَاخۡتَلَفُوۡا ؕ وَ لَوۡ  لَا کَلِمَۃٌ سَبَقَتۡ مِنۡ رَّبِّکَ لَقُضِیَ بَیۡنَہُمۡ فِیۡمَا فِیۡہِ  یَخۡتَلِفُوۡنَ ﴿۱۹﴾', 'اور سب لوگ پہلے ایک ہی امت یعنی ایک ہی ملت پر تھے۔پھر جدا جدا ہو گئے۔ اور اگر ایک بات جو تمہارے پروردگار کی طرف سے پہلے ہی طے نہ ہو چکی ہوتی تو جن باتوں میں وہ اختلاف کرتے ہیں ان میں فیصلہ کر دیا جاتا۔', 'اور لوگ جو ہیں سو ایک ہی امت ہیں پیچھے جدا جدا ہو گئے اور اگر نہ ایک بات پہلے ہو چکتی تیرے رب کی تو فیصلہ ہو جاتا ان میں جس بات میں کہ اختلاف کر رہے ہیں [۳۳]', 'Mankind were but one community (i.e. on one religion - Islamic Monotheism), then they differed (later), and had not it been for a Word that went forth before from your Lord, it would have been settled between them regarding what they differed.', 'All the people were no more than a single community; later, they differed. But for a word from your Lord that had already come to pass, a decisive judgment would have been made about their mutual differences.'),
(1384, 10, 20, 2, 7, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ یَقُوۡلُوۡنَ لَوۡ لَاۤ  اُنۡزِلَ عَلَیۡہِ اٰیَۃٌ مِّنۡ رَّبِّہٖ ۚ فَقُلۡ  اِنَّمَا الۡغَیۡبُ لِلّٰہِ فَانۡتَظِرُوۡا ۚ اِنِّیۡ  مَعَکُمۡ  مِّنَ  الۡمُنۡتَظِرِیۡنَ ﴿٪۲۰﴾', 'اور کہتے ہیں کہ اس پر اسکے پروردگار کی طرف سے کوئی نشانی کیوں نازل نہیں ہوئی؟ کہدو کہ غیب کا علم تو اللہ ہی کو ہے سو تم انتظار کرو میں بھی تمہارے ساتھ انتظار کرتا ہوں۔', 'اور کہتے ہیں کیوں نہ اتری اس پر ایک نشانی اس کے رب سے سو تو کہہ دے کہ غیب کی بات اللہ ہی جانے سو منتظر رہو میں بھی تمہارے ساتھ انتظار کرتا ہوں [۳۴]', 'And they say: \"How is it that not a sign is sent down on him from his Lord?\" Say: \"The unseen belongs to Allah Alone, so wait you, verily I am with you among those who wait (for Allahs Judgement).\"', 'And they say, “Why is it that no sign has been sent down to him from his Lord?” Say, “The Unseen is only for Allah. So, wait. I am waiting with you.”'),
(1385, 10, 21, 3, 8, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ اِذَاۤ  اَذَقۡنَا النَّاسَ رَحۡمَۃً  مِّنۡۢ بَعۡدِ ضَرَّآءَ  مَسَّتۡہُمۡ  اِذَا لَہُمۡ  مَّکۡرٌ  فِیۡۤ  اٰیَاتِنَا ؕ قُلِ اللّٰہُ  اَسۡرَعُ مَکۡرًا ؕ اِنَّ رُسُلَنَا یَکۡتُبُوۡنَ مَا تَمۡکُرُوۡنَ ﴿۲۱﴾', 'اور جب ہم لوگوں کو تکلیف پہنچے کے بعد اپنی رحمت سے آسائش کا مزہ چکھاتے ہیں تو وہ ہماری آیتوں میں حیلے کرنے لگتے ہیں کہدو کہ اللہ بہت جلد تدبیر کرنے والا ہے اور جو حیلے تم کرتے ہو ہمارے فرشتے انکو لکھتے جاتے ہیں۔', 'اور جب چکھائیں ہم لوگوں کو مزا اپنی رحمت کا بعد ایک تکلیف کے جو ان کو پہنچی تھی اسی وقت بنانے لگیں حیلے ہماری قدرتوں میں کہہ دے کہ اللہ سب سے جلد بنا سکتا ہے حیلے تحقیق ہمارے فرشتے لکھتے ہیں حیلہ بازی تمہاری [۳۵]', 'And when We let mankind taste of mercy after some adversity has afflicted them, behold! They take to plotting against Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.)! Say: \"Allah is more Swift in planning!\" Certainly, Our Messengers (angels) record all of that which you plot.', 'Once We cause people to taste a blessing after a hardship having afflicted them, they at once start devising plans against Our verses. Say, Allah is swifter in implementing His plan. Indeed, Our messengers (angels) record whatever you intrigue.'),
(1386, 10, 22, 3, 8, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'ہُوَ الَّذِیۡ یُسَیِّرُکُمۡ فِی الۡبَرِّ وَ الۡبَحۡرِ ؕ حَتّٰۤی اِذَا کُنۡتُمۡ فِی الۡفُلۡکِ ۚ وَ  جَرَیۡنَ بِہِمۡ بِرِیۡحٍ طَیِّبَۃٍ وَّ فَرِحُوۡا بِہَا جَآءَتۡہَا رِیۡحٌ عَاصِفٌ وَّ جَآءَہُمُ الۡمَوۡجُ مِنۡ کُلِّ مَکَانٍ وَّ ظَنُّوۡۤا اَنَّہُمۡ اُحِیۡطَ بِہِمۡ ۙ دَعَوُا اللّٰہَ  مُخۡلِصِیۡنَ لَہُ الدِّیۡنَ ۬ۚ  لَئِنۡ اَنۡجَیۡتَنَا مِنۡ ہٰذِہٖ لَنَکُوۡنَنَّ  مِنَ  الشّٰکِرِیۡنَ ﴿۲۲﴾', 'وہی تو ہے جو تم کو جنگل اور دریا میں چلنے پھرنے اور سیر کرنے کی توفیق دیتا ہے۔ یہاں تک کہ جب تم کشتیوں میں سوار ہوتے ہو اور کشتیاں خوشگوار ہوا کی مدد سے سواروں کو لے کر چلنے لگتی ہیں اور وہ اس پر خوش ہوتے ہیں تو ناگہاں زناٹے کی ہوا چل پڑتی ہے اور لہریں ہر طرف سے ان پر جوش مارتی ہوئی آنے لگتی ہیں اور وہ خیال کرتے ہیں کہ اب تو لہروں میں گھر گئے تو اس وقت خالص اللہ ہی کی عبادت کر کے اس سے دعا مانگنے لگتے ہیں کہ اے اللہ اگر تو ہم کو اس سے نجات بخشے تو ہم تیرے بہت ہی شکرگذار ہوں۔', 'وہی تم کو پھراتا ہے جنگل اور دریا میں یہاں تک کہ جب تم بیٹھے کشتیوں میں اور لے کر چلیں وہ لوگوں کو اچھی ہوا سے اور خوش ہوئے اس سے آئی کشتیوں پر ہوا تند اور آئی ان پر موج ہر جگہ سے اور جان لیا انہوں نےکہ وہ گھر گئے پکارنے لگے اللہ کو خالص ہو کر اس کی بندگی میں اگر تو نے بچا لیا ہم کو اس سے تو بیشک ہم رہیں گے شکر گذار', 'He it is Who enables you to travel through land and sea, till when you are in the ships and they sail with them with a favourable wind, and they are glad therein, then comes a stormy wind and the waves come to them from all sides, and they think that they are encircled therein, they invoke Allah, making their Faith pure for Him Alone, saying: \"If You (Allah) deliver us from this, we shall truly be of the grateful.\"', 'He is the One who enables you to travel on land and at sea, until when you are aboard the boats, and they sail with those on board, under a favorable wind, and they are pleased with it, there comes upon them a violent wind, and the wave comes upon them from every direction, and they think that they are surrounded from all sides, they pray to Allah, having faith in Him alone, (and say,) “If You deliver us from this, we shall be grateful indeed.”'),
(1387, 10, 23, 3, 8, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'فَلَمَّاۤ  اَنۡجٰہُمۡ  اِذَا ہُمۡ یَبۡغُوۡنَ فِی الۡاَرۡضِ بِغَیۡرِ الۡحَقِّ ؕ یٰۤاَیُّہَا النَّاسُ  اِنَّمَا بَغۡیُکُمۡ عَلٰۤی اَنۡفُسِکُمۡ ۙ مَّتَاعَ  الۡحَیٰوۃِ الدُّنۡیَا ۫ ثُمَّ  اِلَیۡنَا مَرۡجِعُکُمۡ فَنُنَبِّئُکُمۡ بِمَا کُنۡتُمۡ تَعۡمَلُوۡنَ ﴿۲۳﴾', 'پھر جب وہ انکو نجات دے دیتا ہے تو ملک میں ناحق شرارت کرنے لگتے ہیں۔ لوگو! تمہاری شرارت کا وبال تمہاری ہی جانوں پر ہو گا تم دنیا کی زندگی کے فائدے اٹھا لو پھر تم کو ہمارے ہی پاس لوٹ کر آنا ہے۔ اس وقت ہم تمکو بتائیں گے جو کچھ تم کیا کرتے تھے۔', 'پھر جب بچا دیا ان کو اللہ نے لگے شرارت کرنے اسی وقت زمین میں ناحق کی [۳۶] سنو لوگو تمہاری شرارت ہے تمہی پر نفع اٹھا لو دنیا کی زندگانی کا پھر ہمارے پاس ہے تم کو لوٹ کر آنا پھر ہم بتلا دیں گے جو کچھ کہ تم کرتے تھے [۳۷]', 'But when He delivered them, behold! They rebel (disobey Allah) in the earth wrongfully. O mankind! Your rebellion (disobedience to Allah) is only against your ownselves, - a brief enjoyment of this worldly life, then (in the end) unto Us is your return, and We shall inform you that which you used to do.', 'But when He delivers them, they at once start rebelling on the earth wrongfully. O people, your rebellion is, in fact, against your own selves. It is only worldly life that you are enjoying. Thereafter, it is to Us that you have to return; then We will tell you what you have been doing.'),
(1388, 10, 24, 3, 8, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'اِنَّمَا مَثَلُ الۡحَیٰوۃِ الدُّنۡیَا کَمَآءٍ اَنۡزَلۡنٰہُ مِنَ السَّمَآءِ فَاخۡتَلَطَ بِہٖ نَبَاتُ الۡاَرۡضِ مِمَّا یَاۡکُلُ النَّاسُ وَ الۡاَنۡعَامُ ؕ حَتّٰۤی اِذَاۤ اَخَذَتِ الۡاَرۡضُ زُخۡرُفَہَا وَ ازَّیَّنَتۡ وَ ظَنَّ  اَہۡلُہَاۤ   اَنَّہُمۡ قٰدِرُوۡنَ عَلَیۡہَاۤ ۙ اَتٰہَاۤ  اَمۡرُنَا لَیۡلًا اَوۡ نَہَارًا فَجَعَلۡنٰہَا حَصِیۡدًا  کَاَنۡ لَّمۡ تَغۡنَ بِالۡاَمۡسِ ؕ کَذٰلِکَ نُفَصِّلُ الۡاٰیٰتِ لِقَوۡمٍ  یَّتَفَکَّرُوۡنَ ﴿۲۴﴾', 'دنیا کی زندگی کی مثال مینہ کی سی ہے کہ ہم نے اسکو آسمان سے برسایا۔ پھر اسکے ساتھ ملا جلا سبزہ جسے آدمی اور جانور کھاتے ہیں نکلا یہاں تک کہ زمین سبزے سے خوشنما اور آراستہ ہو گئ اور زمین والوں نے خیال کیا کہ وہ اس پر پوری دسترس رکھتے ہیں ناگہاں رات کو یا دن کو ہمارا حکم عذاب آ پہنچا تو ہم نے اسکو کاٹ کر ایسا کر ڈالا کہ گویا کل وہاں کچھ تھا ہی نہیں۔ جو لوگ غور کرنے والے ہیں انکے لئے ہم اپنی قدرت کی نشانیاں اسی طرح کھول کھول کر بیان کرتے ہیں۔', 'دنیا کی زندگانی کی وہی مثل ہے جیسے ہم نے پانی اتارا آسمان سے پھر رلا ملا نکلا اس سے سبزہ زمین کا جو کہ کھائیں آدمی اور جانور [۳۸] یہاں تک کہ جب پکڑی زمین نے رونق اور مزین ہو گئی اور خیال کیا زمین والوں نے کہ یہ ہمارے ہاتھ لگے گی [۳۹] ناگاہ پہنچا اس پر ہمارا حکم رات کو یا دن کو پھر کر ڈالا اس کو کاٹ کر ڈھیر گویا کل یہاں نہ تھی آبادی اسی طرح ہم کھول کر بیان کرتے ہیں نشانیوں کو ان لوگوں کے سامنے جو غور کرتے ہیں [۴۰]', 'Verily the likeness of (this) worldly life is as the water (rain) which We send down from the sky, so by it arises the intermingled produce of the earth of which men and cattle eat until when the earth is clad with its adornments and is beautified, and its people think that they have all the powers of disposal over it, Our Command reaches it by night or by day and We make it like a clean-mown harvest, as if it had not flourished yesterday! Thus do We explain the Ayat (proofs, evidences, verses, lessons, signs, revelations, laws, etc.) in detail for the people who reflect.', 'The example of worldly life is just like the water We sent down from the sky, then the vegetation of the earth grew with it, which is (meant to be) eaten by men and cattle, until when the earth took on its ornament and was fully adorned, and its people thought that they had control over it, Our command came to it at night or by day, and We turned it into a stubble, as if it had not been there a day earlier. This is how We elaborate the verses for a people who reflect.'),
(1389, 10, 25, 3, 8, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ اللّٰہُ یَدۡعُوۡۤا اِلٰی دَارِ السَّلٰمِ ؕ وَ یَہۡدِیۡ مَنۡ یَّشَآءُ  اِلٰی صِرَاطٍ مُّسۡتَقِیۡمٍ ﴿۲۵﴾', 'اور اللہ سلامتی کے گھر کی طرف بلاتا ہے اور جسکو چاہتا ہے سیدھا رستہ دکھاتا ہے۔', 'اور اللہ بلاتا ہے سلامتی کے گھر کی طرف اور دکھلاتا ہے جس کو چاہے راستہ سیدھا [۴۱]', 'Allah calls to the home of peace (i.e. Paradise, by accepting Allahs religion of Islamic Monotheism and by doing righteous good deeds and abstaining from polytheism and evil deeds) and guides whom He wills to a Straight Path.', 'Allah invites (people) to the Abode of Peace and brings whom He wills to a straight path.'),
(1390, 10, 26, 3, 8, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'لِلَّذِیۡنَ اَحۡسَنُوا الۡحُسۡنٰی وَ زِیَادَۃٌ ؕ وَ لَا یَرۡہَقُ وُجُوۡہَہُمۡ قَتَرٌ وَّ لَا ذِلَّۃٌ ؕ اُولٰٓئِکَ اَصۡحٰبُ الۡجَنَّۃِ ۚ ہُمۡ فِیۡہَا خٰلِدُوۡنَ ﴿۲۶﴾', 'جن لوگوں نے نیکوکاری کی ان کے لئے بھلائی ہے اور مزید اور بھی۔ اور انکے چہروں پر نہ تو سیاہی چھائے گی اور نہ رسوائی۔ یہی جنتی ہیں کہ اس میں ہمیشہ رہیں گے۔', 'جنہوں نے کی بھلائی انکے لئے ہے بھلائی اور زیادتی [۴۲] اور نہ چڑھے گی ان کے منہ پر سیاہی اور نہ رسوائی وہ ہیں جنت والے وہ اسی میں رہا کریں گے [۴۳]', 'For those who have done good is the best (reward, i.e. Paradise) and even more (i.e. having the honour of glancing at the Countenance of Allah Ìá ÌáÇáå) Neither darkness nor dust nor any humiliating disgrace shall cover their faces. They are the dwellers of Paradise, they will abide therein forever.', 'For those who do good there is the best, and something more. Neither gloom shall cover their faces, nor disgrace. Those are the people of Paradise. Therein they shall live forever.'),
(1391, 10, 27, 3, 8, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ الَّذِیۡنَ کَسَبُوا السَّیِّاٰتِ جَزَآءُ سَیِّئَۃٍۭ بِمِثۡلِہَا ۙ وَ تَرۡہَقُہُمۡ ذِلَّۃٌ ؕ مَا لَہُمۡ مِّنَ اللّٰہِ مِنۡ عَاصِمٍ ۚ کَاَنَّمَاۤ  اُغۡشِیَتۡ وُجُوۡہُہُمۡ قِطَعًا مِّنَ الَّیۡلِ مُظۡلِمًا ؕ اُولٰٓئِکَ اَصۡحٰبُ النَّارِ ۚ ہُمۡ فِیۡہَا خٰلِدُوۡنَ ﴿۲۷﴾', 'اور جنہوں نے برے کام کئے تو برائی کا بدلہ ویسا ہی ہوگا اور انکے چہروں پر ذلت چھا جائے گی۔ اور کوئی انکو اللہ سے بچانے والا نہ ہوگا۔ انکے چہروں کی سیاہی کا یہ عالم ہوگا کہ ان پر گویا اندھیری رات کے ٹکڑے اوڑھا دیئے گئے ہیں۔ یہی دوزخی ہیں کہ ہمیشہ اس میں رہیں گے۔', 'اور جنہوں نے کمائیں برائیاں بدلا ملے برائی کا اس کے برابر [۴۴] اور ڈھانک لے گی انکو رسوائی کوئی نہیں انکو اللہ سے بچانے والا گویا کہ ڈھانک دیے گئے انکے چہرے اندھیری رات کے ٹکڑوں سے [۴۵] وہ ہیں دوزخ والے وہ اسی میں رہا کریں گے', 'And those who have earned evil deeds, the recompense of an evil deed is the like thereof, and humiliating disgrace will cover them (their faces). No defender will they have from Allah. Their faces will be covered, as it were, with pieces from the darkness of night. They are dwellers of the Fire, they will abide therein forever.', 'As for those who commit evils, the recompense of each evil shall be similar to that evil, and disgrace shall cover them. For them, there is none to save from Allah. Their faces will seem to be covered with layers of a dark night. Those are the people of the Fire. Therein they shall live forever.'),
(1392, 10, 28, 3, 8, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ یَوۡمَ نَحۡشُرُہُمۡ جَمِیۡعًا ثُمَّ نَقُوۡلُ لِلَّذِیۡنَ اَشۡرَکُوۡا مَکَانَکُمۡ اَنۡتُمۡ وَ شُرَکَآؤُکُمۡ ۚ فَزَیَّلۡنَا بَیۡنَہُمۡ وَ قَالَ شُرَکَآؤُہُمۡ مَّا کُنۡتُمۡ  اِیَّانَا تَعۡبُدُوۡنَ ﴿۲۸﴾', 'اور جس دن ہم ان سب کو جمع کریں گے پھر مشرکوں سے کہیں گے کہ تم اور تمہارے شریک اپنی اپنی جگہ ٹھہرے رہو تو ہم ان میں جدائی ڈال دیں گے اور ان کے شریک ان سے کہیں گے کہ تم ہم کو تو نہیں پوجا کرتے تھے۔', 'اور جس دن جمع کریں گے ہم ان سب کو پھر کہیں گے شرک کرنے والوں کو کھڑے ہو اپنی اپنی جگہ تم اور تمہارے شریک [۴۶] پھر تڑا دیں گے ہم آپس میں انکو اور کہیں گے ان کے شریک تم ہماری تو بندگی نہ کرتے تھے', 'And the Day whereon We shall gather them all together, then We shall say to those who did set partners in worship with Us: \"Stop at your place! You and your partners (whom you had worshipped in the worldly life).\" then We shall separate them, and their (Allahs so-called) partners shall say: \"It was not us that you used to worship.\"', 'And (be mindful of) the Day when We shall gather them together, then We shall say to those who associated partners with Allah, “Wait in your place, you and your associate-gods.” Then We will cause a split between them, and their associate-gods will say, “It was not us that you worshipped.'),
(1393, 10, 29, 3, 8, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'فَکَفٰی بِاللّٰہِ شَہِیۡدًۢا بَیۡنَنَا وَ بَیۡنَکُمۡ اِنۡ  کُنَّا عَنۡ عِبَادَتِکُمۡ  لَغٰفِلِیۡنَ ﴿۲۹﴾', 'بس ہمارے اور تمہارے درمیان اللہ ہی گواہ کافی ہے۔ ہم تمہاری پرستش سے بالکل بیخبر تھے۔', 'سو اللہ کافی ہے شاہد ہمارے اور تمہارے بیچ میں ہم کو تمہاری بندگی کی خبر نہ تھی [۴۷]', '\"So sufficient is Allah for a witness between us and you, that We indeed knew nothing of your worship of us.\"', 'So, Allah is enough as witness between us and between you. We were totally unaware of your worship.”'),
(1394, 10, 30, 3, 8, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'ہُنَالِکَ تَبۡلُوۡا کُلُّ نَفۡسٍ مَّاۤ  اَسۡلَفَتۡ وَ رُدُّوۡۤا اِلَی اللّٰہِ مَوۡلٰىہُمُ الۡحَقِّ وَ ضَلَّ عَنۡہُمۡ  مَّا  کَانُوۡا  یَفۡتَرُوۡنَ ﴿٪۳۰﴾', 'وہاں ہر شخص اپنے اعمال کی جو اس نے پہلے کئے ہوں گے جانچ کر لے گا اور وہ اپنے سچے مالک اللہ کی طرف لوٹائے جائیں گے اور جو کچھ وہ جھوٹ باندھا کرتے تھے سب ان سے جاتا رہے گا۔', 'وہاں جانچ لے گا ہر کوئی جو اس نے پہلے کیا تھا اور رجوع کریں گے اللہ کی طرف جو سچا مالک ہے ان کا اور جاتا رہے گا انکے پاس سے جو جھوٹ باندھا کرتےتھے [۴۸]', 'There! Every person will know (exactly) what (all) he had earned before, and they will be brought back to Allah, their rightful Lord (Maula), and their invented false deities will vanish from them.', 'Thereupon, everyone shall assess what one had sent ahead, and they will be sent back to Allah, their true Lord, and whatever they used to fabricate will vanish from them.'),
(1395, 10, 31, 4, 9, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'قُلۡ مَنۡ یَّرۡزُقُکُمۡ مِّنَ السَّمَآءِ وَ الۡاَرۡضِ اَمَّنۡ یَّمۡلِکُ السَّمۡعَ وَ الۡاَبۡصَارَ وَ مَنۡ یُّخۡرِجُ الۡحَیَّ مِنَ الۡمَیِّتِ وَ یُخۡرِجُ الۡمَیِّتَ مِنَ الۡحَیِّ وَ مَنۡ یُّدَبِّرُ الۡاَمۡرَ ؕ فَسَیَقُوۡلُوۡنَ اللّٰہُ ۚ فَقُلۡ  اَفَلَا  تَتَّقُوۡنَ ﴿۳۱﴾', 'اے پیغمبر کہو کہ تم کو آسمان اور زمین میں رزق کون دیتا ہے یا تمہارے کانوں اور آنکھوں کا مالک کون ہے اور بےجان سے جاندار کون پیدا کرتا ہے اور جاندار سے بےجان کون پیدا کرتا ہے اور دنیا کے کاموں کا انتظام کون کرتا ہے؟ تو یہی کہیں گے کہ اللہ۔ تو کہو کہ پھر تم اللہ سے ڈرتے کیوں نہیں۔', 'تو پوچھ کون روزی دیتا ہے تم کو آسمان سے اور زمین سے [۴۹] یا کون مالک ہے کان اور آنکھوں کا [۵۰] اور کون نکالتا ہے زندہ کو مردہ سے اور نکالتا ہے مردہ کو زندہ سے [۵۱] اور کون تدبیر کرتا ہے کاموں کی [۵۲] سو بو ل اٹھیں گے کہ اللہ تو تو کہہ پھر ڈرتے نہیں ہو', 'Say (O MuhammadSAW ): \"Who provides for you from the sky and from the earth? Or who owns hearing and sight? And who brings out the living from the dead and brings out the dead from the living? And who disposes the affairs?\" They will say: \"Allah.\" Say: \"Will you not then be afraid of Allahs Punishment (for setting up rivals in worship with Allah)?\"', 'Say, “Who gives you sustenance from the heavens and the earth? Or, who controls the (powers of) hearing and seeing? And who brings forth the living from the dead, and brings forth the dead from the living? And who manages everything?” They will say, “Allah.” Then, (you) say, “Would you not, then, fear Allah (by desisting from holding others as gods)?”'),
(1396, 10, 32, 4, 9, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'فَذٰلِکُمُ  اللّٰہُ  رَبُّکُمُ الۡحَقُّ ۚ فَمَا ذَا بَعۡدَ الۡحَقِّ  اِلَّا الضَّلٰلُ ۚۖ فَاَنّٰی تُصۡرَفُوۡنَ ﴿۳۲﴾', 'یہی اللہ تو تمہارا حقیقی پروردگار ہے اور حق بات کے ظاہر ہونے کے بعد گمراہی کے سوا ہے ہی کیا؟ تو تم کہاں پھرے جاتے ہو؟', 'سو یہ اللہ ہے رب تمہارا سچا پھر کیا رہ گیا سچ کے پیچھے مگر بھٹکنا سو کہاں سے لوٹے جاتے ہو [۵۳]', 'Such is Allah, your Lord in truth. So after the truth, what else can there be, save error? How then are you turned away?', 'So, that is Allah, your Lord in truth. And what is there after truth but error? To where, then, are you being diverted (by your whims)?'),
(1397, 10, 33, 4, 9, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'کَذٰلِکَ حَقَّتۡ کَلِمَتُ رَبِّکَ عَلَی الَّذِیۡنَ فَسَقُوۡۤا  اَنَّہُمۡ  لَا  یُؤۡمِنُوۡنَ ﴿۳۳﴾', 'اسی طرح اللہ کا ارشاد ان نافرمانوں کے حق میں ثابت ہو کر رہا کہ یہ ایمان نہیں لائیں گے۔', 'اسی طرح ٹھیک آئی بات تیرے رب کی ان نافرمانوں پر کہ یہ ایمان نہ لائیں گے [۵۴]', 'Thus is the Word of your Lord justified against those who rebel (disobey Allah) that they will not believe (in the Oneness of Allah and in Muhammad SAW as the Messenger of Allah).', 'This is how the Word of your Lord has come true about the sinners that they will not believe.'),
(1398, 10, 34, 4, 9, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'قُلۡ ہَلۡ مِنۡ شُرَکَآئِکُمۡ مَّنۡ یَّبۡدَؤُا الۡخَلۡقَ ثُمَّ یُعِیۡدُہٗ ؕ قُلِ اللّٰہُ یَبۡدَؤُا الۡخَلۡقَ ثُمَّ  یُعِیۡدُہٗ   فَاَنّٰی تُؤۡفَکُوۡنَ ﴿۳۴﴾', 'ان سے پوچھو کہ بھلا تمہارے شریکوں میں کوئی ایسا ہے کہ خلقت کو پہلی بار پیدا کرے اور پھر اسکو دوبارہ بنائے کہدو کہ اللہ ہی پہلی بار پیدا کرتا ہے پھر وہی اسکو دوبارہ پیدا کرے گا تو تم کہاں الٹے جارہے ہو۔', 'پوچھ کوئی ہے تمہارے شریکوں میں جو پیدا کرے خلق کو پھر دوبارہ زندہ کرے تو کہہ اللہ پیدا کرتا ہے پھر اس کو دہرائے گا سو کہاں سے پلٹے جاتے ہو [۵۵]', 'Say: \"Is there of your (Allahs so-called) partners one that originates the creation and then repeats it?\" Say: \"Allah originates the creation and then He repeats it. Then how are you deluded away (from the truth)?\"', 'Say, “Is there any one from your ‘associate-gods’ who originates the creation, then brings it again? To where then, are you being turned away (by your desires)?”'),
(1399, 10, 35, 4, 9, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'قُلۡ ہَلۡ مِنۡ شُرَکَآئِکُمۡ مَّنۡ یَّہۡدِیۡۤ  اِلَی الۡحَقِّ ؕ قُلِ اللّٰہُ یَہۡدِیۡ لِلۡحَقِّ ؕ اَفَمَنۡ یَّہۡدِیۡۤ اِلَی الۡحَقِّ اَحَقُّ اَنۡ یُّتَّبَعَ اَمَّنۡ لَّا یَہِدِّیۡۤ  اِلَّاۤ  اَنۡ یُّہۡدٰی ۚ فَمَا  لَکُمۡ ۟ کَیۡفَ  تَحۡکُمُوۡنَ ﴿۳۵﴾', 'پوچھو کہ بھلا تمہارے شریکوں میں کون ایسا ہے کہ حق کا رستہ دکھائے کہدو کہ اللہ ہی حق کا رستہ دکھاتا ہے بھلا جو حق کا رستہ دکھائے وہ اس قابل ہے کہ اسکی پیروی کی جائے۔ یا وہ کہ جب تک کوئی اسے رستہ نہ بتائے وہ رستہ نہ پائے۔ تو تم کو کیا ہوا ہے کیسا انصاف کرتے ہو؟', 'پوچھ کوئی ہے تمہارے شریکوں میں جو راہ بتلائے صحیح تو کہہ اللہ راہ بتلاتا ہے صحیح تو اب جو کوئی راہ بتائے صحیح اسکی بات ماننی چاہئے یا اسکی جو آپ نہ پائے راہ مگر جب کوئی اور اسکو راہ بتلائے سو کیا ہو گیا تم کو کیسا انصاف کرتے ہو [۵۶]', 'Say: \"Is there of your (Allahs so-called) partners one that guides to the truth?\" Say: \"It is Allah Who guides to the truth. Is then He, Who gives guidance to the truth, more worthy to be followed, or he who finds not guidance (himself) unless he is guided? Then, what is the matter with you? How judge you?\"', 'Say, “Is there any one from your associate-gods who guides to the truth?” Say, “Allah guides to the truth. Is, then, He who guides to the truth more worthy of being obeyed, or he who has no guidance at all unless he is guided (by someone else)? So, what has happened to you? How do you judge things?'),
(1400, 10, 36, 4, 9, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ مَا یَتَّبِعُ اَکۡثَرُہُمۡ اِلَّا ظَنًّا ؕ اِنَّ الظَّنَّ لَا یُغۡنِیۡ مِنَ الۡحَقِّ شَیۡئًا ؕ اِنَّ اللّٰہَ  عَلِیۡمٌۢ  بِمَا یَفۡعَلُوۡنَ ﴿۳۶﴾', 'اور ان میں کے اکثر محض گمان کی پیروی کرتے ہیں۔ اور کچھ شک نہیں کہ گمان حق کے مقابلے میں کچھ بھی کارآمد نہیں ہو سکتا۔ بیشک اللہ تمہارے سب اعمال سے واقف ہے۔', 'اور وہ اکثر چلتے ہیں محض اٹکل پر سو اٹکل کام نہیں دیتی حق بات میں کچھ بھی [۵۷] اللہ کو خوب معلوم ہے جو کچھ وہ کرتے ہیں', 'And most of them follow nothing but conjecture. Certainly, conjecture can be of no avail against the truth. Surely, Allah is All-Aware of what they do.', 'Most of them follow nothing but conjectures. Surely, conjectures are of no avail in the matter of truth at all. Certainly, Allah is fully aware of what they do.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1401, 10, 37, 4, 9, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ مَا کَانَ ہٰذَا الۡقُرۡاٰنُ اَنۡ یُّفۡتَرٰی مِنۡ دُوۡنِ اللّٰہِ  وَ لٰکِنۡ تَصۡدِیۡقَ الَّذِیۡ بَیۡنَ یَدَیۡہِ وَ تَفۡصِیۡلَ الۡکِتٰبِ لَا رَیۡبَ فِیۡہِ  مِنۡ  رَّبِّ  الۡعٰلَمِیۡنَ ﴿۟۳۷﴾', 'اور یہ قرآن ایسا نہیں کہ اللہ کے سوا کوئی اسکو اپنی طرف سے بنا لائے۔ ہاں یہ اللہ کا کلام ہے جو کتابیں اس سے پہلے کی ہیں۔ انکی تصدیق کرتا ہے۔ اور انہی کتابوں کی اس میں تفصیل ہے اس میں کچھ شک نہیں کہ یہ رب العالمین کی طرف سے نازل ہوا ہے۔', 'اور وہ نہیں یہ قرآن کہ کوئی بنا لے اللہ کےسوا [۵۸] اور لیکن تصدیق کرتا ہے اگلے کلام کی [۵۹] اور بیان کرتا ہے ان چیزوں کو جو تم پر لکھی گئیں جس میں کوئی شبہ نہیں پروردگار عالم کی طرف سے [۶۰]', 'And this Quran is not such as could ever be produced by other than Allah (Lord of the heavens and the earth), but it is a confirmation of (the revelation) which was before it (i.e. the Taurat (Torah), and the Injeel (Gospel), etc.), and a full explanation of the Book (i.e. laws and orders, etc, decreed for mankind) - wherein there is no doubt from the the Lord of the Alameen (mankind, jinns,and all that exists).', 'And this Qur’ān is not such as could have been made up by someone without (having been revealed by) Allah, but it is a confirmation of that (discourse) which had been (revealed) before it, and an elaboration of what is prescribed. There is no doubt in it. It is from the Lord of all the worlds.'),
(1402, 10, 38, 4, 9, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'اَمۡ یَقُوۡلُوۡنَ افۡتَرٰىہُ ؕ قُلۡ فَاۡتُوۡا بِسُوۡرَۃٍ مِّثۡلِہٖ وَ ادۡعُوۡا مَنِ اسۡتَطَعۡتُمۡ مِّنۡ دُوۡنِ اللّٰہِ  اِنۡ  کُنۡتُمۡ  صٰدِقِیۡنَ ﴿۳۸﴾', 'کیا یہ لوگ کہتے ہیں کہ پیغمبر نے اسے خود ہی گھڑ لیا ہے کہدو کہ اگر سچے ہو تو تم بھی اس طرح کی ایک سورت بنا لاؤ اور اللہ کے سوا جنکو تم بلا سکو بلا بھی لو۔', 'کیا لوگ کہتےہیں کہ یہ بنا لایا ہے تو کہہ دے تم لے آؤ ایک ہی سورت ایسی اور بلا لو جس کو بلا سکو اللہ کے سوا اگر تم سچے ہو [۶۱]', 'Or do they say: \"He (Muhammad SAW) has forged it?\" Say: \"Bring then a Soorah (chapter) like unto it, and call upon whomsoever you can, besides Allah, if you are truthful!\"', 'Or, do they say that he has made it up? Say, “Then, bring a Sūrah like this, and call whomsoever you can beside Allah, if you are true.”'),
(1403, 10, 39, 4, 9, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'بَلۡ  کَذَّبُوۡا بِمَا لَمۡ یُحِیۡطُوۡا بِعِلۡمِہٖ وَ لَمَّا یَاۡتِہِمۡ تَاۡوِیۡلُہٗ ؕ  کَذٰلِکَ  کَذَّبَ  الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ فَانۡظُرۡ کَیۡفَ کَانَ عَاقِبَۃُ  الظّٰلِمِیۡنَ ﴿۳۹﴾', 'حقیقت یہ ہے کہ جس چیز کے علم پر یہ قابو نہیں پا سکے اسکو نادانی سے جھٹلا دیا اور ابھی اس کی حقیقت ان پر کھلی ہی نہیں۔ اسی طرح جو لوگ ان سے پہلے تھے انہوں نے جھٹلایا تھا سو دیکھ لو کہ ظالموں کا کیسا انجام ہوا؟', 'بات یہ ہے کہ جھٹلانے لگے جس کے سمجھنے پر انہوں نےقابو نہ پایا [۶۲] اور ابھی آئی نہیں اسکی حقیقت [۶۳] اسی طرح جھٹلاتے رہے ان سے اگلے سو دیکھ لے کیسا ہوا انجام گنہگاروں کا', 'Nay, they deny that; the knowledge whereof they could not compass and whereof the interpretation has not yet come unto them. Thus those before them did deny. Then see what was the end of the Zalimoon (polytheists and wrong-doers, etc.)!', 'But they have rejected a thing they could not comprehend with knowledge, while its ultimate end has not appeared to them as yet. Similarly those who passed before them had rejected the truth. So, look how was the fate of the unjust.'),
(1404, 10, 40, 4, 9, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ مِنۡہُمۡ مَّنۡ یُّؤۡمِنُ بِہٖ وَ  مِنۡہُمۡ مَّنۡ لَّا یُؤۡمِنُ بِہٖ ؕ وَ رَبُّکَ اَعۡلَمُ  بِالۡمُفۡسِدِیۡنَ ﴿٪۴۰﴾', 'اور ان میں سے کچھ تو ایسے ہیں کہ اس پر ایمان لے آتے ہیں اور کچھ ایسے ہیں کہ ایمان نہیں لاتے۔ اور تمہارا پروردگار شریروں سے خوب واقف ہے۔', 'اور بعضے ان میں یقین کریں گے قرآن کا اور بعضے یقین نہ کریں گے اور تیرا رب خوب جانتا ہے شرارت والوں کو [۶۴]', 'And of them there are some who believe therein, and of them there are some who believe not therein, and your Lord is All-Aware of the Mufsidoon (evil-doers, liars, etc.).', 'And among them there are those who believe in it, and among them there are others who do not believe in it. And your Lord has the best knowledge about the mischief-makers.'),
(1405, 10, 41, 5, 10, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ اِنۡ کَذَّبُوۡکَ فَقُلۡ لِّیۡ عَمَلِیۡ وَ لَکُمۡ  عَمَلُکُمۡ ۚ اَنۡتُمۡ بَرِیۡٓـــُٔوۡنَ مِمَّاۤ اَعۡمَلُ وَ اَنَا بَرِیۡٓءٌ  مِّمَّا تَعۡمَلُوۡنَ ﴿۴۱﴾', 'اور اگر یہ تمہاری تکذیب کریں تو کہدو کہ مجھ کو میرے اعمال کا بدلہ ملے گا اور تم کو تمہارے اعمال کا تم میرے اعمال کے جوابدہ نہیں ہو اور میں تمہارے اعمال کا جوابدہ نہیں ہوں۔', 'اور اگر تجھ کو جھٹلائیں تو کہہ میرے لئے میرا کام اور تمہارے لئے تمہارا کام تم پر ذمہ نہیں میرے کام کا اور مجھ پر ذمہ نہیں جو تم کرتے ہو [۶۵]', 'And if they belie you, say: \"For me are my deeds and for you are your deeds! You are innocent of what I do, and I am innocent of what you do!\"', 'And if they give the lie to you, say, “For me, my deed, and for you, your deed. You are not accountable for what I do, and I am not accountable for what you do.”'),
(1406, 10, 42, 5, 10, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ مِنۡہُمۡ مَّنۡ یَّسۡتَمِعُوۡنَ اِلَیۡکَ ؕ اَفَاَنۡتَ تُسۡمِعُ الصُّمَّ وَ لَوۡ کَانُوۡا لَا یَعۡقِلُوۡنَ ﴿۴۲﴾', 'اور ان میں بعض ایسے ہیں کہ تمہاری طرف کان لگاتے ہیں تو کیا تم بہروں کو سناؤ گے اگرچہ کچھ بھی سنتے سمجھتے نہ ہوں۔', 'اور بعضے ان میں کان رکھتے ہیں تیری طرف کیا تو سنائے گا بہروں کو اگرچہ ان کو  سمجھ نہ ہو', 'And among them are some who listen to you, but can you make the deaf to hear, even though they apprehend not?', 'And among them there are those who listen to you. Would you, then, make the deaf hear, even though they lack understanding?'),
(1407, 10, 43, 5, 10, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ مِنۡہُمۡ مَّنۡ یَّنۡظُرُ اِلَیۡکَ ؕ اَفَاَنۡتَ تَہۡدِی الۡعُمۡیَ وَ لَوۡ کَانُوۡا لَا یُبۡصِرُوۡنَ ﴿۴۳﴾', 'اور بعض ایسے ہیں کہ تمہاری طرف دیکھتے ہیں تو کیا تم اندھوں کو رستہ دکھاؤ گے اگرچہ کچھ بھی دیکھتے بھالتے نہ ہوں۔', 'اور بعضے ان میں نگاہ کرتے ہیں تیری طرف کیا تو راہ دکھائے گا اندھوں کو اگرچہ وہ سوجھ نہ رکھتے ہوں [۶۶]', 'And among them are some who look at you, but can you guide the blind, even though they see not?', 'And among them there are those who look at you. Would you, then, guide the blind even when they have no insight?'),
(1408, 10, 44, 5, 10, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'اِنَّ اللّٰہَ  لَا یَظۡلِمُ النَّاسَ شَیۡئًا وَّ لٰکِنَّ النَّاسَ اَنۡفُسَہُمۡ یَظۡلِمُوۡنَ ﴿۴۴﴾', 'اللہ تو لوگوں پر ذرا بھی ظلم نہیں کرتا لیکن لوگ خود ہی اپنے آپ پر ظلم کرتے ہیں۔', 'اللہ ظلم نہیں کرتا لوگوں پر کچھ بھی لیکن لوگ اپنے اوپر آپ ظلم کرتے ہیں [۶۷]', 'Truly! Allah wrongs not mankind in aught; but mankind wrong themselves.', 'Surely, Allah does not wrong people at all, but the people do wrong their own selves.'),
(1409, 10, 45, 5, 10, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ یَوۡمَ یَحۡشُرُہُمۡ کَاَنۡ لَّمۡ یَلۡبَثُوۡۤا اِلَّا سَاعَۃً مِّنَ النَّہَارِ یَتَعَارَفُوۡنَ بَیۡنَہُمۡ ؕ قَدۡ خَسِرَ الَّذِیۡنَ  کَذَّبُوۡا بِلِقَآءِ اللّٰہِ  وَ مَا  کَانُوۡا مُہۡتَدِیۡنَ ﴿۴۵﴾', 'اور جس دن اللہ انکو جمع کرے گا تو وہ دنیا کی نسبت ایسا خیال کریں گے کہ گویا وہاں گھڑی بھر دن سے زیادہ رہے ہی نہیں تھے اور آپس میں ایکدوسرے کو شناخت بھی کریں گے۔ جن لوگوں نے اللہ کے روبرو حاضر ہونے کو جھٹلایا وہ خسارے میں پڑ گئے اور راہ یاب نہ ہوئے۔', 'اور جس دن انکو جمع کرے گا گویا وہ نہ رہے تھے مگر ایک گھڑی دن [۶۸] ایک دوسرے کو پہچانیں گے [۶۹] بیشک خسارے میں پڑے جنہوں نے جھٹلایا اللہ سے ملنے کو اور نہ آئے وہ راہ پر [۷۰]', 'And on the Day when He shall gather (resurrect) them together, (it will be) as if they had not stayed (in the life of this world and graves, etc.) but an hour of a day. They will recognise each other. Ruined indeed will be those who denied the meeting with Allah, and were not guided.', 'The Day when He will gather them (in the next life,) they will feel as if they had not stayed (in the world) any longer than a fraction of a day. They will recognize each other. Losers, indeed, are those who deny that they will ever face Allah; they are not on the right path.'),
(1410, 10, 46, 5, 10, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ اِمَّا نُرِیَنَّکَ بَعۡضَ الَّذِیۡ نَعِدُہُمۡ اَوۡ نَتَوَفَّیَنَّکَ فَاِلَیۡنَا مَرۡجِعُہُمۡ ثُمَّ اللّٰہُ شَہِیۡدٌ عَلٰی  مَا یَفۡعَلُوۡنَ ﴿۴۶﴾', 'اور اے پیغمبر اگر ہم کوئی عذاب جس کا ان لوگوں سے وعدہ کرتے ہیں تمہاری آنکھوں کے سامنے نازل کریں یا اس وقت جب ہم تمہیں اٹھا لیں بہرحال انکو ہمارے ہی پاس لوٹ کر آنا ہے پھر جو کچھ یہ کر رہے ہیں اللہ اسکو دیکھ رہا ہے۔', 'اور اگر ہم دکھائیں گے تجھ کو کوئی چیز ان وعدوں میں سے جو کئے ہیں ہم نے ان سے یا وفات دیں تجھ کو سو ہماری ہی طرف ہے ان کو لوٹنا پھر اللہ شاہد ہے ان کاموں پر جو کرتے ہیں [۷۱]', 'Whether We show you (in your lifetime, O Muhammad SAW) some of what We promise them (the torment), - or We cause you to die, - still unto Us is their return, and moreover Allah is Witness over what they used to do.', 'No matter whether We show you (during your life) some of what We warn them of, or We take you back to Us (before it), in any case, they have to return to Us. Then, Allah is witness to what they do.'),
(1411, 10, 47, 5, 10, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ  لِکُلِّ  اُمَّۃٍ  رَّسُوۡلٌ ۚ فَاِذَا جَآءَ رَسُوۡلُہُمۡ قُضِیَ بَیۡنَہُمۡ بِالۡقِسۡطِ وَ ہُمۡ لَا یُظۡلَمُوۡنَ ﴿۴۷﴾', 'اور ہر ایک امت کی طرف پیغمبر بھیجا گیا پھر جب ان کا پیغمبر آ جاتا ہے تو ان میں انصاف کے ساتھ فیصلہ کر دیا جاتا ہے۔ اور ان پر ظلم نہیں کیا جاتا۔', 'اور ہر فرقہ کا ایک رسول ہے پھر جب پہنچا انکے پاس رسول ان کا فیصلہ ہوا ان میں انصاف سے اور ان پر ظلم نہیں ہوتا [۷۲]', 'And for every Ummah (a community or a nation), there is a Messenger; when their Messenger comes, the matter will be judged between them with justice, and they will not be wronged.', 'For every people there is a messenger. So, when their messenger comes, the matter is decided between them with justice, and they are not wronged.'),
(1412, 10, 48, 5, 10, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ یَقُوۡلُوۡنَ مَتٰی ہٰذَا الۡوَعۡدُ  اِنۡ  کُنۡتُمۡ صٰدِقِیۡنَ ﴿۴۸﴾', 'اور یہ کہتے ہیں کہ اگر تم سچے ہو تو جس عذاب کا یہ وعدہ ہے وہ آئے گا کب۔', 'اور کہتے ہیں کب ہے یہ وعدہ اگر تم سچے ہو [۷۳]', 'And they say: \"When will be this promise (the torment or the Day of Resurrection), - if you speak the truth?\"', 'They say, “When will this promise (of punishment to the disbelievers) be fulfilled if you are true?”'),
(1413, 10, 49, 5, 10, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'قُلۡ لَّاۤ  اَمۡلِکُ لِنَفۡسِیۡ ضَرًّا وَّ لَا  نَفۡعًا اِلَّا مَا شَآءَ  اللّٰہُ ؕ لِکُلِّ  اُمَّۃٍ  اَجَلٌ ؕ اِذَا  جَآءَ اَجَلُہُمۡ فَلَا یَسۡتَاۡخِرُوۡنَ سَاعَۃً وَّ لَا  یَسۡتَقۡدِمُوۡنَ ﴿۴۹﴾', 'کہدو کہ میں تو اپنے نقصان اور فائدے کا بھی کچھ اختیار نہیں رکھتا۔ مگر جو اللہ چاہے۔ ہر ایک امت کے لئے موت کا ایک وقت مقرر ہے۔ جب وہ وقت آ جاتا ہے تو ایک گھڑی بھی دیر نہیں کر سکتے اور نہ جلدی کر سکتے ہیں۔', 'تو کہہ میں مالک نہیں اپنے واسطے برے کا نہ بھلے کا مگر جو چاہے اللہ ہر فرقہ کا ایک وعدہ ہے جب آ پہنچے گا ان کا وعدہ پھر نہ پیچھے سرک سکیں گے ایک گھڑی اور نہ آگے سرک سکیں گے [۷۴]', 'Say (O Muhammad SAW): \"I have no power over any harm or profit to myself except what Allah may will. For every Ummah (a community or a nation), there is a term appointed; when their term is reached, neither can they delay it nor can they advance it an hour (or a moment).\" (Tafsir Al-Qurtubee).', 'Say, “I have no power to bring a harm or a benefit to myself, except what Allah wills. For every people there is an appointed time. When their time comes, they are not able to put it off for a moment, nor are they able to go ahead of it.”'),
(1414, 10, 50, 5, 10, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'قُلۡ اَرَءَیۡتُمۡ اِنۡ اَتٰىکُمۡ عَذَابُہٗ بَیَاتًا اَوۡ نَہَارًا مَّاذَا یَسۡتَعۡجِلُ مِنۡہُ الۡمُجۡرِمُوۡنَ ﴿۵۰﴾', 'کہدو کہ بھلا دیکھو تو اگر اس کا عذاب تم پر ناگہاں آجائے رات کو یا دن کو تو پھر گناہگار کس بات کی جلدی کرتے ہیں۔', 'تو کہہ بھلا دیکھو تو اگر آ پہنچے تم پر عذاب اس کا راتوں رات یا دن کو تو کیا کر لیں گے اس سے پہلے گنہگار [۷۵]', 'Say: \"Tell me, - if His torment should come to you by night or by day, - which portion thereof would the Mujrimoon (disbelievers, polytheists, sinners, criminals) hasten on ?\"', 'Say, “Just tell me, if His punishment befalls you at night or by day, what (desirable thing) will it have that the sinners are asking it so hurriedly?'),
(1415, 10, 51, 5, 10, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'اَثُمَّ  اِذَا مَا وَقَعَ اٰمَنۡتُمۡ  بِہٖ ؕ آٰلۡـٰٔنَ  وَ قَدۡ کُنۡتُمۡ  بِہٖ  تَسۡتَعۡجِلُوۡنَ ﴿۵۱﴾', 'کیا جب وہ آ واقع ہو گا تب اس پر ایمان لاؤ گے اس وقت کہا جائے گا کیا اب ایمان لائے؟ اور اسی کے لئے تو تم جلدی مچایا کرتے تھے۔', 'کیاپھر جب عذاب واقع ہو چکے گا تب اس پر یقین کرو گے اب قائل ہوئے اور تم اسی کا تقاضا کرتے تھے [۷۶]', 'Is it then, that when it has actually befallen, that you will believe in it? What! Now (you believe)? And you used (aforetime) to hasten it on!\"', 'Is it only when it befalls you that you will believe in it? (It will be said to you at that time, “Have you believed) now, while you used to demand (in mockery) that it should come sooner?”'),
(1416, 10, 52, 5, 10, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'ثُمَّ  قِیۡلَ  لِلَّذِیۡنَ ظَلَمُوۡا ذُوۡقُوۡا عَذَابَ الۡخُلۡدِ ۚ ہَلۡ تُجۡزَوۡنَ اِلَّا بِمَا کُنۡتُمۡ تَکۡسِبُوۡنَ ﴿۵۲﴾', 'پھر ظالم لوگوں سے کہا جائے گا کہ عذاب دائمی کا مزہ چکھو اب تم انہی اعمال کا بدلہ پاؤ گے جو دنیا میں کرتے رہے۔', 'پھر کہیں گے گنہگاروں کو چکھتے رہو عذاب ہمیشگی کا وہی بدلا ملتا ہے جو کچھ کماتے تھے [۷۷]', 'Then it will be said to them who wronged themselves: \"Taste you the everlasting torment! Are you recompensed (aught) save what you used to earn?\"', 'Then it will be said to the unjust, “Taste the punishment lasting for ever. You shall not be punished except for what you have been earning.”'),
(1417, 10, 53, 5, 10, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ یَسۡتَنۡۢبِئُوۡنَکَ اَحَقٌّ ہُوَ ؕؔ قُلۡ اِیۡ وَ رَبِّیۡۤ  اِنَّہٗ  لَحَقٌّ ۚؕؔ وَ مَاۤ  اَنۡتُمۡ بِمُعۡجِزِیۡنَ ﴿٪۵۳﴾', 'اور اے نبی تم سے دریافت کرتے ہیں کہ آیا یہ سچ ہے کہدو ہاں میرے رب کی قسم یہ سچ ہے اور تم بھاگ کر اللہ کو عاجز نہیں کر سکو گے۔', 'اور تجھ سے خبر پوچھتے ہیں کیا سچ ہے یہ بات تو کہہ البتہ قسم میرے رب کی یہ سچ ہے اور تم تھکا نہ سکو گے [۷۸]', 'And they ask you (O Muhammad SAW) to inform them (saying): \"Is it true (i.e. the torment and the establishment of the Hour; - the Day of Resurrection)?\" Say: \"Yes! By my Lord! It is the very truth! and you cannot escape from it!\"', 'They ask you to tell them whether it is true. Say, “Yes, by my Lord, it is true. And you cannot frustrate (Allah’s plan).”'),
(1418, 10, 54, 6, 11, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ لَوۡ اَنَّ لِکُلِّ نَفۡسٍ ظَلَمَتۡ مَا فِی الۡاَرۡضِ لَافۡتَدَتۡ بِہٖ ؕ وَ اَسَرُّوا النَّدَامَۃَ  لَمَّا رَاَوُا الۡعَذَابَ ۚ وَ قُضِیَ بَیۡنَہُمۡ  بِالۡقِسۡطِ  وَ ہُمۡ  لَا  یُظۡلَمُوۡنَ ﴿۵۴﴾', 'اور اگر ہر ایک نافرمان شخص کے پاس روئے زمین کی تمام چیزیں ہوں تو وہ عذاب سے بچنے کے بدلے میں سب دے ڈالے اور جب وہ عذاب کو دیکھیں گے تو پچھتائیں گے اور ندامت کو چھپائیں گے۔ اور ان میں انصاف کے ساتھ فیصلہ کر دیا جائے گا اور ان پر ظلم نہیں ہو گا۔', 'اور اگر ہو  ہر شخص گنہگار کے پاس جتنا کچھ ہے زمین میں البتہ دے ڈالے اپنے بدلے میں [۷۹] اور چھپے چھپے پچھتائیں گے جب دیکھیں گےعذاب اور ان میں فیصلہ ہو گا انصاف سے اور ان پر ظلم نہ ہو گا [۸۰]', 'And if every person who had wronged (by disbelieving in Allah and by worshipping others besides Allah), possessed all that is on earth, and sought to ransom himself therewith (it will not be accepted), and they would feel in their hearts regret when they see the torment, and they will be judged with justice, and no wrong will be done unto them.', 'If anyone who did wrong possesses all that is on the earth, he would (agree to) ransom himself with it. And they will conceal their remorse when they will see the punishment. And the matter will be decided between them with justice and they will not be wronged.'),
(1419, 10, 55, 6, 11, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'اَلَاۤ اِنَّ لِلّٰہِ مَا فِی السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ اَلَاۤ  اِنَّ وَعۡدَ اللّٰہِ حَقٌّ وَّ لٰکِنَّ اَکۡثَرَہُمۡ لَا  یَعۡلَمُوۡنَ ﴿۵۵﴾', 'سن رکھو کہ جو کچھ آسمانوں اور زمین میں ہے سب اللہ ہی کا ہے۔ سن رکھو کہ اللہ کا وعدہ سچا ہے لیکن اکثر لوگ نہیں جانتے۔', 'سن رکھو اللہ کا ہے جو کچھ ہے آسمان اور زمین میں سن رکھو وعدہ اللہ کا سچ ہے [۸۱] پر بہت لوگ نہیں جانتے [۸۲]', 'No doubt, surely, all that is in the heavens and the earth belongs to Allah. No doubt, surely, Allahs Promise is true. But most of them know not.', 'Look! To Allah belongs all that is in the heavens and the earth. Look! Allah’s promise is certainly true, but most of them do not know.'),
(1420, 10, 56, 6, 11, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'ہُوَ  یُحۡیٖ وَ یُمِیۡتُ وَ اِلَیۡہِ تُرۡجَعُوۡنَ ﴿۵۶﴾', 'وہی جان بخشتا اور وہی موت دیتا ہے اور تم لوگ اسی کی طرف لوٹ کر جاؤ گے۔', 'وہی جلاتا ہے اور مارتا ہے اور اسی کی طرف پھر جاؤ گے [۸۳]', 'It is He Who gives life, and causes death, and to Him you (all) shall return.', 'He gives life and brings death, and to Him you shall be returned.'),
(1421, 10, 57, 6, 11, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'یٰۤاَیُّہَا النَّاسُ قَدۡ جَآءَتۡکُمۡ  مَّوۡعِظَۃٌ مِّنۡ رَّبِّکُمۡ وَ شِفَآءٌ لِّمَا فِی الصُّدُوۡرِ ۬ۙ وَ ہُدًی  وَّ رَحۡمَۃٌ   لِّلۡمُؤۡمِنِیۡنَ ﴿۵۷﴾', 'لوگو تمہارے پاس تمہارے پروردگار کی طرف سے نصیحت اور دلوں کی بیماریوں کی شفا اور مومنوں کے لئے ہدایت اور رحمت آ پہنچی ہے۔', 'اے لوگو تمہارے پاس آئی ہے نصیحت تمہارے رب سے اور شفا دلوں کے روگ کی اور ہدایت اور رحمت مسلمانوں کے واسطے [۸۴]', 'O mankind! There has come to you a good advice from your Lord (i.e. the Quran, ordering all that is good and forbidding all that is evil), and a healing for that (disease of ignorance, doubt, hypocrisy and differences, etc.) in your breasts, - a guidance and a mercy (explaining lawful and unlawful things, etc.) for the believers.', 'O men, there has come to you an advice from your Lord, and a cure for the ailments of your hearts, and guidance and mercy for the believers.'),
(1422, 10, 58, 6, 11, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'قُلۡ بِفَضۡلِ اللّٰہِ وَ بِرَحۡمَتِہٖ فَبِذٰلِکَ فَلۡیَفۡرَحُوۡا ؕ ہُوَ  خَیۡرٌ  مِّمَّا  یَجۡمَعُوۡنَ ﴿۵۸﴾', 'کہدو کہ یہ کتاب اللہ کے فضل اور اسکی مہربانی سے نازل ہوئی ہے تو چاہیے کہ لوگ اس سے خوش ہوں یہ اس سے کہیں بہتر ہے جو وہ جمع کرتے ہیں۔', 'کہہ اللہ کے فضل سے اور اسکی مہربانی سے سو اسی پر انکو خوش ہونا چاہئے [۸۵] یہ بہت  ہے ان چیزوں سے جو جمع کرتے ہیں [۸۶]', 'Say: \"In the Bounty of Allah, and in His Mercy (i.e. Islam and the Quran); -therein let them rejoice.\" That is better than what (the wealth) they amass.', 'Say, “With the grace of Allah and with His mercy (this book has been revealed). So they should rejoice in it. It is much better than that (wealth) which they accumulate.'),
(1423, 10, 59, 6, 11, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'قُلۡ اَرَءَیۡتُمۡ مَّاۤ  اَنۡزَلَ اللّٰہُ  لَکُمۡ مِّنۡ رِّزۡقٍ فَجَعَلۡتُمۡ مِّنۡہُ حَرَامًا وَّ حَلٰلًا ؕ قُلۡ آٰللّٰہُ  اَذِنَ لَکُمۡ اَمۡ عَلَی اللّٰہِ تَفۡتَرُوۡنَ ﴿۵۹﴾', 'کہو کہ بھلا دیکھو تو۔ اللہ نے تمہارے لئے جو رزق نازل فرمایا تو تم نے اس میں سے بعض کو حرام ٹھہرایا اور بعض کو حلال ان سے پوچھو کیا اللہ نے تمہیں اس کا حکم دیا ہے یا تم اللہ پر جھوٹ باندھتے ہو؟', 'تو کہہ بھلا دیکھو تو اللہ نے جو اتاری تمہارے واسطے روزی پھر تم نے ٹھہرائی اس میں سے کوئی حرام اور کوئی حلال کہہ کیا اللہ نے حکم دیا تم کو یا اللہ پر افترا کرتے ہو [۸۷]', 'Say (O Muhammad SAW to these polytheists): \"Tell me, what provision Allah has sent down to you! And you have made of it lawful and unlawful.\" Say (O Muhammad SAW): \"Has Allah permitted you (to do so), or do you invent a lie against Allah?\"', 'Say, “Have you ever considered, whatever provision Allah has sent down for your benefit, you have made up lawful and unlawful from it?” Say, “Has Allah permitted you or are you fabricating a lie against Allah?”'),
(1424, 10, 60, 6, 11, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ مَا ظَنُّ الَّذِیۡنَ یَفۡتَرُوۡنَ عَلَی اللّٰہِ الۡکَذِبَ یَوۡمَ  الۡقِیٰمَۃِ ؕ اِنَّ  اللّٰہَ   لَذُوۡ فَضۡلٍ عَلَی النَّاسِ  وَ لٰکِنَّ  اَکۡثَرَہُمۡ  لَا  یَشۡکُرُوۡنَ ﴿٪۶۰﴾', 'اور جو لوگ اللہ پر جھوٹ باندھتے ہیں وہ قیامت کے دن کی نسبت کیا خیال رکھتے ہیں؟ بیشک اللہ لوگوں پر مہربان ہے لیکن اکثر لوگ شکر نہیں کرتے۔', 'اور کیا خیال ہے جھوٹ باندھنے والوں کا اللہ پر قیامت کے دن [۸۸] اللہ تو فضل کرتا ہے لوگوں پر اور لیکن بہت لوگ حق نہیں مانتے [۸۹]', 'And what think those who invent lies against Allah, on the Day of Resurrection? (i.e. Do they think that they will be forgiven and excused! Nay, they will have an eternal punishment in the Fire of Hell). Truly, Allah is full of Bounty to mankind, but most of them are ungrateful.', 'What is the assumption of those who fabricate a lie against Allah (about) the Day of Judgment? Indeed Allah is gracious to people, but most of them are not grateful.'),
(1425, 10, 61, 7, 12, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ مَا تَکُوۡنُ فِیۡ شَاۡنٍ وَّ مَا تَتۡلُوۡا مِنۡہُ مِنۡ قُرۡاٰنٍ وَّ لَا تَعۡمَلُوۡنَ مِنۡ عَمَلٍ اِلَّا کُنَّا عَلَیۡکُمۡ شُہُوۡدًا  اِذۡ تُفِیۡضُوۡنَ فِیۡہِ ؕ وَ مَا یَعۡزُبُ عَنۡ رَّبِّکَ مِنۡ مِّثۡقَالِ  ذَرَّۃٍ فِی الۡاَرۡضِ وَ لَا فِی السَّمَآءِ وَ لَاۤ اَصۡغَرَ مِنۡ ذٰلِکَ وَ لَاۤ اَکۡبَرَ   اِلَّا  فِیۡ  کِتٰبٍ  مُّبِیۡنٍ ﴿۶۱﴾', 'اور تم جس حال میں ہوتے ہو۔ یا قرآن میں سے کچھ پڑھتے ہو یا تم لوگ کوئی اور کام کرتے ہو۔ جب اس میں مصروف ہوتے ہو تو ہم تمہارے پاس ہوتے ہیں اور تمہارے پروردگار سے کوئی ذرہ بھر بھی چیز پوشیدہ نہیں رہتی نہ زمین میں اور نہ آسمان میں اور نہ کوئی چیز ہے اس سے چھوٹی اور نہ بڑی مگر کتاب روشن میں لکھی ہوئی ہے۔', 'اور نہیں ہوتا تو کسی حال میں اور نہ پڑھتا ہے اس میں سے کچھ قرآن اور نہیں کرتے ہو تم لوگ کچھ کام کہ ہم نہیں ہوتے حاضر تمہارے پاس جب تم مصروف ہوتے ہو اس میں اور غائب نہیں رہتا تیرے رب سے ایک ذرہ بھر زمین میں اور نہ آسمان میں اور نہ چھوٹا اس سے اور نہ بڑا جو نہیں ہے کھلی ہوئی کتاب میں [۹۰]', 'Whatever you (O Muhammad SAW) may be doing, and whatever portion you may be reciting from the Quran, - and whatever deed you (mankind) may be doing (good or evil), We are Witness thereof, when you are doing it. And nothing is hidden from your Lord (so much as) the weight of an atom (or small ant) on the earth or in the heaven. Not what is less than that or what is greater than that but is (written) in a Clear Record. (Tafsir At-Tabaree. Vol.11, Page 129).', 'In whatever condition you are, and whatever portion of the Qur’ān you recite therein, and whatever work you all do, We are present before you when you are engaged in it. Hidden from your Lord is nothing even to the measure of a particle on the earth or in the heavens. And there is nothing smaller or greater that is not in the clear Book.'),
(1426, 10, 62, 7, 12, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'اَلَاۤ اِنَّ اَوۡلِیَآءَ اللّٰہِ لَا خَوۡفٌ عَلَیۡہِمۡ وَ لَا  ہُمۡ  یَحۡزَنُوۡنَ ﴿ۚۖ۶۲﴾', 'سن رکھو کہ جو اللہ کے دوست ہیں انکو نہ کچھ خوف ہو گا اور نہ وہ غمناک ہوں گے۔', 'یاد رکھو جو لوگ اللہ کے دوست ہیں نہ ڈر ہے ان پر اور نہ وہ غمگین ہوں گے [۹۱]', 'No doubt! Verily, the Auliya of Allah (i.e. those who believe in the Oneness of Allah and fear Allah much (abstain from all kinds of sins and evil deeds which he has forbidden), and love Allah much (perform all kinds of good deeds which He has ordained)), no fear shall come upon them nor shall they grieve, -', 'Listen, the friends of Allah shall have no fear, nor shall they grieve.'),
(1427, 10, 63, 7, 12, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'الَّذِیۡنَ  اٰمَنُوۡا  وَ کَانُوۡا  یَتَّقُوۡنَ ﴿ؕ۶۳﴾', 'یعنی وہ جو ایمان لائے اور پرہیزگار رہے۔', 'جو لوگ کہ ایمان لائے اور ڈرتے رہے [۹۲]', 'Those who believed (in the Oneness of Allah - Islamic Monotheism), and used to fear Allah much (by abstaining from evil deeds and sins and by doing righteous deeds).', '-those who have believed and have been fearful of Allah.'),
(1428, 10, 64, 7, 12, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'لَہُمُ الۡبُشۡرٰی فِی الۡحَیٰوۃِ الدُّنۡیَا وَ فِی الۡاٰخِرَۃِ ؕ لَا  تَبۡدِیۡلَ  لِکَلِمٰتِ اللّٰہِ ؕ ذٰلِکَ  ہُوَ  الۡفَوۡزُ  الۡعَظِیۡمُ ﴿ؕ۶۴﴾', 'انکے لئے دنیا کی زندگی میں بھی بشارت ہے اور آخرت میں بھی۔ اللہ کی باتیں بدلتی نہیں۔ یہی تو بڑی کامیابی ہے۔', 'ان کے لئے ہے خوشخبری دنیا کی زندگانی میں اور آخرت میں [۹۳] بدلتی نہیں اللہ کی باتیں[۹۴] یہی ہے بڑی کامیابی', 'For them are glad tidings, in the life of the present world (i.e. righteous dream seen by the person himself or shown to others), and in the Hereafter. No change can there be in the Words of Allah, this is indeed the supreme success.', 'For them there is the good news in the worldly life and in the Hereafter: there is no change in the words of Allah.That is the great achievement.'),
(1429, 10, 65, 7, 12, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ لَا یَحۡزُنۡکَ قَوۡلُہُمۡ ۘ اِنَّ الۡعِزَّۃَ لِلّٰہِ جَمِیۡعًا ؕ ہُوَ  السَّمِیۡعُ  الۡعَلِیۡمُ ﴿۶۵﴾', 'اور اے پیغمبر ان لوگوں کی باتوں سے آزردہ نہ ہونا کیونکہ عزت سب اللہ ہی کی ہے وہ سب کچھ سنتا ہے جانتا ہے۔', 'اور رنج مت کر ان کی بات سے اصل میں سب زور اللہ کے لئے  ہے وہی ہے سننے والا جاننے والا [۹۵]', 'And let not their speech grieve you (O Muhammad SAW), for all power and honour belong to Allah. He is the All-Hearer, the All-Knower.', '(O Prophet,) what they say should not make you grieve. Surely, all power belongs to Allah. He is All-Hearing, All Knowing.'),
(1430, 10, 66, 7, 12, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'اَلَاۤ اِنَّ لِلّٰہِ مَنۡ فِی السَّمٰوٰتِ وَ مَنۡ فِی الۡاَرۡضِ ؕ وَ مَا یَتَّبِعُ الَّذِیۡنَ یَدۡعُوۡنَ مِنۡ دُوۡنِ اللّٰہِ شُرَکَآءَ ؕ اِنۡ یَّـتَّبِعُوۡنَ  اِلَّا  الظَّنَّ  وَ  اِنۡ  ہُمۡ   اِلَّا  یَخۡرُصُوۡنَ ﴿۶۶﴾', 'سن رکھو کہ جو مخلوق آسمانوں میں ہے اور جو زمین میں ہے سب اللہ ہی کے بندے ہیں اور یہ جو اللہ کے سوا اپنے بنائے ہوئے شریکوں کو پکارتے ہیں وہ کسی اور چیز کے پیچھے نہیں چلتے۔ صرف گمان کے پیچھے چلتے ہیں اور محض اٹکلیں دوڑا رہے ہیں۔', 'سنتا ہے بیشک اللہ کا ہے جو کوئی ہے آسمانوں میں اور جو کوئی ہے زمین میں اور یہ جو پیچھے پڑے ہیں اللہ کے سوا شریکوں کو پکارنے والے سو یہ کچھ نہیں مگر پیچھے پڑے ہیں اپنے خیال کے اور کچھ نہیں مگر اٹکلیں دوڑاتے ہیں [۹۶]', 'No doubt! Verily, to Allah belongs whosoever is in the heavens and whosoever is in the earth. And those who worship and invoke others besides Allah, in fact they follow not the (Allahs so-called) partners, they follow only a conjecture and they only invent lies.', 'Listen, to Allah belong all those in the heavens and all those on the earth. And those who invoke associate-gods besides Allah do not follow a reality. They follow nothing but whims and do nothing but make conjectures.'),
(1431, 10, 67, 7, 12, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'ہُوَ الَّذِیۡ جَعَلَ لَکُمُ الَّیۡلَ لِتَسۡکُنُوۡا فِیۡہِ وَ النَّہَارَ  مُبۡصِرًا ؕ اِنَّ فِیۡ  ذٰلِکَ  لَاٰیٰتٍ  لِّقَوۡمٍ  یَّسۡمَعُوۡنَ ﴿۶۷﴾', 'وہی تو ہے جس نے تمہارے لئے رات بنائی تاکہ اس میں آرام کرو۔ اور روز روشن بنایا تاکہ اس میں کام کرو جو لوگ قوت سماعت رکھتے ہیں انکے لئے اس میں نشانیاں ہیں۔', 'وہی ہے جس نے بنایا تمہارے واسطے رات کو کہ چین حاصل کرو اس میں اور دن دیا دکھلانے والا بیشک اس میں نشانیاں ہیں ان لوگوں کے لئے جو سنتے ہیں [۹۷]', 'He it is Who has appointed for you the night that you may rest therein, and the day to make things visible (to you). Verily, in this are Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) for a people who listen (i.e. those who think deeply).', 'He is the One who made for you the night, so that you may have rest in it, and (made) the day to see. Indeed, there are signs therein for a people who listen.'),
(1432, 10, 68, 7, 12, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'قَالُوا اتَّخَذَ اللّٰہُ وَلَدًا سُبۡحٰنَہٗ ؕ ہُوَ الۡغَنِیُّ ؕ لَہٗ  مَا فِی السَّمٰوٰتِ  وَ مَا فِی الۡاَرۡضِ ؕ اِنۡ عِنۡدَکُمۡ مِّنۡ سُلۡطٰنٍۭ بِہٰذَا ؕ اَتَقُوۡلُوۡنَ عَلَی اللّٰہِ مَا لَا تَعۡلَمُوۡنَ ﴿۶۸﴾', 'بعض لوگ کہتے ہیں کہ اللہ نے بیٹا بنا لیا ہے اسکی ذات اولاد سے پاک ہے وہ  تو بے نیاز ہے۔ جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب اسی کا ہے اے افتراپردازو تمہارے پاس اس قول باطل کی کوئی دلیل نہیں ہے۔ کیا تم اللہ کی نسبت ایسی بات کہتے ہو جو جانتے نہیں۔', 'کہتےہیں ٹھہرا لیا اللہ نے بیٹا وہ پاک ہے وہ بے نیاز ہے اسی کا ہے جو کچھ ہے آسمانوں میں اور جو کچھ ہے زمین میں نہیں تمہارےپاس کوئی سند اس کی کیوں جھوٹ کہتے ہو اللہ پر جس بات کی تم کو خبر نہیں [۹۸]', 'They (Jews, Christians and pagans) say: \"Allah has begotten a son (children).\" Glory be to Him! He is Rich (Free of all wants). His is all that is in the heavens and all that is in the earth. No warrant you have for this. Do you say against Allah what you know not.', 'They say, “Allah has got a son.” Pure is He. He is Self-Sufficient. To Him belongs what is in the heavens and what is in the earth. You have no proof for it. Do you allege about Allah what you do not know?'),
(1433, 10, 69, 7, 12, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'قُلۡ اِنَّ الَّذِیۡنَ یَفۡتَرُوۡنَ عَلَی اللّٰہِ الۡکَذِبَ  لَا  یُفۡلِحُوۡنَ ﴿ؕ۶۹﴾', 'کہدو کہ جو لوگ اللہ پر جھوٹ باندھتے ہیں فلاح نہیں پائیں گے۔', 'کہہ جو لوگ باندھتے ہیں اللہ پر جھوٹ بھلائی نہیں پاتے', 'Say: \"Verily, those who invent lie against Allah will never be successful\" -', 'Say: Those who fabricate lies against Allah shall not prosper.'),
(1434, 10, 70, 7, 12, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'مَتَاعٌ فِی الدُّنۡیَا ثُمَّ  اِلَیۡنَا مَرۡجِعُہُمۡ ثُمَّ نُذِیۡقُہُمُ الۡعَذَابَ الشَّدِیۡدَ بِمَا کَانُوۡا  یَکۡفُرُوۡنَ ﴿٪۷۰﴾', 'انکے لئے جو فائدے ہیں دنیا میں ہی ہیں پھر انکو ہماری ہی طرف لوٹ کر آنا ہے اس وقت ہم انکو عذاب شدید کے مزے چکھائیں گے کیونکہ وہ کفر کی باتیں کیا کرتے تھے۔', 'تھوڑا سا نفع اٹھا لینا دنیا میں پھر ہماری طرف ہے ان کو لوٹنا پھر چکھائیں گے ہم انکو سخت عذاب بدلا ان  کے کفر کا [۹۹]', 'A brief enjoyment in this world! - and then unto Us will be their return, then We shall make them taste the severest torment because they used to disbelieve (in Allah, belie His Messengers, deny and challenge His Ayat (proofs, signs, verses, etc.)).', 'It will be a little enjoyment in this world; thereafter to Us they are bound to return; then We shall make them taste the severe punishment, because they used to disbelieve.'),
(1435, 10, 71, 8, 13, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ اتۡلُ عَلَیۡہِمۡ نَبَاَ نُوۡحٍ ۘ اِذۡ قَالَ لِقَوۡمِہٖ یٰقَوۡمِ  اِنۡ کَانَ کَبُرَ عَلَیۡکُمۡ مَّقَامِیۡ وَ تَذۡکِیۡرِیۡ بِاٰیٰتِ اللّٰہِ  فَعَلَی  اللّٰہِ تَوَکَّلۡتُ فَاَجۡمِعُوۡۤا اَمۡرَکُمۡ وَ شُرَکَآءَکُمۡ ثُمَّ لَا یَکُنۡ اَمۡرُکُمۡ عَلَیۡکُمۡ غُمَّۃً ثُمَّ اقۡضُوۡۤا اِلَیَّ وَ لَا تُنۡظِرُوۡنِ ﴿۷۱﴾', 'اور انکو نوح کا قصہ پڑھ کو سنا دو جب انہوں نے اپنی قوم سے کہا کہ اے قوم! اگر تم کو میرا اپنے درمیان رہنا اور اللہ کی آیتوں سے نصیحت کرنا ناگوار ہو تو میں تو اللہ پر بھروسہ رکھتا ہوں۔ تم اپنے شریکوں کے ساتھ مل کر ایک کام جو میرے بارے میں کرنا چاہو مقرر کر لو اور وہ تمہاری تمام جماعت کو معلوم ہو جائے اور کسی سے پوشیدہ نہ رہے پھر وہ کام میرے خلاف کر گزرو اور مجھے مہلت نہ دو۔', 'اور سنا ان کو حال نوح کا [۱۰۰] جب کہا اپنی قوم کو اے قوم اگر بھاری ہوا ہے تم پر میرا کھڑا ہونا اور نصیحت کرنا اللہ کی آیتوں سےتو میں نے اللہ پر بھروسہ کیا اب تم سب مل کر مقرر کرو اپنا کام اور جمع کرو اپنے شریکوں کو پھر نہ رہے تم کو اپنے کام میں شبہ پھر کر گذرو میرے ساتھ اور مجھ کو مہلت نہ دو [۱۰۱]', 'And recite to them the news of Nooh (Noah). When he said to his people: \"O my people, if my stay (with you), and my reminding (you) of the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah is hard on you, then I put my trust in Allah. So devise your plot, you and your partners, and let not your plot be in doubt for you. Then pass your sentence on me and give me no respite.', 'Recite to them the story of (the Prophet) NūH (Noah), when he said to his people, “O my people, if it is hard on you that I stay (with you) and give (you) advice through the signs of Allah, then, in Allah I place my trust. So, be firm in your plan (against me) with (the help of) all your partners, and your plan should not be a cause of concern for you; then carry it out against me and give me no respite.'),
(1436, 10, 72, 8, 13, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'فَاِنۡ تَوَلَّیۡتُمۡ فَمَا سَاَلۡتُکُمۡ مِّنۡ اَجۡرٍ ؕ اِنۡ اَجۡرِیَ اِلَّا عَلَی اللّٰہِ ۙوَ اُمِرۡتُ اَنۡ اَکُوۡنَ  مِنَ  الۡمُسۡلِمِیۡنَ ﴿۷۲﴾', 'اب اگر تم نے منہ پھیر لیا تو تم جانتے ہو کہ میں نے تم سے کچھ معاوضہ نہیں مانگا میرا معاوضہ تو اللہ کے ذمے ہے اور مجھے حکم ہوا ہے کہ میں فرمانبرداروں میں رہوں۔', 'پرھ اگر منہ پھیرو گے تو میں نے نہیں چاہی تم سے مزدروی میری مزدوری ہے اللہ پر اور مجھ کو حکم ہے کہ رہوں فرمانبردار [۱۰۲]', '\"But if you turn away (from accepting my doctrine of Islamic Monotheism, i.e. to worship none but Allah), then no reward have I asked of you, my reward is only from Allah, and I have been commanded to be one of the Muslims (those who submit to Allahs Will).\"', 'Still, if you turn away, then, I did not demand any reward from you. My reward is with none except Allah, and I have been commanded to be among those who submit.”'),
(1437, 10, 73, 8, 13, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'فَکَذَّبُوۡہُ  فَنَجَّیۡنٰہُ وَ مَنۡ مَّعَہٗ فِی الۡفُلۡکِ وَ جَعَلۡنٰہُمۡ خَلٰٓئِفَ وَ اَغۡرَقۡنَا الَّذِیۡنَ کَذَّبُوۡا بِاٰیٰتِنَا ۚ فَانۡظُرۡ کَیۡفَ کَانَ  عَاقِبَۃُ  الۡمُنۡذَرِیۡنَ ﴿۷۳﴾', 'پھر ان لوگوں نے انکی تکذیب کی تو ہم نے انکو اور جو لوگ انکے ساتھ کشتی میں سوار تھے سب کو طوفان سے بچا لیا اور انہیں زمین میں خلیفہ بنا دیا اور جن لوگوں نے ہماری آیتوں کو جھٹلایا انکو غرق کر دیا تو دیکھ لو کہ جو لوگ ڈرائے گئے تھے ان کا کیسا انجام ہوا؟', 'پھر اس کو جھٹلایا سو ہم نے بچا لیا اسکو اور جو اس کے ساتھ تھے کشتی میں اور ان کو قائم کر دیا جگہ پر اور ڈبا دیا ان کو جو جھٹلاتے تھے ہماری باتوں کو سو دیکھ لے کیسا ہوا انجام ان کا جن کو ڈرایا تھا [۱۰۳]', 'They denied him, but We delivered him, and those with him in the ship, and We made them generations replacing one after another, while We drowned those who belied Our Ayat (proofs, evidences, lessons, signs, revelations, etc.). Then see what was the end of those who were warned.', 'Then they rejected him, and We saved him and those with him in the Ark and made them the successors, and drowned those who gave the lie to Our signs. So look how was the fate of those who were warned.'),
(1438, 10, 74, 8, 13, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'ثُمَّ بَعَثۡنَا مِنۡۢ بَعۡدِہٖ رُسُلًا اِلٰی قَوۡمِہِمۡ فَجَآءُوۡہُمۡ بِالۡبَیِّنٰتِ فَمَا کَانُوۡا لِیُؤۡمِنُوۡا بِمَا کَذَّبُوۡا بِہٖ  مِنۡ  قَبۡلُ ؕ کَذٰلِکَ نَطۡبَعُ عَلٰی قُلُوۡبِ الۡمُعۡتَدِیۡنَ ﴿۷۴﴾', 'پھر نوح کے بعد ہم نے اور پیغمبر اپنی اپنی قوم کی طرف بھیجے۔ تو وہ انکے پاس کھلی نشانیاں لے کر آئے۔ مگر وہ لوگ ایسے نہ تھے کہ جس چیز کو پہلے جھٹلا چکے تھے اس پر ایمان لے آتے۔ اسی طرح ہم زیادتی کرنے والوں کے دلوں پر مہر لگا دیتے ہیں۔', 'پھر بھیجے ہم نے نوح کے بعد کتنے پیغمبر ان کی قوم کی طرف پھر لائے انکے پاس کھلی دلیلیں سو ان سے یہ نہ ہوا کہ ایمان لے آئیں اس بات پر جسکو جھٹلا چکے تھے پہلے سے [۱۰۴] اسی طرح ہم مہر لگا دیتے ہیں دلوں پر حد سے نکل جانے والوں کے [۱۰۵]', 'Then after him We sent Messengers to their people, they brought them clear proofs, but they would not believe what they had already rejected beforehand. Thus We seal the hearts of the transgressors (those who disbelieve in the Oneness of Allah and disobey Him).', 'Then, after him, We sent messengers to their peoples, and they came to them with clear signs, but they were not to believe in what they had rejected earlier. This is how We seal the hearts of the transgressors.'),
(1439, 10, 75, 8, 13, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'ثُمَّ بَعَثۡنَا مِنۡۢ بَعۡدِہِمۡ مُّوۡسٰی وَ ہٰرُوۡنَ اِلٰی فِرۡعَوۡنَ وَ مَلَا۠ئِہٖ بِاٰیٰتِنَا فَاسۡتَکۡبَرُوۡا وَ کَانُوۡا قَوۡمًا مُّجۡرِمِیۡنَ ﴿۷۵﴾', 'پھر انکے بعد ہم نے موسٰی اور ہارون کو اپنی نشانیاں دے کر فرعون اور اسکے سرداروں کے پاس بھیجا تو انہوں نے تکبر کیا اور وہ گناہگار لوگ تھے۔', 'پھر بھیجا ہم نے ان کے پیچھے موسٰی اور ہارون کو فرعون اور اس کے سرداروں کے پاس اپنی نشانیاں دے کر پھر تکبر کرنے لگے اور وہ تھے لوگ گنہگار [۱۰۶]', 'Then after them We sent Moosa (Moses) and Haroon (Aaron) to Firaun (Pharaoh) and his chiefs with Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.). But they behaved arrogantly and were Mujrimoon (disbelievers, sinners, polytheists, criminals, etc.) folk.', 'Then, after them, We sent Mūsā and Hārūn with Our signs to Pharaoh and his group, but they showed arrogance. And they were surely a guilty people.'),
(1440, 10, 76, 8, 13, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'فَلَمَّا جَآءَہُمُ الۡحَقُّ مِنۡ عِنۡدِنَا قَالُوۡۤا اِنَّ ہٰذَا  لَسِحۡرٌ  مُّبِیۡنٌ ﴿۷۶﴾', 'تو جب انکے پاس ہمارے ہاں سے حق آیا تو کہنے لگے کہ یہ تو کھلا جادو ہے۔', 'پھر جب پہنچی ان کو سچی بات ہمارے پاس سے کہنے لگے یہ تو جادو ہے کھلا [۱۰۷]', 'So when came to them the truth from Us, they said: \"This is indeed clear magic.\"', 'So, when Truth came to them from Us, they said, “It is certainly a clear magic.”'),
(1441, 10, 77, 8, 13, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'قَالَ مُوۡسٰۤی اَتَقُوۡلُوۡنَ لِلۡحَقِّ لَمَّا جَآءَکُمۡ ؕ اَسِحۡرٌ ہٰذَا ؕ وَ لَا یُفۡلِحُ السّٰحِرُوۡنَ ﴿۷۷﴾', 'موسٰی نے کہا کیا تم حق کے بارے میں جب وہ تمہارے پاس آیا یہ کہتے ہو کہ یہ جادو ہے حالانکہ جادوگر فلاح نہیں پانے کے۔', 'کہا موسٰی نے کیا تم یہ کہتے ہو حق بات کو جب وہ پہنچے تمہارے پاس کیا یہ جادو ہے اور نجات نہیں پاتے جادو کرنے والے [۱۰۸]', 'Moosa (Moses) said: \"Say you (this) about the truth when it has come to you? Is this magic? But the magicians will never be successful.\"', 'Mūsā said, “Do you say (this) about the Truth when it came to you? Is this magic, while the magicians do not achieve success?”'),
(1442, 10, 78, 8, 13, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'قَالُوۡۤا اَجِئۡتَنَا لِتَلۡفِتَنَا عَمَّا وَجَدۡنَا عَلَیۡہِ اٰبَآءَنَا وَ تَکُوۡنَ لَکُمَا الۡکِبۡرِیَآءُ  فِی الۡاَرۡضِ ؕ وَ مَا نَحۡنُ لَکُمَا بِمُؤۡمِنِیۡنَ ﴿۷۸﴾', 'وہ بولے کیا تم ہمارے پاس اس لئے آئے ہو کہ جس راہ پر ہم اپنے باپ دادا کو پاتے رہے ہیں اس سے ہم کو پھیر دو۔ اور اس ملک میں تم دونوں ہی کی سرداری ہو جائے؟ اور ہم تم پر ایمان لانے والے نہیں ہیں۔', 'بولے کیا تو آیا ہے کہ ہم کو پھیر دے اس رستہ سے جس پر پایا ہم نے اپنے باپ دادوں کو اور تم دونوں کو سرداری مل جائے اس ملک میں اور ہم نہیں ہیں تم کو ماننے والے [۱۰۹]', 'They said: \"Have you come to us to turn us away from that (Faith) we found our fathers following, - and that you two may have greatness in the land? We are not going to believe you two!\"', 'They said, “Have you come to us to turn us away from the way on which we have found our fathers, and so that you both have supremacy on earth? We are not going to believe in you.”'),
(1443, 10, 79, 8, 13, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ قَالَ فِرۡعَوۡنُ ائۡتُوۡنِیۡ بِکُلِّ سٰحِرٍ عَلِیۡمٍ ﴿۷۹﴾', 'اور فرعون نے حکم دیا کہ سب کامل فن جادوگروں کو ہمارے پاس لے آؤ۔', 'اور بولا فرعون لاؤ میرے پاس جو جادوگر ہو پڑھا ہوا [۱۱۰]', 'And Firaun (Pharaoh) said: \"Bring to me every well-versed sorcerer.\"', 'And Pharaoh said, “Bring to me every knowledgeable magician.”'),
(1444, 10, 80, 8, 13, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'فَلَمَّا جَآءَ السَّحَرَۃُ قَالَ لَہُمۡ مُّوۡسٰۤی اَلۡقُوۡا  مَاۤ   اَنۡتُمۡ  مُّلۡقُوۡنَ ﴿۸۰﴾', 'چنانچہ جب جادوگر آئے تو موسٰی نے ان سے کہا کہ جو تم کو ڈالنا ہو ڈالو۔', 'پھر جب آئے جادوگر کہا ان کو موسٰی نے ڈالو جو تم ڈالتے ہو [۱۱۱]', 'And when the sorcerers came, Moosa (Moses) said to them: \"Cast down what you want to cast!\"', 'So, when the magicians came, Mūsā said to them, “Cast what you have to cast.”'),
(1445, 10, 81, 8, 13, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'فَلَمَّاۤ  اَلۡقَوۡا قَالَ مُوۡسٰی مَا جِئۡتُمۡ  بِہِ ۙ السِّحۡرُ ؕ اِنَّ  اللّٰہَ  سَیُبۡطِلُہٗ ؕ اِنَّ  اللّٰہَ  لَا یُصۡلِحُ  عَمَلَ  الۡمُفۡسِدِیۡنَ ﴿۸۱﴾', 'پھر جب انہوں نے اپنی رسیوں اور لاٹھیوں کو ڈالا تو موسٰی نے کہا کہ جو چیزیں تم بنا کر لائے ہو جادو ہے اللہ اسکو ابھی نیست و نابود کر دے گا۔ اللہ شریروں کے کام سنوارا نہیں کرتا۔', 'پھر جب انہوں نے ڈالا موسٰی بولا کہ جو تم لائے ہو سو جادو ہے [۱۱۲] اب اللہ اسکو بگاڑتا ہے بیشک اللہ نہیں سنوارتا شریروں کے کام [۱۱۳]', 'Then when they had cast down, Moosa (Moses) said: \"What you have brought is sorcery, Allah will surely make it of no effect. Verily, Allah does not set right the work of Al-Mufsidoon (the evil-doers, corrupts, etc.).', 'So, when they had cast, Mūsā said, “All that you have brought is magic. Allah will certainly bring it to naught. Be assured that Allah does not set right the work of the mischief-makers.”'),
(1446, 10, 82, 8, 13, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ یُحِقُّ اللّٰہُ  الۡحَقَّ بِکَلِمٰتِہٖ وَ لَوۡ کَرِہَ الۡمُجۡرِمُوۡنَ ﴿٪۸۲﴾', 'اور اللہ اپنے حکم سے سچ کو سچ ہی کر دے گا اگرچہ گناہگار برا ہی مانیں۔', 'اور اللہ سچا کرتا ہے حق بات کو اپنے حکم سے اور پڑے برا مانیں گنہگار', '\"And Allah will establish and make apparent the truth by His Words, however much the Mujrimoon (criminals, disbelievers, polytheists, sinners, etc.) may hate it.\"', 'And Allah establishes the truth through His words, even though the guilty ones may dislike it.'),
(1447, 10, 83, 9, 14, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'فَمَاۤ اٰمَنَ لِمُوۡسٰۤی اِلَّا ذُرِّیَّۃٌ  مِّنۡ قَوۡمِہٖ عَلٰی خَوۡفٍ مِّنۡ فِرۡعَوۡنَ وَ مَلَا۠ئِہِمۡ  اَنۡ یَّفۡتِنَہُمۡ ؕ وَ اِنَّ فِرۡعَوۡنَ لَعَالٍ فِی الۡاَرۡضِ ۚ وَ  اِنَّہٗ   لَمِنَ  الۡمُسۡرِفِیۡنَ ﴿۸۳﴾', 'تو موسٰی پر کوئی ایمان نہ لایا۔ مگر اسکی قوم میں سے چند لڑکے اور وہ بھی فرعون اور اسکے اہل دربار سے ڈرتے ڈرتے کہ کہیں وہ انکو آفت میں نہ پھنسا دے۔ اور فرعون ملک میں متکبر تھا اور کبروکفر میں حد سے بڑھا ہوا تھا۔', 'پھر کوئی ایمان نہ لایا موسٰی پر مگر کچھ لڑکے اس کی قوم کے [۱۱۴] ڈرتے ہوئے فرعون سے اور انکے سرداروں سے کہ کہیں انکو بچلا نہ دے [۱۱۵] اور فرعون چڑھ رہا ہے ملک میں اور اس نے ہاتھ چھوڑ رکھا ہے [۱۱۶]', 'But none believed in Moosa (Moses) except the offspring of his people, because of the fear of Firaun (Pharaoh) and his chiefs, lest they should persecute them; and verily, Firaun (Pharaoh) was arrogant tyrant on the earth, he was indeed one of the Musrifoon (polytheists, sinners and transgressors, those who give up the truth and follow the evil, and commit all kinds of great sins).', 'Then, except some youths of his people, no one believed in Mūsā for the fear of Pharaoh and his group, lest he should persecute them. Pharaoh was high-handed in the land and he was of those who crossed all limits.'),
(1448, 10, 84, 9, 14, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ قَالَ مُوۡسٰی یٰقَوۡمِ  اِنۡ  کُنۡتُمۡ اٰمَنۡتُمۡ بِاللّٰہِ فَعَلَیۡہِ تَوَکَّلُوۡۤا  اِنۡ کُنۡتُمۡ مُّسۡلِمِیۡنَ ﴿۸۴﴾', 'اور موسٰی نے کہا کہ بھائیو! اگر تم اللہ پر ایمان لائے ہو تو اگر دل سے فرمانبردار ہو تو اسی پر بھروسہ رکھو۔', 'اور کہا موسٰی نے اے میری قوم اگر تم ایمان لائے ہو اللہ پر تو اسی پر بھروسہ کرو اگر ہو تم فرمانبردار [۱۱۷]', 'And Moosa (Moses) said: \"O my people! If you have believed in Allah, then put your trust in Him if you are Muslims (those who submit to Allahs Will).\"', 'And Mūsā said, “My people, if you have believed in Allah, then, in Him place your trust if you are obedient.”'),
(1449, 10, 85, 9, 14, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'فَقَالُوۡا عَلَی اللّٰہِ تَوَکَّلۡنَا ۚ رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَۃً   لِّلۡقَوۡمِ الظّٰلِمِیۡنَ ﴿ۙ۸۵﴾', 'پس وہ بولے کہ ہم اللہ ہی پر بھروسہ رکھتے ہیں اے ہمارے پروردگار ہم کو ظالم لوگوں کے ہاتھ سے آزمائش میں نہ ڈال۔', 'تب وہ بولے ہم نے اللہ پر بھرسہ کیا اے رب ہمارے نہ آزما ہم پر زور اس ظالم قوم کا [۱۱۸]', 'They said: \"In Allah we put our trust. Our Lord! Make us not a trial for the folk who are Zalimoon (polytheists and wrong-doing) (i.e. do not make them overpower us).', 'So, they said, “In Allah we have placed our trust: Our Lord, do not make us a victim of the unjust people,'),
(1450, 10, 86, 9, 14, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ نَجِّنَا بِرَحۡمَتِکَ مِنَ الۡقَوۡمِ الۡکٰفِرِیۡنَ ﴿۸۶﴾', 'اور اپنی رحمت سے ہمیں قوم کفار سے نجات بخش۔', 'اور چھڑا دے ہم کو مہربانی فرما کر ان کافر لوگوں سے [۱۱۹]', '\"And save us by Your Mercy from the disbelieving folk.\"', 'and save us, through Your mercy, from the disbelieving people.”'),
(1451, 10, 87, 9, 14, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ اَوۡحَیۡنَاۤ  اِلٰی مُوۡسٰی وَ اَخِیۡہِ اَنۡ تَبَوَّاٰ لِقَوۡمِکُمَا بِمِصۡرَ بُیُوۡتًا وَّ اجۡعَلُوۡا بُیُوۡتَکُمۡ قِبۡلَۃً  وَّ اَقِیۡمُوا الصَّلٰوۃَ ؕ وَ بَشِّرِ  الۡمُؤۡمِنِیۡنَ ﴿۸۷﴾', 'اور ہم نے موسٰی اور اسکے بھائی کی طرف وحی بھیجی کہ اپنے لوگوں کے لئے مصر میں گھر بناؤ اور اپنے گھروں کو قبلہ یعنی مسجدیں ٹھہراؤ۔ اور نماز قائم کرتے رہو اور مومنوں کو خوشخبری سنا دو۔', 'اور حکم بھیجا ہم نے موسٰی کو اور اسکے بھائی کو کہ مقرر کرو اپنی قوم کے واسطے مصر میں سے گھر [۱۲۰] اور بناؤ اپنے گھر قبلہ رو اور قائم کرو نماز [۱۲۱] اور خوشخبری دے ایمان والوں کو [۱۲۲]', 'And We inspired Moosa (Moses) and his brother (saying): \"Take dwellings for your people in Egypt, and make your dwellings as places for your worship, and perform As-Salat (Iqamat-as-Salat), and give glad tidings to the believers.\"', 'And We revealed to Mūsā and his brother: “Have houses for your people in Egypt, and make your houses worship oriented, and establish Salāh, and give good tidings to the believers.”'),
(1452, 10, 88, 9, 14, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ قَالَ مُوۡسٰی رَبَّنَاۤ اِنَّکَ اٰتَیۡتَ فِرۡعَوۡنَ وَ مَلَاَہٗ  زِیۡنَۃً  وَّ اَمۡوَالًا فِی الۡحَیٰوۃِ الدُّنۡیَا ۙ رَبَّنَا لِیُضِلُّوۡا عَنۡ سَبِیۡلِکَ ۚ رَبَّنَا اطۡمِسۡ عَلٰۤی اَمۡوَالِہِمۡ وَ اشۡدُدۡ عَلٰی قُلُوۡبِہِمۡ فَلَا یُؤۡمِنُوۡا حَتّٰی  یَرَوُا  الۡعَذَابَ  الۡاَلِیۡمَ ﴿۸۸﴾', 'اور موسٰی نے کہا کہ اے ہمارے پروردگار تو نے فرعون اور اسکے سرداروں کو دنیا کی زندگی میں بارونق سازوسامان اور مال و زر دے رکھا ہے۔ اے پروردگار کیا اسی لئے کہ وہ تیرے رستے سے گمراہ کر دیں اے پروردگار۔ ان کے مال کر برباد کر دے اور انکے دلوں کو سخت کر دے کہ ایمان نہ لائیں جب تک عذاب الیم نہ دیکھیں۔', 'اور کہا موسٰی نے اے رب ہمارے تو نے دی ہے فرعون کو اور اس کے سرداروں کو رونق اور مال دنیا کی زندگی میں [۱۲۳] اے رب اس واسطے کہ بہکائیں تیری راہ سے [۱۲۴] اے رب مٹا دے ان کے  مال اور سخت کر دے ان کے دل کہ نہ ایمان لائیں جب تک دیکھ لیں عذاب دردناک [۱۲۵]', 'And Moosa (Moses) said: \"Our Lord! You have indeed bestowed on Firaun (Pharaoh) and his chiefs splendour and wealth in the life of this world, our Lord! That they may lead men astray from Your Path. Our Lord! Destroy their wealth, and harden their hearts, so that they will not believe until they see the painful torment.\"', 'Mūsā said, “Our Lord, You have given Pharaoh and his group glamour and riches in the worldly life, so that, our Lord, they mislead (people) from Your path. Our Lord, obliterate their riches and harden their hearts, so that they may not come to believe until they witness the painful punishment.”'),
(1453, 10, 89, 9, 14, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'قَالَ قَدۡ اُجِیۡبَتۡ دَّعۡوَتُکُمَا فَاسۡتَقِیۡمَا وَ لَا تَتَّبِعٰٓنِّ سَبِیۡلَ  الَّذِیۡنَ لَا یَعۡلَمُوۡنَ ﴿۸۹﴾', 'اللہ نے فرمایا کہ تمہاری دعا قبول کر لی گئ تو تم ثابت قدم رہنا اور بے عقلوں کے رستے پر نہ چلنا۔', 'فرمایا قبول ہو چکی دعا تمہاری [۱۲۶] سو تم دونوں ثابت رہو اور مت چلو راہ انکی جو ناواقف ہیں [۱۲۷]', 'Allah said: \"Verily, the invocation of you both is accepted. So you both keep to the Straight Way (i.e. keep on doing good deeds and preaching Allahs Message with patience), and follow not the path of those who know not (the truth i.e. to believe in the Oneness of Allah, and also to believe in the Reward of Allah: Paradise, etc.).\"', 'Allah said, “The prayer of the two of you has been granted; so stand firm, and never follow the way of the ignorant.”'),
(1454, 10, 90, 9, 14, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ جٰوَزۡنَا بِبَنِیۡۤ  اِسۡرَآءِیۡلَ الۡبَحۡرَ فَاَتۡبَعَہُمۡ فِرۡعَوۡنُ وَ جُنُوۡدُہٗ  بَغۡیًا وَّ عَدۡوًا ؕ حَتّٰۤی اِذَاۤ  اَدۡرَکَہُ الۡغَرَقُ ۙ قَالَ اٰمَنۡتُ اَنَّہٗ  لَاۤ اِلٰہَ  اِلَّا الَّذِیۡۤ اٰمَنَتۡ بِہٖ بَنُوۡۤا اِسۡرَآءِیۡلَ وَ اَنَا مِنَ الۡمُسۡلِمِیۡنَ ﴿۹۰﴾', 'اور ہم نے بنی اسرائیل کو سمندر سے پار کروایا تو فرعون اور اسکے لشکر نے سرکشی اور زیادتی کرتے ہوئے ان کا تعاقب کیا۔ یہاں تک کہ جب اسکو غرق کرنے والے عذاب نے آ پکڑا تو کہنے لگا میں ایمان لایا کہ جس اللہ پر بنی اسرائیل ایمان لائے ہیں اسکے سوا کوئی معبود نہیں اور میں فرمانبرداروں میں ہوں۔', 'اور پار کر دیا ہم نے بنی اسرائیل کو دریا سے پھرپیچھا کیا ان کا فرعون نے اور اس کے لشکر نے شرارت سے اور تعدی سے یہاں تک کہ جب ڈوبنے لگا بولا یقین کر لیا میں نے کہ کوئی معبود نہیں مگر جس پر کہ ایمان لائے بنی اسرائیل اور میں ہوں فرمانبرداروں میں', 'And We took the Children of Israel across the sea, and Firaun (Pharaoh) with his hosts followed them in oppression and enmity, till when drowning overtook him, he said: \"I believe that La ilaha illa (Huwa): (none has the right to be worshipped but) He,\" in Whom the Children of Israel believe, and I am one of the Muslims (those who submit to Allahs Will).\"', 'And We let the children of Isrā’īl cross the sea. So, Pharaoh and his troops chased them in transgression and hostility, until when he was about to drown, he said, “I believe that there is no god but the One in whom the children of Isrā’īl believe, and I am among those who submit to Allah.”'),
(1455, 10, 91, 9, 14, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'آٰلۡـٰٔنَ وَ قَدۡ عَصَیۡتَ قَبۡلُ وَ کُنۡتَ مِنَ الۡمُفۡسِدِیۡنَ ﴿۹۱﴾', 'جواب ملا کہ اب ایمان لاتا ہے حالانکہ تو پہلے نافرمانی کرتا رہا اور مفسد بنا رہا۔', 'اب یہ کہتا ہے اور تو نافرمانی کرتا رہا اس سے پہلے اور رہا گمراہوں میں [۱۲۸]', 'Now (you believe) while you refused to believe before and you were one of the Mufsidoon (evil-doers, corrupts, etc.).', '(Allah said,) “Is it now (that you have come to believe) while you were rebellious all along, and you were among the mischief-makers?'),
(1456, 10, 92, 9, 14, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'فَالۡیَوۡمَ نُنَجِّیۡکَ بِبَدَنِکَ  لِتَکُوۡنَ لِمَنۡ خَلۡفَکَ اٰیَۃً ؕ وَ اِنَّ کَثِیۡرًا مِّنَ النَّاسِ عَنۡ  اٰیٰتِنَا  لَغٰفِلُوۡنَ ﴿٪۹۲﴾', 'تو آج ہم تیرے بدن کو بچا لیں گے تا کہ تو پچھلوں کے لئے عبرت ہو اور بہت سے لوگ ہماری نشانیوں سے بیخبر ہیں۔', 'سو آج بچائے دیتے ہیں ہم تیرے بدن کو تاکہ ہووے تو اپنے پچھلوں کے واسطے نشانی اور بیشک بہت لوگ ہماری قدرتوں پر توجہ نہیں کرتے [۱۲۹]', 'So this day We shall deliver your (dead) body (out from the sea) that you may be a sign to those who come after you! And verily, many among mankind are heedless of Our Ayat (proofs, evidences, verses, lessons, signs , revelations, etc.).', 'So, today, We shall save your body, so that you may become a sign for those after you. And many of the people are heedless of Our signs.”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1457, 10, 93, 10, 15, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ لَقَدۡ بَوَّاۡنَا بَنِیۡۤ  اِسۡرَآءِیۡلَ مُبَوَّاَ صِدۡقٍ وَّ رَزَقۡنٰہُمۡ مِّنَ الطَّیِّبٰتِ ۚ فَمَا اخۡتَلَفُوۡا حَتّٰی جَآءَہُمُ الۡعِلۡمُ ؕ اِنَّ رَبَّکَ یَقۡضِیۡ بَیۡنَہُمۡ یَوۡمَ الۡقِیٰمَۃِ فِیۡمَا کَانُوۡا فِیۡہِ  یَخۡتَلِفُوۡنَ ﴿۹۳﴾', 'اور ہم نے بنی اسرائیل کو رہنے کو عمدہ جگہ دی اور کھانے کو پاکیزہ چیزیں عطا کیں۔ پھر بھی وہ باوجود علم ہونے کے اختلاف کرتے رہے۔ بیشک جن باتوں میں وہ اختلاف کرتے رہے تمہارا پروردگار قیامت کے دن ان میں ان باتوں کا فیصلہ کر دے گا۔', 'اور جگہ دی ہم نے بنی اسرائیل کو پسندیدہ جگہ اور کھانے کو دیں ستھری چیزیں [۱۳۰] سو ان میں پھوٹ نہیں پڑی یہاں تک کہ پہنچی ان کو خبر بیشک تیرا رب ان میں فیصلہ کر ے گا قیامت کے دن جس بات میں کہ ان میں پھوٹ پڑی [۱۳۱]', 'And indeed We settled the Children of Israel in an honourable dwelling place (Sham and Misr), and provided them with good things, and they differed not until the knowledge came to them. Verily, Allah will judge between them on the Day of Resurrection in that in which they used to differ.', 'And surely We gave the children of Isrā’īl a proper place to live, and provided them with good things. Then they did not disagree between themselves but after knowledge had come to them. Surely, Allah will decide between them on the Day of Judgment about the matters in which they used to dispute each other.'),
(1458, 10, 94, 10, 15, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'فَاِنۡ کُنۡتَ فِیۡ شَکٍّ مِّمَّاۤ  اَنۡزَلۡنَاۤ  اِلَیۡکَ فَسۡـَٔلِ الَّذِیۡنَ یَقۡرَءُوۡنَ الۡکِتٰبَ مِنۡ قَبۡلِکَ ۚ لَقَدۡ جَآءَکَ الۡحَقُّ مِنۡ رَّبِّکَ فَلَا تَکُوۡنَنَّ  مِنَ  الۡمُمۡتَرِیۡنَ ﴿ۙ۹۴﴾', 'اب اگر تم کو اس کتاب کے بارے میں جو ہم نے تم پر نازل کی ہے کچھ شک ہو تو جو لوگ تم سے پہلے کی اتری ہوئی کتابیں پڑھتے ہیں ان سے پوچھ لو۔ تمہارے پروردگار کی طرف سے تمہارے پاس حق آ چکا ہے تو تم ہرگز شک کرنے والوں میں نہ ہونا۔', 'سو اگر تو ہے شک میں اس چیز سے کہ اتاری ہم نے تیری طرف تو پوچھ ان سے جو پڑھتے ہیں کتاب تجھ سے پہلے بیشک آئی ہے تیرے پاس حق بات تیرے رب سے سو تو ہرگز مت ہو شک کرنے والا', 'So if you (O Muhammad SAW) are in doubt concerning that which We have revealed unto you, (i.e. that your name is written in the Taurat (Torah) and the Injeel (Gospel)) then ask those who are reading the Book (the Taurat (Torah) and the Injeel (Gospel)) before you. Verily, the truth has come to you from your Lord. So be not of those who doubt (it).', 'So, (O prophet,) even if you are in doubt about what We have sent down to you, ask those who read the Book (revealed) before you. Surely, truth has come to you from your Lord, so never be among those who are suspicious.'),
(1459, 10, 95, 10, 15, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ لَا تَکُوۡنَنَّ مِنَ الَّذِیۡنَ  کَذَّبُوۡا بِاٰیٰتِ اللّٰہِ  فَتَکُوۡنَ  مِنَ  الۡخٰسِرِیۡنَ ﴿۹۵﴾', 'اور نہ ان لوگوں میں ہونا جو اللہ کی آیتوں کی تکذیب کرتے ہیں نہیں تو نقصان اٹھاؤ گے۔', 'اور مت ہو ان میں جنہوں نے جھٹلایا اللہ کی باتوں کو پھر تو بھی ہو جائے خرابی میں پڑنے والا', 'And be not one of those who belie the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah, for then you shall be one of the losers.', 'And never be among those who have rejected Our signs, lest you should be among the losers.'),
(1460, 10, 96, 10, 15, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'اِنَّ الَّذِیۡنَ حَقَّتۡ عَلَیۡہِمۡ کَلِمَتُ رَبِّکَ لَا  یُؤۡمِنُوۡنَ ﴿ۙ۹۶﴾', 'جن لوگوں کے بارے میں اللہ کا حکم عذاب قرار پا چکا ہے وہ ایمان نہیں لانے کے۔', 'جن پر ثابت ہو چکی بات تیرے رب کی وہ ایمان نہ لائیں گے', 'Truly! Those, against whom the Word (Wrath) of your Lord has been justified, will not believe.', 'Surely, those against whom the Word of your Lord stands settled will not believe,'),
(1461, 10, 97, 10, 15, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ لَوۡ جَآءَتۡہُمۡ کُلُّ اٰیَۃٍ حَتّٰی یَرَوُا الۡعَذَابَ  الۡاَلِیۡمَ ﴿۹۷﴾', 'جب تک کہ عذاب الیم نہ دیکھ لیں خواہ انکے پاس ہر طرح کی نشانی آ جائے۔', 'اگرچہ پہنچیں انکو ساری نشانیاں جب تک نہ دیکھ لیں عذاب دردناک [۱۳۲]', 'Even if every sign should come to them, - until they see the painful torment.', 'even though every sign comes to them, unless they witness the painful punishment.'),
(1462, 10, 98, 10, 15, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'فَلَوۡ لَا کَانَتۡ قَرۡیَۃٌ اٰمَنَتۡ فَنَفَعَہَاۤ اِیۡمَانُہَاۤ  اِلَّا قَوۡمَ یُوۡنُسَ ؕ لَمَّاۤ  اٰمَنُوۡا کَشَفۡنَا عَنۡہُمۡ عَذَابَ الۡخِزۡیِ  فِی الۡحَیٰوۃِ الدُّنۡیَا وَ مَتَّعۡنٰہُمۡ اِلٰی حِیۡنٍ ﴿۹۸﴾', 'سو کوئی بستی ایسی کیوں نہ ہوئی کہ ایمان لاتی تو اس کا ایمان اسے نفع دیتا۔ ہاں یونس کی قوم کہ جب ایمان لائی تو ہم نے دنیا کی زندگی میں ان سے ذلت کا عذاب دور کر دیا اور ایک مدت تک فوائد دنیاوی سے انکو بہرہ مند رکھا۔', 'سو کیوں نہ ہوئی کوئی بستی کہ ایمان لاتی پھر کام آتا انکو ایمان لانا مگر یونس کی قوم جب وہ ایمان لائی اٹھا لیا ہم نے ان پر سے ذلت کا عذاب دنیا کی زندگانی میں اور فائدہ پہنچایا ہم نے انکو ایک وقت تک [۱۳۳]', 'Was there any town (community) that believed (after seeing the punishment), and its Faith (at that moment) saved it (from the punishment)? (The answer is none,) - except the people of Yoonus (Jonah); when they believed, We removed from them the torment of disgrace in the life of the (present) world, and permitted them to enjoy for a while.', 'So, how is it that there never was a town, which could have believed and its belief would have been of benefit to it, except the people of Yūnus? When they came to believe, We removed from them the punishment of humiliation in the worldly life and let them enjoy themselves for some time.'),
(1463, 10, 99, 10, 15, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ لَوۡ شَآءَ رَبُّکَ لَاٰمَنَ مَنۡ فِی الۡاَرۡضِ کُلُّہُمۡ جَمِیۡعًا ؕ اَفَاَنۡتَ تُکۡرِہُ النَّاسَ حَتّٰی  یَکُوۡنُوۡا مُؤۡمِنِیۡنَ ﴿۹۹﴾', 'اور اگر تمہارا پروردگار چاہتا تو جتنے لوگ زمین میں ہیں سب کے سب ایمان لے آتے۔ تو کیا تم لوگوں پر زبردستی کرنا چاہتے ہو کہ وہ مومن ہو جائیں؟', 'اور اگر تیرا رب چاہتا بیشک ایمان لے آتے جتنے لوگ کہ زمین میں ہیں سارےتمام اب کیا تو زبردستی کرے گا لوگوں پر کہ ہو جائیں با ایمان [۱۳۴]', 'And had your Lord willed, those on earth would have believed, all of them together. So, will you (O Muhammad SAW) then compel mankind, until they become believers.', 'Had your Lord willed, all those on earth would have believed altogether. Would you, then, compel people, so that they become believers?'),
(1464, 10, 100, 10, 15, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ مَا کَانَ لِنَفۡسٍ اَنۡ تُؤۡمِنَ اِلَّا بِاِذۡنِ اللّٰہِ ؕ وَ یَجۡعَلُ الرِّجۡسَ عَلَی الَّذِیۡنَ لَا یَعۡقِلُوۡنَ ﴿۱۰۰﴾', 'حالانکہ کسی شخص کو قدرت نہیں ہے کہ اللہ کے حکم کے بغیر ایمان لائے اور جو لوگ بے عقل ہیں ان پر وہ کفر و ذلت کی نجاست ڈالتا ہے۔', 'اور کسی سے نہیں ہو سکتا کہ ایمان لائے مگر اللہ کے حکم سے اور وہ ڈالتا ہے گندگی ان پر جو نہیں سوچتے [۱۳۵]', 'It is not for any person to believe, except by the Leave of Allah, and He will put the wrath on those who are heedless.', 'It is not (possible) for any one that he believes except with the will of Allah. And He makes filth settle on those who do not understand.'),
(1465, 10, 101, 10, 15, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'قُلِ انۡظُرُوۡا مَاذَا فِی السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ مَا تُغۡنِی الۡاٰیٰتُ وَ النُّذُرُ عَنۡ قَوۡمٍ لَّا یُؤۡمِنُوۡنَ ﴿۱۰۱﴾', 'ان کفار سے کہو کہ دیکھو تو آسمانوں اور زمین میں کیا کیا کچھ ہے؟ اور جو لوگ ایمان نہیں رکھتے نشانیان اور ڈرانے والے انکے کچھ کام نہیں آتے۔', 'تو کہہ دیکھو تو کیا کچھ ہے آسمانوں میں اور زمین میں اور کچھ کام نہیں آتیں نشانیاں اور ڈرانے والے ان لوگوں کو جو نہیں مانتے [۱۳۶]', 'Say: \"Behold all that is in the heavens and the earth,\" but neither Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) nor warners benefit those who believe not.', 'Say, “Look at what is there in the heavens and the earth.” But, signs and warnings do not suffice a people who do not believe.'),
(1466, 10, 102, 10, 15, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'فَہَلۡ یَنۡتَظِرُوۡنَ اِلَّا مِثۡلَ اَیَّامِ الَّذِیۡنَ خَلَوۡا مِنۡ قَبۡلِہِمۡ ؕ قُلۡ فَانۡتَظِرُوۡۤا اِنِّیۡ مَعَکُمۡ مِّنَ الۡمُنۡتَظِرِیۡنَ ﴿۱۰۲﴾', 'سو جیسے برے دن ان سے پہلے لوگوں پر گذر چکے ہیں اسی طرح کے دنوں کے یہ منتظر ہیں۔ کہدو کہ تم بھی انتظار کرو۔ میں بھی تمہارے ساتھ انتظار کرتا ہوں۔', 'سو اب کچھ نہیں جس کا انتظار کریں مگر انہی کے سے دن جو گذر چکے ہیں ان سے پہلے تو کہہ اب راہ دیکھو میں بھی تمہارے ساتھ راہ دیکھتا ہوں [۱۳۷]', 'Then do they wait for (anything) save for (destruction) like the days of the men who passed away before them? Say: \"Wait then, I am (too) with you among those who wait.\"', 'So, are they waiting for nothing short of something like the days of those who have passed before them? Say, “So wait. I am with you, among those who are waiting.”'),
(1467, 10, 103, 10, 15, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'ثُمَّ نُنَجِّیۡ رُسُلَنَا وَ الَّذِیۡنَ اٰمَنُوۡا کَذٰلِکَ ۚ حَقًّا عَلَیۡنَا نُنۡجِ الۡمُؤۡمِنِیۡنَ ﴿۱۰۳﴾٪', 'پھر ہم اپنے پیغمبروں کو اور مومنوں کو نجات دیتے رہے ہیں اسی طرح ہمارا ذمہ ہے کہ مسلمانوں کو بھی نجات دیں۔', 'پھر ہم بچا لیتے ہیں اپنے رسولوں کو اور ان کو جو ایمان لائے اسی طرح ذمہ ہے ہمارا بچا دیں گے ایمان والوں کو [۱۳۸]', 'Then (in the end) We save Our Messengers and those who believe! Thus it is incumbent upon Us to save the believers.', 'Then We (used to) save Our messengers and those who believed. Similarly, it being undertaken by Us, We shall save the believers.'),
(1468, 10, 104, 11, 16, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'قُلۡ یٰۤاَیُّہَا النَّاسُ اِنۡ  کُنۡتُمۡ  فِیۡ  شَکٍّ مِّنۡ دِیۡنِیۡ فَلَاۤ اَعۡبُدُ الَّذِیۡنَ تَعۡبُدُوۡنَ مِنۡ دُوۡنِ اللّٰہِ وَ لٰکِنۡ اَعۡبُدُ اللّٰہَ الَّذِیۡ یَتَوَفّٰىکُمۡ ۚۖ وَ اُمِرۡتُ اَنۡ اَکُوۡنَ  مِنَ  الۡمُؤۡمِنِیۡنَ ﴿۱۰۴﴾ۙ', 'اے پیغمبر کہدو کہ لوگو اگر تم کو میرے دین میں کسی طرح کا شک ہو تو سن رکھو کہ جن لوگوں کی تم اللہ کے سوا عبادت کرتے ہو میں انکی عبادت نہیں کرتا۔ لیکن میں اس اللہ کی عبادت کرتا ہوں جو تمہاری روحیں قبض کر لیتا ہے۔ اور مجھ کو یہی حکم ہوا ہے کہ ایمان لانے والوں میں ہو جاؤں۔', 'کہہ دے اے لوگو اگر تم شک میں ہو میرے دین سے تو میں عبادت نہیں کرتا جن کی تم عبادت کرتے ہو اللہ کےسوا اور لیکن میں عبادت کرتا ہوں اللہ کی جو کھینچ لیتا ہے تم کو اور مجھ کو حکم ہے کہ رہوں ایمان والوں میں', 'Say (O Muhammad SAW): \"O you mankind! If you are in doubt as to my religion (Islam), then (know that) I will never worship those whom you worship, besides Allah. But I worship Allah Who causes you to die, I am commanded to be one of the believers.', 'Say, “O people, if you are in doubt about my Faith, then, I do not worship those whom you worship beside Allah. Rather, I worship Allah who brings death to you. And I have been ordained to be among the believers,'),
(1469, 10, 105, 11, 16, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ اَنۡ اَقِمۡ  وَجۡہَکَ لِلدِّیۡنِ حَنِیۡفًا ۚ وَ لَا  تَکُوۡنَنَّ  مِنَ  الۡمُشۡرِکِیۡنَ ﴿۱۰۵﴾', 'اور یہ کہ اے  نبی سب سے یکسو ہو کر دین اسلام کی پیروی کئے جاؤ اور مشرکوں میں سے ہرگز نہ ہونا۔', 'اوریہ کہ سیدھا کر منہ اپنا دین پر حنیف ہو کر اور مت ہو شرک والوں میں', '\"And (it is inspired to me): Direct your face (O Muhammad SAW) entirely towards the religion Hanifa (Islamic Monotheism, i.e. to worship none but Allah Alone), and never be one of the Mushrikoon (those who ascribe partners to Allah, polytheists, idolaters, disbelievers in the Oneness of Allah, and those who worship others along with Allah).', 'and that I should make myself firm on Faith, being upright, and never should be among the Mushriks (who ascribe partners to Allah).”'),
(1470, 10, 106, 11, 16, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ لَا تَدۡعُ مِنۡ دُوۡنِ اللّٰہِ مَا لَا یَنۡفَعُکَ وَ لَا یَضُرُّکَ ۚ فَاِنۡ فَعَلۡتَ فَاِنَّکَ اِذًا مِّنَ الظّٰلِمِیۡنَ ﴿۱۰۶﴾', 'اور اللہ کو چھوڑ کو ایسی چیز کو نہ پکارنا جو نہ تمہارا کچھ بھلا کر سکے اور نہ کچھ بگاڑ سکے اب اگر ایسا کرو گے تو ظالموں میں ہو جاؤ گے۔', 'اور مت پکار اللہ کے سوا ایسے کو کہ نہ بھلا کرے تیرا اور نہ برا پھر اگر تو ایسا کرے تو تو بھی اس وقت ہو ظالموں میں [۱۳۹]', '\"And invoke not besides Allah, any that will neither profit you, nor hurt you, but if (in case) you did so, you shall certainly be one of the Zalimoon (polytheists and wrong-doers).\"', 'And do not invoke, other than Allah, what neither benefits you nor harms you, for, if you do so, then you will surely be one of the unjust.'),
(1471, 10, 107, 11, 16, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ اِنۡ یَّمۡسَسۡکَ اللّٰہُ بِضُرٍّ فَلَا کَاشِفَ لَہٗۤ  اِلَّا ہُوَ ۚ وَ اِنۡ یُّرِدۡکَ بِخَیۡرٍ فَلَا رَآدَّ لِفَضۡلِہٖ ؕ یُصِیۡبُ بِہٖ مَنۡ یَّشَآءُ مِنۡ عِبَادِہٖ ؕ وَ ہُوَ  الۡغَفُوۡرُ  الرَّحِیۡمُ ﴿۱۰۷﴾', 'اور اگر اللہ تم کو کوئی تکلیف پہنچائے۔ تو اس کے سوا اس کا کوئی دور کرنے والا نہیں۔ اور اگر تم سے بھلائی کرنی چاہے تو اسکے فضل کو کوئی روکنے والا نہیں۔ وہ اپنے بندوں میں سے جسے چاہتا ہے فائدہ پہنچاتا ہے۔ اور وہ بخشنے والا ہے مہربان ہے۔', 'اور اگر پہنچا دیوے تجھ کو اللہ کچھ تکلیف تو کوئی نہیں اس کو ہٹانے والا اس کے سوا اور اگر پہنچانا چاہے تجھ کو کچھ بھلائی تو کوئی پھرنے والا نہیں اس کے فضل کو پہنچائے اپنا فضل جس پر چاہے اپنے بندوں میں اور وہی ہے بخشنے والا مہربان [۱۴۰]', 'And if Allah touches you with hurt, there is none who can remove it but He; and if He intends any good for you, there is none who can repel His Favour which He causes it to reach whomsoever of His slaves He will. And He is the Oft-Forgiving, Most Merciful.', 'If Allah brings some harm to you, there is none to remove it except He. And if He intends to bring some good to you, there is none to turn His grace back. He brings it to whomever He wills from among His servants. He is the Most-Forgiving, the Very Merciful.'),
(1472, 10, 108, 11, 16, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'قُلۡ یٰۤاَیُّہَا النَّاسُ قَدۡ جَآءَکُمُ الۡحَقُّ مِنۡ رَّبِّکُمۡ ۚ فَمَنِ اہۡتَدٰی فَاِنَّمَا یَہۡتَدِیۡ لِنَفۡسِہٖ ۚ وَ مَنۡ ضَلَّ فَاِنَّمَا یَضِلُّ عَلَیۡہَا ۚ وَ مَاۤ  اَنَا عَلَیۡکُمۡ بِوَکِیۡلٍ ﴿۱۰۸﴾ؕ', 'کہدو کہ لوگو تمہارے پروردگار کہ ہاں سے تمہارے پاس حق آچکا ہے تو جو کوئی ہدایت حاصل کرتا ہے تو ہدایت سے اپنے ہی حق میں بھلائی کرتا ہے اور جو گمراہی اختیار کرتا ہے تو گمراہی سے اپنا ہی نقصان کرتا ہے۔ اور میں تمہارا وکیل نہیں ہوں۔', 'کہہ دے اے لوگو پہنچ چکا حق تم کو تمہارے رب سے اب جو کوئی راہ پر آئے سو وہ راہ پاتا ہے اپنے بھلے کو اور جو کوئی بہکا پھرے سو بہکا پھرے گا اپنے برے کو اور میں تم پر نہیں ہوں مختار [۱۴۱]', 'Say: \"O you mankind! Now truth (i.e. the Quran and Prophet Muhammad SAW), has come to you from your Lord. So whosoever receives guidance, he does so for the good of his own self, and whosoever goes astray, he does so to his own loss, and I am not (set) over you as a Wakeel (disposer of affairs to oblige you for guidance).\"', 'Say, “O people, the truth has come to you from your Lord. So, whoever accepts guidance accepts it to his own benefit, and whoever goes astray does so to his own detriment. And I am not responsible for you.”'),
(1473, 10, 109, 11, 16, 11, 'یَعۡتَذِرُوۡنَ', 'یونس', 'وَ اتَّبِعۡ مَا یُوۡحٰۤی اِلَیۡکَ وَ اصۡبِرۡ  حَتّٰی یَحۡکُمَ  اللّٰہُ ۚۖ وَ ہُوَ خَیۡرُ الۡحٰکِمِیۡنَ ﴿۱۰۹﴾٪', 'اور اے پیغمبر تم کو جو حکم بھیجا جاتا ہے اس کی پیروی کئے جاؤ اور تکلیفوں پر صبر کرو۔ یہاں تک کہ اللہ فیصلہ کر دے اور وہ سب سے بہتر فیصلہ کرنے والا ہے۔', 'اور تو چل اسی پر جو حکم پہنچے تیری طرف اور صبر کر جب تک فیصلہ کرے اللہ اور وہ ہے سب سے بہتر فیصلہ کرنے والا [۱۴۲]', 'And (O Muhammad SAW), follow the inspiration sent unto you, and be patient till Allah gives judgement. And He is the Best of judges.', 'Follow what is being revealed to you, and be patient until Allah gives His judgment, and He is the best of all judges.'),
(1474, 11, 1, 1, 0, 11, 'یَعۡتَذِرُوۡنَ', 'ھود', 'الٓرٰ ۟  کِتٰبٌ اُحۡکِمَتۡ اٰیٰتُہٗ ثُمَّ  فُصِّلَتۡ مِنۡ  لَّدُنۡ  حَکِیۡمٍ  خَبِیۡرٍ ۙ﴿۱﴾', 'الٓرا۔ یہ وہ کتاب ہے جسکی آیتیں جچی تلی ہیں پھر یہ کہ اللہ حکیم و خبیر نازل کرنے والے کی طرف سے بہ تفصیل بیان کی گئ ہیں۔', 'یہ کتاب ہے کہ جانچ لیا ہے اسکی باتوں کو پھر کھولی گئی ہیں ایک حکمت والے خبردار کے پاس سے [۱]', 'Alif-Lam-Ra. (These letters are one of the miracles of the Quran and none but Allah (Alone) knows their meanings).(This is) a Book, the Verses whereof are perfected (in every sphere of knowledge, etc.), and then explained in detail from One (Allah), Who is All-Wise and Well-Acquainted (with all things).', 'Alif , Lām , Rā . (This is) a book the verses of which have been made firm, and elaborated by the One who is All Wise, All Aware,'),
(1475, 11, 2, 1, 0, 11, 'یَعۡتَذِرُوۡنَ', 'ھود', 'اَلَّا تَعۡبُدُوۡۤا اِلَّا اللّٰہَ ؕ اِنَّنِیۡ لَکُمۡ مِّنۡہُ  نَذِیۡرٌ  وَّ بَشِیۡرٌ ۙ﴿۲﴾', 'اس کا پیغام یہ ہے کہ اللہ کے سوا کسی کی عبادت نہ کرو اور میں اسکی طرف سے تم کو ڈر سنانے والا اور خوشخبری دینے والا ہوں۔', 'کہ عبادت نہ کرو مگر اللہ کی [۲] میں تم کو اسی کی طرف سے ڈر اور خوشخبری سناتا ہوں [۳]', '(Saying) worship none but Allah. Verily, I (Muhammad SAW) am unto you from Him a warner and a bringer of glad tidings.', '(directing the Prophet to say to the people,) “You must not worship anyone other than Allah; I am for you a warner from Him, and a bearer of glad tidings;'),
(1476, 11, 3, 1, 0, 11, 'یَعۡتَذِرُوۡنَ', 'ھود', 'وَّ اَنِ اسۡتَغۡفِرُوۡا رَبَّکُمۡ  ثُمَّ  تُوۡبُوۡۤا  اِلَیۡہِ یُمَتِّعۡکُمۡ مَّتَاعًا حَسَنًا اِلٰۤی اَجَلٍ مُّسَمًّی وَّ یُؤۡتِ کُلَّ ذِیۡ فَضۡلٍ فَضۡلَہٗ ؕ وَ اِنۡ تَوَلَّوۡا فَاِنِّیۡۤ  اَخَافُ عَلَیۡکُمۡ  عَذَابَ یَوۡمٍ  کَبِیۡرٍ ﴿۳﴾', 'اور یہ کہ اپنے پروردگار سے بخشش مانگو اور اسکے آگے توبہ کرو وہ تم کو ایک وقت مقررہ تک متاع نیک سے بہرہ مند کرے گا اور ہر لائق فضیلت کو اسکی فضیلت دے گا۔ اور اگر روگردانی کرو گے تو مجھے تمہارے بارے میں قیامت کے بڑے دن کے عذاب کا ڈر ہے۔', 'اور یہ کہ گناہ بخشواؤ اپنے رب سے پھر رجوع کرو اسکی طرف کہ فائدہ پہنچائے تم کو اچھا فائدہ ایک وقت مقرر تک [۴] اور دیوے ہر زیادتی والے کو زیادتی اپنی [۵] اور اگر تم پھر جاؤ گے تو میں ڈرتا ہوں تم پر ایک بڑے دن کےعذاب سے [۶]', 'And (commanding you): \"Seek the forgiveness of your Lord, and turn to Him in repentance, that He may grant you good enjoyment, for a term appointed, and bestow His abounding Grace to every owner of grace (i.e. the one who helps and serves needy and deserving, physically and with his wealth, and even with good words). But if you turn away, then I fear for you the torment of a Great Day (i.e. the Day of Resurrection).', 'and you must seek forgiveness from your Lord, then, turn to Him in repentance, and He will provide you with good things to enjoy for a given time, and bestow His extra favor on everyone who has extra good deeds (in his account). And if you turn away, then, I fear for you the punishment of a terrible day.'),
(1477, 11, 4, 1, 0, 11, 'یَعۡتَذِرُوۡنَ', 'ھود', 'اِلَی اللّٰہِ  مَرۡجِعُکُمۡ ۚ وَ ہُوَ  عَلٰی  کُلِّ  شَیۡءٍ  قَدِیۡرٌ ﴿۴﴾', 'تم سب کو اللہ کی طرف لوٹ کر جانا ہے۔ اور وہ ہر چیز پر قادر ہے۔', 'اللہ کی طرف ہے تم کو لوٹ کر جانا اور وہ ہر چیز پر قادر ہے', 'To Allah is your return, and He is Able to do all things.\"', 'To Allah is your return, and He is powerful over everything.”'),
(1478, 11, 5, 1, 0, 11, 'یَعۡتَذِرُوۡنَ', 'ھود', 'اَلَاۤ  اِنَّہُمۡ  یَثۡنُوۡنَ صُدُوۡرَہُمۡ  لِیَسۡتَخۡفُوۡا مِنۡہُ ؕ اَلَا حِیۡنَ یَسۡتَغۡشُوۡنَ ثِیَابَہُمۡ ۙ یَعۡلَمُ مَا یُسِرُّوۡنَ وَ مَا یُعۡلِنُوۡنَ ۚ اِنَّہٗ عَلِیۡمٌۢ   بِذَاتِ  الصُّدُوۡرِ ﴿۵﴾', 'دیکھو یہ اپنے سینوں کو دہرا کرتے ہیں تاکہ اللہ سے چھپ جائیں۔ سن رکھو جس وقت یہ اپنے کپڑوں میں لپٹ رہے ہوتے ہیں تب بھی وہ انکی چھپی اور کھلی باتوں کو جانتا ہے۔ وہ تو دلوں کی باتوں تک سے آگاہ ہے۔', 'سنتا ہے وہ دوہرے کرتے ہیں اپنے سینے تاکہ چھپائیں اس سے سنتا ہے جس وقت اوڑھتے ہیں اپنے کپڑے جانتا ہے جو کچھ چھپاتے ہیں اور جو ظاہر کرتے ہیں وہ تو جاننے والا ہے دلوں کی بات [۷]', 'No doubt! They did fold up their breasts, that they may hide from Him. Surely, even when they cover themselves with their garments, He knows what they conceal and what they reveal. Verily, He is the All-Knower of the (innermost secrets) of the breasts.', 'Beware, they bend their chests to hide from Him. Beware, when they cover up themselves with their clothes, He knows what they hide and what they expose. Surely, He is All Aware of what lies in the hearts.'),
(1479, 11, 6, 1, 1, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ مَا مِنۡ دَآبَّۃٍ  فِی الۡاَرۡضِ  اِلَّا عَلَی اللّٰہِ  رِزۡقُہَا وَ یَعۡلَمُ مُسۡتَقَرَّہَا وَ مُسۡتَوۡدَعَہَا ؕ کُلٌّ  فِیۡ  کِتٰبٍ مُّبِیۡنٍ ﴿۶﴾', 'اور زمین پر کوئی چلنے پھرنے والا نہیں مگر اس کا رزق اللہ کے ذمے ہے وہ اسکے رہنے کی جگہ کو  بھی جانتا ہے اور جہاں سونپا جاتا ہے اسے بھی۔ یہ سب کچھ کتاب روشن میں لکھا ہوا ہے۔', 'اور کوئی نہیں ہے چلنے والا زمین پر مگر اللہ پر ہے اس کی روزی [۸] اور جانتا ہے جہاں وہ ٹھہرتا ہے اور جہاں سونپا جاتا ہے [۹] سب کچھ موجود ہے کھلی کتاب میں [۱۰]', 'And no (moving) living creature is there on earth but its provision is due from Allah. And He knows its dwelling place and its deposit (in the uterous, grave, etc.). all is in a Clear Book (Al-Lauh Al-Mahfooz - the Book of Decrees with Allah).', 'There is no creature on earth whose sustenance is not undertaken by Allah. He knows its permanent and its temporary place. Everything is in a clear book.'),
(1480, 11, 7, 1, 1, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ ہُوَ الَّذِیۡ خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ فِیۡ سِتَّۃِ  اَیَّامٍ وَّ کَانَ عَرۡشُہٗ عَلَی الۡمَآءِ لِیَبۡلُوَکُمۡ اَیُّکُمۡ اَحۡسَنُ عَمَلًا ؕ وَ لَئِنۡ قُلۡتَ اِنَّکُمۡ مَّبۡعُوۡثُوۡنَ مِنۡۢ بَعۡدِ الۡمَوۡتِ لَیَقُوۡلَنَّ الَّذِیۡنَ  کَفَرُوۡۤا اِنۡ  ہٰذَاۤ   اِلَّا  سِحۡرٌ  مُّبِیۡنٌ ﴿۷﴾', 'اور وہی تو ہے جس نے آسمانوں اور زمین کو چھ دن میں بنایا اور اس وقت اس کا عرش پانی پر تھا تمہارے پیدا کرنے سے مقصود یہ ہے کہ وہ تم کو آزمائے کہ تم میں عمل کے لحاظ سے کون بہتر ہے۔ اور اے نبی اگر تم کہو کہ تم لوگ مرنے کے بعد زندہ کر کے اٹھائے جاؤ گے تو کافر کہہ دیں گے کہ یہ تو کھلا جادو ہوا۔', 'اور وہی ہے جس نے بنائے آسمان اور زمین چھ دن میں [۱۱] اور تھا اس کا تخت پانی پر [۱۲] تاکہ آزمائے تم کو کہ کون تم میں اچھا کرتا ہے کام [۱۳] اور اگر تو کہے کہ تم اٹھو گے مرنے کے بعد تو البتہ کافر کہنے لگیں یہ کچھ نہیں مگر جادو ہے کھلا ہوا [۱۴]', 'And He it is Who has created the heavens and the earth in six Days and His Throne was on the water, that He might try you, which of you is the best in deeds. But if you were to say to them: \"You shall indeed be raised up after death,\" those who disbelieve would be sure to say, \"This is nothing but obvious magic.\"', 'He is the One who created the heavens and the earth in six days, while His throne was on water, so that He might test you as to who among you is better in deed. And if you say, “You shall be raised after death,” the disbelievers will surely say, “This is nothing but sheer magic.”'),
(1481, 11, 8, 1, 1, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ لَئِنۡ اَخَّرۡنَا عَنۡہُمُ الۡعَذَابَ اِلٰۤی اُمَّۃٍ مَّعۡدُوۡدَۃٍ  لَّیَقُوۡلُنَّ مَا یَحۡبِسُہٗ ؕ اَلَا یَوۡمَ یَاۡتِیۡہِمۡ لَیۡسَ مَصۡرُوۡفًا عَنۡہُمۡ وَ حَاقَ بِہِمۡ مَّا کَانُوۡا بِہٖ یَسۡتَہۡزِءُوۡنَ ٪﴿۸﴾', 'اور اگر ایک مدت معین تک ہم ان سے عذاب روک دیں تو کہیں گے کہ کونسی چیز عذاب کو روکے ہوئے ہے؟ دیکھو جس روز وہ ان پر واقع ہو گا پھر ٹلنے کا نہیں۔ اور جس چیز کا یہ مذاق اڑاتے ہیں وہ ان کو گھیر لے گی۔', 'اور اگر ہم روکے رکھیں ان سے عذاب کو ایک مدت معلوم تک تو کہنے لگیں کس چیز نے روک دیا عذاب کو سنتا ہے جس دن آئے گا ان پر نہ پھیرا جائے گا ان سے اور گھیر لے گی ان کو وہ چیز جس پر ٹھٹھے کیا کرتے تھے [۱۵]', 'And if We delay the torment for them till a determined term, they are sure to say, \"What keeps it back?\" Verily, on the day it reaches them, nothing will turn it away from them, and they will be surrounded by (fall in) that at which they used to mock!', 'And if We defer the punishment for them for a certain time, they will say, “What is holding it back?” Beware, the day it will visit them, it shall not be turned back from them, and they shall be besieged by what they used to ridicule.'),
(1482, 11, 9, 2, 2, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ لَئِنۡ اَذَقۡنَا الۡاِنۡسَانَ مِنَّا رَحۡمَۃً  ثُمَّ  نَزَعۡنٰہَا مِنۡہُ ۚ اِنَّہٗ  لَیَـُٔوۡسٌ کَفُوۡرٌ ﴿۹﴾', 'اور اگر ہم انسان کو اپنے پاس سے نعمت بخشیں پھر اس سے اسکو چھین لیں تو ناامید اور ناشکرا ہو جاتا ہے۔', 'اور اگر ہم چکھا دیں آدمی کو اپنی طرف سے رحمت پھر وہ چھین لیں اس سے تو وہ ناامید ناشکر ہوتا ہے [۱۶]', 'And if We give man a taste of Mercy from Us, and then withdraw it from him, verily! He is despairing, ungrateful.', 'If We give man a taste of Our mercy and then take it away from him, he becomes highly desperate, utterly ungrateful.'),
(1483, 11, 10, 2, 2, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ لَئِنۡ اَذَقۡنٰہُ نَعۡمَآءَ بَعۡدَ ضَرَّآءَ مَسَّتۡہُ  لَیَقُوۡلَنَّ ذَہَبَ السَّیِّاٰتُ عَنِّیۡ ؕ اِنَّہٗ  لَفَرِحٌ  فَخُوۡرٌ ﴿ۙ۱۰﴾', 'اور اگر تکلیف پہنچنے کے بعد آسائش کا مزہ چکھائیں تو خوش ہو کر کہتا ہے کہ سب سختیاں مجھ سے دور ہو گئیں۔ بیشک وہ ہے ہی خوشی میں مست ہو جانے والا بڑا فخر جتانے والا۔', 'اور اگر ہم چکھاویں اسکو آرام بعد تکلیف کے جو پہنچی تھی اسکو تو بول اٹھے دور ہوئیں برائیاں مجھ سے وہ تو اترانے والا شیخی خورا ہے [۱۷]', 'But if We let him taste good (favour) after evil (poverty and harm) has touched him, he is sure to say: \"Ills have departed from me.\" Surely, he is exultant, and boastful (ungrateful to Allah).', 'And if We give him a taste of comfort after a hardship has touched him, he will say, “Evils have gone away from me”, (and thus) He will become over-exulting, boastful,'),
(1484, 11, 11, 2, 2, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'اِلَّا الَّذِیۡنَ صَبَرُوۡا وَ عَمِلُوا  الصّٰلِحٰتِ ؕ اُولٰٓئِکَ  لَہُمۡ  مَّغۡفِرَۃٌ   وَّ  اَجۡرٌ  کَبِیۡرٌ ﴿۱۱﴾', 'ہاں جنہوں نے صبر کیا اور عمل نیک کئے یہی ہیں جنکے لئے بخشش اور اجر عظیم ہے۔', 'مگر جو لوگ صابر ہیں اور کرتے ہیں نیکیاں انکے واسطے بخشش ہے اور ثواب بڑا [۱۸]', 'Except those who show patience and do righteous good deeds, those: theirs will be forgiveness and a great reward (Paradise).', 'except those who are patient and do good deeds. Such people will have Allah’s forgiveness and a great reward.'),
(1485, 11, 12, 2, 2, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'فَلَعَلَّکَ تَارِکٌۢ بَعۡضَ مَا یُوۡحٰۤی اِلَیۡکَ وَ ضَآئِقٌۢ  بِہٖ صَدۡرُکَ اَنۡ یَّقُوۡلُوۡا لَوۡ لَاۤ اُنۡزِلَ عَلَیۡہِ  کَنۡزٌ  اَوۡ جَآءَ مَعَہٗ مَلَکٌ ؕ اِنَّمَاۤ  اَنۡتَ نَذِیۡرٌ ؕ وَ اللّٰہُ عَلٰی کُلِّ شَیۡءٍ وَّکِیۡلٌ ﴿ؕ۱۲﴾', 'تو شاید تم کچھ چیز وحی میں سے جو تمہارے پاس آتی ہے چھوڑ دو اور اس خیال سے تمہارا دل تنگ ہو کہ کافر یہ کہنے لگیں کہ اس پر کوئی خزانہ کیوں نہیں نازل ہوا یا اسکے ساتھ کوئی فرشتہ کیوں نہیں آیا۔ اے نبی تم تو صرف نصیحت کرنے والے ہو۔ اور اللہ ہر چیز کا نگہبان ہے۔', 'سو کہیں تو چھوڑ بیٹھے گا کچھ چیز ان میں سے جو وحی آئی تیری طرف اور تنگ ہو گا اس سے تیرا جی اس بات پر کہ وہ کہتے ہیں کیوں نہ اترا اس پر خزانہ یا کیوں نہ آیا اسکے ساتھ فرشتہ تو تو ڈرانے والا ہے اور اللہ ہے ہر چیز کا ذمہ دار [۱۹]', 'So perchance you (Muhammad SAW) may give up a part of what is revealed unto you, and that your breast feels straitened for it because they say, \"Why has not a treasure been sent down unto him, or an angel has come with him?\" But you are only a warner. And Allah is a Wakeel (Disposer of affairs, Trustee, Guardian, etc.) over all things.', 'Is it then possible from you (O Prophet,) that you will abandon some of what is being revealed to you, and that your heart will be straitened thereby, because they say, “Why has a treasure not been sent down to him or an angel not come with him?” You are but a warner. And Allah takes care of everything.'),
(1486, 11, 13, 2, 2, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'اَمۡ یَقُوۡلُوۡنَ افۡتَرٰىہُ ؕ قُلۡ فَاۡتُوۡا بِعَشۡرِ سُوَرٍ مِّثۡلِہٖ مُفۡتَرَیٰتٍ وَّ ادۡعُوۡا مَنِ اسۡتَطَعۡتُمۡ مِّنۡ دُوۡنِ اللّٰہِ  اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ ﴿۱۳﴾', 'کیا یہ لوگ کہتے ہیں کہ اس نے قرآن ازخود بنا لیا ہے کہدو کہ اگر سچے ہو تو تم بھی ایسی دس سورتیں بنا لاؤ اور اللہ کے سوا جس جس کو بلا سکتے ہو بلا بھی لو۔', 'کیا کہتے ہیں کہ بنا لیا ہے تو قرآن کو کہہ دے تم بھی لے آؤ ایک دس سورتیں ایسی بنا کر اور بلا لو جس کو بلا سکو اللہ کے سوا اگر ہو تم سچے', 'Or they say, \"He (Prophet Muhammad SAW) forged it (the Quran).\" Say: \"Bring you then ten forged Soorah (chapters) like unto it, and call whomsoever you can, other than Allah (to your help), if you speak the truth!\"', 'Do they say that he has fabricated it? Say (to them), “Then bring ten Sūrahs like this, fabricated. And call whomsoever you can, other than Allah, if you are true.”'),
(1487, 11, 14, 2, 2, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'فَاِلَّمۡ یَسۡتَجِیۡبُوۡا لَکُمۡ فَاعۡلَمُوۡۤا اَنَّمَاۤ اُنۡزِلَ بِعِلۡمِ اللّٰہِ وَ اَنۡ  لَّاۤ  اِلٰہَ  اِلَّا ہُوَ ۚ فَہَلۡ  اَنۡتُمۡ  مُّسۡلِمُوۡنَ ﴿۱۴﴾', 'پس اگر وہ تمہاری بات قبول نہ کریں تو جان لو کہ یہ قرآن  اللہ کے علم سے اترا ہے اور یہ کہ اسکے سوا کوئی معبود نہیں تو کیا تم لوگ اسلام لاتے ہو۔', 'پھر اگر نہ پورا کریں تمہارا کہنا تو جان لو کہ قرآن تو اترا ہے اللہ کی وحی سے اور یہ کہ کوئی حاکم نہیں اسکے سوا پھر اب تم حکم مانتے ہو [۲۰]', 'If then they answer you not, know then that the Revelation (this Quran) is sent down with the Knowledge of Allah and that La ilaha illa Huwa: (none has the right to be worshipped but He)! Will you then be Muslims (those who submit to Islam)?', 'So, if they do not respond to your call, then be assured that it has been sent down with the knowledge of Allah and that there is no god but He. So, do you submit?'),
(1488, 11, 15, 2, 2, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'مَنۡ کَانَ یُرِیۡدُ الۡحَیٰوۃَ  الدُّنۡیَا وَ زِیۡنَتَہَا نُوَفِّ اِلَیۡہِمۡ اَعۡمَالَہُمۡ فِیۡہَا وَ ہُمۡ  فِیۡہَا  لَا  یُبۡخَسُوۡنَ ﴿۱۵﴾', 'جو لوگ دنیا کی زندگی اور اسکی زیب و زینت کے طالب ہوں ہم انکے اعمال کا بدلہ انہیں دنیا ہی میں دے دیتے ہیں اور اس میں انکی حق تلفی نہیں کی جاتی۔', 'جو کوئی چاہے دنیا کی زندگانی اور اسکی زینت بھگتا دیں گے ہم انکو ان کے عمل دنیا میں اور انکو اس میں کچھ نقصان نہیں [۲۱]', 'Whosoever desires the life of the world and its glitter; to them We shall pay in full (the wages of) their deeds therein, and they will have no diminution therein.', 'Those who seek (merely) the worldly life and its beauty, We will fully recompense them herein for their acts, and their right will not be curtailed in this world.'),
(1489, 11, 16, 2, 2, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'اُولٰٓئِکَ الَّذِیۡنَ لَیۡسَ لَہُمۡ فِی الۡاٰخِرَۃِ  اِلَّا النَّارُ ۫ۖ وَ  حَبِطَ مَا صَنَعُوۡا  فِیۡہَا وَ  بٰطِلٌ  مَّا  کَانُوۡا  یَعۡمَلُوۡنَ ﴿۱۶﴾', 'یہ وہ لوگ ہیں جنکے لئے آخرت میں آتش جہنم کے سوا اور کچھ نہیں اور جو عمل انہوں نے دنیا میں کئے سب برباد اور جو کچھ یہ کرتے رہے سب ضائع ہوا۔', 'یہی ہیں جن کے واسطے کچھ نہیں آخرت میں آگ کے سوا [۲۲] اور برباد ہوا جو کچھ کیا تھا یہاں اور خراب گیا جو کمایا تھا [۲۳]', 'They are those for whom there is nothing in the Hereafter but Fire; and vain are the deeds they did therein. And of no effect is that which they used to do.', 'Those are the people for whom there is nothing in the Hereafter except fire. Nullified will be whatever they worked herein, and void will be what they have been doing.'),
(1490, 11, 17, 2, 2, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'اَفَمَنۡ کَانَ عَلٰی بَیِّنَۃٍ مِّنۡ رَّبِّہٖ وَ یَتۡلُوۡہُ شَاہِدٌ مِّنۡہُ وَ مِنۡ قَبۡلِہٖ  کِتٰبُ مُوۡسٰۤی اِمَامًا وَّ  رَحۡمَۃً ؕ اُولٰٓئِکَ یُؤۡمِنُوۡنَ بِہٖ ؕ وَ مَنۡ یَّکۡفُرۡ بِہٖ مِنَ الۡاَحۡزَابِ فَالنَّارُ مَوۡعِدُہٗ ۚ فَلَا تَکُ فِیۡ مِرۡیَۃٍ  مِّنۡہُ ٭ اِنَّہُ الۡحَقُّ مِنۡ رَّبِّکَ وَ لٰکِنَّ اَکۡثَرَ  النَّاسِ لَا  یُؤۡمِنُوۡنَ ﴿۱۷﴾', 'بھلا جو لوگ اپنے پروردگار کی طرف سے دلیل روشن رکھتے ہوں اور انکے ساتھ ایک آسمانی گواہ بھی اسکی جانب سے ہو اور اس سے پہلے موسٰی کی کتاب ہو جو پیشوا اور رحمت ہے تو کیا وہ قرآن پر ایمان نہیں لائیں گے؟ یہی لوگ تو اس پر ایمان لاتے ہیں اور جو کوئی اور فرقوں میں سے اس سے منکر ہو تو اس کا ٹھکانہ آگ ہے تو تم اس قرآن سے شک میں نہ ہونا۔ یہ تمہارے پروردگار کی طرف سے حق ہے لیکن اکثر لوگ ایمان نہیں لاتے۔', 'بھلا ایک شخص جو ہے صاف رستہ پر اپنے رب کے اور اس کے ساتھ ساتھ ہے ایک گواہ اللہ کی طرف سے اور اس سے پہلے گواہ تھی موسٰی کی کتاب رستہ بتلاتی اور بخشواتی (اورونکی برابر ہے)[۲۴] یہی لوگ مانتے ہیں قرآن کو اور جو کوئی منکر ہو اس سے سب فرقوں میں سےسو دوزخ ہے ٹھکانہ اس کا [۲۵] سو تو مت رہ شبہ میں اس سے بیشک وہ حق ہے تیرے رب کی طرف سے اور پر بہت سے لوگ یقین نہیں کرتے [۲۶]', 'Can they (Muslims) who rely on a clear proof (the Quran) from their Lord, and whom a witness (Prophet Muhammad SAW through Jibrael (Gabriel ÓáÇã)) from Him follows it (can they be equal with the disbelievers); and before it, came the Book of Moosa (Moses), a guidance and a mercy, they believe therein, but those of the sects (Jews, Christians and all the other non-Muslim nations) that reject it (the Quran), the Fire will be their promised meeting-place. So be not in doubt about it (i.e. those who denied Prophet Muhammad SAW and also denied all that which he brought from Allah, surely, they will enter Hell). Verily, it is the truth from your Lord, but most of the mankind believe not.', 'Then, can such people be equal to the one who has a clear proof from his Lord, followed by an evidence from within, and before which there was the Book of Mūsā, a guide and a mercy? Such people believe in it; and whoever of the groups denies its veracity, his promised place is the Fire. So, do not be in doubt about it. Surely, it is the truth from your Lord, but most of people do not believe.'),
(1491, 11, 18, 2, 2, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ مَنۡ اَظۡلَمُ  مِمَّنِ افۡتَرٰی عَلَی اللّٰہِ  کَذِبًا ؕ اُولٰٓئِکَ یُعۡرَضُوۡنَ عَلٰی رَبِّہِمۡ وَ یَقُوۡلُ الۡاَشۡہَادُ  ہٰۤؤُلَآءِ الَّذِیۡنَ کَذَبُوۡا عَلٰی رَبِّہِمۡ ۚ اَلَا لَعۡنَۃُ اللّٰہِ عَلَی الظّٰلِمِیۡنَ ﴿ۙ۱۸﴾', 'اور اس سے بڑھ کو ظالم کون ہو گا جو اللہ پر جھوٹ باندھے؟ ایسے لوگ اپنے رب کے سامنے پیش کئے جائیں گے اور گواہ کہیں گے کہ یہی لوگ ہیں جنہوں نے اپنے پروردگار پر جھوٹ بولا تھا۔ سن رکھو کہ ظالموں پر اللہ کی لعنت ہے۔', 'اور اس سے بڑھ کر ظالم کون جو باندھے اللہ پر جھوٹ [۲۷] وہ لوگ روبرو آئیں گے اپنے رب کے اور کہیں گے گواہی دینے والے  یہی ہیں جنہوں نے جھوٹ کہا تھا اپنے رب پر [۲۸] سن لو پھٹکار ہے اللہ کی ناانصاف لوگوں پر', 'And who does more wrong than he who invents a lie against Allah. Such wi,l be brought before their Lord, and the witnesses will say, \"These are the ones who lied against their Lord!\" No doubt! the curse of Allah is on the Zalimoon (polytheists, wrong-doers, oppressors, etc.).', 'Who is more unjust than the one who forges a lie against Allah? Such people will be presented before their Lord, and the witnesses will say, “These are the ones who lied against their Lord. Lo! the curse of Allah lies on the unjust,'),
(1492, 11, 19, 2, 2, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'الَّذِیۡنَ یَصُدُّوۡنَ عَنۡ سَبِیۡلِ اللّٰہِ وَ یَبۡغُوۡنَہَا عِوَجًا ؕ وَ ہُمۡ بِالۡاٰخِرَۃِ ہُمۡ کٰفِرُوۡنَ ﴿۱۹﴾', 'جو اللہ کے رستے سے روکتے اور اس میں کجی چاہتے ہیں۔ اور وہ آخرت کا بھی انکار کرتے ہیں۔', 'جو کہ روکتے ہیں اللہ کی راہ سے اور ڈھونڈھتے ہیں اس میں کجی اور وہی ہیں آخر ت سے منکر [۲۹]', 'Those who hinder (others) from the Path of Allah (Islamic Monotheism), and seek a crookedness therein, while they are disbelievers in the Hereafter.', 'the ones who prevent (people) from the way of Allah and seek crookedness in it, and who are deniers of the Hereafter.”'),
(1493, 11, 20, 2, 2, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'اُولٰٓئِکَ لَمۡ یَکُوۡنُوۡا مُعۡجِزِیۡنَ فِی الۡاَرۡضِ وَ مَا کَانَ لَہُمۡ مِّنۡ دُوۡنِ اللّٰہِ مِنۡ  اَوۡلِیَآءَ ۘ یُضٰعَفُ لَہُمُ الۡعَذَابُ ؕ مَا کَانُوۡا یَسۡتَطِیۡعُوۡنَ السَّمۡعَ وَ مَا کَانُوۡا  یُبۡصِرُوۡنَ ﴿۲۰﴾', 'یہ لوگ زمین میں کہیں چھپ کر اللہ کو ہرا نہیں سکتے۔ اور نہ اللہ کے سوا کوئی ان کا حمایتی ہے۔ اے پیغمبر انکو دگنا عذاب دیا جائے گا۔ کیونکہ یہ شدت کفر سے تمہاری بات نہیں سن سکتے تھے اور نہ تم کو دیکھ سکتے تھے۔', 'وہ لوگ نہیں تھکانے والے زمین میں بھاگ کر اور نہیں انکے واسطے اللہ کے سوا کوئی حمایتی [۳۰] دونا ہے ان کے لئے عذاب [۳۱] نہ طاقت رکھتے تھے سننے کی اور نہ دیکھتے تھے [۳۲]', 'By no means will they escape (from Allahs Torment) on earth, nor have they protectors besides Allah! Their torment will be doubled! They could not bear to hear (the preachers of the truth) and they used not to see (the truth because of their severe aversin, inspite of the fact that they had the sense of hearing and sight).', 'They were unable to frustrate (Allah’s plan) on the earth, and they had no supporters besides Allah. Punishment will be doubled for them. They were not able to hear, nor would they see.'),
(1494, 11, 21, 2, 2, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'اُولٰٓئِکَ الَّذِیۡنَ خَسِرُوۡۤا اَنۡفُسَہُمۡ  وَ ضَلَّ عَنۡہُمۡ  مَّا  کَانُوۡا  یَفۡتَرُوۡنَ ﴿۲۱﴾', 'یہی ہیں جنہوں نے اپنے آپکو خسارے میں ڈالا اور جو کچھ یہ افترا کیا کرتے تھے ان سے جاتا رہا۔', 'وہی ہیں جو کھو بیٹھے اپنی جان اور گم ہو گیا ان سےجو جھوٹ باندھا تھا [۳۳]', 'They are those who have lost their ownselves, and their invented false deities will vanish from them.', 'Those are the ones who brought loss to their own selves, and all that they used to fabricate vanished from them.'),
(1495, 11, 22, 2, 2, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'لَا جَرَمَ  اَنَّہُمۡ  فِی الۡاٰخِرَۃِ  ہُمُ الۡاَخۡسَرُوۡنَ ﴿۲۲﴾', 'بلاشبہ یہ لوگ آخرت میں سب سے زیادہ نقصان پانے والے ہیں۔', 'اس میں شک نہیں کہ یہ لوگ آخرت میں یہی ہیں سب سے زیادہ نقصان میں', 'Certainly, they are those who will be the greatest losers in the Hereafter.', 'Essentially, they are the worst losers in the Hereafter.'),
(1496, 11, 23, 2, 2, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'اِنَّ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ وَ اَخۡبَتُوۡۤا اِلٰی رَبِّہِمۡ ۙ اُولٰٓئِکَ اَصۡحٰبُ الۡجَنَّۃِ ۚ ہُمۡ  فِیۡہَا  خٰلِدُوۡنَ ﴿۲۳﴾', 'جو لوگ ایمان لائے اور عمل نیک کئے۔ اور اپنے پروردگار کے آگے عاجزی کی۔ یہی صاحب جنت ہیں۔ ہمیشہ اس میں رہیں گے۔', 'البتہ جو لوگ ایمان لائے اور کام کئے نیک اور عاجزی کی اپنے رب کے سامنے وہ ہیں جنت کے رہنے والے وہ اسی میں رہا کریں گے [۳۴]', 'Verily, those who believe (in the Oneness of Allah - Islamic Monotheism) and do righteous good deeds, and humble themselves (in repentance and obedience) before their Lord, - they will be dwellers of Paradise to dwell therein forever.', 'Surely, those who believe and do good deeds and humble themselves before their Lord, those are the people of Paradise. There they shall live forever.'),
(1497, 11, 24, 2, 2, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'مَثَلُ الۡفَرِیۡقَیۡنِ کَالۡاَعۡمٰی وَ الۡاَصَمِّ وَ الۡبَصِیۡرِ وَ السَّمِیۡعِ ؕ ہَلۡ یَسۡتَوِیٰنِ مَثَلًا ؕ اَفَلَا  تَذَکَّرُوۡنَ ﴿٪۲۴﴾', 'دونوں فریقوں یعنی کافر اور مومن کی مثال ایسی ہے جیسے ایک اندھا بہرا ہو اور ایک دیکھتا سنتا۔ بھلا دونوں کا حال یکساں ہو سکتا ہے؟ پھر تم سوچتے کیوں نہیں۔', 'مثال ان دونوں فرقوں کی جیسے ایک تو اندھا اور بہرا اور دوسرا دیکھتا اور سنتا کیا برابر ہے دونوں کا حال پھر کیا تم غور نہیں کرتے [۳۵]', 'The likeness of the two parties is as the blind and the deaf and the seer and the hearer. Are they equal when compared? Will you not then take heed?', 'The example of the two groups is that of a blind and deaf person on the one hand, and a seeing and hearing one on the other. Are the two equal when compared? Would you still pay no heed?'),
(1498, 11, 25, 3, 3, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ لَقَدۡ اَرۡسَلۡنَا نُوۡحًا اِلٰی قَوۡمِہٖۤ ۫ اِنِّیۡ لَکُمۡ  نَذِیۡرٌ  مُّبِیۡنٌ ﴿ۙ۲۵﴾', 'اور ہم نے نوح کو انکی قوم کی طرف بھیجا تو انہوں نے ان سے کہا کہ میں تم کو کھول کھول کر ڈر سنانے اور یہ پیغام پہنچانے آیا ہوں۔', 'اور ہم نے بھیجا نوح کو اسکی قوم کی طرف کہ میں تم کو ڈر کی بات سناتا ہوں کھول کر [۳۶]', 'And indeed We sent Nooh (Noah) to his people (and he said): \"I have come to you as a plain warner.\"', 'We sent NūH to his people (saying to them): “I am here to warn you'),
(1499, 11, 26, 3, 3, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'اَنۡ  لَّا تَعۡبُدُوۡۤا اِلَّا اللّٰہَ ؕ اِنِّیۡۤ  اَخَافُ عَلَیۡکُمۡ  عَذَابَ  یَوۡمٍ  اَلِیۡمٍ ﴿۲۶﴾', 'کہ اللہ کے سوا کسی کی عبادت نہ کرو۔ مجھے تمہاری نسبت دردناک عذاب کا خوف ہے۔', 'کہ نہ پرستش کرو اللہ کے سوا [۳۷] میں ڈرتا ہوں تم پر دردناک دن کے عذاب سے [۳۸]', '\"That you worship none but Allah, surely, I fear for you the torment of a painful Day.\"', 'that you should worship none but Allah, (otherwise) I fear for you the punishment of a painful day.”'),
(1500, 11, 27, 3, 3, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'فَقَالَ الۡمَلَاُ الَّذِیۡنَ کَفَرُوۡا مِنۡ قَوۡمِہٖ مَا نَرٰىکَ اِلَّا بَشَرًا مِّثۡلَنَا وَ مَا نَرٰىکَ اتَّبَعَکَ اِلَّا الَّذِیۡنَ ہُمۡ اَرَاذِلُنَا بَادِیَ الرَّاۡیِ ۚ وَ مَا نَرٰی لَکُمۡ  عَلَیۡنَا مِنۡ فَضۡلٍۭ  بَلۡ  نَظُنُّکُمۡ  کٰذِبِیۡنَ ﴿۲۷﴾', 'تو انکی قوم کے سردار جو کافر تھے کہنے لگے کہ ہم تم کو اپنے ہی جیسا ایک آدمی دیکھتے ہیں اور یہ بھی دیکھتے ہیں کہ تمہارے پیرو وہی لوگ ہوئے ہیں جو ہم میں ادنٰی درجے کے ہیں۔ اور وہ بھی سطحی رائے سے اور ہم تم میں اپنے اوپر کسی طرح کی فضیلت نہیں دیکھتے بلکہ تمہیں جھوٹا خیال کرتے ہیں۔', 'پھر بولے سردار جو کافر تھے اس کی قوم کے ہم کو تو تو نظر نہیں آتا مگر ایک آدمی ہم جیسا اور دیکھتے نہیں کوئی تابع ہوا ہو تیرا مگر جو ہم میں نیچ قوم ہیں بلا تامل اور ہم نہیں دیکھتے تم کو اوپر اپنے کچھ بڑائی بلکہ ہم کو تو خیال ہے کہ تم سب جھوٹے ہو [۳۹]', 'The chiefs of the disbelievers among his people said: \"We see you but a man like ourselves, nor do we see any follow you but the meanest among us and they (too) followed you without thinking. And we do not see in you any merit above us, in fact we think you are liars.\"', 'So the chiefs of his people who disbelieved replied, “We are not seeing that you are anything more than a man like us, and we are not seeing that any people have followed you except those who are the meanest among us, and we have not seen in you people any superiority over us; rather, we believe that you are liars.”'),
(1501, 11, 28, 3, 3, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالَ یٰقَوۡمِ اَرَءَیۡتُمۡ اِنۡ کُنۡتُ عَلٰی بَیِّنَۃٍ مِّنۡ رَّبِّیۡ  وَ اٰتٰىنِیۡ رَحۡمَۃً مِّنۡ عِنۡدِہٖ فَعُمِّیَتۡ عَلَیۡکُمۡ ؕ اَنُلۡزِمُکُمُوۡہَا وَ اَنۡتُمۡ لَہَا کٰرِہُوۡنَ ﴿۲۸﴾', 'فرمایا کہ اے قوم! دیکھو تو اگر میں اپنے پروردگار کی طرف سے دلیل روشن رکھتا ہوں اور اس نے مجھے اپنے ہاں سے رحمت بخشی ہو جس کی حقیقت تم سے پوشیدہ ہو گئ ہے تو کیا ہم اس کے لئے تمہیں مجبور کر سکتے ہیں جبکہ تم اس سے ناخوش ہو۔', 'بولا اے قوم دیکھو تو اگر میں ہوں صاف راستہ پر اپنے رب کے اور اس نے بھیجی مجھ پر رحمت اپنے پاس سے پھر اس کو تمہاری آنکھ سے مخفی رکھا تو کیا ہم تم کو مجبور  کر سکتے ہیں اس پر اور تم اس سے بیزا ہو [۴۰]', 'He said: \"O my people! Tell me, if I have a clear proof from my Lord, and a Mercy (Prophethood, etc.) has come to me from Him, but that (Mercy) has been obscured from your sight. Shall we compel you to accept it (Islamic Monotheism) when you have a strong hatred for it?', 'He said, “O my people, tell me, if I am on a clear path from my Lord, and He has bestowed mercy upon me from Himself which is hidden from your sight, shall we, then, impose it upon you by force, while you are averse to it?'),
(1502, 11, 29, 3, 3, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ یٰقَوۡمِ لَاۤ  اَسۡئَلُکُمۡ عَلَیۡہِ مَالًا ؕ اِنۡ  اَجۡرِیَ   اِلَّا عَلَی اللّٰہِ وَ مَاۤ  اَنَا بِطَارِدِ الَّذِیۡنَ اٰمَنُوۡا ؕ اِنَّہُمۡ مُّلٰقُوۡا  رَبِّہِمۡ  وَ لٰکِنِّیۡۤ  اَرٰىکُمۡ قَوۡمًا تَجۡہَلُوۡنَ ﴿۲۹﴾', 'اور اے قوم! میں اس نصیحت کے بدلے تم سے مال و زر کا مطالبہ تو نہیں کرتا میرا صلہ تو اللہ کے ذمے ہے اور جو لوگ ایمان لائے ہیں میں انکو نکالنے والا بھی نہیں ہوں۔ وہ تو اپنے پروردگار سے ملنے والے ہیں لیکن میں دیکھتا ہوں کہ تم لوگ نادانی کر رہے ہو۔', 'اور اے میری قوم نہیں مانگتا میں تم سے اس پر کچھ مال میری مزدوری نہیں مگر اللہ پر اور میں نہیں ہانکنے والا ایمان والوں کو ان کو ملنا ہے اپنے رب سے [۴۱] لیکن میں دیکھتا ہوں تم لوگ جاہل ہو [۴۲]', '\"And O my people! I ask of you no wealth for it, my reward is from none but Allah. I am not going to drive away those who have believed. Surely, they are going to meet their Lord, but I see that you are a people that are ignorant.', 'And, O my people, I do not demand from you any wealth for it. My reward is with none but Allah. And I am not the one who could drive the believers away. Surely, they will be meeting their Lord (gracefully), but I do see your behavior is that of ignorance.'),
(1503, 11, 30, 3, 3, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ یٰقَوۡمِ مَنۡ یَّنۡصُرُنِیۡ مِنَ اللّٰہِ  اِنۡ طَرَدۡتُّہُمۡ ؕ اَفَلَا   تَذَکَّرُوۡنَ ﴿۳۰﴾', 'اے میری قوم! اگر میں انکو نکال دوں تو اللہ کی گرفت سے بچانے کے لئے کون میری مدد کر سکتا ہے۔ بھلا تم غور کیوں نہیں کرتے؟', 'اور اےقوم کون چھڑائے مجھ کو اللہ سے اگر ان کو ہانک دوں کیا تم دھیان نہیں کرتے [۴۳]', '\"And O my people! Who will help me against Allah, if I drove them away? Will you not then give a thought?', 'O my people, who would help me against (the punishment of) Allah, if I were to drive them away? Would you still take no lesson?'),
(1504, 11, 31, 3, 3, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ لَاۤ   اَقُوۡلُ  لَکُمۡ  عِنۡدِیۡ خَزَآئِنُ اللّٰہِ وَ لَاۤ  اَعۡلَمُ  الۡغَیۡبَ وَ لَاۤ  اَقُوۡلُ  اِنِّیۡ مَلَکٌ وَّ لَاۤ  اَقُوۡلُ لِلَّذِیۡنَ تَزۡدَرِیۡۤ اَعۡیُنُکُمۡ  لَنۡ  یُّؤۡتِیَہُمُ  اللّٰہُ خَیۡرًا ؕ اَللّٰہُ  اَعۡلَمُ  بِمَا فِیۡۤ  اَنۡفُسِہِمۡ ۚۖ اِنِّیۡۤ  اِذًا لَّمِنَ  الظّٰلِمِیۡنَ ﴿۳۱﴾', 'اور میں نہ تم سے یہ کہتا ہوں کہ میرے پاس اللہ کے خزانے ہیں اور نہ یہ کہ میں غیب جانتا ہوں اور نہ یہ کہتا ہوں کہ میں فرشتہ ہوں اور نہ ان لوگوں کی نسبت جنکو تم حقارت کی نظر سے دیکھتے ہو یہ کہتا ہوں کہ اللہ انکو بھلائی یعنی اعمال کی جزا نہیں دے گا۔ جو انکے دلوں میں ہے اسے اللہ خوب جانتا ہے۔ اگر میں ایسا کہوں تو بےانصافوں میں ہو جاؤں۔', 'اور میں نہیں کہتا تم کو کہ میر ے پاس ہیں خزانے اللہ کے اور نہ میں خبر رکھوں غیب کی اور نہ کہوں کہ میں فرشتہ ہوں اور نہ کہوں گا کہ جو لوگ تمہاری آنکھ میں حقیر ہیں نہ دے گا ان کو اللہ بھلائی اللہ خوب جانتا ہے جو کچھ انکے جی میں ہے یہ کہوں تو میں بے انصاف ہوں [۴۴]', '\"And I do not say to you that with me are the Treasures of Allah, \"Nor that I know the Ghaib (unseen); \"nor do I say I am an angel, and I do not say of those whom your eyes look down upon that Allah will not bestow any good on them. Allah knows what is in their inner-selves (as regards belief, etc.). In that case, I should, indeed be one of the Zalimoon (wrong-doers, oppressors, etc.).\"', 'And I do not say to you that I have the treasures of Allah, nor that I have the knowledge of the unseen, nor do I say that I am an angel. Nor do I say (as you do) about those who are contemptible in your eyes that Allah will never award them any good; Allah knows best what lies in their hearts. (If I were to say so,) then, I would indeed be one of the unjust.”'),
(1505, 11, 32, 3, 3, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالُوۡا یٰنُوۡحُ قَدۡ جٰدَلۡتَنَا فَاَکۡثَرۡتَ جِدَالَنَا فَاۡتِنَا بِمَا تَعِدُنَاۤ  اِنۡ  کُنۡتَ مِنَ  الصّٰدِقِیۡنَ ﴿۳۲﴾', 'انہوں نے کہا کہ نوح تم نے ہم سے جھگڑا تو کیا اور جھگڑا بھی بہت کیا اب اگر سچے ہو تو جس چیز سے ہمیں ڈراتے ہو وہ ہم پر لا نازل کرو۔', 'بولے اے نوح تو نے ہم سے جگھڑا کیا اور بہت جھگڑ چکا اب لے آ جو تو وعدہ کرتا ہے ہم سے اگر تو سچا ہے [۴۵]', 'They said: \"O Nooh (Noah)! You have disputed with us and much have you prolonged the dispute with us, now bring upon us what you threaten us with, if you are of the truthful.\"', 'They said, “O NūH, you have debated with us, and debated too much. Now bring upon us what you threaten us with, if you are one of the truthful.”'),
(1506, 11, 33, 3, 3, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالَ اِنَّمَا یَاۡتِیۡکُمۡ بِہِ اللّٰہُ اِنۡ شَآءَ وَ مَاۤ  اَنۡتُمۡ  بِمُعۡجِزِیۡنَ ﴿۳۳﴾', 'نوح نے کہا کہ اس عذاب کو تو اللہ ہی چاہے گا تو نازل کرے گا۔ اور تم اللہ کو کسی طرح ہرا نہیں سکتے۔', 'کہا کہ لائے گا تو اس کو اللہ ہی اگر چاہے گا اور تم نہ تھکا سکو گے بھاگ کر [۴۶]', 'He said: \"Only Allah will bring it (the punishment) on you, if He will, and then you will escape not.', 'He said, “Only Allah will bring it to you, if He so wills, and you cannot frustrate (His will).'),
(1507, 11, 34, 3, 3, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ لَا یَنۡفَعُکُمۡ نُصۡحِیۡۤ  اِنۡ  اَرَدۡتُّ اَنۡ اَنۡصَحَ لَکُمۡ  اِنۡ کَانَ اللّٰہُ یُرِیۡدُ اَنۡ یُّغۡوِیَکُمۡ ؕ ہُوَ رَبُّکُمۡ ۟ وَ اِلَیۡہِ تُرۡجَعُوۡنَ ﴿ؕ۳۴﴾', 'اور اگر میں یہ چاہوں کہ تمہاری خیرخواہی کروں اور اللہ یہ چاہے کہ تمہیں گمراہ رہنے دے تو میری خیر خواہی تم کو کچھ فائدہ نہیں دے سکتی۔ وہی تمہارا پروردگار ہے اور تمہیں اسی کی طرف لوٹ کر جانا ہے۔', 'اور نہ کارگر ہو گی تم کو میری نصیحت جو چاہوں کہ تم کو نصیحت کروں اگر اللہ چاہتا ہو گا کہ تم کو گمراہ کرے وہی ہے رب تمہارا اور اسی کی طرف لوٹ جاؤ گے [۴۷]', '\"And my advice will not profit you, even if I wish to give you good counsel, if Allahs Will is to keep you astray. He is your Lord! and to Him you shall return.\"', 'My good counsel will not profit you, even though I wish you the best, if Allah wills to let you go astray. He is your Lord, and to Him you shall be made to return.”'),
(1508, 11, 35, 3, 3, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'اَمۡ  یَقُوۡلُوۡنَ افۡتَرٰىہُ ؕ قُلۡ  اِنِ افۡتَرَیۡتُہٗ فَعَلَیَّ  اِجۡرَامِیۡ وَ اَنَا بَرِیۡٓءٌ  مِّمَّا تُجۡرِمُوۡنَ ﴿٪۳۵﴾', 'کیا یہ لوگ کہتے ہیں کہ اس پیغمبر نے قرآن اپنے دل سے بنا لیا ہے کہدو کہ اگر میں نے دل سے بنا لیا ہے تو میرے گناہ کا وبال مجھ پر اور جو گناہ تم کرتے ہو اس سے میں بری الذمہ ہوں۔', 'کیا کہتے ہیں کہ بنا لایا قرآن کو [۴۸] کہہ دے اگر میں بنا لایا ہوں تو مجھ پر ہے میرا گناہ اور میرا ذمہ نہیں جو تم گناہ کرتے ہو [۴۹]', 'Or they (the pagans of Makkah) say: \"He (Muhammad SAW) has fabricated it (the Quran).\" Say: \"If I have fabricated it, upon me be my crimes, but I am innocent of (all) those crimes which you commit.\"', 'Do they (the pagans of Makkah) still say that he (Muhammad) has forged it? Say, “If I have forged it, then, I am responsible for my sin, and I am free of the sins you commit.”'),
(1509, 11, 36, 4, 4, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ اُوۡحِیَ  اِلٰی نُوۡحٍ اَنَّہٗ  لَنۡ یُّؤۡمِنَ مِنۡ قَوۡمِکَ اِلَّا مَنۡ قَدۡ اٰمَنَ فَلَا تَبۡتَئِسۡ بِمَا کَانُوۡا یَفۡعَلُوۡنَ ﴿ۚۖ۳۶﴾', 'اور نوح کی طرف وحی کی گئ کہ تمہاری قوم میں جو لوگ ایمان لاچکے لاچکے ان کے سوا اور کوئی ایمان نہیں لائے گا تو جو کام یہ کر رہے ہیں انکی وجہ سے غم نہ کھاؤ۔', 'اور حکم ہوا طرف نوح کی کہ اب ایمان نہ لائے گا تیری قوم میں مگر جو ایمان لاچکا سو غمگین نہ رہ ان کاموں پر جو کر رہے ہیں [۵۰]', 'And it was inspired to Nooh (Noah): \"None of your people will believe except those who have believed already. So be not sad because of what they used to do.', 'And it was revealed to NūH: None of your people would come to believe any more, except those who have already believed. So, be not distressed by what they have been doing.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1510, 11, 37, 4, 4, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ اصۡنَعِ الۡفُلۡکَ بِاَعۡیُنِنَا وَ وَحۡیِنَا وَ لَا تُخَاطِبۡنِیۡ فِی الَّذِیۡنَ ظَلَمُوۡا ۚ اِنَّہُمۡ مُّغۡرَقُوۡنَ ﴿۳۷﴾', 'اور ایک کشتی ہمارے حکم سے ہمارے سامنے بناؤ۔ اور جو لوگ ظالم ہیں انکے بارے میں مجھ سے کچھ نہ کہنا کیونکہ وہ ضرور غرق کر دیئے جائیں گے۔', 'اور بنا کشتی روبرو ہمارے اور ہمارے حکم سے اور نہ بات کر مجھ سے ظالموں کے حق میں یہ بیشک غرق ہوں گے [۵۱]', '\"And construct the ship under Our Eyes and with Our Inspiration, and address Me not on behalf of those who did wrong; they are surely to be drowned.\"', 'And make an ark under Our eyes and according to Our revelation; and do not speak to Me about those who have crossed the limits, as they are destined to be drowned.”'),
(1511, 11, 38, 4, 4, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ یَصۡنَعُ الۡفُلۡکَ ۟ وَ کُلَّمَا مَرَّ عَلَیۡہِ مَلَاٌ مِّنۡ قَوۡمِہٖ  سَخِرُوۡا مِنۡہُ ؕ قَالَ  اِنۡ تَسۡخَرُوۡا مِنَّا فَاِنَّا نَسۡخَرُ  مِنۡکُمۡ کَمَا  تَسۡخَرُوۡنَ ﴿ؕ۳۸﴾', 'اور نوح نے کشتی بنانی شروع کر دی اور جب انکی قوم کے سردار انکے پاس سے گذرتے تو ان سے تمسخر کرتے۔ وہ کہتے کہ اگر تم ہم سے تمسخر کرتے ہو تو جس طرح تم ہم سے تمسخر کرتے ہو اسی طرح ایک وقت ہم بھی تم سے تمسخر کریں گے۔', 'اور وہ کشتی بناتا تھا [۵۲] اور جب گذرتے اس پر سردار اس کی قوم کے ہنسی کرتے اس سے [۵۳] بولا اگر تم ہنستے ہو ہم سے تو ہم ہنستے ہیں تم سے جیسے تم ہنستے ہو [۵۴]', 'And as he was constructing the ship, whenever the chiefs of his people passed by him, they made a mockery of him. He said: \"If you mock at us, so do we mock at you likewise for your mocking.', 'He started making the Ark. Whenever the leaders of his people passed by him, they mocked at him. He said, “If you mock at us, we mock at you like you mock at us:'),
(1512, 11, 39, 4, 4, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'فَسَوۡفَ تَعۡلَمُوۡنَ ۙ مَنۡ یَّاۡتِیۡہِ عَذَابٌ یُّخۡزِیۡہِ  وَ یَحِلُّ  عَلَیۡہِ  عَذَابٌ  مُّقِیۡمٌ ﴿۳۹﴾', 'اور تم کو جلد معلوم ہو جائے گا کہ کس پر عذاب آتا ہے جو اسے رسوا کرے گا اور کس پر ہمیشہ کا عذاب نازل ہوتا ہے؟', 'اب جلد جان لو گے کہ کس پر آتا ہے عذاب کہ رسوا کرے اسکو اور اترتا ہے اس پر عذاب دائمی [۵۵]', '\"And you will know who it is on whom will come a torment that will cover him with disgrace and on whom will fall a lasting torment.\"', 'So, you shall soon know who will be visited by a scourge that will humiliate him, and upon whom a lasting punishment will settle forever.”'),
(1513, 11, 40, 4, 4, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'حَتّٰۤی اِذَا جَآءَ اَمۡرُنَا وَ فَارَ التَّنُّوۡرُ ۙ قُلۡنَا احۡمِلۡ فِیۡہَا مِنۡ کُلٍّ زَوۡجَیۡنِ اثۡنَیۡنِ وَ اَہۡلَکَ اِلَّا مَنۡ سَبَقَ عَلَیۡہِ الۡقَوۡلُ وَ مَنۡ اٰمَنَ ؕ وَ مَاۤ  اٰمَنَ  مَعَہٗۤ   اِلَّا قَلِیۡلٌ ﴿۴۰﴾', 'یہاں تک کہ جب ہمارا حکم آ پہنچا اور تنور جوش مارنے لگا۔ تو ہم نے نوح کو حکم دیا کہ ہر قسم کے پالتو جانوروں میں سے جوڑا جوڑا یعنی ایک ایک نر اور ایک ایک مادہ لے لو اور جس شخص کی نسبت حکم ہو چکا ہے کہ ہلاک ہو جائے گا اسکو چھوڑ کر اپنے گھر والوں کو اور جو ایمان لایا ہو اسکو کشتی میں سوار کر لو اور انکے ساتھ ایمان بہت ہی کم لوگ لائے تھے۔', 'یہاں تک کہ جب پہنچا حکم ہمارا اور جوش مارا تنور نے [۵۶] کہا ہم نے چڑھا لے کشتی میں ہر قسم سے جوڑا دو عدد [۵۷] اور اپنے گھر کے لوگ مگر جس پر پہلے ہو چکا ہے حکم [۵۸] اور سب ایمان والوں کو اور ایمان نہ لائے تھے اس کے ساتھ مگر تھوڑے [۵۹]', '(So it was) till then there came Our Command and the oven gushed forth (water like fountains from the earth). We said: \"Embark therein, of each kind two (male and female), and your family, except him against whom the Word has already gone forth, and those who believe. And none believed with him, except a few.\"', 'At last, when Our command came and the oven overflowed, We said, “Take into the Ark a pair of two from every species, along with your family,-except those against whom the Word has already been pronounced-and (also take into it) those who have believed.” And there were only a few who had believed with him.'),
(1514, 11, 41, 4, 4, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ قَالَ ارۡکَبُوۡا فِیۡہَا بِسۡمِ اللّٰہِ مَ‍‍جۡؔرٖىہَا وَ مُرۡسٰىہَا ؕ اِنَّ رَبِّیۡ لَغَفُوۡرٌ رَّحِیۡمٌ  ﴿۴۱﴾', 'نوح نے کہا کہ اللہ کا نام لے کر کہ اسی کے کرم سے اس کا چلنا اور ٹھہرنا ہے اس میں سوار ہو جاؤ بیشک میرا پروردگار بخشنے والا ہے مہربان ہے۔', 'اور بولا سوار ہو جاؤ اس میں اللہ کے نام سے ہے اس کا چلنا اور ٹھہرنا تحقیق میرا رب ہے بخشنے والا مہربان [۶۰]', 'And he (Nooh (Noah) ) said: \"Embark therein, in the Name of Allah will be its moving course and its resting anchorage. Surely, my Lord is Oft-Forgiving, Most Merciful.\" (Tafsir At-Tabaree, Vol. 12, Page 43)', 'He (NūH) said, “Embark it. With the name of Allah it sails and anchors. Surely, my Lord is Most-Forgiving, Very-Merciful.'),
(1515, 11, 42, 4, 4, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ ہِیَ تَجۡرِیۡ بِہِمۡ فِیۡ مَوۡجٍ کَالۡجِبَالِ ۟  وَ نَادٰی نُوۡحُۨ  ابۡنَہٗ وَ کَانَ فِیۡ  مَعۡزِلٍ یّٰـبُنَیَّ ارۡکَبۡ مَّعَنَا وَ لَا تَکُنۡ مَّعَ الۡکٰفِرِیۡنَ ﴿۴۲﴾', 'اور وہ انکو لے کر طوفان کی لہروں میں چلنے لگی لہریں کیا تھیں گویا پہاڑ تھے اس وقت نوح نے اپنے بیٹے کو جو کشتی سے الگ تھا پکارا کہ بیٹا ہمارے ساتھ سوار ہو جا اور کافروں میں شامل نہ ہو۔', 'اور وہ لئے جارہی تھی انکو لہروں میں جیسے پہاڑ اور پکارا نوح نے اپنے بیٹے کو اور وہ ہو رہا تھا کنارے اے بیٹے سوار ہو جا ساتھ ہمارے اور مت رہ ساتھ کافروں کے [۶۱]', 'So it (the ship) sailed with them amidst the waves like mountains, and Nooh (Noah) called out to his son, who had separated himself (apart), \"O my son! Embark with us and be not with the disbelievers.\"', 'And it was sailing with them amidst the waves like mountains. And NūH called out to his son, who was at an isolated place, “O my child, come on board with us, and do not be in the company of the disbelievers.”'),
(1516, 11, 43, 4, 4, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالَ سَاٰوِیۡۤ  اِلٰی جَبَلٍ یَّعۡصِمُنِیۡ  مِنَ الۡمَآءِ ؕ قَالَ لَا عَاصِمَ  الۡیَوۡمَ  مِنۡ  اَمۡرِ اللّٰہِ  اِلَّا مَنۡ رَّحِمَ ۚ وَ حَالَ بَیۡنَہُمَا الۡمَوۡجُ  فَکَانَ  مِنَ  الۡمُغۡرَقِیۡنَ  ﴿۴۳﴾', 'اس نے کہا کہ میں ابھی پہاڑ سے جا لگوں گا وہ مجھے پانی سے بچا لے گا۔ فرمایا کہ آج اللہ کے عذاب سے کوئی بچانے والا نہیں اور نہ کوئی بچ سکتا ہے مگر وہی جس پر اللہ رحم کرے۔ اتنے میں دونوں کے درمیان لہر حائل ہو گئ اور وہ ڈوب کر رہ گیا۔', 'بولا جا لگوں گا کسی پہاڑ کو جو بچا لے گا مجھ کو پانی سے [۶۲] کہا کوئی بچانے والا نہیں آ ج اللہ کے حکم سے مگر جس پر وہی رحم کرے اور حائل ہو گئ دونوں میں موج پھر ہو گیا ڈوبنے والوں میں [۶۳]', 'The son replied: \"I will betake myself to a mountain, it will save me from the water.\" Nooh (Noah) said: \"This day there is no saviour from the Decree of Allah except him on whom He has mercy.\" And a wave came in between them, so he (the son) was among the drowned.', 'He said, “I shall take shelter on a mountain which will save me from the water.” He said, “There is no saver today from the command of Allah, except the one to whom He shows mercy.” And the waves rose high between the two, and he was among those who were drowned.'),
(1517, 11, 44, 4, 4, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ قِیۡلَ یٰۤاَرۡضُ ابۡلَعِیۡ مَآءَکِ وَ یٰسَمَآءُ اَقۡلِعِیۡ وَ غِیۡضَ الۡمَآءُ وَ قُضِیَ الۡاَمۡرُ وَ اسۡتَوَتۡ عَلَی الۡجُوۡدِیِّ  وَ قِیۡلَ بُعۡدًا لِّلۡقَوۡمِ  الظّٰلِمِیۡنَ ﴿۴۴﴾', 'اور حکم دیا گیا کہ اے زمین اپنا پانی نگل جا اور اے آسمان تھم جا۔ اور پانی خشک ہو گیا اور کام تمام کر دیا گیا اور کشتی کوہ جودی پر جا ٹھہری۔ اور کہہ دیا گیا کہ بےانصاف لوگوں پر لعنت۔', 'اور حکم آیا اے زمین نگل جا اپنا پانی اور اے آسمان تھم جا اور سکھا دیا گیا پانی اور ہو چکا کام اور کشتی ٹھہری جودی پہاڑ پر اور حکم ہوا کہ دور ہو قوم  ظالم [۶۴]', 'And it was said: \"O earth! Swallow up your water, and O sky! Withhold (your rain).\" And the water was diminished (made to subside) and the Decree (of Allah) was fulfilled (i.e. the destruction of the people of Nooh (Noah). And it (the ship) rested on Mount Judi, and it was said: \"Away with the people who are Zalimoon (polytheists and wrong-doing)!\"', 'It was said (by Allah), “O earth, suck in your water, and O heaven, stop.” And water subsided, and the matter was over. It (the Ark) came to rest on the Jūdī, and it was said, “Away with the wrongdoers.”'),
(1518, 11, 45, 4, 4, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ نَادٰی نُوۡحٌ رَّبَّہٗ  فَقَالَ رَبِّ اِنَّ ابۡنِیۡ مِنۡ اَہۡلِیۡ وَ اِنَّ وَعۡدَکَ الۡحَقُّ وَ اَنۡتَ اَحۡکَمُ  الۡحٰکِمِیۡنَ ﴿۴۵﴾', 'اور نوح نے اپنے پروردگار کو پکارا اور کہا کہ پروردگار میرا بیٹا بھی میرے گھر والوں میں ہے تو اس کو بھی نجات دے تیرا وعدہ سچا ہے اور تو بہترین حاکم ہے۔', 'اور پکارا نوح نے اپنے رب کو کہا اے رب میرا بیٹا ہے میرے گھر والوں میں اور بیشک تیرا وعدہ سچا ہے اور تو سب سے بڑا حاکم ہے', 'And Nooh (Noah) called upon his Lord and said, \"O my Lord! Verily, my son is of my family! And certainly, Your Promise is true, and You are the Most Just of the judges.\"', 'NūH called unto his Lord and said, “My Lord, my son is a part of my family, and surely Your promise is true, and You are the greatest of all judges.”'),
(1519, 11, 46, 4, 4, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالَ یٰنُوۡحُ  اِنَّہٗ  لَیۡسَ مِنۡ اَہۡلِکَ ۚ اِنَّہٗ عَمَلٌ غَیۡرُ صَالِحٍ ٭۫ۖ  فَلَا تَسۡـَٔلۡنِ مَا لَـیۡسَ لَکَ بِہٖ عِلۡمٌ ؕ اِنِّیۡۤ  اَعِظُکَ اَنۡ تَکُوۡنَ  مِنَ  الۡجٰہِلِیۡنَ ﴿۴۶﴾', 'اللہ نے فرمایا کہ اے نوح وہ تیرے گھر والوں میں نہیں ہے۔ وہ تو سراسر بدعمل ہے تو جس چیز کی تم کو حقیقت معلوم نہیں اسکے بارے میں مجھ سے درخواست ہی نہ کرو۔ اور میں تم کو نصیحت کرتا ہوں کہ نادان نہ بنو۔', 'فرمایا اے نوح وہ نہیں تیرے گھر  والوں میں اس کے کام ہیں خراب سو مت پوچھ مجھ سے جو تجھ کو معلوم نہیں میں نصیحت کرتا ہو ں تجھ کو کہ نہ ہو جائے تو جاہلوں میں [۶۵]', 'He said: \"O Nooh (Noah)! Surely, he is not of your family; verily, his work is unrighteous, so ask not of Me that of which you have no knowledge! I admonish you, lest you be one of the ignorants.\"', 'He said, “O NūH, in fact, he is not a part of your family. Indeed, he is (a man of) bad deeds. So do not ask Me something of which you have no knowledge. I exhort you not to be among the ignorant.”'),
(1520, 11, 47, 4, 4, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالَ رَبِّ اِنِّیۡۤ  اَعُوۡذُ بِکَ اَنۡ اَسۡـَٔلَکَ مَا لَـیۡسَ لِیۡ بِہٖ عِلۡمٌ ؕ وَ اِلَّا تَغۡفِرۡ لِیۡ وَ تَرۡحَمۡنِیۡۤ   اَکُنۡ  مِّنَ  الۡخٰسِرِیۡنَ ﴿۴۷﴾', 'نوح نے کہا پروردگار میں تجھ سے پناہ مانگتا ہوں کہ ایسی چیز کا تجھ سے سوال کروں جس کی حقیقت مجھے معلوم نہیں۔ اور اگر تو مجھے نہیں بخشے گا اور مجھ پر رحم نہیں فرمائے گا تو میں تباہ ہو جاؤں گا۔', 'بولا اے رب میں پناہ لیتا ہوں تیری اس سے کہ پوچھوں تجھ سےجو معلوم نہ ہو مجھ کو [۶۶[ اور اگر تو نہ بخشے مجھ کو اور رحم نہ کرے تو میں ہوں نقصان والوں میں [۶۷]', 'Nooh (Noah) said: \"O my Lord! I seek refuge with You from asking You that of which I have no knowledge. And unless You forgive me and have Mercy on me, I would indeed be one of the losers.\"', 'He said, “My Lord, I seek refuge with You that I should ask You something of which I have no knowledge. If You do not forgive me and do not show mercy to me, I shall be among the losers.”'),
(1521, 11, 48, 4, 4, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قِیۡلَ یٰنُوۡحُ اہۡبِطۡ بِسَلٰمٍ مِّنَّا وَ بَرَکٰتٍ عَلَیۡکَ وَ عَلٰۤی اُمَمٍ  مِّمَّنۡ مَّعَکَ ؕ وَ اُمَمٌ سَنُمَتِّعُہُمۡ ثُمَّ یَمَسُّہُمۡ مِّنَّا عَذَابٌ  اَلِیۡمٌ ﴿۴۸﴾', 'حکم ہوا کہ نوح ہماری طرف سے سلامتی اور برکتوں کے ساتھ جو تم پر اور تمہارے ساتھ کی جماعتوں پر نازل کی گئ ہیں اتر آؤ۔ اور کچھ اور جماعتیں ہوں گی جنکو ہم دنیا کے فوائد سے بہرہ مند کریں گے پھر انکو ہماری طرف سے عذاب الیم پہنچے گا۔', 'حکم ہوا اے نوح اتر سلامتی کے ساتھ ہماری طرف سے اور برکتوں کےساتھ تجھ پر اور ان فرقوں پر جو تیرے ساتھ ہیں اور دوسرے فرقے ہیں کہ ہم فائدہ دیں گے انکو پھر پہنچے گا ان کو ہماری طرف سے عذاب دردناک [۶۸]', 'It was said: \"O Nooh (Noah)! Come down (from the ship) with peace from Us and blessings on you and on the people who are with you (and on some of their off spring), but (there will be other) people to whom We shall grant their pleasures (for a time), but in the end a painful torment will reach them from Us.\"', 'It was said, “O NūH, disembark in peace from Us and with blessings upon you and upon the peoples (springing) from those with you. And there are peoples whom We shall give some enjoyment, then a painful punishment from Us will visit them.”'),
(1522, 11, 49, 4, 4, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'تِلۡکَ مِنۡ اَنۡۢبَآءِ الۡغَیۡبِ نُوۡحِیۡہَاۤ  اِلَیۡکَ ۚ مَا کُنۡتَ تَعۡلَمُہَاۤ  اَنۡتَ وَ لَا قَوۡمُکَ مِنۡ قَبۡلِ ہٰذَا ؕۛ فَاصۡبِرۡ ؕۛ اِنَّ الۡعَاقِبَۃَ  لِلۡمُتَّقِیۡنَ  ﴿٪۴۹﴾', 'یہ حالات غیب کی خبروں میں سے ہیں جو ہم تمہاری طرف بھیجتے ہیں۔ اور اس سے پہلے نہ تم ہی انکو جانتے تھے اور نہ تمہاری قوم ہی ان سے واقف تھی تو صبر کرو کہ انجام پرہیزگاروں ہی کا بھلا ہے۔', 'یہ باتیں منجملہ غیب کی خبروں کی ہیں کہ ہم بھیجتے ہیں تیری طرف نہ تجھ کو ان کی خبر تھی اور نہ تیری قوم کو اس سے پہلے [۶۹] سو تو صبر کر البتہ انجام بھلا ہے ڈرنے والوں کا [۷۰]', 'This is of the news of the unseen which We reveal unto you (O Muhammad SAW), neither you nor your people knew them before this. So be patient. Surely, the (good) end is for the Muttaqoon (pious - see V.2:2)', 'These are some reports from the unseen (events), which We reveal to you. You did not know them before this, neither you nor your people. So, be patient. Surely, the end is in favor of the God-fearing.'),
(1523, 11, 50, 5, 5, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ اِلٰی عَادٍ  اَخَاہُمۡ ہُوۡدًا ؕ قَالَ یٰقَوۡمِ اعۡبُدُوا اللّٰہَ  مَا  لَکُمۡ مِّنۡ  اِلٰہٍ  غَیۡرُہٗ ؕ اِنۡ  اَنۡتُمۡ   اِلَّا  مُفۡتَرُوۡنَ ﴿۵۰﴾', 'اور ہم نے قوم عاد کی طرف انکے بھائی ہود کو بھیجا انہوں نے کہا اے میری قوم! اللہ ہی کی عبادت کرو اسکے سوا تمہارا کوئی معبود نہیں۔ تم شرک کر کے اللہ پر محض بہتان باندھتے ہو۔', 'اور عاد کی طرف ہم نے بھیجا انکے بھائی ہود کو بولا اے قوم بندگی کرو اللہ کی کوئی تمہارا حاکم نہیں سوائے اس کے تم سب جھوٹ کہتے ہو [۷۱]', 'And to Ad (people We sent) their brother Hood. He said, \"O my people! Worship Allah! You have no other Ilah (God) but Him. Certainly, you do nothing but invent (lies)!', 'And to ‘Ād, (We sent) their brother Hūd. He said, “O my people, worship Allah. You have no god other than Him. You are nothing but fabricators.'),
(1524, 11, 51, 5, 5, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'یٰقَوۡمِ لَاۤ  اَسۡـَٔلُکُمۡ  عَلَیۡہِ  اَجۡرًا ؕ اِنۡ اَجۡرِیَ  اِلَّا عَلَی الَّذِیۡ فَطَرَنِیۡ ؕ اَفَلَا تَعۡقِلُوۡنَ ﴿۵۱﴾', 'میری قوم! میں اس وعظ و نصیحت کا تم سے کچھ صلہ نہیں مانگتا۔ میرا صلہ تو اسکے ذمے ہے جس نے مجھے پیدا کیا۔ بھلا تم سمجھتے کیوں نہیں؟', 'اےقوم میں تم سے نہیں مانگتا اس پر مزدوری میری مزدوری اسی پر ہے جس نے مجھ کو پیدا کیا [۷۲] پھر کیا تم نہیں سمجھتے [۷۳]', '\"O my people I ask of you no reward for it (the Message). My reward is only from Him, Who created me. Will you not then understand?', 'O my people, I ask you no reward for it. My reward is only on the One who created me. Do you, then, not understand?'),
(1525, 11, 52, 5, 5, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ یٰقَوۡمِ اسۡتَغۡفِرُوۡا رَبَّکُمۡ ثُمَّ تُوۡبُوۡۤا اِلَیۡہِ  یُرۡسِلِ السَّمَآءَ  عَلَیۡکُمۡ مِّدۡرَارًا وَّ  یَزِدۡکُمۡ   قُوَّۃً   اِلٰی قُوَّتِکُمۡ  وَ لَا  تَتَوَلَّوۡا  مُجۡرِمِیۡنَ ﴿۵۲﴾', 'اور اے قوم! اپنے پروردگار سے بخشش مانگو پھر اسکے آگے توبہ کرو وہ تم پر آسمان سے موسلا دھار بارش برسائے گا اور تمہاری طاقت پر طاقت بڑھائے گا۔ اور دیکھو گناہگار بن کر روگردانی نہ کرو۔', 'اور اے قوم گناہ بخشواؤ اپنے رب سے پھر رجوع کرو اسکی طرف [۷۴] چھوڑے گا تم پر آسمان سے دھاریں [۷۵] اور زیادہ دے گا تم کو زور پر زور اور روگردانی نہ کرو گنہگار ہو کر [۷۶]', '\"And O my people! Ask forgiveness of your Lord and then repent to Him, He will send you (from the sky) abundant rain, and add strength to your strength, so do not turn away as Mujrimoon (criminals, disbelievers in the Oneness of Allah).\"', 'O my people, seek forgiveness from your Lord, then turn to Him in repentance, and He will release the heavens pouring upon you, and will add strength to your strength, and do not turn away like sinners.”'),
(1526, 11, 53, 5, 5, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالُوۡا یٰہُوۡدُ مَا جِئۡتَنَا بِبَیِّنَۃٍ وَّ مَا نَحۡنُ بِتَارِکِیۡۤ  اٰلِہَتِنَا عَنۡ قَوۡلِکَ وَ مَا نَحۡنُ  لَکَ  بِمُؤۡمِنِیۡنَ ﴿۵۳﴾', 'وہ بولے ہود تم ہمارے پاس کوئی دلیل ظاہر نہیں لائے۔ اور ہم صرف تمہارے کہنے سے نہ اپنے معبودوں کو چھوڑنے والے ہیں اور نہ تم پر ایمان لانے والے ہیں۔', 'بولے اے ہود تو ہمارے پاس کوئی سند لے کر نہیں آیا اور ہم نہیں چھوڑنے والے اپنے ٹھاکروں (معبودوں) کو تیرے کہنے سے اور ہم نہیں تجھ کو ماننے والے [۷۷]', 'They said: \"O Hood! No evidence have you brought us, and we shall not leave our gods for your (mere) saying! And we are not believers in you.', 'They said, “O Hūd, you did not bring to us any proof, and we are not to leave our gods on your statement, and we are not to believe in you.'),
(1527, 11, 54, 5, 5, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'اِنۡ نَّقُوۡلُ  اِلَّا اعۡتَرٰىکَ بَعۡضُ اٰلِہَتِنَا بِسُوۡٓءٍ ؕ قَالَ  اِنِّیۡۤ  اُشۡہِدُ  اللّٰہَ  وَ اشۡہَدُوۡۤا اَنِّیۡ  بَرِیۡٓءٌ   مِّمَّا  تُشۡرِکُوۡنَ ﴿ۙ۵۴﴾', 'ہم تو یہ سمجھتے ہیں کہ ہمارے کسی معبود نے تمہیں تکلیف پہنچا کر دیوانہ کر دیا ہے۔ انہوں نے کہا کہ میں اللہ کو گواہ کرتا ہوں اور تم بھی گواہ رہو کہ جنکو تم اللہ کا شریک بناتے ہو۔ میں ان سے بیزار ہوں۔', 'ہم تو یہی کہتے ہیں کہ تجھ کو آسیب پہنچایا ہے کسی ہمارے ٹھاکروں (معبودوں) نے بری طرح [۷۸] بولا میں گواہ کرتا ہوں اللہ کو اور تم گواہ رہو کہ میں بیزار ہوں ان سے جن کو تم شریک کرتے ہو', '\"All that we say is that some of our gods (false deities) have seized you with evil (madness).\" He said: \"I call Allah to witness and bear you witness that I am free from that which you ascribe as partners in worship, -', 'We do not say except that some of our gods have subjected you to some evil.” He said, “I make Allah my witness, and you bear witness that I have nothing to do with what you take as gods'),
(1528, 11, 55, 5, 5, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'مِنۡ دُوۡنِہٖ فَکِیۡدُوۡنِیۡ جَمِیۡعًا ثُمَّ لَا تُنۡظِرُوۡنِ ﴿۵۵﴾', 'یعنی جنکی اللہ کے سوا عبادت کرتے ہو تو تم سب مل کر میرے بارے میں جو تدبیر کرنی چاہو کر لو اور مجھے مہلت نہ دو۔', 'اس کے سوا سو برائی کرو میرے حق میں تم سب مل کر پھر مجھ کو مہلت نہ دو', 'With Him (Allah). So plot against me, all of you, and give me no respite.', 'besides Him. So, try your plans against me, all of you together, then give me no respite.'),
(1529, 11, 56, 5, 5, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'اِنِّیۡ تَوَکَّلۡتُ عَلَی اللّٰہِ رَبِّیۡ وَ  رَبِّکُمۡ ؕ مَا مِنۡ دَآبَّۃٍ  اِلَّا ہُوَ اٰخِذٌۢ  بِنَاصِیَتِہَا ؕ اِنَّ رَبِّیۡ عَلٰی صِرَاطٍ مُّسۡتَقِیۡمٍ ﴿۵۶﴾', 'میں اللہ پر جو میرا اور تمہارا سب کا پروردگار ہے بھروسہ رکھتا ہوں زمین پر جو چلنے پھرنے والا ہے وہ اللہ کے قبضہ قدرت میں ہے بیشک میرا پروردگار سیدھے رستے پر ہے۔', 'میں نے بھروسہ کیا اللہ پر جو رب ہے میرا اور تمہارا کوئی نہیں زمین پر پاؤں دھرنے والا مگر اللہ کے ہاتھ میں ہے چوٹی اسکی بیشک میرا رب ہے سیدھی راہ پر [۷۹]', '\"I put my trust in Allah, my Lord and your Lord! There is not a moving (living) creature but He has grasp of its forelock. Verily, my Lord is on the Straight Path (the truth).', 'I place my trust in Allah who is my Lord and your Lord. There is no creature but He holds it by the forelock. Surely, my Lord is on a straight path.'),
(1530, 11, 57, 5, 5, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'فَاِنۡ تَوَلَّوۡا فَقَدۡ اَبۡلَغۡتُکُمۡ  مَّاۤ   اُرۡسِلۡتُ بِہٖۤ  اِلَیۡکُمۡ ؕ وَ یَسۡتَخۡلِفُ رَبِّیۡ قَوۡمًا غَیۡرَکُمۡ ۚ وَ لَا تَضُرُّوۡنَہٗ شَیۡئًا ؕ اِنَّ رَبِّیۡ عَلٰی  کُلِّ شَیۡءٍ  حَفِیۡظٌ ﴿۵۷﴾', 'اب اگر تم روگردانی کرو گے تو جو پیغام میرے ذریعے تمہاری طرف بھیجا گیا ہے وہ میں نے تمہیں پہنچا دیا ہے اور میرا پروردگار تمہاری جگہ اور لوگوں کو لا بسائے گا۔ اور تم اللہ کا کچھ بھی نہیں بگاڑ سکو گے۔ میرا پروردگار تو ہر چیز پر نگہبان ہے۔', 'پھر اگر تم منہ پھیرو گے تو میں پہنچا چکا تم کو جو میرے ہاتھ بھیجا تھا تمہاری طرف اور  قائم مقام کرے گا میرا رب کوئی اور لوگ اور نہ بگاڑ سکو گے اللہ کا کچھ تحقیق میرا رب ہے ہر چیز پر نگہبان [۸۰]', '\"So if you turn away, still I have conveyed the Message with which I was sent to you. My Lord will make another people succeed you, and you will not harm Him in the least. Surely, my Lord is Guardian over all things.\"', 'Now, if you turn away, I have already conveyed to you the message with which I was sent to you. My Lord will replace you with some other people, and you cannot do Him any harm. Surely, my Lord is guardian over every thing.”'),
(1531, 11, 58, 5, 5, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ لَمَّا جَآءَ  اَمۡرُنَا نَجَّیۡنَا ہُوۡدًا وَّ الَّذِیۡنَ اٰمَنُوۡا مَعَہٗ بِرَحۡمَۃٍ مِّنَّا ۚ وَ نَجَّیۡنٰہُمۡ مِّنۡ عَذَابٍ  غَلِیۡظٍ ﴿۵۸﴾', 'اور جب ہمارا حکم عذاب آ پہنچا تو ہم نے ہود کو اور جو لوگ انکے ساتھ ایمان لائے تھے انکو اپنی مہربانی سے بچا لیا۔ اور انہیں عذاب شدید سے نجات دی۔', 'اور جب پہنچا ہمارا حکم بچا دیا ہم نے ہود کو اور جو لوگ ایمان لائے تھے اس کےساتھ اپنی رحمت سے اور بچا دیا انکو ایک بھاری عذاب سے [۸۱]', 'And when Our Commandment came, We saved Hood and those who believed with him by a Mercy from Us, and We saved them from a severe torment.', 'So, when came Our command, We saved Hūd and those who believed along with him, out of mercy from Us, and We did save them from a heavy punishment.'),
(1532, 11, 59, 5, 5, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ تِلۡکَ عَادٌ ۟ۙ جَحَدُوۡا بِاٰیٰتِ رَبِّہِمۡ وَ عَصَوۡا رُسُلَہٗ وَ اتَّبَعُوۡۤا اَمۡرَ  کُلِّ جَبَّارٍ عَنِیۡدٍ ﴿۵۹﴾', 'یہ وہی قوم عاد ہے جس نے اللہ کی نشانیوں سے انکار کیا اور اسکے پیغمبروں کی نافرمانی کی اور ہر سرکش و متکبر کا کہا مانا۔', 'اور یہ تھے عاد کہ منکر ہوئے اپنے رب کی باتوں سے اور نہ مانا اسکے رسولوں کو اور مانا حکم انکا جو سرکش تھے مخالف [۸۲]', 'Such were Ad (people). They rejected the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of their Lord and disobeyed His Messengers, and followed the command of every proud obstinate (oppressor of the truth, from their leaders).', 'Such was the tribe of ‘Ād who rejected the signs of their Lord, disobeyed their Messengers and followed the dictates of every obstinate tyrant!'),
(1533, 11, 60, 5, 5, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ اُتۡبِعُوۡا فِیۡ ہٰذِہِ  الدُّنۡیَا لَعۡنَۃً  وَّ  یَوۡمَ الۡقِیٰمَۃِ ؕ اَلَاۤ   اِنَّ  عَادًا کَفَرُوۡا  رَبَّہُمۡ ؕ اَلَا  بُعۡدًا  لِّعَادٍ  قَوۡمِ  ہُوۡدٍ ﴿٪۶۰﴾', 'اور اس دنیا میں بھی لعنت ان کے پیچھے لگی رہی اور قیامت کے دن بھی لگی رہے گی دیکھو قوم عاد نے اپنے پروردگار سے کفر کیا اور سن رکھو قوم عاد پر پھٹکار ہے جو ہود کی قوم تھی۔', 'اور پیچھے سے آئی انکو اس دنیا میں پھٹکار اور قیامت کے دن بھی [۸۳] سن لو عاد منکر ہوئے اپنے رب سے سن لو پھٹکار ہے عاد کو جو قوم تھی ہود کی [۸۴]', 'And they were pursued by a curse in this world and (so they will be) on the Day of Resurrection. No doubt! Verily, Ad disbelieved in their Lord. So away with Ad, the people of Hood.', 'A curse was made to pursue them in this world and on the Day of Judgment. Lo! The people of ‘Ād disbelieved their Lord. Lo! Ruined were ‘Ād, the people of Hūd.'),
(1534, 11, 61, 6, 6, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ اِلٰی ثَمُوۡدَ  اَخَاہُمۡ صٰلِحًا ۘ قَالَ یٰقَوۡمِ اعۡبُدُوا اللّٰہَ مَا لَکُمۡ مِّنۡ  اِلٰہٍ غَیۡرُہٗ ؕ ہُوَ اَنۡشَاَکُمۡ مِّنَ الۡاَرۡضِ وَ اسۡتَعۡمَرَکُمۡ فِیۡہَا فَاسۡتَغۡفِرُوۡہُ  ثُمَّ تُوۡبُوۡۤا  اِلَیۡہِ ؕ اِنَّ  رَبِّیۡ  قَرِیۡبٌ مُّجِیۡبٌ  ﴿۶۱﴾', 'اور قوم ثمود کی طرف ان کے بھائی صالح کو بھیجا تو انہوں نے کہا اے قوم! اللہ ہی کی عبادت کرو۔ اسکے سوا تمہارا کوئی معبود نہیں۔ اسی نے تم کو زمین سے پیدا کیا۔ اور اس میں آباد کیا۔ تو اس سے مغفرت مانگو۔ اور اسکے آگے توبہ کرو۔ بیشک میرا پروردگار نزدیک بھی ہے اور دعا کا قبول کرنے والا بھی ہے۔', 'اور ثمود کی طرف بھیجا ان کا بھائی صالح [۸۵] بولا اے قوم بندگی کرو اللہ کی کوئی حاکم نہیں تمہارا اس کے سوا اسی نے بنایا تم کو زمین سے [۸۶] اور بسایا تم کو اس میں سو گناہ بخشواؤ اس سے اور رجوع کرو اسکی طرف تحقیق میرا رب نزدیک ہے قبول کرنے والا [۸۷]', 'And to Thamood (people, We sent) their brother Salih (Saleh). He said: \"O my people! Worship Allah, you have no other Ilah (God) but Him. He brought you forth from the earth and settled you therein, then ask forgiveness of Him and turn to Him in repentance. Certainly, my Lord is Near (to all by His Knowledge), Responsive.\"', 'And to (the people of) Thamūd (We sent) their brother, SāliH. He said, “O my people, worship Allah. You have no god other than Him. He has created you from earth and made you settle therein. So, seek His forgiveness, then turn to Him in repentance. Surely, my Lord is near, responsive to the prayers.”'),
(1535, 11, 62, 6, 6, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالُوۡا یٰصٰلِحُ  قَدۡ کُنۡتَ فِیۡنَا مَرۡجُوًّا قَبۡلَ  ہٰذَاۤ   اَتَنۡہٰنَاۤ   اَنۡ  نَّعۡبُدَ مَا یَعۡبُدُ اٰبَآؤُنَا وَ اِنَّنَا لَفِیۡ شَکٍّ مِّمَّا تَدۡعُوۡنَاۤ  اِلَیۡہِ  مُرِیۡبٍ ﴿۶۲﴾', 'انہوں نے کہا کہ صالح اس سے پہلے ہم تم سے کئ طرح کی امیدیں رکھتے تھے اب وہ منقطع ہو گئیں کیا تم ہم کو ان چیزوں سے منع کرتے ہو جنکو ہمارے بزرگ پوجتے آئے ہیں۔ اور جس بات کی طرف تم ہمیں بلاتے ہو اسکی طرف سے ہم بڑے بھاری شک میں ہیں۔', 'بولے اے صالح تجھ سے تو ہم کو امید تھی اس سے پہلے کیا تو ہم کو منع کرتا ہے کہ پرستش کریں جنکی پرستش کرتے رہے ہمارے باپ دادے اور ہم کو تو شبہ ہے اس میں جس کی طرف تو بلاتا ہے ایسا کہ دل نہیں مانتا [۸۸]', 'They said: \"O Salih (Saleh)! You have been among us as a figure of good hope (and we wished for you to be our chief), till this (new thing which you have brought; that we leave our gods and worship your God (Allah) Alone)! Do you (now) forbid us the worship of what our fathers have worshipped? But we are really in grave doubt as to that which you invite us to (monotheism).\"', 'They said, “O SāliH, we had hopes in you before this. Do you ask us not to worship what our fathers used to worship? We have serious doubts that have disturbed us about the faith to which you are calling us.”'),
(1536, 11, 63, 6, 6, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالَ یٰقَوۡمِ اَرَءَیۡتُمۡ  اِنۡ کُنۡتُ عَلٰی بَیِّنَۃٍ مِّنۡ رَّبِّیۡ وَ اٰتٰىنِیۡ مِنۡہُ رَحۡمَۃً  فَمَنۡ یَّنۡصُرُنِیۡ مِنَ اللّٰہِ  اِنۡ عَصَیۡتُہٗ ۟ فَمَا  تَزِیۡدُوۡنَنِیۡ  غَیۡرَ  تَخۡسِیۡرٍ ﴿۶۳﴾', 'صالح نے کہا اے میری قوم! بھلا دیکھو تو اگر میں اپنے پروردگار کی طرف سے کھلی دلیل پر ہوں اور اس نے مجھے اپنے ہاں سے نبوت کی نعمت بخشی ہو تو اگر میں اللہ کی نافرمانی کروں تو اسکے سامنے میری کون مدد کرے گا؟ تم تو کفر کی باتوں سے میرا نقصان ہی کرتے ہو۔', 'بولا اے قوم بھلا دیکھو تو اگر مجھ کو سمجھ مل گئ اپنے رب کی طرف سے اور اس نے مجھ کو دی رحمت اپنی طرف سے پھر کون بچائے مجھ کو اس سے اگر اسکی نافرمانی کروں [۸۹] سو تم کچھ نہیں بڑھاتے میرا سوائے نقصان کے [۹۰]', 'He said: \"O my people! Tell me, if I have a clear proof from my Lord, and there has come to me a Mercy (Prophethood, etc.) from Him, who then can help me against Allah, if I were to disobey Him? Then you increase me not but in loss.', 'He said, “O my people, tell me: If I have a clear proof from my Lord, and He has bestowed mercy upon me from Himself, who will come to my help against Allah, if I still disobey Him? So, you extend nothing to me but loss.'),
(1537, 11, 64, 6, 6, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ یٰقَوۡمِ ہٰذِہٖ نَاقَۃُ اللّٰہِ لَکُمۡ اٰیَۃً فَذَرُوۡہَا تَاۡکُلۡ فِیۡۤ  اَرۡضِ اللّٰہِ  وَ لَا تَمَسُّوۡہَا بِسُوۡٓءٍ فَیَاۡخُذَکُمۡ عَذَابٌ قَرِیۡبٌ ﴿۶۴﴾', 'اور یہ بھی کہا کہ اے قوم! یہ اللہ کی اونٹنی تمہارے لئے ایک نشانی یعنی معجزہ ہے۔ تو اسکو چھوڑ دو کہ اللہ کی زمین میں جہاں چاہے چرتی پھرے اور اسکو کسی طرح کی تکلیف نہ دینا ورنہ تمہیں جلد عذاب آ پکڑے گا۔', 'اور اے قوم یہ اونٹنی ہے اللہ کی تمہارے لئے نشانی سو چھوڑ دو اسکو کھاتی پھرے اللہ کی زمین میں اور مت ہاتھ لگاؤ اس کو بری طرح پھر تو آ پکڑے گا تم کو عذاب بہت جلد', '\"And O my people! This she-camel of Allah is a sign to you, leave her to feed on Allahs earth, and touch her not with evil, lest a near torment will seize you.\"', 'And O my people, this is the she-camel of Allah, a sign for you. So, leave her free to eat on the earth of Allah, and do not even touch her with evil (intention), lest an approaching punishment should seize you.”'),
(1538, 11, 65, 6, 6, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'فَعَقَرُوۡہَا فَقَالَ تَمَتَّعُوۡا فِیۡ  دَارِکُمۡ ثَلٰثَۃَ  اَیَّامٍ ؕ ذٰلِکَ وَعۡدٌ غَیۡرُ مَکۡذُوۡبٍ ﴿۶۵﴾', 'مگر انہوں نے اسکو کاٹ ڈالا۔ تو صالح نے کہا کہ اپنے گھروں میں تین دن اور فائدے اٹھا لو۔ یہ وعدہ ہے کہ جھوٹا نہ ہوگا۔', 'پھر اسکے پاؤں کاٹے تب کہا فائدہ اٹھالو اپنے گھروں میں تین دن یہ وعدہ ہے جو جھوٹا نہ ہو گا [۹۱]', 'But they killed her. So he said: \"Enjoy yourselves in your homes for three days. This is a promise (i.e. a threat) that will not be belied.\"', 'Then they slaughtered her. So, he said, “Enjoy yourselves in your homes for three days (only). That is a promise, not to be backed out.”'),
(1539, 11, 66, 6, 6, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'فَلَمَّا جَآءَ اَمۡرُنَا نَجَّیۡنَا صٰلِحًا وَّ الَّذِیۡنَ اٰمَنُوۡا مَعَہٗ بِرَحۡمَۃٍ  مِّنَّا وَ مِنۡ خِزۡیِ یَوۡمِئِذٍ ؕ اِنَّ رَبَّکَ ہُوَ الۡقَوِیُّ  الۡعَزِیۡزُ ﴿۶۶﴾', 'پس جب ہمارا حکم آ گیا تو ہم نے صالح کو اور جو لوگ انکے ساتھ ایمان لائے تھے انکو اپنی مہربانی سے بچا لیا اور اس دن کی رسوائی سے محفوظ رکھا بیشک تمہارا پروردگار طاقتور ہے زبردست ہے۔', 'پھر جب پہنچا حکم ہمارا بچا دیا ہم نے صالح کو اور جو ایمان لائے اسکے ساتھ اپنی رحمت سے اور اس دن کی رسوائی سے [۹۲] بیشک تیرا رب وہی ہے زور والا زبردست [۹۳]', 'So when Our Commandment came, We saved Salih (Saleh) and those who believed with him by a Mercy from Us, and from the disgrace of that Day. Verily, your Lord, He is the All-Strong, the All-Mighty.', 'So, when came Our command, We saved SāliH and those who believed along with Him, out of mercy from Us, and (We saved them) from the disgrace of that day. Surely, your Lord is the Powerful, the All Mighty.'),
(1540, 11, 67, 6, 6, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ اَخَذَ الَّذِیۡنَ ظَلَمُوا الصَّیۡحَۃُ فَاَصۡبَحُوۡا فِیۡ  دِیَارِہِمۡ  جٰثِمِیۡنَ ﴿ۙ۶۷﴾', 'اور جن لوگوں نے ظلم کیا تھا انکو چنگھاڑ کی صورت میں عذاب نے آ پکڑا تو وہ اپنے گھروں میں اوندھے پڑے رہ گئے۔', 'اور پکڑ لیا ان ظالموں کو  ہولناک آواز نے  پھر صبح کو رہ گئے اپنے گھروں میں اوندھے پڑے ہوئے', 'And As-Saeehah (torment - awful cry, etc.) overtook the wrong-doers, so they lay (dead), prostrate in their homes, -', 'And those who transgressed were caught by the Cry, and they were found dead in their homes, fallen on their knees,'),
(1541, 11, 68, 6, 6, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'کَاَنۡ لَّمۡ  یَغۡنَوۡا فِیۡہَا ؕ اَلَاۤ  اِنَّ  ثَمُوۡدَا۠ کَفَرُوۡا  رَبَّہُمۡ ؕ اَلَا  بُعۡدًا  لِّثَمُوۡدَ  ﴿٪۶۸﴾', 'گویا کبھی ان میں بسے ہی نہ تھے۔ سن رکھو قوم ثمود نے اپنے پروردگار سے کفر کیا۔ اور سن رکھو قوم ثمود پر پھٹکار ہے۔', 'جیسے کبھی رہے ہی نہ تھے وہاں [۹۴] سن لو ثمود منکر ہوئے اپنے رب سےسن لو پھٹکار ہے ثمود کو [۹۵]', 'As if they had never lived there. No doubt! Verily, Thamood disbelieved in their Lord. So away with Thamood!', 'as though they had never lived there. Lo! The people of Thamūd disbelieved their Lord. Lo! Ruined were the people of Thamūd.'),
(1542, 11, 69, 7, 7, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ لَقَدۡ جَآءَتۡ رُسُلُنَاۤ  اِبۡرٰہِیۡمَ بِالۡبُشۡرٰی قَالُوۡا سَلٰمًا ؕ قَالَ  سَلٰمٌ  فَمَا لَبِثَ اَنۡ  جَآءَ  بِعِجۡلٍ حَنِیۡذٍ ﴿۶۹﴾', 'اور ہمارے فرشتے ابراہیم کے پاس بشارت لے کر آئے تو سلام کہا انہوں نے بھی جواب میں سلام کہا۔ ابھی کچھ وقفہ نہیں ہوا تھا کہ ابراہیم ایک بھنا ہوا بچھڑا لے آئے۔', 'اور البتہ آ چکے ہیں ہمارے بھیجے ہوئے ابراہیم کے پاس خوشخبری لے کر بولے سلام وہ بولا سلام ہے پھر دیر نہ کی کہ لے آیا ایک بچھڑا تلا ہوا [۹۶]', 'And verily, there came Our Messengers to Ibraheem (Abraham) with glad tidings.They said: Salam (greetings or peace!) He answered, Salam (greetings or peace!) and he hastened to entertain them with a roasted calf.', 'And Our emissaries came to Ibrāhīm with the good news. They greeted him with “Salām (peace).” He said, “Salām.” Then he took not much time in bringing a roasted calf.'),
(1543, 11, 70, 7, 7, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'فَلَمَّا رَاٰۤ  اَیۡدِیَہُمۡ لَا تَصِلُ  اِلَیۡہِ  نَکِرَہُمۡ وَ اَوۡجَسَ مِنۡہُمۡ خِیۡفَۃً ؕ قَالُوۡا لَا تَخَفۡ  اِنَّاۤ   اُرۡسِلۡنَاۤ  اِلٰی  قَوۡمِ  لُوۡطٍ ﴿ؕ۷۰﴾', 'پھر جب دیکھا کہ انکے ہاتھ کھانے کی طرف نہیں بڑھتے۔ یعنی وہ کھانا نہیں کھاتے تو انکو اجنبی سمجھ کر دل میں خوف کیا۔ فرشتوں نے کہا کہ خوف نہ کیجئے ہم قوم لوط کی طرف انکے ہلاک کرنے کو بھیجے گئے ہیں۔', 'پھر جب دیکھا ان کے ہاتھ نہیں آتے کھانے پر تو کھٹکا اور دل میں ان سے ڈرا [۹۷] وہ بولے مت ڈر ہم بھیجے ہوئے آئے ہیں طرف قوم لوط کی [۹۸]', 'But when he saw their hands went not towards it (the meal), he felt some mistrust of them, and conceived a fear of them. They said: \"Fear not, we have been sent against the people of Lout (Lot).\"', 'So, when he noticed their hands not acceding to it, he found them strange and felt scared of them. They said, “Be not scared. We have been sent to the people of LūT.”'),
(1544, 11, 71, 7, 7, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ امۡرَاَتُہٗ  قَآئِمَۃٌ  فَضَحِکَتۡ فَبَشَّرۡنٰہَا بِاِسۡحٰقَ ۙ وَ مِنۡ وَّرَآءِ  اِسۡحٰقَ یَعۡقُوۡبَ ﴿۷۱﴾', 'اور ابراہیم کی بیوی جو پاس کھڑی تھی ہنس پڑی تو ہم نے اس کو اسحٰق کی اور اسحٰق کے بعد یعقوب کی خوشخبری دی۔', 'اور اس کی عورت کھڑی تھی تب وہ ہنس پڑی پھر ہم نے خوشخبری دی اسکو اسحٰق کے پیدا ہونے کی اور اسحٰق کے پیچھے یعقوب کی [۹۹]', 'And his wife was standing (there), and she laughed (either, because the Messengers did not eat their food or for being glad for the destruction of the people of Lout (Lot). But We gave her glad tidings of Ishaque (Isaac), and after him, of Yaqoob (Jacob).', 'His wife was standing (nearby), and she laughed. Thus We gave her the good news about IsHāq, and about Ya‘qūb after IsHāq.'),
(1545, 11, 72, 7, 7, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالَتۡ یٰوَیۡلَتٰۤیءَ اَلِدُ وَ اَنَا عَجُوۡزٌ وَّ ہٰذَا بَعۡلِیۡ  شَیۡخًا ؕ اِنَّ ہٰذَا  لَشَیۡءٌ  عَجِیۡبٌ ﴿۷۲﴾', 'اس نے کہا اے ہے میرے بچہ ہوگا۔ میں تو بڑھیا ہوں اور یہ میرے میاں بھی بوڑھے ہیں یہ تو بڑی عجیب بات ہے۔', 'بولی اے خرابی کیا میں بچہ جنوں گی اور میں بڑھیا ہوں اور یہ خاوند میر اہے بوڑھا [۱۰۰] یہ تو ایک عجیب بات ہے [۱۰۱]', 'She said (in astonishment): \"Woe unto me! Shall I bear a child while I am an old woman, and here is my husband, an old man? Verily! This is a strange thing!\"', 'She said, “Woe to me! Shall I give birth to a child while I am an old woman and this is my husband, an old man? This is something amazing indeed.”'),
(1546, 11, 73, 7, 7, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالُوۡۤا اَتَعۡجَبِیۡنَ مِنۡ اَمۡرِ اللّٰہِ  رَحۡمَتُ اللّٰہِ وَ بَرَکٰتُہٗ عَلَیۡکُمۡ اَہۡلَ الۡبَیۡتِ ؕ اِنَّہٗ  حَمِیۡدٌ  مَّجِیۡدٌ ﴿۷۳﴾', 'انہوں نے کہا کیا تم اللہ کی قدرت سے تعجب کرتی ہو؟ اے اہل بیت تم پر اللہ کی رحمت اور اسکی برکتیں ہیں وہ لائق تعریف ہے بڑا ہے۔', 'وہ بولے کیا تو تعجب کرتی ہے اللہ کے حکم سے اللہ کی رحمت ہے اور برکتیں تم پر اے گھر والو تحقیق اللہ ہے تعریف کیا گیا بڑائیوں والا [۱۰۲]', 'They said: \"Do you wonder at the Decree of Allah? The Mercy of Allah and His Blessings be on you, O the family (of Ibraheem (Abraham)). Surely, He (Allah) is All-Praiseworthy, All-Glorious.\"', 'They said, “Do you marvel at Allah’s command? Allah’s mercy and His blessings have always been upon you, O people of the house. Surely, He is Praiseworthy, Glorious.”'),
(1547, 11, 74, 7, 7, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'فَلَمَّا ذَہَبَ عَنۡ اِبۡرٰہِیۡمَ الرَّوۡعُ وَ جَآءَتۡہُ  الۡبُشۡرٰی یُجَادِلُنَا فِیۡ قَوۡمِ لُوۡطٍ ﴿ؕ۷۴﴾', 'پھر جب ابراہیم سے خوف جاتا رہا اور انکو خوشخبری بھی مل گئ تو قوم لوط کے بارے میں لگے ہم سے بحث کرنے۔', 'پھر جب جاتا رہا ابراہیم سے ڈر اور آئی اس کو خوشخبری جھگڑنے لگا ہم سے قوم لوط کے حق میں', 'Then when the fear had gone away from (the mind of) Ibraheem (Abraham), and the glad tidings had reached him, he began to plead with Us (Our Messengers) for the people of Lout (Lot).', 'So, when fear left Ibrāhīm and the happy news came to him, he started disputing with Us for the people of LūT.'),
(1548, 11, 75, 7, 7, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'اِنَّ  اِبۡرٰہِیۡمَ  لَحَلِیۡمٌ  اَوَّاہٌ   مُّنِیۡبٌ ﴿۷۵﴾', 'بیشک ابراہیم بڑے تحمل والے نرم دل اور رجوع کرنے والے تھے۔', 'البتہ ابراہیم تحمل والا نرم دل ہے رجوع رہنے والا', 'Verily, Ibraheem (Abraham) was, without doubt, forbearing, used to invoke Allah with humility, and was repentant (to Allah all the time, again and again).', 'Surely, Ibrāhīm is forbearing, very penitent, ever-turning to Allah.'),
(1549, 11, 76, 7, 7, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'یٰۤـاِبۡرٰہِیۡمُ اَعۡرِضۡ عَنۡ ہٰذَا ۚ اِنَّہٗ قَدۡ جَآءَ اَمۡرُ رَبِّکَ ۚ وَ اِنَّہُمۡ اٰتِیۡہِمۡ عَذَابٌ غَیۡرُ  مَرۡدُوۡدٍ ﴿۷۶﴾', 'اے ابراہیم اس بات کو جانے دو۔ تمہارے پروردگار کا حکم آ پہنچا ہے۔ اور ان لوگوں پر عذاب آنے والا ہے جو کبھی نہیں ٹلنے کا۔', 'اے ابراہیم چھوڑ یہ خیال وہ تو آ چکا حکم تیرے رب کا اور ان پر آتا ہے عذاب جو لوٹایا نہیں جاتا [۱۰۳]', '\"O Ibraheem (Abraham)! Forsake this. Indeed, the Commandment of your Lord has gone forth. Verily, there will come a torment for them which cannot be turned back.\"', '“O Ibrāhīm! Leave it. In fact, the command of your Lord has come to pass, and there has to come upon them a punishment that cannot be averted.”'),
(1550, 11, 77, 7, 7, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ لَمَّا جَآءَتۡ رُسُلُنَا لُوۡطًا سِیۡٓءَ بِہِمۡ وَ ضَاقَ بِہِمۡ ذَرۡعًا وَّ قَالَ ہٰذَا یَوۡمٌ عَصِیۡبٌ ﴿۷۷﴾', 'اور جب ہمارے فرشتے لوط کے پاس آئے تو وہ ان کے آنے سے غمناک اور تنگدل ہوئے اور کہنے لگے کہ آج کا دن بڑی مشکل کا دن ہے۔', 'اور جب پہنچے ہمارے بھیجے ہوئے لوط کے پاس غمگین ہوا انکے آنے سے اور تنگ دل ہوا دل میں اور بولا آج دن بڑ اسخت ہے [۱۰۴]', 'And when Our Messengers came to Lout (Lot), he was grieved on their account and felt himself straitened for them (lest the town people should approach them to commit sodomy with them). He said: \"This is a distressful day.\"', 'When Our emissaries (angels) came to LūT, he was saddened because of them, and his heart felt uneasy for their sake, and He said, “This is a very hard day.”'),
(1551, 11, 78, 7, 7, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ جَآءَہٗ  قَوۡمُہٗ یُہۡرَعُوۡنَ  اِلَیۡہِ ؕ وَ مِنۡ قَبۡلُ کَانُوۡا یَعۡمَلُوۡنَ السَّیِّاٰتِ ؕ قَالَ یٰقَوۡمِ ہٰۤؤُلَآءِ بَنَاتِیۡ ہُنَّ اَطۡہَرُ  لَکُمۡ فَاتَّقُوا اللّٰہَ وَ لَا تُخۡزُوۡنِ فِیۡ ضَیۡفِیۡ ؕ اَلَـیۡسَ مِنۡکُمۡ  رَجُلٌ  رَّشِیۡدٌ ﴿۷۸﴾', 'اور لوط کی قوم کے لوگ انکے پاس بےتحاشہ دوڑتے ہوئے آئے اور یہ لوگ پہلے ہی سے انتہائی بیہودہ حرکتیں کیا کرتے تھے لوط نے کہا کہ اے بھائیو! یہ جو میری قوم کی لڑکیاں ہیں یہ تمہارے لئے جائز اور پاک ہیں۔ تو اللہ سے ڈرو اور میرے مہمانوں کے بارے میں مجھے بے آبرو نہ کرو۔ کیا تم میں کوئی بھی شائستہ آدمی نہیں؟', 'اور آئی اس کے پاس قوم اسکی دوڑتی بے اختیار اور آگے سے کر رہے تھے برے کام [۱۰۵] بولا اے قوم یہ میری بیٹیاں حاضر ہیں یہ پاک ہیں تم کو اُن سے سو ڈرو تم اللہ سے اور مت رسوا کرو مجھ کو میرے مہمانوں میں کیا تم میں ایک مرد بھی نہیں نیک چلن [۱۰۶]', 'And his people came rushing towards him, and since aforetime they used to commit crimes (sodomy, etc.), he said: \"O my people! Here are my daughters (i.e. the daughters of my nation), they are purer for you (if you marry them lawfully). So fear Allah and degrade me not as regards my guests! Is there not among you a single right-minded man?\"', 'And his people came to him, rushing upon him. They were already habitual to commit evil deeds. He said, “These are my daughters. They are purer for you.So, have fear of Allah and do not disgrace me in respect of my guests. Is there no reasonable man among you?”'),
(1552, 11, 79, 7, 7, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالُوۡا لَقَدۡ عَلِمۡتَ مَا لَنَا فِیۡ بَنٰتِکَ مِنۡ حَقٍّ ۚ وَ  اِنَّکَ  لَتَعۡلَمُ  مَا نُرِیۡدُ ﴿۷۹﴾', 'وہ بولے تم کو معلوم ہے کہ تمہاری ان بیٹیوں کی ہمیں کچھ حاجت نہیں۔ اور جو ہماری غرض ہے اسے تم خوب جانتے ہو۔', 'بولے تو تو جانتا ہے ہم کو تیری بیٹیوں سے کچھ غرض نہیں اور تجھ کو تو معلوم ہے جو ہم چاہتے ہیں [۱۰۷]', 'They said: \"Surely you know that we have neither any desire nor in need of your daughters, and indeed you know well what we want!\"', 'They said, “You know that we have no claim on your daughters, and you know well what we want.”'),
(1553, 11, 80, 7, 7, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالَ لَوۡ اَنَّ لِیۡ بِکُمۡ قُوَّۃً  اَوۡ اٰوِیۡۤ اِلٰی رُکۡنٍ  شَدِیۡدٍ ﴿۸۰﴾', 'لوط نے کہا اے کاش مجھ میں تمہارے مقابلے کی طاقت ہوتی یا میں کسی مضبوط قلعے میں پناہ لے لیتا۔', 'کہنے لگا کاش مجھ کو تمہارے مقابلہ میں زور ہوتا یا جا بیٹھتا کسی مستحکم پناہ میں [۱۰۸]', 'He said: \"Would that I had strength (men) to overpower you, or that I could betake myself to some powerful support (to resist you).\"', 'He said, “Would that I had some power over you, or could seek refuge in a strong support!”'),
(1554, 11, 81, 7, 7, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالُوۡا یٰلُوۡطُ اِنَّا رُسُلُ رَبِّکَ  لَنۡ  یَّصِلُوۡۤا  اِلَیۡکَ فَاَسۡرِ  بِاَہۡلِکَ بِقِطۡعٍ مِّنَ الَّیۡلِ وَ لَا یَلۡتَفِتۡ مِنۡکُمۡ اَحَدٌ  اِلَّا امۡرَاَتَکَ ؕ اِنَّہٗ  مُصِیۡبُہَا مَاۤ  اَصَابَہُمۡ ؕ اِنَّ مَوۡعِدَہُمُ الصُّبۡحُ ؕ اَلَـیۡسَ  الصُّبۡحُ  بِقَرِیۡبٍ  ﴿۸۱﴾', 'فرشتوں نے کہا کہ اے لوط ہم تمہارے پروردگار کے فرشتے ہیں یہ لوگ ہرگز تم تک نہیں پہنچ سکیں گے تو کچھ رات رہے سے اپنے گھر والوں کو لے کر چل دو اور تم میں سے کوئی شخص پیچھے مڑ کر نہ دیکھے۔ مگر تمہاری بیوی کہ جو آفت ان پر پڑنے والی ہے وہی اسپر بھی پڑے گی۔ انکے عذاب کے وعدے کا وقت صبح ہے اور کیا صبح کچھ دور ہے؟', 'مہمان بولے اے لوط ہم بھیجے ہوئے ہیں تیرے رب کے ہرگز نہ پہنچ سکیں گے تجھ تک [۱۰۹] سو لے نکل اپنے لوگوں کو کچھ رات سے اور مڑ کر نہ دیکھے تم میں کوئی مگر عورت تیری کہ اس کو پہنچ کر رہے گا جو ان کو پہنچے گا [۱۱۰] ان کے وعدہ کا وقت ہے صبح کیا صبح نہیں ہے نزدیک [۱۱۱]', 'They (Messengers) said: \"O Lout (Lot)! Verily, we are the Messengers from your Lord! They shall not reach you! So travel with your family in a part of the night, and let not any of you look back, but your wife (will remain behind), verily, the punishment which will afflict them, will afflict her. Indeed, morning is their appointed time. Is not the morning near?\"', 'They (the angels) said, “O LūT, we are emissaries of your Lord. They shall never reach you. So, move with your family in a part of night, and none of you shall turn to look back; except your woman. There has to befall her whatever will befall them. Their deadline is the morning. Is it not that the morning is near?”'),
(1555, 11, 82, 7, 7, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'فَلَمَّا جَآءَ اَمۡرُنَا جَعَلۡنَا عَالِیَہَا سَافِلَہَا وَ اَمۡطَرۡنَا عَلَیۡہَا حِجَارَۃً  مِّنۡ سِجِّیۡلٍ ۬ۙ مَّنۡضُوۡدٍ ﴿ۙ۸۲﴾', 'پھر جب ہمارا حکم آیا ہم نے اس بستی کو الٹ کر نیچے اوپر کر دیا۔ اور ان پر پتھر کی تہ بہ تہ کنکریاں برسائیں۔', 'پھر جب پہنچا حکم ہمارا کر ڈالی ہم نے وہ بستی اوپر نیچے اور برسائے ہم نے اس پر پتھر کنکر کے [۱۱۲] تہہ بہ تہہ [۱۱۳]', 'So when Our Commandment came, We turned (the towns of Sodom in Palestine) upside down, and rained on them stones of baked clay, piled up;', 'So, when Our command came to pass, We turned their habitations upside down, and rained on it stones of hard clay, one over another'),
(1556, 11, 83, 7, 7, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'مُّسَوَّمَۃً  عِنۡدَ رَبِّکَ ؕ وَ مَا ہِیَ مِنَ الظّٰلِمِیۡنَ بِبَعِیۡدٍ ﴿٪۸۳﴾', 'جن پر تمہارے پروردگار کے ہاں سے نشان کئے ہوئے تھے۔ اور وہ بستی ان ظالموں سے کچھ دور نہیں۔', 'نشان کئے ہوئے تیرے رب کے پاس [۱۱۴] اور نہیں ہے وہ بستی ان ظالموں سے کچھ دور [۱۱۵]', 'Marked from your Lord, and they are not ever far from the Zalimoon (polytheists, evil-doers, etc.).', 'marked from your Lord. And it is not far from the transgressors.'),
(1557, 11, 84, 8, 8, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ اِلٰی مَدۡیَنَ اَخَاہُمۡ شُعَیۡبًا ؕ قَالَ یٰقَوۡمِ  اعۡبُدُوا  اللّٰہَ مَا لَکُمۡ مِّنۡ اِلٰہٍ غَیۡرُہٗ ؕ وَ لَا تَنۡقُصُوا الۡمِکۡیَالَ وَ الۡمِیۡزَانَ  اِنِّیۡۤ  اَرٰىکُمۡ  بِخَیۡرٍ  وَّ اِنِّیۡۤ  اَخَافُ عَلَیۡکُمۡ عَذَابَ یَوۡمٍ مُّحِیۡطٍ  ﴿۸۴﴾', 'اور مدین کی طرف انکے بھائی شعیب کو بھیجا تو انہوں نے کہا کہ اے قوم! اللہ ہی کی عبادت کرو کہ اسکے سوا تمہارا کوئی معبود نہیں۔ اور ناپ اور تول میں کمی نہ کیا کرو میں تو تم کو آسودہ حال دیکھتا ہوں اور اگر تم ایمان نہ لاؤ گے تو مجھے تمہارے بارے میں ایک ایسے دن کے عذاب کا خوف ہے جو تم کو گھیر کر رہے گا۔', 'اور مدین کی طرف بھیجا ان کے بھائی شعیب کو بولا اے میری قوم بندگی کرو اللہ کی کوئی نہیں تمہارا معبود اس کے سوائے اور نہ گھٹاؤ ماپ اور تول کو [۱۱۶] میں دیکھتا ہوں تم کو آسودہ حال اور ڈرتا ہوں تم پر عذاب سے ایک گھیر لینے والے دن کے [۱۱۷]', 'And to the Madyan (Midian) people (We sent) their brother Shuaib. He said: \"O my people! Worship Allah, you have no other Ilah (God) but Him, and give not short measure or weight, I see you in prosperity; and verily I fear for you the torment of a Day encompassing.', 'And to Madyan (We sent) their brother, Shu‘aib. He said, “O my people, worship Allah. You have no god other than Him. And do not curtail the measure and the weight. I see you quite well off, and I fear for you the punishment of an encircling day.'),
(1558, 11, 85, 8, 8, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ یٰقَوۡمِ اَوۡفُوا الۡمِکۡیَالَ وَ الۡمِیۡزَانَ بِالۡقِسۡطِ وَ لَا تَبۡخَسُوا النَّاسَ اَشۡیَآءَہُمۡ وَ لَا تَعۡثَوۡا فِی الۡاَرۡضِ مُفۡسِدِیۡنَ ﴿۸۵﴾', 'اور اے میری قوم! ناپ اور تول انصاف کے ساتھ پوری پوری کیا کرو اور لوگوں کو انکی چیزیں کم نہ دیا کرو۔ اور زمین میں خرابی کرتے نہ پھرو۔', 'اور اے قوم پورا کرو ماپ اور تول کو انصاف سے [۱۱۸] اور نہ گھٹا دو لوگوں کو ان کی چیزیں [۱۱۹] اور مت مچاؤ زمین میں فساد [۱۲۰]', '\"And O my people! Give full measure and weight in justice and reduce not the things that are due to the people, and do not commit mischief in the land, causing corruption.', 'And O my people, perfect the measure and the balance with justice and do not make the people short of their things, and do not go about the earth spreading disorder.'),
(1559, 11, 86, 8, 8, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'بَقِیَّتُ اللّٰہِ خَیۡرٌ لَّکُمۡ  اِنۡ کُنۡتُمۡ مُّؤۡمِنِیۡنَ ۬ۚ وَ مَاۤ  اَنَا عَلَیۡکُمۡ  بِحَفِیۡظٍ ﴿۸۶﴾', 'اگر تم کو میرے کہنے کا یقین ہو تو اللہ کا دیا ہوا نفع ہی تمہارے لئے بہتر ہے اور میں تمہارا نگہبان نہیں ہوں۔', 'جو بچ رہے اللہ کا دیا وہ بہتر ہے تم کو اگر ہو تم ایمان والے [۱۲۱] اور میں نہیں ہوں تم پر نگہبان [۱۲۲]', '\"That which is left by Allah for you (after giving the rights of the people) is better for you, if you are believers. And I am not set over you as a guardian.', 'Whatever is allowed by Allah to retain (lawfully) is better for you, if you are believers. And I am not a watchman over you.'),
(1560, 11, 87, 8, 8, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالُوۡا یٰشُعَیۡبُ اَصَلٰوتُکَ تَاۡمُرُکَ اَنۡ نَّتۡرُکَ مَا یَعۡبُدُ اٰبَآؤُنَاۤ اَوۡ اَنۡ نَّفۡعَلَ فِیۡۤ اَمۡوَالِنَا مَا نَشٰٓؤُاؕ اِنَّکَ لَاَنۡتَ الۡحَلِیۡمُ الرَّشِیۡدُ  ﴿۸۷﴾', 'انہوں نے کہا اے شعیب کیا تمہاری نماز تمہیں یہ سکھاتی ہے کہ جنکو ہمارے باپ دادا پوجتے آئے ہیں ہم انکو ترک کر دیں یا اپنے مال میں تصرف کرنا چاہیں تو نہ کریں تم تو بڑے نرم دل اور بڑے سیدھے ہو۔', 'بولے اے شعیب کیا تیرے نماز پڑھنے نے تجھ کو یہ سکھایا کہ ہم چھوڑ دیں جن کو پوجتے رہے ہمارے باپ دادے یا چھوڑ دیں کرنا جو کچھ کہ کرتے ہیں اپنے مالوں میں تو ہی بڑ ابا وقار  ہے نیک چلن [۱۲۳]', 'They said: \"O Shuaib! Does your Salat (prayer) (i.e. the prayers which you offer has spoiled your mind, so you) command that we leave off what our fathers used to worship, or that we leave off doing what we like with our property? Verily, you are the forbearer, right-minded!\" (They said this sarcastically).', 'They said, “O Shu‘aib, does your Salāh (prayer) command you that we should forsake what our fathers used to worship or that we should not deal with our wealth as we please? You pretend to be the only man of wisdom and guidance.”'),
(1561, 11, 88, 8, 8, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالَ یٰقَوۡمِ اَرَءَیۡتُمۡ اِنۡ کُنۡتُ عَلٰی بَیِّنَۃٍ مِّنۡ رَّبِّیۡ وَ رَزَقَنِیۡ مِنۡہُ رِزۡقًا حَسَنًا ؕ وَ مَاۤ  اُرِیۡدُ اَنۡ اُخَالِفَکُمۡ  اِلٰی مَاۤ اَنۡہٰکُمۡ عَنۡہُ  ؕ اِنۡ اُرِیۡدُ اِلَّا الۡاِصۡلَاحَ مَا  اسۡتَطَعۡتُ ؕ وَ مَا تَوۡفِیۡقِیۡۤ اِلَّا بِاللّٰہِ ؕعَلَیۡہِ  تَوَکَّلۡتُ وَ اِلَیۡہِ  اُنِیۡبُ ﴿۸۸﴾', 'انہوں نے کہا کہ اے قوم! دیکھو تو اگر میں اپنے پروردگار کی طرف سے دلیل روشن پر ہوں اور اس نے اپنے ہاں سے مجھے نیک روزی دی ہو تو کیا میں اپنا فرض ادا نہ کروں؟ اور میں نہیں چاہتا کہ جس بات سے میں تمہیں منع کروں خود اسکو کرنے لگوں میں تو جہاں تک مجھ سے ہو سکے تمہارے معاملات کی اصلاح چاہتا ہوں اور اس بارے میں مجھے توفیق کا ملنا اللہ ہی کے فضل سے ہے۔ میں اسی پر بھروسہ رکھتا ہوں اور اسی کی طرف رجوع کرتا ہوں۔', 'بولا اے قوم دیکھو تو اگر مجھ کو سمجھ آ گئ اپنے رب کی طرف سے اور اس نے روزی دی مجھ کو نیک روزی [۱۲۴] اور میں یہ نہیں چاہتا کہ بعد کو خود کروں وہ کام جو تم سے چھڑاؤں [۱۲۵] میں تو چاہتا ہوں سنوارنا جہاں تک ہو سکے اور بن آنا ہے اللہ کی مدد سے اسی پر میں نے بھروسہ کیا ہے اور اسی کی طرف میرا رجوع ہے [۱۲۶]', 'He said: \"O my people! Tell me, if I have a clear evidence from my Lord, and He has given me a good sustenance from Himself (shall I corrupt it by mixing it with the unlawfully earned money). I wish not, in contradiction to you, to do that which I forbid you. I only desire reform so far as I am able, to the best of my power. And my guidance cannot come except from Allah, in Him I trust and unto Him I repent.', 'He said, “O my people, tell me, if I am on a clear path from my Lord and He has provided me with a good provision from Himself, (should I still leave you unguided?) I do not want to do in your absence what I forbid you from. I want nothing but to set things right as far as I can. My ability to do any thing comes from none but Allah. In Him alone I have placed my trust and to Him alone I turn in humbleness.'),
(1562, 11, 89, 8, 8, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ یٰقَوۡمِ لَا یَجۡرِمَنَّکُمۡ شِقَاقِیۡۤ اَنۡ یُّصِیۡبَکُمۡ مِّثۡلُ مَاۤ  اَصَابَ قَوۡمَ  نُوۡحٍ اَوۡ قَوۡمَ ہُوۡدٍ اَوۡ قَوۡمَ صٰلِحٍ ؕ وَ مَا قَوۡمُ لُوۡطٍ مِّنۡکُمۡ  بِبَعِیۡدٍ ﴿۸۹﴾', 'اور اے قوم! میری مخالفت تم سے کوئی ایسا کام نہ کرا دے کہ جیسی مصیبت نوح کی قوم یا ہود کی قوم یا صالح کی قوم پر واقع ہوئی تھی ویسی ہی مصیبت تم پر واقع ہو اور لوط کی قوم کا زمانہ تو تم سے کچھ دور نہیں۔', 'اور اے قوم نہ کمائیو میری ضد کر کے یہ کہ پڑے تم پر جیسا کچھ کہ پڑ چکا قوم نوح پر یا قوم ہود پر یا قوم صالح پر اور قوم لوط تو تم سے کچھ دور ہی نہیں [۱۲۷]', '\"And O my people! Let not my Shiqaq cause you to suffer the fate similar to that of the people of Nooh (Noah) or of Hood or of Salih (Saleh), and the people of Lout (Lot) are not far off from you!', 'O my people, let not your hostility towards me cause you to suffer what was suffered by the people of NūH, or the people of Hūd, or the people of SāliH. And the people of LūT are not far from you.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1563, 11, 90, 8, 8, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ اسۡتَغۡفِرُوۡا رَبَّکُمۡ ثُمَّ تُوۡبُوۡۤا اِلَیۡہِ ؕ اِنَّ  رَبِّیۡ  رَحِیۡمٌ   وَّدُوۡدٌ ﴿۹۰﴾', 'اور اپنے پروردگار سے بخشش مانگو اور اسکے آگے توبہ کرو۔ بیشک میرا پروردگار بڑا مہربان ہے بہت محبت کرنے والا ہے۔', 'اور گناہ بخشواؤ اپنے رب سے اور رجوع کرو اسکی طرف البتہ میرا رب ہے مہربان محبت والا [۱۲۸]', '\"And ask forgiveness of your Lord and turn unto Him in repentance. Verily, my Lord is Most Merciful, Most Loving.\"', 'Seek forgiveness from your Lord, then turn towards Him in repentance. Surely, my Lord is very merciful, most loving.”'),
(1564, 11, 91, 8, 8, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالُوۡا یٰشُعَیۡبُ مَا نَفۡقَہُ کَثِیۡرًا مِّمَّا تَقُوۡلُ وَ  اِنَّا  لَنَرٰىکَ فِیۡنَا ضَعِیۡفًا ۚ وَ لَوۡ لَا رَہۡطُکَ لَرَجَمۡنٰکَ ۫ وَ مَاۤ  اَنۡتَ عَلَیۡنَا بِعَزِیۡزٍ ﴿۹۱﴾', 'انہوں نے کہا کہ شعیب تمہاری بہت سی باتیں ہماری سمجھ میں نہیں آتیں اور ہم دیکھتے ہیں کہ تم ہم میں کمزور بھی ہو اور اگر تمہارے بھائی بند نہ ہوتے تو ہم تم کو سنگسار کر دیتے اور تم ہم پر کسی طرح بھی غالب نہیں ہو۔', 'بولے اے شعیب ہم نہیں سمجھتے بہت باتیں جو تو کہتا ہے [۱۲۹] اور ہم تو دیکھتے ہیں کہ تو ہم میں کمزور ہے [۱۳۰] اور اگر نہ ہوتے تیرے بھائی بند تو تجھ کو تو ہم سنگسار کر ڈالتے اور ہماری نگاہ میں تیری کچھ عزت نہیں [۱۳۱]', 'They said: \"O Shuaib! We do not understand much of what you say, and we see you a weak (man, it is said that he was a blind man) among us. Were it not for your family, we should certainly have stoned you and you are not powerful against us.\"', 'They said, “O Shu‘aib, we do not understand much of what you say, and, in fact, we see you are weak among us. But for your clan, we would have stoned you. And to us, you are not a man of respect.”'),
(1565, 11, 92, 8, 8, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'قَالَ یٰقَوۡمِ اَرَہۡطِیۡۤ اَعَزُّ  عَلَیۡکُمۡ  مِّنَ اللّٰہِ ؕ وَ اتَّخَذۡتُمُوۡہُ  وَرَآءَکُمۡ  ظِہۡرِیًّا ؕ اِنَّ  رَبِّیۡ  بِمَا تَعۡمَلُوۡنَ  مُحِیۡطٌ ﴿۹۲﴾', 'انہوں نے کہا کہ اے قوم! کیا میرے بھائی بندوں کا دباؤ تم پر اللہ سے زیادہ ہے؟ اور اسکو تم نے پیٹھ پیچھے ڈال رکھا ہے۔ میرا پروردگار تو تمہارے سب اعمال کا احاطہ کئے ہوئے ہے۔', 'بولا اے قوم کیا میرے بھائی بندوں کا دباؤ تم پر زیادہ ہے اللہ سے اور اس کو ڈال رکھا تم نے پیٹھ پیچھے بھلا کر تحقیق میرے رب کے قابو میں ہے جو کچھ کرتے ہو [۱۳۲]', 'He said: \"O my people! Is then my family of more weight with you than Allah? And you have cast Him away behind your backs. Verily, my Lord is surrounding all that you do.', 'He said, “O my people, is my clan more respectable to you than Allah, as you have taken Him as something thrown behind your backs? Surely, my Lord encompasses all that you do.'),
(1566, 11, 93, 8, 8, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ یٰقَوۡمِ اعۡمَلُوۡا عَلٰی مَکَانَتِکُمۡ  اِنِّیۡ عَامِلٌ ؕ سَوۡفَ تَعۡلَمُوۡنَ ۙ مَنۡ یَّاۡتِیۡہِ عَذَابٌ یُّخۡزِیۡہِ  وَ مَنۡ ہُوَ کَاذِبٌ ؕ وَ ارۡتَقِبُوۡۤا  اِنِّیۡ  مَعَکُمۡ  رَقِیۡبٌ ﴿۹۳﴾', 'اور اے قوم! تم اپنی جگہ کام کئے جاؤ میں اپنی جگہ کام کئے جاتا ہوں تم کو عنقریب معلوم ہو جائے گا کہ رسوا کرنے والا عذاب کس پر آتا ہے اور جھوٹا کون ہے اور تم بھی انتظار کرو میں بھی تمہارے ساتھ انتظار کرتا ہوں۔', 'اور اے میری قوم کام کئےجاؤ اپنی جگہ میں بھی کام کرتا ہوں آگے معلوم کر لو گے کس پر آتا ہے عذاب رسوا کرنے والا اور کون ہے جھوٹا اور تاکتے رہو میں بھی تمہارے ساتھ تاک رہا ہوں [۱۳۳]', '\"And O my people! Act according to your ability and way, and I am acting (on my way). You will come to know who it is on whom descends the torment that will cover him with ignominy, and who is a liar! And watch you! Verily, I too am watching with you.\"', 'O my people, do what you can, I am to do (what I can). Soon you will know the one whom the punishment will visit, putting him to disgrace, and the one who is false. And wait. I am, with you, waiting.”'),
(1567, 11, 94, 8, 8, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ لَمَّا جَآءَ اَمۡرُنَا نَجَّیۡنَا شُعَیۡبًا وَّ الَّذِیۡنَ اٰمَنُوۡا مَعَہٗ بِرَحۡمَۃٍ  مِّنَّا وَ اَخَذَتِ الَّذِیۡنَ ظَلَمُوا الصَّیۡحَۃُ فَاَصۡبَحُوۡا  فِیۡ  دِیَارِہِمۡ  جٰثِمِیۡنَ ﴿ۙ۹۴﴾', 'اور جب ہمارا حکم آ پہنچا تو ہم نے شعیب کو اور جو لوگ انکے ساتھ ایمان لائے تھے انکو تو اپنی رحمت سے بچا لیا اور جو ظالم تھے انکو چنگھاڑ نے آ دبوچا تو وہ اپنے گھروں میں اوندھے پڑے رہ گئے۔', 'اور جب پہنچا ہمارا حکم بچا دیا ہم نے شعیب کو اور جو ایمان لائے تھے اسکے ساتھ اپنی مہربانی سے اور آ پکڑا ان ظالموں کو کڑک نے پھر صبح کو رہ گئے اپنے گھروں میں اوندھے پڑے ہوئے', 'And when Our Commandment came, We saved Shuaib and those who believed with him by a Mercy from Us. And As-Saeehah (torment - awful cry, etc.) seized the wrong-doers, and they lay (dead) prostrate in their homes.', 'And when Our command came, We saved Shu‘aib and those who believed along with him, out of mercy from Us; and those who transgressed were caught by the Cry, and they were found (dead) in their homes, fallen on their knees'),
(1568, 11, 95, 8, 8, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'کَاَنۡ لَّمۡ  یَغۡنَوۡا  فِیۡہَا ؕ اَلَا بُعۡدًا لِّمَدۡیَنَ  کَمَا بَعِدَتۡ  ثَمُوۡدُ ﴿٪۹۵﴾', 'گویا ان میں کبھی بسے ہی نہ تھے۔ سن رکھو کہ مدین پر ویسی ہی پھٹکار ہے جیسی ثمود پر پھٹکار تھی۔', 'گویا کبھی وہاں بسے ہی نہ تھے [۱۳۴] سن لو پھٹکار ہے مدین کو جیسے پھٹکار ہوئی تھی ثمود کو [۱۳۵]', 'As if they had never lived there! So away with Madyan (Midian)! As away with Thamud! (All these nations were destroyed).', 'as though they never lived there. Lo! Ruined were Madyan, like Thamūd were ruined.'),
(1569, 11, 96, 9, 9, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ لَقَدۡ اَرۡسَلۡنَا مُوۡسٰی بِاٰیٰتِنَا وَ سُلۡطٰنٍ مُّبِیۡنٍ ﴿ۙ۹۶﴾', 'اور ہم نے موسٰی کو اپنی نشانیاں اور دلیل روشن دے کر بھیجا۔', 'اور البتہ بھیج چکے ہیں ہم موسٰی کو اپنی نشانیاں اور واضح سند دے کر [۱۳۶]', 'And indeed We sent Moosa (Moses) with Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) and a manifest authority;', 'And We sent Mūsā, with Our signs and with clear proof,'),
(1570, 11, 97, 9, 9, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'اِلٰی فِرۡعَوۡنَ وَ مَلَا۠ئِہٖ فَاتَّبَعُوۡۤا اَمۡرَ فِرۡعَوۡنَ ۚ وَ مَاۤ اَمۡرُ فِرۡعَوۡنَ بِرَشِیۡدٍ ﴿۹۷﴾', 'فرعون اور اسکے سرداروں کی طرف تو وہ فرعون ہی کے حکم پر چلتے رہے۔ حالانکہ فرعون کا حکم درست نہیں تھا۔', 'فرعون اور اس کے سرداروں کے پاس پھر وہ چلے حکم پر فرعون کے اور نہیں بات فرعون کی کچھ کام کی [۱۳۷]', 'To Firaun (Pharaoh) and his chiefs, but they followed the command of Firaun (Pharaoh), and the command of Firaun (Pharaoh) was no right guide.', 'to Pharaoh and his group. So, they followed the command of Pharaoh, while the command of Pharaoh was not right.'),
(1571, 11, 98, 9, 9, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'یَقۡدُمُ  قَوۡمَہٗ یَوۡمَ الۡقِیٰمَۃِ فَاَوۡرَدَہُمُ النَّارَ ؕ وَ بِئۡسَ الۡوِرۡدُ  الۡمَوۡرُوۡدُ ﴿۹۸﴾', 'وہ قیامت کے دن اپنی قوم کے آگے آگے چلے گا پھر انکو دوزخ میں جا اتارے گا۔ اور جس مقام پر وہ اتارے جائیں گے وہ برا ہے۔', 'آگے ہو گا اپنی قوم کے قیامت کے دن پھر پہنچائے انکو آگ پر اور برا گھاٹ ہے جس پر پہنچے [۱۳۸]', 'He will go ahead of his people on the Day of Resurrection, and will lead them into the Fire, and evil indeed is the place to which they are led.', 'He will lead his people on the Day of Judgement, and make them descend into the Fire. And it is the evil descending place.'),
(1572, 11, 99, 9, 9, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ  اُتۡبِعُوۡا فِیۡ ہٰذِہٖ  لَعۡنَۃً وَّ یَوۡمَ الۡقِیٰمَۃِ ؕ بِئۡسَ الرِّفۡدُ  الۡمَرۡفُوۡدُ ﴿۹۹﴾', 'اور اس جہان میں بھی لعنت انکے پیچھے لگا دی گئ اور قیامت کے دن بھی پیچھے لگی رہے گی جو انعام انکو ملا ہے برا ہے۔', 'اور پیچھے سے ملتی رہی اس جہان میں لعنت اور دن قیامت کے بھی برا انعام ہے جو ان کو ملا [۱۳۹]', 'They were pursued by a curse in this (deceiving life of this world) and (so they will be pursued by a curse) on the Day of Resurrection. How bad is the curse (in this world) pursued by another curse (in the Hereafter).', 'The curse was made to pursue them here and on the Day of Judgement. It is the evil reward to be offered.'),
(1573, 11, 100, 9, 9, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'ذٰلِکَ مِنۡ اَنۡۢبَآءِ الۡقُرٰی نَقُصُّہٗ عَلَیۡکَ مِنۡہَا قَآئِمٌ   وَّ حَصِیۡدٌ ﴿۱۰۰﴾', 'یہ پرانی بستیوں کے تھوڑے سے حالات ہیں جو ہم تم سے بیان کرتے ہیں۔ ان میں سے بعض تو باقی ہیں اور بعض تہس نہس ہو گئیں۔', 'یہ تھوڑے سے حالات ہیں بستیوں کے کہ ہم سناتے ہیں تجھ کو بعض ان میں سےابتک قائم ہیں اور بعض کی جڑ کٹ گئ [۱۴۰]', 'These are some of the news of the (population of) towns which We relate unto you (O Muhammad SAW); of them, some are standing, and some have been (already) reaped.', 'That is a part of stories of the towns that We narrate to you. Some of them are still standing, and (some are) eradicated like a harvested field.'),
(1574, 11, 101, 9, 9, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ مَا ظَلَمۡنٰہُمۡ وَ لٰکِنۡ ظَلَمُوۡۤا اَنۡفُسَہُمۡ فَمَاۤ اَغۡنَتۡ عَنۡہُمۡ اٰلِہَتُہُمُ الَّتِیۡ یَدۡعُوۡنَ مِنۡ دُوۡنِ اللّٰہِ مِنۡ شَیۡءٍ لَّمَّا جَآءَ اَمۡرُ رَبِّکَ ؕ وَ مَا  زَادُوۡہُمۡ غَیۡرَ تَتۡبِیۡبٍ ﴿۱۰۱﴾', 'اور ہم نے ان لوگوں پر ظلم نہیں کیا۔ بلکہ انہوں نے خود اپنے اوپر ظلم کیا غرض جب تمہارے پروردگار کا حکم آ پہنچا تو جن معبودوں کو وہ اللہ کے سوا پکارا کرتے تھے وہ انکے کچھ بھی کام نہ آئے۔ اور بربادی کے سوا انہیں اور کچھ نہ دے سکے۔', 'اور ہم نے ان پر ظلم نہیں کیا لیکن ظلم کر گئے وہی اپنی جان پر پھر کچھ کام نہ آئے ان کے ٹھاکر (معبود) جن کو پکارتے تھے سوائے اللہ کے کسی چیز میں جس وقت پہنچا حکم تیرے رب کا [۱۴۱] اور نہیں بڑھایا انکے حق میں سوائے ہلاک کرنے کے [۱۴۲]', 'We wronged them not, but they wronged themselves. So their aliha (gods), other than Allah, whom they invoked, profited them naught when there came the Command of your Lord, nor did they add aught (to their lot) but destruction.', 'We did no wrong to them; rather, they have wronged themselves. So, their gods whom they used to invoke beside Allah did not come to their help in any way, when came the command of your Lord, and they added nothing to them except destruction.'),
(1575, 11, 102, 9, 9, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ کَذٰلِکَ اَخۡذُ رَبِّکَ اِذَاۤ اَخَذَ الۡقُرٰی وَ ہِیَ  ظَالِمَۃٌ ؕ اِنَّ  اَخۡذَہٗۤ  اَلِیۡمٌ شَدِیۡدٌ ﴿۱۰۲﴾', 'اور تمہارا پروردگار جب نافرمان بستیوں کر پکڑا کرتا ہے تو اسکی پکڑ اسی طرح کی ہوتی ہے۔ بیشک اسکی پکڑ دکھ دینے والی سخت ہے۔', 'اور ایسی ہی ہے پکڑ تیرے رب کی جب پکڑتا ہے بستیوں کو اور وہ ظلم کرتے ہوتے ہیں بیشک اس کی پکڑ دردناک ہے شدت کی [۱۴۳]', 'Such is the Seizure of your Lord when He seizes the (population of) towns while they are doing wrong. Verily, His Seizure is painful, and severe.', 'Such is the seizing of your Lord when He seizes the (people of) towns when they are transgressing. Indeed, His seizing is painful, severe.'),
(1576, 11, 103, 9, 9, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'اِنَّ فِیۡ ذٰلِکَ لَاٰیَۃً لِّمَنۡ خَافَ عَذَابَ الۡاٰخِرَۃِ ؕ ذٰلِکَ  یَوۡمٌ  مَّجۡمُوۡعٌ ۙ لَّہُ النَّاسُ  وَ ذٰلِکَ  یَوۡمٌ  مَّشۡہُوۡدٌ ﴿۱۰۳﴾', 'ان قصوں میں اس شخص کے لئے جو عذاب آخرت سے ڈرے عبرت ہے۔ یہ وہ دن ہوگا جسمیں سب اکٹھے کئے جائیں گے اور یہی وہ دن ہوگا جسمیں سب اللہ کے روبرو حاضر کئے جائیں گے۔', 'اس بات میں نشانی ہے اس کو جو ڈرتا ہے آخرت کے عذاب سے [۱۴۴] وہ ایک دن ہے جس میں جمع ہوں گے سب لوگ اور وہ دن ہے سب کے پیش ہونے کا [۱۴۵]', 'Indeed in that (there) is a sure lesson for those who fear the torment of the Hereafter. That is a Day whereon mankind will be gathered together, and that is a Day when all (the dwellers of the heavens and the earth) will be present.', 'In this there is a sign for the one who fears the punishment of the Hereafter. That is a day when all the people shall be gathered together, and that is a day which will be witnessed by all.'),
(1577, 11, 104, 9, 9, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ مَا نُؤَخِّرُہٗۤ   اِلَّا  لِاَجَلٍ  مَّعۡدُوۡدٍ ﴿۱۰۴﴾ؕ', 'اور ہم اسکے لانے میں ایک وقت معین تک تاخیر کر رہے ہیں۔', 'اور اس کو ہم دیر جو کرتے ہیں سو ایک وعدہ کے لئے جو مقرر ہے [۱۴۶]', 'And We delay it only for a term (already) fixed.', 'We do not defer it but for a limited term.'),
(1578, 11, 105, 9, 9, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'یَوۡمَ یَاۡتِ لَا تَکَلَّمُ نَفۡسٌ اِلَّا بِاِذۡنِہٖ ۚ فَمِنۡہُمۡ  شَقِیٌّ  وَّ سَعِیۡدٌ ﴿۱۰۵﴾', 'جس روز وہ آجائے گا تو کوئی شخص اللہ کے حکم کے بغیر بول بھی نہیں سکے گا پھر ان میں سے کچھ بدبخت ہوں گے اور کچھ نیک بخت۔', 'جس دن وہ آئے گا بات نہ کر سکے گا کوئی جاندار مگر اسکے حکم سے سو ان میں بعضے بدبخت ہیں اور بعضے نیک بخت [۱۴۷]', 'On the Day when it comes, no person shall speak except by His (Allahs) Leave. Some among them will be wretched and (others) blessed.', 'The day it comes no one shall speak except by His leave. So, some of them will be wretched and (some) blessed.'),
(1579, 11, 106, 9, 9, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'فَاَمَّا الَّذِیۡنَ شَقُوۡا فَفِی النَّارِ لَہُمۡ فِیۡہَا زَفِیۡرٌ  وَّ شَہِیۡقٌ ﴿۱۰۶﴾ۙ', 'تو جو بدبخت ہوں گے وہ دوزخ میں ڈال دیئے جائیں گے اس میں ان کو چلانا اور دھاڑنا ہو گا۔', 'سو جو لوگ بد بخت ہیں وہ تو آگ میں ہیں انکو  وہاں چیخنا ہے اور دہاڑنا', 'As for those who are wretched, they will be in the Fire, sighing in a high and low tone.', 'As for those who are wretched, they shall be in the Fire. For them there is (nothing but) crying and howling.'),
(1580, 11, 107, 9, 9, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'خٰلِدِیۡنَ فِیۡہَا مَا دَامَتِ السَّمٰوٰتُ وَ الۡاَرۡضُ اِلَّا مَا شَآءَ رَبُّکَ ؕ اِنَّ رَبَّکَ فَعَّالٌ  لِّمَا یُرِیۡدُ ﴿۱۰۷﴾', 'جب تک آسمان اور زمین ہیں وہ اسی میں رہیں گے۔ مگر جتنا تمہارا پروردگار چاہے۔ بیشک تمہارا پروردگار جو چاہتا ہے کر دیتا ہے۔', 'ہمیشہ رہیں اس میں جب تک رہے آسمان اور زمین مگر جو چاہے تیرا رب بیشک تیرا رب کر ڈالتا ہے جو چاہے', 'They will dwell therein for all the time that the heavens and the earth endure, except as your Lord wills. Verily, your Lord is the doer of what He wills.', 'They shall remain there forever, as long as the heavens and the earth remain intact, unless your Lord wills (otherwise). Surely, your Lord does what He intends.'),
(1581, 11, 108, 9, 9, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ اَمَّا الَّذِیۡنَ سُعِدُوۡا فَفِی الۡجَنَّۃِ خٰلِدِیۡنَ فِیۡہَا مَا دَامَتِ السَّمٰوٰتُ وَ الۡاَرۡضُ  اِلَّا  مَا شَآءَ رَبُّکَ ؕ عَطَآءً غَیۡرَ  مَجۡذُوۡذٍ ﴿۱۰۸﴾', 'اور جو نیک بخت ہوں گے وہ بہشت میں داخل کئے جائیں گے اور جب تک آسمان اور زمین ہیں ہمیشہ اسی میں رہیں گے مگر جتنا تمہارا پروردگار چاہے یہ اللہ کی بخشش ہے جو کبھی منقطع نہیں ہو گی۔', 'اور جو لوگ نیک بخت ہیں سو جنت میں ہیں ہمیشہ رہیں اس میں جب تک رہے آسمان اور زمین مگر جو چاہے تیرا رب بخشش ہے بے انتہا [۱۴۸]', 'And those who are blessed, they will be in Paradise, abiding therein for all the time that the heavens and the earth endure, except as your Lord will, a gift without an end.', 'As for those who are blessed, they shall be in Paradise living there forever, as long as the heavens and the earth remain intact, unless your Lord wills (otherwise), It will be an award never to be ceased.'),
(1582, 11, 109, 9, 9, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'فَلَا تَکُ فِیۡ  مِرۡیَۃٍ  مِّمَّا یَعۡبُدُ  ہٰۤؤُلَآءِ ؕ مَا یَعۡبُدُوۡنَ  اِلَّا کَمَا یَعۡبُدُ  اٰبَآؤُہُمۡ مِّنۡ قَبۡلُ ؕ وَ اِنَّا لَمُوَفُّوۡہُمۡ نَصِیۡبَہُمۡ غَیۡرَ مَنۡقُوۡصٍ ﴿۱۰۹﴾٪', 'تو یہ لوگ جو غیر اللہ کی پرستش کرتے ہیں۔ اس سے تم شک میں نہ پڑنا۔ یہ اسی طرح پرستش کرتے ہیں جس طرح پہلے سے انکے باپ دادا پرستش کرتے آئے ہیں۔ اور ہم انکو ان کا حصہ پورا پورا بغیر کچھ کم کئے دینے والے ہیں۔', 'سو تو نہ رہ دھوکے میں ان چیزوں سے جن کو پوجتے ہیں یہ لوگ کچھ نہیں پوجتے مگر ویسا ہی جیسا کہ پوجتے تھے انکے باپ دادے اس سے پہلے اور ہم دینے والے ہیں انکو انکا حصہ یعنی عذاب سے بلا نقصان [۱۴۹]', 'So be not in doubt (O Muhammad SAW) as to what these (pagans and polytheists) men worship. They worship nothing but what their fathers worshipped before (them). And verily, We shall repay them in full their portion without diminution.', 'So, be not in doubt about what they worship. They worship only in the way their fathers used to worship earlier. Surely, We are going to pay them their full share, not curtailed in the least.'),
(1583, 11, 110, 10, 10, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ لَقَدۡ اٰتَیۡنَا مُوۡسَی الۡکِتٰبَ فَاخۡتُلِفَ فِیۡہِ ؕ وَ لَوۡ لَا کَلِمَۃٌ سَبَقَتۡ مِنۡ رَّبِّکَ لَقُضِیَ بَیۡنَہُمۡ ؕ وَ اِنَّہُمۡ لَفِیۡ شَکٍّ  مِّنۡہُ  مُرِیۡبٍ ﴿۱۱۰﴾', 'اور ہم نے موسٰی کو کتاب دی تو اس میں اختلاف کیا گیا۔ اور اگر تمہارے پروردگار کی طرف سے ایک بات پہلے نہ ہو چکی ہوتی تو ان میں فیصلہ کر دیا جاتا۔ اور وہ تو اس کی طرف سے بڑے بھاری شک میں پڑے ہوئے ہیں۔', 'اور البتہ ہم نے دی تھی موسٰی کو کتاب پھر اس میں پھوٹ پڑ گئ اور اگر نہ ہوتا ایک لفظ کہ پہلے فرما چکا تھا تیرا رب تو فیصلہ ہو جاتا ان میں اور ان کو اس میں شبہ ہے کہ مطمئن نہیں ہونے دیتا [۱۵۰]', 'Indeed, We gave the Book to Moosa (Moses), but differences arose therein, and had it not been for a Word that had gone forth before from your Lord, the case would have been judged between them, and indeed they are in grave doubt concerning it (this Quran).', 'And We gave Mūsā the Book, then it was disputed about. But for a word from your Lord that had already come to pass, the matter would have been decided between them. Surely, they are in confounding doubt about it.'),
(1584, 11, 111, 10, 10, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ  اِنَّ  کُلًّا  لَّمَّا لَیُوَفِّیَنَّہُمۡ  رَبُّکَ  اَعۡمَالَہُمۡ ؕ اِنَّہٗ  بِمَا  یَعۡمَلُوۡنَ  خَبِیۡرٌ ﴿۱۱۱﴾', 'اور تمہارا پروردگار ان سب کو قیامت کے دن انکے اعمال کا پورا پورا بدلہ دے گا۔ بیشک جو عمل یہ کرتے ہیں وہ اس سے واقف ہے۔', 'اور جتنے لوگ ہیں جب وقت آیا پورا (بھگتا دے گا) دے گا رب تیرا ان کو ان کے اعمال اس کو سب خبر ہے جو کچھ وہ  کر رہے ہیں [۱۵۱]', 'And verily, to each of them your Lord will repay their works in full. Surely, He is All-Aware of what they do.', 'And to all of them, your Lord shall pay for their deeds in full. Surely, He is aware of all that they do.'),
(1585, 11, 112, 10, 10, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'فَاسۡتَقِمۡ کَمَاۤ  اُمِرۡتَ وَ مَنۡ تَابَ مَعَکَ وَ لَا تَطۡغَوۡا ؕ اِنَّہٗ  بِمَا تَعۡمَلُوۡنَ بَصِیۡرٌ ﴿۱۱۲﴾', 'سو اے پیغمبر جیسا تم کو حکم ہوتا ہے اس پر تم اور جو لوگ تمہارے ساتھ تائب ہوئے ہیں قائم رہو۔ اور حد سے تجاوز نہ کرنا۔ وہ تمہارے سب اعمال کو دیکھ رہا ہے۔', 'سو تو سیدھا چلا جا جیسا تجھ کو حکم ہوا اور جس نے توبہ کی تیرے ساتھ اور حد سے نہ بڑھو بیشک وہ دیکھتا ہے جو کچھ تم کرتے ہو [۱۵۲]', 'So stand (ask Allah to make) you (Muhammad SAW) firm and straight (on the religion of Islamic Monotheism) as you are commanded and those (your companions) who turn in repentance (unto Allah) with you, and transgress not (Allahs legal limits). Verily, He is All-Seer of what you do.', 'So, stand firm (on faith) as you have been commanded, as well as those who having repented (from disbelief) have joined you, and do not cross the limits. Surely, He is watchful of what you do.'),
(1586, 11, 113, 10, 10, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ لَا تَرۡکَنُوۡۤا اِلَی الَّذِیۡنَ ظَلَمُوۡا فَتَمَسَّکُمُ النَّارُ ۙ وَ مَا لَکُمۡ مِّنۡ دُوۡنِ اللّٰہِ مِنۡ اَوۡلِیَآءَ ثُمَّ  لَا  تُنۡصَرُوۡنَ ﴿۱۱۳﴾', 'اور مسلمانو جو لوگ ظالم ہیں انکی طرف مائل نہ ہونا نہیں تو تمہیں بھی دوزخ کی آگ آ لپٹے گی اور اللہ کے سوا تمہارے کوئی دوست نہیں ہونگے پھر تمہیں کوئی مدد بھی نہ ملے گی۔', 'اور مت جھکو ان کی طرف جو ظالم ہیں پھر تم کو لگے گی آگ اور کوئی نہیں تمہارا اللہ کے سوا مددگار پھر کہیں مدد نہ پاؤ گے [۱۵۳]', 'And incline not toward those who do wrong, lest the Fire should touch you, and you have no protectors other than Allah, nor you would then be helped.', 'And do not incline towards the wrongdoers, lest the Fire should catch you, and you have no supporters other than Allah, then you should not be helped.'),
(1587, 11, 114, 10, 10, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ اَقِمِ الصَّلٰوۃَ طَرَفَیِ النَّہَارِ وَ زُلَفًا مِّنَ الَّیۡلِ ؕ اِنَّ الۡحَسَنٰتِ یُذۡہِبۡنَ السَّیِّاٰتِ ؕ ذٰلِکَ  ذِکۡرٰی  لِلذّٰکِرِیۡنَ ﴿۱۱۴﴾ۚ', 'اور دن کے دونوں سروں یعنی صبح اور شام کے اوقات میں اور رات کی چند ساعتوں میں نماز پڑھا کرو۔ کچھ شک نہیں کہ نیکیاں گناہوں کو دور کر دیتی ہیں۔ یہ انکے لئے نصیحت ہے جو نصیحت قبول کرنے والے ہیں۔', 'اور قائم کر نماز کو دونوں طرف دن کے اورکچھ ٹکڑوں میں رات کے [۱۵۴] البتہ نیکیاں دور کرتی ہیں برائیوں کو یہ یادگاری ہے یاد رکھنے والوں کو [۱۵۵]', 'And perform As-Salat (Iqamat-as-Salat), at the two ends of the day and in some hours of the night (i.e. the five compulsory Salat (prayers)). Verily, the good deeds remove the evil deeds (i.e. small sins). That is a reminder (an advice) for the mindful (those who accept advice).', 'Establish Salāh at both ends of the day, and in the early hours of the night. Surely, good deeds erase bad deeds. That is a reminder for the mindful.'),
(1588, 11, 115, 10, 10, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ اصۡبِرۡ فَاِنَّ اللّٰہَ لَا یُضِیۡعُ اَجۡرَ الۡمُحۡسِنِیۡنَ ﴿۱۱۵﴾', 'اور صبر کئے رہو کہ اللہ نیکوکاروں کا اجر ضائع نہیں کرتا۔', 'اور صبر کر البتہ اللہ ضائع نہیں کرتا ثواب نیکی کرنے والوں کا [۱۵۶]', 'And be patient; verily, Allah loses not the reward of the good-doers.', 'And be patient, for Allah does not let the reward of the righteous go to waste.'),
(1589, 11, 116, 10, 10, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'فَلَوۡ لَا کَانَ مِنَ الۡقُرُوۡنِ مِنۡ قَبۡلِکُمۡ اُولُوۡا بَقِیَّۃٍ یَّنۡہَوۡنَ عَنِ الۡفَسَادِ فِی الۡاَرۡضِ اِلَّا قَلِیۡلًا مِّمَّنۡ اَنۡجَیۡنَا مِنۡہُمۡ ۚ وَ اتَّبَعَ  الَّذِیۡنَ  ظَلَمُوۡا مَاۤ اُتۡرِفُوۡا فِیۡہِ وَ کَانُوۡا مُجۡرِمِیۡنَ ﴿۱۱۶﴾', 'تو جو امتیں تم سے پہلے گذر چکی ہیں ان میں ایسے ہوشمند کیوں نہ ہوئے جو ملک میں خرابی کرنے سے روکتے ہاں ایسے تھوڑے سے تھے جنکو ہم نے ان میں سے نجات بخشی۔ اور جو ظالم تھے وہ انہی باتوں کے پیچھے لگے رہے جن میں عیش و آرام تھا اور وہ گناہوں میں ڈوبے ہوئے تھے۔', 'سو کیویں نہ ہوئے ان جماعتوں میں جو تم سے پہلے تھیں ایسے لوگ جن میں اثر خیر رہا ہو کہ منع کرتے رہتے بگاڑ کرنے سے ملک میں مگر تھوڑے کہ جن کو ہم نے بچا لیا ان میں سے اور چلے وہ لوگ (اور پیچھے پڑے رہے ظالم اسی چیز کے جس میں ان کو عیش ملا) جو ظالم تھے وہی راہ جس میں عیش سے رہتے تھے اور تھے گنہگار [۱۵۷]', 'If only there had been among the generations before you, persons having wisdom, prohibiting (others) from Al-Fasad (disbelief, polytheism, and all kinds of crimes and sins) in the earth, except a few of those whom We saved from among them. Those who did wrong pursued the enjoyment of good things of (this worldly) life, and were Mujrimoon (criminals, disbelievers in Allah, polytheists, sinners, etc.).', 'Then, why is it that there were no people, among the generations before you, who would have enough remnants of wisdom to stop others from creating disorder in the land, except a few among them whom We saved (from Our punishment)? And the wrongdoers pursued the luxuries they were involved in, and they became sinners.'),
(1590, 11, 117, 10, 10, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ مَا کَانَ رَبُّکَ لِیُہۡلِکَ الۡقُرٰی بِظُلۡمٍ  وَّ  اَہۡلُہَا مُصۡلِحُوۡنَ ﴿۱۱۷﴾', 'اور تمہارا پروردگار ایسا نہیں ہے کہ بستیوں کو جبکہ وہاں کے باشندے نیکوکار ہوں ازراہ ظلم تباہ کر دے۔', 'اور تیرا رب ہرگز ایسا نہیں کہ ہلاک کرے بستیوں کو زبردستی سے اور لوگ وہاں کے نیک ہوں [۱۵۸]', 'And your Lord would never destroy the towns wrongfully, while their people were right-doers.', 'Your Lord is not such that He would destroy the towns unjustly while their people are good in their ways.'),
(1591, 11, 118, 10, 10, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ لَوۡ شَآءَ رَبُّکَ لَجَعَلَ النَّاسَ اُمَّۃً وَّاحِدَۃً  وَّ لَا  یَزَالُوۡنَ  مُخۡتَلِفِیۡنَ ﴿۱۱۸﴾ۙ', 'اور اگر تمہارا پروردگار چاہتا تو تمام لوگوں کو ایک ہی جماعت کر دیتا اور وہ برابر اختلاف کرتے رہیں گے۔', 'اور اگر چاہتا تیرا رب کر ڈالتا لوگوں کو ایک راستہ پر اور ہمیشہ رہتے ہیں اختلاف میں', 'And if your Lord had so willed, He could surely have made mankind one Ummah (nation or community (following one religion only i.e. Islam)), but they will not cease to disagree,-', 'Had your Lord willed, He would have made all the people a single community. But, they will continue in their differences,'),
(1592, 11, 119, 10, 10, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'اِلَّا مَنۡ رَّحِمَ رَبُّکَ ؕ وَ لِذٰلِکَ خَلَقَہُمۡ ؕ وَ تَمَّتۡ کَلِمَۃُ رَبِّکَ لَاَمۡلَـَٔنَّ  جَہَنَّمَ  مِنَ الۡجِنَّۃِ  وَ النَّاسِ  اَجۡمَعِیۡنَ ﴿۱۱۹﴾', 'مگر جن پر تمہارا پروردگار رحم فرمائے اور اسی لئے اس نے انکو پیدا کیا ہے اور تمہارے پروردگار کا قول پورا ہو گیا کہ میں دوزخ کو جنوں اور انسانوں سب سے بھر دوں گا۔', 'مگر جن پر حم کیا تیرے رب نے [۱۵۹] اور اسی واسطے انکو پیدا کیا ہے اور پوری ہوئی بات تیرے رب کی کہ البتہ بھر دوں گا دوزخ جنوں سے اور آدمیوں سے اکٹھے [۱۶۰]', 'Except him on whom your Lord has bestowed His Mercy (the follower of truth - Islamic Monotheism) and for that did He create them. And the Word of your Lord has been fulfilled (i.e. His Saying): \"Surely, I shall fill Hell with jinns and men all together.\"', 'except those whom Allah has blessed with mercy, and for that He has created them. And perfect is the word of your Lord: “I will surely fill the Hell with Jinns and the human beings, all together.”'),
(1593, 11, 120, 10, 10, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ کُلًّا نَّقُصُّ عَلَیۡکَ مِنۡ اَنۡۢبَآءِ الرُّسُلِ مَا نُثَبِّتُ بِہٖ فُؤَادَکَ ۚ وَ جَآءَکَ فِیۡ ہٰذِہِ الۡحَقُّ وَ مَوۡعِظَۃٌ وَّ ذِکۡرٰی لِلۡمُؤۡمِنِیۡنَ ﴿۱۲۰﴾', 'اور اے نبی اور پیغمبروں کے وہ سب حالات جو ہم تم سے بیان کرتے ہیں ان سے ہم تمہارے دل کو جمائے رکھتے ہیں اور ان حالات میں تمہارے پاس حق پہنچ گیا اور یہ مومنوں کے لئے نصیحت اور عبرت ہے۔', 'اور سب چیز بیان کرتے ہیں ہم تیرے پاس رسولوں کےاحوال سے جس سے تسلی دیں تیرے دل کو اور آئی تیرے پاس اس سورت میں تحقیق بات اور نصیحت اور یاداشت ایمان والوں کو [۱۶۱]', 'And all that We relate to you (O Muhammad SAW) of the news of the Messengers is in order that We may make strong and firm your heart thereby. And in this (chapter of the Quran) has come to you the truth, as well as an admonition and a reminder for the believers.', 'We narrate to you all such stories from the events of the messengers as We strengthen your heart therewith. And in these (stories) there has come to you the truth, a good counsel and a reminder to those who believe.'),
(1594, 11, 121, 10, 10, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ قُلۡ لِّلَّذِیۡنَ لَا یُؤۡمِنُوۡنَ اعۡمَلُوۡا عَلٰی مَکَانَتِکُمۡ ؕ اِنَّا  عٰمِلُوۡنَ ﴿۱۲۱﴾ۙ', 'اور جو لوگ ایمان نہیں لائے ان سے کہدو کہ تم اپنی جگہ عمل کئے جاؤ ہم اپنی جگہ عمل کئے جاتے ہیں۔', 'اور کہہ دے ان کو جو ایمان نہیں لاتے کام کئے جاؤ اپنی جگہ پر ہم بھی کام کرتے ہیں', 'And say to those who do not believe: \"Act according to your ability and way, We are acting (in our way).', 'Say to those who do not believe, “Do whatever you can. We are doing (what we can).'),
(1595, 11, 122, 10, 10, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ انۡتَظِرُوۡا ۚ اِنَّا مُنۡتَظِرُوۡنَ ﴿۱۲۲﴾', 'اور نتیجہ اعمال کا تم بھی انتظار کرو ہم بھی انتظار کرتے ہیں۔', 'اور انتظار کرو ہم بھی منتظر ہیں [۱۶۲]', 'And you wait ! We (too) are waiting.\"', 'And wait. We too are waiting.”'),
(1596, 11, 123, 10, 10, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'ھود', 'وَ لِلّٰہِ غَیۡبُ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ اِلَیۡہِ یُرۡجَعُ الۡاَمۡرُ کُلُّہٗ  فَاعۡبُدۡہُ وَ تَوَکَّلۡ عَلَیۡہِ ؕ وَ مَا رَبُّکَ بِغَافِلٍ عَمَّا تَعۡمَلُوۡنَ ﴿۱۲۳﴾٪', 'اور آسمانوں اور زمین کی چھپی چیزوں کا علم اللہ ہی کو ہے اور تمام معاملات اسی کی طرف رجوع کئے جائیں گے۔ تو اسی کی عبادت کرو اور اسی پر بھروسہ رکھو۔ اور جو کچھ تم لوگ کر رہے ہو تمہارا پروردگار اس سے بےخبر نہیں۔', 'اور اللہ کے پا س ہے چھپی بات آسمانوں کی اور زمین کی اور اسی کی طرف رجوع ہے سب کام کا سو اسی کی بندگی کر اور اسی پر بھروسہ رکھ اور تیرا رب بیخبر نہیں جو کام تم کرتے ہو [۱۶۳]', 'And to Allah belongs the Ghaib (unseen) of the heavens and the earth, and to Him return all affairs (for decision). So worship Him (O Muhammad SAW) and put your trust in Him. And your Lord is not unaware of what you (people) do.\"', 'To Allah belong the secrets of the heavens and the earth, and to Him the entire matter shall be returned. So worship Him and have trust in Him. Your Lord is not unaware of what you do.'),
(1597, 12, 1, 1, 11, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'الٓرٰ ۟ تِلۡکَ اٰیٰتُ الۡکِتٰبِ الۡمُبِیۡنِ ۟﴿۱﴾', 'الٓرا۔ یہ کتاب روشن کی آیتیں ہیں۔', 'یہ آیتیں ہیں واضح کتاب کی [۱]', 'Alif-Lam-Ra. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings).These are the Verses of the Clear Book (the Quran that makes clear the legal and illegal things, legal laws, a guidance and a blessing).', 'Alif Lām Rā. These are verses of the enlightening Book.'),
(1598, 12, 2, 1, 11, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'اِنَّاۤ اَنۡزَلۡنٰہُ  قُرۡءٰنًا عَرَبِیًّا لَّعَلَّکُمۡ تَعۡقِلُوۡنَ ﴿۲﴾', 'ہم نے اس قرآن کو عربی میں نازل کیا ہے تاکہ تم لوگ سمجھ سکو۔', 'ہم نے اس کو اتارا ہے قرآن عربی زبان کا تاکہ تم سمجھ لو [۲]', 'Verily, We have sent it down as an Arabic Quran in order that you may understand.', 'We have sent it down, as an Arabic Qur’an, so that you may understand.'),
(1599, 12, 3, 1, 11, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'نَحۡنُ نَقُصُّ عَلَیۡکَ اَحۡسَنَ الۡقَصَصِ بِمَاۤ اَوۡحَیۡنَاۤ اِلَیۡکَ ہٰذَا الۡقُرۡاٰنَ ٭ۖ وَ اِنۡ   کُنۡتَ  مِنۡ  قَبۡلِہٖ  لَمِنَ  الۡغٰفِلِیۡنَ ﴿۳﴾', 'اے پیغمبر ہم اس قرآن کے ذریعے سے جو ہم نے تمہاری طرف بھیجا ہے تمہیں ایک نہایت اچھا قصہ سناتے ہیں۔ اور تم اس سے پہلے بےخبر تھے۔', 'ہم بیان کرتے ہیں تیرے پاس بہت اچھا بیان اس واسطے کہ بھیجا ہم نے تیری طرف یہ قرآن اور تو تھا اس سے پہلے البتہ بیخبروں میں [۳]', 'We relate unto you (Muhammad SAW) the best of stories through Our Revelations unto you, of this Quran. And before this (i.e. before the coming of Divine Inspiration to you), you were among those who knew nothing about it (the Quran).', 'By revealing this Qur’an to you, we hereby narrate to you the best narrative, while before this you were among those unaware (of it).'),
(1600, 12, 4, 1, 11, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'اِذۡ  قَالَ یُوۡسُفُ لِاَبِیۡہِ یٰۤاَبَتِ اِنِّیۡ  رَاَیۡتُ اَحَدَعَشَرَ کَوۡکَبًا وَّ الشَّمۡسَ وَ الۡقَمَرَ رَاَیۡتُہُمۡ  لِیۡ  سٰجِدِیۡنَ ﴿۴﴾', 'جب یوسف نے اپنے والد سے کہا کہ ابا میں نے خواب میں گیارہ ستاروں اور سورج اور چاند کو دیکھا ہے۔ دیکھتا کیا ہوں کہ وہ مجھے سجدہ کر رہے ہیں۔', 'جس وقت کہا یوسف نے اپنے باپ سے اے باپ میں نے دیکھا خواب میں گیارہ ستاروں کو اور سورج کو اور چاند کو دیکھا میں نے انکو اپنے واسطے سجدہ کرتے ہوئے [۴]', '(Remember) when Yoosuf (Joseph) said to his father: \"O my father! Verily, I saw (in a dream) eleven stars and the sun and the moon, I saw them prostrating themselves to me.\"', '(It happened) when Yūsuf said to his father, “My father, I saw (in dream) eleven stars and the Sun and the Moon; I saw them all fallen prostrate before me.’’'),
(1601, 12, 5, 1, 11, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'قَالَ یٰبُنَیَّ  لَا تَقۡصُصۡ رُءۡیَاکَ عَلٰۤی اِخۡوَتِکَ فَیَکِیۡدُوۡا لَکَ کَیۡدًا ؕ اِنَّ الشَّیۡطٰنَ  لِلۡاِنۡسَانِ  عَدُوٌّ  مُّبِیۡنٌ ﴿۵﴾', 'انہوں نے کہا کہ بیٹا! اپنے خواب کا ذکر اپنے بھائیوں سے نہ کرنا نہیں تو وہ تمہارے حق میں کوئی چال چلیں گے۔ کچھ شک نہیں کہ شیطان انسان کا کھلا دشمن ہے۔', 'کہا اے بیٹے مت بیان کرنا خواب اپنا اپنے بھائیوں کے آگے پھر وہ بنائیں گے تیرے واسطے کچھ فریب البتہ شیطان ہے انسان کا صریح دشمن [۵]', 'He (the father) said: \"O my son! Relate not your vision to your brothers, lest they arrange a plot against you. Verily! Shaitan (Satan) is to man an open enemy!', 'He said, “My son, do not relate your dream to your brothers, lest they should devise a plan against you. Surely, Satan is an open enemy for mankind.'),
(1602, 12, 6, 1, 11, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ کَذٰلِکَ یَجۡتَبِیۡکَ رَبُّکَ وَ یُعَلِّمُکَ مِنۡ تَاۡوِیۡلِ الۡاَحَادِیۡثِ وَ یُتِمُّ نِعۡمَتَہٗ عَلَیۡکَ وَ عَلٰۤی اٰلِ یَعۡقُوۡبَ کَمَاۤ  اَتَمَّہَا عَلٰۤی  اَبَوَیۡکَ  مِنۡ قَبۡلُ  اِبۡرٰہِیۡمَ وَ  اِسۡحٰقَ ؕ اِنَّ رَبَّکَ عَلِیۡمٌ  حَکِیۡمٌ ٪﴿۶﴾', 'اور اسی طرح اللہ تمہیں برگزیدہ و ممتاز کرے گا اور خواب کی باتوں کی تعبیر کا علم سکھائے گا۔ اور جس طرح اس نے اپنی نعمت پہلے تمہارے دادا پردادا ابراہیم اور اسحٰق پر پوری کی تھی اسی طرح تم پر اور اولاد یعقوب پر پوری کرے گا بیشک تمہارا پروردگار سب کچھ جاننے والا ہے حکمت والا ہے۔', 'اور اسی طرح برگزیدہ کرے گا تجھ کو تیرا رب [۶] اور سکھلائے گا تجھ کو ٹھکانے پر لگانا باتوں کا [۷] اور پورا کرے گا اپنا انعام تجھ پر اور یعقوب کے گھر پر [۸] جیسا پورا کیا ہے تیرے دو باپ دادوں پر اس سے پہلے ابراہیم اور اسحٰق پر [۹] البتہ تیرا رب خبردار ہے حکمت والا [۱۰]', '\"Thus will your Lord choose you and teach you the interpretation of dreams (and other things) and perfect His Favour on you and on the offspring of Yaqoob (Jacob), as He perfected it on your fathers, Ibraheem (Abraham) and Ishaque (Isaac) aforetime! Verily, your Lord is All-Knowing, All-Wise.\"', 'And it will be in this way that your Lord will choose you and teach you the correct interpretation of events, and will perfect His bounty upon you and upon the House of Ya‘qūb, as He has perfected it earlier upon your fore-fathers, Ibrāhīm and IsHāq. Surely, your Lord is All-Wise, All-Knowing.”'),
(1603, 12, 7, 2, 12, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'لَقَدۡ کَانَ فِیۡ یُوۡسُفَ وَ اِخۡوَتِہٖۤ  اٰیٰتٌ لِّلسَّآئِلِیۡنَ ﴿۷﴾', 'ہاں یوسف اور انکے بھائیوں کے قصے میں پوچھنے والوں کے لئے بہت سی نشانیاں ہیں۔', 'البتہ ہیں یوسف کے قصہ میں اور اس کے بھائیوں کے قصہ میں نشانیاں پوچھنے والوں کے لئے [۱۱]', 'Verily, in Yoosuf (Joseph) and his brethren, there were Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) for those who ask.', 'Surely, in (the story of) Yūsuf and his brothers, there are signs for those who ask.'),
(1604, 12, 8, 2, 12, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'اِذۡ قَالُوۡا لَیُوۡسُفُ وَ اَخُوۡہُ  اَحَبُّ اِلٰۤی اَبِیۡنَا مِنَّا وَ نَحۡنُ عُصۡبَۃٌ ؕ اِنَّ اَبَانَا لَفِیۡ ضَلٰلٍ مُّبِیۡنِۣ ۚ﴿ۖ۸﴾', 'جب انہوں نے آپس میں تذکرہ کیا کہ یوسف اور اس کا بھائی ابا کو ہم سے زیادہ پیارے ہیں حالانکہ ہم جماعت کی جماعت ہیں۔ کچھ شک نہیں کہ ابا کھلی غلطی پر ہیں۔', 'جب کہنے لگے البتہ یوسف اور اس کا بھائی زیادہ پیارا ہے ہمارے باپ کو ہم سے اور ہم ان سے قوت والے لوگ ہیں البتہ ہمارا باپ صریح خطا پر ہے [۱۲]', 'When they said: \"Truly, Yoosuf (Joseph) and his brother (Benjamin) are loved more by our father than we, but we are Usbah (a strong group). Really, our father is in a plain error.', '(It happened) when they said, “Yūsuf and his brother are dearer to our father than we are, while we are a whole group. Surely, our father is in clear error.'),
(1605, 12, 9, 2, 12, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'اقۡتُلُوۡا یُوۡسُفَ اَوِ اطۡرَحُوۡہُ  اَرۡضًا یَّخۡلُ لَکُمۡ وَجۡہُ  اَبِیۡکُمۡ وَ تَکُوۡنُوۡا مِنۡۢ  بَعۡدِہٖ  قَوۡمًا  صٰلِحِیۡنَ ﴿۹﴾', 'یوسف کو یا تو جان سے مار ڈالو یا کسی ملک پر پھینک آؤ۔ پھر ابا کی توجہ صرف تمہاری طرف ہو جائے گی اور اسکے بعد تم نیک لوگوں میں ہو جاؤ گے۔', 'مار ڈالو یوسف کو یا پھینک دو کسی ملک میں کہ خالص رہے تم پر توجہ تمہارے باپ کی [۱۳] اور ہو رہنا اس کے بعد نیک لوگ [۱۴]', '\"Kill Yoosuf (Joseph) or cast him out to some (other) land, so that the favour of your father may be given to you alone, and after that you will be righteous folk (by intending repentance before committing the sin).\"', 'Let us kill Yūsuf, or throw him at some place on earth, and thus your father’s full attention will be devoted for you alone, and after doing that, you may become a righteous people.’’'),
(1606, 12, 10, 2, 12, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'قَالَ قَآئِلٌ مِّنۡہُمۡ لَا تَقۡتُلُوۡا یُوۡسُفَ وَ اَلۡقُوۡہُ فِیۡ غَیٰبَتِ الۡجُبِّ یَلۡتَقِطۡہُ بَعۡضُ السَّیَّارَۃِ   اِنۡ  کُنۡتُمۡ  فٰعِلِیۡنَ ﴿۱۰﴾', 'ان میں سے ایک کہنے والے نے کہا کہ یوسف کو جان سے نہ مارو۔ کسی اندھے کنویں میں ڈال دو کہ کوئی راہ گیر اسے نکال کر کسی دوسرے ملک میں لے جائے گا۔ اگر تم کو کرنا ہی ہے تو یوں کرو۔', 'بولا ایک بولنے والا ان میں مت مار ڈالو یوسف کو اور ڈال دو اس کو گمنام کنوئیں میں کہ اٹھالے جائے اس کو کوئی مسافر اگر تم کو کرنا ہے [۱۵]', 'One from among them said: \"Kill not Yoosuf (Joseph), but if you must do something, throw him down to the bottom of a well, he will be picked up by some caravan of travellers.\"', 'One of them said, “Do not kill Yūsuf; rather, cast him into the bottom of a pit, so that some wayfarers may pick him up, if you are going to do something anyway.’’'),
(1607, 12, 11, 2, 12, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'قَالُوۡا یٰۤاَبَانَا مَا لَکَ لَا تَاۡمَنَّا عَلٰی یُوۡسُفَ  وَ  اِنَّا  لَہٗ   لَنٰصِحُوۡنَ ﴿۱۱﴾', 'یہ مشورہ کر کے وہ اپنے والد سے کہنے لگے کہ اباجان کیا سبب ہے کہ آپ یوسف کے بارے میں ہمارا اعتبار نہیں کرتے حالانکہ ہم اسکے خیرخواہ ہیں۔', 'بولے اے باپ کیا بات ہے کہ تو اعتبار نہیں کرتا ہمارا یوسف پر اور ہم تو اسکے خیرا خواہ ہیں [۱۶]', 'They said: \"O our father! Why do you not trust us with Yoosuf (Joseph), - when we are indeed his well-wishers?\"', 'They said (to Ya‘qūb), “Our father, why is it that you do not trust us about Yūsuf, while we are his well-wishers indeed.'),
(1608, 12, 12, 2, 12, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'اَرۡسِلۡہُ  مَعَنَا غَدًا یَّرۡتَعۡ وَ یَلۡعَبۡ وَ  اِنَّا لَہٗ   لَحٰفِظُوۡنَ ﴿۱۲﴾', 'کل اسے ہمارے ساتھ بھیج دیجئے کہ خوب میوے کھائے اور کھیلے کودے ہم اسکے نگہبان ہیں۔', 'بھیج اسکو ہمارےساتھ کل کو خوب کھائے اور کھیلے اور ہم تو اسکے نگہبان ہیں [۱۷]', '\"Send him with us tomorrow to enjoy himself and play, and verily, we will take care of him.\"', 'Send him with us tomorrow, that he may eat and play, and of course, we will remain as guards for him.”'),
(1609, 12, 13, 2, 12, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'قَالَ اِنِّیۡ لَیَحۡزُنُنِیۡۤ  اَنۡ تَذۡہَبُوۡا بِہٖ وَ اَخَافُ اَنۡ یَّاۡکُلَہُ الذِّئۡبُ وَ اَنۡتُمۡ عَنۡہُ غٰفِلُوۡنَ ﴿۱۳﴾', 'انہوں نے کہا کہ یہ امر مجھے غمناک کئے دیتا ہے کہ تم اسے لے جاؤ یعنی وہ مجھ سے جدا ہو جائے اور مجھے یہ خوف بھی ہے کہ تم کھیل میں اس سے غافل ہو جاؤ اور اسے بھیڑیا کھا جائے۔', 'بولا مجھ کو غم ہوتا ہے اس سے کہ تم اس کو لے جاؤ اور ڈرتا ہوں اس سے کہ کھا جائے اسکو بھیڑیا اور تم اس سے بیخبر رہو [۱۸]', 'He (Yaqoob (Jacob)) said: \"Truly, it saddens me that you should take him away. I fear lest a wolf should devour him, while you are careless of him.\"', 'He said, “It makes me sad that you should take him with you, and I fear that some wolf may eat him up when you are heedless of him.”'),
(1610, 12, 14, 2, 12, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'قَالُوۡا  لَئِنۡ  اَکَلَہُ  الذِّئۡبُ وَ نَحۡنُ عُصۡبَۃٌ  اِنَّاۤ   اِذًا  لَّخٰسِرُوۡنَ ﴿۱۴﴾', 'وہ کہنے لگے کہ اگر ہماری موجودگی میں کہ ہم ایک طاقتور جماعت ہیں اسے بھیڑیا کھا گیا تو ہم بڑے نقصان میں پڑ گئے۔', 'بولے اگر کھا گیا اس کو بھیڑیا اور ہم ایک جماعت ہیں وقت ور تو تو ہم نے سب کچھ گنوا دیا [۱۹]', 'They said: \"If a wolf devours him, while we are Usbah (a strong group) (to guard him), then surely, we are the losers.\"', 'They said, “If a wolf eats him up, while we are a whole group, we are then losers indeed.”'),
(1611, 12, 15, 2, 12, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'فَلَمَّا ذَہَبُوۡا بِہٖ  وَ  اَجۡمَعُوۡۤا اَنۡ یَّجۡعَلُوۡہُ  فِیۡ غَیٰبَتِ  الۡجُبِّ ۚ وَ  اَوۡحَیۡنَاۤ  اِلَیۡہِ لَتُنَبِّئَنَّہُمۡ بِاَمۡرِہِمۡ ہٰذَا وَ ہُمۡ لَا یَشۡعُرُوۡنَ ﴿۱۵﴾', 'غرض جب وہ اسکو لے گئے اور اس بات پر اتفاق کر لیا کہ اسکو اندھے کنوئیں میں ڈالدیں اور ہم نے یوسف کی طرف وحی بھیجی کہ ایک وقت ایسا آئے گا کہ تم انہیں انکے اس سلوک سے آگاہ کرو گے اور انکو اس وحی کی کچھ خبر نہ ہو گی۔', 'پھر جب لیکر چلے اس کو اور متفق ہوئے کہ ڈالیں اسکو گمنام کنویں میں اور ہم نے اشارہ کر دیا اسکو کہ تو جتائے گا انکو ان کا یہ کام اور وہ تجھ کو نہ جانیں گے [۲۰]', 'So, when they took him away, they all agreed to throw him down to the bottom of the well, and We inspired in him:\"Indeed, you shall (one day) inform them of this their affair, when they know (you) not.\"', 'So, when they went away with him and were determined to put him in the bottom of a pit, (they did accordingly). And We revealed to him (Yūsuf), “You will (one day) remind them of this deed of theirs, and they will not recognize (you).”'),
(1612, 12, 16, 2, 12, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ جَآءُوۡۤ  اَبَاہُمۡ  عِشَآءً  یَّبۡکُوۡنَ ؕ﴿۱۶﴾', 'اور یہ حرکت کر کے وہ رات کے وقت باپ کے پاس روتے ہوئے آئے۔', 'اور آئے اپنے باپ کے پاس اندھیرا پڑے روتے ہوئے [۲۱]', 'And they came to their father in the early part of the night weeping.', 'And at nightfall, they came to their father weeping.'),
(1613, 12, 17, 2, 12, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'قَالُوۡا یٰۤاَبَانَاۤ  اِنَّا ذَہَبۡنَا نَسۡتَبِقُ وَ تَرَکۡنَا یُوۡسُفَ عِنۡدَ مَتَاعِنَا فَاَکَلَہُ  الذِّئۡبُ ۚ وَ مَاۤ  اَنۡتَ بِمُؤۡمِنٍ لَّنَا وَ لَوۡ کُنَّا صٰدِقِیۡنَ ﴿۱۷﴾', 'کہنے لگے کہ ابا جان ہم تو دوڑنے اور ایک دوسرے سے آگے نکلنے میں مصروف ہو گئے اور یوسف کو اپنے اسباب کے پاس چھوڑ گئے تو اسے بھیڑیا کھا گیا۔ اور آپ ہماری بات کو گو ہم سچ ہی کہتے ہیں باور نہیں کریں گے۔', 'کہنے لگے اے باپ ہم لگے دوڑنے آگے نکلنے کو اور چھوڑا یوسف کو اپنے اسباب کے پاس پھر اس کو کھا گیا بھیڑیا [۲۲] اور تو باور نہ کرے گا ہمارا کہنا اور اگرچہ ہم سچے ہوں [۲۳]', 'They said:\"O our father! We went racing with one another, and left Yoosuf (Joseph) by our belongings and a wolf devoured him; but you will never believe us even when we speak the truth.\"', 'They said, “Father, we went racing with one another, and left Yūsuf with our belongings, and the wolf ate him up. You will never believe us, howsoever truthful we may be.”'),
(1614, 12, 18, 2, 12, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ جَآءُوۡ عَلٰی  قَمِیۡصِہٖ بِدَمٍ  کَذِبٍ ؕ قَالَ بَلۡ سَوَّلَتۡ لَکُمۡ اَنۡفُسُکُمۡ اَمۡرًا ؕ فَصَبۡرٌ  جَمِیۡلٌ ؕ وَ اللّٰہُ  الۡمُسۡتَعَانُ عَلٰی  مَا  تَصِفُوۡنَ ﴿۱۸﴾', 'اور انکے کرتے پر جھوٹ موٹ کا لہو بھی لگا لائے یعقوب نے کہا کہ یوں نہیں ہے بلکہ تم اپنے دل سے یہ بات بنا لائے ہو اچھا صبر کہ وہی خوب ہے اور جو تم بیان کرتے ہو اسکے بارے میں اللہ ہی سے مدد چاہئیے۔', 'اور لائے اس کے کرتے پر لہو لگا کر جھوٹ [۲۴] بولا یہ ہر گز نہیں بلکہ بنا دی ہے تم کو تمہارے جیوں نےایک بات اب صبر ہی بہتر ہے اور اللہ ہی سے مدد مانگتا ہوں اس بات پر جو تم ظاہر کرتے ہو [۲۵]', 'And they brought his shirt stained with false blood. He said: \"Nay, but your ownselves have made up a tale. So (for me) patience is most fitting. And it is Allah (Alone) Whose help can be sought against that which you assert.\"', 'And they came with fake blood on his shirt. He said, “Rather, your inner desires have tempted you to do something. So, patience is best. It is Allah whose help is sought against what you describe.’’'),
(1615, 12, 19, 2, 12, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ جَآءَتۡ سَیَّارَۃٌ  فَاَرۡسَلُوۡا وَارِدَہُمۡ فَاَدۡلٰی دَلۡوَہٗ ؕ قَالَ یٰبُشۡرٰی ہٰذَا غُلٰمٌ ؕ وَ اَسَرُّوۡہُ بِضَاعَۃً ؕ وَ اللّٰہُ عَلِیۡمٌۢ بِمَا یَعۡمَلُوۡنَ ﴿۱۹﴾', 'اور اب اللہ کی شان دیکھو کہ اس کنوئیں کے قریب ایک قافلہ آ وارد ہوا اور انہوں نے پانی کے لئے اپنا سقا بھیجا تو اس نے کنوئیں میں ڈول لٹکایا یوسف اس سے لٹک گئے وہ بولا زہے قسمت یہ تو ایک لڑکا ہے اور اسکو قیمتی سمجھ کر چھپا لیا اور جو کچھ وہ کرتے تھے اللہ کو خوب معلوم تھا۔', 'اور آیا ایک قافلہ پھر بھیجا اپنا پانی بھرنے والا اس نے لٹکایا اپنا ڈول کہنے لگا کیا خوشی کی بات ہے یہ ہے ایک لڑکا [۲۶] اور چھپا لیا اس کو تجارت کا مال سمجھ کر [۲۷] اور اللہ خوب جانتا ہی جو کچھ وہ کرتے ہیں [۲۸]', 'And there came a caravan of travellers; they sent their water-drawer, and he let down his bucket (into the well). He said: \"What good news! Here is a boy.\" So they hid him as merchandise (a slave). And Allah was the All-Knower of what they did.', 'And some wayfarers came (near the pit in which Yūsuf was thrown), and sent their water-drawer (to bring water for them). So, he let down his bucket. He said, “What a good news! Here is a boy.” And they kept him hidden as merchandise, while Allah was aware of what they were doing.'),
(1616, 12, 20, 2, 12, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ شَرَوۡہُ بِثَمَنٍۭ بَخۡسٍ دَرَاہِمَ مَعۡدُوۡدَۃٍ ۚ وَ کَانُوۡا  فِیۡہِ  مِنَ  الزَّاہِدِیۡنَ ﴿٪۲۰﴾', 'اور انہوں نے اسکو تھوڑی سی قیمت یعنی معدودے چند درہموں پر بیچ ڈالا اور وہ اس سے بیزار ہو رہے تھے۔', 'اور بیچ آئے اسکو بھائی ناقص قیمت کو گنتی کی چونیاں [۲۹] اور ہو رہے تھے اس سے بیزار [۳۰]', 'And they sold him for a low price, - for a few Dirhams (i.e. for a few silver coins). And they were of those who regarded him insignificant.', 'And they sold him for a paltry price, for a few silver-coins, and they had not much interest in him.'),
(1617, 12, 21, 3, 13, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ قَالَ الَّذِی اشۡتَرٰىہُ مِنۡ مِّصۡرَ لِامۡرَاَتِہٖۤ  اَکۡرِمِیۡ مَثۡوٰىہُ عَسٰۤی اَنۡ یَّنۡفَعَنَاۤ  اَوۡ نَتَّخِذَہٗ  وَلَدًا ؕ وَ کَذٰلِکَ مَکَّنَّا لِیُوۡسُفَ فِی الۡاَرۡضِ ۫ وَ لِنُعَلِّمَہٗ مِنۡ تَاۡوِیۡلِ الۡاَحَادِیۡثِ ؕ وَ اللّٰہُ غَالِبٌ عَلٰۤی اَمۡرِہٖ وَ لٰکِنَّ اَکۡثَرَ النَّاسِ لَا  یَعۡلَمُوۡنَ ﴿۲۱﴾', 'اور مصر میں جس شخص نے اسکو خریدا اسنے اپنی بیوی سے جس کا نام زلیخا تھا کہا کہ اسکو عزت و اکرام سے رکھو۔ عجب نہیں کہ یہ ہمیں فائدہ دے یا ہم اسے بیٹا بنا لیں اس طرح ہم نے یوسف کو سرزمین مصر میں جگہ دی اور غرض یہ تھی کہ ہم انکو خواب کی باتوں کی تعبیر سکھائیں۔ اور اللہ اپنے کام پر غالب ہے لیکن اکثر لوگ نہیں جانتے۔', 'اور کہا جس شخص نےخرید کیا اسکو مصر سے اپنی عورت کو آبرو سے رکھ اس کو شاید ہمارےکام آئے یا ہم کر لیں اسکو بیٹا [۳۱] اور اسی طرح جگہ دی ہم نے یوسف کو اس ملک میں اور اس واسطے کہ اسکو سکھائیں کچھ ٹھکانے پر بٹھانا باتوں کو [۳۲] اور اللہ در رہتا ہے اپنے کام میں و لیکن اکثر لوگ نہیں جانتے [۳۳]', 'And he (the man) from Egypt who bought him, said to his wife: \"Make his stay comfortable, may be he will profit us or we shall adopt him as a son.\" Thus did We establish Yoosuf (Joseph) in the land, that We might teach him the interpretation of events. And Allah has full power and control over His Affairs, but most of men know not.', 'And the one who bought him from Egypt said to his wife, “Make his stay graceful. He may be useful for us. Or, we may adopt him as a son.” And thus We established Yūsuf in the land, so that We should teach him the interpretation of events. Allah is powerful in (enforcing) His command, but most of the people do not know.'),
(1618, 12, 22, 3, 13, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ لَمَّا بَلَغَ اَشُدَّہٗۤ  اٰتَیۡنٰہُ حُکۡمًا وَّ عِلۡمًا ؕ وَ کَذٰلِکَ نَجۡزِی الۡمُحۡسِنِیۡنَ ﴿۲۲﴾', 'اور جب وہ اپنی جوانی کو پہنچے تو ہم نے انکو دانائی اور علم عطا کیا اور نیکوکاروں کو ہم اسی طرح بدلہ دیا کرتے ہیں۔', 'اور جب پہنچ گیا اپنی قوت کو دیا ہم نے اسکو حکم اور علم [۳۴] اور ایسا ہی بدلہ دیتےہیں ہم نیکی والوں کو [۳۵]', 'And when he (Yoosuf (Joseph)) attained his full manhood, We gave him wisdom and knowledge (the Prophethood), thus We reward the Muhsinoon (doers of good - see V.2:112).', 'And when he reached the prime of his age, We gave him wisdom and knowledge, and this is how We reward those who are good in their deeds.'),
(1619, 12, 23, 3, 13, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ رَاوَدَتۡہُ الَّتِیۡ ہُوَ فِیۡ بَیۡتِہَا عَنۡ نَّفۡسِہٖ  وَ غَلَّقَتِ الۡاَبۡوَابَ وَ قَالَتۡ ہَیۡتَ لَکَ ؕ قَالَ مَعَاذَ اللّٰہِ  اِنَّہٗ  رَبِّیۡۤ  اَحۡسَنَ مَثۡوَایَ ؕ اِنَّہٗ  لَا یُفۡلِحُ الظّٰلِمُوۡنَ ﴿۲۳﴾', 'اور جس عورت کے گھر میں وہ رہتے تھے اس نے انکو اپنی طرف مائل کرنا چاہا اور دروازے بند کر کے کہنے لگی یوسف جلدی آؤ انہوں نے کہا کہ اللہ پناہ میں رکھے وہ یعنی تمہارے میاں تو میرے آقا ہیں انہوں نے مجھے اچھی طرح سے رکھا ہے میں ایسا ظلم نہیں کر سکتا بیشک ظالم لوگ فلاح نہیں پائیں گے۔', 'اور پھسلایا اسکو اس عورت نے جسکے گھر میں تھا اپنا جی تھامنے سے اور بند کردیئے دروازے اور بولی شتابی کر [۳۶] کہا خدا کی پناہ وہ عزیز مالک ہے میرا اچھی طرح رکھا ہے مجھ کو بیشک بھلائی نہیں پاتے جو لوگ کہ بے انصاف ہوں [۳۷]', 'And she, in whose house he was, sought to seduce him (to do an evil act), she closed the doors and said: \"Come on, O you.\" He said: \"I seek refuge in Allah (or Allah forbid)! Truly, he (your husband) is my master! He made my stay agreeable! (So I will never betray him). Verily, the Zalimoon (wrong and evil-doers) will never be successful.\" \n  And she, in whose house he was, sought to seduce him (to do an evil act), she closed the doors and said: \"Come on, O you.\" He said: \"I seek refuge in Allah (or Allah forbid)! Truly, he (your husband) is my master! He made my stay agreeable! (So I will never betray him). Verily, the Zalimoon (wrong and evil-doers) will never be successful.\"', 'And she, in whose house he was, seduced him towards herself, and bolted the doors, and said, “come on!” He said, “I seek refuge with Allah. Surely, he (your husband) is my master. He has given me a good lodging. Indeed, the wrongdoers do not prosper.”'),
(1620, 12, 24, 3, 13, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ لَقَدۡ ہَمَّتۡ بِہٖ ۚ وَ ہَمَّ بِہَا لَوۡ لَاۤ  اَنۡ رَّاٰ بُرۡہَانَ رَبِّہٖ ؕ کَذٰلِکَ لِنَصۡرِفَ عَنۡہُ السُّوۡٓءَ  وَ الۡفَحۡشَآءَ ؕ اِنَّہٗ  مِنۡ  عِبَادِنَا الۡمُخۡلَصِیۡنَ ﴿۲۴﴾', 'اور اس عورت نے ان کا قصد کیا اور انہوں نے اس کا قصد کیا اگر وہ اپنے پروردگار کی نشانی نہ دیکھتے تو جو ہوتا سو ہوتا۔ یوں اس لئے کیا گیا کہ ہم ان سے برائی اور بےحیائی کو روک دیں۔ بیشک وہ ہمارے چنے ہوئے بندوں میں سے تھے۔', 'اور البتہ عوت نے فکر کیا اس کا اور اس نے فکر کیا عورت کا [۳۸] اگر نہ ہوتا یہ کہ دیکھے قدرت اپنے رب کی [۳۹] یوں ہی ہوا تاکہ ہٹائیں ہم اس سے برائی اور بے حیائی البتہ وہ ہے ہمارے برگزیدہ بندوں میں [۴۰]', 'And indeed she did desire him and he would have inclined to her desire, had he not seen the evidence of his Lord. Thus it was, that We might turn away from him evil and illegal sexual intercourse. Surely, he was one of Our chosen, guided slaves.', 'She certainly desired him, and he might have desired her, had he not seen the proof from his Lord. Thus We did, to turn evil and lewdness away from him. Surely, he was one of Our chosen servants.'),
(1621, 12, 25, 3, 13, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ اسۡتَبَقَا الۡبَابَ وَ قَدَّتۡ قَمِیۡصَہٗ مِنۡ دُبُرٍ وَّ اَلۡفَیَا سَیِّدَہَا لَدَا الۡبَابِ ؕ قَالَتۡ مَا جَزَآءُ مَنۡ اَرَادَ بِاَہۡلِکَ سُوۡٓءًا اِلَّاۤ  اَنۡ یُّسۡجَنَ اَوۡ عَذَابٌ اَلِیۡمٌ ﴿۲۵﴾', 'اور دونوں دروازے کی طرف بھاگے آگے یوسف پیچھے زلیخا اور عورت نے ان کا کرتہ پیچھے سے پکڑ کو جو کھینچا تو پھاڑ ڈالا اور دونوں کو دروازے کے پاس عورت کا خاوند مل گیا تو عورت بولی کہ جو شخص تمہاری بیوی کے ساتھ برا ارادہ کرے اسکی اسکے سوا کیا سزا ہے کہ یا تو قید کیا جائے یا اسے دکھ کا عذاب دیا جائے۔', 'اور دونوں دوڑے دروازہ کو اور عورت نے چیر ڈالا اس کا کرتہ پیچھے سے اور دونوں مل گئے عورت کے خاوند سے دروازہ کے پاس [۴۱] بولی اور کچھ سزا نہیں ایسے شخص کی جو چاہے تیرے گھر میں برائی مگر یہی کہ قید میں ڈالا جائے یا عذاب دردناک [۴۲]', 'So they raced with one another to the door, and she tore his shirt from the back. They both found her lord (i.e. her husband) at the door. She said: \"What is the recompense (punishment) for him who intended an evil design against your wife, except that he be put in prison or a painful torment?\"', 'They raced towards the door, and she ripped his shirt from behind, and they found her master by the door. She said, “What could be the punishment of him who intended evil with your wife, except that he be imprisoned or (given) a painful chastisement?”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1622, 12, 26, 3, 13, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'قَالَ ہِیَ رَاوَدَتۡنِیۡ عَنۡ نَّفۡسِیۡ وَ شَہِدَ شَاہِدٌ مِّنۡ اَہۡلِہَا ۚ اِنۡ کَانَ قَمِیۡصُہٗ  قُدَّ مِنۡ قُبُلٍ فَصَدَقَتۡ وَ ہُوَ مِنَ الۡکٰذِبِیۡنَ ﴿۲۶﴾', 'یوسف نے کہا اسی نے مجھ کو اپنی طرف مائل کرنا چاہا تھا اور اسکے خاندان میں سے ایک گواہ نے گواہی دی  کہ اگر اس کا کرتا آگے سے پھٹا ہو تو یہ سچی اور یوسف جھوٹا ہے۔', 'یوسف بولا اسی نے خواہش کی مجھ سے کہ نہ تھاموں اپنے جی کو اور گواہی دی ایک گواہ نے عورت کے لوگوں میں سے [۴۳] اگر ہے کرتا اس کا پھٹا آگے سے تو عورت سچی ہے اور وہ ہے جھوٹا', 'He (Yoosuf (Joseph)) said: \"It was she that sought to seduce me,\" - and a witness of her household bore witness (saying): \"If it be that his shirt is torn from the front, then her tale is true and he is a liar!', 'He (Yūsuf) said, “It was she who tried to seduce me.” And a witness from her family observed that if his shirt was ripped from the front side, then she is true and he is a liar;'),
(1623, 12, 27, 3, 13, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ  اِنۡ  کَانَ  قَمِیۡصُہٗ  قُدَّ مِنۡ دُبُرٍ فَکَذَبَتۡ  وَ ہُوَ  مِنَ  الصّٰدِقِیۡنَ ﴿۲۷﴾', 'اور اگر کرتا پیچھے سے پھٹا ہو تو یہ جھوٹی اور وہ سچا ہے۔', 'اور اگر ہے کرتہ اس کا پھٹا پیچھے سے تو یہ جھوٹی ہے اور وہ سچا ہے', '\"But if it be that his shirt is torn from the back, then she has told a lie and he is speaking the truth!\"', 'and if his shirt was ripped from behind, then she is telling a lie and he is truthful.'),
(1624, 12, 28, 3, 13, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'فَلَمَّا رَاٰ  قَمِیۡصَہٗ  قُدَّ مِنۡ دُبُرٍ قَالَ  اِنَّہٗ مِنۡ  کَیۡدِکُنَّ ؕ اِنَّ  کَیۡدَکُنَّ  عَظِیۡمٌ ﴿۲۸﴾', 'سو جب اس کا کرتہ دیکھا تو پیچھے سے پھٹا تھا تب اس نے زلیخا سے کہا کہ یہ تمہارا ہی فریب ہے۔ اور کچھ شک نہیں کہ تم عورتوں کے فریب بڑے بھاری ہوتے ہیں۔', 'پھر جب دیکھا عزیز نے کرتہ اس کا پھٹا ہوا پیچھے سے کہا بیشک یہ ایک فریب ہے تم عورتوں کا البتہ تمہارا فریب بڑا ہے', 'So when he (her husband) saw his ((Yoosufs (Joseph)) shirt torn at the back; (her husband) said: \"Surely, it is a plot of you women! Certainly mighty is your plot!', 'So, when he (her husband) saw his shirt ripped from behind, he said, “This is certainly your trickery, O women. Great is the trickery of you women indeed.'),
(1625, 12, 29, 3, 13, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'یُوۡسُفُ اَعۡرِضۡ عَنۡ ہٰذَا ٜ وَ اسۡتَغۡفِرِیۡ  لِذَنۡۢبِکِ ۚۖ اِنَّکِ  کُنۡتِ مِنَ الۡخٰطِئِیۡنَ ﴿٪۲۹﴾', 'یوسف! اس بات کا خیال نہ کر۔ اور زلیخا تو اپنے گناہوں کی بخشش مانگ۔ بیشک خطا تیری ہی ہے۔', 'یوسف جانے دے اس ذکر کو اور عورت تو بخشوا اپنا گناہ بیشک تو ہی گنہگار تھی [۴۴]', '\"O Yoosuf (Joseph)! Turn away from this! (O woman!) Ask forgiveness for your sin. Verily, you were of the sinful.\"', 'O Yūsuf, ignore this matter, and you (O woman,) seek forgiveness for your sin, for you were guilty infact.”'),
(1626, 12, 30, 4, 14, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ قَالَ نِسۡوَۃٌ  فِی الۡمَدِیۡنَۃِ  امۡرَاَتُ الۡعَزِیۡزِ  تُرَاوِدُ  فَتٰىہَا عَنۡ  نَّفۡسِہٖ ۚ قَدۡ شَغَفَہَا حُبًّا ؕ اِنَّا لَنَرٰىہَا فِیۡ ضَلٰلٍ مُّبِیۡنٍ ﴿۳۰﴾', 'اور شہر میں عورتیں گفتگوئیں کرنے لگیں کہ عزیز کی بیوی اپنے غلام کو اپنی طرف مائل کرنا چاہتی ہے اور اسکی محبت اسکے دل میں گھر کر گئ ہے۔ ہم دیکھتی ہیں کہ وہ کھلی گمراہی میں ہے۔', 'اور کہنے لگیں عورتیں اس شہر میں عزیز کی عورت خواہش کرتی ہے اپنے غلام سے اسکے جی کو فریفتہ ہو گیا اس کا دل اسکی محبت میں ہم تو دیکھتے ہیں اسکو صریح خطا پر [۴۵]', 'And women in the city said: \"The wife of Al-Azeez is seeking to seduce her (slave) young man, indeed she loves him violently; verily we see her in plain error.\"', 'And women in the city said, “The wife of the minister is seducing her youthful slave. His love has entered the depth of her heart. Surely, we see her in open error.”'),
(1627, 12, 31, 4, 14, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'فَلَمَّا سَمِعَتۡ بِمَکۡرِہِنَّ  اَرۡسَلَتۡ اِلَیۡہِنَّ وَ اَعۡتَدَتۡ لَہُنَّ مُتَّکَاً  وَّ اٰتَتۡ کُلَّ وَاحِدَۃٍ  مِّنۡہُنَّ سِکِّیۡنًا وَّ قَالَتِ اخۡرُجۡ عَلَیۡہِنَّ ۚ فَلَمَّا رَاَیۡنَہٗۤ  اَکۡبَرۡنَہٗ وَ قَطَّعۡنَ اَیۡدِیَہُنَّ وَ قُلۡنَ حَاشَ لِلّٰہِ مَا ہٰذَا بَشَرًا ؕ اِنۡ  ہٰذَاۤ  اِلَّا مَلَکٌ  کَرِیۡمٌ ﴿۳۱﴾', 'پھر جب زلیخا نے ان عورتوں کی گفتگو جو حقیقت میں دیدار یوسف کے لئے ایک چال تھی سنی تو انکے پاس دعوت کا پیغام بھیجا اور انکے لئے ایک محفل مرتب کی۔ اور پھل تراشنے کے لئے ہر ایک کو ایک ایک چھری دی اور یوسف سے کہا کہ انکے سامنے آؤ۔ جب عورتوں نے انکو دیکھا تو انکا رعب حسن ان پر ایسا چھا گیا کہ پھل تراشتے تراشتے اپنے ہاتھ کاٹ لئے اور بیساختہ بول اٹھیں کہ اللہ پاک ہے یہ آدمی نہیں یہ تو کوئی بزرگ فرشتہ ہے۔', 'پھر جب سنا اس نے ان کا فریب [۴۶] بلوا بھیجا انکو اور تیار کی انکے واسطے ایک مجلس اور دی انکو ہر ایک کے ہاتھ میں ایک چھری اور بولی یوسف نکل آ انکے سامنے پھر جب دیکھا اس کو ششدر رہ گئیں اور کاٹ ڈالے اپنے ہاتھ [۴۷] اور کہنے لگیں حاشا للہ نہیں یہ شخص آدمی یہ تو کوئی فرشتہ ہے بزرگ [۴۸]', 'So when she heard of their accusation, she sent for them and prepared a banquet for them; she gave each one of them a knife (to cut the foodstuff with), and she said ((to Yoosuf (Joseph)): \"Come out before them.\" Then, when they saw him, they exalted him (at his beauty) and (in their astonishment) cut their hands. They said: \"How perfect is Allah (or Allah forbid)! No man is this! This is none other than a noble angel!\"', 'So, when she heard of their taunting comments, she extended an invitation to them and arranged for them a comfortable place (to sit and dine) and gave everyone a knife, and said (to Yūsuf): “come out to them.” So when they saw him, they found him great, and (were so stunned that they) cut their hands and said, “Oh God! He is no human being. He is but a noble angel.”'),
(1628, 12, 32, 4, 14, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'قَالَتۡ فَذٰلِکُنَّ الَّذِیۡ لُمۡتُنَّنِیۡ فِیۡہِ ؕ وَ لَقَدۡ رَاوَدۡتُّہٗ عَنۡ نَّفۡسِہٖ فَاسۡتَعۡصَمَ ؕ وَ لَئِنۡ لَّمۡ  یَفۡعَلۡ  مَاۤ  اٰمُرُہٗ   لَیُسۡجَنَنَّ وَ لَیَکُوۡنًا مِّنَ  الصّٰغِرِیۡنَ ﴿۳۲﴾', 'زلیخا نے کہا تو یہ وہی ہے جسکے بارے میں تم مجھے طعنے دیتی تھیں اور بیشک میں نے اسکو اپنی طرف مائل کرنا چاہا مگر یہ بچا رہا اور اگر یہ وہ کام نہ کرے گا جو میں اسے کہتی ہوں تو قید کر دیا جائے گا اور ذلیل ہو گا۔', 'بولی یہ وہی ہے کہ طعنہ دیا تھا تم نے مجھ کو اسکے واسطے [۴۹] اور میں نے لینا چاہا تھا اس سے اس کا جی پھر اس نے تھام رکھا [۵۰] اور بیشک اگر نہ کرے گا جو میں اسکو کہتی ہوں تو قید میں پڑے گا اور ہو گا بےعزت [۵۱]', 'She said: \"This is he (the young man) about whom you did blame me (for his love), and I did seek to seduce him, but he refused. And now if he refuses to obey my order, he shall certainly be cast into prison, and will be one of those who are disgraced.\"', 'She said, “This is the one about whom you reproached me. Yes, I seduced him, but he abstained. And should he not follow my command, he shall be imprisoned and will be disgraced.”'),
(1629, 12, 33, 4, 14, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'قَالَ رَبِّ السِّجۡنُ اَحَبُّ اِلَیَّ مِمَّا یَدۡعُوۡنَنِیۡۤ  اِلَیۡہِ ۚ وَ اِلَّا تَصۡرِفۡ عَنِّیۡ کَیۡدَہُنَّ اَصۡبُ  اِلَیۡہِنَّ وَ اَکُنۡ مِّنَ الۡجٰہِلِیۡنَ ﴿۳۳﴾', 'یوسف نے دعا کی کہ پروردگار جس کام کی طرف یہ مجھے بلا تی ہیں اسکی نسبت مجھے قید پسند ہے۔ اور اگر تو مجھ سے انکے فریب کو نہ ہٹائے گا تو میں انکی طرف مائل ہو جاؤں گا اور نادانوں میں سے ہو جاؤں گا۔', 'یوسف بولا اے رب مجھ کو قید پسند ہے اس بات سے جسکی طرف مجھ کو بلاتی ہیں اور اگر تو نہ دفع کرے گا مجھ سے ان کا فریب تو مائل ہو جاؤں گا انکی طرف اور ہو جاؤں گا بے عقل [۵۲]', 'He said:\"O my Lord! Prison is more to my liking than that to which they invite me. Unless You turn away their plot from me, I will feel inclined towards them and be one (of those who commit sin and deserve blame or those who do deeds) of the ignorants.\"', 'He (Yūsuf) said, “My Lord, the prison is dearer to me than what these women invite me to do. If You do not turn their guile away from me, I shall get inclined towards them and shall be among the ignorant.”'),
(1630, 12, 34, 4, 14, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'فَاسۡتَجَابَ لَہٗ  رَبُّہٗ  فَصَرَفَ عَنۡہُ کَیۡدَہُنَّ ؕ اِنَّہٗ  ہُوَ السَّمِیۡعُ الۡعَلِیۡمُ ﴿۳۴﴾', 'پس انکے رب نے انکی دعا قبول کر لی اور ان سے عورتوں کا داؤ ٹال دیا۔ بیشک وہی تو سننے والا ہے جاننے والا ہے۔', 'سو قبول کر لی اس کی دعا اس کے رب نے پھر دفع کیا اس سے ان کا فریب [۵۳] البتہ وہی ہے سننے والا خبردار [۵۴]', 'So his Lord answered his invocation and turned away from him their plot. Verily, He is the All-Hearer, the All-Knower.', 'So, his Lord accepted his prayer and turned their guile away from him. Surely, He is the All-Hearing, the All-Knowing.'),
(1631, 12, 35, 4, 14, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'ثُمَّ بَدَا لَہُمۡ مِّنۡۢ بَعۡدِ مَا رَاَوُا الۡاٰیٰتِ لَیَسۡجُنُنَّہٗ حَتّٰی حِیۡنٍ ﴿٪۳۵﴾', 'پھر باوجود اسکے کہ وہ لوگ انکی بیگناہی کے نشان دیکھ چکے تھے۔ انکی رائے یہی ٹھہری کہ کچھ عرصے کے لئے ان کو قید ہی کر دیں۔', 'پھر یوں سمجھ آیا لوگوں کی ان نشانیوں کے دیکھنے پر کہ قید رکھیں اسکو ایک مدت [۵۵]', 'Then it appeared to them, after they had seen the proofs (of his innocence) to imprison him for a time.', 'Later on, even after having seen the clear signs (of his innocence), they deemed it proper to imprison him for some time.'),
(1632, 12, 36, 5, 15, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ دَخَلَ مَعَہُ السِّجۡنَ فَتَیٰنِ ؕ قَالَ اَحَدُہُمَاۤ  اِنِّیۡۤ  اَرٰىنِیۡۤ  اَعۡصِرُ خَمۡرًا ۚ وَ قَالَ الۡاٰخَرُ اِنِّیۡۤ  اَرٰىنِیۡۤ  اَحۡمِلُ فَوۡقَ رَاۡسِیۡ خُبۡزًا تَاۡکُلُ الطَّیۡرُ مِنۡہُ ؕ نَبِّئۡنَا بِتَاۡوِیۡلِہٖ ۚ اِنَّا نَرٰىکَ مِنَ الۡمُحۡسِنِیۡنَ ﴿۳۶﴾', 'اور انکے ساتھ دو اور جوان بھی داخل زنداں ہوئے ایک نے ان میں سے کہا کہ میں نے خواب دیکھا ہے دیکھتا کیا ہوں کہ شراب کے لئے انگور نچوڑ رہا ہوں دوسرے نے کہا کہ میں نے بھی خواب دیکھا ہے میں یہ دیکھتا ہوں کہ اپنے سر پر روٹیاں اٹھائے ہوئے ہوں اور پرندے ان میں سے کھا رہے ہیں تو ہمیں انکی تعبیر بتا دیجئے کہ ہم تمہیں نیکوکار دیکھتے ہیں۔', 'اور داخل ہوئے قید خانہ میں اسکے ساتھ دو جوان کہنے لگا ان میں سے ایک میں دیکھتا ہوں کہ میں نچوڑتا ہوں شراب اور دوسرے نے کہا میں دیکھتا ہوں کہ اٹھار رہا ہوں اپنے سر پر روٹی کہ جانور کھاتے ہیں اس میں سے بتلا ہم کو اس کی تعبیر ہم دیکھتے ہیں تجھ کو نیکی والا [۵۶]', 'And there entered with him two young men in the prison. One of them said: \"Verily, I saw myself (in a dream) pressing wine.\" The other said: \"Verily, I saw myself (in a dream) carrying bread on my head and birds were eating thereof.\" (They said): \"Inform us of the interpretation of this. Verily, we think you are one of the Muhsinoon (doers of good - see V.2:112).\"', 'And two men entered the prison with him. One of them said, “I have seen myself (in dream) pressing wine.” And the other said, “I saw myself carrying bread on my head of which the birds were eating. Let us know its interpretation. We see you are a man of good deeds.”'),
(1633, 12, 37, 5, 15, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'قَالَ لَا یَاۡتِیۡکُمَا طَعَامٌ تُرۡزَقٰنِہٖۤ  اِلَّا نَبَّاۡتُکُمَا بِتَاۡوِیۡلِہٖ  قَبۡلَ اَنۡ یَّاۡتِیَکُمَا ؕ ذٰلِکُمَا مِمَّا عَلَّمَنِیۡ رَبِّیۡ ؕ اِنِّیۡ تَرَکۡتُ مِلَّۃَ  قَوۡمٍ لَّا یُؤۡمِنُوۡنَ بِاللّٰہِ  وَ ہُمۡ  بِالۡاٰخِرَۃِ  ہُمۡ  کٰفِرُوۡنَ ﴿۳۷﴾', 'یوسف نے کہا کہ جو کھانا تم کو ملنے والا ہے وہ آنے نہیں پائے گا کہ میں اس سے پہلے تم کو اس کی تعبیر بتا دوں گا۔ یہ ان باتوں میں سے ہے جو میرے پروردگار نے مجھے سکھائی ہیں جو لوگ اللہ پر ایمان نہیں لاتے اور آخرت کا انکار کرتے ہیں میں نے انکا مذہب چھوڑ دیا ہے۔', 'بولا نہ آنے پائے گا تم کو کھانا جو ہر روز تم کو ملتا ہے مگر بتا چکوں گا تم کو اس کی تعبیر اس کے آنے سے پہلے یہ علم ہے کہ مجھ کو سکھایا میرے رب نے میں نے چھوڑا دین اس قوم کا کہ ایمان نہیں لاتے اللہ پر اور آخرت سے وہ لوگ منکر ہیں [۵۷]', 'He said: \"No food will come to you (in wakefulness or in dream) as your provision, but I will inform (in wakefulness) its interpretation before it (the food) comes. This is of that which my Lord has taught me. Verily, I have abandoned the religion of a people that believe not in Allah and are disbelievers in the Hereafter (i.e. the Kananioon of Egypt who were polytheists and used to worship sun and other false deities).', 'He said, “No food provided for you shall come to you, but I can give you its description before it comes to you. This is the knowledge my Lord has given to me. I have abandoned the way of those who do not believe in Allah, and who are deniers of the Hereafter,'),
(1634, 12, 38, 5, 15, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ اتَّبَعۡتُ مِلَّۃَ  اٰبَآءِیۡۤ   اِبۡرٰہِیۡمَ  وَ اِسۡحٰقَ وَ یَعۡقُوۡبَ ؕ مَا کَانَ لَنَاۤ  اَنۡ نُّشۡرِکَ بِاللّٰہِ  مِنۡ  شَیۡءٍ ؕ ذٰلِکَ مِنۡ فَضۡلِ اللّٰہِ عَلَیۡنَا وَ عَلَی النَّاسِ وَ لٰکِنَّ اَکۡثَرَ  النَّاسِ لَا  یَشۡکُرُوۡنَ ﴿۳۸﴾', 'اور میں اپنے باپ دادا ابراہیم اور اسحٰق اور یعقوب کے مذہب پر چلتا ہوں۔ ہمیں شایاں نہیں ہے کہ کسی چیز کو اللہ کے ساتھ شریک بنائیں یہ اللہ کا فضل ہے ہم پر بھی اور لوگوں پر بھی۔ لیکن اکثر لوگ شکر نہیں کرتے۔', 'اور پکڑا میں نے دین اپنے باپ دادوں کا ابراہیم اور اسحاق اور یعقوب کا ہمارا کام نہیں کہ شریک کریں اللہ کا کسی چیز کو یہ فضل ہے اللہ کا ہم پر اور سب لوگوں پر لیکن بہت لوگ احسان نہیں مانتے [۵۸]', '\"And I have followed the religion of my fathers, - Ibraheem (Abraham), Ishaque (Isaac) and Yaqoob (Jacob) (ã ), and never could we attribute any partners whatsoever to Allah. This is from the Grace of Allah to us and to mankind, but most men thank not (i.e. they neither believe in Allah, nor worship Him).', 'and I have followed the way of my fathers, Ibrāhīm, IsHāq and Ya‘qūb. It is not for us that we associate any partners with Allah. All this is a part of the favor Allah has bestowed upon us and upon the people, but most of the people are not grateful.'),
(1635, 12, 39, 5, 15, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'یٰصَاحِبَیِ السِّجۡنِ ءَاَرۡبَابٌ مُّتَفَرِّقُوۡنَ خَیۡرٌ  اَمِ  اللّٰہُ   الۡوَاحِدُ  الۡقَہَّارُ ﴿ؕ۳۹﴾', 'اے میرے قیدخانے کے رفیقو! بھلا کئی جدا جدا آقا اچھے یا اللہ جو اکیلا ہے سب پر غالب ہے؟', 'اے رفیقو قید خانہ کے بھلا کئی معبود جدا جدا بہتر یا اللہ اکیلا زبردست [۵۹]', '\"O two companions of the prison! Are many different lords (gods) better or Allah, the One, the Irresistible?', 'O my fellow prisoners, are different gods better or Allah, the One, the All-Dominant?'),
(1636, 12, 40, 5, 15, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'مَا تَعۡبُدُوۡنَ مِنۡ دُوۡنِہٖۤ  اِلَّاۤ  اَسۡمَآءً سَمَّیۡتُمُوۡہَاۤ  اَنۡتُمۡ وَ اٰبَآؤُکُمۡ مَّاۤ اَنۡزَلَ اللّٰہُ  بِہَا مِنۡ سُلۡطٰنٍ ؕ اِنِ الۡحُکۡمُ  اِلَّا لِلّٰہِ ؕ اَمَرَ اَلَّا تَعۡبُدُوۡۤا اِلَّاۤ اِیَّاہُ ؕ ذٰلِکَ الدِّیۡنُ الۡقَیِّمُ  وَ لٰکِنَّ  اَکۡثَرَ  النَّاسِ لَا  یَعۡلَمُوۡنَ ﴿۴۰﴾', 'جن چیزوں کی تم اللہ کے سوا پرستش کرتے ہو وہ صرف نام ہی نام ہیں۔ جو تم نے اور تمہارے باپ دادا نے رکھ لئے ہیں۔ اللہ نے انکی کوئی سند نازل نہیں کی سن رکھو کہ اللہ کے سوا کسی کی حکومت نہیں ہے اس نے ارشاد فرمایا ہے کہ اسکے سوا کسی کی عبادت نہ کرو یہی سیدھا دین ہے لیکن اکثر لوگ نہیں جانتے۔', 'کچھ نہیں پوجتے ہو سوائے اس کے مگر نام ہیں جو رکھ لئے ہیں تم نے اور تمہارے باپ دادوں نے نہیں اتاری اللہ نے ان کی کوئی سند [۶۰] حکومت نہیں ہے کسی کی سوائے اللہ کے اس نے فرما دیا کہ نہ پوجو مگر اسی کو [۶۱] یہی ہے راستہ سیدھا پر بہت لوگ نہیں جانتے [۶۲]', '\"You do not worship besides Him but only names which you have named (forged), you and your fathers, for which Allah has sent down no authority. The command (or the judgement) is for none but Allah. He has commanded that you worship none but Him (i.e. His Monotheism), that is the (true) straight religion, but most men know not.', 'Whatever you worship, other than Him, are nothing but names you have coined, you and your fathers. Allah has sent down no authority for them. Sovereignty belongs to none but Allah. He has ordained that you shall not worship anyone but Him. This is the only right path. But most of the people do not know.”'),
(1637, 12, 41, 5, 15, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'یٰصَاحِبَیِ السِّجۡنِ اَمَّاۤ  اَحَدُ کُمَا فَیَسۡقِیۡ رَبَّہٗ خَمۡرًا ۚ وَ اَمَّا الۡاٰخَرُ فَیُصۡلَبُ فَتَاۡکُلُ الطَّیۡرُ مِنۡ رَّاۡسِہٖ ؕ قُضِیَ الۡاَمۡرُ  الَّذِیۡ  فِیۡہِ تَسۡتَفۡتِیٰنِ ﴿ؕ۴۱﴾', 'اے میرے قید خانے کے رفیقو تم میں سے ایک جو پہلا خواب بیان کرنے والا ہے وہ تو اپنے آقا کو شراب پلایا کرے گا۔ اور جو دوسرا ہے وہ سولی دیا جائے گا اور پرندے اس کا سر نوچیں گے۔ جو بات تم مجھ سے پوچھتے تھے وہ فیصل ہو چکی ہے۔', 'اے رفیقو قید خانہ کے ایک جو ہے تم دونوں میں سو پلائے گا اپنے خاوند (مالک) کو شراب اور دوسرا جو ہے سو سولی دیا جائے گا  (چڑھے گا) پھر کھائیں گے جانور اس کے سر میں سے فیصل ہوا وہ کام جس کی تحقیق تم چاہتے تھے [۶۳]', '\"O two companions of the prison! As for one of you, he (as a servant) will pour out wine for his lord (king or master) to drink; and as for the other, he will be crucified and birds will eat from his head. Thus is the case judged concerning which you both did inquire.\"', '“O my fellow prisoners, one of you will serve wine to his master, while the other will be crucified and birds will eat from his head. Destined is the matter you are asking about.”'),
(1638, 12, 42, 5, 15, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ قَالَ لِلَّذِیۡ ظَنَّ اَنَّہٗ نَاجٍ مِّنۡہُمَا اذۡکُرۡنِیۡ عِنۡدَ رَبِّکَ ۫ فَاَنۡسٰہُ الشَّیۡطٰنُ ذِکۡرَ رَبِّہٖ فَلَبِثَ فِی السِّجۡنِ بِضۡعَ سِنِیۡنَ ﴿ؕ٪۴۲﴾', 'اور ان دونوں  میں سے جس کی نسبت یوسف نے خیال کیا کہ وہ رہائی پا جائے گا اس سے کہا کہ اپنے آقا سے میرا ذکر بھی کر دینا۔ پھر شیطان نے اسے ان کا اپنے آقا سے ذکر کرنا بھلا دیا اور یوسف کئ برس قید خانے ہی میں رہے۔', 'اور کہہ دیا یوسف نے اسکو جسکو گمان کیا تھا کہ بچے گا ان دونوں میں میرا ذکر کرنا اپنے خاوند (مالک) کے پاس [۶۴] سو بھلا دیا اسکو شیطان نے ذکر کرنا اپنے خاوند (مالک) سے پھر رہا قید میں کئ برس [۶۵]', 'And he said to the one whom he knew to be saved: \"Mention me to your lord (i.e. your king, so as to get me out of the prison).\" But Shaitan (Satan) made him forget to mention it to his Lord (or Satan made ((Yoosuf (Joseph)) to forget the remembrance of his Lord (Allah) as to ask for His Help, instead of others). So (Yoosuf (Joseph)) stayed in prison a few (more) years.', 'And he (Yūsuf) said to the one whom he believed likely to be released out of the two, “Tell your master about me.” Then, the Satan made him forget to tell his master. So, he (Yūsuf) remained in prison for a few years.'),
(1639, 12, 43, 6, 16, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ قَالَ الۡمَلِکُ اِنِّیۡۤ  اَرٰی سَبۡعَ بَقَرٰتٍ سِمَانٍ یَّاۡکُلُہُنَّ سَبۡعٌ عِجَافٌ وَّ سَبۡعَ سُنۡۢبُلٰتٍ خُضۡرٍ وَّ اُخَرَ  یٰبِسٰتٍ ؕ یٰۤاَیُّہَا الۡمَلَاُ  اَفۡتُوۡنِیۡ فِیۡ رُءۡیَایَ اِنۡ کُنۡتُمۡ لِلرُّءۡیَا تَعۡبُرُوۡنَ ﴿۴۳﴾', 'اور بادشاہ نے کہا کہ میں نے خواب دیکھا ہے دیکھتا کیا ہوں کہ سات موٹی گائیں ہیں جنکو سات دبلی گائیں کھا رہی ہیں۔ اور سات خوشے سبز ہیں اور سات خشک۔ اے درباریو اگر تم خوابوں کی تعبیر دے سکتے ہو تو مجھے میرے خواب کی تعبیر بتاؤ۔', 'اور کہا بادشاہ نے میں خواب میں دیکھتا ہوں سات گائیں موٹی انکو کھاتی ہیں سات گائیں دبلی اور سات بالیں ہری اور دوسری سوکھی [۶۶] اے دربار والو تعبیر کہو مجھ سے میرے خواب کی اگر ہو تم خواب کی تعبیر دینے والے [۶۷]', 'And the king (of Egypt) said: \"Verily, I saw (in a dream) seven fat cows, whom seven lean ones were devouring - and of seven green ears of corn, and (seven) others dry. O notables! Explain to me my dream, if it be that you can interpret dreams.\"', 'And (one day) the king said (to his courtiers), “I have seen (in a dream) seven fat cows being eaten by seven lean ones, and seven ears of grain which are green and (seven) others which are dry. O people, tell me about my dream, if you can interpret dreams.”'),
(1640, 12, 44, 6, 16, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'قَالُوۡۤا اَضۡغَاثُ اَحۡلَامٍ ۚ وَ مَا نَحۡنُ بِتَاۡوِیۡلِ  الۡاَحۡلَامِ  بِعٰلِمِیۡنَ ﴿۴۴﴾', 'انہوں نے کہا یہ خواب تو پریشان خیالی سے ہیں اور ہمیں ایسے خوابوں کی تعبیر نہیں آتی۔', 'بولے یہ خیالی خواب ہیں اور ہم کو ایسے خوابوں کی تعبیر معلوم نہیں [۶۸]', 'They said: \"Mixed up false dreams and we are not skilled in the interpretation of dreams.\"', 'They said, “(It seems to be) a mishmash of dreams, and we do not know the interpretation of dreams.”'),
(1641, 12, 45, 6, 16, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ قَالَ الَّذِیۡ نَجَا مِنۡہُمَا وَ ادَّکَرَ  بَعۡدَ اُمَّۃٍ  اَنَا  اُنَبِّئُکُمۡ  بِتَاۡوِیۡلِہٖ فَاَرۡسِلُوۡنِ ﴿۴۵﴾', 'اور وہ شخص جو دونوں قیدیوں میں سے رہائی پا گیا تھا اور جسے مدت کے بعد وہ بات یاد آ گئ بول اٹھا کہ میں آپ کو اسکی تعبیر لا بتاتا ہوں مجھے قید خانے جانے کی اجازت دیجئے۔', 'اور بولا وہ جو بچا تھا ان دونوں میں سے اور یاد آ گیا اس کو مدت کے بعد میں بتاؤں تم کو اس کی تعبیر سو تم مجھ کو بھیجو [۶۹]', 'Then the man who was released (one of the two who were in prison), now at length remembered and said: \"I will tell you its interpretation, so send me forth.\"', 'And said the one who was released (from the prison) out of the two, and recalled (Yūsuf) after a long time, “I shall tell you its interpretation. Just send me (to Yūsuf).”'),
(1642, 12, 46, 6, 16, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'یُوۡسُفُ اَیُّہَا الصِّدِّیۡقُ اَفۡتِنَا فِیۡ سَبۡعِ بَقَرٰتٍ سِمَانٍ یَّاۡکُلُہُنَّ سَبۡعٌ عِجَافٌ وَّ سَبۡعِ سُنۡۢبُلٰتٍ خُضۡرٍ وَّ اُخَرَ  یٰبِسٰتٍ ۙ لَّعَلِّیۡۤ  اَرۡجِعُ  اِلَی النَّاسِ لَعَلَّہُمۡ یَعۡلَمُوۡنَ ﴿۴۶﴾', 'غرض وہ یوسف کے پاس آیا اور کہنے لگا یوسف اے بڑے سچے یوسف ہمیں اس خواب کی تعبیر بتایئے کہ سات موٹی گائیوں کو سات دبلی گائیں کھا رہی ہیں۔ اور سات خوشے سبز ہیں اور سات سوکھے تاکہ میں لوگوں کے پاس واپس جا کر تعبیر بتاؤں عجب نہیں کہ وہ تمہاری قدر جانیں۔', 'جا کر کہا اے یوسف اے سچے [۷۰] حکم دےہم کو اس خواب میں سات گائیں موٹی انکو کھائیں سات دبلی اور سات بالیں ہری اور دوسری سوکھی تاکہ لے جاؤں میں لوگوں کے پاس شاید انکو معلوم ہو [۷۱]', '(He said): \"O Yoosuf (Joseph), the man of truth! Explain to us (the dream) of seven fat cows whom seven lean ones were devouring, and of seven green ears of corn, and (seven) others dry, that I may return to the people, and that they may know.\"', '(Thus he came to the prison and said to Yūsuf “Yūsuf, O the truthful one, tell us about seven fat cows eaten by seven lean ones, and seven ears of grain which are green and (seven) others which are dry, so that I may go back to the people and they may know (the interpretation of the dream.)”'),
(1643, 12, 47, 6, 16, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'قَالَ تَزۡرَعُوۡنَ سَبۡعَ سِنِیۡنَ دَاَبًا ۚ فَمَا حَصَدۡتُّمۡ  فَذَرُوۡہُ  فِیۡ  سُنۡۢبُلِہٖۤ  اِلَّا قَلِیۡلًا  مِّمَّا  تَاۡکُلُوۡنَ ﴿۴۷﴾', 'انہوں نے کہا کہ تم لوگ سات سال متواتر کھیتی کرتے رہو گے تو جو غلہ کاٹو تو تھوڑے سے غلے کے سوا جو کھانے میں آئے باقی کو خوشوں میں ہی رہنے دینا۔', 'کہا تم کھیتی کرو گے سات برس جم کر سو جو کاٹو اس کو چھوڑ دو اس کی بال میں مگر تھوڑا سا جو تم کھاؤ', '((Yoosuf (Joseph)) said: \"For seven consecutive years, you shall sow as usual and that (the harvest) which you reap you shall leave in ears, (all) - except a little of it which you may eat.', 'He said, “You will grow crops for seven years consecutively. So, what you have harvested, leave it in its ear, except a little which you eat.'),
(1644, 12, 48, 6, 16, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'ثُمَّ یَاۡتِیۡ مِنۡۢ بَعۡدِ ذٰلِکَ سَبۡعٌ شِدَادٌ یَّاۡکُلۡنَ مَا قَدَّمۡتُمۡ لَہُنَّ اِلَّا قَلِیۡلًا مِّمَّا تُحۡصِنُوۡنَ ﴿۴۸﴾', 'پھر اسکے بعد خشک سالی کے سات سخت سال آئیں گے کہ جو غلہ تم نے جمع کر رکھا ہو گا وہ اس سب کو کھا جائیں گے۔ صرف وہی تھوڑا سا رہ جائے گا جو تم احتیاط سے رکھ چھوڑو گے۔', 'پھر آئیں گے اس کے بعد سات برس سختی کے کھا جائیں گے جو رکھا تم نے انکے واسطے مگر تھوڑا سا جو روک رکھو گے بیج کے واسطے', '\"Then will come after that, seven hard (years), which will devour what you have laid by in advance for them, (all) except a little of that which you have guarded (stored).', 'Then seven hard years shall come after that, which shall eat up what you have stored for them, except a little which you preserve (to sow).'),
(1645, 12, 49, 6, 16, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'ثُمَّ  یَاۡتِیۡ مِنۡۢ  بَعۡدِ ذٰلِکَ  عَامٌ فِیۡہِ یُغَاثُ  النَّاسُ  وَ فِیۡہِ  یَعۡصِرُوۡنَ ﴿٪۴۹﴾', 'پھر اسکے بعد ایک سال آئے گا کہ خوب مینہ برسے گا اور لوگ اس میں رس نچوڑیں گے۔', 'پھر آئے گا اس کے پیچھے ایک برس اس میں مینہ برسے گا لوگوں پر اور اس میں رس نچوڑیں گے [۷۲]', '\"Then thereafter will come a year in which people will have abundant rain and in which they will press (wine and oil).\"', 'Then there shall come after that a year in which people will have rains and in which they will extract juices.”'),
(1646, 12, 50, 7, 0, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'وَ  قَالَ الۡمَلِکُ ائۡتُوۡنِیۡ بِہٖ ۚ فَلَمَّا جَآءَہُ الرَّسُوۡلُ قَالَ ارۡجِعۡ  اِلٰی رَبِّکَ فَسۡـَٔلۡہُ مَا بَالُ النِّسۡوَۃِ  الّٰتِیۡ قَطَّعۡنَ اَیۡدِیَہُنَّ ؕ اِنَّ رَبِّیۡ بِکَیۡدِہِنَّ عَلِیۡمٌ ﴿۵۰﴾', 'اور یہ تعبیر سن کر بادشاہ نے حکم دیا کہ یوسف کو میرے پاس لے آؤ۔ سو جب قاصد انکے پاس گیا تو انہوں نے کہا کہ اپنے آقا کے پاس واپس جاؤ اور اس سے پوچھو کہ ان عورتوں کا کیا حال ہے جنہوں نے اپنے ہاتھ کاٹ لئے تھے۔ بیشک میرا پروردگار انکے فریب سے خوب واقف ہے۔', 'اور کہا بادشاہ نے لے آؤ اسکو میرے پاس پھر جب پہنچا اس کے پاس بھیجا ہوا آدمی کہا لو ٹ جا اپنے خاوند (مالک) کے پاس اور پوچھ اس سے کیا حقیقت ہے ان عورتوں کی جنہوں نے کاٹے تھے ہاتھ اپنے [۷۳] میرا رب تو ان کا فریب سب جانتا ہے [۷۴]', 'And the king said: \"Bring him to me.\" But when the messenger came to him, (Yoosuf (Joseph)) said: \"Return to your lord and ask him, What happened to the women who cut their hands? Surely, my Lord (Allah) is Well-Aware of their plot.\"', 'And (when this person went back and told the king about the interpretation of the dream), the king said, “Bring him to me.” So, when the messenger came to Yūsuf, he said, “Go back to your lord and ask him, ‘What is the case of the women who cut their hands?’ Surely, my Lord knows well their guile.”'),
(1647, 12, 51, 7, 0, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'قَالَ مَا خَطۡبُکُنَّ  اِذۡ  رَاوَدۡتُّنَّ یُوۡسُفَ عَنۡ نَّفۡسِہٖ ؕ قُلۡنَ حَاشَ لِلّٰہِ  مَا عَلِمۡنَا عَلَیۡہِ مِنۡ سُوۡٓءٍ ؕ قَالَتِ امۡرَاَتُ الۡعَزِیۡزِ الۡـٰٔنَ حَصۡحَصَ الۡحَقُّ ۫ اَنَا رَاوَدۡتُّہٗ عَنۡ  نَّفۡسِہٖ  وَ  اِنَّہٗ   لَمِنَ  الصّٰدِقِیۡنَ ﴿۵۱﴾', 'بادشاہ نے عورتوں سے پوچھا کہ تمہارا کیا قصہ تھا جب تم نے یوسف کو اپنی طرف مائل کرنا چاہا؟ سب بول اٹھیں کہ اللہ پاک ہے ہم نے اس میں کوئی برائی معلوم نہیں کی عزیز کی بیوی نے کہا اب سچی بات تو ظاہر ہو ہی گئ ہے اصل یہ ہے کہ میں نے اسکو اپنی طرف مائل کرنا چاہا تھا اور وہ بیشک سچا ہے۔', 'کہا بادشاہ نے عورتوں کو کیا حقیقت ہے تمہاری جب تم نے پھسلایا یوسف کو اسکے نفس کی حفاظت سے [۷۵] بولیں حاشا للہ ہم کو معلوم نہیں اس پر کچھ برائی بولی عورت عزیز کی اب کھل گئ سچی بات میں نے پھسلایا تھا اسکو اس کے جی سے اور وہ سچا ہے [۷۶]', '(The King) said (to the women): \"What was your affair when you did seek to seduce Yoosuf (Joseph)?\" The women said: \"Allah forbid! No evil know we against him!\" The wife of Al-Azeez said: \"Now the truth is manifest (to all), it was I who sought to seduce him, and he is surely of the truthful.\"', 'He (the king) said, “What was your case, O women, when you seduced Yūsuf?” They said, “God forbid, we know of no evil in him.” The governor’s wife said, “Now the truth has come to light. I did seduce him, and he is surely truthful.”'),
(1648, 12, 52, 7, 0, 12, 'وَ مَا مِنۡ دَآبَّۃٍ', 'یوسف', 'ذٰلِکَ لِیَعۡلَمَ اَنِّیۡ لَمۡ اَخُنۡہُ بِالۡغَیۡبِ وَ اَنَّ  اللّٰہَ  لَا یَہۡدِیۡ  کَیۡدَ  الۡخَآئِنِیۡنَ ﴿۵۲﴾', 'یوسف نے کہا کہ میں نے یہ بات اس لئے پوچھی ہے کہ عزیز کو یقین ہو جائے کہ میں نے اسکی پیٹھ پیچھے اسکی امانت میں خیانت نہیں کی اور اللہ خیانت کرنے والوں کی چال کو چلنے نہیں دیتا۔', 'یوسف نے کہا یہ اس واسطے کہ عزیز معلوم کر لیوے کہ میں نے اسکی چوری نہیں کی چھپ کر اور یہ کہ اللہ نہیں چلاتا (چلنے نہ دیتا) فریب دغا بازوں کا [۷۷]', '(Then Yoosuf (Joseph) said: \"I asked for this enquiry) in order that he (Al-Azeez) may know that I betrayed him not in secret. And, verily! Allah guides not the plot of the betrayers.', '(Then Yūsuf said), “That was because he (the governor) may know that I did not betray him in his absence, and that Allah does not lead the guile of betrayers to success.'),
(1649, 12, 53, 7, 1, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ مَاۤ  اُبَرِّیُٔ نَفۡسِیۡ ۚ اِنَّ  النَّفۡسَ لَاَمَّارَۃٌۢ بِالسُّوۡٓءِ  اِلَّا مَا رَحِمَ  رَبِّیۡ ؕ اِنَّ رَبِّیۡ  غَفُوۡرٌ  رَّحِیۡمٌ ﴿۵۳﴾', 'اور میں اپنے آپکو پاک صاف نہیں کہتا کیونکہ نفس امارہ انسان کو برائی ہی سکھاتا رہتا ہے۔ مگر یہ کہ میرا پروردگار رحم فرمائے۔ بیشک میرا پروردگار بخشنے والا ہے مہربان ہے۔', 'اور میں پاک نہیں کہتا اپنے جی کو بیشک جی تو سکھلاتا ہے برائی مگر جو رحم کر دیا میرے رب نے بیشک میرا رب بخشنے والا ہے مہربان [۷۸]', '\"And I free not myself (from the blame). Verily, the (human) self is inclined to evil, except when my Lord bestows His Mercy (upon whom He wills). Verily, my Lord is Oft-Forgiving, Most Merciful.\"', 'And I do not absolve my inner self of blame. Surely, man’s inner self often incites to evil, unless my Lord shows mercy. Certainly, my Lord is the Most-Forgiving, Very-Merciful.”'),
(1650, 12, 54, 7, 1, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ قَالَ الۡمَلِکُ ائۡتُوۡنِیۡ بِہٖۤ  اَسۡتَخۡلِصۡہُ لِنَفۡسِیۡ ۚ فَلَمَّا  کَلَّمَہٗ  قَالَ  اِنَّکَ الۡیَوۡمَ  لَدَیۡنَا مَکِیۡنٌ  اَمِیۡنٌ ﴿۵۴﴾', 'اور بادشاہ نے حکم دیا کہ اسے میرے پاس لاؤ میں اسے اپنا مصاحب خاص بناؤں گا۔ پھر جب ان سے گفتگو کی تو کہا کہ آج سے تم ہمارے ہاں صاحب منزلت ہو اور صاحب اعتبار ہو۔', 'اور کہا بادشاہ نے لے آؤ اسکو میرے پاس میں خالص کر رکھوں اسکو اپنے کام میں [۷۹] پھر جب بات چیت کی اس سے کہا واقعی تو نے آج سے ہمارے پاس جگہ پائی معتبر ہو کر [۸۰]', 'And the king said: \"Bring him to me that I may attach him to my person.\" Then, when he spoke to him, he said: \"Verily, this day, you are with us high in rank and fully trusted.\"', 'The king said, “Bring him to me, and I shall employ him purely for myself.” So, when he (the king) talked to him, he said (to Yūsuf), “Today you are with us well-placed, fully trusted.”'),
(1651, 12, 55, 7, 1, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالَ اجۡعَلۡنِیۡ عَلٰی خَزَآئِنِ الۡاَرۡضِ ۚ اِنِّیۡ  حَفِیۡظٌ  عَلِیۡمٌ ﴿۵۵﴾', 'یوسف نے کہا مجھے زرعی پیداوار پر مقرر کر دیجئے کیونکہ میں حفاظت بھی کر سکتا ہوں اور اس کام سے واقف بھی ہوں۔', 'یوسف نے کہا مجھ کو مقرر کر ملک کے خزانوں پر میں نگہبان ہوں خوب جاننے والا [۸۱]', '(Yoosuf (Joseph)) said: \"Set me over the storehouses of the land; I will indeed guard them with full knowledge\" (as a minister of finance in Egypt, in place of Al-Aziz who was dead at that time).', 'He said, “Appoint me to (supervise) the treasures of the land. I am indeed a knowledgeable keeper.”'),
(1652, 12, 56, 7, 1, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ کَذٰلِکَ مَکَّنَّا لِیُوۡسُفَ فِی الۡاَرۡضِ ۚ یَتَبَوَّاُ مِنۡہَا حَیۡثُ یَشَآءُ ؕ نُصِیۡبُ بِرَحۡمَتِنَا مَنۡ نَّشَآءُ  وَ لَا نُضِیۡعُ  اَجۡرَ الۡمُحۡسِنِیۡنَ ﴿۵۶﴾', 'اس طرح ہم نے یوسف کو ملک مصر میں جگہ دی۔ اور وہ اس ملک میں جہاں چاہتے تھے رہتے تھے۔ ہم اپنی رحمت جس پر چاہتے ہیں کرتے ہیں اور نیکوکاروں کے اجر کو ضائع نہیں کرتے۔', 'اور یوں قدرت دی ہم نے یوسف کو اس زمین میں جگہ پکڑتا تھا اس میں جہاں چاہتا [۸۲] پہنچا دیتے ہیں ہم رحمت اپنی جس کو چاہیں اور ضائع نہیں کرتے ہم بدلا بھلائی والوں کا', 'Thus did We give full authority to Yoosuf (Joseph) in the land, to take possession therein, as when or where he likes. We bestow of Our Mercy on whom We please, and We make not to be lost the reward of Al-Muhsinoon (the good doers - see V.2:112).', 'And thus We gave Yūsuf power in the land. He could settle in it wherever he wished. We extend Our mercy to whomsoever We will, and We do not let the reward of the righteous people to go to waste.'),
(1653, 12, 57, 7, 1, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ لَاَجۡرُ الۡاٰخِرَۃِ خَیۡرٌ لِّلَّذِیۡنَ اٰمَنُوۡا وَ کَانُوۡا  یَتَّقُوۡنَ ﴿٪۵۷﴾', 'اور جو لوگ ایمان لائے اور ڈرتے رہے انکے لئے آخرت کا اجر بہت بہتر ہے۔', 'اور ثواب آخرت کا بہتر  ہے انکو جو ایمان لائے اور رہے پرہیزگاری میں [۸۳]', 'And verily, the reward of the Hereafter is better for those who believe and used to fear Allah and keep their duty to Him (by abstaining from all kinds of sins and evil deeds and by performing all kinds of righteous good deeds).', 'And the reward of the Hereafter is surely better for those who believe and constantly observe taqwā.'),
(1654, 12, 58, 8, 2, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ جَآءَ اِخۡوَۃُ یُوۡسُفَ فَدَخَلُوۡا عَلَیۡہِ فَعَرَفَہُمۡ  وَ ہُمۡ  لَہٗ  مُنۡکِرُوۡنَ ﴿۵۸﴾', 'اور یوسف کے بھائی کنعان سے مصر میں غلہ خریدنے کے لئے آئے تو یوسف کے پاس گئے تو یوسف نے انکو پہچان لیا اور وہ انکو نہ پہچان سکے۔', 'اور آئے بھائی یوسف کے پھر داخل ہوئے اسکے  پاس تو اس نے پہچان لیا انکو اور وہ نہیں پہچانتے [۸۴]', 'And Yoosufs (Joseph) brethren came and they entered unto him, and he recognized them, but they recognized him not.', 'And came the brothers of Yūsuf and appeared before him. He recognized them, while they did not recognize him.'),
(1655, 12, 59, 8, 2, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ لَمَّا جَہَّزَہُمۡ بِجَہَازِہِمۡ قَالَ ائۡتُوۡنِیۡ بِاَخٍ  لَّکُمۡ  مِّنۡ اَبِیۡکُمۡ ۚ اَلَا تَرَوۡنَ اَنِّیۡۤ اُوۡفِی الۡکَیۡلَ وَ اَنَا خَیۡرُ الۡمُنۡزِلِیۡنَ ﴿۵۹﴾', 'اور جب یوسف نے انکے لئے ان کا سامان تیار کر دیا تو کہا کہ پھر آنا تو جو باپ کی طرف سے تمہارا ایک اور بھائی ہے اسے بھی میرے پاس لیتے آنا۔ کیا تم نہیں دیکھتے کہ میں ناپ بھی پوری پوری دیتا ہوں اور مہمانداری بھی خوب کرتا ہوں۔', 'اور جب تیار کر دیا انکو ان کا اسباب کہا لے آیئو میرے پاس ایک بھائی جو تمہارا ہے باپ کی طرف سے تم نہیں دیکھتے ہو کہ میں پورا دیتا ہوں ماپ اور خوب طرح اتارتا ہوں مہمانوں کو [۸۵]', 'And when he had furnished them forth with provisions (according to their need), he said: \"Bring me a brother of yours from your father; (he meant Benjamin). See you not that I give full measure, and that I am the best of the hosts?', 'When he equipped them with their provisions, he said, “Bring to me your other brother from your father’s side. Do you not see that I give full measure, and I extend the best hospitality?'),
(1656, 12, 60, 8, 2, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'فَاِنۡ لَّمۡ  تَاۡتُوۡنِیۡ بِہٖ  فَلَا کَیۡلَ  لَکُمۡ  عِنۡدِیۡ  وَ لَا  تَقۡرَبُوۡنِ  ﴿۶۰﴾', 'اب اگر تم اسے میرے پاس نہ لاؤ گے تو نہ تمہیں میرے ہاں سے غلہ ملے گا اور نہ تم میرے پاس ہی آ سکو گے۔', 'پھر اگر اس کو نہ لائے میرے پاس تو تمہارے لئے بھرتی نہیں میرے نزدیک اور میرےپاس نہ آئیو [۸۶]', '\"But if you bring him not to me, there shall be no measure (of corn) for you with me, nor shall you come near me.\"', 'Still, if you do not bring him to me, then you deserve no (further) measure from me, nor shall you approach me any more.”'),
(1657, 12, 61, 8, 2, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالُوۡا سَنُرَاوِدُ عَنۡہُ اَبَاہُ وَ اِنَّا لَفٰعِلُوۡنَ ﴿۶۱﴾', 'انہوں نے کہا کہ ہم اسکے بارے میں اسکے والد کو پھسلائیں گے۔ اور ہم یہ کام کر کے رہیں گے۔', 'بولے ہم خواہش کریں گے اس کے باپ سے اور ہم کو یہ کام کرنا ہے [۸۷]', 'They said: \"We shall try to get permission (for him) from his father, and verily, we shall do it.\"', 'They said, “We shall persuade his father about him and we will certainly do it.”'),
(1658, 12, 62, 8, 2, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ  قَالَ لِفِتۡیٰنِہِ اجۡعَلُوۡا بِضَاعَتَہُمۡ فِیۡ رِحَالِہِمۡ لَعَلَّہُمۡ یَعۡرِفُوۡنَہَاۤ اِذَا انۡقَلَبُوۡۤا اِلٰۤی اَہۡلِہِمۡ لَعَلَّہُمۡ یَرۡجِعُوۡنَ ﴿۶۲﴾', 'اور یوسف نے اپنے خدام سے کہا کہ ان کا سرمایہ یعنی غلے کی قیمت انکے سامان میں رکھ دو عجب نہیں کہ جب یہ اپنے اہل و عیال میں جائیں تو اسے پہچان لیں اور عجب نہیں کہ یہ پھر یہاں آئیں۔', 'اور کہدیا اپنے خدمت گاروں کو رکھ دو انکی پونجی انکے اسباب میں شاید اس کو پہچانیں جب پھر کر پہنچیں اپنے گھر شاید وہ پھر آ جائیں [۸۸]', 'And (Yoosuf (Joseph)) told his servants to put their money (with which they had bought the corn) into their bags, so that they might know it when they go back to their people, in order that they might come back.', 'And he (Yūsuf) said to his boys, “Put their goods in their camel-packs. Perhaps they will recognize it when they go back to their family; perhaps they will come again.”'),
(1659, 12, 63, 8, 2, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'فَلَمَّا رَجَعُوۡۤا اِلٰۤی اَبِیۡہِمۡ قَالُوۡا یٰۤاَبَانَا مُنِعَ مِنَّا الۡکَیۡلُ فَاَرۡسِلۡ مَعَنَاۤ  اَخَانَا نَکۡتَلۡ  وَ  اِنَّا لَہٗ  لَحٰفِظُوۡنَ ﴿۶۳﴾', 'پس جب وہ اپنے والد کے پاس واپس گئے تو کہنے لگے کہ ابا ہمارے لئے غلے کی بندش کر دی گئ ہے تو ہمارے ساتھ ہمارے بھائی کو بھیج دیجئے تاکہ ہم پھر غلہ لائیں اور ہم اسکے نگہبان ہیں۔', 'پھر جب پہنچے اپنے باپ کے پاس بولے اے باپ روک دی گئ ہم سے بھرتی سو بھیج ہمارے ساتھ ہمارے بھائی کو کہ بھرتی لے آئیں اور ہم اسکے نگہبان ہیں [۸۹]', 'So, when they returned to their father, they said: \"O our father! No more measure of grain shall we get (unless we take our brother). So send our brother with us, and we shall get our measure and truly we will guard him.\"', 'So, when they returned to their father, they said, “Father, the (required) measure (of grain) has been withheld from us, therefore, send our brother with us, so that we may receive our full measure. And, of course, we are his guards.”'),
(1660, 12, 64, 8, 2, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالَ ہَلۡ اٰمَنُکُمۡ عَلَیۡہِ اِلَّا کَمَاۤ اَمِنۡتُکُمۡ عَلٰۤی اَخِیۡہِ مِنۡ قَبۡلُ ؕ فَاللّٰہُ خَیۡرٌ حٰفِظًا ۪ وَّ ہُوَ اَرۡحَمُ الرّٰحِمِیۡنَ ﴿۶۴﴾', 'یعقوب نے کہا کہ میں اسکے بارے میں تمہارا اعتبار نہیں کرتا مگر ویسا ہی جیسا پہلے اسکے بھائی کے بارے میں کیا تھا سو اللہ ہی بہتر نگہبان ہے اور وہ سب سے زیادہ رحم کرنے والا ہے۔', 'کہا میں کیا اعتبار کروں تمہارا اس پر مگر وہی جیسا اعتبار کیا تھا اس کے بھائی پر اس سے پہلے سو اللہ بہتر ہے نگہبان اور وہی ہے سب مہربانوں سے مہربان [۹۰]', 'He said: \"Can I entrust him to you except as I entrusted his brother (Yoosuf (Joseph)) to you aforetime? But Allah is the Best to guard, and He is the Most Merciful of those who show mercy.\"', 'He said, “Shall I trust you about him as I trusted you earlier about his brother? Well, Allah is the best guardian, and He is the Most-Merciful of all the merciful.”'),
(1661, 12, 65, 8, 2, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ لَمَّا فَتَحُوۡا مَتَاعَہُمۡ وَجَدُوۡا بِضَاعَتَہُمۡ رُدَّتۡ  اِلَیۡہِمۡ ؕ قَالُوۡا  یٰۤاَبَانَا مَا نَبۡغِیۡ ؕ ہٰذِہٖ  بِضَاعَتُنَا رُدَّتۡ اِلَیۡنَا ۚ وَ نَمِیۡرُ اَہۡلَنَا وَ نَحۡفَظُ اَخَانَا وَ نَزۡدَادُ کَیۡلَ  بَعِیۡرٍ ؕ ذٰلِکَ  کَیۡلٌ یَّسِیۡرٌ ﴿۶۵﴾', 'اور جب انہوں نے اپنا اسباب کھولا تو دیکھا کہ ان کا سرمایہ واپس کر دیا گیا ہے۔ کہنے لگے ابا ہمیں اور کیا چاہیے دیکھئے یہ ہماری پونجی بھی ہمیں واپس کر دی گئ ہے۔ اور ہم اپنے اہل و عیال کے لئے پھر غلہ لائیں گے اور اپنے بھائی کی نگہبانی کریں گے اور ایک بار شتر زیادہ لائیں گے کہ یہ غلہ جو ہم لائے ہیں تھوڑا ہے۔', 'اور جب کھولی اپنی چیز بست پائی اپنی پونچی کہ پھیر دی گئ انکی طرف بولے اے باپ ہم کو اور کیا چاہیئے یہ پونچی ہماری پھیر دی ہے ہم کو اب جائیں تو رسد لائیں ہم اپنے گھر کو اور خبرداری کر یں گے اپنے بھائی کی اور زیادہ لیویں بھرتی ایک اونٹ کی [۹۱] وہ بھرتی آسان ہے [۹۲]', 'And when they opened their bags, they found their money had been returned to them. They said: \"O our father! What (more) can we desire? This, our money has been returned to us, so we shall get (more) food for our family, and we shall guard our brother and add one more measure of a camels load. This quantity is easy (for the king to give).\"', 'When they opened their baggage, they found their goods given back to them. They said, “Our father, what else should we want? Here is our goods given back to us, and we shall bring food to our family, protect our brother and add the measure of one camel more. That is an easy measure.”'),
(1662, 12, 66, 8, 2, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالَ لَنۡ اُرۡسِلَہٗ  مَعَکُمۡ حَتّٰی تُؤۡتُوۡنِ مَوۡثِقًا مِّنَ اللّٰہِ  لَتَاۡتُنَّنِیۡ بِہٖۤ اِلَّاۤ اَنۡ یُّحَاطَ بِکُمۡ ۚ فَلَمَّاۤ اٰتَوۡہُ مَوۡثِقَہُمۡ قَالَ اللّٰہُ عَلٰی مَا نَقُوۡلُ  وَکِیۡلٌ ﴿۶۶﴾', 'یعقوب نے کہا کہ جب تک تم اللہ کا عہد نہ دو کہ اسکو میرے پاس صحیح سالم لے آؤ گے میں اسے ہرگز تمہارے ساتھ نہیں بھیجنے کا۔ مگر یہ کہ تم گھیر لئے جاؤ یعنی بےبس ہو جاؤ تو مجبوری ہے پس جب انہوں نے والد کو اپنا قول دیا  تو یعقوب نے کہا کہ جو قول و قرار ہم کر رہے ہیں اس کا اللہ ضامن ہے۔', 'کہا ہر گز نہ بھیجوں گا اسکو تمہارے ساتھ یہاں تک کہ دو مجھ کو عہد خدا کا کہ البتہ پہنچا دو گے اسکو میرے پاس مگر یہ کہ گھیرے جاؤ تم سب پھر جب دیا اسکو سب نے عہد بولا اللہ ہماری باتوں پر نگہبان ہے [۹۳]', 'He (Yaqoob (Jacob)) said: \"I will not send him with you until you swear a solemn oath to me in Allahs Name, that you will bring him back to me unless you are yourselves surrounded (by enemies, etc.),\" And when they had sworn their solemn oath, he said: \"Allah is the Witness over what we have said.\"', 'He said, “I shall never send him with you until you give me a pledge in the name of Allah that you will definitely bring him back to me, unless you are overpowered (by circumstances).” So, when they gave him their pledge, he said, “Allah is watchful over what we say.”'),
(1663, 12, 67, 8, 2, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ قَالَ یٰبَنِیَّ  لَا تَدۡخُلُوۡا مِنۡۢ بَابٍ وَّاحِدٍ  وَّ ادۡخُلُوۡا  مِنۡ  اَبۡوَابٍ  مُّتَفَرِّقَۃٍ ؕ وَ مَاۤ  اُغۡنِیۡ عَنۡکُمۡ  مِّنَ اللّٰہِ مِنۡ شَیۡءٍ ؕ اِنِ الۡحُکۡمُ  اِلَّا لِلّٰہِ ؕ عَلَیۡہِ تَوَکَّلۡتُ ۚ وَ عَلَیۡہِ فَلۡیَتَوَکَّلِ الۡمُتَوَکِّلُوۡنَ ﴿۶۷﴾', 'اور فرمایا کہ اے میرے بیٹو ایک ہی دروازے سے داخل نہ ہونا بلکہ جدا جدا دروازوں سے داخل ہونا۔ اور میں اللہ کی تقدیر تو تم سے روک نہیں سکتا۔ بیشک حکم اللہ ہی کا ہے۔ میں اسی پر بھروسہ رکھتا ہوں اور اہل توکل کو اسی پر بھروسہ رکھنا چاہئیے۔', 'اور کہا اے بیٹو نہ داخل ہونا ایک دروازہ سے اور داخل ہونا کئ دروازوں سے جدا جدا اور میں نہیں بچا سکتا تم کو اللہ کی کسی بات سے حکم کسی کا نہیں سوائے اللہ کے اسی پر مجھ کو بھروسہ ہے  اور اسی پر بھروسہ چاہئے بھروسہ کرنے والوں کو [۹۴]', 'And he said: \"O my sons! Do not enter by one gate, but enter by different gates, and I cannot avail you against Allah at all. Verily! The decision rests only with Allah. In him, I put my trust and let all those that trust, put their trust in Him.\"', 'And he said, “O my sons, do not enter (the city) all of you from the same gate, rather, enter from different gates. And I cannot help you in any way against (the will of) Allah. Sovereignty belongs to none but Allah. In Him I place my trust, and all those who trust should trust in Him alone.”'),
(1664, 12, 68, 8, 2, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ لَمَّا دَخَلُوۡا مِنۡ حَیۡثُ اَمَرَہُمۡ  اَبُوۡہُمۡ ؕ مَا کَانَ یُغۡنِیۡ عَنۡہُمۡ مِّنَ اللّٰہِ مِنۡ شَیۡءٍ اِلَّا حَاجَۃً فِیۡ نَفۡسِ یَعۡقُوۡبَ قَضٰہَا ؕ وَ اِنَّہٗ  لَذُوۡ عِلۡمٍ لِّمَا عَلَّمۡنٰہُ  وَ لٰکِنَّ اَکۡثَرَ  النَّاسِ  لَا  یَعۡلَمُوۡنَ ﴿٪۶۸﴾', 'اور جب وہ ان ان مقامات سے داخل ہوئے جہاں جہاں سے داخل ہونے کے لئے انکے والد نے ان سے کہا تھا تو وہ تدبیر اللہ کے حکم کو ذرا بھی ٹال نہیں سکتی تھی۔ ہاں وہ یعقوب کے دل کی خواہش تھی جو انہوں نے پوری کی تھی اور بیشک وہ صاحب علم تھے کیونکہ ہم نے انکو علم سکھایا تھا لیکن اکثر لوگ نہیں جانتے۔', 'اور جب داخل ہوئے جہاں سے کہا تھا انکے باپ نے [۹۵] کچھ نہ بچا سکتا تھا انکو اللہ کی کسی بات سے مگر ایک خواہش تھی یعقوب کے جی میں سو پوری کر چکا اور وہ تو خبردار تھا جو کچھ ہم نے اس کو سکھایا لیکن بہت لوگوں کو خبر نہیں [۹۶]', 'And when they entered according to their fathers advice, it did not avail them in the least against (the Will of) Allah, it was but a need of Yaqoobs (Jacob) inner-self which he discharged. And verily, he was endowed with knowledge because We had taught him, but most men know not.', 'And (recall) when they entered (the city) in the manner their father had advised them. He could not help them in any way against (the will of) Allah, but it was just an urge in the heart of Ya‘qūb which he satisfied; he was a man of knowledge, because We had taught him, but most of the people do not know.'),
(1665, 12, 69, 9, 3, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ لَمَّا دَخَلُوۡا عَلٰی یُوۡسُفَ اٰوٰۤی اِلَیۡہِ اَخَاہُ  قَالَ  اِنِّیۡۤ   اَنَا  اَخُوۡکَ فَلَا تَبۡتَئِسۡ بِمَا  کَانُوۡا  یَعۡمَلُوۡنَ ﴿۶۹﴾', 'اور جب وہ لوگ یوسف کے پاس پہنچے تو یوسف نے اپنے حقیقی بھائی کو اپنے پاس جگہ دی اور کہا کہ میں تمہارا بھائی ہوں تو جو سلوک یہ ہمارے ساتھ کرتے رہے ہیں اس پر افسوس نہ کرنا۔', 'اور جب داخل ہوئے یوسف کے پاس اپنے پاس رکھا اپنے بھائی کو کہا تحقیق میں ہوں بھائی تیرا سو غمگین مت ہو ان کاموں سے جو انہوں نے کئے ہیں [۹۷]', 'And when they went in before Yoosuf (Joseph), he betook his brother (Benjamin) to himself and said: \"Verily!I am your brother, so grieve not for what they used to do.\"', 'And when they came to Yūsuf, he lodged his brother (Binyamin) with himself. He said, “Look, I am your brother! So do not grieve for what they have been doing.”'),
(1666, 12, 70, 9, 3, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'فَلَمَّا جَہَّزَہُمۡ بِجَہَازِہِمۡ جَعَلَ السِّقَایَۃَ  فِیۡ رَحۡلِ اَخِیۡہِ  ثُمَّ اَذَّنَ مُؤَذِّنٌ اَیَّتُہَا الۡعِیۡرُ اِنَّکُمۡ لَسٰرِقُوۡنَ ﴿۷۰﴾', 'پھر جب ان کا اسباب تیار کر دیا تو اپنے بھائی کے تھیلے میں آبخورہ رکھ دیا پھر جب وہ آبادی سے باہر نکل گئے تو ایک پکارنے والے نے آواز دی کہ قافلے والو! تم تو چور ہو۔', 'پھر جب تیار کر دیا انکے واسطے اسباب انکا رکھ دیا پینے کا پیالہ اسباب میں اپنے بھائی کے پھر پکارا پکارنے والے نے اے قافلہ والو تم تو البتہ چور ہو [۹۸]', 'So when he had furnished them forth with their provisions, he put the (golden) bowl into his brothers bag, then a crier cried: \"O you (in) the caravan! Surely, you are thieves!\"', 'Later, when he equipped them with their provisions, he placed the bowl in the camel-pack of his brother. Then, an announcer shouted out, “O people of the caravan, you are thieves.”'),
(1667, 12, 71, 9, 3, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالُوۡا وَ اَقۡبَلُوۡا عَلَیۡہِمۡ  مَّا ذَا  تَفۡقِدُوۡنَ ﴿۷۱﴾', 'وہ انکی طرف متوجہ ہو کر کہنے لگے کہ تمہاری کیا چیز کھوئی گئ ہے۔', 'کہنے لگے منہ کر کے انکی طرف تمہاری کیا چیز گم ہو گئ [۹۹]', 'They, turning towards them, said: \"What is it that you have missed?\"', 'Turning towards them, they said, “What are you missing?”'),
(1668, 12, 72, 9, 3, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالُوۡا نَفۡقِدُ صُوَاعَ  الۡمَلِکِ  وَ لِمَنۡ  جَآءَ بِہٖ  حِمۡلُ  بَعِیۡرٍ  وَّ اَنَا  بِہٖ  زَعِیۡمٌ ﴿۷۲﴾', 'وہ بولے کہ بادشاہ کا کٹورہ کھویا گیا ہے اور جو شخص اسکو لے کے آئے اسکے لئے ایک بار شتر انعام اور میں اسکا ضامن ہوں۔', 'بولے ہم نہیں پاتے بادشاہ کا پیمانہ اور جو کوئی اس کو لائے اسکو ملے ایک بوجھ اونٹ کا اور میں ہوں اس کا ضامن [۱۰۰]', 'They said: \"We have missed the (golden) bowl of the king and for him who produces it is (the reward of) a camel load; I will be bound by it.\"', 'They said, “We are missing the measuring-bowl of the king, and whoever brings it back shall deserve a camel-load, and I stand surety for it.”'),
(1669, 12, 73, 9, 3, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالُوۡا تَاللّٰہِ  لَقَدۡ عَلِمۡتُمۡ مَّا جِئۡنَا لِنُفۡسِدَ فِی الۡاَرۡضِ وَ مَا کُنَّا سٰرِقِیۡنَ ﴿۷۳﴾', 'وہ کہنے لگے کہ اللہ کی قسم تم کو معلوم ہے کہ ہم اس ملک میں اس لئے نہیں آئے کہ خرابی کریں اور نہ ہم چوری کیا کرتے ہیں۔', 'بولے قسم اللہ کی تم کو معلوم ہے ہم شرارت کرنے کو نہیں آئے ملک میں اور نہ ہم کبھی چور تھے [۱۰۱]', 'They said: \"By Allah! Indeed you know that we came not to make mischief in the land, and we are no thieves!\"', 'They said, “We swear by Allah, you know, we did not come to make mischief in the land, nor have we ever been thieves.”'),
(1670, 12, 74, 9, 3, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالُوۡا  فَمَا  جَزَآؤُہٗۤ   اِنۡ  کُنۡتُمۡ کٰذِبِیۡنَ ﴿۷۴﴾', 'وہ بولے کہ اگر تم جھوٹے نکلے یعنی چوری ثابت ہوئی تو اسکی سزا کیا؟', 'بولے پھر کیا سزا ہے اسکی اگر تم نکلے جھوٹے [۱۰۲]', 'They (Yoosufs (Joseph) men) said: \"What then shall be the penalty of him, if you are (proved to be) liars.\"', 'They said, “What is the punishment, if you are liars?”'),
(1671, 12, 75, 9, 3, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالُوۡا جَزَآؤُہٗ  مَنۡ وُّجِدَ فِیۡ  رَحۡلِہٖ  فَہُوَ جَزَآؤُہٗ ؕ  کَذٰلِکَ  نَجۡزِی  الظّٰلِمِیۡنَ ﴿۷۵﴾', 'انہوں نے کہا کہ اسکی سزا یہ کہ جس کے تھیلے میں وہ دستیاب ہو وہی اس کا بدل قرار دیا جائے ہم ظالموں کو یہی سزا دیا کرتے ہیں۔', 'کہنے لگے اس کی سزا یہ کہ جس کے اسباب میں سے ہاتھ آئے وہی اسکے بدلے میں جائے ہم یہی سزا دیتے ہیں ظالموں کو [۱۰۳]', 'They (Yoosufs (Joseph) brothers) said: \"The penalty should be that he, in whose bag it is found, should be held for the punishment (of the crime). Thus we punish the Zalimoon (wrong-doers, etc.)!\"', 'They said, “Its punishment? The one in whose saddlebag it is found shall himself be the punishment. This is how we punish the wrongdoers.”'),
(1672, 12, 76, 9, 3, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'فَبَدَاَ بِاَوۡعِیَتِہِمۡ قَبۡلَ وِعَآءِ اَخِیۡہِ ثُمَّ اسۡتَخۡرَجَہَا مِنۡ وِّعَآءِ اَخِیۡہِ ؕ کَذٰلِکَ  کِدۡنَا لِیُوۡسُفَ ؕ مَا  کَانَ  لِیَاۡخُذَ اَخَاہُ فِیۡ  دِیۡنِ الۡمَلِکِ  اِلَّاۤ  اَنۡ  یَّشَآءَ  اللّٰہُ ؕ نَرۡفَعُ دَرَجٰتٍ مَّنۡ نَّشَآءُ ؕ وَ فَوۡقَ کُلِّ ذِیۡ  عِلۡمٍ  عَلِیۡمٌ ﴿۷۶﴾', 'پھر یوسف نے اپنے بھائی کے تھیلے سے پہلے انکے تھیلوں کو دیکھنا شروع کیا۔ پھر اپنے بھائی کے تھیلے میں سے اسکو نکال لیا۔ اس طرح ہم نے یوسف کے لئے تدبیر کی ورنہ بادشاہ کے قانون کے مطابق وہ اپنے بھائی کو لے نہیں سکتے تھے مگر یہ کہ اللہ چاہے۔ ہم جس کے چاہتے ہیں درجے بلند کرتے ہیں اور ہر علم والے سے بڑھ کر ایک بڑا علم والا ہے۔', 'پھر شروع کیں یوسف نے انکی خرجیاں دیکھنی اپنے بھائی کی خرجی سے پہلے آخر کو وہ برتن نکالا اپنے بھائی کی خرجی سے[۱۰۴] یوں داؤ بتا دیا ہم نے یوسف کو [۱۰۵] وہ ہر گز نہ لے سکتا تھا اپنے بھائی کو دین (قانون) میں اس بادشاہ کے مگر جو چاہے اللہ [۱۰۶] ہم درجے بلند کرتے ہیں جس کے چاہیں [۱۰۷] اور ہر جاننے والے سے اوپر  ہے ایک جاننے والا [۱۰۸]', 'So he (Yoosuf (Joseph)) began (the search) in their bags before the bag of his brother. Then he brought it out of his brothers bag. Thus did We plan for Yoosuf (Joseph). He could not take his brother by the law of the king (as a slave), except that Allah willed it. (So Allah made the brothers to bind themselves with their way of \"punishment, i.e. enslaving of a thief.\") We raise to degrees whom We please, but over all those endowed with knowledge is the All-Knowing (Allah).', 'So, he started with their bags before (searching) the bag of his brother, then, recovered it from the bag of his brother.This is how We planned for Yūsuf. He had no right to take his brother according to the law of the king, unless Allah so willed. We elevate in ranks whomsoever We will. Above every man of knowledge, there is someone more knowledgeable.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1673, 12, 77, 9, 3, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالُوۡۤا اِنۡ یَّسۡرِقۡ فَقَدۡ سَرَقَ اَخٌ لَّہٗ  مِنۡ قَبۡلُ ۚ فَاَسَرَّہَا یُوۡسُفُ فِیۡ نَفۡسِہٖ وَ لَمۡ یُبۡدِہَا لَہُمۡ ۚ قَالَ اَنۡتُمۡ شَرٌّ مَّکَانًا ۚ وَ اللّٰہُ  اَعۡلَمُ  بِمَا تَصِفُوۡنَ ﴿۷۷﴾', 'برادران یوسف نے کہا کہ اگر اس نے چوری کی ہو تو کچھ عجب نہیں کہ اس کے ایک بھائی نے بھی پہلے چوری کی تھی۔ مگر یوسف نے اس بات کو اپنے دل میں مخفی رکھا اور ان پر ظاہر نہ ہونے دیا یعنی زیرلب کہا کہ تم بڑے برے ہو۔ اور جو تم بیان کرتے ہو اللہ اسے خوب جانتا ہے۔', 'کہنے لگےاگر اس نے چرایا تو چوری کی تھی اسکے ایک بھائی نے بھی اس سے پہلے [۱۰۹] تب آہستہ سے کہا یوسف نے اپنے جی میں اور انکو نہ جتایا کہا جی میں کہ تم بدتر ہو درجہ میں اور اللہ خوب جانتا ہے جو تم بیان کرتے ہو [۱۱۰]', 'They ((Yoosufs (Joseph) brothers) said: \"If he steals, there was a brother of his (Yoosuf (Joseph)) who did steal before (him).\" But these things did Yoosuf (Joseph) keep in himself, revealing not the secrets to them. He said (within himself): \"You are in worst case, and Allah knows best the truth of what you assert!\"', 'They said, “If he commits theft, (there is nothing surprising, because) his other brother had committed theft earlier.” Yūsuf kept it (his reaction) to himself and did not reveal it to them. He said (in his heart), “You are even worse in position. Allah knows best of what you allege.”'),
(1674, 12, 78, 9, 3, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالُوۡا یٰۤاَیُّہَا الۡعَزِیۡزُ اِنَّ لَہٗۤ  اَبًا شَیۡخًا کَبِیۡرًا فَخُذۡ اَحَدَنَا مَکَانَہٗ ۚ اِنَّا نَرٰىکَ مِنَ  الۡمُحۡسِنِیۡنَ ﴿۷۸﴾', 'وہ کہنے لگے کہ اے عزیز اسکے والد بہت بوڑھے ہیں اور اس سے بہت محبت رکھتے ہیں تو اسکو چھوڑ دیجئے اور اسکی جگہ ہم میں سے کسی کو رکھ لیجئے ہم دیکھتے ہیں کہ آپ احسان کرنے والے ہیں۔', 'کہنے لگے اے عزیز اس کا ایک باپ ہے بوڑھا بڑی عمر کا سو رکھ لے ایک کو ہم میں سے اس کی جگہ ہم دیکھتے ہیں تو ہے احسان کرنے والا [۱۱۱]', 'They said: \"O ruler of the land! Verily, he has an old father (who will grieve for him); so take one of us in his place. Indeed we think that you are one of the Muhsinoon (good-doers - see V.2:112).\"', 'They said, “O ‘Azīz, he has a father, a very old man. So, take one of us in his place. We see you are a generous man.”'),
(1675, 12, 79, 9, 3, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالَ مَعَاذَ اللّٰہِ اَنۡ نَّاۡخُذَ اِلَّا مَنۡ وَّجَدۡنَا مَتَاعَنَا عِنۡدَہٗۤ ۙ اِنَّاۤ اِذًا لَّظٰلِمُوۡنَ ﴿٪۷۹﴾', 'یوسف نے کہا کہ اللہ پناہ میں رکھے کہ جس شخص کے پاس ہم نے اپنی چیز پائی ہے اسکے سوا کسی اور کو پکڑ لیں ایسا کریں تو ہم بڑے بےانصاف ہیں۔', 'بولا اللہ پناہ دے کہ ہم کسی کو پکڑیں مگر جس کے پاس پائی ہم نے اپنی چیز [۱۱۲] تو تو ہم ضرور بے انصاف ہوئے [۱۱۳]', 'He said: \"Allah forbid, that we should take anyone but him with whom we found our property. Indeed (if we did so), we should be Zalimoon (wrong-doers).\"', 'He said, “We seek Allah’s refuge from keeping anyone other than him with whom we have found our thing, otherwise we shall be unjust.”'),
(1676, 12, 80, 10, 4, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'فَلَمَّا اسۡتَیۡـَٔسُوۡا مِنۡہُ خَلَصُوۡا نَجِیًّا ؕ قَالَ کَبِیۡرُہُمۡ اَلَمۡ تَعۡلَمُوۡۤا اَنَّ اَبَاکُمۡ قَدۡ اَخَذَ عَلَیۡکُمۡ  مَّوۡثِقًا مِّنَ اللّٰہِ وَ مِنۡ قَبۡلُ مَا فَرَّطۡتُّمۡ فِیۡ یُوۡسُفَ ۚ فَلَنۡ اَبۡرَحَ الۡاَرۡضَ حَتّٰی یَاۡذَنَ لِیۡۤ  اَبِیۡۤ  اَوۡ یَحۡکُمَ اللّٰہُ  لِیۡ ۚ وَ ہُوَ  خَیۡرُ  الۡحٰکِمِیۡنَ ﴿۸۰﴾', 'آخر جب وہ اس سے ناامید ہو گئے تو الگ ہو کر صلاح کرنے لگے۔ سب سے بڑے نے کہا کیا تم نہیں جانتے کہ تمہارے والد نے تم سے اللہ کا عہد لیا ہے اور اس سے پہلے بھی تم یوسف کے بارے میں قصور کر چکے ہو تو جب تک والد صاحب مجھے اجازت نہ دیں میں تو اس جگہ سے ہلنے کا نہیں یا اللہ میرے لئے کوئی فیصلہ کرے۔ اور وہ سب سے بہتر فیصلہ کرنے والا ہے۔', 'پھر جب ناامید ہوئے اس سے اکیلے ہو بیٹھے مشورہ کرنے کو بولا ان میں کا بڑا کیا تم کو معلوم نہیں کہ تمہارے باپ نے لیا ہے تم سے عہد اللہ کا اور پہلے جو قصور کر چکے ہو یوسف کے حق (قصہ) میں سو میں تو ہرگز نہ سرکوں گا اس ملک سے جب تک کہ حکم دے مجھ کو باپ میرا یا قضیہ چکا دے اللہ میری طرف اور وہ ہے سب سے بہتر چکانے والا [۱۱۴]', 'So, when they despaired of him, they held a conference in private. The eldest among them said: \"Know you not that your father did take an oath from you in Allahs Name, and before this you did fail in your duty with Yoosuf (Joseph)? Therefore I will not leave this land until my father permits me, or Allah decides my case (by releasing Benjamin) and He is the Best of the judges.', 'So when they lost hope in him, they went aside for consultation. The oldest of them said, “Do you not know that your father has taken pledge from you in the name of Allah, while you had defaulted earlier in the case of Yūsuf. So, I shall never leave this land unless my father permits me or Allah decides about me. He is the best of all judges.'),
(1677, 12, 81, 10, 4, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'اِرۡجِعُوۡۤا اِلٰۤی اَبِیۡکُمۡ  فَقُوۡلُوۡا یٰۤاَبَانَاۤ  اِنَّ ابۡنَکَ سَرَقَ ۚ وَ مَا شَہِدۡنَاۤ اِلَّا بِمَا عَلِمۡنَا وَ مَا کُنَّا لِلۡغَیۡبِ حٰفِظِیۡنَ ﴿۸۱﴾', 'تم سب والد صاحب کے واپس پاس جاؤ اور کہو کہ ابا آپ کے صاحبزادے نے وہاں جا کر چوری کی۔ اور ہم نے تو اپنی دانست کے مطابق آپ سے اسکے لے آنے کا عہد کیا تھا مگر ہم غیب کی باتوں کے جاننے اور یاد رکھنے والے تو نہیں تھے۔', 'پھر جاؤ اپنے باپ کے پاس اور کہو اے باپ تیرے بیٹے نے تو چوری کی اور ہم نے تو وہی کہا تھا جو ہم کو خبر تھی اور ہم کو غیب کی بات کا دھیان نہ تھا [۱۱۵]', '\"Return to your father and say, O our father! Verily, your son (Benjamin) has stolen, and we testify not except according to what we know, and we could not know the unseen!', 'Go back to your father and say, ‘Our father, your son has committed theft, and we do not testify except what we know, and we could not guard against the unseen.'),
(1678, 12, 82, 10, 4, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ سۡـَٔلِ الۡقَرۡیَۃَ  الَّتِیۡ  کُنَّا فِیۡہَا وَ الۡعِیۡرَ الَّتِیۡۤ  اَقۡبَلۡنَا فِیۡہَا ؕ وَ اِنَّا لَصٰدِقُوۡنَ ﴿۸۲﴾', 'اور جس بستی میں ہم ٹھہرے تھے وہاں سے یعنی اہل مصر سے اور جس قافلے میں آئے ہیں اس سے دریافت کر لیجئے۔ اور ہم اس بیان میں بالکل سچے ہیں۔', 'اور پوچھ لے اس بستی سے جس میں ہم تھے اور اس قافلہ سے جس میں ہم آئے ہیں اور ہم بیشک سچ کہتے ہیں [۱۱۶]', '\"And ask (the people of) the town where we have been, and the caravan in which we returned, and indeed we are telling the truth.\"', 'Ask (the people of) the town in which we have been, and the caravan with which we have come, and undoubtedly we are truthful.”'),
(1679, 12, 83, 10, 4, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالَ  بَلۡ  سَوَّلَتۡ  لَکُمۡ  اَنۡفُسُکُمۡ  اَمۡرًا ؕ فَصَبۡرٌ جَمِیۡلٌ ؕ عَسَی اللّٰہُ  اَنۡ یَّاۡتِـیَنِیۡ بِہِمۡ جَمِیۡعًا ؕ اِنَّہٗ  ہُوَ الۡعَلِیۡمُ الۡحَکِیۡمُ ﴿۸۳﴾', 'جب انہوں نے یہ بات یعقوب سے آ کر کہی تو انہوں نے کہا کہ حقیقت یوں نہیں ہے بلکہ یہ بات تم نے اپنے دل سے بنا لی ہے تو صبر ہی بہتر ہے۔ عجب نہیں کہ اللہ ان سب کو میرے پاس لے آئے۔ بیشک وہ علم والا ہے حکمت والا ہے۔', 'بولا کوئی نہیں بنالی ہے تمہارے جی نے ایک بات اب صبر ہی بہتر (کام آئے ، بن پڑے) ہے شاید اللہ لے آئے میرے پاس ان سب کو  وہی ہے خبردار حکمتوں والا [۱۱۷]', 'He (Yaqoob (Jacob)) said: \"Nay, but your ownselves have beguiled you into something. So patience is most fitting (for me). May be Allah will bring them (back) all to me. Truly He! only He is All-Knowing, All-Wise.\"', 'He (Ya‘qūb) said, “Rather, your inner desires have seduced you to something. So, patience is best. Hopefully, Allah may bring them all together. Surely, He is the All-Knowing, All-Wise.”'),
(1680, 12, 84, 10, 4, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ تَوَلّٰی عَنۡہُمۡ  وَ قَالَ یٰۤاَسَفٰی عَلٰی یُوۡسُفَ وَ ابۡیَضَّتۡ عَیۡنٰہُ مِنَ الۡحُزۡنِ فَہُوَ کَظِیۡمٌ ﴿۸۴﴾', 'اور انکے پاس سے چلے گئے اور کہنے لگے کہ ہائے افسوس یوسف پر ہائے افسوس اور رنج و الم میں انکی آنکھیں سفید ہو گئیں اور ان کا دل غم سے بھر رہا تھا۔', 'اور الٹا پھرا انکے پاس سے اور بولا اے افسوس یوسف پر [۱۱۸] اور سفید ہو گئیں آنکھیں اسکی غم سے [۱۱۹] سو وہ آپ کو گھونٹ رہا تھا [۱۲۰]', 'And he turned away from them and said: \"Alas, my grief for Yoosuf (Joseph)!\" And he lost his sight because of the sorrow that he was suppressing.', 'He turned away from them and said, “How sad I am about Yūsuf!” and his eyes turned white with sorrow and he was suppressing (his anger and grief).'),
(1681, 12, 85, 10, 4, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالُوۡا تَاللّٰہِ تَفۡتَؤُا تَذۡکُرُ  یُوۡسُفَ حَتّٰی تَکُوۡنَ حَرَضًا اَوۡ تَکُوۡنَ مِنَ الۡہٰلِکِیۡنَ ﴿۸۵﴾', 'بیٹے کہنے لگے کہ واللہ آپ تو یوسف کو اسی طرح یاد ہی کرتے رہیں گے یہاں تک کہ آپ گھل جائیں گے یا جان ہی دے دیں گے۔', 'کہنے لگے قسم اللہ کی تو نہ چھوڑے گا یوسف کی یاد کو جب تک کہ گھل جائے یا ہو جائے مردہ', 'They said: \"By Allah! You will never cease remembering Yoosuf (Joseph) until you become weak with old age, or until you be of the dead.\"', 'They said, “By God, you will not stop remembering Yūsuf until you collapse or perish.”'),
(1682, 12, 86, 10, 4, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالَ اِنَّمَاۤ اَشۡکُوۡا بَثِّیۡ وَ حُزۡنِیۡۤ   اِلَی اللّٰہِ وَ اَعۡلَمُ  مِنَ  اللّٰہِ  مَا  لَا  تَعۡلَمُوۡنَ ﴿۸۶﴾', 'انہوں نے کہا کہ میں تو اپنے غم و اندوہ کا اظہار اللہ سے کرتا ہوں۔ اور اللہ کی طرف سے وہ باتیں جانتا ہوں جو تم نہیں جانتے۔', 'بولا میں تو کھولتا ہوں اپنا اضطراب اور غم اللہ کے سامنے اور جانتا ہوں اللہ کی طرف سے جو تم نہیں جانتے [۱۲۱]', 'He said: \"I only complain of my grief and sorrow to Allah, and I know from Allah that which you know not.', 'He said, “I do not complain of my anguish and sorrow to anyone but Allah, and I know from Allah what you do not know.'),
(1683, 12, 87, 10, 4, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'یٰبَنِیَّ اذۡہَبُوۡا فَتَحَسَّسُوۡا مِنۡ یُّوۡسُفَ وَ اَخِیۡہِ وَ لَا تَایۡـَٔسُوۡا مِنۡ رَّوۡحِ اللّٰہِ ؕ اِنَّہٗ  لَا یَایۡـَٔسُ مِنۡ رَّوۡحِ اللّٰہِ  اِلَّا الۡقَوۡمُ  الۡکٰفِرُوۡنَ ﴿۸۷﴾', 'اے بیٹو  یوں کرو کہ ایک دفعہ پھر جاؤ اور یوسف اور اسکے بھائی کو تلاش کرو اور اللہ کی رحمت سے ناامید نہ ہونا کہ اللہ کی رحمت سے تو کافر لوگ ہی ناامید ہوا کرتے ہیں۔', 'اے بیٹو جاؤ اور تلاش کرو یوسف کی اور اسکے بھائی کی اور ناامید مت ہو اللہ کے فیض سے بیشک نا امید نہیں ہوتے اللہ کے فیض سے مگر وہی لوگ جو کافر ہیں [۱۲۲]', '\"O my sons! Go you and enquire about Yoosuf (Joseph) and his brother, and never give up hope of Allahs Mercy. Certainly no one despairs of Allahs Mercy, except the people who disbelieve.\"', 'O my sons, go and search for Yūsuf and his brother, and do not lose hope in the mercy of Allah. In fact, only the infidels lose hope in Allah’s mercy.”'),
(1684, 12, 88, 10, 4, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'فَلَمَّا دَخَلُوۡا عَلَیۡہِ قَالُوۡا یٰۤاَیُّہَا الۡعَزِیۡزُ مَسَّنَا وَ اَہۡلَنَا الضُّرُّ وَ جِئۡنَا بِبِضَاعَۃٍ مُّزۡجٰىۃٍ فَاَوۡفِ لَنَا الۡکَیۡلَ وَ تَصَدَّقۡ عَلَیۡنَا ؕ اِنَّ اللّٰہَ یَجۡزِی  الۡمُتَصَدِّقِیۡنَ ﴿۸۸﴾', 'پھر جب وہ یوسف کے پاس گئے تو کہنے لگے کہ اے عزیز ہمیں اور ہمارے اہل و عیال کو بڑی تکلیف ہو رہی ہے اور ہم یہ تھوڑا سا سرمایہ لائے ہیں آپ ہمیں اسکے عوض پورا غلہ دے دیجئے۔ اور ہم پر خیرات کیجئے کہ اللہ خیرات کرنے والوں کو ثواب دیتا ہے۔', 'پھر جب داخل ہوئے اسکے پاس بولے اے عزیز پڑی ہم پر اور ہمارے گھر پر سختی اور لائے ہیں ہم پونجی ناقص سو پوری دے ہم کو بھرتی اور خیرات کر ہم پر اللہ بدلہ دیتا ہے خیرات کرنے والوں کو [۱۲۳]', 'Then, when they entered unto him (Yoosuf (Joseph)), they said: \"O ruler of the land! A hard time has hit us and our family, and we have brought but poor capital, so pay us full measure and be charitable to us. Truly, Allah does reward the charitable.\"', 'So, when they came to him (Yūsuf), they said, “‘Azīz, we and our family are struck by distress, and we have brought some goods of very little worth. So, give us the full measure (of grain) and be charitable to us. Surely, Allah rewards the charitable.”'),
(1685, 12, 89, 10, 4, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالَ ہَلۡ عَلِمۡتُمۡ مَّا فَعَلۡتُمۡ بِیُوۡسُفَ وَ اَخِیۡہِ   اِذۡ  اَنۡتُمۡ  جٰہِلُوۡنَ ﴿۸۹﴾', 'یوسف نے کہا تمہیں معلوم ہے کہ جب تم نادانی میں پھنسے ہوئے تھے تو تم نے یوسف اور اسکے بھائی کے ساتھ کیا کیا تھا؟', 'کہا کچھ تم کو خبر ہے کہ کیا کیا تم نے یوسف سے اور اسکے بھائی سے [۱۲۴] جب تم کو سمجھ نہ تھی [۱۲۵]', 'He said: \"Do you know what you did with Yoosuf (Joseph) and his brother, when you were ignorant?\"', 'He said, “Do you know what you did to Yūsuf and his brother when you were ignorant?”'),
(1686, 12, 90, 10, 4, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالُوۡۤا ءَاِنَّکَ لَاَنۡتَ یُوۡسُفُ ؕ قَالَ اَنَا یُوۡسُفُ وَ ہٰذَاۤ  اَخِیۡ ۫ قَدۡ مَنَّ اللّٰہُ عَلَیۡنَا ؕ اِنَّہٗ  مَنۡ یَّـتَّقِ وَ یَصۡبِرۡ  فَاِنَّ اللّٰہَ  لَا  یُضِیۡعُ  اَجۡرَ  الۡمُحۡسِنِیۡنَ ﴿۹۰﴾', 'وہ بولے کیا واقعی تمہی یوسف ہو انہوں نے کہا ہاں میں ہی یوسف ہوں۔ اور بنیامین کی طرف اشارہ کر کے کہنے لگے یہ میرا بھائی ہے اللہ نے ہم پر بڑا احسان کیا ہے۔ جو شخص اللہ سے ڈرتا اور صبر کرتا ہے تو اللہ نیکوکاروں کا اجر ضائع نہیں کرتا۔', 'بولے کیا سچ تو ہی ہے یوسف [۱۲۶] کہا میں یوسف ہوں اور یہ ہے میرا بھائی [۱۲۷] اللہ نے احسان کیا ہم پر [۱۲۸] البتہ جو کوئی ڈرتا ہے اور صبر کرتا ہے تو اللہ ضائع نہیں کرتا حق نیکی والوں کا [۱۲۹]', 'They said: \"Are you indeed Yoosuf (Joseph)?\" He said: \"I am Yoosuf (Joseph), and this is my brother (Benjamin). Allah has indeed been gracious to us. Verily, he who fears Allah with obedience to Him (by abstaining from sins and evil deeds, and by performing righteous good deeds), and is patient, then surely, Allah makes not the reward of the Muhsinoon (good-doers - see V.2:112) to be lost.\"', 'They said, “Is it that you are, in fact, Yūsuf?” He said, “I am Yūsuf, and this is my brother. Allah has been very kind to us. Surely, whoever fears Allah and observes patience, Allah does not let the reward of such good people to go to waste.”'),
(1687, 12, 91, 10, 4, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالُوۡا تَاللّٰہِ لَقَدۡ اٰثَرَکَ اللّٰہُ عَلَیۡنَا وَ  اِنۡ کُنَّا لَخٰطِئِیۡنَ ﴿۹۱﴾', 'وہ بولے اللہ کی قسم اللہ نے تم کو ہم پر فضیلت بخشی ہے اور بیشک ہم خطاکار تھے۔', 'بولے قسم اللہ کی البتہ پسند کر لیا تجھ کو اللہ نے ہم سے اور ہم تھے چوکنے والے [۱۳۰]', 'They said: \"By Allah! Indeed Allah has preferred you above us, and we certainly have been sinners.\"', 'They said, “We swear by Allah, indeed Allah has given to you preference over us, and we were guilty in fact.”'),
(1688, 12, 92, 10, 4, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالَ لَا تَثۡرِیۡبَ عَلَیۡکُمُ الۡیَوۡمَ ؕ یَغۡفِرُ اللّٰہُ  لَکُمۡ ۫ وَ ہُوَ اَرۡحَمُ الرّٰحِمِیۡنَ ﴿۹۲﴾', 'یوسف نے کہا کہ آج کے دن تم پر کوئی ملامت نہیں۔ اللہ تم کو معاف کرے۔ اور وہ سب سے بڑھ کر رحم کرنے والا ہے۔', 'کہا کچھ الزام نہیں تم پر آج بخشے اللہ تم کو [۱۳۱] اور وہ ہے سب مہربانوں سے مہربان [۱۳۲]', 'He said: \"No reproach on you this day, may Allah forgive you, and He is the Most Merciful of those who show mercy!', 'He said, “No reproach upon you today! May Allah forgive you, and He is the Most- Merciful of all the merciful.'),
(1689, 12, 93, 10, 4, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'اِذۡہَبُوۡا بِقَمِیۡصِیۡ ہٰذَا فَاَلۡقُوۡہُ عَلٰی وَجۡہِ اَبِیۡ یَاۡتِ بَصِیۡرًا ۚ وَ اۡتُوۡنِیۡ بِاَہۡلِکُمۡ  اَجۡمَعِیۡنَ ﴿٪۹۳﴾', 'یہ میرا کرتہ لے جاؤ پھر اسے والد صاحب کے منہ پر ڈال دینا تو وہ بینا ہو جائیں گے۔ اور اپنے تمام اہل و عیال کو میرے پاس لے آؤ۔', 'لیجاؤ یہ کرتا میرا اور ڈالو اسکو  منہ پر میرے باپ کے کہ چلا آئے آنکھوں سے دیکھتا ہوا اور لے آؤ میرے پاس گھر اپنا سارا [۱۳۳]', '\"Go with this shirt of mine, and cast it over the face of my father, he will become clear-sighted, and bring to me all your family.\"', 'Go with this shirt of mine, and put it over the face of my father, and he will turn into a sighted man. And bring to me all your family.”'),
(1690, 12, 94, 11, 5, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ لَمَّا فَصَلَتِ الۡعِیۡرُ قَالَ اَبُوۡہُمۡ اِنِّیۡ لَاَجِدُ رِیۡحَ یُوۡسُفَ لَوۡ لَاۤ اَنۡ تُفَنِّدُوۡنِ ﴿۹۴﴾', 'اور جب قافلہ مصر سے روانہ ہوا۔ تو انکے والد کہنے لگے کہ اگر مجھ کو یہ نہ کہو کہ بوڑھا بہک گیا ہے تو مجھے تو یوسف کی بو آ رہی ہے۔', 'اور جب جدا ہوا قافلہ کہا انکے باپ نے میں پاتا ہوں بو  یوسف کی [۱۳۴] اگر نہ کہو مجھ کو کہ بوڑھا بہک گیا [۱۳۵]', 'And when the caravan departed, their father said: \"I do indeed feel the smell of Yoosuf (Joseph), if only you think me not a dotard (a person who has weakness of mind because of old age).\"', 'And when the caravan set out (from Egypt), their father (Ya‘qūb) said (in Canaan), “I sense the fragrance of Yūsuf, if you do not take me to be senile.”'),
(1691, 12, 95, 11, 5, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالُوۡا تَاللّٰہِ  اِنَّکَ لَفِیۡ ضَلٰلِکَ الۡقَدِیۡمِ ﴿ٙ۹۵﴾', 'وہ بولے کہ واللہ آپ اسی قدیم غلطی میں مبتلا ہیں۔', 'لوگ بولے قسم اللہ کی تو تو اپنی اسی قدیم غلطی میں ہے [۱۳۶]', 'They said: \"By Allah! Certainly, you are in your old error.\"', 'They said, “By God, you are still in your old fallacy!”'),
(1692, 12, 96, 11, 5, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'فَلَمَّاۤ  اَنۡ جَآءَ الۡبَشِیۡرُ اَلۡقٰىہُ عَلٰی وَجۡہِہٖ فَارۡتَدَّ بَصِیۡرًا ۚ قَالَ اَلَمۡ اَقُلۡ لَّکُمۡ ۚۙ اِنِّیۡۤ اَعۡلَمُ مِنَ اللّٰہِ مَا لَا تَعۡلَمُوۡنَ ﴿۹۶﴾', 'مگر جب خوشخبری دینے والا آ پہنچا تو اس نے کرتہ انکے منہ پر ڈال دیا سو وہ بینا ہو گئے۔ اور بیٹوں سے کہنے لگے۔ کیا میں نے تم سے نہیں کہا تھا کہ میں اللہ کی طرف سے وہ باتیں جانتا ہوں جو تم نہیں جانتے؟', 'پھر جب پہنچا خوشخبری والا ڈالا اس نے وہ کرتا اس کے منہ پر پھر لوٹ کر  ہو گیا دیکھنے والا [۱۳۷] بولا میں نے نہ کہا تھا تم کو کہ میں جانتا ہوں اللہ کی طرف سے جو تم نہیں جانتے [۱۳۸]', 'Then, when the bearer of the glad tidings arrived, he cast it (the shirt) over his face, and he became clear-sighted. He said: \"Did I not say to you, I know from Allah that which you know not. \"', 'So, when came the man with good news, he put it (the shirt) on his face, and he turned into a sighted man. He (Ya‘qūb) said, “Did I not tell you that I know from Allah what you do not know?”'),
(1693, 12, 97, 11, 5, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالُوۡا یٰۤاَبَانَا اسۡتَغۡفِرۡ لَنَا ذُنُوۡبَنَاۤ اِنَّا کُنَّا خٰطِئِیۡنَ ﴿۹۷﴾', 'بیٹوں نے کہا کہ ابا ہمارے لئے ہمارے گناہ کی مغفرت مانگیئے۔ بیشک ہم خطاکار تھے۔', 'بولے اے باپ بخشوا ہمارے گناہوں کو بیشک ہم تھے چوکنے والے [۱۳۹]', 'They said: \"O our father! Ask forgiveness (from Allah) for our sins, indeed we have been sinners.\"', 'They said, “Our father, pray to Allah to forgive us our sins. Surely, we have been guilty.”'),
(1694, 12, 98, 11, 5, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قَالَ سَوۡفَ اَسۡتَغۡفِرُ لَکُمۡ رَبِّیۡ ؕ اِنَّہٗ ہُوَ  الۡغَفُوۡرُ  الرَّحِیۡمُ ﴿۹۸﴾', 'فرمایا میں اپنے پروردگار سے تمہارے لئے بخشش مانگوں گا۔ بیشک وہ بخشنے والا ہے مہربان ہے۔', 'کہا دم لو بخشواؤں گا تم کو اپنے رب سے وہی ہے بخشنے والا مہربان [۱۴۰]', 'He said: \"I will ask my Lord for forgiveness for you, verily He! Only He is the Oft-Forgiving, the Most Merciful.\"', 'He said, “I shall pray to my Lord to forgive you. Surely, He is the Most-Forgiving, Very-Merciful.”'),
(1695, 12, 99, 11, 5, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'فَلَمَّا دَخَلُوۡا عَلٰی یُوۡسُفَ اٰوٰۤی اِلَیۡہِ اَبَوَیۡہِ وَ قَالَ ادۡخُلُوۡا مِصۡرَ اِنۡ شَآءَ اللّٰہُ   اٰمِنِیۡنَ ﴿ؕ۹۹﴾', 'پھر جب یہ سب لوگ یوسف کے پاس پہنچے تو انہوں نے اپنے والدین کو اپنے پاس جگہ دی اور کہا مصر میں داخل ہو جایئے اللہ نے چاہا تو امن و امان سے رہیے گا۔', 'پھر جب داخل ہوئے یوسف کے پاس جگہ دی اپنے پاس ماں باپ کو اور کہا داخل ہو مصر میں اللہ نے چاہا تو دل جمعی سے [۱۴۱]', 'Then, when they entered unto Yoosuf (Joseph), he betook his parents to himself and said: \"Enter Egypt, if Allah wills, in security.\"', 'Later, when they came to Yūsuf, he placed his parents near himself and said, “Enter Egypt, God willing, in peace.”'),
(1696, 12, 100, 11, 5, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ رَفَعَ اَبَوَیۡہِ عَلَی الۡعَرۡشِ وَ خَرُّوۡا لَہٗ سُجَّدًا ۚ وَ قَالَ یٰۤاَبَتِ ہٰذَا تَاۡوِیۡلُ رُءۡیَایَ مِنۡ قَبۡلُ ۫ قَدۡ جَعَلَہَا رَبِّیۡ حَقًّا ؕ وَ قَدۡ  اَحۡسَنَ  بِیۡۤ   اِذۡ  اَخۡرَجَنِیۡ مِنَ السِّجۡنِ وَ جَآءَ بِکُمۡ مِّنَ الۡبَدۡوِ مِنۡۢ بَعۡدِ اَنۡ  نَّزَغَ  الشَّیۡطٰنُ  بَیۡنِیۡ وَ بَیۡنَ اِخۡوَتِیۡ ؕ اِنَّ رَبِّیۡ  لَطِیۡفٌ لِّمَا یَشَآءُ ؕ اِنَّہٗ  ہُوَ  الۡعَلِیۡمُ  الۡحَکِیۡمُ ﴿۱۰۰﴾', 'اور اپنے والدین کو تخت پر بٹھایا اور سب انکے آگے سجدے میں گر پڑے اور اس وقت یوسف نے کہا ابا جان یہ میرے اس خواب کی تعبیر ہے جو میں نے پہلے بچپن میں دیکھا تھا۔ میرے پروردگار نے اسے سچ کر دیا۔ اور اس نے مجھ پر بہت سے احسان کئے ہیں کہ مجھ کو قید خانے سے نکالا۔ اور اسکے بعد کہ شیطان نے مجھ میں اور میرے بھائیوں میں فساد ڈال دیا تھا آپ کو گاؤں سے یہاں لایا۔ بیشک میرا پروردگار جو چاہتا ہے تدبیر سے کرتا ہے وہ علم والا ہے حکمت والا ہے۔', 'اور اونچا بٹھایا اپنے ماں باپ کو تخت پر اور سب گرے اس کے آگے سجدہ میں [۱۴۲] اور کہا اے باپ یہ بیان ہے میرے اس پہلے خواب کا اس کو میرے رب نے سچ کر دیا [۱۴۳] اور اس نے انعام کیا مجھ پر جب مجھ کو نکالا قید خانہ سے اور تم کو لے آیا گاؤں سے بعد اس کے کہ جھگڑا ڈال چکا تھا شیطان مجھ میں اور میرے بھائیوں میں میرا رب تدبیر سے کرتا ہے جو چاہتا ہے بیشک وہی ہے خبردار حکمت والا [۱۴۴]', 'And he raised his parents to the throne and they fell down before him prostrate. And he said: \"O my father! This is the interpretation of my dream aforetime! My Lord has made it come true! He was indeed good to me, when He took me out of the prison, and brought you (all here) out of the bedouin-life, after Shaitan (Satan) had sown enmity between me and my brothers. Certainly, my Lord is the Most Courteous and Kind unto whom He will. Truly He! Only He is the All-Knowing, the All-Wise.', 'And he raised his parents up on the throne, and they all fell before him in prostration. He said, “My father, here is the fulfillment of my early dream. My Lord has made it come true. He favored me when he released me from the prison, and brought you from the countryside after Satan had caused a rift between me and my brothers. Surely, my Lord does what He wills in a subtle way. Surely, He is the All-Knowing, the All-Wise.”'),
(1697, 12, 101, 11, 5, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'رَبِّ قَدۡ اٰتَیۡتَنِیۡ مِنَ الۡمُلۡکِ وَ عَلَّمۡتَنِیۡ مِنۡ تَاۡوِیۡلِ الۡاَحَادِیۡثِ ۚ فَاطِرَ السَّمٰوٰتِ وَ الۡاَرۡضِ ۟ اَنۡتَ وَلِیّٖ فِی الدُّنۡیَا وَ الۡاٰخِرَۃِ ۚ تَوَفَّنِیۡ مُسۡلِمًا وَّ اَلۡحِقۡنِیۡ  بِالصّٰلِحِیۡنَ ﴿۱۰۱﴾', 'جب یہ سب باتیں ہو لیں تو یوسف نے اللہ سے دعا کی کہ اے میرے پروردگار تو نے مجھ کو حکومت سے نوازا اور خوابوں کی تعبیر کا علم بخشا۔ اے آسمانوں اور زمین کے پیدا کرنے والے تو ہی دنیا اور آخرت میں میرا کارساز ہے۔ تو مجھے دنیا سے اپنی اطاعت کی حالت میں اٹھائیو اور آخرت میں اپنے نیک بندوں میں داخل کیجیو۔', 'اے رب تو نے دی مجھ کو کچھ حکومت اور سکھایا مجھ کو کچھ پھیرنا باتوں کا [۱۴۵] اے پیدا کرنے والے آسمان اور زمین کے تو ہی میرا کارساز ہے دنیا میں اور آخرت میں موت دے مجھ کو اسلام پر [۱۴۶] اور ملا مجھ کو نیک بختوں میں [۱۴۷]', '\"My Lord! You have indeed bestowed on me of the sovereignty, and taught me the interpretation of dreams; The (only) Creator of the heavens and the earth! You are my Walee (Protector, Helper, Supporter, Guardian, etc.) in this world and in the Hereafter, cause me to die as a Muslim (the one submitting to Your Will), and join me with the righteous.\"', '“My Lord, You have given me power to rule and the knowledge of interpreting events. O Creator of the heavens and the Earth, You are my guardian in this world and the Hereafter. Make me die a Muslim and make me join the righteous.”'),
(1698, 12, 102, 11, 5, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'ذٰلِکَ  مِنۡ  اَنۡۢبَآءِ الۡغَیۡبِ نُوۡحِیۡہِ  اِلَیۡکَ ۚ وَ مَا کُنۡتَ لَدَیۡہِمۡ  اِذۡ  اَجۡمَعُوۡۤا  اَمۡرَہُمۡ  وَ ہُمۡ  یَمۡکُرُوۡنَ ﴿۱۰۲﴾', 'اے پیغمبر یہ اخبار غیب میں سے ہیں جو ہم تمہاری طرف بھیجتے ہیں۔ اور جب برادران یوسف نے اپنی بات پر اتفاق کیا تھا اور وہ فریب کر رہے تھے تو تم انکے پاس تو نہ تھے۔', 'یہ خبریں ہیں غیب کی ہم بھیجتے ہیں تیرے پاس اور تو نہیں تھا انکے پاس جب وہ ٹھہرانے لگے اپنا کام اور فریب کرنے لگے [۱۴۸]', 'This is of the news of the Ghaib (unseen) which We reveal by Inspiration to you (O Muhammad SAW ). You were not (present) with them when they arranged their plan together, and (also, while) they were plotting.', 'That is a part of the reports of the unseen We reveal to you (O Prophet). You were not with them when they determined their object, and when they were planning devices.'),
(1699, 12, 103, 11, 5, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ مَاۤ  اَکۡثَرُ النَّاسِ وَ لَوۡ حَرَصۡتَ بِمُؤۡمِنِیۡنَ ﴿۱۰۳﴾', 'اور بہت سے آدمی گو تم کتنی ہی خواہش کرو ایمان لانے والے نہیں ہیں۔', 'اور اکثر لوگ نہیں ہیں یقین کرنے والے اگرچہ تو کتنا ہی چاہے [۱۴۹]', 'And most of mankind will not believe even if you desire it eagerly.', 'Most of the people are not going to believe despite your strong desire for it.'),
(1700, 12, 104, 11, 5, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ مَا تَسۡـَٔلُہُمۡ عَلَیۡہِ مِنۡ اَجۡرٍ ؕ اِنۡ ہُوَ اِلَّا ذِکۡرٌ  لِّلۡعٰلَمِیۡنَ ﴿۱۰۴﴾٪', 'اور تم ان سے اس خیرخواہی کا کچھ صلہ بھی تو نہیں مانگتے یہ قرآن اور کچھ نہیں تمام جہانوں کے لئے نصیحت ہے۔', 'اور تو مانگتا نہیں ان سے اس پر کچھ بدلا یہ تو اور کچھ نہیں مگر نصیحت سارے عالم کو [۱۵۰]', 'And no reward you (O Muhammad SAW) ask of them (those who deny your Prophethood) for it, it(the Quran) is no less than a Reminder and an advice unto the Alameen (men and jinns).', 'And you do not demand from them any reward against it. It is nothing but a reminder for all the (people of the) worlds.'),
(1701, 12, 105, 12, 6, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ کَاَیِّنۡ مِّنۡ اٰیَۃٍ  فِی السَّمٰوٰتِ وَ الۡاَرۡضِ یَمُرُّوۡنَ عَلَیۡہَا وَ ہُمۡ عَنۡہَا مُعۡرِضُوۡنَ ﴿۱۰۵﴾', 'اور آسمان و زمین میں بہت سی نشانیاں ہیں جن پر سے یہ گذرتے ہیں اور انکو نظرانداز کر دیتے ہیں۔', 'اور بہتیری نشانیاں ہیں آسمان اور زمین میں جن پر گذر ہوتا رہتا ہے ان کا اور وہ ان پر دھیان نہیں کرتے [۱۵۱]', 'And how many a sign in the heavens and the earth they pass by, while they are averse therefrom.', 'How many a sign there are in the heavens and the Earth, which they pass by and they are heedless to them;'),
(1702, 12, 106, 12, 6, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ مَا یُؤۡمِنُ اَکۡثَرُہُمۡ بِاللّٰہِ  اِلَّا وَ ہُمۡ مُّشۡرِکُوۡنَ ﴿۱۰۶﴾', 'اور یہ اکثر اللہ پر ایمان نہیں رکھتے۔ مگر اسکے ساتھ شرک بھی کرتے ہیں۔', 'اور نہیں ایمان لاتے بہت لوگ اللہ پر مگر ساتھ ہی شریک بھی کرتے ہیں [۱۵۲]', 'And most of them believe not in Allah except that they attribute partners unto Him (i.e. they are Mushrikoon -polytheists - see Verse 6: 121).', 'and most of them do not believe in Allah without associating partners with Him in His divinity.'),
(1703, 12, 107, 12, 6, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'اَفَاَمِنُوۡۤا اَنۡ تَاۡتِیَہُمۡ غَاشِیَۃٌ مِّنۡ عَذَابِ اللّٰہِ  اَوۡ  تَاۡتِیَہُمُ السَّاعَۃُ بَغۡتَۃً   وَّ ہُمۡ  لَا  یَشۡعُرُوۡنَ ﴿۱۰۷﴾', 'تو کیا یہ اس بات سے بےخوف ہیں کہ ان پر اللہ کا عذاب نازل ہو کر انکو ڈھانپ لے یا ان پر ناگہاں قیامت آ جائے اور انہیں خبر بھی نہ ہو۔', 'کیا نڈر ہو گئے اس سے کہ آ ڈھانکے انکو ایک آفت اللہ کے عذاب کی یا آ پہنچے قیامت اچانک اور انکو خبر نہ ہو [۱۵۳]', 'Do they then feel secure from the coming against them of the covering veil of the Torment of Allah, or of the coming against them of the (Final) Hour, all of a sudden while they perceive not?', 'Do they feel themselves secure from the visit of Allah’s encircling punishment or from the sudden arrival of the Hour, while they are not conscious of it?'),
(1704, 12, 108, 12, 6, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'قُلۡ ہٰذِہٖ سَبِیۡلِیۡۤ  اَدۡعُوۡۤا  اِلَی اللّٰہِ ۟ؔ عَلٰی بَصِیۡرَۃٍ  اَنَا  وَ مَنِ اتَّبَعَنِیۡ ؕ وَ سُبۡحٰنَ اللّٰہِ  وَ مَاۤ   اَنَا مِنَ  الۡمُشۡرِکِیۡنَ ﴿۱۰۸﴾', 'کہدو میرا رستہ تو یہ ہے۔ میں اللہ کی طرف بلاتا ہوں سمجھ بوجھ کر۔ میں بھی لوگوں کو اللہ کی طرف بلاتا ہوں اور میرے پیرو بھی۔ اور اللہ پاک ہے اور میں شرک کرنے والوں میں سے نہیں ہوں۔', 'کہہ دے یہ میری راہ ہے بلاتا ہوں اللہ کی طرف سمجھ بوجھ کر میں اور جو میرے ساتھ ہے اور اللہ پاک ہے اور میں نہیں شریک بتانے والوں میں [۱۵۴]', 'Say (O Muhammad SAW): \"This is my way; I invite unto Allah (i.e. to the Oneness of Allah - Islamic Monotheism) with sure knowledge, I and whosoever follows me (also must invite others to Allah i.e to the Oneness of Allah - Islamic Monotheism) with sure knowledge. And Glorified and Exalted be Allah (above all that they associate as partners with Him). And I am not of the Mushrikoon (polytheists, pagans, idolaters and disbelievers in the Oneness of Allah; those who worship others along with Allah or set up rivals or partners to Allah).\"', 'Say, “This is my way. I call (people) to Allah with full perception, both I and my followers. Pure is Allah; and I am not among those who associate partners with Allah.”'),
(1705, 12, 109, 12, 6, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'وَ مَاۤ  اَرۡسَلۡنَا مِنۡ قَبۡلِکَ اِلَّا رِجَالًا نُّوۡحِیۡۤ  اِلَیۡہِمۡ مِّنۡ اَہۡلِ الۡقُرٰی ؕ اَفَلَمۡ یَسِیۡرُوۡا فِی الۡاَرۡضِ فَیَنۡظُرُوۡا کَیۡفَ کَانَ عَاقِبَۃُ  الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ ؕ وَ لَدَارُ الۡاٰخِرَۃِ خَیۡرٌ لِّلَّذِیۡنَ اتَّقَوۡا ؕ اَفَلَا  تَعۡقِلُوۡنَ ﴿۱۰۹﴾', 'اور ہم نے تم سے پہلے بستیوں کے رہنے والوں میں سے مرد ہی بھیجے تھے جنکی طرف ہم وحی بھیجتے تھے کیا ان لوگوں نے ملک میں سیروسیاحت نہیں کی کہ دیکھ لیتے کہ جو لوگ ان سے پہلے تھے ان کا انجام کیا ہوا۔ اور متقیوں کے لئے آخرت کا گھر بہت اچھا ہے کیا تم سمجھتے نہیں؟', 'اور جتنے بھیجے ہم نے تجھ سے پہلے وہ سب مرد ہی تھے کہ وحی بھیجتے تھے ہم انکو بستیوں کے رہنے والے سو کیا ان لوگوں نے نہیں سیر کی ملک کی کہ دیکھ لیتے کیسا ہوا انجام ان لوگوں کا جو ان سے پہلے تھے اور آخرت کا گھر تو بہتر ہے پرہیز کرنے والوں کو کیا اب بھی نہیں سمجھتے [۱۵۵]', 'And We sent not before you (as Messengers) any but men, whom We inspired from among the people of townships. Have they not travelled through the earth and seen what was the end of those who were before them? And verily, the home of the Hereafter is the best for those who fear Allah and obey Him (by abstaining from sins and evil deeds, and by performing righteous good deeds). Do you not then understand?', 'We did not send before you (messengers) other than men from the people of the towns whom We inspired with revelation. Have they not traveled in the land where they could have seen how was the fate of those before them? And surely the abode of the Hereafter is much better for those who fear Allah. Would you, then, still not understand?'),
(1706, 12, 110, 12, 6, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'حَتّٰۤی اِذَا اسۡتَیۡـَٔسَ الرُّسُلُ وَ ظَنُّوۡۤا اَنَّہُمۡ قَدۡ کُذِبُوۡا جَآءَہُمۡ نَصۡرُنَا ۙ فَنُجِّیَ مَنۡ  نَّشَآءُ ؕ وَلَا  یُرَدُّ بَاۡسُنَا عَنِ الۡقَوۡمِ  الۡمُجۡرِمِیۡنَ ﴿۱۱۰﴾', 'یہاں تک کہ جب پیغمبر ناامید ہوگئے اور انہوں نے خیال کیا کہ اپنی نصرت کے بارے میں جو بات انہوں نے کہی تھی اس میں وہ سچے نہ نکلے تو انکے پاس ہماری مدد آ پہنچی۔ پھر جسے ہم نے چاہا بچا دیا اور ہمارا عذاب اتر کر گناہگار لوگوں سے پھرا نہیں کرتا۔', 'یہاں تک کہ جب ناامید ہونے لگے رسول اور خیال کرنے لگے کہ ان سے جھوٹ کہا گیا تھا پہنچی انکو ہماری مدد پھر بچا دیا جنکو ہم نے چاہا اور پھرتا نہیں عذاب ہمارا قوم گنہگار سے [۱۵۶]', '(They were reprieved) until, when the Messengers gave up hope and thought that they were denied (by their people), then came to them Our Help, and whomsoever We willed were delivered. And Our Punishment cannot be warded off from the people who are Mujrimoon (criminals, disobedients to Allah, sinners, disbelievers, polytheists).', '(Punishment was often delayed) until when the messengers were in despair and thought that they were wrong in their estimation, Our help came to them, then saved were those whom We willed. And Our punishment is not averted from the guilty.'),
(1707, 12, 111, 12, 6, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'یوسف', 'لَقَدۡ کَانَ فِیۡ قَصَصِہِمۡ عِبۡرَۃٌ  لِّاُولِی الۡاَلۡبَابِ ؕ مَا کَانَ حَدِیۡثًا یُّفۡتَرٰی وَ لٰکِنۡ تَصۡدِیۡقَ الَّذِیۡ بَیۡنَ یَدَیۡہِ وَ تَفۡصِیۡلَ کُلِّ شَیۡءٍ وَّ ہُدًی وَّ رَحۡمَۃً لِّقَوۡمٍ  یُّؤۡمِنُوۡنَ ﴿۱۱۱﴾٪', 'ان کے قصے میں عقلمندوں کے لئے عبرت ہے۔ یہ قرآن ایسی بات نہیں ہے جو اپنے دل سے بنائی گئ ہو بلکہ جو کتابیں اس سے پہلے نازل ہوئی ہیں انکی تصدیق کرنے والا ہے اور ہر چیز کی تفصیل کرنے والا اور مومنوں کے لئے ہدایت اور رحمت ہے۔', 'البتہ انکے احوال سے اپنا حال قیاس کرنا ہے عقل والوں کو [۱۵۷] کچھ بنائی ہوئی بات نہیں لیکن موافق ہے اس کلام کے جو اس سے پہلے ہے اور بیان ہر چیز کا اور ہدایت اور رحمت ان لوگوں کو جو ایمان لاتے ہیں [۱۵۸]', 'Indeed in their stories, there is a lesson for men of understanding. It (the Quran) is not a forged statement but a confirmation of the Allahs existing Books (the Taurat (Torah), the Injeel (Gospel) and other Scriptures of Allah) and a detailed explanation of everything and a guide and a Mercy for the people who believe.', 'Surely, in the narratives of these, there is a lesson for the people of understanding. It is not an invented story, rather, a confirmation of what has been before it, and an elaboration of everything, and guidance and mercy for a people who believe.'),
(1708, 13, 1, 1, 7, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'الٓـمّٓرٰ ۟ تِلۡکَ اٰیٰتُ الۡکِتٰبِ ؕ وَ الَّذِیۡۤ اُنۡزِلَ اِلَیۡکَ مِنۡ رَّبِّکَ الۡحَقُّ وَ لٰکِنَّ اَکۡثَرَ  النَّاسِ لَا  یُؤۡمِنُوۡنَ ﴿۱﴾', 'الٓمرا۔  اے نبی یہ کتاب الٰہی کی آیتیں ہیں۔ اور جو کچھ تمہارے پروردگار کی طرف سے تم پر نازل ہوا ہے حق ہے لیکن اکثر لوگ ایمان نہیں لاتے۔', 'یہ آیتیں ہیں کتاب کی اور جو کچھ اترا تجھ پر تیرے رب سے سو حق ہے لیکن بہت لوگ نہیں مانتے [۱]', 'Alif-Lam-Meem-Ra. (These letters are one of the miracles of the Quran and none but Allah (Alone) knows their meanings).These are the Verses of the Book (the Quran), and that which has been revealed unto you (Muhammad SAW) from your Lord is the truth, but most men believe not.', 'Alif , Lām , Mīm , Rā. These are the verses of the Book. What has been sent down to you from your Lord is true, but most of the people do not believe.'),
(1709, 13, 2, 1, 7, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'اَللّٰہُ الَّذِیۡ رَفَعَ السَّمٰوٰتِ بِغَیۡرِ عَمَدٍ تَرَوۡنَہَا ثُمَّ  اسۡتَوٰی عَلَی الۡعَرۡشِ وَ سَخَّرَ الشَّمۡسَ وَ الۡقَمَرَ ؕ کُلٌّ یَّجۡرِیۡ لِاَجَلٍ مُّسَمًّی ؕ یُدَبِّرُ الۡاَمۡرَ یُفَصِّلُ الۡاٰیٰتِ لَعَلَّکُمۡ بِلِقَآءِ رَبِّکُمۡ تُوۡقِنُوۡنَ ﴿۲﴾', 'اللہ وہی تو ہے جس نے ستونوں کے بغیر آسمان جیسا کہ تم دیکھتے ہو اتنے اونچے بنائے۔ پھر عرش پر جلوہ افروز ہوا اور سورج اور چاند کو کام میں لگا دیا۔ ہر ایک ایک میعاد معین تک گردش کر رہا ہے وہی دنیا کے کاموں کا انتظام کرتا ہے اس طرح وہ اپنی آیتیں کھول کھول کر بیان کرتا ہے کہ تم اپنے پروردگار کے روبرو جانے کا یقین کرو۔', 'اللہ وہ ہے جس نے اونچے بنائے آسمان بغیر ستون دیکھتے ہو [۲] پھر قائم ہوا عرش پر [۳] اور کام میں لگا دیا سورج اور چاند کو ہر ایک چلتا ہے وقت مقرر پر (تک) [۴] تدبیر کرتا ہے کام کی ظاہر کرتا ہے نشانیاں کہ (تاکہ) شاید تم اپنے رب سے ملنے کا یقین کرو [۵]', 'Allah is He Who raised the heavens without any pillars that you can see. Then, He Istawa (rose above) the Throne (really in a manner that suits His Majesty). He has subjected the sun and the moon (to continue going round)! Each running (its course) for a term appointed. He regulates all affairs, explaining the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) in detail, that you may believe with certainty in the meeting with your Lord.', 'Allah is the One who raised the heavens without pillars that you can see them. Then He positioned Himself on the Throne and subjugated the sun and the moon, each one of them running to an appointed time. He manages all matters, elaborating the signs, so that you may be sure of meeting your Lord.'),
(1710, 13, 3, 1, 7, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ ہُوَ الَّذِیۡ مَدَّ الۡاَرۡضَ وَ جَعَلَ  فِیۡہَا رَوَاسِیَ وَ اَنۡہٰرًا ؕ وَ مِنۡ کُلِّ الثَّمَرٰتِ جَعَلَ فِیۡہَا زَوۡجَیۡنِ اثۡنَیۡنِ یُغۡشِی الَّیۡلَ النَّہَارَ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیٰتٍ لِّقَوۡمٍ  یَّتَفَکَّرُوۡنَ ﴿۳﴾', 'اور وہ وہی ہے جس نے زمین کو پھیلایا اور اس میں پہاڑ اور دریا پیدا کئے۔ اور ہر طرح کے میووں کی دو دو قسمیں بنائیں وہی رات کو دن کا لباس پہناتا ہے۔ غور کرنے والوں کے لئے اس میں بہت سی نشانیاں ہیں۔', 'اور وہی ہے جس نے پھیلائی زمین اور رکھے اس میں بوجھ (پہاڑ) اور ندیاں  [۶] اور ہر میوے کے رکھے اس میں جوڑے دو دو قسم [۷] ڈھانکتا ہے دن پر رات کو [۸] اس میں نشانیاں ہیں انکے واسطے جو کہ دھیان کرتے ہیں', 'And it is He Who spread out the earth, and placed therein firm mountains and rivers and of every kind of fruits He made Zawjain Ithnaeen (two in pairs - may mean two kinds or it may mean: of two sorts, e.g. black and white, sweet and sour, small and big, etc.) He brings the night as a cover over the day. Verily, in these things, there are Ayat (proofs, evidences, lessons, signs, etc.) for people who reflect.', 'He is the One who spread out the earth and made mountains and rivers on it, and created in it the pairs of two from all the fruits. He makes the night cover the day. Surely, in that there are signs for a people who think.'),
(1711, 13, 4, 1, 7, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ فِی الۡاَرۡضِ قِطَعٌ مُّتَجٰوِرٰتٌ وَّ جَنّٰتٌ مِّنۡ اَعۡنَابٍ وَّ زَرۡعٌ وَّ نَخِیۡلٌ صِنۡوَانٌ وَّ غَیۡرُ صِنۡوَانٍ یُّسۡقٰی بِمَآءٍ وَّاحِدٍ ۟ وَ نُفَضِّلُ بَعۡضَہَا عَلٰی بَعۡضٍ فِی الۡاُکُلِ ؕ اِنَّ فِیۡ ذٰلِکَ  لَاٰیٰتٍ  لِّقَوۡمٍ  یَّعۡقِلُوۡنَ ﴿۴﴾', 'اور زمین میں کئ طرح کے قطعات ہیں۔ ایک دوسرے سے ملے ہوئے۔ اور انگور کے باغ اور کھیتی اور کھجور کے درخت۔ بعض کی بہت سی شاخیں ہیں اور بعض کی اتنی نہیں ہوتیں باوجودیکہ پانی سب کو ایک ہی ملتا ہے اور ہم بعض میووں کو بعض پر لذت میں فضیلت دیتے ہیں اور اس میں سمجھنے والوں کے لئے بہت سی نشانیاں ہیں۔', 'اور زمین میں کھیت ہیں مختلف ایک دوسرے (پاس پاس) سے متصل اور باغ ہیں انگور کے اور کھیتیاں ہیں اور کھجوریں ہیں ایک کی جڑ دوسری سے ملی ہوئی اور بعضی بن ملی انکو پانی بھی ایک ہی دیا جاتا ہے اور ہم ہیں کہ بڑھا دیتے ہیں ان میں ایک کو ایک سے میووں میں ان چیزوں میں نشانیاں ہیں انکو جو غور کرتے ہیں [۹]', 'And in the earth are neighbouring tracts, and gardens of vines, and green crops (fields etc.), and date-palms, growing out two or three from a single stem root, or otherwise (one stem root for every palm ), watered with the same water, yet some of them We make more excellent than others to eat. Verily, in these things, there are Ayat (proofs, evidences, lessons, signs) for the people who understand.', 'And in the earth there are tracts of land neighboring each other, and gardens of grapes, and farms and date palms, some having twin trunks and some having a single one. (Although) all of them are irrigated with the same water, We make some of them better than others in taste. Surely, in that there are signs for a people who understand.'),
(1712, 13, 5, 1, 7, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ اِنۡ تَعۡجَبۡ فَعَجَبٌ قَوۡلُہُمۡ ءَ اِذَا کُنَّا تُرٰبًا ءَ اِنَّا لَفِیۡ خَلۡقٍ جَدِیۡدٍ ۬ؕ اُولٰٓئِکَ الَّذِیۡنَ  کَفَرُوۡا بِرَبِّہِمۡ ۚ وَ اُولٰٓئِکَ  الۡاَغۡلٰلُ فِیۡۤ  اَعۡنَاقِہِمۡ ۚ وَ اُولٰٓئِکَ اَصۡحٰبُ  النَّارِ ۚ ہُمۡ  فِیۡہَا  خٰلِدُوۡنَ ﴿۵﴾', 'اگر تم عجیب بات سننی چاہو۔ تو کافروں کا یہ کہنا عجیب ہے کہ جب ہم مر کر مٹی ہو جائیں گے تو کیا از سرنو پیدا ہوں گے؟ یہی لوگ ہیں جو اپنے پروردگار سے منکر ہوئے ہیں۔ اور یہی ہیں جنکی گردنوں میں طوق ہوں گے۔ اور یہی اہل دوزخ ہیں کہ ہمیشہ اس میں جلتے رہیں گے۔', 'اور اگر تو عجیب بات چاہے تو عجیب ہے ان کا کہنا کہ کیا جب ہو گئے ہم مٹی کیا نئے سرے سے بنائے جائیں گے [۱۰] وہی ہیں جو منکر ہو گئے اپنے رب سے اور وہی ہیں کہ طوق ہیں انکی گردنوں میں اور وہ ہیں دوزخ والے وہ اسی میں رہیں گے برابر [۱۱]', 'And if you (O Muhammad SAW) wonder (at these polytheists who deny your message of Islamic Monotheism and have taken besides Allah others for worship who can neither harm nor benefit), then wondrous is their saying: \"When we are dust, shall we indeed then be (raised) in a new creation?\" They are those who disbelieve in their Lord! They are those who will have iron chains tying their hands to their necks. They will be dwellers of the Fire to abide therein.', 'If you wonder, then wondrous indeed is their saying, “Is it that, once we are dust, we are to be created anew?” They are those who have disbelieved in their Lord, and they are those who (shall) have shackles around their necks, and they are the people of the Fire. They shall remain there forever.'),
(1713, 13, 6, 1, 7, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ یَسۡتَعۡجِلُوۡنَکَ بِالسَّیِّئَۃِ قَبۡلَ الۡحَسَنَۃِ وَ قَدۡ خَلَتۡ مِنۡ قَبۡلِہِمُ الۡمَثُلٰتُ ؕ وَ اِنَّ رَبَّکَ لَذُوۡ مَغۡفِرَۃٍ  لِّلنَّاسِ عَلٰی ظُلۡمِہِمۡ ۚ وَ اِنَّ رَبَّکَ لَشَدِیۡدُ  الۡعِقَابِ ﴿۶﴾', 'اور یہ لوگ بھلائی سے پہلے تم سے برائی جلدی سے مانگتے ہیں یعنی طالب عذاب ہیں حالانکہ ان سے پہلے عذاب واقع ہو چکے ہیں۔ اور تمہارا پروردگار لوگوں کو باوجود انکی بےانصافیوں کے معاف کرنے والا ہے۔ اور بیشک تمہارا پروردگار سخت عذاب دینے والا ہے۔', 'اور جلد مانگتے ہیں تجھ سے برائی کو پہلے بھلائی سے [۱۲] اور گذر چکے ہیں ان سے پہلے بہت سے عذاب (مثالیں) اور تیرا رب معاف بھی کرتا ہے لوگوں کو باوجود انکے ظلم کے اور تیرے رب کا عذاب بھی سخت ہے [۱۳]', 'They ask you to hasten the evil before the good, yet (many) exemplary punishments have indeed occurred before them. But verily, your Lord is full of Forgiveness for mankind inspite of their wrong-doing. And verily, your Lord is (also) Severe in punishment.', 'They ask for evil to come sooner than good, while punishments have really come to pass (against people) earlier to them. And surely, your Lord is the lord of forgiveness for the people against their wrongdoing, and surely, your Lord is severe in punishing.'),
(1714, 13, 7, 1, 7, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ  یَقُوۡلُ  الَّذِیۡنَ  کَفَرُوۡا لَوۡ لَاۤ  اُنۡزِلَ عَلَیۡہِ اٰیَۃٌ  مِّنۡ رَّبِّہٖ ؕ اِنَّمَاۤ  اَنۡتَ مُنۡذِرٌ وَّ  لِکُلِّ  قَوۡمٍ  ہَادٍ ٪﴿۷﴾', 'اور کافر لوگ کہتے ہیں کہ اس پیغمبر پر اسکے پروردگار کی طرف سے کوئی نشانی کیوں نازل نہیں ہوئی۔ اے نبی تم تو صرف خبردار کرنے والے ہو اور ہر ایک قوم کے لئے راہنما ہوا کرتا ہے۔', 'اور کہتے ہیں کافر کیوں نہ اتری اس پر کوئی نشانی اسکے رب سے [۱۴] تیرا کام تو ڈر سنا دینا ہے اور ہر قوم کے لئے ہوا ہے راہ بتانے والا [۱۵]', 'And the disbelievers say: \"Why is not a sign sent down to him from his Lord?\" You are only a warner, and to every people there is a guide.', 'The disbelievers say, “Why is it that no sign has been sent down to him from his Lord?” You are but a warner; and for every people there is a guide.'),
(1715, 13, 8, 2, 8, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'اَللّٰہُ یَعۡلَمُ مَا تَحۡمِلُ کُلُّ اُنۡثٰی وَ مَا تَغِیۡضُ الۡاَرۡحَامُ وَ  مَا تَزۡدَادُ ؕ وَ کُلُّ شَیۡءٍ عِنۡدَہٗ  بِمِقۡدَارٍ ﴿۸﴾', 'اللہ ہی اس بچے سے واقف ہے جو عورت کے پیٹ میں ہوتا ہے اور وہی پیٹ کے سکڑنے اور بڑھنے سے بھی واقف ہے اور ہرچیز کا اسکے ہاں ایک اندازہ مقرر ہے۔', 'اللہ جانتا ہے جو پیٹ میں رکھتی ہے ہر مادہ [۱۶] اور جو سکڑتے ہیں پیٹ اور بڑھتے ہیں اور ہر چیز کا اس کے  یہاں اندازہ ہے  [۱۷]', 'Allah knows what every female bears, and by how much the wombs fall short (of their time or number) or exceed. Everything with Him is in (due) proportion.', 'Allah knows what every female carries and what the wombs decrease or increase. Everything has measure with Him'),
(1716, 13, 9, 2, 8, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'عٰلِمُ الۡغَیۡبِ وَ الشَّہَادَۃِ  الۡکَبِیۡرُ الۡمُتَعَالِ ﴿۹﴾', 'وہ چھپی اور ظاہر چیزوں کا جاننے والا ہے۔ سب سے بزرگ ہے عالی رتبہ ہے۔', 'جاننے والا پوشیدہ اور ظاہر کا سب سے بڑا برتر [۱۸]', 'All-Knower of the unseen and the seen, the Most Great, the Most High.', 'He is the Knower of the hidden and the manifest. He is the Great, the High.'),
(1717, 13, 10, 2, 8, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'سَوَآءٌ  مِّنۡکُمۡ مَّنۡ اَسَرَّ الۡقَوۡلَ وَ مَنۡ جَہَرَ بِہٖ وَ مَنۡ ہُوَ مُسۡتَخۡفٍۭ بِالَّیۡلِ وَ سَارِبٌۢ  بِالنَّہَارِ ﴿۱۰﴾', 'کوئی تم میں سے چپکے سے بات کہے یا پکار کر۔ یا رات کو کہیں چھپ جائے یا دن کی روشنی میں کھلم کھلا چلے پھرے اللہ کے نزدیک برابر ہے۔', 'برابر ہے تم میں جو آہستہ بات کہے اور جو کہے پکار کر اور جو چھپ رہا ہے رات میں اور جو گلیوں میں پھرتا ہے دن کو [۱۹]', 'It is the same (to Him) whether any of you conceal his speech or declare it openly, whether he be hid by night or go forth freely by day.', 'Alike (for Him) is he, from among you, who speaks quietly and he who speaks aloud, and he who hides in the night and he who walks out in the day.'),
(1718, 13, 11, 2, 8, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'لَہٗ  مُعَقِّبٰتٌ مِّنۡۢ بَیۡنِ یَدَیۡہِ وَ مِنۡ خَلۡفِہٖ  یَحۡفَظُوۡنَہٗ  مِنۡ اَمۡرِ اللّٰہِ ؕ اِنَّ اللّٰہَ  لَا یُغَیِّرُ مَا بِقَوۡمٍ حَتّٰی یُغَیِّرُوۡا مَا بِاَنۡفُسِہِمۡ ؕ وَ  اِذَاۤ   اَرَادَ  اللّٰہُ بِقَوۡمٍ سُوۡٓءًا فَلَا مَرَدَّ  لَہٗ ۚ وَ مَا لَہُمۡ  مِّنۡ  دُوۡنِہٖ مِنۡ  وَّالٍ ﴿۱۱﴾', 'اسکے آگے اور پیچھے اللہ کے چوکیدار ہیں جو اللہ کے حکم سے اسکی نگرانی کرتے ہیں۔ اللہ اس نعمت کو جو کسی قوم کو حاصل ہے نہیں بدلتا جب تک کہ وہ اپنی حالت کو نہ بدلے۔ اور جب اللہ کسی قوم کے ساتھ برائی کا ارادہ کرتا ہے تو وہ پھر نہیں سکتی۔ اور اللہ کے سوا ان کا کوئی مددگار نہیں ہوتا۔', 'اسکے پہرے والے ہیں بندہ کے آگے سے پیچھے سے اسکی نگہبانی کرتے ہیں اللہ کے حکم سے [۲۰] اللہ نہیں بدلتا کسی قوم کی حالت کو جب تک وہ نہ بدلیں جو ان کے جیوں میں ہے اور جب چاہتا ہے اللہ کسی قوم پر آفت پھر وہ نہیں پھرتی اور کوئی نہیں ان کا اس کےسوا مدگار [۲۱]', 'For each (person), there are angels in succession, before and behind him. They guard him by the Command of Allah. Verily! Allah will not change the good condition of a people as long as they do not change their state of goodness themselves (by committing sins and by being ungrateful and disobedient to Allah). But when Allah wills a peoples punishment, there can be no turning back of it, and they will find besides Him no protector.', 'For every one (from among you) there are angels replacing one another, in front of him and behind him, who guard him under the command of Allah. Surely, Allah does not change the condition of a people unless they change themselves. When Allah intends evil for a people, there is no way to turn it back, and for them there is no patron other than Him.'),
(1719, 13, 12, 2, 8, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'ہُوَ  الَّذِیۡ یُرِیۡکُمُ  الۡبَرۡقَ خَوۡفًا وَّ طَمَعًا  وَّ یُنۡشِیُٔ  السَّحَابَ  الثِّقَالَ ﴿ۚ۱۲﴾', 'وہی تو ہے جو تم کو ڈرانے اور امید دلانے کے لئے بجلی دکھاتا اور بھاری بھاری بادل پیدا کرتا ہے۔', 'وہی ہےکہ تم کو دکھلاتا ہے بجلی ڈر کو (ڈرانے کو) اور امید کو اور اٹھاتا ہے بادل بھاری [۲۲]', 'It is He who shows you the lightning, as a fear (for travellers) and as a hope (for those who wait for rain). And it is He Who brings up (or originates) the clouds, heavy (with water).', 'He is the One who makes you see the lightening in fear and hope, and who forms the heavy clouds.'),
(1720, 13, 13, 2, 8, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ یُسَبِّحُ الرَّعۡدُ بِحَمۡدِہٖ  وَ الۡمَلٰٓئِکَۃُ مِنۡ خِیۡفَتِہٖ ۚ وَ یُرۡسِلُ الصَّوَاعِقَ فَیُصِیۡبُ بِہَا مَنۡ یَّشَآءُ  وَ ہُمۡ  یُجَادِلُوۡنَ فِی اللّٰہِ ۚ وَ ہُوَ  شَدِیۡدُ الۡمِحَالِ ﴿ؕ۱۳﴾', 'اور رعد اور فرشتے سب اسکے خوف سے اسکی تسبیح و تحمید کرتے رہتے ہیں اور وہی بجلیاں بھیجتا ہے پھر جس پر چاہتا ہے گرا بھی دیتا ہے۔ جبکہ وہ اللہ کے بارے میں جھگڑتے ہیں اور وہ بڑی قوت والا ہے۔', 'اور پڑھتا ہے گرج والا خوبیاں اسکی اور سب فرشتے اس کے ڈر سے [۲۳] اور بھیجتا ہے کڑک بجلیاں پھر ڈالتا ہے جس پر چاہے اور یہ لوگ جھگڑتے ہیں اللہ کی بات میں اور اس کی آن (پکڑ) سخت ہے [۲۴]', 'And Ar-Rad (thunder) glorifies and praises Him, and so do the angels because of His Awe, He sends the thunderbolts, and therewith He strikes whom He wills, yet they (disbelievers) dispute about Allah. And He is Mighty in strength and Severe in punishment.', 'The thunder proclaims His purity with His praise, and (so do) the angels, out of His awe. And He sends the thunderbolts and strikes with it whom He wills. They are quarrelling about Allah, and He is stern in His plan.'),
(1721, 13, 14, 2, 8, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'لَہٗ  دَعۡوَۃُ   الۡحَقِّ ؕ وَ الَّذِیۡنَ  یَدۡعُوۡنَ مِنۡ دُوۡنِہٖ لَا یَسۡتَجِیۡبُوۡنَ لَہُمۡ بِشَیۡءٍ  اِلَّا کَبَاسِطِ کَفَّیۡہِ  اِلَی الۡمَآءِ لِیَبۡلُغَ فَاہُ وَ مَا ہُوَ بِبَالِغِہٖ ؕ وَ مَا دُعَآءُ الۡکٰفِرِیۡنَ  اِلَّا  فِیۡ  ضَلٰلٍ ﴿۱۴﴾', 'کام کا پکارنا تو اسی کا ہے اور جنکو یہ لوگ اس کے سوا پکارتے ہیں وہ انکی پکار کو کسی طرح قبول نہیں کرتے۔ مگر اس شخص کی طرح جو اپنے دونوں ہاتھ پانی کی طرف پھیلا دے تاکہ دور ہی سے اسکے منہ تک آ پہنچے حالانکہ وہ اس تک کبھی بھی نہیں آ سکتا اور اسی طرح کافروں کی پکار بےکار ہے۔', 'اسی کا پکارنا سچ ہے اور جن لوگوں کو کہ پکارتے ہیں اس کے سوا وہ نہیں کام آتے ان کے کچھ بھی مگر جیسے کسی نے پھیلائے دونوں ہاتھ پانی کی طرف کہ آ پہنچے اسکے منہ تک اور وہ کبھی نہ پہنچے گا اس تک اور جتنی پکار ہے کافروں کی سب گمراہی ہے [۲۵]', 'For Him (Alone) is the Word of Truth (i.e. none has the right to be worshipped but He). And those whom they (polytheists and disbelievers) invoke, answer them no more than one who stretches forth his hand (at the edge of a deep well) for water to reach his mouth, but it reaches him not, and the invocation of the disbelievers is nothing but an error (i.e. of no use).', 'True prayers are to be directed to Him alone; and those to whom they pray instead of Him do not respond to them at all, but they are like one who stretches his hands towards water so that it may reach his mouth (by itself), while it is not to reach it. And the prayer of the disbelievers (that they make to false gods) is nothing but straying in void.'),
(1722, 13, 15, 2, 8, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ لِلّٰہِ یَسۡجُدُ مَنۡ فِی السَّمٰوٰتِ وَ الۡاَرۡضِ طَوۡعًا وَّ کَرۡہًا وَّ ظِلٰلُہُمۡ بِالۡغُدُوِّ  وَ الۡاٰصَالِ  ﴿ٛ۱۵﴾', 'اور جتنی مخلوقات آسمانوں اور زمین میں ہے خوشی سے یا ناخوشی سے اللہ کے آگے سجدہ کرتی ہے اور انکے سائے بھی صبح و شام سجدے کرتے ہیں۔', 'اور اللہ کو سجدہ کرتا ہے جو کوئی ہے آسمان اور زمین میں خوشی سے اور زور سے اور انکی پرچھائیاں صبح اور شام [۲۶]', 'And unto Allah (Alone) falls in prostration whoever is in the heavens and the earth, willingly or unwillingly, and so do their shadows in the mornings and in the afternoons.', 'To Allah bow in prostration all who are in the heavens and the earth, willingly or unwillingly, and their shadows as well in morns and eves.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1723, 13, 16, 2, 8, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'قُلۡ مَنۡ رَّبُّ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ قُلِ اللّٰہُ ؕ قُلۡ  اَفَاتَّخَذۡتُمۡ  مِّنۡ  دُوۡنِہٖۤ  اَوۡلِیَآءَ  لَا یَمۡلِکُوۡنَ لِاَنۡفُسِہِمۡ نَفۡعًا وَّ لَا ضَرًّا ؕ قُلۡ ہَلۡ یَسۡتَوِی الۡاَعۡمٰی وَ الۡبَصِیۡرُ ۬ۙ اَمۡ ہَلۡ تَسۡتَوِی الظُّلُمٰتُ وَ النُّوۡرُ ۬ۚ اَمۡ  جَعَلُوۡا لِلّٰہِ  شُرَکَآءَ  خَلَقُوۡا کَخَلۡقِہٖ فَتَشَابَہَ الۡخَلۡقُ عَلَیۡہِمۡ ؕ قُلِ اللّٰہُ خَالِقُ کُلِّ شَیۡءٍ وَّ ہُوَ الۡوَاحِدُ الۡقَہَّارُ ﴿۱۶﴾', 'ان سے پوچھو کہ آسمانوں اور زمین کا پروردگار کون ہے؟  تم ہی کہدو کہ اللہ۔ ان سے کہو کہ کیا تم نے اللہ کو چھوڑ کر ایسے لوگوں کو کارساز بنایا ہے جو خود اپنے نفع و نقصان کا بھی اختیار نہیں رکھتے کہو کیا اندھا اور آنکھوں والا برابر ہیں؟ یا اندھیرا اور اجالا برابر ہو سکتا ہے؟ بھلا ان لوگوں نے جنکو اللہ کا شریک مقرر کیا ہے۔ کیا انہوں نے اللہ کی سی مخلوقات پیدا کی ہے جس کے سبب انکے لئے مخلوقات مشتبہ ہو گئ ہے۔ کہدو کہ اللہ ہی ہر چیز کا پیدا کرنے والا ہے اور وہ یکتا ہے بڑا زبردست ہے۔', 'پوچھ کون ہے رب آسمان اور زمین کا کہدے اللہ ہے کہہ پھر کیا تم نے پکڑے ہیں اس کے سوا ایسے حمایتی جو مالک نہیں اپنے بھلے اور برے کے [۲۷] کہہ کیا برابر ہوتا ہے اندھا اور دیکھنے والا یا کہیں برابر ہے اندھیرا اور اجالا [۲۸]کیا ٹھہرائے ہیں انہوں نے اللہ کے لئے شریک کہ انہوں نے کچھ پیدا کیا ہے جیسے پیدا کیا اللہ نے پھر مشتبہ ہو گئ پیدائش انکی نظر میں کہہ اللہ ہے پیدا کرنے والا ہر چیز کا اور وہی ہے اکیلا زبردست [۲۹]', 'Say (O Muhammad SAW): \"Who is the Lord of the heavens and the earth?\" Say: \"(It is) Allah.\" Say: \"Have you then taken (for worship) Auliya (protectors, etc.) other than Him, such as have no power either for benefit or for harm to themselves?\" Say: \"Is the blind equal to the one who sees? Or darkness equal to light? Or do they assign to Allah partners who created the like of His creation, so that the creation (which they made and His creation) seemed alike to them.\" Say: \"Allah is the Creator of all things, He is the One, the Irresistible.\"', 'Say, “Who is the Lord of the heavens and the earth?” Say, “Allah.” Say, “Have you, then, taken as protectors those besides Him who possess no power to cause benefit or harm even to themselves?” Say, “Is it that a blind person and a sighted one are equal, or that all sorts of the darkness and the light are alike?” Or, have they ascribed such partners with Allah who (according to their belief) have created (some of the creation) as He has created, and thus the creation seemed to them alike? Say, “Allah is the Creator of all things, and He is the One, the All-Dominant.”'),
(1724, 13, 17, 2, 8, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'اَنۡزَلَ مِنَ السَّمَآءِ  مَآءً  فَسَالَتۡ اَوۡدِیَۃٌۢ بِقَدَرِہَا فَاحۡتَمَلَ السَّیۡلُ زَبَدًا رَّابِیًا ؕ وَ مِمَّا یُوۡقِدُوۡنَ عَلَیۡہِ فِی النَّارِ ابۡتِغَآءَ حِلۡیَۃٍ  اَوۡ مَتَاعٍ زَبَدٌ مِّثۡلُہٗ ؕ کَذٰلِکَ یَضۡرِبُ اللّٰہُ الۡحَقَّ وَ الۡبَاطِلَ ۬ؕ فَاَمَّا الزَّبَدُ فَیَذۡہَبُ جُفَآءً ۚ وَ اَمَّا مَا یَنۡفَعُ النَّاسَ فَیَمۡکُثُ فِی الۡاَرۡضِ ؕ  کَذٰلِکَ یَضۡرِبُ اللّٰہُ   الۡاَمۡثَالَ ﴿ؕ۱۷﴾', 'اسی نے آسمان سے مینہ برسایا پھر اس سے اپنے اپنے اندازے کے مطابق نالے بہ نکلے پھر پانی پر پھولا ہوا جھاگ آ گیا۔ اور جس چیز کو زیور یا کوئی اور سامان بنانے کے لئے آگ میں تپاتے ہیں اس میں بھی ایسا ہی جھاگ ہوتا ہے۔ اس طرح اللہ حق و باطل کی مثال بیان فرماتا ہے۔ سو جھاگ تو سوکھ کر زائل ہو جاتا ہے اور پانی جو لوگوں کو فائدہ پہنچاتا ہے وہ زمین میں ٹھہرا رہتا ہے۔ اس طرح اللہ صحیح اور غلط کی مثالیں بیان فرماتا ہے تاکہ تم سمجھو۔', 'اتارا اس نے آسمان سے پانی پھر بہنے لگے نالےاپنی اپنی موافق پھر اوپر لے آیا وہ نالا جھاگ پھولا ہوا اور جس چیز کو دھونکتے ہیں آگ میں واسطے زیور کے یا اسباب کے اسمیں بھی جھاگ ہے ویسا ہی یوں بیان (ٹھہراتا ہے) کرتا ہے اللہ حق اور باطل کو سو وہ جھاگ تو جاتا رہتا ہے سوکھ کر اور وہ جو کام آتا ہے لوگوں کے سو باقی رہتا ہے زمین میں اس طرح بیان کرتا ہے اللہ مثالیں [۳۰]', 'He sends down water (rain) from the sky, and the valleys flow according to their measure, but the flood bears away the foam that mounts up to the surface, and (also) from that (ore) which they heat in the fire in order to make ornaments or utensils, rises a foam like unto it, thus does Allah (by parables) show forth truth and falsehood. Then, as for the foam it passes away as scum upon the banks, while that which is for the good of mankind remains in the earth. Thus Allah sets forth parables (for the truth and falsehood, i.e. Belief and disbelief).', 'He sent down water from the heavens, so the canals flowed according to their capacity, and the flood carried bulging scum. And a similar scum comes up from what they melt in the fire to obtain ornaments or other objects. This is how Allah depicts the truth and the untruth. As for the scum, it goes to be thrown away, while that which benefits people remains on the earth. This is how Allah brings out the parables.'),
(1725, 13, 18, 2, 8, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'لِلَّذِیۡنَ اسۡتَجَابُوۡا لِرَبِّہِمُ الۡحُسۡنٰی ؕؔ وَ الَّذِیۡنَ لَمۡ  یَسۡتَجِیۡبُوۡا لَہٗ  لَوۡ  اَنَّ  لَہُمۡ  مَّا فِی الۡاَرۡضِ جَمِیۡعًا وَّ مِثۡلَہٗ  مَعَہٗ لَافۡتَدَوۡا بِہٖ ؕ اُولٰٓئِکَ لَہُمۡ سُوۡٓءُ الۡحِسَابِ ۬ۙ وَ مَاۡوٰىہُمۡ جَہَنَّمُ ؕ وَ بِئۡسَ الۡمِہَادُ ﴿٪۱۸﴾', 'جن لوگوں نے اللہ کے حکم کو قبول کیا انکی حالت بہت بہتر ہو گی۔ اور جنہوں نے اسکو قبول نہ کیا اگر روئے زمین کے سب خزانے انکے اختیار میں ہوں تو وہ سب کے سب اور انکے ساتھ اتنے ہی اور نجات کے بدلے میں صرف کر ڈالیں مگر نجات کہاں؟ ایسے لوگوں کا حساب بھی برا ہوگا اور ان کا ٹھکانہ بھی دوزخ ہے اور وہ بری جگہ ہے۔', 'جنہوں نے مانا اپنے رب کا حکم ان کے واسطے بھلائی ہے [۳۱] اور جنہوں نے اس کا حکم نہ مانا اگر انکے پاس ہو جو کچھ کہ زمین میں ہے سارا اور اتنا ہی اس کےساتھ اور تو سب دیویں (دے ڈالیں) اپنے بدلہ میں [۳۲] ان لوگوں کے لئے ہے برا حساب [۳۳] اور ٹھکانا ان کا دوزخ ہے اور وہ بری (برا بچھونا ہے) آرام کی جگہ ہے', 'For those who answered their Lords Call (believed in the Oneness of Allah and followed His Messenger Muhammad SAW i.e. Islamic Monotheism) is Al-Husna (i.e. Paradise). But those who answered not His Call (disbelieved in the Oneness of Allah and followed not His Messenger Muhammad SAW), if they had all that is in the earth together with its like, they would offer it in order to save themselves (from the torment, it will be in vain). For them there will be the terrible reckoning. Their dwelling place will be Hell; - and worst indeed is that place for rest.', 'For those who obey their Lord there is the best of rewards; and those who do not obey Him (shall be in such a plight that) even if they possess all that is on earth, rather twice as much, they would offer it in ransom (to redeem themselves from the punishment). For these there is the worst of reckoning, and their abode is Hell, which is an evil bed to rest.'),
(1726, 13, 19, 3, 9, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'اَفَمَنۡ یَّعۡلَمُ اَنَّمَاۤ  اُنۡزِلَ  اِلَیۡکَ مِنۡ رَّبِّکَ الۡحَقُّ کَمَنۡ ہُوَ اَعۡمٰی ؕ اِنَّمَا یَتَذَکَّرُ اُولُوا الۡاَلۡبَابِ ﴿ۙ۱۹﴾', 'بھلا جو شخص یہ جانتا ہے کہ جو کچھ تمہارے پروردگار کی طرف سے تم پر نازل ہوا ہے حق ہے وہ اس شخص کی طرح ہے جو اندھا ہے؟ اور سمجھتے تو وہی ہیں جو عقلمند ہیں۔', 'بھلا جو شخص جانتا ہے کہ جو کچھ اترا تجھ پر تیرے رب سے حق ہے برابر ہو سکتا ہے اسکے جو کہ اندھا ہے سمجھتے وہی ہیں جنکو عقل ہے [۳۴]', 'Shall he then who knows that what has been revealed unto you (O Muhammad SAW) from your Lord is the truth be like him who is blind? But it is only the men of understanding that pay heed.', 'Now, can the one who knows that whatever has been revealed to you from your Lord is the truth, be equal to one who is blind? Only the people of understanding respond to the advice -'),
(1727, 13, 20, 3, 9, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'الَّذِیۡنَ یُوۡفُوۡنَ بِعَہۡدِ اللّٰہِ وَ لَا یَنۡقُضُوۡنَ  الۡمِیۡثَاقَ ﴿ۙ۲۰﴾', 'جو اللہ کے عہد کو پورا کرتے ہیں اور قول و قرار کو نہیں توڑتے۔', 'وہ لوگ جو پورا کرتے ہیں اللہ کے عہد کو اور نہیں توڑتے اس عہد کو [۳۵]', 'Those who fulfill the Covenant of Allah and break not the Meethaq (bond, treaty, covenant);', 'those who fulfill (their) pledge with Allah and do not break the covenant,'),
(1728, 13, 21, 3, 9, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ الَّذِیۡنَ یَصِلُوۡنَ مَاۤ  اَمَرَ اللّٰہُ بِہٖۤ  اَنۡ یُّوۡصَلَ  وَ  یَخۡشَوۡنَ  رَبَّہُمۡ وَ یَخَافُوۡنَ سُوۡٓءَ  الۡحِسَابِ ﴿ؕ۲۱﴾', 'اور جن رشتوں کے جوڑے رکھنے کا اللہ نے حکم دیا انکو جوڑے رکھتے اور اپنے پروردگار سے ڈرتے رہتے اور برے حساب سے خوف رکھتے ہیں۔', 'اور وہ لوگ جو ملاتے ہیں جس کو اللہ نے فرمایا ملانا [۳۶] اور ڈرتے ہیں اپنے رب سے اور اندیشہ رکھتے ہیں برے حساب کا [۳۷]', 'Those who join that which Allah has commanded to be joined (i.e. they are good to their relatives and do not sever the bond of kinship), fear their Lord, and dread the terrible reckoning (i.e. abstain from all kinds of sins and evil deeds which Allah has forbidden and perform all kinds of good deeds which Allah has ordained).', 'and those who maintain the relationships Allah has commanded to be maintained and fear their Lord and are frightful of evil reckoning,'),
(1729, 13, 22, 3, 9, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ الَّذِیۡنَ صَبَرُوا ابۡتِغَآءَ  وَجۡہِ  رَبِّہِمۡ  وَ اَقَامُوا الصَّلٰوۃَ  وَ  اَنۡفَقُوۡا  مِمَّا  رَزَقۡنٰہُمۡ سِرًّا وَّ عَلَانِیَۃً وَّ یَدۡرَءُوۡنَ بِالۡحَسَنَۃِ السَّیِّئَۃَ  اُولٰٓئِکَ  لَہُمۡ  عُقۡبَی الدَّارِ ﴿ۙ۲۲﴾', 'اور جو اپنے پروردگار کی خوشنودی حاصل کرنے کے لئے مصائب پر صبر کرتے ہیں۔ اور نماز پڑھتے ہیں اور جو مال ہم نے ان کو دیا ہے اس میں سے پوشیدہ اور ظاہر خرچ کرتے ہیں اور نیکی سے برائی کو دور کرتے ہیں یہی لوگ ہیں جن کے لئے عاقبت کا گھر ہے۔', 'اور وہ لوگ جنہوں نے صبر کیا خوشی کو اپنے رب کی [۳۸] اور قائم رکھی نماز اور خرچ کیا ہمارے دیے میں سے پوشیدہ (چھپے) اور ظاہر [کھلے) [۳۹] اور کرتے ہیں برائی کے مقابلہ میں بھلائی [۴۰] ان لوگوں کے لئے ہے آخرت کا گھر', 'And those who remain patient, seeking their Lords Countenance, perform As-Salat (Iqamat-as-Salat), and spend out of that which We have bestowed on them, secretly and openly, and defend evil with good, for such there is a good end;', 'and those who observe patience in order to seek the pleasure of their Lord and establish Salāh and spend secretly and openly from what We have given to them, and repel evil with good. Those are the ones for whom there is the ultimate abode,'),
(1730, 13, 23, 3, 9, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'جَنّٰتُ عَدۡنٍ یَّدۡخُلُوۡنَہَا وَ مَنۡ صَلَحَ مِنۡ اٰبَآئِہِمۡ وَ اَزۡوَاجِہِمۡ وَ ذُرِّیّٰتِہِمۡ وَ الۡمَلٰٓئِکَۃُ یَدۡخُلُوۡنَ عَلَیۡہِمۡ مِّنۡ کُلِّ بَابٍ ﴿ۚ۲۳﴾', 'یعنی ہمیشہ رہنے کے باغات جن میں وہ داخل ہوں گے اور انکے باپ دادوں اور بیبیوں اور اولاد میں سے جو نیکوکار ہوں گے وہ بھی بہشت میں جائیں گے اور فرشتے بہشت کے ہر ایک دروازے سے انکے پاس آئیں گے۔', 'باغ ہیں رہنے کے [۴۱] داخل ہوں گے ان میں اور جو نیک ہوئے انکے باپ دادوں میں اور جو روؤں میں اور اولاد میں [۴۲] اور فرشتے آئیں ان کے پاس ہر دروازے سے', 'Adn (Eden) Paradise (everlasting Gardens), which they shall enter and (also) those who acted righteously from among their fathers, and their wives, and their offspring. And angels shall enter unto them from every gate (saying):', 'the eternal gardens they enter, and those as well who are righteous from their fathers, spouses, and progeny. The angels will enter onto them from every gate'),
(1731, 13, 24, 3, 9, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'سَلٰمٌ عَلَیۡکُمۡ بِمَا صَبَرۡتُمۡ فَنِعۡمَ عُقۡبَی الدَّارِ ﴿ؕ۲۴﴾', 'اور کہیں گے تم پر سلام ہو یہ تمہاری ثابت قدمی کا بدلہ ہے۔ اور عاقبت کا گھر خوب گھر ہے۔', 'کہیں گے سلامتی تم پر بدلے اسکے کہ تم نے صبر کیا سو خوب ملا عاقبت کا گھر [۴۳]', '\"Salamun Alaikum (peace be upon you) for that you persevered in patience! Excellent indeed is the final home!\"', '(saying) “Peace on you for the patience you observed. So, how excellent is the ultimate abode.”'),
(1732, 13, 25, 3, 9, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ الَّذِیۡنَ یَنۡقُضُوۡنَ عَہۡدَ اللّٰہِ  مِنۡۢ  بَعۡدِ مِیۡثَاقِہٖ وَ یَقۡطَعُوۡنَ  مَاۤ  اَمَرَ اللّٰہُ بِہٖۤ اَنۡ یُّوۡصَلَ وَ یُفۡسِدُوۡنَ فِی الۡاَرۡضِ ۙ اُولٰٓئِکَ لَہُمُ اللَّعۡنَۃُ وَ لَہُمۡ سُوۡٓءُ  الدَّارِ ﴿۲۵﴾', 'اور جو لوگ اللہ سے پختہ عہد کر کے اسکو توڑ ڈالتے اور جن رشتوں کے جوڑے رکھنے کا اللہ نے حکم دیا ہے انکو قطع کر دیتے اور ملک میں فساد کرتے ہیں ایسوں پر لعنت ہے اور انکے لئے برا انجام ہے۔', 'اور جو لوگ توڑتے ہیں عہد اللہ کا مضبوط کرنے کے بعد اور قطع کرتے ہیں اس چیز کو جس کو فرمایا اللہ نے جوڑنا اور فساد اٹھاتے ہیں ملک میں ایسےلوگ انکے واسطے ہے لعنت اور انکے لئے ہے برا گھر [۴۴]', 'And those who break the Covenant of Allah, after its ratification, and sever that which Allah has commanded to be joined (i.e. they sever the bond of kinship and are not good to their relatives), and work mischief in the land, on them is the curse (i.e. they will be far away from Allahs Mercy); And for them is the unhappy (evil) home (i.e. Hell).', 'As for those who break their pledge with Allah after it has been made binding, and cut off the relationships Allah has commanded to be joined, and make mischief in the land, those are the ones for whom there is the curse, and for them there is the evil abode.'),
(1733, 13, 26, 3, 9, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'اَللّٰہُ یَبۡسُطُ الرِّزۡقَ لِمَنۡ یَّشَآءُ  وَ یَقۡدِرُ ؕ وَ فَرِحُوۡا بِالۡحَیٰوۃِ الدُّنۡیَا ؕ وَ مَا الۡحَیٰوۃُ الدُّنۡیَا فِی الۡاٰخِرَۃِ  اِلَّا مَتَاعٌ ﴿٪۲۶﴾', 'اللہ جس کا چاہتا ہے رزق فراخ کر دیتا ہے اور جس کا چاہتا ہے تنگ کر دیتا ہے۔ اور کافر لوگ دنیا کی زندگی پر خوش ہو رہے ہیں۔ اور دنیا کی زندگی آخرت کے مقابلے میں بہت تھوڑا سامان ہے۔', 'اللہ کشادہ کرتا ہے روزی جس کو چاہے اور تنگ کرتا ہے [۴۵] اور فریفتہ ہیں دنیا کی زندگی پر اور دنیا کی زندگی کچھ نہیں آخرت کے آگے مگر متاع (مال) حقیر [۴۶]', 'Allah increases the provision for whom He wills, and straitens (it for whom He wills), and they rejoice in the life of the world, whereas the life of this world as compared with the Hereafter is but a brief passing enjoyment.', 'Allah expands the provision for whom He wills and narrows it (for whom He wills). They are happy with the worldly life, while the worldly life, compared to the Hereafter, is nothing but a little enjoyment.'),
(1734, 13, 27, 4, 10, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ  یَقُوۡلُ الَّذِیۡنَ  کَفَرُوۡا لَوۡ لَاۤ  اُنۡزِلَ عَلَیۡہِ اٰیَۃٌ  مِّنۡ رَّبِّہٖ ؕ قُلۡ  اِنَّ اللّٰہَ  یُضِلُّ مَنۡ یَّشَآءُ وَ یَہۡدِیۡۤ اِلَیۡہِ مَنۡ اَنَابَ ﴿ۖۚ۲۷﴾', 'اور کافر کہتے ہیں کہ اس پیغمبر پر اسکے پروردگار کی طرف سے کوئی نشانی کیوں نازل نہیں ہوئی۔ کہدو کہ اللہ جسے چاہتا ہے گمراہ کر تا ہے اور جو اسکی طرف رجوع ہوتا ہے اسکو اپنی طرف کا رستہ دکھاتا ہے۔', 'اور کہتے ہیں کافر کیوں نہ اتری اس پر کوئی نشانی اس کے رب سے کہہ دے اللہ گمراہ (بچلاتا ہے) کرتا ہے جس کو چاہے اور راہ دکھلاتا ہے اپنی طرف اسکو جو رجوع ہوا [۴۷]', 'And those who disbelieve say: \"Why is not a sign sent down to him (Muhammad SAW) from his Lord?\" Say: \"Verily, Allah sends astray whom He wills and guides unto Himself those who turn to Him in repentance.\"', 'The disbelievers say, “Why is it that no sign (of their choice) has been sent down to him from his Lord?” Say, “Allah lets go astray whom He wills and gives guidance to those who turn to Him,'),
(1735, 13, 28, 4, 10, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'اَلَّذِیۡنَ اٰمَنُوۡا وَ تَطۡمَئِنُّ قُلُوۡبُہُمۡ بِذِکۡرِ اللّٰہِ ؕ اَلَا بِذِکۡرِ اللّٰہِ تَطۡمَئِنُّ الۡقُلُوۡبُ ﴿ؕ۲۸﴾', 'یعنی انکو جو ایمان لاتے اور جنکے دل اللہ کی یاد سے آرام پاتے ہیں انکو اور سن رکھو کہ اللہ کی یاد سے ہی دل آرام پاتے ہیں۔', 'وہ لوگ جو ایمان لائے اور چین پاتے ہیں انکے دل اللہ کی یاد سے [۴۸] سنتا ہے اللہ کی یاد ہی سے چین پاتے ہیں دل [۴۹]', 'Those who believe (in the Oneness of Allah - Islamic Monotheism), and whose hearts find rest in the remembrance of Allah, Verily, in the remembrance of Allah do hearts find rest.', 'the ones who believe and their hearts are peaceful with the remembrance of Allah. Listen, the hearts find peace only in the remembrance of Allah.”'),
(1736, 13, 29, 4, 10, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'اَلَّذِیۡنَ  اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ  طُوۡبٰی لَہُمۡ  وَ حُسۡنُ  مَاٰبٍ ﴿۲۹﴾', 'جو لوگ ایمان لائے اور عمل نیک کئے انکے لئے خوشحالی اور عمدہ ٹھکانہ ہے۔', 'جو لوگ ایمان لائے اور کام کئے اچھے خوشحالی (خوبی) ہے انکے واسطے اور اچھا ٹھکانا [۵۰]', 'Those who believe (in the Oneness of Allah - Islamic Monotheism), and work righteousness, Tooba (it means all kinds of happiness or name of a tree in Paradise) is for them and a beautiful place of (final) return.', 'Those who believe and do good deeds, for them there is the bliss and a good place to return.'),
(1737, 13, 30, 4, 10, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'کَذٰلِکَ اَرۡسَلۡنٰکَ فِیۡۤ  اُمَّۃٍ قَدۡ خَلَتۡ مِنۡ قَبۡلِہَاۤ اُمَمٌ لِّتَتۡلُوَا۠ عَلَیۡہِمُ الَّذِیۡۤ اَوۡحَیۡنَاۤ  اِلَیۡکَ وَ ہُمۡ یَکۡفُرُوۡنَ بِالرَّحۡمٰنِ ؕ قُلۡ ہُوَ  رَبِّیۡ  لَاۤ  اِلٰہَ   اِلَّا ہُوَ ۚ عَلَیۡہِ  تَوَکَّلۡتُ وَ  اِلَیۡہِ  مَتَابِ  ﴿۳۰﴾', 'جس طرح ہم پہلے پیغمبر بھیجتے رہے ہیں اسی طرح اے نبی ہم نے تم کو اس امت میں جس سے پہلے بہت سی امتیں گذر چکی ہیں بھیجا ہے تاکہ تم انکو وہ کتاب جو ہم نے تمہاری طرف بھیجی ہے پڑھ کر سنا دو۔ اور یہ لوگ رحمٰن کو نہیں مانتے۔ کہدو وہی تو میرا پروردگار ہے اسکے سوا کوئی معبود نہیں میں اسی پر بھروسہ رکھتا ہوں اور اسی کی طرف رجوع کرتا ہوں۔', 'اسی طرح تجھ کو بھیجا ہم نے ایک امت میں کہ گذر چکی ہیں اس سے پہلے بہت امتیں تاکہ سنا دے تو انکو جو حکم بھیجا ہم نے تیری طرف [۵۱] اور وہ منکر ہوتے ہیں رحمٰن سے [۵۲] تو کہہ وہی رب میرا ہے کسی کی بندگی نہیں اسکے سوا اسی پر میں نے بھروسہ کیا ہے اور اسی کی طرف آتا ہوں رجوع کر کے [۵۳]', 'Thus have We sent you (O Muhammad SAW) to a community before whom other communities have passed away, in order that you might recite unto them what We have inspired to you, while they disbelieve in the Most Beneficient (Allah) Say: \"He is my Lord! La ilaha illa Huwa (none has the right to be worshipped but He)! In Him is my trust, and to Him will be my return with repentance.\"', 'Thus We have sent you, amidst a community before which many communities have passed away, so that you may recite to them what We have revealed to you, while they disbelieve in Ar-RaHmān (the All-Merciful Allah). Say, “He is my Lord. There is no god but He. In Him I place my trust, and to Him is my return.”'),
(1738, 13, 31, 4, 10, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ لَوۡ اَنَّ  قُرۡاٰنًا سُیِّرَتۡ بِہِ الۡجِبَالُ اَوۡ قُطِّعَتۡ بِہِ  الۡاَرۡضُ اَوۡ کُلِّمَ  بِہِ الۡمَوۡتٰی ؕ بَلۡ  لِّلّٰہِ الۡاَمۡرُ جَمِیۡعًا ؕ اَفَلَمۡ  یَایۡـَٔسِ الَّذِیۡنَ  اٰمَنُوۡۤا  اَنۡ  لَّوۡ  یَشَآءُ اللّٰہُ لَہَدَی النَّاسَ جَمِیۡعًا ؕ وَ لَا یَزَالُ الَّذِیۡنَ کَفَرُوۡا تُصِیۡبُہُمۡ بِمَا صَنَعُوۡا قَارِعَۃٌ  اَوۡ  تَحُلُّ قَرِیۡبًا مِّنۡ دَارِہِمۡ حَتّٰی یَاۡتِیَ  وَعۡدُ  اللّٰہِ ؕ اِنَّ  اللّٰہَ  لَا یُخۡلِفُ  الۡمِیۡعَادَ ﴿٪۳۱﴾', 'اور اگر کوئی قرآن ایسا ہوتا کہ اسکی تاثیر سے پہاڑ چل پڑتے یا زمین پھٹ جاتی یا مردوں سے کلام کر سکتے تو کیا یہ لوگ ایمان لے آتے بات یہ ہے کہ سب باتیں اللہ کے اختیار میں ہیں۔ تو کیا مومنوں کو اس سے اطمینان نہیں ہوا کہ اگر اللہ چاہتا تو سب لوگوں کو ہدایت کے رستے پر چلا دیتا اور کافروں پر ہمیشہ انکے اعمال کے بدلے آفت آتی رہے گی۔ یا انکے مکانات کے قریب نازل ہوتی رہے گی۔ یہاں تک کہ اللہ کا وعدہ آ پہنچے۔ بیشک اللہ وعدہ خلاف نہیں کرتا۔', 'اور اگر کوئی قرآن ہوا ہوتا کہ چلیں اس سے پہاڑ یا ٹکڑے ہووے اس سے زمین یا بولیں ( بولنے لگیں) اس سے مردے تو کیا ہوتا بلکہ سب کام تو اللہ کے ہاتھ میں ہیں [۵۴] سو کیا خاطر جمع نہیں ایمان والوں کو اس پر کہ اگر چاہے اللہ تو راہ پر لائے سب لوگوں کو [۵۵] اور برابر پہنچتا رہے گا منکروں کو ان کے کرتوت پر صدمہ (دھڑکا) یا اترے گا انکے گھر سے نزدیک جب تک کہ پہنچے وعدہ اللہ کا بیشک اللہ خلاف نہیں کرتا اپنا وعدہ [۵۶]', 'And if there had been a Quran with which mountains could be moved (from their places), or the earth could be cloven asunder, or the dead could be made to speak (it would not have been other than this Quran). But the decision of all things is certainly with Allah. Have not then those who believe yet known that had Allah willed, He could have guided all mankind? And a disaster will not cease to strike those who disbelieve because of their (evil) deeds or it (i.e. the disaster) settle close to their homes, until the Promise of Allah comes to pass. Certainly, Allah does not fail in His Promise.', 'And even if there were a Qur’ān wherewith the mountains could be moved, or the earth could be split apart, or wherewith the dead are spoken to, (they would not believe). In fact, every decision rests only with Allah. Are the believers not satisfied with the fact that, if Allah willed, He would have brought all the people to the right path?And the disbelievers are continually receiving affliction because of what they did, or it visits somewhere close to their homes, until Allah’s promise will come to pass. Surely, Allah does not go back upon His promise.'),
(1739, 13, 32, 5, 11, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ لَقَدِ اسۡتُہۡزِیَٔ بِرُسُلٍ مِّنۡ قَبۡلِکَ فَاَمۡلَیۡتُ لِلَّذِیۡنَ  کَفَرُوۡا ثُمَّ   اَخَذۡتُہُمۡ ۟ فَکَیۡفَ کَانَ عِقَابِ ﴿۳۲﴾', 'اور تم سے پہلے بھی رسولوں کے ساتھ تمسخر ہوتے رہے ہیں تو میں نے کافروں کو مہلت دی پھر میں نے انکو پکڑ لیا سو دیکھ لو کہ میرا عذاب کیسا رہا۔', 'اور ٹھٹھا کر چکے ہیں کتنے رسولوں سے تجھ سے پہلے سو ڈھیل دی میں نے منکروں کو پھر ان کو پکڑ لیا سو کیسا تھا میرا بدلہ [۵۷]', 'And indeed (many) Messengers were mocked at before you (O Muhammad SAW), but I granted respite to those who disbelieved, and finally I punished them. Then how (terrible) was My Punishment!', 'Messengers have been mocked at before you, so I let the disbelievers go on for a while. Then I seized them. So, how was My punishment?'),
(1740, 13, 33, 5, 11, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'اَفَمَنۡ ہُوَ قَآئِمٌ عَلٰی کُلِّ نَفۡسٍۭ بِمَا کَسَبَتۡ ۚ وَ جَعَلُوۡا لِلّٰہِ شُرَکَآءَ ؕ قُلۡ سَمُّوۡہُمۡ ؕ اَمۡ تُنَبِّـُٔوۡنَہٗ بِمَا لَا یَعۡلَمُ فِی الۡاَرۡضِ اَمۡ بِظَاہِرٍ مِّنَ الۡقَوۡلِ ؕ بَلۡ زُیِّنَ لِلَّذِیۡنَ کَفَرُوۡا مَکۡرُہُمۡ وَ صُدُّوۡا عَنِ  السَّبِیۡلِ ؕ وَ مَنۡ یُّضۡلِلِ اللّٰہُ  فَمَا لَہٗ  مِنۡ ہَادٍ ﴿۳۳﴾', 'تو کیا وہ جو ہر شخص کے اعمال کا نگران و نگہبان ہے وہ بتوں کی طرح بے علم و بیخبر ہو سکتا ہے؟ اور ان لوگوں نے اللہ کے شریک مقرر کر رکھے ہیں۔ ان سے کہو کہ ذرا ان کے نام تو لو۔ کیا تم اسے ایسی چیزیں بتاتے ہو جو روئے زمین پر ہیں اور اسے معلوم نہیں یا تم لوگ محض سطحی بات کی تقلید کرتے ہو اصل یہ ہے کہ کافروں کو انکے فریب خوبصورت معلوم ہوتے ہیں۔ اور وہ ہدایت کے رستے سے روک لئے گئے ہیں۔ اور جسے اللہ گمراہ  رہنے دے اسے کوئی ہدایت کرنے والا نہیں۔', 'بھلا جو لئے کھڑا ہے ہر کسی کے سر پر جو کچھ اس نے کیا ہے (اوروں کی برابر ہو سکتا ہے) اور مقرر کرتے ہیں اللہ کے لئے شریک [۵۸] کہہ ان کا نام لو [۵۹] یا اللہ کو بتلاتے ہو جو وہ نہیں جانتا زمین میں [۶۰] یا کرتے ہو اوپر ہی اوپر باتیں [۶۱] یہ نہیں بلکہ بھلے سمجھا دیے ہیں منکروں کو ان کے فریب اور وہ روک دیئے گئے ہیں راہ سے [۶۲] اور جس کو گمراہ کرے اللہ سو کوئی نہیں اسکو راہ بتانے والا [۶۳]', 'Is then He (Allah) Who takes charge (guards, maintains, provides, etc.) of every person and knows all that he has earned (like any other deities who know nothing)? Yet they ascribe partners to Allah. Say: \"Name them! Is it that you will inform Him of something He knows not in the earth or is it (just) a show of false words.\" Nay! To those who disbelieve, their plotting is made fairseeming, and they have been hindered from the Right Path, and whom Allah sends astray, for him, there is no guide.', 'Is then He, who is watchful over everyone and over whatever he does, (equal to their false deities?) Still they have made partners with Allah. Say, “Give their names. Is it that you are informing Him of something on earth He does not know, or of just empty words?” But, their ill- designs have been made alluring for the disbelievers, and they have been barred from the Path. And for the one whom Allah deprives of guidance, there is no one to guide.'),
(1741, 13, 34, 5, 11, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'لَہُمۡ عَذَابٌ فِی الۡحَیٰوۃِ الدُّنۡیَا وَ لَعَذَابُ الۡاٰخِرَۃِ اَشَقُّ ۚ وَ مَا لَہُمۡ مِّنَ اللّٰہِ  مِنۡ  وَّاقٍ ﴿۳۴﴾', 'انکو دنیا کی زندگی میں بھی عذاب ہے۔ اور آخرت کا عذاب تو بہت ہی سخت ہے اور انکو اللہ کے عذاب سے کوئی بھی بچانے والا نہیں۔', 'ان کو مار پڑتی ہے دنیا کی زندگی میں [۶۴] اور آخرت کی مار تو بہت ہی سخت ہے اور کوئی نہیں انکو اللہ سے بچانے والا [۶۵]', 'For them is a torment in the life of this world, and certainly, harder is the torment of the Hereafter. And they have no protector against Allah.', 'For them there is punishment in the worldly life, and indeed the punishment of the Hereafter is even harder, and for them there is none to save them from Allah.'),
(1742, 13, 35, 5, 11, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'مَثَلُ الۡجَنَّۃِ الَّتِیۡ وُعِدَ الۡمُتَّقُوۡنَ ؕ تَجۡرِیۡ مِنۡ  تَحۡتِہَا الۡاَنۡہٰرُ ؕ اُکُلُہَا دَآئِمٌ وَّ ظِلُّہَا ؕ تِلۡکَ عُقۡبَی الَّذِیۡنَ اتَّقَوۡا ٭ۖ وَّ عُقۡبَی الۡکٰفِرِیۡنَ النَّارُ ﴿۳۵﴾', 'جس جنت کا پرہیزگاروں سے وعدہ کیا گیا ہے۔ اسکی شان یہ ہے کہ اسکے نیچے نہریں بہ رہی ہیں۔ اسکے پھل ہمیشہ باقی رہنے والے ہیں اور اسکے سائے بھی۔ یہ ان لوگوں کا انجام ہے جو متقی ہیں۔ اور کافروں کا انجام دوزخ ہے۔', 'حال جنت کا جس کا وعدہ ہے پرہیزگاروں سے بہتی ہیں اس کے نیچے نہریں میوہ اس کا ہمیشہ ہے [۶۶] اور سایہ بھی [۶۷] یہ بدلہ ہے ان کا جو ڈرتے رہے [۶۸] اور بدلہ منکروں کا آگ ہے [۶۹]', 'The description of the Paradise which the Muttaqoon (pious - see V.2:2): have been promised! -Underneath it rivers flow, its provision is eternal and so is its shade, this is the end (final destination) of the Muttaqoon (pious - see V.2:2), and the end (final destination) of the disbelievers is Fire. (See Verse 47:15)', 'Here is the description of the Paradise promised to the God-fearing: underneath it the rivers flow; its food is everlasting and (so is) its shade. This is the ultimate abode of the God-fearing while the ultimate abode of the disbelievers is Fire.'),
(1743, 13, 36, 5, 11, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ الَّذِیۡنَ اٰتَیۡنٰہُمُ الۡکِتٰبَ یَفۡرَحُوۡنَ بِمَاۤ اُنۡزِلَ اِلَیۡکَ وَ مِنَ الۡاَحۡزَابِ مَنۡ یُّنۡکِرُ بَعۡضَہٗ ؕ قُلۡ اِنَّمَاۤ  اُمِرۡتُ اَنۡ اَعۡبُدَ اللّٰہَ  وَ لَاۤ   اُشۡرِکَ بِہٖ ؕ اِلَیۡہِ  اَدۡعُوۡا وَ  اِلَیۡہِ  مَاٰبِ ﴿۳۶﴾', 'اور جن لوگوں کو ہم نے کتاب دی ہے وہ اس کتاب سے جو تم پر نازل ہوئی ہے خوش ہوتے ہیں اور بعض فرقے اسکی بعض باتیں نہیں بھی مانتے کہدو کہ مجھ کو یہی حکم ہوا ہے کہ اللہ ہی کی عبادت کروں اور اسکے ساتھ کسی کو شریک نہ بناؤں۔ میں اسی کی طرف بلا تا ہوں اور اسی کی طرف مجھے لوٹنا ہے۔', 'اور وہ لوگ جن کو ہم نے دی ہے کتاب خوش ہوتے ہیں اس سے جو نازل ہوا تجھ پر [۷۰] اور بعضےفرقے نہیں مانتے اسکی بعضی بات [۷۱] کہہ مجھ کو یہی حکم ہوا کہ بندگی کروں اللہ کی اور شریک نہ کروں اس کا اسی کی طرف بلاتا ہوں اور اسی کی طرف ہے میرا ٹھکانہ [۷۲]', 'Those to whom We have given the Book (such as Abdullah bin Salam and other Jews who embraced Islam), rejoice at what has been revealed unto you (i.e. the Quran), but there are among the Confederates (from the Jews and pagans) those who reject a part thereof. Say (O Muhammad SAW): \"I am commanded only to worship Allah (Alone) and not to join partners with Him. To Him (Alone) I call and to Him is my return.\"', 'Those to whom We have given the Book are happy with what has been sent down to you. And among their groups there are those who deny some of it. Say, “I am commanded only to worship Allah and not to ascribe partners to Him. To Him I call and to Him is my return.”'),
(1744, 13, 37, 5, 11, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ کَذٰلِکَ اَنۡزَلۡنٰہُ حُکۡمًا عَرَبِیًّا ؕ وَ لَئِنِ اتَّبَعۡتَ اَہۡوَآءَہُمۡ بَعۡدَ مَا جَآءَکَ مِنَ الۡعِلۡمِ ۙ مَا لَکَ مِنَ اللّٰہِ مِنۡ وَّلِیٍّ وَّ لَا  وَاقٍ ﴿٪۳۷﴾', 'اور اسی طرح ہم نے اس قرآن کو عربی زبان کا فرمان بنا کر نازل کیا ہے۔ اور اگر تم علم آ جانے کے بعد ان لوگوں کی خواہشوں کے پیچھے چلو گے تو اللہ کے سامنے کوئی نہ تمہارا مددگار ہو گا اور نہ کوئی بچانے والا۔', 'اور اسی طرح اتارا ہم نے یہ کلام  حکم عربی زبان میں [۷۳] اور اگر تو چلے انکی خواہش کے موافق بعد اس علم کےجو تجھ کو پہنچ چکا کوئی نہیں تیرا اللہ سے حمایتی اور نہ بچانے والا [۷۴]', 'And thus have We sent it (the Quran) down to be a judgement of authority in Arabic. Were you (O Muhammad SAW) to follow their (vain) desires after the knowledge which has come to you, then you will not have any Walee (protector) or defender against Allah.', 'Thus We have sent it down, being a command in Arabic. And if you follow their desires, after the knowledge that has come to you, there shall be neither a friend for you against Allah, nor a savior.'),
(1745, 13, 38, 6, 12, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ لَقَدۡ اَرۡسَلۡنَا رُسُلًا مِّنۡ قَبۡلِکَ وَ جَعَلۡنَا لَہُمۡ  اَزۡوَاجًا وَّ ذُرِّیَّۃً ؕ وَ مَا کَانَ لِرَسُوۡلٍ اَنۡ یَّاۡتِیَ بِاٰیَۃٍ  اِلَّا بِاِذۡنِ اللّٰہِ ؕ لِکُلِّ  اَجَلٍ  کِتَابٌ ﴿۳۸﴾', 'اور اے نبی ہم نے تم سے پہلے بھی پیغمبر بھیجے تھے اور انکو بیویاں اور اولاد بھی دی تھی۔ اور کسی پیغمبر کے اختیار کی بات نہ تھی کہ اللہ کے حکم کے بغیر کوئی نشانی لے آتا۔ ہر حکم قضا کتاب میں لکھا ہوا ہے۔', 'اور بھیج چکے ہیں ہم کتنے رسول تجھ سے پہلے اور ہم نے دی تھیں انکو جو روئیں اور اولاد اور نہیں ہوا کسی رسول سے کہ وہ لے آئے کوئی نشانی مگر اللہ کے اذن سے ہر ایک وعدہ ہے لکھا ہوا [۷۵]', 'And indeed We sent Messengers before you (O Muhammad SAW), and made for them wives and offspring. And it was not for a Messenger to bring a sign except by Allahs Leave. (For) each and every matter there is a Decree (from Allah).', 'We have sent messengers before you, and gave them wives and children. It is not for a messenger to bring a verse without the will of Allah. For every age there are some rules prescribed.'),
(1746, 13, 39, 6, 12, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'یَمۡحُوا اللّٰہُ مَا یَشَآءُ وَ یُثۡبِتُ ۚۖ وَ عِنۡدَہٗۤ   اُمُّ   الۡکِتٰبِ ﴿۳۹﴾', 'اللہ جس چیز کو چاہتا ہے مٹا دیتا ہے اور جسکو چاہتا ہے باقی رکھتا ہے اور اسی کے پاس اصل کتاب ہے۔', 'مٹاتا ہے اللہ جو چاہے اور باقی رکھتا ہے اور اسی کے پاس ہے اصل کتاب [۷۶]', 'Allah blots out what He wills and confirms (what He wills). And with Him is the Mother of the Book (Al-Lauh Al-Mahfooz)', 'Allah wipes off what He wills and affirms (what He wills), and with Him is the Mother Book.'),
(1747, 13, 40, 6, 12, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ  اِنۡ مَّا نُرِیَنَّکَ بَعۡضَ الَّذِیۡ نَعِدُہُمۡ  اَوۡ نَتَوَفَّیَنَّکَ فَاِنَّمَا عَلَیۡکَ الۡبَلٰغُ وَ عَلَیۡنَا  الۡحِسَابُ  ﴿۴۰﴾', 'اور اگر ہم کوئی عذاب جس کا ان لوگوں سے وعدہ کرتے ہیں تمہیں دکھائیں یعنی تمہارے روبرو ان پر نازل کریں یا تمہاری مدت حیات پوری کر دیں یعنی تمہارے انتقال کے بعد عذاب بھیجیں تو تمہارا کام ہمارے احکام کا پہنچا دینا ہے اور ہمارا کام حساب لینا ہے۔', 'اور اگر دکھلا دیں ہم تجھ کو کوئی وعدہ جو ہم نے کیا ہے ان سے یا تجھ کو اٹھالیویں سو تیرا ذمہ تو پہنچا دینا ہے اور ہمارا ذمہ ہے حساب لینا [۷۷]', 'Whether We show you (O Muhammad SAW) part of what We have promised them or cause you to die, your duty is only to convey (the Message) and on Us is the reckoning.', 'And if We show you (O prophet) some of what We have promised to them, or We take you back to Us (before that), in both cases you have only to convey the message, and We have to reckon.'),
(1748, 13, 41, 6, 12, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'اَوَ لَمۡ  یَرَوۡا اَنَّا نَاۡتِی الۡاَرۡضَ نَنۡقُصُہَا مِنۡ اَطۡرَافِہَا ؕ وَ اللّٰہُ یَحۡکُمُ  لَا مُعَقِّبَ لِحُکۡمِہٖ ؕ وَ ہُوَ  سَرِیۡعُ  الۡحِسَابِ ﴿۴۱﴾', 'کیا انہوں نے نہیں دیکھا کہ ہم زمین کو اسکے کناروں سے گھٹاتے چلے آ رہے ہیں اور اللہ جیسا چاہتا ہے حکم کرتا ہے کوئی اسکے حکم کا رد کرنے والا نہیں اور وہ جلد حساب لینے والا ہے۔', 'کیا وہ نہیں دیکھتے کہ ہم چلے آتے ہیں زمین کو گھٹاتے اس کے کناروں سے [۷۸] اور اللہ حکم کرتا ہے کوئی نہیں کہ پیچھے ڈالے اس کا حکم [۷۹] اور وہ جلد لیتا ہے حساب [۸۰]', 'See they not that We gradually reduce the land (of disbelievers, by giving it to the believers, in war victories) from its outlying borders. And Allah judges, there is none to put back His Judgement and He is Swift at reckoning.', 'Have they not seen that We are coming to the land narrowing it down from all its sides? Allah judges; there is none to repel His judgement. And He is swift at reckoning.'),
(1749, 13, 42, 6, 12, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ قَدۡ مَکَرَ الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ فَلِلّٰہِ الۡمَکۡرُ  جَمِیۡعًا ؕ یَعۡلَمُ  مَا تَکۡسِبُ کُلُّ نَفۡسٍ ؕ وَ سَیَعۡلَمُ  الۡکُفّٰرُ  لِمَنۡ  عُقۡبَی الدَّارِ ﴿۴۲﴾', 'جو لوگ ان سے پہلے تھے وہ بھی بہتیری تدبیریں کرتے رہے ہیں سو تدبیر تو سب اللہ ہی کی ہوتی ہے۔ ہر شخص جو کچھ کر رہا ہے اللہ اسے جانتا ہے اور کافر جلد معلوم کر لیں گے کہ آخرت میں اچھا انجام کس کے لئے ہوتا ہے۔', 'اور فریب کر چکے ہیں جو ان سے پہلے تھے سو اللہ کے ہاتھ میں ہے سب فریب [۸۱] جانتا ہے جو کچھ کماتا ہے ہر ایک جی [۸۲] اور اب معلوم کئے لیتے ہیں کافر کہ کس کا ہوتا ہے پچھلا گھر [۸۳]', 'And verily, those before them did devise plots, but all planning is Allahs. He knows what every person earns, and the disbelievers will know who gets the good end (final destination).', 'Those before them did devise plans, but all the real plans belong only to Allah. He knows what every soul earns, and the disbelievers will soon know for whom is the excellent end.'),
(1750, 13, 43, 6, 12, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الرعد', 'وَ یَقُوۡلُ الَّذِیۡنَ کَفَرُوۡا لَسۡتَ مُرۡسَلًا ؕ قُلۡ  کَفٰی بِاللّٰہِ  شَہِیۡدًۢا بَیۡنِیۡ وَ بَیۡنَکُمۡ ۙ وَ مَنۡ عِنۡدَہٗ  عِلۡمُ  الۡکِتٰبِ ﴿٪۴۳﴾', 'اور کافر لوگ کہتے ہیں کہ تم  پیغمبر نہیں ہو۔ کہدو کہ میرے اور تمہارے درمیان اللہ اور وہ شخص جسکے پاس کتاب آسمانی کا علم ہے بطور گواہ کافی ہے۔', 'اور کہتےہیں کافر تو بھیجا ہوا نہیں آیا کہدے اللہ کافی ہے گواہ میرے اور تمہارے بیچ میں [۸۴] اور جس کو خبر ہے کتاب کی [۸۵]', 'And those who disbelieve, say: \"You (O Muhammad SAW) are not a Messenger.\" Say: \"Sufficient for a witness between me and you is Allah and those too who have knowledge of the Scripture (such as Abdullah bin Salam and other Jews and Christians who embraced Islam).\"', 'The disbelievers say, “You are not a messenger.” Say, “Allah is sufficient as a witness between me and you, and those too (are my witnesses) who have the knowledge of the Book.”'),
(1751, 14, 1, 1, 13, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'الٓرٰ ۟ کِتٰبٌ اَنۡزَلۡنٰہُ  اِلَیۡکَ لِتُخۡرِجَ النَّاسَ مِنَ الظُّلُمٰتِ اِلَی النُّوۡرِ ۬ۙ بِاِذۡنِ رَبِّہِمۡ  اِلٰی صِرَاطِ الۡعَزِیۡزِ  الۡحَمِیۡدِ ۙ﴿۱﴾', 'الٓرا۔  یہ ایک پرنور کتاب ہے اس کو ہم نے تم پر اس لئے نازل کیا ہے کہ تم لوگوں کو اندھیروں سے نکال کر روشنی کی طرف لے جاؤ یعنی انکے پروردگار کے حکم سے عزت والے خوبیوں والے مالک کے رستے کی طرف۔', 'الرٓ  یہ ایک کتاب ہے کہ ہم نے اتاری تیری طرف کہ تو نکالے لوگوں کو اندھیروں سے اجالے کی طرف انکے رب کے حکم سے [۱] رستہ (راہ) پر (کی طرف) اس زبردست خوبیوں والے', 'Alif-Lam-Ra.(These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings).(This is) a Book which We have revealed unto you (O Muhammad SAW) in order that you might lead mankind out of darkness (of disbelief and polytheism) into light (of belief in the Oneness of Allah and Islamic Monotheism) by their Lords Leave to the Path of the All-Mighty, the Owner of all Praise.', 'Alif, Lām, Rā. This is a book We have sent down to you, so that you may deliver the people, with the will of their Lord, out of all sorts of darkness into the light, leading them to the path of the Almighty, the Praiseworthy'),
(1752, 14, 2, 1, 13, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'اللّٰہِ الَّذِیۡ لَہٗ  مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ؕ وَ وَیۡلٌ لِّلۡکٰفِرِیۡنَ مِنۡ عَذَابٍ  شَدِیۡدِۣ ۙ﴿۲﴾', 'یعنی اس اللہ کے راستے کی طرف کہ جو کچھ آسمانوں اور زمین میں ہے سب اسی کا ہے۔ اور ان کافروں کے لئے عذاب شدید کی وجہ سے تباہی اور بربادی مقدر ہے۔', 'اللہ کہ جس کا ہے جو کچھ کہ موجود ہے آسمانوں میں اور جو کچھ ہے زمین میں [۲] اور مصیبت ہے کافروں کو ایک سخت عذاب سے [۳]', 'Allah to Whom belongs all that is in the heavens and all that is in the earth! And woe unto the disbelievers from a severe torment.', 'Allah, the One to whom belongs what is in the heavens and what is in the earth. Woe be to the disbelievers because of a severe punishment,'),
(1753, 14, 3, 1, 13, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'الَّذِیۡنَ  یَسۡتَحِبُّوۡنَ الۡحَیٰوۃَ  الدُّنۡیَا عَلَی الۡاٰخِرَۃِ وَ یَصُدُّوۡنَ عَنۡ سَبِیۡلِ اللّٰہِ  وَ یَبۡغُوۡنَہَا عِوَجًا ؕ اُولٰٓئِکَ فِیۡ ضَلٰلٍۭ بَعِیۡدٍ ﴿۳﴾', 'جو آخرت کے مقابلے میں دنیاوی زندگی کو پسند کرتے اور لوگوں کو اللہ کے رستے سے روکتے اور اس میں کجی چاہتے ہیں یہ لوگ بڑے دور کی گمراہی میں ہیں۔', 'جو کہ پسند رکھتے ہیں زندگی دنیا کی آخرت سے اور روکتے ہیں اللہ کی راہ سے اور تلاش کرتے ہیں (نکالنا چاہے ہیں) اس میں کجی وہ راستہ بھول کر جاپڑے ہیں دور [۴]', 'Those who prefer the life of this world instead of the Hereafter, and hinder (men) from the Path of Allah (i.e.Islam) and seek crookedness therein - They are far astray.', 'to those who prefer the worldly life to the Hereafter and prevent (people) from the way of Allah, and seek to make it crooked. Those have gone too far in straying.'),
(1754, 14, 4, 1, 13, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ مَاۤ  اَرۡسَلۡنَا مِنۡ رَّسُوۡلٍ  اِلَّا بِلِسَانِ قَوۡمِہٖ  لِیُبَیِّنَ لَہُمۡ ؕ فَیُضِلُّ اللّٰہُ مَنۡ یَّشَآءُ  وَ یَہۡدِیۡ مَنۡ یَّشَآءُ ؕ وَ ہُوَ الۡعَزِیۡزُ  الۡحَکِیۡمُ ﴿۴﴾', 'اور ہم نے کوئی پیغمبر نہیں بھیجا مگر وہ اپنی قوم کی زبان بولتا تھا تاکہ انہیں احکام الٰہی کھول کھول کر بتا دے۔ پھر اللہ جسے چاہتا ہے گمراہ  رہنے دیتا ہے۔ اور جسے چاہتا ہے ہدایت دیتا ہے اور وہ غالب ہے حکمت والا ہے۔', 'اور کوئی رسول نہیں بھیجا ہم نے مگر بولی بولنے والا اپنی قوم کی تاکہ ان کو سمجھائے [۵] پھر راستہ بھلاتا ہے (بھٹکاتا ہے) اللہ جس کو چاہے اور راستہ دکھلا دیتا ہے (دیتا ہے ) جسکو چاہے اور وہ ہے زبردست حکمتوں والا [۶]', 'And We sent not a Messenger except with the language of his people, in order that he might make (the Message) clear for them. Then Allah misleads whom He wills and guides whom He wills. And He is the All-Mighty, the All-Wise.', 'We did not send any messenger but (speaking) in the language of his people, so that he might clearly convey the message to them. So, Allah lets go astray whom He wills and lets find guidance whom He wills. And He is the Mighty, the Wise.'),
(1755, 14, 5, 1, 13, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ لَقَدۡ اَرۡسَلۡنَا مُوۡسٰی بِاٰیٰتِنَاۤ  اَنۡ  اَخۡرِجۡ  قَوۡمَکَ مِنَ الظُّلُمٰتِ  اِلَی النُّوۡرِ ۬ۙ وَ ذَکِّرۡہُمۡ بِاَیّٰىمِ اللّٰہِ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیٰتٍ  لِّکُلِّ  صَبَّارٍ  شَکُوۡرٍ ﴿۵﴾', 'اور ہم نے موسٰی کو اپنی نشانیاں دے کر بھیجا کہ اپنی قوم کو تاریکیوں سے نکال کر روشنی میں لے جاؤ۔ اور ان کو اللہ کے دن یاد دلاؤ۔ اور اس میں ان لوگوں کے لئے جو صابر و شاکر ہیں نشانیاں ہیں۔', 'اور بھیجا تھا ہم نے موسٰی کو اپنی نشانیاں دے کر کہ نکال اپنی قوم کو اندھیروں سے اجالے کی طرف اور یاد دلا انکو دن اللہ کے البتہ اس میں نشانیاں ہیں اس کو جو صبر کرنے والا ہے شکر گذار (حق ماننے والا) [۷]', 'And indeed We sent Moosa (Moses) with Our Ayat (signs, proofs, and evidences) (saying): \"Bring out your people from darkness into light, and make them remember the annals of Allah. Truly, therein are evidences, proofs and signs for every patient, thankful (person).\"', 'Surely, We sent Mūsā with Our signs saying to him, “Bring your people out of (all sorts of) darkness into the light, and remind them of the Days of Allah. Surely, there are signs therein for every one who observes patience and gratitude.'),
(1756, 14, 6, 1, 13, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ  اِذۡ  قَالَ مُوۡسٰی لِقَوۡمِہِ اذۡکُرُوۡا نِعۡمَۃَ اللّٰہِ عَلَیۡکُمۡ  اِذۡ  اَنۡجٰکُمۡ مِّنۡ اٰلِ فِرۡعَوۡنَ یَسُوۡمُوۡنَکُمۡ سُوۡٓءَ الۡعَذَابِ وَ یُذَبِّحُوۡنَ  اَبۡنَآءَکُمۡ وَ یَسۡتَحۡیُوۡنَ نِسَآءَکُمۡ ؕ وَ فِیۡ  ذٰلِکُمۡ بَلَآءٌ  مِّنۡ رَّبِّکُمۡ  عَظِیۡمٌ ٪﴿۶﴾', 'اور جب موسٰی نے اپنی قوم سے کہا کہ اللہ نے جو تم پر مہربانیاں کی ہیں انکو یاد کرو جبکہ اس نے تم کو فرعون کی قوم سے رہائی بخشی۔ وہ لوگ تمہیں برے برے عذاب دیتے تھے اور تمہارے بیٹوں کو مار ڈالتے تھے اور تمہاری لڑکیوں کو زندہ رہنے دیتے تھے۔ اور اس میں تمہارے پروردگار کی طرف سے بڑی آزمائش تھی۔', 'اور جب کہا موسٰی نے اپنی قوم کو یاد کرو اللہ کا احسان اپنے اوپر جب چھڑا دیا تم کو فرعون کی قوم سے وہ پہنچاتے تھے تم کو برا عذاب [۸] اور ذبح کرتے تمہارے بیٹوں کو اور زندہ رکھتے تمہاری عورتوں کو اور اس میں مدد ہوئی تمہارے رب کی طرف سے بڑی [۹]', 'And (remember) when Moosa (Moses) said to his people: \"Call to mind Allahs Favour to you, when He delivered you from Firauns (Pharaoh) people who were afflicting you with horrible torment, and were slaughtering your sons and letting your women alive, and in it was a tremendous trial from your Lord.\"', 'And when Mūsā said to his people, “Remember Allah’s blessing upon you when He delivered you from Pharaoh’s people who had been inflicting a grievous torment on you, slaughtering your sons and leaving your women alive. In that there was a great trial from your Lord.”'),
(1757, 14, 7, 2, 14, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ اِذۡ  تَاَذَّنَ  رَبُّکُمۡ  لَئِنۡ شَکَرۡتُمۡ لَاَزِیۡدَنَّکُمۡ  وَ لَئِنۡ کَفَرۡتُمۡ  اِنَّ عَذَابِیۡ لَشَدِیۡدٌ ﴿۷﴾', 'اور جب تمہارے پروردگار نے تم کو آگاہ کیا کہ اگر شکر کرو گے تو میں تمہیں زیادہ دوں گا اور اگر ناشکری کرو گے تو یاد رکھو کہ میرا عذاب بھی سخت ہے۔', 'اور جب سنا دیا تمہارے رب نے اگر احسان مانو گے تو اور بھی دوں گا تم کو [۱۰] اور اگر ناشکری کرو گے تو میرا عذاب البتہ سخت ہے [۱۱]', 'And (remember) when your Lord proclaimed: \"If you give thanks (by accepting Faith and worshipping none but Allah), I will give you more (of My Blessings), but if you are thankless (i.e. disbelievers), verily! My Punishment is indeed severe.\"', '(Recall the time) when your Lord declared, “If you express gratitude, I shall certainly give you more, and if you are ungrateful, then My punishment is severe.”'),
(1758, 14, 8, 2, 14, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ قَالَ مُوۡسٰۤی  اِنۡ تَکۡفُرُوۡۤا اَنۡتُمۡ  وَ  مَنۡ فِی الۡاَرۡضِ جَمِیۡعًا ۙ فَاِنَّ اللّٰہَ لَغَنِیٌّ حَمِیۡدٌ ﴿۸﴾', 'اور موسٰی نے صاف صاف کہدیا کہ اگر تم اور جتنے اور لوگ زمین میں ہیں سب کے سب ناشکری کرو تو بھی اللہ بےنیاز ہے قابل تعریف ہے۔', 'اور کہا موسٰی نے اگر کفر (منکر ہو گے) کرو گے تم اور جو لوگ زمین میں ہیں سارے تو اللہ بے پروا ہے سب خوبیوں والا [۱۲]', 'And Moosa (Moses) said: \"If you disbelieve, you and all on earth together, then verily! Allah is Rich (Free of all wants), Owner of all Praise.\"', 'And Mūsā said, “If you and all those on earth become ungrateful, then Allah is free of all needs, worthy of every praise.”'),
(1759, 14, 9, 2, 14, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'اَلَمۡ یَاۡتِکُمۡ نَبَؤُا الَّذِیۡنَ مِنۡ قَبۡلِکُمۡ قَوۡمِ نُوۡحٍ وَّ عَادٍ وَّ ثَمُوۡدَ ۬ؕۛ وَ الَّذِیۡنَ مِنۡۢ بَعۡدِہِمۡ ؕۛ لَا  یَعۡلَمُہُمۡ  اِلَّا اللّٰہُ ؕ جَآءَتۡہُمۡ رُسُلُہُمۡ بِالۡبَیِّنٰتِ فَرَدُّوۡۤا اَیۡدِیَہُمۡ فِیۡۤ  اَفۡوَاہِہِمۡ وَ قَالُوۡۤا اِنَّا کَفَرۡنَا بِمَاۤ  اُرۡسِلۡتُمۡ  بِہٖ وَ  اِنَّا  لَفِیۡ شَکٍّ مِّمَّا  تَدۡعُوۡنَنَاۤ   اِلَیۡہِ  مُرِیۡبٍ ﴿۹﴾', 'بھلا تم کو ان لوگوں کے حالات کی خبر نہیں پہنچی جو تم سے پہلے تھے۔ یعنی نوح اور عاد اور ثمود کی قوم اور جو انکے بعد تھے۔ جن کا علم اللہ کے سوا کسی کو نہیں۔ جب انکے پاس انکے پیغمبر نشانیاں لے کر آئے تو انہوں نے اپنے ہاتھ ان کے مونہوں پر رکھ دیئے کہ خاموش رہو اور کہنے لگے کہ ہم تو تمہاری رسالت کو تسلیم نہیں کرتے اور جس چیز کی طرف تم ہمیں بلاتے ہو ہم کو اس میں بھاری شک ہے۔', 'کیا نہیں پہنچی تم کو خبر ان لوگوں کی جو پہلے تھے تم سے قوم نوح کی اور عاد اور ثمود اور جو ان سے پیچھے ہوئے کسی کو انکی خبر نہیں مگر اللہ کو [۱۳] آئے انکے پاس انکے رسول نشانیاں لے کر پھر لوٹائے (الٹے دے لئے) انہوں نے اپنے ہاتھ اپنے منہ میں [۱۴] اور بولے ہم نہیں مانتے جو تم کو دے کر بھیجا اور ہم کو تو شبہ ہے اس راہ میں جسکی طرف تم ہم کو بلاتے ہو خلجان میں ڈالنے والا', 'Has not the news reached you, of those before you, the people of Nooh (Noah), and Ad, and Thamud? And those after them? None knows them but Allah. To them came their Messengers with clear proofs, but they put their hands in their mouths (biting them from anger) and said: \"Verily, we disbelieve in that with which you have been sent, and we are really in grave doubt as to that to which you invite us (i.e. Islamic Monotheism).\"', 'Has there not come to you the news of those before you, the people of NūH, ‘Ād and Thamūd and of those after them. No one knows them except Allah. Their prophets came to them with clear signs, but they put their hands into their mouths and said, “We reject what you are sent with, and indeed we are in confounding doubt about what you are calling us to believe.”'),
(1760, 14, 10, 2, 14, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'قَالَتۡ رُسُلُہُمۡ اَفِی اللّٰہِ شَکٌّ فَاطِرِ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ یَدۡعُوۡکُمۡ  لِیَغۡفِرَ لَکُمۡ مِّنۡ ذُنُوۡبِکُمۡ وَ یُؤَخِّرَکُمۡ اِلٰۤی اَجَلٍ مُّسَمًّی ؕ قَالُوۡۤا اِنۡ اَنۡتُمۡ  اِلَّا بَشَرٌ مِّثۡلُنَا ؕ تُرِیۡدُوۡنَ  اَنۡ تَصُدُّوۡنَا عَمَّا کَانَ یَعۡبُدُ اٰبَآؤُنَا فَاۡتُوۡنَا بِسُلۡطٰنٍ مُّبِیۡنٍ ﴿۱۰﴾', 'انکے پیغمبروں نے کہا کیا تم کو اللہ کے بارے میں شک ہے جو آسمانوں اور زمین کا پیدا کرنے والا ہے۔ وہ تمہیں اس لئے بلا تا ہے کہ تمہارے گناہ بخشے اور ایک مدت مقرر تک تمکو مہلت دے۔ وہ بولے کہ تم تو ہمارے ہی جیسے آدمی ہو۔ تمہارا یہ منشا ہے کہ جن چیزوں کو ہمارے بڑے پوجتے رہے ہیں انکے پوجنے سے تم ہمیں روکدو تو اچھا کوئی کھلی دلیل لاؤ یعنی معجزہ دکھاؤ۔', 'بولے انکے رسول کیا اللہ میں شبہ ہے جس نے بنائے آسمان اور زمین [۱۵] وہ تم کو بلاتا ہے تاکہ بخشے تم کو کچھ گناہ تمہارے [۱۶] اور ڈھیل دے تم کو ایک وعدہ تک جو ٹھہر چکا ہے [۱۷] کہنے لگے تم تو یہی آدمی ہو ہم جیسے تم چاہتے ہو کہ روک دو ہم کو ان چیزوں سے جن کو پوجتے رہے ہمارے باپ دادے سو لاؤ کوئی سند کھلی ہوئی [۱۸]', 'Their Messengers said: \"What! Can there be a doubt about Allah, the Creator of the heavens and the earth? He calls you (to Monotheism and to be obedient to Allah) that He may forgive you of your sins and give you respite for a term appointed.\" They said: \"You are no more than human beings like us! You wish to turn us away from what our fathers used to worship. Then bring us a clear authority i.e. a clear proof of what you say).\"', 'Their prophets said, “Is it in Allah that you have some doubt, who is the Creator of the heavens and the earth? He calls you, so that He may forgive you some of your sins and give you respite up to a specified term.” They said, “You are no more than a human being like us. You want to prevent us from what our forefathers used to worship. So, bring us some clear authority.”'),
(1761, 14, 11, 2, 14, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'قَالَتۡ لَہُمۡ رُسُلُہُمۡ  اِنۡ نَّحۡنُ اِلَّا بَشَرٌ مِّثۡلُکُمۡ  وَ لٰکِنَّ اللّٰہَ یَمُنُّ عَلٰی مَنۡ یَّشَآءُ مِنۡ عِبَادِہٖ ؕ وَ مَا کَانَ لَنَاۤ  اَنۡ نَّاۡتِیَکُمۡ بِسُلۡطٰنٍ اِلَّا بِاِذۡنِ اللّٰہِ ؕ وَ عَلَی اللّٰہِ  فَلۡیَتَوَکَّلِ  الۡمُؤۡمِنُوۡنَ ﴿۱۱﴾', 'پیغمبروں نے ان سے کہا کہ ہاں ہم تمہارے ہی جیسے آدمی ہیں لیکن اللہ اپنے بندوں میں سے جس پر چاہتا ہے نبوت کا احسان کرتا ہے۔ اور ہمارے اختیار کی بات نہیں کہ ہم اللہ کے حکم کے بغیر تم کو تمہاری فرمائش کے مطابق معجزہ دکھائیں اور اللہ ہی پر مومنوں کو تو بھروسہ رکھنا چاہیے۔', 'ان کو کہا ان کے رسولوں نے ہم تو یہی آدمی ہیں جیسےتم لیکن اللہ احسان کرتا ہے اپنے بندوں میں جس پر چاہے [۱۹] اور ہمارا کام نہیں کہ لے آئیں تمہارے پاس سند مگر اللہ کے حکم سے اور اللہ پر بھروسہ چاہئے ایمان والوں کو [۲۰]', 'Their Messengers said to them: \"We are no more than human beings like you, but Allah bestows His Grace to whom He wills of His slaves. It is not ours to bring you an authority (proof) except by the Permission of Allah. And in Allah (Alone) let the believers put their trust.', 'Their prophets said to them, “We are no more than a human being like you, but Allah bestows His favour upon whom He wills from among His servants. It is not for us to bring you an authority without Allah’s permission, and in Allah the believers must place their trust.'),
(1762, 14, 12, 2, 14, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ مَا لَنَاۤ  اَلَّا نَتَوَکَّلَ عَلَی اللّٰہِ وَ قَدۡ ہَدٰىنَا سُبُلَنَا ؕ وَ لَنَصۡبِرَنَّ عَلٰی مَاۤ اٰذَیۡتُمُوۡنَا ؕ وَ عَلَی اللّٰہِ فَلۡیَتَوَکَّلِ الۡمُتَوَکِّلُوۡنَ ﴿٪۱۲﴾', 'اور ہم کیوں اللہ پر بھروسہ نہ رکھیں حالانکہ اس نے ہم کو ہمارے دین کے سیدھے رستے بتائے ہیں اور جو تکلیفیں تم ہم کو دیتے ہو اس پر ہم صبر کریں گے۔ اور اہل توکل کو تو اللہ ہی پر بھروسہ رکھنا چاہیے۔', 'اور ہم کو کیا ہوا کہ بھروسہ نہ کریں اللہ پر اور وہ سمجھا چکا ہم کو ہماری راہیں [۲۱] اور ہم صبر کریں گے ایذا پر جو تم ہم کو دیتے ہو اور اللہ پر بھروسہ چاہئے بھروسے والوں کو [۲۲]', '\"And why should we not put our trust in Allah while He indeed has guided us our ways. And we shall certainly bear with patience all the hurt you may cause us, and in Allah (Alone) let those who trust, put their trust.\"', 'What is wrong with us that we should not put our trust in Allah when He has guided us to our paths? We shall, of course, endure with patience all your persecutions; and all those who have to trust should trust only in Allah.”'),
(1763, 14, 13, 3, 15, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ قَالَ الَّذِیۡنَ کَفَرُوۡا لِرُسُلِہِمۡ لَنُخۡرِجَنَّکُمۡ مِّنۡ اَرۡضِنَاۤ  اَوۡ لَتَعُوۡدُنَّ فِیۡ مِلَّتِنَا ؕ فَاَوۡحٰۤی اِلَیۡہِمۡ رَبُّہُمۡ لَنُہۡلِکَنَّ  الظّٰلِمِیۡنَ ﴿ۙ۱۳﴾', 'اور جو کافر تھے انہوں نے اپنے پیغمبروں سے کہا کہ یا تو ہم تم کو اپنے ملک سے باہر نکال دیں گے یا تم ہمارے مذہب میں واپس آ جاؤ۔ پس انکے پروردگار نے انکی طرف وحی بھیجی کہ ہم ظالموں کو ہلاک کر دیں گے۔', 'اور کہا کافروں نے اپنے رسولوں کو ہم نکال دیں گے تم کو اپنی زمین سے یا لوٹ آؤ ہمارے دین میں [۲۳] تب حکم بھیجا انکو ان کے رب نے ہم غارت کریں گے ان ظالموں کو', 'And those who disbelieved, said to their Messengers: \"Surely, we shall drive you out of our land, or you shall return to our religion.\" So their Lord inspired them: \"Truly, We shall destroy the Zalimoon (polytheists, disbelievers and wrong-doers.).', 'The disbelievers said to their prophets, “We shall certainly expel you from our land unless you come back to our faith.” So, their Lord revealed to them, “We shall destroy the transgressors,'),
(1764, 14, 14, 3, 15, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ لَنُسۡکِنَنَّـکُمُ الۡاَرۡضَ مِنۡۢ بَعۡدِہِمۡ ؕ ذٰلِکَ لِمَنۡ خَافَ مَقَامِیۡ وَ خَافَ وَعِیۡدِ ﴿۱۴﴾', 'اور انکے بعد تم کو اس زمین میں آباد کر دیں گے۔ یہ اس شخص کے لئے ہے جو قیامت کے روز میرے سامنے کھڑے ہونے سے ڈرے اور میرے عذاب سے خوف کرے۔', 'اور آباد کریں گے تم کو اس زمین میں ان کے پیچھے [۲۴] یہ ملتا ہے اس کو جو ڈرتا ہے کھڑے ہونے سے میرے سامنے اور ڈرتا ہے میرے عذاب کے وعدہ سے [۲۵]', '\"And indeed, We shall make you dwell in the land after them. This is for him who fears standing before Me (on the Day of Resurrection or fears My Punishment) and also fears My Threat.\"', 'and shall certainly let you dwell in the land after them. This is for the one who is fearful of standing before Me and is fearful of My warning.”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1765, 14, 15, 3, 15, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ اسۡتَفۡتَحُوۡا وَ خَابَ  کُلُّ جَبَّارٍ عَنِیۡدٍ ﴿ۙ۱۵﴾', 'اور پیغمبروں نے اللہ سے فتح چاہی اور ہر سرکش ضدی نامراد رہ گیا۔', 'اور فیصلہ (فتح) لگے ماننے پیغمبر [۲۶] اور نامراد ہو ا ہر ایک سرکش ضدی (ضد کرنے والا) [۲۷]', 'But they (the Messengers) sought victory and help (from their Lord (Allah)), and every obstinate, arrogant dictator (who refuses to believe in the Oneness of Allah) was brought to a complete loss and destruction.', 'They sought final decision (by demanding the divine scourge), and (thus) every obstinate tyrant failed.'),
(1766, 14, 16, 3, 15, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'مِّنۡ وَّرَآئِہٖ جَہَنَّمُ وَ یُسۡقٰی مِنۡ مَّآءٍ صَدِیۡدٍ ﴿ۙ۱۶﴾', 'اسکے پیچھے دوزخ ہے اور اسے پیپ والا پانی پلایا جائے گا۔', 'پیچھے اس کے دوزخ ہے اور پلائیں گے اس کو پانی پیپ کا [۲۸]', 'In front of him (every obstinate, arrogant dictator) is Hell, and he will be made to drink boiling, festering water.', 'The Hell is pursuing him, and he shall be made to drink pus-fluid,'),
(1767, 14, 17, 3, 15, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'یَّتَجَرَّعُہٗ  وَ لَا یَکَادُ یُسِیۡغُہٗ  وَ یَاۡتِیۡہِ الۡمَوۡتُ مِنۡ کُلِّ مَکَانٍ وَّ مَا ہُوَ  بِمَیِّتٍ ؕ وَ مِنۡ  وَّرَآئِہٖ  عَذَابٌ  غَلِیۡظٌ ﴿۱۷﴾', 'وہ اسکو گھونٹ گھونٹ کر کے پئے گا اور گلے سے نہیں اتار سکے گا اور ہر طرف سے اسے موت آ رہی ہو گی مگر وہ مرنے میں نہیں آئے گا اور اسکے بعد سخت عذاب ہو گا۔', 'گھونٹ گھونٹ پیتا ہے اسکو اور گلے سے نہیں اتار سکتا [۲۹] اور چلی آتی ہے اس پر موت ہر طرف (جگہ) سے اور وہ نہیں مرتا اور اس کے پیچھے عذاب ہے سخت [۳۰]', 'He will sip it unwillingly, and he will find a great difficulty to swallow it down his throat, and death will come to him from every side, yet he will not die and in front of him, will be a great torment.', 'which he will arduously sip, and will not be able to swallow. Death will come upon him from every side, yet he will not die, and still a heavy chastisement will be ahead of him.'),
(1768, 14, 18, 3, 15, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'مَثَلُ الَّذِیۡنَ کَفَرُوۡا بِرَبِّہِمۡ اَعۡمَالُہُمۡ کَرَمَادِۣ اشۡتَدَّتۡ بِہِ الرِّیۡحُ فِیۡ یَوۡمٍ عَاصِفٍ ؕ لَا یَقۡدِرُوۡنَ مِمَّا کَسَبُوۡا عَلٰی شَیۡءٍ ؕ ذٰلِکَ ہُوَ الضَّلٰلُ الۡبَعِیۡدُ ﴿۱۸﴾', 'جن لوگوں نے اپنے پروردگار سے کفر کیا انکے اعمال کی مثال راکھ کی سی ہے کہ آندھی کے دن اس پر زور کی ہوا چلے جو اسے اڑا لے جائے۔ اسی طرح جو کام وہ کرتے رہے ان پر انکو کچھ قابو نہ ہو گا۔ یہی تو پرلے سرے کی گمراہی ہے۔', 'حال ان لوگوں کا جو منکر ہوئے اپنے رب سے انکے عمل ہیں جیسے وہ راکھ کہ زور کی چلے اس پر ہوا آندھی کے دن کچھ ان کے ہاتھ میں نہ ہو گا اپنی کمائی میں سے یہی ہے بہک کر دور جا پڑنا [۳۱]', 'The parable of those who disbelieve in their Lord is that their works are as ashes, on which the wind blows furiously on a stormy day, they shall not be able to get aught of what they have earned. That is the straying, far away (from the Right Path).', 'The deeds of those who refuse to believe in their Lord are like ashes blown away by the wind on a stormy day. They will not be able to gain anything out of what they did. That is the farthest point of straying away from the right path.'),
(1769, 14, 19, 3, 15, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'اَلَمۡ تَرَ اَنَّ اللّٰہَ خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ بِالۡحَقِّ ؕ اِنۡ یَّشَاۡ یُذۡہِبۡکُمۡ وَ یَاۡتِ  بِخَلۡقٍ  جَدِیۡدٍ ﴿ۙ۱۹﴾', 'کیا تم نے نہیں دیکھا کہ اللہ نے آسمانوں اور زمین کو تدبیر سے پیدا کیا ہے؟ اگر وہ چاہے تو تم کو نابود کر دے اور تمہاری جگہ نئی مخلوق پیدا کر دے۔', 'تو نے کیا نہیں دیکھا کہ اللہ نے بنائے آسمان اور زمین جیسی چاہئے اگر چاہے تم کو لیجائے اور لائے کوئی پیدائش (مخلوق) نئی', 'Do you not see that Allah has created the heavens and the earth with truth? If He will, He can remove you and bring (in your place) a new creation!', 'Have you not seen that Allah has created the heavens and the earth with truth? If He wills, He can put you away and bring a new creation;'),
(1770, 14, 20, 3, 15, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَّ  مَا  ذٰلِکَ  عَلَی  اللّٰہِ  بِعَزِیۡزٍ ﴿۲۰﴾', 'اور یہ اللہ کو کچھ بھی مشکل نہیں۔', 'اور یہ اللہ کو کچھ مشکل نہیں [۳۲]', 'And for Allah that is not hard or difficult (i.e. very easy for Allah).', 'and that is not at all difficult for Allah.'),
(1771, 14, 21, 3, 15, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ بَرَزُوۡا لِلّٰہِ جَمِیۡعًا فَقَالَ الضُّعَفٰٓؤُا لِلَّذِیۡنَ اسۡتَکۡبَرُوۡۤا اِنَّا کُنَّا لَکُمۡ تَبَعًا فَہَلۡ اَنۡتُمۡ مُّغۡنُوۡنَ عَنَّا مِنۡ عَذَابِ اللّٰہِ مِنۡ شَیۡءٍ ؕ قَالُوۡا لَوۡ ہَدٰىنَا اللّٰہُ  لَہَدَیۡنٰکُمۡ ؕ سَوَآءٌ  عَلَیۡنَاۤ  اَجَزِعۡنَاۤ  اَمۡ صَبَرۡنَا مَا لَنَا مِنۡ  مَّحِیۡصٍ  ﴿٪۲۱﴾', 'اور قیامت کے دن سب لوگ اللہ کے سامنے کھڑے ہوں گے تو غریب پیروکار بڑے بن بیٹھنے والوں سے کہیں گے کہ ہم تو تمہارے پیرو تھے۔ کیا تم اللہ کا کچھ عذاب ہم پر سے دفع کر سکتے ہو؟ وہ کہیں گے کہ اگر اللہ ہم کو ہدایت کرتا تو ہم تم کو ہدایت کرتے۔ اب ہم گھبرہٹ ظاہر کریں یا صبر کریں ہمارے حق میں برابر ہے۔ کوئی جگہ رہائی کی ہمارے لئے نہیں ہے۔', 'سامنے کھڑے ہوں گے اللہ کے سارے [۳۳] پھر کہیں گے کمزور بڑائی والوں کو ہم تو تمہارے تابع تھے سو کیا بچاؤ گے ہم کو اللہ کے کسی عذاب سے کچھ[۳۴] وہ کہیں گے اگر ہدایت (راہ پر لانا) کرتا ہم کو اللہ تو البتہ ہم تم کو ہدایت (راہ پر لاتے) کرتے اب برابر ہے ہمارےحق میں ہم بے قراری کریں یا صبر کریں ہم کو نہیں خلاصی [۳۵]', 'And they all shall appear before Allah (on the Day of Resurrection) then the weak will say to those who were arrogant (chiefs): \"Verily, we were following you; can you avail us anything from Allahs Torment?\" They will say: \"Had Allah guided us, we would have guided you. It makes no difference to us (now) whether we rage, or bear (these torments) with patience, there is no place of refuge for us.\"', 'All of them shall appear before Allah. Then, the weak shall say to the arrogant, “We were your followers. So, can you relieve us a little from Allah’s punishment?” They will say, “Had Allah guided us, we would have guided you. It is all the same for us whether we deplore or endure, we have no way out.”'),
(1772, 14, 22, 4, 16, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ قَالَ  الشَّیۡطٰنُ لَمَّا قُضِیَ الۡاَمۡرُ اِنَّ اللّٰہَ وَعَدَکُمۡ وَعۡدَ الۡحَقِّ وَ وَعَدۡتُّکُمۡ فَاَخۡلَفۡتُکُمۡ ؕ وَ مَا کَانَ لِیَ عَلَیۡکُمۡ مِّنۡ سُلۡطٰنٍ  اِلَّاۤ  اَنۡ دَعَوۡتُکُمۡ فَاسۡتَجَبۡتُمۡ لِیۡ ۚ فَلَا تَلُوۡمُوۡنِیۡ وَ لُوۡمُوۡۤا اَنۡفُسَکُمۡ ؕ مَاۤ  اَنَا بِمُصۡرِخِکُمۡ وَ مَاۤ  اَنۡتُمۡ بِمُصۡرِخِیَّ ؕ اِنِّیۡ کَفَرۡتُ بِمَاۤ اَشۡرَکۡتُمُوۡنِ مِنۡ قَبۡلُ ؕ اِنَّ الظّٰلِمِیۡنَ لَہُمۡ  عَذَابٌ اَلِیۡمٌ ﴿۲۲﴾', 'اور جب حساب کتاب کا کام فیصل ہو چکے گا تو شیطان کہے گا جو وعدہ اللہ نے تم سے کیا تھا وہ تو سچا تھا اور جو وعدہ میں نے تم سے کیا تھا وہ جھوٹا تھا۔ اور میرا تم پر کسی طرح کا زور نہیں تھا۔ ہاں میں نے تم کو گمراہی اور باطل کی طرف بلایا تو تم نے جلدی سے اور بےدلیل میرا کہنا مان لیا۔ تو آج مجھے ملامت نہ کرو اپنے آپ ہی کو ملامت کرو۔ نہ میں تمہاری فریاد رسی کر سکتا ہوں اور نہ تم میری فریاد رسی کر سکتے ہو۔ میں اس بات سے انکار کرتا ہوں کہ تم پہلے مجھے شریک بناتے تھے بیشک جو ظالم ہیں انکے لئے درد دینے والا عذاب ہے۔', 'اور بولا شیطان جب فیصل ہو چکا سب کام بیشک اللہ نے تم کو دیا تھا سچا وعدہ اور میں نے تم سے وعدہ کیا پھر (سو) جھوٹا کیا اور میری تم پر کچھ حکومت نہ تھی مگر یہ کہ میں نے بلایا تم کو پھر تم نے مان لیا میری بات کو سو الزام نہ دو مجھ کو اور الزام دو اپنے آپ کو نہ میں تمہاری فریاد کو پہنچوں نہ تم میری فریاد کو پہنچو  میں منکر ہوں (مجھ کو قبول نہیں) جو تم نے مجھ کو شریک بنایا تھا اس سے پہلے البتہ جو ظالم ہیں انکے لئے ہے عذاب دردناک [۳۶]', 'And Shaitan (Satan) will say when the matter has been decided: \"Verily, Allah promised you a promise of truth. And I too promised you, but I betrayed you. I had no authority over you except that I called you, so you responded to me. So blame me not, but blame yourselves. I cannot help you, nor can you help me. I deny your former act in associating me (Satan) as a partner with Allah (by obeying me in the life of the world). Verily, there is a painful torment for the Zalimoon (polytheists and wrong-doers, etc.).\"', 'The Satan will say when the matter will have been decided, “Allah promised you a truthful promise while I gave you a promise and did not fulfill it. I had no authority over you, except that I invited you and you accepted my call. So, do not blame me, but blame yourselves. Neither I can come to your help, nor can you come to my help. I disown your associating me with Allah in the past. Surely, there is a painful punishment for the unjust.”'),
(1773, 14, 23, 4, 16, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ اُدۡخِلَ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ جَنّٰتٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَا بِاِذۡنِ رَبِّہِمۡ ؕ تَحِیَّتُہُمۡ  فِیۡہَا  سَلٰمٌ ﴿۲۳﴾', 'اور جو ایمان لائے اور عمل نیک کرتے رہے وہ بہشتوں میں داخل کئے جائیں گے جنکے نیچے نہریں بہ رہی ہیں اپنے پروردگار کے حکم سے وہ ہمیشہ ان میں رہیں گے وہاں وہ ہر ملاقات پر ایکدوسرے کو سلام کہیں گے۔', 'اور داخل کئے گئے جو لوگ ایمان لائے تھے اور کام کئے تھے نیک باغوں میں جن کے نیچے بہتی ہیں نہریں ہمیشہ رہیں (رہا کریں انہی میں) ان میں اپنے رب کے حکم سے [۳۷] انکی ملاقات ہے وہاں سلام [۳۸]', 'And those who believed (in the Oneness of Allah and His Messengers and whatever they brought) and did righteous deeds, will be made to enter Gardens under which rivers flow, - to dwell therein forever (i.e.in Paradise), with the permission of their Lord. Their greeting therein will be: Salam (peace!).', 'And those who believed and did good deeds shall be admitted to Gardens beneath which rivers flow, living there forever by the will of Allah. There they shall greet each other with “Salām.”'),
(1774, 14, 24, 4, 16, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'اَلَمۡ تَرَ کَیۡفَ ضَرَبَ اللّٰہُ مَثَلًا کَلِمَۃً طَیِّبَۃً  کَشَجَرَۃٍ  طَیِّبَۃٍ اَصۡلُہَا ثَابِتٌ وَّ فَرۡعُہَا فِی  السَّمَآءِ ﴿ۙ۲۴﴾', 'کیا تم نے نہیں دیکھا کہ اللہ نے کلمہ طیبہ کی کیسی مثال بیان فرمائی ہے وہ ایسی ہے جیسے پاکیزہ درخت جس کی جڑ مضبوط ہو اور شاخیں آسمان میں پھیلی ہوں۔', 'تو نے نہ دیکھا کیسی بیان کی اللہ نے ایک مثال [۳۹] بات ستھری [۴۰] جیسے ایک درخت ستھرا [۴۱] اسکی جڑ مضبوط ہے اور ٹہنے (شاخیں) ہیں آسمان میں [۴۲]', 'See you not how Allah sets forth a parable? - A goodly word as a goodly tree, whose root is firmly fixed, and its branches (reach) to the sky (i.e. very high).', 'Have you not seen how Allah has set forth a parable: A good word is like a good tree, having its root firm and its branches in the sky.'),
(1775, 14, 25, 4, 16, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'تُؤۡتِیۡۤ  اُکُلَہَا کُلَّ حِیۡنٍۭ  بِاِذۡنِ رَبِّہَا ؕ وَ یَضۡرِبُ اللّٰہُ  الۡاَمۡثَالَ لِلنَّاسِ لَعَلَّہُمۡ یَتَذَکَّرُوۡنَ ﴿۲۵﴾', 'وہ اپنے پروردگار کے حکم سے ہر موقع پر پھل لاتا ہو اور اللہ لوگوں کے لئے مثالیں بیان فرماتا ہے تاکہ وہ نصیحت حاصل کریں۔', 'لاتا ہے پھل اپنا ہر وقت پر اپنے رب کے حکم سے [۴۳] اور بیان کرتا ہے اللہ مثالیں لوگوں کے واسطے تاکہ وہ فکر کریں (سوچیں)', 'Giving its fruit at all times, by the Leave of its Lord and Allah sets forth parables for mankind in order that they may remember.', 'It brings its fruits at all times with the will of its Lord. Allah sets forth the parables for the people, so that they may take lesson.'),
(1776, 14, 26, 4, 16, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ مَثَلُ کَلِمَۃٍ خَبِیۡثَۃٍ کَشَجَرَۃٍ خَبِیۡثَۃِۣ اجۡتُثَّتۡ مِنۡ فَوۡقِ الۡاَرۡضِ مَا  لَہَا مِنۡ  قَرَارٍ ﴿۲۶﴾', 'اور ناپاک بات یعنی غلط عقیدے کی مثال ناپاک درخت کی سی ہے کہ وہ زمین کے اوپر ہی سے اکھیڑ کر پھینک دیا جائے اسکو ذرا بھی قرار و ثبات نہیں۔', 'اور مثال گندی بات کی [۴۴] جیسے درخت گندا [۴۵] اکھاڑ لیا (پھینکا) اسکو زمین کے اوپر سے کچھ نہیں اسکو ٹھہراؤ (جماؤ) [۴۶]', 'And the parable of an evil word is that of an evil tree uprooted from the surface of earth having no stability.', 'And the parable of a bad word is like a bad tree, removed from the top of the soil, having no firm root.'),
(1777, 14, 27, 4, 16, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'یُثَبِّتُ اللّٰہُ الَّذِیۡنَ اٰمَنُوۡا بِالۡقَوۡلِ الثَّابِتِ فِی الۡحَیٰوۃِ الدُّنۡیَا وَ فِی الۡاٰخِرَۃِ ۚ وَ یُضِلُّ اللّٰہُ الظّٰلِمِیۡنَ ۟ۙ وَ یَفۡعَلُ  اللّٰہُ  مَا یَشَآءُ ﴿٪۲۷﴾', 'اللہ مومنوں کے دلوں کو صحیح اور پکی بات سے دنیا کی زندگی میں بھی مضبوط رکھتا ہے اور آخرت میں بھی رکھے گا اور اللہ بےانصافوں کو گمراہ کر دیتا ہے۔ اور اللہ جو چاہتا ہے کرتا ہے۔', 'مضبوط کرتا ہے اللہ ایمان والوں کو مضبوط بات سے دنیا کی زندگی میں اور آخرت میں [۴۷] اور بچلا (راہ بھلا دیتا ہے) دیتا ہے اللہ بے انصافوں کو [۴۸] اور کرتا ہے اللہ جو چاہے [۴۹]', 'Allah will keep firm those who believe, with the word that stands firm in this world (i.e. they will keep on worshipping Allah Alone and none else), and in the Hereafter. And Allah will cause to go astray those who are Zalimoon (polytheists and wrong-doers, etc.), and Allah does what He wills.', 'Allah keeps the believers firm with the stable word in the worldly life and in the Hereafter; and Allah lets the unjust go astray; and Allah does what He wills.'),
(1778, 14, 28, 5, 17, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'اَلَمۡ تَرَ اِلَی الَّذِیۡنَ بَدَّلُوۡا نِعۡمَتَ اللّٰہِ کُفۡرًا  وَّ اَحَلُّوۡا  قَوۡمَہُمۡ  دَارَ  الۡبَوَارِ ﴿ۙ۲۸﴾', 'کیا تم نے ان لوگوں کو نہیں دیکھا جنہوں نے اللہ کے احسان کو ناشکری سے بدل دیا۔ اور اپنی قوم کو تباہی کے گھر میں لا اتارا۔', 'تو نے نہ دیکھا انکو جنہوں نے بدلہ کیا اللہ کے احسان کا ناشکری اور اتارا اپنی قوم کو تباہی کے گھر میں [۵۰]', 'Have you not seen those who have changed the Blessings of Allah into disbelief (by denying Prophet Muhammad SAW and his Message of Islam), and caused their people to dwell in the house of destruction?', 'Have you not seen those who adopted disbelief in exchange of Allah’s favor and caused their people to disembark at a land of total destruction,'),
(1779, 14, 29, 5, 17, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'جَہَنَّمَ ۚ یَصۡلَوۡنَہَا ؕ وَ بِئۡسَ الۡقَرَارُ ﴿۲۹﴾', 'یعنی دوزخ میں کہ سب ناشکرے اس میں داخل ہوں گے اور وہ برا ٹھکانہ ہے۔', 'جو دوزخ ہے داخل ہوں گے اس میں اور وہ برا ٹھکانہ ہے', 'Hell, in which they will burn, - and what an evil place to settle in!', '(which is) the Jahannam. They shall enter it; and it is an evil place to dwell.'),
(1780, 14, 30, 5, 17, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ جَعَلُوۡا لِلّٰہِ اَنۡدَادًا لِّیُضِلُّوۡا عَنۡ سَبِیۡلِہٖ ؕ قُلۡ تَمَتَّعُوۡا فَاِنَّ مَصِیۡرَکُمۡ  اِلَی  النَّارِ ﴿۳۰﴾', 'اور ان لوگوں نے اللہ کے شریک مقرر کئے کہ لوگوں کو اسکے رستے سے گمراہ کریں۔ کہدو کہ چند روز فائدے اٹھا لو آخر کار تم کو دوزخ کی طرف لوٹ کر جانا ہے۔', 'اور ٹھہرائے اللہ کے لئے مقابل کہ بہکائیں لوگوں کو اس کی راہ سے [۵۱] تو کہہ مزا اڑا لو پھر تو کو لوٹنا ہے طرف آگ کی [۵۲]', 'And they set up rivals to Allah, to mislead (men) from His Path! Say: \"Enjoy (your brief life)! But certainly, your destination is the (Hell) Fire!\"', 'They have set up partners with Allah, so that they may mislead (the people) from His path. Say, “Enjoy (for a while). Then your ultimate journey is to the Fire.”'),
(1781, 14, 31, 5, 17, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'قُلۡ لِّعِبَادِیَ الَّذِیۡنَ اٰمَنُوۡا یُقِیۡمُوا الصَّلٰوۃَ وَ یُنۡفِقُوۡا مِمَّا رَزَقۡنٰہُمۡ سِرًّا وَّ عَلَانِیَۃً مِّنۡ قَبۡلِ اَنۡ یَّاۡتِیَ یَوۡمٌ  لَّا بَیۡعٌ  فِیۡہِ  وَ لَا  خِلٰلٌ ﴿۳۱﴾', 'اے پیغمبر میرے مومن بندوں سے کہدو کہ نماز پڑھا کریں اور اس دن کے آنے سے پیشتر جس میں نہ اعمال کا سودا ہوگا اور نہ دوستی کام آئے گی ہمارے دیئے ہوئے مال میں سے پوشیدہ اور علانیہ خرچ کرتے رہیں۔', 'کہدے میرے بندوں کو جو ایمان لائے ہیں قائم رکھیں نماز اور خرچ کریں ہماری دی ہوئی روزی میں سے پوشیدہ اور ظاہر (چھپے اور کھلے) [۵۳] پہلے اس سے کہ آئے وہ دن جس میں نہ سودا (خرید و فروخت) ہے نہ دوستی [۵۴]', 'Say (O Muhammad SAW) to Ibadee (My slaves) who have believed, that they should perform As-Salat (Iqamat-as-Salat), and spend in charity out of the sustenance We have given them, secretly and openly, before the coming of a Day on which there will be neither mutual bargaining nor befriending.', 'Say to My believing servants that they should establish Salāh and spend, secretly and openly, out of what We have given to them before there comes a day in which there is neither a trade nor friendship.'),
(1782, 14, 32, 5, 17, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'اَللّٰہُ  الَّذِیۡ  خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ وَ اَنۡزَلَ مِنَ السَّمَآءِ مَآءً  فَاَخۡرَجَ بِہٖ مِنَ الثَّمَرٰتِ رِزۡقًا لَّکُمۡ ۚ وَ سَخَّرَ لَکُمُ  الۡفُلۡکَ  لِتَجۡرِیَ فِی  الۡبَحۡرِ  بِاَمۡرِہٖ ۚ وَ  سَخَّرَ  لَکُمُ  الۡاَنۡہٰرَ ﴿ۚ۳۲﴾', 'اللہ ہی تو ہے جس نے آسمانوں اور زمین کو پیدا کیا۔ اور آسمان سے مینہ برسایا۔ پھر اس سے تمہارے کھانے کے لئے پھل پیدا کئے۔ اور کشتیوں اور جہازوں کو تمہارے زیرفرمان کیا تاکہ وہ سمندر میں اس کے حکم سے چلیں اور نہروں کو بھی تمہارے زیرفرمان کیا۔', 'اللہ وہ ہے جس نے بنائے آسمان اور زمین اور اتارا آسمان سے پانی [۵۵] پھر اس سے نکالی روزی تمہاری میوے [۵۶] اور کہنے میں کیا تمہارے کشتی کو (کام میں دیں تمہارے کشتیاں کہ چلیں) کہ چلے دریا میں اسکے حکم سے [۵۷] اور کام میں لگایا (دیں) تمہارے ندیوں (ندیاں) کو', 'Allah is He Who has created the heavens and the earth and sends down water (rain) from the sky, and thereby brought forth fruits as provision for you; and He has made the ships to be of service to you, that they may sail through the sea by His Command; and He has made rivers (also) to be of service to you.', 'Allah is the One who created the heavens and the earth and sent down water from the sky, then brought forth with it sustenance for you from the produce, and subjugated for you the ships, so that they may sail in the sea with His command, and subjugated for you the rivers;'),
(1783, 14, 33, 5, 17, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ سَخَّرَ لَکُمُ الشَّمۡسَ وَ الۡقَمَرَ دَآئِبَیۡنِ ۚ  وَ سَخَّرَ لَکُمُ الَّیۡلَ وَ النَّہَارَ ﴿ۚ۳۳﴾', 'اور سورج اور چاند کو تمہارے لئے کام میں لگا دیا کہ دونوں دن رات ایک ڈگر پر چل رہے ہیں۔ اور رات اور دن کو بھی تمہاری خاطر کام میں لگا دیا۔', 'اور کام میں لگا دیا تمہارے سورج اور چاند کو ایک دستور پر برابر اور کام میں لگا دیا تمہارے رات اور دن کو [۵۸]', 'And He has made the sun and the moon, both constantly pursuing their courses, to be of service to you; and He has made the night and the day, to be of service to you.', 'and He subjugated for you the sun and the moon, moving constantly, and subjugated for you the day and the night,'),
(1784, 14, 34, 5, 17, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ اٰتٰىکُمۡ مِّنۡ کُلِّ مَا سَاَلۡتُمُوۡہُ ؕ وَ اِنۡ تَعُدُّوۡا نِعۡمَتَ اللّٰہِ لَا تُحۡصُوۡہَا ؕ اِنَّ الۡاِنۡسَانَ  لَظَلُوۡمٌ  کَفَّارٌ ﴿٪۳۴﴾', 'اور جو کچھ تم نے مانگا سب میں سے تم کو عنایت کیا اور اگر اللہ کے احسان گننے لگو تو شمار نہ کر سکو مگر لوگ نعمتوں کا شکر نہیں کرتے کچھ شک نہیں کہ انسان بڑا بےانصاف ہے ناشکرا ہے۔', 'اور دیا تم کو ہر چیز میں سےجو تم نے مانگی [۵۹] اور اگر گنو احسان اللہ کے نہ پورے کر سکو [۶۰] بیشک آدمی بڑا بے انصاف ہے ناشکر [۶۱]', 'And He gave you of all that you asked for, and if you count the Blessings of Allah, never will you be able to count them. Verily! Man is indeed an extreme wrong-doer, - a disbeliever (an extreme ingrate, denies Allahs Blessings by disbelief, and by worshipping others besides Allah, and by disobeying Allah and His Prophet Muhammad SAW).', 'and He gave you whatever you asked for. If you (try to) count the bounties of Allah, you cannot count them all. Indeed, man is highly unjust, very ungrateful.'),
(1785, 14, 35, 6, 18, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ اِذۡ  قَالَ اِبۡرٰہِیۡمُ رَبِّ اجۡعَلۡ ہٰذَا الۡبَلَدَ  اٰمِنًا وَّ اجۡنُبۡنِیۡ وَ بَنِیَّ  اَنۡ نَّعۡبُدَ  الۡاَصۡنَامَ ﴿ؕ۳۵﴾', 'اور جب ابراہیم نے دعا کی کہ اے میرے پروردگار اس شہر کو لوگوں کے لئے امن کی جگہ بنا دے اور مجھے اور میری اولاد کو اس بات سے کہ بتوں کی پرستش کرنے لگیں بچائے رکھیو۔', 'اور جس وقت کہا ابراہیم نے [۶۲] اے رب کر دے اس شہر کو امن والا اور دور کر مجھ کو اور میری اولاد کو اس بات سے کہ ہم پوجیں مورتوں کو [۶۳]', 'And (remember) when Ibrahim (Abraham) said: \"O my Lord! Make this city (Makkah) one of peace and security, and keep me and my sons away from worshipping idols.', '(Recall) when Ibrāhīm said, “My Lord, make this city peaceful, and keep me and my children away from worshiping idols.'),
(1786, 14, 36, 6, 18, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'رَبِّ اِنَّہُنَّ اَضۡلَلۡنَ  کَثِیۡرًا مِّنَ النَّاسِ ۚ فَمَنۡ تَبِعَنِیۡ فَاِنَّہٗ  مِنِّیۡ ۚ وَ مَنۡ عَصَانِیۡ فَاِنَّکَ غَفُوۡرٌ  رَّحِیۡمٌ  ﴿۳۶﴾', 'اے پروردگار انہوں نے بہت سے لوگوں کو گمراہ کیا ہے۔ سو جس شخص نے میرا کہا مانا وہ میرا ہے اور جس نے میری نافرمانی کی تو تو بخشنے والا ہے مہربان ہے۔', 'اے رب انہوں نے گمراہ کیا (گمراہی میں ڈالا) بہت لوگوں کو [۶۴] سو جس نے پیروی کی میری (جو کوئی میرے رستہ پر چلا) وہ تو میرا ہے اور جس نے میرا کہنا نہ مانا سو تو بخشنے والا مہربان ہے [۶۵]', '\"O my Lord! They have indeed led astray many among mankind. But whoso follows me, he verily is of me. And whoso disobeys me, - still You are indeed Oft-Forgiving, Most Merciful.', 'My Lord, they have misled many a people. So, the one who follows me does surely belong to me. As for the one who disobeys me, then You are Most-Forgiving, Very-Merciful.'),
(1787, 14, 37, 6, 18, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'رَبَّنَاۤ  اِنِّیۡۤ  اَسۡکَنۡتُ مِنۡ ذُرِّیَّتِیۡ بِوَادٍ غَیۡرِ  ذِیۡ  زَرۡعٍ عِنۡدَ  بَیۡتِکَ  الۡمُحَرَّمِ ۙ رَبَّنَا لِیُـقِیۡمُوا الصَّلٰوۃَ فَاجۡعَلۡ اَفۡئِدَۃً مِّنَ النَّاسِ تَہۡوِیۡۤ اِلَیۡہِمۡ وَارۡ زُقۡہُمۡ مِّنَ الثَّمَرٰتِ لَعَلَّہُمۡ یَشۡکُرُوۡنَ ﴿۳۷﴾', 'اے پروردگار میں نے اپنی اولاد ایک وادی میں جہاں کھیتی نہیں تیرے عزت و ادب والے گھر کے پاس لا بسائی ہے۔ اے پروردگار تاکہ یہ نماز پڑھیں سو تو لوگوں کے دلوں کو ایسا کر دے کہ انکی طرف جھکے رہیں اور انکو میووں سے روزی دیتے رہنا تاکہ تیرا شکر کریں۔', 'اے رب میں نے بسایا ہے اپنی ایک اولاد کو میدان میں کہ جہاں کھیتی نہیں تیرے محترم (حرمت والے) گھر کے پاس اے رب ہمارے تاکہ قائم رکھیں نماز کو سو رکھ بعض لوگوں کے دل کہ مائل (جھکتے رہیں ) ہوں ان کی طرف اور روزی دے انکو میووں سے شاید وہ شکر کریں [۶۶]', '\"O our Lord! I have made some of my offspring to dwell in an uncultivable valley by Your Sacred House (the Kabah at Makkah); in order, O our Lord, that they may perform As-Salat (Iqamat-as-Salat), so fill some hearts among men with love towards them, and (O Allah) provide them with fruits so that they may give thanks.', 'Our Lord, I have settled some of my children in a valley of no vegetation, close to Your sanctified House, so that, Our Lord, they may establish Salāh. So, make hearts of people yearn towards them, and provide them with fruits, so that they may be grateful.'),
(1788, 14, 38, 6, 18, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'رَبَّنَاۤ  اِنَّکَ تَعۡلَمُ مَا نُخۡفِیۡ وَ مَا نُعۡلِنُ ؕ وَ مَا یَخۡفٰی عَلَی اللّٰہِ مِنۡ شَیۡءٍ  فِی الۡاَرۡضِ وَ لَا  فِی  السَّمَآءِ ﴿۳۸﴾', 'اے پروردگار جو بات ہم چھپاتے اور جو ظاہر کرتے ہیں۔ تو سب جانتا ہے اور اللہ سے کوئی چیز مخفی نہیں نہ زمین میں نہ آسمان میں۔', 'اے رب ہمارے تو تو جانتا ہے جو کچھ ہم کرتے ہیں چھپا کر اور جو کچھ کرتے ہیں دکھا کر (کھول کر) اور مخفی نہیں اللہ پر کوئی چیز زمین میں نہ آسمان میں [۶۷]', '\"O our Lord! Certainly, You know what we conceal and what we reveal. Nothing on the earth or in the heaven is hidden from Allah.', 'Our Lord, surely You know what we conceal and what we reveal.-Hidden from Allah is nothing whatsoever, neither in the earth nor in the heavens.'),
(1789, 14, 39, 6, 18, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'اَلۡحَمۡدُ لِلّٰہِ الَّذِیۡ وَہَبَ لِیۡ عَلَی الۡکِبَرِ  اِسۡمٰعِیۡلَ وَ اِسۡحٰقَ ؕ اِنَّ  رَبِّیۡ لَسَمِیۡعُ  الدُّعَآءِ ﴿۳۹﴾', 'اللہ کا شکر ہے جس نے مجھ کو بڑی عمر میں اسمٰعیل اور اسحٰق بخشے۔ بیشک میرا پروردگار دعا سننے والا ہے۔', 'شکر ہے اللہ کا جس نے بخشا مجھ کو اتنی بڑی عمر میں اسمٰعیل اور اسحٰق بیشک میرا رب سنتا ہے دعا کو [۶۸]', '\"All the praises and thanks be to Allah, Who has given me in old age Ismail (Ishmael) and Ishaque (Isaac). Verily! My Lord is indeed the All-Hearer of invocations.', 'Praise be to Allah who, despite my old age, blessed me with Ismā‘īl (Ishmael) and IsHāq (Isaac). Surely, my Lord is the One who listens to the prayer.'),
(1790, 14, 40, 6, 18, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'رَبِّ اجۡعَلۡنِیۡ مُقِیۡمَ الصَّلٰوۃِ  وَ مِنۡ ذُرِّیَّتِیۡ ٭ۖ رَبَّنَا وَ تَقَبَّلۡ دُعَآءِ ﴿۴۰﴾', 'اے پروردگار مجھ کو ایسی توفیق عنایت کر کہ نماز پڑھتا رہوں اور میری اولاد کو بھی یہ توفیق بخش اے پروردگار میری دعا قبول فرما۔', 'اے رب میرے کر مجھ کو کہ قائم رکھوں نماز اور میری اولاد میں سے بھی اے رب میرے [۶۹] اور قبول کر میری دعا [۷۰]', '\"O my Lord! Make me one who performs As-Salat (Iqamat-as-Salat), and (also) from my offspring, our Lord! And accept my invocation.', 'My Lord, make me steadfast in Salāh, and my offspring as well. And, Our Lord, grant my prayer.'),
(1791, 14, 41, 6, 18, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'رَبَّنَا اغۡفِرۡ لِیۡ  وَ لِوَالِدَیَّ وَ لِلۡمُؤۡمِنِیۡنَ  یَوۡمَ  یَقُوۡمُ الۡحِسَابُ ﴿٪۴۱﴾', 'اے پروردگار حساب کتاب کے دن میری اور میرے ماں باپ کی اور مومنوں کی مغفرت کیجیو۔', 'اے ہمارے رب بخش مجھ کو اور میرے ماں باپ کو اور سب ایمان والوں کو جس دن قائم ہو حساب [۷۱]', '\"Our Lord! Forgive me and my parents, and (all) the believers on the Day when the reckoning will be established.\"', 'Our Lord, forgive me and my parents and all believers on the day when reckoning shall take place.”'),
(1792, 14, 42, 7, 19, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ لَا تَحۡسَبَنَّ اللّٰہَ غَافِلًا عَمَّا یَعۡمَلُ الظّٰلِمُوۡنَ ۬ؕ اِنَّمَا یُؤَخِّرُہُمۡ لِیَوۡمٍ تَشۡخَصُ  فِیۡہِ  الۡاَبۡصَارُ ﴿ۙ۴۲﴾', 'اور مومنو یہ نہ سمجھنا کہ یہ ظالم جو کام کر رہے ہیں اللہ ان سے بیخبر ہے۔ وہ انکو اس دن تک مہلت دے رہا ہے جبکہ دہشت کے سبب آنکھیں  پھٹی کی پھٹی رہ جائیں گی۔', 'اور ہرگز مت خیال کر کہ اللہ بیخبر ہے ان کاموں سے جو کرتے ہیں بے انصاف [۷۲] ان کو تو ڈھیل دے رکھی ہے (چھوڑ رکھا ہے) اس دن کے لئے کہ پتھرا جائیں گی (کھلی رہ جائیں گی) آنکھیں [۷۳]', 'Consider not that Allah is unaware of that which the Zalimoon (polytheists, wrong-doers, etc.) do, but He gives them respite up to a Day when the eyes will stare in horror.', 'Never think that Allah is unaware of what the wrongdoers are doing. He is but giving them respite up to a day when the eyes shall remain upraised (in terror).'),
(1793, 14, 43, 7, 19, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'مُہۡطِعِیۡنَ مُقۡنِعِیۡ رُءُوۡسِہِمۡ لَا یَرۡتَدُّ اِلَیۡہِمۡ  طَرۡفُہُمۡ ۚ وَ اَفۡـِٕدَتُہُمۡ  ہَوَآءٌ ﴿ؕ۴۳﴾', 'اور لوگ سر اٹھائے ہوئے میدان قیامت کی طرف دوڑ رہے ہوں گے ان کی نگاہیں خود اپنی طرف لوٹ نہ سکیں گی۔ اور انکے دل مارے خوف کے ہوا ہو رہے ہوں گے۔', 'دوڑتے ہوں گے اوپر اٹھائے اپنے سر  پھر کر نہیں آئیں گی انکی طرف انکی آنکھیں اور دل انکے اڑ گئے ہوں گے [۷۴]', '(They will be) hastening forward with necks outstretched, their heads raised up (towards the sky), their gaze returning not towards them and their hearts empty (from thinking because of extreme fear).', 'They shall be rushing with their heads raised upward; their eyes shall not return towards them and their hearts shall be hollow.'),
(1794, 14, 44, 7, 19, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ اَنۡذِرِ النَّاسَ یَوۡمَ  یَاۡتِیۡہِمُ  الۡعَذَابُ فَیَقُوۡلُ الَّذِیۡنَ ظَلَمُوۡا رَبَّنَاۤ  اَخِّرۡنَاۤ  اِلٰۤی  اَجَلٍ قَرِیۡبٍ ۙ نُّجِبۡ دَعۡوَتَکَ وَ نَتَّبِعِ الرُّسُلَ ؕ اَوَ لَمۡ  تَکُوۡنُوۡۤا اَقۡسَمۡتُمۡ مِّنۡ  قَبۡلُ  مَا  لَکُمۡ  مِّنۡ  زَوَالٍ ﴿ۙ۴۴﴾', 'اور لوگوں کو اس دن سے آگاہ کر دو جب ان پر عذاب آ جائے گا تب ظالم لوگ کہیں گے کہ اے ہمارے پروردگار ہمیں تھوڑی سی مہلت عطا کر تاکہ ہم تیری دعوت توحید قبول کریں۔ اور تیرے پیغمبروں کے پیچھے چلیں تو جواب ملے گا کیا تم پہلے قسمیں نہیں کھایا کرتے تھے کہ تم کو اس حال سے جسمیں تم ہو زوال نہیں ہوگا۔', 'اور ڈرا دے لوگوں کو اس دن سے کہ آئے گا ان پر عذاب [۷۵] تب کہیں گے ظالم اے رب ہمارے مہلت دے ہم کو تھوڑی مدت تک کہ ہم قبول کر لیں تیرے بلانے کو اور پیروی کر لیں رسولوں کی [۷۶] کیا تم پہلے قسم نہ کھاتے تھے کہ تم کو نہیں دنیا سے ٹلنا (کچھ زوال) [۷۷]', 'And warn (O Muhammad SAW) mankind of the Day when the torment will come unto them; then the wrong-doers will say: \"Our Lord! Respite us for a little while, we will answer Your Call and follow the Messengers!\" (It will be said): \"Had you not sworn aforetime that you would not leave (the world for the Hereafter).', 'Warn the people of a day when punishment will come upon them, and the wrongdoers will say, “Our Lord, give us respite for a short term, and we will respond to Your call and will follow the messengers.” (Allah will say), “Is it not that you had sworn oaths earlier that you would not have to leave (the world)?'),
(1795, 14, 45, 7, 19, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَّ سَکَنۡتُمۡ فِیۡ مَسٰکِنِ الَّذِیۡنَ ظَلَمُوۡۤا اَنۡفُسَہُمۡ وَ تَبَیَّنَ لَکُمۡ  کَیۡفَ فَعَلۡنَا بِہِمۡ  وَ ضَرَبۡنَا  لَکُمُ  الۡاَمۡثَالَ ﴿۴۵﴾', 'اور جو لوگ اپنے آپ پر ظلم کرتے تھے تم انکے مکانوں میں رہتے تھے اور تم پر ظاہر ہو چکا تھا کہ ہم نے ان لوگوں کے ساتھ کس طرح کا معاملہ کیا تھا۔ اور تمہارے سمجھانے کے لئے مثالیں بیان کر دی تھیں۔', 'اور آباد تھے تم بستیوں میں انہی لوگوں کی جنہوں نے ظلم کیا اپنی جان پر اور کھل چکا تھا تم کو کہ کیسا کیا ہم نے ان سے اور بتلائے ہم نے تم کو سب قصے [۷۸]', '\"And you dwelt in the dwellings of men who wronged themselves, and it was clear to you how We had dealt with them. And We put forth (many) parables for you.\"', 'And you dwelt in the dwellings of those who wronged themselves, and it became clear to you how We dealt with them, and We put forth for you the examples.”'),
(1796, 14, 46, 7, 19, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ قَدۡ مَکَرُوۡا مَکۡرَہُمۡ وَ عِنۡدَ اللّٰہِ مَکۡرُہُمۡ ؕ وَ اِنۡ کَانَ مَکۡرُہُمۡ لِتَزُوۡلَ مِنۡہُ  الۡجِبَالُ ﴿۴۶﴾', 'اور انہوں نے بڑی بڑی تدبیریں کیں۔ اور انکی سب تدبیریں اللہ کے ہاں لکھی ہوئی ہیں۔ گو وہ تدبیریں ایسی غضب کی تھیں کہ ان سے پہاڑ بھی ٹل جائیں۔', 'اور یہ بنا چکے ہیں اپنا داؤ اور اللہ کے آگے ہے ان کا داؤ [۷۹] اور نہ ہو گا ان کا داؤ کہ ٹل جائیں اس سے پہاڑ [۸۰]', 'Indeed, they planned their plot, and their plot was with Allah, though their plot was a great (one, still) it would never be able to remove the mountains (real mountains or the Islamic law) from their places (as it is of no importance) (Tafsir Ibn Kathir, Vol. 2, Page 597). (It is said by some interpreters regarding this Verse that the Quraish pagans plotted against Prophet Muhammad SAW to kill him but they failed and were unable to carry out their plot which they plotted).', 'And they worked out their plot and whatever they plot is before Allah, even though their plot is such as would move the mountains.'),
(1797, 14, 47, 7, 19, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'فَلَا تَحۡسَبَنَّ اللّٰہَ مُخۡلِفَ وَعۡدِہٖ  رُسُلَہٗ ؕ اِنَّ  اللّٰہَ  عَزِیۡزٌ  ذُو انۡتِقَامٍ ﴿ؕ۴۷﴾', 'تو ایسا خیال نہ کرنا کہ اللہ نے جو اپنے پیغمبروں سے وعدہ کیا ہے وہ اسکے خلاف کرے گا۔ بیشک اللہ زبردست ہے بدلہ لینے والا ہے۔', 'سو خیال مت کر کہ اللہ خلاف کرے گا اپنا وعدہ اپنے رسولوں سے [۸۱] بیشک اللہ زبردست ہے بدلہ لینے  والا [۸۲]', 'So think not that Allah will fail to keep His Promise to His Messengers. Certainly, Allah is All-Mighty, - All-Able of Retribution.', 'So, never think that Allah will do against His promise to His messengers. Surely, Allah is Mighty, the Lord of Retribution'),
(1798, 14, 48, 7, 19, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'یَوۡمَ تُبَدَّلُ الۡاَرۡضُ غَیۡرَ الۡاَرۡضِ وَ السَّمٰوٰتُ وَ  بَرَزُوۡا  لِلّٰہِ  الۡوَاحِدِ الۡقَہَّارِ ﴿۴۸﴾', 'جس دن یہ زمین دوسری ہی زمین بنا دی جائےگی اور آسمان بھی بدل دیئے جائیں گے اور سب لوگ اللہ کے سامنے نکل کھڑے ہوں گے جو یکتا ہے بڑا زبردست ہے۔', 'جس دن بدلی جائے اس زمین سے اور زمین اور بدلے جائیں آسمان اور لوگ نکل کھڑے ہوں سامنے اللہ اکیلے زبردست کے [۸۳]', 'On the Day when the earth will be changed to another earth and so will be the heavens, and they (all creatures) will appear before Allah, the One, the Irresistible.', 'the day on which this earth will be turned into some other earth, and the skies as well, and they all shall appear before Allah, the One, the All-Dominant.'),
(1799, 14, 49, 7, 19, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'وَ تَـرَی الۡمُجۡرِمِیۡنَ یَوۡمَئِذٍ مُّقَرَّنِیۡنَ فِی  الۡاَصۡفَادِ ﴿ۚ۴۹﴾', 'اور اس دن تم گنہگاروں کو دیکھو گے کہ زنجیروں میں جکڑے ہوئے ہیں۔', 'اور دیکھے تو گنہگاروں کو اس دن باہم جکڑے ہوئے زنجیروں میں [۸۴]', 'And you will see the Mujrimoon (criminals, disbelievers in the Oneness of Allah Islamic Monotheism, polytheists, disobedient to Allah, etc.) that Day bound together in fetters; (Muqarranoon in fetters; mean:- with their hands and feet tied to their necks with chains.)', 'On that day you will see the culprits tied up together in chains,'),
(1800, 14, 50, 7, 19, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'سَرَابِیۡلُہُمۡ مِّنۡ قَطِرَانٍ وَّ تَغۡشٰی وُجُوۡہَہُمُ  النَّارُ ﴿ۙ۵۰﴾', 'انکے کرتے تارکول کے ہوں گے اور انکے چہروں کو آگ لپٹ رہی ہوگی۔', 'کرتے ان کے ہیں گندھک کے [۸۵] اور ڈھانکے لیتی ہے انکے منہ کو آگ [۸۶]', 'Their garments will be of pitch, and fire will cover their faces.', 'their shirts will be of rosin, and their faces will be covered with Fire'),
(1801, 14, 51, 7, 19, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'لِیَجۡزِیَ اللّٰہُ  کُلَّ  نَفۡسٍ مَّا کَسَبَتۡ ؕ اِنَّ  اللّٰہَ  سَرِیۡعُ  الۡحِسَابِ ﴿۵۱﴾', 'یہ اس لئے کہ اللہ ہر شخص کو اسکے اعمال کا بدلہ دے۔ بیشک اللہ جلد حساب لینے والا ہے۔', 'تاکہ بدلہ دے اللہ ہر ایک جی کو اس کی کمائی کا بیشک اللہ جلد کرنے والا ہے حساب [۸۷]', 'That Allah may requite each person according to what he has earned. Truly, Allah is Swift at reckoning.', 'so that Allah repays everyone in full whatever he earned. Indeed, Allah is swift at reckoning.'),
(1802, 14, 52, 7, 19, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'ابراھیم', 'ہٰذَا بَلٰغٌ  لِّلنَّاسِ وَ لِیُنۡذَرُوۡا بِہٖ وَ لِیَعۡلَمُوۡۤا اَنَّمَا ہُوَ  اِلٰہٌ  وَّاحِدٌ  وَّ لِیَذَّکَّرَ اُولُوا  الۡاَلۡبَابِ ﴿٪۵۲﴾', 'یہ قرآن لوگوں کے نام اللہ کا پیغام ہے تاکہ ان کو اس سے ڈرایا جائے اور تاکہ وہ جان لیں کہ وہی اکیلا معبود ہے اور تاکہ اہل عقل نصیحت حاصل کریں۔', 'یہ خبر پہنچا دینی ہے لوگوں کو اور تاکہ چونک جائیں اس سے اور تاکہ جان لیں کہ معبود وہی ہے  ایک ہے اور تاکہ سوچ لیں عقل والے [۸۸]', 'This (Quran) is a Message for mankind (and a clear proof against them), in order that they may be warned thereby, and that they may know that He is the only One Ilah (God - Allah) - (none has the right to be worshipped but Allah), and that men of understanding may take heed.', 'This is a message for mankind, so that they (take lesson and) be warned, and so that they may know that He is One God, and so that the people of understanding may observe the advice.'),
(1803, 15, 1, 1, 0, 13, 'وَ مَاۤ  اُبَرِّیُٔ', 'الحجر', 'الٓرٰ ۟  تِلۡکَ اٰیٰتُ الۡکِتٰبِ وَ قُرۡاٰنٍ مُّبِیۡنٍ ﴿۱﴾', 'الٓرا۔ یہ اللہ کی کتاب اور قرآن روشن کی آیتیں ہیں۔', 'یہ آیتیں ہیں کتاب کی [۱] اور واضح قراآن کی [۲]', 'Alif-Lam-Ra. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings).These are the Verses of the Book, and a plain Quran.', 'Alif, Lām, Rā. These are verses of the Book and the enlightening Qur’ān.'),
(1804, 15, 2, 1, 1, 14, 'رُبَمَا', 'الحجر', 'رُبَمَا یَوَدُّ الَّذِیۡنَ کَفَرُوۡا لَوۡ کَانُوۡا مُسۡلِمِیۡنَ  ﴿۲﴾', 'کسی وقت کافر لوگ آرزو کریں گے کہ اے کاش وہ مسلمان ہوتے۔', 'کسی وقت آرزو کریں گے یہ لوگ جو منکر ہیں کیا اچھا ہوتا جو ہوتے مسلمان [۳]', 'Perhaps (often) will those who disbelieve wish that they were Muslims (those who have submitted themselves to Allahs Will in Islam Islamic Monotheism, this will be on the Day of Resurrection when they will see the disbelievers going to Hell and the Muslims going to Paradise).', 'On many occasions, the disbelievers will wish that they were Muslims.'),
(1805, 15, 3, 1, 1, 14, 'رُبَمَا', 'الحجر', 'ذَرۡہُمۡ یَاۡکُلُوۡا وَ یَتَمَتَّعُوۡا وَ یُلۡہِہِمُ الۡاَمَلُ  فَسَوۡفَ  یَعۡلَمُوۡنَ ﴿۳﴾', 'اے نبی ان کو انکے حال پر رہنے دو کہ کھا پی لیں اور فائدے اٹھا لیں اور لمبی لمبی آرزوئیں انکو دنیا میں مشغول کئے رکھیں آخرکار انکو اس کا انجام معلوم ہو جائے گا۔', 'چھوڑ دے انکو کھالیں اور برت لیں (فائدہ اٹھا لیں) اور امید میں (پر بھولے) لگے رہیں سو آئندہ معلوم کر لیں گے [۴]', 'Leave them to eat and enjoy, and let them be preoccupied with (false) hope. They will come to know!', 'Let them eat and enjoy, and let (their) fancy make them neglectful, for they shall soon come to know (their ultimate end).'),
(1806, 15, 4, 1, 1, 14, 'رُبَمَا', 'الحجر', 'وَ مَاۤ  اَہۡلَکۡنَا مِنۡ قَرۡیَۃٍ  اِلَّا وَ لَہَا کِتَابٌ  مَّعۡلُوۡمٌ ﴿۴﴾', 'اور ہم نے کوئی بستی ہلاک نہیں کی۔ مگر اس کا وقت مقرر لکھا ہوا تھا۔', 'اور کوئی بستی ہم نے غارت نہیں کی مگر اس کا وقت لکھا ہوا تھا مقرر [۵]', 'And never did We destroy a township but there was a known decree for it.', 'We did not destroy any town without having a pre-determined time for it.'),
(1807, 15, 5, 1, 1, 14, 'رُبَمَا', 'الحجر', 'مَا تَسۡبِقُ مِنۡ اُمَّۃٍ  اَجَلَہَا وَ مَا یَسۡتَاۡخِرُوۡنَ ﴿۵﴾', 'کوئی امت اپنی مدت مقررہ سے نہ آگے نکل سکتی ہے اور نہ پیچھے رہ سکتی ہے۔', 'نہ سبقت کرتا ہے کوئی فرقہ اپنے وقت مقرر سے اور نہ پیچھے رہتا ہے [۶]', 'No nation can anticipate its term, nor delay it.', 'No people can precede their appointed time, nor can they exceed it.'),
(1808, 15, 6, 1, 1, 14, 'رُبَمَا', 'الحجر', 'وَ قَالُوۡا یٰۤاَیُّہَا الَّذِیۡ نُزِّلَ عَلَیۡہِ الذِّکۡرُ اِنَّکَ  لَمَجۡنُوۡنٌ ؕ﴿۶﴾', 'اور کفار کہتے ہیں کہ اے شخص جس پر نصیحت کی کتاب نازل ہوئی ہے تو تو دیوانہ ہے۔', 'اور لوگ کہتے ہیں اے وہ شخص کہ تجھ پر اترا ہے قرآن (نصیحت) تو بیشک دیوانہ ہے [۷]', 'And they say: \"O you (Muhammad SAW ) to whom the Dhikr (the Quran) has been sent down! Verily, you are a mad man.', 'They say, “O you to whom the Dhikr (the Qur’ān) has been revealed, you are surely insane.'),
(1809, 15, 7, 1, 1, 14, 'رُبَمَا', 'الحجر', 'لَوۡ مَا تَاۡتِیۡنَا بِالۡمَلٰٓئِکَۃِ  اِنۡ کُنۡتَ مِنَ  الصّٰدِقِیۡنَ ﴿۷﴾', 'اگر تو سچا ہے تو ہمارے پاس فرشتوں کو کیوں نہیں لے آتا۔', 'کیوں نہیں لے آتا ہمارے پاس فرشتوں کو اگر تو سچا ہے [۸]', '\"Why do you not bring angels to us if you are of the truthful ones?\"', 'Why do you not bring the angels to us, if you are one of the truthful?”'),
(1810, 15, 8, 1, 1, 14, 'رُبَمَا', 'الحجر', 'مَا نُنَزِّلُ الۡمَلٰٓئِکَۃَ  اِلَّا بِالۡحَقِّ وَ مَا کَانُوۡۤا  اِذًا  مُّنۡظَرِیۡنَ ﴿۸﴾', 'کہدو ہم فرشتوں کو نازل نہیں کیا کرتے مگر حق کے ساتھ۔ اور اس وقت انکو مہلت نہیں ملے گی۔', 'ہم نہیں اتارتے فرشتوں کو مگر کام پورا (ٹھیک) کر کے اور اس وقت نہ ملے گی ان کو مہلت (ڈھیل) [۹]', 'We send not the angels down except with the truth (i.e. for torment, etc.), and in that case, they (the disbelievers) would have no respite!', 'We do not send down the angels except with truth, and then they shall be given no respite.'),
(1811, 15, 9, 1, 1, 14, 'رُبَمَا', 'الحجر', 'اِنَّا نَحۡنُ نَزَّلۡنَا الذِّکۡرَ  وَ  اِنَّا  لَہٗ  لَحٰفِظُوۡنَ ﴿۹﴾', 'بیشک یہ کتاب نصیحت ہمیں نے اتاری ہے اور یقینًا ہم اسکے نگہبان ہیں۔', 'ہم نے آپ اتاری ہے یہ نصیحت اور ہم آپ اس کے نگہبان ہیں [۱۰]', 'Verily We: It is We Who have sent down the Dhikr (i.e. the Quran) and surely, We will guard it (from corruption).', 'We, Ourselves, have sent down the Dhikr (the Qur’ān), and We are there to protect it.'),
(1812, 15, 10, 1, 1, 14, 'رُبَمَا', 'الحجر', 'وَ لَقَدۡ  اَرۡسَلۡنَا مِنۡ قَبۡلِکَ فِیۡ شِیَعِ الۡاَوَّلِیۡنَ ﴿۱۰﴾', 'اور ہم نے تم سے پہلے کے مختلف گروہوں میں بھی پیغمبر بھیجے تھے۔', 'اور ہم بھیج چکے ہیں رسول تجھ سے پہلے اگلے فرقوں میں', 'Indeed, We sent Messengers before you (O Muhammad SAW) amongst the sects (communities) of old.', 'We did send the messengers before you among the groups of earlier peoples.'),
(1813, 15, 11, 1, 1, 14, 'رُبَمَا', 'الحجر', 'وَ مَا یَاۡتِیۡہِمۡ مِّنۡ رَّسُوۡلٍ  اِلَّا کَانُوۡا بِہٖ یَسۡتَہۡزِءُوۡنَ ﴿۱۱﴾', 'اور انکے پاس کوئی پیغمبر نہیں آتا تھا مگر وہ اسکے ساتھ ہنسی کرتے تھے۔', 'اور نہیں آتا ان کے پاس کوئی رسول مگر کرتے رہے ہیں اس سے ہنسی [۱۱]', 'And never came a Messenger to them but they did mock him.', 'No messenger came to them but they used to mock at him.'),
(1814, 15, 12, 1, 1, 14, 'رُبَمَا', 'الحجر', 'کَذٰلِکَ نَسۡلُکُہٗ فِیۡ  قُلُوۡبِ الۡمُجۡرِمِیۡنَ ﴿ۙ۱۲﴾', 'اسی طرح ہم اس گستاخی کو گنہگاروں کے دلوں میں ڈالے رکھتے ہیں۔', 'اسی طرح بٹھا دیتے ہیں ہم اسکو دل میں گنہگاروں کے [۱۲]', 'Thus do We let it (polytheism and disbelief) enter into the hearts of the Mujrimoon (criminals, polytheists, pagans, etc. (because of their mockery at the Messengers)).', 'Likewise, We make it (i.e. disbelief) enter into the hearts of the sinners,'),
(1815, 15, 13, 1, 1, 14, 'رُبَمَا', 'الحجر', 'لَا یُؤۡمِنُوۡنَ بِہٖ وَ قَدۡ خَلَتۡ سُنَّۃُ الۡاَوَّلِیۡنَ ﴿۱۳﴾', 'سو وہ اس پر ایمان نہیں لاتے اور پہلے لوگوں کی روش بھی یہی رہی ہے۔', 'یقین نہ لائیں گے اس پر اور ہوتی آئی ہے رسم پہلوں کی [۱۳]', 'They would not believe in it (the Quran), and already the example of (Allahs punishment of) the ancients (who disbelieved) has gone forth.', '(whereby) they do not believe in it (the Qur’ān), and this has been the way of earlier people.'),
(1816, 15, 14, 1, 1, 14, 'رُبَمَا', 'الحجر', 'وَ لَوۡ فَتَحۡنَا عَلَیۡہِمۡ بَابًا مِّنَ السَّمَآءِ فَظَلُّوۡا فِیۡہِ  یَعۡرُجُوۡنَ ﴿ۙ۱۴﴾', 'اور اگر ہم آسمان کا کوئی دروازہ ان پر کھول دیں اور وہ اس میں چڑھنے بھی لگیں۔', 'اور اگر ہم کھول دیں ان پر دروازہ آسمان سے اور سارے دن اس میں چڑھتے رہیں', 'And even if We opened to them a gate from the heaven and they were to continue ascending thereto,', 'Even if We open a gate in the sky and they keep ascending through it,'),
(1817, 15, 15, 1, 1, 14, 'رُبَمَا', 'الحجر', 'لَقَالُوۡۤا اِنَّمَا سُکِّرَتۡ اَبۡصَارُنَا بَلۡ نَحۡنُ قَوۡمٌ  مَّسۡحُوۡرُوۡنَ ﴿٪۱۵﴾', 'تو بھی وہ یہی کہیں کہ ہماری آنکھیں باندھ دی گئ ہیں بلکہ ہم پر جادو کر دیا گیا ہے۔', 'توبھی یہی کہیں گے کہ باندھ دیا ہے ہماری نگاہ کو نہیں بلکہ ہم لوگوں پر جادو ہوا ہے [۱۴]', 'They would surely say: \"Our eyes have been (as if) dazzled. Nay, we are a people bewitched.\"', 'still they will say, “In fact our eyes have been deluded; rather we are enchanted people.'),
(1818, 15, 16, 2, 2, 14, 'رُبَمَا', 'الحجر', 'وَ لَقَدۡ جَعَلۡنَا فِی السَّمَآءِ بُرُوۡجًا وَّ زَیَّنّٰہَا  لِلنّٰظِرِیۡنَ ﴿ۙ۱۶﴾', 'اور ہم نے آسمان میں برج بنائے ہیں اور دیکھنے والوں کے لئے اسکو سجا دیا ہے۔', 'اور ہم نے بنائے ہیں آسمان میں برج [۱۵] اور رونق دی اسکو دیکھنے والوں کی نظر میں [۱۶]', 'And indeed, We have put the big stars in the heaven and We beautified it for the beholders.', 'We have created stellar formations in the sky and have beautified them for onlookers,'),
(1819, 15, 17, 2, 2, 14, 'رُبَمَا', 'الحجر', 'وَ  حَفِظۡنٰہَا مِنۡ کُلِّ شَیۡطٰنٍ رَّجِیۡمٍ ﴿ۙ۱۷﴾', 'اور ہر شیطان مردود سے اسے محفوظ کر دیا ہے۔', 'اور محفوظ رکھا ہم نے اسکو ہر شیطان مردود سے', 'And We have guarded it (near heaven) from every outcast Shaitan (devil).', 'and have protected them from every outcast devil,'),
(1820, 15, 18, 2, 2, 14, 'رُبَمَا', 'الحجر', 'اِلَّا مَنِ اسۡتَرَقَ السَّمۡعَ فَاَتۡبَعَہٗ شِہَابٌ مُّبِیۡنٌ ﴿۱۸﴾', 'ہاں اگر کوئی چوری سے سننا چاہے تو ایک روشن انگارہ اسکے پیچھے لپکتا ہے۔', 'مگر جو چوری سے سن بھاگا سو اسکے پیچھے پڑا انگارہ چمکتا ہوا [۱۷]', 'Except him (devil) that gains hearing by stealing, he is pursued by a clear flaming fire.', 'but the one who tries to eavesdrop is chased by a clearly visible flame.'),
(1821, 15, 19, 2, 2, 14, 'رُبَمَا', 'الحجر', 'وَ الۡاَرۡضَ مَدَدۡنٰہَا وَ اَلۡقَیۡنَا فِیۡہَا رَوَاسِیَ وَ اَنۡۢبَتۡنَا فِیۡہَا مِنۡ کُلِّ شَیۡءٍ مَّوۡزُوۡنٍ ﴿۱۹﴾', 'اور زمین کو ہم نے پھیلایا اور اس پر پہاڑ بنا کر رکھ دیئے اور اس میں ہر ایک چیز اندازے سے اگائی۔', 'اور زمین کو ہم نے پھیلایا اور رکھ دیے اس پر بوجھ (پہاڑ) اور اگائی اس میں ہر چیز اندازے سے', 'And the earth We spread out, and placed therein firm mountains, and caused to grow therein all kinds of things in due proportion.', 'As for the earth, We have stretched it out and placed on it firm mountains, and We have caused to grow in it everything well-balanced,'),
(1822, 15, 20, 2, 2, 14, 'رُبَمَا', 'الحجر', 'وَ جَعَلۡنَا لَکُمۡ  فِیۡہَا مَعَایِشَ وَ مَنۡ لَّسۡتُمۡ  لَہٗ  بِرٰزِقِیۡنَ ﴿۲۰﴾', 'اور ہم نے تمہارے لئے اور ان لوگوں کے لئے جنکو تم روزی نہیں دیتے اس میں معاش کے سامان پیدا کئے۔', 'اور بنا دیے تمہارے واسطے اس میں معیشت کے اسباب اور وہ چیزیں جنکو تم روزی نہیں دیتے [۱۸]', 'And We have provided therein means of living, for you and for those whom you provide not (moving (living) creatures, cattle, beasts, and other animals).', 'and created in it sources of sustenance for you and those (creatures) for whom you are not the sustainers.'),
(1823, 15, 21, 2, 2, 14, 'رُبَمَا', 'الحجر', 'وَ  اِنۡ مِّنۡ شَیۡءٍ   اِلَّا عِنۡدَنَا خَزَآئِنُہٗ ۫ وَ  مَا  نُنَزِّلُہٗۤ  اِلَّا بِقَدَرٍ  مَّعۡلُوۡمٍ ﴿۲۱﴾', 'اور ہمارے ہاں ہر چیز کے خزانے ہیں اور ہم اسکو بمقدار مناسب اتارتے رہتے ہیں۔', 'اور ہر  چیز کے ہمارے پاس خزانے ہیں اور اتارتے ہیں ہم اندازہ معین پر (ٹھہرے ہوئے اندازہ پر) [۱۹]', 'And there is not a thing, but with Us are the stores thereof. And We send it not down except in a known measure.', 'We have treasures of every thing, but We send it down only in a determined quantity.'),
(1824, 15, 22, 2, 2, 14, 'رُبَمَا', 'الحجر', 'وَ اَرۡسَلۡنَا الرِّیٰحَ لَوَاقِحَ فَاَنۡزَلۡنَا مِنَ السَّمَآءِ مَآءً فَاَسۡقَیۡنٰکُمُوۡہُ ۚ وَ مَاۤ اَنۡتُمۡ  لَہٗ  بِخٰزِنِیۡنَ ﴿۲۲﴾', 'اور ہم ہوائیں چلاتے ہیں جو پانی سے بھری ہوئی ہوتی ہیں سو ہم آسمان سے مینہ برساتے ہیں پھر ہم تمکو اس کا پانی پلاتے ہیں اور تم تو اس کا خزانہ نہیں رکھتے۔', 'اور چلائیں ہم نے ہوائیں رس بھری (بوجھل کرنے والی ابر کی) پھر اتارا ہم نے آسمان سے پانی پھر تم کو وہ پلایا [۲۰] اور تمہارے پاس نہیں اس کا خزانہ [۲۱]', 'And We send the winds fertilizing (to fill heavily the clouds with water), then caused the water (rain) to descend from the sky, and We gave it to you to drink, and it is not you who are the owners of its stores (i.e. to give water to whom you like or to withhold it from whom you like).', 'And We sent forth winds carrying the clouds, then sent down water from the sky and gave it to you to drink, and you are not able to store it.'),
(1825, 15, 23, 2, 2, 14, 'رُبَمَا', 'الحجر', 'وَ اِنَّا لَنَحۡنُ نُحۡیٖ وَ نُمِیۡتُ وَ نَحۡنُ الۡوٰرِثُوۡنَ ﴿۲۳﴾', 'اور یقینًا ہم ہی حیات بخشتے اور ہم ہی موت دیتے ہیں اور ہم ہی سب کے وارث ہوں گے۔', 'اور ہم ہی ہیں جلانے والے اور مارنے والے اور ہم ہی ہیں پیچھے رہنے والے [۲۲]', 'And certainly We! We it is Who give life, and cause death, and We are the Inheritors.', 'It is indeed We, and only We, who give life and bring death, and We are the ultimate inheritor (of everything).'),
(1826, 15, 24, 2, 2, 14, 'رُبَمَا', 'الحجر', 'وَ لَقَدۡ عَلِمۡنَا الۡمُسۡتَقۡدِمِیۡنَ مِنۡکُمۡ وَ لَقَدۡ  عَلِمۡنَا الۡمُسۡتَاۡخِرِیۡنَ ﴿۲۴﴾', 'اور جو لوگ تم میں پہلے گذر چکے ہیں ہم کو معلوم ہیں اور جو پیچھے آنے والے ہیں وہ بھی ہم کو معلوم ہیں۔', 'اور ہم نے جان رکھا ہے آگے بڑھنے والوں کو تم میں سے اور جان رکھا ہے پیچھے رہنے والوں کو [۲۳]', 'And indeed, We know the first generations of you who had passed away, and indeed, We know the present generations of you (mankind), and also those who will come afterwards.', 'We know those of you who went ahead, and We know those who remained late.'),
(1827, 15, 25, 2, 2, 14, 'رُبَمَا', 'الحجر', 'وَ اِنَّ رَبَّکَ ہُوَ یَحۡشُرُہُمۡ ؕ اِنَّہٗ حَکِیۡمٌ عَلِیۡمٌ ﴿٪۲۵﴾', 'اور تمہارا پروردگار قیامت کے دن ان سب کو جمع کرے گا وہ بڑا دانا ہے خبردار ہے۔', 'اور تیرا رب وہی اکٹھا کر لائے گا انکو بیشک وہی ہے حکمتوں والا خبردار [۲۴]', 'And verily, your Lord will gather them together. Truly, He is All-Wise, All-Knowing.', 'Surely, your Lord will gather all of them together. Indeed He is All-Wise, All-Knowing.'),
(1828, 15, 26, 3, 3, 14, 'رُبَمَا', 'الحجر', 'وَ لَقَدۡ خَلَقۡنَا الۡاِنۡسَانَ مِنۡ صَلۡصَالٍ مِّنۡ حَمَاٍ مَّسۡنُوۡنٍ ﴿ۚ۲۶﴾', 'اور ہم نے انسان کو کھنکھناتے سڑے ہوئے گارے سے پیدا کیا ہے۔', 'اور بنایا ہم نے آدمی کو کھنکھناتے (بجنے والی مٹی سے) سنے (جو بنی ہے سڑے ہوئے گارے سے) ہوئے گارے سے[۲۵]', 'And indeed, We created man from sounding clay of altered black smooth mud.', 'Indeed We created man from a ringing clay made of decayed mud.'),
(1829, 15, 27, 3, 3, 14, 'رُبَمَا', 'الحجر', 'وَ الۡجَآنَّ خَلَقۡنٰہُ مِنۡ قَبۡلُ مِنۡ نَّارِ السَّمُوۡمِ ﴿۲۷﴾', 'اور جنوں کو اس سے بھی پہلے بے دھوئیں کی آگ سے پیدا کیا تھا۔', 'اور جان (جنوں کو) بنایا ہم نے اس سے پہلے لو کی آگ سے [۲۶]', 'And the jinn, We created aforetime from the smokeless flame of fire.', 'As for the Jānn (the first Jinn), We had created him earlier from the fire of the scorching wind.'),
(1830, 15, 28, 3, 3, 14, 'رُبَمَا', 'الحجر', 'وَ اِذۡ قَالَ رَبُّکَ لِلۡمَلٰٓئِکَۃِ  اِنِّیۡ خَالِقٌۢ بَشَرًا مِّنۡ صَلۡصَالٍ مِّنۡ  حَمَاٍ  مَّسۡنُوۡنٍ ﴿۲۸﴾', 'اور وہ وقت قابل ذکر ہے جب تمہارے پروردگار نے فرشتوں سے فرمایا کہ میں کھنکھناتے سڑے ہوئے گارے سے بشر بنانے والا ہوں۔', 'اور جب کہا تیرے رب نے فرشتوں کو میں بناؤں گا ایک بشر کھنکھناتے سنے ہوئے گارے سے', 'And (remember) when your Lord said to the angels: \"I am going to create a man (Adam) from sounding clay of altered black smooth mud.', 'Recall when your Lord said to the angels, “I am going to create a human being from a ringing clay made of decayed mud.'),
(1831, 15, 29, 3, 3, 14, 'رُبَمَا', 'الحجر', 'فَاِذَا سَوَّیۡتُہٗ  وَ نَفَخۡتُ فِیۡہِ  مِنۡ  رُّوۡحِیۡ فَقَعُوۡا  لَہٗ   سٰجِدِیۡنَ ﴿۲۹﴾', 'جب میں اسکو درست کرلوں اور اس میں اپنی طرف سے روح پھونک دوں تو اسکے آگے سجدے میں گر پڑنا۔', 'پھر جب ٹھیک کروں اسکو اور پھونک دوں اس میں اپنی جان سے تو گر پڑیو اسکے آگے سجدہ کرتے ہوئے [۲۷]', '\"So, when I have fashioned him completely and breathed into him (Adam) the soul which I created for him, then fall (you) down prostrating yourselves unto him.\"', 'When I form him perfect, and blow in him of My spirit, then you must fall down before him in prostration.”'),
(1832, 15, 30, 3, 3, 14, 'رُبَمَا', 'الحجر', 'فَسَجَدَ  الۡمَلٰٓئِکَۃُ  کُلُّہُمۡ  اَجۡمَعُوۡنَ ﴿ۙ۳۰﴾', 'چنانچہ فرشتے تو سب کے سب سجدے میں گر پڑے۔', 'تب سجدہ کیا ان فرشتوں نے سب نے مل کر', 'So, the angels prostrated themselves, all of them together.', 'So the angels prostrated themselves, all together,'),
(1833, 15, 31, 3, 3, 14, 'رُبَمَا', 'الحجر', 'اِلَّاۤ  اِبۡلِیۡسَ ؕ اَبٰۤی اَنۡ یَّکُوۡنَ مَعَ السّٰجِدِیۡنَ ﴿۳۱﴾', 'مگر شیطان کہ اس نے سجدہ کرنے والوں کے ساتھ ہونے سے انکار کیا۔', 'مگر ابلیس نے نہ مانا کہ ساتھ ہو سجدہ کرنے والوں کے', 'Except Iblees (Satan), - he refused to be among the prostrators.', 'except Iblīs (Satan). He refused to join those who prostrated.'),
(1834, 15, 32, 3, 3, 14, 'رُبَمَا', 'الحجر', 'قَالَ یٰۤـاِبۡلِیۡسُ مَا لَکَ اَلَّا تَکُوۡنَ مَعَ السّٰجِدِیۡنَ ﴿۳۲﴾', 'فرمایا اے ابلیس! تجھے کیا ہوا کہ تو سجدہ کرنے والوں میں شامل نہ ہوا۔', 'فرمایا اے ابلیس کیا ہوا تجھ کو کہ ساتھ نہ ہوا سجدہ کرنے والوں کے', '(Allah) said: \"O Iblees (Satan)! What is your reason for not being among the prostrators?\"', 'He (Allah) said, “O Iblīs, what is the matter with you that you did not join those who prostrated?”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1835, 15, 33, 3, 3, 14, 'رُبَمَا', 'الحجر', 'قَالَ لَمۡ  اَکُنۡ  لِّاَسۡجُدَ  لِبَشَرٍ  خَلَقۡتَہٗ مِنۡ  صَلۡصَالٍ  مِّنۡ  حَمَاٍ  مَّسۡنُوۡنٍ ﴿۳۳﴾', 'اس نے کہا میں ایسا نہیں ہوں کہ انسان کو جس کو تو نے کھنکھناتے سڑے ہوئے گارے سے بنایا ہے سجدہ کروں۔', 'بولا میں وہ نہیں کہ سجدہ کروں ایک بشر کو جسکو تو نے بنایا کھنکھناتے سنے ہوئے گارے سے', '(Iblees (Satan)) said: \"I am not the one to prostrate myself to a human being, whom You created from sounding clay of altered black smooth mud.\"', 'He said, “I am not such that I should prostrate myself before a mortal whom You have created from a ringing clay made of decayed mud.”'),
(1836, 15, 34, 3, 3, 14, 'رُبَمَا', 'الحجر', 'قَالَ  فَاخۡرُجۡ  مِنۡہَا فَاِنَّکَ  رَجِیۡمٌ ﴿ۙ۳۴﴾', 'فرمایا یہاں سے نکل جا کہ اب تو مردود ہے۔', 'فرمایا تو تو نکل یہاں سے [۲۸] تجھ پر مار ہے [۲۹]', '(Allah) said: \"Then, get out from here, for verily, you are Rajeem (an outcast or a cursed one).\" (Tafseer At-Tabaree)', 'He said, “Then, get out of here, for you are an outcast,'),
(1837, 15, 35, 3, 3, 14, 'رُبَمَا', 'الحجر', 'وَّ اِنَّ عَلَیۡکَ اللَّعۡنَۃَ اِلٰی یَوۡمِ الدِّیۡنِ ﴿۳۵﴾', 'اور تجھ پر قیامت کے دن تک لعنت برسے گی۔', 'اور تجھ پر پھٹکار ہے اس دن تک کہ انصاف ہو [۳۰]', '\"And verily, the curse shall be upon you till the Day of Recompense (i.e. the Day of Resurrection).\"', 'and upon you is the curse up to the Day of Judgment.”'),
(1838, 15, 36, 3, 3, 14, 'رُبَمَا', 'الحجر', 'قَالَ رَبِّ فَاَنۡظِرۡنِیۡۤ  اِلٰی یَوۡمِ یُبۡعَثُوۡنَ ﴿۳۶﴾', 'اس نے کہا کہ پروردگار مجھے اس دن تک مہلت دے جب لوگ مرنے کے بعد زندہ کئے جائیں گے۔', 'بولا اے رب تو مجھ کو ڈھیل دے اس دن تک کہ مردے زندہ ہوں', '(Iblees (Satan)) said: \"O my Lord! Give me then respite till the Day they (the dead) will be resurrected.\"', 'He said, “My Lord, then give me respite up to the day they (the dead) shall be raised.”'),
(1839, 15, 37, 3, 3, 14, 'رُبَمَا', 'الحجر', 'قَالَ فَاِنَّکَ مِنَ الۡمُنۡظَرِیۡنَ ﴿ۙ۳۷﴾', 'فرمایا اچھا سو تجھے مہلت دی جاتی ہے۔', 'فرمایا تو تجھ کو ڈھیل دی', 'Allah said: \"Then, verily, you are of those reprieved,', 'He (Allah) said, “Well, respite is given to you'),
(1840, 15, 38, 3, 3, 14, 'رُبَمَا', 'الحجر', 'اِلٰی یَوۡمِ  الۡوَقۡتِ  الۡمَعۡلُوۡمِ ﴿۳۸﴾', 'وقت مقرر یعنی قیامت کے دن تک۔', 'اسی مقرر وقت کے دن تک [۳۱]', '\"Till the Day of the time appointed.\"', 'till the day of the Appointed Time.”'),
(1841, 15, 39, 3, 3, 14, 'رُبَمَا', 'الحجر', 'قَالَ رَبِّ بِمَاۤ  اَغۡوَیۡتَنِیۡ لَاُزَیِّنَنَّ  لَہُمۡ فِی الۡاَرۡضِ  وَ لَاُغۡوِیَنَّہُمۡ  اَجۡمَعِیۡنَ ﴿ۙ۳۹﴾', 'اس نے کہا کہ پروردگار جیسا تو نے مجھے بھٹکا دیا ہے میں بھی زمین میں لوگوں کے لئے گناہوں کو آراستہ کر کے دکھاؤں گا اور سب کو بہکاؤں گا۔', 'بولا اے رب جیسا تو نے مجھ کو راہ سے کھو دیا میں بھی ان سب کو بہاریں دکھلاؤں گا زمین میں اور  راہ سےکھو دوں گا ان سب کو', '(Iblees (Satan)) said: \"O my Lord! Because you misled me, I shall indeed adorn the path of error for them (mankind) on the earth, and I shall mislead them all.', 'He said, “My Lord, since You made me go astray, I swear that I shall beautify for them (evils) on the earth, and shall lead all of them astray,'),
(1842, 15, 40, 3, 3, 14, 'رُبَمَا', 'الحجر', 'اِلَّا عِبَادَکَ  مِنۡہُمُ  الۡمُخۡلَصِیۡنَ ﴿۴۰﴾', 'ہاں ان میں جو تیرے خاص بندے ہیں ان پر میرا قابو چلنا مشکل ہے۔', 'مگر جو تیرے چنے ہوئے بندے ہیں [۳۲]', '\"Except Your chosen, (guided) slaves among them.\"', 'except those of Your servants from among them who are chosen (by You).”'),
(1843, 15, 41, 3, 3, 14, 'رُبَمَا', 'الحجر', 'قَالَ  ہٰذَا  صِرَاطٌ  عَلَیَّ  مُسۡتَقِیۡمٌ ﴿۴۱﴾', 'فرمایا کہ مجھ تک پہنچنے کا یہی سیدھا رستہ ہے۔', 'فرمایا یہ راہ ہے مجھ تک سیدھی [۳۳]', '(Allah) said: \"This is the Way which will lead straight to Me.\"', 'He (Allah) said, “This is the straight path leading to Me (that a person is chosen by Me through his good deeds).'),
(1844, 15, 42, 3, 3, 14, 'رُبَمَا', 'الحجر', 'اِنَّ عِبَادِیۡ لَیۡسَ لَکَ عَلَیۡہِمۡ سُلۡطٰنٌ  اِلَّا مَنِ اتَّبَعَکَ  مِنَ  الۡغٰوِیۡنَ ﴿۴۲﴾', 'جو میرے خاص بندے ہیں ان پر تجھے کچھ قدرت نہیں کہ انکو گناہ میں ڈال سکے ہاں بدراہوں میں سے جو تیرے پیچھے چل پڑے۔', 'جو میرے بندے ہیں تیرا ان پر کچھ زور نہیں مگر جو تیری راہ چلا بہکے ہوؤں میں [۳۴]', '\"Certainly, you shall have no authority over My slaves, except those who follow you of the Ghaween (Mushrikoon and those who go astray, criminals, polytheists, and evil-doers, etc.).', 'My servants are such that you have no power over them except those of the deviators who will follow you.'),
(1845, 15, 43, 3, 3, 14, 'رُبَمَا', 'الحجر', 'وَ  اِنَّ جَہَنَّمَ  لَمَوۡعِدُہُمۡ  اَجۡمَعِیۡنَ ﴿۟ۙ۴۳﴾', 'اور ان سب کے وعدے کی جگہ جہنم ہے۔', 'اور دوزخ پر وعدہ ہے ان سب کا [۳۵]', '\"And surely, Hell is the promised place for them all.', 'And Jahannam (Hell) is the promised place for them all.'),
(1846, 15, 44, 3, 3, 14, 'رُبَمَا', 'الحجر', 'لَہَا سَبۡعَۃُ  اَبۡوَابٍ ؕ لِکُلِّ بَابٍ مِّنۡہُمۡ جُزۡءٌ  مَّقۡسُوۡمٌ  ﴿٪۴۴﴾', 'اسکے سات دروازے ہیں۔ ہر ایک دروازے کے لئے ان میں سے جماعتیں الگ الگ حصہ ہے۔', 'اسکے سات دروازے ہیں ہر دروازہ کے واسطے ان میں سے ایک فرقہ ہے بانٹا ہوا [۳۶]', '\"It (Hell) has seven gates, for each of those gates is a (special) class (of sinners) assigned.', 'It has seven gates. For each gate there is a group apportioned from them.”'),
(1847, 15, 45, 4, 4, 14, 'رُبَمَا', 'الحجر', 'اِنَّ  الۡمُتَّقِیۡنَ  فِیۡ  جَنّٰتٍ  وَّ عُیُوۡنٍ ﴿ؕ۴۵﴾', 'جو متقی ہیں وہ باغوں اور چشموں میں ہوں گے۔', 'پرہیزگار ہیں باغوں میں اور چشموں میں [۳۷]', '\"Truly! The Muttaqoon (pious and righteous persons - see V.2:2) will be amidst Gardens and water-springs (Paradise).', 'Surely, the God-fearing will be in gardens and streams:'),
(1848, 15, 46, 4, 4, 14, 'رُبَمَا', 'الحجر', 'اُدۡخُلُوۡہَا بِسَلٰمٍ  اٰمِنِیۡنَ ﴿۴۶﴾', 'ان سے کہا جائے گا کہ ان میں سلامتی اور امن و اطمینان سے داخل ہو جاؤ۔', 'کہیں گے انکو جاؤ ان میں سلامتی سے خاطر جمع سے (بے کھٹکے) [۳۸]', '\"(It will be said to them): Enter therein (Paradise), in peace and security.', '“Enter here in peace, free of fear.”'),
(1849, 15, 47, 4, 4, 14, 'رُبَمَا', 'الحجر', 'وَ نَزَعۡنَا مَا فِیۡ صُدُوۡرِہِمۡ مِّنۡ غِلٍّ اِخۡوَانًا عَلٰی  سُرُرٍ  مُّتَقٰبِلِیۡنَ ﴿۴۷﴾', 'اور انکے دلوں میں جو کدورت ہو گی ہم اسے نکال دیں گے گویا بھائی بھائی مسندوں پر ایک دوسرے کے سامنے بیٹھے ہیں۔', 'اور نکال ڈالی ہم نے جو انکے جیوں میں تھی خفگی بھائی ہو گئے [۳۹] تختوں پر بیٹھے آمنے سامنے [۴۰]', '\"And We shall remove from their breasts any sense of injury (that they may have), (So they will be like) brothers facing each other on thrones.', 'We shall have removed whatever grudge they had in their hearts, (thus making them) brothers, sitting on couches, face to face.'),
(1850, 15, 48, 4, 4, 14, 'رُبَمَا', 'الحجر', 'لَا  یَمَسُّہُمۡ فِیۡہَا نَصَبٌ  وَّ  مَا ہُمۡ  مِّنۡہَا بِمُخۡرَجِیۡنَ ﴿۴۸﴾', 'نہ انکو وہاں کوئی تکلیف پہنچے گی اور نہ وہ وہاں سے نکالے جائیں گے۔', 'نہ پہنچے گی انکو  وہاں کچھ تکلیف اور نہ انکو  وہاں سے کوئی نکالے [۴۱]', '\"No sense of fatigue shall touch them, nor shall they (ever) be asked to leave it.\"', 'No weariness shall touch them nor will they be expelled from there.'),
(1851, 15, 49, 4, 4, 14, 'رُبَمَا', 'الحجر', 'نَبِّیٔۡ عِبَادِیۡۤ  اَنِّیۡۤ  اَنَا الۡغَفُوۡرُ الرَّحِیۡمُ ﴿ۙ۴۹﴾', 'اے پیغمبر میرے بندوں کو بتا دو کہ میں بڑا بخشنے والا ہوں بڑا مہربان ہوں۔', 'خبر سنا دے میرے بندوں کو کہ میں ہوں اصل بخشنے والا مہربان', 'Declare (O Muhammad SAW) unto My slaves, that truly, I am the Oft-Forgiving, the Most-Merciful.', 'Tell My servants that I am the Most-Forgiving, the Very-Merciful'),
(1852, 15, 50, 4, 4, 14, 'رُبَمَا', 'الحجر', 'وَ اَنَّ عَذَابِیۡ ہُوَ  الۡعَذَابُ  الۡاَلِیۡمُ ﴿۵۰﴾', 'اور یہ کہ میرا عذاب بھی درد دینے والا عذاب ہے۔', 'اور یہ بھی کہ میرا عذاب وہی عذاب دردناک ہے [۴۲]', 'And that My Torment is indeed the most painful torment.', 'and that My punishment is the painful punishment,'),
(1853, 15, 51, 4, 4, 14, 'رُبَمَا', 'الحجر', 'وَ نَبِّئۡہُمۡ عَنۡ ضَیۡفِ  اِبۡرٰہِیۡمَ ﴿ۘ۵۱﴾', 'اور انکو ابراہیم کے مہمانوں کو احوال سنا دو۔', 'اور حال سنا دے انکو ابراہیم کے مہمانوں کا [۴۳]', 'And tell them about the guests (the angels) of Ibrahim (Abraham).', 'and tell them about the guests of Ibrāhīm.'),
(1854, 15, 52, 4, 4, 14, 'رُبَمَا', 'الحجر', 'اِذۡ دَخَلُوۡا عَلَیۡہِ فَقَالُوۡا سَلٰمًا ؕ قَالَ  اِنَّا مِنۡکُمۡ  وَجِلُوۡنَ ﴿۵۲﴾', 'جب وہ ابراہیم کے پاس آئے تو سلام کہا۔ انہوں نے کہا کہ ہمیں تو تم سے ڈر لگتا ہے۔', 'جب چلے آئے اسکے گھر میں اور بولے (کیا انہوں نے) سلام وہ بولا ہم کو تم سے ڈر معلوم ہوتا ہے [۴۴]', 'When they entered unto him, and said: Salaman (peace)! (Ibrahim (Abraham)) said: \"Indeed! We are afraid of you.\"', 'When they visited him, they greeted him with Salām (peace on you). He said, “We are scared of you.”'),
(1855, 15, 53, 4, 4, 14, 'رُبَمَا', 'الحجر', 'قَالُوۡا لَا تَوۡجَلۡ  اِنَّا نُبَشِّرُکَ بِغُلٰمٍ عَلِیۡمٍ ﴿۵۳﴾', 'مہمانوں نے کہا کہ ڈریئے نہیں ہم آپ کو ایک دانشمند لڑکے کی خوشخبری دیتے ہیں۔', 'بولے ڈر مت ہم تجھ کو خوشخبری سناتے ہیں ایک ہوشیار لڑکے کی [۴۵]', 'They (the angels) said: \"Do not be afraid! We give you glad tidings of a boy (son) possessing much knowledge and wisdom.\"', 'They said, “Do not be scared. We give you good news of a boy who will be knowledgeable.”'),
(1856, 15, 54, 4, 4, 14, 'رُبَمَا', 'الحجر', 'قَالَ اَبَشَّرۡتُمُوۡنِیۡ عَلٰۤی اَنۡ مَّسَّنِیَ الۡکِبَرُ  فَبِمَ  تُبَشِّرُوۡنَ ﴿۵۴﴾', 'وہ بولے کہ جب مجھے بڑھاپے نے آ پکڑا تو تم خوشخبری دینے لگے۔ اب کاہے کی خوشخبری دیتے ہو۔', 'بولا کیا خوشخبری سناتے ہو مجھ کو جب پہنچ چکا مجھ کو بڑھاپا اب کاہے پر خوشخبری سناتے ہو [۴۶]', '(Ibrahim (Abraham)) said: \"Do you give me glad tidings (of a son) when old age has overtaken me? Of what then is your news?\"', 'He said, “Do you give me the good news despite the old age has befallen me? So what good news you are giving to me?”'),
(1857, 15, 55, 4, 4, 14, 'رُبَمَا', 'الحجر', 'قَالُوۡا بَشَّرۡنٰکَ بِالۡحَقِّ فَلَا تَکُنۡ مِّنَ الۡقٰنِطِیۡنَ ﴿۵۵﴾', 'انہوں نے کہا کہ ہم آپ کو سچی خوشخبری دیتے ہیں سو آپ مایوس نہ ہوں۔', 'بولے ہم نے تجھ کو خوشخبری سنائی سچی (پکی) سو مت ہو تو نا امیدوں میں', 'They (the angels) said: \"We give you glad tidings in truth. So be not of the despairing ones.\"', 'They said, “We have given to you the good news of a fact. So do not be one of those who lose hope.”'),
(1858, 15, 56, 4, 4, 14, 'رُبَمَا', 'الحجر', 'قَالَ وَ مَنۡ یَّقۡنَطُ مِنۡ رَّحۡمَۃِ  رَبِّہٖۤ  اِلَّا الضَّآلُّوۡنَ ﴿۵۶﴾', 'ابراہیم نے کہا کہ اللہ کی رحمت سے مایوس ہونا تو گمراہوں کا کام ہے۔', 'بولا اور کون آس توڑے اپنے رب کی رحمت سے مگر (وہی) جو گمراہ ہیں [۴۷]', '(Ibrahim (Abraham)) said: \"And who despairs of the Mercy of his Lord except those who are astray?\"', 'He said, “Who can lose hope in the mercy of his Lord except those who have lost the straight path?”'),
(1859, 15, 57, 4, 4, 14, 'رُبَمَا', 'الحجر', 'قَالَ فَمَا خَطۡبُکُمۡ اَیُّہَا الۡمُرۡسَلُوۡنَ ﴿۵۷﴾', 'پھر کہنے لگے کہ فرشتو! تمہار اصل کام کیا ہے۔', 'بولا پھر کیا مہم ہے تمہاری اے اللہ کے بھیجے ہوؤ [۴۸]', '(Ibrahim (Abraham) again) said: \"What then is the business on which you have come, O Messengers?\"', 'He said, “Then, what is your mission, O messengers?”'),
(1860, 15, 58, 4, 4, 14, 'رُبَمَا', 'الحجر', 'قَالُوۡۤا اِنَّاۤ اُرۡسِلۡنَاۤ  اِلٰی قَوۡمٍ مُّجۡرِمِیۡنَ ﴿ۙ۵۸﴾', 'انہوں نے کہا ہم ایک گنہگار قوم کی طرف بھیجے گئے ہیں کہ اس کو عذاب کریں۔', 'بولے ہم بھیجے ہوئے آئے ہیں ایک قوم گنہگار پر', 'They (the angels) said: \"We have been sent to a people who are Mujrimoon (criminals, disbelievers, polytheists, sinners).', 'They said, “We have been sent to a sinful people,'),
(1861, 15, 59, 4, 4, 14, 'رُبَمَا', 'الحجر', 'اِلَّاۤ اٰلَ لُوۡطٍ ؕ اِنَّا لَمُنَجُّوۡہُمۡ اَجۡمَعِیۡنَ ﴿ۙ۵۹﴾', 'مگر لوط کے گھر والے کہ ان سب کو ہم بچا لیں گے۔', 'مگر لوط کے گھر والے ہم انکو بچا لیں گے سب کو', '\"(All) except the family of Lout (Lot). Them all we are surely going to save (from destruction).', 'except the family of LūT - all of whom we shall save,'),
(1862, 15, 60, 4, 4, 14, 'رُبَمَا', 'الحجر', 'اِلَّا امۡرَاَتَہٗ  قَدَّرۡنَاۤ ۙ اِنَّہَا  لَمِنَ الۡغٰبِرِیۡنَ ﴿٪۶۰﴾', 'البتہ انکی بیوی کہ اسکے لئے ہم نے ٹھہرا دیا ہے کہ وہ پیچھے رہ جائے گی۔', 'مگر ایک اسکی عورت ہم نے ٹھہرا لیا وہ ہے رہ جانے والوں میں [۴۹]', '\"Except his wife, of whom We have decreed that she shall be of those who remain behind (i.e. she will be destroyed).\"', 'but his wife. We have ordained that she will be among those who will remain behind.”'),
(1863, 15, 61, 5, 5, 14, 'رُبَمَا', 'الحجر', 'فَلَمَّا جَآءَ  اٰلَ  لُوۡطِۣ الۡمُرۡسَلُوۡنَ ﴿ۙ۶۱﴾', 'پھر جب فرشتے لوط کے گھر آئے۔', 'پھر جب پہنچے لوط کے گھر وہ بھیجے ہوئے', 'Then, when the Messengers (the angels) came unto the family of Lout (Lot).', 'So when the messengers came to the family of LūT,'),
(1864, 15, 62, 5, 5, 14, 'رُبَمَا', 'الحجر', 'قَالَ  اِنَّکُمۡ  قَوۡمٌ  مُّنۡکَرُوۡنَ ﴿۶۲﴾', 'تو انہوں نے کہا کہ تم تو نا آشنا سے لوگ ہو۔', 'بولا تم لوگ ہو اوپرے (جن سے کھٹکا ہوتا ہے) [۵۰]', 'He said: \"Verily! You are people unknown to me.\"', 'he said, “You are an unfamiliar people.”'),
(1865, 15, 63, 5, 5, 14, 'رُبَمَا', 'الحجر', 'قَالُوۡا بَلۡ جِئۡنٰکَ بِمَا کَانُوۡا فِیۡہِ یَمۡتَرُوۡنَ ﴿۶۳﴾', 'وہ بولے کہ نہیں بلکہ ہم آپ کے پاس وہ چیز لے کر آئے ہیں جس میں لوگ شک کرتے تھے۔', 'بولے نہیں پر ہم لیکر آئے ہیں تیرے پاس وہ چیز جس میں وہ جھگڑتے تھے [۵۱]', 'They said: \"Nay, we have come to you with that (torment) which they have been doubting.', 'They said, “No, but we have brought to you that (scourge) in which they have been doubting,'),
(1866, 15, 64, 5, 5, 14, 'رُبَمَا', 'الحجر', 'وَ  اَتَیۡنٰکَ بِالۡحَقِّ وَ  اِنَّا  لَصٰدِقُوۡنَ ﴿۶۴﴾', 'اور ہم آپ کے پاس یقینی بات لے کر آئے ہیں اور ہم سچ کہتے ہیں۔', 'اور ہم لائے ہیں تیرے پاس پکی بات اور ہم سچ کہتے ہیں [۵۲]', '\"And we have brought to you the truth (the news of the destruction of your nation) and certainly, we tell the truth.', 'and we have come to you with a definite matter and surely we are truthful.'),
(1867, 15, 65, 5, 5, 14, 'رُبَمَا', 'الحجر', 'فَاَسۡرِ بِاَہۡلِکَ بِقِطۡعٍ مِّنَ الَّیۡلِ وَ اتَّبِعۡ اَدۡبَارَہُمۡ وَ لَا یَلۡتَفِتۡ مِنۡکُمۡ  اَحَدٌ وَّ امۡضُوۡا  حَیۡثُ  تُؤۡمَرُوۡنَ ﴿۶۵﴾', 'تو آپ کچھ رات رہے سے اپنے گھر والوں کو لے نکلیں اور خود انکے پیچھے چلیں اور آپ میں سے کوئی شخص پیچھے مڑ کر نہ دیکھے۔ اور جہاں آپ کو حکم ہو وہاں چلے جایئے۔', 'سو لے نکل اپنے گھر کو کچھ رات رہے سے اور تو چل ان کے پیچھے اور مڑ کر نہ دیکھے تم میں سے کوئی [۵۳] اور چلے جاؤ جہاں تم کو حکم ہے [۵۴]', '\"Then travel in a part of the night with your family, and you go behind them in the rear, and let no one amongst you look back, but go on to where you are ordered.\"', 'So, carry your family after a part of the night (has passed), and follow them at the rear (to make sure that all of your family has joined you), and no one from you should look back; and keep going to where you are commanded.”'),
(1868, 15, 66, 5, 5, 14, 'رُبَمَا', 'الحجر', 'وَ قَضَیۡنَاۤ  اِلَیۡہِ ذٰلِکَ الۡاَمۡرَ اَنَّ  دَابِرَ ہٰۤؤُلَآءِ  مَقۡطُوۡعٌ  مُّصۡبِحِیۡنَ ﴿۶۶﴾', 'اور ہم نے لوط کی طرف وحی بھیجی کہ ان لوگوں کی جڑ صبح ہوتے ہوتے کاٹ دی جائے گی۔', 'اور مقرر کر دی ہم نے اس کو یہ بات کہ ان کی جڑ کٹے گی صبح ہوتے [۵۵]', 'And We made known this decree to him, that the root of those (sinners) was to be cut off in the early morning.', 'We conveyed to him Our decision that they (the unbelievers) were to be totally uprooted when they would see the morning.'),
(1869, 15, 67, 5, 5, 14, 'رُبَمَا', 'الحجر', 'وَ جَآءَ اَہۡلُ الۡمَدِیۡنَۃِ یَسۡتَبۡشِرُوۡنَ ﴿۶۷﴾', 'اور اہل شہر لوط کے پاس خوش خوش دوڑے آئے۔', 'اور آئے شہر کے لوگ خوشیاں کرتے [۵۶]', 'And the inhabitants of the city came rejoicing (at the news of the young mens arrival).', 'And the people of the city came rejoicing.'),
(1870, 15, 68, 5, 5, 14, 'رُبَمَا', 'الحجر', 'قَالَ  اِنَّ ہٰۤؤُلَآءِ ضَیۡفِیۡ فَلَا تَفۡضَحُوۡنِ ﴿ۙ۶۸﴾', 'لوط نے کہا کہ یہ میرے مہمان ہیں کہیں ان کے بارے میں مجھے رسوا نہ کرنا۔', 'لوط نے کہا یہ لوگ میرے مہمان ہیں سو مجھ کو رسوا مت کرو [۵۷]', '(Lout (Lot)) said: \"Verily! these are my guests, so shame me not.', 'He (LūT) said, “They are my guests; so do not put me to shame,'),
(1871, 15, 69, 5, 5, 14, 'رُبَمَا', 'الحجر', 'وَ اتَّقُوا  اللّٰہَ  وَ لَا  تُخۡزُوۡنِ ﴿۶۹﴾', 'اور اللہ سے ڈرو۔ اور میری بےآبروئی نہ کرو۔', 'اور ڈرو  اللہ سے اور میری آبرو مت کھوؤ [۵۸]', '\"And fear Allah and disgrace me not.\"', 'and fear Allah and do not disgrace me.”'),
(1872, 15, 70, 5, 5, 14, 'رُبَمَا', 'الحجر', 'قَالُوۡۤا  اَوَ لَمۡ  نَنۡہَکَ  عَنِ الۡعٰلَمِیۡنَ ﴿۷۰﴾', 'وہ بولے کیا ہم نے تمکو سارے جہاں کی حمایت و طرفداری سے منع نہیں کیا۔', 'بولے کیا ہم نے تجھ کو منع نہیں کیا جہان کی حمایت سے [۵۹]', 'They (people of the city) said: \"Did we not forbid you to entertain (or protect) any of the Alameen (people, foreigners, strangers, etc. from us)?\"', 'They said, “Had we not forbidden you from (being the guardian of) the whole world?”'),
(1873, 15, 71, 5, 5, 14, 'رُبَمَا', 'الحجر', 'قَالَ ہٰۤؤُلَآءِ بَنٰتِیۡۤ  اِنۡ کُنۡتُمۡ فٰعِلِیۡنَ ﴿ؕ۷۱﴾', 'انہوں نے کہا کہ اگر تمہیں کرنا ہی ہے تو یہ میری قوم کی لڑکیاں ہیں ان سے شادی کر لو۔', 'بولا یہ حاضر ہیں میری بیٹیاں اگر تم کو کرنا ہے [۶۰]', '(Lout (Lot)) said: \"These (the girls of the nation) are my daughters (to marry lawfully), if you must act (so).\"', 'He said, “These are my daughters, if you are to do something.”'),
(1874, 15, 72, 5, 5, 14, 'رُبَمَا', 'الحجر', 'لَعَمۡرُکَ اِنَّہُمۡ لَفِیۡ سَکۡرَتِہِمۡ یَعۡمَہُوۡنَ ﴿۷۲﴾', 'اے نبی تمہاری جان کی قسم وہ اپنی مستی میں مدہوش ہو رہے تھے۔', 'قسم ہے تیری جان کی وہ اپنی مستی میں مدہوش (نشے) ہیں [۶۱]', 'Verily, by your life (O Muhammad SAW), in their wild intoxication, they were wandering blindly.', 'By your life, (O prophet) they were wandering blindly in their intoxication (misguidance).'),
(1875, 15, 73, 5, 5, 14, 'رُبَمَا', 'الحجر', 'فَاَخَذَتۡہُمُ  الصَّیۡحَۃُ  مُشۡرِقِیۡنَ ﴿ۙ۷۳﴾', 'سو ان کو سورج نکلتے نکلتے چنگھاڑ نے آ پکڑا۔', 'پھر آ پکڑا انکو چنگھاڑ نے سورج نکلتے وقت (ہی) [۶۲]', 'So As-Saeehah (torment - awful cry, etc.) overtook them at the time of sunrise;', 'So, they were seized by the Cry at sunrise.'),
(1876, 15, 74, 5, 5, 14, 'رُبَمَا', 'الحجر', 'فَجَعَلۡنَا عَالِیَہَا سَافِلَہَا وَ اَمۡطَرۡنَا عَلَیۡہِمۡ  حِجَارَۃً  مِّنۡ  سِجِّیۡلٍ ﴿ؕ۷۴﴾', 'اور ہم نے ان بستیوں کو الٹ کر نیچے اوپر کر دیا۔ اور ان پر کھنگر کی  پتھریاں برسائیں۔', 'پھر کر ڈالی ہم نے وہ بستی اوپر تلے اور برسائے ان پر پتھر کھنگر (کنکر) کے [۶۳]', 'And We turned (the towns of Sodom in Palestine) upside down and rained down on them stones of baked clay.', 'Then, We turned it (the city) upside down and rained down upon them stones of baked clay.'),
(1877, 15, 75, 5, 5, 14, 'رُبَمَا', 'الحجر', 'اِنَّ  فِیۡ ذٰلِکَ  لَاٰیٰتٍ  لِّلۡمُتَوَسِّمِیۡنَ ﴿۷۵﴾', 'بیشک اس قصے میں اہل فراست کے لئے نشانی ہے۔', 'بیشک اس میں نشانیاں ہیں دھیان کرنے والوں کو [۶۴]', 'Surely! In this are signs, for those who see (or understand or learn the lessons from the Signs of Allah).', 'Surely, in that there are signs for those who read signs.'),
(1878, 15, 76, 5, 5, 14, 'رُبَمَا', 'الحجر', 'وَ  اِنَّہَا لَبِسَبِیۡلٍ  مُّقِیۡمٍ ﴿۷۶﴾', 'اور وہ بستیاں اب تک شام جانے والے سیدھے رستے پر موجود ہیں۔', 'اور وہ بستی واقع ہےسیدھی راہ پر [۶۵]', 'And verily! They (the cities) were right on the highroad (from Makkah to Syria i.e. the place where the Dead Sea is now).', 'Surely, it (their city) is located on the straight road.'),
(1879, 15, 77, 5, 5, 14, 'رُبَمَا', 'الحجر', 'اِنَّ فِیۡ ذٰلِکَ لَاٰیَۃً   لِّلۡمُؤۡمِنِیۡنَ ﴿ؕ۷۷﴾', 'بیشک اس میں ایمان لانے والوں کے لئے نشانی ہے۔', 'البتہ اس میں نشانی ہے ایمان والوں کو (یقین کرنے والوں کو) [۶۶]', 'Surely! Therein is indeed a sign for the believers.', 'Surely, in it there is a sign for the believers.'),
(1880, 15, 78, 5, 5, 14, 'رُبَمَا', 'الحجر', 'وَ  اِنۡ کَانَ اَصۡحٰبُ الۡاَیۡکَۃِ لَظٰلِمِیۡنَ ﴿ۙ۷۸﴾', 'اور بن کے رہنے والے یعنی قوم شعیب کے لوگ بھی گنہگار تھے۔', 'اور تحقیق تھے بن کے رہنے والے گنہگار [۶۷]', 'And the dwellers in the wood (i.e. the people of Madyan (Midian) to whom Prophet Shuaib () was sent by Allah), were also Zalimoon (polytheists and wrong-doers, etc.).', 'And the people of Aikah were (also) transgressors.'),
(1881, 15, 79, 5, 5, 14, 'رُبَمَا', 'الحجر', 'فَانۡتَقَمۡنَا مِنۡہُمۡ ۘ وَ اِنَّہُمَا لَبِاِمَامٍ مُّبِیۡنٍ ﴿ؕ٪۷۹﴾', 'تو ہم نے ان سے بھی بدلہ لیا اور یہ دونوں شہر کھلے رستے پر موجود ہیں۔', 'سو ہم نے بدلہ لیا ان سے اور یہ دونوں بستیاں واقع ہیں کھلے راستہ پر [۶۸]', 'So, We took vengeance on them. They are both on an open highway, plain to see.', 'So, We punished them in retribution, and both of them are (situated) by a highway, clearly visible.'),
(1882, 15, 80, 6, 6, 14, 'رُبَمَا', 'الحجر', 'وَ لَقَدۡ کَذَّبَ اَصۡحٰبُ الۡحِجۡرِ  الۡمُرۡسَلِیۡنَ ﴿ۙ۸۰﴾', 'اور وادی حجر کے رہنے والوں نے بھی پیغمبروں کی تکذیب کی۔', 'اور بیشک جھٹلایا حجر والوں نے (حجر کے رہنے والوں نے) رسولوں کو [۶۹]', 'And verily, the dwellers of Al-Hijr (the rocky tract) denied the Messengers.', 'And the people of Al-Hijr gave the lie to the messengers.'),
(1883, 15, 81, 6, 6, 14, 'رُبَمَا', 'الحجر', 'وَ اٰتَیۡنٰہُمۡ اٰیٰتِنَا فَکَانُوۡا عَنۡہَا مُعۡرِضِیۡنَ ﴿ۙ۸۱﴾', 'ہم نے ان کو اپنی نشانیاں دیں اور وہ ان سے منہ پھیرتے رہے۔', 'اور دیں ہم نے انکو اپنی نشانیاں سو رہے ان سے منہ پھیرتے (ان کو ٹالنے) [۷۰]', 'And We gave them Our Signs, but they were averse to them.', 'We provided them with Our signs, yet they kept turning away from them.'),
(1884, 15, 82, 6, 6, 14, 'رُبَمَا', 'الحجر', 'وَ کَانُوۡا یَنۡحِتُوۡنَ مِنَ الۡجِبَالِ بُیُوۡتًا اٰمِنِیۡنَ ﴿۸۲﴾', 'اور وہ پہاڑوں کو تراش تراش کر گھر بناتے تھے کہ امن و اطمینان سے رہیں گے۔', 'اور تھے کہ تراشتے تھے پہاڑوں کے گھر اطمینان کے ساتھ [۷۱]', 'And they used to hew out dwellings from the mountains (feeling themselves) secure.', 'They used to hew out houses from the hills peacefully.'),
(1885, 15, 83, 6, 6, 14, 'رُبَمَا', 'الحجر', 'فَاَخَذَتۡہُمُ  الصَّیۡحَۃُ  مُصۡبِحِیۡنَ ﴿ۙ۸۳﴾', 'آخر زوردار آواز نے ان کو صبح ہوتے ہوتے آ پکڑا۔', 'پھر پکڑا انکو چنگھاڑ نے صبح ہونے (ہوتے) کے وقت', 'But As-Saeehah (torment - awful cry etc.) overtook them in the early morning (of the fourth day of their promised punishment days).', 'Then, the Cry seized them by the morning.'),
(1886, 15, 84, 6, 6, 14, 'رُبَمَا', 'الحجر', 'فَمَاۤ  اَغۡنٰی عَنۡہُمۡ مَّا کَانُوۡا یَکۡسِبُوۡنَ ﴿ؕ۸۴﴾', 'اور جو کام وہ کرتے تھے وہ ان کے کچھ بھی کام نہ آئے۔', 'پھر کام نہ آیا انکے جو کچھ کمایا تھا [۷۲]', 'And all that which they used to earn availed them not.', 'So, whatever they earned did not come to their help.'),
(1887, 15, 85, 6, 6, 14, 'رُبَمَا', 'الحجر', 'وَ مَا خَلَقۡنَا السَّمٰوٰتِ وَ الۡاَرۡضَ وَ مَا بَیۡنَہُمَاۤ  اِلَّا بِالۡحَقِّ ؕ وَ اِنَّ السَّاعَۃَ لَاٰتِیَۃٌ  فَاصۡفَحِ  الصَّفۡحَ  الۡجَمِیۡلَ ﴿۸۵﴾', 'اور ہم نے آسمانوں اور زمین کو اور جو مخلوقات ان میں ہے سب کو تدبیر کے ساتھ پیدا کیا ہے۔ اور قیامت تو ضرور آ کر رہے گی تو تم ان لوگوں سے اچھی طرح سے درگذر کرو۔', 'اور ہم نے بنائے نہیں آسمان اور زمین اور جو ان کے بیچ میں ہے بغیر حکمت (تدبیر) اور قیامت بیشک آنے والی ہے سو کنارہ کر اچھی  طرح کنارہ [۷۳]', 'And We created not the heavens and the earth and all that is between them except with truth, and the Hour is surely coming, so overlook (O Muhammad SAW), their faults with gracious forgiveness. (This was before the ordainment of Jihad holy fighting in Allahs Cause).', 'We did not create the heavens and the earth and all that is in between them without a truthful purpose. The Hour is sure to come. Therefore, overlook (their evil behavior) in a gracious manner.'),
(1888, 15, 86, 6, 6, 14, 'رُبَمَا', 'الحجر', 'اِنَّ  رَبَّکَ ہُوَ  الۡخَلّٰقُ  الۡعَلِیۡمُ ﴿۸۶﴾', 'کچھ شک نہیں کہ تمہارا پروردگار ہی سب کچھ پیدا کرنے والا ہے جاننے والا ہے۔', 'تیرا رب جو ہے وہی ہے پیدا کرنے والا خبردار [۷۴]', 'Verily, your Lord is the All-Knowing Creator.', 'Surely, your Lord is the Creator of all, the All-Knowing.'),
(1889, 15, 87, 6, 6, 14, 'رُبَمَا', 'الحجر', 'وَ لَقَدۡ اٰتَیۡنٰکَ سَبۡعًا مِّنَ الۡمَثَانِیۡ وَ الۡقُرۡاٰنَ  الۡعَظِیۡمَ ﴿۸۷﴾', 'اور ہم نے تم کو سات آیتیں جو نماز میں دھرا کر پڑھی جاتی ہیں یعنی سورۃ الحمد اور عظمت والا کلام عطا فرمایا ہے۔', 'اور ہم نے دی ہیں تجھ کو سات آیتیں وظیفہ اور قرآن بڑے درجہ کا [۷۵]', 'And indeed, We have bestowed upon you seven of Al-Mathani (the seven repeatedly recited Verses), (i.e. Soorat Al-Fatiha) and the Grand Quran.', 'We have given you the seven oft-repeated verses and the glorious Qur’ān.'),
(1890, 15, 88, 6, 6, 14, 'رُبَمَا', 'الحجر', 'لَا تَمُدَّنَّ عَیۡنَیۡکَ اِلٰی مَا مَتَّعۡنَا بِہٖۤ اَزۡوَاجًا مِّنۡہُمۡ وَ لَا تَحۡزَنۡ عَلَیۡہِمۡ وَ اخۡفِضۡ جَنَاحَکَ  لِلۡمُؤۡمِنِیۡنَ  ﴿۸۸﴾', 'ہم نے کفار کی کئ جماعتوں کو جنکو فوائد دنیاوی سے نوازا ہے تم ان کی طرف رغبت سے آنکھ اٹھا کر نہ دیکھنا اور نہ ان کے حال پر رنج و غم کرنا اور مومنوں کے ساتھ تواضع سے پیش آنا۔', 'مت ڈال اپنی آنکھیں ان چیزوں پر جو برتنے کو دیں ہم نے ان میں سے کئ طرح کے لوگوں کو [۷۶] اور نہ غم کھا ان پر اور جھکا اپنے بازو ایمان والوں کے واسطے [۷۷]', 'Look not with your eyes ambitiously at what We have bestowed on certain classes of them (the disbelievers), nor grieve over them. And lower your wings for the believers (be courteous to the fellow-believers).', 'Never stretch your eyes towards what We have given to groups of them to enjoy, and do not grieve for them, and be kind to believers in humbleness,'),
(1891, 15, 89, 6, 6, 14, 'رُبَمَا', 'الحجر', 'وَ قُلۡ   اِنِّیۡۤ   اَنَا النَّذِیۡرُ  الۡمُبِیۡنُ ﴿ۚ۸۹﴾', 'اور کہدو کہ میں تو علانیہ ڈر سنانے والا ہوں۔', 'اور کہہ کہ میں وہی ہوں ڈرانے والا کھول کر [۷۸]', 'And say: \"I am indeed a plain warner.\"', 'and say, “I am a plain warner indeed”'),
(1892, 15, 90, 6, 6, 14, 'رُبَمَا', 'الحجر', 'کَمَاۤ   اَنۡزَلۡنَا عَلَی  الۡمُقۡتَسِمِیۡنَ ﴿ۙ۹۰﴾', 'اور ہم ان کفار پر اسی طرح عذاب نازل کریں گے جس طرح ان لوگوں پر نازل کیا جنہوں نے تقسیم کر دیا۔', 'جیسا ہم نے بھیجا ہے ان بانٹنے والوں پر', 'As We have sent down on the dividers, (Quraish pagans or Jews and Christians).', '(to warn them that We may send down the scourge upon them) as We sent down upon the dividers.'),
(1893, 15, 91, 6, 6, 14, 'رُبَمَا', 'الحجر', 'الَّذِیۡنَ  جَعَلُوا  الۡقُرۡاٰنَ  عِضِیۡنَ  ﴿۹۱﴾', 'یعنی قرآن کو کچھ ماننے اور کچھ نہ ماننے سے ٹکڑے ٹکڑے کر ڈالا۔', 'جنہوں نے کیا ہے قرآن کو بوٹیاں [۷۹]', 'Who have made the Quran into parts. (i.e. believed in a part and disbelieved in the other).', 'who had split the divine recitation (Scriptures) into bits.'),
(1894, 15, 92, 6, 6, 14, 'رُبَمَا', 'الحجر', 'فَوَ رَبِّکَ  لَنَسۡـَٔلَنَّہُمۡ  اَجۡمَعِیۡنَ ﴿ۙ۹۲﴾', 'سو تمہارے پروردگار کی قسم ہم ان سے ضرور پرسش کریں گے۔', 'سو قسم ہے تیرے رب کی ہم کو پوچھنا ہے ان سب سے', 'So, by your Lord (O Muhammad SAW), We shall certainly call all of them to account.', 'So, by your Lord, We shall question all of them.'),
(1895, 15, 93, 6, 6, 14, 'رُبَمَا', 'الحجر', 'عَمَّا  کَانُوۡا  یَعۡمَلُوۡنَ ﴿ٙ۹۳﴾', 'ان کاموں کی جو وہ کرتے رہے۔', 'جو کچھ وہ کرتے تھے [۸۰]', 'For all that they used to do.', 'about what they have been doing.'),
(1896, 15, 94, 6, 6, 14, 'رُبَمَا', 'الحجر', 'فَاصۡدَعۡ بِمَا تُؤۡمَرُ وَ اَعۡرِضۡ عَنِ الۡمُشۡرِکِیۡنَ ﴿۹۴﴾', 'پس جو حکم تم کو اللہ کی طرف سے ملا ہے وہ لوگوں کو بے دھڑک سنا دو اور مشرکوں کا ذرا خیال نہ کرو۔', 'سو سنا دے کھول کر جو تجھ کو حکم ہوا اور پروا نہ کر مشرکوں کی [۸۱]', 'Therefore proclaim openly (Allahs Message Islamic Monotheism) that which you are commanded, and turn away from Al-Mushrikoon (polytheists, idolaters, and disbelievers, etc. - see V.2:105).', 'Now, proclaim what you are commanded to, and turn away from those who ascribe partners to Allah.'),
(1897, 15, 95, 6, 6, 14, 'رُبَمَا', 'الحجر', 'اِنَّا کَفَیۡنٰکَ الۡمُسۡتَہۡزِءِیۡنَ ﴿ۙ۹۵﴾', 'ہم تمہیں ان لوگوں کے شر سے بچانے کے لئے کافی ہیں جو تم سے ہنسی کرتے ہیں۔', 'ہم بس (کافی) ہیں تیری طرف سے ٹھٹھے کرنے والوں کو [۸۲]', 'Truly! We will suffice you against the scoffers.', 'Surely, We are sufficient for you against those who deride,'),
(1898, 15, 96, 6, 6, 14, 'رُبَمَا', 'الحجر', 'الَّذِیۡنَ یَجۡعَلُوۡنَ مَعَ اللّٰہِ اِلٰہًا اٰخَرَ ۚ فَسَوۡفَ یَعۡلَمُوۡنَ ﴿۹۶﴾', 'جو اللہ کے ساتھ کوئی اور معبود قرار دیتے ہیں سو عنقریب انکو ان باتوں کا انجام معلوم ہو جائے گا۔', 'جو کہ ٹھہراتے ہیں اللہ کے ساتھ دوسرے کی بندگی سو عنقریب معلوم کر لیں گے [۸۳]', 'Who set up along with Allah another ilah (god), they will come to know.', '- those who believe in any other god along with Allah. So, they shall soon learn (the reality).'),
(1899, 15, 97, 6, 6, 14, 'رُبَمَا', 'الحجر', 'وَ لَقَدۡ نَعۡلَمُ اَنَّکَ یَضِیۡقُ صَدۡرُکَ بِمَا یَقُوۡلُوۡنَ ﴿ۙ۹۷﴾', 'اور ہم جانتے ہیں کہ انکی باتوں سے تمہارا دل تنگ ہوتا ہے۔', 'اور ہم جانتے ہیں کہ تیرا جی رکتا ہے انکی باتوں سے', 'Indeed, We know that your breast is straitened at what they say.', 'We know that your heart feels distressed for what they say.'),
(1900, 15, 98, 6, 6, 14, 'رُبَمَا', 'الحجر', 'فَسَبِّحۡ بِحَمۡدِ رَبِّکَ وَ کُنۡ مِّنَ السّٰجِدِیۡنَ ﴿ۙ۹۸﴾', 'تو تم اپنے پروردگار کی تسبیح کہتے اور اسکی خوبیاں بیان کرتے رہو اور سجدہ کرنے والوں میں سے ہو جاؤ۔', 'سو تو یاد کر خوبیاں اپنے رب کی اور ہو سجدہ کرنے والوں سے [۸۴]', 'So glorify the praises of your Lord and be of those who prostrate themselves (to Him).', 'So, proclaim the purity and glory of your Lord, and be among those who prostrate themselves (before Allah);'),
(1901, 15, 99, 6, 6, 14, 'رُبَمَا', 'الحجر', 'وَ اعۡبُدۡ رَبَّکَ حَتّٰی یَاۡتِیَکَ الۡیَقِیۡنُ ﴿٪۹۹﴾', 'اور اپنے پروردگار کی عبادت کئے جاؤ یہاں تک کہ تمہاری موت کا وقت آ جائے۔', 'اور بندگی کئے جا اپنے رب کی جب تک آئے تیرے پاس یقینی بات [۸۵]', 'And worship your Lord until there comes unto you the certainty (i.e. death).', 'and worship your Lord until comes to you that which is certain.'),
(1902, 16, 1, 1, 7, 14, 'رُبَمَا', 'النحل', 'اَتٰۤی اَمۡرُ اللّٰہِ فَلَا تَسۡتَعۡجِلُوۡہُ ؕ سُبۡحٰنَہٗ وَ تَعٰلٰی عَمَّا  یُشۡرِکُوۡنَ ﴿۱﴾', 'اللہ کا حکم یعنی عذاب گویا آ ہی پہنچا تو کافرو اس کے لئے جلدی مت کرو۔اور یہ لوگ جو اللہ کا شریک بناتے ہیں وہ اس سے پاک اور بالاتر ہے۔', 'آ پہنچا حکم اللہ کا سو اس کی جلدی مت کرو [۱] وہ پاک ہے اور برتر ہے انکے شریک بتلانے سے [۲]', 'The Event (the Hour or the punishment of disbelievers and polytheists or the Islamic laws or commandments), ordained by Allah will come to pass, so seek not to hasten it. Glorified and Exalted be He above all that they associate as partners with Him.', 'Allah’s command has (almost) come. So, do not demand that it should come sooner. Pure is He, and much higher than their ascribing partners to Him.'),
(1903, 16, 2, 1, 7, 14, 'رُبَمَا', 'النحل', 'یُنَزِّلُ الۡمَلٰٓئِکَۃَ بِالرُّوۡحِ مِنۡ  اَمۡرِہٖ عَلٰی مَنۡ یَّشَآءُ مِنۡ عِبَادِہٖۤ  اَنۡ  اَنۡذِرُوۡۤا  اَنَّہٗ  لَاۤ  اِلٰہَ   اِلَّاۤ   اَنَا  فَاتَّقُوۡنِ ﴿۲﴾', 'وہی فرشتوں کو پیغام دے کر اپنے حکم سے اپنے بندوں میں سے جسکے پاس چاہتا ہے بھیجتا ہے کہ لوگوں کو بتا دو کہ میرے سوا کوئی معبود نہیں تو مجھی سے ڈرو۔', 'اتارتا ہے فرشتوں کو [۳] بھید دے کر [۴] اپنے حکم سے جس پر چاہے اپنے بندوں میں [۵] کہ خبردار کر دو کہ کسی کی بندگی نہیں سوا میرے سو مجھ سے ڈرو [۶]', 'He sends down the angels with inspiration of His Command to whom of His slaves He pleases (saying): \"Warn mankind that La ilaha illa Ana (none has the right to be worshipped but I), so fear Me (by abstaining from sins and evil deeds).', 'He sends down the angels at His behest with the spirit, (that is, the revelation), upon whom He wills from among His servants: “Warn people that there is no god but Me. So, fear Me.”'),
(1904, 16, 3, 1, 7, 14, 'رُبَمَا', 'النحل', 'خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ بِالۡحَقِّ ؕ تَعٰلٰی عَمَّا  یُشۡرِکُوۡنَ ﴿۳﴾', 'اسی نے آسمانوں اور زمین کو حکمت سے پیدا کیا۔ اسکی ذات ان کافروں کے شرک سے بلند و برتر ہے۔', 'بنائے آسمان اور زمین ٹھیک ٹھیک وہ برتر ہے انکے شریک بتلانے سے [۷]', 'He has created the heavens and the earth with truth. High be He Exalted above all they associate as partners with Him.', 'He created the heavens and the earth in the proper way. He is much higher than their ascribing partners to Him.'),
(1905, 16, 4, 1, 7, 14, 'رُبَمَا', 'النحل', 'خَلَقَ الۡاِنۡسَانَ مِنۡ نُّطۡفَۃٍ  فَاِذَا ہُوَ خَصِیۡمٌ مُّبِیۡنٌ ﴿۴﴾', 'اسی نے انسان کو نطفے سے بنایا مگر وہ کھلم کھلا جھگڑالو بن گیا۔', 'بنایا آدمی کو ایک بوند سے پھر جبھی ہو گیا جھگڑا کرنے والا بولنے والا [۸]', 'He has created man from Nutfah (mixed drops of male and female sexual discharge), then behold, this same (man) becomes an open opponent.', 'He created man from a drop, and soon he turned into a debating person, expressing himself openly.'),
(1906, 16, 5, 1, 7, 14, 'رُبَمَا', 'النحل', 'وَ الۡاَنۡعَامَ خَلَقَہَا ۚ لَکُمۡ فِیۡہَا دِفۡءٌ  وَّ  مَنَافِعُ وَ مِنۡہَا  تَاۡکُلُوۡنَ ﴿۪۵﴾', 'اور مویشیوں کو بھی اسی نے پیدا کیا۔ ان میں تمہارے لئے سردی سے بچاؤ اور بہت سے دوسرے فائدے ہیں اور ان میں سے بعض کو تم کھاتے بھی ہو۔', 'اور چوپائے بنا دیے تمہارے واسطے ان میں جڑا دل ہے اور کتنے فائدے اور بعضوں کو کھاتے ہو [۹]', 'And the cattle, He has created them for you; in them there is warmth (warm clothing), and numerous benefits, and of them you eat.', 'He has created cattle in which there is warmth and other benefits for you; and from them you have food;'),
(1907, 16, 6, 1, 7, 14, 'رُبَمَا', 'النحل', 'وَ لَکُمۡ فِیۡہَا جَمَالٌ حِیۡنَ تُرِیۡحُوۡنَ وَ حِیۡنَ  تَسۡرَحُوۡنَ ﴿۪۶﴾', 'اور جب شام کو انہیں جنگل سے لاتے ہو اور جب صبح کو جنگل چرانے لے جاتے ہو تو ان سے تمہاری عزت و شان کا اظہار ہوتا ہے۔', 'اور تم کو ان سے عزت ہے جب شام کو چرا کر لاتے ہو اور جب چرانے لے جاتے ہو [۱۰]', 'And wherein is beauty for you, when you bring them home in the evening, and as you lead them forth to pasture in the morning.', 'and in them there is a beautiful look for you when you drive them home in the evening and take them out to graze.'),
(1908, 16, 7, 1, 7, 14, 'رُبَمَا', 'النحل', 'وَ تَحۡمِلُ اَثۡقَالَکُمۡ  اِلٰی بَلَدٍ لَّمۡ تَکُوۡنُوۡا بٰلِغِیۡہِ   اِلَّا بِشِقِّ الۡاَنۡفُسِ ؕ اِنَّ رَبَّکُمۡ   لَرَءُوۡفٌ  رَّحِیۡمٌ ۙ﴿۷﴾', 'اور دوردراز شہروں میں جہاں تم سخت محنت کے بغیر پہنچ نہیں سکتے وہ تمہارے بوجھ اٹھا کر لے جاتے ہیں کچھ شک نہیں کہ تمہارا پروردگار نہایت شفقت والا ہے مہربان ہے۔', 'اور اٹھا لے چلتے ہیں بوجھ تمہارے ان شہروں تک کہ تم نہ پہنچتے وہاں مگر جان مار کر بیشک تمہارا رب بڑا شفقت کرنے والا مہربان ہے [۱۱]', 'And they carry your loads to a land that you could not reach except with great trouble to yourselves. Truly, your Lord is full of Kindness, Most Merciful.', 'And they carry your loads to a city where you were not able to reach without putting yourselves to arduous labor. Surely, your Lord is Very-Kind, Very-Merciful.'),
(1909, 16, 8, 1, 7, 14, 'رُبَمَا', 'النحل', 'وَّ الۡخَیۡلَ وَ الۡبِغَالَ وَ الۡحَمِیۡرَ لِتَرۡکَبُوۡہَا وَ زِیۡنَۃً ؕ وَ یَخۡلُقُ مَا لَا تَعۡلَمُوۡنَ ﴿۸﴾', 'اور اسی نے گھوڑے اور خچر اور گدھے پیدا کئے تاکہ تم ان پر سوار ہو اور وہ تمہارے لئے رونق و زینت بھی ہیں اور وہ اور چیزیں بھی پیدا کرتا ہے جنکی تم کو خبر نہیں۔', 'اور گھوڑے پیدا کئے اور خچریں اور گدھے کہ ان پر سوار ہو اور زینت کے لئے [۱۲] اور پیدا کرتا ہے جو تم نہیں جانتے [۱۳]', 'And (He has created) horses, mules and donkeys, for you to ride and as an adornment. And He creates (other) things of which you have no knowledge.', 'And (He created) horses, mules and donkeys, so that you may ride on them, and they may give you a good look. And He creates what you do not know (as yet).'),
(1910, 16, 9, 1, 7, 14, 'رُبَمَا', 'النحل', 'وَ عَلَی اللّٰہِ  قَصۡدُ السَّبِیۡلِ وَ مِنۡہَا جَآئِرٌ ؕ وَ لَوۡ شَآءَ لَہَدٰىکُمۡ اَجۡمَعِیۡنَ ﴿٪۹﴾', 'اور سیدھا رستہ تو اللہ تک جا پہنچتا ہے۔ اور بعض رستے ٹیڑھے ہیں اور اگر وہ چاہتا تو تم سب کو سیدھے رستے پر چلا دیتا۔', 'اور اللہ  تک پہنچتی ہے سیدھی راہ اور بعضی راہ کج بھی ہے [۱۴] اور اگر وہ چاہے تو سیدھی راہ دے تم سب کو [۱۵]', 'And upon Allah is the responsibility to explain the Straight Path (i.e. Islamic Monotheism for mankind i.e. to show them legal and illegal, good and evil things, etc. so, whosoever accepts the guidance, it will be for his own benefit and whosoever goes astray, it will be for his own destruction), but there are ways that turn aside (such as Paganism, Judaism, Christianity, etc.). And had He willed, He would have guided you all (mankind).', 'Undertaken by Allah is (to show) the right path, while there are some (paths) that are crooked. Had He so willed, He would have led all of you to the right path.'),
(1911, 16, 10, 2, 8, 14, 'رُبَمَا', 'النحل', 'ہُوَ الَّذِیۡۤ اَنۡزَلَ مِنَ السَّمَآءِ مَآءً لَّکُمۡ  مِّنۡہُ شَرَابٌ وَّ مِنۡہُ  شَجَرٌ  فِیۡہِ تُسِیۡمُوۡنَ ﴿۱۰﴾', 'وہی تو ہے جس نے آسمان سے پانی برسایا جسے تم پیتے ہو اور اس سے درخت بھی شاداب ہوتے ہیں جن میں تم اپنے مویشیوں کو چراتے ہو۔', 'وہی ہے جس نے اتارا آسمان سے تمہارے لئے پانی اس سے پیتے ہو اور اسی سے درخت ہوتے ہیں جس میں چراتے ہو [۱۶]', 'He it is Who sends down water (rain) from the sky; from it you drink and from it (grows) the vegetation on which you send your cattle to pasture;', 'He is the One who sent down water from the heavens, of which you have your drink; and with it (you grow) plants on which you pasture your cattle.'),
(1912, 16, 11, 2, 8, 14, 'رُبَمَا', 'النحل', 'یُنۡۢبِتُ لَکُمۡ بِہِ الزَّرۡعَ وَ الزَّیۡتُوۡنَ وَ النَّخِیۡلَ وَ الۡاَعۡنَابَ وَ مِنۡ کُلِّ الثَّمَرٰتِ ؕ اِنَّ  فِیۡ  ذٰلِکَ لَاٰیَۃً  لِّقَوۡمٍ یَّتَفَکَّرُوۡنَ ﴿۱۱﴾', 'اسی پانی سے وہ تمہارے لئے کھیتی اور زیتون اور کھجور اور انگور اور دوسرے بے شمار درخت اگاتا ہے۔ اور ہر طرح کے پھل پیدا کرتا ہے غور کرنے والوں کے لئے اس میں اللہ کی قدرت کی بڑی نشانی ہے۔', 'اگاتا ہے تمہارے واسطے اس سے کھیتی اور زیتون اور کھجوریں اور انگور اور ہر قسم کے میوے اس میں البتہ نشانی ہے ان لوگوں کو جو غور کرتے ہیں [۱۷]', 'With it He causes to grow for you the crops, the olives, the date-palms, the grapes, and every kind of fruit. Verily! In this is indeed an evident proof and a manifest sign for people who give thought.', 'He causes the crops therewith to grow for you, and olives, and date palms, and grape vines, and all the fruits. Surely, in that, there is a sign for a people who ponder.'),
(1913, 16, 12, 2, 8, 14, 'رُبَمَا', 'النحل', 'وَ  سَخَّرَ لَکُمُ الَّیۡلَ وَ النَّہَارَ ۙ وَ الشَّمۡسَ وَ الۡقَمَرَ ؕ وَ النُّجُوۡمُ  مُسَخَّرٰتٌۢ بِاَمۡرِہٖ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیٰتٍ لِّقَوۡمٍ  یَّعۡقِلُوۡنَ ﴿ۙ۱۲﴾', 'اور اسی نے تمہارے لئے رات اور دن اور سورج اور چاند کو کام میں لگایا اور اسی کے حکم سے ستارے بھی کام میں لگے ہوئے ہیں۔ سمجھنے والوں کے لئے اس میں بہت سی نشانیاں ہیں۔', 'اور تمہارے کام میں لگا دیا رات اور دن اور سورج اور چاند کو اور ستارے کام میں لگے ہیں اسکے حکم سے [۱۸] اس میں نشانیاں ہیں ان لوگوں کو جو سمجھ رکھتے ہیں', 'And He has subjected to you the night and the day, the sun and the moon; and the stars are subjected by His Command. Surely, in this are proofs for people who understand.', 'He has subjugated for you the day and the night and the sun and the moon, and the stars (too) are subservient by His command. Surely, in that, there are signs for a people who understand.'),
(1914, 16, 13, 2, 8, 14, 'رُبَمَا', 'النحل', 'وَ مَا ذَرَاَ لَکُمۡ فِی الۡاَرۡضِ مُخۡتَلِفًا اَلۡوَانُہٗ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیَۃً  لِّقَوۡمٍ یَّذَّکَّرُوۡنَ ﴿۱۳﴾', 'اور جو طرح طرح کے رنگوں کی چیزیں اس نے زمین میں پیدا کیں سب تمہارے زیر فرمان کر دیں نصیحت حاصل کرنے والوں کے لئے اس میں نشانی ہے۔', 'اور جو چیزیں پھیلائیں تمہارے واسطے زمین میں رنگ برنگ کی [۱۹] اس میں نشانی ہے ان لوگوں کو جو سوچتے ہیں', 'And whatsoever He has created for you on this earth of varying colours (and qualities from vegetation and fruits, etc. (botanical life) and from animal (zoological life)). Verily! In this is a sign for people who remember.', 'And (He subjugated to you) whatever He created for you on the earth having varied colors. Surely, in that, there is a sign for a people who accept advice.'),
(1915, 16, 14, 2, 8, 14, 'رُبَمَا', 'النحل', 'وَ ہُوَ الَّذِیۡ سَخَّرَ  الۡبَحۡرَ   لِتَاۡکُلُوۡا  مِنۡہُ لَحۡمًا طَرِیًّا وَّ تَسۡتَخۡرِجُوۡا مِنۡہُ حِلۡیَۃً تَلۡبَسُوۡنَہَا ۚ وَ تَرَی الۡفُلۡکَ مَوَاخِرَ فِیۡہِ وَ لِتَبۡتَغُوۡا مِنۡ فَضۡلِہٖ وَ لَعَلَّکُمۡ   تَشۡکُرُوۡنَ ﴿۱۴﴾', 'اور وہی تو ہے جس نے دریا کو تمہارے اختیار میں کیا تاکہ اس میں سے تازہ گوشت نکال کر کھاؤ۔ اور اس سے زیور موتی وغیرہ نکالو جسے تم پہنتے ہو۔ اور تم دیکھتے ہو کہ کشتیاں سمندر میں پانی کو پھاڑتی چلی جاتی ہیں۔ اور اس لئے بھی سمندر کو تمہارے اختیار میں کیا کہ تم اللہ کا فضل معاش حاصل کرو اور تاکہ اس کا شکر کرو۔', 'اور وہی ہے جس نے کام میں لگا دیا دریا کو کہ کھاؤ اس میں سے گوشت تازہ اور نکالو اس میں سے گہنا جو پہنتے ہو اور دیکھتا ہے تو کشتیوں کو چلتی ہیں پانی پھاڑ کر اسمیں (دریا میں) [۲۰] اور اس واسطے کہ تلاش کرو اسکے فضل سے اور تاکہ احسان مانو [۲۱]', 'And He it is Who has subjected the sea (to you), that you eat thereof fresh tender meat (i.e. fish), and that you bring forth out of it ornaments to wear. And you see the ships ploughing through it, that you may seek (thus) of His Bounty (by transporting the goods from place to place) and that you may be grateful.', 'He is the One who has subjugated the sea, so that you may eat fresh meat from it, and may take out from it ornaments you wear, and you see the boats cleaving through it, and so that you may seek His bounty, and that you may be grateful.'),
(1916, 16, 15, 2, 8, 14, 'رُبَمَا', 'النحل', 'وَ اَلۡقٰی فِی الۡاَرۡضِ رَوَاسِیَ اَنۡ  تَمِیۡدَ بِکُمۡ  وَ اَنۡہٰرًا وَّ سُبُلًا  لَّعَلَّکُمۡ تَہۡتَدُوۡنَ ﴿ۙ۱۵﴾', 'اور اسی نے زمین پر پہاڑ بنا کر رکھ دیئے کہ تم کو لے کر کہیں ڈولنے نہ لگے اور ندیاں اور راستے بنا دیئے تاکہ ایک مقام سے دوسرے مقام تک آسانی سے جا سکو۔', 'اور رکھ دیے زمین پر بوجھ (پہاڑ) کہ کبھی جھک پڑے تم کو لے کر [۲۲] اور بنائیں ندیاں [۲۳] اور راستے تا کہ تم راہ پاؤ [۲۴]', 'And He has affixed into the earth mountains standing firm, lest it should shake with you, and rivers and roads, that you may guide yourselves.', 'And He placed mountains on the earth, lest it should shake with you, and rivers and tracks, so that you may find the right way,'),
(1917, 16, 16, 2, 8, 14, 'رُبَمَا', 'النحل', 'وَ  عَلٰمٰتٍ ؕ وَ  بِالنَّجۡمِ  ہُمۡ  یَہۡتَدُوۡنَ ﴿۱۶﴾', 'اور رستوں میں نشانات بنا دیئے اور لوگ ستاروں سے بھی رستے معلوم کرتے ہیں۔', 'اور بنائیں (رکھیں) علامتیں [۲۵] اور ستاروں سے لوگ راہ پاتے ہیں [۲۶]', 'And landmarks (signposts, etc. during the day) and by the stars (during the night), they (mankind) guide themselves.', 'and He has set landmarks. And by the stars they find the right way.'),
(1918, 16, 17, 2, 8, 14, 'رُبَمَا', 'النحل', 'اَفَمَنۡ یَّخۡلُقُ کَمَنۡ لَّا یَخۡلُقُ ؕ اَفَلَا تَذَکَّرُوۡنَ ﴿۱۷﴾', 'تو جو اتنی مخلوقات پیدا کرے کیا وہ اس مخلوق جیسا ہو سکتا ہے جو کچھ بھی پیدا نہ کر سکے تو پھر تم غور کیوں نہیں کرتے؟', 'بھلا جو پیدا کرے برابر ہے اس کے جو کچھ نہ پیدا کرے کیا تم سوچتے نہیں [۲۷]', 'Is then He, Who creates as one who creates not? Will you not then remember?', 'Is then the One who creates (everything) equal to one who does not create? Would you still pay no heed?'),
(1919, 16, 18, 2, 8, 14, 'رُبَمَا', 'النحل', 'وَ اِنۡ تَعُدُّوۡا نِعۡمَۃَ اللّٰہِ لَا تُحۡصُوۡہَا ؕ اِنَّ  اللّٰہَ  لَغَفُوۡرٌ  رَّحِیۡمٌ ﴿۱۸﴾', 'اور اگر تم اللہ کی نعمتوں کو شمار کرنا چاہو تو گن نہ سکو۔ بیشک اللہ بخشنے والا ہے مہربان ہے۔', 'اور اگر شمار (گنو) کرو اللہ کی نعمتوں کو نہ پورا کر سکو گے ان کو [۲۸] بیشک اللہ بخشنے والا مہربان ہے [۲۹]', 'And if you would count the graces of Allah, never could you be able to count them. Truly! Allah is Oft-Forgiving, Most Merciful.', 'If you count the bounties of Allah, you cannot count them all. Surely, Allah is Most-Forgiving, Very-Merciful.'),
(1920, 16, 19, 2, 8, 14, 'رُبَمَا', 'النحل', 'وَ اللّٰہُ یَعۡلَمُ  مَا تُسِرُّوۡنَ وَ مَا  تُعۡلِنُوۡنَ ﴿۱۹﴾', 'اور جو کچھ تم چھپاتے اور جو کچھ ظاہر کرتے ہو سب سے اللہ واقف ہے۔', 'اور اللہ جانتا ہے جو تم چھپاتے ہو اور جو ظاہر کرتے ہو [۳۰]', 'And Allah knows what you conceal and what you reveal.', 'Allah knows what you conceal and what you reveal.'),
(1921, 16, 20, 2, 8, 14, 'رُبَمَا', 'النحل', 'وَ الَّذِیۡنَ یَدۡعُوۡنَ مِنۡ دُوۡنِ اللّٰہِ  لَا یَخۡلُقُوۡنَ شَیۡئًا وَّ ہُمۡ  یُخۡلَقُوۡنَ ﴿ؕ۲۰﴾', 'اور جن لوگوں کو یہ اللہ کے سوا پکارتے ہیں وہ کوئی چیز بھی تو نہیں بنا سکتے بلکہ وہ خود بنائے جاتے ہیں۔', 'اور جن کو پکارتے ہیں اللہ کے سوائے کچھ پیدا نہیں کرتے اور وہ خود پیدا کئے ہوئے ہیں [۳۱]', 'Those whom they (Al-Mushrikoon) invoke besides Allah have not created anything, but are themselves created.', 'Those whom they invoke beside Allah do not create any thing; rather they are themselves created;'),
(1922, 16, 21, 2, 8, 14, 'رُبَمَا', 'النحل', 'اَمۡوَاتٌ غَیۡرُ  اَحۡیَآءٍ ۚ وَ مَا یَشۡعُرُوۡنَ ۙ اَیَّانَ  یُبۡعَثُوۡنَ ﴿٪۲۱﴾', 'وہ تو مردہ ہیں بےجان۔ ان کو تو یہ بھی معلوم نہیں کہ اٹھائے کب جائیں گے۔', 'مردے ہیں جن میں جان نہیں [۳۲] اور نہیں جانتے کب اٹھائے جائیں گے [۳۳]', '(They are) dead, lifeless, and they know not when they will be raised up.', 'they are dead, having no life, and they do not know when they shall be raised again.'),
(1923, 16, 22, 3, 9, 14, 'رُبَمَا', 'النحل', 'اِلٰـہُکُمۡ  اِلٰہٌ  وَّاحِدٌ ۚ فَالَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِالۡاٰخِرَۃِ  قُلُوۡبُہُمۡ مُّنۡکِرَۃٌ وَّ  ہُمۡ  مُّسۡتَکۡبِرُوۡنَ ﴿۲۲﴾', 'لوگو تمہارا معبود تو ایک ہی معبود ہے۔ سو جو لوگ آخرت پر ایمان نہیں رکھتے ان کے دل انکار کر رہے ہیں اور وہ سرکش ہو رہے ہیں۔', 'معبود تمہارا معبود ہے اکیلا سو جن کو یقین نہیں آخرت کی زندگی کا ان کے دل نہیں مانتے اور وہ مغرور ہیں [۳۴]', 'Your Ilah (God) is One Ilah (God Allah, none has the right to be worshipped but He). But for those who believe not in the Hereafter, their hearts deny (the faith in the Oneness of Allah), and they are proud.', 'Your God is One God. As for those who do not believe in the Hereafter, their hearts are defiant and they are arrogant.'),
(1924, 16, 23, 3, 9, 14, 'رُبَمَا', 'النحل', 'لَاجَرَمَ  اَنَّ اللّٰہَ  یَعۡلَمُ  مَا  یُسِرُّوۡنَ وَ مَا یُعۡلِنُوۡنَ ؕ اِنَّہٗ  لَا یُحِبُّ الۡمُسۡتَکۡبِرِیۡنَ ﴿۲۳﴾', 'یہ جو کچھ چھپاتے ہیں اور جو ظاہر کرتے ہیں اللہ ضرور اس کو جانتا ہے۔ وہ سرکشوں کو ہرگز پسند نہیں کرتا۔', 'ٹھیک بات ہے کہ اللہ جانتا ہے جو کچھ چھپاتے ہیں اور جو کچھ ظاہر (جتلاتے ہیں) کرتے ہیں بیشک وہ نہیں پسند کرتا غرور کرنے والوں کو [۳۵]', 'Certainly, Allah knows what they conceal and what they reveal. Truly, He likes not the proud.', 'Invariably, Allah knows what they conceal and what they reveal. Surely, He does not like the arrogant.'),
(1925, 16, 24, 3, 9, 14, 'رُبَمَا', 'النحل', 'وَ اِذَا قِیۡلَ لَہُمۡ مَّا ذَاۤ  اَنۡزَلَ رَبُّکُمۡ ۙ قَالُوۡۤا  اَسَاطِیۡرُ  الۡاَوَّلِیۡنَ ﴿ۙ۲۴﴾', 'اور جب ان کافروں سے کہا جاتا ہے کہ تمہارے پروردگار نے کیا اتارا ہے تو کہتے ہیں پہلے لوگوں کی حکایتیں۔', 'اور جب کہے ان سےکہ کیا اتارا ہے تمہارے رب نے تو کہیں کہانیاں ہیں پہلوں کی [۳۶]', 'And when it is said to them: \"What is it that your Lord has sent down (unto Muhammad SAW)?\" They say: \"Tales of the men of old!\"', 'When it is said to them, “What has your Lord sent down?” They say, “It is nothing but the tales of the ancient people.”'),
(1926, 16, 25, 3, 9, 14, 'رُبَمَا', 'النحل', 'لِیَحۡمِلُوۡۤا اَوۡزَارَہُمۡ کَامِلَۃً یَّوۡمَ الۡقِیٰمَۃِ ۙ وَ مِنۡ اَوۡزَارِ الَّذِیۡنَ یُضِلُّوۡنَہُمۡ بِغَیۡرِ عِلۡمٍ ؕ اَلَا سَآءَ مَا یَزِرُوۡنَ ﴿٪۲۵﴾', 'اے پیغمبر ان کو بکنے دو یہ قیامت کے دن اپنے اعمال کے پورے بوجھ بھی اٹھائیں گے اور جنکو یہ بےتحقیق گمراہ کرتے ہیں انکے بوجھ بھی اٹھائیں گے سن رکھو کہ جو بوجھ یہ اٹھا رہے ہیں برے ہیں۔', 'تاکہ اٹھائیں بوجھ اپنے پورے دن قیامت کے اور کچھ بوجھ ان کے جن کو بہکاتے ہیں بلا تحقیق سنتا ہے برا بوجھ ہے جو اٹھاتے ہیں [۳۷]', 'They will bear their own burdens in full on the Day of Resurrection, and also of the burdens of those whom they misled without knowledge. Evil indeed is that which they shall bear!', 'Hence, they shall bear the full weight of their burdens on the Day of Judgment, and also some of the burdens of those whom they mislead without knowledge. Remember, evil is the burden they bear.'),
(1927, 16, 26, 4, 10, 14, 'رُبَمَا', 'النحل', 'قَدۡ مَکَرَ الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ فَاَتَی اللّٰہُ بُنۡیَانَہُمۡ مِّنَ الۡقَوَاعِدِ فَخَرَّ عَلَیۡہِمُ السَّقۡفُ مِنۡ فَوۡقِہِمۡ وَ اَتٰىہُمُ الۡعَذَابُ مِنۡ  حَیۡثُ لَا یَشۡعُرُوۡنَ ﴿۲۶﴾', 'ان سے پہلے لوگوں نے بھی ایسی ہی مکاریاں کی تھیں تو اللہ کا حکم ان کی عمارت کی بنیادوں کی طرف سے آ پہنچا اور چھت ان پر ان کے اوپر سے گر پڑی۔ اور ایسی طرف سے ان پر عذاب آ واقع ہوا جہاں سے ان کو خیال بھی نہ تھا۔', 'البتہ دغابازی کر چکے ہیں جو تھے ان سے پہلے (ان سے اگلے) پھر پہنچا حکم اللہ کا ان کی عمارت پر بنیادوں سے پھر گر پڑی ان پر چھت اوپر سے اور آیا ان پرعذاب جہاں سے ان کو خبر نہ تھی [۳۸]', 'Those before them indeed plotted, but Allah struck at the foundation of their building, and then the roof fell down upon them, from above them, and the torment overtook them from directions they did not perceive.', 'Those (too) who were before them made plots. Then (the command of) Allah came upon their buildings (uprooting them) from the foundations. So roofs fell down upon them from above, and the chastisement came to them from where they could not even imagine.'),
(1928, 16, 27, 4, 10, 14, 'رُبَمَا', 'النحل', 'ثُمَّ یَوۡمَ الۡقِیٰمَۃِ یُخۡزِیۡہِمۡ وَ یَقُوۡلُ اَیۡنَ شُرَکَآءِیَ الَّذِیۡنَ  کُنۡتُمۡ  تُشَآقُّوۡنَ فِیۡہِمۡ ؕ قَالَ الَّذِیۡنَ اُوۡتُوا الۡعِلۡمَ  اِنَّ الۡخِزۡیَ الۡیَوۡمَ  وَ السُّوۡٓءَ  عَلَی  الۡکٰفِرِیۡنَ ﴿ۙ۲۷﴾', 'پھر وہ انکو قیامت کے دن بھی ذلیل کرے گا اور کہے گا کہ میرے وہ شریک کہاں ہیں جنکے بارے میں تم جھگڑا کرتے تھے؟ جن لوگوں کو علم دیا گیا تھا وہ کہیں گے کہ آج کافروں کی رسوائی اور برائی ہے۔', 'پھر قیامت کے دن رسوا کرے گا ان کو اور کہے گا کہاں ہیں میرے شریک جن پر تم کو بڑی ضد تھی [۳۹] بولیں گے  جن کو دی گئ تھی خبر بیشک رسوائی آج کے دن اور برائی منکروں پر ہے [۴۰]', 'Then, on the Day of Resurrection, He will disgrace them and will say: \"Where are My (so called) partners concerning whom you used to disagree and dispute (with the believers, by defying and disobeying Allah)?\" Those who have been given the knowledge (about the Torment of Allah for the disbelievers) will say: \"Verily! Disgrace this Day and misery are upon the disbelievers.', 'Then, on the Day of Judgment, He will put them to disgrace and will say, “Where are My partners for whose sake you used to quarrel (with the believers)?” Those endowed with knowledge will say, “Today, the disgrace and the evil (chastisement) has to befall the unbelievers,');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1929, 16, 28, 4, 10, 14, 'رُبَمَا', 'النحل', 'الَّذِیۡنَ تَتَوَفّٰىہُمُ الۡمَلٰٓئِکَۃُ ظَالِمِیۡۤ اَنۡفُسِہِمۡ ۪ فَاَلۡقَوُا السَّلَمَ مَا کُنَّا نَعۡمَلُ مِنۡ سُوۡٓءٍ ؕ بَلٰۤی  اِنَّ اللّٰہَ عَلِیۡمٌۢ  بِمَا کُنۡتُمۡ  تَعۡمَلُوۡنَ ﴿۲۸﴾', 'ان کا حال یہ ہے کہ جب فرشتے انکی روحیں قبض کرنے لگتے ہیں جبکہ یہ اپنے ہی حق میں ظلم کرنے والے ہوتے ہیں تو مطیع و فرمانبردار ہو جاتے ہیں اور کہتے ہیں کہ ہم کوئی برائی نہیں کرتے تھے۔ ہاں جو کچھ تم کیا کرتے تھے اللہ اسے خوب جانتا ہے۔', 'جن کی جان نکالتے ہیں فرشتے اور وہ برا کر رہے ہیں اپنے حق میں [۴۱] تب ظاہر کریں گے اطاعت کہ ہم تو کرتے نہ تھے کچھ برائی [۴۲] کیوں نہیں اللہ خوب جانتا ہے جو تم کرتے تھے [۴۳]', '\"Those whose lives the angels take while they are doing wrong to themselves (by disbelief and by associating partners in worship with Allah and by committing all kinds of crimes and evil deeds).\" Then, they will make (false) submission (saying): \"We used not to do any evil.\" (The angels will reply): \"Yes! Truly, Allah is All-Knower of what you used to do.', 'the ones to whom the angels brought death while they were (still) wronging themselves.” Then, they will resort to submission, (yet will say), “We used to do nothing wrong.” (They will be answered) Why not? Allah knows well what you used to do.'),
(1930, 16, 29, 4, 10, 14, 'رُبَمَا', 'النحل', 'فَادۡخُلُوۡۤا اَبۡوَابَ جَہَنَّمَ خٰلِدِیۡنَ فِیۡہَا ؕ فَلَبِئۡسَ مَثۡوَی الۡمُتَکَبِّرِیۡنَ ﴿۲۹﴾', 'سو دوزخ کے دروازوں میں داخل ہو جاؤ۔ ہمیشہ اس میں رہو گے۔ اب تکبر کرنے والوں کا برا ٹھکانہ ہے۔', 'سو داخل ہو دروازوں میں دوزخ کے رہا کرو سدا اسی میں سو کیا برا ٹھکانا ہے غرور کرنے والوں کا', '\"So enter the gates of Hell, to abide therein, and indeed, what an evil abode will be for the arrogant.\"', 'Hence, enter the gates of Jahannam to live in it forever. So evil is the abode of the arrogant.'),
(1931, 16, 30, 4, 10, 14, 'رُبَمَا', 'النحل', 'وَ  قِیۡلَ لِلَّذِیۡنَ اتَّقَوۡا مَاذَاۤ  اَنۡزَلَ رَبُّکُمۡ ؕ قَالُوۡا  خَیۡرًا ؕ لِلَّذِیۡنَ  اَحۡسَنُوۡا فِیۡ ہٰذِہِ  الدُّنۡیَا حَسَنَۃٌ ؕ وَ لَدَارُ الۡاٰخِرَۃِ خَیۡرٌ ؕ وَ لَنِعۡمَ  دَارُ الۡمُتَّقِیۡنَ ﴿ۙ۳۰﴾', 'اور جب پرہیزگاروں سے پوچھا جاتا ہے کہ تمہارے پروردگار نے کیا نازل کیا ہے۔ تو کہتے ہیں کہ بہترین کلام جو لوگ نیکوکار ہیں انکے لئے اس دنیا میں بھی بھلائی ہے اور آخرت کا گھر تو بہت ہی اچھا ہے اور پرہیزگاروں کا گھر بہت خوب ہے۔', 'اور کہا پرہیزگاروں کو کیا اتارا تمہارے رب نے بولے نیک بات جنہوں نے بھلائی کی اس دنیا میں انکو بھلائی ہے[۴۴] اور آخرت کا گھر بہتر ہے اور کیا خوب گھر ہے پرہیزگاروں کا [۴۵]', 'And (when) it is said to those who are the Muttaqoon (pious - see V.2:2) \"What is it that your Lord has sent down?\" They say: \"That which is good.\" For those who do good in this world, there is good, and the home of the Hereafter will be better. And excellent indeed will be the home (i.e. Paradise) of the Muttaqoon (pious - see V.2:2).', 'And (on the other hand,) it is said to the God-fearing, “What has your Lord sent down?” They say, “(He has sent down) excellent (discourse).” For those who do good, there is good (end) in this world, and indeed the abode of the Hereafter is much better. Excellent is the abode of the God-fearing -'),
(1932, 16, 31, 4, 10, 14, 'رُبَمَا', 'النحل', 'جَنّٰتُ عَدۡنٍ یَّدۡخُلُوۡنَہَا تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ  لَہُمۡ  فِیۡہَا مَا یَشَآءُوۡنَ ؕ   کَذٰلِکَ یَجۡزِی  اللّٰہُ   الۡمُتَّقِیۡنَ ﴿ۙ۳۱﴾', 'وہ بہشت جاودانی جن میں وہ داخل ہوں گے انکے نیچے نہریں بہ رہی ہیں وہاں جو چاہیں گے انکے لئے میسر ہو گا۔ اللہ پرہیزگاروں کو ایسا ہی بدلہ دیتا ہے۔', 'باغ ہیں ہمیشہ رہنے کے جن میں وہ جائیں گے بہتی ہیں ان کے نیچے نہریں ان کے واسطے وہاں ہے جو چاہیں [۴۶] ایسا بدلہ دے گا اللہ پرہیزگاروں کو [۴۷]', 'Adn (Eden) Paradise (Gardens of Eternity) which they will enter, under which rivers flow, they will have therein all that they wish. Thus Allah rewards the Muttaqoon (pious - see V.2:2).', 'the eternal gardens they enter, with rivers flowing beneath them. For them there is what they desire. That is how Allah rewards the God-fearing -'),
(1933, 16, 32, 4, 10, 14, 'رُبَمَا', 'النحل', 'الَّذِیۡنَ تَتَوَفّٰىہُمُ الۡمَلٰٓئِکَۃُ  طَیِّبِیۡنَ ۙ یَقُوۡلُوۡنَ سَلٰمٌ عَلَیۡکُمُ ۙ ادۡخُلُوا الۡجَنَّۃَ  بِمَا کُنۡتُمۡ  تَعۡمَلُوۡنَ ﴿۳۲﴾', 'انکی کیفیت یہ ہے کہ جب فرشتے انکی جانیں نکالنے لگتے ہیں۔ اور یہ کفر و شرک سے پاک ہوتے ہیں تو سلام علیکم کہتے ہیں اور کہتے ہیں کہ جو عمل تم کیا کرتے تھے انکے بدلے میں بہشت میں داخل ہو جاؤ۔', 'جن کی جان قبض کرتے ہیں فرشتے اور وہ ستھری ہیں [۴۸] کہتےہیں فرشتے سلامتی تم پر جاؤ بہشت میں [۴۹] بدلہ ہے اس کا جو تم کرتے تھے [۵۰]', 'Those whose lives the angels take while they are in a pious state (i.e. pure from all evil, and worshipping none but Allah Alone) saying (to them): Salamun Alaikum (peace be on you) enter you Paradise, because of (the good) which you used to do (in the world).\"', 'the ones to whom angels bring death while they are pure (in beliefs and deeds). They (angels) say, “Peace on you! Enter Paradise for the deeds you have been doing.”'),
(1934, 16, 33, 4, 10, 14, 'رُبَمَا', 'النحل', 'ہَلۡ یَنۡظُرُوۡنَ  اِلَّاۤ  اَنۡ  تَاۡتِیَہُمُ الۡمَلٰٓئِکَۃُ  اَوۡ یَاۡتِیَ  اَمۡرُ رَبِّکَ ؕ کَذٰلِکَ فَعَلَ الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ ؕ وَ مَا ظَلَمَہُمُ اللّٰہُ وَ لٰکِنۡ کَانُوۡۤا اَنۡفُسَہُمۡ یَظۡلِمُوۡنَ ﴿۳۳﴾', 'کیا یہ کافر اس بات کے منتظر ہیں کہ فرشتے انکے پاس جان نکالنے آئیں یا تمہارے پروردگار کا حکم عذاب آ پہنچے۔ اسی طرح ان لوگوں نے کیا تھا جو ان سے پہلے تھے اور اللہ نے ان پر ظلم نہیں کیا۔ بلکہ وہ خود اپنے آپ پر ظلم کرتے تھے۔', 'کیا کافر اب اس کے منتظر ہیں کہ آئیں ان پر فرشتے یا پہنچے حکم تیرے رب کا [۵۱] اسی طرح کیا تھا ان سے اگلوں نے اور اللہ نے ظلم نہ کیا ان پر لیکن وہ خود اپنا برا کرتے رہے', 'Do they (the disbelievers and polytheists) await but that the angels should come to them (to take away their souls (at death)), or there should come the command (i.e. the torment or the Day of Resurrection) of your Lord? Thus did those before them. And Allah wronged them not, but they used to wrong themselves.', 'They (the unbelievers) are waiting for nothing but that the angels should come to them, or comes the command of your Lord. Similar was the reaction of those who were before them. Allah did not wrong them; rather they were doing wrong to themselves.'),
(1935, 16, 34, 4, 10, 14, 'رُبَمَا', 'النحل', 'فَاَصَابَہُمۡ سَیِّاٰتُ مَا عَمِلُوۡا وَ حَاقَ بِہِمۡ مَّا کَانُوۡا بِہٖ یَسۡتَہۡزِءُوۡنَ ﴿٪۳۴﴾', 'تو انکو انکے اعمال کے برے بدلے ملے اور جس چیز کے ساتھ وہ ٹھٹھے کیا کرتے تھے اس نے انکو ہر طرف سے گھیر لیا۔', 'پھر پڑے ان کے سر ان کے برے کام اور الٹ پڑا ان پر جو ٹھٹھا کرتے تھے [۵۲]', 'Then, the evil results of their deeds overtook them, and that at which they used to mock surrounded them.', 'So, the evils of what they did overtook them, and they were encircled by the very thing they used to ridicule.'),
(1936, 16, 35, 5, 11, 14, 'رُبَمَا', 'النحل', 'وَ قَالَ الَّذِیۡنَ اَشۡرَکُوۡا لَوۡ شَآءَ اللّٰہُ مَا عَبَدۡنَا مِنۡ دُوۡنِہٖ مِنۡ شَیۡءٍ نَّحۡنُ وَ لَاۤ اٰبَآؤُنَا وَ لَا حَرَّمۡنَا مِنۡ دُوۡنِہٖ مِنۡ شَیۡءٍ ؕ  کَذٰلِکَ  فَعَلَ  الَّذِیۡنَ  مِنۡ  قَبۡلِہِمۡ ۚ فَہَلۡ عَلَی الرُّسُلِ  اِلَّا الۡبَلٰغُ  الۡمُبِیۡنُ ﴿۳۵﴾', 'اور مشرک کہتے ہیں کہ اگر اللہ چاہتا تو نہ ہم ہی اسکے سوا کسی چیز کو پوجتے اور نہ ہمارے بڑے ہی پوجتے اور نہ اسکے فرمان کے بغیر ہم کسی چیز کو حرام ٹھہراتے اے پیغمبر اسی طرح ان سے اگلے لوگوں نے کیا تھا۔ تو پیغمبروں کے ذمے اللہ کے احکام کو کھول کر سنا دینے کے سوا اور کچھ نہیں۔', 'اور بولے شرک کرنے والے اگر چاہتا اللہ نہ پوجتے ہم اس کےسوا کسی چیز کو اور نہ ہمارے باپ اور نہ حرام ٹھہرا لیتے ہم بدون اسکے حکم کے کسی چیز کو [۵۳] اسی طرح کیا ان سے اگلوں نے سو رسولوں کے ذمہ نہیں مگر پہنچا دینا صاف صاف [۵۴]', 'And those who join others in worship with Allah say: \"If Allah had so willed, neither we nor our fathers would have worshipped aught but Him, nor would we have forbidden anything without (Command from) Him.\" So did those before them. Then! Are the Messengers charged with anything but to convey clearly the Message?', 'The polytheists said, “If Allah had so willed, we would have not worshipped anything other than Him - neither we nor our forefathers - nor would we have made anything unlawful without (a command from) Him.” Similar was the reaction of those who were before them. Therefore, the messengers’ obligation is no more than to convey the message clearly.'),
(1937, 16, 36, 5, 11, 14, 'رُبَمَا', 'النحل', 'وَ لَقَدۡ بَعَثۡنَا فِیۡ کُلِّ اُمَّۃٍ  رَّسُوۡلًا اَنِ اعۡبُدُوا اللّٰہَ  وَ اجۡتَنِبُوا الطَّاغُوۡتَ ۚ فَمِنۡہُمۡ مَّنۡ ہَدَی اللّٰہُ وَ مِنۡہُمۡ مَّنۡ حَقَّتۡ عَلَیۡہِ  الضَّلٰلَۃُ ؕ فَسِیۡرُوۡا فِی الۡاَرۡضِ فَانۡظُرُوۡا کَیۡفَ کَانَ عَاقِبَۃُ  الۡمُکَذِّبِیۡنَ ﴿۳۶﴾', 'اور ہم نے ہر امت میں کوئی پیغمبر بھیجا کہ اللہ ہی کی عبادت کرو اور بتوں کی پرستش سے اجتناب کرو۔ تو ان میں بعض ایسے ہیں جنکو اللہ نے ہدایت دی اور بعض ایسے ہیں جن پر گمراہی ثابت ہوئی سو زمین میں چل پھر کر دیکھ لو کہ جھٹلانے والوں کا انجام کیسا ہوا۔', 'اور ہم نے اٹھائے ہیں (بھیجے ہیں) ہر امت میں رسول [۵۵] کہ بندگی کرو اللہ کی اور بچو ہڑونگے سے (جھوٹے معبودوں سے) [۵۶] پھر کسی کو ان میں سے ہدایت کی (راہ سمجھائی) اللہ نے اور کسی پر ثابت ہوئی گمراہی سو سفر کرو (چلو پھرو زمین میں) ملکوں میں پھر دیکھو کیا ہوا انجام جھٹلانے والوں کا', 'And verily, We have sent among every Ummah (community, nation) a Messenger (proclaiming): \"Worship Allah (Alone), and avoid (or keep away from) Taghoot (all false deities, etc. i.e. do not worship Taghoot besides Allah).\" Then of them were some whom Allah guided and of them were some upon whom the straying was justified. So travel through the land and see what was the end of those who denied (the truth).', 'We did raise a messenger among every people, with the message: “Worship Allah and stay away from the Rebel (the Satan).” Then, there were some among them whom Allah guided, and there were others against whom deviation (from the right path) was established. So, travel on earth and see how was the fate of those who rejected (the prophets).'),
(1938, 16, 37, 5, 11, 14, 'رُبَمَا', 'النحل', 'اِنۡ تَحۡرِصۡ عَلٰی ہُدٰىہُمۡ فَاِنَّ اللّٰہَ  لَا یَہۡدِیۡ مَنۡ یُّضِلُّ وَ مَا لَہُمۡ  مِّنۡ نّٰصِرِیۡنَ ﴿۳۷﴾', 'اگر تم ان کفار کی ہدایت کے لئے بہت زیادہ خواہش رکھو جس کو اللہ گمراہ رہنے دے اس کو وہ ہدایت نہیں دیا کرتا اور ایسے لوگوں کا کوئی مددگار بھی نہیں ہوتا۔', 'اگر تو طمع کرے انکو راہ پر لانے کی تو اللہ راہ نہیں دیتا جن کو بچلاتا ہے اور کوئی نہیں ان کا مددگار [۵۷]', 'If you (O Muhammad SAW) covet for their guidance, then verily Allah guides not those whom He makes to go astray (or none can guide him whom Allah sends astray). And they will have no helpers.', 'If you are keen for their guidance, then, (remember that) Allah does not lead those to the right path whom He lets go astray, and for them there are no helpers.'),
(1939, 16, 38, 5, 11, 14, 'رُبَمَا', 'النحل', 'وَ اَقۡسَمُوۡا بِاللّٰہِ جَہۡدَ اَیۡمَانِہِمۡ ۙ لَا یَبۡعَثُ اللّٰہُ مَنۡ یَّمُوۡتُ ؕ بَلٰی وَعۡدًا عَلَیۡہِ حَقًّا وَّ لٰکِنَّ  اَکۡثَرَ  النَّاسِ لَا  یَعۡلَمُوۡنَ ﴿ۙ۳۸﴾', 'اور یہ اللہ کی سخت سخت قسمیں کھاتے ہیں کہ جو مر جاتا ہے اللہ اسے  زندہ کر کے نہیں اٹھائے گا۔ کیوں نہیں۔ یہ اللہ کا وعدہ سچا ہے اور اس کا پورا کرنا اسے ضرور ہے لیکن اکثر لوگ نہیں جانتے۔', 'اور قسمیں کھاتے ہیں اللہ کی سخت قسمیں کہ نہ اٹھائے گا اللہ جو کوئی مر جائے [۵۸] کیوں نہیں (بیشک اٹھائے گا) وعدہ ہو چکا ہے اس پر پکا لیکن اکثر لوگ نہیں جانتے [۵۹]', 'And they swear by Allah their strongest oaths, that Allah will not raise up him who dies. Yes, (He will raise them up), a promise (binding) upon Him in truth, but most of mankind know not.', 'They swore by Allah on solemn oaths: “Allah will not resurrect those who die.” Why not? It is a promise on His part, which is due to come true, but most of the people do not know.'),
(1940, 16, 39, 5, 11, 14, 'رُبَمَا', 'النحل', 'لِیُبَیِّنَ لَہُمُ الَّذِیۡ یَخۡتَلِفُوۡنَ فِیۡہِ وَ لِیَعۡلَمَ الَّذِیۡنَ کَفَرُوۡۤا اَنَّہُمۡ کَانُوۡا کٰذِبِیۡنَ ﴿۳۹﴾', 'تاکہ جن باتوں میں یہ اختلاف کرتے ہیں وہ ان پر ظاہر کر دے اور اس لئے کہ کافر جان لیں کہ وہ جھوٹے تھے۔', 'اٹھائے گا تاکہ ظاہر کر دے ان پر جس بات میں کہ جھگڑتے ہیں اور تاکہ معلوم کر لیں کافر کہ وہ جھوٹے تھے [۶۰]', 'In order that He may make manifest to them the truth of that wherein they differ, and that those who disbelieved (in Resurrection, and in the Oneness of Allah) may know that they were liars.', '(He will resurrect all of them,) so that He discloses for them what they have been disputing about, and so that those who disbelieve may know that they were liars.'),
(1941, 16, 40, 5, 11, 14, 'رُبَمَا', 'النحل', 'اِنَّمَا قَوۡلُنَا لِشَیۡءٍ   اِذَاۤ   اَرَدۡنٰہُ اَنۡ نَّقُوۡلَ  لَہٗ   کُنۡ  فَیَکُوۡنُ ﴿٪۴۰﴾', 'جب ہم کسی چیز کا ارادہ کرتے ہیں تو ہماری بات یہی ہوتی ہے کہ اسکو کہہ دیتے ہیں کہ ہو جا تو وہ ہو جاتی ہے۔', 'ہمارا کہنا کسی چیز کو جب ہم اس کو کرنا چاہیں یہی ہے کہ کہیں اس کو ہو جا تو وہ ہو جائے [۶۱]', 'Verily! Our Word unto a thing when We intend it, is only that We say unto it: \"Be!\" and it is.', 'Whenever We intend to do something, We do no more than say to it, “Be,” and it comes to be.'),
(1942, 16, 41, 6, 12, 14, 'رُبَمَا', 'النحل', 'وَ الَّذِیۡنَ ہَاجَرُوۡا فِی اللّٰہِ  مِنۡۢ  بَعۡدِ مَا ظُلِمُوۡا لَـنُبَوِّئَنَّہُمۡ فِی الدُّنۡیَا حَسَنَۃً ؕ وَ لَاَجۡرُ الۡاٰخِرَۃِ  اَکۡبَرُ ۘ لَوۡ کَانُوۡا یَعۡلَمُوۡنَ ﴿ۙ۴۱﴾', 'اور جن لوگوں نے ظلم سہنے کے بعد اللہ کے لئے وطن چھوڑا ہم ان کو دنیا میں اچھا ٹھکانہ دیں گے اور آخرت کا اجر تو بہت بڑا ہے۔ کاش وہ اسے جانتے۔', 'اور جنہوں نے گھر چھوڑا اللہ کے واسطے بعد اس کے کہ ظلم اٹھایا البتہ انکو ہم ٹھکانا دیں گے دنیا میں اچھا اور ثواب آخرت کا تو بہت بڑا ہے اگر ان کو معلوم ہوتا [۶۲]', 'And as for those who emigrated for the Cause of Allah, after suffering oppression, We will certainly give them goodly residence in this world, but indeed the reward of the Hereafter will be greater, if they but knew!', 'Those who have migrated for the sake of Allah after they were oppressed, We shall give them a good place in the world, 6 and of course, the reward of the Hereafter is much greater, if they only knew!'),
(1943, 16, 42, 6, 12, 14, 'رُبَمَا', 'النحل', 'الَّذِیۡنَ صَبَرُوۡا وَ عَلٰی رَبِّہِمۡ یَتَوَکَّلُوۡنَ ﴿۴۲﴾', 'یعنی وہ لوگ جو صبر کرتے ہیں اور اپنے پروردگار پر بھروسا رکھتے ہیں۔', 'جو ثابت قدم رہے اور اپنے رب پر بھروسہ کیا [۶۳]', '(They are) those who remained patient (in this world for Allahs sake), and put their trust in their Lord (Allah Alone).', '- those who kept patient, and who place trust in their Lord.'),
(1944, 16, 43, 6, 12, 14, 'رُبَمَا', 'النحل', 'وَ مَاۤ  اَرۡسَلۡنَا مِنۡ قَبۡلِکَ اِلَّا رِجَالًا نُّوۡحِیۡۤ  اِلَیۡہِمۡ فَسۡـَٔلُوۡۤا اَہۡلَ الذِّکۡرِ  اِنۡ کُنۡتُمۡ  لَا  تَعۡلَمُوۡنَ ﴿ۙ۴۳﴾', 'اور ہم نے تم سے پہلے مردوں ہی کو پیغمبر بنا کر بھیجا تھا جنکی طرف ہم وحی بھیجا کرتے تھے اگر تم لوگ نہیں جانتے تو اہل کتاب سے پوچھ لو۔', 'اور تجھ سے پہلے بھی ہم نے یہی مرد بھیجے تھے کہ حکم بھیجتے تھے ہم انکی طرف سو پوچھو یاد رکھنے والوں سے اگر تم کو معلوم نہیں [۶۴]', 'And We sent not (as Our Messengers) before you (O Muhammad SAW) any but men, whom We inspired, (to preach and invite mankind to believe in the Oneness of Allah). So ask of those who know the Scripture (learned men of the Taurat (Torah) and the Injeel (Gospel)), if you know not.', 'We did not send (messengers) before you other than men whom We inspired with revelation. So, ask the people (having the knowledge) of the Reminder (the earlier Scriptures), if you do not know.'),
(1945, 16, 44, 6, 12, 14, 'رُبَمَا', 'النحل', 'بِالۡبَیِّنٰتِ وَ الزُّبُرِ ؕ وَ اَنۡزَلۡنَاۤ  اِلَیۡکَ الذِّکۡرَ  لِتُبَیِّنَ  لِلنَّاسِ مَا نُزِّلَ  اِلَیۡہِمۡ وَ لَعَلَّہُمۡ  یَتَفَکَّرُوۡنَ ﴿۴۴﴾', 'اور ان پیغمبروں کو دلیلیں اور کتابیں دے کر بھیجا تھا اور ہم نے تم پر بھی یہ کتاب نازل کی ہے تاکہ جو ارشادات لوگوں پر نازل ہوئے ہیں وہ ان پر ظاہر کر دو۔ اور تاکہ وہ غور کریں۔', 'بھیجا تھا انکو نشانیاں دے کر اور ورقے (اوراق) [۶۵] اور اتاری ہم نے تجھ پر یہ یاداشت کہ تو کھول دے لوگوں کے سامنے وہ چیز جو اتری انکے واسطے [۶۶] تاکہ وہ غور (دھیان) کریں [۶۷]', 'With clear signs and Books (We sent the Messengers). And We have also sent down unto you (O Muhammad SAW) the reminder and the advice (the Quran), that you may explain clearly to men what is sent down to them, and that they may give thought.', '(We sent them) with clear signs and scriptures. And We sent down the Reminder (The Qur’ān) to you, so that you explain to the people what has been revealed for them, and so that they may ponder.'),
(1946, 16, 45, 6, 12, 14, 'رُبَمَا', 'النحل', 'اَفَاَمِنَ الَّذِیۡنَ مَکَرُوا السَّیِّاٰتِ اَنۡ یَّخۡسِفَ اللّٰہُ بِہِمُ الۡاَرۡضَ اَوۡ یَاۡتِیَہُمُ الۡعَذَابُ  مِنۡ  حَیۡثُ لَا  یَشۡعُرُوۡنَ ﴿ۙ۴۵﴾', 'اب کیا جو لوگ بری بری چالیں چلتے ہیں اس بات سے بےخوف ہیں کہ اللہ انکو زمین میں دھنسا دے یا ایسی طرف سے ان پر عذاب آ جائے جہاں سے انکو خبر ہی نہ ہو۔', 'سو کیا نڈر ہو گئے وہ لوگ جو برے فریب (داؤ) کرتے ہیں اس سے کہ دھنسا دیوے اللہ ان کو زمین میں یا آ پہنچے ان پر عذاب جہاں سے خبر نہ رکھتے ہوں [۶۸]', 'Do then those who devise evil plots feel secure that Allah will not sink them into the earth, or that the torment will not seize them from directions they perceive not?', 'Do those who contrive evil plots feel immune from that Allah makes them sink into the earth, or from that the punishment comes to them from where they would not perceive,'),
(1947, 16, 46, 6, 12, 14, 'رُبَمَا', 'النحل', 'اَوۡ یَاۡخُذَہُمۡ فِیۡ تَقَلُّبِہِمۡ فَمَا ہُمۡ بِمُعۡجِزِیۡنَ ﴿ۙ۴۶﴾', 'یا انکو چلتے پھرتے پکڑ لے تو وہ اللہ کو عاجز نہیں کر سکتے۔', 'یا پکڑ لے ان کو چلتے پھرتے سو وہ نہیں ہیں عاجز کرنے والے [۶۹]', 'Or that He may catch them in the midst of their going to and fro (in their jobs), so that there be no escape for them (from Allahs Punishment)?', 'or that He seizes them when roaming about - while they are not able to frustrate Him -'),
(1948, 16, 47, 6, 12, 14, 'رُبَمَا', 'النحل', 'اَوۡ یَاۡخُذَہُمۡ عَلٰی تَخَوُّفٍ ؕ فَاِنَّ رَبَّکُمۡ لَرَءُوۡفٌ  رَّحِیۡمٌ ﴿۴۷﴾', 'یا جب انکو عذاب کا ڈر پیدا ہو گیا ہو تو ان کو پکڑ لے بیشک تمہارا پروردگار بہت شفقت کرنے والا ہے مہربان ہے۔', 'یا پکڑ لے ان کو ڈرانے کے بعد (ڈرا کر)  [۷۰] سو تمہارا رب بڑا نرم ہے مہربان [۷۱]', 'Or that He may catch them with gradual wasting (of their wealth and health). Truly! Your Lord is indeed full of Kindness, Most Merciful?', 'or that He seizes them while they are in apprehension? So, indeed your Lord is Very-Kind, Very-Merciful.'),
(1949, 16, 48, 6, 12, 14, 'رُبَمَا', 'النحل', 'اَوَ لَمۡ  یَرَوۡا  اِلٰی مَا خَلَقَ اللّٰہُ  مِنۡ  شَیۡءٍ یَّتَفَیَّؤُا ظِلٰلُہٗ عَنِ الۡیَمِیۡنِ وَ الشَّمَآئِلِ سُجَّدًا  لِّلّٰہِ  وَ  ہُمۡ   دٰخِرُوۡنَ ﴿۴۸﴾', 'کیا ان لوگوں نے اللہ کی مخلوقات میں سے ایسی چیزیں نہیں دیکھیں جنکے سائے دائیں سے بائیں کو اور بائیں سے دائیں کو لوٹتے رہتے ہیں یعنی اللہ کے آگے عاجزی سے سجدے کی حالت میں رہتے ہیں۔', 'کیا نہیں دیکھتے وہ جو کہ اللہ نے پیدا کی ہے کوئی چیز کہ ڈھلتے ہیں سایے ان کے داہنی طرف سے اور بائیں طرف سے سجدہ کرتے ہوئے اللہ کو اور وہ عاجزی میں ہیں [۷۲]', 'Have they not observed things that Allah has created, (how) their shadows incline to the right and to the left, making prostration unto Allah, and they are lowly?', 'Have they not observed the things Allah has created, their shadows inclining from the right and the left prostrating themselves before Allah, while they are humble?'),
(1950, 16, 49, 6, 12, 14, 'رُبَمَا', 'النحل', 'وَ لِلّٰہِ یَسۡجُدُ  مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ مِنۡ دَآبَّۃٍ وَّ الۡمَلٰٓئِکَۃُ وَ ہُمۡ  لَا یَسۡتَکۡبِرُوۡنَ ﴿۴۹﴾', 'اور تمام جاندار جو آسمانوں میں ہیں اور جو زمین میں ہیں سب اللہ کے آگے سجدہ کرتے ہیں اور فرشتے بھی۔ اور وہ ذرا غرور نہیں کرتے۔', 'اور اللہ کو سجدہ کرتا ہے جو آسمان میں ہے اور جو زمین میں ہے جانداروں سے اور فرشتے اور وہ تکبر نہیں کرتے [۷۳]', 'And to Allah prostate all that is in the heavens and all that is in the earth, of the live moving creatures and the angels, and they are not proud (i.e. they worship their Lord (Allah) with humility).', 'To Allah prostrates itself whatever creature there is in the heavens and in the earth, and the angels, and they show no arrogance.'),
(1951, 16, 50, 6, 12, 14, 'رُبَمَا', 'النحل', 'یَخَافُوۡنَ رَبَّہُمۡ مِّنۡ فَوۡقِہِمۡ وَ یَفۡعَلُوۡنَ مَا  یُؤۡمَرُوۡنَ ﴿٪ٛ۵۰﴾', 'اور اپنے پروردگار سے جو انکے اوپر ہے ڈرتے ہیں اور جو انکو ارشاد ہوتا ہے اس پر عمل کرتے ہیں۔', 'ڈر رکھتے ہیں اپنے رب کا اپنے اوپر سے اور کرتے ہیں جو حکم پاتے ہیں [۷۴]', 'They fear their Lord above them, and they do what they are commanded.', 'They fear their Lord above them and do as they are commanded.'),
(1952, 16, 51, 7, 13, 14, 'رُبَمَا', 'النحل', 'وَ قَالَ اللّٰہُ  لَا تَتَّخِذُوۡۤا  اِلٰـہَیۡنِ  اثۡنَیۡنِ ۚ اِنَّمَا ہُوَ  اِلٰہٌ  وَّاحِدٌ ۚ فَاِیَّایَ فَارۡہَبُوۡنِ ﴿۵۱﴾', 'اور اللہ نے فرمایا ہے کہ دو دو معبود نہ بناؤ معبود تو وہی ایک ہے سو اے بندو مجھی سے ڈرتے رہو۔', 'اور کہا ہے اللہ نے مت پکڑو معبود دو وہ معبود ایک ہی ہے سو مجھ سے ڈرو [۷۵]', 'And Allah said (O mankind!): \"Take not ilahaeen (two gods in worship, etc.). Verily, He (Allah) is (the) only One Ilah (God). Then, fear Me (Allah Ìá ÌáÇáå) much (and Me (Alone), i.e. be away from all kinds of sins and evil deeds that Allah has forbidden and do all that Allah has ordained and worship none but Allah).', 'Allah has said, “Do not take two gods. He is but One God. So, Me alone you fear.”'),
(1953, 16, 52, 7, 13, 14, 'رُبَمَا', 'النحل', 'وَ لَہٗ  مَا فِی السَّمٰوٰتِ وَ الۡاَرۡضِ وَ لَہُ الدِّیۡنُ وَاصِبًا ؕ اَفَغَیۡرَ اللّٰہِ تَتَّقُوۡنَ ﴿۵۲﴾', 'اور جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب اسی کا ہے اور اسی کی عبادت لازم ہے تو تم اللہ کے سوا اوروں سے کیوں ڈرتے ہو؟', 'اور اسی کا ہے جو کچھ ہے آسمانوں میں اور زمین میں اور اسی کی عبادت ہے (اسی کا انصاف) ہمیشہ [۷۶] سو کیا سوائے اللہ کے کسی سے ڈرتے ہو (خطرہ رکھتے ہو)', 'To Him belongs all that is in the heavens and (all that is in) the earth and Ad-Din Wasiba is His ((i.e. perpetual sincere obedience to Allah is obligatory). None has the right to be worshipped but Allah)). Will you then fear any other than Allah?', 'And to Him belongs what is in the heavens and the earth, and it is only He who deserves obedience as ever due. Would you, then, fear someone other than Allah?'),
(1954, 16, 53, 7, 13, 14, 'رُبَمَا', 'النحل', 'وَ مَا بِکُمۡ مِّنۡ نِّعۡمَۃٍ فَمِنَ اللّٰہِ ثُمَّ  اِذَا مَسَّکُمُ  الضُّرُّ  فَاِلَیۡہِ  تَجۡـَٔرُوۡنَ ﴿ۚ۵۳﴾', 'اور جو نعمتیں تم کو میسر ہیں سب اللہ کی طرف سے ہیں۔ پھر جب تم کو کوئی تکلیف پہنچتی ہے تو اسی کے آگے فریاد کرتے ہو۔', 'اور جو کچھ تمہارے پاس ہے نعمت سو اللہ کی طرف سے پھر جب پہنچتی ہے تم کو سختی تو اسی کی طرف چلاتے ہو (اسی سے فریاد کرتے ہو) [۷۷]', 'And whatever of blessings and good things you have, it is from Allah. Then, when harm touches you, unto Him you cry aloud for help.', 'Whatever blessing you have is from Allah. Then, once you are touched by distress, to Him alone you cry for help.'),
(1955, 16, 54, 7, 13, 14, 'رُبَمَا', 'النحل', 'ثُمَّ  اِذَا کَشَفَ الضُّرَّ عَنۡکُمۡ  اِذَا فَرِیۡقٌ  مِّنۡکُمۡ  بِرَبِّہِمۡ  یُشۡرِکُوۡنَ ﴿ۙ۵۴﴾', 'پھر جب وہ تم سے تکلیف کو دور کر دیتا ہے تو کچھ لوگ تم میں سے اللہ کے ساتھ شریک کرنے لگتے ہیں۔', 'پھر جب کھول دیتا ہے سختی تم سے اسی وقت ایک فرقہ تم میں سے اپنے رب کے ساتھ لگتا ہے شریک بتانے', 'Then, when He has removed the harm from you, behold! Some of you associate others in worship with their Lord (Allah).', 'Then, as soon as He removes the distress from you, a group from among you starts ascribing partners to their Lord.'),
(1956, 16, 55, 7, 13, 14, 'رُبَمَا', 'النحل', 'لِیَکۡفُرُوۡا بِمَاۤ  اٰتَیۡنٰہُمۡ ؕ فَتَمَتَّعُوۡا ۟ فَسَوۡفَ تَعۡلَمُوۡنَ ﴿۵۵﴾', 'تاکہ جو نعمتیں ہم نے انکو عطا فرمائی ہیں انکی ناشکری کریں تو مشرکو دنیا میں فائدے اٹھا لو۔ پھر عنقریب تم کو اس کا انجام معلوم ہو جائے گا۔', 'تاکہ منکر ہو جائیں اس چیز سے جو کہ ہم نے انکو دی ہے سو مزے اڑا لو آخر معلوم کر لو گے [۷۸]', 'So (as a result of that ) they deny (with ungratefulness) that (Allahs Favours) which We have bestowed on them! Then enjoy yourselves (your short stay), but you will come to know (with regrets).', 'Thus, they deny what We have given to them. Well, enjoy yourself (for some time), and soon you will come to know (the fate of your misdeeds).'),
(1957, 16, 56, 7, 13, 14, 'رُبَمَا', 'النحل', 'وَ یَجۡعَلُوۡنَ لِمَا لَا یَعۡلَمُوۡنَ نَصِیۡبًا مِّمَّا رَزَقۡنٰہُمۡ ؕ تَاللّٰہِ  لَتُسۡـَٔلُنَّ عَمَّا کُنۡتُمۡ تَفۡتَرُوۡنَ ﴿۵۶﴾', 'اور ہمارے دیئے ہوئے مال میں سے ایسی چیزوں کا حصہ مقرر کرتے ہیں جنکو جانتے ہی نہیں کافرو اللہ کی قسم کہ جو تم جھوٹ باندھا کرتے ہو اسکی تم سے ضرور پرسش ہو گی۔', 'اور ٹھہراتے ہیں ان کے لئے جن کی خبر نہیں رکھتے (جن کو خبر نہیں) ایک حصہ ہماری دی ہوئی روزی میں سے [۷۹] قسم اللہ کی تم سے پوچھنا ہے جو تم بہتان باندھتے ہو [۸۰]', 'And they assign a portion of that which We have provided them unto what they know not (false deities). By Allah, you shall certainly be questioned about (all) that you used to fabricate.', 'They allocate a share from what We have given to them for those (idols) the reality of whom they do not even know. By Allah, you shall definitely be responsible for the fabrications you have been inventing.'),
(1958, 16, 57, 7, 13, 14, 'رُبَمَا', 'النحل', 'وَ یَجۡعَلُوۡنَ لِلّٰہِ الۡبَنٰتِ سُبۡحٰنَہٗ ۙ وَ لَہُمۡ مَّا یَشۡتَہُوۡنَ ﴿۵۷﴾', 'اور یہ لوگ اللہ کے لئے تو بیٹیاں تجویز کرتے ہیں وہ پاک ہے اور اپنے لئے بیٹے جو مرغوب و دلپسند ہیں۔', 'اور ٹھہراتے ہیں اللہ کے لئے بیٹیاں وہ اس سے پاک ہے (لائق نہیں) [۸۱] اور اپنے لئے جو دل چاہتا ہے [۸۲]', 'And they assign daughters unto Allah! Glorified (and Exalted) be He above all that they associate with Him! . And unto themselves what they desire;', 'They ascribe daughters to Allah - Pure is He - and for themselves is what they desire!'),
(1959, 16, 58, 7, 13, 14, 'رُبَمَا', 'النحل', 'وَ اِذَا بُشِّرَ اَحَدُہُمۡ بِالۡاُنۡثٰی ظَلَّ  وَجۡہُہٗ  مُسۡوَدًّا  وَّ ہُوَ کَظِیۡمٌ ﴿ۚ۵۸﴾', 'اور جب ان میں سے کسی کو بیٹی کے پیدا ہونے کی خبر ملتی ہے تو اس کا منہ غم کے سبب کالا پڑ جاتا ہے اور وہ اندر ہی اندر گھٹنے لگتا ہے۔', 'اور جب خوشخبری ملے ان میں کسی کو بیٹی کی سارے دن رہے منہ اس کا سیاہ اور جی میں گھٹتا رہے [۸۳]', 'And when the news of (the birth of) a female (child) is brought to any of them, his face becomes dark, and he is filled with inward grief!', 'When one of them is given the good news of a female child, his face becomes gloomy and he is choked with grief.'),
(1960, 16, 59, 7, 13, 14, 'رُبَمَا', 'النحل', 'یَتَوَارٰی مِنَ الۡقَوۡمِ مِنۡ سُوۡٓءِ مَا بُشِّرَ بِہٖ ؕ اَیُمۡسِکُہٗ عَلٰی ہُوۡنٍ اَمۡ  یَدُسُّہٗ  فِی التُّرَابِ ؕ اَلَا  سَآءَ  مَا  یَحۡکُمُوۡنَ ﴿۵۹﴾', 'اور اس خبر بد کے سبب جو وہ سنتا ہے لوگوں سے چھپتا پھرتا ہے سوچتا ہے۔ کہ آیا ذلت برداشت کر کے لڑکی کو زندہ رہنے دے یا زمین میں گاڑ دے دیکھو یہ جو تجویز کرتے ہیں بہت بری ہے۔', 'چھپتا پھرے لوگوں سے مارےبرائی اس خوشخبری کے جو سنی [۸۴] اس کو رہنے دے ذلت قبول کر کے یا اس کو داب دے مٹی میں [۸۵] سنتا ہے برا فیصلہ کرتے ہیں [۸۶]', 'He hides himself from the people because of the evil of that whereof he has been informed. Shall he keep her with dishonour or bury her in the earth? Certainly, evil is their decision.', 'He hides himself from people because of the (self-presumed) bad news given to him (and wonders): Shall he keep it despite the disgrace (he will face in the society), or put it away into the dust? In fact, evil is what they decide.'),
(1961, 16, 60, 7, 13, 14, 'رُبَمَا', 'النحل', 'لِلَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِالۡاٰخِرَۃِ مَثَلُ السَّوۡءِ ۚ وَ لِلّٰہِ الۡمَثَلُ الۡاَعۡلٰی ؕ وَ ہُوَ الۡعَزِیۡزُ  الۡحَکِیۡمُ ﴿٪۶۰﴾', 'جو لوگ آخرت پر ایمان نہیں رکھتے انہی کے لئے بری مثال ہے اور اللہ کو صفت اعلیٰ زیب دیتی ہے اور وہ غالب ہے حکمت والا ہے۔', 'جو نہیں مانتے آخرت کو ان کی بری مثال ہے اور اللہ کی مثال (شان) سب سے اوپر [۸۷] اور وہی ہے زبردست حکمت والا [۸۸]', 'For those who believe not in the Hereafter is an evil description, and for Allah is the highest description. And He is the All-Mighty, the All-Wise.', 'Those who do not believe in the Hereafter have evil attributes, and to Allah belong the most exalted attributes. He is the Mighty, the Wise.'),
(1962, 16, 61, 8, 14, 14, 'رُبَمَا', 'النحل', 'وَ لَوۡ  یُؤَاخِذُ اللّٰہُ النَّاسَ بِظُلۡمِہِمۡ مَّا تَرَکَ عَلَیۡہَا مِنۡ دَآبَّۃٍ وَّ لٰکِنۡ یُّؤَخِّرُہُمۡ  اِلٰۤی اَجَلٍ مُّسَمًّی ۚ فَاِذَا جَآءَ  اَجَلُہُمۡ لَا یَسۡتَاۡخِرُوۡنَ سَاعَۃً وَّ لَا یَسۡتَقۡدِمُوۡنَ ﴿۶۱﴾', 'اور اگر اللہ لوگوں کو انکے ظلم کے سبب پکڑنے لگے تو ایک جاندار کو زمین پر نہ چھوڑے۔ لیکن انکو ایک وقت مقرر تک مہلت دیئے جاتا ہے۔ پھر جب وہ وقت آ جاتا ہے تو ایک گھڑی نہ پیچھے رہ سکتے ہیں نہ آگے بڑھ سکتے ہیں۔', 'اور اگر پکڑے اللہ لوگوں کو ان کی بے انصافی پر نہ چھوڑے زمین پر ایک چلنے والا لیکن ڈھیل دیتا ہے ان کو ایک وقت موعود تک پھر جب آ پہنچے گا ان کا وعدہ نہ پیچھے سرک سکیں گے ایک گھڑی اور نہ آگے سرک سکیں گے [۸۹]', 'And if Allah were to seize mankind for their wrong-doing, He would not leave on it (the earth) a single moving (living) creature, but He postpones them for an appointed term and when their term comes, neither can they delay nor can they advance it an hour (or a moment).', 'If Allah were to seize the people for their transgression, He would have spared no creature on earth, but He lets them go on up to an appointed time. So, when their time will come, they will not be able to delay it for a moment, nor to bring it soon.'),
(1963, 16, 62, 8, 14, 14, 'رُبَمَا', 'النحل', 'وَ یَجۡعَلُوۡنَ لِلّٰہِ مَا یَکۡرَہُوۡنَ وَ تَصِفُ اَلۡسِنَتُہُمُ الۡکَذِبَ اَنَّ  لَہُمُ  الۡحُسۡنٰی ؕ لَا  جَرَمَ  اَنَّ لَہُمُ النَّارَ وَ اَنَّہُمۡ مُّفۡرَطُوۡنَ ﴿۶۲﴾', 'اور یہ اللہ کے لئے ایسی چیزیں تجویز کرتے ہیں جنکو خود ناپسند کرتے ہیں اور زبان سے جھوٹ بکے جاتے ہیں۔ کہ انکو قیامت کے دن بھلائی یعنی نجات ہو گی۔ کچھ شک نہیں کہ انکے لئے دوزخ کی آگ تیار ہے اور یہ دوزخ میں سب سے آگے بھیجے جائیں گے۔', 'اور کرتے ہیں (ٹھہراتے ہیں) اللہ کے واسطے جس کو اپنا جی نہ چاہے [۹۰] اور بیان کرتی ہیں زبانیں انکی جھوٹ کہ انکے واسطے خوبی ہے [۹۱] آپ ثابت ہے (محقق ہو گیا)کہ انکے واسطے آگ ہے اور وہ بڑھائے جارہے ہیں [۹۲]', 'They assign to Allah that which they dislike (for themselves), and their tongues assert the falsehood that the better things will be theirs. No doubt for them is the Fire, and they will be the first to be hastened on into it, and left there neglected. (Tafsir Al-Qurtubee, Vol.10, Page 121)', 'They assign to Allah what they themselves dislike, and their tongues make the false statement that for them there is a happy end. No, Fire is imminently theirs, and they are being driven (towards it) speedily.'),
(1964, 16, 63, 8, 14, 14, 'رُبَمَا', 'النحل', 'تَاللّٰہِ  لَقَدۡ  اَرۡسَلۡنَاۤ  اِلٰۤی اُمَمٍ مِّنۡ قَبۡلِکَ فَزَیَّنَ لَہُمُ الشَّیۡطٰنُ اَعۡمَالَہُمۡ فَہُوَ وَلِیُّہُمُ الۡیَوۡمَ  وَ لَہُمۡ  عَذَابٌ  اَلِیۡمٌ ﴿۶۳﴾', 'اللہ کی قسم ہم نے تم سے پہلی امتوں کی طرف بھی پیغمبر بھیجے تو شیطان نے انکے کرتوت ان کو آراستہ کر دکھائے تو آج بھی وہی ان کا دوست ہے اور انکے لئے عذاب الیم ہے۔', 'قسم اللہ کی ہم نے رسول بھیجے مختلف فرقوں میں تجھ سے پہلے پھر اچھے کر کے دکھلائے انکو شیطان نے ان کے کام سو وہی رفیق ان کا ہے آج اور ان کے واسطے عذاب دردناک ہے [۹۳]', 'By Allah, We indeed sent (Messengers) to the nations before you (O Muhammad SAW), but Shaitan (Satan) made their deeds fair-seeming to them. So he (Satan) is their Wali (helper) today (i.e. in this world), and theirs will be a painful torment.', 'By Allah, We sent (messengers) to communities before you, but the Satan made their deeds look good to them. So, he is their patron today, and for them there is a painful punishment.'),
(1965, 16, 64, 8, 14, 14, 'رُبَمَا', 'النحل', 'وَ مَاۤ  اَنۡزَلۡنَا عَلَیۡکَ الۡکِتٰبَ اِلَّا لِتُبَیِّنَ لَہُمُ الَّذِی اخۡتَلَفُوۡا فِیۡہِ ۙ وَ ہُدًی  وَّ  رَحۡمَۃً   لِّقَوۡمٍ  یُّؤۡمِنُوۡنَ ﴿۶۴﴾', 'اور ہم نے جو کتاب تم پر نازل کی ہے تو اس لئے کہ جس بات میں ان لوگوں کو اختلاف ہے تم اس کا فیصلہ کر دو۔ اور یہ مومنوں کے لئے ہدایت اور رحمت ہے۔', 'اور ہم نے اتاری تجھ پر کتاب اسی واسطے کہ کھول کر سنا دے تو ان کو وہ چیز کہ جس میں جھگڑ رہے ہیں [۹۴] اور سیدھی راہ سجھانے کو اور واسطے بخشش ایمان لانے والوں کے (رحمت ان لوگوں کے لئے جو ایمان لائے) [۹۵]', 'And We have not sent down the Book (the Quran) to you (O Muhammad SAW), except that you may explain clearly unto them those things in which they differ, and (as) a guidance and a mercy for a folk who believe.', 'We have sent down the Book to you, only because you may explain to them what they differed about, and (so that it may be) guidance and mercy for a people who believe.'),
(1966, 16, 65, 8, 14, 14, 'رُبَمَا', 'النحل', 'وَ اللّٰہُ  اَنۡزَلَ مِنَ السَّمَآءِ  مَآءً  فَاَحۡیَا بِہِ الۡاَرۡضَ بَعۡدَ مَوۡتِہَا ؕ اِنَّ فِیۡ  ذٰلِکَ لَاٰیَۃً  لِّقَوۡمٍ  یَّسۡمَعُوۡنَ ﴿٪۶۵﴾', 'اور اللہ ہی نے آسمان سے پانی برسایا پھر اس سے زمین کو اسکے مرنے کے بعد زندہ کیا بیشک اس میں سننے والوں کے لئے نشانی ہے۔', 'اور اللہ نے اتارا آسمان سے پانی پھر اس سے زندہ کیا زمین کو اس کے مرنے کے پیچھے [۹۶]اس میں نشانی ہے ان لوگوں کو جو سنتے ہیں [۹۷]', 'And Allah sends down water (rain) from the sky, then He revives the earth therewith after its death. Verily, in this is a sign (clear proof) for people who listen (obey Allah).', 'Allah sent down water from the heavens and revived the land with it after it was dead. Surely, in that there is a sign for a people who listen.'),
(1967, 16, 66, 9, 15, 14, 'رُبَمَا', 'النحل', 'وَ  اِنَّ لَکُمۡ فِی الۡاَنۡعَامِ لَعِبۡرَۃً ؕ نُسۡقِیۡکُمۡ  مِّمَّا فِیۡ بُطُوۡنِہٖ مِنۡۢ  بَیۡنِ  فَرۡثٍ وَّ دَمٍ لَّبَنًا خَالِصًا سَآئِغًا لِّلشّٰرِبِیۡنَ ﴿۶۶﴾', 'اور تمہارے لئے چوپایوں میں بھی مقام عبرت و غور ہے کہ انکے پیٹوں میں جو گوبر اور لہو ہے اس کے درمیان سے نکال کر  ہم تم کو خالص دودھ پلاتے ہیں جو پینے والوں کے لئے خوشگوار ہے۔', 'اور تمہارے واسطے چوپاؤں میں سوچنے کی جگہ ہے پلاتے ہیں تم کو اس کے پیٹ کی چیزوں میں سےگوبر اور لہو کے بیچ میں سے (درمیان سے) دودھ ستھرا [۹۸] خوشگوار پینے والوں کے لئے [۹۹]', 'And verily! In the cattle, there is a lesson for you. We give you to drink of that which is in their bellies, from between excretions and blood, pure milk; palatable to the drinkers.', 'Surely there is a lesson for you in the cattle. We provide you, out of what lies in their bellies between feces and blood, the (drink of) milk, pure and pleasant for those who drink.'),
(1968, 16, 67, 9, 15, 14, 'رُبَمَا', 'النحل', 'وَ مِنۡ ثَمَرٰتِ النَّخِیۡلِ وَ الۡاَعۡنَابِ تَتَّخِذُوۡنَ مِنۡہُ سَکَرًا  وَّ  رِزۡقًا حَسَنًا ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیَۃً   لِّقَوۡمٍ  یَّعۡقِلُوۡنَ ﴿۶۷﴾', 'اور کھجور اور انگور کے میووں سے بھی تم پینے کی چیزیں تیار کرتے ہو کہ ان سے شراب بناتے ہو اور عمدہ رزق کھاتے ہو جو لوگ سمجھ رکھتے ہیں انکے لئے ان چیزوں میں نشانی ہے۔', 'اور میووں سے کھجور کے اور انگور کے بناتے ہو اس سے نشہ اور روزی خاصی [۱۰۰] اس میں نشانی ہے ان لوگوں کے واسطے جو سمجھتے ہیں (سوچتے ہیں) [۱۰۱]', 'And from the fruits of date-palms and grapes, you derive strong drink (this was before the order of the prohibition of the alcoholic drinks) and a goodly provision. Verily, therein is indeed a sign for people who have wisdom.', 'And from the fruits of date palms and grape vines, you obtain intoxicants, and good provision. Surely, in that there is a sign for a people who understand.'),
(1969, 16, 68, 9, 15, 14, 'رُبَمَا', 'النحل', 'وَ اَوۡحٰی رَبُّکَ اِلَی النَّحۡلِ اَنِ اتَّخِذِیۡ مِنَ الۡجِبَالِ بُیُوۡتًا وَّ مِنَ الشَّجَرِ وَ مِمَّا یَعۡرِشُوۡنَ ﴿ۙ۶۸﴾', 'اور تمہارے پروردگار نے شہد کی مکھی کو ارشاد فرمایا کہ پہاڑوں میں اور درختوں میں اور اونچی اونچی چھتریوں میں جو لوگ بناتے ہیں گھر بنا۔', 'اور حکم دیا تیرے رب نے شہد کی مکھی کو کہ بنا لے پہاڑوں میں گھر اور درختوں میں اور جہاں ٹٹیاں باندھتے ہیں [۱۰۲]', 'And your Lord inspired the bee, saying: \"Take you habitations in the mountains and in the trees and in what they erect.', 'Your Lord revealed to the honeybee: “Make homes in the mountains, in the trees and in the structures they raise.'),
(1970, 16, 69, 9, 15, 14, 'رُبَمَا', 'النحل', 'ثُمَّ  کُلِیۡ مِنۡ کُلِّ الثَّمَرٰتِ فَاسۡلُکِیۡ سُبُلَ رَبِّکِ ذُلُلًا ؕ یَخۡرُجُ مِنۡۢ بُطُوۡنِہَا شَرَابٌ مُّخۡتَلِفٌ اَلۡوَانُہٗ  فِیۡہِ شِفَآءٌ لِّلنَّاسِ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیَۃً   لِّقَوۡمٍ  یَّتَفَکَّرُوۡنَ ﴿۶۹﴾', 'پھر ہر قسم کے میوے کھا۔ اور اپنے پروردگار کے صاف رستوں پر چلی جا۔ اس کے پیٹ سے پینے کی چیز نکلتی ہے جس کے مختلف رنگ ہوتے ہیں اس میں لوگوں کے لئے شفا ہے بیشک سوچنے والوں کے لئے اس میں بھی نشانی ہے۔', 'پھر کھا ہر طرح کے میووں سے [۱۰۳] پھر چل راہوں میں (راستوں میں) اپنے رب کی صاف پڑے ہیں [۱۰۴] نکلتی ہے ان کے پیٹ میں سے پینے کی چیز جسکے مختلف رنگ ہیں [۱۰۵] اس میں مرض اچھے ہوتے ہیں لوگوں کے [۱۰۶] اس میں نشانی ہے ان لوگوں کے لئے جو دھیان کرتے ہیں [۱۰۷]', '\"Then, eat of all fruits, and follow the ways of your Lord made easy (for you).\" There comes forth from their bellies, a drink of varying colour wherein is healing for men. Verily, in this is indeed a sign for people who think.', 'Then, eat from all the fruits, and go along the pathways of your Lord made easy for you.” From their bellies comes out a drink of various colors in which there is cure for people. Surely, in that there is a sign for a people who ponder.'),
(1971, 16, 70, 9, 15, 14, 'رُبَمَا', 'النحل', 'وَ اللّٰہُ خَلَقَکُمۡ ثُمَّ یَتَوَفّٰىکُمۡ ۟ۙ وَ مِنۡکُمۡ مَّنۡ  یُّرَدُّ   اِلٰۤی اَرۡذَلِ الۡعُمُرِ  لِکَیۡ لَا یَعۡلَمَ  بَعۡدَ عِلۡمٍ شَیۡئًا ؕ اِنَّ اللّٰہَ عَلِیۡمٌ  قَدِیۡرٌ ﴿٪۷۰﴾', 'اور اللہ ہی نے تم کو پیدا کیا۔ پھر وہی تم کو موت دیتا ہے اور تم میں بعض ایسے ہوتے ہیں کہ نہایت خراب عمر کو پہنچ جاتے ہیں۔ تاکہ بہت کچھ جاننے کے بعد ہر چیز سے بےعلم ہو جائیں۔ بیشک اللہ سب کچھ جاننے والا ہے قدرت والا ہے۔', 'اور اللہ نے تم کو پیدا کیا پھر تم کو موت دیتا ہے اور کوئی تم میں سے پہنچ جاتا ہے نکمی عمر کو کہ سمجھنے کے پیچھے اب کچھ نہ سمجھے اللہ خبردار ہے قدرت والا [۱۰۸]', 'And Allah has created you and then He will cause you to die, and of you there are some who are sent back to senility, so that they know nothing after having known (much). Truly! Allah is All-Knowing, All-Powerful.', 'Allah has created you, then He takes you back. And among you there is one who is carried to the worst part of the age, so that he knows nothing after having knowledge. Surely, Allah is All-Knowing, All-Powerful.'),
(1972, 16, 71, 10, 16, 14, 'رُبَمَا', 'النحل', 'وَ اللّٰہُ  فَضَّلَ بَعۡضَکُمۡ عَلٰی بَعۡضٍ فِی الرِّزۡقِ ۚ فَمَا الَّذِیۡنَ فُضِّلُوۡا بِرَآدِّیۡ رِزۡقِہِمۡ عَلٰی مَا مَلَکَتۡ  اَیۡمَانُہُمۡ  فَہُمۡ فِیۡہِ سَوَآءٌ ؕ اَفَبِنِعۡمَۃِ اللّٰہِ یَجۡحَدُوۡنَ ﴿۷۱﴾', 'اور اللہ نے رزق و دولت میں بعض کو بعض پر فضیلت دی ہے تو جن لوگوں کو فضیلت دی ہے وہ اپنا رزق اپنے غلاموں کو تو دے ڈالنے والے ہیں نہیں کہ سب اس میں برابر ہو جائیں تو کیا یہ لوگ نعمت الہٰی کے منکر ہیں؟', 'اور اللہ نے بڑائی دی تم میں ایک کو ایک پر روزی میں سو جن کو بڑائی دی وہ نہیں پہنچا دیتے اپنی روزی ان کو جن کے مالک ان کے ہاتھ ہیں کہ وہ سب اس میں برابر ہو جائیں کیا اللہ کی نعمت کے منکر ہیں [۱۰۹]', 'And Allah has preferred some of you above others in wealth and properties. Then, those who are preferred will by no means hand over their wealth and properties to those (slaves) whom their right hands possess, so that they may be equal with them in respect thereof. Do they then deny the Favour of Allah?', 'Allah has given some of you preference over others in provision. So, those given preference are not willing to pass on their provision to their slaves, so that they become equal in it: Do they, then, reject the blessing of Allah?'),
(1973, 16, 72, 10, 16, 14, 'رُبَمَا', 'النحل', 'وَ اللّٰہُ جَعَلَ لَکُمۡ مِّنۡ اَنۡفُسِکُمۡ اَزۡوَاجًا وَّ جَعَلَ لَکُمۡ مِّنۡ اَزۡوَاجِکُمۡ بَنِیۡنَ وَ حَفَدَۃً  وَّ رَزَقَکُمۡ مِّنَ الطَّیِّبٰتِ ؕ اَفَبِالۡبَاطِلِ  یُؤۡمِنُوۡنَ وَ بِنِعۡمَتِ اللّٰہِ ہُمۡ یَکۡفُرُوۡنَ ﴿ۙ۷۲﴾', 'اور اللہ ہی نے تم میں سے تمہارے لئے بیویاں پیدا کیں اور بیویوں سے تمہارے بیٹے اور پوتے پیدا کئے اور کھانے کو تمہیں پاکیزہ چیزیں دیں تو کیا یہ لوگ باطل پر اعتقاد رکھتے اور اللہ کی نعمتوں سے انکار کرتے ہیں؟', 'اور اللہ نے پیدا کیں تمہارے واسطے تمہای ہی قسم سے عورتیں [۱۱۰] اور دیے تم کو تمہاری عورتوں سے بیٹے اور پوتے [۱۱۱] اور کھانے کو دیں تمکو ستھری چیزیں [۱۱۲] سو کیا جھوٹی باتیں مانتے ہیں اور اللہ کے فضل کو نہیں مانتے [۱۱۳]', 'And Allah has made for you wives of your own kind, and has made for you, from your wives, sons and grandsons, and has bestowed on you good provision. Do they then believe in false deities and deny the Favour of Allah (by not worshipping Allah Alone).', 'Allah has created spouses from among you and created sons and grandsons for you from your spouses, and gave you provision from good things. Is it, then, the falsehood that they believe in, and the blessing of Allah that they reject?'),
(1974, 16, 73, 10, 16, 14, 'رُبَمَا', 'النحل', 'وَ یَعۡبُدُوۡنَ مِنۡ دُوۡنِ اللّٰہِ مَا لَا یَمۡلِکُ لَہُمۡ رِزۡقًا مِّنَ السَّمٰوٰتِ وَ الۡاَرۡضِ شَیۡئًا  وَّ لَا یَسۡتَطِیۡعُوۡنَ ﴿ۚ۷۳﴾', 'اور اللہ کے سوا ایسوں کو پوجتے ہیں جو انکو آسمانوں اور زمین میں روزی دینے کا ذرا بھی اختیار نہیں رکھتے اور نہ کسی اور طرح کا مقدور رکھتے ہیں۔', 'اور پوجتے ہیں اللہ کے سوائے ایسوں کو جو مختار نہیں انکی روزی کے آسمان اور زمین میں سے کچھ بھی [۱۱۴] اور نہ قدرت رکھتے ہیں [۱۱۵]', 'And they worship others besides Allah, such as do not and cannot own any provision for them from the heavens or the earth.', 'They worship, besides Allah, the objects that have no power to give them anything from the heavens and the earth, nor can they ever have such power.'),
(1975, 16, 74, 10, 16, 14, 'رُبَمَا', 'النحل', 'فَلَا تَضۡرِبُوۡا لِلّٰہِ الۡاَمۡثَالَ ؕ اِنَّ اللّٰہَ یَعۡلَمُ  وَ  اَنۡتُمۡ  لَا تَعۡلَمُوۡنَ ﴿۷۴﴾', 'تو لوگو اللہ کے لئے غلط مثالیں نہ بناؤ بیشک اللہ جانتا ہے اور تم نہیں جانتے۔', 'سو مت چسپاں کرو (بٹھلاؤ) اللہ پر مثالیں [۱۱۶] بیشک اللہ جانتا ہے اور تم نہیں جانتے [۱۱۷]', 'So put not forward similitudes for Allah (as there is nothing similar to Him, nor He resembles anything). Truly! Allah knows and you know not.', 'So, do not coin similarities for Allah. Surely, Allah knows and you do not know.'),
(1976, 16, 75, 10, 16, 14, 'رُبَمَا', 'النحل', 'ضَرَبَ اللّٰہُ مَثَلًا عَبۡدًا مَّمۡلُوۡکًا لَّا یَقۡدِرُ عَلٰی شَیۡءٍ وَّ مَنۡ رَّزَقۡنٰہُ مِنَّا رِزۡقًا حَسَنًا فَہُوَ یُنۡفِقُ مِنۡہُ سِرًّا وَّ جَہۡرًا ؕ ہَلۡ یَسۡتَوٗنَ ؕ اَلۡحَمۡدُ لِلّٰہِ ؕ بَلۡ اَکۡثَرُہُمۡ  لَا  یَعۡلَمُوۡنَ ﴿۷۵﴾', 'اللہ ایک اور مثال بیان فرماتا ہے کہ ایک غلام ہے جو بالکل دوسرے کے اختیار میں ہے اور کسی چیز پر قدرت نہیں رکھتا اور ایک ایسا شخص ہے جس کو ہم نے اپنے ہاں سے بہت سا مال طیب عطا فرمایا ہے اور وہ اس میں سے رات دن پوشیدہ اور ظاہر خرچ کرتا رہتا ہے تو کیا یہ دونوں شخص برابر ہیں؟ ہرگز نہیں الحمداللہ لیکن ان میں سے اکثر لوگ نہیں سمجھ رکھتے۔', 'اللہ نے بتلائی ایک مثال ایک بندہ (غلام) پرایا مال نہیں قدرت رکھتا کسی چیز پر اور ایک جسکو ہم نے روزی دی اپنی طرف سے خاصی روزی سو وہ خرچ کرتا ہے اس میں سے چھپا کر اور سب کے روبرو کہیں برابر ہوتے ہیں سب تعریف اللہ کو ہے پر بہت لوگ نہیں جانتے [۱۱۸]', 'Allah puts forward the example (of two men a believer and a disbeliever); a slave (disbeliever) under the possession of another, he has no power of any sort, and (the other), a man (believer) on whom We have bestowed a good provision from Us, and He spends thereof secretly and openly. Can they be equal? (By no means, not). All the praises and thanks be to Allah. Nay! (But) most of them know not.', 'Allah gives an example: There is a slave owned (by someone), who has no power over anything, and there is a person whom We have given good provision from Us, and he spends out of it secretly and openly. Are they equal? Praise be to Allah. But, most of them do not know.'),
(1977, 16, 76, 10, 16, 14, 'رُبَمَا', 'النحل', 'وَ ضَرَبَ اللّٰہُ مَثَلًا رَّجُلَیۡنِ اَحَدُہُمَاۤ اَبۡکَمُ لَا یَقۡدِرُ عَلٰی شَیۡءٍ وَّ ہُوَ  کَلٌّ عَلٰی مَوۡلٰىہُ ۙ اَیۡنَمَا یُوَجِّہۡہُّ  لَایَاۡتِ بِخَیۡرٍ ؕ ہَلۡ یَسۡتَوِیۡ ہُوَ ۙ وَ مَنۡ  یَّاۡمُرُ  بِالۡعَدۡلِ ۙ وَ ہُوَ  عَلٰی صِرَاطٍ مُّسۡتَقِیۡمٍ ﴿٪۷۶﴾', 'اور اللہ ایک اور مثال بیان فرماتا ہے کہ دو آدمی ہیں ایک ان میں سے گونگا اور کسی کا غلام ہے بےاختیار و ناتواں کہ کسی چیز پر قدرت نہیں رکھتا۔ اور اپنے مالک کو دوبھر ہو رہا ہے وہ جہاں اسے بھیجتا ہے کبھی اچھی خبر نہیں لاتا۔ کیا ایسا گونگا بہرا اور وہ شخص جو سنتا بولتا اور لوگوں کو انصاف کرنے کا حکم دیتا ہے۔ اور خود سیدھے رستے پر چل رہا ہے دونوں برابر ہو سکتے ہیں؟', 'اور بتائی اللہ نے ایک دوسری مثال دو مرد ہیں ایک گونگا [۱۱۹] کچھ کام نہیں کر سکتا [۱۲۰] اور وہ بھاری ہے اپنے صاحب (مالک) پر جس طرف اسکو بھیجے نہ کر کے لائے کچھ بھلائی [۱۲۱] کہیں برابر ہے وہ اور ایک وہ شخص جو حکم کرتا ہے انصاف سے اور ہے سیدھی راہ پر  [۱۲۲]', 'And Allah puts forward (another) example of two men, one of them dumb, who has no power over anything (disbeliever), and he is a burden to his master, whichever way he directs him, he brings no good. Is such a man equal to one (believer in the Islamic Monotheism) who commands justice, and is himself on a Straight Path?', 'And Allah gives another example: There are two men. One of them is dumb who is unable to do anything, and he is a burden on his master. Wherever he directs him to, he brings no good. Can he be equal to the one who enjoins justice and is on the straight path?'),
(1978, 16, 77, 11, 17, 14, 'رُبَمَا', 'النحل', 'وَ  لِلّٰہِ غَیۡبُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ مَاۤ اَمۡرُ السَّاعَۃِ  اِلَّا کَلَمۡحِ الۡبَصَرِ اَوۡ ہُوَ اَقۡرَبُ ؕ اِنَّ اللّٰہَ عَلٰی کُلِّ شَیۡءٍ قَدِیۡرٌ ﴿۷۷﴾', 'اور آسمانوں اور زمین کا بھید اللہ ہی کے پاس ہے اور اللہ کے نزدیک قیامت کا آنا یوں ہے جیسے آنکھ کا جھپکنا بلکہ اس سے بھی جلد تر کچھ شک نہیں کہ اللہ ہر چیز پر قادر ہے۔', 'اور اللہ ہے کہ پاس ہیں بھید آسمانوں اور زمین کے [۱۲۳] اور قیامت کا کام تو ایسا ہے جسیے لپک نگاہ کی یا اس سے بھی قریب [۱۲۴] اور اللہ ہر چیز پر قادر ہے [۱۲۵]', 'And to Allah belongs the unseen of the heavens and the earth. And the matter of the Hour is not but as a twinkling of the eye, or even nearer. Truly! Allah is Able to do all things.', 'To Allah belongs the Unseen of the heavens and the earth; and the matter of Hour (of Judgment) is no more than of twinkling of the eye, or even quicker. Of course, Allah is powerful over everything.'),
(1979, 16, 78, 11, 17, 14, 'رُبَمَا', 'النحل', 'وَ اللّٰہُ اَخۡرَجَکُمۡ  مِّنۡۢ بُطُوۡنِ اُمَّہٰتِکُمۡ لَا تَعۡلَمُوۡنَ شَیۡئًا ۙ وَّ جَعَلَ لَکُمُ السَّمۡعَ وَ الۡاَبۡصَارَ وَ الۡاَفۡـِٕدَۃَ ۙ لَعَلَّکُمۡ  تَشۡکُرُوۡنَ ﴿۷۸﴾', 'اور اللہ ہی نے تم کو تمہاری ماؤں کے شکم سے پیدا کیا اس حال میں کہ تم کچھ نہیں جانتے تھے۔ اور اس نے تم کو کان اور آنکھیں اور دل اور انکے علاوہ اور اعضاء بخشے تاکہ تم شکر کرو۔', 'اور اللہ نے تم کو نکالا تمہاری ماں کے پیٹ سے نہ جانتے تھے تم کسی چیز کو اور دیئے تم کو کان اور آنکھیں اور دل تاکہ تم احسان مانو [۱۲۶]', 'And Allah has brought you out from the wombs of your mothers while you know nothing. And He gave you hearing, sight, and hearts that you might give thanks (to Allah).', 'Allah has brought you forth from your mothers’ wombs when you knew nothing, and He made for you ears, eyes and hearts, so that you may be grateful.'),
(1980, 16, 79, 11, 17, 14, 'رُبَمَا', 'النحل', 'اَلَمۡ یَرَوۡا اِلَی الطَّیۡرِ مُسَخَّرٰتٍ فِیۡ جَوِّ السَّمَآءِ ؕ مَا یُمۡسِکُہُنَّ  اِلَّا اللّٰہُ ؕ اِنَّ فِیۡ  ذٰلِکَ  لَاٰیٰتٍ  لِّقَوۡمٍ  یُّؤۡمِنُوۡنَ ﴿۷۹﴾', 'کیا ان لوگوں نے پرندوں کو نہیں دیکھا کہ آسمان کی ہوا میں گھرے ہوئے اڑتے رہتے ہیں۔ انکو اللہ ہی تھامے رکھتا ہے ایمان والوں کے لئے اس میں بہت سی نشانیاں ہیں۔', 'کیا نہیں دیکھے اڑتے جانور حکم کے باندھے ہوئے آسمان کی ہوا میں کوئی نہیں تھام رہا ان کو سوائے اللہ کے [۱۲۷] اس میں نشانیاں ہیں ان لوگوں کو جو یقین لاتے ہیں [۱۲۸]', 'Do they not see the birds held (flying) in the midst of the sky? None holds them but Allah (none gave them the ability to fly but Allah). Verily, in this are clear proofs and signs for people who believe (in the Oneness of Allah).', 'Did they not look at the birds how they are controlled in the atmosphere of the sky? No one holds them but Allah. Surely, in that there are signs for a people who believe.'),
(1981, 16, 80, 11, 17, 14, 'رُبَمَا', 'النحل', 'وَ اللّٰہُ جَعَلَ لَکُمۡ مِّنۡۢ بُیُوۡتِکُمۡ سَکَنًا وَّ جَعَلَ لَکُمۡ مِّنۡ جُلُوۡدِ الۡاَنۡعَامِ بُیُوۡتًا تَسۡتَخِفُّوۡنَہَا یَوۡمَ ظَعۡنِکُمۡ وَ یَوۡمَ اِقَامَتِکُمۡ ۙ وَ مِنۡ اَصۡوَافِہَا وَ اَوۡبَارِہَا وَ اَشۡعَارِہَاۤ  اَثَاثًا وَّ مَتَاعًا اِلٰی حِیۡنٍ ﴿۸۰﴾', 'اور اللہ ہی نے تمہارے لئے گھروں کو رہنے کی جگہ بنایا اور اسی نے چوپایوں کی کھالوں سے تمہارے لئے ڈیرے بنائے جنکو تم ہلکا پھلکا دیکھ کر سفر اور حضر میں کام میں لاتے ہو اور انکی اون اور پشم اور بالوں سے تم اسباب اور برتنے کی چیزیں بناتے ہو جو مدت تک کام دیتی ہیں۔', 'اور اللہ نے بنا دیئے تم کو تمہارے گھر بسنے کی جگہ [۱۲۹] اور بنا دیئے تم کو چوپاؤں کی کھال سے ڈیرے جو ہلکے رہتے ہیں تم پر جس دن سفر میں ہو اور جس دن گھر میں [۱۳۰] اور بھیڑوں کی اون سے اور اونٹوں کی ببریوں سے [۱۳۱] اور بکریوں کے بالوں سے کتنے اسباب اور استعمال کی چیزیں وقت مقرر تک [۱۳۲]', 'And Allah has made for you in your homes an abode, and made for you out of the hides of the cattle (tents for) dwelling, which you find so light (and handy) when you travel and when you stay (in your travels), and of their wool, fur, and hair (sheep wool, camel fur, and goat hair), a furnishing and articles of convenience (e.g. carpets, blankets, etc.), a comfort for a while.', 'Allah has made your houses a place of comfort for you, and made for you houses from the hides of cattle, which you find so light on the day you travel and the day you camp, and out of their wool and their fur and their hair (He created) furnishings and goods of enjoyment for a period of time.'),
(1982, 16, 81, 11, 17, 14, 'رُبَمَا', 'النحل', 'وَ اللّٰہُ جَعَلَ لَکُمۡ  مِّمَّا خَلَقَ ظِلٰلًا وَّ جَعَلَ لَکُمۡ  مِّنَ  الۡجِبَالِ  اَکۡنَانًا وَّ جَعَلَ لَکُمۡ سَرَابِیۡلَ تَقِیۡکُمُ  الۡحَرَّ وَ سَرَابِیۡلَ تَقِیۡکُمۡ بَاۡسَکُمۡ ؕ کَذٰلِکَ یُتِمُّ نِعۡمَتَہٗ عَلَیۡکُمۡ لَعَلَّکُمۡ تُسۡلِمُوۡنَ ﴿۸۱﴾', 'اور اللہ ہی نے تمہارے آرام کے لئے اپنی پیدا کی ہوئی چیزوں کے سائے بنائے اور پہاڑوں میں غار بنائے اور تمہارے لئے کرتے بنائے جو تم کو گرمی سے بچائیں۔ اور ایسے کرتے بھی جو تم کو اسلحہ جنگ کے ضرر سے محفوظ رکھیں۔ اسی طرح اللہ اپنا احسان تم پر پورا کرتا ہے تاکہ تم فرمانبردار بنو۔', 'اور اللہ نے بنا دیئے تمہارے واسطے اپنی بنائی ہوئی چیزوں کے سائے [۱۳۳] اور بنا دیں تمہارےواسطے پہاڑوں میں چھپنے کی جگہیں [۱۳۴] اور بنا دیے تم کو کرتے جو بچاؤ ہیں گرمی میں [۱۳۵] اور کرتے جو بچاؤ ہیں لڑائی میں [۱۳۶] اسی طرح پورا کرتا ہے اپنا احسان تم پر تاکہ تم حکم مانو [۱۳۷]', 'And Allah has made for you out of that which He has created shades, and has made for you places of refuge in the mountains, and has made for you garments to protect you from the heat (and cold), and coats of mail to protect you from your (mutual) violence. Thus does He perfect His Grace unto you, that you may submit yourselves to His Will (in Islam).', 'Allah has made for your benefit shades from what He has created, and made for you shelters in the mountains, and made for you shirts that protect you from heat, and shirts that protect you in your battles. This is how He perfects His favor upon you, so that you may submit.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(1983, 16, 82, 11, 17, 14, 'رُبَمَا', 'النحل', 'فَاِنۡ  تَوَلَّوۡا فَاِنَّمَا عَلَیۡکَ الۡبَلٰغُ الۡمُبِیۡنُ ﴿۸۲﴾', 'پس اگر یہ لوگ روگردانی کریں تو اے پیغمبر تمہارا کام فقط صاف صاف پہنچا دینا ہے۔', 'پھر اگر پھر جائیں تو تیرا کام تو یہی ہے کھول کر سنا دینا [۱۳۸]', 'Then, if they turn away, your duty (O Muhammad SAW) is only to convey (the Message) in a clear way.', 'If they still turn away, then, your responsibility is only to convey the message clearly.'),
(1984, 16, 83, 11, 17, 14, 'رُبَمَا', 'النحل', 'یَعۡرِفُوۡنَ نِعۡمَتَ اللّٰہِ ثُمَّ  یُنۡکِرُوۡنَہَا وَ اَکۡثَرُہُمُ  الۡکٰفِرُوۡنَ ﴿٪۸۳﴾', 'یہ اللہ کی نعمتوں سے واقف ہیں۔ مگر واقف ہو کر ان سے انکار کرتے ہیں۔ اور یہ اکثر ناشکرے ہیں۔', 'پہچانتے ہیں اللہ کا احسان پھر منکر ہو جاتے ہیں اور بہت ان میں ناشکر ہیں [۱۳۹]', 'They recognise the Grace of Allah, yet they deny it (by worshipping others besides Allah) and most of them are disbelievers (deny the Prophethood of Muhammad SAW).', 'They are aware of Allah’s favor, yet they deny it, and most of them are ungrateful.'),
(1985, 16, 84, 12, 18, 14, 'رُبَمَا', 'النحل', 'وَ یَوۡمَ نَبۡعَثُ مِنۡ کُلِّ اُمَّۃٍ  شَہِیۡدًا ثُمَّ لَا یُؤۡذَنُ  لِلَّذِیۡنَ کَفَرُوۡا وَ لَا ہُمۡ یُسۡتَعۡتَبُوۡنَ ﴿۸۴﴾', 'اور جس دن ہم ہر امت میں سے ایک گواہ یعنی پیغمبر کو کھڑا کریں گے پھر نہ تو کفار کو بولنے کی اجازت ملے گی اور نہ انکے عذر قبول کئے جائیں گے۔', 'اور جس دن کھڑا کریں ہم ہر فرقہ میں ایک بتلانے والا پھر حکم (اجازت) نہ ملے منکروں کو اور نہ ان سے توبہ لی جائے [۱۴۰]', 'And (remember) the Day when We shall raise up from each nation a witness (their Messenger), then, those who have disbelieved will not be given leave (to put forward excuses), nor will they be allowed (to return to the world) to repent and ask for Allahs Forgiveness (of their sins, etc.).', '(Remember) the Day on which We shall raise up a witness from every people, then the disbelievers will not be allowed (to make excuses), nor shall they be asked to repent.'),
(1986, 16, 85, 12, 18, 14, 'رُبَمَا', 'النحل', 'وَ اِذَا رَاَ الَّذِیۡنَ ظَلَمُوا الۡعَذَابَ فَلَا یُخَفَّفُ عَنۡہُمۡ  وَ لَا  ہُمۡ  یُنۡظَرُوۡنَ ﴿۸۵﴾', 'اور جب ظالم لوگ عذاب دیکھ لیں گے تو پھر نہ تو انکے عذاب ہی میں تخفیف کی جائے گی اور نہ انکو مہلت ہی دی جائے گی۔', 'اور جب دیکھیں گے ظالم عذاب کو پھر ہلکا نہ ہو گا ان سے اور نہ ان کو ڈھیل ملے [۱۴۱]', 'And when those who did wrong (the disbelievers) will see the torment, then it will not be lightened unto them, nor will they be given respite.', 'And when the unjust will see the punishment, it will not be lightened for them, nor will they be given respite.'),
(1987, 16, 86, 12, 18, 14, 'رُبَمَا', 'النحل', 'وَ اِذَا رَاَ  الَّذِیۡنَ  اَشۡرَکُوۡا شُرَکَآءَہُمۡ  قَالُوۡا رَبَّنَا ہٰۤؤُلَآءِ شُرَکَآؤُنَا الَّذِیۡنَ کُنَّا نَدۡعُوۡا مِنۡ دُوۡنِکَ ۚ فَاَلۡقَوۡا اِلَیۡہِمُ الۡقَوۡلَ   اِنَّکُمۡ  لَکٰذِبُوۡنَ ﴿ۚ۸۶﴾', 'اور جب مشرک اپنے بنائے ہوئے شریکوں کو دیکھیں گے تو کہیں گے کہ پروردگار یہ وہی ہمارے شریک ہیں جنکو ہم تیرے سوا پکارا کرتے تھے۔ تو وہ انکے کلام کو مسترد کر دیں گے اور ان سے کہیں گے کہ تم جھوٹے ہو۔', 'اور جب دیکھیں مشرک اپنے شریکوں کو بولیں اے رب یہ ہمارے شریک ہیں جن کو ہم پکارتے تھے تیرے سوائے [۱۴۲] تب وہ ان پر ڈالیں گے بات کہ تم جھوٹے ہو [۱۴۳]', 'And when those who associated partners with Allah see their (Allahs so-called) partners, they will say: \"Our Lord! These are our partners whom we used to invoke besides you.\" But they will throw back their word at them (and say): \"Surely! You indeed are liars!\"', 'When the Mushriks (i.e. those who ascribe partners to Allah) will see those whom they made partners with Allah, they will say: “Our Lord, these are the partners we made whom we called in worship besides you.” Then, they (the partners) will turn to them saying: “You are indeed liars.”'),
(1988, 16, 87, 12, 18, 14, 'رُبَمَا', 'النحل', 'وَ  اَلۡقَوۡا  اِلَی اللّٰہِ یَوۡمَئِذِۣ السَّلَمَ وَ ضَلَّ  عَنۡہُمۡ  مَّا  کَانُوۡا  یَفۡتَرُوۡنَ ﴿۸۷﴾', 'اور اس دن اللہ کے سامنے سرنگوں ہو جائیں گے اور جو طوفان وہ باندھا کرتے تھے سب ان سے جاتا رہے گا۔', 'اور آ پڑیں اللہ کے آگے اس دن عاجز ہو کر اور بھول جائیں (جائے گی ان سے) جو جھوٹ باندھتے تھے [۱۴۴]', 'And they will offer (their full) submission to Allah (Alone) on that Day, and their invented false deities (all that they used to invoke besides Allah, e.g. idols, saints, priests, monks, angels, jinns, Jibrael (Gabriel), Messengers, etc.) will vanish from them.', 'On that day they will tender submission to Allah, and all that they used to fabricate will have vanished from them.'),
(1989, 16, 88, 12, 18, 14, 'رُبَمَا', 'النحل', 'اَلَّذِیۡنَ  کَفَرُوۡا وَ صَدُّوۡا عَنۡ سَبِیۡلِ اللّٰہِ زِدۡنٰہُمۡ عَذَابًا فَوۡقَ الۡعَذَابِ بِمَا کَانُوۡا  یُفۡسِدُوۡنَ ﴿۸۸﴾', 'جن لوگوں نے کفر کیا اور لوگوں کو اللہ کے رستے سے روکا ہم انکو عذاب پر عذاب دیں گے۔ اس لئے کہ شرارت کیا کرتے تھے۔', 'جو لوگ منکر ہوئے ہیں اور روکتے رہے ہیں اللہ کی راہ سے انکو ہم بڑھا دیں گے عذاب پر عذاب بدلہ اس کا جو شرارت کرتے تھے [۱۴۵]', 'Those who disbelieved and hinder (men) from the Path of Allah, for them We will add torment over the torment; because they used to spread corruption (by disobeying Allah themselves, as well as ordering others (mankind) to do so).', 'For those who disbelieve and put obstructions in the way of Allah, We shall add up punishment after punishment for the mischief they used to make.'),
(1990, 16, 89, 12, 18, 14, 'رُبَمَا', 'النحل', 'وَ یَوۡمَ نَبۡعَثُ فِیۡ کُلِّ اُمَّۃٍ شَہِیۡدًا عَلَیۡہِمۡ مِّنۡ اَنۡفُسِہِمۡ وَ جِئۡنَا بِکَ شَہِیۡدًا عَلٰی ہٰۤؤُلَآءِ ؕ وَ نَزَّلۡنَا عَلَیۡکَ الۡکِتٰبَ تِبۡیَانًا  لِّکُلِّ شَیۡءٍ  وَّ  ہُدًی  وَّ  رَحۡمَۃً   وَّ  بُشۡرٰی  لِلۡمُسۡلِمِیۡنَ ﴿٪۸۹﴾', 'اور اس دن کو یاد کرو جس دن ہم ہر امت میں سے خود ان پر گواہ کھڑے کریں گے۔ اور اے پیغمبر تم کو ان لوگوں پر گواہ لائیں گے۔ اور ہم نے تم پر ایسی کتاب نازل کی ہے کہ اس میں ہر چیز کا بیان مفصل ہے اور مسلمانوں کے لئے ہدایت اور رحمت اور بشارت ہے۔', 'اور جس دن کھڑا کریں گے ہم ہر فرقہ میں ایک بتلانے والا ان پر انہی میں کا اور تجھ کو لائیں بتلانے کو ان لوگوں پر [۱۴۶] اور اتاری ہم نے تجھ پر کتاب کھلا بیان ہر  چیز کا [۱۴۷] اور ہدایت اور رحمت اور خوشخبری حکم ماننے والوں کے لئے [۱۴۸]', 'And (remember) the Day when We shall raise up from every nation a witness against them from amongst themselves. And We shall bring you (O Muhammad SAW) as a witness against these. And We have sent down to you the Book (the Quran) as an exposition of everything, a guidance, a mercy, and glad tidings for those who have submitted themselves (to Allah as Muslims).', 'And (think of) the day We shall send to every people a witness from among them (to testify) against them, and We shall bring you (O prophet) as witness against these. And We have revealed to you the Book, an exposition of everything, and guidance, and mercy, and glad tidings for the Muslims.'),
(1991, 16, 90, 13, 19, 14, 'رُبَمَا', 'النحل', 'اِنَّ اللّٰہَ یَاۡمُرُ بِالۡعَدۡلِ وَ الۡاِحۡسَانِ وَ اِیۡتَآیِٔ ذِی الۡقُرۡبٰی وَ یَنۡہٰی عَنِ الۡفَحۡشَآءِ  وَ الۡمُنۡکَرِ وَ الۡبَغۡیِ ۚ یَعِظُکُمۡ   لَعَلَّکُمۡ   تَذَکَّرُوۡنَ ﴿۹۰﴾', 'اللہ انصاف اور احسان کرنے اور رشتہ داروں کو خرچ سے مدد دینے کا حکم دیتا ہے۔ اور بےحیائی اور نامعقول کاموں سے اور سرکشی سے منع کرتا ہے اور تمہیں نصیحت کرتا ہے تاکہ تم یاد رکھو۔', 'اللہ حکم کرتا ہے انصاف کرنے کا اور بھلائی کرنے کا اور قرابت والوں کے (کو) دینے کا [۱۴۹] اور منع کرتا ہے بے حیائی سے اور نامعقول کام سے اور سرکشی سے [۱۵۰] تم کو سمجھاتا ہے تاکہ تم یاد رکھو [۱۵۱]', 'Verily, Allah enjoins Al-Adl (i.e. justice and worshipping none but Allah Alone - Islamic Monotheism) and Al-Ihsan (i.e. to be patient in performing your duties to Allah, totally for Allahs sake and in accordance with the Sunnah (legal ways) of the Prophet SAW in a perfect manner), and giving (help) to kith and kin (i.e. all that Allah has ordered you to give them e.g., wealth, visiting, looking after them, or any other kind of help, etc.): and forbids Al-Fahsha (i.e all evil deeds, e.g. illegal sexual acts, disobedience of parents, polytheism, to tell lies, to give false witness, to kill a life without right, etc.), and Al-Munkar (i.e all that is prohibited by Islamic law: polytheism of every kind, disbelief and every kind of evil deeds, etc.), and Al-Baghy (i.e. all kinds of oppression), He admonishes you, that you may take heed.', 'Allah enjoins to do justice and to adopt good behavior and to give relatives (their due rights), and forbids shameful acts, evil deeds and oppressive attitude. He exhorts you, so that you may be mindful.'),
(1992, 16, 91, 13, 19, 14, 'رُبَمَا', 'النحل', 'وَ اَوۡفُوۡا بِعَہۡدِ اللّٰہِ  اِذَا عٰہَدۡتُّمۡ  وَ لَا تَنۡقُضُوا الۡاَیۡمَانَ بَعۡدَ تَوۡکِیۡدِہَا وَ قَدۡ جَعَلۡتُمُ اللّٰہَ  عَلَیۡکُمۡ  کَفِیۡلًا ؕ اِنَّ اللّٰہَ یَعۡلَمُ  مَا تَفۡعَلُوۡنَ ﴿۹۱﴾', 'اور جب اللہ سے عہد کرو تو اس کو پورا کرو اور جب پکی قسمیں کھاؤ تو انکو مت توڑو کہ تم اللہ کو اپنا ضامن مقرر کر چکے ہو اور جو کچھ تم کرتے ہو اللہ اس کو جانتا ہے۔', 'اور پورا کرو عہد اللہ کا جب آپس میں عہد کرو اور نہ توڑو قسموں کو پکا کرنے کے بعد اور تم نے کیا ہے اللہ کو اپنا ضامن اللہ جانتا ہے جو تم کرتےہو [۱۵۲]', 'And fulfill the Covenant of Allah (Baia: pledge for Islam) when you have covenanted, and break not the oaths after you have confirmed them, and indeed you have appointed Allah your surety. Verily! Allah knows what you do.', 'Fulfill the Covenant of Allah when you pledge, and do not break oaths after you swear them solemnly, while you have made Allah a witness over you. Surely, Allah knows all that you do.'),
(1993, 16, 92, 13, 19, 14, 'رُبَمَا', 'النحل', 'وَ لَا تَکُوۡنُوۡا  کَالَّتِیۡ نَقَضَتۡ غَزۡلَہَا مِنۡۢ بَعۡدِ قُوَّۃٍ  اَنۡکَاثًا ؕ تَتَّخِذُوۡنَ اَیۡمَانَکُمۡ دَخَلًۢا بَیۡنَکُمۡ اَنۡ  تَکُوۡنَ اُمَّۃٌ ہِیَ  اَرۡبٰی مِنۡ اُمَّۃٍ ؕ اِنَّمَا یَبۡلُوۡکُمُ اللّٰہُ بِہٖ ؕ وَ لَیُبَیِّنَنَّ لَکُمۡ  یَوۡمَ الۡقِیٰمَۃِ مَا کُنۡتُمۡ  فِیۡہِ  تَخۡتَلِفُوۡنَ ﴿۹۲﴾', 'اور اس عورت کی طرح نہ ہونا جس نے محنت سے تو سوت کاتا۔ پھر اسکو توڑ کر ٹکڑے ٹکڑے کر ڈالا کہ تم اپنی قسموں کو آپس میں اس بات کا ذریعہ بنانے لگو کہ ایک گروہ دوسرے گروہ سے زیادہ غالب رہے۔ بات یہ ہے کہ اللہ تمہیں اس سے آزماتا ہے اور جن باتوں میں تم اختلاف کرتے ہو قیامت کے دن اس کی حقیقت تم پر ظاہر کر دے گا۔', 'اور مت رہو جیسے وہ عورت کہ توڑا اس نے اپنا سوت کاتا ہوا محنت  (مضبوط کرنے ) کے بعد ٹکڑے ٹکڑے [۱۵۳] کہ ٹھہراؤ اپنی قسموں کو دخل دینے کا بہانہ ایک دوسرے میں (آپس میں) اس واسطے کہ ایک فرقہ ہو چڑھا ہوا دوسرے سے [۱۵۴] یہ تو اللہ پر کھتا ہے تمکو اس سے [۱۵۵] اور آئندہ کھول دے گا اللہ تم کو قیامت کے دن جس بات میں تم جھگڑ رہے تھے [۱۵۶]', 'And be not like her who undoes the thread which she has spun after it has become strong, by taking your oaths a means of deception among yourselves, lest a nation may be more numerous than another nation. Allah only tests you by this (i.e who obeys Allah and fulfills Allahs Covenant and who disobeys Allah and breaks Allahs Covenant). And on the Day of Resurrection, He will certainly make clear to you that wherein you used to differ (i.e. a believer confesses and believes in the Oneness of Allah and in the Prophethood of Prophet Muhammad SAW which the disbeliever denies it and that was their difference amongst them in the life of this world).', 'Do not be like the woman who had broken her yarn into pieces after spinning it firmly, by taking your oaths as means of mischief between yourselves, merely because a group gets greater benefit than the other. In fact, Allah puts you to a test thereby and, of course, on the Day of Resurrection He will explain to you all those matters in which you disagreed.'),
(1994, 16, 93, 13, 19, 14, 'رُبَمَا', 'النحل', 'وَ لَوۡ  شَآءَ  اللّٰہُ  لَجَعَلَکُمۡ اُمَّۃً  وَّاحِدَۃً وَّ لٰکِنۡ یُّضِلُّ مَنۡ یَّشَآءُ  وَ یَہۡدِیۡ مَنۡ یَّشَآءُ ؕ وَ لَتُسۡـَٔلُنَّ عَمَّا کُنۡتُمۡ  تَعۡمَلُوۡنَ ﴿۹۳﴾', 'اور اگر اللہ چاہتا تو تم سب کو ایک ہی جماعت بنا دیتا لیکن وہ جسے چاہتا ہے گمراہ رہنے دیتا ہے اور جسے چاہتا ہے ہدایت دیتا ہے۔ اور جو عمل تم کرتے ہو اس دن انکے بارے میں تم سے ضرور پوچھا جائے گا۔', 'اور اللہ چاہتا تو تم سب کو ایک ہی فرقہ کر دیتا ہے لیکن راہ بھلاتا ہے جس کو چاہے اور سمجھاتا ہے جس کو چاہے [۱۵۷] اور تم سے پوچھ ہو گی جو کام تم کرتے تھے [۱۵۸]', 'And had Allah willed, He could have made you (all) one nation, but He sends astray whom He wills and guides whom He wills. But you shall certainly be called to account for what you used to do.', 'If Allah so willed, He would have made all of you a single community, but He lets whom He wills go astray and takes whom He wills to the right path; and surely you will be questioned about what you used to do.'),
(1995, 16, 94, 13, 19, 14, 'رُبَمَا', 'النحل', 'وَ لَا تَتَّخِذُوۡۤا  اَیۡمَانَکُمۡ  دَخَلًۢا بَیۡنَکُمۡ فَتَزِلَّ قَدَمٌۢ  بَعۡدَ ثُبُوۡتِہَا وَ تَذُوۡقُوا السُّوۡٓءَ بِمَا صَدَدۡتُّمۡ  عَنۡ سَبِیۡلِ اللّٰہِ ۚ وَ  لَکُمۡ  عَذَابٌ عَظِیۡمٌ ﴿۹۴﴾', 'اور اپنی قسموں کو آپس میں اس بات کا ذریعہ نہ بناؤ کہ لوگوں کے قدم جم چکنے کے بعد لڑکھڑا جائیں اور اس وجہ سے کہ تم نے لوگوں کو اللہ کے رستے سے روکا۔ تم کو سزا چکھنی پڑے۔ اور تمہیں بڑا سخت عذاب ملے۔', 'اور نہ ٹھہراؤ اپنی قسموں کو دھوکا [فریب] آپس میں کہ ڈگ نہ جائے کسی کا پاؤں جمنے کے پیچھے اور تم چکھو سزا اس بات پر کہ تم نے روکا اللہ کی راہ سے اور تم کو بڑا عذاب ہو [۱۵۹]', 'And make not your oaths, a means of deception among yourselves, lest a foot may slip after being firmly planted, and you may have to taste the evil (punishment in this world) of having hindered (men) from the Path of Allah (i.e. Belief in the Oneness of Allah and His Messenger, Muhammad SAW), and yours will be a great torment (i.e. the Fire of Hell in the Hereafter).', 'Do not make your oaths a means of mischief among yourselves, lest a foot should slip after it is firmly placed, and you taste evil consequences for your having prevented (others) from the path of Allah, and you incur a great punishment.'),
(1996, 16, 95, 13, 19, 14, 'رُبَمَا', 'النحل', 'وَ لَا تَشۡتَرُوۡا بِعَہۡدِ اللّٰہِ ثَمَنًا قَلِیۡلًا ؕ اِنَّمَا عِنۡدَ اللّٰہِ ہُوَ خَیۡرٌ لَّکُمۡ اِنۡ کُنۡتُمۡ تَعۡلَمُوۡنَ ﴿۹۵﴾', 'اور اللہ سے جو تم نے عہد کیا ہے اس کو مت بیچو اور اس کے بدلے تھوڑی سی قیمت نہ لو۔ کیونکہ ایفائے عہد کا جو صلہ اللہ کے ہاں مقرر ہے وہ اگر سمجھو تو تمہارے لئے بہتر ہے۔', 'اور نہ لو اللہ کے عہد پر مول (مال) تھوڑا سا بیشک جو اللہ کے یہاں ہے وہی بہتر ہے تمہارے حق میں اگر تم جانتے ہو [۱۶۰]', 'And purchase not a small gain at the cost of Allahs Covenant. Verily! What is with Allah is better for you if you did but know.', 'And do not take a paltry price against the pledge of Allah. Indeed, what is with Allah is much better for you, if you only knew.'),
(1997, 16, 96, 13, 19, 14, 'رُبَمَا', 'النحل', 'مَا عِنۡدَکُمۡ یَنۡفَدُ وَ مَا عِنۡدَ اللّٰہِ بَاقٍ ؕ وَ لَنَجۡزِیَنَّ الَّذِیۡنَ صَبَرُوۡۤا اَجۡرَہُمۡ بِاَحۡسَنِ مَا  کَانُوۡا یَعۡمَلُوۡنَ ﴿۹۶﴾', 'جو کچھ تمہارے پاس ہے وہ ختم ہو جاتا ہے اور جو اللہ کے پاس ہے وہ باقی ہے کہ کبھی ختم نہیں ہو گا اور جن لوگوں نے صبر کیا ہم انکو ان کے اعمال کا بہت اچھا بدلہ دیں گے۔', 'جو تمہارے پاس ہے ختم ہو جائے گا اور جو اللہ کے پاس ہے کبھی ختم نہ ہو گا (سو رہنے والا ہے) [۱۶۱] اور ہم بدلے میں دیں گے صبر کرنے والوں کو ان کا حق اچھے کاموں پر جو کرتے تھے [۱۶۲]', 'Whatever is with you, will be exhausted, and whatever with Allah (of good deeds) will remain. And those who are patient, We will certainly pay them a reward in proportion to the best of what they used to do.', 'What is with you shall perish and what is with Allah shall last. And certainly, We shall bless those who observed patience, with their reward for the best of what they used to do.'),
(1998, 16, 97, 13, 19, 14, 'رُبَمَا', 'النحل', 'مَنۡ عَمِلَ صَالِحًا مِّنۡ ذَکَرٍ اَوۡ اُنۡثٰی وَ ہُوَ مُؤۡمِنٌ فَلَنُحۡیِیَنَّہٗ  حَیٰوۃً  طَیِّبَۃً ۚ وَ لَنَجۡزِیَنَّہُمۡ اَجۡرَہُمۡ بِاَحۡسَنِ مَا کَانُوۡا یَعۡمَلُوۡنَ ﴿۹۷﴾', 'جو شخص نیک اعمال کرے گا مرد ہو یا عورت اور وہ مومن بھی ہو گا تو ہم اسکو دنیا میں پاک زندگی بسر کروائیں گے اور آخرت میں انکے اعمال کا نہایت اچھا صلہ دیں گے۔', 'جس نے کیا نیک کام مرد ہو یا عورت ہو اور وہ ایمان پر ہے تو اس کو ہم زندگی دیں گے ایک اچھی زندگی [۱۶۳] اور بدلے میں دیں گے ان کو حق ان کا بہتر کاموں پر جو کرتے تھے', 'Whoever works righteousness, whether male or female, while he (or she) is a true believer (of Islamic Monotheism) verily, to him We will give a good life (in this world with respect, contentment and lawful provision), and We shall pay them certainly a reward in proportion to the best of what they used to do (i.e. Paradise in the Hereafter).', 'Whoever, male or female, has acted righteously, while being a believer, We shall certainly make him live a good life, and shall give such people their reward for the best of what they used to do.'),
(1999, 16, 98, 13, 19, 14, 'رُبَمَا', 'النحل', 'فَاِذَا  قَرَاۡتَ الۡقُرۡاٰنَ  فَاسۡتَعِذۡ بِاللّٰہِ مِنَ  الشَّیۡطٰنِ  الرَّجِیۡمِ ﴿۹۸﴾', 'سو جب تم قرآن پڑھنے لگو تو شیطان مردود سے اللہ کی پناہ مانگ لیا کرو۔', 'سو جب تو پڑھنے لگے قرآن تو پناہ لے اللہ کی شیطان مردود سے [۱۶۴]', 'So when you want to recite the Quran, seek refuge with Allah from Shaitan (Satan), the outcast (the cursed one).', 'So, when you recite the Qur’ān, seek refuge with Allah against Satan, the accursed.'),
(2000, 16, 99, 13, 19, 14, 'رُبَمَا', 'النحل', 'اِنَّہٗ  لَیۡسَ لَہٗ  سُلۡطٰنٌ عَلَی الَّذِیۡنَ اٰمَنُوۡا  وَ عَلٰی  رَبِّہِمۡ  یَتَوَکَّلُوۡنَ ﴿۹۹﴾', 'حقیقت یہ ہے کہ جو مومن ہیں اور اپنے پروردگار پر بھروسہ رکھتے ہیں ان پر اس کا کچھ زور نہیں چلتا۔', 'اس کا زور نہیں چلتا ان پر جو ایمان رکھتے ہیں اور اپنے رب پر بھروسہ کرتے ہیں [۱۶۵]', 'Verily! He has no power over those who believe and put their trust only in their Lord (Allah).', 'He is such that he has no authority over those who believe and place trust in their Lord.'),
(2001, 16, 100, 13, 19, 14, 'رُبَمَا', 'النحل', 'اِنَّمَا سُلۡطٰنُہٗ  عَلَی الَّذِیۡنَ یَتَوَلَّوۡنَہٗ وَ الَّذِیۡنَ  ہُمۡ  بِہٖ  مُشۡرِکُوۡنَ ﴿۱۰۰﴾٪', 'اس کا زور انہی لوگوں پر چلتا ہے جو اسکو رفیق بناتے ہیں اور اسکے وسوسے کے سبب اللہ کے ساتھ شریک مقرر کرتے ہیں۔', 'اس کا زور تو انہی پر ہے جو اس کو رفیق سمجھتے ہیں اور جو اسکو شریک مانتے ہیں [۱۶۶]', 'His power is only over those who obey and follow him (Satan), and those who join partners with Him (Allah) (i.e. those who are Mushrikoon - polytheists - see Verse 6:121).', 'His authority is only over those who befriend him and those who associate partners with Allah.'),
(2002, 16, 101, 14, 20, 14, 'رُبَمَا', 'النحل', 'وَ اِذَا بَدَّلۡنَاۤ  اٰیَۃً  مَّکَانَ اٰیَۃٍ ۙ وَّ اللّٰہُ اَعۡلَمُ  بِمَا یُنَزِّلُ قَالُوۡۤا  اِنَّمَاۤ   اَنۡتَ مُفۡتَرٍ ؕ بَلۡ   اَکۡثَرُہُمۡ  لَا یَعۡلَمُوۡنَ  ﴿۱۰۱﴾', 'اور جب ہم کوئی آیت کسی آیت کی جگہ بدل دیتے ہیں۔ اور اللہ جو کچھ نازل فرماتا ہے اسے خوب جانتا ہے تو کافر کہتے ہیں کہ تم تو اپنی طرف سے بنا لاتے ہو حقیقت یہ ہے کہ ان میں اکثر نادان ہیں۔', 'اور جب ہم بدلتے ہیں ایک آیت کی جگہ دوسری آیت اور اللہ خوب جانتا ہے جو اتارتا ہے تو کہتے ہیں تو تو بنا لاتا ہے یہ بات نہیں پر اکثروں کو ان میں خبر نہیں [۱۶۷]', 'And when We change a Verse (of the Quran, i.e. cancel (abrogate) its order) in place of another, and Allah knows the best of what He sends down, they (the disbelievers) say: \"You (O Muhammad SAW) are but a Muftari! (forger, liar).\" Nay, but most of them know not.', 'Whenever We replace a verse with another verse - and Allah knows well what He reveals - they say, “You are but a forger.” The fact rather is that most of them are ignorant.'),
(2003, 16, 102, 14, 20, 14, 'رُبَمَا', 'النحل', 'قُلۡ نَزَّلَہٗ  رُوۡحُ الۡقُدُسِ مِنۡ رَّبِّکَ بِالۡحَقِّ  لِیُـثَبِّتَ الَّذِیۡنَ اٰمَنُوۡا  وَ ہُدًی  وَّ  بُشۡرٰی  لِلۡمُسۡلِمِیۡنَ ﴿۱۰۲﴾', 'کہدو کہ اسکو روح القدس تمہارے پروردگار کی طرف سے سچائی کے ساتھ لے کر نازل ہوئے ہیں تاکہ یہ قرآن مومنوں کو ثابت قدم رکھے اور حکم ماننے والوں کے لئے تو یہ ہدایت اور بشارت ہے۔', 'تو کہہ اس کو اتارا ہے پاک فرشتے نے تیرے رب کی طرف سے بلاشبہ [۱۶۸] تاکہ ثابت کرے ایمان والوں کو اور ہدایت اور خوشخبری مسلمانوں کے واسطے [۱۶۹]', 'Say (O Muhammad SAW) Ruh-ul-Qudus (Jibrael (Gabriel)) has brought it (the Quran) down from your Lord with truth, that it may make firm and strengthen (the Faith of) those who believe and as a guidance and glad tidings to those who have submitted (to Allah as Muslims).', 'Say, “This has been brought down by RūH-ul-Qudus (the Holy Spirit - Jibra’īl ) from your Lord rightly (as due), so that it may bring firmness to the believers and become guidance and good news for the Muslims.'),
(2004, 16, 103, 14, 20, 14, 'رُبَمَا', 'النحل', 'وَ لَقَدۡ نَعۡلَمُ  اَنَّہُمۡ  یَقُوۡلُوۡنَ  اِنَّمَا  یُعَلِّمُہٗ بَشَرٌ ؕ لِسَانُ الَّذِیۡ یُلۡحِدُوۡنَ  اِلَیۡہِ اَعۡجَمِیٌّ  وَّ ہٰذَا لِسَانٌ عَرَبِیٌّ  مُّبِیۡنٌ ﴿۱۰۳﴾', 'اور ہمیں معلوم ہے کہ یہ کہتے ہیں کہ اس پیغمبر کو ایک شخص سکھا جاتا ہے۔ مگر جس کی طرف تعلیم کی نسبت کرتے ہیں اسکی زبان تو عجمی ہے اور یہ صاف عربی زبان ہے۔', 'اور ہم کو خوب معلوم  ہے کہ وہ کہتے ہیں اس کو تو سکھلاتا ہے ایک آدمی [۱۷۰] جس کی طرف تعریض کرتے ہیں اس کی زبان ہے عجمی اور یہ قرآن زبان عربی ہے صاف [۱۷۱]', 'And indeed We know that they (polytheists and pagans) say: \"It is only a human being who teaches him (Muhammad SAW).\" The tongue of the man they refer to is foreign, while this (the Quran) is a clear Arabic tongue.', 'We know well that they say, “There is a man who teaches him.” The language of the one they refer to is non-Arabic while this is clear Arabic language.'),
(2005, 16, 104, 14, 20, 14, 'رُبَمَا', 'النحل', 'اِنَّ الَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِاٰیٰتِ اللّٰہِ ۙ لَا یَہۡدِیۡہِمُ  اللّٰہُ  وَ لَہُمۡ  عَذَابٌ  اَلِیۡمٌ ﴿۱۰۴﴾', 'جو لوگ اللہ کی آیتوں پر ایمان نہیں لاتے ان کو اللہ ہدایت نہیں دیتا اور انکے لئے عذاب الیم ہے۔', 'وہ لوگ جن کو اللہ کی باتوں پر یقین نہیں ان کو اللہ راہ نہیں دیتا اور ان کےلئے عذاب دردناک ہے  [۱۷۲]', 'Verily! Those who believe not in the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah, Allah will not guide them and theirs will be a painful torment.', 'Surely, those who do not believe in Allah’s verses, Allah does not lead them to the right path, and for them there is a painful punishment.'),
(2006, 16, 105, 14, 20, 14, 'رُبَمَا', 'النحل', 'اِنَّمَا یَفۡتَرِی الۡکَذِبَ الَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِاٰیٰتِ اللّٰہِ ۚ وَ اُولٰٓئِکَ ہُمُ الۡکٰذِبُوۡنَ ﴿۱۰۵﴾', 'جھوٹ تو وہی لوگ باندھا کرتے ہیں جو اللہ کی آیتوں پر ایمان نہیں لاتے اور وہی جھوٹے ہیں۔', 'جھوٹ تو وہ لوگ بناتے ہیں جن کو یقین نہیں اللہ کی باتوں پر اور وہی لوگ جھوٹے ہیں [۱۷۳]', 'It is only those who believe not in the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah, who fabricate falsehood, and it is they who are liars.', 'It is (not the Prophet but) the disbelievers in Allah’s verses who forge lies, and it is they who are the liars.'),
(2007, 16, 106, 14, 20, 14, 'رُبَمَا', 'النحل', 'مَنۡ کَفَرَ بِاللّٰہِ مِنۡۢ بَعۡدِ  اِیۡمَانِہٖۤ  اِلَّا مَنۡ اُکۡرِہَ  وَ  قَلۡبُہٗ  مُطۡمَئِنٌّۢ  بِالۡاِیۡمَانِ وَ لٰکِنۡ مَّنۡ شَرَحَ بِالۡکُفۡرِ صَدۡرًا فَعَلَیۡہِمۡ غَضَبٌ مِّنَ اللّٰہِ ۚ وَ لَہُمۡ عَذَابٌ عَظِیۡمٌ ﴿۱۰۶﴾', 'جو شخص ایمان لانے کے بعد اللہ کے ساتھ کفر کرے وہ نہیں جو کفر پر زبردستی مجبور کیا جائے اور اس کا دل ایمان کے ساتھ مطمئن ہو۔ بلکہ وہ جو دل سے اور دل کھول کر کفر کرے۔ تو ایسوں پر اللہ کا غضب ہے اور انکو بڑا سخت عذاب ہو گا۔', 'جو کوئی منکر ہوا اللہ سے یقین لانے کے پیچھے مگر وہ نہیں جس پر زبردستی کی گئ اور اس کا دل برقرار ہے ایمان پر [۱۷۴] و لیکن جو کوئی دل کھول کر منکر ہوا سو ان پر غضب ہے اللہ کا اور ان کو بڑا عذاب ہے', 'Whoever disbelieved in Allah after his belief, except him who is forced thereto and whose heart is at rest with Faith but such as open their breasts to disbelief, on them is wrath from Allah, and theirs will be a great torment.', 'Whoever rejects his faith in Allah after having believed in Him - not the one who is compelled (to utter a word of disbelief) under duress while his heart is at peace with Faith, but the one who has laid his breast wide open for disbelief - upon such people is the wrath of Allah, and for them there is a heavy punishment.'),
(2008, 16, 107, 14, 20, 14, 'رُبَمَا', 'النحل', 'ذٰلِکَ بِاَنَّہُمُ اسۡتَحَبُّوا الۡحَیٰوۃَ الدُّنۡیَا عَلَی الۡاٰخِرَۃِ ۙ وَ اَنَّ اللّٰہَ  لَا یَہۡدِی الۡقَوۡمَ  الۡکٰفِرِیۡنَ ﴿۱۰۷﴾', 'یہ اس لئے کہ انہوں نے دنیا کی زندگی کو آخرت کے مقابلے میں عزیز تر رکھا۔ اور اس لئے کہ اللہ کافر لوگوں کو ہدایت نہیں دیتا۔', 'یہ اس واسطے کہ انہوں نے عزیز رکھا دنیا کی زندگی کو آخرت سے اور اللہ راستہ نہیں دیتا منکر لوگوں کو [۱۷۵]', 'That is because they loved and preferred the life of this world over that of the Hereafter. And Allah guides not the people who disbelieve.', 'That is because they have preferred the worldly life to the Hereafter, and that Allah does not lead the disbelieving people to the right path.'),
(2009, 16, 108, 14, 20, 14, 'رُبَمَا', 'النحل', 'اُولٰٓئِکَ الَّذِیۡنَ طَبَعَ اللّٰہُ عَلٰی قُلُوۡبِہِمۡ وَ سَمۡعِہِمۡ وَ اَبۡصَارِہِمۡ ۚ وَ اُولٰٓئِکَ ہُمُ الۡغٰفِلُوۡنَ ﴿۱۰۸﴾', 'یہی لوگ ہیں جنکے دلوں پر اور کانوں پر اور آنکھوں پر اللہ نے مہر لگا رکھی ہے اور یہی غفلت میں پڑے ہوئے ہیں۔', 'یہ وہی ہیں کہ مہر کر دی اللہ نے ان کے دل پر اور کانوں پر اور آنکھوں پر اور یہی ہیں بے ہوش [۱۷۶]', 'They are those upon whose hearts, hearing (ears) and sight (eyes) Allah has set a seal. And they are the heedless!', 'Those are the ones Allah has set a seal on whose hearts, ears and eyes; and they are the heedless.'),
(2010, 16, 109, 14, 20, 14, 'رُبَمَا', 'النحل', 'لَاجَرَمَ  اَنَّہُمۡ  فِی الۡاٰخِرَۃِ   ہُمُ  الۡخٰسِرُوۡنَ ﴿۱۰۹﴾', 'کچھ شک نہیں کہ آخرت میں یہی لوگ خسارہ پانے والے ہوں گے۔', 'خود ظاہر ہے کہ آخرت میں یہی لوگ خراب ہیں [۱۷۷]', 'No doubt, in the Hereafter, they will be the losers.', 'Invariably, they are the losers in the Hereafter.'),
(2011, 16, 110, 14, 20, 14, 'رُبَمَا', 'النحل', 'ثُمَّ  اِنَّ رَبَّکَ لِلَّذِیۡنَ ہَاجَرُوۡا مِنۡۢ بَعۡدِ مَا فُتِنُوۡا ثُمَّ جٰہَدُوۡا وَ صَبَرُوۡۤا ۙ اِنَّ رَبَّکَ مِنۡۢ  بَعۡدِہَا  لَغَفُوۡرٌ  رَّحِیۡمٌ ﴿۱۱۰﴾٪', 'پھر جن لوگوں نے ایذائیں اٹھانے کے بعد ترک وطن کیا۔ پھر جہاد کیا اور ثابت قدم رہے تمہارا پروردگار انکو بیشک ان آزمائشوں کے بعد بخشنے والا ہے رحمت کرنے والا ہے۔', 'پھر بات یہ ہے کہ تیرا رب ان لوگوں پر کہ انہوں نے وطن چھوڑا ہے بعد اس کے مصیبت (بچلائے گئے) اٹھائی پھر جہاد کرتے رہے اور قائم رہے بیشک تیرا رب ان باتوں کے بعد بخشنے والا مہربان ہے [۱۷۸]', 'Then, verily! Your Lord for those who emigrated after they had been put to trials and thereafter strove hard and fought (for the Cause of Allah) and were patient, verily, your Lord afterward is, Oft-Forgiving, Most Merciful.', 'Then, your Lord - for those who left their homes after being persecuted, then fought in the way of Allah and stood patient - surely your Lord is, after all that, Most-Forgiving, Very-Merciful.'),
(2012, 16, 111, 15, 21, 14, 'رُبَمَا', 'النحل', 'یَوۡمَ تَاۡتِیۡ کُلُّ نَفۡسٍ تُجَادِلُ عَنۡ نَّفۡسِہَا وَ تُوَفّٰی کُلُّ نَفۡسٍ مَّا  عَمِلَتۡ وَ  ہُمۡ لَا  یُظۡلَمُوۡنَ ﴿۱۱۱﴾', 'جس دن ہر شخص اپنی طرف سے جھگڑا کرنے آئے گا۔ اور ہر شخص کو اسکے اعمال کا پورا پورا بدلہ دیا جائے گا اور کسی کا نقصان نہیں کیا جائے گا۔', 'جس دن آئے گا ہر جی جواب سوال کرتا اپنی طرف سے [۱۷۹] اور پورا ملے گا ہر کسی کو جو اس نے کمایا اور ان پر ظلم نہ ہو گا [۱۸۰]', '(Remember) the Day when every person will come up pleading for himself, and every one will be paid in full for what he did (good or evil, belief or disbelief in the life of this world) and they will not be dealt with unjustly.', '(All this will happen) on the day when everyone will come pleading for himself, and everyone will be given in full what he did, and they will not be wronged.'),
(2013, 16, 112, 15, 21, 14, 'رُبَمَا', 'النحل', 'وَ ضَرَبَ اللّٰہُ مَثَلًا قَرۡیَۃً کَانَتۡ اٰمِنَۃً مُّطۡمَئِنَّۃً یَّاۡتِیۡہَا رِزۡقُہَا رَغَدًا مِّنۡ کُلِّ مَکَانٍ فَکَفَرَتۡ بِاَنۡعُمِ اللّٰہِ فَاَذَاقَہَا اللّٰہُ لِبَاسَ الۡجُوۡعِ وَ الۡخَوۡفِ بِمَا  کَانُوۡا  یَصۡنَعُوۡنَ ﴿۱۱۲﴾', 'اور اللہ ایک بستی کی مثال بیان فرماتا ہے جو کہ ہر طرح امن چین سے تھی ہر طرف سے اس کا رزق با فراغت چلا آتا تھا۔ مگر ان لوگوں نے اللہ کی نعمتوں کی ناشکری کی تو اللہ نے انکے اعمال کے سبب انکو بھوک اور خوف کا لباس پہنا کر ناشکری کا مزہ چکھا دیا۔', 'اور بتلائی اللہ نے ایک مثال (مثل) ایک بستی تھی چین امن سے [۱۸۱] چلی آتی تھی اسکو روزی فراغت کی ہر جگہ سے [۱۸۲] پھر ناشکری کی اللہ کے احسانوں کی پھر چکھایا اس کو اللہ نے مزہ کہ ان کے تن کے کپڑے ہو گئے بھوک اور ڈر بدلہ اس کا جو وہ کرتے تھے [۱۸۳]', 'And Allah puts forward the example of a township (Makkah), that dwelt secure and well content; its provision coming to it in abundance from every place, but it (its people) denied the Favours of Allah (with ungratefulness). So Allah made it taste the extreme of hunger (famine) and fear, because of that (evil, i.e. denying Prophet Muhammad SAW) which they (its people) used to do.', 'Allah gives an example: There was a town, secure and content with its sustenance coming in plenty from every place. Then, it turned ungrateful to the bounties of Allah; so, Allah made it to taste hunger and terror (that covered it) like a garment, as recompense of what its people used to do.'),
(2014, 16, 113, 15, 21, 14, 'رُبَمَا', 'النحل', 'وَ لَقَدۡ جَآءَہُمۡ رَسُوۡلٌ مِّنۡہُمۡ فَکَذَّبُوۡہُ فَاَخَذَہُمُ  الۡعَذَابُ  وَ ہُمۡ  ظٰلِمُوۡنَ ﴿۱۱۳﴾', 'اور انکے پاس انہی میں سے ایک پیغمبر آیا تو انہوں نے اس کو جھٹلایا سو ان کو عذاب نے آ پکڑا اور وہ ظالم تھے۔', 'اور ان کے پاس پہنچ چکا رسول انہی میں کا پھر اس کو جھٹلایا پھر آ پکڑا انکو عذاب نے اور وہ گنہگار تھے [۱۸۴]', 'And verily, there had come unto them a Messenger (Muhammad SAW) from among themselves, but they denied him, so the torment overtook them while they were Zalimoon (polytheists and wrong-doers, etc.).', 'And, of course, a messenger from among themselves had come to them, but they rejected him; so the punishment seized them when they were wrongdoers.'),
(2015, 16, 114, 15, 21, 14, 'رُبَمَا', 'النحل', 'فَکُلُوۡا مِمَّا رَزَقَکُمُ اللّٰہُ حَلٰلًا طَیِّبًا ۪ وَّ اشۡکُرُوۡا نِعۡمَتَ اللّٰہِ  اِنۡ  کُنۡتُمۡ  اِیَّاہُ تَعۡبُدُوۡنَ ﴿۱۱۴﴾', 'پس اللہ نے جو تم کو حلال طیب رزق دیا ہے اسے کھاؤ اور اللہ کی نعمتوں کا شکر بھی کرو۔ اگر اسی کی عبادت کرتے ہو۔', 'سو کھاؤ جو روزی دی تم کو اللہ نے حلال اور پاک اور شکر کرو اللہ کے احسان کا اگر تم اسی کو پوجتے ہو [۱۸۵]', 'So eat of the lawful and good food which Allah has provided for you. And be grateful for the Graces of Allah, if it is He Whom you worship.', 'So, eat the permissible and pure things from what Allah has provided you, and be grateful for the bounty of Allah, if you worship Him alone.'),
(2016, 16, 115, 15, 21, 14, 'رُبَمَا', 'النحل', 'اِنَّمَا حَرَّمَ عَلَیۡکُمُ الۡمَیۡتَۃَ  وَ الدَّمَ وَ  لَحۡمَ  الۡخِنۡزِیۡرِ  وَ  مَاۤ   اُہِلَّ  لِغَیۡرِ  اللّٰہِ بِہٖ ۚ فَمَنِ اضۡطُرَّ  غَیۡرَ  بَاغٍ  وَّ لَا  عَادٍ  فَاِنَّ  اللّٰہَ  غَفُوۡرٌ  رَّحِیۡمٌ ﴿۱۱۵﴾', 'اس نے تم پر مردار اور لہو اور سور کا گوشت حرام کر دیا ہے اور جس چیز پر اللہ کے سوا کسی اور کا نام پکارا جائے اس کو بھی ہاں اگر کوئی ناچار ہو جائے تو بشرطیکہ گناہ کرنے والا نہ ہو اور نہ حد سے نکلنے والا تو اللہ بخشنے والا ہے مہربان ہے۔', 'اللہ نے تو یہی حرام کیا ہےتم پر مردار اور لہو اور سور کا گوشت اور جس پر نام پکارا اللہ کے سوا کسی اور کا پھر جو کوئی ناچار ہو جائے نہ زور کرتا ہو نہ زیادتی تو اللہ بخشنے والا مہربان ہے [۱۸۶]', 'He has forbidden you only Al-Maytatah (meat of a dead animal), blood, the flesh of swine, and any animal which is slaughtered as a sacrifice for others than Allah (or has been slaughtered for idols etc. or on which Allahs Name has not been mentioned while slaughtering). But if one is forced by necessity, without wilful disobedience, and not transgressing, then, Allah is Oft-Forgiving, Most Merciful.', 'He has but prohibited for you the carrion, the blood, the flesh of swine and what has been invoked upon with a name other than that of Allah. However, if anyone is compelled by necessity - neither seeking pleasure, nor crossing the limit (of necessity) - then, Allah is Most-Forgiving, Very-Merciful.'),
(2017, 16, 116, 15, 21, 14, 'رُبَمَا', 'النحل', 'وَ لَا تَقُوۡلُوۡا لِمَا تَصِفُ اَلۡسِنَتُکُمُ الۡکَذِبَ ہٰذَا حَلٰلٌ وَّ ہٰذَا حَرَامٌ لِّتَفۡتَرُوۡا عَلَی اللّٰہِ  الۡکَذِبَ ؕ اِنَّ  الَّذِیۡنَ یَفۡتَرُوۡنَ عَلَی اللّٰہِ الۡکَذِبَ لَا یُفۡلِحُوۡنَ ﴿۱۱۶﴾ؕ', 'اور یونہی جھوٹ جو تمہاری زبان پر آ جائے مت کہدیا کرو کہ یہ حلال ہے اور یہ حرام ہے۔ تاکہ اللہ پر جھوٹ باندھنے لگو۔ جو لوگ اللہ پر جھوٹ باندھتے ہیں۔ ان کا بھلا نہیں ہو گا۔', 'اور مت کہو اپنی زبانوں کے جھوٹ بنا لینے سے کہ یہ حلال ہے اور یہ حرام ہے کہ اللہ پر بہتان باندھو [۱۸۷] بیشک جو بہتان باندھتے ہیں اللہ پر ان کا بھلا نہ ہو گا', 'And say not concerning that which your tongues put forth falsely: \"This is lawful and this is forbidden,\" so as to invent lies against Allah. Verily, those who invent lies against Allah will never prosper.', 'Do not say about what your tongues describe falsely, “This is lawful and that is unlawful” so that you may forge the lie upon Allah. Surely, those who forge a lie upon Allah do not prosper.'),
(2018, 16, 117, 15, 21, 14, 'رُبَمَا', 'النحل', 'مَتَاعٌ   قَلِیۡلٌ ۪ وَّ لَہُمۡ عَذَابٌ اَلِیۡمٌ ﴿۱۱۷﴾', 'جھوٹ کا فائدہ تو تھوڑا سا ہے مگر اس کے بدلے انکو عذاب الیم بہت ہو گا۔', 'تھوڑا سا فائدہ اٹھا لیں اور ان کےواسطے عذاب دردناک ہے [۱۸۸]', 'A passing brief enjoyment (will be theirs), but they will have a painful torment.', '(Let there be) a little enjoyment, and (then) for them there is a painful punishment.'),
(2019, 16, 118, 15, 21, 14, 'رُبَمَا', 'النحل', 'وَ عَلَی الَّذِیۡنَ ہَادُوۡا حَرَّمۡنَا مَا قَصَصۡنَا عَلَیۡکَ مِنۡ قَبۡلُ ۚ وَ مَا ظَلَمۡنٰہُمۡ وَ لٰکِنۡ کَانُوۡۤا  اَنۡفُسَہُمۡ یَظۡلِمُوۡنَ ﴿۱۱۸﴾', 'اور جو چیزیں ہم تم سے پہلے بیان کر چکے ہیں وہ ہم نے یہودیوں پر حرام کر دی تھیں۔ اور ہم نے ان پر کچھ ظلم نہیں کیا بلکہ وہی اپنے آپ پر ظلم کرتے تھے۔', 'اور جو لوگ یہودی ہیں ان پر ہم نے حرام کیا تھا جو تجھ کو پہلے سنا چکے اور ہم نے ان پر ظلم نہیں کیا پر وہ اپنے اوپر آپ ظلم کرتے تھے [۱۸۹]', 'And unto those who are Jews, We have forbidden such things as We have mentioned to you (O Muhammad SAW) before (in Soorat-Al-Anam, (The Cattle), see Verse 6:146). And We wronged them not, but they used to wrong themselves.', 'For those who are Jews, We had prohibited that which We have already told you; and We did not wrong them, but it was they who used to wrong themselves.'),
(2020, 16, 119, 15, 21, 14, 'رُبَمَا', 'النحل', 'ثُمَّ  اِنَّ رَبَّکَ لِلَّذِیۡنَ عَمِلُوا السُّوۡٓءَ بِجَہَالَۃٍ  ثُمَّ تَابُوۡا مِنۡۢ  بَعۡدِ ذٰلِکَ وَ اَصۡلَحُوۡۤا ۙ اِنَّ رَبَّکَ مِنۡۢ بَعۡدِہَا لَغَفُوۡرٌ رَّحِیۡمٌ ﴿۱۱۹﴾٪', 'پھر جن لوگوں نے نادانی سے غلط کام کر لیا۔ پھر اس کے بعد توبہ کی اور نیکوکار ہو گئے تو تمہارا پروردگار انکو توبہ کرنے اور نیکوکار ہو جانے کے بعد بخشنے والا ہے رحمت کرنے والا ہے۔', 'پھر بات یہ ہے کہ تیرا رب ان لوگوں پر جنہوں نے برائی کی نادانی سے [۱۹۰] پھر توبہ کی اس کے  پیچھے اور سنوارا اپنے کام کو سو تیرا رب ان باتوں کے پیچھے بخشنے والا مہربان ہے [۱۹۱]', 'Then, verily! Your Lord for those who do evil (commit sins and are disobedient to Allah) in ignorance and afterward repent and do righteous deeds, verily, your Lord thereafter, (to such) is Oft-Forgiving, Most Merciful.', 'Then your Lord - for those who did evil because of ignorance, then repented after that and corrected themselves - surely your Lord is, after all that, Most-Forgiving, Very-Merciful.'),
(2021, 16, 120, 16, 22, 14, 'رُبَمَا', 'النحل', 'اِنَّ  اِبۡرٰہِیۡمَ کَانَ اُمَّۃً  قَانِتًا لِّلّٰہِ حَنِیۡفًا ؕ وَ لَمۡ یَکُ مِنَ الۡمُشۡرِکِیۡنَ ﴿۱۲۰﴾ۙ', 'بیشک ابراہیم لوگوں کے امام اور اللہ کے فرمانبردار تھے۔ جو ایک طرف کے ہو رہے تھے اور مشرکوں میں سے نہ تھے۔', 'اصل میں تو ابراہیم تھا راہ ڈالنے والا فرمانبردار  اللہ کا سب سے ایک طرف ہو کر اور نہ تھا شرک والوں میں [۱۹۲]', 'Verily, Ibrahim (Abraham) was an Ummah (a leader having all the good righteous qualities), or a nation, obedient to Allah, Hanifa (i.e. to worship none but Allah), and he was not one of those who were Al-Mushrikoon (polytheists, idolaters, disbelievers in the Oneness of Allah, and those who joined partners with Allah).', 'Surely, Ibrāhīm was an Ummah (a whole community in himself), devoted to Allah, a man of pure faith; and he was not among the Mushriks (i.e. those who associate partners with Allah)'),
(2022, 16, 121, 16, 22, 14, 'رُبَمَا', 'النحل', 'شَاکِرًا  لِّاَنۡعُمِہٖ ؕ اِجۡتَبٰہُ وَ ہَدٰىہُ  اِلٰی  صِرَاطٍ  مُّسۡتَقِیۡمٍ ﴿۱۲۱﴾', 'اس کی نعمتوں کے شکرگذار تھے۔ اللہ نے ان کو برگذیدہ کیا تھا اور اپنی سیدھی راہ پر چلایا تھا۔', 'حق ماننے والا اس کے احسانوں کا [۱۹۳] اس کو اللہ نے چن لیا اور چلایا سیدھی راہ پر [۱۹۴]', '(He was) thankful for His (Allahs) Graces. He (Allah) chose him (as an intimate friend) and guided him to a Straight Path (Islamic Monotheism, neither Judaism nor Christianity).', 'He was grateful to His bounties. He (Allah) chose him and led him to the straight path.'),
(2023, 16, 122, 16, 22, 14, 'رُبَمَا', 'النحل', 'وَ اٰتَیۡنٰہُ  فِی الدُّنۡیَا حَسَنَۃً ؕ وَ  اِنَّہٗ  فِی الۡاٰخِرَۃِ   لَمِنَ  الصّٰلِحِیۡنَ ﴿۱۲۲﴾ؕ', 'اور ہم نے ان کو دنیا میں بھی خوبی دی تھی۔ اور وہ آخرت میں بھی نیک لوگوں میں ہوں گے۔', 'اور دی ہم نے دنیا میں اس کو خوبی [۱۹۵] اور وہ آخرت میں اچھے لوگوں میں ہے [۱۹۶]', 'And We gave him good in this world, and in the Hereafter he shall be of the righteous.', 'We bestowed good upon him in this world; and in the Hereafter, he is among the righteous.'),
(2024, 16, 123, 16, 22, 14, 'رُبَمَا', 'النحل', 'ثُمَّ اَوۡحَیۡنَاۤ  اِلَیۡکَ اَنِ اتَّبِعۡ مِلَّۃَ  اِبۡرٰہِیۡمَ حَنِیۡفًا ؕ وَ مَا کَانَ مِنَ الۡمُشۡرِکِیۡنَ ﴿۱۲۳﴾', 'پھر اے نبی ہم نے تمہاری طرف وحی بھیجی کہ دین ابراہیم کی پیروی کرو جو ایک طرف کے ہو رہے تھے اور مشرکوں میں سے نہ تھے۔', 'پھر حکم بھیجا ہم نے تجھ کو کہ چل دین ابراہیم پر جو ایک طرف کا تھا اور نہ تھا وہ شرک والوں میں [۱۹۷]', 'Then, We have inspired you (O Muhammad SAW saying): \"Follow the religion of Ibrahim (Abraham) Hanifa (Islamic Monotheism - to worship none but Allah) and he was not of the Mushrikoon (polytheists, idolaters, disbelievers, etc.).', 'Then, We revealed to you, “Follow the way of Ibrāhīm, the upright, and he was not among the Mushriks”.'),
(2025, 16, 124, 16, 22, 14, 'رُبَمَا', 'النحل', 'اِنَّمَا جُعِلَ السَّبۡتُ عَلَی الَّذِیۡنَ اخۡتَلَفُوۡا فِیۡہِ ؕ وَ اِنَّ رَبَّکَ لَیَحۡکُمُ بَیۡنَہُمۡ یَوۡمَ الۡقِیٰمَۃِ  فِیۡمَا کَانُوۡا فِیۡہِ یَخۡتَلِفُوۡنَ ﴿۱۲۴﴾', 'ہفتے کا دن تو انہی لوگوں پر مقرر کیا گیا تھا جنہوں نے اس میں اختلاف کیا۔ اور تمہارا پروردگار قیامت کے دن ان میں ان باتوں کا فیصلہ کر دے گا جن میں وہ اختلاف کرتے تھے۔', 'ہفتہ کا دن جو مقرر کیا سو انہی پر جو اس میں اختلاف کرتے تھے اور تیرا رب حکم کرے گا ان میں قیامت کے دن جس بات میں اختلاف کرتے تھے [۱۹۸]', 'The Sabbath was only prescribed for those who differed concerning it, and verily, your Lord will judge between them on the Day of Resurrection about that wherein they used to differ.', 'The Sabbath was prescribed only for those people (i.e. Jews) who differed in it, and your Lord will certainly judge between them on the Day of Resurrection in those matters in which they used to differ.'),
(2026, 16, 125, 16, 22, 14, 'رُبَمَا', 'النحل', 'اُدۡعُ  اِلٰی سَبِیۡلِ رَبِّکَ بِالۡحِکۡمَۃِ وَ الۡمَوۡعِظَۃِ  الۡحَسَنَۃِ وَ جَادِلۡہُمۡ بِالَّتِیۡ ہِیَ اَحۡسَنُ ؕ اِنَّ رَبَّکَ ہُوَ اَعۡلَمُ بِمَنۡ ضَلَّ عَنۡ سَبِیۡلِہٖ  وَ ہُوَ  اَعۡلَمُ بِالۡمُہۡتَدِیۡنَ ﴿۱۲۵﴾', 'اے پیغمبر لوگوں کو حکمت اور نیک نصیحت سے اپنے پروردگار کے رستے کی طرف بلاؤ۔ اور بہت اچھے طریق سے ان سے مناظرہ کرو۔ جو اسکے راستے سے بھٹک گیا۔ تمہارا پروردگار اسے بھی خوب جانتا ہے اور جو رستے پر چلنے والے ہیں ان سے بھی خوب واقف ہے۔', 'بلا اپنے رب کی راہ پر پکی باتیں سمجھا کر اور نصیحت سنا کر بھلی طرح اور الزام دے انکو جس طرح بہتر ہو [۱۹۹] تیرا رب ہی بہتر جانتا ہے ان کو جو بھول گیا اس کی راہ اور وہی بہتر جانتا ہے انکو جو راہ پر ہیں [۲۰۰]', 'Invite (mankind, O Muhammad SAW) to the Way of your Lord (i.e. Islam) with wisdom (i.e. with the Divine Inspiration and the Quran) and fair preaching, and argue with them in a way that is better. Truly, your Lord knows best who has gone astray from His Path, and He is the Best Aware of those who are guided.', 'Invite (people) to the way of your Lord with wisdom and good counsel. And argue with them in the best of manners. Surely, your Lord knows best the one who deviates from His way, and He knows best the ones who are on the right path.'),
(2027, 16, 126, 16, 22, 14, 'رُبَمَا', 'النحل', 'وَ اِنۡ عَاقَبۡتُمۡ فَعَاقِبُوۡا بِمِثۡلِ مَا عُوۡقِبۡتُمۡ  بِہٖ ؕ وَ لَئِنۡ صَبَرۡتُمۡ  لَہُوَ خَیۡرٌ  لِّلصّٰبِرِیۡنَ ﴿۱۲۶﴾', 'اور اگر تم انکو تکلیف دینی چاہو تو اتنی ہی دو جتنی تکلیف تم کو ان سے پہنچی اور اگر صبر کرو تو یہ صبر کرنے والوں کے لئے بہت اچھا ہے۔', 'اور اگر بدلہ لو تو بدلہ لو اسی قدر جس قدر کو تم کو تکلیف پہنچائی جائے (پہنچے) اور اگر صبر کرو تو یہ بہتر ہے صبر کرنے والوں کو [۲۰۱]', 'And if you punish (your enemy, O you believers in the Oneness of Allah), then punish them with the like of that with which you were afflicted. But if you endure patiently, verily, it is better for As-Sabirin (the patient ones, etc.).', 'And if you were to harm (them) in retaliation, harm them to the measure you were harmed. And if you opt for patience, it is definitely much better for those who are patient.'),
(2028, 16, 127, 16, 22, 14, 'رُبَمَا', 'النحل', 'وَ اصۡبِرۡ وَ مَا صَبۡرُکَ  اِلَّا بِاللّٰہِ وَ لَا تَحۡزَنۡ عَلَیۡہِمۡ وَ لَا تَکُ فِیۡ  ضَیۡقٍ مِّمَّا یَمۡکُرُوۡنَ ﴿۱۲۷﴾', 'اور صبر ہی کرو اور تمہارا صبر بھی اللہ ہی کی مدد سے ہے اور ان کے بارے میں غم نہ کرو اور جو یہ سازشیں کرتے ہیں اس سے تنگدل نہ ہو۔', 'اور تو صبر کر اور تجھ سے صبر ہو سکے اللہ ہی کی مدد سے اور ان پر غم نہ کھا اور تنگ مت ہو ان کے فریب سے [۲۰۲]', 'And endure you patiently (O Muhammad SAW), your patience is not but from Allah. And grieve not over them (polytheists and pagans, etc.), and be not distressed because of what they plot.', 'And be patient. Your patience is bestowed by none but Allah, and do not grieve over them, and do not be in distress for what they devise.'),
(2029, 16, 128, 16, 22, 14, 'رُبَمَا', 'النحل', 'اِنَّ اللّٰہَ مَعَ الَّذِیۡنَ اتَّقَوۡا وَّ الَّذِیۡنَ ہُمۡ مُّحۡسِنُوۡنَ ﴿۱۲۸﴾٪', 'کچھ شک نہیں کہ جو پرہیزگار ہیں اور جو نیکوکار ہیں اللہ ان کا مددگار ہے۔', 'اللہ ساتھ ہے ان کے جو پرہیزگار ہیں اور جو نیکی کرتے ہیں [۲۰۳]', 'Truly, Allah is with those who fear Him (keep their duty unto Him), and those who are Muhsinoon (good-doers, - see the footnote of V.9:120).', 'Surely, Allah is with those who fear Him and those who are good in their deeds'),
(2030, 17, 1, 1, 1, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'سُبۡحٰنَ الَّذِیۡۤ  اَسۡرٰی بِعَبۡدِہٖ لَیۡلًا مِّنَ الۡمَسۡجِدِ الۡحَرَامِ  اِلَی الۡمَسۡجِدِ الۡاَقۡصَا الَّذِیۡ بٰرَکۡنَا حَوۡلَہٗ  لِنُرِیَہٗ مِنۡ اٰیٰتِنَا ؕ اِنَّہٗ  ہُوَ  السَّمِیۡعُ  الۡبَصِیۡرُ ﴿۱﴾', 'وہ قادر مطلق جو ہر خامی سے پاک ہے ایک رات اپنے بندے کو مسجد حرام یعنی خانہ کعبہ سے مسجد اقصٰے یعنی بیت المقدس تک جسکے چاروں طرف ہم نے برکتیں رکھی ہیں لے گیا تاکہ ہم اسے اپنی قدرت کی نشانیاں دکھائیں۔ بیشک وہ سننے والا ہے دیکھنے والا ہے۔', 'پاک ذات ہے [۱] جو لے گیا اپنے بندہ کو راتوں رات مسجد حرام سے مسجد اقصٰی تک [۲] جس کو گھیر رکھا ہے ہماری برکت نے تاکہ دکھلائیں اُسکو کچھ اپنی قدرت کے نمونے [۳] وہی ہے سننے والا دیکھنے والا [۴]', 'Glorified (and Exalted) be He (Allah) (above all that (evil) they associate with Him),Who took His slave (Muhammad SAW) for a journey by night from Al-Masjid-al-Haram (at Makkah) to the farthest mosque (in Jerusalem), the neighbourhood whereof We have blessed, in order that We might show him (Muhammad SAW) of Our Ayat (proofs, evidences, lessons, signs, etc.). Verily, He is the All-Hearer, the All-Seer.', 'Glorious is He Who made his servant travel by night from Al-Masjid-ul-Harām to Al-Masjid-ul-AqSā whose environs We have blessed, so that We let him see some of Our signs. Surely, He is the All-Hearing, the All- Seeing.'),
(2031, 17, 2, 1, 1, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ اٰتَیۡنَا مُوۡسَی الۡکِتٰبَ وَ جَعَلۡنٰہُ ہُدًی  لِّبَـنِیۡۤ   اِسۡرَآءِیۡلَ  اَلَّا  تَتَّخِذُوۡا مِنۡ دُوۡنِیۡ  وَکِیۡلًا  ؕ﴿۲﴾', 'اور ہم نے موسٰی کو کتاب عنایت کی تھی اور اسکو بنی اسرائیل کے لئے راہنما مقرر کیا تھا کہ میرے سوا کسی کو کارساز نہ ٹھہرانا۔', 'اور دی ہم نے موسٰی کو کتاب اور کیا اس کو ہدایت بنی اسرائیل کے واسطے [۵] کہ نہ ٹھہراؤ میرےسوا کسی کو کارساز [۶]', 'And We gave Moosa (Moses) the Scripture and made it a guidance for the Children of Israel (saying): \"Take not other than Me as (your) Wakeel (Protector, Lord, or Disposer of your affairs, etc).', 'And We gave Mūsā the Book and made it guidance for the children of Isrā’īl (bearing the command) “Do not take anyone other than Me as guardian,'),
(2032, 17, 3, 1, 1, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'ذُرِّیَّۃَ مَنۡ حَمَلۡنَا مَعَ نُوۡحٍ ؕ اِنَّہٗ  کَانَ عَبۡدًا  شَکُوۡرًا ﴿۳﴾', 'اے ان لوگوں کی اولاد جنکو ہم نے نوح کے ساتھ کشتی میں سوار کیا تھا۔ بیشک نوح ہمارے شکرگذار بندے تھے۔', 'تم جو اولاد ہو ان لوگوں کی جن کو چڑھایا ہم نے نوح کےساتھ بیشک وہ تھا بندہ حق ماننے والا [۷]', '\"O offspring of those whom We carried (in the ship) with Nooh (Noah)! Verily, he was a grateful slave.\"', 'O you, the progeny of those whom We put on board with NūH. Surely, He was a very grateful servant.”'),
(2033, 17, 4, 1, 1, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ قَضَیۡنَاۤ  اِلٰی بَنِیۡۤ  اِسۡرَآءِیۡلَ فِی الۡکِتٰبِ لَتُفۡسِدُنَّ فِی الۡاَرۡضِ مَرَّتَیۡنِ  وَ لَتَعۡلُنَّ  عُلُوًّا کَبِیۡرًا ﴿۴﴾', 'اور ہم نے کتاب میں بنی اسرائیل سےکہدیا تھا کہ تم زمین میں دو دفعہ فساد مچاؤ گے اور بڑی سرکشی کرو گے۔', 'اور صاف کہہ سنایا ہم نے بنی اسرائیل کو کتاب میں کہ تم خرابی کرو گے ملک میں دو بار اور سرکشی کرو گے بڑی سرکشی [۸]', 'And We decreed for the Children of Israel in the Scripture, that indeed you would do mischief on the earth twice and you will become tyrants and extremely arrogant!', 'And We declared to the children of Isrā’īl in the Book: “You will surely spread mischief on the earth twice, and you will surely show utmost haughtiness.'),
(2034, 17, 5, 1, 1, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'فَاِذَا جَآءَ وَعۡدُ اُوۡلٰىہُمَا بَعَثۡنَا عَلَیۡکُمۡ  عِبَادًا  لَّنَاۤ   اُولِیۡ  بَاۡسٍ  شَدِیۡدٍ فَجَاسُوۡا خِلٰلَ الدِّیَارِ ؕ وَ کَانَ وَعۡدًا  مَّفۡعُوۡلًا ﴿۵﴾', 'پس جب پہلے وعدے کا وقت آیا تو ہم نے اپنے سخت لڑائی لڑنے والے بندے تم پر مسلط کر دیئے اور وہ شہروں کے اندر پھیل گئے۔ اور وہ وعدہ پورا ہو کر رہا۔', 'پھر جب آیا پہلا وعدہ بھیجے ہم نے تم پر اپنے بندے [۹] سخت لڑائی والے پھر پھیل پڑے شہروں کے بیچ اور وہ وعدہ ہونا ہی تھا [۱۰]', 'So, when the promise came for the first of the two, We sent against you slaves of Ours given to terrible warfare. They entered the very innermost parts of your homes. And it was a promise (completely) fulfilled.', 'So, when came the time appointed for the first of the two, We dispatched against you some servants belonging to us having strong aggressive power, who combed through the houses; and it was a promise, bound to be fulfilled.'),
(2035, 17, 6, 1, 1, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'ثُمَّ رَدَدۡنَا لَکُمُ الۡکَرَّۃَ عَلَیۡہِمۡ وَ اَمۡدَدۡنٰکُمۡ بِاَمۡوَالٍ وَّ بَنِیۡنَ وَ جَعَلۡنٰکُمۡ  اَکۡثَرَ  نَفِیۡرًا ﴿۶﴾', 'پھر ہم نے دوسری بار تمکو ان پر غلبہ دیا اور مال اور بیٹوں سے تمہاری مدد کی۔ اور تمکو جماعت کثیر بنا دیا۔', 'پھر ہم نے پھیر دی تمہاری باری [۱۱] ان پر اور قوت دی تم کو مال سے اور بیٹوں سے اور اس سے زیادہ کر دیا تمہارا لشکر', 'Then We gave you once again, a return of victory over them. And We helped you with wealth and children and made you more numerous in man power.', 'Then We gave you your turn to overpower them, and increased your strength with wealth and sons, and made you greater in number,'),
(2036, 17, 7, 1, 1, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اِنۡ اَحۡسَنۡتُمۡ اَحۡسَنۡتُمۡ لِاَنۡفُسِکُمۡ ۟ وَ اِنۡ اَسَاۡتُمۡ فَلَہَا ؕ فَاِذَا جَآءَ وَعۡدُ الۡاٰخِرَۃِ  لِیَسُوۡٓءٗا  وُجُوۡہَکُمۡ وَ لِیَدۡخُلُوا الۡمَسۡجِدَ کَمَا دَخَلُوۡہُ  اَوَّلَ مَرَّۃٍ  وَّ  لِیُتَبِّرُوۡا مَا عَلَوۡا تَتۡبِیۡرًا ﴿۷﴾', 'اگر تم نیکوکاری کرو گے تو اپنی جانوں کے لئے کرو گے اور اگر اعمال بد کرو گے تو ان کا وبال بھی تمہاری ہی جانوں پر ہو گا پھر جب دوسرے وعدے کا وقت آیا تو ہم نے پھر اپنے بندے بھیجے تاکہ تمہارے چہروں کو بگاڑ دیں۔ اور جس طرح پہلی دفعہ مسجد بیت المقدس میں داخل ہو گئے تھے اسی طرح پھر اس میں داخل ہو جائیں اور جس چیز پر غلبہ پائیں اسے تباہ کر دیں۔', 'اگر بھلائی کی تم نے تو بھلا کیا اپنا اور اگر برائی کی تو اپنے لئے [۱۲] پھر جب پہنچا وعدہ دوسرا بھیجے اور بندے کہ اداس کر دیں تمہارے منہ اور گھس جائیں مسجد میں جیسےگھس گئے تھے پہلی بار اور خراب کر دیں جس جگہ غالب ہوں پوری خرابی [۱۳]', '(And We said): \"If you do good, you do good for your ownselves, and if you do evil (you do it) against yourselves.\" Then, when the second promise came to pass, (We permitted your enemies) to make your faces sorrowful and to enter the mosque (of Jerusalem) as they had entered it before, and to destroy with utter destruction all that fell in their hands.', '(saying) ‘If you do good, you will do it for your own benefit, and if you do evil, it will be against yourselves’. Later, when came the time appointed for the second, (We sent others,) so that they spoil your faces, and so that they enter into the Mosque as the former ones entered it the first time, and utterly destroy whatever they prevail upon.'),
(2037, 17, 8, 1, 1, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'عَسٰی رَبُّکُمۡ اَنۡ یَّرۡحَمَکُمۡ ۚ وَ اِنۡ عُدۡتُّمۡ عُدۡنَا ۘ وَ جَعَلۡنَا جَہَنَّمَ لِلۡکٰفِرِیۡنَ  حَصِیۡرًا ﴿۸﴾', 'امید ہے کہ تمہارا پروردگار تم پر رحم کرے۔ اور اگر تم پھر وہی حرکتیں کرو گے تو ہم بھی وہی پہلا سلوک کریں گے اور ہم نے جہنم کو کافروں کے لئے قیدخانہ بنا رکھا ہے۔', 'بعید نہیں تمہارے رب سے کہ رحم کرے تم پر اور اگر پھر وہی کرو گے تو ہم پھر وہی کریں گے اور کیا ہے ہم نے دوزخ کو کافروں کا قید خانہ [۱۴]', '(And We said in the Taurat (Torah)): \"It may be that your Lord may show mercy unto you, but if you return (to sins), We shall return (to Our Punishment). And We have made Hell a prison for the disbelievers.', 'May be your Lord would bestow mercy upon you. But if you do this again, We shall do that again, and We have made Jahannam (Hell) a prison for the disbelievers.”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(2038, 17, 9, 1, 1, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اِنَّ ہٰذَا  الۡقُرۡاٰنَ  یَہۡدِیۡ  لِلَّتِیۡ ہِیَ اَقۡوَمُ وَ یُبَشِّرُ الۡمُؤۡمِنِیۡنَ الَّذِیۡنَ یَعۡمَلُوۡنَ الصّٰلِحٰتِ اَنَّ لَہُمۡ اَجۡرًا کَبِیۡرًا ۙ﴿۹﴾', 'یہ قرآن وہ رستہ دکھاتا ہے جو سب سے سیدھا ہے اور مومنوں کو جو نیک عمل کرتے ہیں بشارت دیتا ہے کہ ان کے لئے اجر عظیم ہے۔', 'یہ قرآن بتلاتا ہے وہ راہ جو سب سے سیدھی ہے اور خوشخبری سناتا ہے ایمان والوں کو جو عمل کرتے ہیں اچھے کہ ان کے لئے ہے ثواب بڑا [۱۵]', 'Verily, this Quran guides to that which is most just and right and gives glad tidings to the believers (in the Oneness of Allah and His Messenger, Muhammad SAW, etc.). who work deeds of righteousness, that they shall have a great reward (Paradise).', 'Surely, this Qur’ān guides to something that is most straightforward, and gives glad tidings to the believers who do good deeds that ready for them there is a great reward,'),
(2039, 17, 10, 1, 1, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَّ اَنَّ الَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِالۡاٰخِرَۃِ اَعۡتَدۡنَا  لَہُمۡ  عَذَابًا  اَلِیۡمًا ﴿٪۱۰﴾', 'اور یہ بھی بتاتا ہے کہ جو آخرت پر ایمان نہیں رکھتے ان کے لئے ہم نے دکھ دینے والا عذاب تیار کر رکھا ہے۔', 'اور یہ کہ جو نہیں مانتے آخرت کو ان کے لئے تیار کیا ہے ہم نے عذاب دردناک', 'And that those who believe not in the Hereafter (i.e. they disbelieve that they will be recompensed for what they did in this world, good or bad, etc.), for them We have prepared a painful torment (Hell).', 'and that We have prepared a painful punishment for those who do not believe in the Hereafter.'),
(2040, 17, 11, 2, 2, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ یَدۡعُ الۡاِنۡسَانُ بِالشَّرِّ دُعَآءَہٗ  بِالۡخَیۡرِ ؕ وَ کَانَ  الۡاِنۡسَانُ  عَجُوۡلًا ﴿۱۱﴾', 'اور انسان جس طرح جلدی سے بھلائی مانگتا ہے اسی طرح برائی مانگتا ہے۔ اور انسان بڑا جلدباز ہے۔', 'اور مانگتا ہے آدمی برائی جیسے مانگتا ہے بھلائی اور ہے انسان جلد باز [۱۶]', 'And man invokes (Allah) for evil as he invokes (Allah) for good and man is ever hasty (i.e., if he is angry with somebody, he invokes (saying): \"O Allah! Curse him, etc.\" and that one should not do, but one should be patient).', 'Man prays for evil like his prayer for good, and man is so hasty.'),
(2041, 17, 12, 2, 2, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ جَعَلۡنَا الَّیۡلَ وَ النَّہَارَ اٰیَتَیۡنِ فَمَحَوۡنَاۤ اٰیَۃَ الَّیۡلِ وَ جَعَلۡنَاۤ  اٰیَۃَ النَّہَارِ مُبۡصِرَۃً  لِّتَبۡتَغُوۡا فَضۡلًا مِّنۡ رَّبِّکُمۡ وَ لِتَعۡلَمُوۡا عَدَدَ السِّنِیۡنَ وَ الۡحِسَابَ ؕ وَ کُلَّ شَیۡءٍ فَصَّلۡنٰہُ تَفۡصِیۡلًا ﴿۱۲﴾', 'اور ہم نے دن اور رات کو دو نشانیاں بنایا ہے سو رات کی نشانی کو تاریک بنایا۔ اور دن کی نشانی کو روشن۔ تاکہ تم اپنے پروردگار کا فضل یعنی روزی تلاش کرو اور برسوں کا شمار اور حساب جانو۔ اور ہم نے ہر چیز کی بخوبی تفصیل کر دی ہے۔', 'اور ہم نے بنائے رات اور دن دو نمونے [۱۷] پھر مٹا دیا رات کا نمونہ [۱۸] اور بنا دیا دن کا نمونہ دیکھنے کو تاکہ تلاش کرو فضل اپنے رب کا [۱۹] اور تاکہ معلوم کرو گنتی برسوں کی اور حساب [۲۰] اور سب چیز سنائی ہم نے کھول کر [۲۱]', 'And We have appointed the night and the day as two Ayat (signs etc.). Then, We have made dark the sign of the night while We have made the sign of day illuminating, that you may seek bounty from your Lord, and that you may know the number of the years and the reckoning. And We have explained everything (in detail) with full explanation.', 'We have made the night and the day two signs, then We made the sign of night marked by darkness and the sign of day bright, so that you may seek grace from your Lord, and that you may know how to number the years and how to compute, and We have expounded everything in detail.'),
(2042, 17, 13, 2, 2, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ کُلَّ  اِنۡسَانٍ اَلۡزَمۡنٰہُ طٰٓئِرَہٗ  فِیۡ عُنُقِہٖ ؕ وَ نُخۡرِجُ لَہٗ یَوۡمَ الۡقِیٰمَۃِ کِتٰبًا  یَّلۡقٰىہُ  مَنۡشُوۡرًا ﴿۱۳﴾', 'اور ہم نے ہر انسان کے اعمال نامے کو بہ صورت کتاب اسکے گلے میں لٹکا دیا ہے۔ اور قیامت کے روز وہ کتاب اسے نکال دکھائیں گے جسے وہ کھلا ہوا دیکھے گا۔', 'اور جو آدمی ہے لگا دی ہے ہم نے اس کی بری قسمت اس کی گردن سے اور نکال دکھائیں گے اس کو قیامت کے دن ایک کتاب کہ دیکھے گا اسکو کھلی ہوئی [۲۲]', 'And We have fastened every mans deeds to his neck, and on the Day of Resurrection, We shall bring out for him a book which he will find wide open.', 'We have tied up every human’s fortune to his neck, and on the Day of Resurrection, We will bring forth a book for him that he will find wide open,'),
(2043, 17, 14, 2, 2, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اِقۡرَاۡ کِتٰبَکَ ؕ  کَفٰی بِنَفۡسِکَ الۡیَوۡمَ عَلَیۡکَ  حَسِیۡبًا ﴿ؕ۱۴﴾', 'کہا جائے گا کہ اپنی کتاب پڑھ لے۔ تو آج آپ ہی اپنا حساب کرنے والا کافی ہے۔', 'پڑھ لے کتاب اپنی (لکھا اپنا) تو ہی بس (کافی)  ہے آج کے دن اپنا حساب لینے والا [۲۳]', '(It will be said to him): \"Read your book. You yourself are sufficient as a reckoner against you this Day.\"', '(and We will say to him) “Read your book. Enough are you today to take your own account.”'),
(2044, 17, 15, 2, 2, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'مَنِ اہۡتَدٰی فَاِنَّمَا یَہۡتَدِیۡ لِنَفۡسِہٖ ۚ وَ مَنۡ ضَلَّ فَاِنَّمَا یَضِلُّ عَلَیۡہَا ؕ وَ لَا تَزِرُ وَازِرَۃٌ  وِّزۡرَ  اُخۡرٰی ؕ وَ مَا کُنَّا مُعَذِّبِیۡنَ  حَتّٰی  نَبۡعَثَ  رَسُوۡلًا ﴿۱۵﴾', 'جو شخص ہدایت اختیار کرتا ہے تو اپنے لئے اختیار کر تا ہے اور جو گمراہ ہوتا ہے تو گمراہی کا ضرر بھی اسی کو ہو گا اور کوئی شخص کسی دوسرے کا بوجھ نہیں اٹھائے گا۔ اور جب تک ہم پیغمبر نہ بھیج لیں عذاب نہیں دیا کرتے۔', 'جو کوئی راہ پر آیا تو آیا اپنے ہی بھلے کو اور جو کوئی بہکا رہا تو بہکا رہا اپنے ہی برے کو اور کسی پر نہیں پڑتا بوجھ دوسرے کا [۲۴] اور ہم نہیں ڈالتے بلا جب تک نہ بھیجیں کوئی رسول [۲۵]', 'Whoever goes right, then he goes right only for the benefit of his ownself. And whoever goes astray, then he goes astray to his own loss. No one laden with burdens can bear anothers burden. And We never punish until We have sent a Messenger (to give warning).', 'Whoever adopts the right path does so for his own benefit, and whoever goes astray does so to his own detriment, and no bearer of burden shall bear the burden of another, and it is not Our way to punish (anyone) unless We send a Messenger.'),
(2045, 17, 16, 2, 2, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ اِذَاۤ  اَرَدۡنَاۤ  اَنۡ نُّہۡلِکَ قَرۡیَۃً  اَمَرۡنَا مُتۡرَفِیۡہَا فَفَسَقُوۡا فِیۡہَا فَحَقَّ عَلَیۡہَا الۡقَوۡلُ  فَدَمَّرۡنٰہَا  تَدۡمِیۡرًا ﴿۱۶﴾', 'اور جب ہمارا ارادہ کسی بستی کے ہلاک کرنے کا ہوا تو وہاں کے آسودہ لوگوں کو فواحش پر مامور کر دیا تو وہ نافرمانیاں کرتے رہے پھر اس پر عذاب کا حکم ثابت ہو گیا۔ اور ہم نے اسے ہلاک کر ڈالا۔', 'اور جب ہم نے چاہا کہ غارت کریں کسی بستی کو حکم بھیج دیا اس کےعیش کرنے والوں کو پھر انہوں نے نافرمانی کی اس میں تب ثابت ہو گئ ان پر بات پھر اکھاڑ مارا ہم نے انکو اٹھا کر [۲۶]', 'And when We decide to destroy a town (population), We (first) send a definite order (to obey Allah and be righteous) to those among them (or We (first) increase in number those of its population) who are given the good things of this life. Then, they transgress therein, and thus the word (of torment) is justified against it (them). Then We destroy it with complete destruction.', 'And when We intend to destroy a habitation, We command its affluent people (to do good), then they commit sins therein, and thus the word (of punishment) becomes applicable to it (habitation), and We annihilate it totally.'),
(2046, 17, 17, 2, 2, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ کَمۡ  اَہۡلَکۡنَا مِنَ الۡقُرُوۡنِ مِنۡۢ  بَعۡدِ نُوۡحٍ ؕ وَ کَفٰی بِرَبِّکَ بِذُنُوۡبِ عِبَادِہٖ خَبِیۡرًۢا  بَصِیۡرًا ﴿۱۷﴾', 'اور ہم نے نوح کے بعد بہت سی امتوں کو ہلاک کر ڈالا اور تمہارا پروردگار اپنے بندوں کے گناہوں کو جاننے اور دیکھنے والا کافی ہے۔', 'اور بہت غارت کر دیئے ہم نے قرن نوح کے پیچھے [۲۷] اور کافی ہےتیرا رب اپنے بندوں کے گناہ جاننے والا دیکھنے والا [۲۸]', 'And how many generations have We destroyed after Nooh (Noah)! And Sufficient is your Lord as an All-Knower and All-Beholder of the sins of His slaves.', 'How many a generation have We destroyed after NūH! And enough is your Lord to know, (and) watch the sins of His servants.'),
(2047, 17, 18, 2, 2, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'مَنۡ کَانَ یُرِیۡدُ الۡعَاجِلَۃَ عَجَّلۡنَا لَہٗ فِیۡہَا مَا نَشَآءُ لِمَنۡ نُّرِیۡدُ ثُمَّ  جَعَلۡنَا لَہٗ جَہَنَّمَ ۚ یَصۡلٰىہَا مَذۡمُوۡمًا مَّدۡحُوۡرًا ﴿۱۸﴾', 'جو شخص دنیا کی آسودگی کا خواہشمند ہو تو ہم اس میں سے جسے چاہتے ہیں اور جتنا چاہتے ہیں جلد دے دیتے ہیں۔ پھر اسکے لئے جہنم کو ٹھکانہ مقرر کر رکھا ہے جسمیں وہ نفریں سن کر اور درگاہ الٰہی سے راندہ ہو کر داخل ہو گا۔', 'جو کوئی چاہتا ہو پہلا گھر جلد دے دیں ہم اس کو اسی میں جتنا چاہیں جس کو چاہیں پھر ٹھہرایا ہم نے اس کے واسطے دوزخ داخل ہو گا ا سمیں اپنی برائی سنکر دھکیلا جا کر [۱۹]', 'Whoever wishes for the quick-passing (transitory enjoyment of this world), We readily grant him what We will for whom We like. Then, afterwards, We have appointed for him Hell, he will burn therein disgraced and rejected, ( far away from Allahs Mercy).', 'Whoever opts for the immediate (benefits from) life herein, We give him, right here in this life, as much as We will, to whomever We intend. Then We assign Jahannam for him where he shall enter condemned, discarded.'),
(2048, 17, 19, 2, 2, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ مَنۡ اَرَادَ   الۡاٰخِرَۃَ  وَ سَعٰی لَہَا سَعۡیَہَا وَ ہُوَ مُؤۡمِنٌ فَاُولٰٓئِکَ کَانَ سَعۡیُہُمۡ  مَّشۡکُوۡرًا ﴿۱۹﴾', 'اور جو شخص آخرت کا خواستگار ہو اور اس میں اتنی کوشش کرے جتنی اسے لائق ہے اور وہ مومن بھی ہو تو ایسے ہی لوگوں کی کوشش ٹھکانے لگتی ہے۔', 'اور جس نے چاہا پچھلا گھر اور دوڑ کی اس کے واسطے جو اس کی دوڑ ہے اور وہ یقین پر ہے سو ایسوں کی دوڑ ٹھکانے لگی ہے [۳۰]', 'And whoever desires the Hereafter and strives for it, with the necessary effort due for it (i.e. do righteous deeds of Allahs Obedience) while he is a believer (in the Oneness of Allah Islamic Monotheism), then such are the ones whose striving shall be appreciated, thanked and rewarded (by Allah).', 'And whoever opts for the Hereafter and makes efforts for it as due, while he is a believer, then, the effort of such people is appreciated!'),
(2049, 17, 20, 2, 2, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'کُلًّا نُّمِدُّ ہٰۤؤُلَآءِ وَ ہٰۤؤُلَآءِ مِنۡ عَطَآءِ رَبِّکَ ؕ وَ مَا  کَانَ عَطَـآءُ  رَبِّکَ  مَحۡظُوۡرًا ﴿۲۰﴾', 'ہم انکو اور انکو سب کو تمہارے پروردگار کی بخشش سے مدد دیتے ہیں اور تمہارے پروردگار کی بخشش کسی سے رکی ہوئی نہیں۔', 'ہر ایک کو ہم پہنچائے جاتے ہیں۔ اِنکو اور اُن کو تیرے رب کی بخشش میں سے اور تیرے رب کی بخشش کسی نے نہیں روک لی [۳۱]', 'To each these as well as those We bestow from the Bounties of your Lord. And the Bounties of your Lord can never be forbidden.', 'To all of them - both these and those - We extend the grants of your Lord. And the grant of your Lord is not barred (for anyone).'),
(2050, 17, 21, 2, 2, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اُنۡظُرۡ کَیۡفَ فَضَّلۡنَا بَعۡضَہُمۡ  عَلٰی  بَعۡضٍ ؕ وَ  لَلۡاٰخِرَۃُ   اَکۡبَرُ  دَرَجٰتٍ  وَّ  اَکۡبَرُ  تَفۡضِیۡلًا ﴿۲۱﴾', 'دیکھو ہم نے کس طرح بعض کو بعض پر فضیلت بخشی ہے۔ اور آخرت درجوں میں دنیا سے بہت برتر اور برتری میں کہیں بڑھ کر ہے۔', 'دیکھ کیا بڑھا دیا ہم نے ایک کو ایک سے اور پچھلے گھر میں تو اور بڑے درجے ہیں اور بڑی فضیلت [۳۲]', 'See how We prefer one above another (in this world) and verily, the Hereafter will be greater in degrees and greater in preference.', 'See how We made some of them excel some others (in this world) and, of course, the Hereafter is much higher in ranks and much greater in degrees of merit.'),
(2051, 17, 22, 2, 2, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'لَا تَجۡعَلۡ مَعَ اللّٰہِ اِلٰـہًا اٰخَرَ  فَتَقۡعُدَ مَذۡمُوۡمًا  مَّخۡذُوۡلًا ﴿٪۲۲﴾', 'اور اللہ کے ساتھ کوئی اور معبود نہ بنانا کہ ملامتیں سن کر اور بےکس ہو کر بیٹھے رہ جاؤ گے۔', 'مت ٹھہرا للہ کے ساتھ دوسرا حاکم پھر بیٹھ رہے گا تو الزام کھا کر بےکس ہو کر [۳۳]', 'Set not up with Allah any other ilah (god), (O man)! (This verse is addressed to Prophet Muhammad SAW , but its implication is general to all mankind), or you will sit down reproved, forsaken (in the Hell-fire).', 'Do not set up any other god along with Allah, otherwise you will sit condemned, forsaken.'),
(2052, 17, 23, 3, 3, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ قَضٰی رَبُّکَ اَلَّا تَعۡبُدُوۡۤا اِلَّاۤ  اِیَّاہُ وَ بِالۡوَالِدَیۡنِ اِحۡسَانًا ؕ اِمَّا یَبۡلُغَنَّ عِنۡدَکَ الۡکِبَرَ اَحَدُہُمَاۤ  اَوۡ  کِلٰہُمَا فَلَا تَقُلۡ لَّہُمَاۤ  اُفٍّ  وَّ لَا  تَنۡہَرۡہُمَا وَ قُلۡ  لَّہُمَا  قَوۡلًا کَرِیۡمًا ﴿۲۳﴾', 'اور تمہارے پروردگار نے ارشاد فرمایا ہے کہ اسکے سوا کسی کی عبادت نہ کرو اور ماں باپ کے ساتھ بھلائی کرتے رہو اگر ان میں سے ایک یا دونوں تمہارے سامنے بڑھاپے کو پہنچ جائیں تو انکو اف تک نہ کہنا اور نہ انہیں جھڑکنا اور ان سے بات ادب کے ساتھ کرنا۔', 'اور حکم کر چکا تیرا رب کہ نہ پوجو اس کے سوائے اور ماں باپ کے ساتھ بھلائی کرو [۳۴] اگر پہنچ جائے تیرے سامنے بڑھاپے کو ایک ان میں سے یا دونوں تو نہ کہہ ان کو ہوں اور نہ جھڑک ان کو اور کہہ ان سے بات ادب کی [۳۵]', 'And your Lord has decreed that you worship none but Him. And that you be dutiful to your parents. If one of them or both of them attain old age in your life, say not to them a word of disrespect, nor shout at them but address them in terms of honour.', 'Your Lord has decreed that you worship none but Him, and do good to parents. If any one of them or both of them reach old age, do not say to them: uff (a word or expression of anger or contempt) and do not scold them, and address them with respectful words,'),
(2053, 17, 24, 3, 3, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ اخۡفِضۡ لَہُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحۡمَۃِ  وَ قُلۡ  رَّبِّ  ارۡحَمۡہُمَا کَمَا رَبَّیٰنِیۡ  صَغِیۡرًا ﴿ؕ۲۴﴾', 'اور عجزونیاز سے انکے آگے جھکے رہو اور انکے حق میں دعا کرو کہ اے پروردگار جیسا انہوں نے مجھے بچپن میں شفقت سے پرورش کیا ہے تو بھی انکے حال پر رحمت فرما۔', 'اور جھکا دے ان کے آگے کندھے عاجزی کر کر نیازمندی سے اور کہہ اے رب ان پر رحم کر جیسا پالا انہوں نے مجھ کو چھوٹا سا [۳۶]', 'And lower unto them the wing of submission and humility through mercy, and say: \"My Lord! Bestow on them Your Mercy as they did bring me up when I was small.\"', 'and submit yourself before them in humility out of compassion, and say, “My Lord, be merciful to them as they have brought me up in my childhood.”'),
(2054, 17, 25, 3, 3, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'رَبُّکُمۡ اَعۡلَمُ بِمَا فِیۡ نُفُوۡسِکُمۡ ؕ اِنۡ تَکُوۡنُوۡا صٰلِحِیۡنَ فَاِنَّہٗ  کَانَ  لِلۡاَوَّابِیۡنَ غَفُوۡرًا ﴿۲۵﴾', 'جو کچھ تمہارے دلوں میں ہے تمہارا پروردگار اس سے بخوبی واقف ہے۔ اگر تم نیک ہو گے تو وہ رجوع لانے والوں کو بخش دینے والا ہے۔', 'تمہارا رب خوب جانتا ہے جو تمہارے جی میں ہے اگر تم نیک ہو گے تو وہ رجوع کرنے والوں کو بخشتا ہے [۳۷]', 'Your Lord knows best what is in your inner-selves. If you are righteous, then, verily, He is Ever Most Forgiving to those who turn unto Him again and again in obedience, and in repentance.', 'Your Lord knows best what is in your hearts. If you are righteous, then He is Most-Forgiving for those who turn to Him in repentance.'),
(2055, 17, 26, 3, 3, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ اٰتِ ذَاالۡقُرۡبٰی حَقَّہٗ  وَ الۡمِسۡکِیۡنَ وَ ابۡنَ  السَّبِیۡلِ  وَ لَا  تُبَذِّرۡ  تَبۡذِیۡرًا ﴿۲۶﴾', 'اور رشتہ داروں اور محتاجوں اور مسافروں کو ان کا حق ادا کرو اور فضول خرچی سے مال نہ اڑاؤ۔', 'اور دے قرابت والے کو اس کا حق اور محتاج کو اور مسافر کو اور مت اڑا بیجا (فضول) [۳۸]', 'And give to the kindred his due and to the Miskeen (poor) and to the wayfarer. But spend not wastefully (your wealth) in the manner of a spendthrift . (Tafsir. At-Tabaree, Vol. 10, Page 158 (Verse 9: 60)).', 'Give the relative his right, and the needy and the wayfarer. And do not squander recklessly.'),
(2056, 17, 27, 3, 3, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اِنَّ الۡمُبَذِّرِیۡنَ کَانُوۡۤا اِخۡوَانَ الشَّیٰطِیۡنِ ؕ وَ کَانَ الشَّیۡطٰنُ لِرَبِّہٖ کَفُوۡرًا ﴿۲۷﴾', 'کہ فضول خرچی کرنے والے تو شیطان کے بھائی ہیں اور شیطان اپنے پروردگار کی نعمتوں کا کفران کرنے والا یعنی ناشکرا ہے۔', 'بےشک اڑانے والے بھائی ہیں شیطانوں کے اور شیطان ہے اپنے رب کا ناشکر [۳۹]', 'Verily, spendthrifts are brothers of the Shayateen (devils), and the Shaitan (Devil Satan) is ever ungrateful to his Lord.', 'Surely, squanderers are brothers of satans, and the Satan is very ungrateful to his Lord.'),
(2057, 17, 28, 3, 3, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ اِمَّا تُعۡرِضَنَّ عَنۡہُمُ ابۡتِغَآءَ رَحۡمَۃٍ مِّنۡ رَّبِّکَ تَرۡجُوۡہَا فَقُلۡ لَّہُمۡ قَوۡلًا مَّیۡسُوۡرًا ﴿۲۸﴾', 'اور اگر تم اپنے پروردگار کی رحمت یعنی فراخ دستی کے انتظار میں جس کی تمہیں امید ہو ان مستحقین کی طرف توجہ نہ کر سکو تو ان سے نرمی سے بات کہہ دیا کرو۔', 'اور اگر کبھی تغافل کرے تو ان کی طرف سے انتظار میں اپنے رب کی مہربانی کے جسکی تجھ کو توقع ہے تو کہہ دے انکو بات نرمی کی [۴۰]', 'And if you (O Muhammad SAW) turn away from them (kindred, poor, wayfarer, etc. whom We have ordered you to give their rights, but if you have no money at the time they ask you for it) and you are awaiting a mercy from your Lord for which you hope, then, speak unto them a soft kind word (i.e. Allah will give me and I shall give you).', 'And if you turn away from them looking for a bounty from your Lord you are expecting, then speak to them in polite words.'),
(2058, 17, 29, 3, 3, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ لَا تَجۡعَلۡ یَدَکَ مَغۡلُوۡلَۃً  اِلٰی عُنُقِکَ  وَ لَا تَبۡسُطۡہَا کُلَّ الۡبَسۡطِ فَتَقۡعُدَ مَلُوۡمًا  مَّحۡسُوۡرًا ﴿۲۹﴾', 'اور اپنے ہاتھ کو نہ تو گردن سے بندھا ہوا یعنی بہت تنگ کر لو کہ کسی کو کچھ دو ہی نہیں اور نہ بالکل کھول ہی دو کہ سبھی کچھ دے ڈالو اور انجام یہ ہو کہ ملامت زدہ اور حسرت زدہ ہو کر بیٹھ جاؤ۔', 'اور نہ رکھ اپنا ہاتھ بندھا ہوا اپنی گردن کے ساتھ اور نہ کھول دے اس کو بالکل کھول دینا پھر تو بیٹھ رہے الزام کھایا ہارا ہوا [۴۱]', 'And let not your hand be tied (like a miser) to your neck, nor stretch it forth to its utmost reach (like a spendthrift), so that you become blameworthy and in severe poverty.', 'And do not keep your hand tied to your neck, nor extend it to the full extent, lest you should be sitting reproached, empty-handed.'),
(2059, 17, 30, 3, 3, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اِنَّ رَبَّکَ یَبۡسُطُ الرِّزۡقَ لِمَنۡ یَّشَآءُ وَ یَقۡدِرُ ؕ اِنَّہٗ کَانَ بِعِبَادِہٖ خَبِیۡرًۢا بَصِیۡرًا ﴿٪۳۰﴾', 'بیشک تمہارا پروردگار جسکی روزی چاہتا ہے فراخ کر دیتا ہے اور جسکی روزی چاہتا ہے تنگ کر دیتا ہے وہ اپنے بندوں سے خبردار ہے اور انکو دیکھ رہا ہے۔', 'تیرا رب کھول دیتا ہے روزی جسکے واسطے چاہے اور تنگ بھی وہی کرتا ہے [۴۲] وہی ہے اپنے بندوں کو جاننے والا دیکھنے والا [۴۳]', 'Truly, your Lord enlarges the provision for whom He wills and straitens (for whom He wills). Verily, He is Ever All-Knower, All-Seer of His slaves.', 'Indeed, your Lord expands sustenance for whomsoever He wills, and constricts (for whomsoever He wills). Surely, He is All-Aware of His servants, All-Seeing.'),
(2060, 17, 31, 4, 4, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ لَا تَقۡتُلُوۡۤا  اَوۡلَادَکُمۡ  خَشۡیَۃَ  اِمۡلَاقٍ ؕ نَحۡنُ نَرۡزُقُہُمۡ  وَ  اِیَّاکُمۡ ؕ اِنَّ  قَتۡلَہُمۡ کَانَ خِطۡاً کَبِیۡرًا ﴿۳۱﴾', 'اور اپنی اولاد کو مفلسی کے خوف سے قتل نہ کرنا کیونکہ ان کو اور تم کو ہم ہی رزق دیتے ہیں۔ کچھ شک نہیں کہ ان کا مار ڈالنا بڑا سخت گناہ ہے۔', 'اور نہ مار ڈالو اپنی اولاد کو مفلسی کے خوف سے ہم روزی دیتےہیں انکو اور تم کو [۴۴] بیشک اُن کا مارنا بڑی خطاء ہے [۴۵]', 'And kill not your children for fear of poverty. We provide for them and for you. Surely, the killing of them is a great sin.', 'Do not kill your children for fear of poverty. We provide sustenance to them and to you, too. Killing them is a great sin indeed.'),
(2061, 17, 32, 4, 4, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ لَا تَقۡرَبُوا الزِّنٰۤی اِنَّہٗ کَانَ فَاحِشَۃً ؕ وَ سَآءَ  سَبِیۡلًا ﴿۳۲﴾', 'اور زنا کے پاس بھی نہ جانا کہ وہ بےحیائی ہے اور بری راہ ہے۔', 'اور پاس نہ جاؤ زنا کے [۴۶] وہ ہے بے حیائی اور بری راہ ہے [۴۷]', 'And come not near to the unlawful sexual intercourse. Verily, it is a Fahishah (i.e. anything that transgresses its limits (a great sin)), and an evil way (that leads one to Hell unless Allah forgives him).', 'Do not even go close to fornication. It is indeed a shameful act, and an evil way to follow.'),
(2062, 17, 33, 4, 4, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ لَا تَقۡتُلُوا النَّفۡسَ الَّتِیۡ حَرَّمَ اللّٰہُ  اِلَّا بِالۡحَقِّ ؕ وَ مَنۡ قُتِلَ مَظۡلُوۡمًا فَقَدۡ جَعَلۡنَا لِوَلِیِّہٖ سُلۡطٰنًا فَلَا یُسۡرِفۡ فِّی الۡقَتۡلِ ؕ اِنَّہٗ  کَانَ  مَنۡصُوۡرًا ﴿۳۳﴾', 'اور جس جاندار کا مارنا اللہ نے حرام کیا ہے اسے قتل نہ کرنا مگر جائز طور پر یعنی بفتوٰی شریعت اور جو شخص ظلم سے قتل کیا جائے ہم نے اسکے وارث کو اختیار دیا ہے کہ ظالم قاتل سے بدلہ لے تو اسکو چاہیے کہ قتل کے قصاص میں زیادتی نہ کرے۔ کہ وہ منصور و فتح یاب ہے۔', 'اور نہ مارو اس جان کو جس کو منع کر دیا اللہ نے مگر حق پر [۴۸] اور جو مارا گیا ظلم سے تو دیا ہم نے اسکے وارث کو زور  سو حد سے نہ نکل جائے قتل کرنے میں [۴۹] اسکو مدد ملتی ہے [۵۰]', 'And do not kill anyone which Allah has forbidden, except for a just cause. And whoever is killed (intentionally with hostility and oppression and not by mistake), We have given his heir the authority ((to demand Qisas, Law of Equality in punishment or to forgive, or to take Diya (blood money)). But let him not exceed limits in the matter of taking life (i.e he should not kill except the killer only). Verily, he is helped (by the Islamic law).', 'Do not kill any person the life of whom is sanctified by Allah, except for a just reason. And whoever is killed unjustly, We have invested his heir with authority (of equal retaliation), but he must not cross the limit in the matter of killing. Surely, he will be helped.'),
(2063, 17, 34, 4, 4, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ لَا تَقۡرَبُوۡا مَالَ الۡیَتِیۡمِ  اِلَّا بِالَّتِیۡ  ہِیَ اَحۡسَنُ حَتّٰی یَبۡلُغَ  اَشُدَّہٗ ۪ وَ اَوۡفُوۡا بِالۡعَہۡدِ ۚ اِنَّ  الۡعَہۡدَ  کَانَ  مَسۡـُٔوۡلًا ﴿۳۴﴾', 'اور یتیم کے مال کے پاس بھی نہ پھٹکنا۔ مگر ایسے طریق سے کہ بہت بہتر ہو یہاں تک کہ وہ جوانی کو پہنچ جائے۔ اور عہد کو پورا کرو کہ عہد کے بارے میں ضرور پرسش ہو گی۔', 'اور پاس نہ جاؤ یتیم کے مال کے مگر جس طرح کہ بہتر ہو جب تک کہ وہ پہنچے اپنی جوانی کو [۵۱] اور پورا کرو عہد کو بیشک عہد کی پوچھ ہو گی [۵۲]', 'And come not near to the orphans property except to improve it, until he attains the age of full strength. And fulfil (every) covenant. Verily! the covenant, will be questioned about.', 'Do not go near the property of an orphan, except in a manner that is good, until he comes to his maturity. And fulfill the covenant. Surely, the covenant shall be asked about (on the Day of Reckoning).'),
(2064, 17, 35, 4, 4, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ اَوۡفُوا الۡکَیۡلَ اِذَا کِلۡتُمۡ وَ زِنُوۡا بِالۡقِسۡطَاسِ الۡمُسۡتَقِیۡمِ ؕ ذٰلِکَ خَیۡرٌ  وَّ اَحۡسَنُ  تَاۡوِیۡلًا ﴿۳۵﴾', 'اور جب کوئی چیز ناپ کر دینے لگو تو پیمانہ پورا بھرا کرو اور جب تول کر دو۔ تو ترازو سیدھی رکھ کر تولا کرو۔ یہ بہت اچھی بات اور انجام کے لحاظ سے بھی بہت بہتر ہے۔', 'اور پورا بھر دو ماپ جب ماپ کر دینے لگو اور تولو سیدھی ترازو سے [۵۳] یہ بہتر ہے اور اچھا ہے اس کا انجام [۵۴]', 'And give full measure when you measure, and weigh with a balance that is straight. That is good (advantageous) and better in the end.', 'And give full measure when you measure, and weigh with a straight balance. That is fair, and better at the end.'),
(2065, 17, 36, 4, 4, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ لَا تَقۡفُ مَا لَیۡسَ لَکَ بِہٖ عِلۡمٌ ؕ اِنَّ السَّمۡعَ وَ الۡبَصَرَ وَ الۡفُؤَادَ  کُلُّ  اُولٰٓئِکَ کَانَ  عَنۡہُ  مَسۡـُٔوۡلًا ﴿۳۶﴾', 'اور اے بندے جس چیز کا تجھے علم نہیں اسکے پیچھے نہ پڑ۔ کہ کان اور آنکھ اور دل ان سب اعضاء کے بارے میں ضرور باز پرس ہو گی۔', 'اور نہ پیچھے پڑ جس بات کی خبر نہیں تجھ کو بیشک کان اور آنکھ اور دل ان سب کی اس سے پوچھ ہو گی [۵۵]', 'And follow not (O man i.e., say not, or do not or witness not, etc.) that of which you have no knowledge (e.g. ones saying: \"I have seen,\" while in fact he has not seen, or \"I have heard,\" while he has not heard). Verily! The hearing, and the sight, and the heart, of each of those you will be questioned (by Allah).', 'And do not follow a thing about which you have no knowledge. Surely, the ear, the eye and the heart - each one of them shall be interrogated about.'),
(2066, 17, 37, 4, 4, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ لَا تَمۡشِ فِی الۡاَرۡضِ مَرَحًا ۚ اِنَّکَ  لَنۡ تَخۡرِقَ الۡاَرۡضَ وَ لَنۡ تَبۡلُغَ الۡجِبَالَ طُوۡلًا ﴿۳۷﴾', 'اور زمین پر اکڑ کر اور تن کر مت چل کہ تو زمین کو پھاڑ تو نہیں ڈالے گا اور نہ لمبا ہو کر پہاڑوں کی چوٹی تک پہنچ جائے گا۔', 'اور مت چل زمین پر اتراتا ہوا تو پھاڑ نہ ڈالے گا زمین کو اور نہ ہنچے گا پہاڑوں تک لمبا ہو کر [۵۶]', 'And walk not on the earth with conceit and arrogance. Verily, you can neither rend nor penetrate the earth, nor can you attain a stature like the mountains in height.', 'Do not walk on the earth in haughty style. You can neither tear the earth apart, nor can you match the mountains in height.'),
(2067, 17, 38, 4, 4, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'کُلُّ ذٰلِکَ کَانَ سَیِّئُہٗ عِنۡدَ رَبِّکَ مَکۡرُوۡہًا ﴿۳۸﴾', 'ان سب عادتوں کی برائی تیرے پروردگار کے نزدیک بہت ناپسند ہے۔', 'یہ جتنی باتیں ہیں ان سب میں بری چیز ہے تیرے رب کی بیزاری [۵۷]', 'All the bad aspects of these (the above mentioned things) are hateful to your Lord.', 'That which is evil, of all these, is detestable in the sight of your Lord.'),
(2068, 17, 39, 4, 4, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'ذٰلِکَ مِمَّاۤ  اَوۡحٰۤی  اِلَیۡکَ رَبُّکَ مِنَ الۡحِکۡمَۃِ ؕ وَ لَا تَجۡعَلۡ مَعَ اللّٰہِ  اِلٰـہًا اٰخَرَ فَتُلۡقٰی فِیۡ جَہَنَّمَ مَلُوۡمًا مَّدۡحُوۡرًا ﴿۳۹﴾', 'اے پیغمبر یہ ان ہدایتوں میں سے ہیں جو اللہ نے حکمت کی باتیں تمہاری طرف وحی کی ہیں اور اللہ کے ساتھ کوئی اور معبود نہ بنانا کہ ایسا کرنے سے ملامت زدہ اور راندہ درگاہ بنا کر جہنم میں ڈال دیئے جاؤ گے۔', 'یہ ہے ان باتوں میں سے جو وحی بھیجی تیرے رب نے تیری طرف عقل کے کاموں سے [۵۸] اور نہ ٹھہرہا اللہ کے سوائے کسی اور کی بندگی پھر پڑے تو دوزخ میں الزام کھا کر دھکیلا جا کر [۵۹]', 'This is (part) of Al-Hikmah (wisdom, good manners and high character, etc.) which your Lord has inspired to you (O Muhammad SAW ). And set not up with Allah any other ilah (god) lest you should be thrown into Hell, blameworthy and rejected, (from Allahs Mercy).', 'This is part of the Wisdom your Lord has revealed to you. And do not set up any other god along with Allah, lest you should be thrown into Jahannam , reproached, rejected.'),
(2069, 17, 40, 4, 4, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اَفَاَصۡفٰىکُمۡ رَبُّکُمۡ  بِالۡبَنِیۡنَ وَ اتَّخَذَ مِنَ الۡمَلٰٓئِکَۃِ  اِنَاثًا ؕ اِنَّکُمۡ  لَتَقُوۡلُوۡنَ قَوۡلًا عَظِیۡمًا ﴿٪۴۰﴾', 'مشرکو! کیا تمہارے پروردگار نے تمکو تو لڑکے دیئے اور اپنے لئے فرشتوں کو بیٹیاں بنایا۔ کچھ شک نہیں کہ یہ تم بڑی نامعقول بات کہتے ہو۔', 'کیا تم کو چن کر دیدئے تمہارے رب نے بیٹے اور اپنے لئے کر لیا فرشتوں کو بیٹیاں تم کہتے ہو بھاری بات [۶۰]', 'Has then your Lord (O pagans of Makkah) preferred for you sons, and taken for Himself from among the angels daughters. Verily! You utter an awful saying, indeed.', 'Is it, then, that your Lord has chosen you people to have sons, and has Himself opted for females from among the angels? Surely, you are uttering a serious statement.'),
(2070, 17, 41, 5, 5, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ لَقَدۡ صَرَّفۡنَا فِیۡ ہٰذَا  الۡقُرۡاٰنِ  لِیَذَّکَّرُوۡا ؕ وَ  مَا  یَزِیۡدُہُمۡ   اِلَّا  نُفُوۡرًا ﴿۴۱﴾', 'اور ہم نے اس قرآن میں طرح طرح کی باتیں بیان کی ہیں تاکہ لوگ نصیحت حاصل کریں مگر وہ اس سے اور بدک جاتے ہیں۔', 'اور پھیر پھیر کر سمجھایا ہم نے اس قرآن میں تاکہ وہ سوچیں اور ان کو زیاد ہوتا ہے وہی بدکنا [۶۱]', 'And surely, We have explained (Our Promises, Warnings and (set forth many) examples) in this Quran that they (the disbelievers) may take heed, but it increases them in naught save aversion.', 'Surely, We have explained things in various ways in this Qur’ān, so that they may pay heed to the advice; but it increases nothing in them except aversion.'),
(2071, 17, 42, 5, 5, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'قُلۡ  لَّوۡ کَانَ مَعَہٗۤ  اٰلِـہَۃٌ  کَمَا یَقُوۡلُوۡنَ اِذًا  لَّابۡتَغَوۡا اِلٰی ذِی الۡعَرۡشِ سَبِیۡلًا ﴿۴۲﴾', 'کہدو کہ اگر اللہ کے ساتھ اور معبود ہوتے جیسا کہ یہ کہتے ہیں تو وہ ضرور عرش والے کی طرف لڑنے بھڑنے کے لئے رستہ نکالتے۔', 'کہہ اگر ہوتے اس کے ساتھ اور حاکم جیسا یہ بتلاتے ہیں [۶۲] تو نکالتے صاحب عرش کی طرف راہ [۶۳]', 'Say (O Muhammad SAW to these polytheists, pagans, etc.): \"If there had been other aliha (gods) along with Him as they assert, then they would certainly have sought out a way to the Lord of the Throne (seeking His Pleasures and to be near to Him).', 'Say, “Had there been other gods along with Him”, as they say, “then they would have found out a way to the Lord of the Throne”.'),
(2072, 17, 43, 5, 5, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'سُبۡحٰنَہٗ  وَ تَعٰلٰی عَمَّا یَقُوۡلُوۡنَ عُلُوًّا کَبِیۡرًا ﴿۴۳﴾', 'وہ پاک ہے اور جو کچھ یہ بکواس کرتے ہیں اس سے اس کا رتبہ بہت عالی ہے۔', 'وہ پاک ہے اور برتر ہے ان کی باتوں سے بے نہایت', 'Glorified and High be He! From Uluwan Kabeera (the great falsehood) that they say! (i.e.forged statements that there are other gods along with Allah, but He is Allah, the One, the Self-Sufficient Master, whom all creatures need. He begets not, nor was He begotten, and there is none comparable or coequal unto Him).', 'Pure is He, and Exalted, immensely above what they say.'),
(2073, 17, 44, 5, 5, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'تُسَبِّحُ  لَہُ  السَّمٰوٰتُ السَّبۡعُ  وَ الۡاَرۡضُ وَ مَنۡ فِیۡہِنَّ ؕ وَ اِنۡ مِّنۡ شَیۡءٍ  اِلَّا یُسَبِّحُ بِحَمۡدِہٖ  وَ لٰکِنۡ لَّا تَفۡقَہُوۡنَ تَسۡبِیۡحَہُمۡ ؕ اِنَّہٗ  کَانَ حَلِیۡمًا غَفُوۡرًا ﴿۴۴﴾', 'ساتوں آسمان اور زمین اور جو لوگ ان میں ہیں سب اسی کی تسبیح کرتے ہیں۔ اور مخلوقات میں سے کوئی چیز نہیں مگر اسکی تعریف کے ساتھ تسبیح کرتی ہے۔ لیکن تم انکی تسبیح کو نہیں سمجھتے۔ بیشک وہ بردبار ہے غفار ہے۔', 'اس کی پاکی بیان کرتے ہیں ساتوں آسمان اور زمین اور جو کوئی ان میں ہے اور کوئی چیز نہیں جو نہیں پڑھتی خوبیاں اس کی لیکن تم نہیں سمجھتے ان کا پڑھنا [۶۴] بیشک وہ ہے تحمل والا بخشنے والا [۶۵]', 'The seven heavens and the earth and all that is therein, glorify Him and there is not a thing but glorifies His Praise. But you understand not their glorification. Truly, He is Ever Forbearing, Oft-Forgiving.', 'All the seven skies and the earth and all those therein extol His purity. And there is not a single thing that does not extol His purity along with His praise, but you do not understand their extolling. Surely He is Forbearing, Most-Forgiving.'),
(2074, 17, 45, 5, 5, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ اِذَا قَرَاۡتَ الۡقُرۡاٰنَ جَعَلۡنَا بَیۡنَکَ وَ بَیۡنَ  الَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِالۡاٰخِرَۃِ حِجَابًا مَّسۡتُوۡرًا  ﴿ۙ۴۵﴾', 'اور اے نبی جب تم قرآن پڑھا کرتے ہو تو ہم تم میں اور ان لوگوں میں جو آخرت پر ایمان نہیں رکھتے چھپا ہوا پردہ یعنی حجاب ڈال دیتے ہیں۔', 'اور جب تو پڑھتا ہے قرآن کر دیتے ہیں ہم بیچ میں تیرے اور ان لوگوں کے جو نہیں مانتے آخرت کو ایک پردہ چھپا ہوا [۶۶]', 'And when you (Muhammad SAW) recite the Quran, We put between you and those who believe not in the Hereafter, an invisible veil (or screen their hearts, so they hear or understand it not).', 'When you recite the Qur’ān, We place an invisible curtain between you and those who do not believe in the Hereafter,'),
(2075, 17, 46, 5, 5, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَّ جَعَلۡنَا عَلٰی قُلُوۡبِہِمۡ  اَکِنَّۃً  اَنۡ یَّفۡقَہُوۡہُ  وَ فِیۡۤ  اٰذَانِہِمۡ وَقۡرًا ؕ وَ اِذَا ذَکَرۡتَ رَبَّکَ فِی الۡقُرۡاٰنِ وَحۡدَہٗ  وَلَّوۡا عَلٰۤی  اَدۡبَارِہِمۡ  نُفُوۡرًا ﴿۴۶﴾', 'اور انکے دلوں پر بھی پردے ڈال دیتے ہیں کہ اسے سمجھ نہ سکیں اور انکے کانوں میں ثقل پیدا کر دیتے ہیں۔ اور جب تم قرآن میں اپنے پروردگار یکتا کا ذکر کرتے ہو تو وہ لوگ بدک جاتے اور پیٹھ پھیر کر چل دیتے ہیں۔', 'اور ہم رکھتے ہیں ان کے دلوں پر پردہ کہ اس کو نہ سمجھیں [۶۷] اور ان کے کانوں میں بوجھ [۶۸] اور جب ذکر کرتا ہے تو قرآن میں اپنے رب کا اکیلا کر کر بھاگتے ہیں اپنی پیٹھ پر بدک کر [۶۹]', 'And We have put coverings over their hearts lest, they should understand it (the Quran), and in their ears deafness. And when you make mention of your Lord Alone (La ilaha ill-Allah (none has the right to be worshipped but Allah) Islamic Monotheism ()) in the Quran, they turn on their backs, fleeing in extreme dislikeness.', 'and We put covers on their hearts barring them from understanding it, and (We put) deafness in their ears; and when you refer to your Lord alone (without referring to their presumed deities,) in the Qur’ān, they turn their backs in aversion.'),
(2076, 17, 47, 5, 5, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'نَحۡنُ اَعۡلَمُ بِمَا یَسۡتَمِعُوۡنَ بِہٖۤ  اِذۡ یَسۡتَمِعُوۡنَ  اِلَیۡکَ وَ اِذۡ ہُمۡ نَجۡوٰۤی  اِذۡ یَقُوۡلُ الظّٰلِمُوۡنَ  اِنۡ تَتَّبِعُوۡنَ  اِلَّا رَجُلًا  مَّسۡحُوۡرًا ﴿۴۷﴾', 'یہ لوگ جب تمہاری طرف کان لگاتے ہیں تو جس نیت سے یہ سنتے ہیں ہم اسے خوب جانتے ہیں اور جب یہ سرگوشیاں کرتے ہیں یعنی جب ظالم کہتے ہیں کہ تم تو ایک ایسے شخص کی پیروی کرتے ہو جس پر جادو کیا گیا ہے۔', 'ہم خوب جانتے ہیں جس واسطے وہ سنتے ہیں [۷۰] جس وقت کان رکھتے ہیں تیری طرف اور جب وہ مشورت کرتے ہیں جب کہ کہتے ہیں یہ بے انصاف جس کے کہنے پر تم چلتے ہو وہ نہیں ہے مگر ایک مرد جادو کا مارا [۷۱]', 'We know best of what they listen to, when they listen to you. And when they take secret counsel, behold, the Zalimoon (polytheists and wrong-doers, etc.) say: \"You follow none but a bewitched man.\"', 'We are fully aware of the reason for which they listen, when they listen to you, and when they are in secret consultation: when the transgressors say, “You are following none but a bewitched man.”'),
(2077, 17, 48, 5, 5, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اُنۡظُرۡ کَیۡفَ ضَرَبُوۡا لَکَ الۡاَمۡثَالَ فَضَلُّوۡا  فَلَا  یَسۡتَطِیۡعُوۡنَ  سَبِیۡلًا ﴿۴۸﴾', 'دیکھو انہوں نے کس کس طرح کی تمہارے بارے میں باتیں بنائی ہیں۔ سو یہ گمراہ ہو رہے ہیں اور رستہ نہیں پا سکتے۔', 'دیکھ لے کیسے جماتے ہیں تجھ پر مثلیں اور بہکتے پھرتے ہیں سو راہ نہیں پا سکتے [۷۲]', 'See what examples they have put forward for you. So they have gone astray, and never can they find a way.', 'See how they have made (silly) statements about you; so they have gone astray and cannot find a way.'),
(2078, 17, 49, 5, 5, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ قَالُوۡۤاءَ اِذَا کُنَّا عِظَامًا  وَّ  رُفَاتًاءَ اِنَّا  لَمَبۡعُوۡثُوۡنَ  خَلۡقًا جَدِیۡدًا ﴿۴۹﴾', 'اور کہتے ہیں کہ جب ہم مر کر بوسیدہ ہڈیاں اور چور چور ہو جائیں گے تو کیا ازسرنو پیدا ہو کر اٹھیں گے؟', 'اور کہتے ہیں کیا جب ہم ہو جائیں ہڈیاں اور چورا چورا پھر اٹھیں گے نئے بن کر [۷۳]', 'And they say: \"When we are bones and fragments (destroyed), should we really be resurrected (to be) a new creation?\"', 'And they say, “Once we are reduced to bones and dust, is it then that we will be raised, created anew?”'),
(2079, 17, 50, 5, 5, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'قُلۡ  کُوۡنُوۡا  حِجَارَۃً   اَوۡ  حَدِیۡدًا ﴿ۙ۵۰﴾', 'کہدو کہ خواہ تم پتھر ہو جاؤ یا لوہا۔', 'تو کہہ تم ہو جاؤ پتھر یا لوہا', 'Say (O Muhammad SAW) \"Be you stones or iron,\"', 'Say, “Be you stones or iron'),
(2080, 17, 51, 5, 5, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اَوۡ خَلۡقًا مِّمَّا یَکۡبُرُ فِیۡ صُدُوۡرِکُمۡ ۚ فَسَیَقُوۡلُوۡنَ مَنۡ یُّعِیۡدُنَا ؕ قُلِ الَّذِیۡ فَطَرَکُمۡ   اَوَّلَ مَرَّۃٍ ۚ فَسَیُنۡغِضُوۡنَ اِلَیۡکَ رُءُوۡسَہُمۡ وَ یَقُوۡلُوۡنَ مَتٰی ہُوَ ؕ  قُلۡ  عَسٰۤی  اَنۡ  یَّکُوۡنَ  قَرِیۡبًا ﴿۵۱﴾', 'یا کوئی اور چیز جو تمہارے نزدیک پتھر اور لوہے سے بھی زیادہ سخت ہو۔ جھٹ کہیں گے کہ بھلا ہمیں دوبارہ کون جلائے گا؟ کہدو کہ وہی جس نے تمکو پہلی بار پیدا کیا۔ تو تعجب سے تمہارے آگے سر ہلائیں گے اور پوچھیں گے کہ ایسا کب ہوگا۔ کہدو امید ہے کہ جلد ہو گا۔', 'یا کوئی خلقت جس کو مشکل سمجھو اپنے جی میں [۷۴] پھر اب کہیں گے کون لوٹا کر لائے گا ہم کو کہہ جس نے پیدا کیا تم کو پہلی بار [۷۵] پھر اب مٹکائیں گے تیری طرف اپنے سر اور کہیں گے کب ہو گا یہ [۷۶] تو کہہ شاید نزدیک ہی ہو گا [۷۷]', '\"Or some created thing that is yet greater (or harder) in your breasts (thoughts to be resurrected, even then you shall be resurrected)\" Then, they will say: \"Who shall bring us back (to life)?\" Say: \"He Who created you first!\" Then, they will shake their heads at you and say: \"When will that be ?\" Say: \"Perhaps it is near!\"', 'or any creation you deem harder in your hearts.” Thereupon they will ask, “Who will bring us back?” Say, “The One who created you for the first time.” So, they will shake their heads before you and say, “When shall that be?” Say, “May be, it is near.”'),
(2081, 17, 52, 5, 5, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'یَوۡمَ  یَدۡعُوۡکُمۡ فَتَسۡتَجِیۡبُوۡنَ بِحَمۡدِہٖ وَ  تَظُنُّوۡنَ   اِنۡ   لَّبِثۡتُمۡ   اِلَّا   قَلِیۡلًا  ﴿٪۵۲﴾', 'جس دن وہ تمہیں پکارے گا تو تم اسکی تعریف کے ساتھ جواب دو گے اور خیال کرو گے کہ تم دنیا میں بہت کم مدت رہے۔', 'جس دن تم کو پکارے گا پھر چلے آؤ گے اسکی تعریف کرتے ہوئے [۷۸] اور اٹکل کرو گے کہ دیر نہیں لگی تم کو مگر تھوڑی [۷۹]', 'On the Day when He will call you, and you will answer (His Call) with (words of) His Praise and Obedience, and you will think that you have stayed (in this world) but a little while!', '(It will be) on a day when He will call you, and you will respond praising Him, and you will think you did not stay (on the earth) but for a short while.'),
(2082, 17, 53, 6, 6, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ قُلۡ لِّعِبَادِیۡ یَقُوۡلُوا الَّتِیۡ  ہِیَ  اَحۡسَنُ ؕ اِنَّ الشَّیۡطٰنَ یَنۡزَغُ بَیۡنَہُمۡ ؕ اِنَّ الشَّیۡطٰنَ کَانَ لِلۡاِنۡسَانِ عَدُوًّا مُّبِیۡنًا ﴿۵۳﴾', 'اور میرے بندوں سے کہدو کہ لوگوں سے ایسی باتیں کہا کریں جو بہت پسندیدہ ہوں۔ کیونکہ شیطان بری باتوں سے ان میں فساد ڈلوا دیتا ہے۔ کچھ شک نہیں کہ شیطان انسان کا کھلا دشمن ہے۔', 'اور کہہ دے میرے بندوں کہ بات وہی کہیں جو بہتر ہو شیطان جھڑپ کرواتا ہے ان میں شیطان ہے انسان کا دشمن صریح [۸۰]', 'And say to My slaves (i.e. the true believers of Islamic Monotheism) that they should (only) say those words that are the best. (Because) Shaitan (Satan) verily, sows disagreements among them. Surely, Shaitan (Satan) is to man a plain enemy.', 'Tell My servants that they should speak that which is best. Surely, Satan creates discord among them. Indeed, Satan is an open enemy to mankind.'),
(2083, 17, 54, 6, 6, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'رَبُّکُمۡ  اَعۡلَمُ  بِکُمۡ ؕ اِنۡ  یَّشَاۡ یَرۡحَمۡکُمۡ  اَوۡ اِنۡ یَّشَاۡ یُعَذِّبۡکُمۡ ؕ وَ مَاۤ  اَرۡسَلۡنٰکَ عَلَیۡہِمۡ  وَکِیۡلًا  ﴿۵۴﴾', 'تمہارا پروردگار تم سے خوب واقف ہے۔ اگر چاہے تو تم پر رحم کرے یا اگر چاہے تو تمہیں عذاب دے۔ اور ہم نے تمکو ان پر داروغہ بنا کر نہیں بھیجا۔', 'تمہارا رب خوب جانتا ہے تم کو اگر چاہے تم پر رحم کرے اور اگر چاہے تم کو عذاب دے [۸۱] اور تجھ کو نہیں بھیجا ہم نے ان پر ذمہ لینے والا [۸۲]', 'Your Lord knows you best, if He will, He will have mercy on you, or if He will, He will punish you. And We have not sent you (O Muhammad SAW) as a guardian over them.', 'Your Lord knows you best. If He so wills, He will have mercy on you, and if He so wills, He will punish you, and We did not send you (O Prophet,) to become responsible for them.'),
(2084, 17, 55, 6, 6, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ رَبُّکَ اَعۡلَمُ بِمَنۡ فِی السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ لَقَدۡ فَضَّلۡنَا بَعۡضَ النَّبِیّٖنَ عَلٰی بَعۡضٍ وَّ اٰتَیۡنَا دَاوٗدَ  زَبُوۡرًا ﴿۵۵﴾', 'اور جو لوگ آسمانوں اور زمین میں ہیں تمہارا پروردگار ان سے خوب واقف ہے۔ اور ہم نے بعض پیغمبروں کو بعض پر فضیلت بخشی اور داؤد کو زبور عنایت کی۔', 'اور تیرا رب خوب جانتا ہے انکو جو آسمانوں میں ہیں اور زمین میں اور ہم نے افضل کیا ہے بعض پیغمبروں کو بعضوں سے اور دی ہم نے داؤد کو زبور [۸۳]', 'And your Lord knows best all who are in the heavens and the earth. And indeed, We have preferred some of the Prophets above others, and to Dawood (David) We gave the Zaboor (Psalms).', 'Your Lord knows best about all those in the heavens and the earth, and We have certainly granted excellence to some prophets over some others, and We gave Dawūd the Zabūr (the Psalms).'),
(2085, 17, 56, 6, 6, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'قُلِ ادۡعُوا الَّذِیۡنَ  زَعَمۡتُمۡ  مِّنۡ  دُوۡنِہٖ فَلَا یَمۡلِکُوۡنَ  کَشۡفَ الضُّرِّ عَنۡکُمۡ   وَ لَا تَحۡوِیۡلًا ﴿۵۶﴾', 'کہو کہ مشرکو جن لوگوں کی نسبت تمہیں معبود ہونے کا گمان ہے۔ ان کو بلا دیکھو۔ وہ تم سے تکلیف کے دور کرنے یا اسکے بدل دینے کا کچھ بھی اختیار نہیں رکھتے۔', 'کہہ پکارو جن کو تم سمجھتے ہو سوائے اس کے سو وہ اختیار نہیں رکھتے کہ کھول دیں تکلیف کو تم سے اور نہ بدل دیں [۸۴]', 'Say (O Muhammad SAW): \"Call unto those besides Him whom you pretend (to be gods like angels, Iesa (Jesus), Uzair (Ezra), etc.). They have neither the power to remove the adversity from you nor even to shift it from you to another person.\"', 'Say, “Call those whom you assume (to be gods), besides Him, while they have no power to remove distress from you, nor to change it.”'),
(2086, 17, 57, 6, 6, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اُولٰٓئِکَ الَّذِیۡنَ یَدۡعُوۡنَ یَبۡتَغُوۡنَ  اِلٰی رَبِّہِمُ الۡوَسِیۡلَۃَ اَیُّہُمۡ اَقۡرَبُ وَ یَرۡجُوۡنَ رَحۡمَتَہٗ وَ یَخَافُوۡنَ عَذَابَہٗ ؕ اِنَّ عَذَابَ  رَبِّکَ  کَانَ  مَحۡذُوۡرًا ﴿۵۷﴾', 'یہ لوگ جنکو اللہ کے سوا پکارتے ہیں وہ خود اپنے پروردگار کے ہاں ذریعہ تقرب تلاش کرتے رہتے ہیں کہ کون ان میں اللہ کا زیادہ مقرب ہوتا ہے اور اسکی رحمت کے امیدوار رہتے ہیں اور اسکے عذاب سے خوف رکھتے ہیں بیشک تمہارے پروردگار کا عذاب ڈرنے کی چیز ہے۔', 'وہ لوگ جن کو یہ پکارتے ہیں وہ خود ڈھونڈتے ہیں اپنے رب تک وسیلہ کہ کونسا بندہ بہت نزدیک ہے [۸۵] اور امید رکھتے ہیں اس کی مہربانی کی اور ڈرتے ہیں اس کے عذاب سے بیشک تیرے رب کا عذاب ڈرنے کی چیز ہے [۸۶]', 'Those whom they call upon (like Iesa (Jesus) son of Maryam (Mary), Uzair (Ezra), angel, etc.) desire (for themselves) means of access to their Lord (Allah), as to which of them should be the nearest and they (Iesa (Jesus), Uzair (Ezra), angels, etc.) hope for His Mercy and fear His Torment. Verily, the Torment of your Lord is something to be afraid of!', 'Those whom they invoke, do themselves seek the means of access to their Lord as to which of them becomes the closest, and they hope for His Mercy and fear His punishment. The punishment of your Lord is really something to be feared.'),
(2087, 17, 58, 6, 6, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ اِنۡ مِّنۡ قَرۡیَۃٍ  اِلَّا نَحۡنُ  مُہۡلِکُوۡہَا قَبۡلَ یَوۡمِ الۡقِیٰمَۃِ  اَوۡ مُعَذِّبُوۡہَا عَذَابًا شَدِیۡدًا ؕ کَانَ  ذٰلِکَ فِی الۡکِتٰبِ مَسۡطُوۡرًا ﴿۵۸﴾', 'اور کفر کرنے والوں کی کوئی بستی نہیں مگر قیامت کے دن سے پہلے ہم اسے ہلاک کر دیں گے یا اسے سخت عذاب دیں گے۔ یہ کتاب یعنی تقدیر میں لکھا جا چکا ہے۔', 'اور کوئی بستی نہیں جس کو ہم خراب نہ کر دیں گے قیامت سے پہلے یا آفت ڈالیں گے اس پر سخت آفت [۸۷] یہ ہے کتاب میں لکھا گیا [۸۸]', 'And there is not a town (population) but We shall destroy it before the Day of Resurrection, or punish it with a severe torment. That is written in the Book (of our Decrees)', 'There is no town but We are to destroy it before the Doomsday, or punish it with severe punishment. That is what stands written in the Book.'),
(2088, 17, 59, 6, 6, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ مَا مَنَعَنَاۤ  اَنۡ  نُّرۡسِلَ بِالۡاٰیٰتِ اِلَّاۤ  اَنۡ  کَذَّبَ بِہَا الۡاَوَّلُوۡنَ ؕ وَ اٰتَیۡنَا ثَمُوۡدَ النَّاقَۃَ  مُبۡصِرَۃً  فَظَلَمُوۡا بِہَا ؕ وَ مَا نُرۡسِلُ  بِالۡاٰیٰتِ  اِلَّا  تَخۡوِیۡفًا ﴿۵۹﴾', 'اور ہم نے نشانیاں بھیجنی اس لئے موقوف کر دیں کہ پہلے لوگوں نے اسکی تکذیب کی تھی۔ اور ہم نے ثمود کو اونٹنی نبوت صالح کی کھلی نشانی دی تو انہوں نے اس پر ظلم کیا۔ اور ہم جو نشانیاں بھیجا کرتے ہیں تو ڈرانے کو۔', 'اور ہم نے اس لئے موقوف کیں نشانیاں بھیجنی کہ اگلوں نے ان کو جھٹلایا [۸۹] اور ہم نے دی ثمود کو اونٹنی ان کے سجھانے کو پھر ظلم کیا اس پر [۹۰] اور نشانیاں جو ہم بھیجتے ہیں سو ڈرانے کو [۹۱]', 'And nothing stops Us from sending the Ayat (proofs, evidences, signs) but that the people of old denied them. And We sent the she-camel to Thamood as a clear sign, but they did her wrong. And We sent not the signs except to warn, and to make them afraid (of destruction).', 'Nothing made us refrain from sending the signs (demanded by the pagans,) except that the earlier people had rejected them. (For example,) We gave Thamūd the she-camel, as an eye-opener, then they did wrong to her, and We do not send signs but as a warning.'),
(2089, 17, 60, 6, 6, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ اِذۡ قُلۡنَا  لَکَ  اِنَّ رَبَّکَ اَحَاطَ بِالنَّاسِ ؕ وَ مَا جَعَلۡنَا الرُّءۡیَا الَّتِیۡۤ  اَرَیۡنٰکَ اِلَّا فِتۡنَۃً  لِّلنَّاسِ وَ الشَّجَرَۃَ  الۡمَلۡعُوۡنَۃَ فِی الۡقُرۡاٰنِ ؕ وَ نُخَوِّفُہُمۡ ۙ فَمَا یَزِیۡدُہُمۡ  اِلَّا  طُغۡیَانًا کَبِیۡرًا ﴿٪۶۰﴾', 'اور جب ہم نے تم سے کہا کہ تمہارا پروردگار لوگوں کا احاطہ کئے ہوئے ہے۔ اور جو منظر ہم نے تمہیں دکھایا اسکو لوگوں کے لئے آزمائش کیا اور اسی طرح تھوہر کے درخت کو جس پر قرآن میں لعنت کی گئ۔ اور ہم انہیں ڈراتے ہیں تو اس سے انکی سرکشی میں اضافہ ہوتا ہے۔', 'اور جب کہہ دیا ہم نے تجھ سے کہ تیرے رب نے گھیر لیا ہے لوگوں کو [۹۲] اور وہ دکھلاوا جو تجھ کو دکھلایا ہم نے سو جانچنے کو لوگوں کے [۹۳] اور ایسے ہی وہ درخت جس پر پھٹکار ہے قرآن میں [۹۴] اور ہم انکو ڈراتے ہیں تو انکو زیادہ ہوتی ہے بری شرارت [۹۵]', 'And (remember) when We told you: \"Verily! Your Lord has encompassed mankind (i.e. they are in His Grip).\" And We made not the vision which we showed you (O Muhammad as an actual eye-witness and not as a dream on the night of Al-Isra) but a trial for mankind, and likewise the accursed tree (Zaqqoom, mentioned) in the Quran. We warn and make them afraid but it only increases them in naught save great disbelief, oppression and disobedience to Allah.', '(Remember) when We said to you that your Lord encompasses all humans. And We did not make the vision We showed to you, but a test for the people - and the tree cursed in the Qur’ān as well. And We warn them, yet it adds nothing to them but enormous rebellion.'),
(2090, 17, 61, 7, 7, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ اِذۡ قُلۡنَا لِلۡمَلٰٓئِکَۃِ  اسۡجُدُوۡا  لِاٰدَمَ فَسَجَدُوۡۤا اِلَّاۤ اِبۡلِیۡسَ ؕ قَالَ ءَاَسۡجُدُ لِمَنۡ  خَلَقۡتَ  طِیۡنًا ﴿ۚ۶۱﴾', 'اور جب ہم نے فرشتوں سے کہا کہ آدم کو سجدہ کرو تو سب نے سجدہ کیا مگر ابلیس نے نہ کیا۔ بولا کہ بھلا میں ایسے شخص کو سجدہ کروں جس کو تو نے مٹی سے پیدا کیا ہے۔', 'اور جب ہم نے کہا فرشتوں کو سجدہ کرو آدم کو تو سجدہ میں گر پڑے مگر ابلیس بولا کیا میں سجدہ کروں ایک شخص کو جس کو تو نے بنایا مٹی کا [۹۶]', 'And (remember) when We said to the angels: \"Prostrate unto Adam.\" They prostrated except Iblees (Satan). He said: \"Shall I prostrate to one whom You created from clay?\"', '(Remember) when We said to the angels, “Prostrate yourself before ’Ādam.” So, they all prostrated, except Iblīs (Satan). He said, “Shall I prostrate before the one You have created from mud?”'),
(2091, 17, 62, 7, 7, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'قَالَ  اَرَءَیۡتَکَ ہٰذَا  الَّذِیۡ  کَرَّمۡتَ عَلَیَّ ۫ لَئِنۡ اَخَّرۡتَنِ اِلٰی یَوۡمِ الۡقِیٰمَۃِ لَاَحۡتَنِکَنَّ ذُرِّیَّتَہٗۤ  اِلَّا  قَلِیۡلًا ﴿۶۲﴾', 'اور ازراہ طنز کہنے لگا کہ دیکھ تو یہی وہ ہے جسے تو نے مجھ پر فضیلت دی ہے اگر تو مجھ کو قیامت کے دن تک کی مہلت دے تو میں تھوڑے سے شخصوں کے سوا اسکی تمام اولاد کی جڑ کاٹتا رہوں گا۔', 'کہنے لگا بھلا دیکھ تو یہ شخص جس کو تو نے مجھ سے بڑھا دیا اگر تو مجھ کو ڈھیل دیوے قیامت کے دن تک تو میں اس کی اولاد کو ڈانٹی دے لوں گا مگر تھوڑے سے [۹۷]', '(Iblees (Satan)) said: \"See? This one whom You have honoured above me, if You give me respite (keep me alive) to the Day of Resurrection, I will surely seize and mislead his offspring (by sending them astray) all but a few!\"', 'He (Iblīs) added, “Tell me, this one whom You have honored more than me, if You give me respite till the Doomsday, I will subdue his progeny, except a few of them.”'),
(2092, 17, 63, 7, 7, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'قَالَ اذۡہَبۡ فَمَنۡ تَبِعَکَ مِنۡہُمۡ فَاِنَّ جَہَنَّمَ  جَزَآؤُکُمۡ  جَزَآءً  مَّوۡفُوۡرًا ﴿۶۳﴾', 'اللہ نے فرمایا یہاں سے چلا جا۔ جو شخص ان میں سے تیری پیروی کرے گا تو تم سب کی جزا  جہنم ہے اور وہ پوری سزا ہے۔', 'فرمایا جا پھر جو کوئی تیرے ساتھ ہوا ان میں سے سو دوزخ ہے تم سب کی سزا بدلہ پورا [۹۸]', '(Allah) said: \"Go, and whosoever of them follows you, surely! Hell will be the recompense of you (all) an ample recompense.', 'He (Allah) said, “Go then, for whoever of them follows you, the Hell shall be the recompense of you all, a full recompense.'),
(2093, 17, 64, 7, 7, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ اسۡتَفۡزِزۡ مَنِ اسۡتَطَعۡتَ مِنۡہُمۡ بِصَوۡتِکَ وَ اَجۡلِبۡ عَلَیۡہِمۡ بِخَیۡلِکَ وَ رَجِلِکَ وَ شَارِکۡہُمۡ فِی الۡاَمۡوَالِ وَ الۡاَوۡلَادِ وَ عِدۡہُمۡ ؕ وَ مَا یَعِدُہُمُ الشَّیۡطٰنُ   اِلَّا  غُرُوۡرًا ﴿۶۴﴾', 'اور ان میں سے جسکو بہکا سکے اپنی آواز سے بہکاتا رہ۔ اور ان پر اپنے سواروں اور پیادوں کو چڑھا کر لاتا رہ اور انکے مال اور اولاد میں شریک ہوتا رہ اور ان سے وعدہ کرتا رہ۔ اور شیطان جو وعدے ان سے کرتا ہے سب دھوکا ہے۔', 'اور گھبرا لے ان میں جس کو تو گھبرا سکے اپنی آواز سے [۹۹] اور لے آ ان پر اپنے سوار اور پیادے [۱۰۰] اور ساجھا کر ان سے مال اور اولاد میں [۱۰۱] اور وعدے دے انکو اور کچھ نہیں وعدہ دیتا انکو شیطان مگر دغابازی [۱۰۲]', '\"And Istafziz (literally means: befool them gradually) those whom you can among them with your voice (i.e. songs, music, and any other call for Allahs disobedience), make assaults on them with your cavalry and your infantry, mutually share with them wealth and children (by tempting them to earn money by illegal ways usury, etc., or by committing illegal sexual intercourse, etc.), and make promises to them.\" But Satan promises them nothing but deceit.', 'Entice with your voice those of them whom you can, and rally against them your horsemen and your footmen, and share with them in their wealth and their children, and make promises to them” - and Satan promises them nothing but delusion -'),
(2094, 17, 65, 7, 7, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اِنَّ عِبَادِیۡ  لَیۡسَ  لَکَ  عَلَیۡہِمۡ سُلۡطٰنٌ ؕ وَ کَفٰی  بِرَبِّکَ  وَکِیۡلًا  ﴿۶۵﴾', 'جو میرے مخلص بندے ہیں ان پر تیرا کچھ زور نہیں۔ اور اے پیغمبر تمہارا پروردگار کارساز کافی ہے۔', 'وہ جو میرے بندے ہیں ان پر نہیں تیری حکومت اور تیرا رب کافی ہے کام بنانے والا [۱۰۳]', '\"Verily! My slaves (i.e the true believers of Islamic Monotheism), you have no authority over them. And All-Sufficient is your Lord as a Guardian.\"', '“As for My servants, you have no control over them, and your Lord is enough to look after (everything).”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(2095, 17, 66, 7, 7, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'رَبُّکُمُ الَّذِیۡ یُزۡجِیۡ لَکُمُ الۡفُلۡکَ فِی الۡبَحۡرِ لِتَبۡتَغُوۡا مِنۡ فَضۡلِہٖ ؕ اِنَّہٗ کَانَ بِکُمۡ  رَحِیۡمًا ﴿۶۶﴾', 'تمہارا پروردگار وہ ہے جو تمہارے لئے  سمندر میں کشتیاں چلاتا ہے تاکہ تم اسکے فضل سے روزی تلاش کرو۔ بیشک وہ تم پر مہربان ہے۔', 'تمہارا رب وہ ہے جو چلاتا ہے تمہارے واسطے کشتی دریا میں [۱۰۴] تاکہ تلاش کرو اس کا فضل [۱۰۵] وہی ہے تم پر مہربان', 'Your Lord is He Who drives the ship for you through the sea, in order that you may seek of His Bounty. Truly! He is Ever Most Merciful towards you.', 'Your Lord is the One who causes ships to sail for you through the sea, so that you may go in quest of His bounty; surely, He is Ever-Merciful for you.'),
(2096, 17, 67, 7, 7, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ اِذَا مَسَّکُمُ الضُّرُّ  فِی الۡبَحۡرِ ضَلَّ مَنۡ تَدۡعُوۡنَ  اِلَّاۤ  اِیَّاہُ ۚ فَلَمَّا نَجّٰىکُمۡ  اِلَی الۡبَرِّ  اَعۡرَضۡتُمۡ ؕ وَ کَانَ  الۡاِنۡسَانُ کَفُوۡرًا ﴿۶۷﴾', 'اور جب تم کو سمندر میں تکلیف پہنچتی ہے یعنی ڈوبنے کا خوف ہوتا ہے تو جنکو تم پکارا کرتے ہو سب اس پروردگار کے سوا گم ہو جاتے ہیں پھر جب وہ تمکو ڈوبنے سے بچا کر خشکی کی طرف لے جاتا ہے تو تم منہ پھیر لیتے ہو اور انسان ہے ہی ناشکرا۔', 'اور جب آتی ہے تم پر آفت دریا میں بھول جاتے ہو جن کو پکارا کرتے تھے اللہ کے سوائے پھر جب بچا لایا تم کو خشکی میں پھر جاتے ہو اور ہے انسان بڑا نا شکر [۱۰۶]', 'And when harm touches you upon the sea, those that you call upon besides Him vanish from you except Him (Allah Alone). But when He brings you safely to land, you turn away (from Him). And man is ever ungrateful.', 'you face a hardship at sea, vanished are those whom you used to invoke, except Him (Allah). Then, once He brings you safe to the land, you turn away (from Him); man is so ungrateful.'),
(2097, 17, 68, 7, 7, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اَفَاَمِنۡتُمۡ اَنۡ یَّخۡسِفَ بِکُمۡ جَانِبَ الۡبَرِّ اَوۡ یُرۡسِلَ عَلَیۡکُمۡ حَاصِبًا ثُمَّ لَا تَجِدُوۡا  لَکُمۡ  وَکِیۡلًا  ﴿ۙ۶۸﴾', 'کیا تم اس سے بےخوف ہو کہ اللہ تمہیں خشکی کی طرف لے جا کر زمین میں دھنسا دے یا تم پر سنگریزوں کی بھری ہوئی آندھی چلا دے۔ پھر تم اپنا کوئی نگہبان نہ پاؤ۔', 'سو کیا تم بے ڈر ہو گئے اس سے کہ دھنسا دے تم کو جنگل کے کنارے [۱۰۷] یا بھیج دے تم پر آندھی پتھر برسانے والی پھر نہ پاؤ اپنا کوئی نگہبان', 'Do you then feel secure that He will not cause a side of the land to swallow you up, or that He will not send against you a violent sand-storm? Then, you shall find no Wakeel (guardian one to guard you from the torment).', 'Do you, then, feel secure from that He makes a part of the land sink down along with you, or that He sends down a rain of stones on you, whereupon you will find no one to protect you?'),
(2098, 17, 69, 7, 7, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اَمۡ  اَمِنۡتُمۡ اَنۡ یُّعِیۡدَکُمۡ فِیۡہِ تَارَۃً  اُخۡرٰی فَیُرۡسِلَ عَلَیۡکُمۡ قَاصِفًا مِّنَ الرِّیۡحِ فَیُغۡرِقَکُمۡ بِمَا کَفَرۡتُمۡ ۙ ثُمَّ لَا  تَجِدُوۡا لَکُمۡ عَلَیۡنَا بِہٖ تَبِیۡعًا ﴿۶۹﴾', 'یا اس بات سے بےخوف ہو کہ تمکو دوسری دفعہ سمندر میں لے جائے پھر تم پر تیز ہوا چلائے اور تمہارے کفر کے سبب تمہیں ڈبو دے۔ پھر تم اس معاملے میں اپنے لئے کوئی بازپرس کرنے والا نہ پاؤ۔', 'یا بے ڈر  ہو گئے ہو اس سے کہ پھر لیجائے تمکو دریا میں [۱۰۸] دوسری بار پھر بھیجے تم پر ایک سخت جھوکا ہوا کا پھر ڈبا دے تم کو بدلے میں اس ناشکری کے پھر نہ پاؤ اپنی طرف سے ہم پر اس کا کوئی باز پرس کرنے والا [۱۰۹]', 'Or do you feel secure that He will not send you back a second time to sea and send against you a hurricane of wind and drown you because of your disbelief, then you will not find any avenger therein against Us?', 'Or, do you feel secure from that He takes you back to it (the sea) once again, and sends a heavy storm of wind upon you which drowns you because of your disbelief, and then you will find no one to help?'),
(2099, 17, 70, 7, 7, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ لَقَدۡ کَرَّمۡنَا بَنِیۡۤ  اٰدَمَ وَ حَمَلۡنٰہُمۡ  فِی الۡبَرِّ وَ الۡبَحۡرِ وَ رَزَقۡنٰہُمۡ مِّنَ الطَّیِّبٰتِ وَ فَضَّلۡنٰہُمۡ عَلٰی کَثِیۡرٍ مِّمَّنۡ خَلَقۡنَا تَفۡضِیۡلًا ﴿٪۷۰﴾', 'اور ہم نے بنی آدم کو عزت بخشی اور انکو خشکی اور تری میں سواری دی اور پاکیزہ روزی عطا کی اور اپنی بہت سی مخلوقات پر فضیلت دی۔', 'اور ہم نےعزت دی ہے آدم کی اولاد کو اور سواری دی ان کو جنگل اور دریا میں اور روزی دی ہم نے ان کو ستھری چیزوں سے اور بڑھا دیا ان کو بہتوں سے جن کو پیدا کیا ہم نے بڑائی دے کر [۱۱۰]', 'And indeed We have honoured the Children of Adam, and We have carried them on land and sea, and have provided them with At-Taiyibat (lawful good things), and have preferred them above many of those whom We have created with a marked preference.', 'And We bestowed dignity on the children of ’Ādam and provided them with rides on the land and in the sea, and provided them with a variety of good things and made them much superior to many of those whom We have created.'),
(2100, 17, 71, 8, 8, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'یَوۡمَ نَدۡعُوۡا کُلَّ اُنَاسٍۭ بِاِمَامِہِمۡ ۚ فَمَنۡ اُوۡتِیَ کِتٰبَہٗ  بِیَمِیۡنِہٖ فَاُولٰٓئِکَ یَقۡرَءُوۡنَ  کِتٰبَہُمۡ وَ لَا یُظۡلَمُوۡنَ فَتِیۡلًا  ﴿۷۱﴾', 'جس دن ہم سب لوگوں کو انکے پیشواؤں کے ساتھ بلائیں گے۔ تو جنکے اعمال کی کتاب انکے داہنے ہاتھ میں دی جائے گی وہ اپنی کتاب کو خوش ہو ہو کر پڑھیں گے اور ان پر دھاگے برابر بھی ظلم نہ ہوگا۔', 'جس دن ہم بلائیں گے ہر فرقہ کو ان کے سرداروں کے ساتھ سو جس کو ملا اس کا اعمال نامہ اس کے داہنی ہاتھ میں سو وہ لوگ پڑھیں گے اپنا لکھا [۱۱۱] اور ظلم نہ ہو گا ان پر ایک تاگے کا [۱۱۲]', '(And remember) the Day when We shall call together all human beings with their (respective) Imam (their Prophets, or their records of good and bad deeds, or their Holy Books like the Quran, the Taurat (Torah), the Injeel (Gospel), etc.). So whosoever is given his record in his right hand, such will read their records, and they will not be dealt with unjustly in the least.', '(Think of) the Day when We will call every people with their books of deeds. Then the ones who will be given their book in their right hands will read their book (happily) and will not be wronged even to the measure of a fine thread.'),
(2101, 17, 72, 8, 8, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ مَنۡ کَانَ فِیۡ ہٰذِہٖۤ  اَعۡمٰی فَہُوَ فِی الۡاٰخِرَۃِ   اَعۡمٰی  وَ اَضَلُّ  سَبِیۡلًا ﴿۷۲﴾', 'اور جو شخص اس دنیا میں اندھا ہو وہ آخرت میں بھی اندھا ہو گا اور نجات کے رستے سے بہت دور۔', 'اور جو کوئی رہا اس جہان میں اندھا سو وہ پچھلے جہان میں بھی اندھا ہے اور بہت دور پڑا ہوا راہ سے [۱۱۳]', 'And whoever is blind in this world (i.e., does not see Allahs Signs and believes not in Him), will be blind in the Hereafter, and more astray from the Path.', 'But whoever is (too) blind in this (world to see the right path) will be (too) blind in the Hereafter (to reach the salvation), and much more astray from the path.'),
(2102, 17, 73, 8, 8, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ اِنۡ کَادُوۡا لَیَفۡتِنُوۡنَکَ عَنِ الَّذِیۡۤ اَوۡحَیۡنَاۤ  اِلَیۡکَ لِتَفۡتَرِیَ عَلَیۡنَا غَیۡرَہٗ ٭ۖ وَ  اِذًا  لَّاتَّخَذُوۡکَ  خَلِیۡلًا ﴿۷۳﴾', 'اور اے پیغمبر جو وحی ہم نے تمہاری طرف بھیجی ہے قریب تھا کہ یہ کافر لوگ تم کو اس سے بہکا دیں تاکہ تم اس کے سوا اور باتیں ہماری نسبت بنا لو۔ اور اس وقت وہ تمکو دوست بنا لیتے۔', 'اور وہ لوگ تو چاہتے تھے کہ تجھ کو بچلا دیں اس چیز سے کہ جو وحی بھیجی ہم نے تیری طرف تاکہ جھوٹ بنا لائے تو ہم پر وحی کے سوا اور تب تو بنا لیتے تجھ کو دوست [۱۱۴]', 'Verily, they were about to tempt you away from that which We have revealed (the Quran) unto you (O Muhammad SAW), to fabricate something other than it against Us, and then they would certainly have taken you a friend!', '(O Prophet,) Surely, they were about to lure you away from what We have revealed to you, so that you forge something else against Us, and in that case they would have certainly made you a bosom friend.'),
(2103, 17, 74, 8, 8, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ لَوۡ لَاۤ  اَنۡ ثَبَّتۡنٰکَ لَقَدۡ کِدۡتَّ تَرۡکَنُ اِلَیۡہِمۡ  شَیۡئًا  قَلِیۡلًا ﴿٭ۙ۷۴﴾', 'اور اگر ہم تم کو ثابت قدم نہ رہنے دیتے تو تم کسی قدر انکی طرف مائل ہونے ہی لگے تھے۔', 'اور اگر یہ نہ ہوتا کہ ہم نے تجھ کو سنبھالے رکھا تو لگ جاتا جھکنے ان کی طرف تھوڑا سا [۱۱۵]', 'And had We not made you stand firm, you would nearly have inclined to them a little.', 'Had We not made you firm, it was likely that you would have inclined towards them a little bit.'),
(2104, 17, 75, 8, 8, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اِذًا  لَّاَذَقۡنٰکَ ضِعۡفَ الۡحَیٰوۃِ  وَ ضِعۡفَ الۡمَمَاتِ ثُمَّ  لَا تَجِدُ  لَکَ  عَلَیۡنَا نَصِیۡرًا ﴿۷۵﴾', 'اس وقت ہم تمکو زندگی میں بھی عذاب کا دگنا اور مرنے پر بھی دگنا مزہ چکھاتے۔ پھر تم ہمارے مقابلے میں کسی کو اپنا مددگار نہ پاتے۔', 'تب تو ضرور چکھاتے ہم تجھ کو دونا مزہ زندگی میں اور دونا مرنے میں پھر نہ پاتا تو اپنے واسطے ہم پر مدد کرنے والا [۱۱۶]', 'In that case, We would have made you taste a double portion (of punishment) in this life and a double portion (of punishment) after death. And then you would have found none to help you against Us.', 'In that case, We would have surely made you taste a double (punishment) in life and a double (punishment) after death, then you would not have found anyone to help you against Us.'),
(2105, 17, 76, 8, 8, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ  اِنۡ  کَادُوۡا  لَیَسۡتَفِزُّوۡنَکَ مِنَ  الۡاَرۡضِ لِیُخۡرِجُوۡکَ مِنۡہَا وَ اِذًا  لَّا یَلۡبَثُوۡنَ خِلٰفَکَ   اِلَّا   قَلِیۡلًا ﴿۷۶﴾', 'اور قریب تھا کہ یہ لوگ تمہیں زمین مکہ سے پھسلا دیں تاکہ تمہیں وہاں سے نکال دیں۔ اور اس وقت تمہارے بعد یہ بھی نہ رہتے مگر کم۔', 'اور وہ تو چاہتے تھے کہ گھبرا دیں تجھ کو اس زمین سے تاکہ نکال دیں تجھ کو یہاں سے اور اس وقت نہ ٹھہریں گے وہ بھی تیرے پیچھے مگر تھوڑا [۱۱۷]', 'And Verily, they were about to frighten you so much as to drive you out from the land. But in that case they would not have stayed (therein) after you, expcept for a little while.', 'And they were likely to harass you in the land, so that they could expel you from there, and in that case, they will have not lived (there) after you, but a little.'),
(2106, 17, 77, 8, 8, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'سُنَّۃَ مَنۡ قَدۡ اَرۡسَلۡنَا قَبۡلَکَ مِنۡ رُّسُلِنَا وَ لَا تَجِدُ  لِسُنَّتِنَا تَحۡوِیۡلًا ﴿٪۷۷﴾', 'جو پیغمبر ہم نے تم سے پہلے بھیجے تھے ان کا اور انکے بارے میں ہمارا یہی طریق رہا ہے اور تم ہمارے طریق میں تغیروتبدل نہ پاؤ گے۔', 'دستور چلا آتا ہے ان رسولوں کا جو تجھ سے پہلے بھیجے ہم نے اپنے پیغمبر اور نہ پائے گا تو ہمارے دستور میں تفاوت [۱۱۸]', '(This was Our) Sunnah (rule or way) with the Messengers We sent before you (O Muhammad SAW), and you will not find any alteration in Our Sunnah (rule or way, etc.).', 'Such has been Our way with the messengers We sent before you. And you will find no change in Our way.'),
(2107, 17, 78, 9, 9, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اَقِمِ الصَّلٰوۃَ  لِدُلُوۡکِ الشَّمۡسِ اِلٰی غَسَقِ  الَّیۡلِ وَ  قُرۡاٰنَ  الۡفَجۡرِ ؕ اِنَّ  قُرۡاٰنَ الۡفَجۡرِ  کَانَ  مَشۡہُوۡدًا ﴿۷۸﴾', 'اے محمد ﷺ سورج کے ڈھلنے سے رات کے اندھیرے تک ظہر۔ عصر۔ مغرب۔ عشاء کی نمازیں اور صبح کو قرآن پڑھا کرو۔ کیونکہ صبح کے وقت قرآن کا پڑھنا فرشتوں کی حاضری کا باعث ہوتا ہے۔', 'قائم رکھ نماز کو [۱۱۹] سورج ڈھلنے سے رات کے اندھیرے تک [۱۲۰] اورقرآن پڑھنا فجر کا [۱۲۱] بیشک قرآن پڑھنا فجر کا ہوتا ہے روبرو [۱۲۲]', 'Perform AsSalat (Iqamat-as-Salat) from mid-day till the darkness of the night (i.e. the Zuhr, Asr, Maghrib, and Isha prayers), and recite the Quran in the early dawn (i.e. the morning prayer). Verily, the recitation of the Quran in the early dawn is ever witnessed (attended by the angels in charge of mankind of the day and the night).', '(O Prophet,) establish Salāh between the decline of the sun and the darkness of the night, and (establish) the recital at dawn. Surely, the recital at dawn is well attended.'),
(2108, 17, 79, 9, 9, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ مِنَ الَّیۡلِ فَتَہَجَّدۡ بِہٖ نَافِلَۃً  لَّکَ ٭ۖ عَسٰۤی اَنۡ  یَّبۡعَثَکَ رَبُّکَ مَقَامًا مَّحۡمُوۡدًا ﴿۷۹﴾', 'اور بعض حصہ شب میں بیدار ہوا کرو اور تہجد کی نماز پڑھا کرو یہ شب خیزی تمہارے لئے ایک اضافی عمل ہے امید ہے کہ اللہ تمکو مقام محمود پر فائز فرمائے۔', 'اور کچھ رات جاگتا رہ قرآن کے ساتھ یہ زیادتی ہے تیرے لئے [۱۲۳] قریب ہے کہ کھڑا کر دے تجھ کو تیرا رب مقام محمود میں [۱۲۴]', 'And in some parts of the night (also) offer the Salat (prayer) with it (i.e. recite the Quran in the prayer), as an additional prayer (Tahajjud optional prayer Nawafil) for you (O Muhammad SAW). It may be that your Lord will raise you to Maqaman Mahmooda (a station of praise and glory, i.e. the highest degree in Paradise!).', 'And during the night, wake up for Salāh of tahajjud , an additional prayer for you. It is very likely that your Lord will place you at Praised Station.'),
(2109, 17, 80, 9, 9, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ قُلۡ رَّبِّ اَدۡخِلۡنِیۡ مُدۡخَلَ صِدۡقٍ وَّ اَخۡرِجۡنِیۡ مُخۡرَجَ صِدۡقٍ وَّ اجۡعَلۡ لِّیۡ مِنۡ لَّدُنۡکَ سُلۡطٰنًا نَّصِیۡرًا ﴿۸۰﴾', 'اور کہو کہ اے پروردگار مجھے مدینے میں اچھی طرح داخل کیجیو اور مکے سے اچھی طرح نکالیو۔ اور اپنے ہاں سے زور و قوت کو میرا مددگار بنائیو۔', 'اور کہہ اے رب داخل کر مجھ کو سچا داخل کرنا اور نکال مجھ کو سچا نکالنا [۱۲۵] اور عطا کر دے مجھ کو اپنے پاس سے حکومت کی مدد [۱۲۶]', 'And say (O Muhammad SAW): My Lord! Let my entry (to the city of Al-Madinah) be good, and likewise my exit (from the city of Makkah) be good. And grant me from You an authority to help me (or a firm sign or a proof).', 'And say, “O my Lord, make me enter a rightful entrance and make me exit a rightful exit, and grant me from Your Own a power, favored (by You).”'),
(2110, 17, 81, 9, 9, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ قُلۡ جَآءَ الۡحَقُّ وَ زَہَقَ الۡبَاطِلُ ؕ اِنَّ الۡبَاطِلَ  کَانَ  زَہُوۡقًا ﴿۸۱﴾', 'اور کہدو کہ حق آ گیا اور باطل نابود ہو گیا بیشک باطل نابود ہونے والا ہے۔', 'اور کہہ آیا سچ اور نکل بھاگا جھوٹ بیشک جھوٹ ہے نکل بھاگنے والا [۱۲۷]', 'And say: \"Truth (i.e. Islamic Monotheism or this Quran or Jihad against polytheists) has come and Batil (falsehood, i.e. Satan or polytheism, etc.) has vanished. Surely! Batil is ever bound to vanish.\"', 'And say, “Truth has come and falsehood has vanished. Falsehood is surely bound to vanish.”'),
(2111, 17, 82, 9, 9, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ نُنَزِّلُ مِنَ الۡقُرۡاٰنِ مَا ہُوَ شِفَآءٌ وَّ رَحۡمَۃٌ  لِّلۡمُؤۡمِنِیۡنَ ۙ وَ لَا یَزِیۡدُ الظّٰلِمِیۡنَ   اِلَّا  خَسَارًا ﴿۸۲﴾', 'اور ہم قرآن میں وہ چیز نازل کرتے ہیں جو مومنوں کے لئے شفا اور رحمت ہے اور ظالموں کے حق میں تو اس سے نقصان ہی بڑھتا ہے۔', 'اور ہم اتارتے ہیں قرآن میں سے جس سے روگ دفع ہوں اور رحمت ایمان والوں کے واسطے اور گنہگاروں کو تو اس سے نقصان ہی بڑھتا ہے [۱۲۸]', 'And We send down from the Quran that which is a healing and a mercy to those who believe (in Islamic Monotheism and act on it), and it increases the Zalimoon (polytheists and wrong-doers) nothing but loss.', 'We reveal the Qur’ān, which is cure and mercy for the believers; and it adds nothing to the unjust but loss.'),
(2112, 17, 83, 9, 9, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ  اِذَاۤ   اَنۡعَمۡنَا عَلَی  الۡاِنۡسَانِ اَعۡرَضَ وَ نَاٰ بِجَانِبِہٖ ۚ وَ اِذَا مَسَّہُ  الشَّرُّ کَانَ یَــُٔوۡسًا ﴿۸۳﴾', 'اور جب ہم انسان کو نعمت بخشتے ہیں تو روگرداں ہو جاتا ہے اور پہلو پھیر لیتا ہے۔ اور جب اسے سختی پہنچتی ہے تو ناامید ہو جاتا ہے۔', 'اور جب ہم آرام بھیجیں انسان پر تو ٹال جائے اور بچائے اپنا پہلو اور جب پہنچے اس کو برائی تو رہ جائے مایوس ہو کر [۱۲۹]', 'And when We bestow Our Grace on man (the disbeliever), he turns away and becomes arrogant, far away from the Right Path. And when evil touches him he is in great despair.', 'When We bestow Our favor upon man, he avoids (to recognize it) and keeps himself far aside (from obedience), and when some evil touches him, he is in total despair.'),
(2113, 17, 84, 9, 9, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'قُلۡ کُلٌّ یَّعۡمَلُ عَلٰی شَاکِلَتِہٖ ؕ فَرَبُّکُمۡ اَعۡلَمُ  بِمَنۡ  ہُوَ  اَہۡدٰی  سَبِیۡلًا ﴿٪۸۴﴾', 'کہدو کہ ہر شخص اپنے طریق کے مطابق عمل کرتا ہے۔ سو تمہارا پروردگار اس شخص سے خوب واقف ہے جو سب سے زیادہ سیدھے رستے پر ہے۔', 'تو کہہ ہر ایک کام کرتا ہے اپنے ڈھنگ پر سو تیرا رب خوب جانتا ہے کس نے خوب پالیا راستہ [۱۳۰]', 'Say (O Muhammad SAW to mankind): \"Each one does according to Shakilatihi (i.e. his way or his religion or his intentions, etc.), and your Lord knows best of him whose path (religion, etc.) is right.\"', 'Say, “Everyone acts in his own style. So, your Lord knows best which one is better guided in his way.”'),
(2114, 17, 85, 10, 10, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ یَسۡـَٔلُوۡنَکَ عَنِ الرُّوۡحِ ؕ قُلِ الرُّوۡحُ مِنۡ  اَمۡرِ رَبِّیۡ وَ مَاۤ  اُوۡتِیۡتُمۡ مِّنَ الۡعِلۡمِ اِلَّا  قَلِیۡلًا ﴿۸۵﴾', 'اور تم سے روح کے بارے میں سوال کرتے ہیں۔ کہدو کہ وہ میرے پروردگار کا ایک حکم ہے اور تم لوگوں کو بہت ہی کم علم دیا گیا ہے۔', 'اور تجھ سے پوچھتے ہیں روح کو [۱۳۱] کہدے روح ہے میرے رب کے حکم سے اور تم کو علم دیا ہے تھوڑا سا [۱۳۲]', 'And they ask you (O Muhammad SAW) concerning the Rooh (the Spirit); Say: \"The Rooh (the Spirit): it is one of the things, the knowledge of which is only with my Lord. And of knowledge, you (mankind) have been given only a little.\"', 'And they ask you about the soul. Say, “The soul is something from the command of my Lord, and you are not given from the knowledge but a little.”'),
(2115, 17, 86, 10, 10, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ لَئِنۡ شِئۡنَا لَنَذۡہَبَنَّ بِالَّذِیۡۤ  اَوۡحَیۡنَاۤ اِلَیۡکَ ثُمَّ لَا تَجِدُ لَکَ بِہٖ عَلَیۡنَا  وَکِیۡلًا ﴿ۙ۸۶﴾', 'اور اگر ہم چاہیں تو جو کتاب ہم تمہاری طرف بھیجتے ہیں اسے دلوں سے محو کر دیں۔ پھر تم اسکے لئے ہمارے مقابلے میں کسی کو مددگار نہ پاؤ۔', 'اور اگر ہم چاہیں تو لیجائیں اس چیز کو جو ہم نے تجھ کو وحی بھیجی پھر تو نہ پائے اپنے واسطے اس کے لاد ینے کو ہم پر کوئی ذمہ دار', 'And if We willed We could surely take away that which We have revealed to you by inspiration (i.e. this Quran). Then you would find no protector for you against Us in that respect.', 'And if We so will, We will surely take away what We have revealed to you, then you shall find no one to rely upon against Us in this matter.'),
(2116, 17, 87, 10, 10, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اِلَّا رَحۡمَۃً  مِّنۡ رَّبِّکَ ؕ اِنَّ  فَضۡلَہٗ  کَانَ عَلَیۡکَ  کَبِیۡرًا ﴿۸۷﴾', 'مگر اس کا قائم رہنا تمہارے پروردگار کی رحمت ہے۔ کچھ شک نہیں کہ تم پر اس کا بڑا فضل ہے۔', 'مگر مہربانی سے تیرے رب کی اس کی بخشش تجھ پر بڑی ہے [۱۳۳]', 'Except as a Mercy from your Lord. Verily! His Grace unto you (O Muhammad SAW) is ever great.', 'But it is a mercy from your Lord. Great is indeed His favor upon you.'),
(2117, 17, 88, 10, 10, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'قُلۡ لَّئِنِ اجۡتَمَعَتِ الۡاِنۡسُ وَ الۡجِنُّ عَلٰۤی اَنۡ یَّاۡتُوۡا بِمِثۡلِ ہٰذَا الۡقُرۡاٰنِ لَا یَاۡتُوۡنَ بِمِثۡلِہٖ وَ لَوۡ کَانَ بَعۡضُہُمۡ لِبَعۡضٍ  ظَہِیۡرًا ﴿۸۸﴾', 'کہدو کہ اگر انسان اور جن اس بات پر مجتمع ہوں کہ اس قرآن جیسا بنا لائیں تو اس جیسا نہ لا سکیں گے اگرچہ وہ ایک دوسرے کے مددگار ہوں۔', 'کہہ اگر جمع ہوں آدمی اور جن اس پر کہ لائیں ایسا قرآن ہر گز نہ لائیں گے ایسا قرآن اور پڑے مدد کیا کریں ایک دوسرے کی [۱۳۴]', 'Say: \"If the mankind and the jinns were together to produce the like of this Quran, they could not produce the like thereof, even if they helped one another.\"', 'Say, “If all the humans and jinns join together to produce anything like this Qur’ān, they will not (be able to) come up with anything like it, even if they assist one another.'),
(2118, 17, 89, 10, 10, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ لَقَدۡ صَرَّفۡنَا لِلنَّاسِ فِیۡ ہٰذَا الۡقُرۡاٰنِ مِنۡ کُلِّ مَثَلٍ ۫ فَاَبٰۤی اَکۡثَرُ النَّاسِ اِلَّا کُفُوۡرًا ﴿۸۹﴾', 'اور ہم نے قرآن میں سب باتیں طرح طرح سے بیان کر دی ہیں مگر اکثر لوگوں نے انکار کرنے کے سوا قبول نہ کیا۔', 'اور ہم نے پھیر پھیر کو سمجھائی لوگوں کو اس قرآن میں ہر مثل سو نہیں رہتے بہت لوگ بن ناشکری کئے [۱۳۵]', 'And indeed We have fully explained to mankind, in this Quran, every kind of similitude, but most mankind refuse (the truth and accept nothing) but disbelief.', 'Indeed We explained every subject in this Qur’ān in various ways for the benefit of mankind. Still, most of the people refused to do anything but reject.'),
(2119, 17, 90, 10, 10, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ قَالُوۡا لَنۡ نُّؤۡمِنَ لَکَ حَتّٰی تَفۡجُرَ  لَنَا مِنَ  الۡاَرۡضِ  یَنۡۢبُوۡعًا ﴿ۙ۹۰﴾', 'اور کہنے لگے کہ ہم تم پر ایمان نہیں لائیں گے جب تک کہ عجیب و غریب باتیں نہ دکھاؤ یعنی یا تو ہمارے لئے زمین سے چشمہ جاری کر دو۔', 'اور بولے ہم نہ مانیں گے تیرا کہا جب تک تو نہ جاری کر دے ہمارے واسطے زمین سے ایک چشمہ [۱۳۶]', 'And they say: \"We shall not believe in you (O Muhammad SAW), until you cause a spring to gush forth from the earth for us;', 'They said, “We shall never believe in you unless you cause a spring to gush forth for us from the earth.'),
(2120, 17, 91, 10, 10, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اَوۡ تَکُوۡنَ لَکَ جَنَّۃٌ  مِّنۡ نَّخِیۡلٍ وَّ عِنَبٍ فَتُفَجِّرَ  الۡاَنۡہٰرَ  خِلٰلَہَا تَفۡجِیۡرًا ﴿ۙ۹۱﴾', 'یا تمہارا کھجوروں اور انگوروں کا کوئی باغ ہو اور اسکے بیچ میں نہریں بہا نکالو۔', 'یا ہو جائے تیرے واسطے ایک باغ کھجور اور انگور کا پھر بہائے تو اس کے بیچ نہریں چلا کر', '\"Or you have a garden of date-palms and grapes, and cause rivers to gush forth in their midst abundantly;', 'Or you have a garden of date palms and grapes, then you bring forth rivers from their midst in abundance.'),
(2121, 17, 92, 10, 10, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اَوۡ تُسۡقِطَ السَّمَآءَ کَمَا زَعَمۡتَ عَلَیۡنَا کِسَفًا اَوۡ تَاۡتِیَ بِاللّٰہِ  وَ الۡمَلٰٓئِکَۃِ  قَبِیۡلًا ﴿ۙ۹۲﴾', 'یا جیسا تم کہا کرتے ہو ہم پر آسمان کے ٹکڑے گرا دو یا اللہ اور فرشتوں کو ہمارے سامنے لے آؤ۔', 'یا گرا دے آسمان ہم پر جیسا کہ تو کہا کرتا ہے ٹکڑے ٹکڑے [۱۳۷] یا لے آ اللہ کو اور فرشتوں کو سامنے [۱۳۸]', '\"Or you cause the heaven to fall upon us in pieces, as you have pretended, or you bring Allah and the angels before (us) face to face;', 'Or you cause the sky to fall upon us in pieces, as you claimed, or you bring Allah and angels before us face to face.'),
(2122, 17, 93, 10, 10, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اَوۡ  یَکُوۡنَ لَکَ بَیۡتٌ مِّنۡ زُخۡرُفٍ اَوۡ تَرۡقٰی فِی السَّمَآءِ ؕ وَ لَنۡ نُّؤۡمِنَ لِرُقِیِّکَ حَتّٰی تُنَزِّلَ عَلَیۡنَا کِتٰبًا نَّقۡرَؤُہٗ ؕ قُلۡ سُبۡحَانَ رَبِّیۡ  ہَلۡ کُنۡتُ  اِلَّا بَشَرًا رَّسُوۡلًا ﴿٪۹۳﴾', 'یا تمہارا سونے کا گھر ہو۔ یا تم آسمان پر چڑھ جاؤ اور ہم تمہارے چڑھنے کو بھی نہیں مانیں گے جب تک کہ کوئی کتاب نہ لاؤ جسے ہم پڑھ بھی لیں کہدو کہ میرا پروودگار پاک ہے میں تو صرف ایک پیغام پہنچانے والا انسان ہوں۔', 'یا ہو جائے تیرے لئے ایک گھر سنہرا [۱۳۹] یا چڑھ جائے تو آسمان میں اور ہم نہ مانیں گے تیرے چڑھ جانے کو جب تک نہ اتار لائے ہم پر ایک کتاب جس کو ہم پڑھیں [۱۴۰] تو کہہ سبحان اللہ میں کون ہوں مگر ایک آدمی ہوں بھیجا ہوا [۱۴۱]', '\"Or you have a house of adornable materials (like silver and pure gold, etc.), or you ascend up into the sky, and even then we will put no faith in your ascension until you bring down for us a Book that we would read.\" Say (O Muhammad SAW): \"Glorified (and Exalted) be my Lord (Allah) above all that evil they (polytheists) associate with Him! Am I anything but a man, sent as a Messenger?\"', 'Or you have a house made of gold. Or you ascend to the sky, and we will not believe in your ascension unless you send down to us a book we may read.” Say, “I proclaim the Purity of my Lord. I am nothing but human, a messenger.”'),
(2123, 17, 94, 11, 11, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ مَا مَنَعَ النَّاسَ اَنۡ یُّؤۡمِنُوۡۤا اِذۡ جَآءَہُمُ الۡہُدٰۤی اِلَّاۤ  اَنۡ قَالُوۡۤا اَبَعَثَ اللّٰہُ   بَشَرًا  رَّسُوۡلًا ﴿۹۴﴾', 'اور جب لوگوں کے پاس ہدایت آ گئ تو انکو ایمان لانے سے اس کے سوا کوئی چیز مانع نہ ہوئی کہ کہنے لگے کہ کیا اللہ نے آدمی کو پیغمبر کر کے بھیجا ہے۔', 'اور لوگوں کو روکا نہیں ایمان لانے سے جب پہنچی ان کو ہدایت مگر اسی بات نے کہ کہنے لگے کیا اللہ نے بھیجا آدمی کو پیغام دے کر [۱۴۲]', 'And nothing prevented men from believing when the guidance came to them, except that they said: \"Has Allah sent a man as (His) Messenger?\"', 'Nothing prevented people from believing, when guidance came to them, except that they said, “Has Allah sent a man as a messenger?”'),
(2124, 17, 95, 11, 11, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'قُلۡ لَّوۡ کَانَ فِی الۡاَرۡضِ مَلٰٓئِکَۃٌ یَّمۡشُوۡنَ مُطۡمَئِنِّیۡنَ لَنَزَّلۡنَا عَلَیۡہِمۡ مِّنَ  السَّمَآءِ  مَلَکًا  رَّسُوۡلًا ﴿۹۵﴾', 'کہدو کہ اگر زمین میں فرشتے ہوتے کہ اس میں چلتے پھرتے اور رہتے بستے تو ہم ان کے پاس کسی فرشتے کو پیغمبر بنا کر بھیجتے۔', 'کہہ اگر ہوتے زمین میں فرشتے پھرتے بستے تو ہم اتارتے ان پر آسمان سے کوئی فرشتہ پیغام دے کر [۱۴۳]', 'Say: \"If there were on the earth, angels walking about in peace and security, We should certainly have sent down for them from the heaven an angel as a Messenger.\"', 'Say, “Had there been angels (living) on the earth, walking about in peace, We would have certainly sent down an angel from the heavens as a messenger.”'),
(2125, 17, 96, 11, 11, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'قُلۡ  کَفٰی بِاللّٰہِ  شَہِیۡدًۢا  بَیۡنِیۡ وَ بَیۡنَکُمۡ ؕ اِنَّہٗ  کَانَ  بِعِبَادِہٖ  خَبِیۡرًۢا  بَصِیۡرًا ﴿۹۶﴾', 'کہدو کہ میرے اور تمہارے درمیان اللہ ہی گواہ کافی ہے۔ وہی اپنے بندوں سے خبردار ہے انکو دیکھنے والا ہے۔', 'کہہ اللہ کافی ہے حق ثابت کرنے والا میرے اور تمہارے بیچ میں وہ ہے اپنے بندوں سے خبردار دیکھنے والا [۱۴۴]', 'Say: \"Sufficient is Allah for a witness between me and you. Verily! He is the All-Knower, the All-Seer of His slaves.\"', 'Say, “Allah is sufficient as witness between me and you. Surely, He is All-Aware, All-Watchful to His servants.”'),
(2126, 17, 97, 11, 11, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ مَنۡ یَّہۡدِ اللّٰہُ  فَہُوَ الۡمُہۡتَدِ ۚ وَ مَنۡ یُّضۡلِلۡ فَلَنۡ تَجِدَ  لَہُمۡ  اَوۡلِیَآءَ مِنۡ دُوۡنِہٖ ؕ وَ نَحۡشُرُہُمۡ یَوۡمَ الۡقِیٰمَۃِ عَلٰی وُجُوۡہِہِمۡ عُمۡیًا وَّ بُکۡمًا وَّ صُمًّا ؕ مَاۡوٰىہُمۡ جَہَنَّمُ ؕ کُلَّمَا خَبَتۡ زِدۡنٰہُمۡ سَعِیۡرًا ﴿۹۷﴾', 'اور جس شخص کو اللہ ہدایت دے وہی ہدایت یاب ہے۔ اور جنکو گمراہ رہنے دے تو تم اللہ کے سوا انکے رفیق نہیں پاؤ گے۔ اور ہم انکو قیامت کے دن اوندھے منہ اندھے گونگے اور بہرے بنا کر اٹھائیں گے اور ان کا ٹھکانہ دوزخ ہے۔ جب اسکی آگ بجھنے کو ہو گی تو ہم انکو عذاب دینے کے لئے اسے اور بھڑکا دیں گے۔', 'اور جس کو راہ دکھلائے اللہ وہی ہے راہ پانے والا اور جس کو بھٹکائے پھر تو نہ پائے انکے واسطے کوئی رفیق اللہ کے سوائے [۱۴۵] اور اٹھائیں گے ہم انکو دن قیامت کے چلیں گے منہ کے بل اندھے اور گونگے اور بہرے [۱۴۶] ٹھکانا ان کو دوزخ ہے جب لگے گی بجھنے اور بھڑکا دیں گے ان پر [۱۴۷]', 'And he whom Allah guides, he is led aright; but he whom He sends astray for such you will find no Auliya (helpers and protectors, etc.), besides Him, and We shall gather them together on the Day of Resurrection on their faces, blind, dumb and deaf, their abode will be Hell; whenever it abates, We shall increase for them the fierceness of the Fire.', 'The one whom Allah guides is the guided one; and those whom He lets go astray, you will never find for them any helpers other than Him. And We shall gather them on the Day of Judgment, with their faces down-blind, dumb and deaf. Their abode is the Fire. Whenever it calms down, We increase its flames for them.'),
(2127, 17, 98, 11, 11, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'ذٰلِکَ جَزَآؤُہُمۡ بِاَنَّہُمۡ کَفَرُوۡا بِاٰیٰتِنَا وَ قَالُوۡۤاءَ اِذَا کُنَّا عِظَامًا وَّ رُفَاتًاءَ اِنَّا  لَمَبۡعُوۡثُوۡنَ  خَلۡقًا جَدِیۡدًا ﴿۹۸﴾', 'یہ انکی سزا ہے اس لئے کہ وہ ہماری آیتوں سے کفر کرتے تھے اور کہتے تھے کہ جب ہم مر کر بوسیدہ ہڈیاں اور ریزہ ریزہ ہو جائیں گے تو کیا ازسرنو پیدا کئے جائیں گے؟', 'یہ ان کی سزا ہے اس واسطے کہ منکر ہوئے ہماری آیتوں سے اور بولے کیا جب ہم ہو گئے ہڈیاں چورا چورا کیا ہم کو اٹھائیں گے نئے بنا کر [۱۴۸]', 'That is their recompense, because they denied Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) and said: \"When we are bones and fragments, shall we really be raised up as a new creation?\"', 'That is their punishment, because they rejected Our signs and said, “Is it that once we are reduced to bones and dust, is it then that we shall be raised, created anew?”'),
(2128, 17, 99, 11, 11, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'اَوَ لَمۡ یَرَوۡا اَنَّ اللّٰہَ  الَّذِیۡ خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ قَادِرٌ عَلٰۤی اَنۡ یَّخۡلُقَ مِثۡلَہُمۡ وَ جَعَلَ لَہُمۡ اَجَلًا  لَّا رَیۡبَ فِیۡہِ ؕ فَاَبَی الظّٰلِمُوۡنَ  اِلَّا کُفُوۡرًا ﴿۹۹﴾', 'کیا انہوں نے نہیں دیکھا کہ اللہ جس نے آسمانوں اور زمین کو پیدا کیا ہے اس بات پر قادر ہے کہ ان جیسے لوگ پیدا کر دے۔ اور اس نے ان کے لئے ایک وقت مقرر کر دیا ہے جسمیں کچھ بھی شک نہیں۔ تو ظالموں نے انکار کے سوا اسے قبول نہ کیا۔', 'کیا نہیں دیکھ چکےکہ جس اللہ نے بنائے آسمان اور زمین وہ بنا سکتا ہے ایسوں کو [۱۴۹] اور مقرر کیا ہے انکے واسطے ایک وقت بے شبہ [۱۵۰] سو نہیں رہا جاتا بے انصافوں کو بن ناشکری کیے [۱۵۱]', 'See they not that Allah, Who created the heavens and the earth, is Able to create the like of them. And He has decreed for them an appointed term, whereof there is not doubt. But the Zalimoon (polytheists and wrong-doers, etc.) refuse (the truth the Message of Islamic Monotheism, and accept nothing) but disbelief.', 'Have they not seen that Allah who has created the heavens and the earth has the power to create them as they were? He has appointed a time for them in which there is no doubt. Still, the wrongdoers refused to do anything but reject.'),
(2129, 17, 100, 11, 11, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'قُلۡ لَّوۡ اَنۡتُمۡ تَمۡلِکُوۡنَ خَزَآئِنَ رَحۡمَۃِ رَبِّیۡۤ  اِذًا  لَّاَمۡسَکۡتُمۡ خَشۡیَۃَ  الۡاِنۡفَاقِ ؕ وَ کَانَ الۡاِنۡسَانُ  قَتُوۡرًا ﴿۱۰۰﴾٪', 'کہدو کہ اگر میرے پروردگار کی رحمت کے خزانے تمہارے ہاتھ میں ہوتے تو تم خرچ ہو جانے کے خوف سے انکو بند کر رکھتے۔ اور انسان دل کا بہت تنگ ہے۔', 'کہہ اگر تمہارے ہاتھ میں ہوتے میرے رب کی رحمت کے خزانے تو ضرور بند کر رکھتے اس ڈر سے کہ خرچ نہ ہو جائیں اور ہے انسان دل کا تنگ [۱۵۲]', 'Say (to the disbelievers): \"If you possessed the treasure of the Mercy of my Lord (wealth, money, provision, etc.), then you would surely hold back (from spending) for fear of (being exhausted), and man is ever miserly!\"', 'Say, “If you were to own the treasures of my Lord’s blessing, you would certainly hold them back, lest it should be spent. Man is so niggardly.”'),
(2130, 17, 101, 12, 12, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ لَقَدۡ اٰتَیۡنَا مُوۡسٰی تِسۡعَ اٰیٰتٍۭ بَیِّنٰتٍ فَسۡـَٔلۡ بَنِیۡۤ  اِسۡرَآءِیۡلَ اِذۡ جَآءَہُمۡ فَقَالَ لَہٗ  فِرۡعَوۡنُ  اِنِّیۡ لَاَظُنُّکَ یٰمُوۡسٰی مَسۡحُوۡرًا ﴿۱۰۱﴾', 'اور ہم نے موسٰی کو نو کھلی نشانیاں دیں تو بنی اسرائیل سے دریافت کر لو کہ جب وہ انکے پاس آئے تو فرعون نے ان سے کہا کہ موسٰی! میں خیال کرتا ہوں کہ تم پر جادو کیا گیا ہے۔', 'اور ہم نے دیں موسٰی کو نو نشانیاں صاف پھر پوچھ بنی اسرائیل سے جب آیا وہ انکے پاس [۱۵۳] تو کہا اس کو فرعون نے میری اٹکل میں تو موسٰی تجھ پر جادو ہوا [۱۵۴]', 'And indeed We gave to Moosa (Moses) nine clear signs. Ask then the Children of Israel, when he came to them, then Firaun (Pharaoh) said to him: \"O Moosa (Moses)! I think you are indeed bewitched.\"', 'Surely we gave Mūsā nine clear signs. So, ask the children of Isrā’īl, when he came to them, Pharaoh said to him, “I am afraid, O Mūsā, you are under the spell of magic.”'),
(2131, 17, 102, 12, 12, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'قَالَ لَقَدۡ عَلِمۡتَ مَاۤ  اَنۡزَلَ ہٰۤؤُلَآءِ  اِلَّا رَبُّ السَّمٰوٰتِ  وَ الۡاَرۡضِ  بَصَآئِرَ ۚ وَ  اِنِّیۡ  لَاَظُنُّکَ یٰفِرۡعَوۡنُ مَثۡبُوۡرًا ﴿۱۰۲﴾', 'انہوں نے کہا کہ تم یہ جانتے ہو کہ آسمانوں اور زمین کے پروردگار کے سوا اسکو کسی نے نازل نہیں کیا۔ اور وہ بھی تم لوگوں کے سمجھانے کو اور اے فرعون! میں خیال کرتا ہوں کہ تم ہلاک ہو جاؤ گے۔', 'بولا تو جان چکا ہے کہ یہ چیزیں کسی نے نہیں اتاریں مگر آسمان اور زمین کے مالک نے سجھانے کو اور میری اٹکل میں فرعون تو غارت ہوا چاہتا ہے [۱۵۵]', '(Moosa (Moses)) said: \"Verily, you know that these signs have been sent down by none but the Lord of the heavens and the earth as clear (evidences i.e. proofs of Allahs Oneness and His Omnipotence, etc.). And I think you are, indeed, O Firaun (Pharaoh) doomed to destruction (away from all good)!\"', 'He (Mūsā) said, “You know well that these (signs) are sent down by none but by the Lord of the heavens and the earth as eye-openers. And, I am afraid O Pharaoh, you are going to be destroyed.”'),
(2132, 17, 103, 12, 12, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'فَاَرَادَ  اَنۡ یَّسۡتَفِزَّہُمۡ مِّنَ الۡاَرۡضِ فَاَغۡرَقۡنٰہُ  وَ مَنۡ  مَّعَہٗ  جَمِیۡعًا ﴿۱۰۳﴾ۙ', 'تو اس نے چاہا کہ انکو سرزمین مصر سے نکال دے تو ہم نے اسکو اور جو اسکے ساتھ تھے۔ سب کو ڈبو دیا۔', 'پھر چاہا کہ بنی اسرائیل کو چین نہ دے اس زمین میں پھر ڈبا دیا ہم نے اسکو اور اس کے ساتھ والوں کو سب کو [۱۵۶]', 'So he resolved to turn them out of the land (of Egypt). But We drowned him and all who were with him.', 'Then he (Pharaoh) tried to harass them to drive them out of the land, so We drowned him and those with him altogether,'),
(2133, 17, 104, 12, 12, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَّ قُلۡنَا مِنۡۢ بَعۡدِہٖ  لِبَنِیۡۤ  اِسۡرَآءِیۡلَ اسۡکُنُوا الۡاَرۡضَ فَاِذَا جَآءَ وَعۡدُ الۡاٰخِرَۃِ  جِئۡنَا بِکُمۡ  لَفِیۡفًا ﴿۱۰۴﴾ؕ', 'اور اسکے بعد بنی اسرائیل سے کہا کہ تم اس ملک میں رہو سہو۔ پھر جب آخرت کا وعدہ آ جائے گا تو ہم تم سب کو جمع کر کے لے آئیں گے۔', 'اور کہا ہم نے اس کے پیچھے بنی اسرائیل کو آباد رہو تم زمین میں پھر جب آئے گا وعدہ آخرت کالے آئیں گے ہم تم کو سمیٹ کر [۱۵۷]', 'And We said to the Children of Israel after him: \"Dwell in the land, then, when the final and the last promise comes near (i.e. the Day of Resurrection or the descent of Christ (Iesa (Jesus), son of Maryam (Mary) on the earth). We shall bring you altogether as mixed crowd (gathered out of various nations).(Tafsir Al-Qurtubee, Vol. 10, Page 338)', 'and thereafter We said to the children of Isrā’īl, “Live in the land. So, when the appointed time of the Hereafter will come, We shall bring you all joined together.”'),
(2134, 17, 105, 12, 12, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ بِالۡحَقِّ اَنۡزَلۡنٰہُ  وَ بِالۡحَقِّ نَزَلَ ؕ وَ مَاۤ اَرۡسَلۡنٰکَ  اِلَّا  مُبَشِّرًا  وَّ  نَذِیۡرًا ﴿۱۰۵﴾ۘ', 'اور ہم نے اس قرآن کو سچائی کے ساتھ نازل کیا ہے اور وہ سچائی کے ساتھ نازل ہوا اور اے محمد ﷺ ہم نے تمکو صرف خوشخبری دینے والا اور ڈر سنانے والا بنا کر بھیجا ہے۔', 'اور سچ کے ساتھ اتارا ہم نے یہ قرآن اور سچ کے ساتھ اترا [۱۵۸] اور تجھ کو جو بھیجا ہم نے سو خوشی اور ڈر سنانے کو [۱۵۹]', 'And with truth We have sent it down (i.e. the Quran), and with truth it has descended. And We have sent you (O Muhammad SAW) as nothing but a bearer of glad tidings (of Paradise, for those who follow your Message of Islamic Monotheism), and a warner (of Hell-fire for those who refuse to follow your Message of Islamic Monotheism).', 'With truth We have sent it (the Qur’ān) down and with truth it descended, and We did not send you but as a bearer of good tidings and as a warner.'),
(2135, 17, 106, 12, 12, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ قُرۡاٰنًا فَرَقۡنٰہُ لِتَقۡرَاَہٗ  عَلَی النَّاسِ عَلٰی  مُکۡثٍ  وَّ  نَزَّلۡنٰہُ  تَنۡزِیۡلًا ﴿۱۰۶﴾', 'اور ہم نے قرآن کو تھوڑا تھوڑا کر کے نازل کیا ہے تاکہ تم لوگوں کو ٹھہر ٹھہر کر پڑھ کر سناؤ اور ہم نے اسکو آہستہ آہستہ اتارا ہے۔', 'اور پڑھنے کا وظیفہ کیا ہم نےقرآن کو جدا جدا کر کے کہ پڑھے تو اسکو لوگوں پر ٹھہر ٹھہر کر اور اس کو ہم نے اتارتے اتارتے اتارا [۱۶۰]', 'And (it is) a Quran which We have divided (into parts), in order that you might recite it to men at intervals. And We have revealed it by stages. (in 23 years).', 'We have divided the Qur’ān in portions, so that you may recite it to the people gradually, and We have revealed it little by little.'),
(2136, 17, 107, 12, 12, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'قُلۡ اٰمِنُوۡا بِہٖۤ  اَوۡ لَا تُؤۡمِنُوۡا ؕ اِنَّ الَّذِیۡنَ  اُوۡتُوا الۡعِلۡمَ مِنۡ قَبۡلِہٖۤ  اِذَا یُتۡلٰی عَلَیۡہِمۡ یَخِرُّوۡنَ لِلۡاَذۡقَانِ سُجَّدًا ﴿۱۰۷﴾ۙ', 'کہدو کہ تم اس پر ایمان لاؤ یا نہ لاؤ یہ فی نفسہ حق ہے جن لوگوں کو اس سے پہلے علم کتاب دیا گیا ہے۔ جب وہ انکو پڑھ کر سنایا جاتا ہے تو وہ تھوڑیوں کے بل سجدے میں پڑتے ہیں۔', 'کہہ کہ تم اس کو مانو یا نہ مانو جن کو علم ملا ہے اس کے پہلے سے جب ان کے پاس اس کو پڑھیں گرتے ہیں تھوڑیوں پر سجدہ میں', 'Say (O Muhammad SAW to them): \"Believe in it (the Quran) or do not believe (in it). Verily! Those who were given knowledge before it (the Jews and the Christians like Abdullah bin Salam and Salman Al-Farisee), when it is recited to them, fall down on their faces in humble prostration.\"', 'Say, “Believe in it or do not believe in it; when it is recited to those who were given knowledge before it, they fall down on their faces in prostration'),
(2137, 17, 108, 12, 12, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَّ یَقُوۡلُوۡنَ سُبۡحٰنَ رَبِّنَاۤ  اِنۡ کَانَ وَعۡدُ رَبِّنَا  لَمَفۡعُوۡلًا ﴿۱۰۸﴾', 'اور کہتے ہیں کہ ہمارا پروردگار پاک ہے۔ بیشک ہمارے پروردگار کا وعدہ پورا ہو کر رہا۔', 'اور کہتے ہیں پاک ہے ہمارا رب بیشک ہمارے رب کا وعدہ ہو کر رہے گا [۱۶۱]', 'And they say: \"Glory be to our Lord! Truly, the Promise of our Lord must be fulfilled.\"', 'and say, “Pure is our Lord. Certainly, the word of our Lord was sure to be fulfilled.”'),
(2138, 17, 109, 12, 12, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ یَخِرُّوۡنَ لِلۡاَذۡقَانِ یَبۡکُوۡنَ وَ یَزِیۡدُہُمۡ خُشُوۡعًا ﴿۱۰۹﴾ٛ', 'اور وہ تھوڑیوں کے بل گر پڑتے ہیں اور روتے جاتے ہیں اور اس سے انکو اور زیادہ عاجزی پیدا ہوتی ہے۔', 'اور گرتے ہیں تھوڑیوں پر روتے ہوئے اور زیادہ ہوتی ہے ان کو عاجزی [۱۶۲]', 'And they fall down on their faces weeping and it adds to their humility.', 'They fall down on their faces weeping, and it increases humbleness in their hearts.'),
(2139, 17, 110, 12, 12, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'قُلِ ادۡعُوا اللّٰہَ  اَوِ ادۡعُوا الرَّحۡمٰنَ ؕ اَیًّامَّا تَدۡعُوۡا فَلَہُ  الۡاَسۡمَآءُ  الۡحُسۡنٰی ۚ وَ لَا تَجۡہَرۡ بِصَلَاتِکَ وَ لَا تُخَافِتۡ بِہَا وَ ابۡتَغِ  بَیۡنَ  ذٰلِکَ  سَبِیۡلًا ﴿۱۱۰﴾', 'کہدو کہ تم معبود برحق کو اللہ کے نام سے پکارو یا رحمٰن کے نام سے جس نام سے پکارو اسکے سب نام اچھے ہیں۔ اور نماز نہ بلند آواز سے پڑھو اور نہ آہستہ بلکہ اسکے بیچ کا طریقہ اختیار کرو۔', 'کہہ اللہ کہہ کر پکارو یا رحمٰن کہہ کر جو کر پکارو گے سو اسی کے ہیں سب نام خاصے [۱۶۳] اور پکار کر مت پڑھ اپنی نماز اور نہ چپکے پڑھ اور ڈھونڈ لے اس کے بیچ میں راہ [۱۶۴]', 'Say (O Muhammad SAW): \"Invoke Allah or invoke the Most Beneficent (Allah), by whatever name you invoke Him (it is the same), for to Him belong the Best Names. And offer your Salat (prayer) neither aloud nor in a low voice, but follow a way between.', 'Say, “Call (Him by the name of) Allah or Ar-RaHmān, in whichever way you call, His are the Best Names.” Do not be (too) loud in your Salāh, nor be (too) low in it, and seek a way in between.'),
(2140, 17, 111, 12, 12, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الاسراء', 'وَ قُلِ الۡحَمۡدُ لِلّٰہِ الَّذِیۡ لَمۡ  یَتَّخِذۡ وَلَدًا وَّ لَمۡ  یَکُنۡ لَّہٗ  شَرِیۡکٌ فِی الۡمُلۡکِ  وَ لَمۡ یَکُنۡ لَّہٗ  وَلِیٌّ  مِّنَ الذُّلِّ وَ کَبِّرۡہُ  تَکۡبِیۡرًا ﴿۱۱۱﴾٪', 'اور کہو کہ سب تعریف اللہ ہی کو ہے جس نے نہ تو کسی کو بیٹا بنایا ہے اور نہ اسکی بادشاہی میں کوئی شریک ہے۔ اور نہ اس وجہ سے کہ وہ عاجز و ناتواں ہے کوئی اس کا مددگار ہے اور اسکو بڑا جان کر اسکی بڑائی کرتے رہو۔', 'اور کہہ سب تعریفیں اللہ کو جونہیں رکھتا اولاد اور نہ کوئی اس کا ساجھی سلطنت میں اور نہ کوئی اس کا مددگار ذلت کے وقت پر اور اس کی برائی کر بڑا جان کر [۱۶۵]', 'And say: \"All the praises and thanks be to Allah, Who has not begotten a son (nor an offspring), and Who has no partner in (His) Dominion, nor He is low to have a Walee (helper, protector or supporter). And magnify Him with all the magnificence, (Allahu-Akbar (Allah is the Most Great)).\"', 'Say, “Praise belongs to Allah who has neither had a son, nor is there any partner to Him in His kingdom, nor is anyone (needed) to protect Him from (any) weakness. And proclaim His greatness, an open proclamation.'),
(2141, 18, 1, 1, 13, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'اَلۡحَمۡدُ لِلّٰہِ الَّذِیۡۤ  اَنۡزَلَ عَلٰی عَبۡدِہِ الۡکِتٰبَ  وَ لَمۡ  یَجۡعَلۡ  لَّہٗ عِوَجًا ؕ﴿ٜ۱﴾', 'سب تعریف اللہ ہی کو ہے جس نے اپنے محبوب بندے محمد ﷺ پر یہ کتاب نازل کی اور اس میں کسی طرح کی کجی اور پیچیدگی نہ رکھی۔', 'سب تعریف اللہ کو جس نے اتاری اپنے بندہ پر کتاب اور نہ رکھی اس میں کچھ کجی [۱]', 'All the praises and thanks be to Allah, Who has sent down to His slave (Muhammad SAW) the Book (the Quran), and has not placed therein any crookedness', 'Praise belongs to Allah who has sent down the Book to His servant, and allowed no crookedness in it,'),
(2142, 18, 2, 1, 13, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'قَیِّمًا  لِّیُنۡذِرَ بَاۡسًا شَدِیۡدًا مِّنۡ لَّدُنۡہُ وَ یُبَشِّرَ الۡمُؤۡمِنِیۡنَ الَّذِیۡنَ یَعۡمَلُوۡنَ الصّٰلِحٰتِ اَنَّ  لَہُمۡ  اَجۡرًا حَسَنًا ۙ﴿۲﴾', 'بلکہ سیدھی اور سلیس اتاری تاکہ لوگوں کو عذاب سخت سے جو اسکی طرف سے آنے والا ہے ڈرائے اور مومنوں کو جو نیک عمل کرتے ہیں خوشخبری سنائے کہ انکے لئے ان کے کاموں کا نیک بدلہ یعنی بہشت ہے۔', 'ٹھیک اتاری تاکہ ڈر سنا دےایک سخت آفت کا اللہ کی طرف سے [۲] اور خوشخبری دے ایمان لانے  والوں کو جو کرتے ہیں نیکیاں کہ ان کے لئے اچھا بدلہ ہے', '(He has made it) Straight to give warning (to the disbelievers) of a severe punishment from Him, and to give glad tidings to the believers (in the Oneness of Allah Islamic Monotheism), who work righteous deeds, that they shall have a fair reward (i.e. Paradise).', 'a straightforward Book to warn of a severe punishment from Him, and to give the good news to the believers, who do righteous deeds, that they will have an excellent reward (Paradise)'),
(2143, 18, 3, 1, 13, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'مَّاکِثِیۡنَ فِیۡہِ اَبَدًا ۙ﴿۳﴾', 'جس میں وہ  ہمیشہ رہیں گے۔', 'جس میں رہا کریں ہمیشہ [۳]', 'They shall abide therein forever.', 'in which they will dwell for ever,'),
(2144, 18, 4, 1, 13, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَّ یُنۡذِرَ الَّذِیۡنَ قَالُوا اتَّخَذَ اللّٰہُ وَلَدًا ٭﴿۴﴾', 'اور ان لوگوں کو بھی ڈرائے جو کہتے ہیں کہ اللہ نے کسی کو بیٹا بنا لیا ہے۔', 'اور ڈر سنا دے انکو جو کہتے ہیں اللہ رکھتا ہے اولاد [۴]', 'And to warn those (Jews, Christians, and pagans) who say, \"Allah has begotten a son (or offspring or children).\"', 'and to warn those who have said that Allah has had a son,'),
(2145, 18, 5, 1, 13, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'مَا لَہُمۡ بِہٖ مِنۡ عِلۡمٍ وَّ لَا لِاٰبَآئِہِمۡ ؕ کَبُرَتۡ کَلِمَۃً  تَخۡرُجُ مِنۡ اَفۡوَاہِہِمۡ ؕ اِنۡ یَّقُوۡلُوۡنَ  اِلَّا کَذِبًا ﴿۵﴾', 'ان کو اس بات کا کچھ بھی علم نہیں اور نہ انکے باپ دادا ہی کو تھا۔ یہ بڑی سخت بات ہے جو انکے منہ سے نکلتی ہے اور کچھ شک نہیں کہ یہ جو کچھ کہتے ہیں محض جھوٹ ہے۔', 'کچھ خبر نہیں ان کو اس بات کی اور نہ ان کے باپ دادوں کو کیا بڑی بات نکلتی ہے ان کے منہ سے سب جھوٹ ہے جو کہتے ہیں [۵]', 'No knowledge have they of such a thing, nor had their fathers. Mighty is the word that comes out of their mouths (i.e. He begot (took) sons and daughters). They utter nothing but a lie.', 'while they have no knowledge about it, nor had their fathers. Grave is the word that comes out of their mouths. They say nothing but lie.'),
(2146, 18, 6, 1, 13, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'فَلَعَلَّکَ بَاخِعٌ نَّفۡسَکَ عَلٰۤی اٰثَارِہِمۡ  اِنۡ لَّمۡ  یُؤۡمِنُوۡا بِہٰذَا  الۡحَدِیۡثِ  اَسَفًا ﴿۶﴾', 'اے پیغمبر اگر یہ اس کلام پر ایمان نہ لائیں تو شاید تم انکے پیچھے رنج کر کر کے اپنے تئیں ہلاک کر دو گے۔', 'سو کہیں تو گھونٹ ڈالے گا اپنی جان کو ان کے پیچھے اگر وہ نہ مانیں گے اس بات کو پچتا پچتا کر [۶]', 'Perhaps, you, would kill yourself (O Muhammad SAW) in grief, over their footsteps (for their turning away from you), because they believe not in this narration (the Quran).', 'So, (O Prophet) perhaps you are going to kill yourself after them, out of grief, if they do not believe in this discourse.'),
(2147, 18, 7, 1, 13, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'اِنَّا جَعَلۡنَا مَا عَلَی الۡاَرۡضِ زِیۡنَۃً  لَّہَا لِنَبۡلُوَہُمۡ  اَیُّہُمۡ   اَحۡسَنُ  عَمَلًا ﴿۷﴾', 'جو چیز زمین پر ہے ہم نے اسکو زمین کے لئے زینت بنایا ہے تاکہ لوگوں کی آزمائش کریں کہ ان میں کون اچھے عمل کرنے والا ہے۔', 'ہم نے بنایا ہے جو کچھ زمین پر ہے اس کی رونق تاکہ جانچیں لوگوں کو کون ان میں اچھا کرتا ہے کام [۷]', 'Verily! We have made that which is on earth as an adornment for it, in order that We may test them (mankind) as to which of them are best in deeds. (i.e.those who do good deeds in the most perfect manner, that means to do them (deeds) totally for Allahs sake and in accordance to the legal ways of the Prophet SAW ).', 'Surely, We have made what is on earth an adornment for it, so that We test them as to who among them is better in deeds.'),
(2148, 18, 8, 1, 13, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ اِنَّا لَجٰعِلُوۡنَ مَا عَلَیۡہَا صَعِیۡدًا جُرُزًا  ؕ﴿۸﴾', 'اور جو چیز زمین پر ہے ہم اسکو نابود کر کے بنجر میدان کر دیں گے۔', 'اور ہم کو کرنا ہے جو کچھ اس پر ہے میدان چھانٹ کر [۸]', 'And verily! We shall make all that is on it (the earth) a bare dry soil (without any vegetation or trees, etc.).', 'And surely, We are going to turn whatever is thereon into a barren land.'),
(2149, 18, 9, 1, 13, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'اَمۡ حَسِبۡتَ اَنَّ  اَصۡحٰبَ الۡکَہۡفِ وَ الرَّقِیۡمِ ۙ کَانُوۡا  مِنۡ  اٰیٰتِنَا  عَجَبًا ﴿۹﴾', 'کیا تم خیال کرتے ہو کہ غار اور لوح والے ہماری نشانیوں میں سے عجیب تھے؟', 'کیا تو خیال کرتا ہے کہ غار اور کھوہ کے رہنے والے ہماری قدرتوں میں عجب اچنبھا تھے [۹]', 'Do you think that the people of the Cave and the Inscription (the news or the names of the people of the Cave) were a wonder among Our Signs?', 'Do you think that the People of Kahf (the Cave) and Raqīm (inscription) were unusual out of Our signs?'),
(2150, 18, 10, 1, 13, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'اِذۡ اَوَی الۡفِتۡیَۃُ  اِلَی الۡکَہۡفِ فَقَالُوۡا رَبَّنَاۤ اٰتِنَا مِنۡ لَّدُنۡکَ رَحۡمَۃً  وَّ ہَیِّیٔۡ لَنَا مِنۡ  اَمۡرِنَا  رَشَدًا  ﴿۱۰﴾', 'جب وہ نوجوان غار میں جا رہے تو کہنے لگے کہ اے ہمارے پروردگار ہم پر اپنے ہاں سے رحمت نازل فرما۔ اور ہمارے کام میں درستی کے سامان مہیا کر۔', 'جب جا بیٹھے وہ جوان پہاڑ کی کھو میں پھر بولے اے رب دے ہم کو اپنے پاس سے بخشش اور پوری کر دے ہمارے کام کی درستی', '(Remember) when the young men fled for refuge (from their disbelieving folk) to the Cave, they said: \"Our Lord! Bestow on us mercy from Yourself, and facilitate for us our affair in the right way!\"', 'When the young men took refuge in the Cave and said, “Our Lord, bless us with mercy from Your own and provide us with guidance in our matters.”'),
(2151, 18, 11, 1, 13, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'فَضَرَبۡنَا عَلٰۤی اٰذَانِہِمۡ فِی الۡکَہۡفِ سِنِیۡنَ عَدَدًا ﴿ۙ۱۱﴾', 'تو ہم نے غار میں کئی سال تک انکے کانوں پر نیند کا پردہ ڈالے رکھا یعنی انکو سلائے رکھا۔', 'پھر تھپک دئے ہم نے ان کے کان اس کھوہ میں چند برس گنتی کے [۱۰]', 'Therefore We covered up their (sense of) hearing (causing them, to go in deep sleep) in the Cave for a number of years.', 'So, We sealed up their hearing (putting them to sleep) in the Cave for a number of years.'),
(2152, 18, 12, 1, 13, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'ثُمَّ بَعَثۡنٰہُمۡ لِنَعۡلَمَ اَیُّ الۡحِزۡبَیۡنِ اَحۡصٰی  لِمَا  لَبِثُوۡۤا  اَمَدًا ﴿٪۱۲﴾', 'پھر انکو جگا اٹھایا تاکہ معلوم کریں کہ جتنی مدت وہ غار میں رہے دونوں جماعتوں میں سے اسکی مقدار کس کو خوب یاد ہے۔', 'پھر ہم نے ان کو اٹھایا کہ معلوم کریں دو فرقوں میں کس نے یاد رکھی ہے جتنی مدت وہ رہے [۱۱]', 'Then We raised them up (from their sleep), that We might test which of the two parties was best at calculating the time period that they had tarried.', 'Thereafter We raised them up, so that We know which of the two groups had better calculated the period in which they remained (sleeping).'),
(2153, 18, 13, 2, 14, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'نَحۡنُ نَقُصُّ عَلَیۡکَ نَبَاَہُمۡ  بِالۡحَقِّ ؕ اِنَّہُمۡ فِتۡیَۃٌ  اٰمَنُوۡا بِرَبِّہِمۡ وَ زِدۡنٰہُمۡ ہُدًی  ﴿٭ۖ۱۳﴾', 'ہم انکے حالات تم سے صحیح صحیح بیان کرتے ہیں۔ وہ کئ نوجوان تھے جو اپنے پروردگار پر ایمان لائے تھے۔ اور ہم نے انکو اور زیادہ ہدایت دی تھی۔', 'ہم سنا دیں تجھ کو ان کا حال تحقیقی وہ کئ جوان ہیں کہ یقین لائے اپنے رب پر اور زیادہ دی ہم نے انکو سوجھ [۱۲]', 'We narrate unto you (O Muhammad SAW) their story with truth: Truly! They were young men who believed in their Lord (Allah), and We increased them in guidance.', 'We narrate to you their story with truth. They were young men who believed in their Lord and We gave them more guidance.'),
(2154, 18, 14, 2, 14, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَّ رَبَطۡنَا عَلٰی قُلُوۡبِہِمۡ اِذۡ قَامُوۡا فَقَالُوۡا رَبُّنَا رَبُّ السَّمٰوٰتِ وَ الۡاَرۡضِ لَنۡ نَّدۡعُوَا۠ مِنۡ دُوۡنِہٖۤ  اِلٰـہًا لَّقَدۡ قُلۡنَاۤ  اِذًا  شَطَطًا ﴿۱۴﴾', 'اور انکے دلوں کو مربوط یعنی مضبوط کر دیا جب وہ اٹھ کھڑے ہوئے تو کہنے لگے کہ ہمارا پروردگار آسمانوں اور زمین کا مالک ہے۔ ہم اسکے سوا کسی کو معبود سمجھ کر نہ پکاریں گے اگر ایسا کیا تو اس وقت ہم نے بے عقلی کی بات کی۔', 'اور گرہ دی ان کے دل پر [۱۳] جب کھڑے ہوئے پھر بولے ہمارا رب ہے رب آسمان اور زمین کا نہ پکاریں گے ہم اس کے سوائے کسی کو معبود نہیں تو کہی ہم نے بات عقل سے دور [۱۴]', 'And We made their hearts firm and strong (with the light of Faith in Allah and bestowed upon them patience to bear the separation of their kith and kin and dwellings, etc.) when they stood up and said: \"Our Lord is the Lord of the heavens and the earth, never shall we call upon any ilah (god) other than Him; if we did, we should indeed have uttered an enormity in disbelief.', 'We made their hearts firm when they stood up and said, “Our Lord is the Lord of the heavens and the earth. We shall never invoke any god other than Him, otherwise we would be saying something far from the truth.'),
(2155, 18, 15, 2, 14, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'ہٰۤؤُلَآءِ قَوۡمُنَا اتَّخَذُوۡا مِنۡ دُوۡنِہٖۤ اٰلِہَۃً ؕ  لَوۡ لَا یَاۡتُوۡنَ عَلَیۡہِمۡ بِسُلۡطٰنٍۭ بَیِّنٍ ؕ فَمَنۡ اَظۡلَمُ  مِمَّنِ افۡتَرٰی عَلَی اللّٰہِ کَذِبًا ﴿ؕ۱۵﴾', 'ان ہماری قوم کے لوگوں نے اسکے سوا اور معبود بنا رکھے ہیں۔ بھلا یہ انکے معبود ہونے پر کوئی کھلی دلیل کیوں نہیں لاتے۔ تو اس سے زیادہ کون ظالم ہے جو اللہ پر جھوٹ باندھے۔', 'یہ ہماری قوم ہے ٹھہرا لئے انہوں نے اللہ کے سوائے اور  معبود کیوں نہیں لاتے ان پر کوئی سند کھلی پھر اس سے بڑا گنہگار کون جس نے باندھا اللہ پر جھوٹ [۱۵]', '\"These our people have taken for worship aliha (gods) other than Him (Allah). Why do they not bring for them a clear authority? And who does more wrong than he who invents a lie against Allah.', 'These, our people, have adopted gods other than Him. Why do they not bring a clear proof in their favor? So, who is more unjust than the one who fabricates a lie against Allah?');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(2156, 18, 16, 2, 14, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ اِذِ اعۡتَزَلۡتُمُوۡہُمۡ وَمَا یَعۡبُدُوۡنَ  اِلَّا اللّٰہَ  فَاۡ وٗۤا اِلَی الۡکَہۡفِ یَنۡشُرۡ لَکُمۡ رَبُّکُمۡ مِّنۡ رَّحۡمَتِہٖ وَیُہَیِّیٔۡ لَکُمۡ مِّنۡ  اَمۡرِکُمۡ  مِّرۡفَقًا ﴿۱۶﴾', 'اور جب تم نے ان مشرکوں سے اور جنکی یہ اللہ کے سوا عبادت کرتے ہیں ان سے کنارہ کر لیا ہے تو غار میں چل رہو۔ تمہارا پروردگار تمہارے لئے اپنی رحمت وسیع کر دے گا اور تمہارے کاموں میں آسانی کے سامان مہیا کرے گا۔', 'اور جب تم نے کنارہ کر لیا ان سے اور جن کو وہ پوجتے ہیں اللہ کےسوائے تو اب جا بیٹھو اس کھوہ میں پھیلا دے تم پر رب تمہار ا کچھ اپنی رحمت سے اور بنا دیوے تمہارے واسطے تمہارے کام میں آرام [۱۶]', '(The young men said to one another): \"And when you withdraw from them, and that which they worship, except Allah, then seek refuge in the Cave, your Lord will open a way for you from His Mercy and will make easy for you your affair (i.e. will give you what you will need of provision, dwelling, etc.).\"', 'When you have turned away from them, and those whom they worship, except Allah, then seek refuge in the cave, and your Lord will extend His mercy for you, and provide you ease in your matters.”'),
(2157, 18, 17, 2, 14, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ تَرَی الشَّمۡسَ  اِذَا طَلَعَتۡ  تَّزٰوَرُ عَنۡ کَہۡفِہِمۡ ذَاتَ الۡیَمِیۡنِ وَ اِذَا غَرَبَتۡ تَّقۡرِضُہُمۡ ذَاتَ الشِّمَالِ وَ ہُمۡ فِیۡ فَجۡوَۃٍ مِّنۡہُ ؕ ذٰلِکَ مِنۡ اٰیٰتِ اللّٰہِ ؕ مَنۡ یَّہۡدِ اللّٰہُ فَہُوَ الۡمُہۡتَدِ ۚ وَ مَنۡ  یُّضۡلِلۡ  فَلَنۡ تَجِدَ  لَہٗ   وَلِیًّا  مُّرۡشِدًا ﴿٪۱۷﴾', 'اور جب سورج نکلے تو تم دیکھو کہ دھوپ انکے غار سے داہنی طرف سمٹ جائے اور جب غروب ہو تو ان سے بائیں طرف کترا جائے اور وہ اس غار کے کشادہ حصے میں تھے یہ اللہ کی نشانیوں میں سے ہیں۔ جسکو اللہ ہدایت دے وہ ہدایت یاب ہے۔ اور جسکو گمراہ رہنے دے تو تم اسکے لئے کوئی دوست راہ بتانے والا نہ پاؤ گے۔', 'اور تو دیکھے دھوپ جب نکلتی ہے بچ کر جاتی ہے ان کی کھوہ سےداہنے کو اور جب ڈوبتی ہے کترا جاتی ہے ان سے بائیں کو اور وہ میدان میں ہیں اس کے یہ ہے اللہ کی قدرتوں سے [۱۷] جسکو راہ دیوے اللہ وہی آئے راہ پر اور جس کو وہ بچلائے پھر تو نہ پائے اس کا کوئی رفیق راہ پر لانے والا [۱۸]', 'And you might have seen the sun, when it rose, declining to the right from their Cave, and when it set, turning away from them to the left, while they lay in the midst of the Cave. That is (one) of the Ayat (proofs, evidences, signs) of Allah. He whom Allah guides, is rightly guided; but he whom He sends astray, for him you will find no Walee (guiding friend) to lead him (to the right Path).', 'You would see the sun, when it rose, turning away from their Cave towards the right; and when it set, it bypassed them towards the left, and they were (lying) in the hollow thereof. That is one of the signs of Allah.Whomsoever Allah guides is the one who gets the right path and whomsoever He lets go astray, for him you will find no one to help, no one to lead.'),
(2158, 18, 18, 3, 15, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ تَحۡسَبُہُمۡ اَیۡقَاظًا وَّ ہُمۡ رُقُوۡدٌ ٭ۖ وَّ نُقَلِّبُہُمۡ ذَاتَ الۡیَمِیۡنِ وَ ذَاتَ الشِّمَالِ ٭ۖ وَ کَلۡبُہُمۡ بَاسِطٌ ذِرَاعَیۡہِ  بِالۡوَصِیۡدِ ؕ لَوِ اطَّلَعۡتَ عَلَیۡہِمۡ لَوَلَّیۡتَ مِنۡہُمۡ فِرَارًا  وَّ  لَمُلِئۡتَ مِنۡہُمۡ  رُعۡبًا ﴿۱۸﴾', 'اور تم ان کے متعلق خیال کرو کہ وہ جاگ رہے ہیں۔ حالانکہ وہ سوتے ہیں۔ اور ہم انکو دائیں اور بائیں کروٹ بدلاتے تھے۔ اور ان کا کتا چوکھٹ پر دونوں ہاتھ پھیلائے ہوئے تھا۔ اگر تم انکو جھانک کر دیکھتے تو پیٹھ پھیر کر بھاگ جاتے اور ان سے دہشت میں آ جاتے۔', 'اور تو سمجھے وہ جاگتے ہیں اور وہ سو رہے ہیں اور کروٹیں دلاتے ہیں ہم انکو داہنے اور بائیں اور کتا ان کا پسار رہا ہے اپنی باہیں چوکھٹ پر اگر تو جھانک کر دیکھے ان کو تو پیٹھ دے کر بھاگے ان سے اور بھر جائے تجھ میں انکی دہشت [۱۹]', 'And you would have thought them awake, while they were asleep. And We turned them on their right and on their left sides, and their dog stretching forth his two forelegs at the entrance (of the Cave or in the space near to the entrance of the Cave (as a guard at the gate)). Had you looked at them, you would certainly have turned back from them in flight, and would certainly have been filled with awe of them.', 'And you would think they were awake while they were asleep. We turned them on their sides, right and left. And their dog had its forelegs stretched out to the doorstep. If you had a look at them, you would have fled away from them and would have been filled with awe of them.'),
(2159, 18, 19, 3, 15, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ کَذٰلِکَ بَعَثۡنٰہُمۡ  لِیَتَسَآءَلُوۡا  بَیۡنَہُمۡ ؕ قَالَ قَآئِلٌ مِّنۡہُمۡ کَمۡ لَبِثۡتُمۡ ؕ قَالُوۡا لَبِثۡنَا یَوۡمًا اَوۡ بَعۡضَ یَوۡمٍ ؕ قَالُوۡا رَبُّکُمۡ  اَعۡلَمُ بِمَا لَبِثۡتُمۡ ؕ فَابۡعَثُوۡۤا اَحَدَکُمۡ بِوَرِقِکُمۡ ہٰذِہٖۤ  اِلَی الۡمَدِیۡنَۃِ فَلۡیَنۡظُرۡ  اَیُّہَاۤ   اَزۡکٰی  طَعَامًا فَلۡیَاۡتِکُمۡ بِرِزۡقٍ مِّنۡہُ  وَ لۡـیَؔ‍‍‍تَلَطَّفۡ وَ لَا  یُشۡعِرَنَّ  بِکُمۡ  اَحَدًا ﴿۱۹﴾', 'اور اسی طرح ہم نے انکو اٹھایا تاکہ آپس میں ایک دوسرے سے دریافت کریں۔ ایک کہنے والے نے کہا کہ تم یہاں کتنی مدت رہے؟ انہوں نے کہا کہ ایک دن یا اس سے بھی کم۔ انہوں نے کہا کہ جتنی مدت تم رہے ہو تمہارا پروردگار ہی اسکو خوب جانتا ہے۔ تو اپنے میں سے کسی کو یہ روپیہ دے کر شہر بھیجو وہ دیکھے کہ نفیس کھانا کون سا ہے تو اس میں سے کھانا لے آئے اور احتیاط سے آئے جائے اور تمہارا حال کسی کو نہ بتائے۔', 'اور اسی طرح ان کو جگا دیا ہم نے کہ آپس میں پوچھنے لگے ایک بولا ان میں کتنی دیر ٹھہرےتم بولے ہم ٹھہرے ایک دن یا دن سے کم بولے تمہارا رب ہی خوب جانے جتنی دیر تم رہے ہو اب بھیجو اپنے میں سے ایک کو یہ روپیہ دے کر اپنا اس شہر میں پھر دیکھے کونسا کھانا ستھرا ہے سو لائے تمہارے پاس اس میں سے کھانا اور نرمی سے جائے اور جتا نہ دے تمہاری خبر کسی کو', 'Likewise, We awakened them (from their long deep sleep) that they might question one another. A speaker from among them said: \"How long have you stayed (here)?\" They said: \"We have stayed (perhaps) a day or part of a day.\" They said: \"Your Lord (Alone) knows best how long you have stayed (here). So send one of you with this silver coin of yours to the town, and let him find out which is the good lawful food, and bring some of that to you. And let him be careful and let no man know of you.', 'In this way We raised them up until they asked each other. One of them said, “How long did you tarry?” They said, “A day, or part of a day.” They said, “Your Lord knows best how long you tarried.” So, send one of you with this silver (coin) of yours to the city and let him look around which of the eatables are the purest and let him bring you some food from there. And he must act in polite manner, and must not let anyone know about you.'),
(2160, 18, 20, 3, 15, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'اِنَّہُمۡ اِنۡ یَّظۡہَرُوۡا عَلَیۡکُمۡ یَرۡجُمُوۡکُمۡ اَوۡ یُعِیۡدُوۡکُمۡ فِیۡ مِلَّتِہِمۡ وَ لَنۡ تُفۡلِحُوۡۤا اِذًا  اَبَدًا ﴿۲۰﴾', 'اگر وہ تم پر دسترس پالیں گے تو تمہیں سنگسار کر دیں گے۔ یا پھر اپنے مذہب میں داخل کر لیں گے اور اس وقت تم کبھی فلاح نہیں پاؤ گے۔', 'وہ لوگ اگر خبر پالیں تمہاری پتھروں سے مار ڈالیں تم کو یا لوٹا لیں تم کو اپنے دین میں اور تب تو بھلا نہ ہو گا تمہارا کبھی [۲۰]', '\"For if they come to know of you, they will stone you (to death or abuse and harm you) or turn you back to their religion, and in that case you will never be successful.\"', 'If they (the habitants of the city) will know about you, they will force you to revert to their faith, and in that case, you will never find success.”'),
(2161, 18, 21, 3, 15, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ کَذٰلِکَ اَعۡثَرۡنَا عَلَیۡہِمۡ لِیَعۡلَمُوۡۤا اَنَّ وَعۡدَ اللّٰہِ حَقٌّ وَّ اَنَّ السَّاعَۃَ  لَا رَیۡبَ فِیۡہَا ۚ٭ اِذۡ یَتَنَازَعُوۡنَ بَیۡنَہُمۡ اَمۡرَہُمۡ فَقَالُوا ابۡنُوۡا عَلَیۡہِمۡ بُنۡیَانًا ؕ رَبُّہُمۡ اَعۡلَمُ بِہِمۡ ؕ قَالَ الَّذِیۡنَ غَلَبُوۡا عَلٰۤی اَمۡرِہِمۡ  لَنَتَّخِذَنَّ  عَلَیۡہِمۡ  مَّسۡجِدًا ﴿۲۱﴾', 'اور اسی طرح ہم نے لوگوں کو ان کے حال سے خبردار کر دیا تاکہ وہ جانیں کہ اللہ کا وعدہ سچا ہے۔ اور یہ کہ قیامت جس کا وعدہ کیا جاتا ہے اس میں کچھ شک نہیں۔ اس وقت لوگ انکے بارے میں باہم جھگڑنے لگے۔ اور کہنے لگے کہ ان کے غار پر عمارت بنا دو۔ ان کا پروردگار ان کے حال سے خوب واقف ہے۔ جو لوگ انکے معاملے میں غلبہ رکھتے تھے وہ کہنے لگے کہ ہم انکے غار پر مسجد بنائیں گے۔', 'اور اسی طرح خبر ظاہر کر دی ہم نے انکی تاکہ لوگ جان لیں کہ اللہ کا وعدہ ٹھیک ہے اور قیامت کے آنے میں دھوکہ نہیں جب  جھگڑ رہے تھے آپس میں اپنی بات پر [۲۱] پھر کہنے لگے بناؤ ان پر ایک عمارت انکا رب خوب جانتا ہے ان کا حال بولے وہ لوگ جن کا کام غالب تھا ہم بنائیں گے ان کی جگہ پر عبادت خانہ [۲۲]', 'And thus We made their case known to the people, that they might know that the Promise of Allah is true, and that there can be no doubt about the Hour. (Remember) when they (the people of the city) disputed among themselves about their case, they said: \"Construct a building over them, their Lord knows best about them,\" (then) those who won their point said (most probably the disbelievers): \"We verily shall build a place of worship over them.\"', 'And in this way, We made them known to the people (of the city), so that they realize that Allah’s promise is true, and that there is no doubt about the Hour (the Day of Resurrection). When they were disputing among themselves in their matter, they said, “Erect a building over them. Their Lord knows them best.” Said those who prevailed in their matter, “We will certainly make a mosque over them.”'),
(2162, 18, 22, 3, 15, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'سَیَقُوۡلُوۡنَ ثَلٰثَۃٌ رَّابِعُہُمۡ کَلۡبُہُمۡ ۚ وَ یَقُوۡلُوۡنَ خَمۡسَۃٌ سَادِسُہُمۡ کَلۡبُہُمۡ رَجۡمًۢا بِالۡغَیۡبِ ۚ وَ یَقُوۡلُوۡنَ سَبۡعَۃٌ وَّ ثَامِنُہُمۡ کَلۡبُہُمۡ ؕ قُلۡ رَّبِّیۡۤ  اَعۡلَمُ بِعِدَّتِہِمۡ مَّا یَعۡلَمُہُمۡ  اِلَّا  قَلِیۡلٌ ۬۟ فَلَا تُمَارِ فِیۡہِمۡ  اِلَّا مِرَآءً  ظَاہِرًا ۪ وَّ لَا تَسۡتَفۡتِ  فِیۡہِمۡ  مِّنۡہُمۡ   اَحَدًا ﴿٪۲۲﴾', 'بعض لوگ اٹکل پچو کہیں گے کہ وہ تین تھے اور چوتھا ان کا کتا تھا اور بعض کہیں گے کہ وہ پانچ تھے اور چھٹا ان کا کتا تھا۔ اور بعض کہیں گے کہ وہ سات تھے اور آٹھواں ان کا کتا تھا۔ کہدو کہ میرا پروردگار ہی انکے شمار سے خوب واقف ہے انکو جانتے بھی ہیں تو تھوڑے ہی لوگ جانتے ہیں تو تم انکے معاملے میں بحث نہ کرنا مگر سرسری سی بحث۔ اور نہ انکے بارے میں ان میں سے کسی سے کچھ دریافت ہی کرنا۔', 'اب یہی کہیں گے وہ تین ہیں چوتھا ان کا کتا اور یہ بھی کہیں گے وہ پانچ ہیں چھٹا ان کا کتا بدون نشانی دیکھے پتھر چلانا [۲۳] اور یہ بھی کہیں گے وہ سات ہیں اور آٹھوں انکا کتا تو کہہ میرا رب خوب جانتا ہے ان کی گنتی ان کی خبر نہیں رکھتے مگر تھوڑے لوگ سو مت جھگڑ ان کی بات میں مگر سر سری جھگڑا اور مت تحقیق کر ان کا حال ان میں کسی سے [۲۴]', '(Some) say they were three, the dog being the fourth among them; (others) say they were five, the dog being the sixth, guessing at the unseen; (yet others) say they were seven, the dog being the eighth. Say (O Muhammad SAW): \"My Lord knows best their number; none knows them but a few.\" So debate not (about their number, etc.) except with the clear proof (which We have revealed to you). And consult not any of them (people of the Scripture, Jews and Christians) about (the affair of) the people of the Cave.', 'Some will say, “(They were) three, the fourth of them being their dog,” and some will say, “Five, the sixth of them being their dog, just making conjectures.” And others will say, “Seven, the eighth of them is their dog.” Say, “My Lord knows best about their number.” No one knows them except a few, so do not argue about them except an apparent argumentation. And do not ask anyone of these about them.'),
(2163, 18, 23, 4, 16, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ لَا تَقُوۡلَنَّ لِشَایۡءٍ  اِنِّیۡ  فَاعِلٌ ذٰلِکَ غَدًا ﴿ۙ۲۳﴾', 'اور کسی کام کی نسبت نہ کہنا کہ میں اسے کل کر دوں گا۔', 'اور نہ کہنا کسی کام کو کہ میں یہ کروں گا کل کو', 'And never say of anything, \"I shall do such and such thing tomorrow.\"', 'And never say about anything, “I will do this tomorrow,”'),
(2164, 18, 24, 4, 16, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'اِلَّاۤ اَنۡ یَّشَآءَ اللّٰہُ ۫ وَ اذۡکُرۡ رَّبَّکَ اِذَا نَسِیۡتَ وَ قُلۡ عَسٰۤی اَنۡ یَّہۡدِیَنِ رَبِّیۡ لِاَقۡرَبَ مِنۡ ہٰذَا  رَشَدًا ﴿۲۴﴾', 'مگر ان شاء اللہ کہہ کر یعنی اگر اللہ چاہے تو کر دوں گا اور جب اللہ کا نام لینا بھول جاؤ تو یاد آنے پر لے لو۔ اور کہدو کہ امید ہے کہ میرا پروردگار مجھے اس سے بھی زیادہ ہدایت کی باتیں بتائے۔', 'مگر یہ کہ اللہ چاہے اور یاد کر لے اپنے رب کو جب بھول جائے اور کہہ امید ہے کہ میرا رب مجھ کو دکھلائے اس سے زیادہ نزدیک راہ نیکی کی [۲۵]', 'Except (with the saying), \"If Allah will!\" And remember your Lord when you forget and say: \"It may be that my Lord guides me unto a nearer way of truth than this.\"', 'unless (you say - ‘if) Allah wills.’ And remember your Lord if you forget, and say (to those who asked you about the story of the People of the Cave), “May be, my Lord will lead me to something closer than this to guidance.”'),
(2165, 18, 25, 4, 16, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ لَبِثُوۡا فِیۡ  کَہۡفِہِمۡ ثَلٰثَ مِائَۃٍ سِنِیۡنَ وَ ازۡدَادُوۡا  تِسۡعًا ﴿۲۵﴾', 'اور اصحاب کہف اپنے غار میں نو اوپر تین سو سال رہے۔', 'اور مدت گذری ان پر اپنی کھوہ میں تین سو برس اور ان کے اوپر نو [۲۶]', 'And they stayed in their Cave three hundred (solar) years, and add nine (for lunar years).', 'They stayed in their Cave for three hundred years and added nine.'),
(2166, 18, 26, 4, 16, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'قُلِ اللّٰہُ  اَعۡلَمُ بِمَا لَبِثُوۡا ۚ لَہٗ غَیۡبُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ اَبۡصِرۡ بِہٖ  وَ  اَسۡمِعۡ ؕ مَا  لَہُمۡ  مِّنۡ  دُوۡنِہٖ مِنۡ وَّلِیٍّ ۫ وَّ لَا یُشۡرِکُ  فِیۡ  حُکۡمِہٖۤ   اَحَدًا ﴿۲۶﴾', 'کہدو کہ جتنی مدت وہ رہے اسے اللہ ہی خوب جانتا ہے۔ اسی کو آسمانوں اور  زمین کی پوشیدہ باتیں معلوم ہیں۔ وہ کیا خوب دیکھنے والا اور کیا خوب سننے والا ہے۔ اسکے سوا ان کا کوئی کارساز نہیں اور نہ وہ اپنے حکم میں کسی کو شریک کرتا ہے۔', 'تو کہہ اللہ خوب جانتا ہے جتنی مدت ان پر گذری اسی کی پاس ہیں چھپے بھید آسمان اور زمین کے کیا عجیب دیکھتا اور سنتا ہے [۲۷] کوئی نہیں بندوں پر اس کے سوائے مختار اور نہیں شریک کرتا اپنے حکم میں کسی کو [۲۸]', 'Say: \"Allah knows best how long they stayed. With Him is (the knowledge of) the unseen of the heavens and the earth. How clearly He sees, and hears (everything)! They have no Walee (Helper, Disposer of affairs, Protector, etc.) other than Him, and He makes none to share in His Decision and His Rule.\"', 'Say, “Allah knows best how long they stayed. To Him belongs the unseen of the heavens and the earth - how well He sees and how well He hears! They have no supporter other than Him and He lets no one share His authority.”'),
(2167, 18, 27, 4, 16, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ اتۡلُ مَاۤ  اُوۡحِیَ  اِلَیۡکَ مِنۡ  کِتَابِ رَبِّکَ ۚؕ  لَا مُبَدِّلَ لِکَلِمٰتِہٖ ۚ۟ وَ لَنۡ تَجِدَ مِنۡ دُوۡنِہٖ  مُلۡتَحَدًا ﴿۲۷﴾', 'اور اپنے پروردگار کی کتاب کو جو تمہارے پاس بھیجی جاتی ہے پڑھتے رہا کرو۔ اسکی باتوں کو کوئی بدلنے والا نہیں۔ اور اسکے سوا تم کہیں پناہ بھی نہیں پاؤ گے۔', 'اور پڑھ جو وحی ہوئی تجھ کو تیرے رب کی کتاب سے کوئی بدلنے والا نہیں اسکی باتیں اور کہیں نہ پائے گا تو اس کے سوائے چھپنے کو جگہ [۲۹]', 'And recite what has been revealed to you (O Muhammad SAW) of the Book (the Quran) of your Lord (i.e. recite it, understand and follow its teachings and act on its orders and preach it to men). None can change His Words, and none will you find as a refuge other than Him.', 'And recite what has been revealed to you of the Book of your Lord. There is no one to change His words, and you will never find a refuge beside Him.'),
(2168, 18, 28, 4, 16, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ اصۡبِرۡ نَفۡسَکَ مَعَ الَّذِیۡنَ یَدۡعُوۡنَ رَبَّہُمۡ بِالۡغَدٰوۃِ  وَ الۡعَشِیِّ یُرِیۡدُوۡنَ وَجۡہَہٗ  وَ لَا  تَعۡدُ عَیۡنٰکَ عَنۡہُمۡ ۚ تُرِیۡدُ زِیۡنَۃَ الۡحَیٰوۃِ  الدُّنۡیَا ۚ وَ لَا تُطِعۡ مَنۡ  اَغۡفَلۡنَا قَلۡبَہٗ عَنۡ  ذِکۡرِنَا وَ اتَّبَعَ ہَوٰىہُ  وَ کَانَ   اَمۡرُہٗ   فُرُطًا ﴿۲۸﴾', 'اور جو لوگ صبح و شام اپنے پروردگار کو پکارتے اور اسکی خوشنودی کے طالب ہیں انکے ساتھ صبر کرتے رہو۔ اور تمہاری نگاہیں ان میں سے گذر کر اور طرف نہ دوڑیں۔ کہ تم دنیاوی زندگی کی رونقوں کے خواستگار ہو جاؤ۔ اور جس شخص کے دل کو ہم نے اپنی یاد سے غافل کر دیا ہے اور وہ اپنی خواہش کی پیروی کرتا ہے اور اس کا کام حد سے بڑھ گیا ہے اس کا کہا نہ ماننا۔', 'اور روکے رکھ اپنے آپ کو ان کے ساتھ جو پکارتے ہیں اپنے رب کو صبح اور شام طالب ہیں اسکے منہ کے [۳۰] اور نہ دوڑیں تیری آنکھیں انکو چھوڑ کر تلاش میں رونق زندگانی دنیا کی [۳۱] اور نہ کہا مان اس کا جس کا دل غافل کیا ہم نے اپنی یاد سے اور پیچھے پڑا ہوا ہے اپنی خوشی کے اور اس کا کام ہے حد پر نہ رہنا [۳۲]', 'And keep yourself (O Muhammad SAW) patiently with those who call on their Lord (i.e. your companions who remember their Lord with glorification, praising in prayers, etc., and other righteous deeds, etc.) morning and afternoon, seeking His Face, and let not your eyes overlook them, desiring the pomp and glitter of the life of the world; and obey not him whose heart We have made heedless of Our Remembrance, one who follows his own lusts and whose affair (deeds) has been lost.', 'Keep yourself content with those who call their Lord morning and evening, seeking His pleasure, and let not your eyes overlook them, seeking the splendor of the worldly life. And do not obey the one whose heart We have made heedless of Our remembrance, and who has followed his desire and whose behavior has exceeded the limits.'),
(2169, 18, 29, 4, 16, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ قُلِ الۡحَقُّ مِنۡ رَّبِّکُمۡ ۟ فَمَنۡ شَآءَ فَلۡیُؤۡمِنۡ وَّ مَنۡ شَآءَ  فَلۡیَکۡفُرۡ ۙ اِنَّاۤ اَعۡتَدۡنَا لِلظّٰلِمِیۡنَ نَارًا ۙ اَحَاطَ بِہِمۡ سُرَادِقُہَا ؕ وَ اِنۡ یَّسۡتَغِیۡثُوۡا یُغَاثُوۡا بِمَآءٍ کَالۡمُہۡلِ یَشۡوِی الۡوُجُوۡہَ ؕ بِئۡسَ الشَّرَابُ ؕ وَ سَآءَتۡ  مُرۡتَفَقًا ﴿۲۹﴾', 'اور کہدو کہ لوگو یہ قرآن تمہارے پروردگار کی طرف سے برحق ہے تو جو چاہے ایمان لائے اور جو چاہے کافر رہے ہم نے ظالموں کے لئے دوزخ کی آگ تیار کر رکھی ہے جسکی قناتیں انکو گھیر رہی ہوں گی۔ اور اگر فریاد کریں گے تو ایسے کھولتے ہوئے پانی سے انکی داد رسی کی جائے گی جو پگھلے ہوئے تانبے کی طرح گرم ہو گا اور جو انکے چہروں کو بھون ڈالے گا انکے پینے کا پانی بھی برا اور آرام گاہ بھی بری۔', 'اور کہہ سچی بات ہے تمہارے رب کی طرف سے پھر جو کوئی چاہے مانے اور جو کوئی چاہے نہ مانے [۳۳] ہم نے تیار کر رکھی ہے گنہگاروں کے واسطے آگ کہ گھیر رہی ہیں انکو اسکی قناتیں [۳۴] اور اگر فریاد کریں گے تو ملے گا پانی جیسے پیپ بھون ڈالے منہ کو کیا برا پینا ہے اور کیا برا آرام [۳۵]', 'And say: \"The truth is from your Lord.\" Then whosoever wills, let him believe, and whosoever wills, let him disbelieve. Verily, We have prepared for the Zalimoon (polytheists and wrong-doers, etc.), a Fire whose walls will be surrounding them (disbelievers in the Oneness of Allah). And if they ask for help (relief, water, etc.) they will be granted water like boiling oil, that will scald their faces. Terrible the drink, and an evil Murtafaqa (dwelling, resting place, etc.)!', 'And say, “The truth is from your Lord. Now, whoever so wills may believe and whoever so wills may deny.” Surely, We have prepared for the unjust a fire, whose tent will envelop them. And if they will beg for help, they shall be helped with water like oily dregs that will scald the faces. Vile is the drink, and evil is the Fire as a resting-place.'),
(2170, 18, 30, 4, 16, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'اِنَّ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ اِنَّا  لَا نُضِیۡعُ اَجۡرَ مَنۡ اَحۡسَنَ عَمَلًا ﴿ۚ۳۰﴾', 'اور جو ایمان لائے اور کام بھی نیک کرتے رہے تو ہم نیک کام کرنے والوں کا اجر ضائع نہیں کرتے۔', 'بیشک جو لوگ یقین لائے اور کیں نیکیاں ہم نہیں کھوتے بدلہ اس کا جس نے بھلا کیا کام [۳۶]', 'Verily! As for those who believe and do righteous deeds, certainly! We shall not suffer to be lost the reward of anyone who does his (righteous) deeds in the most perfect manner.', 'As for those who believe and do righteous deeds,-of course, We do not waste the reward of those who are good in deeds.'),
(2171, 18, 31, 4, 16, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'اُولٰٓئِکَ لَہُمۡ جَنّٰتُ عَدۡنٍ تَجۡرِیۡ مِنۡ تَحۡتِہِمُ الۡاَنۡہٰرُ یُحَلَّوۡنَ فِیۡہَا مِنۡ اَسَاوِرَ مِنۡ ذَہَبٍ وَّ یَلۡبَسُوۡنَ ثِیَابًا خُضۡرًا مِّنۡ سُنۡدُسٍ وَّ اِسۡتَبۡرَقٍ مُّتَّکِئِیۡنَ فِیۡہَا عَلَی الۡاَرَآئِکِ ؕ نِعۡمَ الثَّوَابُ ؕ وَ حَسُنَتۡ  مُرۡتَفَقًا ﴿٪۳۱﴾', 'ایسے لوگوں کے لئے ہمیشہ رہنے کے باغ ہیں جن میں ان کے محلوں کے نیچے نہریں بہ رہی ہیں۔ انکو وہاں سونے کے کنگن پہنائے جائیں گے اور وہ باریک دیبا اور اطلس کے سبز کپڑے پہنا کریں گے۔ اور تختوں پر تکیے لگا کر بیٹھا کریں گے کیا خوب بدلہ اور کیا خوب آرام گاہ ہے۔', 'ایسوں کے واسطے باغ ہیں بسنے کے بہتی ہیں ان کے نیچے نہریں پہنائے جائیں گے ان کو وہاں کنگن سونے کے [۳۷] اور پہنیں گے کپڑے سبز باریک اور گاڑھے ریشم کے [۳۸] تکیہ لگائے ہوئے ان میں تختوں پر کیا خوب بدلہ ہے اور کیا خوب آرام [۳۹]', 'These! For them will be Adn (Eden) Paradise (everlasting Gardens); wherein rivers flow underneath them, therein they will be adorned with bracelets of gold, and they will wear green garments of fine and thick silk. They will recline therein on raised thrones. How good is the reward, and what an excellent Murtafaqa (dwelling, resting place, etc.)!', 'Those are the ones for whom there are eternal gardens, rivers flowing beneath them. They will be adorned therein with bracelets of gold, and they will be dressed in green garments, made of fine silk and thick silk, reclining therein on couches. Excellent is the reward and beautiful is the Paradise as a resting-place.'),
(2172, 18, 32, 5, 17, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ اضۡرِبۡ لَہُمۡ مَّثَلًا رَّجُلَیۡنِ جَعَلۡنَا لِاَحَدِہِمَا جَنَّتَیۡنِ مِنۡ اَعۡنَابٍ وَّ حَفَفۡنٰہُمَا بِنَخۡلٍ وَّ جَعَلۡنَا بَیۡنَہُمَا زَرۡعًا ﴿ؕ۳۲﴾', 'اور ان سے دو شخصوں کا حال بیان کرو جن میں سے ایک کو ہم نے انگور کے دو باغ عنایت کئے تھے اور انکے گردا گرد کھجوروں کے درخت لگا دیئے تھے اور انکے درمیان کھیتی پیدا کر دی تھی۔', 'اور بتلا انکو مثل دو مردوں کی [۴۰] کر دیے ہم نے ان میں سے ایک کے لئے دو باغ انگور کے اور گرد ان کے کھجویرں اور  رکھی دونوں کے بیچ میں کھیتی [۴۱]', 'And put forward to them the example of two men; unto one of them We had given two gardens of grapes, and We had surrounded both with date-palms; and had put between them green crops (cultivated fields etc.).', 'Give them an example. There were two men; We gave one of them two gardens of grapes, and surrounded both of them with date-palms, and placed vegetation between them.'),
(2173, 18, 33, 5, 17, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'کِلۡتَا الۡجَنَّتَیۡنِ اٰتَتۡ اُکُلَہَا وَ لَمۡ تَظۡلِمۡ مِّنۡہُ  شَیۡئًا ۙ وَّ  فَجَّرۡنَا خِلٰلَہُمَا نَہَرًا ﴿ۙ۳۳﴾', 'دونوں باغ کثرت سے پھل لاتے۔ اور اسکی پیداوار میں کسی طرح کی کمی نہ ہوتی اور دونوں میں ہم نے ایک نہر بھی جاری کر رکھی تھی۔', 'دونوں باغ لاتے ہیں اپنا میوہ اور نہیں گھٹاتے اس میں سے کچھ [۴۲] اور بہا دی ہم نے ان دنوں کے بیچ نہر [۴۳]', 'Each of those two gardens brought forth its produce, and failed not in the least therein, and We caused a river to gush forth in the midst of them.', 'Both the gardens brought forth their fruit, and suppressed nothing from it, and We caused a stream to flow through them.'),
(2174, 18, 34, 5, 17, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَّ کَانَ لَہٗ  ثَمَرٌ ۚ فَقَالَ لِصَاحِبِہٖ وَ ہُوَ یُحَاوِرُہٗۤ  اَنَا  اَکۡثَرُ  مِنۡکَ مَالًا وَّ اَعَزُّ   نَفَرًا ﴿۳۴﴾', 'اور اس طرح اس شخص کو انکی پیداوار ملتی رہتی تھی تو ایک دن جبکہ وہ اپنے دوست سے باتیں کر رہا تھا کہنے لگا کہ میں تم سے مال و دولت میں بھی زیادہ ہوں اور جتھے اور جماعت کے لحاظ سے بھی زیادہ عزت والا ہوں۔', 'اور ملا اسکو پھل [۴۴] پھر بولا اپنے ساتھی سے جب باتیں کرنے لگا اس سے میرے پاس زیادہ ہے تجھ سے مال اور آبرو کے لوگ [۴۵]', 'And he had property (or fruit) and he said to his companion, in the course of mutual talk: I am more than you in wealth and stronger in respect of men.\" (See Tafsir Qurtubee, Vol. 10, Page 403).', 'And he had wealth. So, he said to his companion while conversing with him, “I am greater than you in wealth and stronger in manpower.”'),
(2175, 18, 35, 5, 17, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ دَخَلَ جَنَّتَہٗ  وَ ہُوَ ظَالِمٌ  لِّنَفۡسِہٖ ۚ قَالَ مَاۤ   اَظُنُّ  اَنۡ  تَبِیۡدَ  ہٰذِہٖۤ   اَبَدًا ﴿ۙ۳۵﴾', 'اور ایسی شیخیوں سے اپنے حق میں ظلم کرتا ہوا اپنے باغ میں داخل ہوا کہنے لگا کہ میں نہیں خیال کرتا کہ یہ باغ کبھی تباہ ہو۔', 'اور گیا اپنے باغ میں اور وہ برا کر رہا تھا اپنی جان پر [۴۶] بولا نہیں آتا مجھ کو خیال کہ خراب ہووے یہ باغ کبھی', 'And he went into his garden while in a state (of pride and disbelief) unjust to himself. He said: \"I think not that this will ever perish.', 'And he entered his garden while he was doing wrong to himself. He said, “I do not think that this will ever perish,'),
(2176, 18, 36, 5, 17, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَّ مَاۤ  اَظُنُّ السَّاعَۃَ قَآئِمَۃً ۙ وَّ لَئِنۡ رُّدِدۡتُّ اِلٰی رَبِّیۡ  لَاَجِدَنَّ خَیۡرًا مِّنۡہَا مُنۡقَلَبًا ﴿۳۶﴾', 'اور نہ خیال کرتا ہوں کہ قیامت برپا ہو اور اگر میں اپنے پروردگار کی طرف لوٹایا بھی جاؤں۔ تو وہاں ضرور اس سے اچھی جگہ پاؤں گا۔', 'اور نہیں خیال کرتا ہوں کہ قیامت ہونے والی ہے اور اگر کبھی پہنا دیا گیا میں اپنے رب کے پاس پاؤں گا بہتر اس سے وہاں پہنچ کر [۴۷]', '\"And I think not the Hour will ever come, and if indeed I am brought back to my Lord, (on the Day of Resurrection), I surely shall find better than this when I return to Him.\"', 'and I do not think that the Hour (Day of Judgment) has to come. And even if I am sent back to my Lord, I will surely find a better place than this to resort to.”'),
(2177, 18, 37, 5, 17, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'قَالَ لَہٗ  صَاحِبُہٗ  وَ ہُوَ یُحَاوِرُہٗۤ اَکَفَرۡتَ بِالَّذِیۡ خَلَقَکَ مِنۡ تُرَابٍ ثُمَّ  مِنۡ  نُّطۡفَۃٍ   ثُمَّ  سَوّٰىکَ  رَجُلًا ﴿ؕ۳۷﴾', 'تو اس کا دوست جو اس سے گفتگو کر رہا تھا کہنے لگا کہ کیا تم اس ذات سے کفر کرتے ہو جس نے تم کو مٹی سے پیدا کیا پھر نطفے سے پھر تمہیں پورا آدمی بنایا۔', 'کہا اس کو دوسرے نے جب بات کرنے لگا کیا تو منکر ہو گیا اس سے جس نے پیدا کیا تجھ کو مٹی سے پھر قطرہ سے پھر پورا کر دیا تجھ کو مرد', 'His companion said to him, during the talk with him: \"Do you disbelieve in Him Who created you out of dust (i.e. your father Adam), then out of Nutfah (mixed semen drops of male and female discharge), then fashioned you into a man?', 'Said his companion, as he was conversing with him, “Do you deny Him who created you from dust, then from a drop (of semen), then He made you a perfect man?'),
(2178, 18, 38, 5, 17, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'لٰکِنَّا۠ ہُوَ اللّٰہُ  رَبِّیۡ وَ لَاۤ  اُشۡرِکُ بِرَبِّیۡۤ اَحَدًا ﴿۳۸﴾', 'مگر میں تو یہ کہتا ہوں کہ اللہ ہی میرا پروردگار ہے اور میں اپنے پروردگار کے ساتھ کسی کو شریک نہیں کرتا۔', 'پھر میں تو یہی کہتا ہوں وہی اللہ ہے میرا رب اور نہیں مانتا شریک اپنے رب کا کسی کو [۴۸]', '\"But as for my part (I believe) that He is Allah, my Lord and none shall I associate as partner with my Lord.', 'As for me, I believe that Allah is my Lord, and I do not associate anyone with my Lord.'),
(2179, 18, 39, 5, 17, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ لَوۡ لَاۤ  اِذۡ دَخَلۡتَ جَنَّتَکَ قُلۡتَ مَا شَآءَ  اللّٰہُ ۙ لَا قُوَّۃَ اِلَّا بِاللّٰہِ ۚ اِنۡ تَرَنِ  اَنَا  اَقَلَّ  مِنۡکَ  مَالًا  وَّ  وَلَدًا ﴿ۚ۳۹﴾', 'اور جب تم اپنے باغ میں داخل ہوئے تو تم نے ماشاء اللہ لاقوۃ الاباللہ کیوں نہ کہا؟ اگر تم مجھے مال و اولاد میں اپنے سے کمتر دیکھتے ہو۔', 'اور جب تو آتا تھا اپنے باغ میں کیوں نہ کہا تو نے جو چاہے اللہ سو ہو طاقت نہیں مگر جو دے اللہ [۴۹] اگر تو دیکھتا ہے مجھ کو کہ میں کم ہوں تجھ سے مال اور اولاد میں', 'It was better for you to say, when you entered your garden: That which Allah wills (will come to pass)! There is no power but with Allah . If you see me less than you in wealth, and children.', 'Why, when you entered your garden, did you not say, ‘(Everything is) as Allah wills. There is no power except with Allah’? If you see me inferior to you in wealth and children,'),
(2180, 18, 40, 5, 17, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'فَعَسٰی رَبِّیۡۤ  اَنۡ یُّؤۡتِیَنِ خَیۡرًا مِّنۡ جَنَّتِکَ وَ یُرۡسِلَ عَلَیۡہَا حُسۡبَانًا مِّنَ السَّمَآءِ  فَتُصۡبِحَ  صَعِیۡدًا  زَلَقًا ﴿ۙ۴۰﴾', 'تو عجب نہیں کہ میرا پروردگار مجھے تمہارے باغ سے بہتر عطا فرمائے اور تمہارے اس  باغ پر آسمان سے آفت بھیج دے تو وہ صاف میدان ہو جائے۔', 'تو امید ہے کہ میرا رب دیوے مجھ کو تیرے باغ سے بہتر [۵۰] اور بھیج دے اس پر لو کا ایک جھونکا آسمان سے پھر صبح کو رہ جاٹے میدان صاف', '\"It may be that my Lord will give me something better than your garden, and will send on it Husban (torment, bolt, etc.) from the sky, then it will be a slippery earth.', 'then, it is likely that my Lord will give me (what is) better than your garden, and will send to it a punishment from the heavens, and it will become a barren land.'),
(2181, 18, 41, 5, 17, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'اَوۡ یُصۡبِحَ  مَآؤُہَا غَوۡرًا  فَلَنۡ تَسۡتَطِیۡعَ  لَہٗ  طَلَبًا ﴿۴۱﴾', 'یا اس باغ کی نہر کا پانی گہرائی میں اتر جائے تو پھر تم اسے تلاش نہ کر سکو۔', 'یا صبح کو ہو رہے اس کا پانی خشک پھر نہ لا سکے تو اس کو ڈھونڈھ کر [۵۱]', '\"Or the water thereof (of the gardens) becomes deep-sunken (underground) so that you will never be able to seek it.\"', 'Or, its water will sink deep in the earth, so that you will never be able to search it out.”'),
(2182, 18, 42, 5, 17, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ اُحِیۡطَ بِثَمَرِہٖ  فَاَصۡبَحَ یُقَلِّبُ کَفَّیۡہِ عَلٰی مَاۤ  اَنۡفَقَ فِیۡہَا وَ ہِیَ خَاوِیَۃٌ عَلٰی عُرُوۡشِہَا وَ یَقُوۡلُ یٰلَیۡتَنِیۡ لَمۡ اُشۡرِکۡ بِرَبِّیۡۤ   اَحَدًا ﴿۴۲﴾', 'اور اسکے میووں کو عذاب نے آ گھیرا اور وہ اپنی چھتریوں پر گر کر رہ گیا۔ تو جو مال اس نے اس پر خرچ کیا تھا۔ اس پر حسرت سے ہاتھ ملنے لگا۔ اور کہنے لگا کہ کاش میں اپنے پروردگار کے ساتھ کسی کو شریک نہ بناتا۔', 'اور سمیٹ لیا گیا اس کا سارا پھل پھر صبح کو رہ گیا ہاتھ نچاتا [۵۲] اس مال پر جو اس میں لگایا تھا اور وہ گرا پڑا تھا اپنی چھتریوں پر [۵۳] اور کہنے لگا کیا خوب ہوتا اگر میں شریک نہ بناتا اپنے رب کا کسی کو [۵۴]', 'So his fruits were encircled (with ruin). And he remained clapping his hands with sorrow over what he had spent upon it, while it was all destroyed on its trellises, he could only say: \"Would I had ascribed no partners to my Lord!\" (Tafsir Ibn Katheer)', 'And its produce was overwhelmed by calamities and he stood wringing his hands (in anguish) over what he had invested in it, while it was fallen down on its trellises and he was saying, “I wish I had not ascribed any partner to my Lord!”'),
(2183, 18, 43, 5, 17, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ لَمۡ تَکُنۡ لَّہٗ  فِئَۃٌ  یَّنۡصُرُوۡنَہٗ  مِنۡ  دُوۡنِ  اللّٰہِ  وَ مَا  کَانَ  مُنۡتَصِرًا  ﴿ؕ۴۳﴾', 'اس وقت اللہ کے سوا کوئی جماعت اسکی مددگار نہ ہوئی اور نہ وہ بدلہ لے سکا۔', 'اور نہ ہوئی اس کی جماعت کہ مدد کریں اس کی اللہ کے سوائے اور نہ ہوا وہ کہ خود بدلہ لے سکے [۵۵]', 'And he had no group of men to help him against Allah, nor could he defend or save himself.', 'There were no supporters for him beside Allah, who could come to his help, nor was he able to defend himself.'),
(2184, 18, 44, 5, 17, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'ہُنَالِکَ الۡوَلَایَۃُ لِلّٰہِ الۡحَقِّ ؕ ہُوَ خَیۡرٌ ثَوَابًا  وَّ  خَیۡرٌ  عُقۡبًا ﴿٪۴۴﴾', 'یہاں سے ثابت ہوا کہ حکومت سب اللہ کی ہے جو معبود برحق ہے وہی بہترین ثواب عطا کرنے والا اور بہترین انجام لانے والا ہے۔', 'یہاں سب اختیار ہے اللہ سچے کا اسی کا انعام بہتر ہے اور اچھا ہے اسی کا دیا ہوا بدلہ [۵۶]', 'There (on the Day of Resurrection), Al-Walayah (the protection, power, authority and kingdom) will be for Allah (Alone), the True God. He (Allah) is the Best for reward and the Best for the final end. (La ilaha ill-Allah none has the right to be worshipped but Allah).', 'That is where the power of protection rests with Allah, the True God. He is the best in rewarding and best in requiting.'),
(2185, 18, 45, 6, 18, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ اضۡرِبۡ لَہُمۡ مَّثَلَ الۡحَیٰوۃِ الدُّنۡیَا کَمَآءٍ اَنۡزَلۡنٰہُ مِنَ السَّمَآءِ فَاخۡتَلَطَ بِہٖ نَبَاتُ الۡاَرۡضِ فَاَصۡبَحَ ہَشِیۡمًا تَذۡرُوۡہُ  الرِّیٰحُ ؕ وَ کَانَ اللّٰہُ عَلٰی کُلِّ شَیۡءٍ  مُّقۡتَدِرًا ﴿۴۵﴾', 'اور ان سے دنیا کی زندگی کی مثال بھی بیان کر دو کہ وہ ایسی ہے جیسے پانی جسے ہم نے آسمان سے برسایا۔ تو اسکے ساتھ زمین کی پیدوار ملکر نکلی پھر وہ چورا چورار ہو گئ کہ ہوائیں اسے اڑاتی پھرتی ہیں۔ اور اللہ تو ہر چیز پر قدرت رکھتا ہے۔', 'اور بتلا دے ان کو مثل دنیا کی زندگی کی جیسے پانی اتارا ہم نے آسمان سے پھر رلا ملا نکلا اس کی وجہ سے زمین کا سبزہ پھر کل کو ہو گیا چورا چورا ہوا میں اڑتا ہوا [۵۷] اور اللہ کو ہے ہر چیز پر قدرت [۵۸]', 'And put forward to them the example of the life of this world, it is like the water (rain) which We send down from the sky, and the vegetation of the earth mingles with it, and becomes fresh and green. But (later) it becomes dry and broken pieces, which the winds scatter. And Allah is Able to do everything.', 'Give them the example of the worldly life; it is like water We sent down from the sky, then the vegetation of the earth was mingled with it, and then it turned into chaff that is blown by the winds, and Allah is powerful over everything.'),
(2186, 18, 46, 6, 18, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'اَلۡمَالُ وَ الۡبَنُوۡنَ زِیۡنَۃُ  الۡحَیٰوۃِ الدُّنۡیَا ۚ وَ الۡبٰقِیٰتُ الصّٰلِحٰتُ خَیۡرٌ عِنۡدَ  رَبِّکَ  ثَوَابًا  وَّ  خَیۡرٌ  اَمَلًا ﴿۴۶﴾', 'مال اور بیٹے تو دنیا کی زندگی کی رونق و زینت ہیں۔ اور نیکیاں جو باقی رہنے والی ہیں وہ ثواب کے لحاظ سے تمہارے پروردگار کے ہاں بہت اچھی اور امید کے لحاظ سے بہت بہتر ہیں۔', 'مال اور بیٹے رونق ہیں دنیا کی زندگی میں اور باقی رہنے والی نیکیوں کا بہتر ہے تیرے رب کے یہاں بدلا اور بہتر ہے توقع [۵۹]', 'Wealth and children are the adornment of the life of this world. But the good righteous deeds (five compulsory prayers, deeds of Allahs obedience, good and nice talk, remembrance of Allah with glorification, praises and thanks, etc.), that last, are better with your Lord for rewards and better in respect of hope.', 'Wealth and children are the embellishment of the worldly life, and the everlasting virtues are better with your Lord, both in rewards and in creating good hopes'),
(2187, 18, 47, 6, 18, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ یَوۡمَ نُسَیِّرُ الۡجِبَالَ وَ تَرَی الۡاَرۡضَ بَارِزَۃً ۙ وَّ حَشَرۡنٰہُمۡ  فَلَمۡ  نُغَادِرۡ  مِنۡہُمۡ اَحَدًا ﴿ۚ۴۷﴾', 'اور جس دن ہم پہاڑوں کو چلائیں گے اور تم زمین کو صاف میدان دیکھو گے اور ان لوگوں کو ہم جمع کر لیں گے تو ان میں سے کسی کو بھی نہیں چھوڑیں گے۔', 'اور جس دن ہم چلائیں پہاڑ اور تو دیکھے زمین کو کھلی ہوئی [۶۰] اور گھیر ملائیں ہم انکو پھر نہ چھوڑیں ان میں سے ایک کو [۶۱]', 'And (remember) the Day We shall cause the mountains to pass away (like clouds of dust), and you will see the earth as a levelled plain, and we shall gather them all together so as to leave not one of them behind.', 'And (visualize) the Day when We will make mountains move, and you will see the earth fully exposed, and We shall gather them together, so as not to leave a single one of them.'),
(2188, 18, 48, 6, 18, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ عُرِضُوۡا عَلٰی رَبِّکَ صَفًّا ؕ لَقَدۡ جِئۡتُمُوۡنَا کَمَا خَلَقۡنٰکُمۡ  اَوَّلَ مَرَّۃٍۭ ۫ بَلۡ زَعَمۡتُمۡ  اَلَّنۡ نَّجۡعَلَ  لَکُمۡ  مَّوۡعِدًا ﴿۴۸﴾', 'اور سب تمہارے پروردگار کے سامنے صف باندھ کر لائے جائیں گے تو ہم ان سے کہیں گے کہ جس طرح ہم نے تمکو پہلی بار پیدا کیا تھا اسی طرح آج تم ہمارے سامنے آئے۔ لیکن تم نے تو یہ خیال کر رکھا تھا کہ ہم نے تمہارے لئے قیامت کا کوئی وقت مقرر ہی نہیں کیا۔', 'اور سامنے آئیں تیرے رب کے صف باندھ کر آ پہنچے تم ہمارے پاس جیسے ہم نے بنایا تھا تم کو پہلی بار نہیں تم تو کہتے تھے کہ نہ مقرر کریں گے ہم تمہارے لئے کوئی وعدہ [۶۲]', 'And they will be set before your Lord in (lines as) rows, (and Allah will say): \"Now indeed, you have come to Us as We created you the first time. Nay, but you thought that We had appointed no meeting for you (with Us).\"', 'And they shall be presented lined-up before your Lord. (It will be said to them,) “Lo! You have come to Us just as We had created you for the first time, while you claimed that We would not make any appointed time for you.”'),
(2189, 18, 49, 6, 18, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ وُضِعَ الۡکِتٰبُ فَتَرَی الۡمُجۡرِمِیۡنَ مُشۡفِقِیۡنَ  مِمَّا فِیۡہِ وَ یَقُوۡلُوۡنَ یٰوَیۡلَتَنَا مَالِ ہٰذَا الۡکِتٰبِ لَا یُغَادِرُ صَغِیۡرَۃً وَّ لَا کَبِیۡرَۃً  اِلَّاۤ  اَحۡصٰہَا ۚ وَ  وَجَدُوۡا مَا عَمِلُوۡا حَاضِرًا ؕ وَ لَا یَظۡلِمُ  رَبُّکَ  اَحَدًا ﴿٪۴۹﴾', 'اور اعمال کی کتاب کھول کر رکھی جائے گی تو تم گناہگاروں کو دیکھو گے کہ جو کچھ اس میں لکھا ہو گا اس سے ڈر رہے ہوں گے۔ اور کہیں گے۔ ہائے شامت یہ کیسی کتاب ہے کہ نہ چھوٹی بات کو چھوڑتی ہے نہ بڑی کو کوئی بات بھی نہیں مگر اسے لکھ رکھا ہے۔ اور جو جو عمل کئے ہوں گے سب کو حاضر پائیں گے۔ اور تمہارا پروردگار کسی پر ظلم نہیں کرے گا۔', 'اور رکھا جائے گا حساب کا کاغذ پھر تو دیکھے گنہگاروں کو ڈرتے ہیں اس سے جو اس میں لکھا ہے [۶۳] اور کہتے ہیں ہائے خرابی کیا ہے یہ کاغذ نہیں چھوٹی اس سے چھوٹی بات اور نہ بڑی بات جو اس میں نہیں آ گئ اور پائیں گے جو کچھ کیا ہے سامنے [۶۴] اور تیرا رب ظلم نہ کرے گا کسی پر [۶۵]', 'And the Book (ones Record) will be placed (in the right hand for a believer in the Oneness of Allah, and in the left hand for a disbeliever in the Oneness of Allah), and you will see the Mujrimoon (criminals, polytheists, sinners, etc.), fearful of that which is (recorded) therein. They will say: \"Woe to us! What sort of Book is this that leaves neither a small thing nor a big thing, but has recorded it with numbers!\" And they will find all that they did, placed before them, and your Lord treats no one with injustice.', 'And the book (of deeds) will be placed (before them), then you will see the guilty people scared of its contents and saying, “Woe to us! What a book is this! It has missed nothing, minor or major, but has taken it into account.” Thus they will find whatever they did present before them, and your Lord will not wrong anyone.'),
(2190, 18, 50, 7, 19, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ اِذۡ  قُلۡنَا لِلۡمَلٰٓئِکَۃِ اسۡجُدُوۡا  لِاٰدَمَ فَسَجَدُوۡۤا  اِلَّاۤ  اِبۡلِیۡسَ ؕ کَانَ مِنَ  الۡجِنِّ فَفَسَقَ عَنۡ اَمۡرِ رَبِّہٖ ؕ اَفَتَتَّخِذُوۡنَہٗ وَ ذُرِّیَّتَہٗۤ  اَوۡلِیَآءَ مِنۡ دُوۡنِیۡ  وَ ہُمۡ  لَکُمۡ عَدُوٌّ ؕ بِئۡسَ  لِلظّٰلِمِیۡنَ  بَدَلًا ﴿۵۰﴾', 'اور جب ہم نے فرشتوں کو حکم دیا کہ آدم کو سجدہ کرو تو سب نے سجدہ کیا مگر ابلیس نے نہ کیا وہ جنات میں سے تھا تو اپنے پروردگار کے حکم سے باہر ہو گیا۔ کیا تم اسکو اور اسکی اولاد کو میرے سوا دوست بناتے ہو حالانکہ وہ تمہارے دشمن ہیں۔ اور شیطان کی دوستی ظالموں کے لئے اللہ کی دوستی کا برا بدل ہے۔', 'اور جب کہا ہم نے فرشتوں کو سجدہ کرو آدم کو تو سجدہ میں گر پڑے مگر ابلیس تھا جن کی قسم سے سو نکل بھاگا اپنے رب کے حکم سے سو کیا اب تم ٹھہراتے ہو اس کو اور اس کی اولاد کو رفیق میرے سوائے اور وہ تمہارے دشمن ہیں برا ہاتھ لگا بے انصافوں کے بدلہ [۶۶]', 'And (remember) when We said to the angels; \"Prostrate to Adam.\" So they prostrated except Iblees (Satan). He was one of the jinns; he disobeyed the Command of his Lord. Will you then take him (Iblees) and his offspring as protectors and helpers rather than Me while they are enemies to you? What an evil is the exchange for the Zalimoon (polytheists, and wrong-doers, etc).', '(Recall) when We said to the angels, “Prostrate yourselves before ’Ādam.” So, they prostrated themselves, all of them but Iblīs (Satan). He was of the Jinn, so he rebelled against the command of your Lord. Do you still take him and his progeny as friends instead of Me, while they are enemy to you? Evil is he as substitute (of obedience to Allah) for wrongdoers.'),
(2191, 18, 51, 7, 19, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'مَاۤ  اَشۡہَدۡتُّہُمۡ خَلۡقَ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ لَا خَلۡقَ اَنۡفُسِہِمۡ ۪ وَ مَا کُنۡتُ مُتَّخِذَ  الۡمُضِلِّیۡنَ  عَضُدًا ﴿۵۱﴾', 'میں نے انکو نہ تو آسمانوں اور زمین کے پیدا کرنے کے وقت بلایا تھا اور نہ خود انکے پیدا کرنے کے وقت۔ اور میں ایسا نہ تھا کہ گمراہ کرنے والوں کو مددگار بناتا۔', 'دکھلا نہیں لیا تھا میں نے انکو بنانا آسمان اور زمین کا اور نہ بنانا خود ان کا اور میں وہ نہیں کہ بناؤں بہکانے والوں کو اپنا مددگار [۶۷]', 'I (Allah) made them (Iblees and his offspring) not to witness (nor took their help in) the creation of the heavens and the earth and not (even) their own creation, nor was I (Allah) to take the misleaders as helpers.', 'I did not make them witnesses of the creation of the heavens and the earth, nor of their own creation. I was not such that I should take the misleaders as helpers.'),
(2192, 18, 52, 7, 19, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ یَوۡمَ یَقُوۡلُ نَادُوۡا شُرَکَآءِیَ  الَّذِیۡنَ زَعَمۡتُمۡ فَدَعَوۡہُمۡ فَلَمۡ یَسۡتَجِیۡبُوۡا لَہُمۡ وَ جَعَلۡنَا بَیۡنَہُمۡ  مَّوۡبِقًا ﴿۵۲﴾', 'اور جس دن اللہ فرمائے گا کہ اب میرے شریکوں کو جنکی نسبت تم معبود ہونے کا گمان رکھتے تھے بلاؤ تو وہ انکو بلائیں گے مگر وہ انکو کچھ جواب نہ دیں گے۔ اور ہم انکے درمیان ہلاکت کی ایک جگہ بنا دیں گے۔', 'اور جس دن فرمائے گا پکارو میرے شریکوں کو [۶۸] جن کو تم مانتے تھے پھر پکاریں گے سو وہ جواب نہ دیں گے ان کو اور کر دیں گے ہم انکے بیچ مرنے کی جگہ [۶۹]', 'And (remember) the Day He will say:\"Call those (so-called) partners of Mine whom you pretended.\" Then they will cry unto them, but they will not answer them, and We shall put Maubiqa (a barrier, or enmity, or destruction, or a valley in Hell) between them.', '(Recall) the Day when He will say, “Call My ‘partners’ whom you claimed as such.” So, they will call them, but they will not respond to them, and We will put a destructive barrier between them.'),
(2193, 18, 53, 7, 19, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ رَاَ الۡمُجۡرِمُوۡنَ النَّارَ فَظَنُّوۡۤا اَنَّہُمۡ مُّوَاقِعُوۡہَا وَ لَمۡ  یَجِدُوۡا عَنۡہَا مَصۡرِفًا ﴿٪۵۳﴾', 'اور گناہگار لوگ دوزخ کو دیکھیں گے تو یقین کر لیں گے کہ وہ اس میں پڑنے والے ہیں۔ اور اس سے بچنے کا کوئی رستہ نہ پائیں گے۔', 'اور دیکھیں گےگنہگار آگ کو پھر سمجھ لیں گےکہ ان کو پڑنا ہے اس میں اور نہ بدل سکیں گے اس سے رستہ [۷۰]', 'And the Mujrimoon (criminals, polytheists, sinners), shall see the Fire and apprehend that they have to fall therein. And they will find no way of escape from there.', 'And the sinners will see the Fire; so they will know that they will have to fall into it, and they will find no way to bypass it.'),
(2194, 18, 54, 8, 20, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ لَقَدۡ صَرَّفۡنَا فِیۡ ہٰذَا الۡقُرۡاٰنِ لِلنَّاسِ مِنۡ کُلِّ مَثَلٍ ؕ وَ کَانَ الۡاِنۡسَانُ اَکۡثَرَ  شَیۡءٍ  جَدَلًا ﴿۵۴﴾', 'اور ہم نے اس قرآن میں لوگوں کے سمجھانے کے لئے طرح طرح کی مثالیں بیان فرمائی ہیں۔ لیکن انسان سب چیزوں سے بڑھ کر جھگڑالو ہے۔', 'اور بیشک پھیر پھیر کو سمجھائی ہم نے اس قرآن میں لوگوں کو ہر ایک مثل اور ہے انسان سب چیز سے زیادہ جھگڑالو [۷۱]', 'And indeed We have put forth every kind of example in this Quran, for mankind. But, man is ever more quarrelsome than anything.', 'Indeed We have explained in this Qur’ān every subject in various ways for the benefit of the people, but out of all creation, man is most disputing.'),
(2195, 18, 55, 8, 20, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ مَا مَنَعَ النَّاسَ اَنۡ یُّؤۡمِنُوۡۤا اِذۡ جَآءَہُمُ الۡہُدٰی وَ یَسۡتَغۡفِرُوۡا رَبَّہُمۡ  اِلَّاۤ  اَنۡ تَاۡتِیَہُمۡ سُنَّۃُ  الۡاَوَّلِیۡنَ اَوۡ یَاۡتِیَہُمُ الۡعَذَابُ  قُبُلًا ﴿۵۵﴾', 'اور لوگوں کے پاس جب ہدایت آ گئ تو انکو کس چیز نے منع کیا کہ ایمان لائیں اور اپنے پروردگار سے بخشش مانگیں۔ بجز اسکے کہ اس بات کے منتظر ہوں کہ انہیں بھی پہلوں کا سا معاملہ پیش آئے۔ یا ان پر عذاب سامنے سے آ جائے۔', 'اور لوگوں کو جو روکا اس بات سے کہ یقین لے آئیں جب پہنچی انکو ہدایت اور گناہ بخشوائیں اپنے رب سے سو اسی انتظار نے کہ پہنچے ان پر رسم پہلوں کی یا آ کھڑا ہو ان پر عذاب سامنے کا [۷۲]', 'And nothing prevents men from believing, now when the guidance (the Quran) has come to them, and from asking Forgiveness of their Lord, except that the ways of the ancients be repeated with them (i.e. their destruction decreed by Allah), or the torment be brought to them face to face?', 'The only thing that prevented people from believing, even after the guidance had come to them, and from seeking forgiveness from their Lord, is (their demand) that what used to come to the earlier people should come to them as well, or that the punishment should visit them face to face.'),
(2196, 18, 56, 8, 20, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ مَا نُرۡسِلُ الۡمُرۡسَلِیۡنَ  اِلَّا مُبَشِّرِیۡنَ وَ مُنۡذِرِیۡنَ ۚ وَ یُجَادِلُ الَّذِیۡنَ کَفَرُوۡا بِالۡبَاطِلِ لِیُدۡحِضُوۡا بِہِ  الۡحَقَّ وَ اتَّخَذُوۡۤا اٰیٰتِیۡ  وَ مَاۤ   اُنۡذِرُوۡا ہُزُوًا ﴿۵۶﴾', 'اور ہم جو پیغمبروں کو بھیجا کرتے ہیں تو صرف اس لئے کہ لوگوں کو اللہ کی نعمتوں کی خوشخبریاں سنائیں اور عذاب سے ڈرائیں اور جو کافر ہیں وہ باطل کی مدد سے جھگڑا کرتے ہیں تاکہ اس سے حق کو پھسلا دیں اور انہوں نے ہماری آیتوں کو اور جس چیز سے انکو ڈرایا جاتا ہے اسے ہنسی بنا لیا ہے۔', 'اور ہم جو رسول بھیجتے ہیں سو خوشخبری اور ڈر سنانے کو [۷۳] اور جھگڑا کرتے ہیں کافر جھوٹا جھگڑا کہ ٹلا دیں اس سے سچی بات کو [۷۴] اور ٹھہرا لیا انہوں نے میرے کلام کو اور جو ڈر سنائے گئے ٹھٹھا [۷۵]', 'And We send not the Messengers except as giver of glad tidings and warners. But those who disbelieve, dispute with false argument, in order to refute the truth thereby. And they treat My Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), and that with which they are warned, as jest and mockery!', 'We send the messengers only as bearers of good tidings and warnings, and those who disbelieve raise disputes on the basis of the false (arguments), so that they may nullify the truth with it; and they have taken My signs, and the warnings given to them, as mockery.'),
(2197, 18, 57, 8, 20, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ مَنۡ اَظۡلَمُ مِمَّنۡ ذُکِّرَ بِاٰیٰتِ رَبِّہٖ فَاَعۡرَضَ عَنۡہَا وَ نَسِیَ مَا قَدَّمَتۡ یَدٰہُ ؕ اِنَّا جَعَلۡنَا عَلٰی قُلُوۡبِہِمۡ  اَکِنَّۃً  اَنۡ یَّفۡقَہُوۡہُ  وَ فِیۡۤ  اٰذَانِہِمۡ  وَقۡرًا ؕ وَ  اِنۡ تَدۡعُہُمۡ  اِلَی الۡہُدٰی فَلَنۡ یَّہۡتَدُوۡۤا  اِذًا  اَبَدًا ﴿۵۷﴾', 'اور اس سے بڑھکر ظالم کون جسکو اس کے پروردگار کی آیات کے ذریعے سمجھایا گیا تو اس نے ان سے منہ پھیر لیا۔ اور جو اعمال وہ آگے کر چکا اسکو بھول گیا۔ ہم نے انکے دلوں پر پردے ڈال دیئے کہ اسے سمجھ نہ سکیں۔ اور کانوں میں ثقل پیدا کر دیا ہے کہ سن نہ سکیں اور اگر تم انکو رستے کی طرف بلاؤ تو کبھی رستے پر نہ آئیں گے۔', 'اور اس سے زیادہ ظالم کون جس کو سمجھایا اسکے رب کے کلام سے پھر منہ پھیر لیا اسکی طرف سے اور بھول گیا جو کچھ آگے بھیج چکے ہیں اس کے ہاتھ [۷۶] ہم نے ڈال دیے ہیں انکے دلوں پر پردے کہ اس کو نہ سمجھیں اور انکے کانوں میں ہے بوجھ اور اگر تو ان کو بلائے راہ پر تو ہر گز نہ آئیں راہ پر اس وقت کبھی [۷۷]', 'And who does more wrong than he who is reminded of the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of his Lord, but turns away from them forgetting what (deeds) his hands have sent forth. Truly, We have set veils over their hearts lest they should understand this (the Quran), and in their ears, deafness. And if you (O Muhammad SAW) call them to guidance, even then they will never be guided.', 'Who is more unjust than the one who was reminded through the signs of his Lord, but he turned away from them, and forgot what his own hands sent ahead. Indeed We have put covers on their hearts that bar them from understanding it, and (We have created) deafness in their ears. And if you call them to guidance, even then they will never adopt the right path.'),
(2198, 18, 58, 8, 20, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ رَبُّکَ الۡغَفُوۡرُ ذُو الرَّحۡمَۃِ ؕ لَوۡ یُؤَاخِذُہُمۡ بِمَا کَسَبُوۡا لَعَجَّلَ لَہُمُ الۡعَذَابَ ؕ بَلۡ لَّہُمۡ مَّوۡعِدٌ  لَّنۡ یَّجِدُوۡا مِنۡ  دُوۡنِہٖ  مَوۡئِلًا  ﴿۵۸﴾', 'اور تمہارا پروردگار بخشنے والا صاحب رحمت ہے۔ اگر وہ انکے کرتوتوں پر ان کو پکڑنے لگے تو ان پر جھٹ عذاب بھیج دے مگر ان کے لئے ایک وقت مقرر کر رکھا ہے کہ اس کے عذاب سے کوئی پناہ کی جگہ نہ پائیں گے۔', 'اور تیرا رب بڑا بخشنے والا ہے رحمت والا اگر ان کو پکڑے انکے کئے پر تو جلد ڈالے ان پر عذاب [۷۸] پر ان کے لئے ایک وعدہ ہے کہیں نہ پائیں گے اس سے ورے سرک جانے کو جگہ [۷۹]', 'And your Lord is Most Forgiving, Owner of Mercy. Were He to call them to account for what they have earned, then surely, He would have hastened their punishment. But they have their appointed time, beyond which they will find no escape.', 'Your Lord is the Most Forgiving, the Lord of Mercy. If He seizes them for what they did, He may cause the punishment to befall them sooner, but there is an appointed time for them, from which they can never find a place of refuge.'),
(2199, 18, 59, 8, 20, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ تِلۡکَ الۡقُرٰۤی اَہۡلَکۡنٰہُمۡ  لَمَّا ظَلَمُوۡا  وَ جَعَلۡنَا لِمَہۡلِکِہِمۡ مَّوۡعِدًا ﴿٪۵۹﴾', 'اور یہ بستیاں جو ویران  پڑی ہیں جب انہوں نے کفر کر کے ظلم کیا تو ہم نے انکو تباہ کر دیا۔ اور انکی تباہی کے لئے ایک وقت مقرر کر دیا تھا۔', 'اور یہ سب بستیاں ہیں جن کو ہم نے غارت کیا جب وہ ظالم ہو گئے اور مقرر کیا تھا ہم نے انکی ہلاکت کا ایک وعدہ [۸۰]', 'And these towns (population, Ad, Thamood, etc.) We destroyed when they did wrong. And We appointed a fixed time for their destruction.', 'These are the towns that We destroyed when they (i.e. their people) transgressed, and We had appointed a time for their destruction.'),
(2200, 18, 60, 9, 21, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ اِذۡ قَالَ مُوۡسٰی لِفَتٰىہُ لَاۤ  اَبۡرَحُ حَتّٰۤی اَبۡلُغَ  مَجۡمَعَ الۡبَحۡرَیۡنِ اَوۡ اَمۡضِیَ حُقُبًا ﴿۶۰﴾', 'اور جب موسٰی نے اپنے شاگرد سے کہا کہ جب تک میں دو دریاؤں کے ملنے کی جگہ نہ پہنچ جاؤں ٹلنے کا نہیں خواہ صدیوں چلتا رہوں۔', 'اور جب کہا موسٰی نے اپنے جوان کو میں نہ ہٹوں گا جب تک نہ پہنچ جاؤں جہاں ملتے ہیں دو دریا یا چلا جاؤں قرنوں میں [۸۱]', 'And (remember) when Moosa (Moses) said to his boy-servant: \"I will not give up (travelling) until I reach the junction of the two seas or (until) I spend years and years in travelling.\"', '(Recall) when Mūsā said to his young man, “I shall not give up until I reach the meeting point of the two seas, or else I shall go on traveling for years.”'),
(2201, 18, 61, 9, 21, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'فَلَمَّا بَلَغَا مَجۡمَعَ بَیۡنِہِمَا نَسِیَا حُوۡتَہُمَا فَاتَّخَذَ سَبِیۡلَہٗ  فِی الۡبَحۡرِ  سَرَبًا ﴿۶۱﴾', 'پھر جب وہ دونوں ان دریاؤں کے سنگم پر پہنچے تو اپنی مچھلی بھول گئے پھر اس مچھلی نے دریا میں سرنگ کی طرح اپنا رستہ بنا لیا۔', 'پھر جب پہنچے دونوں دریا کے ملاپ تک بھول گئے اپنی مچھلی پھر اس نے اپنی راہ کر لی دریا میں سرنگ بنا کر [۸۲]', 'But when they reached the junction of the two seas, they forgot their fish, and it took its way through the sea as in a tunnel.', 'So, when they reached the meeting point of the two seas, they forgot their fish, and it made its way into the sea as in a tunnel.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(2202, 18, 62, 9, 21, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'فَلَمَّا جَاوَزَا قَالَ لِفَتٰىہُ اٰتِنَا غَدَآءَنَا ۫ لَقَدۡ لَقِیۡنَا مِنۡ سَفَرِنَا ہٰذَا نَصَبًا ﴿۶۲﴾', 'جب آگے چلے تو موسٰی نے اپنے شاگرد سے کہا کہ ہمارا کھانا لاؤ اس سفر سے ہم کو بہت تکان ہو گئ ہے۔', 'پھر جب آگے چلے کہا موسٰی نے اپنے جوان کو لا ہمارے پاس ہمارا کھانا ہم نے پائی اپنے اس سفر میں تکلیف [۸۳]', 'So when they had passed further on (beyond that fixed place), Moosa (Moses) said to his boy-servant: \"Bring us our morning meal; truly, we have suffered much fatigue in this, our journey.\"', 'When they went further, he said to his young man, “Bring us our morning meal; we have, indeed, had much fatigue from this journey of ours.”'),
(2203, 18, 63, 9, 21, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'قَالَ اَرَءَیۡتَ اِذۡ اَوَیۡنَاۤ  اِلَی الصَّخۡرَۃِ فَاِنِّیۡ نَسِیۡتُ الۡحُوۡتَ ۫ وَ مَاۤ  اَنۡسٰنِیۡہُ  اِلَّا الشَّیۡطٰنُ اَنۡ اَذۡکُرَہٗ ۚ  وَ اتَّخَذَ سَبِیۡلَہٗ  فِی الۡبَحۡرِ ٭ۖ عَجَبًا ﴿۶۳﴾', 'اس نے کہا کہ بھلا آپ نے دیکھا کہ جب ہم نے اس چٹان کے پاس آرام کیا تھا تو میں مچھلی وہیں بھول گیا۔ اور مجھے آپ سے اس کا ذکر کرنا شیطان نے بھلا دیا۔ اور اس مچھلی نے عجیب طرح سے دریا میں اپنا رستہ بنایا۔', 'بولا وہ دیکھا تو نے جب ہم نے جگہ پکڑی اس پتھر کے پاس سو میں بھول گیا مچھلی اور یہ مجھ کو بھلا دیا شیطان ہی نے کہ اس کا ذکر کروں [۸۴] اور اس نے کر لیا اپنا رستہ دریا میں عجیب طرح', 'He said:\"Do you remember when we betook ourselves to the rock? I indeed forgot the fish, none but Shaitan (Satan) made me forget to remember it. It took its course into the sea in a strange (way)!\"', 'He said, “You see, when we stayed at the rock, I forgot the fish. It was none but Satan who made me forget it to tell you about it - and it made its way into the sea in an amazing manner.”'),
(2204, 18, 64, 9, 21, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'قَالَ ذٰلِکَ مَا کُنَّا نَبۡغِ ٭ۖ فَارۡتَدَّا عَلٰۤی اٰثَارِہِمَا قَصَصًا  ﴿ۙ۶۴﴾', 'موسٰی نے کہا یہی تو وہ مقام ہے جسے ہم تلاش کرتے تھے تو وہ اپنے پاؤں کے نشان دیکھتے دیکھتے لوٹ گئے۔', 'کہا یہی ہے جو ہم چاہتے تھے پھر الٹے پھرے اپنے پیر پہچانتے [۸۵]', '(Moosa (Moses)) said: \"That is what we have been seeking.\" So they went back retracing their footsteps.', 'He said, “That was what we were looking for.” So they returned, retracing their footsteps.'),
(2205, 18, 65, 9, 21, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'فَوَجَدَا عَبۡدًا مِّنۡ عِبَادِنَاۤ اٰتَیۡنٰہُ رَحۡمَۃً  مِّنۡ عِنۡدِنَا وَ عَلَّمۡنٰہُ مِنۡ لَّدُنَّا عِلۡمًا ﴿۶۵﴾', 'وہاں انہوں نے ہمارے بندوں میں سے ایک بندہ دیکھا جس کو ہم نے اپنے ہاں سے رحمت خاص سے نوازا تھا اور اپنے پاس سے ایک خاص علم بخشا تھا۔', 'پھر پایا ایک بندہ ہمارے بندوں میں کا جس کو دی تھی ہم نے رحمت اپنے پاس سے اور سکھلایا تھا اپنے پاس سے ایک علم [۸۶]', 'Then they found one of Our slaves, unto whom We had bestowed mercy from Us, and whom We had taught knowledge from Us.', 'Then they found one of Our servants whom We blessed with mercy from Us and whom We gave knowledge, a knowledge from Our own.'),
(2206, 18, 66, 9, 21, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'قَالَ لَہٗ مُوۡسٰی ہَلۡ اَتَّبِعُکَ عَلٰۤی اَنۡ تُعَلِّمَنِ  مِمَّا عُلِّمۡتَ رُشۡدًا ﴿۶۶﴾', 'موسٰی نے ان سے جن کا نام خضر تھا کہا کہ جو علم اللہ کی طرف سے آپکو سکھایا گیا ہے اگر آپ اس میں سے مجھے کچھ بھلائی کی باتیں سکھائیں تو میں آپ کے ساتھ رہوں۔', 'کہا اس کو موسٰی نے کہے تو تیرے ساتھ رہوں اس بات پر کہ مجھ کو سکھلا دے کچھ جو تجھ کو سکھلائی ہے بھلی راہ [۸۷]', 'Moosa (Moses) said to him (Khidr) \"May I follow you so that you teach me something of that knowledge (guidance and true path) which you have been taught (by Allah)?\"', 'Mūsā said to him, “May I have your company so that you teach me some of the rightful knowledge you have been given.”'),
(2207, 18, 67, 9, 21, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'قَالَ اِنَّکَ لَنۡ تَسۡتَطِیۡعَ مَعِیَ صَبۡرًا ﴿۶۷﴾', 'خضر نے کہا کہ تم میرے ساتھ رہ کر صبر نہیں کر سکو گے۔', 'بولا تو نہ ٹھہر سکے گا میرے ساتھ', 'He (Khidr) said: \"Verily! You will not be able to have patience with me!', 'He said, “You can never bear with me patiently.'),
(2208, 18, 68, 9, 21, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'وَ کَیۡفَ تَصۡبِرُ  عَلٰی مَا لَمۡ تُحِطۡ بِہٖ خُبۡرًا ﴿۶۸﴾', 'اور جس بات کی تمہیں خبر ہی نہیں اس پر صبر کر بھی کیسے سکتے ہو۔', 'اور کیونکر ٹھہرے گا دیکھ کر ایسی چیز کو کہ تیرے قابو میں نہیں اس کا سمجھنا [۸۸]', '\"And how can you have patience about a thing which you know not?\"', 'And how would you keep patient over something your comprehension cannot grasp?”'),
(2209, 18, 69, 9, 21, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'قَالَ سَتَجِدُنِیۡۤ  اِنۡ شَآءَ اللّٰہُ صَابِرًا وَّ لَاۤ اَعۡصِیۡ  لَکَ  اَمۡرًا ﴿۶۹﴾', 'موسٰی نے کہا اللہ نے چاہا تو آپ مجھے صابر پائیے گا۔ اور میں آپکے ارشاد کے خلاف نہیں کروں گا۔', 'کہا تو پائے گا اگر اللہ نے چاہا مجھ کو ٹھہرنے والا اور نہ ٹالوں گا تیرا کوئی حکم [۸۹]', 'Moosa (Moses) said: \"If Allah will, you will find me patient, and I will not disobey you in aught.\"', 'He (Mūsā) said, “You will find me patient, if Allah wills, and I shall not disobey any order from you.”'),
(2210, 18, 70, 9, 21, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'قَالَ فَاِنِ اتَّبَعۡتَنِیۡ فَلَا تَسۡـَٔلۡنِیۡ عَنۡ شَیۡءٍ  حَتّٰۤی  اُحۡدِثَ  لَکَ  مِنۡہُ  ذِکۡرًا ﴿٪۷۰﴾', 'خضر نے کہا اگر تم میرے ساتھ رہنا چاہو تو شرط یہ ہے مجھ سے کوئی بات نہ پوچھنا جب تک میں خود اس کا ذکر تم سے نہ کروں۔', 'بولا پھر اگر میرے ساتھ رہنا ہےتو مت پوچھیو مجھ سے کوئی چیز جب تک میں شروع نہ کروں تیرے آگے اس کا ذکر [۹۰]', 'He (Khidr) said: \"Then, if you follow me, ask me not about anything till I myself mention it to you.\"', 'He said, “Well, if you follow me, do not ask me about anything unless I myself start telling you about it.”'),
(2211, 18, 71, 10, 0, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'فَانۡطَلَقَا ٝ حَتّٰۤی اِذَا رَکِبَا فِی السَّفِیۡنَۃِ خَرَقَہَا ؕ قَالَ اَخَرَقۡتَہَا لِتُغۡرِقَ اَہۡلَہَا ۚ لَقَدۡ جِئۡتَ شَیۡئًا اِمۡرًا ﴿۷۱﴾', 'تو دونوں چل پڑے یہاں تک کہ جب کشتی میں سوار ہوئے تو خضر نے کشتی کو پھاڑ ڈالا۔ موسٰی نے کہا کیا آپ نے اسکو اس لئے پھاڑا ہے کہ سواروں کو غرق کر دیں۔ یہ تو آپ نے بڑی عجیب بات کی۔', 'پھر دونوں چلے یہاں تک کہ جب چڑھے کشتی میں اس کو پھاڑ ڈالا موسٰی بولا کیا تو نے اس کو پھاڑ ڈالا کہ ڈبا دے اسکے لوگوں کو البتہ تو نے کی ایک چیز بھاری [۹۱]', 'So they both proceeded, till, when they embarked the ship, he (Khidr) scuttled it. Moosa (Moses) said: \"Have you scuttled it in order to drown its people? Verily, you have committed a thing \"Imra\" (a Munkar - evil, bad, dreadful thing).\"', 'So, they both moved ahead, until when they boarded a boat, he sliced it (by removing one of its planks). He (Mūsā) said, “Did you slice it to drown its people? In fact, you have done a terrible act.”'),
(2212, 18, 72, 10, 0, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'قَالَ اَلَمۡ اَقُلۡ اِنَّکَ لَنۡ تَسۡتَطِیۡعَ مَعِیَ صَبۡرًا ﴿۷۲﴾', 'خضر نے کہا۔ کیا میں نے نہیں کہا تھا کہ تم میرے ساتھ صبر نہ کر سکو گے۔', 'بولا میں نے نہ کہا تھا تو نہ ٹھہر سکے  گا میرے ساتھ', 'He (Khidr) said: \"Did I not tell you, that you would not be able to have patience with me?\"', 'He said, “Did I not say that you can never bear with me patiently?”'),
(2213, 18, 73, 10, 0, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'قَالَ لَا تُؤَاخِذۡنِیۡ بِمَا نَسِیۡتُ وَ لَا تُرۡہِقۡنِیۡ مِنۡ  اَمۡرِیۡ  عُسۡرًا ﴿۷۳﴾', 'موسٰی نے کہا کہ جو بھول مجھ سے ہوئی اس پر مواخذہ نہ کیجئے۔ اور میرے معاملے میں مجھ پر مشکل نہ ڈالئے۔', 'کہا مجھ کو نہ پکڑ میری بھول پر اور مت ڈال مجھ پر میرا کام مشکل [۹۲]', '(Moosa (Moses)) said: \"Call me not to account for what I forgot, and be not hard upon me for my affair (with you).\"', 'He (Mūsā) said, “Do not hold me punishable for what I forgot, and do not make my course too difficult for me.”'),
(2214, 18, 74, 10, 0, 15, 'سُبۡحٰنَ الَّذِیۡۤ', 'الکہف', 'فَانۡطَلَقَا ٝ حَتّٰۤی   اِذَا  لَقِیَا غُلٰمًا فَقَتَلَہٗ ۙ قَالَ  اَقَتَلۡتَ نَفۡسًا  زَکِیَّۃًۢ بِغَیۡرِ  نَفۡسٍ ؕ لَقَدۡ جِئۡتَ شَیۡئًا نُّکۡرًا ﴿۷۴﴾', 'پھر دونوں چلے۔ یہاں تک کہ رستے میں ایک لڑکا ملا تو خضر نے اسے مار ڈالا۔ موسٰی نے کہا کہ آپ نے ایک بےگناہ شخص کو ناحق بغیر قصاص کے مار ڈالا۔ یہ تو آپ نے بری بات کی۔', 'پھر دونوں چلے یہاں تک کہ جب ملے ایک لڑکے سے تو اسکو مار ڈالا [۹۳] موسٰی بولا کیا تو نے مار ڈالی ایک جان ستھری [۹۴] بغیر عوض کسی جان کے بیشک تو نے کی ایک چیز نا معقول [۹۵]', 'Then they both proceeded, till they met a boy, he (Khidr) killed him. Moosa (Moses) said: \"Have you killed an innocent person who had killed none? Verily, you have committed a thing \"Nukra\" (a great Munkar - prohibited, evil, dreadful thing)!\"', 'So, they moved ahead until when they met a boy, he killed him (the boy). He (Mūsā) said, “Did you kill an innocent soul while he did not kill anyone? You have committed a heinous act indeed.”'),
(2215, 18, 75, 10, 1, 16, 'قَالَ اَلَمۡ', 'الکہف', 'قَالَ اَلَمۡ  اَقُلۡ لَّکَ اِنَّکَ لَنۡ تَسۡتَطِیۡعَ مَعِیَ صَبۡرًا ﴿۷۵﴾', 'خضر نے کہا کیا میں نے نہیں کہا تھا کہ تم سے میرے ساتھ صبر نہیں ہو سکے گا۔', 'بولا میں نے تجھ کو نہ کہا تھا کہ تو نہ ٹھہر سکے گا میرے ساتھ [۹۶]', '(Khidr) said: \"Did I not tell you that you can have no patience with me?\"', 'He said, “Did I not tell you that you can never bear with me patiently?”'),
(2216, 18, 76, 10, 1, 16, 'قَالَ اَلَمۡ', 'الکہف', 'قَالَ اِنۡ سَاَلۡتُکَ عَنۡ شَیۡءٍۭ بَعۡدَہَا فَلَا تُصٰحِبۡنِیۡ ۚ قَدۡ بَلَغۡتَ مِنۡ لَّدُنِّیۡ عُذۡرًا ﴿۷۶﴾', 'انہوں نے کہا کہ اگر میں اسکے بعد پھر کوئی بات پوچھوں یعنی اعتراض کروں تو مجھے اپنے ساتھ نہ رکھیئے گا کہ آپ میری طرف سے عذر کے قبول کرنے میں حد کو پہنچ گئے ہیں۔', 'کہا اگر تجھ سے پوچھوں کوئی چیز اس کے بعد تو مجھ کو ساتھ نہ رکھیو تو اتار چکا میری طرف سے الزام [۹۷]', '(Moosa (Moses)) said: \"If I ask you anything after this, keep me not in your company, you have received an excuse from me.\"', 'He (Mūsā) said, “If I ask you about something after this, do not allow me your company. You have now reached a point where you have a valid excuse (to part with me) from my own side. “'),
(2217, 18, 77, 10, 1, 16, 'قَالَ اَلَمۡ', 'الکہف', 'فَانۡطَلَقَا ٝ حَتّٰۤی اِذَاۤ  اَتَیَاۤ اَہۡلَ قَرۡیَۃِۣ اسۡتَطۡعَمَاۤ اَہۡلَہَا فَاَبَوۡا اَنۡ یُّضَیِّفُوۡہُمَا فَوَجَدَا فِیۡہَا جِدَارًا یُّرِیۡدُ اَنۡ یَّنۡقَضَّ فَاَقَامَہٗ ؕ قَالَ لَوۡ شِئۡتَ  لَتَّخَذۡتَ  عَلَیۡہِ  اَجۡرًا ﴿۷۷﴾', 'پھر دونوں چلے۔ یہاں تک کہ ایک گاؤں والوں کے پاس پہنچے اور ان سے کھانا طلب کیا۔ انہوں نے انکی ضیافت کرنے سے انکار کیا۔ پھر انہوں نے وہاں ایک دیوار دیکھی جو گرا چاہتی تھی تو خضر نے اسکو سیدھا کر دیا۔ موسٰی نے کہا کہ اگر آپ چاہتے تو ان سے اس کا معاوضہ لے لیتے تاکہ کھانے کا کام چلتا۔', 'پھر دونوں چلے یہاں تک کہ جب پہنچے ایک گاؤں کے لوگوں تک کھانا چاہا وہاں کے لوگوں سے انہوں نے نہ مانا انکو مہمان رکھیں پھر پائی وہاں ایک دیوار جو گرا چاہتی تھی اسکو سیدھا کر دیا [۹۸] بولا موسٰی اگر تو چاہتا تو لے لیتا اس پر مزدوری [۹۹]', 'Then they both proceeded, till, when they came to the people of a town, they asked them for food, but they refused to entertain them. Then they found therein a wall about to collapse and he (Khidr) set it up straight. (Moosa (Moses)) said: If you had wished, surely, you could have taken wages for it!\"', 'Then, they moved ahead until they came to the people of a town; they asked its people for food, and they refused to host them. Then, they found there a wall tending to fall down. So he (KhaDir) set it right. He (Mūsā) said, “If you wished, you could have charged a fee for this.”'),
(2218, 18, 78, 10, 1, 16, 'قَالَ اَلَمۡ', 'الکہف', 'قَالَ ہٰذَا فِرَاقُ بَیۡنِیۡ وَ بَیۡنِکَ ۚ سَاُنَبِّئُکَ بِتَاۡوِیۡلِ مَا لَمۡ تَسۡتَطِعۡ عَّلَیۡہِ صَبۡرًا ﴿۷۸﴾', 'خضر نے کہا کہ اب مجھ میں اور تم میں علیحدگی۔ مگر جن باتوں پر تم صبر نہ کر سکے میں انکا تمہیں بھید بتائے دیتا ہوں۔', 'کہا اب جدائی ہے میرے اور تیرے بیچ اب جتلائے دیتا ہوں تجھ کو پھیر ان باتوں کا جس پر تو صبر نہ کر سکا [۱۰۰]', '(Khidr) said: \"This is the parting between me and you, I will tell you the interpretation of (those) things over which you were unable to hold patience.', 'He said, “Here is the point of parting ways between me and you. I shall now explain to you the reality of things about which you could not remain patient.'),
(2219, 18, 79, 10, 1, 16, 'قَالَ اَلَمۡ', 'الکہف', 'اَمَّا السَّفِیۡنَۃُ  فَکَانَتۡ لِمَسٰکِیۡنَ یَعۡمَلُوۡنَ فِی الۡبَحۡرِ فَاَرَدۡتُّ اَنۡ اَعِیۡبَہَا وَ کَانَ  وَرَآءَہُمۡ مَّلِکٌ یَّاۡخُذُ کُلَّ  سَفِیۡنَۃٍ  غَصۡبًا ﴿۷۹﴾', 'کہ جو وہ کشتی تھی غریب لوگوں کی تھی جو دریا میں محنت کر کے یعنی کشتیاں چلا کر گذارہ کرتے تھے۔ اور انکے سامنے کی طرف ایک بادشاہ تھا جو ہر اچھی کشتی کو زبردستی چھین لیتا تھا تو میں نے چاہا کہ اسے عیب دار کر دوں تاکہ وہ اسے غصب نہ کر سکے۔', 'وہ جو کشتی تھی سو چند محتاجوں کی جو محنت کرتے تھے دریا میں [۱۰۱] سو میں نے چاہا کہ اس میں عیب ڈال دوں اور ان کے پرے تھا ایک بادشاہ جو لے لیتا تھا ہر کشتی کو چھین کر [۱۰۲]', '\"As for the ship, it belonged to Masakeen (poor people) working in the sea. So I wished to make a defective damage in it, as there was a king after them who seized every ship by force.', 'As for the boat, it belonged to some poor people who worked at sea. So I wanted to make it defective, as there was a king across them who used to usurp every boat by force.'),
(2220, 18, 80, 10, 1, 16, 'قَالَ اَلَمۡ', 'الکہف', 'وَ اَمَّا الۡغُلٰمُ فَکَانَ اَبَوٰہُ  مُؤۡمِنَیۡنِ  فَخَشِیۡنَاۤ  اَنۡ یُّرۡہِقَہُمَا طُغۡیَانًا وَّ کُفۡرًا ﴿ۚ۸۰﴾', 'اور وہ جو لڑکا تھا اسکے ماں باپ دونوں مومن تھے ہمیں اندیشہ ہوا کہ وہ بڑا ہو کر بدکردار ہوگا تو کہیں انکو سرکشی اور کفر میں نہ پھنسا دے۔', 'اور وہ جو لڑکا تھا سو اس کے ماں باپ تھے ایمان والے پھر ہم کو اندیشہ ہوا کہ ان کو عاجز کر دے زبردستی اور کفر کر کر [۱۰۳]', '\"And as for the boy, his parents were believers, and we feared lest he should oppress them by rebellion and disbelief.', 'As for the boy, his parents were believers. We apprehended that he would impose rebellion and infidelity upon them.'),
(2221, 18, 81, 10, 1, 16, 'قَالَ اَلَمۡ', 'الکہف', 'فَاَرَدۡنَاۤ  اَنۡ یُّبۡدِلَہُمَا رَبُّہُمَا خَیۡرًا مِّنۡہُ  زَکٰوۃً  وَّ  اَقۡرَبَ  رُحۡمًا ﴿۸۱﴾', 'تو ہم نے چاہا کہ ان کا پروردگار اسکی جگہ انکو اور بچہ عطا فرمائے جو اخلاقی پاکیزگی میں بہتر اور محبت میں زیادہ قریب ہو۔', 'پھر ہم نے چاہا کہ بدلہ دے ان کو ان کا رب بہتر اس سے پاکیزگی میں اور نزدیک تر شفقت میں [۱۰۴]', '\"So we intended that their Lord should change him for them for one better in righteousness and near to mercy.', 'We, therefore, wished that their Lord would replace him with someone better than him in piety, and more akin to affection.'),
(2222, 18, 82, 10, 1, 16, 'قَالَ اَلَمۡ', 'الکہف', 'وَ اَمَّا الۡجِدَارُ فَکَانَ لِغُلٰمَیۡنِ یَتِیۡمَیۡنِ فِی الۡمَدِیۡنَۃِ  وَ کَانَ تَحۡتَہٗ کَنۡزٌ لَّہُمَا وَ کَانَ اَبُوۡہُمَا صَالِحًا ۚ فَاَرَادَ  رَبُّکَ اَنۡ یَّبۡلُغَاۤ  اَشُدَّہُمَا وَ یَسۡتَخۡرِجَا کَنۡزَہُمَا ٭ۖ رَحۡمَۃً مِّنۡ رَّبِّکَ ۚ وَ مَا فَعَلۡتُہٗ عَنۡ اَمۡرِیۡ ؕ ذٰلِکَ تَاۡوِیۡلُ  مَا  لَمۡ تَسۡطِعۡ  عَّلَیۡہِ صَبۡرًا ﴿ؕ٪۸۲﴾', 'اور وہ جو دیوار تھی سو دو یتیم لڑکوں کی تھی جو شہر میں رہتے تھے اور اسکے نیچے انکا خزانہ دفن تھا اور انکا باپ ایک نیک آدمی تھا۔ تو تمہارے پروردگار نے چاہا کہ وہ اپنی جوانی کو پہنچ جائیں اور پھر اپنا خزانہ نکالیں۔ یہ تمہارے پروردگار کی مہربانی ہے۔ اور یہ کام میں نے اپنی طرف سے نہیں کئے۔ یہ ان باتوں کی حقیقت ہے جن پر تم صبر نہ کر سکے۔', 'اور وہ جو دیوار تھی سو دو یتیم لڑکوں کی تھی اس شہر میں اور اسکے نیچے مال گڑا تھا ان کا اور ان کا باپ تھا نیک پھر چاہا تیرے رب نے کہ وہ پہنچ جائیں اپنی جوانی کو اور نکالیں اپنامال گڑا ہوا [۱۰۵] مہربانی سے تیرے رب کی اور میں نے یہ نہیں کیا اپنے حکم سے [۱۰۶] یہ ہے پھیر ان چیزوں کا جن پر تو صبر نہ کر سکا', '\"And as for the wall, it belonged to two orphan boys in the town; and there was under it a treasure belonging to them; and their father was a righteous man, and your Lord intended that they should attain their age of full strength and take out their treasure as a mercy from your Lord. And I did it not of my own accord. That is the interpretation of those (things) over which you could not hold patience.\"', 'As for the wall, it belonged to two orphan boys in the city, and there was a treasure beneath it belonging to them, and their father was a pious man. So your Lord willed that they should reach their maturity and dig out their treasure, as a mercy from your Lord. I did not do it on my own accord. This is the reality of things about which you could not remain patient.”'),
(2223, 18, 83, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'وَ یَسۡـَٔلُوۡنَکَ عَنۡ ذِی الۡقَرۡنَیۡنِ ؕ قُلۡ سَاَتۡلُوۡا  عَلَیۡکُمۡ  مِّنۡہُ  ذِکۡرًا ﴿ؕ۸۳﴾', 'اور تم سے ذوالقرنین کے بارے میں دریافت کرتے ہیں۔ کہدو کہ میں اسکا کسی قدر حال تمہیں پڑھ کر سناتا ہوں۔', 'اور تجھ سے پوچھتے ہیں ذوالقرنین کو کہہ اب پڑھتا ہوں تمہارے آگے اس کا کچھ احوال', 'And they ask you about Dhul-Qarnain. Say: \"I shall recite to you something of his story.\"', 'They ask you about Dhul-Qarnain. Say, “I shall now recite to you an account of him.”'),
(2224, 18, 84, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'اِنَّا مَکَّنَّا لَہٗ فِی الۡاَرۡضِ وَ اٰتَیۡنٰہُ مِنۡ کُلِّ شَیۡءٍ سَبَبًا ﴿ۙ۸۴﴾', 'ہم نے اسکو زمین میں بڑا اقتدار دیا تھا اور ہر طرح کا سامان اسکو عطا کیا تھا۔', 'ہم نے اس کو جمایا تھا ملک میں اور دیا تھا ہم نے اسکو ہر چیز کا سامان [۱۰۷]', 'Verily, We established him in the earth, and We gave him the means of everything.', 'Surely, We gave him power on earth and gave him means to (have) everything (he needs).'),
(2225, 18, 85, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'فَاَتۡبَعَ  سَبَبًا ﴿۸۵﴾', 'تو اس نے سفر کا ایک سامان کیا۔', 'پھر پیچھے پڑا ایک سامان کے [۱۰۸]', 'So he followed a way.', 'So he followed a course,'),
(2226, 18, 86, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'حَتّٰۤی  اِذَا بَلَغَ  مَغۡرِبَ الشَّمۡسِ وَجَدَہَا تَغۡرُبُ فِیۡ عَیۡنٍ حَمِئَۃٍ  وَّ وَجَدَ عِنۡدَہَا قَوۡمًا ۬ؕ قُلۡنَا یٰذَا الۡقَرۡنَیۡنِ  اِمَّاۤ  اَنۡ تُعَذِّبَ وَ اِمَّاۤ  اَنۡ تَتَّخِذَ فِیۡہِمۡ حُسۡنًا ﴿۸۶﴾', 'یہاں تک کہ جب سورج کے غروب ہونے کی جگہ پہنچا تو اسے ایسا پایا کہ ایک کیچڑ والے چشمے میں ڈوب رہا ہے اور اس چشمے کے پاس ایک قوم دیکھی۔ ہم نے کہا ذوالقرنین! تم انکو خواہ تکلیف دو خواہ انکے بارے میں بھلائی اختیار کرو دونوں باتوں کی تمکو قدرت ہے۔', 'یہاں تک کہ جب پہنچا سورج ڈونبے کی جگہ پایا کہ وہ ڈوبتا ہے ایک دلدل کی ندی میں [۱۰۹] اور پایا اس کے پاس لوگوں کو ہم نے کہا اے ذوالقرنین یا تو تو لوگوں کو تکلیف دے اور یا رکھ ان میں خوبی [۱۱۰]', 'Until, when he reached the setting place of the sun, he found it setting in a spring of black muddy (or hot) water. And he found near it a people. We (Allah) said (by inspiration): \"O Dhul-Qarnain! Either you punish them, or treat them with kindness.\"', 'until when he reached the point of sunset, he found it setting into a miry spring, and found a people near it. We said, “O Dhul-Qarnain, either punish them or adopt good behavior with them.”'),
(2227, 18, 87, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'قَالَ اَمَّا مَنۡ ظَلَمَ فَسَوۡفَ نُعَذِّبُہٗ ثُمَّ یُرَدُّ  اِلٰی رَبِّہٖ فَیُعَذِّبُہٗ عَذَابًا نُّکۡرًا ﴿۸۷﴾', 'ذوالقرنین نے کہا کہ جو کفر و بدکرداری سے ظلم کرے گا اسے ہم سزا دیں گے پھر وہ اپنے پروردگار کی طرف لوٹایا جائے گا۔ تو وہ بھی اسے بڑا عذاب دے گا۔', 'بولا جو کوئی ہو گا بے انصاف سو ہم اسکو سزا دیں گے پھرلوٹ جائے گا اپنے رب کے پاس وہ عذاب دے گا اس کو برا عذاب', 'He said: \"As for him (a disbeliever in the Oneness of Allah) who does wrong, we shall punish him; and then he will be brought back unto his Lord; Who will punish him with a terrible torment (Hell).', 'He said, “As for him who does wrong, we shall punish him, then he will be sent back to his Lord, and He will punish him with a severe punishment.'),
(2228, 18, 88, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'وَ اَمَّا مَنۡ اٰمَنَ وَ عَمِلَ صَالِحًا فَلَہٗ جَزَآءَۨ  الۡحُسۡنٰی ۚ وَ سَنَقُوۡلُ لَہٗ مِنۡ اَمۡرِنَا  یُسۡرًا ﴿ؕ۸۸﴾', 'اور جو ایمان لائے گا اور عمل نیک کرے گا اسکے لئے بہت اچھا بدلہ ہے۔ اور ہم اپنے معاملے میں اس سے نرم بات کہیں گے۔', 'اور جو کوئی یقین لایا اور کیا اس نے بھلا کام سو اس کا بدلہ بھلائی ہے اور ہم حکم دیں گے اس کو اپنے کام میں آسانی [۱۱۱]', '\"But as for him who believes (in Allahs Oneness) and works righteousness, he shall have the best reward, (Paradise), and we (Dhul-Qarnain) shall speak unto him mild words (as instructions).\"', 'As for the one who believes and acts righteously, he will have the best (life) as reward, and we shall speak to him politely in our directions.”'),
(2229, 18, 89, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'ثُمَّ   اَتۡبَعَ سَبَبًا ﴿۸۹﴾', 'پھر اس نے ایک اور سامان سفر کیا۔', 'پھر لگا ایک سامان کے پیچھے [۱۱۲]', 'Then he followed another way,', 'Thereafter, he followed a course,'),
(2230, 18, 90, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'حَتّٰۤی  اِذَا بَلَغَ  مَطۡلِعَ  الشَّمۡسِ وَجَدَہَا تَطۡلُعُ عَلٰی قَوۡمٍ لَّمۡ نَجۡعَلۡ لَّہُمۡ مِّنۡ دُوۡنِہَا سِتۡرًا ﴿ۙ۹۰﴾', 'یہاں تک کہ سورج کے طلوع ہونے کے مقام پر پہنچا تو دیکھا کہ وہ ایسے لوگوں پر طلوع  ہوتا ہے جنکے لئے ہم نے دھوپ سے بچاؤ کی کوئی اوٹ نہیں بنائی تھی۔', 'یہاں تک کہ جب پہنچا سورج نکلنے کی جگہ پایا اس کو کہ نکلتا ہے ایک قوم پر کہ نہیں بنا دیا ہم نے انکے لئے آفتاب سے ورے کوئی حجاب [۱۱۳]', 'Until, when he came to the rising place of the sun, he found it rising on a people for whom We (Allah) had provided no shelter against the sun.', 'until when he reached the point of sunrise, he found it rising over a people for whom We did not make any shelter against it.'),
(2231, 18, 91, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'کَذٰلِکَ ؕ وَ قَدۡ اَحَطۡنَا بِمَا لَدَیۡہِ خُبۡرًا ﴿۹۱﴾', 'حقیقت یوں ہی تھی اور جو کچھ اسکے پاس تھا ہم کو سب کی خبر تھی۔', 'یونہی ہے اور ہمارے قابو میں آ چکی ہے اس کے  پاس کی خبر [۱۱۴]', 'So (it was)! And We knew all about him (Dhul-Qarnain).', 'Thus it was, and Our knowledge fully comprehends whatever (wealth and equipment) he had with him.'),
(2232, 18, 92, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'ثُمَّ  اَتۡبَعَ  سَبَبًا ﴿۹۲﴾', 'پھر اس نے ایک اور سفر کا سامان کیا۔', 'پھر لگا ایک سامان کے پیچھے [۱۱۵]', 'Then he followed (another) way,', 'Thereafter he followed a course'),
(2233, 18, 93, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'حَتّٰۤی  اِذَا بَلَغَ  بَیۡنَ السَّدَّیۡنِ وَجَدَ مِنۡ دُوۡنِہِمَا قَوۡمًا ۙ لَّا یَکَادُوۡنَ یَفۡقَہُوۡنَ قَوۡلًا ﴿۹۳﴾', 'یہاں تک کہ دو اونچے سیدھے پہاڑوں کے درمیان پہنچا۔ تو دیکھا کہ انکے اس طرف کچھ لوگ ہیں کہ بات کو سمجھ نہیں سکتے۔', 'یہاں تک کہ جب پہنچا دو پہاڑوں کے بیچ پائے ان سے ورے ایسے لوگ جو لگتے نہیں کہ سمجھیں ایک بات [۱۱۶]', 'Until, when he reached between two mountains, he found, before (near) them (those two mountains), a people who scarcely understood a word.', 'until when he reached between the two mountains, he found by them a people who were almost unable to understand anything said.'),
(2234, 18, 94, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'قَالُوۡا یٰذَاالۡقَرۡنَیۡنِ  اِنَّ یَاۡجُوۡجَ وَ مَاۡجُوۡجَ مُفۡسِدُوۡنَ فِی الۡاَرۡضِ فَہَلۡ نَجۡعَلُ لَکَ خَرۡجًا عَلٰۤی اَنۡ  تَجۡعَلَ بَیۡنَنَا وَ  بَیۡنَہُمۡ  سَدًّا ﴿۹۴﴾', 'ان لوگوں نے کہا کہ اے ذوالقرنین! یاجوج اور ماجوج اس علاقے میں فساد کرتے رہتے ہیں بھلا ہم آپکے لئے خرچ کا انتظام کر دیں کہ آپ ہمارے اور انکے درمیان ایک دیوار کھینچ دیں۔', 'بولے اے ذوالقرنین یہ یاجوج و ماجوج دھوم اٹھاتے ہیں ملک میں سو تو کہے تو ہم مقرر کر دیں تیرے واسطے کچھ محصول اس شرط پر کہ بنا دےتو ہم میں ان میں ایک آڑ [۱۱۷]', 'They said: \"O Dhul-Qarnain! Verily! Yajooj and Majooj (Gog and Magog) are doing great mischief in the land. Shall we then pay you a tribute in order that you might erect a barrier between us and them?\"', 'They said, “O Dhul-Qarnain, the (tribes of) Ya’jūj and Ma’jūj (Gog and Magog) are mischief-makers on the earth. So, should we assign a tax for you on condition that you make a barrier between us and them?”'),
(2235, 18, 95, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'قَالَ مَا مَکَّنِّیۡ فِیۡہِ رَبِّیۡ خَیۡرٌ فَاَعِیۡنُوۡنِیۡ بِقُوَّۃٍ  اَجۡعَلۡ بَیۡنَکُمۡ وَ بَیۡنَہُمۡ  رَدۡمًا ﴿ۙ۹۵﴾', 'ذوالقرنین نے کہا کہ خرچ کا جو مقدور اللہ نے مجھے بخشا ہے وہ بہت اچھا ہے۔ تم مجھے قوت بازو سے مدد دو۔ میں تمہارے اور انکے درمیان ایک مضبوط رکاوٹ بنا دوں گا۔', 'بولا جو مقدور دیا مجھ کو میرے رب نے وہ بہتر ہے سو مدد کرو میری محنت میں بنا دوں تمہارے انکے بیچ ایک دیوار موٹی [۱۱۸]', 'He said: \"That (wealth, authority and power) in which my Lord had established me is better (than your tribute). So help me with strength (of men), I will erect between you and them a barrier.', 'He said, “What my Lord has (already) given in my control is better enough (for me than the tax you are offering to me), so help me (only) with some (man) power, and I shall make a rampart between you and them.'),
(2236, 18, 96, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'اٰتُوۡنِیۡ زُبَرَ الۡحَدِیۡدِ ؕ حَتّٰۤی  اِذَا سَاوٰی بَیۡنَ الصَّدَفَیۡنِ قَالَ انۡفُخُوۡا ؕ حَتّٰۤی  اِذَا جَعَلَہٗ  نَارًا ۙ قَالَ اٰتُوۡنِیۡۤ  اُفۡرِغۡ عَلَیۡہِ قِطۡرًا ﴿ؕ۹۶﴾', 'تم لوہے کے بڑے بڑے تختے میرے پاس لاؤ چنانچہ کام جاری کر دیا گیا یہاں تک کہ جب اس نے دونوں پہاڑوں کے درمیان کا حصہ برابر کر دیا اور کہا کہ اب اسے دھونکو۔ یہانتک کہ جب اس کو دھونک دھونک کر آگ کر دیا تو کہا کہ اب میرے پاس تانبا لاؤ کہ اس پر پگھلا کر ڈال دوں۔', 'لا دو مجھ کو تختے لوہے کے یہاں تک کہ جب برابر کر دیا دونوں پھانکوں تک پہاڑ کی کہا دھونکو یہاں تک کہ جب کر دیا اس کو آگ کہا لاؤ میرے پاس کہ ڈالوں اس پر پگھلا ہوا تانبا [۱۱۹]', '\"Give me pieces (blocks) of iron,\" then, when he had filled up the gap between the two mountain-cliffs, he said: \"Blow,\" till when he had made it (red as) fire, he said: \"Bring me molten copper to pour over it.\"', 'Bring me big pieces of iron.” (They proceeded accordingly) until when he leveled up (the gap) between the two cliffs, he said, “Blow.” (They complied) until when he made it (like) fire, he said, “Bring me molten copper, and I will pour it upon this.”'),
(2237, 18, 97, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'فَمَا اسۡطَاعُوۡۤا اَنۡ یَّظۡہَرُوۡہُ  وَ مَا اسۡتَطَاعُوۡا  لَہٗ  نَقۡبًا ﴿۹۷﴾', 'پھر ان میں یہ قدرت نہ رہی کہ اس پر چڑھ سکیں۔ اور نہ یہ طاقت رہی کہ اس میں نقب لگا سکیں۔', 'پھر نہ چڑھ سکیں اس پر اور نہ کر سکیں اس میں سوراخ [۱۲۰]', 'So they (Yajooj and Majooj (Gog and Magog)) were made powerless to scale it or dig through it.', 'So they (Ya’jūj and Ma’jūj) were not able to climb it, nor were they able to make a hole in it.'),
(2238, 18, 98, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'قَالَ ہٰذَا رَحۡمَۃٌ مِّنۡ رَّبِّیۡ ۚ فَاِذَا جَآءَ وَعۡدُ رَبِّیۡ جَعَلَہٗ  دَکَّآءَ ۚ وَ کَانَ وَعۡدُ رَبِّیۡ  حَقًّا  ﴿ؕ۹۸﴾', 'بولا کہ یہ میرے پروردگار کی مہربانی ہے پھر جب میرے پروردگار کا وعدہ آ پہنچے گا تو اس کو ڈھا کر ہموار کر دے گا اور میرے پروردگار کا وعدہ سچا ہے۔', 'بولا یہ ایک مہربانی ہے میرے رب کی پھر جب آئے وعدہ میرے رب کا گرا دے اس کو ڈھا کر اور ہے وعدہ میرے رب کا سچا [۱۲۱]', 'Dhul-Qarnain) said: \"This is a mercy from my Lord, but when the Promise of my Lord comes, He shall level it down to the ground. And the Promise of my Lord is ever true.\"', 'He said, “This is a mercy from my Lord. Then, when the promise of my Lord will come, He will make it leveled to the ground. The promise of my Lord is true.”'),
(2239, 18, 99, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'وَ تَرَکۡنَا بَعۡضَہُمۡ یَوۡمَئِذٍ یَّمُوۡجُ فِیۡ بَعۡضٍ وَّ نُفِخَ فِی الصُّوۡرِ فَجَمَعۡنٰہُمۡ جَمۡعًا ﴿ۙ۹۹﴾', 'اس روز ہم انکو چھوڑ دیں گے کہ روئے زمین پر پھیل کر ایک دوسرے میں گھس جائیں گے اور صور پھونکا جائے گا تو ہم سب کو جمع کر لیں گے۔', 'اور چھوڑ دیں گے ہم خلق کو اس دن ایک دوسرے میں گھستے اور پھونک ماریں گے صور میں پھر جمع کر لائیں گے ہم ان سب کو', 'And on that Day (i.e. the Day Yajooj and Majooj (Gog and Magog) will come out), We shall leave them to surge like waves on one another, and the Trumpet will be blown, and We shall collect them all together.', 'And on that day, (i.e. the Doomsday) We will leave them (all the people including Ya’jūj and Ma’jūj) surging over one another. And the Horn shall be blown, then We shall gather them together.'),
(2240, 18, 100, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'وَّ عَرَضۡنَا جَہَنَّمَ  یَوۡمَئِذٍ  لِّلۡکٰفِرِیۡنَ  عَرۡضَۨا ﴿۱۰۰﴾ۙ', 'اور اس روز ہم جہنم کو کافروں کے سامنے لائیں گے۔', 'اور دکھلا دیں ہم دوزخ اس دن کافروں کو سامنے [۱۲۲]', 'And on that Day We shall present Hell to the disbelievers, plain to view,', 'And on that day We will bring Jahannam fully exposed before the infidels'),
(2241, 18, 101, 11, 2, 16, 'قَالَ اَلَمۡ', 'الکہف', 'الَّذِیۡنَ کَانَتۡ اَعۡیُنُہُمۡ فِیۡ غِطَـآءٍ عَنۡ ذِکۡرِیۡ وَ کَانُوۡا لَا یَسۡتَطِیۡعُوۡنَ سَمۡعًا ﴿۱۰۱﴾٪', 'جنکی آنکھیں میری یاد سے پردے میں تھیں اور وہ سننے کی طاقت نہیں رکھتے تھے۔', 'جن کی آنکھوں پر پردہ پڑا تھا میری یاد سے اور نہ سن سکتے تھے [۱۲۳]', '(To) Those whose eyes had been under a covering from My Reminder (this Quran), and who could not bear to hear (it).', 'whose eyes were under a cover against My reminders, and they were not able to listen.'),
(2242, 18, 102, 12, 3, 16, 'قَالَ اَلَمۡ', 'الکہف', 'اَفَحَسِبَ الَّذِیۡنَ کَفَرُوۡۤا اَنۡ یَّتَّخِذُوۡا عِبَادِیۡ مِنۡ دُوۡنِیۡۤ  اَوۡلِیَآءَ ؕ اِنَّـاۤ  اَعۡتَدۡنَا جَہَنَّمَ  لِلۡکٰفِرِیۡنَ نُزُلًا ﴿۱۰۲﴾', 'اب کیا کافر یہ خیال کرتے ہیں کہ وہ میرے بندوں کو میرے سوا اپنا کارساز بنائیں گے تو ہم خفا نہیں ہونگے ہم نے ایسے کافروں کے لئے جہنم کی مہمانی تیار کر رکھی ہے۔', 'اب کیا سمجھتے ہیں منکر کہ ٹھہرائیں میرے بندوں کو میرے سوا حمایتی [۱۲۴] ہم نے تیار کیا ہے دوزخ کو کافروں کی مہمانی [۱۲۵]', 'Do then those who disbelieve think that they can take My slaves (i.e., the angels, Allahs Messengers, Iesa (Jesus), son of Maryam (Mary), etc.) as Auliya (lords, gods, protectors, etc.) besides Me? Verily, We have prepared Hell as an entertainment for the disbelievers (in the Oneness of Allah Islamic Monotheism).', 'Do, then, the disbelievers deem (it fit) that they take My servants as patrons beside Me? Surely, We have prepared Jahannam as entertainment for the disbelievers.'),
(2243, 18, 103, 12, 3, 16, 'قَالَ اَلَمۡ', 'الکہف', 'قُلۡ ہَلۡ نُنَبِّئُکُمۡ  بِالۡاَخۡسَرِیۡنَ اَعۡمَالًا ﴿۱۰۳﴾ؕ', 'کہدو کہ ہم تمہیں ایسے لوگ بتائیں جو اعمال کے لحاظ سے بڑے نقصان میں ہیں۔', 'تو کہہ ہم بتائیں تم کو کن کا کیا ہوا گیا بہت اکارت', 'Say (O Muhammad SAW): \"Shall We tell you the greatest losers in respect of (their) deeds?', 'Say, “Shall We tell you about the greatest losers in respect of (their) deeds?'),
(2244, 18, 104, 12, 3, 16, 'قَالَ اَلَمۡ', 'الکہف', 'اَلَّذِیۡنَ ضَلَّ سَعۡیُہُمۡ فِی الۡحَیٰوۃِ  الدُّنۡیَا وَ ہُمۡ یَحۡسَبُوۡنَ اَنَّہُمۡ یُحۡسِنُوۡنَ صُنۡعًا ﴿۱۰۴﴾', 'یہ وہ لوگ ہیں جنکی دوڑ دھوپ دنیا کی زندگی میں برباد ہو گئ۔ اور وہ یہ سمجھے ہوئے ہیں کہ وہ اچھے کام کر رہے ہیں۔', 'وہ لوگ جن کی کوشش بھٹکتی رہی دنیا کی زندگی میں اور وہ سمجھتے رہے کہ خوب بناتے ہیں کام [۱۲۶]', '\"Those whose efforts have been wasted in this life while they thought that they were acquiring good by their deeds!', 'Those are the ones whose effort in the worldly life has gone in vain, while they think they are doing well.'),
(2245, 18, 105, 12, 3, 16, 'قَالَ اَلَمۡ', 'الکہف', 'اُولٰٓئِکَ الَّذِیۡنَ کَفَرُوۡا بِاٰیٰتِ رَبِّہِمۡ وَ لِقَآئِہٖ فَحَبِطَتۡ اَعۡمَالُہُمۡ فَلَا نُقِیۡمُ لَہُمۡ یَوۡمَ الۡقِیٰمَۃِ  وَزۡنًا ﴿۱۰۵﴾', 'یہ وہ لوگ ہیں جنہوں نے اپنے پروردگار کی آیتوں کو نہ مانا اور اسکے سامنے جانے سے انکار کیا تو انکے اعمال ضائع ہو گئے سو ہم قیامت کے دن انکے لئے کچھ بھی وزن قائم نہیں کریں گے۔', 'وہی ہیں جو منکر ہوئے اپنے رب کی نشانیوں سے اور اسکے ملنے سے [۱۲۷] سو برباد گیا ان کا کیا ہوا پھر نہ کھڑی کریں گے ہم انکے واسطے قیامت کے دن تول [۱۲۸]', '\"They are those who deny the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of their Lord and the Meeting with Him (in the Hereafter). So their works are in vain, and on the Day of Resurrection, We shall not give them any weight.', 'Those are the ones who rejected the signs of their Lord and (the concept of) meeting with Him, so their deeds have gone to waste, and We shall assign to them no weight at all.'),
(2246, 18, 106, 12, 3, 16, 'قَالَ اَلَمۡ', 'الکہف', 'ذٰلِکَ جَزَآؤُہُمۡ جَہَنَّمُ بِمَا کَفَرُوۡا وَ اتَّخَذُوۡۤا اٰیٰتِیۡ وَ  رُسُلِیۡ  ہُزُوًا ﴿۱۰۶﴾', 'یہ انکی سزا ہے یعنی جہنم۔ اس لئے کہ انہوں نے کفر کیا اور ہماری آیتوں اور ہمارے پیغمبروں کی ہنسی اڑائی۔', 'یہ بدلہ ان کا ہے دوزخ اس پر کہ منکر ہوئے اور ٹھہرایا میری باتوں اور میرے رسولوں کو ٹھٹھا [۱۲۹]', '\"That shall be their recompense, Hell; because they disbelieved and took My Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) and My Messengers by way of jest and mockery.', 'That is their punishment, the Jahannam , for they disbelieved and made My signs and My messengers a mockery.'),
(2247, 18, 107, 12, 3, 16, 'قَالَ اَلَمۡ', 'الکہف', 'اِنَّ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ کَانَتۡ لَہُمۡ  جَنّٰتُ الۡفِرۡدَوۡسِ نُزُلًا ﴿۱۰۷﴾ۙ', 'جو لوگ ایمان لائے اور عمل نیک کئے انکے لئے بہشت کے باغ بطور مہمانی ہوں گے۔', 'جو لوگ ایمان لائے ہیں اور کئے ہیں بھلے کام انکے واسطے ہے ٹھنڈی چھاؤں کے باغ مہمانی', '\"Verily! Those who believe (in the Oneness of Allah Islamic Monotheism) and do righteous deeds, shall have the Gardens of Al-Firdaus (the Paradise) for their entertainment.', 'Surely those who believed and did righteous deeds, theirs are the Gardens of Firdaus as entertainment'),
(2248, 18, 108, 12, 3, 16, 'قَالَ اَلَمۡ', 'الکہف', 'خٰلِدِیۡنَ فِیۡہَا لَا  یَبۡغُوۡنَ عَنۡہَا حِوَلًا ﴿۱۰۸﴾', 'ہمیشہ ان میں رہیں گے اور وہاں سے مکان بدلنا نہ چاہیں گے۔', 'رہا کریں ان میں نہ چاہیں وہاں سے جگہ بدلنی [۱۳۰]', '\"Wherein they shall dwell (forever). No desire will they have to be removed therefrom.\"', 'where they will live forever, and will not wish to move from there.”'),
(2249, 18, 109, 12, 3, 16, 'قَالَ اَلَمۡ', 'الکہف', 'قُلۡ لَّوۡ کَانَ الۡبَحۡرُ مِدَادًا لِّکَلِمٰتِ رَبِّیۡ لَنَفِدَ الۡبَحۡرُ  قَبۡلَ اَنۡ تَنۡفَدَ کَلِمٰتُ رَبِّیۡ وَ لَوۡ  جِئۡنَا بِمِثۡلِہٖ  مَدَدًا ﴿۱۰۹﴾', 'کہدو کہ اگر سمندر میرے پروردگار کی باتوں کے لکھنے کے لئے روشنائی ہو تو قبل اسکے کہ میرے پروردگار کی باتیں تمام ہوں سمندر ختم ہو جائے اگرچہ ہم ویسا ہی اور اسکی مدد کو لائیں۔', 'تو کہہ اگر دریا سیاہی ہو کہ لکھے میرے رب کی باتیں بیشک دریا خرچ ہو چکے ابھی نہ پوری ہوں میرے رب کی باتیں اور اگرچہ دوسرا بھی لائیں ہم ویسا ہی اسکی مدد کو [۱۳۱]', 'Say (O Muhammad SAW to mankind). \"If the sea were ink for (writing) the Words of my Lord, surely, the sea would be exhausted before the Words of my Lord would be finished, even if we brought (another sea) like it for its aid.\"', 'Say, “If the ocean were to be ink for (writing) the Words of my Lord, the ocean would have been consumed before the Words of my Lord are exhausted, even though we were to bring another (ocean) like it in addition.”'),
(2250, 18, 110, 12, 3, 16, 'قَالَ اَلَمۡ', 'الکہف', 'قُلۡ اِنَّمَاۤ  اَنَا بَشَرٌ  مِّثۡلُکُمۡ  یُوۡحٰۤی  اِلَیَّ اَنَّمَاۤ  اِلٰـہُکُمۡ  اِلٰہٌ  وَّاحِدٌ ۚ فَمَنۡ کَانَ یَرۡجُوۡا لِقَآءَ رَبِّہٖ فَلۡیَعۡمَلۡ عَمَلًا صَالِحًا وَّ لَا یُشۡرِکۡ بِعِبَادَۃِ  رَبِّہٖۤ  اَحَدًا ﴿۱۱۰﴾٪', 'کہدو کہ میں تمہاری طرح کا ایک بشر ہوں۔ البتہ میری طرف وحی آتی ہے کہ تمہارا معبود وہی ایک معبود ہے تو جو شخص اپنے پروردگار سے ملنے کی امید رکھے چاہیے کہ عمل نیک کرے اور اپنے پروردگار کی عبادت میں کسی کو شریک نہ بنائے۔', 'تو کہہ میں بھی ایک آدمی ہوں جیسے تم حکم آتا ہے مجھ کو کہ معبود تمہارا ایک معبود ہے سو پھر جس کو امید ہو ملنے کی اپنے رب سے سوہ وہ کرے کچھ کام نیک اور شریک نہ کرے اپنے رب کی بندگی میں کسی کو [۱۳۲]', 'Say (O Muhammad SAW): \"I am only a man like you. It has been inspired to me that your Ilah (God) is One Ilah (God i.e. Allah). So whoever hopes for the Meeting with his Lord, let him work righteousness and associate none as a partner in the worship of his Lord.\"', 'Say, “Surely, I am but a human being like you; it is revealed to me that your God is the One God. So the one who hopes to meet his Lord must do righteous deed and must not associate anyone in the worship of his Lord.”'),
(2251, 19, 1, 1, 4, 16, 'قَالَ اَلَمۡ', 'مریم', 'کٓہٰیٰعٓصٓ ۟﴿ۚ۱﴾', 'کہٰیٰعص۔', 'کہٰیٰعص', 'Kaf HaYaAeenSad. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings).', 'Kāf, Hā Yā, ‘Ain, Sād'),
(2252, 19, 2, 1, 4, 16, 'قَالَ اَلَمۡ', 'مریم', 'ذِکۡرُ  رَحۡمَتِ  رَبِّکَ  عَبۡدَہٗ   زَکَرِیَّا  ۖ﴿ۚ۲﴾', 'یہ تمہارے پروردگار کی مہربانی کا بیان ہے جو اس نے اپنے بندے زکریا پر کی تھی۔', 'یہ مذکور ہے تیرے رب کی رحمت کا اپنے بندہ زکریا پر [۱]', '(This is) a mention of the mercy of your Lord to His slave Zakariya (Zachariah).', 'This is a narration of your Lord’s mercy to His servant Zakariyyā,'),
(2253, 19, 3, 1, 4, 16, 'قَالَ اَلَمۡ', 'مریم', 'اِذۡ  نَادٰی  رَبَّہٗ  نِدَآءً  خَفِیًّا ﴿۳﴾', 'جب انہوں نے اپنے پروردگار کو دبی آواز سے پکارا۔', 'جب پکارا اُس نے اپنے رب کو چھپی آواز سے [۲]', 'When he called out his Lord (Allah) a call in secret,', 'When he called his Lord in a low voice.'),
(2254, 19, 4, 1, 4, 16, 'قَالَ اَلَمۡ', 'مریم', 'قَالَ رَبِّ اِنِّیۡ وَہَنَ الۡعَظۡمُ مِنِّیۡ وَ اشۡتَعَلَ الرَّاۡسُ شَیۡبًا وَّ لَمۡ  اَکُنۡۢ بِدُعَآئِکَ  رَبِّ  شَقِیًّا ﴿۴﴾', 'اور کہا کہ اے میرے پروردگار میری ہڈیاں بڑھاپے کے سبب کمزور ہو گئ ہیں اور سر سفید بالوں کیوجہ سے چمکنے لگا ہے اور اے میرے پروردگار میں تجھ سے مانگ کر کبھی محروم نہیں رہا۔', 'بولا اے میرے رب بوڑھی ہو گئیں میری ہڈیاں اور شعلہ نکلا سر سے بڑھاپے کا [۳] اور تجھ سے مانگ کر اے رب میں کبھی محروم نہیں رہا [۴]', 'Saying: \"My Lord! Indeed my bones have grown feeble, and grey hair has spread on my head, And I have never been unblest in my invocation to You, O my Lord!', 'He said, “My Lord, I am in a state that bones in my body have turned feeble, and the head has flared up grey with old age, and I never remained, My Lord, unanswered in my prayer to You.'),
(2255, 19, 5, 1, 4, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ اِنِّیۡ خِفۡتُ الۡمَوَالِیَ مِنۡ وَّرَآءِیۡ وَ کَانَتِ  امۡرَاَتِیۡ عَاقِرًا فَہَبۡ لِیۡ مِنۡ لَّدُنۡکَ  وَلِیًّا  ۙ﴿۵﴾', 'اور میں اپنے بعد اپنے بھائی بندوں سے ڈرتا ہوں اور میری بیوی بانجھ ہے پھر بھی مجھے اپنے پاس سے ایک وارث عطا فرما۔', 'اور میں ڈرتا ہوں بھائی بندوں سے اپنے پیچھے [۵] اور عورت میری بانجھ ہے سو بخش تو مجھ کو اپنے پاس سے ایک کام اٹھانے والا', '\"And Verily! I fear my relatives after me, since my wife is barren. So give me from Yourself an heir,', 'I fear (my) kinsmen after me, and my wife is barren, so bless me with an heir, from Your own side,'),
(2256, 19, 6, 1, 4, 16, 'قَالَ اَلَمۡ', 'مریم', 'یَّرِثُنِیۡ وَ یَرِثُ مِنۡ اٰلِ یَعۡقُوۡبَ ٭ۖ وَ اجۡعَلۡہُ   رَبِّ  رَضِیًّا ﴿۶﴾', 'جو میری اور اولاد یعقوب کی میراث کا مالک ہو۔ اور اے میرے پروردگار اسکو خوش اخلاق بنائیو۔', 'جو میری جگہ بیٹھے اور یعقوب کی اولاد کی [۶] اور کر اُسکو اے رب من مانتا [۷]', '\"Who shall inherit me, and inherit (also) the posterity of Yaqoob (Jacob) (inheritance of the religious knowledge and Prophethood, not the wealth, etc.). And make him, my Lord, one with whom You are Well-pleased!\".', 'who inherits me and inherits the house of Ya‘qūb. And make him, My Lord, a favourite one.”'),
(2257, 19, 7, 1, 4, 16, 'قَالَ اَلَمۡ', 'مریم', 'یٰزَکَرِیَّاۤ  اِنَّا نُبَشِّرُکَ بِغُلٰمِۣ اسۡمُہٗ یَحۡیٰی ۙ لَمۡ  نَجۡعَلۡ  لَّہٗ  مِنۡ  قَبۡلُ  سَمِیًّا ﴿۷﴾', 'فرمایا اے زکریا ہم تمکو ایک لڑکے کی بشارت دیتے ہیں جس کا نام یحیٰی ہو گا اس سے پہلے ہم نے اس نام کا کوئی شخص پیدا نہیں کیا۔', 'اے زکریا ہم تجھ کو خوشخبری سناتے ہیں ایک لڑکے کی جس کا نام ہے یحیٰی نہیں کیا ہم نے پہلے اس نام کا کوئی [۸]', '(Allah said) \"O Zakariya (Zachariah)! Verily, We give you the glad tidings of a son, His name will be Yahya (John). We have given that name to none before (him).\"', '(Allah said) “O Zakariyyā, We give you the good news of a boy whose name is YaHyā. We did not create any one before him of the same name.”'),
(2258, 19, 8, 1, 4, 16, 'قَالَ اَلَمۡ', 'مریم', 'قَالَ رَبِّ اَنّٰی یَکُوۡنُ لِیۡ غُلٰمٌ وَّ کَانَتِ امۡرَاَتِیۡ  عَاقِرًا  وَّ  قَدۡ  بَلَغۡتُ مِنَ  الۡکِبَرِ  عِتِیًّا ﴿۸﴾', 'انہوں نے کہا کہ پروردگار میرے ہاں کس طرح لڑکا ہو گا۔ جبکہ میری بیوی بانجھ ہے اور میں بڑھاپے کی اس حالت کو پہنچ گیا کہ سوکھ گیا ہوں۔', 'بولا اے رب کہاں سے ہو گا مجھ کو لڑکا اور میری عورت بانجھ ہے اور میں بوڑھا ہو گیا یہاں تک کہ اکڑ گیا [۹]', 'He said: \"My Lord! How can I have a son, when my wife is barren, and I have reached the extreme old age.\"', 'He Said, “My Lord, how shall there be a boy for me while my wife is barren, and I have reached the extreme of old age?”'),
(2259, 19, 9, 1, 4, 16, 'قَالَ اَلَمۡ', 'مریم', 'قَالَ  کَذٰلِکَ ۚ قَالَ رَبُّکَ ہُوَ  عَلَیَّ ہَیِّنٌ  وَّ قَدۡ خَلَقۡتُکَ مِنۡ قَبۡلُ وَ لَمۡ  تَکُ شَیۡئًا ﴿۹﴾', 'حکم ہوا کہ اسی طرح ہو گا تمہارے پروردگار نے فرمایا ہے کہ مجھے یہ آسان ہے اور میں پہلے تمکو بھی تو پیدا کر چکا ہوں اور تم کچھ چیز نہ تھے۔', 'کہا یونہی ہو گا [۱۰] فرما دیا تیرے رب نے وہ مجھ پر آسان ہے اور تجھ کو پیدا کیا میں نے پہلے سے اور نہ تھا تو کوئی چیز [۱۱]', 'He said: \"So (it will be). Your Lord says; It is easy for Me. Certainly I have created you before, when you had been nothing!\"', 'He said, “So it is; your Lord said ‘it is easy for Me, and I did create you before, when you were nothing.’”'),
(2260, 19, 10, 1, 4, 16, 'قَالَ اَلَمۡ', 'مریم', 'قَالَ رَبِّ اجۡعَلۡ  لِّیۡۤ   اٰیَۃً ؕ قَالَ اٰیَتُکَ اَلَّا تُکَلِّمَ النَّاسَ ثَلٰثَ لَیَالٍ سَوِیًّا ﴿۱۰﴾', 'کہا کہ پروردگار میرے لئے کوئی نشانی مقرر فرما۔ فرمایا نشانی یہ ہے کہ تم صحیح و سالم ہوتے ہوئے تین رات دن لوگوں سے بات نہ کر سکو گے۔', 'بولا اے رب ٹھہرا دے میرے لئے کوئی نشانی فرمایا تیری نشانی یہ کہ بات نہ کرے تو لوگوں سے تین رات تک صحیح تندرست [۱۲]', '(Zakariya (Zachariah)) said: \"My Lord! Appoint for me a sign.\" He said: \"Your sign is that you shall not speak unto mankind for three nights, though having no bodily defect.\"', 'He said, “My Lord, make for me a sign.” He said, “Your sign is that you will not (be able to) speak to the people for three (consecutive) nights, even though you will be sound in health.”'),
(2261, 19, 11, 1, 4, 16, 'قَالَ اَلَمۡ', 'مریم', 'فَخَرَجَ عَلٰی قَوۡمِہٖ مِنَ الۡمِحۡرَابِ فَاَوۡحٰۤی  اِلَیۡہِمۡ اَنۡ سَبِّحُوۡا بُکۡرَۃً وَّ عَشِیًّا ﴿۱۱﴾', 'پھر وہ عبادت کے حجرے سے نکل کر اپنی قوم کے پاس آئے تو ان سے اشارے سے کہا کہ صبح و شام تسبیح کرتے رہو۔', 'پھر نکلا اپنے لوگوں کے پاس حجرہ سے تو اشارہ سے کہا اُنکو کہ یاد کرو صبح اور شام [۱۳]', 'Then he came out to his people from Al-Mihrab (a praying place or a private room, etc.), he told them by signs to glorify Allahs Praises in the morning and in the afternoon.', 'Then he came out to his people from the place of prayer, and directed them by gestures to proclaim the purity of Allah at morning and evening.'),
(2262, 19, 12, 1, 4, 16, 'قَالَ اَلَمۡ', 'مریم', 'یٰیَحۡیٰی خُذِ الۡکِتٰبَ بِقُوَّۃٍ ؕ وَ اٰتَیۡنٰہُ الۡحُکۡمَ  صَبِیًّا ﴿ۙ۱۲﴾', 'فرمایا اے یحیٰی ہماری کتاب کو مضبوطی سے تھامے رہو۔ اور ہم نے انکو لڑکپن ہی میں دانائی عطا فرمائی تھی۔', 'اے یحیٰی اٹھا لے کتاب زور سے [۱۴] اور دیا ہم نے اُسکو حکم کرنا لڑکا پن میں [۱۵]', '(It was said to his son): \"O Yahya (John)! Hold fast the Scripture (the Taurat (Torah)).\" And We gave him wisdom while yet a child.', '(When the child was born, Allah said to him,) “O YaHyā, hold on to the Book firmly.” And We gave him wisdom, while he was still a child,'),
(2263, 19, 13, 1, 4, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَّ حَنَانًا مِّنۡ لَّدُنَّا وَ زَکٰوۃً ؕ وَ کَانَ تَقِیًّا ﴿ۙ۱۳﴾', 'اور اپنے پاس سے شفقت اور پاکیزگی دی تھی اور وہ پرہیزگار تھے۔', 'اور شوق دیا اپنی طرف سے اورستھرائی اور تھا پرہیز گار [۱۶]', 'And (made him) sympathetic to men as a mercy (or a grant) from Us, and pure from sins (i.e. Yahya (John)) and he was righteous,', 'and (blessed him with) love from our own, and purity; and he was God-fearing,'),
(2264, 19, 14, 1, 4, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَّ بَرًّۢا بِوَالِدَیۡہِ وَ لَمۡ یَکُنۡ جَبَّارًا عَصِیًّا ﴿۱۴﴾', 'اور وہ اپنے ماں باپ کے ساتھ نیکی کرنے والے تھے اور سرکش اور نافرمان نہیں تھے۔', 'اور نیکی کرنے والا اپنے ماں باپ سے اور نہ تھا زبردست خود سر [۱۷]', 'And dutiful towards his parents, and he was neither an arrogant nor disobedient (to Allah or to his parents).', 'and he was good to his parents; and he was not oppressive (or) disobedient.'),
(2265, 19, 15, 1, 4, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ سَلٰمٌ  عَلَیۡہِ یَوۡمَ وُلِدَ وَ  یَوۡمَ  یَمُوۡتُ وَ  یَوۡمَ  یُبۡعَثُ حَیًّا ﴿٪۱۵﴾', 'اور جس دن وہ پیدا ہوئے اور جس دن وفات پائیں گے اور جس دن زندہ کر کے اٹھائے جائیں گے۔ ان پر سلام ہے۔', 'اور سلام ہے اُس پر جس دن پیدا ہو ا اور جس دن مرے اورجس دن اٹھ کھڑا ہو زندہ ہو کر [۱۸]', 'And Salamun (peace) be on him the day he was born, the day he dies, and the day he will be raised up to life (again)!', 'Peace on him the day he was born, the day he dies and the day he will be raised alive.'),
(2266, 19, 16, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ اذۡکُرۡ فِی الۡکِتٰبِ مَرۡیَمَ ۘ اِذِ انۡتَبَذَتۡ مِنۡ اَہۡلِہَا مَکَانًا شَرۡقِیًّا ﴿ۙ۱۶﴾', 'اور کتاب یعنی قرآن میں مریم کا بھی تذکرہ کرو جب وہ اپنے لوگوں سے الگ ہو کر مکان کے مشرقی حصے میں چلی گئیں۔', 'اور مذکور کر کتاب میں مریم کا جب جدا ہوئی اپنے لوگوں سے ایک شرقی مکان میں [۱۹]', 'And mention in the Book (the Quran, O Muhammad SAW , the story of) Maryam (Mary), when she withdrew in seclusion from her family to a place facing east.', 'And mention in the Book (the story of) Maryam, when she secluded herself from her people to a place towards East,'),
(2267, 19, 17, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'فَاتَّخَذَتۡ مِنۡ دُوۡنِہِمۡ  حِجَابًا ۪۟ فَاَرۡسَلۡنَاۤ  اِلَیۡہَا رُوۡحَنَا فَتَمَثَّلَ لَہَا بَشَرًا سَوِیًّا ﴿۱۷﴾', 'پھر انہوں نے انکی طرف سے پردہ کر لیا  تو ہم نے ان کی طرف اپنا فرشتہ بھیجا سو وہ انکے سامنے ایک خوبصورت مرد کی صورت میں آیا۔', 'پھر پکڑ لیا اُن سے ورے ایک پردہ پھر بھیجا ہم نے اُسکے پاس اپنا فرشتہ پھر بن کر آیا اُسکے آگے آدمی پورا [۲۰]', 'She placed a screen (to screen herself) from them; then We sent to her Our Ruh (angel Jibrael (Gabriel)), and he appeared before her in the form of a man in all respects.', 'then she used a barrier to hide herself from them. Then, We sent to her Our Spirit, (Jibra’īl) and he took before her the form of a perfect human being.'),
(2268, 19, 18, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'قَالَتۡ اِنِّیۡۤ  اَعُوۡذُ بِالرَّحۡمٰنِ مِنۡکَ اِنۡ کُنۡتَ تَقِیًّا ﴿۱۸﴾', 'مریم بولیں کہ اگر تم پرہیزگار ہو تو میں تم سے بچنے کیلئے رحمٰن کی پناہ لیتی ہوں۔', 'بولی مجھ کو رحمٰن کی پناہ تجھ سے اگر ہے تو ڈر رکھنے والا [۲۱]', 'She said: \"Verily! I seek refuge with the Most Beneficent (Allah) from you, if you do fear Allah.\"', 'She said, “I seek refuge with the All-Merciful (Allah) against you, if you are God-fearing.”'),
(2269, 19, 19, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'قَالَ  اِنَّمَاۤ  اَنَا رَسُوۡلُ رَبِّکِ ٭ۖ لِاَہَبَ لَکِ غُلٰمًا  زَکِیًّا ﴿۱۹﴾', 'فرشتے نے کہا کہ میں تو تمہارے پروردگار کا بھیجا ہوا یعنی فرشتہ ہوں اور اس لئے آیا ہوں کہ تمہیں پاکیزہ لڑکا بخشوں۔', 'بولا میں تو بھیجا ہوا ہوں تیرے رب کا کہ دے جاؤں تجھ کو ایک لڑکا ستھرا [۲۲]', '(The angel) said: \"I am only a Messenger from your Lord, (to announce) to you the gift of a righteous son.\"', 'He said, “I am but a message-bearer of your Lord (sent) to give you a boy, purified.”'),
(2270, 19, 20, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'قَالَتۡ اَنّٰی یَکُوۡنُ لِیۡ غُلٰمٌ وَّ لَمۡ یَمۡسَسۡنِیۡ  بَشَرٌ  وَّ  لَمۡ   اَکُ  بَغِیًّا ﴿۲۰﴾', 'مریم نے کہا کہ میرے ہاں لڑکا کیونکر ہو گا جبکہ مجھے کسی مرد نے بطور شوہر چھوا تک نہیں اور میں بدکار بھی نہیں ہوں۔', 'بولی کہاں سے ہو گا میرے لڑکا اور چھوا نہیں مجھ کو آدمی نے اور میں بدکار کبھی نہیں تھی [۲۳]', 'She said: \"How can I have a son, when no man has touched me, nor am I unchaste?\"', 'She said, “How shall I have a boy while no human has ever touched me, nor have I ever been unchaste?”'),
(2271, 19, 21, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'قَالَ  کَذٰلِکِ ۚ قَالَ رَبُّکِ ہُوَ  عَلَیَّ ہَیِّنٌ ۚ وَ  لِنَجۡعَلَہٗۤ  اٰیَۃً  لِّلنَّاسِ وَ رَحۡمَۃً  مِّنَّا ۚ وَ کَانَ  اَمۡرًا مَّقۡضِیًّا ﴿۲۱﴾', 'فرشتے نے کہا کہ یونہی ہو گا تمہارے پروردگار نے فرمایا کہ یہ مجھے آسان ہے اور میں اسے اسی طریق پر پیدا کروں گا تاکہ ہم اس کو لوگوں کے لئے اپنی طرف سے نشانی اور ذریعہ رحمت بنائیں اور یہ کام مقرر ہو چکا ہے۔', 'بولا یونہی فرما دیا تیرے رب نے وہ مجھ پر آسان ہے [۲۴] اور اُسکو ہم کیا چاہتے ہیں لوگوں کیلئے نشانی اور مہربانی اپنی طرف سے اور ہے یہ کام مقرر ہو چکا [۲۵]', 'He said: \"So (it will be), your Lord said: That is easy for Me (Allah): And (We wish) to appoint him as a sign to mankind and a mercy from Us (Allah), and it is a matter (already) decreed, (by Allah). \"', 'He said, “So it is; your Lord said, ‘It is easy for Me, and (We will do this) so that We make it a sign for people and a mercy from Us, and this is a matter already destined.’”'),
(2272, 19, 22, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'فَحَمَلَتۡہُ  فَانۡتَبَذَتۡ بِہٖ مَکَانًا قَصِیًّا ﴿۲۲﴾', 'چنانچہ وہ اس بچے کے ساتھ حاملہ ہو گئیں اور اسے لیکر ایک دور جگہ چلی گئیں۔', 'پھر پیٹ میں لیا اُسکو [۲۶] پھر یکسو ہوئی اُسکو لیکر ایک بعید مکان میں [۲۷]', 'So she conceived him, and she withdrew with him to a far place (i.e. Bethlehem valley about 4-6 miles from Jerusalem).', 'So she conceived him, and went in seclusion with him to a remote place.'),
(2273, 19, 23, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'فَاَجَآءَہَا الۡمَخَاضُ  اِلٰی جِذۡعِ  النَّخۡلَۃِ ۚ قَالَتۡ یٰلَیۡتَنِیۡ مِتُّ قَبۡلَ ہٰذَا  وَ کُنۡتُ نَسۡیًا مَّنۡسِیًّا ﴿۲۳﴾', 'پھر دردزہ انکو کھجور کے تنے کی طرف لے آیا۔ کہنے لگیں کہ کاش میں اس سے پہلے مر چکتی اور بھولی بسری ہو گئ ہوتی۔', 'پھر لے آیا اُسکو دردزہ ایک کھجور کی جڑ میں بولی کسی طرح میں مر چکتی اس سے پہلے اور ہو جاتی بھولی بسری [۲۸]', 'And the pains of childbirth drove her to the trunk of a date-palm. She said: \"Would that I had died before this, and had been forgotten and out of sight!\"', 'Then the labour pains brought her to the trunk of a palm-tree. She said “O that I would have died before this, and would have been something gone, forgotten.”'),
(2274, 19, 24, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'فَنَادٰىہَا مِنۡ تَحۡتِہَاۤ  اَلَّا تَحۡزَنِیۡ قَدۡ جَعَلَ  رَبُّکِ  تَحۡتَکِ  سَرِیًّا ﴿۲۴﴾', 'تب انکے ٹیلے کے نیچے کی جانب سے فرشتے نے انکو آواز دی کہ غمناک نہ ہو۔ تمہارے پروردگار نے تمہارے نیچے ایک چشمہ پیدا کر دیا ہے۔', 'پس آواز دی اسکو اُسکے نیچے سے کہ غمگین مت ہو  کر دیا تیرے رب نے تیرے نیچے ایک چشمہ', 'Then (the babe Iesa (Jesus) or Jibrael (Gabriel)) cried unto her from below her, saying: \"Grieve not! Your Lord has provided a water stream under you;', 'Then he called her from beneath her: “Do not grieve; your Lord has placed a stream beneath you.'),
(2275, 19, 25, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ ہُزِّیۡۤ  اِلَیۡکِ بِجِذۡعِ النَّخۡلَۃِ  تُسٰقِطۡ عَلَیۡکِ  رُطَبًا جَنِیًّا ﴿۫۲۵﴾', 'اور کھجور کے تنے کو پکڑ کر اپنی طرف ہلاؤ وہ تم پر تازہ عمدہ کھجوریں گرائے گا۔', 'اور ہلا اپنی طرف کھجور کی جڑ  اُس سے گریں گی تجھ پر پکی کھجوریں [۲۹]', '\"And shake the trunk of date-palm towards you, it will let fall fresh ripe-dates upon you.\"', 'Shake the trunk of the palm-tree towards yourself and, it will drop upon you ripe fresh dates.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(2276, 19, 26, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'فَکُلِیۡ وَ اشۡرَبِیۡ وَ قَرِّیۡ عَیۡنًا ۚ فَاِمَّا تَرَیِنَّ مِنَ الۡبَشَرِ اَحَدًا ۙ فَقُوۡلِیۡۤ  اِنِّیۡ نَذَرۡتُ لِلرَّحۡمٰنِ صَوۡمًا فَلَنۡ اُکَلِّمَ الۡیَوۡمَ  اِنۡسِیًّا ﴿ۚ۲۶﴾', 'تو کھاؤ اور پیو اور آنکھیں ٹھنڈی کرو۔ اگر تم کسی آدمی کو دیکھو تو کہنا کہ میں نے اللہ کے لئے روزے کی منت مانی تو آج میں کسی آدمی سے ہرگز گلام نہیں کروں گی۔', 'اب کھا اور پی اور آنکھ ٹھنڈی رکھ [۳۰] پھر اگر تو دیکھے کوئی آدمی تو کہیو میں نے مانا ہے رحمٰن کا روزہ سو بات نہ کروں گی آج کسی آدمی سے [۳۱]', '\"So eat and drink and be glad, and if you see any human being, say: Verily! I have vowed a fast unto the Most Beneficent (Allah) so I shall not speak to any human being this day.\"', 'So eat, drink and cool your eyes. Then if you see any human being, say (to him), “I have vowed a fast (of silence) for the All-Merciful (Allah,) and therefore, I shall never speak to any human today.”'),
(2277, 19, 27, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'فَاَتَتۡ بِہٖ  قَوۡمَہَا تَحۡمِلُہٗ ؕ قَالُوۡا  یٰمَرۡیَمُ لَقَدۡ جِئۡتِ  شَیۡئًا فَرِیًّا ﴿۲۷﴾', 'پھر وہ اس بچے کو اٹھا کر اپنی برادری والوں کے پاس لے آئیں۔ وہ کہنے لگے کہ مریم یہ تو تو نے برا کام کیا۔', 'پھر لائی اسکو اپنے لوگوں کے پاس گود میں وہ اُسکو کہنے لگے اے مریم تو نے کی یہ چیز طوفان کی [۳۲]', 'Then she brought him (the baby) to her people, carrying him. They said: \"O Mary! Indeed you have brought a thing Fariya (an unheard mighty thing).', 'Then she came to her people carrying him (the baby). They said, “O Maryam you have committed something grave indeed.'),
(2278, 19, 28, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'یٰۤاُخۡتَ ہٰرُوۡنَ مَا کَانَ  اَبُوۡکِ امۡرَ اَ سَوۡءٍ وَّ مَا  کَانَتۡ  اُمُّکِ  بَغِیًّا ﴿ۖۚ۲۸﴾', 'اے ہارون کی بہن نہ تو تیرا باپ ہی برا آدمی تھا اور نہ تیری ماں ہی بدکار تھی۔', 'اے بہن ہارون کی نہ تھا تیرا باپ برا آدمی اور نہ تھی تیری ماں بدکار [۳۳]', '\"O sister (i.e. the like) of Haroon (Aaron) (not the brother of Moosa (Moses), but he was another pious man at the time of Maryam (Mary))! Your father was not a man who used to commit adultery, nor your mother was an unchaste woman.\"', 'O sister of Hārūn, neither your father was a man of evil nor was your mother unchaste.”'),
(2279, 19, 29, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'فَاَشَارَتۡ اِلَیۡہِ ؕ قَالُوۡا کَیۡفَ نُکَلِّمُ مَنۡ  کَانَ فِی  الۡمَہۡدِ  صَبِیًّا ﴿۲۹﴾', 'تو مریم نے اس بچے کی طرف اشارہ کیا۔ وہ بولے کہ ہم اس سے کہ گود کا بچہ ہے کیسے بات کریں۔', 'پھر ہاتھ سے بتلایا اُس لڑکے کو [۳۴] بولے ہم کیونکر بات کریں اُس شخص سے کہ وہ ہے گود میں لڑکا [۳۵]', 'Then she pointed to him. They said: \"How can we talk to one who is a child in the cradle?\"', 'So, she pointed towards him (the baby). They said, “How shall we speak to someone who is still a child in the cradle?”'),
(2280, 19, 30, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'قَالَ اِنِّیۡ عَبۡدُ اللّٰہِ ۟ؕ اٰتٰنِیَ الۡکِتٰبَ وَ جَعَلَنِیۡ  نَبِیًّا ﴿ۙ۳۰﴾', 'بچے نے کہا کہ میں اللہ کا بندہ ہوں اس نے مجھے کتاب دی ہے اور نبی بنایا ہے۔', 'وہ بولا میں بندہ ہوں اللہ کا مجھ کو اُس نے کتاب دی ہے اور مجھ کو اُس نے نبی کیا [۳۶]', '\"He (Iesa (Jesus)) said: Verily! I am a slave of Allah, He has given me the Scripture and made me a Prophet;\"', 'Spoke he (the baby), “Verily I am the servant of Allah. He has given me the Book, and made me a prophet,'),
(2281, 19, 31, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَّ جَعَلَنِیۡ مُبٰرَکًا اَیۡنَ مَا کُنۡتُ ۪ وَ اَوۡصٰنِیۡ بِالصَّلٰوۃِ  وَ الزَّکٰوۃِ مَا دُمۡتُ  حَیًّا ﴿۪ۖ۳۱﴾', 'اور میں جہاں ہوں اور جس حال میں ہوں اس نے مجھے صاحب برکت بنایا ہے اور جب تک زندہ ہوں مجھ کو نماز اور زکوٰۃ کا ارشاد فرمایا ہے۔', 'اور بنایا مجھ کو برکت والا جس جگہ میں ہوں اور تاکید کی مجھ کو نماز کی اور زکوٰۃ کی جب تک میں رہوں زندہ [۳۷]', '\"And He has made me blessed wheresoever I be, and has enjoined on me Salat (prayer), and Zakat, as long as I live.\"', 'and He has made me a blessed one wherever I be, and has enjoined Salāh and Zakāh upon me as long as I am alive,'),
(2282, 19, 32, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَّ بَرًّۢا بِوَالِدَتِیۡ ۫ وَ لَمۡ  یَجۡعَلۡنِیۡ جَبَّارًا شَقِیًّا ﴿۳۲﴾', 'اور مجھے اپنی ماں کے ساتھ نیک سلوک کرنے والا بنایا ہے اور سرکش و بدبخت نہیں بنایا۔', 'اورسلوک کرنے والا اپنی ماں سے [۳۸] اور نہیں بنایا مجھ کو زبردست بدبخت [۳۹]', '\"And dutiful to my mother, and made me not arrogant, unblest.', 'and (He has made me) good to my mother, and he did not make me oppressive (or) ill-fated.'),
(2283, 19, 33, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ السَّلٰمُ عَلَیَّ یَوۡمَ وُلِدۡتُّ وَ یَوۡمَ اَمُوۡتُ  وَ  یَوۡمَ  اُبۡعَثُ  حَیًّا ﴿۳۳﴾', 'اور جس دن میں پیدا ہوا اور جس دن مروں گا اور جس دن زندہ کر کے اٹھایا جاؤں گا مجھ پر سلام ہے۔', 'اور سلام ہے مجھ پر جس دن میں پیدا ہوا اور جس دن مروں اور جس دن اٹھ کھڑا ہوں زندہ ہو کر [۴۰]', '\"And Salam (peace) be upon me the day I was born, and the day I die, and the day I shall be raised alive!\"', 'And peace is upon me the day I was born, the day I shall die, and the day I shall be raised alive again.”'),
(2284, 19, 34, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'ذٰلِکَ عِیۡسَی ابۡنُ مَرۡیَمَ ۚ قَوۡلَ الۡحَقِّ الَّذِیۡ  فِیۡہِ  یَمۡتَرُوۡنَ ﴿۳۴﴾', 'یہ مریم کے بیٹے عیسٰی ہیں اور یہ سچی بات ہے جس میں لوگ شک کرتے ہیں۔', 'یہ ہے عیسٰی مریم کا بیٹا سچی بات جس میں لوگ جھگڑتے ہیں [۴۱]', 'Such is Iesa (Jesus), son of Maryam (Mary). (it is) a statement of truth, about which they doubt (or dispute).', 'That is ‘Īsā, the son of Maryam, to say the truth in which they (Christians) are disputing.'),
(2285, 19, 35, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'مَا کَانَ لِلّٰہِ اَنۡ یَّتَّخِذَ مِنۡ  وَّلَدٍ ۙ سُبۡحٰنَہٗ ؕ اِذَا  قَضٰۤی اَمۡرًا فَاِنَّمَا یَقُوۡلُ لَہٗ  کُنۡ فَیَکُوۡنُ ﴿ؕ۳۵﴾', 'اللہ کو شایاں نہیں کہ کسی کو بیٹا بنائے وہ پاک ہے جب کسی چیز کا ارادہ کرتا ہے تو اس کو یہی کہتا ہے کہ ہو جا تو وہ ہو جاتی ہے۔', 'اللہ ایسا نہیں کہ رکھے اولاد وہ پاک ذات ہے جب ٹھہرا لیتا ہے کسی کام کا کرنا سو یہی کہتا ہے اسکو کہ ہو وہ ہو جاتا ہے [۴۲]', 'It befits not (the Majesty of) Allah that He should beget a son (this refers to the slander of Christians against Allah, by saying that Iesa (Jesus) is the son of Allah). Glorified (and Exalted be He above all that they associate with Him). When He decrees a thing, He only says to it, \"Be!\" and it is.', 'It is not for Allah to have a son. Pure is He. When He decides a thing, He simply says to it, “Be” and it comes to be.'),
(2286, 19, 36, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ اِنَّ اللّٰہَ رَبِّیۡ وَ رَبُّکُمۡ فَاعۡبُدُوۡہُ ؕ ہٰذَا صِرَاطٌ  مُّسۡتَقِیۡمٌ ﴿۳۶﴾', 'اور بیشک اللہ ہی میرا اور تمہارا پروردگار ہے تو اسی کی عبادت کرو یہی سیدھا رستہ ہے۔', 'اور کہا بیشک اللہ ہے رب میرا اور  رب تمہارا سو اُسکی بندگی کرو  یہ  ہے راہ سیدھی', '(Iesa (Jesus) said): \"And verily Allah is my Lord and your Lord. So worship Him (Alone). That is the Straight Path. (Allahs Religion of Islamic Monotheism which He did ordain for all of His Prophets).\" (Tafsir At-Tabaree)', 'And (O Prophet, say to the people,) “Allah is surely my Lord and your Lord. So, worship Him. This is the straight path.”'),
(2287, 19, 37, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'فَاخۡتَلَفَ الۡاَحۡزَابُ مِنۡۢ بَیۡنِہِمۡ ۚ فَوَیۡلٌ لِّلَّذِیۡنَ  کَفَرُوۡا مِنۡ مَّشۡہَدِ یَوۡمٍ عَظِیۡمٍ ﴿۳۷﴾', 'پھر اہل کتاب کے فرقوں نے باہم اختلاف کیا۔ سو جو لوگ کافر ہوئے ہیں ان کو بڑے دن یعنی قیامت کے روز حاضر ہونے سے خرابی ہے۔', 'پھر جُدی جُدی راہ اختیار کی فرقوں نے اُن میں سے سو خرابی ہے منکروں کو جس وقت دیکھیں گے ایک دن بڑا [۴۳]', 'Then the sects differed (i.e. the Christians about Iesa (Jesus) ), so woe unto the disbelievers (those who gave false witness by saying that Iesa (Jesus) is the son of Allah) from the meeting of a great Day (i.e. the Day of Resurrection, when they will be thrown in the blazing Fire).', 'Then the groups among them fell in dispute. So, how evil is the fate of the disbelievers when they have to face the Great Day.'),
(2288, 19, 38, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'اَسۡمِعۡ بِہِمۡ وَ اَبۡصِرۡ ۙ یَوۡمَ یَاۡتُوۡنَنَا لٰکِنِ الظّٰلِمُوۡنَ الۡیَوۡمَ فِیۡ ضَلٰلٍ مُّبِیۡنٍ ﴿۳۸﴾', 'وہ جس دن ہمارے سامنے آئیں گے۔ کیسے سننے والے اور کیسے دیکھنے والے ہوں گے مگر ظالم آج کھلی گمراہی میں ہیں۔', 'کیا خوب سنتے اور دیکھتے ہونگے جس دن آئیں گے ہمارے پاس پر بے انصاف آج کے دن صریح بہک رہے ہیں [۴۴]', 'How clearly will they (polytheists and disbelievers in the Oneness of Allah) see and hear, the Day when they will appear before Us! But the Zalimoon (polytheists and wrong-doers) today are in plain error.', 'How strong will their hearing be, and how strong their vision, the day they will come to Us! But today the transgressors are straying in clear error.'),
(2289, 19, 39, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ اَنۡذِرۡہُمۡ  یَوۡمَ  الۡحَسۡرَۃِ  اِذۡ  قُضِیَ الۡاَمۡرُ ۘ وَ  ہُمۡ   فِیۡ غَفۡلَۃٍ   وَّ  ہُمۡ  لَا  یُؤۡمِنُوۡنَ ﴿۳۹﴾', 'اور انکو حسرت اور افسوس کے دن سے ڈرا دو جب بات فیصل کر دی جائے گی اور وہ غفلت میں پڑے ہوئے ہیں اور ایمان نہیں لاتے۔', 'اور ڈر سنا دے اُنکو اُس پچتاوے کے دن کا  جب فیصل ہو چکے گا کام [۴۵] اور وہ بھول رہے ہیں اور وہ یقین نہیں لاتے [۴۶]', 'And warn them (O Muhammad SAW) of the Day of grief and regrets, when the case has been decided, while (now) they are in a state of carelessness, and they believe not.', 'Warn them of The Day of Remorse when the whole thing will be settled, while they are heedless and do not believe.'),
(2290, 19, 40, 2, 5, 16, 'قَالَ اَلَمۡ', 'مریم', 'اِنَّا نَحۡنُ نَرِثُ الۡاَرۡضَ وَ مَنۡ عَلَیۡہَا وَ اِلَیۡنَا یُرۡجَعُوۡنَ ﴿٪۴۰﴾', 'ہم ہی زمین کے اور جو لوگ اس پر بستے ہیں ان کے وارث ہونگے۔ اور ہماری ہی طرف انکو لوٹنا ہو گا۔', 'ہم وارث ہوں گے زمین کے اور جو کوئی ہے زمین پر اور وہ ہماری طرف پھر آئیں گے [۴۷]', 'Verily! We will inherit the earth and whatsoever is thereon. And to Us they all shall be returned,', 'Surely We, only We, shall be the ultimate owner of the earth and all those on it, and to Us they will be returned.'),
(2291, 19, 41, 3, 6, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ اذۡکُرۡ  فِی الۡکِتٰبِ اِبۡرٰہِیۡمَ ۬ؕ اِنَّہٗ  کَانَ صِدِّیۡقًا  نَّبِیًّا ﴿۴۱﴾', 'اور کتاب میں ابراہیم کا ذکر کرو بیشک وہ نہایت سچے تھے پیغمبر تھے۔', 'اور مذکور کر کتاب میں ابراہیم کا [۴۸] بیشک تھا وہ سچا نبی [۴۹]', 'And mention in the Book (the Quran) Ibrahim (Abraham). Verily! He was a man of truth, a Prophet.', 'And mention in the Book (the story of) Ibrāhīm. Indeed, he was Siddīq (a man of truth), a prophet,'),
(2292, 19, 42, 3, 6, 16, 'قَالَ اَلَمۡ', 'مریم', 'اِذۡ  قَالَ لِاَبِیۡہِ یٰۤاَبَتِ لِمَ تَعۡبُدُ مَا لَا یَسۡمَعُ وَ لَا یُبۡصِرُ وَ لَا یُغۡنِیۡ عَنۡکَ شَیۡئًا ﴿۴۲﴾', 'جب انہوں نے اپنے باپ سے کہا کہ ابا آپ ایسی چیزوں کو کیوں پوجتے ہیں جو نہ سنیں اور نہ دیکھیں اور نہ آپ کے کچھ کام آسکیں۔', 'جب کہا اپنے باپ کو اے باپ میرے کیوں پوجتا ہے اسکو جو نہ سنے اور نہ دیکھے اور نہ کام آئے تیرے کچھ [۵۰]', 'When he said to his father: \"O my father! Why do you worship that which hears not, sees not and cannot avail you in anything?', 'when he said to his father, “My dear father, why do you worship something that does neither hear nor see, nor help you in any way?'),
(2293, 19, 43, 3, 6, 16, 'قَالَ اَلَمۡ', 'مریم', 'یٰۤاَبَتِ اِنِّیۡ قَدۡ جَآءَنِیۡ مِنَ الۡعِلۡمِ  مَا لَمۡ یَاۡتِکَ فَاتَّبِعۡنِیۡۤ  اَہۡدِکَ صِرَاطًا سَوِیًّا ﴿۴۳﴾', 'ابا مجھے ایسا علم ملا ہے جو آپ کو نہیں ملا تو میرے ساتھ ہو جائیے میں آپ کو سیدھی راہ پر لے چلوں گا۔', 'اے باپ میرے مجھ کو آئی ہے خبر ایک چیز کی جو تجھ کو نہیں آئی سو میری راہ چل دکھلا دوں تجھ کو راہ سیدھی [۵۱]', '\"O my father! Verily! There has come to me of knowledge that which came not unto you. So follow me. I will guide you to a Straight Path.', 'My dear father, indeed there has come to me a knowledge that has not come to you; so, follow me, and I shall lead you to a straight path.'),
(2294, 19, 44, 3, 6, 16, 'قَالَ اَلَمۡ', 'مریم', 'یٰۤاَبَتِ لَا تَعۡبُدِ الشَّیۡطٰنَ ؕ اِنَّ الشَّیۡطٰنَ  کَانَ  لِلرَّحۡمٰنِ عَصِیًّا ﴿۴۴﴾', 'ابا شیطان کی پوجا نہ کیجئے بیشک شیطان اللہ کا نافرمان ہے۔', 'اے باپ میرے مت پوج شیطان کو بیشک شیطان ہے رحمٰن کا نافرمان [۵۲]', '\"O my father! Worship not Shaitan (Satan). Verily! Shaitan (Satan) has been a rebel against the Most Beneficent (Allah).', 'My dear father, do not worship the Satan. The Satan is surely rebellious to the All-Merciful, (Allah).'),
(2295, 19, 45, 3, 6, 16, 'قَالَ اَلَمۡ', 'مریم', 'یٰۤاَبَتِ اِنِّیۡۤ  اَخَافُ اَنۡ یَّمَسَّکَ عَذَابٌ مِّنَ الرَّحۡمٰنِ فَتَکُوۡنَ لِلشَّیۡطٰنِ وَلِیًّا ﴿۴۵﴾', 'ابا مجھے ڈر لگتا ہے کہ آپ کو اللہ کا عذاب آ پکڑے تو آپ شیطان کے ساتھی ہو جائیں۔', 'اے باپ میرے میں ڈرتا ہوں کہیں آ لگے تجھ کو ایک آفت رحمٰن سے پھر تو ہو جائے شیطان کا ساتھی [۵۳]', '\"O my father! Verily! I fear lest a torment from the Most Beneficent (Allah) overtake you, so that you become a companion of Shaitan (Satan) (in the Hell-fire).\" (Tafsir Al-Qurtubee)', 'My dear father, I fear lest a punishment from the All- Merciful (Allah) should afflict you, and you become a companion of Satan.”'),
(2296, 19, 46, 3, 6, 16, 'قَالَ اَلَمۡ', 'مریم', 'قَالَ  اَرَاغِبٌ اَنۡتَ عَنۡ  اٰلِہَتِیۡ یٰۤـاِبۡرٰہِیۡمُ ۚ لَئِنۡ لَّمۡ تَنۡتَہِ لَاَرۡجُمَنَّکَ وَ اہۡجُرۡنِیۡ  مَلِیًّا ﴿۴۶﴾', 'اس نے کہا کہ ابراہیم! کیا تو میرے معبودوں کے خلاف ہے؟ اگر تو باز نہ آئے گا تو میں تجھے سنگسار کر دوں گا۔ اور تو ہمیشہ کے لئے مجھ سے دور ہو جا۔', 'وہ بولا کیا تو پھرا ہوا ہے میرے ٹھاکروں سے اے ابراہیم اگر تو باز نہ آئے گا تو تجھ کو سنگسار کروں گا اور دور ہو جا میرے پاس سے ایک مدت [۵۴]', 'He (the father) said: \"Do you reject my gods, O Ibrahim (Abraham)? If you stop not (this), I will indeed stone you. So get away from me safely before I punish you.\"', 'He said, “Are you averse to my gods O Ibrāhīm? Should you not stop, I will definitely stone you. And leave me for good.”'),
(2297, 19, 47, 3, 6, 16, 'قَالَ اَلَمۡ', 'مریم', 'قَالَ سَلٰمٌ  عَلَیۡکَ ۚ سَاَسۡتَغۡفِرُ  لَکَ  رَبِّیۡ ؕ اِنَّہٗ  کَانَ  بِیۡ  حَفِیًّا ﴿۴۷﴾', 'ابراہیم نے سلام علیکم کہا اور کہا کہ میں آپ کے لئے اپنے پروردگار سے بخشش مانگوں گا۔ بیشک وہ مجھ پر نہایت مہربان ہے۔', 'کہا تیری سلامتی رہے [۵۵] میں گناہ بخشواؤں گا تیرا اپنے رب سے بیشک وہ ہے مجھ پر مہربان [۵۶]', 'Ibrahim (Abraham) said: \"Peace be on you! I will ask Forgiveness of my Lord for you. Verily! He is unto me, Ever Most Gracious.', 'He said, “Peace on you. I shall seek forgiveness for you from my Lord. He has always been gracious to me.'),
(2298, 19, 48, 3, 6, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ اَعۡتَزِلُکُمۡ وَ مَا تَدۡعُوۡنَ مِنۡ دُوۡنِ اللّٰہِ  وَ اَدۡعُوۡا  رَبِّیۡ ۫ۖ عَسٰۤی اَلَّاۤ  اَکُوۡنَ  بِدُعَآءِ   رَبِّیۡ  شَقِیًّا ﴿۴۸﴾', 'اور میں آپ لوگوں سے اور جنکو آپ اللہ کے سوا پکارا کرتے ہیں ان سے کنارہ کرتا ہوں اور اپنے پروردگار ہی کو پکاروں گا امید ہے کہ میں اپنے پروردگار کو پکار کر محروم نہیں رہوں گا۔', 'اور چھوڑتا ہوں تم کو اور جنکو تم پوجتے ہو اللہ کے سوا اور میں بندگی کروں گا اپنے ر ب کی امید ہے کہ نہ رہوں گا اپنے رب کی بندگی کر کر محروم [۵۷]', '\"And I shall turn away from you and from those whom you invoke besides Allah. And I shall call on my Lord; and I hope that I shall not be unblest in my invocation to my Lord.\"', 'And I go away from you and what you invoke besides Allah. And I shall invoke my Lord. Hopefully I shall not be a looser by invoking my Lord.”'),
(2299, 19, 49, 3, 6, 16, 'قَالَ اَلَمۡ', 'مریم', 'فَلَمَّا اعۡتَزَلَہُمۡ وَ مَا یَعۡبُدُوۡنَ مِنۡ دُوۡنِ اللّٰہِ ۙ وَہَبۡنَا لَہٗۤ  اِسۡحٰقَ  وَ  یَعۡقُوۡبَ ؕ وَ کُلًّا  جَعَلۡنَا  نَبِیًّا ﴿۴۹﴾', 'اور جب ابراہیم ان لوگوں سے اور جنکی وہ اللہ کے سوا پرستش کرتے تھے الگ ہو گئے تو ہم نے انکو اسحٰق اور اسحٰق کو یعقوب بخشے اور ہر ایک کو پیغمبر بنایا۔', 'پھر جب جُدا ہوا اُن سے اور جنکو وہ پوجتے تھے اللہ کے سوا بخشا ہم نے اُسکو اسحٰق او ریعقوب اور دونوں کو نبی کیا [۵۸]', 'So when he had turned away from them and from those whom they worshipped besides Allah, We gave him Ishaque (Isaac) and Yaqoob (Jacob), and each one of them We made a Prophet.', 'So, when he went away from them and what they worshipped besides Allah, We blessed him with IsHāq (Isaac) and Ya‘qūb (Jacob) and We made each one of them a prophet,'),
(2300, 19, 50, 3, 6, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ وَہَبۡنَا لَہُمۡ مِّنۡ رَّحۡمَتِنَا وَ جَعَلۡنَا لَہُمۡ  لِسَانَ  صِدۡقٍ  عَلِیًّا ﴿٪۵۰﴾', 'اور ہم نے انکو اپنی رحمت سے بہت سی چیزیں عنایت کیں۔ اور انکا ذکر جمیل بلند کیا۔', 'اور دیا ہم نے انکو اپنی رحمت سے اور کہا اُنکے واسطے سچا بول اونچا [۵۹]', 'And We gave them of Our Mercy (a good provision in plenty), and We granted them honour on the tongues (of all the nations, i.e everybody remembers them with a good praise).', 'and We bestowed on them (a great deal) of our mercy, and caused them to have a good name at a high level.'),
(2301, 19, 51, 4, 7, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ اذۡکُرۡ فِی الۡکِتٰبِ مُوۡسٰۤی ۫ اِنَّہٗ  کَانَ مُخۡلَصًا وَّ کَانَ رَسُوۡلًا  نَّبِیًّا ﴿۵۱﴾', 'اور کتاب میں موسٰی کا بھی ذکر کرو بیشک وہ ہمارے برگزیدہ تھے اور رسول تھے نبی تھے۔', 'اور مذکور کر کتاب میں موسٰی کا [۶۰] بیشک وہ تھا چنا ہوا اور تھا رسول نبی [۶۱]', 'And mention in the Book (this Quran) Moosa (Moses). Verily! He was chosen and he was a Messenger (and) a Prophet.', 'And mention in the Book (the story of) Mūsā. Indeed he was a chosen one and was a messenger, a prophet.'),
(2302, 19, 52, 4, 7, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ نَادَیۡنٰہُ مِنۡ جَانِبِ الطُّوۡرِ الۡاَیۡمَنِ  وَ قَرَّبۡنٰہُ  نَجِیًّا ﴿۵۲﴾', 'اور ہم نے انکو طور کی داہنی طرف سے پکارا اور باتیں کرنے کے لئے نزدیک بلایا۔', 'اور پکارا ہم نے اُسکو داہنی طرف سے طور پہاڑ کی اور نزدیک بلایا اُسکو بھید کہنے کو [۶۲]', 'And We called him from the right side of the Mount, and made him draw near to Us for a talk with him (Moosa (Moses)).', 'And We called him from the right side of the mount Tūr (Sinai), and We brought him close to communicate in secret.'),
(2303, 19, 53, 4, 7, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ وَہَبۡنَا لَہٗ  مِنۡ رَّحۡمَتِنَاۤ  اَخَاہُ ہٰرُوۡنَ نَبِیًّا ﴿۵۳﴾', 'اور اپنی مہربانی سے انکو ان کا بھائی ہارون پیغمبر بنا کر عطا کیا۔', 'اور بخشا ہم نے اُسکو اپنی مہربانی سے بھائی اُس کا ہارون نبی [۶۳]', 'And We bestowed on him his brother Haroon (Aaron), (also) a Prophet, out of Our Mercy.', 'And, out of Our mercy, We granted him his brother Hārūn as a prophet.'),
(2304, 19, 54, 4, 7, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ اذۡکُرۡ فِی الۡکِتٰبِ اِسۡمٰعِیۡلَ ۫ اِنَّہٗ کَانَ صَادِقَ الۡوَعۡدِ وَ کَانَ رَسُوۡلًا نَّبِیًّا  ﴿ۚ۵۴﴾', 'اور کتاب میں اسمٰعیل کا بھی ذکر کرو وہ وعدے کے سچے اور رسول تھے نبی تھے۔', 'اور مذکور کر کتاب میں اسمٰعیل کا وہ تھا وعدہ کا سچا اور تھا رسول نبی [۶۴]', 'And mention in the Book (the Quran) Ismail (Ishmael). Verily! He was true to what he promised, and he was a Messenger, (and) a Prophet.', 'And mention in the Book (the story of) Ismā‘īl. He was indeed true to his promise, and was a messenger, a prophet.'),
(2305, 19, 55, 4, 7, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ کَانَ یَاۡمُرُ اَہۡلَہٗ  بِالصَّلٰوۃِ  وَ الزَّکٰوۃِ ۪ وَ کَانَ عِنۡدَ رَبِّہٖ  مَرۡضِیًّا ﴿۵۵﴾', 'اور وہ اپنے گھر والوں کو نماز اور زکوٰۃ کا حکم کرتے تھے اور اپنے پروردگار کے ہاں پسندیدہ تھے۔', 'اور حکم کرتا تھا اپنے گھر والوں کو نماز کا اور زکوٰۃ کا [۶۵] اور تھا اپنے رب کے یہاں پسندیدہ [۶۶]', 'And he used to enjoin on his family and his people As-Salat (the prayers) and the Zakat, and his Lord was pleased with him.', 'He used to enjoin Salāh and Zakāh upon his family, and was favourite to his Lord.'),
(2306, 19, 56, 4, 7, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ اذۡکُرۡ فِی  الۡکِتٰبِ  اِدۡرِیۡسَ ۫ اِنَّہٗ  کَانَ  صِدِّیۡقًا  نَّبِیًّا ﴿٭ۙ۵۶﴾', 'اور کتاب میں ادریس کا بھی ذکر کرو۔ وہ بھی نہایت سچے تھے نبی تھے۔', 'اور مذکور کر کتاب میں ادریس کا وہ تھا سچا نبی [۶۷]', 'And mention in the Book (the Quran) Idris (Enoch).Verily! He was a man of truth, (and) a Prophet.', 'And mention in the Book (the story of) Idrīs. He was indeed a Siddīq (man of truth), a prophet.'),
(2307, 19, 57, 4, 7, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَّ رَفَعۡنٰہُ  مَکَانًا عَلِیًّا ﴿۵۷﴾', 'اور ہم نے انکو اونچی جگہ اٹھا لیا تھا۔', 'اور اٹھا لیا ہم نے اسکو ایک اونچے مکان پر [۶۸]', 'And We raised him to a high station.', 'We raised him to a high place.'),
(2308, 19, 58, 4, 7, 16, 'قَالَ اَلَمۡ', 'مریم', 'اُولٰٓئِکَ الَّذِیۡنَ اَنۡعَمَ اللّٰہُ عَلَیۡہِمۡ مِّنَ النَّبِیّٖنَ مِنۡ ذُرِّیَّۃِ  اٰدَمَ ٭ وَ مِمَّنۡ حَمَلۡنَا مَعَ نُوۡحٍ ۫ وَّ مِنۡ ذُرِّیَّۃِ  اِبۡرٰہِیۡمَ وَ اِسۡرَآءِیۡلَ ۫ وَ مِمَّنۡ ہَدَیۡنَا وَ اجۡتَبَیۡنَا ؕ اِذَا تُتۡلٰی عَلَیۡہِمۡ اٰیٰتُ الرَّحۡمٰنِ  خَرُّوۡا  سُجَّدًا  وَّ  بُکِیًّا ﴿ٛ۵۸﴾', 'یہ وہ لوگ ہیں جن پر اللہ نے اپنے پیغمبروں میں سے فضل کیا یعنی اولاد آدم میں سے اور ان لوگوں میں سے جنکو ہم نے نوح کے ساتھ کشتی میں سوار کیا اور ابراہیم اور یعقوب کی اولاد میں سے اور ان لوگوں میں سے جنکو ہم نے ہدایت دی اور جنہیں برگزیدہ کیا۔ جب ان کے سامنے ہماری آیتیں پڑھی جاتی تھیں تو سجدے میں گر پڑتے اور روتے رہتے تھے۔', 'یہ وہ لوگ ہیں جن پر انعام کیااللہ نے پیغمبروں میں آدم کی اولاد میں اور اُن میں جنکو سوار کر لیا ہم نے نوح کے ساتھ اور ابراہیم کی اولاد میں اور اسرائیل کی [۶۹] اور اُن میں جنکو ہم نے ہدایت کی اور  پسند کیا [۷۰] جب اُنکو سنائے آیتیں رحمٰن کی گرتے ہیں سجدہ میں اور روتے ہوئے [۷۱]', 'Those were they unto whom Allah bestowed His Grace from among the Prophets, of the offspring of Adam, and of those whom We carried (in the ship) with Nooh (Noah), and of the offspring of Ibrahim (Abraham) and Israel and from among those whom We guided and chose. When the Verses of the Most Beneficent (Allah) were recited unto them, they fell down prostrating and weeping.', 'Those are the people whom Allah has blessed with bounties, the prophets from the progeny of ’Ādam, and of those whom We caused to board (the Ark) along with NūH, and from the progeny of Ibrāhīm and Isrā’īl (Jacob), and from those whom We guided and selected. When the verses of The RaHmān (The All-Merciful) were recited before them, they used to fall down in Sajdah (prostration), while they were weeping.'),
(2309, 19, 59, 4, 7, 16, 'قَالَ اَلَمۡ', 'مریم', 'فَخَلَفَ مِنۡۢ بَعۡدِہِمۡ خَلۡفٌ اَضَاعُوا الصَّلٰوۃَ وَ اتَّبَعُوا الشَّہَوٰتِ فَسَوۡفَ یَلۡقَوۡنَ  غَیًّا ﴿ۙ۵۹﴾', 'پھر ان کے بعد چند ناخلف ان کے جانشین ہوئے جنہوں نے نماز کو ضائع کر دیا۔ اور خواہشات نفسانی کے پیچھے لگ گئے۔ سو عنقریب انکو گمراہی کی سزا ملے گی۔', 'پھر اُنکی جلگہ آئے ناخلف کھو بیٹھے نماز اور پیچھے پڑ گئے مزوں کے سو آگے دیکھ لیں گے گمراہی کو [۷۲]', 'Then, there has succeeded them a posterity who have given up As-Salat (the prayers) (i.e. made their Salat (prayers) to be lost, either by not offering them or by not offering them perfectly or by not offering them in their proper fixed times, etc.) and have followed lusts. So they will be thrown in Hell.', 'Then came after them the successors who neglected Salāh and followed (their selfish) desires. So they will soon face (the outcome of their) deviation,'),
(2310, 19, 60, 4, 7, 16, 'قَالَ اَلَمۡ', 'مریم', 'اِلَّا مَنۡ تَابَ وَ اٰمَنَ وَ عَمِلَ صَالِحًا فَاُولٰٓئِکَ یَدۡخُلُوۡنَ  الۡجَنَّۃَ  وَ لَا یُظۡلَمُوۡنَ  شَیۡئًا ﴿ۙ۶۰﴾', 'ہاں جس نے توبہ کی اور ایمان لایا اور عمل نیک کئے تو ایسے لوگ بہشت میں داخل ہوں گے اور انکا ذرا نقصان نہ کیا جائے گا۔', 'مگر جس نے توبہ کی اور یقین لایا اور کی نیکی سو وہ لوگ جائیں گے بہشت میں اور اُن کا حق ضائع نہ ہو گا کچھ [۷۳]', 'Except those who repent and believe (in the Oneness of Allah and His Messenger Muhammad SAW), and work righteousness. Such will enter Paradise and they will not be wronged in aught.', 'except those who repent and believe and do good deeds, and therefore they will enter the Paradise and will not be wronged at all.'),
(2311, 19, 61, 4, 7, 16, 'قَالَ اَلَمۡ', 'مریم', 'جَنّٰتِ عَدۡنِۣ الَّتِیۡ وَعَدَ الرَّحۡمٰنُ عِبَادَہٗ بِالۡغَیۡبِ ؕ اِنَّہٗ کَانَ وَعۡدُہٗ  مَاۡتِیًّا ﴿۶۱﴾', 'یعنی ہمیشہ کی بہشتوں میں جس کا اللہ نے اپنے بندوں سے وعدہ کیا ہے کہ جو انکی آنکھوں سے پوشیدہ ہے بیشک اس کا وعدہ نیکوکاروں کے سامنے آنے والا ہے۔', 'باغوں میں بسنے کے جن کا وعدہ کیا ہے رحمٰن نے اپنے بندوں سے اُنکے بن دیکھے بیشک ہے اُس کے وعدہ پر پہنچنا [۷۴]', '(They will enter) Adn (Eden) Paradise (everlasting Gardens), which the Most Beneficent (Allah) has promised to His slaves in the unseen: Verily! His Promise must come to pass.', '(They will enter) the Gardens of eternity, promised by the All-Merciful (Allah) to His servants, in the unseen world. They will surely reach (the places of) His promise.'),
(2312, 19, 62, 4, 7, 16, 'قَالَ اَلَمۡ', 'مریم', 'لَا یَسۡمَعُوۡنَ فِیۡہَا لَغۡوًا اِلَّا سَلٰمًا ؕ وَ لَہُمۡ  رِزۡقُہُمۡ  فِیۡہَا بُکۡرَۃً  وَّ عَشِیًّا ﴿۶۲﴾', 'وہ اس میں سلام کے سوا کوئی بیہودہ کلام نہ سنیں گے اور انکو صبح و شام کھانا ملے گا۔', 'نہ سنیں گے وہاں بک بک سوائے سلام [۷۵] اور اُنکے لئے ہے اُنکی روزی وہاں صبح اور شام [۷۶]', 'They shall not hear therein (in Paradise) any Laghw (dirty, false, evil vain talk), but only Salam (salutations of peace). And they will have therein their sustenance, morning and afternoon. (See (V.40:55)).', 'They will not hear anything absurd therein, but a word of peace, and there they will have their provision at morn and eve.'),
(2313, 19, 63, 4, 7, 16, 'قَالَ اَلَمۡ', 'مریم', 'تِلۡکَ الۡجَنَّۃُ الَّتِیۡ نُوۡرِثُ مِنۡ عِبَادِنَا مَنۡ  کَانَ  تَقِیًّا ﴿۶۳﴾', 'یہی وہ جنت ہے جس کا ہم اپنے بندوں میں سے ایسے شخص کو مالک بنائیں گے جو پرہیزگار ہو گا۔', 'یہ وہ بہشت ہے جو میراث دینگے ہم اپنے بندوں میں جو کوئی ہو گا پرہیزگار [۷۷]', 'Such is the Paradise which We shall give as an inheritance to those of Our slaves who have been Al-Muttaqoon (pious and righteous persons - See V.2:2).', 'That is the Paradise We will give as inheritance to those of Our servants who have been God-fearing.'),
(2314, 19, 64, 4, 7, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ مَا نَتَنَزَّلُ  اِلَّا بِاَمۡرِ رَبِّکَ ۚ لَہٗ مَا بَیۡنَ اَیۡدِیۡنَا وَ مَا خَلۡفَنَا وَ مَا بَیۡنَ ذٰلِکَ ۚ وَ مَا  کَانَ  رَبُّکَ  نَسِیًّا ﴿ۚ۶۴﴾', 'اور فرشتوں نے پیغمبر کو جواب دیا کہ ہم تمہارے پروردگار کے حکم کے سوا اتر نہیں سکتے جو کچھ ہمارے آگے ہے اور جو پیچھے ہے اور جو اسکے درمیان ہے سب اسی کا ہے اور تمہارا پروردگار بھولنے والا نہیں۔', 'اور ہم نہیں اترتے مگر حکم سے تیرے رب کے اُسی کا ہے جو ہمارے آگے ہے اور جو ہمارے پیچھے اور جو اسکے بیچ میں ہے اور تیرا رب نہیں ہے بھولنے والا [۷۸]', 'And we (angels) descend not except by the Command of your Lord (O Muhammad SAW). To Him belongs what is before us and what is behind us, and what is between those two, and your Lord is never forgetful,', '(Jibra’īl X said to the Holy Prophet) “We do not descend but with the command of your Lord. To Him belongs what is in front of us and what is behind us and what is in between; and your Lord is not the One who forgets.'),
(2315, 19, 65, 4, 7, 16, 'قَالَ اَلَمۡ', 'مریم', 'رَبُّ السَّمٰوٰتِ وَ الۡاَرۡضِ  وَ مَا بَیۡنَہُمَا فَاعۡبُدۡہُ وَ اصۡطَبِرۡ  لِعِبَادَتِہٖ ؕ ہَلۡ  تَعۡلَمُ  لَہٗ  سَمِیًّا ﴿٪۶۵﴾', 'یعنی آسمان اور زمین کا اور جو ان دونوں کے درمیان ہے سب کا پروردگار تو اسی کی عبادت کرو اور اسکی عبادت پر ثابت قدم رہو۔ بھلا تم کوئی اس کا ہم نام جانتے ہو۔', 'رب آسمانوں کا اور زمین کا اور جو اُنکے بیچ میں ہے سو اُسی کی بندگی کر اور قائم رہ اسکی بندگی پر [۷۹] کسی کو پہچانتا ہے تو اسکے نام کا [۸۰]', 'Lord of the heavens and the earth, and all that is between them, so worship Him (Alone) and be constant and patient in His worship. Do you know of any who is similar to Him? (of course none is similar or coequal or comparable to Him, and He has none as partner with Him). (There is nothing like unto Him and He is the All-Hearer, the All-Seer).', '(He is) the Lord of the heavens and the earth and whatever lies between them. So, worship Him and persevere in His worship. Do you know any one worthy of His name?”'),
(2316, 19, 66, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ یَقُوۡلُ الۡاِنۡسَانُ ءَ اِذَا مَا مِتُّ  لَسَوۡفَ اُخۡرَجُ  حَیًّا ﴿۶۶﴾', 'اور کافر انسان کہتا ہے کہ جب میں مر جاؤں گا تو کیا زندہ کر کے نکالا جاؤں گا؟', 'اور کہتا ہے آدمی کیا جب میں مر جاؤں تو پھر نکلوں گا زندہ ہو کر [۸۱]', 'And man (the disbeliever) says: \"When I am dead, shall I then be raised up alive?\"', 'Man says, “Is it that, once I die, I shall be brought forth alive?”'),
(2317, 19, 67, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'اَوَ لَا یَذۡکُرُ الۡاِنۡسَانُ اَنَّا خَلَقۡنٰہُ مِنۡ قَبۡلُ  وَ لَمۡ  یَکُ شَیۡئًا ﴿۶۷﴾', 'کیا ایسا انسان یاد نہیں کرتا کہ ہم نے اس کو پہلے بھی تو پیدا کیا تھا جبکہ وہ کچھ بھی چیز نہ تھا۔', 'کیا یاد نہیں رکھتا آدمی کہ ہم نے اسکو بنایا پہلے سے اور وہ کچھ چیز نہ تھا [۸۲]', 'Does not man remember that We created him before, while he was nothing?', 'Does not the man remember that We created him before, when he was nothing?'),
(2318, 19, 68, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'فَوَ رَبِّکَ لَنَحۡشُرَنَّہُمۡ وَ الشَّیٰطِیۡنَ ثُمَّ لَنُحۡضِرَنَّہُمۡ  حَوۡلَ  جَہَنَّمَ  جِثِیًّا ﴿ۚ۶۸﴾', 'سو تمہارے پروردگار کی قسم! ہم انکو جمع کریں گے اور شیطانوں کو بھی۔ پھر ان سب کو جہنم کے گرد حاضر کریں گے اور وہ گھٹنوں پر گرے ہوئے ہوں گے۔', 'سو قسم ہے تیرے رب کی ہم گھیر بلائیں گے  انکو اور شیطانوں کو [۸۳] پھر سامنے لائیں گے گرد دوزخ کے گھٹنوں پر گرے ہوئے [۸۴]', 'So by your Lord, surely, We shall gather them together, and (also) the Shayatin (devils) (with them), then We shall bring them round Hell on their knees.', 'So, by your Lord, We will definitely gather them together, and the devils as well; then We will definitely make them present around the Jahannam , fallen on their knees.'),
(2319, 19, 69, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'ثُمَّ  لَنَنۡزِعَنَّ مِنۡ کُلِّ  شِیۡعَۃٍ  اَیُّہُمۡ  اَشَدُّ عَلَی الرَّحۡمٰنِ عِتِیًّا ﴿ۚ۶۹﴾', 'پھر ہر گروہ میں سے ہم ایسے لوگوں کو کھینچ نکالیں گے جو رحمٰن کے مقابلے میں سخت سرکشی کرتے تھے۔', 'پھر جدا کر لیں گے ہم ہر ایک فرقہ میں سے جو نسا اُن میں سے سخت رکھتا تھا رحمٰن سے اکڑ', 'Then indeed We shall drag out from every sect all those who were worst in obstinate rebellion against the Most Beneficent (Allah).', 'Then, out of every group, We will certainly draw out those who were more rebellious against the All-Merciful (Allah).'),
(2320, 19, 70, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'ثُمَّ لَنَحۡنُ اَعۡلَمُ بِالَّذِیۡنَ ہُمۡ اَوۡلٰی بِہَا صِلِیًّا ﴿۷۰﴾', 'پھر ہم ان لوگوں سے خوب واقف ہیں جو اس میں داخل ہونے کے زیادہ لائق ہیں۔', 'پھر ہم کو خوب معلوم ہیں جو بہت قابل ہیں اُس میں داخل ہونے کے [۸۵]', 'Then, verily, We know best those who are most worthy of being burnt therein.', 'Then of course, We are most aware of those who are more deserving to enter it (the Jahannam ).'),
(2321, 19, 71, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ اِنۡ مِّنۡکُمۡ  اِلَّا وَارِدُہَا ۚ کَانَ عَلٰی رَبِّکَ حَتۡمًا مَّقۡضِیًّا ﴿ۚ۷۱﴾', 'اور تم میں سے کوئی شخص نہیں مگر اسے اس پر گذرنا ہو گا۔ یہ تمہارے پروردگار پر لازم ہے اور مقرر ہے۔', 'اور کوئی نہیں تم میں جو نہ پہنچے گا اس پر ہو چکا یہ وعدہ تیرے رب پر لازم مقرر', 'There is not one of you but will pass over it (Hell); this is with your Lord; a Decree which must be accomplished.', 'There is none among you who does not have to arrive at it. This is undertaken by your Lord as an absolute decree, bound to be enforced.'),
(2322, 19, 72, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'ثُمَّ نُنَجِّی الَّذِیۡنَ اتَّقَوۡا وَّ نَذَرُ الظّٰلِمِیۡنَ  فِیۡہَا جِثِیًّا ﴿۷۲﴾', 'پھر ہم پرہیزگاروں کو نجات دیں گے۔ اور ظالموں کو اس میں گھٹنوں کے بل پڑا ہوا چھوڑ دیں گے۔', 'پھر بچائیں گے ہم انکو  جو ڈرتے رہے اور چھوڑ دیں گے گنہگاروں کو اس میں اوندھے گرے ہوئے [۸۶]', 'Then We shall save those who use to fear Allah and were dutiful to Him. And We shall leave the Zalimoon (polytheists and wrongdoers, etc.) therein (humbled) to their knees (in Hell).', 'Then We will save those who feared Allah, and will leave the wrongdoers in it, fallen on their knees.'),
(2323, 19, 73, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ اِذَا تُتۡلٰی عَلَیۡہِمۡ اٰیٰتُنَا بَیِّنٰتٍ قَالَ الَّذِیۡنَ کَفَرُوۡا لِلَّذِیۡنَ اٰمَنُوۡۤا ۙ اَیُّ الۡفَرِیۡقَیۡنِ خَیۡرٌ  مَّقَامًا وَّ اَحۡسَنُ نَدِیًّا ﴿۷۳﴾', 'اور جب ان لوگوں کے سامنے ہماری آیتیں پڑھی جاتی ہیں تو جو کافر ہیں وہ مومنوں سے کہتے ہیں کہ دونوں فریق میں سے مکان کس کے اچھے اور مجلسیں کس کی بہتر ہیں؟', 'اور جب سنائے انکو ہماری آیتیں کھلی ہوئی کہتے ہیں جو لوگ کہ منکر  ہیں ایمان والوں کو دونوں فرقوں میں کس کا مکان بہتر ہے اور کس کی اچھی لگی ہے مجلس [۸۷]', 'And when Our Clear Verses are recited to them, those who disbelieve (the rich and strong among the pagans of Quraish who live a life of luxury) say to those who believe (the weak, poor companions of Prophet Muhammad SAW who have a hard life): \"Which of the two groups (i.e. believers and disbelievers) is best in (point of) position and as regards station (place of council for consultation).\"', 'When Our verses are recited to them in all their clarity, the disbelievers say to the believers, “Which of the two groups is superior in its place and better in its assembly?”'),
(2324, 19, 74, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ کَمۡ اَہۡلَکۡنَا قَبۡلَہُمۡ مِّنۡ قَرۡنٍ ہُمۡ اَحۡسَنُ  اَثَاثًا  وَّ رِءۡیًا ﴿۷۴﴾', 'اور ہم نے ان سے پہلے بہت سی امتیں ہلاک کر دیں۔ وہ لوگ ان سے ٹھاٹھ باٹھ اور نمود و نمائش میں کہیں اچھے تھے۔', 'اورکتنی ہلاک کر چکے ہیں ہم پہلے اُن سے جماعتیں وہ اُن سے بہتر تھے سامان میں اور نمود میں [۸۸]', 'And how many a generation (past nations) have We destroyed before them, who were better in wealth, goods and outward appearance?', 'How many a generation We have destroyed before them who were better in assets and outlook!'),
(2325, 19, 75, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'قُلۡ مَنۡ کَانَ فِی الضَّلٰلَۃِ  فَلۡیَمۡدُدۡ لَہُ الرَّحۡمٰنُ مَدًّا ۬ۚ حَتّٰۤی  اِذَا رَاَوۡا مَا یُوۡعَدُوۡنَ  اِمَّا  الۡعَذَابَ وَ اِمَّا السَّاعَۃَ ؕ فَسَیَعۡلَمُوۡنَ مَنۡ ہُوَ شَرٌّ مَّکَانًا  وَّ  اَضۡعَفُ  جُنۡدًا ﴿۷۵﴾', 'کہدو کہ جو شخص گمراہی میں پڑا ہوا ہے۔ رحمٰن اسکو آہستہ آہستہ مہلت دیئے جاتا ہے یہاں تک کہ جب اس چیز کو دیکھ لیں گے جس کا ان سے وعدہ کیا جاتا ہے خواہ عذاب اور خواہ قیامت تو اس وقت جان لیں گے کہ مکان کس کا برا ہے اور لشکر کس کا کمزور ہے۔', 'تو کہہ جو رہا بھٹکتا سو چاہئے اُسکو کھینچ لیجائے رحمٰن لنبا [۸۹] یہاں تک کہ جب دیکھیں گے جو وعدہ  ہوا تھا اُن سے یا آفت اور یا قیامت سو تب معلوم کر لیں گے کس کا برا ہے مکان اور کس کی فوج کمزور ہے [۹۰]', 'Say (O Muhammad SAW) whoever is in error, the Most Beneficent (Allah) will extend (the rope) to him, until, when they see that which they were promised, either the torment or the Hour, they will come to know who is worst in position, and who is weaker in forces. (This is the answer for the Verse No.19:73)', 'Say, “Whoever stays straying, let his term be extended by the All-Merciful (Allah) still longer, until when they will see what they are being warned of: either the punishment or the Hour (of Doom), then they will know who was worse in his place and weaker in his forces.'),
(2326, 19, 76, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ یَزِیۡدُ اللّٰہُ  الَّذِیۡنَ اہۡتَدَوۡا ہُدًی ؕ وَ الۡبٰقِیٰتُ الصّٰلِحٰتُ خَیۡرٌ عِنۡدَ رَبِّکَ ثَوَابًا وَّ  خَیۡرٌ  مَّرَدًّا ﴿۷۶﴾', 'اور جو لوگ ہدایت یاب ہیں اللہ انکو زیادہ ہدایت دیتا ہے اور نیکیاں جو باقی رہنے والی ہیں وہ تمہارے پروردگار کے ہاں صلے کے لحاظ سے خوب اور انجام کے اعتبار سے بہتر ہیں۔', 'اور بڑھاتا جاتا ہے اللہ سوجھنے والوں کو سوجھ [۹۱] اور باقی رہنے والی نیکیاں بہتر رکھتی ہیں تیرے رب کے یہاں بدلہ اور بہتر پھر جانے کو جگہ [۹۲]', 'And Allah increases in guidance those who walk aright (true believers in the Oneness of Allah who fear Allah much (abstain from all kinds of sins and evil deeds which He has forbidden), and love Allah much (perform all kinds of good deeds which He has ordained)). And the righteous good deeds that last, are better with your Lord, for reward and better for resort.', 'Allah makes those on the right path excel in guidance. And the everlasting virtues are better with your Lord in respect of reward and better in their return.'),
(2327, 19, 77, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'اَفَرَءَیۡتَ الَّذِیۡ کَفَرَ بِاٰیٰتِنَا وَ قَالَ لَاُوۡتَیَنَّ  مَالًا  وَّ  وَلَدًا ﴿ؕ۷۷﴾', 'بھلا تم نے اس شخص کو دیکھا جس نے ہماری آیتوں سے کفر کیا اور کہنے لگا کہ اگر میں ازسرنو زندہ ہوا بھی تو یہی مال اور اولاد مجھے وہاں ملے گا۔', 'بھلا تو نے دیکھا اُسکو جو منکر ہوا ہماری آیتوں سے اور کہا مجھ کو مل کر رہے گا مال اور اولاد [۹۳]', 'Have you seen him who disbelieved in Our Ayat (this Quran and Muhammad SAW) and (yet) says: \"I shall certainly be given wealth and children (if I will be alive (again)),\"', 'Have you, then, seen him who rejected Our verses and said, “I shall certainly be given wealth and children”?'),
(2328, 19, 78, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'اَطَّلَعَ  الۡغَیۡبَ اَمِ  اتَّخَذَ عِنۡدَ الرَّحۡمٰنِ  عَہۡدًا ﴿ۙ۷۸﴾', 'کیا اس نے غیب کی خبر پا لی ہے یا اللہ کے یہاں سے عہد لے لیا ہے؟', 'کیا جھانک آیا ہے غیب کو  یا لے رکھا ہے رحمٰن سے عہد [۹۴]', 'Has he known the unseen or has he taken a covenant from the Most Beneficent (Allah)?', 'Has he peeped into the Unseen or taken a covenant with the All-Merciful (Allah)?'),
(2329, 19, 79, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'کَلَّا ؕ سَنَکۡتُبُ مَا یَقُوۡلُ وَ نَمُدُّ  لَہٗ  مِنَ الۡعَذَابِ  مَدًّا ﴿ۙ۷۹﴾', 'ہر گز نہیں۔ یہ جو کچھ کہتا ہے ہم اس کو لکھتے جاتے اور اسکے لئے آہستہ آہستہ عذاب بڑھاتے جاتے ہیں۔', 'یہ نہیں ہم لکھ رکھیں گے جو وہ کہتا ہے اور بڑھاتے جائیں گے اسکو عذاب میں لنبا [۹۵]', 'Nay! We shall record what he says, and We shall increase his torment (in the Hell);', 'Never! We will write what he says and extend for him the punishment extensively.'),
(2330, 19, 80, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَّ  نَرِثُہٗ  مَا یَقُوۡلُ وَ یَاۡتِیۡنَا  فَرۡدًا ﴿۸۰﴾', 'اور جو چیزیں یہ بتاتا ہے انکے ہم وارث ہوں گے اور یہ اکیلا ہمارے سامنے آئے گا۔', 'اور ہم لے لیں گے اُسکے مرنے پر جو کچھ وہ بتلا رہا ہے اور آئے گا ہمارے پاس اکیلا [۹۶]', 'And We shall inherit from him (at his death) all that he talks of (i.e. wealth and children which We have bestowed upon him in this world), and he shall come to Us alone.', 'And We will inherit from him what he is talking about, and he will come to Us all alone.'),
(2331, 19, 81, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ اتَّخَذُوۡا مِنۡ دُوۡنِ اللّٰہِ اٰلِہَۃً  لِّیَکُوۡنُوۡا  لَہُمۡ  عِزًّا ﴿ۙ۸۱﴾', 'اور ان لوگوں نے اللہ کے سوا اور معبود بنا لئے ہیں تاکہ وہ ان کے لئے موجب عزت ہوں۔', 'اور پکڑ  رکھا ہے لوگوں نے اللہ کے سوا اوروں کو معبود تاکہ وہ ہوں اُنکے لئے مدد ہرگز نہیں [۹۷]', 'And they have taken (for worship) aliha (gods) besides Allah, that they might give them honour, power and glory (and also protect them from Allahs Punishment etc.).', 'They have taken gods other than Allah, so that they may be a source of might for them.'),
(2332, 19, 82, 5, 8, 16, 'قَالَ اَلَمۡ', 'مریم', 'کَلَّا ؕ سَیَکۡفُرُوۡنَ  بِعِبَادَتِہِمۡ وَ یَکُوۡنُوۡنَ  عَلَیۡہِمۡ  ضِدًّا ﴿٪۸۲﴾', 'ہرگز نہیں وہ معبود ان باطل انکی پرستش سے انکار کریں گے اور ان کے دشمن و مخالف ہوں گے۔', 'وہ منکر  ہونگے اُنکی بندگی سے اورہو جائیں گے اُنکے مخالف [۹۸]', 'Nay, but they (the so-called gods) will deny their worship of them, and become opponents to them (on the Day of Resurrection).', 'Never! They (their fabricated deities) will soon reject their having worshipped them, and they will be just the opposite for them.'),
(2333, 19, 83, 6, 9, 16, 'قَالَ اَلَمۡ', 'مریم', 'اَلَمۡ  تَرَ  اَنَّـاۤ  اَرۡسَلۡنَا الشَّیٰطِیۡنَ عَلَی الۡکٰفِرِیۡنَ  تَؤُزُّہُمۡ   اَزًّا ﴿ۙ۸۳﴾', 'کیا تم نے نہیں دیکھا کہ ہم نے شیطانوں کو کافروں پر چھوڑ رکھا ہے کہ وہ انکو خوب اکساتے رہتے ہیں۔', 'تو نے نہیں دیکھا کہ ہم نے چھوڑ رکھے ہیں شیطان منکروں پر اچھالتے ہیں انکو ابھار کر', 'See you not that We have sent the Shayatin (devils) against the disbelievers to push them to do evil.', 'Have you not seen that We have sent the devils onto the disbelievers inciting them with all their incitements.'),
(2334, 19, 84, 6, 9, 16, 'قَالَ اَلَمۡ', 'مریم', 'فَلَا  تَعۡجَلۡ عَلَیۡہِمۡ ؕ اِنَّمَا  نَعُدُّ  لَہُمۡ  عَدًّا ﴿ۚ۸۴﴾', 'تو تم ان پر عذاب کے لئے جلدی نہ کرو۔ کہ ہم تو ان کے لئے دن شمار کر رہے ہیں۔', 'سو تو جلدی نہ کر ان پرہم تو پوری کرتے ہیں انکی گنتی [۹۹]', 'So make no haste against them; We only count out to them a (limited) number (of the days of the life of this world and delay their term so that they may increase in evil and sins).', 'So make no hurry about them; We are but counting for them a count down.'),
(2335, 19, 85, 6, 9, 16, 'قَالَ اَلَمۡ', 'مریم', 'یَوۡمَ نَحۡشُرُ الۡمُتَّقِیۡنَ  اِلَی الرَّحۡمٰنِ وَفۡدًا ﴿ۙ۸۵﴾', 'جس روز ہم پرہیزگاروں کو رحمٰن کے سامنے بطور مہمان جمع کریں گے۔', 'جس دن ہم اکٹھا کرلائیں گے پرہیزگاروں کو رحمٰن کے پاس مہمان بلائے ہوئے', 'The Day We shall gather the Muttaqoon (pious - see V.2:2) unto the Most Beneficent (Allah), like a delegate (presented before a king for honour).', 'The day We will assemble the God-fearing before the All-Merciful (Allah) as guests,'),
(2336, 19, 86, 6, 9, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَّ نَسُوۡقُ الۡمُجۡرِمِیۡنَ اِلٰی جَہَنَّمَ وِرۡدًا ﴿ۘ۸۶﴾', 'اور گناہگاروں کو دوزخ کی طرف پیاسے ہانک لے جائیں گے۔', 'اور ہانک لیجائیں گے گنہگاروں کو دوزذخ کی طرف پیاس سے [۱۰۰]', 'And We shall drive the Mujrimoon (polytheists, sinners, criminals, disbelievers in the Oneness of Allah, etc.) to Hell, in a thirsty state (like a thirsty herd driven down to water),', 'and will drive the sinners towards the Jahannam as herds of cattle (are driven) towards water,'),
(2337, 19, 87, 6, 9, 16, 'قَالَ اَلَمۡ', 'مریم', 'لَا یَمۡلِکُوۡنَ الشَّفَاعَۃَ  اِلَّا مَنِ اتَّخَذَ عِنۡدَ  الرَّحۡمٰنِ  عَہۡدًا ﴿ۘ۸۷﴾', 'تو لوگ کسی کی سفارش کا اختیار نہ رکھیں گے مگر جس نے رحمٰن سے اقرار لے لیا ہو۔', 'نہیں اختیار رکھتے لوگ سفارش کا مگر جس نے لے لیا ہے رحمٰن سے وعدہ [۱۰۱]', 'None shall have the power of intercession, but such a one as has received permission (or promise) from the Most Beneficent (Allah).', 'none will have power to intercede, except the one who has entered into a covenant with the All-Merciful (Allah).'),
(2338, 19, 88, 6, 9, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ قَالُوا  اتَّخَذَ  الرَّحۡمٰنُ  وَلَدًا ﴿ؕ۸۸﴾', 'اور کہتے ہیں کہ رحمٰن بیٹا رکھتا ہے۔', 'اور لوگ کہتے ہیں رحمٰن رکھتا ہے اولاد [۱۰۲]', 'And they say: \"The Most Beneficent (Allah) has begotten a son (or offspring or children) (as the Jews say: Uzair (Ezra) is the son of Allah, and the Christians say that He has begotten a son (Iesa (Christ) ), and the pagan Arabs say that He has begotten daughters (angels, etc.)).\"', 'They say, “The All-Merciful (Allah) has got a son.”'),
(2339, 19, 89, 6, 9, 16, 'قَالَ اَلَمۡ', 'مریم', 'لَقَدۡ  جِئۡتُمۡ  شَیۡئًا  اِدًّا ﴿ۙ۸۹﴾', 'ایسا کہنے والو یہ تو تم بری بات زبان پر لاتے ہو۔', 'بیشک تم آ پھنسے ہو بھاری چیز میں', 'Indeed you have brought forth (said) a terrible evil thing.', 'Indeed you have come up with such an abominable statement'),
(2340, 19, 90, 6, 9, 16, 'قَالَ اَلَمۡ', 'مریم', 'تَکَادُ السَّمٰوٰتُ یَتَفَطَّرۡنَ مِنۡہُ وَ تَنۡشَقُّ الۡاَرۡضُ وَ تَخِرُّ الۡجِبَالُ ہَدًّا ﴿ۙ۹۰﴾', 'قریب ہے کہ اس جھوٹ سے آسمان پھٹ پڑیں اور زمین شق ہو جائے اور پہاڑ پارہ پارہ ہو کر گر پڑیں۔', 'ابھی آسمان پھٹ پڑیں اس بات سے اور ٹکڑے ہو زمیں اور گر پڑیں پہاڑ  ڈھے کر', 'Whereby the heavens are almost torn, and the earth is split asunder, and the mountains fall in ruins,', 'that the heavens are well-nigh to explode at it, and the earth to burst apart, and the mountains to fall down crumbling,'),
(2341, 19, 91, 6, 9, 16, 'قَالَ اَلَمۡ', 'مریم', 'اَنۡ  دَعَوۡا  لِلرَّحۡمٰنِ  وَلَدًا ﴿ۚ۹۱﴾', 'کہ انہوں نے رحمٰن کے لئے بیٹا تجویز کیا۔', 'اس پر کہ پکارتے ہیں رحمٰن کے نام پر اولاد [۱۰۳]', 'That they ascribe a son (or offspring or children) to the Most Beneficent (Allah).', 'for they have ascribed a son to the All-Merciful (Allah),'),
(2342, 19, 92, 6, 9, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ مَا یَنۡۢبَغِیۡ لِلرَّحۡمٰنِ اَنۡ  یَّتَّخِذَ  وَلَدًا ﴿ؕ۹۲﴾', 'اور رحمٰن کو شایاں نہیں کہ کسی کو بیٹا بنائے۔', 'اور نہیں پھبتا رحمٰن کو کہ رکھے اولاد [۱۰۴]', 'But it is not suitable for (the Majesty of) the Most Beneficent (Allah) that He should beget a son (or offspring or children).', 'while it does not behove the All-Merciful to have a son.'),
(2343, 19, 93, 6, 9, 16, 'قَالَ اَلَمۡ', 'مریم', 'اِنۡ کُلُّ مَنۡ فِی السَّمٰوٰتِ وَ الۡاَرۡضِ  اِلَّاۤ اٰتِی  الرَّحۡمٰنِ  عَبۡدًا ﴿ؕ۹۳﴾', 'ہر شخص جو آسمانوں اور زمین میں ہے رحمٰن کے روبرو بطور بندہ ہی آئے گا۔', 'کوئی نہیں آسمان اور زمین میں جو نہ آئے رحمٰن کا بندہ ہو کر [۱۰۵]', 'There is none in the heavens and the earth but comes unto the Most Beneficent (Allah) as a slave.', 'There is none in the heavens and the earth, but bound to come to the All-Merciful as a salve.'),
(2344, 19, 94, 6, 9, 16, 'قَالَ اَلَمۡ', 'مریم', 'لَقَدۡ  اَحۡصٰہُمۡ  وَ عَدَّہُمۡ  عَدًّا ﴿ؕ۹۴﴾', 'اس نے ان سب کو اپنے علم سے گھیر رکھا اور ایک ایک کو شمار کر رکھا ہے۔', 'اُسکے پاس اُنکی شمار ہے اور گن رکھی ہے انکی گنتی', 'Verily, He knows each one of them, and has counted them a full counting.', 'He has fully encompassed them and precisely calculated their numbers,'),
(2345, 19, 95, 6, 9, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ  کُلُّہُمۡ  اٰتِیۡہِ  یَوۡمَ الۡقِیٰمَۃِ   فَرۡدًا ﴿۹۵﴾', 'اور یہ سب قیامت کے دن اس کے سامنے اکیلے اکیلے حاضر ہوں گے۔', 'اور ہر ایک اُن میں آئے گا اُسکے سامنے قیامت کے دن اکیلا [۱۰۶]', 'And everyone of them will come to Him alone on the Day of Resurrection (without any helper, or protector or defender).', 'and each one of them is bound to come to Him on the Day of Judgment, all alone.'),
(2346, 19, 96, 6, 9, 16, 'قَالَ اَلَمۡ', 'مریم', 'اِنَّ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ سَیَجۡعَلُ  لَہُمُ  الرَّحۡمٰنُ  وُدًّا ﴿۹۶﴾', 'اور جو لوگ ایمان لائے اور عمل نیک کئے رحمٰن انکی محبت مخلوقات کے دل میں پیدا کر دے گا۔', 'البتہ جو یقین لائے ہیں اور کی ہیں اُنہوں نے نیکیاں اُنکو دے گا رحمٰن محبت [۱۰۷]', 'Verily, those who believe (in the Oneness of Allah and in His Messenger (Muhammad SAW)) and work deeds of righteousness, the Most Beneficent (Allah) will bestow love for them (in the hearts of the believers).', 'Surely, those who believe and do righteous deeds, for them the All-Merciful (Allah) will create love.'),
(2347, 19, 97, 6, 9, 16, 'قَالَ اَلَمۡ', 'مریم', 'فَاِنَّمَا یَسَّرۡنٰہُ بِلِسَانِکَ لِتُبَشِّرَ بِہِ الۡمُتَّقِیۡنَ  وَ  تُنۡذِرَ  بِہٖ  قَوۡمًا  لُّدًّا ﴿۹۷﴾', 'اے پیغمبر ﷺ ہم نے یہ قرآن تمہاری زبان میں آسان بنا کر  نازل کیا ہے تاکہ تم اس سے پرہیزگاروں کو خوشخبری پہنچا دو اور جھگڑالوؤں کو ڈر سنا دو۔', 'سو ہم نے آسان کر دیا یہ قرآن تیری زبان میں اسی واسطے کہ خوشخبری سنا دے تو ڈرنے والوں کو اور ڈرا دے جھگڑالو لوگوں کو [۱۰۸]', 'So We have made this (the Quran) easy in your own tongue (O Muhammad SAW), only that you may give glad tidings to the Muttaqoon (pious and righteous persons - See V.2:2), and warn with it the Ludda (most quarrelsome) people.', 'So We have made it (the Qur’ān) easy through your tongue, so that you give with it the good news to the God-fearing, and warn with it an obstinate people.'),
(2348, 19, 98, 6, 9, 16, 'قَالَ اَلَمۡ', 'مریم', 'وَ کَمۡ  اَہۡلَکۡنَا قَبۡلَہُمۡ مِّنۡ قَرۡنٍ ؕ ہَلۡ تُحِسُّ مِنۡہُمۡ مِّنۡ  اَحَدٍ اَوۡ تَسۡمَعُ لَہُمۡ رِکۡزًا ﴿٪۹۸﴾', 'اور ہم نے ان سے پہلے بہت سے گروہوں کو ہلاک کر دیا ہے بھلا تم ان میں سے کسی کو دیکھتے ہو یا کہیں انکی بھنک سنتے ہو۔', 'اور بہت ہلاک کر چکے ہم اُن سے پہلے جماعتیں آہٹ پاتا ہے تو اُن میں کسی کی یا سنتا ہے اُنکی بھنک [۱۰۹]', 'And how many a generation before them have We destroyed! Can you (O Muhammad SAW) find a single one of them or hear even a whisper of them?', 'And how many a generation We have destroyed before them! Do you sense (the presence of) any one of them, or hear from them even a whisper?'),
(2349, 20, 1, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'طٰہٰ ۚ﴿۱﴾', 'طٰہٰ۔', 'طٰہٰ۔', 'TaHa. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings.)', 'Tā-Hā'),
(2350, 20, 2, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'مَاۤ   اَنۡزَلۡنَا عَلَیۡکَ  الۡقُرۡاٰنَ  لِتَشۡقٰۤی ۙ﴿۲﴾', 'اے نبی ﷺ ہم نے تم پر قرآن اس لئے نازل نہیں کیا کہ تم مشقت میں پڑ جاؤ۔', 'اس واسطے نہیں اتارا ہم نے تجھ پر قرآن کہ تو محنت میں پڑے', 'We have not sent down the Quran unto you (O Muhammad SAW) to cause you distress,', 'We did not reveal the Qur’ān to you to (make you) face hardship'),
(2351, 20, 3, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اِلَّا  تَذۡکِرَۃً   لِّمَنۡ  یَّخۡشٰی  ۙ﴿۳﴾', 'مگر ہر اس شخص کی نصیحت کے لئے نازل کیا ہے جو خوف رکھتا ہے۔', 'مگر نصیحت کے واسطے اُسکی جو ڈرتا ہے [۱]', 'But only as a Reminder to those who fear (Allah).', 'rather to remind him who has the fear (of Allah),'),
(2352, 20, 4, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'تَنۡزِیۡلًا مِّمَّنۡ خَلَقَ الۡاَرۡضَ وَ السَّمٰوٰتِ الۡعُلٰی  ؕ﴿۴﴾', 'یہ اس ذات کا اتارا ہوا ہے جس نے زمین اور اونچے اونچے آسمان بنائے۔', 'اتارا ہوا ہے اُس کا جس نے بنائی زمین اور آسمان اونچے [۲]', 'A revelation from Him (Allah) Who has created the earth and high heavens.', 'it being a revelation from the One Who created the earth, and high heavens.'),
(2353, 20, 5, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اَلرَّحۡمٰنُ  عَلَی الۡعَرۡشِ  اسۡتَوٰی  ﴿۵﴾', 'یعنی رحمٰن جو عرش پر جلوہ افروز ہوا۔', 'وہ بڑا مہربان عرش پر قائم ہوا [۳]', 'The Most Beneficent (Allah) Istawa (rose over) the (Mighty) Throne (in a manner that suits His Majesty).', 'The RaHmān (Allah, the All-Merciful) has positioned Himself on the Throne.'),
(2354, 20, 6, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'لَہٗ مَا فِی السَّمٰوٰتِ  وَ مَا فِی الۡاَرۡضِ وَ مَا بَیۡنَہُمَا وَ مَا  تَحۡتَ الثَّرٰی  ﴿۶﴾', 'جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے اور جو کچھ ان دونوں کے بیچ میں ہے اور جو کچھ مٹی کے نیچے ہے سب اسی کا ہے۔', 'اُسی کاہے جو کچھ ہے آسمان اور زمین میں اور اُن دونوں کے درمیان اور نیچے گیلی زمین کے [۴]', 'To Him belongs all that is in the heavens and all that is on the earth, and all that is between them, and all that is under the soil.', 'To Him belongs all that is in the heavens, all that is in the earth and whatever lies between them and whatever lies beneath the soil.'),
(2355, 20, 7, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ اِنۡ تَجۡہَرۡ بِالۡقَوۡلِ فَاِنَّہٗ یَعۡلَمُ السِّرَّ وَ اَخۡفٰی  ﴿۷﴾', 'اور اگر تم پکار کر بات کہو تو کیا ہے وہ تو آہستہ کہی ہوئی اور نہایت پوشیدہ بات تک کو جانتا ہے۔', 'اور اگر تو بات کہے پکار کر تو اُسکو تو خبر ہے چھپی ہوئی بات کی اور اُس سے بھی چھپی ہوئی کی [۵]', 'And if you (O Muhammad SAW) speak (the invocation) aloud, then verily, He knows the secret and that which is yet more hidden.', 'If you pronounce the word aloud, then (it makes no difference, for) He certainly knows the secret and what is even more hidden.'),
(2356, 20, 8, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اَللّٰہُ  لَاۤ  اِلٰہَ  اِلَّا ہُوَ ؕ لَہُ  الۡاَسۡمَآءُ الۡحُسۡنٰی ﴿۸﴾', 'اللہ وہ معبود برحق ہے کہ اس کے سوا کوئی معبود نہیں ہے اس کے سب نام اچھے ہیں۔', 'اللہ ہے جسکے سوا بندگی نہیں کسی کی اُسی کے ہیں سب نام خاصے [۶]', 'Allah! La ilahla illa Huwa (none has the right to be worshipped but He)! To Him belong the Best Names.', '(Such is) Allah. There is no god but He. For Him are the Beautiful Names.'),
(2357, 20, 9, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ ہَلۡ  اَتٰىکَ  حَدِیۡثُ  مُوۡسٰی  ۘ﴿۹﴾', 'اور کیا تمہیں موسٰی کے حال کی خبر ملی ہے۔', 'اور پہنچی ہے تجھ کو  بات موسٰی کی [۷]', 'And has there come to you the story of Moosa (Moses)?', 'Has there come to you the story of Mūsā?');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(2358, 20, 10, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اِذۡ رَاٰ نَارًا فَقَالَ  لِاَہۡلِہِ  امۡکُثُوۡۤا  اِنِّیۡۤ اٰنَسۡتُ نَارًا لَّعَلِّیۡۤ  اٰتِیۡکُمۡ مِّنۡہَا بِقَبَسٍ  اَوۡ  اَجِدُ  عَلَی النَّارِ  ہُدًی ﴿۱۰﴾', 'جب انہوں نے آگ دیکھی تو اپنے گھر والوں سے کہا کہ تم یہاں ٹھہرو۔ میں نے آگ دیکھی ہے میں وہاں جاتا ہوں شاید اس میں سے میں تمہارے پاس انگارہ لاؤں یا آگ کے مقام سے اپنا رستہ معلوم کر سکوں۔', 'جب اُس نے دیکھی ایک آگ تو کہا اپنے گھر والوں کو ٹھہرو میں نے دیکھی ہے ایک آگ شاید لے آؤں تمہارے پاس اُس میں سے سلگا کر یا پاؤں آگ پر پہنچ کر رستہ کا پتہ', 'When he saw a fire, he said to his family: \"Wait! Verily, I have seen a fire, perhaps I can bring you some burning brand therefrom, or find some guidance at the fire.\"', 'When he saw a fire and said to his family, “Stay here. I have noticed a fire. Perhaps I can bring you an ember from it, or find some guidance by the fire.”'),
(2359, 20, 11, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَلَمَّاۤ   اَتٰىہَا  نُوۡدِیَ  یٰمُوۡسٰی ﴿ؕ۱۱﴾', 'پھر جب وہ وہاں پہنچے تو آواز آئی کہ اے موسٰی۔', 'پھر جب پہنچا آگ کے پاس آواز آئی اے موسٰی [۸]', 'And when he came to it (the fire), he was called by name: \"O Moosa (Moses)!', 'So when he came to it, he was called, “O Mūsā,'),
(2360, 20, 12, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اِنِّیۡۤ  اَنَا رَبُّکَ فَاخۡلَعۡ نَعۡلَیۡکَ ۚ اِنَّکَ بِالۡوَادِ  الۡمُقَدَّسِ طُوًی  ﴿ؕ۱۲﴾', 'میں تو تمہارا پروردگار ہوں تو اپنے جوتے اتار دو تم یہاں پاک میدان یعنی طوٰی میں ہو۔', 'میں ہوں تیرا رب سو اتار ڈال اپنی جوتیاں تو ہے پاک میدان طویٰ میں [۹]', '\"Verily! I am your Lord! So take off your shoes, you are in the sacred valley, Tuwa.', 'it is Me, your Lord, so remove your shoes; you are in the sacred valley of Tuwā.'),
(2361, 20, 13, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ  اَنَا  اخۡتَرۡتُکَ  فَاسۡتَمِعۡ  لِمَا یُوۡحٰی ﴿۱۳﴾', 'اور میں نے تم کو منتخب کر لیا تو جو حکم دیا جائے اسے سنو۔', 'اور میں نے تجھ کو پسند کیا ہے سو تو سنتا رہ جو حکم ہو [۱۰]', '\"And I have chosen you. So listen to that which is inspired to you.', 'I have chosen you (for prophet-hood), so listen to what is revealed:'),
(2362, 20, 14, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اِنَّنِیۡۤ  اَنَا اللّٰہُ  لَاۤ  اِلٰہَ   اِلَّاۤ   اَنَا  فَاعۡبُدۡنِیۡ ۙ وَ  اَقِمِ  الصَّلٰوۃَ   لِذِکۡرِیۡ ﴿۱۴﴾', 'بیشک میں ہی اللہ ہوں۔ میرے سوا کوئی معبود نہیں تو میری عبادت کیا کرو۔ اور میری یاد کے لئے نماز پڑھا کرو۔', 'میں جو ہوں اللہ ہوں کسی کی بندگی نہیں سوا میرے سو میری بندگی کر اور نماز قائم رکھ میری یادگاری کو [۱۱]', '\"Verily! I am Allah! La ilaha illa Ana (none has the right to be worshipped but I), so worship Me, and perform AsSalat (Iqamat-as-Salat) for My Remembrance.', 'Surely, I AM ALLAH. There is no god but Myself, so worship Me, and establish Salāh for My remembrance.'),
(2363, 20, 15, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اِنَّ السَّاعَۃَ  اٰتِیَۃٌ  اَکَادُ اُخۡفِیۡہَا لِتُجۡزٰی کُلُّ  نَفۡسٍۭ  بِمَا  تَسۡعٰی ﴿۱۵﴾', 'قیامت یقیناً آنے والی ہے۔ میں چاہتا ہوں کے اس کے وقت کو پوشیدہ رکھوں تاکہ ہر شخص جو کوشش کرے اس کا بدلہ پائے۔', 'قیامت بیشک آنے والی ہے میں مخفی رکھنا چاہتا ہوں اُسکو [۱۲] تاکہ بدلہ ملے ہر شخص کو جو اُس نے کمایا ہے [۱۳]', '\"Verily, the Hour is coming and My Will is to keep it hidden that every person may be rewarded for that which he strives.', 'Surely, the Hour (i.e. the Day of Judgment) has to come. I would keep it secret, so that everyone is given a return for the effort one makes.'),
(2364, 20, 16, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَلَا یَصُدَّنَّکَ عَنۡہَا مَنۡ لَّا یُؤۡمِنُ بِہَا وَ اتَّبَعَ  ہَوٰىہُ  فَتَرۡدٰی ﴿۱۶﴾', 'تو جو شخص اس پر ایمان نہیں رکھتا اور اپنی خواہش کے پیچھے چلتا ہے کہیں تمکو اس کے یقین سے روک نہ دے تو اس صورت میں تم ہلاک ہو جاؤ۔', 'سو کہیں تجھ کو نہ روک دے اُس سے وہ شخص جو یقین نہیں رکھتا اُس کا اور پیچھے پڑ رہا ہے اپنے مزوں کے پھر تو بھی پٹکا جائے [۱۴]', '\"Therefore, let not the one who believes not therein (i.e. in the Day of Resurrection, Reckoning, Paradise and Hell, etc.), but follows his own lusts, divert you therefrom, lest you perish.', 'So the one who does not believe in it and follows his desires must not make you neglectful of it, otherwise you will perish.'),
(2365, 20, 17, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ  مَا تِلۡکَ بِیَمِیۡنِکَ  یٰمُوۡسٰی ﴿۱۷﴾', 'اور اے موسٰی یہ تمہارے داہنے ہاتھ میں کیا ہے؟', 'اور یہ کیا ہے تیرے داہنے ہاتھ میں اے موسٰی [۱۵]', '\"And what is that in your right hand, O Moosa (Moses)?\"', 'And what is that in your right hand, O Mūsā?”'),
(2366, 20, 18, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ ہِیَ عَصَایَ ۚ اَتَوَکَّؤُا عَلَیۡہَا وَ اَہُشُّ بِہَا عَلٰی غَنَمِیۡ وَ لِیَ فِیۡہَا مَاٰرِبُ  اُخۡرٰی  ﴿۱۸﴾', 'انہوں نے کہا یہ میری لاٹھی ہے اس پر میں ٹیک لگاتا ہوں اور اس سے اپنی بکریوں کے لئے پتے جھاڑتا ہوں اور اس میں میرے اور بھی کئ فائدے ہیں۔', 'بولا یہ میری لاٹھی ہے اس پر ٹیک لگاتا ہوں اور پتے جھاڑتا ہوں اس سے اپنی بکریوں پر اور میرے اس میں چند کام ہیں اور بھی [۱۶]', 'He said: \"This is my stick, whereon I lean, and wherewith I beat down branches for my sheep, and wherein I find other uses.\"', 'He said, “It is my staff. I lean on it, and I beat down leaves with it for my sheep, and I have many other uses for it.”'),
(2367, 20, 19, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ  اَلۡقِہَا یٰمُوۡسٰی ﴿۱۹﴾', 'فرمایا کہ موسٰی اسے زمین پر ڈال دو۔', 'فرمایا ڈالدے اُسکو اے موسٰی', '(Allah) said: \"Cast it down, O Moosa (Moses)!\"', 'He said, “Throw it down O Mūsā”.'),
(2368, 20, 20, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَاَلۡقٰہَا فَاِذَا ہِیَ حَیَّۃٌ  تَسۡعٰی  ﴿۲۰﴾', 'تو انہوں نے اسکو ڈال دیا اور وہ یکایک سانپ بن کر دوڑنے لگا۔', 'تو اُسکو ڈال دیا پھر اسی وقت وہ تو سانپ ہو گیا دوڑتا ہوا [۱۷]', 'He cast it down, and behold! It was a snake, moving quickly.', 'So, he threw it down, and suddenly it was a snake, running around.'),
(2369, 20, 21, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ خُذۡہَا وَ لَا تَخَفۡ ٝ سَنُعِیۡدُہَا سِیۡرَتَہَا الۡاُوۡلٰی ﴿۲۱﴾', 'فرمایا کہ اسے پکڑ لو اور ڈرنا مت۔ ہم اسکو ابھی اسکی پہلی حالت پر لوٹا دیں گے۔', 'فرمایا پکڑ لے اُسکو اور مت ڈر ہم ابھی پھیر دیں گے اُسکو پہلی حالت پر [۱۸]', 'Allah said:\"Grasp it, and fear not, We shall return it to its former state,', 'He said, “Pick it up, and be not scared. We shall restore it to its former state.'),
(2370, 20, 22, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ اضۡمُمۡ یَدَکَ  اِلٰی جَنَاحِکَ تَخۡرُجۡ بَیۡضَآءَ  مِنۡ غَیۡرِ  سُوۡٓءٍ  اٰیَۃً  اُخۡرٰی ﴿ۙ۲۲﴾', 'اور اپنا ہاتھ اپنی بغل میں دبا لو کہ وہ کسی عیب و بیماری کے بغیر سفید چمکتا دمکتا نکلے گا۔ یہ دوسری نشانی ہے۔', 'اور ملا لے اپنا ہاتھ اپنی بغل سےکہ نکلے سفید ہو کر بلا عیب [۱۹] یہ نشانی دوسری', '\"And press your (right) hand to your (left) side, it will come forth white (and shining), without any disease as another sign,', 'And press your hand under your arm, and it will come out (brightly) white without any disease, as another sign,'),
(2371, 20, 23, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'لِنُرِیَکَ مِنۡ اٰیٰتِنَا الۡکُبۡرٰی  ﴿ۚ۲۳﴾', 'تاکہ ہم تمہیں اپنے بڑے بڑے نشانات دکھائیں۔', 'تاکہ دکھاتےجائیں ہم تجھ کو اپنی نشانیاں بڑی[۲۰]', '\"That We may show you (some) of Our Greater Signs.', 'so that We may show you some of Our great signs.'),
(2372, 20, 24, 1, 10, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اِذۡہَبۡ  اِلٰی  فِرۡعَوۡنَ  اِنَّہٗ  طَغٰی  ﴿٪۲۴﴾', 'تم فرعون کے پاس جاؤ کہ وہ سرکش ہو رہا ہے۔', 'جا طرف فرعون کے کہ اُس نے بہت سر اٹھایا', '\"Go to Firaun (Pharaoh)! Verily, he has transgressed (all bounds in disbelief and disobedience, and has behaved as an arrogant, and as a tyrant).\"', 'Go to Pharaoh. He has really exceeded all bounds.”'),
(2373, 20, 25, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ  رَبِّ  اشۡرَحۡ  لِیۡ  صَدۡرِیۡ ﴿ۙ۲۵﴾', 'کہا اے میرے پروردگار اس کام کے لئے میرا سینہ کھولدے۔', 'بولا اے رب کشادہ کر میرا سینہ [۲۱]', '(Moosa (Moses)) said: \"O my Lord! Open for me my chest (grant me self-confidence, contentment, and boldness).', 'He said, “My Lord, put my heart at peace for me,'),
(2374, 20, 26, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ  یَسِّرۡ لِیۡۤ   اَمۡرِیۡ ﴿ۙ۲۶﴾', 'اور میرا کام آسان کر دے۔', 'اور  آسان کر میرا کام [۲۲]', '\"And ease my task for me;', 'and make my task easy for me'),
(2375, 20, 27, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ  احۡلُلۡ  عُقۡدَۃً   مِّنۡ  لِّسَانِیۡ ﴿ۙ۲۷﴾', 'اور میری زبان کی گرہ کھول دے۔', 'اور کھول دے گرہ میری زبان سے', '\"And make loose the knot (the defect) from my tongue, (i.e. remove the incorrectness from my speech) (That occurred as a result of a brand of fire which Moosa (Moses) put in his mouth when he was an infant). (Tafsir At-Tabaree, Vol. 16, Page 159).', 'and remove the knot from my tongue,'),
(2376, 20, 28, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'یَفۡقَہُوۡا  قَوۡلِیۡ ﴿۪۲۸﴾', 'تاکہ وہ میری بات سمجھ لیں۔', 'کہ سمجھیں میری بات [۲۳]', '\"That they understand my speech,', 'so that they may understand my speech.'),
(2377, 20, 29, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ اجۡعَلۡ  لِّیۡ  وَزِیۡرًا مِّنۡ  اَہۡلِیۡ ﴿ۙ۲۹﴾', 'اور میرے گھر والوں میں سے ایک کو میرا وزیر یعنی مددگار مقرر فرما۔', 'اور دےمجھ کو ایک کام بٹانے والا میرے گھر کا', '\"And appoint for me a helper from my family,', 'And make for me an assistant from my own family,'),
(2378, 20, 30, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'ہٰرُوۡنَ  اَخِی ﴿ۙ۳۰﴾', 'یعنی میرے بھائی ہارون کو۔', 'ہارون میرا بھائی [۲۴]', '\"Haroon (Aaron), my brother;', 'that is, Hārūn, my brother.'),
(2379, 20, 31, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اشۡدُدۡ  بِہٖۤ   اَزۡرِیۡ ﴿ۙ۳۱﴾', 'اس سے میری کمر کو مضبوط کر۔', 'اُس سے مضبوط کر میری کمر', '\"Increase my strength with him,', 'Enhance with him my strength,'),
(2380, 20, 32, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ  اَشۡرِکۡہُ   فِیۡۤ   اَمۡرِیۡ ﴿ۙ۳۲﴾', 'اور اسے میرے کام میں شریک کر۔', 'اور شریک کر اُسکو میرے کام میں [۲۵]', '\"And let him share my task (of conveying Allahs Message and Prophethood),', 'and make him share my task,'),
(2381, 20, 33, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'کَیۡ  نُسَبِّحَکَ  کَثِیۡرًا ﴿ۙ۳۳﴾', 'تاکہ ہم تیری بہت سی تسبیح کریں۔', 'کہ تیری پاک ذات کا بیان کریں ہم بہت سا', '\"That we may glorify You much,', 'so that we proclaim Your purity in abundance'),
(2382, 20, 34, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَّ  نَذۡکُرَکَ  کَثِیۡرًا ﴿ؕ۳۴﴾', 'اور تجھے کثرت سے یاد کریں۔', 'اور یاد کریں ہم تجھ کو بہت سا [۲۶]', '\"And remember You much,', 'and remember You in abundance.'),
(2383, 20, 35, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اِنَّکَ  کُنۡتَ  بِنَا بَصِیۡرًا ﴿۳۵﴾', 'تو ہم کو ہر حال میں دیکھ رہا ہے۔', 'تو تو ہے ہم کو خوب دیکھتا [۲۷]', '\"Verily! You are of us Ever a Well-Seer.\"', 'You are certainly watchful over us.”'),
(2384, 20, 36, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ  قَدۡ  اُوۡتِیۡتَ  سُؤۡلَکَ  یٰمُوۡسٰی ﴿۳۶﴾', 'فرمایا۔ موسٰی تمہاری دعا قبول کی گئ۔', 'فرمایا ملا تجھ کو تیرا سوال اے موسٰی [۲۸]', 'Allah said: \"You are granted your request, O Moosa (Moses)!', 'He said, “You have been granted your request O Mūsā.'),
(2385, 20, 37, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ لَقَدۡ مَنَنَّا عَلَیۡکَ  مَرَّۃً   اُخۡرٰۤی  ﴿ۙ۳۷﴾', 'اور ہم نے تم پر ایک بار اور بھی احسان کیا تھا۔', 'اور احسان کیا تھا ہم نے تجھ پر ایک بار اور بھی [۲۹]', '\"And indeed We conferred a favour on you another time (before).', 'And We had bestowed Our favour on you another time,'),
(2386, 20, 38, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اِذۡ   اَوۡحَیۡنَاۤ  اِلٰۤی  اُمِّکَ  مَا یُوۡحٰۤی ﴿ۙ۳۸﴾', 'جب ہم نے تمہاری والدہ کو الہام کیا تھا جو تمہیں بتایا جاتا ہے۔', 'جب حکم بھیجا ہم نے تیری ماں کو جو آگے سناتے ہیں [۳۰]', '\"When We inspired your mother with that which We inspired.', 'when We revealed to your mother what was to be revealed,'),
(2387, 20, 39, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اَنِ اقۡذِفِیۡہِ فِی التَّابُوۡتِ فَاقۡذِفِیۡہِ فِی الۡیَمِّ فَلۡیُلۡقِہِ الۡیَمُّ بِالسَّاحِلِ یَاۡخُذۡہُ عَدُوٌّ لِّیۡ وَ عَدُوٌّ لَّہٗ ؕ وَ اَلۡقَیۡتُ عَلَیۡکَ مَحَبَّۃً مِّنِّیۡ ۬ۚ وَ لِتُصۡنَعَ  عَلٰی عَیۡنِیۡ  ﴿ۘ۳۹﴾', 'وہ یہ تھا کہ اسے یعنی موسٰی کو صندوق میں رکھو پھر اس صندوق کو دریا میں ڈالدو تو دریا اسکو کنارے پر ڈال دے گا اور میرا اور اس کا دشمن اسے اٹھا لے گا۔ اور موسٰی میں نے تم پر اپنی طرف سے محبت ڈال دی اور اس لئے کہ  تم میرے سامنے پرورش پاؤ۔', 'کہ ڈال اُسکو صندوق میں پھر اُسکو ڈال دے دریا میں پھر دریا اُسکو لے ڈالے کنارے پر اٹھا لے اُسکو ایک دشمن میرا اور اُس کا [۳۱] اور ڈال دی میں نے تجھ پر محبت اپنی طرف سے [۳۲] اور تاکہ پرورش پائے تو میری آنکھ کے سامنے [۳۳]', '\"Saying: Put him (the child) into the Taboot (a box or a case or a chest) and put it into the river (Nile), then the river shall cast it up on the bank, and there, an enemy of Mine and an enemy of his shall take him. And I endued you with love from Me, in order that you may be brought up under My Eye,', 'that is, ‘Put him (the baby) in the chest, then cast it into the river, then let the river throw it by the shore, and it will be picked up by one who is enemy to Me and enemy to him.’ And I had cast love on you from Myself (so that you might be favourite of all), and that you might be brought up under My eye.'),
(2388, 20, 40, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اِذۡ تَمۡشِیۡۤ اُخۡتُکَ فَتَقُوۡلُ ہَلۡ اَدُلُّکُمۡ  عَلٰی مَنۡ  یَّکۡفُلُہٗ ؕ فَرَجَعۡنٰکَ اِلٰۤی اُمِّکَ کَیۡ تَقَرَّ عَیۡنُہَا وَ لَا تَحۡزَنَ ۬ؕ وَ قَتَلۡتَ نَفۡسًا فَنَجَّیۡنٰکَ مِنَ الۡغَمِّ وَ فَتَنّٰکَ فُتُوۡنًا ۬۟ فَلَبِثۡتَ سِنِیۡنَ فِیۡۤ  اَہۡلِ مَدۡیَنَ ۬ۙ ثُمَّ جِئۡتَ عَلٰی قَدَرٍ یّٰمُوۡسٰی ﴿۴۰﴾', 'جب تمہاری بہن وہاں فرعون کے ہاں گئ اور کہنے لگی کہ میں تمہیں اس کا پتہ دوں جو اسکو پالے پوسے۔ تو اس طریق سے ہم نے تمکو تمہاری ماں کے پاس پہنچا دیا تاکہ انکی آنکھیں ٹھنڈی ہوں اور وہ رنج نہ کریں اور تم نے ایک شخص کو مار ڈالا تھا تو ہم نے تم کو غم سے نجات دی اور ہم نے تمہاری کئ بار آزمائش کی۔ پھر تم کئ سال اہل مدین میں ٹھہرے رہے۔ پھر اے موسٰی تم ایک اندازے پر آ پہنچے۔', 'جب چلنے لگی تیری بہن اور کہنے لگی میں بتاؤں تمکو ایسا شخص جو اُسکو  پالے پھر پہنچا دیا ہم نے تجھ کو تیری ماں کے پاس کہ ٹھنڈی رہے اُسکی آنکھ اور غم نہ کھائے [۳۴] اور تو نے مار ڈالا ایک شخص کو پھر بچا دیا ہم نے تجھ کو اُس غم سے [۳۵] اور جانچا ہم نے تجھ کو ایک ذرا جانچنا [۳۶] پھر ٹھہرا رہا تو کئ برس مدین والوں میں پھر آیا تو تقدیر سے اے موسٰی', '\"When your sister went and said: Shall I show you one who will nurse him? So We restored you to your mother, that she might cool her eyes and she should not grieve. Then you did kill a man, but We saved you from great distress and tried you with a heavy trial. Then you stayed a number of years with the people of Madyan (Midian). Then you came here according to the fixed term which I ordained (for you), O Moosa (Moses)!', '(Remember) when your sister was going (to the family of Pharaoh) and was saying, ‘Shall I lead you to one who nurses him?’ Thus We brought you back to your mother, so that her eyes might have comfort and she might not grieve. And you had killed a person, then We brought you out of the trouble; and We tested you with a great ordeal. Then you lived a number of years amidst the people of Madyan. After all this, you came O Mūsā, to a destined point of time.'),
(2389, 20, 41, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ اصۡطَنَعۡتُکَ  لِنَفۡسِیۡ ﴿ۚ۴۱﴾', 'اور میں نے تمکو اپنے کام کے لئے بنایا ہے۔', 'اور بنایا میں نے تجھ کو خاص اپنے واسطے [۳۸]', '\"And I have Istanatuka, for Myself.', 'I have fashioned you for Myself.'),
(2390, 20, 42, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اِذۡہَبۡ اَنۡتَ وَ اَخُوۡکَ بِاٰیٰتِیۡ وَ لَا تَنِیَا فِیۡ  ذِکۡرِیۡ ﴿ۚ۴۲﴾', 'تو تم اور تمہارا بھائی دونوں ہماری نشانیاں لے کر جاؤ اور میری یاد میں سستی نہ کرنا۔', 'جا تو اور تیرا بھائی میری نشانیاں لیکر اور سستی نہ کریو میری یاد میں [۳۹]', '\"Go you and your brother with My Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), and do not, you both, slacken and become weak in My Remembrance.', 'Go, you and your brother, with My signs, and do not be slack in My remembrance.'),
(2391, 20, 43, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اِذۡہَبَاۤ  اِلٰی  فِرۡعَوۡنَ  اِنَّہٗ  طَغٰی  ﴿ۚۖ۴۳﴾', 'دونوں فرعون کے پاس جاؤ کہ وہ سرکش ہو رہا ہے۔', 'جاؤ طرف فرعون کی اُس نے بہت سر اٹھایا [۴۰]', '\"Go, both of you, to Firaun (Pharaoh), verily, he has transgressed (all bounds in disbelief and disobedience and behaved as an arrogant and as a tyrant).', 'Go, both of you, to Pharaoh; he has indeed transgressed all limits.'),
(2392, 20, 44, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَقُوۡلَا لَہٗ  قَوۡلًا لَّیِّنًا لَّعَلَّہٗ  یَتَذَکَّرُ اَوۡ یَخۡشٰی ﴿۴۴﴾', 'اور اس سے نرمی سے بات کرنا شاید وہ غور کرے یا ڈر جائے۔', 'سو کہو اُس سے بات نرم شاید وہ سوچے یا ڈرے [۴۱]', '\"And speak to him mildly, perhaps he may accept admonition or fear Allah.\"', 'So speak to him in soft words. May be, he accepts the advice or fears (Allah)”.'),
(2393, 20, 45, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَا رَبَّنَاۤ  اِنَّنَا نَخَافُ اَنۡ یَّفۡرُطَ عَلَیۡنَاۤ اَوۡ  اَنۡ  یَّطۡغٰی  ﴿۴۵﴾', 'دونوں کہنے لگے کہ اے ہمارے پروردگار ہمیں خوف ہے کہ وہ ہم پر زیادتی کرنے لگے یا زیادہ سرکش ہو جائے۔', 'بولے اے رب ہمارے ہم ڈرتے ہیں کہ بھبک پڑے ہم پر یا جوش میں آ جائے [۴۲]', 'They said: \"Our Lord! Verily! We fear lest he should hasten to punish us or lest he should transgress (all bounds against us).\"', 'They said, “Our Lord, we fear that he will hasten against us, or will become (more) rebellious (against You).”'),
(2394, 20, 46, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ لَا تَخَافَاۤ اِنَّنِیۡ مَعَکُمَاۤ  اَسۡمَعُ وَ اَرٰی  ﴿۴۶﴾', 'اللہ نے فرمایا کہ ڈرو مت میں تمہارے ساتھ ہوں کہ سنتا اور دیکھتا ہوں۔', 'فرمایا نہ ڈرو میں ساتھ ہوں تمہارے سنتا ہوں اور دیکھتا ہوں [۴۳]', 'He (Allah) said: \"Fear not, verily! I am with you both, hearing and seeing.', 'He said, “Do not be afraid. I AM surely with you both. I hear and I see.'),
(2395, 20, 47, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَاۡتِیٰہُ  فَقُوۡلَاۤ  اِنَّا  رَسُوۡلَا  رَبِّکَ فَاَرۡسِلۡ مَعَنَا بَنِیۡۤ  اِسۡرَآءِیۡلَ ۬ۙ  وَ لَا تُعَذِّبۡہُمۡ ؕ قَدۡ جِئۡنٰکَ بِاٰیَۃٍ  مِّنۡ رَّبِّکَ ؕ وَ  السَّلٰمُ  عَلٰی  مَنِ  اتَّبَعَ  الۡہُدٰی ﴿۴۷﴾', 'اچھا تو اسکے پاس جاؤ اور کہو کہ ہم آپکے پروردگار کے بھیجے ہوئے ہیں۔ تو بنی اسرائیل کو ہمارے ساتھ جانے کی اجازت دیجئیے اور انہیں عذاب نہ کیجئے۔ ہم آپکے پاس آپ کے پروردگار کی طرف سے نشانی لے کر آئے ہیں۔ اور جو ہدایت کی بات مانے اسکو سلامتی ہو۔', 'سو جاؤ اُسکے پاس اور کہو ہم دونوں بھیجے ہوئے ہیں تیرے رب کے سو بھیجدے ہمارے ساتھ بنی اسرائیل کو اور مت ستا اُنکو [۴۴] ہم آئے ہیں تیرے پاس نشانی لیکر تیرے رب کی [۴۵] اور سلامتی ہو اُسکی جو مان لے راہ کی بات', '\"So go you both to him, and say: Verily, we are Messengers of your Lord, so let the Children of Israel go with us, and torment them not; indeed, we have come with a sign from your Lord! And peace will be upon him who follows the guidance!', 'So, come to him and say, ‘We are the messengers of your Lord. So, let the children of Isrā’īl go with us, and do not persecute them. We have come to you with a sign from your Lord; and peace be upon the one who follows the guidance.'),
(2396, 20, 48, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اِنَّا  قَدۡ اُوۡحِیَ  اِلَیۡنَاۤ  اَنَّ الۡعَذَابَ عَلٰی مَنۡ  کَذَّبَ  وَ تَوَلّٰی ﴿۴۸﴾', 'ہماری طرف یہ وحی آئی ہے کہ جو جھٹلائے اور منہ پھیرے اس کے لئے عذاب تیار ہے۔', 'ہم کو حکم ملا ہے کہ عذاب اُس پر ہے جو جھٹلائے اور منہ پھیر لے [۴۶]', 'Truly, it has been revealed to us that the torment will be for him who denies (believes not in the Oneness of Allah, and in His Messengers, etc.), and turns away.(from the truth and obedience of Allah)\"', 'Verily, it has been revealed to us that the punishment is for the one who denies and turns away.’”'),
(2397, 20, 49, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ  فَمَنۡ  رَّبُّکُمَا  یٰمُوۡسٰی ﴿۴۹﴾', 'غرض موسٰی اور ہارون فرعون کے پاس گئے اس نے کہا کہ موسٰی تمہارا پروردگار کون ہے۔', 'بولا پھر کون ہے رب تم دونوں کا اے موسٰی [۴۷]', 'Firaun (Pharaoh) said: \"Who then, O Moosa (Moses), is the Lord of you two?\"', 'He (Pharaoh) said, “Who then is the Lord of you two, O Mūsā?”'),
(2398, 20, 50, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ رَبُّنَا الَّذِیۡۤ اَعۡطٰی کُلَّ شَیۡءٍ خَلۡقَہٗ  ثُمَّ  ہَدٰی ﴿۵۰﴾', 'کہا کہ ہمارا پروردگار وہ ہے جس نے ہر چیز کو اسکی شکل و صورت بخشی پھر راہ دکھائی۔', 'کہا رب ہمارا وہ ہے جس نے دی ہر چیز کو اُسکی صورت پھر راہ سجھائی [۴۸]', '(Moosa (Moses)) said: \"Our Lord is He Who gave to each thing its form and nature, then guided it aright.\"', 'He (Mūsā) said, “Our Lord is the One who gave everything its due shape, then guided it.”'),
(2399, 20, 51, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ  فَمَا  بَالُ  الۡقُرُوۡنِ  الۡاُوۡلٰی ﴿۵۱﴾', 'کہا تو پہلی قوموں کا کیا حال ہوا؟', 'بولا پھر کیا حقیقت ہے اُن پہلی جماعتوں کی', '(Firaun (Pharaoh)) said: \"What about the generations of old?\"', 'He said, “Then, what is the status of the earlier generations?”'),
(2400, 20, 52, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ عِلۡمُہَا عِنۡدَ رَبِّیۡ فِیۡ  کِتٰبٍ ۚ  لَا یَضِلُّ  رَبِّیۡ  وَ لَا  یَنۡسَی ﴿۫۵۲﴾', 'فرمایا کہ ان کا علم میرے پروردگار کو ہے جو کتاب میں لکھا ہوا ہے میرا پروردگار نہ چوکتا ہے نہ بھولتا ہے۔', 'کہا اُنکی خبر میرے رب کے پاس لکھی ہوئی ہے نہ بہکتا ہے میرا رب اور نہ بھولتا ہے [۴۹]', '(Moosa (Moses)) said: \"The knowledge thereof is with my Lord, in a Record. My Lord is neither unaware nor He forgets, \"', 'He replied, “The knowledge about those is with my Lord in a Book. My Lord does neither err nor forget.”'),
(2401, 20, 53, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'الَّذِیۡ جَعَلَ لَکُمُ الۡاَرۡضَ مَہۡدًا وَّ سَلَکَ  لَکُمۡ  فِیۡہَا سُبُلًا وَّ  اَنۡزَلَ مِنَ السَّمَآءِ  مَآءً ؕ فَاَخۡرَجۡنَا بِہٖۤ  اَزۡوَاجًا مِّنۡ  نَّبَاتٍ  شَتّٰی ﴿۵۳﴾', 'وہ وہی تو ہے جس نے تم لوگوں کے لئے زمین کر فرش بنایا۔ اور اس میں تمہارے لئے رستے بنا دیئے اور آسمان سے پانی برسایا پھر اس سے مختلف نباتات پیدا کیں۔', 'وہ ہے جس نے بنا دیا تمہارے واسطے زمین کو بچھونا اور چلائیں تمہارے لئے اُس میں راہیں [۵۰] اور اتارا آسمان سے پانی پھر نکالی ہم نے اُس سے طرح طرح کی سبزی [۵۱]', 'Who has made earth for you like a bed (spread out); and has opened roads (ways and paths etc.) for you therein; and has sent down water (rain) from the sky. And We have brought forth with it various kinds of vegetation.', '(He is) the One who made the earth a cradle for you, and made in it pathways for you to move, and sent down water from the heavens; and We brought forth with it pairs of different vegetations :'),
(2402, 20, 54, 2, 11, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'کُلُوۡا وَ ارۡعَوۡا اَنۡعَامَکُمۡ ؕ اِنَّ  فِیۡ ذٰلِکَ لَاٰیٰتٍ  لِّاُولِی  النُّہٰی ﴿٪۵۴﴾', 'کہ خود بھی کھاؤ اور اپنے مویشیوں کو بھی چراؤ۔ بیشک ان باتوں میں عقل والوں کے لئے بہت سی نشانیاں ہیں۔', 'کھاؤ اور چراؤ اپنے چوپایوں کو [۵۲] البتہ اُس میں نشانیاں ہیں عقل رکھنے والوں کو [۵۳]', 'Eat and pasture your cattle, (therein); verily, in this are proofs and signs for men of understanding.', 'Eat, and graze your cattle. Surely, in that there are signs for the people of understanding.'),
(2403, 20, 55, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'مِنۡہَا خَلَقۡنٰکُمۡ وَ فِیۡہَا نُعِیۡدُکُمۡ  وَ مِنۡہَا نُخۡرِجُکُمۡ  تَارَۃً   اُخۡرٰی ﴿۵۵﴾', 'اسی زمین سے ہم نے تمکو پیدا کیا اور اسی میں ہم تمہیں لوٹائیں گے اور اسی سے ہم تمہیں دوسری دفعہ نکالیں گے۔', 'اسی زمین میں ہم نے تمکو بنایا اور اسی میں تمکو پھر پہنچا دیتے ہیں اور اسی سے نکالیں گے تمکو دوسری بار [۵۴]', 'Thereof (the earth) We created you, and into it We shall return you, and from it We shall bring you out once again.', 'From this (dust) We created you, and in this we shall put you back, and from this We shall raise you up once again.'),
(2404, 20, 56, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ لَقَدۡ اَرَیۡنٰہُ  اٰیٰتِنَا کُلَّہَا فَکَذَّبَ وَ اَبٰی ﴿۵۶﴾', 'اور ہم نے فرعون کو اپنی سب نشانیاں دکھائیں مگر وہ تکذیب اور انکار ہی کرتا رہا۔', 'اور ہم نے فرعون کو دکھلا دیں اپنی سب نشانیاں پھر اُس نے جھٹلایا اور نہ مانا [۵۵]', 'And indeed We showed him (Firaun (Pharaoh)) all Our Signs and Evidences, but he denied and refused.', 'And We showed him (Pharaoh) all Our signs, yet he rejected and refused.'),
(2405, 20, 57, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ  اَجِئۡتَنَا لِتُخۡرِجَنَا مِنۡ  اَرۡضِنَا بِسِحۡرِکَ یٰمُوۡسٰی ﴿۵۷﴾', 'کہنے لگا کہ موسٰی کیا تم ہمارے پاس اس لئے آئے ہو کہ اپنے جادو کے زور سے ہمیں ہمارے ملک سے نکال دو۔', 'بولا کیا تو آیا ہے ہم کو نکالنے ہمارے ملک سے اپنے جادو کے زور سے اے موسٰی [۵۶]', 'He (Firaun (Pharaoh)) said: \"Have you come to drive us out of our land with your magic, O Moosa (Moses)?', 'Said he, “Have you come to us to drive us out of our land with your sorcery, O Mūsā?'),
(2406, 20, 58, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَلَنَاۡتِیَنَّکَ بِسِحۡرٍ مِّثۡلِہٖ فَاجۡعَلۡ بَیۡنَنَا وَ بَیۡنَکَ مَوۡعِدًا  لَّا نُخۡلِفُہٗ  نَحۡنُ  وَ لَاۤ  اَنۡتَ  مَکَانًا  سُوًی ﴿۵۸﴾', 'تو ہم بھی تمہارے مقابل ایسا ہی جادو لائیں گے تو ہمارے اور اپنے درمیان ایک وقت مقرر کر لو کہ نہ تو ہم اسکے خلاف کریں اور نہ تم اور یہ مقابلہ ایک ہموار میدان میں ہو گا۔', 'سو ہم بھی لائیں گے تیرے مقابلہ میں ایک ایسا ہی جادو سو ٹھہرا لے ہمارے اور اپنے بیچ میں ایک وعدہ نہ ہم خلاف کریں اُس کا اور نہ  تو ایک میدان صاف میں [۵۷]', '\"Then verily, we can produce magic the like thereof; so appoint a meeting between us and you, which neither we, nor you shall fail to keep, in an open wide place where both shall have a just and equal chance (and beholders could witness the competition).\"', 'We will, then, bring to you a similar sorcery. So, make an appointment between you and us for an even place, not to be backed out, neither by us nor by you.”'),
(2407, 20, 59, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ مَوۡعِدُکُمۡ یَوۡمُ الزِّیۡنَۃِ وَ اَنۡ یُّحۡشَرَ  النَّاسُ ضُحًی ﴿۵۹﴾', 'موسٰی نے کہا کہ آپ کے لئے یوم زنیت کا وعدہ ہے اور یہ کہ لوگ اس روز دن چڑھے اکٹھے ہو جائیں۔', 'کہا وعدہ تمہارا ہے جشن کا دن اور یہ کہ جمع ہوں لوگ دن چڑھے [۵۸]', '(Moosa (Moses)) said: \"Your appointed meeting is the day of the festival, and let the people assemble when the sun has risen (forenoon).\"', 'He (Mūsā) said, “Your appointment is the festival day, and the people should be assembled at forenoon.”'),
(2408, 20, 60, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَتَوَلّٰی فِرۡعَوۡنُ فَجَمَعَ  کَیۡدَہٗ  ثُمَّ  اَتٰی ﴿۶۰﴾', 'تو فرعون لوٹ گیا اور اپنے سامان جمع کر کے پھر آیا۔', 'پھر اُلٹا پھرا فرعون پھر جمع کئے اپنے سارے داؤ پھر آیا [۵۹]', 'So Firaun (Pharaoh) withdrew, devised his plot and then came back.', 'So, Pharaoh turned back, and put his plot together, then came.'),
(2409, 20, 61, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ لَہُمۡ مُّوۡسٰی وَیۡلَکُمۡ لَا تَفۡتَرُوۡا عَلَی اللّٰہِ  کَذِبًا فَیُسۡحِتَکُمۡ  بِعَذَابٍ ۚ وَ قَدۡ  خَابَ  مَنِ افۡتَرٰی ﴿۶۱﴾', 'موسٰی نے ان جادوگروں سے کہا کہ یہ تمہاری بربادی ہو گی۔ اللہ پر جھوٹ نہ باندھو وہ تمہیں عذاب سے فنا کر دے گا۔ اور جس نے جھوٹ باندھا وہ نامراد رہا۔', 'کہا اُنکو موسٰی نے کم بختی تمہاری جھوٹ نہ بولو اللہ پر پھر غارت کر دے تمکو کسی سخت آفت سے اور مراد کو نہیں پہنچا جس نے جھوٹ باندھا [۶۰]', 'Moosa (Moses) said to them: \"Woe unto you! Invent not a lie against Allah, lest He should destroy you completely by a torment. And surely, he who invents a lie (against Allah) will fail miserably.\"', 'Mūsā said to them, “Pity on you, do not fabricate a lie against Allah, lest He should destroy you with a punishment. And loser is he who fabricates a lie.”'),
(2410, 20, 62, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَتَنَازَعُوۡۤا اَمۡرَہُمۡ بَیۡنَہُمۡ وَ اَسَرُّوا النَّجۡوٰی  ﴿۶۲﴾', 'تو وہ باہم اپنے معاملے میں جھگڑنے اور چپکے چپکے سرگوشی کرنے لگے۔', 'پھر جھگڑے اپنے کا م پر آپس میں اور چھپ کر کیا مشورہ [۶۱]', 'Then they debated with one another what they must do, and they kept their talk secret.', 'Then, they disputed among themselves in their matter, and kept their talk secret.'),
(2411, 20, 63, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالُوۡۤا  اِنۡ ہٰذٰىنِ لَسٰحِرٰنِ یُرِیۡدٰنِ اَنۡ یُّخۡرِجٰکُمۡ  مِّنۡ اَرۡضِکُمۡ  بِسِحۡرِہِمَا وَ یَذۡہَبَا بِطَرِیۡقَتِکُمُ  الۡمُثۡلٰی ﴿۶۳﴾', 'کہنے لگے کہ یہ دونوں جادوگر ہیں چاہتے ہیں کہ اپنے جادو کے زور سے تمکو تمہارے ملک سے نکال دیں۔ اور تمہارے بہترین مذہب کو نابود کر دیں۔', 'بولے مقرر یہ دونوں جادوگر ہیں چاہتے ہیں کہ نکال دیں تمکو تمہارے ملک سے اپنے جادو کے زور سے اور موقوف کرا دیں تمہارے اچھے خاصے چلن کو [۶۲]', 'They said: \"Verily! These are two magicians. Their object is to drive you out from your land with magic, and overcome your chiefs and nobles.', 'Said they, “Certainly, these two are sorcerers who wish to drive you out from your land, and do away with your excellent way of life.'),
(2412, 20, 64, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَاَجۡمِعُوۡا کَیۡدَکُمۡ  ثُمَّ  ائۡتُوۡا  صَفًّا ۚ وَ  قَدۡ  اَفۡلَحَ  الۡیَوۡمَ  مَنِ  اسۡتَعۡلٰی ﴿۶۴﴾', 'تو تم جادو کا سامان اکٹھا کر لو اور پھر قطار باندھ کر آؤ۔ آج جو غالب رہا وہی کامیاب ہوا۔', 'سو مقرر کر لو اپنی تدبیر پھر آؤ قطار باندھ کر اور جیت گیا آج جو غالب رہا [۶۳]', '\"So devise your plot, and then assemble in line. And whoever overcomes this day will be indeed successful.\"', 'So, make your plot firm and come forth in one row. Successful today is the one who prevails.”'),
(2413, 20, 65, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالُوۡا یٰمُوۡسٰۤی  اِمَّاۤ  اَنۡ تُلۡقِیَ وَ  اِمَّاۤ  اَنۡ نَّکُوۡنَ  اَوَّلَ  مَنۡ  اَلۡقٰی ﴿۶۵﴾', 'جادوگر بولے کہ موسٰی یا تو تم اپنی چیز ڈالو یا ہم اپنی چیزیں پہلے ڈالتے ہیں۔', 'بولے اے موسٰی یا تو تو ڈال اور یا ہم ہوں پہلے ڈالنے والے', 'They said:\"O Moosa (Moses)! Either you throw first or we be the first to throw?\"', 'They said, “O Mūsā, either you throw (first), or shall we be first to throw?”'),
(2414, 20, 66, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ بَلۡ اَلۡقُوۡا ۚ فَاِذَا حِبَالُہُمۡ وَ عِصِیُّہُمۡ  یُخَیَّلُ   اِلَیۡہِ مِنۡ سِحۡرِہِمۡ  اَنَّہَا  تَسۡعٰی  ﴿۶۶﴾', 'موسٰی نے کہا بلکہ تم ہی پہلے ڈالو جب انہوں نے چیزیں ڈالیں تو یکایک انکی رسیاں اور لاٹھیاں موسٰی کے خیال میں ایسی آنے لگیں کہ وہ میدان میں ادھر ادھر دوڑ رہی ہیں۔', 'کہا نہیں تم ڈالو [۶۴] پھر تبھی اُنکی رسیاں اور لاٹھیاں اُسکے خیال میں آئیں اُنکے جادو سے کہ دوڑ رہی ہیں [۶۵]', '(Moosa (Moses)) said: \"Nay, throw you (first)!\" Then behold, their ropes and their sticks, by their magic, appeared to him as though they moved fast.', 'He said, “Rather, you throw.” Then, suddenly their ropes and sticks seemed to him, due to their magic, as if they were running.'),
(2415, 20, 67, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَاَوۡجَسَ  فِیۡ  نَفۡسِہٖ  خِیۡفَۃً  مُّوۡسٰی ﴿۶۷﴾', 'اس وقت موسٰی نے اپنے دل میں خوف محسوس کیا۔', 'پھر پانے لگا اپنے جی میں ڈر موسٰی [۶۶]]', 'So Moosa (Moses) conceived a fear in himself.', 'So, Mūsā concealed some fear in his heart.'),
(2416, 20, 68, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قُلۡنَا لَا  تَخَفۡ اِنَّکَ اَنۡتَ الۡاَعۡلٰی ﴿۶۸﴾', 'ہم نے کہا خوف نہ کرو بلاشبہ تم ہی غالب رہو گے۔', 'ہم نے کہا تو مت ڈر مقرر تو ہی رہے گا غالب [۶۷]', 'We (Allah) said: \"Fear not! Surely, you will have the upper hand.', 'We said, “Do not be scared. Certainly, you are to be the upper most.'),
(2417, 20, 69, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ اَلۡقِ مَا فِیۡ یَمِیۡنِکَ تَلۡقَفۡ مَا صَنَعُوۡا ؕ اِنَّمَا صَنَعُوۡا کَیۡدُ سٰحِرٍ ؕ وَ لَا  یُفۡلِحُ  السَّاحِرُ  حَیۡثُ  اَتٰی ﴿۶۹﴾', 'اور جو چیز یعنی لاٹھی تمہارے داہنے ہاتھ میں ہے اسے ڈالدو کہ جو کچھ انہوں نے بنایا ہے اسکو وہ نگل جائے گی جو کچھ انہوں نے بنایا ہے یہ تو جادوگروں کے ہتھکنڈے ہیں اور جادوگر جہاں بھی جائے کامیاب نہیں ہو گا۔', 'اور ڈال جو تیرے داہنے ہاتھ میں ہے کہ نگل جائے جو کچھ اُنہوں نے بنایا [۶۸] اُن کا بنایا ہوا فریب ہے جادوگر کا  اور بھلا نہیں ہوتا جادوگر کا جہاں ہو [۶۹]', '\"And throw that which is in your right hand! It will swallow up that which they have made. That which they have made is only a magicians trick, and the magician will never be successful, no matter whatever amount (of skill) he may attain.\"', 'And throw what is in your right hand, and it will devour what they have concocted. What they have concocted is but a sleight of a magician. And the magician does not succeed wherever he comes from.”'),
(2418, 20, 70, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَاُلۡقِیَ السَّحَرَۃُ  سُجَّدًا قَالُوۡۤا  اٰمَنَّا بِرَبِّ ہٰرُوۡنَ  وَ  مُوۡسٰی ﴿۷۰﴾', 'اس پر جادوگر سجدے میں گر پڑے کہنے لگے کہ ہم موسٰی اور ہارون کے پروردگار پر ایمان لائے۔', 'پھر گر پڑے جادوگر سجدہ میں بولے ہم یقین لائے رب پر ہارون اور موسٰی کے [۷۰]', 'So the magicians fell down prostrate. They said: \"We believe in the Lord of Haroon (Aaron) and Moosa (Moses).\"', 'So, the magicians were led (by the truth) to fall in prostration. They said, “We have (now) believed in the Lord of Hārūn and Mūsā.”'),
(2419, 20, 71, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ اٰمَنۡتُمۡ لَہٗ  قَبۡلَ اَنۡ اٰذَنَ  لَکُمۡ ؕ اِنَّہٗ لَکَبِیۡرُکُمُ الَّذِیۡ عَلَّمَکُمُ السِّحۡرَ ۚ فَلَاُقَطِّعَنَّ  اَیۡدِیَکُمۡ وَ اَرۡجُلَکُمۡ مِّنۡ خِلَافٍ وَّ لَاُصَلِّبَنَّکُمۡ فِیۡ جُذُوۡعِ النَّخۡلِ ۫ وَ لَتَعۡلَمُنَّ  اَیُّنَاۤ   اَشَدُّ  عَذَابًا  وَّ  اَبۡقٰی ﴿۷۱﴾', 'فرعون بولا کہ پیشتر اسکے کہ میں تمہیں اجازت دوں تم اس پر ایمان لے آئے۔ بیشک یہ تمہارا بڑا یعنی استاد ہے جس نے تمکو جادو سکھایا ہے۔ سو میں تمہارے ہاتھ اور پاؤں مخالفت سمت سے کٹوا دوں گا اور تمکو کھجوروں کے تنوں پر سولی چڑھوا دوں گا اور تمکو معلوم ہو گا کہ ہم میں سے کس کا عذاب زیادہ سخت اور دیر تک رہنے والا ہے۔', 'بولا فرعون تم نے اُسکو مان لیا میں نے ابھی حکم نہ دیا تھا وہی تمہارا بڑا ہے جس نے سکھلایا تمکو جادو [۷۱] سو اب میں کٹواؤں گا تمہارے ہاتھ اور دوسری طرف کے پاؤں [۷۲] اور سولی دوں گا تمکو کھجور کے تنا پر [۷۳] اور جان لو گے ہم میں کس کا عذاب سخت ہے اور دیر تک رہنے والا [۷۴]', '(Firaun (Pharaoh)) said: \"Believe you in him (Moosa (Moses)) before I give you permission? Verily! He is your chief who taught you magic. So I will surely cut off your hands and feet on opposite sides, and I will surely crucify you on the trunks of date-palms, and you shall surely know which of us (I (Firaun Pharaoh) or the Lord of Moosa (Moses) (Allah)) can give the severe and more lasting torment.\"', 'He (Pharaoh) said, “You have believed in him before I permit you. This man is in fact your master who has taught you the magic. So I will certainly cut off your hands and your legs from opposite sides, and will crucify you on the trunks of palm-trees, and you shall know whose punishment, out of us, is more severe and more lasting.”'),
(2420, 20, 72, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالُوۡا  لَنۡ نُّؤۡثِرَکَ عَلٰی مَا جَآءَنَا مِنَ الۡبَیِّنٰتِ وَ الَّذِیۡ فَطَرَنَا فَاقۡضِ مَاۤ  اَنۡتَ قَاضٍ ؕ اِنَّمَا تَقۡضِیۡ ہٰذِہِ  الۡحَیٰوۃَ الدُّنۡیَا ﴿ؕ۷۲﴾', 'انہوں نے کہا کہ جو دلائل ہمارے پاس آ گئے ہیں ان پر اور جس نے ہم کو پیدا کیا ہے اس پر ہم آپ کو ہرگز ترجیح نہیں دیں گے۔ تو آپ کو جو حکم دینا ہو دے دیجئے اور آپ جو حکم دے سکتے ہیں وہ صرف اسی دنیا کی زندگی میں دے سکتے ہیں۔', 'وہ بولے ہم تجھ کو زیادہ نہ سمجھیں گے اُس چیز سے جو پہنچی ہم کو صاف دلیل اور اُس سے جس نے ہم کو پیدا کیا سو تو کر گذر جو تجھ کو کرنا ہے تو یہی کرے گا اس دنیا کی زندگی میں', 'They said: \"We prefer you not over the clear signs that have come to us, and to Him (Allah) Who created us. So decree whatever you desire to decree, for you can only decree (regarding) this life of the world.', 'They said, “We will never prefer you over the clear signs that have come to us, and over Him who has created us. So, decide whatever you have to decide. You will decide only for this worldly life.'),
(2421, 20, 73, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اِنَّـاۤ  اٰمَنَّا بِرَبِّنَا لِیَغۡفِرَ لَنَا خَطٰیٰنَا وَ مَاۤ  اَکۡرَہۡتَنَا عَلَیۡہِ  مِنَ  السِّحۡرِ ؕ وَ اللّٰہُ  خَیۡرٌ  وَّ  اَبۡقٰی ﴿۷۳﴾', 'ہم تو اپنے پروردگار پر ایمان لے آئے تاکہ وہ ہمارے گناہوں کو معاف کرے اور اسے بھی جو آپ نے ہم سے زبردستی جادو کرایا اور اللہ سب سے اچھا ہے اور ہمیشہ باقی رہنے والا ہے۔', 'ہم یقین لائے ہیں اپنے رب پر تاکہ بخشے ہم کو ہمارے گناہ اور جو تو نے زبردستی کروایا ہم سے یہ جادو [۷۵] اور اللہ بہتر ہے اور سدا باقی رہنے والا [۷۶]', '\"Verily! We have believed in our Lord, that He may forgive us our faults, and the magic to which you did compel us. And Allah is better as regards reward in comparison to your (Firauns (Pharaoh)) reward, and more lasting (as regards punishment in comparison to your punishment).\"', 'We have put our faith in our Lord, so that He forgives us for our sins and for the magic you compelled us to perform. And Allah is the Best and Everlasting.”'),
(2422, 20, 74, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اِنَّہٗ  مَنۡ یَّاۡتِ رَبَّہٗ  مُجۡرِمًا فَاِنَّ  لَہٗ جَہَنَّمَ ؕ لَا  یَمُوۡتُ  فِیۡہَا وَ  لَا  یَحۡیٰی ﴿۷۴﴾', 'جو شخص اپنے پروردگار کے پاس گناہگار ہو کر آئے گا تو اسکے لئے جہنم ہے جس میں نہ وہ مرے گا نہ جئے گا۔', 'بات یہی ہے کہ جو کوئی آیا رب کے پاس گناہ لیکر سو اُس کے واسطے دوزخ ہے نہ مرے اُس میں نہ جئے [۷۷]', 'Verily! Whoever comes to his Lord as a Mujrim (criminal, polytheist, disbeliever in the Oneness of Allah and His Messengers, sinner, etc.), then surely, for him is Hell, therein he will neither die nor live.', 'Surely whoever comes to his Lord as a sinner, for him there is Jahannam in which he neither will die nor will live (a happy life).'),
(2423, 20, 75, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ مَنۡ یَّاۡتِہٖ مُؤۡمِنًا قَدۡ عَمِلَ الصّٰلِحٰتِ فَاُولٰٓئِکَ  لَہُمُ  الدَّرَجٰتُ  الۡعُلٰی ﴿ۙ۷۵﴾', 'اور جو اسکے روبرو ایماندار ہو کر آئے گا اور عمل بھی نیک کئے ہوں گے تو ایسے لوگوں کے لئے اونچے اونچے درجے ہیں۔', 'اور جو آیا اُسکے پاس ایمان لیکر نیکیاں کر کر سو اُن لوگوں کیلئے ہیں درجے بلند', 'But whoever comes to Him (Allah) as a believer (in the Oneness of Allah, etc.), and has done righteous good deeds, for such are the high ranks (in the Hereafter),', 'And whoever will come to Him as believer, having done righteous deeds, for such people there are the highest ranks,'),
(2424, 20, 76, 3, 12, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'جَنّٰتُ عَدۡنٍ  تَجۡرِیۡ مِنۡ  تَحۡتِہَا  الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَا ؕ وَ ذٰلِکَ جَزٰٓؤُا  مَنۡ  تَزَکّٰی ﴿٪۷۶﴾', 'یعنی ہمیشہ رہنے کے باغ جنکے نیچے نہریں بہ رہی ہیں۔ ہمیشہ ان میں رہیں گے اور یہ اس شخص کا بدلہ ہے جو پاک ہوا۔', 'باغ ہیں بسنے کے بہتی ہیں اُنکے نیچے سے نہریں ہمیشہ رہا کریں گے اُن میں [۷۸] اور یہ بدلہ ہے اُس کا جو پاک ہوا [۷۹]', 'Adn (Edn) Paradise (everlasting Gardens), under which rivers flow, wherein they will abide forever: such is the reward of those who purify themselves ((by abstaining from all kinds of sins and evil deeds) which Allah has forbidden and by doing all that which Allah has ordained)).', 'the eternal gardens beneath which rivers flow, in which they shall live for ever. That is the reward for the one who has purified himself.'),
(2425, 20, 77, 4, 13, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ لَقَدۡ اَوۡحَیۡنَاۤ  اِلٰی مُوۡسٰۤی ۬ۙ اَنۡ  اَسۡرِ بِعِبَادِیۡ فَاضۡرِبۡ لَہُمۡ طَرِیۡقًا فِی الۡبَحۡرِ یَبَسًا ۙ لَّا  تَخٰفُ دَرَکًا وَّ لَا  تَخۡشٰی ﴿۷۷﴾', 'اور ہم نے موسٰی کی طرف وحی بھیجی کہ ہمارے بندوں کو راتوں رات نکال لے جاؤ پھر انکے لئے سمندر میں لاٹھی مار کر خشک رستہ بنا دو پھر تم کو نہ فرعون کے آ پکڑنے کا خوف ہو گا اور نہ غرق ہونے کا ڈر۔', 'اور ہم نے حکم بھیجا موسٰی کو کہ لے نکل میرےبندوں کو رات سے پھر ڈال دے اُنکے لئے سمندر میں رستہ سوکھا نہ خطرہ کر آ پکڑنے کا اور نہ ڈر ڈوبنے سے', 'And indeed We inspired Moosa (Moses) (saying): \"Travel by night with Ibadi (My slaves) and strike a dry path for them in the sea, fearing neither to be overtaken (by Firaun (Pharaoh)) nor being afraid (of drowning in the sea).\"', 'And We revealed to Mūsā saying, “Set out with my servants at night, then make for them a dry path across the sea (with the strike of your staff), neither fearing to be caught up, nor having any fear (of drowning).”'),
(2426, 20, 78, 4, 13, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَاَتۡبَعَہُمۡ فِرۡعَوۡنُ بِجُنُوۡدِہٖ فَغَشِیَہُمۡ مِّنَ  الۡیَمِّ  مَا غَشِیَہُمۡ ﴿ؕ۷۸﴾', 'پھر فرعون نے اپنے لشکروں کے ساتھ ان کا تعاقب کیا۔ تو سمندر کی موجوں نے ان پر چڑھ کر انہیں ڈھانک لیا یعنی ڈبو دیا۔', 'پھر پیھچا کیا اُن کا فرعون نے اپنے لشکروں کو لیکر پھر ڈھانپ لیا اُنکو پانی نے جیسا کہ ڈھانپ لیا [۸۰]', 'Then Firaun (Pharaoh) pursued them with his hosts, but the sea-water completely overwhelmed them and covered them up.', 'Then Pharaoh chased them with his troops. So, they were encircled by that (huge wave) from the sea which overwhelmed them.'),
(2427, 20, 79, 4, 13, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ اَضَلَّ فِرۡعَوۡنُ  قَوۡمَہٗ  وَ مَا ہَدٰی ﴿۷۹﴾', 'اور فرعون نے اپنی قوم کو گمراہ کر دیا اور سیدھے رستے پر نہ ڈالا۔', 'اور بہکایا فرعون نے اپنی قوم کو اور نہ سمجھایا [۸۱]', 'And Firaun (Pharaoh) led his people astray, and he did not guide them.', 'Pharaoh held his people astray, and did not show them the right path.'),
(2428, 20, 80, 4, 13, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'یٰبَنِیۡۤ  اِسۡرَآءِیۡلَ قَدۡ  اَنۡجَیۡنٰکُمۡ مِّنۡ عَدُوِّکُمۡ وَ وٰعَدۡنٰکُمۡ جَانِبَ الطُّوۡرِ الۡاَیۡمَنَ وَ نَزَّلۡنَا عَلَیۡکُمُ الۡمَنَّ وَ السَّلۡوٰی ﴿۸۰﴾', 'اے آل یعقوب ہم نے تمکو تمہارے دشمن سے نجات دی اور تورات دینے کے لئے تم سے کوہ طور کی داہنی جانب مقرر کی اور تم پر من اور سلوٰی نازل کیا۔', 'اے اولاد اسرائیل چھڑا لیا ہم نے تمکو تمہارے دشمن سے اور وعدہ ٹھہرا یا تم سے داہنی طرف پہاڑ کی اور اتارا تم پر من اور سلویٰ', 'O Children of Israel! We delivered you from your enemy, and We made a covenant with you on the right side of the Mount, and We sent down to you Al-Manna and quails,', 'O children of Isrā’īl , We delivered you from your enemy and appointed for you the right side of the mount Tūr (Sinai), and sent down for you the Mann and Salwā :'),
(2429, 20, 81, 4, 13, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'کُلُوۡا مِنۡ طَیِّبٰتِ مَا رَزَقۡنٰکُمۡ وَ لَا تَطۡغَوۡا فِیۡہِ فَیَحِلَّ عَلَیۡکُمۡ غَضَبِیۡ ۚ وَ مَنۡ یَّحۡلِلۡ عَلَیۡہِ غَضَبِیۡ فَقَدۡ ہَوٰی ﴿۸۱﴾', 'اور حکم دیا کہ جو پاکیزہ چیزیں ہم نے تمکو دی ہیں انکو کھاؤ۔ اور اس میں حد سے نہ نکلنا۔ ورنہ تم پر میرا غضب نازل ہو گا اور جس پر میرا غضب عذاب نازل ہوا وہ ہلاک ہو گیا۔', 'کھاؤ ستھری چیزیں جو روزی دی ہم نے تمکو اور نہ کرو اُس میں زیادتی [۸۲] پھر تو اترے گا تم پر میرا غصہ اور جس پر اترا میرا غصہ سو وہ پٹکا گیا [۸۳]', '(Saying) eat of the Taiyibat (good lawful things) wherewith We have provided you, and commit no oppression therein, lest My Anger should justly descend on you. And he on whom My Anger descends, he is indeed perished.', 'Eat from the good things We have provided to you, and do not exceed the limits in it, lest My wrath should descend on you. The one upon whom My wrath descends certainly falls into destruction.'),
(2430, 20, 82, 4, 13, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ اِنِّیۡ لَغَفَّارٌ لِّمَنۡ تَابَ وَ اٰمَنَ وَ عَمِلَ صَالِحًا  ثُمَّ  اہۡتَدٰی ﴿۸۲﴾', 'اور جو توبہ کرے اور ایمان لائے اور عمل نیک کرے پھر سیدھے رستے چلے اسکو میں بخش دینے والا ہوں۔', 'اور میری بڑی بخشش ہے اس پر جو توبہ کرے اور یقین لائے اور کرے بھلا کام پھر راہ پر رہے [۸۴]', 'And verily, I am indeed Forgiving to him who repents, believes (in My Oneness, and associates none in worship with Me) and does righteous good deeds, and then remains constant in doing them, (till his death).', 'Surely I am the Most-Forgiving for him who repents and believes and acts righteously, then follows the right path.'),
(2431, 20, 83, 4, 13, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ  مَاۤ   اَعۡجَلَکَ  عَنۡ  قَوۡمِکَ  یٰمُوۡسٰی ﴿۸۳﴾', 'اور اے موسٰی تم نے اپنی قوم سے آگے چلے آنے میں کیوں جلدی کی؟', 'اور کیوں جلدی کی تونے اپنی قوم سے اے موسٰی', '\"And what made you hasten from your people, O Moosa (Moses)?\"', '“What has caused you to hurry before your people, O Mūsā?”'),
(2432, 20, 84, 4, 13, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ ہُمۡ اُولَآءِ عَلٰۤی  اَثَرِیۡ وَ عَجِلۡتُ اِلَیۡکَ  رَبِّ  لِتَرۡضٰی ﴿۸۴﴾', 'کہا وہ میرے پیچھے آ رہے ہیں اور اے میرے پروردگار میں نے تیری طرف آنے کی جلدی اس لئے کی کہ تو خوش ہو جائے۔', 'بولا وہ یہ آ رہے ہیں میرے پیچھے اور میں جلدی آیا تیری طرف اے میرے رب تاکہ تو راضی ہو [۸۵]', 'He said: \"They are close on my footsteps, and I hastened to You, O my Lord, that You might be pleased.\"', 'He said, “Here they are just behind me, and I hurried towards You, my Lord, so that You be pleased.”'),
(2433, 20, 85, 4, 13, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ فَاِنَّا قَدۡ فَتَنَّا قَوۡمَکَ مِنۡۢ بَعۡدِکَ وَ اَضَلَّہُمُ  السَّامِرِیُّ ﴿۸۵﴾', 'فرمایا کہ ہم نے تمہاری قوم کو تمہارے بعد آزمائش میں ڈالدیا ہے اور سامری نے انکو بہکا دیا ہے۔', 'فرمایا ہم نے بچلا دیا تیری قوم کو تیرے پیچھے اور بہکایا اُنکو سامری نے [۸۶]', '(Allah) said: \"Verily! We have tried your people in your absence, and As-Samiri has led them astray.\"', 'He said, “We have then put your people to test after you (left them) and Sāmiriyy has misguided them.”'),
(2434, 20, 86, 4, 13, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَرَجَعَ مُوۡسٰۤی اِلٰی قَوۡمِہٖ غَضۡبَانَ  اَسِفًا ۬ۚ  قَالَ یٰقَوۡمِ  اَلَمۡ  یَعِدۡکُمۡ  رَبُّکُمۡ وَعۡدًا حَسَنًا ۬ؕ اَفَطَالَ عَلَیۡکُمُ الۡعَہۡدُ اَمۡ  اَرَدۡتُّمۡ اَنۡ یَّحِلَّ عَلَیۡکُمۡ غَضَبٌ  مِّنۡ  رَّبِّکُمۡ فَاَخۡلَفۡتُمۡ مَّوۡعِدِیۡ ﴿۸۶﴾', 'اور موسٰی غصے اور غم کی حالت میں اپنی قوم کے پاس واپس آئے اور کہنے لگے کہ اے قوم کیا تمہارے پروردگار نے تم سے اچھا وعدہ نہیں کیا تھا؟ کیا میری جدائی کی مدت تمہیں لمبی معلوم ہوئی یا تم نے یہ چاہا کہ تم پر تمہارے پروردگار کی طرف سے غضب نازل ہو۔ اور اس لئے تم نے مجھ سے جو وعدہ کیا تھا اس کے خلاف کیا۔', 'پھر الٹا پھرا موسٰی اپنی قوم کے پاس غصہ میں بھرا پچتاتا ہوا کہا اے قوم کیا تم سے وعدہ نہ کیا تھا تمہارے رب نے اچھا وعدہ کیا طویل ہو گئ تم پر مدت یا چاہا تم نے کہ اترے تم پر غضب تمہارے رب کا اس لئے خلاف کیا تم نے میرا وعدہ [۸۷]', 'Then Moosa (Moses) returned to his people in a state of anger and sorrow. He said: \"O my people! Did not your Lord promise you a fair promise? Did then the promise seem to you long in coming? Or did you desire that wrath should descend from your Lord on you, so you broke your promise to me (i.e disbelieving in Allah and worshipping the calf)?\"', 'So, Mūsā went back to his people, angry and sad. He said, “O my people, did your Lord not promise you a good promise? Did then the time become too long for you, or did you wish that wrath from your Lord befalls you, and hence you broke your promise to me?”'),
(2435, 20, 87, 4, 13, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالُوۡا مَاۤ  اَخۡلَفۡنَا مَوۡعِدَکَ بِمَلۡکِنَا وَ لٰکِنَّا حُمِّلۡنَاۤ  اَوۡزَارًا مِّنۡ زِیۡنَۃِ الۡقَوۡمِ فَقَذَفۡنٰہَا فَکَذٰلِکَ اَلۡقَی  السَّامِرِیُّ ﴿ۙ۸۷﴾', 'وہ کہنے لگے کہ ہم نے اپنے اختیار سے آپ سے وعدہ خلافی نہیں کی۔ لیکن ہم ان لوگوں کے زیوروں کا بوجھ اٹھائے ہوئے تھے۔ پھر ہم نے اسکو آگ میں ڈال دیا اور اسی طرح سامری نے ڈال دیا۔', 'بولے ہم نے خلاف نہیں کیا تیرا وعدہ اپنے اختیار سے و لیکن اٹھوایا ہم سے بھاری بوجھ قوم فرعون کے زیور کا سو ہم نے اُسکو پھینک دیا پھر اس طرح ڈھالا سامری نے  [۸۸]', 'They said: \"We broke not the promise to you, of our own will, but we were made to carry the weight of the ornaments of the (Firauns (Pharaoh)) people, then we cast them (into the fire), and that was what As-Samiri suggested.\"', 'They said, “We did not break our promise to you of our own accord, but we were burdened with loads from the ornaments of the people;so we threw them, and thus did Sāmiriyy cast.”'),
(2436, 20, 88, 4, 13, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَاَخۡرَجَ لَہُمۡ عِجۡلًا جَسَدًا لَّہٗ خُوَارٌ فَقَالُوۡا ہٰذَاۤ  اِلٰـہُکُمۡ وَ اِلٰہُ  مُوۡسٰی ۬ فَنَسِیَ ﴿ؕ۸۸﴾', 'تو اس نے انکے لئے ایک بچھڑا بنا دیا یعنی ایک بیجان جسم جس میں گائے کی سی آواز تھی۔ تو لوگ کہنے لگے کہ یہی تمہارا معبود ہے اور یہی موسٰی کا معبود ہے۔ مگر وہ بھول گئے ہیں۔', 'پھر بنا نکالا اُنکے واسطے ایک بچھڑا ایک دھڑ جسمیں آواز گائے کی پھر کہنے لگے یہ معبود ہے تمہارا اور معبود ہے موسٰی کا سو وہ بھول گیا [۸۹]', 'Then he took out (of the fire) for them a statue of a calf which seemed to low. They said: \"This is your ilah (god), and the ilah (god) of Moosa (Moses), but (Moosa (Moses)) has forgotten (his god).\"', 'Then he brought forth for them a calf, which was (merely) a body with a lowing sound. Then they said, “This is your god and the god of Mūsā, and he (Mūsā) erred.”'),
(2437, 20, 89, 4, 13, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اَفَلَا  یَرَوۡنَ  اَلَّا  یَرۡجِعُ  اِلَیۡہِمۡ  قَوۡلًا ۬ۙ وَّ لَا یَمۡلِکُ  لَہُمۡ  ضَرًّا  وَّ لَا  نَفۡعًا ﴿٪۸۹﴾', 'تو کیا یہ لوگ نہیں دیکھتے کہ وہ انکی کسی بات کا جواب نہیں دیتا۔ اور نہ انکے نقصان اور نفع کا کچھ اختیار رکھتا ہے۔', 'بھلا یہ لوگ نہیں دیکھتے کہ وہ جواب تک نہیں دیتا اُنکو کسی بات کا اور اختیار نہیں رکھتا اُنکے برے کا اور نہ بھلے کا [۹۰]', 'Did they not see that it could not return them a word (for answer), and that it had no power either to harm them or to do them good?', 'Have they not been seeing that it did not respond to them (even) with a word, nor did it have power to harm or benefit them?'),
(2438, 20, 90, 5, 14, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ لَقَدۡ قَالَ لَہُمۡ ہٰرُوۡنُ مِنۡ قَبۡلُ یٰقَوۡمِ اِنَّمَا فُتِنۡتُمۡ بِہٖ ۚ وَ  اِنَّ رَبَّکُمُ  الرَّحۡمٰنُ فَاتَّبِعُوۡنِیۡ  وَ اَطِیۡعُوۡۤا  اَمۡرِیۡ ﴿۹۰﴾', 'اور ہارون نے ان سے پہلے ہی کہہ دیا تھا کہ لوگو اس کے ذریعے تمہیں فتنے میں ڈال دیا گیا ہے اور تمہارا پروردگار تو رحمٰن ہی ہے تو میری پیروی کرو اور میرا کہا مانو۔', 'اور کہا تھا اُنکو ہارون نے پہلے سے اے قوم بات یہی ہے کہ تم بہک گئے اس بچھڑے سے اور تمہارا رب تو رحمٰن ہے سو میری راہ چلو اور مانو بات میری [۹۱]', 'And Haroon (Aaron) indeed had said to them beforehand: \"O my people! You are being tried in this, and verily, your Lord is (Allah) the Most Beneficent, so follow me and obey my order.\"', 'Hārūn had already said to them, “O my people, you have only been led astray with it, and your Lord is the RaHmān (All-Merciful). So follow me and obey my command.”'),
(2439, 20, 91, 5, 14, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالُوۡا لَنۡ نَّبۡرَحَ عَلَیۡہِ عٰکِفِیۡنَ حَتّٰی یَرۡجِعَ   اِلَیۡنَا مُوۡسٰی  ﴿۹۱﴾', 'وہ کہنے لگے کہ جب تک موسٰی ہمارے پاس واپس نہ آئیں ہم تو اس کی پوجا پر قائم رہیں گے۔', 'بولے ہم برابر اسی پر لگے بیٹھے رہیں گے جب تک لوٹ کر نہ آئے ہمارے پاس موسٰی [۹۲]', 'They said: \"We will not stop worshipping it (i.e. the calf), until Moosa (Moses) returns to us.\"', 'They said, “We will never cease to stay with it in devotion, until Mūsā returns to us.”'),
(2440, 20, 92, 5, 14, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ یٰہٰرُوۡنُ مَا مَنَعَکَ اِذۡ  رَاَیۡتَہُمۡ ضَلُّوۡۤا ﴿ۙ۹۲﴾', 'پھر موسٰی نے ہارون سے کہا کہ اے ہارون جب تم نے انکو دیکھا تھا کہ گمراہ ہو گئے ہیں تو تم کو کس چیز نے روکا تھا۔', 'کہا موسٰی نے اے ہارون کس چیز نے روکا تجھ کو جب دیکھا تھا تو نے کہ وہ بہک گئے', '(Moosa (Moses)) said: \"O Haroon (Aaron)! What stopped you when you saw them going astray;', 'He (Mūsā) said, “O Hārūn, what did prevent you from following me when you saw them going astray?'),
(2441, 20, 93, 5, 14, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اَلَّا  تَتَّبِعَنِ ؕ اَفَعَصَیۡتَ   اَمۡرِیۡ ﴿۹۳﴾', 'یعنی اس بات سے کہ تم میرے پیچھے چلے آؤ بھلا تم نے میرے حکم کے خلاف کیوں کیا؟', 'کہ تو میرےپیچھے نہ آیا کیا تو نے رد کیا میرا حکم [۹۳]', '\"That you followed me not (according to my advice to you)? Have you then disobeyed my order?\"', 'Did you then disobey my command?”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(2442, 20, 94, 5, 14, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ یَبۡنَؤُمَّ  لَا تَاۡخُذۡ بِلِحۡیَتِیۡ  وَ لَا بِرَاۡسِیۡ ۚ اِنِّیۡ خَشِیۡتُ اَنۡ تَقُوۡلَ فَرَّقۡتَ بَیۡنَ بَنِیۡۤ  اِسۡرَآءِیۡلَ وَ لَمۡ تَرۡقُبۡ قَوۡلِیۡ ﴿۹۴﴾', 'کہنے لگے کہ اے ماں جائے میری داڑھی اور سر کے بالوں کو نہ پکڑیئے میں تو اس سے ڈرا کہ آپ یہ نہ کہیں کہ تم نے بنی اسرائیل میں تفرقہ ڈال دیا اور میری بات کو ملحوظ نہ رکھا۔', 'وہ بولا اے میری ماں کے جنے نہ پکڑ میری داڑھی اور نہ سر [۹۴] میں ڈرا کہ تو کہے گا پھوٹ ڈالدی تو نے بنی اسرائیل میں اور یاد نہ رکھی میری بات [۹۵]', 'He (Haroon (Aaron)) said: \"O son of my mother! Seize (me) not by my beard, nor by my head! Verily, I feared lest you should say: You have caused a division among the Children of Israel, and you have not respected my word! \"', 'He said, “O son of my mother, do not hold me by my beard, nor by my head. I feared that you would say, ‘You have caused discord among the children of Isrā’īl and did not observe my advice.’”'),
(2443, 20, 95, 5, 14, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ فَمَا خَطۡبُکَ  یٰسَامِرِیُّ ﴿۹۵﴾', 'موسٰی نے فرمایا کہ اے سامری تیرا کیا حال ہے؟', 'کہا موسٰی نے اب تیری کیا حقیقت ہے اے سامری [۹۶]', '(Moosa (Moses)) said: \"And what is the matter with you. O Samiri? (i.e. why did you do so?)\"', 'He (Mūsā) said, “What then is your case, O Sāmiriyy?”'),
(2444, 20, 96, 5, 14, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ بَصُرۡتُ بِمَا لَمۡ یَبۡصُرُوۡا بِہٖ فَقَبَضۡتُ قَبۡضَۃً  مِّنۡ  اَثَرِ الرَّسُوۡلِ فَنَبَذۡتُہَا وَ کَذٰلِکَ سَوَّلَتۡ لِیۡ نَفۡسِیۡ ﴿۹۶﴾', 'اس نے کہا کہ میں نے ایسی چیز دیکھی جو اوروں نے نہیں دیکھی تو میں نے فرشتے کے نقش پا سے مٹی کی ایک مٹھی بھر لی۔ پھر اسکو بچھڑے کے جسم میں ڈال دیا اور مجھے میرے جی نے اس کام کو اچھا بتایا۔', 'بولا میں نے دیکھ لیا جو اوروں نے نہ دیکھا پھر بھر لی میں نے ایک مٹھی پاؤں کے نیچے سے اُس بھیجے ہوئے کے پھر میں نے وہی ڈالدی اور یہی صلاح دی مجھ کو میرے جی نے [۹۷]', '(Samiri) said: \"I saw what they saw not, so I took a handful (of dust) from the hoof print of the messenger (Jibraels (Gabriel) horse) and threw it (into the fire in which were put the ornaments of the Firauns (Pharaoh) people, or into the calf). Thus my inner-self suggested to me.\"', 'He said, “I perceived something they did not perceive. So I picked up a handful from under the footstep of the messenger. Then, I cast it. And thus my inner self tempted me.”'),
(2445, 20, 97, 5, 14, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ فَاذۡہَبۡ فَاِنَّ لَکَ فِی الۡحَیٰوۃِ  اَنۡ تَقُوۡلَ لَا مِسَاسَ ۪ وَ اِنَّ لَکَ مَوۡعِدًا لَّنۡ تُخۡلَفَہٗ ۚ وَ انۡظُرۡ  اِلٰۤی  اِلٰـہِکَ الَّذِیۡ ظَلۡتَ عَلَیۡہِ عَاکِفًا ؕ لَنُحَرِّقَنَّہٗ  ثُمَّ لَنَنۡسِفَنَّہٗ  فِی الۡیَمِّ  نَسۡفًا ﴿۹۷﴾', 'موسٰی نے کہا جا تجھ کو دنیا کی زندگی میں یہ سزا ہے کہ کہتا رہے کہ مجھ کو ہاتھ نہ لگانا اور تیرے لئے ایک اور وعدہ ہے یعنی عذاب کا جو تجھ سے ٹل نہ سکے گا۔ اور جس معبود کی پوجا پر تو جما ہوا تھا اسکو دیکھ ہم اسے جلا دیں گے پھر اس کی راکھ کر اڑا کر دریا میں بکھیر دیں گے۔', 'کہا موسٰی نے دور ہو تیرے لئے زندگی بھر تو اتنی سزا ہے کہ کہا کرے مت چھیڑو [۹۸] اور تیرے واسطے ایک وعدہ ہے وہ ہرگز تجھ سے خلاف نہ ہو گا [۹۹] اور دیکھ اپنے معبود کو جس پر تمام دن تو معتکف رہتا تھا ہم اسکو جلا دیں گے پھر بکھیر دیں گے دریا میں اڑا کر [۱۰۰]', 'Moosa (Moses) said: \"Then go away! And verily, your (punishment) in this life will be that you will say: \"Touch me not (i.e.you will live alone exiled away from mankind); and verily (for a future torment), you have a promise that will not fail. And look at your ilah (god), to which you have been devoted. We will certainly burn it, and scatter its particles in the sea.\"', 'He (Mūsā) said, “Then go away; it is destined for you that, throughout your life, you will say: ‘Do not touch me’. And, of course, you have another promise that will not be broken for you. And look at your god to which you stayed devoted. We will certainly burn it, then we will scatter it thoroughly in the sea.'),
(2446, 20, 98, 5, 14, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اِنَّمَاۤ  اِلٰـہُکُمُ  اللّٰہُ  الَّذِیۡ لَاۤ اِلٰہَ  اِلَّا ہُوَ ؕ وَسِعَ  کُلَّ  شَیۡءٍ  عِلۡمًا ﴿۹۸﴾', 'تمہارا معبود تو اللہ ہی ہے جسکے سوا کوئی معبود نہیں اس کا علم ہر چیز پر محیط ہے۔', 'تمہارا معبود تو وہی اللہ ہے جس کے سوا کسی کی بندگی نہیں سب چیز سما گئ ہے اُسکے علم میں [۱۰۱]', 'Your Ilah (God) is only Allah, the One (La ilaha illa Huwa) (none has the right to be worshipped but He). He has full knowledge of all things.', 'Your God is Allah other than whom there is no god. He encompasses everything with knowledge.”'),
(2447, 20, 99, 5, 14, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'کَذٰلِکَ نَقُصُّ عَلَیۡکَ مِنۡ اَنۡۢبَآءِ مَا قَدۡ سَبَقَ ۚ وَ قَدۡ اٰتَیۡنٰکَ مِنۡ لَّدُنَّا ذِکۡرًا ﴿ۖۚ۹۹﴾', 'اس طرح ہم تم سے وہ حالات بیان کرتے ہیں جو گذر چکے ہیں۔ اور ہم نے تمہیں اپنے پاس سے نصیحت کی کتاب عطا فرمائی ہے۔', 'یوں سناتےہیں ہم تجھ کو اُنکے احوال جو پہلے گذر چکے [۱۰۲] اور ہم نے دی تجھ کو  اپنے پاس سے پڑھنے کی کتاب [۱۰۳]', 'Thus We relate to you (O Muhammad SAW) some information of what happened before. And indeed We have given you from Us a Reminder (this Quran).', 'This is how We narrate to you certain events of what has passed, and We have given to you, from Ourself, a (book of) advice.'),
(2448, 20, 100, 5, 14, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'مَنۡ اَعۡرَضَ عَنۡہُ فَاِنَّہٗ یَحۡمِلُ یَوۡمَ الۡقِیٰمَۃِ  وِزۡرًا ﴿۱۰۰﴾ۙ', 'جو شخص اس سے منہ پھیرے گا وہ قیامت کے دن گناہ کا بوجھ اٹھائے گا۔', 'جو کوئی منہ پھیر لے اُس سے وہ اٹھائے گا دن قیامت کے ایک بوجھ', 'Whoever turns away from it (this Quran i.e. does not believe in it, nor acts on its orders), verily, they will bear a heavy burden (of sins) on the Day of Resurrection,', 'Whoever turns away from it shall certainly bear a heavy burden on Doomsday,'),
(2449, 20, 101, 5, 14, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'خٰلِدِیۡنَ فِیۡہِ ؕ وَ سَآءَ لَہُمۡ یَوۡمَ الۡقِیٰمَۃِ  حِمۡلًا ﴿۱۰۱﴾ۙ', 'ایسے لوگ ہمیشہ اس عذاب میں مبتلا رہیں گے اور یہ بوجھ قیامت کے روز انکے لئے برا ہوگا۔', 'سدا رہیں گے اس میں اور برا ہے اُن پر قیامت میں وہ بوجھ اٹھانے کا [۱۰۴]', 'They will abide in that (state in the Fire of Hell), and evil indeed will it be that load for them on the Day of Resurrection;', 'all such people living under it forever. And how evil for them will be that burden on the Doomsday!'),
(2450, 20, 102, 5, 14, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'یَّوۡمَ یُنۡفَخُ فِی الصُّوۡرِ وَ نَحۡشُرُ الۡمُجۡرِمِیۡنَ  یَوۡمَئِذٍ  زُرۡقًا ﴿۱۰۲﴾ۚۖ', 'جس روز صور پھونکا جائے گا اور ہم گناہگاروں کو یوں اکٹھا کریں گے کہ انکی آنکھیں نیلی نیلی ہوں گی۔', 'جس دن پھونکیں گے صور میں اور گھیر لائیں گے ہم گناہگاروں کو اُس دن نیلی آنکھیں [۱۰۵]', 'The Day when the Trumpet will be blown (the second blowing): that Day, We shall gather the Mujrimoon (criminals, polytheists, sinners, disbelievers in the Oneness of Allah, etc.) Zurqa: (blue or blind eyed with black faces).', 'The Day when the Horn (Sūr) will be blown, and We shall gather them together while they will have turned blue on that day,'),
(2451, 20, 103, 5, 14, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'یَّتَخَافَتُوۡنَ بَیۡنَہُمۡ  اِنۡ لَّبِثۡتُمۡ اِلَّا عَشۡرًا ﴿۱۰۳﴾', 'تو وہ آپس میں آہستہ آہستہ کہیں گے کہ تم دنیا میں صرف دس ہی دن رہے ہو۔', 'چپکے چپکے کہتے ہونگے آپس میں تم نہیں رہے مگر دس دن [۱۰۶]', 'In whispers will they speak to each other (saying): \"You stayed not longer than ten (days).\"', 'and will be whispering among themselves, “You did not remain (in graves) more than ten (days)”.'),
(2452, 20, 104, 5, 14, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'نَحۡنُ اَعۡلَمُ بِمَا یَقُوۡلُوۡنَ اِذۡ یَقُوۡلُ اَمۡثَلُہُمۡ طَرِیۡقَۃً اِنۡ لَّبِثۡتُمۡ اِلَّا یَوۡمًا ﴿۱۰۴﴾٪', 'جو باتیں یہ کریں گے ہم خوب جانتے ہیں۔ اس وقت ان میں سب سے اچھی راہ والا یعنی عاقل و ہوشمند کہے گا کہ نہیں بلکہ صرف ایک ہی روز ٹھہرے ہو۔', 'ہم کو خوب معلوم ہے جو کچھ کہتے ہیں [۱۰۷] جب بولے گا اُن میں اچھی راہ روشن والا تم نہیں رہے مگر ایک دن [۱۰۸]', 'We know very well what they will say, when the best among them in knowledge and wisdom will say: \"You stayed no longer than a day!\"', 'We know very well what they say, when the best of them in his ways will say, “You did not remain more than one day.”'),
(2453, 20, 105, 6, 15, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ یَسۡـَٔلُوۡنَکَ عَنِ الۡجِبَالِ فَقُلۡ یَنۡسِفُہَا رَبِّیۡ  نَسۡفًا ﴿۱۰۵﴾ۙ', 'اے نبی ﷺ لوگ تم سے پہاڑوں کے بارے میں دریافت کرتے ہیں کہدو کہ میرا رب انکو راکھ بنا کر بکھیر دے گا۔', 'اور تجھ سے پوچھتے ہیں پہاڑوں کا حال سو تو کہہ اُنکو بکھیر دے گا میرا رب اڑا کر', 'And they ask you concerning the mountains, say; \"My Lord will blast them and scatter them as particles of dust.', 'They ask you about the mountains. So, say (to them), “My Lord will crush them into dust thoroughly,'),
(2454, 20, 106, 6, 15, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَیَذَرُہَا  قَاعًا صَفۡصَفًا ﴿۱۰۶﴾ۙ', 'پھر زمین کو ہموار میدان کر چھوڑے گا۔', 'پھر کر چھوڑے گا زمین کو صاف میدان', '\"Then He shall leave it as a level smooth plain.', 'then will turn them into a leveled plain'),
(2455, 20, 107, 6, 15, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'لَّا  تَرٰی  فِیۡہَا عِوَجًا  وَّ  لَاۤ   اَمۡتًا ﴿۱۰۷﴾ؕ', 'جس میں تم کوئی نشیب و فراز نہ دیکھو گے۔', 'نہ دیکھے تو اُس میں موڑ اور نہ ٹیلا [۱۰۹]', '\"You will see therein nothing crooked or curved.\"', 'in which you will see neither a curve nor an uneven place.”'),
(2456, 20, 108, 6, 15, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'یَوۡمَئِذٍ یَّتَّبِعُوۡنَ الدَّاعِیَ لَا عِوَجَ لَہٗ ۚ وَ خَشَعَتِ الۡاَصۡوَاتُ لِلرَّحۡمٰنِ فَلَا تَسۡمَعُ   اِلَّا ہَمۡسًا ﴿۱۰۸﴾', 'اس روز لوگ پکارنے والے کے پیچھے چلیں گے اور اسکی پیروی سے انحراف نہ کر سکیں گے اور رحمٰن کے سامنے آوازیں پست ہو جائیں گی تو تم ایک ہلکی آواز کے سوا کوئی آواز نہ سنو گے۔', 'اُس دن پیچھے دوڑیں گے پکارنے والے کے ٹیڑھی نہیں جسکی بات [۱۱۰] اور دب جائیں گی آوازیں رحمٰن کے ڈر سے پھر تو نہ سنے گا مگر گھس گھسی آواز [۱۱۱]', 'On that Day mankind will follow strictly (the voice of) Allahs caller, no crookedness (that is without going to the right or left of that voice) will they show him (Allahs caller). And all voices will be humbled for the Most Beneficent (Allah), and nothing shall you hear but the low voice of their footsteps.', 'That day they will follow the caller who will find no deviation (from anyone). And the voices will turn low in awe for the RaHmān (All-Merciful, Allah). So, you will hear not but whispering.'),
(2457, 20, 109, 6, 15, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'یَوۡمَئِذٍ لَّا تَنۡفَعُ الشَّفَاعَۃُ  اِلَّا مَنۡ اَذِنَ  لَہُ  الرَّحۡمٰنُ  وَ رَضِیَ  لَہٗ  قَوۡلًا ﴿۱۰۹﴾', 'اس روز کسی کی سفارش کچھ فائدہ نہ دے گی مگر اس شخص کی جسے رحمٰن اجازت دے اور اسکی بات کو پسند فرمائے۔', 'اُس دن کام نہ آئے گی سفارش مگر جسکو اجازت رحمٰن نے دی اور پسند کی اسکی بات [۱۱۲]', 'On that day no intercession shall avail, except the one for whom the Most Beneficent (Allah) has given permission and whose word is acceptable to Him.', 'That day no intercession will be of any use to anyone, except the one whom the RaHmān (All-Merciful, Allah) has permitted and was pleased with his word.'),
(2458, 20, 110, 6, 15, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'یَعۡلَمُ مَا بَیۡنَ اَیۡدِیۡہِمۡ  وَ مَا خَلۡفَہُمۡ  وَ لَا یُحِیۡطُوۡنَ  بِہٖ  عِلۡمًا ﴿۱۱۰﴾', 'جو کچھ انکے آگے ہے اور جو کچھ انکے پیچھے ہے وہ اسکو جانتا ہے اور وہ اپنے علم سے اللہ کے علم کا احاطہ نہیں کر سکتے۔', 'وہ جانتا ہے جو کچھ ہے اُنکے آگے اور پیچھے اور یہ قابو میں نہیں لا سکتے اُسکو دریافت کر کر [۱۱۳]', 'He (Allah) knows what happens to them (His creatures) in this world, and what will happen to them (in the Hereafter), and they will never compass anything of His Knowledge.', 'He knows what is in front of them and what is behind them, and they do not encompass Him in (their) knowledge.'),
(2459, 20, 111, 6, 15, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ عَنَتِ الۡوُجُوۡہُ  لِلۡحَیِّ الۡقَیُّوۡمِ ؕ وَ قَدۡ خَابَ  مَنۡ  حَمَلَ  ظُلۡمًا ﴿۱۱۱﴾', 'اور اس زندہ و قائم کے روبرو منہ لٹک جائیں گے۔ اور جس نے ظلم کا بوجھ اٹھایا وہ نامراد رہا۔', 'اور رگڑتے ہیں منہ آگے اس جیتے ہمیشہ رہنے والے کے [۱۱۴] اور خراب ہوا جس نے بوجھ اٹھایا ظلم کا [۱۱۵]', 'And (all) faces shall be humbled before (Allah), the Ever Living, the One Who sustains and protects all that exists. And he who carried (a burden of) wrongdoing (i.e. he who disbelieved in Allah, ascribed partners to Him, and did deeds of His disobedience), became indeed a complete failure (on that Day).', 'All faces will be humbled before (Allah,) the Ever-Alive, the All-Sustaining; and the loser will be the one who bears (the burden of his) injustice.'),
(2460, 20, 112, 6, 15, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ مَنۡ یَّعۡمَلۡ مِنَ الصّٰلِحٰتِ وَ ہُوَ مُؤۡمِنٌ فَلَا یَخٰفُ ظُلۡمًا وَّ لَا ہَضۡمًا  ﴿۱۱۲﴾', 'اور جو نیک کام کرے گا اور مومن بھی ہوگا تو اسکو نہ ظلم کا خوف ہو گا اور نہ نقصان کا۔', 'اور جو  کوئی کرے کچھ بھلائیاں اور وہ ایمان بھی رکھتا ہو سو اُسکو ڈر نہیں بے انصافی کا اور نہ نقصان پہنچنے کا [۱۱۶]', 'And he who works deeds of righteousness, while he is a believer (in Islamic Monotheism) then he will have no fear of injustice, nor of any curtailment (of his reward).', 'But whoever does righteous deeds, while he is a believer, shall fear neither injustice nor curtailment (of his rewards).'),
(2461, 20, 113, 6, 15, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ کَذٰلِکَ اَنۡزَلۡنٰہُ  قُرۡاٰنًا عَرَبِیًّا وَّ صَرَّفۡنَا فِیۡہِ مِنَ الۡوَعِیۡدِ لَعَلَّہُمۡ یَتَّقُوۡنَ اَوۡ  یُحۡدِثُ  لَہُمۡ  ذِکۡرًا ﴿۱۱۳﴾', 'اور ہم نے اسکو اسی طرح کا قرآن عربی نازل کیا ہے اور اس میں طرح طرح کے ڈراوے بیان کر دیئے ہیں تاکہ لوگ پرہیزگار بنیں۔ یا اللہ انکے لئے نصیحت پیدا کر دے۔', 'اور اسی طرح اتارا ہم نے قرآن عربی زبان کا اور پھیر پھیر کر سنائی ہم نے اُس میں ڈرانے کی باتیں تاکہ وہ پرہیز کریں یا ڈالے اُنکے دل میں سوچ [۱۱۷]', 'And thus We have sent it down as a Quran in Arabic, and have explained therein in detail the warnings, in order that they may fear Allah, or that it may cause them to have a lesson from it (or to have the honour for believing and acting on its teachings).', 'And in this way We have sent it down to you as an Arabic Qur’ān, and have detailed in it some warnings in various ways, so that they may fear, or it may produce a lesson for them.'),
(2462, 20, 114, 6, 15, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَتَعٰلَی اللّٰہُ  الۡمَلِکُ الۡحَقُّ ۚ وَ لَا تَعۡجَلۡ بِالۡقُرۡاٰنِ مِنۡ قَبۡلِ اَنۡ یُّقۡضٰۤی اِلَیۡکَ وَحۡیُہٗ ۫ وَ  قُلۡ  رَّبِّ  زِدۡنِیۡ  عِلۡمًا ﴿۱۱۴﴾', 'تو اللہ جو سچا بادشاہ ہے عالی قدر ہے۔ اور قرآن کی وحی جو تمہاری طرف بھیجی جاتی ہے اس کے پورا ہونے سے پہلے قرآن کے پڑھنے میں جلدی نہ کیا کرو اور دعا کرو کہ میرے پروردگار مجھے اور زیادہ علم دے۔', 'سو بلند درجہ اللہ کا اُس سچے بادشاہ کا [۱۱۸] اور  تو جلدی نہ کر قرآن کے لینے میں جب تک کہ پورا نہ ہو چکے اُس کا اترنا اور کہہ اے رب زیادہ کر میری سمجھ [۱۱۹]', 'Then High above all be Allah, the True King. And be not in haste (O Muhammad SAW) with the Quran before its revelation is completed to you, and say: \"My Lord! Increase me in knowledge.\"', 'So High above all is Allah, the True King! And do not hasten with (reciting) the Qur’ān before its revelation to you is concluded, and say, “My Lord, improve me in knowledge.”'),
(2463, 20, 115, 6, 15, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ لَقَدۡ عَہِدۡنَاۤ  اِلٰۤی اٰدَمَ مِنۡ قَبۡلُ فَنَسِیَ  وَ  لَمۡ  نَجِدۡ  لَہٗ  عَزۡمًا ﴿۱۱۵﴾٪', 'اور ہم نے پہلے آدم سے عہد لیا تھا مگر وہ اسے بھول گئے اور ہم نے ان میں ارادے کی پختگی نہ پائی۔', 'اور ہم نے تاکید کر دی تھی آدم کو  اُس سے پہلے پھر بھول گیا اور نہ پائی ہم نے اسمیں کچھ ہمت [۱۲۰]', 'And indeed We made a covenant with Adam before, but he forgot, and We found on his part no firm will-power.', 'We had given a directive to ’Ādam earlier, then he forgot, and We did not find in him a firm resolve.'),
(2464, 20, 116, 7, 16, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ اِذۡ  قُلۡنَا لِلۡمَلٰٓئِکَۃِ اسۡجُدُوۡا لِاٰدَمَ فَسَجَدُوۡۤا   اِلَّاۤ   اِبۡلِیۡسَ ؕ اَبٰی ﴿۱۱۶﴾', 'اور جب ہم نے فرشتوں سے کہا کہ آدم کے آگے سجدہ کرو تو سب سجدے میں گر پڑے مگر ابلیس نے انکار کیا۔', 'اور جب کہا ہم نے فرشتوں کو سجدہ کرو آدم کو تو سجدہ میں گر پڑے مگر نہ مانا ابلیس نے', 'And (remember) when We said to the angels: \"Prostrate yourselves to Adam.\" They prostrated (all) except Iblees (Satan), who refused.', 'When We said to the angels, “Prostrate yourselves to ’Ādam”. So, all of them fell prostrate, except Iblīs , who refused.'),
(2465, 20, 117, 7, 16, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَقُلۡنَا یٰۤـاٰدَمُ  اِنَّ  ہٰذَا عَدُوٌّ لَّکَ وَ لِزَوۡجِکَ فَلَا یُخۡرِجَنَّکُمَا مِنَ الۡجَنَّۃِ فَتَشۡقٰی  ﴿۱۱۷﴾', 'اس پر ہم نے فرمایا کہ آدم یہ تمہارا اور تمہاری بیوی کا دشمن ہے تو یہ کہیں تم دونوں کو بہشت سے نہ نکلوا دے۔ پھر تم تکلیف میں پڑ جاؤ۔', 'پھر کہہ دیا ہم نے اے آدم یہ دشمن تیرا ہے اور تیرے جوڑے کا سو نکلوا نہ دے تمکو بہشت سے پھر تو پڑ جائے تکلیف میں [۱۲۱]', 'Then We said: \"O Adam! Verily, this is an enemy to you and to your wife. So let him not get you both out of Paradise, so that you be distressed in misery.', 'So, We said “’Ādam, this is an enemy to you and to your wife. So let him not expel you from Paradise, lest you should get into trouble.'),
(2466, 20, 118, 7, 16, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اِنَّ  لَکَ  اَلَّا  تَجُوۡعَ  فِیۡہَا وَ لَا  تَعۡرٰی ﴿۱۱۸﴾ۙ', 'یہاں تمکو یہ آسائش ہے کہ نہ بھوکے رہو نہ ننگے۔', 'تجھ کو یہ ملا ہے کہ نہ بھوکا ہو تو اُس میں اور نہ ننگا', 'Verily, you have (a promise from Us) that you will never be hungry therein nor naked.', 'Here you have the privilege that you will not be hungry nor will you be unclad,'),
(2467, 20, 119, 7, 16, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ اَنَّکَ لَا  تَظۡمَؤُا فِیۡہَا وَ لَا تَضۡحٰی ﴿۱۱۹﴾', 'اور یہ کہ نہ پیاسے رہو اور نہ دھوپ کھاؤ۔', 'اور یہ کہ نہ پیاس کھینچے تو اس میں اور نہ دھوپ [۱۲۲]', 'And you (will) suffer not from thirst therein nor from the suns heat.', 'and you will not be thirsty, nor will you be exposed to sun.”'),
(2468, 20, 120, 7, 16, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَوَسۡوَسَ اِلَیۡہِ الشَّیۡطٰنُ قَالَ یٰۤـاٰدَمُ ہَلۡ اَدُلُّکَ عَلٰی شَجَرَۃِ الۡخُلۡدِ وَ مُلۡکٍ لَّا یَبۡلٰی ﴿۱۲۰﴾', 'پھر شیطان نے انکے دل میں وسوسہ ڈالا۔ اور کہا کہ آدم بھلا میں تمکو ایسا درخت بتاؤں جو ہمیشہ کی زندگی کا باعث ہو اور ایسی بادشاہت کہ کبھی زائل نہ ہو۔', 'پھر جی میں ڈالا اُسکے شیطان نے کہا اے آدم میں بتاؤں تجھ کو درخت سدا زندہ رہنے کا اور بادشاہی جو پرانی نہ ہو [۱۲۳]', 'Then Shaitan (Satan) whispered to him, saying : \"O Adam! Shall I lead you to the Tree of Eternity and to a kingdom that will never waste away?\"', 'Then the Satan instigated him. He said, “’Ādam, shall I guide you to the tree of eternity and to an empire that does not decay?”'),
(2469, 20, 121, 7, 16, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَاَکَلَا مِنۡہَا فَبَدَتۡ لَہُمَا سَوۡاٰتُہُمَا وَ طَفِقَا یَخۡصِفٰنِ عَلَیۡہِمَا مِنۡ وَّرَقِ الۡجَنَّۃِ ۫ وَ عَصٰۤی  اٰدَمُ   رَبَّہٗ  فَغَوٰی  ﴿۱۲۱﴾۪ۖ', 'سو دونوں نے اس درخت کا پھل کھا لیا تو ان پر انکی شرمگاہیں ظاہر ہو گئیں اور وہ اپنے اوپر بہشت کے پتے چپکانے لگے اور آدم نے اپنے پروردگار کے حکم کے خلاف کیا تو وہ اپنے مقصد سے بے راہ ہو گئے۔', 'پھر دونوں نے کھا لیا اُسمیں سے پھر کھل گئیں اُن پر اُنکی بری چیزیں اور لگے گانٹھنے اپنے اوپر پتے بہشت کے [۱۲۴] اور حکم ٹالا آدم نے اپنے رب کا پھر راہ سے بہکا', 'Then they both ate of the tree, and so their private parts appeared to them, and they began to stick on themselves the leaves from Paradise for their covering. Thus did Adam disobey his Lord, so he went astray.', 'So, both of them Ādam and Hawwā’ (Eve)] ate from it, and their parts of shame were exposed to them, and they started stitching on themselves some of the leaves of Paradise. And ’Ādam disobeyed his Lord, and erred.'),
(2470, 20, 122, 7, 16, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'ثُمَّ  اجۡتَبٰہُ رَبُّہٗ  فَتَابَ عَلَیۡہِ  وَ  ہَدٰی ﴿۱۲۲﴾', 'پھر انکے پروردگار نے انکو نوازا تو ان پر مہربانی سے توجہ فرمائی اور سیدھی راہ بتائی۔', 'پھر نواز دیا اُسکو اُسکے رب نے پھر متوجہ ہوا اُس پر اور راہ پر لایا [۱۲۵]', 'Then his Lord chose him, and turned to him with forgiveness, and gave him guidance.', 'Thereafter his Lord chose him. So He accepted his repentance and gave (him) guidance.'),
(2471, 20, 123, 7, 16, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ اہۡبِطَا مِنۡہَا جَمِیۡعًۢا بَعۡضُکُمۡ لِبَعۡضٍ عَدُوٌّ ۚ فَاِمَّا یَاۡتِیَنَّکُمۡ مِّنِّیۡ ہُدًی ۬ۙ فَمَنِ اتَّبَعَ ہُدَایَ  فَلَا  یَضِلُّ  وَ لَا  یَشۡقٰی  ﴿۱۲۳﴾', 'فرمایا کہ تم دونوں یہاں سے نیچے اتر جاؤ۔ تم میں بعض بعض کے دشمن ہوں گے پھر اگر میری طرف سے تمہارے پاس ہدایت آئے تو جو شخص میری ہدایت کی پیروی کرے گا وہ نہ گمراہ ہو گا اور نہ تکلیف میں پڑے گا۔', 'فرمایا اترو یہاں سے دونوں اکٹھے رہو ایک دوسرے کے دشمن [۱۲۶] پھر اگر پہنچے تمکو میری طرف سے ہدایت [۱۲۷] پھر جو چلا میری بتلائی راہ پر سو نہ وہ بہکے گا اور نہ وہ تکلیف میں پڑے گا [۱۲۸]', '(Allah) said:\"Get you down (from the Paradise to the earth), both of you, together, some of you are an enemy to some others. Then if there comes to you guidance from Me, then whoever follows My Guidance shall neither go astray, nor fall into distress and misery.', 'He said (to ’Ādam and Iblīs), “Go down from here, all of you, some of you enemies of some others. Then, should some guidance come to you from Me, the one who follows My guidance shall not go astray, nor shall he be in trouble.'),
(2472, 20, 124, 7, 16, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ مَنۡ اَعۡرَضَ عَنۡ ذِکۡرِیۡ فَاِنَّ لَہٗ مَعِیۡشَۃً ضَنۡکًا وَّ نَحۡشُرُہٗ یَوۡمَ الۡقِیٰمَۃِ  اَعۡمٰی ﴿۱۲۴﴾', 'اور جو میری نصیحت سے منہ پھیرے گا اسکی زندگی تنگ ہو جائے گی اور قیامت کو ہم اسے اندھا کر کے اٹھائیں گے۔', 'اور جس نے منہ پھیرا میری یاد سے تو اُسکو ملنی ہے گذران تنگی کی [۱۲۹] اور لائیں گے ہم اُسکو دن قیامت کے اندھا [۱۳۰]', '\"But whosoever turns away from My Reminder (i.e. neither believes in this Quran nor acts on its orders, etc.) verily, for him is a life of hardship, and We shall raise him up blind on the Day of Resurrection.\"', 'As for the one who turns away from My message, he shall have a straitened life, and We shall raise him blind on the Day of Judgment.”'),
(2473, 20, 125, 7, 16, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ رَبِّ  لِمَ حَشَرۡتَنِیۡۤ  اَعۡمٰی وَ قَدۡ کُنۡتُ  بَصِیۡرًا ﴿۱۲۵﴾', 'وہ کہے گا کہ میرے پروردگار تو نے مجھے اندھا کر کے کیوں اٹھایا میں تو دیکھتا بھالتا تھا۔', 'وہ کہے گا اے رب کیوں اٹھا لایا تو مجھ کو اندھا اور میں تو تھا دیکھنے والا [۱۳۱]', 'He will say:\"O my Lord! Why have you raised me up blind, while I had sight (before).\"', 'He will say, “My Lord, why did you raise me blind while I was sighted?”'),
(2474, 20, 126, 7, 16, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قَالَ  کَذٰلِکَ اَتَتۡکَ اٰیٰتُنَا فَنَسِیۡتَہَا ۚ  وَکَذٰلِکَ  الۡیَوۡمَ  تُنۡسٰی ﴿۱۲۶﴾', 'اللہ فرمائے گا کہ ایسا ہی چاہیے تھا تیرے پاس ہماری آیتیں آئیں تو تو نے انکو بھلا دیا۔ اسی طرح آج ہم تجھ کو بھلا دیں گے۔', 'فرمایا یونہی پہنچی تھیں تجھ کو میری آیتیں پھر تو نے انکو بھلا دیا اور اسی طرح آج تجھ کو بھلا دیں گے [۱۳۲]', '(Allah) will say: \"Like this, Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) came unto you, but you disregarded them (i.e. you left them, did not think deeply in them, and you turned away from them), and so this Day, you will be neglected (in the Hell-fire, away from Allahs Mercy).\"', 'He will say, “In the similar manner as Our signs came to you, and you had ignored them. In the same way you will be ignored today.”'),
(2475, 20, 127, 7, 16, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ کَذٰلِکَ نَجۡزِیۡ مَنۡ اَسۡرَفَ وَ لَمۡ  یُؤۡمِنۡۢ بِاٰیٰتِ رَبِّہٖ ؕ وَ لَعَذَابُ الۡاٰخِرَۃِ اَشَدُّ وَ اَبۡقٰی  ﴿۱۲۷﴾', 'اور جو شخص حد سے نکل جائے اور اپنے پروردگار کی آیتوں پر ایمان نہ لائے ہم اسکو ایسا ہی بدلہ دیتے ہیں۔ اور آخرت کا عذاب بہت سخت اور ہمیشہ باقی رہنے والا ہے۔', 'اور اسی طرح بدلہ دیں گے ہم اُسکو جو حد سے نکلا اور یقین نہ لایا اپنے رب کی باتوں پر [۱۳۳] اور آخرت کا عذاب سخت ہے اور بہت باقی رہنے والا [۱۳۴]', 'And thus do We requite him who transgresses beyond bounds (i.e. commits the great sins and disobeys his Lord (Allah) and believes not in His Messengers, and His revealed Books, like this Quran, etc.), and believes not in the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of his Lord, and the torment of the Hereafter is far more severe and more lasting.', 'Thus We recompense him who exceeds the limits and does not believe in the signs of his Lord. Certainly the punishment of the Hereafter is more severe and more lasting.'),
(2476, 20, 128, 7, 16, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'اَفَلَمۡ یَہۡدِ لَہُمۡ کَمۡ اَہۡلَکۡنَا قَبۡلَہُمۡ مِّنَ الۡقُرُوۡنِ یَمۡشُوۡنَ فِیۡ مَسٰکِنِہِمۡ ؕ اِنَّ فِیۡ ذٰلِکَ  لَاٰیٰتٍ  لِّاُولِی  النُّہٰی ﴿۱۲۸﴾٪', 'تو کیا یہ بات ان لوگوں کے لئے موجب ہدایت نہ ہوئی کہ ہم ان سے پہلے بہت سے فرقوں کو ہلاک کر چکے ہیں جنکے رہنے کے مقامات میں یہ چلتے پھرتے ہیں عقل والوں کے لئے اس میں بہت سی نشانیاں ہیں۔', 'سو کیا اُنکو سمجھ نہ آئی اس بات سے کہ کتنی غارت کر دیں ہم نے اُن سے پہلے جماعتیں یہ لوگ پھرتے ہیں اُنکی جگہوں میں [۱۳۵] اس میں خوب نشانیاں ہیں عقل رکھنے والوں کو', 'Is it not a guidance for them (to know) how many generations We have destroyed before them, in whose dwellings they walk? Verily, in this are signs indeed for men of understanding.', 'Did it give them no guidance (to realize) how many generations We have destroyed prior to them in whose dwellings they (often) walk around? Surely, in this there are signs for the men of reason.'),
(2477, 20, 129, 8, 17, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ لَوۡ لَا کَلِمَۃٌ سَبَقَتۡ مِنۡ رَّبِّکَ لَکَانَ لِزَامًا  وَّ  اَجَلٌ  مُّسَمًّی ﴿۱۲۹﴾ؕ', 'اور اگر ایک بات تمہارے پروردگار کی طرف سے پہلے صادر اور جزائے اعمال کے لئے ایک میعاد مقرر نہ ہو چکی ہوتی تو نزول عذاب لازم ہو جاتا۔', 'اور اگر نہ ہوتی ایک بات کہ نکل چکی تیرے ب کی طرف سے تو ضرور ہو جاتی مٹھ بھیڑ اور اگر نہ ہوتا وعدہ مقرر کیا گیا [۱۳۶]', 'And had it not been for a Word that went forth before from your Lord, and a term determined, (their punishment) must necessarily have come (in this world).', 'But for a word from your Lord that had passed earlier, and an appointed time that had been fixed, it (the punishment) would have been inevitable (for them).'),
(2478, 20, 130, 8, 17, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'فَاصۡبِرۡ عَلٰی مَا یَقُوۡلُوۡنَ وَ سَبِّحۡ بِحَمۡدِ رَبِّکَ قَبۡلَ طُلُوۡعِ الشَّمۡسِ وَ قَبۡلَ غُرُوۡبِہَا ۚ وَ مِنۡ اٰنَآیِٔ الَّیۡلِ فَسَبِّحۡ وَ اَطۡرَافَ النَّہَارِ لَعَلَّکَ تَرۡضٰی ﴿۱۳۰﴾', 'پس جو کچھ یہ بکواس کرتے ہیں اس پر صبر کرو۔ اور سورج کے نکلنے سے پہلے اور اسکے غروب ہونے سے پہلے اپنے پروردگار کی تسبیح و تحمید کیا کرو اور رات کی کچھ گھڑیوں میں بھی اسکی تسبیح کیا کرو اور دن کے مختلف اوقات یعنی دوپہر کے وقت بھی تاکہ تم خوش ہو جاؤ۔', 'سو تو سہتا رہ جو وہ کہیں [۱۳۷] اور پڑھتا رہ خوبیاں اپنے رب کی سورج نکلنے سے پہلے اور غروب ہونے سے پہلے [۱۳۸] اور کچھ گھڑیوں میں رات کی پڑھا کر [۱۳۹] اور دن کی حدوں پر [۱۴۰] شاید تو راضی ہو [۱۴۱]', 'So bear patiently (O Muhammad SAW) what they say, and glorify the praises of your Lord before the rising of the sun, and before its setting, and during some of the hours of the night, and at the sides of the day (an indication for the five compulsory congregational prayers), that you may become pleased with the reward which Allah shall give you.', 'So, (O messenger,) endure with patience what they say, and proclaim the purity and praise of your Lord before sunrise and before sunset. And in some hours of night, proclaim His purity, and at points of the day as well, so that you may be pleased.'),
(2479, 20, 131, 8, 17, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ لَا تَمُدَّنَّ عَیۡنَیۡکَ  اِلٰی مَا مَتَّعۡنَا بِہٖۤ اَزۡوَاجًا مِّنۡہُمۡ زَہۡرَۃَ الۡحَیٰوۃِ  الدُّنۡیَا ۬ۙ لِنَفۡتِنَہُمۡ فِیۡہِ ؕ وَ  رِزۡقُ  رَبِّکَ خَیۡرٌ  وَّ  اَبۡقٰی  ﴿۱۳۱﴾', 'اور کئ طرح کے لوگوں کو جو ہم نے دنیا کی زندگی میں آرائش کی چیزوں سے نوازا ہے تاکہ انکی آزمائش کریں ان پر نگاہ نہ کرنا اور تمہارے پروردگار کی عطا فرمائی ہوئی روزی بہت بہتر اور باقی رہنے والی ہے۔', 'اور مت پسار اپنی آنکھیں اُس چیز پر جو فائدہ اٹھانے کو دی ہم نے ان طرح طرح کے لوگوں کو رونق دنیا کی زندگی کی اُنکے جانچے کو اور تیرے رب کی دی ہوئی روزی بہتر ہے اور بہت باقی رہنے والی [۱۴۲]', 'And strain not your eyes in longing for the things We have given for enjoyment to various groups of them (polytheists and disbelievers in the Oneness of Allah), the splendour of the life of this world that We may test them thereby. But the provision (good reward in the Hereafter) of your Lord is better and more lasting.', 'Never stretch your eyes towards the things We have given to some groups of them to enjoy, so that We put them to test thereby, it being merely glamour of the worldly life. And the bounty of your Lord is much better and more lasting.'),
(2480, 20, 132, 8, 17, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ اۡمُرۡ اَہۡلَکَ بِالصَّلٰوۃِ وَ اصۡطَبِرۡ عَلَیۡہَا ؕ لَا نَسۡـَٔلُکَ رِزۡقًا ؕ نَحۡنُ نَرۡزُقُکَ ؕ وَ الۡعَاقِبَۃُ  لِلتَّقۡوٰی ﴿۱۳۲﴾', 'اور اپنے گھر والوں کو نماز کا حکم کرو اور اس پر قائم رہو ہم تم سے روزی کے خواستگار نہیں بلکہ تمہیں ہم روزی دیتے ہیں اور نیک انجام اہل تقوٰی کا ہے۔', 'اور حکم کر اپنے گھر والوں کو نماز کا اور خود بھی قائم رہ اُس پر [۱۴۳] ہم نہیں مانگتے تجھ سے روزی ہم روزی دیتے ہیں تجھ کو اور انجام بھلا ہے پرہیزگاری کا [۱۴۴]', 'And enjoin As-Salat (the prayer) on your family, and be patient in offering them (i.e. the Salat (prayers)). We ask not of you a provision (i.e. to give Us something: money, etc.); We provide for you. And the good end (i.e. Paradise) is for the Muttaqoon (pious - see V.2:2).', 'Bid your family to perform Salāh, and adhere to it yourself. We ask no provision from you. We give provision to you. And the ultimate end is in favour of Taqwā (God-fearing, and piety).'),
(2481, 20, 133, 8, 17, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ قَالُوۡا لَوۡ لَا یَاۡتِیۡنَا بِاٰیَۃٍ مِّنۡ رَّبِّہٖ ؕ اَوَ لَمۡ  تَاۡتِہِمۡ بَیِّنَۃُ  مَا فِی الصُّحُفِ الۡاُوۡلٰی ﴿۱۳۳﴾', 'اور کہتے ہیں کہ یہ پیغمبر اپنے پروردگار کی طرف سے ہمارے پاس کوئی نشانی کیوں نہیں لائے۔ کیا انکے پاس پہلی کتابوں کی نشانی نہیں آئی۔', 'اور لوگ کہتے ہیں کہ کیوں نہیں لے آتا ہمارے پاس کوئی نشانی اپنے رب سے [۱۴۵] کیا پہنچ نہیں چکی اُنکو نشانی اگلی کتابوں میں کی [۱۴۶]', 'They say: \"Why does he not bring us a sign (proof) from his Lord?\" Has there not come to them the proof of that which is (written) in the former papers (Scriptures, i.e. the Taurat (Torah), and the Injeel (Gospel), etc. about the coming of the Prophet Muhammad SAW ).', 'They say, “Why does he not bring to us a sign from his Lord?” Has there not come to them the clear sign of what is contained in the earlier Scriptures?'),
(2482, 20, 134, 8, 17, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'وَ لَوۡ اَنَّـاۤ  اَہۡلَکۡنٰہُمۡ بِعَذَابٍ مِّنۡ قَبۡلِہٖ لَقَالُوۡا رَبَّنَا لَوۡ لَاۤ  اَرۡسَلۡتَ  اِلَیۡنَا رَسُوۡلًا فَنَتَّبِعَ اٰیٰتِکَ مِنۡ قَبۡلِ اَنۡ  نَّذِلَّ  وَ  نَخۡزٰی  ﴿۱۳۴﴾', 'اور اگر ہم انکو پیغمبر کے بھیجنے سے پیشتر کسی عذاب سے ہلاک کر دیتے تو یہ کہتے کہ اے ہمارے پروردگار تو نے ہماری طرف کوئی پیغمبر کیوں نہ بھیجا کہ ہم ذلیل اور رسوا ہونے سے پہلے تیرے احکام کی پیروی کرتے۔', 'اور اگر ہم ہلاک کر دیتے اُنکو کسی آفت میں اس سے پہلے تو کہتے اے رب کیوں نہ بھیجا ہم تک کسی کو پیغام دیکر کہ ہم چلتے تیری کتاب پر ذلیل اور رسوا ہونے سے پہلے', 'And if We had destroyed them with a torment before this (i.e. Messenger Muhammad SAW and the Quran), they would surely have said: \"Our Lord! If only You had sent us a Messenger, we should certainly have followed Your Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), before we were humiliated and disgraced.\"', 'And if We had destroyed them with a punishment before it, they would have said, “Our Lord, why did you not send a messenger to us, so that we might have followed Your signs before we were humiliated and put to disgrace?”'),
(2483, 20, 135, 8, 17, 16, 'قَالَ اَلَمۡ', 'طٰہٰ', 'قُلۡ کُلٌّ مُّتَرَبِّصٌ فَتَرَبَّصُوۡا ۚ فَسَتَعۡلَمُوۡنَ مَنۡ  اَصۡحٰبُ الصِّرَاطِ السَّوِیِّ  وَ مَنِ  اہۡتَدٰی ﴿۱۳۵﴾٪', 'کہدو کہ سب نتائج اعمال کے منتظر ہیں سو تم بھی منتظر رہو۔ عنقریب تمکو معلوم ہو جائے گا کہ دین کے سیدھے رستے پر چلنے والے کون ہیں اور جنت کی طرف راہ پانے والے کون ہیں ہم یا تم۔', 'تو کہہ ہر کوئی راہ دیکھتا ہے سو تم بھی راہ دیکھو اور آئندہ جان لو گے کون ہیں سیدھی راہ  والے اور کس نے راہ پائی [۱۴۷]', 'Say (O Muhammad SAW): \"Each one (believer and disbeliever, etc.) is waiting, so wait you too, and you shall know who are they that are on the Straight and Even Path (i.e. Allahs Religion of Islamic Monotheism), and who are they that have let themselves be guided (on the Right Path).', 'Say, “Everyone is waiting. So wait, then you will know who the people of the straight path are and who has followed the right guidance.”'),
(2484, 21, 1, 1, 1, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'اِقۡتَرَبَ لِلنَّاسِ حِسَابُہُمۡ وَ ہُمۡ فِیۡ غَفۡلَۃٍ  مُّعۡرِضُوۡنَ ۚ﴿۱﴾', 'لوگوں کا حساب اعمال کا وقت نزدیک آ پہنچا ہے اور وہ غفلت میں پڑے اس سے منہ پھیر رہے ہیں۔', 'نزدیک آ گیا لوگوں کے اُنکے حساب کا وقت اور  وہ بیخبر ٹلا رہے ہیں [۱]', 'Draws near for mankind their reckoning, while they turn away in heedlessness.', 'The reckoning of the people has drawn near to them, while they are in negligence, turning away (from its signs).'),
(2485, 21, 2, 1, 1, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'مَا  یَاۡتِیۡہِمۡ مِّنۡ ذِکۡرٍ مِّنۡ رَّبِّہِمۡ مُّحۡدَثٍ اِلَّا اسۡتَمَعُوۡہُ  وَ ہُمۡ  یَلۡعَبُوۡنَ ۙ﴿۲﴾', 'انکے پاس کوئی نئی نصیحت ان کے پروردگار کی طرف سے نہیں آتی مگر وہ اسے کھیلتے ہوئے سنتے ہیں۔', 'کوئی نصیحت نہیں پہنچتی اُنکو  اُنکے رب سے نئی مگر اُسکو سنتے ہیں کھیل میں لگےہوئے', 'Comes not unto them an admonition (a chapter of the Quran) from their Lord as a recent revelation but they listen to it while they play,', 'No fresh message of advice comes to them from their Lord, but they listen to it as if they were playing,'),
(2486, 21, 3, 1, 1, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'لَاہِیَۃً  قُلُوۡبُہُمۡ ؕ وَ اَسَرُّوا النَّجۡوَی ٭ۖ الَّذِیۡنَ ظَلَمُوۡا ٭ۖ ہَلۡ ہٰذَاۤ  اِلَّا بَشَرٌ مِّثۡلُکُمۡ ۚ اَفَتَاۡتُوۡنَ السِّحۡرَ  وَ اَنۡتُمۡ تُبۡصِرُوۡنَ ﴿۳﴾', 'ان کے دل غفلت میں پڑے ہوئے ہیں۔ اور ظالم لوگ آپس میں چپکے چپکے باتیں کرتے ہیں کہ یہ شخص کچھ بھی نہیں مگر تمہارے جیسا آدمی ہے تو تم آنکھوں دیکھے جادو کی لپیٹ میں کیوں آتے ہو۔', 'کھیل میں پڑے ہیں دل اُنکے [۲] اور چھپا کر مصلحت کی بے انصافوں نے یہ شخص کون ہے ایک آدمی ہےتم ہی جیسا پھر کیوں پھنستے ہو اُسکے جاد ومیں آنکھوں دیکھتے [۳]', 'With their hearts occupied (with evil things) those who do wrong, conceal their private counsels, (saying): \"Is this (Muhammad SAW) more than a human being like you? Will you submit to magic while you see it?\"', 'their hearts paying no heed. And the wrongdoers whisper in secret, “This one is nothing but a mortal like you. Would you then go along with sorcery while you can see (the reality)?”'),
(2487, 21, 4, 1, 1, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قٰلَ رَبِّیۡ یَعۡلَمُ الۡقَوۡلَ فِی السَّمَآءِ وَ الۡاَرۡضِ ۫ وَ ہُوَ  السَّمِیۡعُ  الۡعَلِیۡمُ ﴿۴﴾', 'پیغمبر ﷺ نے کہا کہ جو بات آسمان اور زمین میں کہی جاتی ہے میرا پروردگار اسے جانتا ہے۔ اور وہ سننے والا ہے جاننے والا ہے۔', 'اُس نے کہا میرے رب کو خبر ہے بات کی آسمان میں ہو یا زمین میں اور وہ ہے سننے والا جاننے والا [۴]', 'He (Muhammad SAW) said: \"My Lord knows (every) word (spoken) in the heavens and on earth. And He is the All-Hearer, the All-Knower.\"', 'He (the prophet) said, “My Lord knows all that is spoken in the heavens and the earth, and He is the All-Hearing, the All-Knowing.”'),
(2488, 21, 5, 1, 1, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'بَلۡ قَالُوۡۤا اَضۡغَاثُ اَحۡلَامٍۭ بَلِ افۡتَرٰىہُ بَلۡ ہُوَ شَاعِرٌ ۚۖ فَلۡیَاۡتِنَا بِاٰیَۃٍ کَمَاۤ اُرۡسِلَ  الۡاَوَّلُوۡنَ ﴿۵﴾', 'بلکہ ظالم کہنے لگے کہ یہ قرآن پریشان باتیں ہیں جو خواب میں دیکھ لی ہیں نہیں بلکہ اس نے اسکو اپنی طرف سے بنا لیا ہے نہیں بلکہ یہ ایک شاعر ہے تو جیسے پہلے پیغمبر نشانیاں دے کر بھیجے گئے تھے اسی طرح یہ بھی ہمارے پاس کوئی نشانی لائے۔', 'اُسکو چھوڑ کر کہتے ہیں بیہودہ خواب ہیں نہیں جھوٹ باندھ لیا ہے نہیں شعر کہتا ہے پھر چاہیئے لے آئے ہمارے پاس کوئی نشانی جیسے پیغام لیکر آئے ہیں پہلے [۵]', 'Nay, they say:\"These (revelations of the Quran which are inspired to Muhammad SAW) are mixed up false dreams! Nay, he has invented it! Nay, he is a poet! Let him then bring us an Ayah (sign as a proof) like the ones (Prophets) that were sent before (with signs)!\"', 'Further they said, “(The Qur’ān is) a mixture of jumble dreams. Rather, he (the prophet) has fabricated it. Rather, he is a poet. So, let him bring a sign to us, as the earlier ones were sent with.”'),
(2489, 21, 6, 1, 1, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'مَاۤ  اٰمَنَتۡ قَبۡلَہُمۡ مِّنۡ قَرۡیَۃٍ اَہۡلَکۡنٰہَا ۚ اَفَہُمۡ  یُؤۡمِنُوۡنَ ﴿۶﴾', 'ان سے پہلے جن بستیوں کو ہم نے ہلاک کیا وہ ایمان نہیں لاتی تھیں۔ تو کیا یہ ایمان لے آئیں گے۔', 'نہیں مانا اُن سے پہلے کسی بستی نے جنکو غارت کر دیا ہم نے کیا اب یہ مان لیں گے [۶]', 'Not one of the towns (populations), of those which We destroyed, believed before them (though We sent them signs), will they then believe?', 'Not a single town from those whom We destroyed came to believe before them. So, will they believe?'),
(2490, 21, 7, 1, 1, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ مَاۤ  اَرۡسَلۡنَا قَبۡلَکَ اِلَّا رِجَالًا نُّوۡحِیۡۤ اِلَیۡہِمۡ فَسۡـَٔلُوۡۤا اَہۡلَ الذِّکۡرِ  اِنۡ  کُنۡتُمۡ  لَا تَعۡلَمُوۡنَ ﴿۷﴾', 'اور ہم نے تم سے پہلے آدمی ہی پیغمبر بنا کر بھیجے جنکی طرف ہم وحی بھیجتے تھے۔ اگر تم نہیں جانتے تو جو یاد رکھتے ہیں ان سے پوچھ لو۔', 'اور پیغام نہیں بھیجا ہم نے تجھ سے پہلے مگر  یہی مردوں کے ہاتھ وحی بھیجتے تھے ہم اُنکو سو پوچھ لو یاد رکھنے والوں سے اگر تم نہیں جانتے [۷]', 'And We sent not before you (O Muhammad SAW) but men to whom We inspired, so ask the people of the Reminder (Scriptures - the Taurat (Torah), the Injeel (Gospel)) if you do not know.', 'And We did not send before you messengers except men whom We inspired with revelation. So, ask the people (having the knowledge) of the Message, if you do not know.'),
(2491, 21, 8, 1, 1, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ مَا جَعَلۡنٰہُمۡ جَسَدًا لَّا یَاۡکُلُوۡنَ الطَّعَامَ  وَ مَا  کَانُوۡا  خٰلِدِیۡنَ ﴿۸﴾', 'اور ہم نے انکے ایسے جسم نہیں بنائے تھے کہ کھانا نہ کھائیں اور نہ وہ ہمیشہ رہنے والے تھے۔', 'اور نہیں بنائے تھے ہم نے اُنکے ایسے بدن کہ وہ کھانا نہ کھائیں اور نہ تھے وہ ہمیشہ رہ جانے والے [۸]', 'And We did not create them (the Messengers, with) bodies that ate not food, nor were they immortals,', 'We did not make them such bodies as ate no food, nor were they immortal.'),
(2492, 21, 9, 1, 1, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'ثُمَّ  صَدَقۡنٰہُمُ  الۡوَعۡدَ  فَاَنۡجَیۡنٰہُمۡ وَ مَنۡ  نَّشَآءُ وَ اَہۡلَکۡنَا الۡمُسۡرِفِیۡنَ ﴿۹﴾', 'پھر ہم نے انکے بارے میں اپنا وعدہ سچا کر دیا تو انکو اور جسکو چاہا نجات دی اور حد سے نکل جانے والوں کو ہلاک کر دیا۔', 'پھر سچا کر دیا ہم نے اُن سے وعدہ سو بچا دیا اُنکو اور جسکو ہم نے چاہا اور غارت کر دیا حد  سے نکلے والوں کو [۹]', 'Then We fulfilled to them the promise, and We saved them and those whom We willed, but We destroyed Al-Musrifoon (i.e. extravagants in oppression, polytheism and in sin).', 'Then We caused the promise to come true for them, so We saved them and those whom We willed, and destroyed the transgressors.'),
(2493, 21, 10, 1, 1, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'لَقَدۡ اَنۡزَلۡنَاۤ  اِلَیۡکُمۡ  کِتٰبًا فِیۡہِ  ذِکۡرُکُمۡ ؕ اَفَلَا  تَعۡقِلُوۡنَ ﴿٪۱۰﴾', 'ہم نے تمہاری طرف ایسی کتاب نازل کی ہے جس میں تمہارا تذکرہ ہے کیا تم نہیں سمجھتے؟', 'ہم نے اتاری ہے تمہاری طرف کتاب کہ اُس میں تمہارا ذکر ہے کیا تم سمجھتے نہیں [۱۰]', 'Indeed, We have sent down for you (O mankind) a Book, (the Quran) in which there is Dhikrukum, (your Reminder or an honour for you i.e. honour for the one who follows the teaching of the Quran and acts on its orders). Will you not then understand?', 'Surely, We have sent down to you (O people of Arabia) a book having a good counsel for you. So, do you not understand?'),
(2494, 21, 11, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ کَمۡ قَصَمۡنَا مِنۡ قَرۡیَۃٍ کَانَتۡ ظَالِمَۃً وَّ  اَنۡشَاۡنَا  بَعۡدَہَا  قَوۡمًا  اٰخَرِیۡنَ  ﴿۱۱﴾', 'اور ہم نے بہت سی بستیوں کو جو ظالم تھیں پیس ڈالا اور انکے بعد اور لوگ پیدا کر دیئے۔', 'اور کتنی پیس ڈالیں ہم نے بسیتاں جو تھیں گنہگار اور اٹھا کھڑے کئے اُنکے پیچھے اور لوگ [۱۱]', 'How many a town (community), that were wrong-doers, have We destroyed, and raised up after them another people!', 'How many a town, that were unjust, have We crushed and raised up after them another people!'),
(2495, 21, 12, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'فَلَمَّاۤ  اَحَسُّوۡا بَاۡسَنَاۤ  اِذَا ہُمۡ  مِّنۡہَا یَرۡکُضُوۡنَ ﴿ؕ۱۲﴾', 'جب انہوں نے ہمارے عذاب کو دیکھا تو لگے اس سے بھاگنے۔', 'پھر جب آہٹ پائی انہوں نے ہماری آفت کی تب لگے وہاں سے ایڑ کرنے', 'Then, when they perceived (saw) Our Torment (coming), behold, they (tried to) flee from it.', 'So, as soon as they sensed Our punishment (approaching them), they started fleeing from it.'),
(2496, 21, 13, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'لَا تَرۡکُضُوۡا وَ ارۡجِعُوۡۤا اِلٰی مَاۤ  اُتۡرِفۡتُمۡ فِیۡہِ وَ مَسٰکِنِکُمۡ  لَعَلَّکُمۡ  تُسۡـَٔلُوۡنَ ﴿۱۳﴾', 'مت بھاگو اور جن نعمتوں میں تم عیش و آسائش کرتے تھے انکی اور اپنے گھروں کی طرف لوٹ جاؤ شائد تم سے اس بارے میں دریافت کیا جائے۔', 'ایڑ مت کرو اور لوٹ جاؤ جہاں تم نے عیش کیا تھا اور اپنے گھروں میں شاید کوئی تمکو پوچھے [۱۲]', 'Flee not, but return to that wherein you lived a luxurious life, and to your homes, in order that you may be questioned.', '(It was said to them,) “Do not flee, and go back to the luxuries you were made to enjoy, and to your dwellings. May be you are asked questions.”'),
(2497, 21, 14, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قَالُوۡا یٰوَیۡلَنَاۤ  اِنَّا کُنَّا ظٰلِمِیۡنَ ﴿۱۴﴾', 'کہنے لگے ہائے شامت بیشک ہم ظالم تھے۔', 'کہنے لگے ہائے خرابی ہم تھے بیشک گنہگار', 'They cried: \"Woe to us! Certainly! We have been Zalimoon (polytheists, wrong-doers and disbelievers in the Oneness of Allah, etc.).\"', 'They said, “Alas for us! We were wrongdoers indeed.”'),
(2498, 21, 15, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'فَمَا زَالَتۡ تِّلۡکَ دَعۡوٰىہُمۡ  حَتّٰی  جَعَلۡنٰہُمۡ  حَصِیۡدًا  خٰمِدِیۡنَ ﴿۱۵﴾', 'تو وہ برابر اسی طرح پکارتے رہے یہاں تک کہ ہم نے انکو کھیتی کی طرح کاٹ کر اور آگ کی طرح بجھا کر ڈھیر کر دیا۔', 'پھر برابر یہی رہی اُنکی فریاد یہاں تک کہ ڈھیر کر دیے گئے کاٹ کر بجھے پڑے ہوئے [۱۳]', 'And that cry of theirs ceased not, till We made them as a field that is reaped, extinct (dead).', 'Then, this continued to be their cry till We turned them into stubble, totally extinguished.'),
(2499, 21, 16, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ مَا خَلَقۡنَا السَّمَآءَ وَ الۡاَرۡضَ وَ مَا بَیۡنَہُمَا  لٰعِبِیۡنَ ﴿۱۶﴾', 'اور ہم نے آسمان اور زمین کو اور جو مخلوقات ان دونوں کے درمیان ہے اس کو کھیل تماشے کے لئے پیدا نہیں کیا۔', 'اور ہم نے نہیں بنایا آسمان اور زمین کو اور جو کچھ انکے بیچ میں ہےکھیلتے ہوئے [۱۴]', 'We created not the heavens and the earth and all that is between them for a (mere) play .', 'We did not create the heavens and the earth and what lies between them for play.'),
(2500, 21, 17, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'لَوۡ اَرَدۡنَاۤ  اَنۡ نَّتَّخِذَ لَہۡوًا لَّاتَّخَذۡنٰہُ مِنۡ لَّدُنَّاۤ  ٭ۖ اِنۡ  کُنَّا فٰعِلِیۡنَ ﴿۱۷﴾', 'اگر ہم چاہتے کہ کھیل کی چیزیں بنائیں تو اگر ہم کو کرنا ہی ہوتا تو ہم اپنے پاس سے بنا لیتے۔', 'اگر ہم چاہتے کہ بنا لیں کچھ کھلونا تو بنا لیتے ہم اپنے پاس سے اگر ہم کو کرنا ہوتا', 'Had We intended to take a pastime (i.e. a wife or a son, etc.), We could surely have taken it from Us, if We were going to do (that).', 'Had We intended to have a pastime, We would have had it from Our own, if We were ever to do so.'),
(2501, 21, 18, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'بَلۡ نَقۡذِفُ بِالۡحَقِّ عَلَی الۡبَاطِلِ فَیَدۡمَغُہٗ فَاِذَا ہُوَ زَاہِقٌ ؕ وَ لَکُمُ الۡوَیۡلُ  مِمَّا تَصِفُوۡنَ ﴿۱۸﴾', 'نہیں بلکہ ہم سچ کو جھوٹ پر کھینچ مارتے ہیں تو وہ اس کا سر توڑ دیتا ہے اور جھوٹ اسی وقت نابود ہو جاتا ہے۔ اور جو باتیں تم بناتے ہو ان سے تمہاری ہی خرابی ہے۔', 'یوں نہیں پر ہم پھینک مارتے ہیں سچ کو جھوٹ پر پھر وہ اُس کا سر پھوڑ ڈالتا ہے پھر وہ جاتا رہتا ہے اور تمہارے لئے خرابی ہے اُن باتوں سے جو تم بتلاتے ہو [۱۵]', 'Nay, We fling (send down) the truth (this Quran) against the falsehood (disbelief), so it destroys it, and behold, it (falsehood) is vanished. And woe to you for that (lie) which you ascribe (to Us) (against Allah by uttering that Allah has a wife and a son).', 'Instead, We launch the truth against falsehood, which gets it smashed, and in no time it is gone. Alas to you for what you describe!'),
(2502, 21, 19, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ لَہٗ مَنۡ فِی السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ مَنۡ عِنۡدَہٗ  لَا یَسۡتَکۡبِرُوۡنَ عَنۡ عِبَادَتِہٖ وَ لَا یَسۡتَحۡسِرُوۡنَ ﴿ۚ۱۹﴾', 'اور جو لوگ آسمانوں میں اور جو زمین میں ہیں سب اسی کا مال ہیں اور جو فرشتے اسکے پاس ہیں وہ اسکی عبادت سے نہ تکبر کرتے ہیں اور نہ اکتاتے ہیں۔', 'اور اُسی کا ہے جو کوئی ہے آسمان اور  زمین میں [۱۶] اور جو اُسکے نزدیک رہتے ہیں سرکشی نہیں کرتے اُسکی عبادت سے اور نہیں کرتے کاہلی', 'To Him belongs whosoever is in the heavens and on earth. And those who are near Him (i.e. the angels) are not too proud to worship Him, nor are they weary (of His worship).', 'To Him belong all those in the heavens and the earth. And those who are near to Him are not arrogant against His worship, nor are they sluggish.'),
(2503, 21, 20, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'یُسَبِّحُوۡنَ الَّیۡلَ وَ النَّہَارَ لَا یَفۡتُرُوۡنَ ﴿۲۰﴾', 'رات دن اسکی تسبیح کرتے رہتے ہیں نہ تھکتے ہیں نہ تھمتے ہیں۔', 'یاد کرتےہیں رات اور دن نہیں تھکتے [۱۷]', 'They (i.e. the angels) glorify His Praises night and day, (and) they never slacken (to do so).', 'They proclaim His purity night and day, never slackening.'),
(2504, 21, 21, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'اَمِ اتَّخَذُوۡۤا اٰلِہَۃً مِّنَ الۡاَرۡضِ ہُمۡ یُنۡشِرُوۡنَ ﴿۲۱﴾', 'بھلا لوگوں نے جو زمین کی چیزوں سے بعض کو معبود بنا لیا ہے تو کیا وہ ان کو مرنے کے بعد اٹھا کھڑا کریں گے؟', 'کیا ٹھہرائے ہیں انہوں نے اور معبود زمین میں کہ وہ جلا اٹھائیں گے اُنکو [۱۸]', 'Or have they taken (for worship) aliha (gods) from the earth who raise the dead?', 'Or have they adopted gods from the earth, who raise the dead?'),
(2505, 21, 22, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'لَوۡ  کَانَ فِیۡہِمَاۤ  اٰلِہَۃٌ  اِلَّا اللّٰہُ  لَفَسَدَتَا ۚ فَسُبۡحٰنَ اللّٰہِ  رَبِّ الۡعَرۡشِ عَمَّا یَصِفُوۡنَ ﴿۲۲﴾', 'اگر آسمان اور زمین میں اللہ کے سوا اور معبود ہوتے تو زمین اور آسمان درہم برہم ہو جاتے۔ جو باتیں یہ لوگ بناتے ہیں تو اللہ جو مالک عرش ہے ان باتوں سے پاک ہے۔', 'اگر ہوتے ان دونوں میں اور معبود سوائے اللہ کے تو دونوں خراب ہو جاتے [۱۹] سو پاک ہے اللہ عرش کا مالک اُن باتوں سے جو یہ بتلاتے ہیں [۲۰]', 'Had there been therein (in the heavens and the earth) gods besides Allah, then verily both would have been ruined. Glorified be Allah, the Lord of the Throne, (High is He) above what they attribute to Him!', 'Had there been gods beside Allah, in the heavens and the earth, both of them would have fallen in disorder. So pure is Allah, the Lord of the Throne, from what they describe.'),
(2506, 21, 23, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'لَا  یُسۡـَٔلُ  عَمَّا  یَفۡعَلُ  وَ  ہُمۡ  یُسۡـَٔلُوۡنَ ﴿۲۳﴾', 'وہ جو کام کرتا ہے اسکی پرسش نہیں ہو گی اور جو کام یہ لوگ کرتے ہیں اسکی ان سے پرسش ہو گی۔', 'اُس سے پوچھا نہ جائے جو وہ کرے اور  اِن سے پوچھا جائے [۲۱]', 'He cannot be questioned as to what He does, while they will be questioned.', 'He is not questioned of what He does, and they are questioned.'),
(2507, 21, 24, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'اَمِ اتَّخَذُوۡا مِنۡ دُوۡنِہٖۤ  اٰلِہَۃً ؕ قُلۡ ہَاتُوۡا بُرۡہَانَکُمۡ ۚ ہٰذَا ذِکۡرُ  مَنۡ مَّعِیَ وَ ذِکۡرُ مَنۡ قَبۡلِیۡ ؕ بَلۡ  اَکۡثَرُہُمۡ لَا یَعۡلَمُوۡنَ ۙ الۡحَقَّ  فَہُمۡ  مُّعۡرِضُوۡنَ ﴿۲۴﴾', 'کیا لوگوں نے اللہ کو چھوڑ کر اور معبود بنا لئے ہیں کہدو کہ اس بات پر اپنی دلیل پیش کرو۔ یہ میری اور میرے ساتھ والوں کی کتاب بھی ہے اور جو مجھ سے پہلے پیغمبر ہوئے ہیں۔ انکی کتابیں بھی ہیں۔ بلکہ بات یہ ہے کہ ان میں اکثر حق بات کو نہیں جانتے اور اس لئے اس سے منہ پھیر لیتے ہیں۔', 'کیا ٹھہرائے ہیں انہوں نے اُس سے ورے اور معبود تو کہہ لاؤ اپنی سند [۲۲] یہی بات ہے میرے ساتھ والوں کی اور یہی بات ہے مجھ سے پہلوں کی کوئی نہیں پر وہ بہت لوگ نہیں سمجھتے سچی بات سو ٹلا رہے ہیں [۲۳]', 'Or have they taken for worship (other) aliha (gods) besides Him? Say: \"Bring your proof:\" This (the Quran) is the Reminder for those with me and the Reminder for those before me. But most of them know not the Truth, so they are averse.', 'Is it that they have adopted gods besides Him? Say, “Bring your proof.” Here is the (book carrying) advice for those with me, and the (books carrying) advice for those before me. Yet most of them do not know the truth, and therefore they are averse.'),
(2508, 21, 25, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ مَاۤ  اَرۡسَلۡنَا مِنۡ قَبۡلِکَ مِنۡ رَّسُوۡلٍ  اِلَّا نُوۡحِیۡۤ  اِلَیۡہِ اَنَّہٗ  لَاۤ  اِلٰہَ  اِلَّاۤ  اَنَا فَاعۡبُدُوۡنِ ﴿۲۵﴾', 'اور جو پیغمبر ہم نے تم سے پہلے بھیجے انکی طرف یہی وحی بھیجی کہ میرے سوا کوئی معبود نہیں تو میری ہی عبادت کرو۔', 'اور نہیں بھیجا ہم نے تجھ سے پہلے کوئی رسول مگر اُسکو  یہی حکم بھیجا کہ بات یوں ہے کہ کسی کی بندگی نہیں سوائے میرے سو میری بندگی کرو [۲۴]', 'And We did not send any Messenger before you (O Muhammad SAW) but We inspired him (saying): La ilaha illa Ana (none has the right to be worshipped but I (Allah)), so worship Me (Alone and none else).\"', 'We did not send before you any messenger but We revealed to him that there is no god but I, so worship Me.”'),
(2509, 21, 26, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ قَالُوا اتَّخَذَ الرَّحۡمٰنُ وَلَدًا سُبۡحٰنَہٗ ؕ بَلۡ  عِبَادٌ   مُّکۡرَمُوۡنَ ﴿ۙ۲۶﴾', 'اور کہتے ہیں کہ رحمٰن بیٹا رکھتا ہے وہ پاک ہے اس کے نہ بیٹا ہے نہ بیٹی بلکہ جنکو یہ لوگ اسکے بیٹے بیٹیاں سمجھتے ہیں وہ اسکے عزت والے بندے ہیں۔', 'اور کہتے ہں رحمٰن نے کر لیا کسی کو بیٹا وہ ہر گز اس لائق نہیں [۲۵] لیکن وہ بندے ہیں جنکو عزت دی ہے', 'And they say: \"The Most Beneficent (Allah) has begotten a son (or children).\" Glory to Him! They (those whom they call children of Allah i.e. the angels, Iesa (Jesus) son of Maryam (Mary), Uzair (Ezra), etc.), are but honoured slaves.', 'They said, “The RaHmān (the All-Merciful, Allah) has taken children for Himself.” Pure is He (from having children). They are but (His) honored servants.'),
(2510, 21, 27, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'لَا یَسۡبِقُوۡنَہٗ  بِالۡقَوۡلِ وَ ہُمۡ  بِاَمۡرِہٖ یَعۡمَلُوۡنَ ﴿۲۷﴾', 'اسکے آگے بڑھ کر بول نہیں سکتے۔ اور اسکے حکم پر عمل کرتے ہیں۔', 'اس سے بڑھ کر نہیں بول سکتے اور وہ اسی کے حکم پر کام کرتے ہیں [۲۶]', 'They speak not until He has spoken, and they act on His Command.', 'They do not precede Him in speech, and only under His command they act.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(2511, 21, 28, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'یَعۡلَمُ مَا بَیۡنَ اَیۡدِیۡہِمۡ  وَ مَا خَلۡفَہُمۡ  وَ لَا یَشۡفَعُوۡنَ ۙ اِلَّا لِمَنِ ارۡتَضٰی وَ ہُمۡ مِّنۡ خَشۡیَتِہٖ مُشۡفِقُوۡنَ ﴿۲۸﴾', 'جو کچھ انکے آگے ہو چکا ہے اور جو پیچھے ہو گا وہ سب سے واقف ہے اور وہ اسکے پاس کسی کی سفارش نہیں کرسکتے مگر اس شخص کی جس سے اللہ خوش ہو اور وہ اسکی ہیبت سے ڈرتے رہتے ہیں۔', 'اُسکو معلوم ہے جو اُنکے آگے ہیں اور پیچھے [۲۷] اور وہ سفارش نہیں کرتے مگر اُسکی جس سے اللہ راضی ہو [۲۸] اور وہ اُسکی ہیبت سے ڈرتے ہیں [۲۹]', 'He knows what is before them, and what is behind them, and they cannot intercede except for him with whom He is pleased. And they stand in awe for fear of Him.', 'He knows what is in front of them and what is behind them, and they make recommendation for none but for whom He likes, and in awe of Him they are fearful.'),
(2512, 21, 29, 2, 2, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ مَنۡ یَّقُلۡ مِنۡہُمۡ  اِنِّیۡۤ  اِلٰہٌ  مِّنۡ دُوۡنِہٖ فَذٰلِکَ نَجۡزِیۡہِ جَہَنَّمَ ؕ کَذٰلِکَ نَجۡزِی الظّٰلِمِیۡنَ ﴿٪۲۹﴾', 'اور جو شخص ان میں سے یہ کہے کہ اللہ کے سوا میں بھی معبود ہوں تو اسے ہم دوزخ کی سزا دیں گے ظالموں کو ہم ایسی ہی سزا دیا کرتے ہیں۔', 'اور جو کوئی اُن میں کہے کہ میری بندگی ہے اس سے ورے سو اسکو ہم بدلہ دیں گے دوزخ یونہی ہم بدلہ دیتے ہیں بے انصافوں کو [۳۰]', 'And if any of them should say: \"Verily, I am an ilah (a god) besides Him (Allah),\" such a one We should recompense with Hell. Thus We recompense the Zalimoon (polytheists and wrong-doers, etc.).', 'Should any one of them say, “I am god besides Him”, We will recompense him with Jahannam (Hell). This is how We recompense the transgressors.'),
(2513, 21, 30, 3, 3, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'اَوَ لَمۡ  یَرَ الَّذِیۡنَ  کَفَرُوۡۤا  اَنَّ  السَّمٰوٰتِ وَ الۡاَرۡضَ کَانَتَا رَتۡقًا فَفَتَقۡنٰہُمَا ؕ وَ جَعَلۡنَا مِنَ الۡمَآءِ کُلَّ  شَیۡءٍ حَیٍّ ؕ اَفَلَا یُؤۡمِنُوۡنَ ﴿۳۰﴾', 'کیا کافروں نے نہیں دیکھا کہ آسمان اور زمین دونوں ملے ہوئے تھے تو ہم نے انکو جدا جدا کر دیا اور تمام جاندار چیزیں ہم نے پانی سے بنائیں پھر یہ لوگ ایمان کیوں نہیں لاتے۔', 'اور کیا نہیں دیکھا ان منکروں نے کہ آسمان اور زمین منہ بند تھے پھر ہم نے انکو کھول دیا [۳۱] اور بنائی ہم نے پانی سے ہر ایک چیز جس میں جان ہے [۳۲] پھر کیا یقین نہیں کرتے [۳۳]', 'Have not those who disbelieve known that the heavens and the earth were joined together as one united piece, then We parted them? And We have made from water every living thing. Will they not then believe?', 'Did the disbelievers not observe that the heavens and the earth were closed, then We opened them? And We created from water every living thing. Would they still not believe?'),
(2514, 21, 31, 3, 3, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ جَعَلۡنَا فِی الۡاَرۡضِ رَوَاسِیَ اَنۡ  تَمِیۡدَ بِہِمۡ ۪ وَ جَعَلۡنَا فِیۡہَا فِجَاجًا سُبُلًا   لَّعَلَّہُمۡ  یَہۡتَدُوۡنَ ﴿۳۱﴾', 'اور ہم نے زمین میں پہاڑ بنائے تاکہ وہ لوگوں کو لیکر ڈولنے نہ لگے اور اس میں کشادہ رستے بنائے تاکہ لوگ ان پر چلیں۔', 'اور رکھ دیے ہم نے زمین میں بھاری بوجھ کبھی اُنکو لے کر جھک پڑے [۳۴] اور رکھیں اُس میں کشادہ راہیں تاکہ وہ راہ پائیں [۳۵]', 'And We have placed on the earth firm mountains, lest it should shake with them, and We placed therein broad highways for them to pass through, that they may be guided.', 'And We created mountains on the earth, lest it should shake with them, and We have made therein paths and ways, so that they are guided.'),
(2515, 21, 32, 3, 3, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ  جَعَلۡنَا السَّمَآءَ سَقۡفًا مَّحۡفُوۡظًا ۚۖ وَّ ہُمۡ  عَنۡ  اٰیٰتِہَا مُعۡرِضُوۡنَ ﴿۳۲﴾', 'اور آسمان کو محفوظ چھت بنایا۔ اس پر بھی وہ ہماری نشانیوں سے منہ پھیر رہے ہیں۔', 'اور بنایا ہم نے آسمان کو چھت محفوظ [۳۶] اور وہ آسمان کی نشانیوں کو دھیان میں نہیں لاتے [۳۷]', 'And We have made the heaven a roof, safe and well guarded. Yet they turn away from its signs (i.e. sun, moon, winds, clouds, etc.).', 'We made the sky a protected roof; and they are averse to its signs.'),
(2516, 21, 33, 3, 3, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ ہُوَ الَّذِیۡ خَلَقَ الَّیۡلَ وَ النَّہَارَ وَ الشَّمۡسَ وَ الۡقَمَرَ ؕ کُلٌّ فِیۡ  فَلَکٍ یَّسۡبَحُوۡنَ ﴿۳۳﴾', 'اور وہی تو ہے جس نے رات اور دن اور سورج اور چاند کو بنایا یہ سب اپنے اپنے مدار میں تیر رہے ہیں۔', 'اور وہی ہے جس نے بنائے رات اور دن اور سورج اور چاند [۳۸] سب اپنے اپنے گھر میں پھرتے ہیں [۳۹]', 'And He it is Who has created the night and the day, and the sun and the moon, each in an orbit floating.', 'He is the One who has created the night and the day, and the sun and the moon, each floating in an orbit.'),
(2517, 21, 34, 3, 3, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ مَا جَعَلۡنَا لِبَشَرٍ مِّنۡ قَبۡلِکَ الۡخُلۡدَ ؕ اَفَا۠ئِنۡ  مِّتَّ  فَہُمُ  الۡخٰلِدُوۡنَ  ﴿۳۴﴾', 'اور اے پیغمبر ہم نے تم سے پہلے کسی آدمی کو بقائے دوام نہیں بخشا۔ بھلا اگر تم مر جاؤ تو کیا یہ لوگ ہمیشہ رہیں گے۔', 'اور نہیں دیا ہم نے تجھ سے پہلے کسی آدمی کو ہمیشہ کیلئے زندہ رہنا پھر کیا اگر تو مر گیا تو وہ رہ جائیں گے', 'And We granted not to any human being immortality before you (O Muhammad SAW), then if you die, would they live forever?', 'We did not assign immortality to any human (even) before you. So, if you die, will they live for ever?'),
(2518, 21, 35, 3, 3, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'کُلُّ نَفۡسٍ ذَآئِقَۃُ  الۡمَوۡتِ ؕ وَ نَبۡلُوۡکُمۡ بِالشَّرِّ وَ الۡخَیۡرِ  فِتۡنَۃً ؕ وَ اِلَیۡنَا  تُرۡجَعُوۡنَ ﴿۳۵﴾', 'ہر شخص کو موت کا مزہ چکھنا ہے۔ اور ہم تم لوگوں کو سختی اور آسودگی میں آزمائش کے طور پر مبتلا کرتے ہیں۔ اور تم ہماری طرف ہی لوٹ کر آؤ گے۔', 'ہر جی کو چکھنی ہے موت [۴۰] اور ہم تمکو جانچتے ہیں برائی سے اور بھلائی سے آزمانے کو [۴۱] اور ہماری طرف پھر کر آ جاؤ گے [۴۲]', 'Everyone is going to taste death, and We shall make a trial of you with evil and with good, and to Us you will be returned.', 'Every one has to taste death, and We test you through bad and good (situations) with a trial, and to Us you are to be returned.'),
(2519, 21, 36, 3, 3, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ اِذَا رَاٰکَ الَّذِیۡنَ  کَفَرُوۡۤا  اِنۡ یَّتَّخِذُوۡنَکَ  اِلَّا ہُزُوًا ؕ اَہٰذَا  الَّذِیۡ  یَذۡکُرُ   اٰلِہَتَکُمۡ ۚ وَ ہُمۡ   بِذِکۡرِ  الرَّحۡمٰنِ ہُمۡ کٰفِرُوۡنَ ﴿۳۶﴾', 'اور جب کافر تمکو دیکھتے ہیں تو تم سے ہنسی کر تے ہیں۔ کہ کیا یہی شخص ہے جو تمہارے معبودوں کا ذکر برائی سے کیا کرتا ہے حالانکہ وہ خود رحمٰن کے ذکر سے منکر ہیں۔', 'اور جہاں تجھ کو دیکھا منکروں نے تو کوئی کام نہیں اُنکو تجھ سے مگر ٹھٹھا کرنا کیا یہی شخص ہے جو نام لیتا ہے تمہارے معبودوں کا اور  وہ رحمٰن کے نام سے منکر ہیں [۴۳]', 'And when those who disbelieve (in the Oneness of Allah) see you (O Muhammad SAW), they take you not except for mockery (saying): \"Is this the one who talks (badly) about your gods?\" While they disbelieve at the mention of the Most Beneficent (Allah). (Tafsir. Al-Qurtubee).', 'When disbelievers see you, they do nothing but take you in jest (saying to one another,) “Is this the one who talks of your gods?” - while they themselves reject even talking of the RaHmān (All-Merciful).'),
(2520, 21, 37, 3, 3, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'خُلِقَ الۡاِنۡسَانُ مِنۡ عَجَلٍ ؕ سَاُورِیۡکُمۡ اٰیٰتِیۡ  فَلَا  تَسۡتَعۡجِلُوۡنِ ﴿۳۷﴾', 'انسان کچھ ایسا جلد باز ہے کہ گویا جلدبازی ہی سے بنایا گیا ہے۔ میں تم لوگوں کو عنقریب اپنی نشانیان دکھاؤں گا تو تم مجھ سے جلدی نہ کرو۔', 'بنا ہے آدمی جلدی کا اب دکھلاتا ہوں تمکو  اپنی نشانیاں سو مجھ سے جلدی مت کرو [۴۴]', 'Man is created of haste, I will show you My Ayat (torments, proofs, evidences, verses, lessons, signs, revelations, etc.).So ask Me not to hasten (them).', 'Man is made of haste. I shall show you My signs, so do not seek haste from Me.'),
(2521, 21, 38, 3, 3, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ یَقُوۡلُوۡنَ مَتٰی ہٰذَا الۡوَعۡدُ اِنۡ  کُنۡتُمۡ صٰدِقِیۡنَ ﴿۳۸﴾', 'اور کہتے ہیں کہ اگر تم سچے ہو تو جس عذاب کی یہ وعید ہے وہ کب آئے گا۔', 'اور کہتے ہیں کب ہو گا یہ وعدہ اگر تم سچے ہو [۴۵]', 'And they say: \"When will this promise (come to pass), if you are truthful.\"', 'They say, “When will this promise be (fulfilled), if you are true?”'),
(2522, 21, 39, 3, 3, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'لَوۡ  یَعۡلَمُ  الَّذِیۡنَ  کَفَرُوۡا حِیۡنَ لَا یَکُفُّوۡنَ عَنۡ وُّجُوۡہِہِمُ  النَّارَ  وَ لَا عَنۡ ظُہُوۡرِہِمۡ  وَ لَا  ہُمۡ  یُنۡصَرُوۡنَ ﴿۳۹﴾', 'اے کاش کافر اس وقت کو جانیں جب وہ اپنے چہروں پر سے دوزخ کی آگ کو روک نہ سکیں گے اور نہ اپنی پیٹھوں پر سے اور نہ ان کا کوئی مددگار ہو گا۔', 'اگر جان لیں یہ منکر اُس وقت کو کہ نہ روک سکیں گے اپنے منہ سے آگ اور نہ اپنی پیٹھ سے اور نہ اُنکو مدد پہنچے گی', 'If only those who disbelieved knew (the time) when they will not be able to ward off the Fire from their faces, nor from their backs; and they will not be helped.', 'Only if the disbelievers were to know the time when they will not (be able to) keep off the fire from their faces or from their backs, nor will they be helped.'),
(2523, 21, 40, 3, 3, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'بَلۡ تَاۡتِیۡہِمۡ بَغۡتَۃً  فَتَبۡہَتُہُمۡ فَلَا یَسۡتَطِیۡعُوۡنَ رَدَّہَا وَ لَا ہُمۡ یُنۡظَرُوۡنَ ﴿۴۰﴾', 'بلکہ قیامت ان پر یکایک آ واقع ہو گی۔ اور انکے ہوش کھو دے گی۔ پھر نہ تو وہ اسکو ہٹا سکیں گے اور نہ انکو مہلت دی جائے گی۔', 'کچھ نہیں وہ آئے گی اُن پر ناگہاں پھر انکے ہوش کھو دیگی پھر نہ پھیر سکیں گے اُسکو اور نہ اُنکو فرصت ملے گی [۴۶]', 'Nay, it (the Fire or the Day of Resurrection) will come upon them all of a sudden and will perplex them, and they will have no power to avert it, nor will they get respite.', 'Rather, it will come upon them suddenly and will baffle them. So they will not be able to turn it back, nor will they be given respite.'),
(2524, 21, 41, 3, 3, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ لَقَدِ اسۡتُہۡزِئَ بِرُسُلٍ مِّنۡ قَبۡلِکَ فَحَاقَ بِالَّذِیۡنَ سَخِرُوۡا مِنۡہُمۡ مَّا کَانُوۡا بِہٖ  یَسۡتَہۡزِءُوۡنَ ﴿٪۴۱﴾', 'اور تم سے پہلے بھی پیغمبروں کا مذاق اڑایا جاتا رہا ہے تو جو لوگ ان میں سے تمسخر کیا کرتے تھے انکو اسی عذاب نے جسکی ہنسی اڑاتے تھے آ گھیرا۔', 'اور ٹھٹھے ہو چکے ہیں رسولوں سے تجھ سے پہلے پھر الٹ پڑی ٹھٹھا کرنے والوں پر اُن میں سے وہ چیز جس کا ٹھٹھا کرتے تھے [۴۷]', 'Indeed (many) Messengers were mocked before you (O Muhammad SAW), but the scoffers were surrounded by that, whereat they used to mock.', 'In fact, messengers have been mocked at prior to you. So those who laughed at them were besieged by what they used to ridicule.'),
(2525, 21, 42, 4, 4, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قُلۡ مَنۡ یَّکۡلَؤُکُمۡ  بِالَّیۡلِ وَ النَّہَارِ مِنَ الرَّحۡمٰنِ ؕ بَلۡ ہُمۡ عَنۡ ذِکۡرِ رَبِّہِمۡ مُّعۡرِضُوۡنَ ﴿۴۲﴾', 'کہو کہ رات اور دن میں رحمٰن سے کون تمہاری حفاظت کر سکتا ہے؟ بات یہ ہے کہ یہ اپنے پروردگار کی یاد سے منہ پھیرے ہوئے ہیں۔', 'تو کہہ کون نگہبانی کرتا ہے تمہاری رات میں اور دن میں رحمٰن سے [۴۸] کوئی نہیں وہ اپنے رب کے ذکر سے منہ پھیرتے ہیں [۴۹]', 'Say: \"Who can guard and protect you in the night or in the day from the (punishment of the) Most Beneficent (Allah)?\" Nay, but they turn away from the remembrance of their Lord.', 'Say, “Who will guard you, during night and day, against the RaHmān (All-Merciful, Allah)?” Rather, to the remembrance of their Lord they are averse.'),
(2526, 21, 43, 4, 4, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'اَمۡ لَہُمۡ اٰلِہَۃٌ  تَمۡنَعُہُمۡ مِّنۡ دُوۡنِنَا ؕ لَا یَسۡتَطِیۡعُوۡنَ نَصۡرَ اَنۡفُسِہِمۡ وَ لَا ہُمۡ مِّنَّا یُصۡحَبُوۡنَ ﴿۴۳﴾', 'کیا ہمارے سوا انکے اور معبود ہیں کہ انکو مصائب سے بچا سکیں۔ وہ آپ اپنی مدد تو کر ہی نہیں سکیں گے اور نہ ہماری طرف سے انکی رفاقت ہو گی۔', 'یا اُنکے واسطے کوئی معبود ہیں کہ اُنکو بچاتے ہیں ہمارے سوا وہ اپنی بھی مدد نہیں کر سکتے اور نہ اُنکی ہماری طرف سے رفاقت ہو [۵۰]', 'Or have they aliha (gods) who can guard them from Us? They have no power to help themselves, nor can they be protected from Us (i.e. from Our Torment).', 'Or do they have gods who protect them besides Us? They are not able to help even themselves, nor will they have anyone to side with them against Us.'),
(2527, 21, 44, 4, 4, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'بَلۡ مَتَّعۡنَا ہٰۤؤُلَآءِ  وَ اٰبَآءَہُمۡ حَتّٰی طَالَ عَلَیۡہِمُ الۡعُمُرُ ؕ اَفَلَا یَرَوۡنَ اَنَّا نَاۡتِی الۡاَرۡضَ نَنۡقُصُہَا مِنۡ اَطۡرَافِہَا ؕ اَفَہُمُ  الۡغٰلِبُوۡنَ ﴿۴۴﴾', 'بلکہ ہم ان لوگوں کو اور انکے باپ دادا کو متمتع کرتے رہے یہاں تک کہ اسی حالت میں انکی عمریں بسر ہو گئیں کیا یہ نہیں دیکھتے کہ ہم زمین کو اسکے کناروں سے گھٹاتے چلے آتے ہیں۔ تو کیا یہ لوگ غلبہ پانے والے ہیں؟', 'کوئی نہیں پر ہم نے عیش دیا اُنکو اور اُنکے باپ دادوں کو  یہاں تک کہ بڑھ گئ اُن پر زندگی [۵۱] پھر کیا نہیں دیکھتے کہ ہم چلے آتے ہیں زمین کو گھٹاتے اُسکے کناروں سے اب کیا وہ جیتنے والےہیں [۵۲]', 'Nay, We gave the luxuries of this life to these men and their fathers until the period grew long for them. See they not that We gradually reduce the land (in their control) from its outlying borders? Is it then they who will overcome.', 'But We have given benefits to these and their fathers until life was prolonged for them. So do they not see that We are coming to the land narrowing it down from all its sides? Then, are they the ones to prevail?'),
(2528, 21, 45, 4, 4, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قُلۡ  اِنَّمَاۤ  اُنۡذِرُکُمۡ  بِالۡوَحۡیِ ۫ۖ وَ لَا یَسۡمَعُ الصُّمُّ الدُّعَآءَ  اِذَا مَا یُنۡذَرُوۡنَ ﴿۴۵﴾', 'کہدو کہ میں تم کو وحی کے مطابق خبردار کرتا ہوں اور بہروں کو جب تنبیہ کی جائے تو وہ پکار کو سنتے ہی نہیں۔', 'تو کہہ میں جو تمکو ڈراتا ہوں سو حکم کے موافق اور سنتے نہیں بہرے پکارنے کو جب کوئی اُنکو ڈر کی بات سنائے [۵۳]', 'Say (O Muhammad SAW): \"I warn you only by the revelation (from Allah and not by the opinion of the religious scholars and others). But the deaf (who follow the religious scholars and others blindly) will not hear the call, (even) when they are warned ((i.e. one should follow only the Quran and the Sunnah (legal ways, orders, acts of worship, statements of Prophet Muhammad SAW , as the Companions of the Prophet SAW did)).', 'Say, “I warn you only by revelation, but the deaf do not listen to the call when they are warned.”'),
(2529, 21, 46, 4, 4, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ لَئِنۡ مَّسَّتۡہُمۡ نَفۡحَۃٌ مِّنۡ عَذَابِ رَبِّکَ لَیَقُوۡلُنَّ یٰوَیۡلَنَاۤ  اِنَّا کُنَّا ظٰلِمِیۡنَ ﴿۴۶﴾', 'اور اگر انکو تمہارے پروردگار کا تھوڑا سا عذاب بھی پہنچے تو کہنے لگیں کہ ہائے کم بختی ہم بیشک گناہگار تھے۔', 'اور کہیں پہنچ جائے اُن تک ایک بھاپ تیرے رب کے عذاب کی تو ضرور کہنے لگیں ہائے کم بختی ہماری بیشک ہم تھے گنہگار [۵۴]', 'And if a breath (minor calamity) of the Torment of your Lord touches them, they will surely cry: \"Woe unto us! Indeed we have been Zalimoon (polytheists and wrong-doers, etc.).', 'If a whiff of your Lord’s torment were to touch them, they would certainly say, “Alas to us! We were wrongdoers indeed.”'),
(2530, 21, 47, 4, 4, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ نَضَعُ الۡمَوَازِیۡنَ الۡقِسۡطَ لِیَوۡمِ الۡقِیٰمَۃِ  فَلَا  تُظۡلَمُ  نَفۡسٌ شَیۡئًا ؕ وَ اِنۡ کَانَ مِثۡقَالَ حَبَّۃٍ مِّنۡ خَرۡدَلٍ اَتَیۡنَا بِہَا ؕ وَ کَفٰی  بِنَا حٰسِبِیۡنَ ﴿۴۷﴾', 'اور ہم قیامت کے دن انصاف کی ترازو کھڑی کریں گے تو کسی شخص کی ذرا بھی حق تلفی نہ کی جائے گی۔ اور اگر رائی کے دانے کے برابر بھی کسی کا عمل ہو گا تو ہم اس کو لا موجود کریں گے اور ہم حساب کرنے کو کافی ہیں۔', 'اور رکھیں گے ہم ترازوئیں انصاف کی قیامت کے دن پھر ظلم نہ ہو گا کسی جی پر ایک ذرہ اور اگر ہو گا برابر رائی کے دانہ کی تو ہم لے آئیں گے اُسکو [۵۵] اور ہم کافی ہیں حساب کرنے کو [۵۶]', 'And We shall set up balances of justice on the Day of Resurrection, then none will be dealt with unjustly in anything. And if there be the weight of a mustard seed, We will bring it. And Sufficient are We as Reckoners.', 'We shall place scales to do justice on the Day of Judgment. So no one shall be wronged in the least. Even if it (a deed) is to the measure of a mustard seed, We will bring it forth, and We are enough to take account.'),
(2531, 21, 48, 4, 4, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ لَقَدۡ اٰتَیۡنَا مُوۡسٰی وَ ہٰرُوۡنَ الۡفُرۡقَانَ وَ ضِیَآءً  وَّ  ذِکۡرًا  لِّلۡمُتَّقِیۡنَ ﴿ۙ۴۸﴾', 'اور ہم نے موسٰی اور ہارون کو ہدایت اور گمراہی میں فرق کر دینے والی اور سرتاپا روشنی اور نصیحت کی کتاب عطا کی یعنی پرہیزگاروں کے لئے۔', 'اور ہم نے دی تھی موسٰی اور ہارون کو قضیے چکانے والی کتاب اور روشنی اور نصیحت ڈرنے والوں کو [۵۷]', 'And indeed We granted to Moosa (Moses) and Haroon (Aaron) the criterion (of right and wrong), and a shining light (i.e. the Taurat (Torah)) and a Reminder for Al-Muttaqoon (the pious - see V.2:2).', 'And We gave Mūsā and Hārūn the Criterion, and a light and an advice for the God-fearing,'),
(2532, 21, 49, 4, 4, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'الَّذِیۡنَ  یَخۡشَوۡنَ رَبَّہُمۡ بِالۡغَیۡبِ وَ ہُمۡ مِّنَ  السَّاعَۃِ  مُشۡفِقُوۡنَ ﴿۴۹﴾', 'جو بن دیکھے اپنے پروردگار سے ڈرتے ہیں اور قیامت کا بھی خوف رکھتے ہیں۔', 'جو ڈرتے ہیں اپنے رب سے بن دیکھے اور وہ قیامت کا خطرہ رکھتے ہیں [۵۸]', 'Those who fear their Lord without seeing Him, while they are afraid of the Hour.', '- those who have awe of their Lord without having seen Him, and are fearful of the Hour (of Judgment).'),
(2533, 21, 50, 4, 4, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ ہٰذَا ذِکۡرٌ  مُّبٰرَکٌ اَنۡزَلۡنٰہُ ؕ اَفَاَنۡتُمۡ  لَہٗ مُنۡکِرُوۡنَ ﴿٪۵۰﴾', 'اور یہ مبارک نصیحت ہے جسے ہم نے نازل فرمایا ہے تو کیا تم اس سے انکار کرتے ہو؟', 'اور یہ ایک نصیحت ہے برکت کی جو ہم نے اتاری سو کیا تم اُسکو نہیں مانتے [۵۹]', 'And this is a blessed Reminder (the Quran) which We have sent down, will you then (dare to) deny it?', 'And this is a blessed advice We have sent down. Are you still rejecting it?'),
(2534, 21, 51, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ لَقَدۡ اٰتَیۡنَاۤ  اِبۡرٰہِیۡمَ  رُشۡدَہٗ  مِنۡ  قَبۡلُ وَ کُنَّا  بِہٖ  عٰلِمِیۡنَ  ﴿ۚ۵۱﴾', 'اور ہم نے ابراہیم کو پہلے ہی سے ہدایت دی تھی اور ہم انکے حال سے واقف تھے۔', 'اور آگے دی تھی ہم نے ابراہیم کو اُسکی نیک راہ [۶۰] اور ہم رکھتے ہیں اُسکی خبر [۶۱]', 'And indeed We bestowed aforetime on Ibrahim (Abraham) his (portion of) guidance, and We were Well-Acquainted with him (as to his Belief in the Oneness of Allah, etc.).', 'Even earlier We had given Ibrāhīm his right course, and We knew him well'),
(2535, 21, 52, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'اِذۡ قَالَ لِاَبِیۡہِ وَ قَوۡمِہٖ مَا ہٰذِہِ التَّمَاثِیۡلُ  الَّتِیۡۤ  اَنۡتُمۡ  لَہَا  عٰکِفُوۡنَ ﴿۵۲﴾', 'جب انہوں نے اپنے باپ اور اپنی برادری والوں سے کہا یہ کیسی مورتیں ہیں جنکی پرستش پر تم لوگ جمے ہوئے ہو۔', 'جب کہا اُس نے اپنے باپ کو اور اپنی قوم کو یہ کیسی مورتیں ہیں جن پر تم مجاور بنے بیٹھے ہو [۶۲]', 'When he said to his father and his people: \"What are these images, to which you are devoted?\"', 'when he said to his father and his people, “What are these statues you are devoted to?”'),
(2536, 21, 53, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قَالُوۡا  وَجَدۡنَاۤ  اٰبَآءَنَا لَہَا عٰبِدِیۡنَ ﴿۵۳﴾', 'وہ کہنے لگے کہ ہم نے اپنے باپ دادا کو انکی پرستش کرتے دیکھا ہے۔', 'بولے ہم نے پایا اپنے باپ دادوں کو انہی کی پوجا کرتے [۶۳]', 'They said:\"We found our fathers worshipping them.\"', 'They said, “We found our fathers worshipping them,”'),
(2537, 21, 54, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قَالَ لَقَدۡ کُنۡتُمۡ  اَنۡتُمۡ  وَ اٰبَآؤُکُمۡ  فِیۡ  ضَلٰلٍ مُّبِیۡنٍ ﴿۵۴﴾', 'ابراہیم نے کہا کہ تم بھی گمراہ ہو اور تمہارے باپ دادا بھی کھلی گمراہی میں پڑے رہے۔', 'بولا مقرر ہے تم اور تمہارے باپ دادے صریح گمراہی میں [۶۴]', 'He said: \"Indeed you and your fathers have been in manifest error.\"', 'He said, “Surely you and your fathers have been in open error.”'),
(2538, 21, 55, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قَالُوۡۤا  اَجِئۡتَنَا بِالۡحَقِّ اَمۡ  اَنۡتَ مِنَ اللّٰعِبِیۡنَ ﴿۵۵﴾', 'وہ بولے کیا تم ہمارے پاس واقعی حق لائے ہو یا ہم سے کھیل کی باتیں کرتے ہو۔', 'بولے تو ہمارے پاس لایا ہے سچی بات یا تو کھلاڑیاں کرتا ہے [۶۵]', 'They said: \"Have you brought us the truth, or are you one of those who play about?\"', 'They said, “Did you come to us with truth or are you one of the triflers?”'),
(2539, 21, 56, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قَالَ بَلۡ رَّبُّکُمۡ رَبُّ السَّمٰوٰتِ وَ الۡاَرۡضِ الَّذِیۡ فَطَرَہُنَّ ۫ۖ وَ اَنَا عَلٰی ذٰلِکُمۡ  مِّنَ  الشّٰہِدِیۡنَ ﴿۵۶﴾', 'ابراہیم نے کہا نہیں بلکہ تمہارا پروردگار آسمانوں اور زمین کا پروردگار ہے جس نے انکو پیدا کیا ہے اور میں اس بات کا گواہ اور اسی کا قائل ہوں۔', 'بولا نہیں رب تمہارا وہی ہے  رب آسمان اور زمین کا جس نے اُنکو بنایا اور میں اسی بات کا قائل ہوں [۶۶]', 'He said: \"Nay, your Lord is the Lord of the heavens and the earth, Who created them and of that I am one of the witnesses.', 'He said, “No, your Lord is the Lord of the heavens and the earth, who has created them, and I am one of those who bear witness to it.'),
(2540, 21, 57, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ تَاللّٰہِ لَاَکِیۡدَنَّ  اَصۡنَامَکُمۡ بَعۡدَ اَنۡ تُوَلُّوۡا مُدۡبِرِیۡنَ ﴿۵۷﴾', 'اور اللہ کی قسم جب تم پیٹھ پھیر کر چلے جاؤ گے تو میں تمہارے بتوں سے ایک چال چلوں گا۔', 'اور قسم اللہ کی میں علاج کروں گا تمہارے بتوں کا جب تم جا چکو گے پیٹھ پھیر کر [۶۷]', '\"And by Allah, I shall plot a plan (to destroy) your idols after you have gone away and turned your backs.\"', 'And I swear by Allah that I will devise something against your idols after you have gone away turning your backs.”'),
(2541, 21, 58, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'فَجَعَلَہُمۡ جُذٰذًا  اِلَّا کَبِیۡرًا  لَّہُمۡ  لَعَلَّہُمۡ اِلَیۡہِ  یَرۡجِعُوۡنَ ﴿۵۸﴾', 'پھر انکو توڑ کر ریزہ ریزہ کر دیا مگر ایک بڑے بت کو نہ توڑا تاکہ وہ اسکی طرف رجوع کریں۔', 'پھر کر ڈلا اُنکو ٹکڑے ٹکڑے مگر ایک بڑا اُن کا کہ شاید اُسکی طرف رجوع کریں [۶۸]', 'So he broke them to pieces, (all) except the biggest of them, that they might turn to it.', 'Then, he turned all of them into pieces, except the big one of them, so that they may come back to it.'),
(2542, 21, 59, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قَالُوۡا مَنۡ فَعَلَ ہٰذَا بِاٰلِہَتِنَاۤ  اِنَّہٗ  لَمِنَ  الظّٰلِمِیۡنَ ﴿۵۹﴾', 'کہنے لگے کہ ہمارے معبودوں کے ساتھ یہ معاملہ کس نے کیا؟ وہ تو کوئی ظالم ہے۔', 'کہنے لگے کس نے کیا یہ کام ہمارے معبودوں کے ساتھ وہ تو کوئی بے انصاف ہے [۶۹]', 'They said: \"Who has done this to our aliha (gods)? He must indeed be one of the wrong-doers.\"', 'They said, “Who has done this to our gods? He is one of the wrongdoers indeed.”'),
(2543, 21, 60, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قَالُوۡا سَمِعۡنَا فَتًی یَّذۡکُرُہُمۡ یُقَالُ لَہٗۤ اِبۡرٰہِیۡمُ ﴿ؕ۶۰﴾', 'لوگوں نے کہا کہ ہم نے ایک جوان کو انکا ذکر کرتے ہوئے سنا ہے اسے ابراہیم کہتے ہیں۔', 'وہ بولے ہم نے سنا ہے ایک جوان جو بتوں کو کچھ کہا کرتا ہے اُسکو کہتے ہیں ابراہیم [۷۰]', 'They said: \"We heard a young man talking (against) them who is called Ibrahim (Abraham).\"', 'Some of them said, “We have heard a youth talking about them. He is called Ibrāhīm.”'),
(2544, 21, 61, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قَالُوۡا فَاۡتُوۡا بِہٖ عَلٰۤی اَعۡیُنِ النَّاسِ لَعَلَّہُمۡ  یَشۡہَدُوۡنَ ﴿۶۱﴾', 'وہ بولے کہ اسے لوگوں کے سامنے لاؤ تاکہ وہ گواہ رہیں۔', 'وہ بولے اُسکو لے آؤ لوگوں کے سامنے شاید وہ دیکھیں [۷۱]', 'They said: \"Then bring him before the eyes of the people, that they may testify.\"', 'They said, “Then, bring him before the eyes of the people, so that they may see”.'),
(2545, 21, 62, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قَالُوۡۤا ءَاَنۡتَ فَعَلۡتَ ہٰذَا بِاٰلِہَتِنَا یٰۤـاِبۡرٰہِیۡمُ ﴿ؕ۶۲﴾', 'جب ابراہیم آئے تو بت پرستوں نے کہا کہ ابراہیم بھلا یہ کام ہمارے معبودوں کے ساتھ تو نے کیا ہے؟', 'بولے کیا تو نےکیا ہے یہ ہمارے معبودوں کیساتھ اے ابراہیم', 'They said: \"Are you the one who has done this to our gods, O Ibrahim (Abraham)?\"', 'They said, “Is it you O Ibrāhīm who has done this to our gods?”'),
(2546, 21, 63, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قَالَ بَلۡ  فَعَلَہٗ ٭ۖ   کَبِیۡرُہُمۡ ہٰذَا فَسۡـَٔلُوۡہُمۡ  اِنۡ  کَانُوۡا یَنۡطِقُوۡنَ ﴿۶۳﴾', 'ابراہیم نے کہا بلکہ یہ ان کے ان بڑے بت نے کیا ہو گا۔ اگر یہ بولتے ہوں تو ان سے پوچھ لو۔', 'بولا نہیں پر یہ کیا ہے اُنکے اس بڑے نے سو  اُن سے پوچھ لو اگر وہ بولتے ہیں [۷۲]', '(Ibrahim (Abraham)) said: \"Nay, this one, the biggest of them (idols) did it. Ask them, if they can speak!\"', 'He said, “Rather, this is done by this chief of theirs. So, ask them if they can speak.”'),
(2547, 21, 64, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'فَرَجَعُوۡۤا اِلٰۤی اَنۡفُسِہِمۡ فَقَالُوۡۤا اِنَّکُمۡ اَنۡتُمُ  الظّٰلِمُوۡنَ ﴿ۙ۶۴﴾', 'انہوں نے اپنے دل میں غور کیا تو آپس میں کہنے لگے بیشک تم ہی بےانصاف ہو۔', 'پھر سوچے اپنے جی میں پھر بولے لوگو تم ہی بے انصاف ہو [۷۳]', 'So they turned to themselves and said: \"Verily, you are the Zalimoon (polytheists and wrong-doers).\"', 'So they turned to one another and said, “In fact, you yourselves are the wrongdoers.”'),
(2548, 21, 65, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'ثُمَّ  نُکِسُوۡا عَلٰی  رُءُوۡسِہِمۡ ۚ لَقَدۡ  عَلِمۡتَ مَا ہٰۤؤُلَآءِ  یَنۡطِقُوۡنَ ﴿۶۵﴾', 'پھر شرمندہ ہو کر سر نیچا کر لیا اس پر بھی ابراہیم سے کہنے لگے کہ تم جانتے ہو یہ بولتے نہیں۔', 'پھر اوندھے ہو گئے سر جھکا کر [۷۴] تو تو جانتا ہے جیسا یہ بولتے ہیں [۷۵]', 'Then they turned to themselves (their first thought and said): \"Indeed you (Ibrahim (Abraham)) know well that these (idols) speak not!\"', 'Then, hanging their heads they reversed their position (and replied to Ibrāhīm,) “You already knew that they do not speak.”'),
(2549, 21, 66, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قَالَ اَفَتَعۡبُدُوۡنَ مِنۡ دُوۡنِ اللّٰہِ مَا لَا یَنۡفَعُکُمۡ  شَیۡئًا وَّ لَا  یَضُرُّکُمۡ ﴿ؕ۶۶﴾', 'ابراہیم نے کہا پھر تم اللہ کو چھوڑ کر کیوں ایسی چیزوں کو پوجتے ہو جو نہ تمہیں کچھ فائدہ دے سکیں اور نہ نقصان پہنچا سکیں؟', 'بولا کیا پھر تم پوجتے ہو اللہ سے ورے ایسے کو جو تمہارا کچھ بھلا کرنے نہ برا', '(Ibrahim (Abraham)) said: \"Do you then worship besides Allah, things that can neither profit you, nor harm you?', 'He said, “Do you then worship, beside Allah, what does neither benefit you in the least nor harm you?'),
(2550, 21, 67, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'اُفٍّ لَّکُمۡ وَ لِمَا تَعۡبُدُوۡنَ مِنۡ دُوۡنِ اللّٰہِ ؕ اَفَلَا  تَعۡقِلُوۡنَ ﴿۶۷﴾', 'تف ہے تم پر اور جنکو تم اللہ کے سوا پوجتے ہو ان پر۔ کیا تم عقل نہیں رکھتے؟', 'بیزار ہوں میں تم سے اور جنکو تم پوجتے ہو اللہ کے سوائے کیا تم کو سمجھ نہیں [۷۶]', '\"Fie upon you, and upon that which you worship besides Allah! Have you then no sense?\"', 'Fie upon you and upon what you worship other than Allah. Do you then not understand?”'),
(2551, 21, 68, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قَالُوۡا حَرِّقُوۡہُ وَ انۡصُرُوۡۤا اٰلِہَتَکُمۡ  اِنۡ کُنۡتُمۡ  فٰعِلِیۡنَ ﴿۶۸﴾', 'تب وہ آپس میں کہنے لگے کہ اگر تمہیں اس سے اپنے معبودوں کا انتقام لینا ہے اور کچھ کرنا ہے تو اسکو جلا ڈالو اور اپنے معبودوں کی مدد کرو۔', 'بولے اسکو جلاؤ اور مدد کرو اپنے معبودوں کی اگر کچھ کرتے ہو [۷۷]', 'They said: \"Burn him and help your aliha (gods), if you will be doing.\"', 'They said, “(O people) burn him and help your gods, if you are to take action.”'),
(2552, 21, 69, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قُلۡنَا یٰنَارُ کُوۡنِیۡ بَرۡدًا وَّ سَلٰمًا عَلٰۤی اِبۡرٰہِیۡمَ ﴿ۙ۶۹﴾', 'ہم نے حکم دیا اے آگ سرد ہو جا اور ابراہیم پر سلامتی والی بن جا۔', 'ہم نے کہا اے آگ ٹھنڈی ہو جا اور آرام کر ابراہیم پر [۷۸]', 'We (Allah) said: \"O fire! Be you coolness and safety for Ibrahim (Abraham)!\"', 'We said, “O fire, be cold and safe for Ibrāhīm.”'),
(2553, 21, 70, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ اَرَادُوۡا بِہٖ کَیۡدًا فَجَعَلۡنٰہُمُ الۡاَخۡسَرِیۡنَ ﴿ۚ۷۰﴾', 'ان لوگوں نے برا تو ان کا چاہا تھا مگر ہم نے انہی کو نقصان میں ڈال دیا۔', 'اور چاہنے لگے اُس کا برا پھر اُنہی کو ہم نے ڈالا نقصان میں [۷۹]', 'And they wanted to harm him, but We made them the worst losers.', 'And they intended to harm him, but We made them the worst losers.'),
(2554, 21, 71, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ نَجَّیۡنٰہُ  وَ لُوۡطًا  اِلَی الۡاَرۡضِ الَّتِیۡ بٰرَکۡنَا  فِیۡہَا  لِلۡعٰلَمِیۡنَ ﴿۷۱﴾', 'اور ابراہیم اور لوط کو اس سرزمین کی طرف بچا نکالا جس میں ہم نے اہل عالم کے لئے برکت رکھی تھی۔', 'اور بچا نکالا ہم نے اُسکو اور لوط کو اُس زمین کی طرف جس میں برکت رکھی ہم نے جہان کے واسطے [۸۰]', 'And We rescued him and Lout (Lot) to the land which We have blessed for the Alameen (mankind and jinns).', 'And We rescued him and LūT towards the land we blessed for all the worlds.'),
(2555, 21, 72, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ وَہَبۡنَا لَہٗۤ  اِسۡحٰقَ ؕ وَ یَعۡقُوۡبَ  نَافِلَۃً ؕ وَ کُلًّا  جَعَلۡنَا صٰلِحِیۡنَ ﴿۷۲﴾', 'اور ہم نے ابراہیم کو اسحٰق عطا کئے۔ اور اسکے بعد مزید یعقوب بھی۔ اور ہم نے سب کو نیک بنایا تھا۔', 'اور بخشا ہم نے اُسکو اسحٰق اور یعقوب دیا انعام میں [۸۱] اور سب کو نیک بخت کیا [۸۲]', 'And We bestowed upon him Ishaque (Isaac), and (a grandson) Yaqoob (Jacob). Each one We made righteous.', 'And We blessed him with IsHāq and Ya‘qūb as gift, and each one of them We made righteous.'),
(2556, 21, 73, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ جَعَلۡنٰہُمۡ اَئِمَّۃً یَّہۡدُوۡنَ بِاَمۡرِنَا وَ اَوۡحَیۡنَاۤ  اِلَیۡہِمۡ فِعۡلَ الۡخَیۡرٰتِ وَ اِقَامَ الصَّلٰوۃِ  وَ اِیۡتَآءَ الزَّکٰوۃِ ۚ وَ کَانُوۡا لَنَا عٰبِدِیۡنَ ﴿ۚۙ۷۳﴾', 'اور ہم نے انکو پیشوا بنایا کہ ہمارے حکم سے ہدایت کرتے تھے اور انکو نیک کام کرنے اور نماز پڑھنے اور زکوٰۃ دینے کا حکم بھیجا اور وہ ہماری ہی عبادت کیا کرتے تھے۔', 'اور اُنکو کیا ہم نے پیشوا راہ بتلاتے تھے ہمارے حکم سے [۸۳] اور کہلا بھیجا ہم نے اُنکو کرنا نیکیوں کا اور قائم رکھنی نماز اور دینی زکوٰۃ [۸۴] اور وہ تھے ہماری بندگی میں لگے ہوئے [۸۵]', 'And We made them leaders, guiding (mankind) by Our Command, and We inspired in them the doing of good deeds, performing Salat (Iqamat-as-Salat), and the giving of Zakat and of Us (Alone) they were worshippers.', 'And We made them the Imams who guided (people) under Our command, and We inspired them to do good deeds and to establish Salāh and pay Zakāh, and Us alone they worshipped.'),
(2557, 21, 74, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ لُوۡطًا اٰتَیۡنٰہُ حُکۡمًا وَّ عِلۡمًا وَّ نَجَّیۡنٰہُ مِنَ الۡقَرۡیَۃِ  الَّتِیۡ کَانَتۡ تَّعۡمَلُ الۡخَبٰٓئِثَ ؕ اِنَّہُمۡ کَانُوۡا قَوۡمَ سَوۡءٍ فٰسِقِیۡنَ ﴿ۙ۷۴﴾', 'اور لوط کا قصہ یاد کرو جب انکو ہم نے حکمت و نبوت اور علم بخشا اور اس بستی سے جہاں کے لوگ گندے کام کیا کرتے تھے بچا نکالا بیشک وہ برے اور بدکردار لوگ تھے۔', 'اور لوط کو  دیا ہم نے حکم اور سمجھ [۸۶] اور بچا نکالا اُسکو اس بستی سے جو کرتے تھے گندے کام وہ تھے لوگ بڑے نافرمان [۸۷]', 'And (remember) Lout (Lot), We gave him Hukman (right judgement of the affairs and Prophethood) and (religious) knowledge, and We saved him from the town (folk) who practised Al-Khabaith (evil, wicked and filthy deeds, etc.). Verily, they were a people given to evil, and were Fasiqoon (rebellious, disobedient, to Allah).', 'As for LūT, We gave him wisdom and knowledge, and We delivered him from the town that used to do dirty deeds. Indeed, they were the people of evil, the sinners.'),
(2558, 21, 75, 5, 5, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ اَدۡخَلۡنٰہُ فِیۡ  رَحۡمَتِنَا ؕ اِنَّہٗ مِنَ الصّٰلِحِیۡنَ ﴿٪۷۵﴾', 'اور انہیں اپنی رحمت میں داخل کیا۔ کچھ شک نہیں کہ وہ نیک کرداروں میں تھے۔', 'اور اُسکو  لے لیا ہم نے اپنی رحمت میں وہ ہے نیک بختوں میں [۸۸]', 'And We admitted him to Our Mercy, truly, he was of the righteous.', 'And We admitted him to Our mercy. Indeed, He was of the righteous.'),
(2559, 21, 76, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ نُوۡحًا اِذۡ نَادٰی مِنۡ قَبۡلُ فَاسۡتَجَبۡنَا لَہٗ فَنَجَّیۡنٰہُ وَ اَہۡلَہٗ مِنَ الۡکَرۡبِ الۡعَظِیۡمِ ﴿ۚ۷۶﴾', 'اور نوح کا قصہ بھی یاد کرو جب اس سے پیشتر انہوں نے ہمیں پکارا تو ہم نے انکی دعا قبول فرمائی اور انکو اور انکے ساتھیوں کو بڑی گھبراہٹ سے نجات دی۔', 'اور نوح کو جب اُس نے پکارا اُس سے پہلے [۸۹] پھر قبول کر لی ہم نے اُس کی دعا سو بچا دیا اُسکو اور اسکے گھر والوں کو بڑی گھبراہٹ سے', 'And (remember) Nooh (Noah), when he cried (to Us) aforetime. We listened to his invocation and saved him and his family from great distress.', 'And (remember) NūH, when he called (for help) earlier, so We responded to him and saved him and his family from the terrible agony,'),
(2560, 21, 77, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ نَصَرۡنٰہُ مِنَ الۡقَوۡمِ الَّذِیۡنَ کَذَّبُوۡا بِاٰیٰتِنَا ؕ اِنَّہُمۡ کَانُوۡا قَوۡمَ سَوۡءٍ فَاَغۡرَقۡنٰہُمۡ  اَجۡمَعِیۡنَ ﴿۷۷﴾', 'اور جو لوگ ہماری آیتوں کی تکذیب کرتے تھے ان پر نصرت بخشی۔ وہ بیشک برے لوگ تھے سو ہم نے ان سب کو غرق کر دیا۔', 'اور مدد کی اُسکی اُن لوگوں پر جو جھٹلاتے تھے ہماری آیتیں وہ تھے برے لوگ پھر ڈبا دیا ہم نے اُن سب کو [۹۰]', 'We helped him against people who denied Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.). Verily, they were a people given to evil. So We drowned them all.', 'and helped him against the people who gave the lie to Our verses. Indeed, they were the people of evil, therefore, We drowned them all.'),
(2561, 21, 78, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ دَاوٗدَ  وَ سُلَیۡمٰنَ  اِذۡ یَحۡکُمٰنِ فِی الۡحَرۡثِ  اِذۡ  نَفَشَتۡ فِیۡہِ غَنَمُ  الۡقَوۡمِ ۚ وَ کُنَّا  لِحُکۡمِہِمۡ  شٰہِدِیۡنَ ﴿٭ۙ۷۸﴾', 'اور داؤد اور سلیمان کا حال بھی سن لو کہ جب وہ ایک کھیتی کا مقدمہ فیصل کرنے لگے جس میں کچھ لوگوں کی بکریاں رات کر چر گئیں اور اسے روند گئ تھیں اور ہم انکے فیصلے کے گواہ تھے۔', 'اور داؤد اور سلیمان کو جب لگے فیصل کرنے کھیتی کا جھگڑا جب روند گئیں اُسکو رات میں ایک قوم کی بکریاں اور سامنے تھا ہمارے اُن کا فیصلہ', 'And (remember) Dawood (David) and Sulaiman (Solomon), when they gave judgement in the case of the field in which the sheep of certain people had pastured at night and We were witness to their judgement.', 'And (remember) Dawūd (David) and Sulaimān (Solomon), when they were adjudicating about the tillage in which the goats of other people wandered at night (and trampled it), and We were witness to their judgment.'),
(2562, 21, 79, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'فَفَہَّمۡنٰہَا سُلَیۡمٰنَ ۚ وَ کُلًّا  اٰتَیۡنَا حُکۡمًا وَّ عِلۡمًا ۫ وَّ سَخَّرۡنَا مَعَ دَاوٗدَ الۡجِبَالَ یُسَبِّحۡنَ وَ الطَّیۡرَ ؕ وَ کُنَّا فٰعِلِیۡنَ ﴿۷۹﴾', 'تو ہم نے فیصلہ کرنے کا طریق سلیمان کو سمجھا دیا۔ اور ہم نے دونوں کو حکمت و نبوت اور علم بخشا تھا اور ہم نے پہاڑوں کو داؤد کا مسخر کر دیا تھا کہ انکے ساتھ تسبیح کرتے تھے اور پرندوں کو بھی مسخر کر دیا تھا اور ہم ہی ایسا کرنے والے تھے۔', 'پھر سمجھا دیا ہم نے وہ فیصلہ سلیمان کو اور دونوں کو دیا تھا ہم نے حکم اور سمجھ [۹۱] اور تابع کیے ہم نے داؤد کے ساتھ پہاڑ تسبیح پڑھا کرتے اور اڑتے جانور [۹۲] اور یہ سب کچھ ہم نے کیا [۹۳]', 'And We made Sulaiman (Solomon) to understand (the case), and to each of them We gave Hukman (right judgement of the affairs and Prophethood) and knowledge. And We subjected the mountains and the birds to glorify Our Praises along with Dawood (David), And it was We Who were the doers (of all these things).', 'So, We enabled Sulaimān to understand it. And to each one of them We gave wisdom and knowledge. And with Dawūd We subjugated the mountains that pronounced tasbīH (Allah’s purity), and the birds as well. And We were the One who did (it).'),
(2563, 21, 80, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ عَلَّمۡنٰہُ  صَنۡعَۃَ  لَبُوۡسٍ لَّکُمۡ لِتُحۡصِنَکُمۡ مِّنۡۢ بَاۡسِکُمۡ ۚ فَہَلۡ اَنۡتُمۡ شٰکِرُوۡنَ ﴿۸۰﴾', 'اور ہم نے تمہارے لئے انکو ایک طرح کا لباس بنانا بھی سکھا دیا تاکہ تمکو لڑائی کے ضرر سے بچائے پس تمکو شکرگذار ہونا چاہیئے۔', 'اور اُسکو سکھلایا ہم نے بنانا ایک تمہارا لباس کہ بچاؤ ہو تمکو لڑائی میں [۹۴] سو کچھ تم شکر کرتے ہو [۹۵]', 'And We taught him the making of metal coats of mail (for battles), to protect you in your fighting. Are you then grateful?', 'We taught him the skill of making armor as dress for you to protect you from what may harm you (in combat). So are you grateful?'),
(2564, 21, 81, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ لِسُلَیۡمٰنَ الرِّیۡحَ عَاصِفَۃً تَجۡرِیۡ بِاَمۡرِہٖۤ  اِلَی الۡاَرۡضِ الَّتِیۡ بٰرَکۡنَا فِیۡہَا ؕ وَ کُنَّا بِکُلِّ  شَیۡءٍ  عٰلِمِیۡنَ ﴿۸۱﴾', 'اور ہم نے تیز ہوا سلیمان کے تابع فرمان کر دی تھی جو انکے حکم سے اس ملک میں چلتی تھی جس میں ہم نے برکت دی تھی یعنی شام کیطرف اور ہم ہر چیز سے خبردار ہیں۔', 'اور سلیمان کے تابع کی ہوا زور سے چلنے والی کہ چلتی اسکے حکم اسے اُس زمین کی طرف جہاں برکت دی ہے ہم نے [۹۶] اور ہم کو سب چیز کی خبر ہے [۹۷]', 'And to Sulaiman (Solomon) (We subjected) the wind strongly raging, running by his command towards the land which We had blessed. And of everything We are the All-Knower.', 'And for Sulaimān, (We subjugated) the violent wind that blew under his command to the land in which We placed Our blessings. And We were the One who knew everything.'),
(2565, 21, 82, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ مِنَ الشَّیٰطِیۡنِ مَنۡ یَّغُوۡصُوۡنَ لَہٗ وَ یَعۡمَلُوۡنَ عَمَلًا دُوۡنَ ذٰلِکَ ۚ وَ کُنَّا لَہُمۡ حٰفِظِیۡنَ ﴿ۙ۸۲﴾', 'اور بڑے بڑے جنات کو بھی انکے تابع کر دیا تھا کہ ان میں سے بعض انکے لئے غوطہ خوری کرتے تھے اور اسکے علاوہ اور کام بھی کرتے تھے۔ اور ہم انکے نگہبان تھے۔', 'اور تابع کئے کتنے شیطان جو غوطہ لگاتے اُسکے واسطے اور بہت سے کام بناتے اسکے سوائے [۹۸] اور ہم نے اُنکو تھام رکھا تھا [۹۹]', 'And of the Shayatin (devils) (from the jinns) were some who dived for him, and did other work besides that; and it was We Who guarded them.', 'And from the devils, (We subjugated for him) those who dived in water for him and did jobs other than that. And We were the One who kept watch over them.'),
(2566, 21, 83, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ اَیُّوۡبَ اِذۡ نَادٰی رَبَّہٗۤ  اَنِّیۡ مَسَّنِیَ الضُّرُّ وَ اَنۡتَ  اَرۡحَمُ  الرّٰحِمِیۡنَ ﴿ۚۖ۸۳﴾', 'اور ایوب کو یاد کرو جب انہوں نے اپنے پروردگار سے دعا کی کہ مجھے تکلیف پہنچی ہے اور تو سب سے بڑھ کر رحم کرنے والا ہے۔', 'اور ایوب کو جس وقت پکارا اُس نے اپنے رب کو کہ مجھ پر پڑی ہے تکلیف اور تو ہے سب رحم  والوں سے رحم کرنے والا', 'And (remember) Ayoob (Job), when he cried to his Lord: \"Verily, distress has seized me, and You are the Most Merciful of all those who show mercy.\"', 'And (remember) Ayyūb (Job), when he called his Lord saying, “Here I am, afflicted by pain and You are the most merciful of all the merciful.”'),
(2567, 21, 84, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'فَاسۡتَجَبۡنَا لَہٗ فَکَشَفۡنَا مَا بِہٖ مِنۡ ضُرٍّ وَّ اٰتَیۡنٰہُ  اَہۡلَہٗ  وَ مِثۡلَہُمۡ مَّعَہُمۡ  رَحۡمَۃً مِّنۡ عِنۡدِنَا وَ ذِکۡرٰی  لِلۡعٰبِدِیۡنَ  ﴿۸۴﴾', 'تو ہم نے انکی دعا قبول کر لی اور جو انکو تکلیف تھی وہ دور کر دی اور انکو بال بچے بھی عطا فرمائے اور اپنی مہربانی سے انکے ساتھ اتنے ہی اور بخشے اور عبادت کرنے والوں کے لئے یہ نصیحت ہے۔', 'پھر ہم نے سن لی اُسکی فریاد سو دور کر دی جو اُس پر تھی تکلیف اور عطا کئے اُسکو اسکے گھر والے اور اتنے ہی اور اُنکے ساتھ [۱۰۰] رحمت اپنی طرف سے اور نصیحت بندگی کرنے والوں کو [۱۰۱]', 'So We answered his call, and We removed the distress that was on him, and We restored his family to him (that he had lost), and the like thereof along with them, as a mercy from Ourselves and a Reminder for all who worship Us.', 'So, We answered his prayer and removed whatever pain he had, and gave him (back) his family and the like thereof along with them, as a mercy from Our own Self and as a lesson for the worshippers.'),
(2568, 21, 85, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ اِسۡمٰعِیۡلَ وَ اِدۡرِیۡسَ وَ ذَاالۡکِفۡلِ ؕ کُلٌّ  مِّنَ  الصّٰبِرِیۡنَ ﴿ۚۖ۸۵﴾', 'اور اسمٰعیل اور ادریس اور ذوالکفل کو بھی یاد کرو یہ سب صبر کرنے والے تھے۔', 'اور اسمٰعیل اور ادریس اور ذوالکفل کو یہ سب ہیں صبر والے [۱۰۲]', 'And (remember) Ismaeel (Ishmael), and Idris (Enoch) and Dhul-Kifl (Isaiah), all were from among As-Sabirin (the patient ones, etc.).', 'And (remember) Ismā‘īl and Idrīs and Dhul-Kifl. Each one of them was of those who observed patience.'),
(2569, 21, 86, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ اَدۡخَلۡنٰہُمۡ فِیۡ رَحۡمَتِنَا ؕ اِنَّہُمۡ مِّنَ الصّٰلِحِیۡنَ ﴿۸۶﴾', 'اور ہم نے انکو اپنی رحمت میں داخل کیا۔ بلاشبہ وہ نیکوکار تھے۔', 'اور لے لیا ہم نے اُنکو اپنی رحمت میں وہ ہیں نیک بختوں میں', 'And We admitted them to Our Mercy. Verily, they were of the righteous.', 'And We admitted them to Our mercy. Surely, they were of the righteous.'),
(2570, 21, 87, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ ذَاالنُّوۡنِ  اِذۡ ذَّہَبَ مُغَاضِبًا فَظَنَّ اَنۡ لَّنۡ نَّقۡدِرَ عَلَیۡہِ فَنَادٰی فِی الظُّلُمٰتِ  اَنۡ  لَّاۤ  اِلٰہَ   اِلَّاۤ  اَنۡتَ  سُبۡحٰنَکَ ٭ۖ اِنِّیۡ  کُنۡتُ  مِنَ الظّٰلِمِیۡنَ ﴿ۚۖ۸۷﴾', 'اور مچھلی والے پیغمبر یعنی یونس کو یاد کرو جب وہ اپنی قوم سے ناراض ہو کر غصے کی حالت میں چل دیئے اور خیال کیا کہ ہم ان پر گرفت نہیں کریں گے مگر پھر اندھیروں میں اللہ کو پکارنے لگے کہ تیرے سوا کوئی معبود نہیں۔ تو پاک ہے اور بیشک میں قصوروار ہوں۔', 'اور مچھلی والے کو جب چلا گیا غصہ ہو کر [۱۰۳] پھر سمجھا کہ ہم نہ پکڑ سکیں گے اُسکو  [۱۰۴] پھر پکارا اُن اندھیروں میں [۱۰۵] کہ کوئی حاکم نہیں سوائے تیرے تو بے عیب ہے میں تھا گنہگاروں سے [۱۰۶]', 'And (remember) Dhan-Noon (Jonah), when he went off in anger, and imagined that We shall not punish him (i.e. the calamites which had befallen him)! But he cried through the darkness (saying): La ilaha illa Anta (none has the right to be worshipped but You (O Allah)), Glorified (and Exalted) are You (above all that (evil) they associate with You). Truly, I have been of the wrong-doers.\"', 'And (remember) Dhunnūn (the man of the fish, namely Yūnus X), when he walked away in anger and thought that We would never put him to trouble. Then, he called (Us) in depths of darkness saying, “There is no god but You. Pure are You. Indeed I was among the wrongdoers”.'),
(2571, 21, 88, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'فَاسۡتَجَبۡنَا لَہٗ ۙ وَ نَجَّیۡنٰہُ مِنَ الۡغَمِّ ؕ وَ کَذٰلِکَ  نُــۨۡجِی الۡمُؤۡمِنِیۡنَ ﴿۸۸﴾', 'تو ہم نے انکی دعا قبول کر لی اور انکو غم سے نجات بخشی۔ اور ایمان والوں کو ہم اسی طرح نجات دیا کرتے ہیں۔', 'پھر سن لی ہم نے اُسکی فریاد اور بچا دیا اُسکو  اُس گھٹنے سے اور یوں ہم بچا دیتےہیں ایمان والوں کو [۱۰۷]', 'So We answered his call, and delivered him from the distress. And thus We do deliver the believers (who believe in the Oneness of Allah, abstain from evil and work righteousness).', 'So We responded to him and rescued him from the distress. And this is how We rescue the believers.'),
(2572, 21, 89, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ زَکَرِیَّاۤ  اِذۡ نَادٰی رَبَّہٗ رَبِّ لَا تَذَرۡنِیۡ فَرۡدًا  وَّ  اَنۡتَ  خَیۡرُ  الۡوٰرِثِیۡنَ ﴿ۚۖ۸۹﴾', 'اور زکریا کو یاد کرو جب انہوں نے اپنے پروردگار کو پکارا کہ پروردگار! مجھے اکیلا نہ چھوڑ اور تو تو سب سے بہتر وارث ہے۔', 'اور زکریا کو جب پکارا اُس نے اپنے رب کو اے رب نہ چھوڑ مجھ کو اکیلا [۱۰۸] اور تو ہے سب سے بہتر وارث [۱۰۹]', 'And (remember) Zakariya (Zachariah), when he cried to his Lord: \"O My Lord! Leave me not single (childless), though You are the Best of the inheritors.\"', 'And (remember) Zakariyyā when he called his Lord, “My Lord, do not leave me alone and You are the best of inheritors.”'),
(2573, 21, 90, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'فَاسۡتَجَبۡنَا لَہٗ ۫ وَ وَہَبۡنَا لَہٗ یَحۡیٰی وَ اَصۡلَحۡنَا لَہٗ  زَوۡجَہٗ ؕاِنَّہُمۡ کَانُوۡا یُسٰرِعُوۡنَ فِی الۡخَیۡرٰتِ وَ یَدۡعُوۡنَنَا رَغَبًا وَّ رَہَبًا ؕوَ کَانُوۡا لَنَا خٰشِعِیۡنَ ﴿۹۰﴾', 'تو ہم نے انکی پکار سن لی اور انکو یحیٰی بخشے اور انکی بیوی کو اولاد کے قابل بنا دیا۔ یہ لوگ لپک لپک کر نیکیاں کرتے اور ہمیں امید اور خوف سے پکارتے اور ہمارے آگے عاجزی کیا کرتے تھے۔', 'پھر ہم نے سن لی اُسکی دعا اور بخشا اُسکو یحیٰی اور اچھا کر دیا اُسکی عورت کو [۱۱۰] وہ لوگ دوڑتے تھے بھلائیوں پر اور پکارتے تھے ہم کو توقع سے اور ڈر سے اور تھے ہمارے آگے عاجز [۱۱۱]', 'So We answered his call, and We bestowed upon him Yahya (John), and cured his wife (to bear a child) for him. Verily, they used to hasten on to do good deeds, and they used to call on Us with hope and fear, and used to humble themselves before Us.', 'So, We responded to him and gave him YaHyā and made his wife good for him. They used to race towards the good deeds and call Us with hope and fear; and they were humble to Us.'),
(2574, 21, 91, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ الَّتِیۡۤ  اَحۡصَنَتۡ فَرۡجَہَا فَنَفَخۡنَا فِیۡہَا مِنۡ رُّوۡحِنَا وَ جَعَلۡنٰہَا وَ ابۡنَہَاۤ  اٰیَۃً  لِّلۡعٰلَمِیۡنَ ﴿۹۱﴾', 'اور ان خاتون یعنی مریم کو بھی یاد کرو جنہوں نے اپنی عفت کو محفوظ رکھا۔ تو ہم نے ان میں اپنی روح پھونک دی اور انکو اور انکے بیٹے کو اہل عالم کے لئے نشانی بنا دیا۔', 'اور وہ عورت جس نے قابو میں رکھی اپنی شہوت [۱۱۲] پھر پھونک دی ہم نے اُس عورت میں اپنی روح [۱۱۳] اور کیا اُسکو اور اُسکے بیٹے کو نشانی جہان والوں کے واسطے [۱۱۴]', 'And (remember) she who guarded her chastity (Virgin Maryam (Mary)), We breathed into (the sleeves of) her (shirt or garment) (through Our Rooh Jibrael (Gabriel)), and We made her and her son (Iesa (Jesus)) a sign for Al-Alamin (the mankind and jinns).', 'And (remember) her who protected her private part (that is, Maryam). So, We blew in her (a life) through Our Spirit, and made her and her son (‘Īsā X) a sign for all the worlds.'),
(2575, 21, 92, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'اِنَّ ہٰذِہٖۤ  اُمَّتُکُمۡ اُمَّۃً  وَّاحِدَۃً ۫ۖ وَّ اَنَا رَبُّکُمۡ  فَاعۡبُدُوۡنِ ﴿۹۲﴾', 'لوگو یہ تمہاری جماعت ایک ہی جماعت ہے اور میں تمہارا پروردگار ہوں تو میری ہی عبادت کیا کرو۔', 'یہ لوگ ہیں  تمہارے دین کے سب ایک دین پر اور میں ہوں رب تمہارا سو میری بندگی کرو [۱۱۵]', 'Truly! This, your Ummah (Sharia or religion (Islamic Monotheism)) is one religion, and I am your Lord, therefore worship Me (Alone). (Tafseer Ibn Katheer)', 'Surely, this is the fraternity of your Faith, a single Faith, and I am your Lord; so worship Me.'),
(2576, 21, 93, 6, 6, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ تَقَطَّعُوۡۤا  اَمۡرَہُمۡ بَیۡنَہُمۡ ؕ کُلٌّ اِلَیۡنَا رٰجِعُوۡنَ ﴿٪۹۳﴾', 'اور لوگ اپنے معاملے میں باہم متفرق ہو گئے۔ مگر آخر سب ہماری طرف رجوع کرنے والے ہیں۔', 'اور ٹکڑے ٹکڑے بانٹ لیا لوگوں نے آپس میں اپنا کام [۱۱۶] سب ہمارےپاس پھر آئیں گے [۱۱۷]', 'But they have broken up and differed as regards their religion among themselves. (And) they all shall return to Us.', 'But they have separated their ways from one another. All of them have to return to Us.'),
(2577, 21, 94, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'فَمَنۡ یَّعۡمَلۡ مِنَ الصّٰلِحٰتِ وَ ہُوَ  مُؤۡمِنٌ فَلَا کُفۡرَانَ لِسَعۡیِہٖ ۚ وَ اِنَّا لَہٗ کٰتِبُوۡنَ ﴿۹۴﴾', 'اب جو نیک کام کرے گا اور مومن بھی ہوگا تو اسکی کوشش رائیگاں نہیں جائے گی۔ اور ہم اس کے لئے ثواب اعمال لکھ رہے ہیں۔', 'سو جو کوئی کرےکچھ نیک کام اور وہ رکھتا ہو ایمان سو اکارت نہ کریں گے اُسکی سعی کو اور ہم اُسکو لکھ لیتے ہیں [۱۱۸]', 'So whoever does righteous good deeds while he is a believer (in the Oneness of Allah Islamic Monotheism), his efforts will not be rejected. Verily! We record it in his Book of deeds.', 'So, whoever does righteous deeds, while he is a believer, his effort will not be rejected, and We are to put it on record.'),
(2578, 21, 95, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ حَرٰمٌ عَلٰی قَرۡیَۃٍ  اَہۡلَکۡنٰہَاۤ  اَنَّہُمۡ لَا  یَرۡجِعُوۡنَ ﴿۹۵﴾', 'اور جس بستی والوں کو ہم نے ہلاک کر دیا محال ہے کہ رجوع کریں وہ واپس نہیں آئیں گے۔', 'اور مقرر ہو چکا ہر بستی پر جس کو غارت کر دیا ہم نے کہ وہ پھر کر نہیں آئیں گے [۱۱۹]', 'And a ban is laid on every town (population) which We have destroyed that they shall not return (to this world again, nor repent to Us).', 'It is banned for (the people of) a town that We destroyed that they come back'),
(2579, 21, 96, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'حَتّٰۤی  اِذَا  فُتِحَتۡ یَاۡجُوۡجُ وَ مَاۡجُوۡجُ وَ ہُمۡ  مِّنۡ  کُلِّ  حَدَبٍ  یَّنۡسِلُوۡنَ ﴿۹۶﴾', 'یہاں تک کہ یاجوج اور ماجوج کھول دیئے جائیں اور وہ ہر بلندی سے نیچے آ رہے ہوں۔', 'یہاں تک کہ جب کھول دئے جائیں یاجوج اور ماجوج اور وہ ہر اوچان سے پھسلتے چلے آئیں [۱۲۰]', 'Until, when Yajooj and Majooj (Gog and Magog) are let loose (from their barrier), and they swiftly swarm from every mound.', 'until when the Ya’jūj and Ma’jūj (Gog and Magog) are released, while they run down from every height,'),
(2580, 21, 97, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ اقۡتَرَبَ الۡوَعۡدُ الۡحَقُّ فَاِذَا ہِیَ شَاخِصَۃٌ  اَبۡصَارُ الَّذِیۡنَ کَفَرُوۡا ؕ یٰوَیۡلَنَا قَدۡ کُنَّا فِیۡ غَفۡلَۃٍ  مِّنۡ  ہٰذَا بَلۡ کُنَّا ظٰلِمِیۡنَ ﴿۹۷﴾', 'اور قیامت کا سچا وعدہ قریب آجائے۔ تو ناگہاں کافروں کی آنکھیں پھٹی کی پھٹی رہ جائیں اور کہنے لگیں کہ ہائے شامت ہم اس حال سے غفلت میں رہے بلکہ ہم خود ہی ظالم تھے۔', 'اور نزدیک آ لگے سچا وعدہ پھر اس دم اوپر لگی رہ جائیں منکروں کی آنکھیں ہائے کمبختی ہماری ہم بے خبر رہے اس سے [۱۲۱] نہیں پر ہم تھے گنہگار [۱۲۲]', 'And the true promise (Day of Resurrection) shall draw near (of fulfillment). Then (when mankind is resurrected from their graves), you shall see the eyes of the disbelievers fixedly stare in horror. (They will say): \"Woe to us! We were indeed heedless of this; nay, but we were Zalimoon (polytheists and wrong-doers, etc.).\"', 'and the True Promise draws near, then it will so happen that the eyes of the disbelievers shall remain upraised (in terror, and they will say,) “Alas to us! We were in negligence about this; rather we were transgressors.”'),
(2581, 21, 98, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'اِنَّکُمۡ وَ مَا تَعۡبُدُوۡنَ مِنۡ دُوۡنِ اللّٰہِ حَصَبُ جَہَنَّمَ ؕ اَنۡتُمۡ  لَہَا وٰرِدُوۡنَ ﴿۹۸﴾', 'کافرو اس روز تم اور جنکی تم اللہ کے سوا عبادت کرتے ہو دوزخ کا ایندھن ہونگے اور تم سب اس میں داخل ہو کر رہو گے۔', 'تم اور جو کچھ تم پوجتے ہو اللہ کے سوائے ایندھن ہے دوزخ کا تمکو اُس پر پہنچنا ہے [۱۲۳]', 'Certainly! You (disbelievers) and that which you are worshipping now besides Allah, are (but) fuel for Hell! (Surely), you will enter it.', 'Surely, you and whatever you worship other than Allah are the fuel of Jahannam.. There you will have to arrive.'),
(2582, 21, 99, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'لَوۡ کَانَ ہٰۤؤُلَآءِ اٰلِہَۃً مَّا وَرَدُوۡہَا ؕ وَ کُلٌّ  فِیۡہَا خٰلِدُوۡنَ ﴿۹۹﴾', 'اگر یہ لوگ درحقیقت معبود ہوتے تو اس میں داخل نہ ہوتے۔ سب اس میں ہمیشہ رہیں گے۔', 'اگر ہوتے یہ بت معبود تو نہ پہنچتے اُس پر اور سارے اُس میں سدا پڑے رہیں گے [۱۲۴]', 'Had these (idols, etc.) been aliha (gods), they would not have entered there (Hell), and all of them will abide therein.', 'Had they been gods, they would not have arrived at it, and all of them will remain there forever.'),
(2583, 21, 100, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'لَہُمۡ فِیۡہَا زَفِیۡرٌ  وَّ  ہُمۡ فِیۡہَا لَا یَسۡمَعُوۡنَ ﴿۱۰۰﴾', 'وہاں انکو چلانا ہو گا اور اس میں کچھ اور نہ سن سکیں گے۔', 'اُنکو وہاں چلانا ہے اور اُس میں کچھ نہ سنیں گے [۱۲۵]', 'Therein breathing out with deep sighs and roaring will be their portion, and therein they will hear not.', 'For them, there will be screams in it and they will not hear.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(2584, 21, 101, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'اِنَّ الَّذِیۡنَ سَبَقَتۡ لَہُمۡ مِّنَّا الۡحُسۡنٰۤی ۙ اُولٰٓئِکَ عَنۡہَا مُبۡعَدُوۡنَ ﴿۱۰۱﴾ۙ', 'جن لوگوں کے لئے ہماری طرف سے پہلے بھلائی مقرر ہو چکی ہے وہ اس سے دور رکھے جائیں گے۔', 'جنکے لئے پہلے سے ٹھہر چکی ہماری طرف سے نیکی وہ اُس سے دور رہیں گے [۱۲۶]', 'Verily those for whom the good has preceded from Us, they will be removed far therefrom (Hell) (e.g. Iesa (Jesus), son of Maryam (Mary); Uzair (Ezra), etc.).', 'As for those for whom the good (news) from Us has come earlier, they will be kept far away from it.'),
(2585, 21, 102, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'لَا یَسۡمَعُوۡنَ حَسِیۡسَہَا ۚ وَ ہُمۡ  فِیۡ مَا اشۡتَہَتۡ  اَنۡفُسُہُمۡ  خٰلِدُوۡنَ ﴿۱۰۲﴾ۚ', 'یہاں تک کہ اسکی آواز بھی تو نہیں سنیں گے۔ اور جو کچھ ان کا جی چاہے گا اس میں یعنی ہر طرح کے عیش اور مزے میں ہمیشہ رہیں گے۔', 'نہیں سنیں گے اُسکی آہٹ اور وہ اپنے جی کے مزوں میں سدا رہیں گے [۱۲۷]', 'They shall not hear the slightest sound of it (Hell), while they abide in that which their ownselves desire.', 'They will not hear the slightest of its sound, and they will remain forever in what their souls desire.'),
(2586, 21, 103, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'لَا یَحۡزُنُہُمُ الۡفَزَعُ الۡاَکۡبَرُ وَ تَتَلَقّٰہُمُ الۡمَلٰٓئِکَۃُ ؕ ہٰذَا یَوۡمُکُمُ الَّذِیۡ  کُنۡتُمۡ تُوۡعَدُوۡنَ ﴿۱۰۳﴾', 'انکو اس دن کا بڑا بھاری خوف غمگین نہیں کرے گا۔ اور فرشتے انکو لینے آئیں گے اور کہیں گے کہ یہی وہ دن ہے جس کا تم سے وعدہ کیا جاتا تھا۔', 'نہ غم ہو گا اُنکو اس بڑی گھبراہٹ میں [۱۲۸] اور لینے آئیں گے اُنکو فرشتے آج دن تمہارا ہے جس کا تم سے وعدہ کیا گیا تھا [۱۲۹]', 'The greatest terror (on the Day of Resurrection) will not grieve them, and the angels will meet them, (with the greeting): \"This is your Day which you were promised.\"', 'They shall not be grieved by the Biggest Panic, and the angels shall receive them (saying), “This is your day that you had been promised”'),
(2587, 21, 104, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'یَوۡمَ نَطۡوِی السَّمَآءَ کَطَیِّ السِّجِلِّ لِلۡکُتُبِ ؕ کَمَا بَدَاۡنَاۤ  اَوَّلَ خَلۡقٍ نُّعِیۡدُہٗ ؕ وَعۡدًا عَلَیۡنَا ؕ اِنَّا کُنَّا فٰعِلِیۡنَ ﴿۱۰۴﴾', 'جس دن ہم آسمان کو اس طرح لپیٹ لیں گے جیسے خطوں کا طومار لپیٹ لیتے ہیں جس طرح ہم نے کائنات کو پہلے پیدا کیا تھا اسی طرح دوبارہ پیدا کر دیں گے یہ وعدہ ہے جس کا پورا کرنا لازم ہے۔ ہم ایسا ضرور کرنے والے ہیں۔', 'جس دن ہم لپیٹ دیں گے آسمان کو جیسے لپیٹتے ہیں طومار میں کاغذ [۱۳۰] جیسا سرے سے بنایا تھا ہم نے پہلی بار پھر اُسکو دہرائیں گے وعدہ ضرور ہو چکا ہے ہم پر ہم کو پورا کرنا ہے [۱۳۱]', 'And (remember) the Day when We shall roll up the heavens like a scroll rolled up for books, as We began the first creation, We shall repeat it, (it is) a promise binding upon Us. Truly, We shall do it.', '- the Day when We roll up the sky like a scroll rolls up the writings. Just as We originated the first creation, so We shall bring it back again - a promise (undertaken to be binding) on Us. We are sure to do it.'),
(2588, 21, 105, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ لَقَدۡ کَتَبۡنَا فِی الزَّبُوۡرِ مِنۡۢ بَعۡدِ الذِّکۡرِ اَنَّ الۡاَرۡضَ یَرِثُہَا عِبَادِیَ الصّٰلِحُوۡنَ ﴿۱۰۵﴾', 'اور ہم نے نصیحت کی کتاب یعنی تورات کے بعد زبور میں لکھ دیا تھا کہ میرے نیکوکار بندے ملک کے وارث ہوں گے۔', 'اور ہم نے لکھ دیا ہے زبور میں نصیحت کے پیچھے کہ آخر زمین پر مالک ہوں گے میرے نیک بندے [۱۳۲]', 'And indeed We have written in Zaboor (Psalms) (i.e. all the revealed Holy Books the Taurat (Torah), the Injeel (Gospel), the Quran) after (We have already written in) Al-Lauh Al-Mahfooz (the Book, that is in the heaven with Allah), that My righteous slaves shall inherit the land (i.e. the land of Paradise).', 'And We have written in Zabūr (Psalms) after the advice that the land will be inherited by My righteous slaves.'),
(2589, 21, 106, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'اِنَّ فِیۡ ہٰذَا لَبَلٰغًا لِّقَوۡمٍ  عٰبِدِیۡنَ ﴿۱۰۶﴾ؕ', 'عبادت کرنے والے لوگوں کے لئے اس میں اللہ کے حکموں کی تبلیغ ہے۔', 'اس میں مطلب کو پہنچتے ہیں لوگ بندگی والے [۱۳۳]', 'Verily, in this (the Quran) there is a plain Message for people who worship Allah (i.e. the true, real believers of Islamic Monotheism who act practically on the Quran and the Sunnah legal ways of the Prophet SAW).', 'Surely, in this (Qur’ān) there is a message conveyed to a people who worship (Allah).'),
(2590, 21, 107, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ مَاۤ  اَرۡسَلۡنٰکَ اِلَّا رَحۡمَۃً  لِّلۡعٰلَمِیۡنَ ﴿۱۰۷﴾', 'اور اے نبی ﷺ ہم نے تمکو تمام جہانوں کے لئے رحمت بنا کر بھیجا ہے۔', 'اور تجھ کو جو ہم نے بھیجا سو مہربانی کر کر جہاں کے لوگوں پر [۱۳۴]', 'And We have sent you (O Muhammad SAW) not but as a mercy for the Alameen (mankind, jinns and all that exists).', 'And We have not sent you but as mercy for all the worlds.'),
(2591, 21, 108, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قُلۡ اِنَّمَا یُوۡحٰۤی  اِلَیَّ  اَنَّمَاۤ  اِلٰـہُکُمۡ  اِلٰہٌ وَّاحِدٌ ۚ فَہَلۡ اَنۡتُمۡ مُّسۡلِمُوۡنَ ﴿۱۰۸﴾', 'کہدو کہ مجھ پر اللہ کی طرف سے یہ وحی آتی ہے کہ تم سب کا معبود ایک ہی معبود ہے تو کیا تم فرمانبردار ہو جاتے ہو۔', 'تو کہہ مجھ کو تو حکم یہی آیا ہے کہ معبود تمہارا ایک معبود ہے پھر کیا ہو تم حکمبرداری کرنے والے [۱۳۵]', 'Say (O Muhammad SAW): \"It is revealed to me that your Ilah (God) is only one Ilah (God - Allah). Will you then submit to His Will (become Muslims and stop worshipping others besides Allah)?\"', 'Say, “What is revealed to me is simply that your God is One God. So do you submit?”'),
(2592, 21, 109, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'فَاِنۡ تَوَلَّوۡا فَقُلۡ اٰذَنۡتُکُمۡ عَلٰی سَوَآءٍ ؕ وَ اِنۡ  اَدۡرِیۡۤ  اَقَرِیۡبٌ اَمۡ بَعِیۡدٌ مَّا تُوۡعَدُوۡنَ ﴿۱۰۹﴾', 'پھر اگر یہ لوگ منہ پھیریں تو کہدو کہ میں نے تم سب کو یکساں احکام الہٰی سے آگاہ کر دیا ہے۔ اور مجھکو معلوم نہیں کہ جس چیز کا تم سے وعدہ کیا جاتا ہے وہ عنقریب آنے والی ہے یا اس کا وقت دور ہے۔', 'پھر اگر وہ منہ موڑیں تو تو کہدے میں نے خبر کر دی تمکو دونوں طرف باربار [۱۳۶] اور میں نہیں جانتا نزدیک ہے یا دور ہے جو تم سے وعدہ ہوا [۱۳۷]', 'But if they (disbelievers, idolaters, Jews, Christians, polytheists, etc.) turn away (from Islamic Monotheism) say (to them O Muhammad SAW): \"I give you a notice (of war as) to be known to us all alike. And I know not whether that which you are promised (i.e. the torment or the Day of Resurrection) is near or far.\"', 'But, if they turn away, then say (to them), “I have warned you all alike, and I do not know whether what you have been warned of is near or far.'),
(2593, 21, 110, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'اِنَّہٗ  یَعۡلَمُ  الۡجَہۡرَ  مِنَ الۡقَوۡلِ وَ یَعۡلَمُ مَا تَکۡتُمُوۡنَ ﴿۱۱۰﴾', 'جو بات پکار کر کی جائے وہ اسے بھی جانتا ہے اور جو تم چھپاتے ہو وہ اس سے بھی واقف ہے۔', 'وہ رب جانتا ہے جو بات پکار کر کرو اور جانتا ہے جو تم چھپاتے ہو [۱۳۸]', '(Say O Muhammad SAW) Verily, He (Allah) knows that which is spoken aloud (openly) and that which you conceal.', 'Surely, He knows what is spoken openly and He knows what you conceal.'),
(2594, 21, 111, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'وَ اِنۡ اَدۡرِیۡ لَعَلَّہٗ  فِتۡنَۃٌ  لَّکُمۡ وَ مَتَاعٌ  اِلٰی  حِیۡنٍ ﴿۱۱۱﴾', 'اور میں نہیں جانتا شاید وہ تمہارے لئے آزمائش ہو اور ایک مدت تک تم اس سے فائدہ اٹھاتے رہو۔', 'اور میں نہیں جانتا شاید تاخیر میں تمکو جانچنا ہے اور فائدہ دینا ہے ایک وقت تک [۱۳۹]', 'And I know not, perhaps it may be a trial for you, and an enjoyment for a while.', 'And I do not know; perhaps it is a trial for you and an enjoyment for a while.”'),
(2595, 21, 112, 7, 7, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الانبیآء', 'قٰلَ رَبِّ احۡکُمۡ بِالۡحَقِّ ؕ وَ رَبُّنَا الرَّحۡمٰنُ الۡمُسۡتَعَانُ عَلٰی مَا تَصِفُوۡنَ ﴿۱۱۲﴾٪', 'پیغمبر نے کہا کہ اے میرے پروردگار حق کے ساتھ فیصلہ کر دے اور ہمارا پروردگار جو بڑا مہربان ہے اسی سے ان باتوں میں جو تم بیان کرتے ہو مدد مانگی جاتی ہے۔', 'رسول نے کہا اے رب فیصلہ کر انصاف کا [۴۰] اور رب ہمارا رحمٰن ہے اُسی سے مدد مانگتے ہیں اُن باتوں پر جو تم بتلاتے ہو [۱۴۱]', 'He (Muhammad SAW) said:\"My Lord! Judge You in truth! Our Lord is the Most Beneficent, Whose Help is to be sought against that which you attribute (unto Allah that He has offspring, and unto Muhammad SAW that he is a sorcerer, and unto the Quran that it is poetry, etc.)!\"', 'He (Our Messenger) said, “My Lord, judge with truth. And Our Lord is the RaHmān (All-Merciful), the One whose help is sought against what you describe.'),
(2596, 22, 1, 1, 8, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'یٰۤاَیُّہَا النَّاسُ اتَّقُوۡا رَبَّکُمۡ ۚ اِنَّ  زَلۡزَلَۃَ  السَّاعَۃِ  شَیۡءٌ  عَظِیۡمٌ ﴿۱﴾', 'لوگو اپنے پروردگار سے ڈرو کہ قیامت کا زلزلہ ایک حادثہ عظیم ہے۔', 'لوگو ڈرو اپنے رب سے بیشک بھونچال قیامت کا ایک بڑی چیز ہے', 'O mankind! Fear your Lord and be dutiful to Him! Verily, the earthquake of the Hour (of Judgement) is a terrible thing.', 'O mankind, fear your Lord. Indeed the quake of the (destined) Hour is something terrible.'),
(2597, 22, 2, 1, 8, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'یَوۡمَ تَرَوۡنَہَا تَذۡہَلُ کُلُّ مُرۡضِعَۃٍ عَمَّاۤ اَرۡضَعَتۡ وَ تَضَعُ کُلُّ ذَاتِ حَمۡلٍ حَمۡلَہَا وَ تَرَی النَّاسَ سُکٰرٰی وَ مَا ہُمۡ  بِسُکٰرٰی وَ لٰکِنَّ عَذَابَ اللّٰہِ شَدِیۡدٌ ﴿۲﴾', 'اے مخاطب جس دن تو اسکو دیکھے گا اس دن یہ حال ہو گا کہ تمام دودھ پلانے والی عورتیں اپنے بچوں کو بھول جائیں گی۔ اور تمام حمل والیوں کے حمل گر پڑیں گے اور لوگ تجھ کو مدہوش نظر آئیں گے حالانکہ وہ مدہوش نہیں ہوں گے بلکہ عذاب دیکھ کر مدہوش ہو رہے ہوں گے بیشک اللہ کا عذاب بڑا سخت ہے۔', 'جس دن اُسکو دیکھو گے بھول جائیگی ہر دودھ پلانے والی اپنے دودھ پلائے کو اور ڈال دیگی ہر پیٹ والی اپنا پیٹ اور تو دیکھے لوگوں پر نشہ اور اُن پر نشہ نہیں پر آفت اللہ کی سخت ہے [۱]', 'The Day you shall see it, every nursing mother will forget her nursling, and every pregnant one will drop her load, and you shall see mankind as in a drunken state, yet they will not be drunken, but severe will be the Torment of Allah.', 'The day you will see it, every suckling female will forget that which she suckles, and every female having pregnancy shall abort her fetus, and you will see people as if they are drunk, while they are not drunk, but Allah’s torment is (so) severe.'),
(2598, 22, 3, 1, 8, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ مِنَ النَّاسِ مَنۡ یُّجَادِلُ فِی اللّٰہِ  بِغَیۡرِ عِلۡمٍ  وَّ  یَتَّبِعُ  کُلَّ  شَیۡطٰنٍ  مَّرِیۡدٍ ۙ﴿۳﴾', 'اور بعض لوگ ایسے ہیں جو اللہ کی شان میں علم کے بغیر جھگڑتے اور ہر شیطان سرکش کی پیروی کرتے ہیں۔', 'اور بعضے لوگ وہ ہیں جو جھگڑتے ہیں اللہ کی بات میں بیخبری سے [۲] اور پیروی کرتا ہے ہر شیطان سرکش کی [۳]', 'And among mankind is he who disputes concerning Allah, without knowledge, and follows every rebellious (disobedient to Allah) Shaitan (devil) (devoid of each and every kind of good).', 'Among the people there is one who debates about Allah without knowledge, and follows every rebellious Satan,'),
(2599, 22, 4, 1, 8, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'کُتِبَ عَلَیۡہِ  اَنَّہٗ  مَنۡ تَوَلَّاہُ  فَاَنَّہٗ یُضِلُّہٗ وَ یَہۡدِیۡہِ  اِلٰی عَذَابِ السَّعِیۡرِ ﴿۴﴾', 'جس کے بارے میں لکھ دیا گیا ہے کہ جو اسے دوست رکھے گا تو وہ اسکو گمراہ کر دے گا اور دوزخ کے عذاب کا رستہ دکھائے گا۔', 'جس کے حق میں لکھ دیا گیا ہے کہ جو کوئی اُسکا رفیق ہو سو وہ اُسکو بہکائے اور لیجائے عذاب میں دوزخ کے [۴]', 'For him (the devil) it is decreed that whosoever follows him, he will mislead him, and will drive him to the torment of the Fire. (Tafsir At-Tabaree)', 'about whom it is destined that if someone takes him for friend, he will misguide him and lead him to the torment of the Fire.'),
(2600, 22, 5, 1, 8, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'یٰۤاَیُّہَا النَّاسُ  اِنۡ  کُنۡتُمۡ فِیۡ رَیۡبٍ مِّنَ الۡبَعۡثِ فَاِنَّا خَلَقۡنٰکُمۡ مِّنۡ تُرَابٍ ثُمَّ مِنۡ نُّطۡفَۃٍ  ثُمَّ مِنۡ عَلَقَۃٍ  ثُمَّ مِنۡ مُّضۡغَۃٍ مُّخَلَّقَۃٍ  وَّ غَیۡرِ مُخَلَّقَۃٍ  لِّنُبَیِّنَ لَکُمۡ ؕ وَ نُقِرُّ  فِی الۡاَرۡحَامِ مَا نَشَآءُ  اِلٰۤی اَجَلٍ مُّسَمًّی ثُمَّ نُخۡرِجُکُمۡ طِفۡلًا ثُمَّ  لِتَبۡلُغُوۡۤا  اَشُدَّکُمۡ ۚ وَ مِنۡکُمۡ  مَّنۡ یُّتَوَفّٰی وَ مِنۡکُمۡ مَّنۡ یُّرَدُّ  اِلٰۤی  اَرۡذَلِ الۡعُمُرِ لِکَیۡلَا یَعۡلَمَ مِنۡۢ بَعۡدِ عِلۡمٍ شَیۡئًا ؕ وَ تَرَی الۡاَرۡضَ ہَامِدَۃً  فَاِذَاۤ  اَنۡزَلۡنَا عَلَیۡہَا الۡمَآءَ   اہۡتَزَّتۡ وَ  رَبَتۡ وَ  اَنۡۢبَتَتۡ مِنۡ  کُلِّ  زَوۡجٍۭ  بَہِیۡجٍ ﴿۵﴾', 'لوگو اگر تمکو مرنے کے بعد جی اٹھنے میں کچھ شک ہو تو ہم نے تمکو پہلی بار بھی تو پیدا کیا تھا یعنی ابتدا میں مٹی سے پھر اس سے نطفہ بنا کر۔ پھر اس سے خون کا لوتھڑا بنا کر۔ پھر اس سے بوٹی بنا کر۔ جسکی بناوٹ کامل بھی ہوتی ہے اور ناقص بھی تاکہ تم پر اپنی خالقیت ظاہر کر دیں اور ہم جسکو چاہتے ہیں ایک میعاد مقرر تک پیٹ میں ٹھہرائے رکھتے ہیں پھر تمکو بچہ بنا کر نکالتے ہیں۔ پھر تم جوانی کو پہنچتے ہو۔ اور بعض قبل از پیری مر جاتے ہیں اور بعض بڑھاپے کی نہایت خراب عمر کی طرف لوٹائے جاتے ہیں کہ بہت کچھ جاننے کے بعد بالکل بے علم ہو جاتے ہیں۔ اور اے دیکھنے والے تو دیکھتا ہے کہ ایک وقت میں زمین خشک پڑی ہوتی ہے پھر جب ہم اس پر مینہ برساتے ہیں تو وہ شاداب ہو جاتی اور ابھرنے لگتی ہے اور طرح طرح کی بارونق چیزیں اگاتی ہے۔', 'اے لوگو اگر تمکو دھوکا ہے جی اٹھنے میں تو ہم نے تمکو بنایا [۵] مٹی سے پھر قطرہ سے [۶] پھر جمے ہوئے خون سے پھر گوشت کی بوٹی نقشہ بنی ہوئی سے اور بدون نقشہ بنی ہوئی سے [۷] اس واسطے کہ تم کو کھول کر سنا دیں [۸] اور ٹھہرا رکھتے ہیں ہم پیٹ میں جو کچھ چاہیں ایک وقت معین تک [۹] پھر تم کو نکالتے ہیں لڑکا پھر جب تک کہ پہنچو اپنی جوانی کے زور کو اورکوئی تم میں سے قبضہ کر لیا جاتا ہے اور کوئی تم میں سے پھر چلایا جاتا ہے نکمی عمر تک تاکہ سمجھنے کے پیچھے کچھ نہ سمجھنے لگے [۱۰] اور تو دیکھتا ہے زمین خراب پڑی ہوئی پھر جہاں ہم نے اتارا اُس پر پانی تازی ہو گئ اور ابھری اور اگائیں ہر قسم قسم رونق کی چیزیں [۱۱]', 'O mankind! If you are in doubt about the Resurrection, then verily! We have created you (i.e. Adam) from dust, then from a Nutfah (mixed drops of male and female sexual discharge i.e. offspring of Adam), then from a clot (a piece of thick coagulated blood) then from a little lump of flesh, some formed and some unformed (miscarriage), that We may make (it) clear to you (i.e. to show you Our Power and Ability to do what We will). And We cause whom We will to remain in the wombs for an appointed term, then We bring you out as infants, then (give you growth) that you may reach your age of full strength. And among you there is he who dies (young), and among you there is he who is brought back to the miserable old age, so that he knows nothing after having known. And you see the earth barren, but when We send down water (rain) on it, it is stirred (to life), it swells and puts forth every lovely kind (of growth).', 'O mankind, if you are in doubt about Resurrection, then (recall that) We created you from dust, then from a drop of semen, then from a clot, then from a piece of flesh, either shaped or unshaped, so that We manifest (Our power) to you.We retain in the wombs whatever We will to a specified term. Then We bring you out as babies, then (We nourish you) so that you reach your maturity. And among you there is one who dies, and among you there is one who is carried to the worst part of the age, so that he knows nothing even after having knowledge.And you see the land dry. Then once We send down water on it, it stirs and swells and puts forth every pleasant pair (of vegetation).'),
(2601, 22, 6, 1, 8, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'ذٰلِکَ بِاَنَّ اللّٰہَ ہُوَ الۡحَقُّ وَ اَنَّہٗ یُحۡیِ الۡمَوۡتٰی  وَ  اَنَّہٗ  عَلٰی کُلِّ  شَیۡءٍ  قَدِیۡرٌ ۙ﴿۶﴾', 'ان قدرتوں سے ظاہر ہے کہ اللہ ہی قادر مطلق ہے جو برحق ہے۔ اور یہ کہ وہ مردوں کو زندہ کر دیتا ہے۔ اور یہ کہ وہ ہر چیز پر قدرت رکھتا ہے۔', 'یہ سب کچھ اس واسطے کہ اللہ وہی ہے محقق اور وہ جِلاتا ہے مُردوں کو اور وہ ہر چیز کر سکتا ہے', 'That is because Allah, He is the Truth, and it is He Who gives life to the dead, and it is He Who is Able to do all things.', 'That is because Allah is the truth, and that He gives life to the dead, and that He is powerful to do everything,'),
(2602, 22, 7, 1, 8, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَّ  اَنَّ السَّاعَۃَ اٰتِیَۃٌ  لَّا رَیۡبَ  فِیۡہَا ۙ وَ اَنَّ اللّٰہَ  یَبۡعَثُ  مَنۡ  فِی  الۡقُبُوۡرِ ﴿۷﴾', 'اور یہ کہ قیامت آنے والی ہے۔ اس میں کچھ شک نہیں اور یہ کہ اللہ سب لوگوں کو جو قبروں میں ہیں جلا اٹھائے گا۔', 'اور یہ کہ قیامت آنی ہے اُس میں دھوکا نہیں اور یہ کہ اللہ اٹھائے گا قبروں میں پڑے ہوؤں کو [۱۲]', 'And surely, the Hour is coming, there is no doubt about it, and certainly, Allah will resurrect those who are in the graves.', 'and that the Hour (of Doom) has to come, in which there is no doubt, and that Allah will raise again all those in the graves.'),
(2603, 22, 8, 1, 8, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ مِنَ النَّاسِ مَنۡ یُّجَادِلُ فِی اللّٰہِ بِغَیۡرِ عِلۡمٍ  وَّ لَا ہُدًی وَّ لَا کِتٰبٍ مُّنِیۡرٍ ۙ﴿۸﴾', 'اور لوگوں میں کوئی ایسا بھی ہے جو اللہ کی شان میں بغیر علم کے اور بغیر ہدایت کے اور بغیر کتاب روشن کے جھگڑتا ہے۔', 'اور بعضا شخص وہ ہے جو جھگڑتا ہے اللہ کی بات میں بغیر جانے اور بغیر دلیل اور بدون روشن کتاب کے [۱۳]', 'And among men is he who disputes about Allah, without knowledge or guidance, or a Book giving light (from Allah),', 'Among men there is one who debates about Allah with no knowledge, no guidance and no enlightening book,'),
(2604, 22, 9, 1, 8, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'ثَانِیَ عِطۡفِہٖ  لِیُضِلَّ عَنۡ  سَبِیۡلِ اللّٰہِ ؕ لَہٗ فِی الدُّنۡیَا خِزۡیٌ وَّ نُذِیۡقُہٗ یَوۡمَ الۡقِیٰمَۃِ  عَذَابَ  الۡحَرِیۡقِ ﴿۹﴾', 'اور تکبر سے گردن موڑ لیتا ہے تاکہ لوگوں کو اللہ کے رستے سے گمراہ کر دے۔ اس کے لئے دنیا میں ذلت ہے۔ اور قیامت کے دن ہم اسے عذاب آتش سوزاں کا مزہ چکھائیں گے۔', 'اپنی کروٹ موڑ کر [۱۴] تاکہ بہکائے اللہ کی راہ سے اُسکے لئے دنیا میں رسوائی ہے اور چکھائیں گے ہم اُسکو قیامت کے دن جلن کی مار [۱۵]', 'Bending his neck in pride (far astray from the Path of Allah), and leading (others) too (far) astray from the Path of Allah. For him there is disgrace in this worldly life, and on the Day of Resurrection We shall make him taste the torment of burning (Fire).', 'turning his side away to lead (people) astray from the way of Allah. For him there is disgrace in this world, and We will have him taste the punishment of Fire on the Day of Judgment'),
(2605, 22, 10, 1, 8, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'ذٰلِکَ بِمَا قَدَّمَتۡ یَدٰکَ وَ اَنَّ اللّٰہَ لَیۡسَ بِظَلَّامٍ   لِّلۡعَبِیۡدِ ﴿٪۱۰﴾', 'اے سرکش یہ اس کفر کی سزا ہے جو تیرے ہاتھوں نے آگے بھیجا ہے اور اللہ اپنے بندوں پر ظلم کرنے والا نہیں۔', 'یہ اُسکی وجہ سے جو آگے بھیج چکے تیرے دو ہاتھ اور  اُس وجہ سےکہ اللہ نہیں ظلم کرتا بندوں پر [۱۶]', 'That is because of what your hands have sent forth, and verily, Allah is not unjust to (His) slaves.', '(and will say to him) “All this is due to what your hands sent ahead, and that Allah is not unjust to His servants.”'),
(2606, 22, 11, 2, 9, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ مِنَ النَّاسِ مَنۡ یَّعۡبُدُ اللّٰہَ عَلٰی حَرۡفٍ ۚ فَاِنۡ  اَصَابَہٗ  خَیۡرُۨ  اطۡمَاَنَّ بِہٖ ۚ وَ اِنۡ اَصَابَتۡہُ فِتۡنَۃُۨ  انۡقَلَبَ عَلٰی وَجۡہِہٖ ۟ۚ  خَسِرَ الدُّنۡیَا وَ الۡاٰخِرَۃَ ؕ ذٰلِکَ  ہُوَ  الۡخُسۡرَانُ  الۡمُبِیۡنُ ﴿۱۱﴾', 'اور لوگوں میں بعض ایسا بھی ہے جو کنارے پر کھڑا ہو کر اللہ کی عبادت کرتا ہے۔ اگر اسکو کوئی دنیاوی فائدہ پہنچے تو اسکے سبب مطمئن ہو جائے اور اگر کوئی آفت آ پڑے تو منہ کے بل لوٹ جائے یعنی پھر کافر ہو جائے اس نے دنیا میں بھی نقصان اٹھایا اور آخرت میں بھی یہی تو صاف نقصان ہے۔', 'اور بعضا شخص وہ ہے کہ بندگی کرتا ہے اللہ کی کنارے پر پھر اگر پہنچی اُسکو بھلائی تو قائم ہو گیا اُس عبادت پر اور اگر پہنچ گئ اُسکو جانچ پھر گیا الٹا اپنے منہ پر گنوائی دنیا اور آخرت یہی ہے ٹوٹا صریح [۱۷]', 'And among mankind is he who worships Allah as it were, upon the very edge (i.e. in doubt); if good befalls him, he is content therewith; but if a trial befalls him, he turns back on his face (i.e. reverts back to disbelief after embracing Islam). He loses both this world and the Hereafter. That is the evident loss.', 'And among men there is one who worships Allah (standing) on the verge: so if some good thing happens to him, he is satisfied with it, and if a trial befalls him, he turns his face back. He loses both this world and the Hereafter. That is the manifest loss.'),
(2607, 22, 12, 2, 9, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'یَدۡعُوۡا مِنۡ دُوۡنِ اللّٰہِ  مَا لَا  یَضُرُّہٗ  وَ مَا لَا یَنۡفَعُہٗ ؕ ذٰلِکَ ہُوَ الضَّلٰلُ الۡبَعِیۡدُ ﴿ۚ۱۲﴾', 'یہ اللہ کے سوا ایسی چیز کو پکارتا ہے جو نہ اسے نقصان پہنچائے اور نہ فائدہ دے سکے یہی تو پرلے درجے کی گمراہی ہے۔', 'پکارتا ہے اللہ کے سوائے ایسی چیز کو کہ نہ اُسکا نقصان کرے اور نہ اُسکا فائدہ کرے یہی ہے دور جا پڑنا گمراہ ہو کر [۱۸]', 'He calls besides Allah unto that which hurts him not, nor profits him. That is a straying far away.', 'He prays to someone, instead of Allah, who can neither harm him nor benefit him. That is the error that takes him too far from the right path.'),
(2608, 22, 13, 2, 9, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'یَدۡعُوۡا لَمَنۡ ضَرُّہٗۤ  اَقۡرَبُ مِنۡ نَّفۡعِہٖ ؕ لَبِئۡسَ  الۡمَوۡلٰی  وَ  لَبِئۡسَ  الۡعَشِیۡرُ ﴿۱۳﴾', 'بلکہ ایسے شخص کو پکارتا ہے جسکا نقصان فائدے سے زیادہ قریب ہے۔ ایسا دوست بھی برا اور ایسا ساتھی بھی برا۔', 'پکارے جاتا ہے اُسکو جس کا ضرر پہلے پہنچے نفع سے [۱۹] بیشک برا دوست ہے اور برا رفیق [۲۰]', 'He calls unto him whose harm is nearer than his profit; certainly, and evil Maula (patron) and certainly an evil friend!', 'He, rather, prays to someone whose harm is more likely than his benefit. Wretched is such a patron and wretched is such a companion.'),
(2609, 22, 14, 2, 9, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'اِنَّ اللّٰہَ یُدۡخِلُ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ جَنّٰتٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ ؕ اِنَّ  اللّٰہَ  یَفۡعَلُ  مَا  یُرِیۡدُ ﴿۱۴﴾', 'جو لوگ ایمان لائے اور عمل نیک کرتے رہے اللہ انکو بہشتوں میں داخل کرے گا جنکے نیچے نہریں بہہ رہی ہیں۔ کچھ شک نہیں کہ اللہ جو چاہتا ہے کرتا ہے۔', 'اللہ داخل کرے گا اُنکو جو ایمان لائے اور کیں بھلائیاں باغوں میں بہتی ہیں نیچے اُنکے نہریں [۲۱] اللہ کرتا ہے جو چاہے [۲۲]', 'Truly, Allah will admit those who believe (in Islamic Monotheism) and do righteous good deeds (according to the Quran and the Sunnah) to Gardens underneath which rivers flow (in Paradise). Verily, Allah does what He wills.', 'Surely, Allah will admit those who believe and do good deeds into gardens beneath which rivers flow. Surely Allah does what He intends.'),
(2610, 22, 15, 2, 9, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'مَنۡ کَانَ یَظُنُّ  اَنۡ لَّنۡ یَّنۡصُرَہُ اللّٰہُ فِی الدُّنۡیَا وَ الۡاٰخِرَۃِ  فَلۡیَمۡدُدۡ  بِسَبَبٍ  اِلَی السَّمَآءِ  ثُمَّ لۡیَقۡطَعۡ فَلۡیَنۡظُرۡ ہَلۡ یُذۡہِبَنَّ  کَیۡدُہٗ   مَا  یَغِیۡظُ ﴿۱۵﴾', 'جو شخص یہ گمان کرتا ہو کہ اللہ اسکو دنیا اور آخرت میں مدد نہیں دے گا تو اسکو چاہیے کہ اوپر کی طرف یعنی اپنے گھر کی چھت میں ایک رسی باندھے پھر اس سے اپنا گلا گھونٹ لے پھر دیکھے کہ آیا یہ تدبیر اسکے غصے کو دور کر دیتی ہے۔', 'جسکو یہ خیال ہو کہ ہرگز نہ مدد کرے گا اُسکی اللہ دنیا میں اور آخرت میں تو تان لے ایک رسی آسمان کو پھر کاٹ ڈالے اب دیکھے کچھ جاتا رہا اُسکی اس تدبیر سے اُس کا غصہ [۲۳]', 'Whoever thinks that Allah will not help him (Muhammad SAW) in this world and in the Hereafter, let him stretch out a rope to the ceiling and let him strangle himself. Then let him see whether his plan will remove that whereat he rages!', 'If someone thinks that Allah will never help him (the prophet) in this world and in the Hereafter, he should stretch a rope to the sky, then cut (Allah’s communication) off (from the prophet) and see whether his effort can really remove what irritates (him).'),
(2611, 22, 16, 2, 9, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ کَذٰلِکَ  اَنۡزَلۡنٰہُ اٰیٰتٍۭ بَیِّنٰتٍ ۙ وَّ اَنَّ اللّٰہَ  یَہۡدِیۡ  مَنۡ  یُّرِیۡدُ ﴿۱۶﴾', 'اور اسی طرح ہم نے اس قرآن کو اتارا جسکی تمام باتیں کھلی ہوئی ہیں اور یہ یاد رکھو کہ اللہ جسکو چاہتا ہے ہدایت دیتا ہے۔', 'اور یوں اتارا ہم نے یہ قرآن کھلی باتیں اور یہ ہے کہ اللہ سمجھا دیتا ہے جسکو چاہے [۲۴]', 'Thus have We sent it (this Quran) down (to Muhammad SAW) as clear signs, evidences and proofs, and surely, Allah guides whom He wills.', 'And this is how We have sent it (the Qur’ān) down as clear signs, and the fact is that Allah leads whom He wills to the right path.'),
(2612, 22, 17, 2, 9, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'اِنَّ الَّذِیۡنَ اٰمَنُوۡا وَ الَّذِیۡنَ ہَادُوۡا وَ الصّٰبِئِیۡنَ وَ النَّصٰرٰی وَ الۡمَجُوۡسَ وَ الَّذِیۡنَ اَشۡرَکُوۡۤا ٭ۖ اِنَّ اللّٰہَ یَفۡصِلُ بَیۡنَہُمۡ  یَوۡمَ الۡقِیٰمَۃِ ؕ اِنَّ اللّٰہَ  عَلٰی  کُلِّ  شَیۡءٍ  شَہِیۡدٌ ﴿۱۷﴾', 'جو لوگ مومن یعنی مسلمان ہیں اور جو یہودی ہیں اور ستارہ پرست اور عیسائی اور مجوسی اور مشرک اللہ ان سب میں قیامت کے دن فیصلہ کر دے گا بیشک اللہ ہر چیز سے باخبر ہے۔', 'جو لوگ مسلمان ہیں اور جو یہود ہیں اور صابئیں اور نصاریٰ اور مجوس [۲۵] اور جو شرک کرتے ہیں مقرر اللہ فیصلہ کرے گا اُن میں قیامت کے دن اللہ کے سامنے ہے ہر چیز [۲۶]', 'Verily, those who believe (in Allah and in His Messenger Muhammad SAW), and those who are Jews, and the Sabians, and the Christians, and the Magians, and those who worship others besides Allah, truly, Allah will judge between them on the Day of Resurrection. Verily! Allah is Witness over all things.', 'As for those who believe and the Jews and the Sabians and the Christians and the Magians and those who ascribe partners to Allah, Allah will judge between them on the Day of Judgment. Surely Allah is witness to every thing.'),
(2613, 22, 18, 2, 9, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'اَلَمۡ تَرَ اَنَّ اللّٰہَ یَسۡجُدُ لَہٗ  مَنۡ فِی السَّمٰوٰتِ وَ مَنۡ فِی الۡاَرۡضِ وَ الشَّمۡسُ وَ الۡقَمَرُ وَ النُّجُوۡمُ وَ الۡجِبَالُ وَ الشَّجَرُ وَ الدَّوَآبُّ وَ کَثِیۡرٌ  مِّنَ  النَّاسِ ؕ وَ کَثِیۡرٌ حَقَّ عَلَیۡہِ الۡعَذَابُ ؕ وَ مَنۡ  یُّہِنِ اللّٰہُ  فَمَا لَہٗ  مِنۡ مُّکۡرِمٍ ؕ اِنَّ اللّٰہَ  یَفۡعَلُ مَا  یَشَآءُ ﴿ؕٛ۱۸﴾', 'کیا تم نے نہیں دیکھا کہ جو مخلوق آسمانوں میں ہے اور جو زمین میں ہے اور سورج اور چاند ستارے اور پہاڑ اور درخت اور چوپائے اور بہت سے انسان اللہ کو سجدہ کرتے ہیں اور بہت سے ایسے ہیں جن پر عذاب ثابت ہو چکا ہے۔ اور جس شخص کو اللہ ذلیل کرے اسکو کوئی عزت دینے والا نہیں بیشک اللہ جو چاہتا ہے کرتا ہے۔', 'تو نے نہیں دیکھا کہ اللہ کو سجدہ کرتا ہے جو  کوئی آسمان میں ہے اور جو کوئی زمین میں ہے اور سورج اور چاند اورتارے اور پہاڑ اور درخت اور جانور اور بہت آدمی [۲۷] اور بہت ہیں کہ اُن پر ٹھہر چکا عذاب [۲۸] اور جسکو اللہ ذلیل کرے اُسے کوئی نہیں عزت دینے والا اللہ کرتا ہے جو چاہے [۲۹]', 'See you not that to Allah prostrates whoever is in the heavens and whoever is on the earth, and the sun, and the moon, and the stars, and the mountains, and the trees, and Ad-Dawab (moving living creatures, beasts, etc.), and many of mankind? But there are many (men) on whom the punishment is justified. And whomsoever Allah disgraces, none can honour him. Verily! Allah does what He wills.', 'Have you not seen that to Allah prostrate all those in the skies and all those on the earth, and the sun, the moon, the stars, the mountains, the trees, the animals and many from mankind? And there are many on whom punishment has become due. And the one whom Allah puts to disgrace, there is none to give him respect. Surely Allah does what He wills.'),
(2614, 22, 19, 2, 9, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'ہٰذٰنِ خَصۡمٰنِ اخۡتَصَمُوۡا فِیۡ رَبِّہِمۡ ۫ فَالَّذِیۡنَ کَفَرُوۡا قُطِّعَتۡ لَہُمۡ ثِیَابٌ مِّنۡ نَّارٍ ؕ یُصَبُّ مِنۡ فَوۡقِ رُءُوۡسِہِمُ الۡحَمِیۡمُ ﴿ۚ۱۹﴾', 'یہ دو فریق ایک دوسرے کے دشمن اپنے پروردگار کے بارے میں جھگڑتے ہیں۔ تو جو کافر ہیں انکے لئے آگ کے کپڑے قطع کئے جائیں گے اور ان کے سروں پر جلتا ہوا پانی ڈالا جائے گا۔', 'یہ دو مدعی ہیں جھگڑے ہیں اپنے رب پر [۳۰] سو جو منکر ہوئے اُنکے واسطے بیونتے ہیں کپڑے آگ کے [۳۱] ڈالتےہیں اُنکے سر پر جلتا پانی', 'These two opponents (believers and disbelievers) dispute with each other about their Lord; then as for those who disbelieve, garments of fire will be cut out for them, boiling water will be poured down over their heads.', 'These are two opponents who have disputed about their Lord. As for those who disbelieve, garments from fire shall be tailored for them, and boiling water shall be poured from over their heads'),
(2615, 22, 20, 2, 9, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'یُصۡہَرُ  بِہٖ  مَا فِیۡ  بُطُوۡنِہِمۡ  وَ الۡجُلُوۡدُ ﴿ؕ۲۰﴾', 'اس سے ان کے پیٹ کے اندر کی چیزیں اور کھالیں گل جائیں گی۔', 'گل کر نکل جاتا ہے اُس سے جو کچھ اُنکے پیٹ میں ہے اور کھال بھی', 'With it will melt or vanish away what is within their bellies, as well as (their) skins.', 'whereby everything in their bellies, as well as the skins, will be melted.'),
(2616, 22, 21, 2, 9, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ لَہُمۡ  مَّقَامِعُ مِنۡ  حَدِیۡدٍ ﴿۲۱﴾', 'اور ان کے مارنے کیلئے لوہے کے ہتھوڑے ہوں گے۔', 'اور اُنکے واسطے ہتوڑے ہیں لوہے کے [۳۲]', 'And for them are hooked rods of iron (to punish them).', 'And for them there are hooked rods of iron.'),
(2617, 22, 22, 2, 9, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'کُلَّمَاۤ  اَرَادُوۡۤا اَنۡ یَّخۡرُجُوۡا مِنۡہَا مِنۡ غَمٍّ  اُعِیۡدُوۡا فِیۡہَا ٭ وَ ذُوۡقُوۡا عَذَابَ الۡحَرِیۡقِ ﴿٪۲۲﴾', 'جب وہ چاہیں گے کہ اس رنج و تکلیف کی وجہ سے دوزخ سے نکل جائیں تو پھر اسی میں لوٹا دیئے جائیں گے اور کہا جائے گا کہ جلنے کے عذاب کا مزہ چکھتے رہو۔', 'جب چاہیں کہ نکل پڑیں دوزخ سے گھٹنے کے مارے پھر ڈال دیے جائیں اُسکے اندر اور چکھتے رہو جلنے کا عذاب [۳۳]', 'Every time they seek to get away therefrom, from anguish, they will be driven back therein, and (it will be) said to them: \"Taste the torment of burning!\"', 'Whenever, in their anguish, they will intend to come out of it (the fire), they will be turned back to it, and (it will be said to them,) “Taste the punishment of burning”.'),
(2618, 22, 23, 3, 10, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'اِنَّ اللّٰہَ یُدۡخِلُ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ جَنّٰتٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ  یُحَلَّوۡنَ فِیۡہَا مِنۡ اَسَاوِرَ مِنۡ ذَہَبٍ وَّ لُؤۡلُؤًا ؕ وَ لِبَاسُہُمۡ  فِیۡہَا حَرِیۡرٌ ﴿۲۳﴾', 'جو لوگ ایمان لائے اور عمل نیک کرتے رہے اللہ انکو بہشتوں میں داخل کرے گا جنکے تلے نہریں بہ رہی ہیں۔ وہاں انکو سونے کے کنگن پہنائے جائیں گے اور موتی۔ اور وہاں ان کا لباس ریشمی ہو گا۔', 'بیشک اللہ داخل کرے گا اُنکو جو یقین لائے اور کیں بھلائیاں باغوں میں بہتی ہیں انکے نیچےنہریں گہنا پہنائیں گے اُنکو  وہاں کنگن سونے کے اور موتی [۳۴] اور اُنکی پوشاک ہے وہاں ریشم کی [۳۵]', 'Truly, Allah will admit those who believe (in the Oneness of Allah Islamic Monotheism) and do righteous good deeds, to Gardens underneath which rivers flow (in Paradise), wherein they will be adorned with bracelets of gold and pearls and their garments therein will be of silk.', 'Surely Allah will admit those who believe and do good deeds to gardens beneath which rivers flow. They will be adorned therein with bracelets of gold and with pearls, and their dress therein will be (of) silk.'),
(2619, 22, 24, 3, 10, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ ہُدُوۡۤا اِلٰی الطَّیِّبِ مِنَ الۡقَوۡلِ ۚۖ وَ ہُدُوۡۤا  اِلَی  صِرَاطِ  الۡحَمِیۡدِ ﴿۲۴﴾', 'اور انکو اچھی بات کیطرف راہنمائی کی گئ اور خوبیوں والے مالک کی راہ بتائی گئ۔', 'اور راہ پائی انہوں نے ستھری بات کی [۳۶] اور پائی اُس تعریفوں والے کی راہ [۳۷]', 'And they are guided (in this world) unto goodly speech (i.e. La ilaha ill-Allah, Alhamdu lillah, recitation of the Quran, etc.) and they are guided to the Path of Him (i.e. Allahs Religion of Islamic Monotheism), Who is Worthy of all praises.', 'Guided they were to the good word (of faith) and guided they were to the path of (Allah,) the Praised One.'),
(2620, 22, 25, 3, 10, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'اِنَّ الَّذِیۡنَ کَفَرُوۡا وَ یَصُدُّوۡنَ عَنۡ سَبِیۡلِ اللّٰہِ وَ الۡمَسۡجِدِ  الۡحَرَامِ  الَّذِیۡ جَعَلۡنٰہُ  لِلنَّاسِ سَوَآءَۨ  الۡعَاکِفُ فِیۡہِ وَ الۡبَادِ ؕ وَ مَنۡ یُّرِدۡ  فِیۡہِ  بِاِلۡحَادٍۭ بِظُلۡمٍ  نُّذِقۡہُ  مِنۡ  عَذَابٍ  اَلِیۡمٍ ﴿٪۲۵﴾', 'جو لوگ کافر ہیں اور لوگوں کو اللہ کے رستے سے اور مسجد حرام سے جسے ہم نے لوگوں کے لئے یکساں عبادت گاہ بنایا ہے روکتے ہیں خواہ وہ وہاں کے رہنے والے ہوں یا باہر سے آنے والے۔ اور جو اس میں شرارت سے کجروی و کفر کرنا چاہے تو اسکو ہم درد دینے والے عذاب کا مزہ چکھائیں گے۔', 'جو لوگ منکر ہوئے اور روکتے ہیں اللہ کی راہ سے اور مسجد حرام سے جو ہم نے بنائی سب لوگوں کے واسطے برابر ہے اس میں رہنے والا اور باہر سے آنے والا [۳۸] اور جو اُس میں چاہے ٹیڑھی راہ شرارت سے اسے ہم چکھائیں گے ایک عذاب دردناک [۳۹]', 'Verily! Those who disbelieve and hinder (men) from the Path of Allah, and from Al-Masjid-al-Haram (at Makkah) which We have made (open) to (all) men, the dweller in it and the visitor from the country are equal there (as regards its sanctity and pilgrimage (Hajj and Umrah)). And whoever inclines to evil actions therein or to do wrong (i.e. practise polytheism and leave Islamic Monotheism), him We shall cause to taste a painful torment.', 'Surely (We will punish) those who disbelieve and prevent (people) from the way of Allah and from Al-Masjid-ul-Harām (the Sacred Mosque), which We have made for all men, where residents and visitors are all equal. And whoever intends therein to commit deviation with injustice, We will make him taste a painful punishment.'),
(2621, 22, 26, 4, 11, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ اِذۡ بَوَّاۡنَا لِاِبۡرٰہِیۡمَ مَکَانَ الۡبَیۡتِ اَنۡ لَّا تُشۡرِکۡ بِیۡ شَیۡئًا وَّ طَہِّرۡ بَیۡتِیَ لِلطَّآئِفِیۡنَ وَ الۡقَآئِمِیۡنَ وَ الرُّکَّعِ السُّجُوۡدِ ﴿۲۶﴾', 'اور ایک وقت تھا جب ہم نے ابراہیم کو خانہ کعبہ کا مقام بتا دیا اور ارشاد فرمایا کہ میرے ساتھ کسی چیز کو شریک نہ کیجیو اور طواف کرنے والوں اور قیام کرنے والوں اور رکوع کرنے والوں اور سجدہ کرنے والوں کے لئے میرے گھر کو صاف رکھا کرنا۔', 'اور جب ٹھیک کر دی ہم نے ابراہیم کو جگہ اُس گھر کی [۴۰] کہ شریک نہ کرنا میرے ساتھ کسی کو [۴۱] اور پاک رکھ میرا گھر طواف کرنے والوں کے واسطے اور کھڑے رہنے والوں کے اور رکوع و سجود والوں کے [۴۲]', 'And (remember) when We showed Ibrahim (Abraham) the site of the (Sacred) House (the Kabah at Makkah) (saying): \"Associate not anything (in worship) with Me, (La ilaha ill-Allah (none has the right to be worshipped but Allah Islamic Monotheism), and sanctify My House for those who circumambulate it, and those who stand up for prayer, and those who bow (submit themselves with humility and obedience to Allah), and make prostration (in prayer, etc.);\"', 'And (remember) when We pointed out for Ibrāhīm the place of the House (of Allah) saying, “Do not associate anything with Me as My partner, and purify My House for those who make Tawāf (circumambulation around it), and those who perform Qiyām (standing up in worship) and those who perform Rukū‘ (bowing down) and Sujūd (prostration),'),
(2622, 22, 27, 4, 11, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ اَذِّنۡ فِی النَّاسِ بِالۡحَجِّ  یَاۡتُوۡکَ  رِجَالًا وَّ عَلٰی کُلِّ ضَامِرٍ یَّاۡتِیۡنَ مِنۡ کُلِّ فَجٍّ عَمِیۡقٍ ﴿ۙ۲۷﴾', 'اور لوگوں میں حج کے لئے اعلان کر دو کہ تمہاری طرف پیدل اور دبلے دبلے اونٹوں پر جو دور دراز رستوں سے چلے آتے ہوں سوار ہو کر چلے آئیں۔', 'اور پکار دے لوگوں میں حج کے واسطے کہ آئیں تیری طرف پیروں چل کر اور سوار ہو کر دبلے دبلے اونٹوں پر چلے آئیں راہوں دور سے [۴۳]', 'And proclaim to mankind the Hajj (pilgrimage). They will come to you on foot and on every lean camel, they will come from every deep and distant (wide) mountain highway (to perform Hajj).', 'and announce among people about (the obligation of) Hajj, so that they should come to you on foot, and on every camel turned lean, traveling through every distant hilly pathway,'),
(2623, 22, 28, 4, 11, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'لِّیَشۡہَدُوۡا مَنَافِعَ  لَہُمۡ  وَ یَذۡکُرُوا  اسۡمَ اللّٰہِ فِیۡۤ  اَیَّامٍ مَّعۡلُوۡمٰتٍ عَلٰی مَا رَزَقَہُمۡ مِّنۡۢ بَہِیۡمَۃِ الۡاَنۡعَامِ ۚ فَکُلُوۡا مِنۡہَا وَ اَطۡعِمُوا  الۡبَآئِسَ الۡفَقِیۡرَ ﴿۫۲۸﴾', 'تاکہ اپنے فائدے کے کاموں کے لئے حاضر ہوں۔ اور قربانی کےایام معلوم میں مویشی چوپایوں کے ذبح کے وقت جو اللہ نے انکو دیئے ہیں ان پر اللہ کا نام لیں۔ اب اس میں سے تم خود بھی کھاؤ اور خستہ حال ضرورت مند کو بھی کھلاؤ۔', 'تاکہ پہنچیں اپنے فائدہ کی جگہوں پر [۴۴] اور پڑھیں اللہ کا نام کئ دن جو معلوم ہیں ذبح پر چوپایوں مواشی کے جو اللہ نے دیے ہیں اُنکو [۴۵] سو کھاؤ اُس میں سے اور کِھلاؤ برے حال کے محتاج کو [۴۶]', 'That they may witness things that are of benefit to them (i.e. reward of Hajj in the Hereafter, and also some worldly gain from trade, etc.), and mention the Name of Allah on appointed days (i.e. 10th, 11th, 12th, and 13th day of Dhul-Hijjah), over the beast of cattle that He has provided for them (for sacrifice) (at the time of their slaughtering by saying: Bismillah, Wallahu-Akbar, Allahumma Minka wa Ilaik). Then eat thereof and feed therewith the poor who have a very hard time.', 'so that they witness benefits for them, and recite Allah’s name in specified days, over the provision He gave them from the cattle. “So, eat thereof and feed the distressed, the poor.”'),
(2624, 22, 29, 4, 11, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'ثُمَّ لۡیَقۡضُوۡا تَفَثَہُمۡ وَ لۡیُوۡفُوۡا نُذُوۡرَہُمۡ وَ لۡیَطَّوَّفُوۡا بِالۡبَیۡتِ الۡعَتِیۡقِ ﴿۲۹﴾', 'پھر چاہیے کہ لوگ اپنا میل کچیل دور کریں اور منتیں پوری کریں اور اس قدیم گھر یعنی بیت اللہ کا طواف کریں۔', 'پھر چاہیئے کہ ختم کر دیں اپنا میل کچیل اور پوری کریں اپنی منتیں اور طواف کریں اس قدیم گھر کا [۴۷]', 'Then let them complete the prescribed duties (Manasik of Hajj) for them, and perform their vows, and circumambulate the Ancient House (the Kabah at Makkah).', 'Then, they must remove their dirt, and fulfill their vows, and make Tawāf of the Ancient House.”'),
(2625, 22, 30, 4, 11, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'ذٰلِکَ ٭ وَ مَنۡ یُّعَظِّمۡ حُرُمٰتِ اللّٰہِ فَہُوَ خَیۡرٌ لَّہٗ عِنۡدَ رَبِّہٖ ؕ وَ اُحِلَّتۡ لَکُمُ الۡاَنۡعَامُ  اِلَّا مَا یُتۡلٰی عَلَیۡکُمۡ فَاجۡتَنِبُوا الرِّجۡسَ مِنَ الۡاَوۡثَانِ وَ اجۡتَنِبُوۡا  قَوۡلَ  الزُّوۡرِ ﴿ۙ۳۰﴾', 'یہ ہمارا حکم ہے اور جو شخص ادب کی چیزوں کی جو ہم نے مقرر کی ہیں تعظیم کرے تو یہ اسکے پروردگار کے نزدیک اسکے حق میں بہتر ہے اور تمہارے لئے مویشی حلال کر دیئے گئے ہیں سوائے انکے جو تمہیں پڑھ کر سنائے جاتے ہیں۔ تو بتوں کی پلیدی سے بچو اور جھوٹی بات سے پرہیز کرو۔', 'یہ سن چکے اور جو کوئی بڑائی رکھے اللہ کی حرمتوں کی سو وہ بہتر ہے آُسکے لئے اپنے رب کے پاس [۴۸] اور حلال ہیں تمکو چوپائے [۴۹] مگر جو تمکو سناتےہیں [۵۰] سو بچتے رہو بتوں کی گندگی سے [۵۱] اور بچتے رہو جھوٹی بات سے [۵۲]', 'That (Manasik prescribed duties of Hajj is the obligation that mankind owes to Allah), and whoever honours the sacred things of Allah, then that is better for him with his Lord. The cattle are lawful to you, except those (that will be) mentioned to you (as exceptions). So shun the abomination (worshipping) of idol, and shun lying speech (false statements)', 'Having said that, whoever observes reverence of the things sanctified by Allah, it is good for him with his Lord. And permitted to you are the cattle, except those mentioned to you through recitation (of the verses). So refrain from the filth of the idols and refrain from a word of falsehood,'),
(2626, 22, 31, 4, 11, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'حُنَفَآءَ لِلّٰہِ غَیۡرَ  مُشۡرِکِیۡنَ بِہٖ ؕ وَ مَنۡ یُّشۡرِکۡ بِاللّٰہِ فَکَاَنَّمَا خَرَّ  مِنَ السَّمَآءِ فَتَخۡطَفُہُ الطَّیۡرُ  اَوۡ تَہۡوِیۡ بِہِ الرِّیۡحُ فِیۡ مَکَانٍ  سَحِیۡقٍ ﴿۳۱﴾', 'صرف ایک اللہ کے ہو کر اور اسکے ساتھ شریک نہ ٹھہرا کر اور جو شخص کسی کو اللہ کے ساتھ شریک مقرر کرے تو وہ گویا ایسا ہے جیسے آسمان سے گر پڑے پھر اسکو پرندے اچک لے جائیں یا ہوا کسی دور کی جگہ اڑا کر پھینک دے۔', 'ایک اللہ کی طرف ہو کر نہ کہ اُسکے ساتھ شریک بنا کر [۵۳] اور جس نے شریک بنایا اللہ کا سو جیسے گر پڑا آسمان سے پھر اُچکتے ہیں اُسکو اڑنے والے مردار خوار یا جا ڈالا اُسکو ہوا نے نے کسی دور مکان میں [۵۴]', 'Hunafa Lillah (i.e. to worship none but Allah), not associating partners (in worship, etc.) unto Him and whoever assigns partners to Allah, it is as if he had fallen from the sky, and the birds had snatched him, or the wind had thrown him to a far off place.', 'standing upright for (the obedience of) Allah, not ascribing any partner to Him. Whoever ascribes a partner to Allah, it is as if he falls down from the sky, and either the birds snatch him, or the wind drives him away to a far off place.'),
(2627, 22, 32, 4, 11, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'ذٰلِکَ ٭ وَ مَنۡ یُّعَظِّمۡ شَعَآئِرَ  اللّٰہِ فَاِنَّہَا مِنۡ  تَقۡوَی  الۡقُلُوۡبِ  ﴿۳۲﴾', 'یہ ہمارا حکم ہے اور جو شخص ادب کی چیزوں کی جو اللہ نے مقرر کی ہیں تعظیم کرے تو یہ کام دلوں کی پرہیزگاری سے ہے۔', 'یہ سن چکے اور جو کوئی ادب رکھے اللہ کے نام لگی چیزوں کا سو وہ دل کی پرہیزگاری کی بات ہے [۵۵]', 'Thus it is (what has been mentioned in the above said Verses (27, 28, 29, 30, 31) is an obligation that mankind owes to Allah). And whosoever honours the Symbols of Allah, then it is truly from the piety of the heart.', 'Having said that, if one observes the sanctity of the symbols of Allah, then such things emanate from the piety of the hearts.'),
(2628, 22, 33, 4, 11, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'لَکُمۡ  فِیۡہَا مَنَافِعُ  اِلٰۤی اَجَلٍ مُّسَمًّی ثُمَّ  مَحِلُّہَاۤ  اِلَی الۡبَیۡتِ  الۡعَتِیۡقِ ﴿٪۳۳﴾', 'ان میں ایک وقت مقرر تک تمہارے لئے فائدے ہیں پھر انکو اس قدیم گھر یعنی بیت اللہ تک پہنچنا اور ذبح ہونا ہے۔', 'تمہارے واسطے چوپایوں میں فائدے ہیں ایک مقرر  وعدہ تک پھر اُنکو پہنچنا اُس قدیم گھر تک [۵۶]', 'In them (cattle offered for sacrifice) are benefits for you for an appointed term, and afterwards they are brought for sacrifice unto the ancient House (the Haram - sacred territory of Makkah city).', 'And for you there are benefits in them (the cattle) up to a specified time. Then their place of sacrifice is by the Ancient House.'),
(2629, 22, 34, 5, 12, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ لِکُلِّ اُمَّۃٍ جَعَلۡنَا مَنۡسَکًا لِّیَذۡکُرُوا اسۡمَ اللّٰہِ عَلٰی مَا رَزَقَہُمۡ مِّنۡۢ بَہِیۡمَۃِ الۡاَنۡعَامِ ؕ فَاِلٰـہُکُمۡ اِلٰہٌ  وَّاحِدٌ فَلَہٗۤ اَسۡلِمُوۡا ؕ وَ  بَشِّرِ  الۡمُخۡبِتِیۡنَ ﴿ۙ۳۴﴾', 'اور ہم نے ہر ایک امت کے لئے قربانی کا طریق مقرر کر دیا ہے تاکہ جو مویشی  چوپائے اللہ نے انکو دیئے ہیں انکے ذبح کرنے کے وقت ان پر اللہ کا نام لیں۔ سو تمہارا معبود ایک ہی ہے تو اسی کے فرمانبردار ہو جاؤ۔ اور عاجزی کرنے والوں کو خوشخبری سنا دو۔', 'اور ہر امت کے واسطے ہم نے مقرر کر دی ہے قربانی کہ یاد کریں اللہ کے نام ذبح پر چوپایوں کے جو اُنکو  (اللہ نے دیے) سو اللہ تمہارا ایک اللہ ہے سو اسی کے حکم میں رہو [۵۷] اور بشارت سنا دے عاجزی کرنے والوں کو [۵۸]', 'And for every nation We have appointed religious ceremonies, that they may mention the Name of Allah over the beast of cattle that He has given them for food. And your Ilah (God) is One Ilah (God Allah), so you must submit to Him Alone (in Islam). And (O Muhammad SAW) give glad tidings to the Mukhbitin (those who obey Allah with humility and are humble from among the true believers of Islamic Monotheism),', 'For every Ummah (religious community) We prescribed the act of sacrifice, so that they recite Allah’s name over the provision He gave them from the cattle. So, your God is One God. Therefore, to Him alone you must submit. And give good news to those who turn to Him with humbleness -'),
(2630, 22, 35, 5, 12, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'الَّذِیۡنَ اِذَا ذُکِرَ  اللّٰہُ وَجِلَتۡ قُلُوۡبُہُمۡ وَ الصّٰبِرِیۡنَ عَلٰی مَاۤ  اَصَابَہُمۡ وَ الۡمُقِیۡمِی الصَّلٰوۃِ ۙ وَ  مِمَّا  رَزَقۡنٰہُمۡ  یُنۡفِقُوۡنَ ﴿۳۵﴾', 'یہ وہ لوگ ہیں کہ جب اللہ کا نام لیا جاتا ہے تو انکے دل ڈر جاتے ہیں اور جب ان پر مصیبت پڑتی ہے تو صبر کرتے ہیں اور نماز آداب سے پڑھتے ہیں اور جو مال ہم نے انکو عطا فرمایا ہے اس میں سے نیک کاموں میں خرچ کرتے ہیں۔', 'وہ کہ جب نام لیجئے اللہ کا ڈر جائیں انکے دل اور سہنے والے اُسکو جو اُن پر پڑے [۵۹] اور قائم رکھنے والے نماز کے اورہمارا دیا ہوا کچھ خرچ کرتے رہتے ہیں [۶۰]', 'Whose hearts are filled with fear when Allah is mentioned; who patiently bear whatever may befall them (of calamities); and who perform AsSalat (Iqamat-as-Salat), and who spend (in Allahs Cause) out of what We have provided them.', 'those whose hearts are filled with awe when Allah is remembered, and who observe patience against whatever befalls them, and who are steadfast in Salāh, and who spend (in the way of Allah) out of what We have given to them.'),
(2631, 22, 36, 5, 12, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ الۡبُدۡنَ جَعَلۡنٰہَا لَکُمۡ مِّنۡ  شَعَآئِرِ اللّٰہِ لَکُمۡ فِیۡہَا خَیۡرٌ ٭ۖ فَاذۡکُرُوا اسۡمَ اللّٰہِ عَلَیۡہَا صَوَآفَّ ۚ فَاِذَا وَجَبَتۡ جُنُوۡبُہَا فَکُلُوۡا مِنۡہَا وَ اَطۡعِمُوا الۡقَانِعَ وَ الۡمُعۡتَرَّ ؕ کَذٰلِکَ سَخَّرۡنٰہَا لَکُمۡ لَعَلَّکُمۡ تَشۡکُرُوۡنَ ﴿۳۶﴾', 'اور قربانی کے اونٹوں کو بھی ہم نے تمہارے لئے اللہ کے شعائر مقرر کیا ہے۔ ان میں تمہارے لئے فائدے ہیں تو قربانی کرنے کے وقت قطار باندھ کر ان پر اللہ کا نام لو۔ پھر جب پہلو کے بل گر پڑیں تو ان میں سے کھاؤ اور قناعت سے بیٹھ رہنے والوں اور سوال کرنے والوں کو بھی کھلاؤ اس طرح ہم نے انکو تمہارے زیر فرمان کر دیا ہے تاکہ تم شکر کرو۔', 'اور کعبہ کے چڑھانے کے اونٹ ٹھہرائے ہیں ہم نے تمہارے واسطے نشانی اللہ کے نام کی تمہارے واسطے اس میں بھلائی ہے سو پڑھو اُن پر نام اللہ کا قطار باندھ کر پھر جب گر پڑے اُنکی کروٹ تو کھاؤ اُس میں سے[۶۱] اور کھلاؤ صبر سے بیٹھے کو اوربیقراری کرتے کو [۶۲] اسی طرح تمہارے بس میں کر دیا ہم نے اُن جانوروں کو تاکہ تم احسان مانو [۶۳]', 'And the Budn (cows, oxen, or camels driven to be offered as sacrifices by the pilgrims at the sanctuary of Makkah.) We have made for you as among the Symbols of Allah, therein you have much good. So mention the Name of Allah over them when they are drawn up in lines (for sacrifice). Then, when they are down on their sides (after slaughter), eat thereof, and feed the beggar who does not ask (men), and the beggar who asks (men). Thus have We made them subject to you that you may be grateful.', 'The big animals of sacrifice (like camels and cows) are made by Us among the symbols of Allah for you, in which there is much good for your benefit. So recite the name of Allah over them as they are lined up (for sacrifice). Then, once their flanks fall down (after slaughter), eat of them and feed the one who is content and the one who wishes to receive. Thus We have made them (the animals) subjugated to you, so that you may be grateful.'),
(2632, 22, 37, 5, 12, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'لَنۡ یَّنَالَ اللّٰہَ  لُحُوۡمُہَا وَ لَا دِمَآؤُہَا وَ لٰکِنۡ یَّنَالُہُ التَّقۡوٰی مِنۡکُمۡ ؕ کَذٰلِکَ سَخَّرَہَا لَکُمۡ لِتُکَبِّرُوا اللّٰہَ عَلٰی مَا ہَدٰىکُمۡ ؕ وَ بَشِّرِ  الۡمُحۡسِنِیۡنَ ﴿۳۷﴾', 'اللہ تک نہ ان کا گوشت پہنچتا ہے اور نہ خون۔ بلکہ اس تک تمہاری پرہیزگاری پہنچتی ہے۔ اسی طرح اللہ نے انکو تمہارے زیرفرمان کر دیا ہے تاکہ اس بات کے بدلے کہ اس نے تمکو ہدایت بخشی ہے اسے برزگی سے یاد کرو۔ اور اے پیغمبر نیکوکاروں کو خوشخبری سنا دو۔', 'اللہ کو نہیں پہنچتا اُن کا گوشت اور نہ اُن کا لہو لیکن اُسکو پہنچتا ہے تمہارے دل کا ادب [۶۴] اسی طرح اُنکو بس میں کر دیا تمہارے کہ اللہ کی بڑائی پڑھو اس بات پر کہ تم کو راہ سجھائی اور بشارت سنا دے نیکی والوں کو [۶۵]', 'It is neither their meat nor their blood that reaches Allah, but it is piety from you that reaches Him. Thus have We made them subject to you that you may magnify Allah for His Guidance to you. And give glad tidings (O Muhammad SAW) to the Muhsinoon (doers of good).', 'It is neither their flesh nor their blood that reaches Allah, but what does reach Him is the taqwā (the sense of obedience) on your part. Thus He has made them (the animals) subjugated to you, so that you proclaim Allah’s glory for the guidance He gave you. And give good news to those who are good in their deeds.'),
(2633, 22, 38, 5, 12, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'اِنَّ اللّٰہَ یُدٰفِعُ عَنِ الَّذِیۡنَ اٰمَنُوۡا ؕ اِنَّ اللّٰہَ لَا یُحِبُّ کُلَّ  خَوَّانٍ  کَفُوۡرٍ ﴿٪۳۸﴾', 'اللہ تو مومنوں سے انکے دشمنوں کو ہٹاتا رہتا ہے۔ بیشک اللہ کسی خیانت کرنے والے ناشکرے کو دوست نہیں رکھتا۔', 'اللہ دشمنوں کو ہٹا دے گا ایمان والوں سے [۶۶] اللہ کو خوش نہیں آتا کوئی دغاباز نا شکر [۶۷]', 'Truly, Allah defends those who believe. Verily! Allah likes not any treacherous ingrate to Allah (those who disobey Allah but obey Shaitan (Satan)).', 'Surely, Allah defends those who believe. Allah does not love any treacherous, ungrateful.'),
(2634, 22, 39, 6, 13, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'اُذِنَ لِلَّذِیۡنَ یُقٰتَلُوۡنَ بِاَنَّہُمۡ ظُلِمُوۡا ؕ وَ اِنَّ  اللّٰہَ  عَلٰی  نَصۡرِہِمۡ  لَقَدِیۡرُۨ  ﴿ۙ۳۹﴾', 'جن مسلمانوں سے خوامخواہ لڑائی کی جاتی ہے انکو اجازت ہے کہ وہ بھی لڑیں کیونکہ ان پر ظلم ہو رہا ہے۔ اور اللہ انکی مدد کرے گا وہ یقیناً انکی مدد پر قادر ہے۔', 'حکم ہوا اُن لوگوں کو جن سے کافر لڑتے ہیں اس واسطے کہ اُن پر ظلم ہوا [۶۸] اور اللہ اُنکی مدد کرنے پر قادر ہے [۶۹]', 'Permission to fight is given to those (i.e. believers against disbelievers), who are fighting them, (and) because they (believers) have been wronged, and surely, Allah is Able to give them (believers) victory', 'Permission (to fight) is given to those against whom fighting is launched, because they have been wronged, and Allah is powerful to give them victory.'),
(2635, 22, 40, 6, 13, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'الَّذِیۡنَ اُخۡرِجُوۡا مِنۡ دِیَارِہِمۡ  بِغَیۡرِ  حَقٍّ اِلَّاۤ  اَنۡ یَّقُوۡلُوۡا رَبُّنَا اللّٰہُ ؕ وَ لَوۡ لَا دَفۡعُ اللّٰہِ النَّاسَ بَعۡضَہُمۡ بِبَعۡضٍ لَّہُدِّمَتۡ صَوَامِعُ وَ بِیَعٌ وَّ صَلَوٰتٌ وَّ مَسٰجِدُ یُذۡکَرُ فِیۡہَا اسۡمُ اللّٰہِ کَثِیۡرًا ؕ وَ لَیَنۡصُرَنَّ اللّٰہُ مَنۡ یَّنۡصُرُہٗ ؕ اِنَّ اللّٰہَ لَقَوِیٌّ عَزِیۡزٌ ﴿۴۰﴾', 'یہ وہ لوگ ہیں کہ اپنے گھروں سے ناحق نکال دیئے گئے انہوں نے کچھ قصور نہیں کیا ہاں یہ کہتے ہیں کہ ہمارا پروردگار اللہ ہے اور اگر اللہ لوگوں کو ایک دوسرے سے نہ ہٹاتا رہتا تو خانقاہیں اور گرجے اور یہودیوں کے عبادت خانے اور مسلمانوں کی مسجدیں جن میں اللہ کا کثرت سے ذکر کیا جاتا ہے گرائی جا چکی ہوتیں۔ اور جو شخص اللہ کی مدد کرتا ہے اللہ اسکی ضرور مدد کرتا ہے۔ بیشک اللہ توانا ہے غالب ہے۔', 'وہ لوگ جنکو  نکالا  اُنکے گھروں سے اور دعویٰ کچھ نہیں سوائے اسکے کہ وہ کہتے ہیں ہمارا رب اللہ ہے [۷۰] اور اگر نہ ہٹایا کرتا اللہ لوگوں کو ایک کو دوسرے سے تو ڈھائے جاتے تکئے اور مدرسے اور عبادت خانے اور مسجدیں جن میں نام پڑھا جاتا ہے اللہ کا بہت اور اللہ مقرر مدد کرے گا اُسکی جو مدد کرے گا اُسکی بیشک اللہ زبردست ہے زور  والا [۷۱]', 'Those who have been expelled from their homes unjustly only because they said: \"Our Lord is Allah.\" - For had it not been that Allah checks one set of people by means of another, monasteries, churches, synagogues, and mosques, wherein the Name of Allah is mentioned much would surely have been pulled down. Verily, Allah will help those who help His (Cause). Truly, Allah is All-Strong, All-Mighty.', '(They are) the ones who were expelled from their homes without any just reason, except that they say “Our Lord is Allah.” Had Allah not been repelling some people by means of some others, the monasteries, the churches, the synagogues and the mosques where Allah’s name is abundantly recited would have been demolished. Allah will definitely help those who help Him (by defending the religion prescribed by Him.) Surely Allah is Powerful, Mighty.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(2636, 22, 41, 6, 13, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'اَلَّذِیۡنَ  اِنۡ مَّکَّنّٰہُمۡ  فِی الۡاَرۡضِ اَقَامُوا الصَّلٰوۃَ وَ اٰتَوُا الزَّکٰوۃَ وَ اَمَرُوۡا بِالۡمَعۡرُوۡفِ وَ  نَہَوۡا عَنِ الۡمُنۡکَرِ ؕ وَ لِلّٰہِ  عَاقِبَۃُ  الۡاُمُوۡرِ ﴿۴۱﴾', 'یہ وہ لوگ ہیں کہ اگر ہم انکو ملک میں حکومت دے دیں تو نماز قائم کریں اور زکوٰۃ ادا کریں اور نیک کام کرنے کا حکم دیں اور برے کاموں سے منع کریں اور سب کاموں کا انجام اللہ ہی کے اختیار میں ہے۔', 'وہ لوگ کہ اگر ہم اُنکو قدرت دیں ملک میں تو وہ قائم رکھیں نماز اور دیں زکوٰۃ اور حکم کر دیں بھلے کام کا اور منع کریں برائی سے [۷۲] اور اللہ کے اختیار میں ہے آخر  ہر کام کا [۷۳]', 'Those (Muslim rulers) who, if We give them power in the land, (they) order for Iqamat-as-Salat. (i.e. to perform the five compulsory congregational Salat (prayers) (the males in mosques)), to pay the Zakat and they enjoin Al-Maroof (i.e. Islamic Monotheism and all that Islam orders one to do), and forbid Al-Munkar (i.e. disbelief, polytheism and all that Islam has forbidden) (i.e. they make the Quran as the law of their country in all the spheres of life). And with Allah rests the end of (all) matters (of creatures).', '(The ones who help Allah are) those who, when We give them power in the land, establish Salāh, pay Zakāh, bid what is Fair and forbid what is Unfair. And with Allah lies the fate of all matters.'),
(2637, 22, 42, 6, 13, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ اِنۡ یُّکَذِّبُوۡکَ فَقَدۡ کَذَّبَتۡ قَبۡلَہُمۡ قَوۡمُ  نُوۡحٍ  وَّ عَادٌ  وَّ  ثَمُوۡدُ ﴿ۙ۴۲﴾', 'اور اگر یہ لوگ تمکو جھٹلاتے ہیں تو ان سے پہلے نوح کی قوم اور عاد و ثمود کی قومیں بھی اپنے پیغمبروں کو جھٹلا چکی ہیں۔', 'اور اگر تجھ کو جھٹلائیں تو اُن سے پہلے جھٹلا چکی ہے نوح کی قوم اور عاد اور ثمود', 'And if they belie you (O Muhammad SAW), so were belied the Prophets before them, (by) the people of Nooh (Noah), Ad and Thamood,', 'And if they reject you, so did reject the people of NūH (Noah) and ‘Ād and Thamūd,'),
(2638, 22, 43, 6, 13, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ  قَوۡمُ   اِبۡرٰہِیۡمَ  وَ  قَوۡمُ  لُوۡطٍ ﴿ۙ۴۳﴾', 'اور قوم ابراہیم اور قوم لوط بھی۔', 'اور ابراہیم کی قوم اور لوط کی قوم', 'And the people of Ibrahim (Abraham) and the people of Lout (Lot),', 'and the people of Ibrāhīm and the people of LūT (Lot),'),
(2639, 22, 44, 6, 13, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَّ اَصۡحٰبُ مَدۡیَنَ ۚ وَ کُذِّبَ مُوۡسٰی فَاَمۡلَیۡتُ لِلۡکٰفِرِیۡنَ ثُمَّ  اَخَذۡتُہُمۡ ۚ فَکَیۡفَ کَانَ نَکِیۡرِ ﴿۴۴﴾', 'اور مدین کے رہنے والے بھی اور موسٰی بھی تو جھٹلائے جا چکے ہیں۔ لیکن میں کافروں کو مہلت دیتا رہا پھر میں نے انکو پکڑ لیا۔ تو دیکھ لو کہ میرا عذاب کیسا سخت تھا۔', 'اور مدین کے لوگ [۷۴] اور موسٰی کو جھٹلایا [۷۵] پھر میں نے ڈھیل دی منکروں کر پھر پکڑ لیا اُنکو تو کیسا ہوا میرا انکار [۷۶]', 'And the dwellers of Madyan (Midian); and belied was Moosa (Moses), but I granted respite to the disbelievers for a while, then I seized them, and how (terrible) was My Punishment (against their wrong-doing).', 'and the people of Madyan as well. Mūsā was (also) rejected. So, I gave some respite to the disbelievers, then seized them. So how was My censure?'),
(2640, 22, 45, 6, 13, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'فَکَاَیِّنۡ مِّنۡ قَرۡیَۃٍ  اَہۡلَکۡنٰہَا وَ ہِیَ ظَالِمَۃٌ  فَہِیَ خَاوِیَۃٌ عَلٰی عُرُوۡشِہَا وَ بِئۡرٍ  مُّعَطَّلَۃٍ   وَّ  قَصۡرٍ  مَّشِیۡدٍ ﴿۴۵﴾', 'چنانچہ بہت سی بستیاں ہیں کہ ہم نے انکو تباہ کر ڈالا کہ وہ نافرمان تھیں۔ سو وہ اپنی چھتوں کے بل گری پڑی ہیں۔ اور بہت سے کنوئیں بیکار اور بہت سے مضبوط محل ویران پڑے ہیں۔', 'سو کتنی بستیاں ہم نے غارت کر ڈالیں اور وہ گنہگار تھیں اب وہ گری پڑی ہیں اپنی چھتوں پر [۷۷] اور کتنے کونئیں نکمے پڑے اور کتنے محل گچ کاری کے [۷۸]', 'And many a township have We destroyed while it was given to wrong-doing, so that it lies in ruins (up to this day), and (many) a deserted well and lofty castles!', 'How many towns have We destroyed, as they were wrongdoers! So, they are fallen down on their roofs, and (how many a) deserted well and (how many a) well-built castle!'),
(2641, 22, 46, 6, 13, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'اَفَلَمۡ یَسِیۡرُوۡا فِی الۡاَرۡضِ فَتَکُوۡنَ لَہُمۡ قُلُوۡبٌ یَّعۡقِلُوۡنَ بِہَاۤ  اَوۡ اٰذَانٌ یَّسۡمَعُوۡنَ بِہَا ۚ فَاِنَّہَا لَا تَعۡمَی الۡاَبۡصَارُ  وَ لٰکِنۡ  تَعۡمَی الۡقُلُوۡبُ الَّتِیۡ فِی الصُّدُوۡرِ ﴿۴۶﴾', 'سو کیا ان لوگوں نے ملک میں سیر نہیں کی تاکہ ان کے دل ایسے ہوتے کہ ان سے سمجھ سکتے اور کان ایسے ہوتے کہ ان سے سن سکتے۔ بات یہ ہے کہ آنکھیں اندھی نہیں ہوتیں بلکہ دل جو سینوں میں ہیں وہ اندھے ہو جاتے ہیں۔', 'کیا سیر نہیں کی ملک کی جو اُنکے دل ہوتے جن سے سمجھتے یا کان ہوتے جن سے سنتے [۷۹] سو کچھ آنکھیں اندھی نہیں ہوتیں پر اندھے ہو جاتے ہیں دل جو سینوں میں ہیں [۸۰]', 'Have they not travelled through the land, and have they hearts wherewith to understand and ears wherewith to hear? Verily, it is not the eyes that grow blind, but it is the hearts which are in the breasts that grow blind.', 'Have they not, then, traveled on earth so that they should have had hearts to understand with, or ears to listen with? The fact is that it is not the eyes that turn blind, but what turns blind is the hearts contained in the chests.'),
(2642, 22, 47, 6, 13, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ  یَسۡتَعۡجِلُوۡنَکَ بِالۡعَذَابِ وَ لَنۡ یُّخۡلِفَ اللّٰہُ وَعۡدَہٗ ؕ وَ اِنَّ یَوۡمًا عِنۡدَ رَبِّکَ  کَاَلۡفِ  سَنَۃٍ   مِّمَّا  تَعُدُّوۡنَ ﴿۴۷﴾', 'اور یہ لوگ تم سے عذاب کے لئے جلدی کر رہے ہیں اور اللہ اپنے وعدے کیخلاف ہرگز نہیں کرے گا۔ اور بیشک تمہارے پروردگار کے نزدیک ایک روز تمہارے حساب کی رو سے ہزار برس کے برابر ہے۔', 'اور تجھ سے جلدی مانگتے ہیں عذاب اور اللہ ہرگز نہ ٹالے گا اپنا وعدہ [۸۱] اور ایک دن تیرے رب کے یہاں ہزار برس کے برابر ہوتا ہے جو تم گنتے ہو [۸۲]', 'And they ask you to hasten on the torment! And Allah fails not His Promise. And verily, a day with your Lord is as a thousand years of what you reckon.', 'They ask you to bring the punishment sooner, while Allah will never go back on His promise. In fact, one day with your Lord is like one thousand years according to your calculation.'),
(2643, 22, 48, 6, 13, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ کَاَیِّنۡ مِّنۡ قَرۡیَۃٍ  اَمۡلَیۡتُ لَہَا وَ ہِیَ ظَالِمَۃٌ  ثُمَّ اَخَذۡتُہَا ۚ وَ اِلَیَّ الۡمَصِیۡرُ ﴿٪۴۸﴾', 'اور بہت سی بستیاں ہیں کہ میں انکو مہلت دیتا رہا جبکہ وہ نافرمان تھیں۔ پھر میں نے انکو پکڑ لیا۔ اور میری ہی طرف لوٹ کر آنا ہے۔', 'اور کتنی بستیاں ہیں کہ میں نے اُنکو ڈھیل دی اور وہ گنہگار تھیں پھر میں نے اُنکو پکڑا اور میری طرف پھر کر آنا ہے [۸۳]', 'And many a township did I give respite while it was given to wrong-doing. Then (in the end) I seized it (with punishment). And to Me is the (final) return (of all).', 'And how many towns were there to whom I allowed respite, while they were wrongdoers, then I seized them. And to Me is the final return.'),
(2644, 22, 49, 7, 14, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'قُلۡ یٰۤاَیُّہَا النَّاسُ اِنَّمَاۤ  اَنَا لَکُمۡ نَذِیۡرٌ  مُّبِیۡنٌ ﴿ۚ۴۹﴾', 'اے پیغمبر کہدو کہ لوگو! میں تو تمکو کھلم کھلا خبردار کرنے والا ہوں۔', 'تو کہہ اے لوگو میں تو ڈر سنا دینے والا ہوں تمکو کھول کر [۸۴]', 'Say (O Muhammad SAW): \"O mankind! I am (sent) to you only as a plain warner.\"', 'Say, “O people, I am no more than a plain warner for you.'),
(2645, 22, 50, 7, 14, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'فَالَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ لَہُمۡ مَّغۡفِرَۃٌ  وَّ  رِزۡقٌ  کَرِیۡمٌ ﴿۵۰﴾', 'تو جو لوگ ایمان لائے اور کام نیک کئے ان کے لئے بخشش اور عزت کی روزی ہے۔', 'سو جو لوگ یقین لائے اور کیں بھلائیاں اُنکے گناہ بخش دیتے ہیں اور اُنکو روزی ہے عزت کی [۸۵]', 'So those who believe (in the Oneness of Allah Islamic Monotheism) and do righteous good deeds, for them is forgiveness and Rizqoon Kareem (generous provision, i.e. Paradise).', 'So those who come to believe and do good deeds, for them there is forgiveness and dignified provision.'),
(2646, 22, 51, 7, 14, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ الَّذِیۡنَ سَعَوۡا فِیۡۤ  اٰیٰتِنَا مُعٰجِزِیۡنَ اُولٰٓئِکَ  اَصۡحٰبُ  الۡجَحِیۡمِ ﴿۵۱﴾', 'اور جن لوگوں نے ہماری آیتوں میں اپنے خیال میں ہمیں عاجز کرنے کے لئے دوڑ دھوپ کی وہ اہل دوزخ ہیں۔', 'اور جو دوڑے ہماری آیتوں کے ہرانے کو وہی ہیں دوزخ کے رہنے والے', 'But those who strive against Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), to frustrate and obstruct them, they will be dwellers of the Hell-fire.', 'As for those who strive against Our signs, trying to defeat (the prophet or the believers), they are the people of the Fire.”'),
(2647, 22, 52, 7, 14, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ مَاۤ  اَرۡسَلۡنَا مِنۡ قَبۡلِکَ مِنۡ رَّسُوۡلٍ وَّ لَا نَبِیٍّ  اِلَّاۤ  اِذَا تَمَنّٰۤی اَلۡقَی الشَّیۡطٰنُ فِیۡۤ اُمۡنِیَّتِہٖ ۚ فَیَنۡسَخُ اللّٰہُ مَا یُلۡقِی الشَّیۡطٰنُ ثُمَّ  یُحۡکِمُ  اللّٰہُ  اٰیٰتِہٖ ؕ وَ  اللّٰہُ عَلِیۡمٌ  حَکِیۡمٌ  ﴿ۙ۵۲﴾', 'اور ہم نے تم سے پہلے کوئی رسول اور نبی نہیں بھیجا مگر اس کا یہ حال تھا کہ جب وہ کوئی آرزو کرتا تھا تو شیطان اسکی آرزو میں وسوسہ ڈال دیتا تھا تو جو وسوسہ شیطان ڈالتا ہے اللہ اسکو دور کر دیتا ہے۔ پھر اللہ اپنی آیتوں کو مضبوط کر دیتا ہے۔ اور اللہ علم والا ہے حکمت والا ہے۔', 'اور جو رسول بھیجا ہم نے تجھ سے پہلے یا نبی سو جب لگا خیال باندھنے شیطان نے ملا دیا اُسکے خیال میں پھر اللہ مٹا دیتا ہے شیطان کا ملایا ہوا پھر پکی کر دیتا ہے اپنی باتیں اور اللہ سب خبر رکھتا ہے حکمتوں والا [۸۶]', 'Never did We send a Messenger or a Prophet before you, but; when he did recite the revelation or narrated or spoke, Shaitan (Satan) threw (some falsehood) in it. But Allah abolishes that which Shaitan (Satan) throws in. Then Allah establishes His Revelations. And Allah is All-Knower, All-Wise:', 'We did not send any messenger before you nor a prophet, but (he faced a situation that) when he recited (the revelation), the Satan cast (doubts in the hearts of his opponents) about what he recited. So, Allah nullifies what the Satan casts, then Allah makes His verses firm, and Allah is All-Knowing, All-Wise'),
(2648, 22, 53, 7, 14, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'لِّیَجۡعَلَ مَا یُلۡقِی الشَّیۡطٰنُ فِتۡنَۃً لِّلَّذِیۡنَ فِیۡ قُلُوۡبِہِمۡ مَّرَضٌ وَّ الۡقَاسِیَۃِ  قُلُوۡبُہُمۡ ؕ وَ اِنَّ الظّٰلِمِیۡنَ لَفِیۡ شِقَاقٍۭ بَعِیۡدٍ ﴿ۙ۵۳﴾', 'غرض اس سے یہ ہے کہ جو وسوسہ شیطان ڈالتا ہے اسکو ان لوگوں کے لئے جنکے دلوں میں بیماری ہے اور جنکے دل سخت ہیں ذریعہ آزمائش ٹھہرائے۔ بیشک ظالم لوگ مخالفت میں دور جا پڑے۔', 'اس واسطے کہ جو کچھ شیطان نے ملایا اس سے جانچے اُنکو کہ جنکے دل میں روگ ہیں اور جنکے دل سخت ہیں اور گنہگار تو ہیں مخالفت میں دور جا پڑے', 'That He (Allah) may make what is thrown in by Shaitan (Satan) a trial for those in whose hearts is a disease (of hypocrisy and disbelief) and whose hearts are hardened. And certainly, the Zalimoon (polytheists and wrong-doers, etc.) are in an opposition far-off (from the truth against Allahs Messenger and the believers).', '(All this is allowed to be done) so that He may make what Satan casts a trial for those in whose hearts there is a disease, and whose hearts are hard;-and surely the wrongdoers are in the utmost antagonism-'),
(2649, 22, 54, 7, 14, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَّ لِیَعۡلَمَ الَّذِیۡنَ اُوۡتُوا الۡعِلۡمَ اَنَّہُ الۡحَقُّ مِنۡ رَّبِّکَ فَیُؤۡمِنُوۡا بِہٖ فَتُخۡبِتَ لَہٗ قُلُوۡبُہُمۡ ؕ وَ اِنَّ اللّٰہَ لَہَادِ الَّذِیۡنَ اٰمَنُوۡۤا  اِلٰی  صِرَاطٍ  مُّسۡتَقِیۡمٍ ﴿۵۴﴾', 'اور یہ بھی غرض ہے کہ جن لوگوں کو علم عطا ہوا ہے وہ جان لیں کہ وہ یعنی وحی تمہارے پروردگار کی طرف سے حق ہے تو وہ اس پر ایمان لائیں اور انکے دل اللہ کے آگے عاجزی کریں اور جو لوگ ایمان لائے ہیں اللہ انکو سیدھے رستے کی طرف ہدایت کرتا ہے۔', 'اور اس واسطے کہ معلوم کر لیں وہ لوگ جنکو سمجھ ملی ہے کہ یہ تحقیق ہے تیرے رب کی طرف سے پھر اس پر یقین لائیں اور نرم ہو جائیں اُسکے آگے اُنکے دل اور اللہ سمجھانے والا ہے یقین لانے والوں کو راہ سیدھی [۸۷]', 'And that those who have been given knowledge may know that it (this Quran) is the truth from your Lord, and that they may believe therein, and their hearts may submit to it with humility. And verily, Allah is the Guide of those who believe, to the Straight Path.', 'and so that those who have been given knowledge may know that it (i.e. the revelation recited by the prophet) is the truth from your Lord, and they may believe in it and their hearts may become humble towards it. Allah is the Guide of the believers to the straight path.'),
(2650, 22, 55, 7, 14, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ لَا یَزَالُ الَّذِیۡنَ  کَفَرُوۡا فِیۡ  مِرۡیَۃٍ  مِّنۡہُ حَتّٰی تَاۡتِیَہُمُ السَّاعَۃُ بَغۡتَۃً اَوۡ یَاۡتِیَہُمۡ  عَذَابُ  یَوۡمٍ  عَقِیۡمٍ ﴿۵۵﴾', 'اور کافر لوگ ہمیشہ اسکی طرف سے شک میں رہیں گے یہاں تک کہ قیامت ان پر ناگہاں آ جائے یا ایک نامبارک دن کا عذاب ان پر آ واقع ہو۔', 'اور منکروں کوہمیشہ رہے گا اُس میں دھوکا جب تک کہ آ پہنچے اُن پر قیامت بیخبری میں یا آ پہنچے اُن پر آفت ایسے دن کی جس میں راہ نہیں خلاصی کی [۸۸]', 'And those who disbelieve will not cease to be in doubt about it (this Quran) until the Hour comes suddenly upon them, or there comes to them the torment of the Day after which there will be no night (i.e. the Day of Resurrection).', 'Those who disbelieve will remain in doubt about it (the Qur’ān) forever, until the Hour (of Judgment) comes upon them suddenly, or there comes to them the punishment of a barren day.'),
(2651, 22, 56, 7, 14, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'اَلۡمُلۡکُ یَوۡمَئِذٍ لِّلّٰہِ ؕ یَحۡکُمُ بَیۡنَہُمۡ ؕ فَالَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ فِیۡ جَنّٰتِ النَّعِیۡمِ ﴿۵۶﴾', 'اس روز بادشاہی اللہ ہی کی ہو گی۔ اور وہ ان میں فیصلہ کر دے گا۔ تو جو لوگ ایمان لائے اور عمل نیک کرتے رہے وہ نعمت کے باغوں میں ہوں گے۔', 'راج اُس دن اللہ کا ہے اُن میں فیصلہ کرے گا [۸۹] سو جو یقین لائے اور کیں بھلائیاں نعمت کے باغوں میں میں ہیں', 'The sovereignty on that Day will be that of Allah (the one Who has no partners). He will judge between them. So those who believed (in the Oneness of Allah Islamic Monotheism) and did righteous good deeds will be in Gardens of delight (Paradise).', 'The kingdom, on that day, is for Allah. He will judge between them. So, those who believed and did good deeds shall be in gardens of bliss.'),
(2652, 22, 57, 7, 14, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ الَّذِیۡنَ کَفَرُوۡا وَ کَذَّبُوۡا بِاٰیٰتِنَا فَاُولٰٓئِکَ  لَہُمۡ  عَذَابٌ  مُّہِیۡنٌ ﴿٪۵۷﴾', 'اور جو کافر ہوئے اور ہماری آیتوں کو جھٹلاتے رہے ان کے لئے ذلیل کرنے والا عذاب ہوگا۔', 'اور جو منکر ہوئے اور جھٹلائیں ہماری باتیں سو  انکے لئے ہے ذلت کا عذاب', 'And those who disbelieved and belied Our Verses (of this Quran), for them will be a humiliating torment (in Hell).', 'As for those who disbelieved and rejected Our signs, they are the ones for whom there is a humiliating punishment.'),
(2653, 22, 58, 8, 15, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ الَّذِیۡنَ ہَاجَرُوۡا فِیۡ سَبِیۡلِ اللّٰہِ ثُمَّ قُتِلُوۡۤا اَوۡ مَاتُوۡا لَیَرۡزُقَنَّہُمُ اللّٰہُ رِزۡقًا حَسَنًا ؕ وَ اِنَّ اللّٰہَ  لَہُوَ  خَیۡرُ  الرّٰزِقِیۡنَ ﴿۵۸﴾', 'اور جن لوگوں نے اللہ کی راہ میں ہجرت کی پھر مارے گئے یا مر گئے۔ ان کو اللہ اچھی روزی دے گا۔ اور بیشک اللہ بہترین رزق دینے والا ہے۔', 'اور جو لوگ گھر چھوڑ آئے اللہ کی راہ میں پھر مارے گئے یا مر گئے البتہ اُنکو دے گا اللہ روزی خاصی اور االلہ ہے سب سے بہتر روزی دینے والا', 'Those who emigrated in the Cause of Allah and after that were killed or died, surely, Allah will provide a good provision for them. And verily, it is Allah Who indeed is the Best of those who make provision.', 'Those who left their homeland in the way of Allah, then were slain or died, Allah will certainly give them a good provision, and surely, Allah is the best provider.'),
(2654, 22, 59, 8, 15, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'لَیُدۡخِلَنَّہُمۡ مُّدۡخَلًا  یَّرۡضَوۡنَہٗ ؕ وَ اِنَّ اللّٰہَ  لَعَلِیۡمٌ  حَلِیۡمٌ ﴿۵۹﴾', 'وہ انکو ایسے مقام میں داخل کرے گا جسے وہ پسند کریں گے اور اللہ تو جاننے والا ہے بردبار ہے۔', 'البتہ پہنچائے گا اُنکو ایک جگہ جسکو پسند کریں گے اور اللہ سب کچھ جانتا ہے تحمل والا [۹۰]', 'Truly, He will make them enter an entrance with which they shall be well-pleased, and verily, Allah indeed is All-Knowing, Most Forbearing.', 'He will definitely admit them to an entrance they will be pleased with, and Allah is surely All-Knowing, Forbearing.'),
(2655, 22, 60, 8, 15, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'ذٰلِکَ ۚ وَ مَنۡ عَاقَبَ بِمِثۡلِ مَا عُوۡقِبَ بِہٖ ثُمَّ بُغِیَ عَلَیۡہِ لَیَنۡصُرَنَّہُ اللّٰہُ ؕ اِنَّ اللّٰہَ  لَعَفُوٌّ  غَفُوۡرٌ ﴿۶۰﴾', 'یہ بات اللہ کے ہاں ٹھہر چکی ہے اور جو شخص کسی کو اتنی ہی ایذا دے جتنی ایذا اس کو دی گئ پھر اس شخص پر زیادتی کی جائے تو اللہ اسکی مدد کرے گا۔ بیشک اللہ معاف کرنے والا ہے بخشنے والا ہے۔', 'یہ سن چکے اور جس نے بدلہ لیا جیسا کہ اُسکو دکھ دیا تھا پھر اُس پر کوئی زیادتی کرے تو البتہ اُسکی مدد کرے گا اللہ [۹۱] بیشک اللہ درگذر کرنے والا بخشنے والا ہے [۹۲]', 'That is so. And whoever has retaliated with the like of that which he was made to suffer, and then has again been wronged, Allah will surely help him. Verily! Allah indeed is Oft-Pardoning, Oft-Forgiving.', 'Having said this, whoever afflicts (someone) with a punishment equal to what he was afflicted with (by the latter), and still he (the former) is (again) subjected to aggression (by the latter), Allah will certainly help him. Indeed, Allah is Most-Pardoning, Most-Forgiving.'),
(2656, 22, 61, 8, 15, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'ذٰلِکَ بِاَنَّ اللّٰہَ یُوۡلِجُ الَّیۡلَ  فِی النَّہَارِ  وَ یُوۡلِجُ النَّہَارَ فِی الَّیۡلِ وَ اَنَّ اللّٰہَ سَمِیۡعٌۢ  بَصِیۡرٌ ﴿۶۱﴾', 'یہ اس لئے کہ اللہ رات کو دن میں داخل کرتا ہے اور دن کو رات میں داخل کرتا ہے اور اللہ تو سننے والا ہے دیکھنے والا ہے۔', 'یہ اس واسطے کہ اللہ لے لیتا ہے رات کو دن میں اور دن کو رات میں [۹۳] اور اللہ سنتا دیکھتا ہے [۹۴]', 'That is because Allah merges the night into the day, and He merges the day into the night. And verily, Allah is All-Hearer, All-Seer.', 'That is because Allah makes night enter into the day and makes day enter into the night and that Allah is All-Hearing, All-Seeing.'),
(2657, 22, 62, 8, 15, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'ذٰلِکَ بِاَنَّ اللّٰہَ ہُوَ الۡحَقُّ وَ اَنَّ مَا یَدۡعُوۡنَ مِنۡ دُوۡنِہٖ ہُوَ الۡبَاطِلُ وَ اَنَّ اللّٰہَ  ہُوَ  الۡعَلِیُّ الۡکَبِیۡرُ ﴿۶۲﴾', 'یہ اس لئے کہ اللہ ہی برحق ہے اور جس چیز کو کافر اللہ کے سوا پکارتے ہیں وہ باطل ہے اور اس لئے کہ اللہ اونچی شان والا ہے بڑا ہے۔', 'یہ اس واسطے کہ اللہ وہی ہے صحیح اور جسکو پکارتے ہیں اُسکے سوائے وہی ہے غلط اور اللہ وہی ہے سب سے اوپر بڑا [۹۵]', 'That is because Allah He is the Truth (the only True God of all that exists, Who has no partners or rivals with Him), and what they (the polytheists) invoke besides Him, it is Batil (falsehood) And verily, Allah He is the Most High, the Most Great.', 'That is because Allah is the truth and that whatever they invoke beside Him is false and that Allah is the High, the Great.'),
(2658, 22, 63, 8, 15, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'اَلَمۡ  تَرَ  اَنَّ اللّٰہَ  اَنۡزَلَ  مِنَ  السَّمَآءِ  مَآءً ۫ فَتُصۡبِحُ  الۡاَرۡضُ  مُخۡضَرَّۃً ؕ اِنَّ  اللّٰہَ لَطِیۡفٌ خَبِیۡرٌ ﴿ۚ۶۳﴾', 'کیا تم نہیں دیکھتے کہ اللہ آسمان سے مینہ برساتا ہے تو زمین سرسبز ہو جاتی ہے  بیشک اللہ مہربان ہے خبردار ہے۔', 'تو نے نہیں دیکھا کہ اللہ نے اتارا آسمان سے پانی پھر زمین ہو جاتی ہے سر سبز [۹۶] بیشک اللہ جانتا ہے چھپی تدبیریں خبردار ہے [۹۷]', 'See you not that Allah sends down water (rain) from the sky, and then the earth becomes green? Verily, Allah is the Most Kind and Courteous, Well-Acquainted with all things.', 'Did you not see that Allah has sent down water from the sky, whereby the land becomes green? Surely, Allah is All-Kind, All-Aware.'),
(2659, 22, 64, 8, 15, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'لَہٗ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ؕ وَ اِنَّ  اللّٰہَ  لَہُوَ  الۡغَنِیُّ  الۡحَمِیۡدُ ﴿٪۶۴﴾', 'جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے اسی کا ہے۔ اور بیشک اللہ بے نیاز ہے قابل ستائش ہے۔', 'اُسی کا ہے جو کچھ ہے آسمان اور زمین میں اور اللہ وہی ہے بے پروا تعریفوں والا [۹۸]', 'To Him belongs all that is in the heavens and all that is on the earth. And verily, Allah He is Rich (Free of all wants), Worthy of all praise.', 'To Him belongs all that is in the heavens and all that is in the earth, and surely Allah is the All-Independent, Ever-Praised.'),
(2660, 22, 65, 9, 16, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'اَلَمۡ تَرَ اَنَّ اللّٰہَ سَخَّرَ لَکُمۡ مَّا فِی الۡاَرۡضِ وَ الۡفُلۡکَ  تَجۡرِیۡ فِی الۡبَحۡرِ بِاَمۡرِہٖ ؕ وَ  یُمۡسِکُ  السَّمَآءَ   اَنۡ تَقَعَ عَلَی الۡاَرۡضِ اِلَّا بِاِذۡنِہٖ ؕ اِنَّ اللّٰہَ بِالنَّاسِ  لَرَءُوۡفٌ  رَّحِیۡمٌ ﴿۶۵﴾', 'کیا تم نہیں دیکھتے کہ جتنی چیزیں زمین میں ہیں سب اللہ نے تمہارے زیرفرمان کر رکھی ہیں۔ اور کشتیاں بھی جو اسی کے حکم سے سمندر میں چلتی ہیں۔ اور وہ آسمان کو تھامے رہتا ہے کہ زمین پر نہ گر پڑے مگر اس کے حکم سے۔ بیشک اللہ لوگوں پر نہایت شفقت کرنے والا مہربان ہے۔', 'تو نے نہ دیکھا کہ اللہ نے بس میں کردیا تمہارے جو کچھ ہے زمین میں اور کشتی کو جو چلتی ہے دریا میں اُسکے حکم سے اور تھام رکھتا ہے آسمان کو اس سے کہ گر پڑے زمین پر مگر اُسکے حکم سے بیشک اللہ لوگوں پر نرمی کرنے والا مہربان ہے [۹۹]', 'See you not that Allah has subjected to you (mankind) all that is on the earth, and the ships that sail through the sea by His Command? He withholds the heaven from falling on the earth except by His Leave. Verily, Allah is, for mankind, full of Kindness, Most Merciful.', 'Did you not see that Allah has subjugated to you everything on the earth, and the ships that sail at sea with His command? And He holds the sky so as it cannot fall on the earth except with His permission. Surely Allah is Very-Kind to the people, Very-Merciful.'),
(2661, 22, 66, 9, 16, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ ہُوَ الَّذِیۡۤ  اَحۡیَاکُمۡ ۫ ثُمَّ یُمِیۡتُکُمۡ  ثُمَّ  یُحۡیِیۡکُمۡ ؕ اِنَّ  الۡاِنۡسَانَ لَکَفُوۡرٌ ﴿۶۶﴾', 'اور وہی تو ہے جس نے تمکو حیات بخشی۔ پھر تمکو مارتا ہے۔ پھر تمہیں زندہ بھی کرے گا۔ اور انسان تو بڑا ناشکرا ہے۔', 'اور اُسی نے تمکو جلایا پھر مارتا ہے پھر زندہ کرے گا [۱۰۰] بیشک انسان ناشکر ہے [۱۰۱]', 'It is He, Who gave you life, and then will cause you to die, and will again give you life (on the Day of Resurrection). Verily! Man is indeed an ingrate.', 'He is the One who gave life to you, then He brings death to you, then He will give you life (again). Surely, man is very ungrateful.'),
(2662, 22, 67, 9, 16, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'لِکُلِّ اُمَّۃٍ جَعَلۡنَا مَنۡسَکًا ہُمۡ نَاسِکُوۡہُ فَلَا یُنَازِعُنَّکَ  فِی الۡاَمۡرِ وَ ادۡعُ  اِلٰی رَبِّکَ ؕ اِنَّکَ  لَعَلٰی ہُدًی مُّسۡتَقِیۡمٍ ﴿۶۷﴾', 'ہم نے ہر ایک امت کے لئے بندگی کی ایک راہ مقرر کر دی ہے کہ اسی طرح وہ بندگی کرتے ہیں۔ تو یہ لوگ تم سے اس معاملے میں جھگڑا نہ کریں اور تم لوگوں کو اپنے پروردگار کی طرف بلاتے رہو۔ بیشک تم سیدھے رستے پر ہو۔', 'ہر امت کے لئے ہم نے مقرر کر دی ایک راہ بندگی کی کہ وہ اُسی طرح کرتے ہیں بندگی سو چاہئے تجھ سے جھگڑا نہ کریں اس کام میں اور تو بلائے جا اپنے رب کی طرف بیشک تو ہے سیدھی راہ پر سوجھ والا', 'For every nation We have ordained religious ceremonies (e.g. slaughtering of the beast of cattle during the three days of stay at Meena (Makkah) during the Hajj (pilgrimage)) which they must follow; so let them (pagans) not dispute with you on the matter (i.e. to eat of the cattle which you slaughter, and not to eat of cattle which Allah kills by its natural death), but invite them to your Lord. Verily! You (O Muhammad SAW) indeed are on the (true) straight guidance. (i.e. the true religion of Islamic Monotheism).', 'For every Ummah (religious community) We have appointed a way of worship they are to observe. Therefore, they should never quarrel with you in the matter. And do call (them) to your Lord. Surely, you are on straight Guidance.'),
(2663, 22, 68, 9, 16, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ اِنۡ جٰدَلُوۡکَ فَقُلِ اللّٰہُ  اَعۡلَمُ بِمَا تَعۡمَلُوۡنَ ﴿۶۸﴾', 'اور اگر یہ تم سے جھگڑا کریں تو کہدو کہ جو عمل تم کرتے ہو اللہ ان سے خوب واقف ہے۔', 'اور اگر تجھ سے جھگڑنے لگیں تو تو کہہ اللہ بہتر جانتا ہے جو تم کرتے ہو', 'And if they argue with you (as regards the slaughtering of the sacrifices), say; \"Allah knows best of what you do.', 'And if they dispute with you, say (to them), “Allah is the best aware of what you do.”'),
(2664, 22, 69, 9, 16, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'اَللّٰہُ  یَحۡکُمُ  بَیۡنَکُمۡ  یَوۡمَ الۡقِیٰمَۃِ  فِیۡمَا کُنۡتُمۡ  فِیۡہِ  تَخۡتَلِفُوۡنَ ﴿۶۹﴾', 'جن باتوں میں تم اختلاف کرتے ہو اللہ تم میں قیامت کے روز ان کا فیصلہ کر دے گا۔', 'اللہ فیصلہ کرے گا تم میں قیامت کے دن جس چیز میں تمہاری راہ جدا جدا تھی [۱۰۲]', '\"Allah will judge between you on the Day of Resurrection about that wherein you used to differ.\"', 'Allah will judge between you, on the Day of Judgment, about what you used to dispute.'),
(2665, 22, 70, 9, 16, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'اَلَمۡ  تَعۡلَمۡ  اَنَّ اللّٰہَ یَعۡلَمُ  مَا فِی السَّمَآءِ وَ الۡاَرۡضِ ؕ اِنَّ  ذٰلِکَ فِیۡ   کِتٰبٍ ؕ اِنَّ  ذٰلِکَ عَلَی   اللّٰہِ  یَسِیۡرٌ ﴿۷۰﴾', 'کیا تم نہیں جانتے کہ جو کچھ آسمان اور زمین میں ہے اللہ اسکو جانتا ہے۔ یہ سب کچھ کتاب میں لکھا ہوا ہے بیشک یہ سب اللہ کو آسان ہے۔', 'کیا تجھ کو معلوم نہیں کہ اللہ جانتا ہے جو کچھ ہے آسمان اور زمیں میں یہ سب لکھا ہوا ہے کتاب میں یہ اللہ پر آسان ہے [۱۰۳]', 'Know you not that Allah knows all that is in heaven and on earth? Verily, it is (all) in the Book (Al-Lauh Al-Mahfooz). Verily! That is easy for Allah.', 'Do you not know that Allah knows all that is in the sky and the earth? Surely, that is contained in a Book. Indeed it is so easy for Allah.'),
(2666, 22, 71, 9, 16, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ یَعۡبُدُوۡنَ مِنۡ دُوۡنِ اللّٰہِ مَا لَمۡ  یُنَزِّلۡ بِہٖ سُلۡطٰنًا وَّ مَا لَیۡسَ لَہُمۡ بِہٖ عِلۡمٌ ؕ وَ مَا  لِلظّٰلِمِیۡنَ  مِنۡ  نَّصِیۡرٍ ﴿۷۱﴾', 'اور یہ لوگ اللہ کے سوا ایسی چیزوں کی عبادت کرتے ہیں جنکی اس نے کوئی سند نازل نہیں فرمائی اور نہ انکے پاس اسکی کوئی دلیل ہے اور ظالموں کا کوئی بھی مددگار نہیں ہو گا۔', 'اور پوجتے ہیں اللہ کے سوائے اس چیز کو جسکی سند نہیں اتاری اُس نے اور جسکی خبر نہیں اُنکو [۱۰۴] اور بے انصافوں کا کوئی نہیں مددگار [۱۰۵]', 'And they worship besides Allah others for which He has sent down no authority, and of which they have no knowledge and for the Zalimoon (wrong-doers, polytheists and disbelievers in the Oneness of Allah) there is no helper.', 'They worship, besides Allah, the objects for which He did never send down an authority (or proof) and about which they have no knowledge. And for the wrongdoers there is no helper.'),
(2667, 22, 72, 9, 16, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ اِذَا تُتۡلٰی عَلَیۡہِمۡ اٰیٰتُنَا بَیِّنٰتٍ تَعۡرِفُ فِیۡ  وُجُوۡہِ  الَّذِیۡنَ کَفَرُوا الۡمُنۡکَرَ ؕ یَکَادُوۡنَ یَسۡطُوۡنَ بِالَّذِیۡنَ یَتۡلُوۡنَ عَلَیۡہِمۡ اٰیٰتِنَا ؕ قُلۡ اَفَاُنَبِّئُکُمۡ بِشَرٍّ مِّنۡ ذٰلِکُمۡ ؕ اَلنَّارُ ؕ وَعَدَہَا اللّٰہُ  الَّذِیۡنَ   کَفَرُوۡا ؕ وَ  بِئۡسَ الۡمَصِیۡرُ ﴿٪۷۲﴾', 'اور جب انکو ہماری صاف صاف آیتیں پڑھ کر سنائی جاتی ہیں تو انکی شکل بگڑ جاتی ہے اور تم انکے چہروں میں صاف طور پر ناگواری دیکھتے ہو۔ ایسا لگتا ہے کہ جو لوگ انکو ہماری آیتیں پڑھ کو سناتے ہیں ان پر حملہ کر دیں گے۔ کہدو کہ میں تمکو اس سے بھی بری چیز بتاؤں؟ وہ دوزخ کی آگ ہے۔ جس کا اللہ نے کافروں سے وعدہ کیا ہے اور وہ برا ٹھکانہ ہے۔', 'اور جب سنائے اُنکو ہماری آیتیں صاف تو پہچانے تو منکروں کے منہ کی بری شکل نزدیک ہوتے ہیں کہ حملہ کر پڑیں اُن پر جو پڑھتے ہیں اُنکے پاس ہماری آیتیں [۱۰۶] تو کہہ میں تمکو بتلاؤں ایک چیز اس سے بدتر وہ آگ ہے اس کا وعدہ کر دیا ہے اللہ نے منکروں کو اور وہ بہت بری ہے پھر جانے کی جگہ [۱۰۷]', 'And when Our Clear Verses are recited to them, you will notice a denial on the faces of the disbelievers! They are nearly ready to attack with violence those who recite Our Verses to them. Say: \"Shall I tell you of something worse than that? The Fire (of Hell) which Allah has promised to those who disbelieve, and worst indeed is that destination!\"', 'When Our verses are recited to them in all their clarity, you (can) recognize disgust on the faces of the disbelievers. They seem to attack those who recite to them Our verses. Say, “Shall I, then, tell you about something more disgusting than that? The Fire! Allah has promised it to those who disbelieve. And it is an evil end.”'),
(2668, 22, 73, 10, 17, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'یٰۤاَیُّہَا النَّاسُ ضُرِبَ مَثَلٌ  فَاسۡتَمِعُوۡا لَہٗ  ؕ اِنَّ الَّذِیۡنَ تَدۡعُوۡنَ مِنۡ دُوۡنِ اللّٰہِ لَنۡ یَّخۡلُقُوۡا ذُبَابًا وَّ لَوِ اجۡتَمَعُوۡا  لَہٗ ؕ وَ اِنۡ یَّسۡلُبۡہُمُ الذُّبَابُ شَیۡئًا لَّا یَسۡتَنۡقِذُوۡہُ  مِنۡہُ ؕ ضَعُفَ الطَّالِبُ وَ الۡمَطۡلُوۡبُ ﴿۷۳﴾', 'لوگو ایک مثال بیان کی جاتی ہے اسے غور سے سنو۔ کہ جن لوگوں کو تم اللہ کے سوا پکارتے ہو وہ ایک مکھی بھی نہیں بنا سکتے۔ اگرچہ اس کے لئے سب اکٹھے ہو جائیں اور اگر ان سے مکھی کوئی چیز چھین لے جائے تو اسے اس سے چھڑا نہیں سکتے۔ طالب اور مطلوب یعنی عابد اور معبود دونوں گئے گذرے ہیں۔', 'اے لوگو ایک مثل کہی ہے سو اس پر کان رکھو [۱۰۸] جنکو تم پوجتے ہو اللہ کے سوائے ہرگز نہ بنا سکیں گے ایک مکھی اگرچہ سارے جمع ہو جائیں اور اگر کچھ چھین لے اُن سے مکھی چھڑا نہ سکیں وہ اس سے بودا ہے چاہنے والا اور جنکو چاہتا ہے [۱۰۹]', 'O mankind! A similitude has been coined, so listen to it (carefully): Verily! Those on whom you call besides Allah, cannot create (even) a fly, even though they combine together for the purpose. And if the fly snatched away a thing from them, they would have no power to release it from the fly. So weak are (both) the seeker and the sought.', 'O people, here is a parable set forth to you, so listen to it carefully: All those whom you invoke besides Allah can never create (even) a fly, even though they all join hands together for that. And if a fly snatches something away from them, they cannot release it from its possession. (Equally) feeble are the invoker and the invoked.'),
(2669, 22, 74, 10, 17, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'مَا قَدَرُوا اللّٰہَ حَقَّ قَدۡرِہٖ ؕ اِنَّ اللّٰہَ لَقَوِیٌّ عَزِیۡزٌ ﴿۷۴﴾', 'ان لوگوں نے اللہ کی قدر جیسی کرنی چاہیے تھی نہیں کی کچھ شک نہیں کہ اللہ زبردست ہے غالب ہے۔', 'اللہ کی قدر نہیں سمجھے جیسی اُسکی قدر ہے بیشک اللہ زور آور ہے زبردست [۱۱۰]', 'They have not estimated Allah His Rightful Estimate; Verily, Allah is All-Strong, All-Mighty.', 'They did not recognize Allah in His true esteem. Indeed Allah is Powerful, Mighty.'),
(2670, 22, 75, 10, 17, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'اَللّٰہُ یَصۡطَفِیۡ مِنَ الۡمَلٰٓئِکَۃِ  رُسُلًا وَّ مِنَ النَّاسِ ؕ اِنَّ اللّٰہَ سَمِیۡعٌۢ  بَصِیۡرٌ ﴿ۚ۷۵﴾', 'اللہ فرشتوں میں سے پیغام پہنچانے والے منتخب کر لیتا ہے اور انسانوں میں سے بھی۔ بیشک اللہ سننے والا ہے دیکھنے والا ہے۔', 'اللہ چھانٹ لیتا ہے فرشتوں میں پیغام پہنچانے والے اور آدمیوں میں [۱۱۱] اللہ سنتا  دیکھتا ہے [۱۱۲]', 'Allah chooses Messengers from angels and from men. Verily, Allah is All-Hearer, All-Seer.', 'Allah chooses messengers from angels and from men. Surely, Allah is All-Hearing, All-Seeing.'),
(2671, 22, 76, 10, 17, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'یَعۡلَمُ مَا بَیۡنَ اَیۡدِیۡہِمۡ وَ مَا خَلۡفَہُمۡ ؕ وَ اِلَی اللّٰہِ  تُرۡجَعُ الۡاُمُوۡرُ ﴿۷۶﴾', 'جو انکے آگے ہے اور جو انکے پیچھے ہے وہ اس سے واقف ہے اور سب کاموں کا رجوع اللہ ہی کی طرف ہے۔', 'جانتا ہے جو کچھ اُنکے آگے ہے اور جو کچھ اُنکے پیچھے اور اللہ تک پہنچ ہے ہر کام کی [۱۱۳]', 'He knows what is before them, and what is behind them. And to Allah return all matters (for decision).', 'He knows what is in front of them and what is behind them, and to Allah all matters are to be returned.'),
(2672, 22, 77, 10, 17, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوا ارۡکَعُوۡا  وَ اسۡجُدُوۡا وَ اعۡبُدُوۡا رَبَّکُمۡ وَ افۡعَلُوا الۡخَیۡرَ  لَعَلَّکُمۡ  تُفۡلِحُوۡنَ ﴿ۚٛ۷۷﴾', 'مومنو! رکوع کرتے اور سجدہ کرتے اور اپنے پروردگار کی عبادت کرتے رہو اور نیک کام کرو تاکہ فلاح پاؤ۔', 'اے ایمان والو رکوع کرو اور سجدہ کرو اور بندگی کرو اپنے رب کی اور بھلائی کرو تاکہ تمہارا بھلا ہو  [۱۱۴]', 'O you who believe! Bow down, and prostrate yourselves, and worship your Lord and do good that you may be successful.', 'O you who believe, bow down in Rukū‘ and bow down in Sajdah, and worship your Lord and do good deeds, so that you achieve success.'),
(2673, 22, 78, 10, 17, 17, 'اِقۡتَرَبَ لِلنَّاسِ', 'الحج', 'وَ جَاہِدُوۡا فِی اللّٰہِ حَقَّ جِہَادِہٖ ؕ ہُوَ اجۡتَبٰىکُمۡ وَ مَا جَعَلَ عَلَیۡکُمۡ فِی الدِّیۡنِ مِنۡ حَرَجٍ ؕ مِلَّۃَ  اَبِیۡکُمۡ اِبۡرٰہِیۡمَ ؕ ہُوَ سَمّٰىکُمُ الۡمُسۡلِمِیۡنَ ۬ۙ مِنۡ قَبۡلُ وَ فِیۡ ہٰذَا  لِیَکُوۡنَ الرَّسُوۡلُ شَہِیۡدًا عَلَیۡکُمۡ وَ تَکُوۡنُوۡا شُہَدَآءَ عَلَی النَّاسِ ۚۖ فَاَقِیۡمُوا الصَّلٰوۃَ  وَ اٰتُوا الزَّکٰوۃَ  وَ اعۡتَصِمُوۡا بِاللّٰہِ ؕ ہُوَ مَوۡلٰىکُمۡ ۚ فَنِعۡمَ الۡمَوۡلٰی وَ نِعۡمَ النَّصِیۡرُ ﴿٪۷۸﴾', 'اور اللہ کی راہ میں جہاد کرو۔ جیسا جہاد کرنے کا حق ہے۔ اس نے تمکو منتخب کیا ہے اور تم پر دین کی کسی بات میں تنگی نہیں کی۔ اور تمہارے لئے تمہارے باپ ابراہیم کا دین پسند کیا اسی اللہ نے پہلے یعنی پہلی کتابوں میں تمہارا نام مسلم رکھا تھا اور اس کتاب میں بھی وہی نام رکھا ہے تو جہاد کرو تاکہ پیغمبر تمہارے بارے میں گواہ ہوں۔ اور تم لوگوں کے مقابلے میں گواہ ہو سو مسلمانو نماز قائم کرواور زکوٰۃ دو اور اللہ کے دین کی رسی کو پکڑے رہو وہی تمہارا دوست ہے سو  وہ کیا خوب دوست ہے اور کیا خوب مددگار ہے۔', 'اور محنت کرو اللہ کے واسطے جیسی کہ چاہئے اُسکے واسطے محنت [۱۱۵] اس نے تم کو پسند کیا [۱۱۶] اور نہیں رکھی تم پر دین میں کچھ مشکل [۱۱۷] دین تمہارے باپ ابراہیم کا [۱۱۸] اُسی نے نام رکھا تمہارا مسلمان پہلے سے اور اس قرآن میں [۱۱۹] تاکہ رسول ہو بتانے والا تم پر اور تم ہو بتانے والے لوگوں پر [۱۲۰] سو قائم رکھو نماز اور دیتے رہو زکوٰۃ اور مضبوط پکڑو اللہ کو وہ تمہارا مالک ہے سو خوب مالک ہے اور خوب مددگار [۱۲۱]', 'And strive hard in Allahs Cause as you ought to strive (with sincerity and with all your efforts that His Name should be superior). He has chosen you (to convey His Message of Islamic Monotheism to mankind by inviting them to His religion, Islam), and has not laid upon you in religion any hardship, it is the religion of your father Ibrahim (Abraham) (Islamic Monotheism). It is He (Allah) Who has named you Muslims both before and in this (the Quran), that the Messenger (Muhammad SAW) may be a witness over you and you be witnesses over mankind! So perform AsSalat (Iqamat-as-Salat), give Zakat and hold fast to Allah (i.e. have confidence in Allah, and depend upon Him in all your affairs) He is your Maula (Patron, Lord, etc.), what an Excellent Maula (Patron, Lord, etc.) and what an Excellent Helper!', 'Struggle for (seeking the pleasure of) Allah, a struggle that is owed to Him. He has chosen you and did not impose any hardship on you in the religion, the faith of your father Ibrāhīm. He (Allah) named you as Muslims earlier and also in this (Qur’ān), so that the Messenger becomes a witness to you, and you become witnesses to (other) people. So establish Salāh, pay Zakāh and hold fast to Allah. He is your patron. So, how excellent He is as a patron, and how excellent as a supporter!'),
(2674, 23, 1, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'قَدۡ  اَفۡلَحَ  الۡمُؤۡمِنُوۡنَ ۙ﴿۱﴾', 'بیشک ایمان والے کامیاب ہو گئے۔', 'کام نکال لے گئے ایمان والے', 'Successful indeed are the believers.', 'Success is really attained by the believers'),
(2675, 23, 2, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'الَّذِیۡنَ ہُمۡ  فِیۡ صَلَاتِہِمۡ خٰشِعُوۡنَ ۙ﴿۲﴾', 'جو نماز میں عجزونیاز کرتے ہیں۔', 'جو اپنی نماز میں جھکنے والے ہیں [۱]', 'Those who offer their Salat (prayers) with all solemnity and full submissiveness.', 'who concentrate their attention in humbleness when offering Salāh (prayers)'),
(2676, 23, 3, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ الَّذِیۡنَ ہُمۡ عَنِ اللَّغۡوِ  مُعۡرِضُوۡنَ ﴿ۙ۳﴾', 'اور جو بیہودہ باتوں سے منہ موڑے رہتے ہیں۔', 'اور جو نکمی بات پر دھیان نہیں کرتے [۲]', 'And those who turn away from Al-Laghw (dirty, false, evil vain talk, falsehood, and all that Allah has forbidden).', 'and who keep themselves away from vain things,'),
(2677, 23, 4, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ الَّذِیۡنَ ہُمۡ  لِلزَّکٰوۃِ  فٰعِلُوۡنَ ۙ﴿۴﴾', 'اور جو زکوٰۃ ادا کرتے ہیں۔', 'اور جو زکوٰۃ دیا کرتے ہیں [۳]', 'And those who pay the Zakat .', 'and who are performers of Zakāh ,'),
(2678, 23, 5, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ الَّذِیۡنَ ہُمۡ  لِفُرُوۡجِہِمۡ حٰفِظُوۡنَ ۙ﴿۵﴾', 'اور جو اپنی شرمگاہوں کی حفاظت کرتے ہیں۔', 'اور جو اپنی شہوت کی جگہ کو تھامتے ہیں', 'And those who guard their chastity (i.e. private parts, from illegal sexual acts)', 'and who guard their private parts'),
(2679, 23, 6, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اِلَّا عَلٰۤی اَزۡوَاجِہِمۡ اَوۡ مَا مَلَکَتۡ اَیۡمَانُہُمۡ فَاِنَّہُمۡ غَیۡرُ   مَلُوۡمِیۡنَ ۚ﴿۶﴾', 'مگر اپنی بیویوں سے یا کنیزوں سے جو انکی مِلک ہوتی ہیں کہ ان سے تعلق قائم کرنے میں انہیں ملامت نہیں۔', 'مگر اپنی عورتوں پر یا اپنے ہاتھ کے مال باندیوں پر سو اُن پر نہیں کچھ الزام', 'Except from their wives or (the captives and slaves) that their right hands possess, for then, they are free from blame;', 'except from their wives or from those (bondwomen who are) owned by their hands, as they are not to be blamed.'),
(2680, 23, 7, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'فَمَنِ ابۡتَغٰی وَرَآءَ ذٰلِکَ فَاُولٰٓئِکَ ہُمُ الۡعٰدُوۡنَ ۚ﴿۷﴾', 'اور جو ان کے سوا اوروں کے طالب ہوں وہ اللہ کی مقرر کی ہوئی حد سے نکل جانے والے ہیں۔', 'پھر جو کوئی ڈھونڈے اسکےسوا سو وہی ہیں حد سے بڑھنے والے [۴]', 'But whoever seeks beyond that, then those are the transgressors;', 'However, those who seek (sexual pleasure) beyond that are the transgressors'),
(2681, 23, 8, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ الَّذِیۡنَ ہُمۡ  لِاَمٰنٰتِہِمۡ وَ عَہۡدِہِمۡ رٰعُوۡنَ ۙ﴿۸﴾', 'اور جو امانتوں اور اقراروں کو ملحوظ رکھتے ہیں۔', 'اور جو اپنی امانتوں سے اور اپنے قرار سے خبردار ہیں [۵]', 'Those who are faithfully true to their Amanat (all the duties which Allah has ordained, honesty, moral responsibility and trusts etc.) and to their covenants;', '- and (success is attained) by those who honestly look after their trusts and covenant,'),
(2682, 23, 9, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ الَّذِیۡنَ ہُمۡ عَلٰی صَلَوٰتِہِمۡ یُحَافِظُوۡنَ  ۘ﴿۹﴾', 'اور جو نمازوں کی پابندی کرتے ہیں۔', 'اور جو اپنی نمازوں کی خبر رکھتے ہیں [۶]', 'And those who strictly guard their (five compulsory congregational) Salawat (prayers) (at their fixed stated hours).', 'and who consistently observe their prayers.'),
(2683, 23, 10, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اُولٰٓئِکَ ہُمُ  الۡوٰرِثُوۡنَ ﴿ۙ۱۰﴾', 'یہی لوگ میراث حاصل کرنے والے ہیں۔', 'وہی ہیں میراث لینے والے', 'These are indeed the inheritors.', 'Those are the inheritors'),
(2684, 23, 11, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'الَّذِیۡنَ یَرِثُوۡنَ الۡفِرۡدَوۡسَ ؕ ہُمۡ  فِیۡہَا خٰلِدُوۡنَ ﴿۱۱﴾', 'یعنی جنت الفردوس کے وارث بنیں گے وہ اس میں ہمیشہ رہیں گے۔', 'جو میراث پائیں گے باغ ٹھنڈی چھاؤں کے [۷] وہ اسی میں ہمیشہ رہیں گے', 'Who shall inherit the Firdaus (Paradise). They shall dwell therein forever.', 'who will inherit Firdaus (the Paradise). They will be there forever.'),
(2685, 23, 12, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ لَقَدۡ خَلَقۡنَا الۡاِنۡسَانَ مِنۡ سُلٰلَۃٍ  مِّنۡ طِیۡنٍ ﴿ۚ۱۲﴾', 'اور ہم نے انسان کو مٹی کے خلاصے سے پیدا کیا ہے۔', 'اور ہم نے بنایا آدمی کو چنی ہوئی مٹی سے [۸]', 'And indeed We created man (Adam) out of an extract of clay (water and earth).', 'We have created man from an extract of clay.'),
(2686, 23, 13, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'ثُمَّ  جَعَلۡنٰہُ  نُطۡفَۃً  فِیۡ قَرَارٍ مَّکِیۡنٍ ﴿۪۱۳﴾', 'پھر اسکو ایک مضبوط اور محفوظ جگہ میں نطفہ بنا کر رکھا۔', 'پھر ہم نے رکھا اُسکو پانی کی بوند کر کے ایک جمے ہوئے ٹھکانہ میں [۹]', 'Thereafter We made him (the offspring of Adam) as a Nutfah (mixed drops of the male and female sexual discharge) (and lodged it) in a safe lodging (womb of the woman).', 'Then We made him a sperm-drop in a firm resting place.'),
(2687, 23, 14, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'ثُمَّ خَلَقۡنَا النُّطۡفَۃَ عَلَقَۃً  فَخَلَقۡنَا الۡعَلَقَۃَ مُضۡغَۃً فَخَلَقۡنَا الۡمُضۡغَۃَ عِظٰمًا فَکَسَوۡنَا الۡعِظٰمَ لَحۡمًا ٭ ثُمَّ اَنۡشَاۡنٰہُ خَلۡقًا اٰخَرَ ؕ فَتَبٰرَکَ اللّٰہُ  اَحۡسَنُ  الۡخٰلِقِیۡنَ ﴿ؕ۱۴﴾', 'پھر ہم نے نطفے کا لوتھڑا بنایا۔ پھر لوتھڑے کی بوٹی بنائی۔ پھر بوٹی کی ہڈیاں بنائیں پھر ہڈیوں پر گوشت پوست چڑھایا پھر اسکو نئی صورت میں بنا دیا۔ سو بڑا برکت والا ہے اللہ جو سب سے اچھا بنانے والا ہے۔', 'پھر بنایا اس بوند سے لہو جما ہوا پھر بنائی اس لہو جمے ہوئے سے گوشت کی بوٹی پھر بنائیں اُس بوٹی سےہڈیاں پھر پہنایا ہڈیوں پر گوشت [۱۰] پھر اٹھا کھڑا کیا اسکو ایک نئی صورت میں [۱۱] سو بڑی برکت اللہ کی جو سب سے بہتر بنانے والا ہے [۱۲]', 'Then We made the Nutfah into a clot (a piece of thick coagulated blood), then We made the clot into a little lump of flesh, then We made out of that little lump of flesh bones, then We clothed the bones with flesh, and then We brought it forth as another creation. So blessed be Allah, the Best of creators.', 'Then We turned the sperm-drop into a clot, then We turned the clot into a fetus-lump, then We turned the fetus-lump into bones, then We clothed the bones with flesh; thereafter We developed it into another creature. So, glorious is Allah, the Best of the creators.'),
(2688, 23, 15, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'ثُمَّ  اِنَّکُمۡ بَعۡدَ ذٰلِکَ لَمَیِّتُوۡنَ ﴿ؕ۱۵﴾', 'پھر اس کے بعد تم مر جاتے ہو۔', 'پھر تم اسکے بعد مرو گے [۱۳]', 'After that, surely, you will die.', 'Then, after all this, you are to die.'),
(2689, 23, 16, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'ثُمَّ   اِنَّکُمۡ  یَوۡمَ  الۡقِیٰمَۃِ تُبۡعَثُوۡنَ ﴿۱۶﴾', 'پھر قیامت کے روز اٹھا کھڑے کئے جاؤ گے۔', 'پھر تم قیامت کے دن کھڑے کئےجاؤ گے [۱۴]', 'Then (again), surely, you will be resurrected on the Day of Resurrection.', 'Then you are to be raised again on the Day of Judgment.'),
(2690, 23, 17, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ لَقَدۡ خَلَقۡنَا فَوۡقَکُمۡ  سَبۡعَ طَرَآئِقَ ٭ۖ وَ  مَا کُنَّا عَنِ  الۡخَلۡقِ غٰفِلِیۡنَ ﴿۱۷﴾', 'اور ہم نے تمہارے اوپر کی جانب سات آسمان پیدا کئے اور ہم خلقت سے غافل نہیں ہیں۔', 'اور ہم نے بنائے ہیں تمہارے اوپر سات رستے [۱۵] اور ہم نہیں ہیں خلق سے بے خبر [۱۶]', 'And indeed We have created above you seven heavens (one over the other), and We are never unaware of the creation.', 'And We created above you seven paths (heavens), and We were never neglectful of the creation.'),
(2691, 23, 18, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ اَنۡزَلۡنَا مِنَ السَّمَآءِ مَآءًۢ بِقَدَرٍ فَاَسۡکَنّٰہُ  فِی الۡاَرۡضِ ٭ۖ وَ اِنَّا عَلٰی ذَہَابٍۭ بِہٖ  لَقٰدِرُوۡنَ ﴿ۚ۱۸﴾', 'اور ہم ہی نے آسمان سے ایک اندازے کے ساتھ پانی برسایا۔ پھر اسکو زمین میں ٹھہرا دیا اور ہم اسکے نابود کر دینے پر بھی قادر ہیں۔', 'اور اتارا ہم نے آسمان سے پانی ماپ کر [۱۷] پھر اُسکو ٹھہرا دیا زمین میں [۱۸] اور ہم اُسکو لیجائیں تو لیجا سکتے ہیں [۱۹]', 'And We sent down from the sky water (rain) in (due) measure, and We gave it lodging in the earth, and verily, We are Able to take it away.', 'And We sent down water from the sky in due measure, then We lodged it in the earth, and of course, We are able to take it away.'),
(2692, 23, 19, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'فَاَنۡشَاۡنَا لَکُمۡ بِہٖ جَنّٰتٍ مِّنۡ نَّخِیۡلٍ وَّ اَعۡنَابٍ ۘ لَکُمۡ فِیۡہَا فَوَاکِہُ کَثِیۡرَۃٌ  وَّ  مِنۡہَا تَاۡکُلُوۡنَ ﴿ۙ۱۹﴾', 'پھر ہم نے اس سے تمہارے لئے کھجوروں اور انگوروں کے باغ بنائے ان میں تمہارے لئے بہت سے میوے ہوتے ہیں اور ان میں سے تم کھاتے ہو۔', 'پھر اگا دیے تمہارے واسطے اُس سے باغ کھجور اور انگور کے تمہارے واسطے ان میں میوے ہیں بہت اور اُنہی میں سے کھاتے ہو [۲۰]', 'Then We brought forth for you therewith gardens of date-palms and grapes, wherein is much fruit for you, and whereof you eat.', 'Then We produced with it gardens of date-palms and vines for your benefit. For you there are many fruits in them, and of them you eat'),
(2693, 23, 20, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ شَجَرَۃً  تَخۡرُجُ مِنۡ طُوۡرِ سَیۡنَآءَ تَنۡۢبُتُ بِالدُّہۡنِ وَ صِبۡغٍ  لِّلۡاٰکِلِیۡنَ ﴿۲۰﴾', 'اور وہ درخت بھی ہم ہی نے پیدا کیا جو طور سینا کے دامن میں ہوتا ہے یعنی زیتون کا درخت کہ کھانے کے لئے روغن اور سالن لئے ہوئے اگتا ہے۔', 'اور وہ درخت جو نکلتا ہے سینا پہاڑ سے لے اگتا ہے تیل اور روٹی ڈبونا کھانے والوں کے واسطے [۲۱]', 'And a tree (olive) that springs forth from Mount Sinai, that grows oil, and (it is a) relish for the eaters.', '- and (We produced) a tree (of olive) that comes forth from the (mount) Tūr of Sinai, which grows with oil and with a dressing for those who eat.'),
(2694, 23, 21, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ اِنَّ لَکُمۡ فِی الۡاَنۡعَامِ لَعِبۡرَۃً ؕ نُسۡقِیۡکُمۡ مِّمَّا فِیۡ بُطُوۡنِہَا وَ لَکُمۡ فِیۡہَا مَنَافِعُ کَثِیۡرَۃٌ  وَّ مِنۡہَا تَاۡکُلُوۡنَ ﴿ۙ۲۱﴾', 'اور تمہارے لئے چوپایوں میں بھی عبرت ہے کہ جو انکے پیٹوں میں ہے اس سے ہم تمہیں دودھ پلاتے ہیں اور تمہارے لئے ان میں اور بھی بہت سے فائدے ہیں اور بعض کو تم کھاتے بھی ہو۔', 'اور تمہارے چوپایوں میں دھیان کرنے کی بات ہے پلاتے ہیں ہم تمکو اُنکے پیٹ کی چیز سے اور تمہارے لئے اُن میں بہت فائدے ہیں اور بعضوں کو کھاتے ہو [۲۲]', 'And Verily! In the cattle there is indeed a lesson for you. We give you to drink (milk) of that which is in their bellies. And there are, in them, numerous (other) benefits for you, and of them you eat.', 'And indeed there is a sure lesson in the cattle for you. We give you a drink from that which lies in their bellies, and for you there are many benefits in them, and of them you eat,'),
(2695, 23, 22, 1, 1, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ  عَلَیۡہَا وَ عَلَی الۡفُلۡکِ  تُحۡمَلُوۡنَ ﴿٪۲۲﴾', 'اور ان پر اور کشتیوں پر تم سواری بھی کرتے ہو۔', 'اور اُن پر اور کشتیوں پر لدے پھرتے ہو [۲۳]', 'And on them, and on ships you are carried.', 'and on them and on the boats you are transported.'),
(2696, 23, 23, 2, 2, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ لَقَدۡ اَرۡسَلۡنَا نُوۡحًا اِلٰی قَوۡمِہٖ فَقَالَ یٰقَوۡمِ اعۡبُدُوا اللّٰہَ مَا لَکُمۡ  مِّنۡ  اِلٰہٍ غَیۡرُہٗ ؕ اَفَلَا تَتَّقُوۡنَ ﴿۲۳﴾', 'اور ہم نے نوح کو انکی قوم کی طرف بھیجا تو انہوں نے ان سے کہا کہ اے قوم اللہ ہی کی عبادت کرو اسکے سوا تمہارا کوئی معبود نہیں تو کیا تم ڈرتے نہیں؟', 'اور ہم نے بھیجا نوح کو اُسکی قوم کے پاس تو اُس نے کہا اے قوم بندگی کرو اللہ کی تمہارا کوئی حاکم نہیں اُسکے سوائے کیا تم ڈرتے نہیں', 'And indeed We sent Nooh (Noah) to his people, and he said: \"O my people! Worship Allah! You have no other Ilah (God) but Him (Islamic Monotheism). Will you not then be afraid (of Him i.e. of His Punishment because of worshipping others besides Him)?\"', 'Surely, We sent NūH to his nation. So he said, “My people, worship Allah. You have no god whatsoever other than Him. So, do you not fear Allah?”'),
(2697, 23, 24, 2, 2, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'فَقَالَ الۡمَلَؤُا الَّذِیۡنَ  کَفَرُوۡا مِنۡ قَوۡمِہٖ مَا ہٰذَاۤ  اِلَّا بَشَرٌ  مِّثۡلُکُمۡ ۙ یُرِیۡدُ  اَنۡ یَّتَفَضَّلَ عَلَیۡکُمۡ ؕ وَ لَوۡ شَآءَ اللّٰہُ لَاَنۡزَلَ مَلٰٓئِکَۃً ۚۖ مَّا سَمِعۡنَا بِہٰذَا فِیۡۤ  اٰبَآئِنَا  الۡاَوَّلِیۡنَ ﴿ۚ۲۴﴾', 'اس پر انکی قوم کے سردار جو کافر تھے کہنے لگے کہ یہ تو تم ہی جیسا آدمی ہے۔ تم پر بڑائی حاصل کرنی چاہتا ہے۔ اور اگر اللہ چاہتا تو فرشتے اتار دیتا۔  ہم نے اپنے اگلے باپ دادا میں تو یہ بات کبھی سنی نہیں۔', 'تب بولے سردار جو کافر تھے اُسکی قوم میں یہ کیا ہے آدمی ہے جیسے تم [۲۴] چاہتا ہے کہ بڑائی کرے تم پر اور اگر اللہ چاہتا تو اتارتا فرشتے [۲۵] ہم نے یہ نہیں سنا اپنے اگلے باپ دادوں میں [۲۶]', 'But the chiefs of those who disbelieved among his people said: \"He is no more than a human being like you, he seeks to make himself superior to you. Had Allah willed, He surely could have sent down angels; never did we hear such a thing among our fathers of old.', 'So, said the disbelieving chiefs from among his nation, “This (man) is nothing but a human being like you. He wishes to impose his superiority over you. Had Allah willed, He would have sent down angels (instead of him). We have not heard of such a thing among our forefathers.'),
(2698, 23, 25, 2, 2, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اِنۡ ہُوَ  اِلَّا رَجُلٌۢ بِہٖ جِنَّۃٌ  فَتَرَبَّصُوۡا بِہٖ  حَتّٰی حِیۡنٍ ﴿۲۵﴾', 'اس آدمی کو تو دیوانگی کا عارضہ ہے تو اسکے بارے میں کچھ مدت انتظار کرو۔', 'اور کچھ نہیں یہ ایک مرد ہے کہ اسکو سودا ہے سو راہ دیکھو  اسکی ایک وقت تک [۲۷]', '\"He is only a man in whom is madness, so wait for him a while.\"', 'He is none but a man suffering from madness; so wait for (what happens to) him until some time”'),
(2699, 23, 26, 2, 2, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'قَالَ  رَبِّ  انۡصُرۡنِیۡ بِمَا کَذَّبُوۡنِ ﴿۲۶﴾', 'نوح نے کہا کہ پروردگار انہوں نے مجھے جھٹلایا ہے تو میری مدد کر۔', 'بولا اے رب تو مدد کر میری کہ انہوں نے مجھ کو جھٹلایا [۲۸]', '(Nooh (Noah)) said: \"O my Lord! Help me because they deny me.\"', 'He said, “My Lord, help me, for they have rejected me.”'),
(2700, 23, 27, 2, 2, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'فَاَوۡحَیۡنَاۤ اِلَیۡہِ اَنِ اصۡنَعِ الۡفُلۡکَ بِاَعۡیُنِنَا وَ وَحۡیِنَا فَاِذَا جَآءَ  اَمۡرُنَا وَ فَارَ التَّنُّوۡرُ ۙ فَاسۡلُکۡ فِیۡہَا مِنۡ کُلٍّ زَوۡجَیۡنِ اثۡنَیۡنِ وَ اَہۡلَکَ  اِلَّا مَنۡ سَبَقَ عَلَیۡہِ الۡقَوۡلُ مِنۡہُمۡ ۚ وَ لَا تُخَاطِبۡنِیۡ فِی الَّذِیۡنَ ظَلَمُوۡا ۚ اِنَّہُمۡ  مُّغۡرَقُوۡنَ ﴿۲۷﴾', 'پس ہم نے انکی طرف وحی بھیجی کہ ہمارے سامنے اور ہمارے حکم سے کشتی بناؤ۔ پھر جب ہمارا حکم آ پہنچے اور تنور پانی سے بھر کر جوش مارنے لگے تو سب قسم کے پالتو حیوانات میں سے جوڑا جوڑا یعنی نر اور مادہ دو دو کشتی میں بٹھا لو اور اپنے گھر والوں کو بھی۔ سوائے انکے جنکی نسبت ان میں سے ہلاک ہونے کا حکم پہلے صادر ہو چکا ہے اور ظالموں کے بارے میں مجھ سے کچھ نہ کہنا۔ وہ ضرور ڈبو دیئے جائیں گے۔', 'پھر ہم نے حکم بھیجا اُسکو کہ بنا کشتی ہماری آنکھوں کے سامنے اور ہمارے حکم سے پھر جب پہنچے ہمارا حکم اور ابلے تنور تو تو ڈال لے کشتی میں ہر چیز کا جوڑا دو دو اور اپنے گھر کے لوگ [۲۹] مگر جسکی قسمت میں پہلے سے ٹھہر چکی ہے بات [۳۰] اور مجھ سے بات نہ کر  ان ظالموں کے واسطے بیشک اُنکو ڈوبنا ہے [۳۱]', 'So We inspired him (saying): \"Construct the ship under Our Eyes and under Our Revelation (guidance). Then, when Our Command comes, and the oven gushes forth water, take on board of each kind two (male and female), and your family, except those thereof against whom the Word has already gone forth. And address Me not in favour of those who have done wrong. Verily, they are to be drowned.', 'So, We sent Our revelation to him, saying, “Make the ship under Our eyes and Our revelation. So, when Our command will come, and the oven will gush forth, take on its board a pair of two from each (species) along with your family, except those of them against whom the word has already come to pass. And do not speak to Me (in favor) of those who have done wrong. They are sure to be drowned.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(2701, 23, 28, 2, 2, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'فَاِذَا اسۡتَوَیۡتَ اَنۡتَ وَ مَنۡ مَّعَکَ عَلَی الۡفُلۡکِ فَقُلِ الۡحَمۡدُ  لِلّٰہِ  الَّذِیۡ نَجّٰنَا مِنَ الۡقَوۡمِ  الظّٰلِمِیۡنَ ﴿۲۸﴾', 'پس جب تم اور تمہارے ساتھی کشتی میں بیٹھ جاؤ تو اللہ کا شکر کرنا اور کہنا کہ سب تعریف اللہ ہی کیلئے ہے جس نے ہمکو ظالم لوگوں سے نجات بخشی۔', 'پھر جب چڑھ چکے تو اور جو تیرے ساتھ ہے کشی پر تو کہہ شکر اللہ کا جس نے چھڑایا ہمکو گنہگار لوگوں سے [۳۲]', 'And when you have embarked on the ship, you and whoever is with you, then say: \"All the praises and thanks be to Allah, Who has saved us from the people who are Zalimoon (i.e. oppressors, wrong-doers, polytheists, those who join others in worship with Allah, etc.).', 'So, when you and those with you are well seated in the ship, say, ‘Praise is for Allah who saved us from the wrongdoing people.’'),
(2702, 23, 29, 2, 2, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ قُلۡ رَّبِّ اَنۡزِلۡنِیۡ مُنۡزَلًا مُّبٰرَکًا وَّ اَنۡتَ خَیۡرُ  الۡمُنۡزِلِیۡنَ ﴿۲۹﴾', 'اور یہ بھی دعا کرنا کہ اے پروردگار ہم کو مبارک جگہ اتاریو اور تو سب سے بہتر اتارنے والا ہے۔', 'اور کہہ اے رب اتار مجھ کو برکت کا اتارنا اور تو ہے بہتر اتارنے والا [۳۳]', 'And say: \"My Lord! Cause me to land at a blessed landing-place, for You are the Best of those who bring to land.\"', 'And say, ‘My Lord, make me land a blessed landing, and You are the best of those who bring (someone) to land’”.'),
(2703, 23, 30, 2, 2, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اِنَّ فِیۡ ذٰلِکَ لَاٰیٰتٍ وَّ اِنۡ  کُنَّا لَمُبۡتَلِیۡنَ ﴿۳۰﴾', 'بیشک اس قصے میں نشانیاں ہیں اور ہمیں تو آزمائش کرنا تھی۔', 'اس میں نشانیاں ہیں اور ہم ہیں جانچنے والے [۳۴]', 'Verily, in this (what We did as regards drowning of the people of Nooh (Noah)), there are indeed Ayat (proofs, evidences, lessons, signs, etc. for men to understand), for sure We are ever putting (men) to the test.', 'Surely, there are signs in it, and We do always test (people).'),
(2704, 23, 31, 2, 2, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'ثُمَّ  اَنۡشَاۡنَا مِنۡۢ بَعۡدِہِمۡ قَرۡنًا اٰخَرِیۡنَ ﴿ۚ۳۱﴾', 'پھر انکے بعد ہم نے ایک اور جماعت پیدا کی۔', 'پھر پیدا کی ہم نے اُن سے پیچھے ایک جماعت اور [۳۵]', 'Then, after them, We created another generation.', 'Then after them We created another generation,'),
(2705, 23, 32, 2, 2, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'فَاَرۡسَلۡنَا فِیۡہِمۡ رَسُوۡلًا مِّنۡہُمۡ اَنِ اعۡبُدُوا اللّٰہَ مَا لَکُمۡ  مِّنۡ   اِلٰہٍ  غَیۡرُہٗ ؕ اَفَلَا  تَتَّقُوۡنَ ﴿٪۳۲﴾', 'اور انہی میں سے ان میں ایک پیغمبر بھیجا جس نے ان سے کہا کہ اللہ ہی کی عبادت کرو کہ اسکے سوا تمہارا کوئی معبود نہیں۔ تو کیا تم ڈرتے نہیں؟', 'پھر بھیجا ہم نے اُن میں ایک رسول اُن میں کا [۳۶] کہ بندگی کرو اللہ کی کوئی نہیں تمہارا حاکم اُسکے سوائے پھر کیا تم ڈرتے نہیں', 'And We sent to them a Messenger from among themselves (saying): \"Worship Allah! You have no other Ilah (God) but Him. Will you not then be afraid (of Him i.e. of His Punishment because of worshipping others besides Him)?\"', 'and sent among them a messenger from themselves (to convey the message): “Worship Allah; you have no god whatsoever other than Him. So do you not fear Allah?”'),
(2706, 23, 33, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ قَالَ الۡمَلَاُ مِنۡ قَوۡمِہِ الَّذِیۡنَ  کَفَرُوۡا وَ کَذَّبُوۡا بِلِقَآءِ الۡاٰخِرَۃِ وَ اَتۡرَفۡنٰہُمۡ فِی الۡحَیٰوۃِ الدُّنۡیَا ۙ مَا ہٰذَاۤ  اِلَّا بَشَرٌ مِّثۡلُکُمۡ ۙ یَاۡکُلُ  مِمَّا تَاۡکُلُوۡنَ مِنۡہُ وَ  یَشۡرَبُ  مِمَّا تَشۡرَبُوۡنَ ﴿۪ۙ۳۳﴾', 'اور انکی قوم کے سردار جو کافر تھے اور آخرت کے آنے کو جھوٹ سمجھتے تھے اور دنیا کی زندگی میں ہم نے انکو آسودگی دے رکھی تھی کہنے لگے کہ یہ تو تم ہی جیسا آدمی ہے جس قسم کا کھانا تم کھاتے ہو اسی طرح کا یہ بھی کھاتا ہے اور جو پانی تم پیتے ہو اسی قسم کا یہ بھی پیتا ہے۔', 'اور بولے سردار اُسکی قوم کے جو کافر تھے اور جھٹلاتے تھے آخرت کی ملاقات کو اور آرام دیا تھا اُنکو ہم نے دنیا کی زندگی میں [۳۷] اور کچھ نہیں یہ ایک آدمی ہے جیسے تم، کھاتا ہے جس قسم سے تم کھاتے ہو اور پیتا ہے جس قسم سے تم پیتے ہو [۳۸]', 'And the chiefs of his people, who disbelieved and denied the Meeting in the Hereafter, and to whom We had given the luxuries and comforts of this life, said: \"He is no more than a human being like you, he eats of that which you eat, and drinks of what you drink.', 'Then said the chiefs of his nation who were disbelievers and who denied facing the Hereafter and whom We made affluent in the worldly life, “This (man) is nothing but a human being. He eats from what you eat from, and drinks from what you drink.'),
(2707, 23, 34, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ لَئِنۡ اَطَعۡتُمۡ بَشَرًا مِّثۡلَکُمۡ  اِنَّکُمۡ  اِذًا لَّخٰسِرُوۡنَ ﴿ۙ۳۴﴾', 'اور اگر تم نے اپنے ہی جیسے آدمی کا کہا مان لیا تب تو تم گھاٹے میں پڑ گئے۔', 'اور کہیں تم چلنے لگے کہنے پر ایک آدمی کے اپنے برابر کے تو تم بیشک خراب ہوئے [۳۹]', '\"If you were to obey a human being like yourselves, then verily! You indeed would be losers.', 'If you obey a human like yourselves, then you will be absolute losers.'),
(2708, 23, 35, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اَیَعِدُکُمۡ اَنَّکُمۡ  اِذَا مِتُّمۡ وَ کُنۡتُمۡ تُرَابًا وَّ عِظَامًا  اَنَّکُمۡ  مُّخۡرَجُوۡنَ ﴿۪ۙ۳۵﴾', 'کیا یہ تم سے یہ کہتا ہے کہ جب تم مر جاؤ گے اور مٹی ہو جاؤ گے۔ اور ہڈیوں کے سوا کچھ نہ رہے گا تو تم زمین سے نکالے جاؤ گے؟', 'کیا تم کو وعدہ دیتا ہے کہ جب تم مر جاؤ اور ہو جاؤ مٹی اور ہڈیاں تو تمکو نکلنا ہے', '\"Does he promise you that when you have died and have become dust and bones, you shall come out alive (resurrected)?', 'Does he promise you that, when you die and are turned into dust and bones, you are to be brought forth?'),
(2709, 23, 36, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'ہَیۡہَاتَ ہَیۡہَاتَ لِمَا تُوۡعَدُوۡنَ ﴿۪ۙ۳۶﴾', 'جس بات کا تم سے وعدہ کیا جاتا ہے بہت بعید اور بہت بعید ہے۔', 'کہاں ہو سکتا ہے کہاں ہوسکتا ہے جو تم سے وعدہ ہوتا ہے [۴۰]', '\"Far, very far is that which you are promised.', 'Far too improbable is what you are being promised.'),
(2710, 23, 37, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اِنۡ ہِیَ  اِلَّا حَیَاتُنَا الدُّنۡیَا نَمُوۡتُ وَ نَحۡیَا وَ مَا نَحۡنُ بِمَبۡعُوۡثِیۡنَ ﴿۪ۙ۳۷﴾', 'زندگی تو یہی ہماری دنیا کی زندگی ہے کہ اسی میں ہم مرتے اور جیتے ہیں اور ہم پھر نہیں اٹھائے جائیں گے۔', 'اور کچھ نہیں یہی جینا ہے ہمارا دنیا کا مرتے ہیں اور جیتے ہیں اور ہمکو پھر اٹھنا نہیں [۴۱]', '\"There is nothing but our life of this world! We die and we live! And we are not going to be resurrected!', 'There is nothing but our worldly life. We die and we live, and we are not to be raised again.'),
(2711, 23, 38, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اِنۡ ہُوَ  اِلَّا رَجُلُۨ  افۡتَرٰی عَلَی اللّٰہِ  کَذِبًا وَّ  مَا نَحۡنُ  لَہٗ  بِمُؤۡمِنِیۡنَ ﴿۳۸﴾', 'یہ تو ایک ایسا آدمی ہے جس نے اللہ پر جھوٹ افترا کیا ہے اور ہم اسکو ماننے والے نہیں۔', 'اور کچھ نہیں یہ ایک مرد ہے باندھ لایا ہے اللہ پر جھوٹ [۴۲] اور اُسکو ہم نہیں ماننے والے', '\"He is only a man who has invented a lie against Allah, but we are not going to believe in him.\"', 'He is nothing but a man who has forged a lie against Allah, and we are not going to believe in him.”'),
(2712, 23, 39, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'قَالَ رَبِّ انۡصُرۡنِیۡ  بِمَا کَذَّبُوۡنِ ﴿۳۹﴾', 'پیغمبر نے کہا کہ اے پروردگار انہوں نے مجھے جھوٹا سمجھا ہے تو میری مدد کر۔', 'بولا اے رب میری مدد کر کہ انہوں نے مجھ کو جھٹلایا [۴۳]', 'He said: \"O my Lord! Help me because they deny me.\"', 'He said, “My Lord, help me, for they have rejected me.”'),
(2713, 23, 40, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'قَالَ عَمَّا قَلِیۡلٍ لَّیُصۡبِحُنَّ نٰدِمِیۡنَ ﴿ۚ۴۰﴾', 'فرمایا کہ یہ تھوڑے ہی عرصے میں پشیمان ہو کر رہ جائیں گے۔', 'فرمایا اب تھوڑے دنوں میں صبح کو رہ جائیں گے پچتاتے [۴۴]', '(Allah) said: \"In a little while, they are sure to be regretful.\"', 'He (Allah) said, “In a little while they will have to be remorseful.”'),
(2714, 23, 41, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'فَاَخَذَتۡہُمُ الصَّیۡحَۃُ بِالۡحَقِّ فَجَعَلۡنٰہُمۡ غُثَآءً ۚ فَبُعۡدًا لِّلۡقَوۡمِ  الظّٰلِمِیۡنَ ﴿۴۱﴾', 'آخر انکو وعدہ برحق کے مطابق زور کی آواز نے آ پکڑا تو ہم نے انکو کوڑا کر ڈالا پس ظالم لوگوں پر لعنت ہے۔', 'پھر پکڑا اُنکو چنگھاڑ نے تحقیق [۴۵] پھر کر دیا ہم نے اُنکو کوڑا [۴۶] سو دور ہو جائیں گنہگار لوگ [۴۷]', 'So As-Saeehah (torment - awful cry, etc.) overtook them with justice, and We made them as rubbish of dead plants. So away with the people who are Zalimoon (polytheists, wrong-doers, disbelievers in the Oneness of Allah, disobedient to His Messengers, etc.).', 'So the Cry seized them according to the true (promise), and We turned them in to scum. So, away with the wrongdoing people.'),
(2715, 23, 42, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'ثُمَّ اَنۡشَاۡنَا مِنۡۢ بَعۡدِہِمۡ قُرُوۡنًا اٰخَرِیۡنَ ﴿ؕ۴۲﴾', 'پھر انکے بعد ہم نے اور جماعتیں پیدا کیں۔', 'پھر  پیدا کیں ہم نے اُن سے پیچھے جماعتیں اور', 'Then, after them, We created other generations.', 'Then, after them, We created another generation.'),
(2716, 23, 43, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'مَا تَسۡبِقُ مِنۡ اُمَّۃٍ  اَجَلَہَا وَ مَا یَسۡتَاۡخِرُوۡنَ ﴿ؕ۴۳﴾', 'کوئی جماعت اپنے وقت سے نہ آگے جاسکتی ہے نہ پیچھے رہ سکتی ہے۔', 'نہ آگے جائے کوئی قوم اپنے وعدہ سے اور نہ پیچھے رہے [۴۸]', 'No nation can anticipate their term, nor can they delay it.', 'No community can go ahead of its appointed time, nor can they become late.'),
(2717, 23, 44, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'ثُمَّ  اَرۡسَلۡنَا رُسُلَنَا تَتۡرَا ؕ کُلَّمَا جَآءَ اُمَّۃً  رَّسُوۡلُہَا کَذَّبُوۡہُ  فَاَتۡبَعۡنَا بَعۡضَہُمۡ بَعۡضًا وَّ جَعَلۡنٰہُمۡ اَحَادِیۡثَ ۚ فَبُعۡدًا  لِّقَوۡمٍ لَّا  یُؤۡمِنُوۡنَ ﴿۴۴﴾', 'پھر ہم  لگاتار اپنے پیغمبر بھیجتے رہے جب کسی امت کے پاس اس کا پیغمبر آتا تھا تو وہ اسے جھٹلا دیتے تھے۔ تو ہم بھی بعض کو بعض کے پیچھے ہلاک کرتے اور ان پر عذاب لاتے رہے اور انکو داستانیں بنا کر چھوڑتے رہے پس جو لوگ ایمان نہیں لاتے ان پر لعنت۔', 'پھر بھیجتے رہے ہم  اپنے رسول لگاتار جہاں پہنچا کسی امت کے پاس اُن کا رسول اُسکو جھٹلا دیا پھر چلاتے گئے ہیں ہم ایک کے پیچھے دوسرے  اور کر ڈالا اُنکو کہانیاں [۴۹] سو دو ہو جائیں جو لوگ نہیں مانتے [۵۰]', 'Then We sent Our Messengers in succession, every time there came to a nation their Messenger, they denied him, so We made them follow one another (to destruction), and We made them as Ahadeeth (the true stories for mankind to learn a lesson from them). So away with a people who believe not.', 'Thereafter, We sent Our messengers successively. Whenever its messenger came to a community, they rejected him. Then We made some of them follow others (in destruction) and turned them into tales (of history). So, away with a people who do not believe.'),
(2718, 23, 45, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'ثُمَّ  اَرۡسَلۡنَا مُوۡسٰی وَ اَخَاہُ  ہٰرُوۡنَ ۬ۙ بِاٰیٰتِنَا وَ  سُلۡطٰنٍ مُّبِیۡنٍ  ﴿ۙ۴۵﴾', 'پھر ہم نے موسٰی اور انکے بھائی ہارون کو اپنی نشانیاں اور دلیل ظاہر دے کر بھیجا۔', 'پھر بھیجا ہم نے موسٰی اور اُسکے بھائی ہارون کو اپنی نشانیاں دیکر اور کھلی سند', 'Then We sent Moosa (Moses) and his brother Haroon (Aaron), with Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) and manifest authority,', 'Thereafter, We sent Mūsā and his brother Hārūn with Our signs and a clear proof'),
(2719, 23, 46, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اِلٰی فِرۡعَوۡنَ وَ مَلَا۠ئِہٖ فَاسۡتَکۡبَرُوۡا وَ کَانُوۡا  قَوۡمًا عَالِیۡنَ ﴿ۚ۴۶﴾', 'یعنی فرعون اور اسکے درباریوں کی طرف۔ تو انہوں نے تکبر کیا اور وہ سرکش لوگ تھے۔', 'فرعون اور اُسکے سرداروں کے پاس پھر لگے بڑائی کرنے اور وہ لوگ زور پر چڑھ رہے تھے [۵۱]', 'To Firaun (Pharaoh) and his chiefs, but they behaved insolently and they were people self-exalting (by disobeying their Lord, and exalting themselves over and above the Messenger of Allah).', 'towards Fir‘aun (Pharaoh) and his advisors. But they showed arrogance and they were haughty people.'),
(2720, 23, 47, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'فَقَالُوۡۤا اَنُؤۡمِنُ لِبَشَرَیۡنِ مِثۡلِنَا وَ قَوۡمُہُمَا  لَنَا عٰبِدُوۡنَ ﴿ۚ۴۷﴾', 'کہنے لگے کیا ہم ان اپنے جیسے دو آدمیوں پر ایمان لے آئیں جبکہ انکی قوم کے لوگ ہمارے خدمتگار ہیں۔', 'سو بولے کیا ہم مانیں گے اپنی برابر کے دو آدمیوں کو اور اُنکی قوم ہمارے تابعدار ہیں [۵۲]', 'They said: \"Shall we believe in two men like ourselves, and their people are obedient to us with humility (and we use them to serve us as we like).\"', 'So they said, “shall we believe in two humans who are like ourselves and whose people are serving us as slaves?”'),
(2721, 23, 48, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'فَکَذَّبُوۡہُمَا فَکَانُوۡا مِنَ الۡمُہۡلَکِیۡنَ ﴿۴۸﴾', 'تو ان لوگوں نے انکی تکذیب کی سو آخر ہلاک کر دیئے گئے۔', 'پھر جھٹلایا اُن دونوں کو پھر ہو گئے غارت ہونے والوں میں', 'So they denied them both (Moosa (Moses) and Haroon (Aaron)) and became of those who were destroyed.', 'Thus they rejected both of them and were among the destroyed.'),
(2722, 23, 49, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ لَقَدۡ اٰتَیۡنَا مُوۡسَی الۡکِتٰبَ لَعَلَّہُمۡ یَہۡتَدُوۡنَ ﴿۴۹﴾', 'اور ہم نے موسٰی کو کتاب دی تھی تاکہ وہ لوگ ہدایت پائیں۔', 'اور ہم نے دی موسٰی کو کتاب تاکہ وہ راہ پائیں [۵۳]', 'And indeed We gave Moosa (Moses) the Scripture, that they may be guided.', 'And, of course, We gave Mūsā the Book, so that they may take the right path.'),
(2723, 23, 50, 3, 3, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ جَعَلۡنَا ابۡنَ مَرۡیَمَ وَ اُمَّہٗۤ  اٰیَۃً وَّ اٰوَیۡنٰہُمَاۤ  اِلٰی رَبۡوَۃٍ  ذَاتِ قَرَارٍ وَّ مَعِیۡنٍ ﴿٪۵۰﴾', 'اور ہم نے مریم کے بیٹے عیسٰی اور انکی ماں کو ایک نشانی بنایا تھا اور انکو ایک اونچی جگہ پر جو رہنے کے لائق تھی اور جہاں نتھرا ہوا پانی جاری تھا پناہ دی تھی۔', 'اور بنایا ہم نے مریم کے بیٹے اور اُسکی ماں کو ایک نشانی [۵۴] اور اُنکو ٹھکانا دیا ایک ٹیلہ پر جہاں ٹھہرنے کا موقع تھا اور پانی نتھرا [۵۵]', 'And We made the son of Maryam (Mary) and his mother as a sign, And We gave them refuge on high ground, a place of rest, security and flowing streams.', 'And We made the son of Maryam (Mary) and his mother a sign, and gave them shelter on a height, having a place of rest and running springs.'),
(2724, 23, 51, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'یٰۤاَیُّہَا الرُّسُلُ کُلُوۡا مِنَ الطَّیِّبٰتِ وَ اعۡمَلُوۡا صَالِحًا ؕ اِنِّیۡ  بِمَا تَعۡمَلُوۡنَ عَلِیۡمٌ ﴿ؕ۵۱﴾', 'اے پیغمبرو پاکیزہ چیزیں کھاؤ اور عمل نیک کرو۔ جو عمل تم کرتے ہو میں ان سے واقف ہوں۔', 'اے رسولو کھاؤ ستھری چیزیں اور کام کرو بھلا [۵۶] جو تم کرتے ہو میں جانتا ہوں [۵۷]', 'O (you) Messengers! Eat of the Taiyibat (all kinds of Halal (legal) foods which Allah has made legal (meat of slaughtered eatable animals, milk products, fats, vegetables, fruits, etc.), and do righteous deeds. Verily! I am Well-Acquainted with what you do.', 'O messengers, eat from the good things, and act righteously. Of whatever you do, I am fully aware.'),
(2725, 23, 52, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ  اِنَّ ہٰذِہٖۤ  اُمَّتُکُمۡ  اُمَّۃً وَّاحِدَۃً  وَّ اَنَا رَبُّکُمۡ  فَاتَّقُوۡنِ ﴿۵۲﴾', 'اور یہ تمہاری جماعت حقیقت میں ایک ہی جماعت ہے اور میں تمہارا پروردگار ہوں تو مجھ سے ڈرو۔', 'اور یہ لوگ ہیں تمہارے دین کے سب ایک دین پر اور میں ہوں تمہارا رب سو مجھ سے ڈرتے رہو', 'And verily! This your religion (of Islamic Monotheism) is one religion, and I am your Lord, so keep your duty to Me.', 'Surely, this is your creed, a single creed, and I am your Lord. So fear Me.'),
(2726, 23, 53, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'فَتَقَطَّعُوۡۤا  اَمۡرَہُمۡ بَیۡنَہُمۡ زُبُرًا ؕ کُلُّ حِزۡبٍۭ بِمَا  لَدَیۡہِمۡ  فَرِحُوۡنَ ﴿۵۳﴾', 'پھر لوگوں نے آپس میں اپنے کام کو متفرق کر کے ٹکڑے ٹکرے کر دیا جو چیز جس فرقے کے پاس ہے وہ اسی سے خوش ہو رہا ہے۔', 'پھر پھوٹ ڈال کر کر لیا اپنا کام آپس میں ٹکڑے ٹکڑے [۵۸] ہرفرقہ جو اُنکے پاس ہے اُس پر ریجھ رہے ہیں [۵۹]', 'But they (men) have broken their religion among them into sects, each group rejoicing in its belief.', 'But they split up ways from one another (dividing themselves) into factions, each faction happy with what lies before it.'),
(2727, 23, 54, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'فَذَرۡہُمۡ فِیۡ غَمۡرَتِہِمۡ حَتّٰی حِیۡنٍ ﴿۵۴﴾', 'تو انکو ایک مدت تک انکی غفلت ہی میں رہنے دو۔', 'سو چھوڑ دے تو اُنکو اُنکی بیہوشی میں ڈوبے ایک وقت تک [۶۰]', 'So leave them in their error for a time.', 'So leave them in their negligence for some time.'),
(2728, 23, 55, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اَیَحۡسَبُوۡنَ اَنَّمَا نُمِدُّہُمۡ بِہٖ مِنۡ مَّالٍ وَّ بَنِیۡنَ ﴿ۙ۵۵﴾', 'کیا یہ لوگ یہ خیال کرتے ہیں کہ ہم جو دنیا میں انکو مال اور بیٹوں سے مدد دیتے ہیں۔', 'کیا وہ خیال کرتےہیں کہ یہ جو ہم اُنکو  دیے جاتے ہیں مال اور اولاد', 'Do they think that We enlarge them in wealth and children,', 'Do they think that by consistently providing them with wealth and children,'),
(2729, 23, 56, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'نُسَارِعُ  لَہُمۡ فِی الۡخَیۡرٰتِ ؕ بَلۡ لَّا یَشۡعُرُوۡنَ ﴿۵۶﴾', 'تو اس سے انکی بھلائی میں جلدی کر رہے ہیں نہیں بلکہ یہ سمجھتے ہی نہیں۔', 'سو دوڑ دوڑ کر پہنچا رہے ہیں ہم اُنکو بھلائیاں [۶۱] یہ بات نہیں وہ سمجھتے نہیں [۶۲]', 'We hasten unto them with good things (in this worldly life so that they will have no share of good things in the Hereafter)? Nay, but they perceive not.', 'We are accelerating the (real) good things to them? The fact, however, is that they do not understand (the reality).'),
(2730, 23, 57, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اِنَّ الَّذِیۡنَ ہُمۡ مِّنۡ خَشۡیَۃِ  رَبِّہِمۡ مُّشۡفِقُوۡنَ ﴿ۙ۵۷﴾', 'جو لوگ اپنے پروردگار کے خوف کیوجہ سے ڈرتے ہیں۔', 'البتہ جو لوگ اپنے رب کے خوف سے اندیشہ رکھتے ہیں [۶۳]', 'Verily! Those who live in awe for fear of their Lord;', '(Contrarily) those who are anxious out of awe of their Lord,'),
(2731, 23, 58, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ الَّذِیۡنَ ہُمۡ بِاٰیٰتِ رَبِّہِمۡ  یُؤۡمِنُوۡنَ ﴿ۙ۵۸﴾', 'اور جو اپنے پروردگار کی آیتوں پر ایمان رکھتے ہیں۔', 'اور جو لوگ اپنے رب کی باتوں پر یقین کرتے ہیں [۶۴]', 'And those who believe in the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of their Lord,', 'and those who believe in the verses of their Lord'),
(2732, 23, 59, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ  الَّذِیۡنَ ہُمۡ  بِرَبِّہِمۡ  لَا  یُشۡرِکُوۡنَ ﴿ۙ۵۹﴾', 'اور جو اپنے پروردگار کے ساتھ شریک نہیں کرتے۔', 'اور جو لوگ اپنے رب کے ساتھ کسی کو شریک نہیں مانتے [۶۵]', 'And those who join not anyone (in worship) as partners with their Lord;', 'and those who do not associate any partner to their Lord,'),
(2733, 23, 60, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ الَّذِیۡنَ یُؤۡتُوۡنَ مَاۤ  اٰتَوۡا وَّ قُلُوۡبُہُمۡ وَجِلَۃٌ  اَنَّہُمۡ   اِلٰی رَبِّہِمۡ  رٰجِعُوۡنَ ﴿ۙ۶۰﴾', 'اور جو دے سکتے ہیں دیتے ہیں جبکہ انکے دل اس بات سے ڈرتے رہتے ہیں کہ انکو اپنے پروردگار کی طرف لوٹ کر جانا ہے۔', 'اور جو لوگ کہ دیتے ہیں جو کچھ دیتے ہیں وہ اور اُنکے دل ڈر رہے ہیں اس لئے کہ انکو  اپنے رب کی طرف لوٹ کر جانا ہے [۶۶]', 'And those who give that (their charity) which they give (and also do other good deeds) with their hearts full of fear (whether their alms and charities, etc., have been accepted or not), because they are sure to return to their Lord (for reckoning).', 'And those who give whatever they give, with their hearts full of fear that to their Lord they are to return'),
(2734, 23, 61, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اُولٰٓئِکَ یُسٰرِعُوۡنَ فِی الۡخَیۡرٰتِ وَ ہُمۡ لَہَا سٰبِقُوۡنَ ﴿۶۱﴾', 'یہی لوگ نیکیوں میں جلدی کرتے ہیں اور یہی انکے لئے آگے نکل جاتے ہیں۔', 'وہ لوگ دوڑ دوڑ کر لیتے ہیں بھلائیاں اور وہ ان پر پہنچے سب سے آگے [۶۷]', 'It is these who race for the good deeds, and they are foremost in them (e.g. offering the compulsory Salat (prayers) in their (early) stated, fixed times and so on).', '- those people are accelerating towards the (real) good things, and they are the foremost to attain them.'),
(2735, 23, 62, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ لَا نُکَلِّفُ نَفۡسًا اِلَّا وُسۡعَہَا وَ لَدَیۡنَا کِتٰبٌ یَّنۡطِقُ بِالۡحَقِّ وَ ہُمۡ لَا یُظۡلَمُوۡنَ ﴿۶۲﴾', 'اور ہم کسی شخص کو اسکی طاقت سے زیادہ ذمہ دار نہیں بناتے اور ہمارے پاس ایک کتاب ہے جو سچ سچ کہہ دیتی ہے اور ان پر ظلم نہیں کیا جائے گا۔', 'اور ہم کسی پر بوجھ نہیں ڈالتے مگر اسکی گنجائش کے موافق اور ہمارے پاس لکھا ہوا ہے جو بولتا ہے سچ اور ان پر ظلم نہ ہو گا [۶۸]', 'And We tax not any person except according to his capacity, and with Us is a Record which speaks the truth, and they will not be wronged.', 'We do not place a burden on anyone except according to his ability. With Us there is a book which speaks with truth, and they shall not be wronged.'),
(2736, 23, 63, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'بَلۡ قُلُوۡبُہُمۡ فِیۡ غَمۡرَۃٍ مِّنۡ ہٰذَا وَ لَہُمۡ اَعۡمَالٌ مِّنۡ دُوۡنِ ذٰلِکَ ہُمۡ لَہَا عٰمِلُوۡنَ ﴿۶۳﴾', 'مگر ان کے دل ان باتوں کی طرف سے غفلت میں پڑے ہوئے ہیں اور انکے سوا اور اعمال بھی ہیں جو یہ کرتے رہتے ہیں۔', 'کوئی نہیں انکے دل بیہوش ہیں اس طرف اور انکو اور کام لگ رہے ہیں اسکے سوائے کہ وہ انکو کر رہے ہیں [۶۹]', 'Nay, but their hearts are covered (blind) from understanding this (the Quran), and they have other (evil) deeds, besides, which they are doing.', 'But their hearts are in ignorance about this, and they have deeds, other than that, which they are continuously doing.'),
(2737, 23, 64, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'حَتّٰۤی  اِذَاۤ  اَخَذۡنَا مُتۡرَفِیۡہِمۡ بِالۡعَذَابِ اِذَا ہُمۡ  یَجۡـَٔرُوۡنَ ﴿ؕ۶۴﴾', 'یہاں تک کہ جب ہم نے ان میں سے آسودہ حال لوگوں کو عذاب میں پکڑ لیا تو وہ اسی وقت چلا اٹھیں گے۔', 'یہاں تک کہ جب پکڑیں گے ہم اُنکے آسودہ لوگوں کو آفت میں تبھی وہ لگیں گے چلانے', 'Until, when We grasp those of them who lead a luxurious life with punishment, behold! They make humble invocation with a loud voice.', 'Until when We will seize their affluent ones with punishment, they will suddenly start crying.'),
(2738, 23, 65, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'لَا تَجۡـَٔرُوا  الۡیَوۡمَ ۟ اِنَّکُمۡ مِّنَّا لَا تُنۡصَرُوۡنَ ﴿۶۵﴾', 'آج مت چلاؤ تمکو ہم سے کچھ مدد نہیں ملے گی۔', 'مت چلاؤ آج کے دن تم ہم سے چھوٹ نہ سکو گے [۷۰]', 'Invoke not loudly this day! Certainly, you shall not be helped by Us.', '(Then it will be said to them,) “Do not cry today. You will not be helped by Us.'),
(2739, 23, 66, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'قَدۡ کَانَتۡ اٰیٰتِیۡ تُتۡلٰی عَلَیۡکُمۡ فَکُنۡتُمۡ عَلٰۤی  اَعۡقَابِکُمۡ  تَنۡکِصُوۡنَ ﴿ۙ۶۶﴾', 'میری آیتیں تمکو پڑھ پڑھ کر سنائی جاتی تھیں اور تم الٹے پاؤں پھر پھر جاتے تھے۔', 'تم کو سنائی جاتی تھیں میری آیتیں تو تم ایڑیوں پر الٹے بھاگتے تھے۔', 'Indeed My Verses used to be recited to you, but you used to turn back on your heels (denying them, and with hatred to listen to them).', 'My verses used to be recited to you, but you used to turn back on your heels'),
(2740, 23, 67, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'مُسۡتَکۡبِرِیۡنَ ٭ۖ بِہٖ سٰمِرًا تَہۡجُرُوۡنَ ﴿۶۷﴾', 'ان سے سرکشی کرتے گویا ایک قصہ گو کو چھوڑ کر چلے جاتے تھے۔', 'اس سے تکبر کر کے [۷۱] ایک قصہ گو کو چھوڑ کر چلے گئے [۷۲]', 'In pride (they Quraish pagans and polytheists of Makkah used to feel proud that they are the dwellers of Makkah sanctuary Haram), talking evil about it (the Quran) by night.', 'in arrogance, making it a subject of tales at night, talking nonsense (about it).”'),
(2741, 23, 68, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اَفَلَمۡ  یَدَّبَّرُوا الۡقَوۡلَ اَمۡ  جَآءَہُمۡ  مَّا لَمۡ یَاۡتِ  اٰبَآءَہُمُ  الۡاَوَّلِیۡنَ ﴿۫۶۸﴾', 'کیا انہوں نے اس کلام میں غور نہیں کیا یا انکے پاس کوئی ایسی چیز آئی ہے جو انکے اگلے باپ دادوں کے پاس نہیں آئی تھی۔', 'سو کیا انہوں نے دھیان نہیں کیا اس کلام میں [۷۳] یا آئی ہے ان کے پاس ایسی چیز جو نہ تھی ان کے پہلے باپ دادوں کے پاس [۷۴]', 'Have they not pondered over the Word (of Allah, i.e. what is sent down to the Prophet SAW), or has there come to them what had not come to their fathers of old?', 'Then, is it that they did not ponder over the Word (of Allah), or there has come to them something that did not come to their forefathers?'),
(2742, 23, 69, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اَمۡ لَمۡ یَعۡرِفُوۡا رَسُوۡلَہُمۡ فَہُمۡ لَہٗ مُنۡکِرُوۡنَ ﴿۫۶۹﴾', 'یا یہ اپنے پیغمبر کو جانتے پہچانتے نہیں اس وجہ سے انکو نہیں مانتے؟', 'یا پہچانا نہیں انہوں نے اپنے پیغام لانے والوں کو سو وہ اس کو اوپرا سمجھتے ہیں [۷۵]', 'Or is it that they did not recognize their Messenger (Muhammad SAW) so they deny him?', 'Or did they not recognize their messenger and therefore they denied him?'),
(2743, 23, 70, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اَمۡ یَقُوۡلُوۡنَ بِہٖ جِنَّۃٌ ؕ بَلۡ جَآءَہُمۡ بِالۡحَقِّ  وَ  اَکۡثَرُہُمۡ  لِلۡحَقِّ  کٰرِہُوۡنَ ﴿۷۰﴾', 'کیا یہ کہتے ہیں کہ اسے جنون ہے نہیں بلکہ وہ انکے پاس حق کو لے کر آئے ہیں اور ان میں سے اکثر حق کو ناپسند کرتے ہیں۔', 'یا کہتے ہیں ان کو سودا ہے کوئی نہیں وہ تو لایا ہے ان کے پاس سچی باتے اور ان بہتوں کو سچی بات بری لگتی ہے [۷۶]', 'Or say they: \"There is madness in him?\" Nay, but he brought them the truth (i.e. \"(A) Tauheed: Worshipping Allah Alone in all aspects (B) The Quran (C) The religion of Islam,\") but most of them (the disbelievers) are averse to the truth.', 'Or do they say, “He is suffering from madness?” No, but he has come to them with truth, but it is the truth that most of them dislike.'),
(2744, 23, 71, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ لَوِ اتَّبَعَ الۡحَقُّ اَہۡوَآءَہُمۡ لَفَسَدَتِ السَّمٰوٰتُ وَ الۡاَرۡضُ وَ مَنۡ فِیۡہِنَّ ؕ بَلۡ اَتَیۡنٰہُمۡ بِذِکۡرِہِمۡ فَہُمۡ عَنۡ ذِکۡرِہِمۡ مُّعۡرِضُوۡنَ ﴿ؕ۷۱﴾', 'اور اگر معبود برحق انکی خواہشوں پر چلنے لگے تو آسمان اور زمین اور جو ان میں ہے سب درہم برہم ہو جائیں بلکہ ہم نے انکے پاس انکی نصیحت کی کتاب پہنچا دی ہے اور یہ اپنی کتاب نصیحت سے منہ پھیر رہے ہیں۔', 'اور اگر سچا رب چلے ان کی خوشی پر تو خراب ہو جائیں آسمان اور زمین اور جو کوئی ان میں ہے [۷۷] کوئی نہیں ہم \nنے پہنچائی ہے ان کو ان کی نصیحت [۷۸] سو وہ اپنی نصیحت کو دھیان نہیں کرتے [۷۹]', 'And if the truth had been in accordance with their desires, verily, the heavens and the earth, and whosoever is therein would have been corrupted! Nay, We have brought them their reminder, but they turn away from their reminder.', 'Had the truth followed their desires, the heavens and the earth and all those therein would have fallen in total disorder. However, We have brought to them their advice, but it is their advice that they are averse to.'),
(2745, 23, 72, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اَمۡ  تَسۡـَٔلُہُمۡ خَرۡجًا فَخَرَاجُ رَبِّکَ خَیۡرٌ ٭ۖ وَّ  ہُوَ  خَیۡرُ  الرّٰزِقِیۡنَ ﴿۷۲﴾', 'کیا تم ان سے تبلیغ کے صلے میں کچھ مال مانگتے ہو۔ تو تمہارے پروردگار کا دیا ہوا مال بہت اچھا ہے اور وہ سب سے بہتر رزق دینے والا ہے۔', 'یا تو ان سے مانگتا ہے کچھ محصول سو محصول تیرے رب کا بہتر ہے اور وہ ہے بہتر روزی دینے والا [۸۰]', 'Or is it that you (O Muhammad SAW) ask them for some wages? But the recompense of your Lord is better, and He is the Best of those who give sustenance.', 'Or is it that you (O Prophet) demand remuneration from them? But the remuneration from your Lord is best, and He is the best of all givers.'),
(2746, 23, 73, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ  اِنَّکَ لَتَدۡعُوۡہُمۡ  اِلٰی صِرَاطٍ مُّسۡتَقِیۡمٍ ﴿۷۳﴾', 'اور تم تو انکو سیدھے راستے کی طرف بلاتے ہو۔', 'اور تو تو بلاتا ہے ان کو سیدھی راہ پر', 'And certainly, you (O Muhammad SAW) call them to a Straight Path (true religion Islamic Monotheism).', 'Surely you are inviting them to a straight path,'),
(2747, 23, 74, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ اِنَّ الَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِالۡاٰخِرَۃِ عَنِ الصِّرَاطِ لَنٰکِبُوۡنَ ﴿۷۴﴾', 'اور جو لوگ آخرت پر ایمان نہیں لاتے وہ رستے سے الگ ہو رہے ہیں۔', 'اور جو لوگ نہیں مانتے آخرت کو راہ سے ٹیڑھے ہو گئے ہیں [۸۱]', 'And verily, those who believe not in the Hereafter are indeed deviating far astray from the Path (true religion Islamic Monotheism).', 'and those who do not believe in the Hereafter are surely the deviators from the Path.'),
(2748, 23, 75, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ لَوۡ  رَحِمۡنٰہُمۡ وَ کَشَفۡنَا مَا بِہِمۡ مِّنۡ ضُرٍّ  لَّلَجُّوۡا فِیۡ طُغۡیَانِہِمۡ یَعۡمَہُوۡنَ ﴿۷۵﴾', 'اور اگر ہم ان پر رحم کریں اور جو تکلیفیں انکو پہنچ رہی ہیں وہ دور کر دیں تو یہ اپنی سرکشی پر اڑے رہیں اور بھٹکتے پھریں۔', 'اور اگر ہم ان پر رحم کریں اور کھول دیں جو تکلیف پہنچی ان کو تو بھی برابر لگے رہیں گے اپنی شرارت میں بہکےہوئے [۸۲]', 'And though We had mercy on them and removed the distress which is on them, still they would obstinately persist in their transgression, wandering blindly.', 'And if We have mercy on them and remove whatever distress they have, they would still persist obstinately in their rebellion, wandering blindly (in disbelief).'),
(2749, 23, 76, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ لَقَدۡ اَخَذۡنٰہُمۡ  بِالۡعَذَابِ فَمَا اسۡتَکَانُوۡا لِرَبِّہِمۡ  وَ مَا یَتَضَرَّعُوۡنَ ﴿۷۶﴾', 'اور ہم نے انکو عذاب میں بھی پکڑا تو بھی انہوں نے اللہ کے آگے عاجزی نہ کی اور یہ عاجزی کرتے ہی نہیں۔', 'اور ہم نے پکڑا تھا ان کو آفت میں پھر نہ عاجزی کی اپنے رب کے آگے اور نہ گڑگڑائے [۸۳]', 'And indeed We seized them with punishment, but they humbled not themselves to their Lord, nor did they invoke (Allah) with submission to Him.', 'We have already seized them with punishment, but they did not turn humble to their Lord, nor do they supplicate in humility,'),
(2750, 23, 77, 4, 4, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'حَتّٰۤی  اِذَا  فَتَحۡنَا عَلَیۡہِمۡ  بَابًا ذَا عَذَابٍ شَدِیۡدٍ   اِذَا  ہُمۡ  فِیۡہِ  مُبۡلِسُوۡنَ ﴿٪۷۷﴾', 'یہاں تک کہ جب ہم نے ان پر عذاب شدید کا دروازہ کھول دیا تو اس وقت وہاں ناامید ہو گئے۔', 'یہاں تک کہ جب کھول دیں ہم ان پر دروازہ ایک سخت آفت کا تب اس میں ان کی آس ٹوٹے گی [۸۴]', 'Until, when We open for them the gate of severe punishment, then lo! They will be plunged into destruction with deep regrets, sorrows and in despair.', 'until when We will open against them the door of a severe punishment, they will be taken aback in despair.'),
(2751, 23, 78, 5, 5, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ ہُوَ الَّذِیۡۤ  اَنۡشَاَ لَکُمُ السَّمۡعَ وَ الۡاَبۡصَارَ وَ الۡاَفۡـِٕدَۃَ ؕ قَلِیۡلًا مَّا تَشۡکُرُوۡنَ ﴿۷۸﴾', 'اور وہی تو ہے جس نے تمہارے کان اور آنکھیں اور دل بنائے۔ لیکن تم کم ہی شکر کرتے ہو۔', 'اور اسی نے بنا دئے تمہارےکان اور آنکھیں اور دل تم بہت تھوڑا حق مانتے ہو [۸۵]', 'It is He, Who has created for you (the sense of) hearing (ears), sight (eyes), and hearts (understanding). Little thanks you give.', 'He is the One who created for you ears and eyes and hearts. Little you are grateful.'),
(2752, 23, 79, 5, 5, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ ہُوَ الَّذِیۡ ذَرَاَکُمۡ فِی الۡاَرۡضِ وَ اِلَیۡہِ  تُحۡشَرُوۡنَ  ﴿۷۹﴾', 'اور وہی تو ہے جس نے تمکو زمین میں پیدا کیا اور اسی کی طرف تم سب جمع ہو کر جاؤ گے۔', 'اور اسی نے تم کو پھیلا رکھا ہے زمین میں اور اسی کی طرف جمع ہو کر جاؤ گے [۸۶]', 'And it is He Who has created you on the earth, and to Him you shall be gathered back.', 'And He is the One who created you on the earth, and it is He unto whom you will be gathered together.'),
(2753, 23, 80, 5, 5, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ ہُوَ الَّذِیۡ یُحۡیٖ وَ یُمِیۡتُ وَ لَہُ اخۡتِلَافُ الَّیۡلِ وَ النَّہَارِ ؕ اَفَلَا تَعۡقِلُوۡنَ ﴿۸۰﴾', 'اور وہی ہے جو زندگی بخشتا اور موت دیتا ہے اور رات اور دن کا بدلتے رہنا اسی کا تصرف ہے کیا تم سمجھتے نہیں؟', 'اور وہی ہے جلاتا اور مارتا اور اسی کا کام ہے بدلنا رات اور دن کا سو کیا تم کو سمجھ نہیں [۸۷]', 'And it is He Who gives life and causes death, and His is the alternation of night and day. Will you not then understand?', 'And He is the One who gives life and brings death, and it is He who controls the alternation of night and day. So, do you not understand?'),
(2754, 23, 81, 5, 5, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'بَلۡ  قَالُوۡا مِثۡلَ  مَا قَالَ  الۡاَوَّلُوۡنَ ﴿۸۱﴾', 'بات یہ ہے کہ جو بات اگلے کافر کہتے تھے اسی طرح کی بات یہ کہتے ہیں۔', 'کوئی بات نہیں یہ تو وہی کہہ رہے ہیں جیسا کہا کرتے تھے  پہلے لوگ', 'Nay, but they say the like of what the men of old said.', 'But they say as the earlier people had said.'),
(2755, 23, 82, 5, 5, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'قَالُوۡۤا ءَ اِذَا مِتۡنَا وَ کُنَّا تُرَابًا وَّ عِظَامًا ءَ اِنَّا  لَمَبۡعُوۡثُوۡنَ ﴿۸۲﴾', 'کہتے ہیں کہ جب ہم مر جائیں گے اور مٹی ہو جائیں گے اور ہڈیوں کے سوا کے سوا کچھ نہ رہے گا تو کیا ہم پھر اٹھائے جائیں گے؟', 'کہتے ہیں کیا جب ہم مر گئے اور ہو گئے مٹی اور ہڈیاں کیا ہم کو زندہ ہو کر اٹھنا ہے', 'They said: \"When we are dead and have become dust and bones, shall we be resurrected indeed?', 'They said, “Is it that, when we will die and become dust and bones - is it that we will be raised again?'),
(2756, 23, 83, 5, 5, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'لَقَدۡ وُعِدۡنَا نَحۡنُ وَ اٰبَآؤُنَا ہٰذَا مِنۡ قَبۡلُ اِنۡ ہٰذَاۤ  اِلَّاۤ  اَسَاطِیۡرُ الۡاَوَّلِیۡنَ ﴿۸۳﴾', 'یہ وعدہ ہم سے اور ہم سے پہلے ہمارے باپ دادا سے بھی ہوتا چلا آیا ہے اجی یہ تو صرف اگلے لوگوں کی کہانیاں ہیں۔', 'وعدہ دیا جاتا ہے ہم کو اور ہمارے باپ دادوں کو یہی پہلے سے اور کچھ بھی نہیں یہ نقلیں ہیں پہلوں کی [۸۸]', '\"Verily, this we have been promised, we and our fathers before (us)! This is only the tales of the ancients!\"', 'This is what has been promised to us and to our fathers before. It is nothing but the tales of the ancients.”'),
(2757, 23, 84, 5, 5, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'قُلۡ لِّمَنِ الۡاَرۡضُ وَ مَنۡ فِیۡہَاۤ  اِنۡ  کُنۡتُمۡ  تَعۡلَمُوۡنَ ﴿۸۴﴾', 'کہو کہ اگر تم جانتے ہو تو بتاؤ کہ زمین اور جو کچھ زمین میں ہے سب کس کا مال ہے۔', 'تو کہہ کس کی ہے زمین اور جو کوئی اس میں ہے بتاؤ اگر تم جانتے ہو', 'Say: \"Whose is the earth and whosoever is therein? If you know!\"', 'Say, “Whose is the earth and all those therein if you have knowledge?”'),
(2758, 23, 85, 5, 5, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'سَیَقُوۡلُوۡنَ  لِلّٰہِ ؕ قُلۡ  اَفَلَا  تَذَکَّرُوۡنَ ﴿۸۵﴾', 'جھٹ بول اٹھیں گے کہ اللہ کا۔ کہو کہ پھر تم سوچتے کیوں نہیں۔', 'اب کہیں گے سب کچھ اللہ کا ہے تو کہہ پھر تم سوچتے نہیں [۸۹]', 'They will say: \"It is Allahs!\" Say: \"Will you not then remember?\"', 'They will say, “Allah’s.” Say, “Would you still pay no heed?'),
(2759, 23, 86, 5, 5, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'قُلۡ مَنۡ رَّبُّ السَّمٰوٰتِ السَّبۡعِ وَ رَبُّ الۡعَرۡشِ الۡعَظِیۡمِ ﴿۸۶﴾', 'ان سے پوچھو کہ سات آسمانوں کا کون مالک ہے اور عرش عظیم کا کون مالک ہے؟', 'تو کہہ کون ہے مالک ساتوں آسمان کا اور مالک اس بڑے تخت کا', 'Say: \"Who is (the) Lord of the seven heavens, and (the) Lord of the Great Throne?\"', 'Say, “Who is the Lord of the seven heavens and the Lord of the Great Throne?”'),
(2760, 23, 87, 5, 5, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'سَیَقُوۡلُوۡنَ  لِلّٰہِ ؕ قُلۡ  اَفَلَا تَتَّقُوۡنَ ﴿۸۷﴾', 'بیساختہ کہدیں گے کہ یہ چیزیں اللہ ہی کی ہیں کہو کہ پھر تم ڈرتے کیوں نہیں۔', 'اب بتائیں گے اللہ کو تو کہہ پھر تم ڈرتے نہیں [۹۰]', 'They will say: \"Allah.\" Say: \"Will you not then fear Allah (believe in His Oneness, obey Him, believe in the Resurrection and Recompense for each and every good or bad deed).\"', 'They will say, “(All this belongs) to Allah”. Say, “Would you still not fear Allah?”'),
(2761, 23, 88, 5, 5, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'قُلۡ مَنۡۢ بِیَدِہٖ مَلَکُوۡتُ کُلِّ شَیۡءٍ وَّ ہُوَ یُجِیۡرُ وَ لَا یُجَارُ عَلَیۡہِ  اِنۡ کُنۡتُمۡ تَعۡلَمُوۡنَ ﴿۸۸﴾', 'کہو کہ اگر تم جانتے ہو تو بتاؤ کہ وہ کون ہے جس کے ہاتھ میں ہر چیز کی بادشاہی ہے اور وہ پناہ دیتا ہے اور اسکے مقابل کوئی کسی کو پناہ نہیں دے سکتا۔', 'تو کہہ کس کے ہاتھ میں ہے حکومت ہر چیز کی اور وہ بچا لیتا ہے اور اس سے کوئی بچا نہیں سکتا بتاؤ اگر تم جانتے ہو', 'Say \"In Whose Hand is the sovereignty of everything (i.e. treasures of each and everything)? And He protects (all), while against Whom there is no protector, (i.e. if Allah saves anyone none can punish or harm him, and if Allah punishes or harms anyone none can save him), if you know.\" (Tafsir Al-Qurtubee, Vol. 12, Page 145)', 'Say, “Who is the One in whose hand lies the kingdom of every thing and who gives protection, and no protection can be given against him, if you have knowledge?”'),
(2762, 23, 89, 5, 5, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'سَیَقُوۡلُوۡنَ لِلّٰہِ ؕ قُلۡ فَاَنّٰی تُسۡحَرُوۡنَ ﴿۸۹﴾', 'فوراً کہدیں گے کہ ایسی بادشاہی تو اللہ ہی کی ہے کہو کہ پھر تم پر جادو کہاں سے پڑ جاتا ہے۔', 'اب بتائیں گے اللہ کو [۹۱] تو کہہ پھر کہاں سے تم پر جادو آ پڑتا ہے [۹۲]', 'They will say: \"(All that belongs) to Allah.\" Say: \"How then are you deceived and turn away from the truth?\"', 'They will say, “(All this belongs) to Allah.” Say, “Then by which magic are you drawn crazy?”'),
(2763, 23, 90, 5, 5, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'بَلۡ اَتَیۡنٰہُمۡ بِالۡحَقِّ وَ  اِنَّہُمۡ  لَکٰذِبُوۡنَ ﴿۹۰﴾', 'بات یہ ہے کہ ہم نے انکے پاس حق پہنچا دیا ہے اور یہ جو بت پرستی کئے جاتے ہیں بیشک جھوٹے ہیں۔', 'کوئی نہیں ہم نے ان کو پہنچایا سچ اور وہ البتہ جھوٹے ہیں [۹۳]', 'Nay, but We have brought them the truth (Islamic Monotheism), and verily, they (disbelievers) are liars.', 'The fact is that We have brought to them The Truth, and they are absolute liars.'),
(2764, 23, 91, 5, 5, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'مَا اتَّخَذَ اللّٰہُ مِنۡ وَّلَدٍ وَّ مَا کَانَ مَعَہٗ مِنۡ  اِلٰہٍ  اِذًا  لَّذَہَبَ  کُلُّ   اِلٰہٍۭ  بِمَا خَلَقَ وَ لَعَلَا بَعۡضُہُمۡ عَلٰی بَعۡضٍ ؕ سُبۡحٰنَ  اللّٰہِ عَمَّا یَصِفُوۡنَ ﴿ۙ۹۱﴾', 'اللہ نے نہ تو کسی کو اپنا بیٹا بنایا ہے اور نہ اسکے ساتھ کوئی اور معبود ہے ایسا ہوتا تو ہر معبود اپنی اپنی مخلوقات کو لے کر چل دیتا اور ایک دوسرے پر چڑھ دوڑتا۔ یہ لوگ جو کچھ اللہ کے بارے میں بیان کرتے ہیں اللہ اس سے پاک ہے۔', 'اللہ نے کوئی بیٹا نہیں کیا اور نہ اس کے ساتھ کسی کا حکم چلے یوں ہوتا تو لیجاتا ہر حکم والا اپنی بنائی چیز کو اور چڑھائی کرتا ایک پر ایک [۹۴] اللہ نرالا (پاک)  ہے ان کی بتلائی باتوں سے [۹۵]', 'No son (or offspring or children) did Allah beget, nor is there any ilah (god) along with Him; (if there had been many gods), behold, each god would have taken away what he had created, and some would have tried to overcome others! Glorified be Allah above all that they attribute to Him!', 'Allah has not taken a son to Himself, nor was there any god with Him. Had there been so, every god would have taken away what he created, and each one of them would have been aggressive against the other. Pure is Allah from what they describe.'),
(2765, 23, 92, 5, 5, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'عٰلِمِ الۡغَیۡبِ وَ الشَّہَادَۃِ  فَتَعٰلٰی عَمَّا یُشۡرِکُوۡنَ ﴿٪۹۲﴾', 'وہ پوشیدہ اور ظاہر کو جانتا ہے اور مشرک جو اسکے ساتھ شریک ٹھہراتے ہیں اسکی شان اس سے بلند ہے۔', 'جاننے والا چھپے اور کھلے کا وہ بہت اوپر ہے اس سے جسکو یہ شریک بتلاتے ہیں [۹۶]', 'All-Knower of the unseen and the seen! Exalted be He over all that they associate as partners to Him!', 'He is the Knower of the hidden and the manifest. So, He is far higher than their ascribing of partners to Him.'),
(2766, 23, 93, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'قُلۡ  رَّبِّ   اِمَّا تُرِیَنِّیۡ  مَا یُوۡعَدُوۡنَ ﴿ۙ۹۳﴾', 'اے نبی کہو کہ اے پروردگار جس عذاب کا ان کفار سے وعدہ ہوا ہے اگر تو میری زندگی میں ان پر نازل کر کے مجھے بھی دکھائے۔', 'تو کہہ اے رب اگر تو دکھانے لگے مجھ کو جو ان سے وعدہ ہوا ہے', 'Say (O Muhammad SAW): \" My Lord! If You would show me that with which they are threatened (torment),', '(O prophet) say (in prayer), “O my Lord, if You are to show me (in my life) that (punishment) which they (the infidels) are threatened with,'),
(2767, 23, 94, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'رَبِّ فَلَا تَجۡعَلۡنِیۡ  فِی الۡقَوۡمِ الظّٰلِمِیۡنَ ﴿۹۴﴾', 'تو اے پروردگار مجھے اس سے محفوظ رکھیو اور ان ظالموں میں شامل نہ کیجیو۔', 'تو اے رب مجھ کو نہ کریو ان گنہگار لوگوں میں [۹۷]', '\"My Lord! Then (save me from Your Punishment), and put me not amongst the people who are the Zalimoon (polytheists and wrong-doing).\"', 'then, my Lord, do not place me among the wrongdoing people.”'),
(2768, 23, 95, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ اِنَّا عَلٰۤی  اَنۡ نُّرِیَکَ مَا نَعِدُہُمۡ لَقٰدِرُوۡنَ ﴿۹۵﴾', 'اور جو وعدہ ہم ان سے کر رہے ہیں ہم تمکو دکھا کر ان پر نازل کرنے پر قادر ہیں۔', 'اور ہم کو قدرت ہے کہ تجھ کو دکھلا دیں جو ان سےوعدہ کر دیا ہے', 'And indeed We are Able to show you (O Muhammad SAW) that with which We have threatened them.', 'And of course, We do have the power to show you that with which We have threatened them.'),
(2769, 23, 96, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اِدۡفَعۡ  بِالَّتِیۡ  ہِیَ اَحۡسَنُ السَّیِّئَۃَ ؕ نَحۡنُ  اَعۡلَمُ  بِمَا یَصِفُوۡنَ ﴿۹۶﴾', 'اور بری بات کے جواب میں ایسی بات کہو جو نہایت اچھی ہو اور یہ جو کچھ بیان کرتے ہیں ہمیں خوب معلوم ہے۔', 'بری بات کے جواب میں وہ کہہ جو بہتر ہے ہم خوب جانتے ہیں جو یہ بتاتے ہیں [۹۸]', 'Repel evil with that which is better. We are Best-Acquainted with the things they utter.', 'Repel evil with that which is best. We are well aware of what they describe.'),
(2770, 23, 97, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ قُلۡ رَّبِّ اَعُوۡذُ بِکَ مِنۡ ہَمَزٰتِ الشَّیٰطِیۡنِ ﴿ۙ۹۷﴾', 'اور کہو کہ اے پروردگار میں شیطانوں کے وسوسوں سے تیری پناہ مانگتا ہوں۔', 'اور کہہ اے رب میں تیری پناہ چاہتا ہوں شیطان کی چھیڑ سے [۹۹]', 'And say: \"My Lord! I seek refuge with You from the whisperings (suggestions) of the Shayatin (devils).', 'And say, “My Lord, I seek refuge in You from the strokes of the satans (devils),'),
(2771, 23, 98, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ  اَعُوۡذُ  بِکَ رَبِّ اَنۡ یَّحۡضُرُوۡنِ ﴿۹۸﴾', 'اور اے پروردگار اس سے بھی تیری پناہ مانگتا ہوں کہ وہ میرے پاس آ موجود ہوں۔', 'اور پناہ تیری چاہتا ہوں اے رب اس سے کہ میرے پاس آئیں [۱۰۰]', '\"And I seek refuge with You, My Lord! lest they may attend (or come near) me.\"', 'and I seek refuge in You, my Lord, even from their coming near me.”'),
(2772, 23, 99, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'حَتّٰۤی  اِذَا جَآءَ   اَحَدَہُمُ  الۡمَوۡتُ قَالَ رَبِّ  ارۡجِعُوۡنِ ﴿ۙ۹۹﴾', 'یہ لوگ اسی طرح غفلت میں رہیں گے یہاں تک کہ جب ان میں سے کسی کے پاس موت آ جائے گی تو کہے گا کہ اے پروردگار مجھے پھر دنیا میں واپس بھیج دے۔', 'یہاں تک کہ جب پہنچے ان میں کسی کو موت کہے گا اے رب مجھ کو پھر بھیجدو', 'Until, when death comes to one of them (those who join partners with Allah), he says: \"My Lord! Send me back,', '(The infidels go on doing their misdeeds) until when death comes to one of them, he will say, “My Lord send me back,'),
(2773, 23, 100, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'لَعَلِّیۡۤ   اَعۡمَلُ صَالِحًا فِیۡمَا تَرَکۡتُ کَلَّا ؕ اِنَّہَا  کَلِمَۃٌ  ہُوَ قَآئِلُہَا ؕ وَ مِنۡ وَّرَآئِہِمۡ بَرۡزَخٌ   اِلٰی  یَوۡمِ  یُبۡعَثُوۡنَ ﴿۱۰۰﴾', 'تاکہ میں اس میں جسے چھوڑ آیا ہوں نیک کام کیا کروں ہرگز نہیں یہ ایک ایسی بات ہے کہ وہ اسے زبان سے کہہ رہا ہو گا اور اسکے ساتھ عمل نہیں ہو گا اور انکے پیچھے برزخ ہے جہان وہ اس دن تک کہ دوبارہ اٹھائے جائیں گے رہیں گے۔', 'شاید کچھ میں بھلا کام کر لوں اس میں جو پیچھے چھوڑ آیا [۱۰۱] ہر گز نہیں یہ ایک بات ہے کہ وہی کہتا ہے [۱۰۲] اور ان کے پیچھے پردہ ہے اس دن تک کہ اٹھائے جائیں [۱۰۳]', '\"So that I may do good in that which I have left behind!\" No! It is but a word that he speaks, and behind them is Barzakh (a barrier) until the Day when they will be resurrected.', 'so that I may act righteously in that (world) which I have left behind.” Never! It is simply a word he utters, and in front of such people there is a barrier till the day when they will be resurrected.'),
(2774, 23, 101, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'فَاِذَا نُفِخَ فِی الصُّوۡرِ فَلَاۤ  اَنۡسَابَ بَیۡنَہُمۡ  یَوۡمَئِذٍ  وَّ  لَا  یَتَسَآءَلُوۡنَ ﴿۱۰۱﴾', 'پھر جب صور پھونکا جائے گا تو نہ تو ان میں قرابتیں رہیں گی اور نہ ایک دوسرے کو پوچھیں گے۔', 'پھر جب پھونک ماریں صور میں تو نہ قرابتیں ہیں ان میں اس دن اور نہ ایک دوسرے کو پوچھے [۱۰۴]', 'Then, when the Trumpet is blown, there will be no kinship among them that Day, nor will they ask of one another.', 'Thereafter, when the Sūr (the trumpet) is blown, no ties of kinship will remain between them any more, nor will they inquire about one another.'),
(2775, 23, 102, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'فَمَنۡ ثَقُلَتۡ مَوَازِیۡنُہٗ  فَاُولٰٓئِکَ ہُمُ الۡمُفۡلِحُوۡنَ ﴿۱۰۲﴾', 'تو جنکے اعمال کے بوجھ بھاری ہوں گے تو وہی کامیاب ہیں۔', 'سو جسکی بھاری ہوئی تول تو وہی لوگ کام لے نکلے', 'Then, those whose scales (of good deeds) are heavy, - these, they are the successful.', 'So, the one whose scales (of good deeds) turn out to be heavy, then such people are the successful ones,'),
(2776, 23, 103, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ مَنۡ خَفَّتۡ مَوَازِیۡنُہٗ  فَاُولٰٓئِکَ الَّذِیۡنَ خَسِرُوۡۤا اَنۡفُسَہُمۡ فِیۡ جَہَنَّمَ خٰلِدُوۡنَ ﴿۱۰۳﴾ۚ', 'اور جنکے بوجھ ہلکے ہوں گے وہ وہ لوگ ہیں جنہوں نے اپنے آپکو خسارے میں ڈالا ہمیشہ دوزخ میں رہیں گے۔', 'اور جس کی ہلکی نکلی تول سو وہی لوگ ہیں جو ہار بیٹھے اپنی جان دوزخ ہی میں رہا کریں گے', 'And those whose scales (of good deeds) are light, they are those who lose their ownselves, in Hell will they abide.', 'and the one whose scales turn out to be light, then such people are the ones who harmed their own selves; in Jahannam (Hell) they are to remain for ever.'),
(2777, 23, 104, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'تَلۡفَحُ وُجُوۡہَہُمُ النَّارُ وَ ہُمۡ فِیۡہَا کٰلِحُوۡنَ ﴿۱۰۴﴾', 'آگ انکے چہروں کو جھلس دے گی اور وہ اس میں بدشکل ہو رہے ہوں گے۔', 'جھلس دے گی انکے منہ کو آگ اور وہ اس میں بد شکل ہو رہے ہوں گے [۱۰۵]', 'The Fire will burn their faces, and therein they will grin, with displaced lips (disfigured).', 'Fire will scorch their faces, and they will be disfigured therein.'),
(2778, 23, 105, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اَلَمۡ تَکُنۡ اٰیٰتِیۡ تُتۡلٰی عَلَیۡکُمۡ فَکُنۡتُمۡ بِہَا تُکَذِّبُوۡنَ ﴿۱۰۵﴾', 'کیا تمکو میری آیتیں پڑھ کر نہیں سنائی جاتی تھیں پھر تم تو انکو جھٹلائے ہی جاتے تھے۔', 'کیا تم کو سنائی نہ تھیں ہماری آیتیں پھر تم ان کو جھٹلاتے تھے [۱۰۶]', '\"Were not My Verses (this Quran) recited to you, and then you used to deny them?\"', '(It will be said to such people), “Were My verses not used to be recited to you and you used to reject them?”'),
(2779, 23, 106, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'قَالُوۡا رَبَّنَا غَلَبَتۡ عَلَیۡنَا شِقۡوَتُنَا وَ کُنَّا قَوۡمًا ضَآلِّیۡنَ ﴿۱۰۶﴾', 'وہ کہیں گے اے ہمارے پروردگار ہم پر ہماری کم بختی غالب آ گئ اور ہم رستے سے بھٹک گئے۔', 'بولے اے رب زور کیا ہم پر ہماری کم بختی نے اور رہے ہم لوگ بہکے ہوئے', 'They will say: \"Our Lord! Our wretchedness overcame us, and we were (an) erring people.', 'They will say, “Our Lord, our wretchedness prevailed over us, and we were a people wandering astray.'),
(2780, 23, 107, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'رَبَّنَاۤ اَخۡرِجۡنَا مِنۡہَا فَاِنۡ عُدۡنَا فَاِنَّا ظٰلِمُوۡنَ ﴿۱۰۷﴾', 'اے پروردگار ہمکو اس میں سے نکال دے اگر ہم پھر ایسے کام کریں تو ظالم ہوں گے۔', 'اے ہمارے رب نکال لے ہم کو اس میں سے اگر ہم پھر کریں تو ہم گنہگار [۱۰۷]', '\"Our Lord! Bring us out of this; if ever we return (to evil), then indeed we shall be Zalimoon: (polytheists, oppressors, unjust, and wrong-doers, etc.).\"', 'Our Lord, get us out from here; if we do this again, then of course, we will be transgressors.”'),
(2781, 23, 108, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'قَالَ  اخۡسَـُٔوۡا فِیۡہَا وَ لَا  تُکَلِّمُوۡنِ ﴿۱۰۸﴾', 'فرمائے گا کہ اسی میں ذلت کے ساتھ پڑے رہو اور مجھ سے بات نہ کرو۔', 'فرمایا پڑے رہو پھٹکار ے ہوئے اس میں اور مجھ سے نہ بولو', 'He (Allah) will say: \"Remain you in it with ignominy! And speak you not to Me!\"', 'He (Allah) will say, “Stay in it, humiliated, and do not speak to Me.'),
(2782, 23, 109, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اِنَّہٗ کَانَ فَرِیۡقٌ مِّنۡ عِبَادِیۡ یَقُوۡلُوۡنَ رَبَّنَاۤ  اٰمَنَّا فَاغۡفِرۡ لَنَا وَ ارۡحَمۡنَا وَ اَنۡتَ  خَیۡرُ  الرّٰحِمِیۡنَ ﴿۱۰۹﴾ۚۖ', 'میرے بندوں میں ایک گروہ تھا جو دعا کیا کرتا تھا کہ اے ہمارے پروردگار ہم ایمان لائے تو تو ہم کو بخش دے اور ہم پر رحم فرما اور تو سب سے بہتر رحم کرنے والا ہے۔', 'ایک فرقہ تھا میرے بندوں میں جو کہتے تھے اے رب ہمارے ہم یقین لائے سو معاف کر ہم کو اور رحم کر ہم پر اور تو سب رحم والوں سے بہتر ہے [۱۰۸]', 'Verily! There was a party of My slaves, who used to say: \"Our Lord! We believe, so forgive us, and have mercy on us, for You are the Best of all who show mercy!\"', 'There was indeed a group of My servants who used to say, ‘Our Lord, we adhere to the (true) faith, so forgive us and have mercy upon us, and you are the best of all the merciful.’'),
(2783, 23, 110, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'فَاتَّخَذۡتُمُوۡہُمۡ سِخۡرِیًّا حَتّٰۤی اَنۡسَوۡکُمۡ ذِکۡرِیۡ وَ کُنۡتُمۡ  مِّنۡہُمۡ تَضۡحَکُوۡنَ ﴿۱۱۰﴾', 'تو تم ان سے تمسخر کرتے رہے یہاں تک کہ ان کے پیچھے میری یاد بھی بھول گئے اور تم ہمیشہ ان سے ہنسی کیا کرتے تھے۔', 'پھر تم نے ان کو ٹھٹھوں میں پکڑا یہاں تک کہ بھول گئے انکے پیچھے میری یاد اور تم ان سے ہنستے رہے [۱۰۹]', 'But you took them for a laughingstock, so much so that they made you forget My Remembrance while you used to laugh at them!', 'But you made fun of them, so much so that they caused you to forget My remembrance, and you used to laugh at them.'),
(2784, 23, 111, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اِنِّیۡ جَزَیۡتُہُمُ  الۡیَوۡمَ  بِمَا صَبَرُوۡۤا ۙ اَنَّہُمۡ  ہُمُ  الۡفَآئِزُوۡنَ ﴿۱۱۱﴾', 'آج میں نے انکو ان کے صبر کا بدلہ دیا کہ وہی کامیاب ہو گئے۔', 'میں نے آج دیا ان کو بدلہ انکے صبر کرنے کا کہ وہی ہیں مراد کو پہنچنے والے [۱۱۰]', 'Verily! I have rewarded them this Day for their patience, they are indeed the ones that are successful.', 'Today I have so recompensed them for their observing patience that they are the triumphant.”'),
(2785, 23, 112, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'قٰلَ  کَمۡ  لَبِثۡتُمۡ  فِی الۡاَرۡضِ عَدَدَ  سِنِیۡنَ ﴿۱۱۲﴾', 'اللہ پوچھے گا کہ تم زمین میں کتنے برس رہے؟', 'فرمایا تم کتنی دیر رہے زمین میں برسوں کی گنتی سے', 'He (Allah) will say: \"What number of years did you stay on earth?\"', 'He (Allah) will say (to unbelievers), “How long did you stay on the earth by number of years?”'),
(2786, 23, 113, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'قَالُوۡا لَبِثۡنَا یَوۡمًا اَوۡ بَعۡضَ یَوۡمٍ فَسۡـَٔلِ  الۡعَآدِّیۡنَ ﴿۱۱۳﴾', 'وہ کہیں گے کہ ہم ایک روز یا ایک روز سے بھی کم رہے تھے شمار کرنے والوں سے پوچھ لیجئے۔', 'بولے ہم رہے ایک یا کچھ دن سے کم تو پوچھ لے گنتی والوں سے [۱۱۱]', 'They will say: \"We stayed a day or part of a day. Ask of those who keep account.\"', 'They will say, “We stayed for a day or for a part of a day. So, ask those (angels) who have (exact) calculation.”'),
(2787, 23, 114, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'قٰلَ  اِنۡ لَّبِثۡتُمۡ   اِلَّا  قَلِیۡلًا لَّوۡ اَنَّکُمۡ کُنۡتُمۡ تَعۡلَمُوۡنَ ﴿۱۱۴﴾', 'اللہ فرمائے گا کہ وہاں تم بہت ہی کم رہے۔ کاش تم جانتے ہوتے۔', 'فرمایا تم اس میں بہت نہیں تھوڑا ہی رہے ہو  اگر تم جانتے ہوتے [۱۱۲]', 'He (Allah) will say: \"You stayed not but a little, if you had only known!', 'He will say, “You did not stay but for a little. Would that you had understood (this at that time)!');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(2788, 23, 115, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'اَفَحَسِبۡتُمۡ اَنَّمَا خَلَقۡنٰکُمۡ عَبَثًا وَّ اَنَّکُمۡ   اِلَیۡنَا لَا تُرۡجَعُوۡنَ ﴿۱۱۵﴾', 'کیا تم یہ خیال کرتے ہو کہ ہم نے تمکو بے مقصد پیدا کیا ہے اور یہ کہ تم ہماری طرف لوٹ کر نہیں آؤ گے؟', 'سو کیا تم خیال رکھتے ہو کہ ہم نے تم کو بنایا کھیلنے کو اور تم ہمارے پاس پھر کر نہ آؤ گے [۱۱۳]', '\"Did you think that We had created you in play (without any purpose), and that you would not be brought back to Us?\"', 'So did you think that We created you for nothing, and that you will not be brought back to Us?”'),
(2789, 23, 116, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'فَتَعٰلَی اللّٰہُ  الۡمَلِکُ الۡحَقُّ ۚ لَاۤ  اِلٰہَ   اِلَّا ہُوَ ۚ رَبُّ  الۡعَرۡشِ  الۡکَرِیۡمِ ﴿۱۱۶﴾', 'تو اللہ جو سچا بادشاہ ہے اسکی شان اس سے اونچی ہے۔ اسکے سوا کوئی معبود نہیں وہی عرش کریم کا مالک ہے۔', 'سو بہت اوپر ہے اللہ وہ بادشاہ سچا کوئی حاکم نہیں اس کے سوائے مالک اس عزت کے تخت کا [۱۱۴]', 'So Exalted be Allah, the True King, La ilaha illa Huwa (none has the right to be worshipped but He), the Lord of the Supreme Throne!', 'So, High above all is Allah, the King, the True. There is no god but He, the Lord of the Noble Throne.'),
(2790, 23, 117, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ مَنۡ یَّدۡعُ مَعَ اللّٰہِ  اِلٰـہًا اٰخَرَ ۙ  لَا بُرۡہَانَ لَہٗ بِہٖ ۙ فَاِنَّمَا حِسَابُہٗ عِنۡدَ رَبِّہٖ ؕ اِنَّہٗ  لَا یُفۡلِحُ  الۡکٰفِرُوۡنَ ﴿۱۱۷﴾', 'اور جو شخص اللہ کے ساتھ اور معبود کو پکارتا ہے جسکی اسکے پاس کچھ بھی سند نہیں تو اس کا حساب اسکے رب کے ہاں ہو گا۔ کچھ شک نہیں کہ کافر کامیاب نہیں ہوں گے۔', 'اور جو کوئی پکارے اللہ کے ساتھ دوسرا حاکم جس کی سند نہیں اس کے پاس سو اس کا حساب ہے اس کے رب کے نزدیک [۱۱۵] بیشک بھلا نہ ہو گا منکروں کا', 'And whoever invokes (or worships), besides Allah, any other ilah (god), of whom he has no proof, then his reckoning is only with his Lord. Surely! Al-Kafiroon (the disbelievers in Allah and in the Oneness of Allah, polytheists, pagans, idolaters, etc.) will not be successful.', 'And whoever invokes another god with Allah, while he has no proof for it, his reckoning is only with his Lord. Surely, the infidels will not achieve success.'),
(2791, 23, 118, 6, 6, 18, 'قَدۡ  اَفۡلَحَ ', 'المؤمنون', 'وَ قُلۡ رَّبِّ اغۡفِرۡ وَ ارۡحَمۡ وَ اَنۡتَ خَیۡرُ الرّٰحِمِیۡنَ ﴿٪۱۱۸﴾', 'اور اللہ سے دعا کرو کہ میرے پروردگار مجھے بخش دے اور مجھ پر رحم کر اور تو سب سے بہتر رحم فرمانے والا ہے۔', 'اور تو کہہ اے رب معاف کر اور رحم کر اور تو ہے بہتر سب رحم والوں سے [۱۱۶]', 'And say (O Muhammad SAW): \"My Lord! Forgive and have mercy, for You are the Best of those who show mercy!\"', 'And say (O prophet) “My Lord, grant pardon and have mercy, for you are the best of all the merciful.”'),
(2792, 24, 1, 1, 7, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'سُوۡرَۃٌ  اَنۡزَلۡنٰہَا وَ فَرَضۡنٰہَا وَ اَنۡزَلۡنَا فِیۡہَاۤ  اٰیٰتٍۭ بَیِّنٰتٍ لَّعَلَّکُمۡ  تَذَکَّرُوۡنَ ﴿۱﴾', 'یہ ایک سورہ ہے جسکو ہم نے نازل کیا اور اسکے احکام کو فرض کر دیا اور اس میں صاف صاف آیتیں نازل کیں تاکہ تم یاد رکھو۔', 'یہ ایک سورت ہے کہ ہم نے اتاری اور ذمہ پر لازم کی اور اتاریں اس میں باتیں صاف تاکہ تم یاد رکھو [۱]', '(This is) a Soorah (chapter of the Quran) which We have sent down and which We have enjoined, (ordained its legal laws) and in it We have revealed manifest Ayat (proofs, evidences, verses, lessons, signs, revelations lawful and unlawful things, and set boundries of Islamic Religion), that you may remember.', 'This is a Sūrah We have sent down and enjoined, and sent down in it clear signs, so that you may receive the advice.'),
(2793, 24, 2, 1, 7, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'اَلزَّانِیَۃُ وَ الزَّانِیۡ فَاجۡلِدُوۡا کُلَّ وَاحِدٍ مِّنۡہُمَا مِائَۃَ جَلۡدَۃٍ ۪ وَّ لَا  تَاۡخُذۡکُمۡ بِہِمَا رَاۡفَۃٌ  فِیۡ  دِیۡنِ اللّٰہِ  اِنۡ کُنۡتُمۡ تُؤۡمِنُوۡنَ بِاللّٰہِ وَ الۡیَوۡمِ الۡاٰخِرِ ۚ وَ لۡیَشۡہَدۡ عَذَابَہُمَا طَآئِفَۃٌ مِّنَ الۡمُؤۡمِنِیۡنَ ﴿۲﴾', 'بدکاری کرنے والی عورت اور بدکاری کرنے والا مرد جب انکی بدکاری ثابت ہو جائے تو دونوں میں سے ہر ایک کو سو درے مارو۔ اور اگر تم اللہ اور روز آخر پر ایمان رکھتے ہو  تو اللہ کے قانون کو نافذ کرنے میں تمہیں ان پر ہرگز ترس نہ آئے۔ اور چاہیے کہ انکی سزا کے وقت مسلمانوں کی ایک جماعت بھی موجود ہو۔', 'بدکاری کرنے والی عورت اور مرد سو مارو ہر ایک کو دونوں میں سے سوسو درّے [۲] اور نہ آوے تم کو ان پر ترس اللہ کے حکم چلانے میں اگر تم یقین رکھتے ہو اللہ پر اور پچھلے دن پر [۳] اور دیکھیں ان کا مارنا کچھ لوگ مسلمان [۴]', 'The woman and the man guilty of illegal sexual intercourse, flog each of them with a hundred stripes. Let not pity withhold you in their case, in a punishment prescribed by Allah, if you believe in Allah and the Last Day. And let a party of the believers witness their punishment. (This punishment is for unmarried persons guilty of the above crime but if married persons commit it, the punishment is to stone them to death, according to Allahs Law).', 'The fornicating woman and the fornicating man, flog each one of them with one hundred stripes. No pity for them should prevail upon you in the matter of Allah’s religion, if you really believe in Allah and the Last Day; and a group of believers must witness their punishment.'),
(2794, 24, 3, 1, 7, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'اَلزَّانِیۡ  لَا یَنۡکِحُ  اِلَّا  زَانِیَۃً  اَوۡ  مُشۡرِکَۃً ۫ وَّ الزَّانِیَۃُ  لَا یَنۡکِحُہَاۤ  اِلَّا زَانٍ  اَوۡ مُشۡرِکٌ ۚ وَ حُرِّمَ  ذٰلِکَ عَلَی الۡمُؤۡمِنِیۡنَ ﴿۳﴾', 'بدکار مرد تو بدکار یا مشرک عورت کے سوا کسی سے نکاح نہیں کرتا اور بدکار عورت کو بھی بدکار یا مشرک مرد کے سوا اور کوئی نکاح میں نہیں لاتا اور یہ یعنی بدکار عورت سے نکاح کرنا مومنوں پر حرام ہے۔', 'بدکارمرد نہیں نکاح کرتا مگر عورت بدکار سے یا شرک والی سے اور بدکار عورت سے نکاح نہیں کرتا مگر بدکار مرد یا مشرک [۵] اور یہ حرام ہوا ہے ایمان والوں پر [۶]', 'The adulterer marries not but an adulteress or a Mushrikah and the adulteress none marries her except an adulterer or a Muskrik (and that means that the man who agrees to marry (have a sexual relation with) a Mushrikah (female polytheist, pagan or idolatress) or a prostitute, then surely he is either an adulterer, or a Mushrik (polytheist, pagan or idolater, etc.) And the woman who agrees to marry (have a sexual relation with) a Mushrik (polytheist, pagan or idolater) or an adulterer, then she is either a prostitute or a Mushrikah (female polytheist, pagan, or idolatress, etc.)). Such a thing is forbidden to the believers (of Islamic Monotheism).', 'A man who is fornicator does not (like to) marry but a woman who is a fornicator or a polytheist; and a woman who is a fornicator does not (like to) marry but a man who is a fornicator or a polytheist. And this (i.e. preferring to marry such spouses) has been prohibited for the believers.'),
(2795, 24, 4, 1, 7, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ الَّذِیۡنَ یَرۡمُوۡنَ الۡمُحۡصَنٰتِ ثُمَّ لَمۡ یَاۡتُوۡا بِاَرۡبَعَۃِ  شُہَدَآءَ فَاجۡلِدُوۡہُمۡ ثَمٰنِیۡنَ جَلۡدَۃً  وَّ لَا تَقۡبَلُوۡا لَہُمۡ شَہَادَۃً  اَبَدًا ۚ وَ اُولٰٓئِکَ ہُمُ  الۡفٰسِقُوۡنَ ۙ﴿۴﴾', 'اور جو لوگ پرہیزگار عورتوں کو بدکاری کا عیب لگائیں اور اس پر چار گواہ نہ لائیں تو انکو اسّی درے مارو اور کبھی انکی شہادت قبول نہ کرو اور یہی بدکردار ہیں۔', 'اور جو لوگ عیب لگاتے ہیں حفاظت والیوں کو (پاکدامنوں کو) پھر نہ لائے چار مرد شاہد [۷] تو مارو ان کو اسی درّے اور نہ مانو ان کی گواہی کبھی [۸] اور وہی لوگ ہیں نافرمان [۹]', 'And those who accuse chaste women, and produce not four witnesses, flog them with eighty stripes, and reject their testimony forever, they indeed are the Fasiqoon (liars, rebellious, disobedient to Allah).', 'Those who accuse the chaste women (of fornication), but they do not produce four witnesses, flog them with eighty stripes and do not accept their any evidence any more. They are the sinners,'),
(2796, 24, 5, 1, 7, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'اِلَّا الَّذِیۡنَ تَابُوۡا مِنۡۢ بَعۡدِ ذٰلِکَ وَ اَصۡلَحُوۡا ۚ فَاِنَّ  اللّٰہَ  غَفُوۡرٌ  رَّحِیۡمٌ ﴿۵﴾', 'ہاں جو اسکے بعد توبہ کر لیں اور اپنی حالت سنوار لیں تو اللہ بھی بخشنے والا ہے مہربان ہے۔', 'مگر جنہوں نے توبہ کر لی اس کے پیچھے اور سنور گئے تو اللہ بخشنے والا مہربان ہے [۱۰]', 'Except those who repent thereafter and do righteous deeds, (for such) verily, Allah is Oft-Forgiving, Most Merciful.', 'except those who repent afterwards and mend their ways; then, Allah is All-Forgiving, Very-Merciful.'),
(2797, 24, 6, 1, 7, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ الَّذِیۡنَ یَرۡمُوۡنَ اَزۡوَاجَہُمۡ وَ لَمۡ  یَکُنۡ لَّہُمۡ شُہَدَآءُ  اِلَّاۤ  اَنۡفُسُہُمۡ فَشَہَادَۃُ اَحَدِہِمۡ  اَرۡبَعُ شَہٰدٰتٍۭ بِاللّٰہِ ۙ اِنَّہٗ  لَمِنَ الصّٰدِقِیۡنَ ﴿۶﴾', 'اور جو لوگ اپنی بیویوں پر بدکاری کی تہمت لگائیں اور خود انکے سوا اور گواہ نہ ہوں تو ہر ایک کی شہادت یہ ہے کہ پہلے تو چار بار اللہ کی قسم کھائے کہ بیشک وہ سچا ہے۔', 'اور جو عیب لگائیں اپنی جوروؤں کو [۱۱] اور شاہد نہ ہوں انکے پاس سوائے انکی جان کے تو ایسے شخص کی گواہی کی یہ صورت ہے کہ چار بار گواہی دے اللہ کی قسم کھا کر مقرر وہ شخص سچا ہے', 'And for those who accuse their wives, but have no witnesses except themselves, let the testimony of one of them be four testimonies (i.e. testifies four times) by Allah that he is one of those who speak the truth.', 'Those who accuse their wives (of adultery) while they have no witnesses except their own selves, then the evidence of one of them would be to swear four oaths by Allah that he is truthful,'),
(2798, 24, 7, 1, 7, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ الۡخَامِسَۃُ اَنَّ لَعۡنَتَ اللّٰہِ عَلَیۡہِ  اِنۡ کَانَ مِنَ  الۡکٰذِبِیۡنَ ﴿۷﴾', 'اور پانچویں بار یہ کہے کہ اگر وہ جھوٹا ہو تو اس پر اللہ کی لعنت۔', 'اور پانچویں بار یہ کہ اللہ کی پھٹکار ہو اس شخص پر اگر ہو وہ جھوٹا', 'And the fifth (testimony) (should be) the invoking of the Curse of Allah on him if he be of those who tell a lie (against her).', 'and the fifth (oath) that Allah’s curse be on him if he is one of the liars.'),
(2799, 24, 8, 1, 7, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ یَدۡرَؤُا  عَنۡہَا الۡعَذَابَ اَنۡ تَشۡہَدَ اَرۡبَعَ شَہٰدٰتٍۭ بِاللّٰہِ ۙ اِنَّہٗ لَمِنَ الۡکٰذِبِیۡنَ ۙ﴿۸﴾', 'اور عورت سے سزا کو یہ بات ٹال سکتی ہے کہ وہ پہلے چار بار اللہ کی قسم کھائے کہ بیشک یہ جھوٹا ہے۔', 'اور عورت سے ٹل جائے مار یوں کہ وہ گواہی دے چار گواہی اللہ کی قسم کھا کر مقرر وہ شخص جھوٹا ہے', 'But it shall avert the punishment (of stoning to death) from her, if she bears witness four times by Allah, that he (her husband) is telling a lie.', 'And it will remove the punishment from the woman if she swears four oaths by Allah that he (the accuser husband) is certainly one of the liars,'),
(2800, 24, 9, 1, 7, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ الۡخَامِسَۃَ  اَنَّ غَضَبَ اللّٰہِ عَلَیۡہَاۤ  اِنۡ  کَانَ مِنَ  الصّٰدِقِیۡنَ ﴿۹﴾', 'اور پانچویں دفعہ یوں کہے کہ اگر یہ سچا ہو تو مجھ پر اللہ کا غضب نازل ہو۔', 'اور پانچویں یہ کہ اللہ کا غضب آئے اس عورت پر اگر وہ شخص سچا ہے [۱۲]', 'And the fifth (testimony) should be that the Wrath of Allah be upon her if he (her husband) speaks the truth.', 'and the fifth (oath) that Allah’s wrath be on her if he is one of the truthful.'),
(2801, 24, 10, 1, 7, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ لَوۡ لَا فَضۡلُ اللّٰہِ عَلَیۡکُمۡ  وَ رَحۡمَتُہٗ وَ اَنَّ  اللّٰہَ   تَوَّابٌ  حَکِیۡمٌ ﴿٪۱۰﴾', 'اور اگر تم پر اللہ کا فضل اور اسکی مہربانی نہ ہوتی تو بہت سی خرابیاں پیدا ہو جاتیں۔ اور یہ کہ اللہ توبہ قبول کرنے والا ہے حکیم ہے۔', 'اور اگر نہ ہوتا اللہ کا فضل تمہارے اوپر اور اسکی رحمت اور یہ کہ اللہ معاف کرنے والا ہے حکمتیں جاننے والا تو کیا کچھ نہ ہوتا [۱۳]', 'And had it not been for the Grace of Allah and His Mercy on you (He would have hastened the punishment upon you)! And that Allah is the One Who accepts repentance, the All-Wise.', 'Had it not been for the grace of Allah upon you, and His mercy, and (had it not been) that Allah is Most-Relenting, All-Wise, (you would have faced severe hardships).'),
(2802, 24, 11, 2, 8, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'اِنَّ  الَّذِیۡنَ جَآءُوۡ بِالۡاِفۡکِ عُصۡبَۃٌ مِّنۡکُمۡ ؕ لَا تَحۡسَبُوۡہُ شَرًّا  لَّکُمۡ ؕ بَلۡ ہُوَ خَیۡرٌ  لَّکُمۡ ؕ لِکُلِّ  امۡرِیًٔ  مِّنۡہُمۡ  مَّا اکۡتَسَبَ مِنَ الۡاِثۡمِ ۚ وَ الَّذِیۡ تَوَلّٰی کِبۡرَہٗ   مِنۡہُمۡ  لَہٗ  عَذَابٌ  عَظِیۡمٌ ﴿۱۱﴾', 'جن لوگوں نے یہ بہتان باندھا ہے وہ تم ہی میں سے ایک جماعت ہے اسکو اپنے حق میں برا نہ سمجھنا۔ بلکہ وہ تمہارے لئے اچھا ہے۔ ان میں سے جس شخص نے گناہ کا جتنا حصہ لیا اسکے لئے اتنا وبال ہے اور جس نے ان میں سے اس بہتان کا بڑا بوجھ اٹھایا ہے اسکو بڑا عذاب ہو گا۔', 'جو لوگ لائے ہیں یہ طوفان [۱۴] تمہیں میں ایک جماعت ہیں [۱۵] تم اس کو نہ سمجھو برا اپنے حق میں بلکہ یہ بہتر ہے تمہارے حق میں [۱۶] ہر آدمی کے لئے ان میں سے وہ ہے جتنا اس نے گناہ کمایا اور جس نے اٹھایا ہے اس کا بڑا بوجھ اس کے واسطے بڑا عذاب ہے [۱۷]', 'Verily! Those who brought forth the slander (against Aishah ÑÖì Ç the wife of the Prophet SAW) are a group among you. Consider it not a bad thing for you. Nay, it is good for you. Unto every man among them will be paid that which he had earned of the sin, and as for him among them who had the greater share therein, his will be a great torment.', 'Those who have come up with the false imputation are a gang among you. Do not think it is bad for you; rather, it is good for you. Every one of them is liable for what he earned of the sin. And the one who played the major role in it, for him there is a mighty punishment.'),
(2803, 24, 12, 2, 8, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'لَوۡ لَاۤ اِذۡ سَمِعۡتُمُوۡہُ  ظَنَّ الۡمُؤۡمِنُوۡنَ وَ الۡمُؤۡمِنٰتُ بِاَنۡفُسِہِمۡ خَیۡرًا ۙ وَّ قَالُوۡا ہٰذَاۤ   اِفۡکٌ  مُّبِیۡنٌ ﴿۱۲﴾', 'جب تم نے وہ بات سنی تھی تو مومن مردوں اور عورتوں نے کیوں اپنے دلوں میں نیک گمان نہ کیا۔ اور کیوں نہ کہہ دیا کہ یہ کھلم کھلا بہتان ہے۔', 'کیوں نہ جب تم نے اس کو سنا تھا خیال کیا ہوتا ایمان والے مردوں اور ایمان والی عورتوں نے اپنے لوگوں پر بھلا خیال اور کہا ہوتا یہ صریح طوفان ہے [۱۸]', 'Why then, did not the believers, men and women, when you heard it (the slander) think good of their own people and say: \"This (charge) is an obvious lie?\"', 'Why - when you (O believers) heard of it - did the believing men and the believing women not think well about their own selves, and (why did they not) say, “This is a manifest lie”.'),
(2804, 24, 13, 2, 8, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'لَوۡ لَا جَآءُوۡ عَلَیۡہِ  بِاَرۡبَعَۃِ شُہَدَآءَ ۚ فَاِذۡ لَمۡ یَاۡتُوۡا بِالشُّہَدَآءِ  فَاُولٰٓئِکَ عِنۡدَ  اللّٰہِ   ہُمُ   الۡکٰذِبُوۡنَ ﴿۱۳﴾', 'یہ بہتان لگانے والے اپنی بات کی تصدیق کے لئے چار گواہ کیوں نہ لائے۔ تو جب یہ گواہ نہیں لا سکے تو اللہ کے نزدیک یہی جھوٹے ہیں۔', 'کیوں نہ لائے وہ اس بات پر چار شاہد پھر جب نہ لائے شاہد تو وہ لوگ اللہ کے یہاں وہی ہیں جھوٹے [۱۹]', 'Why did they not produce four witnesses? Since they (the slanderers) have not produced witnesses! Then with Allah they are the liars.', 'Why did they (the accusers) not bring four witnesses to prove this? So, as they did not bring the witnesses, they are the liars in the sight of Allah.'),
(2805, 24, 14, 2, 8, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ لَوۡ لَا فَضۡلُ اللّٰہِ عَلَیۡکُمۡ وَ رَحۡمَتُہٗ فِی الدُّنۡیَا وَ الۡاٰخِرَۃِ  لَمَسَّکُمۡ فِیۡ مَاۤ اَفَضۡتُمۡ  فِیۡہِ  عَذَابٌ عَظِیۡمٌ  ﴿ۚۖ۱۴﴾', 'اور اگر دنیا اور آخرت میں تم پر اللہ کا فضل اور اسکی رحمت نہ ہوتی تو جس شغل میں تم منہمک تھے اسکی وجہ سے تم پر بڑا سخت عذاب نازل ہوتا۔', 'اور اگر نہ ہوتا اللہ کا فضل تم پر اور اسکی رحمت دنیا اور آخرت میں تو تم پر پڑ جاتی اس چرچا کرنے میں کوئی آفت بڑی [۲۰]', 'Had it not been for the Grace of Allah and His Mercy unto you in this world and in the Hereafter, a great torment would have touched you for that whereof you had spoken.', 'Had it not been for the grace of Allah upon you, and His mercy in this world and in the Hereafter, a severe punishment would have reached you for what you indulged in -'),
(2806, 24, 15, 2, 8, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'اِذۡ تَلَقَّوۡنَہٗ  بِاَلۡسِنَتِکُمۡ وَ تَقُوۡلُوۡنَ بِاَفۡوَاہِکُمۡ  مَّا  لَیۡسَ لَکُمۡ  بِہٖ عِلۡمٌ وَّ تَحۡسَبُوۡنَہٗ ہَیِّنًا ٭ۖ وَّ ہُوَ عِنۡدَ اللّٰہِ عَظِیۡمٌ ﴿۱۵﴾', 'جب تم اپنی زبانوں سے اس کا ایک دوسرے سے ذکر کرتے تھے اور اپنے منہ سے ایسی بات کہتے تھے جس کا تمکو کچھ بھی علم نہ تھا اور تم اسے ایک ہلکی بات سمجھتے تھے حالانکہ اللہ کے نزدیک وہ بڑی بھاری بات تھی۔', 'جب لینے لگے تم اس کو اپنی زبانوں پر اور بولنے لگے اپنے منہ سے جس چیز کی تم کو خبر نہیں اور تم سمجھتے ہو اسکو  ہلکی بات اور یہ اللہ کے یہاں بہت بڑی بات ہے [۲۱]', 'When you were propagating it with your tongues, and uttering with your mouths that whereof you had no knowledge, you counted it a little thing, while with Allah it was very great.', 'when you were welcoming it with your tongues, and were saying with your mouths something of which you had no knowledge, and were taking it as a trivial matter, while in the sight of Allah it was grave.'),
(2807, 24, 16, 2, 8, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ لَوۡ لَاۤ  اِذۡ سَمِعۡتُمُوۡہُ  قُلۡتُمۡ مَّا یَکُوۡنُ لَنَاۤ  اَنۡ  نَّتَکَلَّمَ  بِہٰذَا ٭ۖ سُبۡحٰنَکَ ہٰذَا بُہۡتَانٌ عَظِیۡمٌ ﴿۱۶﴾', 'اور جب تم نے اسے سنا تھا تو کیوں نہ کہدیا کہ ہمیں شایاں نہیں کہ ایسی بات زبان پر لائیں۔ پروردگار تو پاک ہے یہ تو بہت بڑا بہتان ہے۔', 'اور کیوں نہ جب تم نے اس کو سنا تھا کہا ہوتا ہم کو نہیں لائق کہ منہ پر لائیں یہ بات اللہ تو پاک ہے یہ تو بڑا بہتان ہے [۲۲]', 'And why did you not, when you heard it, say? \"It is not right for us to speak of this. Glory be to You (O Allah) this is a great lie.\"', 'And why, when you heard of it, did you not say, “It is not for us to speak about this. Pure are You (O Allah). This is a terrible calumny.”'),
(2808, 24, 17, 2, 8, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'یَعِظُکُمُ اللّٰہُ اَنۡ تَعُوۡدُوۡا لِمِثۡلِہٖۤ  اَبَدًا اِنۡ  کُنۡتُمۡ  مُّؤۡمِنِیۡنَ ﴿ۚ۱۷﴾', 'اللہ تمہیں نصیحت کرتا ہے کہ اگر مومن ہو تو پھر کبھی ایسا کام نہ کرنا۔', 'اللہ تم کو سمجھاتا ہے کہ پھر نہ کرو ایسا کام کبھی اگر تم ایمان رکھتے ہو [۲۳]', 'Allah forbids you from it and warns you not to repeat the like of it forever, if you are believers.', 'Allah admonishes you never to repeat something like this, if you are believers.'),
(2809, 24, 18, 2, 8, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ یُبَیِّنُ اللّٰہُ  لَکُمُ الۡاٰیٰتِ ؕ وَ اللّٰہُ عَلِیۡمٌ  حَکِیۡمٌ ﴿۱۸﴾', 'اور اللہ تمہارے سمجھانے کے لئے اپنی آیتیں کھول کھول کر بیان فرماتا ہے اور اللہ جاننے والا ہے حکمت والا ہے۔', 'اور کھولتا ہے اللہ تمہارے واسطے پتے کی باتیں اور اللہ سب جانتا ہے حکمت والا ہے [۲۴]', 'And Allah makes the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) plain to you, and Allah is All-Knowing, All-Wise.', 'Allah makes the signs clear to you, and Allah is All-Knowing, All-Wise.'),
(2810, 24, 19, 2, 8, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'اِنَّ الَّذِیۡنَ یُحِبُّوۡنَ اَنۡ تَشِیۡعَ الۡفَاحِشَۃُ فِی الَّذِیۡنَ اٰمَنُوۡا لَہُمۡ عَذَابٌ اَلِیۡمٌ ۙ فِی الدُّنۡیَا وَ الۡاٰخِرَۃِ ؕ وَ اللّٰہُ  یَعۡلَمُ  وَ  اَنۡتُمۡ  لَا  تَعۡلَمُوۡنَ ﴿۱۹﴾', 'جو لوگ اس بات کو پسند کرتے ہیں کہ مومنوں میں بےحیائی یعنی تہمت بدکاری کی خبر پھیلے انکو دنیا اور آخرت میں دکھ دینے والا عذاب ہو گا اور اللہ جانتا ہے اور تم نہیں جانتے۔', 'جو لوگ چاہتے ہیں کہ چرچا ہو بدکاری کا ایمان والوں میں [۲۵] انکے لئے عذاب ہے دردناک دنیا اور آخرت میں [۲۶] اور اللہ جانتا ہے اور تم نہیں جانتے [۲۷]', 'Verily, those who like that (the crime of) illegal sexual intercourse should be propagated among those who believe, they will have a painful torment in this world and in the Hereafter. And Allah knows and you know not.', 'Surely, those who like that lewdness spreads among the believers, for them there is painful punishment in this world and the Hereafter. Allah knows, and you do not know.'),
(2811, 24, 20, 2, 8, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ لَوۡ لَا فَضۡلُ اللّٰہِ عَلَیۡکُمۡ  وَ  رَحۡمَتُہٗ  وَ  اَنَّ  اللّٰہَ  رَءُوۡفٌ  رَّحِیۡمٌ ﴿٪۲۰﴾', 'اور اگر تم پر اللہ کا فضل اور اسکی رحمت نہ ہوتی تو کیا کچھ نہ ہوتا مگر وہ کریم ہے اور یہ کہ اللہ نہایت مہربان ہے رحیم ہے۔', 'اور اگر نہ ہوتا اللہ کا فضل تم پر اور اسکی رحمت اور یہ کہ اللہ نرمی کرنے والا ہے مہربان تو کیا کچھ نہ ہوتا [۲۸]', 'And had it not been for the Grace of Allah and His Mercy on you, (Allah would have hastened the punishment upon you). And that Allah is full of kindness, Most Merciful.', 'Had it not been for the grace of Allah upon you, and His mercy, and that Allah is Very-Kind, Very-Merciful (you would have been destroyed).'),
(2812, 24, 21, 3, 9, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَتَّبِعُوۡا خُطُوٰتِ الشَّیۡطٰنِ ؕ وَ مَنۡ یَّتَّبِعۡ خُطُوٰتِ الشَّیۡطٰنِ فَاِنَّہٗ یَاۡمُرُ بِالۡفَحۡشَآءِ وَ الۡمُنۡکَرِ ؕ وَ لَوۡ لَا فَضۡلُ اللّٰہِ عَلَیۡکُمۡ وَ رَحۡمَتُہٗ  مَا زَکٰی مِنۡکُمۡ  مِّنۡ  اَحَدٍ  اَبَدًا  ۙ  وَّ لٰکِنَّ  اللّٰہَ یُزَکِّیۡ مَنۡ یَّشَآءُ ؕ وَ اللّٰہُ سَمِیۡعٌ عَلِیۡمٌ ﴿۲۱﴾', 'مومنو! شیطان کے قدموں پر نہ چلنا۔ اور جو شخص شیطان کے قدموں پر چلے گا تو شیطان تو بےحیائی کی باتیں اور برے کام ہی بتائے گا اور اگر تم پر اللہ کا فضل اور اسکی مہربانی نہ ہوتی تو ایک شخص بھی تم میں پاک نہ ہو سکتا مگر اللہ جسکو چاہتا ہے پاک کر دیتا ہے اور اللہ سننے والا ہے جاننے والا ہے۔', 'اے ایمان والو نہ چلو قدموں پر شیطان کے اور جو کوئی چلے گا قدموں پر شیطان کےسو وہ تو یہی بتلائے گا بیحائی اور بری بات [۲۹] اور اگر نہ ہوتا اللہ کا فضل تم پر اور اس کی رحمت تو نہ سنورتا تم میں ایک شخص بھی کبھی و لیکن اللہ سنوارتا ہے جس کو چاہے اور اللہ سب کچھ سنتا جانتا ہے [۳۰]', 'O you who believe! Follow not the footsteps of Shaitan (Satan). And whosoever follows the footsteps of Shaitan (Satan), then, verily he commands Al-Fahsha (i.e. to commit indecency (illegal sexual intercourse, etc.)), and Al-Munkar (disbelief and polytheism (i.e. to do evil and wicked deeds; to speak or to do what is forbidden in Islam, etc.)). And had it not been for the Grace of Allah and His Mercy on you, not one of you would ever have been pure from sins. But Allah purifies (guides to Islam) whom He wills, and Allah is All-Hearer, All-Knower.', 'O you who believe, do not follow the footsteps of Satan. Whoever follows the footsteps of Satan, (should know that) he orders (one to commit) shameful acts and evil deeds. Had it not been for the grace of Allah upon you, and His mercy, not a single person from you would have ever attained purity. But Allah purifies whomsoever He wills. Allah is All-Hearing, All-Knowing.'),
(2813, 24, 22, 3, 9, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ لَا یَاۡتَلِ اُولُوا الۡفَضۡلِ مِنۡکُمۡ وَ السَّعَۃِ  اَنۡ یُّؤۡتُوۡۤا  اُولِی الۡقُرۡبٰی وَ الۡمَسٰکِیۡنَ وَ الۡمُہٰجِرِیۡنَ فِیۡ سَبِیۡلِ اللّٰہِ ۪ۖ وَ لۡیَعۡفُوۡا وَ لۡیَصۡفَحُوۡا ؕ اَلَا تُحِبُّوۡنَ اَنۡ یَّغۡفِرَ اللّٰہُ  لَکُمۡ ؕ وَ اللّٰہُ غَفُوۡرٌ   رَّحِیۡمٌ ﴿۲۲﴾', 'اور جو لوگ تم میں صاحب فضل اور صاحب مال ہیں وہ اس بات کی قسم نہ کھائیں کہ رشتہ داروں اور محتاجوں اور وطن چھوڑ جانے والوں کو کچھ نہیں دیں گے۔ اور انکو چاہیے کہ معاف کر دیں اور درگذر کریں کیا تم پسند نہیں کرتے کہ اللہ تمکو بخش دے؟ اور اللہ تو بخشنے والا ہے مہربان ہے۔', 'اور قسم نہ کھائیں بڑے درجہ  والے تم میں سے اور کشائش والے اس پر کہ دیں قرابتیوں کو اور محتاجوں کو اور وطن چھوڑنے والوں کو اللہ کی راہ میں اور چاہئے کہ معاف کریں اور درگزر کریں کیا تم نہیں چاہتے کہ اللہ تم کو معاف کرے اور اللہ بخشنے والا مہربان ہے [۳۱]', 'And let not those among you who are blessed with graces and wealth swear not to give (any sort of help) to their kinsmen, Al-Masakeen (the poor), and those who left their homes for Allahs Cause. Let them pardon and forgive. Do you not love that Allah should forgive you? And Allah is Oft-Forgiving, Most Merciful.', 'The men of grace and wealth among you should not swear against giving (their charitable gifts) to the kinsmen and the poor and to those who have migrated in the way of Allah, and they should forgive and forego. Do you not like that Allah forgives you? Allah is Most-Forgiving, Very-Merciful.'),
(2814, 24, 23, 3, 9, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'اِنَّ  الَّذِیۡنَ یَرۡمُوۡنَ الۡمُحۡصَنٰتِ الۡغٰفِلٰتِ الۡمُؤۡمِنٰتِ لُعِنُوۡا فِی الدُّنۡیَا وَ الۡاٰخِرَۃِ ۪ وَ  لَہُمۡ  عَذَابٌ  عَظِیۡمٌ ﴿ۙ۲۳﴾', 'جو لوگ پرہیزگار اور برے کاموں سے بےخبر اور ایمان دار عورتوں پر بدکاری کی تہمت لگاتے ہیں ان پر دنیا اور آخرت دونوں میں لعنت ہے اور انکو سخت عذاب ہو گا۔', 'جو لوگ عیب لگاتے ہیں حفاظت والیوں بیخبر ایمان والیوں کو ان کو پھٹکار ہے دنیا میں اور آخرت میں اور انکے لئے ہے بڑا عذاب [۳۲]', 'Verily, those who accuse chaste women, who never even think of anything touching their chastity and are good believers, are cursed in this life and in the Hereafter, and for them will be a great torment,', 'Surely, those who level a false charge against the chaste, natve and believing women are cursed in this world and the Hereafter, and for them there is a mighty punishment'),
(2815, 24, 24, 3, 9, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'یَّوۡمَ  تَشۡہَدُ عَلَیۡہِمۡ اَلۡسِنَتُہُمۡ وَ اَیۡدِیۡہِمۡ  وَ  اَرۡجُلُہُمۡ  بِمَا  کَانُوۡا یَعۡمَلُوۡنَ  ﴿۲۴﴾', 'یعنی قیامت کے روز جس دن ان کی زبانیں اور ہاتھ اور پاؤں سب ان کے کاموں کی گواہی دیں گے۔', 'جس دن کہ ظاہر کر دیں گی ان کی زبانیں اور ہاتھ اور پاؤں جو کچھ وہ کرتے تھے [۳۳]', 'On the Day when their tongues, their hands, and their legs or feet will bear witness against them as to what they used to do.', 'on the Day when their tongues, their hands and their legs will testify against themselves of what they used to do.'),
(2816, 24, 25, 3, 9, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'یَوۡمَئِذٍ یُّوَفِّیۡہِمُ اللّٰہُ  دِیۡنَہُمُ الۡحَقَّ وَ یَعۡلَمُوۡنَ  اَنَّ  اللّٰہَ  ہُوَ الۡحَقُّ الۡمُبِیۡنُ ﴿۲۵﴾', 'اس دن اللہ انکو ان کے اعمال کا پورا پورا اور ٹھیک ٹھیک بدلہ دے گا اور انکو معلوم ہو جائے گا کہ اللہ برحق اور حق کو ظاہر کرنے والا ہے۔', 'اس دن پوری دے گا انکو اللہ ان کی سزا جو چاہئے اور جان لیں گے کہ اللہ وہی ہے سچا کھولنے والا [۳۴]', 'On that Day Allah will pay them the recompense of their deeds in full, and they will know that Allah, He is the Manifest Truth.', 'On that day Allah will give them their rightful recompense in full, and they will know that Allah is the Very Truth who makes all things manifest.'),
(2817, 24, 26, 3, 9, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'اَلۡخَبِیۡثٰتُ لِلۡخَبِیۡثِیۡنَ وَ الۡخَبِیۡثُوۡنَ لِلۡخَبِیۡثٰتِ ۚ وَ الطَّیِّبٰتُ لِلطَّیِّبِیۡنَ وَ الطَّیِّبُوۡنَ لِلطَّیِّبٰتِ ۚ اُولٰٓئِکَ مُبَرَّءُوۡنَ مِمَّا یَقُوۡلُوۡنَ ؕ لَہُمۡ مَّغۡفِرَۃٌ  وَّ رِزۡقٌ  کَرِیۡمٌ ﴿٪۲۶﴾', 'ناپاک عورتیں ناپاک مردوں کے لئے ہیں اور ناپاک مرد ناپاک عورتوں کے لئے۔ اور پاک عورتیں پاک مردوں کے لئے ہیں اور پاک مرد پاک عورتوں کے لئے۔ یہ پاک لوگ ان جھوٹوں کی باتوں سے بری ہیں اور ان کے لئے بخشش اور نیک روزی ہے۔', 'گندیاں ہیں گندوں کے واسطے اور گندے واسطے گندیوں کے اور ستھریاں ہیں ستھروں کے واسطے اور ستھرے واسطے ستھریوں کے [۳۵] وہ لوگ بے تعلق ہیں ان باتوں سے جو یہ کہتے ہیں [۳۶] انکے واسطے بخشش ہے اور روزی ہے عزت کی [۳۷]', 'Bad statements are for bad people (or bad women for bad men) and bad people for bad statements (or bad men for bad women). Good statements are for good people (or good women for good men) and good people for good statements (or good men for good women), such (good people) are innocent of (each and every) bad statement which they say, for them is Forgiveness, and Rizqun Kareem (generous provision i.e.Paradise).', 'Vile women are for vile men, and vile men are for vile women; and good women are for good men, and good men are for good women. Those are free from what they (the accusers) say. For them there is forgiveness, and a graceful provision.'),
(2818, 24, 27, 4, 10, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَدۡخُلُوۡا بُیُوۡتًا غَیۡرَ  بُیُوۡتِکُمۡ  حَتّٰی تَسۡتَاۡنِسُوۡا وَ تُسَلِّمُوۡا عَلٰۤی اَہۡلِہَا ؕ ذٰلِکُمۡ  خَیۡرٌ لَّکُمۡ  لَعَلَّکُمۡ  تَذَکَّرُوۡنَ ﴿۲۷﴾', 'مومنو! اپنے گھروں کے سوا دوسرے لوگوں کے گھروں میں گھر والوں سے اجازت لئے اور انکو سلام کئے بغیر داخل نہ ہوا کرو۔ یہ تمہارے حق میں بہتر ہے اور ہم یہ نصیحت اس لئے کرتے ہیں کہ شاید تم یاد رکھو۔', 'اے ایمان والو مت جایا کرو کسی گھر میں اپنے گھروں کے سوائے جب تک بول چال نہ کر لو اور سلام کر لو ان گھر والوں پر یہ بہتر ہے تمہارے حق میں تاکہ تم یاد رکھو [۳۸]', 'O you who believe! Enter not houses other than your own, until you have asked permission and greeted those in them, that is better for you, in order that you may remember.', 'O you who believe, do not enter any houses, other than your own houses unless you seek permission and greet their inmates with Salām . That is good for you, so that you may be heedful.'),
(2819, 24, 28, 4, 10, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'فَاِنۡ  لَّمۡ تَجِدُوۡا فِیۡہَاۤ  اَحَدًا فَلَا تَدۡخُلُوۡہَا حَتّٰی یُؤۡذَنَ لَکُمۡ ۚ وَ  اِنۡ قِیۡلَ لَکُمُ ارۡجِعُوۡا فَارۡجِعُوۡا ہُوَ اَزۡکٰی لَکُمۡ ؕ وَ اللّٰہُ  بِمَا تَعۡمَلُوۡنَ عَلِیۡمٌ ﴿۲۸﴾', 'پھر اگر تم گھر میں کسی کو موجود نہ پاؤ تو جب تک تمکو اجازت نہ دی جائے اس میں مت داخل ہو۔ اور اگر یہ کہا جائے کہ اس وقت لوٹ جاؤ تو لوٹ جایا کرو یہ تمہارے لئے بڑی پاکیزگی کی بات ہے اور جو کام تم کرتے ہو اللہ سب جانتا ہے۔', 'پھر اگر نہ پاؤ اس میں کسی کو تو اس میں نہ جاؤ جب تک کہ اجازت نہ ملے تم کو [۳۹] اور اگر تم کو جواب ملے کہ پھر جاؤ تو پھر جاؤ اس میں خوب ستھرائی ہے تمہارے لئے [۴۰] اور اللہ جو تم کرتے ہو اس کو جانتا ہے [۴۱]', 'And if you find no one therein, still, enter not until permission has been given. And if you are asked to go back, go back, for it is purer for you, and Allah is All-Knower of what you do.', 'Even if you do not find anyone in them, do not enter therein until permission is given to you. And if it is said to you, ‘Go back’, just go back; it is more decent for you. Allah is All-Aware of what you do.'),
(2820, 24, 29, 4, 10, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'لَیۡسَ عَلَیۡکُمۡ جُنَاحٌ اَنۡ تَدۡخُلُوۡا بُیُوۡتًا غَیۡرَ مَسۡکُوۡنَۃٍ فِیۡہَا مَتَاعٌ لَّکُمۡ ؕ وَ اللّٰہُ یَعۡلَمُ  مَا تُبۡدُوۡنَ وَ مَا تَکۡتُمُوۡنَ ﴿۲۹﴾', 'ہاں اگر تم کسی ایسے مکان میں جاؤ جسمیں کوئی نہ بستا ہو اور اس میں تمہارا اسباب رکھا ہو تو تم پر کچھ گناہ نہیں۔ اور جو کچھ تم ظاہر کرتے ہو اور جو پوشیدہ کرتے ہو اللہ کو سب معلوم ہے۔', 'نہیں گناہ تم پر اس میں کہ جاؤ ان گھروں میں جہاں کوئی نہیں بستا اس میں کچھ چیز ہو تمہاری [۴۲] اور اللہ کو معلوم ہے جو تم ظاہر کرتے ہو اور جو چھپاتے ہو [۴۳]', 'There is no sin on you that you enter (without taking permission) houses uninhabited (i.e. not possessed by anybody), (when) you have any interest in them. And Allah has knowledge of what you reveal and what you conceal.', 'There is no sin on you if you enter uninhabited houses in which you have rightful benefit. Allah knows what you reveal and what you conceal.'),
(2821, 24, 30, 4, 10, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'قُلۡ لِّلۡمُؤۡمِنِیۡنَ یَغُضُّوۡا مِنۡ  اَبۡصَارِہِمۡ وَ یَحۡفَظُوۡا فُرُوۡجَہُمۡ ؕ ذٰلِکَ اَزۡکٰی لَہُمۡ ؕ اِنَّ اللّٰہَ خَبِیۡرٌۢ  بِمَا یَصۡنَعُوۡنَ ﴿۳۰﴾', 'مومن مردوں سے کہدو کہ اپنی نظریں نیچی رکھا کریں اور اپنی شرمگاہوں کی حفاظت کیا کریں۔ یہ انکے لئے بڑی پاکیزگی کی بات ہے اور جو کام یہ کرتے ہیں اللہ ان سے خبردار ہے۔', 'کہہ دے ایمان والوں کو نیچی رکھیں ذری اپنی آنکھیں [۴۴] اور تھامتے رہیں اپنے ستر کو [۴۵] اس میں خوب ستھرائی ہے انکے لئے بیشک اللہ کو خبر ہے جو کچھ کرتےہیں [۴۶]', 'Tell the believing men to lower their gaze (from looking at forbidden things), and protect their private parts (from illegal sexual acts, etc.). That is purer for them. Verily, Allah is All-Aware of what they do.', 'Tell the believing men that they must lower their gazes and guard their private parts; it is more decent for them. Surely Allah is All-Aware of what they do.'),
(2822, 24, 31, 4, 10, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ قُلۡ  لِّلۡمُؤۡمِنٰتِ یَغۡضُضۡنَ مِنۡ اَبۡصَارِہِنَّ وَ یَحۡفَظۡنَ فُرُوۡجَہُنَّ وَ لَا یُبۡدِیۡنَ  زِیۡنَتَہُنَّ  اِلَّا مَا ظَہَرَ  مِنۡہَا وَ لۡیَضۡرِبۡنَ بِخُمُرِہِنَّ عَلٰی جُیُوۡبِہِنَّ ۪ وَ لَا یُبۡدِیۡنَ زِیۡنَتَہُنَّ  اِلَّا  لِبُعُوۡلَتِہِنَّ  اَوۡ اٰبَآئِہِنَّ اَوۡ اٰبَآءِ بُعُوۡلَتِہِنَّ اَوۡ اَبۡنَآئِہِنَّ  اَوۡ اَبۡنَآءِ بُعُوۡلَتِہِنَّ اَوۡ اِخۡوَانِہِنَّ اَوۡ بَنِیۡۤ  اِخۡوَانِہِنَّ اَوۡ بَنِیۡۤ اَخَوٰتِہِنَّ اَوۡ نِسَآئِہِنَّ اَوۡ مَا مَلَکَتۡ اَیۡمَانُہُنَّ اَوِ التّٰبِعِیۡنَ غَیۡرِ اُولِی الۡاِرۡبَۃِ مِنَ الرِّجَالِ اَوِ الطِّفۡلِ الَّذِیۡنَ لَمۡ  یَظۡہَرُوۡا عَلٰی عَوۡرٰتِ النِّسَآءِ ۪ وَ لَا یَضۡرِبۡنَ بِاَرۡجُلِہِنَّ لِیُعۡلَمَ  مَا یُخۡفِیۡنَ مِنۡ زِیۡنَتِہِنَّ ؕ وَ تُوۡبُوۡۤا اِلَی اللّٰہِ جَمِیۡعًا اَیُّہَ الۡمُؤۡمِنُوۡنَ لَعَلَّکُمۡ تُفۡلِحُوۡنَ  ﴿۳۱﴾', 'اور مومن عورتوں سے کہدو کہ وہ بھی اپنی نگاہیں نیچی رکھا کریں اور اپنی شرمگاہوں کی حفاظت کیا کریں اور اپنی آرائش یعنی زیور کے مقامات کو ظاہر نہ ہونے دیا کریں مگر جو اس میں سے کھلا رہتا ہو۔ اور اپنے سینوں پر اوڑھنیاں اوڑھے رہا کریں اور اپنے خاوند اور باپ اور خسر اور بیٹوں اور خاوند کے بیٹوں اور بھائیوں اور بھتیجوں اور بھانجوں اور اپنی جیسی مومن عورتوں اور لونڈی غلاموں کے سوا نیز ان خدام کے جو عورتوں کی خواہش نہ رکھیں یا ایسے لڑکوں کے جو عورتوں کے پردے کی چیزوں سے واقف نہ ہوں غرض ان لوگوں کے سوا کسی پر اپنی زینت اور سنگھار کے مقامات کو ظاہر نہ ہونے دیں۔ اور اپنے پاؤں ایسے طور سے زمین پر نہ ماریں کہ جھنکار کانوں میں پہنچے اور ان کا پوشیدہ زیور معلوم ہو جائے اور مومنو سب اللہ کے آگے توبہ کرو تاکہ فلاح پاؤ۔', 'اور کہہ دے ایمان والیوں کو نیچی رکھیں ذرا اپنی آنکھیں اور تھامتی رہیں اپنے ستر کو اور نہ دکھائیں اپنا سنگار مگر جو کھلی چیز ہے اس میں سے [۴۷] اور ڈال لیں اپنی اوڑھنی اپنے گریبان پر [۴۸] اور نہ کھولیں اپنا سنگار مگر اپنے خاوند کے آگے یا اپنے باپ کے [۴۹] یا پنے خاوند کے باپ کے یا اپنے بیٹے کے یا اپنے خاوند کے بیٹے کے یا اپنے بھائی کے یا اپنے بھتیجوں کے یا اپنے بھانجوں کے یا اپنی عورتوں کے [۵۰] یا اپنے ہاتھ کے مال کے [۵۱] یا کاربار کرنے والوں کے (خدمت میں مشغول رہنے والوں کے) جو مرد کہ کچھ غرض نہیں رکھتے [۵۲] یا لڑکوں کے جنہوں نے ابھی نہیں پہچانا عورتوں کے بھید کو [۵۳] اور نہ ماریں زمین پر اپنے پاؤں کو کہ جانا جائے جو چھپاتی ہیں اپنا سنگار [۵۴] اور توبہ کرو اللہ کے آگے سب مل کر اے ایمان والو تاکہ تم بھلائی پاؤ [۵۵]', 'And tell the believing women to lower their gaze (from looking at forbidden things), and protect their private parts (from illegal sexual acts, etc.) and not to show off their adornment except only that which is apparent (like palms of hands or one eye or both eyes for necessity to see the way, or outer dress like veil, gloves, head-cover, apron, etc.), and to draw their veils all over Juyubihinna (i.e. their bodies, faces, necks and bosoms, etc.) and not to reveal their adornment except to their husbands, their fathers, their husbands fathers, their sons, their husbands sons, their brothers or their brothers sons, or their sisters sons, or their (Muslim) women (i.e. their sisters in Islam), or the (female) slaves whom their right hands possess, or old male servants who lack vigour, or small children who have no sense of the shame of sex. And let them not stamp their feet so as to reveal what they hide of their adornment. And all of you beg Allah to forgive you all, O believers, that you may be successful.', 'And tell the believing women that they must lower their gazes and guard their private parts, and must not expose their adornment, except that which appears thereof, and must wrap their bosoms with their shawls, and must not expose their adornment, except to their husbands or their fathers or the fathers of their husbands, or to their sons or the sons of their husbands, or to their brothers or the sons of their brothers or the sons of their sisters, or to their women, or to those owned by their right hands, or male attendants having no (sexual) urge, or to the children who are not yet conscious of the shames of women. And let them not stamp their feet in a way that the adornment they conceal is known. And repent to Allah O believers, all of you, so that you may achieve success.'),
(2823, 24, 32, 4, 10, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ اَنۡکِحُوا الۡاَیَامٰی مِنۡکُمۡ وَ الصّٰلِحِیۡنَ مِنۡ عِبَادِکُمۡ وَ اِمَآئِکُمۡ ؕ اِنۡ یَّکُوۡنُوۡا فُقَرَآءَ یُغۡنِہِمُ اللّٰہُ مِنۡ فَضۡلِہٖ ؕ وَ اللّٰہُ  وَاسِعٌ  عَلِیۡمٌ ﴿۳۲﴾', 'اور اپنی قوم کی بیوہ عورتوں کے نکاح کر دیا کرو۔ اور اپنے غلاموں اور لونڈیوں کے بھی جو نیک ہوں نکاح کر دیا کرو اگر وہ مفلس ہوں گے تو اللہ انکو اپنے فضل سے غنی کر دے گا۔ اور اللہ بہت وسعت والا ہے سب کچھ جاننے والا ہے۔', 'اور نکاح کر دو رانڈوں کا اپنے اندر [۵۶] اور جو نیک ہوں تمہارے غلام اور لونڈیاں [۵۷] اگر وہ ہوں گے مفلس اللہ ان کو غنی کر دے گا اپنے فضل سے [۵۸] اور اللہ کشائش والا ہے سب کچھ جانتا ہے [۵۹]', 'And marry those among you who are single (i.e. a man who has no wife and the woman who has no husband) and (also marry) the Salihoon (pious, fit and capable ones) of your (male) slaves and maid-servants (female slaves). If they be poor, Allah will enrich them out of His Bounty. And Allah is All-Sufficent for His creatures needs, All-Knowing (about the state of the people).', 'Arrange the marriage of the spouseless among you, and the capable from among your bondmen and bondwomen. If they are poor, Allah will enrich them out of His grace. Allah is All-Encompassing, All-Knowing.'),
(2824, 24, 33, 4, 10, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ لۡیَسۡتَعۡفِفِ  الَّذِیۡنَ لَا یَجِدُوۡنَ  نِکَاحًا حَتّٰی یُغۡنِیَہُمُ اللّٰہُ  مِنۡ فَضۡلِہٖ ؕ وَ الَّذِیۡنَ یَبۡتَغُوۡنَ الۡکِتٰبَ مِمَّا مَلَکَتۡ اَیۡمَانُکُمۡ فَکَاتِبُوۡہُمۡ  اِنۡ عَلِمۡتُمۡ فِیۡہِمۡ خَیۡرًا ٭ۖ وَّ اٰتُوۡہُمۡ مِّنۡ مَّالِ اللّٰہِ الَّذِیۡۤ  اٰتٰىکُمۡ ؕ وَ لَا تُکۡرِہُوۡا فَتَیٰتِکُمۡ عَلَی الۡبِغَآءِ  اِنۡ  اَرَدۡنَ تَحَصُّنًا لِّتَبۡتَغُوۡا عَرَضَ الۡحَیٰوۃِ  الدُّنۡیَا ؕ وَ مَنۡ  یُّکۡرِہۡہُّنَّ فَاِنَّ اللّٰہَ مِنۡۢ بَعۡدِ اِکۡرَاہِہِنَّ غَفُوۡرٌ رَّحِیۡمٌ ﴿۳۳﴾', 'اور جنکو بیاہ کا مقدور نہ ہو وہ پاکدامنی کو اختیار کئے رہیں یہاں تک کہ اللہ انکو اپنے فضل سے غنی کر دے۔ اور جو غلام تم سے مکاتبت یعنی مال دیکر پروانہ آزادی کی تحریر چاہیں اگر تم ان میں صلاحیت اور نیکی پاؤ تو ان سے مکاتبت کر لو اور اللہ نے جو مال تمکو بخشا ہے اس میں سے انکو بھی دو۔ اور اپنی باندیوں کو اگر وہ پاکدامن رہنا چاہیں تو دنیاوی زندگی کے فوائد حاصل کرنے کے لئے بدکاری پر مجبور نہ کرنا اور جو انکو مجبور کرے گا تو ان بیچاریوں کے مجبور کئے جانے کے بعد اللہ بخشنے والا ہے مہربان ہے۔', 'اور اپنے آپ کو تھامتے رہیں جن کو نہیں ملتا سامان نکاح کا جب تک کہ مقدور دے ان کو اللہ اپنے فضل سے [۶۰] اور جو لوگ چاہیں لکھت آزادی کی مال دے کر ان میں سے کہ جو تمہارے ہاتھ کے مال ہیں (جن کے مالک ہیں تمہارےہاتھ) تو انکو لکھ کر دیدو اگر سمجھو ان میں کچھ نیکی  [۶۱] اور دو ان کو اللہ کے مال سے جو اس نے تم کو دیا ہے [۶۲] اور نہ زبردستی کرو اپنی چھوکریوں پر بدکاری کے واسطے اگر وہ چاہیں قید سے رہنا کہ تم کمانا چاہو اسباب دنیا کی زندگانی کا [۶۳] اور جو کوئی ان پر زبردستی کرے گا تو اللہ ان کی بے بسی کے پیچھے بخشنے والا مہربان ہے [۶۴]', 'And let those who find not the financial means for marriage keep themselves chaste, until Allah enriches them of His Bounty. And such of your slaves as seek a writing (of emancipation), give them such writing, if you know that they are good and trustworthy. And give them something yourselves out of the wealth of Allah which He has bestowed upon you. And force not your maids to prostitution, if they desire chastity, in order that you may make a gain in the (perishable) goods of this worldly life. But if anyone compels them (to prostitution), then after such compulsion, Allah is Oft-Forgiving, Most Merciful (to those women, i.e. He will forgive them because they have been forced to do this evil action unwillingly).', 'And those who cannot afford marriage should keep themselves chaste until Allah enriches them out of His grace. And those of your slaves who wish to enter the contract of Kitābah (emancipation by paying money), contract Kitābah with them, if you recognize some good in them. And give them out of the wealth of Allah that He has given to you. And do not compel your maids to prostitution - if they wish to observe chastity - in order that you may seek the temporary benefit of the worldly life. If one compels them, then after their being compelled, Allah is Most-Forgiving, Very-Merciful.'),
(2825, 24, 34, 4, 10, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ لَقَدۡ  اَنۡزَلۡنَاۤ  اِلَیۡکُمۡ   اٰیٰتٍ مُّبَیِّنٰتٍ وَّ مَثَلًا مِّنَ الَّذِیۡنَ خَلَوۡا مِنۡ قَبۡلِکُمۡ  وَ  مَوۡعِظَۃً   لِّلۡمُتَّقِیۡنَ ﴿٪۳۴﴾', 'اور ہم نے تمہاری طرف روشن آیتیں نازل کی ہیں اور جو لوگ تم سے پہلے گذر چکے ہیں انکی خبریں اور پرہیزگاروں کے لئے نصیحت۔', 'اور ہم نے اتاریں تمہاری طرف آیتیں کھلی ہوئی اور کچھ حال انکا جو ہو چکے تم سے پہلے اور نصیحت ڈرنے والوں کو [۶۵]', 'And indeed We have sent down for you Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) that make things plain, and the example of those who passed away before you, and an admonition for those who are Al-Muttaqoon (the pious - see V.2:2).', 'Indeed We have sent down to you enlightening verses, and an exemplary description of those who passed away before you, and a good counsel for the God-fearing.'),
(2826, 24, 35, 5, 11, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'اَللّٰہُ  نُوۡرُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ مَثَلُ نُوۡرِہٖ کَمِشۡکٰوۃٍ  فِیۡہَا مِصۡبَاحٌ ؕ اَلۡمِصۡبَاحُ فِیۡ زُجَاجَۃٍ ؕ اَلزُّجَاجَۃُ کَاَنَّہَا کَوۡکَبٌ دُرِّیٌّ یُّوۡقَدُ مِنۡ شَجَرَۃٍ مُّبٰرَکَۃٍ  زَیۡتُوۡنَۃٍ  لَّا شَرۡقِیَّۃٍ  وَّ لَا غَرۡبِیَّۃٍ ۙ یَّکَادُ زَیۡتُہَا یُضِیۡٓءُ وَ لَوۡ لَمۡ تَمۡسَسۡہُ نَارٌ ؕ نُوۡرٌ عَلٰی نُوۡرٍ ؕ یَہۡدِی اللّٰہُ  لِنُوۡرِہٖ مَنۡ یَّشَآءُ ؕ وَ یَضۡرِبُ اللّٰہُ الۡاَمۡثَالَ لِلنَّاسِ ؕ وَ اللّٰہُ  بِکُلِّ شَیۡءٍ عَلِیۡمٌ ﴿ۙ۳۵﴾', 'اللہ آسمانوں اور زمین کا نور ہے۔ اسکے نور کی مثال ایسی ہے کہ گویا ایک طاق ہے جس میں ایک چراغ ہے اور چراغ ایک قندیل میں ہے اور قندیل ایسی صاف شفاف ہے کہ گویا موتی کا سا چمکتا ہوا تارہ ہے۔ اس میں ایک مبارک درخت کا تیل جلایا جاتا ہے یعنی زیتون کا کہ نہ مشرق کی طرف ہے نہ مغرب کی طرف ایسا معلوم ہوتا ہے کہ اس کا تیل خواہ آگ اسے نہ بھی چھوئے جلنے کو تیار ہے بڑی روشنی پر روشنی ہو رہی ہے اللہ اپنے نور سے جسکو چاہتا ہے سیدھی راہ دکھاتا ہے اور اللہ جو مثالیں بیان فرماتا ہے تو لوگوں کے سمجھانے کے لئے اور اللہ ہر چیز سے واقف ہے۔', 'اللہ روشنی ہے آسمانوں اور زمین کی [۶۶] مثال اس کی روشنی کی جیسے ایک طاق اس میں ہو ایک چراغ وہ چراغ دھرا ہو ایک شیشہ میں وہ شیشہ ہے جیسے ایک تارہ چمکتا ہوا تیل جلتا ہے اس میں ایک برکت کے درخت کا وہ زیتون ہے نہ مشرق کی طرف ہے اور نہ مغرب کی طرف قریب ہے اس کا تیل کہ روشن ہو جائے اگرچہ نہ لگی ہو اس میں آگ روشنی پر روشنی اللہ راہ دکھلا دیتا ہے اپنی روشنی کی جس کو چاہے اور بیان کرتا ہے اللہ مثالیں لوگوں کے واسطے اور اللہ سب چیز کو جانتا ہے [۶۷]', 'Allah is the Light of the heavens and the earth. The parable of His Light is as (if there were) a niche and within it a lamp, the lamp is in glass, the glass as it were a brilliant star, lit from a blessed tree, an olive, neither of the east (i.e. neither it gets sun-rays only in the morning) nor of the west (i.e. nor it gets sun-rays only in the afternoon, but it is exposed to the sun all day long), whose oil would almost glow forth (of itself), though no fire touched it. Light upon Light! Allah guides to His Light whom He wills. And Allah sets forth parables for mankind, and Allah is All-Knower of everything.', 'Allah is the Light of the heavens and the earth. The parable of His Light is as (if there were) a niche and within it a lamp, the lamp is in glass, the glass as it were a brilliant star, lit from a blessed tree, an olive, neither of the east (i.e. neither it gets sun-rays only in the morning) nor of the west (i.e. nor it gets sun-rays only in the afternoon, but it is exposed to the sun all day long), whose oil would almost glow forth (of itself), though no fire touched it. Light upon Light! Allah guides to His Light whom He wills. And Allah sets forth parables for mankind, and Allah is All-Knower of everything.'),
(2827, 24, 36, 5, 11, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'فِیۡ  بُیُوۡتٍ اَذِنَ اللّٰہُ  اَنۡ تُرۡفَعَ وَ یُذۡکَرَ فِیۡہَا اسۡمُہٗ ۙ یُسَبِّحُ لَہٗ  فِیۡہَا بِالۡغُدُوِّ وَ الۡاٰصَالِ ﴿ۙ۳۶﴾', 'وہ قندیل ان گھروں میں ہے جنکے بارے میں اللہ نے ارشاد فرمایا ہے کہ بلند کئے جائیں۔  اور وہاں اللہ کے نام کا ذکر کیا جائے اور ان میں صبح و شام اسکی تسبیح کرتے ہیں۔', 'ان گھروں میں کہ اللہ نے حکم دیا انکو بلند کرنے کا [۶۸] اور و ہاں اس کا نام پڑھنے کا [۶۹] یاد کرتے ہیں اسکی وہاں صبح و شام [۷۰]', 'In houses (mosques), which Allah has ordered to be raised (to be cleaned, and to be honoured), in them His Name is glorified in the mornings and in the afternoons or the evenings,', '(The guided people worship Allah) in the houses that Allah has permitted to be raised, and where His name is recounted and His purity is pronounced, in the morning and in the evening,'),
(2828, 24, 37, 5, 11, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'رِجَالٌ ۙ لَّا تُلۡہِیۡہِمۡ تِجَارَۃٌ  وَّ لَا بَیۡعٌ عَنۡ ذِکۡرِ اللّٰہِ وَ  اِقَامِ الصَّلٰوۃِ  وَ  اِیۡتَآءِ الزَّکٰوۃِ ۪ۙ یَخَافُوۡنَ یَوۡمًا تَتَقَلَّبُ فِیۡہِ الۡقُلُوۡبُ وَ الۡاَبۡصَارُ ﴿٭ۙ۳۷﴾', 'ایسے لوگ جنکو اللہ کے ذکر اور نماز پڑھنے اور زکوٰۃ دینے سے نہ سوداگری غافل کرتی ہے نہ خریدوفروخت۔ وہ اس دن سے جب دل خوف اور گھبراہٹ کے سبب الٹ جائیں گے اور آنکھیں اوپر چڑھ جائیں گی ڈرتے ہیں۔', 'وہ مرد کہ نہیں غافل ہوتے سودا کرنے میں اور نہ بیچنے میں اللہ کی یاد سے اور نماز قائم رکھنے سے اور زکوٰۃ دینے سے [۷۱] ڈرتے رہتے ہیں اس دن سے جس میں الٹ جائیں گے دل اور آنکھیں [۷۲]', 'Men whom neither trade nor sale diverts them from the Remembrance of Allah (with heart and tongue), nor from performing AsSalat (Iqamat-as-Salat), nor from giving the Zakat. They fear a Day when hearts and eyes will be overturned (from the horror of the torment of the Day of Resurrection).', 'by the men whom no trade or sale makes neglectful of the remembrance of Allah, nor from establishing Salāh and paying Zakāh ; they are fearful of a day in which the hearts and the eyes will be over-turned.'),
(2829, 24, 38, 5, 11, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'لِیَجۡزِیَہُمُ اللّٰہُ  اَحۡسَنَ مَا عَمِلُوۡا وَ یَزِیۡدَہُمۡ مِّنۡ فَضۡلِہٖ ؕ وَ اللّٰہُ یَرۡزُقُ مَنۡ یَّشَآءُ  بِغَیۡرِ  حِسَابٍ  ﴿۳۸﴾', 'تاکہ اللہ انکو ان کے اعمال کا بہت اچھا بدلہ دے۔ اور اپنے فضل سے زیادہ بھی عطا فرمائے اور اللہ جسکو چاہتا ہے بیحساب رزق دیتا ہے۔', 'تاکہ بدلہ دے انکو اللہ انکے بہتر سے بہتر کاموں کا اور زیادتی دے انکو اپنے فضل سے [۷۳] اور اللہ روزی دیتا ہے جس کو چاہے بے شمار [۷۴]', 'That Allah may reward them according to the best of their deeds, and add even more for them out of His Grace. And Allah provides without measure to whom He wills.', 'The fate (of such people) is that Allah will reward them for the best deeds they did, and will give them more out of His grace. Allah gives whom He wills without counting.'),
(2830, 24, 39, 5, 11, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ الَّذِیۡنَ  کَفَرُوۡۤا اَعۡمَالُہُمۡ کَسَرَابٍۭ بِقِیۡعَۃٍ یَّحۡسَبُہُ الظَّمۡاٰنُ مَآءً ؕ حَتّٰۤی اِذَا جَآءَہٗ  لَمۡ  یَجِدۡہُ شَیۡئًا وَّ وَجَدَ  اللّٰہَ عِنۡدَہٗ  فَوَفّٰىہُ حِسَابَہٗ ؕ وَ اللّٰہُ سَرِیۡعُ الۡحِسَابِ ﴿ۙ۳۹﴾', 'اور جن لوگوں نے کفر کیا انکے اعمال کی مثال ایسی ہے جیسے میدان میں ریت کہ پیاسا اسے پانی سمجھے یہاں تک کہ جب اسکے پاس آئے تو اسے کچھ بھی نہ پائے۔ اور اللہ ہی کو اپنے پاس دیکھے تو وہ اسے اس کا حساب پورا پورا چکا دے اور اللہ جلد حساب کرنے والا ہے۔', 'اور جو لوگ منکر ہیں ان کے کام جیسے ریت جنگل میں پیاسا جانے اس کو پانی یہاں تک کہ جب پہنچا اس پر اس کو کچھ نہ پایا اور اللہ کو پایا اپنے پاس پھر اسکو پورا پہنچا دیا اس کا لکھا اور اللہ جلد لینے والا ہے حساب [۷۵]', 'As for those who disbelieve, their deeds are like a mirage in a desert. The thirsty one thinks it to be water, until he comes up to it, he finds it to be nothing, but he finds Allah with him, Who will pay him his due (Hell). And Allah is Swift in taking account.', 'As for those who disbelieve, their deeds are like a mirage in a desert plain, which a thirsty person deems to be water, until when he comes to it, he finds it nothing, and finds (the decree of) Allah with him, so He pays him his account in full. Allah is swift at reckoning.'),
(2831, 24, 40, 5, 11, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'اَوۡ کَظُلُمٰتٍ فِیۡ بَحۡرٍ لُّجِّیٍّ یَّغۡشٰہُ مَوۡجٌ مِّنۡ فَوۡقِہٖ مَوۡجٌ مِّنۡ فَوۡقِہٖ سَحَابٌ ؕ ظُلُمٰتٌۢ  بَعۡضُہَا فَوۡقَ بَعۡضٍ ؕ اِذَاۤ اَخۡرَجَ یَدَہٗ  لَمۡ  یَکَدۡ یَرٰىہَا ؕ وَ مَنۡ  لَّمۡ یَجۡعَلِ اللّٰہُ   لَہٗ   نُوۡرًا  فَمَا  لَہٗ  مِنۡ  نُّوۡرٍ ﴿٪۴۰﴾', 'یا انکے اعمال کی مثال ایسی ہے جیسے گہرے سمندر میں اندھیرے جس پر لہر چڑھی چلی آتی ہو اور اسکے اوپر اور لہر آ رہی ہو اور اسکے اوپر بادل ہو غرض اندھیرے ہی اندھیرے ہوں ایک پر ایک چھایا ہوا جب اپنا ہاتھ نکالے تو کچھ نہ دیکھ سکے۔ اور جسکو اللہ روشنی نہ دے اسکو کہیں بھی روشنی نہیں مل سکتی۔', 'یا جیسے اندھیرے گہرے دریا میں چڑھی آتی ہے اس پر ایک لہر اس پر ایک اور لہر اس کے اوپر بادل اندھیرے ہیں ایک پر ایک [۷۶] جب نکالے اپنا ہاتھ لگتا نہیں کہ اس کو وہ سوجھے [۷۷] اور جسکو اللہ نے نہ دی روشنی اسکے واسطے کہیں نہیں روشنی [۷۸]', 'Or (the state of a disbeliever) is like the darkness in a vast deep sea, overwhelmed with a great wave topped by a great wave, topped by dark clouds, darkness, one above another, if a man stretches out his hand, he can hardly see it! And he for whom Allah has not appointed light, for him there is no light.', 'Or (their deeds) are like layers of darkness in a vast deep sea overwhelmed by a wave, above which there is another wave, above which there are clouds - layers of darkness, one above the other. When one puts forth his hand, he can hardly see it; and the one to whom Allah does not give light can have no light at all.'),
(2832, 24, 41, 6, 12, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'اَلَمۡ تَرَ اَنَّ اللّٰہَ  یُسَبِّحُ لَہٗ  مَنۡ فِی السَّمٰوٰتِ وَ الۡاَرۡضِ وَ الطَّیۡرُ  صٰٓفّٰتٍ ؕ کُلٌّ قَدۡ عَلِمَ  صَلَاتَہٗ وَ تَسۡبِیۡحَہٗ ؕ وَ اللّٰہُ  عَلِیۡمٌۢ   بِمَا یَفۡعَلُوۡنَ ﴿۴۱﴾', 'کیا تم نے نہیں دیکھا کہ جو لوگ آسمانوں اور زمین میں ہیں اللہ کی تسبیح کرتے رہتے ہیں۔ اور پر پھیلائے ہوئے پرندے بھی۔ اور سب اپنی نماز اور تسبیح کے طریقے سے واقف ہیں اور جو کچھ وہ کرتے ہیں سب اللہ کو معلوم ہے۔', 'کیا تو نہ نے دیکھا کہ اللہ کی یاد کرتے ہیں جو کوئی ہیں آسمان و زمین میں اور اڑتے جانور پر کھولے ہوئے [۷۹] ہر ایک نے جان رکھی ہے اپنی طرح کی بندگی اور یاد [۸۰] اور اللہ کو معلوم ہے جو کچھ کرتے ہیں [۸۱]', 'See you not (O Muhammad SAW) that Allah, He it is Whom glorify whosoever is in the heavens and the earth, and the birds with wings out-spread (in their flight). Of each one He (Allah) knows indeed his Salat (prayer) and his glorification, (or everyone knows his Salat (prayer) and his glorification), and Allah is All-Aware of what they do.', 'Did you not realize that purity of Allah is proclaimed by all those in the heavens and the earth, and by the birds with their wings spread out? Everyone knows one’s own (way of) praying (to Allah) and one’s own (way of) proclaiming Allah’s purity. And Allah knows well what they do.'),
(2833, 24, 42, 6, 12, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ لِلّٰہِ مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ ۚ وَ  اِلَی اللّٰہِ  الۡمَصِیۡرُ ﴿۴۲﴾', 'اور آسمان اور زمین کی بادشاہی اللہ ہی کے لئے ہے اور اللہ ہی کی طرف لوٹ کر جانا ہے۔', 'اور اللہ کی حکومت ہے آسمان اور زمین میں اور اللہ ہی تک پھر جانا ہے [۸۲]', 'And to Allah belongs the sovereignty of the heavens and the earth, and to Allah is the return (of all).', 'To Allah belongs the Kingdom of the heavens and the earth, and towards Allah is the final return.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(2834, 24, 43, 6, 12, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'اَلَمۡ  تَرَ  اَنَّ اللّٰہَ یُزۡجِیۡ سَحَابًا ثُمَّ  یُؤَلِّفُ بَیۡنَہٗ  ثُمَّ یَجۡعَلُہٗ  رُکَامًا فَتَرَی الۡوَدۡقَ یَخۡرُجُ مِنۡ خِلٰلِہٖ ۚ وَ  یُنَزِّلُ مِنَ السَّمَآءِ مِنۡ جِبَالٍ فِیۡہَا مِنۡۢ بَرَدٍ فَیُصِیۡبُ بِہٖ مَنۡ یَّشَآءُ وَ یَصۡرِفُہٗ عَنۡ مَّنۡ یَّشَآءُ ؕ یَکَادُ سَنَا بَرۡقِہٖ یَذۡہَبُ بِالۡاَبۡصَارِ ﴿ؕ۴۳﴾', 'کیا تم نے نہیں دیکھا کہ اللہ ہی بادلوں کو چلاتا ہے پھر انکو آپس میں ملا دیتا ہے۔ پھر انکو تہ بہ تہ کر دیتا ہے پھر تم دیکھتے ہو کہ بادل سے مینہ نکل کر برس رہا ہے اور آسمان میں جو اولوں کے پہاڑ ہیں ان سے اولے نازل کرتا ہے تو جس پر چاہتا ہے اسکو برسا دیتا ہے اور جس سے چاہتا ہے ہٹا رکھتا ہے۔ اور بادل میں جو بجلی ہوتی ہے اسکی چمک آنکھوں کو خیرہ کر کے بینائی کو اچکے لئے جاتی ہے۔', 'تو نے نہ دیکھا اللہ ہانک لاتا ہے بادل کو پھر انکو ملا دیتا ہے پھر انکو رکھتا ہے تہ بر تہ پھر تو دیکھے مینہ نکلتا ہے اس کے بیچ سے [۸۳] اور اتارتا ہے آسمان سے اس میں جو پہاڑ ہیں اولوں کے پھر وہ ڈالتا ہے جس پر چاہے اور بچا دیتا ہے جس سے چاہے [۸۴] ابھی اس کی بجلی کی کوند لیجائے آنکھوں کو [۸۵]', 'See you not that Allah drives the clouds gently, then joins them together, then makes them into a heap of layers, and you see the rain comes forth from between them. And He sends down from the sky hail (like) mountains, (or there are in the heaven mountains of hail from where He sends down hail), and strike therewith whom He will, and averts it from whom He wills. The vivid flash of its (clouds) lightning nearly blinds the sight. (Tafsir At-Tabaree).', 'Do you not realize that Allah drives the clouds, then joins them together, then turns them into a heap? Then you see the rain coming out from their midst. He sends down from the sky mountains (of clouds) having hail in them, then He afflicts with it whomsoever He wills and turns it away from whomsoever He wills. The flash of its lightning seems to snatch away the eyes.'),
(2835, 24, 44, 6, 12, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'یُقَلِّبُ اللّٰہُ الَّیۡلَ وَ النَّہَارَ ؕ اِنَّ فِیۡ ذٰلِکَ لَعِبۡرَۃً   لِّاُولِی  الۡاَبۡصَارِ  ﴿۴۴﴾', 'اللہ ہی رات اور دن کو بدلتا رہتا ہے۔ اہل بصارت کے لئے اس میں بڑی عبرت ہے۔', 'اللہ بدلتا ہے رات اور دن کو [۸۶] اس میں دھیان کرنے کی جگہ ہے آنکھ والوں کو [۸۷]', 'Allah causes the night and the day to succeed each other (i.e. if the day is gone, the night comes, and if the night is gone, the day comes, and so on). Truly, in these things is indeed a lesson for those who have insight.', 'Allah alternates the night and the day. Surely, in that there is a lesson for those who have eyes to see.'),
(2836, 24, 45, 6, 12, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ اللّٰہُ خَلَقَ کُلَّ دَآبَّۃٍ  مِّنۡ مَّآءٍ ۚ فَمِنۡہُمۡ مَّنۡ یَّمۡشِیۡ عَلٰی بَطۡنِہٖ ۚ وَ مِنۡہُمۡ مَّنۡ یَّمۡشِیۡ عَلٰی  رِجۡلَیۡنِ ۚ  وَ مِنۡہُمۡ مَّنۡ یَّمۡشِیۡ عَلٰۤی اَرۡبَعٍ ؕ یَخۡلُقُ اللّٰہُ  مَا یَشَآءُ ؕ اِنَّ  اللّٰہَ  عَلٰی کُلِّ  شَیۡءٍ  قَدِیۡرٌ ﴿۴۵﴾', 'اور اللہ ہی نے ہر چلنے پھرنے والے جاندار کو پانی سے پیدا کیا۔ تو ان میں سے بعض ایسے ہیں کہ پیٹ کے بل چلتے ہیں اور بعض ایسے ہیں جو دو پاؤں پر چلتے ہیں اور بعض ایسے ہیں جو چار پاؤں پر چلتے ہیں۔ اللہ جو چاہتا ہے پیدا کرتا ہے بیشک اللہ ہر چیز پر قادر ہے۔', 'اور اللہ نے بنایا ہر پھرنے والے کو ایک پانی سے [۸۸] پھر کوئی ہے کہ چلتا ہے اپنے پیٹ پر [۸۹] اور کوئی ہے کہ چلتا ہے دو پاؤں پر [۹۰] اور کوئی ہے کہ چلتا ہے چار پر [۹۱] بناتا ہے اللہ جو چاہتا ہے بیشک اللہ ہر چیز کر سکتا ہے [۹۲]', 'Allah has created every moving (living) creature from water. Of them there are some that creep on their bellies, some that walk on two legs, and some that walk on four. Allah creates what He wills. Verily! Allah is Able to do all things.', 'Allah has created every moving creature from water. So, some of them move on their bellies; and some of them move on two legs, and some of them move on four. Allah creates what He wills. Surely, Allah is powerful over everything.'),
(2837, 24, 46, 6, 12, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'لَقَدۡ اَنۡزَلۡنَاۤ  اٰیٰتٍ مُّبَیِّنٰتٍ ؕ وَ اللّٰہُ یَہۡدِیۡ مَنۡ  یَّشَآءُ   اِلٰی صِرَاطٍ مُّسۡتَقِیۡمٍ ﴿۴۶﴾', 'ہم ہی نے روشن آیتیں نازل کی ہیں اور اللہ جسکو چاہتا ہے سیدھے راستے کی طرف ہدایت کرتا ہے۔', 'ہم نے اتاریں آیتیں کھول کھول کر بتلانے والی اور اللہ چلائے جس کو چاہے سیدھی راہ پر [۹۳]', 'We have indeed sent down (in this Quran) manifest Ayat (proofs, evidences, verses, lessons, signs, revelations, lawful and unlawful things, and the set boundries of Islamic religion, etc. that make things clear showing the Right Path of Allah). And Allah guides whom He wills to a Straight Path (i.e. to Allahs religion of Islamic Monotheism).', 'We have surely sent down enlightening verses, and Allah guides whom He wills to the straight path.'),
(2838, 24, 47, 6, 12, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ یَقُوۡلُوۡنَ اٰمَنَّا بِاللّٰہِ وَ بِالرَّسُوۡلِ وَ اَطَعۡنَا ثُمَّ یَتَوَلّٰی فَرِیۡقٌ مِّنۡہُمۡ مِّنۡۢ بَعۡدِ ذٰلِکَ ؕ وَ مَاۤ   اُولٰٓئِکَ بِالۡمُؤۡمِنِیۡنَ ﴿۴۷﴾', 'اور بعض لوگ کہتے ہیں کہ ہم اللہ پر اور رسول پر ایمان لائے اور ان کا حکم مان لیا پھر اسکے بعد ان میں سے ایک فریق پھر جاتا ہے اور یہ لوگ صاحب ایمان ہی نہیں ہیں۔', 'اور لوگ کہتے ہیں ہم نے مانا اللہ کو اور رسول کو اور حکم میں آ گئے پھر پھر جاتا ہے ایک فرقہ ان میں سے اس کے پیچھے اور وہ لوگ نہیں ماننے والے [۹۴]', 'They (hypocrites) say: \"We have believed in Allah and in the Messenger (Muhammad SAW), and we obey,\" then a party of them turn away thereafter, such are not believers.', 'They say, “We have believed in Allah and in the messenger, and have adopted obedience”, then a group from them goes back after all this. Those are no believers.'),
(2839, 24, 48, 6, 12, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ اِذَا  دُعُوۡۤا اِلَی اللّٰہِ وَ رَسُوۡلِہٖ لِیَحۡکُمَ بَیۡنَہُمۡ  اِذَا فَرِیۡقٌ مِّنۡہُمۡ مُّعۡرِضُوۡنَ ﴿۴۸﴾', 'اور جب انکو اللہ اور اسکے رسول کی طرف بلایا جاتا ہے تاکہ پیغمبر ان کا قضیہ چکا دیں تو ان میں سے ایک فریق منہ پھیر لیتا ہے۔', 'اور جب ان کو بلائیے اللہ اور رسول کی طرف کہ ان میں قضیہ چکائے تبھی ایک فرقہ کے لوگ ان میں منہ موڑتے ہیں', 'And when they are called to Allah (i.e. His Words, the Quran) and His Messenger (SAW), to judge between them, lo! a party of them refuse (to come) and turn away.', 'When they are summoned to Allah and His messenger that he (the messenger) may judge between them, in no time a group of them turns averse.'),
(2840, 24, 49, 6, 12, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ اِنۡ یَّکُنۡ  لَّہُمُ الۡحَقُّ یَاۡتُوۡۤا اِلَیۡہِ مُذۡعِنِیۡنَ ﴿ؕ۴۹﴾', 'اور اگر انکو حق ملتا ہو تو اسکی طرف قبول کر کے چلے آتے ہیں۔', 'اور اگر ان کو کچھ پہنچتا ہو تو چلے آئیں اس کی طرف قبول کر کر [۹۵]', 'But if the right is with them, they come to him willingly with submission.', 'And if the right is theirs, they would come to him as (if they are) submissive ones.'),
(2841, 24, 50, 6, 12, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'اَفِیۡ  قُلُوۡبِہِمۡ مَّرَضٌ اَمِ ارۡتَابُوۡۤا اَمۡ یَخَافُوۡنَ اَنۡ یَّحِیۡفَ اللّٰہُ  عَلَیۡہِمۡ وَ رَسُوۡلُہٗ ؕ بَلۡ  اُولٰٓئِکَ  ہُمُ  الظّٰلِمُوۡنَ ﴿٪۵۰﴾', 'کیا انکے دلوں میں بیماری ہے یا یہ شک میں ہیں یا انکو یہ خوف ہے کہ اللہ اور اس کا رسول ان پر ظلم کریں گے؟ نہیں بلکہ یہ خود ہی ظالم ہیں۔', 'کیا انکے دلوں میں روگ ہے [۹۶] یا دھوکے میں پڑے ہوئے ہیں یا ڈرتے ہیں کہ بے انصافی کرے گا ان پر اللہ اور اس کا رسول کچھ نہیں وہی لوگ بے انصاف ہیں [۹۷]', 'Is there a disease in their hearts? Or do they doubt or fear lest Allah and His Messenger (SAW) should wrong them in judgement. Nay, it is they themselves who are the Zalimoon (polytheists, hypocrites and wrong-doers, etc.).', 'Is there a malady in their hearts or do they have doubt or do they fear that Allah and His messenger will do injustice to them? Rather they themselves are the unjust.'),
(2842, 24, 51, 7, 13, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'اِنَّمَا کَانَ  قَوۡلَ الۡمُؤۡمِنِیۡنَ  اِذَا دُعُوۡۤا اِلَی اللّٰہِ وَ رَسُوۡلِہٖ  لِیَحۡکُمَ بَیۡنَہُمۡ اَنۡ یَّقُوۡلُوۡا سَمِعۡنَا وَ اَطَعۡنَا ؕ وَ اُولٰٓئِکَ ہُمُ الۡمُفۡلِحُوۡنَ ﴿۵۱﴾', 'مومنوں کی تو یہ بات ہے کہ جب اللہ اور اسکے رسول کی طرف بلائے جائیں تاکہ وہ ان میں فیصلہ کریں تو کہیں کہ ہم نے حکم سن لیا اور مان لیا اور یہی لوگ فلاح پانے والے ہیں۔', 'ایمان والوں کی بات یہی تھی کہ جب بلائیے انکو اللہ اور رسول کی طرف فیصلہ کرنے کو ان میں تو کہیں ہم نے سن لیا اور حکم مان لیا اور وہ لوگ کہ انہی کا بھلا ہے [۹۸]', 'The only saying of the faithful believers, when they are called to Allah (His Words, the Quran) and His Messenger (SAW), to judge between them, is that they say: \"We hear and we obey.\" And such are the prosperous ones (who will live forever in Paradise).', 'The only reply of the (true) believers, when they are summoned to Allah and His messenger that he (the messenger) may judge between them, is that they say, “We listen and obey.” Such people are the successful.'),
(2843, 24, 52, 7, 13, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ مَنۡ یُّطِعِ اللّٰہَ وَ رَسُوۡلَہٗ  وَ یَخۡشَ اللّٰہَ  وَ یَتَّقۡہِ  فَاُولٰٓئِکَ  ہُمُ  الۡفَآئِزُوۡنَ ﴿۵۲﴾', 'اور جو شخص اللہ اور اسکے رسول کی فرمانبرداری کرے گا اور اس سے ڈرے گا اور اسکا تقویٰ اختیار کرے گا ایسے ہی لوگ مراد کو پہنچنے والے ہیں۔', 'اور جو کوئی حکم پر چلے اللہ کے اور اسکے رسول کے اور ڈرتا رہے اللہ سے اور بچکر چلے اس سے سو وہی لوگ ہیں مراد کو پہنچنے والے [۹۹]', 'And whosoever obeys Allah and His Messenger (SAW), fears Allah, and keeps his duty (to Him), such are the successful ones.', 'Whoever obeys Allah and His messenger and has awe of Him and observes Taqwā for His sake, then such people are the victorious.'),
(2844, 24, 53, 7, 13, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ اَقۡسَمُوۡا بِاللّٰہِ جَہۡدَ  اَیۡمَانِہِمۡ لَئِنۡ اَمَرۡتَہُمۡ  لَیَخۡرُجُنَّ ؕ قُلۡ لَّا تُقۡسِمُوۡا ۚ طَاعَۃٌ  مَّعۡرُوۡفَۃٌ ؕ اِنَّ اللّٰہَ خَبِیۡرٌۢ  بِمَا تَعۡمَلُوۡنَ ﴿۵۳﴾', 'اور یہ اللہ کی سخت سخت قسمیں کھاتے ہیں کہ اگر تم انکو حکم دو تو سب گھروں سے نکل کھڑے ہوں۔ کہدو کہ قسمیں مت کھاؤ پسندیدہ فرمانبرداری درکار ہے بیشک اللہ تمہارے سب اعمال سے خبردار ہے۔', 'اور قسمیں کھاتے ہیں اللہ کی اپنی تاکید کی قسمیں کہ اگر تو حکم کرےتو سب کچھ چھوڑ کر نکل جائیں تو کہہ قسمیں نہ کھاؤ حکمبرداری چاہئے جو دستور ہے البتہ اللہ کو خبر ہے جو تم کرتے ہو [۱۰۰]', 'They swear by Allah their strongest oaths, that if only you would order them, they would leave (their homes for fighting in Allahs Cause). Say: \"Swear you not; (this) obedience (of yours) is known (to be false). Verily, Allah knows well what you do.\"', 'And they (the hypocrites) swear by Allah on forceful oaths that if you (O prophet) order them, they will certainly leave (their homes for Jihād ). Say, “do not swear, (the reality of your) obedience is known. Indeed Allah is fully aware of what you do.”'),
(2845, 24, 54, 7, 13, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'قُلۡ اَطِیۡعُوا اللّٰہَ وَ اَطِیۡعُوا الرَّسُوۡلَ ۚ فَاِنۡ  تَوَلَّوۡا فَاِنَّمَا عَلَیۡہِ مَا حُمِّلَ وَ عَلَیۡکُمۡ مَّا حُمِّلۡتُمۡ ؕ وَ اِنۡ تُطِیۡعُوۡہُ تَہۡتَدُوۡا ؕ وَ مَا عَلَی الرَّسُوۡلِ  اِلَّا الۡبَلٰغُ الۡمُبِیۡنُ ﴿۵۴﴾', 'کہدو کہ اللہ کی فرمانبرداری کرو اور رسول کے حکم پر چلو۔ اگر منہ موڑو گے تو رسول پر اس چیز کا ادا کرنا ہے جو انکے ذمے ہے اور تم پر اس چیز کا ادا کرنا ہے جو تمہارے ذمے ہے اور اگر تم ان کے فرمان پر چلو گے تو سیدھا رستہ پا لو گے اور رسول کے ذمے تو صاف صاف پہنچا دینا ہے۔', 'تو کہہ حکم مانو اللہ کا اور حکم مانو رسول کا پھر اگر تم منہ پھیرو گے تو اس کا ذمہ ہے جو بوجھ اس پر رکھا اور تمہارا ذمہ ہے جو بوجھ تم پر رکھا اور اگر اس کا کہا مانو تو راہ پاؤ اور پیغام لانے والے کا ذمہ نہیں مگر پہنچا دینا کھول کر [۱۰۱]', 'Say: \"Obey Allah and obey the Messenger, but if you turn away, he (Messenger Muhammad SAW) is only responsible for the duty placed on him (i.e. to convey Allahs Message) and you for that placed on you. If you obey him, you shall be on the right guidance. The Messengers duty is only to convey (the message) in a clear way (i.e. to preach in a plain way).\"', 'Say, “Obey Allah and obey the messenger. But if you turn away, then on him (the messenger) lies (the responsibility of) what he is burdened with, and on you lies (the responsibility of) what you are burdened with. And if you obey him, you will get the right path. The duty of the Messenger is no more than to convey the message clearly.”'),
(2846, 24, 55, 7, 13, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَعَدَ  اللّٰہُ  الَّذِیۡنَ  اٰمَنُوۡا مِنۡکُمۡ وَ عَمِلُوا الصّٰلِحٰتِ لَیَسۡتَخۡلِفَنَّہُمۡ فِی الۡاَرۡضِ کَمَا اسۡتَخۡلَفَ الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ ۪ وَ لَیُمَکِّنَنَّ لَہُمۡ دِیۡنَہُمُ  الَّذِی ارۡتَضٰی لَہُمۡ وَ لَیُبَدِّلَنَّہُمۡ مِّنۡۢ بَعۡدِ خَوۡفِہِمۡ  اَمۡنًا ؕ یَعۡبُدُوۡنَنِیۡ لَا  یُشۡرِکُوۡنَ بِیۡ شَیۡئًا ؕ وَ مَنۡ  کَفَرَ بَعۡدَ ذٰلِکَ فَاُولٰٓئِکَ ہُمُ  الۡفٰسِقُوۡنَ ﴿۵۵﴾', 'جو لوگ تم میں سے ایمان لائے اور نیک کام کرتے رہے ان سے اللہ کا وعدہ ہے کہ انکو ملک کا حاکم بنا دے گا جیسا ان سے پہلے لوگوں کو حاکم بنایا تھا اور ان کے دین کو جسے اس نے ان کے لئے پسند کیا ہے مستحکم و پائدار کرے گا اور خوف کے بعد انکو امن بخشے گا۔ وہ میری عبادت کریں گے اور میرے ساتھ کسی چیز کو شریک نہ بنائیں گے۔ اور جو اسکے بعد کفر کرے تو ایسے ہی لوگ بدکردار ہیں۔', 'وعدہ کر لیا اللہ نے ان لوگوں سے جو تم میں ایمان لائے ہیں اور کئے ہیں انہوں نے نیک کام البتہ پیچھے حاکم کر دے گا انکو ملک میں جیسا حاکم کیا تھا ان سے اگلوں کو اور جما دے گا ان کے لئے دین ان کا جو پسند کر دیا انکے واسطے اور دے گا ان کو ان کے ڈر کے بدلے میں امن میری بندگی کریں گے شریک نہ کریں گے میرا کسی کو [۱۰۲] اور جو کوئی ناشکری کرے گا اسکے پیچھے سو  وہی لوگ ہیں نافرمان [۱۰۳]', 'Allah has promised those among you who believe, and do righteous good deeds, that He will certainly grant them succession to (the present rulers) in the earth, as He granted it to those before them, and that He will grant them the authority to practise their religion, that which He has chosen for them (i.e. Islam). And He will surely give them in exchange a safe security after their fear (provided) they (believers) worship Me and do not associate anything (in worship) with Me. But whoever disbelieved after this, they are the Fasiqoon (rebellious, disobedient to Allah).', 'Allah has promised those of you who believe and do good deeds that He will certainly make them (His) vicegerents in the land, as He made those before them, and will certainly establish for them their religion which He has chosen for them, and will certainly give them peace in place of fear in which they were before; (provided that) they worship Me, ascribing no partner to Me. And those who turn infidel after that are the transgressors.'),
(2847, 24, 56, 7, 13, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ اَقِیۡمُوا الصَّلٰوۃَ  وَ اٰتُوا الزَّکٰوۃَ وَ اَطِیۡعُوا الرَّسُوۡلَ لَعَلَّکُمۡ تُرۡحَمُوۡنَ ﴿۵۶﴾', 'اور نماز پڑھتے رہو اور زکوٰۃ دیتے رہو اور پیغمبر کے فرمان پر چلتے رہو تاکہ تم پر رحمت کی جائے۔', 'اور قائم رکھو نماز اور دیتے رہو زکوٰۃ اور حکم پر چلو رسول کے تاکہ تم پر رحم ہو [۱۰۴]', 'And perform AsSalat (IqamatasSalat), and give Zakat and obey the Messenger (Muhammad SAW) that you may receive mercy (from Allah).', 'Establish Salāh and pay Zakāh and obey the messenger, so that you may be favored with mercy.'),
(2848, 24, 57, 7, 13, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'لَا تَحۡسَبَنَّ الَّذِیۡنَ کَفَرُوۡا مُعۡجِزِیۡنَ فِی الۡاَرۡضِ ۚ وَ مَاۡوٰىہُمُ النَّارُ ؕ وَ لَبِئۡسَ الۡمَصِیۡرُ ﴿٪۵۷﴾', 'اور ایسا خیال نہ کرنا کہ کافر لوگ ہمکو زمین میں مغلوب کر دیں گے ان کا ٹھکانہ دوزخ ہے اور وہ بہت برا ٹھکانہ ہے۔', 'نہ خیال کر کہ یہ جو کافر ہیں تھکا دیں گے بھاگ کر ملک میں اور ان کا ٹھکانہ آگ ہے اور وہ بری جگہ ہے پھر جانے کی [۱۰۵]', 'Consider not that the disbelievers can escape in the land. Their abode shall be the Fire, and worst indeed is that destination.', 'Never think that the disbelievers are (able) to frustrate (Allah’s plan) on the earth. Their abode is the Fire. Indeed it is an evil terminus.'),
(2849, 24, 58, 8, 14, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لِیَسۡتَاۡذِنۡکُمُ الَّذِیۡنَ مَلَکَتۡ اَیۡمَانُکُمۡ وَ الَّذِیۡنَ لَمۡ  یَبۡلُغُوا  الۡحُلُمَ  مِنۡکُمۡ  ثَلٰثَ مَرّٰتٍ ؕ مِنۡ قَبۡلِ صَلٰوۃِ  الۡفَجۡرِ وَ حِیۡنَ تَضَعُوۡنَ ثِیَابَکُمۡ مِّنَ الظَّہِیۡرَۃِ وَ مِنۡۢ بَعۡدِ صَلٰوۃِ الۡعِشَآءِ ۟ؕ ثَلٰثُ عَوۡرٰتٍ لَّکُمۡ ؕ لَیۡسَ عَلَیۡکُمۡ وَ لَا عَلَیۡہِمۡ جُنَاحٌۢ بَعۡدَہُنَّ ؕ طَوّٰفُوۡنَ عَلَیۡکُمۡ بَعۡضُکُمۡ  عَلٰی بَعۡضٍ ؕ  کَذٰلِکَ یُبَیِّنُ اللّٰہُ  لَکُمُ  الۡاٰیٰتِ ؕ وَ اللّٰہُ  عَلِیۡمٌ حَکِیۡمٌ ﴿۵۸﴾', 'مومنو تمہارے باندی غلام اور جو بچے تم میں سے بلوغ کو نہیں پہنچے تین دفعہ یعنی تین اوقات میں تم سے اجازت لیا کریں۔ ایک تو نماز فجر سے پہلے اور دوسرے گرمی کی دوپہر کو جب تم کپڑے اتار دیتے ہو اور تیسرے عشاء کی نماز کے بعد یہ تین وقت تمہارے پردے کے ہیں انکے آگے پیچھے یعنی دوسرے وقتوں میں نہ تم پر کچھ گناہ ہے اور نہ ان پر کہ کام کاج کے لئے ایک دوسرے کے پاس آتے رہتے ہو۔ اس طرح اللہ اپنی آیتیں کھول کھول کر بیان فرماتا ہے اور اللہ بڑا علم والا ہے بڑا حکمت والا ہے۔', 'اے ایمان والو  اجازت لیکر آئیں تم سے جو تمہارےہاتھ کے مال ہیں [۱۰۶] اور جو کہ نہیں پہنچے تم میں عقل کی حد کو تین بار فجر کی نماز سے پہلے اور جب اتار رکھتے ہو اپنے کپڑے دوپہر میں اور عشاء کی نماز سے پیچھے یہ تین وقت بدن کھلنے کے ہیں تمہارے [۱۰۷] کچھ تنگی نہیں تم پر اور ان پر ان وقتوں کے پیچھے پھرا ہی کرتے ہو ایک دوسرے کے پاس [۱۰۸] یوں کھولتا ہے اللہ تمہارے آگے باتیں اور اللہ سب کچھ جاننے والا حکمت والا ہے', 'O you who believe! Let your legal slaves and slave-girls, and those among you who have not come to the age of puberty ask your permission (before they come to your presence) on three occasions; before Fajr (morning) prayer, and while you put off your clothes for the noonday (rest), and after the Isha (late-night) prayer. (These) three times are of privacy for you, other than these times there is no sin on you or on them to move about, attending (helping) you each other. Thus Allah makes clear the Ayat (the Verses of this Quran, showing proofs for the legal aspects of permission for visits, etc.) to you. And Allah is All-Knowing, All-Wise.', 'O you who believe, the slaves owned by you, and those of you who have not reached puberty, must seek your permission (to see you) at three times: before the prayer of Fajr, and when you take off your clothes at noon, and after the prayer of ‘Ishā’. These are three times of privacy for you. There is no harm, neither to you nor to them, after these (three times). They are your frequent visitors, as some of you are (frequent visitors) of the others. This is how Allah explains the verses to you. Allah is All-Knowing, All-Wise.'),
(2850, 24, 59, 8, 14, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ اِذَا بَلَغَ  الۡاَطۡفَالُ مِنۡکُمُ الۡحُلُمَ فَلۡیَسۡتَاۡذِنُوۡا کَمَا اسۡتَاۡذَنَ الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ ؕ کَذٰلِکَ یُبَیِّنُ اللّٰہُ  لَکُمۡ اٰیٰتِہٖ ؕ وَ اللّٰہُ  عَلِیۡمٌ  حَکِیۡمٌ ﴿۵۹﴾', 'اور جب تمہارے لڑکے بالغ ہو جائیں تو انکو بھی اسی طرح اجازت لینی چاہیے جس طرح ان سے اگلے یعنی بڑے آدمی اجازت حاصل کرتے رہے ہیں۔ اس طرح اللہ تم سے اپنی آیتیں کھول کھول کر بیان فرماتا ہے اور اللہ جاننے والا ہے حکمت والا ہے۔', 'اور جب پہنچیں لڑکے تم میں کے عقل کی حد کو تو انکو ویسی ہی اجازت لینی چاہئے جیسے لیتے رہے ہیں ان سے اگلے [۱۰۹] یوں کھول کر سناتا ہے اللہ تم کو اپنی باتیں اور اللہ سب کچھ جاننے والا حکمت والا ہے', 'And when the children among you come to puberty, then let them (also) ask for permission, as those senior to them (in age). Thus Allah makes clear His Ayat (Commandments and legal obligations) for you. And Allah is All-Knowing, All-Wise.', 'When the children from among you reach puberty, they must seek permission, as the permission is sought by those before them. This is how Allah explains His verses to you. Allah is All-Knowing, All-Wise.'),
(2851, 24, 60, 8, 14, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'وَ الۡقَوَاعِدُ مِنَ النِّسَآءِ الّٰتِیۡ  لَا یَرۡجُوۡنَ نِکَاحًا فَلَیۡسَ عَلَیۡہِنَّ جُنَاحٌ اَنۡ یَّضَعۡنَ ثِیَابَہُنَّ غَیۡرَ مُتَبَرِّجٰتٍۭ بِزِیۡنَۃٍ ؕ وَ اَنۡ یَّسۡتَعۡفِفۡنَ خَیۡرٌ   لَّہُنَّ ؕ وَ اللّٰہُ  سَمِیۡعٌ  عَلِیۡمٌ ﴿۶۰﴾', 'اور بڑی عمر کی عورتیں جنکو نکاح کی توقع نہیں رہی اور وہ  زائد کپڑے اتار کر سر ننگا کر لیا کریں تو ان پر کچھ گناہ نہیں بشرطیکہ اپنی زینت کی چیزیں نہ ظاہر کریں۔ اور اگر اس سے بھی بچیں تو یہ ان کے حق میں بہتر ہے اور اللہ سنتا ہے جانتا ہے۔', 'اور جو بیٹھ رہی ہیں گھروں میں تمہاری عورتوں میں سے جنکو توقع نہیں رہی نکاح کی ان  پرگناہ نہیں کہ اتار رکھیں اپنے کپڑے یہ نہیں کہ دکھاتی پھریں اپنا سنگار اور اس سے بھی بچیں تو بہتر ہے انکے لئے [۱۱۰] اور اللہ سب باتیں سنتا جانتا ہے [۱۱۱]', 'And as for women past child-bearing who do not expect wed-lock, it is no sin on them if they discard their (outer) clothing in such a way as not to show their adornment. But to refrain (i.e. not to discard their outer clothing) is better for them. And Allah is All-Hearer, All-Knower.', 'And those old women who have no hope for marriage, there is no sin on them, if they take off their (extra) clothes while they do not display their adornment. Still, that they refrain (even from this) is better for them. Allah is All-Hearing, All-Knowing.'),
(2852, 24, 61, 8, 14, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'لَیۡسَ عَلَی الۡاَعۡمٰی حَرَجٌ وَّ لَا عَلَی الۡاَعۡرَجِ حَرَجٌ وَّ لَا عَلَی الۡمَرِیۡضِ حَرَجٌ وَّ لَا عَلٰۤی  اَنۡفُسِکُمۡ اَنۡ تَاۡکُلُوۡا مِنۡۢ بُیُوۡتِکُمۡ اَوۡ بُیُوۡتِ اٰبَآئِکُمۡ  اَوۡ بُیُوۡتِ اُمَّہٰتِکُمۡ  اَوۡ  بُیُوۡتِ  اِخۡوَانِکُمۡ اَوۡ بُیُوۡتِ اَخَوٰتِکُمۡ  اَوۡ  بُیُوۡتِ اَعۡمَامِکُمۡ اَوۡ بُیُوۡتِ عَمّٰتِکُمۡ  اَوۡ  بُیُوۡتِ  اَخۡوَالِکُمۡ  اَوۡ بُیُوۡتِ خٰلٰتِکُمۡ  اَوۡ  مَا مَلَکۡتُمۡ مَّفَاتِحَہٗۤ  اَوۡ صَدِیۡقِکُمۡ ؕ لَیۡسَ عَلَیۡکُمۡ جُنَاحٌ  اَنۡ  تَاۡکُلُوۡا جَمِیۡعًا اَوۡ اَشۡتَاتًا ؕ فَاِذَا دَخَلۡتُمۡ بُیُوۡتًا فَسَلِّمُوۡا عَلٰۤی اَنۡفُسِکُمۡ تَحِیَّۃً مِّنۡ عِنۡدِ اللّٰہِ مُبٰرَکَۃً  طَیِّبَۃً ؕ کَذٰلِکَ یُبَیِّنُ اللّٰہُ لَکُمُ الۡاٰیٰتِ لَعَلَّکُمۡ تَعۡقِلُوۡنَ ﴿٪۶۱﴾', 'نہ تو اندھے پر کچھ گناہ ہے اور نہ لنگڑے پر اور نہ بیمار پر اور نہ خود تم پر کہ اپنے گھروں سے کھانا کھاؤ یا اپنے باپ دادا کے گھروں سے یا اپنی ماؤں کے گھروں سے یا بھائیوں کے گھروں سے یا اپنی بہنوں کے گھروں سے یا اپنے چچاؤں کے گھروں سے یا اپنی پھوپھیوں کے گھروں سے یا اپنے ماموؤں کے گھروں سے یا اپنی خالاؤں کے گھروں سے یا اس گھر سے جسکی کنجیاں تمہارے ہاتھ میں ہوں۔ یا اپنے دوستوں کے گھروں سے  اور اس کا بھی تم پر کچھ گناہ نہیں کہ سب مل کر کھانا کھاؤ یا جدا جدا پھر جب گھروں میں جایا کرو تو اپنے گھر والوں کو سلام کیا کرو یہ اللہ کی طرف سےمبارک اور پاکیزہ تحفہ ہے۔ اس طرح اللہ اپنی آیتیں کھول کھول کر بیان فرماتا ہے تاکہ تم سمجھو۔', 'نہیں ہے اندھے پر کچھ تکلیف اور نہ لنگڑے پر تکلیف اور نہ بیمار پر تکلیف [۱۱۲] اور نہیں تکلیف تم لوگوں پر کہ کھاؤ اپنے گھروں سے یا اپنے باپ کے گھر سے یا اپنی ماں کے گھر سے یا اپنے بھائی کے گھر سے یا اپنی بہن کے گھر سے یا اپنے چچا کے گھر سے یا اپنی پھوپھی کے گھر سے یا اپنے ماموں کے گھر سے یا اپنی خالہ کے گھر سے یا جس گھر کی کنجیوں کے تم مالک ہو یا اپنے دوست کے گھر سے [۱۱۳] نہیں گناہ تم پر کہ کھاؤ آپس میں مل کر یا جدا ہو کر پھر جب کبھی جانے لگو گھروں میں تو سلام کہو اپنے لوگوں پر نیک دعا ہے اللہ کے یہاں سے برکت والی ستھری یوں کھولتا ہے اللہ تمہارے آگے اپنی باتیں تاکہ تم سمجھ لو [۱۱۴]', 'There is no restriction on the blind, nor any restriction on the lame, nor any restriction on the sick, nor on yourselves, if you eat from your houses, or the houses of your fathers, or the houses of your mothers, or the houses of your brothers, or the houses of your sisters, or the houses of your fathers brothers, or the houses of your fathers sisters, or the houses of your mothers brothers, or the houses of your mothers sisters, or (from that) whereof you hold keys, or (from the house) of a friend. No sin on you whether you eat together or apart. But when you enter the houses, greet one another with a greeting from Allah (i.e. say: Úáíßã As-Salamu Alaikum - peace be on you) blessed and good. Thus Allah makes clear the Ayat (these Verses or your religious symbols and signs, etc.) to you that you may understand.', 'There is no blame on a blind person, nor is there any blame on any lame one, nor is there any blame on a sick person, nor on yourselves in that you eat (something) from your own homes or from the homes of your fathers or the homes of your mothers or the homes of your brothers or the homes of your sisters or the homes of your paternal uncles, or the homes of your paternal aunts or the homes of your maternal uncles or the homes of your maternal aunts or from the places the keys of which you have under your control,16 or from (the home of) your friend.There is no sin on you if you eat together or separately. So when you enter homes, greet one another with Salām , a greeting prescribed by Allah, which is blessed, pleasant. This is how Allah explains the verses to you, so that you may understand.'),
(2853, 24, 62, 9, 15, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'اِنَّمَا الۡمُؤۡمِنُوۡنَ الَّذِیۡنَ  اٰمَنُوۡا بِاللّٰہِ وَ رَسُوۡلِہٖ  وَ اِذَا کَانُوۡا مَعَہٗ عَلٰۤی  اَمۡرٍ جَامِعٍ  لَّمۡ   یَذۡہَبُوۡا حَتّٰی یَسۡتَاۡذِنُوۡہُ ؕ اِنَّ الَّذِیۡنَ یَسۡتَاۡذِنُوۡنَکَ اُولٰٓئِکَ  الَّذِیۡنَ یُؤۡمِنُوۡنَ بِاللّٰہِ وَ  رَسُوۡلِہٖ ۚ فَاِذَا اسۡتَاۡذَنُوۡکَ لِبَعۡضِ شَاۡنِہِمۡ فَاۡذَنۡ  لِّمَنۡ شِئۡتَ مِنۡہُمۡ وَ اسۡتَغۡفِرۡ لَہُمُ اللّٰہَ ؕ اِنَّ اللّٰہَ  غَفُوۡرٌ  رَّحِیۡمٌ ﴿۶۲﴾', 'مومن تو وہ ہیں جو اللہ پر اور اسکے رسول پر ایمان لائے اور جب کبھی ایسے کام کے لئے جو جمع ہو کر کرنے کا ہو پیغمبر کے پاس جمع ہوں تو ان سے اجازت لئے بغیر چلے نہیں جاتے اے پیغمبر جو لوگ تم سے اجازت حاصل کرتے ہیں وہی اللہ پر اور اسکے رسول پر ایمان رکھتے ہیں۔ سو جب یہ لوگ تم سے کسی کام کے لئے اجازت مانگا کریں تو ان میں سے جسے چاہا کرو اجازت دے دیا کرو اور انکے لئے اللہ سے بخشش مانگا کرو۔ کچھ شک نہیں کہ اللہ بخشنے والا ہے مہربان ہے۔', 'ایمان والے وہ ہیں جو یقین لائے اللہ پر اور اسکے رسول پر اور جب ہوتے ہیں اس کے ساتھ کسی جمع ہونے کے کام میں تو چلے نہیں جاتے جب تک اس سے اجازت نہ لے لیں جو لوگ تجھ سے اجازت لیتے ہیں وہی ہیں جو مانتے ہیں اللہ کو اور اس کے رسول کو [۱۱۵] پھر جب اجازت مانگیں تجھ سے اپنے کسی کام کے لئے تو اجازت دے جس کو ان میں سے تو چاہے اور معافی مانگ انکے واسطے اللہ سے اللہ بخشنے والا مہربان ہے [۱۱۶]', 'The true believers are only those, who believe in (the Oneness of) Allah and His Messenger (Muhammad SAW), and when they are with him on some common matter, they go not away until they have asked his permission. Verily! Those who ask your permission, those are they who (really) believe in Allah and His Messenger. So if they ask your permission for some affairs of theirs, give permission to whom you will of them, and ask Allah for their forgiveness. Truly, Allah is Oft-Forgiving, Most Merciful.', 'The believers are only those who believe in Allah and His messenger and who, when they are with him for a collective matter, do not leave unless they seek his permission. Surely, those who seek your permission are the ones who believe in Allah and His messenger. So, if they seek permission from you for some business of theirs, give permission to whom you wish from among them, and pray to Allah for their forgiveness. Surely, Allah is Most-Forgiving, Very-Merciful.'),
(2854, 24, 63, 9, 15, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'لَا تَجۡعَلُوۡا دُعَآءَ الرَّسُوۡلِ بَیۡنَکُمۡ کَدُعَآءِ  بَعۡضِکُمۡ  بَعۡضًا ؕ قَدۡ یَعۡلَمُ  اللّٰہُ  الَّذِیۡنَ  یَتَسَلَّلُوۡنَ مِنۡکُمۡ  لِوَاذًا ۚ فَلۡیَحۡذَرِ الَّذِیۡنَ یُخَالِفُوۡنَ عَنۡ اَمۡرِہٖۤ  اَنۡ تُصِیۡبَہُمۡ فِتۡنَۃٌ  اَوۡ یُصِیۡبَہُمۡ عَذَابٌ  اَلِیۡمٌ ﴿۶۳﴾', 'مومنو پیغمبر کے پکارنے کو ایسا خیال نہ کرنا جیسا تم آپس میں ایک دوسرے کو  پکارنے ہو۔ بیشک اللہ کو وہ لوگ معلوم ہیں جو تم میں سے آنکھ بچا کر کھسک جاتے ہیں۔ تو جو لوگ انکے حکم کی مخالفت کرتے ہیں انکو ڈرنا چاہیے کہ ایسا نہ ہو کہ ان پر کوئی آفت پڑ جائے یا تکلیف دینے والا عذاب نازل ہو۔', 'مت کو لو بلانا رسول کا اپنے اندر برابر اسکے جو بلاتا ہے تم میں ایک دوسرے کو [۱۱۷] اللہ جانتا ہے ان لوگوں کو تم میں سے جو سٹک جاتے ہیں آنکھ بچا کر [۱۱۸] سو ڈرتے رہیں وہ لوگ جو خلاف کرتے ہیں اس کے حکم کا اس سے کہ آپڑے ان پر کچھ خرابی یا پہنچے ان کو عذاب دردناک [۱۱۱۹]', 'Make not the calling of the Messenger (Muhammad SAW) among you as your calling of one another. Allah knows those of you who slip away under shelter (of some excuse without taking the permission to leave, from the Messenger SAW). And let those who oppose the Messengers (Muhammad SAW) commandment (i.e. his Sunnah legal ways, orders, acts of worship, statements, etc.) (among the sects) beware, lest some Fitnah (disbelief, trials, afflictions, earthquakes, killing, overpowered by a tyrant, etc.) befall them or a painful torment be inflicted on them.', 'Do not take the call of the messenger among you as a call of one of you to another. Allah definitely knows those of you who sneak out hiding themselves under the cover of others. So, those who violate his (messenger’s) order must beware, lest they are visited by a trial or they are visited by a painful punishment.'),
(2855, 24, 64, 9, 15, 18, 'قَدۡ  اَفۡلَحَ ', 'النور', 'اَلَاۤ  اِنَّ لِلّٰہِ مَا فِی السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ قَدۡ یَعۡلَمُ مَاۤ  اَنۡتُمۡ عَلَیۡہِ ؕ وَ یَوۡمَ یُرۡجَعُوۡنَ  اِلَیۡہِ  فَیُنَبِّئُہُمۡ بِمَا عَمِلُوۡا ؕ وَ اللّٰہُ  بِکُلِّ  شَیۡءٍ  عَلِیۡمٌ ﴿٪۶۴﴾', 'دیکھو جو کچھ آسمانوں اور زمین میں ہے سب اللہ ہی کا ہے جس طریق پر تم ہو وہ اسے جانتا ہے اور جس روز لوگ اسکی طرف لوٹائے جائیں گے تو جو عمل وہ کرتے رہے وہ ان کو بتا دے گا۔ اور اللہ ہر چیز سے واقف ہے۔', 'سنتے ہو اللہ ہی کا ہے جو کچھ ہے آسمانوں اور زمین میں اس کو معلوم ہے جس حال پر تم ہو اور جس دن پھیرےجائیں گے اس کی طرف تو بتائے گا ان کو جو کچھ انہوں نے کیا اور اللہ ہر ایک چیز کو جانتا ہے [۱۲۰]', 'Certainly, to Allah belongs all that is in the heavens and the earth. Surely, He knows your condition and (He knows) the Day when they will be brought back to Him, then He will inform them of what they did. And Allah is All-Knower of everything.', 'Remember! To Allah belongs all that is there in the heavens and the earth. He knows the condition in which you are at present; and the Day on which they will be returned to Him, He will tell them what they did. Allah is fully aware of everything.'),
(2856, 25, 1, 1, 16, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'تَبٰرَکَ الَّذِیۡ نَزَّلَ الۡفُرۡقَانَ عَلٰی عَبۡدِہٖ لِیَکُوۡنَ  لِلۡعٰلَمِیۡنَ  نَذِیۡرَا ۙ﴿۱﴾', 'وہ ذات بہت ہی بابرکت ہے جس نے اپنے بندے پر قرآن نازل فرمایا تاکہ اہل عالم کو خبردار کرے۔', 'بڑی برکت ہے اسکی جس نے اتاری فیصلہ کی کتاب [۱] اپنے بندہ پر [۲] تاکہ رہے جہان والوں کے لئے ڈرانے والا [۳]', 'Blessed be He Who sent down the criterion (of right and wrong, i.e. this Quran) to His slave (Muhammad SAW) that he may be a warner to the Alameen (mankind and jinns).', 'Glorious is the One who has revealed the Criterion to His servant, so that he may be a warner to all the worlds,'),
(2857, 25, 2, 1, 16, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'ۣالَّذِیۡ لَہٗ  مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ لَمۡ  یَتَّخِذۡ وَلَدًا وَّ لَمۡ  یَکُنۡ لَّہٗ شَرِیۡکٌ فِی الۡمُلۡکِ وَ خَلَقَ کُلَّ شَیۡءٍ فَقَدَّرَہٗ تَقۡدِیۡرًا ﴿۲﴾', 'وہی کہ آسمانوں اور زمین کی بادشاہی اسی کی ہے اور جس نے کسی کو بیٹا نہیں بنایا اور جس کا بادشاہی میں کوئی شریک نہیں اور جس نے ہر چیز کو پیدا کیا پھر اس کا ایک اندازہ ٹھہرایا۔', 'وہ کہ جس کی ہے سلطنت آسمان اور زمین میں اور نہیں پکڑا اس نے بیٹا اور نہیں کوئی اس کا ساجھی سلطنت میں اور بنائی ہر چیز  پھر ٹھیک کیا اسکو ماپ کر [۴]', 'He to Whom belongs the dominion of the heavens and the earth, and Who has begotten no son (children or offspring) and for Whom there is no partner in the dominion. He has created everything, and has measured it exactly according to its due measurements.', 'the One to whom belongs the kingdom of the heavens and the earth, and who did neither have a son, nor is there any partner to him in the Kingdom, and who has created everything and designed it in a perfect measure.'),
(2858, 25, 3, 1, 16, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'وَ اتَّخَذُوۡا مِنۡ دُوۡنِہٖۤ  اٰلِہَۃً  لَّا یَخۡلُقُوۡنَ شَیۡئًا وَّ ہُمۡ یُخۡلَقُوۡنَ وَ لَا یَمۡلِکُوۡنَ لِاَنۡفُسِہِمۡ ضَرًّا وَّ لَا نَفۡعًا وَّ لَا یَمۡلِکُوۡنَ مَوۡتًا  وَّ لَا حَیٰوۃً   وَّ  لَا نُشُوۡرًا ﴿۳﴾', 'اور لوگوں نے اسکے سوا اور معبود بنا لئے ہیں جو کوئی چیز بھی پیدا نہیں کر سکتے اور خود پیدا کئے گئے ہیں۔ اور نہ اپنے لئے نقصان کا اور نہ نفع کا کچھ اختیار رکھتے ہیں اور نہ مرنا انکے اختیار میں ہے اور نہ جینا اور نہ مر کر اٹھ کھڑے ہونا۔', 'اور لوگوں نے پکڑ رکھے ہیں اس سے ورے کتنے حاکم جو نہیں بناتے کچھ چیز اور وہ خود بنائے گئے ہیں اور نہیں مالک اپنے حق میں برے کے اور نہ بھلے کے اور نہیں مالک مرنے کے اور نہ جینے کے اور نہ جی اٹھنے کے [۵]', 'Yet they have taken besides Him other aliha (gods) that created nothing but are themselves created, and possess neither hurt nor benefit for themselves, and possess no power (of causing) death, nor (of giving) life, nor of raising the dead.', 'Yet they have adopted other gods, beside Him, who do not create any thing, as they themselves are created, and they possess no power to cause harm or benefit even to themselves, nor do they have any control over death or life or resurrection.'),
(2859, 25, 4, 1, 16, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'وَ قَالَ الَّذِیۡنَ  کَفَرُوۡۤا اِنۡ ہٰذَاۤ  اِلَّاۤ  اِفۡکُۨ افۡتَرٰىہُ وَ اَعَانَہٗ  عَلَیۡہِ  قَوۡمٌ   اٰخَرُوۡنَ ۚۛ فَقَدۡ  جَآءُوۡ  ظُلۡمًا  وَّ  زُوۡرًا ۚ﴿ۛ۴﴾', 'اور کافر کہتے ہیں کہ یہ قرآن من گھڑت باتیں ہیں جو اس مدعی رسالت نے بنا لی ہیں۔ اور کچھ دوسرے لوگوں نے اس میں اسکی مدد کی ہے۔ یہ لوگ ایسا کہنے سے ظلم اور جھوٹ پر اتر آئے ہیں۔', 'اور کہنے لگے جو منکر ہیں اور کچھ نہیں ہے یہ مگر طوفان باندھ لایا ہے اور ساتھ دیا ہے اس کا اس میں اور لوگوں نے [۶] سو آگئے بے انصافی اور جھوٹ پر [۷]', 'Those who disbelieve say: \"This (the Quran) is nothing but a lie that he (Muhammad SAW) has invented, and others have helped him at it, so that they have produced an unjust wrong (thing) and a lie.\"', 'The disbelievers said, “This is nothing but a lie he (the messenger) has fabricated and some other people have helped him in it.” Thus they came up with sheer injustice and falsehood.'),
(2860, 25, 5, 1, 16, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'وَ قَالُوۡۤا اَسَاطِیۡرُ الۡاَوَّلِیۡنَ اکۡتَتَبَہَا فَہِیَ تُمۡلٰی عَلَیۡہِ  بُکۡرَۃً   وَّ اَصِیۡلًا ﴿۵﴾', 'اور کہتے ہیں کہ یہ پہلے لوگوں کی کہانیاں ہیں جنکو اس نے جمع کر رکھا ہے اور وہ صبح و شام اسکو لکھوائی جاتی ہیں۔', 'اور کہنے لگے یہ نقلیں ہیں پہلوں کی جنکو اس نے لکھ رکھا ہے سو وہی لکھوائی جاتی ہیں اس کے پاس صبح اور شام [۸]', 'And they say: \"Tales of the ancients, which he has written down, and they are dictated to him morning and afternoon.\"', 'And they said, “(These are) the tales of the ancients he (the messenger) has caused to be written, and they are read out to him at morn and eve.”'),
(2861, 25, 6, 1, 16, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'قُلۡ اَنۡزَلَہُ الَّذِیۡ یَعۡلَمُ السِّرَّ فِی السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ اِنَّہٗ  کَانَ غَفُوۡرًا  رَّحِیۡمًا ﴿۶﴾', 'کہدو کہ اسکو اس نے اتارا ہے جو آسمانوں اور زمین کی پوشیدہ باتوں کو جانتا ہے۔ بیشک وہ بخشنے والا ہے مہربان ہے۔', 'تو کہہ اسکو اتارا ہے اس نے جو جانتا ہے چھپے ہوئے بھید آسمانوں اور زمین میں [۹] بیشک وہ بخشنے والا مہربان ہے [۱۰]', 'Say: \"It (this Quran) has been sent down by Him (Allah) (the Real Lord of the heavens and earth) Who knows the secret of the heavens and the earth. Truly, He is Oft-Forgiving, Most Merciful.\"', 'Say, “It is sent down by the One who knows the secret in the heavens and the earth. Indeed He is Most-Forgiving, Very-Merciful.'),
(2862, 25, 7, 1, 16, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'وَ قَالُوۡا مَالِ ہٰذَا الرَّسُوۡلِ یَاۡکُلُ الطَّعَامَ وَ یَمۡشِیۡ  فِی الۡاَسۡوَاقِ ؕ لَوۡ لَاۤ اُنۡزِلَ اِلَیۡہِ مَلَکٌ فَیَکُوۡنَ مَعَہٗ نَذِیۡرًا ۙ﴿۷﴾', 'اور کہتے ہیں یہ کیسا پیغمبر ہے کہ کھانا کھاتا ہے اور بازاروں میں چلتا پھرتا ہے۔ اس پر کوئی فرشتہ کیوں نازل نہیں کیا گیا کہ اسکے ساتھ خبردار کرنے کو رہتا۔', 'اور کہنے لگے یہ کیسا رسول ہے کھاتا ہے کھانا اور پھرتا ہے بازاروں میں [۱۱] کیوں نہ اترا اسکی طرف کوئی فرشتہ کہ رہتا اس کے ساتھ ڈرانے کو', 'And they say: \"Why does this Messenger (Muhammad SAW) eat food, and walk about in the markets (like ourselves). Why is not an angel sent down to him to be a warner with him?', 'They said, “What sort of messenger is this who eats food and walks in the markets? Why is it that an angel has not been sent down to him who would have been a warner along with him.'),
(2863, 25, 8, 1, 16, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'اَوۡ یُلۡقٰۤی اِلَیۡہِ کَنۡزٌ اَوۡ تَکُوۡنُ لَہٗ جَنَّۃٌ یَّاۡکُلُ مِنۡہَا ؕ وَ قَالَ الظّٰلِمُوۡنَ  اِنۡ تَتَّبِعُوۡنَ   اِلَّا  رَجُلًا  مَّسۡحُوۡرًا ﴿۸﴾', 'یا اسکی طرف آسمان سے خزانہ اتارا جاتا یا اس کا کوئی باغ ہوتا کہ اس میں سے کھایا کرتا۔ اور ظالم کہتے ہیں کہ تم تو ایک جادو زدہ شخص کہ پیروی کرتے ہو۔', 'یا آ پڑتا اسکے پاس خزانہ یا ہو جاتا اس کے لئے ایک باغ کہ کھایا کرتا اس میں سے [۱۲] اور کہنے لگے بے انصاف تم پیروی کرتے ہو اس ایک مرد جادو مارے کی [۱۳]', '\"Or (why) has not a treasure been granted to him, or why has he not a garden whereof he may eat?\" And the Zalimoon (polytheists and wrong-doers, etc.) say: \"You follow none but a man bewitched.\"', 'Or a treasure should have been thrown down to him, or he should have a garden to eat from it?” And the transgressors said (to the believers,) “You are following none but a bewitched man.”'),
(2864, 25, 9, 1, 16, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'اُنۡظُرۡ کَیۡفَ ضَرَبُوۡا لَکَ الۡاَمۡثَالَ فَضَلُّوۡا  فَلَا  یَسۡتَطِیۡعُوۡنَ سَبِیۡلًا ﴿٪۹﴾', 'اے پیغمبر دیکھو تو یہ تمہارے بارے میں کس کس طرح کی باتیں کرتے ہیں سو گمراہ ہو گئے اور رستہ نہیں پا سکتے۔', 'دیکھ کیسی بٹھلاتےہیں تجھ پر مثلیں سو بہک گئے اب پا نہیں سکتے راستہ [۱۴]', 'See how they coin similitudes for you, so they have gone astray, and they cannot find a (Right) Path.', 'See how they coined similes for you, so they have gone astray and cannot find a way.'),
(2865, 25, 10, 2, 17, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'تَبٰرَکَ الَّذِیۡۤ  اِنۡ شَآءَ جَعَلَ لَکَ خَیۡرًا مِّنۡ ذٰلِکَ جَنّٰتٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ ۙ وَ  یَجۡعَلۡ  لَّکَ  قُصُوۡرًا ﴿۱۰﴾', 'وہ اللہ بہت بابرکت ہے جو اگر چاہے تو تمہارے لئے اس سے بہتر چیزیں بنا دے یعنی باغات جنکے نیچے نہریں بہ رہی ہوں نیز تمہارے لئے محل بنا دے۔', 'بڑی برکت ہے اسکی جو چاہے تو کر دے تیرے واسطے اس سے بہتر باغ کہ نیچے بہتی ہیں ان کے نہریں اور کر دے تیرے واسطے محل [۱۵]', 'Blessed be He Who, if He will, will assign you better than (all) that, - Gardens under which rivers flow (Paradise) and will assign you palaces (i.e. in Paradise).', 'Glorious is the One who, if He so wills, would give you better than that - gardens beneath which rivers flow, and would give you palaces.'),
(2866, 25, 11, 2, 17, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'بَلۡ  کَذَّبُوۡا بِالسَّاعَۃِ ۟ وَ  اَعۡتَدۡنَا لِمَنۡ کَذَّبَ بِالسَّاعَۃِ سَعِیۡرًا ﴿ۚ۱۱﴾', 'بلکہ یہ تو قیامت ہی کو جھٹلاتے ہیں اور ہم نے قیامت کے جھٹلانے والوں کے لئے دوزخ تیار کر رکھی ہے۔', 'کچھ نہیں وہ جھٹلاتے ہیں قیامت کو اور ہم نے تیار کی ہے اسکے واسطے کہ جھٹلاتا ہے قیامت کو آگ [۱۶]', 'Nay, they deny the Hour (the Day of Resurrection), and for those who deny the Hour, We have prepared a flaming Fire (i.e. Hell).', 'But they have disbelieved the Hour (the Day of Judgment) and for those who disbelieve the Hour, We have prepared a flaming fire.'),
(2867, 25, 12, 2, 17, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'اِذَا  رَاَتۡہُمۡ مِّنۡ مَّکَانٍۭ بَعِیۡدٍ سَمِعُوۡا  لَہَا تَغَیُّظًا وَّ  زَفِیۡرًا ﴿۱۲﴾', 'جس وقت وہ انکو دور سے دیکھی گی تو غضبناک ہو رہی ہو گی اور یہ اسکے جوش غضب اور چیخنے چلانے کو سنیں گے۔', 'جب وہ دیکھے گی ان کو دور کی جگہ سے  سنیں گے اس کا جھنجلانا اور چلانا [۱۷]', 'When it (Hell) sees them from a far place, they will hear its raging and its roaring.', 'When it will see them from a distant place, they will hear (the sounds of) its raging and breathing,'),
(2868, 25, 13, 2, 17, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'وَ اِذَاۤ  اُلۡقُوۡا مِنۡہَا مَکَانًا ضَیِّقًا مُّقَرَّنِیۡنَ  دَعَوۡا  ہُنَالِکَ ثُبُوۡرًا ﴿ؕ۱۳﴾', 'اور جب یہ دوزخ کی کسی تنگ جگہ میں زنجیروں میں جکڑ کر ڈالے جائیں گے تو وہاں موت کو پکاریں گے۔', 'اور جب ڈالے جائیں گے اس کے اندر ایک جگہ تنگ میں ایک زنجیر میں کئ کئی بندھے ہوئے پکاریں گے اس جگہ موت کو [۱۸]', 'And when they shall be thrown into a narrow place thereof, chained together, they will exclaim therein for destruction.', 'and when they will be thrown into a narrow place therein, while they will be chained together, they will call for death.'),
(2869, 25, 14, 2, 17, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'لَا تَدۡعُوا الۡیَوۡمَ ثُبُوۡرًا وَّاحِدًا وَّ ادۡعُوۡا ثُبُوۡرًا کَثِیۡرًا ﴿۱۴﴾', 'آج ایک ہی موت کو نہ پکارو اور بہت سی موتوں کو پکارو۔', 'مت پکارو آج ایک مرنے کو اور پکارو بہت سے مرنے کو [۱۹]', 'Exclaim not today for one destruction, but exclaim for many destructions.', '(Then it will be said to them,) “Do not call for one death today, but call for many a death.”'),
(2870, 25, 15, 2, 17, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'قُلۡ اَذٰلِکَ خَیۡرٌ اَمۡ جَنَّۃُ  الۡخُلۡدِ الَّتِیۡ وُعِدَ الۡمُتَّقُوۡنَ ؕ کَانَتۡ لَہُمۡ جَزَآءً وَّ مَصِیۡرًا ﴿۱۵﴾', 'پوچھو کہ یہ بہتر ہے یا ہمیشہ کی جنت جس کا پرہیزگاروں سے وعدہ ہے۔ یہ انکے اعمال کا بدلہ اور رہنے کا ٹھکانہ ہو گا۔', 'تو کہہ بھلا یہ چیز بہتر ہے یا باغ ہمیشہ رہنے کا جس کا وعدہ ہو چکا پرہیزگاروں سے [۲۰] وہ ہو گا ان کا بدلہ اور پھر جانے کی جگہ', 'Say: (O Muhammad SAW) \"Is that (torment) better or the Paradise of Eternity promised to the Muttaqoon (pious and righteous persons - see V.2:2)?\" It will be theirs as a reward and as a final destination.', 'Say, “Is that better or the eternal paradise the God-fearing are promised?” It will be a reward for them and a final abode.'),
(2871, 25, 16, 2, 17, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'لَہُمۡ فِیۡہَا مَا یَشَآءُوۡنَ خٰلِدِیۡنَ ؕ کَانَ عَلٰی رَبِّکَ  وَعۡدًا  مَّسۡـُٔوۡلًا ﴿۱۶﴾', 'وہاں جو چاہیں گے انکے لئے میسر ہو گا ہمیشہ اس میں رہیں گے یہ وعدہ اللہ کو پورا کرنا لازم ہے اور اس لائق ہے کہ مانگ لیا جائے۔', 'انکے واسطے وہاں ہے جو وہ چاہیں [۲۱] رہا کریں ہمیشہ ہو چکا تیرے رب کے ذمہ وعدہ مانگا ملتا [۲۲]', 'For them there will be therein all that they desire, and they will abide (there forever). It is a promise binding upon your Lord that must be fulfilled.', 'For them there will be whatever they wish, while they will be eternal. This is a promise undertaken by your Lord, (the fulfillment of) which is worth praying for.'),
(2872, 25, 17, 2, 17, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'وَ یَوۡمَ یَحۡشُرُہُمۡ وَ مَا یَعۡبُدُوۡنَ مِنۡ دُوۡنِ اللّٰہِ فَیَقُوۡلُ ءَاَنۡتُمۡ اَضۡلَلۡتُمۡ عِبَادِیۡ ہٰۤؤُلَآءِ اَمۡ ہُمۡ ضَلُّوا السَّبِیۡلَ ﴿ؕ۱۷﴾', 'اور جس دن اللہ انکو اور انکو جنہیں یہ اللہ کے سوا پوجتے ہیں جمع کرے گا تو فرمائے گا کیا تم نے میرے ان بندوں کو گمراہ کیا تھا یا یہ خود گمراہ ہو گئے تھے۔', 'اور جس دن جمع کر بلائے گا انکو اور جنکو وہ  پوجتے ہیں اللہ کے سوائے پھر ان سے کہے گا کیا تم نے بہکایا میرے ان بندوں کو یا وہ آپ بہکے راہ سے [۲۳]', 'And on the Day when He will gather them together and that which they worship besides Allah (idols, angels, pious men, saints, Iesa (Jesus) son of Maryam (Mary), etc.). He will say: \"Was it you who misled these My slaves or did they (themselves) stray from the (Right) Path?\"', '(Remember) the Day when He will gather them and what they used to worship beside Allah and will say (to the latter ones), “Did you mislead these My servants, or did they themselves lose the way?”'),
(2873, 25, 18, 2, 17, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'قَالُوۡا سُبۡحٰنَکَ مَا کَانَ یَنۡۢبَغِیۡ لَنَاۤ  اَنۡ نَّتَّخِذَ مِنۡ دُوۡنِکَ مِنۡ  اَوۡلِیَآءَ  وَ لٰکِنۡ مَّتَّعۡتَہُمۡ وَ اٰبَآءَہُمۡ حَتّٰی نَسُوا الذِّکۡرَ ۚ وَ کَانُوۡا  قَوۡمًۢا  بُوۡرًا ﴿۱۸﴾', 'وہ کہیں گے تو پاک ہے ہمیں یہ بات شایاں نہ تھی کہ تیرے سوا اوروں کو دوست بناتے۔ لیکن تو نے ہی انکو اور انکے باپ دادا کو برتنے کو نعمتیں دیں یہاں تک کہ وہ تیری یاد کو بھول گئے اور یہ ہلاک ہونے والے لوگ تھے۔', 'بولیں گے تو پاک ہے ہم سے بن نہ آتا تھا کہ پکڑ لیں کسی کو تیرے بغیر رفیق [۲۴] لیکن تو ان کو فائدہ پہنچاتا رہا اور انکے باپ دادوں کو یہاں تک کہ بھلا بیٹھے تیری یاد اور یہ تھے لوگ تباہ ہونے والے [۲۵]', 'They will say: \"Glorified be You! It was not for us to take any Auliya (Protectors, Helpers, etc.) besides You, but You gave them and their fathers comfort till they forgot the warning, and became a lost people (doomed to total loss).', 'They will say, “Pure are You. It was not for us to adopt other guardians than You. Instead, You gave them and their fathers (worldly) benefits till they forgot the advice, and became a ruined people.”'),
(2874, 25, 19, 2, 17, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'فَقَدۡ کَذَّبُوۡکُمۡ بِمَا تَقُوۡلُوۡنَ ۙ فَمَا تَسۡتَطِیۡعُوۡنَ صَرۡفًا وَّ لَا نَصۡرًا ۚ وَ مَنۡ یَّظۡلِمۡ  مِّنۡکُمۡ  نُذِقۡہُ عَذَابًا کَبِیۡرًا ﴿۱۹﴾', 'تو کافرو انہوں نے تو تم کو تمہاری بات میں جھٹلا دیا۔ پس اب تم عذاب کو نہ پھیر سکتے ہو نہ کسی سے مدد لے سکتے ہو۔ اور جو شخص تم میں سے ظلم کرے گا ہم اسکو بڑے عذاب کا مزہ چکھائیں گے۔', 'سو وہ تو جھٹلا چکے تم کو تمہاری بات میں [۲۶] اب نہ تم لوٹا سکتے ہو اور نہ مدد کر سکتے ہو [۲۷] اور جو کوئی تم میں گنہگار ہے اس کو ہم چکھائیں گے بڑ اعذاب [۲۸]', 'Thus they (false gods all deities other than Allah) will give you (polytheists) the lie regarding what you say (that they are gods besides Allah), then you can neither avert (the punishment), nor get help. And whoever among you does wrong (i.e. sets up rivals to Allah), We shall make him taste a great torment.', 'Thus they will refute you in what you say, and you will not be able to repulse (the punishment,) or to receive help. Whoever commits injustice from among you, We will make him taste a painful punishment.'),
(2875, 25, 20, 2, 17, 18, 'قَدۡ  اَفۡلَحَ ', 'الفرقان', 'وَ مَاۤ  اَرۡسَلۡنَا قَبۡلَکَ مِنَ الۡمُرۡسَلِیۡنَ  اِلَّاۤ  اِنَّہُمۡ لَیَاۡکُلُوۡنَ الطَّعَامَ وَ  یَمۡشُوۡنَ فِی الۡاَسۡوَاقِ ؕ وَ جَعَلۡنَا بَعۡضَکُمۡ لِبَعۡضٍ فِتۡنَۃً ؕ اَتَصۡبِرُوۡنَ ۚ وَ کَانَ رَبُّکَ بَصِیۡرًا ﴿٪۲۰﴾', 'اور ہم نے تم سے پہلے جتنے پیغمبر بھیجے ہیں سب کھانا کھاتے تھے اور بازاروں میں چلتے پھرتے تھے اور ہم نے تمہیں ایک دوسرے کے لئے آزمائش بنایا۔ کیا تم لوگ صبر کرو گے اور تمہارا پروردگار تو دیکھنے والا ہے۔', 'اور جتنے بھیجے ہم نے تجھ سے پہلے رسول سب کھاتے تھے کھانا اور پھرتے تھے بازاروں میں [۲۹] اور ہم نے رکھا ہے تم میں ایک دوسرے کے جانچنے کو دیکھیں ثابت بھی رہتے ہو [۳۰] اور تیرا رب سب کچھ دیکھتا ہے [۳۱]', 'And We never sent before you (O Muhammad SAW) any of the Messengers but verily, they ate food and walked in the markets. And We have made some of you as a trial for others: will you have patience? And your Lord is Ever All-Seer (of everything).', 'We did not send any messengers before you (O prophet,) but all of them used to eat food and walk in the markets. And We have made some of you a test for some others. Would you observe patience? And your Lord is Ever-seeing.'),
(2876, 25, 21, 3, 1, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ قَالَ الَّذِیۡنَ لَا یَرۡجُوۡنَ لِقَآءَنَا لَوۡ لَاۤ اُنۡزِلَ عَلَیۡنَا الۡمَلٰٓئِکَۃُ  اَوۡ  نَرٰی رَبَّنَا ؕ لَقَدِ اسۡتَکۡبَرُوۡا فِیۡۤ  اَنۡفُسِہِمۡ وَ عَتَوۡ عُتُوًّا کَبِیۡرًا ﴿۲۱﴾', 'اور جو لوگ ہم سے ملنے کی امید نہیں رکھتے۔ کہتے ہیں کہ ہم پر فرشتے کیوں نہ نازل کئے گئے۔ یا ہم آنکھ سے اپنے پروردگار کو دیکھ لیں۔ یہ اپنے خیال میں بڑائی رکھتے ہیں اور اسی بنا پر بڑے سرکش ہو رہے ہیں۔', 'اور بولے وہ لوگ جو امید نہیں رکھتے کہ ہم سے ملیں گے کیوں نہ اترے ہم پر فرشتے یا ہم دیکھ لیتے اپنے رب کو [۳۲] بہت بڑائی رکھتے ہیں اپنے جی میں اور سر چڑھ رہے ہیں بڑی شرارت میں [۳۳]', 'And those who expect not for a Meeting with Us (i.e. those who deny the Day of Resurrection and the life of the Hereafter), say: \"Why are not the angels sent down to us, or why do we not see our Lord?\" Indeed they think too highly of themselves, and are scornful with great pride.', 'Said those who do not even expect to meet Us, “Why the angels are not sent down to us or why do we not see our Lord?” Indeed they think too highly of themselves, and have gone too far in rebellion.'),
(2877, 25, 22, 3, 1, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'یَوۡمَ یَرَوۡنَ الۡمَلٰٓئِکَۃَ  لَا بُشۡرٰی یَوۡمَئِذٍ لِّلۡمُجۡرِمِیۡنَ وَ یَقُوۡلُوۡنَ حِجۡرًا مَّحۡجُوۡرًا ﴿۲۲﴾', 'جس دن یہ فرشتوں کو دیکھیں گے اس دن گناہگاروں کے لئے کوئی خوشی کی بات نہیں ہو گی اور کہیں گے کہیں کوئی رکاوٹ کھڑی کر دی جائے۔', 'جس دن دیکھیں گے فرشتوں کو کچھ خوشخبری نہیں اس دن گنہگاروں کو اور کہیں گے کہیں روک دی جائے کوئی آڑ [۳۴]', 'On the Day they will see the angels, no glad tidings will there be for the Mujrimoon (criminals, disbelievers, polytheists, sinners, etc.) that day. And they (angels) will say: \"All kinds of glad tidings are forbidden for you,\" (None will be allowed to enter Paradise except the one who said: La ilaha ill-Allah, \"(none has the right to be worshipped but Allah) and acted practically on its legal orders and obligations).', 'The Day they will see the angels, there will be no good news for the sinners that day, and they will say, “(We need) a shelter, fully protected!”'),
(2878, 25, 23, 3, 1, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ قَدِمۡنَاۤ اِلٰی مَا عَمِلُوۡا مِنۡ عَمَلٍ فَجَعَلۡنٰہُ  ہَبَآءً  مَّنۡثُوۡرًا  ﴿۲۳﴾', 'اور جو انہوں نے عمل کئے ہوں گے ہم انکی طرف متوجہ ہوں گے تو انکو بکھرا ہوا غبار  کر دیں گے۔', 'اور ہم پہنچے انکے کاموں پر جو انہوں نے کئے تھے پھر ہم نے کر ڈالا اسکو خاک اڑتی ہوئی [۳۵]', 'And We shall turn to whatever deeds they (disbelievers, polytheists, sinners, etc.) did, and We shall make such deeds as scattered floating particles of dust.', 'And We will proceed to whatever deeds they did, and will turn them into scattered dust.'),
(2879, 25, 24, 3, 1, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'اَصۡحٰبُ الۡجَنَّۃِ یَوۡمَئِذٍ خَیۡرٌ  مُّسۡتَقَرًّا وَّ اَحۡسَنُ  مَقِیۡلًا ﴿۲۴﴾', 'اس دن اہل جنت کا ٹھکانہ بھی بہتر ہو گا اور انکے آرام کی جگہ بھی خوب ہو گی۔', 'بہشت کے لوگوں کا اس دن خوب ہے ٹھکانا اور خوب ہے جگہ دوپہر کے آرام کی [۳۶]', 'The dwellers of Paradise (i.e. those who deserved it through their Faith and righteousness) will, on that Day, have the best abode, and have the fairest of places for repose.', 'The people of Paradise, on that day, will be the best in (terms of their) abode and best in (terms of their) resting-place.'),
(2880, 25, 25, 3, 1, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ یَوۡمَ تَشَقَّقُ السَّمَآءُ بِالۡغَمَامِ وَ نُزِّلَ الۡمَلٰٓئِکَۃُ  تَنۡزِیۡلًا ﴿۲۵﴾', 'اور جس دن آسمان ابر سے پھٹ جائے گا اور فرشتے نازل کئے جائیں گے۔', 'اور جس دن پھٹ جائے گا آسمان بادل سے اور اتارے جائیں فرشتے تار لگا کر [۳۷]', 'And (remember) the Day when the heaven shall be rent asunder with clouds, and the angels will be sent down, with a grand descending.', 'The Day the sky will break open with a cloud, and the angels will be sent down in a majestic descent,');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(2881, 25, 26, 3, 1, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'اَلۡمُلۡکُ یَوۡمَئِذِۣ الۡحَقُّ لِلرَّحۡمٰنِ ؕ وَ کَانَ یَوۡمًا عَلَی الۡکٰفِرِیۡنَ عَسِیۡرًا ﴿۲۶﴾', 'اس دن سچی بادشاہی رحمٰن ہی کی ہو گی۔ اور وہ دن کافروں پر سخت مشکل ہو گا۔', 'بادشاہی اس دن سچی ہے رحمٰن کی اور ہے وہ دن منکروں پر مشکل [۳۸]', 'The sovereignty on that Day will be the true (sovereignty), belonging to the Most Beneficent (Allah), and it will be a hard Day for the disbelievers (those who disbelieve in the Oneness of Allah Islamic Monotheism).', 'the Kingdom on that day will be for the RaHmān (the All-Merciful, Allah), and it will be a difficult day for the disbelievers.'),
(2882, 25, 27, 3, 1, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ  یَوۡمَ یَعَضُّ الظَّالِمُ عَلٰی  یَدَیۡہِ یَقُوۡلُ یٰلَیۡتَنِی اتَّخَذۡتُ مَعَ الرَّسُوۡلِ سَبِیۡلًا ﴿۲۷﴾', 'اور جس دن ظالم اپنے ہاتھ کاٹ کاٹ کھائے گا اور کہے گا کہ اے کاش میں نے پیغمبر کے ساتھ رستہ اختیار کیا ہوتا۔', 'اور جس دن کاٹ کاٹ کھائے گا اپنے ہاتھوں کو کہے گا اے کاش کے میں نے پکڑا ہوتا رسول کے ساتھ رستہ [۳۹]', 'And (remember) the Day when the Zalim (wrong-doer, oppressor, polytheist, etc.) will bite at his hands, he will say: \"Oh! Would that I had taken a path with the Messenger ( Muhammad SAW).', 'And (Be mindful of) the Day the wrongdoer will bite his hands saying, “Would that I had taken a path along with the messenger!'),
(2883, 25, 28, 3, 1, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'یٰوَیۡلَتٰی لَیۡتَنِیۡ لَمۡ اَتَّخِذۡ فُلَانًا خَلِیۡلًا ﴿۲۸﴾', 'ہائے شامت کاش میں نے فلاں شخص کو دوست نہ بنایا ہوتا۔', 'اے خرابی میری کاش کے نہ پکڑا ہوتا میں نے فلانے کو دوست [۴۰]', '\"Ah! Woe to me! Would that I had never taken so-and-so as a friend!', 'Woe to me! Would that I had not taken so-and-so for my friend!'),
(2884, 25, 29, 3, 1, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'لَقَدۡ اَضَلَّنِیۡ عَنِ الذِّکۡرِ  بَعۡدَ  اِذۡ جَآءَنِیۡ ؕ وَ کَانَ الشَّیۡطٰنُ لِلۡاِنۡسَانِ خَذُوۡلًا ﴿۲۹﴾', 'اس نے مجھ کو کتاب نصیحت کے میرے پاس آنے کے بعد بہکا دیا۔ اور شیطان انسان کو وقت پر دغا دینے والا ہے۔', 'اس نے تو بہکا دیا مجھ کو نصیحت سے مجھ تک پہنچ چکنے کے پیچھے (بعد)  اور ہے شیطان آدمی کو  وقت پر دغا دینے والا [۴۱]', '\"He indeed led me astray from the Reminder (this Quran) after it had come to me. And Shaitan (Satan) is ever a deserter to man in the hour of need.\"', 'Indeed he led me astray from the advice after it had come to me.” And the Satan is man’s betrayer.'),
(2885, 25, 30, 3, 1, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ قَالَ الرَّسُوۡلُ یٰرَبِّ اِنَّ قَوۡمِی اتَّخَذُوۡا ہٰذَا  الۡقُرۡاٰنَ  مَہۡجُوۡرًا ﴿۳۰﴾', 'اور پیغمبر کہیں گے کہ اے پروردگار میری قوم نے اس قرآن کو چھوڑ رکھا تھا۔', 'اور کہا رسول نے اے میرے رب میری قوم نے ٹھہرایا ہے اس قرآن کو جھک جھک [۴۲]', 'And the Messenger (Muhammad SAW) will say: \"O my Lord! Verily, my people deserted this Quran (neither listened to it, nor acted on its laws and orders).', 'And the messenger will say, “O my Lord, my people had taken this Qur’ān as deserted.”'),
(2886, 25, 31, 3, 1, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ کَذٰلِکَ جَعَلۡنَا لِکُلِّ نَبِیٍّ عَدُوًّا مِّنَ الۡمُجۡرِمِیۡنَ ؕ وَ کَفٰی بِرَبِّکَ ہَادِیًا وَّ نَصِیۡرًا ﴿۳۱﴾', 'اور اسی طرح ہم نے گناہگاروں میں سے ہر پیغمبر کا دشمن بنا دیا اور تمہارا پروردگار ہدایت دینے اور مدد کرنے کو کافی ہے۔', 'اور اسی طرح رکھے ہیں ہم نے ہر نبی کے لئے دشمن گنہگاروں میں سے [۴۳] اور کافی ہے تیرا رب راہ دکھانے اور مدد کرنے کو [۴۴]', 'Thus have We made for every Prophet an enemy among the Mujrimoon (disbelievers, polytheists, criminals, etc.). But Sufficient is your Lord as a Guide and Helper.', 'In a similar way We made for every prophet an enemy from among the sinners, but your Lord suffices as a guide and as a supporter.'),
(2887, 25, 32, 3, 1, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ قَالَ الَّذِیۡنَ کَفَرُوۡا لَوۡ لَا نُزِّلَ عَلَیۡہِ الۡقُرۡاٰنُ جُمۡلَۃً  وَّاحِدَۃً ۚۛ کَذٰلِکَ ۚۛ لِنُثَبِّتَ بِہٖ  فُؤَادَکَ وَ رَتَّلۡنٰہُ تَرۡتِیۡلًا ﴿۳۲﴾', 'اور کافر کہتے ہیں کہ اس پر قرآن ایک ہی دفعہ کیوں نہیں اتارا گیا۔ اس طرح آہستہ آہستہ اس لئے اتارا گیا کہ اس سے تمہارے دل کو مضبوط رکھیں۔ اور اسی واسطے ہم اسکو ٹھہر ٹھہر کر پڑھتے رہے ہیں۔', 'اور کہنے لگے وہ لوگ جو منکر ہیں کیوں نہ اترا اس پر قرآن سارا ایک جگہ ہو کر [۴۵] اسی طرح اتارا  تاکہ ثابت رکھیں ہم اس سےتیرا دل اور پڑھ سنایا ہم نے اسکو ٹھہر ٹھہر کر [۴۶]', 'And those who disbelieve say: \"Why is not the Quran revealed to him all at once?\" Thus (it is sent down in parts), that We may strengthen your heart thereby. And We have revealed it to you gradually, in stages. (It was revealed to the Prophet SAW in 23 years.).', 'Said those who disbelieved, “Why has the Qur’ān not been revealed to him all at once?” (It has been sent down) in this way (i.e. in parts) so that We make your heart firm, and We revealed it little by little.'),
(2888, 25, 33, 3, 1, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ لَا یَاۡتُوۡنَکَ بِمَثَلٍ  اِلَّا جِئۡنٰکَ بِالۡحَقِّ وَ  اَحۡسَنَ  تَفۡسِیۡرًا ﴿ؕ۳۳﴾', 'اور یہ لوگ تمہارے پاس جو اعتراض کی بات لاتے ہیں ہم تمہارے پاس اس کا معقول اور خوب واضح جواب بھیج دیتے ہیں۔', 'اور نہیں لاتے تیرے پاس کوئی مثل کہ ہم نہیں پہنچا دیتے تجھ کو ٹھیک بات اور اس سے بہتر کھول کر [۴۷]', 'And no example or similitude do they bring (to oppose or to find fault in you or in this Quran), but We reveal to you the truth (against that similitude or example), and the better explanation thereof.', 'They bring to you no hypothesis, but We bring to you the correct position and (an answer) better explained.'),
(2889, 25, 34, 3, 1, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'اَلَّذِیۡنَ یُحۡشَرُوۡنَ عَلٰی وُجُوۡہِہِمۡ اِلٰی جَہَنَّمَ ۙ  اُولٰٓئِکَ شَرٌّ مَّکَانًا وَّ اَضَلُّ سَبِیۡلًا ﴿٪۳۴﴾', 'جو لوگ اپنے چہروں کے بل دوزخ کی طرف جمع کئے جائیں گے ان کا ٹھکانہ بھی برا ہے اور وہ رستے سے بھی بہکے ہوئے ہیں۔', 'جو لوگ کہ گھیر کر لائے جائیں گے اوندھے پڑے ہوئے اپنے منہ پر دوزخ کی طرف انہی کا برا درجہ ہے اور بہت بہکے ہوئے ہیں راہ سے [۴۸]', 'Those who will be gathered to Hell (prone) on their faces, such will be in an evil state, and most astray from the (Straight) Path.', 'Those who will be driven on their faces to Hell - they are the worst in situation and far more astray from the path.'),
(2890, 25, 35, 4, 2, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ لَقَدۡ اٰتَیۡنَا مُوۡسَی الۡکِتٰبَ وَ جَعَلۡنَا مَعَہٗۤ   اَخَاہُ  ہٰرُوۡنَ  وَزِیۡرًا ﴿ۚۖ۳۵﴾', 'اور ہم نے موسٰی کو کتاب دی اور انکے بھائی ہارون کو مددگار کے طور پر انکے ساتھ کر دیا۔', 'اور ہم نے دی موسٰی کو کتاب اورکر دیا ہم نے اس کے ساتھ اس کا بھائی ہارون کام بٹانے والا', 'And indeed We gave Moosa (Moses) the Scripture (the Taurat (Torah)), and placed his brother Haroon (Aaron) with him as a helper;', 'Surely We gave Mūsā the Book, and appointed his brother Hārūn as a minister with him.'),
(2891, 25, 36, 4, 2, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'فَقُلۡنَا اذۡہَبَاۤ  اِلَی الۡقَوۡمِ الَّذِیۡنَ کَذَّبُوۡا بِاٰیٰتِنَا ؕ فَدَمَّرۡنٰہُمۡ  تَدۡمِیۡرًا ﴿ؕ۳۶﴾', 'پھر ہم نے کہا کہ دونوں ان لوگوں کے پاس جاؤ جنہوں نے ہماری آیتوں کی تکذیب کی آخر ہم نے انکو پوری طرح ہلاک کر دیا۔', 'پھر کہا ہم نے دونوں جاؤ  ان لوگوں کے پاس جنہوں نے جھٹلایا ہماری باتوں کو [۴۹] پھر دے مارا ہم نے ان کو اکھاڑ کر', 'And We said: \"Go you both to the people who have denied Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.).\" Then We destroyed them with utter destruction.', 'So we said, “Go, both of you, to the people who have rejected Our signs” Then We annihilated them totally.'),
(2892, 25, 37, 4, 2, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ قَوۡمَ نُوۡحٍ  لَّمَّا کَذَّبُوا الرُّسُلَ اَغۡرَقۡنٰہُمۡ وَ جَعَلۡنٰہُمۡ لِلنَّاسِ اٰیَۃً ؕ وَ اَعۡتَدۡنَا لِلظّٰلِمِیۡنَ عَذَابًا  اَلِیۡمًا  ﴿ۚۖ۳۷﴾', 'اور نوح کی قوم نے بھی جب پیغمبروں کو جھٹلایا تو ہم نے انہیں غرق کر دیا اور انکو لوگوں کے لئے نشانی بنا دیا۔ اور ظالموں کے لئے ہم نے دکھ دینے والا عذاب تیار کر رکھا ہے۔', 'اور نوح کی قوم کو جب انہوں نے جھٹلایا پیغام لانے والوں کو [۵۰] ہم نے انکو ڈبا دیا اور کیا ان کو لوگوں کے حق میں نشانی اور تیار کر رکھا ہے ہم نے گنہگاروں کے واسطے عذاب دردناک', 'And Noohs (Noah) people, when they denied the Messengers We drowned them, and We made them as a sign for mankind. And We have prepared a painful torment for the Zalimoon (polytheists and wrong-doers, etc).', 'As for the people of NūH, when they rejected the messengers, We drowned them and made them an example for mankind, and We have prepared a painful punishment for the transgressors.'),
(2893, 25, 38, 4, 2, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَّ عَادًا  وَّ  ثَمُوۡدَا۠  وَ اَصۡحٰبَ الرَّسِّ وَ قُرُوۡنًۢا  بَیۡنَ  ذٰلِکَ  کَثِیۡرًا ﴿۳۸﴾', 'اور عاد اور ثمود اور کنوئیں والوں اور انکے درمیان اور بہت سی جماعتوں کو بھی ہلاک کر دیا۔', 'اور عاد کو اور ثمود کو اور کنوئیں والوں کو [۵۱] اور اس کے بیچ میں بہت سی جماعتوں کو', 'And (also) Ad and Thamood, and the dwellers of Ar-Rass, and many generations in between.', 'And (We annihilated also the peoples of) ‘Ād and Thamūd and the people of Rass, and many generations in between them.'),
(2894, 25, 39, 4, 2, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ کُلًّا ضَرَبۡنَا لَہُ  الۡاَمۡثَالَ ۫ وَ کُلًّا  تَبَّرۡنَا تَتۡبِیۡرًا ﴿۳۹﴾', 'اور سب کے سمجھانے کے لئے ہم نے مثالیں بیان کیں اور نہ ماننے پر سب کو تہس نہس کر دیا۔', 'اور سب کو کہہ سنائیں ہم نے مثالیں اور سب کو کھو دیا ہم نے غارت کر کر [۵۲]', 'And for each of them We put forward examples (as proofs and lessons, etc.), and each (of them) We brought to utter ruin (because of their disbelief and evil deeds).', 'To each (of them) We cited examples, and each of them We brought to utter ruin.'),
(2895, 25, 40, 4, 2, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ لَقَدۡ اَتَوۡا عَلَی الۡقَرۡیَۃِ الَّتِیۡۤ  اُمۡطِرَتۡ مَطَرَ  السَّوۡءِ ؕ اَفَلَمۡ  یَکُوۡنُوۡا یَرَوۡنَہَا ۚ بَلۡ  کَانُوۡا  لَا  یَرۡجُوۡنَ  نُشُوۡرًا ﴿۴۰﴾', 'اور یہ کافر اس بستی پر بھی گذر چکے ہیں جس پر بری طرح کا مینہ برسایا گیا تھا تو کیا یہ اسکو دیکھتے نہ ہوں گے۔ بلکہ انکو تو مرنے کے بعد جی اٹھنے کی امید ہی نہیں۔', 'اور یہ لوگ ہو آئے ہیں اس بستی کے پاس جن پر برسا برُا برساؤ [۵۳] کیا دیکھتے نہ تھے اس کو [۵۴] نہیں پر امید نہیں رکھتے جی اٹھنے کی [۵۵]', 'And indeed they have passed by the town (of Prophet Lout (Lot)) on which was rained the evil rain. Did they (disbelievers) not then see it (with their own eyes)? Nay ! But they used not to expect for any resurrection.', 'Indeed they (the pagans of Makkah) have passed by the town that was afflicted by an evil rain sent down to it. So, have they not been seeing it? Rather, they do not believe in Resurrection.'),
(2896, 25, 41, 4, 2, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ اِذَا رَاَوۡکَ اِنۡ یَّتَّخِذُوۡنَکَ اِلَّا ہُزُوًا ؕ اَہٰذَا  الَّذِیۡ  بَعَثَ  اللّٰہُ  رَسُوۡلًا ﴿۴۱﴾', 'اور یہ لوگ جب تمکو دیکھتے ہیں تو تمہاری ہنسی اڑاتے ہیں کہ کیا یہی شخص ہے جسکو اللہ نے پیغمبر بنا کر بھیجا ہے۔', 'اور جہاں تجھ کو دیکھیں کچھ کام نہیں انکو تجھ سے مگر ٹھٹھے کرنے کیا یہ ہے جس کو بھیجا اللہ نے پیغام دے کر', 'And when they see you (O Muhammad SAW), they treat you only as a mockery (saying):\"Is this the one whom Allah has sent as a Messenger?', 'When they see you, they take you only as a laughing stock, (saying) “Is this the man whom Allah has sent as a messenger?'),
(2897, 25, 42, 4, 2, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'اِنۡ  کَادَ  لَیُضِلُّنَا عَنۡ  اٰلِہَتِنَا  لَوۡ لَاۤ  اَنۡ صَبَرۡنَا عَلَیۡہَا ؕ وَ سَوۡفَ یَعۡلَمُوۡنَ حِیۡنَ یَرَوۡنَ الۡعَذَابَ مَنۡ اَضَلُّ سَبِیۡلًا ﴿۴۲﴾', 'اگر ہم اپنے معبودوں کے بارے میں ثابت قدم نہ رہتے تو یہ ضرور ہمکو بہکا دیتا اور ان سے پھیر دیتا اور یہ عنقریب معلوم کر لیں گے جب عذاب دیکھیں گے کہ سیدھے رستے سے کون بھٹکا ہوا ہے۔', 'یہ تو ہم کو بچلا ہی دیتا ہمارے معبودوں سے اگر ہم نہ جمے رہتے ان پر [۵۶] اور آگے جان لیں گے جس وقت دیکھیں گے عذاب کہ کون بہت بچلا ہوا ہے راہ سے [۵۷]', '\"He would have nearly misled us from our aliha (gods), had it not been that we were patient and constant in their worship!\" And they will know when they see the torment, who it is that is most astray from the (Right) Path!', 'He would have almost led us astray from our gods, had we not been so firm towards them.” They will know when they will see the punishment, who is farther astray in his way.'),
(2898, 25, 43, 4, 2, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'اَرَءَیۡتَ مَنِ اتَّخَذَ اِلٰـہَہٗ ہَوٰىہُ ؕ اَفَاَنۡتَ تَکُوۡنُ  عَلَیۡہِ   وَکِیۡلًا ﴿ۙ۴۳﴾', 'اے پیغمبر کیا تم نے اس شخص کو دیکھا جس نے اپنی خواہش نفس کو اپنا معبود بنا رکھا ہے تو کیا تم اسکے ذمہ دار ہو سکتے ہو؟', 'بھلا دیکھ تو اس شخص کو جس نے پوجنا اختیار کیا اپنی خواہش کا کہیں تو لے سکتا ہے اس کا ذمہ [۵۸]', 'Have you (O Muhammad SAW) seen him who has taken as his ilah (god) his own desire? Would you then be a Wakeel (a disposer of his affairs or a watcher) over him?', 'Tell me about the one who has taken his desire as his god, would you then, become a guardian for him?'),
(2899, 25, 44, 4, 2, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'اَمۡ  تَحۡسَبُ اَنَّ  اَکۡثَرَہُمۡ  یَسۡمَعُوۡنَ  اَوۡ یَعۡقِلُوۡنَ ؕ اِنۡ  ہُمۡ   اِلَّا  کَالۡاَنۡعَامِ  بَلۡ ہُمۡ اَضَلُّ  سَبِیۡلًا ﴿٪۴۴﴾', 'یا تم یہ خیال کرتے ہو کہ ان میں اکثر سنتے یا سمجھتے ہیں؟ نہیں یہ تو چوپایوں کی طرح کے ہیں بلکہ ان سے بھی گئے گذرے۔', 'یا تو خیال رکھتا ہے کہ بہت سے ان میں سنتے یا سمجھتے ہیں اور کچھ نہیں وہ برابر ہیں چوپایوں کے بلکہ وہ زیادہ بہکے ہوئے ہیں راہ سے [۵۹]', 'Or do you think that most of them hear or understand? They are only like cattle; nay, they are even farther astray from the Path. (i.e. even worst than cattle).', 'Or do you think that most of them listen or understand? They are but like cattle. Rather, they are even farther astray from the (right) way.'),
(2900, 25, 45, 5, 3, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'اَلَمۡ  تَرَ  اِلٰی رَبِّکَ کَیۡفَ مَدَّ  الظِّلَّ ۚ وَ لَوۡ شَآءَ لَجَعَلَہٗ  سَاکِنًا ۚ ثُمَّ جَعَلۡنَا الشَّمۡسَ عَلَیۡہِ  دَلِیۡلًا ﴿ۙ۴۵﴾', 'بھلا تم نے اپنے پروردگار کی قدرت کو نہیں دیکھا کہ وہ سائے کو کس طرح دراز کر کے پھیلا دیتا ہے اور اگر وہ چاہتا تو اسکو بےحرکت ٹھہرا رکھتا پھر ہم سورج کو اسکا راہنما بنا دیتے ہیں۔', 'تو نے نہیں دیکھا اپنے رب کی طرف کیسے دراز کیا سایہ کو اگر چاہتا تو اس کو ٹھہرا رکھتا پھر ہم نے مقرر کیا سورج کو اس کا راہ بتانے والا', 'Have you not seen how your Lord spread the shadow. If He willed, He could have made it still then We have made the sun its guide (i.e. after the sunrise, it (the shadow) squeezes and vanishes at midnoon and then again appears in the afternoon with the decline of the sun, and had there been no sun light, there would have been no shadow).', 'Have you not observed how your Lord stretched out the shadow (of the sun)? If He so willed, He would have made it stand still. Then We made the sun an indicator for it.'),
(2901, 25, 46, 5, 3, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'ثُمَّ  قَبَضۡنٰہُ   اِلَیۡنَا قَبۡضًا یَّسِیۡرًا ﴿۴۶﴾', 'پھر ہم اسکو آہستہ آہستہ اپنی طرف سمیٹ لیتے ہیں۔', 'پھر کھینچ لیا ہم نے اسکو  اپنی طرف سہج سہج سمیٹ کر [۶۰]', 'Then We withdraw it to Us a gradual concealed withdrawal.', 'Then We pulled it toward Us in a gradual manner.'),
(2902, 25, 47, 5, 3, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ ہُوَ الَّذِیۡ  جَعَلَ  لَکُمُ  الَّیۡلَ  لِبَاسًا وَّ النَّوۡمَ سُبَاتًا وَّ جَعَلَ النَّہَارَ  نُشُوۡرًا ﴿۴۷﴾', 'اور وہی تو ہے جس نے رات کو تمہارے لئے پردہ اور نیند کو آرام بنایا اور دن کو اٹھ کھڑے ہونے کا وقت ٹھہرایا۔', 'اور وہی ہے جس نے بنا دیا تمہارے واسطے رات کو اوڑھنا اور نیند کو آرام اور دن کو بنا دیا اٹھ نکلنے کے لئے [۶۱]', 'And it is He Who makes the night a covering for you, and the sleep (as) repose, and makes the day Nushoor (i.e. getting up and going about here and there for daily work, etc. after ones sleep at night or like resurrection after ones death).', 'He is the One who has made the night an apparel for you, and the sleep a means of rest, and has made the day a means of revival.'),
(2903, 25, 48, 5, 3, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ ہُوَ الَّذِیۡۤ  اَرۡسَلَ الرِّیٰحَ بُشۡرًۢا بَیۡنَ یَدَیۡ رَحۡمَتِہٖ ۚ وَ اَنۡزَلۡنَا مِنَ السَّمَآءِ مَآءً  طَہُوۡرًا ﴿ۙ۴۸﴾', 'اور وہی تو ہے جو اپنی رحمت یعنی مینہ کے آگے ہواؤں کو خوشخبری بنا کر بھیجتا ہے اور ہم آسمان سے پاک نتھرا ہوا پانی برساتے ہیں۔', 'اور وہی ہے جس نے چلائیں ہوائیں خوشخبری لانے والیاں اس کی رحمت سے آگے اور اتارا ہم نے آسمان سے پانی پاکی حاصل کرنے کا', 'And it is He Who sends the winds as heralds of glad tidings, going before His Mercy (rain), and We send down pure water from the sky,', 'And He is the One who has sent the winds conveying good news before His mercy, and We have sent down purifying water from the heavens,'),
(2904, 25, 49, 5, 3, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'لِّنُحۡیَِۧ بِہٖ بَلۡدَۃً  مَّیۡتًا وَّ نُسۡقِیَہٗ مِمَّا خَلَقۡنَاۤ   اَنۡعَامًا وَّ  اَنَاسِیَّ  کَثِیۡرًا ﴿۴۹﴾', 'تاکہ اس سے شہر مردہ یعنی بنجر زمین کو زندہ کر دیں اور تاکہ ہم وہ پانی بہت سے اور آدمیوں کو جو ہم نے پیدا کئے ہیں پلائیں۔', 'کہ زندہ کر دیں اس سے مرے ہوئے دیس کو اور پلائیں اس کو اپنے پیدا کئے ہوئے بہت سے چوپایوں اور آدمیوں کو [۶۲]', 'That We may give life thereby to a dead land, and We give to drink thereof many of the cattle and men that We had created.', 'so that We revive a dead land therewith, and give drink to the many cattle and humans created by Us.'),
(2905, 25, 50, 5, 3, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ لَقَدۡ صَرَّفۡنٰہُ بَیۡنَہُمۡ  لِیَذَّکَّرُوۡا ۫ۖ فَاَبٰۤی  اَکۡثَرُ  النَّاسِ   اِلَّا کُفُوۡرًا  ﴿۵۰﴾', 'اور ہم نے اس قرآن کی آیتوں کو طرح طرح سے لوگوں میں بیان کیا تاکہ وہ نصیحت پکڑیں مگر بہت سے لوگوں نے انکار کے سوا قبول نہ کیا۔', 'اور طرح طرح سے تقسیم کیا ہم نے اس کو انکے بیچ میں تا دھیان رکھیں پھر بھی نہیں رہتے بہت لوگ بدون ناشکری کیے [۶۳]', 'And indeed We have distributed it (rain or water) amongst them in order that they may remember the Grace of Allah, but most men refuse (or deny the Truth or Faith) and accept nothing but disbelief or ingratitude.', 'And We have distributed it (the water) among them, so that they may take lesson. Yet most of the people refused all but ungratefulness.'),
(2906, 25, 51, 5, 3, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ لَوۡ شِئۡنَا لَبَعَثۡنَا فِیۡ کُلِّ قَرۡیَۃٍ نَّذِیۡرًا ﴿۫ۖ۵۱﴾', 'اور اگر ہم چاہتے تو ہر بستی میں ڈرانے والا بھیج دیتے۔', 'اور اگر ہم چاہتے تو اٹھاتے ہر بستی میں کوئی ڈرانے والا', 'And had We willed, We would have raised a warner in every town.', 'Had We so willed, We would have sent a (separate) warner for every town, (but, according to Our wisdom, We have sent Muhammad as a prophet for all these towns)'),
(2907, 25, 52, 5, 3, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'فَلَا  تُطِعِ الۡکٰفِرِیۡنَ وَ جَاہِدۡہُمۡ بِہٖ جِہَادًا کَبِیۡرًا ﴿۵۲﴾', 'تو تم کافروں کا کہا نہ مانو اور ان سے اس قرآن کے حکم کے مطابق بڑے شدومد سے لڑو۔', 'سو تو کہنا مت مان منکروں کا اور مقابلہ کر ان کا اسکے ساتھ بڑے زور سے [۶۴]', 'So obey not the disbelievers, but strive against them (by preaching) with the utmost endeavour, with it (the Quran).', 'So, (O Prophet,) do not obey the infidels, and strive against them with it (the Qur’ān), in utmost endeavor.'),
(2908, 25, 53, 5, 3, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ ہُوَ الَّذِیۡ مَرَجَ الۡبَحۡرَیۡنِ ہٰذَا عَذۡبٌ فُرَاتٌ وَّ ہٰذَا مِلۡحٌ  اُجَاجٌ ۚ وَ جَعَلَ بَیۡنَہُمَا بَرۡزَخًا  وَّ  حِجۡرًا  مَّحۡجُوۡرًا ﴿۵۳﴾', 'اور وہی تو ہے جس نے دو دریاؤں کو ملا کر چلایا ایک کا پانی شیریں ہے پیاس بجھانے والا اور دوسرے کا کھاری کڑوا اور دونوں کے درمیان ایک پردہ اور مضبوط اوٹ بنا دی ہے۔', 'اور وہی ہے جس نے ملے ہوئے چلائے دو دریا یہ میٹھا ہے پیاس بجھانے والا اور یہ کھاری ہے کڑوا اور رکھا ان دونوں کے بیچ پردا  اور  آڑ  روکی ہوئی [۶۵]', 'And it is He Who has let free the two seas (kinds of water), one palatable and sweet, and the other salt and bitter, and He has set a barrier and a complete partition between them.', 'He is the One who joined the two seas, so as this is sweet, very sweet, and this is bitter, very bitter, and made between them a buffer and an insurmountable barrier.'),
(2909, 25, 54, 5, 3, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ ہُوَ الَّذِیۡ خَلَقَ مِنَ الۡمَآءِ بَشَرًا فَجَعَلَہٗ  نَسَبًا وَّ صِہۡرًا ؕ وَ کَانَ رَبُّکَ قَدِیۡرًا ﴿۵۴﴾', 'اور وہی تو ہے جس نے پانی سے آدمی پیدا کیا۔ پھر اسکو ددھیال ننھیال اور سسرال والا بنایا۔ اور تمہارا پروردگار ہر طرح کی قدرت رکھتا ہے۔', 'اور ہی ہے جس نے بنایا پانی سے آدمی پھر ٹھہرایا اس کے لئے جد اور سسرال اور تیرا رب سب کچھ کر سکتا ہے', 'And it is He Who has created man from water, and has appointed for him kindred by blood, and kindred by marriage. And your Lord is Ever All-Powerful to do what He will.', 'And He is the One who created man from water, then made of him relations created by lineage and relations created by marriage. Your Lord is All-Powerful.'),
(2910, 25, 55, 5, 3, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ یَعۡبُدُوۡنَ مِنۡ دُوۡنِ اللّٰہِ مَا لَا یَنۡفَعُہُمۡ  وَ لَا یَضُرُّہُمۡ ؕ وَ کَانَ الۡکَافِرُ عَلٰی  رَبِّہٖ   ظَہِیۡرًا ﴿۵۵﴾', 'اور یہ لوگ اللہ کو چھوڑ کر ایسی چیز کی پرستش کرتے ہیں کہ جو نہ انکو فائدہ پہنچا سکے اور نہ نقصان اور کافر اپنے پروردگار کی طرف سے پیٹھ پھیرنے والا ہے۔', 'اور پوجتے ہیں اللہ کو چھوڑ کر وہ چیز جو نہ بھلا کرے ان کا نہ برا اور ہے کافر اپنے رب کی طرف سے پیٹھ پھیر رہا [۶۶]', 'And they (disbelievers, polytheists, etc.) worship besides Allah, that which can neither profit them nor harm them, and the disbeliever is ever a helper (of the Satan) against his Lord.', 'They worship, instead of Allah, what can neither give them any benefit nor can cause them any harm. The disbeliever is always a supporter (of Satan) against his Lord.'),
(2911, 25, 56, 5, 3, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ مَاۤ  اَرۡسَلۡنٰکَ  اِلَّا مُبَشِّرًا وَّ نَذِیۡرًا ﴿۵۶﴾', 'اور ہم نے اے نبی تمکو صرف خوشی اور عذاب کی خبر سنانے کو بھیجا ہے۔', 'اور تجھ کو ہم نے بھیجا یہی خوشی اور ڈر سنانے کے لئے', 'And We have sent you (O Muhammad SAW ) only as a bearer of glad tidings and a warner.', 'We did not send you but as a bearer of good news and as a warner.'),
(2912, 25, 57, 5, 3, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'قُلۡ مَاۤ  اَسۡـَٔلُکُمۡ  عَلَیۡہِ مِنۡ اَجۡرٍ  اِلَّا مَنۡ  شَآءَ  اَنۡ یَّتَّخِذَ  اِلٰی رَبِّہٖ سَبِیۡلًا ﴿۵۷﴾', 'کہدو کہ میں تم سے اس کام کی اجرت نہیں مانگتا۔ ہاں جو شخص چاہے اپنے پروردگار کی طرف جانے کا رستہ اختیار کر لے۔', 'تو کہہ میں نہیں مانگتا تم سے اس پر کچھ مزدوری مگر جو کوئی چاہے کہ پکڑ لے اپنے رب کی طرف راہ [۶۷]', 'Say: \"No reward do I ask of you for this (that which I have brought from my Lord and its preaching, etc.), save that whosoever wills, may take a Path to his Lord.', 'Say, “I do not demand from you any return, except that one should adopt the (proper) way to his Lord, if he so wills.'),
(2913, 25, 58, 5, 3, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ تَوَکَّلۡ عَلَی الۡحَیِّ الَّذِیۡ لَا یَمُوۡتُ وَ سَبِّحۡ بِحَمۡدِہٖ ؕ وَ کَفٰی بِہٖ بِذُنُوۡبِ عِبَادِہٖ خَبِیۡرَا ﴿ۚۛۙ۵۸﴾', 'اور اس خدائے زندہ پر بھروسہ رکھو جو کبھی نہیں مرے گا اور اسکی تعریف کے ساتھ تسبیح کرتے رہو اور وہ اپنے بندوں کے گناہوں سے خبر رکھنے کو کافی ہے۔', 'اور بھروسہ کر اوپر اس زندہ کے جو نہیں مرتا [۶۸] اور یاد کر اسکی خوبیاں اور وہ کافی ہے اپنے بندوں کے گناہوں سے خبردار [۶۹]', 'And put your trust (O Muhammad SAW) in the Ever Living One Who dies not, and glorify His Praises, and Sufficient is He as the All-Knower of the sins of His slaves;', 'And place your trust in the Ever-Living who cannot die, and proclaim His purity along with His praise. Enough is He to be aware of the sins of His servants,'),
(2914, 25, 59, 5, 3, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'ۣالَّذِیۡ خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ وَ  مَا بَیۡنَہُمَا فِیۡ سِتَّۃِ  اَیَّامٍ ثُمَّ  اسۡتَوٰی عَلَی الۡعَرۡشِ ۚۛ اَلرَّحۡمٰنُ فَسۡـَٔلۡ بِہٖ خَبِیۡرًا ﴿۵۹﴾', 'وہی جس نے آسمانوں اور زمین کو اور جو کچھ ان دونوں کے درمیان ہے چھ دن میں پیدا کیا پھر عرش پر جلوہ افروز ہوا وہ جو رحمٰن یعنی بڑا مہربان ہے تو اس کا حال کسی باخبر سے دریافت کر لو۔', 'جس نے بنائے آسمان اور زمین اور جو کچھ انکے بیچ میں ہے چھ دن میں پھر قائم ہوا عرش پر [۷۰] وہ بڑی رحمت والا سو پوچھ اس سے جو اسکی خبر رکھتا ہو [۷۱]', 'Who created the heavens and the earth and all that is between them in six Days. Then He Istawa (rose over) the Throne (in a manner that suits His Majesty). The Most Beneficent (Allah)! Ask Him (O Prophet Muhammad SAW), (concerning His Qualities, His rising over His Throne, His creations, etc.), as He is Al-Khabeer (The All-Knower of everything i.e. Allah).', 'the One who created in six days the heavens and the earth and whatever lies between them, then He positioned Himself on the Throne. (He is) the RaHmān (the All-Merciful, Allah). So ask about Him someone who knows.'),
(2915, 25, 60, 5, 3, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ اِذَا قِیۡلَ لَہُمُ  اسۡجُدُوۡا  لِلرَّحۡمٰنِ قَالُوۡا وَ مَا  الرَّحۡمٰنُ ٭ اَنَسۡجُدُ لِمَا تَاۡمُرُنَا  وَ  زَادَہُمۡ  نُفُوۡرًا ﴿٪ٛ۶۰﴾', 'اور جب ان کفار سے کہا جاتا ہے کہ رحمٰن کو سجدہ کرو تو کہتے ہیں اور رحمٰن کیا ہوتا ہے؟ کیا جس کے لئے تم ہم سے کہتے ہو ہم اسکے آگے سجدہ کریں اور وہ اس بات سے اور بدکتے ہیں۔', 'اور جب کہیے ان سے سجدہ کرو رحمٰن کو کہیں رحمٰن کیا ہے کیا سجدہ کرنے لگیں ہم جسکو تو فرمائے اور بڑھ جاتا ہے ان کا بدکنا [۷۲]', 'And when it is said to them: \"Prostrate to the Most Beneficent (Allah)! They say: \"And what is the Most Beneficent? Shall we fall down in prostration to that which you (O Muhammad SAW) command us?\" And it increases in them only aversion.', 'And when it is said to them, “Prostrate yourselves to the RaHmān (the All-Merciful, Allah),” they say “What is RaHmān? Shall we prostrate ourselves to the one to whom you direct us?” And it increases nothing in them except aversion.'),
(2916, 25, 61, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'تَبٰرَکَ الَّذِیۡ جَعَلَ فِی السَّمَآءِ  بُرُوۡجًا وَّ جَعَلَ  فِیۡہَا سِرٰجًا وَّ قَمَرًا  مُّنِیۡرًا ﴿۶۱﴾', 'بڑی برکت والا ہے وہ جس نے آسمان میں برج بنائے اور ان میں آفتاب کا نہایت روشن چراغ اور چمکتا ہوا چاند بھی بنایا۔', 'بڑی برکت ہے اسکی جس نے بنائے آسمان میں برج [۷۳] اور رکھا اس میں چراغ [۷۴] اور چاند اجالا کرنے والا', 'Blessed be He Who has placed in the heaven big stars, and has placed therein a great lamp (sun), and a moon giving light.', 'Glorious is the One who made stellar formations in the sky, and placed therein a lamp (i.e. the sun) and a bright moon.'),
(2917, 25, 62, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ ہُوَ الَّذِیۡ جَعَلَ الَّیۡلَ وَ النَّہَارَ خِلۡفَۃً لِّمَنۡ اَرَادَ  اَنۡ یَّذَّکَّرَ اَوۡ اَرَادَ شُکُوۡرًا ﴿۶۲﴾', 'اور وہی تو ہے جس نے رات اور دن کو ایک دوسرے کے پیچھے آنے جانے والا بنایا یہ باتیں اس شخص کے لئے جو غور کرنا چاہے یا شکرگذاری کا ارادہ کرے سوچنے اور سمجھنے کی ہیں۔', 'اور وہی ہے جس نے بنائے رات اور دن بدلتے سدلتے [۷۵] اس شخص کے واسطے کہ چاہو دھیان رکھنا یا چاہے شکر کرنا [۷۶]', 'And He it is Who has put the night and the day in succession, for such who desires to remember or desires to show his gratitude.', 'And He is the One who made the day and the night following each other, for the one who wishes to be mindful or wishes to show gratitude.'),
(2918, 25, 63, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ عِبَادُ  الرَّحۡمٰنِ الَّذِیۡنَ  یَمۡشُوۡنَ عَلَی الۡاَرۡضِ ہَوۡنًا وَّ اِذَا خَاطَبَہُمُ الۡجٰہِلُوۡنَ  قَالُوۡا سَلٰمًا ﴿۶۳﴾', 'اور رحمٰن کے بندے تو وہ ہیں جو زمین پر آہستگی سے چلتے ہیں اور جب جاہل لوگ ان سے جاہلانہ گفتگو کرتے ہیں تو سلام کہتے ہیں۔', 'اور بندے رحمٰن کے وہ ہیں جو چلتے ہیں زمین پر دبے پاؤں [۷۷] اور جب بات کرنے لگیں ان سے بے سمجھ لوگ تو کہیں صاحب سلامت [۷۸]', 'And the slaves of the Most Beneficent (Allah) are those who walk on the earth in humility and sedateness, and when the foolish address them (with bad words) they reply back with mild words of gentleness.', 'The servants of the RaHmān (the All-Merciful, Allah) are those who walk on the earth humbly, and when the ignorant people speak to them, they reply peacefully,'),
(2919, 25, 64, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ الَّذِیۡنَ یَبِیۡتُوۡنَ لِرَبِّہِمۡ سُجَّدًا وَّ قِیَامًا ﴿۶۴﴾', 'اور وہ جو اپنے پروردگار کے آگے سجدے کر کے اور عجزوادب سے کھڑے رہ کر راتیں بسر کرتے ہیں۔', 'اور وہ لوگ جو رات کاٹتے ہیں اپنے رب کے آگے سجدہ میں اور کھڑے [۷۹]', 'And those who spend the night before their Lord, prostrate and standing.', 'and those who pass the night prostrating themselves and standing before their Lord,'),
(2920, 25, 65, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ الَّذِیۡنَ یَقُوۡلُوۡنَ رَبَّنَا اصۡرِفۡ عَنَّا عَذَابَ جَہَنَّمَ ٭ۖ اِنَّ عَذَابَہَا کَانَ غَرَامًا ﴿٭ۖ۶۵﴾', 'اور وہ جو دعا مانگتے رہتے ہیں کہ اے پروردگار دوزخ کے عذاب کو ہم سے دور رکھیو کہ اس کا عذاب چمٹنے والا ہے۔', 'اور وہ لوگ کہ کہتے ہیں اے رب ہٹا ہم سے دوزخ کا عذاب بیشک اس کا عذاب چمٹنے والا ہے', 'And those who say: \"Our Lord! Avert from us the torment of Hell. Verily! Its torment is ever an inseparable, permanent punishment.\"', 'and those who say, “Our Lord, avert from us the punishment of Jahannam (the Hell); indeed, its punishment is a persisting affliction.”'),
(2921, 25, 66, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'اِنَّہَا سَآءَتۡ مُسۡتَقَرًّا وَّ  مُقَامًا ﴿۶۶﴾', 'بیشک دوزخ ٹھہرنے اور رہنے کی بہت بری جگہ ہے۔', 'وہ بری جگہ ہے ٹھہرنے کی اور بری جگہ رہنے کی [۸۰]', 'Evil indeed it (Hell) is as an abode and as a place to dwell.', 'Indeed, it is evil as an abode and a place to dwell in'),
(2922, 25, 67, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ الَّذِیۡنَ  اِذَاۤ  اَنۡفَقُوۡا لَمۡ  یُسۡرِفُوۡا وَ لَمۡ یَقۡتُرُوۡا وَ کَانَ  بَیۡنَ  ذٰلِکَ  قَوَامًا ﴿۶۷﴾', 'اور وہ کہ جب خرچ کرتے ہیں تو نہ بیجا اڑاتے ہیں اور نہ تنگی کو کام میں لاتے ہیں۔ بلکہ اعتدال کے ساتھ نہ ضرورت سے زیادہ نہ کم۔', 'اور وہ لوگ کہ جب خرچ کرنے لگیں نہ بیجا اڑائیں اور نہ تنگی کریں اور ہے اس کے بیچ ایک سیدھی گذران [۸۱]', 'And those, who, when they spend, are neither extravagant nor niggardly, but hold a medium (way) between those (extremes).', '- and those who, when they spend, are neither extravagant nor miserly, and it (i.e. their spending) is moderate in between (the two extremes,)'),
(2923, 25, 68, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ الَّذِیۡنَ لَا یَدۡعُوۡنَ مَعَ اللّٰہِ  اِلٰـہًا اٰخَرَ  وَ لَا یَقۡتُلُوۡنَ النَّفۡسَ الَّتِیۡ حَرَّمَ اللّٰہُ  اِلَّا بِالۡحَقِّ وَ لَا یَزۡنُوۡنَ ۚ وَ مَنۡ یَّفۡعَلۡ  ذٰلِکَ  یَلۡقَ  اَثَامًا ﴿ۙ۶۸﴾', 'اور وہ جو اللہ کے ساتھ کسی اور معبود کو نہیں پکارتے اور جس شخص کو مار ڈالنا اللہ نے حرام کیا ہے اسکو قتل نہیں کرتے مگر جائز طریق یعنی شریعت کے حکم سے اور بدکاری نہیں کرتے اور جو یہ کام کرے گا سخت گناہ میں مبتلا ہو گا۔', 'اور وہ لوگ کہ نہیں پکارتے اللہ کے ساتھ دوسرے حاکم کو اور نہیں خون کرتے جان کا جو منع کر دی اللہ نے مگر جہاں چاہئے [۸۲] اور بدکاری نہیں کرتے اور جو کوئی کرے یہ کام وہ جا پڑ اگناہ میں [۸۳]', 'And those who invoke not any other ilah (god) along with Allah, nor kill such life as Allah has forbidden, except for just cause, nor commit illegal sexual intercourse and whoever does this shall receive the punishment.', '- and those who do not invoke any other god along with Allah, and do not kill a person whom Allah has given sanctity, except rightfully, nor do they fornicate; and whoever does it, shall face the recompense of his sin,'),
(2924, 25, 69, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'یُّضٰعَفۡ لَہُ  الۡعَذَابُ یَوۡمَ  الۡقِیٰمَۃِ وَ یَخۡلُدۡ   فِیۡہٖ   مُہَانًا ﴿٭ۖ۶۹﴾', 'قیامت کے دن اسکو دونا عذاب ہو گا اور وہ ذلت و خواری سے ہمیشہ اس میں رہے گا۔', 'دونا ہو گا اس کو عذب قیامت کےدن اور پڑا رہے گا اس میں خوار ہو کر [۸۴]', 'The torment will be doubled to him on the Day of Resurrection, and he will abide therein in disgrace;', 'the punishment will be doubled for him, and he will remain there disdained, for ever,'),
(2925, 25, 70, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'اِلَّا مَنۡ تَابَ وَ اٰمَنَ وَ عَمِلَ عَمَلًا صَالِحًا فَاُولٰٓئِکَ یُبَدِّلُ اللّٰہُ سَیِّاٰتِہِمۡ  حَسَنٰتٍ ؕ وَ کَانَ  اللّٰہُ  غَفُوۡرًا  رَّحِیۡمًا ﴿۷۰﴾', 'مگر جس نے توبہ کی اور ایمان لایا اور اچھے کام کئے تو ایسے لوگوں کے گناہوں کو اللہ نیکیوں سے بدل دے گا اور اللہ تو بخشنے والا ہے مہربان ہے۔', 'مگر جس نے توبہ کی اور یقین لایا اور کیا کچھ کام نیک سو ان کو بدل دے گا، اللہ برائیوں کی جگہ بھلائیاں اور ہے اللہ بخشنے والا مہربان [۸۵]', 'Except those who repent and believe (in Islamic Monotheism), and do righteous deeds, for those, Allah will change their sins into good deeds, and Allah is Oft-Forgiving, Most Merciful.', 'except the one who repents and believes and does good deeds, then Allah will replace the evils of such people by good deeds, and Allah is Most-Forgiving, Very-Merciful.'),
(2926, 25, 71, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ مَنۡ تَابَ وَ عَمِلَ صَالِحًا فَاِنَّہٗ یَتُوۡبُ اِلَی  اللّٰہِ  مَتَابًا ﴿۷۱﴾', 'اور جو توبہ کرتا اور عمل نیک کرتا ہے تو بیشک وہ اللہ کی طرف رجوع کرتا ہے۔', 'اور جو کوئی توبہ کرے اور کرے کام نیک سو وہ پھر آتا ہے اللہ کی طرف پھر آنے کی جگہ [۸۶]', 'And whosoever repents and does righteous good deeds, then verily, he repents towards Allah with true repentance.', 'Whoever repents and does righteous deeds turns to Allah truly'),
(2927, 25, 72, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ الَّذِیۡنَ لَا یَشۡہَدُوۡنَ الزُّوۡرَ ۙ وَ اِذَا مَرُّوۡا بِاللَّغۡوِ  مَرُّوۡا کِرَامًا ﴿۷۲﴾', 'اور وہ جو جھوٹی گواہی نہیں دیتے اور جب انکو بیہودہ چیزوں کے پاس سے گذرنے کا اتفاق ہو تو شریفانہ انداز سے گذرتے ہیں۔', 'اور جو لوگ شامل نہیں ہوتے جھوٹے کام میں [۸۷] اور جب گزرتے ہیں کھیل کی باتوں پر نکل جائیں بزرگانہ [۸۸]', 'And those who do not witness falsehood, and if they pass by some evil play or evil talk, they pass by it with dignity.', '- and those who do not witness falsehood, and when they pass by the absurd things, Pass by them with dignity,'),
(2928, 25, 73, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ الَّذِیۡنَ  اِذَا ذُکِّرُوۡا بِاٰیٰتِ رَبِّہِمۡ لَمۡ یَخِرُّوۡا عَلَیۡہَا صُمًّا وَّ عُمۡیَانًا ﴿۷۳﴾', 'اور وہ کہ جب انکو انکے پروردگار کی باتیں سمجھائی جاتی ہیں تو ان پر اندھے اور بہرے ہو کر نہیں گرتے بلکہ غوروفکر سے سنتے ہیں۔', 'اور وہ لوگ کہ جب انکو سمجھائیں انکے رب کی باتیں نہ پڑیں ان پر بہرے اندھے ہو کر [۸۹]', 'And those who, when they are reminded of the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of their Lord, fall not deaf and blind thereat.', 'and those who, when they are reminded of the verses of their Lord, do not fall at them as deaf and blind ones,'),
(2929, 25, 74, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'وَ الَّذِیۡنَ یَقُوۡلُوۡنَ رَبَّنَا ہَبۡ لَنَا مِنۡ اَزۡوَاجِنَا وَ ذُرِّیّٰتِنَا قُرَّۃَ اَعۡیُنٍ وَّ اجۡعَلۡنَا لِلۡمُتَّقِیۡنَ اِمَامًا ﴿۷۴﴾', 'اور وہ جو دعا مانگتے ہیں کہ اے پروردگار ہم کو ہماری بیویوں کی طرف سے اور اولاد کی طرف سے آنکھوں کی ٹھنڈک عطا فرما اور ہمیں پرہیزگاروں کا امام بنا۔', 'اور وہ لوگ جو کہتے ہیں اے رب دے ہم کو ہماری عورتوں کی طرف سے اور اولاد کی طرف سے آنکھ کی ٹھنڈک [۹۰] اور کر ہم کو پرہیزگاروں کا پیشوا [۹۱]', 'And those who say: \"Our Lord! Bestow on us from our wives and our offspring who will be the comfort of our eyes, and make us leaders for the Muttaqoon\" (pious - see V.2:2 and the footnote of V.3:164).\"', '- and those who say, “Our Lord, Give us, from our spouses and our children, comfort of eyes, and make us heads of the God-fearing.”'),
(2930, 25, 75, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'اُولٰٓئِکَ یُجۡزَوۡنَ الۡغُرۡفَۃَ  بِمَا صَبَرُوۡا وَ یُلَقَّوۡنَ فِیۡہَا تَحِیَّۃً  وَّ  سَلٰمًا ﴿ۙ۷۵﴾', 'ان صفات کے لوگوں کو انکے صبر کے بدلے اونچے اونچے محل دیئے جائیں گے۔ اور وہاں فرشتے ان سے دعا و سلام کے ساتھ ملاقات کریں گے۔', 'ان کو بدلہ ملے گا کوٹھوں کی جھروکے اس لئے کہ وہ ثابت قدم رہے اور لینے آئیں گے ان کو وہاں دعا و سلام کہتے ہوئے [۹۲]', 'Those will be rewarded with the highest place (in Paradise) because of their patience. Therein they shall be met with greetings and the word of peace and respect.', 'Such people will be rewarded with the high place - because they observed patience - and will be received therein with prayers of their eternal life and peace,'),
(2931, 25, 76, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'خٰلِدِیۡنَ فِیۡہَا ؕ حَسُنَتۡ مُسۡتَقَرًّا وَّ مُقَامًا ﴿۷۶﴾', 'اس میں وہ ہمیشہ رہیں گے۔ اور وہ ٹھہرنے اور رہنے کی بہت ہی عمدہ جگہ ہے۔', 'سدا رہا کریں ان میں خوب جگہ ہے ٹھہرنے کی اور خوب جگہ رہنے کی [۹۳]', 'Abiding therein; excellent it is as an abode, and as a place to dwell.', 'living in it (the Paradise) for ever. It is best as an abode and as a place to dwell in.'),
(2932, 25, 77, 6, 4, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الفرقان', 'قُلۡ  مَا یَعۡبَؤُا بِکُمۡ  رَبِّیۡ  لَوۡ لَا دُعَآؤُکُمۡ ۚ فَقَدۡ کَذَّبۡتُمۡ  فَسَوۡفَ  یَکُوۡنُ  لِزَامًا ﴿٪۷۷﴾', 'کہدو کہ اگر تم اللہ کو نہیں پکارتے تو میرا پروردگار بھی تمہاری کچھ پروا نہیں کرتا۔ تم نے تکذیب کی ہے سو اب مڈھ بھیڑ ہو گی۔', 'تو کہہ پروا نہیں رکھتا میرا رب تمہاری اگر تم اس کو نہ پکارا کرو [۹۴] سو تم تو جھٹلا چکے اب آگے کو ہونی ہے مٹھ بھیڑ [۹۵]', 'Say (O Muhammad SAW to the disbelievers): \"My Lord pays attention to you only because of your invocation to Him. But now you have indeed denied (Him). So the torment will be yours for ever (inseparable permanent punishment).\"', 'Say (O Prophet), “My Lord will never care about you, if you will not invoke Him. Now since you rejected (the truth), the punishment will be inseparable from you.”'),
(2933, 26, 1, 1, 5, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'طٰسٓمّٓ ﴿۱﴾', 'طٰسم۔', 'طٰسم۔', 'TaSeenMeem. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings.)', 'Tā sīn mīm.'),
(2934, 26, 2, 1, 5, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'تِلۡکَ اٰیٰتُ  الۡکِتٰبِ  الۡمُبِیۡنِ ﴿۲﴾', 'یہ کتاب روشن کی آیتیں ہیں۔', 'یہ آیتیں ہیں کھلی کتاب کی [۱]', 'These are the Verses of the manifest Book (this Quran, which was promised by Allah in the Taurat (Torah) and the Injeel (Gospel), makes things clear).', 'These are the verses of the manifest Book.'),
(2935, 26, 3, 1, 5, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'لَعَلَّکَ بَاخِعٌ نَّفۡسَکَ اَلَّا یَکُوۡنُوۡا مُؤۡمِنِیۡنَ ﴿۳﴾', 'اے پیغمبر شاید تم اس رنج سے کہ یہ لوگ ایمان نہیں لاتے اپنے آپکو ہلاکت میں ڈال دو گے۔', 'شاید تو گھونٹ مارے اپنی جان اس بات پر کہ وہ یقین نہیں کرتے [۲]', 'It may be that you (O Muhammad SAW) are going to kill yourself with grief, that they do not become believers (in your Risalah (Messengership) and in your Message of Islamic Monotheism).', '(O Prophet,) perhaps you are going to let yourself collapse in grief because they do not believe.'),
(2936, 26, 4, 1, 5, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنۡ نَّشَاۡ نُنَزِّلۡ عَلَیۡہِمۡ مِّنَ السَّمَآءِ  اٰیَۃً فَظَلَّتۡ اَعۡنَاقُہُمۡ  لَہَا خٰضِعِیۡنَ ﴿۴﴾', 'اگر ہم چاہیں تو ان پر آسمان سے کوئی نشانی اتار دیں پھر انکی گردنیں اسکے آگے جھک جائیں۔', 'اگر ہم چاہیں اتاریں ان پر آسمان سے ایک نشانی پھر رہ جائیں ان کی گردنیں اس کے آگے نیچی [۳]', 'If We will, We could send down to them from the heaven a sign, to which they would bend their necks in humility.', 'If We so will, We can send down to them a sign from the sky, for which their necks will stay bent in submission.'),
(2937, 26, 5, 1, 5, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ مَا یَاۡتِیۡہِمۡ مِّنۡ ذِکۡرٍ مِّنَ الرَّحۡمٰنِ مُحۡدَثٍ  اِلَّا  کَانُوۡا عَنۡہُ  مُعۡرِضِیۡنَ  ﴿۵﴾', 'اور انکے پاس رحمٰن کی طرف سے کوئی نئی نصیحت نہیں آتی مگر یہ اس سے منہ پھیر لیتے ہیں۔', 'اور نہیں پہنچتی ان کے پاس کوئی نصیحت رحمٰن سے نئی جس سے منہ نہیں موڑتے [۴]', 'And never comes there unto them a Reminder as a recent revelation from the Most Beneficent (Allah), but they turn away therefrom.', 'Never a new message comes to them from the RaHmān (the All-Merciful Allah), but they become averse to it.'),
(2938, 26, 6, 1, 5, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَقَدۡ کَذَّبُوۡا  فَسَیَاۡتِیۡہِمۡ  اَنۡۢبٰٓؤُا مَا کَانُوۡا  بِہٖ  یَسۡتَہۡزِءُوۡنَ ﴿۶﴾', 'سو یہ تو جھٹلا چکے اب انکو اس چیز کی حقیقت معلوم ہو جائے گی جسکی ہنسی اڑاتے تھے۔', 'سو یہ تو جھٹلا چکے اب پہنچے گی ان پر حقیقت اس بات کی جس پر ٹھٹھے کرتے تھے [۵]', 'So they have indeed denied (the truth this Quran), then the news of what they mocked at, will come to them.', 'Thus they rejected (the Truth); well, soon will come to them the real descriptions of what they used to ridicule.'),
(2939, 26, 7, 1, 5, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اَوَ لَمۡ یَرَوۡا اِلَی الۡاَرۡضِ کَمۡ اَنۡۢبَتۡنَا فِیۡہَا مِنۡ  کُلِّ  زَوۡجٍ   کَرِیۡمٍ ﴿۷﴾', 'کیا انہوں نے زمین کی طرف نہیں دیکھا کہ ہم نے اس میں ہر قسم کی کتنی نفیس چیزیں اگائی ہیں۔', 'کیا نہیں دیکھتے وہ زمین کو کتنی اگائیں ہم نے اس میں ہر ایک قسم کی خاصی چیزیں', 'Do they not observe the earth, how much of every good kind We cause to grow therein?', 'Have they not looked at the earth, how many of the noble pairs (of vegetation) We have caused to grow in it?'),
(2940, 26, 8, 1, 5, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنَّ فِیۡ ذٰلِکَ لَاٰیَۃً  ؕوَ مَا کَانَ اَکۡثَرُ ہُمۡ مُّؤۡمِنِیۡنَ ﴿۸﴾', 'کچھ شک نہیں کہ اس میں نشانی ہے مگر یہ اکثر ایمان لانے والے نہیں۔', 'اس میں البتہ نشانی ہے اور ان میں بہت لوگ نہیں ماننے والے [۶]', 'Verily, in this is an Ayah (proof or sign), yet most of them (polytheists, pagans, etc., who do not believe in Resurrection) are not believers.', 'Surely, in this there is a sign, but most of them are not believers,'),
(2941, 26, 9, 1, 5, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اِنَّ  رَبَّکَ  لَہُوَ  الۡعَزِیۡزُ  الرَّحِیۡمُ ﴿٪۹﴾', 'اور تمہارا پروردگار غالب ہے مہربان ہے۔', 'اور تیرا رب وہی ہے زبردست رحم والا [۷]', 'And verily, your Lord! He is truly the All-Mighty, the Most Merciful.', 'and indeed your Lord is the Mighty, the Merciful.'),
(2942, 26, 10, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اِذۡ نَادٰی رَبُّکَ مُوۡسٰۤی  اَنِ ائۡتِ الۡقَوۡمَ  الظّٰلِمِیۡنَ ﴿ۙ۱۰﴾', 'اور جب تمہارے پروردگار نے موسٰی کو پکارا کہ ظالم لوگوں کے پاس جاؤ۔', 'اور جب پکارا تیرے رب نے موسٰی کو کہ جا اس قوم گنہگار کے پاس', 'And (remember) when your Lord called Moosa (Moses) (saying): \"Go to the people who are Zalimoon (polytheists and wrong-doing),', '(Remember) when your Lord called Mūsā saying, “Go to the transgressing people,'),
(2943, 26, 11, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَوۡمَ  فِرۡعَوۡنَ ؕ اَلَا  یَتَّقُوۡنَ  ﴿۱۱﴾', 'یعنی قوم فرعون کے پاس۔ کیا وہ ڈرتے نہیں۔', 'قوم فرعون کے پاس کیا وہ ڈرتے نہیں [۸]', 'The people of Firaun (Pharaoh). Will they not fear Allah and become righteous?\"', 'the people of Pharaoh. Do they not fear Allah?”'),
(2944, 26, 12, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ  رَبِّ  اِنِّیۡۤ   اَخَافُ اَنۡ  یُّکَذِّبُوۡنِ ﴿ؕ۱۲﴾', 'انہوں نے کہا کہ میرے پروردگار میں ڈرتا ہوں کہ وہ مجھے جھوٹا سمجھیں۔', 'بولا اے رب میں ڈرتا ہوں کہ مجھ کو جھٹلائیں', 'He said: \"My Lord! Verily, I fear that they will belie me,', 'He (Mūsā) said, “My Lord, I fear that they will reject me.'),
(2945, 26, 13, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ یَضِیۡقُ صَدۡرِیۡ  وَ لَا یَنۡطَلِقُ لِسَانِیۡ فَاَرۡسِلۡ  اِلٰی ہٰرُوۡنَ ﴿۱۳﴾', 'اور میرا دل تنگ ہوتا ہے اور میری زبان رکتی ہے تو ہارون کو حکم بھیج کہ میرے ساتھ چلیں۔', 'اور رک جاتا ہے میرا جی اور نہیں چلتی میری زبان سو پیغام دے ہارون کو [۹]', '\"And my breast straitens, and my tongue expresses not well. So send for Haroon (Aaron) (to come along with me).', 'My heart gets straitened, and my tongue is not fluent; so send for Hārūn.'),
(2946, 26, 14, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ لَہُمۡ عَلَیَّ  ذَنۡۢبٌ فَاَخَافُ اَنۡ یَّقۡتُلُوۡنِ  ﴿ۚ۱۴﴾', 'اور ان لوگوں کا مجھ پر ایک گناہ یعنی فرعونی کے خون کا دعوٰی بھی ہے سو مجھے یہ بھی ڈر ہے کہ مجھ کو مار ہی ڈالیں۔', 'اور انکو مجھ پر ہے ایک گناہ کا دعویٰ [۱۰] سو ڈرتا ہوں کہ مجھ کو مار ڈالیں [۱۱]', '\"And they have a charge of crime against me, and I fear they will kill me.\"', 'Moreover, they have (leveled) a charge of offence against me, and I fear they will kill me;”'),
(2947, 26, 15, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ کَلَّا ۚ فَاذۡہَبَا بِاٰیٰتِنَاۤ  اِنَّا مَعَکُمۡ مُّسۡتَمِعُوۡنَ ﴿۱۵﴾', 'فرمایا ہرگز نہیں۔ پس تم دونوں ہماری نشانیاں لیکر جاؤ ہم تمہارے ساتھ سننے والے ہیں۔', 'فرمایا کبھی نہیں تم دونوں جاؤ لیکر ہماری نشانیاں ہم ساتھ تمہارے سنتے ہیں [۱۲]', 'Allah said: \"Nay! Go you both with Our Signs. Verily! We shall be with you, listening.', 'He (Allah) said, “Never! (They will not be able to kill you.) So go, both of you, with Our signs. We are with you, listening (to the conversation you will have with him.)'),
(2948, 26, 16, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاۡتِیَا فِرۡعَوۡنَ فَقُوۡلَاۤ  اِنَّا رَسُوۡلُ رَبِّ الۡعٰلَمِیۡنَ ﴿ۙ۱۶﴾', 'سو دونوں فرعون کے پاس جاؤ اور کہو کہ ہم تمام جہانوں کے مالک کے بھیجے ہوئے ہیں۔', 'سو جاؤ فرعون کے پاس اور کہو ہم پیغام لے کر آئے ہیں پروردگار عالم کا', '\"And when you both come to Firaun (Pharaoh), say: We are the Messengers of the Lord of the Alameen (mankind, jinns and all that exists),', 'So go, both of you, to Pharaoh and say, ‘We both are messengers of the Lord of all the worlds,'),
(2949, 26, 17, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اَنۡ  اَرۡسِلۡ  مَعَنَا بَنِیۡۤ   اِسۡرَآءِیۡلَ ﴿ؕ۱۷﴾', 'اور اس لئے آئے ہیں کہ آپ بنی اسرائیل کو ہمارے ساتھ جانے کی اجازت دیں۔', 'یہ کہ بھیجدے ہمارے ساتھ بنی اسرائیل کو [۱۳]', '\"So allow the Children of Israel to go with us. \"', '(sent with the message) that you must send the children of Isrā’īl with us’”.'),
(2950, 26, 18, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ اَلَمۡ  نُرَبِّکَ فِیۡنَا وَلِیۡدًا وَّ لَبِثۡتَ فِیۡنَا مِنۡ عُمُرِکَ  سِنِیۡنَ ﴿ۙ۱۸﴾', 'فرعون نے موسٰی سے کہا کیا ہم نے تمکو جبکہ تم بچے تھے پرورش نہیں کیا تھا اور تم نے برسوں ہمارے ہاں عمر بسر نہیں کی؟', 'بولا کیا نہیں پالا ہم نے تجھ کو اپنے اندر لڑکا سا [۱۴] اور رہا تو ہم میں اپنی عمر میں سے کئ برس [۱۵]', '(Firaun (Pharaoh)) said (to Moosa (Moses)): \"Did we not bring you up among us as a child? And you did dwell many years of your life with us.', 'He (Pharaoh) said, “Did we not nourish you among us as a child? And you remained amidst us for years,'),
(2951, 26, 19, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ فَعَلۡتَ فَعۡلَتَکَ الَّتِیۡ فَعَلۡتَ وَ اَنۡتَ مِنَ الۡکٰفِرِیۡنَ ﴿۱۹﴾', 'اور تم نے ایک اور کام کیا تھا جو کیا تم ناشکرے معلوم ہوتے ہو۔', 'اور کر گیا تو اپنی وہ کرتوت جو کر گیا [۱۶] اور تو ہے ناشکر [۱۷]', '\"And you did your deed, which you did (i.e. the crime of killing a man). And you are one of the ingrates.\"', 'and you did the blunder you did; still you are ungrateful.”'),
(2952, 26, 20, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ فَعَلۡتُہَاۤ  اِذًا وَّ اَنَا مِنَ الضَّآلِّیۡنَ ﴿ؕ۲۰﴾', 'موسٰی نے کہا کہ ہاں وہ حرکت مجھ سے ناگہاں سرزد ہوئی تھی اور میں خطاکاروں میں تھا۔', 'کہا کیا تو تھا میں نے وہ کام اور میں تھا چوکنے والا [۱۸]', 'Moosa (Moses) said: \"I did it then, when I was an ignorant (as regards my Lord and His Message).', 'He said, “I did that at a time when I was mistaken.'),
(2953, 26, 21, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَفَرَرۡتُ مِنۡکُمۡ  لَمَّا خِفۡتُکُمۡ  فَوَہَبَ لِیۡ رَبِّیۡ حُکۡمًا وَّ جَعَلَنِیۡ مِنَ الۡمُرۡسَلِیۡنَ ﴿۲۱﴾', 'پھر جب مجھے تم سے ڈر لگا تو میں تمہارے پاس سے فرار ہو گیا۔ پھر میرے رب نے مجھکو نبوت و علم بخشا اور مجھے پیغمبروں میں سے کیا۔', 'پھر بھاگا میں تم سے جب تمہارا ڈر دیکھا پھر بخشا مجھ کو میرے رب نے حکم اور ٹھہرایا مجھ کو پیغام پہنچانے والا [۱۹]', '\"So I fled from you when I feared you. But my Lord has granted me Hukman (i.e. religious knowledge, right judgement of the affairs and Prophethood), and appointed me as one of the Messengers.', 'Then I fled away from you when I feared you. Thereafter my Lord granted wisdom to me, and made me one of the messengers.'),
(2954, 26, 22, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ تِلۡکَ نِعۡمَۃٌ  تَمُنُّہَا عَلَیَّ  اَنۡ عَبَّدۡتَّ بَنِیۡۤ   اِسۡرَآءِیۡلَ ﴿ؕ۲۲﴾', 'اور کیا یہی احسان ہے جو آپ مجھ پر رکھتے ہیں کہ آپ نے بنی اسرائیل کو غلام بنا رکھا ہے۔', 'اور کیا وہ احسان ہے جو تو مجھ پر رکھتا ہے کہ غلام بنایا تو نے بنی اسرائیل کو [۲۰]', '\"And this is the past favour with which you reproach me, that you have enslaved the Children of Israel.\"', 'As for the favor with which you are obliging me, it is that you have enslaved the children of Isrā’īl.”'),
(2955, 26, 23, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ فِرۡعَوۡنُ  وَ  مَا رَبُّ الۡعٰلَمِیۡنَ ﴿ؕ۲۳﴾', 'فرعون نے کہا اور رب العالمین کیا ہوتا ہے؟', 'بولا فرعون کیا معنی پروردگار عالم کا [۲۱]', 'Firaun (Pharaoh) said: \"And what is the Lord of the Alameen (mankind, jinns and all that exists)?\"', 'Pharaoh said, “What is the Lord of the worlds?”'),
(2956, 26, 24, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ رَبُّ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ مَا بَیۡنَہُمَا ؕ اِنۡ  کُنۡتُمۡ  مُّوۡقِنِیۡنَ ﴿۲۴﴾', 'فرمایا آسمانوں اور زمین اور جو کچھ ان دونوں میں ہے سب کا مالک۔ بشرطیکہ تم لوگوں کو یقین ہو۔', 'کہا پروردگار آسمان اور زمین کا اور جو کچھ انکے بیچ میں ہے اگر تم یقین کرو [۲۲]', 'Moosa (Moses) said: \"Lord of the heavens and the earth, and all that is between them, if you seek to be convinced with certainty.\"', 'He (Mūsā) said, “Lord of the heavens and the earth and whatever there is between them, if you are to believe”'),
(2957, 26, 25, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ  لِمَنۡ  حَوۡلَہٗۤ   اَلَا  تَسۡتَمِعُوۡنَ ﴿۲۵﴾', 'فرعون نے اپنےاردگرد کے لوگوں سے کہا کہ کیا تم سنتے نہیں؟', 'بولا اپنے گرد والوں سے کیا تم نہیں سنتے ہو [۲۳]', 'Firaun (Pharaoh) said to those around: \"Do you not hear (what he says)?\"', 'He (The Pharaoh) said to those around him, “Are you not hearing?”'),
(2958, 26, 26, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ رَبُّکُمۡ وَ رَبُّ اٰبَآئِکُمُ  الۡاَوَّلِیۡنَ ﴿۲۶﴾', 'موسٰی نے کہا کہ تمہارا اور تمہارے اگلے باپ دادوں کا بھی مالک۔', 'کہا پروردگار تمہارا اور پروردگار تمہارے اگلے باپ دادوں کا [۲۴]', 'Moosa (Moses) said: \"Your Lord and the Lord of your ancient fathers!\"', 'He (Mūsā) said, “Your Lord and the Lord of your early forefathers”'),
(2959, 26, 27, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ  اِنَّ رَسُوۡلَکُمُ الَّذِیۡۤ اُرۡسِلَ  اِلَیۡکُمۡ  لَمَجۡنُوۡنٌ ﴿۲۷﴾', 'فرعون نے کہا کہ یہ پیغمبر جو تمہاری طرف بھیجا گیا ہے باؤلا ہے۔', 'بولا تمہارا  پیغام لانے والا جو تمہاری طرف بھیجا گیا ضرور باؤلا ہے [۲۵]', 'Firaun (Pharaoh) said: \"Verily, your Messenger who has been sent to you is a madman!\"', 'He (Pharaoh) said, “Your messenger who is sent to you is a mad man indeed.”'),
(2960, 26, 28, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ رَبُّ الۡمَشۡرِقِ وَ الۡمَغۡرِبِ وَ مَا بَیۡنَہُمَا ؕ اِنۡ  کُنۡتُمۡ  تَعۡقِلُوۡنَ ﴿۲۸﴾', 'موسٰی نے کہا کہ مشرق اور مغرب اور جو کچھ ان دونوں کے درمیان ہے سب کا مالک بشرطیکہ تمکو سمجھ ہو۔', 'کہا پروردگار مشرق کا اور مغرب کا اور جو کچھ ان کے بیچ میں ہے اگر تم سمجھ رکھتے ہو [۲۶]', 'Moosa (Moses) said: \"Lord of the east and the west, and all that is between them, if you did but understand!\"', 'He (Mūsā) said, “Lord of the East and the West and whatever lies between them, if you are to understand.”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(2961, 26, 29, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ لَئِنِ اتَّخَذۡتَ اِلٰـہًا غَیۡرِیۡ لَاَجۡعَلَنَّکَ مِنَ  الۡمَسۡجُوۡنِیۡنَ ﴿۲۹﴾', 'فرعون نے کہا کہ اگر تم نے میرے سوا کسی اور کو معبود بنایا تو میں تمہیں قید کر دوں گا۔', 'بولا اگر تو نے ٹھہرایا کوئی اور حاکم میرے سوائے تو مقرر (ضرور)  ڈالوں گا تجھ کو قید میں [۲۷]', 'Firaun (Pharaoh) said: \"If you choose an ilah (god) other than me, I will certainly put you among the prisoners.\"', 'He (Pharaoh) said, “If you adopt a God other than me, I will certainly put you to prison.”'),
(2962, 26, 30, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ  اَوَ لَوۡ  جِئۡتُکَ بِشَیۡءٍ  مُّبِیۡنٍ ﴿ۚ۳۰﴾', 'موسٰی نے کہا خواہ میں آپکے پاس روشن چیز لاؤں یعنی معجزہ؟', 'کہا اور اگر لیکر آیا ہوں تیرے پاس ایک چیز کھول دینے والی [۲۸]', 'Moosa (Moses) said: \"Even if I bring you something manifest (and convincing)?\"', 'He (Mūsā) said “Will you (do this) even if I bring to you something evident?”'),
(2963, 26, 31, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ فَاۡتِ بِہٖۤ  اِنۡ  کُنۡتَ مِنَ الصّٰدِقِیۡنَ ﴿۳۱﴾', 'فرعون نے کہا اگر سچے ہو تو اسے لاؤ دکھاؤ۔', 'بولا تو وہ چیز لا اگر تو سچ کہتا ہے', 'Firaun (Pharaoh) said: \"Bring it forth then, if you are of the truthful!\"', 'He said, “Then bring it, if you are truthful.”'),
(2964, 26, 32, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاَلۡقٰی عَصَاہُ  فَاِذَا ہِیَ ثُعۡبَانٌ  مُّبِیۡنٌ ﴿ۚۖ۳۲﴾', 'پس انہوں نے اپنی لاٹھی ڈال دی تو وہ اسی وقت صاف اژدھا بن گئ۔', 'پھر ڈال دیا اپنا عصا سو اسی وقت وہ اژدھا ہو گیا صریح', 'So (Moosa (Moses)) threw his stick, and behold, it was a serpent, manifest.', 'So, he threw down his staff, and in no time it was a serpent, clearly visible,'),
(2965, 26, 33, 2, 6, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَّ نَزَعَ یَدَہٗ  فَاِذَا ہِیَ بَیۡضَآءُ  لِلنّٰظِرِیۡنَ ﴿٪۳۳﴾', 'اور اپنا ہاتھ جو نکالا تو اسی دم دیکھنے والوں کے لئے سفید براق نظر آنے لگا۔', 'اور اندر (بغل)  سے نکالا اپنا ہاتھ سو اسی وقت وہ سفید تھا دیکھنے والوں کے سامنے', 'And he drew out his hand, and behold, it was white to all beholders!', 'and he drew out his hand, and right then it was a white light to the onlookers.'),
(2966, 26, 34, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ لِلۡمَلَاِ حَوۡلَہٗۤ  اِنَّ ہٰذَا  لَسٰحِرٌ  عَلِیۡمٌ ﴿ۙ۳۴﴾', 'فرعون نے اپنے گرد کے سرداروں سے کہا کہ یہ تو ایک ماہر جادوگر ہے۔', 'بولا اپنے گرد کے سرداروں سے یہ تو کوئی جادوگر ہے پڑھا ہوا', '(Firaun (Pharaoh)) said to the chiefs around him: \"Verily! This is indeed a well-versed sorcerer.', 'He (Pharaoh) said to the chiefs around him “This man is certainly an expert sorcerer”.'),
(2967, 26, 35, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'یُّرِیۡدُ  اَنۡ یُّخۡرِجَکُمۡ مِّنۡ  اَرۡضِکُمۡ بِسِحۡرِہٖ ٭ۖ  فَمَا ذَا  تَاۡمُرُوۡنَ  ﴿۳۵﴾', 'چاہتا ہے کہ تمکو اپنے جادو کے زور سے تمہارے ملک سے نکال دے تو تمہاری کیا رائے ہے؟', 'چاہتا ہے کہ نکال دے تم کو تمہارے دیس سے اپنے جادو کے زور سے سو اب کیا حکم دیتے ہو [۲۹]', '\"He wants to drive you out of your land by his sorcery, then what is it your counsel, and what do you command?\"', 'He wants to expel you from your land with his sorcery. So what do you suggest?”'),
(2968, 26, 36, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالُوۡۤا اَرۡجِہۡ  وَ اَخَاہُ  وَ ابۡعَثۡ فِی الۡمَدَآئِنِ  حٰشِرِیۡنَ ﴿ۙ۳۶﴾', 'انہوں نے کہا کہ اسکو اور اسکے بھائی کو کچھ مہلت دیجئے اور شہروں میں نقیب بھیج دیجئے۔', 'بولے ڈھیل دے اسکو اور اسکے بھائی کو اور بھیجدے شہروں میں نقیب', 'They said: \"Put him off and his brother (for a while), and send callers to the cities;', 'They said, “Leave him and his brother alone for some time, and send heralds to the cities,'),
(2969, 26, 37, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'یَاۡتُوۡکَ  بِکُلِّ  سَحَّارٍ  عَلِیۡمٍ ﴿۳۷﴾', 'کہ سب ماہر جادوگروں کو جمع کر کے آپ کے پاس لے آئیں۔', 'لے آئیں تیرے پاس جو بڑا جادوگر ہو پڑھا ہوا', '\"To bring up to you every well-versed sorcerer.\"', 'so that they bring to you every highly expert sorcerer.”'),
(2970, 26, 38, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَجُمِعَ  السَّحَرَۃُ  لِمِیۡقَاتِ یَوۡمٍ مَّعۡلُوۡمٍ  ﴿ۙ۳۸﴾', 'آخر جادوگر ایک مقررہ دن کی معیاد پر جمع ہو گئے۔', 'پھر اکٹھے کئے جادوگر وعدہ پر ایک مقرر دن کے [۳۰]', 'So the sorcerers were assembled at a fixed time on a day appointed.', 'So the sorcerers were assembled for the appointed time of a known day,'),
(2971, 26, 39, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَّ قِیۡلَ لِلنَّاسِ ہَلۡ اَنۡتُمۡ مُّجۡتَمِعُوۡنَ ﴿ۙ۳۹﴾', 'اور لوگوں سے کہدیا گیا کہ تم سب کو اکٹھے ہو جانا چاہیے۔', 'اور کہہ دیا لوگوں کو کیا تم بھی اکٹھے ہو گئے', 'And it was said to the people: \"Are you (too) going to assemble?', 'and it was said to the people, “Would you assemble,'),
(2972, 26, 40, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'لَعَلَّنَا نَتَّبِعُ السَّحَرَۃَ  اِنۡ کَانُوۡا ہُمُ الۡغٰلِبِیۡنَ ﴿۴۰﴾', 'تاکہ اگر جادوگر غالب رہیں تو ہم انکے پیرو ہو جائیں۔', 'شاید ہم راہ قبول کر لیں جادوگروں کی اگر ہو ان کو غلبہ [۳۱]', '\"That we may follow the sorcerers (who were on Firauns (Pharaoh) religion of disbelief) if they are the winners.\"', 'so that we may follow the sorcerers if they are victorious?”'),
(2973, 26, 41, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَلَمَّا جَآءَ السَّحَرَۃُ  قَالُوۡا لِفِرۡعَوۡنَ اَئِنَّ لَنَا لَاَجۡرًا  اِنۡ  کُنَّا نَحۡنُ  الۡغٰلِبِیۡنَ ﴿۴۱﴾', 'پھر جب جادوگر آ گئے تو فرعون سے کہنے لگے کہ اگر ہم غالب رہے تو ہمیں صلہ بھی عطا ہو گا؟', 'پھر جب آئے جادوگر کہنے لگےفرعون سے بھلا کچھ ہمارا حق بھی ہے اگر ہو ہم کو غلبہ', 'So when the sorcerers arrived, they said to Firaun (Pharaoh): \"Will there surely be a reward for us if we are the winners?\"', 'So, when the sorcerers came, they said to Pharaoh, “Will there be a sure reward for us, if we are the victorious?”'),
(2974, 26, 42, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ نَعَمۡ  وَ  اِنَّکُمۡ  اِذًا  لَّمِنَ  الۡمُقَرَّبِیۡنَ  ﴿۴۲﴾', 'فرعون نے کہا ہاں اور تب تم مقربوں میں بھی داخل کر لئے جاؤ گے۔', 'بولا البتہ (ہاں)  اور تم اس وقت مقربوں (مصاحبوں)  میں ہو گے [۳۲]', 'He said: \"Yes, and you shall then verily be of those brought near (to myself).\"', 'He said, “Yes, and of course, you will then be among the closer ones.”'),
(2975, 26, 43, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ لَہُمۡ مُّوۡسٰۤی اَلۡقُوۡا مَاۤ  اَنۡتُمۡ مُّلۡقُوۡنَ ﴿۴۳﴾', 'موسٰی نے ان سے کہا کہ جو چیز ڈالنی چاہتے ہو ڈالو۔', 'کہا ان کو موسٰی نے ڈالو جو تم ڈالتے ہو [۳۳]', 'Moosa (Moses) said to them: \"Throw what you are going to throw!\"', 'Mūsā said to them, “Throw you down what you are to throw.”'),
(2976, 26, 44, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاَلۡقَوۡا حِبَالَہُمۡ وَ عِصِیَّہُمۡ وَ قَالُوۡا بِعِزَّۃِ  فِرۡعَوۡنَ  اِنَّا  لَنَحۡنُ  الۡغٰلِبُوۡنَ ﴿۴۴﴾', 'تو انہوں نے اپنی رسیاں اور لاٹھیاں ڈالیں اور کہنے لگے کہ فرعون کے اقبال کی قسم! ہم ہی ضرور غالب رہیں گے۔', 'پھر ڈالیں انہوں نے اپنی رسیاں اور لاٹھیاں اور بولے فرعون کے اقبال سے ہماری ہی فتح ہے [۳۴]', 'So they threw their ropes and their sticks, and said: \"By the might of Firaun (Pharaoh), it is we who will certainly win!\"', 'So they threw down their ropes and their staffs and said, “By the majesty of Pharaoh, we will be the triumphant for sure.”'),
(2977, 26, 45, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاَلۡقٰی مُوۡسٰی عَصَاہُ  فَاِذَا ہِیَ تَلۡقَفُ مَا  یَاۡفِکُوۡنَ ﴿ۚۖ۴۵﴾', 'پھر موسٰی نے اپنی لاٹھی ڈالی تو وہ ان چیزوں کو جو جادوگروں نے بنائی تھیں نگلنے لگی۔', 'پھر ڈالا موسٰی نے اپنا عصا پھر تبھی وہ نگلنے لگا جو سانگ انہوں نے بنایا تھا [۳۵]', 'Then Moosa (Moses) threw his stick, and behold, it swallowed up all the falsehoods which they showed!', 'Then Mūsā threw down his staff, and in no time it started swallowing the falsehood they invented.'),
(2978, 26, 46, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاُلۡقِیَ  السَّحَرَۃُ   سٰجِدِیۡنَ ﴿ۙ۴۶﴾', 'تب جادوگر سجدے میں گر پڑے۔', 'پھر اوندھے گرے جادوگر سجدہ میں', 'And the sorcerers fell down prostrate.', 'So the sorcerers were made (by the truth they saw) to fall down in prostration.'),
(2979, 26, 47, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالُوۡۤا  اٰمَنَّا  بِرَبِّ  الۡعٰلَمِیۡنَ ﴿ۙ۴۷﴾', 'اور کہنے لگے کہ ہم تمام جہان کے مالک پر ایمان لائے۔', 'بولے ہم نے مان لیا جہان کے رب کو', 'Saying: \"We believe in the Lord of the Alameen (mankind, jinns and all that exists).', 'They said, “We have believed in the Lord of the worlds,'),
(2980, 26, 48, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'رَبِّ مُوۡسٰی  وَ  ہٰرُوۡنَ ﴿۴۸﴾', 'جو موسٰی اور ہارون کا رب ہے۔', 'جو رب ہے موسٰی اور ہارون کا', '\"The Lord of Moosa (Moses) and Haroon (Aaron).\"', 'the Lord of Mūsā and Hārūn.”'),
(2981, 26, 49, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ اٰمَنۡتُمۡ لَہٗ  قَبۡلَ اَنۡ اٰذَنَ  لَکُمۡ ۚ اِنَّہٗ لَکَبِیۡرُکُمُ  الَّذِیۡ عَلَّمَکُمُ  السِّحۡرَ ۚ فَلَسَوۡفَ تَعۡلَمُوۡنَ ۬ؕ لَاُقَطِّعَنَّ اَیۡدِیَکُمۡ وَ اَرۡجُلَکُمۡ  مِّنۡ خِلَافٍ وَّ لَاُوصَلِّبَنَّکُمۡ   اَجۡمَعِیۡنَ ﴿ۚ۴۹﴾', 'فرعون نے کہا کیا اس سے پہلے کہ میں تمکو اجازت دوں تم اس پر ایمان لے آئے بیشک یہ تمہارا بڑا ہے جس نے تمکو جادو سکھایا ہے۔ سو عنقریب تم اس کا انجام معلوم کر لو گے کہ میں تمہارے ہاتھ اور مخالف سمت کے پاؤں کاٹ دوں گا اور تم سب کو سولی پر چڑھا دوں گا۔', 'بولا تم نے اسکو مان لیا ابھی میں نے حکم نہیں دیا تم کو  مقرر (بیشک) وہ تمہارا بڑا ہے جس نے تم کو سکھلایا جادو [۳۶] سو اب معلوم کر لو گے البتہ کاٹوں گا تمہارے ہاتھ اور دوسری طرف کے پاؤں اور سولی چڑھاؤں گا تم سب کو', '(Firaun (Pharaoh)) said: \"You have believed in him before I give you leave. Surely, he indeed is your chief, who has taught you magic! So verily, you shall come to know. Verily, I will cut off your hands and your feet on opposite sides, and I will crucify you all.\"', 'He (Pharaoh) said, “You have believed in him before I permit you. Surely, he (Mūsā) is the chief of you all, who has taught you sorcery. So you will soon know (your fate). I will cut off your hands and feet from different sides, and will crucify you all together.'),
(2982, 26, 50, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالُوۡا  لَا ضَیۡرَ ۫ اِنَّاۤ اِلٰی رَبِّنَا مُنۡقَلِبُوۡنَ ﴿ۚ۵۰﴾', 'انہوں نے کہا کہ کچھ نقصان کی بات نہیں ہم اپنے پروردگار کی طرف لوٹ جانے والے ہیں۔', 'بولے کچھ ڈر نہیں ہم کو اپنے رب کی طرف پھر جانا ہے [۳۷]', 'They said: \"No harm! Surely, to our Lord (Allah) we are to return;', 'They said, “There is no harm. We will return to our Lord.'),
(2983, 26, 51, 3, 7, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنَّا نَطۡمَعُ اَنۡ یَّغۡفِرَ لَنَا رَبُّنَا خَطٰیٰنَاۤ  اَنۡ  کُنَّاۤ   اَوَّلَ  الۡمُؤۡمِنِیۡنَ ﴿ؕ٪۵۱﴾', 'ہمیں امید ہے کہ ہمارا پروردگار ہمارے گناہ بخش دے گا۔ اس لئے کہ ہم اوّل ایمان لانے والوں میں ہو گئے۔', 'ہم غرض رکھتے ہیں کہ بخش دے ہم کو رب ہمارا تقصیریں ہماری اس واسطے کہ ہم ہوئے پہلے قبول کرنے والے [۳۸]', '\"Verily! We really hope that our Lord will forgive us our sins, as we are the first of the believers (in Moosa (Moses) and in the Monotheism which he has brought from Allah).\"', 'We really hope that our Lord will forgive us our faults, as we are the first of the believers.”'),
(2984, 26, 52, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ اَوۡحَیۡنَاۤ   اِلٰی مُوۡسٰۤی اَنۡ اَسۡرِ بِعِبَادِیۡۤ  اِنَّکُمۡ  مُّتَّبَعُوۡنَ ﴿۵۲﴾', 'اور ہم نے موسٰی کی طرف وحی بھیجی کہ ہمارے بندوں کو راتوں رات لے نکلو البتہ فرعونیوں کی طرف سے تمہارا تعاقب کیا جائے گا۔', 'اور حکم بھیجا ہم نے موسٰی کو کہ رات کو لے نکل میرے بندوں کو البتہ تمہارا پیچھا کریں گے [۳۹]', 'And We inspired Moosa (Moses), saying: \"Take away My slaves by night, verily, you will be pursued.\"', 'And We revealed to Mūsā saying, “Make My servants travel at night. You will be pursued.”'),
(2985, 26, 53, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاَرۡسَلَ فِرۡعَوۡنُ فِی الۡمَدَآئِنِ  حٰشِرِیۡنَ ﴿ۚ۵۳﴾', 'تو فرعون نے شہروں میں نقیب روانہ کئے۔', 'پھر بھیجے فرعون نے شہروں میں نقیب [۴۰]', 'Then Firaun (Pharaoh) sent callers to (all) the cities.', 'So Pharaoh sent into the cities (his) men to muster (people)'),
(2986, 26, 54, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنَّ  ہٰۤؤُلَآءِ   لَشِرۡ  ذِمَۃٌ  قَلِیۡلُوۡنَ ﴿ۙ۵۴﴾', 'اور کہا کہ یہ تھوڑے سے لوگوں کی جماعت ہے۔', 'یہ لوگ جو ہیں سو ایک جماعت ہے تھوڑی سی [۴۱]', '(Saying): \"Verily! These indeed are but a small band.', 'saying, “These are a small band,'),
(2987, 26, 55, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اِنَّہُمۡ  لَنَا  لَغَآئِظُوۡنَ ﴿ۙ۵۵﴾', 'اور یہ ہم سے غصہ کھا رہے ہیں۔', 'اور وہ مقرر ہم سے دل جلے ہوئے ہیں [۴۲]', '\"And verily, they have done what has enraged us;', 'and indeed they are enraging us,'),
(2988, 26, 56, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اِنَّا  لَجَمِیۡعٌ  حٰذِرُوۡنَ ﴿ؕ۵۶﴾', 'اور ہم سب ان سے خطرہ رکھتے ہیں۔', 'اور ہم سارے ان سے خطرہ رکھتے ہیں [۴۳]', '\"But we are host all assembled, amply fore-warned.\"', 'and we are a host, well-armed.”'),
(2989, 26, 57, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاَخۡرَجۡنٰہُمۡ مِّنۡ جَنّٰتٍ  وَّ  عُیُوۡنٍ ﴿ۙ۵۷﴾', 'آخر ہم نے انکو باغوں اور چشموں سے نکال دیا۔', 'پھر نکال باہر کیا ہم نے ان کو باغوں اور چشموں سے', 'So, We expelled them from gardens and springs,', 'Thus We expelled them (i.e. the people of Pharaoh) from gardens and springs,'),
(2990, 26, 58, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَّ کُنُوۡزٍ وَّ  مَقَامٍ  کَرِیۡمٍ ﴿ۙ۵۸﴾', 'اور خزانوں اور نفیس مکانات سے۔', 'اور خزانوں اور عمدہ مکانوں سے اسی طرح [۴۴]', 'Treasures, and every kind of honourable place.', 'and from treasures and a noble abode.'),
(2991, 26, 59, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'کَذٰلِکَ ؕ وَ اَوۡرَثۡنٰہَا بَنِیۡۤ   اِسۡرَآءِیۡلَ ﴿ؕ۵۹﴾', 'انکے ساتھ ہم نے اسی طرح کیا اور ان چیزوں کا وارث بنی اسرائیل کو بنا دیا۔', 'اور ہاتھ لگا دیں ہم نے یہ چیزیں بنی اسرائیل کے [۴۵]', 'Thus (We turned them (Pharaohs people) out) and We caused the Children of Israel to inherit them.', 'Thus it was. And We made the children of Isrā’īl inherit all such things.'),
(2992, 26, 60, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاَتۡبَعُوۡہُمۡ مُّشۡرِقِیۡنَ ﴿۶۰﴾', 'تو انہوں نے سورج نکلتے وقت انکا تعاقب کیا۔', 'پھر پیچھے پڑے ان کے سورج کے نکلنے کے وقت', 'So they pursued them at sunrise.', 'So they (the people of Pharaoh) pursued them (the people of Mūsā) at the time of sunrise.'),
(2993, 26, 61, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَلَمَّا تَرَآءَ   الۡجَمۡعٰنِ قَالَ اَصۡحٰبُ مُوۡسٰۤی  اِنَّا  لَمُدۡرَکُوۡنَ ﴿ۚ۶۱﴾', 'پھر جب دونوں جماعتیں آمنے سامنے ہوئیں تو موسٰی کے ساتھی کہنے لگے کہ ہم تو پکڑ لئے گئے۔', 'پھر جب مقابل ہوئیں دونوں فوجیں کہنے لگے موسٰی کے لوگ ہم تو پکڑے گئے [۴۶]', 'And when the two hosts saw each other, the companions of Moosa (Moses) said: \"We are sure to be overtaken.\"', 'And when the two hosts saw each other, the companions of Mūsā said, “Surely we are overtaken.”'),
(2994, 26, 62, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ  کَلَّا ۚ اِنَّ  مَعِیَ  رَبِّیۡ  سَیَہۡدِیۡنِ ﴿۶۲﴾', 'موسٰی نے کہا ہرگز نہیں میرا پروردگار میرے ساتھ ہے وہ مجھے رستہ بتائے گا۔', 'کہا ہرگز نہیں میرے ساتھ ہے میرا رب وہ مجھ کو راہ بتلائے گا [۴۷]', '(Moosa (Moses)) said: \"Nay, verily! With me is my Lord, He will guide me.\"', 'He said, “Never! Indeed with me is my Lord. He will guide me.”'),
(2995, 26, 63, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاَوۡحَیۡنَاۤ  اِلٰی مُوۡسٰۤی اَنِ اضۡرِبۡ بِّعَصَاکَ  الۡبَحۡرَ ؕ فَانۡفَلَقَ فَکَانَ کُلُّ فِرۡقٍ  کَالطَّوۡدِ  الۡعَظِیۡمِ ﴿ۚ۶۳﴾', 'اس وقت ہم نے موسٰی کی طرف وحی بھیجی کہ اپنی لاٹھی سمندر پر مارو۔ تو سمندر پھٹ گیا سو ہر ایک ٹکڑا یوں ہو گیا کہ گویا بڑا پہاڑ ہے۔', 'پھر حکم بھیجا ہم نے موسٰی کو کہ مار اپنے عصا سے دریا کو پھر دریا پھٹ گیا تو ہو گئ ہر پھانگ جیسے بڑا پہاڑ [۴۸]', 'Then We inspired Moosa (Moses) (saying): \"Strike the sea with your stick.\" And it parted, and each separate part (of that sea water) became like the huge, firm mass of a mountain.', 'So We revealed to Mūsā saying, “Strike the sea with your staff.” So it was severed apart, and each part became like a big mountain.'),
(2996, 26, 64, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اَزۡلَفۡنَا ثَمَّ   الۡاٰخَرِیۡنَ ﴿ۚ۶۴﴾', 'اور دوسروں یعنی فرعونیوں کو وہاں ہم نے قریب کر دیا۔', 'اور پاس پہنچا دیا ہم نے اسی جگہ دوسروں کو', 'Then We brought near the others (Firauns (Pharaoh) party) to that place.', 'Then We brought others close to that place.'),
(2997, 26, 65, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ اَنۡجَیۡنَا مُوۡسٰی وَ مَنۡ  مَّعَہٗۤ   اَجۡمَعِیۡنَ ﴿ۚ۶۵﴾', 'اور موسٰی اور انکے ساتھ والوں کو تو ہم نے بچا لیا۔', 'اور بچا دیا ہم نے موسٰی کو اور جو لوگ تھے اس کے ساتھ سب کو', 'And We saved Moosa (Moses) and all those with him.', 'And We saved Mūsā and all those with him.'),
(2998, 26, 66, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'ثُمَّ   اَغۡرَقۡنَا  الۡاٰخَرِیۡنَ ﴿ؕ۶۶﴾', 'پھر دوسروں کو ہم نے ڈبو دیا۔', 'پھر ڈبا دیا ہم نے ان دوسروں کو [۴۹]', 'Then We drowned the others.', 'Then we drowned the others.'),
(2999, 26, 67, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنَّ  فِیۡ  ذٰلِکَ لَاٰیَۃً ؕ وَ مَا کَانَ  اَکۡثَرُہُمۡ مُّؤۡمِنِیۡنَ ﴿۶۷﴾', 'بیشک اس قصے میں نشانی ہے۔ لیکن یہ اکثر ایمان لانے والے نہیں۔', 'اس چیز میں ایک نشانی ہے اور نہیں تھے بہت لوگ ان میں ماننے والے [۵۰]', 'Verily! In this is indeed a sign (or a proof), yet most of them are not believers.', 'Surely, in this there is a sign, but most of them are not believers,'),
(3000, 26, 68, 4, 8, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اِنَّ  رَبَّکَ لَہُوَ  الۡعَزِیۡزُ  الرَّحِیۡمُ ﴿٪۶۸﴾', 'اور تمہارا پروردگار تو غالب ہے مہربان ہے۔', 'اور تیرا رب وہی ہے زبردست رحم والا [۵۱]', 'And verily, your Lord! He is truly the All-Mighty, the Most Merciful.', 'and indeed your Lord is the Mighty, the Merciful.'),
(3001, 26, 69, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ اتۡلُ  عَلَیۡہِمۡ  نَبَاَ   اِبۡرٰہِیۡمَ ﴿ۘ۶۹﴾', 'اور انکو ابراہیم کا حال پڑھ کر سنا دو۔', 'اور سنا دے ان کو خبر ابراہیم کی', 'And recite to them the story of Ibrahim (Abraham).', 'And recite before them the narrative of Ibrāhīm,'),
(3002, 26, 70, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِذۡ قَالَ لِاَبِیۡہِ  وَ قَوۡمِہٖ مَا تَعۡبُدُوۡنَ ﴿۷۰﴾', 'جب انہوں نے اپنے باپ اور اپنی قوم کے لوگوں سے کہا کہ تم کس چیز کو پوجتے ہو؟', 'جب کہا اپنے باپ کو اور اس کی قوم کو تم کس کو پوجتے ہو [۵۲]', 'When he said to his father and his people: \"What do you worship?\"', 'when he said to his father and to his people, “What do you worship?”'),
(3003, 26, 71, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالُوۡا نَعۡبُدُ اَصۡنَامًا فَنَظَلُّ لَہَا عٰکِفِیۡنَ ﴿۷۱﴾', 'وہ کہنے لگے کہ ہم بتوں کو پوجتے ہیں اور انکی پوجا پر قائم ہیں۔', 'وہ بولے ہم پوجتے ہیں مورتوں کو پھر سارے دن انہی کے پاس لگے بیٹھے رہتے ہیں [۵۳]', 'They said: \"We worship idols, and to them we are ever devoted.\"', 'They said, “We worship idols, and stay devoted to them.”'),
(3004, 26, 72, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ ہَلۡ یَسۡمَعُوۡنَکُمۡ   اِذۡ   تَدۡعُوۡنَ ﴿ۙ۷۲﴾', 'ابراہیم نے کہا کہ جب تم انکو پکارتے ہو تو کیا یہ تمہاری آواز سنتے ہیں؟', 'کہا کچھ سنتے ہیں تمہارا کہا جب تم پکارتے ہو [۵۴]', 'He said: \"Do they hear you, when you call (on them)?', 'He said, “Do they listen to you when you call (them)'),
(3005, 26, 73, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اَوۡ  یَنۡفَعُوۡنَکُمۡ  اَوۡ  یَضُرُّوۡنَ ﴿۷۳﴾', 'یا تمہیں کچھ فائدہ دے سکتے یا نقصان پہنچا سکتے ہیں؟', 'یا کچھ بھلا کرتے ہیں تمہارا یا برا [۵۵]', '\"Or do they benefit you or do they harm (you)?\"', 'or do they bring benefit to you or harm?”'),
(3006, 26, 74, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالُوۡا بَلۡ وَجَدۡنَاۤ  اٰبَآءَنَا کَذٰلِکَ یَفۡعَلُوۡنَ ﴿۷۴﴾', 'انہوں نے کہا نہیں بلکہ ہم نے اپنے باپ دادا کو اسی طرح کرتے دیکھا ہے۔', 'بولے نہیں پر ہم نے پایا اپنے باپ دادوں کو یہی کام کرتے [۵۶]', 'They said: \"Nay, but we found our fathers doing so.\"', 'They said, “No, but we have found our fathers doing like this.”'),
(3007, 26, 75, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ اَفَرَءَیۡتُمۡ مَّا کُنۡتُمۡ تَعۡبُدُوۡنَ ﴿ۙ۷۵﴾', 'ابراہیم نے کہا کیا تم نے دیکھا کہ جنکو تم پوجتے رہے ہو۔', 'کہا بھلا دیکھتے ہو جن کو پوجتے رہے ہو', 'He said: \"Do you observe that which you have been worshipping,', 'He said, “Have you then ever considered what you have been worshipping,'),
(3008, 26, 76, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اَنۡتُمۡ  وَ  اٰبَآؤُکُمُ  الۡاَقۡدَمُوۡنَ ﴿۫ۖ۷۶﴾', 'تم بھی اور تمہارے اگلے باپ دادا بھی۔', 'تم اور تمہارے باپ دادے اگلے [۵۷]', '\"You and your ancient fathers?', 'you and your ancient fathers,'),
(3009, 26, 77, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاِنَّہُمۡ عَدُوٌّ  لِّیۡۤ   اِلَّا  رَبَّ  الۡعٰلَمِیۡنَ ﴿ۙ۷۷﴾', 'تو وہ میرے دشمن ہیں۔ مگر رب العالمین میرا دوست ہے۔', 'سو وہ میرے غنیم ہیں [۵۸] مگر جہان کا رب [۵۹]', '\"Verily! They are enemies to me, save the Lord of the Alameen (mankind, jinns and all that exists);', 'they all are an enemy to me, except the Lord of the worlds,'),
(3010, 26, 78, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'الَّذِیۡ خَلَقَنِیۡ فَہُوَ  یَہۡدِیۡنِ ﴿ۙ۷۸﴾', 'جس نے مجھے پیدا کیا ہے سو وہی مجھے رستہ دکھاتا ہے۔', 'جس نے مجھ کو بنایا سو وہی مجھ کو راہ دکھلاتا ہے [۶۰]', '\"Who has created me, and it is He Who guides me;', 'who created me, and who guides me,'),
(3011, 26, 79, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ الَّذِیۡ ہُوَ  یُطۡعِمُنِیۡ وَ  یَسۡقِیۡنِ ﴿ۙ۷۹﴾', 'اور وہ جو مجھے کھلاتا اور پلاتا ہے۔', 'اور وہ جو مجھ کو کھلاتا ہے اور پلاتا ہے', '\"And it is He Who feeds me and gives me to drink.', 'and Who feeds me and gives me drink,'),
(3012, 26, 80, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اِذَا  مَرِضۡتُ  فَہُوَ  یَشۡفِیۡنِ ﴿۪ۙ۸۰﴾', 'اور جب میں بیمار پڑتا ہوں تو مجھے شفا بخشتا ہے۔', 'اور جب میں بیمار ہوں تو وہی شفا دیتا ہے', '\"And when I am ill, it is He who cures me;', 'and when I become sick, He heals me,'),
(3013, 26, 81, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ الَّذِیۡ  یُمِیۡتُنِیۡ ثُمَّ   یُحۡیِیۡنِ ﴿ۙ۸۱﴾', 'اور وہ جو مجھے موت دے گا اور پھر زندہ کرے گا۔', 'اور ہ جو مجھ کو مارے گا پھر جلائے گا [۶۱]', '\"And Who will cause me to die, and then will bring me to life (again);', 'and who will make me die, then will give me life,'),
(3014, 26, 82, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ الَّذِیۡۤ  اَطۡمَعُ اَنۡ یَّغۡفِرَ لِیۡ خَطِیۡٓئَتِیۡ یَوۡمَ  الدِّیۡنِ ﴿ؕ۸۲﴾', 'اور وہ جس سے میں امید رکھتا ہوں کہ قیامت کے دن میرا قصور بخشے گا۔', 'اور وہ جو مجھ کو توقع ہے کہ بخشے میری تقصیر انصاف کے دن [۶۲]', '\"And Who, I hope will forgive me my faults on the Day of Recompense, (the Day of Resurrection),\"', 'and who, I hope, will forgive my fault on the Day of Retribution.'),
(3015, 26, 83, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'رَبِّ ہَبۡ لِیۡ حُکۡمًا وَّ اَلۡحِقۡنِیۡ بِالصّٰلِحِیۡنَ ﴿ۙ۸۳﴾', 'اے پروردگار مجھے علم و دانش عطا فرما اور نیکوکاروں میں شامل فرما۔', 'اے میرے رب دے مجھ کو حکم اور ملا مجھ کو نیکوں میں [۶۳]', 'My Lord! Bestow Hukman (religious knowledge, right judgement of the affairs and Prophethood) on me, and join me with the righteous;', 'O my Lord, give me wisdom, and make me join the righteous,'),
(3016, 26, 84, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ اجۡعَلۡ لِّیۡ  لِسَانَ صِدۡقٍ فِی الۡاٰخِرِیۡنَ ﴿ۙ۸۴﴾', 'اور بعد والے لوگوں میں میرا ذکر نیک باقی رکھیو۔', 'اور رکھ میرا بول سچا پچھلوں میں [۶۴]', 'And grant me an honourable mention in later generations;', 'and destine for me a truthful description among the next generations,'),
(3017, 26, 85, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ اجۡعَلۡنِیۡ  مِنۡ وَّرَثَۃِ  جَنَّۃِ النَّعِیۡمِ ﴿ۙ۸۵﴾', 'اور مجھے نعمت کی بہشت کے وارثوں میں شامل کیجیو۔', 'اور کر مجھ کو وارثوں میں نعمت کے باغ کے [۶۵]', 'And make me one of the inheritors of the Paradise of Delight;', 'and make me among those who will inherit the Garden of Bliss,'),
(3018, 26, 86, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ اغۡفِرۡ  لِاَبِیۡۤ  اِنَّہٗ کَانَ مِنَ الضَّآلِّیۡنَ ﴿ۙ۸۶﴾', 'اور میرے باپ کو بخش دے کہ وہ گمراہوں میں سے ہے۔', 'اور معاف کر میرے باپ کو وہ تھا راہ بھولے ہوؤں میں [۶۶]', 'And forgive my father, verily he is of the erring;', 'and forgive my father. Indeed he was one of those who went astray,'),
(3019, 26, 87, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ لَا  تُخۡزِنِیۡ  یَوۡمَ  یُبۡعَثُوۡنَ ﴿ۙ۸۷﴾', 'اور جس دن لوگ اٹھا کھڑے کئے جائیں گے مجھے رسوا نہ کیجیو۔', 'اور رسوا نہ کر مجھ کو کہ جس دن سب جی کر اٹھیں گے', 'And disgrace me not on the Day when (all the creatures) will be resurrected;', 'and do not put me to disgrace on the Day when all will be raised to life,'),
(3020, 26, 88, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'یَوۡمَ لَا  یَنۡفَعُ  مَالٌ  وَّ  لَا  بَنُوۡنَ ﴿ۙ۸۸﴾', 'جس دن نہ مال ہی کچھ فائدہ دے سکے گا اور نہ بیٹے۔', 'جس دن نہ کام آئے کوئی مال اور نہ بیٹے', 'The Day whereon neither wealth nor sons will avail,', 'the Day when neither wealth will be of any use (to any one) nor sons,'),
(3021, 26, 89, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِلَّا  مَنۡ  اَتَی اللّٰہَ  بِقَلۡبٍ سَلِیۡمٍ ﴿ؕ۸۹﴾', 'ہاں جو شخص اللہ کے پاس بے روگ دل لے کر آیا وہ بچ جائے گا۔', 'مگر جو کوئی آیا اللہ کے پاس لیکر دل چنگا [۶۷]', 'Except him who brings to Allah a clean heart (clean from Shirk (polytheism) and Nifaq (hypocrisy)).', 'except to him who will come to Allah with a sound heart,'),
(3022, 26, 90, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ اُزۡلِفَتِ  الۡجَنَّۃُ   لِلۡمُتَّقِیۡنَ ﴿ۙ۹۰﴾', 'اور بہشت پرہیزگاروں کے قریب کر دی جائے گی۔', 'اور پاس لائیں بہشت کو واسطے ڈر والوں کے', 'And Paradise will be brought near to the Muttaqoon (pious - see V.2:2).', 'and the Paradise will be brought near to the God-fearing'),
(3023, 26, 91, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  بُرِّزَتِ الۡجَحِیۡمُ  لِلۡغٰوِیۡنَ ﴿ۙ۹۱﴾', 'اور دوزخ گمراہوں کے سامنے لائی جائے گی۔', 'اور نکالیں دوزخ کو سامنے بے را ہوں کے [۶۸]', 'And the (Hell) Fire will be placed in full view of the erring.', 'and the Hell will be fully uncovered for the perverse,'),
(3024, 26, 92, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  قِیۡلَ  لَہُمۡ اَیۡنَمَا کُنۡتُمۡ تَعۡبُدُوۡنَ ﴿ۙ۹۲﴾', 'اور ان سے کہا جائے گا کہ جنکو تم پوجتے تھے وہ کہاں ہیں؟', 'اور کہیں ان کو کہاں ہیں جن کو تم پوجتے تھے', 'And it will be said to them: \"Where are those (the false gods whom you used to set up as rivals with Allah) that you used to worship', 'and it will be said to them, ‘Where is that which you used to worship'),
(3025, 26, 93, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'مِنۡ دُوۡنِ اللّٰہِ ؕ ہَلۡ یَنۡصُرُوۡنَکُمۡ  اَوۡ یَنۡتَصِرُوۡنَ ﴿ؕ۹۳﴾', 'یعنی جنکو اللہ کے سوا پوجتے تھے کیا وہ تمہاری مدد کر سکتے ہیں یا خود بدلہ لے سکتے ہیں؟', 'اللہ کے سوائے کیا کچھ مدد کرتے ہیں تمہاری یا بدلہ لے سکتے ہیں [۶۹]', '\"Instead of Allah? Can they help you or (even) help themselves?\"', 'beside Allah? Can they help you or help themselves?’'),
(3026, 26, 94, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَکُبۡکِبُوۡا فِیۡہَا  ہُمۡ  وَ الۡغَاوٗنَ ﴿ۙ۹۴﴾', 'تو وہ خود اور گمراہ یعنی بت اور بت پرست اوندھے منہ دوزخ میں ڈال دیئے جائیں گے۔', 'پھر اوندھے ڈالیں  اس میں انکو  اور سب بے راہوں کو', 'Then they will be thrown on their faces into the (Fire), They and the Ghawoon (devils, and those who were in error).', 'So they (their false gods) will be thrown on their faces into it - they and the erring people'),
(3027, 26, 95, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  جُنُوۡدُ   اِبۡلِیۡسَ  اَجۡمَعُوۡنَ ﴿ؕ۹۵﴾', 'اور شیطان کے لشکر سب کے سب داخل جہنم ہوں گے۔', 'اور ابلیس کے لشکر کو سبہوں کو', 'And the whole hosts of Iblees (Satan) together.', 'and the entire army of Iblīs (Satan), all together.'),
(3028, 26, 96, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالُوۡا  وَ ہُمۡ  فِیۡہَا یَخۡتَصِمُوۡنَ ﴿ۙ۹۶﴾', 'وہاں وہ آپس میں جھگڑیں گے اور کہیں گے۔', 'کہیں گے جب وہ وہاں باہم جھگڑنے لگیں', 'They will say while contending therein,', 'They will say when they will be quarreling there with each other,'),
(3029, 26, 97, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'تَاللّٰہِ   اِنۡ  کُنَّا لَفِیۡ ضَلٰلٍ مُّبِیۡنٍ ﴿ۙ۹۷﴾', 'کہ اللہ کی قسم ہم تو کھلی گمراہی میں تھے۔', 'قسم اللہ کی ہم تھے صریح غلطی میں', 'By Allah, we were truly in a manifest error,', '‘By Allah, we were in open error'),
(3030, 26, 98, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِذۡ  نُسَوِّیۡکُمۡ  بِرَبِّ الۡعٰلَمِیۡنَ ﴿۹۸﴾', 'جب کہ ہم تمہیں رب العمالمین کے برابر ٹھہراتے تھے۔', 'جب ہم تم کو برابر کرتے تھے پروردگار عالم کے', 'When We held you (false gods) as equals (in worship) with the Lord of the Alameen (mankind, jinns and all that exists);', 'when we used to equate you with the Lord of the worlds,'),
(3031, 26, 99, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ مَاۤ   اَضَلَّنَاۤ  اِلَّا  الۡمُجۡرِمُوۡنَ ﴿۹۹﴾', 'اور ہم کو ان گناہگاروں ہی نے گمراہ کیا تھا۔', 'اور ہم کو راہ سے بہکایا سو ان گنہگاروں نے', 'And none has brought us into error except the Mujrimoon (Iblees (Satan) and those of human beings who commit crimes, murderers, polytheists, oppressors, etc.).', 'and it is only the sinners who misguided us.'),
(3032, 26, 100, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَمَا  لَنَا مِنۡ شَافِعِیۡنَ ﴿۱۰۰﴾ۙ', 'تو آج نہ کوئی ہمارے لئے سفارش کرنے والا ہے۔', 'پھر کوئی نہیں ہماری سفارش کرنے والے', 'Now we have no intercessors,', 'Now we have neither any intercessors'),
(3033, 26, 101, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ لَا صَدِیۡقٍ حَمِیۡمٍ ﴿۱۰۱﴾', 'اور نہ کوئی گرم جوش دوست۔', 'اور نہ کوئی دوست محبت کرنے والا [۷۰]', 'Nor a close friend (to help us).', 'nor any true friend.'),
(3034, 26, 102, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَلَوۡ اَنَّ  لَنَا کَرَّۃً  فَنَکُوۡنَ مِنَ الۡمُؤۡمِنِیۡنَ ﴿۱۰۲﴾', 'تو کاش ہمیں دنیا میں دوبارہ جانا ہو تو ہم مومنوں میں ہو جائیں۔', 'سو کسی طرح ہم کو پھر جانا ملے تو ہم ہوں ایمان والوں میں [۷۱]', '(Alas!) If we only had a chance to return (to the world), we shall truly be among the believers!', 'Would that we have a chance to return whereby we may join the believers!’”'),
(3035, 26, 103, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنَّ فِیۡ  ذٰلِکَ لَاٰیَۃً ؕ وَ مَا  کَانَ  اَکۡثَرُہُمۡ مُّؤۡمِنِیۡنَ ﴿۱۰۳﴾', 'بیشک اس میں نشانی ہے اور ان میں اکثر ایمان لانے والے نہیں۔', 'اس بات میں نشانی ہے اور بہت لوگ ان میں نہیں ماننے والے [۷۲]', 'Verily! In this is indeed a sign, yet most of them are not believers.', 'Surely, in this there is a sign, but most of them are not believers,'),
(3036, 26, 104, 5, 9, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اِنَّ  رَبَّکَ  لَہُوَ  الۡعَزِیۡزُ  الرَّحِیۡمُ ﴿۱۰۴﴾٪', 'اور تمہارا پروردگار تو غالب ہے مہربان ہے۔', 'اور تیرا رب وہی ہے زبردست رحم والا', 'And verily, your Lord! He is truly the All-Mighty, the Most Merciful.', 'and indeed your Lord is the Mighty, the Merciful.'),
(3037, 26, 105, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'کَذَّبَتۡ  قَوۡمُ  نُوۡحِۣ الۡمُرۡسَلِیۡنَ ﴿۱۰۵﴾ۚۖ', 'قوم نوح نے بھی پیغمبروں کو جھٹلایا۔', 'جھٹلایا نوح کی قوم نے پیغام لانے والوں کو', 'The people of Nooh (Noah) belied the Messengers.', 'The people of NūH rejected the messengers'),
(3038, 26, 106, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِذۡ قَالَ لَہُمۡ اَخُوۡہُمۡ نُوۡحٌ اَلَا تَتَّقُوۡنَ ﴿۱۰۶﴾ۚ', 'جب ان سے ان کے بھائی نوح نے کہا کہ تم ڈرتے کیوں نہیں۔', 'جب کہا ان کو ان کے بھائی نوح نے کیا تم کو ڈر نہیں', 'When their brother Nooh (Noah) said to them: \"Will you not fear Allah and obey Him?', 'when their brother NūH said to them, “Do you not fear Allah?'),
(3039, 26, 107, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنِّیۡ   لَکُمۡ  رَسُوۡلٌ اَمِیۡنٌ ﴿۱۰۷﴾ۙ', 'میں تو تمہارا امانت دار پیغمبر ہوں۔', 'میں تمہارے واسطے پیغام لانے والا ہوں', '\"I am a trustworthy Messenger to you.', 'I am an honest messenger for you.'),
(3040, 26, 108, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاتَّقُوا اللّٰہَ  وَ اَطِیۡعُوۡنِ ﴿۱۰۸﴾ۚ', 'تو اللہ سے ڈرو اور میرا کہا مانو۔', 'معتبر سو ڈرو اللہ سے اور میرا کہا مانو [۷۳]', '\"So fear Allah, keep your duty to Him, and obey me.', 'So, fear Allah and obey me.'),
(3041, 26, 109, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ مَاۤ  اَسۡـَٔلُکُمۡ  عَلَیۡہِ مِنۡ اَجۡرٍ ۚ اِنۡ اَجۡرِیَ   اِلَّا  عَلٰی رَبِّ  الۡعٰلَمِیۡنَ ﴿۱۰۹﴾ۚ', 'اور میں اس کام کا تم سے کوئی صلہ نہیں مانگتا میرا صلہ تو رب العالمین کے ذمے ہے۔', 'اور مانگتا نہیں میں تم سے اس پر کچھ بدلہ میرا بدلہ ہے اسی پروردگار عالم پر', '\"No reward do I ask of you for it (my Message of Islamic Monotheism), my reward is only from the Lord of the Alameen (mankind, jinns and all that exists).', 'I do not claim from you any reward for it. My reward is with none but with the Lord of the worlds;'),
(3042, 26, 110, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاتَّقُوا  اللّٰہَ   وَ اَطِیۡعُوۡنِ ﴿۱۱۰﴾ؕ', 'تو اللہ سے ڈرو اور میرے کہنے پر چلو۔', 'سو ڈرو اللہ سے اور میرا کہا مانو [۷۴]', '\"So keep your duty to Allah, fear Him and obey me.\"', 'so, fear Allah and obey me.”'),
(3043, 26, 111, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالُوۡۤا اَنُؤۡمِنُ لَکَ وَ اتَّبَعَکَ الۡاَرۡذَلُوۡنَ ﴿۱۱۱﴾ؕ', 'وہ بولے کہ کیا ہم تمکو مان لیں جبکہ تمہارے پیرو تو رذیل ترین لوگ ہوئے ہیں۔', 'بولے کیا ہم تجھ کو مان لیں اور تیرے ساتھ ہو رہے ہیں کمینے [۷۵]', 'They said: \"Shall we believe in you, when the meanest (of the people) follow you?\"', 'They said, “Shall we believe in you while you are followed by the lowest people?”'),
(3044, 26, 112, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ وَ مَا عِلۡمِیۡ بِمَا کَانُوۡا یَعۡمَلُوۡنَ ﴿۱۱۲﴾ۚ', 'نوح نے کہا مجھے کیا معلوم کہ وہ کیا کرتے ہیں۔', 'کہا مجھ کو کیا جاننا ہے اس کو جو کام وہ کر رہے ہیں', 'He said: \"And what knowledge have I of what they used to do?', 'He said, “I do not know about what they do;'),
(3045, 26, 113, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنۡ حِسَابُہُمۡ  اِلَّا عَلٰی رَبِّیۡ لَوۡ  تَشۡعُرُوۡنَ ﴿۱۱۳﴾ۚ', 'ان کا حساب اعمال میرے پروردگار کے ذمے ہے کاش تم سمجھو۔', 'ان کا حساب پوچھنا میرے رب کا ہی کام ہے اگر تم سمجھ رکھتے ہو', '\"Their account is only with my Lord, if you could (but) know.', 'their account is with none but with my Lord, if you have sense.'),
(3046, 26, 114, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ مَاۤ   اَنَا بِطَارِدِ  الۡمُؤۡمِنِیۡنَ ﴿۱۱۴﴾ۚ', 'اور میں مومنوں کو نکال دینے والا نہیں ہوں۔', 'اور میں ہانکنے والا نہیں ایمان لانے والوں کو [۷۶]', '\"And I am not going to drive away the believers.', 'And I am not the one who would drive the believers away;'),
(3047, 26, 115, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنۡ  اَنَا  اِلَّا  نَذِیۡرٌ  مُّبِیۡنٌ ﴿۱۱۵﴾ؕ', 'میں تو فقط صاف صاف خبردار کرنے والا ہوں۔', 'میں تو بس یہی ڈر سنا دینے والا ہوں کھول کر [۷۷]', 'I am only a plain warner.\"', 'I am no more than a plain warner.”'),
(3048, 26, 116, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالُوۡا لَئِنۡ لَّمۡ تَنۡتَہِ یٰنُوۡحُ لَتَکُوۡنَنَّ مِنَ  الۡمَرۡجُوۡمِیۡنَ ﴿۱۱۶﴾ؕ', 'انہوں نے کہا کہ نوح اگر تم باز نہ آؤ گے تو سنگسار کر دیئے جاؤ گے۔', 'بولے اگر تو نہ چھوڑے گا اے نوح تو ضرور سنگسار کر دیا جائے گا [۷۸]', 'They said: \"If you cease not, O Nooh (Noah)! You will surely be among those stoned (to death).\"', 'They said, “Should you not stop, O NūH, you will surely be stoned.”'),
(3049, 26, 117, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ رَبِّ  اِنَّ   قَوۡمِیۡ  کَذَّبُوۡنِ ﴿۱۱۷﴾ۚۖ', 'نوح نے کہا کہ پروردگار میری قوم نے تو مجھے جھٹلا دیا۔', 'کہا اے رب میری قوم نے تو مجھکو جھٹلا دیا', 'He said: \"My Lord! Verily, my people have belied me.', 'He said, “My Lord, my people have rejected me.'),
(3050, 26, 118, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَافۡتَحۡ  بَیۡنِیۡ وَ بَیۡنَہُمۡ فَتۡحًا وَّ نَجِّنِیۡ وَ مَنۡ  مَّعِیَ مِنَ الۡمُؤۡمِنِیۡنَ ﴿۱۱۸﴾', 'سو تو میرے اور انکے درمیان ایک کھلا فیصلہ کر دے اور مجھے اور جو مومن میرے ساتھ ہیں انکو بچا لے۔', 'سو فیصلہ کر  دے میرے انکے بیچ میں کسی طرح کا فیصلہ [۷۹] اور بچا لے میرے ساتھ ہیں ایمان والے [۸۰]', 'Therefore judge You between me and them, and save me and those of the believers who are with me.\"', 'So judge between me and them with an open verdict, and save me and all the believers who are with me.”'),
(3051, 26, 119, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاَنۡجَیۡنٰہُ وَ مَنۡ مَّعَہٗ  فِی الۡفُلۡکِ الۡمَشۡحُوۡنِ ﴿۱۱۹﴾ۚ', 'پس ہم نے انکو اور جو انکے ساتھ بھری ہوئی کشتی میں سوار تھے انکو بچا لیا۔', 'پھر بچا دیا ہم نے اسکو اور جو اس کےساتھ تھے اس لدی ہوئی کشتی میں', 'And We saved him and those with him in the laden ship.', 'So We saved him and those with him in the Ark that was fully occupied.'),
(3052, 26, 120, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'ثُمَّ   اَغۡرَقۡنَا بَعۡدُ الۡبٰقِیۡنَ ﴿۱۲۰﴾ؕ', 'پھر اسکے بعد ہم نے باقی لوگوں کو ڈبو دیا۔', 'پھر ڈبا دیا ہم نے اس کے پیچھے ان باقی رہے ہوؤں کو [۸۱]', 'Then We drowned the rest (disbelievers) thereafter.', 'Then We drowned, after that, all the remaining.'),
(3053, 26, 121, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنَّ فِیۡ ذٰلِکَ لَاٰیَۃً ؕ وَ مَا کَانَ  اَکۡثَرُہُمۡ مُّؤۡمِنِیۡنَ ﴿۱۲۱﴾', 'بیشک اس میں نشانی ہے اور ان میں اکثر ایمان لانے والے نہیں تھے۔', 'البتہ اس بات میں نشانی ہے اور ان میں بہت لوگ نہیں ہیں ماننے والے', 'Verily, in this is indeed a sign, yet most of them are not believers.', 'Surely, in this there is a sign, but most of them are not believers'),
(3054, 26, 122, 6, 10, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اِنَّ  رَبَّکَ  لَہُوَ الۡعَزِیۡزُ  الرَّحِیۡمُ ﴿۱۲۲﴾٪', 'اور تمہارا پروردگار تو غالب ہے مہربان ہے۔', 'اور تیرا رب وہی ہے زبردست رحم  والا', 'And verily! Your Lord, He is indeed the All-Mighty, the Most Merciful.', 'and indeed your Lord is the Mighty, the Very-Merciful.'),
(3055, 26, 123, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'کَذَّبَتۡ  عَادُۨ    الۡمُرۡسَلِیۡنَ ﴿۱۲۳﴾ۚۖ', 'قوم عاد نے بھی پیغمبروں کو جھٹلایا۔', 'جھٹلایا عاد نے پیغام لانے والوں کو', 'Ad (people) belied the Messengers.', 'The (people of) ‘Ād rejected the messengers'),
(3056, 26, 124, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِذۡ  قَالَ لَہُمۡ  اَخُوۡہُمۡ ہُوۡدٌ  اَلَا تَتَّقُوۡنَ ﴿۱۲۴﴾ۚ', 'جب ان سے انکے بھائی ہود نے کہا کیا تم ڈرتے نہیں؟', 'جب کہا ان کو ان کےبھائی ہود نے کیا تم کو ڈر نہیں', 'When their brother Hood said to them: \"Will you not fear Allah and obey Him?', 'when their brother Hūd said to them, “Do you not fear Allah?'),
(3057, 26, 125, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنِّیۡ  لَکُمۡ  رَسُوۡلٌ  اَمِیۡنٌ ﴿۱۲۵﴾ۙ', 'میں تو تمہارا امانت دار پیغمبر ہوں۔', 'میں تمہارے پاس پیغام لانے والا معتبر ہوں', '\"Verily! I am a trustworthy Messenger to you.', 'I am an honest messenger for you,'),
(3058, 26, 126, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاتَّقُوا  اللّٰہَ  وَ  اَطِیۡعُوۡنِ ﴿۱۲۶﴾ۚ', 'تو اللہ سے ڈرو اور میرا کہا مانو۔', 'سو ڈرو اللہ سے اور میرا کہا مانو', '\"So fear Allah, keep your duty to Him, and obey me.', 'so fear Allah and obey me.'),
(3059, 26, 127, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ مَاۤ  اَسۡـَٔلُکُمۡ عَلَیۡہِ  مِنۡ اَجۡرٍ ۚ اِنۡ اَجۡرِیَ   اِلَّا  عَلٰی  رَبِّ  الۡعٰلَمِیۡنَ ﴿۱۲۷﴾ؕ', 'اور میں اس کا تم سے کچھ بدلہ نہیں مانگتا میرا بدلہ رب العالمین کے ذمے ہے۔', 'اور نہیں مانگتا میں تم سے اس پر کچھ بدلہ میرا بدلہ ہے اسی جہان کےمالک پر', '\"No reward do I ask of you for it (my Message of Islamic Monotheism), my reward is only from the Lord of the Alameen (mankind, jinns, and all that exists).', 'I do not claim from you any reward for it. My reward is with none but with the Lord of the worlds.'),
(3060, 26, 128, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اَتَبۡنُوۡنَ بِکُلِّ رِیۡعٍ  اٰیَۃً  تَعۡبَثُوۡنَ ﴿۱۲۸﴾', 'بھلا تم ہر اونچی جگہ پر فضول نشان تعمیر کرتے ہو۔', 'کیا بناتے ہو ہر اونچی زمین پر ایک نشان کھیلنے کو', '\"Do you build high palaces on every high place, while you do not live in them?', 'Do you erect on every height a monument, having no sound purpose,'),
(3061, 26, 129, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ تَتَّخِذُوۡنَ مَصَانِعَ لَعَلَّکُمۡ تَخۡلُدُوۡنَ ﴿۱۲۹﴾ۚ', 'اور محل بناتے ہو کہ شاید تم ہمیشہ رہو گے۔', 'اور بناتے ہو کاریگریاں شاید تم ہمیشہ رہو گے [۸۲]', '\"And do you get for yourselves palaces (fine buildings) as if you will live therein for ever.', 'and take the objects of architecture as if you are going to live forever,'),
(3062, 26, 130, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اِذَا  بَطَشۡتُمۡ  بَطَشۡتُمۡ  جَبَّارِیۡنَ ﴿۱۳۰﴾ۚ', 'اور جب کسی کو پکڑتے ہو تو جابرانہ پکڑتے ہو۔', 'اور جب ہاتھ ڈالتے ہو تو پنجہ مارتے ہو ظلم سے', '\"And when you seize, seize you as tyrants?', 'and when you seize (someone) you seize as tyrants?'),
(3063, 26, 131, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاتَّقُوا اللّٰہَ  وَ  اَطِیۡعُوۡنِ ﴿۱۳۱﴾ۚ', 'تو اللہ سے ڈرو اور میری اطاعت کرو۔', 'سو ڈرو  اللہ سے اور میرا کہا مانو [۸۳]', '\"So fear Allah, keep your duty to Him, and obey me.', 'So fear Allah and obey me.'),
(3064, 26, 132, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ اتَّقُوا الَّذِیۡۤ  اَمَدَّکُمۡ بِمَا تَعۡلَمُوۡنَ ﴿۱۳۲﴾ۚ', 'اور اس سے ڈرو جس نے تمکو ان چیزوں سے مدد دی جنکو تم جانتے ہو۔', 'اور ڈرو اس سے جس نے تم کو پہنچائیں وہ چیزیں جو تم جانتے ہو', '\"And keep your duty to Him, fear Him Who has aided you with all (good things) that you know.', 'And fear the One who has supported you with what you know.'),
(3065, 26, 133, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اَمَدَّکُمۡ   بِاَنۡعَامٍ  وَّ  بَنِیۡنَ ﴿۱۳۳﴾ۚۙ', 'اس نے تمہیں مویشیوں اور بیٹوں سے مدد دی۔', 'پہنچائے تم کو چوپائے اور بیٹے', '\"He has aided you with cattle and children.', 'He has supported you with cattle and sons,'),
(3066, 26, 134, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  جَنّٰتٍ  وَّ  عُیُوۡنٍ ﴿۱۳۴﴾ۚ', 'اور باغوں اور چشموں سے۔', 'اور باغ اور چشمے', '\"And gardens and springs.', 'and with gardens and springs.'),
(3067, 26, 135, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنِّیۡۤ  اَخَافُ عَلَیۡکُمۡ عَذَابَ یَوۡمٍ عَظِیۡمٍ ﴿۱۳۵﴾ؕ', 'مجھکو تمہارے بارے میں بڑے سخت دن کے عذاب کا خوف ہے۔', 'میں ڈرتا ہوں تم پر ایک بڑے دن کی آفت سے [۸۴]', '\"Verily, I fear for you the torment of a Great Day.\"', 'In fact I fear for you the punishment of a horrible day.”'),
(3068, 26, 136, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالُوۡا سَوَآءٌ  عَلَیۡنَاۤ  اَوَ عَظۡتَ اَمۡ  لَمۡ تَکُنۡ   مِّنَ  الۡوٰعِظِیۡنَ ﴿۱۳۶﴾ۙ', 'وہ کہنے لگے تم ہمیں خواہ نصیحت کرو یا نہ کرو ہمارے لئے یکساں ہے۔', 'بولے ہم کو برابر ہے تو نصیحت کرے یا نہ بنے تو نصیحت کرنے والا', 'They said: \"It is the same to us whether you preach or be not of those who preach.', 'They said, “It is all equal for us, whether you give us advice or you do not become one of the advisors.'),
(3069, 26, 137, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنۡ  ہٰذَاۤ   اِلَّا  خُلُقُ  الۡاَوَّلِیۡنَ ﴿۱۳۷﴾ۙ', 'یہ تو اگلوں ہی کی عادت ہے۔', 'اور کچھ نہیں یہ باتیں عادت ہے اگلے لوگوں کی', '\"This is no other than the false-tales and religion of the ancients, (Tafsir At-Tabaree, Vol.19, Page 97)', 'This is nothing but the practice of the ancient,'),
(3070, 26, 138, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ مَا نَحۡنُ  بِمُعَذَّبِیۡنَ ﴿۱۳۸﴾ۚ', 'اور ہم پر کوئی عذاب نہیں آئے گا۔', 'اور ہم پر آفت نہیں آنے والی [۸۵]', '\"And we are not going to be punished.\"', 'and we are not going to be punished.”'),
(3071, 26, 139, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَکَذَّبُوۡہُ  فَاَہۡلَکۡنٰہُمۡ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیَۃً ؕ وَ مَا کَانَ اَکۡثَرُہُمۡ مُّؤۡمِنِیۡنَ ﴿۱۳۹﴾', 'تو انہوں نے ہود کو جھٹلایا سو ہم نے انکو ہلاک کر ڈالا۔ بیشک اس میں نشانی ہے۔ اور ان میں اکثر ایمان لانے والے نہیں تھے۔', 'پھر اسکو جھٹلانے لگے تو ہم نے انکو غارت کر دیا [۸۶] اس بات میں البتہ نشانی ہے اور ان میں بہت لوگ نہیں ماننے والے', 'So they belied him, and We destroyed them. Verily! In this is indeed a sign, yet most of them are not believers.', 'Thus they rejected him, so We destroyed them. Surely, in this there is a sign, but most of them are not believers,'),
(3072, 26, 140, 7, 11, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اِنَّ  رَبَّکَ  لَہُوَ  الۡعَزِیۡزُ  الرَّحِیۡمُ ﴿۱۴۰﴾٪', 'اور تمہارا پروردگار تو غالب ہے مہربان ہے۔', 'اور تیرا رب وہی ہے زبردست رحم  والا', 'And verily! Your Lord, He is indeed the All-Mighty, the Most Merciful.', 'and indeed your Lord is the Mighty, the Merciful.'),
(3073, 26, 141, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'کَذَّبَتۡ ثَمُوۡدُ  الۡمُرۡسَلِیۡنَ ﴿۱۴۱﴾ۚۖ', 'قوم ثمود نے بھی پیغمبروں کو جھٹلایا۔', 'جھٹلایا ثمود نے پیغام لانے والوں کو', 'Thamood (people) belied the Messenger.', 'The (people of) Thamūd rejected the messengers'),
(3074, 26, 142, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِذۡ قَالَ لَہُمۡ اَخُوۡہُمۡ صٰلِحٌ  اَلَا تَتَّقُوۡنَ ﴿۱۴۲﴾ۚ', 'جب ان سے انکے بھائی صالح نے کہا کہ تم ڈرتے کیوں نہیں؟', 'جب کہا ان کو انکے بھائی صالح نے کیا تم ڈرتے نہیں', 'When their brother Salih (Saleh) said to them: \"Will you not fear Allah and obey Him?', 'when their brother SāliH said to them, “Do you not fear Allah?'),
(3075, 26, 143, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنِّیۡ   لَکُمۡ  رَسُوۡلٌ اَمِیۡنٌ ﴿۱۴۳﴾ۙ', 'میں تو تمہارا امانت دار پیغمبر ہوں۔', 'میں تمہارے پاس پیغام لانے والا ہوں معتبر', '\"I am a trustworthy Messenger to you.', 'I am an honest messenger for you.'),
(3076, 26, 144, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاتَّقُوا اللّٰہَ  وَ اَطِیۡعُوۡنِ ﴿۱۴۴﴾ۚ', 'تو اللہ سے ڈرو اور میرا کہا مانو۔', 'سو ڈرو اللہ سے اور میرا کہا مانو', '\"So fear Allah, keep your duty to Him, and obey me.', 'So, fear Allah and obey me.'),
(3077, 26, 145, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ مَاۤ  اَسۡـَٔلُکُمۡ عَلَیۡہِ مِنۡ اَجۡرٍ ۚ اِنۡ اَجۡرِیَ   اِلَّا عَلٰی  رَبِّ  الۡعٰلَمِیۡنَ ﴿۱۴۵﴾ؕ', 'اور میں اس کا تم سے بدلہ نہیں مانگتا۔ میرا بدلہ رب العالمین کے ذمے ہے۔', 'اور نہیں مانگتا میں تم سے اس پر کچھ بدلہ میرا بدلہ ہے اسی جہان کے پالنے والے پر', '\"No reward do I ask of you for it (my Message of Islamic Monotheism), my reward is only from the Lord of the Alameen (mankind, jinns and all that exists).', 'I do not claim from you any reward for it. My reward is with none but with the Lord of the worlds.'),
(3078, 26, 146, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اَتُتۡرَکُوۡنَ  فِیۡ  مَا ہٰہُنَاۤ  اٰمِنِیۡنَ ﴿۱۴۶﴾ۙ', 'کیا جو چیزیں تمہیں یہاں میسر ہیں ان میں تم یوں ہی بے خوف چھوڑ دیئے جاؤ گے؟', 'کیا چھوڑے رکھیں گے تم کو یہاں کی چیزوں میں بے کھٹکے', '\"Will you be left secure in that which you have here?', 'Will you be left secure in whatever is here,'),
(3079, 26, 147, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فِیۡ  جَنّٰتٍ  وَّ عُیُوۡنٍ ﴿۱۴۷﴾ۙ', 'یعنی باغ اور چشمے۔', 'باغوں میں اور چشموں میں', '\"In gardens and springs.', 'in gardens and springs,'),
(3080, 26, 148, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَّ  زُرُوۡعٍ  وَّ  نَخۡلٍ طَلۡعُہَا ہَضِیۡمٌ ﴿۱۴۸﴾ۚ', 'اور کھیتاں اور کھجوریں جنکے خوشے لطیف و نازک ہوتے ہیں۔', 'اور کھیتوں میں اور کھجوروں میں جن کا گابھا ملائم ہے', 'And green crops (fields etc.) and date-palms with soft spadix.', 'and in farms and date-palms, the spathes of which are interwoven?'),
(3081, 26, 149, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ تَنۡحِتُوۡنَ مِنَ الۡجِبَالِ بُیُوۡتًا فٰرِہِیۡنَ ﴿۱۴۹﴾ۚ', 'اور  پہاڑوں میں تراش تراش کر پر تکلف گھر بناتے ہو۔', 'اور تراشتے ہو پہاڑوں کے گھر تکلف کے', '\"And you carve houses out of mountains with great skill.', 'You hew out houses from the hills with pride.'),
(3082, 26, 150, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاتَّقُوا اللّٰہَ  وَ اَطِیۡعُوۡنِ ﴿۱۵۰﴾ۚ', 'تو اللہ سے ڈرو اور میرے کہے پر چلو۔', 'سو ڈرو اللہ سے اور میرا کہا مانو [۸۷]', '\"So fear Allah, keep your duty to Him, and obey me.', 'So fear Allah and obey me,'),
(3083, 26, 151, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ لَا تُطِیۡعُوۡۤا  اَمۡرَ  الۡمُسۡرِفِیۡنَ ﴿۱۵۱﴾ۙ', 'اور حد سے تجاوز کرنے والوں کی بات نہ مانو۔', 'اورنہ مانو حکم بیباک لوگوں کا', '\"And follow not the command of Al-Musrifoon (i.e. their chiefs, leaders who were polytheists, criminals and sinners),', 'and do not obey the order of the transgressors'),
(3084, 26, 152, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'الَّذِیۡنَ یُفۡسِدُوۡنَ فِی الۡاَرۡضِ وَ لَا یُصۡلِحُوۡنَ ﴿۱۵۲﴾', 'جو ملک میں فساد کرتے ہیں اور اصلاح نہیں کرتے۔', 'جو خرابی کرتے ہیں ملک میں اور اصلاح نہیں کرتے [۸۸]', '\"Who make mischief in the land, and reform not.\"', 'who make mischief on the land and who do not set things right”.'),
(3085, 26, 153, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالُوۡۤا  اِنَّمَاۤ   اَنۡتَ مِنَ  الۡمُسَحَّرِیۡنَ ﴿۱۵۳﴾ۚ', 'وہ کہنے لگے کہ تم تو جادو زدہ ہو۔', 'بولے تجھ پر تو کسی نے جادو کیا ہے', 'They said: \"You are only of those bewitched!', 'They said, “You are merely one of those bewitched.'),
(3086, 26, 154, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'مَاۤ  اَنۡتَ اِلَّا بَشَرٌ مِّثۡلُنَا ۚۖ فَاۡتِ بِاٰیَۃٍ  اِنۡ  کُنۡتَ مِنَ  الصّٰدِقِیۡنَ ﴿۱۵۴﴾', 'تم اور کچھ نہیں ہماری ہی طرح کے آدمی ہو۔ اگر سچے ہو تو کوئی نشانی پیش کرو۔', 'توبھی ایک آدمی ہے جیسے ہم [۸۹] سو لے آ کچھ نشانی اگر تو سچا ہے [۹۰]', '\"You are but a human being like us. Then bring us a sign if you are of the truthful.\"', 'You are nothing but a human like us. So, bring a sign if you are one of the truthful.”'),
(3087, 26, 155, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ ہٰذِہٖ نَاقَۃٌ  لَّہَا شِرۡبٌ وَّ لَکُمۡ شِرۡبُ  یَوۡمٍ  مَّعۡلُوۡمٍ ﴿۱۵۵﴾ۚ', 'صالح نے کہا دیکھو یہ اونٹنی ہے ایک دن پانی پینے کی اسکی باری ہے اور ایک معین روز تمہاری باری۔', 'کہا یہ اونٹنی ہے اسکے لئے پانی پینے کی ایک باری اور تمہارے لئے باری ایک دن کی مقرر [۹۱]', 'He said: \"Here is a she-camel; it has a right to drink (water), and you have a right to drink (water) (each) on a day, known.', 'He said, “This is a she-camel. She has a share of water, and you have a share of water on a specified day.'),
(3088, 26, 156, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ لَا تَمَسُّوۡہَا بِسُوۡٓءٍ فَیَاۡخُذَکُمۡ عَذَابُ  یَوۡمٍ  عَظِیۡمٍ ﴿۱۵۶﴾', 'اور اسکو کوئی تکلیف نہ دینا نہیں تو تمکو ایک بڑے سخت دن کا عذاب آ پکڑے گا۔', 'اور مت چھیڑیو اس کو بری طرح سے پھر پکڑ لے تم کو آفت ایک بڑے دن کی [۹۲]', '\"And touch her not with harm, lest the torment of a Great Day seize you.\"', 'So do not touch her with evil (intent), lest you should be seized by a painful punishment.”'),
(3089, 26, 157, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَعَقَرُوۡہَا فَاَصۡبَحُوۡا نٰدِمِیۡنَ ﴿۱۵۷﴾ۙ', 'بالآخر انہوں نے اسکو مار ڈالا پھر نادم ہوئے۔', 'پھر کاٹ ڈالا اس اونٹنی کو پھر کل کو رہ گئے پچتاتے [۹۳]', 'But they killed her, and then they became regretful.', 'But they killed her, then they became remorseful,');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(3090, 26, 158, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاَخَذَہُمُ الۡعَذَابُ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیَۃً ؕ وَ مَا  کَانَ  اَکۡثَرُہُمۡ مُّؤۡمِنِیۡنَ ﴿۱۵۸﴾', 'سو انکو عذاب نے آ پکڑا۔ بیشک اس میں نشانی ہے اور ان میں اکثر ایمان لانے والے نہیں تھے۔', 'پھر آ پکڑا ان کو عذاب نے البتہ اس بات میں نشانی ہے اور  ان میں بہت لوگ نہیں ماننے والے', 'So the torment overtook them. Verily, in this is indeed a sign, yet most of them are not believers.', 'and the punishment seized them. Surely, in this there is a sign, but most of them are not believers,'),
(3091, 26, 159, 8, 12, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اِنَّ رَبَّکَ لَہُوَ  الۡعَزِیۡزُ  الرَّحِیۡمُ ﴿۱۵۹﴾٪', 'اور تمہارا پروردگار تو غالب ہے مہربان ہے۔', 'اور تیرا رب وہی ہے زبردست رحم کرنے والا', 'And verily! Your Lord, He is indeed the All-Mighty, the Most Merciful.', 'and indeed your Lord is the Mighty, the Merciful.'),
(3092, 26, 160, 9, 13, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'کَذَّبَتۡ قَوۡمُ  لُوۡطِۣ الۡمُرۡسَلِیۡنَ ﴿۱۶۰﴾ۚۖ', 'قوم لوط نے بھی پیغمبروں کو جھٹلایا۔', 'جھٹلایا لوط کی قوم نے پیغام لانے والوں کو', 'The prople of Lout (Lot) (those dwelt in the towns of Sodom in Palestine) belied the Messengers.', 'The people of LūT rejected the messengers'),
(3093, 26, 161, 9, 13, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِذۡ قَالَ لَہُمۡ اَخُوۡہُمۡ لُوۡطٌ اَلَا تَتَّقُوۡنَ ﴿۱۶۱﴾ۚ', 'جب ان سے انکے بھائی لوط نے کہا کہ تم کیوں نہیں ڈرتے۔', 'جب کہا ان کو انکے بھائی لوط نے کیا تم ڈرتے نہیں', 'When their brother Lout (Lot) said to them: \"Will you not fear Allah and obey Him?', 'when their brother LūT said to them, “Do you not fear Allah?'),
(3094, 26, 162, 9, 13, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنِّیۡ  لَکُمۡ  رَسُوۡلٌ  اَمِیۡنٌ ﴿۱۶۲﴾ۙ', 'میں تو تمہارا امانت دار پیغمبر ہوں۔', 'میں تمہارے لئے پیغام لانے والا ہوں معتبر', '\"Verily! I am a trustworthy Messenger to you.', 'I am an honest messenger for you.'),
(3095, 26, 163, 9, 13, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاتَّقُوا اللّٰہَ  وَ اَطِیۡعُوۡنِ ﴿۱۶۳﴾ۚ', 'تو اللہ سے ڈرو اور میرا کہا مانو۔', 'سو ڈرو اللہ سے اور میرا کہا مانو', '\"So fear Allah, keep your duty to Him, and obey me.', 'So fear Allah and obey me.'),
(3096, 26, 164, 9, 13, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ مَاۤ  اَسۡـَٔلُکُمۡ عَلَیۡہِ  مِنۡ اَجۡرٍ ۚ اِنۡ اَجۡرِیَ   اِلَّا عَلٰی  رَبِّ  الۡعٰلَمِیۡنَ ﴿۱۶۴﴾ؕ', 'اور میں تم سے اس کام کا بدلہ نہیں مانگتا میرا بدلہ رب العالمین کے ذمے ہے۔', 'اور مانگتا نہیں میں تم سے اس کا کچھ بدلہ میرا بدلہ ہے اسی پروردگار عالم پر', '\"No reward do I ask of you for it (my Message of Islamic Monotheism), my reward is only from the Lord of the Alameen (mankind, jinns and all that exists).', 'I do not claim from you any reward for it. My reward is with none but with the Lord of the worlds.'),
(3097, 26, 165, 9, 13, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اَتَاۡتُوۡنَ الذُّکۡرَانَ  مِنَ  الۡعٰلَمِیۡنَ ﴿۱۶۵﴾ۙ', 'کیا تم دنیا جہان میں سے لڑکوں پر مائل ہوتے ہو۔', 'کیا تم دوڑتے ہو جہان کے مردوں پر [۹۴]', '\"Go you in unto the males of the Alameen (mankind),', 'Do you go to the males (for having sex) out of the whole universe,'),
(3098, 26, 166, 9, 13, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ تَذَرُوۡنَ مَا خَلَقَ لَکُمۡ  رَبُّکُمۡ  مِّنۡ اَزۡوَاجِکُمۡ ؕ بَلۡ اَنۡتُمۡ قَوۡمٌ عٰدُوۡنَ ﴿۱۶۶﴾', 'اور تمہارے پروردگار نے جو تمہارے لئے تمہاری بیویاں پیدا کی ہیں انکو چھوڑ دیتے ہو حقیقت یہ ہے کہ تم حد سے نکل جانے والے لوگ ہو۔', 'اور چھوڑتے ہو جو تمہارے واسطے بنا دی ہیں تمہارے رب نے تمہاری جوروئیں بلکہ تم لوگ ہو حد سے بڑھنے والے [۹۵]', '\"And leave those whom Allah has created for you to be your wives? Nay, you are a trespassing people!\"', 'and leave your wives whom your Lord has created for you? Indeed you are a people who cross (all) limits.”'),
(3099, 26, 167, 9, 13, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالُوۡا لَئِنۡ لَّمۡ تَنۡتَہِ یٰلُوۡطُ لَتَکُوۡنَنَّ مِنَ الۡمُخۡرَجِیۡنَ ﴿۱۶۷﴾', 'وہ کہنے لگے کہ اے لوط اگر تم باز نہ آئے تو شہر بدر کر دیئے جاؤ گے۔', 'بولے اگر نہ چھوڑے گا تو اے لوط تو تُو نکال دیا جائے گا [۹۶]', 'They said: \"If you cease not. O Lout (Lot)! Verily, you will be one of those who are driven out!\"', 'They said, “If you do not stop O LūT, you shall be included among the outcast.”'),
(3100, 26, 168, 9, 13, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ اِنِّیۡ  لِعَمَلِکُمۡ مِّنَ الۡقَالِیۡنَ ﴿۱۶۸﴾ؕ', 'لوط نے کہا میں تمہارے کام سے سخت بیزار ہوں۔', 'کہا میں تمہارے کام سے البتہ بیزار ہوں [۹۷]', 'He said: \"I am, indeed, of those who disapprove with severe anger and fury your (this evil) action (of sodomy).', 'He said “Indeed, I am annoyed with your act.'),
(3101, 26, 169, 9, 13, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'رَبِّ  نَجِّنِیۡ  وَ  اَہۡلِیۡ  مِمَّا یَعۡمَلُوۡنَ ﴿۱۶۹﴾', 'اے میرے پروردگار مجھکو اور میرے گھر والوں کو انکے کاموں کے وبال سے نجات دے۔', 'اے رب خلاص کر مجھ کو اور میرے گھر والوں کو ان کاموں سے جو یہ کرتے ہیں [۹۸]', '\"My Lord! Save me and my family from what they do.\"', 'My Lord, save me and my family from what they do.”'),
(3102, 26, 170, 9, 13, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَنَجَّیۡنٰہُ  وَ  اَہۡلَہٗۤ   اَجۡمَعِیۡنَ ﴿۱۷۰﴾ۙ', 'سو ہم نے انکو اور انکے گھر والوں کو سب کو نجات دی۔', 'پھر بچا دیا ہم نے اسکو اور اس کے گھر والوں کو سب کو', 'So We saved him and his family, all,', 'So We saved him and his family, all of them'),
(3103, 26, 171, 9, 13, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِلَّا  عَجُوۡزًا فِی الۡغٰبِرِیۡنَ ﴿۱۷۱﴾ۚ', 'مگر ایک بڑھیا کہ پیچھے رہ جانے والوں میں تھی۔', 'مگر ایک بڑھیا رہ گئ رہنے والوں میں [۹۹]', 'Except an old woman (his wife) among those who remained behind.', 'except an old woman among those who remained behind.'),
(3104, 26, 172, 9, 13, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'ثُمَّ  دَمَّرۡنَا الۡاٰخَرِیۡنَ ﴿۱۷۲﴾ۚ', 'پھر ہم نے اوروں کو ہلاک کر دیا۔', 'پھر اٹھا مارا ہم نے ان دوسروں کو', 'Then afterward We destroyed the others.', 'Then We destroyed the others,'),
(3105, 26, 173, 9, 13, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ اَمۡطَرۡنَا عَلَیۡہِمۡ مَّطَرًا ۚ فَسَآءَ مَطَرُ الۡمُنۡذَرِیۡنَ ﴿۱۷۳﴾', 'اور ان پر مینہ برسایا سو جو مینہ ان لوگوں پر جو خبردار کئے گئے تھے برسا وہ برا تھا۔', 'اور برسایا ان پرایک برساؤ سو کیا برا برساؤ تھا ان ڈرائے ہوؤں کا [۱۰۰]', 'And We rained on them a rain (of torment). And how evil was the rain of those who had been warned.', 'and subjected them to a terrible rain. So evil was the rain of those who were warned.'),
(3106, 26, 174, 9, 13, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنَّ فِیۡ ذٰلِکَ لَاٰیَۃً ؕ وَ مَا  کَانَ  اَکۡثَرُہُمۡ مُّؤۡمِنِیۡنَ ﴿۱۷۴﴾', 'بیشک اس میں نشانی ہے۔ اور ان میں اکثر ایمان لانے والے نہیں تھے۔', 'البتہ اس میں نشانی ہے اور ان میں بہت لوگ نہیں تھے ماننے والے', 'Verily, in this is indeed a sign, yet most of them are not believers.', 'Surely, in this there is a sign, but most of them are not believers,'),
(3107, 26, 175, 9, 13, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اِنَّ  رَبَّکَ لَہُوَ  الۡعَزِیۡزُ  الرَّحِیۡمُ ﴿۱۷۵﴾٪', 'اور تمہارا پروردگار تو غالب ہے مہربان ہے۔', 'اور تیرا رب وہی ہے زبردست رحم والا', 'And verily! Your Lord, He is indeed the All-Mighty, the Most Merciful.', 'and indeed your Lord is the Mighty, the Merciful.'),
(3108, 26, 176, 10, 14, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'کَذَّبَ اَصۡحٰبُ  لۡـَٔـیۡکَۃِ  الۡمُرۡسَلِیۡنَ ﴿۱۷۶﴾ۚۖ', 'اور بن کے رہنے والوں نے بھی پیغمبروں کو جھٹلایا۔', 'جھٹلایا بن کے رہنے والوں نے پیغام لانے والوں کو [۱۰۱]', 'The dwellers of Al-Aiyka (near Madyan (Midian)) belied the Messengers.', 'The people of Aaikah rejected the messengers'),
(3109, 26, 177, 10, 14, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِذۡ   قَالَ لَہُمۡ شُعَیۡبٌ  اَلَا  تَتَّقُوۡنَ ﴿۱۷۷﴾ۚ', 'جب ان سے شعیب نے کہا کہ تم ڈرتے کیوں نہیں۔', 'جب کہا ان کو شعیب نے کیا تم ڈرتے نہیں', 'When Shuaib (Shuaib) said to them: \"Will you not fear Allah (and obey Him)?', 'when Shu‘aib said to them, “Do you not fear Allah?'),
(3110, 26, 178, 10, 14, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنِّیۡ  لَکُمۡ  رَسُوۡلٌ  اَمِیۡنٌ ﴿۱۷۸﴾ۙ', 'میں تو تمہارا امانت دار پیغمبر ہوں۔', 'میں تم کو پیغام پہنچانے والا ہوں معتبر', '\"I am a trustworthy Messenger to you.', 'I am an honest messenger for you.'),
(3111, 26, 179, 10, 14, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاتَّقُوا  اللّٰہَ   وَ  اَطِیۡعُوۡنِ ﴿۱۷۹﴾ۚ', 'تو اللہ سے ڈرو اور میرا کہا مانو۔', 'سو ڈرو اللہ سے اور میرا کہا مانو', '\"So fear Allah, keep your duty to Him, and obey me.', 'So fear Allah and obey me.'),
(3112, 26, 180, 10, 14, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ مَاۤ  اَسۡـَٔلُکُمۡ عَلَیۡہِ مِنۡ اَجۡرٍ ۚ اِنۡ اَجۡرِیَ  اِلَّا عَلٰی رَبِّ الۡعٰلَمِیۡنَ ﴿۱۸۰﴾ؕ', 'اور میں اس کام کا تم سے کچھ بدلہ نہیں مانگتا میرا بدلہ تو رب العالمین کے ذمے ہے۔', 'اور نہیں مانگتا میں تم سے اس پر کچھ بدلہ میرا بدلہ ہے اسی پروردگار عالم پر', '\"No reward do I ask of you for it (my Message of Islamic Monotheism), my reward is only from the Lord of the Alameen (mankind, jinns and all that exists).', 'And I do not claim from you any reward for it; my reward is with none but with the Lord of the worlds.'),
(3113, 26, 181, 10, 14, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اَوۡفُوا الۡکَیۡلَ وَ لَا تَکُوۡنُوۡا مِنَ الۡمُخۡسِرِیۡنَ ﴿۱۸۱﴾ۚ', 'دیکھو پیمانہ پورا بھرا کرو اور نقصان نہ کیا کرو۔', 'پورا بھر کر دو ماپ اور مت ہو نقصان دینے والے', '\"Give full measure, and cause no loss (to others).', 'Give full measure, and do not be among those who bring loss to others.'),
(3114, 26, 182, 10, 14, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  زِنُوۡا  بِالۡقِسۡطَاسِ  الۡمُسۡتَقِیۡمِ ﴿۱۸۲﴾ۚ', 'اور ترازو سیدھی رکھ کر تولا کرو۔', 'اور تولو سیدھی ترازو سے [۱۰۲]', '\"And weigh with the true and straight balance.', 'Weigh with an even balance,'),
(3115, 26, 183, 10, 14, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ لَا تَبۡخَسُوا النَّاسَ اَشۡیَآءَہُمۡ وَ لَا تَعۡثَوۡا فِی  الۡاَرۡضِ  مُفۡسِدِیۡنَ ﴿۱۸۳﴾ۚ', 'اور لوگوں کو انکی چیزیں کم نہ دیا کرو اور ملک میں فساد نہ کرتے پھرو۔', 'اور مت گھٹا دو لوگوں کو ان کی چیزیں اور مت دوڑو ملک میں خرابی ڈالتے ہوئے [۱۰۳]', '\"And defraud not people by reducing their things, nor do evil, making corruption and mischief in the land.', 'and do not make people short of their things, and do not spread disorder in the land as mischief-makers,'),
(3116, 26, 184, 10, 14, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ اتَّقُوا الَّذِیۡ خَلَقَکُمۡ وَ الۡجِبِلَّۃَ الۡاَوَّلِیۡنَ ﴿۱۸۴﴾ؕ', 'اور اس سے ڈرو جس نے تمکو اور پہلی خلقت کو پیدا کیا۔', 'اور ڈرو اس سے جس نے بنایا تم کو اور اگلی خلقت کو', '\"And fear Him Who created you and the generations of the men of old.\"', 'and be fearful of the One who created you and the former generations.”'),
(3117, 26, 185, 10, 14, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالُوۡۤا  اِنَّمَاۤ   اَنۡتَ مِنَ  الۡمُسَحَّرِیۡنَ ﴿۱۸۵﴾ۙ', 'وہ کہنے لگے کہ تم تو جادو زدہ ہو۔', 'بولے تجھ پر تو کسی نے جادو کر دیا ہے', 'They said: \"You are only one of those bewitched!', 'They said, “You are but one of the bewitched men.'),
(3118, 26, 186, 10, 14, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ مَاۤ  اَنۡتَ اِلَّا بَشَرٌ  مِّثۡلُنَا وَ  اِنۡ  نَّظُنُّکَ لَمِنَ  الۡکٰذِبِیۡنَ ﴿۱۸۶﴾ۚ', 'اور تم اور کچھ نہیں ہم ہی جیسے آدمی ہو۔ اور ہمارا خیال ہے کہ تم جھوٹے ہو۔', 'اور تو بھی ایک آدمی ہے جیسے ہم اور ہمارے خیال میں تو تُو جھوٹا ہے [۱۰۴]', '\"You are but a human being like us and verily, we think that you are one of the liars!', 'You are no more than a human like us, and in fact we consider you to be one of the liars.'),
(3119, 26, 187, 10, 14, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاَسۡقِطۡ عَلَیۡنَا کِسَفًا مِّنَ السَّمَآءِ  اِنۡ  کُنۡتَ مِنَ  الصّٰدِقِیۡنَ ﴿۱۸۷﴾ؕ', 'سو اگر سچے ہو تو ہم پر آسمان سے ایک ٹکڑا لا گراؤ۔', 'سو گرا دے ہم پر کوئی ٹکڑا آسمان کا اگر تو سچا ہے [۱۰۵]', '\"So cause a piece of the heaven to fall on us, if you are of the truthful!\"', 'So cause a piece from the sky to fall down upon us, if you are one of the truthful.”'),
(3120, 26, 188, 10, 14, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'قَالَ  رَبِّیۡۤ   اَعۡلَمُ  بِمَا تَعۡمَلُوۡنَ ﴿۱۸۸﴾', 'شعیب نے کہا کہ جو کام تم کرتے ہو میرا پروردگار اس سے خوب واقف ہے۔', 'کہا میرا رب خوب جانتا ہے جو کچھ تم کرتے ہو [۱۰۶]', 'He said: \"My Lord is the Best Knower of what you do.\"', 'He said, “My Lord knows well what you do.”'),
(3121, 26, 189, 10, 14, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَکَذَّبُوۡہُ  فَاَخَذَہُمۡ عَذَابُ یَوۡمِ  الظُّلَّۃِ ؕ اِنَّہٗ  کَانَ عَذَابَ  یَوۡمٍ  عَظِیۡمٍ ﴿۱۸۹﴾', 'تو ان لوگوں نے انکو جھٹلایا پس سائبان والے دن کے عذاب نے انکو آ پکڑا۔ بیشک وہ بڑے سخت دن کا عذاب تھا۔', 'پھر اس کو جھٹلایا پھر پکڑ لیا ان کو آفت نے سائبان والے دن کی بیشک وہ تھا عذاب بڑے دن کا [۱۰۷]', 'But they belied him, so the torment of the day of shadow (a gloomy cloud) seized them, indeed that was the torment of a Great Day.', 'Thus they rejected him, so they were seized by the torment of the Day of Canopy. Indeed it was the punishment of a terrible day.'),
(3122, 26, 190, 10, 14, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنَّ فِیۡ  ذٰلِکَ لَاٰیَۃً ؕ وَ مَا کَانَ  اَکۡثَرُہُمۡ مُّؤۡمِنِیۡنَ ﴿۱۹۰﴾', 'اس میں یقیناً نشانی ہے۔ اور ان میں اکثر ایمان لانے والے نہیں تھے۔', 'البتہ اس بات میں نشانی ہے اور ان میں بہت لوگ نہیں ماننے والے', 'Verily, in this is indeed a sign, yet most of them are not believers.', 'Surely, in this there is a sign, but most of them are not believers,'),
(3123, 26, 191, 10, 14, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اِنَّ  رَبَّکَ  لَہُوَ  الۡعَزِیۡزُ  الرَّحِیۡمُ ﴿۱۹۱﴾٪', 'اور تمہارا پروردگار تو غالب ہے مہربان ہے۔', 'اور تیرا رب وہی ہے زبردست رحم والا', 'And verily! Your Lord, He is indeed the All-Mighty, the Most Merciful.', 'and indeed your Lord is the Mighty, the Merciful.'),
(3124, 26, 192, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اِنَّہٗ   لَتَنۡزِیۡلُ  رَبِّ  الۡعٰلَمِیۡنَ ﴿۱۹۲﴾ؕ', 'اور یہ قرآن رب العالمین کا اتارا ہوا ہے۔', 'اور یہ قرآن ہے اتارا ہوا پروردگار عالم کا', 'And truly, this (the Quran) is a revelation from the Lord of the Alameen (mankind, jinns and all that exists),', 'This (Qur’ān) is the revelation of the Lord of the worlds.'),
(3125, 26, 193, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'نَزَلَ  بِہِ  الرُّوۡحُ  الۡاَمِیۡنُ ﴿۱۹۳﴾ۙ', 'اس کو امانتدار فرشتہ لے کر اترا ہے۔', 'لیکر اترا ہے اسکو فرشتہ معتبر', 'Which the trustworthy Rooh (Jibrael (Gabriel)) has brought down;', 'The Trusted Spirit has brought it down'),
(3126, 26, 194, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'عَلٰی قَلۡبِکَ لِتَکُوۡنَ مِنَ الۡمُنۡذِرِیۡنَ ﴿۱۹۴﴾', 'یعنی اسنے تمہارے دل پر اسکا القا کیا ہے تاکہ لوگوں کو خبردار کرتے رہو۔', 'ترے دل پر کہ تو ہو ڈر سنادینے والا [۱۰۸]', 'Upon your heart (O Muhammad SAW) that you may be (one) of the warners,', 'upon your heart, so that you become one of the warners'),
(3127, 26, 195, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'بِلِسَانٍ عَرَبِیٍّ مُّبِیۡنٍ ﴿۱۹۵﴾ؕ', 'اور القا بھی فصیح و بلیغ عربی زبان میں کیا ہے۔', 'کھلی عربی زبان میں [۱۰۹]', 'In the plain Arabic language.', 'in plain Arabic language.'),
(3128, 26, 196, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اِنَّہٗ  لَفِیۡ  زُبُرِ الۡاَوَّلِیۡنَ ﴿۱۹۶﴾', 'اور اسکی خبر پہلے پیغمبروں کی کتابوں میں لکھی ہوئی ہے۔', 'اور یہ لکھا ہے پہلوں کی کتابوں میں [۱۱۰]', 'And verily, it (the Quran, and its revelation to Prophet Muhammad SAW) is (announced) in the Scriptures (i.e. the Taurat (Torah) and the Injeel (Gospel)) of former people.', 'And of course, it is (mentioned) in the Scriptures of the former people.'),
(3129, 26, 197, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اَوَ لَمۡ  یَکُنۡ لَّہُمۡ اٰیَۃً  اَنۡ یَّعۡلَمَہٗ عُلَمٰٓؤُا بَنِیۡۤ   اِسۡرَآءِیۡلَ ﴿۱۹۷﴾ؕ', 'اور کیا ان کے لئے یہ سند نہیں ہے کہ علمائے بنی اسرائیل اس بات کو جانتے ہیں۔', 'کیا انکے واسطے نشانی نہیں یہ بات کہ اسکی خبر رکھتے ہیں پڑھے لوگ بنی اسرائیل کے [۱۱۱]', 'Is it not a sign to them that the learned scholars (like Abdullah bin Salam ÑÖì who embraced Islam) of the Children of Israel knew it (as true)?', 'Is it not a proof for them that the knowledgeable of the children of Isrā’īl recognize him (the prophet)?'),
(3130, 26, 198, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ لَوۡ  نَزَّلۡنٰہُ عَلٰی بَعۡضِ الۡاَعۡجَمِیۡنَ ﴿۱۹۸﴾ۙ', 'اور اگر ہم اس کو کسی عجمی پر اتارتے۔', 'اور اگر اتارتے ہم یہ کتاب کسی اوپری (دوسری) زبان والے پر', 'And if We had revealed it (this Quran) unto any of the non-Arabs,', 'Even if We had revealed it to a Non-Arab,'),
(3131, 26, 199, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَقَرَاَہٗ  عَلَیۡہِمۡ مَّا کَانُوۡا بِہٖ مُؤۡمِنِیۡنَ ﴿۱۹۹﴾ؕ', 'اور وہ اسے ان لوگوں کر پڑھ کر سناتا تو یہ اسے کبھی نہ مانتے۔', 'اور وہ اسکو پڑھ کر سناتا تو بھی اس پر یقین نہ لاتے [۱۱۲]', 'And he had recited it unto them, they would not have believed in it.', 'and he had recited it to them, they would not have believed in it.'),
(3132, 26, 200, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'کَذٰلِکَ سَلَکۡنٰہُ  فِیۡ قُلُوۡبِ الۡمُجۡرِمِیۡنَ ﴿۲۰۰﴾ؕ', 'اسی طرح ہم نے انکار کو گنہگاروں کے دلوں میں داخل کر دیا۔', 'اسی طرح گھسا دیا ہم نے اس انکار کو گنہگاروں کے دل میں', 'Thus have We caused it (the denial of the Quran) to enter the hearts of the Moojrimoon (criminals, polytheists, sinners, etc.).', 'This is how We have made it pass through the hearts of the sinners.'),
(3133, 26, 201, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'لَا یُؤۡمِنُوۡنَ بِہٖ حَتّٰی یَرَوُا الۡعَذَابَ الۡاَلِیۡمَ ﴿۲۰۱﴾ۙ', 'وہ جب تک درد دینے والا عذاب نہ دیکھ لیں اس کو نہیں مانیں گے۔', 'وہ نہ مانیں گے اس کو جب تک نہ دیکھ لیں گےعذاب دردناک [۱۱۳]', 'They will not believe in it until they see the painful torment;', 'They will not believe in it until they will see the painful punishment'),
(3134, 26, 202, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَیَاۡتِیَہُمۡ  بَغۡتَۃً   وَّ  ہُمۡ  لَا  یَشۡعُرُوۡنَ ﴿۲۰۲﴾ۙ', 'وہ عذاب ان پر ناگہاں آ واقع ہو گا اور انہیں خبر بھی نہ ہو گی۔', 'پھر آئے ان پر اچانک اور انکو خبر بھی نہ ہو', 'It shall come to them of a sudden, while they perceive it not;', 'and it will come to them suddenly while they will not be anticipating (it),'),
(3135, 26, 203, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَیَقُوۡلُوۡا ہَلۡ  نَحۡنُ  مُنۡظَرُوۡنَ ﴿۲۰۳﴾ؕ', 'اس وقت کہیں گے کیا ہمیں مہلت ملے گی؟', 'پھر کہنے لگیں کچھ بھی ہم کو فرصت ملے گی [۱۱۴]', 'Then they will say: \"Can we be respited?\"', 'and (then) they will say, “Is it (possible) that we are given some respite?”'),
(3136, 26, 204, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اَفَبِعَذَابِنَا یَسۡتَعۡجِلُوۡنَ ﴿۲۰۴﴾', 'تو کیا یہ ہمارے عذاب کیلئے جلدی مچا رہے ہیں۔', 'کیا ہمارے عذاب کو جلد مانگتے ہیں', 'Would they then wish for Our Torment to be hastened on?', 'Is it then Our punishment that they are trying to hasten up?'),
(3137, 26, 205, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اَفَرَءَیۡتَ اِنۡ مَّتَّعۡنٰہُمۡ سِنِیۡنَ ﴿۲۰۵﴾ۙ', 'بھلا دیکھو تو اگر ہم انکو برسوں فائدے دیتے رہیں۔', 'بھلا دیکھ تو اگر فائدہ پہنچاتے رہیں ہم انکو برسوں', 'Tell Me, if We do let them enjoy for years,', 'So tell me, if We give them enjoyment for years,'),
(3138, 26, 206, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'ثُمَّ  جَآءَہُمۡ  مَّا  کَانُوۡا  یُوۡعَدُوۡنَ ﴿۲۰۶﴾ۙ', 'پھر ان پر وہ عذاب آ واقع ہو جس کا ان سے وعدہ کیا جاتا ہے۔', 'پھر پہنچے ان پر جس چیز کا ان سے وعدہ تھا', 'And afterwards comes to them that (punishment) which they had been promised!', 'then comes to them what they are warned of,'),
(3139, 26, 207, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'مَاۤ  اَغۡنٰی عَنۡہُمۡ مَّا کَانُوۡا یُمَتَّعُوۡنَ ﴿۲۰۷﴾ؕ', 'تو جو فائدے یہ اٹھاتے رہے انکے کس کام آئیں گے۔', 'تو کیا کام آئے گا ان کے جو کچھ فائدے اٹھاتے رہے [۱۱۵]', 'All that with which they used to enjoy shall not avail them.', 'what help can they receive from the comforts they were given to enjoy?'),
(3140, 26, 208, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ مَاۤ  اَہۡلَکۡنَا مِنۡ قَرۡیَۃٍ  اِلَّا لَہَا مُنۡذِرُوۡنَ ﴿۲۰۸﴾٭ۖۛ', 'اور ہم نے کوئی بستی ہلاک نہیں کی مگر اس کے لئے خبردار کرنے والے پہلے بھیج دیتے تھے۔', 'اور کوئی بستی نہیں غارت کی ہم نے جس کے لئے نہیں تھے ڈر سنادینے والے', 'And never did We destroy a township, but it had its warners', 'We did not destroy any town unless it has had warners'),
(3141, 26, 209, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'ذِکۡرٰی ۟ۛ وَ مَا کُنَّا ظٰلِمِیۡنَ ﴿۲۰۹﴾', 'تاکہ یاد دلا دیں اور ہم ظالم نہیں ہیں۔', 'یاد دلانے کو اور ہمارا کام نہیں ہے ظلم کرنا [۱۱۶]', 'By way of reminder, and We have never been unjust.', 'to give advice, and We have never been unjust.'),
(3142, 26, 210, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ مَا  تَنَزَّلَتۡ بِہِ  الشَّیٰطِیۡنُ ﴿۲۱۰﴾', 'اور اس قرآن کو شیطان لے کر نازل نہیں ہوئے۔', 'اور اس قرآن کو نہیں لیکر اترے شیطان', 'And it is not the Shayatin (devils) who have brought it (this Quran) down,', 'And this (Qur’ān) is not brought down by devils.'),
(3143, 26, 211, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ مَا یَنۡۢبَغِیۡ لَہُمۡ وَ مَا یَسۡتَطِیۡعُوۡنَ ﴿۲۱۱﴾ؕ', 'یہ کام نہ تو انکے لائق ہے اور نہ وہ اسکی طاقت رکھتے ہیں۔', 'اور نہ ان سے بن آئے اور نہ وہ کر سکیں [۱۱۷]', 'Neither would it suit them, nor they can (produce it).', 'It neither suits them, nor are they able to (do this).'),
(3144, 26, 212, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنَّہُمۡ  عَنِ  السَّمۡعِ  لَمَعۡزُوۡلُوۡنَ ﴿۲۱۲﴾ؕ', 'وہ تو آسمانی باتوں کے سننے کے مقامات سے الگ کر دیئے گئے ہیں۔', 'ان کو تو سننے کی جگہ سے دور کر دیا ہے [۱۱۸]', 'Verily, they have been removed far from hearing it.', 'In fact, they are kept far away from hearing (it at the time of revelation).'),
(3145, 26, 213, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَلَا تَدۡعُ مَعَ اللّٰہِ  اِلٰـہًا اٰخَرَ  فَتَکُوۡنَ مِنَ  الۡمُعَذَّبِیۡنَ ﴿۲۱۳﴾ۚ', 'تو اللہ کے سوا کسی اور معبود کو مت پکارنا ورنہ تمکو عذاب دیا جائے گا۔', 'سو تو مت پکار اللہ کے ساتھ دوسرا معبود پھر تو پڑے عذاب میں [۱۱۹]', 'So invoke not with Allah another ilah (god) lest you be among those who receive punishment.', 'So do not invoke any other god along with Allah, otherwise you will be among those who are to be punished.'),
(3146, 26, 214, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ اَنۡذِرۡ عَشِیۡرَتَکَ  الۡاَقۡرَبِیۡنَ ﴿۲۱۴﴾ۙ', 'اور اپنے قریب کے رشتہ داروں کو ڈر سنا دو۔', 'اور ڈر سنا دے اپنے قریب کے رشتہ داروں کو [۱۲۰]', 'And warn your tribe (O Muhammad SAW) of near kindred.', 'And warn the nearest people of your clan,'),
(3147, 26, 215, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ اخۡفِضۡ جَنَاحَکَ لِمَنِ اتَّبَعَکَ مِنَ الۡمُؤۡمِنِیۡنَ ﴿۲۱۵﴾ۚ', 'اور جو مومن تمہارے پیرو ہو گئے ہیں ان سے تواضع سے پیش آؤ۔', 'اور اپنے بازو نیچے رکھ انکے واسطے جو تیرے ساتھ ہیں ایمان والے [۱۲۱]', 'And be kind and humble to the believers who follow you.', 'and be kind with humbleness to the believers who followed you.'),
(3148, 26, 216, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'فَاِنۡ عَصَوۡکَ فَقُلۡ اِنِّیۡ بَرِیۡٓءٌ مِّمَّا تَعۡمَلُوۡنَ ﴿۲۱۶﴾ۚ', 'پھر اگر لوگ تمہاری نافرمانی کریں تو کہدو کہ میں تمہارے اعمال سے بےتعلق ہوں۔', 'پھر اگر تیری نافرمانی کریں تو کہہ دے میں بیزار ہوں تمہارے کام سے [۱۲۲]', 'Then if they disobey you, say: \"I am innocent of what you do.\"', 'So if they disobey you, then say, “I disown what you do,”'),
(3149, 26, 217, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ تَوَکَّلۡ عَلَی الۡعَزِیۡزِ  الرَّحِیۡمِ ﴿۲۱۷﴾ۙ', 'اور اس غالب اور مہربان پر بھروسہ رکھو۔', 'اور بھروسہ کر اس زبردست رحم  والے پر [۱۲۳]', 'And put your trust in the All-Mighty, the Most Merciful,', 'and place your trust in the Mighty, the Merciful,'),
(3150, 26, 218, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'الَّذِیۡ  یَرٰىکَ حِیۡنَ تَقُوۡمُ ﴿۲۱۸﴾ۙ', 'جو تمکو جب تم تہجد کے وقت اٹھتے ہو دیکھتا ہے۔', 'جو دیکھتا ہے تجھ کو جب تو اٹھتا ہے', 'Who sees you (O Muhammad SAW) when you stand up (alone at night for Tahajjud prayers).', 'Who sees you when you stand (in prayer,)'),
(3151, 26, 219, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ تَقَلُّبَکَ فِی السّٰجِدِیۡنَ ﴿۲۱۹﴾', 'اور نمازیوں کیساتھ تمہارے رکوع اور سجود کو بھی دیکھتا ہے۔', 'اور تیرا پھرنا نمازیوں میں [۱۲۴]', 'And your movements among those who fall prostrate (along with you to Allah in the five compulsory congregational prayers).', 'and (sees) your movement among those who prostrate themselves.'),
(3152, 26, 220, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِنَّہٗ  ہُوَ  السَّمِیۡعُ  الۡعَلِیۡمُ ﴿۲۲۰﴾', 'بیشک وہ سننے والا ہے جاننے والا ہے۔', 'بیشک وہی ہے سننے والا جاننے والا', 'Verily! He, only He, is the All-Hearer, the All-Knower.', 'Surely, He is the All-Hearing, the All-Knowing.'),
(3153, 26, 221, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'ہَلۡ اُنَبِّئُکُمۡ عَلٰی مَنۡ تَنَزَّلُ الشَّیٰطِیۡنُ ﴿۲۲۱﴾ؕ', 'کیا میں تمہیں بتاؤں کہ شیطان یعنی جنات کس پر اترتے ہیں۔', 'میں بتلاؤں تم کو کس پر اترتے ہیں شیطان', 'Shall I inform you (O people!) upon whom the Shayatin (devils) descend?', 'Shall I tell you on whom the devils descend?'),
(3154, 26, 222, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'تَنَزَّلُ عَلٰی کُلِّ  اَفَّاکٍ  اَثِیۡمٍ ﴿۲۲۲﴾ۙ', 'وہ ہر جھوٹے گنہگار پر اترتے ہیں۔', 'اترتے ہیں ہر جھوٹے گنہگار پر [۱۲۵]', 'They descend on every lying (one who tells lies), sinful person.', 'They descend on every sinful liar.'),
(3155, 26, 223, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'یُّلۡقُوۡنَ السَّمۡعَ وَ اَکۡثَرُہُمۡ کٰذِبُوۡنَ ﴿۲۲۳﴾ؕ', 'جنات سنی ہوئی بات اسکے کان میں لا ڈالتے ہیں اور وہ اکثر جھوٹے ہیں۔', 'لا ڈالتے ہیں سنی ہوئی بات اور بہت ان میں جھوٹے ہیں [۱۲۶]', 'Who gives ear (to the devils and they pour what they may have heard of the unseen from the angels), and most of them are liars.', 'They give ear to hear (secretly,) and most of them tell lies.'),
(3156, 26, 224, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ الشُّعَرَآءُ  یَتَّبِعُہُمُ  الۡغَاوٗنَ ﴿۲۲۴﴾ؕ', 'اور شاعروں کی پیروی گمراہ لوگ کیا کرتے ہیں۔', 'اور شاعروں کی بات پر چلیں وہی جو بے راہ ہیں [۱۲۷]', 'As for the poets, the erring follow them,', 'As for the poets, they are followed by the straying people.'),
(3157, 26, 225, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اَلَمۡ  تَرَ  اَنَّہُمۡ  فِیۡ کُلِّ وَادٍ  یَّہِیۡمُوۡنَ ﴿۲۲۵﴾ۙ', 'کیا تم نے نہیں دیکھا کہ وہ ہر وادی میں سر مارتے پھرتے ہیں۔', 'تو نے نہیں دیکھا کہ وہ ہر میدان میں سر مارے پھرتے ہیں [۱۲۸]', 'See you not that they speak about every subject (praising others right or wrong) in their poetry?', 'Did you not see that they wander in every valley,'),
(3158, 26, 226, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'وَ  اَنَّہُمۡ  یَقُوۡلُوۡنَ مَا  لَا  یَفۡعَلُوۡنَ ﴿۲۲۶﴾ۙ', 'اور کہتے وہ ہیں جو کرتے نہیں۔', 'اور یہ کہ وہ کہتے ہیں جو نہیں کرتے [۱۲۹]', 'And that they say what they do not do.', 'and that they say what they do not?'),
(3159, 26, 227, 11, 15, 19, 'وَ قَالَ الَّذِیۡنَ ', 'الشعراء', 'اِلَّا الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ وَ ذَکَرُوا اللّٰہَ  کَثِیۡرًا وَّ انۡتَصَرُوۡا مِنۡۢ بَعۡدِ مَا ظُلِمُوۡا ؕ وَ سَیَعۡلَمُ الَّذِیۡنَ ظَلَمُوۡۤا اَیَّ  مُنۡقَلَبٍ  یَّنۡقَلِبُوۡنَ ﴿۲۲۷﴾٪', 'مگر جو لوگ ایمان لائے اور نیک کام کئے اور اللہ کو بہت یاد کرتے رہے اور انہوں نے اپنے اوپر ظلم ہونے کے بعد انتقام بھی لیا اور ظالم عنقریب جان لیں گے کہ کون سی جگہ لوٹ کر جاتے ہیں۔', 'مگر وہ لوگ جو یقین لائے اور کام کئے اچھے اور یاد کی اللہ کی بہت اور بدلہ لیا اس کے پیچھے کہ ان پر ظلم ہوا [۱۳۰] اور اب معلوم کر لیں گے ظلم کرنے والے کہ کس کروٹ الٹتے ہیں [۱۳۱]', 'Except those who believe (in the Oneness of Allah Islamic Monotheism), and do righteous deeds, and remember Allah much, and reply back (in poetry) to the unjust poetry (which the pagan poets utter against the Muslims). And those who do wrong will come to know by what overturning they will be overturned.', 'Except those who believe and do righteous deeds and remember Allah very much, and defend themselves after they are wronged. And the wrongdoers will soon know to which place they are going to return.'),
(3160, 27, 1, 1, 16, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'طٰسٓ ۟ تِلۡکَ اٰیٰتُ الۡقُرۡاٰنِ  وَ کِتَابٍ مُّبِیۡنٍ ۙ﴿۱﴾', 'طٰس۔ یہ قرآن یعنی کتاب روشن کی آیتیں ہیں۔', 'طٰس۔ یہ آیتیں ہیں قرآن اور کھلی کتاب کی', 'TaSeen. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings). These are the Verses of the Quran, and (it is) a Book (that makes things) clear;', 'Tā Sīn . These are the verses of the Qur’ān and an enlightening book,'),
(3161, 27, 2, 1, 16, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'ہُدًی وَّ  بُشۡرٰی  لِلۡمُؤۡمِنِیۡنَ ۙ﴿۲﴾', 'مومنوں کے لئے ہدایت اور بشارت ہے۔', 'ہدایت اور خوشخبری ایمان والوں کے واسطے', 'A guide (to the Right Path); and glad tidings for the believers (who believe in the Oneness of Allah (i.e. Islamic Monotheism)).', 'a guidance and good news to the believers'),
(3162, 27, 3, 1, 16, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'الَّذِیۡنَ یُقِیۡمُوۡنَ الصَّلٰوۃَ وَ یُؤۡتُوۡنَ الزَّکٰوۃَ  وَ ہُمۡ بِالۡاٰخِرَۃِ  ہُمۡ یُوۡقِنُوۡنَ ﴿۳﴾', 'وہ جو نماز پڑھتے اور زکوٰۃ دیتے ہیں اور وہ آخرت کا بھی یقین رکھتے ہیں۔', 'جو قائم رکھتے ہیں نماز کو اور دیتے ہیں زکوٰۃ اور ان کو آخرت پر یقین ہے', 'Those who perform AsSalat (IqamatasSalat) and give Zakat and they believe with certainty in the Hereafter (resurrection, recompense of their good and bad deeds, Paradise and Hell, etc.).', 'who establish Salāh and pay Zakāh and who have faith in the Hereafter.'),
(3163, 27, 4, 1, 16, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'اِنَّ الَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِالۡاٰخِرَۃِ  زَیَّنَّا لَہُمۡ  اَعۡمَالَہُمۡ  فَہُمۡ  یَعۡمَہُوۡنَ ؕ﴿۴﴾', 'جو لوگ آخرت پر ایمان نہیں رکھتے ہم نے ان کے اعمال ان کے لئے آراستہ کر دیئے ہیں تو وہ بھٹکتے پھر رہے ہیں۔', 'جو لوگ نہیں مانتے آخرت کو اچھے دکھلائے ہم نے ان کی نظروں میں انکے کام سو وہ بہکے  پھرتے ہیں [۱]', 'Verily, those who believe not in the Hereafter, We have made their deeds fair-seeming to them, so they wander about blindly.', 'As for those who do not believe in the Hereafter, We have made their deeds look beautiful to them. So they are wandering astray.'),
(3164, 27, 5, 1, 16, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'اُولٰٓئِکَ الَّذِیۡنَ لَہُمۡ سُوۡٓءُ الۡعَذَابِ وَ ہُمۡ فِی  الۡاٰخِرَۃِ  ہُمُ  الۡاَخۡسَرُوۡنَ ﴿۵﴾', 'یہی لوگ ہیں جنکے لئے برا عذاب ہے اور وہ آخرت میں بھی نقصان اٹھانے والے ہیں۔', 'وہی ہیں جن کے واسطے بری طرح کا عذاب ہے اور آخرت میں وہی ہیں خراب [۲]', 'They are those for whom there will be an evil torment (in this world). And in the Hereafter they will be the greatest losers.', 'Those are the people who deserve the worst punishment and who are the worst losers in the Hereafter.'),
(3165, 27, 6, 1, 16, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَ اِنَّکَ لَتُلَقَّی الۡقُرۡاٰنَ مِنۡ لَّدُنۡ حَکِیۡمٍ عَلِیۡمٍ ﴿۶﴾', 'اور تمکو یہ قرآن اس حکیم و علیم کی طرف سے عطا کیا جاتا ہے۔', 'اور تجھ کو قرآن پہنچتا ہے ایک حکمت والے خبردار کے پاس سے [۳]', 'And verily, you (O Muhammad SAW) are receiving the Quran from the One, All-Wise, All-Knowing.', 'Indeed you are being given the Qur’ān by a Wise, Knowledgeable Being.'),
(3166, 27, 7, 1, 16, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'اِذۡ  قَالَ مُوۡسٰی لِاَہۡلِہٖۤ  اِنِّیۡۤ   اٰنَسۡتُ نَارًا ؕ سَاٰتِیۡکُمۡ مِّنۡہَا بِخَبَرٍ اَوۡ اٰتِیۡکُمۡ بِشِہَابٍ قَبَسٍ لَّعَلَّکُمۡ تَصۡطَلُوۡنَ ﴿۷﴾', 'جب موسٰی نے اپنے گھر والوں سے کہا کہ میں نے آگ دیکھی ہے میں وہاں سے رستے کا پتہ لاتا ہوں یا کوئی شعلہ یعنی ایک انگارہ تمہارے پاس لاتا ہوں تاکہ تم آگ تاپو۔', 'جب کہا موسٰی نے اپنے گھر والوں کو میں نے دیکھی ہے آگ [۴] اب لاتا ہوں تمہارے پاس وہاں سے کچھ خبر یا لاتا ہوں انگارا سلگا کر شاید تم سینکو [۵]', '(Remember) when Moosa (Moses) said to his household: \"Verily! I have seen a fire, I will bring you from there some information, or I will bring you a burning brand, that you may warm yourselves.\"', '(Remember) when Mūsā said to his family, “I have noticed a fire. I shall bring to you some news from it, or bring to you a live ember, so that you may warm yourselves.”'),
(3167, 27, 8, 1, 16, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'فَلَمَّا جَآءَہَا نُوۡدِیَ اَنۡۢ بُوۡرِکَ مَنۡ فِی النَّارِ وَ مَنۡ  حَوۡلَہَا ؕ وَ سُبۡحٰنَ اللّٰہِ رَبِّ  الۡعٰلَمِیۡنَ ﴿۸﴾', 'جب موسٰی اسکے پاس آئے تو ندا آئی کہ وہ جو آگ میں تجلی دکھاتا ہے با برکت ہے اور وہ جو آگ کے اردگرد ہے۔ اور اللہ جو تمام عالم کا پروردگار ہے پاک ہے۔', 'پھر جب پہنچا اسکے پاس آواز ہوئی کہ برکت ہے اس پر جو کوئی کہ آگ میں ہے اور جو اسکے آس پاس ہے [۶] اور پاک ہے وہ ذات اللہ کی جو رب سارے جہان کا [۷]', 'But when he came to it, he was called: \"Blessed is whosoever is in the fire, and whosoever is round about it! And glorified be Allah, the Lord of the Alameen (mankind, jinns and all that exists).', 'So when he came to it, he was called: “Blessed is the one who is in the fire and the one who is around it. And pure is Allah, the Lord of the worlds.'),
(3168, 27, 9, 1, 16, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'یٰمُوۡسٰۤی  اِنَّہٗۤ  اَنَا اللّٰہُ الۡعَزِیۡزُ الۡحَکِیۡمُ ۙ﴿۹﴾', 'اے موسٰی میں اللہ ہوں عزت والا حکمت والا۔', 'اے موسٰی وہ میں اللہ ہوں زبردست حکمتوں والا [۸]', '\"O Moosa (Moses)! Verily! It is I, Allah, the All-Mighty, the All-Wise.', 'O Mūsā, the fact is that I AM ALLAH, the Mighty, the Wise.'),
(3169, 27, 10, 1, 16, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَ اَلۡقِ عَصَاکَ ؕ فَلَمَّا رَاٰہَا تَہۡتَزُّ  کَاَنَّہَا جَآنٌّ  وَّلّٰی مُدۡبِرًا  وَّ لَمۡ  یُعَقِّبۡ ؕ یٰمُوۡسٰی لَا تَخَفۡ ۟ اِنِّیۡ  لَا یَخَافُ لَدَیَّ الۡمُرۡسَلُوۡنَ ﴿٭ۖ۱۰﴾', 'اور اپنی لاٹھی ڈال دو۔ سو جب اسے دیکھا تو اس طرح حرکت کر رہی تھی گویا سانپ ہے تو پیٹھ پھیر کر بھاگے اور پیچھے مڑ کر نہ دیکھا فرمایا اے موسٰی ڈرو مت۔ میرے پاس پیغمبر ڈرا نہیں کرتے۔', 'اور ڈال دے لاٹھی اپنی پھر جب دیکھا اسکو پھنپھناتے جیسے سانپ کی سٹک [۹] لوٹا پیٹھ پھیر کر او رمڑ کر نہ دیکھا [۱۰] اے موسٰی مت ڈر میں جو ہوں میرےپاس نہیں ڈرتے رسول [۱۱]', '\"And throw down your stick!\" But when he saw it moving as if it were a snake, he turned in flight, and did not look back. (It was said): \"O Moosa (Moses)! Fear not, verily! The Messengers fear not in front of Me.', 'And cast your staff down.” So when he saw it moving, as if it was a snake, he retreated turning his back, and did not look behind. “O Mūsā, be not scared. I am such that the messengers are not scared before Me,'),
(3170, 27, 11, 1, 16, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'اِلَّا مَنۡ ظَلَمَ  ثُمَّ  بَدَّلَ حُسۡنًۢا بَعۡدَ سُوۡٓءٍ فَاِنِّیۡ  غَفُوۡرٌ  رَّحِیۡمٌ ﴿۱۱﴾', 'ہاں جس نے ظلم کیا پھر برائی کے بعد اسے نیکی سے بدل دیا تو میں بخشنے والا مہربان ہوں۔', 'مگر جس نے زیادتی کی پھر بدلے میں نیکی کی برائی کے پیچھے تو میں بخشنے والا مہربان ہوں [۱۲]', '\"Except him who has done wrong and afterwards has changed evil for good, then surely, I am Oft-Forgiving, Most Merciful.', 'except him who did wrong, then after (having done) evil, replaced (it) with good, then I am Most-Forgiving, Very-Merciful.'),
(3171, 27, 12, 1, 16, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَ اَدۡخِلۡ  یَدَکَ فِیۡ جَیۡبِکَ تَخۡرُجۡ بَیۡضَآءَ مِنۡ غَیۡرِ سُوۡٓءٍ ۟ فِیۡ تِسۡعِ اٰیٰتٍ اِلٰی فِرۡعَوۡنَ وَ قَوۡمِہٖ ؕ اِنَّہُمۡ  کَانُوۡا  قَوۡمًا فٰسِقِیۡنَ ﴿۱۲﴾', 'اور اپنا ہاتھ اپنے گریبان میں ڈالو بے عیب سفید و روشن نکلے گا ان دو معجزوں کے ساتھ جو نو معجزوں میں داخل ہیں فرعون اور اسکی قوم کے پاس جاؤ کہ وہ بدکردار لوگ ہیں۔', 'اور ڈال دے ہاتھ اپنا اپنے گریبان میں کہ نکلے سفید ہو کر نہ کسی برائی سے یہ دونوں ملکر نو نشانیاں لیکر جا فرعون اور اس کی قوم کی طرف بیشک وہ تھے لوگ نافرمان [۱۳]', '\"And put your hand into your bosom, it will come forth white without hurt. (These are) among the nine signs (you will take) to Firaun (Pharaoh) and his people, they are a people who are the Fasiqoon (rebellious, disobedient to Allah).', 'And put your hand into your bosom, and it will come out white, without any evil, as one of the nine signs (sent) to Pharaoh and his people. Surely they have been a sinful people.'),
(3172, 27, 13, 1, 16, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'فَلَمَّا جَآءَتۡہُمۡ اٰیٰتُنَا مُبۡصِرَۃً  قَالُوۡا ہٰذَا  سِحۡرٌ  مُّبِیۡنٌ ﴿ۚ۱۳﴾', 'پھر جب انکے پاس ہماری روشن نشانیاں پہنچیں تو کہنے لگے یہ کھلا جادو ہے۔', 'پھر جب پہنچیں انکے پاس ہماری نشانیاں سمجھانے کو بولے یہ جادو ہے صریح', 'But when Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) came to them, clear to see, they said: \"This is a manifest magic.\"', 'So when Our signs came to them as eye-openers, they said, “This is a clear magic.”'),
(3173, 27, 14, 1, 16, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَ جَحَدُوۡا بِہَا وَ اسۡتَیۡقَنَتۡہَاۤ  اَنۡفُسُہُمۡ ظُلۡمًا وَّ عُلُوًّا ؕ فَانۡظُرۡ کَیۡفَ کَانَ عَاقِبَۃُ  الۡمُفۡسِدِیۡنَ ﴿٪۱۴﴾', 'اور بےانصافی اور غرور سے انکو ماننے سے انکار کیا جبکہ انکے دل ان کو مان چکے تھے۔ سو دیکھ لو کہ فساد کرنے والوں کا انجام کیسا ہوا۔', 'اور ان کا انکار کیا اور ان کا یقین کر چکے تھے اپنے جی میں بے انصافی اور غرور سے سو دیکھ لے کیا ہوا انجام خرابی کرنے والوں کا [۱۴]', 'And they belied them (those Ayat) wrongfully and arrogantly, though their ownselves were convinced thereof (i.e. those (Ayat) are from Allah, and Moosa (Moses) is the Messenger of Allah in truth, but they disliked to obey Moosa (Moses), and hated to believe in his Message of Monotheism). So see what was the end of the Mufsidoon (disbelievers, disobedient to Allah, evil-doers, liars.).', 'And they denied them out of sheer injustice and arrogance, though their hearts believed them (to be true). See, then, how was the fate of the mischief-makers.'),
(3174, 27, 15, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَ لَقَدۡ اٰتَیۡنَا دَاوٗدَ  وَ سُلَیۡمٰنَ عِلۡمًا ۚ وَ قَالَا الۡحَمۡدُ لِلّٰہِ الَّذِیۡ فَضَّلَنَا عَلٰی کَثِیۡرٍ  مِّنۡ عِبَادِہِ  الۡمُؤۡمِنِیۡنَ ﴿۱۵﴾', 'اور ہم نے داؤد اور سلیمان کو علم بخشا اور انہوں نے کہا کہ اللہ کا شکر ہے جس نے ہمیں اپنے بہت سے مومن بندوں پر فضیلت دی۔', 'اور ہم نے دیا داؤد اور سلیمان کو ایک علم [۱۵] اور بولے شکر اللہ کا جس نے ہم کو بزرگی دی [۱۶] اپنے بہت سے بندوں ایمان والوں پر [۱۷]', 'And indeed We gave knowledge to Dawood (David) and Sulaiman (Solomon), and they both said: \"All the praises and thanks be to Allah, Who has preferred us above many of His believing slaves!\"', 'Surely We gave knowledge to Dāwūd and Sulaimān, and they said, “Praise belongs to Allah who made us excel many of His believing servants.'),
(3175, 27, 16, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَ وَرِثَ سُلَیۡمٰنُ دَاوٗدَ وَ قَالَ یٰۤاَیُّہَا النَّاسُ عُلِّمۡنَا مَنۡطِقَ الطَّیۡرِ وَ اُوۡتِیۡنَا مِنۡ کُلِّ شَیۡءٍ ؕ اِنَّ ہٰذَا لَہُوَ الۡفَضۡلُ  الۡمُبِیۡنُ ﴿۱۶﴾', 'اور سلیمان داؤد کے قائم مقام ہوئے۔ اور کہنے لگے کہ لوگو ہمیں اللہ کی طرف سے پرندوں کی بولی سکھائی گئ ہے اور ہر چیز عنایت فرمائی گئ ہے۔ بیشک یہ اس کا خاص فضل ہے۔', 'اور قائم مقام ہوا سلیمان داؤد کا [۱۸] اور بولے اے لوگو  ہم کو سکھائی ہے بولی اڑتے جانوروں کی [۱۹] اور دیا ہم کو ہر چیز میں سے [۲۰] بیشک یہی ہے فضیلت صریح', 'And Sulaiman (Solomon) inherited (the knowledge of) Dawood (David). He said: \"O mankind! We have been taught the language of birds, and on us have been bestowed all things. This, verily, is an evident grace (from Allah).\"', 'And Sulaimān inherited (the traits of) Dāwūd and said, “O people we have been taught the speech of birds, and all sorts of things are given to us. Indeed, this is the evident grace (of Allah).”'),
(3176, 27, 17, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَ حُشِرَ لِسُلَیۡمٰنَ جُنُوۡدُہٗ  مِنَ الۡجِنِّ وَ الۡاِنۡسِ  وَ الطَّیۡرِ  فَہُمۡ  یُوۡزَعُوۡنَ ﴿۱۷﴾', 'اور سلیمان کے لئے جنوں اور انسانوں اور پرندوں کے لشکر جمع کئے گئے اور پھر انکی جماعتیں بنائی گئیں۔', 'اور جمع کئے گئے سلیمان کے پاس اسکے لشکر جن اور انسان اور اڑتے جانور پھر انکی جماعتیں بنائی [۲۱]', 'And there were gathered before Sulaiman (Solomon) his hosts of jinns and men, and birds, and they all were set in battle order (marching forwards).', 'And mustered for Sulaimān were his forces from among the Jinns and the humans and the birds. So all of them were kept under (his) control,'),
(3177, 27, 18, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'حَتّٰۤی  اِذَاۤ  اَتَوۡا عَلٰی وَادِ  النَّمۡلِ ۙ قَالَتۡ نَمۡلَۃٌ  یّٰۤاَیُّہَا النَّمۡلُ ادۡخُلُوۡا مَسٰکِنَکُمۡ ۚ لَا یَحۡطِمَنَّکُمۡ  سُلَیۡمٰنُ  وَ جُنُوۡدُہٗ ۙ وَ ہُمۡ  لَا یَشۡعُرُوۡنَ ﴿۱۸﴾', 'یہاں تک کہ جب چیونٹیوں کے میدان میں پہنچے تو ایک چیونٹی نے کہا کہ چیونٹیو اپنے اپنے بلوں میں داخل ہو جاؤ ایسا نہ ہو کہ سلمیان اور اسکے لشکر تمکو کچل ڈالیں اور انکو خبر بھی نہ ہو۔', 'یہاں تک کہ جب پہنچے چیونٹیوں کے میدان پر [۲۲] کہا ایک چیونٹی نے اے چیونٹیو گھس جاؤ اپنے گھروں میں نہ پیس ڈالے تم کو سلیمان اور اسکی فوجیں اور انکو خبر بھی نہ ہو [۲۳]', 'Till, when they came to the valley of the ants, one of the ants said: \"O ants! Enter your dwellings, lest Sulaiman (Solomon) and his hosts crush you, while they perceive not.\"', 'until when they reached the valley of the ants, one of the ants said, “O ants, enter your dwelling places, lest Sulaimān and his armies crush you unknowingly.”'),
(3178, 27, 19, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'فَتَبَسَّمَ ضَاحِکًا مِّنۡ قَوۡلِہَا وَ قَالَ رَبِّ اَوۡزِعۡنِیۡۤ  اَنۡ اَشۡکُرَ  نِعۡمَتَکَ الَّتِیۡۤ اَنۡعَمۡتَ عَلَیَّ وَ عَلٰی وَالِدَیَّ وَ اَنۡ اَعۡمَلَ صَالِحًا تَرۡضٰىہُ وَ اَدۡخِلۡنِیۡ بِرَحۡمَتِکَ فِیۡ عِبَادِکَ الصّٰلِحِیۡنَ ﴿۱۹﴾', 'تو وہ اسکی بات سے ہنس پڑے اور کہنے لگے کہ اے پروردگار مجھے توفیق عنایت کر کہ جو احسان تو نے مجھ پر اور میرے ماں باپ پر کئے ہیں ان کا شکر کروں اور ایسے نیک کام کروں کہ تو ان سے خوش ہو جائے اور مجھے اپنی رحمت سے اپنے نیک بندوں میں داخل فرما۔', 'پھر مسکرا کر ہنس پڑا اسکی بات سے [۲۴] اور بولا اے میرے رب میری قسمت میں دےکہ شکر کروں تیرے احسان کا جو تو نے کیا مجھ پر اور میرے ماں باپ پر اور یہ کہ کروں کام نیک جو تو پسند کرے اور ملا لے مجھ کو اپنی رحمت سے اپنے نیک بندوں میں [۲۵]', 'So he (Sulaiman (Solomon)) smiled, amused at her speech and said: \"My Lord! Inspire and bestow upon me the power and ability that I may be grateful for Your Favours which You have bestowed on me and on my parents, and that I may do righteous good deeds that will please You, and admit me by Your Mercy among Your righteous slaves.\"', 'So he (Sulaimān) smiled, laughing on her speech and said, “My Lord, enable me to become grateful to Your favor that you have bestowed on me and on my parents, and to do good deeds that You like, and admit me, with Your mercy, among Your righteous servants.”'),
(3179, 27, 20, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَ تَفَقَّدَ الطَّیۡرَ فَقَالَ مَا لِیَ  لَاۤ  اَرَی الۡہُدۡہُدَ ۫ۖ اَمۡ کَانَ مِنَ الۡغَآئِبِیۡنَ ﴿۲۰﴾', 'اور جب انہوں نے پرندوں کا جائزہ لیا تو کہنے لگے کیا سبب ہے مجھے ہد ہد نظر نہیں آتا کیا کہیں غائب ہو گیا ہے؟', 'اور خبر لی اڑتے جانوروں کی تو کہا کیا ہے جو میں نہیں دیکھتا ہد ہد کو یا ہے وہ غائب [۲۶]', 'He inspected the birds, and said: \"What is the matter that I see not the hoopoe? Or is he among the absentees?', 'And (once) he (Sulaimān) checked the birds and said, “How is it with me that I do not see the hudhud (hoopoe)? Rather he has disappeared.'),
(3180, 27, 21, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'لَاُعَذِّبَنَّہٗ  عَذَابًا شَدِیۡدًا  اَوۡ لَاَاذۡبَحَنَّہٗۤ اَوۡ لَیَاۡتِیَنِّیۡ بِسُلۡطٰنٍ مُّبِیۡنٍ ﴿۲۱﴾', 'میں اسے سخت سزا دوں گا یا ذبح کر ڈالوں گا یا میرے سامنے اپنی بے قصوری کی واضح دلیل  پیش کرے۔', 'اس کو سزا دوں گا سخت سزا [۲۷] یا ذبح کر ڈالوں گا یا لائے میرے پاس کوئی سند صریح [۲۸]', '\"I will surely punish him with a severe torment, or slaughter him, unless he brings me a clear reason.\"', 'I will punish him with a severe punishment or slaughter him unless he brings to me a clear plea.”'),
(3181, 27, 22, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'فَمَکَثَ غَیۡرَ بَعِیۡدٍ فَقَالَ اَحَطۡتُّ بِمَا لَمۡ تُحِطۡ بِہٖ وَ جِئۡتُکَ مِنۡ سَبَاٍۭ بِنَبَاٍ یَّقِیۡنٍ ﴿۲۲﴾', 'ابھی تھوڑی ہی دیر ہوئی تھی کہ ہد ہد آ موجود ہوا اور کہنے لگا کہ مجھے ایک ایسی چیز معلوم ہوئی ہے جسکی آپکو خبر نہیں اور میں آپ کے پاس ملک سبا سے ایک یقینی خبر لے کر آیا ہوں۔', 'پھر بہت دیر نہ کی کہ آ کر کہا میں لے آیا خبر ایک چیز کی کہ تجھ کو اس کی خبر نہ تھی اور آیا ہوں تیرے پاس سبا سے ایک خبر لیکر تحقیقی [۲۹]', 'But the hoopoe stayed not long, he (came up and) said: \"I have grasped (the knowledge of a thing) which you have not grasped and I have come to you from Saba (Sheba) with true news.', 'Then the hoopoe did not take long and said (to Sulaimān), “I have discovered what you did not, and have brought to you a sure information from Saba’ (Sheba).'),
(3182, 27, 23, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'اِنِّیۡ وَجَدۡتُّ امۡرَاَۃً  تَمۡلِکُہُمۡ وَ اُوۡتِیَتۡ مِنۡ کُلِّ شَیۡءٍ وَّ لَہَا عَرۡشٌ عَظِیۡمٌ ﴿۲۳﴾', 'میں نے ایک عورت دیکھی کہ ان لوگوں پر حکومت کرتی ہے اور ہر چیز اسے میسر ہے اور اس کا ایک شاندار تخت ہے۔', 'میں نے پایا ایک عورت کو جو ان پر بادشاہی کرتی ہے اور اسکو ہر ایک چیز ملی ہے [۳۰] اور اس کا ایک تخت ہے بڑا [۳۱]', '\"I found a woman ruling over them, and she has been given all things that could be possessed by any ruler of the earth, and she has a great throne.', 'I have found a woman ruling over them, and all sorts of things are given to her, and she has a great throne.'),
(3183, 27, 24, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَجَدۡتُّہَا وَ قَوۡمَہَا یَسۡجُدُوۡنَ لِلشَّمۡسِ مِنۡ  دُوۡنِ اللّٰہِ  وَ زَیَّنَ لَہُمُ الشَّیۡطٰنُ  اَعۡمَالَہُمۡ فَصَدَّہُمۡ عَنِ السَّبِیۡلِ  فَہُمۡ   لَا  یَہۡتَدُوۡنَ ﴿ۙ۲۴﴾', 'میں نے دیکھا کہ وہ اور اسکی قوم اللہ کو چھوڑ کر آفتاب کو سجدہ کرتے ہیں اور شیطان نے انکے اعمال انہیں آراستہ کر دکھائے ہیں اور انکو رستے سے روک رکھا ہے پس وہ رستے پر نہیں آتے۔', 'میں نے پایا کہ وہ اور اسکی قوم سجدہ کرتے ہیں سورج کو اللہ کے سوائے اور بھلے دکھلا رکھے ہیں ان کو شیطان نے انکے کام پھر روک دیا ہے انکو رستہ سے سو وہ راہ نہیں پاتے [۳۲]', '\"I found her and her people worshipping the sun instead of Allah, and Shaitan (Satan) has made their deeds fair-seeming to them, and has barred them from (Allahs) Way, so they have no guidance,\"', 'I have found her and her people prostrating themselves to the sun, instead of Allah, and the Satan has beautified their deeds for them, and has prevented them from the way, so they do not take the right path,'),
(3184, 27, 25, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'اَلَّا یَسۡجُدُوۡا  لِلّٰہِ الَّذِیۡ یُخۡرِجُ الۡخَبۡءَ فِی السَّمٰوٰتِ وَ الۡاَرۡضِ وَ یَعۡلَمُ مَا تُخۡفُوۡنَ  وَ مَا  تُعۡلِنُوۡنَ ﴿۲۵﴾', 'اور نہیں سمجھتے ہیں کہ اللہ کو جو آسمانوں اور زمین میں چھپی چیزوں کو ظاہر کر دیتا اور تمہارے پوشیدہ اور ظاہر اعمال کو جانتا ہے کیوں سجدہ نہ کریں۔', 'کیوں نہ سجدہ کریں اللہ کو جو نکالتا ہے چھپی ہوئی چیز آسمانوں میں اور زمین میں اور جانتا ہے جو چھپاتے ہو اور جو ظاہر کرتے ہو [۳۳]', 'Al-La (this word has two interpretations) (A) (As Shaitan (Satan) has barred them from Allahs Way) so that they do not worship (prostrate before) Allah, or (B) So that they may worship (prostrate before) Allah, Who brings to light what is hidden in the heavens and the earth, and knows what you conceal and what you reveal. (Tafsir At-Tabaree, Vol. 19, Page 149)', 'that is, they do not prostrate to Allah who brings forth what is hidden in the heavens and the earth,-and who knows whatever you conceal and whatever you reveal.”'),
(3185, 27, 26, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'اَللّٰہُ  لَاۤ  اِلٰہَ  اِلَّا ہُوَ   رَبُّ الۡعَرۡشِ الۡعَظِیۡمِ ﴿ٛ۲۶﴾', 'اللہ کے سوا کوئی عبادت کے لائق نہیں وہی عرش عظیم کا مالک ہے۔', 'اللہ ہے کسی کی بندگی نہیں اس کے سوائے پروردگار تخت بڑے کا [۳۴]', 'Allah, La ilaha illa Huwa (none has the right to be worshipped but He), the Lord of the Supreme Throne!', 'Allah! There is no god but He, the Lord of the Great Throne.'),
(3186, 27, 27, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'قَالَ سَنَنۡظُرُ اَصَدَقۡتَ اَمۡ  کُنۡتَ مِنَ الۡکٰذِبِیۡنَ ﴿۲۷﴾', 'سلیمان نے کہا اچھا ہم دیکھیں گے تو نے سچ کہا ہے یا تو جھوٹا ہے۔', 'سلیمان نے کہا ہم اب دیکھتے ہیں تو نے سچ کہا یا تو جھوٹا ہے [۳۵]', '(Sulaiman (Solomon)) said: \"We shall see whether you speak the truth or you are (one) of the liars.', 'He (Sulaimān) said, “We shall see whether you have told the truth or you are one of the liars.'),
(3187, 27, 28, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'اِذۡہَبۡ بِّکِتٰبِیۡ ہٰذَا فَاَلۡقِہۡ  اِلَیۡہِمۡ ثُمَّ تَوَلَّ عَنۡہُمۡ فَانۡظُرۡ  مَا ذَا یَرۡجِعُوۡنَ ﴿۲۸﴾', 'یہ میرا خط لے جا اور اسے انکی طرف ڈال دے پھر انکے پاس سے ہٹ جانا اور دیکھنا کہ وہ کیا جواب دیتے ہیں۔', 'لیجا میرا یہ خط اور ڈال دے ان کی طرف پھر ان کے پاس سے ہٹ آ پھر دیکھ وہ کیا جواب دیتے ہیں [۳۶]', '\"Go you with this letter of mine, and deliver it to them, then draw back from them, and see what (answer) they return.\"', 'Go with this letter of mine, and deliver it down to them, then turn back from them, and see how they react.”'),
(3188, 27, 29, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'قَالَتۡ یٰۤاَیُّہَا الۡمَلَؤُا  اِنِّیۡۤ   اُلۡقِیَ   اِلَیَّ  کِتٰبٌ کَرِیۡمٌ ﴿۲۹﴾', 'ملکہ نے کہا کہ دربار والو مجھ تک ایک نامہ گرامی پہنچایا گیا ہے۔', 'کہنے لگی اے دربار والو میرے پاس ڈالا گیا ایک خط عزت کا', 'She said: \"O chiefs! Verily! Here is delivered to me a noble letter,', 'She (the queen) said (to her officials after receiving the letter), “O chieftains, there has been delivered to me an esteemed letter.'),
(3189, 27, 30, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'اِنَّہٗ مِنۡ سُلَیۡمٰنَ وَ اِنَّہٗ بِسۡمِ اللّٰہِ   الرَّحۡمٰنِ الرَّحِیۡمِ ﴿ۙ۳۰﴾', 'وہ سلیمان کی طرف سے ہے اور مضمون یہ ہے کہ شروع اللہ کا نام لے کر جو بڑا مہربان نہایت رحم والا ہے۔', 'وہ خط ہے سلیمان کی طرف سے [۳۷] اور وہ یہ ہے شروع اللہ کے نام سے جو بیحد مہربان نہایت رحم والا ہے', '\"Verily! It is from Sulaiman (Solomon), and verily! It (reads): In the Name of Allah, the Most Beneficent, the Most Merciful;', 'It is from Sulaimān, and it is (in the following words :) With the name of Allah, the All-Merciful, the Very-Merciful.'),
(3190, 27, 31, 2, 17, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'اَلَّا تَعۡلُوۡا عَلَیَّ  وَ اۡتُوۡنِیۡ  مُسۡلِمِیۡنَ ﴿٪۳۱﴾', 'بعد اسکے یہ کہ مجھ سے سرکشی نہ کرو اور مطیع و فرمانبردار ہو کر میرے پاس چلے آؤ۔', 'کہ زور نہ کرو میرے مقابلہ میں اور چلے آؤ میرے سامنے حکمبردار ہو کر [۳۸]', '\"Be you not exalted against me, but come to me as Muslims (true believers who submit to Allah with full submission) \"', 'Do not rebel against me, and come to me in submission.”'),
(3191, 27, 32, 3, 18, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'قَالَتۡ یٰۤاَیُّہَا الۡمَلَؤُا  اَفۡتُوۡنِیۡ  فِیۡۤ   اَمۡرِیۡ ۚ مَا کُنۡتُ قَاطِعَۃً  اَمۡرًا حَتّٰی تَشۡہَدُوۡنِ ﴿۳۲﴾', 'خط سنا کر کہنے لگی کہ کے اے اہل دربار میرے اس معاملے میں مجھے مشورہ دو جب تک کہ تم حاضر نہ ہو اور صلاح نہ دو میں کسی کام کا فیصلہ نہیں کیا کرتی۔', 'کہنے لگی اے دربار والو مشورہ دو مجھ کو میرے کام میں میں طے نہیں کرتی کوئی کام تمہارے حاضر ہونے تک [۳۹]', 'She said: \"O chiefs! Advise me in (this) case of mine. I decide no case till you are present with me.\"', 'She said, “O chieftains, advise me in the matter I have (before me). I am not the one who decides a matter absolutely unless you are present with me.”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(3192, 27, 33, 3, 18, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'قَالُوۡا نَحۡنُ اُولُوۡا قُوَّۃٍ  وَّ اُولُوۡا بَاۡسٍ شَدِیۡدٍ ۬ۙ وَّ الۡاَمۡرُ  اِلَیۡکِ فَانۡظُرِیۡ مَاذَا تَاۡمُرِیۡنَ ﴿۳۳﴾', 'وہ بولے کہ ہم بڑے زورآور اور سخت جنگجو ہیں اور حکم آپ کے اختیار میں ہے تو جو حکم دیجئے گا اسکے انجام پر نظر کر لیجئے گا۔', 'وہ بولے ہم لوگ زور آور ہیں اور سخت لڑائی والے اور کام تیرے اختیار میں ہے سو تو دیکھ لے جو حکم کرے [۴۰]', 'They said: \"We have great strength, and great ability for war, but it is for you to command; so think over what you will command.\"', 'They said, “We are powerful and tough fighters, and the decision lies with you; so consider what command you should give.”'),
(3193, 27, 34, 3, 18, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'قَالَتۡ اِنَّ  الۡمُلُوۡکَ اِذَا دَخَلُوۡا قَرۡیَۃً اَفۡسَدُوۡہَا وَ جَعَلُوۡۤا اَعِزَّۃَ  اَہۡلِہَاۤ  اَذِلَّۃً ۚ وَ کَذٰلِکَ  یَفۡعَلُوۡنَ ﴿۳۴﴾', 'اس نے کہا کہ بادشاہ جب کسی شہر میں داخل ہوتے ہیں تو اسکو تباہ کر دیتے ہیں اور وہاں کے عزت والوں کو ذلیل کر دیا کرتے ہیں اور اسی طرح یہ بھی کریں گے۔', 'کہنے لگی بادشاہ جب گھستے ہیں کسی بستی میں اسکو خراب کر دیتے ہیں اور کر ڈالتے ہیں وہاں کے سرداروں کو بے عزت اور ایسا ہی کچھ کریں گے', 'She said: \"Verily! Kings, when they enter a town (country), they despoil it, and make the most honourable amongst its people low. And thus they do.', 'She said, “In fact when the kings enter a town, they put it to disorder, and put its honorable citizens to disgrace, and this is how they normally do.'),
(3194, 27, 35, 3, 18, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَ اِنِّیۡ مُرۡسِلَۃٌ  اِلَیۡہِمۡ بِہَدِیَّۃٍ  فَنٰظِرَۃٌۢ بِمَ  یَرۡجِعُ  الۡمُرۡسَلُوۡنَ ﴿۳۵﴾', 'اور میں انکی طرف کچھ تحفہ بھیجتی ہوں اور دیکھتی ہوں کہ قاصد کیا جواب لاتے ہیں۔', 'اور میں بھیجتی ہوں ان کی طرف کچھ تحفہ پھر دیکھتی ہوں کیا جواب لیکر پھرتے ہیں بھیجے ہوئے [۴۱]', '\"But verily! I am going to send him a present, and see with what (answer) the messengers return.\"', 'And I am going to send a gift to them, then see, what response the envoys will bring back.”'),
(3195, 27, 36, 3, 18, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'فَلَمَّا جَآءَ سُلَیۡمٰنَ قَالَ  اَتُمِدُّوۡنَنِ بِمَالٍ  ۫ فَمَاۤ  اٰتٰىنَِۧ اللّٰہُ خَیۡرٌ  مِّمَّاۤ   اٰتٰىکُمۡ  ۚ بَلۡ  اَنۡتُمۡ  بِہَدِیَّتِکُمۡ  تَفۡرَحُوۡنَ ﴿۳۶﴾', 'پس جب قاصد سلیمان کے پاس پہنچا تو سلیمان نے کہا کیا تم مجھے مال سے مدد دینا چاہتے ہو سو جو کچھ اللہ نے مجھے عطا فرمایا ہے وہ اس سے کہیں بہتر ہے جو تمہیں دیا ہے حقیقت یہ ہے کہ اپنے تحفے سے تم ہی خوش ہوتے ہو گے۔', 'پھر جب پہنچا سلیمان کے پاس بولا کیا تم میری اعانت کرتے ہو مال سے جو اللہ نے مجھ کو دیا ہے بہتر ہے اس سے جو تم کو دیا ہے بلکہ تم ہی اپنے تحفہ سے خوش رہو [۴۲]', 'So when (the messengers with the present) came to Sulaiman (Solomon), he said: \"Will you help me in wealth? What Allah has given me is better than that which He has given you! Nay, you rejoice in your gift!\"', 'So when he (the envoy) came to Sulaimān, he said, “Are you extending a financial aid to me? So what Allah has given me is much better than what He has given to you. But you yourselves are proud of your gift.'),
(3196, 27, 37, 3, 18, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'اِرۡجِعۡ  اِلَیۡہِمۡ فَلَنَاۡتِیَنَّہُمۡ بِجُنُوۡدٍ لَّا قِبَلَ لَہُمۡ بِہَا وَ لَنُخۡرِجَنَّہُمۡ مِّنۡہَاۤ  اَذِلَّۃً  وَّ  ہُمۡ  صٰغِرُوۡنَ ﴿۳۷﴾', 'انکے پاس واپس جاؤ اب ہم ان پر ایسے لشکر لے کر حملہ کریں گے جنکے مقابلے کی ان میں طاقت نہ ہو گی اور انکو وہاں سے بےعزت کر کے نکال دیں گے اور وہ ذلیل ہوں گے۔', 'پھر جا ان کے پاس اب ہم پہنچتے ہیں ان پر ساتھ لشکروں کے جنکا مقابلہ نہ ہو سکے ان سے اور نکال دیں گے ان کو وہاں سے بےعزت کر کر اور وہ خوار ہوں گے [۴۳]', '(Then Sulaiman (Solomon) said to the chief of her messengers who brought the present): \"Go back to them. We verily shall come to them with hosts that they cannot resist, and we shall drive them out from there in disgrace, and they will be abased.\"', 'Go back to them, and we will bring to them forces they have no power to face, and we will certainly drive them out from there in humiliation while they are disgraced.”'),
(3197, 27, 38, 3, 18, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'قَالَ یٰۤاَیُّہَا الۡمَلَؤُا اَیُّکُمۡ یَاۡتِیۡنِیۡ بِعَرۡشِہَا قَبۡلَ  اَنۡ یَّاۡتُوۡنِیۡ مُسۡلِمِیۡنَ ﴿۳۸﴾', 'سلیمان نے کہا کہ اے دربار والو کوئی تم میں ایسا ہے کہ قبل اس کے کہ وہ لوگ فرمانبردار ہو کر ہمارے پاس آئیں ملکہ کا تخت میرے پاس لے آئے۔', 'بولا اے دربار والو تم میں کوئی ہے کہ لے آوے میرے پاس اس کا تخت پہلے اس سے کہ وہ آئیں میرے پاس حکم بردار ہو کر [۴۴]', 'He said: \"O chiefs! Which of you can bring me her throne before they come to me surrendering themselves in obedience?\"', 'He said, “O chieftains, which one of you will bring her throne to me before they come to me submissively?”'),
(3198, 27, 39, 3, 18, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'قَالَ عِفۡرِیۡتٌ مِّنَ الۡجِنِّ اَنَا اٰتِیۡکَ بِہٖ قَبۡلَ  اَنۡ  تَقُوۡمَ مِنۡ مَّقَامِکَ ۚ وَ اِنِّیۡ عَلَیۡہِ  لَقَوِیٌّ  اَمِیۡنٌ ﴿۳۹﴾', 'جنات میں سے ایک قوی ہیکل جن نے کہا کہ قبل اسکے کہ آپ اپنی جگہ سے اٹھیں میں اسکو آپ کے پاس لا حاضر کرتا ہوں اور مجھے اس پر قدرت بھی حاصل ہے اور امانتدار بھی ہوں۔', 'بولا ایک دیو جنوں میں سے میں لائے دیتا ہوں وہ تجھکو  پہلے اس سے کہ تو اٹھے اپنی جگہ سے [۴۵] اور میں اس پر زورآور ہوں معتبر [۴۶]', 'An Ifreet (strong) from the jinns said: \"I will bring it to you before you rise from your place (council). And verily, I am indeed strong, and trustworthy for such work.\"', 'A stalwart of the Jinn said, “I will bring it to you before you rise up from your place, and for this (task) I am powerful, reliable.”'),
(3199, 27, 40, 3, 18, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'قَالَ الَّذِیۡ عِنۡدَہٗ  عِلۡمٌ  مِّنَ  الۡکِتٰبِ اَنَا اٰتِیۡکَ بِہٖ قَبۡلَ  اَنۡ یَّرۡتَدَّ اِلَیۡکَ طَرۡفُکَ ؕ فَلَمَّا رَاٰہُ  مُسۡتَقِرًّا عِنۡدَہٗ  قَالَ ہٰذَا مِنۡ فَضۡلِ رَبِّیۡ ۟ۖ لِیَبۡلُوَنِیۡۤ  ءَاَشۡکُرُ اَمۡ  اَکۡفُرُ ؕ وَ مَنۡ شَکَرَ فَاِنَّمَا یَشۡکُرُ  لِنَفۡسِہٖ ۚ وَ مَنۡ  کَفَرَ  فَاِنَّ رَبِّیۡ غَنِیٌّ  کَرِیۡمٌ ﴿۴۰﴾', 'ایک شخص جسکو کتاب الہٰی کا علم تھا کہنے لگا کہ میں آپکی آنکھ کے جھپکنے سے پہلے پہلے اسے آپ کے پاس حاضر کئے دیتا ہوں۔ جب سلیمان نے تخت کو اپنے پاس رکھا ہوا دیکھا تو کہا کہ یہ میرے پروردگار کا فضل ہے تاکہ مجھے آزمائے کہ میں شکر کرتا ہوں یا کفران نعمت کرتا ہوں اور جو شکر کرتا ہے تو اپنے ہی فائدے کے لئے شکر کرتا ہے اور جو ناشکری کرتا ہے تو میرا پروردگار بے نیاز ہے کرم کرنے والا ہے۔', 'بولا وہ شخص جس کے پاس تھا ایک علم کتاب کا میں لائے دیتا ہوں تیرے پاس اسکو پہلے اس سے کہ پھر آئے تیری طرف تیری آنکھ [۴۷] پھر جب دیکھا اسکو دھرا ہوا اپنے پاس کہا یہ میرے رب کا فضل ہے [۴۸] میرے جانچنے کو کہ میں شکر کرتا ہوں یا ناشکری [۴۹] اور جو کوئی شکر کرے سو شکر کرے اپنے واسطے اور جو کوئی ناشکری کرے سو میرا رب بے پروا ہے کرم والا [۵۰]', 'One with whom was knowledge of the Scripture said: \"I will bring it to you within the twinkling of an eye!\" then when (Sulaiman (Solomon)) saw it placed before him, he said: \"This is by the Grace of my Lord to test me whether I am grateful or ungrateful! And whoever is grateful, truly, his gratitude is for (the good of) his ownself, and whoever is ungrateful, (he is ungrateful only for the loss of his ownself). Certainly! My Lord is Rich (Free of all wants), Bountiful.\"', 'Said the one who had the knowledge of the book, “I will bring it to you before your glance returns to you.” So when he saw it (the throne) well placed before him, he said, “This is by the grace of my Lord, so that He may test me whether I am grateful or ungrateful. Whoever is grateful is grateful for his own benefit, and whoever is ungrateful, then my Lord is Need-Free, Bountiful”.'),
(3200, 27, 41, 3, 18, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'قَالَ نَکِّرُوۡا  لَہَا عَرۡشَہَا نَنۡظُرۡ اَتَہۡتَدِیۡۤ  اَمۡ تَکُوۡنُ مِنَ الَّذِیۡنَ لَا یَہۡتَدُوۡنَ ﴿۴۱﴾', 'سلیمان نے کہا کہ ملکہ کے امتحان عقل کے لئے اسکے تخت کی صورت بدل دو دیکھیں کہ وہ سوجھ رکھتی ہے یا ان لوگوں میں سے ہے جو سوجھ نہیں رکھتے۔', 'کہا روپ بدل دکھلاؤ اس عورت کے آگے اسکے تخت کا سمجھ پاتی ہے یا ان لوگوں میں ہوتی ہے جن کو سمجھ نہیں [۵۱]', 'He said: \"Disguise her throne for her that we may see whether she will be guided (to recognise her throne), or she will be one of those not guided.\"', 'He said, “Disguise the throne for her, and we will see whether she discovers the truth, or she does not recognize it.”'),
(3201, 27, 42, 3, 18, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'فَلَمَّا جَآءَتۡ قِیۡلَ  اَہٰکَذَا عَرۡشُکِ ؕ قَالَتۡ کَاَنَّہٗ ہُوَ ۚ وَ اُوۡتِیۡنَا الۡعِلۡمَ  مِنۡ قَبۡلِہَا  وَ کُنَّا مُسۡلِمِیۡنَ ﴿۴۲﴾', 'پھر جب وہ آ پہنچی تو پوچھا گیا کہ کیا آپ کا تخت بھی اسی طرح کا ہے اس نے کہا کہ یہ تو گویا ہوبہو وہی ہے اور ہمکو اس سے پہلے ہی سلیمان کی عظمت و شان کا علم ہو گیا تھا اور ہم فرمانبردار ہیں۔', 'پھر جب وہ آ پہنچی کسی نے کہا کیا ایسا ہے تیرا تخت بولی گویا یہ وہی ہے [۵۲] اور ہم کو معلوم ہو چکا پہلے سے اور ہم ہو چکے حکم بردار [۵۳]', 'So when she came, it was said (to her): \"Is your throne like this?\" She said: \"(It is) as though it were the very same.\" And (Sulaiman (Solomon) said): \"Knowledge was bestowed on us before her, and we were submitted to Allah (in Islam as Muslims before her).\"', 'So when she came, it was said (to her), “Is your throne like this?” She said, “It seems to be the same. We have been made to recognize the truth even before this, and we have already submitted.”'),
(3202, 27, 43, 3, 18, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَ  صَدَّہَا مَا کَانَتۡ تَّعۡبُدُ مِنۡ دُوۡنِ اللّٰہِ ؕ اِنَّہَا  کَانَتۡ مِنۡ  قَوۡمٍ  کٰفِرِیۡنَ ﴿۴۳﴾', 'اور وہ جو اللہ کے سوا دوسروں کی پرستش کرتی تھی سلیمان نے اسکو اس سے منع کیا کہ وہ کافروں میں سے تھی۔', 'اور روک دیا اس کو ان چیزوں سے جو پوجتی تھی اللہ کے سوائے البتہ وہ تھی منکر لوگوں میں [۵۴]', 'And that which she used to worship besides Allah has prevented her (from Islam), for she was of a disbelieving people.', 'And she was prevented (from submitting before this) by that which she used to worship instead of Allah. Indeed she was from a disbelieving people.'),
(3203, 27, 44, 3, 18, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'قِیۡلَ  لَہَا ادۡخُلِی الصَّرۡحَ ۚ فَلَمَّا رَاَتۡہُ حَسِبَتۡہُ  لُجَّۃً  وَّ کَشَفَتۡ عَنۡ سَاقَیۡہَا ؕ قَالَ  اِنَّہٗ  صَرۡحٌ مُّمَرَّدٌ مِّنۡ قَوَارِیۡرَ ۬ؕ قَالَتۡ رَبِّ  اِنِّیۡ ظَلَمۡتُ نَفۡسِیۡ وَ اَسۡلَمۡتُ مَعَ سُلَیۡمٰنَ لِلّٰہِ رَبِّ الۡعٰلَمِیۡنَ ﴿٪۴۴﴾', 'اسکے بعد اس سے کہا گیا کہ محل میں چلئے۔ جب اس نے اسکے فرش کو دیکھا تو اسے پانی کا حوض سمجھا اور کپڑا اٹھا کر اپنی پنڈلیاں کھول دیں سلیمان نے کہا یہ ایسا محل ہے جس کے نیچے بھی شیشے جڑے ہوئے ہیں وہ بول اٹھی کہ پروردگار میں اپنے آپ پر ظلم کرتی رہی تھی اور اب میں سلیمان کے ساتھ اللہ رب العالمین پر ایمان لاتی ہوں۔', 'کسی نے کہا اس عورت کو اندر چل محل میں پھر جب دیکھا اسکو خیال کیا کہ  وہ پانی ہے گہرا اور کھولیں اپنی پنڈلیاں [۵۵] کہا یہ تو ایک محل ہے جڑے ہوئے ہیں اس میں شیشے [۵۶] بولی اے رب میں نے برا کیا ہے اپنی جان کا اور میں حکم بردار ہوئی ساتھ سلیمان کے اللہ کے آگے جو رب ہے سارے جہان کا [۵۷]', 'It was said to her: \"Enter As-Sarh\" ((a glass surface with water underneath it) or a palace), but when she saw it, she thought it was a pool, and she (tucked up her clothes) uncovering her legs, Sulaiman (Solomon) said: \"Verily, it is Sarh ((a glass surface with water underneath it) or a palace) paved smooth with slab of glass.\" She said: \"My Lord! Verily, I have wronged myself, and I submit (in Islam, together with Sulaiman (Solomon), to Allah, the Lord of the Alameen (mankind, jinns and all that exists).\"', 'It was said to her, “Enter the palace.” Then once she saw it, she thought it was flowing water, and uncovered her legs. He (Sulaimān) said, “This is a palace made of glasses.” She said, “My Lord, I had surely wronged myself, and now I submit, along with Sulaimān, to Allah, the Lord of all the worlds.”'),
(3204, 27, 45, 4, 19, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَ لَقَدۡ اَرۡسَلۡنَاۤ  اِلٰی ثَمُوۡدَ  اَخَاہُمۡ  صٰلِحًا اَنِ اعۡبُدُوا اللّٰہَ  فَاِذَا ہُمۡ فَرِیۡقٰنِ یَخۡتَصِمُوۡنَ ﴿۴۵﴾', 'اور ہم نے ثمود کی طرف انکے بھائی صالح کو بھیجا کہ اللہ کی عبادت کرو تو وہ دو فریق ہو کر آپس میں جھگڑنے لگے۔', 'اور ہم نے بھیجا تھا ثمود کی طرف ان کے بھائی صالح کو کہ بندگی کرو اللہ کی پھر وہ تو دو فرقے ہو کر لگے جھگڑنے [۵۸]', 'And indeed We sent to Thamood their brother Salih (Saleh), saying: \"Worship Allah (Alone and none else). Then look! They became two parties (believers and disbelievers) quarreling with each other.\"', 'And We sent to Thamūd their brother SāliH saying (to them), “Worship Allah”. Then suddenly they became two groups quarrelling with each other.'),
(3205, 27, 46, 4, 19, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'قَالَ یٰقَوۡمِ لِمَ تَسۡتَعۡجِلُوۡنَ بِالسَّیِّئَۃِ قَبۡلَ الۡحَسَنَۃِ ۚ لَوۡ لَا تَسۡتَغۡفِرُوۡنَ اللّٰہَ لَعَلَّکُمۡ تُرۡحَمُوۡنَ ﴿۴۶﴾', 'صالح نے کہا کہ اے قوم! تم بھلائی سے پہلے برائی کے لئے کیوں جلدی کرتے ہو اور اللہ سے بخشش کیوں نہیں مانگتے تاکہ تم پر رحم کیا جائے۔', 'کہا اے میری قوم کیوں جلدی مانگتے ہو  برائی کو پہلے بھلائی سے کیوں نہیں گناہ بخشواتے اللہ سے شاید تم پر رحم ہو جائے [۵۹]', 'He said: \"O my people! Why do you seek to hasten the evil (torment) before the good (Allahs Mercy)? Why seek you not the Forgiveness of Allah, that you may receive mercy?\"', 'He said, “My people, why do you seek evil to come sooner before good? Why do you not seek forgiveness from Allah, so that you are treated with mercy?”'),
(3206, 27, 47, 4, 19, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'قَالُوا اطَّیَّرۡنَا بِکَ وَ بِمَنۡ مَّعَکَ ؕ قَالَ طٰٓئِرُکُمۡ عِنۡدَ اللّٰہِ  بَلۡ  اَنۡتُمۡ قَوۡمٌ تُفۡتَنُوۡنَ ﴿۴۷﴾', 'وہ کہنے لگے کہ تم اور تمہارے ساتھی ہمارے لئے برا شگون ہیں صالح نے کہا کہ تمہاری بد شگونی اللہ کے پاس ہے بلکہ تم ایسے لوگ ہو جنکی آزمائش کی جاتی ہے۔', 'بولے ہم نے منحوس قدم دیکھا تجھ کو اور تیرے ساتھ والوں کو [۶۰] کہا تمہاری بری قسمت اللہ کے پاس ہے [۶۱] کچھ نہیں تم لوگ جانچے جاتے ہو [۶۲]', 'They said: \"We augur ill omen from you and those with you.\" He said: \"Your ill omen is with Allah; nay, but you are a people that are being tested.\"', 'They said, “We regard you and those with you as a sign of bad omen.” He said, “Your omen is with Allah, but you are a people put to a test.”'),
(3207, 27, 48, 4, 19, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَ کَانَ فِی الۡمَدِیۡنَۃِ  تِسۡعَۃُ  رَہۡطٍ یُّفۡسِدُوۡنَ فِی الۡاَرۡضِ وَ لَا یُصۡلِحُوۡنَ ﴿۴۸﴾', 'اور شہر میں نو شخص تھے جو ملک میں فساد کیا کرتے تھے اور اصلاح سے کام نہیں لیتے تھے۔', 'اور تھے اس شہر میں نو شخص کہ خرابی کرتے ملک میں اور اصلاح نہ کرتے [۶۳]', 'And there were in the city nine men (from the sons of their chiefs), who made mischief in the land, and would not reform.', 'And there were nine persons in the city who used to make mischief on the earth and did not put things right.'),
(3208, 27, 49, 4, 19, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'قَالُوۡا تَقَاسَمُوۡا بِاللّٰہِ لَنُبَیِّتَنَّہٗ وَ اَہۡلَہٗ ثُمَّ لَنَقُوۡلَنَّ لِوَلِیِّہٖ مَا شَہِدۡنَا مَہۡلِکَ  اَہۡلِہٖ  وَ  اِنَّا  لَصٰدِقُوۡنَ ﴿۴۹﴾', 'کہنے لگے کہ اللہ کی قسم کھاؤ کہ ہم رات کو اس پر اور اسکے گھر والوں پر شبخون ماریں گے۔ پھر اسکے وارثوں سے کہدیں گے کہ ہم تو اسکے گھر والوں کے موقع ہلاکت پر تھے ہی نہیں اور ہم سچ کہتے ہیں۔', 'بولے کہ آپس میں قسم کھاؤ اللہ کی کہ البتہ رات کو جا پڑیں ہم اس پر اسکے گھر پر پھر کہدیں گے اسکے دعویٰ کرنے والے کو ہم نے نہیں دیکھا جب تباہ ہوا اس کا گھر اور ہم بیشک سچ کہتے ہیں [۶۴]', 'They said: \"Swear one to another by Allah that we shall make a secret night attack on him and his household, and afterwards we will surely say to his near relatives: We witnessed not the destruction of his household, and verily! We are telling the truth.\"', 'They said, “Let us swear a mutual oath by Allah that we shall attack him (SāliH) and his family at night, then will say to his heir, ‘We did not witness the destruction of his family, and we are really truthful.’”'),
(3209, 27, 50, 4, 19, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَ مَکَرُوۡا مَکۡرًا وَّ  مَکَرۡنَا مَکۡرًا  وَّ ہُمۡ لَا  یَشۡعُرُوۡنَ ﴿۵۰﴾', 'اور وہ ایک چال چلے اور ہم نے بھی ایک تدبیر کی اور انکو کچھ خبر نہ ہوئی۔', 'اور انہوں نے بنایا ایک فریب اور ہم نے بنایا ایک فریب اور انکو خبر نہ ہوئی [۶۵]', 'So they plotted a plot, and We planned a plan, while they perceived not.', 'Thus they devised a plan, and We devised a plan, while they were not aware.'),
(3210, 27, 51, 4, 19, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'فَانۡظُرۡ کَیۡفَ کَانَ عَاقِبَۃُ مَکۡرِہِمۡ ۙ اَنَّا دَمَّرۡنٰہُمۡ  وَ  قَوۡمَہُمۡ  اَجۡمَعِیۡنَ ﴿۵۱﴾', 'تو دیکھ لو کہ انکی چال کا انجام کیسا ہوا ہم نے انکو اور ان کی قوم سب کو ہلاک کر ڈالا۔', 'پھر دیکھ لے کیسا ہوا انجام انکے فریب کا کہ ہلاک کر ڈالا ہم نے انکو اور انکی قوم کو سب کو [۶۶]', 'Then see how was the end of their plot! Verily! We destroyed them and their nation, all together.', 'So, look how was the fate of their plan, that We annihilated them and their people altogether.'),
(3211, 27, 52, 4, 19, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'فَتِلۡکَ بُیُوۡتُہُمۡ خَاوِیَۃًۢ بِمَا ظَلَمُوۡا ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیَۃً   لِّقَوۡمٍ  یَّعۡلَمُوۡنَ ﴿۵۲﴾', 'اب ان کے یہ گھر ان کے ظلم کے سبب تلپٹ پڑے ہیں۔ جو لوگ علم رکھتے ہیں انکے لئے اس میں نشانی ہے۔', 'سو یہ پڑے ہیں ان کے گھر ڈھیر ہوئے بسبب انکے انکار کے [۶۷] البتہ اس میں نشانی ہے ان لوگوں کے لئے جو جانتے ہیں [۶۸]', 'These are their houses in utter ruin, for they did wrong. Verily, in this is indeed an Ayah (a lesson or a sign) for people who know.', 'Now those are their houses, lying empty because of their transgression. Surely, in this there are signs for a people who have knowledge.'),
(3212, 27, 53, 4, 19, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَ اَنۡجَیۡنَا الَّذِیۡنَ اٰمَنُوۡا وَ کَانُوۡا یَتَّقُوۡنَ ﴿۵۳﴾', 'اور جو لوگ ایمان لائے اور ڈرتے تھے ان کو ہم نے نجات دی۔', 'اور بچا دیا ہم نے ان کو جو یقین لائے تھے اور بچتے رہے تھے [۶۹]', 'And We saved those who believed, and used to fear Allah, and keep their duty to Him.', 'And We saved those who believed and who used to be God-fearing.'),
(3213, 27, 54, 4, 19, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَ لُوۡطًا اِذۡ قَالَ لِقَوۡمِہٖۤ  اَتَاۡتُوۡنَ الۡفَاحِشَۃَ  وَ اَنۡتُمۡ  تُبۡصِرُوۡنَ ﴿۵۴﴾', 'اور لوط کو یاد کرو جب انہوں نے اپنی قوم سے کہا کہ تم بےحیائی کے کام کیوں کرتے ہو جبکہ تم دیکھتے ہو۔', 'اور لوط کو جب کہا اس نے اپنی قوم کو کیا تم کرتے ہو بے حیائی اور تم دیکھتے ہو [۷۰]', 'And (remember) Lout (Lot)! When he said to his people . Do you commit AlFahishah (evil, great sin, every kind of unlawful sexual intercourse, sodomy, etc.) while you see (one another doing evil without any screen, etc.)?\"', 'And (We sent) LūT when he said to his people, “Do you commit the shameful act while you can see (its shamefulness)?'),
(3214, 27, 55, 4, 19, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'اَئِنَّکُمۡ لَتَاۡتُوۡنَ الرِّجَالَ شَہۡوَۃً مِّنۡ دُوۡنِ النِّسَآءِ ؕ بَلۡ  اَنۡتُمۡ  قَوۡمٌ  تَجۡہَلُوۡنَ ﴿۵۵﴾', 'کیا تم عورتوں کو چھوڑ کو لذت حاصل کرنے کے لئے مردوں کی طرف مائل ہوتے ہو۔ حقیقت یہ ہے کہ تم احمق لوگ ہو۔', 'کیا تم دوڑتے ہو مردوں پر للچا کر عورتوں کو چھوڑ کر کوئی نہیں تم لوگ بے سمجھ ہو [۷۱]', '\"Do you approach men in your lusts rather than women? Nay, but you are a people who behave senselessly.\"', 'Is it that you really come to men lustfully instead of women? No, you are a people committing acts of ignorance.”'),
(3215, 27, 56, 4, 19, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'فَمَا کَانَ جَوَابَ قَوۡمِہٖۤ  اِلَّاۤ  اَنۡ قَالُوۡۤا اَخۡرِجُوۡۤا اٰلَ لُوۡطٍ مِّنۡ  قَرۡیَتِکُمۡ ۚ  اِنَّہُمۡ اُنَاسٌ  یَّتَطَہَّرُوۡنَ ﴿۵۶﴾', 'تو انکی قوم کے لوگ بولے تو یہ بولے اور اسکے سوا ان کا کچھ جواب نہ تھا کہ لوط کے گھر والوں کو اپنے شہر سے نکال دو یہ لوگ پاک بننا چاہتے ہیں۔', 'پھر اور کچھ جواب نہ تھا اس کی قوم کا مگر  یہی کہ کہتے تھے نکال دو لوط کے گھر کو اپنے شہر سے یہ لوگ ہیں ستھرے رہا چاہتے [۷۲]', 'There was no other answer given by his people except that they said: \"Drive out the family of Lout (Lot) from your city. Verily, these are men who want to be clean and pure!\"', 'So, the answer of his people was not else but that they said, “Expel the family of LūT from your town. They are a people who over-indulge in purity.”'),
(3216, 27, 57, 4, 19, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'فَاَنۡجَیۡنٰہُ وَ اَہۡلَہٗۤ   اِلَّا  امۡرَاَتَہٗ ۫ قَدَّرۡنٰہَا  مِنَ  الۡغٰبِرِیۡنَ ﴿۵۷﴾', 'تو ہم نے انکو اور ان کے گھر والوں کو نجات دی مگر انکی بیوی کہ اسکی نسبت ہم نے مقرر کر رکھا تھا کہ وہ پیچھے رہنے والوں میں ہوگی۔', 'پھر بچا دیا ہم نے اسکو اور اسکے گھر والوں کو [۷۳] مگر اسکی عورت مقرر کر دیا تھا ہم نے اسکو  رہ جانے والوں میں [۷۴]', 'So We saved him and his family, except his wife. We destined her to be of those who remained behind.', 'So, We saved him and his family, except his wife. We destined her to remain among those who stayed behind.'),
(3217, 27, 58, 4, 19, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'وَ اَمۡطَرۡنَا عَلَیۡہِمۡ مَّطَرًا ۚ فَسَآءَ مَطَرُ الۡمُنۡذَرِیۡنَ ﴿٪۵۸﴾', 'اور ہم نے ان پر مینہ برسایا سو جو مینہ ان لوگوں پر برسا جنکو متنبہ کر دیا گیا تھا برا تھا۔', 'اور برسا دیا ہم نے ان پر برساؤ پھر کیا برا برساؤ تھا ان ڈرائے ہوؤں کا [۷۵]', 'And We rained down on them a rain (of stones). So evil was the rain of those who were warned.', 'And We rained on them a rain. So evil was the rain of those who were warned.'),
(3218, 27, 59, 5, 0, 19, 'وَ قَالَ الَّذِیۡنَ ', 'النمل', 'قُلِ الۡحَمۡدُ لِلّٰہِ وَ سَلٰمٌ عَلٰی عِبَادِہِ الَّذِیۡنَ اصۡطَفٰی ؕ آٰللّٰہُ خَیۡرٌ اَمَّا یُشۡرِکُوۡنَ ﴿ؕ۵۹﴾', 'کہدو کہ سب تعریف اللہ ہی کیلئے ہے اور اسکے ان بندوں پر سلام ہے جنکو اس نے منتخب فرمایا۔ بھلا اللہ بہتر ہے یا وہ جنکو یہ اس کا شریک بناتے ہیں۔', 'تو کہہ تعریف ہے اللہ کو اور سلام ہے اس کے بندوں پر جن کو اس نے پسند کیا [۷۶] بھلا اللہ بہتر ہے یا جنکو  وہ شریک کرتے ہیں [۷۷]', 'Say (O Muhammad SAW): \"Praise and thanks be to Allah, and peace be on His slaves whom He has chosen (for His Message)! Is Allah better, or (all) that you ascribe as partners (to Him)?\" (Of course, Allah is Better).', 'Say, “Praise belongs to Allah, and peace be on those of His servants whom He has chosen.” Is Allah better or that which they associate (with Him as His partners)?'),
(3219, 27, 60, 5, 1, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'اَمَّنۡ  خَلَقَ  السَّمٰوٰتِ وَ الۡاَرۡضَ وَ اَنۡزَلَ لَکُمۡ مِّنَ السَّمَآءِ مَآءً ۚ فَاَنۡۢبَتۡنَا بِہٖ حَدَآئِقَ ذَاتَ بَہۡجَۃٍ ۚ مَا کَانَ  لَکُمۡ  اَنۡ تُنۡۢبِتُوۡا  شَجَرَہَا ؕ ءَ اِلٰہٌ  مَّعَ اللّٰہِ ؕ بَلۡ ہُمۡ قَوۡمٌ  یَّعۡدِلُوۡنَ ﴿ؕ۶۰﴾', 'بھلا کس نے آسمانوں اور زمین کو پیدا کیا اور کس نے تمہارے لئے آسمان سے پانی برسایا۔ پھر ہم نے اس سے سر سبز باغ اگائے تمہارا کام تو نہ تھا کہ تم انکے درختوں کو اگاتے تو کیا اللہ کے ساتھ کوئی اور بھی معبود ہے ہرگز نہیں بلکہ یہ لوگ رستے سے الگ ہو رہے ہیں۔', 'بھلا کس نے بنائے آسمان اور زمین اور اتار دیا تمہارے لئے آسمان سے پانی پھر اگائے ہم نے اس سے باغ رونق والے تمہارا کام نہ تھا کہ اگاتے ان کے درخت [۷۸] اب کوئی اور حاکم ہے اللہ کے ساتھ کوئی نہیں وہ لوگ راہ سے مڑتے ہیں [۷۹]', 'Is not He (better than your gods) Who created the heavens and the earth, and sends down for you water (rain) from the sky, whereby We cause to grow wonderful gardens full of beauty and delight? It is not in your ability to cause the growth of their trees. Is there any ilah (god) with Allah? Nay, but they are a people who ascribe equals (to Him)!', 'Or the One who created the heavens and the earth and sent down for you water from the sky? Then We caused to grow with it gardens, full of glamour. It was not within your ability to grow their trees. Is there any god along with Allah? No, but they are a people who equate (others with Allah).'),
(3220, 27, 61, 5, 1, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'اَمَّنۡ جَعَلَ الۡاَرۡضَ قَرَارًا وَّ جَعَلَ خِلٰلَہَاۤ  اَنۡہٰرًا وَّ جَعَلَ  لَہَا رَوَاسِیَ وَ جَعَلَ بَیۡنَ الۡبَحۡرَیۡنِ حَاجِزًا ؕ ءَ اِلٰہٌ مَّعَ اللّٰہِ ؕ بَلۡ  اَکۡثَرُہُمۡ  لَا یَعۡلَمُوۡنَ ﴿ؕ۶۱﴾', 'بھلا کس نے زمین کو قرارگاہ بنایا اور اسکے بیچ نہریں بنائیں اور اسکے لئے پہاڑ بنائے اور کس نے دو دریاؤں کے بیچ اوٹ بنائی یہ سب کچھ اللہ نے بنایا تو کیا اللہ کے ساتھ کوئی اور معبود بھی ہے؟ ہرگز نہیں بلکہ ان میں اکثر علم نہیں رکھتے۔', 'بھلا کس نے بنایا زمین کو ٹھہرنے کی جگہ [۸۰] اور بنائیں اس کے بیچ میں ندیاں اور  رکھے اسکے ٹھہرانے کو بوجھ [۸۱] اور رکھا دو دریا میں پردہ [۸۲] اب کوئی اور حاکم ہے اللہ کے ساتھ کوئی نہیں بہتوں کو ان میں سمجھ نہیں [۸۳]', 'Is not He (better than your gods) Who has made the earth as a fixed abode, and has placed rivers in its midst, and has placed firm mountains therein, and has set a barrier between the two seas (of salt and sweet water).Is there any ilah (god) with Allah? Nay, but most of them know not.', 'Or the One who made the earth a place to settle and made rivers amidst it and made mountains for (making) it (firm), and made a barrier between two seas? Is there any god along with Allah? No, but most of them do not have knowledge.'),
(3221, 27, 62, 5, 1, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'اَمَّنۡ یُّجِیۡبُ الۡمُضۡطَرَّ اِذَا دَعَاہُ وَ یَکۡشِفُ السُّوۡٓءَ وَ یَجۡعَلُکُمۡ  خُلَفَآءَ الۡاَرۡضِ ؕ ءَ اِلٰہٌ مَّعَ اللّٰہِ ؕ قَلِیۡلًا مَّا تَذَکَّرُوۡنَ ﴿ؕ۶۲﴾', 'بھلا کون بیقرار کی التجا قبول کرتا ہے۔ جب وہ اس سے دعا کرتا ہے اور کون اسکی تکلیف کو دور کرتا ہے اور کون تمکو زمین میں اگلوں کا جانشین بناتا ہے یہ سب کچھ اللہ کرتا ہے تو کیا اللہ کے ساتھ کوئی اور معبود بھی ہے؟ ہرگز نہیں مگر تم بہت کم غور کرتے ہو۔', 'بھلا کون پہنچتا ہے بےکس کی پکار کو جب اسکو پکارتا ہے اور دور کر دیتا ہے سختی [۸۴] اور کرتا ہے تم کو نائب اگلوں کا زمین پر [۸۵] اب کوئی حاکم ہے اللہ کے ساتھ تم بہت کم دھیان کرتے ہو [۸۶]', 'Is not He (better than your gods) Who responds to the distressed one, when he calls Him, and Who removes the evil, and makes you inheritors of the earth, generations after generations. Is there any ilah (god) with Allah? Little is that you remember!', 'Or the One who responds to a helpless person when He prays to Him and removes distress, and who makes you vicegerents of the earth? Is there any god along with Allah? No, but little you heed to advice.'),
(3222, 27, 63, 5, 1, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'اَمَّنۡ یَّہۡدِیۡکُمۡ  فِیۡ  ظُلُمٰتِ الۡبَرِّ  وَ الۡبَحۡرِ وَ مَنۡ یُّرۡسِلُ الرِّیٰحَ بُشۡرًۢا  بَیۡنَ یَدَیۡ رَحۡمَتِہٖ ؕ ءَ  اِلٰہٌ مَّعَ اللّٰہِ ؕ تَعٰلَی اللّٰہُ عَمَّا یُشۡرِکُوۡنَ ﴿ؕ۶۳﴾', 'بھلا کون تمکو جنگل اور دریا کے اندھیروں میں رستہ بتاتا اور کون ہواؤں کو اپنی رحمت کے آگے خوشخبری بنا کر بھیجتا ہے یہ سب کچھ اللہ کرتا ہے تو کیا اللہ کے ساتھ کوئی اور معبود بھی ہے؟ ہرگز نہیں یہ لوگ جو شرک کرتے ہیں اللہ کی شان اس سے بلند ہے۔', 'بھلا کون راہ بتاتا ہے تم کو اندھیروں میں جنگل کے اور دریا کے [۸۷] اور کون چلاتا ہے ہوائیں خوشخبری لانے والیاں اس کی رحمت سے پہلے [۸۸] اب کوئی حاکم ہے اللہ کے ساتھ اللہ بہت اوپر ہے اس سے جسکو شریک بتلاتے ہیں [۸۹]', 'Is not He (better than your gods) Who guides you in the darkness of the land and the sea, and Who sends the winds as heralds of glad tidings, going before His Mercy (rain)? Is there any ilah (god) with Allah? High Exalted be Allah above all that they associate as partners (to Him)!', 'Or the One who guides you in depths of darkness on land and sea, and who sends the winds bearing good news before His mercy? Is there any god along with Allah? Allah is far higher than the partners they ascribe to Him.'),
(3223, 27, 64, 5, 1, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'اَمَّنۡ یَّبۡدَؤُا الۡخَلۡقَ ثُمَّ  یُعِیۡدُہٗ  وَ مَنۡ یَّرۡزُقُکُمۡ مِّنَ السَّمَآءِ  وَ الۡاَرۡضِ ؕ ءَ اِلٰہٌ   مَّعَ  اللّٰہِ ؕ قُلۡ ہَاتُوۡا بُرۡہَانَکُمۡ اِنۡ  کُنۡتُمۡ  صٰدِقِیۡنَ ﴿۶۴﴾', 'بھلا کون خلقت کو پہلی بار پیدا کرتا۔ پھر اسکو دوبارہ پیدا کرے گا اور کون تمکو آسمان اور زمین سے رزق دیتا ہے یہ سب کچھ اللہ کرتا ہے تو کیا اللہ کے ساتھ کوئی اور معبود بھی ہے؟ ہرگز نہیں کہدو کہ مشرکو اگر تم سچے ہو تو دلیل پیش کرو۔', 'بھلا کون سرے سے بناتا ہے پھر اسکو دہرائے گا [۹۰] اور کون روزی دیتا ہے تمکو آسمان سے اور زمین سے [۹۱] اب کوئی حاکم ہے اللہ کے ساتھ تو کہہ لاؤ اپنی سند اگر تم سچے ہو [۹۲]', 'Is not He (better than your so-called gods) Who originates creation, and shall thereafter repeat it, and Who provides for you from heaven and earth? Is there any ilah (god) with Allah? Say, \"Bring forth your proofs, if you are truthful.\"', 'Or the One who originated creation, then will reproduce it, and who gives you provision from the sky and the earth? Is there any god along with Allah? Say, “Bring your proof if you are true.”'),
(3224, 27, 65, 5, 1, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'قُلۡ لَّا یَعۡلَمُ مَنۡ فِی السَّمٰوٰتِ وَ الۡاَرۡضِ الۡغَیۡبَ  اِلَّا اللّٰہُ ؕ وَ مَا یَشۡعُرُوۡنَ  اَیَّانَ  یُبۡعَثُوۡنَ ﴿۶۵﴾', 'کہدو کہ جو لوگ آسمانوں اور زمین میں ہیں اللہ کے سوا غیب کی باتیں نہیں جانتے اور نہ یہ جانتے ہیں کہ کب زندہ کر کے اٹھائے جائیں گے۔', 'تو کہہ خبر نہیں رکھتا جو کوئی ہے آسمان اور زمین میں چھپی ہوئی چیز کی مگر اللہ [۹۳] اور ان کو خبر نہیں کب جی اٹھیں گے [۹۴]', 'Say: \"None in the heavens and the earth knows the Ghaib (unseen) except Allah, nor can they perceive when they shall be resurrected.\"', 'Say, “No one in the heavens and the earth has the knowledge of the Unseen except Allah.” And they do not know when they will be raised again.'),
(3225, 27, 66, 5, 1, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'بَلِ ادّٰرَکَ عِلۡمُہُمۡ فِی الۡاٰخِرَۃِ ۟ بَلۡ  ہُمۡ  فِیۡ شَکٍّ  مِّنۡہَا ۫۟ بَلۡ  ہُمۡ  مِّنۡہَا عَمُوۡنَ ﴿٪۶۶﴾', 'بلکہ آخرت کے بارے میں ان کا علم ختم ہو چکا ہے بلکہ یہ اسکی طرف سے شک میں ہیں بلکہ یہ اس سے اندھے ہو رہے ہیں۔', 'بلکہ تھک کر گر گیا ان کا فکر آخرت کے بارہ میں بلکہ ان کو شبہ ہے اس میں بلکہ وہ اس سے اندھے ہیں [۹۵]', 'Nay, they have no knowledge of the Hereafter. Nay, they are in doubt about it. Nay, they are blind about it.', 'Rather, their knowledge has failed in respect of the Hereafter. Rather, they are in doubt about it. Rather, they are blind to it.'),
(3226, 27, 67, 6, 2, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'وَ  قَالَ الَّذِیۡنَ  کَفَرُوۡۤا ءَ اِذَا کُنَّا تُرٰبًا وَّ  اٰبَآؤُنَاۤ   اَئِنَّا  لَمُخۡرَجُوۡنَ ﴿۶۷﴾', 'اور جو لوگ کافر ہیں کہتے ہیں کہ جب ہم اور ہمارے باپ دادا مٹی ہو جائیں گے تو کیا ہم پھر قبروں سے نکالے جائیں گے۔', 'اور بولے وہ لوگ جو منکر ہیں کیا جب ہم ہو جائیں مٹی اور ہمارے باپ دادے کیا ہم کو زمین سے نکال لیں گے', 'And those who disbelieve say: \"When we have become dust, we and our fathers, shall we really be brought forth (again)?', 'And said those who disbelieved, “Is it that, when we and our fathers become dust,-is it that we shall really be brought forth?'),
(3227, 27, 68, 6, 2, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'لَقَدۡ وُعِدۡنَا ہٰذَا نَحۡنُ وَ اٰبَآؤُنَا مِنۡ قَبۡلُ ۙ اِنۡ ہٰذَاۤ  اِلَّاۤ  اَسَاطِیۡرُ  الۡاَوَّلِیۡنَ ﴿۶۸﴾', 'یہ وعدہ ہم سے اور ہمارے باپ دادا سے پہلے سے ہوتا چلا آیا ہے کہاں کا اٹھنا اور کیسی قیامت یہ تو صرف پہلے لوگوں کی کہانیاں ہیں۔', 'وعدہ پہنچ چکا ہے اس کا ہم کو اور ہمارے باپ دادوں کو پہلے سے کچھ بھی نہیں یہ نقلیں ہیں اگلوں کی [۹۶]', '\"Indeed we were promised this, we and our forefathers before, Verily, these are nothing but tales of ancients.\"', 'Indeed, it was promised to us and to our fathers even before this. This is nothing but the tales of the ancients.”'),
(3228, 27, 69, 6, 2, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'قُلۡ سِیۡرُوۡا فِی الۡاَرۡضِ فَانۡظُرُوۡا کَیۡفَ  کَانَ عَاقِبَۃُ  الۡمُجۡرِمِیۡنَ ﴿۶۹﴾', 'کہدو کہ ملک میں چلو پھرو پھر دیکھو کہ گناہگاروں کا انجام کیا ہوا ہے۔', 'تو کہہ دے پھر و ملک میں تو دیکھو کیسا ہوا انجام کار گنہاگاروں کا [۹۷]', 'Say to them (O Muhammad SAW) \"Travel in the land and see how has been the end of the criminals (those who denied Allahs Messengers and disobeyed Allah).\"', 'Say, “Travel in the land and see how was the fate of the sinners.”'),
(3229, 27, 70, 6, 2, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'وَ لَا تَحۡزَنۡ عَلَیۡہِمۡ وَ لَا تَکُنۡ فِیۡ ضَیۡقٍ مِّمَّا  یَمۡکُرُوۡنَ ﴿۷۰﴾', 'اور ان کے حال پر غم نہ کرنا اور نہ ان چالوں سے جو یہ کر رہے ہیں تنگ دل ہونا۔', 'اور غم نہ کر ان پر اور نہ خفا ہو ان کے فریب بنانے سے [۹۸]', 'And grieve you not for them, nor be straitened (in distress) because of what they plot.', 'And do not grieve for them, nor should your heart be straitened because of what they plan.'),
(3230, 27, 71, 6, 2, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'وَ یَقُوۡلُوۡنَ مَتٰی ہٰذَا الۡوَعۡدُ  اِنۡ  کُنۡتُمۡ صٰدِقِیۡنَ ﴿۷۱﴾', 'اور کہتے ہیں کہ اگر تم سچے ہو تو یہ وعدہ کب پورا ہو گا؟', 'اور کہتے ہیں کب ہوگا یہ وعدہ اگر تم سچے ہو [۹۹]', 'And they (the disbelievers in the Oneness of Allah) say: \"When (will) this promise (be fulfilled), if you are truthful?\"', 'They say, “When shall this promise come to pass if you are true?”'),
(3231, 27, 72, 6, 2, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'قُلۡ عَسٰۤی اَنۡ یَّکُوۡنَ رَدِفَ لَکُمۡ بَعۡضُ الَّذِیۡ  تَسۡتَعۡجِلُوۡنَ ﴿۷۲﴾', 'کہدو کہ جس عذاب کے لئے تم جلدی کر رہے ہو شاید اس میں سے کچھ تمہارے نزدیک آ پہنچا ہو۔', 'تو کہہ کیا بعید ہے جو تمہاری پیٹھ پر پہنچ چکی ہو بعضی وہ  چیز جس کی جلدی کر رہے ہو [۱۰۰]', 'Say: \"Perhaps that which you wish to hasten on, may be close behind you.', 'Say, “It is not unlikely that some part of that (punishment) which you are asking to come soon is already following you closely.”'),
(3232, 27, 73, 6, 2, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'وَ اِنَّ رَبَّکَ لَذُوۡ فَضۡلٍ عَلَی النَّاسِ وَ لٰکِنَّ  اَکۡثَرَہُمۡ  لَا  یَشۡکُرُوۡنَ ﴿۷۳﴾', 'اور تمہارا پروردگار تو لوگوں پر فضل کرنے والا ہے لیکن ان میں سے اکثر شکر نہیں کرتے۔', 'اور تیرا رب تو فضل رکھتا ہے لوگوں پر  پر ان میں بہت لوگ شکر نہیں کرتے [۱۰۱]', '\"Verily, your Lord is full of Grace for mankind, yet most of them do not give thanks.\"', 'And surely, your Lord is graceful for the mankind, but most of the people are not grateful.'),
(3233, 27, 74, 6, 2, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'وَ اِنَّ رَبَّکَ لَیَعۡلَمُ مَا تُکِنُّ صُدُوۡرُہُمۡ وَ مَا  یُعۡلِنُوۡنَ ﴿۷۴﴾', 'اور جو باتیں انکے سینوں میں پوشیدہ ہوتی ہیں اور جو کام وہ ظاہر کرتے ہیں تمہارا پروردگار ان سب کو جانتا ہے۔', 'اور تیرا رب جانتا ہے جو چھپ رہا ہے انکے سینوں میں اور جو کچھ کہ ظاہر کرتے ہیں', 'And verily, your Lord knows what their breasts conceal and what they reveal.', 'Of course, your Lord knows for sure what their hearts conceal and what they reveal.'),
(3234, 27, 75, 6, 2, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'وَ مَا مِنۡ غَآئِبَۃٍ  فِی السَّمَآءِ وَ الۡاَرۡضِ  اِلَّا  فِیۡ  کِتٰبٍ  مُّبِیۡنٍ ﴿۷۵﴾', 'اور آسمانوں اور زمین میں کوئی پوشیدہ چیز نہیں ہے مگر یہ کہ وہ ایک کتاب روشن میں لکھی ہوئی ہے۔', 'اور کوئی چیز نہیں جو غائب ہو آسمان اور زمین میں مگر موجود ہے کھلی کتاب میں [۱۰۲]', 'And there is nothing hidden in the heaven and the earth, but is in a Clear Book (i.e. Al-Lauh Al-Mahfooz).', 'There is nothing hidden in the heavens and the earth that is not (recorded) in a manifest book.'),
(3235, 27, 76, 6, 2, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'اِنَّ ہٰذَا الۡقُرۡاٰنَ یَقُصُّ عَلٰی بَنِیۡۤ اِسۡرَآءِیۡلَ  اَکۡثَرَ الَّذِیۡ ہُمۡ فِیۡہِ یَخۡتَلِفُوۡنَ ﴿۷۶﴾', 'بیشک یہ قرآن بنی اسرائیل کے سامنے اکثر باتیں جن میں وہ اختلاف کرتے ہیں بیان کر دیتا ہے۔', 'یہ قرآن سناتا ہے بنی اسرائیل کو بہت چیزیں جس میں وہ جھگڑ رہے ہیں', 'Verily, this Quran narrates to the Children of Israel most of that about which they differ.', 'Surely this Qur’ān mentions to the children of Isrā’īl most of the matters in which they dispute.'),
(3236, 27, 77, 6, 2, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'وَ اِنَّہٗ  لَہُدًی وَّ رَحۡمَۃٌ  لِّلۡمُؤۡمِنِیۡنَ ﴿۷۷﴾', 'اور بیشک یہ مومنوں کے لئے ہدایت اور رحمت ہے۔', 'اور بیشک وہ ہدایت ہے اور رحمت ہے ایمان والوں کے واسطے [۱۰۳]', 'And truly, it (this Quran) is a guide and a mercy to the believers.', 'It is guidance and mercy for the believers.'),
(3237, 27, 78, 6, 2, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'اِنَّ رَبَّکَ یَقۡضِیۡ بَیۡنَہُمۡ بِحُکۡمِہٖ ۚ وَ ہُوَ الۡعَزِیۡزُ  الۡعَلِیۡمُ ﴿ۙۚ۷۸﴾', 'تمہارا پروردگار قیامت کے روز ان میں اپنے حکم سے فیصلہ کر دے گا اور وہ غالب ہے علم والا ہے۔', 'تیرا رب ان میں فیصلہ کرے گا اپنی حکومت سے اور وہی ہے زبردست سب کچھ جاننے والا [۱۰۴]', 'Verily, your Lord will decide between them (various sects) by His Judgement. And He is the All-Mighty, the All-Knowing.', 'And surely your Lord will decide between them by His judgment, and He is the All-Mighty, the All-Knowing.'),
(3238, 27, 79, 6, 2, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'فَتَوَکَّلۡ عَلَی اللّٰہِ ؕ اِنَّکَ عَلَی الۡحَقِّ الۡمُبِیۡنِ ﴿۷۹﴾', 'تو اللہ پر بھروسہ رکھو تم تو صاف حق پر ہو۔', 'سو تو بھروسہ کر اللہ پر بیشک تو ہے صحیح کھلے رستہ پر [۱۰۵]', 'So put your trust in Allah; surely, you (O Muhammad SAW) are on manifest truth.', 'So trust in Allah. Surely you are on the clear truth.'),
(3239, 27, 80, 6, 2, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'اِنَّکَ لَا تُسۡمِعُ الۡمَوۡتٰی وَ لَا  تُسۡمِعُ  الصُّمَّ الدُّعَآءَ   اِذَا  وَلَّوۡا  مُدۡبِرِیۡنَ ﴿۸۰﴾', 'کچھ شک نہیں کہ تم مردوں کو بات نہیں سنا سکتے اور نہ بہروں کو جبکہ وہ پیٹھ پھیر لیں آواز سنا سکتے ہو۔', 'البتہ تو نہیں سنا سکتا مردوں کو اور نہیں سنا سکتا بہروں کو اپنی پکار جب لوٹیں وہ پیٹھ پھیر کر', 'Verily, you cannot make the dead to hear (i.e. benefit them and similarly the disbelievers), nor can you make the deaf to hear the call, when they flee, turning their backs.', 'Surely, you cannot make the dead to hear, nor can you make the deaf to hear your call when they turn their backs in retreat,'),
(3240, 27, 81, 6, 2, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'وَ مَاۤ   اَنۡتَ بِہٰدِی  الۡعُمۡیِ عَنۡ  ضَلٰلَتِہِمۡ ؕ اِنۡ تُسۡمِعُ  اِلَّا مَنۡ  یُّؤۡمِنُ بِاٰیٰتِنَا  فَہُمۡ  مُّسۡلِمُوۡنَ ﴿۸۱﴾', 'اور نہ اندھوں کر گمراہی سے نکال کر رستہ دکھا سکتے ہو تم تو انہی کو سنا سکتے ہو جو ہماری آیتوں پر ایمان لاتے ہیں پھر وہ فرمانبردار ہو جاتے ہیں۔', 'اور نہ تو دکھلا سکے اندھوں کو  جب وہ راہ سے بچلیں [۱۰۶] تو تو سناتا ہے اسکو جو یقین رکھتا ہو ہماری باتوں پر سو وہ حکمبردار ہیں [۱۰۷]', 'Nor can you lead the blind out of their error, you can only make to hear those who believe in Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), and who have submitted (themselves to Allah in Islam as Muslims).', 'nor can you show the right path to the blind against their wandering astray. You can make no one to listen (to you) except those who believe in Our verses, then submit themselves (to Allah).'),
(3241, 27, 82, 6, 2, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'وَ  اِذَا  وَقَعَ  الۡقَوۡلُ عَلَیۡہِمۡ اَخۡرَجۡنَا لَہُمۡ  دَآبَّۃً  مِّنَ الۡاَرۡضِ تُکَلِّمُہُمۡ ۙ اَنَّ النَّاسَ  کَانُوۡا بِاٰیٰتِنَا  لَا  یُوۡقِنُوۡنَ ﴿٪۸۲﴾', 'اور جب انکے بارے میں عذاب کا وعدہ پورا ہو گا تو ہم انکے لئے زمین میں سے ایک جانور نکالیں گے جو ان سے باتیں کرے گا۔ یہ ہم اسلئے کریں گے کہ لوگ ہماری آیتوں پر ایمان نہیں لاتے تھے۔', 'اور جب پڑ چکے گی ان پر بات نکالیں گے ہم ان کے آگے ایک جانور زمین سے  ان سے باتیں کرے گا اس واسطے کہ لوگ ہماری نشانیوں کا یقین نہیں کرتے تھے [۱۰۸]', 'And when the Word (of torment) is fulfilled against them, We shall bring out from the earth a beast to them, which will speak to them because mankind believed not with certainty in Our Ayat (Verses of the Quran and Prophet Muhammad SAW).', 'When the word will come to fall upon them, We will bring forth for them a beast from the earth who will speak to them that the human beings (i.e the infidels) did not believe in Our signs.'),
(3242, 27, 83, 7, 3, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'وَ یَوۡمَ نَحۡشُرُ مِنۡ کُلِّ اُمَّۃٍ  فَوۡجًا مِّمَّنۡ یُّکَذِّبُ بِاٰیٰتِنَا فَہُمۡ  یُوۡزَعُوۡنَ ﴿۸۳﴾', 'اور جس روز ہم ہر امت میں سے ایک بڑے گروہ کو جمع کریں گے جو ہماری آیتوں کی تکذیب کرتے تھے پھر ان کی جماعت بندی کی جائے گی۔', 'اور جس دن گھیر بلائیں گے ہم اہر ایک فرقہ میں سے ایک جماعت جو جھٹلاتے تھے ہماری باتوں کو پھر انکی جماعت بندی ہو گی [۱۰۹]', 'And (remember) the Day when We shall gather out of every nation a troop of those who denied Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), and (then) they (all) shall be gathered (and driven to the place of reckoning),', 'And (remember) the day when We will gather from every nation a host of those who used to reject Our verses, and they will be kept under control.'),
(3243, 27, 84, 7, 3, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'حَتّٰۤی  اِذَا جَآءُوۡ قَالَ  اَکَذَّبۡتُمۡ بِاٰیٰتِیۡ وَ لَمۡ تُحِیۡطُوۡا بِہَا عِلۡمًا اَمَّا ذَا کُنۡتُمۡ  تَعۡمَلُوۡنَ ﴿۸۴﴾', 'یہاں تک کہ جب سب آ جائیں گے تو اللہ فرمائے گا کہ کیا تم نے میری آیتوں کو جھٹلا دیا تھا حالانکہ تم نے اپنے علم سے ان کا احاطہ تو کیا ہی نہ تھا۔ بھلا تم کیا کرتے رہتے تھے؟', 'یہاں تک کہ جب حاضر ہو جائیں فرمائے گا کیوں جھٹلایا تم نے میری باتوں کو اور نہ آ چکی تھیں تمہاری سمجھ میں یا بولو کہ کیا کرتے تھے [۱۱۰]', 'Till, when they come (before their Lord at the place of reckoning), He will say: \"Did you deny My Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) when you comprehended them not in knowledge, or what (else) was it that you used to do?\"', 'Until when they will come, He (Allah) will say, “Did you reject My verses while you did not comprehend them with knowledge, or what was it that you used to do?'),
(3244, 27, 85, 7, 3, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'وَ وَقَعَ الۡقَوۡلُ عَلَیۡہِمۡ بِمَا ظَلَمُوۡا فَہُمۡ لَا  یَنۡطِقُوۡنَ ﴿۸۵﴾', 'اور ان کے ظلم کے سبب انکے حق میں وعدہ عذاب پورا ہو کر رہے گا تو وہ بول بھی نہ سکیں گے۔', 'اور پڑ چکی ان پر بات اس واسطے کہ انہوں نے شرارت کی تھی اب وہ کچھ نہیں بول سکتے [۱۱۱]', 'And the Word (of torment) will be fulfilled against them, because they have done wrong, and they will be unable to speak (in order to defend themselves).', 'And the Word will come to fall on them because of their transgression, so they will not (be able to) speak.'),
(3245, 27, 86, 7, 3, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'اَلَمۡ  یَرَوۡا اَنَّا جَعَلۡنَا الَّیۡلَ  لِیَسۡکُنُوۡا فِیۡہِ وَ النَّہَارَ مُبۡصِرًا ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیٰتٍ  لِّقَوۡمٍ  یُّؤۡمِنُوۡنَ ﴿۸۶﴾', 'کیا انہوں نے نہیں دیکھا کہ ہم نے رات کو اس لئے بنایا ہے کہ اس میں آرام کریں اور دن کو روشن بنایا ہے کہ اس میں کام کریں بیشک اس میں مومن لوگوں کے لئے نشانیاں ہیں۔', 'کیا نہیں دیکھتے کہ ہم نے بنائی رات کہ اس میں چین حاصل کریں اور دن بنایا دیکھنے کا البتہ اس میں نشانیاں ہیں ان لوگوں کے لئے جو یقین کرتے ہیں [۱۱۲]', 'See they not that We have made the night for them to rest therein, and the day sight-giving? Verily, in this are Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) for the people who believe.', 'Did they not see that We made the night, so that they may have rest in it, and (made) the day to make them see? Surely, in this there are signs for a people who believe.'),
(3246, 27, 87, 7, 3, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'وَ یَوۡمَ یُنۡفَخُ فِی الصُّوۡرِ فَفَزِعَ مَنۡ فِی السَّمٰوٰتِ وَ مَنۡ فِی الۡاَرۡضِ اِلَّا مَنۡ شَآءَ  اللّٰہُ ؕ وَ  کُلٌّ   اَتَوۡہُ   دٰخِرِیۡنَ ﴿۸۷﴾', 'اور جس روز صور پھونکا جائے گا تو جو لوگ آسمانوں میں اور جو زمین میں ہیں سب گھبرا اٹھیں گے مگر وہ جسے اللہ چاہے اور سب اسکے پاس عاجز ہو کر چلے آئیں گے۔', 'اور جس دن پھونکی جائیگی صور [۱۱۳] تو گھبرا جائے جو کوئی ہے آسمان میں اور جو کوئی ہے زمین میں مگر جس کو اللہ چاہے [۱۱۴] اور سب چلے آئیں اسکے آگے عاجزی سے [۱۱۵]', 'And (remember) the Day on which the Trumpet will be blown and all who are in the heavens and all who are on the earth, will be terrified except him whom Allah will (exempt). And all shall come to Him humbled.', 'And (remember) the day when the Horn will be blown; so all those in the heavens and the earth will be in panic, except those whom Allah wills. And All (of them) will come to Him in humility.'),
(3247, 27, 88, 7, 3, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'وَ تَرَی الۡجِبَالَ تَحۡسَبُہَا جَامِدَۃً  وَّ  ہِیَ تَمُرُّ مَرَّ السَّحَابِ ؕ صُنۡعَ اللّٰہِ  الَّذِیۡۤ اَتۡقَنَ کُلَّ شَیۡءٍ ؕ اِنَّہٗ  خَبِیۡرٌۢ  بِمَا تَفۡعَلُوۡنَ ﴿۸۸﴾', 'اور تم پہاڑوں کو دیکھتے ہو تو خیال کرتے ہو کہ مضبوط جمے ہوئے ہیں مگر وہ اس روز اس طرح اڑتے پھریں گے جیسے بادل یہ اللہ کی کاریگری ہے جس نے ہر چیز کو مضبوط بنایا۔ بیشک وہ تمہارے سب افعال سے باخبر ہے۔', 'اور تو دیکھے پہاڑوں کو سمجھے کہ وہ جم رہے ہیں اور وہ چلیں گے جیسے چلے بادل [۱۱۶] کاریگری اللہ کی جس نے سادھا ہے ہر چیز کو [۱۱۷] اس کو خبر ہے جو کچھ تم کرتے ہو [۱۱۸]', 'And you will see the mountains and think them solid, but they shall pass away as the passing away of the clouds. The Work of Allah, Who perfected all things, verily! He is Well-Acquainted with what you do.', 'And you see the mountains (at present) supposing them as fixed (forever), while (on that Day) they will fly like the flight of clouds - an act of Allah who has perfected every thing. Surely, He is All-Aware of what you do.'),
(3248, 27, 89, 7, 3, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'مَنۡ جَآءَ  بِالۡحَسَنَۃِ  فَلَہٗ خَیۡرٌ  مِّنۡہَا ۚ وَ ہُمۡ  مِّنۡ  فَزَعٍ  یَّوۡمَئِذٍ  اٰمِنُوۡنَ ﴿۸۹﴾', 'جو شخص نیکی لے کر آئے گا تو اسکے لئے اس سے بہتر بدلہ تیار ہے اور ایسے لوگ اس روز گھبراہٹ سے بےخوف ہوں گے۔', 'جو کوئی لیکر آیا بھلائی تو اس کو ملے اس سے بہتر [۱۱۹] اور ان کو گھبراہٹ سے اس دن امن ہے [۱۲۰]', 'Whoever brings a good deed (i.e. Belief in the Oneness of Allah along with every deed of righteousness), will have better than its worth, and they will be safe from the terror on that Day.', 'Whoever will come with the good deed will have (a reward) better than that, and such people will be immune on that day from any panic.'),
(3249, 27, 90, 7, 3, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'وَ مَنۡ جَآءَ بِالسَّیِّئَۃِ  فَکُبَّتۡ وُجُوۡہُہُمۡ  فِی النَّارِ ؕ ہَلۡ تُجۡزَوۡنَ  اِلَّا مَا کُنۡتُمۡ تَعۡمَلُوۡنَ ﴿۹۰﴾', 'اور جو برائی لے کر آئے گا تو ایسے لوگ اوندھے منہ دوزخ میں ڈال دیئے جائیں گے۔ تمکو تو ان ہی اعمال کا بدلہ ملے گا جو تم کرتے رہے ہو۔', 'اور جو کوئی لیکر آیا برائی سو اوندھے ڈالیں ان کے منہ آگ میں وہی بدلہ پاؤ گے جو کچھ تم کیا کرتے تھے [۱۲۱]', 'And whoever brings an evil (deed) (i.e. Shirk polytheism, disbelief in the Oneness of Allah and every evil sinful deed), they will be cast down (prone) on their faces in the Fire. (And it will be said to them) \"Are you being recompensed anything except what you used to do?\"', 'And whoever will come with evil deed, the faces of such people will be thrown down into the Fire. You will not be recompensed but for what you used to do.'),
(3250, 27, 91, 7, 3, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'اِنَّمَاۤ  اُمِرۡتُ اَنۡ اَعۡبُدَ رَبَّ ہٰذِہِ الۡبَلۡدَۃِ  الَّذِیۡ حَرَّمَہَا وَ لَہٗ  کُلُّ  شَیۡءٍ ۫ وَّ اُمِرۡتُ اَنۡ  اَکُوۡنَ مِنَ الۡمُسۡلِمِیۡنَ ﴿ۙ۹۱﴾', 'کہدو مجھکو یہی ارشاد ہوا ہے کہ اس شہر مکہ کے مالک کی عبادت کروں جس نے اسکو محترم بنایا ہے اور ہر چیز اسی کی ہے اور مجھے یہ بھی حکم ہوا ہے کہ میں فرمانبردار رہوں۔', 'مجھ کو یہی حکم ہے کہ بندگی کروں اس شہر کے مالک کی جس نے اس کو حرمت دی اور اسی کی ہے ہر ایک چیز [۱۲۲] اور مجھ کو حکم ہے کہ رہوں حکم برداروں میں [۱۲۳]', 'I (Muhammad SAW) have been commanded only to worship the Lord of this city (Makkah), Him Who has sanctified it and His is everything. And I am commanded to be from among the Muslims (those who submit to Allah in Islam).', 'I am but ordered to worship the Lord of this city, which is sanctified by Him. And to Him belongs every thing, and I am ordered to be one of the Muslims (who submit themselves to Allah),'),
(3251, 27, 92, 7, 3, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'وَ اَنۡ  اَتۡلُوَا الۡقُرۡاٰنَ ۚ فَمَنِ اہۡتَدٰی فَاِنَّمَا یَہۡتَدِیۡ لِنَفۡسِہٖ ۚ وَ مَنۡ ضَلَّ فَقُلۡ  اِنَّمَاۤ   اَنَا مِنَ  الۡمُنۡذِرِیۡنَ ﴿۹۲﴾', 'اور یہ بھی کہ قرآن پڑھا کروں تو اب جو شخص راہ راست اختیار کرتا ہے تو اپنے ہی فائدے کے لئے اختیار کرتا ہے۔ اور جو گمراہ رہتا ہے تو کہدو کہ میں تو صرف خبردار کرنے والا ہوں۔', 'اور یہ کہ سنا دون قرآن [۱۲۴] پھر جو کوئی راہ پر آیا سو راہ پر آئے گا اپنے ہی بھلے کو اور جو کوئی بہکا رہا تو کہدے میں تو یہی ہوں ڈر سنا دینے والا [۱۲۵]', 'And to recite the Quran, so whosoever receives guidance, receives it for the good of his ownself, and whosoever goes astray, say (to him): \"I am only one of the warners.\"', 'and to recite the Qur’ān; so whoever takes the right path, takes it for his own benefit. As for the one who goes astray, say (to him), “I am only one of the warners.”'),
(3252, 27, 93, 7, 3, 20, 'اَمَّنۡ  خَلَقَ', 'النمل', 'وَ قُلِ الۡحَمۡدُ  لِلّٰہِ سَیُرِیۡکُمۡ  اٰیٰتِہٖ فَتَعۡرِفُوۡنَہَا ؕ وَ مَا رَبُّکَ بِغَافِلٍ عَمَّا تَعۡمَلُوۡنَ ﴿٪۹۳﴾', 'اور کہو کہ اللہ کا شکر ہے۔ وہ تمکو عنقریب اپنی نشانیاں دکھائے گا تو تم انکو پہچان لو گے۔ اور جو کام تم کرتے ہو تمہارا پروردگار ان سے بیخبر نہیں ہے۔', 'اور کہہ تعریف ہے سب اللہ کو [۱۲۶] آگے دکھائے گا تم کو اپنے نمونے تو انکو پہچان لو گے [۱۲۷] اور تیرا رب بے خبر نہیں ان کاموں سے جو تم کرتے ہو [۱۲۸]', 'And say ((O Muhammad SAW) to these polytheists and pagans etc.): \"All the praises and thanks be to Allah. He will show you His Ayat (signs, in yourselves, and in the universe or punishments, etc.), and you shall recognise them. And your Lord is not unaware of what you do.\"', 'And say, “Praise belongs to Allah. He will show you His signs, then you will recognize them.” And your Lord is not unaware of what you do.'),
(3253, 28, 1, 1, 4, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'طٰسٓمّٓ ﴿۱﴾', 'طٰسم۔', 'طٰسم۔', 'TaSeenMeem (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings)', 'Tā Sīn Mīm.'),
(3254, 28, 2, 1, 4, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'تِلۡکَ اٰیٰتُ  الۡکِتٰبِ  الۡمُبِیۡنِ ﴿۲﴾', 'یہ کتاب روشن کی آیتیں ہیں۔', 'یہ آیتیں ہیں کھلی کتاب کی', 'These are Verses of the manifest Book (that makes clear truth from falsehood, good from evil, etc.).', 'These are verses of the clear Book.'),
(3255, 28, 3, 1, 4, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'نَتۡلُوۡا عَلَیۡکَ مِنۡ نَّبَاِ مُوۡسٰی وَ فِرۡعَوۡنَ بِالۡحَقِّ  لِقَوۡمٍ  یُّؤۡمِنُوۡنَ ﴿۳﴾', 'اے پیغمبر ہم تمہیں موسٰی  اور فرعون کے کچھ حالات مومن لوگوں کے سنانے کے لئے صحیح صحیح سناتے ہیں۔', 'ہم سناتے ہیں تجھ کو کچھ احوال موسٰی اور فرعون کا تحقیقی ان لوگوں کے  واسطے جو یقین کرتے ہیں [۱]', 'We recite to you some of the news of Moosa (Moses) and Firaun (Pharaoh) in truth, for a people who believe (those who believe in this Quran, and in the Oneness of Allah).', 'We recite to you a part of the story of Mūsā and Pharaoh with truth for a people who believe.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(3256, 28, 4, 1, 4, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'اِنَّ فِرۡعَوۡنَ عَلَا فِی الۡاَرۡضِ وَ جَعَلَ اَہۡلَہَا شِیَعًا یَّسۡتَضۡعِفُ طَآئِفَۃً  مِّنۡہُمۡ یُذَبِّحُ اَبۡنَآءَہُمۡ وَ یَسۡتَحۡیٖ نِسَآءَہُمۡ ؕ اِنَّہٗ  کَانَ مِنَ الۡمُفۡسِدِیۡنَ ﴿۴﴾', 'کہ فرعون نے ملک میں سر اٹھا رکھا تھا اور وہاں کے باشندوں کر گروہ گروہ بنا رکھا تھا ان میں سے ایک گروہ کو یہاں تک کمزور کر دیا تھا کہ انکے بیٹوں کو ذبح کر ڈالتا اور انکی لڑکیوں کو زندہ رہنے دیتا۔ بیشک وہ مفسدوں میں تھا۔', 'فرعون چڑھ رہا تھا ملک میں اور کر  رکھا تھا وہاں کے لوگوں کو کئ فرقے کمزور کر  رکھا تھا ایک فرقہ کو ان میں [۲] ذبح کرتا تھا انکے بیٹوں کو اور زندہ رکھتا تھا انکی عورتوں کو [۳] بیشک وہ تھا خرابی ڈالنے والا [۴]', 'Verily, Firaun (Pharaoh) exalted himself in the land and made its people sects, weakening (oppressing) a group (i.e. Children of Israel) among them, killing their sons, and letting their females live. Verily, he was of the Mufsidoon (i.e. those who commit great sins and crimes, oppressors, tyrants, etc.).', 'Indeed, Pharaoh had become high-handed in the land, and had divided its people into different groups; he used to persecute a group of them, slaughtering their sons and keeping their women alive. Indeed he was one of the mischief-makers,'),
(3257, 28, 5, 1, 4, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ نُرِیۡدُ اَنۡ نَّمُنَّ عَلَی الَّذِیۡنَ اسۡتُضۡعِفُوۡا فِی الۡاَرۡضِ وَ نَجۡعَلَہُمۡ اَئِمَّۃً  وَّ  نَجۡعَلَہُمُ  الۡوٰرِثِیۡنَ ۙ﴿۵﴾', 'اور ہم چاہتے تھے کہ جو لوگ ملک میں کمزور کر دیئے گئے ہیں ان پر احسان کریں اور انکو پیشوا بنائیں اور انہیں ملک کا وارث بنائیں۔', 'اور ہم چاہتے ہیں کو احسان کریں ان لوگوں پر جو کمزور ہوئے پڑے تھے ملک میں اور کر دیں ان کو سردار اور کر دیں ان کو قائم مقام', 'And We wished to do a favour to those who were weak (and oppressed) in the land, and to make them rulers and to make them the inheritors,', 'while We intended to favor those who were held as weak in the land, and to make them leaders and make them inheritors,'),
(3258, 28, 6, 1, 4, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ نُمَکِّنَ لَہُمۡ فِی الۡاَرۡضِ وَ نُرِیَ فِرۡعَوۡنَ وَ ہَامٰنَ وَ جُنُوۡدَہُمَا مِنۡہُمۡ مَّا  کَانُوۡا  یَحۡذَرُوۡنَ ﴿۶﴾', 'اور ملک میں انکو قدرت دیں اور فرعون اور ہامان اور انکے لشکر کو وہ چیز دکھا دیں جس سے وہ ڈرتے تھے۔', 'اور جما دیں ان کو ملک میں [۵] اور دکھا دیں فرعون اور ہامان کو [۶] اور انکے لشکروں کو انکے ہاتھ سے جس چیز کا ان کو خطرہ تھا [۷]', 'And to establish them in the land, and We let Firaun (Pharaoh) and Haman and their hosts receive from them that which they feared.', 'and give them power in the land, and to show Pharaoh, Hāmān and their armies the very thing they were fearing from them.'),
(3259, 28, 7, 1, 4, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ اَوۡحَیۡنَاۤ  اِلٰۤی اُمِّ مُوۡسٰۤی اَنۡ  اَرۡضِعِیۡہِ ۚ فَاِذَا خِفۡتِ عَلَیۡہِ  فَاَلۡقِیۡہِ فِی الۡیَمِّ  وَ لَا تَخَافِیۡ  وَ لَا تَحۡزَنِیۡ ۚ اِنَّا رَآدُّوۡہُ  اِلَیۡکِ وَ جَاعِلُوۡہُ  مِنَ الۡمُرۡسَلِیۡنَ ﴿۷﴾', 'اور ہم نے موسٰی  کی ماں کی طرف وحی بھیجی کہ اسکو دودھ پلاؤ پھر جب تمکو اسکے بارے میں کچھ خوف پیدا ہو تو اسے دریا میں ڈال دینا اور نہ تو خوف کرنا اور نہ رنج کرنا۔ ہم اسکو تمہارے پاس واپس پہنچا دیں گے اور بعد میں اسے پیغمبر بنا دیں گے۔', 'اور ہم نے حکم بھیجا موسٰی کی ماں کو کہ اس کو دودھ پلاتی رہ پھر جب تجھ کو ڈر ہو اس کا تو ڈال دے اسکو دریا میں [۸] اور نہ خطرہ کر اور نہ غمگین ہو ہم پھر  پہنچا دیں گے اسکو  تیری طرف اور کریں گے اس کو رسولوں سے [۹]', 'And We inspired the mother of Moosa (Moses), (saying): \"Suckle him (Moosa (Moses)), but when you fear for him, then cast him into the river and fear not, nor grieve. Verily! We shall bring him back to you, and shall make him one of (Our) Messengers.\"', 'We inspired the mother of Mūsā saying, “Suckle him (Mūsā). Then once you fear about him, cast him in the river, and do not fear, and do not grieve. Surely We are going to bring him back to you and appoint him one of (Our) messengers.”'),
(3260, 28, 8, 1, 4, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَالۡتَقَطَہٗۤ  اٰلُ فِرۡعَوۡنَ  لِیَکُوۡنَ لَہُمۡ عَدُوًّا وَّ حَزَنًا ؕ اِنَّ فِرۡعَوۡنَ  وَ ہَامٰنَ  وَ جُنُوۡدَہُمَا  کَانُوۡا خٰطِئِیۡنَ ﴿۸﴾', 'سو فرعون کے لوگوں نے اسکو اٹھا لیا اس لئے کہ نتیجہ یہ ہونا تھا کہ وہ ان کا دشمن اور انکے لئے موجب غم ہو۔ بیشک فرعون اور ہامان اور انکے لشکر غلطی پر تھے۔', 'پھر اٹھا لیا اس کو فرعون کے گھر والوں نے کہ ہو ان کا دشمن اور غم میں ڈالنے والا بیشک فرعون اور ہامان اور ان کے لشکر تھے چوکنے والے [۱۰]', 'Then the household of Firaun (Pharaoh) picked him up, that he might become for them an enemy and a (cause of) grief. Verily! Firaun (Pharaoh), Haman and their hosts were sinners.', 'So the family of Pharaoh picked him up, so that he becomes for them an enemy and a (cause of) grief. Indeed Pharaoh, Hāmān and their armies were mistaken.'),
(3261, 28, 9, 1, 4, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ قَالَتِ امۡرَاَتُ فِرۡعَوۡنَ قُرَّتُ عَیۡنٍ لِّیۡ وَ لَکَ ؕ لَا تَقۡتُلُوۡہُ ٭ۖ عَسٰۤی اَنۡ  یَّنۡفَعَنَاۤ اَوۡ  نَتَّخِذَہٗ   وَلَدًا  وَّ  ہُمۡ  لَا یَشۡعُرُوۡنَ ﴿۹﴾', 'اور فرعون کی بیوی نے کہا کہ یہ میری اور تمہاری دونوں کی آنکھوں کی ٹھنڈک ہے اسکو قتل نہ کرنا۔ شاید یہ ہمیں فائدہ پہنچائے یا ہم اسے بیٹا بنا لیں اور وہ انجام سے بیخبر تھے۔', 'اور بولی فرعون کی عورت یہ تو آنکھوں کی ٹھنڈک ہے میرے لئے اور تیرے لئے [۱۱] اسکو مت مارو کچھ بعید نہیں جو ہمارے کام آئے یا ہم اسکو کر لیں بیٹا [۱۲] اور ان کو کچھ خبر نہ تھی [۱۳]', 'And the wife of Firaun (Pharaoh) said: \"A comfort of the eye for me and for you. Kill him not, perhaps he may be of benefit to us, or we may adopt him as a son.\" And they perceive not (the result of that).', 'And the wife of Pharaoh said, (to Pharaoh about Mūsā), “He may be a delight of eye for me and you. Do not kill him. It is hoped that he will be of benefit to us, or we will adopt him as a son.” And they were not aware (of what was going to happen).'),
(3262, 28, 10, 1, 4, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ اَصۡبَحَ فُؤَادُ  اُمِّ مُوۡسٰی فٰرِغًا ؕ اِنۡ کَادَتۡ لَتُبۡدِیۡ بِہٖ  لَوۡ لَاۤ  اَنۡ رَّبَطۡنَا عَلٰی قَلۡبِہَا لِتَکُوۡنَ مِنَ الۡمُؤۡمِنِیۡنَ ﴿۱۰﴾', 'اور موسٰی  کی ماں کا دل بیقرار ہو گیا اگر ہم انکے دل کو مضبوط نہ کر دیتے تو قریب تھا کہ وہ اس غم کو ظاہر کر دیتیں۔ ہم چاہتے تھے کہ وہ مومنوں میں رہیں۔', 'اور صبح کو موسٰی کی ماں کے دل میں قرار نہ رہا قریب تھی کہ ظاہر کر دے بیقراری کو اگر نہ ہم نے گرہ دی ہوتی اس کے دل پر اس واسطے کہ رہے یقین کرنے والوں میں [۱۴]', 'And the heart of the mother of Moosa (Moses) became empty (from every thought, except the thought of Moosa (Moses)). She was very near to disclose his (case, i.e. the child is her son), had We not strengthened her heart (with Faith), so that she might remain as one of the believers.', 'And the heart of the mother of Mūsā became restless; indeed she was about to disclose this (the real facts about Mūsā), had We not strengthened her heart to remain among those who have firm belief (in Allah’s promise).'),
(3263, 28, 11, 1, 4, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ قَالَتۡ لِاُخۡتِہٖ قُصِّیۡہِ ۫ فَبَصُرَتۡ بِہٖ عَنۡ  جُنُبٍ  وَّ  ہُمۡ  لَا  یَشۡعُرُوۡنَ ﴿ۙ۱۱﴾', 'اور والدہ موسٰی نے اسکی بہن سے کہا کہ اسکے پیچھے پیچھے چلی جا تو وہ اسے دور سے دیکھتی رہی اور ان لوگوں کو کچھ خبر نہ تھی۔', 'اور کہہ دیا اس کی بہن کو پیچھے چلی جا پھر دیکھتی رہی اس کو  اجنبی ہو کر اور ان کو خبر نہ ہوئی [۱۵]', 'And she said to his (Musas (Moses)) sister: \"Follow him.\" So she (his sister) watched him from a far place secretly, while they perceived not.', 'She said to his sister, “Keep track of him.” So she watched him from a distance, while they were not aware.'),
(3264, 28, 12, 1, 4, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ حَرَّمۡنَا عَلَیۡہِ الۡمَرَاضِعَ مِنۡ قَبۡلُ فَقَالَتۡ ہَلۡ  اَدُلُّکُمۡ  عَلٰۤی  اَہۡلِ بَیۡتٍ یَّکۡفُلُوۡنَہٗ  لَکُمۡ وَ ہُمۡ لَہٗ نٰصِحُوۡنَ ﴿۱۲﴾', 'اور ہم نے پہلے ہی سے اس پر دائیوں کے دودھ حرام کر دیئے تھے۔ تو موسٰی  کی بہن نے کہا کہ میں تمیں ایسے گھر والے بتاؤں کہ تمہارے لئے اس بچے کو پالیں اور اسکی خیرخواہی سے پرورش کریں۔', 'اور روک رکھا تھا ہم نے موسٰی سے دائیوں کو پہلے سے  پھر بولی میں بتلاؤں تم کو ایک گھر  والے کہ اس کو پال دیں تمہارے لئے اور وہ اس کا بھلا چاہنے والے ہیں [۱۶]', 'And We had already forbidden (other) foster suckling mothers for him, until she (his sister came up and) said: \"Shall I direct you to a household who will rear him for you, and sincerely they will look after him in a good manner?\"', 'And We had already barred him (Mūsā) from (accepting) any suckling women, so she (his sister) said (to Pharaoh’s people), “Shall I point out to you a family who will nurse him for you, and they will be his well-wishers?”'),
(3265, 28, 13, 1, 4, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَرَدَدۡنٰہُ  اِلٰۤی  اُمِّہٖ کَیۡ تَقَرَّ عَیۡنُہَا وَ لَا تَحۡزَنَ وَ لِتَعۡلَمَ  اَنَّ وَعۡدَ اللّٰہِ حَقٌّ وَّ لٰکِنَّ  اَکۡثَرَہُمۡ  لَا  یَعۡلَمُوۡنَ ﴿٪۱۳﴾', 'سو ہم نے اس طریق سے انکو ان کی ماں کے پاس واپس پہنچا دیا تاکہ انکی آنکھیں ٹھنڈی ہوں اور وہ غم نہ کھائیں اور معلوم کر لیں کہ اللہ کا وعدہ سچا ہے لیکن اکثر لوگ نہیں جانتے۔', 'پھر ہم نے پہنچا دیا اس کو  اسکی ماں کی طرف کہ ٹھنڈی رہے اس کی آنکھ اور غمگین نہ ہو اور جانے کہ اللہ کا وعدہ ٹھیک ہے [۱۷] پر بہت لوگ نہیں جانتے [۱۸]', 'So did We restore him to his mother, that she might be delighted, and that she might not grieve, and that she might know that the Promise of Allah is true. But most of them know not.', 'Thus We brought him back to his mother, so that her eye might have comfort and she might not grieve, and so that she might know that Allah’s promise is true, but most of them do not know.'),
(3266, 28, 14, 2, 5, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ لَمَّا بَلَغَ  اَشُدَّہٗ  وَ اسۡتَوٰۤی اٰتَیۡنٰہُ حُکۡمًا وَّ عِلۡمًا ؕ وَ کَذٰلِکَ نَجۡزِی الۡمُحۡسِنِیۡنَ ﴿۱۴﴾', 'اور جب موسٰی  جوانی کو پہنچے اور بھرپور جوان ہو گئے تو ہم نے انکو حکمت اور علم عنایت کیا۔ اور ہم نیکوکاروں کو ایسا ہی بدلہ دیا کرتے ہیں۔', 'اور جب پہنچ گیا اپنے زور پر اور سنھبل گیا دی ہم نے اس کو حکمت اور سمجھ اور اسی طرح ہم بدلہ دیتے ہیں نیکی والوں کو [۱۹]', 'And when he attained his full strength, and was perfect (in manhood), We bestowed on him Hukman (Prophethood, right judgement of the affairs) and religious knowledge (of the religion of his forefathers i.e. Islamic Monotheism). And thus do We reward the Muhsinoon (i.e. good doers - see the footnote of V.9:120).', 'And when he reached his maturity and became perfect, We gave him wisdom and knowledge. This is how We reward those who are good in their deeds.'),
(3267, 28, 15, 2, 5, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ دَخَلَ الۡمَدِیۡنَۃَ عَلٰی حِیۡنِ غَفۡلَۃٍ مِّنۡ اَہۡلِہَا فَوَجَدَ فِیۡہَا رَجُلَیۡنِ یَقۡتَتِلٰنِ ٭۫ ہٰذَا مِنۡ شِیۡعَتِہٖ وَ ہٰذَا مِنۡ عَدُوِّہٖ ۚ فَاسۡتَغَاثَہُ  الَّذِیۡ مِنۡ شِیۡعَتِہٖ عَلَی الَّذِیۡ  مِنۡ عَدُوِّہٖ ۙ فَوَکَزَہٗ  مُوۡسٰی فَقَضٰی عَلَیۡہِ ٭۫  قَالَ ہٰذَا مِنۡ عَمَلِ الشَّیۡطٰنِ ؕ اِنَّہٗ  عَدُوٌّ مُّضِلٌّ مُّبِیۡنٌ ﴿۱۵﴾', 'اور وہ ایسے وقت شہر میں داخل ہوئے کہ وہاں کے باشندے بیخبر ہو رہے تھے تو دیکھا کہ وہاں دو شخص لڑ رہے تھے ایک تو موسٰی  کی قوم کا ہے اور دوسرا انکے دشمنوں میں سے تو جو شخص انکی قوم میں سے تھا اس نے دوسرے شخص کے مقابلے میں جو موسٰی  کے دشمنوں میں سے تھا مدد طلب کی تو موسٰی نے اسکو مکا مارا اور اس کا کام تمام کر دیا کہنے لگے کہ یہ تو شیطانی کام ہوا بیشک وہ انسان کا دشمن ہے کھلا بہکانے والا ہے۔', 'اور آیا شہر کے اندر جس وقت بیخبر ہوئے تھے وہاں کے لوگ [۲۰] پھر پائے اس نے دو مرد لڑتے ہوئے یہ ایک اسکے رفیقوں میں اور یہ دوسرا اسکے دشمنوں میں پھر فریاد کی اس سے اس نے جو تھا اس کے رفیقوں میں اس کی جو  تھا اس کے دشمنوں میں پھر مکا مارا  اسکو موسٰی نے  پھر اسکو تمام کر دیا بولا یہ ہوا شیطان کے کام سے بیشک وہ دشمن ہے بہکانے والا صریح', 'And he entered the city at a time of unawareness of its people, and he found there two men fighting, - one of his party (his religion - from the Children of Israel), and the other of his foes. The man of his (own) party asked him for help against his foe, so Moosa (Moses) struck him with his fist and killed him. He said: \"This is of Shaitans (Satan) doing, verily, he is a plain misleading enemy.\"', 'Once he entered the city at a time when its people were heedless; so he found in it two men fighting each other: This one was from his own group, and that one from his enemies. So the one from his own group called him for help against the one who was from his enemies. So Mūsā gave him a blow with his fist and finished him off. (Then) He (Mūsā) said (out of remorse), “This is some of Satan’s act. He is indeed a clear enemy who misleads (people).”'),
(3268, 28, 16, 2, 5, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'قَالَ رَبِّ اِنِّیۡ ظَلَمۡتُ نَفۡسِیۡ فَاغۡفِرۡ لِیۡ فَغَفَرَ  لَہٗ ؕ اِنَّہٗ  ہُوَ  الۡغَفُوۡرُ  الرَّحِیۡمُ ﴿۱۶﴾', 'بولے کہ اے پروردگار میں نے اپنے آپ پر ظلم کیا سو تو مجھے بخش دے تو اللہ نے انکو بخش دیا۔ بیشک وہ بخشنے والا ہے مہربان ہے۔', 'بولا اے میرے رب میں نے برا کیا اپنی جان کا سو بخش مجھ کو پھر اس کو بخش دیا بیشک وہی ہے بخشنے والا مہربان [۲۱]', 'He said: \"My Lord! Verily, I have wronged myself, so forgive me.\" Then He forgave him. Verily, He is the Oft-Forgiving, the Most Merciful.', 'He said, “O my Lord, I have wronged myself, so forgive me.” So He forgave him. Indeed He is the most Forgiving, Very-Merciful.'),
(3269, 28, 17, 2, 5, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'قَالَ رَبِّ بِمَاۤ  اَنۡعَمۡتَ عَلَیَّ  فَلَنۡ  اَکُوۡنَ  ظَہِیۡرًا  لِّلۡمُجۡرِمِیۡنَ ﴿۱۷﴾', 'کہنے لگے کہ اے پروردگار تو نے جو مجھ پر مہربانی فرمائی ہے تو میں بھی آئندہ کبھی گنہگاروں کا مددگار نہ بنوں گا۔', 'بولا اے رب جیسا تو نے فضل کر دیا مجھ پر پھر میں کبھی نہ ہوں گا مددگار گنہگاروں کا [۲۲]', 'He said: \"My Lord! For that with which You have favoured me, I will never more be a helper for the Mujrimoon (criminals, disobedient to Allah, polytheists, sinners, etc.)!\"', 'He (Mūsā) said, “O my Lord! As You have favored me, I will never be a supporter of the sinners.”'),
(3270, 28, 18, 2, 5, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَاَصۡبَحَ فِی الۡمَدِیۡنَۃِ خَآئِفًا یَّتَرَقَّبُ فَاِذَا  الَّذِی اسۡتَنۡصَرَہٗ  بِالۡاَمۡسِ یَسۡتَصۡرِخُہٗ ؕ قَالَ لَہٗ  مُوۡسٰۤی  اِنَّکَ لَغَوِیٌّ  مُّبِیۡنٌ ﴿۱۸﴾', 'الغرض صبح کے وقت شہر میں ڈرتے ڈرتے داخل ہوئے کہ دیکھیں کیا ہوتا ہے تو ناگہاں وہی شخص جس نے کل ان سے مدد مانگی تھی پھر انکو پکار رہا ہے۔ موسٰی  نے اس سے کہا کہ تو تو بڑا بہکا ہوا ہے۔', 'پھر صبح کو اٹھا اس شہر میں ڈرتا ہوا انتظار کرتا ہوا [۲۳] پھر ناگہاں جس نے کل مدد مانگی تھی اس سے آج پھر فریاد کرتا ہے اس سے [۲۴] کہا موسٰی نے بیشک تو بے راہ ہے صریح [۲۵]', 'So he became afraid, looking about in the city (waiting as to what will be the result of his crime of killing), when behold, the man who had sought his help the day before, called for his help (again). Moosa (Moses) said to him: \"Verily, you are a plain misleader!\"', 'Then next morning he was fearful in the city, waiting (for what comes next) when the man who sought his help the day before, shouted to him for help (again). Mūsā said to him, “You are surely a clear trouble-maker.”'),
(3271, 28, 19, 2, 5, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَلَمَّاۤ  اَنۡ  اَرَادَ  اَنۡ یَّبۡطِشَ بِالَّذِیۡ ہُوَ عَدُوٌّ لَّہُمَا ۙ قَالَ یٰمُوۡسٰۤی  اَتُرِیۡدُ اَنۡ تَقۡتُلَنِیۡ  کَمَا قَتَلۡتَ نَفۡسًۢا بِالۡاَمۡسِ ٭ۖ اِنۡ تُرِیۡدُ  اِلَّاۤ  اَنۡ تَکُوۡنَ جَبَّارًا فِی الۡاَرۡضِ وَ مَا تُرِیۡدُ اَنۡ تَکُوۡنَ مِنَ الۡمُصۡلِحِیۡنَ ﴿۱۹﴾', 'پھر جب موسٰی  نے ارادہ کیا کہ اس شخص کو جو ان دونوں کا دشمن تھا پکڑ لیں تو وہ بول اٹھا کہ جس طرح تم نے کل ایک شخص کو مار ڈالا تھا اسی طرح چاہتے ہو کہ تم مجھے بھی مار ڈالو۔ تم تو یہی چاہتے ہو کہ ملک میں ظلم و ستم کرتے پھرو اور یہ نہیں چاہتے کہ صلح کرانے والوں میں سے ہو جاؤ۔', 'پھر جب چاہا کہ ہاتھ ڈالے اس پر جو دشمن تھا ان دونوں کا بول اٹھا اے موسٰی کیا تو چاہتا ہے کہ خون کرے میرا جیسے خون کر چکا ہے کل ایک جان کا [۲۶] تیرا یہی جی چاہتا ہے کہ زبردستی کرتا پھرے ملک میں اور نہیں چاہتا کہ ہو صلح کرا دینے والا [۲۷]', 'Then when he decided to seize the man who was an enemy to both of them, the man said: \"O Moosa (Moses)! Is it your intention to kill me as you killed a man yesterday? Your aim is nothing but to become a tyrant in the land, and not to be one of those who do right.\"', 'Thereafter when he intended to grasp at the one who was an enemy to both of them, he (i.e. the Israelite) said, “O Mūsā, do you want to kill me as you have killed a person yesterday? Your intention is only to become a tyrant in the land, and you do not intend to be one of the peace-makers.”'),
(3272, 28, 20, 2, 5, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ جَآءَ رَجُلٌ مِّنۡ اَقۡصَا الۡمَدِیۡنَۃِ یَسۡعٰی ۫ قَالَ یٰمُوۡسٰۤی  اِنَّ الۡمَلَاَ یَاۡتَمِرُوۡنَ بِکَ لِیَقۡتُلُوۡکَ فَاخۡرُجۡ  اِنِّیۡ لَکَ  مِنَ  النّٰصِحِیۡنَ ﴿۲۰﴾', 'اور ایک شخص شہر کی پرلی طرف سے دوڑتا ہوا آیا بولا کہ اے موسٰی اہل دربار تمہارے بارے میں مشورے کرتے ہیں کہ تمکو مار ڈالیں سو تم یہاں سے نکل جاؤ۔ میں تمہارا خیر خواہ ہوں۔', 'اور آیا شہر کے پرلے سرے سے ایک مرد دوڑتا ہوا کہا اے موسٰی دربار والے مشورہ کرتے ہیں تجھ پر کہ تجھ کو مار ڈالیں سو نکل جا میں تیرا بھلا چاہنے والا ہوں [۲۸]', 'And there came a man running, from the farthest end of the city. He said: \"O Moosa (Moses)! Verily, the chiefs are taking counsel together about you, to kill you, so escape.Truly, I am to you of those who give sincere advice.\"', 'And there came a man running from the farthest part of the city. He said, “The chiefs are counseling each other about you, so that they kill you. So, leave (the city). I am one of your well-wishers.”'),
(3273, 28, 21, 2, 5, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَخَرَجَ مِنۡہَا خَآئِفًا یَّتَرَقَّبُ ۫ قَالَ  رَبِّ نَجِّنِیۡ مِنَ الۡقَوۡمِ  الظّٰلِمِیۡنَ ﴿٪۲۱﴾', 'چنانچہ موسٰی  وہاں سے ڈرتے ڈرتے نکل کھڑے ہوئے کہ دیکھیں کیا ہوتا ہے اور دعا کرنے لگے کہ اے پروردگار مجھے ظالم لوگوں سے نجات دے۔', 'پھر نکلا وہاں سے ڈرتا ہوا راہ دیکھتا بولا اے رب بچا لے مجھ کو اس قوم بے انصاف سے', 'So he escaped from there, looking about in a state of fear. He said: \"My Lord! Save me from the people who are Zalimoon (polytheists and wrong-doers)!\"', 'So, he went out of it (the city), looking around in a state of fear. He said, “O my Lord, save me from the cruel people.”'),
(3274, 28, 22, 3, 6, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ لَمَّا تَوَجَّہَ  تِلۡقَآءَ مَدۡیَنَ قَالَ عَسٰی رَبِّیۡۤ   اَنۡ  یَّہۡدِیَنِیۡ  سَوَآءَ  السَّبِیۡلِ ﴿۲۲﴾', 'اور جب انہوں نے مدین کی طرف رخ کیا تو کہنے لگے امید ہے کہ میرا پروردگار مجھے سیدھا رستہ بتائے۔', 'اور جب منہ کیا مدین کی سیدھ پر بولا امید  ہے کہ میرا رب لے جائے مجھ کو سیدھی راہ پر [۲۹]', 'And when he went towards (the land of) Madyan (Midian) he said: \"It may be that my Lord guides me to the Right Way.\"', 'When he set out towards Madyan, he said, “I hope my Lord will guide me to the straight path”.'),
(3275, 28, 23, 3, 6, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ لَمَّا وَرَدَ مَآءَ مَدۡیَنَ وَجَدَ عَلَیۡہِ اُمَّۃً مِّنَ النَّاسِ یَسۡقُوۡنَ ۬۫ وَ  وَجَدَ مِنۡ دُوۡنِہِمُ  امۡرَاَتَیۡنِ تَذُوۡدٰنِ ۚ قَالَ مَا خَطۡبُکُمَا ؕ قَالَتَا لَا نَسۡقِیۡ حَتّٰی یُصۡدِرَ الرِّعَآءُ ٜ وَ اَبُوۡنَا شَیۡخٌ   کَبِیۡرٌ ﴿۲۳﴾', 'اور جب مدین کے پانی کے مقام پر پہنچے تو دیکھا کہ وہاں لوگ جمع ہو رہے اور اپنے مویشیوں کو پانی پلا رہے ہیں اور انکے ایک طرف دو عورتیں اپنی بکریوں کو روکے کھڑی ہیں۔ موسٰی  نے ان سے کہا تمہارا کیا کام ہے۔ وہ بولیں کہ جب تک چرواہے اپنے جانوروں کو لے نہ جائیں ہم پانی نہیں پلا سکتے اور ہمارے والد بڑی عمر کے بوڑھے ہیں۔', 'اور جب پہنچا مدین کے پانی پر پایا وہاں ایک جماعت کو لوگوں کی  پانی پلاتے ہوئے [۳۰] اور پایا ان سے ورے دو عورتوں کو کہ روکے ہوئے کھڑی تھیں اپنی بکریاں بولا تمہارا کیا حال ہے وہ بولیں ہم نہیں پلاتیں پانی چرواہوں کے پھیر لیجانے تک [۳۱] اور ہمارا باپ بوڑھا ہے بڑی عمر کا [۳۲]', 'And when he arrived at the water of Madyan (Midian) he found there a group of men watering (their flocks), and besides them he found two women who were keeping back (their flocks). He said: \"What is the matter with you?\" They said: \"We cannot water (our flocks) until the shepherds take (their flocks). And our father is a very old man.\"', 'And when he arrived at the waters of Madyan, he found a large number of people watering (their animals) and found, aloof from them, two women keeping (their animals) back. He said, “What is the matter with you?” They said, “We cannot water (our animals) until these shepherds take (their animals) back after watering them, and our father is very old man.”'),
(3276, 28, 24, 3, 6, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَسَقٰی لَہُمَا ثُمَّ تَوَلّٰۤی اِلَی الظِّلِّ فَقَالَ رَبِّ اِنِّیۡ لِمَاۤ  اَنۡزَلۡتَ اِلَیَّ مِنۡ خَیۡرٍ  فَقِیۡرٌ ﴿۲۴﴾', 'تو موسٰی  نے انکے لئے بکریوں کو پانی پلا دیا پھر سائے کی طرف چلے گئے۔ اور کہنے لگے کہ پروردگار میں اس کا محتاج ہوں کہ تو مجھ پر اپنی نعمت نازل فرمائے۔', 'پھر اس نے پانی پلا دیا انکے جانوروں کو [۳۳] پھر ہٹ کر آیا چھاؤں کی طرف بولا اے رب تو جو چیز اتارے میری طرف اچھی میں اس کا محتاج ہوں [۳۴]', 'So he watered (their flocks) for them, then he turned back to shade, and said: \"My Lord! Truly, I am in need of whatever good that You bestow on me!\"', 'So he (Mūsā) watered (their animals) for them, then he turned to a shade and said, “My Lord, I am in need of whatever good you send down to me.”'),
(3277, 28, 25, 3, 6, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَجَآءَتۡہُ  اِحۡدٰىہُمَا تَمۡشِیۡ عَلَی اسۡتِحۡیَآءٍ ۫ قَالَتۡ اِنَّ  اَبِیۡ یَدۡعُوۡکَ لِیَجۡزِیَکَ اَجۡرَ مَا سَقَیۡتَ لَنَا ؕ فَلَمَّا جَآءَہٗ  وَ قَصَّ عَلَیۡہِ  الۡقَصَصَ ۙ قَالَ  لَا تَخَفۡ ٝ۟ نَجَوۡتَ مِنَ الۡقَوۡمِ الظّٰلِمِیۡنَ ﴿۲۵﴾', 'تھوڑی دیر کے بعد ان میں سے ایک عورت جو شرماتی اور لجاتی چلی آتی تھی۔ موسٰی  کے پاس آئی کہنے لگی کہ تمکو میرے والد بلاتے ہیں کہ تم نے جو ہمارے لئے پانی پلایا تھا اسکی تمکو اجرت دیں۔ پھر جب وہ انکے پاس آئے اور ان سے اپنا ماجرا بیان کیا تو انہوں نے کہا کہ کچھ خوف نہ کرو۔ تم ظالم لوگوں سے بچ آئے ہو۔', 'پھر آئی اسکے پاس ان دونوں میں سے ایک چلتی تھی شرم سے [۳۵] بولی میرا باپ تجھ کو بلاتا ہے کہ بدلے میں دے حق اس کا کہ تو نے پانی پلا دیا ہمارے جانوروں کو [۳۶] پھر جب پہنچا اسکے پاس اور بیان کیا اس سے احوال کہا مت ڈر بچ آیا تو اس قوم بے انصاف سے [۳۷]', 'Then there came to him one of the two women, walking shyly. She said: \"Verily, my father calls you that he may reward you for having watered (our flocks) for us.\" So when he came to him and narrated the story, he said: \"Fear you not. You have escaped from the people who are Zalimoon (polytheists, disbelievers, and wrong-doers).\"', 'Then one of the two women came to him, walking bashfully. She said, “My father is calling you, so that he may give you a reward for watering our animals. So when he (Mūsā) came to him (the father of the women) and narrated to him the whole story, the latter said, “Do not fear; you have escaped from the wrongdoing people.”'),
(3278, 28, 26, 3, 6, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'قَالَتۡ اِحۡدٰىہُمَا یٰۤاَبَتِ اسۡتَاۡجِرۡہُ ۫ اِنَّ خَیۡرَ مَنِ اسۡتَاۡجَرۡتَ الۡقَوِیُّ الۡاَمِیۡنُ ﴿۲۶﴾', 'ایک لڑکی بولی کہ ابا انکو نوکر رکھ لیجئے کیونکہ بہترین نوکر جو آپ رکھیں وہ ہے جو توانا ہو امانتدار ہو۔', 'بولی ان دونوں میں سے ایک اے باپ اس کو نوکر رکھ لے البتہ بہتر نوکر جو کہ تو رکھنا چاہے وہ ہے جو زور آور ہو امانت دار [۳۸]', 'And said one of them (the two women): \"O my father! Hire him! Verily, the best of men for you to hire is the strong, the trustworthy.\"', 'One of the two women said, “Dear father, hire him; the best man you can hire is someone who is strong, trustworthy.”'),
(3279, 28, 27, 3, 6, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'قَالَ اِنِّیۡۤ  اُرِیۡدُ اَنۡ اُنۡکِحَکَ اِحۡدَی ابۡنَتَیَّ ہٰتَیۡنِ عَلٰۤی اَنۡ تَاۡجُرَنِیۡ ثَمٰنِیَ حِجَجٍ ۚ فَاِنۡ اَتۡمَمۡتَ عَشۡرًا  فَمِنۡ عِنۡدِکَ ۚ وَ مَاۤ  اُرِیۡدُ اَنۡ اَشُقَّ عَلَیۡکَ ؕ سَتَجِدُنِیۡۤ اِنۡ  شَآءَ  اللّٰہُ  مِنَ  الصّٰلِحِیۡنَ ﴿۲۷﴾', 'انہوں نے موسٰی  سے کہا کہ میں چاہتا ہوں کہ اپنی ان دو بیٹیوں میں سے ایک کو تم سے بیاہ دوں اس عہد پر کہ تم آٹھ برس میری خدمت کرو پھر اگر دس سال پورے کر دو تو وہ تمہاری طرف سے احسان ہو گا اور میں تم پر تکلیف ڈالنی نہیں چاہتا۔ تم مجھے ان شاء اللہ نیک لوگوں میں پاؤ گے۔', 'کہا میں چاہتا ہوں کہ بیاہ دوں تجھ کو ایک بیٹی اپنی ان دونوں میں سے اس شرط پر کہ تو میری نوکری کرے آٹھ برس [۳۹] پھر اگر تو پورے کر دے دس برس تو وہ تیری طرف سے ہے [۴۰] اور میں نہیں چاہتا کہ تجھ پر تکلیف ڈالوں تو پائے گا مجھ کو اگر اللہ نے چاہا نیک بختوں سے [۴۱]', 'He said: \"I intend to wed one of these two daughters of mine to you, on condition that you serve me for eight years, but if you complete ten years, it will be (a favour) from you. But I intend not to place you under a difficulty. If Allah will, you will find me one of the righteous.\"', 'He (the father) said (to Mūsā), “I wish to marry to you one of these two daughters of mine on condition that you act as my employee for eight years. Then if you complete ten (years) it will be of your own accord. And I do not want to put you in any trouble; you will find me, Inshā’allah (God-willing) one of the righteous.”'),
(3280, 28, 28, 3, 6, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'قَالَ ذٰلِکَ بَیۡنِیۡ وَ بَیۡنَکَ ؕ اَیَّمَا الۡاَجَلَیۡنِ قَضَیۡتُ فَلَا عُدۡوَانَ عَلَیَّ ؕ وَ اللّٰہُ  عَلٰی  مَا  نَقُوۡلُ  وَکِیۡلٌ ﴿٪۲۸﴾', 'موسٰی  نے کہا کہ مجھ میں اور آپ میں یہ عہد پختہ ہوا میں جو مدت چاہوں پوری کردوں پھر مجھ پر کوئی زیادتی نہ ہو۔ اور ہم جو معاہدہ کرتے ہیں اللہ اس پر گواہ ہے۔', 'بولا یہ وعدہ ہو چکا میرے اور تیرے بیچ جونسی مدت ان دنوں میں پوری کر دوں سو زیادتی نہ ہو مجھ پر اور اللہ پر بھروسہ اس چیز کا جو ہم کہتے ہیں [۴۲]', 'He (Moosa (Moses)) said: \"That (is settled) between me and you whichever of the two terms I fulfill, there will be no injustice to me, and Allah is Surety over what we say.\"', 'He (Mūsā) said, “This is (done) between me and you. Whichever of the two terms I fulfill, there should be no excess against me, and Allah is witness to what we are saying.”'),
(3281, 28, 29, 4, 7, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَلَمَّا قَضٰی مُوۡسَی الۡاَجَلَ وَ سَارَ بِاَہۡلِہٖۤ  اٰنَسَ مِنۡ جَانِبِ الطُّوۡرِ نَارًا ۚ قَالَ  لِاَہۡلِہِ  امۡکُثُوۡۤا  اِنِّیۡۤ  اٰنَسۡتُ نَارًا لَّعَلِّیۡۤ  اٰتِیۡکُمۡ مِّنۡہَا بِخَبَرٍ اَوۡ جَذۡوَۃٍ مِّنَ النَّارِ  لَعَلَّکُمۡ  تَصۡطَلُوۡنَ ﴿۲۹﴾', 'پھر جب موسٰی  نے مدت پوری کر دی اور اپنے گھر کے لوگوں کو لے کر چلے تو طور کی طرف سے آگ دکھائی دی وہ اپنے گھر والوں سے کہنے لگے کہ تم یہاں ٹھہرو۔ مجھے آگ نظر آئی ہے شاید میں وہاں سے رستے کا کچھ پتہ لاؤں یا آگ کا انگارہ لے آؤں تاکہ تم آگ تاپو۔', 'پھر جب پوری کر چکا موسٰیؑ وہ مدت اور لیکر چلا اپنے گھر  والوں کو دیکھی کوہ طور کی طرف سے ایک آگ کہا اپنے گھر والوں کو ٹھہرو میں نے دیکھی ہے ایک آگ شاید لے آؤں تمہارے پاس وہاں کی کچھ خبر یا انگارا آگ کا تاکہ تم تاپو', 'Then, when Moosa (Moses) had fulfilled the term, and was travelling with his family, he saw a fire in the direction of Toor (Mount). He said to his family: \"Wait, I have seen a fire; perhaps I may bring to you from there some information, or a burning fire-brand that you may warm yourselves.\"', 'So, when Mūsā completed the term and set forth with his wife, he noticed a fire from the direction of (the mount) Tūr, he said to his wife, “Stay here; I have noticed a fire. May be I bring to you some information or an ember from the fire, so that you may warm yourself.”'),
(3282, 28, 30, 4, 7, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَلَمَّاۤ  اَتٰىہَا نُوۡدِیَ مِنۡ شَاطِیَٔ الۡوَادِ الۡاَیۡمَنِ فِی الۡبُقۡعَۃِ  الۡمُبٰرَکَۃِ مِنَ الشَّجَرَۃِ  اَنۡ یّٰمُوۡسٰۤی  اِنِّیۡۤ  اَنَا اللّٰہُ  رَبُّ الۡعٰلَمِیۡنَ ﴿ۙ۳۰﴾', 'سو جب اس کے پاس پہنچے تو میدان کے دائیں کنارے سے ایک مبارک جگہ میں ایک درخت میں سے آواز آئی کہ اے موسٰی یہ میں ہوں اللہ تمام جہانوں کا پروردگار۔', 'پھر جب پہنچا اسکے پاس آواز ہوئی میدان کے داہنے کنارے سے برکت  والے تختہ میں ایک درخت سے [۴۳] کہ اے موسٰی میں ہوں میں اللہ جہان کا رب', 'So when he reached it (the fire), he was called from the right side of the valley, in the blessed place from the tree: \"O Moosa (Moses)! Verily! I am Allah, the Lord of the Alameen (mankind, jinns and all that exists)!', 'So when he came to it, he was called by a voice coming from a side of the right valley in the blessed ground, from the tree, saying, “O Mūsā, I AM ALLAH, the Lord of the worlds,”'),
(3283, 28, 31, 4, 7, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ اَنۡ  اَلۡقِ عَصَاکَ ؕ فَلَمَّا رَاٰہَا تَہۡتَزُّ کَاَنَّہَا جَآنٌّ  وَّلّٰی مُدۡبِرًا وَّ لَمۡ  یُعَقِّبۡ ؕ یٰمُوۡسٰۤی اَقۡبِلۡ وَ لَا تَخَفۡ ۟ اِنَّکَ مِنَ الۡاٰمِنِیۡنَ ﴿۳۱﴾', 'اور یہ کہ اپنی لاٹھی ڈال دو۔ سو جب انہوں نے دیکھا کہ وہ حرکت کر رہی ہے گویا سانپ ہے تو پیٹھ پھیر کر چل دیئے اور پیچھے مڑ کر بھی نہ دیکھا۔ فرمایا موسٰی  آگے آؤ اور ڈرو مت تم امن پانے والوں میں ہو۔', 'اور یہ کہ ڈالدے اپنی لاٹھی پھر جب دیکھا اسکو پھنپناتے جیسے سانپ کی سٹک الٹا پھرا منہ موڑ کر اور نہ دیکھا پیچھے پھر کر اے موسٰی آگے آ اور مت ڈر تجھ کو کچھ خطرہ نہیں', '\"And throw your stick!\" But when he saw it moving as if it were a snake, he turned in flight, and looked not back. (It was said): \"O Moosa (Moses)! Draw near, and fear not. Verily, you are of those who are secure.', 'and saying, “Throw down your staff.” So when he saw it moving as if it were a snake, he turned back in retreat, and did not look back. (Allah said to him), “O Mūsā come forward and do not fear; you are one of those in peace.'),
(3284, 28, 32, 4, 7, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'اُسۡلُکۡ یَدَکَ فِیۡ جَیۡبِکَ تَخۡرُجۡ بَیۡضَآءَ مِنۡ غَیۡرِ سُوۡٓءٍ ۫ وَّ اضۡمُمۡ  اِلَیۡکَ جَنَاحَکَ مِنَ الرَّہۡبِ فَذٰنِکَ بُرۡہَانٰنِ مِنۡ رَّبِّکَ اِلٰی فِرۡعَوۡنَ وَ مَلَا۠ئِہٖ ؕ اِنَّہُمۡ کَانُوۡا قَوۡمًا فٰسِقِیۡنَ ﴿۳۲﴾', 'اپنا ہاتھ گریبان میں ڈالو تو بغیر کسی عیب کے سفید روشن ہو کر نکل آئے گا اور خوف دور کرنے کی غرض سے اپنے بازو کو اپنی طرف یعنی سینے سے ملا لو۔ یہ دو دلیلیں تمہارے پروردگار کی طرف سے ہیں فرعون اور اسکے درباریوں کیلئے بیشک وہ نافرمان لوگ ہیں۔', 'ڈال اپنا ہاتھ اپنے گریبان میں نکل آئے سفید ہو کر نہ کہ کسی برائی سے [۴۴] اور ملا لے اپنی طرف اپنا بازو ڈر سے [۴۵] سو یہ دو سندیں ہیں تیرے رب کی طرف سے فرعون اور اسکے سرداروں پر [۴۶] بیشک وہ تھے لوگ نافرمان', '\"Put your hand in your bosom, it will come forth white without a disease, and draw your hand close to your side to be free from fear (that which you suffered from the snake, and also by that your hand will return to its original state). these are two Burhan (signs, miracles, evidences, proofs) from your Lord to Firaun (Pharaoh) and his chiefs. Verily, they are the people who are Fasiqoon (rebellious, disobedient to Allah).', 'Insert your hand into your bosom, and it will come out white without any evil (disease), and press your arm to your side for (removing) fear. Thus these are two proofs from your Lord (sent) to Pharaoh and his chiefs. Indeed they are transgressing people.”'),
(3285, 28, 33, 4, 7, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'قَالَ رَبِّ اِنِّیۡ قَتَلۡتُ مِنۡہُمۡ نَفۡسًا فَاَخَافُ اَنۡ یَّقۡتُلُوۡنِ ﴿۳۳﴾', 'موسٰی  نے کہا اے پروردگار ان میں کا ایک شخص میرے ہاتھ سے قتل ہو چکا ہے سو مجھے خوف ہے کہ وہ  مجھ کو مار ڈالیں گے۔', 'بولا اے رب میں نے خون کیا ہے ان میں ایک جان کا سو ڈرتا ہوں کہ مجھ کو مار ڈالیں گے [۴۷]', 'He said: \"My Lord! I have killed a man among them, and I fear that they will kill me.', 'He said, “My Lord, I have killed a person from them, therefore I fear that they will kill me.'),
(3286, 28, 34, 4, 7, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ اَخِیۡ ہٰرُوۡنُ ہُوَ اَفۡصَحُ مِنِّیۡ لِسَانًا فَاَرۡسِلۡہُ  مَعِیَ رِدۡاً  یُّصَدِّقُنِیۡۤ  ۫ اِنِّیۡۤ   اَخَافُ  اَنۡ  یُّکَذِّبُوۡنِ ﴿۳۴﴾', 'اور ہارون  جو میرا بھائی ہے اسکی زبان مجھ سے زیادہ فصیح ہے تو اسکو میرے ساتھ مددگار بنا کر بھیج کہ میری تصدیق کرے مجھے خوف ہے کہ وہ لوگ میری تکذیب کریں گے۔', 'اور میرا بھائی ہارون اس کی زبان چلتی ہے مجھ سے زیادہ سو اس کو بھیج میرے ساتھ مدد کو کہ میری تصدیق کرے میں ڈرتا ہوں کہ مجھ کو جھوٹا کریں [۴۸]', '\"And my brother Haroon (Aaron) he is more eloquent in speech than me so send him with me as a helper to confirm me. Verily! I fear that they will belie me.\"', 'And my brother Hārūn is more eloquent than me in speech; so send him with me as a helper to bear me out. I am afraid, they will give the lie to me.”'),
(3287, 28, 35, 4, 7, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'قَالَ سَنَشُدُّ عَضُدَکَ بِاَخِیۡکَ وَ نَجۡعَلُ لَکُمَا سُلۡطٰنًا فَلَا یَصِلُوۡنَ  اِلَیۡکُمَا ۚۛ بِاٰیٰتِنَاۤ ۚۛ اَنۡتُمَا وَ مَنِ اتَّبَعَکُمَا الۡغٰلِبُوۡنَ ﴿۳۵﴾', 'فرمایا ہم تمہارے بھائی کے ذریعے تمہارے بازو کو مضبوط کریں گے اور تم دونوں کو غلبہ دیں گے تو ہماری نشانیوں کے سبب وہ تم تک پہنچ نہ سکیں گے  تم دونوں اور جنہوں نے تمہاری پیروی کی وہی غالب رہیں گے۔', 'فرمایا ہم مضبوط کر دیں گے تیرے بازو کو تیرے بھائی سے اور دیں گے تم کو غلبہ پھر وہ نہ پہنچ سکیں گے تم تک ہماری نشانیوں سے تم اور جو تمہارے ساتھ ہو غالب رہو گے [۴۹]', 'Allah said: \"We will strengthen your arm through your brother, and give you both power, so they shall not be able to harm you, with Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), you two as well as those who follow you will be the victors.\"', 'He (Allah) said, “We will strengthen your arm with your brother, and will give both of you such a power that they will have no access to you (to cause any harm) because of Our signs.10 You and your followers will be the victors.”'),
(3288, 28, 36, 4, 7, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَلَمَّا جَآءَہُمۡ مُّوۡسٰی بِاٰیٰتِنَا بَیِّنٰتٍ قَالُوۡا مَا ہٰذَاۤ  اِلَّا سِحۡرٌ مُّفۡتَرًی وَّ مَا سَمِعۡنَا بِہٰذَا  فِیۡۤ   اٰبَآئِنَا  الۡاَوَّلِیۡنَ ﴿۳۶﴾', 'پھر جب موسٰی  انکے پاس ہماری کھلی نشانیاں لے کر آئے تو وہ کہنے لگے کہ یہ تو جادو ہے جو اس نے بنا کھڑا کیا ہے اور یہ باتیں ہم نے اپنے اگلے باپ دادا میں تو کبھی سنی نہیں۔', 'پھر جب پہنچا انکے پاس موسٰی لیکر ہماری نشانیاں کھلی ہوئی بولے اور کچھ نہیں یہ جادو ہے باندھا ہوا [۵۰] اور ہم نے سنا نہیں یہ اپنے اگلے باپ دادوں میں [۵۱]', 'Then when Moosa (Moses) came to them with Our Clear Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), they said: \"This is nothing but invented magic. Never did we hear of this among our fathers of old.\"', 'So when Mūsā came to them with Our clear signs, they said, “This is nothing but a forged magic, and we have never heard of such a thing happening in the days of our forefathers.”'),
(3289, 28, 37, 4, 7, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ قَالَ  مُوۡسٰی رَبِّیۡۤ  اَعۡلَمُ بِمَنۡ جَآءَ بِالۡہُدٰی مِنۡ عِنۡدِہٖ  وَ مَنۡ تَکُوۡنُ لَہٗ عَاقِبَۃُ  الدَّارِ ؕ اِنَّہٗ  لَا یُفۡلِحُ  الظّٰلِمُوۡنَ ﴿۳۷﴾', 'اور موسٰی  نے کہا کہ میرا پروردگار اس شخص کو خوب جانتا ہے جو اسکی طرف سے ہدایت لے کر آیا ہے اور جسکے لئے عاقبت کا گھر یعنی بہشت ہے۔ بیشک ظالم کامیاب نہیں ہونگے۔', 'اور کہا موسٰی نے میرا رب تو خوب جانتا ہے جو کوئی لایا ہے ہدایت کی بات اس کے پاس سے اور جس کو ملے گا آخرت کا گھر بیشک بھلا نہ ہوگا بے انصافوں کا [۵۲]', 'Moosa (Moses) said: \"My Lord knows best him who came with guidance from Him, and whose will be the happy end in the Hereafter. Verily, the Zalimoon (wrong-doers, polytheists and disbelievers in the Oneness of Allah) will not be successful.\"', 'Mūsā said, “My Lord is best aware of the one who has brought guidance from Him and who is going to meet the best end of the abode. It is certain that the wrongdoers will not succeed.”'),
(3290, 28, 38, 4, 7, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ قَالَ فِرۡعَوۡنُ یٰۤاَیُّہَا الۡمَلَاُ  مَا عَلِمۡتُ لَکُمۡ مِّنۡ  اِلٰہٍ غَیۡرِیۡ ۚ فَاَوۡقِدۡ لِیۡ یٰہَامٰنُ عَلَی الطِّیۡنِ فَاجۡعَلۡ  لِّیۡ صَرۡحًا لَّعَلِّیۡۤ اَطَّلِعُ  اِلٰۤی  اِلٰہِ مُوۡسٰی ۙ وَ اِنِّیۡ لَاَظُنُّہٗ مِنَ  الۡکٰذِبِیۡنَ ﴿۳۸﴾', 'اور فرعون نے کہا کہ اے اہل دربار میں اپنے سوا کسی کو تمہارا خدا نہیں جانتا سو اے ہامان میرے لئے گارے کو آگ لگا کر اینٹیں پکا دو پھر ایک اونچا محل بنا دو تاکہ میں موسٰی  کےخدا کی طرف چڑھ کر اسے جھانک لوں اور میں تو اسے جھوٹا سمجھتا ہوں۔', 'اور بولا فرعون اے دربار والو مجھ کو تو معلوم نہیں تمہارا کوئی حاکم ہو میرے سوا سو آگ دے اے ہامان میرے واسطے گارے کو پھر بنا میرے واسطے ایک محل تا کہ میں جھانک کر دیکھ لوں موسٰی کے رب کو اور میری اٹکل میں تو وہ جھوٹا ہے [۵۳]', 'Firaun (Pharaoh) said: \"O chiefs! I know not that you have an ilah (a god) other than me, so kindle for me (a fire), O Haman, to bake (bricks out of) clay, and set up for me a Sarhan (a lofty tower, or palace, etc.) in order that I may look at (or look for) the Ilah (God) of Moosa (Moses); and verily, I think that he (Moosa (Moses)) is one of the liars.\"', 'And Pharaoh said (to his people,) “O courtiers, I do not recognize any god for you other than me. So kindle for me, O Hāmān, a fire on the clay (to bake bricks) and build for me a tower, so that I may look on to the God of Mūsā. I deem him to be one of the liars.”'),
(3291, 28, 39, 4, 7, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ اسۡتَکۡبَرَ ہُوَ وَ جُنُوۡدُہٗ  فِی الۡاَرۡضِ بِغَیۡرِ الۡحَقِّ وَ ظَنُّوۡۤا اَنَّہُمۡ  اِلَیۡنَا لَا یُرۡجَعُوۡنَ ﴿۳۹﴾', 'اور وہ اور اس کے لشکر ملک میں ناحق مغرور ہو رہے تھے اور خیال کرتے تھے کہ وہ ہماری طرف لوٹ کر نہیں آئیں گے۔', 'اور بڑائی کرنے لگے وہ اور اس کے لشکر ملک میں ناحق اور سمجھے کہ وہ ہماری طرف پھر کر نہ آئیں گے', 'And he and his hosts were arrogant in the land, without right, and they thought that they would never return to Us.', '(Thus) he and his hosts showed arrogance in the land with no justification and thought that they would not be returned to Us.'),
(3292, 28, 40, 4, 7, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَاَخَذۡنٰہُ وَ جُنُوۡدَہٗ  فَنَبَذۡنٰہُمۡ فِی الۡیَمِّ ۚ فَانۡظُرۡ کَیۡفَ کَانَ عَاقِبَۃُ  الظّٰلِمِیۡنَ ﴿۴۰﴾', 'تو ہم نے اسے اور اسکے لشکروں کو پکڑ لیا آخر ہم نے انہیں سمندر میں پھینک دیا۔ سو دیکھ لو کہ ظالموں کا کیسا انجام ہوا۔', 'پھر پکڑ اہم نے اسکو اور اسکے لشکروں کو پھر پھینک دیا ہم نے انکو دریا میں سو دیکھ لے کیسا ہوا انجام گنہگاروں کا [۵۴]', 'So We seized him and his hosts, and We threw them all into the sea (and drowned them). So behold (O Muhammad SAW) what was the end of the Zalimoon (wrong-doers, polytheists and those who disbelieved in the Oneness of their Lord (Allah), or rejected the advice of His Messenger Moosa (Moses) ).', 'So We seized him and his hosts and threw them into the sea. Look then, how was the fate of the wrongdoers.'),
(3293, 28, 41, 4, 7, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ جَعَلۡنٰہُمۡ  اَئِمَّۃً  یَّدۡعُوۡنَ  اِلَی النَّارِ ۚ وَ  یَوۡمَ  الۡقِیٰمَۃِ  لَا  یُنۡصَرُوۡنَ ﴿۴۱﴾', 'اور ہم نے انکو پیشوا بنایا تھا وہ لوگوں کو دوزخ کی طرف بلاتے تھے اور قیامت کے دن انکی مدد نہیں کی جائے گی۔', 'اور کیا ہم نے ان کو پیشوا کہ بلاتے ہیں دوزخ کی طرف [۵۵] اور قیامت کے دن ان کو مدد نہ ملے گی [۵۶]', 'And We made them leaders inviting to the Fire, and on the Day of Resurrection, they will not be helped.', 'We made them leaders who called (people) towards hell; and on the Day of Judgment, they will not be helped.'),
(3294, 28, 42, 4, 7, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ اَتۡبَعۡنٰہُمۡ فِیۡ ہٰذِہِ الدُّنۡیَا لَعۡنَۃً ۚ وَ یَوۡمَ الۡقِیٰمَۃِ ہُمۡ مِّنَ الۡمَقۡبُوۡحِیۡنَ ﴿٪۴۲﴾', 'اور اس دنیا سے ہم نے ان کے پیچھے لعنت لگا دی اور وہ قیامت کے روز بھی بدحالوں میں ہوں گے۔', 'اور پیچھے رکھ دی ہم نے ان پر اس دنیا میں پھٹکار اور قیامت کے دن ان پر برائی ہے [۵۷]', 'And We made a curse to follow them in this world, and on the Day of Resurrection, they will be among Al-Maqbuhoon (those who are prevented to receive Allahs Mercy or any good, despised or destroyed, etc.).', 'And We made a curse to pursue them in this world; and on the Day of Judgment they will be among those dejected.'),
(3295, 28, 43, 5, 8, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ لَقَدۡ اٰتَیۡنَا مُوۡسَی الۡکِتٰبَ مِنۡۢ بَعۡدِ مَاۤ اَہۡلَکۡنَا الۡقُرُوۡنَ الۡاُوۡلٰی بَصَآئِرَ لِلنَّاسِ وَ ہُدًی وَّ رَحۡمَۃً  لَّعَلَّہُمۡ  یَتَذَکَّرُوۡنَ ﴿۴۳﴾', 'اور ہم نے پہلی امتوں کے ہلاک کرنے کے بعد موسٰی  کو کتاب دی جو لوگوں کے لئے بصیرت اور ہدایت اور رحمت ہے تاکہ وہ نصیحت حاصل کریں۔', 'اور دی ہم نے موسٰیؑ کو کتاب بعد ا سکے کہ ہم غارت کر چکے پہلی جماعتوں کو [۵۸] سمجھانے والی لوگوں کو اور راہ بتانے والی اور رحمت تاکہ وہ یاد رکھیں [۵۹]', 'And indeed We gave Moosa (Moses), after We had destroyed the generations of old, the Scripture (the Taurat (Torah)) as an enlightenment for mankind, and a guidance and a mercy, that they might remember (or receive admonition).', 'And We gave Mūsā, after We destroyed the earlier generations, the Book having insights for people and a guidance and mercy, so that they may receive the advice.'),
(3296, 28, 44, 5, 8, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ مَا کُنۡتَ بِجَانِبِ الۡغَرۡبِیِّ  اِذۡ  قَضَیۡنَاۤ اِلٰی مُوۡسَی الۡاَمۡرَ  وَ مَا کُنۡتَ  مِنَ  الشّٰہِدِیۡنَ ﴿ۙ۴۴﴾', 'اور جب ہم نے موسٰی  کی طرف حکم بھیجا تھا تو تم طور کی مغربی جانب نہیں تھے اور نہ اس واقعے کے دیکھنے والوں میں تھے۔', 'اور تو نہ تھا غرب کی طرف جب ہم نے بھیجا موسٰیؑ کو حکم [۶۰] اور نہ تھا تو دیکھنے والا', 'And you (O Muhammad SAW) were not on the western side (of the Mount), when We made clear to Moosa (Moses) the commandment, and you were not among those present.', 'And (O prophet,) you were not there at the Western side (of the mount Tūr) when We delegated the matter to Mūsā, nor were you among those present,'),
(3297, 28, 45, 5, 8, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ لٰکِنَّاۤ  اَنۡشَاۡنَا قُرُوۡنًا فَتَطَاوَلَ عَلَیۡہِمُ الۡعُمُرُ ۚ وَ مَا کُنۡتَ ثَاوِیًا فِیۡۤ  اَہۡلِ مَدۡیَنَ تَتۡلُوۡا عَلَیۡہِمۡ اٰیٰتِنَا ۙ وَ لٰکِنَّا کُنَّا  مُرۡسِلِیۡنَ ﴿۴۵﴾', 'لیکن ہم نے موسٰی  کے بعد کئ امتوں کو پیدا کیا پھر ان پر ایک لمبی مدت گذر گئ اور نہ تم مدین والوں میں رہنے والے تھے کہ انکو ہماری آیتیں پڑھ پڑھ کر سناتے تھے۔ اور ہاں ہم ہی تو پیغمبر بھیجنے والے تھے۔', 'لیکن ہم نے پیدا کیں کئ جماعتیں پھر دراز ہوئی ان پر مدت [۶۱] اور تو نہ رہتا تھا مدین والوں میں کہ ان کو سناتا ہماری آیتیں پر ہم رہے ہیں رسول بھیجتے [۶۲]', 'But We created generations (after generations i.e. after Moosa (Moses) ), and long were the ages that passed over them. And you (O Muhammad SAW) were not a dweller among the people of Madyan (Midian), reciting Our Verses to them. But it is We Who kept sending (Messengers).', 'but We created generations (after him) and a long time passed over them. And you were not dwelling among the people of Madyan, reciting Our verses to them, but it is We who do send messengers.'),
(3298, 28, 46, 5, 8, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ مَا کُنۡتَ بِجَانِبِ الطُّوۡرِ  اِذۡ نَادَیۡنَا وَ لٰکِنۡ رَّحۡمَۃً مِّنۡ رَّبِّکَ لِتُنۡذِرَ قَوۡمًا مَّاۤ  اَتٰىہُمۡ مِّنۡ نَّذِیۡرٍ  مِّنۡ قَبۡلِکَ  لَعَلَّہُمۡ  یَتَذَکَّرُوۡنَ ﴿۴۶﴾', 'اور نہ تم اس وقت جب کہ ہم نے موسٰی  کو آواز دی طور کے کنارے تھے۔ بلکہ تمہارا بھیجا جانا تمہارے پروردگار کی رحمت ہے تاکہ تم ان لوگوں کو جنکے پاس تم سے پہلے کوئی خبردار کرنے والا نہیں آیا خبردار کرو تاکہ وہ نصیحت حاصل کریں۔', 'اور تو نہ تھاطور کے کنارے جب ہم نے  آواز دی لیکن یہ انعام ہے تیرے رب کا [۶۳] تاکہ تو ڈر سنا دے ان لوگوں کو جنکے پاس نہیں آیا کوئی ڈر سنانے  والا تجھ سے پہلے تاکہ وہ یاد رکھیں [۶۴]', 'And you (O Muhammad SAW) were not at the side of the Toor (Mount) when We did call, (it is said that Allah called the followers of Muhammad SAW , and they answered His Call, or that Allah called Moosa (Moses)). But (you are sent) as a mercy from your Lord, to give warning to a people to whom no warner had come before you, in order that they may remember or receive admonition. (Tafsir At-Tabaree, Vol. 20, Page 81).', 'And you were not at the side of (the mount) Tūr when We called (Mūsā), but it (your prophet-hood through which you knew all this) is a mercy from your Lord, so that you warn a people to whom no warner has come before you, that they may receive the advice.'),
(3299, 28, 47, 5, 8, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ لَوۡ لَاۤ  اَنۡ تُصِیۡبَہُمۡ مُّصِیۡبَۃٌۢ  بِمَا قَدَّمَتۡ  اَیۡدِیۡہِمۡ فَیَقُوۡلُوۡا رَبَّنَا لَوۡ لَاۤ اَرۡسَلۡتَ  اِلَیۡنَا رَسُوۡلًا فَنَتَّبِعَ اٰیٰتِکَ وَ نَکُوۡنَ  مِنَ  الۡمُؤۡمِنِیۡنَ ﴿۴۷﴾', 'اور اے پیغمبر ہم نے تمکو اس لئے بھیجا ہے کہ ایسا نہ ہو کہ اگر ان اعمال کے سبب جو انکے ہاتھ آگے بھیج چکے ہیں ان پر کوئی مصیبت واقع ہو تو یہ کہنے لگیں کہ اے پروردگار تو نے ہماری طرف کوئی پیغمبر کیوں نہ بھیجا کہ ہم تیری آیتوں کی پیروی کرتے اور ایمان لانے والوں میں ہوتے۔', 'اور اتنی بات کےلئے کہ کبھی آن پڑے ان پر آفت ان کاموں کی وجہ سے جنکو  بھیج چکے ہیں انکے ہاتھ تو کہنے لگیں اے رب ہمارے کیوں نہ بھیج دیا ہمارے پاس کسی کو پیغام دے کر تو ہم چلتے تیری باتوں پر اور ہوتے ایمان والوں میں [۶۵]', 'And if (We had) not (sent you to the people of Makkah) in case a calamity should seize them for (the deeds) that their hands have sent forth, they should have said: \"Our Lord! Why did You not send us a Messenger? We should then have followed Your Ayat (Verses of the Quran) and should have been among the believers.\"', 'And (We have sent you as a messenger) lest, in case they suffered a calamity because of what their hands sent ahead, they should say, “Our Lord, why did You not send a messenger to us, so that we might have followed your verses and been among the believers?”'),
(3300, 28, 48, 5, 8, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَلَمَّا جَآءَہُمُ الۡحَقُّ مِنۡ عِنۡدِنَا قَالُوۡا لَوۡ لَاۤ  اُوۡتِیَ  مِثۡلَ  مَاۤ   اُوۡتِیَ  مُوۡسٰی ؕ اَوَ لَمۡ  یَکۡفُرُوۡا بِمَاۤ  اُوۡتِیَ  مُوۡسٰی  مِنۡ  قَبۡلُ ۚ قَالُوۡا  سِحۡرٰنِ تَظٰہَرَا ۟ٝ وَ قَالُوۡۤا اِنَّا بِکُلٍّ  کٰفِرُوۡنَ ﴿۴۸﴾', 'پھر جب انکے پاس ہماری طرف سے حق آ پہنچا تو کہنے لگے کہ جیسی نشانیاں موسٰی کو ملی تھیں ویسی اسکو کیوں نہیں ملیں۔ کیا جو نشانیاں پہلے موسٰی  کو دی گئ تھیں انہوں نے ان سے کفر نہیں کیا؟ کہنے لگے کہ دونوں جادوگر ہیں ایک دوسرے کے موافق۔ اور بولے کہ ہم سب سے منکر ہیں۔', 'پھر جب پہنچی ان کو ٹھیک بات ہمارے پاس سے کہنے لگے کیوں نہ ملا اس رسول کو جیسا ملا تھا موسٰی کو [۶۶] کیا ابھی منکر نہیں ہو چکے اس سے جو موسیٰ کو ملا تھا اس سے پہلے [۶۷] کہنے لگے دونوں جادو  ہیں آپس میں موافق اور کہنے لگے ہم دونوں کو نہیں مانتے [۶۸]', 'But when the truth (i.e. Muhammad SAW with his Message) has come to them from Us, they say: \"Why is he not given the like of what was given to Moosa (Moses)? Did they not disbelieve in that which was given to Moosa (Moses) of old? They say: \"Two kinds of magic (the Taurat (Torah) and the Quran) each helping the other!\" And they say: \"Verily! In both we are disbelievers.\"', 'But when the Truth came to them from Us, they said, “Why has he (the messenger) not been given (a book) similar to what Mūsā had been given?” Is it not that they denied what Mūsā had been given before? They said, “Both (Qur’ān and Torah) are works of magic that support each other.” And they said, “We disbelieve each one of them.”'),
(3301, 28, 49, 5, 8, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'قُلۡ فَاۡتُوۡا بِکِتٰبٍ مِّنۡ عِنۡدِ اللّٰہِ ہُوَ اَہۡدٰی مِنۡہُمَاۤ  اَتَّبِعۡہُ  اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ ﴿۴۹﴾', 'کہدو کہ اگر سچے ہو تو تم اللہ کے پاس سے کوئی اور کتاب لے آؤ جو ان دونوں کتابوں سے بڑھ کر ہدایت کرنے والی ہو۔ تاکہ میں بھی اسی کی پیروی کروں۔', 'تو کہہ اب تم لاؤ کوئی کتاب اللہ کے پاس کی جو ان دونوں سے بہتر ہو کہ میں اس پر چلوں اگر تم سچے ہو [۶۹]', 'Say (to them, O Muhammad SAW): \"Then bring a Book from Allah, which is a better guide than these two (the Taurat (Torah) and the Quran), that I may follow it, if you are truthful.\"', 'Say, “Then bring a book from Allah which is better than both, in guidance, and I shall follow it, if you are true.”'),
(3302, 28, 50, 5, 8, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَاِنۡ لَّمۡ یَسۡتَجِیۡبُوۡا لَکَ فَاعۡلَمۡ  اَنَّمَا یَتَّبِعُوۡنَ  اَہۡوَآءَہُمۡ ؕ وَ مَنۡ اَضَلُّ  مِمَّنِ اتَّبَعَ ہَوٰىہُ بِغَیۡرِ ہُدًی مِّنَ اللّٰہِ ؕ اِنَّ اللّٰہَ  لَا  یَہۡدِی الۡقَوۡمَ الظّٰلِمِیۡنَ ﴿٪۵۰﴾', 'پھر اگر یہ تمہاری بات قبول نہ کریں تو جان لو کہ یہ صرف اپنی خواہشوں کی پیروی کرتے ہیں۔ اور اس سے زیادہ کون گمراہ ہو گا جو اللہ کی ہدایات کو چھوڑ کر اپنی خواہش کے پیچھے چلے۔ بیشک اللہ ظالم لوگوں کو ہدایت نہیں دیتا۔', 'پھر اگر نہ کر لائیں تیرا کہا تو جان لے کہ وہ چلتے ہیں نری اپنی خواہشوں پر اور اس سے گمراہ زیادہ کون جو چلے اپنی خواہش پر بدون راہ بتلائے اللہ کے بیشک اللہ راہ نہیں دیتا بے انصاف لوگوں کو [۷۰]', 'But if they answer you not (i.e. do not believe in your doctrine of Islamic Monotheism, nor follow you), then know that they only follow their own lusts. And who is more astray than one who follows his own lusts, without guidance from Allah? Verily! Allah guides not the people who are Zalimoon (wrong-doers, disobedient to Allah, and polytheists).', 'So if they do not respond to you, be sure that they are only following their desires. And who is more astray than the one who follows his desire without guidance from Allah. Surely Allah does not take the wrongdoing people onto the right path.'),
(3303, 28, 51, 6, 9, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ لَقَدۡ وَصَّلۡنَا لَہُمُ الۡقَوۡلَ لَعَلَّہُمۡ یَتَذَکَّرُوۡنَ ﴿ؕ۵۱﴾', 'اور ہم پے در پے ان لوگوں کے پاس ہدایت کی باتیں بھیجتے رہے ہیں تاکہ نصیحت حاصل کریں۔', 'اور ہم پے درپے بھیجتے رہے ہیں انکو اپنے کلام تاکہ وہ دھیان میں لائیں [۷۱]', 'And indeed now We have conveyed the Word (this Quran in which is the news of everything to them), in order that they may remember (or receive admonition).', 'And We have conveyed (Our) word to them one after the other, so that they may receive the advice.'),
(3304, 28, 52, 6, 9, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'اَلَّذِیۡنَ اٰتَیۡنٰہُمُ الۡکِتٰبَ مِنۡ قَبۡلِہٖ ہُمۡ بِہٖ یُؤۡمِنُوۡنَ ﴿۵۲﴾', 'جن لوگوں کو ہم نے اس سے پہلے کتاب دی تھی وہ اس پر ایمان لے آتے ہیں۔', 'جن کو ہم نے دی ہے کتاب اس سے پہلے وہ اس پر یقین کرتے ہیں', 'Those to whom We gave the Scripture (i.e. the Taurat (Torah) and the Injeel (Gospel), etc.) before it, - they believe in it (the Quran).', 'As for those to whom We gave the Book before this, they believe in it (Qur’ān).'),
(3305, 28, 53, 6, 9, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ  اِذَا یُتۡلٰی عَلَیۡہِمۡ  قَالُوۡۤا اٰمَنَّا بِہٖۤ  اِنَّہُ الۡحَقُّ مِنۡ رَّبِّنَاۤ  اِنَّا کُنَّا مِنۡ قَبۡلِہٖ مُسۡلِمِیۡنَ ﴿۵۳﴾', 'اور جب قرآن انکو پڑھ کو سنایا جاتا ہے تو کہتے ہیں کہ ہم اس پر ایمان لے آئے بیشک یہ ہمارے پروردگار کی طرف سے برحق ہے اور ہم تو اس سے پہلے کے حکم بردار ہیں۔', 'اور جب ان کو سنائے تو کہیں ہم یقین لائے اس پر یہی ہے ٹھیک ہمارے رب کا بھیجا ہوا ہم ہیں اس سے پہلے کے حکم بردار [۷۲]', 'And when it is recited to them, they say: \"We believe in it. Verily, it is the truth from our Lord. Indeed even before it we have been from those who submit themselves to Allah in Islam as Muslims (like Abdullah bin Salam and Salman Al-Farisee, etc.).', 'And when this (Qur’ān) is recited to them, they say, “We believe in it. It is the truth from our Lord, and we are the ones who had submitted (to it) even before it (was revealed).”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(3306, 28, 54, 6, 9, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'اُولٰٓئِکَ یُؤۡتَوۡنَ اَجۡرَہُمۡ مَّرَّتَیۡنِ بِمَا صَبَرُوۡا وَ یَدۡرَءُوۡنَ بِالۡحَسَنَۃِ  السَّیِّئَۃَ  وَ  مِمَّا  رَزَقۡنٰہُمۡ  یُنۡفِقُوۡنَ ﴿۵۴﴾', 'ان لوگوں کو دگنا بدلہ دیا جائے گا کیونکہ صبر کرتے رہے ہیں اور بھلائی کے ساتھ برائی کو دور کرتے ہیں اور جو مال ہم نے انکو دیا ہے اس میں سے خرچ کرتے ہیں۔', 'وہ لوگ پائیں گے اپنا ثواب دوہرا اس بات پر کہ قائم رہے [۷۳] اور بھلائی کرتے ہیں برائی کے جواب میں [۷۴] اور ہمارا دیا ہو کچھ خرچ کرتے رہتے ہیں [۷۵]', 'These will be given their reward twice over, because they are patient, and repel evil with good, and spend (in charity) out of what We have provided them.', 'Such people will be given their reward twice, because they observed patience. And they repel evil with good, and spend from what We have given to them.'),
(3307, 28, 55, 6, 9, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ اِذَا سَمِعُوا اللَّغۡوَ اَعۡرَضُوۡا عَنۡہُ وَ قَالُوۡا لَنَاۤ  اَعۡمَالُنَا وَ لَکُمۡ  اَعۡمَالُکُمۡ ۫ سَلٰمٌ  عَلَیۡکُمۡ ۫ لَا  نَبۡتَغِی الۡجٰہِلِیۡنَ ﴿۵۵﴾', 'اور جب بیہودہ بات سنتے ہیں تو اس سے منہ پھیر لیتے ہیں اور کہتے ہیں کہ ہمکو ہمارے اعمال اور تمکو تمہارے اعمال۔ تمکو سلام۔ ہم جاہلوں کو نہیں چاہتے۔', 'اور جب سنیں نکمی باتیں اس سے کنارہ کریں اورکہیں ہم کو ہمارے کام اور تم کو تمہارے کام سلامت رہو ہم کو نہیں چاہئیں بے سمجھ لوگ [۷۶]', 'And when they hear AlLaghw (dirty, false, evil vain talk), they withdraw from it and say: \"To us our deeds, and to you your deeds. Peace be to you. We seek not the ignorant.\"', 'And when they hear absurd talk, they withdraw from it and say, “Our deeds are for us and your deeds are for you. Peace be on you. We do not desire (to be entangled with) the ignorant people.”'),
(3308, 28, 56, 6, 9, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'اِنَّکَ لَا تَہۡدِیۡ مَنۡ  اَحۡبَبۡتَ وَ لٰکِنَّ اللّٰہَ یَہۡدِیۡ مَنۡ یَّشَآءُ ۚ وَ ہُوَ اَعۡلَمُ بِالۡمُہۡتَدِیۡنَ ﴿۵۶﴾', 'اے نبی تم جسکو دوست رکھتے ہو اسے ہدایت نہیں کر سکتے بلکہ اللہ ہی جسکو چاہتا ہے ہدایت کرتا ہے اور وہ ہدایت پانے والوں کو خوب جانتا ہے۔', 'تو راہ پر نہیں لاتا جس کو چاہے پر اللہ راہ پر لائے جس کو چاہے [۷۷] اور وہی خوب جانتا ہے جو راہ پر آئیں گے [۷۸]', 'Verily! You (O Muhammad SAW) guide not whom you like, but Allah guides whom He wills. And He knows best those who are the guided.', 'You cannot give guidance to whomsoever you wish, but Allah gives guidance to whomsoever He wills, and He best knows the ones who are on the right path.'),
(3309, 28, 57, 6, 9, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ قَالُوۡۤا اِنۡ نَّتَّبِعِ الۡہُدٰی مَعَکَ نُتَخَطَّفۡ مِنۡ  اَرۡضِنَا ؕ اَوَ لَمۡ نُمَکِّنۡ لَّہُمۡ حَرَمًا اٰمِنًا یُّجۡبٰۤی  اِلَیۡہِ  ثَمَرٰتُ  کُلِّ شَیۡءٍ رِّزۡقًا مِّنۡ لَّدُنَّا وَ لٰکِنَّ  اَکۡثَرَہُمۡ  لَا  یَعۡلَمُوۡنَ ﴿۵۷﴾', 'اور کہتے ہیں کہ اگر ہم تمہارے ساتھ ہدایت کی پیروی کریں تو اپنے ملک سے اچک لئے جائیں۔ کیا ہم نے انکو حرم میں جو امن کا مقام ہے جگہ نہیں دی۔ جہاں ہر قسم کے میوے پہنچائے جاتے ہیں بطور رزق ہماری طرف سے لیکن ان میں سے اکثر نہیں جانتے۔', 'اور کہنے لگے اگر ہم راہ پر آئیں تیرے ساتھ اچک لئے جائیں اپنے ملک سے [۷۹] کیا ہم نے جگہ نہیں دی ان کو حرمت والے پناہ کے مکان میں کھینچے چلے آتے ہیں اسکی طرف میوے ہر چیز کے روزی ہماری طرف سے پر بہت ان میں سمجھ نہیں رکھتے [۸۰]', 'And they say: \"If we follow the guidance with you, we would be snatched away from our land.\" Have We not established for them a secure sanctuary (Makkah), to which are brought fruits of all kinds, a provision from Ourselves, but most of them know not.', 'They said, “If we follow the guidance with you (O Muhammad), we will be driven out of our land.” Is it not that We have established them in the peaceful Haram (sanctuary) to which the fruits of everything are drawn as a provision from Us? But most of them do not know.'),
(3310, 28, 58, 6, 9, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ کَمۡ  اَہۡلَکۡنَا مِنۡ قَرۡیَۃٍۭ  بَطِرَتۡ مَعِیۡشَتَہَا ۚ فَتِلۡکَ مَسٰکِنُہُمۡ لَمۡ تُسۡکَنۡ مِّنۡۢ  بَعۡدِہِمۡ  اِلَّا قَلِیۡلًا ؕ وَ کُنَّا نَحۡنُ  الۡوٰرِثِیۡنَ ﴿۵۸﴾', 'اور ہم نے بہت سی بستیوں کو ہلاک کر ڈالا جو اپنی عیش والی زندگی میں اترا رہے تھے۔ سو یہ انکے مکانات ہیں جو انکے بعد آباد ہی نہیں ہوئے مگر بہت کم۔ اور انکے بعد ہم ہی وارث ہوئے۔', 'اور کتنی غارت کر دیں ہم نے بستیاں جو اترا چلی تھیں اپنی گذران میں اب یہ ہیں ان کے گھر آباد نہیں ہوئے ان کے پیچھے مگر تھوڑے [۸۱] اور ہم ہیں آخر کو سب کچھ لینے والے [۸۲]', 'And how many a town (population) have We destroyed, which were thankless for its means of livelihood (disobeyed Allah, and His Messengers, by doing evil deeds and crimes) ! And those are their dwellings, which have not been inhabited after them except a little. And verily! We have been the inheritors.', 'And how many a town have We destroyed that were over-proud of their means of living. Now, those are their habitations, which were never inhabited after them except a few, and We alone were the inheritors.'),
(3311, 28, 59, 6, 9, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ مَا کَانَ رَبُّکَ مُہۡلِکَ الۡقُرٰی حَتّٰی یَبۡعَثَ فِیۡۤ  اُمِّہَا رَسُوۡلًا یَّتۡلُوۡا عَلَیۡہِمۡ اٰیٰتِنَا ۚ وَ مَا کُنَّا مُہۡلِکِی الۡقُرٰۤی  اِلَّا وَ اَہۡلُہَا ظٰلِمُوۡنَ ﴿۵۹﴾', 'اور تمہارا پروردگار بستیوں کو ہلاک نہیں کیا کرتا۔ جب تک انکے بڑے شہر میں پیغمبر نہ بھیج لے جو انکو ہماری آیتیں پڑھ پڑھ کر سنائے اور ہم بستیوں کو ہلاک نہیں کیا کرتے مگر اس حالت میں کہ وہاں کے باشندے ظالم ہوں۔', 'اور تیرا رب نہیں غارت کرنے والا بستیوں کو جب تک نہ بھیج لے ان کی بڑی بستی میں کسی کو پیغام دے کر جو سنائے انکو ہماری باتیں [۸۳] اور ہم ہر گز نہیں غارت کرنے والے بستیوں کو مگر جب کہ وہاں کے لوگ گنہگار ہوں [۸۴]', 'And never will your Lord destroy the towns (populations) until He sends to their mother town a Messenger reciting to them Our Verses. And never would We destroy the towns unless the people thereof are Zalimoon (polytheists, wrong-doers, disbelievers in the Oneness of Allah, oppressors and tyrants).', 'And your Lord is not such as He would destroy the towns unless he had sent to their central place a messenger who recites to them Our verses, nor are We such as would destroy the towns unless their people are wrongdoers.'),
(3312, 28, 60, 6, 9, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ مَاۤ  اُوۡتِیۡتُمۡ مِّنۡ شَیۡءٍ فَمَتَاعُ  الۡحَیٰوۃِ الدُّنۡیَا وَ زِیۡنَتُہَا ۚ وَ مَا عِنۡدَ اللّٰہِ خَیۡرٌ  وَّ  اَبۡقٰی ؕ اَفَلَا  تَعۡقِلُوۡنَ ﴿٪۶۰﴾', 'اور اے لوگو جو چیز تمکو دی گئ ہے سو وہ دنیا کی زندگی کا فائدہ اور اسکی زینت ہے۔ اور جو اللہ کے پاس ہے وہ بہتر اور ہمیشہ باقی رہنے والی ہے۔ کیا تم سمجھتے نہیں؟', 'اور جو تم کو ملی ہے کوئی چیز سو فائدہ اٹھا لینا ہے دنیا کی زندگی میں اور  یہاں کی رونق ہے اور جو اللہ کے  پاس ہے سو بہتر ے اور باقی رہنے والا کیا تم کو سمجھ نہیں [۸۵]', 'And whatever you have been given is an enjoyment of the life of (this) world and its adornment, and that (Hereafter) which is with Allah is better and will remain forever. Have you then no sense?', 'Moreover, whatever of anything you are given is (no more than) an enjoyment of the worldly life and its decoration, and that which lies with Allah is much better and far more lasting. So do you not use reason?'),
(3313, 28, 61, 7, 10, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'اَفَمَنۡ وَّعَدۡنٰہُ وَعۡدًا حَسَنًا فَہُوَ لَاقِیۡہِ کَمَنۡ مَّتَّعۡنٰہُ مَتَاعَ الۡحَیٰوۃِ الدُّنۡیَا ثُمَّ ہُوَ یَوۡمَ الۡقِیٰمَۃِ مِنَ الۡمُحۡضَرِیۡنَ ﴿۶۱﴾', 'بھلا جس شخص سے ہم نے اچھا وعدہ کیا اور وہ اسے حاصل کرنے والا ہے تو کیا وہ اس شخص کا سا ہے جسکو ہم نے دنیا کی زندگی کے فائدے سے بہرہ مند کیا پھر وہ قیامت کے روز ان لوگوں میں ہو جو گرفتار کر کے حاضر کئے جائیں گے۔', 'بھلاا یک شخص جس سے ہم  نے وعدہ کیا ہے اچھا وعدہ سو ہ اس کو پانے والا ہے برابر ہے، اسکے جسکو ہم نے فائدہ دیا دنیا کی زندگانی کا پھر وہ قیامت کے دن پکڑ ا ہوا  آیا [۸۶]', 'Is he whom We have promised an excellent promise (Paradise), which he will find true, like him whom We have made to enjoy the luxuries of the life of (this) world, then on the Day of Resurrection, he will be among those brought up (to be punished in the Hell-fire)?', 'Is then the one, to whom We have made a good promise which he is going to meet, like the one whom We have given the benefit of enjoying the worldly life, then on the Day of Judgment he will be among those arraigned?'),
(3314, 28, 62, 7, 10, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ یَوۡمَ یُنَادِیۡہِمۡ فَیَقُوۡلُ  اَیۡنَ شُرَکَآءِیَ الَّذِیۡنَ  کُنۡتُمۡ  تَزۡعُمُوۡنَ ﴿۶۲﴾', 'اور جس روز اللہ انکو پکارے گا سو کہے گا کہ میرے وہ شریک کہاں ہیں جنکا تمہیں دعوٰی تھا۔', 'اور جس دن انکو  پکارے گا تو کہے گا کہاں ہیں میرے شریک جن کا تم دعویٰ کرتے تھے [۸۷]', 'And (remember) the Day when He will call to them, and say: \"Where are My (so-called) partners whom you used to assert?\"', '(Remember) the Day when He will call them and say, “Where are My ‘partners’ you used to claim?'),
(3315, 28, 63, 7, 10, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'قَالَ الَّذِیۡنَ حَقَّ عَلَیۡہِمُ الۡقَوۡلُ رَبَّنَا ہٰۤؤُلَآءِ  الَّذِیۡنَ اَغۡوَیۡنَا ۚ اَغۡوَیۡنٰہُمۡ کَمَا غَوَیۡنَا ۚ تَبَرَّاۡنَاۤ  اِلَیۡکَ ۫ مَا کَانُوۡۤا اِیَّانَا یَعۡبُدُوۡنَ ﴿۶۳﴾', 'تو جن لوگوں پر عذاب کا حکم ثابت ہو چکا ہو گا وہ کہیں گے کہ اے ہمارے پروردگار یہ وہ لوگ ہیں جنکو ہم نے گمراہ کیا تھا۔ اور جس طرح ہم خود گمراہ ہوئے تھے اسی طرح ہم نے انکو گمراہ کیا تھا اب ہم تیری طرف متوجہ ہو کر ان سے بیزار ہوتے ہیں یہ ہمیں نہیں پوجتے تھے۔', 'بولے جن پر ثابت ہو چکی بات اے رب یہ لوگ ہیں جن کو ہم نے بہکایا ان کو بہکایا جیسے ہم آپ بہکے ہم منکر ہوئے تیرے آگے وہ ہم کو نہ پوجتے تھے [۸۸]', 'Those about whom the Word will have come true (to be punished) will say: \"Our Lord! These are they whom we led astray. We led them astray, as we were astray ourselves. We declare our innocence (from them) before You. It was not us they worshipped.\"', 'Those against whom the word will come true will say, “Our Lord, these are the ones whom we led astray. We led them astray as we ourselves went astray. We negate before you our responsibility (in respect of them); it was not we whom they worshipped.”'),
(3316, 28, 64, 7, 10, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ قِیۡلَ ادۡعُوۡا شُرَکَآءَکُمۡ  فَدَعَوۡہُمۡ فَلَمۡ  یَسۡتَجِیۡبُوۡا لَہُمۡ وَ رَاَوُا الۡعَذَابَ ۚ لَوۡ  اَنَّہُمۡ  کَانُوۡا یَہۡتَدُوۡنَ ﴿۶۴﴾', 'اور کہا جائے گا کہ اپنے شریکوں کو بلاؤ۔ سو وہ انکو پکاریں گے تو وہ انکو جواب نہ دیں سکیں گے اور جب عذاب کو دیکھ لیں گے تو تمنا کریں گے کہ کاش وہ ہدایت یاب ہوتے۔', 'اور کہیں گے پکارو اپنے شریکوں کو پھر پکاریں گے انکو تو  وہ جواب نہ دیں گے ان کو [۸۹] اور دیکھیں گے عذاب کاش کہ کسی طرح وہ راہ پائے ہوئے ہوتے [۹۰]', 'And it will be said (to them): \"Call upon your (so-called) partners (of Allah), and they will call upon them, but they will give no answer to them, and they will see the torment. (They will then wish) if only they had been guided!', 'And it will be said, “Call those whom you held as co-gods.” So they will call them, but they will not respond to them, and they will see the punishment. Would that they had taken the right path!'),
(3317, 28, 65, 7, 10, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ یَوۡمَ یُنَادِیۡہِمۡ فَیَقُوۡلُ مَاذَاۤ  اَجَبۡتُمُ الۡمُرۡسَلِیۡنَ ﴿۶۵﴾', 'اور جس روز اللہ انکو پکارے گا اور کہے گا کہ تم نے پیغمبروں کو کیا جواب دیا تھا۔', 'اور جس دن ان کو پکارے گا تو فرمائے گا کیا جواب دیا تھا تم نے پیغام پہنچانے والوں کو', 'And (remember) the Day (Allah) will call to them, and say: \"What answer gave you to the Messengers?\"', '(Remember) the Day when He (Allah) will call them and say, “What response did you give to the messengers?”'),
(3318, 28, 66, 7, 10, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَعَمِیَتۡ عَلَیۡہِمُ الۡاَنۡۢبَآءُ یَوۡمَئِذٍ فَہُمۡ لَا  یَتَسَآءَلُوۡنَ ﴿۶۶﴾', 'تو اس روز ان پر خبریں بند ہو جائیں گی پھر وہ آپس میں کچھ بھی نہ پوچھ سکیں گے۔', 'پھر بند ہو جائیں گی ان پر باتیں اس دن سو  وہ آپس میں بھی نہ پوچھیں گے [۹۱]', 'Then the news of a good answer will be obscured to them on that day, and they will not be able to ask one another.', 'So all events will become too obscure for them (to give a correct reply), and they will not (be able to) consult each other.'),
(3319, 28, 67, 7, 10, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَاَمَّا مَنۡ تَابَ وَ اٰمَنَ وَ عَمِلَ صَالِحًا فَعَسٰۤی اَنۡ  یَّکُوۡنَ مِنَ الۡمُفۡلِحِیۡنَ ﴿۶۷﴾', 'سو رہا وہ شخص جس نے توبہ کی اور ایمان لایا اور عمل نیک کئے تو امید ہے کہ وہ کامیاب ہونے والوں میں ہو۔', 'سو جس نے کہ توبہ کی اور یقین لایا اعمال کئے اچھے سو  امید ہے کہ ہو چھوٹنے والوں میں [۹۲]', 'But as for him who repented (from polytheism and sins, etc.), believed (in the Oneness of Allah, and in His Messenger Muhammad SAW), and did righteous deeds (in the life of this world), then he will be among those who are successful.', 'As for the one who repents and becomes a believer and acts righteously, hopefully he will be among the successful.'),
(3320, 28, 68, 7, 10, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ رَبُّکَ یَخۡلُقُ مَا یَشَآءُ وَ یَخۡتَارُ ؕ مَا کَانَ لَہُمُ الۡخِیَرَۃُ ؕ سُبۡحٰنَ اللّٰہِ  وَ تَعٰلٰی عَمَّا یُشۡرِکُوۡنَ ﴿۶۸﴾', 'اور تمہارا پروردگار جو چاہتا ہے پیدا کرتا ہے اور جسے چاہتا ہے برگزیدہ کر لیتا ہے۔ انکو اس کا اختیار نہیں ہے۔ یہ جو شرک کرتے ہیں اللہ اس سے پاک و بالاتر ہے۔', 'اور تیرا رب پیدا کرتا ہے جو چاہے اور پسند کرے جس کو چاہے انکے  ہاتھ میں نہیں پسند کرنا [۹۳] اللہ نرالا ہے اور بہت اوپر ہے اس چیز سے کہ شریک بتلاتے ہیں [۹۴]', 'And your Lord creates whatsoever He wills and chooses, no choice have they (in any matter). Glorified be Allah, and exalted above all that they associate as partners (with Him).', 'Your Lord creates what He wills and chooses. Choice is not theirs. Pure is Allah and far higher than their ascribing of partners to Him.'),
(3321, 28, 69, 7, 10, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ رَبُّکَ یَعۡلَمُ مَا تُکِنُّ صُدُوۡرُہُمۡ وَ مَا یُعۡلِنُوۡنَ ﴿۶۹﴾', 'اور انکے سینے جو کچھ مخفی کرتے ہیں اور جو یہ ظاہر کرتے ہیں تمہارا پروردگار اسکو جانتا ہے۔', 'اور تیرا رب جانتا ہے جو چھپ رہا ہے انکے سینوں میں اور جو کچھ کہ ظاہر میں کرتے ہیں [۹۵]', 'And your Lord knows what their breasts conceal, and what they reveal.', 'Your Lord knows what their hearts conceal and what they reveal.'),
(3322, 28, 70, 7, 10, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ ہُوَ اللّٰہُ  لَاۤ  اِلٰہَ  اِلَّا ہُوَ ؕ لَہُ  الۡحَمۡدُ فِی الۡاُوۡلٰی وَ الۡاٰخِرَۃِ ۫ وَ لَہُ  الۡحُکۡمُ  وَ  اِلَیۡہِ تُرۡجَعُوۡنَ ﴿۷۰﴾', 'اور وہی اللہ ایسا ہے کہ اسکے سوا کوئی معبود نہیں دنیا اور آخرت میں اسی کی تعریف ہے اور اسی کا حکم چلتا ہے اور اسی کی طرف تم لوٹائے جاؤ گے۔', 'اور وہی اللہ ہے کسی کی بندگی نہیں اسکے سوا اسی کی تعریف ہے دنیا اور آخرت میں اور اسی کے ہاتھ حکم ہے اور اسی کے پاس پھیرے جاؤ گے [۹۶]', 'And He is Allah; La ilaha illa Huwa (none has the right to be worshipped but He). His is all praise, in the first (i.e. in this world) and in the last (i.e.in the Hereafter). And for Him is the Decision, and to Him shall you (all) be returned.', 'And He is Allah. There is no god but He. Praise is only for Him in the beginning and at the end, and He alone has the right to judge, and to Him you are to be returned.'),
(3323, 28, 71, 7, 10, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'قُلۡ اَرَءَیۡتُمۡ  اِنۡ جَعَلَ اللّٰہُ عَلَیۡکُمُ الَّیۡلَ سَرۡمَدًا  اِلٰی یَوۡمِ الۡقِیٰمَۃِ مَنۡ اِلٰہٌ غَیۡرُ اللّٰہِ یَاۡتِیۡکُمۡ بِضِیَآءٍ ؕ اَفَلَا تَسۡمَعُوۡنَ ﴿۷۱﴾', 'کہو بھلا دیکھو تو اگر اللہ تم پر ہمیشہ قیامت کے دن تک رات کی تاریکی کئے رہے تو اللہ کے سوا کون معبود ہے جو تمکو روشنی لا دے تو کیا تم سنتے نہیں۔', 'تو کہہ دیکھو تو اگر اللہ رکھ دے تم پر رات ہمیشہ کو قیامت کے دن تک [۹۷] کون حاکم ہے اللہ کے سوائے کہ لائے تم کو کہیں سے روشنی پھر کیا تم سنتے نہیں [۹۸]', 'Say (O Muhammad SAW): \"Tell me! If Allah made night continuous for you till the Day of Resurrection, who is an ilah (a god) besides Allah who could bring you light? Will you not then hear?\"', 'Say, “Tell me, if Allah were to impose the night over you, continuing forever up to the Day of Judgment, which god, other than Allah, would bring to you light? Then, do you not listen?”'),
(3324, 28, 72, 7, 10, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'قُلۡ  اَرَءَیۡتُمۡ  اِنۡ جَعَلَ  اللّٰہُ عَلَیۡکُمُ النَّہَارَ سَرۡمَدًا  اِلٰی یَوۡمِ الۡقِیٰمَۃِ مَنۡ اِلٰہٌ غَیۡرُ اللّٰہِ یَاۡتِیۡکُمۡ بِلَیۡلٍ تَسۡکُنُوۡنَ  فِیۡہِ ؕ اَفَلَا  تُبۡصِرُوۡنَ ﴿۷۲﴾', 'کہو کہ بھلا دیکھو تو اگر اللہ تم پر ہمیشہ قیامت تک دن کئے رہے تو اللہ کے سوا کون معبود ہے کہ تمکو رات لا دے جسمیں تم آرام کرو۔ تو کیا تم دیکھتے نہیں۔', 'تو کہہ دیکھو تو اگر رکھ دے اللہ تم پر دن ہمیشہ کو قیامت کے دن تک کون حاکم ہے اللہ کے سوائے کہ لائے تم کو رات جس میں آرام کرو پھر کیا تم نہیں دیکھتے [۹۹]', 'Say (O Muhammad SAW): \"Tell me! If Allah made day continuous for you till the Day of Resurrection, who is an ilah (a god) besides Allah who could bring you night wherein you rest? Will you not then see?\"', 'Say, “Tell me, if Allah were to impose the day over you, continuing for ever up to the Day of Judgment, which god, other than Allah, would bring to you night in which you may have rest? Then, do you not see?”'),
(3325, 28, 73, 7, 10, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ مِنۡ رَّحۡمَتِہٖ جَعَلَ لَکُمُ الَّیۡلَ وَ النَّہَارَ  لِتَسۡکُنُوۡا فِیۡہِ وَ لِتَبۡتَغُوۡا مِنۡ فَضۡلِہٖ  وَ  لَعَلَّکُمۡ  تَشۡکُرُوۡنَ ﴿۷۳﴾', 'اور اس نے اپنی رحمت سے تمہارے لئے رات کو اور دن کو بنایا تاکہ تم اس میں آرام کرو اور اس میں اس کا فضل تلاش کرو اور تاکہ شکر کرو۔', 'اور اپنی مہربانی سے بنا دئے تمہارے واسطے رات اور دن کہ اس میں چین بھی کرو اور تلاش بھی کرو کچھ اس کا فضل اور تاکہ تم شکر کرو [۱۰۰]', 'It is out of His Mercy that He has put for you night and day, that you may rest therein (i.e. during the night) and that you may seek of His Bounty (i.e. during the day), and in order that you may be grateful.', 'And it is out of His mercy that He has made day and night for you, so that you may have rest in it, and so that you may search for His grace, and so that you may be grateful.'),
(3326, 28, 74, 7, 10, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ یَوۡمَ یُنَادِیۡہِمۡ فَیَقُوۡلُ اَیۡنَ شُرَکَآءِیَ الَّذِیۡنَ  کُنۡتُمۡ تَزۡعُمُوۡنَ ﴿۷۴﴾', 'اور جس دن وہ انکو پکارے گا تو کہے گا کہ میرے وہ شریک جنکا تمہیں دعوٰی تھا کہاں ہیں۔', 'اور جس دن ان کو پکارے گا تو فرمائے گا کہاں ہیں میرے شریک جن کا تم دعویٰ کرتے تھے', 'And (remember) the Day when He (your Lord Allah) will call them (those who worshipped others along with Allah), and will say: \"Where are My (so-called) partners, whom you used to assert?\"', 'And (remember) the Day when He (Allah) will call them (the disbelievers) and say, “Where are My ‘partners’ you used to claim?”'),
(3327, 28, 75, 7, 10, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ نَزَعۡنَا مِنۡ کُلِّ  اُمَّۃٍ  شَہِیۡدًا فَقُلۡنَا ہَاتُوۡا بُرۡہَانَکُمۡ فَعَلِمُوۡۤا اَنَّ الۡحَقَّ  لِلّٰہِ وَ ضَلَّ عَنۡہُمۡ  مَّا  کَانُوۡا  یَفۡتَرُوۡنَ ﴿٪۷۵﴾', 'اور ہم ہر ایک امت میں سے ایک گواہ نکال لیں گے پھر کہیں گے کہ اپنی دلیل پیش کرو تو وہ جان لیں گے کہ سچ بات اللہ کی ہے اور جو کچھ وہ افترا کیا کرتے تھے ان سے جاتا رہے گا۔', 'اور جدا کریں گے ہم ہر فرقہ میں سے ایک احوال بتلانے والا [۱۰۱] پھر کہیں گے لاؤ اپنی سند [۱۰۲] تب جان لیں گے کہ سچ بات ہے اللہ کی اور کھوئی جائیں گی ان سے جو باتیں وہ جوڑتے تھے [۱۰۳]', 'And We shall take out from every nation a witness, and We shall say: \"Bring your proof.\" Then they shall know that the truth is with Allah (Alone), and the lies (false gods) which they invented will disappear from them.', 'And We will draw out a witness from every community (to prove their disbelief) and will say, “Bring your proof”. Then they will know that truth is from Allah, and all that they used to forge shall vanish from them.'),
(3328, 28, 76, 8, 11, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'اِنَّ قَارُوۡنَ کَانَ مِنۡ قَوۡمِ  مُوۡسٰی فَبَغٰی عَلَیۡہِمۡ ۪ وَ اٰتَیۡنٰہُ مِنَ الۡکُنُوۡزِ مَاۤ  اِنَّ مَفَاتِحَہٗ  لَتَنُوۡٓاُ بِالۡعُصۡبَۃِ  اُولِی الۡقُوَّۃِ ٭ اِذۡ  قَالَ  لَہٗ  قَوۡمُہٗ  لَا تَفۡرَحۡ  اِنَّ اللّٰہَ  لَا یُحِبُّ الۡفَرِحِیۡنَ ﴿۷۶﴾', 'قارون موسٰی  کی قوم میں سے تھا پھر وہ ان پر زیادتی کرنے لگا۔ اور ہم نے اسکو اتنے خزانے دیئے تھے کہ انکی کنجیاں ایک طاقتور جماعت کو اٹھانا مشکل ہوتیں جب اس سے اسکی قوم نے کہا کہ اترایئے مت کہ اللہ اترانے والوں کو پسند نہیں کرتا۔', 'قارون جو تھا سو موسٰی کی قوم سے پھر شرارت کرنے لگا ان پر [۱۰۴] اور ہم نے دیے تھے اسکو خزانے اتنے کہ اسکی کنجیاں اٹھانے سے تھک جاتے کئ مرد زور آور [۱۰۵] جب کہا اس کو اسکی قوم نے اترا مت اللہ کو نہیں بھاتے اترانے والے [۱۰۶]', 'Verily, Qaroon (Korah) was of Moosas (Moses) people, but he behaved arrogantly towards them. And We gave him of the treasures, that of which the keys would have been a burden to a body of strong men. When his people said to him: \"Do not be glad (with ungratefulness to Allahs Favours). Verily! Allah likes not those who are glad (with ungratefulness to Allahs Favours).', 'Indeed Qārūn was from the people of Mūsā, then he rebelled against them. And We had given to him such treasures as their keys would weigh too heavy for a strong group of people. (Remember) when his people said to him, “Do not exult. Surely, Allah does not like the exultant.'),
(3329, 28, 77, 8, 11, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ ابۡتَغِ  فِیۡمَاۤ  اٰتٰىکَ اللّٰہُ  الدَّارَ الۡاٰخِرَۃَ  وَ لَا تَنۡسَ نَصِیۡبَکَ مِنَ الدُّنۡیَا وَ اَحۡسِنۡ کَمَاۤ  اَحۡسَنَ اللّٰہُ  اِلَیۡکَ وَ لَا تَبۡغِ الۡفَسَادَ فِی الۡاَرۡضِ ؕ اِنَّ اللّٰہَ  لَا یُحِبُّ الۡمُفۡسِدِیۡنَ ﴿۷۷﴾', 'اور جو مال تمکو اللہ نے عطا فرمایا ہے اس سے آخرت کی بھلائی طلب کیجئے اور دنیا سے اپنا حصہ نہ بھلایئے اور جیسی اللہ نے تم سے بھلائی کی ہے ویسی تم بھی لوگوں سے بھلائی کرو۔ اور ملک میں طالب فساد نہ ہو۔ کیونکہ اللہ فساد کرنے والوں کو دوست نہیں رکھتا۔', 'اور جو تجھ کو اللہ نے دیا ہے اس سے کما لے پچھلا گھر [۱۰۷] اور نہ بھول اپنا حصہ دنیا سے اور بھلائی کر جیسے اللہ نے بھلائی کی تجھ سے [۱۰۸] اور مت چاہ خرابی ڈالنی ملک میں اللہ کو بھاتے نہیں خرابی ڈالنے والے [۱۰۹]', 'But seek, with that (wealth) which Allah has bestowed on you, the home of the Hereafter, and forget not your portion of legal enjoyment in this world, and do good as Allah has been good to you, and seek not mischief in the land. Verily, Allah likes not the Mufsidoon (those who commit great crimes and sins, oppressors, tyrants, mischief-makers, corrupts).', 'And seek the (betterment of) the Ultimate Abode with what Allah has given to you, and do not neglect your share from this world, and do good as Allah did good to you, and do not seek to make mischief in the land. Surely, Allah does not like the mischief-makers.”'),
(3330, 28, 78, 8, 11, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'قَالَ  اِنَّمَاۤ   اُوۡتِیۡتُہٗ  عَلٰی  عِلۡمٍ عِنۡدِیۡ ؕ اَوَ لَمۡ یَعۡلَمۡ اَنَّ اللّٰہَ  قَدۡ اَہۡلَکَ مِنۡ قَبۡلِہٖ مِنَ الۡقُرُوۡنِ مَنۡ ہُوَ اَشَدُّ مِنۡہُ  قُوَّۃً وَّ اَکۡثَرُ جَمۡعًا ؕ وَ لَا یُسۡـَٔلُ عَنۡ ذُنُوۡبِہِمُ  الۡمُجۡرِمُوۡنَ ﴿۷۸﴾', 'وہ بولا کہ یہ مال مجھے میرے ہنر کے سبب ملا ہے کیا اسکو معلوم نہیں تھا کہ اللہ نے اس سے پہلے بہت سی امتیں جو اس سے قوت میں بڑھ کر اور جمعیت میں بیشتر تھیں ہلاک کر ڈالی تھیں۔ اور گنہگاروں سے انکے گناہوں کے بارے میں پوچھا نہیں جائے گا۔', 'بولا یہ مال تو مجھ کو ملا ہے ایک ہنر سے جو میرے پاس ہے [۱۱۰] کیا اس نے یہ نہ جانا کہ اللہ غارت کر چکا ہے اس سے پہلے کتنی جماعتیں جو اس سے زیادہ رکھتی تھیں زور اور زیادہ رکھتی تھیں مال کی جمع [۱۱۱] اور پوچھی نہ جائیں گنہگاروں سے ان کے گناہ [۱۱۲]', 'He said: \"This has been given to me only because of knowledge I possess.\" Did he not know that Allah had destroyed before him generations, men who were stronger than him in might and greater in the amount (of riches) they had collected. But the Mujrimoon (criminals, disbelievers, polytheists, sinners, etc.) will not be questioned of their sins (because Allah knows them well, so they will be punished without account).', 'He said, “This is given to me because of the knowledge (I have) with me.” Did he not know that Allah had destroyed, from the generations before him, those who were stronger than him in power and greater than him in multitude? And the sinners have not to be asked about their sins.'),
(3331, 28, 79, 8, 11, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَخَرَجَ عَلٰی قَوۡمِہٖ فِیۡ زِیۡنَتِہٖ ؕ قَالَ الَّذِیۡنَ یُرِیۡدُوۡنَ الۡحَیٰوۃَ  الدُّنۡیَا یٰلَیۡتَ لَنَا مِثۡلَ مَاۤ  اُوۡتِیَ  قَارُوۡنُ ۙ اِنَّہٗ  لَذُوۡ حَظٍّ عَظِیۡمٍ ﴿۷۹﴾', 'تو ایک روز قارون بڑی آرائش اور ٹھاٹھ سے اپنی قوم کے سامنے نکلا۔ جو لوگ دنیا کی زندگی کے طالب تھے کہنے لگے کہ جیسا مال و متاع قارون کو ملا ہے کاش ایسا ہی ہمیں بھی ملے۔ وہ تو بڑے نصیب والا ہے۔', 'پھر نکلا اپنی قوم کے سامنے اپنے ٹھاٹھ سےکہنے لگے جو لوگ طالب تھے دنیا کی زندگانی کے اے کاش ہم کو ملے جیسا کچھ ملا ہے قارون کو بیشک اسکی بڑی قسمت ہے [۱۱۳]', 'So he went forth before his people in his pomp. Those who were desirous of the life of the world, said: \"Ah, would that we had the like of what Qaroon (Korah) has been given? Verily! He is the owner of a great fortune.\"', 'Then (once) he came out before his people in his embellishment. Said those who are desirous of the worldly life, “Would that we had the like of what Qārūn has been given! He is a man of great fortune indeed.”'),
(3332, 28, 80, 8, 11, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ قَالَ الَّذِیۡنَ  اُوۡتُوا الۡعِلۡمَ وَیۡلَکُمۡ ثَوَابُ اللّٰہِ خَیۡرٌ  لِّمَنۡ  اٰمَنَ وَ عَمِلَ صَالِحًا ۚ وَ لَا  یُلَقّٰہَاۤ   اِلَّا الصّٰبِرُوۡنَ ﴿۸۰﴾', 'اور جن لوگوں کو علم دیا گیا تھا وہ کہنے لگے کہ تم پر افسوس۔ مومنوں اور نیکوکاروں کے لئے جو ثواب اللہ کے ہاں تیار ہے وہ کہیں بہتر ہے اور وہ صرف صبر کرنے والوں ہی کو ملے گا۔', 'اور بولے جن کو ملی تھی سمجھ اے خرابی تمہاری اللہ کا دیا ثواب بہتر ہے انکے واسطے جو یقین لائے اور کام کیا بھلا [۱۱۴] اور یہ بات انہی کے دل میں پڑتی ہے جو سہنے والے ہیں [۱۱۵]', 'But those who had been given (religious) knowledge said: \"Woe to you! The Reward of Allah (in the Hereafter) is better for those who believe and do righteous good deeds, and this none shall attain except those who are patient (in following the truth).\"', 'And said those who were given knowledge, “Woe to you, Allah’s reward is much better for him who believes and acts righteously. But this is given to none but to those who observe restraint.”'),
(3333, 28, 81, 8, 11, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'فَخَسَفۡنَا بِہٖ وَ بِدَارِہِ  الۡاَرۡضَ ۟ فَمَا  کَانَ لَہٗ  مِنۡ فِئَۃٍ  یَّنۡصُرُوۡنَہٗ  مِنۡ دُوۡنِ اللّٰہِ ٭ وَ مَا  کَانَ مِنَ الۡمُنۡتَصِرِیۡنَ ﴿۸۱﴾', 'پس ہم نے قارون کو اور اسکی حویلی کو زمین میں دھنسا دیا۔ تو اللہ کے سوا کوئی جماعت اسکی مددگار نہ ہو سکی۔ اور نہ وہ بدلہ لے سکا۔', 'پھر دھنسا دیا ہم نے اس کو اور اسکے گھر کو زمین میں پھر نہ ہوئی س کی کوئی جماعت جو مدد کرتی اسکی اللہ کے سوائے اور نہ وہ خود مدد لا سکا [۱۱۶]', 'So We caused the earth to swallow him and his dwelling place. Then he had no group or party to help him against Allah, nor was he one of those who could save themselves.', 'Then We made him and his home sink into the earth. So there was no group for him who could help him against Allah, nor was he one of those who could defend themselves.'),
(3334, 28, 82, 8, 11, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ اَصۡبَحَ الَّذِیۡنَ تَمَنَّوۡا مَکَانَہٗ بِالۡاَمۡسِ یَقُوۡلُوۡنَ وَیۡکَاَنَّ اللّٰہَ یَبۡسُطُ الرِّزۡقَ لِمَنۡ یَّشَآءُ مِنۡ عِبَادِہٖ وَ یَقۡدِرُ ۚ لَوۡ لَاۤ  اَنۡ مَّنَّ  اللّٰہُ عَلَیۡنَا لَخَسَفَ بِنَا ؕ وَیۡکَاَنَّہٗ  لَا  یُفۡلِحُ  الۡکٰفِرُوۡنَ ﴿٪۸۲﴾', 'اور وہ لوگ جو کل اس کے رتبے کی تمنا کرتے تھے صبح کو کہنے لگے ہائے شامت! اللہ ہی تو اپنے بندوں میں سے جسکے لئے چاہتا ہے رزق فراخ کر دیتا ہے اور جسکے لئے چاہتا ہے تنگ کر دیتا ہے۔ اگر اللہ ہم پر احسان نہ کرتا تو ہمیں بھی دھنسا دیتا۔ ہائے خرابی! کافر کامیاب نہیں ہوتے۔', 'اور فجر کو لگے کہنے جو کل شام آرزو کرتے تھے اس کا سا درجہ ارے خرابی یہ تو اللہ کھول دیتا ہے روزی جس کو چاہے اپنے بندوں میں اور تنگ کر دیتا ہے [۱۱۷] اگر نہ احسان کرتا ہم پر اللہ تو ہم کو بھی دھنسا دیتا اے خرابی یہ تو چھٹکارا نہیں پاتے منکر [۱۱۸]', 'And those who had desired (for a position like) his position the day before, began to say: \"Know you not that it is Allah Who enlarges the provision or restricts it to whomsoever He pleases of His slaves. Had it not been that Allah was Gracious to us, He could have caused the earth to swallow us up (also)! Know you not that the disbelievers will never be successful.', 'And those who wished to be in his position the day before, started saying, “Oh, it seems that Allah extends provision to whom He wills and straitens (for whom He wills). Had Allah not favored us, He would have made us sink (too). Oh, it seems that the infidels do not succeed.”'),
(3335, 28, 83, 9, 12, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'تِلۡکَ الدَّارُ الۡاٰخِرَۃُ  نَجۡعَلُہَا لِلَّذِیۡنَ لَا یُرِیۡدُوۡنَ عُلُوًّا فِی الۡاَرۡضِ وَ لَا فَسَادًا ؕ وَ الۡعَاقِبَۃُ  لِلۡمُتَّقِیۡنَ ﴿۸۳﴾', 'وہ جو آخرت کا گھر ہے ہم نے اسے ان لوگوں کے لئے تیار کر رکھا ہے جو ملک میں ظلم اور فساد کا ارادہ نہیں رکھتے اور انجام نیک تو پرہیزگاروں ہی کا ہے۔', 'وہ گھر پچھلا ہے ہم دیں گے وہ ان لوگوں کو جو نہیں چاہتے اپنی بڑائی ملک میں اور نہ بگاڑ ڈالنا اور عاقبت بھلی ہے ڈرنے والوں کی [۱۱۹]', 'That home of the Hereafter (i.e. Paradise), We shall assign to those who rebel not against the truth with pride and oppression in the land nor do mischief by committing crimes. And the good end is for the Muttaqoon (pious - see V.2:2).', 'As for that Ultimate Abode (the Hereafter), We assign it to those who do not intend haughtiness on earth nor mischief. And the (best) end is for the God-fearing.'),
(3336, 28, 84, 9, 12, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'مَنۡ جَآءَ بِالۡحَسَنَۃِ فَلَہٗ  خَیۡرٌ  مِّنۡہَا ۚ وَ مَنۡ جَآءَ بِالسَّیِّئَۃِ  فَلَا یُجۡزَی الَّذِیۡنَ عَمِلُوا السَّیِّاٰتِ  اِلَّا مَا کَانُوۡا یَعۡمَلُوۡنَ ﴿۸۴﴾', 'جو شخص نیکی لے کر آئے گا اس کے لئے اس سے بہتر صلہ ہو گا اور جو برائی لائے گا تو جن لوگوں نے برے کام کئے انکو بدلہ بھی اسی طرح کا ملے گا جس طرح کے وہ کام کرتے تھے۔', 'جو لیکر آیا بھلائی اس کو ملنا ہے اس سے بہتر [۱۲۰] اور جو کوئی لے کر آیا برائی سو برائیاں کرنے والے ان کو وہی سزا ملے گی جو کچھ کرتے تھے [۱۲۱]', 'Whosoever brings good (Islamic Monotheism along with righteous deeds), he shall have the better thereof, and whosoever brings evil (polytheism along with evil deeds) then, those who do evil deeds will only be requited for what they used to do.', 'Whoever brings good deed shall have better than it, and whoever brings evil deed, then those who commit evils shall not be punished except for what they used to do.'),
(3337, 28, 85, 9, 12, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'اِنَّ الَّذِیۡ فَرَضَ عَلَیۡکَ الۡقُرۡاٰنَ لَرَآدُّکَ اِلٰی مَعَادٍ ؕ قُلۡ رَّبِّیۡۤ  اَعۡلَمُ مَنۡ جَآءَ بِالۡہُدٰی وَ مَنۡ ہُوَ فِیۡ ضَلٰلٍ مُّبِیۡنٍ ﴿۸۵﴾', 'اے پیغمبر جس اللہ نے تم پر قرآن کے احکام کو فرض کیا ہے وہ تمہیں پہلی جگہ لوٹا دے گا۔ کہدو کہ میرا پروردگار اس شخص کو بھی خوب جانتا ہے جو ہدایت لے کر آیا اور اسکو بھی جو کھلی گمراہی میں ہے۔', 'جس نے حکم بھیجا تجھ پر قرآن کا وہ پھر لانے والا ہے تجھ کو پہلی جگہ [۱۲۲] تو کہہ میرا رب خوب جانتا ہے کون لایا ہے راہ کی سوجھ اور کون پڑا ہے صریح گمراہی میں [۱۲۳]', 'Verily, He Who has given you (O Muhammad SAW) the Quran (i.e. ordered you to act on its laws and to preach it to others) will surely bring you back to the Maad (place of return, either to Makkah or to Paradise after your death, etc.). Say (O Muhammad SAW): \"My Lord is Aware of him who brings guidance, and he who is in manifest error.\"', 'Surely the One who has enjoined the Qur’ān upon you will surely bring you back to a place of return. Say, “My Lord best knows the one who has come with guidance and the one who is in manifest error.”'),
(3338, 28, 86, 9, 12, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ مَا کُنۡتَ تَرۡجُوۡۤا اَنۡ یُّلۡقٰۤی  اِلَیۡکَ الۡکِتٰبُ  اِلَّا رَحۡمَۃً  مِّنۡ رَّبِّکَ فَلَا تَکُوۡنَنَّ  ظَہِیۡرًا  لِّلۡکٰفِرِیۡنَ ﴿۫۸۶﴾', 'اور اے نبی تمہیں امید نہ تھی کہ تم پر یہ کتاب نازل کی جائے گی۔ مگر تمہارے پروردگار کی مہربانی سے نازل ہوئی سو تم ہرگز کافروں کے مددگار نہ ہونا۔', 'اور تو توقع نہ رکھتا تھا کہ اتاری جائے تجھ پر کتاب مگر مہربانی سے تیرے رب کی [۱۲۴] سو تو مت ہو مددگار کافروں کا [۱۲۵]', 'And you were not expecting that the Book (this Quran) would be sent down to you, but it is a mercy from your Lord. So never be a supporter of the disbelievers.', 'You were not expecting that the Book would be sent down to you, but it was a mercy from your Lord. So, never be a supporter for the infidels.'),
(3339, 28, 87, 9, 12, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ لَا یَصُدُّنَّکَ عَنۡ اٰیٰتِ اللّٰہِ  بَعۡدَ  اِذۡ اُنۡزِلَتۡ  اِلَیۡکَ وَ ادۡعُ  اِلٰی رَبِّکَ وَ لَا تَکُوۡنَنَّ  مِنَ  الۡمُشۡرِکِیۡنَ ﴿ۚ۸۷﴾', 'اور وہ تمہیں اللہ کی آیتوں کی تبلیغ سے بعد اسکے کہ وہ تم پر نازل ہو چکی ہیں روک نہ دیں اور اپنے پروردگار کو پکارتے رہو اور مشرکوں میں سے ہرگز نہ ہو جانا۔', 'اور نہ ہو کہ وہ تجھ کو روک دیں اللہ کے حکموں سے بعد اس کے کہ اتر چکے تیری طرف اور بلا اپنے رب کی طرف اور مت ہو شریک والوں میں [۱۲۶]', 'And let them not turn you (O Muhammad SAW) away from (preaching) the Ayat (revelations and verses) of Allah after they have been sent down to you, and invite (men) to (believe in) your Lord (i.e: in the Oneness (Tauheed) of Allah (1) Oneness of the Lordship of Allah; (2) Oneness of the worship of Allah; (3) Oneness of the Names and Qualities of Allah), and be not of Al-Mushrikoon (those who associate partners with Allah, e.g. polytheists, pagans, idolaters, those who disbelieve in the Oneness of Allah and deny the Prophethood of Messenger Muhammad SAW).', 'And let them not prevent you from Allah’s verses after they are sent down to you, and call (people) to your Lord, and never become one of those who associate partners with Allah.'),
(3340, 28, 88, 9, 12, 20, 'اَمَّنۡ  خَلَقَ', 'القصص', 'وَ لَا تَدۡعُ مَعَ اللّٰہِ  اِلٰـہًا اٰخَرَ ۘ لَاۤ  اِلٰہَ اِلَّا ہُوَ ۟ کُلُّ  شَیۡءٍ ہَالِکٌ  اِلَّا وَجۡہَہٗ ؕ لَہُ  الۡحُکۡمُ  وَ  اِلَیۡہِ  تُرۡجَعُوۡنَ ﴿٪۸۸﴾', 'اور اللہ کے ساتھ کسی اور کو معبود سمجھ کر نہ پکارنا اسکے سوا کوئی معبود نہیں۔ اسکی ذات پاک کے سوا ہر چیز فنا ہونے والی ہے۔ اسی کا حکم چلتا ہے اور اسی کی طرف تم لوٹ کر جاؤ گے۔', 'اور مت پکار اللہ کے سوائے دوسرا حاکم [۱۲۷] کسی کی بندگی نہیں اسکے سوائے ہر چیز فنا ہے مگر اس کا منہ [۱۲۸] اسی کا حکم ہے اور اسی کی طرف پھر جاؤ گے [۱۲۹]', 'And invoke not any other ilah (god) along with Allah, La ilaha illa Huwa (none has the right to be worshipped but He). Everything will perish save His Face. His is the Decision, and to Him you (all) shall be returned.', 'And do not invoke any other god along with Allah. There is no god but He. Every thing is going to perish except His Face. He alone has the right to judge, and to Him you are to be returned.'),
(3341, 29, 1, 1, 13, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'الٓـمّٓ ۚ﴿۱﴾', 'الٓم۔', 'الٓم۔', 'AlifLamMeem. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings.)', 'Alif , Lām , Mīm .'),
(3342, 29, 2, 1, 13, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'اَحَسِبَ النَّاسُ اَنۡ یُّتۡرَکُوۡۤا اَنۡ یَّقُوۡلُوۡۤا اٰمَنَّا وَ ہُمۡ  لَا یُفۡتَنُوۡنَ ﴿۲﴾', 'کیا لوگ یہ خیال کئے ہوئے ہیں کہ صرف یہ کہنے سے کہ ہم ایمان لے آئے چھوڑ دیئے جائیں گے اور انکی آزمائش نہیں کی جائے گی۔', 'کیا یہ سمجھتے ہیں لوگ کہ چھوٹ جائیں گے اتنا کہہ کر کہ ہم یقین لائے اور ان کو جانچ نہ لیں گے [۱]', 'Do people think that they will be left alone because they say: \"We believe,\" and will not be tested.', 'Do people think that they will be left (at ease) only on their saying, “We believe” and will not be put to any test?'),
(3343, 29, 3, 1, 13, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ لَقَدۡ فَتَنَّا الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ فَلَیَعۡلَمَنَّ اللّٰہُ  الَّذِیۡنَ صَدَقُوۡا وَ لَیَعۡلَمَنَّ  الۡکٰذِبِیۡنَ  ﴿۳﴾', 'اور جو لوگ ان سے پہلے ہو چکے ہیں ہم نے انکو بھی آزمایا تھا اور انکو بھی آزمائیں گے سو اللہ انکو ضرور معلوم کرے گا جو اپنے ایمان میں سچے ہیں اور انکو بھی جو جھوٹے ہیں۔', 'اور ہم نے جانچا ہے ان کو جو ان سے پہلے تھے [۲] سو البتہ معلوم کرے گا اللہ جو لوگ سچے ہیں اور البتہ معلوم کرے گا جھوٹوں کو [۳]', 'And We indeed tested those who were before them. And Allah will certainly make (it) known (the truth of) those who are true, and will certainly make (it) known (the falsehood of) those who are liars, (although Allah knows all that before putting them to test).', 'Indeed We have tested those who were before them. So Allah will surely know the ones who are truthful, and He will surely know the liars.'),
(3344, 29, 4, 1, 13, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'اَمۡ حَسِبَ الَّذِیۡنَ یَعۡمَلُوۡنَ السَّیِّاٰتِ اَنۡ  یَّسۡبِقُوۡنَا ؕ سَآءَ  مَا یَحۡکُمُوۡنَ  ﴿۴﴾', 'کیا وہ لوگ جو برے کام کرتے ہیں یہ سمجھے ہوئے ہیں کہ یہ ہمارے قابو سے نکل جائیں گے۔ جو فیصلہ یہ کرتے ہیں برا ہے۔', 'کیا یہ سمجھتے ہیں جو لوگ کہ کرتے ہیں برائیاں کہ ہم سے بچ جائیں بری بات طے کرتے ہیں [۴]', 'Or those who do evil deeds think that they can outstrip Us (i.e. escape Our Punishment)? Evil is that which they judge!', 'Or do those who commit evils think that they will outstrip Us? Evil is what they predicate.'),
(3345, 29, 5, 1, 13, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'مَنۡ کَانَ یَرۡجُوۡا لِقَآءَ اللّٰہِ  فَاِنَّ  اَجَلَ اللّٰہِ  لَاٰتٍ ؕ وَ ہُوَ  السَّمِیۡعُ  الۡعَلِیۡمُ ﴿۵﴾', 'جو شخص اللہ کی ملاقات کی امید رکھتا ہو تو اللہ کا مقرر کیا ہوا وقت ضرور آنے والا ہے۔ اور وہ سننے والا ہے جاننے والا ہے۔', 'جو کوئی توقع رکھتا ہے اللہ کی ملاقات کی سو اللہ کا وعدہ آ رہا ہے اور وہ ہے سننے والا جاننے والا [۵]', 'Whoever hopes for the Meeting with Allah, then Allahs Term is surely coming. and He is the All-Hearer, the All-Knower', 'Whoever hopes to meet Allah (must be sure that) Allah’s appointed time has to come, and He is the All-Hearing, the All-Knowing.'),
(3346, 29, 6, 1, 13, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ مَنۡ جَاہَدَ فَاِنَّمَا یُجَاہِدُ لِنَفۡسِہٖ ؕ اِنَّ  اللّٰہَ  لَغَنِیٌّ  عَنِ  الۡعٰلَمِیۡنَ ﴿۶﴾', 'اور جو شخص محنت کرتا ہے تو اپنے ہی فائدے کے لئے محنت کرتا ہے۔ بیشک اللہ تو سارے جہان سے بے نیاز ہے۔', 'اور جو کوئی محنت اٹھائے سو اٹھاتا ہے اپنے ہی واسطے اللہ کو پروا نہیں جہان والوں کی [۶]', 'And whosoever strives, he strives only for himself. Verily, Allah is free of all wants from the Alameen (mankind, jinns, and all that exists).', 'Whoever strives, strives for his own benefit. Surely Allah is independent of all the worlds.'),
(3347, 29, 7, 1, 13, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ الَّذِیۡنَ  اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ لَنُکَفِّرَنَّ عَنۡہُمۡ سَیِّاٰتِہِمۡ وَ لَنَجۡزِیَنَّہُمۡ اَحۡسَنَ  الَّذِیۡ  کَانُوۡا  یَعۡمَلُوۡنَ ﴿۷﴾', 'اور جو لوگ ایمان لائے اور نیک عمل کرتے رہے ہم ان کے گناہوں کو ان سے دور کر دیں گے اور انکو انکے اعمال کا بہت اچھا بدلہ دیں گے۔', 'اور جو لوگ یقین لائے اور کیے  بھلے کام ہم اتار دیں گے ان پر سے برائیاں ان کی اور بدلا دیں گے ان کو بہتر سے بہتر کاموں کا [۷]', 'Those who believe (in the Oneness of Allah (Monotheism) and in Messenger Muhammad SAW , and do not apostate because of the harm they receive from the polytheists), and do righteous good deeds, surely, We shall remit from them their evil deeds and shall reward them according to the best of that which they used to do.', 'Those who believe and do righteous deeds, We will expiate their bad deeds and will give them a better reward (than their expectation) for what they used to do.'),
(3348, 29, 8, 1, 13, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ وَصَّیۡنَا الۡاِنۡسَانَ بِوَالِدَیۡہِ حُسۡنًا ؕ وَ  اِنۡ جَاہَدٰکَ لِتُشۡرِکَ بِیۡ  مَا لَیۡسَ لَکَ بِہٖ عِلۡمٌ  فَلَا تُطِعۡہُمَا ؕ اِلَیَّ  مَرۡجِعُکُمۡ فَاُنَبِّئُکُمۡ  بِمَا کُنۡتُمۡ تَعۡمَلُوۡنَ ﴿۸﴾', 'اور ہم نے انسان کو اسکے ماں باپ کے ساتھ نیک سلوک کرنے کا حکم دیا ہے اے مخاطب اگر تیرے ماں باپ تجھے مجبور کریں کہ تو میرے ساتھ کسی کو شریک بنائے جسکی حقیقت کی تجھے واقفیت نہیں۔ تو ان کا کہا نہ مانیو۔ تم سب کو میری طرف لوٹ کر آنا ہے۔ پھر جو کچھ تم کرتے تھے میں تم کو جتا دوں گا۔', 'اور ہم نے تاکید کر دی انسان کو اپنے ماں باپ سے بھلائی سے رہنے کی اور اگر وہ تجھ سے زور کریں کہ تو شریک کرے میرا جس کی تجھ کو خبر نہیں [۸] تو انکا کہنا مت مان [۹] مجھی تک پھر آنا ہے تم کو سو میں بتلا دوں گا تمکو جو کچھ تم کرتے تھے [۱۰]', 'And We have enjoined on man to be good and dutiful to his parents, but if they strive to make you join with Me (in worship) anything (as a partner) of which you have no knowledge, then obey them not. Unto Me is your return, and I shall tell you what you used to do.', 'We have instructed man to do good to his parents. And if they insist upon you that you should ascribe partners to Me, then do not obey them. To Me is your return; then I shall tell you what you used to do.'),
(3349, 29, 9, 1, 13, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ لَنُدۡخِلَنَّہُمۡ  فِی الصّٰلِحِیۡنَ ﴿۹﴾', 'اور جو لوگ ایمان لائے اور نیک عمل کرتے رہے انکو ہم نیک لوگوں میں داخل کریں گے۔', 'اور جو لوگ یقین لائے اور بھلے کام کیے ہم ان کو داخل کریں گے نیک لوگوں میں [۱۱]', 'And for those who believe (in the Oneness of Allah and other items of Faith) and do righteous good deeds, surely, We shall make them enter in (the enterance of) the righteous (i.e. in Paradise).', 'And those who believe and do righteous deeds, We shall include them among the righteous.'),
(3350, 29, 10, 1, 13, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ مِنَ النَّاسِ مَنۡ یَّقُوۡلُ اٰمَنَّا بِاللّٰہِ  فَاِذَاۤ اُوۡذِیَ فِی اللّٰہِ جَعَلَ فِتۡنَۃَ  النَّاسِ کَعَذَابِ اللّٰہِ ؕ وَ لَئِنۡ جَآءَ  نَصۡرٌ مِّنۡ رَّبِّکَ لَیَقُوۡلُنَّ  اِنَّا کُنَّا مَعَکُمۡ ؕ اَوَ لَیۡسَ اللّٰہُ  بِاَعۡلَمَ بِمَا فِیۡ صُدُوۡرِ الۡعٰلَمِیۡنَ ﴿۱۰﴾', 'اور بعض لوگ ایسے ہیں جو کہتے ہیں کہ ہم اللہ پر ایمان لائے پھر جب انکو اللہ کے رستے میں کوئی ایذا پہنچتی ہے تو لوگوں کی ایذا کو یوں سمجھتے ہیں جیسے اللہ کا عذاب اور اگر تمہارے پروردگار کی طرف سے مدد پہنچے تو کہتے ہیں کہ ہم تو تمہارے ساتھ تھے۔ کیا جو اہل عالم کے سینوں میں ہے اللہ اس سے واقف نہیں؟', 'اور ایک وہ لوگ ہیں کہ کہتے ہیں یقین لائے ہم اللہ پر پھر جب اس کو ایذا پہنچے اللہ کی راہ میں کرنے لگے لوگوں کے ستانے کو برابر اللہ کے عذاب کے [۱۲] اور اگر آ پہنچے مدد تیرے رب کی طرف سے تو کہنے لگیں ہم تو تمہارے ساتھ ہیں [۱۳] کیا یہ نہیں کہ اللہ خوب خبردار ہے جو کچھ سینوں میں ہے جہان والوں کے [۱۴]', 'Of mankind are some who say: \"We believe in Allah,\" but if they are made to suffer for the sake of Allah, they consider the trial of mankind as Allahs punishment, and if victory comes from your Lord, (the hypocrites) will say: \"Verily! We were with you (helping you).\" Is not Allah Best Aware of what is in the breast of the Alameen (mankind and jinns).', 'Among men there are those who say, “We believe in Allah”, but when they are persecuted in (the way of) Allah, they take the persecution of men, as equal to the punishment of Allah. And should any help come from your Lord, they will certainly say, “We were with you.” Is it not that Allah knows well what lies in the hearts of the people of all the worlds?'),
(3351, 29, 11, 1, 13, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ لَیَعۡلَمَنَّ اللّٰہُ  الَّذِیۡنَ اٰمَنُوۡا وَ لَیَعۡلَمَنَّ الۡمُنٰفِقِیۡنَ ﴿۱۱﴾', 'اور اللہ ان کو ضرور معلوم کرے گا جو سچے مومن ہیں اور وہ منافقوں کو بھی معلوم کر کے رہے گا۔', 'اور البتہ معلوم کرے گا اللہ ان لوگوں کو جو یقین لائے ہیں اور البتہ معلوم کرے گا جو لوگ دغاباز ہیں [۱۵]', 'Verily, Allah knows those who believe, and verily, He knows the hypocrites (i.e. Allah will test the people with good and hard days to discriminate the good from the wicked (although Allah knows all that before putting them to test)).', 'Allah will certainly know those who believe and He will certainly know the hypocrites.'),
(3352, 29, 12, 1, 13, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ قَالَ الَّذِیۡنَ کَفَرُوۡا لِلَّذِیۡنَ اٰمَنُوا اتَّبِعُوۡا سَبِیۡلَنَا وَ لۡنَحۡمِلۡ خَطٰیٰکُمۡ ؕ وَ مَا ہُمۡ بِحٰمِلِیۡنَ مِنۡ خَطٰیٰہُمۡ مِّنۡ شَیۡءٍ ؕ اِنَّہُمۡ  لَکٰذِبُوۡنَ ﴿۱۲﴾', 'اور جو کافر ہیں وہ مومنوں سے کہتے ہیں کہ ہمارے طریقے پر چلو اور ہم تمہارے گناہ اٹھا لیں گے۔ حالانکہ وہ انکے گناہوں کا کچھ بھی بوجھ اٹھانے والے نہیں۔ کچھ شک نہیں کہ یہ جھوٹے ہیں۔', 'اور کہنے لگے منکر ایمان والوں کو تم چلو ہماری راہ اور ہم اٹھا لیں تمہارے گناہ [۱۶] اور  وہ کچھ نہ اٹھائیں گے ان کے گناہ بیشک وہ جھوٹے ہیں', 'And those who disbelieve say to those who believe: \"Follow our way and we will verily bear your sins,\" never will they bear anything of their sins. Surely, they are liars.', 'Those who disbelieve say to those who believe, “Follow our way, and we will bear the burden of your sins.” And they are not (able) to bear the burden of their sins in the least. Indeed they are pure liars.'),
(3353, 29, 13, 1, 13, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ لَیَحۡمِلُنَّ  اَثۡقَالَہُمۡ  وَ اَثۡقَالًا مَّعَ اَثۡقَالِہِمۡ ۫ وَ لَیُسۡـَٔلُنَّ یَوۡمَ الۡقِیٰمَۃِ عَمَّا کَانُوۡا یَفۡتَرُوۡنَ ﴿٪۱۳﴾', 'اور یہ اپنے بوجھ بھی اٹھائیں گے اور اپنے بوجھوں کے ساتھ اور لوگوں کے بوجھ بھی اور جو جھوٹ یہ لوگ گھڑتے رہے قیامت کے دن انکی ان سے ضرور پرسش ہو گی۔', 'اور البتہ اٹھائیں گے اپنے بوجھ اور کتنے بوجھ ساتھ اپنے بوجھ کے [۱۷] اور البتہ ان سے پوچھ ہو گی قیامت کے دن جو باتیں کہ جھوٹ بناتے تھے [۱۸]', 'And verily, they shall bear their own loads, and other loads besides their own, and verily, they shall be questioned on the Day of Resurrection about that which they used to fabricate.', 'They shall certainly bear their own loads, and some other loads along with their own loads, and they will certainly be questioned about what they used to forge.'),
(3354, 29, 14, 2, 14, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ لَقَدۡ  اَرۡسَلۡنَا نُوۡحًا  اِلٰی قَوۡمِہٖ فَلَبِثَ فِیۡہِمۡ  اَلۡفَ سَنَۃٍ  اِلَّا خَمۡسِیۡنَ عَامًا ؕ فَاَخَذَہُمُ  الطُّوۡفَانُ  وَ ہُمۡ  ظٰلِمُوۡنَ ﴿۱۴﴾', 'اور ہم نے نوح  کو انکی قوم کی طرف بھیجا تو وہ ان میں پچاس برس کم ہزار برس رہے۔ پھر ان لوگوں کو طوفان کے عذاب نے آ پکڑا۔ اور وہ ظالم تھے۔', 'اور ہم نے بھیجا نوح کو اس کی قوم کے پاس پھر رہا ان میں ہزار برس پچاس برس کم [۱۹] پھر پکڑا ان کو طوفان نے اور وہ گنہگار تھے [۲۰]', 'And indeed We sent Nooh (Noah) to his people, and he stayed among them a thousand years less fifty years (inviting them to believe in the Oneness of Allah (Monotheism), and discard the false gods and other deities), and the Deluge overtook them while they were Zalimoon (wrong-doers, polytheists, disbelievers, etc.).', 'We sent NūH to his people. So he stayed with them one thousand, less fifty, years. Then the Deluge seized them, and they were transgressors.'),
(3355, 29, 15, 2, 14, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'فَاَنۡجَیۡنٰہُ  وَ اَصۡحٰبَ السَّفِیۡنَۃِ وَ جَعَلۡنٰہَاۤ  اٰیَۃً  لِّلۡعٰلَمِیۡنَ ﴿۱۵﴾', 'پھر ہم نے نوح  کو اور کشتی والوں کو نجات دی۔ اور کشتی کو اہل عالم کے لئے نشانی بنا دیا۔', 'پھر بچا دیا ہم نے اسکو اور جہاز والوں کو [۲۱] اور  رکھا ہم نے جہاز کو نشانی جہاں والوں کے واسطے [۲۲]', 'Then We saved him and those with him in the ship, and made it (the ship) as an Ayah (a lesson, a warning, etc.) for the Alameen (mankind, jinns and all that exists).', 'So We saved him and the people of the Ark, and made it a sign for all the worlds.'),
(3356, 29, 16, 2, 14, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ  اِبۡرٰہِیۡمَ   اِذۡ قَالَ  لِقَوۡمِہِ اعۡبُدُوا اللّٰہَ وَ اتَّقُوۡہُ ؕ ذٰلِکُمۡ  خَیۡرٌ  لَّکُمۡ  اِنۡ  کُنۡتُمۡ  تَعۡلَمُوۡنَ ﴿۱۶﴾', 'اور ابراہیم  کو یاد کرو جب انہوں نے اپنی قوم سے کہا کہ اللہ کی عبادت کرو اور اس سے ڈرو۔ اگر تم سمجھ رکھتے ہو تو یہ تمہارے حق میں بہتر ہے۔', 'اور ابراہیم کو جب کہا اس نے اپنی قوم کو بندگی کرو اللہ کی اور ڈرتے رہو  اس سے یہ بہتر ہے تمہارے حق میں اگر تم سمجھ رکھتے ہو', 'And (remember) Ibrahim (Abraham) when he said to his people: \"Worship Allah (Alone), and fear Him, that is better for you if you did but know.', 'And (We sent) Ibrāhīm when he said to his people, “Worship Allah and fear Him. That is better for you if you know.'),
(3357, 29, 17, 2, 14, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'اِنَّمَا تَعۡبُدُوۡنَ مِنۡ دُوۡنِ اللّٰہِ  اَوۡثَانًا وَّ تَخۡلُقُوۡنَ  اِفۡکًا ؕ اِنَّ الَّذِیۡنَ تَعۡبُدُوۡنَ مِنۡ دُوۡنِ اللّٰہِ لَا یَمۡلِکُوۡنَ لَکُمۡ رِزۡقًا فَابۡتَغُوۡا عِنۡدَ اللّٰہِ الرِّزۡقَ وَ اعۡبُدُوۡہُ وَ اشۡکُرُوۡا لَہٗ ؕ  اِلَیۡہِ تُرۡجَعُوۡنَ ﴿۱۷﴾', 'تم تو اللہ کو چھوڑ کر بتوں کو پوجتے اور جھوٹی باتیں بناتے ہو جن لوگوں کو تم اللہ کے سوا پوجتے ہو وہ تمکو رزق دینے کا اختیار نہیں رکھتے پس اللہ ہی کے ہاں سے رزق طلب کرو اور اسی کی عبادت کرو اور اسی کا شکر کرو اسی کی طرف تم لوٹ کر جاؤ گے۔', 'تم تو پوجتے ہو اللہ کے سوائے یہ بتوں کے تھان اور بناتے ہو جھوٹی باتیں [۲۳] بیشک جن کو تم پوجتے ہو اللہ کے سوائے وہ مالک نہیں تمہاری روزی کے سو تم ڈھونڈو  اللہ کے یہاں روزی اور اس کی بندگی کرو اور اس کا حق مانو اسی کی طرف پھر جاؤ گے [۲۴]', '\"You worship besides Allah only idols, and you only invent falsehood. Verily, those whom you worship besides Allah have no power to give you provision, so seek your provision from Allah (Alone), and worship Him (Alone), and be grateful to Him. To Him (Alone) you will be brought back.', 'You only worship idols beside Allah, and you invent a lie. In fact those whom you worship beside Allah do not have power to give you provision. So seek provision with Allah and worship Him and be grateful to Him. To Him you are to be returned.'),
(3358, 29, 18, 2, 14, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ اِنۡ تُکَذِّبُوۡا فَقَدۡ کَذَّبَ اُمَمٌ مِّنۡ قَبۡلِکُمۡ ؕ وَ مَا عَلَی الرَّسُوۡلِ  اِلَّا الۡبَلٰغُ  الۡمُبِیۡنُ ﴿۱۸﴾', 'اور اگر تم جھٹلاتے ہو تو تم سے پہلے بھی امتیں اپنے پیغمبروں کی تکذیب کر چکی ہیں۔ اور پیغمبر کے ذمے کھول کر سنا دینے کے سوا اور کچھ نہیں۔', 'اور اگر تم جھٹلاؤ گے تو جھٹلا چکے ہیں بہت فرقے تم سے پہلے اور رسول کا ذمہ تو بس یہی ہے پیغام پہنچا دینا کھول کر [۲۵]', '\"And if you deny, then nations before you have denied (their Messengers). And the duty of the Messenger is only to convey (the Message) plainly.\"', 'And if you reject me, then many nations have rejected their messengers before you. The messenger has no more obligation than to convey the message clearly.”'),
(3359, 29, 19, 2, 14, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'اَوَ لَمۡ  یَرَوۡا کَیۡفَ یُبۡدِئُ اللّٰہُ  الۡخَلۡقَ ثُمَّ یُعِیۡدُہٗ ؕ اِنَّ ذٰلِکَ عَلَی اللّٰہِ یَسِیۡرٌ ﴿۱۹﴾', 'کیا انہوں نے نہیں دیکھا کہ اللہ کس طرح خلقت کو پہلی بار پیدا کرتا پھر کس طرح اسکو دوبارہ پیدا کرے گا۔ یہ اللہ کو آسان ہے۔', 'کیا دیکھتے نہیں کیونکر شروع کرتا ہے اللہ پیدائش کو پھر اس کو دہرائے گا [۲۶] یہ اللہ پر آسان ہے [۲۷]', 'See they not how Allah originates creation, then repeats it. Verily, that is easy for Allah.', 'Did they not see how Allah originates the creation, then He will do it again. Surely this is easy for Allah.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(3360, 29, 20, 2, 14, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'قُلۡ سِیۡرُوۡا فِی الۡاَرۡضِ فَانۡظُرُوۡا کَیۡفَ بَدَاَ  الۡخَلۡقَ ثُمَّ اللّٰہُ یُنۡشِیُٔ النَّشۡاَۃَ الۡاٰخِرَۃَ ؕ اِنَّ اللّٰہَ عَلٰی کُلِّ شَیۡءٍ  قَدِیۡرٌ ﴿ۚ۲۰﴾', 'کہدو کہ ملک میں چلو پھرو اور دیکھو کہ اس نے کس طرح خلقت کو پہلی دفعہ پیدا کیا ہے پھر اللہ ہی دوسری بار بھی پیدا کرے گا۔ بیشک اللہ ہر چیز پر قادر ہے۔', 'تو کہہ ملک میں پھرو  پھر دیکھو کیونکر شروع کیا ہے پیدائش کو پھر اللہ اٹھائے گا پچھلا اٹھان [۲۸] بیشک اللہ ہر چیز کر سکتا ہے', 'Say: \"Travel in the land and see how (Allah) originated creation, and then Allah will bring forth (resurrect) the creation of the Hereafter (i.e. resurrection after death). Verily, Allah is Able to do all things.\"', 'Say, “Go about in the land and look how He has originated the creation. Then Allah will create the subsequent creation. Surely Allah is powerful to do everything.”'),
(3361, 29, 21, 2, 14, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'یُعَذِّبُ مَنۡ یَّشَآءُ  وَ  یَرۡحَمُ  مَنۡ یَّشَآءُ ۚ وَ  اِلَیۡہِ تُقۡلَبُوۡنَ ﴿۲۱﴾', 'وہ جسے چاہے عذاب دے اور جس پر چاہے رحم کرے۔ اور اسی کی طرف تم لوٹائے جاؤ گے۔', 'دکھ دے گا جس کو چاہے اور رحم کرے گا جس پر چاہے [۲۹] اور اسی کی طرف پھر جاؤ گے', 'He punishes whom He will, and shows mercy to whom He will, and to Him you will be returned.', 'He punishes whom He wills and has mercy on whom He wills. And to Him you are to be turned back.'),
(3362, 29, 22, 2, 14, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ مَاۤ  اَنۡتُمۡ  بِمُعۡجِزِیۡنَ فِی الۡاَرۡضِ  وَ لَا فِی السَّمَآءِ ۫ وَ مَا لَکُمۡ مِّنۡ دُوۡنِ اللّٰہِ مِنۡ  وَّلِیٍّ   وَّ لَا  نَصِیۡرٍ ﴿٪۲۲﴾', 'اور تم اسکو نہ زمین میں عاجز کر سکتے ہو نہ آسمان میں اور نہ اللہ کے سوا تمہارا کوئی دوست ہے اور نہ مددگار۔', 'اور تم عاجز کرنے والے نہیں زمین میں اور نہ آسمان میں اور کوئی نہیں تمہارا اللہ سے ورے حمایتی اور نہ مددگار [۳۰]', 'And you cannot escape in the earth or in the heaven. And besides Allah you have neither any Walee (Protector or Guardian) nor any Helper.', 'You are not (able) to frustrate (Allah) neither in the earth nor in the sky. And, apart from Allah, you have neither a protector nor a helper.'),
(3363, 29, 23, 3, 15, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ الَّذِیۡنَ کَفَرُوۡا بِاٰیٰتِ اللّٰہِ وَ لِقَآئِہٖۤ اُولٰٓئِکَ یَئِسُوۡا مِنۡ رَّحۡمَتِیۡ وَ اُولٰٓئِکَ لَہُمۡ عَذَابٌ  اَلِیۡمٌ ﴿۲۳﴾', 'اور جن لوگوں نے اللہ کی آیتوں سے اور اسکے سامنے حاضر ہونے سے انکار کیا وہ میری رحمت سے ناامید ہو گئے ہیں اور انکو درد دینے والا عذاب ہو گا۔', 'اور جو لوگ منکر ہوئے اللہ کی باتوں سے اور اس کے ملنے سے وہ ناامید ہوئے میری رحمت سے [۳۱] اور ان کے لیے دردناک عذاب ہے', 'And those who disbelieve in the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah and the Meeting with Him, it is they who have no hope of My Mercy, and it is they who will (have) a painful torment.', 'And those who deny the signs of Allah and meeting with Him - those will despair of My mercy, and those are the ones for whom there is a painful punishment.'),
(3364, 29, 24, 3, 15, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'فَمَا کَانَ جَوَابَ قَوۡمِہٖۤ  اِلَّاۤ  اَنۡ قَالُوا اقۡتُلُوۡہُ  اَوۡ حَرِّقُوۡہُ  فَاَنۡجٰىہُ اللّٰہُ مِنَ النَّارِ ؕ اِنَّ  فِیۡ ذٰلِکَ لَاٰیٰتٍ لِّقَوۡمٍ یُّؤۡمِنُوۡنَ ﴿۲۴﴾', 'تو انکی قوم کے لوگ جواب میں بولے تو یہ بولے کہ اسے مار ڈالو یا جلا دو۔ مگر اللہ نے انکو آگ میں جلنے سے بچا لیا۔ جو لوگ ایمان رکھتے ہیں انکے لئے اس میں نشانیاں ہیں۔', 'پھر کچھ جواب نہ تھا اس کی قوم کا مگر  یہی کہ بولے اس کو مار ڈالو یا جلا دو [۳۲] پھر اس کو بچا دیا اللہ نے آگ سے [۳۳] اس میں بڑی نشانیاں ہیں ان لوگوں کے لیے جو  یقین لاتے ہیں [۳۴]', 'So nothing was the answer of (Ibraheems (Abraham)) people except that they said: \"Kill him or burn him.\" Then Allah saved him from the fire. Verily, in this are indeed signs for a people who believe.', 'So, the response of his (Ibrāhīm) people was none but that they said, “Kill him” or “Burn him”. So Allah saved him from the fire. Surely in this there are signs for a people who believe.'),
(3365, 29, 25, 3, 15, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ قَالَ  اِنَّمَا اتَّخَذۡتُمۡ مِّنۡ دُوۡنِ اللّٰہِ اَوۡثَانًا ۙ مَّوَدَّۃَ بَیۡنِکُمۡ فِی الۡحَیٰوۃِ الدُّنۡیَا ۚ ثُمَّ یَوۡمَ الۡقِیٰمَۃِ یَکۡفُرُ بَعۡضُکُمۡ بِبَعۡضٍ وَّ یَلۡعَنُ بَعۡضُکُمۡ بَعۡضًا ۫ وَّ مَاۡوٰىکُمُ النَّارُ وَ مَا لَکُمۡ مِّنۡ  نّٰصِرِیۡنَ ﴿٭ۙ۲۵﴾', 'اور ابرہیم  نے کہا کہ تم جو اللہ کو چھوڑ کر بتوں کو لے بیٹھے ہو تو دنیا کی زندگی میں باہم دوستی کے لئے مگر پھر قیامت کے دن ایک دوسرے کی دوستی سے انکار کر دو گے اور ایک دوسرے پر لعنت بھیجو گے اور تمہارا ٹھکانہ دوزخ ہو گا اور کوئی تمہارا مددگار نہ ہوگا۔', 'اور ابراہیم بولا [۳۵] جو ٹھہرائے ہیں تم نے اللہ کے سوائے بتوں کے تھان سو دوستی کر کر آپس میں دنیا کی زندگانی میں [۳۶] پھر دن قیامت کے منکر ہو جاؤ گے ایک سے ایک اور لعنت کرو گے ایک کو ایک [۳۷] اور ٹھکانا تمہارا آگ ہے اور کوئی نہیں تمہارا مددگار [۳۸]', 'And (Ibrahim (Abraham)) said: \"You have taken (for worship) idols instead of Allah, and the love between you is only in the life of this world, but on the Day of Resurrection, you shall disown each other, and curse each other, and your abode will be the Fire, and you shall have no helper.\"', 'And he (Ibrāhīm) said, “You have adopted idols instead of Allah, only because of love (you have) with each other in the worldly life. Then on the Day of Judgment you will reject each other, and will curse each other. And your abode is the Fire, and you will have no helpers.”'),
(3366, 29, 26, 3, 15, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'فَاٰمَنَ لَہٗ  لُوۡطٌ ۘ وَ  قَالَ  اِنِّیۡ مُہَاجِرٌ  اِلٰی رَبِّیۡ ؕ اِنَّہٗ  ہُوَ  الۡعَزِیۡزُ  الۡحَکِیۡمُ ﴿۲۶﴾', 'پس ان پر ایک لوط ایمان لائے اور ابراہیم  کہنے لگے کہ میں اپنے پروردگار کی طرف ہجرت کرنے والا ہوں۔ بیشک وہ غالب ہے حکمت والا ہے۔', 'پھر مان لیا اس کو لوط نے اور وہ بولا میں تو وطن چھوڑتا ہوں اپنے رب کی طرف بیشک وہی ہے زبردست حکمت والا [۳۹]', 'So Lout (Lot) believed in him (Ibrahims (Abraham) Message of Islamic Monotheism). He (Ibrahim (Abraham)) said: \"I will emigrate for the sake of my Lord. Verily, He is the All-Mighty, the All-Wise.\"', 'So LūT believed in him, and he (Ibrāhīm) said, “I am going to leave my homeland towards my Lord. Surely He is the Mighty, the Wise.'),
(3367, 29, 27, 3, 15, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ وَہَبۡنَا لَہٗۤ  اِسۡحٰقَ وَ  یَعۡقُوۡبَ وَ  جَعَلۡنَا فِیۡ  ذُرِّیَّتِہِ النُّبُوَّۃَ  وَ الۡکِتٰبَ وَ اٰتَیۡنٰہُ  اَجۡرَہٗ  فِی الدُّنۡیَا ۚ وَ اِنَّہٗ فِی الۡاٰخِرَۃِ  لَمِنَ الصّٰلِحِیۡنَ ﴿۲۷﴾', 'اور ہم نے انکو اسحٰق  اور یعقوب  بخشے اور انہی کی اولاد میں پیغمبری اور کتاب رکھ دی اور انکو دنیا میں بھی ان کا صلہ عنایت کیا اور وہ آخرت میں بھی نیک لوگوں میں ہوں گے۔', 'اور دیا ہم نے اس کو اسحٰق اور یعقوب [۴۰] اور رکھ دی اس کی اولاد میں پیغمبری اور کتاب [۴۱] اور دیا ہم نے اس کو اس کا ثواب دنیا میں اور وہ آخرت میں البتہ نیکوں سے ہے [۴۲]', 'And We bestowed on him (Ibrahim (Abraham)), Ishaque (Isaac) and Yaqoob (Jacob), and ordained among his offspring Prophethood and the Book (i.e. the Taurat (Torah) (to Moosa Moses), the Injeel (Gospel) (to Iesa Jesus), the Quran (to Muhammad SAW), all from the offspring of Ibrahim (Abraham)), and We granted him his reward in this world, and verily, in the Hereafter he is indeed among the righteous.', 'And We granted him IsHāq (Isaac) and Ya‘qūb (Jacob), and assigned prophet-hood and Book to his progeny, and gave him his reward in the world; and of course, in the Hereafter, he will be one of the righteous.'),
(3368, 29, 28, 3, 15, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ لُوۡطًا اِذۡ قَالَ لِقَوۡمِہٖۤ  اِنَّکُمۡ  لَتَاۡتُوۡنَ الۡفَاحِشَۃَ ۫ مَا سَبَقَکُمۡ  بِہَا مِنۡ اَحَدٍ مِّنَ الۡعٰلَمِیۡنَ ﴿۲۸﴾', 'اور لوط  کو یاد کرو جب انہوں نے اپنی قوم سے کہا کہ تم عجب بےحیائی کے مرتکب ہوتے ہو۔ تم سے پہلے اہل عالم میں سے کسی نے ایسا کام نہیں کیا۔', 'اور بھیجا لوط کو جب کہا اپنی قوم کو تم آتے ہو بیحیائی کے کام پر تم سے پہلے نہیں کیا وہ کسی نے جہان میں [۴۳]', 'And (remember) Lout (Lot), when he said to his people: \"You commit Al-Fahishah (sodomy the worst sin) which none has preceded you in (committing) it in the Alameen (mankind and jinns).\"', 'And (We sent) LūT when he said to his people, “Indeed you commit the shameful act that no one in the worlds has ever preceded you in it.'),
(3369, 29, 29, 3, 15, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'اَئِنَّکُمۡ لَتَاۡتُوۡنَ الرِّجَالَ وَ تَقۡطَعُوۡنَ السَّبِیۡلَ ۬ۙ وَ تَاۡتُوۡنَ فِیۡ نَادِیۡکُمُ الۡمُنۡکَرَ ؕ فَمَا کَانَ  جَوَابَ قَوۡمِہٖۤ  اِلَّاۤ اَنۡ  قَالُوا ائۡتِنَا بِعَذَابِ اللّٰہِ  اِنۡ  کُنۡتَ مِنَ الصّٰدِقِیۡنَ ﴿۲۹﴾', 'کیا تم مردوں کی طرف مائل ہوتے اور راہزنی کرتے ہو۔ اور اپنی مجلسوں میں ناپسندیدہ کام کرتے ہو۔ تو انکی قوم کے لوگ جواب میں بولے تو یہ بولے کہ اگر تم سچے ہو تو ہم پر عذاب لے آؤ۔', 'کیا تم دوڑتے ہو مردوں پر اور راہ مارتے ہو [۴۴] اور کرتے ہو اپنی مجلس میں برا کام [۴۵] پھر کچھ جواب نہ تھا اس کی قوم کا مگر یہی کہ بولے لے آ ہم پر عذاب ا للہ کا اگر تو ہے سچا [۴۶]', '\"Verily, you do sodomy with men, and rob the wayfarer (travellers, etc.)! And practise Al-Munkar (disbelief and polytheism and every kind of evil wicked deed) in your meetings.\" But his people gave no answer except, that they said: \"Bring Allahs Torment upon us if you are one of the truthful.\"', 'Is it (not) a fact that you go for men (to satisfy your lust) and rob the wayfarers and commit evil in your gathering?” So the answer of his people was none but that they said, “Bring us Allah’s punishment, if you are one of the truthful.”'),
(3370, 29, 30, 3, 15, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'قَالَ رَبِّ انۡصُرۡنِیۡ عَلَی الۡقَوۡمِ الۡمُفۡسِدِیۡنَ ﴿٪۳۰﴾', 'لوط  نے کہا کہ اے میرے پروردگار ان مفسد لوگوں کے مقابلے میں مجھے نصرت عنایت فرما۔', 'بولا اے رب میری مدد کر ان شریر لوگوں پر [۴۷]', 'He said: \"My Lord! Give me victory over the people who are Mufsidoon (those who commit great crimes and sins, oppressors, tyrants, mischief-makers, corrupts).', 'He said, “My Lord, help me against the people who make mischief.”'),
(3371, 29, 31, 4, 16, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ لَمَّا جَآءَتۡ رُسُلُنَاۤ  اِبۡرٰہِیۡمَ بِالۡبُشۡرٰی ۙ قَالُوۡۤا اِنَّا مُہۡلِکُوۡۤا اَہۡلِ ہٰذِہِ  الۡقَرۡیَۃِ ۚ اِنَّ  اَہۡلَہَا کَانُوۡا ظٰلِمِیۡنَ ﴿ۚۖ۳۱﴾', 'اور جب ہمارے فرشتے ابراہیم  کے پاس خوشی کی خبر لے کر آئے تو کہنے لگے کہ ہم اس بستی کے لوگوں کو ہلاک کر دینے والے ہیں کہ یہاں کے رہنے والے نافرمان ہیں۔', 'اور جب پہنچے ہمارے بھیجے ہوئے ابراہیم کےپاس خوشخبری لے کر بولے ہم کو غارت کرنا ہے اس بستی والوں کو بیشک اس کے لوگ ہور رہے ہیں گنہگار [۴۸]', 'And when Our Messengers came to Ibrahim (Abraham) with the glad tidings they said: \"Verily, we are going to destroy the people of this (Louts (Lots)) town (i.e. the town of Sodom in Palestine) truly, its people have been Zalimoon (wrong-doers, polytheists and disobedient to Allah, and have also belied their Messenger Lout (Lot)).\"', 'And when Our messengers came to Ibrāhīm with the good news, they said, “We are going to destroy the people of this town. Surely its people have been transgressors.”'),
(3372, 29, 32, 4, 16, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'قَالَ اِنَّ فِیۡہَا لُوۡطًا ؕ قَالُوۡا نَحۡنُ اَعۡلَمُ بِمَنۡ فِیۡہَا ٝ۫ لَنُنَجِّیَنَّہٗ  وَ اَہۡلَہٗۤ  اِلَّا امۡرَاَتَہٗ ٭۫ کَانَتۡ مِنَ  الۡغٰبِرِیۡنَ ﴿۳۲﴾', 'ابراہیم  نے کہا کہ اس میں تو لوط  بھی ہیں۔ وہ کہنے لگے کہ جو لوگ یہاں رہتے ہیں ہمیں سب معلوم ہیں۔ ہم انکو اور ان کے گھر والوں کو بچا لیں گے بجز انکی بیوی کے کہ وہ پیچھے رہنے والوں میں ہو گی۔', 'بولا اس میں تو لوط بھی ہے [۴۹] وہ بولے ہم کو خوب معلوم ہے جو کوئی اس میں ہے ہم بچا لیں گے اسکو اور اس کے گھر والوں کو مگر اس کی عورت کہ رہے گی رہ جانے والوں میں [۵۰]', 'Ibrahim (Abraham) said: \"But there is Lout (Lot) in it.\" They said:\"We know better who is there, we will verily save him (Lout (Lot)) and his family, except his wife, she will be of those who remain behind (i.e. she will be destroyed along with those who will be destroyed from her folk).\"', 'He said, “There is LūT in it.” They said, “We know well who is in it. We will certainly save him and his family except his wife who will be among those remaining behind.”'),
(3373, 29, 33, 4, 16, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ لَمَّاۤ  اَنۡ جَآءَتۡ رُسُلُنَا لُوۡطًا سِیۡٓءَ بِہِمۡ وَ ضَاقَ بِہِمۡ ذَرۡعًا وَّ قَالُوۡا لَا تَخَفۡ وَ لَا تَحۡزَنۡ ۟ اِنَّا مُنَجُّوۡکَ وَ اَہۡلَکَ  اِلَّا امۡرَاَتَکَ  کَانَتۡ  مِنَ  الۡغٰبِرِیۡنَ ﴿۳۳﴾', 'اور جب ہمارے فرشتے لوط  کے پاس آئے تو وہ انکی وجہ سے ناخوش اور تنگدل ہوئے۔ فرشتوں نے کہا کچھ خوف نہ کیجئے۔ اور نہ رنج کیجئے ہم آپکو اور آپ کے گھر والوں کو بچا لیں گے مگر آپ کی بیوی کہ پیچھے رہنے والوں میں ہوگی۔', 'اور جب پہنچے ہمارے بھیجے ہوئے لوط کے پاس ناخوش ہوا ان کو دیکھ کر اور تنگ ہوا دل میں [۵۱] اور وہ بولے مت ڈر اور غم نہ کھا ہم بچائیں گے تجھ کو اور تیرے گھر کو مگر عورت تیری رہ گئ رہ جانے والوں میں', 'And when Our Messengers came to Lout (Lot), he was grieved because of them, and felt straitened on their account. They said: \"Have no fear, and do not grieve! Truly, we shall save you and your family, except your wife, she will be of those who remain behind (i.e. she will be destroyed along with those who will be destroyed from her folk).', 'And when Our messengers came to LūT, he grieved for them and his heart was straitened because of them, but they said, “We are going to save you and your family, except your wife who will be among those remaining behind.'),
(3374, 29, 34, 4, 16, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'اِنَّا مُنۡزِلُوۡنَ عَلٰۤی اَہۡلِ ہٰذِہِ  الۡقَرۡیَۃِ رِجۡزًا مِّنَ السَّمَآءِ بِمَا کَانُوۡا یَفۡسُقُوۡنَ ﴿۳۴﴾', 'ہم اس بستی کے رہنے والوں پر اس سبب سے کہ یہ بدکرداری کرتے رہے ہیں آسمان سے عذاب نازل کرنے والے ہیں۔', 'ہم کو اتارنی ہے اس بستی والوں پر ایک آفت آسمان سے اس بات پر کہ وہ نافرمان ہو رہے تھے [۵۲]', 'Verily, we are about to bring down on the people of this town a great torment from the sky, because they have been rebellious (against Allahs Command).\"', 'We are going to bring down on the people of this town a punishment from the sky, because they used to act sinfully.”'),
(3375, 29, 35, 4, 16, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ لَقَدۡ تَّرَکۡنَا مِنۡہَاۤ  اٰیَۃًۢ  بَیِّنَۃً  لِّقَوۡمٍ یَّعۡقِلُوۡنَ ﴿۳۵﴾', 'اور ہم نے سمجھنے والے لوگوں کے لئے اس بستی کی ایک کھلی نشانی چھوڑ دی۔', 'اور چھوڑ رکھا ہم نے اس کا نشان نظر آتا ہوا سمجھ دار لوگوں کے واسطے [۵۳]', 'And indeed We have left thereof an evident Ayah (a lesson and a warning and a sign the place where the Dead Sea is now in Palestine) for a folk who understand.', 'And We left from it (the town) an evident sign for a people who understand.'),
(3376, 29, 36, 4, 16, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ اِلٰی مَدۡیَنَ  اَخَاہُمۡ شُعَیۡبًا ۙ فَقَالَ یٰقَوۡمِ اعۡبُدُوا اللّٰہَ وَ ارۡجُوا الۡیَوۡمَ الۡاٰخِرَ وَ لَا تَعۡثَوۡا فِی الۡاَرۡضِ مُفۡسِدِیۡنَ ﴿۳۶﴾', 'اور مدین کی طرف انکے بھائی شعیب کو بھیجا تو انہوں نے کہا اے قوم اللہ کی عبادت کرو اور روز آخر کے آنے کی امید رکھو اور ملک میں فساد نہ مچاؤ۔', 'اور بھیجا مدین کے پاس ان کے بھائی شعیب کو پھر بولا اے قوم بندگی کرو اللہ کی اور توقع رکھو پچھلے دن کی [۵۴] اور مت پھرو زمین میں خرابی مچاتے [۵۵]', 'And to (the people of) Madyan (Midian), We sent their brother Shuaib (Shuaib). He said: \"O my people! Worship Allah, and hope for (the reward of good deeds by worshipping Allah Alone, on) the last Day, and commit no mischief on the earth as Mufsidoon (those who commit great crimes, oppressors, tyrants, mischief-makers, corrupts).', 'And (We sent) to Madyan their brother Shu‘aib. So he said, “O my people, worship Allah and fear the Last Day, and do not roam about in the land as mischief makers.”'),
(3377, 29, 37, 4, 16, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'فَکَذَّبُوۡہُ  فَاَخَذَتۡہُمُ  الرَّجۡفَۃُ فَاَصۡبَحُوۡا  فِیۡ  دَارِہِمۡ  جٰثِمِیۡنَ ﴿۫۳۷﴾', 'مگر انہوں نے انکو جھوٹا سمجھا سو انکو زلزلے کے عذاب نے آ پکڑا اور وہ اپنے گھروں میں اوندھے پڑے رہ گئے۔', 'پھر اس کو جھٹلایا تو پکڑ لیا انکو زلزلے نے پھر صبح کو رہ گئے اپنے گھروں میں اوندھے پڑے', 'And they belied him (Shuaib (Shuaib)), so the earthquake seized them, and they lay (dead), prostrate in their dwellings.', 'So they gave the lie to him, then they were seized by the earthquake and they remained in their homes lying on their faces.'),
(3378, 29, 38, 4, 16, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ عَادًا وَّ ثَمُوۡدَا۠  وَ قَدۡ تَّبَیَّنَ  لَکُمۡ  مِّنۡ مَّسٰکِنِہِمۡ ۟ وَ زَیَّنَ لَہُمُ الشَّیۡطٰنُ اَعۡمَالَہُمۡ فَصَدَّہُمۡ عَنِ السَّبِیۡلِ وَ کَانُوۡا مُسۡتَبۡصِرِیۡنَ ﴿ۙ۳۸﴾', 'اور عاد اور ثمود کو بھی ہم نے ہلاک کر دیا چنانچہ انکے ویران گھر تمہاری آنکھوں کے سامنے ہیں اور شیطان نے انکے اعمال انکو آراستہ کر دکھائے اور انکو سیدھے رستے سے روک دیا۔ حالانکہ وہ دیکھنے والے لوگ تھے۔', 'اور ہلاک کیا عاد کو اور ثمود کو اور تم پر حال کھل چکا ہے ان کے گھروں سے [۵۶] اور فریفتہ کیا انکو شیطان نے ان کے کاموں پر پھر روک دیا ان کو راہ سے اور تھے ہوشیار [۵۷]', 'And Ad and Thamood (people)! And indeed (their destruction) is clearly apparent to you from their (ruined) dwellings. Shaitan (Satan) made their deeds fair-seeming to them, and turned them away from the (Right) Path, though they were intelligent.', 'And (We destroyed) ‘Ād and Thamūd, and it is visible to you through their dwellings. And the Satan had beautified for them their deeds, so he prevented them from the (right) way, even though they were people of insight.'),
(3379, 29, 39, 4, 16, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ قَارُوۡنَ وَ فِرۡعَوۡنَ وَ ہَامٰنَ ۟ وَ لَقَدۡ جَآءَہُمۡ  مُّوۡسٰی بِالۡبَیِّنٰتِ فَاسۡتَکۡبَرُوۡا فِی الۡاَرۡضِ وَ مَا کَانُوۡا سٰبِقِیۡنَ ﴿ۚۖ۳۹﴾', 'اور قارون اور فرعون اور ہامان کو بھی ہلاک کر دیا اور انکے پاس موسٰی  کھلی نشانیاں لے کر آئے تو وہ ملک میں مغرور ہو گئے اور وہ ہمارے قابو سے نکل جانے والے نہ تھے۔', 'اور ہلاک کیا قارون اور فرعون اور ہامان کو  اور ان کے پاس پہنچا موسٰی کھلی نشانیاں لے کر  پھر بڑائی کرنے لگے ملک میں اور نہیں تھے ہم سے جیت جانے والے [۵۸]', 'And (We destroyed also) Qaroon (Korah), Firaun (Pharaoh), and Haman. And indeed Moosa (Moses) came to them with clear Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), but they were arrogant in the land, yet they could not outstrip Us (escape Our punishment).', 'And (We also destroyed) Qārūn and Pharaoh and Hāmān. Indeed Mūsā came to them with clear signs; so they acted arrogantly on the earth, and were not (able) to escape.'),
(3380, 29, 40, 4, 16, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'فَکُلًّا  اَخَذۡنَا بِذَنۡۢبِہٖ ۚ فَمِنۡہُمۡ مَّنۡ اَرۡسَلۡنَا عَلَیۡہِ حَاصِبًا ۚ وَ  مِنۡہُمۡ مَّنۡ اَخَذَتۡہُ  الصَّیۡحَۃُ ۚ وَ مِنۡہُمۡ مَّنۡ خَسَفۡنَا بِہِ الۡاَرۡضَ ۚ وَ مِنۡہُمۡ مَّنۡ  اَغۡرَقۡنَا ۚ وَ مَا کَانَ اللّٰہُ  لِیَظۡلِمَہُمۡ  وَ لٰکِنۡ  کَانُوۡۤا  اَنۡفُسَہُمۡ  یَظۡلِمُوۡنَ ﴿۴۰﴾', 'تو ہم نے سب کو انکے گناہوں کے سبب پکڑ لیا۔ سو ان میں کچھ تو ایسے تھے جن پر ہم نے پتھروں کا مینہ برسایا۔ اور کچھ ایسے تھے جنکو چنگھاڑ نے آ پکڑا اور کچھ ایسے تھے جنکو ہم نے زمین میں دھنسا دیا۔ اور کچھ ایسے تھے جنکو غرق کر دیا اور اللہ ایسا نہ تھا کہ ان پر ظلم کرتا لیکن وہ ہی اپنے آپ پر ظلم کرتے تھے۔', 'پھر سب کو پکڑ ا ہم نے اپنے اپنے گناہ پر [۵۹] پھر کوئی تھا کہ اس پر ہم نے بھیجا پتھراؤ  ہوا سے [۶۰] اور کوئی تھا کہ اس کو  پکڑا چنگھاڑ نے [۶۱] اور کوئی تھا کہ اس کو دھنسا دیا ہم نے زمین میں [۶۲] اور کوئی تھا کہ اس کو ڈبا دیا ہم نے [۶۳] اور اللہ ایسا نہ تھا کہ ان پر ظلم کرے پر تھے وہ اپنا آپ ہی برا کرتے [۶۴]', 'So We punished each (of them) for his sins, of them were some on whom We sent Hasiban (a violent wind with shower of stones) (as the people of Lout (Lot)), and of them were some who were overtaken by AsSaihah (torment awful cry, etc. (as Thamood or Shuaibs people)), and of them were some whom We caused the earth to swallow (as Qaroon (Korah)), and of them were some whom We drowned (as the people of Nooh (Noah), or Firaun (Pharaoh) and his people). It was not Allah Who wronged them, but they wronged themselves.', 'Thus We seized each one of them for his sin. So to some of them We sent a violent wind; and some of them were seized by a Cry; and some of them We made to sink in the earth; and some of them We drowned. And Allah was not to do injustice to them, but they used to do injustice to their own selves.'),
(3381, 29, 41, 4, 16, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'مَثَلُ الَّذِیۡنَ اتَّخَذُوۡا مِنۡ دُوۡنِ اللّٰہِ اَوۡلِیَآءَ کَمَثَلِ الۡعَنۡکَبُوۡتِ ۖۚ اِتَّخَذَتۡ بَیۡتًا ؕ وَ اِنَّ  اَوۡہَنَ الۡبُیُوۡتِ لَبَیۡتُ الۡعَنۡکَبُوۡتِ ۘ  لَوۡ  کَانُوۡا  یَعۡلَمُوۡنَ ﴿۴۱﴾', 'جن لوگوں نے اللہ کے سوا اوروں کو کارساز بنا رکھا ہے انکی مثال مکڑی کی سی ہے کہ وہ بھی ایک طرح کا گھر بناتی ہے۔ اور کچھ شک نہیں کہ تمام گھروں سے کمزور مکڑی کا گھر ہے کاش یہ اس بات کو جانتے۔', 'مثال ان لوگوں کی جنہوں نے پکڑے اللہ کو چھوڑ کر اور حمایتی جیسے مکڑی کی مثال بنا لیا اس نے ایک گھر اور سب گھروں میں بودا سو مکڑی کا گھر اگر ان کو سمجھ ہوتی [۶۵]', 'The likeness of those who take Auliya (protectors and helpers) other than Allah is as the likeness of a spider, who builds (for itself) a house, but verily, the frailest (weakest) of houses is the spiders house; if they but knew.', 'The example of those who have adopted patrons other than Allah is like the spider that has made a house, while indeed the weakest of houses is the house of the spider. If only they know.'),
(3382, 29, 42, 4, 16, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'اِنَّ اللّٰہَ یَعۡلَمُ مَا یَدۡعُوۡنَ مِنۡ دُوۡنِہٖ مِنۡ شَیۡءٍ ؕ وَ  ہُوَ  الۡعَزِیۡزُ  الۡحَکِیۡمُ ﴿۴۲﴾', 'یہ جس چیز کو اللہ کے سوا پکارتے ہیں خواہ وہ کچھ ہی ہو اللہ اسے جانتا ہے۔ اور وہ غالب ہے حکمت والا ہے۔', 'اللہ جانتا ہے جس جس کو  وہ پکارتے ہیں اس کے سوائے کوئی چیز ہو [۶۶] اور وہ  زبردست ہے حکمتوں والا [۶۷]', 'Verily, Allah knows what things they invoke instead of Him. He is the All-Mighty, the All-Wise.', 'Surely, Allah knows whatever thing they invoke beside Allah, and He is the Mighty, the Wise.'),
(3383, 29, 43, 4, 16, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'وَ تِلۡکَ الۡاَمۡثَالُ نَضۡرِبُہَا لِلنَّاسِ ۚ وَ مَا یَعۡقِلُہَاۤ  اِلَّا  الۡعٰلِمُوۡنَ ﴿۴۳﴾', 'اور یہ مثالیں ہم لوگوں کے سمجھانے کے لئے بیان کرتے ہیں اور اسے تو اہل دانش ہی سمجھتے ہیں۔', 'اور یہ مثالیں بٹھلاتے ہیں ہم لوگوں کے واسطے اور ان کو سمجھتے وہی  ہیں جن کو سمجھ ہے [۶۸]', 'And these similitudes We put forward for mankind, but none will understand them except those who have knowledge (of Allah and His Signs, etc.).', 'We site these examples for people, but no one understands them except the knowledgeable ones.'),
(3384, 29, 44, 4, 16, 20, 'اَمَّنۡ  خَلَقَ', 'العنکبوت', 'خَلَقَ اللّٰہُ  السَّمٰوٰتِ وَ الۡاَرۡضَ بِالۡحَقِّ ؕ اِنَّ  فِیۡ  ذٰلِکَ لَاٰیَۃً   لِّلۡمُؤۡمِنِیۡنَ ﴿٪۴۴﴾', 'اللہ نے آسمانوں اور زمین کو حکمت کے ساتھ پیدا کیا ہے۔ کچھ شک نہیں کہ ایمان والوں کے لئے اس میں نشانی ہے۔', 'اللہ نے بنائے آسمان اور زمین جیسے چاہئیں [۶۹] اس میں نشانی ہے  یقین لانے  والوں کے لئے [۷۰]', '(Allah says to His Prophet Muhammad SAW): \"Allah (Alone) created the heavens and the earth with truth (and none shared Him in their creation).\" Verily! Therein is surely a sign for those who believe.', 'Allah has created the heavens and the earth with truth. Surely in this there is a sign for the believers.'),
(3385, 29, 45, 5, 1, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'اُتۡلُ مَاۤ  اُوۡحِیَ  اِلَیۡکَ مِنَ الۡکِتٰبِ وَ اَقِمِ الصَّلٰوۃَ ؕ اِنَّ الصَّلٰوۃَ  تَنۡہٰی عَنِ الۡفَحۡشَآءِ  وَ الۡمُنۡکَرِ ؕ وَ لَذِکۡرُ اللّٰہِ اَکۡبَرُ ؕ وَ اللّٰہُ یَعۡلَمُ مَا تَصۡنَعُوۡنَ ﴿۴۵﴾', 'اے نبی یہ کتاب جو تمہاری طرف وحی کی گئ ہے اسکو پڑھا کرو اور نماز کے پابند رہو۔ کچھ شک نہیں کہ نماز بے حیائی اور بری باتوں سے روکتی ہے۔ اور اللہ کا ذکر سب سے بڑا ہے۔ اور جو کچھ تم کرتے ہو اللہ اسے جانتا ہے۔', 'تو  پڑھ جو اتری تیری طرف کتاب [۷۱] اور قائم رکھ نماز بیشک نماز  روکتی ہے بیحیائی اور بری بات سے [۷۲] اور اللہ کی یاد ہے سب سے بڑی [۷۳] اور اللہ کو خبر ہے جو تم کرتے ہو [۷۴]', 'Recite (O Muhammad SAW) what has been revealed to you of the Book (the Quran), and perform As-Salat (IqamatasSalat). Verily, As-Salat (the prayer) prevents from Al-Fahsha (i.e. great sins of every kind, unlawful sexual intercourse, etc.) and Al-Munkar (i.e. disbelief, polytheism, and every kind of evil wicked deed, etc.) and the remembering (praising, etc.) of (you by) Allah (in front of the angels) is greater indeed (than your remembering (praising, etc.) Allah in prayers, etc.). And Allah knows what you do.', 'Recite (O Prophet) what is revealed to you of the Book, and establish Salāh . Surely Salāh restrains one from shameful and evil acts. Indeed remembrance of Allah is the greatest of all things. Allah knows what you do.'),
(3386, 29, 46, 5, 1, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'وَ لَا تُجَادِلُوۡۤا اَہۡلَ الۡکِتٰبِ اِلَّا بِالَّتِیۡ ہِیَ  اَحۡسَنُ ٭ۖ اِلَّا  الَّذِیۡنَ ظَلَمُوۡا مِنۡہُمۡ وَ قُوۡلُوۡۤا اٰمَنَّا بِالَّذِیۡۤ اُنۡزِلَ  اِلَیۡنَا وَ اُنۡزِلَ اِلَیۡکُمۡ وَ اِلٰـہُنَا وَ اِلٰـہُکُمۡ وَاحِدٌ  وَّ  نَحۡنُ  لَہٗ  مُسۡلِمُوۡنَ ﴿۴۶﴾', 'اور اہل کتاب سے بحث نہ کرو مگر ایسے طریق سے کہ نہایت اچھا ہو۔ ہاں جو ان میں سے بے انصافی کریں انکے ساتھ اسی طرح مجادلہ کرو اور کہدو کہ جو کتاب ہم پر اتری اور جو کتابیں تم پر اتریں ہم سب پر ایمان رکھتے ہیں اور ہمارا اور تمہارا معبود ایک ہی ہے اور ہم اسی کے فرمانبردار ہیں۔', 'اور جھگڑا نہ کرو  اہل کتاب سے  مگر اس طرح پر جو بہتر ہو مگر جو ان میں بے انصاف ہیں [۷۵] اور یوں کہو کہ  ہم مانتے ہیں جو اترا ہم کو اور اترا تم کو [۷۶] اور بندگی ہماری اور تمہاری ایک ہی کو  ہے اور ہم  اسی کے حکم پر چلتے ہیں [۷۷]', 'And argue not with the people of the Scripture (Jews and Christians), unless it be in (a way) that is better (with good words and in good manner, inviting them to Islamic Monotheism with His Verses), except with such of them as do wrong, and say (to them): \"We believe in that which has been revealed to us and revealed to you; our Ilah (God) and your Ilah (God) is One (i.e. Allah), and to Him we have submitted (as Muslims).\"', 'Do not debate with the people of the Book unless it is in the best manner, except with those of them who commit injustice. And say, “We believe in what is sent down to us and sent down to you, and our God and your God is One, and to Him we submit (ourselves).”'),
(3387, 29, 47, 5, 1, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'وَ کَذٰلِکَ  اَنۡزَلۡنَاۤ  اِلَیۡکَ الۡکِتٰبَ ؕ فَالَّذِیۡنَ اٰتَیۡنٰہُمُ الۡکِتٰبَ یُؤۡمِنُوۡنَ بِہٖ ۚ وَ مِنۡ ہٰۤؤُلَآءِ  مَنۡ یُّؤۡمِنُ بِہٖ ؕ وَ مَا یَجۡحَدُ  بِاٰیٰتِنَاۤ  اِلَّا الۡکٰفِرُوۡنَ ﴿۴۷﴾', 'اور اسی طرح ہم نے تمہاری طرف کتاب اتاری ہے۔ تو جن لوگوں کو ہم نے کتابیں دی تھیں وہ اس پر ایمان لے آتے ہیں۔ اور بعض ان مشرک لوگوں میں سے بھی اس پر ایمان لے آتے ہیں۔ اور ہماری آیتوں سے وہی انکار کرتے ہیں جو ہیں ہی کافر۔', 'اور ویسی ہی ہم نے اتاری تجھ پر کتاب [۷۸] سو جن کو ہم نے کتاب دی ہے وہ اس کو مانتے ہیں اور ان مکہ والوں میں بھی بعضے ہیں کہ اس کو مانتے ہیں اور منکر  وہی ہیں ہماری باتوں سے جو نافرمان ہیں [۷۹]', 'And thus We have sent down the Book (i.e this Quran) to you (O Muhammad SAW), and those whom We gave the Scripture (the Taurat (Torah) and the Injeel (Gospel) aforetime) believe therein as also do some of these (who are present with you now like Abdullah bin Salam) and none but the disbelievers reject Our Ayat ((proofs, signs, verses, lessons, etc., and deny Our Oneness of Lordship and Our Oneness of worship and Our Oneness of Our Names and Qualities: i.e. Islamic Monotheism)).', 'Thus We have sent down the Book to you. So those to whom We have given the Book believe in it. And from these (the people of Makkah) there are ones who believe in it, and no one rejects Our verses except the infidels.'),
(3388, 29, 48, 5, 1, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'وَ مَا کُنۡتَ تَتۡلُوۡا مِنۡ قَبۡلِہٖ مِنۡ کِتٰبٍ وَّ لَا تَخُطُّہٗ  بِیَمِیۡنِکَ اِذًا  لَّارۡتَابَ الۡمُبۡطِلُوۡنَ ﴿۴۸﴾', 'اور تم اس سے پہلے کوئی کتاب نہیں پڑھتے تھے اور نہ اسے اپنے ہاتھ سے لکھ ہی سکتے تھے ایسا ہوتا تو اہل باطل ضرور شک کرتے۔', 'اور تو پڑھتا نہ تھا اس سے  پہلے کوئی کتاب اور نہ لکھتا تھا اپنے داہنے ہاتھ سے تب تو البتہ شبہ میں پڑتے یہ جھوٹے [۸۰]', 'Neither did you (O Muhammad SAW) read any book before it (this Quran), nor did you write any book (whatsoever) with your right hand. In that case, indeed, the followers of falsehood might have doubted.', 'You (O Prophet,) have never been reciting any book before this, nor have you been writing it with your right hand; had it been so, the adherents of falsehood would have raised doubts.'),
(3389, 29, 49, 5, 1, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'بَلۡ ہُوَ اٰیٰتٌۢ بَیِّنٰتٌ فِیۡ صُدُوۡرِ الَّذِیۡنَ اُوۡتُوا الۡعِلۡمَ ؕ وَ مَا یَجۡحَدُ بِاٰیٰتِنَاۤ  اِلَّا الظّٰلِمُوۡنَ ﴿۴۹﴾', 'بلکہ یہ روش آیتیں ہیں۔ جن لوگوں کو علم دیا گیا ہے انکے سینوں میں محفوظ اور ہماری آیتوں سے وہی لوگ انکار کرتے ہیں جو بےانصاف ہیں۔', 'بلکہ یہ قرآن تو آیتیں ہیں صاف ان لوگوں کے سینوں میں جن کو ملی ہے سمجھ [۸۱] اور منکر نہیں ہماری باتوں سے مگر وہی جو بے انصاف ہیں [۸۲]', 'Nay, but they, the clear Ayat (i.e the description and the qualities of Prophet Muhammad SAW written like verses in the Taurat (Torah) and the Injeel (Gospel)) are preserved in the breasts of those who have been given knowledge (from the people of the Scriptures). And none but the Zalimoon (polytheists and wrongdoers, etc.) deny Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.).', 'But it (the Qur’ān in itself) is (a package of) evident signs in the hearts of those who are given knowledge. And no one rejects our verses except the wrongdoers.'),
(3390, 29, 50, 5, 1, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'وَ قَالُوۡا لَوۡ لَاۤ   اُنۡزِلَ عَلَیۡہِ اٰیٰتٌ مِّنۡ رَّبِّہٖ ؕ قُلۡ  اِنَّمَا الۡاٰیٰتُ عِنۡدَ اللّٰہِ ؕ وَ اِنَّمَاۤ   اَنَا نَذِیۡرٌ  مُّبِیۡنٌ ﴿۵۰﴾', 'اور کافر کہتے ہیں کہ اس پر اسکے پروردگار کی طرف سے نشانیاں کیوں نازل نہیں ہوئیں کہدو کہ نشانیاں تو اللہ ہی کے پاس ہیں۔ اور میں تو کھلم کھلا خبردار کرنے والا ہوں۔', 'اور کہتے ہیں کیوں نہ اتریں اس پر کچھ نشانیاں اس کے رب سے تو کہہ نشانیاں تو ہیں اختیار میں اللہ کے اور میں تو بس سنا دینے والا ہوں کھول کر [۸۳]', 'And they say: \"Why are not signs sent down to him from his Lord? Say: \"The signs are only with Allah, and I am only a plain warner.\"', 'And they say, “Why is it that no signs (miracles) have been sent down to him from his Lord?” Say, “Signs are only with Allah, and I am only a plain warner.”'),
(3391, 29, 51, 5, 1, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'اَوَ لَمۡ یَکۡفِہِمۡ  اَنَّاۤ  اَنۡزَلۡنَا عَلَیۡکَ الۡکِتٰبَ یُتۡلٰی عَلَیۡہِمۡ ؕ اِنَّ  فِیۡ ذٰلِکَ لَرَحۡمَۃً  وَّ ذِکۡرٰی  لِقَوۡمٍ  یُّؤۡمِنُوۡنَ ﴿٪۵۱﴾', 'کیا ان لوگوں کے لئے یہ کافی نہیں کہ ہم نے تم پر کتاب نازل کی جو انکو پڑھ کر سنائی جاتی ہے۔ کچھ شک نہیں کہ مومن لوگوں کے لئے اس میں رحمت اور نصیحت ہے۔', 'کیا ان کو  یہ کافی نہیں کہ ہم نے تجھ پر اتاری کتاب کہ ان پر پڑھی جاتی ہے بیشک اس میں رحمت ہے اور سمجھانا ان لوگوں کو جو مانتے ہیں [۸۴]', 'Is it not sufficient for them that We have sent down to you the Book (the Quran) which is recited to them? Verily, herein is mercy and a reminder (or an admonition) for a people who believe.', 'Is it not sufficient for them that We have sent down to you the Book that is being recited to them? Surely in it there is mercy and advice for a people who believe.'),
(3392, 29, 52, 6, 2, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'قُلۡ  کَفٰی بِاللّٰہِ  بَیۡنِیۡ وَ بَیۡنَکُمۡ  شَہِیۡدًا ۚ یَعۡلَمُ مَا فِی السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ الَّذِیۡنَ اٰمَنُوۡا بِالۡبَاطِلِ وَ کَفَرُوۡا بِاللّٰہِ ۙ اُولٰٓئِکَ  ہُمُ  الۡخٰسِرُوۡنَ ﴿۵۲﴾', 'کہدو کہ میرے اور تمہارے درمیان اللہ ہی گواہ کافی ہے جو چیز آسمانوں اور زمین میں ہے وہ سب کو جانتا ہے۔ اور جن لوگوں نے باطل کو مانا اور اللہ سے انکار کیا وہی نقصان اٹھانے والے ہیں۔', 'تو کہہ کافی ہے اللہ میرے اور تمہارے بیچ گواہ جانتا ہے جو کچھ ہے آسمان اور زمین میں [۸۵] اور جو لوگ یقین لاتے ہیں جھوٹ پر  اور منکر ہوئے ہیں اللہ سے وہی ہیں نقصان پانے  والے [۸۶]', 'Say (to them O Muhammad SAW): \"Sufficient is Allah for a witness between me and you. He knows what is in the heavens and on earth.\" And those who believe in Batil (all false deities other than Allah), and disbelieve in Allah and (in His Oneness), it is they who are the losers.', 'Say, “Allah is enough as a witness between me and you. He knows what is in the heavens and the earth. And those who believe in falsity and do not believe in Allah,-those are the losers.'),
(3393, 29, 53, 6, 2, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'وَ یَسۡتَعۡجِلُوۡنَکَ بِالۡعَذَابِ ؕ وَ لَوۡ لَاۤ اَجَلٌ مُّسَمًّی لَّجَآءَہُمُ  الۡعَذَابُ ؕ وَ لَیَاۡتِیَنَّہُمۡ  بَغۡتَۃً  وَّ  ہُمۡ  لَا  یَشۡعُرُوۡنَ ﴿۵۳﴾', 'اور یہ لوگ تم سے عذاب کے لئے جلدی کر رہے ہیں۔ اور اگر ایک وقت مقرر نہ ہو چکا ہوتا تو ان پر عذاب آ بھی گیا ہوتا۔ اور وہ کسی وقت میں ان پر ضرور اچانک آ کر رہے گا اور انکو معلوم بھی نہ ہوگا۔', 'اور جلد مانگتے ہیں تجھ سے آفت [۸۷] اور اگر نہ ہوتا ایک وعدہ مقررہ تو آ پہنچتی ان پر آفت اور البتہ آئے گی ان پر اچانک  اور ان کو خبر نہ ہو گی [۸۸]', 'And they ask you to hasten on the torment (for them), and had it not been for a term appointed, the torment would certainly have come to them. And surely, it will come upon them suddenly while they perceive not!', 'They ask you to bring the punishment soon. Had there not been an appointed time, the punishment would have come to them. It will surely come to them suddenly while they will not be aware.'),
(3394, 29, 54, 6, 2, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'یَسۡتَعۡجِلُوۡنَکَ بِالۡعَذَابِ ؕ وَ  اِنَّ  جَہَنَّمَ لَمُحِیۡطَۃٌۢ  بِالۡکٰفِرِیۡنَ ﴿ۙ۵۴﴾', 'یہ تم سے عذاب کے لئے جلدی کر رہے ہیں۔ جبکہ دوزخ تو کافروں کو گھیر لینے والی ہے۔', 'جلدی مانگتے ہیں تجھ سے عذاب [۸۹] اور دوزخ گھیر رہی ہے مجرموں کو [۹۰]', 'They ask you to hasten on the torment. And verily! Hell, of a surety, will encompass the disbelievers.', 'They ask you to bring the punishment soon, while the Jahannam is surely going to engulf the disbelievers'),
(3395, 29, 55, 6, 2, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'یَوۡمَ  یَغۡشٰہُمُ  الۡعَذَابُ مِنۡ فَوۡقِہِمۡ وَ مِنۡ تَحۡتِ اَرۡجُلِہِمۡ وَ یَقُوۡلُ ذُوۡقُوۡا مَا کُنۡتُمۡ  تَعۡمَلُوۡنَ ﴿۵۵﴾', 'جس دن عذاب انکو انکے اوپر سے اور انکے پیروں کے نیچے سے ڈھانک لے گا اور اللہ فرمائے گا کہ جو کام تم کیا کرتے تھے اب ان کا مزہ چکھو۔', 'جس دن گھیر لے گا ان کو عذاب ان کے اوپر سے اور پاؤں کے نیچے سے اور کہے گا چکھو جیسا کچھ تم کرتے تھے [۹۱]', 'On the Day when the torment (Hell-fire) shall cover them from above them and from underneath their feet, and it will be said: \"Taste what you used to do.\"', 'on the Day when the punishment will envelop them from above them and from under their feet and He (Allah) will say, “Taste what you used to do.”'),
(3396, 29, 56, 6, 2, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'یٰعِبَادِیَ الَّذِیۡنَ اٰمَنُوۡۤا اِنَّ  اَرۡضِیۡ وَاسِعَۃٌ   فَاِیَّایَ  فَاعۡبُدُوۡنِ ﴿۵۶﴾', 'اے میرے بندو جو ایمان لائے ہو میری زمین فراخ ہے تو میری ہی عبادت کرو۔', 'اے بندو میرے جو یقین لائے ہو میری زمین کشادہ ہے سو مجھی کو بندگی کر و [۹۲]', 'O My slaves who believe! Certainly, spacious is My earth. Therefore worship Me (Alone).\"', 'O My servants who believe, surely My earth is vast. So, Me alone you must worship.'),
(3397, 29, 57, 6, 2, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'کُلُّ نَفۡسٍ ذَآئِقَۃُ  الۡمَوۡتِ ۟ ثُمَّ  اِلَیۡنَا تُرۡجَعُوۡنَ ﴿۵۷﴾', 'ہر شخص موت کا مزہ چکھنے والا ہے۔ پھر تم ہماری ہی طرف لوٹ کر آؤ گے۔', 'جو جی ہے سو چکھے گا موت پھر ہماری طرف پھر آؤ گے [۹۳]', 'Everyone shall taste the death. Then unto Us you shall be returned.', 'Every person has to taste death, then to Us you are to be returned.'),
(3398, 29, 58, 6, 2, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'وَ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ لَنُبَوِّئَنَّہُمۡ مِّنَ الۡجَنَّۃِ غُرَفًا تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَا ؕ نِعۡمَ  اَجۡرُ  الۡعٰمِلِیۡنَ ﴿٭ۖ۵۸﴾', 'اور جو لوگ ایمان لائے اور نیک عمل کرتے رہے انکو ہم بہشت کے اونچے اونچے محلوں میں جگہ دیں گے جنکے نیچے نہریں بہ رہی ہیں۔ ہمیشہ ان میں رہیں گے۔ نیک عمل کرنے والوں کا یہ خوب بدلہ ہے۔', 'اور جو  لوگ یقین لائے اور کیے بھلے کام ان کو ہم جگہ دیں گے بہشت میں جھروکے نیچے بہتی ہیں ان کےنہریں سدا رہیں ان میں خوب ثواب ملا کام  والوں کو', 'And those who believe (in the Oneness of Allah Islamic Monotheism) and do righteous good deeds, to them We shall surely give lofty dwellings in Paradise, underneath which rivers flow, to live therein forever. Excellent is the reward of the workers.', 'As for those who believe and do righteous deeds, We shall accommodate them in mansions of the Paradise beneath which rivers flow, where they will live forever. Excellent is the reward of the workers,'),
(3399, 29, 59, 6, 2, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'الَّذِیۡنَ صَبَرُوۡا وَ عَلٰی رَبِّہِمۡ یَتَوَکَّلُوۡنَ ﴿۵۹﴾', 'جو صبر کرتے اور اپنے پروردگار پر بھروسہ رکھتے ہیں۔', 'جنہوں نے صبر کیا اور اپنے رب پر بھروسہ رکھا [۹۴]', 'Those who are patient, and put their trust (only) in their Lord (Allah).', 'who observe restraint patiently and place their trust in their Lord alone.'),
(3400, 29, 60, 6, 2, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'وَ کَاَیِّنۡ مِّنۡ دَآبَّۃٍ  لَّا تَحۡمِلُ رِزۡقَہَا ٭ۖ اَللّٰہُ  یَرۡزُقُہَا وَ اِیَّاکُمۡ ۫ۖ  وَ ہُوَ السَّمِیۡعُ  الۡعَلِیۡمُ ﴿۶۰﴾', 'اور بہت سے جانور ہیں جو اپنا رزق اٹھانے نہیں پھرتے اللہ ہی انکو رزق دیتا ہے اور تمکو بھی۔ اور وہ سننے والا ہے جاننے والا ہے۔', 'اور کتنے جانور ہیں جو اٹھا نہیں رکھتے اپنی روزی اللہ روزی دیتا ہے انکو اور تم کو بھی اور وہی ہے سننے والا جاننے والا [۹۵]', 'And so many a moving (living) creature there is, that carries not its own provision! Allah provides for it and for you. And He is the All-Hearer, the AllKnower.', 'How many an animal there is that does not carry its provision. Allah gives provision to it as well as to you, and He is the All-Hearing, the All-knowing.'),
(3401, 29, 61, 6, 2, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'وَ لَئِنۡ سَاَلۡتَہُمۡ مَّنۡ خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ وَ سَخَّرَ الشَّمۡسَ وَ الۡقَمَرَ لَیَقُوۡلُنَّ  اللّٰہُ ۚ فَاَنّٰی  یُؤۡفَکُوۡنَ ﴿۶۱﴾', 'اور اگر ان سے پوچھو کہ آسمانوں اور زمین کو کس نے پیدا کیا۔ اور سورج اور چاند کو کس نے تمہارے زیر فرمان کیا تو کہدیں گے اللہ نے۔ تو پھر یہ کہاں الٹے جا رہے ہیں۔', 'اور اگر تو لوگوں سے پوچھے کہ کس نے بنایا ہے آسمان اور زمین کو اور کام میں لگایا سورج اور چاند کو تو کہیں اللہ نے پھر کہاں سے الٹ جاتے ہیں [۹۶]', 'If you were to ask them: \"Who has created the heavens and the earth and subjected the sun and the moon?\" They will surely reply: \"Allah.\" How then are they deviating (as polytheists and disbelievers)?', 'If you ask them as to who has created the heavens and the earth and has subjugated the sun and the moon, they will certainly say, “Allah”. How then are they driven aback (by their whims?)'),
(3402, 29, 62, 6, 2, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'اَللّٰہُ یَبۡسُطُ الرِّزۡقَ لِمَنۡ یَّشَآءُ مِنۡ عِبَادِہٖ  وَ یَقۡدِرُ  لَہٗ  ؕ اِنَّ  اللّٰہَ  بِکُلِّ  شَیۡءٍ عَلِیۡمٌ ﴿۶۲﴾', 'اللہ ہی اپنے بندوں میں سے جسکے لئے چاہتا ہے روزی فراخ کر دیتا ہے اور جسکے لئے چاہتا ہے تنگ کر دیتا ہے بیشک اللہ ہر چیز سے واقف ہے۔', 'اللہ پھیلاتا ہے روزی جس کے واسطے چاہے اپنے بندوں میں اور ماپ کر دیتا ہے جسکو چاہے [۹۷] بیشک اللہ ہر چیز سے خبردار ہے [۹۸]', 'Allah enlarges the provision for whom He wills of His slaves, and straitens it for whom (He wills). Verily, Allah is the AllKnower of everything.', 'Allah extends provision to whom He wills from His servants, and straitens it (for whom He wills). Surely Allah knows every thing well.'),
(3403, 29, 63, 6, 2, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'وَ لَئِنۡ سَاَلۡتَہُمۡ مَّنۡ نَّزَّلَ مِنَ السَّمَآءِ مَآءً  فَاَحۡیَا بِہِ الۡاَرۡضَ مِنۡۢ بَعۡدِ مَوۡتِہَا لَیَقُوۡلُنَّ اللّٰہُ ؕ قُلِ الۡحَمۡدُ لِلّٰہِ ؕ بَلۡ  اَکۡثَرُہُمۡ  لَا  یَعۡقِلُوۡنَ ﴿٪۶۳﴾', 'اور اگر تم ان سے پوچھو کہ آسمان سے پانی کس نے برسایا پھر اس سے زمین کو اسکے مرنے کے بعد کس نے زندہ کیا تو کہدیں گے کہ اللہ نے۔ کہدو کہ اللہ کا شکر ہے لیکن ان میں اکثر نہیں سمجھتے۔', 'اور جو تو پوچھے ان سے کس نے اتارا  آسمان سے پانی پھر زندہ کر دیا اس سے زمین کو اس کے مرجانے کے بعد تو کہیں اللہ نے تو کہہ سب خوبی اللہ کو ہے پر بہت لوگ نہیں سمجھتے [۹۹]', 'If you were to ask them: \"Who sends down water (rain) from the sky, and gives life therewith to the earth after its death?\" They will surely reply: \"Allah.\" Say: \"All the praises and thanks be to Allah!\" Nay! Most of them have no sense.', 'And if you ask them as to who sends down water from the sky, then revives the land with it, they will certainly say, “Allah”. Say, “Praise is for Allah.” But most of them do not understand.'),
(3404, 29, 64, 7, 3, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'وَ مَا ہٰذِہِ  الۡحَیٰوۃُ  الدُّنۡیَاۤ  اِلَّا لَہۡوٌ وَّ لَعِبٌ ؕ وَ اِنَّ الدَّارَ الۡاٰخِرَۃَ  لَہِیَ الۡحَیَوَانُ ۘ لَوۡ  کَانُوۡا یَعۡلَمُوۡنَ ﴿۶۴﴾', 'اور یہ دنیا کی زندگی تو صرف کھیل اور تماشا ہے اور ہمیشہ کی زندگی کا مقام تو آخرت کا گھر ہے کاش یہ لوگ سمجھتے۔', 'اور یہ دنیا کا جینا تو بس جی بہلانا اور کھیلنا ہے اور پچھلا گھر جو ہے سو وہی ہے زندہ رہنا اگر ان کو سمجھ ہوتی [۱۰۰]', 'And this life of the world is only amusement and play! Verily, the home of the Hereafter, that is the life indeed (i.e. the eternal life that will never end), if they but knew', 'This worldly life is nothing but an amusement and play, and the Last Abode is the real life indeed. Only if they know!'),
(3405, 29, 65, 7, 3, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'فَاِذَا  رَکِبُوۡا فِی الۡفُلۡکِ دَعَوُا اللّٰہَ مُخۡلِصِیۡنَ لَہُ  الدِّیۡنَ ۬ۚ فَلَمَّا نَجّٰہُمۡ  اِلَی الۡبَرِّ   اِذَا  ہُمۡ   یُشۡرِکُوۡنَ ﴿ۙ۶۵﴾', 'پھر جب یہ کشتی میں سوار ہوتے ہیں تو اللہ کو پکارتے خالص کرتے ہوئے اسی کیلئے اطاعت کو۔ لیکن جب وہ انکو نجات دے کر خشکی پر پہنچا دیتا ہے تو جھٹ شرک کر نے لگ جاتے ہیں۔', 'پھر جب سوار ہوئے کشتی میں پکارنے لگے اللہ کو خالص اسی پر رکھ کر اعتقاد پھر جب بچا لایا انکو  زمین کی طرف اسی وقت لگے شریک بنانے', 'And when they embark on a ship, they invoke Allah, making their Faith pure for Him only, but when He brings them safely to land, behold, they give a share of their worship to others.', 'So when they embark on a ship, they invoke Allah, having their faith purely in Him. But when He saves them (and brings them) to the land, in no time they start committing shirk (ascribing partners to Allah),'),
(3406, 29, 66, 7, 3, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'لِیَکۡفُرُوۡا بِمَاۤ  اٰتَیۡنٰہُمۡ ۚۙ وَ لِیَتَمَتَّعُوۡا ٝ فَسَوۡفَ یَعۡلَمُوۡنَ ﴿۶۶﴾', 'تاکہ جو ہم نے انکو بخشا ہے اسکی ناشکری کریں اور فائدہ اٹھائیں سو خیر عنقریب انکو معلوم ہو جائے گا۔', 'تاکہ مکرتے رہیں ہمارے دیے ہوئے سے اور مزے اڑاتے رہیں سو عنقریب جان لیں گے [۱۰۱]', 'So that they become ingrate for that which We have given them, and that they take their enjoyment (as a warning and a threat), but they will come to know.', 'thus becoming ungrateful for what We gave to them. Let them have some enjoyment, then they will soon come to know (the ill-fate of their attitude).'),
(3407, 29, 67, 7, 3, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'اَوَ لَمۡ  یَرَوۡا  اَنَّا جَعَلۡنَا حَرَمًا  اٰمِنًا  وَّ یُتَخَطَّفُ النَّاسُ مِنۡ حَوۡلِہِمۡ ؕ اَفَبِالۡبَاطِلِ یُؤۡمِنُوۡنَ وَ بِنِعۡمَۃِ اللّٰہِ یَکۡفُرُوۡنَ ﴿۶۷﴾', 'کیا انہوں نے نہیں دیکھا کہ ہم نے حرم کو مقام امن بنایا ہے اور لوگ انکے گردونواح سے اچک لئے جاتے ہیں۔ کیا یہ لوگ باطل پر اعتقاد رکھتے ہیں اور اللہ کی نعمتوں کی ناشکری کرتے ہیں۔', 'کیا نہیں دیکھتے کہ ہم نے رکھ دی ہے پناہ کی جگہ امن کی اور لوگ اچکے جاتے ہیں ان کے آس پاس سے کیاجھوٹ پر یقین رکھتے ہیں اور اللہ کا احسان نہیں مانتے [۱۰۲]', 'Have they not seen that We have made (Makkah) a sanctuary secure, and that men are being snatched away from all around them? Then do they believe in Batil (falsehood - polytheism, idols and all deities other than Allah), and deny (become ingrate for) the Graces of Allah?', 'Did they not see that We have made a peaceful sanctuary (Haram ) while (other) people around them are being snatched away? Do they still believe in falsity and reject Allah’s grace?'),
(3408, 29, 68, 7, 3, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'وَ مَنۡ اَظۡلَمُ  مِمَّنِ افۡتَرٰی عَلَی اللّٰہِ  کَذِبًا اَوۡ کَذَّبَ بِالۡحَقِّ  لَمَّا جَآءَہٗ ؕ اَلَیۡسَ فِیۡ جَہَنَّمَ مَثۡوًی  لِّلۡکٰفِرِیۡنَ ﴿۶۸﴾', 'اور اس سے بڑا ظالم کون جو اللہ پر جھوٹ بہتان باندھے یا جب حق بات اسکے پاس آئے تو اسکی تکذیب کرے۔ کیا کافروں کا ٹھکانہ جہنم میں نہیں ہے؟', 'اور اس سے زیادہ بے انصاف کون جو باندھے اللہ پر جھوٹ یا جھٹلائے سچی بات کو جب اس تک پہنچے کیا دوزخ میں بسنے کی جگہ نہیں منکروں کے لئے [۱۰۳]', 'And who does more wrong than he who invents a lie against Allah or denies the truth (Muhammad SAW and his doctrine of Islamic Monotheism and this Quran), when it comes to him? Is there not a dwelling in Hell for disbelievers (in the Oneness of Allah and in His Messenger Muhammad SAW)?', 'Who is more unjust than the one who forges a lie against Allah or rejects the truth when it comes to him? Is there not in Jahannam a home for disbelievers?'),
(3409, 29, 69, 7, 3, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'العنکبوت', 'وَ الَّذِیۡنَ جَاہَدُوۡا فِیۡنَا لَنَہۡدِیَنَّہُمۡ سُبُلَنَا ؕ وَ اِنَّ اللّٰہَ  لَمَعَ الۡمُحۡسِنِیۡنَ ﴿٪۶۹﴾', 'اور جن لوگوں نے ہمارے راستے میں محنت کی ہم ان کو ضرور اپنے رستوں پر چلا دیں گے۔ اور اللہ تو نیکوکاروں کے ساتھ ہے۔', 'اور جنہوں نے محنت کی ہمارے واسطے ہم سجھا دیں گے ان کو اپنی راہیں [۱۰۴] اور بیشک اللہ ساتھ ہے نیکی والوں کے [۱۰۵]', 'As for those who strive hard in Us (Our Cause), We will surely guide them to Our Paths (i.e. Allahs Religion - Islamic Monotheism). And verily, Allah is with the Muhsinoon (good doers).\"', 'As for those who strive in Our way, We will certainly take them onto Our paths, and indeed Allah is with those who are good in deeds.'),
(3410, 30, 1, 1, 4, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'الٓـمّٓ  ۚ﴿۱﴾', 'الٓم۔', 'الٓم۔', 'AlifLamMeem. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings).', 'Alif, Lām , Mīm .'),
(3411, 30, 2, 1, 4, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'غُلِبَتِ  الرُّوۡمُ ۙ﴿۲﴾', 'اہل روم مغلوب ہو گئے۔', 'مغلوب ہو گئے ہیں رومی', 'The Romans have been defeated.', 'The Romans have been defeated'),
(3412, 30, 3, 1, 4, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'فِیۡۤ  اَدۡنَی الۡاَرۡضِ وَ ہُمۡ مِّنۡۢ  بَعۡدِ غَلَبِہِمۡ سَیَغۡلِبُوۡنَ ۙ﴿۳﴾', 'نزدیک کے ملک میں۔ اور وہ مغلوب ہونے کے بعد عنقریب غالب آ جائیں گے۔', 'ملتے ہوئے ملک میں [۱] اور وہ اس مغلوب ہونے کے بعد عنقریب غالب ہوں گے', 'In the nearer land (Syria, Iraq, Jordan, and Palestine), and they, after their defeat, will be victorious.', 'in the nearer land; and they, after their defeat, will triumph'),
(3413, 30, 4, 1, 4, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'فِیۡ بِضۡعِ سِنِیۡنَ ۬ؕ لِلّٰہِ الۡاَمۡرُ  مِنۡ قَبۡلُ وَ مِنۡۢ  بَعۡدُ ؕ وَ  یَوۡمَئِذٍ  یَّفۡرَحُ  الۡمُؤۡمِنُوۡنَ ۙ﴿۴﴾', 'چند ہی سال میں۔ پہلے بھی اور بعد میں بھی اللہ ہی کا حکم ہے اور اس روز مومن خوش ہو جائیں گے۔', 'چند برسوں میں [۲] اللہ کے ہاتھ ہیں سب کام پہلے اور پچھلے [۳] اور اس دن خوش ہوں گے مسلمان', 'Within three to nine years. The decision of the matter, before and after (these events) is only with Allah, (before the defeat of Romans by the Persians, and after, i.e. the defeat of the Persians by the Romans). And on that Day, the believers (i.e. Muslims) will rejoice (at the victory given by Allah to the Romans against the Persians),', 'within a few years. To Allah belonged the matter before and (to Him it belongs) thereafter. And on that day the believers will rejoice'),
(3414, 30, 5, 1, 4, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'بِنَصۡرِ اللّٰہِ ؕ یَنۡصُرُ مَنۡ یَّشَآءُ ؕ وَ ہُوَ الۡعَزِیۡزُ  الرَّحِیۡمُ ۙ﴿۵﴾', 'یعنی اللہ کی مدد سے۔ وہ جسے چاہتا ہے مدد دیتا ہے اور وہی تو غالب ہے بڑا مہربان ہے۔', 'اللہ کی مدد سے [۴] مدد کرتا ہے جس کی چاہتا ہے اور وہی ہے زبردست رحم والا [۵]', 'With the help of Allah, He helps whom He wills, and He is the AllMighty, the Most Merciful.', 'with Allah’s help. He helps whomsoever He wills. And He is the Mighty, the Very-Merciful.'),
(3415, 30, 6, 1, 4, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَعۡدَ اللّٰہِ ؕ لَا یُخۡلِفُ اللّٰہُ  وَعۡدَہٗ وَ لٰکِنَّ  اَکۡثَرَ  النَّاسِ لَا یَعۡلَمُوۡنَ ﴿۶﴾', 'یہ اللہ کا وعدہ ہے اللہ اپنے وعدے کے خلاف نہیں کرتا لیکن اکثر لوگ نہیں جانتے۔', 'اللہ کا وعدہ ہو چکا خلاف نہ کرے گا اللہ اپنا وعدہ لیکن بہت لوگ نہیں جانتے [۶]', '(It is) a Promise of Allah (i.e. Allah will give victory to the Romans against the Persians), and Allah fails not in His Promise, but most of men know not.', 'It is a promise from Allah. Allah does not fail in His promise, but most of the people do not know.'),
(3416, 30, 7, 1, 4, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'یَعۡلَمُوۡنَ ظَاہِرًا مِّنَ  الۡحَیٰوۃِ  الدُّنۡیَا ۚۖ وَ ہُمۡ عَنِ الۡاٰخِرَۃِ   ہُمۡ  غٰفِلُوۡنَ ﴿۷﴾', 'یہ لوگ دنیا کی ظاہری زندگی کو جانتے ہیں۔ اور آخرت کی طرف سے غافل ہیں۔', 'جانتے ہیں اوپر اوپر  دنیا کے جینے کو اور وہ  لوگ آخرت کی خبر نہیں رکھتے [۷]', 'They know only the outside appearance of the life of the world (i.e. the matters of their livelihood, like irrigating or sowing or reaping, etc.), and they are heedless of the Hereafter.', 'They know something superficial of the worldly life, but of the Hereafter they are negligent.'),
(3417, 30, 8, 1, 4, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'اَوَ لَمۡ  یَتَفَکَّرُوۡا فِیۡۤ   اَنۡفُسِہِمۡ ۟ مَا خَلَقَ اللّٰہُ  السَّمٰوٰتِ وَ الۡاَرۡضَ وَ مَا بَیۡنَہُمَاۤ  اِلَّا بِالۡحَقِّ وَ اَجَلٍ مُّسَمًّی ؕ وَ اِنَّ کَثِیۡرًا مِّنَ النَّاسِ بِلِقَآیِٔ رَبِّہِمۡ لَکٰفِرُوۡنَ ﴿۸﴾', 'کیا انہوں نے اپنے دل میں غور نہیں کیا۔ کہ اللہ نے آسمانوں اور زمین کو اور جو کچھ ان دونوں کے درمیان ہے انکو حکمت سے اور ایک وقت مقرر تک کے لئے پیدا کیا ہے۔ اور بہت سے لوگ اپنے پروردگار سے ملنے کے منکر ہیں۔', 'کیا دھیان نہیں کرتے اپنے جی میں کہ اللہ نے  جو بنائے آسمان اور زمین اور جو کچھ ان کے بیچ میں ہے سو ٹھیک سادہ کر اور  وعدہ مقرر پر [۸] اور بہت لوگ اپنے رب کا ملنا نہیں مانتے [۹]', 'Do they not think deeply (in their ownselves) about themselves (how Allah created them from nothing, and similarly He will resurrect them)? Allah has created not the heavens and the earth, and all that is between them, except with truth and for an appointed term. And indeed many of mankind deny the Meeting with their Lord. (See Tafsir AtTabaree, Part 21, Page 24).', 'Did they not reflect in their own selves? Allah did not create the heavens and the earth and what is between them but with a just cause and for an appointed time. Yet many of the people are disbelievers in the meeting with their Lord.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(3418, 30, 9, 1, 4, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'اَوَ لَمۡ  یَسِیۡرُوۡا فِی الۡاَرۡضِ فَیَنۡظُرُوۡا کَیۡفَ کَانَ عَاقِبَۃُ  الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ ؕ کَانُوۡۤا  اَشَدَّ مِنۡہُمۡ  قُوَّۃً  وَّ اَثَارُوا الۡاَرۡضَ وَ عَمَرُوۡہَاۤ  اَکۡثَرَ مِمَّا عَمَرُوۡہَا وَ جَآءَتۡہُمۡ  رُسُلُہُمۡ بِالۡبَیِّنٰتِ ؕ فَمَا کَانَ اللّٰہُ  لِیَظۡلِمَہُمۡ وَ لٰکِنۡ  کَانُوۡۤا  اَنۡفُسَہُمۡ  یَظۡلِمُوۡنَ ؕ﴿۹﴾', 'کیا ان لوگوں نے ملک میں سیر نہیں کی سیر کرتے تو دیکھ لیتے کہ جو لوگ ان سے پہلے تھے ان کا انجام کیسا ہوا۔ وہ ان سے زور و قوت میں کہیں زیادہ تھے اور انہوں نے زمین کو جوتا اور اسکو اس سے زیادہ آباد کیا تھا جو انہوں نے آباد کیا۔ اور انکے پاس ان کے پیغمبر نشانیاں لے کر آتے رہے۔ تو اللہ ایسا نہ تھا کہ ان پر ظلم کرتا بلکہ وہی اپنے آپ پر ظلم کرتے تھے۔', 'کیا انہوں نے سیر نہیں کی ملک کی جو دیکھیں انجام کیسا ہوا ان سے پہلوں کا ان سے زیادہ تھے زور میں اور جوتا انہوں نے زمین کو اور بسایا اس کو ان کے بسانے سے زیادہ اور پہنچے ان کے پاس رسول انکے لے کر کھلے حکم [۱۰] سو اللہ نہ تھا ان پر ظلم کرنے والا لیکن وہ اپنا آپ برا کرتے تھے [۱۱]', 'Do they not travel in the land, and see what was the end of those before them? They were superior to them in strength, and they tilled the earth and populated it in greater numbers than these (pagans) have done, and there came to them their Messengers with clear proofs. Surely, Allah wronged them not, but they used to wrong themselves.', 'Have they not traveled on earth to see how was the end of those before them? They were stronger than these in power, and they had tilled the land and had made it more populous than these have made it, and their messengers had come to them with clear proofs. So Allah was not such as could do injustice to them, but they used to do injustice to themselves.'),
(3419, 30, 10, 1, 4, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'ثُمَّ کَانَ عَاقِبَۃَ  الَّذِیۡنَ  اَسَآءُوا السُّوۡٓاٰۤی  اَنۡ  کَذَّبُوۡا بِاٰیٰتِ اللّٰہِ  وَ  کَانُوۡا بِہَا  یَسۡتَہۡزِءُوۡنَ  ﴿٪۱۰﴾', 'پھر جن لوگوں نے برائی کی ان کا انجام بھی برا ہوا اس لئے کہ وہ اللہ کی آیتوں کو جھٹلاتے اور ان کی ہنسی اڑاتے رہے تھے۔', 'پھر ہوا انجام برا کرنے والوں کا برا اس واسطے کہ جھٹلاتے تھے اللہ کی باتیں اور ان پر ٹھٹھے کرتے تھے [۱۲]', 'Then evil was the end of those who did evil, because they belied the Ayat (proofs, evidences, verses, lessons, signs, revelations, Messengers, etc.) of Allah and made mock of them.', 'Then the end of those who did evil was evil, because they rejected the verses of Allah and used to make mockery of them.'),
(3420, 30, 11, 2, 5, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'اَللّٰہُ  یَبۡدَؤُا  الۡخَلۡقَ ثُمَّ یُعِیۡدُہٗ  ثُمَّ  اِلَیۡہِ  تُرۡجَعُوۡنَ ﴿۱۱﴾', 'اللہ ہی خلقت کو پہلی بار پیدا کرتا ہے پھر وہی اسکو دوبارہ پیدا کرے گا پھر تم اسی کی طرف لوٹ کر جاؤ گے۔', 'اللہ بناتا ہے پہلی بار پھر اس کو دہرائے گا پھر اسی کی طرف جاؤ گے', 'Allah (Alone) originates the creation, then He will repeat it, then to Him you will be returned.', 'Allah originates the creation, then He will create it again, then to Him you are to be returned.'),
(3421, 30, 12, 2, 5, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ یَوۡمَ تَقُوۡمُ السَّاعَۃُ  یُبۡلِسُ الۡمُجۡرِمُوۡنَ ﴿۱۲﴾', 'اور جس دن قیامت برپا ہو گی گنہگار ناامید ہو جائیں گے۔', 'اور جس دن برپا ہو گی قیامت آس توڑ کر رہ جائیں گے گنہگار', 'And on the Day when the Hour will be established, the Mujrimoon (disbelievers, sinners, criminals, polytheists, etc.) will be plunged into destruction with deep regrets, sorrows, and despair.', 'On the day when the Hour (Qiyāmah : the Day of Judgement)) will take place, the guilty will be taken aback in grief and despair.'),
(3422, 30, 13, 2, 5, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ لَمۡ یَکُنۡ لَّہُمۡ مِّنۡ شُرَکَآئِہِمۡ شُفَعٰٓؤُا وَ کَانُوۡا بِشُرَکَآئِہِمۡ کٰفِرِیۡنَ ﴿۱۳﴾', 'اور انکے بنائے ہوئے شریکوں میں سے کوئی ان کا سفارشی نہ ہوگا اور وہ اپنے شریکوں سے منکر ہو جائیں گے۔', 'اور نہ ہوں گے ان کے شریکوں میں کوئی انکے سفارش کرنے والے اور وہ ہو جائیں گے اپنے شریکوں سے منکر [۱۳]', 'No intercessor will they have from those whom they made equal with Allah (partners i.e. their socalled associate gods), and they will (themselves) reject and deny their partners.', 'They will have no intercessors from among their (so-called) ‘partners of Allah’, and they themselves will reject their (such) ‘partners’.'),
(3423, 30, 14, 2, 5, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ یَوۡمَ تَقُوۡمُ السَّاعَۃُ  یَوۡمَئِذٍ یَّتَفَرَّقُوۡنَ ﴿۱۴﴾', 'اور جس دن قیامت برپا ہو گی اس روز وہ الگ الگ فرقے ہو جائیں گے۔', 'اور جس دن قائم ہو گی قیامت اس دن لوگ ہوں گے قسم قسم [۱۴]', 'And on the Day when the Hour will be established, that Day shall (all men) be separated (i.e the believers will be separated from the disbelievers).', 'And the day when the Hour (Qiyāmah : the Day of Judgement)) will take place-it will be on that day that they will turn into separate groups.'),
(3424, 30, 15, 2, 5, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'فَاَمَّا الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا  الصّٰلِحٰتِ فَہُمۡ  فِیۡ رَوۡضَۃٍ  یُّحۡبَرُوۡنَ ﴿۱۵﴾', 'تو جو لوگ ایمان لائے اور عمل نیک کرتے رہے وہ بہشت کے باغ میں خوشحال ہوں گے۔', 'سو جو لوگ یقین لائے اور کیے بھلے کام سو باغ میں ہوں گے  انکی آؤ بھگت ہو گی [۱۵]', 'Then as for those who believed (in the Oneness of Allah Islamic Monotheism) and did righteous good deeds, such shall be honoured and made to enjoy luxurious life (forever) in a Garden of delight (Paradise).', 'Then, those who had believed and had done righteous deeds-they will be in a garden, extremely delighted.'),
(3425, 30, 16, 2, 5, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ اَمَّا الَّذِیۡنَ کَفَرُوۡا وَ کَذَّبُوۡا بِاٰیٰتِنَا وَ لِقَآیِٔ الۡاٰخِرَۃِ  فَاُولٰٓئِکَ فِی الۡعَذَابِ مُحۡضَرُوۡنَ ﴿۱۶﴾', 'اور جنہوں نے کفر کیا اور ہماری آیتوں اور آخرت کی پیشی کو جھٹلایا۔ وہ عذاب  میں گرفتار کر کے لائے جائیں گے۔', 'اور جو منکر ہوئے اور جھٹلائیں ہماری باتیں اور ملنا پچھلے گھر کا سو  وہ عذاب میں پکڑے آئیں گے', 'And as for those who disbelieved and belied Our Ayat (proofs, evidences, verses, lessons, signs, revelations, Allahs Messengers, Resurrection, etc.), and the Meeting of the Hereafter, such shall be brought forth to the torment (in the Hell-fire).', 'As for those who had disbelieved and rejected Our verses and the meeting of the Hereafter, they will be brought for punishment.'),
(3426, 30, 17, 2, 5, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'فَسُبۡحٰنَ اللّٰہِ  حِیۡنَ تُمۡسُوۡنَ وَ حِیۡنَ تُصۡبِحُوۡنَ ﴿۱۷﴾', 'تو جس وقت شام ہو اور جس وقت صبح ہو اللہ کی تسبیح کرو یعنی نماز پڑھو۔', 'سو پاک اللہ کی یاد کرو جب شام کرو اور جب صبح کرو', 'So glorify Allah (above all that (evil) they associate with Him (O believers)), when you come up to the evening (i.e. offer the (Maghrib) sunset and (Isha) night prayers), and when you enter the morning (i.e offer the (Fajr) morning prayer).', 'So, proclaim Allah’s purity (from shirk) when you see the evening and when you see the morning.'),
(3427, 30, 18, 2, 5, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ لَہُ الۡحَمۡدُ فِی السَّمٰوٰتِ وَ الۡاَرۡضِ وَ عَشِیًّا وَّ  حِیۡنَ  تُظۡہِرُوۡنَ ﴿۱۸﴾', 'اور آسمانوں اور زمین میں اسی کی تعریف ہے۔ اور تیسرے پہر بھی اور جب دوپہر ہو اس وقت بھی نماز پڑھا کرو۔', 'اور اسی کی خوبی ہے آسمان میں اور زمین میں اور پچھلے وقت اور جب دوپہر ہو [۱۶]', 'And His is all the praises and thanks in the heavens and the earth, and (glorify Him) in the afternoon (i.e. offer Asr prayer) and when you come up to the time, when the day begins to decline (i.e offer Zuhr prayer). (Ibn Abbas said: \"These are the five compulsory congregational prayers mentioned in the Quran).\"', 'And to Him be praise in the heavens and the earth, and in the afternoon and when you enter the time of àuhr (soon after the decline of the sun towards West).'),
(3428, 30, 19, 2, 5, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'یُخۡرِجُ  الۡحَیَّ مِنَ الۡمَیِّتِ وَ یُخۡرِجُ الۡمَیِّتَ مِنَ الۡحَیِّ  وَ یُحۡیِ الۡاَرۡضَ بَعۡدَ مَوۡتِہَا ؕ وَ کَذٰلِکَ  تُخۡرَجُوۡنَ ﴿٪۱۹﴾', 'وہی زندہ کو مردے سے نکالتا ہے اور وہی مردے کو زندہ سے نکالتا ہے اور وہی زمین کو اسکے مرنے کے بعد زندہ کرتا ہے۔ اور اسی طرح تم دوبارہ زمین میں سے نکالے جاؤ گے۔', 'نکالتا ہے زندہ کو مردہ سے اور نکالتا ہے مردہ کو زندہ سے اور زندہ کرتا ہے زمین کو اس کے مرنے کے پیچھے اور اسی طرح تم نکالے جاؤ گے [۱۷]', 'He brings out the living from the dead, and brings out the dead from the living. And He revives the earth after its death. And thus shall you be brought out (resurrected).', 'He brings out the living from the dead, and brings out the dead from the living, and gives life to the land after it is dead. And in similar way you will be brought out (from graves).'),
(3429, 30, 20, 3, 6, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ مِنۡ اٰیٰتِہٖۤ  اَنۡ خَلَقَکُمۡ  مِّنۡ تُرَابٍ ثُمَّ اِذَاۤ   اَنۡتُمۡ  بَشَرٌ  تَنۡتَشِرُوۡنَ ﴿۲۰﴾', 'اور اسی کی نشانیوں میں سے ہے کہ اس نے تمہیں مٹی سے پیدا کیا۔ پھر اب تم انسان ہو کر جا بجا پھیل رہے ہو۔', 'اور اسکی نشانیوں میں سے ہے یہ کہ تم کو بنایا پھر اب تم انسان ہو زمین میں پھیلے پڑے [۱۸]', 'And among His Signs is this, that He created you (Adam) from dust, and then (Hawwa (Eve) from Adams rib, and then his offspring from the semen, and), - behold you are human beings scattered!', 'It is among His signs that He has created you from dust, then soon you are human beings scattered around.'),
(3430, 30, 21, 3, 6, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ مِنۡ اٰیٰتِہٖۤ  اَنۡ خَلَقَ لَکُمۡ مِّنۡ اَنۡفُسِکُمۡ اَزۡوَاجًا لِّتَسۡکُنُوۡۤا اِلَیۡہَا وَ جَعَلَ بَیۡنَکُمۡ  مَّوَدَّۃً  وَّ رَحۡمَۃً ؕ اِنَّ  فِیۡ ذٰلِکَ لَاٰیٰتٍ  لِّقَوۡمٍ  یَّتَفَکَّرُوۡنَ  ﴿۲۱﴾', 'اور اسی کی نشانیوں میں سے ہے کہ اس نے تمہارے لئے تمہاری ہی جنس کی عورتیں پیدا کیں تاکہ انکی طرف مائل ہو کر آرام حاصل کرو اور تم میں محبت اور مہربانی پیدا کر دی جو لوگ غور کرتے ہیں انکے لئے ان باتوں میں بہت سی نشانیاں ہیں۔', 'اور اسکی نشانیوں سے ہے یہ کہ بنا دیے تمہارے واسطے تمہاری قسم سے جوڑے کہ چین سے رہو  انکے پاس اور رکھا تمہارے بیچ میں پیار اور مہربانی البتہ اس میں بہت پتے کی باتیں ہیں انکے لئے جو دھیان کرتے ہیں [۱۹]', 'And among His Signs is this, that He created for you wives from among yourselves, that you may find repose in them, and He has put between you affection and mercy. Verily, in that are indeed signs for a people who reflect.', 'And it is among His signs that He has created for you wives from among yourselves, so that you may find tranquility in them, and He has created love and kindness between you. Surely in this there are signs for a people who reflect.'),
(3431, 30, 22, 3, 6, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ مِنۡ اٰیٰتِہٖ خَلۡقُ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ اخۡتِلَافُ اَلۡسِنَتِکُمۡ وَ اَلۡوَانِکُمۡ ؕ اِنَّ فِیۡ ذٰلِکَ  لَاٰیٰتٍ  لِّلۡعٰلِمِیۡنَ ﴿۲۲﴾', 'اور اسی کی نشانیوں میں سے ہے آسمانوں اور زمین کا پیدا کرنا اور تمہاری زبانوں اور رنگوں کا جدا جدا ہونا۔ اہل دانش کے لئے ان باتوں میں بہت سی نشانیاں ہیں۔', 'اور اسکی نشانیوں سے ہے آسمان اور زمین کا بنانا اور طرح طرح کی بولیاں تمہاری اور رنگ اس میں بہت نشانیاں ہیں سمجھنے والوں کو [۲۰]', 'And among His Signs is the creation of the heavens and the earth, and the difference of your languages and colours. Verily, in that are indeed signs for men of sound knowledge.', 'And among His signs is the creation of the heavens and the earth and the difference of your tongues and colors. Surely in this there are signs for the persons having knowledge.'),
(3432, 30, 23, 3, 6, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ مِنۡ اٰیٰتِہٖ مَنَامُکُمۡ بِالَّیۡلِ وَ النَّہَارِ وَ ابۡتِغَآؤُکُمۡ  مِّنۡ فَضۡلِہٖ ؕ اِنَّ فِیۡ  ذٰلِکَ لَاٰیٰتٍ لِّقَوۡمٍ  یَّسۡمَعُوۡنَ ﴿۲۳﴾', 'اور اسی کی نشانیوں میں سے ہے تمہارا رات اور دن میں سونا اور اسکے فضل کا تلاش کرنا۔ جو لوگ سنتے ہیں ان کے لئے ان باتوں میں بہت سی نشانیاں ہیں۔', 'اور اسکی نشانیوں سے  ہے تمہارا سونا رات اور دن میں اور تلاش کرنا اس کے فضل سے [۲۱] اس میں بہت پتے ہیں ان کو جو سنتے ہیں [۲۲]', 'And among His Signs is the sleep that you take by night and by day, and your seeking of His Bounty. Verily, in that are indeed signs for a people who listen.', 'And among His signs is your sleep by night and day, and your search for His grace. Surely in this there are signs for a people who listen.'),
(3433, 30, 24, 3, 6, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ مِنۡ  اٰیٰتِہٖ  یُرِیۡکُمُ الۡبَرۡقَ خَوۡفًا وَّ طَمَعًا وَّ  یُنَزِّلُ مِنَ السَّمَآءِ  مَآءً  فَیُحۡیٖ بِہِ الۡاَرۡضَ بَعۡدَ مَوۡتِہَا ؕ اِنَّ فِیۡ  ذٰلِکَ لَاٰیٰتٍ  لِّقَوۡمٍ  یَّعۡقِلُوۡنَ ﴿۲۴﴾', 'اور اسی کی نشانیوں میں سے ہے کہ وہ تمکو خوف اور امید دلانے کے لئے بجلی دکھاتا ہے اور آسمان سے بارش برساتا ہے۔ پھر زمین کو اسکے مر جانے کے بعد زندہ و شاداب کر دیتا ہے۔ عقل والوں کے لئے ان باتوں میں بہت سی نشانیاں ہیں۔', 'اور اسکی نشانیوں سے ہے یہ کہ دکھلاتا ہے تمکو بجلی ڈر اور امید کے لئے [۲۳] اور اتارتا ہے آسمان سے پانی پھر زندہ کرتا ہے اس سے زمین کر مر گئے پیچھے اس میں بہت پتے ہیں ان کے لئے جو سوچتے ہیں [۲۴]', 'And among His Signs is that He shows you the lightning, by way of fear and hope, and He sends down water (rain) from the sky, and therewith revives the earth after its death. Verily, in that are indeed signs for a people who understand.', 'And it is among His signs that He shows you the lightening which causes fear and hope, and that He sends down water from the sky, then He revives the earth with it after its death. Surely in this there are signs for a people who understand.'),
(3434, 30, 25, 3, 6, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ مِنۡ اٰیٰتِہٖۤ  اَنۡ  تَقُوۡمَ السَّمَآءُ وَ الۡاَرۡضُ بِاَمۡرِہٖ ؕ ثُمَّ  اِذَا دَعَاکُمۡ دَعۡوَۃً ٭ۖ مِّنَ  الۡاَرۡضِ ٭ۖ اِذَاۤ  اَنۡتُمۡ تَخۡرُجُوۡنَ ﴿۲۵﴾', 'اور اسی کی نشانیوں میں سے ہے کہ آسمان اور زمین اسکے حکم سے قائم ہیں۔ پھر جب وہ تمکو زمین میں سے نکلنے کے لئے آواز دے گا تو تم جھٹ نکل پڑو گے۔', 'اور اس کی نشانیوں سے یہ ہے کہ کھڑ ا ہے آسمان اور  زمین اس کے حکم سے [۲۵] پھر جب پکارے گا تم کو ایک بار زمین سے اسی وقت تم نکل پڑو گے [۲۶]', 'And among His Signs is that the heaven and the earth stand by His Command, then afterwards when He will call you by single call, behold, you will come out from the earth (i.e from your graves for reckoning and recompense).', 'And it is among His signs that the sky and the earth stand firm by His command. Then, when He will call you from the earth, by a single call, you will be coming out all at once.'),
(3435, 30, 26, 3, 6, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ لَہٗ مَنۡ فِی  السَّمٰوٰتِ  وَ الۡاَرۡضِ ؕ کُلٌّ لَّہٗ   قٰنِتُوۡنَ ﴿۲۶﴾', 'اور آسما نوں اور زمین میں جتنے فرشتے اور انسان وغیرہ ہیں اسی کے مملوک ہیں اور تمام اسکے فرمانبردار ہیں۔', 'اور اسی کا ہے جو کوئی ہے آسمان اور زمین میں سب اس کے حکم کے تابع ہیں [۲۷]', 'To Him belongs whatever is in the heavens and the earth. All are obedient to Him.', 'To Him belong all those in the heavens and the earth. All (of them) are obedient to Him.'),
(3436, 30, 27, 3, 6, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ ہُوَ الَّذِیۡ  یَبۡدَؤُا  الۡخَلۡقَ ثُمَّ  یُعِیۡدُہٗ وَ ہُوَ اَہۡوَنُ عَلَیۡہِ ؕ وَ لَہُ  الۡمَثَلُ  الۡاَعۡلٰی فِی السَّمٰوٰتِ وَ الۡاَرۡضِ ۚ وَ ہُوَ الۡعَزِیۡزُ الۡحَکِیۡمُ ﴿٪۲۷﴾', 'اور وہی تو ہے جو خلقت کو پہلی دفعہ پیدا کرتا ہے پھر اسے دوبارہ پیدا کرے گا۔ اور یہ اسکو بہت آسان ہے۔ اور آسمانوں اور زمین میں اسکی شان نہایت بلند ہے۔ اور وہ غالب ہے حکمت والا ہے۔', 'اور وہی ہے جو  پہلی بار بناتا ہے پھر اس کو دھرائے گا اور  وہ آسان ہے اس پر [۲۸] اور اسکی شان سب سے اوپر ہے آسمان اور  زمین میں اور وہی ہے زبردست حکمتوں والا [۲۹]', 'And He it is Who originates the creation, then will repeat it (after it has been perished), and this is easier for Him. His is the highest description (i.e. none has the right to be worshipped but He, and there is nothing comparable unto Him) in the heavens and in the earth. And He is the AllMighty, the AllWise.', 'It is He who originates the creation, then will create it again; and it is easier for Him. His is the highest description in the heavens and the earth, and He is the Mighty, the Wise.'),
(3437, 30, 28, 4, 7, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'ضَرَبَ لَکُمۡ مَّثَلًا مِّنۡ اَنۡفُسِکُمۡ ؕ ہَلۡ لَّکُمۡ  مِّنۡ مَّا مَلَکَتۡ  اَیۡمَانُکُمۡ مِّنۡ شُرَکَآءَ  فِیۡ مَا رَزَقۡنٰکُمۡ فَاَنۡتُمۡ فِیۡہِ سَوَآءٌ  تَخَافُوۡنَہُمۡ کَخِیۡفَتِکُمۡ اَنۡفُسَکُمۡ ؕ کَذٰلِکَ نُفَصِّلُ  الۡاٰیٰتِ  لِقَوۡمٍ  یَّعۡقِلُوۡنَ ﴿۲۸﴾', 'وہ تمہارے لئے تمہارے ہی حال کی ایک مثال بیان فرماتا ہے کہ بھلا جن غلاموں کے تم مالک ہو وہ اس مال میں جو ہم نے تمکو عطا فرمایا ہے تمہارے شریک ہیں؟ اور کیا تم اس میں انکو اپنے برابر مالک سمجھتے ہو اور کیا تم ان سے اس طرح ڈرتے ہو جس طرح اپنوں سے ڈرتے ہو؟ اس طرح ہم عقل والوں کے لئے اپنی آیتیں کھول کھول کر بیان کرتے ہیں۔', 'بتلائی تم کو ایک مثل تمہارے اندر  سے دیکھو جو تمہارے ہاتھ کے مال ہیں ان میں ہیں کوئی ساجھی تمہارے ہماری دی ہوئی روزی میں کہ تم سب اس میں برابر رہو  خطر رکھو ان کا جیسے خطرہ رکھو اپنوں کا یوں کھول کر بیان کرتے ہیں ہم نشانیاں ان  لوگوں کے لئے جو سمجھتے ہیں [۳۰]', 'He sets forth for you a parable from your ownselves, - Do you have partners among those whom your right hands possess (i.e your slaves) to share as equals in the wealth We have bestowed on you? Whom you fear as you fear each other? Thus do We explain the signs in detail to a people who have sense .', 'He (Allah) gives you an example from yourselves: Do you have, from among your slaves, any partners in the wealth that We have given to you, so as they and you are equal in it, (and) so as you fear them like you fear each other? This is how We explain the signs for a people who understand.'),
(3438, 30, 29, 4, 7, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'بَلِ  اتَّبَعَ  الَّذِیۡنَ ظَلَمُوۡۤا اَہۡوَآءَہُمۡ بِغَیۡرِ  عِلۡمٍ ۚ فَمَنۡ  یَّہۡدِیۡ مَنۡ  اَضَلَّ  اللّٰہُ ؕ وَ  مَا لَہُمۡ  مِّنۡ  نّٰصِرِیۡنَ  ﴿۲۹﴾', 'مگر جو ظالم ہیں وہ بے سمجھے اپنی خواہشوں کے پیچھے چلتے ہیں تو جسکو اللہ گمراہ رہنے دے اسے کون ہدایت دے سکتا ہے؟ اور ان کا کوئی مددگار نہیں۔', 'بلکہ چلتے ہیں یہ بے انصاف اپنی خواہشوں پر بن سمجھے [۳۱] سو کون سمجھائے جس کو  اللہ نے بھٹکایا اور کوئی نہیں ان کا مددگار [۳۲]', 'Nay, but those who do wrong follow their own lusts without knowledge, Then who will guide him whom Allah has sent astray? And for such there will be no helpers.', 'But the wrongdoers have followed their desires without knowledge. So who can guide the one whom Allah leaves astray? For such people there are no helpers.'),
(3439, 30, 30, 4, 7, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'فَاَقِمۡ  وَجۡہَکَ لِلدِّیۡنِ حَنِیۡفًا ؕ فِطۡرَتَ اللّٰہِ  الَّتِیۡ فَطَرَ  النَّاسَ عَلَیۡہَا ؕ لَا تَبۡدِیۡلَ  لِخَلۡقِ اللّٰہِ ؕ ذٰلِکَ الدِّیۡنُ الۡقَیِّمُ ٭ۙ وَ لٰکِنَّ  اَکۡثَرَ النَّاسِ لَا یَعۡلَمُوۡنَ ﴿٭ۙ۳۰﴾', 'سو تو تم ایک طرف کے ہو کر دین الٰہی پر سیدھا رخ کئے چلتے رہو اور اللہ کی فطرت کو جس پر اس نے لوگوں کو پیدا کیا ہے اختیار کئے رہو اللہ کی بنائی ہوئی فطرت میں تغیروتبدل نہیں ہو سکتا۔ یہی سیدھا دین ہے لیکن اکثر لوگ نہیں جانتے۔', 'سو تو سیدھا رکھ اپنا منہ دین  پر ایک طرف کا ہو کر [۳۳] وہی تراش اللہ کی جس پر تراشا لوگوں کو [۳۴] بدلنا نہیں اللہ کے بنائے کو [۳۵] یہی ہے دین سیدھا و لیکن اکثر لوگ نہیں سمجھتے [۳۶]', 'So set you (O Muhammad SAW) your face towards the religion of pure Islamic Monotheism Hanifa (worship none but Allah Alone) Allahs Fitrah (i.e. Allahs Islamic Monotheism), with which He has created mankind. No change let there be in Khalqillah (i.e. the Religion of Allah Islamic Monotheism), that is the straight religion, but most of men know not. (Tafsir AtTabaree, Vol 21, Page 41)', 'So, set your face to the Faith uprightly, this (faith) being the nature designed by Allah on which He has created the mankind. There is no change in Allah’s creation. That is the straight faith, but most of the people do not know.'),
(3440, 30, 31, 4, 7, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'مُنِیۡبِیۡنَ اِلَیۡہِ وَ اتَّقُوۡہُ  وَ اَقِیۡمُوا الصَّلٰوۃَ  وَ لَا تَکُوۡنُوۡا مِنَ الۡمُشۡرِکِیۡنَ ﴿ۙ۳۱﴾', 'مومنو اسی اللہ کی طرف رجوع کئے رہو اور اس سے ڈرتے رہو اور نماز قائم کرتے رہو اور مشرکوں میں نہ ہونا۔', 'سب رجوع ہو کر اسکی طرف [۳۷] اور اس سے ڈرتے رہو اور قائم رکھو نماز اور مت ہو شرک کرنے والوں میں', '(Always) Turning in repentance to Him (only), and be afraid and dutiful to Him; and perform AsSalat (IqamatasSalat) and be not of AlMushrikoon (the disbelievers in the Oneness of Allah, polytheists, idolaters, etc.).', '(Set your face to the Faith) turning totally towards Him, and fear Him, and establish Salāh, and do not be among those who associate partners with Allah'),
(3441, 30, 32, 4, 7, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'مِنَ الَّذِیۡنَ فَرَّقُوۡا دِیۡنَہُمۡ  وَ کَانُوۡا شِیَعًا ؕ کُلُّ  حِزۡبٍۭ بِمَا لَدَیۡہِمۡ فَرِحُوۡنَ ﴿۳۲﴾', 'اور نہ ان لوگوں میں ہونا جنہوں نے اپنے دین کو ٹکڑے ٹکڑے کر دیا اور خود  بھی فرقے فرقے ہو گئے۔ ہر فرقہ اسی میں مگن ہے جو اسکے پاس ہے۔', 'جنہوں نے کہ پھوٹ ڈالی اپنے دین میں اور ہو گئے ان میں بہت فرقے ہر فرقہ جو اس کے پاس ہے اس پر فریفتہ ہے [۳۸]', 'Of those who split up their religion (i.e. who left the true Islamic Monotheism), and became sects, (i.e. they invented new things in the religion (Bidah), and followed their vain desires), each sect rejoicing in that which is with it.', '- among those who split up their religion and became sects. Each group is happy with what it has before it.'),
(3442, 30, 33, 4, 7, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ اِذَا مَسَّ النَّاسَ ضُرٌّ دَعَوۡا رَبَّہُمۡ مُّنِیۡبِیۡنَ  اِلَیۡہِ ثُمَّ   اِذَاۤ   اَذَاقَہُمۡ  مِّنۡہُ رَحۡمَۃً اِذَا فَرِیۡقٌ مِّنۡہُمۡ بِرَبِّہِمۡ یُشۡرِکُوۡنَ ﴿ۙ۳۳﴾', 'اور جب لوگوں کو تکلیف پہنچتی ہے تو اپنے پروردگار کو پکارتے ہیں اسی کی طرف رجوع کرتے ہوئے پھر جب وہ انکو اپنی رحمت کا مزہ چکھاتا ہے تو ایک فریق ان میں سے اپنے پروردگار کیساتھ شرک کرنے لگتا ہے۔', 'اور جب پہنچے لوگوں کو کچھ سختی تو پکاریں اپنے رب کو اس کی طرف رجوع ہو کر پھر جہاں چکھائی ان کو اپنی طرف سے کچھ مہربانی اسی وقت ایک جماعت ان میں اپنے رب کا شریک لگی بتانے', 'And when harm touches men, they cry sincerely only to their Lord (Allah), turning to Him in repentance, but when He gives them a taste of His Mercy, behold! a party of them associate partners in worship with their Lord.', 'When the people are visited by some affliction, they invoke their Lord with exclusive concentration on Him. Then once He gives them a taste of His mercy, a group of them starts at once ascribing partners to their Lord,'),
(3443, 30, 34, 4, 7, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'لِیَکۡفُرُوۡا بِمَاۤ  اٰتَیۡنٰہُمۡ ؕ فَتَمَتَّعُوۡا ٝ فَسَوۡفَ تَعۡلَمُوۡنَ ﴿۳۴﴾', 'تاکہ جو ہم نے انکو بخشا ہے اسکی ناشکری کریں سو خیر فائدے اٹھا لو عنقریب تمکو اس کا انجام معلوم ہو جائے گا۔', 'کہ منکر ہوجائیں ہمارے دیے ہوئے سے سو مزے اڑا لو اب آگے جان لو گے [۳۹]', 'So as to be ungrateful for the graces which We have bestowed on them. Then enjoy (your short life); but you will come to know.', 'so as to become ungrateful for what We gave to them. So enjoy yourselves awhile; then you will soon come to know.'),
(3444, 30, 35, 4, 7, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'اَمۡ  اَنۡزَلۡنَا عَلَیۡہِمۡ سُلۡطٰنًا فَہُوَ یَتَکَلَّمُ  بِمَا  کَانُوۡا بِہٖ  یُشۡرِکُوۡنَ ﴿۳۵﴾', 'کیا ہم نے ان پر کوئی ایسی دلیل نازل کی ہے کہ پھر وہ انکو اللہ کے ساتھ شرک کرنا بتاتی ہے۔', 'کیا ہم نے  ان پر اتاری ہے کوئی سند سو وہ بول رہی ہے جو یہ شریک بتاتے ہیں [۴۰]', 'Or have We revealed to them a Scripture, which speaks of that which they have been associating with Him?', 'Is it that We have sent down to them any authority that speaks to them about their associating partners with Him?'),
(3445, 30, 36, 4, 7, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ اِذَاۤ  اَذَقۡنَا النَّاسَ رَحۡمَۃً  فَرِحُوۡا بِہَا ؕ  وَ  اِنۡ  تُصِبۡہُمۡ سَیِّئَۃٌۢ  بِمَا قَدَّمَتۡ  اَیۡدِیۡہِمۡ   اِذَا  ہُمۡ  یَقۡنَطُوۡنَ ﴿۳۶﴾', 'اور جب ہم لوگوں کو اپنی رحمت کا مزہ چکھاتے ہیں تو وہ اس سے خوش ہو جاتے ہیں۔ اور اگر انکے اعمال کے سبب جو انکے ہاتھوں نے آگے بھیجے ہیں انہیں کوئی تکلیف پہنچے تو ناامید ہو کر رہ جاتے ہیں۔', 'اور جب چکھائیں ہم لوگوں کو کچھ مہربانی اس پر پھولے نہیں سماتے اور اگر آ پڑے ان پر کچھ برائی اپنے ہاتھوں کے بھیجے ہوئے پر تو آس توڑ بیٹھیں [۴۱]', 'And when We cause mankind to taste of mercy, they rejoice therein, but when some evil afflicts them because of (evil deeds and sins) that their (own) hands have sent forth, lo! They are in despair!', 'When We give people a taste of mercy, they are happy with it, and if they are touched by an evil because of what their hands sent ahead, they are at once in despair.'),
(3446, 30, 37, 4, 7, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'اَوَ لَمۡ  یَرَوۡا  اَنَّ اللّٰہَ  یَبۡسُطُ الرِّزۡقَ  لِمَنۡ یَّشَآءُ  وَ یَقۡدِرُ ؕ اِنَّ  فِیۡ  ذٰلِکَ لَاٰیٰتٍ لِّقَوۡمٍ  یُّؤۡمِنُوۡنَ ﴿۳۷﴾', 'کیا انہوں نے نہیں دیکھا کہ اللہ ہی جسکے لئے چاہتا ہے رزق فراخ کرتا ہے اور جسکے لئے چاہتا ہے تنگ کرتا ہے۔ بیشک اس میں ایمان لانے والوں کے لئے نشانیاں ہیں۔', 'کیا نہیں دیکھ چکے کہ اللہ پھیلا دیتا ہے روزی کو جس پر چاہے اور ماپ کر دیتا ہے جسکو چاہے اس میں نشانیاں ہیں ان لوگوں کو جو یقین رکھتے ہیں [۴۲]', 'Do they not see that Allah enlarges the provision for whom He wills and straitens (it for whom He wills). Verily, in that are indeed signs for a people who believe.', 'Did they not see that Allah extends provision to whomsoever He wills, and straitens (it for whomsoever He wills)? Surely in this there are signs for a people who believe.'),
(3447, 30, 38, 4, 7, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'فَاٰتِ ذَاالۡقُرۡبٰی حَقَّہٗ  وَ الۡمِسۡکِیۡنَ وَ ابۡنَ‌السَّبِیۡلِ ؕ ذٰلِکَ خَیۡرٌ لِّلَّذِیۡنَ یُرِیۡدُوۡنَ وَجۡہَ اللّٰہِ ۫ وَ اُولٰٓئِکَ ہُمُ الۡمُفۡلِحُوۡنَ ﴿۳۸﴾', 'تو اہل قرابت اور محتاجوں اور مسافروں کو ان کا حق دیتے رہو۔ جو لوگ اللہ کی رضا کے طالب ہیں یہ انکے حق میں بہتر ہے۔ اور یہی لوگ کامیابی حاصل کرنے والے ہیں۔', 'سو تو دے قرابت  والے کو  اس کا حق اور محتاج کو اور مسافر کو یہ بہتر ہے ان کے لئے جو چاہتے ہیں اللہ کا منہ اور وہی ہیں جن کا بھلا ہے [۴۳]', 'So give to the kindred his due, and to AlMiskeen (the poor) and to the wayfarer. That is best for those who seek Allahs Countenance, and it is they who will be successful.', 'So give to the kinsman his right, and to the needy and the wayfarer. That is better for those who seek Allah’s pleasure, and it is they who will be successful.'),
(3448, 30, 39, 4, 7, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ مَاۤ  اٰتَیۡتُمۡ مِّنۡ رِّبًا لِّیَرۡبُوَا۠ فِیۡۤ  اَمۡوَالِ النَّاسِ فَلَا یَرۡبُوۡا عِنۡدَ اللّٰہِ ۚ وَ مَاۤ  اٰتَیۡتُمۡ  مِّنۡ زَکٰوۃٍ  تُرِیۡدُوۡنَ وَجۡہَ اللّٰہِ فَاُولٰٓئِکَ  ہُمُ  الۡمُضۡعِفُوۡنَ ﴿۳۹﴾', 'اور جو سود تم دیتے ہو کہ وہ لوگوں کے مال میں بڑھے تو اللہ کے نزدیک تو وہ بڑھتا بھی نہیں اور جو تم زکوٰۃ دیتے ہو اللہ کی رضامندی طلب کرتے ہوئے تو وہ موجب برکت ہے اور ایسے ہی لوگ اپنے مال کو کئ گنا کرنے والے ہیں۔', 'اور جو دیتے ہو بیاج پر کہ بڑھتا رہے لوگوں کے مال میں سو وہ نہیں بڑھتا اللہ کے یہاں اور جو دیتے ہو  پاک دل سے چاہ کر رضامندی اللہ کی سو یہ وہی ہیں جن کے دونے ہوئے [۴۴]', 'And that which you give in gift (to others), in order that it may increase (your wealth by expecting to get a better one in return) from other peoples property, has no increase with Allah, but that which you give in Zakat seeking Allahs Countenance then those, they shall have manifold increase.', 'Whatever Ribā (increased amount) you give, so that it may increase in the wealth of the people, it does not increase with Allah; and whatever Zakāh you give, seeking Allah’s pleasure with it, (it is multiplied by Allah, and) it is such people who multiply (their wealth in real terms.)'),
(3449, 30, 40, 4, 7, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'اَللّٰہُ  الَّذِیۡ خَلَقَکُمۡ ثُمَّ  رَزَقَکُمۡ ثُمَّ یُمِیۡتُکُمۡ ثُمَّ یُحۡیِیۡکُمۡ ؕ ہَلۡ مِنۡ شُرَکَآئِکُمۡ  مَّنۡ یَّفۡعَلُ مِنۡ ذٰلِکُمۡ  مِّنۡ شَیۡءٍ ؕ سُبۡحٰنَہٗ  وَ تَعٰلٰی عَمَّا یُشۡرِکُوۡنَ ﴿٪۴۰﴾', 'اللہ ہی تو ہے جس نے تمکو پیدا کیا پھر اس نے تمکو رزق دیا پھر وہ تمہیں موت دے گا۔ پھر زندہ کرے گا۔ بھلا تمہارے بنائے ہوئے شریکوں میں بھی کوئی ایسا ہے جو ان کاموں میں سے کچھ کر سکے۔ وہ پاک ہے اور اسکی شان انکے شریکوں سے بلند ہے۔', 'اللہ وہ ہی ہے جس نے تم کو بنایا پھر تم کو روزی دی پھر تم کو مارتا ہے پھر تم کو جلائے گا کوئی ہے تمہارے شریکوں میں جو کر سکے ان کاموں میں سے ایک کام وہ نرالا ہے اور بہت اوپر ہے اس سے کہ شریک بتلاتے ہیں [۴۵]', 'Allah is He Who created you, then provided food for you, then will cause you to die, then (again) He will give you life (on the Day of Resurrection). Is there any of your (socalled) partners (of Allah) that do anything of that ? Glory be to Him! And Exalted be He above all that (evil) they associate (with Him).', 'Allah is the One who created you, then gave sustenance to you, then He will make you dead, then He will make you alive. Is there any one from your (so-called) ‘partners of God’ who can do anything of that (kind)? Pure is He, and far higher than what they associate (with Him).'),
(3450, 30, 41, 5, 8, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'ظَہَرَ الۡفَسَادُ فِی الۡبَرِّ وَ الۡبَحۡرِ بِمَا کَسَبَتۡ اَیۡدِی  النَّاسِ  لِیُذِیۡقَہُمۡ بَعۡضَ الَّذِیۡ عَمِلُوۡا  لَعَلَّہُمۡ یَرۡجِعُوۡنَ ﴿۴۱﴾', 'خشکی اور تری میں لوگوں کے اعمال کے سبب فساد پھیل گیا ہے تاکہ اللہ انکو ان کے بعض اعمال کا مزہ چکھائے عجب نہیں کہ وہ باز آ جائیں۔', 'پھیل پڑی ہے خرابی جنگل میں اور دریا میں لوگوں کے ہاتھ کی کمائی سے چکھانا چاہیے ان کو کچھ مزہ ان کے کام کا تاکہ وہ پھر آئیں [۴۶]', 'Evil (sins and disobedience of Allah, etc.) has appeared on land and sea because of what the hands of men have earned (by oppression and evil deeds, etc.), that Allah may make them taste a part of that which they have done, in order that they may return (by repenting to Allah, and begging His Pardon).', 'Calamities have appeared on land and sea because of what the hands of the people have earned, so that He (Allah) makes them taste some of what they did, in order that they may return (to the right way).'),
(3451, 30, 42, 5, 8, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'قُلۡ سِیۡرُوۡا فِی الۡاَرۡضِ فَانۡظُرُوۡا کَیۡفَ کَانَ عَاقِبَۃُ  الَّذِیۡنَ مِنۡ قَبۡلُ ؕ کَانَ اَکۡثَرُہُمۡ  مُّشۡرِکِیۡنَ ﴿۴۲﴾', 'کہدو کہ ملک میں چلو پھرو اور دیکھو کہ جو لوگ تم سے پہلے تھے ان کا کیسا انجام ہوا ہے۔ ان میں زیادہ تر مشرک ہی تھے۔', 'تو کہہ پھرو ملک میں تو دیکھو کیسا ہوا انجام پہلوں کا بہت ان میں تھے شرک کرنے والے [۴۷]', 'Say (O Muhammad SAW): \"Travel in the land and see what was the end of those before (you)! Most of them were Mushrikoon (the disbelievers in the Oneness of Allah, polytheists, idolaters, etc.).\"', 'Say, “Go about in the land, and see how was the end of those who were before. Most of them were Mushriks (i.e. those who ascribe partners to Allah)”.'),
(3452, 30, 43, 5, 8, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'فَاَقِمۡ وَجۡہَکَ لِلدِّیۡنِ الۡقَیِّمِ مِنۡ قَبۡلِ اَنۡ یَّاۡتِیَ یَوۡمٌ  لَّا  مَرَدَّ لَہٗ مِنَ اللّٰہِ یَوۡمَئِذٍ  یَّصَّدَّعُوۡنَ ﴿۴۳﴾', 'تو اس روز سے پہلے جو اللہ کی طرف سے آ کر رہے گا اور رک نہیں سکے گا سیدھے دین کے رستے پر سیدھا رخ کئے چلتے رہو کہ اس روز سب لوگ منتشر ہو جائیں گے۔', 'سو تو سیدھا رکھ اپنا منہ سیدھی ر اہ پر [۴۸] اس سے پہلے کہ آ پہنچے وہ دن جس کو پھرنا نہیں اللہ کی طرف سے [۴۹] اس دن لوگ جدا جدا ہوں گے [۵۰]', 'So set you (O Muhammad SAW) your face to (the obedience of Allah, your Lord) the straight and right religion (Islamic Monotheism), before there comes from Allah a Day which none can avert it. On that Day men shall be divided ((in two groups), a group in Paradise and a group in Hell).', 'Then set your face to the straight Faith before the arrival of a day that will never be repulsed by Allah. On that Day the people will be split apart.'),
(3453, 30, 44, 5, 8, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'مَنۡ کَفَرَ فَعَلَیۡہِ کُفۡرُہٗ ۚ وَ مَنۡ عَمِلَ صَالِحًا  فَلِاَنۡفُسِہِمۡ  یَمۡہَدُوۡنَ ﴿ۙ۴۴﴾', 'جس شخص نے کفر کیا تو اسکے کفر کا ضرر اسی کو ہے اور جس نے نیک عمل کئے تو ایسے لوگ اپنے ہی لئے آرام گاہ درست کرتے ہیں۔', 'جو منکر ہوا سو  اس پر  پڑے اسکا منکر ہونا [۵۱] او رجو کوئی کرے بھلے کام سو وہ اپنی راہ سنوارتے ہیں [۵۲]', 'Whosoever disbelieves will suffer from his disbelief, and whosoever does righteous good deeds (by practising Islamic Monotheism), then such will prepare a good place (in Paradise) for themselves (and will be saved by Allah from His Torment).', 'Whoever disbelieves, his unbelief will be against him; and whoever acts righteously, then such people are paving the path for themselves,'),
(3454, 30, 45, 5, 8, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'لِیَجۡزِیَ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ مِنۡ فَضۡلِہٖ ؕ  اِنَّہٗ  لَا یُحِبُّ الۡکٰفِرِیۡنَ ﴿۴۵﴾', 'تاکہ جو لوگ ایمان لائے اور نیک عمل کرتے رہے انکو اللہ اپنے فضل سے بدلہ دے بیشک وہ کافروں کو دوست نہیں رکھتا۔', 'تاکہ وہ بدلہ دے ان کو جو یقین لائے اور کام کئے بھلے اپنے فضل سے [۵۳] بیشک اس کو نہیں بھاتے انکار  والے [۵۴]', 'That He may reward those who believe (in the Oneness of Allah Islamic Monotheism), and do righteous good deeds, out of His Bounty. Verily, He likes not the disbelievers.', 'so that Allah may give reward, out of His grace, to those who believed and did righteous deeds. Surely He does not love the unbelievers.'),
(3455, 30, 46, 5, 8, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ مِنۡ اٰیٰتِہٖۤ  اَنۡ یُّرۡسِلَ الرِّیَاحَ مُبَشِّرٰتٍ وَّ  لِیُذِیۡقَکُمۡ  مِّنۡ  رَّحۡمَتِہٖ  وَ لِتَجۡرِیَ الۡفُلۡکُ بِاَمۡرِہٖ  وَ لِتَبۡتَغُوۡا مِنۡ فَضۡلِہٖ وَ لَعَلَّکُمۡ  تَشۡکُرُوۡنَ ﴿۴۶﴾', 'اور اسی کی نشانیوں میں سے ہے کہ وہ ہواؤں کو بھیجتا ہے کہ خوشخبری دیتی ہیں تاکہ تمکو اپنی رحمت کے مزے چکھائے اور تاکہ اسکے حکم سے کشتیاں چلیں اور تاکہ تم اسکے فضل سے روزی طلب کرو اور تاکہ تم شکر کرو۔', 'اور اس کی نشانیوں میں ایک یہ ہے کہ چلاتا ہے ہوائیں خوشخبری لانے والیاں اور تاکہ چکھائے تمکو کچھ مزہ اپنی مہربانی کا [۵۵] اور تاکہ چلیں جہاز  اسکے حکم سے [۵۶] اور تاکہ تلاش کرو اس کے فضل سے اور تاکہ تم حق مانو [۵۷]', 'And among His Signs is this, that He sends the winds as glad tidings, giving you a taste of His Mercy (i.e. rain), and that the ships may sail at His Command, and that you may seek of His Bounty, in order that you may be thankful.', 'And among His signs is that He sends winds giving good news (of rain), and so that He gives you a taste of His mercy, and that the ships may sail with His command, and that you may search for His grace, and you may be grateful.'),
(3456, 30, 47, 5, 8, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ لَقَدۡ  اَرۡسَلۡنَا مِنۡ قَبۡلِکَ رُسُلًا  اِلٰی قَوۡمِہِمۡ فَجَآءُوۡہُمۡ  بِالۡبَیِّنٰتِ فَانۡتَقَمۡنَا مِنَ الَّذِیۡنَ اَجۡرَمُوۡا ؕ وَ کَانَ حَقًّا عَلَیۡنَا  نَصۡرُ  الۡمُؤۡمِنِیۡنَ ﴿۴۷﴾', 'اور ہم نے تم سے پہلے بھی پیغمبر بھیجے تو وہ ان کے پاس نشانیاں لے کر آئے سو جو لوگ نافرمانی کرتے تھے ہم نے ان سے بدلہ لے کر چھوڑا اور مومنوں کی مدد ہم پر لازم تھی۔', 'اور ہم بھیج چکے ہیں تجھ سے  پہلے کتنے رسول اپنی اپنی قوم کے پاس سو پہنچے انکے پاس نشانیاں لے کر پھر بدلہ لیا ہم نے ان سے جو گنہگار تھے اور حق ہے ہم پر مدد ایمان والوں کی [۵۸]', 'And indeed We did send Messengers before you (O Muhammad SAW) to their own peoples. They came to them with clear proofs, then, We took vengeance on those who committed crimes (disbelief, setting partners in worship with Allah, sins, etc.), and (as for) the believers it was incumbent upon Us to help (them).', 'We had indeed sent before you messengers to their people. So they came to them with clear proofs. Then We took vengeance upon those who were guilty; and it was due on Us to help the believers.'),
(3457, 30, 48, 5, 8, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'اَللّٰہُ  الَّذِیۡ یُرۡسِلُ الرِّیٰحَ فَتُثِیۡرُ  سَحَابًا فَیَبۡسُطُہٗ فِی السَّمَآءِ کَیۡفَ یَشَآءُ وَ یَجۡعَلُہٗ کِسَفًا فَتَرَی الۡوَدۡقَ یَخۡرُجُ مِنۡ خِلٰلِہٖ ۚ فَاِذَاۤ  اَصَابَ بِہٖ مَنۡ یَّشَآءُ مِنۡ عِبَادِہٖۤ   اِذَا  ہُمۡ  یَسۡتَبۡشِرُوۡنَ ﴿ۚ۴۸﴾', 'اللہ ہی تو ہے جو ہواؤں کو بھیجتا ہے تو وہ بادل کو ابھارتی ہیں۔ پھر اللہ اسکو جس طرح چاہتا ہے آسمان میں پھیلا دیتا اور تہ بہ تہ کر دیتا ہے پھر تم دیکھتے ہو کہ اسکے بیچ میں سے بارش کی بوندیں نکلنے لگتی ہیں پھر جب وہ اپنے بندوں میں سے جن پر چاہتا ہے اسے برسا دیتا ہے تو اسی وقت وہ خوش ہو جاتے ہیں۔', 'اللہ ہے جو چلاتا ہے ہوائیں پھر  وہ اٹھاتی ہیں بادل کو پھر پھیلا دیتا ہے اس کو آسمان میں جس طرح چاہے [۵۹] اور رکھتا ہے اس کو تہہ بہ تہہ پھر تو  دیکھے مینہ کو کہ نکلتا ہے اس کے بیچ میں سے پھر جب اس کو پہنچاتا ہے جس کو کہ چاہتا ہے اپنے بندوں میں تبھی وہ لگتے ہیں خوشیاں کرنے [۶۰]', 'Allah is He Who sends the winds, so they raise clouds, and spread them along the sky as He wills, and then break them into fragments, until you see rain drops come forth from their midst! Then when He has made them fall on whom of His slaves as He will, lo! they rejoice!', 'Allah is the One who sends the winds, so they stir up a cloud, then He spreads it in the sky however he wills, and makes it (split) into pieces. Then you see the rain coming out from its midst. So, once He makes it reach those whom He wills from His slaves, they start rejoicing,'),
(3458, 30, 49, 5, 8, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ اِنۡ کَانُوۡا مِنۡ قَبۡلِ اَنۡ یُّنَزَّلَ عَلَیۡہِمۡ مِّنۡ  قَبۡلِہٖ لَمُبۡلِسِیۡنَ ﴿۴۹﴾', 'جبکہ وہ اسکے برسنے سے پہلے یقینًا ناامید ہو رہے تھے۔', 'اور پہلے سے ہو رہے تھے اس کے اترنے سے پہلے ہی نا امید [۶۱]', 'And verily before that (rain), just before it was sent down upon them, they were in despair!', 'even though they were absolutely hopeless before it was sent down to them.'),
(3459, 30, 50, 5, 8, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'فَانۡظُرۡ  اِلٰۤی  اٰثٰرِ  رَحۡمَتِ اللّٰہِ  کَیۡفَ یُحۡیِ الۡاَرۡضَ بَعۡدَ مَوۡتِہَا ؕ اِنَّ  ذٰلِکَ لَمُحۡیِ  الۡمَوۡتٰی ۚ وَ ہُوَ  عَلٰی کُلِّ  شَیۡءٍ  قَدِیۡرٌ ﴿۵۰﴾', 'تو اے دیکھنے والے اللہ کی رحمت کی نشانیوں کی طرف دیکھ کہ وہ کس طرح زمین کو اسکے مرنے کے بعد زندہ کرتا ہے بیشک وہ مردوں کو زندہ کرنے والا ہے۔ اور وہ ہر چیز پر قادر ہے۔', 'سو دیکھ لے اللہ کی مہربانی کی نشانیاں کیونکر زندہ کرتا ہے زمین کو ا سکے مرگئے  پیچھے [۶۲] بیشک وہی ہے مردوں کو زندہ کرنے والا اور وہ ہرچیز کر سکتا ہے [۶۳]', 'Look then at the effects (results) of Allahs Mercy, how He revives the earth after its death. Verily! That (Allah) Who revived the earth after its death shall indeed raise the dead (on the Day of Resurrection), and He is Able to do all things.', 'So, look to the effects of Allah’s mercy, how He gives life to the earth after its death. Surely, That (Allah) is the One who will give life to the dead; and He has the power to do everything.'),
(3460, 30, 51, 5, 8, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ لَئِنۡ  اَرۡسَلۡنَا رِیۡحًا فَرَاَوۡہُ  مُصۡفَرًّا لَّظَلُّوۡا مِنۡۢ  بَعۡدِہٖ  یَکۡفُرُوۡنَ ﴿۵۱﴾', 'اور اگر ہم ایسی ہوا بھیجیں کہ وہ اسکے سبب کھیتی کو دیکھیں کہ زرد ہو گئ ہے تو اسکے بعد وہ ناشکری کرنے لگ جائیں۔', 'اور اگر ہم بھیجیں ایک ہوا پھر دیکھیں وہ کھیتی کو کہ زرد پڑ گئ تو لگیں اس کے پیچھے ناشکری کرنے [۶۴]', 'And if We send a wind (which would spoil the green growth (tilth) brought up by the previous rain), and they see (their tilth) turn yellow, behold, they then after their being glad, would become unthankful (to their Lord Allah as) disbelievers.', 'Should We send a (harmful) wind, and they see it (the tillage) turning yellow, then they will turn ungrateful, even after all the aforesaid (bounties of Allah).'),
(3461, 30, 52, 5, 8, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'فَاِنَّکَ لَا تُسۡمِعُ الۡمَوۡتٰی وَ لَا تُسۡمِعُ الصُّمَّ  الدُّعَآءَ   اِذَا  وَلَّوۡا  مُدۡبِرِیۡنَ ﴿۵۲﴾', 'تو تم مردوں کو بات نہیں سنا سکتے اور نہ بہروں کو جب وہ پیٹھ پھیر کو لوٹ جائیں آواز سنا سکتے ہو۔', 'سو تو سنا نہیں سکتا مردوں کو اور نہیں سنا سکتا بہروں کو پکارنا جب کہ پھریں پیٹھ دے کر', 'So verily, you (O Muhammad SAW) cannot make the dead to hear (i.e. the disbelievers, etc.), nor can you make the deaf to hear the call, when they show their backs, turning away.', 'So, you cannot make the dead to hear, nor can you make the deaf to hear the call when they turn their backs in retreat.'),
(3462, 30, 53, 5, 8, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ مَاۤ  اَنۡتَ بِہٰدِ الۡعُمۡیِ عَنۡ ضَلٰلَتِہِمۡ ؕ اِنۡ  تُسۡمِعُ  اِلَّا مَنۡ یُّؤۡمِنُ بِاٰیٰتِنَا فَہُمۡ مُّسۡلِمُوۡنَ ﴿٪۵۳﴾', 'اور نہ اندھوں کو انکی گمراہی سے نکال کر راہ راست پر لا سکتے ہو۔ تم تو انہی لوگوں کو سنا سکتے ہو جو ہماری آیتوں پر ایمان لاتے ہیں سو وہی فرمانبردار ہیں۔', 'اور نہ تو راہ سمجھائے ا ندھوں کو  انکے بھٹکنے سے تو تو سنائے اسی کو جو یقین لائے ہماری باتوں پر سو  وہ مسلمان ہوتے ہیں [۶۵]', 'And you (O Muhammad SAW) cannot guide the blind from their straying; you can make to hear only those who believe in Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), and have submitted to Allah in Islam (as Muslims).', 'Nor are you (able) to show the right path to the blind against their straying. You can make none to listen except those who believe in Our signs, hence they submit.'),
(3463, 30, 54, 6, 9, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'اَللّٰہُ  الَّذِیۡ خَلَقَکُمۡ مِّنۡ ضُؔعۡفٍ ثُمَّ جَعَلَ مِنۡۢ بَعۡدِ ضُؔعۡفٍ قُوَّۃً  ثُمَّ جَعَلَ مِنۡۢ بَعۡدِ قُوَّۃٍ  ضُؔعۡفًا وَّ شَیۡبَۃً ؕ یَخۡلُقُ مَا یَشَآءُ ۚ وَ ہُوَ  الۡعَلِیۡمُ  الۡقَدِیۡرُ ﴿۵۴﴾', 'اللہ ہی تو ہے جس نے تمکو ابتدا میں کمزور حالت میں پیدا کیا پھر کمزوری کے بعد طاقت عنایت کی پھر طاقت کے بعد کمزوری اور بڑھاپا دیا۔ وہ جو چاہتا ہے پیدا کرتا ہے اور وہ صاحب علم ہے صاحب قدرت ہے۔', 'اللہ ہے جس نے بنایا تم کمزوری سے پھر دیا کمزوری کے پیچھے زور پھر دے گا زور کے پیچھے کمزوری اور سفید بال بناتا ہے جو کچھ چاہے اور وہ ہے سب کچھ جانتا کر سکتا [۶۶]', 'Allah is He Who created you in (a state of) weakness, then gave you strength after weakness, then after strength gave (you) weakness and grey hair. He creates what He wills. And it is He Who is the AllKnowing, the AllPowerful (i.e. Able to do all things).', 'Allah is the One who created you in a state of weakness, then He created strength after weakness, then created weakness and old age after strength. He creates what He wills, and He is All-Knowing, All-Powerful.'),
(3464, 30, 55, 6, 9, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ یَوۡمَ تَقُوۡمُ السَّاعَۃُ  یُقۡسِمُ الۡمُجۡرِمُوۡنَ ۬ۙ مَا لَبِثُوۡا غَیۡرَ  سَاعَۃٍ ؕ کَذٰلِکَ  کَانُوۡا  یُؤۡفَکُوۡنَ ﴿۵۵﴾', 'اور جس روز قیامت برپا ہو گی گناہگار قسمیں اٹھائیں گے کہ وہ دنیا میں ایک گھڑی سے زیادہ نہیں رہے تھے۔ اسی طرح وہ اوندھائے جاتے تھے۔', 'اور جس دن قائم ہو گی قیامت قسمیں کھائیں گے گنہگار کہ ہم نہیں رہے تھے ایک گھڑی سے زیادہ [۶۷] اسی طرح تھے الٹے جاتے [۶۸]', 'And on the Day that the Hour will be established, the Mujrimoon (criminals, disbelievers, polytheists, sinners, etc.) will swear that they stayed not but an hour, thus were they ever deluded (away from the truth (i.e they used to tell lies and take false oaths, and turn away from the truth) in this life of the world)).', 'And on the Day when the Hour (Qiyāmah : the Day of Judgement) will take place, the sinners will swear that they did not remain (in the graves) more than one hour. In the similar way they used to be contrary (to truth in their worldly life).'),
(3465, 30, 56, 6, 9, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ قَالَ الَّذِیۡنَ  اُوۡتُوا الۡعِلۡمَ  وَ الۡاِیۡمَانَ لَقَدۡ لَبِثۡتُمۡ  فِیۡ کِتٰبِ اللّٰہِ  اِلٰی یَوۡمِ الۡبَعۡثِ ۫ فَہٰذَا یَوۡمُ الۡبَعۡثِ وَ لٰکِنَّکُمۡ  کُنۡتُمۡ  لَا  تَعۡلَمُوۡنَ ﴿۵۶﴾', 'اور جن لوگوں کو علم اور ایمان دیا گیا تھا وہ کہیں گے کہ اللہ کی کتاب کے مطابق تم قیامت تک رہے ہو۔ اور یہ قیامت ہی کا دن ہے لیکن تمکو اس کا یقین ہی نہ تھا۔', 'اور کہیں گے جنکو ملی ہے سمجھ اور یقین تمہارا ٹھہرنا تھا اللہ کی کتاب میں جی اٹھنے کے دن تک سو یہ ہے جی اُٹھنے کا دن پر تم نہیں تھے جانتے [۶۹]', 'And those who have been bestowed with knowledge and faith will say: \"Indeed you have stayed according to the Decree of Allah, until the Day of Resurrection, so this is the Day of Resurrection, but you knew not.\"', 'As for those who were given knowledge and belief, they will say, “You remained, according to the destiny written by Allah, up to the Day of Resurrection. So this is the Day of Resurrection, but you had no belief.”'),
(3466, 30, 57, 6, 9, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'فَیَوۡمَئِذٍ لَّا یَنۡفَعُ الَّذِیۡنَ ظَلَمُوۡا مَعۡذِرَتُہُمۡ  وَ لَا ہُمۡ  یُسۡتَعۡتَبُوۡنَ ﴿۵۷﴾', 'تو اس روز ظالم لوگوں کو ان کا عذر کچھ فائدہ نہ دے گا اور نہ ان سے توبہ قبول کی جائے گی۔', 'سو اُس دن کام نہ آئے گا ان گنہگاروں کو قصور بخشوانا اور نہ ان سے کوئی منانا چاہے [۷۰]', 'So on that Day no excuse of theirs will avail those who did wrong (by associating partners in worship with Allah, and by denying the Day of Resurrection), nor will they be allowed (then) to return to seek Allahs Pleasure (by having Islamic Faith with righteous deeds and by giving up polytheism, sins and crimes with repentance).', 'So, on that Day, their apology will not benefit the wrongdoers, nor will they be asked to repent.'),
(3467, 30, 58, 6, 9, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'وَ لَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِیۡ ہٰذَا الۡقُرۡاٰنِ مِنۡ کُلِّ مَثَلٍ ؕ وَ لَئِنۡ جِئۡتَہُمۡ بِاٰیَۃٍ لَّیَقُوۡلَنَّ  الَّذِیۡنَ کَفَرُوۡۤا اِنۡ  اَنۡتُمۡ  اِلَّا مُبۡطِلُوۡنَ ﴿۵۸﴾', 'اور ہم نے لوگوں کے سمجھانے کے لئے اس قرآن میں ہر طرح کی مثال بیان کر دی ہے اور اگر تم انکے سامنے کوئی نشانی پیش کرو تو یہ کافر کہدیں گے کہ تم تو جھوٹے ہو۔', 'اور ہم نے بٹھلائی ہے آدمیوں کے واسطے اس قرآن میں ہر ایک طرح کی مثل اور جو تو لائے اُنکے پاس کوئی آیت تو ضرور کہیں وہ منکر تم سب جھوٹ بناتے ہو [۷۱]', 'And indeed We have set forth for mankind, in this Quran every kind of parable. But if you (O Muhammad SAW) bring to them any sign or proof, (as an evidence for the truth of your Prophethood), the disbelievers are sure to say (to the believers): \"You follow nothing but falsehood, and magic.\"', 'Indeed We have given in this Qur’ān all kinds of examples for the benefit of mankind. (Still) if you bring to them a sign, the disbelievers will certainly say, “You are nothing but men of falsehood.”'),
(3468, 30, 59, 6, 9, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'کَذٰلِکَ یَطۡبَعُ اللّٰہُ عَلٰی قُلُوۡبِ الَّذِیۡنَ لَا  یَعۡلَمُوۡنَ  ﴿۵۹﴾', 'اسی طرح اللہ ان لوگوں کے دلوں پر جو سمجھ نہیں رکھتے مہر لگا دیتا ہے۔', 'یوں مہر لگا دیتا ہے اللہ اُن کے دلوں پر جو سمجھ نہیں رکھتے [۷۲]', 'Thus does Allah seal up the hearts of those who know not (the proofs and evidence of the Oneness of Allah i.e. those who try not to understand true facts that which you (Muhammad SAW) have brought to them).', 'Thus Allah seals up the hearts of those who do not believe.'),
(3469, 30, 60, 6, 9, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الروم', 'فَاصۡبِرۡ  اِنَّ وَعۡدَ اللّٰہِ  حَقٌّ وَّ لَا یَسۡتَخِفَّنَّکَ  الَّذِیۡنَ  لَا یُوۡقِنُوۡنَ ﴿٪۶۰﴾', 'پس تم جمے رہو بیشک اللہ کا وعدہ سچا ہے اور دیکھو جو لوگ یقین نہیں رکھتے وہ تمہیں اکھاڑ نہ بنا دیں۔', 'سو تو قائم رہ بیشک اللہ کا وعدہ ٹھیک ہے اور اکھاڑ نہ دیں تجھ کو وہ لوگ جو یقین نہیں لاتے [۷۳]', 'So be patient (O Muhammad SAW). Verily, the Promise of Allah is true, and let not those who have no certainty of faith, discourage you from conveying Allahs Message (which you are obliged to convey).', 'So, be patient. Surely Allah’s promise is true, and let not the disbelievers shake your firmness.'),
(3470, 31, 1, 1, 10, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'الٓـمّٓ ۚ﴿۱﴾', 'الٓم۔', 'الٓم۔', 'AlifLamMeem. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings.)', 'Alif Lām Mīm .'),
(3471, 31, 2, 1, 10, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'تِلۡکَ اٰیٰتُ الۡکِتٰبِ  الۡحَکِیۡمِ ۙ﴿۲﴾', 'یہ حکمت کی بھری ہوئی کتاب کی آیتیں ہیں۔', 'یہ آیتیں ہیں پکی کتاب کی', 'These are Verses of the Wise Book (the Quran).', 'These are verses of the Wise Book,'),
(3472, 31, 3, 1, 10, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'ہُدًی  وَّ  رَحۡمَۃً   لِّلۡمُحۡسِنِیۡنَ ۙ﴿۳﴾', 'نیکوکاروں کے لئے ہدایت اور رحمت۔', 'ہدایت ہے اور مہربانی نیکی کرنے والوں کے لئے [۱]', 'A guide and a mercy for the Muhsinoon (gooddoers)', 'a guidance and mercy for those who are good in their deeds'),
(3473, 31, 4, 1, 10, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'الَّذِیۡنَ یُقِیۡمُوۡنَ الصَّلٰوۃَ وَ یُؤۡتُوۡنَ الزَّکٰوۃَ وَ ہُمۡ بِالۡاٰخِرَۃِ ہُمۡ یُوۡقِنُوۡنَ ؕ﴿۴﴾', 'وہ جو نماز کی پابندی کرتے اور زکوٰۃ دیتے ہیں اور وہی ہیں جو آخرت کا یقین رکھتے ہیں۔', 'جو کہ قائم رکھتے ہیں نماز اور دیتے ہیں زکوٰۃ اور  وہ ہیں جو آخرت پر ان کو یقین ہے', 'Those who perform AsSalat (Iqamatas- Salat) and give Zakat and they have faith in the Hereafter with certainty.', 'who are steadfast in Salāh and who pay Zakāh and have faith in the Hereafter.'),
(3474, 31, 5, 1, 10, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'اُولٰٓئِکَ عَلٰی ہُدًی مِّنۡ رَّبِّہِمۡ وَ اُولٰٓئِکَ ہُمُ  الۡمُفۡلِحُوۡنَ ﴿۵﴾', 'یہی اپنے پروردگار کی طرف سے ہدایت پر ہیں اور یہی کامیاب ہیں۔', 'انہوں نے پائی ہے راہ اپنے رب کی طرف سےاور وہی مردا کو پہنچے [۲]', 'Such are on guidance from their Lord, and such are the successful.', 'It is these who are on guidance given by their Lord, and it is just these who are successful.'),
(3475, 31, 6, 1, 10, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'وَ مِنَ النَّاسِ مَنۡ یَّشۡتَرِیۡ لَہۡوَ الۡحَدِیۡثِ لِیُضِلَّ عَنۡ سَبِیۡلِ اللّٰہِ بِغَیۡرِ عِلۡمٍ ٭ۖ وَّ یَتَّخِذَہَا ہُزُوًا ؕ اُولٰٓئِکَ لَہُمۡ عَذَابٌ  مُّہِیۡنٌ ﴿۶﴾', 'اور لوگوں میں بعض ایسا ہے جو بیہودہ حکایتیں خریدتا ہے تاکہ لوگوں کو بے سمجھے اللہ کے رستے سے گمراہ کرے اور اس سے ہنسی کرے یہی لوگ ہیں جنکو ذلیل کرنے والا عذاب ہوگا۔', 'اور ایک وہ لوگ ہیں کہ خریدارا ہیں کھیل کی باتوں کے تاکہ بچلائیں اللہ کی راہ سے بن سمجھے اور ٹھہرائیں اسی کو ہنسی وہ جو ہیں ان کو ذلت کا عذاب ہے [۳]', 'And of mankind is he who purchases idle talks (i.e.music, singing, etc.) to mislead (men) from the Path of Allah without knowledge, and takes it (the Path of Allah, the Verses of the Quran) by way of mockery. For such there will be a humiliating torment (in the Hell-fire).', 'There is a man among the people who buys discourses of distracting amusements, so that he may mislead (people) from the Way of Allah, and make a mockery of it. For such people there is a disgraceful punishment.'),
(3476, 31, 7, 1, 10, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'وَ اِذَا تُتۡلٰی عَلَیۡہِ اٰیٰتُنَا وَلّٰی مُسۡتَکۡبِرًا کَاَنۡ  لَّمۡ یَسۡمَعۡہَا کَاَنَّ فِیۡۤ  اُذُنَیۡہِ  وَقۡرًا ۚ فَبَشِّرۡہُ  بِعَذَابٍ اَلِیۡمٍ ﴿۷﴾', 'اور جب اسکو ہماری آیتیں سنائی جاتی ہیں تو اکڑ کر منہ پھیر لیتا ہے گویا انکو سنا ہی نہیں۔ جیسے اسکے کانوں میں ثقل ہے تو اسکو درد دینے والے عذاب کی خوشخبری سنا دو۔', 'اور جب سنائے اس کو ہمای آیتیں پیٹھ دیجائے غرور سے گویا ان کو سنا ہی نہیں گویا اس کےدونوں کان بہرے ہیں سو خوشخبری دے اس کو دردناک عذاب کی [۴]', 'And when Our Verses (of the Quran) are recited to such a one, he turns away in pride, as if he heard them not, as if there were deafness in his ear. So announce to him a painful torment.', 'And when Our verses are recited to him, he turns away in arrogance, as if he did not hear them, as if there is heaviness in his ears. So give him the ‘good’ news of a painful punishment.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(3477, 31, 8, 1, 10, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'اِنَّ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ لَہُمۡ  جَنّٰتُ  النَّعِیۡمِ ۙ﴿۸﴾', 'جو لوگ ایمان لائے اور نیک کام کرتے رہے انکے لئے نعمت کے باغ ہیں۔', 'جو لوگ یقین لائے اور کیے بھلے کام  ان کے  واسطے ہیں نعمت کے باغ', 'Verily, those who believe (in Islamic Monotheism) and do righteous good deeds, for them are Gardens of delight (Paradise).', 'Surely, for those who believe and do righteous deeds there are gardens of bliss'),
(3478, 31, 9, 1, 10, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'خٰلِدِیۡنَ فِیۡہَا ؕ وَعۡدَ اللّٰہِ حَقًّا ؕ وَ ہُوَ الۡعَزِیۡزُ  الۡحَکِیۡمُ ﴿۹﴾', 'ہمیشہ ان میں رہیں گے۔ اللہ کا وعدہ سچا ہے۔ اور وہ غالب ہے حکمت والا ہے۔', 'ہمیشہ رہا کریں ان میں وعدہ ہو چکا اللہ کا سچا اور وہ زبردست ہے حکمتوں والا [۵]', 'To abide therein. It is a Promise of Allah in truth. And He is the AllMighty, the AllWise.', 'in which they will live forever - an absolute promise of Allah. He is the Mighty, the Wise.'),
(3479, 31, 10, 1, 10, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'خَلَقَ السَّمٰوٰتِ بِغَیۡرِ عَمَدٍ تَرَوۡنَہَا وَ اَلۡقٰی فِی الۡاَرۡضِ رَوَاسِیَ  اَنۡ تَمِیۡدَ بِکُمۡ وَ بَثَّ فِیۡہَا مِنۡ کُلِّ دَآبَّۃٍ ؕ وَ اَنۡزَلۡنَا مِنَ السَّمَآءِ مَآءً  فَاَنۡۢبَتۡنَا فِیۡہَا مِنۡ  کُلِّ  زَوۡجٍ  کَرِیۡمٍ ﴿۱۰﴾', 'اسی نے آسمانوں کو ستونوں کے بغیر پیدا کیا جیسا کہ تم دیکھتے ہو۔ اور زمین میں پہاڑ بنا کر رکھ دیئے تاکہ وہ تمکو لیکر ڈولنے نہ لگے اور اس میں ہر طرح کے جانور پھیلا دیئے۔ اور ہم ہی نے آسمان سے پانی نازل کیا پھر اس میں ہر قسم کی نفیس چیزیں اگائیں۔', 'بنائے آسمان بغیر ستونوں کے تم اس کو دیکھتے ہو [۶] اور رکھ دیے زمین پر پہاڑ کہ تم کو لیکر جھک نہ پڑے [۷] اور بکھیر دیے اس میں سب طرح کے جانور اور اتارا ہم نے آسمان سے پانی پھر اگائے زمین میں ہر قسم کے جوڑے خاصے [۸]', 'He has created the heavens without any pillars, that you see and has set on the earth firm mountains, lest it should shake with you. And He has scattered therein moving (living) creatures of all kinds. And We send down water (rain) from the sky, and We cause (plants) of every goodly kind to grow therein.', 'He has created the skies without the pillars that you may see, and placed mountains on the earth, lest it shakes with you, and spread over it all kinds of creatures. And We sent down water from the heavens, and caused to grow in it every noble pair.'),
(3480, 31, 11, 1, 10, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'ہٰذَا خَلۡقُ اللّٰہِ  فَاَرُوۡنِیۡ  مَاذَا خَلَقَ الَّذِیۡنَ مِنۡ دُوۡنِہٖ ؕ بَلِ الظّٰلِمُوۡنَ فِیۡ ضَلٰلٍ مُّبِیۡنٍ ﴿٪۱۱﴾', 'یہ تو اللہ کی تخلیق ہے اب مجھے دکھاؤ کہ اللہ کے سوا جو ہستیاں ہیں انہوں نے کیا پیدا کیا ہے؟ حقیقت یہ ہے کہ یہ ظالم کھلی گمراہی میں ہیں۔', 'یہ سب کچھ بنایا ہوا ہے اللہ کا اب دکھلاؤ مجھ کو کیا بنایا ہے اوروں نے جو  اس کے سوا ہیں [۹] کچھ نہیں پر  بے انصاف صریح بھٹک رہے ہیں [۱۰]', 'This is the creation of Allah. So show Me that which those (whom you worship), besides Him have created. Nay, the Zalimoon (polytheists, wrongdoers and those who do not believe in the Oneness of Allah) are in plain error.', 'This is the creation of Allah. Now, show me what is created by those others, besides Him. Rather, the transgressors are in open error.'),
(3481, 31, 12, 2, 11, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'وَ لَقَدۡ اٰتَیۡنَا لُقۡمٰنَ الۡحِکۡمَۃَ اَنِ اشۡکُرۡ لِلّٰہِ ؕ وَ مَنۡ یَّشۡکُرۡ فَاِنَّمَا یَشۡکُرُ لِنَفۡسِہٖ ۚ وَ مَنۡ کَفَرَ فَاِنَّ اللّٰہَ غَنِیٌّ حَمِیۡدٌ ﴿۱۲﴾', 'اور ہم نے لقمان کو دانائی بخشی۔ کہ اللہ کا شکر کرو۔ اور جو شخص شکر کرتا ہے تو اپنے ہی فائدے کے لئے شکر کرتا ہے۔ اور جو ناشکری کرتا ہے تو اللہ بھی بے نیاز ہے لائق حمد و ثنا ہے۔', 'اور ہم نے دی لقمان کو عقل مندی [۱۱] کہ حق مان اللہ کا اور جو کوئی حق مانے اللہ کا تو مانے گا اپنے بھلے کو اور جو کوئی منکر ہو گا تو اللہ بے پروا ہے سب تعریفوں والا [۱۲]', 'And indeed We bestowed upon Luqman AlHikmah (wisdom and religious understanding, etc.) saying: \"Give thanks to Allah,\" and whoever gives thanks, he gives thanks for (the good of) his ownself. And whoever is unthankful, then verily, Allah is AllRich (Free of all wants), Worthy of all praise.', 'We gave wisdom to Luqmān, and said, “Be grateful to Allah;” and whoever is grateful is, in fact, grateful for his own benefit, and whoever is ungrateful, then Allah is free of all needs, worthy of all praise.'),
(3482, 31, 13, 2, 11, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'وَ اِذۡ قَالَ لُقۡمٰنُ لِابۡنِہٖ وَ ہُوَ یَعِظُہٗ یٰبُنَیَّ لَا تُشۡرِکۡ بِاللّٰہِ ؕؔ اِنَّ الشِّرۡکَ لَظُلۡمٌ  عَظِیۡمٌ ﴿۱۳﴾', 'اور اس وقت کو یاد کرو جب لقمان نے اپنے بیٹے کو نصیحت کرتے ہوئے کہا کہ بیٹا اللہ کے ساتھ شرک نہ کرنا۔ شرک تو بڑا بھاری ظلم ہے۔', 'اور جب کہا لقمان نے اپنے بیٹے کو جب اس کو سمجھانے لگا اے بیٹے شریک نہ ٹھہرائیو اللہ کا [۱۳] بیشک شریک بنانا بھاری بے انصافی ہے [۱۴]', 'And (remember) when Luqman said to his son when he was advising him: \"O my son! Join not in worship others with Allah. Verily! Joining others in worship with Allah is a great Zoolm (wrong) indeed.', '(Remember) when Luqmān said to his son, while he was advising him, “My dear son, do not ascribe partners to Allah. Indeed, ascribing partners to Allah (shirk) is grave transgression.”'),
(3483, 31, 14, 2, 11, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'وَ وَصَّیۡنَا  الۡاِنۡسَانَ بِوَالِدَیۡہِ ۚ حَمَلَتۡہُ  اُمُّہٗ  وَہۡنًا عَلٰی وَہۡنٍ وَّ فِصٰلُہٗ  فِیۡ عَامَیۡنِ  اَنِ اشۡکُرۡ لِیۡ وَ لِوَالِدَیۡکَ ؕ اِلَیَّ  الۡمَصِیۡرُ ﴿۱۴﴾', 'اور ہم نے انسان کو جسے اسکی ماں تکلیف پر تکلیف سہہ کر پیٹ میں اٹھائے رکھتی ہے پھر اسکو دودھ پلاتی ہے اور آخرکار دو برس میں اس کا دودھ چھڑانا ہوتا ہے میں نے تاکید کی ہے کہ میرا بھی شکر کرتا رہ اور اپنے ماں باپ کا بھی کہ تمکو میری ہی طرف لوٹ کر آنا ہے۔', 'اور ہم نے تاکید کر دی انسان کو  اسکے ماں باپ کے واسطے پیٹ میں رکھا اس کو اسکی ماں نے تھک تھک کر اور دودھ چھڑانا ہے اس کا دو برس میں کہ حق مان میرا اور اپنے ماں باپ کا آخر مجھی تک آنا ہے [۱۵]', 'And We have enjoined on man (to be dutiful and good) to his parents. His mother bore him in weakness and hardship upon weakness and hardship, and his weaning is in two years give thanks to Me and to your parents, unto Me is the final destination.', 'We commanded man (to be good) in respect of his parents. His mother carried him (in her womb) despite weakness upon weakness, and his weaning is in two years. (We said to man,) “Be grateful to Me, and to your parents. To Me is the ultimate return.'),
(3484, 31, 15, 2, 11, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'وَ اِنۡ جَاہَدٰکَ عَلٰۤی اَنۡ تُشۡرِکَ بِیۡ مَا لَیۡسَ لَکَ بِہٖ عِلۡمٌ ۙ فَلَا تُطِعۡہُمَا وَ صَاحِبۡہُمَا فِی الدُّنۡیَا مَعۡرُوۡفًا ۫ وَّ اتَّبِعۡ سَبِیۡلَ مَنۡ اَنَابَ اِلَیَّ ۚ ثُمَّ  اِلَیَّ مَرۡجِعُکُمۡ فَاُنَبِّئُکُمۡ بِمَا کُنۡتُمۡ تَعۡمَلُوۡنَ ﴿۱۵﴾', 'اور اگر وہ دونوں تجھ پر زور ڈالیں کہ تو میرے ساتھ کسی ایسی چیز کو شریک کرے جس کا تجھے کچھ بھی علم نہیں تو ان کا کہا نہ ماننا۔ ہاں دنیا کے کاموں میں ان کا اچھی طرح ساتھ دینا اور جو شخص میری طرف رجوع لائے اس کے رستے پر چلنا پھر تمکو میری طرف لوٹ کر آنا ہے۔ تو جو کام تم کرتے رہے ہو سب سے تمکو آگاہ کر دوں گا۔', 'اور اگر وہ دونوں تجھ سے اڑیں اس بات پر کہ شریک مان میرا اس چیز کو جو تجھ کو معلوم نہیں تو انکا کہنا مت مان [۱۶] اور ساتھ دے ان کا دنیا میں دستور کے موافق [۱۷] اور راہ چل اس کی جو رجوع ہوا میری طرف [۱۸] پھر میری طرف ہے تم کو پھر آنا پھر میں جتلا دوں گا تم کو جو کچھ تم کرتے تھے [۱۹]', 'But if they (both) strive with you to make you join in worship with Me others that of which you have no knowledge, then obey them not, but behave with them in the world kindly, and follow the path of him who turns to Me in repentance and in obedience. Then to Me will be your return, and I shall tell you what you used to do.', 'However, if they force you to ascribe partners to Me about whom you (can) have no (source of) knowledge, then do not obey them. Remain with them in this world with due fairness, but follow the way of the one who has turned himself towards Me. Then, towards Me is your return, so I shall tell you what you had been doing.”'),
(3485, 31, 16, 2, 11, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'یٰبُنَیَّ  اِنَّہَاۤ  اِنۡ تَکُ مِثۡقَالَ حَبَّۃٍ  مِّنۡ خَرۡدَلٍ فَتَکُنۡ فِیۡ صَخۡرَۃٍ  اَوۡ فِی السَّمٰوٰتِ اَوۡ فِی الۡاَرۡضِ یَاۡتِ بِہَا اللّٰہُ ؕ اِنَّ اللّٰہَ  لَطِیۡفٌ خَبِیۡرٌ ﴿۱۶﴾', 'لقمان نے یہ بھی کہا کہ بیٹا اگر کوئی عمل چاہے رائی کے دانے کے برابر بھی چھوٹا ہو اور ہو بھی کسی پتھر کے اندر یا آسمانوں میں مخفی ہو یا زمین میں اللہ اسکو قیامت کے دن لا موجود کرے گا۔ کچھ شک نہیں کہ اللہ باریک بین ہے خبردار ہے۔', 'اے بیٹے اگر کوئی چیز ہو برابر رائی کے دانہ کی پھر وہ ہو کسی پتھر میں یا آسمانوں میں یا زمین میں لا حاضر کرے اس کو اللہ بیشک اللہ جانتا ہے چھپی ہوئی چیزوں کو خبردار ہے [۲۰]', '\"O my son! If it be (anything) equal to the weight of a grain of mustard seed, and though it be in a rock, or in the heavens or in the earth, Allah will bring it forth. Verily, Allah is Subtle (in bringing out that grain), WellAware (of its place).', '(Luqmān went on saying to his son,) “My dear son, in fact, if there be anything to the measure of a grain of rye, and it be (hidden) in a rock or in the heavens or in the earth, Allah will bring it forth. Surely, Allah is All-Fine, All-Aware.'),
(3486, 31, 17, 2, 11, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'یٰبُنَیَّ  اَقِمِ الصَّلٰوۃَ  وَ اۡمُرۡ بِالۡمَعۡرُوۡفِ وَ انۡہَ  عَنِ الۡمُنۡکَرِ وَ اصۡبِرۡ عَلٰی مَاۤ اَصَابَکَ ؕ اِنَّ  ذٰلِکَ مِنۡ عَزۡمِ  الۡاُمُوۡرِ ﴿ۚ۱۷﴾', 'بیٹا نماز کی پابندی رکھنا اور لوگوں کو اچھے کاموں کے کرنے کا مشورہ دیتے رہنا بری باتوں سے منع کرتے رہنا اور جو مصیبت تجھ پر واقع ہو اس پر صبر کرنا۔ بیشک یہ بڑی ہمت کے کام ہیں۔', 'اے بیٹے قائم رکھ نماز اور سکھلا بھلی بات اور منع کر برائی سے [۲۱] اور تحمل کر جو تجھ پر پڑے بیشک یہ ہیں ہمت کے کام [۲۲]', '\"O my son! AqimisSalat (perform AsSalat), enjoin (people) for AlMaroof (Islamic Monotheism and all that is good), and forbid (people) from AlMunkar (i.e. disbelief in the Oneness of Allah, polytheism of all kinds and all that is evil and bad), and bear with patience whatever befall you. Verily! These are some of the important commandments ordered by Allah with no exemption.', 'My dear son, establish Salāh , and bid the Fair and forbid the Unfair, and observe patience on what befalls you. Surely, this is among the matters of determination;'),
(3487, 31, 18, 2, 11, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'وَ لَا تُصَعِّرۡ  خَدَّکَ  لِلنَّاسِ وَ لَا  تَمۡشِ فِی الۡاَرۡضِ مَرَحًا ؕ اِنَّ  اللّٰہَ  لَا  یُحِبُّ  کُلَّ مُخۡتَالٍ  فَخُوۡرٍ ﴿ۚ۱۸﴾', 'اور تکبر کرتے ہوئے لوگوں کے سامنے گال نہ پھلانا اور زمین میں اکڑ کر نہ چلنا۔ اسلئے کہ اللہ کسی اترانے والے شیخی خورے کو پسند نہیں کرتا۔', 'اور اپنے گال مت پھلا لوگوں کی طرف [۲۳] اور مت چل زمین پر اتراتا بیشک اللہ کو نہیں بھاتا کوئی اتراتا بڑائیاں کرنے والا [۲۴]', '\"And turn not your face away from men with pride, nor walk in insolence through the earth. Verily, Allah likes not each arrogant boaster.', 'and do not turn your cheek away from people, and do not walk on the earth haughtily. Surely, Allah does not like anyone who is arrogant, proud;'),
(3488, 31, 19, 2, 11, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'وَ اقۡصِدۡ فِیۡ  مَشۡیِکَ وَ اغۡضُضۡ مِنۡ صَوۡتِکَ ؕ اِنَّ  اَنۡکَرَ  الۡاَصۡوَاتِ لَصَوۡتُ الۡحَمِیۡرِ ﴿٪۱۹﴾', 'اور اپنی چال میں اعتدال کئے رہنا اور بولتے وقت ذرا آواز نیچی رکھنا کیونکہ بہت اونچی آواز گدھوں کی سی ہے اور کچھ شک نہیں کہ سب سے بری آواز گدھوں کی ہوتی ہے۔', 'اور چل بیچ کی چال اور نیچی کر آواز اپنی بیشک بری سے بری آواز گدھے کی آواز ہے [۲۵]', '\"And be moderate (or show no insolence) in your walking, and lower your voice. Verily, the harshest of all voices is the voice (braying) of the ass.\"', 'and be moderate in your walk, and lower your voice. Surely, the ugliest of voices is the voice of the donkeys.”'),
(3489, 31, 20, 3, 12, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'اَلَمۡ تَرَوۡا اَنَّ اللّٰہَ سَخَّرَ لَکُمۡ مَّا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ وَ اَسۡبَغَ عَلَیۡکُمۡ نِعَمَہٗ  ظَاہِرَۃً  وَّ بَاطِنَۃً ؕ وَ مِنَ النَّاسِ مَنۡ یُّجَادِلُ فِی اللّٰہِ  بِغَیۡرِ عِلۡمٍ وَّ لَا ہُدًی وَّ لَا کِتٰبٍ مُّنِیۡرٍ ﴿۲۰﴾', 'کیا تم نے نہیں دیکھا کہ جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب کو اللہ نے تمہارے قابو میں کر دیا ہے اور تم پر اپنی ظاہری اور باطنی نعمتیں پوری کر دی ہیں۔ اور بعض لوگ ایسے ہیں کہ اللہ کے بارے میں جھگڑتے ہیں نہ علم رکھتے ہیں اور نہ ہدایت اور نہ کتاب روشن۔', 'کیا تم نے نہیں دیکھا کہ اللہ نے کام میں لگائے تمہارے جو کچھ ہے آسمان اور زمین میں [۲۶] اور پوری کر دیں تم پر اپنی نعمتیں کھلی اور چھپی [۲۷] اور لوگوں میں ایسے بھی ہیں جو جھگڑتے ہیں اللہ کی بات میں نہ سمجھ رکھیں نہ سوجھ اور نہ روشن کتاب [۲۸]', 'See you not (O men) that Allah has subjected for you whatsoever is in the heavens and whatsoever is in the earth, and has completed and perfected His Graces upon you, (both) apparent (i.e Islamic Monotheism, and the lawful pleasures of this world, including health, good looks, etc.) and hidden (i.e. Ones Faith in Allah (of Islamic Monotheism) knowledge, wisdom, guidance for doing righteous deeds, and also the pleasures and delights of the Hereafter in Paradise, etc.)? Yet of mankind is he who disputes about Allah without knowledge or guidance or a Book giving light!', 'Have you not seen that Allah has subjugated for you what is in the heavens and what is on the earth, and has perfected His blessings on you, both outward and inward? But among people there are those who debate about Allah with no knowledge, no guidance and no book to enlighten.'),
(3490, 31, 21, 3, 12, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'وَ اِذَا قِیۡلَ لَہُمُ اتَّبِعُوۡا مَاۤ  اَنۡزَلَ اللّٰہُ قَالُوۡا بَلۡ نَتَّبِعُ مَا وَجَدۡنَا عَلَیۡہِ اٰبَآءَنَا ؕ اَوَ لَوۡ  کَانَ الشَّیۡطٰنُ یَدۡعُوۡہُمۡ  اِلٰی  عَذَابِ  السَّعِیۡرِ ﴿۲۱﴾', 'اور جب ان سے کہا جاتا ہے کہ جو کتاب اللہ نے نازل فرمائی ہے اسکی پیروی کرو۔ تو کہتے ہیں کہ ہم تو اسی کی پیروی کریں گے جس پر ہم نے اپنے باپ دادوں کو پایا۔ بھلا اگرچہ شیطان انکو دوزخ کے عذاب کی طرف بلاتا ہو تب بھی۔', 'اور جب ان کو کہیے چلو اس حکم پر جو  اتارا  اللہ نے کہیں نہیں ہم تو چلیں گے اس پر جس پر پایا ہم نے اپنے باپ دادوں کو بھلا اور جو شیطان بلاتا ہو ان کو دوزخ کے عذاب کی طرف تو  بھی [۲۹]', 'And when it is said to them: \"Follow that which Allah has sent down\", they say: \"Nay, we shall follow that which we found our fathers (following).\" (Would they do so) even if Shaitan (Satan) invites them to the torment of the Fire.', 'When it is said to them, “follow what Allah has sent down,” they say, “Instead, we would follow that on which we have found our fathers.” Is it so, even though the Satan has been calling them to the punishment of the flaming Fire?'),
(3491, 31, 22, 3, 12, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'وَ مَنۡ یُّسۡلِمۡ وَجۡہَہٗۤ  اِلَی اللّٰہِ وَ ہُوَ مُحۡسِنٌ فَقَدِ اسۡتَمۡسَکَ بِالۡعُرۡوَۃِ الۡوُثۡقٰی ؕ وَ  اِلَی اللّٰہِ  عَاقِبَۃُ  الۡاُمُوۡرِ ﴿۲۲﴾', 'اور جو شخص اپنے آپکو اللہ کا فرمانبردار کر دے اور نیکوکار بھی ہو تو اس نے مضبوط کڑا تھام لیا۔ اور سب کاموں کا انجام اللہ ہی کی طرف ہے۔', 'اور جو کوئی تابع کرے اپنا منہ اللہ کی طرف اور وہ ہو نیکی پر سو اس نے پکڑ لیا مضبوط کڑا [۳۰] اور اللہ کی طرف ہے آخر ہر کام کا [۳۱]', 'And whosoever submits his face (himself) to Allah (i.e.(follows Allahs Religion of Islamic Monotheism), worships Allah (Alone) with sincere Faith in the (1) Oneness of His Lordship,(2) Oneness of His worship, and (3) Oneness of His Names and Qualities), while he is a Muhsin (gooddoer i.e. performs good deeds totally for Allahs sake without any show-off or to gain praise or fame etc. and does them in accordance with the Sunnah of Allahs Messenger Muhammad SAW), then he has grasped the most trustworthy handhold (La ilaha ill-Allah (none has the right to be worshipped but Allah)). And to Allah return all matters for decision.', 'And whoever submits his self to Allah and is good in deeds, he in fact holds on to the strongest ring. Towards Allah is the ultimate end of all matters.'),
(3492, 31, 23, 3, 12, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'وَ مَنۡ کَفَرَ فَلَا یَحۡزُنۡکَ کُفۡرُہٗ ؕ اِلَیۡنَا مَرۡجِعُہُمۡ فَنُنَبِّئُہُمۡ بِمَا عَمِلُوۡا ؕ اِنَّ اللّٰہَ  عَلِیۡمٌۢ   بِذَاتِ  الصُّدُوۡرِ ﴿۲۳﴾', 'اور جو کفر کرے تو اس کا کفر تمہیں غمناک نہ کر دے انکو ہماری طرف لوٹ کر آنا ہے پھر جو کام وہ کیا کرتے تھے ہم انکو جتا دیں گے۔ بیشک اللہ دلوں کی باتوں سے بھی واقف ہے۔', 'اور جو کوئی منکر ہوا تو تو غم نہ کھا اسکے انکار سے ہماری طرف پھر آنا ہے انکو  پھر ہم جتلا دیں گے ان کو جو انہوں نے کیا ہے البتہ اللہ جانتا ہے جو بات ہے دلوں میں [۳۲]', 'And whoever disbelieved, let not his disbelief grieve you (O Muhammad SAW),. to Us is their return, and We shall inform them what they have done. Verily, Allah is the AllKnower of what is in the breasts (of men).', 'And whoever disbelieves, let not his disbelief grieve you. To Us is their return. Then We will tell them what they did. Surely, Allah is All Aware of what lies in the hearts.'),
(3493, 31, 24, 3, 12, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'نُمَتِّعُہُمۡ قَلِیۡلًا ثُمَّ نَضۡطَرُّہُمۡ  اِلٰی عَذَابٍ  غَلِیۡظٍ ﴿۲۴﴾', 'ہم انکو تھوڑا سا فائدہ پہنچائیں گے پھر عذاب شدید کی طرف مجبور کر کے لیجائیں گے۔', 'کام چلا دیں گے ہم انکا تھوڑے دنوں میں پھر پکڑ بلائیں گے ان کو گاڑھے عذاب میں [۳۳]', 'We let them enjoy for a little while, then in the end We shall oblige them to (enter) a great torment.', 'We let them enjoy a little, then We will drag them to a heavy punishment.'),
(3494, 31, 25, 3, 12, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'وَ لَئِنۡ سَاَلۡتَہُمۡ مَّنۡ خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ لَیَقُوۡلُنَّ اللّٰہُ ؕ قُلِ  الۡحَمۡدُ لِلّٰہِ ؕ بَلۡ  اَکۡثَرُہُمۡ  لَا  یَعۡلَمُوۡنَ ﴿۲۵﴾', 'اور اگر تم ان سے پوچھو کہ آسمانوں اور زمین کو کس نے پیدا کیا تو بول اٹھیں گے کہ اللہ نے۔ کہدو کہ اللہ کا شکر ہے لیکن ان میں اکثر سمجھ نہیں رکھتے۔', 'اور اگر تو پوچھے ان سے کس نے بنائے آسمان اور زمین تو کہیں اللہ نے تو کہہ سب خوبی اللہ کو ہے پر وہ بہت لوگ سمجھ نہیں رکھتے [۳۴]', 'And if you (O Muhammad SAW) ask them: \"Who has created the heavens and the earth,\" they will certainly say: \"Allah.\" Say: \"All the praises and thanks be to Allah!\" But most of them know not.', 'And if you ask them as to who has created the heavens and the earth, they will certainly say, “Allah.” Say, “AlHamdulillāh ” (Praise be to Allah). But most of them do not know.'),
(3495, 31, 26, 3, 12, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'لِلّٰہِ مَا فِی السَّمٰوٰتِ  وَ الۡاَرۡضِ ؕ اِنَّ  اللّٰہَ ہُوَ  الۡغَنِیُّ   الۡحَمِیۡدُ ﴿۲۶﴾', 'جو کچھ آسمانوں اور زمین میں ہے سب اللہ ہی کا ہے۔ بیشک اللہ بے نیاز ہے لائق حمد و ثنا ہے۔', 'اللہ کا ہے جو کچھ ہے آسمان اور زمین میں بیشک اللہ وہی ہے بے پروا سب خوبیوں والا [۳۵]', 'To Allah belongs whatsoever is in the heavens and the earth. Verily, Allah, He is AlGhanee (Rich, Free of all wants), Worthy of all praise.', 'To Allah belongs what is in the heavens and the earth. Surely, it is Allah who is free of all needs, worthy of every praise.'),
(3496, 31, 27, 3, 12, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'وَ لَوۡ اَنَّ مَا فِی الۡاَرۡضِ مِنۡ شَجَرَۃٍ  اَقۡلَامٌ  وَّ  الۡبَحۡرُ  یَمُدُّہٗ  مِنۡۢ بَعۡدِہٖ سَبۡعَۃُ  اَبۡحُرٍ  مَّا نَفِدَتۡ  کَلِمٰتُ اللّٰہِ ؕ اِنَّ  اللّٰہَ  عَزِیۡزٌ  حَکِیۡمٌ ﴿۲۷﴾', 'اور اگر یوں ہو کہ زمین میں جتنے درخت ہیں سب کے سب قلم ہوں اور سمندر کا تمام پانی سیاہی ہو اور اسکے بعد سات سمندر اور سیاہی ہو جائیں تو اللہ کی باتیں یعنی اسکی صفتیں ختم نہ ہوں۔ بیشک اللہ غالب ہے حکمت والا ہے۔', 'اور اگر جتنے درخت ہیں زمین میں قلم ہوں اور سمندر ہو اس کی سیاہی اسکے پیچھے ہوں سات سمندر نہ تمام ہوں باتیں اللہ کی بیشک اللہ زبردست ہے حکمتوں والا [۳۶]', 'And if all the trees on the earth were pens and the sea (were ink wherewith to write), with seven seas behind it to add to its (supply), yet the Words of Allah would not be exhausted. Verily, Allah is AllMighty, AllWise.', 'And if all trees that are on the earth were to be pens, and the ocean (converted into ink) is supported by seven seas following it, the words of Allah would not come to an end. Surely, Allah is Mighty, Wise.'),
(3497, 31, 28, 3, 12, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'مَا خَلۡقُکُمۡ وَ لَا بَعۡثُکُمۡ  اِلَّا کَنَفۡسٍ وَّاحِدَۃٍ ؕ  اِنَّ  اللّٰہَ  سَمِیۡعٌۢ  بَصِیۡرٌ ﴿۲۸﴾', 'اللہ کو تمہارا پیدا کرنا اور جلا اٹھانا ایک شخص کے پیدا کرنے اور جلا اٹھانے کی طرح ہے۔ بیشک اللہ سننے والا ہے دیکھنے والا ہے۔', 'تم سب کا بنانا اور مرے پیچھے جلانا ایسا ہی ہے جیسا ایک جی کا [۳۷] بیشک اللہ سب کچھ سنتا دیکھتا ہے [۳۸]', 'The creation of you all and the resurrection of you all are only as (the creation and resurrection of) a single person. Verily, Allah is AllHearer, AllSeer.', 'Creation and resurrection of all of you is no more (to Allah) than that of one single person. Surely, Allah is All-Hearing, All Seeing.'),
(3498, 31, 29, 3, 12, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'اَلَمۡ  تَرَ  اَنَّ اللّٰہَ یُوۡلِجُ الَّیۡلَ فِی النَّہَارِ وَ یُوۡلِجُ النَّہَارَ فِی الَّیۡلِ وَ سَخَّرَ الشَّمۡسَ وَ الۡقَمَرَ ۫ کُلٌّ  یَّجۡرِیۡۤ   اِلٰۤی   اَجَلٍ مُّسَمًّی وَّ اَنَّ اللّٰہَ بِمَا تَعۡمَلُوۡنَ خَبِیۡرٌ ﴿۲۹﴾', 'کیا تم نے نہیں دیکھا کہ اللہ ہی رات کو دن میں داخل کرتا ہے اور دن کو رات میں داخل کرتا ہے اور اسی نے سورج اور چاند کو کام میں لگا رکھا ہے۔ ہر ایک ایک وقت مقرر تک چل  رہا ہے اور یہ کہ اللہ تمہارے سب اعمال سے خبردار ہے۔', 'تو نے نہیں دیکھا کہ اللہ داخل کرتا ہے رات کو دن میں اور داخل کرتا ہے دن کو رات میں اور کام میں لگا دیا ہے سورج اور چاند کو ہر ایک چلتا ہے ایک مقرر وقت تک [۳۹] اور یہ کہ اللہ خبر رکھتا ہے اسکی جو تم کرتے ہو [۴۰]', 'See you not (O Muhammad SAW) that Allah merges the night into the day (i.e. the decrease in the hours of the night are added in the hours of the day), and merges the day into the night (i.e. the decrease in the hours of day are added in the hours of night), and has subjected the sun and the moon, each running its course for a term appointed; and that Allah is AllAware of what you do.', 'Did you not see that Allah makes the night enter into the day, and makes the day enter into the night, and He has subjugated the sun and the moon, each running towards an appointed time, and that Allah is fully aware of what you do?'),
(3499, 31, 30, 3, 12, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'ذٰلِکَ بِاَنَّ اللّٰہَ ہُوَ الۡحَقُّ وَ اَنَّ مَا یَدۡعُوۡنَ مِنۡ دُوۡنِہِ الۡبَاطِلُ ۙ وَ اَنَّ اللّٰہَ ہُوَ  الۡعَلِیُّ  الۡکَبِیۡرُ ﴿٪۳۰﴾', 'یہ اس لئے کہ اللہ کی ذات ہی برحق ہے اور جس جس کو یہ لوگ اللہ کے سوا پکارتے ہیں وہ سب باطل ہے اور یہ کہ اللہ ہی عالی رتبہ ہے گرامی قدر ہے۔', 'یہ اس لیے کہا کہ اللہ وہی ہے ٹھیک اور جس کسی کو پکارتے ہیں اس کے سوائے سو  وہی جھوٹ ہے [۴۱] اور اللہ وہی ہے سب سے اوپر بڑا [۴۲]', 'That is because Allah, He is the Truth, and that which they invoke besides Him is AlBatil (falsehood, Satan and all other false deities), and that Allah, He is the Most High, the Most Great.', 'That is because Allah is the only Real One and what they invoke other than Him is false and Allah is the High, the Great.'),
(3500, 31, 31, 4, 13, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'اَلَمۡ تَرَ اَنَّ الۡفُلۡکَ تَجۡرِیۡ فِی الۡبَحۡرِ بِنِعۡمَتِ اللّٰہِ  لِیُرِیَکُمۡ مِّنۡ  اٰیٰتِہٖ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیٰتٍ  لِّکُلِّ  صَبَّارٍ  شَکُوۡرٍ ﴿۳۱﴾', 'کیا تم نے نہیں دیکھا کہ اللہ ہی کی مہربانی سے کشتیاں سمندر میں چلتی ہیں۔ تاکہ وہ تمکو اپنی کچھ نشانیاں دکھائے۔ بیشک اس میں ہر صبر کرنے والے شکر کرنے والے کے لئے نشانیاں ہیں۔', 'تو نے نہ دیکھا کہ جہاز چلتے ہیں سمندر میں اللہ کی نعمت لے کر تاکہ دکھلائے تمکو کچھ اپنی قدرتیں [۴۳] البتہ اس میں نشانیاں ہیں ہر ایک تحمل کرنے والے احسان ماننے والے کے واسطے [۴۴]', 'See you not that the ships sail through the sea by Allahs Grace? that He may show you of His Signs? Verily, in this are signs for every patient, grateful (person).', 'Did you not see that the ships sail through the sea by the grace of Allah, so that He shows you some of His signs? In that, indeed, there are signs for every man of patience and gratitude.'),
(3501, 31, 32, 4, 13, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'وَ اِذَا غَشِیَہُمۡ مَّوۡجٌ کَالظُّلَلِ دَعَوُا اللّٰہَ مُخۡلِصِیۡنَ لَہُ الدِّیۡنَ ۬ۚ فَلَمَّا نَجّٰہُمۡ اِلَی الۡبَرِّ فَمِنۡہُمۡ مُّقۡتَصِدٌ ؕ وَ مَا یَجۡحَدُ بِاٰیٰتِنَاۤ  اِلَّا  کُلُّ  خَتَّارٍ  کَفُوۡرٍ ﴿۳۲﴾', 'اور جب ان پر سمندر کی لہریں سائبانوں کی طرح چھا جاتی ہیں تو اللہ کو پکارنے اور خالص اسکی عبادت کرنے لگتے ہیں پھر جب وہ انکو نجات دے کر خشکی پر پہنچا دیتا ہے تو چند ہی لوگ انصاف پر قائم رہتے ہیں۔ اور ہماری نشانیوں سے وہی انکار کرتے ہیں جو عہد شکن ہیں ناشکرے ہیں۔', 'اور جب سر پر آئے انکے موج جیسے بادل پکارنے لگیں اللہ کو خالص کر کر اسی کے لیے بندگی [۴۵] پھر جب بچا دیا انکو جنگل کی طرف تو کوئی ہوتا ہے ان میں بیچ کی چال پر [۴۶] اور منکر وہی ہوتے ہیں ہماری قدرتوں سے جو قول کے جھوٹے ہیں حق نہ ماننے والے [۴۷]', 'And when a wave covers them like shades (i.e. like clouds or the mountains of seawater), they invoke Allah, making their invocations for Him only. But when He brings them safe to land, there are among them those that stop in the middle, between (Belief and disbelief). But none denies Our Signs except every perfidious ungrateful.', 'And when they are covered by waves like canopies, they pray to Allah, having faith exclusively in Him. Then, once He brings them safe to the land, some of them remain balanced, (while others turn ungrateful by denying Allah’s signs.) And no one denies Our signs except every ungrateful traitor.'),
(3502, 31, 33, 4, 13, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'یٰۤاَیُّہَا النَّاسُ اتَّقُوۡا رَبَّکُمۡ  وَ اخۡشَوۡا یَوۡمًا  لَّا یَجۡزِیۡ وَالِدٌ عَنۡ وَّلَدِہٖ ۫ وَ لَا مَوۡلُوۡدٌ  ہُوَ  جَازٍ عَنۡ وَّالِدِہٖ شَیۡئًا ؕ اِنَّ وَعۡدَ اللّٰہِ حَقٌّ فَلَا تَغُرَّنَّکُمُ الۡحَیٰوۃُ الدُّنۡیَا ٝ وَ لَا یَغُرَّنَّکُمۡ  بِاللّٰہِ الۡغَرُوۡرُ ﴿۳۳﴾', 'لوگو اپنے پروردگار سے ڈرو اور اس دن کا خوف کرو کہ نہ تو باپ اپنے بیٹے کے کچھ کام آئے۔ اور نہ بیٹا باپ کے کچھ کام آ سکے۔ بیشک اللہ کا وعدہ سچا ہے پس دنیا کی زندگی تم کو دھوکے میں نہ ڈال دے۔ اور نہ وہ بڑا فریب دینے والا شیطان تمہیں اللہ کے بارے میں کسی طرح کا فریب دے۔', 'اے لوگوں بچتے ہو اپنے رب سے اور ڈرو اس دن سے کہ کام نہ آئے کوئی باپ اپن بیٹے کے بدلے اور نہ کوئی بیٹا ہو جو کام آئے اپنے باپ کی جگہ کچھ بھی [۴۸] بیشک اللہ کا وعدہ ٹھیک ہے سو تم کو نہ بہکائے دنیا کی زندگانی اور نہ دھوکا دے تم کو اللہ کے نام سے وہ دغاباز [۴۹]', 'O mankind! Be afraid of your Lord (by keeping your duty to Him and avoiding all evil), and fear a Day when no father can avail aught for his son, nor a son avail aught for his father. Verily, the Promise of Allah is true, let not then this (worldly) present life deceive you, nor let the chief deceiver (Satan) deceive you about Allah.', 'O people, fear your Lord and fear a day when no father will help his son, nor will a son be helpful to his father at all. Surely, the promise of Allah is true. So, the worldly life must not deceive you, nor should you ever be deceived about Allah by the Deceiver.'),
(3503, 31, 34, 4, 13, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'لقمٰن', 'اِنَّ اللّٰہَ عِنۡدَہٗ  عِلۡمُ  السَّاعَۃِ ۚ وَ  یُنَزِّلُ الۡغَیۡثَ ۚ وَ یَعۡلَمُ مَا فِی الۡاَرۡحَامِ ؕ وَ مَا تَدۡرِیۡ نَفۡسٌ مَّاذَا تَکۡسِبُ غَدًا ؕ وَ مَا تَدۡرِیۡ نَفۡسٌۢ بِاَیِّ  اَرۡضٍ تَمُوۡتُ ؕ اِنَّ  اللّٰہَ عَلِیۡمٌ خَبِیۡرٌ ﴿٪۳۴﴾', 'اللہ ہی کو قیامت کا علم ہے اور وہی مینہ برساتا ہے۔ اور وہی حاملہ کے پیٹ کی چیزوں کو جانتا ہے اور کوئی شخص نہیں جانتا کہ وہ کل کیا کام کرے گا۔ اور کوئی شخص نہیں جانتا کہ کس سرزمین میں اسے موت آئے گی بیشک اللہ ہی جاننے والا ہے اور خبردار ہے۔', 'بیشک اللہ کے پاس ہے قیامت کی خبر اور اتارتا ہے مینہ اور جانتا ہے جو کچھ ہے ماں کے پیٹ میں اور کسی جی کو معلوم نہیں کہ کل کو کیا کرے گا اور کسی جی کو خبر نہیں کہ کس زمین میں مرے گا تحقیق اللہ سب کچھ جاننے  والا خبردار ہے [۵۰]', 'Verily, Allah! With Him (Alone) is the knowledge of the Hour, He sends down the rain, and knows that which is in the wombs. No person knows what he will earn tomorrow, and no person knows in what land he will die. Verily, Allah is AllKnower, AllAware (of things).', 'Surely, it is Allah with whom rests the knowledge of the Hour; and He sends down the rain, and He knows what is in the wombs. No one knows what he will earn tomorrow, and no one knows in which land he will die. Surely, Allah is All Knowing, All Aware.'),
(3504, 32, 1, 1, 14, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'الٓـمّٓ ۚ﴿۱﴾', 'الٓم۔', 'الٓم۔', 'AlifLamMeem. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings.)', 'Alif Lām Mīm.'),
(3505, 32, 2, 1, 14, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'تَنۡزِیۡلُ الۡکِتٰبِ لَا رَیۡبَ فِیۡہِ مِنۡ رَّبِّ الۡعٰلَمِیۡنَ ؕ﴿۲﴾', 'اس میں کچھ شک نہیں کہ اس کتاب کا نازل کیا جانا تمام جہانوں کے پروردگار کی طرف سے ہے۔', 'اتارنا کتاب کا اس میں کچھ دھوکا نہیں پروردگار عالم کی طرف سے ہے [۱]', 'The revelation of the Book (this Quran) is from the Lord of the Alameen (mankind, jinns and all that exists) in which there is not doubt!', '(This) revelation of the Book - in which there is no doubt - is from the Lord of the worlds.'),
(3506, 32, 3, 1, 14, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'اَمۡ  یَقُوۡلُوۡنَ افۡتَرٰىہُ ۚ بَلۡ ہُوَ  الۡحَقُّ مِنۡ رَّبِّکَ لِتُنۡذِرَ قَوۡمًا مَّاۤ  اَتٰہُمۡ  مِّنۡ نَّذِیۡرٍ مِّنۡ قَبۡلِکَ لَعَلَّہُمۡ  یَہۡتَدُوۡنَ ﴿۳﴾', 'کیا یہ لوگ یہ کہتے ہیں کہ پیغمبر نے اسکو ازخود بنا لیا ہے نہیں بلکہ وہ تمہارے پروردگار کی طرف سے برحق ہے تاکہ تم ان لوگوں کو ہدایت کرو جنکے پاس تم سے پہلے کوئی ہدایت کرنے والا نہیں آیا تاکہ یہ رستے پر چلیں۔', 'کیا کہتے ہیں کہ یہ جھوٹ باندھ لایا ہے کوئی نہیں وہ ٹھیک ہے تیرے رب کی طرف سے تاکہ تو ڈر سنا دے ان لوگوں کو جن کے پاس نہیں آیا کوئی ڈرانے والا تجھ سے پہلے تاکہ وہ راہ پر آئیں [۲]', 'Or say they: \"He (Muhammad SAW) has fabricated it?\" Nay, it is the truth from your Lord, that you may warn a people to whom no warner has come before you (O Muhammad SAW), in order that they may be guided.', 'Is it that they say, “He has fabricated it.”? No, it is the truth from your Lord, so that you (O prophet,) may warn a people to whom no warner has come before you; may be they take the right path.'),
(3507, 32, 4, 1, 14, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'اَللّٰہُ الَّذِیۡ خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ وَ مَا بَیۡنَہُمَا فِیۡ سِتَّۃِ  اَیَّامٍ ثُمَّ  اسۡتَوٰی عَلَی الۡعَرۡشِ ؕ مَا لَکُمۡ مِّنۡ دُوۡنِہٖ مِنۡ وَّلِیٍّ  وَّ لَا شَفِیۡعٍ ؕ اَفَلَا تَتَذَکَّرُوۡنَ ﴿۴﴾', 'اللہ ہی تو ہے جس نے آسمانوں اور زمین کو اور جو چیزیں ان دونوں میں ہیں سب کو چھ دن میں پیدا کیا پھر عرش پر جلوہ افروز ہوا۔ اسکے سوا تمہارا نہ کوئی دوست ہے اور نہ سفارش کرنے والا۔ کیا تم نصیحت حاصل نہیں کرتے؟', 'اللہ ہے جس نے بنائے آسمان اور زمین اور جو کچھ انکے بیچ میں ہے چھ دن کے اندر پھر قائم ہوا عرش پر [۳] کوئی نہیں تمہارا اس کے سوائے حمایتی اور نہ سفارشی پھر  تم کیا دھیان نہیں کرتے [۴]', 'Allah it is He Who has created the heavens and the earth, and all that is between them in six Days. Then He Istawa (rose over) the Throne (in a manner that suits His Majesty). You (mankind) have none, besides Him, as a Walee (protector or helper etc.) or an intercessor. Will you not then remember (or be admonished)?', 'Allah is the One who created the heavens and the earth and all that is between them in six days, then He positioned Himself on the Throne. Other than Him, there is neither a guardian for you, nor an intercessor. Would you then not observe the advice?'),
(3508, 32, 5, 1, 14, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'یُدَبِّرُ الۡاَمۡرَ مِنَ السَّمَآءِ  اِلَی الۡاَرۡضِ ثُمَّ یَعۡرُجُ  اِلَیۡہِ  فِیۡ یَوۡمٍ کَانَ مِقۡدَارُہٗۤ اَلۡفَ سَنَۃٍ  مِّمَّا تَعُدُّوۡنَ ﴿۵﴾', 'وہی آسمان سے زمین تک کے ہر کام کا انتظام کرتا ہے۔ پھر ہر کام ایک روز جسکی مقدار تمہارے شمار کے مطابق ہزار برس ہو گی۔ اسکی طرف رجوع کرے گا۔', 'تدبیر سے اتارتا ہے ہر کام آسمان سے زمین تک پھر چڑھتا ہے وہ کام اس کی طرف ایک دن میں جس کا پیمانہ ہزار برس کا ہے تمہاری گنتی میں [۵]', 'He arranges (every) affair from the heavens to the earth, then it (affair) will go up to Him, in one Day, the space whereof is a thousand years of your reckoning (i.e. reckoning of our present worlds time).', 'He manages (every) matter from the sky to the earth, then it (every matter) will ascend to Him in a day the measure of which is one thousand years according to the way you count.'),
(3509, 32, 6, 1, 14, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'ذٰلِکَ عٰلِمُ الۡغَیۡبِ وَ الشَّہَادَۃِ  الۡعَزِیۡزُ الرَّحِیۡمُ ۙ﴿۶﴾', 'اسی شان کا ہے وہ خالق جو پوشیدہ اور ظاہر کا جاننے والا ہے غالب ہے بڑا مہربان ہے۔', 'یہ ہی جاننے والا چھپے اور کھلے کا زبردست رحم والا [۶]', 'That is He, the AllKnower of the unseen and the seen, the AllMighty, the Most Merciful.', 'That One is the All-knower of the Unseen and the seen, the All-Mighty, the Very-Merciful,'),
(3510, 32, 7, 1, 14, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'الَّذِیۡۤ  اَحۡسَنَ کُلَّ شَیۡءٍ خَلَقَہٗ  وَ بَدَاَ خَلۡقَ الۡاِنۡسَانِ مِنۡ طِیۡنٍ ۚ﴿۷﴾', 'وہی جس نے ہرچیز کو بہت اچھی طرح بنایا یعنی اسکو پیدا کیا۔ اور انسان کی پیدائش کو مٹی سے شروع کیا۔', 'جس نے خوب بنائی جو  چیز  بنائی اور شروع کی انسان کی پیدائش ایک گارے سے', 'Who made everything He has created good, and He began the creation of man from clay.', 'who made well whatever He created, and started the creation of man from clay.'),
(3511, 32, 8, 1, 14, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'ثُمَّ جَعَلَ نَسۡلَہٗ  مِنۡ سُلٰلَۃٍ مِّنۡ مَّآءٍ مَّہِیۡنٍ ۚ﴿۸﴾', 'پھر اسکی نسل ایک قسم کے خلاصے سے یعنی حقیر پانی سے بنائی۔', 'پھر بنائی اسکی اولاد نچڑے ہوئے بےقدر پانی سے [۷]', 'Then He made his offspring from semen of worthless water (male and female sexual discharge).', 'Then He made his progeny from a drop of semen, from despised water.'),
(3512, 32, 9, 1, 14, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'ثُمَّ سَوّٰىہُ  وَ نَفَخَ فِیۡہِ مِنۡ رُّوۡحِہٖ وَ جَعَلَ لَکُمُ السَّمۡعَ وَ الۡاَبۡصَارَ وَ الۡاَفۡـِٕدَۃَ ؕ قَلِیۡلًا  مَّا  تَشۡکُرُوۡنَ ﴿۹﴾', 'پھر اسکو درست کیا پھر اس میں اپنی طرف سے روح پھونکی اور تمہارے کان اور آنکھیں اور دل بنائے مگر تم بہت کم شکر کرتے ہو۔', 'پھر اس کو برابر کیا [۸] اور پھونکی اس میں اپنی ایک جان [۹] اور بنا دیے تمہارے لیے کان اور آنکھیں اور دل تم بہت تھوڑا شکر کرتے ہو [۱۰]', 'Then He fashioned him in due proportion, and breathed into him the soul (created by Allah for that person), and He gave you hearing (ears), sight (eyes) and hearts. Little is the thanks you give!', 'Then He gave him a proportioned shape, and breathed into him of His spirit. And He granted you the (power of) hearing and the eyes and the hearts. Little you give thanks.'),
(3513, 32, 10, 1, 14, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'وَ قَالُوۡۤا ءَ اِذَا ضَلَلۡنَا فِی الۡاَرۡضِ ءَ اِنَّا لَفِیۡ خَلۡقٍ جَدِیۡدٍ ۬ؕ بَلۡ ہُمۡ بِلِقَآیِٔ رَبِّہِمۡ کٰفِرُوۡنَ ﴿۱۰﴾', 'اور کہنے لگے کہ جب ہم زمین میں ملیا میٹ ہو جائیں گے تو کیا ازسرنو پیدا ہوں گے۔ حقیقت یہ ہے کہ یہ لوگ اپنے پروردگار کے سامنے جانے ہی کے قائل نہیں۔', 'اور کہتے ہیں کیا جب ہم رل گئے زمین میں کیا ہم کو نیا بننا ہے کچھ نہیں وہ اپنے رب کی ملاقات سے منکر ہیں [۱۱]', 'And they say: \"When we are (dead and become) lost in the earth, shall we indeed be recreated anew?\" Nay, but they deny the Meeting with their Lord!', 'And they said, “Is it that when we disappear in the earth-is it that we really come into a new creation?” Rather they are ones who deny the meeting with their Lord.'),
(3514, 32, 11, 1, 14, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'قُلۡ یَتَوَفّٰىکُمۡ مَّلَکُ الۡمَوۡتِ الَّذِیۡ وُکِّلَ بِکُمۡ  ثُمَّ   اِلٰی رَبِّکُمۡ تُرۡجَعُوۡنَ ﴿٪۱۱﴾', 'کہدو کہ موت کا فرشتہ جو تم پر مقرر کیا گیا ہے تمہاری روحیں قبض کر لیتا ہے پھر تم اپنے پروردگار کی طرف لوٹائے جاؤ گے۔', 'تو کہہ قبض کر لیتا ہے تم کو فرشتہ موت کا جو تم پر مقرر ہے پھر اپنے رب کی طرف پھر جاؤ گے [۱۲]', 'Say: \"The angel of death, who is set over you, will take your souls, then you shall be brought to your Lord.\"', 'Say, “The angel of death who has been assigned for you will take your soul in full, then you will be brought back to your Lord.”'),
(3515, 32, 12, 2, 15, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'وَ لَوۡ تَرٰۤی  اِذِ الۡمُجۡرِمُوۡنَ نَاکِسُوۡا رُءُوۡسِہِمۡ عِنۡدَ رَبِّہِمۡ ؕ رَبَّنَاۤ  اَبۡصَرۡنَا وَ سَمِعۡنَا فَارۡجِعۡنَا نَعۡمَلۡ صَالِحًا  اِنَّا مُوۡقِنُوۡنَ ﴿۱۲﴾', 'اور تم تعجب کرو جب دیکھو کہ گناہگار اپنے پروردگار کے سامنے سر جھکائے ہوں گے اور کہیں گے کہ اے ہمارے پروردگار ہم نے دیکھ لیا اور سن لیا تو ہمکو دنیا میں واپس بھیج دے کہ نیک عمل کریں۔ بیشک ہم یقین کرنے والے ہیں۔', 'اور کبھی تو دیکھے جس وقت کہ منکر سر ڈالے ہوئے ہوں گے اپنے رب کے سامنے [۱۳] اے رب ہم نے دیکھ لیا اور سن لیا اب ہم کو بھیج دے کہ ہم کریں بھلے کام ہم کو یقین آ گیا [۱۴]', 'And if you only could see when the Mujrimoon (criminals, disbelievers, polytheists, sinners, etc.) shall hang their heads before their Lord (saying): \"Our Lord! We have now seen and heard, so send us back (to the world), we will do righteous good deeds. Verily! We now believe with certainty.\"', 'And (you will wonder) if you see the sinners hanging their heads before their Lord (and saying,) “Our Lord, we have now seen and heard, so send us back, and we will do righteous deeds. Surely, (now) we are believers.”'),
(3516, 32, 13, 2, 15, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'وَ لَوۡ شِئۡنَا لَاٰتَیۡنَا کُلَّ نَفۡسٍ ہُدٰىہَا وَ لٰکِنۡ حَقَّ الۡقَوۡلُ مِنِّیۡ لَاَمۡلَـَٔنَّ جَہَنَّمَ مِنَ الۡجِنَّۃِ  وَ النَّاسِ اَجۡمَعِیۡنَ ﴿۱۳﴾', 'اور اگر ہم چاہتے تو ہر شخص کو ہدایت دے دیتے۔ لیکن میری طرف سے یہ بات قرار پاچکی ہے کہ میں دوزخ کو جنوں اور انسانوں سب سے بھر دوں گا۔', 'اور اگر ہم چاہتے تو سجھا دیتے ہر جی کو اس کی راہ لیکن ٹھیک پڑ چکی میری کہی بات کہ مجھ کو بھرنی ہے دوزخ جنوں سے اور آدمیوں سے اکھٹے [۱۵]', 'And if We had willed, surely! We would have given every person his guidance, but the Word from Me took effect (about evildoers), that I will fill Hell with jinn and mankind together.', 'And if We had so willed, We would have led everybody to his right path (by force), but the word from Me had come to pass: “I will certainly fill the Jahannam with jinn and human beings together.”'),
(3517, 32, 14, 2, 15, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'فَذُوۡقُوۡا بِمَا نَسِیۡتُمۡ  لِقَآءَ  یَوۡمِکُمۡ  ہٰذَا ۚ اِنَّا نَسِیۡنٰکُمۡ وَ ذُوۡقُوۡا عَذَابَ الۡخُلۡدِ  بِمَا کُنۡتُمۡ تَعۡمَلُوۡنَ ﴿۱۴﴾', 'سو اب آگ کے مزے چکھو اس لئے کہ تم نے اس دن کے آنے کو بھلا رکھا تھا آج ہم نے بھی تمہیں بھلا دیا ہے اور جو کام تم کرتے تھے انکی سزا میں ہمیشہ کے عذاب کے مزے چکھتے رہو۔', 'سو اب چکھو  مزہ جیسے تم نے بھلا دیا تھا اس اپنے دن کے ملنے کو ہم نے بھی بھلا دیا تم کو [۱۶] اور چکھو عذاب سدا کا عوض اپنے کیے کا', 'Then taste you (the torment of the Fire) because of your forgetting the Meeting of this Day of yours, (and) surely! We too will forget you, so taste you the abiding torment for what you used to do.', 'So, have a taste, because you had forgotten the meeting of this day of yours. We have forgotten you; and taste the eternal punishment for what you used to do.'),
(3518, 32, 15, 2, 15, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'اِنَّمَا یُؤۡمِنُ بِاٰیٰتِنَا الَّذِیۡنَ  اِذَا  ذُکِّرُوۡا بِہَا خَرُّوۡا  سُجَّدًا  وَّ سَبَّحُوۡا بِحَمۡدِ رَبِّہِمۡ وَ  ہُمۡ  لَا  یَسۡتَکۡبِرُوۡنَ ﴿ٛ۱۵﴾', 'ہماری آیتوں پر تو وہی لوگ ایمان لاتے ہیں کہ جب انکو انکے ذریعے نصیحت کی جاتی ہے تو سجدے میں گر پڑتے اور اپنے پروردگار کی تعریف کے ساتھ تسبیح کرتے ہیں اور غرور نہیں کرتے۔', 'ہماری باتوں کو  وہی مانتے ہیں کہ جب ان کو سمجھائے ان سے گر پڑیں سجدہ کر کر اور پاک ذات کو یاد کریں اپنے رب کی خوبیوں کے ساتھ اور وہ بڑائی نہیں کرتے [۱۷]', 'Only those believe in Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), who, when they are reminded of them fall down prostrate, and glorify the Praises of their Lord, and they are not proud.', 'Only those people believe in Our verses who, when they are reminded of them, fall in prostration and pronounce the purity and praise of their Lord, and who do not wax proud.'),
(3519, 32, 16, 2, 15, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'تَتَجَافٰی جُنُوۡبُہُمۡ عَنِ الۡمَضَاجِعِ یَدۡعُوۡنَ رَبَّہُمۡ خَوۡفًا وَّ طَمَعًا ۫ وَّ مِمَّا رَزَقۡنٰہُمۡ  یُنۡفِقُوۡنَ ﴿۱۶﴾', 'انکے پہلو بچھونوں سے الگ رہتے ہیں اس حال میں کہ وہ اپنے پروردگار کو خوف اور امید سے پکارتے اور جو کچھ ہم نے انکو دیا ہے اس میں سے خرچ کرتے ہیں۔', 'جدا رہتی ہیں ان کی کروٹیں اپنے سونے کی جگہ سے [۱۸] پکارتے ہیں اپنے رب کو ڈر سے اور لالچ سے [۱۹] اور ہمارا دیا ہوا کچھ خرچ کرتے ہیں', 'Their sides forsake their beds, to invoke their Lord in fear and hope, and they spend (charity in Allahs Cause) out of what We have bestowed on them.', 'Their sides remain apart from their beds. They call their Lord with fear and hope, and spend (in charity) out of what We have given to them.'),
(3520, 32, 17, 2, 15, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'فَلَا تَعۡلَمُ نَفۡسٌ مَّاۤ  اُخۡفِیَ لَہُمۡ مِّنۡ قُرَّۃِ اَعۡیُنٍ ۚ جَزَآءًۢ  بِمَا  کَانُوۡا  یَعۡمَلُوۡنَ ﴿۱۷﴾', 'سو کوئی شخص نہیں جانتا کہ انکے لئے کیسی آنکھوں کی ٹھنڈک چھپا کر رکھی گئ ہے۔ یہ ان اعمال کا صلہ ہے جو وہ کرتے تھے۔', 'سو کسی جی کو معلوم نہیں جو چھپا دھری ہے انکے  واسطے آنکھوں کی ٹھنڈک بدلا اس کو جو کرتے تھے [۲۰]', 'No person knows what is kept hidden for them of joy as a reward for what they used to do.', 'So, no one knows the delight of eyes that has been reserved for them in secret, as a reward of what they used to do.'),
(3521, 32, 18, 2, 15, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'اَفَمَنۡ کَانَ مُؤۡمِنًا کَمَنۡ کَانَ فَاسِقًا ؕؔ لَا  یَسۡتَوٗنَ ﴿۱۸﴾؃', 'بھلا جو مومن ہو وہ اس شخص کی طرح ہو سکتا ہے جو نافرمان ہو؟ دونوں برابر نہیں ہو سکتے۔', 'بھلا ایک جو ہے ایمان پر برابر ہے اسکے جو نافرمان ہے نہیں برابر ہوتے [۲۱]', 'Is then he who is a believer like him who is Fasiq (disbeliever and disobedient to Allah)? Not equal are they.', 'So, can one who is a believer become like one who is a sinner? They cannot become equal.'),
(3522, 32, 19, 2, 15, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'اَمَّا الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ فَلَہُمۡ جَنّٰتُ الۡمَاۡوٰی ۫ نُزُلًۢا بِمَا کَانُوۡا یَعۡمَلُوۡنَ ﴿۱۹﴾', 'جو لوگ ایمان لائے اور نیک عمل کرتے رہے انکے رہنے کے لئے باغ ہیں۔ یہ مہمانی ان کاموں کی جزا ہے جو وہ کرتے تھے۔', 'سو وہ لوگ جو یقین لائے اور کیے کام بھلے تو ان کے لیے باغ ہیں رہنے کے مہمانی ان کاموں کی وجہ سے جو کرتے تھے [۲۲]', 'As for those who believe (in the Oneness of Allah Islamic Monotheism) and do righteous good deeds, for them are Gardens (Paradise) as an entertainment, for what they used to do.', 'As for those who believe and do righteous deeds, for them there are gardens to dwell, as an honorable hospitality for what they used to do.'),
(3523, 32, 20, 2, 15, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'وَ اَمَّا الَّذِیۡنَ فَسَقُوۡا فَمَاۡوٰىہُمُ النَّارُ ؕ کُلَّمَاۤ  اَرَادُوۡۤا اَنۡ یَّخۡرُجُوۡا مِنۡہَاۤ اُعِیۡدُوۡا فِیۡہَا وَ قِیۡلَ لَہُمۡ ذُوۡقُوۡا عَذَابَ النَّارِ الَّذِیۡ  کُنۡتُمۡ بِہٖ تُکَذِّبُوۡنَ ﴿۲۰﴾', 'اور جنہوں نے نافرمانی کی انکے رہنے کے لئے دوزخ ہے جب چاہیں گے کہ اس میں سے نکل جائیں تو اس میں لوٹا دیئے جائیں گے۔ اور ان سے کہا جائے گا کہ جس دوزخ کے عذاب کو تم جھوٹ سمجھتے تھے اسکے مزے چکھو۔', 'اور وہ لوگ جو نافرمان ہوئے سو انکا گھر ہے آگ جب چاہیں کہ نکل پڑیں اس میں سے الٹا دیے جائیں پھر اسی میں اور کہیں ان کو چکھو آگ کا عذاب جس کو تم جھٹلایا کرتے تھے [۲۳]', 'And as for those who are Fasiqoon (disbelievers and disobedient to Allah), their abode will be the Fire, every time they wish to get away therefrom, they will be put back thereto, and it will be said to them: \"Taste you the torment of the Fire which you used to deny.\"', 'And the ones who disobeyed, their abode is the Fire. Whenever they wish to come out from it, they will be turned back into it, and it will be said to them, “Taste the punishment of fire that you used to deny.”'),
(3524, 32, 21, 2, 15, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'وَ لَنُذِیۡقَنَّہُمۡ مِّنَ الۡعَذَابِ الۡاَدۡنٰی  دُوۡنَ الۡعَذَابِ  الۡاَکۡبَرِ  لَعَلَّہُمۡ  یَرۡجِعُوۡنَ ﴿۲۱﴾', 'اور ہم انکو قیامت کے بڑے عذاب سے پہلے دنیا کے عذاب کا بھی مزہ چکھائیں گے شاید وہ ہماری طرف لوٹ آئیں۔', 'اور البتہ چکھائیں گے ہم ان کو تھوڑا عذاب ورے اس بڑے عذاب سے تاکہ وہ پھر آئیں [۲۴]', 'And verily, We will make them taste of the near torment (i.e. the torment in the life of this world, i.e. disasters, calamities, etc.) prior to the supreme torment (in the Hereafter), in order that they may (repent and) return (i.e. accept Islam).', 'And We will certainly make them taste the nearer punishment before the greater punishment, so that they may return.'),
(3525, 32, 22, 2, 15, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'وَ مَنۡ  اَظۡلَمُ مِمَّنۡ ذُکِّرَ بِاٰیٰتِ رَبِّہٖ ثُمَّ اَعۡرَضَ عَنۡہَا ؕ اِنَّا مِنَ الۡمُجۡرِمِیۡنَ مُنۡتَقِمُوۡنَ ﴿٪۲۲﴾', 'اور اس شخص سے بڑھ کر ظالم کون جسکو اس کے پروردگار کی آیتوں سے نصیحت کی جائے تو وہ ان سے منہ پھیر لے ہم گناہگاروں سے ضرور بدلہ لینے والے ہیں۔', 'اور کون بے انصاف زیادہ اس سے جس کو سمجھایا گیا اسکے رب کی باتوں سے پھر ان سے منہ موڑ گیا [۲۵] مقرر ہم کو ان گنہگاروں سے بدلا لینا ہے [۲۶]', 'And who does more wrong than he who is reminded of the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of his Lord, then he turns aside therefrom? Verily, We shall exact retribution from the Mujrimoon (criminals, disbelievers, polytheists, sinners, etc.).', 'And who is more unjust than the one who was reminded of the verses of his Lord, then he turned away from them. Surely, We have to take vengeance upon the sinners.'),
(3526, 32, 23, 3, 16, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'وَ لَقَدۡ اٰتَیۡنَا مُوۡسَی الۡکِتٰبَ فَلَا تَکُنۡ فِیۡ مِرۡیَۃٍ  مِّنۡ لِّقَآئِہٖ وَ جَعَلۡنٰہُ ہُدًی  لِّبَنِیۡۤ   اِسۡرَآءِیۡلَ ﴿ۚ۲۳﴾', 'اور ہم نے موسٰی کو کتاب دی تو تم ان سے ملاقات ہونے سے متعلق شک میں نہ ہونا اور ہم نے اس کتاب کو بنی اسرائیل کے لئے ذریعہ ہدایت بنایا تھا۔', 'اور ہم نے دی ہے موسٰی کو کتاب سو تو مت رہ دھوکے میں اس کے ملنے سے [۲۷] اور کیا ہم نے اس کو ہدایت بنی اسرائیل کے واسطے', 'And indeed We gave Moosa (Moses) the Scripture (the Taurat (Torah)). So be not you in doubt of meeting him (i.e.when you met Moosa (Moses) during the night of AlIsra and AlMiraj over the heavens). And We made it (the Taurat (Torah)) a guide to the Children of Israel.', 'It is a fact that We gave the Book to Mūsā. So be not in doubt about receiving it, and We made it a guidance for the children of Isrā’īl .'),
(3527, 32, 24, 3, 16, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'وَ جَعَلۡنَا مِنۡہُمۡ  اَئِمَّۃً  یَّہۡدُوۡنَ  بِاَمۡرِنَا لَمَّا صَبَرُوۡا ۟ؕ  وَ کَانُوۡا بِاٰیٰتِنَا یُوۡقِنُوۡنَ ﴿۲۴﴾', 'اور ان میں سے ہم نے پیشوا بنائے تھے جو ہمارے حکم سے ہدایت کیا کرتے تھے۔ جب کہ وہ صبر بھی کرتے تھے۔ اور وہ ہماری آیتوں پر یقین رکھتے تھے۔', 'اور کیے ہم نے ان میں پیشوا جو راہ چلاتے تھے ہمارے حکم سے جب وہ صبر کرتے رہے [۲۸] اور رہے ہماری باتوں پر یقین کرتے [۲۹]', 'And We made from among them (Children of Israel), leaders, giving guidance under Our Command, when they were patient and used to believe with certainty in Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.).', 'And We appointed leaders from among them who guided (people) under Our command, when they observed patience, and kept firm belief in Our verses.'),
(3528, 32, 25, 3, 16, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'اِنَّ  رَبَّکَ ہُوَ یَفۡصِلُ بَیۡنَہُمۡ یَوۡمَ الۡقِیٰمَۃِ  فِیۡمَا  کَانُوۡا فِیۡہِ یَخۡتَلِفُوۡنَ ﴿۲۵﴾', 'بلاشبہ تمہارا پروردگار ہی ان میں جن باتوں میں وہ اختلاف کرتے تھے۔ قیامت کے روز فیصلہ کر دے گا۔', 'تیرا رب جو ہے وہی فیصلہ کرے گا ان میں دن قیامت کے جس بات میں کہ وہ اختلاف کرتے ہیں [۳۰]', 'Verily, your Lord will judge between them on the Day of Resurrection, concerning that wherein they used to differ.', 'Surely, your Lord will judge between them on the Day of Judgment in what they used to differ.'),
(3529, 32, 26, 3, 16, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'اَوَ لَمۡ یَہۡدِ لَہُمۡ کَمۡ  اَہۡلَکۡنَا مِنۡ قَبۡلِہِمۡ مِّنَ الۡقُرُوۡنِ یَمۡشُوۡنَ فِیۡ مَسٰکِنِہِمۡ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیٰتٍ ؕ اَفَلَا یَسۡمَعُوۡنَ ﴿۲۶﴾', 'کیا انکو اس امر سے ہدایت نہ ہوئی کہ ہم نے ان سے پہلے بہت سی امتوں کو جنکے رہنے کے مقامات میں یہ لوگ چلتے پھرتے ہیں ہلاک کر دیا۔ بیشک اس میں نشانیاں ہیں۔ تو یہ سنتے کیوں نہیں۔', 'کیا ان کو راہ نہ سوجھی اس بات سے کہ کتنی غارت کر ڈالیں ہم نے ان سے پہلے جماعتیں کہ پھرتے ہیں یہ ان کے گھروں میں اس میں بہت نشانیاں ہیں کیا وہ سنتے نہیں [۳۱]', 'Is it not a guidance for them, how many generations We have destroyed before them in whose dwellings they do walk about? Verily, therein indeed are signs. Would they not then listen?', 'Has it not been a source of guidance for them as to how many generations We have destroyed before them who used to walk in their dwellings? Surely in this there are signs. So, do they not listen?'),
(3530, 32, 27, 3, 16, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'اَوَ لَمۡ یَرَوۡا اَنَّا نَسُوۡقُ الۡمَآءَ  اِلَی الۡاَرۡضِ الۡجُرُزِ فَنُخۡرِجُ  بِہٖ زَرۡعًا تَاۡکُلُ مِنۡہُ  اَنۡعَامُہُمۡ وَ اَنۡفُسُہُمۡ ؕ اَفَلَا یُبۡصِرُوۡنَ ﴿ؓ۲۷﴾', 'کیا انہوں نے نہیں دیکھا کہ ہم بنجر زمین کی طرف پانی رواں کرتے ہیں پھر اس سے کھیتی پیدا کرتے ہیں جس میں سے انکے چوپائے بھی کھاتے ہیں اور یہ خود بھی کھاتے ہیں تو یہ دیکھتے کیوں نہیں؟', 'یا دیکھا نہیں انہوں نے کہ ہم ہانک دیتے ہیں  پانی کو  ایک زمین چٹیل کی طرف [۳۲] پھر ہم نکالتے ہیں اس سے کھیتی کہ کھاتے ہیں اس میں انکے چوپائے اور خود وہ بھی پھر کیا دیکھتے نہیں [۳۳]', 'Have they not seen how We drive water (rain clouds) to the dry land without any vegetation, and therewith bring forth crops providing food for their cattle and themselves? Will they not then see?', 'Have they not seen that We drive water to the dry land, then We bring forth crops thereby from which their cattle and they themselves have food? So, do they not perceive?'),
(3531, 32, 28, 3, 16, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'وَ یَقُوۡلُوۡنَ مَتٰی ہٰذَا الۡفَتۡحُ  اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ ﴿۲۸﴾', 'اور کہتے ہیں اگر تم سچے ہو تو یہ فیصلہ کب ہو گا؟', 'اور کہتے ہیں کب ہو گا یہ فیصلہ اگر تم سچے ہو [۳۴]', 'They say: \"When will this AlFath (Decision) be (between us and you, i.e. the Day of Resurrection), if you are telling the truth?\"', 'And they say, “When will this decision take place if you are truthful (in your claim)?”'),
(3532, 32, 29, 3, 16, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'قُلۡ یَوۡمَ الۡفَتۡحِ لَا یَنۡفَعُ الَّذِیۡنَ  کَفَرُوۡۤا اِیۡمَانُہُمۡ  وَ لَا  ہُمۡ  یُنۡظَرُوۡنَ ﴿۲۹﴾', 'کہدو کہ فیصلے کے دن کافروں کو ان کا ایمان لانا کچھ بھی فائدہ نہ دے گا اور نہ انکو مہلت دی جائے گی۔', 'تو کہہ کہ فیصلہ کے دن کام نہ آئے گا منکروں کو انکا ایمان لانا اور نہ ان کو ڈھیل ملے گی [۳۵]', 'Say: \"On the Day of AlFath (Decision), no profit will it be to those who disbelieve if they (then) believe! Nor will they be granted a respite.\"', 'Say, “On the day of decision their belief will not be of any use to disbelievers, nor shall they be given any respite.”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(3533, 32, 30, 3, 16, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'السجدۃ', 'فَاَعۡرِضۡ عَنۡہُمۡ وَ انۡتَظِرۡ  اِنَّہُمۡ مُّنۡتَظِرُوۡنَ ﴿٪۳۰﴾', 'تو ان سے منہ پھیر لو اور انتظار کرو یہ بھی انتظار کر رہے ہیں۔', 'سو تو خیال چھوڑ ان کا اور منتظر رہ وہ بھی منتظر ہیں [۳۶]', 'So turn aside from them (O Muhammad SAW) and await, verily they (too) are awaiting.', 'So, just ignore them (O prophet,) and wait. They (too) are waiting.'),
(3534, 33, 1, 1, 17, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'یٰۤاَیُّہَا النَّبِیُّ اتَّقِ اللّٰہَ وَ لَا تُطِعِ الۡکٰفِرِیۡنَ وَ الۡمُنٰفِقِیۡنَ ؕ اِنَّ اللّٰہَ کَانَ عَلِیۡمًا حَکِیۡمًا ۙ﴿۱﴾', 'اے پیغمبر اللہ سے ڈرتے رہنا اور کافروں اور منافقوں کا کہا نہ ماننا۔ بیشک اللہ جاننے والا ہے حکمت والا ہے۔', 'اے نبی ڈر  اللہ سے  اور کہا نہ مان منکروں کا اور دغا بازوں کا مقرر اللہ ہے سب کچھ جاننے  والا حکمتوں والا', 'O Prophet (Muhammad SAW)! Keep your duty to Allah, and obey not the disbelievers and the hypocrites (i.e., do not follow their advices). Verily! Allah is Ever AllKnower, AllWise.', 'O Prophet, fear Allah and do not obey the disbelievers and the hypocrites. Surely Allah is All-Knowing, All-Wise.'),
(3535, 33, 2, 1, 17, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'وَّ اتَّبِعۡ مَا یُوۡحٰۤی اِلَیۡکَ مِنۡ رَّبِّکَ ؕ اِنَّ اللّٰہَ  کَانَ بِمَا تَعۡمَلُوۡنَ خَبِیۡرًا ۙ﴿۲﴾', 'اور جو کتاب تمکو تمہارے پروردگار کی طرف سے وحی کی جاتی ہے اسی کی پیروی کئے جانا بیشک اللہ تمہارے سب اعمال سے خبردار ہے۔', 'اور چل اسی پر جو حکم آئے تجھ کو تیرے رب کی طرف سے بیشک اللہ تمہارے کام کی خبر رکھتا ہے', 'And follow that which is inspired in you from your Lord. Verily, Allah is WellAcquainted with what you do.', 'Follow what is revealed to you from your Lord. Surely Allah is All-Aware of what you do;'),
(3536, 33, 3, 1, 17, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'وَّ تَوَکَّلۡ عَلَی اللّٰہِ ؕ وَ کَفٰی بِاللّٰہِ وَکِیۡلًا ﴿۳﴾', 'اور اللہ پر بھروسہ رکھنا اور اللہ ہی کارساز کافی ہے۔', 'اور بھروسہ رکھ اللہ پر اور اللہ کافی ہے کام بنانے والا [۱]', 'And put your trust in Allah, and Sufficient is Allah as a Wakeel (Trustee, or Disposer of affairs).', 'and place your trust in Allah. Allah is enough as a guardian.'),
(3537, 33, 4, 1, 17, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'مَا جَعَلَ اللّٰہُ  لِرَجُلٍ مِّنۡ قَلۡبَیۡنِ فِیۡ جَوۡفِہٖ ۚ وَ مَا جَعَلَ  اَزۡوَاجَکُمُ الِّٰٓیۡٔ  تُظٰہِرُوۡنَ مِنۡہُنَّ اُمَّہٰتِکُمۡ ۚ وَ مَا جَعَلَ  اَدۡعِیَآءَکُمۡ  اَبۡنَآءَکُمۡ ؕ ذٰلِکُمۡ قَوۡلُکُمۡ بِاَفۡوَاہِکُمۡ ؕ وَ اللّٰہُ یَقُوۡلُ الۡحَقَّ  وَ ہُوَ  یَہۡدِی  السَّبِیۡلَ ﴿۴﴾', 'اللہ نے کسی آدمی کے پہلو میں دو دل نہیں بنائے اور نہ تمہاری بیویوں کو جنکو تم ماں کہہ بیٹھتے ہو تمہاری ماں بنایا اور نہ تمہارے لے پالکوں کو تمہارے بیٹے بنایا یہ سب تمہارے منہ کی باتیں ہیں۔ اور اللہ تو سچی بات فرماتا ہے اور وہی سیدھا رستہ دکھاتا ہے۔', 'اللہ نے رکھے نہیں کسی مرد کے دو دل اس کے اندر اور نہیں کیا تمہاری جوروؤں کو جن کو ماں کہہ بیٹھے ہو سچی مائیں تمہاری اور نہیں کیا تمہارے لے پالکوں کو تمہارے بیٹے  یہ تمہاری بات ہے اپنے منہ کی اور اللہ کہتا ہے ٹھیک بات اور وہی سجھاتا ہے راہ [۲]', 'Allah has not put for any man two hearts inside his body. Neither has He made your wives whom you declare to be like your mothers backs, your real mothers. (AzZihar is the saying of a husband to his wife, \"You are to me like the back of my mother\" i.e. You are unlawful for me to approach.), nor has He made your adopted sons your real sons. That is but your saying with your mouths. But Allah says the truth, and He guides to the (Right) Way.', 'Allah has not made for any man two hearts in his chest cavity, nor did he make your wives whom you subjected to Zihār, your mothers, nor did he make your adopted sons your (real) sons. That is (merely) a word uttered by your mouths. And Allah says the truth and He shows the (right) way.'),
(3538, 33, 5, 1, 17, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'اُدۡعُوۡہُمۡ لِاٰبَآئِہِمۡ ہُوَ  اَقۡسَطُ عِنۡدَ اللّٰہِ ۚ فَاِنۡ لَّمۡ تَعۡلَمُوۡۤا اٰبَآءَہُمۡ فَاِخۡوَانُکُمۡ فِی الدِّیۡنِ وَ مَوَالِیۡکُمۡ ؕ وَ لَیۡسَ عَلَیۡکُمۡ جُنَاحٌ فِیۡمَاۤ  اَخۡطَاۡتُمۡ بِہٖ  ۙ  وَ لٰکِنۡ مَّا تَعَمَّدَتۡ قُلُوۡبُکُمۡ ؕ وَ  کَانَ اللّٰہُ  غَفُوۡرًا  رَّحِیۡمًا ﴿۵﴾', 'مومنو! منہ بولے بیٹوں کو انکے اصلی باپوں کے نام سے پکارا کرو کہ اللہ کے نزدیک یہی بات درست ہے۔ اگر تمکو انکے باپوں کے نام معلوم نہ ہوں تو دین میں وہ تمہارے بھائی اور دوست ہیں اور جو بات غلطی سے ہو گئ ہو اسکا تم پر کچھ گناہ نہیں لیکن جو قصد دلی سے کرو اس پر مواخذہ ہے اور اللہ بخشنے والا ہے مہربان ہے۔', 'پکارو لے پالکوں کو انکے باپ کی طرف نسبت کر کے  یہی پورا انصاف ہے اللہ کے  یہاں [۳] پھر اگر نہ جانتے ہو ان کے باپ کو تو تمہارے بھائی ہیں دین میں اور رفیق ہیں [۴] اور گناہ نہیں تم پر جس چیز میں چوک جاؤ پر وہ جو دل سے ارادہ کرو اور اللہ ہے بخشنے والا مہربان [۵]', 'Call them (adopted sons) by (the names of) their fathers, that is more just with Allah. But if you know not their fathers (names, call them) your brothers in faith and Mawaleekum (your freed slaves). And there is no sin on you if you make a mistake therein, except in regard to what your hearts deliberately intend. And Allah is Ever OftForgiving, Most Merciful.', 'Call them by (the name of) their (real) fathers; It is more equitable in the sight of Allah. And if you do not know their fathers, then they are your brothers in faith and your friends. There is no sin on you in the mistake you make, but in that which you do with intention of your heart; and Allah is Most-Forgiving, Very-Merciful.'),
(3539, 33, 6, 1, 17, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'اَلنَّبِیُّ  اَوۡلٰی بِالۡمُؤۡمِنِیۡنَ مِنۡ اَنۡفُسِہِمۡ وَ اَزۡوَاجُہٗۤ  اُمَّہٰتُہُمۡ ؕ وَ اُولُوا الۡاَرۡحَامِ بَعۡضُہُمۡ اَوۡلٰی بِبَعۡضٍ فِیۡ کِتٰبِ اللّٰہِ مِنَ الۡمُؤۡمِنِیۡنَ وَ الۡمُہٰجِرِیۡنَ  اِلَّاۤ  اَنۡ تَفۡعَلُوۡۤا  اِلٰۤی  اَوۡلِیٰٓئِکُمۡ مَّعۡرُوۡفًا ؕ کَانَ ذٰلِکَ فِی الۡکِتٰبِ مَسۡطُوۡرًا ﴿۶﴾', 'پیغمبر مومنوں پر انکی جانوں سے بھی زیادہ حق رکھتے ہیں اور پیغمبر کی بیویاں لوگوں کی مائیں ہیں اور رشتہ دار آپس میں کتاب اللہ کی رو سے مسلمانوں اور مہاجروں کے مقابلے میں ایک دوسرے کے ترکے کے زیادہ حقدار ہیں۔ مگر یہ کہ تم اپنے دوستوں کے ساتھ احسان کرنا چاہو۔ یہ حکم کتاب یعنی قرآن میں لکھ دیا گیا ہے۔', 'نبی سے لگاؤ ہے ایمان والوں کو زیادہ اپنی جان سے [۶] اور اسکی عورتیں انکی مائیں ہیں [۷] اور قرابت والے ایک دوسرے سے لگاؤ رکھتے ہیں اللہ کے حکم میں زیادہ سب ایمان والوں اور ہجرت کرنے والوں سے مگر یہ کہ کرنا چاہو اپنے رفیقوں سے احسان [۸] یہ ہے کتاب میں لکھا ہوا [۹]', 'The Prophet is closer to the believers than their ownselves, and his wives are their (believers) mothers (as regards respect and marriage). And blood relations among each other have closer personal ties in the Decree of Allah (regarding inheritance) than (the brotherhood of) the believers and the Muhajiroon (emigrants from Makkah, etc.), except that you do kindness to those brothers (when the Prophet SAW joined them in brotherhood ties). This has been written in the (Allahs Book of Divine) Decrees (AlLauh AlMahfooz).\"', 'The Prophet is closer to the believers than their own selves, and his wives are their mothers; and those having mutual kinship are closer to one another (for the purpose of inheritance) than (other) believers and emigrants according to the Book of Allah, unless you do some good to your friends (by making a will in their favor). This had been written in the Book (the Preserved Tablet).'),
(3540, 33, 7, 1, 17, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'وَ اِذۡ اَخَذۡنَا مِنَ النَّبِیّٖنَ مِیۡثَاقَہُمۡ وَ مِنۡکَ وَ مِنۡ نُّوۡحٍ وَّ اِبۡرٰہِیۡمَ وَ مُوۡسٰی وَ عِیۡسَی ابۡنِ مَرۡیَمَ ۪ وَ اَخَذۡنَا مِنۡہُمۡ مِّیۡثَاقًا غَلِیۡظًا ۙ﴿۷﴾', 'اور جب ہم نے پیغمبروں سے انکا عہد لیا اور تم سے اور نوح سے اور ابراہیم سے اور موسٰی سے اور مریم کے بیٹے عیسٰی سے۔ اور ہم نے عہد بھی ان سے پکا لیا۔', 'اور جب لیا ہم نے نبیوں سے ان کا قرار اور تجھ سے اور نوح سے اور ابراہیم سے اور موسٰی سے اور عیسٰی سے جو بیٹا مریم کا اور لیا ہم نے ان سے گاڑھا قرار [۱۰]', 'And (remember) when We took from the Prophets their covenant, and from you (O Muhammad SAW), and from Nooh (Noah), Ibrahim (Abraham), Moosa (Moses), and Iesa (Jesus), son of Maryam (Mary). We took from them a strong covenant.', 'And (recall) when We took from the prophets their covenant, and from you and from NūH and Ibrāhīm and Mūsā and ‘Īsā, the son of Maryam, and We did take from them a firm covenant,'),
(3541, 33, 8, 1, 17, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'لِّیَسۡـَٔلَ الصّٰدِقِیۡنَ عَنۡ صِدۡقِہِمۡ ۚ وَ اَعَدَّ  لِلۡکٰفِرِیۡنَ عَذَابًا  اَلِیۡمًا ٪﴿۸﴾', 'تاکہ سچ کہنے والوں سے انکی سچائی کے بارے میں اللہ دریافت کرے اور اس نے کافروں کے لئے دکھ دینے والا عذاب تیار کر رکھا ہے۔', 'تاکہ پوچھے اللہ سچوں سے ان کا سچ اور تیار رکھا ہے منکروں کے لیے دردناک عذاب [۱۱]', 'That He may ask the truthfuls (Allahs Messengers and His Prophets) about their truth (i.e. the conveyance of Allahs Message that which they were charged with). And He has prepared for the disbelievers a painful torment (Hell-fire).', 'so that He (Allah) may ask the truthful ones about their truth. And He has prepared a painful punishment for the disbelievers.'),
(3542, 33, 9, 2, 18, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوا اذۡکُرُوۡا نِعۡمَۃَ اللّٰہِ عَلَیۡکُمۡ  اِذۡ جَآءَتۡکُمۡ جُنُوۡدٌ  فَاَرۡسَلۡنَا عَلَیۡہِمۡ رِیۡحًا وَّ جُنُوۡدًا لَّمۡ تَرَوۡہَا ؕ وَ کَانَ اللّٰہُ بِمَا تَعۡمَلُوۡنَ بَصِیۡرًا ۚ﴿۹﴾', 'مومنو اللہ کی اس مہربانی کو یاد کرو جو اس نے تم پر اس وقت کی جب فوجیں تم پر حملہ کرنے کو آئیں۔ تو ہم نے ان پر آندھی چھوڑ دی اور ایسے لشکر نازل کئے جنکو تم دیکھ نہیں سکتے تھے اور جو کام تم کرتے ہو اللہ انکو دیکھ رہا ہے۔', 'اے ایمان والو یاد کرو احسان اللہ کا اپنے اوپر جب چڑھ آئیں تم پر فوجیں پھر ہم نے بھیجدی ان پر ہوا اور وہ فوجیں جو تم نے نہیں دیکھیں [۱۲] اور ہے اللہ جو کچھ کرتے ہو دیکھنے والا [۱۳]', 'O you who believe! Remember Allahs Favour to you, when there came against you hosts, and We sent against them a wind and forces that you saw not (i.e. troops of angels during the battle of AlAhzab (the Confederates)). And Allah is Ever AllSeer of what you do.', 'O you who believe, remember Allah’s favor to you, when the forces (of the infidels) came upon you, and We sent upon them a wind, and the forces (of angels) you did not see. Allah is watchful of whatever you do.'),
(3543, 33, 10, 2, 18, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'اِذۡ  جَآءُوۡکُمۡ  مِّنۡ فَوۡقِکُمۡ  وَ مِنۡ اَسۡفَلَ مِنۡکُمۡ  وَ  اِذۡ زَاغَتِ الۡاَبۡصَارُ وَ  بَلَغَتِ الۡقُلُوۡبُ الۡحَنَاجِرَ وَ تَظُنُّوۡنَ بِاللّٰہِ  الظُّنُوۡنَا ﴿۱۰﴾', 'جب وہ لوگ تمہارے اوپر اور نیچے کی طرف سے تم پر چڑھ آئے اور جب تمہاری آنکھیں پھر گئیں اور دل مارے دہشت کے گلوں تک پہنچ گئے اور تم اللہ کی نسبت طرح طرح کے گمان کرنے لگے۔', 'جب چڑھ آئے تم پر اوپر کی طرف سے اور نیچے سے [۱۴] اور جب بدلنے لگیں آنکھیں [۱۵] اور پہنچے دل گلوں تک [۱۶] اور اٹکلنے لگے تم اللہ پر طرح طرح کی اٹکلیں [۱۷]', 'When they came upon you from above you and from below you, and when the eyes grew wild and the hearts reached to the throats, and you were harbouring doubts about Allah.', '(Recall) when they came upon you from above you and from below you, and when the eyes were distracted, and the hearts reached the throats, and you were thinking about Allah all sorts of thoughts.'),
(3544, 33, 11, 2, 18, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'ہُنَالِکَ ابۡتُلِیَ  الۡمُؤۡمِنُوۡنَ وَ زُلۡزِلُوۡا زِلۡزَالًا  شَدِیۡدًا ﴿۱۱﴾', 'اس موقع پر مومن آزمائے گئے اور سختی سے ہلا ہلا دیئے گئے۔', 'وہاں جانچے گئے ایمان والے اور جھڑ جھڑائے گئے  زور کا جھڑ جھڑانا [۱۸]', 'There, the believers were tried and shaken with a mighty shaking.', 'At that occasion, the believers were put to a trial and were shaken with a violent convulsion.'),
(3545, 33, 12, 2, 18, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'وَ اِذۡ یَقُوۡلُ الۡمُنٰفِقُوۡنَ وَ الَّذِیۡنَ فِیۡ قُلُوۡبِہِمۡ مَّرَضٌ مَّا وَعَدَنَا اللّٰہُ وَ رَسُوۡلُہٗۤ   اِلَّا  غُرُوۡرًا ﴿۱۲﴾', 'اور جب منافق اور وہ لوگ جنکے دلوں میں بیماری تھی کہنے لگے کہ اللہ اور اسکے رسول نے تو ہم سے محض دھوکے کا وعدہ کیا تھا۔', 'اور جب کہنے لگے منافق اور جن کے دلوں میں روگ ہے جو وعدہ کیا تھا ہم سے اللہ نے اور اس کے رسول نے سب فریب تھا [۱۹]', 'And when the hypocrites and those in whose hearts is a disease (of doubts) said: \"Allah and His Messenger (SAW) promised us nothing but delusions!\"', '(Remember) when the hypocrites and those having malady in their hearts were saying, “Allah and His messenger did not promise us but deceitfully;'),
(3546, 33, 13, 2, 18, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'وَ اِذۡ  قَالَتۡ طَّآئِفَۃٌ  مِّنۡہُمۡ  یٰۤاَہۡلَ  یَثۡرِبَ لَا  مُقَامَ لَکُمۡ فَارۡجِعُوۡا ۚ وَ یَسۡتَاۡذِنُ فَرِیۡقٌ مِّنۡہُمُ النَّبِیَّ یَقُوۡلُوۡنَ اِنَّ بُیُوۡتَنَا عَوۡرَۃٌ ؕۛ وَ مَا ہِیَ بِعَوۡرَۃٍ ۚۛ اِنۡ  یُّرِیۡدُوۡنَ   اِلَّا  فِرَارًا  ﴿۱۳﴾', 'اور جب ان میں سے ایک جماعت کہتی تھی کہ اے اہل یثرب یہاں تمہارے ٹھہرنے کا مقام نہیں تو لوٹ چلو اور ایک گروہ ان میں سے پیغمبر سے اجازت مانگنے اور کہنے لگا کہ ہمارے گھر کھلے پڑے ہیں حالانکہ وہ کھلے نہیں تھے۔ وہ تو صرف بھاگنا چاہتے تھے۔', 'اور جب کہنے لگی ایک جماعت ان میں اے یثرب والو [۲۰] تمہارے لئے ٹھکانہ نہیں سو پھر چلو اور رخصت مانگنے لگا ایک فرقہ ان میں نبی سے کہنے لگے ہمارے گھر کھلے پڑے ہیں اور وہ کھلے نہیں پڑے ان کی کوئی غرض نہیں مگر بھاگ جانا [۲۱]', 'And when a party of them said: \"O people of Yathrib (AlMadinah)! There is no stand (possible) for you (against the enemy attack!) Therefore go back!\" And a band of them ask for permission of the Prophet ( SAW) saying: \"Truly, our homes lie open (to the enemy).\" And they lay not open. They but wished to flee.', 'and when a group of them said, “O people of Yathrib (Madīnah), there is no place for you to stay; so go back.”And a group of them was seeking permission (to leave) from the prophet, saying, “In fact our homes are vulnerable,” while they were not vulnerable; they wanted nothing but to escape.'),
(3547, 33, 14, 2, 18, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'وَ لَوۡ دُخِلَتۡ عَلَیۡہِمۡ مِّنۡ اَقۡطَارِہَا ثُمَّ سُئِلُوا الۡفِتۡنَۃَ  لَاٰتَوۡہَا وَ مَا تَلَبَّثُوۡا بِہَاۤ   اِلَّا  یَسِیۡرًا ﴿۱۴﴾', 'اور اگر فوجیں اطراف مدینہ سے ان پر آ داخل ہوں پھر ان سے خانہ جنگی کے لئے کہا جائے تو فوراً کرنے لگیں اور اس کے لئے بہت کم توقف کریں۔', 'اور اگر شہر میں کوئی گھس آئے ان پر اس کے کناروں سے پھر ان سے چاہے دین سے بچلنا تو مان لیں اور دیر نہ کریں اس میں مگر تھوڑی [۲۲]', 'And if the enemy had entered from all sides (of the city), and they had been exhorted to AlFitnah (i.e. to renegade from Islam to polytheism) they would surely have committed it and would have hesitated thereupon but little.', 'And if it (Madīnah) is entered (by the enemy, in their presence,) from all its sides and they are asked (to join) the mischief, they would readily commit it, and would not remain in them (their homes) but for a short while'),
(3548, 33, 15, 2, 18, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'وَ لَقَدۡ کَانُوۡا عَاہَدُوا اللّٰہَ مِنۡ قَبۡلُ لَا یُوَلُّوۡنَ الۡاَدۡبَارَ ؕ وَ کَانَ عَہۡدُ اللّٰہِ مَسۡـُٔوۡلًا ﴿۱۵﴾', 'حالانکہ پہلے اللہ سے اقرار کر چکے تھے کہ پیٹھ نہیں پھیریں گے اور اللہ سے جو اقرار کیا جاتا ہے اسکی ضرور پرسش ہو گی۔', 'اور اقرار کر چکے تھے اللہ سے پہلے کہ نہ پھیریں گے  پیٹھ اور اللہ کے قرار کی پوچھ ہوتی ہے [۲۳]', 'And indeed they had already made a covenant with Allah not to turn their backs, and a covenant with Allah must be answered for.', 'despite that they had already made a covenant with Allah that they would not turn their backs; and a covenant with Allah has to be answered for.'),
(3549, 33, 16, 2, 18, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'قُلۡ لَّنۡ یَّنۡفَعَکُمُ الۡفِرَارُ اِنۡ  فَرَرۡتُمۡ مِّنَ الۡمَوۡتِ اَوِ الۡقَتۡلِ وَ اِذًا لَّا تُمَتَّعُوۡنَ  اِلَّا  قَلِیۡلًا ﴿۱۶﴾', 'کہدو کہ اگر تم مرنے یا مارے جانے سے بھاگتے ہو تو بھاگنا تمکو فائدہ نہیں دے گا اور اس صورت میں تم بہت ہی کم فائدہ اٹھاؤ گے۔', 'تو کہہ کچھ کام نہ آئے گا تمہارے یہ بھاگنا اگر بھاگو گے مرنے سے یا مارے جانے سے اور پھر بھی پھیل نہ پاؤ گے مگر تھوڑے دنوں [۲۴]', 'Say (O Muhammad SAW to these hypocrites who ask your permission to run away from you): \"Flight will not avail you if you flee from death or killing, and then you will enjoy no more than a little while!\"', 'Say, “Flight will never be of any use to you, if you flee from death or killing, and even then you will not be left to enjoy (life) but for a little while.”'),
(3550, 33, 17, 2, 18, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'قُلۡ مَنۡ ذَا الَّذِیۡ یَعۡصِمُکُمۡ مِّنَ اللّٰہِ  اِنۡ اَرَادَ بِکُمۡ سُوۡٓءًا اَوۡ اَرَادَ بِکُمۡ رَحۡمَۃً ؕ وَ لَا  یَجِدُوۡنَ لَہُمۡ مِّنۡ دُوۡنِ اللّٰہِ وَلِیًّا  وَّ لَا  نَصِیۡرًا ﴿۱۷﴾', 'کہدو کہ اگر اللہ تمہارے ساتھ برائی کا ارادہ کرے تو کون تمکو اس سے بچا سکتا ہے۔ یا اگر تم پر مہربانی کرنی چاہے تو کون اسکو ہٹا سکتا ہے اور یہ لوگ اللہ کے سوا کسی کو نہ اپنا دوست پائیں گے اور نہ مددگار۔', 'تو کہہ کون ہے کہ تم کو بچائے اللہ سے اگر چاہے تم پر برائی یا چاہے تم پر مہربانی [۲۵] اور نہ پائیں گے اپنے  واسطے اللہ کے سوائے کوئی حمایتی اور نہ مددگار [۲۶]', 'Say: \"Who is he who can protect you from Allah if He intends to harm you, or intends mercy on you?\" And they will not find, besides Allah, for themselves any Walee (protector, supporter, etc.) or any helper.', 'Say, “Who is there to protect you from Allah, if He intends evil to you, or (who is there to prevent Him) if He intends mercy for you?” Beside Allah, they will not find for themselves either a friend or a helper.'),
(3551, 33, 18, 2, 18, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'قَدۡ یَعۡلَمُ اللّٰہُ  الۡمُعَوِّقِیۡنَ مِنۡکُمۡ وَ الۡقَآئِلِیۡنَ لِاِخۡوَانِہِمۡ ہَلُمَّ   اِلَیۡنَا ۚ وَ لَا  یَاۡتُوۡنَ الۡبَاۡسَ  اِلَّا  قَلِیۡلًا ﴿ۙ۱۸﴾', 'اللہ تم میں سے ان لوگوں کو بھی جانتا ہے جو لوگوں کو منع کرتے ہیں اور اپنے بھائیوں سے کہتے ہیں کہ ہمارے پاس چلے آؤ۔ اور وہ لڑائی میں نہیں آتے مگر کم۔', 'اللہ کو خوب معلوم ہیں جو اٹکانے والے ہیں تم میں اور کہتے ہیں اپنے بھائیوں کو چلے آؤ ہمارے پاس اور لڑائی میں نہیں آتے مگر کبھی [۲۷]', 'Allah already knows those among you who keep back (men) from fighting in Allahs Cause, and those who say to their brethren \"Come here towards us,\" while they (themselves) come not to the battle except a little.', 'Allah does know the ones from among you who prevent (others from joining the battle) and those who say to their brothers, “Come along with us,” and who do not come to the battle but for a little while,'),
(3552, 33, 19, 2, 18, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'اَشِحَّۃً  عَلَیۡکُمۡ ۚۖ فَاِذَا جَآءَ الۡخَوۡفُ رَاَیۡتَہُمۡ یَنۡظُرُوۡنَ اِلَیۡکَ تَدُوۡرُ اَعۡیُنُہُمۡ کَالَّذِیۡ یُغۡشٰی عَلَیۡہِ مِنَ الۡمَوۡتِ ۚ فَاِذَا  ذَہَبَ الۡخَوۡفُ سَلَقُوۡکُمۡ بِاَلۡسِنَۃٍ حِدَادٍ  اَشِحَّۃً عَلَی الۡخَیۡرِ ؕ اُولٰٓئِکَ لَمۡ یُؤۡمِنُوۡا فَاَحۡبَطَ اللّٰہُ  اَعۡمَالَہُمۡ ؕ وَ کَانَ ذٰلِکَ عَلَی اللّٰہِ  یَسِیۡرًا ﴿۱۹﴾', 'یہ اس لئے کہ تم سے بخل کرتے ہیں۔ پھر جب ڈر کا وقت آئے تو تم انکو دیکھو کہ تمہاری طرف دیکھ رہے ہیں اور انکی آنکھیں اسی طرح پھر رہی ہیں جیسے کسی کو موت سے غشی آ رہی ہو پھر جب خوف جاتا رہے تو تیز تیز زبانوں کے ساتھ تمہارے بارے میں باتیں کریں اور مال میں بخل کریں یہ لوگ حقیقت میں ایمان لائے ہی نہ تھے تو اللہ نے انکے اعمال برباد کر دیئے اور یہ اللہ کو آسان تھا۔', 'دریغ (بخل کرتے)  رکھتے ہیں تم سے [۲۸] پھر جب آئے ڈر کا وقت تو تو دیکھے ان کو کہ تکتے ہیں تیری طرف پھرتی ہیں آنکھیں ان کی جیسے کسی پر آئے بے ہوشی موت کی پھر جب جاتا رہے ڈر کا وقت چڑھ چڑھ کر بولیں تم پر تیز تیز زبانوں سے ڈھکے (ٹوٹے) پڑتے ہیں مال پر [۲۹] وہ لوگ یقین نہیں لائے پھر اکارت کر ڈالے اللہ نے انکے کئے کام اور یہ ہے اللہ پر آسان [۳۰]', 'Being miserly towards you (as regards help and aid in Allahs Cause). Then when fear comes, you will see them looking to you, their eyes revolving like (those of) one over whom hovers death, but when the fear departs, they will smite you with sharp tongues, miserly towards (spending anything in any) good (and only covetous of booty and wealth). Such have not believed. Therefore Allah makes their deeds fruitless, and that is ever easy for Allah.', '(and that too) with a greed against you (i.e. to extract a share of spoils from you). But when fear comes, you will see them looking towards you, rolling their eyes, like the one who gets faint because of death. Then once fear is gone, they assail you with sharp tongues, in greed for the good (i.e. the wealth acquired as spoils). These people did not accept faith (in real terms), therefore Allah has nullified their acts. All this is so easy for Allah.'),
(3553, 33, 20, 2, 18, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'یَحۡسَبُوۡنَ الۡاَحۡزَابَ لَمۡ  یَذۡہَبُوۡا ۚ وَ اِنۡ یَّاۡتِ الۡاَحۡزَابُ یَوَدُّوۡا لَوۡ اَنَّہُمۡ بَادُوۡنَ فِی الۡاَعۡرَابِ یَسۡاَلُوۡنَ عَنۡ اَنۡۢبَآئِکُمۡ ؕ وَ لَوۡ کَانُوۡا فِیۡکُمۡ مَّا قٰتَلُوۡۤا   اِلَّا  قَلِیۡلًا ﴿٪۲۰﴾', 'یہ لوگ خوف کے سبب خیال کرتے ہیں کہ فوجیں نہیں گئیں۔ اور اگر لشکر آ جائیں تو تمنا کریں کہ کاش خانہ بدوشوں میں جا رہیں اور تمہاری خبر پوچھا کریں۔ اور اگر تمہارے درمیان ہوں تو لڑائی نہ کریں مگر کم۔', 'سمجھتے ہیں کہ فوجیں کفار کی نہیں پھر گئیں اور اگر آجائیں وہ فوجیں تو آرزو کریں کسی طرح ہم باہر نکلے ہوئے ہوں گاؤں میں پوچھ لیا کریں تمہاری خبریں [۳۱] اور اگر ہوں تم میں لڑائی نہ کریں مگر بہت تھوڑی [۳۲]', 'They think that AlAhzab (the Confederates) have not yet withdrawn, and if AlAhzab (the Confederates) should come (again), they would wish they were in the deserts (wandering) among the bedouins, seeking news about you (from a far place); and if they (happen) to be among you, they would not fight but little.', 'They think that the coalition forces have not (yet) gone. And should the coalition forces come (again), they would like to be living in countryside among the Bedouins, asking (others) about your news. And even if they were to remain among you, they would not fight, but a little.'),
(3554, 33, 21, 3, 19, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'لَقَدۡ کَانَ لَکُمۡ  فِیۡ رَسُوۡلِ اللّٰہِ  اُسۡوَۃٌ حَسَنَۃٌ  لِّمَنۡ کَانَ یَرۡجُوا اللّٰہَ وَ الۡیَوۡمَ  الۡاٰخِرَ  وَ ذَکَرَ  اللّٰہَ  کَثِیۡرًا ﴿ؕ۲۱﴾', 'مسلمانو تمکو اللہ کے رسول کی پیروی کرنی بہتر ہے یعنی ہر اس شخص کو جسے اللہ سے ملنے اور روز قیامت کے آنے کی امید ہو اور وہ اللہ کا ذکر کثرت سے کرتا ہو۔', 'تمہارے لئے بھلی تھی سیکھنی رسول اللہ کی چال اسکے لئے جو کوئی امید رکھتا ہے اللہ کی اور پچھلے دن کی اور یاد کرتا ہے اللہ کو بہت سا [۳۳]', 'Indeed in the Messenger of Allah (Muhammad SAW) you have a good example to follow for him who hopes in (the Meeting with) Allah and the Last Day and remembers Allah much.', 'There is indeed a good model for you in the Messenger of Allah - for the one who has hope in Allah and the Last Day, and remembers Allah profusely.'),
(3555, 33, 22, 3, 19, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'وَ لَمَّا رَاَ  الۡمُؤۡمِنُوۡنَ الۡاَحۡزَابَ ۙ قَالُوۡا ہٰذَا مَا وَعَدَنَا اللّٰہُ  وَ رَسُوۡلُہٗ  وَ صَدَقَ اللّٰہُ وَ رَسُوۡلُہٗ ۫ وَ مَا زَادَہُمۡ  اِلَّاۤ اِیۡمَانًا  وَّ  تَسۡلِیۡمًا ﴿ؕ۲۲﴾', 'اور جب مومنوں نے کافروں کے لشکر کو دیکھا تو کہنے لگے یہ وہی ہے جس کا اللہ اور اسکے پیغمبر نے ہم سے وعدہ کیا تھا اور اللہ اور اسکے پیغمبر نے سچ کہا تھا اور اس سے ان کا ایمان اور اطاعت اور زیادہ ہو گئ۔', 'اور جب دیکھی مسلمانوں نے فوجیں بولے یہ وہی ہے جو وعدہ دیا تھا ہم کو اللہ نے اور اسکے رسول نے اور سچ کہا اللہ نے اور اسکے رسول نے اور ان کو اور بڑھ گیا یقین اور اطاعت کرنا [۳۴]', 'And when the believers saw AlAhzab (the Confederates), they said: \"This is what Allah and His Messenger (Muhammad SAW) had promised us, and Allah and His Messenger (Muhammad SAW) had spoken the truth, and it only added to their faith and to their submissiveness (to Allah).', 'When the believers saw the coalition forces, they said, “This is what Allah and His messenger had promised to us, and Allah and His messenger had told the truth.” It only improved them further in faith and submission.'),
(3556, 33, 23, 3, 19, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'مِنَ الۡمُؤۡمِنِیۡنَ رِجَالٌ صَدَقُوۡا مَا عَاہَدُوا اللّٰہَ عَلَیۡہِ ۚ فَمِنۡہُمۡ مَّنۡ قَضٰی نَحۡبَہٗ  وَ مِنۡہُمۡ مَّنۡ یَّنۡتَظِرُ ۫ۖ وَ مَا بَدَّلُوۡا تَبۡدِیۡلًا ﴿ۙ۲۳﴾', 'مومنوں میں کتنے ہی ایسے شخص ہیں کہ جو اقرار انہوں نے اللہ سے کیا تھا اسکو سچ کر دکھایا پھر ان میں بعض ایسے ہیں جنہوں نے اپنی نذر پوری کر دی یعنی جان دیدی اور بعض ایسے ہیں کہ انتظار کر رہے ہیں۔ اور انہوں نے اپنے قول کو ذرا بھی نہیں بدلا۔', 'ایمان والوں میں کتنے مرد ہیں کہ سچ کر دکھلایا جس بات کا عہد کیا تھا اللہ سے پھر کوئی تو ان میں پورا کر چکا اپنا ذمہ اور کوئی ہے ان میں راہ دیکھ رہا اور بدلا نہیں ایک ذرہ [۳۵]', 'Among the believers are men who have been true to their covenant with Allah (i.e. they have gone out for Jihad (holy fighting), and showed not their backs to the disbelievers), of them some have fulfilled their obligations (i.e. have been martyred), and some of them are still waiting, but they have never changed (i.e.they never proved treacherous to their covenant which they concluded with Allah) in the least.', 'Among the believers, there are men who came true to the covenant they had with Allah. So, some of them have fulfilled their vows (by sacrificing their lives in the way of Allah), and some of them are (still) waiting, and they did not change (their commitment) in the least.'),
(3557, 33, 24, 3, 19, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'لِّیَجۡزِیَ اللّٰہُ  الصّٰدِقِیۡنَ بِصِدۡقِہِمۡ وَ یُعَذِّبَ الۡمُنٰفِقِیۡنَ  اِنۡ شَآءَ  اَوۡ یَتُوۡبَ عَلَیۡہِمۡ ؕ اِنَّ اللّٰہَ کَانَ غَفُوۡرًا رَّحِیۡمًا ﴿ۚ۲۴﴾', 'تاکہ اللہ سچوں کو انکی سچائی کا بدلہ دے اور منافقوں کو چاہے تو عذاب دے یا ان پر مہربانی فرمائے۔ بیشک اللہ بخشنے والا ہے مہربان ہے۔', 'تاکہ بدلا دے اللہ سچوں کو انکے سچ کا اور عذاب کرے منافقوں پر اگر چاہے یا تو بہ ڈالے انکے دل پر بیشک اللہ ہے بخشنے والا مہربان [۳۶]', 'That Allah may reward the men of truth for their truth (i.e. for their patience at the accomplishment of that which they covenanted with Allah), and punish the hypocrites if He will or accept their repentance by turning to them in Mercy. Verily, Allah is OftForgiving, Most Merciful.', '(All this happened) so that Allah may give reward to the truthful ones for their truthfulness, and punish the hypocrites, if He so wills, or accept their repentance. Surely, Allah is Most-Forgiving, Very- Merciful.'),
(3558, 33, 25, 3, 19, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'وَ رَدَّ اللّٰہُ الَّذِیۡنَ کَفَرُوۡا بِغَیۡظِہِمۡ  لَمۡ یَنَالُوۡا خَیۡرًا ؕ وَ کَفَی اللّٰہُ  الۡمُؤۡمِنِیۡنَ الۡقِتَالَ ؕ وَ کَانَ  اللّٰہُ   قَوِیًّا عَزِیۡزًا ﴿ۚ۲۵﴾', 'اور جو کافر تھے انکو اللہ نے پھیر دیا وہ اپنے غصے میں بھرے ہوئے تھے کچھ بھلائی حاصل نہ کر سکے۔ اور اللہ مومنوں کیلئے لڑائی میں کافی ہو گیا اور اللہ زورآور ہے غالب ہے۔', 'اور پھیر دیا اللہ نے منکروں کو  اپنے غصہ میں بھرے ہوئے ہاتھ نہ لگی کچھ بھلائی [۳۷] اور اپنے اوپر لے لی اللہ نے مسلمانوں کی لڑائی اور ہے اللہ زور آور زبردست [۳۸]', 'And Allah drove back those who disbelieved in their rage, they gained no advantage (booty, etc.). Allah sufficed for the believers in the fighting (by sending against the disbelievers a severe wind and troops of angels). And Allah is Ever AllStrong, AllMighty.', 'Allah has turned back the disbelievers with all their rage, having achieved no good; and Allah sufficed the believers against fighting. And Allah is Powerful, Mighty.'),
(3559, 33, 26, 3, 19, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'وَ اَنۡزَلَ الَّذِیۡنَ ظَاہَرُوۡہُمۡ مِّنۡ اَہۡلِ الۡکِتٰبِ مِنۡ صَیَاصِیۡہِمۡ وَ قَذَفَ فِیۡ قُلُوۡبِہِمُ الرُّعۡبَ فَرِیۡقًا تَقۡتُلُوۡنَ وَ تَاۡسِرُوۡنَ فَرِیۡقًا  ﴿ۚ۲۶﴾', 'اور اس نے اہل کتاب میں سے جن لوگوں نے انکی یعنی مکے والوں کی مدد کی تھی انکو انکے قلعوں سے اتار دیا اور انکے دلوں میں دہشت ڈال دی۔ تو بعض کو تم قتل کر دیتے تھے اور بعض کو قید کر لیتے تھے۔', 'اور اتار دیا ان کو جو ان کے پشت پناہ ہوئے تھے اہل کتاب سے ان کے قلعوں سے اور ڈال دی ان کے دلوں میں دھاک کتنوں کو تم جان سے مارنے لگے اور کتنوں کو قید کر لیا [۳۹]', 'And those of the people of the Scripture who backed them (the disbelievers) Allah brought them down from their forts and cast terror into their hearts, (so that) a group (of them) you killed, and a group (of them) you made captives.', 'He has brought those of the people of the Book (the Jews) who had backed them, down from their fortresses, and cast awe into their hearts, so as to make you kill some of them and take others as captives;'),
(3560, 33, 27, 3, 19, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'وَ اَوۡرَثَکُمۡ  اَرۡضَہُمۡ وَ دِیَارَہُمۡ وَ اَمۡوَالَہُمۡ وَ اَرۡضًا لَّمۡ تَطَـُٔوۡہَا ؕ وَ کَانَ اللّٰہُ  عَلٰی  کُلِّ  شَیۡءٍ  قَدِیۡرًا ﴿٪۲۷﴾', 'اور انکی زمین اور انکے گھروں اور انکے مال کا اور اس زمین کا جس میں تم نے پاؤں بھی نہیں رکھا تھا اس نے تمکو وارث بنا دیا اور اللہ ہر چیز پر قدرت رکھتا ہے۔', 'اور تم کو دلائی ان کی زمین اور انکے گھر اور ان کے مال اور  ایک زمین کہ جس پر نہیں پھیرے تم نے اپنے قدم اور ہے اللہ سب کچھ کر سکتا [۴۰]', 'And He caused you to inherit their lands, and their houses, and their riches, and a land which you had not trodden (before). And Allah is Able to do all things.', 'and He let you inherit their land and their homes and their wealth, and a land you have not trodden (so far) . And Allah is Powerful to do any thing.'),
(3561, 33, 28, 4, 0, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'یٰۤاَیُّہَا النَّبِیُّ  قُلۡ  لِّاَزۡوَاجِکَ اِنۡ  کُنۡـتُنَّ تُرِدۡنَ  الۡحَیٰوۃَ  الدُّنۡیَا وَ زِیۡنَتَہَا فَتَعَالَیۡنَ اُمَتِّعۡکُنَّ وَ اُسَرِّحۡکُنَّ سَرَاحًا جَمِیۡلًا ﴿۲۸﴾', 'اے پیغمبر اپنی بیویوں سے کہدو کہ اگر تم دنیا کی زندگی اور اسکی زینت و آرائش چاہتی ہو تو آؤ میں تمہیں کچھ مال دوں اور اچھی طرح سے رخصت کر دوں۔', 'اے نبی کہہ دے اپنی عورتوں کو اگر تم چاہتی ہو دنیا کی زندگانی اور یہاں کی رونق تو آؤ کچھ فائدہ پہنچا دوں تم کو اور رخصت کر دوں بھلی طرح سے رخصت کرنا', 'O Prophet (Muhammad SAW)! Say to your wives: If you desire the life of this world, and its glitter, Then come! I will make a provision for you and set you free in a handsome manner (divorce).', 'O prophet, say to your wives, “If you intend (to have the pleasure of) worldly life and its charm, then come on, and I shall give you some stuff, and release you in a handsome fashion;'),
(3562, 33, 29, 4, 0, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'وَ اِنۡ کُنۡـتُنَّ تُرِدۡنَ اللّٰہَ  وَ رَسُوۡلَہٗ وَ الدَّارَ الۡاٰخِرَۃَ  فَاِنَّ اللّٰہَ  اَعَدَّ لِلۡمُحۡسِنٰتِ مِنۡکُنَّ  اَجۡرًا عَظِیۡمًا ﴿۲۹﴾', 'اور اگر تم اللہ اور اسکے پیغمبر اور عاقبت کے گھر یعنی بہشت کی طلبگار ہو تو تم میں جو نیکوکار ہیں انکے لئے اللہ نے اجرعظیم تیار کر رکھا ہے۔', 'اور اگر تم چاہتی ہو اللہ کو اور اسکے رسول کو اور پچھلے گھر کو تو اللہ نے رکھ چھوڑا ہے انکے لئے جو تم میں نیکی  پر ہیں بڑا  ثواب [۴۱]', 'But if you desire Allah and His Messenger, and the home of the Hereafter, then verily, Allah has prepared for AlMuhsinat (gooddoers) amongst you an enormous reward.', 'but if you intend (to gain the pleasure of) Allah and His messenger and (the betterment of) the Hereafter, then, Allah has prepared a great reward for those of you who are good in their deeds”.'),
(3563, 33, 30, 4, 0, 21, 'اُتۡلُ مَاۤ  اُوۡحِیَ ', 'الاحزاب', 'یٰنِسَآءَ  النَّبِیِّ مَنۡ یَّاۡتِ مِنۡکُنَّ بِفَاحِشَۃٍ  مُّبَیِّنَۃٍ یُّضٰعَفۡ لَہَا الۡعَذَابُ ضِعۡفَیۡنِ ؕ وَ کَانَ ذٰلِکَ عَلَی اللّٰہِ  یَسِیۡرًا ﴿۳۰﴾', 'اے پیغمبر کی بیویو تم میں سے جو کوئی کھلی ناشائستہ حرکت کرے گی۔ اسکو دونی سزا دی جائے گی۔ اور یہ بات اللہ کو آسان ہے۔', 'اے نبی کی عورتو جو کوئی کر لائے تم میں کام بیحیائی کا صریح دونا ہو اس کو عذاب دہرا اور ہے یہ اللہ پر آسان [۴۲]', 'O wives of the Prophet! Whoever of you commits an open illegal sexual intercourse, the torment for her will be doubled, and that is ever easy for Allah.', 'O wives of the Prophet, whoever from among you will commit a clearly shameful act, the punishment will be doubled for her; and it is easy for Allah to do so.'),
(3564, 33, 31, 4, 1, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'وَ مَنۡ یَّقۡنُتۡ مِنۡکُنَّ لِلّٰہِ وَ رَسُوۡلِہٖ وَ تَعۡمَلۡ صَالِحًا نُّؤۡتِہَاۤ  اَجۡرَہَا مَرَّتَیۡنِ ۙ وَ  اَعۡتَدۡنَا  لَہَا  رِزۡقًا کَرِیۡمًا ﴿۳۱﴾', 'اور جو تم میں سے اللہ اور اسکے رسول کی فرمانبردار رہے گی اور عمل نیک کرے گی۔ اسکو ہم دونا ثواب دیں گے اور اسکے لئے ہم نے عزت کی روزی تیار کر رکھی ہے۔', 'اور جو کوئی تم میں اطاعت کرے اللہ کی اور اسکے رسول کی اور عمل کرے اچھے دیویں ہم اسکو اس کا ثواب دو بار اور  رکھی ہے ہم نے اس کے واسطے روزی عزت کی [۴۳]', 'And whosoever of you is obedient to Allah and His Messenger SAW , and does righteous good deeds, We shall give her, her reward twice over, and We have prepared for her Rizqan Karima (a noble provision Paradise).', 'And whoever of you stays obedient to Allah and His messenger, and acts righteously, We shall give her twice her reward, and We have prepared for her a prestigious provision.'),
(3565, 33, 32, 4, 1, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'یٰنِسَآءَ  النَّبِیِّ لَسۡتُنَّ کَاَحَدٍ مِّنَ النِّسَآءِ  اِنِ اتَّقَیۡتُنَّ فَلَا تَخۡضَعۡنَ بِالۡقَوۡلِ فَیَطۡمَعَ  الَّذِیۡ  فِیۡ قَلۡبِہٖ مَرَضٌ وَّ  قُلۡنَ  قَوۡلًا  مَّعۡرُوۡفًا ﴿ۚ۳۲﴾', 'اے پیغمبر کی بیویو تم عام عورتوں کی طرح نہیں ہو۔ اگر تم پرہیزگار رہنا چاہتی ہو تو کسی اجنبی شخص سے نرم لہجے میں بات نہ کرو تاکہ وہ شخص جسکے دل میں کسی طرح کا روگ ہے کوئی امید نہ پیدا کر لے۔ اور دستور کے مطابق بات کیا کرو۔', 'اے نبی کی عورتو تم نہیں ہو جیسے ہر کوئی عورتیں [۴۴] اگر تم ڈر رکھو سو تم دب کر بات نہ کرو پھر لالچ کرے کوئی جس کے دل میں روگ ہے اور کہو بات معقول [۴۵]', 'O wives of the Prophet! You are not like any other women. If you keep your duty (to Allah), then be not soft in speech, lest he in whose heart is a disease (of hypocrisy, or evil desire for adultery, etc.) should be moved with desire, but speak in an honourable manner.', 'O wives of the prophet, you are not like any other women, if you observe taqwā (righteousness). So, do not be too soft in your speech, lest someone having disease in his heart should develop fancies (about you); and do speak with appropriate words.'),
(3566, 33, 33, 4, 1, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'وَ قَرۡنَ فِیۡ بُیُوۡتِکُنَّ وَ لَا تَبَرَّجۡنَ تَبَرُّجَ الۡجَاہِلِیَّۃِ  الۡاُوۡلٰی وَ اَقِمۡنَ الصَّلٰوۃَ وَ اٰتِیۡنَ الزَّکٰوۃَ  وَ  اَطِعۡنَ اللّٰہَ  وَ  رَسُوۡلَہٗ ؕ اِنَّمَا یُرِیۡدُ اللّٰہُ  لِیُذۡہِبَ عَنۡکُمُ الرِّجۡسَ اَہۡلَ الۡبَیۡتِ وَ یُطَہِّرَکُمۡ  تَطۡہِیۡرًا ﴿ۚ۳۳﴾', 'اور اپنے گھروں میں ٹھہری رہو اور جس طرح پہلے جاہلیت کے دنوں میں زیب و زینت کی نمائش کیجاتی تھی اس طرح اظہار زینت نہ کرو اور نماز پڑھتی رہو اور زکوٰۃ دیتی رہو اور اللہ اور اسکے رسول کی فرمانبرداری کرتی رہو۔ اے پیغمبر کی گھر والیو اللہ چاہتا ہے کہ تم سے ہر طرح کی ناپاکی دور کر دے اور تمہیں بالکل پاک صاف کر دے۔', 'اور قرار پکڑو اپنے گھروں میں اور دکھلاتی نہ پھرو جیسا کہ دکھانا دستور تھا پہلے جہالت کے وقت میں [۴۶] اور قائم رکھو نماز اور دیتی رہو زکوٰۃ اور اطاعت میں رہو اللہ کی اور اس کے رسول کی [۴۷] اللہ یہی چاہتا ہے کہ دور کرے تم سے گندی باتیں  اے نبی کے گھر والو اور ستھرا کر  دے تم کو ایک ستھرائی سے [۴۸]', 'And stay in your houses, and do not display yourselves like that of the times of ignorance, and perform As-Salat (IqamatasSalat), and give Zakat and obey Allah and His Messenger. Allah wishes only to remove ArRijs (evil deeds and sins, etc.) from you, O members of the family (of the Prophet SAW), and to purify you with a thorough purification.', 'Remain in your homes, and do not display (your) beauty as it used to be displayed in the days of earlier ignorance; and establish Salāh, and pay Zakāh, and obey Allah and His messenger. Allah only intends to keep (all sorts of) filth away from you, O members of the family (of the prophet), and to make you pure through a perfect purification.'),
(3567, 33, 34, 4, 1, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'وَ اذۡکُرۡنَ مَا یُتۡلٰی فِیۡ  بُیُوۡتِکُنَّ  مِنۡ اٰیٰتِ اللّٰہِ  وَ الۡحِکۡمَۃِ ؕ اِنَّ اللّٰہَ  کَانَ لَطِیۡفًا خَبِیۡرًا ﴿٪۳۴﴾', 'اور تمہارے گھروں میں جو اللہ کی آیتیں پڑھی جاتی ہیں اور حکمت کی باتیں سنائی جاتی ہیں انکو یاد رکھو بیشک اللہ باریک بین ہے باخبر ہے۔', 'اور یاد کرو جو پڑھی جاتی ہیں تمہارے گھروں میں اللہ کی باتیں اور عقلمندی کی [۴۹] مقرر اللہ ہے بھید جاننے والا خبردار [۵۰]', 'And remember (O you the members of the Prophets family, the Graces of your Lord), that which is recited in your houses of the Verses of Allah and AlHikmah (i.e. Prophets Sunnah legal ways, etc. so give your thanks to Allah and glorify His Praises for this Quran and the Sunnah). Verily, Allah is Ever Most Courteous, WellAcquainted with all things.', 'And be mindful of Allah’s verses and the wisdom that is recited in your homes. Surely, Allah is All-Kind, All-Aware.'),
(3568, 33, 35, 5, 2, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'اِنَّ  الۡمُسۡلِمِیۡنَ وَ الۡمُسۡلِمٰتِ وَ الۡمُؤۡمِنِیۡنَ وَ الۡمُؤۡمِنٰتِ وَ الۡقٰنِتِیۡنَ وَ الۡقٰنِتٰتِ وَ الصّٰدِقِیۡنَ وَ الصّٰدِقٰتِ وَ الصّٰبِرِیۡنَ وَ الصّٰبِرٰتِ وَ الۡخٰشِعِیۡنَ وَ الۡخٰشِعٰتِ وَ الۡمُتَصَدِّقِیۡنَ وَ الۡمُتَصَدِّقٰتِ وَ الصَّآئِمِیۡنَ وَ الصّٰٓئِمٰتِ وَ الۡحٰفِظِیۡنَ فُرُوۡجَہُمۡ وَ الۡحٰفِظٰتِ وَ الذّٰکِرِیۡنَ اللّٰہَ کَثِیۡرًا وَّ الذّٰکِرٰتِ ۙ اَعَدَّ  اللّٰہُ   لَہُمۡ  مَّغۡفِرَۃً وَّ اَجۡرًا  عَظِیۡمًا  ﴿۳۵﴾', 'جو لوگ اللہ کے آگے سر اطاعت خم کرنے والے ہیں یعنی مسلمان مرد اور مسلمان عورتیں اور مومن مرد اور مومن عورتیں اور فرمانبردار مرد اور فرمانبردار عورتیں اور راستباز مرد اور راستباز عورتیں اور صبر کرنے والے مرد اور صبر کرنے والی عورتیں اور عاجزی کرنے والے مرد اور عاجزی کرنے والی عورتیں اور خیرات کرنے والے مرد اور خیرات کرنے والی عورتیں اور روزے رکھنے والے مرد اور روزے رکھنے والی عورتیں اور اپنی شرمگاہوں کی حفاظت کرنے والے مرد اور حفاظت کرنے والی عورتیں اور اللہ کو کثرت سے یاد کرنے والے مرد اور کثرت سے یاد کرنے والی عورتیں کچھ شک نہیں کہ انکے لئے اللہ نے بخشش اور اجر عظیم تیار کر رکھا ہے۔', 'تحقیق مسلمان مرد اور مسلمان عورتیں اور ایمان دار مرد اور ایمان دار عورتیں اور بندگی کرنے والے مرد اور بندگی کرنے والی عورتیں اور سچے مرد اور سچی عورتیں اور محنت جھیلنے والے مرد اور محنت جھیلنے والی عورتیں [۵۱] اور دبے رہنے والے مرد اور دبی رہنے والی عورتیں [۵۲] اور خیرات کرنے والے مرد اور خیرات کرنے والی عورتیں اور روزہ دار مرد اور روزہ دار عورتیں اور حفاظت کرنے والے مرد اپنی شہوت کی جگہ کو اور حفاظت کرنے والی عورتیں اور یاد کرنے والے مرد اللہ کو بہت سا اور یاد کرنے والی عورتیں رکھی ہے اللہ نے ان کے واسطے معافی اور ثواب بڑا [۵۳]', 'Verily, the Muslims (those who submit to Allah in Islam) men and women, the believers men and women (who believe in Islamic Monotheism), the men and the women who are obedient (to Allah), the men and women who are truthful (in their speech and deeds), the men and the women who are patient (in performing all the duties which Allah has ordered and in abstaining from all that Allah has forbidden), the men and the women who are humble (before their Lord Allah), the men and the women who give Sadaqat (i.e. Zakat, and alms, etc.), the men and the women who observe Saum (fast) (the obligatory fasting during the month of Ramadan, and the optional Nawafil fasting), the men and the women who guard their chastity (from illegal sexual acts) and the men and the women who remember Allah much with their hearts and tongues (while sitting, standing, lying, etc. for more than 300 times extra over the remembrance of Allah during the five compulsory congregational prayers) or praying extra additional Nawafil prayers of night in the last part of night, etc.) Allah has prepared for them forgiveness and a great reward (i.e. Paradise).', 'Surely, Muslim men and Muslim women, believing men and believing women, devout men and devout women, truthful men and truthful women, patient men and patient women, humble men and humble women, and the men who give Sadaqah (charity) and the women who give Sadaqah, and the men who fast and the women who fast, and the men who guard their private parts (against evil acts) and the women who guard (theirs), and the men who remember Allah much and the women who remember (Him) - for them, Allah has prepared forgiveness and a great reward.'),
(3569, 33, 36, 5, 2, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'وَ مَا کَانَ  لِمُؤۡمِنٍ وَّ لَا مُؤۡمِنَۃٍ  اِذَا قَضَی اللّٰہُ  وَ رَسُوۡلُہٗۤ  اَمۡرًا اَنۡ  یَّکُوۡنَ  لَہُمُ الۡخِیَرَۃُ  مِنۡ اَمۡرِہِمۡ ؕ وَ مَنۡ یَّعۡصِ اللّٰہَ وَ رَسُوۡلَہٗ  فَقَدۡ  ضَلَّ  ضَلٰلًا  مُّبِیۡنًا ﴿ؕ۳۶﴾', 'اور کسی مومن مرد اور مومن عورت کو حق نہیں ہے کہ جب اللہ اور اس کا رسول کوئی بات طے کر دیں تو وہ اس کام میں اپنا بھی کچھ اختیار سمجھیں۔ اور جو کوئی اللہ اور اسکے رسول کی نافرمانی کرے وہ بالکل گمراہ ہو گیا۔', 'اور کام نہیں کسی ایماندار مرد کا اور نہ ایماندار عورت کا جب کہ مقرر کر دے اللہ اور اس کا رسول کوئی کام  ان کو رہے اختیار اپنے کام کا اور جس نے نافرمانی کی اللہ کی اور اس کے رسول کی سو وہ راہ بھولا صریح چوک کر [۵۴]', 'It is not for a believer, man or woman, when Allah and His Messenger have decreed a matter that they should have any option in their decision. And whoever disobeys Allah and His Messenger, he has indeed strayed in a plain error.', 'It is not open for a believing man or a believing woman, once Allah and His messenger have decided a thing, that they should have a choice about their matter; and whoever disobeys Allah and His messenger, he indeed gets off the track, falling into an open error.'),
(3570, 33, 37, 5, 2, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'وَ اِذۡ تَقُوۡلُ لِلَّذِیۡۤ  اَنۡعَمَ اللّٰہُ  عَلَیۡہِ وَ اَنۡعَمۡتَ عَلَیۡہِ  اَمۡسِکۡ عَلَیۡکَ زَوۡجَکَ وَ اتَّقِ اللّٰہَ  وَ تُخۡفِیۡ فِیۡ نَفۡسِکَ مَا اللّٰہُ مُبۡدِیۡہِ  وَ تَخۡشَی النَّاسَ ۚ وَ اللّٰہُ   اَحَقُّ اَنۡ  تَخۡشٰہُ ؕ فَلَمَّا قَضٰی زَیۡدٌ مِّنۡہَا وَطَرًا زَوَّجۡنٰکَہَا  لِکَیۡ لَا یَکُوۡنَ عَلَی  الۡمُؤۡمِنِیۡنَ حَرَجٌ  فِیۡۤ  اَزۡوَاجِ اَدۡعِیَآئِہِمۡ  اِذَا  قَضَوۡا  مِنۡہُنَّ  وَطَرًا ؕ وَ کَانَ   اَمۡرُ  اللّٰہِ  مَفۡعُوۡلًا ﴿۳۷﴾', 'اور جب تم اس شخص سے جس پر اللہ نے احسان کیا تھا اور تم نے بھی احسان کیا تھا یہ کہتے تھے کہ اپنی بیوی کو اپنے پاس رہنے دے اور اللہ سے ڈر اور تم اپنے دل میں وہ بات چھپا رہے تھے جسکو اللہ ظاہر کرنے والا تھا اور تم لوگوں سے ڈرتے تھے حالانکہ اللہ ہی اس کا زیادہ مستحق ہے کہ اس سے ڈرو۔ پھر جب زید نے اس سے تعلق ختم کر لیا یعنی اسکو طلاق دے دی تو ہم نے اسے تمہاری زوجیت میں دیدیا تاکہ مومنوں پر انکے منہ بولے بیٹوں کی بیویوں کے ساتھ نکاح کرنے کے بارے میں جب وہ بیٹے ان سے اپنا تعلق ختم کر لیں یعنی طلاق دے دیں کچھ تنگی نہ رہے اور اللہ کا حکم واقع ہو کر رہنے والا تھا۔', 'اور جب تو کہنے لگا اس شخص کو جس پر اللہ نے احسان کیا اور تو نے احسان کیا رہنے دے اپنے پاس اپنی جورو کو اور ڈر اللہ سے اور تو چھپاتا تھا اپنے دل میں ایک چیز جس کو اللہ کھولنا چاہتا ہے اور ڈرتا تھا لوگوں سے اور اللہ سے زیادہ چاہئیے ڈرنا تجھ کو پھر جب زید تمام کر چکا اس عورت سے اپنی غرض [۵۵] ہم نے ا سکو تیرے نکاح میں دیدیا تا نہ رہے مسلمانوں پر گناہ نکاح کر لینا جوروئیں اپنے لے پالکوں کی جب وہ تمام کر لیں ان سے اپنی غرض اور ہے اللہ کا حکم بجا لانا [۵۶]', 'And (remember) when you said to him (Zaid bin Harithah ÑÖì the freedslave of the Prophet SAW) on whom Allah has bestowed Grace (by guiding him to Islam) and you (O Muhammad SAW too) have done favour (by manumitting him) \"Keep your wife to yourself, and fear Allah.\" But you did hide in yourself (i.e. what Allah has already made known to you that He will give her to you in marriage) that which Allah will make manifest, you did fear the people (i.e., Muhammad SAW married the divorced wife of his manumitted slave) whereas Allah had a better right that you should fear Him. So when Zaid had accomplished his desire from her (i.e. divorced her), We gave her to you in marriage, so that (in future) there may be no difficulty to the believers in respect of (the marriage of) the wives of their adopted sons when the latter have no desire to keep them (i.e. they have divorced them). And Allahs Command must be fulfilled.', '(Remember) when you (O Prophet,) were saying to the one who was favored by Allah and favored by you, 16 “Keep your wife to your self, and fear Allah.” And you were concealing in your heart what Allah was going to reveal, and you were fearing people, while Allah is more entitled to be feared by you. So, when Zaid finished his desire for her, We gave her into your marriage, so that there may not be a problem for the believers in marrying wives of their adopted sons, when they finish their desire for them; and Allah’s decree had to be enforced.'),
(3571, 33, 38, 5, 2, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'مَا کَانَ عَلَی النَّبِیِّ مِنۡ حَرَجٍ فِیۡمَا فَرَضَ اللّٰہُ  لَہٗ ؕ سُنَّۃَ اللّٰہِ  فِی الَّذِیۡنَ خَلَوۡا مِنۡ قَبۡلُ ؕ وَ کَانَ  اَمۡرُ  اللّٰہِ   قَدَرًا مَّقۡدُوۡرَۨا ﴿۫ۙ۳۸﴾', 'پیغمبر پر اس کام میں کچھ تنگی نہیں جو اللہ نے انکے لئے مقرر کر دیا۔ اور جو لوگ پہلے گذر چکے ہیں ان میں بھی اللہ کا یہی دستور رہا ہے۔ اور اللہ کا حکم ٹھہر چکا تھا۔', 'نبی پر کچھ مضائقہ نہیں ا س بات میں جو مقرر کر دی اللہ نے اسکے  واسطے جیسے دستور  رہا ہے اللہ کا ان لوگوں میں جو گذرے  پہلے اور ہے حکم اللہ کا مقرر ٹھہر چکا', 'There is no blame on the Prophet (SAW) in that which Allah has made legal for him.That has been Allahs Way with those who have passed away of (the Prophets of) old. And the Command of Allah is a decree determined.', 'There is no problem for the prophet in (doing) what Allah has prescribed for him, a customary practice of Allah in the case of those who have gone before - and Allah’s command is pre-determined by destiny -'),
(3572, 33, 39, 5, 2, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'الَّذِیۡنَ یُبَلِّغُوۡنَ  رِسٰلٰتِ اللّٰہِ وَ یَخۡشَوۡنَہٗ  وَ لَا یَخۡشَوۡنَ  اَحَدًا  اِلَّا اللّٰہَ ؕ وَ کَفٰی  بِاللّٰہِ  حَسِیۡبًا ﴿۳۹﴾', 'یعنی ان پیغمبروں میں جو اللہ کے پیغام جوں کے توں پہنچاتے اور اس سے ڈرتے اور اللہ کے سوا کسی سے نہیں ڈرتے تھے۔ اور اللہ ہی حساب کرنے کو کافی ہے۔', 'وہ لوگ جو پہنچاتے ہیں پیغام اللہ کے اور ڈرتے ہیں اس سے اور نہیں ڈرتے کسی سے سوائے اللہ کے اور بس ہے اللہ کفایت کرنے والا [۵۷]', 'Those who convey the Message of Allah and fear Him, and fear none save Allah. And Sufficient is Allah as a Reckoner.', 'those who convey the messages of Allah and have awe of Him, and have no awe of anyone except Allah. Allah is sufficient to take account (of everyone).'),
(3573, 33, 40, 5, 2, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'مَا کَانَ مُحَمَّدٌ اَبَاۤ  اَحَدٍ مِّنۡ رِّجَالِکُمۡ وَ لٰکِنۡ رَّسُوۡلَ اللّٰہِ وَ خَاتَمَ  النَّبِیّٖنَ ؕ وَ  کَانَ اللّٰہُ  بِکُلِّ شَیۡءٍ عَلِیۡمًا ﴿٪۴۰﴾', 'محمد ﷺ تمہارے مردوں میں سے کسی کے والد نہیں ہیں لیکن اللہ کے پیغمبر اور نبیوں کی مہر یعنی سلسلہ نبوت کو ختم کر دینے والے ہیں اور اللہ ہر چیز سے واقف ہے۔', 'محمد باپ نہیں کسی کا تمہارے مردوں میں سے لیکن رسول ہے اللہ کا [۵۸] اور مہر سب نبیوں پر [۵۹] اور ہے اللہ سب چیزوں کو جاننے والا [۶۰]', 'Muhammad (SAW) is not the father of any man among you, but he is the Messenger of Allah and the last (end) of the Prophets. And Allah is Ever AllAware of everything.', 'MuHammad is not a father of any of your men, but he is a messenger of Allah and the last of the prophets. And Allah has the Knowledge of every thing.'),
(3574, 33, 41, 6, 3, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'یٰۤاَیُّہَاالَّذِیۡنَ  اٰمَنُوا اذۡکُرُوا اللّٰہَ  ذِکۡرًا کَثِیۡرًا﴿ۙ۴۱﴾', 'اے اہل ایمان اللہ کا بہت بہت ذکر کیا کرو۔', 'اے ایمان والو یاد کرو اللہ کی بہت سی  یاد', 'O you who believe! Remember Allah with much remembrance.', 'O you who believe, remember Allah abundantly,'),
(3575, 33, 42, 6, 3, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'وَّ سَبِّحُوۡہُ  بُکۡرَۃً  وَّ  اَصِیۡلًا ﴿۴۲﴾', 'اور صبح و شام اسکی پاکی بیان کرتے رہو۔', 'اور پاکی بولتے رہو اسکی صبح اور شام [۶۱]', 'And glorify His Praises morning and afternoon (the early morning (Fajr) and Asr prayers).', 'and proclaim His purity at morn and eve.'),
(3576, 33, 43, 6, 3, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'ہُوَ الَّذِیۡ یُصَلِّیۡ عَلَیۡکُمۡ وَ مَلٰٓئِکَتُہٗ لِیُخۡرِجَکُمۡ مِّنَ الظُّلُمٰتِ اِلَی النُّوۡرِ ؕ وَ کَانَ بِالۡمُؤۡمِنِیۡنَ رَحِیۡمًا ﴿۴۳﴾', 'وہی تو ہے جو تم پر رحمت بھیجتا ہے اور اسکے فرشتے بھی تاکہ تم کو اندھیروں سے نکال کر روشنی کی طرف لیجائے۔ اور اللہ مومنوں پر مہربان ہے۔', 'وہی ہے جو رحمت بھیجتا ہے تم پر اور اس کے فرشتے  تاکہ نکالے تم کو اندھیروں سے اجالے میں  اور ہے ایمان والوں پر مہربان [۶۲]', 'He it is Who sends Salat (His blessings) on you, and His angels too (ask Allah to bless and forgive you), that He may bring you out from darkness (of disbelief and polytheism) into light (of Belief and Islamic Monotheism). And He is Ever Most Merciful to the believers.', 'He is such that He and His angels send blessings to you, so that He brings you out from all sorts of darkness into Light; and He is Very-Merciful to the believers.'),
(3577, 33, 44, 6, 3, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'تَحِیَّتُہُمۡ یَوۡمَ یَلۡقَوۡنَہٗ سَلٰمٌ ۖۚ وَ اَعَدَّ لَہُمۡ   اَجۡرًا کَرِیۡمًا ﴿۴۴﴾', 'جس روز وہ اس سے ملیں گے تو ان کا تحفہ اللہ کی طرف سے سلام ہو گا اور اس نے انکے لئے عمدہ ثواب تیار کر رکھا ہے۔', 'دعا ان کی جس دن اس سے ملیں گے سلام ہے اور تیار رکھا ہے انکے واسطے ثواب عزت کا [۶۳]', 'Their greeting on the Day they shall meet Him will be \"Salam: Peace (i.e. the angels will say to them: Salamu Alaikum)!\" And He has prepared for them a generous reward (i.e. Paradise).', 'Their greeting, on the Day when they will meet Him, will be, “Salām ” . And He has prepared for them a noble reward.'),
(3578, 33, 45, 6, 3, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'یٰۤاَیُّہَا النَّبِیُّ  اِنَّاۤ  اَرۡسَلۡنٰکَ شَاہِدًا وَّ مُبَشِّرًا وَّ  نَذِیۡرًا ﴿ۙ۴۵﴾', 'اے پیغمبر ہم نے تمکو گواہی دینے والا اور خوشخبری سنانے والا اور خبردار کرنے والا بنا کر بھیجا ہے۔', 'اے نبی ہم نے تجھ کو بھیجا بتانے والا [۶۴] اور خوشخبری سنانے والا اور ڈرانے والا [۶۵]', 'O Prophet (MuhammadSAW )! Verily, We have sent you as witness, and a bearer of glad tidings, and a warner,', 'O prophet, We have sent you as a witness and as a bearer of good news and a warner,'),
(3579, 33, 46, 6, 3, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'وَّ دَاعِیًا اِلَی اللّٰہِ  بِاِذۡنِہٖ وَ سِرَاجًا مُّنِیۡرًا ﴿۴۶﴾', 'اور اللہ کی طرف اسی کے حکم سے بلانے والا اور چراغ روشن۔', 'اور بلانے والا للہ کی طرف اسکے حکم سے اور چمکتا ہوا چراغ [۶۶]', 'And as one who invites to Allah (Islamic Monotheism, i.e. to worship none but Allah (Alone)) by His Leave, and as a lamp spreading light (through your instructions from the Quran and the Sunnah the legal ways of the Prophet SAW ).', 'and as the one who calls (people) towards Allah with His permission, and as a luminous lamp.'),
(3580, 33, 47, 6, 3, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'وَ بَشِّرِ الۡمُؤۡمِنِیۡنَ بِاَنَّ لَہُمۡ مِّنَ اللّٰہِ فَضۡلًا کَبِیۡرًا ﴿۴۷﴾', 'اور مومنوں کو خوشخبری سنا دو کہ انکے لئے اللہ کی طرف سے بڑا فضل ہے۔', 'اور خوشخبری سنا دے ایمان والوں کو کہ ان کے لیے ہے خدا کی طرف سے بڑی بزرگی [۶۷]', 'And announce to the believers (in the Oneness of Allah and in His Messenger Muhammad SAW) the glad tidings, that they will have from Allah a Great Bounty.', 'So give good news to the believers that they are going to receive a huge bounty from Allah;');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(3581, 33, 48, 6, 3, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'وَ لَا تُطِعِ  الۡکٰفِرِیۡنَ وَ الۡمُنٰفِقِیۡنَ وَ دَعۡ  اَذٰىہُمۡ  وَ  تَوَکَّلۡ  عَلَی اللّٰہِ ؕ وَ کَفٰی بِاللّٰہِ  وَکِیۡلًا ﴿۴۸﴾', 'اور کافروں اور منافقوں کا کہا نہ ماننا اور نہ انکے تکلیف دینے پر نظر کرنا اور اللہ پر بھروسہ رکھنا۔ اور اللہ ہی کارساز کافی ہے۔', 'اور کہا مت مان منکروں کا اور دغابازوں کا [۶۸] اور چھوڑ دے انکا ستانا اور بھروسہ کر اللہ پر اور اللہ بس ہے کام بنانے والا [۶۹]', 'And obey not the disbelievers and the hypocrites, and harm them not (till you are ordered). And put your trust in Allah, and Sufficient is Allah as a Wakeel (Trustee, or Disposer of affairs).', 'and do not obey the infidels and the hypocrites, and just ignore any hurt (that afflicts you) from them, and place your trust in Allah. Allah is sufficient (for you) to take care of all matters.'),
(3582, 33, 49, 6, 3, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اِذَا نَکَحۡتُمُ الۡمُؤۡمِنٰتِ ثُمَّ طَلَّقۡتُمُوۡہُنَّ مِنۡ قَبۡلِ اَنۡ تَمَسُّوۡہُنَّ فَمَا لَکُمۡ عَلَیۡہِنَّ مِنۡ عِدَّۃٍ تَعۡتَدُّوۡنَہَا ۚ فَمَتِّعُوۡہُنَّ وَ سَرِّحُوۡہُنَّ  سَرَاحًا جَمِیۡلًا ﴿۴۹﴾', 'مومنو! جب تم مومن عورتوں سے نکاح کر کے انکو ہاتھ لگانے یعنی انکے پاس جانے سے پہلے طلاق دے دو تو تمکو کچھ حق نہیں کہ ان سے عدّت پوری کراؤ۔ بس انکو کچھ فائدہ یعنی خرچ دے دو اور انکو اچھی طرح سے رخصت کر دو۔', 'اے ایمان والوں جب تم نکاح میں لاؤ مسلمان عورتوں کو پھر ان کو چھوڑ دو پہلے اس سے کہ ان کو ہاتھ لگاؤ سو ان پر تم کو حق نہیں عدت میں بٹھلانا کہ گنتی پوری کراؤ سو ان کو دو کچھ فائدہ اور  رخصت کرو بھلی طرح سے [۷۰]', 'O you who believe! When you marry believing women, and then divorce them before you have sexual intercourse with them, no Iddah (divorce prescribed period, see (V.65:4)) have you to count in respect of them. So give them a present, and set them free i.e. divorce, in a handsome manner.', 'O you who believe, when you marry the believing women, and then divorce them before you have touched them, then they have no obligation of any ‘iddah (waiting period) for you that you may count. So give them (due) benefits, and release them in a pleasant manner.'),
(3583, 33, 50, 6, 3, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'یٰۤاَیُّہَا النَّبِیُّ  اِنَّاۤ  اَحۡلَلۡنَا لَکَ اَزۡوَاجَکَ الّٰتِیۡۤ  اٰتَیۡتَ اُجُوۡرَہُنَّ وَ مَا مَلَکَتۡ یَمِیۡنُکَ مِمَّاۤ  اَفَآءَ اللّٰہُ  عَلَیۡکَ وَ بَنٰتِ عَمِّکَ وَ بَنٰتِ عَمّٰتِکَ وَ بَنٰتِ خَالِکَ وَ بَنٰتِ خٰلٰتِکَ الّٰتِیۡ ہَاجَرۡنَ مَعَکَ ۫ وَ امۡرَاَۃً  مُّؤۡمِنَۃً  اِنۡ  وَّہَبَتۡ نَفۡسَہَا لِلنَّبِیِّ  اِنۡ  اَرَادَ  النَّبِیُّ  اَنۡ یَّسۡتَنۡکِحَہَا ٭ خَالِصَۃً  لَّکَ مِنۡ دُوۡنِ الۡمُؤۡمِنِیۡنَ ؕ قَدۡ عَلِمۡنَا مَا فَرَضۡنَا عَلَیۡہِمۡ فِیۡۤ  اَزۡوَاجِہِمۡ وَ مَا مَلَکَتۡ  اَیۡمَانُہُمۡ لِکَیۡلَا یَکُوۡنَ عَلَیۡکَ حَرَجٌ ؕ وَ کَانَ اللّٰہُ  غَفُوۡرًا رَّحِیۡمًا  ﴿۵۰﴾', 'اے پیغمبر ﷺ ہم نے تمہارے لئے تمہاری بیویاں جنکو تم نے انکے مہر دے دیئے ہیں حلال کر دی ہیں اور تمہاری باندیاں جو اللہ نے تمکو کفار سے بطور مال غنیمت دلوائی ہیں اور تمہارے چچا کی بیٹیاں اور تمہاری پھوپھیوں کی بیٹیاں اور تمہارے ماموؤں کی بیٹیاں اور تمہاری خالاؤں کی بیٹیاں جو تمہارے ساتھ وطن چھوڑ کر آئی ہیں سب حلال ہیں اور کوئی مومن عورت اگر اپنے آپکو پیغمبر ﷺ حوالے کر دے یعنی مہر کے بغیر نکاح میں آنا چاہے بشرطیکہ پیغمبر ﷺ بھی اس سے نکاح کرنا چاہیں وہ بھی حلال ہے لیکن یہ اجازت اے نبی ﷺ خاص تم ہی کو ہے سب مسلمانوں کو نہیں۔ ہم نے انکی بیویوں اور باندیوں کے بارے میں جو مہر واجب الادا مقرر کر دیا ہے ہم کو معلوم ہے یہ اس لئے کیا گیا ہے کہ تم پر کسی طرح کی تنگی نہ رہے اور اللہ بخشنے والا ہے مہربان ہے۔', 'اے نبی ہم نے حلال رکھیں تجھ کو تیری عورتیں جن کے مہر تو دے چکا ہے اور جو مال ہو تیرے ہاتھ کا جو ہاتھ لگا دے تیرے اللہ [۷۱] اور تیرے چچا کی بیٹیاں اور پھوپھیوں کی بیٹیاں اور تیرے ماموں کی بیٹیاں اور تیری خالاؤں کی بیٹیاں جنہوں نے وطن چھوڑا تیرے ساتھ اور جو عورت ہو مسلمان اگر بخشدے اپنی جان نبی کو  اگر نبی چاہے کہ اس کو نکاح میں لائے  یہ خاص ہے تیرے لیے سوائے سب مسلمانوں کے ہم کو معلوم ہے جو مقرر کر دیا ہے ہم  نے ان پر انکی عوتوں کے حق میں اور انکے ہاتھ کے مال میں تا نہ رہے تجھ پر تنگی اور ہے اللہ بخشنے  والا مہربان [۷۲]', 'O Prophet (Muhammad SAW)! Verily, We have made lawful to you your wives, to whom you have paid their Mahr (bridal money given by the husband to his wife at the time of marriage), and those (captives or slaves) whom your right hand possesses - whom Allah has given to you, and the daughters of your Amm (paternal uncles) and the daughters of your Ammah (paternal aunts) and the daughters of your Khal (maternal uncles) and the daughters of your Khalah (maternal aunts) who migrated (from Makkah) with you, and a believing woman if she offers herself to the Prophet, and the Prophet wishes to marry her; a privilege for you only, not for the (rest of) the believers. Indeed We know what We have enjoined upon them about their wives and those (captives or slaves) whom their right hands possess, - in order that there should be no difficulty on you. And Allah is Ever OftForgiving, Most Merciful.', 'O prophet, We have made lawful for you all your wives whom you have given their dowers, and those (bondwomen) whom you own, out of the captives Allah has given to you as spoils of war, and daughters of your paternal uncle, and daughters of your paternal aunts, and daughters of your maternal uncle, and daughters of your maternal aunts, who have migrated with you, and a believing woman who offers herself for (marrying) the prophet without dower, if the prophet wishes to bring her into his marriage, these rules being exclusive for you, and not for the (rest of the) believers,- We know what We have prescribed for them in respect of their wives and the slave-girls they own - so that there should be no difficulty for you. Allah is Most-Forgiving, Very-Merciful.'),
(3584, 33, 51, 6, 3, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'تُرۡجِیۡ مَنۡ تَشَآءُ مِنۡہُنَّ وَ تُــٔۡوِیۡۤ  اِلَیۡکَ مَنۡ تَشَآءُ ؕ وَ مَنِ ابۡتَغَیۡتَ مِمَّنۡ عَزَلۡتَ فَلَا جُنَاحَ عَلَیۡکَ ؕ ذٰلِکَ اَدۡنٰۤی  اَنۡ تَقَرَّ اَعۡیُنُہُنَّ وَ لَا یَحۡزَنَّ وَ یَرۡضَیۡنَ بِمَاۤ اٰتَیۡتَہُنَّ کُلُّہُنَّ ؕ وَ اللّٰہُ  یَعۡلَمُ  مَا فِیۡ  قُلُوۡبِکُمۡ ؕ وَ کَانَ اللّٰہُ عَلِیۡمًا حَلِیۡمًا ﴿۵۱﴾', 'اے پیغمبر ﷺ  تمکو یہ بھی اختیار ہے کہ جس بیوی کو چاہو پیچھے رکھو اور جسے چاہو اپنے پاس رکھو۔ اور جسکو تم نے پیچھے کر دیا ہو اگر اسکو پھر اپنے پاس طلب کر لو تو تم پر کچھ گناہ نہیں۔ یہ اجازت اس لئے ہے کہ انکی آنکھیں ٹھنڈی رہیں اور وہ رنجیدہ نہ ہوں اور جو کچھ تم انکو دو اسے لے کر سب خوش رہیں۔ اور جو کچھ تمہارے دلوں میں ہے اللہ اسے جانتا ہے۔ اور اللہ جاننے والا ہے بردبار ہے۔', 'پیچھے رکھ دے تو جس کو چاہو ان میں اور جگہ دے اپنے پاس جس کو چاہے اور جس کو جی چاہے تیرا ان میں سے جن کو کنارے کر دیا تھا تو کچھ گناہ نہیں تجھ پر [۷۳] اس میں قریب ہے کہ ٹھنڈی رہیں آنکھیں انکی اور غم نہ کھائیں اور راضی  رہیں اس پر جو تو نے دیا ان سب کی سب کو اور اللہ جانتا ہے جو کچھ تمہارے دلوں میں ہے اور ہے اللہ سب کچھ جاننے  والا تحمل والا [۷۴]', 'You (O Muhammad SAW) can postpone (the turn of) whom you will of them (your wives), and you may receive whom you will. And whomsoever you desire of those whom you have set aside (her turn temporarily), it is no sin on you (to receive her again), that is better; that they may be comforted and not grieved, and may all be pleased with what you give them. Allah knows what is in your hearts. And Allah is Ever AllKnowing, Most Forbearing.', 'You may postpone (the turn) of any one you wish from among them, and may accommodate with you any one you wish. And should you recall any one from those whom you kept aside, there is no blame on you. It is more likely, in this way, that their eyes will stay content, and they will not grieve, and all of them will be happy with whatever you give to them. Allah knows whatever lies in your hearts, and Allah is All-Knowing, All-Wise.'),
(3585, 33, 52, 6, 3, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'لَا یَحِلُّ  لَکَ النِّسَآءُ  مِنۡۢ بَعۡدُ وَ لَاۤ  اَنۡ تَبَدَّلَ  بِہِنَّ مِنۡ  اَزۡوَاجٍ وَّ لَوۡ  اَعۡجَبَکَ حُسۡنُہُنَّ  اِلَّا مَا مَلَکَتۡ یَمِیۡنُکَ ؕ وَ کَانَ اللّٰہُ  عَلٰی کُلِّ  شَیۡءٍ  رَّقِیۡبًا ﴿٪۵۲﴾', 'اے پیغمبر ﷺ انکے سوا اور عورتیں تمکو جائز نہیں اور نہ یہ کہ ان بیویوں کو چھوڑ کر اور بیویاں کر لو خواہ ان کا حسن تمکو کیسا ہی اچھا لگے مگر وہ جو تمہارے ہاتھ کا مال ہے یعنی باندیوں کے بارے میں تمکو اختیار ہے اور اللہ ہر چیز پر نگاہ رکھتا ہے۔', 'حلال نہیں تجھ کو عورتیں اسکے بعد اور نہ یہ کہ اُنکے بدلے کر لے اور عورتیں اگرچہ خوش لگے تجھ کو اُنکی صورت [۷۵] مگر جو مال ہو تیرے ہاتھ کا [۷۶] اور ہے اللہ ہر چیز پر نگہبان [۷۷]', 'It is not lawful for you (to marry other) women after this, nor to change them for other wives even though their beauty attracts you, except those (captives or slaves) whom your right hand possesses. And Allah is Ever a Watcher over all things.', 'No women are lawful for you after this, nor is it lawful that you replace them (the present wives) with other wives, even though their goodness may attract you, except the bond-women you own. And Allah is watchful of every thing.'),
(3586, 33, 53, 7, 4, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَدۡخُلُوۡا بُیُوۡتَ النَّبِیِّ  اِلَّاۤ اَنۡ یُّؤۡذَنَ لَکُمۡ  اِلٰی طَعَامٍ غَیۡرَ نٰظِرِیۡنَ  اِنٰىہُ ۙ وَ لٰکِنۡ  اِذَا دُعِیۡتُمۡ فَادۡخُلُوۡا فَاِذَا طَعِمۡتُمۡ فَانۡتَشِرُوۡا وَ لَا مُسۡتَاۡنِسِیۡنَ لِحَدِیۡثٍ ؕ اِنَّ ذٰلِکُمۡ کَانَ یُؤۡذِی النَّبِیَّ فَیَسۡتَحۡیٖ مِنۡکُمۡ ۫ وَ اللّٰہُ  لَا یَسۡتَحۡیٖ مِنَ الۡحَقِّ ؕ وَ اِذَا سَاَلۡتُمُوۡہُنَّ مَتَاعًا فَسۡـَٔلُوۡہُنَّ مِنۡ وَّرَآءِ  حِجَابٍ ؕ ذٰلِکُمۡ  اَطۡہَرُ  لِقُلُوۡبِکُمۡ  وَ قُلُوۡبِہِنَّ ؕ وَ مَا کَانَ لَکُمۡ اَنۡ تُؤۡذُوۡا رَسُوۡلَ اللّٰہِ وَ لَاۤ  اَنۡ تَنۡکِحُوۡۤا  اَزۡوَاجَہٗ مِنۡۢ بَعۡدِہٖۤ  اَبَدًا ؕ اِنَّ ذٰلِکُمۡ  کَانَ عِنۡدَ اللّٰہِ  عَظِیۡمًا ﴿۵۳﴾', 'مومنو! پیغمبر ﷺ کے گھروں میں نہ جایا کرو مگر اس صورت میں کہ تمکو اجازت دی جائے یعنی کھانے کیلئے بلایا جائے جبکہ اسکے پکنے کا انتظار بھی نہ کرنا پڑے لیکن جب تمہاری دعوت کی جائے تو جاؤ اور جب کھانا کھا چکو تو چل دو اور باتوں میں جی لگا کر نہ بیٹھ رہو۔ یہ بات پیغمبر ﷺ کو ایذا دیتی تھی اور وہ تم سے حیا کرتے تھے اور کہتے نہیں تھے لیکن اللہ سچی بات کے کہنے سے نہیں شرماتا۔ اور جب پیغمبر ﷺ کی بیویوں سے کوئی سامان مانگو تو پردے کے باہر سے مانگو۔ یہ تمہارے اور ان کے دلوں کے لئے بہت پاکیزگی کی بات ہے۔ اور تمکو یہ شایاں نہیں کہ رسول اللہ ﷺ کو تکلیف دو اور نہ یہ کہ انکی بیویوں سے کبھی انکے بعد نکاح کرو بیشک یہ اللہ کے نزدیک بڑا گناہ کا کام ہے۔', 'اے ایمان والو مت جاؤ نبی کے گھروں میں مگر جو تم کو حکم ہو کھانے کے واسطے نہ راہ دیکھنے والے اس کے پکنے کی لیکن جب تم کو بلائے تب جا ؤ [۷۸] پھر جب کھا چکو تو آپ آپ کو چلے جاؤ اور نہ آپس میں جی لگا کر بیٹھو باتوں میں [۷۹] اس بات سے تمہاری تکلیف تھی نبی کو پھر تم سے شرم کرتا ہے اور اللہ شرم نہیں کرتا ٹھیک بات بتلانے میں [۸۰] اور جب مانگنے جاؤ بیبیوں سے کچھ چیز کام کی تو مانگ لو پردہ کے باہر سے اس میں خوب ستھرائی ہے تمہارے دل کو اور ان کے دل کو [۸۱] اور تم کو نہیں پہنچتا کہ تکلیف دو اللہ کے رسول کو اور نہ یہ کہ نکاح کرو اسکی عورتوں سے اس کے پیچھے کبھی البتہ یہ تمہاری بات اللہ کے یہاں بڑا گناہ ہے [۸۲]', 'O you who believe! Enter not the Prophets houses, except when leave is given to you for a meal, (and then) not (so early as) to wait for its preparation. But when you are invited, enter, and when you have taken your meal, disperse, without sitting for a talk. Verily, such (behaviour) annoys the Prophet, and he is shy of (asking) you (to go), but Allah is not shy of (telling you) the truth. And when you ask (his wives) for anything you want, ask them from behind a screen, that is purer for your hearts and for their hearts. And it is not (right) for you that you should annoy Allahs Messenger, nor that you should ever marry his wives after him (his death). Verily! With Allah that shall be an enormity.', 'O you who believe, do not enter the houses of the Prophet, unless you are permitted for a meal, not (so early as) to wait for its preparation. But when you are invited, go inside. Then, once you have had the meal, just disperse, and (do) not (sit for long) being keen for a chat. This (conduct of yours) hurts the Prophet, but he feels shy of (telling) you (about it), but Allah is not shy of the truth. And when you ask any thing from them (the blessed wives of the Prophet), ask them from behind a curtain. That is better for the purity of your hearts and their hearts. It is not allowed for you that you hurt Allah’s Messenger, nor that you ever marry his wives after him. Indeed, it would be an enormity in the sight of Allah.'),
(3587, 33, 54, 7, 4, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'اِنۡ  تُبۡدُوۡا شَیۡئًا اَوۡ تُخۡفُوۡہُ  فَاِنَّ اللّٰہَ کَانَ بِکُلِّ شَیۡءٍ عَلِیۡمًا ﴿۵۴﴾', 'اگر تم کسی چیز کو ظاہر کرو یا اسکو مخفی رکھو تو یاد رکھو کہ اللہ ہر چیز سے باخبر ہے۔', 'اگر کھول کر کہو تم کسی چیز کو یا اسکو چھپاؤ سو اللہ ہے ہر چیز کو جاننے والا [۸۳]', 'Whether you reveal anything or conceal it, verily, Allah is Ever AllKnower of everything.', 'If you disclose any thing, or conceal it, Allah is All-Knowing about every thing.'),
(3588, 33, 55, 7, 4, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'لَا جُنَاحَ عَلَیۡہِنَّ فِیۡۤ  اٰبَآئِہِنَّ وَ لَاۤ اَبۡنَآئِہِنَّ  وَ لَاۤ  اِخۡوَانِہِنَّ وَ لَاۤ  اَبۡنَآءِ اِخۡوَانِہِنَّ وَ لَاۤ  اَبۡنَآءِ اَخَوٰتِہِنَّ وَ لَا نِسَآئِہِنَّ وَ لَا مَا مَلَکَتۡ اَیۡمَانُہُنَّ ۚ وَ اتَّقِیۡنَ اللّٰہَ ؕ اِنَّ اللّٰہَ کَانَ عَلٰی کُلِّ شَیۡءٍ  شَہِیۡدًا ﴿۵۵﴾', 'خواتین پر اپنے باپ داد سے پردہ نہ کرنے میں کچھ گناہ نہیں اور نہ اپنے بیٹوں سے اور نہ اپنے بھائیوں سے اور نہ اپنے بھتیجوں سے اور نہ اپنے بھانجوں سے نہ اپنی سی خواتین سے اور نہ اپنے باندی غلاموں سے اور اے خواتین اللہ سے ڈرتی رہو بیشک اللہ ہر چیز سے واقف ہے۔', 'گناہ نہیں ان عورتوں کو سامنے ہونے کا اپنے باپوں سے اور نہ اپنے بیٹوں سے اور نہ اپنے بھائیوں سے اور نہ اپنے بھائی کے بیٹوں سے اور نہ اپنی بہن کے بیٹوں سے اور نہ اپنی عورتوں سے اور نہ اپنے ہاتھ کے مال سے [۸۴] اور ڈرتی رہو اے عورتو اللہ سے بیشک اللہ کے سامنے ہے ہر چیز [۸۵]', 'It is no sin on them (the Prophets wives, if they appear unveiled) before their fathers, or their sons, or their brothers, or their brothers sons, or the sons of their sisters, or their own (believing) women, or their (female) slaves, and keep your duty to Allah. Verily, Allah is Ever AllWitness over everything.', 'There is no sin for them (the wives of the Prophet) in (appearing without Hijāb before) their fathers, or their brothers, or the sons of their brothers, or the sons of their sisters, or their own (Muslim) women, or their slave-girls. And (O wives of the Prophet,) fear Allah. Surely, Allah is witness to every thing.'),
(3589, 33, 56, 7, 4, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'اِنَّ اللّٰہَ وَ مَلٰٓئِکَتَہٗ  یُصَلُّوۡنَ عَلَی النَّبِیِّ ؕ یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا صَلُّوۡا عَلَیۡہِ  وَ سَلِّمُوۡا  تَسۡلِیۡمًا ﴿۵۶﴾', 'اللہ اور اسکے فرشتے اس پیغمبر ﷺ پر درورد بھیجتے ہیں۔ مومنو! تم بھی ان پر درور بھیجو اور خوب سلام بھیجا کرو۔', 'اللہ اور اس کے فرشتے رحمت بیجھتے ہیں رسول پر اے ایمان والو رحمت بھیجو اس پر اور سلام بھیجو سلام کہہ کر [۸۶]', 'Allah sends His Salat (Graces, Honours, Blessings, Mercy, etc.) on the Prophet (Muhammad SAW) and also His angels too (ask Allah to bless and forgive him). O you who believe! Send your Salat on (ask Allah to bless) him (Muhammad SAW), and (you should) greet (salute) him with the Islamic way of greeting (salutation i.e. AsSalamu Alaikum).', 'Surely, Allah and His angels send blessings to the Prophet. O you who believe, do pray Allah to bless him, and send your Salām (prayer for his being in peace) to him in abundance.'),
(3590, 33, 57, 7, 4, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'اِنَّ الَّذِیۡنَ یُؤۡذُوۡنَ اللّٰہَ  وَ رَسُوۡلَہٗ  لَعَنَہُمُ  اللّٰہُ  فِی الدُّنۡیَا وَ الۡاٰخِرَۃِ  وَ اَعَدَّ لَہُمۡ  عَذَابًا مُّہِیۡنًا ﴿۵۷﴾', 'جو لوگ اللہ اور اسکے پیغمبر ﷺ کو اذیت پہنچاتے ہیں ان پر اللہ دنیا اور آخرت میں لعنت کرتا ہے اور انکے لئے اس نے ذلیل کرنے والا عذاب تیار کر رکھا ہے۔', 'جو لوگ ستاتے ہیں اللہ کو اور اس کے رسول کو ان کو پھٹکارا اللہ نے دنیا میں اور آخرت میں اور تیار رکھا ہے ان کے واسطے ذلت کا عذاب [۸۷]', 'Verily, those who annoy Allah and His Messenger (SAW) Allah has cursed them in this world, and in the Hereafter, and has prepared for them a humiliating torment.', 'Surely, those who annoy Allah and His Messenger are cursed by Allah in this world and in the Hereafter, and He has prepared for them a humiliating punishment.'),
(3591, 33, 58, 7, 4, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'وَ الَّذِیۡنَ یُؤۡذُوۡنَ الۡمُؤۡمِنِیۡنَ وَ الۡمُؤۡمِنٰتِ بِغَیۡرِ  مَا اکۡتَسَبُوۡا فَقَدِ احۡتَمَلُوۡا بُہۡتَانًا وَّ  اِثۡمًا مُّبِیۡنًا ﴿٪۵۸﴾', 'اور جو لوگ مومن مردوں اور مومن عورتوں کو ایسے کام کی تہمت سے جو انہوں نے نہ کیا ہو ایذا دیں تو انہوں نے بہتان کا اور کھلے گناہ کا بوجھ اپنے سر پر رکھا۔', 'اور جو لوگ تمہت لگاتے ہیں مسلمان  مردوں کو اور مسلمان عورتوں کو بدون گناہ کیے تو اٹھایا انہوں نے بوجھ جھوٹ کا اور صریح گناہ کا [۸۸]', 'And those who annoy believing men and women undeservedly, bear on themselves the crime of slander and plain sin.', 'As for those who hurt believing men and believing women without their having done anything (wrong), they shall bear the burden of slander and a manifest sin.'),
(3592, 33, 59, 8, 5, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'یٰۤاَیُّہَا النَّبِیُّ  قُلۡ  لِّاَزۡوَاجِکَ  وَ  بَنٰتِکَ وَ نِسَآءِ الۡمُؤۡمِنِیۡنَ یُدۡنِیۡنَ عَلَیۡہِنَّ مِنۡ جَلَابِیۡبِہِنَّ ؕ ذٰلِکَ اَدۡنٰۤی اَنۡ یُّعۡرَفۡنَ فَلَا  یُؤۡذَیۡنَ ؕ وَ کَانَ اللّٰہُ غَفُوۡرًا رَّحِیۡمًا ﴿۵۹﴾', 'اے پیغمبر ﷺ اپنی بیویوں اور بیٹیوں اور مسلمانوں کی عورتوں سے کہدو کہ باہر نکلا کریں تو اپنے چہروں پر چادر لٹکا کر گھونگھٹ نکال لیا کریں۔ یہ چیز انکے لئے موجب شناخت و امتیاز ہو گی تو کوئی انکو ایذا نہ دے گا۔ اور اللہ بخشنے والا ہے مہربان ہے۔', 'اے نبی کہہ دے اپنی عورتوں کو اور اپنی بیٹیوں کو اور مسلمانوں کی عورتوں کو نیچے لٹکا لیں اپنے اوپر تھوڑی سی اپنی چادریں [۸۹] اس میں بہت قریب ہے کہ پہچانی پڑیں تو کوئی انکو نہ ستائے اور ہے اللہ بخشنے والا مہربان [۹۰]', 'O Prophet! Tell your wives and your daughters and the women of the believers to draw their cloaks (veils) all over their bodies (i.e.screen themselves completely except the eyes or one eye to see the way). That will be better, that they should be known (as free respectable women) so as not to be annoyed. And Allah is Ever OftForgiving, Most Merciful.', 'O prophet, tell your wives and your daughters and the women of the believers that they should draw down their shawls over them. That will make it more likely that they are recognized, hence not teased. And Allah is Most-Forgiving, Very-Merciful.'),
(3593, 33, 60, 8, 5, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'لَئِنۡ لَّمۡ  یَنۡتَہِ  الۡمُنٰفِقُوۡنَ وَ الَّذِیۡنَ فِیۡ قُلُوۡبِہِمۡ  مَّرَضٌ وَّ الۡمُرۡجِفُوۡنَ فِی الۡمَدِیۡنَۃِ  لَنُغۡرِیَنَّکَ بِہِمۡ ثُمَّ لَا یُجَاوِرُوۡنَکَ  فِیۡہَاۤ   اِلَّا   قَلِیۡلًا ﴿ۖۛۚ۶۰﴾', 'اگر منافق اور وہ لوگ جنکے دلوں میں روگ ہے اور جو مدینے کے شہر میں بری بری خبریں اڑایا کرتے ہیں اپنی حرکتوں سے باز نہ آئیں گے تو ہم تمکو انکے پیچھے لگا دیں گے پھر وہ تمہارے پڑوس میں نہ رہ سکیں گے مگر تھوڑے دن۔', 'البتہ اگر باز نہ آئے منافق اور جن کے دل میں روگ ہے [۹۱] اور جھوٹی خبریں اڑانے والے مدینہ میں [۹۲] تو ہم لگا دیں گے تجھ کو ان کے پیچھے پھر نہ رہنے پائیں گے تیرے ساتھ اس شہر میں مگر تھوڑے  دنوں', 'If the hypocrites, and those in whose hearts is a disease (evil desire for adultery, etc.), and those who spread false news among the people in AlMadinah, cease not, We shall certainly let you overpower them, then they will not be able to stay in it as your neighbours but a little while.', 'If the hypocrites and those having malady in their hearts and the ones who spread rumors in Madīnah do not stop (their evil deeds), We will certainly stir you up against them, then they shall no longer live in it as your neighbors, but for a little while,'),
(3594, 33, 61, 8, 5, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'مَّلۡعُوۡنِیۡنَ ۚۛ اَیۡنَمَا ثُقِفُوۡۤا اُخِذُوۡا وَ قُتِّلُوۡا  تَقۡتِیۡلًا  ﴿۶۱﴾', 'وہ بھی پھٹکارے ہوئے جہاں پائے گئے پکڑے گئے اور جان سے مار ڈالے گئے۔', 'پھٹکارے ہوئے جہاں پائے گئے  پکڑے گئے اور مارے گئے جان سے [۹۳]', 'Accursed, wherever found, they shall be seized and killed with a (terrible) slaughter.', '(and that too in a state of being) accursed. Wherever they are found, they shall be seized, and shall be killed thoroughly'),
(3595, 33, 62, 8, 5, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'سُنَّۃَ اللّٰہِ  فِی الَّذِیۡنَ خَلَوۡا مِنۡ قَبۡلُ ۚ وَ لَنۡ  تَجِدَ لِسُنَّۃِ  اللّٰہِ تَبۡدِیۡلًا ﴿۶۲﴾', 'جو لوگ پہلے گذر چکے ہیں انکے بارے میں بھی اللہ کی یہی عادت رہی ہے اور تم اللہ کی عادت میں تغیروتبدل نہ پاؤ گے۔', 'دستور پڑا ہوا ہے اللہ کا ان لوگوں میں جو  پہلے ہو چکے ہیں اور تو نہ دیکھے گا اللہ کی چال بدلتی [۹۴]', 'That was the Way of Allah in the case of those who passed away of old, and you will not find any change in the Way of Allah.', '- a consistent practice of Allah in the matter of those who have gone before. And you will never find a change in Allah’s consistent practice.'),
(3596, 33, 63, 8, 5, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'یَسۡـَٔلُکَ النَّاسُ عَنِ السَّاعَۃِ ؕ قُلۡ  اِنَّمَا عِلۡمُہَا عِنۡدَ اللّٰہِ ؕ وَ مَا یُدۡرِیۡکَ لَعَلَّ  السَّاعَۃَ   تَکُوۡنُ  قَرِیۡبًا ﴿۶۳﴾', 'لوگ تم سے قیامت کی نسبت دریافت کرتے ہیں کہ کب آئے گی کہدو کہ اس کا علم اللہ ہی کو ہے۔ اور تمہیں کیا پتہ ہو سکتا ہے کہ قیامت قریب ہی آ گئ ہو۔', 'لوگ تجھ سے پوچھتے ہیں قیامت کو تو کہہ اس کی خبر ہے اللہ ہی کے پاس اور تو کیا جانے شاید وہ گھڑی پاس ہی ہو [۹۵]', 'People ask you concerning the Hour, say: \"The knowledge of it is with Allah only. What do you know? It may be that the Hour is near!\"', 'People ask you about the Hour (i.e. the Day of Judgment). Say,” Its knowledge is only with Allah.” And what can let you know? May be, the Hour is near.'),
(3597, 33, 64, 8, 5, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'اِنَّ اللّٰہَ  لَعَنَ الۡکٰفِرِیۡنَ وَ اَعَدَّ لَہُمۡ سَعِیۡرًا ﴿ۙ۶۴﴾', 'بیشک اللہ نے کافروں پر لعنت کی ہے اور انکے لئے جہنم کی آگ تیار کر رکھی ہے۔', 'بیشک اللہ نے پھٹکار دیا ہے منکروں کو اور  رکھی ہے انکے واسطے دہکتی ہوئی آگ [۹۶]', 'Verily, Allah has cursed the disbelievers, and has prepared for them a flaming Fire (Hell).', 'Surely, Allah has cursed the infidels, and has prepared for them a flaming fire,'),
(3598, 33, 65, 8, 5, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'خٰلِدِیۡنَ فِیۡہَاۤ  اَبَدًا ۚ لَا یَجِدُوۡنَ وَلِیًّا وَّ لَا  نَصِیۡرًا ﴿ۚ۶۵﴾', 'اس میں وہ ہمیشہ ہمیشہ رہیں گے نہ کسی کو دوست پائیں گے اور نہ مددگار۔', 'رہا کریں اسی میں ہمیشہ نہ پائیں کوئی حمایتی اور نہ مددگار', 'Wherein they will abide for ever, and they will find neither a Walee (a protector) nor a helper.', 'wherein they will live forever, finding no one to protect or to help.'),
(3599, 33, 66, 8, 5, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'یَوۡمَ تُقَلَّبُ وُجُوۡہُہُمۡ فِی النَّارِ یَقُوۡلُوۡنَ یٰلَیۡتَنَاۤ  اَطَعۡنَا اللّٰہَ  وَ اَطَعۡنَا الرَّسُوۡلَا ﴿۶۶﴾', 'جس دن انکے چہرے آگ میں الٹ پلٹ کئے جائیں تو کہیں گے اے کاش ہم اللہ کی فرمانبرداری کرتے اور رسول ﷺ کا حکم مانتے۔', 'جس دن اوندھے ڈالے جائیں گے ان کے منہ آگ میں [۹۷] کہیں گے کیا اچھا ہوتا جو ہم نے کہا مانا ہوتا اللہ کا اور کہا مانا ہوتا رسول کا [۹۸]', 'On the Day when their faces will be turned over in the Fire, they will say: \"Oh, would that we had obeyed Allah and obeyed the Messenger (Muhammad SAW).\"', 'The Day their faces will be rolled in the fire, they will say, “Oh, would that we had obeyed Allah and obeyed the Messenger!”.'),
(3600, 33, 67, 8, 5, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'وَ قَالُوۡا رَبَّنَاۤ  اِنَّاۤ  اَطَعۡنَا سَادَتَنَا وَ کُبَرَآءَنَا  فَاَضَلُّوۡنَا السَّبِیۡلَا ﴿۶۷﴾', 'اور کہیں گے اے ہمارے پروردگار ہم نے اپنے سرداروں اور بڑوں کا کہا مانا تو انہوں نے ہمکو رستے سے بھٹکا دیا۔', 'اور کہیں گے اے رب ہم نے کہا مانا اپنے سرداروں کا اور اپنے بڑوں کا پھر انہوں نے چکا دیا ہم کو راہ سے', 'And they will say: \"Our Lord! Verily, we obeyed our chiefs and our great ones, and they misled us from the (Right) Way.', 'And they will say, “Our Lord, we obeyed our chiefs and our elders, and they made us to go astray from the path.'),
(3601, 33, 68, 8, 5, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'رَبَّنَاۤ  اٰتِہِمۡ ضِعۡفَیۡنِ مِنَ الۡعَذَابِ وَ الۡعَنۡہُمۡ  لَعۡنًا کَبِیۡرًا ﴿٪۶۸﴾', 'اے ہمارے پروردگار انکو دگنا عذاب دے اور ان پر بڑی لعنت کر۔', 'اے رب ان کو دے دونا عذاب اور پھٹکار انکو بڑی پھٹکار [۹۹]', 'Our Lord! give them double torment and curse them with a mighty curse!\"', 'Our Lord, give them twice the punishment, and send a curse on them, an enormous curse.'),
(3602, 33, 69, 9, 6, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَکُوۡنُوۡا کَالَّذِیۡنَ اٰذَوۡا مُوۡسٰی فَبَرَّاَہُ  اللّٰہُ مِمَّا قَالُوۡا ؕ وَ کَانَ عِنۡدَ اللّٰہِ  وَجِیۡہًا  ﴿ؕ۶۹﴾', 'مومنو! تم ان لوگوں جیسے نہ ہونا جنہوں نے موسٰی کو عیب لگا کر رنج پہنچایا تو اللہ نے انکو بےعیب ثابت کر دیا اور وہ اللہ کے نزدیک آبرو والے تھے۔', 'اے ایمان والو تم مت ہو ان جیسے جنہوں نے ستایا موسٰی کو پھر بے عیب دکھلا دیا اسکو اللہ نے انکے کہنے سے اور تھا اللہ کے  یہاں آبرو والا [۱۰۰]', 'O you who believe! Be not like those who annoyed Moosa (Moses), but Allah cleared him of that which they alleged, and he was honourable before Allah.', 'O you who believe, be not like those who annoyed Mūsā, then Allah cleared him of what they alleged; and he was honorable in the sight of Allah.'),
(3603, 33, 70, 9, 6, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوا اتَّقُوا اللّٰہَ وَ قُوۡلُوۡا  قَوۡلًا  سَدِیۡدًا  ﴿ۙ۷۰﴾', 'مومنو! اللہ سے ڈرا کرو اور بات سیدھی کہا کرو۔', 'اے ایمان والو ڈرتے رہو اللہ سے اور کہو بات سیدھی', 'O you who believe! Keep your duty to Allah and fear Him, and speak (always) the truth.', 'O you who believe, fear Allah, and speak in straightforward words.'),
(3604, 33, 71, 9, 6, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'یُّصۡلِحۡ  لَکُمۡ  اَعۡمَالَکُمۡ وَ یَغۡفِرۡ لَکُمۡ ذُنُوۡبَکُمۡ ؕ وَ مَنۡ یُّطِعِ اللّٰہَ  وَ رَسُوۡلَہٗ  فَقَدۡ  فَازَ  فَوۡزًا عَظِیۡمًا ﴿۷۱﴾', 'وہ تمہارے سب کام سنوار دے گا اور تمہارے گناہ بخش دے گا۔ اور جو شخص اللہ اور اسکے رسول ﷺ کی فرمانبرداری کرے گا تو بیشک بڑی مراد پائے گا۔', 'کہ سنوار دے تمہارے واسطے تمہارے کام اور بخشدے تم کو تمہارے گناہ اور جو کوئی کہنے پر چلا اللہ کے اور اس کے رسول کے اس نے پائی بڑی مراد [۱۰۱]', 'He will direct you to do righteous good deeds and will forgive you your sins. And whosoever obeys Allah and His Messenger (SAW) he has indeed achieved a great achievement (i.e. he will be saved from the Hell-fire and made to enter Paradise).', '(If you do so,) Allah will correct your deeds for your benefit, and forgive your sins for you. Whoever obeys Allah and His Messenger achieves a great success.'),
(3605, 33, 72, 9, 6, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'اِنَّا عَرَضۡنَا الۡاَمَانَۃَ عَلَی السَّمٰوٰتِ وَ الۡاَرۡضِ وَ الۡجِبَالِ فَاَبَیۡنَ اَنۡ یَّحۡمِلۡنَہَا وَ اَشۡفَقۡنَ مِنۡہَا وَ حَمَلَہَا الۡاِنۡسَانُ ؕ اِنَّہٗ کَانَ ظَلُوۡمًا جَہُوۡلًا ﴿ۙ۷۲﴾', 'ہم نے بار امانت کو آسمانوں اور زمین اور پہاڑوں پر پیش کیا تو انہوں نے اسکے اٹھانے سے انکار کیا اور اس سے ڈر گئے۔ اور انسان نے اسکو اٹھا لیا۔ بیشک وہ بڑا ظالم بڑا جاہل ہے۔', 'ہم نے دکھلائی امانت آسمانوں کو اور زمین کو اور پہاڑوں کو پھر کسی نے قبول نہ کیا کہ اس کو اٹھائیں اورا س سے ڈر گئے اور اٹھا لیا اس کو انسان نے یہ ہے بڑا بے ترس نادان [۱۰۲]', 'Truly, We did offer AlAmanah (the trust or moral responsibility or honesty and all the duties which Allah has ordained) to the heavens and the earth, and the mountains, but they declined to bear it and were afraid of it (i.e. afraid of Allahs Torment). But man bore it. Verily, he was unjust (to himself) and ignorant (of its results).', 'We did offer the Trust to the heavens and the earth and the mountains, but they refused to bear its burden and were afraid of it, and man picked it up. Indeed he is unjust (to himself), unaware (of the end).'),
(3606, 33, 73, 9, 6, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'الاحزاب', 'لِّیُعَذِّبَ اللّٰہُ  الۡمُنٰفِقِیۡنَ وَ الۡمُنٰفِقٰتِ وَ الۡمُشۡرِکِیۡنَ وَ الۡمُشۡرِکٰتِ وَ یَتُوۡبَ اللّٰہُ عَلَی الۡمُؤۡمِنِیۡنَ وَ  الۡمُؤۡمِنٰتِ ؕ وَ کَانَ اللّٰہُ  غَفُوۡرًا  رَّحِیۡمًا ﴿٪۷۳﴾', 'تاکہ اللہ منافق مردوں اور منافق عورتوں اور مشرک مردوں اور مشرک عورتوں کو عذاب دے اور اللہ مومن مردوں اور مومن عورتوں پر مہربانی کرے۔ اور اللہ تو بخشنے والا ہے مہربان ہے۔', 'تاکہ عذاب کرے اللہ منافق مردوں کو اور عورتوں کو اور شرک والے مردوں کو اور عورتوں کو اور معاف کرے اللہ ایمان دار مردوں کو اور عورتوں کو اور ہے اللہ بخشنے والا مہربان [۱۰۳]', 'So that Allah will punish the hypocrites, men and women, and the men and women who are AlMushrikoon (the polytheists, idolaters, pagans, disbelievers in the Oneness of Allah, and in His Messenger Muhammad SAW ). And Allah will pardon (accept the repentance of) the true believers of the Islamic Monotheism, men and women. And Allah is Ever OftForgiving, Most Merciful.', 'The result (of all this) is that Allah will punish the hypocrites, men and women, and the Mushriks, men and women, and will accept the repentance of the believing men and women. Surely Allah is Most-Forgiving, Very-Merciful.'),
(3607, 34, 1, 1, 7, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'اَلۡحَمۡدُ لِلّٰہِ الَّذِیۡ لَہٗ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ وَ لَہُ  الۡحَمۡدُ فِی الۡاٰخِرَۃِ ؕ وَ ہُوَ  الۡحَکِیۡمُ  الۡخَبِیۡرُ ﴿۱﴾', 'سب تعریف اللہ ہی کیلئے ہے جو سب چیزوں کا مالک ہے یعنی وہ کہ جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے سب اسی کا ہے اور آخرت میں بھی اسی کی تعریف ہے۔ اور وہ حکمت والا ہے خبردار ہے۔', 'سب خوبی اللہ کی ہے جس کا ہے جو کچھ کہ ہے آسمان اور زمین میں اور اسی کی تعریف ہے آخرت میں اور  وہی ہے حکمتوں والا سب کچھ جاننے والا [۱]', 'All the praises and thanks be to Allah, to Whom belongs all that is in the heavens and all that is in the earth. His is all the praises and thanks in the Hereafter, and He is the AllWise, the AllAware.', 'Praise be to Allah, to whom belongs all that is in the heavens and all that is on the earth; and for Him is the praise in the Hereafter, and He is the Wise, the All-Aware.'),
(3608, 34, 2, 1, 7, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'یَعۡلَمُ مَا یَلِجُ فِی الۡاَرۡضِ وَ مَا یَخۡرُجُ مِنۡہَا وَ مَا یَنۡزِلُ مِنَ السَّمَآءِ وَ مَا یَعۡرُجُ  فِیۡہَا ؕ وَ ہُوَ الرَّحِیۡمُ  الۡغَفُوۡرُ ﴿۲﴾', 'جو کچھ زمین میں داخل ہوتا ہے اور جو اس میں سے نکلتا ہے اور جو آسمان سے اترتا ہے اور جو اس پر چڑھتا ہے سب اسکو معلوم ہے اور وہ مہربان ہے بخشنے والا ہے۔', 'جانتا ہے جو کچھ کہ اندر گھستا ہے زمین کے اور جو کچھ کہ نکتا ہے اس سے اور جو  اترتا ہے آسمان سے اور جو چڑھتا ہے اس میں [۲] اور وہی ہے رحم  والا بخشنے والا [۳]', 'He knows that which goes into the earth and that which comes forth from it, and that which descend from the heaven and that which ascends to it. And He is the Most Merciful, the OftForgiving.', 'He knows all that goes into the earth and all that comes out from it, and all that comes down from the sky and all that ascends thereto. He is the Very-Merciful, the Most-Forgiving.'),
(3609, 34, 3, 1, 7, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ قَالَ الَّذِیۡنَ کَفَرُوۡا لَا تَاۡتِیۡنَا السَّاعَۃُ ؕ قُلۡ  بَلٰی وَ رَبِّیۡ  لَتَاۡتِیَنَّکُمۡ ۙ عٰلِمِ الۡغَیۡبِ ۚ لَا  یَعۡزُبُ عَنۡہُ  مِثۡقَالُ ذَرَّۃٍ  فِی السَّمٰوٰتِ وَ لَا فِی الۡاَرۡضِ وَ لَاۤ  اَصۡغَرُ مِنۡ ذٰلِکَ وَ لَاۤ  اَکۡبَرُ اِلَّا فِیۡ کِتٰبٍ مُّبِیۡنٍ ٭ۙ﴿۳﴾', 'اور کافر کہتے ہیں کہ قیامت کی گھڑی ہم پر نہیں آئے گی۔ کہدو کیوں نہیں آئے گی میرے پروردگار کی قسم وہ تم پر ضرور آ کر رہے گی وہ پروردگار غیب کا جاننے والا ہے ذرہ بھر چیز بھی اس سے پوشیدہ نہیں نہ آسمانوں میں اور نہ زمین میں اور کوئی چیز ذرے سے بھی بڑی یا چھوٹی نہیں مگر کتاب روشن میں لکھی ہوئی ہے۔', 'اور کہنے لگے منکر نہ آئے گی ہم پر قیامت [۴] تو کہہ کیوں نہیں قسم ہے میرے رب کی البتہ آئے گی تم  پر [۵] اس عالم الغیب کی غائب نہیں ہو سکتا اس سے کچھ ذرہ بھر آسمانوں میں اور نہ زمین میں اور کوئی چیز نہیں اس سےچھوٹی اور نہ اس سے بڑی جو نہیں ہے کھلی کتاب میں [۶]', 'Those who disbelieve say: \"The Hour will not come to us.\" Say: \"Yes, by my Lord, it will come to you.\" (Allah, He is) the AllKnower of the unseen, not even the weight of an atom (or a small ant) or less than that or greater, escapes from His Knowledge in the heavens or in the earth, but it is in a Clear Book (AlLauh AlMahfooz).', 'Said those who disbelieve, “The Hour (i.e. the Day of Judgment) will not come to us.” Say, “Why not? By my Lord, the knower of the Unseen, it will come to you.” Nothing in the heavens and in the earth, even to the measure of a particle, can escape Him, nor is there anything smaller than that or bigger, but it is recorded in a manifest book.'),
(3610, 34, 4, 1, 7, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'لِّیَجۡزِیَ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ ؕ اُولٰٓئِکَ لَہُمۡ مَّغۡفِرَۃٌ  وَّ رِزۡقٌ کَرِیۡمٌ  ﴿۴﴾', 'اس لئے کہ جو لوگ ایمان لائے اور عمل نیک کرتے رہے انکو بدلہ دے۔ یہی ہیں جنکے لئے بخشش اور عزت کی روزی ہے۔', 'تاکہ بدلا دے انکو جو یقین لائے اور کئے بھلے کام وہ لوگ جو ہیں ان کے لئے ہے معافی اور عزت کی روزی', 'That He may recompense those who believe (in the Oneness of Allah Islamic Monotheism) and do righteous good deeds. Those, theirs is forgiveness and Rizqun Kareem (generous provision, i.e. Paradise).', '(The Hour will come,) so that He rewards those who believed and did righteous deeds. For such people, there is forgiveness (from Allah) and a noble provision.'),
(3611, 34, 5, 1, 7, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ الَّذِیۡنَ سَعَوۡ فِیۡۤ  اٰیٰتِنَا مُعٰجِزِیۡنَ اُولٰٓئِکَ  لَہُمۡ  عَذَابٌ  مِّنۡ  رِّجۡزٍ  اَلِیۡمٌ ﴿۵﴾', 'اور جنہوں نے ہماری آیتوں کے بارے میں ہمیں ہرانے کی کوشش کی انکے لئے سخت درد دینے والے عذاب کی سزا ہے۔', 'اور جو لوگ دوڑے ہماری آیتوں کے ہرانے کو ان کو بلا کا عذاب ہے دردناک [۷]', 'But those who strive against Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) to frustrate them, those, for them will be a severe painful torment.', 'As for those who strived against Our signs to defeat (the messenger), for such people there is a painful punishment of the divine wrath.'),
(3612, 34, 6, 1, 7, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ  یَرَی الَّذِیۡنَ اُوۡتُوا الۡعِلۡمَ الَّذِیۡۤ  اُنۡزِلَ  اِلَیۡکَ مِنۡ رَّبِّکَ ہُوَ الۡحَقَّ ۙ وَ یَہۡدِیۡۤ   اِلٰی  صِرَاطِ الۡعَزِیۡزِ  الۡحَمِیۡدِ ﴿۶﴾', 'اور جن لوگوں کو علم دیا گیا ہے وہ جانتے ہیں کہ جو قرآن تمہارے پروردگار کی طرف سے تم پر نازل ہوا ہے وہ یقینًا حق ہے۔ اور اس اللہ کا رستہ بتاتا ہے جو غالب ہے قابل تعریف ہے۔', 'اور دیکھ لیں جن کو ملی ہے سمجھ کہ جو تجھ پر  اترا  تیرے رب سے وہی ٹھیک ہے اور سجھاتا ہے راہ  اس زبردست خوبیوں والے کی [۸]', 'And those who have been given knowledge see that what is revealed to you (O Muhammad SAW) from your Lord is the truth, and guides to the Path of the Exalted in Might, Owner of all praise.', 'Those who are blessed with knowledge see that what is sent to you from your Lord is the truth, and it guides (people) to the path of the All-Mighty, the Ever-Praised.'),
(3613, 34, 7, 1, 7, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ قَالَ الَّذِیۡنَ  کَفَرُوۡا ہَلۡ نَدُلُّکُمۡ عَلٰی رَجُلٍ یُّنَبِّئُکُمۡ  اِذَا مُزِّقۡتُمۡ کُلَّ  مُمَزَّقٍ ۙ اِنَّکُمۡ لَفِیۡ خَلۡقٍ جَدِیۡدٍ ۚ﴿۷﴾', 'اور کافر کہتے ہیں کہ بھلا ہم تمہیں ایسا آدمی بتائیں جو تمہیں خبر دیتا ہے کہ جب تم مر کر بالکل ریزہ ریزہ ہو جاؤ گے تم نئے سرے سے پیدا ہو گے۔', 'اور کہنے لگے منکر ہم بتلائیں تمکو  ایک مرد کہ تم کو خبر دیتا ہے جب تم پھٹ کر ہو جاؤ ٹکڑے ٹکڑے تم کو پھر نئے سرے سے بننا ہے', 'Those who disbelieve say: \"Shall we direct you to a man (Muhammad SAW) who will tell you (that) when you have become fully disintegrated into dust with full dispersion, then, you will be created (again) anew?\"', 'And the disbelievers said, “Shall we point out to you a man who informs you that, when you are totally torn into pieces, you shall be (raised) in a new creation?”'),
(3614, 34, 8, 1, 7, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'اَفۡتَرٰی عَلَی اللّٰہِ کَذِبًا اَمۡ بِہٖ جِنَّۃٌ ؕ بَلِ الَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِالۡاٰخِرَۃِ  فِی الۡعَذَابِ  وَ الضَّلٰلِ  الۡبَعِیۡدِ ﴿۸﴾', 'یا تو اس نے اللہ پر جھوٹ باندھ لیا ہے۔ یا اسے جنون ہے۔ بات یہ ہے کہ جو لوگ آخرت پر ایمان نہیں رکھتے وہ آفت اور پرلے درجے کی گمراہی میں پڑے ہیں۔', 'کیا بنا لایا ہے اللہ پر جھوٹ یا ا سکو سودا ہے [۹] کچھ بھی نہیں پر جو یقین نہیں رکھتے آخرت کا آفت میں ہیں اور دور جا پڑے غلطی میں [۱۰]', 'Has he (Muhammad SAW) invented a lie against Allah, or is there a madness in him? Nay, but those who disbelieve in the Hereafter are (themselves) in a torment, and in far error.', 'Has he forged a lie against Allah, or is there a madness in him?” No, but those who do not believe in the Hereafter are in torment and far astray from the right path.'),
(3615, 34, 9, 1, 7, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'اَفَلَمۡ یَرَوۡا اِلٰی مَا بَیۡنَ اَیۡدِیۡہِمۡ وَ مَا خَلۡفَہُمۡ مِّنَ السَّمَآءِ وَ الۡاَرۡضِ ؕ اِنۡ نَّشَاۡ نَخۡسِفۡ بِہِمُ  الۡاَرۡضَ اَوۡ نُسۡقِطۡ عَلَیۡہِمۡ کِسَفًا مِّنَ  السَّمَآءِ ؕ اِنَّ  فِیۡ ذٰلِکَ لَاٰیَۃً  لِّکُلِّ عَبۡدٍ مُّنِیۡبٍ  ٪﴿۹﴾', 'کیا انہوں نے اسکو نہیں دیکھا جو انکے آگے اور پیچھے ہے یعنی آسمان اور زمین۔ اگر ہم چاہیں تو انکو زمین میں دھنسا دیں یا ان پر آسمان کے ٹکڑے گرا دیں۔ اس میں ہر بندے کے لئے جو رجوع کرنے والا ہے ایک نشانی ہے۔', 'کیا دیکھتے نہیں جو کچھ ان کے آگے ہے اور پیچھے ہے آسمان اور زمین سے اگر ہم چاہیں دھنسا دیں ان کو زمین میں یا گرا دیں ان پر ٹکڑا  آسمان سے [۱۱] تحقیق اس میں نشانی ہے ہر بندے رجوع کرنے  والے کے  واسطے [۱۲]', 'See they not what is before them and what is behind them, of the heaven and the earth? If We will, We shall sink the earth with them, or cause a piece of the heaven to fall upon them. Verily, in this is a sign for every faithful believer that (believes in the Oneness of Allah), and turns to Allah (in all affairs with humility and in repentance).', 'Have they not, then, looked to the sky and the earth that lies before them and behind them? If We so will, We would make the earth swallow them up, or cause pieces of the sky to fall upon them. Surely, in this there is a sign for a servant (of Allah) who turns to Him.'),
(3616, 34, 10, 2, 8, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ لَقَدۡ اٰتَیۡنَا دَاوٗدَ  مِنَّا فَضۡلًا ؕ یٰجِبَالُ اَوِّبِیۡ  مَعَہٗ  وَ الطَّیۡرَ ۚ وَ اَلَنَّا لَہُ  الۡحَدِیۡدَ ﴿ۙ۱۰﴾', 'اور ہم نے داؤد کو اپنی طرف سے برتری بخشی تھی۔ اور کہا تھا اے پہاڑو انکے ساتھ تسبیح کرو اور پرندوں کو ان کا مسخر کر دیا اور انکے لئے ہم نے لوہے کو نرم کر دیا۔', 'اور ہم نے دی ہے داؤد کو  اپنی طرف سے بڑائی [۱۳] اے پہاڑو خوش آوازی سے پڑھو  اسکے ساتھ اور اڑتے جانوروں کو [۱۴] اور نرم کر دیا ہم نے اس کے آگے لوہا', 'And indeed We bestowed grace on David from Us (saying): \"O you mountains. Glorify (Allah) with him! And you birds (also)! And We made the iron soft for him.\"', 'Surely We bestowed grace on Dawūd from Us: “O mountains, pronounce with him Allah’s purity repeatedly - and you too O birds!” And We made the iron soft for him'),
(3617, 34, 11, 2, 8, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'اَنِ اعۡمَلۡ سٰبِغٰتٍ وَّ قَدِّرۡ فِی السَّرۡدِ وَ اعۡمَلُوۡا صَالِحًا ؕ اِنِّیۡ  بِمَا تَعۡمَلُوۡنَ بَصِیۡرٌ  ﴿۱۱﴾', 'کہ کشادہ زرہیں بناؤ اور کڑیوں کو اندازہ سے جوڑو اور نیک عمل کرو جو عمل تم کرتے ہو میں انکو دیکھنے والا ہوں۔', 'کہ بنا زرہیں کشادہ اور اندازے سے جوڑ کڑیاں [۱۵] اور کرو تم سب کام بھلا میں جو کچھ  تم کرتے ہو دیکھتا ہوں [۱۶]', 'Saying: \"Make you perfect coats of mail, balancing well the rings of chain armour, and work you (men) righteousness. Truly, I am AllSeer of what you do.\"', '(saying to him,) “Make coats of armour, and maintain balance in combining rings, and do, all of you, righteous deeds. Surely I am watchful of what you do.”'),
(3618, 34, 12, 2, 8, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ لِسُلَیۡمٰنَ الرِّیۡحَ غُدُوُّہَا شَہۡرٌ وَّ رَوَاحُہَا شَہۡرٌ ۚ وَ اَسَلۡنَا لَہٗ  عَیۡنَ الۡقِطۡرِ ؕ وَ مِنَ الۡجِنِّ مَنۡ یَّعۡمَلُ بَیۡنَ یَدَیۡہِ  بِاِذۡنِ رَبِّہٖ ؕ وَ مَنۡ یَّزِغۡ مِنۡہُمۡ عَنۡ اَمۡرِنَا نُذِقۡہُ  مِنۡ عَذَابِ السَّعِیۡرِ ﴿۱۲﴾', 'اور ہوا کو ہم نے سلیمان کے تابع کر دیا تھا اسکی صبح کی منزل ایک مہینے کی راہ ہوتی اور شام کی منزل بھی مہینے بھر کی ہوتی۔ اور انکے لئے ہم نے تانبے کا چشمہ بہا دیا تھا اور جنوں میں سے ایسے تھے جو انکے پروردگار کے حکم سے انکے آگے کام کرتے تھے اور جو کوئی ان میں سے ہمارے حکم کیخلاف کرے گا اسکو ہم جہنم کی آگ کا مزہ چکھائیں گے۔', 'اور مسخر کردیا سلیمان کے آگے ہوا کو صبح کی منزل اسکی ایک مہینہ اور شام کی منزل ایک مہینہ کی اور بہا د یا ہم نے اسکے واسطے چشمہ پگھلے ہوئے تانبے کا [۱۷] اور جنوں میں کتنے لوگ تھے جو محنت کرتے اس کے سامنے اسکے رب کے حکم سے اور جوکوئی پھرے ان میں سے ہمارے حکم سے چکھائیں ہم اسکو  آگ کا عذاب [۱۸]', 'And to Solomon (We subjected) the wind, its morning (stride from sunrise till midnoon) was a months (journey), and its afternoon (stride from the midday decline of the sun to sunset) was a months (journey i.e. in one day he could travel two months journey). And We caused a fount of (molten) brass to flow for him, and there were jinns that worked in front of him, by the Leave of his Lord, and whosoever of them turned aside from Our Command, We shall cause him to taste of the torment of the blazing Fire.', 'And for Sulaimān (We subjugated) the wind; its journey in the morning was (equal to the journey of) one month, and its journey in the afternoon was (equal to the journey) of another month. And We caused a stream of copper to flow for him. And there were some Jinns who worked before him with the leave of his Lord. Whoever of them would deviate from Our command, We would make him taste the punishment of the blazing fire.'),
(3619, 34, 13, 2, 8, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'یَعۡمَلُوۡنَ لَہٗ  مَا یَشَآءُ  مِنۡ مَّحَارِیۡبَ وَ تَمَاثِیۡلَ وَ جِفَانٍ کَالۡجَوَابِ وَ قُدُوۡرٍ رّٰسِیٰتٍ ؕ اِعۡمَلُوۡۤا اٰلَ دَاوٗدَ شُکۡرًا ؕ وَ قَلِیۡلٌ  مِّنۡ عِبَادِیَ  الشَّکُوۡرُ ﴿۱۳﴾', 'وہ جو چاہتے یہ انکے لئے بناتے یعنی قلعے اور تصویریں اور بڑے بڑے لگن جیسے تالاب اور دیگیں جو ایک ہی جگہ رکھی رہیں اے آل داؤد شکر کرتے رہو اور میرے بندوں میں شکرگذار تھوڑے ہیں۔', 'بناتے اس کے واسطے جو کچھ چاہتا قلعے اور  تصویریں اور لگن جیسے تالاب اور دیگیں چولہوں پر جمی ہوئی [۱۹] کام کرو  ا ے داؤد کے گھر  والو احسان مان کر اور تھوڑے ہیں میرے بندوں میں احسان ماننے والے [۲۰]', 'They worked for him what he desired, (making) high rooms, images, basins as large as reservoirs, and (cooking) cauldrons fixed (in their places). \"Work you, O family of Dawud (David), with thanks!\" But few of My slaves are grateful.', 'They used to make for him whatever he wished of castles, images, basins as (large as) tanks, and big cookware fixed (in their places). “Do good, O family of Dawūd, in thankfulness. Very few from My slaves are thankful.”'),
(3620, 34, 14, 2, 8, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'فَلَمَّا قَضَیۡنَا عَلَیۡہِ  الۡمَوۡتَ مَا دَلَّہُمۡ عَلٰی مَوۡتِہٖۤ  اِلَّا دَآبَّۃُ  الۡاَرۡضِ تَاۡکُلُ مِنۡسَاَتَہٗ ۚ فَلَمَّا خَرَّ تَبَیَّنَتِ الۡجِنُّ اَنۡ لَّوۡ کَانُوۡا یَعۡلَمُوۡنَ الۡغَیۡبَ مَا لَبِثُوۡا فِی الۡعَذَابِ الۡمُہِیۡنِ ﴿ؕ۱۴﴾', 'پھر جب ہم نے انکے لئے موت کا حکم صادر کیا تو کسی چیز سے ان کا مرنا معلوم نہ ہوا مگر گھن کے کیڑے سے جو انکے عصا کو کھاتا رہا پھر جب وہ گر پڑے تب جنوں کو معلوم ہوا اور کہنے لگے کہ اگر وہ غیب جانتے ہوتے تو ذلت کی تکلیف میں نہ رہتے۔', 'پھر جب مقرر کیا ہم نےاس پر موت کو نہ جتلایا ان کو اس کا مرنا مگر کیڑے نے گھن کے کھاتا رہا اس کا عصا پھر جب وہ گر پڑا معلوم کیا جنوں نے کہ اگر خبر رکھتے ہوتے غیب کی نہ رہتے ذلت کی تکلیف میں [۲۱]', 'Then when We decreed death for him (Sulaiman (Solomon)), nothing informed them (jinns) of his death except a little worm of the earth, which kept (slowly) gnawing away at his stick, so when he fell down, the jinns saw clearly that if they had known the unseen, they would not have stayed in the humiliating torment.', 'So, when We decided (that) death (should come) upon him, nothing gave them any indication of his death, except a creature of the earth that had eaten up his sceptre. So, when he fell down, the Jinns came to know that if they had the knowledge of the Unseen, they would not have stayed (so long) in the humiliating punishment.'),
(3621, 34, 15, 2, 8, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'لَقَدۡ کَانَ لِسَبَاٍ  فِیۡ مَسۡکَنِہِمۡ اٰیَۃٌ ۚ جَنَّتٰنِ عَنۡ یَّمِیۡنٍ وَّ شِمَالٍ ۬ؕ کُلُوۡا مِنۡ رِّزۡقِ رَبِّکُمۡ وَ اشۡکُرُوۡا لَہٗ ؕ بَلۡدَۃٌ طَیِّبَۃٌ   وَّ  رَبٌّ غَفُوۡرٌ ﴿۱۵﴾', 'اہل سبا کے لئے انکے وطن میں ایک نشانی تھی یعنی دو باغ ایک داہنی طرف اور ایک بائیں طرف کہا گیا کہ اپنے پروردگار کا رزق کھاؤ اور اس کا شکر کرو۔ یہاں تمہارے رہنے کو یہ پاکیزہ علاقہ ہے اور وہاں بڑا بخشنے والا مالک۔', 'تحقیق قوم سبا کو تھی ان کی بستی میں نشانی دو باغ داہنے اور بائیں [۲۲] کھاؤ روزی اپنے رب کی اور اس کا شکر کرو [۲۳] شہر ہے پاکیزہ اور  رب ہے گناہ بخشنے والا [۲۴]', 'Indeed there was for Saba (Sheba) a sign in their dwelling place, - two gardens on the right hand and on the left (and it was said to them) \"Eat of the provision of your Lord, and be grateful to Him, a fair land and an OftForgiving Lord.', 'There was indeed a sign for (the community of) Saba’ in their home-land: two gardens, (one) on the right and (one) on the left. “Eat of the provision from your Lord, and be grateful to Him - (You have) an excellent city, and a Most-Forgiving Lord.”'),
(3622, 34, 16, 2, 8, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'فَاَعۡرَضُوۡا فَاَرۡسَلۡنَا عَلَیۡہِمۡ سَیۡلَ الۡعَرِمِ وَ بَدَّلۡنٰہُمۡ بِجَنَّتَیۡہِمۡ جَنَّتَیۡنِ ذَوَاتَیۡ  اُکُلٍ خَمۡطٍ وَّ اَثۡلٍ وَّ شَیۡءٍ مِّنۡ سِدۡرٍ قَلِیۡلٍ ﴿۱۶﴾', 'تو انہوں نے شکرگذاری سے منہ پھیر لیا پس ہم نے ان پر بند توڑ سیلاب چھوڑ دیا اور انہیں انکے باغوں کے بدلے دو ایسے باغ دیئے جنکے میوے بدمزہ تھے اور جن میں کچھ تو جھاؤ کے پیڑ تھے اور تھوڑی سی بیریاں۔', 'سو دھیان میں نہ لائے پھر چھوڑ دیا ہم نے ان پر ایک نالا زور کا اور دیے ہم نے انکو  بدلے میں ان دو باغوں کے دو اور باغ جن میں کچھ میوہ کسیلا تھا اور جھاؤ اور کچھ بیر تھوڑے سے [۲۵]', 'But they turned away (from the obedience of Allah), so We sent against them Sail AlArim (flood released from the dam), and We converted their two gardens into gardens producing bitter bad fruit, and tamarisks, and some few lotetrees.', 'Then they turned away. So We sent to them the flood of the dam, and replaced their two gardens with two gardens having fruits of bitter taste, and tamarisk and some bushes of wild lotes.'),
(3623, 34, 17, 2, 8, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'ذٰلِکَ جَزَیۡنٰہُمۡ  بِمَا کَفَرُوۡا ؕ وَ ہَلۡ نُجٰزِیۡۤ   اِلَّا الۡکَفُوۡرَ ﴿۱۷﴾', 'یہ ہم نے انکو ناشکری کی سزا دی۔ اور ہم سزا ناشکرے ہی کو دیا کرتے ہیں۔', 'یہ بدلا دیا ہم نے ان کو اس پر کہ ناشکری کی اور ہم یہ بدلا اسی کو دیتے ہیں جو ناشکر  ہو [۲۶]', 'Like this We requited them because they were ungrateful disbelievers. And never do We requit in such a way except those who are ungrateful, (disbelievers).', 'Thus We punished them because of their ungratefulness. We do not give (such a) punishment but to the ungrateful.'),
(3624, 34, 18, 2, 8, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ جَعَلۡنَا بَیۡنَہُمۡ وَ بَیۡنَ الۡقُرَی الَّتِیۡ بٰرَکۡنَا فِیۡہَا قُرًی ظَاہِرَۃً  وَّ قَدَّرۡنَا فِیۡہَا السَّیۡرَ ؕ سِیۡرُوۡا فِیۡہَا لَیَالِیَ وَ اَیَّامًا  اٰمِنِیۡنَ ﴿۱۸﴾', 'اور ہم نے انکے اور ملک شام کی ان بستیوں کے درمیان جن میں ہم نے برکت دی تھی ایک دوسرے کے متصل دیہات بنائے تھے جو سامنے نظر آتے تھے اور ان میں آمدورفت کا اندازہ مقرر کر دیا تھا کہ رات دن بےخوف و خطر چلتے رہو۔', 'اور رکھی تھیں ہم نے ان میں اور ان بستیوں  میں جہاں ہم نے برکت رکھی ہے ایسی بستیاں جو  راہ پر نظر آتی تھیں اور منزلیں مقرر کر دیں ہم نے ان میں آنے جانے کی پھرو  ان میں راتوں کو  اور  دنوں کو امن سے [۲۷]', 'And We placed between them and the towns which We had blessed, towns easy to be seen, and We made the stages (of journey) between them easy (saying): \"Travel in them safely both by night and day.\"', 'And We had set visible townships, all the way between them and the towns blessed by Us, and phased the journey between them in measured phases: “Travel along them at nights and days peacefully.”'),
(3625, 34, 19, 2, 8, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'فَقَالُوۡا رَبَّنَا بٰعِدۡ بَیۡنَ  اَسۡفَارِنَا وَ ظَلَمُوۡۤا اَنۡفُسَہُمۡ فَجَعَلۡنٰہُمۡ  اَحَادِیۡثَ وَ مَزَّقۡنٰہُمۡ کُلَّ مُمَزَّقٍ ؕ اِنَّ  فِیۡ  ذٰلِکَ لَاٰیٰتٍ لِّکُلِّ  صَبَّارٍ  شَکُوۡرٍ ﴿۱۹﴾', 'تو انہوں نے دعا کی کہ اے پروردگار ہماری مسافتوں میں دوری پیدا کر دے اور اس سے انہوں نے اپنے حق میں ظلم کیا تو ہم نے انہیں نابود کر کے داستان بنا دیا اور انہیں بالکل منتشر کر دیا اس میں ہر صابر و شاکر کے لئے نشانیاں ہیں۔', 'پھر کہنے لگے اے رب دراز کر دے ہمارے سفروں کو [۲۸] اور آپ اپنا برا کیا پھر کر ڈالا ہم نے انکو کہانیاں اور کر ڈالا چیر کر ٹکڑے ٹکڑے [۲۹] اس میں پتے کی باتیں ہیں ہر صبر کرنے والے شکر گذار کو [۳۰]', 'But they said: \"Our Lord! Make the stages between our journey longer,\" and they wronged themselves, so We made them as tales (in the land), and We dispersed them all, totally. Verily, in this are indeed signs for every steadfast grateful (person).', 'Then they said, “Our Lord, make (the phases of) our journeys more distant.” And they wronged themselves, therefore We turned them into stories, and tore them into pieces. Surely in this there are signs for everyone who is ever-patient, fully grateful.'),
(3626, 34, 20, 2, 8, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ لَقَدۡ صَدَّقَ عَلَیۡہِمۡ  اِبۡلِیۡسُ ظَنَّہٗ فَاتَّبَعُوۡہُ  اِلَّا فَرِیۡقًا مِّنَ الۡمُؤۡمِنِیۡنَ ﴿۲۰﴾', 'اور شیطان نے انکے بارے میں اپنا خیال سچ کر دکھایا کہ مومنوں کی ایک جماعت کے سوا وہ اسکے پیچھے چل پڑے۔', 'اور سچ کر دکھلائی ان پر ابلیس نے  اپنی اٹکل  پھر اسی کی راہ چلے مگر تھوڑے سے ایمان دار [۳۱]', 'And indeed Iblees (Satan) did prove true his thought about them, and they followed him, all except a group of true believers (in the Oneness of Allah).', 'Iblīs (Satan)has found his assessment true about them. So they followed him, except a group of the believers.'),
(3627, 34, 21, 2, 8, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ مَا کَانَ لَہٗ  عَلَیۡہِمۡ  مِّنۡ سُلۡطٰنٍ اِلَّا لِنَعۡلَمَ مَنۡ یُّؤۡمِنُ بِالۡاٰخِرَۃِ  مِمَّنۡ ہُوَ مِنۡہَا فِیۡ شَکٍّ ؕ وَ رَبُّکَ عَلٰی کُلِّ شَیۡءٍ حَفِیۡظٌ ﴿٪۲۱﴾', 'اور اس کا ان پر کچھ زور نہ تھا مگر ہمارا مقصود یہ تھا کہ جو لوگ آخرت میں شک رکھتے ہیں ان سے ان لوگوں کو جو اس پر ایمان رکھتے ہیں ممتاز کر دیں۔ اور تمہارا پروردگار ہر چیز پر نگہبان ہے۔', 'اور اس کا ان پر کچھ زور نہ تھا مگر اتنے واسطے کہ معلوم کر لیں ہم  اسکو جو  یقین لاتا ہے آخرت پر جدا کر کے اس سے جو رہتا ہے آخرت کی طرف سے دھوکہ میں اور تیرا رب ہر چیز پر نگہبان ہے [۳۲]', 'And he (Iblees Satan) had no authority over them, except that We might test him, who believes in the Hereafter from him who is in doubt about it. And your Lord is a Hafiz over everything. (AllKnower of everything i.e. He keeps record of each and every person as regards deeds, and then He will reward them accordingly).', 'He did not have any power over them, but for the reason that We should recognize the one who believes in the Hereafter as distinct from the one who is in doubt about it; and your Lord is Watchful over every thing.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(3628, 34, 22, 3, 9, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'قُلِ ادۡعُوا الَّذِیۡنَ زَعَمۡتُمۡ مِّنۡ دُوۡنِ اللّٰہِ ۚ لَا یَمۡلِکُوۡنَ مِثۡقَالَ ذَرَّۃٍ  فِی السَّمٰوٰتِ وَ لَا فِی الۡاَرۡضِ وَ مَا لَہُمۡ  فِیۡہِمَا مِنۡ شِرۡکٍ وَّ مَا لَہٗ  مِنۡہُمۡ مِّنۡ ظَہِیۡرٍ ﴿۲۲﴾', 'کہدو کہ جنکو تم اللہ کے سوا معبود خیال کرتے ہو انکو بلاؤ۔ وہ آسمانوں اور زمین میں ذرہ بھر چیز کے بھی مالک نہیں ہیں اور نہ ان میں انکی شرکت ہے اور نہ ان میں سے کوئی اللہ کا مددگار ہے۔', 'تو کہہ پکارو ان کو جن کو گمان  کرتے ہو سوائے اللہ کے [۳۳] وہ مالک نہیں ایک ذرہ بھر کے آسمانوں میں اور نہ زمین میں اور نہ ان کا ان دونوں میں کچھ ساجھا اور نہ ان میں کوئی اس کا مددگار', 'Say: (O Muhammad SAW to those polytheists, pagans, etc.) \"Call upon those whom you assert (to be associate gods) besides Allah, they possess not even the weight of an atom (or a small ant), either in the heavens or on the earth, nor have they any share in either, nor there is for Him any supporter from among them.', 'Say. “Call upon those whom you claim (to be your gods) beside Allah. They do not possess (any thing) even to the measure of a particle, neither in the heavens nor in the earth. They have no contribution at all in either of the two, nor is any of them a helper for Him (Allah).'),
(3629, 34, 23, 3, 9, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ لَا تَنۡفَعُ الشَّفَاعَۃُ عِنۡدَہٗۤ  اِلَّا لِمَنۡ اَذِنَ لَہٗ ؕ حَتّٰۤی  اِذَا فُزِّعَ عَنۡ قُلُوۡبِہِمۡ قَالُوۡا مَاذَا ۙ قَالَ رَبُّکُمۡ ؕ قَالُوا الۡحَقَّ ۚ وَ ہُوَ  الۡعَلِیُّ   الۡکَبِیۡرُ ﴿۲۳﴾', 'اور اللہ کے ہاں کسی کے لئے سفارش فائدہ نہ دے گی مگر اس کے لئے جس کے بارے میں وہ اجازت بخشے یہاں تک کہ جب انکے دلوں سے اضطراب دور کر دیا جائے گا تو کہیں گے کہ تمہارے پروردگار نے کیا فرمایا ہے۔ فرشتے کہیں گے کہ حق فرمایا ہے اور وہ عالی رتبہ ہے گرامی قدر ہے۔', 'اور کام نہیں آتی سفارش اس کے  پاس مگر اس کو کہ جس کے واسطے حکم کر دے [۳۴] یہاں تک کہ جب گھبراہٹ دور ہو جائے ان کے دل سےکہیں کیا فرمایا تمہارے رب نے وہ کہیں فرمایا جو  واجبی ہے اور وہی ہے سب سے اوپر بڑا [۳۵]', 'Intercession with Him profits not, except for him whom He permits. Until when fear is banished from their (angels) hearts, they (angels) say: \"What is it that your Lord has said?\" They say: \"The truth. And He is the Most High, the Most Great.\"', 'Intercession before Him is of no benefit, but for the one whom He has permitted. (And those who receive a command from Allah remain fearful) until when fear is removed from their hearts, they say (to each other), “What did your Lord say?” They say, “The Truth.” He is the High, the Great.'),
(3630, 34, 24, 3, 9, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'قُلۡ مَنۡ یَّرۡزُقُکُمۡ مِّنَ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ قُلِ اللّٰہُ ۙ وَ  اِنَّاۤ  اَوۡ  اِیَّاکُمۡ لَعَلٰی ہُدًی  اَوۡ  فِیۡ  ضَلٰلٍ  مُّبِیۡنٍ ﴿۲۴﴾', 'پوچھو کہ تمکو آسمانوں اور زمین سے کون رزق دیتا ہے؟ کہو کہ اللہ اور ہم یا تم یا تو سیدھے رستے پر ہیں یا کھلم کھلا گمراہی میں۔', 'تو کہہ کون روزی دیتا ہے تم کو آسمان سے اور زمیں سے بتلا دے کہ اللہ [۳۶] اور یا ہم یا تم بیشک ہدایت پر ہیں یا پڑے ہیں گمراہی میں صریح [۳۷]', 'Say (O Muhammad SAW to these polytheists, pagans, etc.) \"Who gives you provision from the heavens and the earth?\" Say: \"Allah, And verily, (either) we or you are rightly guided or in a plain error.\"', 'Say, “Who gives you sustenance from the heavens and the earth?” Say, “Allah”. And We or you are either on the right path or in open error.”'),
(3631, 34, 25, 3, 9, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'قُلۡ  لَّا تُسۡـَٔلُوۡنَ عَمَّاۤ  اَجۡرَمۡنَا وَ لَا نُسۡـَٔلُ  عَمَّا تَعۡمَلُوۡنَ ﴿۲۵﴾', 'کہدو کہ نہ ہمارے گناہوں کی تم سے پرسش ہو گی اور نہ تمہارے اعمال کی ہم سے پرسش ہو گی۔', 'تو کہ تم سے پوچھ نہ ہوگی اسکی جو ہم نے گناہ کیا اور ہم سے پوچھ نہ ہوگی اسکی جو تم کرتے ہو', 'Say (O Muhammad SAW to these polytheists, pagans, etc.) \"You will not be asked about our sins, nor shall we be asked of what you do.\"', 'Say, “You will not be asked about the sins we committed, and we will not be asked about what you do.”'),
(3632, 34, 26, 3, 9, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'قُلۡ یَجۡمَعُ بَیۡنَنَا رَبُّنَا ثُمَّ  یَفۡتَحُ بَیۡنَنَا بِالۡحَقِّ ؕ وَ ہُوَ الۡفَتَّاحُ الۡعَلِیۡمُ ﴿۲۶﴾', 'کہدو کہ ہمارا پروردگار ہمکو جمع کرے گا پھر ہمارے درمیان انصاف کے ساتھ فیصلہ کر دے گا اور وہ خوب فیصلہ کرنے والا ہے صاحب علم ہے۔', 'تو کہہ جمع کرے گا ہم سب کو  رب ہمارا پھر فیصلہ کرے گا ہم میں انصاف کا اور وہی ہے قصہ چکانے  والا سب کچھ جاننے والا [۳۸]', 'Say: \"Our Lord will assemble us all together (on the Day of Resurrection), then He will judge between us with truth. And He is the (Most Trustworthy) AllKnowing Judge.\"', 'Say, “Our Lord will assemble us together, then will judge between us with truth. He is the best Judge, the All-Knowing.”'),
(3633, 34, 27, 3, 9, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'قُلۡ  اَرُوۡنِیَ  الَّذِیۡنَ  اَلۡحَقۡتُمۡ بِہٖ شُرَکَآءَ کَلَّا ؕ بَلۡ ہُوَ  اللّٰہُ  الۡعَزِیۡزُ  الۡحَکِیۡمُ ﴿۲۷﴾', 'کہو کہ مجھے وہ لوگ تو دکھاؤ جنکو تم نے اللہ کا شریک بنا کر اسکے ساتھ ملا رکھا ہے۔ کوئی نہیں بلکہ وہی اللہ غالب ہے حکمت والا ہے۔', 'تو کہہ مجھ کو دکھلاؤ تو سہی جن کو اس سے ملاتے ہو ساجھی قرار دے کر [۳۹] کوئی نہیں وہی اللہ ہے زبردست حکمتوں والا [۴۰]', 'Say (O Muhammad SAW to these polytheists and pagans): \"Show me those whom you have joined to Him as partners. Nay (there are not at all any partners with Him)! But He is Allah (Alone), the AllMighty, the AllWise.\"', 'Say, “Show me the ones whom you have associated with Him as partners. Never! (You can never produce such partners.) He is but Allah, the Mighty, the Wise.”'),
(3634, 34, 28, 3, 9, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ مَاۤ  اَرۡسَلۡنٰکَ  اِلَّا کَآفَّۃً  لِّلنَّاسِ بَشِیۡرًا وَّ نَذِیۡرًا وَّ لٰکِنَّ اَکۡثَرَ النَّاسِ لَا  یَعۡلَمُوۡنَ ﴿۲۸﴾', 'اور اے محمد ﷺ ہم نے تمکو تمام لوگوں کے لئے خوشخبری سنانے والا اور ڈرانے والا بنا کر بھیجا ہے لیکن اکثر لوگ نہیں جانتے۔', 'اور تجھ کو جو ہم نے بھیجا سو سارے لوگوں کے واسطے خوشی اور ڈر سنانے کو لیکن بہت لوگ نہیں سمجھتے [۴۱]', 'And We have not sent you (O Muhammad SAW) except as a giver of glad tidings and a warner to all mankind, but most of men know not.', 'We did not send you (O prophet,) but to the entire mankind, as a bearer of good news and as a warner, but most people do not know.'),
(3635, 34, 29, 3, 9, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ یَقُوۡلُوۡنَ مَتٰی ہٰذَا الۡوَعۡدُ اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ ﴿۲۹﴾', 'اور کہتے ہیں اگر تم سچ کہتے ہو تو بتاؤ یہ قیامت کا وعدہ کب پورا ہو گا؟', 'اور کہتے ہیں کب ہے یہ وعدہ اگر تم سچے ہو [۴۲]', 'And they say: \"When is this promise (i.e. the Day of Resurrection will be fulfilled) if you are truthful?\"', 'They say, “ When will this promise (of the Day of Judgment) be fulfilled, if you are truthful?”'),
(3636, 34, 30, 3, 9, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'قُلۡ لَّکُمۡ مِّیۡعَادُ یَوۡمٍ لَّا تَسۡتَاۡخِرُوۡنَ عَنۡہُ  سَاعَۃً  وَّ لَا تَسۡتَقۡدِمُوۡنَ ﴿٪۳۰﴾', 'کہدو کہ تم سے ایک ایسے دن کا وعدہ ہے جس سے نہ ایک گھڑی پیچھے رہو گے اور نہ آگے بڑھو گے۔', 'تو کہہ تمہارے لیے وعدہ ہے ایک دن کا نہ دیر کرو گے اس سے ایک گھڑی نہ جلدی [۴۳]', 'Say (O Muhammad SAW): \"The appointment to you is for a Day, which you cannot put back for an hour (or a moment) nor put forward.\"', 'Say, “You hold an appointment for a day that you can neither put back for a while, nor can you put it forward.'),
(3637, 34, 31, 4, 10, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ قَالَ الَّذِیۡنَ کَفَرُوۡا لَنۡ نُّؤۡمِنَ بِہٰذَا الۡقُرۡاٰنِ وَ لَا بِالَّذِیۡ بَیۡنَ یَدَیۡہِ ؕ وَ لَوۡ تَرٰۤی  اِذِ  الظّٰلِمُوۡنَ مَوۡقُوۡفُوۡنَ عِنۡدَ رَبِّہِمۡ ۚۖ یَرۡجِعُ بَعۡضُہُمۡ  اِلٰی بَعۡضِۣ الۡقَوۡلَ ۚ یَقُوۡلُ الَّذِیۡنَ اسۡتُضۡعِفُوۡا لِلَّذِیۡنَ اسۡتَکۡبَرُوۡا لَوۡ لَاۤ اَنۡتُمۡ لَکُنَّا مُؤۡمِنِیۡنَ ﴿۳۱﴾', 'اور جو کافر ہیں وہ کہتے ہیں کہ ہم نہ تو اس قرآن کو مانیں گے اور نہ ان کتابوں کو جو اس سے پہلے کی ہیں اور کاش ان ظالموں کو تم اس وقت دیکھو جب یہ اپنے پروردگار کے سامنے کھڑے ہوں گے اور ایک دوسرے پر الزام دھر رہے ہوں گے۔ جو لوگ کمزور سمجھے جاتے تھے وہ بڑے لوگوں سے کہیں گے کہ اگر تم نہ ہوتے تو ہم ضرور ایمان لے آتے۔', 'اور کہنے لگے منکر ہم ہر گز نہ مانیں گے اس قرآن کو  اور نہ اس سے اگلے کو [۴۴] اور کبھی تو دیکھے جبکہ گنہگار کھڑے کئے جائیں اپنے رب کے پاس ایک دوسرے پر ڈالتا ہے بات کو [۴۵] کہتے ہیں وہ لوگ جو کمزور سمجھے جاتے تھے بڑائی کرنے والوں کو اگر تم نہ ہوتے تو ہم  ایمان دار ہوتے [۴۶]', 'And those who disbelieve say: \"We believe not in this Quran nor in that which was before it,\" but if you could see when the Zalimoon (polytheists and wrongdoers, etc.) will be made to stand before their Lord, how they will cast the (blaming) word one to another! Those who were deemed weak will say to those who were arrogant: \"Had it not been for you, we should certainly have been believers!\"', 'Those who disbelieve say, “We will never believe in this Qur’ān, nor in that which was before it.” But if only you could see when the wrongdoers will be made to stand before their Lord, repulsing words (of blame) to one another! Those who were held as weak will say to the overbearing, “Had you not been there, we would have been believers.”'),
(3638, 34, 32, 4, 10, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'قَالَ  الَّذِیۡنَ اسۡتَکۡبَرُوۡا لِلَّذِیۡنَ اسۡتُضۡعِفُوۡۤا اَنَحۡنُ صَدَدۡنٰکُمۡ عَنِ الۡہُدٰی بَعۡدَ اِذۡ جَآءَکُمۡ بَلۡ کُنۡتُمۡ مُّجۡرِمِیۡنَ ﴿۳۲﴾', 'جو لوگ بڑے بن بیٹھے تھے وہ کمزوروں سے کہیں گے کہ بھلا ہم نے تمکو ہدایت سے جب وہ تمہارے پاس آ چکی تھی روکا تھا نہیں بلکہ تم ہی گنہگار تھے۔', 'کہنے لگے بڑائی کرنے والے ان سے جو کہ کمزر گنے گئے تھے کیا ہم نے روکا تم کو حق بات سے تمہار ے پاس پہنچ چکنے کے بعد کوئی نہیں تم  ہی تھے گنہگار [۴۷]', 'And those who were arrogant will say to those who were deemed weak: \"Did we keep you back from guidance after it had come to you? Nay, but you were Mujrimoon (polytheists, sinners, criminals, disobedient to Allah, etc.).', 'Those who were overbearing will say to those weak, “Had we stopped you from (accepting) guidance after it came to you? Rather, you yourselves were guilty.”'),
(3639, 34, 33, 4, 10, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ قَالَ الَّذِیۡنَ اسۡتُضۡعِفُوۡا لِلَّذِیۡنَ اسۡتَکۡبَرُوۡا بَلۡ مَکۡرُ الَّیۡلِ وَ النَّہَارِ اِذۡ  تَاۡمُرُوۡنَنَاۤ  اَنۡ نَّکۡفُرَ  بِاللّٰہِ  وَ  نَجۡعَلَ لَہٗۤ  اَنۡدَادًا ؕ وَ اَسَرُّوا النَّدَامَۃَ  لَمَّا رَاَوُا الۡعَذَابَ ؕ وَ جَعَلۡنَا الۡاَغۡلٰلَ فِیۡۤ  اَعۡنَاقِ الَّذِیۡنَ  کَفَرُوۡا ؕ ہَلۡ  یُجۡزَوۡنَ  اِلَّا مَا  کَانُوۡا یَعۡمَلُوۡنَ ﴿۳۳﴾', 'اور کمزور لوگ ان بڑے لوگوں سے کہیں گے نہیں بلکہ تمہاری رات دن کی چالوں نے ہمیں روک رکھا تھا جب تم ہم سے کہتے تھے کہ ہم اللہ سے کفر کریں اور اس کا شریک بنائیں۔ اور جب وہ عذاب کو دیکھیں گے تو دل میں پشیمان ہوں گے۔ اور ہم کافروں کی گردنوں میں طوق ڈال دیں گے۔ بس جو اعمال وہ کرتے تھے انہی کا ان کو بدلہ ملے گا۔', 'اور کہنے لگے وہ لوگ جو کمزور گنے گئے تھے بڑائی کرنے والوں کو کوئی نہیں پر فریب سے رات دن کے جب تم ہم کو حکم کیا کرتے کہ ہم نہ مانیں اللہ کو اور ٹھہرائیں اسکے ساتھ برابر کے ساجھی [۴۸] اور چھپے چھپے پچتانے لگے جب دیکھ لیا عذاب [۴۹] اور ہم نے ڈالے ہیں طوق گردنوں میں منکروں کے [۵۰] وہی بدلہ پاتے ہیں جو عمل کرتے تھے [۵۱]', 'Those who were deemed weak will say to those who were arrogant: \"Nay, but it was your plotting by night and day, when you ordered us to disbelieve in Allah and set up rivals to Him!\" And each of them (parties) will conceal their own regrets (for disobeying Allah during this worldly life), when they behold the torment. And We shall put iron collars round the necks of those who disbelieved. Are they requited aught except what they used to do?', 'And those weak will say to those overbearing, “But (it was your) intriguing day and night (that stopped us from accepting guidance), when you were directing us to disbelieve in Allah and to set up rivals to Him.” And all of them will conceal (their) regrets when they will see the punishment. And We will place iron-collars around the necks of those who disbelieved. They will not be recompensed except for what they used to do.'),
(3640, 34, 34, 4, 10, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ مَاۤ  اَرۡسَلۡنَا فِیۡ قَرۡیَۃٍ  مِّنۡ نَّذِیۡرٍ  اِلَّا قَالَ  مُتۡرَفُوۡہَاۤ  ۙ اِنَّا بِمَاۤ  اُرۡسِلۡتُمۡ بِہٖ کٰفِرُوۡنَ ﴿۳۴﴾', 'اور ہم نے جس بستی میں بھی کوئی ڈرانے والا بھیجا تو وہاں کے خوشحال لوگوں نے یہ ضرور کہا کہ تم لوگ جو چیز دے کر بھیجے گئے ہو ہم اسکو نہیں مانیں گے۔', 'اور نہیں بھیجا ہم نے کسی بستی میں کوئی ڈرانے والا مگر کہنے لگے ہیں وہاں کے آسودہ لوگ جو تمہارے ہاتھ بھیجا گیا ہم اس کو نہیں مانتے [۵۲]', 'And We did not send a warner to a township, but those who were given the worldly wealth and luxuries among them said: \"We believe not in the (Message) with which you have been sent.\"', 'We did not send a warner to a township, but said those who lived a luxurious life in it, “We reject what you have been sent with.”'),
(3641, 34, 35, 4, 10, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ قَالُوۡا نَحۡنُ  اَکۡثَرُ  اَمۡوَالًا  وَّ  اَوۡلَادًا ۙ وَّ  مَا نَحۡنُ بِمُعَذَّبِیۡنَ ﴿۳۵﴾', 'اور یہ بھی کہنے لگے کہ ہم بہت سا مال اور اولاد رکھتے ہیں اور ہمکو عذاب نہیں ہو گا۔', 'اور کہنے لگے ہم زیادہ ہیں مال اور اولاد میں اور ہم پر آفت نہیں آنے والی [۵۳]', 'And they say: \"We are more in wealth and in children, and we are not going to be punished.\"', 'And they said, “We are superior in riches and children, and we are not going to be punished”.'),
(3642, 34, 36, 4, 10, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'قُلۡ  اِنَّ رَبِّیۡ  یَبۡسُطُ الرِّزۡقَ لِمَنۡ یَّشَآءُ  وَ یَقۡدِرُ وَ لٰکِنَّ  اَکۡثَرَ النَّاسِ لَا یَعۡلَمُوۡنَ ﴿٪۳۶﴾', 'کہدو کہ میرا رب جسکے لئے چاہتا ہے روزی فراخ کر دیتا ہے اور جسکے لئے چاہتا ہے تنگ کر دیتا ہے لیکن اکثر لوگ نہیں جانتے۔', 'تو کہہ میرا رب ہے جو کشادہ کر دیتا ہے روزی جس کو چاہے اور ماپ کر دیتا ہے لیکن بہت لوگ سمجھ نہیں رکھتے [۵۴]', 'Say (O Muhammad SAW): \"Verily, my Lord enlarges and restricts the provision to whom He pleases, but most men know not.\"', 'Say, “In fact, my Lord extends provision to whom He wills, and straitens (it for whom He wills), but most of the people do not know”.'),
(3643, 34, 37, 5, 11, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ مَاۤ  اَمۡوَالُکُمۡ وَ لَاۤ  اَوۡلَادُکُمۡ  بِالَّتِیۡ تُقَرِّبُکُمۡ عِنۡدَنَا زُلۡفٰۤی  اِلَّا مَنۡ اٰمَنَ وَ عَمِلَ صَالِحًا ۫ فَاُولٰٓئِکَ لَہُمۡ جَزَآءُ الضِّعۡفِ بِمَا عَمِلُوۡا وَ ہُمۡ فِی الۡغُرُفٰتِ اٰمِنُوۡنَ ﴿۳۷﴾', 'اور تمہارے مال اور اولاد ایسی چیز نہیں کہ تمکو ہم سے قریب کر دیں ہاں ہمارا مقرب وہ ہے جو ایمان لایا اور عمل نیک کرتا رہا ایسے ہی لوگوں کو انکے اعمال کے سبب دگنا بدلہ ملے گا اور وہ امن و چین سے بلند و بالا عمارتوں میں رہیں گے۔', 'اور تمہارے مال اور تمہاری اولاد وہ نہیں کہ نزدیک کر دیں ہمارے پاس تمہارا درجہ پر جو کوئی یقین لایا اور بھلا کام کیا [۵۵] سو ان کے لیے ہے بدلا دونا انکے کیے کام کا [۵۶] اور وہ جھروکوں میں بیٹھے ہیں دلجمعی سے', 'And it is not your wealth, nor your children that bring you nearer to Us (i.e. pleases Allah), but only he (will please Us) who believes (in the Islamic Monotheism), and does righteous deeds; as for such, there will be twofold reward for what they did, and they will reside in the high dwellings (Paradise) in peace and security.', 'Your riches or your children are not the things that bring you near Us closely; however, the one who believes and acts righteously (is close to Us). Therefore, such people will have the double reward for what they did, and they will be at peace in the upper chambers (of Paradise).'),
(3644, 34, 38, 5, 11, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ الَّذِیۡنَ یَسۡعَوۡنَ فِیۡۤ  اٰیٰتِنَا مُعٰجِزِیۡنَ اُولٰٓئِکَ  فِی الۡعَذَابِ  مُحۡضَرُوۡنَ ﴿۳۸﴾', 'جو لوگ ہماری آیتوں کے سلسلے میں ہمیں ہرانے کی کوشش کرتے ہیں وہ گرفتار عذاب کئے جائیں گے۔', 'اور جو لوگ دوڑتے ہیں ہماری آیتوں کے ہرانے کو  وہ عذاب میں پکڑے ہوئے آتے ہیں [۵۷]', 'And those who strive against Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), to frustrate them, will be brought to the torment.', 'As for those who strive against our signs trying to frustrate (them), they will be arraigned into the torment.'),
(3645, 34, 39, 5, 11, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'قُلۡ  اِنَّ رَبِّیۡ یَبۡسُطُ الرِّزۡقَ لِمَنۡ یَّشَآءُ مِنۡ عِبَادِہٖ وَ یَقۡدِرُ لَہٗ ؕ وَ مَاۤ  اَنۡفَقۡتُمۡ مِّنۡ شَیۡءٍ فَہُوَ یُخۡلِفُہٗ ۚ وَ ہُوَ خَیۡرُ الرّٰزِقِیۡنَ ﴿۳۹﴾', 'کہدو کہ میرا پروردگار اپنے بندوں میں سے جسکے لئے چاہتا ہے روزی فراخ کر دیتا ہے اور جس کے لئے چاہتا ہے تنگ کر دیتا ہے اور تم جو چیز خرچ کرو گے وہ اس کا تمہیں عوض دے گا۔ وہ سب سے اچھا رزق دینے والا ہے۔', 'تو کہہ میرا رب ہے جو کشادہ کر دیتا ہے روزی جس کو چاہے اپنے بندوں میں اور ماپ کر دیتا ہے اور جو خرچ کرتے ہو کچھ چیز وہ اس کا عوض دیتا ہے اور وہ بہتر ہے روزی دینے والا [۵۸]', 'Say: \"Truly, my Lord enlarges the provision for whom He wills of His slaves, and (also) restricts (it) for him, and whatsoever you spend of anything (in Allahs Cause), He will replace it. And He is the Best of providers.\"', 'Say, “ Surely, my Lord extends provision for whomsoever He wills, and straitens (it) for him. And whatever thing you spend, He replaces it, and He is the best of the sustainers.'),
(3646, 34, 40, 5, 11, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ یَوۡمَ یَحۡشُرُہُمۡ جَمِیۡعًا ثُمَّ یَقُوۡلُ لِلۡمَلٰٓئِکَۃِ  اَہٰۤؤُلَآءِ  اِیَّاکُمۡ کَانُوۡا یَعۡبُدُوۡنَ ﴿۴۰﴾', 'اور جس دن وہ ان سب کو جمع کرے گا پھر فرشتوں سے فرمائے گا۔ کیا یہ لوگ تمکو پوجا کرتے تھے۔', 'اور جس دن جمع کرے گا ان سب کو پھر کہے گا فرشتوں کو کیا یہ لوگ تم کوپوجا کرتے تھے [۵۹]', 'And (remember) the Day when He will gather them all together, and then will say to the angels: \"Was it you that these people used to worship?\"', '(Remember) the Day when He will gather all of them together, then will say to the angels, “Is it you that these people used to worship?”'),
(3647, 34, 41, 5, 11, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'قَالُوۡا سُبۡحٰنَکَ اَنۡتَ وَلِیُّنَا مِنۡ دُوۡنِہِمۡ ۚ بَلۡ کَانُوۡا یَعۡبُدُوۡنَ الۡجِنَّ ۚ اَکۡثَرُہُمۡ بِہِمۡ  مُّؤۡمِنُوۡنَ ﴿۴۱﴾', 'وہ کہیں گے تو پاک ہے تو ہی ہمارا دوست ہے نہ کہ یہ بلکہ یہ جنات کو پوجا کرتے تھے۔ اور اکثر ان ہی کو مانتے تھے۔', 'وہ کہیں گے پاک ذات ہے تیری ہم تیری طرف میں ہیں نہ انکی طرف میں نہیں پر پوجتے تھے جنوں کو یہ اکثر انہی پر اعتقاد رکھتے تھے [۶۰]', 'They (angels) will say: \"Glorified be You! You are our Walee (Lord) instead of them. Nay, but they used to worship the jinns; most of them were believers in them.\"', 'They will say, “Pure are You! You are our mentor, not these. Rather, they used to worship the Jinns. Most of these believed in them.”'),
(3648, 34, 42, 5, 11, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'فَالۡیَوۡمَ لَا یَمۡلِکُ بَعۡضُکُمۡ لِبَعۡضٍ نَّفۡعًا وَّ لَا ضَرًّا ؕ وَ نَقُوۡلُ لِلَّذِیۡنَ ظَلَمُوۡا ذُوۡقُوۡا عَذَابَ النَّارِ الَّتِیۡ کُنۡتُمۡ بِہَا تُکَذِّبُوۡنَ ﴿۴۲﴾', 'تو آج تم میں سے کوئی کسی کو نفع اور نقصان پہنچانے کا اختیار نہیں رکھتا اور ہم ظالموں سے کہیں گے کہ اب دوزخ کے عذاب کا جس کو تم جھوٹ سمجھتے تھے مزہ چکھو۔', 'سو  آج تم مالک نہیں ایک دوسرے کے بھلے کے نہ برے کے [۶۱] اور کہیں گے ہم ان گنہگاروں کو چکھو تکلیف اس آگ کی جس کو  تم جھوٹ بتلاتے تھے', 'So Today (i.e. the Day of Resurrection), none of you can profit or harm one another. And We shall say to those who did wrong (i.e. worshipped others (like angels, jinns, prophets, saints, righteous persons, etc.) along with Allah): \"Taste the torment of the Fire which you used to belie.', 'So, you have no power today to benefit or harm one another, and We will say to the wrongdoers, “Taste the punishment of the Fire that you used to deny.”'),
(3649, 34, 43, 5, 11, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ اِذَا تُتۡلٰی عَلَیۡہِمۡ اٰیٰتُنَا بَیِّنٰتٍ قَالُوۡا مَا ہٰذَاۤ  اِلَّا رَجُلٌ یُّرِیۡدُ اَنۡ یَّصُدَّکُمۡ عَمَّا کَانَ یَعۡبُدُ اٰبَآؤُکُمۡ ۚ وَ قَالُوۡا مَا ہٰذَاۤ اِلَّاۤ  اِفۡکٌ مُّفۡتَرًی ؕ وَ قَالَ  الَّذِیۡنَ کَفَرُوۡا لِلۡحَقِّ لَمَّا جَآءَہُمۡ ۙ اِنۡ  ہٰذَاۤ اِلَّا سِحۡرٌ مُّبِیۡنٌ ﴿۴۳﴾', 'اور جب انکو ہماری روشن آیتیں پڑھ کر سنائی جاتی ہیں تو کہتے ہیں یہ ایک ایسا شخص ہے جو چاہتا ہے کہ جن چیزوں کی تمہارے باپ دادا پرستش کیا کرتے تھے ان سے تمکو روک دے اور یہ بھی کہتے ہیں کہ یہ قرآن محض جھوٹ ہے جو اپنی طرف سے بنا لیا گیا ہے اور کافروں کے پاس جب حق آیا تو اسکے بارے میں کہنے لگے کہ یہ تو کھلا جادو ہے۔', 'اور جب پڑھی جائیں انکے  پاس ہماری آیتیں کھلی کھلی کہیں اور کچھ نہیں مگر  یہ ایک مرد ہے چاہتا ہے کہ روک دے تم کو ان سے جن کو پوجتے رہے تمہارے باپ دادے [۶۲] اور کہیں اور کچھ نہیں یہ جھوٹ ہے باندھا ہوا [۶۳] اور کہتے ہیں منکر حق بات کو جب پہنچے ان تک اور کچھ نہیں یہ ایک جادو ہے صریح [۶۴]', 'And when Our Clear Verses are recited to them, they say: \"This (Muhammad SAW) is naught but a man who wishes to hinder you from that which your fathers used to worship.\" And they say: \"This is nothing but an invented lie.\" And those who disbelieve say of the truth when it has come to them (i.e. Prophet Muhammad SAW when Allah sent him as a Messenger with proofs, evidences, verses, lessons, signs, etc.): \"This is nothing but evident magic!\"', 'When Our evident verses are recited to them, they say, “He is nothing but a man who wishes to divert you from what your fathers used to worship.” And they say, “This is nothing but a forged lie.” And the disbelievers say about the Truth, when it came to them, “This is nothing but an explicit magic.”'),
(3650, 34, 44, 5, 11, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ مَاۤ  اٰتَیۡنٰہُمۡ  مِّنۡ کُتُبٍ یَّدۡرُسُوۡنَہَا وَ مَاۤ  اَرۡسَلۡنَاۤ  اِلَیۡہِمۡ قَبۡلَکَ مِنۡ نَّذِیۡرٍ ﴿ؕ۴۴﴾', 'اور ہم نے نہ تو ان مشرکوں کو کتابیں دیں جنکو یہ پڑھتے ہوں اور اے نبی ﷺ نہ تم سے پہلے ان کی طرف کوئی ڈرانے والا بھیجا۔', 'اور ہم نے دی نہیں انکو کچھ کتابیں کہ جن کو  وہ پڑھتے ہوں اور بھیجا نہیں انکے  پاس تجھ سے پہلے کوئی ڈرانے والا [۶۵]', 'And We had not given them Scriptures which they could study, nor sent to them before you (O Muhammad SAW) any warner (Messenger).', 'We did not give them any books that they might study, nor did We send to them any warner before you.'),
(3651, 34, 45, 5, 11, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ کَذَّبَ الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ ۙ وَ مَا بَلَغُوۡا مِعۡشَارَ مَاۤ  اٰتَیۡنٰہُمۡ  فَکَذَّبُوۡا رُسُلِیۡ ۟ فَکَیۡفَ کَانَ  نَکِیۡرِ ﴿٪۴۵﴾', 'اور جو لوگ ان سے پہلے تھے انہوں نے تکذیب کی تھی اور جو کچھ ہم نے انکو دیا تھا یہ اسکے دسویں حصے کو بھی نہیں پہنچے پھر انہوں نے میرے پیغمبروں کو جھٹلایا سو میرا عذاب کیسا ہوا؟', 'اور جھٹلایا ہے ان سے اگلوں نے اور یہ نہیں پہنچے دسویں حصہ کو اس کے جو ہم نے انکو دیا تھا پھر جھٹلایا انہوں نے میرے بھیجے ہوؤں کو تو کیسا ہوا انکار میرا [۶۶]', 'And those before them belied; these have not received one tenth (1/10th) of what We had granted to those (of old), yet they belied My Messengers, then how (terrible) was My denial (punishment)!', 'And those before them had rejected (the prophets), while these (infidels of Makkah) have not reached even one tenth of what We gave to those (before them). So, they rejected my Messengers. Then (imagine) how was My censure!'),
(3652, 34, 46, 6, 12, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'قُلۡ  اِنَّمَاۤ  اَعِظُکُمۡ بِوَاحِدَۃٍ ۚ اَنۡ تَقُوۡمُوۡا لِلّٰہِ  مَثۡنٰی وَ فُرَادٰی ثُمَّ تَتَفَکَّرُوۡا ۟ مَا بِصَاحِبِکُمۡ   مِّنۡ جِنَّۃٍ ؕ اِنۡ ہُوَ اِلَّا نَذِیۡرٌ لَّکُمۡ بَیۡنَ یَدَیۡ عَذَابٍ شَدِیۡدٍ ﴿۴۶﴾', 'کہدو کہ میں تمہیں صرف ایک بات کی نصیحت کرتا ہوں کہ تم اللہ کے لئے دو دو اور اکیلے اکیلے کھڑے ہو جاؤ پھر غور کرو۔ تمہارے رفیق یعنی اس نبی ﷺ کو کسی طرح کا جنون نہیں یہ تو تمکو سخت عذاب کے آنے سے پہلے ڈرانے والے ہیں۔', 'تو کہ میں تو ایک ہی نصیحت کرتا ہوں تم کو کہ اٹھ کھڑے ہو  اللہ کے نام  پر دو دو اور  ایک ایک پھر دھیان کرو کہ اس تمہارے رفیق کو کچھ سودا نہیں یہ تو ایک ڈرانے  والا ہے تم کو ایک بڑی آفت کے آنے سے [۶۷]', 'Say (to them O Muhammad SAW): \"I exhort you on one (thing) only: that you stand up for Allahs sake in pairs and singly, and reflect (within yourselves the life history of the Prophet SAW): there is no madness in your companion (Muhammad SAW), he is only a warner to you in face of a severe torment.\"', 'Say, “I advise you for one thing only: that you stand up before Allah, in pairs and in singles, then reflect; (you will easily appreciate that) there is no madness in your fellow (the Holy Prophet).” He is none but a warner to you in the face of a stern torment.'),
(3653, 34, 47, 6, 12, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'قُلۡ مَا سَاَلۡتُکُمۡ مِّنۡ اَجۡرٍ فَہُوَ لَکُمۡ ؕ اِنۡ اَجۡرِیَ  اِلَّا عَلَی اللّٰہِ ۚ وَ ہُوَ عَلٰی کُلِّ شَیۡءٍ  شَہِیۡدٌ ﴿۴۷﴾', 'کہدو کہ میں نے تم سے کچھ صلہ مانگا ہو تو وہ تمہارا۔ میرا صلہ اللہ ہی کے ذمے ہے۔ اور وہ ہر چیز سے خبردار ہے۔', 'تو کہہ جو میں نے تم سے مانگا ہوکچھ بدلا سو وہ تمہی رکھو میرا بدلہ ہے اسی اللہ پر [۶۸] اور اس کے سامنے ہے ہر چیز [۶۹]', 'Say (O Muhammad SAW): \"Whatever wage I might have asked of you is yours. My wage is from Allah only. and He is Witness over all things.\"', 'Say, “If I had ever claimed any reward from you, then it is yours. My reward is with none but Allah. And He is witness over every thing.”'),
(3654, 34, 48, 6, 12, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'قُلۡ  اِنَّ رَبِّیۡ  یَقۡذِفُ بِالۡحَقِّ ۚ عَلَّامُ الۡغُیُوۡبِ  ﴿۴۸﴾', 'کہدو کہ میرا پروردگار اوپر سے حق ہی نازل کرتا ہے اور وہ غیب کی باتوں کا جاننے والا ہے۔', 'تو کہہ میرا رب پھینک رہا ہے سچا دین اور وہ جانتا ہے چھپی چیزیں [۷۰]', 'Say (O Muhammad SAW): \"Verily! My Lord sends down Inspiration and makes apparent the truth (i.e. this Revelation that had come to me), the AllKnower of the Ghaib (unseen).', 'Say, “My Lord sends forth the Truth. He is the Best-Knower of the Unseen.”'),
(3655, 34, 49, 6, 12, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'قُلۡ جَآءَ الۡحَقُّ وَ مَا یُبۡدِئُ الۡبَاطِلُ وَ مَا یُعِیۡدُ ﴿۴۹﴾', 'کہدو کہ حق آ چکا اور باطل نہ تو پہلے کچھ کر سکتا ہے اور نہ دوبارہ کچھ کرے گا۔', 'تو کہہ آیا دین سچا اور جھوٹ تو کسی چیز کو نہ پیدا کرے اور نہ  پھیر کر لائے [۷۱]', 'Say (O Muhammad SAW): \"The truth (the Quran and Allahs Inspiration) has come, and AlBatil (falsehood - Iblees (Satan)) can neither create anything nor resurrect (anything).\"', 'Say, “Truth has come, and falsehood (has vanished, and it) has no power to produce or reproduce (anything).”'),
(3656, 34, 50, 6, 12, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'قُلۡ اِنۡ ضَلَلۡتُ فَاِنَّمَاۤ  اَضِلُّ عَلٰی نَفۡسِیۡ ۚ وَ اِنِ اہۡتَدَیۡتُ فَبِمَا یُوۡحِیۡۤ  اِلَیَّ رَبِّیۡ ؕ اِنَّہٗ  سَمِیۡعٌ  قَرِیۡبٌ ﴿۵۰﴾', 'کہدو کہ اگر میں گمراہ ہوں تو میری گمراہی کا ضرر مجھی کو ہے۔ اور اگر ہدایت پر ہوں تو یہ اس وحی کے طفیل ہے جو میرا پروردگار میری طرف بھیجتا ہے۔ بیشک وہ سننے والا ہے نزدیک ہے۔', 'تو کہہ اگر میں بہکا ہوا ہوں تو بہکوں گا اپنے ہی نقصان کو اور اگر ہوں سیدھے راستہ پر تو اس سبب سے کہ وحی بھیجتا ہے مجھ کو میر ارب بیشک وہ سب کچھ سنتا ہے نزدیک  [۷۲]', 'Say: \"If (even) I go astray, I shall stray only to my own loss. But if I remain guided, it is because of the Inspiration of my Lord to me. Truly, He is AllHearer, Ever Near (to all things).\"', 'Say, “If I go astray, I shall go astray only to my own detriment. And if I follow the right path, it is because of what my Lord reveals to me. Surely He is All-Hearer, Ever-Near.”'),
(3657, 34, 51, 6, 12, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ لَوۡ تَرٰۤی  اِذۡ  فَزِعُوۡا فَلَا فَوۡتَ وَ اُخِذُوۡا مِنۡ  مَّکَانٍ قَرِیۡبٍ ﴿ۙ۵۱﴾', 'اور کاش تم دیکھو جب یہ گھبرا جائیں گے تو عذاب سے بچ نہیں سکیں گے اور نزدیک ہی سے پکڑ لئے جائیں گے۔', 'اور کبھی تو دیکھے جب یہ گھبرائیں پھر نہ بچیں بھاگ کر اور پکڑے ہوئے آئیں نزدیک جگہ سے [۷۳]', 'And if you could but see, when they will be terrified with no escape (for them), and they will be seized from a near place.', 'And if you could only see when they will be terrified! Then there will be no escape, and they will be seized from a place near at hand.'),
(3658, 34, 52, 6, 12, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَّ قَالُوۡۤا اٰمَنَّا بِہٖ ۚ وَ اَنّٰی لَہُمُ التَّنَاوُشُ مِنۡ مَّکَانٍۭ بَعِیۡدٍ ﴿ۚۖ۵۲﴾', 'اور کہیں گے کہ ہم اس پر ایمان لے آئے اور اب اتنی دور سے ان کا ہاتھ ایمان کے لینے کو کیسے پہنچ سکتا ہے؟', 'اور کہنے لگیں ہم نے اسکو یقین مان لیا اور اب کہاں انکا ہاتھ پہنچ سکتا ہے بعید جگہ سے [۷۴]', 'And they will say (in the Hereafter): \"We do believe (now);\" but how could they receive (Faith and the acceptance of their repentance by Allah) from a place so far off (i.e. to return to the worldly life again).', 'And they will say, “We believe in Him.” And how can they grasp at it (the faith) from a place (so) far off,'),
(3659, 34, 53, 6, 12, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَّ قَدۡ کَفَرُوۡا بِہٖ مِنۡ قَبۡلُ ۚ وَ یَقۡذِفُوۡنَ بِالۡغَیۡبِ مِنۡ مَّکَانٍۭ بَعِیۡدٍ ﴿۵۳﴾', 'جبکہ پہلے تو اس کا انکار کرتے رہے اور بن دیکھے دور ہی سے اٹکل کے تیر چلاتے رہے۔', 'اور اس سے منکر رہے پہلے سے اور پھینکتے رہے بن دیکھے نشانہ پر دور کی جگہ سے [۷۵]', 'Indeed they did disbelieve (in the Oneness of Allah, Islam, the Quran and Muhammad SAW) before (in this world), and they (used to) conjecture about the unseen (i.e. the Hereafter, Hell, Paradise, Resurrection and the Promise of Allah, etc. (by saying) all that is untrue), from a far place.', 'while they had rejected it before, and used to make conjectures from a remote place?'),
(3660, 34, 54, 6, 12, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'سبا', 'وَ حِیۡلَ بَیۡنَہُمۡ وَ بَیۡنَ مَا یَشۡتَہُوۡنَ کَمَا فُعِلَ بِاَشۡیَاعِہِمۡ مِّنۡ قَبۡلُ ؕ اِنَّہُمۡ کَانُوۡا فِیۡ شَکٍّ مُّرِیۡبٍ  ﴿٪۵۴﴾', 'اور ان میں اور انکی خواہشوں میں پردہ حائل کر دیا گیا جیسا کہ پہلے انکے ہم جنسوں سے کیا گیا وہ بھی الجھن میں ڈالنے والے شک میں پڑے ہوئے تھے۔', 'اور رکاوٹ پڑ گئ ان میں اور ان کی آرزو میں [۷۶] جیسا کہ کیا گیا ہے انکے طریقہ  والوں کے ساتھ اس سے پہلے وہ لوگ تھے ایسے تردد میں جو چین نہ لینے دے [۷۷]', 'And a barrier will be set between them and that which they desire (i.e. At-Taubah (turning to Allah in repentance) and the accepting of Faith etc.), as was done in the past with the people of their kind. Verily, they have been in grave doubt.', 'And a barrier will be placed between them and that which they desire, as it will be done with the people of their kind who were before (them). They have been in a perplexing doubt.'),
(3661, 35, 1, 1, 13, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'اَلۡحَمۡدُ لِلّٰہِ فَاطِرِ السَّمٰوٰتِ وَ الۡاَرۡضِ جَاعِلِ الۡمَلٰٓئِکَۃِ  رُسُلًا اُولِیۡۤ  اَجۡنِحَۃٍ مَّثۡنٰی وَ ثُلٰثَ وَ رُبٰعَ ؕ یَزِیۡدُ فِی الۡخَلۡقِ مَا یَشَآءُ ؕ اِنَّ اللّٰہَ عَلٰی کُلِّ شَیۡءٍ  قَدِیۡرٌ ﴿۱﴾', 'سب تعریف اللہ ہی کیلئے ہے جو آسمانوں اور زمین کا پیدا کرنے والا اور فرشتوں کو قاصد بنانے والا ہے جنکے دو دو اور تین تین اور چار چار پر ہیں وہ اپنی مخلوقات میں جو چاہتا ہے بڑھاتا ہے۔ بیشک اللہ ہر چیز پر قادر ہے۔', 'سب خوبی اللہ کو ہے جس نے بنا نکالے آسمان اور زمین [۱] جس نے ٹھہرایا فرشتوں کو پیغام لانے والے [۲] جن کے پر ہیں دو دو اور تین تین اور چار چار [۳] بڑھا دیتا ہے پیدائش میں جو چاہے بیشک اللہ ہر چیز کر سکتا ہے [۴]', 'All the praises and thanks be to Allah, the (only) Originator (or the (only) Creator) of the heavens and the earth, Who made the angels messengers with wings, - two or three or four. He increases in creation what He wills. Verily, Allah is Able to do all things.', 'All praise belongs to Allah, the Originator of the heavens and the earth, who appoints the angels as messengers having wings, in twos, threes and fours. He adds to the creation what He wills. Indeed, Allah is powerful to do every thing.'),
(3662, 35, 2, 1, 13, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'مَا یَفۡتَحِ اللّٰہُ  لِلنَّاسِ مِنۡ  رَّحۡمَۃٍ  فَلَا مُمۡسِکَ لَہَا ۚ وَ مَا یُمۡسِکۡ ۙ فَلَا مُرۡسِلَ  لَہٗ  مِنۡۢ  بَعۡدِہٖ ؕ وَ ہُوَ  الۡعَزِیۡزُ  الۡحَکِیۡمُ ﴿۲﴾', 'اللہ جو لوگوں کیلئے اپنی رحمت کا دروازہ کھول دے تو کوئی اسکو بند کرنے والا نہیں۔ اور جو بند کر دے تو اسکے بعد کوئی اسکو کھولنے والا نہیں اور وہ غالب ہے حکمت والا ہے۔', 'جو کچھ کہ کھول دے اللہ لوگوں پر رحمت میں سے تو کوئی نہیں اس کو  روکنے والا [۵] اور جو کچھ روک رکھے تو کوئی نہیں اس کو بھیجنے والا اسکے سوائے اور وہی ہے زبردست حکمتوں والا [۶]', 'Whatever of mercy (i.e.of good), Allah may grant to mankind, none can withhold it, and whatever He may withhold, none can grant it thereafter. And He is the AllMighty, the AllWise.', 'Whatever blessing Allah opens for the people, there is none to hold it back, and whatever He holds back, there is none to release it thereafter. He is the Mighty, the Wise.'),
(3663, 35, 3, 1, 13, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'یٰۤاَیُّہَا النَّاسُ اذۡکُرُوۡا نِعۡمَتَ اللّٰہِ عَلَیۡکُمۡ ؕ ہَلۡ مِنۡ خَالِقٍ غَیۡرُ اللّٰہِ یَرۡزُقُکُمۡ مِّنَ السَّمَآءِ وَ الۡاَرۡضِ ؕ لَاۤ اِلٰہَ   اِلَّا  ہُوَ ۫ۖ فَاَنّٰی تُؤۡفَکُوۡنَ ﴿۳﴾', 'لوگو اللہ کے جو تم پر احسانات ہیں انکو یاد کرو۔ کیا اللہ کے سوا کوئی اور خالق اور رازق ہے جو تمکو آسمان اور زمین سے رزق دے؟ اسکے سوا کوئی معبود نہیں پس تم کیسے الٹائے جاتے ہو۔', 'اے لوگو یاد کرو احسان اللہ کا اپنے اوپر کیا کوئی ہے بنانے والا اللہ کے سوائے روزی دیتا ہے تم کو آسمان سے اور زمین سے کوئی حاکم نہیں مگر وہ پھر کہاں  الٹے جاتے ہو [۷]', 'O mankind! Remember the Grace of Allah upon you! Is there any creator other than Allah who provides for you from the sky (rain) and the earth? La ilaha illa Huwa (none has the right to be worshipped but He). How then are you turning away (from Him)?', 'O mankind, remember Allah’s blessing upon you. Is there any creator other than Allah who gives you provision from the sky and the earth? There is no god but He. So, to where are you being turned around (by your desires)?'),
(3664, 35, 4, 1, 13, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ اِنۡ یُّکَذِّبُوۡکَ فَقَدۡ کُذِّبَتۡ رُسُلٌ مِّنۡ قَبۡلِکَ ؕ وَ  اِلَی  اللّٰہِ  تُرۡجَعُ  الۡاُمُوۡرُ ﴿۴﴾', 'اور اے پیغمبر اگر یہ لوگ تمکو جھٹلائیں تو تم سے پہلے بھی پیغمبر جھٹلائے گئے ہیں۔ اور سب کام اللہ ہی کی طرف لوٹائے جائیں گے۔', 'اور اگر تجھ کو جھٹلائیں تو جھٹلائے گئے کتنے رسول تجھ سے پہلے اور اللہ تک پہنچتے ہیں سب کام [۸]', 'And if they belie you (O Muhammad SAW), so were Messengers belied before you. And to Allah return all matters (for decision).', '(O Prophet,) if they reject you, (it is not something new, because) many messengers have been rejected before you. It is to Allah that all matters are to be referred.'),
(3665, 35, 5, 1, 13, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'یٰۤاَیُّہَا النَّاسُ  اِنَّ  وَعۡدَ اللّٰہِ حَقٌّ فَلَا تَغُرَّنَّکُمُ الۡحَیٰوۃُ  الدُّنۡیَا ٝ وَ لَا یَغُرَّنَّکُمۡ  بِاللّٰہِ   الۡغَرُوۡرُ ﴿۵﴾', 'لوگو اللہ کا وعدہ سچا ہے۔ تو تمکو دنیا کی زندگی دھوکے میں نہ ڈال دے اور نہ بڑا فریبی یعنی شیطان تمہیں اللہ کے نام سے فریب دے۔', 'اے لوگو بیشک اللہ کا وعدہ ٹھیک ہے سو نہ بہکائے تم کو دنیا کی زندگانی اور نہ دغا دے تم کو اللہ کے نام سے وہ دغا باز', 'O mankind! Verily, the Promise of Allah is true. So let not this present life deceive you, and let not the chief deceiver (Satan) deceive you about Allah.', 'O mankind, Allah’s promise is definitely true, therefore, the worldly life must not deceive you, nor should you be deceived about Allah by the big deceiver (Satan).'),
(3666, 35, 6, 1, 13, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'اِنَّ الشَّیۡطٰنَ لَکُمۡ عَدُوٌّ فَاتَّخِذُوۡہُ عَدُوًّا ؕ اِنَّمَا یَدۡعُوۡا حِزۡبَہٗ  لِیَکُوۡنُوۡا مِنۡ  اَصۡحٰبِ  السَّعِیۡرِ ؕ﴿۶﴾', 'شیطان تمہارا دشمن ہے تم بھی اسے دشمن ہی سمجھو۔ وہ اپنے پیروؤں کے گروہ کو بلاتا ہے تاکہ وہ دوزخ والوں میں ہو جائیں۔', 'تحقیق شیطان تمہارا دشمن ہے سو تم بھی سمجھ رکھو اس کو دشمن وہ تو بلاتا ہے اپنے گروہ کو اسی واسطے کے ہوں دوزخ والوں میں [۹]', 'Surely, Shaitan (Satan) is an enemy to you, so take (treat) him as an enemy. He only invites his Hizb (followers) that they may become the dwellers of the blazing Fire.', 'Surely ShaiTān (Satan) is an enemy for you. So, take him as an enemy. He only invites his group (to falsehood) so that they become inmates of the blazing fire.'),
(3667, 35, 7, 1, 13, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'اَلَّذِیۡنَ کَفَرُوۡا  لَہُمۡ عَذَابٌ شَدِیۡدٌ ۬ؕ وَ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ لَہُمۡ مَّغۡفِرَۃٌ   وَّ  اَجۡرٌ کَبِیۡرٌ ﴿٪۷﴾', 'جنہوں نے کفر کیا انکے لئے سخت عذاب ہے۔ اور جو ایمان لائے اور عمل نیک کرتے رہے انکے لئے بخشش اور بڑا ثواب ہے۔', 'جو منکر ہوئے ان کو سخت عذاب ہے اور جو یقین لائے اور کئے بھلے کام انکے لئے ہے معافی اور بڑا ثواب', 'Those who disbelieve, theirs will be a severe torment; and those who believe (in the Oneness of Allah Islamic Monotheism) and do righteous good deeds, theirs will be forgiveness and a great reward (i.e. Paradise).', 'Those who disbelieve will have a severe punishment; and those who believe and do righteous deeds will have forgiveness and a great reward.'),
(3668, 35, 8, 2, 14, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'اَفَمَنۡ زُیِّنَ لَہٗ  سُوۡٓءُ عَمَلِہٖ  فَرَاٰہُ حَسَنًا ؕ فَاِنَّ اللّٰہَ یُضِلُّ مَنۡ یَّشَآءُ وَ یَہۡدِیۡ مَنۡ یَّشَآءُ ۫ۖ فَلَا تَذۡہَبۡ نَفۡسُکَ عَلَیۡہِمۡ حَسَرٰتٍ ؕ اِنَّ اللّٰہَ عَلِیۡمٌۢ  بِمَا یَصۡنَعُوۡنَ ﴿۸﴾', 'بھلا جس شخص کو اسکے اعمال بد آراستہ کر کے دکھائے جائیں اور وہ انکو عمدہ سمجھنے لگے تو کیا وہ نیکوکار آدمی جیسا ہو سکتا ہے بیشک اللہ جسکو چاہتا ہے گمراہ رہنے دیتا ہے اور جسکو چاہتا ہے ہدایت دیتا ہے۔ تو ان لوگوں پر افسوس کر کر کے تمہارا دم نہ نکل جائے۔ یہ جو کچھ کرتے ہیں اللہ اس سے واقف ہے۔', 'بھلا ایک شخص کو کہ بھلی سمجھائی گئ اسکو اسکے کام کی برائی پھر دیکھا اس نے اسکو بھلا کیونکہ اللہ بھٹکاتا ہے جس کو چاہے اور سمجھاتا ہے جس کو چاہے سو تیرا جی نہ جاتا رہے ان پر پچتا پچتا کر اللہ کو معلوم ہے جو کچھ کرتے ہیں [۱۰]', 'Is he, then, to whom the evil of his deeds made fairseeming, so that he considers it as good (equal to one who is rightly guided)? Verily, Allah sends astray whom He wills, and guides whom He wills. So destroy not yourself (O Muhammad SAW) in sorrow for them. Truly, Allah is the AllKnower of what they do!', 'Then, can the one whose evil deed is so much adorned for him that he deems it really good (be equal to the one who differentiates between good and evil)? The fact, therefore, is that Allah lets go astray whomsoever He wills, and leads to the right path whomsoever He wills. So, (O Prophet,) let not your soul collapse in grief for them. Surely Allah knows well what they are doing.'),
(3669, 35, 9, 2, 14, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ اللّٰہُ  الَّذِیۡۤ  اَرۡسَلَ الرِّیٰحَ فَتُثِیۡرُ سَحَابًا فَسُقۡنٰہُ  اِلٰی بَلَدٍ مَّیِّتٍ فَاَحۡیَیۡنَا بِہِ الۡاَرۡضَ بَعۡدَ مَوۡتِہَا ؕ کَذٰلِکَ النُّشُوۡرُ ﴿۹﴾', 'اور اللہ ہی تو ہے جو ہوائیں چلاتا ہے پھر وہ بادل کو ابھارتی ہیں پھر ہم انکو ایک بے جان علاقے کی طرف لیجاتے ہیں پھر اس سے یعنی بارش سے زمین کو اسکے مردہ ہو جانے کے بعد زندہ کر دیتے ہیں۔ اسی طرح مردوں کا جی اٹھنا ہو گا۔', 'اور اللہ ہے جس نے چلائی ہیں ہوائیں پھر وہ اٹھاتی ہیں بادل کو پھر ہانک لے گئے ہم اسکو  ایک مردہ دیس کی طرف پھر زندہ کر دیا ہم نے اس سے زمین کو اسکے مرجانے کے بعد اسی طرح ہو گا جی اٹھنا [۱۱]', 'And it is Allah Who sends the winds, so that they raise up the clouds, and We drive them to a dead land, and revive therewith the earth after its death. As such (will be) the Resurrection!', 'Allah is the One who sends the winds, then they raise up the clouds, then We drive them to a dead land and revive the land through them after its death. In similar way shall be the Resurrection.'),
(3670, 35, 10, 2, 14, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'مَنۡ کَانَ یُرِیۡدُ الۡعِزَّۃَ  فَلِلّٰہِ  الۡعِزَّۃُ جَمِیۡعًا ؕ اِلَیۡہِ یَصۡعَدُ الۡکَلِمُ الطَّیِّبُ وَ الۡعَمَلُ الصَّالِحُ یَرۡفَعُہٗ ؕ وَ الَّذِیۡنَ یَمۡکُرُوۡنَ السَّیِّاٰتِ لَہُمۡ عَذَابٌ شَدِیۡدٌ ؕ وَ  مَکۡرُ  اُولٰٓئِکَ ہُوَ  یَبُوۡرُ ﴿۱۰﴾', 'جو شخص عزت کا طلبگار ہے تو عزت تو سب اللہ ہی کی ہے۔ اسی کی طرف پاکیزہ کلمات چڑھتے ہیں اور نیک عمل انکو بلند کرتا ہے۔ اور جو لوگ برے برے داؤ چلتے ہیں انکے لئے سخت عذاب ہے۔ اور ان کا داؤ نابود ہو جائے گا۔', 'جس کو چاہئے عزت تو اللہ کے لیے ہے ساری عزت [۱۲] اس کی طرف چڑھتا ہے کلام ستھرا [۱۳] اور کام نیک اس کو اٹھا لیتا ہے [۱۴] اور جو لوگ داؤ میں ہیں برائیوں کے انکے لیے سخت عذاب ہے اور ان کا داؤ ہے ٹوٹے کا [۱۵]', 'Whosoever desires honour, power and glory then to Allah belong all honour, power and glory (and one can get honour, power and glory only by obeying and worshipping Allah (Alone)). To Him ascend (all) the goodly words, and the righteous deeds exalt it (the goodly words i.e. the goodly words are not accepted by Allah unless and until they are followed by good deeds), but those who plot evils, theirs will be severe torment. And the plotting of such will perish.', 'Whoever desires honor, then all honor lies with Allah alone. Towards Him ascends the pure word, and the righteous deed uplifts it. As for those who plot evils, for them there is a severe punishment, and their plot itself will perish.'),
(3671, 35, 11, 2, 14, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ اللّٰہُ خَلَقَکُمۡ مِّنۡ تُرَابٍ ثُمَّ مِنۡ نُّطۡفَۃٍ ثُمَّ جَعَلَکُمۡ اَزۡوَاجًا ؕ وَ مَا تَحۡمِلُ مِنۡ اُنۡثٰی وَ لَا تَضَعُ  اِلَّا بِعِلۡمِہٖ ؕ وَ مَا یُعَمَّرُ مِنۡ مُّعَمَّرٍ وَّ لَا یُنۡقَصُ مِنۡ عُمُرِہٖۤ  اِلَّا فِیۡ  کِتٰبٍ ؕ اِنَّ ذٰلِکَ عَلَی اللّٰہِ یَسِیۡرٌ ﴿۱۱﴾', 'اور اللہ ہی نے تمکو مٹی سے پیدا کیا پھر نطفے سے پھر تمکو جوڑا جوڑا بنا دیا۔ اور کوئی عورت نہ حاملہ ہوتی ہے اور نہ جنتی ہے مگر یہ سب کچھ اسکے علم سے ہوتا ہے۔ اور نہ کسی بڑی عمر والے کو عمر زیادہ دی جاتی ہے اور نہ اسکی عمر کم کی جاتی ہے مگر سب کچھ کتاب میں لکھا ہوا ہے بیشک یہ اللہ کو آسان ہے۔', 'اور اللہ نے تم کو بنایا مٹی سے پھر بوند پانی سے پھر بنایا تم کو جوڑے جوڑے اور نہ پیٹ رہتا ہے کسی مادہ کو اور نہ وہ جنتی ہے بن خبر اس کے [۱۶] اور نہ عمر پاتا ہے کوئی بڑی عمر والا اور نہ گھٹتی ہے کسی کی عمر مگر لکھا ہے کتاب میں بیشک یہ اللہ پر آسان ہے [۱۷]', 'And Allah did create you (Adam) from dust, then from Nutfah (male and female discharge semen drops i.e. Adams offspring), then He made you pairs (male and female). And no female conceives or gives birth, but with His Knowledge. And no aged man is granted a length of life, nor is a part cut off from his life (or another mans life), but is in a Book (AlLauh AlMahfooz) Surely, that is easy for Allah.', 'Allah has created you from dust, then from a drop of semen, then He made you couples. No female conceives (a baby) nor gives birth (to it) without His knowledge; and no aged person is made to advance in age, nor is a part curtailed from his age, but all this is (recorded) in a book. Surely all this is easy for Allah.'),
(3672, 35, 12, 2, 14, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ مَا یَسۡتَوِی الۡبَحۡرٰنِ ٭ۖ ہٰذَا عَذۡبٌ فُرَاتٌ سَآئِغٌ  شَرَابُہٗ  وَ ہٰذَا مِلۡحٌ   اُجَاجٌ ؕ وَ مِنۡ کُلٍّ تَاۡکُلُوۡنَ لَحۡمًا طَرِیًّا وَّ تَسۡتَخۡرِجُوۡنَ حِلۡیَۃً تَلۡبَسُوۡنَہَا ۚ وَ تَرَی الۡفُلۡکَ فِیۡہِ مَوَاخِرَ لِتَبۡتَغُوۡا مِنۡ فَضۡلِہٖ  وَ  لَعَلَّکُمۡ  تَشۡکُرُوۡنَ ﴿۱۲﴾', 'اور دونوں دریا بھی یکساں نہیں ہیں یہ ایک تو میٹھا ہے پیاس بجھانے والا۔ جس کا پانی خوشگوار ہے اور یہ دوسرا کھاری ہے کڑوا۔ اور ہر ایک سے تم تازہ گوشت کھاتے ہو اور زیور نکالتے ہو جسے پہنتے ہو۔ اور تم دریا میں کشتیوں کو دیکھتے ہو کہ پانی کو پھاڑتی چلی آتی ہیں تاکہ تم اسکے فضل سے معاش تلاش کرو اور تاکہ شکر کرو۔', 'اور برابر نہیں دو دریا یہ میٹھا ہے پیاس بجھاتا ہے خوشگوار ہے پینا اس کا اور یہ کھارا کڑوا اور دونوں میں سے کھاتے ہو گوشت تازہ اور نکالتے ہو گہنا جسکو  پہنتے ہو [۱۸] اور تو دیکھے جہازوں کو  اس میں کہ چلتے ہیں پانی کو  پھاڑتے تاکہ  تلاش کرو اسکے فضل سے اور تاکہ تم حق مانو [۱۹]', 'And the two seas (kinds of water) are not alike, this fresh sweet, and pleasant to drink, and that saltish and bitter. And from them both you eat fresh tender meat (fish), and derive the ornaments that you wear. And you see the ships cleaving (the seawater as they sail through it), that you may seek of His Bounty, and that you may give thanks.', 'And two seas are not alike; this one is sweet, saturating, pleasant to drink, and that one is salt, bitter. But from each, you eat fresh meat, and derive ornaments that you wear. And you see the boats therein cleaving through water, so that you may search for His grace, and that you may be grateful.'),
(3673, 35, 13, 2, 14, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'یُوۡلِجُ  الَّیۡلَ فِی النَّہَارِ وَ یُوۡلِجُ  النَّہَارَ فِی الَّیۡلِ ۙ وَ سَخَّرَ الشَّمۡسَ وَ الۡقَمَرَ ۫ۖ کُلٌّ یَّجۡرِیۡ  لِاَجَلٍ مُّسَمًّی ؕ ذٰلِکُمُ اللّٰہُ  رَبُّکُمۡ لَہُ  الۡمُلۡکُ ؕ وَ الَّذِیۡنَ تَدۡعُوۡنَ مِنۡ دُوۡنِہٖ مَا یَمۡلِکُوۡنَ مِنۡ  قِطۡمِیۡرٍ ﴿ؕ۱۳﴾', 'وہی رات کو دن میں داخل کرتا اور وہی دن کو رات میں داخل کرتا ہے اور اسی نے سورج اور چاند کو کام میں لگا دیا ہے ہر ایک ایک وقت مقرر تک چل رہا ہے۔ یہی اللہ تمہارا پروردگار ہے اسی کی بادشاہی ہے اور جن لوگوں کو تم اسکے سوا پکارتے ہو وہ کھجور کی گٹھلی کے چھلکے کے برابر بھی تو کسی چیز کے مالک نہیں۔', 'رات گھساتا ہے دن میں  اور دن گھساتا ہے رات میں اور کام میں لگا دیا سورج اورچاند کو ہر ایک چلتا ہے ایک مقرر وعدہ تک [۲۰] یہ اللہ ہے تمہارا  رب اسی کے لئے بادشاہی ہے اور جن کو تم پکارتے ہو اس کے سوائے وہ مالک نہیں کھجور کی گٹھلی کے ایک چھلکے کے [۲۱]', 'He merges the night into the day (i.e. the decrease in the hours of the night are added to the hours of the day), and He merges the day into the night (i.e. the decrease in the hours of the day are added to the hours of the night). And He has subjected the sun and the moon, each runs its course for a term appointed. Such is Allah your Lord; His is the kingdom. And those, whom you invoke or call upon instead of Him, own not even a Qitmeer (the thin membrane over the datestone).', 'He makes the night enter into the day and makes the day enter into the night, and He has subjugated the sun and the moon; each one of them is running towards an appointed time. That is Allah, your Lord. To Him belongs the kingdom. And those whom you invoke beside Him do not own even the membrane on a date-stone.'),
(3674, 35, 14, 2, 14, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'اِنۡ تَدۡعُوۡہُمۡ لَا یَسۡمَعُوۡا دُعَآءَکُمۡ ۚ وَ لَوۡ سَمِعُوۡا مَا اسۡتَجَابُوۡا  لَکُمۡ ؕ وَ  یَوۡمَ الۡقِیٰمَۃِ  یَکۡفُرُوۡنَ بِشِرۡکِکُمۡ ؕ وَ لَا یُنَبِّئُکَ مِثۡلُ خَبِیۡرٍ ﴿٪۱۴﴾', 'اگر تم ان جھوٹے معبودوں کو پکارو تو وہ تمہاری پکار نہ سنیں اور اگر سن بھی لیں تو تمہاری بات کو قبول نہ کر سکیں اور قیامت کے روز تمہارے شرک سے انکار کر دیں گے اور ایک ہی باخبر کی طرح تمکو کوئی خبر نہیں دے گا۔', 'اگر تم ان کو پکارو سنیں نہیں تمہاری پکار اور اگر سنیں پہنچیں نہیں تمہارے کام پر اور قیامت کے دن منکر  ہوں گے تمہارے شریک ٹھہرانے سے [۲۲] اور کوئی نہ بتلائے گا تجھ کو جیسا بتلائے خبر رکھنے والا [۲۳]', 'If you invoke (or call upon) them, they hear not your call, and if (in case) they were to hear, they could not grant it (your request) to you. And on the Day of Resurrection, they will disown your worshipping them. And none can inform you (O Muhammad SAW) like Him Who is the AllKnower (of each and everything).', 'If you call them, they do not hear your call, and even if they were to hear, they would not respond to you. And on the Day of Judgment they will deny your having held them as Allah’s partners. And none can inform you like Him who is Aware.'),
(3675, 35, 15, 3, 15, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'یٰۤاَیُّہَا النَّاسُ اَنۡتُمُ الۡفُقَرَآءُ  اِلَی اللّٰہِ ۚ وَ اللّٰہُ  ہُوَ  الۡغَنِیُّ   الۡحَمِیۡدُ ﴿۱۵﴾', 'لوگو! تم سب اللہ کے محتاج ہو اور اللہ ہی تو بے نیاز ہے لائق حمد و ثنا ہے۔', 'اے لوگو تم ہو محتاج اللہ کی طرف اور اللہ وہی ہے بے پروا سب تعریفوں والا [۲۴]', 'O mankind! it is you who stand in need of Allah, but Allah is Rich (Free of all wants and needs), Worthy of all praise.', 'O men, you are the ones who need Allah, and Allah is Free-of-All-Needs, the Ever-Praised.'),
(3676, 35, 16, 3, 15, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'اِنۡ  یَّشَاۡ یُذۡہِبۡکُمۡ  وَ یَاۡتِ  بِخَلۡقٍ جَدِیۡدٍ ﴿ۚ۱۶﴾', 'اگر وہ چاہے تو تم کو نابود کر دے اور نئی مخلوق لے آئے۔', 'اگر چاہے تم کو لیجائے اور لے آئے ایک نئی خلقت', 'If He will, He could destroy you and bring about a new creation.', 'If He so wills, He can do away with you and bring a new creation.'),
(3677, 35, 17, 3, 15, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ مَا ذٰلِکَ عَلَی  اللّٰہِ  بِعَزِیۡزٍ ﴿۱۷﴾', 'اور یہ اللہ کو کچھ مشکل نہیں۔', 'اور یہ بات اللہ پر مشکل نہیں [۲۵]', 'And that is not hard for Allah.', 'For Allah, that is not something difficult.'),
(3678, 35, 18, 3, 15, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ لَا تَزِرُ  وَازِرَۃٌ  وِّزۡرَ اُخۡرٰی ؕ وَ اِنۡ تَدۡعُ مُثۡقَلَۃٌ  اِلٰی حِمۡلِہَا لَا یُحۡمَلۡ مِنۡہُ شَیۡءٌ وَّ لَوۡ کَانَ ذَا قُرۡبٰی ؕ اِنَّمَا تُنۡذِرُ الَّذِیۡنَ یَخۡشَوۡنَ رَبَّہُمۡ بِالۡغَیۡبِ وَ اَقَامُوا الصَّلٰوۃَ ؕ وَ مَنۡ تَزَکّٰی فَاِنَّمَا یَتَزَکّٰی  لِنَفۡسِہٖ ؕ وَ  اِلَی  اللّٰہِ  الۡمَصِیۡرُ ﴿۱۸﴾', 'اور کوئی بوجھ اٹھانے والا کسی دوسرے کا بوجھ نہ اٹھائے گا۔ اور کوئی بوجھ میں دبا ہوا اپنا بوجھ بٹانے کیلئے کسی کو بلائے تو بٹایا نہ جائے گا اگرچہ قرابتدار ہی ہو۔ اے پیغمبر تم ان ہی لوگوں کو نصیحت کر سکتے ہو جو بن دیکھے اپنے پروردگار سے ڈرتے اور پابندی سے نماز ادا کرتے ہیں۔ اور جو شخص سنورتا ہے تو وہ اپنے ہی لئے سنورتا ہے اور سب کو اللہ ہی کی طرف لوٹ کر جانا ہے۔', 'اور نہ اٹھائے گا کوئی اٹھانے والا بوجھ دوسرے کا اور اگر پکارے کوئی بوجھل اپنا بوجھ بٹانے کو کوئی نہ اٹھائے اس میں سے ذرا بھی اگر چہ ہو قرابتی [۲۶] تو تو ڈر سنا دیتا ہے انکو جو ڈرتے ہیں اپنے رب سے بن دیکھے اور قائم رکھتے ہیں نماز [۲۷] او جو کوئی سنورے گا تو یہی ہے کہ سنورے گا اپنے فائدہ کو اور اللہ کی طرف ہے سب کو پھر جانا [۲۸]', 'And no bearer of burdens shall bear anothers burden, and if one heavily laden calls another to (bear) his load, nothing of it will be lifted even though he be near of kin. You (O Muhammad SAW) can warn only those who fear their Lord unseen, and perform As-Salat (IqamatasSalat). And he who purifies himself (from all kinds of sins), then he purifies only for the benefit of his ownself. And to Allah is the (final) Return (of all).', 'No bearer will bear the burden of any other person. If a person carrying a heavy load calls (someone) to (share) his load, nothing from it shall be carried (by the latter), even though he be a near of kin. You can warn only those who fear their Lord, while He is unseen, and establish Salāh. Whoever gets purified gets purified for his own benefit. And to Allah is the final return.'),
(3679, 35, 19, 3, 15, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ مَا یَسۡتَوِی  الۡاَعۡمٰی وَ الۡبَصِیۡرُ ﴿ۙ۱۹﴾', 'اور اندھا اور آنکھ والا برابر نہیں۔', 'اور برابر نہیں اندھا اور دیکھتا', 'Not alike are the blind (disbelievers in Islamic Monotheism) and the seeing (believers in Islamic Monotheism).', 'The blind and the sighted are not equal,'),
(3680, 35, 20, 3, 15, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ لَا الظُّلُمٰتُ وَ لَا  النُّوۡرُ ﴿ۙ۲۰﴾', 'اور نہ اندھیرے اور نہ روشنی۔', 'اور نہ اندھیرا اور نہ اجالا', 'Nor are (alike) the darkness (disbelief) and the light (Belief in Islamic Monotheism).', 'nor are darkness and light,'),
(3681, 35, 21, 3, 15, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ لَا الظِّلُّ  وَ لَا  الۡحَرُوۡرُ ﴿ۚ۲۱﴾', 'اور نہ سایہ اور نہ دھوپ۔', 'اور نہ سایہ اور نہ لُو', 'Nor are (alike) the shade and the suns heat.', 'nor shade and heat of the sun.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(3682, 35, 22, 3, 15, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ مَا یَسۡتَوِی  الۡاَحۡیَآءُ  وَ لَا الۡاَمۡوَاتُ ؕ اِنَّ اللّٰہَ  یُسۡمِعُ مَنۡ یَّشَآءُ ۚ وَ مَاۤ  اَنۡتَ بِمُسۡمِعٍ  مَّنۡ فِی الۡقُبُوۡرِ ﴿۲۲﴾', 'اور نہ زندہ اور نہ مردہ لوگ برابر ہو سکتے ہیں۔ اللہ جسکو چاہتا ہے سنا دیتا ہے۔ اور تم انکو جو قبروں میں ہیں سنا نہیں سکتے۔', 'اور برابر نہیں جیتے اور نہ مردے [۲۹] اللہ سناتا ہے جس کو چاہے اور تو نہیں سنانے والا قبر میں پڑے ہوؤں کو', 'Nor are (alike) the living (believers) and the dead (disbelievers). Verily, Allah makes whom He will hear, but you cannot make hear those who are in graves.', 'And the living and the dead are not alike. Allah makes to hear whomsoever He wills. And you cannot make to hear those who are in the graves.'),
(3683, 35, 23, 3, 15, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'اِنۡ  اَنۡتَ  اِلَّا  نَذِیۡرٌ ﴿۲۳﴾', 'تم تو صرف خبردار کرنے والے ہو۔', 'تو تو بس ڈر کی خبر پہنچانے والا ہے [۳۰]', 'You (O Muhammad SAW) are only a warner (i.e. your duty is to convey Allahs Message to mankind but the guidance is in Allahs Hand).', 'You are but a warner.'),
(3684, 35, 24, 3, 15, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'اِنَّاۤ  اَرۡسَلۡنٰکَ بِالۡحَقِّ بَشِیۡرًا وَّ نَذِیۡرًا ؕ وَ اِنۡ  مِّنۡ  اُمَّۃٍ   اِلَّا خَلَا فِیۡہَا نَذِیۡرٌ ﴿۲۴﴾', 'ہم نے تمکو حق کے ساتھ خوشخبری سنانے والا اور ڈرانے والا بنا کر بھیجا ہے اور کوئی امت ایسی نہیں جس میں کوئی خبردار کرنے والا نہ گذرا ہو۔', 'ہم نے بھیجا ہے تجھ کو سچا دین دیکر خوشی اور ڈر سنانے والا اور کوئی فرقہ نہیں جس میں نہیں ہو چکا کوئی ڈر سنانے والا [۳۱]', 'Verily! We have sent you with the truth, a bearer of glad tidings, and a warner. And there never was a nation but a warner had passed among them.', 'Surely We have sent you with truth as a bearer of good news and as a warner, and there was no community without a warner having passed among them.'),
(3685, 35, 25, 3, 15, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ اِنۡ یُّکَذِّبُوۡکَ فَقَدۡ کَذَّبَ الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ ۚ جَآءَتۡہُمۡ  رُسُلُہُمۡ بِالۡبَیِّنٰتِ وَ بِالزُّبُرِ وَ بِالۡکِتٰبِ الۡمُنِیۡرِ ﴿۲۵﴾', 'اور اے نبی اگر یہ تمہاری تکذیب کریں تو جو لوگ ان سے پہلے تھے وہ بھی تکذیب کر چکے ہیں انکے پاس انکے پیغمبر نشانیاں اور صحیفے اور روشن کتابیں لے لے کر آتے رہے۔', 'اور اگر وہ تجھ کو جھٹلائیں تو آگے جھٹلا چکے ہیں جو لوگ کہ ان سے پہلے تھے پہنچے ان کے پاس رسول انکے لیکر کھلی باتیں اور صحیفے اور روشن کتاب [۳۲]', 'And if they belie you, those before them also belied. Their Messengers came to them with clear signs, and with the Scriptures, and the book giving light.', 'If they reject you, (it is not something new, because) those before them have (also) rejected (messengers). Their messengers came to them with clear proofs and with scriptures and with the enlightening book.'),
(3686, 35, 26, 3, 15, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'ثُمَّ  اَخَذۡتُ الَّذِیۡنَ کَفَرُوۡا فَکَیۡفَ کَانَ نَکِیۡرِ ﴿٪۲۶﴾', 'پھر میں نے کافروں کو پکڑ لیا سو دیکھ لو کہ میرا عذاب کیسا ہوا۔', 'پھر پکڑا میں نے منکروں کو سو کیسا ہوا انکار میرا [۳۳]', 'Then I took hold of those who disbelieved, and how terrible was My denial (punishment)!', 'Then I seized those who disbelieved. So, how was My censure !'),
(3687, 35, 27, 4, 16, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'اَلَمۡ  تَرَ  اَنَّ اللّٰہَ  اَنۡزَلَ مِنَ  السَّمَآءِ  مَآءً ۚ فَاَخۡرَجۡنَا بِہٖ ثَمَرٰتٍ  مُّخۡتَلِفًا  اَلۡوَانُہَا ؕ وَ مِنَ الۡجِبَالِ جُدَدٌۢ  بِیۡضٌ وَّ حُمۡرٌ  مُّخۡتَلِفٌ اَلۡوَانُہَا وَ غَرَابِیۡبُ سُوۡدٌ ﴿۲۷﴾', 'کیا تم نے نہیں دیکھا کہ اللہ نے آسمان سے مینہ برسایا پھر ہم نے اس سے طرح طرح کے رنگوں کے میوے پیدا کئے۔ اور پہاڑوں میں سفید اور سرخ رنگ کی گھاٹیاں ہوتی ہیں۔ جنکے مختلف رنگ ہوتے ہیں اور بعض کالی سیاہ بھی ہوتی ہیں۔', 'کیا تو نے نہ دیکھا کہ اللہ نے اتارا  آسمان سے  پانی پھر ہم نے نکالے اس سے میوے طرح طرح کے انکے رنگ [۳۴] اور پہاڑوں میں گھاٹیاں ہیں سفید اور سرخ طرح طرح کے انکے رنگ اور بھجنگے کالے [۳۵]', 'See you not that Allah sends down water (rain) from the sky, and We produce therewith fruits of varying colours, and among the mountains are streaks white and red, of varying colours and (others) very black.', 'Did you not see that Allah has sent down water from the sky? Then We brought forth with it fruits having different colours. And among the mountains there are tracks, white and red- of different colours, and ( others) utterly black.'),
(3688, 35, 28, 4, 16, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ مِنَ النَّاسِ وَ الدَّوَآبِّ وَ الۡاَنۡعَامِ مُخۡتَلِفٌ اَلۡوَانُہٗ  کَذٰلِکَ ؕ اِنَّمَا یَخۡشَی اللّٰہَ مِنۡ عِبَادِہِ  الۡعُلَمٰٓؤُا ؕ اِنَّ اللّٰہَ عَزِیۡزٌ  غَفُوۡرٌ ﴿۲۸﴾', 'اور انسانوں اور جانوروں اور مویشیوں کے بھی کئ طرح کے رنگ ہوتے ہیں۔ اللہ سے تو اسکے بندوں میں سے وہی ڈرتے ہیں جو صاحب علم ہیں۔ بیشک اللہ غالب ہے بخشنے والا ہے۔', 'اور  آدمیوں میں اور کیڑوں میں اور چوپاؤں میں کتنے رنگ ہیں اسی طرح [۳۶] اللہ سے  ڈرتے وہی ہیں اس کے بدنوں میں جن کو سمجھ ہے تحقیق اللہ زبردست ہے بخشنے والا [۳۷]', 'And of men and AdDawab (moving living creatures, beasts, etc.), and cattle, in like manner of various colours. It is only those who have knowledge among His slaves that fear Allah. Verily, Allah is AllMighty, OftForgiving.', 'And among humans and beasts and cattle, there are those having different colours as well. Only those of His slaves fear Allah who are knowledgeable. Surely Allah is Mighty, Forgiving.'),
(3689, 35, 29, 4, 16, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'اِنَّ الَّذِیۡنَ یَتۡلُوۡنَ  کِتٰبَ اللّٰہِ  وَ اَقَامُوا الصَّلٰوۃَ  وَ اَنۡفَقُوۡا مِمَّا رَزَقۡنٰہُمۡ سِرًّا وَّ عَلَانِیَۃً  یَّرۡجُوۡنَ  تِجَارَۃً  لَّنۡ تَبُوۡرَ ﴿ۙ۲۹﴾', 'جو لوگ اللہ کی کتاب پڑھتے اور نماز کی پابندی کرتے ہیں اور جو کچھ ہم نے انکو دیا ہے اس میں سے پوشیدہ اور ظاہر خرچ کرتے ہیں وہ اس تجارت کے فائدے کے امیدوار ہیں جو کبھی تباہ نہیں ہو گی۔', 'جو لوگ پڑھتے ہیں کتاب اللہ کی اور سیدھی کرتے ہیں نماز اور خرچ کرتے ہیں کچھ ہمارا دیا ہوا چھپے اور کھلے امیدوار  ہیں ایک بیوپار کے جس میں ٹوٹا نہ ہو [۳۸]', 'Verily, those who recite the Book of Allah (this Quran), and perform AsSalat (IqamatasSalat), and spend (in charity) out of what We have provided for them, secretly and openly, hope for a (sure) tradegain that will never perish.', 'Surely those who recite Allah’s Book and have established Salāh and have spent, secretly and openly, from what We have provided to them - they hope for a trade that will never crash,'),
(3690, 35, 30, 4, 16, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'لِیُوَفِّیَہُمۡ  اُجُوۡرَہُمۡ وَ یَزِیۡدَہُمۡ مِّنۡ فَضۡلِہٖ ؕ  اِنَّہٗ  غَفُوۡرٌ  شَکُوۡرٌ ﴿۳۰﴾', 'کیونکہ اللہ انکو پورا پورا بدلہ دے گا اور اپنے فضل سے کچھ زیادہ بھی دے گا۔ وہ تو بخشنے والا ہے قدردان ہے۔', 'تاکہ پورا دے انکو  ثواب ان کا اور  زیادہ  دے اپنے فضل سے تحقیق  وہ ہے بخشنے  والا قدر دان [۳۹]', 'That He may pay them their wages in full, and give them (even) more, out of His Grace. Verily! He is OftForgiving, Most Ready to appreciate (good deeds and to recompense).', 'so that He pays them their rewards in full, and gives them more out of His grace. Surely He is Most-Forgiving, Very-Appreciative.'),
(3691, 35, 31, 4, 16, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ الَّذِیۡۤ  اَوۡحَیۡنَاۤ  اِلَیۡکَ  مِنَ الۡکِتٰبِ ہُوَ الۡحَقُّ مُصَدِّقًا لِّمَا بَیۡنَ یَدَیۡہِ ؕ اِنَّ اللّٰہَ بِعِبَادِہٖ  لَخَبِیۡرٌۢ  بَصِیۡرٌ ﴿۳۱﴾', 'اور یہ کتاب جو ہم نے تمہاری طرف بھیجی ہے برحق ہے اور ان کتابوں کی تصدیق کرتی ہے جو اس سے پہلے کی ہیں۔ بیشک اللہ اپنے بندوں سے خبردار ہے اور انکو دیکھنے والا ہے۔', 'اور جو ہم نے تجھ پر اتاری کتاب وہی ٹھیک ہے تصدیق کرنے والی اپنے سےاگلی کتابوں کی بیشک اللہ اپنے بندوں سے خبردار ہے دیکھنے والا [۴۰]', 'And what We have inspired in you (O Muhammad SAW), of the Book (the Quran), it is the (very) truth (that you (Muhammad SAW) and your followers must act on its instructions), confirming that which was (revealed) before it. Verily! Allah is indeed AllAware, and AllSeer of His slaves.', 'The Book We have revealed to you is the Truth, confirming what was (revealed) before it. Surely Allah, in respect of His slaves, is All-Aware, All-Seeing.'),
(3692, 35, 32, 4, 16, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'ثُمَّ  اَوۡرَثۡنَا الۡکِتٰبَ الَّذِیۡنَ اصۡطَفَیۡنَا مِنۡ عِبَادِنَا ۚ فَمِنۡہُمۡ ظَالِمٌ لِّنَفۡسِہٖ ۚ وَ مِنۡہُمۡ مُّقۡتَصِدٌ ۚ وَ مِنۡہُمۡ سَابِقٌۢ بِالۡخَیۡرٰتِ بِاِذۡنِ اللّٰہِ ؕ ذٰلِکَ ہُوَ الۡفَضۡلُ  الۡکَبِیۡرُ ﴿ؕ۳۲﴾', 'پھر ہم نے ان لوگوں کو کتاب کا وارث ٹھہرایا جنکو اپنے بندوں میں سے برگزیدہ کیا۔ تو کچھ تو ان میں سے اپنے آپ پر ظلم کرتے ہیں۔ اور کچھ میانہ رو ہیں۔ اور کچھ اللہ کے حکم سے نیکیوں میں آگے نکل جانے والے ہیں یہی بڑا فضل ہے۔', 'پھر ہم نے وارث کئے کتاب کے وہ لوگ جن کو چن لیا ہم نے اپنے بندوں میں سے پھر کوئی ان میں برا کرتا ہے اپنی جان کا اور کوئی ان میں ہے بیچ کی چال پر اور کوئی ان میں آگے بڑھ گیا ہے لیکر خوبیاں اللہ کے حکم سے یہی ہے بڑی بزرگی [۴۱]', 'Then We gave the Book the Quran) for inheritance to such of Our slaves whom We chose (the followers of Muhammad SAW). Then of them are some who wrong their ownselves, and of them are some who follow a middle course, and of them are some who are, by Allahs Leave, foremost in good deeds. That (inheritance of the Quran), that is indeed a great grace.', 'Then We conveyed the Book as an heritage to those of Our slaves whom We chose. Now, some of them are those who wrong their own selves, and some of them are mediocre, and some of them are those who outpace (others) in righteous deeds with Allah’s permission. That is the great bounty,'),
(3693, 35, 33, 4, 16, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'جَنّٰتُ عَدۡنٍ یَّدۡخُلُوۡنَہَا یُحَلَّوۡنَ فِیۡہَا مِنۡ اَسَاوِرَ  مِنۡ ذَہَبٍ وَّ لُؤۡلُؤًا ۚ وَ لِبَاسُہُمۡ  فِیۡہَا  حَرِیۡرٌ ﴿۳۳﴾', 'ان لوگوں کے لئے ہمیشہ رہنے والی جنتیں ہیں جن میں وہ داخل ہوں گے۔ وہاں انکو سونے کے کنگن اور موتی پہنائے جائیں گے۔ اور انکی پوشاک ریشمی ہو گی۔', 'باغ ہیں بسنے کے جن میں  وہ جائیں گے وہاں انکو  پہنایا جائے گا کنگن سونے کے او رموتی کے اور انکی پوشاک وہاں ریشمی ہے [۴۲]', 'Adn (Eden) Paradise (everlasting Gardens) will they enter, therein will they be adorned with bracelets of gold and pearls, and their garments there will be of silk (i.e. in Paradise).', 'gardens of eternity they enter. They will be ornamented with bracelets of gold and with pearls, and their dress therein will be (of) silk.'),
(3694, 35, 34, 4, 16, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ قَالُوا الۡحَمۡدُ لِلّٰہِ الَّذِیۡۤ  اَذۡہَبَ عَنَّا الۡحَزَنَ ؕ اِنَّ  رَبَّنَا لَغَفُوۡرٌ  شَکُوۡرُۨ ﴿ۙ۳۴﴾', 'وہ کہیں گے کہ اللہ کا شکر ہے جس نے ہم سے رنج و غم دور کیا۔ بیشک ہمارا پروردگار بخشنے والا ہے قدردان ہے۔', 'اور کہیں گے شکر اللہ کا جس نے دور کیا ہم سےغم بیشک ہمارا رب بخشنے والا قدردان ہے [۴۳]', 'And they will say: \"All the praises and thanks be to Allah, Who has removed from us (all) grief. Verily, our Lord is indeed OftForgiving, Most Ready to appreciate (good deeds and to recompense).', 'And they will say, “Praise be to Allah who has removed all sorrow from us. Surely our Lord is Most-Forgiving, Very-Appreciative,'),
(3695, 35, 35, 4, 16, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'الَّذِیۡۤ  اَحَلَّنَا  دَارَ الۡمُقَامَۃِ  مِنۡ فَضۡلِہٖ ۚ لَا یَمَسُّنَا فِیۡہَا نَصَبٌ وَّ لَا یَمَسُّنَا فِیۡہَا  لُغُوۡبٌ ﴿۳۵﴾', 'جس نے ہمکو اپنے فضل سے ہمیشہ کے رہنے کے گھر میں اتارا۔ یہاں نہ تو ہمکو کوئی تکلیف پہنچے گی اور نہ تکان ہی ہو گی۔', 'جس نے اتارا ہم کو آباد رہنے کے گھر میں اپنے فضل سے نہ پہنچے ہم کو اس میں مشقت اور نہ پہنچے ہمکو اس میں تھکنا [۴۴]', 'Who, out of His Grace, has lodged us in a home that will last forever; there, toil will touch us not, nor weariness will touch us.\"', 'who, out of His grace, has made us land at a home of eternal living where we are neither touched by weariness, nor are we touched by boredom.”'),
(3696, 35, 36, 4, 16, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ الَّذِیۡنَ کَفَرُوۡا لَہُمۡ نَارُ جَہَنَّمَ ۚ لَا یُقۡضٰی عَلَیۡہِمۡ  فَیَمُوۡتُوۡا وَ لَا یُخَفَّفُ عَنۡہُمۡ  مِّنۡ عَذَابِہَا ؕ کَذٰلِکَ  نَجۡزِیۡ  کُلَّ کَفُوۡرٍ ﴿ۚ۳۶﴾', 'اور جن لوگوں نے کفر کیا انکے لئے دوزخ کی آگ ہے۔ نہ انہیں موت ہی آئے گی کہ مر جائیں اور نہ دوزخ کا عذاب ہی ان سے ہلکا کیا جائے گا۔ ہم ہر ایک ناشکرے کو ایسا ہی بدلہ دیا کرتے ہیں۔', 'اور جو لوگ منکر ہیں انکے لئے ہے آگ دوزخ کی نہ ان پر حکم پہنچے کہ مر جائیں اور نہ ان پر ہلکی ہو وہاں کی کچھ کلفت یہ سزا دیتےہیں ہم ہر ناشکر کو [۴۵]', 'But those who disbelieve, (in the Oneness of Allah - Islamic Monotheism) for them will be the Fire of Hell. Neither it will have a complete killing effect on them so that they die, nor shall its torment be lightened for them. Thus do We requite every disbeliever!', 'As for those who disbelieve, for them shall be the fire of Jahannam; neither they will be sentenced to death, so that they could die, nor will its torment be lightened for them. It is in this way that We punish every infidel.'),
(3697, 35, 37, 4, 16, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ ہُمۡ یَصۡطَرِخُوۡنَ فِیۡہَا ۚ رَبَّنَاۤ اَخۡرِجۡنَا نَعۡمَلۡ صَالِحًا غَیۡرَ الَّذِیۡ کُنَّا نَعۡمَلُ ؕ اَوَ لَمۡ  نُعَمِّرۡکُمۡ مَّا یَتَذَکَّرُ فِیۡہِ مَنۡ تَذَکَّرَ وَ جَآءَکُمُ  النَّذِیۡرُ ؕ فَذُوۡقُوۡا  فَمَا لِلظّٰلِمِیۡنَ  مِنۡ نَّصِیۡرٍ ﴿٪۳۷﴾', 'وہ اس میں چلائیں گے کہ اے پروردگار ہم کو نکال لے اب ہم نیک عمل کیا کریں گے نہ کہ وہ جو پہلے کرتے تھے۔ کیا ہم نے تمکو اتنی عمر نہیں دی تھی کہ اس میں جو سوچنا چاہتا سوچ لیتا اور تمہارے پاس ڈرانے والا بھی آیا تھا تو اب مزے چکھو ظالموں کا کوئی مددگار نہیں۔', 'اور وہ چلائیں اس میں اے رب ہم کو نکال کہ ہم کچھ بھلا کر لیں وہ نہیں جو کرتے رہے [۴۶] کیا ہم نے عمر نہ دی تھی تمکو اتنی کہ جس میں سوچ لے جس کو سوچنا ہو او رپہنچا تمہارے پاس ڈرانے  والا اب چکھو کہ کوئی نہیں گنہگاروں کا مددگار [۴۷]', 'Therein they will cry: \"Our Lord! Bring us out, we shall do righteous good deeds, not (the evil deeds) that we used to do.\" (Allah will reply): \"Did We not give you lives long enough, so that whosoever would receive admonition, - could receive it? And the warner came to you. So taste you (the evil of your deeds). For the Zalimoon (polytheists and wrongdoers, etc.) there is no helper.\"', 'And they will be crying therein, “Our Lord, take us out (from here), and we will act righteously, not in the way we have been doing before.” (Allah will say to them,) “Did We not give you an age in your life in which lesson could have been learnt by the one who wished to take lesson? And (furthermore) the warner had (also) come to you. So, have a taste, because the wrongdoers will have no supporter.'),
(3698, 35, 38, 5, 17, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'اِنَّ اللّٰہَ عٰلِمُ غَیۡبِ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ اِنَّہٗ عَلِیۡمٌۢ  بِذَاتِ الصُّدُوۡرِ ﴿۳۸﴾', 'بیشک اللہ ہی آسمانوں اور زمین کی پوشیدہ باتوں کا جاننے والا ہے۔ وہ تو دلوں کے بھیدوں تک سے واقف ہے۔', 'اللہ بھید جاننے والا ہے آسمانوں کا اور زمین کا اس کو خوب معلوم ہے جو بات ہے دلوں میں [۴۸]', 'Verily, Allah is the AllKnower of the unseen of the heavens and the earth. Verily! He is the AllKnower of that is in the breasts.', 'Surely Allah is the Knower of the unseen in the heavens and the earth. Indeed He fully knows what lies in the hearts.'),
(3699, 35, 39, 5, 17, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'ہُوَ الَّذِیۡ جَعَلَکُمۡ خَلٰٓئِفَ فِی الۡاَرۡضِ ؕ فَمَنۡ  کَفَرَ فَعَلَیۡہِ  کُفۡرُہٗ ؕ وَ لَا یَزِیۡدُ الۡکٰفِرِیۡنَ کُفۡرُہُمۡ عِنۡدَ  رَبِّہِمۡ  اِلَّا مَقۡتًا ۚ وَ لَا یَزِیۡدُ الۡکٰفِرِیۡنَ  کُفۡرُہُمۡ اِلَّا خَسَارًا ﴿۳۹﴾', 'وہی تو ہے جس نے تمکو زمین میں پہلے لوگوں کا جانشین بنایا اب جس نے کفر کیا اسکے کفر کا ضرر اسی کو ہے۔ اور کافروں کیلئے انکے کفر سے پروردگار کے ہاں ناخوشی ہی بڑھتی ہے اور کافروں کو ان کا کفر نقصان میں اضافہ ہی کرتا ہے۔', 'وہی ہے جس نے کیا تمکو قائم مقام زمین میں [۴۹] پھر جو کوئی ناشکری کرے تو اس پر  پڑے اسکی ناشکری اور منکروں کو نہ بڑھے گی  انکے انکار سے ان کے  رب کے سامنے مگر بیزاری اور منکروں کو نہ بڑھے گا انکے انکار سے مگر نقصان [۵۰]', 'He it is Who has made you successors generations after generations in the earth, so whosoever disbelieves (in Islamic Monotheism) on him will be his disbelief. And the disbelief of the disbelievers adds nothing but hatred with their Lord. And the disbelief of the disbelievers adds nothing but loss.', 'He is the One who has made you successors (of the past generations) on the earth. So the one who becomes infidel, his infidelity will go against himself. Their infidelity adds nothing to the infidels but anger from their Lord, and their infidelity adds nothing to the infidels but loss.'),
(3700, 35, 40, 5, 17, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'قُلۡ  اَرَءَیۡتُمۡ شُرَکَآءَکُمُ الَّذِیۡنَ تَدۡعُوۡنَ مِنۡ  دُوۡنِ اللّٰہِ ؕ اَرُوۡنِیۡ مَاذَا خَلَقُوۡا مِنَ الۡاَرۡضِ اَمۡ لَہُمۡ شِرۡکٌ فِی السَّمٰوٰتِ ۚ اَمۡ اٰتَیۡنٰہُمۡ کِتٰبًا فَہُمۡ عَلٰی بَیِّنَتٍ مِّنۡہُ ۚ بَلۡ  اِنۡ یَّعِدُ الظّٰلِمُوۡنَ بَعۡضُہُمۡ بَعۡضًا اِلَّا غُرُوۡرًا ﴿۴۰﴾', 'بھلا تم نے اپنے شریکوں کو دیکھا جنکو تم اللہ کے سوا پکارتے ہو۔ مجھے دکھاؤ کہ انہوں نے زمین میں سے کون سی چیز پیدا کی ہے یا کیا آسمانوں میں انکی شرکت ہے یا ہم نے انکو کوئی کتاب دی ہے جسکی وہ سند رکھتے ہوں؟ ان میں سے کوئی بات بھی نہیں بلکہ ظالم جو ایک دوسرے کو وعدہ دیتے ہیں محض فریب ہے۔', 'تو کہہ بھلا دیکھو تو اپنے شریکوں کو جن کو  پکارتے ہو اللہ کے سوائے دکھلاؤ تو مجھ کو کیا بنایا انہوں نے زمین میں یا کچھ ان کا ساجھا ہے آسمانوں میں [۵۱] یا ہم نے دی ہے انکو کوئی کتاب سو یہ سند رکھتے ہیں اس کی [۵۲] کوئی نہیں پر جو وعدہ بتلاتے ہیں گنہگار ایک دوسرے کو سب فریب ہے [۵۳]', 'Say (O Muhammad SAW): \"Tell me or inform me (what) do you think about your (socalled) partnergods to whom you call upon besides Allah, show me, what they have created of the earth? Or have they any share in the heavens? Or have We given them a Book, so that they act on clear proof therefrom? Nay, the Zalimoon (polytheists and wrongdoers, etc.) promise one another nothing but delusions.\"', 'Say, “Tell me about your (presumed) co-gods whom you invoke beside Allah. Show me that part of the earth that they have created. Or do they have a share in the (creation) of the heavens?” Or have We given them a book so that they are upon a clear proof from it? No, but the wrongdoers promise one another nothing but delusion.'),
(3701, 35, 41, 5, 17, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'اِنَّ اللّٰہَ یُمۡسِکُ  السَّمٰوٰتِ وَ الۡاَرۡضَ اَنۡ تَزُوۡلَا ۬ۚ وَ لَئِنۡ زَالَتَاۤ  اِنۡ  اَمۡسَکَہُمَا مِنۡ اَحَدٍ مِّنۡۢ بَعۡدِہٖ ؕ اِنَّہٗ کَانَ حَلِیۡمًا غَفُوۡرًا ﴿۴۱﴾', 'اللہ ہی آسمانوں اور زمین کو تھامے ہوئے ہے کہ کہیں وہ اپنی جگہ سے ٹل نہ جائیں۔ اور اگر وہ ٹلنے لگیں تو اللہ کے سوا کوئی ایسا نہیں جو انکو تھام سکے۔ بیشک وہ بردبار ہے بخشنے والا ہے۔', 'تحقیق اللہ تھام رہا ہے آسمانوں کو اور زمین کو کہ ٹل نہ جائیں اور اگر ٹل جائیں تو کوئی نہ تھام سکے انکو  اس کے سوائے [۵۴] وہ ہے تحمل والا بخشنے والا [۵۵]', 'Verily! Allah grasps the heavens and the earth lest they move away from their places, and if they were to move away from their places, there is not one that could grasp them after Him. Truly, He is Ever Most Forbearing, OftForgiving.', 'Undoubtedly, Allah holds back the heavens and the earth from leaving their existing state, and if they were to leave, there is none who can hold them back, except Him. Surely He is Forbearing, Most-Forgiving.'),
(3702, 35, 42, 5, 17, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ اَقۡسَمُوۡا بِاللّٰہِ جَہۡدَ اَیۡمَانِہِمۡ لَئِنۡ جَآءَہُمۡ  نَذِیۡرٌ لَّیَکُوۡنُنَّ اَہۡدٰی مِنۡ اِحۡدَی الۡاُمَمِ ۚ فَلَمَّا جَآءَہُمۡ  نَذِیۡرٌ  مَّا زَادَہُمۡ  اِلَّا  نُفُوۡرَۨا ﴿ۙ۴۲﴾', 'اور یہ اللہ کی بڑی بڑی قسمیں کھاتے ہیں کہ اگر انکے پاس کوئی خبردار کرنے والا آئے تو یہ ہر ایک امت سے بڑھ کر ہدایت پر ہوں۔ مگر جب انکے پاس خبردار کرنے والا آیا تو اس سے انکو نفرت ہی بڑھی۔', 'اور قسمیں کھاتے تھے اللہ کی تاکید کی قسمیں اپنی کہ اگر آئے گا انکے پاس کوئی ڈر سنانے والا البتہ بہتر  راہ چلیں گے ہر ایک امت سے  پھر جب آیا ان کے پاس ڈر سنانے والا اور زیادہ ہو گیا ان کا بدکنا', 'And they swore by Allah their most binding oath, that if a warner came to them, they would be more guided than any of the nations (before them), yet when a warner (Muhammad SAW) came to them, it increased in them nothing but flight (from the truth),', 'They had sworn forceful oaths that if a warner would come to them, they would be more receptive to guidance than any other community. But when a warner came to them, it added nothing to them but aversion,'),
(3703, 35, 43, 5, 17, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'اسۡتِکۡـبَارًا فِی  الۡاَرۡضِ وَ مَکۡرَ السَّیِّیَٔ ؕ وَ لَا یَحِیۡقُ الۡمَکۡرُ السَّیِّیُٔ  اِلَّا بِاَہۡلِہٖ ؕ فَہَلۡ یَنۡظُرُوۡنَ  اِلَّا سُنَّتَ الۡاَوَّلِیۡنَ ۚ فَلَنۡ تَجِدَ لِسُنَّتِ اللّٰہِ تَبۡدِیۡلًا ۬ۚ وَ لَنۡ تَجِدَ  لِسُنَّتِ  اللّٰہِ تَحۡوِیۡلًا ﴿۴۳﴾', 'یعنی انہوں نے ملک میں غرور کرنا اور بری چال چلنا اختیار کیا اور بری چال کا وبال اسکے چلنے والے ہی پر پڑتا ہے۔ یہ تو پہلے لوگوں کی روش کے سوا اور کسی چیز کے منتظر نہیں سو تم اللہ کی عادت میں ہرگز تبدیلی نہ پاؤ گے اور نہ اللہ کے طریقے میں کوئی تغیر دیکھو گے۔', 'غرور کرنا ملک میں اور داؤ کرنا برے کام کا اور برائی کا داؤ  الٹے گا انہی داؤں والوں پر [۵۶] پھر اب وہی راہ دیکھتے ہیں پہلوں کے دستور کی سو تو نہ پائے گا اللہ کا دستور بدلتا اور نہ پائے گا اللہ کا دستور ٹلتا [۵۷]', '(They took to flight because of their) arrogance in the land and their plotting of evil. But the evil plot encompasses only him who makes it. Then, can they expect anything (else), but the Sunnah (way of dealing) of the peoples of old? So no change will you find in Allahs Sunnah (way of dealing), and no turning off will you find in Allahs Sunnah (way of dealing).', 'because of their showing arrogance in the land and plotting of evil. And the evil plot engulfs none but its own people (who make it). So, they are looking for nothing but the (divine) practice with the earlier people. So you will never find in Allah’s practice any change, and you will never find in Allah’s practice any diversion.'),
(3704, 35, 44, 5, 17, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'اَوَ لَمۡ یَسِیۡرُوۡا فِی الۡاَرۡضِ فَیَنۡظُرُوۡا کَیۡفَ کَانَ عَاقِبَۃُ  الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ وَ کَانُوۡۤا اَشَدَّ مِنۡہُمۡ  قُوَّۃً ؕ وَ مَا کَانَ اللّٰہُ  لِیُعۡجِزَہٗ  مِنۡ شَیۡءٍ  فِی السَّمٰوٰتِ وَ لَا فِی الۡاَرۡضِ ؕ اِنَّہٗ  کَانَ عَلِیۡمًا قَدِیۡرًا ﴿۴۴﴾', 'کیا انہوں نے زمین میں سیر نہیں کی تاکہ دیکھتے کہ جو لوگ ان سے پہلے تھے ان کا انجام کیا ہوا حالانکہ وہ ان سے قوت میں بہت زیادہ تھے۔ اور اللہ ایسا نہیں کہ آسمانوں اور زمین میں کوئی چیز اسکو عاجز کر سکے۔ وہ علم والا ہے قدرت والا ہے۔', 'کیا پھرے نہیں ملک میں کہ دیکھ لیں کیسا ہوا انجام ان لوگوں کا جو ان سے پہلے تھے اور تھے ان سے بہت سخت زور میں اور اللہ وہ نہیں جس کو  تھکائے کوئی چیز آسمانوں میں اور نہ زمین میں وہی ہے سب کچھ جانتا کر سکتا [۵۸]', 'Have they not travelled in the land, and seen what was the end of those before them, and they were superior to them in power? Allah is not such that anything in the heavens or in the earth escapes Him. Verily, He is AllKnowing, AllOmnipotent.', 'Did they not travel in the land and see how was the end of those before them? They were stronger than these in power. Allah is not such that something in the heavens or the earth can frustrate Him. Surely He is All-Knowing, All-Powerful.'),
(3705, 35, 45, 5, 17, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'فاطر', 'وَ لَوۡ یُؤَاخِذُ اللّٰہُ  النَّاسَ بِمَا کَسَبُوۡا مَا تَرَکَ عَلٰی ظَہۡرِہَا مِنۡ دَآبَّۃٍ  وَّ لٰکِنۡ یُّؤَخِّرُہُمۡ  اِلٰۤی  اَجَلٍ مُّسَمًّی ۚ فَاِذَا جَآءَ  اَجَلُہُمۡ فَاِنَّ اللّٰہَ کَانَ بِعِبَادِہٖ  بَصِیۡرًا ﴿٪۴۵﴾', 'اور اگر اللہ لوگوں کو انکے اعمال کے سبب پکڑنے لگتا تو روئے زمین پر ایک بھی چلنے پھرنے والے کو نہ چھوڑتا۔ لیکن وہ انکو ایک وقت مقرر تک مہلت دیئے جاتا ہے۔ سو جب ان کا وقت آ جائے گا تو انکے اعمال کا بدلہ دے گا کیونکہ اللہ اپنے بندوں کو دیکھ رہا ہے۔', 'اور اگر پکڑ کرے اللہ لوگوں کی ان کی کمائی پرنہ چھوڑے زمین کی پیٹھ پر ایک بھی ہلنے چلنے والا [۵۹] پر ان کو ڈھیل دیتا ہے ایک مقرر  وعدہ تک پھر جب آئے ان کا وعدہ تو اللہ کی نگاہ میں ہیں اس کے سب بندے [۶۰]', 'And if Allah were to punish men for that which they earned, He would not leave a moving (living) creature on the surface of the earth, but He gives them respite to an appointed term, and when their term comes, then verily, Allah is Ever AllSeer of His slaves.', 'If Allah were to take mankind to task for what they did, He would have not left a living creature on its back, but He delays them upto an appointed time. So when their time will come, then Allah is the One who will see His slaves.'),
(3706, 36, 1, 1, 18, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'یٰسٓ ۚ﴿۱﴾', 'یٰس ۔', 'یٰس ۔', 'Ya-Seen. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings.)', 'Yā Sīn'),
(3707, 36, 2, 1, 18, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'وَ الۡقُرۡاٰنِ  الۡحَکِیۡمِ  ۙ﴿۲﴾', 'قسم ہے قرآن کی جو حکمت سے بھرا ہوا ہے۔', 'قسم ہے اس پکے قرآن کی', 'By the Quran, full of wisdom (i.e. full of laws, evidences, and proofs),', 'By the Qur’ān, that is full of wisdom,'),
(3708, 36, 3, 1, 18, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'اِنَّکَ  لَمِنَ  الۡمُرۡسَلِیۡنَ ۙ﴿۳﴾', 'اے محمد ﷺ بیشک تم پیغمبروں میں سے ہو۔', 'تو تحقیق ہے بھیجے ہوؤں میں سے', 'Truly, you (O Muhammad SAW) are one of the Messengers,', 'You are truly one of the messengers of Allah,'),
(3709, 36, 4, 1, 18, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'عَلٰی صِرَاطٍ مُّسۡتَقِیۡمٍ ؕ﴿۴﴾', 'سیدھے رستے پر ہو۔', 'اوپر سیدھی راہ کے [۱]', 'On a Straight Path (i.e. on Allahs religion of Islamic Monotheism).', '(and you are) on a straight path,'),
(3710, 36, 5, 1, 18, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'تَنۡزِیۡلَ الۡعَزِیۡزِ  الرَّحِیۡمِ ۙ﴿۵﴾', 'یہ قرآن غالب و مہربان کا نازل کیا ہوا ہے۔', 'اتارا زبردست رحم  والے نے [۲]', 'This is) a Revelation sent down by the AllMighty, the Most Merciful,', '(this Qur’ān being) a revelation from the All- Mighty, the Very-Merciful,'),
(3711, 36, 6, 1, 18, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'لِتُنۡذِرَ قَوۡمًا مَّاۤ  اُنۡذِرَ اٰبَآؤُہُمۡ فَہُمۡ غٰفِلُوۡنَ ﴿۶﴾', 'تاکہ تم ان لوگوں کو جنکے باپ دادا کو خبردار نہیں کیا گیا تھا خبردار کر دو کہ وہ غفلت میں پڑے ہوئے ہیں۔', 'تاکہ تو ڈرائے ایک قوم کو کہ ڈر نہیں سنا انکے باپ دادوں نے سو ان کو خبر نہیں', 'In order that you may warn a people whose forefathers were not warned, so they are heedless.', 'so that you may warn a people whose fathers were not warned, and hence, they are unaware.'),
(3712, 36, 7, 1, 18, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'لَقَدۡ حَقَّ الۡقَوۡلُ عَلٰۤی  اَکۡثَرِہِمۡ  فَہُمۡ  لَا یُؤۡمِنُوۡنَ ﴿۷﴾', 'ان میں سے اکثر پر اللہ کی بات پوری ہو چکی ہے سو وہ ایمان نہیں لائیں گے۔', 'ثابت ہو چکی ہے بات ان میں بہتوں پر سو وہ نہ مانیں گے [۳]', 'Indeed the Word (of punishment) has proved true against most of them, so they will not believe.', 'The word has indeed come true about most of them, so they will not believe.'),
(3713, 36, 8, 1, 18, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'اِنَّا جَعَلۡنَا فِیۡۤ  اَعۡنَاقِہِمۡ  اَغۡلٰلًا فَہِیَ  اِلَی  الۡاَذۡقَانِ فَہُمۡ  مُّقۡمَحُوۡنَ ﴿۸﴾', 'ہم نے انکی گردنوں میں طوق ڈال رکھے ہیں اور وہ تھوڑیوں تک پھنسے ہوئے ہیں تو انکی گردنیں اکڑی ہوئی ہیں۔', 'ہم نے ڈالے ہیں انکی گردنوں میں طوق سو  وہ ہیں ٹھوڑیوں تک پھر انکے سر  اُلل (ابھر) رہے ہیں [۴]', 'Verily! We have put on their necks iron collars reaching to chins, so that their heads are forced up.', 'We have placed iron collars on their necks, so they are reaching up to their chins, and their heads are forced to remain upwards.'),
(3714, 36, 9, 1, 18, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'وَ جَعَلۡنَا مِنۡۢ بَیۡنِ اَیۡدِیۡہِمۡ سَدًّا وَّ مِنۡ خَلۡفِہِمۡ سَدًّا فَاَغۡشَیۡنٰہُمۡ فَہُمۡ لَا یُبۡصِرُوۡنَ ﴿۹﴾', 'اور ہم نے انکے آگے بھی دیوار بنا دی اور انکے پیچھے بھی پھر ان پر پردہ ڈال دیا تو یہ دیکھ نہیں سکتے۔', 'اور بنائی ہم نے ان کے آگے دیوار اور پیچھے دیوار پھر اوپر سے ڈھانک دیا سو ان کو کچھ نہیں سوجھتا [۵]', 'And We have put a barrier before them, and a barrier behind them, and We have covered them up, so that they cannot see.', 'And We have placed a barrier in front of them and a barrier behind them, and (thus) they are encircled by Us; so they do not see.'),
(3715, 36, 10, 1, 18, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'وَ سَوَآءٌ عَلَیۡہِمۡ ءَاَنۡذَرۡتَہُمۡ اَمۡ لَمۡ تُنۡذِرۡہُمۡ  لَا  یُؤۡمِنُوۡنَ ﴿۱۰﴾', 'اور تم انکو خبردار کرو یا نہ کرو انکے لئے برابر ہے یہ ایمان نہیں لائیں گے۔', 'اور برابر ہے ان کو تو ڈرائے یا نہ ڈرائے  یقین نہیں کریں گے [۶]', 'It is the same to them whether you warn them or you warn them not, they will not believe.', 'It is all equal for them whether you warn them or do not warn them, they will not believe.'),
(3716, 36, 11, 1, 18, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'اِنَّمَا تُنۡذِرُ مَنِ اتَّبَعَ  الذِّکۡرَ  وَ خَشِیَ الرَّحۡمٰنَ بِالۡغَیۡبِ ۚ فَبَشِّرۡہُ  بِمَغۡفِرَۃٍ وَّ اَجۡرٍ  کَرِیۡمٍ ﴿۱۱﴾', 'تم تو صرف اس شخص کو خبردار کر سکتے ہو جو اس نصیحت یعنی قرآن کی پیروی کرے اور رحمٰن سے غائبانہ ڈرے سو اسکو مغفرت اور بڑے ثواب کی بشارت سنا دو۔', 'تو ڈر سناتے اسکو جو چلے سمجھائے پر اور ڈرے رحمٰن سے بن دیکھے سو  اسکو خوشخبری دے معافی کی اور عزت کے ثواب کی [۷]', 'You can only warn him who follows the Reminder (the Quran), and fears the Most Beneficent (Allah) unseen. Bear you to such one the glad tidings of forgiveness, and a generous reward (i.e. Paradise).', 'You can (usefully) warn only the one who follows the advice and fears the RaHmān (the All-Merciful Allah) without seeing (Him). So give him the good news of forgiveness and of a noble reward.'),
(3717, 36, 12, 1, 18, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'اِنَّا نَحۡنُ نُحۡیِ الۡمَوۡتٰی وَ نَکۡتُبُ مَا قَدَّمُوۡا وَ اٰثَارَہُمۡ ؕؑ وَ کُلَّ شَیۡءٍ اَحۡصَیۡنٰہُ  فِیۡۤ   اِمَامٍ  مُّبِیۡنٍ ﴿٪۱۲﴾', 'بیشک ہم مردوں کو زندہ کریں گے اور جو کچھ وہ آگے بھیج چکے اور جو انکے نشان پیچھے رہ گئے ہم انکو قلم بند کر لیتے ہیں اور ہر چیز کو ہم نے کتاب روشن یعنی لوح محفوظ میں لکھ رکھا ہے۔', 'ہم تو ہیں جو زندہ کرتے ہیں مردوں کو [۸] اور لکھتے ہیں جو آگے بھیج چکے اور جو نشان انکے  پیچھے رہے [۹] اور ہر چیز گن لی ہے ہم نے ایک کھلی اصل میں [۱۰]', 'Verily, We give life to the dead, and We record that which they send before (them), and their traces (their footsteps and walking on the earth with their legs to the mosques for the five compulsory congregational prayers, Jihad (holy fighting in Allahs Cause) and all other good and evil they did, and that which they leave behind), and all things We have recorded with numbers (as a record) in a Clear Book.', 'Surely We will give new life to the dead, and We are recording whatever (deeds) they send before them and whatever effects they leave behind. Every thing is fully computed by Us in a manifest book of record.'),
(3718, 36, 13, 2, 0, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'وَ اضۡرِبۡ لَہُمۡ مَّثَلًا  اَصۡحٰبَ الۡقَرۡیَۃِ ۘ اِذۡ جَآءَہَا  الۡمُرۡسَلُوۡنَ ﴿ۚ۱۳﴾', 'اور ان سے گاؤں والوں کا قصہ بیان کرو جب انکے پاس پیغمبر آئے۔', 'اور بیان کر انکے  واسطے ایک مثل اس گاؤں کے لوگوں کی [۱۱] جبکہ آئے اس میں بھیجے ہوئے [۱۲]', 'And put forward to them a similitude; the (story of the) dwellers of the town, (It is said that the town was Antioch (Antakiya)), when there came Messengers to them.', 'Cite to them the example of the People of the Town, when the messengers came to it,'),
(3719, 36, 14, 2, 0, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'اِذۡ  اَرۡسَلۡنَاۤ  اِلَیۡہِمُ  اثۡنَیۡنِ  فَکَذَّبُوۡہُمَا فَعَزَّزۡنَا بِثَالِثٍ فَقَالُوۡۤا اِنَّاۤ  اِلَیۡکُمۡ مُّرۡسَلُوۡنَ ﴿۱۴﴾', 'یعنی جب ہم نے انکی طرف دو پیغمبر بھیجے تو انہوں نے انکو جھٹلایا۔ پھر ہم نے تیسرے سے تقویت دی تو انہوں نے کہا کہ ہم تمہاری طرف پیغمبر ہو کر آئے ہیں۔', 'جب بھیجے  ہم نے انکی طرف دو تو ان کو کو جھٹلایا پھر ہم نے قوت دی تیسرے سے تب کہا انہوں نے ہم تمہاری طرف آئے ہیں بھیجے ہوئے [۱۳]', 'When We sent to them two Messengers, they belied them both, so We reinforced them with a third, and they said: \"Verily! We have been sent to you as Messengers.\"', 'when We sent to them two (apostles), and they rejected both of them, so We confirmed them with a third one. So they said, “We are sent to you.”'),
(3720, 36, 15, 2, 0, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'قَالُوۡا مَاۤ  اَنۡتُمۡ  اِلَّا بَشَرٌ مِّثۡلُنَا ۙ وَ مَاۤ اَنۡزَلَ  الرَّحۡمٰنُ  مِنۡ شَیۡءٍ ۙ اِنۡ  اَنۡتُمۡ  اِلَّا تَکۡذِبُوۡنَ ﴿۱۵﴾', 'وہ بولے کہ تم اور کچھ نہیں مگر ہماری طرح کے آدمی ہو اور رحمٰن نے کوئی چیز بھی نازل نہیں کی تم محض جھوٹ بولتے ہو۔', 'وہ بولے تم تو یہی انسان ہو جیسے ہم اور رحمٰن نے کچھ نہیں اتارا تم سارے جھوٹ کہتے ہو [۱۴]', 'They (people of the town) said: \"You are only human beings like ourselves, and the Most Beneficent (Allah) has revealed nothing, you are only telling lies.\"', 'They (the people of the Town) said, “You are no more than human beings like us, and the RaHmān (the All-Merciful Allah) has not sent down any thing. You are but telling a lie.”'),
(3721, 36, 16, 2, 0, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'قَالُوۡا رَبُّنَا یَعۡلَمُ  اِنَّاۤ  اِلَیۡکُمۡ لَمُرۡسَلُوۡنَ ﴿۱۶﴾', 'انہوں نے کہا کہ ہمارا پروردگار جانتا ہے کہ ہم تمہاری طرف پیغام دے کر بھیجے گئے ہیں۔', 'کہا ہمارا رب جانتا ہے ہم بیشک تمہاری طرف بھیجے ہوئے آئے ہیں [۱۵]', 'The Messengers said: \"Our Lord knows that we have been sent as Messengers to you,', 'They (the messengers) said, “Our Lord knows that we are undoubtedly sent to you.'),
(3722, 36, 17, 2, 0, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'وَ مَا عَلَیۡنَاۤ  اِلَّا  الۡبَلٰغُ  الۡمُبِیۡنُ ﴿۱۷﴾', 'اور ہمارے ذمے تو صاف صاف پیغام پہنچا دینا ہے اور بس۔', 'اور ہمارا ذمہ یہی ہے پیغام پہنچا دینا کھول کر [۱۶]', '\"And our duty is only to convey plainly (the Message).\"', 'Our obligation is no more than to convey the message clearly.”'),
(3723, 36, 18, 2, 0, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'قَالُوۡۤا اِنَّا تَطَیَّرۡنَا بِکُمۡ ۚ لَئِنۡ لَّمۡ تَنۡتَہُوۡا لَنَرۡجُمَنَّکُمۡ وَ لَیَمَسَّنَّکُمۡ مِّنَّا عَذَابٌ  اَلِیۡمٌ ﴿۱۸﴾', 'وہ بولے کہ ہم تمکو اپنے لئے منحوس سمجھتے ہیں۔ اگر تم باز نہ آؤ گے تو ہم تمہیں سنگسار کر دیں گے اور تمکو ہم سے دکھ دینے والا عذاب پہنچے گا۔', 'بولے ہم نے نامبارک دیکھا تم کو اگر تم باز نہ رہو گے تو ہم تم کو سنگسار کریں گے اور تم کو پہچے گا ہمارے ہاتھ سے عذاب دردناک [۱۷]', 'They (people) said: \"For us, we see an evil omen from you, if you cease not, we will surely stone you, and a painful torment will touch you from us.\"', 'They (the People of the Town) said, “We take you as a bad omen for us. If you do not desist, we will certainly stone you and you will be afflicted by a painful punishment from us.”'),
(3724, 36, 19, 2, 0, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'قَالُوۡا طَآئِرُکُمۡ مَّعَکُمۡ ؕ اَئِنۡ ذُکِّرۡتُمۡ ؕ بَلۡ  اَنۡتُمۡ  قَوۡمٌ  مُّسۡرِفُوۡنَ ﴿۱۹﴾', 'انہوں نے کہا کہ تمہاری نحوست تمہارے ساتھ ہے کیا اس لئے کہ تمکو نصیحت کی گئ۔ نہیں بلکہ تم ایسے لوگ ہو جو حد سے تجاوز کر گئے ہو۔', 'کہنے لگے تمہاری نا مبارکی تمہارے ساتھ ہے کیا اتنی بات پر کہ تم کو سمجھایا کوئی نہیں پرتم لوگ کہ حد پر نہیں رہتے [۱۸]', 'They (Messengers) said: \"Your evil omens be with you! (Do you call it \"evil omen\") because you are admonished? Nay, but you are a people Musrifoon (transgressing all bounds by committing all kinds of great sins, and by disobeying Allah).', 'They said, “Your bad omen is with yourselves. (Do you take it as bad omen) if you are given a good counsel? Rather, you are a people who cross all limits.”'),
(3725, 36, 20, 2, 0, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'وَ جَآءَ مِنۡ اَقۡصَا الۡمَدِیۡنَۃِ  رَجُلٌ یَّسۡعٰی قَالَ یٰقَوۡمِ اتَّبِعُوا الۡمُرۡسَلِیۡنَ ﴿ۙ۲۰﴾', 'اور شہر کے پرلے کنارے سے ایک آدمی دوڑتا ہوا آیا کہنے لگا کہ اے میری قوم پیغمبروں کے پیچھے چلو۔', 'اور آیا شہر کے پرلے سرے سے ایک مرد دوڑتا ہوا [۱۹] بولا اے قوم چلو راہ پر بھیجے ہوؤں کی', 'And there came running from the farthest part of the town, a man, saying: \"O my people! Obey the Messengers;', 'And there came a man rushing from the farthest part of the city. He said, “O my people, follow the messengers.'),
(3726, 36, 21, 2, 0, 22, 'وَ مَنۡ یَّقۡنُتۡ', 'یٰسٓ', 'اتَّبِعُوۡا مَنۡ لَّا یَسۡـَٔلُکُمۡ اَجۡرًا وَّ ہُمۡ مُّہۡتَدُوۡنَ ﴿۲۱﴾', 'ایسوں کے جو تم سے صلہ نہیں مانگتے اور وہ سیدھے رستے پر ہیں۔', 'چلو راہ پر ایسے شخص کی جو تم سے بدلا نہیں چاہتے اور وہ ٹھیک رستہ پر ہیں [۲۰]', '\"Obey those who ask no wages of you (for themselves), and who are rightly guided.', 'Follow those who do not claim any reward from you, and who are on the right path.'),
(3727, 36, 22, 2, 1, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ مَا لِیَ  لَاۤ  اَعۡبُدُ الَّذِیۡ فَطَرَنِیۡ وَ  اِلَیۡہِ تُرۡجَعُوۡنَ ﴿۲۲﴾', 'اور میں کیوں اس ذات کی پرستش نہ کروں جس نے مجھے پیدا کیا اور اسی کی طرف تمکو لوٹ کر جانا ہے۔', 'اور مجھ کو کیا ہوا کہ میں بندگی نہ کروں اسکی جس نے مجھ کو بنایا [۲۱] اور اسی کی طرف سب پھر جاؤ گے [۲۲]', '\"And why should I not worship Him (Allah Alone) Who has created me and to Whom you shall be returned.', 'What excuse do I have if I do not worship the One who has created me and to whom you will be returned?'),
(3728, 36, 23, 2, 1, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'ءَاَتَّخِذُ مِنۡ دُوۡنِہٖۤ  اٰلِہَۃً اِنۡ یُّرِدۡنِ الرَّحۡمٰنُ بِضُرٍّ لَّا تُغۡنِ عَنِّیۡ شَفَاعَتُہُمۡ شَیۡئًا  وَّ لَا  یُنۡقِذُوۡنِ ﴿ۚ۲۳﴾', 'کیا میں اسکو چھوڑ کر اوروں کو معبود بناؤں؟ کہ اگر رحمٰن مجھے نقصان پہنچانا چاہے تو انکی سفارش مجھے کچھ بھی فائدہ نہ دے سکے۔ اور نہ وہ مجھے چھڑا ہی سکیں۔', 'بھلا میں پکڑوں اس کے سوائے اوروں کو پوجنا کہ اگر مجھ پر چاہے رحمٰن تکلیف تو کچھ کام نہ آئے مجھ کو ان کی سفارش اور نہ وہ مجھ کو چھڑائیں', '\"Shall I take besides Him aliha (gods), if the Most Beneficent (Allah) intends me any harm, their intercession will be of no use for me whatsoever, nor can they save me?', 'Shall I adopt those gods besides Him whose intercession, if RaHmān (the All-Merciful Allah) intends to do harm to me, cannot help me in the least, nor can they come to my rescue?'),
(3729, 36, 24, 2, 1, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'اِنِّیۡۤ   اِذًا  لَّفِیۡ  ضَلٰلٍ  مُّبِیۡنٍ ﴿۲۴﴾', 'تب تو میں کھلی گمراہی میں پڑ گیا۔', 'تو تو میں بھٹکتا رہوں صریح [۲۳]', '\"Then verily, I should be in plain error.', 'In that case, I will be in open error indeed.'),
(3730, 36, 25, 2, 1, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'اِنِّیۡۤ   اٰمَنۡتُ بِرَبِّکُمۡ   فَاسۡمَعُوۡنِ ﴿ؕ۲۵﴾', 'میں تو تمہارے پروردگار پر ایمان لایا ہوں سو میری بات سن رکھو۔', 'میں یقین لایا تمہارے رب پر مجھ سے سن لو [۲۴]', 'Verily! I have believed in your Lord, so listen to me!\"', 'Undoubtedly I have believed in your Lord; so listen to me.”'),
(3731, 36, 26, 2, 1, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'قِیۡلَ ادۡخُلِ الۡجَنَّۃَ ؕ قَالَ یٰلَیۡتَ قَوۡمِیۡ یَعۡلَمُوۡنَ ﴿ۙ۲۶﴾', 'حکم ہوا کہ بہشت میں داخل ہو جا۔ بولا کاش! میری قوم کو پتہ چل جائے۔', 'حکم ہوا چلا جا بہشت میں [۲۵] بولا کسی طرح میری قوم معلوم کر لیں', 'It was said (to him when the disbelievers killed him): \"Enter Paradise.\" He said: \"Would that my people knew!', '(Thereafter when his people killed him,) it was said to him, “Enter the Paradise”. He said, “Would that my people knew'),
(3732, 36, 27, 2, 1, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'بِمَا غَفَرَ لِیۡ رَبِّیۡ وَ جَعَلَنِیۡ مِنَ الۡمُکۡرَمِیۡنَ ﴿۲۷﴾', 'کہ میرے رب نے مجھے بخش دیا اور مجھے عزت والوں میں شامل کیا۔', 'کہ کس بنا پر بخشا مجھ کو میرے رب نے اور کیا مجھ کو عزت والوں میں [۲۶]', '\"That my Lord (Allah) has forgiven me, and made me of the honoured ones!\"', 'how my Lord has forgiven me and placed me among the honoured ones!”'),
(3733, 36, 28, 2, 1, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ مَاۤ  اَنۡزَلۡنَا عَلٰی قَوۡمِہٖ مِنۡۢ  بَعۡدِہٖ مِنۡ جُنۡدٍ مِّنَ السَّمَآءِ وَ مَا کُنَّا مُنۡزِلِیۡنَ ﴿۲۸﴾', 'اور ہم نے اسکے بعد اسکی قوم پر کوئی لشکر نہیں اتارا اور نہ ہم اتارنے والے تھے۔', 'اور اتاری نہیں ہم نے اس کی قوم پر اس کے پیچھے کوئ فوج آسمان سے اور ہم فوج  نہیں اتارا کرتے', 'And We sent not against his people after him a host from heaven, nor do We send (such a thing).', 'And We did not send down to his people any army from the heavens after him, nor were We (in need) to send down.'),
(3734, 36, 29, 2, 1, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'اِنۡ کَانَتۡ  اِلَّا صَیۡحَۃً وَّاحِدَۃً  فَاِذَا ہُمۡ خٰمِدُوۡنَ ﴿۲۹﴾', 'وہ تو صرف ایک چنگھاڑ تھی سو وہ اس سے ناگہاں بجھ کر رہ گئے۔', 'بس یہی تھی ایک چنگھاڑ پھر اسی دم سب بجھ گئے [۲۷]', 'It was but one Saihah (shout, etc.) and lo! They (all) were silent (dead-destroyed).', 'It was no more than a single Cry, and in no time they were extinguished.'),
(3735, 36, 30, 2, 1, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'یٰحَسۡرَۃً عَلَی الۡعِبَادِ ۚؑ مَا یَاۡتِیۡہِمۡ مِّنۡ رَّسُوۡلٍ  اِلَّا  کَانُوۡا بِہٖ  یَسۡتَہۡزِءُوۡنَ ﴿۳۰﴾', 'بندوں پر افسوس کہ جب انکے پاس کوئی پیغمبر آتا تو وہ اس سے تمسخر ضرور کرتے۔', 'کیا افسوس ہے بندوں پر کوئی رسول نہیں آیا ان کے پاس جس سے ٹھٹھا نہیں کرتے', 'Alas for mankind! There never came a Messenger to them but they used to mock at him.', 'Alas for the slaves (of Allah)! No messenger came to them, but they have been mocking at him.'),
(3736, 36, 31, 2, 1, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'اَلَمۡ یَرَوۡا کَمۡ  اَہۡلَکۡنَا قَبۡلَہُمۡ مِّنَ الۡقُرُوۡنِ  اَنَّہُمۡ  اِلَیۡہِمۡ لَا یَرۡجِعُوۡنَ ﴿ؕ۳۱﴾', 'کیا انہوں نے نہیں دیکھا کہ ہم نے ان سے پہلے بہت سے لوگوں کو ہلاک کر دیا تھا اب وہ انکی طرف لوٹ کر نہیں آئیں گے۔', 'کیا نہیں دیکھتے کتنی غارت کر چکے ہم ان سے پہلے جماعتیں کہ وہ انکے پاس پھر کر نہیں آئیں گی [۲۸]', 'Do they not see how many of the generations We have destroyed before them? Verily, they will not return to them.', 'Did they not see how many generations We have destroyed before them who will not come back to them?'),
(3737, 36, 32, 2, 1, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ اِنۡ کُلٌّ  لَّمَّا جَمِیۡعٌ لَّدَیۡنَا مُحۡضَرُوۡنَ ﴿٪۳۲﴾', 'اور سب کے سب ہمارے روبرو حاضر کئے جائیں گے۔', 'اور ان سب میں کوئی نہیں جو اکھٹے ہو کر نہ آئیں ہمارے پس پکڑے ہوئے  [۲۹]', 'And surely, all, everyone of them will be brought before Us.', 'All of them are but to be assembled together (and) to be arraigned before Us.'),
(3738, 36, 33, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ اٰیَۃٌ  لَّہُمُ الۡاَرۡضُ الۡمَیۡتَۃُ ۚۖ اَحۡیَیۡنٰہَا وَ اَخۡرَجۡنَا مِنۡہَا حَبًّا فَمِنۡہُ  یَاۡکُلُوۡنَ ﴿۳۳﴾', 'اور ایک نشانی انکے لئے زمین مردہ ہے۔ کہ ہم نے اسکو زندہ کیا اور اس میں سے اناج اگایا۔ پھر یہ اس میں سے کھاتے ہیں۔', 'اور ایک نشانی ہے انکے واسطے زمین مردہ اسکو ہم نے زندہ کر دیا اور نکالا اس میں سے اناج سو اسی میں سے کھاتے ہیں', 'And a sign for them is the dead land. We gave it life, and We brought forth from it grains, so that they eat thereof.', 'And a sign for them is the dead land. We gave it life and brought forth grain from it; so from it they eat.'),
(3739, 36, 34, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ جَعَلۡنَا فِیۡہَا جَنّٰتٍ مِّنۡ نَّخِیۡلٍ وَّ اَعۡنَابٍ وَّ فَجَّرۡنَا فِیۡہَا مِنَ الۡعُیُوۡنِ ﴿ۙ۳۴﴾', 'اور اس میں کھجوروں اور انگوروں کے باغ پیدا کئے اور اس میں چشمے جاری کر دیئے۔', 'اور بنائے ہم نے اس میں باغ کھجور کے اور انگور کے اور بہا دیے اس میں بعضے چشمے', 'And We have made therein gardens of date-palms and grapes, and We have caused springs of water to gush forth therein.', 'And We have placed gardens of date-palms and grapes, and caused springs to gush forth therein,'),
(3740, 36, 35, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'لِیَاۡکُلُوۡا مِنۡ ثَمَرِہٖ ۙ وَ مَا عَمِلَتۡہُ اَیۡدِیۡہِمۡ ؕ اَفَلَا  یَشۡکُرُوۡنَ ﴿۳۵﴾', 'تاکہ یہ ان باغوں کے پھل کھائیں اور انکے ہاتھوں نے تو انکو نہیں بنایا تو پھر کیا یہ شکر نہیں کرتے؟', 'کہ کھائیں اسکے میووں سے [۳۰] اور اس کو بنایا نہیں انکے ہاتھوں نے پھر کیوں شکر نہیں کرتے [۳۱]', 'So that they may eat of the fruit thereof, and their hands made it not. Will they not, then, give thanks?', 'so that they may eat fruits thereof, while it was not made by their hands. Would they not then offer gratitude?'),
(3741, 36, 36, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'سُبۡحٰنَ الَّذِیۡ خَلَقَ الۡاَزۡوَاجَ کُلَّہَا مِمَّا تُنۡۢبِتُ الۡاَرۡضُ وَ مِنۡ اَنۡفُسِہِمۡ وَ  مِمَّا لَا یَعۡلَمُوۡنَ ﴿۳۶﴾', 'وہ  ذات پاک ہے جس نے زمین کی نباتات کے اور خود انکے اور جن چیزوں کی انکو خبر نہیں سب کے جوڑے بنائے۔', 'پاک ذات ہے جس نے بنائے جوڑے سب چیز کے اس قسم سے جو اگتا ہے زمین میں اور خود ان میں سے اور ان چیزوں میں کہ جن کی انکو خبر نہیں [۳۲]', 'Glory be to Him, Who has created all the pairs of that which the earth produces, as well as of their own (human) kind (male and female), and of that which they know not.', 'Pure (from every fault) is the One who has created all the pairs of whatever the earth grows and of the humans themselves and of that which they do not know.'),
(3742, 36, 37, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ اٰیَۃٌ  لَّہُمُ الَّیۡلُ ۚۖ نَسۡلَخُ مِنۡہُ النَّہَارَ  فَاِذَا ہُمۡ  مُّظۡلِمُوۡنَ ﴿ۙ۳۷﴾', 'اور ایک نشانی انکے لئے رات ہے کہ اس پر سے ہم دن کو کھینچ لیتے ہیں تو اسی وقت ان پر اندھیرا چھا جاتا ہے۔', 'اور ایک نشانی ہے انکے واسطے رات کھینچ لیتے ہیں ہم اس پر سے دن کو پھر تبہی یہ رہ جاتے ہیں اندھیرے میں', 'And a sign for them is the night, We withdraw therefrom the day, and behold, they are in darkness.', 'And a sign for them is the night. We strip (the cover of) the day from it, and they are suddenly in darkness.'),
(3743, 36, 38, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ الشَّمۡسُ تَجۡرِیۡ لِمُسۡتَقَرٍّ  لَّہَا ؕ ذٰلِکَ تَقۡدِیۡرُ  الۡعَزِیۡزِ  الۡعَلِیۡمِ ﴿ؕ۳۸﴾', 'اور سورج اپنے مقرر رستے پر چلتا رہتا ہے۔ یہ اس غالب و دانا کا مقرر کیا ہوا اندازہ ہے۔', 'اور سورج چلا جاتا ہے اپنے ٹھہرے ہوئے رستہ پر [۳۳] یہ سادھا ہے اس زبردست باخبر نے [۳۴]', 'And the sun runs on its fixed course for a term (appointed). That is the Decree of the All-Mighty, the All-Knowing.', 'And the sun is quickly proceeding towards its destination. That is the designing of the All-Mighty, the All-Knowing.'),
(3744, 36, 39, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ الۡقَمَرَ قَدَّرۡنٰہُ  مَنَازِلَ حَتّٰی عَادَ کَالۡعُرۡجُوۡنِ  الۡقَدِیۡمِ ﴿۳۹﴾', 'اور چاند کی بھی ہم نے منزلیں مقرر کر دیں یہاں تک کہ گھٹتے گھٹتے کھجور کی پرانی شاخ کی طرح ہو جاتا ہے۔', 'اور چاند کو ہم نے بانٹ دی ہیں منزلیں یہاں تک کہ پھر آ رہا ہے جیسے ٹہنی پرانی [۳۵]', 'And the moon, We have measured for it mansions (to traverse) till it returns like the old dried curved date stalk.', 'And for the moon We have appointed measured phases, until it turned (pale, curved and fine) like an old branch of date palm.'),
(3745, 36, 40, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'لَا الشَّمۡسُ یَنۡۢبَغِیۡ لَہَاۤ اَنۡ تُدۡرِکَ الۡقَمَرَ  وَ لَا الَّیۡلُ سَابِقُ النَّہَارِ ؕ وَ کُلٌّ فِیۡ  فَلَکٍ  یَّسۡبَحُوۡنَ ﴿۴۰﴾', 'نہ تو سورج ہی سے یہ ہو سکتا ہے کہ چاند کو جا پکڑے اور نہ رات ہی دن سے پہلے آ سکتی ہے۔ اور سب اپنے اپنے مدار میں تیر رہے ہیں۔', 'نہ سورج سے ہو کہ پکڑ لے چاند کو اور نہ رات آگے بڑھے دن سے اور ہر کوئی ایک چکر میں پیرتے ہیں [۳۶]', 'It is not for the sun to overtake the moon, nor does the night outstrip the day. They all float, each in an orbit.', 'Neither it is for the sun to overtake the moon, nor can the night outpace the day. Each one is floating in an orbit.'),
(3746, 36, 41, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ اٰیَۃٌ  لَّہُمۡ  اَنَّا حَمَلۡنَا ذُرِّیَّتَہُمۡ  فِی الۡفُلۡکِ  الۡمَشۡحُوۡنِ ﴿ۙ۴۱﴾', 'اور ایک نشانی انکے لئے یہ ہے کہ ہم نے انکی اولاد کو بھری ہوئی کشتی میں سوار کیا۔', 'اور ایک نشانی ہے انکے واسطے کہ ہم نے اٹھا لیا ان کی نسل کو اس بھری ہوئی کشتی میں', 'And an Ayah (sign) for them is that We bore their offspring in the laden ship (of Nooh (Noah)).', 'And it is a sign for them that We boarded their children in the loaded ship,'),
(3747, 36, 42, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ خَلَقۡنَا  لَہُمۡ مِّنۡ مِّثۡلِہٖ مَا یَرۡکَبُوۡنَ ﴿۴۲﴾', 'اور انکے لئے ویسی ہی اور چیزیں پیدا کیں جن پر یہ سوار ہوتے ہیں۔', 'اور بنا دیا ہم نے انکے واسطے کشتی جیسی چیزوں کو جس پر سوار ہوتے ہیں [۳۷]', 'And We have created for them of the like thereunto, so on them they ride.', 'and created for them things similar to it on which they ride.'),
(3748, 36, 43, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ  اِنۡ نَّشَاۡ نُغۡرِقۡہُمۡ  فَلَا صَرِیۡخَ لَہُمۡ وَ لَا ہُمۡ  یُنۡقَذُوۡنَ ﴿ۙ۴۳﴾', 'اور اگر ہم چاہیں تو انکو غرق کر دیں۔ پھر نہ تو ان کا کوئی فریاد رس ہو اور نہ انکو رہائی ملے۔', 'اور اگر ہم چاہیں تو انکو  ڈبا دیں پھر کوئی نہ پہنچےانکی فریاد کو اور نہ وہ چھڑائے جائیں', 'And if We will, We shall drown them, and there will be no shout (or helper) for them (to hear their cry for help) nor will they be saved.', 'And if We so will, We can drown them; then no one will respond to their cry, nor will they be rescued,'),
(3749, 36, 44, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'اِلَّا رَحۡمَۃً  مِّنَّا وَ مَتَاعًا اِلٰی حِیۡنٍ ﴿۴۴﴾', 'مگر یہ ہماری رحمت اور ایک مدت تک کے فائدے ہیں۔', 'مگر ہم اپنی مہربانی سے اور انکا کام چلانے کو ایک وقت تک [۳۸]', 'Unless it be a mercy from Us, and as an enjoyment for a while.', 'unless there be mercy from Us, and (unless) We let them enjoy for a while.'),
(3750, 36, 45, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ اِذَا قِیۡلَ لَہُمُ اتَّقُوۡا مَا بَیۡنَ اَیۡدِیۡکُمۡ وَ مَا خَلۡفَکُمۡ لَعَلَّکُمۡ تُرۡحَمُوۡنَ ﴿۴۵﴾', 'اور جب ان سے کہا جاتا ہے کہ جو تمہارے آگے اور جو تمہارے پیچھے ہے اس سے ڈرو تاکہ تم پر رحم کیا جائے۔', 'اور جب کہیے ان کو بچو اس سے جو تمہارے سامنے آتا ہے اور جو پیچھے چھوڑتے ہو شاید تم پر رحم ہو', 'And when it is said to them: \"Beware of that which is before you (worldly torments), and that which is behind you (torments in the Hereafter), in order that you may receive Mercy (i.e. if you believe in Allahs Religion Islamic Monotheism, and avoid polytheism, and obey Allah with righteous deeds).', 'And (they pay no heed) when it is said to them, “Save yourselves from that (punishment) which is before you (in this world) and that which will come after you (die), so that you may receive mercy”.'),
(3751, 36, 46, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ مَا تَاۡتِیۡہِمۡ مِّنۡ اٰیَۃٍ  مِّنۡ اٰیٰتِ رَبِّہِمۡ اِلَّا  کَانُوۡا عَنۡہَا مُعۡرِضِیۡنَ ﴿۴۶﴾', 'اور انکے پاس انکے پروردگار کی طرف سے کوئی نشانی نہیں آتی مگر اس سے منہ پھیر لیتے ہیں۔', 'اور کوئی حکم نہیں پہنچتا انکو اپنے رب کے حکموں سے جس کو وہ ٹلاتے نہ ہوں [۳۹]', 'And never came an Ayah from among the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of their Lord to them, but they did turn away from it.', 'There comes to them no sign from the signs of your Lord, but they turn averse to it.'),
(3752, 36, 47, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ اِذَا قِیۡلَ لَہُمۡ  اَنۡفِقُوۡا  مِمَّا رَزَقَکُمُ  اللّٰہُ ۙ قَالَ  الَّذِیۡنَ کَفَرُوۡا لِلَّذِیۡنَ اٰمَنُوۡۤا اَنُطۡعِمُ مَنۡ لَّوۡ  یَشَآءُ  اللّٰہُ   اَطۡعَمَہٗۤ ٭ۖ اِنۡ اَنۡتُمۡ   اِلَّا  فِیۡ ضَلٰلٍ مُّبِیۡنٍ ﴿۴۷﴾', 'اور جب ان سے کہا جاتا ہے کہ جو رزق اللہ نے تمکو دیا ہے اس میں سے خرچ کرو۔ تو کافر مومنوں کے متعلق کہتے ہیں کہ بھلا ہم ان لوگوں کو کھانا کھلائیں جنکو اگر اللہ چاہتا تو خود کھلا دیتا تم تو کھلی گمراہی میں ہو۔', 'اور جب کہیے ان کو خرچ کرو کچھ اللہ کا دیا کہتے ہیں منکر ایمان والوں کو ہم کیوں کھلائیں ایسے کو کہ اللہ چاہتا تو اس کو کھلا دیتا [۴۰] تم لوگ تو بالکل بہک رہے ہو صریح [۴۱]', 'And when it is said to them: \"Spend of that with which Allah has provided you,\" those who disbelieve say to those who believe: \"Shall we feed those whom, if Allah willed, He (Himself) would have fed? You are only in a plain error.\"', 'And when it is said to them, “Spend (to the needy) from the provision Allah has given to you”, the disbelievers say to the believers, “Shall we feed those whom Allah could have fed, if Allah so willed? You are but in open error.”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(3753, 36, 48, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ یَقُوۡلُوۡنَ مَتٰی ہٰذَا الۡوَعۡدُ اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ ﴿۴۸﴾', 'اور کہتے ہیں اگر تم سچ کہتے ہو تو بتاؤ یہ وعدہ کب پورا ہو گا؟', 'اور کہتے ہیں کب ہو گا یہ وعدہ اگر تم سچے ہو [۴۲]', 'And they say: \"When will this promise (i.e. Resurrection) be fulfilled, if you are truthful?\"', 'And they say, “When will this promise come true, if you are truthful?”'),
(3754, 36, 49, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'مَا یَنۡظُرُوۡنَ  اِلَّا صَیۡحَۃً وَّاحِدَۃً تَاۡخُذُہُمۡ  وَ ہُمۡ  یَخِصِّمُوۡنَ ﴿۴۹﴾', 'یہ تو ایک چنگھاڑ ہی کے منتظر ہیں جو انکو اس حال میں کہ باہم جھگڑ رہے ہوں گے آ پکڑے گی۔', 'یہ تو راہ دیکھتے ہیں ایک چنگھاڑ کی جو ان کو آ پکڑے گی جب آپس میں جھگڑ رہے ہوں گے', 'They await only but a single Saihah (shout, etc.), which will seize them while they are disputing!', 'They are looking for nothing but for a single Cry that will seize them when they will be quarrelling.'),
(3755, 36, 50, 3, 2, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'فَلَا یَسۡتَطِیۡعُوۡنَ تَوۡصِیَۃً  وَّ لَاۤ  اِلٰۤی اَہۡلِہِمۡ   یَرۡجِعُوۡنَ ﴿٪۵۰﴾', 'پھر نہ تو یہ وصیت ہی کر سکیں گے اور نہ اپنے گھر والوں میں واپس جا سکیں گے۔', 'پھر نہ کر سکیں گے کہ کچھ کہہ ہی مریں  اور نہ اپنے گھر کو پھر کر جا سکیں گے [۴۳]', 'Then they will not be able to make bequest, nor they will return to their family.', 'So they will not be able to make a bequest, nor will they return to their household.'),
(3756, 36, 51, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ نُفِخَ فِی الصُّوۡرِ فَاِذَا ہُمۡ مِّنَ الۡاَجۡدَاثِ  اِلٰی  رَبِّہِمۡ  یَنۡسِلُوۡنَ ﴿۵۱﴾', 'اور جس وقت صور پھونکا جائے گا یہ قبروں سے نکل کر اپنے پروردگار کی طرف دوڑ پڑیں گے۔', 'اور پھونکی جائے صور پھر تبہی وہ قبروں سے اپنے رب کی پھیل پڑیں گے [۴۴]', 'And the Trumpet will be blown (i.e. the second blowing) and behold! From the graves they will come out quickly to their Lord.', 'And the Horn will be blown, and suddenly they will be rushing from their graves towards their Lord.'),
(3757, 36, 52, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'قَالُوۡا یٰوَیۡلَنَا مَنۡۢ بَعَثَنَا مِنۡ مَّرۡقَدِنَا ٜۘؐ ہٰذَا  مَا  وَعَدَ  الرَّحۡمٰنُ وَ صَدَقَ الۡمُرۡسَلُوۡنَ ﴿۵۲﴾', 'کہیں گے ہائے بربادی ہمیں ہماری خواب گاہوں سے کس نے جگا اٹھایا؟ یہ وہی تو ہے جس کا رحمٰن نے وعدہ کیا تھا اور پیغمبروں نے سچ کہا تھا۔', 'کہیں گے اے خرابی ہماری کس نے اٹھا دیا ہم کو ہماری نیند کی جگہ سے [۴۵] یہ وہ ہے جو وعدہ کیا تھا رحمٰن نے اور سچ کہا تھا پیغمبروں نے [۴۶]', 'They will say: \"Woe to us! Who has raised us up from our place of sleep.\" (It will be said to them): \"This is what the Most Beneficent (Allah) had promised, and the Messengers spoke truth!\"', 'They will say, “Woe to us! Who has raised us from our sleeping place? “This is what RaHmān (the All-Merciful Allah) had promised, and the messengers had told the truth.'),
(3758, 36, 53, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'اِنۡ کَانَتۡ  اِلَّا صَیۡحَۃً وَّاحِدَۃً  فَاِذَا ہُمۡ جَمِیۡعٌ  لَّدَیۡنَا  مُحۡضَرُوۡنَ ﴿۵۳﴾', 'وہ تو صرف ایک زور کی آواز ہو گی کہ سب کے سب ہمارے روبرو آ حاضر ہوں گے۔', 'بس ایک چنگھاڑ ہو گی پھر اسی دم وہ سارے ہمارے پاس پکڑے چلے آئیں گے [۴۷]', 'It will be but a single Saihah (shout, etc.), so behold! They will all be brought up before Us!', 'It will be no more than a single Cry, and in no time they will all be arraigned before Us.'),
(3759, 36, 54, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'فَالۡیَوۡمَ لَا تُظۡلَمُ نَفۡسٌ شَیۡئًا وَّ لَا تُجۡزَوۡنَ  اِلَّا مَا کُنۡتُمۡ تَعۡمَلُوۡنَ ﴿۵۴﴾', 'پھر اس روز کسی شخص پر کچھ بھی ظلم نہیں کیا جائے گا اور تمکو بدلہ ویسا ہی ملے گا جیسے تم کام کرتے تھے۔', 'پھر آج کے دن ظلم نہ ہوگا کسی جی پر ذرا اور  وہی بدلہ پاؤ گے جو کرتے تھے [۴۸]', 'This Day (Day of Resurrection), none will be wronged in anything, nor will you be requited anything except that which you used to do.', 'Then, nobody will be subjected to injustice in the least, and you will not be recompensed but for what you used to do.'),
(3760, 36, 55, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'اِنَّ  اَصۡحٰبَ الۡجَنَّۃِ  الۡیَوۡمَ فِیۡ  شُغُلٍ فٰکِہُوۡنَ ﴿ۚ۵۵﴾', 'اہل جنت اس روز عیش و نشاط کے مشغلے میں خوش ہوں گے۔', 'تحقیق بہشت کے لوگ آج ایک مشغلہ میں ہیں باتیں کرتے', 'Verily, the dwellers of the Paradise, that Day, will be busy in joyful things.', 'The people of the Paradise are engaged today in (their) activities, happily enjoying (them).'),
(3761, 36, 56, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'ہُمۡ وَ اَزۡوَاجُہُمۡ فِیۡ ظِلٰلٍ عَلَی الۡاَرَآئِکِ مُتَّکِـُٔوۡنَ ﴿۵۶﴾', 'وہ بھی اور انکی بیویاں بھی سایوں میں تختوں پر تکئے لگائے بیٹھے ہوں گے۔', 'وہ اور ان کی عورتیں سایوں میں تختوں پر بیٹھے ہیں تکیہ لگائے', 'They and their wives will be in pleasant shade, reclining on thrones.', 'They and their spouses are in pleasant shades, reclining on couches.'),
(3762, 36, 57, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'لَہُمۡ فِیۡہَا فَاکِہَۃٌ  وَّ لَہُمۡ مَّا یَدَّعُوۡنَ ﴿ۚۖ۵۷﴾', 'وہاں انکے لئے میوے ہوں گے اور جو وہ منگوائیں گے انکو ملے گا۔', 'انکے لئے وہاں ہے میوہ اور انکے لئے ہے جو کچھ مانگیں [۴۹]', 'They will have therein fruits (of all kinds) and all that they ask for.', 'For them there are fruits, and for them there is whatever they ask for.'),
(3763, 36, 58, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'سَلٰمٌ ۟ قَوۡلًا  مِّنۡ  رَّبٍّ  رَّحِیۡمٍ ﴿۵۸﴾', 'انکو پروردگار مہربان کی طرف سے سلام کہا جائے گا۔', 'سلام بولنا ہے رب مہربان سے [۵۰]', '(It will be said to them): Salamun (peace be on you), a Word from the Lord (Allah), Most Merciful.', '“Salām ”(Peace upon you) is the word (they receive) from Merciful Lord.'),
(3764, 36, 59, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ امۡتَازُوا الۡیَوۡمَ اَیُّہَا الۡمُجۡرِمُوۡنَ ﴿۵۹﴾', 'اور وہ فرمائے گا کہ گنہگارو تم آج الگ ہو جاؤ۔', 'اور تم الگ ہو جاؤ آج  اے گناہگارو [۵۱]', '(It will be said): \"And O you Al-Mujrimoon (criminals, polytheists, sinners, disbelievers in the Islamic Monotheism, wicked evil ones, etc.)! Get you apart this Day (from the believers).', 'And (it will be said to the infidels,) “Get apart (from the believers) today O the guilty ones.'),
(3765, 36, 60, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'اَلَمۡ  اَعۡہَدۡ  اِلَیۡکُمۡ یٰبَنِیۡۤ  اٰدَمَ اَنۡ  لَّا تَعۡبُدُوا الشَّیۡطٰنَ ۚ اِنَّہٗ  لَکُمۡ  عَدُوٌّ مُّبِیۡنٌ ﴿ۙ۶۰﴾', 'اے آدم کی اولاد کیا میں نے تم کو کہہ نہیں دیا تھا کہ شیطان کو نہ پوجنا وہ تمہارا کھلا دشمن ہے۔', 'میں نے  نہ کہہ رکھا تھا تم کو اے آدم کی اولاد کہ نہ پوجیو شیطان کو  وہ کھلا دشمن ہے تمہارا', 'Did I not ordain for you, O Children of Adam, that you should not worship Shaitan (Satan). Verily, he is a plain enemy to you.', 'Did I not direct you, O children of ’Ādam (Adam), that you must not worship the Satan, (because) he is an open enemy for you,'),
(3766, 36, 61, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَّ  اَنِ اعۡبُدُوۡنِیۡ ؕؔ ہٰذَا  صِرَاطٌ مُّسۡتَقِیۡمٌ ﴿۶۱﴾', 'اور یہ کہ میری ہی عبادت کرنا یہی سیدھا رستہ ہے۔', 'اور یہ کہ پوجو مجھ کو یہ راہ ہے سیدھی [۵۲]', 'And that you should worship Me (Alone Islamic Monotheism, and set up not rivals, associate-gods with Me). That is a Straight Path.', 'and that you must worship Me, (because) this is the straight path?'),
(3767, 36, 62, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ لَقَدۡ اَضَلَّ  مِنۡکُمۡ  جِبِلًّا کَثِیۡرًا ؕ اَفَلَمۡ  تَکُوۡنُوۡا تَعۡقِلُوۡنَ ﴿۶۲﴾', 'اور اس نے تم میں سے بہت سی خلقت کو گمراہ کر دیا تھا تو کیا تم سمجھتے نہیں تھے؟', 'اور وہ  بہکا لے گیا تم میں سے بہت خلقت کو پھر کیا تم کو سمجھ نہ تھی', 'And indeed he (Satan) did lead astray a great multitude of you. Did you not, then, understand?', 'He had misguided lot many people from among you. So, did you not have sense?'),
(3768, 36, 63, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'ہٰذِہٖ  جَہَنَّمُ  الَّتِیۡ  کُنۡتُمۡ  تُوۡعَدُوۡنَ ﴿۶۳﴾', 'یہی وہ جہنم ہے جسکی تمہیں دھمکی دی جاتی تھی۔', 'یہ دوزخ ہے جس کا تم کو وعدہ تھا', 'This is Hell which you were promised!', '(Now) this is the Jahannam of which you were consistently warned.'),
(3769, 36, 64, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'اِصۡلَوۡہَا الۡیَوۡمَ بِمَا کُنۡتُمۡ تَکۡفُرُوۡنَ ﴿۶۴﴾', 'جو تم کفر کرتے رہے ہو اسکے بدلے آج اس میں داخل ہو جاؤ۔', 'جا پڑو اس میں آج کے دن بدلا اپنے کفر کا [۵۳]', 'Burn therein this Day, for that you used to disbelieve.', 'Enter it today, because you have been persistently denying (the truth).”'),
(3770, 36, 65, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'اَلۡیَوۡمَ نَخۡتِمُ عَلٰۤی اَفۡوَاہِہِمۡ وَ تُکَلِّمُنَاۤ اَیۡدِیۡہِمۡ وَ تَشۡہَدُ اَرۡجُلُہُمۡ بِمَا کَانُوۡا یَکۡسِبُوۡنَ  ﴿۶۵﴾', 'آج ہم انکے مونہوں پر مہر لگا دیں گے اور جو کچھ یہ کرتے رہے تھے انکے ہاتھ ہم سے بیان کر دیں گے اور انکے پاؤں اسکی گواہی دیں گے۔', 'آج ہم مہر لگا دیں گے ان کے منہ پر اور بولیں گے ہم سے ان کے ہاتھ اور بتلائیں گے ان کے پاؤں جو کچھ وہ کماتے تھے [۵۴]', 'This Day, We shall seal up their mouths, and their hands will speak to Us, and their legs will bear witness to what they used to earn. (It is said that ones left thigh will be the first to bear the witness). (Tafsir At-Tabaree, Vol. 22, Page 24)', 'Today We will set a seal on their mouths, and their hands will speak to Us, and their legs will bear witness about what they used to do.'),
(3771, 36, 66, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ لَوۡ نَشَآءُ  لَطَمَسۡنَا عَلٰۤی  اَعۡیُنِہِمۡ فَاسۡتَبَقُوا الصِّرَاطَ فَاَنّٰی یُبۡصِرُوۡنَ ﴿۶۶﴾', 'اور اگر ہم چاہیں تو انکی آنکھوں کو مٹا کر اندھا کر دیں پھر یہ رستے کو دوڑیں تو کہاں سے دیکھ سکیں گے۔', 'اور اگر ہم چاہیں مٹا دیں ان کی آنکھیں پھر دوڑیں رستہ پانے کو پھر کہاں سے سوجھے', 'And if it had been Our Will, We would surely have wiped out (blinded) their eyes, so that they would struggle for the Path, how then would they see?', 'If We so will, We would wipe out their eyes (right here in this world), and they would be racing towards the way, but how would they see?'),
(3772, 36, 67, 4, 3, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ لَوۡ نَشَآءُ لَمَسَخۡنٰہُمۡ عَلٰی مَکَانَتِہِمۡ فَمَا اسۡتَطَاعُوۡا مُضِیًّا وَّ لَا یَرۡجِعُوۡنَ ﴿٪۶۷﴾', 'اور اگر ہم چاہیں تو انکی جگہ پر انکی صورتیں بدل دیں پھر وہ وہاں سے نہ آگے جا سکیں اور نہ پیچھے لوٹ سکیں۔', 'اور اگر ہم چاہیں صورت مسخ کر دیں انکی جہاں کی تہاں پھر نہ آگے چل سکیں اور نہ وہ الٹے پھر سکیں [۵۵]', 'And if it had been Our Will, We could have transformed them (into animals or lifeless objects) in their places. Then they should have been unable to go forward (move about) nor they could have turned back. (As it happened with the Jews see Verse 7:166 The Quran).', 'And If We so will, We would disfigure them at their places, and they would not be able to move, nor would they return.'),
(3773, 36, 68, 5, 4, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ مَنۡ نُّعَمِّرۡہُ  نُنَکِّسۡہُ  فِی الۡخَلۡقِ ؕ اَفَلَا یَعۡقِلُوۡنَ ﴿۶۸﴾', 'اور جسکو ہم بڑی عمر دیتے ہیں تو اسے تخلیق میں اوندھا دیتے ہیں یعنی اسے بچپن کی کمزوری والی  حالت کی طرف لوٹا دیتے ہیں تو کیا یہ سمجھتے نہیں۔', 'اور جس کو ہم بوڑھا کریں اوندھا کریں اس کی پیدائش میں پھر کیا ان کو سمجھ نہیں [۵۶]', 'And he whom We grant long life, We reverse him in creation (weakness after strength). Will they not then understand?', 'And whomsoever We give long life, we reverse him in creation. Then, do they have no sense?'),
(3774, 36, 69, 5, 4, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ مَا عَلَّمۡنٰہُ الشِّعۡرَ وَ مَا یَنۡۢبَغِیۡ لَہٗ ؕ اِنۡ ہُوَ   اِلَّا  ذِکۡرٌ   وَّ  قُرۡاٰنٌ  مُّبِیۡنٌ ﴿ۙ۶۹﴾', 'اور ہم نے ان کو یعنی اپنے پیغمبر ﷺ کو شعرگوئی نہیں سکھائی اور نہ وہ انکو شایاں ہی ہے۔ یہ تو محض نصیحت ہے اور صاف صاف قرآن ہے۔', 'اور ہم نے نہیں سکھایا اسکو شعر کہنا اور یہ اس کے لائق نہیں یہ تو خالص نصیحت ہے اورقرآن ہے صاف [۵۷]', 'And We have not taught him (Muhammad SAW) poetry, nor is it meet for him. This is only a Reminder and a plain Quran.', 'We did not teach him (the Holy Prophet) poetry, and it is not proper for him. It is nothing (of that sort,) but (it is) an advice and a readable book that explains (the Truth),'),
(3775, 36, 70, 5, 4, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'لِّیُنۡذِرَ مَنۡ کَانَ حَیًّا وَّ یَحِقَّ الۡقَوۡلُ عَلَی الۡکٰفِرِیۡنَ ﴿۷۰﴾', 'تاکہ اس شخص کو جو زندہ ہو خبردار کرے اور کافروں پر بات پوری ہو جائے۔', 'تاکہ ڈر سنائے اس کو جس میں جان ہو اور ثابت ہو الزام منکروں پر [۵۸]', 'That he or it (Muhammad SAW or the Quran) may give warning to him who is living (a healthy minded the believer), and that Word (charge) may be justified against the disbelievers (dead, as they reject the warnings).', 'so that it may warn him who is alive (to listen to the truth), and so that the word may prove true against the disbelievers.'),
(3776, 36, 71, 5, 4, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'اَوَ لَمۡ یَرَوۡا اَنَّا خَلَقۡنَا لَہُمۡ مِّمَّا عَمِلَتۡ اَیۡدِیۡنَاۤ  اَنۡعَامًا فَہُمۡ  لَہَا مٰلِکُوۡنَ ﴿۷۱﴾', 'کیا انہوں نے نہیں دیکھا کہ جو چیزیں ہم نے اپنے ہاتھوں سے بنائیں ان میں سے ہم نے انکے لئے مویشی پیدا کر دیئے اور یہ انکے مالک ہیں۔', 'کیا اور نہیں دیکھتے وہ کہ ہم نے بنا دیے انکے واسطے اپنے ہاتھوں کی بنائی چیزوں سے چوپائے پھر وہ انکے مالک ہیں [۵۹]', 'Do they not see that We have created for them of what Our Hands have created, the cattle, so that they are their owners.', 'Did they not see that We have created for them cattle, among things made (directly) by Our hands, and then they become their owners?'),
(3777, 36, 72, 5, 4, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ ذَلَّلۡنٰہَا لَہُمۡ  فَمِنۡہَا رَکُوۡبُہُمۡ  وَ  مِنۡہَا یَاۡکُلُوۡنَ ﴿۷۲﴾', 'اور انکو انکے قابو میں کر دیا تو کوئی تو ان میں سے انکی سواری ہے اور کسی کو یہ کھاتے ہیں۔', 'اور عاجز کر دیا انکو انکے آگے پھر ان میں کوئی ہے انکی سواری اور کسی کو کھاتے ہیں', 'And We have subdued them unto them so that some of them they have for riding and some they eat.', 'And We have brought them under their control, so as some of them are their means of transport, and some of them they eat.'),
(3778, 36, 73, 5, 4, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ لَہُمۡ  فِیۡہَا مَنَافِعُ  وَ  مَشَارِبُ ؕ اَفَلَا یَشۡکُرُوۡنَ ﴿۷۳﴾', 'اور ان میں انکے لئے اور فائدے اور پینے کی چیزیں ہیں۔ تو کیا یہ شکر نہیں کرتے؟', 'اور انکے واسطے چارپایوں میں فائدے ہیں اور پینے کے گھاٹ پھر کیوں شکر نہیں کرتے [۶۰]', 'And they have (other) benefits from them (besides), and they get (milk) to drink, will they not then be grateful?', 'And for them there are (other) benefits in them and things to drink. So, would they not be grateful?'),
(3779, 36, 74, 5, 4, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ اتَّخَذُوۡا مِنۡ دُوۡنِ اللّٰہِ اٰلِہَۃً  لَّعَلَّہُمۡ یُنۡصَرُوۡنَ ﴿ؕ۷۴﴾', 'اور انہوں نے اللہ کے سوا اور معبود بنا لئے ہیں کہ شاید ان سے انکو مدد پہنچے۔', 'اور پکڑتے ہیں اللہ کے سوائے اور حاکم کہ شاید ان کی مدد کریں', 'And they have taken besides Allah aliha (gods), hoping that they might be helped (by those so called gods).', 'They have adopted gods other than Allah, so that they may be helped (by them).'),
(3780, 36, 75, 5, 4, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'لَا یَسۡتَطِیۡعُوۡنَ نَصۡرَہُمۡ ۙ وَ ہُمۡ   لَہُمۡ  جُنۡدٌ  مُّحۡضَرُوۡنَ ﴿۷۵﴾', 'مگر وہ انکی مدد کی ہرگز طاقت نہیں رکھتے۔ اور وہ انکی فوج بنا کر حاضر کئے جائیں گے۔', 'نہ کر سکیں گے ان کی مدد اور یہ انکی فوج ہو کر پکڑ آئیں گے [۶۱]', 'They cannot help them, but they will be brought forward as a troop against those who worshipped them (at the time of Reckoning).', 'They cannot help them, rather they (the disbelievers themselves) are (like) an army brought forth for (protecting) them (the so-called co-gods)'),
(3781, 36, 76, 5, 4, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'فَلَا یَحۡزُنۡکَ قَوۡلُہُمۡ ۘ اِنَّا نَعۡلَمُ مَا یُسِرُّوۡنَ  وَ مَا  یُعۡلِنُوۡنَ ﴿۷۶﴾', 'تو انکی باتیں تمہیں غمناک نہ کر دیں۔ یہ جو کچھ چھپاتے اور جو کچھ ظاہر کرتے ہیں ہمیں سب معلوم ہے۔', 'اب تو غمگین مت ہو انکی بات سے ہم جانتے ہیں جو وہ چھپاتے ہیں اور جو ظاہر کرتے ہیں [۶۲]', 'So let not their speech, then, grieve you (O Muhammad SAW). Verily, We know what they conceal and what they reveal.', 'So, their remarks must not grieve you. Surely We know what they conceal and what they disclose.'),
(3782, 36, 77, 5, 4, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'اَوَ لَمۡ یَرَ الۡاِنۡسَانُ  اَنَّا خَلَقۡنٰہُ مِنۡ نُّطۡفَۃٍ  فَاِذَا ہُوَ  خَصِیۡمٌ  مُّبِیۡنٌ ﴿۷۷﴾', 'کیا انسان نے نہیں دیکھا کہ ہم نے اسکو نطفے سے پیدا کیا پھر وہ تڑاق پڑاق جھگڑنے لگا۔', 'کیا دیکھتا نہیں انسان کہ ہم نے اس کو بنایا ایک قطرہ سے پھر تبہی وہ ہو گیا جھگڑنے بولنے والا [۶۳]', 'Does not man see that We have created him from Nutfah (mixed male and female discharge semen drops). Yet behold! He (stands forth) as an open opponent.', 'Did man not see that We have created him from a drop of semen? Then suddenly he stood as an open adversary (to Us).'),
(3783, 36, 78, 5, 4, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'وَ ضَرَبَ لَنَا مَثَلًا وَّ نَسِیَ خَلۡقَہٗ ؕ قَالَ مَنۡ  یُّحۡیِ  الۡعِظَامَ  وَ  ہِیَ  رَمِیۡمٌ ﴿۷۸﴾', 'اور ہمارے بارے میں مثالیں بیان کرنے لگا اور اپنی پیدائش کو بھول گیا۔ کہنے لگا کہ جب ہڈیاں بوسیدہ ہو جائیں گی تو انکو کون زندہ کرے گا؟', 'اور بٹھلاتا ہے ہم پر ایک مثل اور بھول گیا اپنی پیدائش کہنے لگا کون زندہ کرے گا ہڈیوں کو جب کھوکھری ہو گئیں [۶۴]', 'And he puts forth for Us a parable, and forgets his own creation. He says: \"Who will give life to these bones when they have rotted away and became dust?\"', 'He has set up an argument about Us and forgot his creation. He said, “Who will give life to the bones when they are decayed?”'),
(3784, 36, 79, 5, 4, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'قُلۡ یُحۡیِیۡہَا الَّذِیۡۤ  اَنۡشَاَہَاۤ  اَوَّلَ  مَرَّۃٍ ؕ وَ  ہُوَ  بِکُلِّ  خَلۡقٍ عَلِیۡمُۨ  ﴿ۙ۷۹﴾', 'کہدو کہ انکو وہ زندہ کرے گا جس نے انکو پہلی بار پیدا کیا تھا۔ اور وہ ہر طرح کی تخلیق کو جانتا ہے۔', 'تو کہہ ان کو زندہ کرے گا جس نے بنایا انکو پہلی بار اور وہ سب بنانا جانتا ہے [۶۵]', 'Say: (O Muhammad SAW) \"He will give life to them Who created them for the first time! And He is the All-Knower of every creation!\"', 'Say, “These will be revived by the same One who had created them for the first time, and who is fully aware of every creation,'),
(3785, 36, 80, 5, 4, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'الَّذِیۡ جَعَلَ لَکُمۡ مِّنَ الشَّجَرِ الۡاَخۡضَرِ نَارًا  فَاِذَاۤ  اَنۡتُمۡ مِّنۡہُ  تُوۡقِدُوۡنَ ﴿۸۰﴾', 'وہی جس نے تمہارے لئے سبز درخت سے آگ پیدا کی پھر تم اسکی ٹہنیوں کو رگڑ کر ان سے آگ نکالتے ہو۔', 'جس نے بنا دی تم کو سبز درخت سے آگ پھر اب تم اس سے سلگاتے ہو [۶۶]', 'He, Who produces for you fire out of the green tree, when behold! You kindle therewith.', '- the One who created for you fire from the green tree, and in no time you kindle from it.”'),
(3786, 36, 81, 5, 4, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'اَوَ لَیۡسَ الَّذِیۡ خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ بِقٰدِرٍ عَلٰۤی  اَنۡ  یَّخۡلُقَ مِثۡلَہُمۡ ؕ؃ بَلٰی ٭ وَ ہُوَ  الۡخَلّٰقُ  الۡعَلِیۡمُ ﴿۸۱﴾', 'بھلا جس نے آسمانوں اور زمین کو پیدا کیا کیا وہ اس بات پر قادر نہیں کہ انکو پھر ویسے ہی پیدا کر دے۔ کیوں نہیں۔ اور وہ تو سب کچھ پیدا کرنے والا کامل علم والا ہے۔', 'کیا جس نے بنائے آسمان اور زمین نہیں بنا سکتا ان جیسے کیوں نہیں اور وہی ہے اصل بنانے والا سب کچھ جاننے والا [۶۷]', 'Is not He, Who created the heavens and the earth Able to create the like of them? Yes, indeed! He is the All-Knowing Supreme Creator.', 'Is it that the One who has created the heavens and the earth has no power to create ones like them? Why not? He is the Supreme Creator, the All-Knowing.'),
(3787, 36, 82, 5, 4, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'اِنَّمَاۤ  اَمۡرُہٗۤ   اِذَاۤ   اَرَادَ  شَیۡئًا اَنۡ یَّقُوۡلَ  لَہٗ کُنۡ  فَیَکُوۡنُ ﴿۸۲﴾', 'اسکی شان یہ ہے کہ جب وہ کسی چیز کا ارادہ کرتا ہے تو اس سے فرما دیتا ہے کہ ہو جا تو وہ ہو جاتی ہے۔', 'اسکا حکم یہی ہے کہ جب کرنا چاہے کسی چیز کو تو کہے اس کو ہو وہ اسی وقت ہو جائے [۶۸]', 'Verily, His Command, when He intends a thing, is only that He says to it, \"Be!\" and it is!', 'His practice, when He intends to do something, is no more than He says, “Be”, and it comes to be.'),
(3788, 36, 83, 5, 4, 23, 'وَ مَا لِیَ ', 'یٰسٓ', 'فَسُبۡحٰنَ الَّذِیۡ بِیَدِہٖ مَلَکُوۡتُ کُلِّ شَیۡءٍ وَّ اِلَیۡہِ  تُرۡجَعُوۡنَ ﴿٪۸۳﴾', 'وہ ذات پاک ہے جسکے ہاتھ میں ہر چیز کی حکومت ہے اور اسی کی طرف تمکو لوٹ کر جانا ہے۔', 'سو پاک ہے وہ ذات جس کے ہاتھ ہے حکومت ہر چیز کی اور اسی کی طرف پھر کر چلے جاؤ گے [۶۹]', 'So Glorified is He and Exalted above all that they associate with Him, and in Whose Hands is the dominion of all things, and to Him you shall be returned.', 'So, pure (from every fault) is the One in whose hand is the dominion of all things. And towards Him you are to be returned.'),
(3789, 37, 1, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ الصّٰٓفّٰتِ  صَفًّا ۙ﴿۱﴾', 'قسم ہے سلیقے سے صف باندھنے والوں کی۔', 'قسم ہے صف باندھنے والوں کی قطار ہو کر [۱]', 'By those (angels) ranged in ranks (or rows).', '(I swear) by those who stand in rows,'),
(3790, 37, 2, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَالزّٰجِرٰتِ  زَجۡرًا ۙ﴿۲﴾', 'پھر ڈانٹنے والوں کی جھڑک کر۔', 'پھر ڈانٹنے والوں کی جھڑک کر [۲]', 'By those (angels) who drive the clouds in a good way.', 'then by those who prevent firmly,'),
(3791, 37, 3, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَالتّٰلِیٰتِ  ذِکۡرًا  ۙ﴿۳﴾', 'پھر ذکر یعنی قرآن پڑھنے والوں کی غور کر کے۔', 'پھر پڑھنے والوں کی  یاد کر کر [۳]', 'By those (angels) who bring the Book and the Quran from Allah to mankind (Tafsir Ibn Katheer).', 'then by those who recite the dhikr,'),
(3792, 37, 4, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّ   اِلٰـہَکُمۡ   لَوَاحِدٌ ﴿ؕ۴﴾', 'کہ تمہارا معبود ایک ہی ہے۔', 'بیشک حاکم تم سب کا ایک ہے [۴]', 'Verily your Ilah (God) is indeed One (i.e. Allah);', 'surely your God is but One,'),
(3793, 37, 5, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'رَبُّ السَّمٰوٰتِ وَ  الۡاَرۡضِ وَ مَا بَیۡنَہُمَا  وَ  رَبُّ  الۡمَشَارِقِ ؕ﴿۵﴾', 'جو آسمانوں اور زمین اور جو چیزیں ان میں ہیں سب کا مالک ہے اور سورج کے طلوع ہونے کے مقامات کا بھی مالک ہے۔', 'رب آسمانوں کا اور زمین کا اور جو کچھ انکے بیچ میں ہے اور رب مشرقوں کا [۵]', 'Lord of the heavens and of the earth, and all that is between them, and Lord of every point of the suns risings. (None has the right to be worshipped but Allah).', 'the Lord of the heavens and the earth and what is between them, and Lord of the points of sunrise.'),
(3794, 37, 6, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّا زَیَّنَّا السَّمَآءَ  الدُّنۡیَا بِزِیۡنَۃِۣ الۡکَوَاکِبِ ۙ﴿۶﴾', 'بیشک ہم ہی نے آسمان دنیا کو ستاروں کی زینت سے سجایا۔', 'ہم نے رونق دی ورلے آسمان کو ایک رونق جو تارے ہیں [۶]', 'Verily! We have adorned the near heaven with the stars (for beauty).', 'Verily, We have decorated the nearest sky with an adornment, the stars,'),
(3795, 37, 7, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ  حِفۡظًا مِّنۡ کُلِّ شَیۡطٰنٍ مَّارِدٍ ۚ﴿۷﴾', 'اور ہر شیطان سرکش سے اسکی حفاظت کی۔', 'اور بچاؤ بنایا ہر شیطان سر کش سے [۷]', 'And to guard against every rebellious devil.', 'and (have made them) a security against every rebellious devil.'),
(3796, 37, 8, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'لَا یَسَّمَّعُوۡنَ  اِلَی الۡمَلَاِ الۡاَعۡلٰی وَ یُقۡذَفُوۡنَ مِنۡ  کُلِّ  جَانِبٍ ٭ۖ﴿۸﴾', 'کہ اوپر کی مجلس کی طرف کان نہ لگا سکیں اور ہر طرف سے ان پر انگارے پھینکے جاتے ہیں۔', 'سن نہیں سکتے اوپرکی مجلس تک اور پھینکے جاتےہیں ان پر ہر طرف سے', 'They cannot listen to the higher group (angels) for they are pelted from every side.', 'They cannot listen to the Upper Realm and are hit from every side'),
(3797, 37, 9, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'دُحُوۡرًا  وَّ  لَہُمۡ  عَذَابٌ  وَّاصِبٌ ۙ﴿۹﴾', 'یعنی وہاں سے نکال دینے کو اور انکے لئے ہمیشہ کا عذاب ہے۔', 'بھگانے کو [۸] اور ان پر مار ہے ہمیشہ کو [۹]', 'Outcast, and theirs is a constant (or painful) torment.', 'to be driven off, and for them there is a lasting punishment;'),
(3798, 37, 10, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِلَّا مَنۡ خَطِفَ الۡخَطۡفَۃَ فَاَتۡبَعَہٗ شِہَابٌ  ثَاقِبٌ ﴿۱۰﴾', 'ہاں جو کوئی فرشتوں کی کسی بات کو چوری سے جھپٹ لینا چاہتا ہے تو جلتا ہوا انگارہ اسکے پیچھے لگ جاتا ہے۔', 'مگر جو کوئی اچک لایا جھپ سے پھر پیچھے لگا اس کے انگارا چمکتا [۱۰]', 'Except such as snatch away something by stealing and they are pursued by a flaming fire of piercing brightness.', 'however, if one snatches a little bit, he is pursued by a bright flame.'),
(3799, 37, 11, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَاسۡتَفۡتِہِمۡ  اَہُمۡ اَشَدُّ خَلۡقًا اَمۡ مَّنۡ خَلَقۡنَا ؕ اِنَّا خَلَقۡنٰہُمۡ مِّنۡ طِیۡنٍ لَّازِبٍ ﴿۱۱﴾', 'تو ان سے پوچھو کہ انکا بنانا مشکل ہے یا جتنی خلقت ہم نے بنائی ہے اس کا؟ انہیں ہم نے چپکنے والے گارے سے بنایا ہے۔', 'اب پوچھ ان سے کیا یہ بنانے مشکل ہیں یا جتنی خلقت کہ ہم نے  بنائی [۱۱] ہم نے ہی انکو بنایا ہے ایک چپکتے گارے سے [۱۲]', 'Then ask them (i.e. these polytheists, O Muhammad SAW): \"Are they stronger as creation, or those (others like the heavens and the earth and the mountains, etc.) whom We have created?\" Verily, We created them of a sticky clay.', 'Now ask them, “Are they stronger in the formation of their bodies, or those (other beings) that We have created?” Certainly, We did create them from sticky clay.'),
(3800, 37, 12, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'بَلۡ عَجِبۡتَ وَ  یَسۡخَرُوۡنَ ﴿۪۱۲﴾', 'ہاں تم تو تعجب کرتے ہو اور یہ مذاق اڑاتے ہیں۔', 'بلکہ تو کرتا ہے تعجب اور وہ کرتے ہیں ٹھٹھے [۱۳]', 'Nay, you (O Muhammad SAW) wondered (at their insolence) while they mock (at you and at the Quran).', 'But you wonder (at their denial), and they mock (at the idea of an Hereafter).'),
(3801, 37, 13, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ  اِذَا  ذُکِّرُوۡا لَا  یَذۡکُرُوۡنَ ﴿۪۱۳﴾', 'اور جب انکو نصیحت کی جاتی ہے تو نصیحت قبول نہیں کرتے۔', 'اور جب انکو سمجھائیے نہیں سوچتے', 'And when they are reminded, they pay no attention.', 'And when any advice is given to them, they pay no heed to it.'),
(3802, 37, 14, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ  اِذَا  رَاَوۡا  اٰیَۃً  یَّسۡتَسۡخِرُوۡنَ ﴿۪۱۴﴾', 'اور جب کوئی نشانی دیکھتے ہیں تو ٹھٹھے کرتے ہیں۔', 'اور جب دیکھیں کچھ نشانی ہنسی میں ڈال دیتے ہیں', 'And when they see an Ayah (a sign, a proof, or an evidence) from Allah, they mock at it.', 'And when they see a sign, they make fun of it,'),
(3803, 37, 15, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ  قَالُوۡۤا  اِنۡ ہٰذَاۤ   اِلَّا  سِحۡرٌ  مُّبِیۡنٌ ﴿ۚۖ۱۵﴾', 'اور کہتے ہیں کہ یہ تو کھلا جادو ہے۔', 'اور کہتے ہیں اور کچھ نہیں یہ تو کھلا جادو ہے [۱۴]', 'And they say: \"This is nothing but evident magic!', 'and say, “This is nothing but an open magic.'),
(3804, 37, 16, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'ءَ اِذَا مِتۡنَا وَ کُنَّا تُرَابًا وَّ  عِظَامًا ءَاِنَّا لَمَبۡعُوۡثُوۡنَ ﴿ۙ۱۶﴾', 'بھلا جب ہم مر گئے اور مٹی اور ہڈیاں ہو گئے تو کیا پھر اٹھائے جائیں گے؟', 'کیا جب ہم مر گئے اور ہو گئے مٹی اور ہڈیاں تو کیا ہم کو پھر اٹھائیں گے', '\"When we are dead and have become dust and bones, shall we (then) verily be resurrected?', 'Is it when we have died and become dust and bones, that we shall be raised again,'),
(3805, 37, 17, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اَوَ اٰبَآؤُنَا الۡاَوَّلُوۡنَ ﴿ؕ۱۷﴾', 'اور کیا ہمارے باپ دادا بھی جو پہلے ہو گذرے ہیں؟', 'کیا اور ہمارے اگلے باپ دادوں کو بھی [۱۵]', '\"And also our fathers of old?\"', 'and even our fathers of aforetime?”'),
(3806, 37, 18, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'قُلۡ  نَعَمۡ  وَ  اَنۡتُمۡ  دَاخِرُوۡنَ ﴿ۚ۱۸﴾', 'کہدو کہ ہاں اور تم لوگ ذلیل ہو گے۔', 'تو کہہ کہ ہاں اور تم ذلیل ہو گے', 'Say (O Muhammad SAW): \"Yes, and you shall then be humiliated.\"', 'Say, “Yes, and you shall be disgraced (too)!”'),
(3807, 37, 19, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَاِنَّمَا ہِیَ زَجۡرَۃٌ  وَّاحِدَۃٌ  فَاِذَا ہُمۡ یَنۡظُرُوۡنَ  ﴿۱۹﴾', 'بس وہ تو ایک زور کی آواز ہو گی اور یہ اسی وقت دیکھنے لگیں گے۔', 'سو وہ اٹھانا تو یہی ہے ایک جھڑکی پھر اسی وقت یہ  لگیں گے دیکھنے [۱۶]', 'It will be a single Zajrah (shout (i.e. the second blowing of the Trumpet)), and behold, they will be staring!', 'So, it will be only a single castigating call, and all of a sudden they will begin to see.'),
(3808, 37, 20, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ قَالُوۡا یٰوَیۡلَنَا ہٰذَا یَوۡمُ  الدِّیۡنِ ﴿۲۰﴾', 'اور کہیں گے ہائے کمبختی ہماری یہی جزا کا دن ہے۔', 'اور کہیں گے اے خرابی ہماری یہ آگیا دن جزا کا [۱۷]', 'They will say: \"Woe to us! This is the Day of Recompense!\"', 'And they will be saying, “Woe to us; this is the Day of Retribution.”'),
(3809, 37, 21, 1, 5, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'ہٰذَا یَوۡمُ الۡفَصۡلِ الَّذِیۡ کُنۡتُمۡ بِہٖ تُکَذِّبُوۡنَ ﴿٪۲۱﴾', 'کہا جائے گا کہ ہاں وہی فیصلے کا دن جسکو تم جھوٹ سمجھتے تھے۔', 'یہ ہے دن فیصلہ کا جس کو تم جھٹلاتے تھے [۱۸]', '(It will be said): \"This is the Day of Judgement which you used to deny.\"', '(It will be said to them,) “This is the Day of Judgment that you used to deny.”'),
(3810, 37, 22, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اُحۡشُرُوا الَّذِیۡنَ ظَلَمُوۡا وَ اَزۡوَاجَہُمۡ وَ مَا  کَانُوۡا  یَعۡبُدُوۡنَ ﴿ۙ۲۲﴾', 'فرشتوں کو حکم ہو گا جو لوگ ظلم کرتے تھے انکو اور انکے ہم جنسوں کو اور جنکو وہ پوجا کرتے تھے سب کو جمع کر لو۔', 'جمع کرو گنہگاروں کو اور انکے جوڑوں کو اور جو کچھ پوجتے تھے [۱۹]', '(It will be said to the angels): \"Assemble those who did wrong, together with their companions (from the devils) and what they used to worship.', '(It will be said to the angels,) “Muster all those who were unjust, and their fellows, and whatever they used to worship'),
(3811, 37, 23, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'مِنۡ دُوۡنِ اللّٰہِ  فَاہۡدُوۡہُمۡ  اِلٰی صِرَاطِ الۡجَحِیۡمِ ﴿ٙ۲۳﴾', 'یعنی جنکو اللہ کے سوا پوجا کرتے تھے پھر انکو جہنم کے رستے پر چلا دو۔', 'اللہ کے سوائے پھر چلاؤ ان کو دوزخ کی راہ پر [۲۰]', '\"Instead of Allah, and lead them on to the way of flaming Fire (Hell);', 'other than Allah, and show them the way to Jahannam ,'),
(3812, 37, 24, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ قِفُوۡہُمۡ   اِنَّہُمۡ  مَّسۡئُوۡلُوۡنَ ﴿ۙ۲۴﴾', 'اور انکو ٹھہرائے رکھو کہ ان سے کچھ پوچھنا ہے۔', 'اور کھڑا رکھو انکو  ان سے پوچھنا ہے [۲۱]', '\"But stop them, verily they are to be questioned.', 'and stop them (for a while,) for they are to be asked some questions.”'),
(3813, 37, 25, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'مَا  لَکُمۡ  لَا  تَنَاصَرُوۡنَ ﴿۲۵﴾', 'تم کو کیا ہوا کہ ایک دوسرے کی مدد نہیں کرتے۔', 'کیا ہوا تم کو  ایک دوسرے کی مدد نہیں کرتے', '\"What is the matter with you? Why do you not help one another (as you used to do in the world)?\"', '(Then they will be asked, “What is wrong with you that you do not help each other?”'),
(3814, 37, 26, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'بَلۡ  ہُمُ  الۡیَوۡمَ  مُسۡتَسۡلِمُوۡنَ ﴿۲۶﴾', 'اصل بات یہ ہے کہ آج یہ لوگ اپنی غلطی تسلیم کر رہے ہیں۔', 'کوئی نہیں وہ آج اپنے آپ کو  پکڑواتے ہیں [۲۲]', 'Nay, but that Day they shall surrender,', 'On the contrary, that day all of them will have totally surrendered.'),
(3815, 37, 27, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ اَقۡبَلَ بَعۡضُہُمۡ عَلٰی بَعۡضٍ یَّتَسَآءَلُوۡنَ ﴿۲۷﴾', 'اور وہ ایک دوسرے کی طرف رخ کر کے سوال و جواب کریں گے۔', 'اور منہ کیا بعضوں نے بعضوں کی طرف لگے پوچھنے', 'And they will turn to one another and question one another.', 'And some of them (the followers of their chiefs) will turn to others (the chiefs), asking questions from one another.'),
(3816, 37, 28, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'قَالُوۡۤا اِنَّکُمۡ کُنۡتُمۡ تَاۡتُوۡنَنَا عَنِ الۡیَمِیۡنِ ﴿۲۸﴾', 'پیروکار اپنے پیشواؤں سے کہیں گے کہ تم ہی ہمارے پاس دائیں طرف سے آتے تھے۔', 'بولے تم ہی تھے کہ آتے تھے ہم پر داہنی طرف سے [۲۳]', 'They will say: \"It was you who used to come to us from the right side (i.e. from the right side of one of us and beautify for us every evil, order us for polytheism, and stop us from the truth i.e. Islamic Monotheism and from every good deed).\"', 'They (the followers) will say, “You were the ones who used to come to (mislead) us forcefully.”'),
(3817, 37, 29, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'قَالُوۡا  بَلۡ  لَّمۡ  تَکُوۡنُوۡا  مُؤۡمِنِیۡنَ ﴿ۚ۲۹﴾', 'وہ کہیں گے نہیں بلکہ تم ہی ایمان لانے والے نہ تھے۔', 'وہ بولے کوئی نہیں پر تم ہی نہ تھے یقین لانے والے', 'They will reply: \"Nay, you yourselves were not believers.', 'They (the chiefs) will say, “On the contrary, you yourselves were not believers.'),
(3818, 37, 30, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ مَا  کَانَ لَنَا عَلَیۡکُمۡ مِّنۡ سُلۡطٰنٍ ۚ بَلۡ  کُنۡتُمۡ  قَوۡمًا طٰغِیۡنَ ﴿۳۰﴾', 'اور ہمارا تم پر کچھ زور نہ تھا۔ بلکہ تم ہی سرکش لوگ تھے۔', 'اور ہمارا تم پر کچھ زور نہ تھا پر تم ہی تھے لوگ حد سے نکل چلنے  والے', '\"And we had no authority over you. Nay! But you were transgressing people (disobedient, polytheists, and disbelievers).', 'We had no authority over you at all, but you yourselves were a transgressing people.'),
(3819, 37, 31, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَحَقَّ عَلَیۡنَا قَوۡلُ رَبِّنَاۤ ٭ۖ اِنَّا  لَذَآئِقُوۡنَ ﴿۳۱﴾', 'سو ہمارے بارے میں ہمارے پروردگار کی بات پوری ہو گئ کہ اب ہم عذاب کے مزے چکھیں گے۔', 'سو ثابت ہو گئ ہم پر بات ہمارے  رب کی بیشک ہم کو مزہ چکھنا ہے', '\"So now the Word of our Lord has been justified against us, that we shall certainly (have to) taste (the torment).', 'So, the word of our Lord has come true against us. Indeed, we have to taste (the punishment).'),
(3820, 37, 32, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَاَغۡوَیۡنٰکُمۡ   اِنَّا کُنَّا غٰوِیۡنَ ﴿۳۲﴾', 'سو ہم نے تمکو بھی گمراہ کیا کہ ہم خود بھی تو گمراہ تھے۔', 'ہم نے تم کو گمراہ کیا جیسے ہم خود تھے گمراہ [۲۴]', '\"So we led you astray because we were ourselves astray.\"', 'We did misguide you, (because) we were ourselves erroneous”.'),
(3821, 37, 33, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَاِنَّہُمۡ یَوۡمَئِذٍ فِی الۡعَذَابِ مُشۡتَرِکُوۡنَ ﴿۳۳﴾', 'پس وہ اس روز عذاب میں ایک دوسرے کے شریک ہوں گے۔', 'سو وہ سب اس دن تکلیف میں شریک ہیں [۲۵]', 'Then verily, that Day, they will (all) share in the torment.', 'So, that day, they will share each other in punishment.'),
(3822, 37, 34, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّا کَذٰلِکَ نَفۡعَلُ  بِالۡمُجۡرِمِیۡنَ ﴿۳۴﴾', 'ہم گنہگاروں کے ساتھ ایسا ہی کیا کرتے ہیں۔', 'ہم ایسا ہی کرتے ہیں گنہگاروں کے حق میں', 'Certainly, that is how We deal with AlMujrimoon (polytheists, sinners, criminals, the disobedient to Allah, etc.).', 'This is how We deal with the criminals.'),
(3823, 37, 35, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّہُمۡ  کَانُوۡۤا  اِذَا  قِیۡلَ  لَہُمۡ  لَاۤ  اِلٰہَ   اِلَّا  اللّٰہُ ۙ یَسۡتَکۡبِرُوۡنَ ﴿ۙ۳۵﴾', 'ان کا یہ حال تھا کہ جب ان سے کہا جاتا تھا کہ اللہ کے سوا کوئی معبود نہیں تو تکبر کرتے تھے۔', 'وہ تھے کہ ان سے جب کوئی کہتا کسی کی بندگی نہیں سوائے اللہ کے تو غرور کرتے [۲۶]', 'Truly, when it was said to them: La ilaha ill-Allah \"(none has the right to be worshipped but Allah),\" they puffed themselves up with pride (i.e. denied it).', 'They were those to whom when it was said: “There is no god but Allah”, they waxed proud,'),
(3824, 37, 36, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ یَقُوۡلُوۡنَ  اَئِنَّا  لَتَارِکُوۡۤا  اٰلِہَتِنَا لِشَاعِرٍ  مَّجۡنُوۡنٍ ﴿ؕ۳۶﴾', 'اور کہتے تھے کہ بھلا ہم ایک دیوانے شاعر کے کہنے سے کہیں اپنے معبودوں کو چھوڑ دینے والے ہیں۔', 'اور کہتے کیا ہم چھوڑ دیں گے اپنے معبودوں کو کہنے سے ایک شاعر دیوانہ کے', 'And (they) said: \"Are we going to abandon our aliha (gods) for the sake of a mad poet?', 'and used to say, “Are we really to leave our gods because of an insane poet?”'),
(3825, 37, 37, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'بَلۡ جَآءَ بِالۡحَقِّ وَ صَدَّقَ الۡمُرۡسَلِیۡنَ ﴿۳۷﴾', 'نہیں بلکہ یہی حق لے کر آئے ہیں اور پہلے کے پیغمبروں کو سچا کہتے ہیں۔', 'کوئی نہیں وہ  لیکر آیا ہے سچا دین اور سچا مانتا ہے سب رسولوں کو [۲۷]', 'Nay! he (Muhammad SAW) has come with the truth (i.e. Allahs Religion - Islamic Monotheism and this Quran) and he confirms the Messengers (before him who brought Allahs religion - Islamic Monotheism).', 'No, he has come with Truth and has confirmed all the messengers (of Allah).'),
(3826, 37, 38, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّکُمۡ  لَذَآئِقُوا  الۡعَذَابِ  الۡاَلِیۡمِ ﴿ۚ۳۸﴾', 'بیشک تم تکلیف دینے والے عذاب کا مزہ چکھنے والے ہو۔', 'بیشک تم کو تو چکھنا ہے عذاب دردناک', 'Verily, you (pagans of Makkah) are going to taste the painful torment;', 'Surely you have to taste the painful punishment,-'),
(3827, 37, 39, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ مَا تُجۡزَوۡنَ  اِلَّا مَا کُنۡتُمۡ تَعۡمَلُوۡنَ ﴿ۙ۳۹﴾', 'اور تمکو بدلہ ویسا ہی ملے گا جیسے تم کام کرتے تھے۔', 'اور وہ ہی بدلا پاؤ گے جو کچھ تم کرتے تھے [۲۸]', 'And you will be requited nothing except for what you used to do (evil deeds, sins, and Allahs disobedience which you used to do in this world);', 'And you will be recompensed for nothing but for what you used to do-'),
(3828, 37, 40, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِلَّا عِبَادَ  اللّٰہِ  الۡمُخۡلَصِیۡنَ ﴿۴۰﴾', 'مگر جو اللہ کے چنے ہوئے بندے ہیں۔', 'مگر جو بندے اللہ کے ہیں چنے ہوئے [۲۹]', 'Save the chosen slaves of Allah (faithful, obedient, true believers of Islamic Monotheism).', 'unlike Allah’s chosen servants.'),
(3829, 37, 41, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اُولٰٓئِکَ لَہُمۡ  رِزۡقٌ  مَّعۡلُوۡمٌ ﴿ۙ۴۱﴾', 'یہی لوگ ہیں جنکے لئے روزی مقرر ہے۔', 'وہ لوگ جو ہیں انکے واسطے روزی ہے مقرر', 'For them there will be a known provision (in Paradise).', 'Those are the people for whom there is a known provision,'),
(3830, 37, 42, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَوَاکِہُ ۚ وَ  ہُمۡ  مُّکۡرَمُوۡنَ ﴿ۙ۴۲﴾', 'یعنی میوے اور ان کا اعزاز و اکرام کیا جائے گا۔', 'میوے [۳۰] اور انکی عزت ہے [۳۱]', 'Fruits; and they shall be honoured,', 'the fruits; and they will be honored'),
(3831, 37, 43, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فِیۡ   جَنّٰتِ  النَّعِیۡمِ ﴿ۙ۴۳﴾', 'نعمت کے باغوں میں۔', 'نعمت کے باغوں میں', 'In the Gardens of delight (Paradise),', 'in Gardens of Bliss'),
(3832, 37, 44, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'عَلٰی  سُرُرٍ  مُّتَقٰبِلِیۡنَ ﴿۴۴﴾', 'ایکدوسرے کے سامنے تختوں پر بیٹھے ہوں گے۔', 'تختوں پر ایک دوسرے کے سامنے', 'Facing one another on thrones,', 'facing each other on couches.'),
(3833, 37, 45, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'یُطَافُ عَلَیۡہِمۡ  بِکَاۡسٍ مِّنۡ  مَّعِیۡنٍۭ ﴿ۙ۴۵﴾', 'شراب لطیف کے جام کا ان میں دور چل رہا ہو گا۔', 'لوگ لئے پھرتے ہیں ان کے پاس پیالہ شراب صاف کا', 'Round them will be passed a cup of pure wine;', 'They will be served with a cup from a flowing drink,'),
(3834, 37, 46, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'بَیۡضَآءَ   لَذَّۃٍ   لِّلشّٰرِبِیۡنَ ﴿ۚۖ۴۶﴾', 'جو رنگ کی سفید اور پینے والوں کے لئے سراسر لذت ہو گی۔', 'سفید رنگ مزہ دینے والی پینے والوں کو', 'White, delicious to the drinkers,', '(that will be) white (and) delicious for those who drink.'),
(3835, 37, 47, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'لَا فِیۡہَا غَوۡلٌ وَّ لَا ہُمۡ عَنۡہَا یُنۡزَفُوۡنَ ﴿۴۷﴾', 'نہ اس سے درد سر ہو اور نہ وہ اس سے بہکیں۔', 'نہ اس میں سر پھرتا ہے اور نہ وہ اس کو  پی کر بہکیں  [۳۲]', 'Neither they will have Ghoul (any kind of hurt, abdominal pain, headache, a sin, etc.) from that, nor will they suffer intoxication therefrom.', 'There will be no headache therein, nor will they be intoxicated with it,'),
(3836, 37, 48, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ عِنۡدَہُمۡ  قٰصِرٰتُ الطَّرۡفِ عِیۡنٌ ﴿ۙ۴۸﴾', 'اور انکے پاس حوریں ہوں گی جو نگاہیں نیچی رکھتی ہوں گی اور آنکھیں بڑی بڑی۔', 'اور ان کے پاس ہیں عورتیں نیچی گناہ رکھنے والیاں بڑی بڑی آنکھوں والیاں [۳۳]', 'And with them will be chaste females, restraining their glances (desiring none except their husbands), with wide and beautiful eyes.', 'and by their side there will be females restricting their gazes (to their husbands), having pretty big eyes,'),
(3837, 37, 49, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'کَاَنَّہُنَّ بَیۡضٌ مَّکۡنُوۡنٌ ﴿۴۹﴾', 'گویا وہ گرد و غبار سے محفوظ انڈے ہیں۔', 'گویا وہ انڈے ہیں چھپے دھرے [۳۴]', '(Delicate and pure) as if they were (hidden) eggs (well) preserved.', 'as if they were eggs hidden (under feathers, protected from pollution).'),
(3838, 37, 50, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَاَقۡبَلَ بَعۡضُہُمۡ عَلٰی بَعۡضٍ یَّتَسَآءَلُوۡنَ ﴿۵۰﴾', 'پھر وہ ایکدوسرے کی طرف رخ کر کے سوال و جواب کریں گے۔', 'پھر منہ کیا ایک نے دوسرے کی طرف لگے پوچھنے', 'Then they will turn to one another, mutually questioning.', 'Then they will turn to each other asking questions mutually.'),
(3839, 37, 51, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'قَالَ  قَآئِلٌ مِّنۡہُمۡ  اِنِّیۡ کَانَ لِیۡ قَرِیۡنٌ ﴿ۙ۵۱﴾', 'ایک کہنے والا ان میں سے کہے گا کہ میرا ایک ساتھی تھا۔', 'بولا ایک بولنے والا ان میں میرا تھا ایک ساتھی', 'A speaker of them will say: \"Verily, I had a companion (in the world),', 'A speaker from them will say, “I had a companion (in the worldly life)'),
(3840, 37, 52, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'یَّقُوۡلُ  اَئِنَّکَ  لَمِنَ  الۡمُصَدِّقِیۡنَ ﴿۵۲﴾', 'جو کہتا تھا کہ بھلا تم بھی ایسی باتوں کی تصدیق کرنے والوں میں ہو۔', 'کہا کرتا کیا تو یقین کرتا ہے', 'Who used to say: \"Are you among those who believe (in resurrection after death).', 'who used to say (to me), “Are you one of those who believe?'),
(3841, 37, 53, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'ءَ اِذَا مِتۡنَا وَ کُنَّا تُرَابًا وَّ  عِظَامًا  ءَ اِنَّا لَمَدِیۡنُوۡنَ ﴿۵۳﴾', 'بھلا جب ہم مر گئے اور مٹی اور ہڈیاں ہو گئے تو کیا ہمکو بدلہ ملے گا؟', 'کیا جب ہم مر گئے اور ہو گئے مٹی اور ہڈیاں کیا ہم کو جزا ملے گی [۳۵]', '\"(That) when we die and become dust and bones, shall we indeed (be raised up) to receive reward or punishment (according to our deeds)?\"', 'Is it when we have died and become dust and bones? Is it true that we are going to be recompensed (for our deeds)?”'),
(3842, 37, 54, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'قَالَ  ہَلۡ  اَنۡتُمۡ  مُّطَّلِعُوۡنَ ﴿۵۴﴾', 'اللہ کہے گا کہ بھلا تم اسے جھانک کر دیکھنا چاہتے ہو۔', 'کہنے لگا بھلا تم جھانک کر دیکھو گے [۳۶]', '(The man) said: \"Will you look down?\"', 'He (the speaker) will say (to other people in Paradise) “Would you like to have a look (at Jahannam to find out what happened to that companion of mine)?”'),
(3843, 37, 55, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَاطَّلَعَ  فَرَاٰہُ  فِیۡ  سَوَآءِ  الۡجَحِیۡمِ ﴿۵۵﴾', 'پھر وہ خود جھانکے گا تو اسکو بیچ دوزخ میں دیکھے گا۔', 'پھر جھانکا تو اس کو دیکھا بیچوں بیچ دوزخ کے', 'So he looked down and saw him in the midst of the Fire.', 'So he will look and will see him in the middle of Jahannam.'),
(3844, 37, 56, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'قَالَ تَاللّٰہِ   اِنۡ  کِدۡتَّ  لَتُرۡدِیۡنِ ﴿ۙ۵۶﴾', 'کہے گا کہ اللہ کی قسم تو تو مجھے بھی ہلاک کرنے لگا تھا۔', 'بولا قسم اللہ کی تو تو مجھ کو ڈالنے لگا تھا گڑھے میں', 'He said: \"By Allah! You have nearly ruined me.', 'He (the speaker) will say (to his companion seen in Jahannam ), “By Allah, you were going almost to ruin me.'),
(3845, 37, 57, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ لَوۡ لَا نِعۡمَۃُ رَبِّیۡ  لَکُنۡتُ مِنَ الۡمُحۡضَرِیۡنَ ﴿۵۷﴾', 'اور اگر میرے پروردگار کی مہربانی نہ ہوتی تو میں بھی ان میں ہوتا جو عذاب میں حاضر کئے گئے ہیں۔', 'اور اگر نہ ہوتا میرے رب کا فضل تو میں بھی ہوتا انہیں میں جو پکڑے ہوئے آئے [۳۷]', '\"Had it not been for the Grace of my Lord, I would certainly have been among those brought forth (to Hell).\"', 'But for the favor of my Lord, I would have been among those produced for punishment.”'),
(3846, 37, 58, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اَفَمَا نَحۡنُ بِمَیِّتِیۡنَ ﴿ۙ۵۸﴾', 'تو کیا واقعی اب ہم مرنے والے نہیں۔', 'کیا اب ہم کو مرنا نہیں', '(Allah informs about that true believer that he said): \"Are we then not to die (any more)?', '(Then the speaker will address other people of Paradise in delight and wonder, saying,) “Are we not then to die anymore'),
(3847, 37, 59, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِلَّا مَوۡتَتَنَا الۡاُوۡلٰی وَ مَا نَحۡنُ بِمُعَذَّبِیۡنَ ﴿۵۹﴾', 'ہاں جو پہلی بار مرنا تھا سو مر چکے اور ہمیں عذاب بھی نہیں ہونے کا۔', 'مگر جو پہلی بار مر چکے اور ہم کو تکلیف نہیں پہنچنے کی', '\"Except our first death, and we shall not be punished? (after we have entered Paradise).\"', 'beyond our first death, nor are we going to be punished?”'),
(3848, 37, 60, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّ ہٰذَا  لَہُوَ  الۡفَوۡزُ  الۡعَظِیۡمُ ﴿۶۰﴾', 'بیشک یہی تو بڑی کامیابی ہے۔', 'بیشک یہی ہے بڑی مراد ملنی', 'Truly, this is the supreme success!', 'This is, indeed, the great achievement.'),
(3849, 37, 61, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'لِمِثۡلِ ہٰذَا فَلۡیَعۡمَلِ الۡعٰمِلُوۡنَ ﴿۶۱﴾', 'ایسی ہی نعمتوں کے لئے عمل کرنے والوں کو عمل کرنے چاہئیں۔', 'ایسی چیزوں کے واسطے چاہئے محنت کریں محنت کرنے والے [۳۸]', 'For the like of this let the workers work.', 'For this kind (of achievement), all workers must work.'),
(3850, 37, 62, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اَذٰلِکَ خَیۡرٌ  نُّزُلًا  اَمۡ شَجَرَۃُ  الزَّقُّوۡمِ ﴿۶۲﴾', 'بھلا یہ مہمانی اچھی ہے یا تھوہر کا درخت۔', 'بھلا یہ بہتر ہے مہمانی یا درخت سیہنڈ کا', 'Is that (Paradise) better entertainment or the tree of Zaqqoom (a horrible tree in Hell)?', 'Is that (blissful Paradise) better for hospitality or the tree of zaqqūm ?'),
(3851, 37, 63, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّا جَعَلۡنٰہَا فِتۡنَۃً  لِّلظّٰلِمِیۡنَ ﴿۶۳﴾', 'ہم نے اسکو ظالموں کے لئے بلا بنایا ہوا ہے۔', 'ہم نے اس کو رکھا ہے ایک بلا ظالموں کے واسطے', 'Truly We have made it (as) a trail for the Zalimoon (polytheists, disbelievers, wrong-doers, etc.).', 'We have made it a test for the unjust.'),
(3852, 37, 64, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّہَا شَجَرَۃٌ  تَخۡرُجُ فِیۡۤ  اَصۡلِ الۡجَحِیۡمِ ﴿ۙ۶۴﴾', 'وہ ایک درخت ہے کہ جہنم کی تہہ میں اگے گا۔', 'وہ ایک درخت ہے کہ نکلتا ہے دوزخ کی جڑ میں [۳۹]', 'Verily, it is a tree that springs out of the bottom of Hell-fire,', 'It is a tree that comes forth in the bottom of Jahannam.'),
(3853, 37, 65, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'طَلۡعُہَا کَاَنَّہٗ  رُءُوۡسُ الشَّیٰطِیۡنِ ﴿۶۵﴾', 'اسکے خوشے ایسے ہوں گے جیسے شیطانوں کے سر۔', 'اس کا خوشہ جیسے سر شیطان کے [۴۰]', 'The shoots of its fruit-stalks are like the heads of Shayatin (devils);', 'Its fruits are like the heads of devils.'),
(3854, 37, 66, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَاِنَّہُمۡ لَاٰکِلُوۡنَ مِنۡہَا فَمَالِـُٔوۡنَ مِنۡہَا الۡبُطُوۡنَ ﴿ؕ۶۶﴾', 'سو وہ اسی میں سے کھائیں گے اور اسی سے پیٹ بھریں گے۔', 'سو  وہ کھائیں گے اس میں سے پھر بھریں گے اس سے پیٹ', 'Truly, they will eat thereof and fill their bellies therewith.', 'So, they have to eat from it and have to fill their bellies with it.'),
(3855, 37, 67, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'ثُمَّ  اِنَّ لَہُمۡ عَلَیۡہَا لَشَوۡبًا مِّنۡ حَمِیۡمٍ ﴿ۚ۶۷﴾', 'پھر اس کھانے کے ساتھ انکو کھولتا ہوا پانی ملا کر دیا جائے گا۔', 'پھر ان کے واسطے اس کے اوپر ملونی ہے جلتے پانی کی [۴۱]', 'Then on the top of that they will be given boiling water to drink so that it becomes a mixture (of boiling water and Zaqqoom in their bellies).', 'Then they will have, on top of it, a mixture made of boiling water.'),
(3856, 37, 68, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'ثُمَّ   اِنَّ  مَرۡجِعَہُمۡ  لَا۠ اِلَی  الۡجَحِیۡمِ ﴿۶۸﴾', 'پھر انکو دوزخ کی طرف لوٹایا جائے گا۔', 'پھر ان کو لیجانا آگ کے ڈھیر میں [۴۲]', 'Then thereafter, verily, their return is to the flaming fire of Hell.', 'Then, their final return is to the Fire.'),
(3857, 37, 69, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّہُمۡ  اَلۡفَوۡا  اٰبَآءَہُمۡ  ضَآلِّیۡنَ ﴿ۙ۶۹﴾', 'انہوں نے اپنے باپ دادا کو گمراہ ہی پایا تھا۔', 'انہوں نے پایا اپنے باپ دادوں کو بہکے ہوئے', 'Verily, they found their fathers on the wrong path;', 'They found their fathers on the wrong path.'),
(3858, 37, 70, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَہُمۡ عَلٰۤی  اٰثٰرِہِمۡ  یُہۡرَعُوۡنَ ﴿۷۰﴾', 'سو وہ انہی کے پیچھے دوڑے چلے جاتے تھے۔', 'سو  وہ انہی کے قدموں پر دوڑتے ہیں [۴۳]', 'So they (too) made haste to follow in their footsteps!', 'So, they used to run in their footsteps.'),
(3859, 37, 71, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ لَقَدۡ ضَلَّ  قَبۡلَہُمۡ  اَکۡثَرُ الۡاَوَّلِیۡنَ ﴿ۙ۷۱﴾', 'اور ان سے پیشتر بہت سے پہلے لوگ بھی گمراہ ہو گئے تھے۔', 'اور بہک چکے ہیں ان سے پہلے بہت لوگ اگلے', 'And indeed most of the men of old went astray before them;', 'Most of the earlier ones (too) had gone astray before them.'),
(3860, 37, 72, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ لَقَدۡ اَرۡسَلۡنَا فِیۡہِمۡ مُّنۡذِرِیۡنَ ﴿۷۲﴾', 'اور ہم نے ان میں خبردار کرنے والے بھیجے۔', 'اور ہم نے بھیجے ہیں ان میں ڈر سنانے والے', 'And indeed We sent among them warners (Messengers);', 'We did send warners among them.'),
(3861, 37, 73, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَانۡظُرۡ کَیۡفَ کَانَ عَاقِبَۃُ  الۡمُنۡذَرِیۡنَ ﴿ۙ۷۳﴾', 'سو دیکھ لو جنکو خبردار کیا گیا تھا ان کا انجام کیسا ہوا۔', 'اب دیکھ کیسا ہوا انجام ڈرائے ہوؤں کا', 'Then see what was the end of those who were warned (but heeded not).', 'So look, how was the end of those warned -'),
(3862, 37, 74, 2, 6, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِلَّا عِبَادَ  اللّٰہِ  الۡمُخۡلَصِیۡنَ ﴿٪۷۴﴾', 'ہاں اللہ کے چنے ہوئے بندوں کا انجام بہت اچھا ہوتا ہے۔', 'مگر جو بندے اللہ کے ہیں چنے ہوئے [۴۴]', 'Except the chosen slaves of Allah (faithful, obedient, and true believers of Islamic Monotheism).', 'except Allah’s chosen servants.'),
(3863, 37, 75, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ لَقَدۡ نَادٰىنَا نُوۡحٌ فَلَنِعۡمَ الۡمُجِیۡبُوۡنَ ﴿۫ۖ۷۵﴾', 'اور ہمکو نوح نے پکارا سو دیکھ لو کہ ہم دعا کو کیسے اچھے قبول کرنے والے ہیں۔', 'اور ہم کو پکارا تھا نوح نے سو کیا خوب پہنچنے والے ہیں ہم پکار  پر', 'And indeed Nooh (Noah) invoked Us, and We are the Best of those who answer (the request).', 'And NūH did call Us (for help after he was disappointed with his people), so (We accepted his prayer, as) We are the best to respond.'),
(3864, 37, 76, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ نَجَّیۡنٰہُ  وَ اَہۡلَہٗ  مِنَ الۡکَرۡبِ الۡعَظِیۡمِ ﴿۫ۖ۷۶﴾', 'اور ہم نے انکو اور انکے گھر والوں کو بڑی مصیبت سے نجات دی۔', 'اور بچا دیا اسکو اور اسکے گھر کو اس بڑی گھبراہٹ سے', 'And We rescued him and his family from the great distress (i.e. drowning),', 'And We delivered him and his family from the great agony,'),
(3865, 37, 77, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ جَعَلۡنَا ذُرِّیَّتَہٗ  ہُمُ  الۡبٰقِیۡنَ ﴿۫ۖ۷۷﴾', 'اور انکی اولاد ہی کو ہم نے باقی رہنے والا بنا دیا۔', 'اور رکھا اس کی اولاد کو  وہی باقی رہنے والے', 'And, his progeny, them We made the survivors (i.e. Shem, Ham and Japheth).', 'and made his progeny the sole survivors (from the Deluge).'),
(3866, 37, 78, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ تَرَکۡنَا عَلَیۡہِ  فِی الۡاٰخِرِیۡنَ ﴿۫ۖ۷۸﴾', 'اور ہم نے پیچھے آنے والوں میں ان کا ذکر جمیل باقی رکھا۔', 'اور باقی رکھا اس پر پچھلے لوگوں میں', 'And left for him (a goodly remembrance) among generations to come in later times:', 'And We left for him (a word of praise) among the later people, (that is):'),
(3867, 37, 79, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'سَلٰمٌ  عَلٰی نُوۡحٍ فِی الۡعٰلَمِیۡنَ ﴿۷۹﴾', 'یعنی تمام جہان میں کہ نوح پر سلام ہو۔', 'کہ سلام ہے نوح پر سارے جہان والوں میں', 'Salamun (peace) be upon Nooh (Noah) (from Us) among the Alameen (mankind, jinns and all that exists)!\"', 'Salām be on NūH among (the people of) all the worlds.'),
(3868, 37, 80, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّا کَذٰلِکَ نَجۡزِی الۡمُحۡسِنِیۡنَ ﴿۸۰﴾', 'نیکوکاروں کو ہم ایسا ہی بدلہ دیا کرتے ہیں۔', 'ہم یوں بدلا دیتے ہیں نیکی والوں کو', 'Verily, thus We reward the Muhsinoon (good-doers - see V.2:112).', 'Certainly, this is how We reward those who are good in their deeds.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(3869, 37, 81, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّہٗ  مِنۡ عِبَادِنَا الۡمُؤۡمِنِیۡنَ ﴿۸۱﴾', 'بیشک وہ ہمارے مومن بندوں میں سے تھے۔', 'وہ ہے  ہمارے ایماندار بندوں میں', 'Verily, he (Nooh (Noah) ) was one of Our believing slaves.', 'He was one of Our believing servants.'),
(3870, 37, 82, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'ثُمَّ   اَغۡرَقۡنَا الۡاٰخَرِیۡنَ  ﴿۸۲﴾', 'پھر ہم نے دوسروں کو ڈبو دیا۔', 'پھر ڈوبا دیا ہم نے دوسروں کو [۴۵]', 'Then We drowned the other (disbelievers and polytheists, etc.).', 'Then, we drowned others.'),
(3871, 37, 83, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ  اِنَّ مِنۡ شِیۡعَتِہٖ  لَاِبۡرٰہِیۡمَ ﴿ۘ۸۳﴾', 'اور انہی کے پیروؤں میں ابراہیم تھے۔', 'اور اسی کی راہ والوں میں ہے ابراہیم [۴۶]', 'And, verily, among those who followed his (Noohs (Noah)) way (Islamic Monotheism) was Ibrahim (Abraham).', 'And certainly one of his adherents was Ibrāhīm.'),
(3872, 37, 84, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِذۡ  جَآءَ  رَبَّہٗ  بِقَلۡبٍ  سَلِیۡمٍ ﴿۸۴﴾', 'جب وہ اپنے پروردگار کے پاس عیب سے پاک دل لے کر آئے۔', 'جب آیا اپنے رب کے پاس لیکر دل نروگا [۴۷]', 'When he came to his Lord with a pure heart (attached to Allah Alone and none else, worshipping none but Allah Alone true Islamic Monotheism, pure from the filth of polytheism).', '(Remember) when he came to his Lord with a pure heart,'),
(3873, 37, 85, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِذۡ قَالَ  لِاَبِیۡہِ وَ قَوۡمِہٖ مَاذَا تَعۡبُدُوۡنَ ﴿ۚ۸۵﴾', 'جب انہوں نے اپنے باپ سے اور اپنی قوم سے کہا کہ تم کن چیزوں کو پوجتے ہو؟', 'جب کہا اپنے باپ کو اور اسکی قوم کو تم کیا پوجتے ہو', 'When he said to his father and to his people: \"What is it that which you worship?', 'when he said to his father and his people, “What is that which you worship?'),
(3874, 37, 86, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اَئِفۡکًا  اٰلِہَۃً  دُوۡنَ اللّٰہِ  تُرِیۡدُوۡنَ ﴿ؕ۸۶﴾', 'کیوں اپنی طرف سے گھڑ کر اللہ کے سوا اور معبودوں کے طالب ہو۔', 'کیا جھوٹ بنائے ہوئے حاکموں کو اللہ کے سوائے چاہتے ہو [۴۸]', '\"Is it a falsehood aliha (gods) other than Allah that you seek?', 'Do you wish (to have) fallacious gods other than Allah?'),
(3875, 37, 87, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَمَا ظَنُّکُمۡ  بِرَبِّ الۡعٰلَمِیۡنَ ﴿۸۷﴾', 'بھلا پروردگار عالم کے بارے میں تمہارا کیا خیال ہے؟', 'پھر کیا خیال کیا ہے تم  نے پروردگار عالم کو [۴۹]', '\"Then what do you think about the Lord of the Alameen (mankind, jinns, and all that exists)?\"', 'Then, what do you think about the Lord of the worlds?”'),
(3876, 37, 88, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَنَظَرَ  نَظۡرَۃً  فِی النُّجُوۡمِ ﴿ۙ۸۸﴾', 'تب انہوں نے ستاروں کی طرف ایک نظر کی۔', 'پھر نگاہ کی ایک بار تاروں میں', 'Then he cast a glance at the stars (to deceive them),', 'Then, he cast a look at the stars,'),
(3877, 37, 89, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَقَالَ  اِنِّیۡ سَقِیۡمٌ ﴿۸۹﴾', 'پھر کہا میری تو طبیعت ٹھیک نہیں ہے۔', 'پھر کہا میں بیمار ہونے والا ہوں', 'And he said: \"Verily, I am sick (with plague. He did this trick to remain in their temple of idols to destroy them and not to accompany them to the pagans feast).\"', 'and then said, “I feel indisposed”'),
(3878, 37, 90, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَتَوَلَّوۡا عَنۡہُ  مُدۡبِرِیۡنَ ﴿۹۰﴾', 'تب لوگ ان سے پیٹھ پھیر کر چلے گئے۔', 'پھر پھر گئے وہ اس سے پیٹھ دے کر', 'So they turned away from him, and departed (for fear of the disease).', 'So they went away from him, turning their backs.'),
(3879, 37, 91, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَرَاغَ  اِلٰۤی  اٰلِہَتِہِمۡ  فَقَالَ  اَلَا  تَاۡکُلُوۡنَ ﴿ۚ۹۱﴾', 'پھر ابراہیم انکے معبودوں کی طرف متوجہ ہوئے اور کہنے لگے کہ تم کھاتے کیوں نہیں۔', 'پھر جا گھسا ان کے بتوں میں پھر بولا تم کیوں نہیں کھاتے [۵۰]', 'Then he turned to their aliha (gods) and said: \"Will you not eat (of the offering before you)?', 'And he made his way to their ‘gods’ and said to them, “Why would you not eat?'),
(3880, 37, 92, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'مَا  لَکُمۡ  لَا تَنۡطِقُوۡنَ ﴿۹۲﴾', 'تمہیں کیا ہوا ہے تم بولتے نہیں؟', 'تم کو کیا ہے کہ نہیں بولتے [۵۱]', '\"What is the matter with you that you speak not?\"', 'What is wrong with you that you do not speak?”'),
(3881, 37, 93, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَرَاغَ  عَلَیۡہِمۡ  ضَرۡبًۢا بِالۡیَمِیۡنِ ﴿۹۳﴾', 'پھر انکو داہنے ہاتھ سے مارنا اور توڑنا شروع کیا۔', 'پھر گھسا ان پر مارتا ہوا داہنے ہاتھ سے [۵۲]', 'Then he turned upon them, striking (them) with (his) right hand.', 'Then he attacked them striking with his right hand.'),
(3882, 37, 94, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَاَقۡبَلُوۡۤا  اِلَیۡہِ  یَزِفُّوۡنَ ﴿۹۴﴾', 'پھر وہ لوگ انکے پاس دوڑے ہوئے آئے۔', 'پھر لوگ آئے اس پر دوڑ کر گھبراتے ہوئے [۵۳]', 'Then they (the worshippers of idols) came, towards him, hastening.', 'Then, they (the idolaters) came to him rushing.'),
(3883, 37, 95, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'قَالَ  اَتَعۡبُدُوۡنَ  مَا تَنۡحِتُوۡنَ ﴿ۙ۹۵﴾', 'ابراہیم نے کہا کہ تم ایسی چیزوں کو کیوں پوجتے ہو جنکو خود تراشتے ہو۔', 'بولا کیوں پوجتے ہو جو آپ تراشتے ہو', 'He said: \"Worship you that which you (yourselves) carve?', 'He said, “Do you worship what is carved by yourselves,'),
(3884, 37, 96, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ اللّٰہُ خَلَقَکُمۡ  وَ مَا تَعۡمَلُوۡنَ ﴿۹۶﴾', 'حالانکہ تمکو اور جو تم بناتے ہو اسکو اللہ ہی نے پیدا کیا ہے۔', 'اور اللہ نے بنایا تم کو اور جو تم بناتے ہو [۵۴]', '\"While Allah has created you and what you make!\"', 'while Allah has created you and what you make?”'),
(3885, 37, 97, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'قَالُوا ابۡنُوۡا لَہٗ  بُنۡیَانًا فَاَلۡقُوۡہُ  فِی الۡجَحِیۡمِ ﴿۹۷﴾', 'وہ کہنے لگے کہ اس کے لئے ایک عمارت بناؤ پھر اسکو آگ کے ڈھیر میں ڈالدو۔', 'بولے بناؤ اس کے واسطے ایک عمارت پھر ڈالو اس کو آگ کے ڈھیر میں', 'They said: \"Build for him a building (it is said that the building was like a furnace) and throw him into the blazing fire!\"', 'They said, “Build for him a structure, and throw him into the blazing fire.”'),
(3886, 37, 98, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَاَرَادُوۡا بِہٖ کَیۡدًا فَجَعَلۡنٰہُمُ  الۡاَسۡفَلِیۡنَ ﴿۹۸﴾', 'غرض انہوں نے انکے ساتھ ایک چال چلنی چاہی اور ہم نے انہی کو زیر کر دیا۔', 'پھر چاہنے لگے اس پر برا داؤ کرنا پھر ہم  نے ڈالا  انہی کو نیچے [۵۵]', 'So they plotted a plot against him, but We made them the lowest.', 'So, they intended to bring harm to him, but We made them the lowest (by frustrating their plan).'),
(3887, 37, 99, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ قَالَ  اِنِّیۡ ذَاہِبٌ  اِلٰی رَبِّیۡ سَیَہۡدِیۡنِ ﴿۹۹﴾', 'اور ابراہیم بولے کہ میں اپنے پروردگار کی طرف جانے والا ہوں وہ مجھے رستہ دکھائے گا۔', 'اور بولا میں جاتا ہوں اپنے رب کی طرف وہ مجھ کو راہ دے گا [۵۶]', 'And he said (after his rescue from the fire): \"Verily, I am going to my Lord. He will guide me!\"', 'And he said, “I am going to my Lord. He will show me the way.'),
(3888, 37, 100, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'رَبِّ ہَبۡ  لِیۡ  مِنَ  الصّٰلِحِیۡنَ ﴿۱۰۰﴾', 'اے پروردگار مجھے اولاد عطا فرما جو سعادت مندوں میں سے ہو۔', 'اے رب بخش مجھ کو کوئی نیک بیٹا [۵۷]', '\"My Lord! Grant me (offspring) from the righteous.\"', 'O my Lord, bless me with a righteous son.”'),
(3889, 37, 101, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَبَشَّرۡنٰہُ  بِغُلٰمٍ  حَلِیۡمٍ ﴿۱۰۱﴾', 'تو ہم نے انکو ایک بردبار لڑکے کی خوشخبری دی۔', 'پھر خوشخبری دی ہم نے اسکو ایک لڑکے کی جو ہو گا تحمل والا [۵۸]', 'So We gave him the glad tidings of a forbearing boy.', 'So, We gave him the good news of a forbearing boy.'),
(3890, 37, 102, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَلَمَّا بَلَغَ مَعَہُ  السَّعۡیَ قَالَ یٰبُنَیَّ  اِنِّیۡۤ اَرٰی فِی الۡمَنَامِ اَنِّیۡۤ  اَذۡبَحُکَ فَانۡظُرۡ مَاذَا تَرٰی ؕ قَالَ یٰۤاَبَتِ افۡعَلۡ مَا تُؤۡمَرُ ۫ سَتَجِدُنِیۡۤ  اِنۡ شَآءَ اللّٰہُ مِنَ الصّٰبِرِیۡنَ ﴿۱۰۲﴾', 'جب وہ انکے ساتھ دوڑ دھوپ کی عمر کو پہنچا تو ابراہیم نے کہا کہ بیٹا میں خواب میں دیکھتا ہوں کہ گویا تمکو ذبح کر رہا ہوں تو تم سوچ لو کہ تمہارا کیا ارادہ ہے۔ انہوں نے کہا کہ ابا جان جو آپ کو حکم ہوا ہے وہی کیجئے اللہ نے چاہا تو آپ مجھے صابروں میں پائیے گا۔', 'پھر جب پہنچا اس کے ساتھ دوڑنے کو کہا اے بیٹے میں دیکھتا ہوں خواب میں کہ تجھ کو ذبح کرتا ہوں پھر دیکھ تو تو کیا دیکھتا ہے بولا اے باپ کر ڈال جو تجھ کو حکم ہوتا ہے تو مجھکو کو پائے گا اگر اللہ نے چاہا سہارنے والا [۵۹]', 'And, when he (his son) was old enough to walk with him, he said: \"O my son! I have seen in a dream that I am slaughtering you (offer you in sacrifice to Allah), so look what you think!\" He said: \"O my father! Do that which you are commanded, Insha Allah (if Allah will), you shall find me of As-Sabirin (the patient ones, etc.).\"', 'Thereafter, when he (the boy) reached an age in which he could work with him, he (Ibrāhīm) said, “O my little son, I have seen in a dream that I am slaughtering you, so consider, what is your opinion?” He said, “O my dear father, do what you have been ordered to do. You will find me, inshā’allah , (if Allah wills) one of those who endure patiently.”'),
(3891, 37, 103, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَلَمَّاۤ   اَسۡلَمَا وَ  تَلَّہٗ   لِلۡجَبِیۡنِ ﴿۱۰۳﴾ۚ', 'اس طرح جب دونوں نے حکم مان لیا اور باپ نے بیٹے کو ماتھے کے بل لٹا دیا۔', 'پھر جب دونوں نے حکم مانا اور پچھایا اسکو ماتھے کے بل [۶۰]', 'Then, when they had both submitted themselves (to the Will of Allah), and he had laid him prostrate on his forehead (or on the side of his forehead for slaughtering);', 'So, (it was a great episode) when both of them submitted themselves (to Allah’s will), and he laid him on his forehead (to slaughter him),'),
(3892, 37, 104, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ  نَادَیۡنٰہُ  اَنۡ  یّٰۤاِبۡرٰہِیۡمُ ﴿۱۰۴﴾ۙ', 'تو ہم نے انکو پکارا کہ اے ابراہیم۔', 'اور ہم نے اس کو پکارا یوں کہ اے ابراہیم', 'And We called out to him: \"O Abraham!', 'and then We called out to him, “O Ibrāhīm,'),
(3893, 37, 105, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'قَدۡ صَدَّقۡتَ الرُّءۡیَا ۚ اِنَّا کَذٰلِکَ نَجۡزِی الۡمُحۡسِنِیۡنَ ﴿۱۰۵﴾', 'تم نے خواب کو سچا کر دکھایا ہم نیکوکاروں کو ایسا ہی بدلہ دیا کرتے ہیں۔', 'تو نے سچ کر دکھایا خواب [۶۱] ہم یوں دیتے ہیں بدلا نیکی کرنے والوں کو', 'You have fulfilled the dream (vision)!\" Verily! Thus do We reward the Muhsinoon (good-doers - see V.2:112).', 'you did make the dream come true.” This is how We reward those who are good in their deeds.'),
(3894, 37, 106, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّ ہٰذَا لَہُوَ  الۡبَلٰٓـؤُا الۡمُبِیۡنُ ﴿۱۰۶﴾', 'بلاشبہ یہ کھلی آزمائش تھی۔', 'بیشک یہی ہے صریح جانچنا [۶۲]', 'Verily, that indeed was a manifest trial', 'This was indeed a trial that clearly demonstrated (their obedience).'),
(3895, 37, 107, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ فَدَیۡنٰہُ  بِذِبۡحٍ عَظِیۡمٍ ﴿۱۰۷﴾', 'اور ہم نے قربانی کے ایک بڑے جانور سے ان کا یعنی اسمٰعیل کا فدیہ دیا۔', 'اور اس کا بدلہ دیا ہم نے ایک جانور ذبح کرنے کے واسطے بڑا [۶۳]', 'And We ransomed him with a great sacrifice (i.e. ßÈÔ - a ram);', 'And We ransomed him with a great sacrifice,'),
(3896, 37, 108, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ تَرَکۡنَا عَلَیۡہِ فِی الۡاٰخِرِیۡنَ ﴿۱۰۸﴾ۖ', 'اور پیچھے آنے والوں میں ہم نے ابراہیم کا ذکر خیر باقی رکھا۔', 'اور باقی رکھا ہم نے اس پر پچھلے لوگوں میں', 'And We left for him (a goodly remembrance) among generations (to come) in later times.', 'and We left for him (a word of praise) among the later people,'),
(3897, 37, 109, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'سَلٰمٌ  عَلٰۤی  اِبۡرٰہِیۡمَ ﴿۱۰۹﴾', 'کہ ابراہیم پر سلام ہو۔', 'کہ سلام ہو ابراہیم پر [۶۴]', 'Salamun (peace) be upon Ibrahim (Abraham)!\"', '(that is,) “Salām be on Ibrāhīm!'),
(3898, 37, 110, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'کَذٰلِکَ نَجۡزِی الۡمُحۡسِنِیۡنَ ﴿۱۱۰﴾', 'نیکوکاروں کو ہم ایسا ہی بدلہ دیا کرتے ہیں۔', 'ہم یوں دیتے ہیں بدلا نیکی کرنے والوں کو', 'Thus indeed do We reward the Muhsinoon (good-doers - see V.2:112).', 'This is how We reward those who are good in their deeds.'),
(3899, 37, 111, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّہٗ مِنۡ عِبَادِنَا الۡمُؤۡمِنِیۡنَ ﴿۱۱۱﴾', 'بیشک وہ ہمارے مومن بندوں میں سے تھے۔', 'وہ ہے ہمارے ایماندار بندوں میں [۶۵]', 'Verily, he was one of Our believing slaves.', 'Surely, he is among Our believing servants.'),
(3900, 37, 112, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ بَشَّرۡنٰہُ بِاِسۡحٰقَ نَبِیًّا مِّنَ الصّٰلِحِیۡنَ ﴿۱۱۲﴾', 'اور ہم نے انکو اسحٰق کی بشارت بھی دی کہ وہ نبی اور نیکوکاروں میں سے ہوں گے۔', 'اور خوشخبری دی ہم نے اسکو اسحٰق کی جو نبی ہو گا نیک بختوں میں [۶۶]', 'And We gave him the glad tidings of Ishaque (Isaac) a Prophet from the righteous.', 'And We gave him the good news of IsHāq (Isaac), a prophet from among the righteous.'),
(3901, 37, 113, 3, 7, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ بٰرَکۡنَا عَلَیۡہِ وَ عَلٰۤی  اِسۡحٰقَ ؕ وَ مِنۡ ذُرِّیَّتِہِمَا مُحۡسِنٌ وَّ ظَالِمٌ لِّنَفۡسِہٖ مُبِیۡنٌ ﴿۱۱۳﴾٪', 'اور ہم نے ان پر اور اسحٰق پر برکتیں نازل کی تھیں۔ اور ان دونوں کی اولاد میں سے نیکوکار بھی ہیں اور اپنے آپ پر سراسر ظلم کرنے والے یعنی گناہگار بھی ہیں۔', 'اور برکت دی ہم نے اس پر اسحٰق پر اور دونوں کی اولاد میں نیکی والے ہیں اور بدکار بھی ہیں اپنے حق میں صریح [۶۷]', 'We blessed him and Ishaque (Isaac), and of their progeny are (some) that do right, and some that plainly wrong themselves.', 'And We did bless him, and IsHāq. And among the progeny of both of them, some are good and some are utterly unjust to their own selves.'),
(3902, 37, 114, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ لَقَدۡ مَنَنَّا عَلٰی مُوۡسٰی وَ ہٰرُوۡنَ ﴿۱۱۴﴾ۚ', 'اور ہم نے موسٰی اور ہارون پر بھی احسان کئے۔', 'اور ہم نے احسان کیا موسٰی اور ہارون پر', 'And, indeed We gave Our Grace to Moosa (Moses) and Haroon (Aaron).', 'Certainly We bestowed favors upon Mūsā and Hārūn,'),
(3903, 37, 115, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ نَجَّیۡنٰہُمَا وَ قَوۡمَہُمَا مِنَ الۡکَرۡبِ الۡعَظِیۡمِ  ﴿۱۱۵﴾ۚ', 'اور انکو اور انکی قوم کو بڑی مصیبت سے نجات بخشی۔', 'اور بچا دیا ہم نے انکو اور ان کی قوم کو اس بڑی گھبراہٹ سے [۶۸]', 'And We saved them and their people from the great distress;', 'and We delivered them and their people from the great agony,'),
(3904, 37, 116, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ نَصَرۡنٰہُمۡ فَکَانُوۡا ہُمُ الۡغٰلِبِیۡنَ ﴿۱۱۶﴾ۚ', 'اور انکی مدد کی تو وہی غالب رہے۔', 'اور انکی ہم نے مدد کی تو رہے وہی غالب [۶۹]', 'And helped them, so that they became the victors;', 'and We helped them, so they became victors,'),
(3905, 37, 117, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ اٰتَیۡنٰہُمَا الۡکِتٰبَ الۡمُسۡتَبِیۡنَ ﴿۱۱۷﴾ۚ', 'اور ہم نے ان دونوں کو کتاب واضح یعنی توریت عنایت کی۔', 'اور ہم نے دی انکو کتاب واضح [۷۰]', 'And We gave them the clear Scripture;', 'and We gave them the clear book,'),
(3906, 37, 118, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ ہَدَیۡنٰہُمَا الصِّرَاطَ الۡمُسۡتَقِیۡمَ ﴿۱۱۸﴾ۚ', 'اور انکو سیدھا رستہ دکھایا۔', 'اور سجھائی انکو سیدھی راہ [۷۱]', 'And guided them to the Right Path;', 'and guided them to the straight path.'),
(3907, 37, 119, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ تَرَکۡنَا عَلَیۡہِمَا فِی الۡاٰخِرِیۡنَ ﴿۱۱۹﴾ۙ', 'اور پیچھے آنے والوں میں ان کا ذکر خیر باقی رکھا۔', 'اور باقی رکھا ان پر پچھلے لوگوں میں کہ', 'And We left for them (a goodly remembrance) among generations (to come) in later times;', 'And We left for them (a word of praise) among the later people,'),
(3908, 37, 120, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'سَلٰمٌ  عَلٰی مُوۡسٰی وَ ہٰرُوۡنَ ﴿۱۲۰﴾', 'کہ موسٰی اور ہارون پر سلام۔', 'سلام ہے موسٰی اور ہارون پر', 'Salamun (peace) be upon Moosa (Moses) and Haroon (Aaron)!\"', '(that is,) Salām be on Mūsā and Hārūn!'),
(3909, 37, 121, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّا کَذٰلِکَ نَجۡزِی الۡمُحۡسِنِیۡنَ ﴿۱۲۱﴾', 'بیشک ہم نیکوکاروں کو ایسا ہی بدلہ دیا کرتے ہیں۔', 'ہم یوں دیتے ہیں بدلا نیکی کرنے  والوں کو', 'Verily, thus do We reward the Muhsinoon (good-doers - see V.2:112).', 'This is how We reward those who are good in their deeds.'),
(3910, 37, 122, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّہُمَا مِنۡ عِبَادِنَا الۡمُؤۡمِنِیۡنَ ﴿۱۲۲﴾', 'وہ دونوں ہمارے مومن بندوں میں سے تھے۔', 'تحقیق وہ دونوں ہیں ہمارے ایماندار بندوں میں [۷۲]', 'Verily! They were two of Our believing slaves.', 'Surely, both of them were among Our believing servants.'),
(3911, 37, 123, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ  اِنَّ  اِلۡیَاسَ لَمِنَ الۡمُرۡسَلِیۡنَ ﴿۱۲۳﴾ؕ', 'اور الیاس بھی پیغمبروں میں سے تھے۔', 'اور تحقیق الیاس ہے رسولوں میں', 'And verily, Iliyas (Elias) was one of the Messengers.', 'And surely, Ilyās is one of the messengers.'),
(3912, 37, 124, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِذۡ  قَالَ  لِقَوۡمِہٖۤ   اَلَا  تَتَّقُوۡنَ ﴿۱۲۴﴾', 'جب انہوں نے اپنی قوم سے کہا کہ تم ڈرتے کیوں نہیں۔', 'جب اس نے کہا اپنی قوم کو کیا تم کو ڈر نہیں', 'When he said to his people: \"Will you not fear Allah?', '(Remember) when he said to his people: “Do you not fear Allah?'),
(3913, 37, 125, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اَتَدۡعُوۡنَ بَعۡلًا وَّ تَذَرُوۡنَ  اَحۡسَنَ الۡخَالِقِیۡنَ ﴿۱۲۵﴾ۙ', 'کیا تم بعل کو پکارتے اور اسے پوجتے ہو اور سب سے بہتر پیدا کرنے والے کو چھوڑے دیتے ہو۔', 'کیا تم پکارتے ہو بعل کو اور چھوڑتے ہو بہتر بنانے والے کو [۷۳]', '\"Will you call upon Bal (a well- known idol of his nation whom they used to worship) and forsake the Best of creators,', 'Do you invoke Ba‘l, and ignore the Best of the creators,'),
(3914, 37, 126, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اللّٰہَ  رَبَّکُمۡ وَ رَبَّ اٰبَآئِکُمُ  الۡاَوَّلِیۡنَ ﴿۱۲۶﴾', 'یعنی اللہ کو جو تمہارا اور تمہارے پہلے باپ دادوں کا پروردگار ہے۔', 'جو اللہ ہے رب تمہارا اور رب تمہارے اگلے باپ دادوں کا [۷۴]', '\"Allah, your Lord and the Lord of your forefathers?\"', 'that is, Allah who is your Lord and the Lord of your forefathers?”'),
(3915, 37, 127, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَکَذَّبُوۡہُ  فَاِنَّہُمۡ  لَمُحۡضَرُوۡنَ ﴿۱۲۷﴾ۙ', 'تو ان لوگوں نے انکو یعنی الیاس کو جھٹلا دیا۔ سو وہ لوگ دوزخ میں حاضر کئے جائیں گے۔', 'پھر اس کو جھٹلایا سو وہ آنے والے ہیں پکڑے ہوئے [۷۵]', 'But they denied him (Iliyas (Elias)), so they will certainly be brought forth (to the punishment),', 'Then they rejected him. Therefore, they will be arraigned -'),
(3916, 37, 128, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِلَّا عِبَادَ  اللّٰہِ  الۡمُخۡلَصِیۡنَ ﴿۱۲۸﴾', 'ہاں اللہ کے چنے ہوئے بندے مبتلائے عذاب نہیں ہوں گے۔', 'مگر جو بندے ہیں اللہ کے چنے ہوئے [۷۶]', 'Except the chosen slaves of Allah.', 'except Allah’s chosen servants.'),
(3917, 37, 129, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ تَرَکۡنَا عَلَیۡہِ  فِی الۡاٰخِرِیۡنَ ﴿۱۲۹﴾ۙ', 'اور ان کا ذکر خیر بعد میں آنے والوں میں باقی رکھا۔', 'اور باقی رکھا ہم نے اس پر پچھلے لوگوں میں', 'And We left for him (a goodly remembrance) among generations (to come) in later times;', 'And We left for him (a word of praise) among the later people,'),
(3918, 37, 130, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'سَلٰمٌ  عَلٰۤی  اِلۡ یَاسِیۡنَ ﴿۱۳۰﴾', 'کہ الیاسین پر سلام ہو۔', 'کہ سلام ہے الیاس پر [۷۷]', 'Salamun (peace) be upon Ilyaseen (Elias)!\"', '(that is,) “Salām on Ilyāsīn (Ilyās).'),
(3919, 37, 131, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّا کَذٰلِکَ نَجۡزِی الۡمُحۡسِنِیۡنَ ﴿۱۳۱﴾', 'ہم نیک لوگوں کو ایسا ہی بدلہ دیتے ہیں۔', 'ہم یوں دیتے ہیں بدلا نیکی کرنے والوں کو', 'Verily, thus do We reward the Muhsinoon (good-doers, who perform good deeds totally for Allahs sake only - see V.2:112).', 'This is how We reward those who are good in their deeds.'),
(3920, 37, 132, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّہٗ  مِنۡ عِبَادِنَا الۡمُؤۡمِنِیۡنَ ﴿۱۳۲﴾', 'بیشک وہ ہمارے مومن بندوں میں سے تھے۔', 'وہ ہے ہمارے ایماندار بندوں میں', 'Verily, he was one of Our believing slaves.', 'Surely, he was from among Our believing servants.'),
(3921, 37, 133, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ  اِنَّ  لُوۡطًا لَّمِنَ الۡمُرۡسَلِیۡنَ ﴿۱۳۳﴾ؕ', 'اور لوط بھی پیغمبروں میں سے تھے۔', 'اور تحقیق لوط ہے رسولوں میں سے', 'And verily, Lout (Lot) was one of the Messengers.', 'And surely, LūT is one of the messengers.'),
(3922, 37, 134, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِذۡ  نَجَّیۡنٰہُ  وَ اَہۡلَہٗۤ   اَجۡمَعِیۡنَ ﴿۱۳۴﴾ۙ', 'جب ہم نے انکو اور انکے گھر والوں کو سب کو عذاب سے نجات دی۔', 'جب بچا دیا ہم نے اسکو اور اسکے سارے گھر والوں کو', 'When We saved him and his family, all,', '(Remember) when We saved him and his family, all of them,'),
(3923, 37, 135, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِلَّا  عَجُوۡزًا فِی الۡغٰبِرِیۡنَ ﴿۱۳۵﴾', 'مگر ایک بڑھیا کہ پیچھے رہ جانے والوں میں تھی۔', 'مگر ایک بڑھیا کہ رہ گئ رہ جانے  والوں میں [۷۸]', 'Except an old woman (his wife) who was among those who remained behind.', 'except an old woman among those remaining behind.'),
(3924, 37, 136, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'ثُمَّ  دَمَّرۡنَا الۡاٰخَرِیۡنَ ﴿۱۳۶﴾', 'پھر ہم نے اوروں کو ہلاک کر دیا۔', 'پھر جڑ سے اکھاڑ  پھینکا ہم نے دوسروں کو [۷۹]', 'Then We destroyed the rest (i.e. the towns of Sodom at the place of the Dead Sea (now) in Palestine). (See the \"Book of History\" by Ibn Katheer).', 'After that, We destroyed others'),
(3925, 37, 137, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ اِنَّکُمۡ لَتَمُرُّوۡنَ عَلَیۡہِمۡ مُّصۡبِحِیۡنَ ﴿۱۳۷﴾', 'اور تم دن کو بھی انکی بستیوں کے پاس سے گزرتے رہتے ہو۔', 'اور تم گذرتے ہو ان پر صبح کے وقت', 'Verily, you pass by them in the morning.', 'and you do pass by them at daybreak'),
(3926, 37, 138, 4, 8, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ  بِالَّیۡلِ ؕ اَفَلَا  تَعۡقِلُوۡنَ ﴿۱۳۸﴾٪', 'اور رات کو بھی۔ تو کیا تم عقل نہیں رکھتے؟', 'اور رات بھی پھر کیا نہیں سمجھتے [۸۰]', 'And at night; will you not then reflect?', 'and by nightfall. Would you still not understand?'),
(3927, 37, 139, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ  اِنَّ یُوۡنُسَ لَمِنَ الۡمُرۡسَلِیۡنَ ﴿۱۳۹﴾ؕ', 'اور یونس بھی پیغمبروں میں سے تھے۔', 'اور تحقیق یونس ہے رسولوں میں سے', 'And, verily, Yoonus (Jonah) was one of the Messengers.', 'And surely, Yūnus (Jonah) is from among the messengers.'),
(3928, 37, 140, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِذۡ   اَبَقَ  اِلَی الۡفُلۡکِ الۡمَشۡحُوۡنِ ﴿۱۴۰﴾ۙ', 'جب وہ بھاگ کر بھری ہوئی کشتی میں پہنچے۔', 'جب بھاگ کر پہنچا اس بھری کشتی پر', 'When he ran to the laden ship,', '(Remember) when he ran away towards the boat that was already loaded.'),
(3929, 37, 141, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَسَاہَمَ فَکَانَ مِنَ الۡمُدۡحَضِیۡنَ ﴿۱۴۱﴾ۚ', 'پھر انہوں نے قرعہ ڈلوایا تو ٹھہرے پھینکے جانے والے۔', 'قرعہ ڈلوایا تو نکلا خطاوار [۸۱]', 'He (agreed to) cast lots, and he was among the losers,', 'Then he participated in drawing lots (to offload one of the passengers) and was the one who was defeated.'),
(3930, 37, 142, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَالۡتَقَمَہُ  الۡحُوۡتُ وَ ہُوَ  مُلِیۡمٌ ﴿۱۴۲﴾', 'پھر مچھلی نے انکو نگل لیا جبکہ وہ اپنے آپکو ملامت کرنے والے تھے۔', 'پھر لقمہ کیا اس کو مچھلی نے اور وہ الزام کھایا ہوا تھا [۸۲]', 'Then a (big) fish swallowed him and he had done an act worthy of blame.', 'Then the fish swallowed him while he was reproaching his own self.'),
(3931, 37, 143, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَلَوۡ لَاۤ  اَنَّہٗ  کَانَ مِنَ الۡمُسَبِّحِیۡنَ ﴿۱۴۳﴾ۙ', 'پھر اگر وہ اللہ کی پاکی بیان نہ کر رہے ہوتے۔', 'پھر اگر نہ ہوتی یہ بات کہ وہ یاد کرتا تھا پاک ذات کو', 'Had he not been of them who glorify Allah,', 'Had he not been of those who proclaim Allah’s purity,'),
(3932, 37, 144, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'لَلَبِثَ فِیۡ  بَطۡنِہٖۤ  اِلٰی یَوۡمِ یُبۡعَثُوۡنَ ﴿۱۴۴﴾ۚؒ', 'تو اس روز تک کہ لوگ دوبارہ زندہ کئے جائیں گے اسی کے پیٹ میں رہتے۔', 'تو رہتا اسی کے پیٹ میں جس دن تک مردے زندہ ہوں [۸۳]', 'He would have indeed remained inside its belly (the fish) till the Day of Resurrection.', 'he would have definitely lived in its belly till the day when the dead will be raised.'),
(3933, 37, 145, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَنَبَذۡنٰہُ  بِالۡعَرَآءِ  وَ  ہُوَ  سَقِیۡمٌ ﴿۱۴۵﴾ۚ', 'پھر ہم نے انکو جب کہ وہ بیمار تھے چٹیل میدان میں ڈالدیا۔', 'پھر ڈال دیا ہم نے اس کو چٹیل میدان میں اور وہ بیمار تھا', 'But We cast him forth on the naked shore while he was sick,', 'Then We cast him ashore in the open while he was ill,'),
(3934, 37, 146, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ اَنۡۢبَتۡنَا عَلَیۡہِ شَجَرَۃً مِّنۡ یَّقۡطِیۡنٍ ﴿۱۴۶﴾ۚ', 'اور ان پر کدو کی بیل اگا دی۔', 'اور اگایا ہم نے اس پر ایک درخت بیل والا [۸۴]', 'And We caused a plant of gourd to grow over him.', 'and We caused a tree of ourds to grow over him.'),
(3935, 37, 147, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ اَرۡسَلۡنٰہُ  اِلٰی مِائَۃِ  اَلۡفٍ اَوۡ یَزِیۡدُوۡنَ ﴿۱۴۷﴾ۚ', 'اور انکو ایک لاکھ یا اس سے زیادہ لوگوں کی طرف پیغمبر بنا کر بھیجا۔', 'اور بھیجا اس کو لاکھ آدمیوں پر یا اس سے زیادہ [۸۵]', 'And We sent him to a hundred thousand (people) or even more.', 'And We had sent him (as messenger) to one hundred thousand, or more.'),
(3936, 37, 148, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَاٰمَنُوۡا  فَمَتَّعۡنٰہُمۡ   اِلٰی حِیۡنٍ ﴿۱۴۸﴾ؕ', 'تو وہ ایمان لے آئے سو ہم بھی انکو دنیا میں ایک وقت مقرر تک فائدے دیتے رہے۔', 'پھر وہ یقین لائے پھر ہم نے فائدہ اٹھانے دیا انکو ایک وقت تک [۸۶]', 'And they believed; so We gave them enjoyment for a while.', 'So, they believed, then, We let them enjoy for a time.'),
(3937, 37, 149, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَاسۡتَفۡتِہِمۡ  اَلِرَبِّکَ الۡبَنَاتُ وَ لَہُمُ الۡبَنُوۡنَ ﴿۱۴۹﴾ۙ', 'ان سے پوچھو تو بھلا تمہارے پروردگار کے لئے تو بیٹیاں ہوں اور انکے لئے بیٹے۔', 'اب ان سے پوچھ کیا تیرے رب کے  یہاں بیٹیاں ہیں اور انکے یہاں بیٹے', 'Now ask them (O Muhammad SAW): \"Are there (only) daughters for your Lord and sons for them?\"', 'So ask them, “Does your Lord have daughters while they have sons?”'),
(3938, 37, 150, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اَمۡ خَلَقۡنَا الۡمَلٰٓئِکَۃَ  اِنَاثًا  وَّ ہُمۡ شٰہِدُوۡنَ ﴿۱۵۰﴾', 'یا ہم نے فرشتوں کو عورتیں بنایا اور یہ اس وقت دیکھ رہے تھے۔', 'یا ہم نے بنایا فرشتوں کو عورت اور  وہ دیکھتے تھے', 'Or did We create the angels females while they were witnesses?', 'Or, had We created angels as females while they were witnessing?'),
(3939, 37, 151, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اَلَاۤ  اِنَّہُمۡ  مِّنۡ  اِفۡکِہِمۡ  لَیَقُوۡلُوۡنَ ﴿۱۵۱﴾ۙ', 'دیکھو یہ اپنی جھوٹ بنائی ہوئی بات کہتے ہیں۔', 'سنتا ہے وہ اپنا جھوٹ بنایا کہتے ہیں کہ', 'Verily, it is of their falsehood that they (Quraish pagans) say:', 'Beware! They are the ones who, by way of a lie of theirs, (have the audacity to) say,'),
(3940, 37, 152, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَلَدَ اللّٰہُ ۙ وَ  اِنَّہُمۡ  لَکٰذِبُوۡنَ ﴿۱۵۲﴾', 'کہ اللہ کے اولاد ہے حالانکہ یہ جھوٹے ہیں۔', 'اللہ کے اولاد ہوئی اور وہ بیشک جھوٹے ہیں [۸۷]', '\"Allah has begotten off spring or children (i.e. angels are the daughters of Allah)?\" And, verily, they are liars!', '“Allah has children” - and they are absolute liars.'),
(3941, 37, 153, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اَصۡطَفَی الۡبَنَاتِ عَلَی الۡبَنِیۡنَ ﴿۱۵۳﴾ؕ', 'کیا اس نے بیٹوں کے مقابلے میں بیٹیوں کو پسند کیا ہے؟', 'کیا اس نے پسند کیں بیٹیاں بیٹوں سے', 'Has He (then) chosen daughters rather than sons?', 'Is it that Allah has chosen daughters (for Himself) instead of sons?'),
(3942, 37, 154, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'مَا  لَکُمۡ ۟  کَیۡفَ تَحۡکُمُوۡنَ ﴿۱۵۴﴾', 'تم کیسے لوگ ہو کس طرح کا فیصلہ کرتے ہو۔', 'کیا ہو گیا ہے تم کو کیسا انصاف کرتے ہو', 'What is the matter with you? How do you decide?', 'What is the matter with you? How (arbitrarily) do you judge?'),
(3943, 37, 155, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اَفَلَا  تَذَکَّرُوۡنَ ﴿۱۵۵﴾ۚ', 'بھلا تم غور کیوں نہیں کرتے۔', 'کیا تم دھیان نہیں کرتے ہو [۸۸]', 'Will you not then remember?', 'Then, is it that you do not think about it?'),
(3944, 37, 156, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اَمۡ  لَکُمۡ  سُلۡطٰنٌ  مُّبِیۡنٌ ﴿۱۵۶﴾ۙ', 'یا تمہارے پاس کوئی واضح دلیل ہے۔', 'یا تمہارے پاس کوئی سند ہے کھلی', 'Or is there for you a plain authority?', 'Or, is it that there is some open authority with you?'),
(3945, 37, 157, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَاۡتُوۡا بِکِتٰبِکُمۡ  اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ ﴿۱۵۷﴾', 'اگر تم سچے ہو تو اپنی کتاب پیش کرو۔', 'تو لاؤ اپنی کتاب اگر ہو تم سچے [۸۹]', 'Then bring your Book if you are truthful!', 'Then bring your book, if you are truthful.'),
(3946, 37, 158, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ جَعَلُوۡا بَیۡنَہٗ  وَ بَیۡنَ الۡجِنَّۃِ  نَسَبًا ؕ وَ لَقَدۡ عَلِمَتِ الۡجِنَّۃُ  اِنَّہُمۡ لَمُحۡضَرُوۡنَ ﴿۱۵۸﴾ۙ', 'اور انہوں نے اللہ میں اور جنوں میں رشتہ ٹھہرا دیا حالانکہ جنات جانتے ہیں کہ وہ اللہ کے سامنے حاضر کئے جائیں گے۔', 'اور ٹھہرایا انہوں نے خدا میں اور جنوں میں ناتاا ور جنوں کو تو معلوم ہے کہ تحقیق و پکڑے ہوئے آئیں گے', 'And they have invented a kinship between Him and the jinns, but the jinns know well that they have indeed to appear (before Him) (i.e. they will be brought for accounts).', 'And they have made up between Him (Allah) and the Jinns some kinship, while the Jinns already know that they are bound to be seized.-'),
(3947, 37, 159, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'سُبۡحٰنَ اللّٰہِ عَمَّا یَصِفُوۡنَ ﴿۱۵۹﴾ۙ', 'یہ جو کچھ بیان کرتے ہیں اللہ اس سے پاک ہے۔', 'اللہ پاک ہے ان باتوں سے جو یہ بتاتے ہیں [۹۰]', 'Glorified is Allah! (He is Free) from what they attribute unto Him!', '-Pure is Allah from what they describe-'),
(3948, 37, 160, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِلَّا عِبَادَ  اللّٰہِ  الۡمُخۡلَصِیۡنَ ﴿۱۶۰﴾', 'مگر اللہ کے چنے ہوئے بندے مبتلائے عذاب نہیں ہوں گے۔', 'مگر جو بندے ہیں اللہ کے چنے ہوئے [۹۱]', 'Except the slaves of Allah, whom He choses (for His Mercy i.e. true believers of Islamic Monotheism who do not attribute false things unto Allah).', 'except Allah’s chosen servants.'),
(3949, 37, 161, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَاِنَّکُمۡ  وَ مَا  تَعۡبُدُوۡنَ ﴿۱۶۱﴾ۙ', 'سو تم لوگ اور جنکو تم پوجتے ہو۔', 'سو تم اور جن کو تم پوجتے ہو', 'So, verily you (pagans) and those whom you worship (idols).', 'So, you and those whom you worship,'),
(3950, 37, 162, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'مَاۤ   اَنۡتُمۡ  عَلَیۡہِ  بِفٰتِنِیۡنَ ﴿۱۶۲﴾ۙ', 'اللہ کے خلاف کسی کو بہکا نہیں سکتے۔', 'کسی کو اس کے ہاتھ سے بہکا کر نہیں لے سکتے', 'Cannot lead astray (turn away from Him (Allah) anyone of the believers),', 'none of you can make anyone turn away from Him (Allah),'),
(3951, 37, 163, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِلَّا  مَنۡ  ہُوَ  صَالِ الۡجَحِیۡمِ ﴿۱۶۳﴾', 'مگر اسی کو جو جہنم میں جانے والا ہے۔', 'مگر اسی کو جو پہنچے والا ہے دوزخ میں [۹۲]', 'Except those who are predestined to burn in Hell!', 'except him who is to burn in Jahannam.'),
(3952, 37, 164, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ مَا مِنَّاۤ   اِلَّا  لَہٗ  مَقَامٌ  مَّعۡلُوۡمٌ ﴿۱۶۴﴾ۙ', 'اور فرشتے کہتے ہیں کہ ہم میں سے ہر ایک کا ایک مقام مقرر ہے۔', 'اور ہم میں جو ہے اس کا یک ٹھکانا ہے مقرر [۹۳]', 'There is not one of us (angels) but has his known place (or position);', 'And (the angels say,) “There is no one among us who does not have a known station,'),
(3953, 37, 165, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَّ  اِنَّا  لَنَحۡنُ الصَّآفُّوۡنَ ﴿۱۶۵﴾ۚ', 'اور ہم صف باندھے رہتے ہیں۔', 'اور ہم ہی ہیں صف باندھنے والے [۹۴]', 'Verily, we (angels), we stand in rows for the prayers (as you Muslims stand in rows for your prayers);', 'and We, surely We, are those who stand in rows'),
(3954, 37, 166, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ  اِنَّا لَنَحۡنُ الۡمُسَبِّحُوۡنَ ﴿۱۶۶﴾', 'اور ہم تسبیح کرتے رہتے ہیں۔', 'اور ہم ہی ہیں پاکی بیان کرنے والے [۹۵]', 'Verily, we (angels), we are they who glorify (Allahs Praises i.e. perform prayers).', 'and We, surely We, are those who proclaim Allah’s purity.”'),
(3955, 37, 167, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ  اِنۡ  کَانُوۡا  لَیَقُوۡلُوۡنَ ﴿۱۶۷﴾ۙ', 'اور یہ لوگ کہا کرتے تھے۔', 'اور یہ تو کہا کرتے تھے', 'And indeed they (Arab pagans) used to say;', 'And they (the pagans) used to say,'),
(3956, 37, 168, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'لَوۡ  اَنَّ عِنۡدَنَا ذِکۡرًا  مِّنَ الۡاَوَّلِیۡنَ ﴿۱۶۸﴾ۙ', 'کہ اگر ہمارے پاس اگلوں کی کوئی نصیحت کی کتاب ہوتی۔', 'اگر ہمارے پاس کچھ احوال ہوتا پہلے لوگوں کا', '\"If we had a reminder as had the men of old (before the coming of Prophet Muhammad SAW as a Messenger of Allah).', '“Had there been a scripture with us like that of the former people,'),
(3957, 37, 169, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'لَکُنَّا عِبَادَ اللّٰہِ الۡمُخۡلَصِیۡنَ ﴿۱۶۹﴾', 'تو ہم اللہ کے چنے ہوئے بندے ہوتے۔', 'تو ہم ہوتے بندے اللہ کے چنے ہوئے', '\"We would have indeed been the chosen slaves of Allah (true believers of Islamic Monotheism)!\"', 'we would have certainly been Allah’s chosen servants.”'),
(3958, 37, 170, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَکَفَرُوۡا بِہٖ فَسَوۡفَ یَعۡلَمُوۡنَ  ﴿۱۷۰﴾', 'پھر اس سے کفر کرتے رہے سو عنقریب انکو اس کا نتیجہ معلوم ہو جائے گا۔', 'سو اس سے منکر ہو گئے اب آگے جان لیں گے [۹۶]', 'But (now that the Quran has come) they disbelieve therein (i.e. in the Quran and in Prophet Muhammad SAW , and all that which he brought, the Divine Revelation), so they will come to know!', 'Then (once the divine book came to them,) they disbelieved in it. So, very soon they will come to know.'),
(3959, 37, 171, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ لَقَدۡ سَبَقَتۡ کَلِمَتُنَا لِعِبَادِنَا الۡمُرۡسَلِیۡنَ ﴿۱۷۱﴾ۚۖ', 'اور اپنے پیغام پہنچانے والے بندوں سے ہمارا وعدہ ہو چکا ہے۔', 'اور پہلے ہو چکا ہمارا حکم اپنے بندوں کے حق میں جو کہ رسول ہیں', 'And, verily, Our Word has gone forth of old for Our slaves, the Messengers,', 'And Our Word has already come to pass in favor of Our servants, the messengers'),
(3960, 37, 172, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اِنَّہُمۡ  لَہُمُ  الۡمَنۡصُوۡرُوۡنَ ﴿۱۷۲﴾۪', 'کہ وہی مظفر و منصور ہوں گے۔', 'بیشک انہی کو مدد دیجاتی ہے', 'That they verily would be made triumphant.', '(that) they are the ones who will be supported,'),
(3961, 37, 173, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ  اِنَّ جُنۡدَنَا لَہُمُ  الۡغٰلِبُوۡنَ ﴿۱۷۳﴾', 'اور ہمارا لشکر ہی غالب رہے گا۔', 'اور ہمارا لشکر جو ہے بیشک وہی کے غالب ہے[۹۷]', 'And that Our hosts, they verily would be the victors.', 'and verily it is Our army (of chosen servants) that prevails.'),
(3962, 37, 174, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَتَوَلَّ عَنۡہُمۡ حَتّٰی حِیۡنٍ ﴿۱۷۴﴾ۙ', 'تو ایک وقت تک ان سے منہ پھیرے رہو۔', 'سو تو ان سے پھر آ ایک وقت تک', 'So turn away (O Muhammad SAW) from them for a while,', 'So, withdraw your attention from them for some time.'),
(3963, 37, 175, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَّ اَبۡصِرۡہُمۡ فَسَوۡفَ یُبۡصِرُوۡنَ ﴿۱۷۵﴾', 'اور انہیں دیکھتے رہو۔ یہ بھی عنقریب کفر کا انجام دیکھ لیں گے۔', 'اور انکو دیکھتا رہ کہ وہ آگے دیکھ لیں گے [۹۸]', 'And watch them and they shall see (the punishment)!', 'But, watch them. They shall soon see (the reality).'),
(3964, 37, 176, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'اَفَبِعَذَابِنَا یَسۡتَعۡجِلُوۡنَ ﴿۱۷۶﴾', 'کیا یہ ہمارے عذاب کے لئے جلدی کر رہے ہیں۔', 'کیا ہماری آفت کو جلد مانگتے ہیں', 'Do they seek to hasten on Our Torment?', 'Are they asking for Our punishment to come sooner?'),
(3965, 37, 177, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'فَاِذَا نَزَلَ بِسَاحَتِہِمۡ فَسَآءَ صَبَاحُ الۡمُنۡذَرِیۡنَ ﴿۱۷۷﴾', 'مگر جب وہ انکے آنگن میں آ اترے گا تو جنکو ڈر سنایا گیا تھا انکے لئے برا دن ہو گا۔', 'پھر جب اترے گی ان کے میدان میں تو بری صبح ہو گی ڈرائے ہوؤں کی [۹۹]', 'Then, when it descends into their courtyard (i.e. near to them), evil will be the morning for those who had been warned!', 'So, when it will descend in their courtyard, then, evil will be the morning of those warned.'),
(3966, 37, 178, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ تَوَلَّ عَنۡہُمۡ حَتّٰی حِیۡنٍ ﴿۱۷۸﴾ۙ', 'اور ایک وقت تک ان سے منہ پھیرے رہو۔', 'اور پھر  آ ان سے ایک وقت تک', 'So turn (O Muhammad SAW) away from them for a while,', 'So, withdraw your attention from them for some time,'),
(3967, 37, 179, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَّ  اَبۡصِرۡ  فَسَوۡفَ یُبۡصِرُوۡنَ ﴿۱۷۹﴾', 'اور دیکھتے رہو یہ بھی عنقریب نتیجہ دیکھ لیں گے۔', 'اور دیکھتا رہ اب آگے دیکھ لیں گے [۱۰۰]', 'And watch and they shall see (the torment)!', 'and watch. They shall soon see (the reality).'),
(3968, 37, 180, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'سُبۡحٰنَ رَبِّکَ رَبِّ الۡعِزَّۃِ عَمَّا یَصِفُوۡنَ ﴿۱۸۰﴾ۚ', 'یہ جو کچھ بیان کرتے ہیں تمہارا پروردگار جو صاحب عزت ہے اس سے پاک ہے۔', 'پاک ذات ہے تیرے رب کی وہ پروردگار عزت والا پاک ہے ان باتوں سے جو  بیان کرتےہیں', 'Glorified be your Lord, the Lord of Honour and Power! (He is free) from what they attribute unto Him!', 'Pure is your Lord, the Lord of all might and honor, from what they describe'),
(3969, 37, 181, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ  سَلٰمٌ  عَلَی  الۡمُرۡسَلِیۡنَ ﴿۱۸۱﴾ۚ', 'اور پیغمبروں پر سلام۔', 'اور سلام ہے رسولوں پر', 'And peace be on the Messengers!', 'and Salām be on the messengers'),
(3970, 37, 182, 5, 9, 23, 'وَ مَا لِیَ ', 'الصّٰفّٰت', 'وَ الۡحَمۡدُ  لِلّٰہِ  رَبِّ الۡعٰلَمِیۡنَ ﴿۱۸۲﴾٪', 'اور سب طرح کی تعریف اللہ رب العالمین کیلئے ہے۔', 'اور سب خوبی ہے اللہ کو جو رب ہے سارے جہان کا [۱۰۱]', 'And all the praise and thanks be to Allah, Lord of the Alameen (mankind, jinns and all that exists).', 'and praised is Allah, the Lord of all the worlds.'),
(3971, 38, 1, 1, 10, 23, 'وَ مَا لِیَ ', 'صٓ', 'صٓ  وَ  الۡقُرۡاٰنِ  ذِی  الذِّکۡرِ ؕ﴿۱﴾', 'ص۔ قسم ہے قرآن کی جو نصیحت سے پر ہے کہ تم حق پر ہو۔', 'ص۔قسم ہے اُس قرآن سمجھانے والے کی', 'Sad (These letters (Sad etc.) are one of the miracles of the Quran and none but Allah (Alone) knows their meanings). By the Quran full of reminding.', 'Sād . I swear by the Qur’ān, (the book) containing advice, (this is true,)'),
(3972, 38, 2, 1, 10, 23, 'وَ مَا لِیَ ', 'صٓ', 'بَلِ  الَّذِیۡنَ   کَفَرُوۡا فِیۡ عِزَّۃٍ   وَّ  شِقَاقٍ ﴿۲﴾', 'مگر جو لوگ کافر ہیں وہ غرور اور مخالفت میں پڑے ہیں۔', 'بلکہ جو لوگ منکر  ہیں غرور میں ہیں اور مقابلہ میں [۱]', 'Nay, those who desbelieve are in false pride and opposition.', 'but those who disbelieve are (involved) in false pride and opposition.'),
(3973, 38, 3, 1, 10, 23, 'وَ مَا لِیَ ', 'صٓ', 'کَمۡ  اَہۡلَکۡنَا مِنۡ قَبۡلِہِمۡ مِّنۡ قَرۡنٍ فَنَادَوۡا  وَّ  لَاتَ حِیۡنَ مَنَاصٍ ﴿۳﴾', 'ہم نے ان سے پہلے بہت سی امتوں کو ہلاک کر دیا تو وہ عذاب کے وقت لگے فریاد کرنے اور وہ چھٹکارے کا وقت نہیں تھا۔', 'بہت غارت کر دیں ہم نے ان سے پہلے جماعتیں پھر لگے پکارنے اور وقت نہ رہا تھا خلاصی کا [۲]', 'How many a generation We have destroyed before them, and they cried out when there was no longer time for escape!', 'How many a generation have We destroyed before them, so they cried out (for mercy), while no time was left for having any refuge.'),
(3974, 38, 4, 1, 10, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ عَجِبُوۡۤا اَنۡ جَآءَہُمۡ مُّنۡذِرٌ مِّنۡہُمۡ ۫ وَ قَالَ  الۡکٰفِرُوۡنَ ہٰذَا سٰحِرٌ کَذَّابٌ ۖ﴿ۚ۴﴾', 'اور انہوں نے تعجب کیا کہ انکے پاس ان ہی میں سے ایک خبردار کرنے والا آیا اور کافر کہنے لگے کہ یہ تو جادوگر ہے جھوٹا۔', 'اور تعجب کرنے لگے اس بات پر کہ آیا ان کے پاس ایک ڈر سنانے والا انہی میں سے اور کہنے لگے منکر یہ جادوگر ہے جھوٹا [۳]', 'And they (Arab pagans) wonder that a warner (Prophet Muhammad SAW) has come to them from among themselves! And the disbelievers say: \"This (Prophet Muhammad SAW) is a sorcerer, a liar.', 'They (the pagans) wonder that a warner has come to them from among themselves. And the disbelievers say, “This is a magician, a sheer liar.'),
(3975, 38, 5, 1, 10, 23, 'وَ مَا لِیَ ', 'صٓ', 'اَجَعَلَ  الۡاٰلِہَۃَ  اِلٰـہًا وَّاحِدًا ۚۖ اِنَّ ہٰذَا  لَشَیۡءٌ  عُجَابٌ ﴿۵﴾', 'کیا اس نے اتنے معبودوں کی جگہ ایک ہی معبود قرار دے دیا؟ یہ تو بڑی عجیب بات ہے۔', 'کیا اس نے کر دی اتنوں کی بندگی کے بدلے ایک ہی کی بندگی یہ بھی ہے بڑے تعجب کی بات', '\"Has he made the aliha (gods) (all) into One Ilah (God - Allah). Verily, this is a curious thing!\"', 'Has he (not) turned all the gods into a single God? It is a very strange thing indeed.”'),
(3976, 38, 6, 1, 10, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ انۡطَلَقَ الۡمَلَاُ مِنۡہُمۡ  اَنِ امۡشُوۡا وَ اصۡبِرُوۡا عَلٰۤی  اٰلِہَتِکُمۡ ۚۖ اِنَّ ہٰذَا لَشَیۡءٌ  یُّرَادُ ۖ﴿ۚ۶﴾', 'اور ان میں جو معزز تھے وہ چل کھڑے ہوئے اور بولے کہ چلو اور اپنے معبودوں کی پوجا پر قائم رہو۔ بیشک یہ ایسی بات ہے جس میں کوئی خاص غرض ہے۔', 'اور چل کھڑےہوئے کئ پنچ ان میں سے کہ چلو اور جمے رہو  اپنے معبودوں پر [۴] بیشک اس بات میں کوئی غرض ہے [۵]', 'And the leaders among them went about (saying): \"Go on, and remain constant to your aliha (gods)! Verily, This is a thing designed (against you)!', 'And the leaders among them walked out saying (to their followers), “Walk away (from the Prophet,) and stay firm on (adhering to) your gods. This (call of the Prophet) is surely something designed (for his personal benefit).'),
(3977, 38, 7, 1, 10, 23, 'وَ مَا لِیَ ', 'صٓ', 'مَا سَمِعۡنَا بِہٰذَا فِی الۡمِلَّۃِ  الۡاٰخِرَۃِ ۚۖ اِنۡ ہٰذَاۤ   اِلَّا  اخۡتِلَاقٌ ۖ﴿ۚ۷﴾', 'یہ بات کسی دوسرے مذہب میں ہم نے کبھی سنی ہی نہیں۔ یہ تو بالکل گھڑی ہوئی بات ہے۔', 'یہ نہیں سنا ہم نے اس پچھلے دین میں اور کچھ نہیں یہ بنائی ہوئی بات ہے [۶]', '\"We have not heard (the like) of this among the people of these later days. This is nothing but an invention!', 'We never heard of it in the classical faith (of ours). This is nothing but a false invention.'),
(3978, 38, 8, 1, 10, 23, 'وَ مَا لِیَ ', 'صٓ', 'ءَ اُنۡزِلَ عَلَیۡہِ الذِّکۡرُ مِنۡۢ بَیۡنِنَا ؕ بَلۡ ہُمۡ فِیۡ شَکٍّ مِّنۡ ذِکۡرِیۡ ۚ بَلۡ  لَّمَّا یَذُوۡقُوۡا عَذَابِ ؕ﴿۸﴾', 'کیا ہم سب میں سے اسی پر نصیحت کی کتاب اتری ہے؟ اصل بات یہ ہے کہ یہ لوگ میری نصیحت کی طرف سے شک میں ہیں۔ بلکہ انہوں نے ابھی میرے عذاب کا مزہ نہیں چکھا۔', 'کیا اسی پر اتری نصیحت ہم سب میں سے [۷] کوئی  نہیں ان کو دھوکا ہے میری نصیحت میں کوئی نہیں ابھی انہوں نے چکھی نہیں میری مار [۸]', '\"Has the Reminder been sent down to him (alone) from among us?\" Nay! but they are in doubt about My Reminder (this Quran)! Nay, but they have not tasted (My) Torment!', 'Is it (believable) that the message of advice has been sent down to him (alone) from among all of us?” The fact is that they are in doubt about My message; rather, they have not yet tasted My punishment.'),
(3979, 38, 9, 1, 10, 23, 'وَ مَا لِیَ ', 'صٓ', 'اَمۡ عِنۡدَہُمۡ  خَزَآئِنُ رَحۡمَۃِ  رَبِّکَ الۡعَزِیۡزِ  الۡوَہَّابِ  ۚ﴿۹﴾', 'کیا انکے پاس تمہارے پروردگار کی رحمت کے خزانے ہیں جو غالب ہے سب کچھ عطا کرنے والا ہے۔', 'کیا ان کے پا س ہیں خزانے تیرے رب کی مہربانی کے جو کہ زبردست ہے بخشنے والا', 'Or have they the treasures of the Mercy of your Lord, the All-Mighty, the Real Bestower?', 'Do they have the treasures of the mercy of your Lord, the Mighty, the Bountiful?'),
(3980, 38, 10, 1, 10, 23, 'وَ مَا لِیَ ', 'صٓ', 'اَمۡ  لَہُمۡ  مُّلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ مَا بَیۡنَہُمَا ۟ فَلۡیَرۡتَقُوۡا فِی الۡاَسۡبَابِ ﴿۱۰﴾', 'یا آسمانوں اور زمین اور جو کچھ ان میں ہے ان سب پر ان ہی کی حکومت ہے۔ تو چاہیئے کہ رسیاں تان کر آسمانوں پر چڑھ جائیں۔', 'یا ان کی حکومت ہے آسمانوں میں اور زمین میں اورجو کچھ ان کے بیچ میں ہے تو انکو چاہئے کہ چڑھ جائیں رسیاں تان کر [۹]', 'Or is it that the dominion of the heavens and the earth and all that is between them is theirs? If so, let them ascend up with means (to the heavens)!', 'Or do they have the ownership of the heavens and the earth and what lies between them? Then let them ascend (to the sky) by ropes.'),
(3981, 38, 11, 1, 10, 23, 'وَ مَا لِیَ ', 'صٓ', 'جُنۡدٌ مَّا ہُنَالِکَ مَہۡزُوۡمٌ مِّنَ الۡاَحۡزَابِ ﴿۱۱﴾', 'یہاں شکست کھائے ہوئے گروہوں میں سے یہ بھی ایک لشکر ہے۔', 'ایک لشکر یہ بھی وہاں تباہ ہوا ان سب لشکروں میں [۱۰]', '(As they denied Allahs Message) they will be a defeated host like the confederates of the old times (who were defeated).', 'What is there (in Makkah) is just a host of the (opposing) groups that has to be defeated.'),
(3982, 38, 12, 1, 10, 23, 'وَ مَا لِیَ ', 'صٓ', 'کَذَّبَتۡ قَبۡلَہُمۡ قَوۡمُ نُوۡحٍ وَّ عَادٌ وَّ فِرۡعَوۡنُ  ذُو الۡاَوۡتَادِ ﴿ۙ۱۲﴾', 'ان سے پہلے نوح  کی قوم اور عاد اور میخوں والا فرعون بھی جھٹلا چکے ہیں۔', 'جھٹلا چکے ہیں ان سے پہلے نوح کی قوم اور عاد اور فرعون میخوں والا [۱۱]', 'Before them (were many who) belied Messengers, the people of Nooh (Noah); and Ad; and Firaun (Pharaoh) the man of stakes (with which he used to punish the people),', 'Even before them, the people of NūH and ‘Ād and Fir‘aun (Pharaoh), the man of stakes,'),
(3983, 38, 13, 1, 10, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ ثَمُوۡدُ وَ قَوۡمُ لُوۡطٍ وَّ اَصۡحٰبُ  لۡـَٔیۡکَۃِ ؕ اُولٰٓئِکَ  الۡاَحۡزَابُ ﴿۱۳﴾', 'اور ثمود اور لوط کی قوم اور بن کے رہنے والے بھی۔ یہی وہ شکست خوردہ گروہ ہیں۔', 'اور ثمود اور لوط کی قوم اور  ایکہ کے لوگ [۱۲] وہ بڑی بڑی فوجیں', 'And Thamood, and the people of Lout (Lot), and the dwellers of the wood; such were the confederates.', 'and Thamūd and the people of LūT and the people of Aaikah have rejected (the messengers). They were the (strong) groups.'),
(3984, 38, 14, 1, 10, 23, 'وَ مَا لِیَ ', 'صٓ', 'اِنۡ کُلٌّ   اِلَّا کَذَّبَ الرُّسُلَ فَحَقَّ عِقَابِ ﴿٪۱۴﴾', 'ان سب نے پیغمبروں کو جھٹلایا تو میرا عذاب ان پر آ واقع ہوا۔', 'یہ جتنے تھے سب نے یہی کیاکہ جھٹلایا رسولوں کو پھر ثابت ہوئی میرے طرف سے سزا [۱۳]', 'Not one of them but belied the Messengers, therefore My Torment was justified,', 'All of them did nothing but declare the messengers as liars; hence, My punishment became due.'),
(3985, 38, 15, 2, 11, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ مَا یَنۡظُرُ ہٰۤؤُلَآءِ  اِلَّا صَیۡحَۃً  وَّاحِدَۃً مَّا لَہَا مِنۡ  فَوَاقٍ ﴿۱۵﴾', 'اور یہ لوگ تو صرف ایک زور کی آواز کا جس میں شروع ہونے کے بعد کچھ وقفہ نہیں ہو گا انتظار کرتے ہیں۔', 'اور راہ نہیں دیکھتے یہ لوگ مگر ایک چنگھاڑ کی جو بیچ میں دم نہ لے گی [۱۴]', 'And these only wait for a single Saihah (shout (i.e. the blowing of the Trumpet by the angel Israfil Sarafil)) there will be no pause or ending thereto (till everything will perish except Allah (the only God full of Majesty, Bounty and Honour)).', 'And these people are waiting for nothing but for a single Cry (the sound of the Trumpet to be blown on Doomsday) that will have no pause.'),
(3986, 38, 16, 2, 11, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ قَالُوۡا رَبَّنَا عَجِّلۡ  لَّنَا قِطَّنَا قَبۡلَ یَوۡمِ  الۡحِسَابِ ﴿۱۶﴾', 'اور کہتے ہیں کہ اے ہمارے پروردگار ہمکو ہمارا حصہ جلدی سے حساب کے دن سے پہلے ہی دیدے۔', 'اور کہتے ہیں اے رب جلد دے ہم کو چھٹی ہماری پہلے حساب کے دن سے [۱۵]', 'They say: \"Our Lord! Hasten to us Qittana (i.e. our Record of good and bad deeds so that we see it) before the Day of Reckoning!\"', 'And they say, “O our Lord, give us our share (of the punishment) sooner, before the Day of Reckoning.”'),
(3987, 38, 17, 2, 11, 23, 'وَ مَا لِیَ ', 'صٓ', 'اِصۡبِرۡ عَلٰی مَا یَقُوۡلُوۡنَ وَ اذۡکُرۡ عَبۡدَنَا دَاوٗدَ   ذَا  الۡاَیۡدِ ۚ اِنَّہٗۤ   اَوَّابٌ ﴿۱۷﴾', 'اے پیغمبر ﷺ یہ جو کچھ کہتے ہیں اس پر صبر کرو۔ اور ہمارے بندے داؤد  کو یاد کرو جو صاحب قوت تھے بیشک وہ رجوع کرنے والے تھے۔', 'تو تحمل کرتا رہ اس پر جو وہ کہتے ہیں اور یاد کر ہمارے بندے داؤد قوت والے کو وہ تھا رجوع رہنے والا [۱۶]', 'Be patient (O Muhammad SAW) of what they say, and remember Our slave Dawood (David), endued with power. Verily, he was ever oft-returning in all matters and in repentance (toward Allah).', 'Bear patiently with what they say, and remember Our servant Dawūd, the man of might. Surely he was ever-turning to Allah.'),
(3988, 38, 18, 2, 11, 23, 'وَ مَا لِیَ ', 'صٓ', 'اِنَّا سَخَّرۡنَا الۡجِبَالَ مَعَہٗ یُسَبِّحۡنَ بِالۡعَشِیِّ  وَ  الۡاِشۡرَاقِ ﴿ۙ۱۸﴾', 'ہم نے پہاڑوں کو انکے زیرفرمان کر دیا تھا کہ صبح و شام انکے ساتھ تسبیح کرتے تھے۔', 'ہم نے تابع کیے پہاڑ اس کےساتھ پاکی بولتے تھے شام کو اور صبح کو [۱۷]', 'Verily, We made the mountains to glorify Our Praises with him (Dawood (David)) in the Ashi (i.e. after the mid-day till sunset) and Ishraq (i.e. after the sunrise till mid-day).', 'We had subjugated the mountains to join him (in) making tasbīH (i.e. pronouncing Allah’s purity) at evening and sunrise,'),
(3989, 38, 19, 2, 11, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ الطَّیۡرَ  مَحۡشُوۡرَۃً ؕ کُلٌّ   لَّہٗۤ   اَوَّابٌ ﴿۱۹﴾', 'اور پرندوں کو بھی کہ وہ جمع رہتے تھے ہر ایک انکے آگے رجوع رہتا تھا۔', 'اور اڑتے جانور جمع ہو کر سب تھے اس کے آگے رجوع رہتے [۱۸]', 'And (so did) the birds assembled: all with him (Dawood (David)) did turn (to Allah i.e. glorified His Praises).', 'and the birds as well, mustered together. All were turning to Allah with him.'),
(3990, 38, 20, 2, 11, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ شَدَدۡنَا مُلۡکَہٗ  وَ اٰتَیۡنٰہُ  الۡحِکۡمَۃَ وَ فَصۡلَ  الۡخِطَابِ ﴿۲۰﴾', 'اور ہم نے انکی بادشاہی کو مستحکم کیا اور انکو حکمت اور فیصلہ کن خطابت عطا فرمائی۔', 'اور قوت دی ہم نے اسکی سلطنت کو [۱۹] اور دی اس کو تدبیر اور فیصلہ کرنا بات کا [۲۰]', 'We made his kingdom strong and gave him Al-Hikmah (Prophethood, etc.) and sound judgement in speech and decision.', 'And We made his kingdom strong, and gave him wisdom and decisive speech.'),
(3991, 38, 21, 2, 11, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ ہَلۡ  اَتٰىکَ نَبَؤُا الۡخَصۡمِ ۘ اِذۡ  تَسَوَّرُوا  الۡمِحۡرَابَ ﴿ۙ۲۱﴾', 'اور اے نبی ﷺ کیا تمہارے پاس ان جھگڑنے والوں کی بھی خبر آئی ہے جب وہ دیوار پھاند کر اندر داخل ہوئے۔', 'اور پہنچی ہے تجھ کو خبر دعوے  والوں کی جب دیوار کود کر آئے عبادت خانہ میں', 'And has the news of the litigants reached you? When they climbed over the wall into (his) Mihrab (a praying place or a private room,).', 'Has there come to you the story of the litigants, when they entered the sanctuary by climbing over the wall?'),
(3992, 38, 22, 2, 11, 23, 'وَ مَا لِیَ ', 'صٓ', 'اِذۡ  دَخَلُوۡا عَلٰی دَاوٗدَ  فَفَزِعَ مِنۡہُمۡ  قَالُوۡا لَا تَخَفۡ ۚ خَصۡمٰنِ بَغٰی بَعۡضُنَا عَلٰی بَعۡضٍ فَاحۡکُمۡ  بَیۡنَنَا بِالۡحَقِّ  وَ لَا تُشۡطِطۡ وَ اہۡدِنَاۤ  اِلٰی سَوَآءِ  الصِّرَاطِ ﴿۲۲﴾', 'جس وقت وہ داؤد  کے پاس آئے تو وہ ان سے گھبرا گئے انہوں نے کہا کہ خوف نہ کیجئے ہم دونوں کا ایک مقدمہ ہے کہ ہم میں سے ایک نے دوسرے پر زیادتی کی ہے تو آپ ہم میں انصاف سے فیصلہ کر دیجئے اور بےانصافی نہ کیجئے گا اور ہمکو سیدھا رستہ دکھا دیجئے۔', 'جب گھس آئے داؤد کے پاس تو ان سے گھبرایا [۲۱] وہ بولے مت گھبرا ہم دو جھگڑتے ہیں زیادتی کی ہے ایک نے دوسرے پر سو فیصلہ کر دے ہم میں انصاف کا اور دور نہ ڈال بات کو اور بتلا دے ہم کو سیدھی راہ [۲۲]', 'When they entered in upon Dawood (David), he was terrified of them, they said: \"Fear not! (We are) two litigants, one of whom has wronged the other, therefore judge between us with truth, and treat us not with injustice, and guide us to the Right Way.', 'When they entered upon Dawūd, and he was scared of them, they said, “Be not scared. We are two litigants; one of us has wronged the other, so decide between us with truth, and do not cross the limits, and guide us to the right path.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(3993, 38, 23, 2, 11, 23, 'وَ مَا لِیَ ', 'صٓ', 'اِنَّ  ہٰذَاۤ  اَخِیۡ ۟ لَہٗ  تِسۡعٌ وَّ تِسۡعُوۡنَ نَعۡجَۃً  وَّ لِیَ نَعۡجَۃٌ  وَّاحِدَۃٌ ۟ فَقَالَ اَکۡفِلۡنِیۡہَا وَ عَزَّنِیۡ  فِی الۡخِطَابِ ﴿۲۳﴾', 'بات یہ ہے کہ یہ میرا بھائی ہے اسکے ہاں ننانوے دنبیاں ہیں اور میرے پاس ایک دنبی ہے۔ یہ کہتا ہے کہ یہ بھی میرے حوالے کر دے اور گفتگو میں مجھ پر حاوی ہو رہا ہے۔', 'یہ جو ہے بھائی ہے میرا اس کے یہاں ہیں نِنّانوے دنبیاں اور میرے یہاں ہیں ایک دنبی پھر کہتا ہے حوالہ کر دے میرے وہ بھی اور زبردستی کرتا ہے مجھ سے بات میں [۲۳]', 'Verily, this my brother (in religion) has ninety nine ewes, while I have (only) one ewe, and he says: \"Hand it over to me, and he overpowered me in speech.\"', 'This is my brother; he has ninety nine ewes, and I have a single ewe; still he said, ‘Give it into my charge.’ And he overpowered me in speech.”'),
(3994, 38, 24, 2, 11, 23, 'وَ مَا لِیَ ', 'صٓ', 'قَالَ لَقَدۡ ظَلَمَکَ بِسُؤَالِ نَعۡجَتِکَ  اِلٰی نِعَاجِہٖ ؕ وَ اِنَّ کَثِیۡرًا مِّنَ الۡخُلَطَآءِ لَیَبۡغِیۡ  بَعۡضُہُمۡ عَلٰی بَعۡضٍ  اِلَّا الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ وَ قَلِیۡلٌ مَّا ہُمۡ ؕ وَ ظَنَّ دَاوٗدُ  اَنَّمَا فَتَنّٰہُ  فَاسۡتَغۡفَرَ رَبَّہٗ  وَ خَرَّ   رَاکِعًا وَّ  اَنَابَ ﴿ٛ۲۴﴾', 'انہوں نے کہا کہ یہ جو تیری دنبی مانگتا ہے کہ اپنی دنبیوں میں ملا لے بیشک تجھ پر ظلم کرتا ہے۔ اور اکثر شریک ایک دوسرے پر زیادتی ہی کیا کرتے ہیں۔ ہاں جو ایمان لائے اور عمل نیک کرتے رہے اور ایسے لوگ بہت کم ہیں۔ اور داؤد  نے خیال کیا کہ اس واقعے سے ہم نے انکو آزمایا ہے تو انہوں نے اپنے پروردگار سے مغفرت مانگی اور جھک کر سجدے میں گر پڑے اور اللہ کی طرف رجوع کیا۔', 'بولا وہ بے انصافی کرتا ہے تجھ پر کہ مانگتا ہے تیری دنبی ملانے کو اپنی دنبیوں میں [۲۴] اور اکثر شریک زیادتی کرتے ہیں ایک دوسرے پر مگر جو یقین لائے ہیں اور کام کئے نیک اور تھوڑے لوگ ہیں ایسے [۲۵] اور خیال میں آیا داؤد کے کہ ہم نے اس کو جانچا پھر گناہ بخشوانے لگا اپنے رب سے اور گر پڑا جھک کر اور رجوع ہوا', '(Dawood (David)) said (immediately without listening to the opponent): \"He has wronged you in demanding your ewe in addition to his ewes. And, verily, many partners oppress one another, except those who believe and do righteous good deeds, and they are few.\" And Dawood (David) guessed that We have tried him and he sought Forgiveness of his Lord, and he fell down prostrate and turned (to Allah) in repentance.', 'He (Dawūd) said, “He has certainly wronged you by demanding your ewe to be added to his ewe. Many partners oppress one another, except those who believe and do righteous deeds, and very few they are.” And Dawūd realized that We had put him to a test, so he prayed to his Lord for forgiveness, and bowing down, he fell in prostration, and turned (to Allah).'),
(3995, 38, 25, 2, 11, 23, 'وَ مَا لِیَ ', 'صٓ', 'فَغَفَرۡنَا لَہٗ  ذٰلِکَ ؕ وَ  اِنَّ  لَہٗ عِنۡدَنَا لَزُلۡفٰی وَ حُسۡنَ مَاٰبٍ ﴿۲۵﴾', 'تو ہم نے انکو بخش دیا۔ اور بیشک انکے لئے ہمارے ہاں قرب اور عمدہ مقام ہے۔', 'پھر ہم نے معاف کر دیا اسکو وہ کام [۲۶] اور اس کے لیے ہمارے پاس مرتبہ ہے اور اچھا ٹھکانہ [۲۷]', 'So We forgave him that, and verily, for him is a near access to Us, and a good place of (final) return (Paradise).', 'So we forgave him that (lapse), and surely he has a place of nearness in Our presence, and an excellent resort.'),
(3996, 38, 26, 2, 11, 23, 'وَ مَا لِیَ ', 'صٓ', 'یٰدَاوٗدُ  اِنَّا جَعَلۡنٰکَ خَلِیۡفَۃً فِی الۡاَرۡضِ فَاحۡکُمۡ بَیۡنَ النَّاسِ بِالۡحَقِّ وَ لَا تَتَّبِعِ الۡہَوٰی فَیُضِلَّکَ عَنۡ سَبِیۡلِ اللّٰہِ ؕ اِنَّ الَّذِیۡنَ یَضِلُّوۡنَ عَنۡ سَبِیۡلِ اللّٰہِ  لَہُمۡ عَذَابٌ شَدِیۡدٌۢ بِمَا نَسُوۡا یَوۡمَ الۡحِسَابِ  ﴿٪۲۶﴾', 'اے داؤد  ہم نے تمکو زمین میں خلیفہ بنایا ہے تو لوگوں میں انصاف کے فیصلے کیا کرو اور خواہش کی پیروی نہ کرنا کہ وہ تمہیں اللہ کے رستے سے بھٹکا دے گی۔ جو لوگ اللہ کے رستے سے بھٹکتے ہیں انکے لئے سخت عذاب ہے اسلئے کہ انہوں نے حساب کے دن کو بھلا دیا۔', 'اے داؤد ہم نے کیا تجھ کو نائب ملک میں سو تو حکومت کر لوگوں میں انصاف سے اور نہ چل جی کی خواہش پر پھر وہ تجھ کو بچلا دے اللہ کی راہ سے مقرر جو لوگ بچلتے ہیں اللہ کی راہ سے ان کے لئے سخت عذاب ہے [۲۸] اسی بات پر کہ بھلایا انہوں نے دن حساب کا [۲۹]', 'O Dawood (David)! Verily! We have placed you as a successor on earth, so judge you between men in truth (and justice) and follow not your desire for it will mislead you from the Path of Allah. Verily! Those who wander astray from the Path of Allah (shall) have a severe torment, because they forgot the Day of Reckoning.', 'O Dawūd, We have made you a vicegerent on earth, so judge between people with truth, and do not follow the selfish desire, lest it should lead you astray from Allah’s path. Surely those who go astray from Allah’s path will have a severe punishment, because they had forgotten the Day of Reckoning.'),
(3997, 38, 27, 3, 12, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ مَا خَلَقۡنَا السَّمَآءَ  وَ الۡاَرۡضَ وَ مَا بَیۡنَہُمَا بَاطِلًا ؕ ذٰلِکَ ظَنُّ الَّذِیۡنَ کَفَرُوۡا ۚ فَوَیۡلٌ  لِّلَّذِیۡنَ کَفَرُوۡا مِنَ النَّارِ ﴿ؕ۲۷﴾', 'اور ہم نے آسمان اور زمین کو اور جو کائنات ان میں ہے اسکو بے مقصد نہیں پیدا کیا۔ یہ ان کا گمان ہے جو کافر ہیں سو کافروں کے لئے دوزخ کا عذاب ہے۔', 'اور ہم نے نہیں بنایا آسمان اور زمین کو اور جو ان کے بیچ میں ہے نکما یہ خیال ہے ان کا جو منکر ہیں سو خرابی ہے منکروں کے لیے آگ سے [۳۰]', 'And We created not the heaven and the earth and all that is between them without purpose! That is the consideration of those who disbelieve! Then woe to those who disbelieve (in Islamic Monotheism) from the Fire!', 'We did not create the heavens and the earth and what is between them in vain. That is the thinking of those who disbelieve. So, woe to the disbelievers because of the Fire (they have to face).'),
(3998, 38, 28, 3, 12, 23, 'وَ مَا لِیَ ', 'صٓ', 'اَمۡ نَجۡعَلُ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ کَالۡمُفۡسِدِیۡنَ فِی الۡاَرۡضِ ۫ اَمۡ  نَجۡعَلُ  الۡمُتَّقِیۡنَ  کَالۡفُجَّارِ ﴿۲۸﴾', 'جو لوگ ایمان لائے اور عمل نیک کرتے رہے۔ کیا انکو ہم انکی طرح کر دیں گے جو ملک میں فساد کرتے ہیں۔ یا پرہیزگاروں کو بدکاروں کی طرح کر دیں گے۔', 'کیا ہم کر دیں گے ایمان والوں کو جو کرتے ہیں نیکیاں برابر ان کے جو خرابی ڈالیں ملک میں کیا ہم کر دیں گے ڈرنے والوں کو برابر ڈھیٹھ لوگوں کے [۳۱]', 'Shall We treat those who believe (in the Oneness of Allah Islamic Monotheism) and do righteous good deeds, as Mufsidoon (those who associate partners in worship with Allah and commit crimes) on earth? Or shall We treat the Muttaqoon (pious - see V.2:2), as the Fujjar (criminals, disbelievers, wicked, etc)?ONT>', 'Shall We make those who believe and do righteous deeds equal to those who commit mischief on the earth? Or shall We make the God-fearing equal to the sinners?'),
(3999, 38, 29, 3, 12, 23, 'وَ مَا لِیَ ', 'صٓ', 'کِتٰبٌ  اَنۡزَلۡنٰہُ  اِلَیۡکَ مُبٰرَکٌ  لِّیَدَّبَّرُوۡۤا اٰیٰتِہٖ وَ  لِیَتَذَکَّرَ  اُولُوا الۡاَلۡبَابِ ﴿۲۹﴾', 'یہ کتاب جو ہم نے تم پر نازل کی ہے بابرکت ہے تاکہ لوگ اسکی آیتوں میں غور کریں اور تاکہ اہل عقل نصیحت حاصل کریں۔', 'ایک کتاب ہے جو اتاری ہم نے تیری طرف برکت کی تا دھیان کریں لوگ اسکی باتیں اور تا سمجھیں عقل والے [۳۲]', '(This is) a Book (the Quran) which We have sent down to you, full of blessings that they may ponder over its Verses, and that men of understanding may remember.', 'This is a blessed Book We have revealed to you, so that they deliberate in its verses, and so that the men of understanding may heed to advice.'),
(4000, 38, 30, 3, 12, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ وَہَبۡنَا لِدَاوٗدَ  سُلَیۡمٰنَ ؕ نِعۡمَ  الۡعَبۡدُ ؕ اِنَّہٗۤ  اَوَّابٌ ﴿ؕ۳۰﴾', 'اور ہم نے داؤد  کو سلیمان  عطا کئے۔ بہت خوب بندے تھے اور وہ اللہ کی طرف بہت رجوع کرنے والے تھے۔', 'اور دیا ہم نے داؤد وکو سلیمان [۳۳] بہت خوب بندہ وہ ہے از  رجوع  رہنے والا', 'And to Dawood (David) We gave Sulaiman (Solomon). How excellent (a) slave! Verily, he was ever oft-returning in repentance (to Us)!', 'And We blessed Dawūd with Sulaimān. He was an excellent servant (of Allah). Surely, he was great in turning (to Us, in penitence and praise).'),
(4001, 38, 31, 3, 12, 23, 'وَ مَا لِیَ ', 'صٓ', 'اِذۡ عُرِضَ عَلَیۡہِ بِالۡعَشِیِّ الصّٰفِنٰتُ الۡجِیَادُ ﴿ۙ۳۱﴾', 'جب انکے سامنے شام کو اصیل گھوڑے پیش کئے گئے۔', 'جب دکھانے کو لائے اسکے سامنے شام کو گھوڑے بہت خاصے', 'When there were displayed before him, in the afternoon, well trained horses of the highest breed (for Jihad (holy fighting in Allahs Cause)).', '(Worth remembering is the incident) when the swift horses of high breeding were presented before him in the evening.'),
(4002, 38, 32, 3, 12, 23, 'وَ مَا لِیَ ', 'صٓ', 'فَقَالَ  اِنِّیۡۤ  اَحۡبَبۡتُ حُبَّ الۡخَیۡرِ عَنۡ ذِکۡرِ  رَبِّیۡ ۚ حَتّٰی تَوَارَتۡ بِالۡحِجَابِ ﴿ٝ۳۲﴾', 'تو کہنے لگے کہ میں نے اپنے پروردگار کی یاد سے غافل ہو کر مال کی محبت اختیار کی۔ یہاں تک کہ آفتاب پردے میں چھپ گیا۔', 'تو بولا میں نے دوست رکھا مال کی محبت کو اپنے رب کی یاد سے یہاں تک کہ سورج چھپ گیا اوٹ میں', 'And he said: \"Alas! I did love the good (these horses) instead of remembering my Lord (in my Asr prayer)\" till the time was over, and (the sun) had hidden in the veil (of night).', 'He said, “I held the love of the good things (i.e. these horses) because of the remembrance of my Lord.” until it went behind the veil.'),
(4003, 38, 33, 3, 12, 23, 'وَ مَا لِیَ ', 'صٓ', 'رُدُّوۡہَا عَلَیَّ ؕ فَطَفِقَ مَسۡحًۢا بِالسُّوۡقِ وَ الۡاَعۡنَاقِ ﴿۳۳﴾', 'بولے کہ انکو میرے پاس واپس لاؤ۔ پھر انکی ٹانگوں اور گردنوں پر ہاتھ پھیرنے لگے۔', 'پھیر لاؤ ان کو میرے پاس پھر لگا  جھاڑنے انکی پنڈلیاں اور گردنیں [۳۴]', 'Then he said \"Bring them (horses) back to me.\" Then he began to pass his hand over their legs and their necks (till the end of the display).', '(Then he said,) “Bring them back to me” - and he started passing his hands over the shanks and the necks (of the horses).'),
(4004, 38, 34, 3, 12, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ لَقَدۡ فَتَنَّا سُلَیۡمٰنَ وَ اَلۡقَیۡنَا عَلٰی کُرۡسِیِّہٖ  جَسَدًا ثُمَّ  اَنَابَ ﴿۳۴﴾', 'اور ہم نے سلیمان  کی آزمائش کی اور انکے تخت پر ایک دھڑ سا ڈال دیا پھر انہوں نے اللہ کی طرف رجوع کیا۔', 'اور ہم نے جانچا سلیمان کو اور ڈال دیا اس کے تخت پر ایک دھڑ پھر وہ رجوع  ہوا [۳۵]', 'And, indeed We did try Sulaiman (Solomon) and We placed on his throne Jasadan (a devil, so he lost his kingdom for a while) but he did return (to his throne and kingdom by the Grace of Allah and he did return) to Allah with obedience and in repentance.', 'And indeed We tested Sulaimān while We threw on his throne a body after which he turned (to Us).'),
(4005, 38, 35, 3, 12, 23, 'وَ مَا لِیَ ', 'صٓ', 'قَالَ رَبِّ اغۡفِرۡ لِیۡ وَ ہَبۡ لِیۡ مُلۡکًا لَّا یَنۡۢبَغِیۡ لِاَحَدٍ مِّنۡۢ بَعۡدِیۡ ۚ اِنَّکَ اَنۡتَ الۡوَہَّابُ  ﴿۳۵﴾', 'اور دعا کی کہ اے پروردگار مجھے معاف فرما اور مجھ کو ایسی بادشاہی عطا فرما کہ میرے بعد کسی کو شایاں نہ ہو۔ بیشک تو سب کچھ عطا فرمانے والا ہے۔', 'بولا اے رب میرے معاف کر مجھ کو اور بخش مجھ کو وہ بادشاہی کہ مناسب نہ ہو کسی کو میرے پیچھے بیشک تو ہے سب کچھ بخشنے والا [۳۶]', 'He said: \"My Lord! Forgive me, and bestow upon me a kingdom such as shall not belong to any other after me: Verily, You are the Bestower.\"', 'He said, “O my Lord, forgive me, and bless me with a kingdom that will not be available to anyone after me. Surely, You are the Bountiful.”'),
(4006, 38, 36, 3, 12, 23, 'وَ مَا لِیَ ', 'صٓ', 'فَسَخَّرۡنَا لَہُ  الرِّیۡحَ تَجۡرِیۡ بِاَمۡرِہٖ رُخَآءً  حَیۡثُ  اَصَابَ  ﴿ۙ۳۶﴾', 'پھر ہم نے ہوا کو انکے زیرفرمان کر دیا کہ جہاں وہ پہنچنا چاہتے انکے حکم سے نرم نرم چلنے لگتی۔', 'پھر ہم نے تابع کر دیا اسکے ہوا کو چلتی تھی اس کے حکم سے نرم نرم جہاں پہنچنا چاہتا', 'So, We subjected to him the wind, it blew gently to his order whithersoever he willed,', 'Then We subjugated the wind for him that blew smoothly on his command to wherever he wished,'),
(4007, 38, 37, 3, 12, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ الشَّیٰطِیۡنَ کُلَّ  بَنَّآءٍ   وَّ غَوَّاصٍ ﴿ۙ۳۷﴾', 'اور جنوں کو بھی انکے زیرفرمان کیا یہ سب عمارتیں بنانے والے اور غوطہ مارنے والے تھے۔', 'اور تابع کر دیے شیطان سارے عمارت بنانے والے اور غوطہ لگانے والے [۳۷]', 'And also the Shayatin (devils) from the jinns (including) every kind of builder and diver,', 'and (We subjugated to him) the devils (among Jinns), all builders and divers,'),
(4008, 38, 38, 3, 12, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَّ اٰخَرِیۡنَ مُقَرَّنِیۡنَ فِی الۡاَصۡفَادِ ﴿۳۸﴾', 'اور کچھ دوسروں کو بھی جو زنجیروں میں جکڑے ہوئے تھے۔', 'بہت سے اور جو باہم جکڑے ہوئے ہیں بیڑیوں میں [۳۸]', 'And also others bound in fetters.', 'and many others held in chains.'),
(4009, 38, 39, 3, 12, 23, 'وَ مَا لِیَ ', 'صٓ', 'ہٰذَا عَطَآؤُنَا فَامۡنُنۡ اَوۡ اَمۡسِکۡ بِغَیۡرِ حِسَابٍ ﴿۳۹﴾', 'ہم نےکہا یہ ہماری بخشش ہے چاہو تو احسان کرو یا رکھ چھوڑو تم سے کچھ حساب نہیں ہے۔', 'یہ ہے بخشش ہماری اب تو احسان کریا رکھ چھوڑ کچھ حساب نہ  ہوگا [۳۹]', '(Saying of Allah to Sulaiman (Solomon)): \"This is Our gift, so spend you or withhold, no account will be asked.\"', 'This is Our gift. So, do favor (to someone) or withhold (it), with no (requirement to give) account.'),
(4010, 38, 40, 3, 12, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ اِنَّ لَہٗ عِنۡدَنَا لَزُلۡفٰی وَ حُسۡنَ مَاٰبٍ ﴿٪۴۰﴾', 'اور بیشک ان کے لئے ہمارے ہاں قرب اور عمدہ ٹھکانہ ہے۔', 'اور س کا ہمارے یہاں مرتبہ ہے اور  اچھا ٹھکانہ [۴۰]', 'And verily, he enjoyed a near access to Us, and a good final return (Paradise).', 'He has a place of nearness in Our presence, and an excellent end.'),
(4011, 38, 41, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ اذۡکُرۡ عَبۡدَنَاۤ  اَیُّوۡبَ ۘ اِذۡ  نَادٰی رَبَّہٗۤ اَنِّیۡ مَسَّنِیَ الشَّیۡطٰنُ بِنُصۡبٍ وَّ عَذَابٍ ﴿ؕ۴۱﴾', 'اور ہمارے بندے ایوب  کو یاد کرو جب انہوں نے اپنے رب کو پکارا اور کہا کہ شیطان نے مجھ کو ایذا اور تکلیف دے رکھی ہے۔', 'اور یاد کر ہمارے بندے ایوب کو جب اس نے  پکارا  اپنے رب کہ مجھ کو لگا دی شیطان نے  ایذ اور تکلیف [۴۱]', 'And remember Our slave Ayoob (Job), when he invoked his Lord (saying): \"Verily! Shaitan (Satan) has touched me with distress (by losing my health) and torment (by losing my wealth)!', 'And remember Our servant, Ayyūb - when he called his Lord saying, “The ShaiTān (Satan) has inflicted weariness and pain upon me.”'),
(4012, 38, 42, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'اُرۡکُضۡ بِرِجۡلِکَ ۚ ہٰذَا مُغۡتَسَلٌۢ  بَارِدٌ وَّ  شَرَابٌ ﴿۴۲﴾', 'ہم نے کہا کہ زمین پر لات مارو دیکھو یہ چشمہ نکل آیا نہانے کو ٹھنڈا پانی اور پینے کو بھی۔', 'لات مار اپنے پاؤں سے یہ چشمہ نکلا نہانے کو اور ٹھنڈا اور پینے کو', '(Allah said to him): \"Strike the ground with your foot: This is a spring of water to wash in, cool and a (refreshing) drink.\"', '(Allah said to him,) “Strike (the ground) with your foot: Here is a cool water to bathe, and a drink!”'),
(4013, 38, 43, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ وَہَبۡنَا  لَہٗۤ  اَہۡلَہٗ  وَ مِثۡلَہُمۡ مَّعَہُمۡ رَحۡمَۃً  مِّنَّا وَ ذِکۡرٰی  لِاُولِی الۡاَلۡبَابِ ﴿۴۳﴾', 'اور ہم نے انکو اہل و عیال اور انکے ساتھ اتنے ہی اور بخشے یہ ہماری طرف سے رحمت اور عقل والوں کے لئے نصیحت تھی۔', 'اور بخشے ہم نے اسکو  اسکے گھر  والے اور ان کے برابر ان کے ساتھ اپنی طرف کی مہربانی سے اور یاد رکھنے کو عقل والوں کے [۴۲]', 'And We gave him (back) his family, and along with them the like thereof, as a Mercy from Us, and a Reminder for those who understand.', 'And We let him have his family and the like of them besides, as a mercy from Us, and a reminder for the people of understanding.'),
(4014, 38, 44, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ خُذۡ بِیَدِکَ ضِغۡثًا  فَاضۡرِبۡ بِّہٖ وَ لَا تَحۡنَثۡ ؕ اِنَّا وَجَدۡنٰہُ صَابِرًا ؕ نِعۡمَ الۡعَبۡدُ ؕ اِنَّہٗۤ  اَوَّابٌ ﴿۴۴﴾', 'اور ہم نے کہا اپنے ہاتھ میں تنکوں کا ایک مٹھا لو پھر اس سے مار لو اور قسم نہ توڑو بیشک ہم نے انکو ثابت قدم پایا۔ بہت خوب بندے تھے بیشک وہ بہت رجوع کرنے والے تھے۔', 'اور پکڑ اپنے ہاتھ میں سیلنکوں کا مٹھا پھر اس سے مار لے اور قسم میں جھوٹا نہ ہو [۴۳] ہم نے اس کو پایا جھیلنے والا بہت خوب بندہ تحقیق وہ ہے رجوع رہنے والا', '\"And take in your hand a bundle of thin grass and strike therewith (your wife), and break not your oath . Truly! We found him patient. How excellent (a) slave! Verily, he was ever oft-returning in repentance (to Us)!', 'And (We said to him,) “Take (a bundle of) thin twigs in your hand, and strike with it, and do not violate your oath. Surely, We found him very enduring. He was really an excellent servant. Surely, he was great in turning (to Us, in penitence and praise).'),
(4015, 38, 45, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ اذۡکُرۡ عِبٰدَنَاۤ  اِبۡرٰہِیۡمَ وَ اِسۡحٰقَ وَ یَعۡقُوۡبَ اُولِی الۡاَیۡدِیۡ  وَ  الۡاَبۡصَارِ ﴿۴۵﴾', 'اور ہمارے بندوں ابراہیم  اور اسحٰق  اور یعقوب  کو یاد کرو جو قوت والے اور صاحب نظر تھے۔', 'اور یاد کر ہمارے بندوں کو ابراہیم اور اسحٰق اور یعقوب ہاتھوں والے اور آنکھوں والے [۴۴]', 'And remember Our slaves, Ibrahim (Abraham), Ishaque (Isaac), and Yaqoob (Jacob), (all) owners of strength (in worshipping Us) and (also) of religious understanding.', 'And remember Our servants - Ibrāhīm and IsHāq and Ya‘qūb - the men of strength and the men of vision.'),
(4016, 38, 46, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'اِنَّاۤ  اَخۡلَصۡنٰہُمۡ بِخَالِصَۃٍ  ذِکۡرَی الدَّارِ ﴿ۚ۴۶﴾', 'ہم نے انکو ایک صفت خاص آخرت کے گھر کی یاد سے ممتاز کیا تھا۔', 'ہم نے امتیاز دیا انکو  ایک چنی ہوئی بات کا وہ یاد اس گھر کی [۴۵]', 'Verily, We did choose them by granting them (a good thing, i.e.) the remembrance of the home (in the Hereafter and they used to make the people remember it, and also they used to invite the people to obey Allah and to do good deeds for the Hereafter).', 'We chose them for a trait of remembering the (eternal) Home (in the Hereafter).'),
(4017, 38, 47, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ اِنَّہُمۡ عِنۡدَنَا لَمِنَ الۡمُصۡطَفَیۡنَ الۡاَخۡیَارِ ﴿ؕ۴۷﴾', 'اور وہ ہمارے نزدیک منتخب او خوبی والوں میں سے تھے۔', 'اور وہ سب ہمارے نزدیک ہیں چنے ہوئے نیک لوگوں میں', 'And they are with Us, verily, of the chosen and the best!', 'And surely they are, in Our sight, among the chosen, the best of the righteous.'),
(4018, 38, 48, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ اذۡکُرۡ  اِسۡمٰعِیۡلَ وَ الۡیَسَعَ وَ ذَاالۡکِفۡلِ ؕ وَ کُلٌّ  مِّنَ  الۡاَخۡیَارِ ﴿ؕ۴۸﴾', 'اور اسمٰعیل  اور الیسع  اور ذوالکفل  کو یاد کرو۔ اور یہ سب بھی خوبی والوں میں سے تھے۔', 'اور یاد کر اسمٰعیل کو اور الیسع کو اور ذوالکفل کو اور ہر ایک تھا خوبی والا [۴۶]', 'And remember Ismail (Ishmael), AlYasaa (Elisha), and Dhul-Kifl (Isaiah), all are among the best.', 'And remember Ismā‘īl and Al-Yasa‘ and Dhul-Kifl. Each one of them was among the best of the righteous.'),
(4019, 38, 49, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'ہٰذَا  ذِکۡرٌ ؕ وَ  اِنَّ  لِلۡمُتَّقِیۡنَ لَحُسۡنَ مَاٰبٍ ﴿ۙ۴۹﴾', 'یہ نصیحت ہے اور پرہیزگاروں کے لئے تو عمدہ ٹھکانہ ہے۔', 'یہ ایک مذکور ہو چکا [۴۷] اور تحقیق ڈر والوں کے لیے ہے اچھا ٹھکانا', 'This is a Reminder, and verily, for the Muttaqoon (pious and righteous persons - see V.2:2) is a good final return (Paradise), -,', 'This is a reminder (of what has passed). And surely the God-fearing will have the best place to return:'),
(4020, 38, 50, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'جَنّٰتِ عَدۡنٍ مُّفَتَّحَۃً  لَّہُمُ  الۡاَبۡوَابُ ﴿ۚ۵۰﴾', 'ہمیشہ رہنے کے باغ جنکے دروازے انکے لئے کھلے ہوں گے۔', 'باغ ہیں سدا بسنے کے کھول رکھے ہیں انکے واسطے دروازے [۴۸]', 'Adn (Edn) Paradise (everlasting Gardens), whose doors will be open for them, (It is said (in Tafsir At-Tabaree, Part 23, Page 174) that one can speak to the doors, just one tells it to open and close, and it will open or close as it is ordered).', '- everlasting gardens, with (their) doors opened for them.'),
(4021, 38, 51, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'مُتَّکِـِٕیۡنَ  فِیۡہَا یَدۡعُوۡنَ فِیۡہَا بِفَاکِہَۃٍ  کَثِیۡرَۃٍ   وَّ  شَرَابٍ ﴿۵۱﴾', 'ان میں تکیے لگائے بیٹھے ہوں گے اور کھانے پینے کے لئے بہت سے میوے اور مشروبات منگاتے رہیں گے۔', 'تکیہ لگائے ہوئے بیٹھے ہیں ان میں میوے بہت اور شراب [۴۹]', 'Therein they will recline; therein they will call for fruits in abundance and drinks;', 'They will be relaxing in it, calling there for plenteous fruits and drinks;'),
(4022, 38, 52, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ عِنۡدَہُمۡ  قٰصِرٰتُ الطَّرۡفِ  اَتۡرَابٌ ﴿۵۲﴾', 'اور انکے پاس نیچی نگاہ رکھنے والی اور ہم عمر حوریں ہوں گی۔', 'اور ان کے  پاس عورتیں ہیں نیچی نگاہ والیاں ایک عمر کی [۵۰]', 'And beside them will be chaste females (virgins) restraining their glances only for their husbands, (and) of equal ages.', 'and in their company there will be females restricting their glances (to their husbands, and) of matching ages.'),
(4023, 38, 53, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'ہٰذَا مَا تُوۡعَدُوۡنَ  لِیَوۡمِ الۡحِسَابِ ﴿ؓ۵۳﴾', 'یہ وہ چیزیں ہیں جن کا حساب کے دن کے لئے تم سے وعدہ کیا جاتا تھا۔', 'یہ وہ ہے جو تم سے وعدہ کیا گیا حساب کے دن پر', 'This it is what you (Al-Muttaqoon - the pious) are promised for the Day of Reckoning!', 'This is what you are being promised for the Day of Reckoning.'),
(4024, 38, 54, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'اِنَّ  ہٰذَا  لَرِزۡقُنَا مَا  لَہٗ  مِنۡ  نَّفَادٍ  ﴿ۚۖ۵۴﴾', 'یہ ہمارا رزق ہے جو کبھی ختم نہیں ہو گا۔', 'یہ ہی روزی ہماری دی ہوئی اسکو نہیں نبڑنا [۵۱]', '(It will be said to them)! Verily, this is Our Provision which will never finish;', 'Surely, that is provision provided by Us, to which there is no end.'),
(4025, 38, 55, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'ہٰذَا ؕ وَ  اِنَّ  لِلطّٰغِیۡنَ  لَشَرَّ  مَاٰبٍ ﴿ۙ۵۵﴾', 'یہ نعمتیں تو فرمانبرداروں کے لئے ہیں اور سرکشوں کے لئے برا ٹھکانہ ہے۔', 'یہ سن چکے [۵۲] اور تحقیق شریروں کے واسطے ہے برا ٹھکانہ', 'This is so! And for the Taghoon (transgressors, disobedient to Allah and His Messenger - disbelievers in the Oneness of Allah, criminals, etc.), will be an evil final return (Fire),', 'Having said this, the transgressors will surely have the most evil place to return:'),
(4026, 38, 56, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'جَہَنَّمَ ۚ یَصۡلَوۡنَہَا ۚ فَبِئۡسَ الۡمِہَادُ ﴿۵۶﴾', 'یعنی دوزخ جس میں وہ داخل ہوں گے۔ اور وہ بری آرامگاہ ہے۔', 'دوزخ ہے جس میں انکو ڈالیں گے سو کیا بری آرام کرنے کی جگہ ہے', 'Hell! Where they will burn, and worst (indeed) is that place to rest!', 'the Jahannam , in which they will enter. So, how evil is that place to rest?'),
(4027, 38, 57, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'ہٰذَا ۙ فَلۡیَذُوۡقُوۡہُ حَمِیۡمٌ  وَّ غَسَّاقٌ ﴿ۙ۵۷﴾', 'یہ کھولتا ہوا گرم پانی اور پیپ ہے اب اسکے مزے چکھیں۔', 'یہ ہے اب اسکو چکھیں [۵۳] گرم پانی اور پیپ [۵۴]', 'This is so! Then let them taste it, a boiling fluid and dirty wound discharges.', 'Let them taste this: hot water and pus,'),
(4028, 38, 58, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَّ اٰخَرُ  مِنۡ شَکۡلِہٖۤ  اَزۡوَاجٌ ﴿ؕ۵۸﴾', 'اور اسی طرح کے اور بہت سے عذاب ہوں گے۔', 'اور کچھ اور اسی شکل کی طرح طرح کی چیزیں', 'And other torments of similar kind, all together!', 'and other things similar to it of various kinds.'),
(4029, 38, 59, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'ہٰذَا فَوۡجٌ مُّقۡتَحِمٌ  مَّعَکُمۡ ۚ لَا مَرۡحَبًۢا بِہِمۡ ؕ اِنَّہُمۡ صَالُوا النَّارِ ﴿۵۹﴾', 'یہ ایک فوج ہے جو تمہارے ساتھ گھستی چلی آ رہی ہے انکو خوش آمدید نہ کہا جائے یہ دوزخ میں جانے والے ہیں۔', 'یہ ایک فوج ہے دھستی آ رہی ہے تمہارے ساتھ جگہ نہ ملیو  ان کو  یہ ہیں گھسنے والے آگ میں', 'This is a troop entering with you (in Hell), no welcome for them! Verily, they shall burn in the Fire!', '(When the leaders of the infidels will see their followers entering the Hell after them, they will say to each other,) “This is a multitude rushing into (the Hell) with you - they are not welcome - they are to burn in the Fire.”'),
(4030, 38, 60, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'قَالُوۡا بَلۡ  اَنۡتُمۡ ۟ لَا مَرۡحَبًۢا بِکُمۡ ؕ اَنۡتُمۡ  قَدَّمۡتُمُوۡہُ   لَنَا ۚ فَبِئۡسَ الۡقَرَارُ ﴿۶۰﴾', 'کہیں گے بلکہ تم ہی کو خوش آمدید نہ کہا جائے۔ تم ہی تو یہ بلا ہمارے سامنے لائے ہو۔ سو یہ برا ٹھکانہ ہے۔', 'وہ بولے بلکہ تم ہی ہو کہ جگہ نہ ملیو تم کو تم ہی پیش لائے ہمارے یہ بلا سو کیا بری ٹھہرنے کی جگہ ہے [۵۵]', '(The followers of the misleaders will say): \"Nay, you (too)! No welcome for you! It is you (misleaders) who brought this upon us (because you misled us in the world), so evil is this place to stay in!\"', 'They (the followers) will say (to their leaders) “No, it is you who are not welcome; you are the ones who brought this upon us.” So, how evil is the place to stay (for ever)!”'),
(4031, 38, 61, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'قَالُوۡا رَبَّنَا مَنۡ قَدَّمَ لَنَا ہٰذَا فَزِدۡہُ عَذَابًا ضِعۡفًا فِی النَّارِ ﴿۶۱﴾', 'وہ کہیں گے اے پروردگار جو اسکو ہمارے سامنے لایا ہے اسکو دوزخ میں دگنا عذاب دے۔', 'وہ بولے اے رب ہمارے جو کوئی لایا ہمارے پیش یہ سو بڑھا دے اسکو دونا عذاب آگ میں [۵۶]', 'They will say: \"Our Lord! Whoever brought this upon us, add to him a double torment in the Fire!\"', 'They (the followers) will say, “Our Lord, whoever has brought this on us, do increase his punishment twofold in the Fire.”'),
(4032, 38, 62, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ قَالُوۡا مَا لَنَا لَا نَرٰی رِجَالًا کُنَّا نَعُدُّہُمۡ مِّنَ الۡاَشۡرَارِ ﴿ؕ۶۲﴾', 'اور کہیں گے۔ کیا سبب ہے کہ یہاں ہم ان لوگوں کو نہیں دیکھتے جنکو ہم بروں میں شمار کرتے تھے۔', 'اور کہیں گے کیا ہوا کہ ہم نہیں دیکھتے ان مردوں کو کہ ہم ان کو شمار کرتے تھے برے لوگوں میں', 'And they will say: \"What is the matter with us that we see not men whom we used to count among the bad ones?\"', 'And they (the infidels) will say, “What is the matter with us that we do not see those men (here in Hell) whom we used to count amongst the worst? (i.e the Muslims whom the infidels used to treat as the worst people among them)'),
(4033, 38, 63, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'اَتَّخَذۡنٰہُمۡ سِخۡرِیًّا  اَمۡ  زَاغَتۡ عَنۡہُمُ الۡاَبۡصَارُ ﴿۶۳﴾', 'کہا ہم نے ان سے ٹھٹھا کیا ہے یا ہماری آنکھیں انکی طرف سے پھر گئ ہیں؟', 'کیا ہم نے انکو  ٹھٹھے میں پکڑا تھا یا چوک گئیں ان سے ہماری آنکھیں [۵۷]', 'Did we take them as an object of mockery, or have (our) eyes failed to perceive them?\"', 'Had we taken them as a laughing-stock (unjustly), or have our eyes missed them?”'),
(4034, 38, 64, 4, 13, 23, 'وَ مَا لِیَ ', 'صٓ', 'اِنَّ  ذٰلِکَ  لَحَقٌّ  تَخَاصُمُ   اَہۡلِ النَّارِ ﴿٪۶۴﴾', 'بیشک یہ اہل دوزخ کا جھگڑنا برحق ہے۔', 'یہ بات ٹھیک ہونی ہے جھگڑا کرنا آپس میں دوزخیوں کا [۵۸]', 'Verily, that is the very truth, the mutual dispute of the people of the Fire!', 'That is going to happen definitely, that is, the mutual quarrel of the people of the Fire.'),
(4035, 38, 65, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'قُلۡ  اِنَّمَاۤ  اَنَا مُنۡذِرٌ ٭ۖ وَّ مَا مِنۡ  اِلٰہٍ   اِلَّا اللّٰہُ  الۡوَاحِدُ  الۡقَہَّارُ ﴿ۚ۶۵﴾', 'کہدو کہ میں تو صرف خبردار کرنے والا ہوں۔ اور اللہ اکیلے اور غالب کے سوا کوئی معبود نہیں۔', 'تو کہہ میں تو یہی ہوں ڈر سنا دینے والا حاکم کوئی نہیں مگر اللہ اکیلا دباؤ  والا', 'Say (O Muhammad SAW): \"I am only a warner and there is no Ilah (God) except Allah (none has the right to be worshipped but Allah) the One, the Irresistible,', 'Say, “I am only a warner, and there is no god but Allah, the One, the All-Dominant,'),
(4036, 38, 66, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'رَبُّ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ مَا بَیۡنَہُمَا الۡعَزِیۡزُ  الۡغَفَّارُ ﴿۶۶﴾', 'جو آسمانوں اور زمین اور جو مخلوق ان میں ہے سب کا مالک ہے۔ غالب ہے بخشنے والا۔', 'رب آسمانون کا اور  زمین کا اور جو انکے بیچ میں زبردست بخشنے  والا [۵۹]', '\"The Lord of the heavens and the earth and all that is between them, the All-Mighty, the Oft-Forgiving.\"', 'the Lord of the heavens and the earth and what is between them, the Mighty, the Very-Forgiving.”'),
(4037, 38, 67, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'قُلۡ ہُوَ  نَبَؤٌا عَظِیۡمٌ ﴿ۙ۶۷﴾', 'کہدو کہ یہ ایک بڑی ہولناک چیز کی خبر ہے۔', 'تو کہہ یہ ایک بڑی خبر ہے', 'Say: \"That (this Quran) is a great news,', 'Say, “It is a great news'),
(4038, 38, 68, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'اَنۡتُمۡ عَنۡہُ  مُعۡرِضُوۡنَ ﴿۶۸﴾', 'جسکو تم دھیان میں نہیں لاتے۔', 'کہ تم اس کو دھیان میں نہیں لاتے [۶۰]', '\"From which you turn away!', 'to which you are averse.'),
(4039, 38, 69, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'مَا کَانَ لِیَ مِنۡ عِلۡمٍۭ  بِالۡمَلَاِ الۡاَعۡلٰۤی  اِذۡ یَخۡتَصِمُوۡنَ ﴿۶۹﴾', 'مجھکو اوپر کی مجلس والوں کا جب وہ جھگڑتے تھے کچھ بھی علم نہ تھا۔', 'مجھ کو کچھ خبر نہ تھی او پر کی مجلس کی جب وہ آپس میں تکرار کرتے ہیں', '\"I had no knowledge of the chiefs (angels) on high when they were disputing and discussing (about the creation of Adam).', 'I had no knowledge of the Heavenly Beings when they were debating (about the creation of ’Ādam).'),
(4040, 38, 70, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'اِنۡ یُّوۡحٰۤی اِلَیَّ  اِلَّاۤ  اَنَّمَاۤ  اَنَا نَذِیۡرٌ  مُّبِیۡنٌ ﴿۷۰﴾', 'میری طرف تو یہی وحی کیجاتی ہے کہ میں کھلم کھلا خبردار کرنے والا ہوں۔', 'مجھ کو تو یہی حکم آتا ہے کہ اور کچھ نہیں میں تو ڈر سنا دینے والا ہوں کھول کر [۶۱]', '\"Only this has been inspired to me, that I am a plain warner.\"', 'Revelation is sent to me only because I am a plain warner.'),
(4041, 38, 71, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'اِذۡ قَالَ رَبُّکَ لِلۡمَلٰٓئِکَۃِ  اِنِّیۡ خَالِقٌۢ  بَشَرًا مِّنۡ طِیۡنٍ ﴿۷۱﴾', 'جب تمہارے پروردگار نے فرشتوں سے کہا کہ میں مٹی سے انسان بنانے والا ہوں۔', 'جب کہا تیرے رب نے فرشتوں کو میں بناتا ہوں ایک انسان مٹی کا [۶۲]', '(Remember) when your Lord said to the angels: \"Truly, I am going to create man from clay\".', 'When your Lord said to the angels, “I am going to create man from clay.'),
(4042, 38, 72, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'فَاِذَا سَوَّیۡتُہٗ وَ نَفَخۡتُ فِیۡہِ مِنۡ رُّوۡحِیۡ فَقَعُوۡا  لَہٗ   سٰجِدِیۡنَ ﴿۷۲﴾', 'جب میں اسکو درست کر لوں اور اس میں اپنی روح پھونک دوں تو اسکے آگے سجدے میں گر پڑنا۔', 'پھر جب ٹھیک بنا چکوں اور پھونکوں اس میں ایک اپنی جان [۶۳] تو تم گرِ  پڑو اسکے آگے سجدہ میں', 'So when I have fashioned him and breathed into him (his) soul created by Me, then you fall down prostrate to him.\"', 'So, once I make him perfectly and breath My spirit into him, you must fall down in prostration before him.”'),
(4043, 38, 73, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'فَسَجَدَ الۡمَلٰٓئِکَۃُ  کُلُّہُمۡ  اَجۡمَعُوۡنَ ﴿ۙ۷۳﴾', 'سو تمام فرشتوں نے سجدہ کیا۔', 'پھر سجدہ کیا فرشتوں نے سب نے اکھٹے ہو کر', 'So the angels prostrated themselves, all of them:', 'Then, the angels prostrated themselves, all of them together -'),
(4044, 38, 74, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'اِلَّاۤ  اِبۡلِیۡسَ ؕ اِسۡتَکۡبَرَ وَ کَانَ مِنَ الۡکٰفِرِیۡنَ ﴿۷۴﴾', 'مگر ابلیس کہ وہ اکڑ بیٹھا اور کافروں میں ہو گیا۔', 'مگر ابلیس نے [۶۴] غرور کیا اور تھا وہ منکروں میں [۶۵]', 'Except Iblees (Satan) he was proud and was one of the disbelievers.', 'except Iblīs (Satan). He waxed proud, and became one of the disbelievers.'),
(4045, 38, 75, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'قَالَ یٰۤاِبۡلِیۡسُ مَا مَنَعَکَ اَنۡ تَسۡجُدَ لِمَا خَلَقۡتُ بِیَدَیَّ ؕ اَسۡتَکۡبَرۡتَ اَمۡ کُنۡتَ مِنَ  الۡعَالِیۡنَ ﴿۷۵﴾', 'اللہ نے فرمایا کہ اے ابلیس جس شخص کو میں نے اپنے ہاتھوں سے بنایا اسکے آگے سجدہ کرنے سے تجھے کس چیز نے منع کیا۔ کیا تو غرور میں آ گیا یا اونچے درجے والوں میں تھا؟', 'فرمایا اے ابلیس کس چیز نے روک دیا تجھ کو کہ سجدہ کرے اس کو جس کو میں نے بنایا اپنے دونوں ہاتھوں سے [۶۶] یہ تو نے غرور کیا یا تو بڑا تھا درجہ میں [۶۷]', '(Allah) said: \"O Iblees (Satan)! What prevents you from prostrating yourself to one whom I have created with Both My Hands. Are you too proud (to fall prostrate to Adam) or are you one of the high exalted?\"', 'He (Allah) said, “O Iblīs, what did prevent you from prostrating yourself before what I created with My hands? Did you wax proud or were you among the lofty ones?”'),
(4046, 38, 76, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'قَالَ  اَنَا خَیۡرٌ  مِّنۡہُ ؕ خَلَقۡتَنِیۡ  مِنۡ نَّارٍ وَّ  خَلَقۡتَہٗ  مِنۡ  طِیۡنٍ ﴿۷۶﴾', 'بولا کہ میں اس سے بہتر ہوں کہ تو نے مجھ کو آگ سے پیدا کیا اور اسے مٹی سے بنایا۔', 'بولا میں بہتر ہوں اس سے مجھ کو بنایا تو نے آگ سے اور اس کو بنایا مٹی سے [۶۸]', '(Iblees (Satan)) said: \"I am better than he, You created me from fire, and You created him from clay.\"', 'He said, “I am better than him. You created me from fire, and created him from clay.”'),
(4047, 38, 77, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'قَالَ فَاخۡرُجۡ  مِنۡہَا فَاِنَّکَ  رَجِیۡمٌ ﴿ۚۖ۷۷﴾', 'فرمایا بس یہاں سے نکل جا تو مردود ہے۔', 'فرمایا تو تو نکل یہاں سے کہ تو مردود ہوا [۶۹]', '(Allah) said: \"Then get out from here, for verily, you are outcast.', 'He said, “Then, get out from here, for you are accursed,'),
(4048, 38, 78, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَّ اِنَّ عَلَیۡکَ لَعۡنَتِیۡۤ  اِلٰی یَوۡمِ الدِّیۡنِ ﴿۷۸﴾', 'اور تجھ پر قیامت کے دن تک میری لعنت پڑتی رہے گی۔', 'اور تجھ پر میری پھٹکار ہے اس جزا کے دن تک [۷۰]', '\"And verily!, My Curse is on you till the Day of Recompense.\"', 'and on you shall remain My curse till the Day of Judgment.”'),
(4049, 38, 79, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'قَالَ رَبِّ فَاَنۡظِرۡنِیۡۤ  اِلٰی یَوۡمِ یُبۡعَثُوۡنَ ﴿۷۹﴾', 'کہنے لگا کہ میرے پروردگار اچھا تو مجھے اس روز تک کہ لوگ اٹھائے جائیں مہلت دے۔', 'بولا اے رب مجھ کو ڈھیل دے جس دن تک کہ مردے جی اٹھیں [۷۱]', '(Iblees (Satan)) said: \"My Lord! Give me then respite till the Day the (dead) are resurrected.\"', 'He said, “O my Lord, then give me respite till the day they are raised again.”'),
(4050, 38, 80, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'قَالَ  فَاِنَّکَ مِنَ الۡمُنۡظَرِیۡنَ ﴿ۙ۸۰﴾', 'فرمایا کہ تجھ کو مہلت دی جاتی ہے۔', 'فرمایا تو تجھ کو ڈھیل ہے', '(Allah) said: \"Verily! You are of those allowed respite', 'He said, “Then, you have been given respite,'),
(4051, 38, 81, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'اِلٰی یَوۡمِ الۡوَقۡتِ الۡمَعۡلُوۡمِ ﴿۸۱﴾', 'اس روز تک جس کا وقت مقرر ہے۔', 'اسی وقت کے دن تک جو معلوم ہے [۷۲]', 'Till the Day of the time appointed.\"', 'until the Day of the Appointed Time.”'),
(4052, 38, 82, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'قَالَ فَبِعِزَّتِکَ لَاُغۡوِیَنَّہُمۡ اَجۡمَعِیۡنَ ﴿ۙ۸۲﴾', 'کہنے لگا کہ مجھے تیری عزت کی قسم میں ان سب کو بہکاتا رہوں گا۔', 'بولا تو قسم ہے تیری عزت کی میں گمراہ کروں گا ان سب کو', '(Iblees (Satan)) said: \"By Your Might, then I will surely mislead them all,', 'He said, “Then, I swear by Your Might, that I will definitely lead them astray, all of them -'),
(4053, 38, 83, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'اِلَّا عِبَادَکَ مِنۡہُمُ  الۡمُخۡلَصِیۡنَ ﴿۸۳﴾', 'سوائے انکے جو تیرے چنے ہوئے بندے ہیں۔', 'مگر جو بندے ہیں تیرے ان میں چنے ہوئے', '\"Except Your chosen slaves amongst them (faithful, obedient, true believers of Islamic Monotheism).\"', 'except Your chosen servants among them.”'),
(4054, 38, 84, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'قَالَ  فَالۡحَقُّ ۫ وَ الۡحَقَّ  اَقُوۡلُ ﴿ۚ۸۴﴾', 'فرمایا ٹھیک ہے اور میں ٹھیک ہی کہتا ہوں۔', 'فرمایا تو ٹھیک بات یہ ہے اور میں ٹھیک ہی کہتا ہوں [۷۳]', '(Allah) said: \"The Truth is, and the Truth I say,', 'He (Allah) said, “Then, the truth is-and it is (always) the truth that I speak-'),
(4055, 38, 85, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'لَاَمۡلَـَٔنَّ جَہَنَّمَ مِنۡکَ وَ مِمَّنۡ تَبِعَکَ مِنۡہُمۡ  اَجۡمَعِیۡنَ  ﴿۸۵﴾', 'کہ میں تجھ سے اور جو ان میں سے تیری پیروی کریں گے سب سے جہنم کو بھر دوں گا۔', 'مجھ کو بھرنا ہے دوزخ تجھ سے اور جو ان میں تیری راہ چلے ان سب سے', 'That I will fill Hell with you (Iblees (Satan)) and those of them (mankind) that follow you, together.\"', 'that I will definitely fill the Jahannam with you and with those who will follow you from among them, all together.”'),
(4056, 38, 86, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'قُلۡ مَاۤ  اَسۡـَٔلُکُمۡ عَلَیۡہِ مِنۡ  اَجۡرٍ وَّ مَاۤ  اَنَا مِنَ الۡمُتَکَلِّفِیۡنَ ﴿۸۶﴾', 'اے پیغمبر کہدو کہ میں تم سے اس کا صلہ نہیں مانگتا اور نہ میں بناوٹ کرنے والوں میں ہوں۔', 'تو کہہ میں مانگتا نہیں تم سے اس پر کچھ بدلا اور میں نہیں اپنے آپ کو بنانے والا', 'Say (O Muhammad SAW): \"No wage do I ask of you for this (the Quran), nor am I one of the Mutakallifoon (those who pretend and fabricate things which do not exist).', 'Say (O Prophet to the unbelievers,) “I do not demand from you any fee for it, nor am I from among those who make up things artificially.'),
(4057, 38, 87, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'اِنۡ  ہُوَ   اِلَّا  ذِکۡرٌ   لِّلۡعٰلَمِیۡنَ ﴿۸۷﴾', 'یہ قرآن تو اہل عالم کے لئے نصیحت ہے۔', 'یہ تو ایک فہمائش  ہے سارے جہان والوں کو', '\"It (this Quran) is only a Reminder for all the Alameen (mankind and jinns).', 'It is nothing but an advice for all the worlds.'),
(4058, 38, 88, 5, 14, 23, 'وَ مَا لِیَ ', 'صٓ', 'وَ  لَتَعۡلَمُنَّ  نَبَاَہٗ  بَعۡدَ حِیۡنٍ ﴿٪۸۸﴾', 'اور تمکو اس کا حال کچھ وقت کے بعد معلوم ہو جائے گا۔', 'اور معلوم کر لو گے  اس کا احوال تھوڑی دیر کے پیچھے [۷۴]', '\"And you shall certainly know the truth of it after a while.\"', 'And you will come to know its reality after a while.”'),
(4059, 39, 1, 1, 15, 23, 'وَ مَا لِیَ ', 'الزمر', 'تَنۡزِیۡلُ  الۡکِتٰبِ مِنَ اللّٰہِ  الۡعَزِیۡزِ الۡحَکِیۡمِ ﴿۱﴾', 'اس کتاب کا اتارا جانا اللہ کی طرف سے ہے جو غالب ہے حکمت والا ہے۔', 'اتارنا ہے کتاب کا اللہ سے جو زبردست ہے حکمتوں والا [۱]', 'The revelation of this Book (the Quran) is from Allah, the All-Mighty, the All-Wise.', 'This is the revelation of the Book from Allah, the Mighty, the Wise.'),
(4060, 39, 2, 1, 15, 23, 'وَ مَا لِیَ ', 'الزمر', 'اِنَّاۤ  اَنۡزَلۡنَاۤ  اِلَیۡکَ الۡکِتٰبَ بِالۡحَقِّ فَاعۡبُدِ اللّٰہَ  مُخۡلِصًا لَّہُ  الدِّیۡنَ ؕ﴿۲﴾', 'اے پیغمبر ہم نے یہ کتاب تمہاری طرف سچائی کے ساتھ نازل کی ہے تو اللہ کی عبادت کرو یعنی اسکی عبادت کو شرک سے خالص کر کے۔', 'میں نے اتاری ہے تیری طرف کتاب ٹھیک ٹھیک سو بندگی کر اللہ کی خالص کر کر اس کے واسطے بندگی', 'Verily, We have sent down the Book to you (O Muhammad SAW) in truth: So worship Allah (Alone) by doing religious deeds sincerely for Allahs sake only, (and not to show-off, and not to set up rivals with Him in worship).', 'Surely We have revealed the Book to you with truth; so worship Allah making your submission exclusive for Him.'),
(4061, 39, 3, 1, 15, 23, 'وَ مَا لِیَ ', 'الزمر', 'اَلَا لِلّٰہِ الدِّیۡنُ الۡخَالِصُ ؕ وَ الَّذِیۡنَ اتَّخَذُوۡا مِنۡ دُوۡنِہٖۤ  اَوۡلِیَآءَ ۘ مَا نَعۡبُدُہُمۡ  اِلَّا لِیُقَرِّبُوۡنَاۤ  اِلَی اللّٰہِ  زُلۡفٰی ؕ اِنَّ اللّٰہَ یَحۡکُمُ بَیۡنَہُمۡ فِیۡ مَا ہُمۡ فِیۡہِ یَخۡتَلِفُوۡنَ ۬ؕ اِنَّ اللّٰہَ  لَا یَہۡدِیۡ مَنۡ ہُوَ کٰذِبٌ  کَفَّارٌ ﴿۳﴾', 'دیکھو خالص عبادت اللہ ہی کے لئے زیبا ہے اور جن لوگوں نے اسکے سوا اور دوست بنائے ہیں وہ کہتے ہیں کہ ہم انکو اس لئے پوجتے ہیں کہ وہ ہم کو اللہ کا مقرب بنا دیں۔ تو جن باتوں میں یہ اختلاف کرتے ہیں اللہ ان میں انکا فیصلہ کر دے گا۔ بیشک اللہ اس شخص کو جو جھوٹا ناشکرا ہے ہدایت نہیں دیتا۔', 'سنتا ہے اللہ ہی کیلئے ہے بندگی خالص [۲] اور جنہوں نے  پکڑ  رکھے ہیں اس سے ورے حمایتی کہ ہم تو ان کو پوجتے ہیں اس واسطے کہ ہم کو پہنچا دیں اللہ کی طرف قریب کے درجہ میں  بیشک اللہ فیصلہ کر دے گا  ان میں جس چیز میں وہ جھگڑ رہے ہیں [۳] البتہ اللہ راہ نہیں دیتا اسکو جو ہو جھوٹا حق نہ ماننے  والا [۴]', 'Surely, the religion (i.e. the worship and the obedience) is for Allah only. And those who take Auliya (protectors and helpers) besides Him (say): \"We worship them only that they may bring us near to Allah.\" Verily, Allah will judge between them concerning that wherein they differ. Truly, Allah guides not him who is a liar, and a disbeliever.', 'Remember, Allah alone deserves the exclusive submission. As for those who have adopted guardians other than Him (saying), “We worship them for no other reason but because they would bring us near to Allah closely”, Allah will judge between them in the matters in which they are differing. Surely, Allah does not guide anyone who is liar, highly infidel.'),
(4062, 39, 4, 1, 15, 23, 'وَ مَا لِیَ ', 'الزمر', 'لَوۡ اَرَادَ  اللّٰہُ اَنۡ یَّتَّخِذَ وَلَدًا  لَّاصۡطَفٰی مِمَّا یَخۡلُقُ مَا یَشَآءُ ۙ سُبۡحٰنَہٗ ؕ ہُوَ اللّٰہُ  الۡوَاحِدُ الۡقَہَّارُ ﴿۴﴾', 'اگر اللہ کسی کو اپنا بیٹا بنانا چاہتا تو اپنی مخلوق میں سے جسکو چاہتا منتخب کر لیتا۔ وہ پاک ہے وہی ہے اللہ جو اکیلا ہے بڑا زبردست ہے۔', 'اگر اللہ چاہتا کہ اولاد کر لے تو چن لیتا اپنی خلق میں جو کچھ چاہتا وہ پاک ہے [۵] وہی ہے اللہ اکیلا دباؤ  والا [۶]', 'Had Allah willed to take a son (or offspring or children), He could have chosen whom He pleased out of those whom He created. But glory be to Him! (He is above such things). He is Allah, the One, the Irresistible.', 'Had Allah opted to have a son of His own, He would have definitely chosen anyone, as He wished, out of what He had created. (But), Pure is He. He is Allah, the Only One, the All-Dominant.'),
(4063, 39, 5, 1, 15, 23, 'وَ مَا لِیَ ', 'الزمر', 'خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ بِالۡحَقِّ ۚ یُکَوِّرُ الَّیۡلَ عَلَی النَّہَارِ وَ یُکَوِّرُ النَّہَارَ عَلَی الَّیۡلِ وَ سَخَّرَ الشَّمۡسَ وَ الۡقَمَرَ ؕ کُلٌّ یَّجۡرِیۡ لِاَجَلٍ مُّسَمًّی ؕ اَلَا ہُوَ  الۡعَزِیۡزُ  الۡغَفَّارُ ﴿۵﴾', 'اسی نے آسمانوں اور زمین کو تدبیر کے ساتھ پیدا کیا ہے۔ اور وہی رات کو دن پر لپیٹتا اور دن کو رات پر لپیٹتا ہے اور اسی نے سورج اور چاند کو کام میں لگا رکھا ہے سب ایک وقت مقرر تک چلتے رہیں گے۔ دیکھو وہی غالب ہے بخشنے والا ہے۔', 'بنائے آسمان اور زمین ٹھیک لپیٹتا ہے رات کو دن پر اور لپیٹتا ہے دن کو رات پر [۷] اور کام میں لگا دیا سورج اور چاند کو ہر ایک چلتا ہے ایک ٹھہری ہوئی مدت پر سنتا ہے وہی ہے زبردست گناہ بخشنے والا[۸]', 'He has created the heavens and the earth with truth. He makes the night to go in the day and makes the day to go in the night. And He has subjected the sun and the moon. Each running (on a fixed course) for an appointed term. Verily, He is the All-Mighty, the Oft-Forgiving.', 'He created the heavens and the earth for just purpose. He wraps the night over the day and He wraps the day over the night, and He has put the sun and the moon under His command, each one of them moving for an appointed term. Remember, He is the Mighty, the Most-Forgiving.'),
(4064, 39, 6, 1, 15, 23, 'وَ مَا لِیَ ', 'الزمر', 'خَلَقَکُمۡ مِّنۡ نَّفۡسٍ وَّاحِدَۃٍ  ثُمَّ  جَعَلَ مِنۡہَا زَوۡجَہَا وَ اَنۡزَلَ  لَکُمۡ مِّنَ الۡاَنۡعَامِ ثَمٰنِیَۃَ  اَزۡوَاجٍ ؕ یَخۡلُقُکُمۡ  فِیۡ بُطُوۡنِ اُمَّہٰتِکُمۡ  خَلۡقًا مِّنۡۢ بَعۡدِ خَلۡقٍ فِیۡ ظُلُمٰتٍ ثَلٰثٍ ؕ ذٰلِکُمُ اللّٰہُ رَبُّکُمۡ لَہُ الۡمُلۡکُ ؕ لَاۤ اِلٰہَ  اِلَّا ہُوَ ۚ فَاَنّٰی تُصۡرَفُوۡنَ ﴿۶﴾', 'اسی نے تمکو ایک جان سے پیدا کیا پھر اس سے اس کا جوڑا بنایا اور اسی نے تمہارے لئے چوپایوں میں سے آٹھ جوڑے بنائے۔ وہی تمکو تمہاری ماؤں کے پیٹ میں پہلے ایک طرح پھر دوسری طرح تین اندھیروں میں بناتا ہے یہی اللہ تمہارا پروردگار ہے اسی کی بادشاہی ہے۔ اسکے سوا کوئی معبود نہیں پھر تم کہاں بہکے جاتے ہو۔', 'بنایا تم کو ایک جی سے پھر بنایا اس سے اس کا جوڑ ا [۹] اور اتارے تمہارے واسطے چوپاؤں سے آٹھ نر مادہ [۱۰] بناتا ہے تم کو ماں کے پیٹ میں ایک طرح پر دوسری طرح کے پیچھے [۱۱] تین اندھیروں کے بیچ [۱۲] وہ اللہ ہے رب تمہارا  اسی کا راج ہے کسی کی بندگی نہیں اسکےسوائے پھر کہاں سے پھرے جاتے ہو [۱۳]', 'He created you (all) from a single person (Adam); then made from him his wife (Hawwa (Eve)). And He has sent down for you of cattle eight pairs (of the sheep, two, male and female; of the goats, two, male and female; of the oxen, two, male and female; and of the camels, two, male and female). He creates you in the wombs of your mothers, creation after creation in three veils of darkness, such is Allah your Lord. His is the kingdom, La ilaha illa Huwa (none has the right to be worshipped but He). How then are you turned away?', 'He created you from a single person, then (once this person was created,) He made his match from him, and sent down for you eight pairs of the cattle. He creates you in the wombs of your mothers, creation after creation, in three layers of darkness. That is your Allah, your Lord. To Him belongs the whole Kingdom. There is no god but He. Then, to where are you being diverted (by your whims)?'),
(4065, 39, 7, 1, 15, 23, 'وَ مَا لِیَ ', 'الزمر', 'اِنۡ  تَکۡفُرُوۡا فَاِنَّ اللّٰہَ غَنِیٌّ  عَنۡکُمۡ ۟ وَ لَا یَرۡضٰی لِعِبَادِہِ  الۡکُفۡرَ ۚ وَ اِنۡ تَشۡکُرُوۡا یَرۡضَہُ لَکُمۡ ؕ وَ لَا تَزِرُ وَازِرَۃٌ  وِّزۡرَ  اُخۡرٰی ؕ ثُمَّ  اِلٰی رَبِّکُمۡ مَّرۡجِعُکُمۡ  فَیُنَبِّئُکُمۡ بِمَا کُنۡتُمۡ تَعۡمَلُوۡنَ ؕ اِنَّہٗ  عَلِیۡمٌۢ  بِذَاتِ الصُّدُوۡرِ ﴿۷﴾', 'اگر ناشکری کرو گے تو اللہ تم سے بے نیاز ہے۔ اور وہ اپنے بندوں سے ناشکری پسند نہیں کرتا اور اگر شکر کرو گے تو وہ اسکو تمہارے لئے پسند کرتا ہے۔ اور کوئی بوجھ اٹھانے والا دوسرے کا بوجھ نہیں اٹھائے گا۔ پھر تمکو اپنے پروردگار کی طرف لوٹنا ہے۔ پھر جو کچھ تم کرتے رہے وہ تمکو بتا دے گا وہ تو دلوں کی پوشیدہ باتوں تک سے آگاہ ہے۔', 'اگر تم منکر ہو گے تو اللہ پروا نہیں رکھتا تمہاری اور پسند نہیں کرتا اپنے بندوں کا منکر ہونا [۱۴] اور اگر اس کا حق مانو گے تو اسکو تمہارے لئے پسند کرے گا [۱۵] اور نہ اٹھائے گا کوئی  اٹھانے والا بوجھ دوسرے کا [۱۶] پھر اپنے رب کی طرف تم کو جانا ہے تو وہ جتلائے گا تم کو جو تم کرتے تھے مقرر اسکو خبر ہے دلوں کی بات کی [۱۷]', 'If you disbelieve, then verily, Allah is not in need of you, He likes not disbelief for His slaves. And if you are grateful (by being believers), He is pleased therewith for you. No bearer of burdens shall bear the burden of another. Then to your Lord is your return, so He will inform you what you used to do. Verily, He is the All-Knower of that which is in (mens) breasts.', 'If you disbelieve, then, Allah does not need you at all, however He does not like for His servants to be disbelievers; and if you are grateful, He will like it for you. No one will bear the burden of someone else. Then, to your Lord is your return; so He will tell you about what you used to do. He is aware of whatever lies in the hearts.'),
(4066, 39, 8, 1, 15, 23, 'وَ مَا لِیَ ', 'الزمر', 'وَ اِذَا مَسَّ الۡاِنۡسَانَ ضُرٌّ دَعَا رَبَّہٗ مُنِیۡبًا اِلَیۡہِ  ثُمَّ  اِذَا خَوَّلَہٗ  نِعۡمَۃً  مِّنۡہُ نَسِیَ مَا کَانَ یَدۡعُوۡۤا  اِلَیۡہِ مِنۡ قَبۡلُ وَ جَعَلَ لِلّٰہِ  اَنۡدَادًا لِّیُضِلَّ عَنۡ سَبِیۡلِہٖ ؕ قُلۡ تَمَتَّعۡ بِکُفۡرِکَ  قَلِیۡلًا ٭ۖ اِنَّکَ  مِنۡ  اَصۡحٰبِ النَّارِ ﴿۸﴾', 'اور جب انسان کو تکلیف پہنچتی ہے تو اپنے پروردگار کو پکارتا ہے اسکی طرف دل سے رجوع کرتا ہے۔ پھر جب وہ اسکو اپنی طرف سے کوئی نعمت دے دیتا ہے تو جس کام کے لئے پہلے اسکو پکارتا تھا اسے بھول جاتا ہے اور اللہ کا شریک بنانے لگتا ہے تاکہ لوگوں کو اسکے رستے سے گمراہ کرے۔ کہدو کہ اے کافر نعمت اپنی ناشکری کے باوجود تھوڑا سا فائدہ اٹھا لے پھر تو تو دوزخیوں میں ہو گا۔', 'اور جب آ لگے انسان کو سختی پکارے اپنے رب کو رجوع ہو کر اسکی طرف پھر جب بخشے اسکو نعمت اپنی طرف سے بھول جائے اس کو کہ جس کے لئے پکار رہا تھا پہلے سے اور ٹھہرائے اللہ کی برابر اوروں کو تاکہ بہکائے اسکی راہ سے [۱۸] تو کہہ برت لے ساتھ اپنے کفر کے تھوڑے دنوں تو ہے دوزخ  والوں میں [۱۹]', 'And when some hurt touches man, he cries to his Lord (Allah Alone), turning to Him in repentance, but when He bestows a favour upon him from Himself, he forgets that for which he cried for before, and he sets up rivals to Allah, in order to mislead others from His Path. Say: \"Take pleasure in your disbelief for a while: surely, you are (one) of the dwellers of the Fire!\"', 'And when man is afflicted by pain, he calls his Lord turning to Him passionately. Thereafter, when He blesses him with some favor from Him, he forgets that for which he was calling Him earlier, and sets up partners for Allah, so that he leads others astray from His way. Say, “Enjoy (the pleasure of) your disbelief for a while, (then) surely, you are from among the people of the Fire.”'),
(4067, 39, 9, 1, 15, 23, 'وَ مَا لِیَ ', 'الزمر', 'اَمَّنۡ ہُوَ قَانِتٌ اٰنَآءَ  الَّیۡلِ سَاجِدًا وَّ قَآئِمًا یَّحۡذَرُ الۡاٰخِرَۃَ  وَ یَرۡجُوۡا رَحۡمَۃَ  رَبِّہٖ ؕ قُلۡ ہَلۡ  یَسۡتَوِی الَّذِیۡنَ یَعۡلَمُوۡنَ وَ الَّذِیۡنَ لَا یَعۡلَمُوۡنَ ؕ اِنَّمَا یَتَذَکَّرُ  اُولُوا الۡاَلۡبَابِ ٪﴿۹﴾', 'بھلا مشرک اچھا ہے یا وہ جو رات کے مختلف اوقات میں زمین پر پیشانی رکھ کر اور کھڑے ہو کر عبادت کرتا اور آخرت سے ڈرتا اور اپنے پروردگار کی رحمت کی امید رکھتا ہے۔ کہو بھلا جو لوگ علم رکھتے ہیں اور جو علم نہیں رکھتے کیا دونوں برابر ہو سکتے ہیں۔ پس نصیحت تو وہی حاصل کرتے ہیں جو عقلمند ہیں۔', 'بھلا ایک جو بندگی میں لگا ہوا ہے رات کی گھڑیوں میں سجدے کرتا ہوا اور کھڑا ہو اخطرہ رکھتا ہے آخرت کا اور امید رکھتا ہے اپنے رب کی مہربانی کی تو کہہ کوئی برابر ہوتے ہیں سمجھ والے اور بے سمجھ سوچتے وہی ہیں جن کو عقل ہے [۲۰]', 'Is one who is obedient to Allah, prostrating himself or standing (in prayer) during the hours of the night, fearing the Hereafter and hoping for the Mercy of his Lord (like one who disbelieves)? Say: \"Are those who know equal to those who know not?\" It is only men of understanding who will remember (i.e. get a lesson from Allahs Signs and Verses).', 'Can (such people be equal to) the one who worships during the hours of night, prostrating himself and standing, fearing the Hereafter and having hopes in his Lord’s mercy? Say, “Can those who know and those who do not know become equal?” It is only the people of understanding who are receptive of the advice.'),
(4068, 39, 10, 2, 16, 23, 'وَ مَا لِیَ ', 'الزمر', 'قُلۡ یٰعِبَادِ الَّذِیۡنَ اٰمَنُوا اتَّقُوۡا رَبَّکُمۡ ؕ لِلَّذِیۡنَ اَحۡسَنُوۡا فِیۡ ہٰذِہِ  الدُّنۡیَا حَسَنَۃٌ ؕ وَ اَرۡضُ اللّٰہِ  وَاسِعَۃٌ ؕ اِنَّمَا یُوَفَّی الصّٰبِرُوۡنَ  اَجۡرَہُمۡ بِغَیۡرِ حِسَابٍ ﴿۱۰﴾', 'اے نبی میرا پیغام سنا دو اے میرے بندو جو ایمان لائے ہو اپنے پروردگار سے ڈرو جن لوگوں نے اس دنیا میں نیکی کی انکے لئے بھلائی ہے اور اللہ کی زمین کشادہ ہے۔ جو صبر کرنے والے ہیں انکو بے حساب ثواب ملے گا۔', 'تو کہہ اے بندو میرے [۲۱] جو یقین لائے ہو ڈرو اپنے رب سے جنہوں نے نیکی کی اس دنیا میں انکے لئے ہی ہے بھلائی [۲۲] اور زمین اللہ کی کشادہ ہے صبر کرنے والوں ہی کو ملتا ہے ان کا ثواب بے شمار [۲۳]', 'Say (O Muhammad SAW): \"O My slaves who believe (in the Oneness of Allah Islamic Monotheism), be afraid of your Lord (Allah) and keep your duty to Him. Good is (the reward) for those who do good in this world, and Allahs earth is spacious (so if you cannot worship Allah at a place, then go to another)! Only those who are patient shall receive their rewards in full, without reckoning.\"', 'Say (on My behalf) “O My servants who believe, fear your Lord. Those who do good deeds in this world will have a good return, and the earth of Allah is wide. Certainly those who observe patience will be given their reward in full without measure.'),
(4069, 39, 11, 2, 16, 23, 'وَ مَا لِیَ ', 'الزمر', 'قُلۡ  اِنِّیۡۤ  اُمِرۡتُ اَنۡ  اَعۡبُدَ اللّٰہَ  مُخۡلِصًا  لَّہُ الدِّیۡنَ ﴿ۙ۱۱﴾', 'کہدو کہ مجھ سے ارشاد ہوا ہے کہ اللہ کی عبادت کو خالص کر کے اسکی بندگی کروں۔', 'تو کہہ مجھ کو حکم ہے کہ بندگی کروں اللہ کی خالص کر کر اسکے لئے بندگی', 'Say (O Muhammad SAW): \"Verily, I am commanded to worship Allah (Alone) by obeying Him and doing religious deeds sincerely for Allahs sake only and not to show off, and not to set up rivals with Him in worship;', 'Say, “I have been ordered to worship Allah, making my submission exclusive to Him.'),
(4070, 39, 12, 2, 16, 23, 'وَ مَا لِیَ ', 'الزمر', 'وَ اُمِرۡتُ لِاَنۡ  اَکُوۡنَ  اَوَّلَ الۡمُسۡلِمِیۡنَ ﴿۱۲﴾', 'اور یہ بھی ارشاد ہوا ہے کہ سب سے پہلے میں فرمانبردار بن جاؤں۔', 'اور حکم ہے کہ میں ہوں سب سے پہلے حکم بردار [۲۴]', '\"And I am commanded (this) in order that I may be the first of those who submit themselves to Allah (in Islam) as Muslims.\"', 'And I have been ordered to be the first of those who submit.”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(4071, 39, 13, 2, 16, 23, 'وَ مَا لِیَ ', 'الزمر', 'قُلۡ  اِنِّیۡۤ  اَخَافُ اِنۡ عَصَیۡتُ رَبِّیۡ  عَذَابَ یَوۡمٍ عَظِیۡمٍ ﴿۱۳﴾', 'کہدو کہ اگر میں اپنے پروردگار کا حکم نہ مانوں تو مجھے بڑے دن کے عذاب سے ڈر لگتا ہے۔', 'تو کہہ میں ڈرتا ہوں اگر حکم نہ مانوں اپنے رب کا ایک بڑے دن کے عذاب سے [۲۵]', 'Say (O Muhammad SAW): \"Verily, if I disobey my Lord, I am afraid of the torment of a great Day.\"', 'Say, “If I were to disobey my Lord, I fear the punishment of a great day.”'),
(4072, 39, 14, 2, 16, 23, 'وَ مَا لِیَ ', 'الزمر', 'قُلِ اللّٰہَ  اَعۡبُدُ  مُخۡلِصًا لَّہٗ  دِیۡنِیۡ ﴿ۙ۱۴﴾', 'کہدو کہ میں اپنے دین کو شرک سے خالص کر کے اللہ ہی کی عبادت کرتا ہوں۔', 'تو کہہ میں تو اللہ کو پوجتا ہوں خالص کر کر اپنی بندگی اس کے واسطے', 'Say (O Muhammad SAW) \"Allah Alone I worship by doing religious deeds sincerely for His sake only and not to show-off, and not to set up rivals with Him in worship.\"', 'Say, “It is Allah whom I worship, making my submission exclusive to Him.'),
(4073, 39, 15, 2, 16, 23, 'وَ مَا لِیَ ', 'الزمر', 'فَاعۡبُدُوۡا مَا شِئۡتُمۡ مِّنۡ دُوۡنِہٖ ؕ قُلۡ  اِنَّ الۡخٰسِرِیۡنَ الَّذِیۡنَ خَسِرُوۡۤا  اَنۡفُسَہُمۡ وَ اَہۡلِیۡہِمۡ یَوۡمَ الۡقِیٰمَۃِ ؕ اَلَا ذٰلِکَ ہُوَ الۡخُسۡرَانُ  الۡمُبِیۡنُ ﴿۱۵﴾', 'اب تم اسکے سوا جسکی چاہو پرستش کرو۔ کہدو کہ نقصان اٹھانے والے تو وہی لوگ ہیں جنہوں نے قیامت کے دن اپنے آپکو اور اپنے گھر والوں کو نقصان میں ڈالا۔ دیکھو یہی سرا سر نقصان ہے۔', 'اب تم پوجو جس کو چاہو اسکے سوائے [۲۶] تو کہہ بڑے ہارنے والے وہ جو ہار بیٹھے اپنی جان کو اور اپنے گھر والوں کو قیامت کے دن سنتا ہے یہی ہے صریح ٹوٹا [۲۷]', 'So worship what you like besides Him. Say (O Muhammad SAW): \"The losers are those who will lose themselves and their families on the Day of Resurrection. Verily, that will be a manifest loss!\"', 'So, worship what you wish other than Him.” Say, “Indeed, the losers are those who (will) lose their selves and their people on the Day of Judgment. Beware, that is really the obvious loss.”'),
(4074, 39, 16, 2, 16, 23, 'وَ مَا لِیَ ', 'الزمر', 'لَہُمۡ مِّنۡ فَوۡقِہِمۡ ظُلَلٌ مِّنَ النَّارِ وَ مِنۡ تَحۡتِہِمۡ ظُلَلٌ ؕ ذٰلِکَ یُخَوِّفُ اللّٰہُ  بِہٖ عِبَادَہٗ ؕ یٰعِبَادِ   فَاتَّقُوۡنِ ﴿۱۶﴾', 'انکے اوپر آگ کے سائبان ہوں گے اور نیچے اسی کے فرش ہوں گے۔ یہ وہ عذاب ہے جس سے اللہ اپنے بندوں کو ڈراتا ہے۔ کہ اے میرے بندو مجھی سے ڈرتے رہو۔', 'ان کے واسطے اوپر سے بادل ہیں آگ کے اور نیچے سے بادل [۲۸] اس چیز سے ڈراتا ہے اللہ اپنے بندوں کو اے بندو میرے تو مجھ سے ڈرو [۲۹]', 'They shall have coverings of Fire, above them and covering (of Fire) beneath them; with this Allah does frighten His slaves: \"O My slaves, therefore fear Me!\"', 'For them there are canopies of fire on top of them and canopies (of fire) underneath them. That is the thing against which Allah warns His servants. “So, O servants of Mine, fear Me.”'),
(4075, 39, 17, 2, 16, 23, 'وَ مَا لِیَ ', 'الزمر', 'وَ الَّذِیۡنَ  اجۡتَنَبُوا الطَّاغُوۡتَ اَنۡ یَّعۡبُدُوۡہَا وَ اَنَابُوۡۤا  اِلَی اللّٰہِ  لَہُمُ الۡبُشۡرٰی ۚ فَبَشِّرۡ  عِبَادِ ﴿ۙ۱۷﴾', 'اور جنہوں نے اس بات سے پرہیز کیا کہ بتوں کو پوجیں اور اللہ کی طرف رجوع کیا انکے لئے بشارت ہے۔ تو میرے بندوں کو بشارت سنا دو۔', 'اور جو لوگ بچے شیطانوں سے کہ انکو  پوجیں اور  رجوع ہوئے اللہ کی طرف انکے لئے ہے خوشخبری [۳۰] سو تو خوشی سنا دے میرے بندوں کو', 'Those who avoid At-Taghoot (false deities) by not worshipping them and turn to Allah in repentance, for them are glad tidings; so announce the good news to My slaves,', 'And those who abstain from worshipping the Tāghūt and turn fervently to Allah, for them there is good news. So, give the good news to My servants'),
(4076, 39, 18, 2, 16, 23, 'وَ مَا لِیَ ', 'الزمر', 'الَّذِیۡنَ  یَسۡتَمِعُوۡنَ الۡقَوۡلَ فَیَتَّبِعُوۡنَ اَحۡسَنَہٗ ؕ اُولٰٓئِکَ الَّذِیۡنَ ہَدٰىہُمُ  اللّٰہُ وَ اُولٰٓئِکَ ہُمۡ  اُولُوا  الۡاَلۡبَابِ ﴿۱۸﴾', 'جو بات کو غور سے سنتے ہیں پھر سب سے اچھی باتوں کی پیروی کرتے ہیں۔ یہی وہ لوگ ہیں جنکو اللہ نے ہدایت دی اور یہی عقل والے ہیں۔', 'جو سنتے ہیں بات پھر چلتے ہیں اس پر جو اس میں نیک ہے [۳۱] وہی ہیں جن کو رستہ دیا اللہ نے اور  وہی ہیں عقل والے [۳۲]', 'Those who listen to the Word (good advice La ilaha ill-Allah (none has the right to be worshipped but Allah) and Islamic Monotheism, etc.) and follow the best thereof (i.e. worship Allah Alone, repent to Him and avoid Taghoot, etc.) those are (the ones) whom Allah has guided and those are men of understanding (like Zaid bin Amr bin Nufail, Salman Al-Farisi and Aboo Dhar Al-Ghifaree). (Tafsir Al-Qurtubi, Vol. 12, P. 244)', 'who listen to what is said, then, follow the best of it. Those are the ones whom Allah has guided, and those are the ones who possess understanding.'),
(4077, 39, 19, 2, 16, 23, 'وَ مَا لِیَ ', 'الزمر', 'اَفَمَنۡ حَقَّ عَلَیۡہِ کَلِمَۃُ  الۡعَذَابِ ؕ اَفَاَنۡتَ تُنۡقِذُ مَنۡ فِی النَّارِ ﴿ۚ۱۹﴾', 'بھلا جس شخص پر عذاب کا حکم صادر ہو چکا ہو۔ تو کیا تم اسے جو دوزخ میں پڑا ہو نکال سکتے ہو۔', 'بھلا جس پر ٹھیک ہو چکا عذاب کا حکم بھلا تو خلاص کر سکے گا اسکو جو آگ میں پڑ چکا [۳۳]', 'Is, then one against whom the Word of punishment justified (equal to the one who avoids evil). Will you (O Muhammad SAW) rescue him who is in the Fire?', 'So tell Me about the one for whom the word of punishment is destined, - is it you, then, who would save someone who is already in the Fire?'),
(4078, 39, 20, 2, 16, 23, 'وَ مَا لِیَ ', 'الزمر', 'لٰکِنِ الَّذِیۡنَ اتَّقَوۡا رَبَّہُمۡ لَہُمۡ غُرَفٌ مِّنۡ فَوۡقِہَا غُرَفٌ مَّبۡنِیَّۃٌ ۙ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ ۬ؕ وَعۡدَ اللّٰہِ ؕ لَا یُخۡلِفُ اللّٰہُ  الۡمِیۡعَادَ ﴿۲۰﴾', 'لیکن جو لوگ اپنے پروردگار سے ڈرتے ہیں انکے لئے اونچے اونچے محل ہیں جنکے اوپر بالاخانے بنے ہوئے ہیں۔ اور انکے نیچے نہریں بہ رہی ہیں۔ یہ اللہ کا وعدہ ہے اللہ وعدے کے خلاف نہیں کرتا۔', 'لیکن جو ڈرتے ہیں اپنے رب سے ان کے واسطے ہیں جھروکے ان کے اوپر اور جھروکے چنے ہوئے [۳۴] اور انکے نیچے بہتی ہیں ندیاں وعدہ ہو چکا اللہ کا اللہ نہیں خلاف کرتا اپنا وعدہ', 'But those who fear Allah and keep their duty to their Lord (Allah), for them are built lofty rooms; one above another under which rivers flow (i.e. Paradise). (This is) the Promise of Allah: and Allah does not fail in (His) Promise.', 'But, for those who fear their Lord, there are chambers with chambers built on top of them, with rivers running from underneath them. This is Allah’s promise. Allah does not go back on any promise.'),
(4079, 39, 21, 2, 16, 23, 'وَ مَا لِیَ ', 'الزمر', 'اَلَمۡ  تَرَ  اَنَّ اللّٰہَ اَنۡزَلَ مِنَ السَّمَآءِ  مَآءً فَسَلَکَہٗ  یَنَابِیۡعَ فِی الۡاَرۡضِ ثُمَّ یُخۡرِجُ بِہٖ زَرۡعًا مُّخۡتَلِفًا  اَلۡوَانُہٗ  ثُمَّ یَہِیۡجُ  فَتَرٰىہُ مُصۡفَرًّا ثُمَّ یَجۡعَلُہٗ  حُطَامًا ؕ اِنَّ فِیۡ  ذٰلِکَ لَذِکۡرٰی لِاُولِی الۡاَلۡبَابِ ﴿٪۲۱﴾', 'کیا تم نے نہیں دیکھا کہ اللہ آسمان سے پانی نازل کرتا پھر اسکو زمین میں چشمے بنا کر جاری کرتا پھر اس سے کھیتی اگاتا ہے جسکے طرح طرح کے رنگ ہوتے ہیں۔ پھر وہ تیار ہو جاتی ہے پس تم اسکو دیکھتے ہو کہ زرد ہو گئ ہے پھر اسے چورا چورا کر دیتا ہے۔ بیشک اس میں عقل والوں کے لئے نصیحت ہے۔', 'تو نے نہیں دیکھا کہ اللہ نے اتارا  آسمان سے پانی پھر چلا دیا وہ پانی چشموں میں زمین کے [۳۵] پھر نکالتا ہے اس سے کھیتی کئ کئ رنگ بدلتی اس پر [۳۶] پھر آئے تیاری پر تو تو دیکھے اس کا رنگ زرد پھر کر ڈالتا ہے اسکو چورا چورا بیشک اس میں نصیحت ہے عقلمندوں کے  واسطے [۳۷]', 'See you not, that Allah sends down water (rain) from the sky, and causes it to penetrate the earth, (and then makes it to spring up) as water-springs and afterward thereby produces crops of different colours, and afterward they wither and you see them turn yellow, then He makes them dry and broken pieces. Verily, in this, is a Reminder for men of understanding.', 'Have you not seen that Allah sent down water from the sky, then made it penetrate into the earth (and gush forth) in the form of springs? Then He brings forth with it crops of different colors, and afterwards they wither, and you see them turned yellow, then He makes them chaff. Surely in that there is a lesson for the people of understanding.'),
(4080, 39, 22, 3, 17, 23, 'وَ مَا لِیَ ', 'الزمر', 'اَفَمَنۡ شَرَحَ اللّٰہُ صَدۡرَہٗ  لِلۡاِسۡلَامِ  فَہُوَ عَلٰی نُوۡرٍ مِّنۡ رَّبِّہٖ ؕ فَوَیۡلٌ  لِّلۡقٰسِیَۃِ قُلُوۡبُہُمۡ مِّنۡ ذِکۡرِ اللّٰہِ ؕ اُولٰٓئِکَ فِیۡ ضَلٰلٍ مُّبِیۡنٍ ﴿۲۲﴾', 'بھلا جس شخص کا سینہ اللہ نے اسلام کے لئے کھول دیا ہو سو وہ اپنے پروردگار کی طرف سے روشنی پر ہو تو کیا وہ سخت دل کافر کی طرح ہو سکتا ہے پس ان پر افسوس ہے جنکے دل اللہ کی یاد سے غافل اور سخت ہو رہے ہیں۔ اور یہی لوگ سراسر گمراہی میں ہیں۔', 'بھلا جس کا سینہ کھول دیا اللہ نے دین اسلام کے واسطے سو وہ روشنی میں ہے اپنے رب کی طرف سے سو خرابی ہے انکو جن کے دل سخت ہیں اللہ کی یاد سے وہ پڑے پھرتے ہیں بھٹکتے صریح [۳۸]', 'Is he whose breast Allah has opened to Islam, so that he is in light from His Lord (as he who is non-Muslim)? So, woe to those whose hearts are hardened against remembrance of Allah! They are in plain error!', 'So I ask about a person whose heart Allah has opened up for Islam, and consequently he proceeds in a light from his Lord. (Can he be equal to the one whose heart is hardened?) So, woe to those whose hearts are too hard to remember Allah. Those are wandering in open error.'),
(4081, 39, 23, 3, 17, 23, 'وَ مَا لِیَ ', 'الزمر', 'اَللّٰہُ  نَزَّلَ  اَحۡسَنَ الۡحَدِیۡثِ کِتٰبًا مُّتَشَابِہًا  مَّثَانِیَ ٭ۖ تَقۡشَعِرُّ مِنۡہُ جُلُوۡدُ الَّذِیۡنَ یَخۡشَوۡنَ  رَبَّہُمۡ ۚ ثُمَّ  تَلِیۡنُ جُلُوۡدُہُمۡ وَ قُلُوۡبُہُمۡ  اِلٰی ذِکۡرِ اللّٰہِ ؕ ذٰلِکَ ہُدَی اللّٰہِ یَہۡدِیۡ بِہٖ مَنۡ یَّشَآءُ ؕ وَ مَنۡ یُّضۡلِلِ اللّٰہُ  فَمَا لَہٗ مِنۡ ہَادٍ ﴿۲۳﴾', 'اللہ نے نہایت اچھی باتیں نازل فرمائی ہیں یعنی کتاب جسکی آیتیں باہم ملتی جلتی ہیں اور دہرائی جاتی ہیں جو لوگ اپنے پروردگار سے ڈرتے ہیں انکے بدن کے رونگٹے اسے سن کر کھڑے ہو جاتے ہیں۔ پھر انکی کھالیں نرم ہو جاتی ہیں اور دل بھی نرم ہو کر اللہ کی یاد کی طرف متوجہ ہو جاتے ہیں۔ یہی اللہ کی ہدایت ہے وہ اس سے جسکو چاہتا ہے ہدایت دیتا ہے۔ اور جسکو اللہ گمراہ رہنے دے اسکو کوئی ہدایت دینے والا نہیں۔', 'اللہ نے اتاری بہتر بات کتاب کی [۳۹] آپس میں ملتی دہرائی ہوئی [۴۰] بال کھڑے ہوئے ہیں اس سے کھال  پر  ان لوگوں کے جو ڈرتے ہیں اپنے رب سے پھر نرم ہوتی ہیں ان کی کھالیں اور ان کے دل اللہ کی یاد پر [۴۱] یہ ہے راہ دینا اللہ کا اس طرح راہ دیتا ہے جس کو چاہے اور جس کو راہ بھلائے اللہ اسکو کوئی نہیں سجھانے والا [۴۲]', 'Allah has sent down the best statement, a Book (this Quran), its parts resembling each other in goodness and truth, oft-repeated. The skins of those who fear their Lord shiver from it (when they recite it or hear it). Then their skin and their heart soften to the remembrance of Allah. That is the guidance of Allah. He Guides therewith whom He pleases and whomever Allah sends astray, for him there is no guide.', 'Allah has sent down the best discourse, a book containing subjects resembling each other, mentioned again and again, shivered from which are the skins of those who have awe of their Lord. Then, their skins and their hearts become soft enough to tend to the remembrance of Allah. This is the Guidance of Allah with which He brings to the right path whomsoever He wills. As for the one whom Allah lets go astray, for him there is no one to guide.'),
(4082, 39, 24, 3, 17, 23, 'وَ مَا لِیَ ', 'الزمر', 'اَفَمَنۡ یَّتَّقِیۡ  بِوَجۡہِہٖ  سُوۡٓءَ  الۡعَذَابِ یَوۡمَ الۡقِیٰمَۃِ ؕ وَ قِیۡلَ  لِلظّٰلِمِیۡنَ ذُوۡقُوۡا مَا کُنۡتُمۡ تَکۡسِبُوۡنَ ﴿۲۴﴾', 'بھلا جو شخص قیامت کے دن اپنے چہرے پر برے عذاب کو روکتا ہو کیا وہ ویسا ہو سکتا ہے جو چین میں ہو اور ظالموں سے کہا جائے گا کہ جو کچھ تم کرتے رہے تھے اب اسکے مزے چکھو۔', 'بھلا ایک وہ جو  روکتا ہے اپنے منہ پر عذاب دن قیامت کے اور کہے گا بے انصافوں کو چکھو جو تم کماتے تھے [۴۳]', 'Is he then, who will confront with his face the awful torment on the Day of Resurrection (as he who enters peacefully in Paradise)? And it will be said to the Zalimoon (polytheists and wrong-doers, etc.): \"Taste what you used to earn!\"', 'Tell Me about the one who tries to save himself from the worst punishment with his face on the Day of Judgment, (whether he is equal to the one who is not liable to any punishment.) And it will be said to the wrongdoers, “Have a taste of what you used to earn.”'),
(4083, 39, 25, 3, 17, 23, 'وَ مَا لِیَ ', 'الزمر', 'کَذَّبَ الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ  فَاَتٰىہُمُ الۡعَذَابُ مِنۡ حَیۡثُ لَا  یَشۡعُرُوۡنَ ﴿۲۵﴾', 'جو لوگ ان سے پہلے تھے انہوں نے بھی تکذیب کی تھی تو ان پر عذاب ایسی جگہ سے آ گیا کہ انکو خبر ہی نہ تھی۔', 'جھٹلا چکے ہیں ان سے اگلے پھر پہنچا ان پر عذاب ایسی جگہ سے کہ انکو خیال بھی نہ تھا۔', 'Those before them belied, and so the torment came on them from directions they perceived not.', 'Those before them had also rejected (the messengers) and consequently, the punishment came upon them in a way that they had never imagined.'),
(4084, 39, 26, 3, 17, 23, 'وَ مَا لِیَ ', 'الزمر', 'فَاَذَاقَہُمُ  اللّٰہُ  الۡخِزۡیَ فِی الۡحَیٰوۃِ الدُّنۡیَا ۚ وَ لَعَذَابُ الۡاٰخِرَۃِ  اَکۡبَرُ ۘ لَوۡ  کَانُوۡا  یَعۡلَمُوۡنَ ﴿۲۶﴾', 'پھر انکو اللہ نے دنیا کی زندگی میں رسوائی کا مزہ چکھا دیا اور آخرت کا عذاب تو بہت ہی بڑا ہے۔ کاش یہ سمجھ رکھتے۔', 'پھر چکھائی انکو اللہ نے رسوائی دنیا کی زندگی میں اور  عذاب آخرت کا تو بہت ہی بڑا ہے اگر ان کو سمجھ ہوتی [۴۴]', 'So Allah made them to taste the disgrace in the present life, but greater is the torment of the Hereafter if they only knew!', 'Then Allah made them taste disgrace in the worldly life, and of course the punishment of the Hereafter is much greater. Only if they knew!'),
(4085, 39, 27, 3, 17, 23, 'وَ مَا لِیَ ', 'الزمر', 'وَ لَقَدۡ ضَرَبۡنَا  لِلنَّاسِ فِیۡ ہٰذَا الۡقُرۡاٰنِ مِنۡ کُلِّ  مَثَلٍ لَّعَلَّہُمۡ  یَتَذَکَّرُوۡنَ ﴿ۚ۲۷﴾', 'اور ہم نے لوگوں کے سمجھانے کے لئے اس قرآن میں ہر طرح کی مثالیں بیان کی ہیں تاکہ وہ نصیحت حاصل کریں۔', 'اور ہم نے بیان کی لوگوں کے واسطے اس قرآن میں سب چیز کی مثل تاکہ وہ دھیان کریں', 'And indeed We have put forth for men, in this Quran every kind of similitude in order that they may remember.', 'And We have cited for people all sorts of examples in this Qur’ān, so that they may receive the message'),
(4086, 39, 28, 3, 17, 23, 'وَ مَا لِیَ ', 'الزمر', 'قُرۡاٰنًا عَرَبِیًّا غَیۡرَ ذِیۡ عِوَجٍ لَّعَلَّہُمۡ یَتَّقُوۡنَ ﴿۲۸﴾', 'یہ قرآن عربی ہے جس میں کوئی عیب اور اختلاف نہیں تاکہ وہ ڈر مانیں۔', 'قرآن ہے عربی زبان کا جس میں کجی نہیں تاکہ وہ بچ کر چلیں [۴۵]', 'An Arabic Quran, without any crookedness (therein) in order that they may avoid all evil which Allah has ordered them to avoid, fear Him and keep their duty to Him.', 'through an Arabic Qur’ān that has no digression (from the truth), so that they may be God-fearing.'),
(4087, 39, 29, 3, 17, 23, 'وَ مَا لِیَ ', 'الزمر', 'ضَرَبَ اللّٰہُ  مَثَلًا رَّجُلًا فِیۡہِ  شُرَکَآءُ مُتَشٰکِسُوۡنَ وَ رَجُلًا سَلَمًا  لِّرَجُلٍ ؕ ہَلۡ  یَسۡتَوِیٰنِ مَثَلًا ؕ اَلۡحَمۡدُ لِلّٰہِ ۚ بَلۡ اَکۡثَرُہُمۡ  لَا یَعۡلَمُوۡنَ ﴿۲۹﴾', 'اللہ ایک مثال بیان کرتا ہے کہ ایک شخص ہے جس میں کئی آدمی شریک ہیں۔ مختلف مزاج کے اور ایک آدمی پورے کا پورا ایک شخص کا غلام ہے۔ بھلا دونوں کی حالت برابر ہے؟ نہیں الحمدللہ مگر یہ اکثر لوگ نہیں جانتے۔', 'اللہ نے بتلائی ایک مثل ایک مرد ہے کہ اس میں شریک ہیں کئ ضدی اور ایک مرد ہے پورا ایک شخص کا کیا برابر ہوتی ہیں دونوں مثل [۴۶] سب خوبی اللہ کے لئے ہے  پر وہ بہت لوگ سمجھ نہیں رکھتے [۴۷]', 'Allah puts forth a similitude: a (slave) man belonging to many partners (like those who worship others along with Allah) disputing with one another, and a (slave) man belonging entirely to one master, (like those who worship Allah Alone). Are those two equal in comparison? All the praises and thanks be to Allah! But most of them know not.', 'Allah has given an example: There is a man (enslaved and) owned by some partners having rivalry with each other, and (on the other hand,) there is a man solely owned by a single man. Can they be equal in comparison? Praise be to Allah! (The truth stands established). But, most of them do not know.'),
(4088, 39, 30, 3, 17, 23, 'وَ مَا لِیَ ', 'الزمر', 'اِنَّکَ مَیِّتٌ وَّ  اِنَّہُمۡ  مَّیِّتُوۡنَ ﴿۫۳۰﴾', 'اے پیغمبر تم بھی مرنے والے ہو اور یہ بھی مرنے والے ہیں۔', 'بیشک تو بھی مرتا ہے اور وہ بھی مرتے ہیں', 'Verily, you (O Muhammad SAW) will die and verily, they (too) will die.', 'Verily, you are to die and they are to die.'),
(4089, 39, 31, 3, 17, 23, 'وَ مَا لِیَ ', 'الزمر', 'ثُمَّ  اِنَّکُمۡ  یَوۡمَ الۡقِیٰمَۃِ عِنۡدَ رَبِّکُمۡ تَخۡتَصِمُوۡنَ ﴿٪۳۱﴾', 'پھر تم سب قیامت کے دن اپنے پروردگار کے سامنے جھگڑو گے۔', 'پھر مقرر  تم قیامت کے دن اپنے رب کے آگے جھگڑو گے [۴۸]', 'Then, on the Day of Resurrection, you will be disputing before your Lord.', 'After that, on the Day of Doom, you will surely place your disputes before your Lord.'),
(4090, 39, 32, 4, 1, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'فَمَنۡ اَظۡلَمُ  مِمَّنۡ  کَذَبَ عَلَی اللّٰہِ وَ  کَذَّبَ بِالصِّدۡقِ اِذۡ جَآءَہٗ ؕ اَلَیۡسَ فِیۡ جَہَنَّمَ مَثۡوًی  لِّلۡکٰفِرِیۡنَ ﴿۳۲﴾', 'پھر اس سے بڑھ کر ظالم کون جو اللہ پر جھوٹ بولے اور سچی بات جب اسکے پاس پہنچ جائے تو اسے جھٹلائے۔ کیا جہنم میں کافروں کا ٹھکانہ نہیں ہے؟', 'پھر اس سے زیادہ ظالم کون  جس نے جھوٹ بولا اللہ پر اور جھٹلایا سچی بات کو جب پہنچی اس کے پاس کیا نہیں دوزخ میں ٹھکانہ منکروں کا [۴۹]', 'Then, who does more wrong than one who utters a lie against Allah, and denies the truth (this Quran, the Prophet (Muhammad SAW), the Islamic Monotheism, the Resurrection and the reward or punishment according to good or evil deeds) when it comes to him! Is there not in Hell an abode for the disbelievers?', 'So, who is more unjust than him who forges a lie against Allah and rejects the truth when it reached him? Is it not that in Jahannam (Hell) there is an abode for the disbelievers?'),
(4091, 39, 33, 4, 1, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ الَّذِیۡ جَآءَ  بِالصِّدۡقِ وَ صَدَّقَ بِہٖۤ اُولٰٓئِکَ ہُمُ  الۡمُتَّقُوۡنَ ﴿۳۳﴾', 'اور جو شخص سچی بات لے کر آیا اور جس نے اسکی تصدیق کی وہی لوگ متقی ہیں۔', 'اور جو لے کر آیا سچی بات اور سچ مانا جس نے اسکو  وہی لوگ ہیں ڈر  والے [۵۰]', 'And he (Muhammad SAW) who has brought the truth (this Quran and Islamic Monotheism) and (those who) believed therein (i.e. the true believers of Islamic Monotheism), those are Al- Muttaqoon (the pious and righteous persons - see V.2:2).', 'As for the one who has come with the truth and believed it to be true, then such people are the ones who are God-fearing.'),
(4092, 39, 34, 4, 1, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'لَہُمۡ مَّا یَشَآءُوۡنَ عِنۡدَ  رَبِّہِمۡ ؕ ذٰلِکَ جَزٰٓؤُا الۡمُحۡسِنِیۡنَ ﴿ۚۖ۳۴﴾', 'وہ جو چاہیں گے انکے لئے انکے پروردگار کے پاس موجود ہے نیکوکاروں کا یہی بدلہ ہے۔', 'ان کے لئے ہے جو وہ چاہیں اپنے رب کے پاس یہ ہے بدلا نیکی والوں کا', 'They shall have all that they will desire with their Lord. That is the reward of Muhsinoon (good-doers - see V.2:112).', 'For them, with their Lord, there is what they wish. That is the reward of those who are good in their deeds,'),
(4093, 39, 35, 4, 1, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'لِیُکَفِّرَ اللّٰہُ  عَنۡہُمۡ  اَسۡوَاَ الَّذِیۡ عَمِلُوۡا وَ یَجۡزِیَہُمۡ  اَجۡرَہُمۡ  بِاَحۡسَنِ الَّذِیۡ کَانُوۡا یَعۡمَلُوۡنَ ﴿۳۵﴾', 'تاکہ اللہ ان سے برائیوں کو جو انہوں نے کیں دور کر دے اور نیک کاموں کا جو وہ کرتے رہے انکو بدلہ دے۔', 'تاکہ اتار دے اللہ ان پر سے برے کام جو انہوں نے کئے تھے اور بدلہ میں دے ان کو ثواب بہتر کاموں کا جو وہ کرتے تھے [۵۱]', 'So that Allah may remit from them the evil of what they did and give them the reward, according to the best of what they used to do.', 'so that Allah wipes out from them the worst deeds they did, and gives their reward to them for the best of what they used to do.'),
(4094, 39, 36, 4, 1, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'اَلَیۡسَ اللّٰہُ  بِکَافٍ عَبۡدَہٗ ؕ وَ  یُخَوِّفُوۡنَکَ بِالَّذِیۡنَ مِنۡ دُوۡنِہٖ ؕ وَ مَنۡ یُّضۡلِلِ اللّٰہُ  فَمَا  لَہٗ  مِنۡ ہَادٍ ﴿ۚ۳۶﴾', 'کیا اللہ اپنے بندے کو کافی نہیں؟ اور اے نبی یہ تمکو ان لوگوں سے جو اللہ کے سوا ہیں یعنی غیر اللہ سے ڈراتے ہیں۔ اور جسکو اللہ گمراہ رہنے دے اسے کوئی ہدایت دینے والا نہیں۔', 'کیا اللہ بس نہں اپنے بندہ کو اور تجھ کو ڈراتے ہیں ان سے جو اس کے سوائے ہیں اور جسکو  راہ بھلائے اللہ تو کوئی نہیں اسکو راہ دینے والا', 'Is not Allah Sufficient for His slave? Yet they try to frighten you with those (whom they worship) besides Him! And whom Allah sends astray, for him there will be no guide.', 'Is Allah not sufficient for (the protection of) His slave? They are frightening you of those (false gods whom they worship) other than Him. Whomsoever Allah would let go astray, for him there is no one to guide.'),
(4095, 39, 37, 4, 1, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ مَنۡ یَّہۡدِ اللّٰہُ  فَمَا لَہٗ مِنۡ مُّضِلٍّ ؕ اَلَیۡسَ اللّٰہُ  بِعَزِیۡزٍ  ذِی انۡتِقَامٍ ﴿۳۷﴾', 'اور جسکو اللہ ہدایت دے اسکو کوئی گمراہ کرنے والا نہیں۔ کیا اللہ عزت والا بدلہ لینے والا نہیں ہے؟', 'اور جسکو  راہ سجھائے اللہ تو کوئی نہیں اسکو بھلانے والا کیا نہیں ہے اللہ زبردست بدلہ لینے والا [۵۲]', 'And whomsoever Allah guides, for him there will be no misleader. Is not Allah All-Mighty, Possessor of Retribution?', 'And whomsoever Allah gives guidance, for him there is no one to misguide. Is it not that Allah is Mighty, Powerful to avenge?'),
(4096, 39, 38, 4, 1, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ لَئِنۡ سَاَلۡتَہُمۡ مَّنۡ خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ لَیَقُوۡلُنَّ  اللّٰہُ ؕ قُلۡ  اَفَرَءَیۡتُمۡ مَّا تَدۡعُوۡنَ مِنۡ دُوۡنِ اللّٰہِ  اِنۡ  اَرَادَنِیَ اللّٰہُ بِضُرٍّ ہَلۡ  ہُنَّ کٰشِفٰتُ ضُرِّہٖۤ  اَوۡ اَرَادَنِیۡ  بِرَحۡمَۃٍ  ہَلۡ ہُنَّ مُمۡسِکٰتُ رَحۡمَتِہٖ ؕ قُلۡ حَسۡبِیَ اللّٰہُ ؕ عَلَیۡہِ یَتَوَکَّلُ  الۡمُتَوَکِّلُوۡنَ  ﴿۳۸﴾', 'اور اگر تم ان سے پوچھو کہ آسمانوں اور زمین کو کس نے پیدا کیا تو کہدیں گے کہ اللہ نے۔ کہو کہ بھلا دیکھو تو جنکو تم اللہ کے سوا پکارتے ہو اگر اللہ مجھکو کوئی تکلیف پہنچانی چاہے تو کیا وہ اس تکلیف کو دور کر سکتے ہیں یا وہ اگر مجھ پر مہربانی کرنا چاہے تو کیا وہ اسکی مہربانی کو روک سکتے ہیں؟ کہدو کہ مجھے اللہ ہی کافی ہے۔ بھروسہ رکھنے والے اسی پر بھروسہ رکھتے ہیں۔', 'اور جو تو ان سے پوچھے کس نے بنائے آسمان اور زمین تو کہیں اللہ نے تو کہہ بھلا دیکھو تو جن کو پوجتے ہو اللہ کے سوائے اگر چاہے اللہ مجھ پر کچھ تکلیف تو وہ ایسے ہیں کہ کھول دیں تکلیف اسکی ڈالی ہوئی یا وہ چاہے مجھ پر مہربانی تو وہ ایسے ہیں کہ روک دیں اسکی مہربانی کو تو کہہ مجھ کو بس ہے اللہ اسی پر بھروسہ رکھتے ہیں بھروسہ رکھنے والے [۵۳]', 'And verily, if you ask them: \"Who created the heavens and the earth?\" Surely, they will say: \"Allah (has created them).\" Say: \"Tell me then, the things that you invoke besides Allah, if Allah intended some harm for me, could they remove His harm, or if He (Allah) intended some mercy for me, could they withhold His Mercy?\" Say : \"Sufficient for me is Allah; in Him those who trust (i.e. believers) must put their trust.\"', 'If you ask them as to who created the heavens and the earth, they will certainly say, “Allah.” Say, “Then, tell me about those whom you invoke other than Allah, if Allah intends to cause some harm to me, are they (able) to remove the harm caused by Him? Or if He intends to bless me with mercy, are they (able) to hold back His mercy (from me)?” Say, “Allah is sufficient for me. In Him trust those who (rightly) trust (in someone).”'),
(4097, 39, 39, 4, 1, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'قُلۡ یٰقَوۡمِ اعۡمَلُوۡا عَلٰی مَکَانَتِکُمۡ  اِنِّیۡ عَامِلٌ ۚ فَسَوۡفَ تَعۡلَمُوۡنَ ﴿ۙ۳۹﴾', 'کہدو کہ اے قوم تم اپنی جگہ عمل کئے جاؤ میں اپنی جگہ عمل کئے جاتا ہوں۔ عنقریب تمکو معلوم ہو جائے گا۔', 'تو کہہ اے قوم کام کئے جاؤ اپنی جگہ پر میں بھی کام کرتا ہوں اب آگے جان لو گے', 'Say: (O Muhammad SAW) \"O My people! Work according to your way, I am working (according to my way). Then you will come to know,', 'Say, “O my people, do at your place (what you are doing). I am to do (what I have been ordered to). Very soon, you will come to know'),
(4098, 39, 40, 4, 1, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'مَنۡ یَّاۡتِیۡہِ عَذَابٌ یُّخۡزِیۡہِ  وَ یَحِلُّ عَلَیۡہِ  عَذَابٌ  مُّقِیۡمٌ ﴿۴۰﴾', 'کہ کس پر عذاب آتا ہے جو اسے رسوا کرے گا۔ اور کس پر ہمیشہ کا عذاب نازل ہوتا ہے۔', 'کس پر آتی ہے آفت کہ اس کو رسوا کرے اور اترتا ہے اس پر عذاب سدا رہنے والا [۵۴]', '\"To whom comes a disgracing torment, and on whom descends an everlasting torment.\"', 'as to who will be visited by a punishment that will disgrace him, and upon whom a lasting punishment will rest.'),
(4099, 39, 41, 4, 1, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'اِنَّاۤ  اَنۡزَلۡنَا عَلَیۡکَ الۡکِتٰبَ لِلنَّاسِ بِالۡحَقِّ ۚ فَمَنِ اہۡتَدٰی فَلِنَفۡسِہٖ ۚ وَ مَنۡ ضَلَّ  فَاِنَّمَا یَضِلُّ عَلَیۡہَا  ۚ وَ  مَاۤ  اَنۡتَ عَلَیۡہِمۡ  بِوَکِیۡلٍ ﴿٪۴۱﴾', 'ہم نے تم پر یہ کتاب لوگوں کی ہدایت کے لئے سچائی کے ساتھ نازل کی ہے۔ تو جو شخص ہدایت پاتا ہے تو اپنے بھلے کے لئے اور جو گمراہ ہوتا ہے تو گمراہی سے اپنا ہی نقصان کرتا ہے۔ اور اے پیغمبر تم انکے ذمہ دار نہیں ہو۔', 'ہم نے اتاری ہے تجھ پر کتاب لوگوں کے واسطے سچے دین کے ساتھ پھر جو کوئی راہ پر آیا سو اپنے بھلے کو اور جو کوئی بہکا سو یہی بات ہے کہ بہکا اپنے برے کو اور تو ان کا ذمہ دار نہیں [۵۵]', 'Verily, We have sent down to you (O Muhammad SAW) the Book (this Quran) for mankind in truth. So whosoever accepts the guidance, it is only for his ownself, and whosoever goes astray, he goes astray only for his (own) loss. And you (O Muhammad SAW) are not a Wakeel (trustee or disposer of affairs, or keeper) over them.', 'We have sent down to you the Book for the people with truth. So, whoever follows the guidance, it is for his own good, and whoever goes astray, he will go astray only to his own detriment - and you are not responsible for them.'),
(4100, 39, 42, 5, 2, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'اَللّٰہُ  یَتَوَفَّی الۡاَنۡفُسَ حِیۡنَ مَوۡتِہَا وَ الَّتِیۡ لَمۡ تَمُتۡ فِیۡ مَنَامِہَا ۚ فَیُمۡسِکُ الَّتِیۡ قَضٰی عَلَیۡہَا الۡمَوۡتَ وَ یُرۡسِلُ الۡاُخۡرٰۤی  اِلٰۤی اَجَلٍ مُّسَمًّی ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیٰتٍ  لِّقَوۡمٍ  یَّتَفَکَّرُوۡنَ ﴿۴۲﴾', 'اللہ لوگوں کے مرنے کے وقت انکی روحیں قبض کر لیتا ہے اور جو مرے نہیں انکی روحیں سوتے میں قبض کر لیتا ہے پھر جن پر موت کا حکم کر چکتا ہے انکو روک رکھتا ہے اور باقی روحوں کو ایک وقت مقرر تک کے لئے چھوڑ دیتا ہے۔ جو لوگ غور و فکر کرتے ہیں انکے لئے اس میں نشانیاں ہیں۔', 'اللہ کھینچ لیتا ہے جانیں جب وقت ہو انکے مرنے کا اور جو نہیں مریں انکو کھینچ لیتا ہے انکی نیند میں پھر  رکھ چھوڑتا ہے جن پر مرنا ٹھہرا دیا ہے بھیج دیتا ہے اوروں کو  ایک وعدہ مقرر تک اس بات میں پتے ہیں ان لوگوں کو جو دھیان کریں [۵۶]', 'It is Allah Who takes away the souls at the time of their death, and those that die not during their sleep. He keeps those (souls) for which He has ordained death and sends the rest for a term appointed. Verily, in this are signs for a people who think deeply.', 'Allah fully takes away the souls (of the people) at the time of their death, and (of) those who do not die, in their sleep. Then He withholds those on whom He had decreed death, and sends others back, up to an appointed term. Surely, in this, there are signs for a people who ponder.'),
(4101, 39, 43, 5, 2, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'اَمِ اتَّخَذُوۡا مِنۡ دُوۡنِ اللّٰہِ شُفَعَآءَ ؕ قُلۡ اَوَ لَوۡ کَانُوۡا  لَا یَمۡلِکُوۡنَ شَیۡئًا وَّ لَا یَعۡقِلُوۡنَ ﴿۴۳﴾', 'کیا انہوں نے اللہ کے سوا اور سفارشی بنا لئے ہیں۔ کہو کہ خواہ وہ کسی چیز کا بھی اختیار نہ رکھتے ہوں اور نہ کچھ سمجھتے ہی ہوں تب بھی۔', 'کیا انہوں نے پکڑے ہیں اللہ کے سوائے کوئی سفارش والے [۵۷] تو کہہ اگرچہ ان کو اختیار نہ ہو کسی چیز کا اور نہ سمجھ [۵۸]', 'Have they taken others as intercessors besides Allah? Say: \"Even if they have power over nothing whatever and have no intelligence?\"', 'Is it that they have adopted intercessors out of those (whom they invoke) other than Allah? Say, “(Do you take them as intercessors) even though they have no power at all, nor do they understand?”'),
(4102, 39, 44, 5, 2, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'قُلۡ  لِّلّٰہِ  الشَّفَاعَۃُ  جَمِیۡعًا ؕ لَہٗ  مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ ثُمَّ  اِلَیۡہِ تُرۡجَعُوۡنَ ﴿۴۴﴾', 'کہدو کہ سفارش تو سب اللہ ہی کے اختیار میں ہے۔ اسی کے لئے آسمانوں اور زمین کی بادشاہت ہے۔ پھر تم اسی کی طرف لوٹ کر جاؤ گے۔', 'تو کہہ اللہ کے اختیار میں ہے ساری سفارش اسی کا راج ہے آسمان اور زمین میں پھر اسی کی طرف پھیرے جاؤ گے [۵۹]', 'Say: \"To Allah belongs all intercession. His is the Sovereignty of the heavens and the earth, then to Him you shall be brought back.\"', 'Say, “Intercession belongs entirely to Allah.”'),
(4103, 39, 45, 5, 2, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ  اِذَا ذُکِرَ اللّٰہُ  وَحۡدَہُ  اشۡمَاَزَّتۡ قُلُوۡبُ الَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِالۡاٰخِرَۃِ ۚ وَ اِذَا ذُکِرَ الَّذِیۡنَ مِنۡ دُوۡنِہٖۤ  اِذَا ہُمۡ یَسۡتَبۡشِرُوۡنَ ﴿۴۵﴾', 'اور جب ایک اکیلے اللہ کا ذکر کیا جاتا ہے تو جو لوگ آخرت پر ایمان نہیں رکھتے انکے دل گھٹ جاتے ہیں۔ اور جب اللہ کے سوا اوروں کا ذکر کیا جاتا ہے تو فوراً خوش ہو جاتے ہیں۔', 'اور جب نام لیجئے خالص اللہ کا رک جاتے ہیں دل انکے جو یقین نہیں رکھتے پچھلے گھر کا اور جب نام لیجئے اس کے سوا اوروں کا تب وہ لگیں خوشیاں کرنے [۶۰]', 'And when Allah Alone is mentioned, the hearts of those who believe not in the Hereafter are filled with disgust (from the Oneness of Allah () and when those (whom they obey or worship) besides Him (like all false deities other than Allah, it may be a Messenger like Iesa (Jesus) son of Maryam (Mary), Uzair (Ezra), an angel, a pious man, a jinn, or any other creature even idols, graves of religious people, saints, priests, monks, etc.) are mentioned, behold, they rejoice!', 'When Allah is mentioned alone, the hearts of those who do not believe in the Hereafter are filled with disgust, and when those (whom they worship) other than Him are mentioned, they become happy forthwith.'),
(4104, 39, 46, 5, 2, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'قُلِ اللّٰہُمَّ  فَاطِرَ السَّمٰوٰتِ وَ الۡاَرۡضِ عٰلِمَ  الۡغَیۡبِ وَ الشَّہَادَۃِ  اَنۡتَ تَحۡکُمُ بَیۡنَ عِبَادِکَ فِیۡ مَا کَانُوۡا فِیۡہِ یَخۡتَلِفُوۡنَ ﴿۴۶﴾', 'کہو کہ اے اللہ اے آسمانوں اور زمین کے پیدا کرنے والے پوشیدہ اور ظاہر کے جاننے والے تو ہی اپنے بندوں میں ان باتوں کا جن میں وہ اختلاف کرتے رہے ہیں فیصلہ کرے گا۔', 'تو کہہ اے اللہ پیدا کرنے والے آسمانوں کے اور زمین کے جاننے والے چھپے اور کھلے کے تو ہی فیصلہ کرے اپنے بندوں میں جس چیز میں وہ جھگڑ رہے تھے [۶۱]', 'Say (O Muhammad SAW): \"O Allah! Creator of the heavens and the earth! All-Knower of the Ghaib (unseen) and the seen. You will judge between your slaves about that wherein they used to differ.\"', 'Say, “O Allah, the Creator of the heavens and the earth, the Knower of the unseen and the seen, you will judge between Your servants in that about which they used to differ.'),
(4105, 39, 47, 5, 2, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ لَوۡ اَنَّ  لِلَّذِیۡنَ ظَلَمُوۡا مَا فِی الۡاَرۡضِ جَمِیۡعًا وَّ مِثۡلَہٗ  مَعَہٗ  لَافۡتَدَوۡا بِہٖ مِنۡ سُوۡٓءِ الۡعَذَابِ یَوۡمَ الۡقِیٰمَۃِ ؕ وَ  بَدَا لَہُمۡ مِّنَ اللّٰہِ  مَا لَمۡ یَکُوۡنُوۡا یَحۡتَسِبُوۡنَ ﴿۴۷﴾', 'اور اگر ظالموں کے پاس وہ سب مال و متاع ہو جو زمین میں ہے اور اسکے ساتھ اسی قدر اور ہو تو قیامت کے روز برے عذاب سے رہائی پانے کے بدلے میں دے ڈالیں۔ اور ان پر اللہ کی طرف سے وہ امر ظاہر ہو جائے گا جس کا انکو خیال بھی نہ تھا۔', 'اور اگر گنہگاروں کے پاس ہو جتنا کچھ کہ زمین میں ہے سارا اور اتنا ہی اور اسکے ساتھ تو سب دے ڈالیں اپنے چھڑوانے میں بری طرح کے عذاب سے دن قیامت کے اور نظر آئے انکو اللہ کی طرف سے جو خیال بھی نہ رکھتے تھے', 'And those who did wrong (the polytheists and disbelievers in the Oneness of Allah), if they had all that is in earth and therewith as much again, they verily, would offer it to ransom themselves therewith on the Day of Resurrection from the evil torment, and there will become apparent to them from Allah, what they had not been reckoning.', 'Were the wrongdoers to own all that is on earth, and even twice as much, they would surely seek to ransom themselves with it against the evil punishment on the Day of Judgment. There will appear to them from Allah what they have never imagined.'),
(4106, 39, 48, 5, 2, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ بَدَا لَہُمۡ سَیِّاٰتُ مَا کَسَبُوۡا  وَ حَاقَ بِہِمۡ  مَّا کَانُوۡا بِہٖ یَسۡتَہۡزِءُوۡنَ ﴿۴۸﴾', 'اور انکے اعمال کی برائیاں ان پر ظاہر ہو جائیں گی اور جس عذاب کی وہ ہنسی اڑاتے تھے وہ انکو آ گھیرے گا۔', 'اور نظر آئیں ان کو برے کام اپنے جو کماتے تھے اور الٹ پڑے ان پر وہ چیز جس پر ٹھٹھا کرتے تھے [۶۲]', 'And the evils of that which they earned will become apparent to them, and they will be encircled by that which they used to mock at!', 'Unveiled to them will be the evils of what they used to earn; and encircled they will be by what they used to ridicule.'),
(4107, 39, 49, 5, 2, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'فَاِذَا مَسَّ الۡاِنۡسَانَ ضُرٌّ دَعَانَا ۫ ثُمَّ   اِذَا خَوَّلۡنٰہُ نِعۡمَۃً  مِّنَّا ۙ قَالَ  اِنَّمَاۤ  اُوۡتِیۡتُہٗ عَلٰی عِلۡمٍ ؕ بَلۡ  ہِیَ فِتۡنَۃٌ  وَّ لٰکِنَّ  اَکۡثَرَہُمۡ  لَا یَعۡلَمُوۡنَ ﴿۴۹﴾', 'سو جب انسان کو تکلیف پہنچتی ہے تو ہمیں پکارنے لگتا ہے۔ پھر جب ہم اسکو اپنی طرف سے نعمت بخشتے ہیں تو کہتا ہے کہ یہ تو مجھے میرے علم و دانش کے سبب ملی ہے۔ نہیں بلکہ وہ آزمائش ہے مگر ان میں سے اکثر نہیں جانتے۔', 'سو جب آ لگتی ہے آدمی کو کچھ تکلیف ہم کو پکارنے لگتا ہے [۶۳] پھر جب ہم بخشیں اسکو اپنی طرف سے کوئی نعمت کہتا ہے یہ تو مجھ کو ملی کہ پہلے سے معلوم تھی [۶۴] کوئی نہیں یہ جانچ ہے پر وہ بہت سے لوگ نہیں سمجھتے [۶۵]', 'When harm touches man, he calls to Us (for help), then when We have (rescued him from that harm and) changed it into a favour from Us, he says: \"Only because of knowledge (that I possess) I obtained it.\" Nay, it is only a trial, but most of them know not!', 'When man is visited by a trouble, he prays to Us, but when, after that, We favor him with some blessing from Us, he says, “This is given to me because of (my) knowledge.” No, but this is a trial, yet most of them do not know.'),
(4108, 39, 50, 5, 2, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'قَدۡ قَالَہَا الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ  فَمَاۤ   اَغۡنٰی عَنۡہُمۡ  مَّا کَانُوۡا یَکۡسِبُوۡنَ ﴿۵۰﴾', 'جو لوگ ان سے پہلے تھے وہ بھی یہی کہا کرتے تھے تو جو کچھ وہ کیا کرتے تھے انکے کچھ کام نہ آیا۔', 'کہہ چکے ہیں یہ بات ان سے اگلے پھر کچھ کام نہ آیا انکو  جو کماتے تھے', 'Verily, those before them said it, yet (all) that they had earned availed them not.', 'The same was said by those before them, but what they used to earn was of no avail to them,'),
(4109, 39, 51, 5, 2, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'فَاَصَابَہُمۡ سَیِّاٰتُ مَا کَسَبُوۡا ؕ وَ الَّذِیۡنَ ظَلَمُوۡا مِنۡ ہٰۤؤُلَآءِ سَیُصِیۡبُہُمۡ سَیِّاٰتُ مَا کَسَبُوۡا ۙ وَ مَا ہُمۡ بِمُعۡجِزِیۡنَ ﴿۵۱﴾', 'آخر ان پر انکی برائیوں کا وبال پڑ گیا اور جو لوگ ان میں سے ظلم کرتے رہے ہیں ان پر بھی انکے برے اعمال کا وبال عنقریب پڑے گا۔ اور وہ اللہ کو عاجز نہیں کر سکتے۔', 'پھر پڑ گئیں ان پربرائیاں جو کمائی تھیں [۶۶] اور جو گنہگار ہیں ان میں سے ان پر بھی اب پڑتی ہیں برائیاں جو کمائی ہیں اور وہ نہیں تھکانے والے [۶۷]', 'So, the evil results of that which they earned overtook them. And those who did wrong of these (people to whom you (Muhammad SAW) have been sent), will also be overtaken by the evil results (torment) for that which they earned, and they will never be able to escape.', 'and they were overtaken by the evils of what they had earned; and the wrongdoers from these (infidels too) will be overtaken by the evils of what they have earned - and they will not be able to escape.'),
(4110, 39, 52, 5, 2, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'اَوَ لَمۡ یَعۡلَمُوۡۤا  اَنَّ اللّٰہَ یَبۡسُطُ الرِّزۡقَ لِمَنۡ یَّشَآءُ وَ یَقۡدِرُ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیٰتٍ لِّقَوۡمٍ  یُّؤۡمِنُوۡنَ ﴿٪۵۲﴾', 'کیا انکو معلوم نہیں کہ اللہ ہی جسکے لئے چاہتا ہے رزق کو فراخ کر دیتا ہے اور جسکے لئے چاہتا ہے تنگ کر دیتا ہے۔ جو لوگ ایمان لاتے ہیں انکے لئے اس میں بہت سی نشانیاں ہیں۔', 'اور کیا نہیں جان چکے کہ اللہ پھیلاتا ہے روزی جس کے واسطے چاہے اور ماپ کر دیتا ہے البتہ اس میں پتے ہیں ان لوگوں کے واسطے جو مانتے ہیں [۶۸]', 'Do they not know that Allah enlarges the provision for whom He wills, and straitens it (for whom He wills). Verily, in this are signs for the folk who believe!', 'Do they not know that it is Allah who extends provision to whomsoever He wills, and straitens (it for whomsoever He wills). Surely in that, there are signs for a people who believe.'),
(4111, 39, 53, 6, 3, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'قُلۡ یٰعِبَادِیَ  الَّذِیۡنَ  اَسۡرَفُوۡا عَلٰۤی اَنۡفُسِہِمۡ  لَا تَقۡنَطُوۡا مِنۡ رَّحۡمَۃِ اللّٰہِ ؕ اِنَّ اللّٰہَ یَغۡفِرُ الذُّنُوۡبَ جَمِیۡعًا ؕ اِنَّہٗ  ہُوَ  الۡغَفُوۡرُ  الرَّحِیۡمُ ﴿۵۳﴾', 'اے پیغمبر میری طرف سے لوگوں کو کہدو کہ اے میرے بندو! جنہوں نے اپنی جانوں پر زیادتی کی ہے اللہ کی رحمت سے ناامید نہ ہونا۔ اللہ تو سب گناہوں کو بخش دیتا ہے بیشک وہی تو ہے بڑا بخشنے والا بڑا مہربان۔', 'کہہ دے اے بندو میرے جنہوں نے کہ زیادتی کہ ہے اپنی جان پر آس مت توڑو اللہ کی مہربانی سے بیشک اللہ بخشتا ہے سب گناہ وہ جو ہے وہی ہے گناہ معاف کرنے والا مہربان [۶۹]', 'Say: \"O Ibadee (My slaves) who have transgressed against themselves (by committing evil deeds and sins)! Despair not of the Mercy of Allah, verily Allah forgives all sins. Truly, He is Oft-Forgiving, Most Merciful.', 'Say (on My behalf), “O servants of Mine who have acted recklessly against their own selves, do not despair of Allah’s mercy. Surely, Allah will forgive all sins. Surely, He is the One who is the Most-Forgiving, the Very-Merciful.'),
(4112, 39, 54, 6, 3, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ اَنِیۡبُوۡۤا اِلٰی  رَبِّکُمۡ وَ اَسۡلِمُوۡا لَہٗ مِنۡ قَبۡلِ اَنۡ یَّاۡتِیَکُمُ الۡعَذَابُ ثُمَّ لَا تُنۡصَرُوۡنَ ﴿۵۴﴾', 'اور اس سے پہلے کہ تم پر عذاب آ واقع ہو۔ اپنے پروردگار کی طرف رجوع کرو اور اسکے فرمانبردار ہو جاؤ۔ ورنہ بعد میں تمکو مدد نہیں ملے گی۔', 'اور رجوع ہو جاؤ اپنے رب کی طرف اور اسکی حکمبرداری کرو  پہلے اس سے کہ آئے تم پر عذاب پھر کوئی تمہاری مدد کو نہ آئے گا [۷۰]', '\"And turn in repentance and in obedience with true Faith (Islamic Monotheism) to your Lord and submit to Him, (in Islam), before the torment comes upon you, then you will not be helped.', 'Turn passionately towards your Lord, and submit to Him before the punishment comes to you, after which you will not be helped.'),
(4113, 39, 55, 6, 3, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ اتَّبِعُوۡۤا  اَحۡسَنَ مَاۤ   اُنۡزِلَ  اِلَیۡکُمۡ مِّنۡ رَّبِّکُمۡ مِّنۡ قَبۡلِ اَنۡ یَّاۡتِیَکُمُ الۡعَذَابُ بَغۡتَۃً  وَّ  اَنۡتُمۡ  لَا  تَشۡعُرُوۡنَ ﴿ۙ۵۵﴾', 'اور اس سے پہلے کہ تم پر ناگہاں عذاب آ جائے اور تمکو خبر بھی نہ ہو اس نہایت اچھی کتاب کی جو تمہارے پروردگار کی طرف سے تمہاری جانب نازل ہوئی ہے پیروی کرو۔', 'اور چلو بہتر بات پر جو اتری تمہاری طرف تمہارے رب سے پہلے اس سے کہ پہنچے تم پر عذاب اچانک اور تمکو خبر نہ ہو [۷۱]', '\"And follow the best of that which is sent down to you from your Lord (i.e. this Quran, do what it orders you to do and keep away from what it forbids), before the torment comes on you suddenly while you perceive not!\"', 'And follow the best of what has been sent down to you from your Lord before the punishment comes to you suddenly when you do not even expect,'),
(4114, 39, 56, 6, 3, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'اَنۡ تَقُوۡلَ نَفۡسٌ یّٰحَسۡرَتٰی عَلٰی مَا فَرَّطۡتُّ فِیۡ جَنۡۢبِ اللّٰہِ وَ اِنۡ کُنۡتُ لَمِنَ السّٰخِرِیۡنَ ﴿ۙ۵۶﴾', 'ایسا نہ ہو کہ اس وقت کوئی شخص کہنے لگے کہ ہائے اس کوتاہی پر افسوس ہے جو میں نے اللہ کا حق ماننے میں کی اور میں تو ہنسی ہی کرتا رہا۔', 'کہیں کہنے لگے کوئی جی اے افسوس اس بات پر کہ میں کوتاہی کرتا رہا اللہ کی طرف سے اور میں تو ہنستا ہی رہا [۷۲]', 'Lest a person should say: \"Alas, my grief that I was undutiful to Allah (i.e. I have not done what Allah has ordered me to do), and I was indeed among those who mocked (at the truth! i.e. La ilaha ill-Allah (none has the right to be worshipped but Allah), the Quran, and Muhammad SAW and at the faithful believers, etc.)', 'lest someone should say, “Pity on me, because I fell short in respect of (observing the rights of) Allah and in fact, I was one of those who mocked”,'),
(4115, 39, 57, 6, 3, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'اَوۡ تَقُوۡلَ لَوۡ اَنَّ اللّٰہَ ہَدٰىنِیۡ  لَکُنۡتُ مِنَ الۡمُتَّقِیۡنَ ﴿ۙ۵۷﴾', 'یا یہ کہنے لگے کہ اگر اللہ مجھ کو ہدایت دیتا تو میں بھی پرہیزگاروں میں ہوتا۔', 'یا کہنے لگے اگر اللہ مجھ کو راہ دکھاتا تو میں ہوتا ڈرنے والوں میں [۷۳]', 'Or (lest) he should say: \"If only Allah had guided me, I should indeed have been among the Muttaqoon (pious and righteous persons - see V.2:2).\"', 'or, (lest) someone should say, “If Allah were to show me the way, I would have surely been among those who fear Allah”,'),
(4116, 39, 58, 6, 3, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'اَوۡ تَقُوۡلَ حِیۡنَ تَرَی الۡعَذَابَ لَوۡ اَنَّ لِیۡ کَرَّۃً  فَاَکُوۡنَ مِنَ الۡمُحۡسِنِیۡنَ ﴿۵۸﴾', 'یا جب عذاب دیکھ لے تو کہنے لگے کہ اگر مجھے پھر ایک دفعہ دنیا میں جانا ہو تو میں نیکوکاروں میں ہو جاؤں۔', 'یا کہنے لگے جب دیکھے عذاب کو کسی طرح مجھ کو پھر جانا ملے تو میں ہو جاؤں نیکی والوں میں [۷۴]', 'Or (lest) he should say when he sees the torment: \"If only I had another chance (to return to the world) then I should indeed be among the Muhsinoon (good-doers - see V.2:112).\"', 'or, (lest) someone should say when he sees the punishment, “Would that I have a chance to return, so that I may become one of those who are good in their deeds.”'),
(4117, 39, 59, 6, 3, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'بَلٰی قَدۡ جَآءَتۡکَ اٰیٰتِیۡ فَکَذَّبۡتَ بِہَا وَ اسۡتَکۡبَرۡتَ وَ کُنۡتَ مِنَ الۡکٰفِرِیۡنَ ﴿۵۹﴾', 'ارشاد ہو گا کیوں نہیں میری آیتیں تیرے پاس پہنچ گئ تھیں۔ مگر تو نے انکو جھٹلایا اور شیخی میں آ گیا اور تو کافر بن گیا۔', 'کیوں نہیں پہنچ چکے تھے تیرے پاس میرے حکم  پھر تو نے انکو جھٹلایا اور غرور کیا اور تو تھا منکروں میں [۷۵]', 'Yes! Verily, there came to you My Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) and you denied them, and were proud and were among the disbelievers.', 'No! My verses had reached you, but you called them untrue, and waxed proud, and became of those who disbelieved.'),
(4118, 39, 60, 6, 3, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ یَوۡمَ الۡقِیٰمَۃِ  تَرَی الَّذِیۡنَ کَذَبُوۡا عَلَی اللّٰہِ  وُجُوۡہُہُمۡ  مُّسۡوَدَّۃٌ ؕ اَلَیۡسَ فِیۡ  جَہَنَّمَ مَثۡوًی  لِّلۡمُتَکَبِّرِیۡنَ ﴿۶۰﴾', 'اور اے مخاطب جن لوگوں نے اللہ پر جھوٹ بولا تم قیامت کے دن دیکھو گے کہ ان کے چہرے سیاہ ہو رہے ہوں گے۔ کیا تکبر کرنے والوں کا ٹھکانہ دوزخ میں نہیں ہے؟', 'اور قیامت کے دن تو دیکھے انکو جو جھوٹ بولتے ہیں اللہ پر کہ ان کے منہ ہوں سیاہ [۷۶] کیا نہیں دوزخ میں ٹھکانہ غرور والوں کا [۷۷]', 'And on the Day of Resurrection you will see those who lied against Allah (i.e. attributed to Him sons, partners, etc.) their faces will be black. Is there not in Hell an abode for the arrogant ones?', 'And on the Day of Judgment, you will see those who had forged lies against Allah (in a state) that their faces are turned black. Is it not that in Jahannam there is an abode for the arrogant?'),
(4119, 39, 61, 6, 3, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ یُنَجِّی اللّٰہُ  الَّذِیۡنَ اتَّقَوۡا بِمَفَازَتِہِمۡ ۫ لَا  یَمَسُّہُمُ السُّوۡٓءُ  وَ لَا  ہُمۡ  یَحۡزَنُوۡنَ ﴿۶۱﴾', 'اور جو پرہیزگار ہیں انکی کامیابی کے سبب اللہ انکو نجات دے گا نہ تو انکو کوئی تکلیف پہنچے گی اور نہ وہ غمناک ہوں گے۔', 'اور بچائے گا اللہ انکو جو ڈرتے رہے انکے بچاؤ کی جگہ نہ لگے انکو برائی اور نہ وہ غمگین ہوں [۷۸]', 'And Allah will deliver those who are the Muttaqoon (pious - see V.2:2) to their places of success (Paradise). Evil shall touch them not, nor shall they grieve.', 'And Allah will save the God-fearing (from Jahannam ), with utmost success granted to them, so as no evil will touch them, nor will they grieve.'),
(4120, 39, 62, 6, 3, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'اَللّٰہُ  خَالِقُ کُلِّ شَیۡءٍ ۫ وَّ ہُوَ عَلٰی کُلِّ شَیۡءٍ  وَّکِیۡلٌ ﴿۶۲﴾', 'اللہ ہی ہر چیز کا پیدا کرنے والا ہے اور وہی ہر چیز کا نگران ہے۔', 'اللہ بنانے والا ہے ہر چیز کا اور وہ ہرچیز کا ذمہ لیتا ہے', 'Allah is the Creator of all things, and He is the Wakeel (Trustee, Disposer of affairs, Guardian, etc.) over all things.', 'Allah is Creator of everything, and He is the Guardian over everything.'),
(4121, 39, 63, 6, 3, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'لَہٗ  مَقَالِیۡدُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ الَّذِیۡنَ کَفَرُوۡا بِاٰیٰتِ اللّٰہِ  اُولٰٓئِکَ ہُمُ الۡخٰسِرُوۡنَ ﴿٪۶۳﴾', 'اسی کے پاس آسمانوں اور زمین کی کنجیاں ہیں اور جنہوں نے اللہ کی آیتوں سے کفر کیا وہی نقصان اٹھانے والے ہیں۔', 'اسی کے پاس ہیں کنجیاں آسمانوں کی اور زمین کی اور جو منکر ہوئے ہیں اللہ کی باتوں سے وہ لوگ جو ہیں وہی ہیں ٹوٹے میں پڑے [۷۹]', 'To Him belong the keys of the heavens and the earth. And those who disbelieve in the Ayat (proofs, evidences, verses, signs, revelations, etc.) of Allah, such are they who will be the losers.', 'To Him belong the keys to the heavens and the earth. As for those who have rejected the verses of Allah, it is they who are the losers.'),
(4122, 39, 64, 7, 4, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'قُلۡ اَفَغَیۡرَ اللّٰہِ  تَاۡمُرُوۡٓنِّیۡۤ  اَعۡبُدُ  اَیُّہَا الۡجٰہِلُوۡنَ ﴿۶۴﴾', 'کہدو کہ اے نادانو! تو کیا تم مجھ سے یہ کہتے ہو کہ میں غیر اللہ کی پرستش کرنے لگوں۔', 'تو کہہ اب اللہ کے سوائے کسی کو بتلاتے ہو کہ پوجوں اے نادانو [۸۰]', 'Say (O Muhammad SAW to the polytheists, etc.): \"Do you order me to worship other than Allah O you fools ?\"', 'Say, “Is it, then, someone other than Allah that you ask me to worship, O ignorant people?”'),
(4123, 39, 65, 7, 4, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ لَقَدۡ  اُوۡحِیَ  اِلَیۡکَ وَ اِلَی الَّذِیۡنَ مِنۡ قَبۡلِکَ ۚ لَئِنۡ  اَشۡرَکۡتَ لَیَحۡبَطَنَّ عَمَلُکَ وَ  لَتَکُوۡنَنَّ  مِنَ  الۡخٰسِرِیۡنَ ﴿۶۵﴾', 'اور اے پیغمبر تمہاری طرف اور ان پیغمبروں کی طرف جو تم سے پہلے ہو چکے ہیں یہی وحی بھیجی گئ ہے۔ کہ اگر تم نے شرک کیا تو تمہارے اعمال برباد ہو جائیں گے اور تم نقصان اٹھانے والوں میں ہو جاؤ گے۔', 'اور حکم ہو چکا ہے تجھ کو اور تجھ سے اگلوں کو کہ اگر تو نے شریک مان لیا تو اکارت جائیں گے تیرے عمل اور تو ہو گا ٹوٹے میں پڑا', 'And indeed it has been revealed to you (O Muhammad SAW), as it was to those (Allahs Messengers) before you: \"If you join others in worship with Allah, (then) surely (all) your deeds will be in vain, and you will certainly be among the losers.\"', 'It has already been revealed to you and to those before you (that): If you associate (partners with Allah), your deeds shall be rendered useless, and you shall be among the losers.'),
(4124, 39, 66, 7, 4, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'بَلِ اللّٰہَ  فَاعۡبُدۡ وَ کُنۡ مِّنَ الشّٰکِرِیۡنَ ﴿۶۶﴾', 'بلکہ اللہ ہی کی عبادت کرو اور شکرگذاروں میں رہو۔', 'نہیں بلکہ اللہ ہی کو پوج اور  رہ حق ماننے والوں میں [۸۱]', 'Nay! But worship Allah (Alone and none else), and be among the grateful.', 'On the contrary, it is Allah whom you should worship; and be among the grateful.'),
(4125, 39, 67, 7, 4, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ مَا قَدَرُوا اللّٰہَ حَقَّ قَدۡرِہٖ ٭ۖ وَ الۡاَرۡضُ جَمِیۡعًا قَبۡضَتُہٗ یَوۡمَ الۡقِیٰمَۃِ وَ السَّمٰوٰتُ مَطۡوِیّٰتٌۢ بِیَمِیۡنِہٖ ؕ سُبۡحٰنَہٗ وَ تَعٰلٰی عَمَّا یُشۡرِکُوۡنَ ﴿۶۷﴾', 'اور انہوں نے اللہ کی قدرشناسی جیسی کرنی چاہیے تھی نہیں کی اور قیامت کے دن تمام زمین اسکی مٹھی میں ہوگی اور آسمان اسکے داہنے ہاتھ میں لپٹے ہوئے ہوں گے۔ اور وہ ان لوگوں کے شرک سے پاک ہے بلند و برتر ہے۔', 'اور نہیں سمجھے اللہ کو جتنا کچھ وہ ہے [۸۲] اور زمین ساری ایک مٹھی ہے اسکی دن قیامت کے اور آسمان لپٹے ہوئے ہوں اسکے داہنے ہاتھ میں وہ پاک ہے اور بہت اوپر ہے اس سے کہ شریک بتلاتے ہیں [۸۳]', 'They made not a just estimate of Allah such as is due to Him. And on the Day of Resurrection the whole of the earth will be grasped by His Hand and the heavens will be rolled up in His Right Hand. Glorified is He, and High is He above all that they associate as partners with Him!', 'They did not hold Allah in His true esteem. The whole earth will be in a single grip of His hand on the Day of Doom, and the heavens (will be) rolled up on his right hand. Pure is He, far too higher than what they associate with Him.'),
(4126, 39, 68, 7, 4, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ نُفِخَ فِی الصُّوۡرِ فَصَعِقَ مَنۡ فِی السَّمٰوٰتِ وَ مَنۡ فِی الۡاَرۡضِ اِلَّا مَنۡ شَآءَ اللّٰہُ ؕ ثُمَّ  نُفِخَ  فِیۡہِ  اُخۡرٰی فَاِذَا ہُمۡ  قِیَامٌ  یَّنۡظُرُوۡنَ ﴿۶۸﴾', 'اور جب صور پھونکا جائے گا تو جو لوگ آسمانوں میں ہیں اور جو زمین میں ہیں سب بیہوش ہو کر گر پڑیں گے مگر وہ جسکو اللہ چاہے پھر دوسری دفعہ صور پھونکا جائے گا تو فوراً سب کھڑے ہو کر دیکھنے لگیں گے۔', 'اور پھونکا جائے صور میں پھر بیہوش ہو جائے جو کوئی ہے آسمانوں میں اور زمین میں مگر جس کو اللہ چاہے پھر پھونکی جائے دوسری بار تو فورًا وہ کھڑے ہو جائیں ہر طرف دیکھتے [۸۴]', 'And the Trumpet will be blown, and all who are in the heavens and all who are on the earth will swoon away, except him whom Allah will. Then it will blown a second time and behold, they will be standing, looking on (waiting).', 'And Horn (Sūr ) will be blown, and all those in the heavens and all those in the earth will faint, except the one whom Allah wills (otherwise). Thereafter, it will be blown once again, and suddenly they will stand up, looking around.'),
(4127, 39, 69, 7, 4, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ اَشۡرَقَتِ  الۡاَرۡضُ بِنُوۡرِ رَبِّہَا وَ وُضِعَ الۡکِتٰبُ وَ جِایۡٓءَ بِالنَّبِیّٖنَ وَ الشُّہَدَآءِ  وَ قُضِیَ بَیۡنَہُمۡ بِالۡحَقِّ وَ ہُمۡ  لَا یُظۡلَمُوۡنَ ﴿۶۹﴾', 'اور زمین اپنے پروردگار کے نور سے چمک اٹھے گی اور اعمال کی کتاب کھول کر رکھ دی جائے گی اور پیغمبر اور دوسرے گواہ حاضر کئے جائیں گے اور ان میں انصاف سے فیصلہ کیا جائے گا اور انکے ساتھ بے انصافی نہیں کی جائے گی۔', 'اور چمکے زمین اپنے رب کے نور سے اور لا دھریں دفتر اور حاضر آئیں پیغمبر اور گواہ اور فیصلہ ہو ان میں انصاف سے اور ان پر ظلم نہ ہو گا [۸۵]', 'And the earth will shine with the light of its Lord (Allah, when He will come to judge among men) and the Book will be placed (open) and the Prophets and the witnesses will be brought forward, and it will be judged between them with truth, and they will not be wronged.', 'And the earth will shine with the light of its Lord, and the book (of everyone’s deeds) will be placed, and the prophets and the witnesses will be brought, and matters will be decided between them with justice, and they will not be wronged.'),
(4128, 39, 70, 7, 4, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ وُفِّیَتۡ کُلُّ  نَفۡسٍ مَّا عَمِلَتۡ وَ ہُوَ اَعۡلَمُ  بِمَا یَفۡعَلُوۡنَ ﴿٪۷۰﴾', 'اور جس شخص نے جو عمل کیا ہو گا اسکو اس کا پورا پورا بدلہ مل جائے گا اور جو کچھ یہ کرتے ہیں اسکو سب کی خبر ہے۔', 'اور پورا ملے ہر جی کو جو اس نے کیا [۸۶] اور اسکو خوب خبر ہے جو کچھ کرتے ہیں [۸۷]', 'And each person will be paid in full of what he did; and He is Best Aware of what they do.', 'And everyone will be paid in full for what he did - and He knows best what they do.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(4129, 39, 71, 8, 5, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ سِیۡقَ الَّذِیۡنَ  کَفَرُوۡۤا اِلٰی جَہَنَّمَ  زُمَرًا ؕ حَتّٰۤی  اِذَا جَآءُوۡہَا فُتِحَتۡ  اَبۡوَابُہَا وَ قَالَ لَہُمۡ خَزَنَتُہَاۤ  اَلَمۡ یَاۡتِکُمۡ رُسُلٌ مِّنۡکُمۡ یَتۡلُوۡنَ عَلَیۡکُمۡ اٰیٰتِ رَبِّکُمۡ وَ یُنۡذِرُوۡنَکُمۡ لِقَآءَ یَوۡمِکُمۡ ہٰذَا ؕ قَالُوۡا بَلٰی وَ لٰکِنۡ حَقَّتۡ کَلِمَۃُ الۡعَذَابِ عَلَی الۡکٰفِرِیۡنَ ﴿۷۱﴾', 'اور کافر گروہ گروہ کر کے جہنم کی طرف ہانکے جائیں گے یہاں تک کہ جب وہ اسکے پاس پہنچ جائیں گے تو اسکے دروازے کھول دیئے جائیں گے اور اسکے داروغہ ان سے کہیں گے کہ کیا تمہارے پاس تم ہی میں سے پیغمبر نہیں آئے تھے جو تمکو تمہارے پروردگار کی آیتیں پڑھ پڑھ کر سناتے اور تمہارے اس دن کے پیش آنے سے تمہیں ڈراتے تھے وہ کہیں گے کیوں نہیں لیکن کافروں کے حق میں عذاب کا حکم ثابت ہو چکا تھا۔', 'اور ہانکے جائیں جو منکر تھے دوزخ کی طرف گروہ گروہ [۸۸] یہاں تک کہ جب پہنچ جائیں اس پر کھولے جائیں اسکے دروازے [۸۹] اور کہنے لگیں انکو اسکے داروغہ [۹۰] کیا نہ پہنچے تھے تمہارے پاس رسول تم میں کے [۹۱] پڑھتے تھے تم پرباتیں تمہارے رب کی اور ڈراتے تھے تم کو اس تمہارے دن کی ملاقات سے بولیں کیوں نہیں پر ثابت ہوا حکم عذاب کا منکروں پر [۹۲]', 'And those who disbelieved will be driven to Hell in groups, till, when they reach it, the gates thereof will be opened (suddenly like a prison at the arrival of the prisoners). And its keepers will say, \"Did not the Messengers come to you from yourselves, reciting to you the Verses of your Lord, and warning you of the Meeting of this Day of yours?\" They will say: \"Yes, but the Word of torment has been justified against the disbelievers!\"', 'Those who disbelieved will be driven towards Jahannam in groups, until when they reach it, its gates will be opened, and its keepers will say to them, “Did messengers from among you not come to you reciting to you the verses of your Lord, and warning you about the meeting of this day of yours?” They will say, “Yes (they did),but the word of punishment had become certain against those who disbelieved.”'),
(4130, 39, 72, 8, 5, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'قِیۡلَ  ادۡخُلُوۡۤا اَبۡوَابَ جَہَنَّمَ خٰلِدِیۡنَ فِیۡہَا ۚ فَبِئۡسَ مَثۡوَی الۡمُتَکَبِّرِیۡنَ ﴿۷۲﴾', 'کہا جائے گا کہ دوزخ کے دروازوں میں داخل ہو جاؤ ہمیشہ اس میں رہو گے سو تکبر کرنے والوں کا برا ٹھکانہ ہے۔', 'حکم ہووے گا کہ داخل ہو جاؤ دروازوں میں دوزخ کے سدا رہنے کو اس میں سو کیا بری جگہ ہے رہنے کی غرور والوں کو [۹۳]', 'It will be said (to them): \"Enter you the gates of Hell, to abide therein. And (indeed) what an evil abode of the arrogant!\"', 'It will be said, “Enter the gates of Jahannam to live in it forever.” So, how evil is the dwelling-place of the arrogant!'),
(4131, 39, 73, 8, 5, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ سِیۡقَ الَّذِیۡنَ اتَّقَوۡا رَبَّہُمۡ  اِلَی الۡجَنَّۃِ زُمَرًا ؕ حَتّٰۤی  اِذَا جَآءُوۡہَا وَ فُتِحَتۡ اَبۡوَابُہَا وَ قَالَ لَہُمۡ خَزَنَتُہَا سَلٰمٌ عَلَیۡکُمۡ طِبۡتُمۡ فَادۡخُلُوۡہَا خٰلِدِیۡنَ ﴿۷۳﴾', 'اور جو لوگ اپنے پروردگار سے ڈرتے ہیں انکو گروہ گروہ کر کے بہشت کی طرف لیجایا جائے گا یہاں تک کہ جب وہ اسکے پاس پہنچ جائیں گے اس حال میں کہ اسکے دروازے کھولے جا چکے ہونگے تو اسکے داروغہ ان سے کہیں گے کہ تم پر سلام ہو تم بہت اچھے رہے۔ اب اس میں ہمیشہ کے لئے داخل ہو جاؤ۔', 'اور ہانکے جائیں وہ لوگ جو ڈرتے رہے تھے اپنے رب سے جنت کو گروہ گروہ [۹۴] یہاں تک کہ جب پہنچ جائیں اس پر اور کھولے جائیں اس کے دروازے اور کہنے لگیں ان کو داروغہ اس کے سلام پہنچے تم پر تم لوگ پاکیزہ ہو سو داخل ہو جاؤ اس میں سدا  رہنے کو [۹۵]', 'And those who kept their duty to their Lord will be led to Paradise in groups, till, when they reach it, and its gates will be opened (before their arrival for their reception) and its keepers will say: Salamun Alaikum (peace be upon you)! You have done well, so enter here to abide therein.\"', 'And those who used to fear their Lord will be led towards Jannah (Paradise) in groups, until when they reach it, while its gates will be (already) opened (for them), and its keepers will say to them, “Salāmun-’alaikum (peace be on you). How good are you! So, enter it to live here forever.”'),
(4132, 39, 74, 8, 5, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ قَالُوا الۡحَمۡدُ لِلّٰہِ الَّذِیۡ صَدَقَنَا وَعۡدَہٗ وَ اَوۡرَثَنَا الۡاَرۡضَ نَتَبَوَّاُ مِنَ الۡجَنَّۃِ حَیۡثُ نَشَآءُ ۚ فَنِعۡمَ  اَجۡرُ الۡعٰمِلِیۡنَ ﴿۷۴﴾', 'اور وہ کہیں گے کہ اللہ کا شکر ہے جس نے اپنے وعدے کو ہم سے سچا کر دیا اور ہمکو اس زمین کا وارث بنا دیا ہم بہشت میں جہاں چاہیں رہیں تو اچھے عمل کرنے والوں کا بدلہ بھی کیسا خوب ہے۔', 'اور وہ بولیں شکر اللہ کا جس نے سچ کیا ہم سے اپنا وعدہ [۹۶] اور وارث کیا ہمکو اس زمین کا [۹۷] گھر لے لیویں بہشت میں سے جہاں چاہیں [۹۸] سو کیا خوب بدلا ہے محنت کرنے والوں کا', 'And they will say: \"All the praises and thanks be to Allah Who has fulfilled His Promise to us and has made us inherit (this) land. We can dwell in Paradise where we will; how excellent a reward for the (pious good) workers!\"', 'And they will say, “AlHamdulillāh : Praise belongs to Allah who made His promise come true for us, and made us inherit the territory, so as we can dwell anywhere we wish in Jannah (Paradise) . So, excellent is the reward of those who did (good) deeds.'),
(4133, 39, 75, 8, 5, 24, 'فَمَنۡ اَظۡلَمُ', 'الزمر', 'وَ تَرَی الۡمَلٰٓئِکَۃَ  حَآفِّیۡنَ مِنۡ حَوۡلِ الۡعَرۡشِ یُسَبِّحُوۡنَ بِحَمۡدِ رَبِّہِمۡ ۚ وَ قُضِیَ بَیۡنَہُمۡ  بِالۡحَقِّ وَ قِیۡلَ الۡحَمۡدُ لِلّٰہِ رَبِّ الۡعٰلَمِیۡنَ ﴿٪۷۵﴾', 'اور تم فرشتوں کو دیکھو گے کہ عرش کے گرد گھیرا باندھے ہوئے ہیں اور اپنے پروردگار کی تعریف و تسبیح کر رہے ہیں اور ان میں انصاف کے ساتھ فیصلہ کر دیا جائے گا اور کہا جائے گا کہ ہر طرح کی تعریف اللہ ہی کیلئے ہے جو تمام جہانوں کا مالک ہے۔', 'اور تو دیکھے فرشتوں کو گھر رہے ہیں عرش کے گرد پاکی بولتے ہیں اپنے رب کی خوبیاں اور فیصلہ ہوتا ہے ان میں انصاف کا اور یہی بات کہتے ہیں کہ سب خوبی ہے اللہ کو جو رب ہے سارے جہان کا [۹۹]', 'And you will see the angels surrounding the Throne (of Allah) from all round, glorifying the praises of their Lord (Allah). And they (all the creatures) will be judged with truth, and it will be said. All the praises and thanks be to Allah, the Lord of the Alameen (mankind, jinns and all that exists).\"', 'And you will see the angels ringed around the Throne proclaiming the purity of their Lord, along with His praise, and matters will stand settled between them rightfully, and it will be said: “AlHamdulillāhi-rabbil‘ālamīn : Praise belongs to Allah, the Lord of the worlds.”'),
(4134, 40, 1, 1, 6, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'حٰمٓ ۚ﴿۱﴾', 'حٰم۔', 'حٰم۔', 'Ha-Meem. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings).', 'Hā Mīm .'),
(4135, 40, 2, 1, 6, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'تَنۡزِیۡلُ  الۡکِتٰبِ مِنَ اللّٰہِ الۡعَزِیۡزِ الۡعَلِیۡمِ ۙ﴿۲﴾', 'اس کتاب کا اتارا جانا اللہ کی طرف سے ہے جو زبردست ہے دانا ہے۔', 'اتارنا کتاب کا اللہ سے ہے جو زبردست ہے خبردار', 'The revelation of the Book (this Quran) is from Allah the All-Mighty, the All-Knower.', 'This is revelation of the Book from Allah, the Mighty, the All-Knowing,'),
(4136, 40, 3, 1, 6, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'غَافِرِ الذَّنۡۢبِ وَ قَابِلِ التَّوۡبِ شَدِیۡدِ الۡعِقَابِ ۙ ذِی الطَّوۡلِ ؕ لَاۤ  اِلٰہَ  اِلَّا ہُوَ ؕ اِلَیۡہِ  الۡمَصِیۡرُ ﴿۳﴾', 'جو گناہ بخشنے والا اور توبہ قبول کرنے والا سخت عذاب دینے والا ہے صاحب کرم ہے۔ اسکے سوا کوئی معبود نہیں۔ اسی کی طرف لوٹ کر جانا ہے۔', 'گناہ بخشنے والا اور توبہ قبول کرنے والا [۱] سخت عذاب دینے والا مقدور  والا [۲] کسی کی بندگی نہیں سوائے اسکے اسی کی طرف پھر جانا ہے [۳]', 'The Forgiver of sin, the Acceptor of repentance, the Severe in punishment, the Bestower (of favours), La ilaha illa Huwa (none has the right to be worshipped but He), to Him is the final return.', 'the One who forgives sins and accepts repentance, the One who is severe in punishment, the One who is the source of all power. There is no god but He. To Him is the ultimate return (of all).'),
(4137, 40, 4, 1, 6, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'مَا یُجَادِلُ  فِیۡۤ  اٰیٰتِ اللّٰہِ  اِلَّا الَّذِیۡنَ کَفَرُوۡا فَلَا یَغۡرُرۡکَ تَقَلُّبُہُمۡ فِی الۡبِلَادِ ﴿۴﴾', 'اللہ کی آیتوں میں وہی لوگ جھگڑتے ہیں جو کافر ہیں۔ تو ان لوگوں کا شہروں میں چلنا پھرنا تمہیں دھوکے میں نہ ڈال دے۔', 'وہی جھگڑتے ہیں اللہ کی باتوں میں جو منکر ہیں [۴] سو تجھ کو دھوکا نہ دے یہ بات کہ وہ چلتے  پھرتے ہیں شہروں میں [۵]', 'None disputes in the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah but those who disbelieve. So let not their ability of going about here and there through the land (for their purposes) deceive you (O Muhammad SAW, their ultimate end will be the Fire of Hell)!', 'No one quarrels about the verses of Allah, except those who disbelieve. So, their (prosperous) movements in the cities should not deceive you.'),
(4138, 40, 5, 1, 6, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'کَذَّبَتۡ قَبۡلَہُمۡ  قَوۡمُ نُوۡحٍ وَّ الۡاَحۡزَابُ مِنۡۢ بَعۡدِہِمۡ ۪ وَ ہَمَّتۡ کُلُّ  اُمَّۃٍۭ بِرَسُوۡلِہِمۡ  لِیَاۡخُذُوۡہُ وَ جٰدَلُوۡا بِالۡبَاطِلِ لِیُدۡحِضُوۡا بِہِ الۡحَقَّ فَاَخَذۡتُہُمۡ ۟ فَکَیۡفَ کَانَ عِقَابِ ﴿۵﴾', 'ان سے پہلے نوح  کی قوم اور انکے بعد اور امتوں نے بھی پیغمبروں کی تکذیب کی اور ہر امت نے اپنے پیغمبر کے بارے میں یہی قصد کیا کہ اسکو پکڑ لیں اور بیہودہ شبہات سے جھگڑتے رہے کہ اس سے حق کو زائل کر دیں تو میں نے انکو پکڑ لیا سو دیکھ لو میرا عذاب کیسا ہوا۔', 'جھٹلا چکے ہیں ان سے پہلے قوم نوح کی اور کتنے فرقے ان سے پیچھے اور ارادہ کیا ہر امت نے اپنے رسول پر کہ اس کو پکڑ لیں اور لانے لگے جھوٹے جھگڑے کہ اس سے ڈگا دیں سچے دین کو پھر میں نے انکو پکڑ لیا کہو  پھر کیسا ہوا میرا سزا دینا [۶]', 'The people of Nooh (Noah) and the confederates after them denied (their Messengers) before these, and every (disbelieving) nation plotted against their Messenger to seize him, and disputed by means of falsehood to refute therewith the truth. So I seized them (with punishment), and how (terrible) was My punishment!', 'Before these, the people of NūH and the groups after them had rejected (the messengers). Every group intended to seize their messenger, and raised disputes on the basis of falsehood, so that they might refute the truth with it, hence I seized them. So, how was My punishment?'),
(4139, 40, 6, 1, 6, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ کَذٰلِکَ حَقَّتۡ کَلِمَتُ رَبِّکَ عَلَی الَّذِیۡنَ  کَفَرُوۡۤا  اَنَّہُمۡ  اَصۡحٰبُ  النَّارِ ۘ﴿ؔ۶﴾', 'اور اسی طرح کافروں کے بارے میں بھی تمہارے پروردگار کی بات پوری ہو چکی ہے کہ وہ اہل دوزخ ہیں۔', 'اور اسی طرح ٹھیک ہو چکی بات تیرے رب کی منکروں پر کہ یہ ہیں دوزخ والے [۷]', 'Thus has the Word of your Lord been justified against those who disbelieved, that they will be the dwellers of the Fire.', 'And similarly, the word of your Lord has become due against those who disbelieve-that they are the people of the Fire.'),
(4140, 40, 7, 1, 6, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اَلَّذِیۡنَ یَحۡمِلُوۡنَ الۡعَرۡشَ وَ مَنۡ حَوۡلَہٗ یُسَبِّحُوۡنَ بِحَمۡدِ  رَبِّہِمۡ وَ یُؤۡمِنُوۡنَ بِہٖ وَ یَسۡتَغۡفِرُوۡنَ  لِلَّذِیۡنَ اٰمَنُوۡا ۚ رَبَّنَا وَسِعۡتَ کُلَّ  شَیۡءٍ رَّحۡمَۃً  وَّ عِلۡمًا فَاغۡفِرۡ  لِلَّذِیۡنَ تَابُوۡا وَ اتَّبَعُوۡا سَبِیۡلَکَ وَ قِہِمۡ  عَذَابَ  الۡجَحِیۡمِ ﴿۷﴾', 'جو لوگ عرش کو اٹھائے ہوئے اور جو اسکے گردا گرد حلقہ باندھے ہوئے ہیں یعنی فرشتے وہ اپنے پروردگار کی تعریف کے ساتھ تسبیح کرتے رہتے ہیں اور اس پر ایمان رکھتے ہیں اور مومنوں کے لئے بخشش مانگتے رہتے ہیں کہ اے ہمارے پروردگار تیری رحمت اور تیرا علم ہر چیز کو سموئے ہوئے ہے تو جن لوگوں نے توبہ کی اور تیرے رستے پر چلے انکو بخش دے اور دوزخ کے عذاب سے بچا لے۔', 'جو لوگ اٹھا رہے ہیں عرش کو اور جو اس کے گرد ہیں پاکی بولتے ہیں اپنے رب کی خوبیاں اور اس پر یقین رکھتے ہیں اور گناہ بخشواتے ہیں ایمان والوں کے [۸] اے پروردگار ہمارے ہر چیز سمائی ہوئی ہے تیری بخشش اور خبر میں سو معاف کر انکو جو توبہ کریں اور چلیں تیری راہ پر اور بچا اُنکو آگ کے عذاب سے [۹]', 'Those (angels) who bear the Throne (of Allah) and those around it glorify the praises of their Lord, and believe in Him, and ask forgiveness for those who believe (in the Oneness of Allah) (saying): \"Our Lord! You comprehend all things in mercy and knowledge, so forgive those who repent and follow Your Way, and save them from the torment of the blazing Fire!', 'Those who are bearing the Throne and those who are around it pronounce the purity of your Lord along with His praise, and believe in Him, and pray for the forgiveness of those who believe, (saying): “Our Lord, Your mercy and knowledge comprehends everything; so forgive those who repent and follow Your way, and save them from the punishment of the Fire.'),
(4141, 40, 8, 1, 6, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'رَبَّنَا وَ اَدۡخِلۡہُمۡ جَنّٰتِ عَدۡنِۣ الَّتِیۡ وَعَدۡتَّہُمۡ وَ مَنۡ صَلَحَ مِنۡ اٰبَآئِہِمۡ وَ اَزۡوَاجِہِمۡ وَ  ذُرِّیّٰتِہِمۡ ؕ اِنَّکَ اَنۡتَ الۡعَزِیۡزُ  الۡحَکِیۡمُ ۙ﴿۸﴾', 'اے ہمارے پروردگار انکو ہمیشہ رہنے کی بہشتوں میں داخل کر جن کا تو نے ان سے وعدہ کیا ہے اور جو جو ان کے باپ دادوں اور انکی بیویوں اور انکی اولاد میں سے نیک ہوں انکو بھی۔ بیشک تو غالب ہے حکمت والا ہے۔', 'اے رب ہمارے اور داخل کر انکو سدا بسنے کے باغوں میں جنکا وعدہ کیا تو نے ان سے اور جو کوئی نیک ہو انکے باپوں میں اور عورتوں میں اور اولاد میں بیشک تو ہی ہے زبردست حکمت والا [۱۰]', '\"Our Lord! And make them enter the Adn (Eden) Paradise (everlasting Gardens) which you have promised them, and to the righteous among their fathers, their wives, and their offspring! Verily, You are the All-Mighty, the All-Wise.', 'And, our Lord, admit them to the eternal gardens of Jannah (Paradise) that You have promised for them, and (admit) those as well who did good from among their fathers and wives and children. You, only You, are the Mighty, the Wise,'),
(4142, 40, 9, 1, 6, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ قِہِمُ السَّیِّاٰتِ ؕ وَ مَنۡ تَقِ السَّیِّاٰتِ یَوۡمَئِذٍ  فَقَدۡ رَحِمۡتَہٗ ؕ وَ ذٰلِکَ ہُوَ الۡفَوۡزُ الۡعَظِیۡمُ ٪﴿۹﴾', 'اور انکو بری حالتوں سے بچائے رکھیو۔ اور جسکو تو اس روز بری حالتوں سے بچا لے گا تو تو نے بیشک اس پر مہربانی فرمائی۔ اور یہی بڑی کامیابی ہے۔', 'اور بچا انکو برائیوں سے اور جس کو تو بچائے برائیوں سے اس دن اس پر مہربانی کی تو نے اور یہ جو ہے یہی ہے بڑی مراد پانی [۱۱]', '\"And save them from (the punishment, because of what they did of) the sins, and whomsoever You save from (the punishment, because of what they did of) the sins (i.e. excuse them) that Day, him verily, You have taken into mercy.\" And that is the supreme success.', 'and save them from evils (of punishment). And whomsoever you save from evils that day, it is surely because you bless him with mercy. And that is the great achievement indeed.”'),
(4143, 40, 10, 2, 7, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اِنَّ الَّذِیۡنَ کَفَرُوۡا یُنَادَوۡنَ  لَمَقۡتُ اللّٰہِ اَکۡبَرُ مِنۡ مَّقۡتِکُمۡ اَنۡفُسَکُمۡ اِذۡ تُدۡعَوۡنَ  اِلَی الۡاِیۡمَانِ فَتَکۡفُرُوۡنَ ﴿۱۰﴾', 'جن لوگوں نے کفر کیا ان سے پکار کر کہدیا جائے گا کہ جب تم دنیا میں ایمان کی طرف بلائے جاتے تھے اور مانتے نہیں تھے تو اللہ اس سے کہیں زیادہ بیزار ہوتا تھا جس قدر تم اپنے آپ سے بیزار ہو رہے ہو۔', 'جو لوگ منکر ہیں انکو پکار کر کہیں گے اللہ بیزار ہوتا تھا زیادہ اس سے جو تم بیزار ہوئے ہو اپنے جی سے جس وقت تمکو بلاتے تھے یقین لانے کو پھر تم منکر ہوتے تھے [۱۲]', 'Those who disbelieve will be addressed (at the time of entering into the Fire): \"Allahs aversion was greater towards you (in the worldly life when you used to reject the Faith) than your aversion towards one another (now in the Fire of Hell, as you are now enemies to one another), when you were called to the Faith but you used to refuse.\"', 'Those who disbelieve will be addressed (by a voice saying): “Allah’s hatred (for you), when you were invited to the true faith and you refused, was greater than your hatred for yourselves (today when you are hating your own selves out of remorse).'),
(4144, 40, 11, 2, 7, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'قَالُوۡا رَبَّنَاۤ  اَمَتَّنَا اثۡنَتَیۡنِ وَ اَحۡیَیۡتَنَا اثۡنَتَیۡنِ فَاعۡتَرَفۡنَا بِذُنُوۡبِنَا فَہَلۡ  اِلٰی خُرُوۡجٍ مِّنۡ سَبِیۡلٍ ﴿۱۱﴾', 'وہ کہیں گے کہ اے ہمارے پروردگار تو نے ہمکو دو دفعہ بے جان کیا اور دو دفعہ جان بخشی۔ ہمکو اپنے گناہوں کا اقرار ہے تو کیا نکلنے کی کوئی سبیل ہے؟', 'بولیں گے اے رب ہمارے تو موت دے چکا ہم کو دوبار اور زندگی دے چکا دو بار [۱۳] اب ہم قائل ہوئے اپنے گناہوں کے [۱۴] پھر اب بھی ہے نکلنے کی کوئی راہ [۱۵]', 'They will say: \"Our Lord! You have made us to die twice (i.e. we were dead in the loins of our fathers and dead after our deaths in this world), and You have given us life twice (i.e. life when we were born and life when we are Resurrected)! Now we confess our sins, then is there any way to get out (of the Fire)?\"', 'They will say, “Our Lord, You gave us death twice and You gave us life twice. Now we confess our sins. So, is there any way to come out of here?”'),
(4145, 40, 12, 2, 7, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'ذٰلِکُمۡ  بِاَنَّہٗۤ  اِذَا  دُعِیَ اللّٰہُ  وَحۡدَہٗ کَفَرۡتُمۡ ۚ وَ اِنۡ یُّشۡرَکۡ بِہٖ تُؤۡمِنُوۡا ؕ فَالۡحُکۡمُ  لِلّٰہِ الۡعَلِیِّ الۡکَبِیۡرِ ﴿۱۲﴾', 'یہ اس لئے کہ جب تنہا اللہ کو پکارا جاتا تھا تو تم انکار کر دیتے تھے۔ اور اگر اسکے ساتھ شریک مقرر کیا جاتا تھا تو مان لیتے لیتے تھے سو حکم تو اللہ ہی کا ہے جو بلند و بالا ہے بڑا ہے۔', 'یہ تم پر اس واسطے ہے کہ جب کسی نے پکارا اللہ کو اکیلا تو تم منکر ہوتے اور جب اسکے ساتھ پکارتے شریک کو تو تم یقین لانے لگتے اب حکم وہی ہے جو کرے اللہ سب سے اوپر بڑا [۱۶]', '(It will be said): \"This is because, when Allah Alone was invoked (in worship, etc.) you disbelieved, but when partners were joined to Him, you believed! So the judgement is only with Allah, the Most High, the Most Great!\"', '(The reply will be, “No.) This is because whenever Allah alone was invoked, you used to disbelieve, and if partners were associated with Him, you used to believe. Now the decision lies with Allah, the High, the Great.”'),
(4146, 40, 13, 2, 7, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'ہُوَ الَّذِیۡ یُرِیۡکُمۡ  اٰیٰتِہٖ وَ  یُنَزِّلُ  لَکُمۡ مِّنَ السَّمَآءِ رِزۡقًا ؕ وَ مَا یَتَذَکَّرُ   اِلَّا مَنۡ یُّنِیۡبُ ﴿۱۳﴾', 'وہی تو ہے جو تمکو اپنی نشانیاں دکھاتا ہے اور تم پر آسمان سے رزق اتارتا ہے۔ اور نصیحت تو وہی حاصل کرتا ہے جو اسکی طرف رجوع کرتا ہے۔', 'وہی ہے تم کو دکھلاتا اپنی نشانیاں اور اتارتا ہے تمہارے واسطے آسمان سے روزی اور سوچ وہی کرے جو رجوع رہتا ہو [۱۷]', 'It is He, Who shows you His Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) and sends down (rain with which grows) provision for you from the sky. And none remembers but those who turn (to Allah) in obedience and in repentance (by begging His Pardon and by worshipping and obeying Him Alone and none else).', 'It is He who shows you His signs and sends down provision for you from the sky; and no one takes lesson but the one who turns to Him.'),
(4147, 40, 14, 2, 7, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'فَادۡعُوا اللّٰہَ  مُخۡلِصِیۡنَ لَہُ  الدِّیۡنَ وَ لَوۡ کَرِہَ  الۡکٰفِرُوۡنَ ﴿۱۴﴾', 'تو اللہ کی عبادت کو خالص کر کے اسی کو پکارو اگرچہ کافر برا ہی مانیں۔', 'سو پکارو اللہ کو خالص کر کر اسکے واسطے بندگی اور پڑے برا مانیں منکر [۱۸]', 'So, call you (O Muhammad SAW and the believers) upon (or invoke) Allah making (your) worship pure for Him (Alone) (by worshipping none but Him and by doing religious deeds sincerely for Allahs sake only and not to show-off and not to set up rivals with Him in worship). However much the disbelievers (in the Oneness of Allah) may hate (it).', 'So, worship Allah, making your submission exclusive for Him, even though the disbelievers dislike (it).'),
(4148, 40, 15, 2, 7, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'رَفِیۡعُ  الدَّرَجٰتِ ذُو الۡعَرۡشِ ۚ یُلۡقِی الرُّوۡحَ مِنۡ  اَمۡرِہٖ عَلٰی مَنۡ یَّشَآءُ مِنۡ عِبَادِہٖ  لِیُنۡذِرَ  یَوۡمَ  التَّلَاقِ ﴿ۙ۱۵﴾', 'وہ مالک درجات عالی اور صاحب عرش ہے۔ اپنے بندوں میں سے جس کو چاہتا ہے اپنے حکم سے وحی بھیجتا ہے تاکہ ملاقات کے دن سے ڈرائے۔', 'وہی ہے اونچے درجوں والا مالک عرش کا اتارتا ہے بھید کی بات اپنے حکم سے جس پر چاہے اپنے بندوں میں [۱۹] تاکہ وہ ڈرائے ملاقات کے دن سے [۲۰]', '(He is Allah) Owner of High Ranks and Degrees, the Owner of the Throne. He sends the Inspiration by His Command to any of His slaves He wills, that he (the person who receives inspiration) may warn (men) of the Day of Mutual Meeting (i.e. The Day of Resurrection).', 'He is High in stations, the Lord of the Throne. He sends the spirit down, under His command, on whomever He wills from among His servants, so that he warns of the Day of Encounter -'),
(4149, 40, 16, 2, 7, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'یَوۡمَ ہُمۡ بٰرِزُوۡنَ ۬ۚ لَا یَخۡفٰی عَلَی اللّٰہِ مِنۡہُمۡ  شَیۡءٌ ؕ لِمَنِ  الۡمُلۡکُ الۡیَوۡمَ ؕ لِلّٰہِ  الۡوَاحِدِ الۡقَہَّارِ ﴿۱۶﴾', 'جس روز وہ نکل پڑیں گے انکی کوئی چیز اللہ سے مخفی نہ رہے گی سوال ہو گا آج کس کی حکومت ہے؟ جواب ملے گا اللہ کی جو اکیلا ہے بڑا زبردست ہے۔', 'جس دن وہ لوگ نکل کھڑے ہوں گے [۲۱] چھپی نہ رہے گی اللہ پر اُنکی کوئی چیز [۲۲] کس کا راج ہے اُس دن اللہ کا ہے جو اکیلا ہے دباؤ  والا [۲۳]', 'The Day when they will (all) come out, nothing of them will be hidden from Allah. Whose is the kingdom this Day? (Allah Himself will reply to His Question): It is Allahs the One, the Irresistible!', 'the day they will come in open view. Nothing about them will remain hidden from Allah. To whom belongs the kingdom today? To Allah alone, the One, the All-Dominant.'),
(4150, 40, 17, 2, 7, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اَلۡیَوۡمَ تُجۡزٰی کُلُّ  نَفۡسٍۭ بِمَا کَسَبَتۡ ؕ  لَا ظُلۡمَ الۡیَوۡمَ ؕ اِنَّ اللّٰہَ سَرِیۡعُ  الۡحِسَابِ ﴿۱۷﴾', 'آج کے دن ہر شخص کو اسکے اعمال کا بدلہ دیا جائے گا۔ آج کسی کے حق میں بے انصافی نہیں ہو گی۔ بیشک اللہ جلد حساب لینے والا ہے۔', 'آج بدلا ملے گا ہر جی کو جیسا اس نے کمایا بالکل ظلم نہیں آج بیشک اللہ جلد لینے والا ہے حساب', 'This Day shall every person be recompensed for what he earned. No injustice (shall be done to anybody). Truly, Allah is Swift in reckoning.', 'Today, everyone will be recompensed for what one earned. There is no injustice today. Surely, Allah is swift in reckoning.'),
(4151, 40, 18, 2, 7, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ اَنۡذِرۡہُمۡ یَوۡمَ الۡاٰزِفَۃِ  اِذِ الۡقُلُوۡبُ لَدَی الۡحَنَاجِرِ کٰظِمِیۡنَ ۬ؕ مَا لِلظّٰلِمِیۡنَ مِنۡ  حَمِیۡمٍ  وَّ لَا  شَفِیۡعٍ  یُّطَاعُ ﴿ؕ۱۸﴾', 'اور انکو قریب آنے والے دن سے ڈراؤ جب کہ دل غم سے بھر کر گلوں تک آ رہے ہوں گے ظالموں کا کوئی دوست نہیں ہوگا اور نہ کوئی سفارشی جسکی بات قبول کی جائے۔', 'اور خبر سنا دے اُنکو اس نزدیک آنے والے دِن کی جس وقت دل  پہنچیں گے گلوں کو تو  وہ دبا رہے ہوں گے [۲۴] کوئی نہیں گنہگاروں کا دوست اور نہ سفارشی کہ جسکی بات مانی جائے [۲۵]', 'And warn them (O Muhammad SAW) of the Day that is drawing near (i.e. the Day of Resurrection), when the hearts will be choking the throats, and they can neither return them (hearts) to their chests nor can they throw them out. There will be no friend, nor an intercessor for the Zalimoon (polytheists and wrong-doers, etc.), who could be given heed to.', 'And warn them of the Day of approaching horror, when hearts will jump up into the throats, (and they will be) choked. There will be neither a friend for the unjust, nor an intercessor to be listened to.'),
(4152, 40, 19, 2, 7, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'یَعۡلَمُ خَآئِنَۃَ  الۡاَعۡیُنِ وَ مَا تُخۡفِی الصُّدُوۡرُ ﴿۱۹﴾', 'وہ آنکھوں کی خیانت کو جانتا ہے اور جو باتیں سینوں میں پوشیدہ ہیں انکو بھی۔', 'وہ جانتا ہے چوری کی نگاہ اور جو کچھ چھپا ہوا ہے سینوں میں', 'Allah knows the fraud of the eyes, and all that the breasts conceal.', 'He knows the treachery of the eyes and whatever is concealed by hearts.'),
(4153, 40, 20, 2, 7, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ اللّٰہُ یَقۡضِیۡ بِالۡحَقِّ ؕ وَ الَّذِیۡنَ یَدۡعُوۡنَ مِنۡ دُوۡنِہٖ لَا یَقۡضُوۡنَ بِشَیۡءٍ ؕ اِنَّ  اللّٰہَ  ہُوَ  السَّمِیۡعُ  الۡبَصِیۡرُ ﴿٪۲۰﴾', 'اور اللہ سچائی کے ساتھ فیصلہ فرماتا ہے۔ اور جنکو یہ لوگ پکارتے ہیں وہ کچھ بھی فیصلہ نہیں کر سکتے۔ بیشک اللہ سننے والا ہے دیکھنے والا ہے۔', 'اور اللہ فیصلہ کرتا ہے انصاف سے [۲۶] اور جنکو پکارتے ہیں اُس کے سوائے نہیں فیصلہ کرتے کچھ بھی بیشک اللہ ہی وہی ہے سننے والا دیکھنے والا [۲۷]', 'And Allah judges with truth, while those to whom they invoke besides Him, cannot judge anything. Certainly, Allah! He is the All-Hearer, the All-Seer.', 'He will give His judgment with truth. And those whom they invoke beside Him cannot judge anything. Surely, it is Allah who is Hearing, Seeing.'),
(4154, 40, 21, 3, 8, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اَوَ لَمۡ یَسِیۡرُوۡا فِی الۡاَرۡضِ فَیَنۡظُرُوۡا کَیۡفَ کَانَ عَاقِبَۃُ  الَّذِیۡنَ کَانُوۡا مِنۡ قَبۡلِہِمۡ ؕ کَانُوۡا ہُمۡ  اَشَدَّ مِنۡہُمۡ  قُوَّۃً وَّ اٰثَارًا فِی الۡاَرۡضِ فَاَخَذَہُمُ اللّٰہُ بِذُنُوۡبِہِمۡ ؕ وَ مَا کَانَ لَہُمۡ مِّنَ اللّٰہِ مِنۡ وَّاقٍ ﴿۲۱﴾', 'کیا انہوں نے زمین میں سیر نہیں کی تاکہ دیکھ لیتے کہ جو لوگ ان سے پہلے تھے ان کا انجام کیسا ہوا۔ وہ ان سے زور اور زمین میں نشانات بنانے کے لحاظ سے کہیں بڑھ کر تھے تو اللہ نے انکو ان کے گناہوں کے سبب پکڑ لیا۔ اور انکو اللہ کے عذاب سے کوئی بھی بچانے والا نہ تھا۔', 'کیا وہ پھرے نہیں ملک میں کہ دیکھتے انجام کیسا ہوا اُنکا جو تھے اُن سے پہلے وہ تھے اُن سے سخت زور میں اور نشانیوں میں جو چھوڑ گئے زمین میں [۲۸] پھر اُنکو پکڑا اللہ نے اُنکے گناہوں پر اور نہ ہوا اُنکو اللہ سے کوئی بچانے والا [۲۹]', 'Have they not travelled in the land and seen what was the end of those who were before them? They were superior to them in strength, and in the traces (which they left) in the land. But Allah seized them with punishment for their sins. And none had they to protect them from Allah.', 'Have they not traveled through the earth and seen how was the fate of those who used to be before them? They were stronger than these in power and in traces left on the earth, but Allah seized them because of their sins. There was no one to save them from Allah.'),
(4155, 40, 22, 3, 8, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'ذٰلِکَ بِاَنَّہُمۡ کَانَتۡ تَّاۡتِیۡہِمۡ رُسُلُہُمۡ بِالۡبَیِّنٰتِ فَکَفَرُوۡا فَاَخَذَہُمُ اللّٰہُ ؕ اِنَّہٗ قَوِیٌّ شَدِیۡدُ الۡعِقَابِ ﴿۲۲﴾', 'یہ اس لئے کہ ان کے پاس پیغمبر کھلی دلیلیں لاتے تھے۔ تو وہ کفر کرتے تھے سو اللہ نے انکو پکڑ لیا۔ بیشک وہ صاحب قوت ہے سخت عذاب دینے والا ہے۔', 'یہ اس لئے کہ اُن کے پاس آتے تھے اُن کے رسول کھلی نشانیاں لیکر پھر منکر ہو گئے تو اُن کو پکڑا اللہ نے بیشک وہ زورآور ہے سخت عذاب دینے والا [۳۰]', 'That was because there came to them their Messengers with clear evidences, proofs and signs but they disbelieved (in them). So Allah seized them with punishment. Verily, He is All-Strong, Severe in punishment.', 'That was because messengers used to come to them with clear signs, but they disbelieved. Then, Allah seized them. Surely, He is Strong, severe in punishment.'),
(4156, 40, 23, 3, 8, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ لَقَدۡ اَرۡسَلۡنَا مُوۡسٰی بِاٰیٰتِنَا وَ سُلۡطٰنٍ مُّبِیۡنٍ ﴿ۙ۲۳﴾', 'اور ہم نے موسٰی کو اپنی نشانیاں اور دلیل روشن دے کر بھیجا۔', 'اور ہم نے بھیجا موسٰی کو اپنی نشانیاں دیکر اور کھلی سند [۳۱]', 'And indeed We sent Moosa (Moses) with Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), and a manifest authority,', 'Indeed We sent Mūsā with Our signs and a manifest proof'),
(4157, 40, 24, 3, 8, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اِلٰی فِرۡعَوۡنَ وَ ہَامٰنَ وَ قَارُوۡنَ فَقَالُوۡا سٰحِرٌ کَذَّابٌ ﴿۲۴﴾', 'یعنی فرعون اور ہامان اور قارون کی طرف تو ان لوگوں نے کہا کہ یہ تو جادوگر ہے جھوٹا۔', 'فرعون اور ہامان اور قارون کے پاس [۳۲] پھر کہنے لگے یہ جادوگر ہے جھوٹا [۳۳]', 'To Firaun (Pharaoh), Haman and Qaroon (Korah), but they called (him): \"A sorcerer, a liar!\"', 'to Pharaoh and Hāmān and Qārūn, but they said, “He is a sorcerer, a liar.”'),
(4158, 40, 25, 3, 8, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'فَلَمَّا جَآءَہُمۡ بِالۡحَقِّ مِنۡ عِنۡدِنَا قَالُوا اقۡتُلُوۡۤا اَبۡنَآءَ الَّذِیۡنَ اٰمَنُوۡا مَعَہٗ وَ اسۡتَحۡیُوۡا نِسَآءَہُمۡ ؕ وَ مَا کَیۡدُ الۡکٰفِرِیۡنَ   اِلَّا فِیۡ ضَلٰلٍ ﴿۲۵﴾', 'غرض جب وہ انکے پاس ہماری طرف سے حق لے کر پہنچے تو وہ کہنے لگے کہ جو لوگ اسکے ساتھ اللہ پر ایمان لائے ہیں انکے بیٹوں کو قتل کر دو اور بیٹیوں کو زندہ رہنے دو اور کافروں کی تدبیریں بے ٹھکانے ہوتی ہیں۔', 'پھر جب پہنچا انکے پاس لیکر سچی بات ہمارے پاس سے بولے مار ڈالو بیٹے انکے جو یقین لائے ہیں اسکے ساتھ اور جیتی رکھو انکی عورتیں [۳۴] اور جو داؤ ہے منکروں کا سو غلطی میں [۳۵]', 'Then, when he brought them the Truth from Us, they said: \"Kill the sons of those who believe with him and let their women live\", but the plots of disbelievers are nothing but errors!', 'And when he brought them the truth from Us, they said, “Kill the sons of those who have accepted faith with him, and spare the lives of their women.” But the plot of the disbelievers is nothing but a failure.'),
(4159, 40, 26, 3, 8, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ قَالَ فِرۡعَوۡنُ  ذَرُوۡنِیۡۤ  اَقۡتُلۡ مُوۡسٰی وَ لۡیَدۡعُ  رَبَّہٗ ۚ  اِنِّیۡۤ  اَخَافُ اَنۡ یُّبَدِّلَ دِیۡنَکُمۡ اَوۡ اَنۡ یُّظۡہِرَ فِی الۡاَرۡضِ الۡفَسَادَ ﴿۲۶﴾', 'اور فرعون بولا کہ مجھے چھوڑو کہ موسٰی  کو قتل کر دوں اور وہ اپنے پروردگار کو بلا لے مجھے ڈر ہے کہ وہ کہیں تمہارے دین کو نہ بدل دے یا ملک میں فساد نہ پیدا کر دے۔', 'اور بولا فرعون مجھکو چھوڑو کہ مار ڈالوں موسٰی کو اور پڑا پکارے اپنے رب کو [۳۶] میں ڈرتا ہوں کہ بگاڑ دے تمہارا دین یا پھیلائے ملک میں خرابی [۳۷]', 'Firaun (Pharaoh) said: \"Leave me to kill Moosa (Moses), and let him call his Lord (to stop me from killing him)! I fear that he may change your religion, or that he may cause mischief to appear in the land!\"', 'And Pharaoh said, “Let me kill Mūsā, and let him call his Lord. I am afraid that he will change your religion or he will cause havoc to appear in the land.”'),
(4160, 40, 27, 3, 8, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ قَالَ مُوۡسٰۤی اِنِّیۡ عُذۡتُ بِرَبِّیۡ وَ رَبِّکُمۡ مِّنۡ کُلِّ مُتَکَبِّرٍ لَّا یُؤۡمِنُ بِیَوۡمِ الۡحِسَابِ ﴿٪۲۷﴾', 'اور موسٰی  نے کہا کہ میں ہر متکبر سے جو حساب کے دن یعنی قیامت پر ایمان نہیں لاتا۔ اپنے اور تمہارے پروردگار کی پناہ لے چکا ہوں۔', 'اور کہا موسٰی نے میں پناہ لے چکا ہوں اپنے اور تمہارے رب کی ہر غرور والے سے [۳۸] جو یقین نہ کرے حساب کے دن کا [۳۹]', 'Moosa (Moses) said: \"Verily, I seek refuge in my Lord and your Lord from every arrogant who believes not in the Day of Reckoning!\"', 'And Mūsā said, “I have sought protection of my Lord and your Lord from every arrogant man who does not believe in the Day of Reckoning.”'),
(4161, 40, 28, 4, 9, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ قَالَ رَجُلٌ  مُّؤۡمِنٌ ٭ۖ مِّنۡ اٰلِ فِرۡعَوۡنَ یَکۡتُمُ  اِیۡمَانَہٗۤ  اَتَقۡتُلُوۡنَ رَجُلًا  اَنۡ یَّقُوۡلَ رَبِّیَ اللّٰہُ وَ قَدۡ جَآءَکُمۡ  بِالۡبَیِّنٰتِ مِنۡ رَّبِّکُمۡ ؕ وَ  اِنۡ یَّکُ  کَاذِبًا فَعَلَیۡہِ کَذِبُہٗ ۚ وَ اِنۡ یَّکُ صَادِقًا یُّصِبۡکُمۡ  بَعۡضُ الَّذِیۡ  یَعِدُکُمۡ ؕ اِنَّ اللّٰہَ  لَا یَہۡدِیۡ مَنۡ ہُوَ مُسۡرِفٌ  کَذَّابٌ ﴿۲۸﴾', 'اور فرعون کے لوگوں میں سے ایک مومن شخص جو اپنے ایمان کو پوشیدہ رکھتا تھا کہنے لگا کیا تم ایسے شخص کو قتل کرنا چاہتے ہو جو کہتا ہے کہ میرا پروردگار اللہ ہے اور وہ تمہارے پاس تمہارے پروردگار کی طرف سے نشانیاں بھی لے کر آیا ہے اور اگر وہ جھوٹا ہو گا تو اسکے جھوٹ کا ضرر اسی کو ہو گا۔ اور اگر سچا ہو گا تو کوئی سا عذاب جس کا وہ تم سے وعدہ کرتا ہے تم پر واقع ہو کر رہے گا۔ بیشک اللہ اس شخص کو ہدایت نہیں دیتا جو حد سے گزرنے والا ہے بڑا جھوٹا ہے۔', 'اور بولا ایک مرد ایماندار فرعون کے لوگوں میں جو چھپاتا تھا اپنا ایمان کیا مارے ڈالتے ہو ایک مرد کو اس بات پر کہ کہتا ہے میرا رب اللہ ہے اور لایا تمہارے پاس کھلی نشانیاں تمہارے رب کی اور اگر وہ جھوٹا ہو گا تو اس پر پڑے گا اس کا جھوٹ اور اگر وہ سچا ہو گا تو تم پر پڑے گا کوئی نہ کوئی وعدہ جو تم سے کرتا ہے [۴۰] بیشک اللہ راہ نہیں دیتا اسکو جو ہے بے لحاظ جھوٹا [۴۱]', 'And a believing man of Firauns (Pharaoh) family, who hid his faith said: \"Would you kill a man because he says: My Lord is Allah, and he has come to you with clear signs (proofs) from your Lord? And if he is a liar, upon him will be (the sin of) his lie; but if he is telling the truth, then some of that (calamity) wherewith he threatens you will befall on you.\" Verily, Allah guides not one who is a Musrif (a polytheist, or a murderer who shed blood without a right, or those who commit great sins, oppressor, transgressor), a liar!', 'And said a believing man from the House of Pharaoh who had kept his faith secret, “Would you kill a man because he says - ‘Allah is my Lord’ - while he has come to you with clear signs from your Lord? If he is a liar, his lie will fall back on himself, and if he is truthful, some of that (punishment) of which he warns you will afflict you. Indeed, Allah does not give guidance to anyone who is transgressor, a liar.'),
(4162, 40, 29, 4, 9, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'یٰقَوۡمِ لَکُمُ  الۡمُلۡکُ الۡیَوۡمَ ظٰہِرِیۡنَ فِی الۡاَرۡضِ ۫ فَمَنۡ یَّنۡصُرُنَا مِنۡۢ بَاۡسِ اللّٰہِ اِنۡ جَآءَنَا ؕ قَالَ فِرۡعَوۡنُ مَاۤ  اُرِیۡکُمۡ  اِلَّا مَاۤ  اَرٰی وَ مَاۤ   اَہۡدِیۡکُمۡ   اِلَّا سَبِیۡلَ  الرَّشَادِ ﴿۲۹﴾', 'اے قوم آج تمہاری ہی حکومت ہے اور تم ہی ملک میں غالب ہو لیکن اگر ہم پر اللہ کا عذاب آ گیا تو اسکے دور کرنے کے لئے ہماری مدد کون کرے گے؟ فرعون نے کہا کہ میں تمہیں وہی بات سجھاتا ہوں جو مجھے سوجھی ہے اور وہی راہ بتاتا ہوں جسمیں بھلائی ہے۔', 'اے میری قوم تمہارا راج ہے چڑھ رہے ہو ملک میں پھرکون مدد کرے گا ہماری اللہ کی آفت سے اگر آ گئ ہم پر [۴۲] بولا فرعون میں تو  وہی بات سمجھاتا ہوں تمکو جو سوجھی مجھکو اور  وہی راہ بتلاتا ہوں جس میں بھلائی ہے [۴۳]', '\"O my people! Yours is the kingdom this day, you are uppermost in the land. But who will save us from the Torment of Allah, should it befall us?\" Firaun (Pharaoh) said: \"I show you only that which I see (correct), and I guide you only to the path of right policy!\"', 'O my people, the kingdom is yours today, while you are dominant on the land. But, who is going to help us against Allah’s punishment, if it comes upon us?” Pharaoh said, “I do not give you an opinion unless I myself believe it to be correct, and I do not direct you to anything but to the right way.”'),
(4163, 40, 30, 4, 9, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ قَالَ الَّذِیۡۤ  اٰمَنَ یٰقَوۡمِ  اِنِّیۡۤ  اَخَافُ عَلَیۡکُمۡ  مِّثۡلَ  یَوۡمِ الۡاَحۡزَابِ ﴿ۙ۳۰﴾', 'تو جو مومن تھا وہ کہنے لگا کہ اے قوم مجھے تمہاری نسبت خوف ہے کہ تم پر دوسری امتوں کی طرح کے دن کا عذاب آ جائے۔', 'اور کہا اُسی ایمان دار نے اے قوم میری میں ڈرتا ہوں کہ آئے تم پر دن اگلے فرقوں کا سا', 'And he who believed said: \"O my people! Verily, I fear for you a fate like that day (of disaster) of the Confederates (of old)!', 'Said he who had believed, “I fear for you something like a day of the (disbelieving) groups (of the past),'),
(4164, 40, 31, 4, 9, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'مِثۡلَ  دَاۡبِ قَوۡمِ نُوۡحٍ وَّ عَادٍ وَّ ثَمُوۡدَ وَ الَّذِیۡنَ مِنۡۢ  بَعۡدِہِمۡ ؕ وَ مَا اللّٰہُ یُرِیۡدُ ظُلۡمًا  لِّلۡعِبَادِ ﴿۳۱﴾', 'جیسے نوح  کی قوم اور عاد اور ثمود اور جو لوگ انکے بعد آئے ہیں انکے حال کی طرح تمہارا حال نہ ہو جائے اور اللہ تو بندوں پر ظلم کرنا نہیں چاہتا۔', 'جیسے حال ہوا قوم نوح کا اور عاد اور ثمود کا اور جو لوگ انکے پیچھے ہوئے اور اللہ بے انصافی نہیں چاہتا بندوں پر [۴۴]', '\"Like the fate of the people of Nooh (Noah), and Ad, and Thamood and those who came after them. And Allah wills no injustice for (His) slaves.', 'like the fate of the people of NūH and ‘Ād and Thamūd and those who were after them - and Allah does not intend to do any injustice to His servants.'),
(4165, 40, 32, 4, 9, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ یٰقَوۡمِ  اِنِّیۡۤ  اَخَافُ عَلَیۡکُمۡ یَوۡمَ التَّنَادِ ﴿ۙ۳۲﴾', 'اور اے قوم مجھے تمہاری نسبت پکار کے دن یعنی روز قیامت کا خوف ہے۔', 'اور اے قوم میری میں ڈرتا ہوں کہ تم پر آئے دن ہانک پکار کا [۴۵]', '\"And, O my people! Verily! I fear for you the Day when there will be mutual calling (between the people of Hell and of Paradise).\"', 'And O my people, I fear for you a day in which people will call one another,'),
(4166, 40, 33, 4, 9, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'یَوۡمَ تُوَلُّوۡنَ  مُدۡبِرِیۡنَ ۚ مَا  لَکُمۡ  مِّنَ اللّٰہِ  مِنۡ عَاصِمٍ ۚ وَ  مَنۡ یُّضۡلِلِ  اللّٰہُ  فَمَا لَہٗ  مِنۡ ہَادٍ ﴿۳۳﴾', 'جس دن تم پیٹھ پھیر کر قیامت کے میدان سے بھاگو گے اس دن تمکو کوئی عذاب الٰہی سے بچانے والا نہ ہو گا اور جس شخص کو اللہ گمراہ رہنے دے اسکو کوئی ہدایت دینے والا نہیں۔', 'جس دن بھاگو گے پیٹھ پھیر کر [۴۶] کوئی نہیں تم کو اللہ سے بچانے والا اور جس کو غلطی میں ڈالے اللہ تو کوئی نہیں اسکو سجانے والا [۴۷]', 'A Day when you will turn your backs and flee having no protector from Allah, And whomsoever Allah sends astray, for him there is no guide.', 'a day when you will turn back on your heels, having no one to save you from Allah - but, whomever Allah lets go astray, for him there is no one to guide.'),
(4167, 40, 34, 4, 9, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ لَقَدۡ جَآءَکُمۡ یُوۡسُفُ مِنۡ قَبۡلُ بِالۡبَیِّنٰتِ فَمَا زِلۡتُمۡ فِیۡ  شَکٍّ  مِّمَّا جَآءَکُمۡ بِہٖ ؕ حَتّٰۤی  اِذَا ہَلَکَ قُلۡتُمۡ لَنۡ یَّبۡعَثَ اللّٰہُ  مِنۡۢ بَعۡدِہٖ  رَسُوۡلًا ؕ کَذٰلِکَ یُضِلُّ اللّٰہُ مَنۡ ہُوَ  مُسۡرِفٌ مُّرۡتَابُۨ ﴿ۚۖ۳۴﴾', 'اور پہلے یوسف  بھی تمہارے پاس کھلی باتیں لے کر آئے تھے تو جو وہ لائے تھے اس کی طرف سے تم برابر شک ہی میں رہے یہاں تک کہ جب وہ وفات پا گئے تو تم کہنے لگے کہ اللہ انکے بعد کبھی کوئی پیغمبر نہیں بھیجے گا۔ اسی طرح اللہ اس شخص کو گمراہ رہنے دیتا ہے جو حد سے نکل جانے والا شک کرنے والا ہو۔', 'اور تمہارے پاس آ چکا ہے یوسف اس سے پہلے کھلی باتیں لے کر پھر تم رہے دھوکے ہی میں ان چیزوں سے جو  وہ تمہارے پاس لے کر  آیا یہاں تک کہ جب مر گیا لگے کہنے ہرگز نہ بھیجے گا اللہ اسکے بعد کوئی رسول [۴۸] اِسی طرح بھٹکاتا ہے اللہ اُس کو جو ہو بیباک شک کرنے والا', 'And indeed Yoosuf (Joseph) did come to you, in times gone by, with clear signs, but you ceased not to doubt in that which he did bring to you, till when he died you said: \"No Messenger will Allah send after him.\" Thus Allah leaves astray him who is a Musrif (a polytheist, oppressor, a criminal, sinner who commit great sins) and a Murtab (one who doubts Allahs Warning and His Oneness).', 'And Yūsuf had already come to you earlier with clear signs, but you remained in suspicion about what he brought to you - until when he died, you said, ‘Allah will never send a messenger after him.’ That is how Allah lets go astray anyone who crosses limits and lives in doubt, -'),
(4168, 40, 35, 4, 9, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'الَّذِیۡنَ یُجَادِلُوۡنَ فِیۡۤ  اٰیٰتِ اللّٰہِ بِغَیۡرِ سُلۡطٰنٍ اَتٰہُمۡ ؕ کَبُرَ مَقۡتًا عِنۡدَ اللّٰہِ وَ عِنۡدَ الَّذِیۡنَ اٰمَنُوۡا ؕ کَذٰلِکَ یَطۡبَعُ اللّٰہُ  عَلٰی کُلِّ  قَلۡبِ مُتَکَبِّرٍ  جَبَّارٍ ﴿۳۵﴾', 'جو لوگ بغیر اسکے کہ انکے پاس کوئی دلیل آئی ہو اللہ کی آیتوں میں جھگڑتے ہیں۔ اللہ کے نزدیک اور مومنوں کے نزدیک جھگڑا سخت ناپسند ہے۔ اسی طرح اللہ ہر متکبر سرکش کے دل پر مہر لگا دیتا ہے۔', 'وہ جو کہ جھگڑتے ہیں اللہ کی باتوں میں بغیر کسی سند کے جو پہنچی ہو اُنکو  بڑی بیزاری ہے اللہ کے یہاں اور ایمانداروں کے یہاں [۴۹] اِسی طرح مہر کر دیتا ہے اللہ ہر دل پر غرور کرنے والے سرکش کے [۵۰]', 'Those who dispute about the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah, without any authority that has come to them, it is greatly hateful and disgusting to Allah and to those who believe. Thus does Allah seal up the heart of every arrogant, tyrant. (So they cannot guide themselves to the Right Path).', 'those who quarrel in Allah’s verses without any authority having reached them. It is terribly hateful with Allah and with those who believe. That is how Allah stamps a seal on the entire heart of an arrogant tyrant.”'),
(4169, 40, 36, 4, 9, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ قَالَ فِرۡعَوۡنُ یٰہَامٰنُ ابۡنِ  لِیۡ صَرۡحًا لَّعَلِّیۡۤ  اَبۡلُغُ  الۡاَسۡبَابَ ﴿ۙ۳۶﴾', 'اور فرعون نے کہا کہ ہامان میرے لئے ایک محل بناؤ تاکہ میں اس پر چڑھ کر رستوں پر پہنچ جاؤں۔', 'اور بولا فرعون کے اے ہامان بنا میرے واسطے ایک اونچا محل شاید میں جا پہنچوں رستوں میں', 'And Firaun (Pharaoh) said: \"O Haman! Build me a tower that I may arrive at the ways,', 'And Fir‘aun (Pharaoh) said, “O Hāmān, make a tower for me, perhaps I could reach the ways -'),
(4170, 40, 37, 4, 9, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اَسۡبَابَ السَّمٰوٰتِ فَاَطَّلِعَ  اِلٰۤی  اِلٰہِ مُوۡسٰی وَ اِنِّیۡ لَاَظُنُّہٗ کَاذِبًا ؕ وَ کَذٰلِکَ زُیِّنَ  لِفِرۡعَوۡنَ سُوۡٓءُ عَمَلِہٖ وَ صُدَّ عَنِ السَّبِیۡلِ ؕ وَ مَا کَیۡدُ فِرۡعَوۡنَ  اِلَّا فِیۡ  تَبَابٍ  ﴿٪۳۷﴾', 'یعنی آسمان کے رستوں پر پھر موسٰی  کے معبود کو جھانک کر دیکھ لوں اور میں تو اسے جھوٹا سمجھتا ہوں۔ اور اسی طرح فرعون کو اسکے اعمال بد اچھے معلوم ہوتے تھے اور وہ رستے سے روک دیا گیا تھا۔ اور فرعون کی تدبیر تو بیکار تھی۔', 'رستوں میں آسمانوں کے پھر جھانک کر دیکھوں موسٰی کے معبود کو [۵۱] اور میری اٹکل میں تو وہ جھوٹا ہے [۵۲] اور اسی طرح بھلے دکھلا دیے فرعون کو اسکے برے کام اور  روک دیا گیا سیدھی راہ سے [۵۳] اور جو داؤ تھا فرعون کا سو تباہ ہونے کے واسطے [۵۴]', '\"The ways of the heavens, and I may look upon the Ilah (God) of Moosa (Moses) but verily, I think him to be a liar.\" Thus it was made fair-seeming, in Firauns (Pharaoh) eyes, the evil of his deeds, and he was hindered from the (Right) Path, and the plot of Firaun (Pharaoh) led to nothing but loss and destruction (for him).', 'the ways to the heavens, and peek towards the God of Mūsā. And indeed I deem him a liar.” That is how his evil deeds were made attractive to Fir‘aun, and (how) he was held back from the way. The evil design of Fir‘aun was (to end) in nothing but ruin.'),
(4171, 40, 38, 5, 10, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ قَالَ الَّذِیۡۤ  اٰمَنَ یٰقَوۡمِ اتَّبِعُوۡنِ اَہۡدِکُمۡ  سَبِیۡلَ  الرَّشَادِ ﴿ۚ۳۸﴾', 'اور وہ شخص جو مومن تھا اسنے کہا کہ بھائیو میرے پیچھے چلو میں تمہیں بھلائی کا رستہ دکھاؤں گا۔', 'اور کہا اسی ایماندار نے اے قوم راہ چلو میری پہنچا دوں تمکو نیکی کی راہ پر [۵۵]', 'And the man who believed said: \"O my people! Follow me, I will guide you to the way of right conduct (i.e. guide you to Allahs religion of Islamic Monotheism with which Moosa (Moses) has been sent).', 'And said he who had believed, “O my people, follow me, I will show you the path of guidance.'),
(4172, 40, 39, 5, 10, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'یٰقَوۡمِ  اِنَّمَا ہٰذِہِ  الۡحَیٰوۃُ  الدُّنۡیَا مَتَاعٌ ۫ وَّ اِنَّ الۡاٰخِرَۃَ ہِیَ دَارُ الۡقَرَارِ ﴿۳۹﴾', 'بھائیو یہ دنیا کی زندگی چند روز فائدہ اٹھانے کی چیز ہے۔ اور جو آخرت ہے وہی ہمیشہ رہنے کا گھر ہے۔', 'اے میری قوم یہ جو زندگی ہے دنیا کی سو کچھ برت لینا ہے اور وہ گھر جو پچھلا ہے وہی ہے جم کر رہنے کا گھر [۵۶]', '\"O my people! Truly, this life of the world is nothing but a (quick passing) enjoyment, and verily, the Hereafter that is the home that will remain forever.\"', 'O my people, this life of the world is only a (momentary) benefit, while the Hereafter is, indeed, the place of permanent living.'),
(4173, 40, 40, 5, 10, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'مَنۡ عَمِلَ سَیِّئَۃً  فَلَا یُجۡزٰۤی  اِلَّا مِثۡلَہَا ۚ وَ مَنۡ عَمِلَ صَالِحًا مِّنۡ  ذَکَرٍ اَوۡ اُنۡثٰی وَ ہُوَ مُؤۡمِنٌ  فَاُولٰٓئِکَ یَدۡخُلُوۡنَ الۡجَنَّۃَ یُرۡزَقُوۡنَ فِیۡہَا بِغَیۡرِ  حِسَابٍ ﴿۴۰﴾', 'جو برے کام کرے گا اسکو بدلہ بھی ویسا ہی ملے گا اور جو نیک کام کرے گا مرد ہو یا عورت جبکہ وہ صاحب ایمان بھی ہو تو ایسے لوگ بہشت میں داخل ہوں گے وہاں انکو بے حساب رزق ملے گا۔', 'جس نے کی ہے برائی تو وہی بدلا پائے گا اسکی برابر اور جس نے کی ہے بھلائی مرد ہو یا عورت اور وہ یقین رکھتا ہو سو وہ لوگ جائیں گے بہشت میں روزی پائیں گے وہاں بے شمار [۵۷]', '\"Whosoever does an evil deed, will not be requited except the like thereof, and whosoever does a righteous deed, whether male or female and is a true believer (in the Oneness of Allah), such will enter Paradise, where they will be provided therein (with all things in abundance) without limit.', 'The one who does something evil will not be punished but in its equal proportion, but the one who does a righteous deed, be he male or female, while he is a believer, then, such people will enter the Jannah (Paradise) where they will be provided with bounties beyond reckoning.'),
(4174, 40, 41, 5, 10, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ یٰقَوۡمِ مَا لِیۡۤ  اَدۡعُوۡکُمۡ  اِلَی النَّجٰوۃِ وَ تَدۡعُوۡنَنِیۡۤ   اِلَی  النَّارِ ﴿ؕ۴۱﴾', 'اور اے قوم میرا کیا حال ہے کہ میں تو تمکو نجات کی طرف بلاتا ہوں اور تم مجھے دوزخ کی آگ کی طرف بلاتے ہو۔', 'اور اے قوم مجھکو کیا ہوا ہے بلاتا ہوں تمکو نجات کی طرف اور تم بلاتے ہو مجھکو آگ کی طرف [۵۸]', '\"And O my people! How is it that I call you to salvation while you call me to the Fire!', 'And O my people, what is wrong with me that I call you to salvation and you call me to the Fire?'),
(4175, 40, 42, 5, 10, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'تَدۡعُوۡنَنِیۡ  لِاَکۡفُرَ بِاللّٰہِ وَ اُشۡرِکَ بِہٖ مَا لَیۡسَ لِیۡ بِہٖ عِلۡمٌ ۫ وَّ اَنَا  اَدۡعُوۡکُمۡ  اِلَی الۡعَزِیۡزِ  الۡغَفَّارِ ﴿۴۲﴾', 'تم مجھے اس لئے بلاتے ہو کہ اللہ کے ساتھ کفر کروں اور اس چیز کو اس کا شریک مقرر کروں جس کا مجھے کچھ بھی علم نہیں۔ اور میں تمکو عزت و اقتدار والے بخشنے والے معبود کی طرف بلاتا ہوں۔', 'تم بلاتے ہو مجھکو کہ منکر ہو جاؤں اللہ سے اور شریک ٹھہراؤں  اُسکا اُسکو جسکی مجھکو خبر نہیں [۵۹] اور میں بلاتا ہوں تمکو اس زبردست گناہ بخشنے والے کی طرف [۶۰]', '\"You invite me to disbelieve in Allah (and in His Oneness), and to join partners in worship with Him; of which I have no knowledge, and I invite you to the All-Mighty, the Oft-Forgiving!', 'You invite me to reject my belief in Allah and ascribe to Him partners about whom I have no knowledge, while I invite you to (Him who is) the Mighty, the Most-Forgiving.'),
(4176, 40, 43, 5, 10, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'لَا جَرَمَ  اَنَّمَا تَدۡعُوۡنَنِیۡۤ  اِلَیۡہِ لَیۡسَ لَہٗ دَعۡوَۃٌ  فِی الدُّنۡیَا وَ لَا فِی الۡاٰخِرَۃِ  وَ اَنَّ مَرَدَّنَاۤ  اِلَی اللّٰہِ وَ اَنَّ الۡمُسۡرِفِیۡنَ ہُمۡ اَصۡحٰبُ النَّارِ ﴿۴۳﴾', 'سچ تو یہ ہے کہ جس چیز کی طرف تم بلاتے ہو اسکو دنیا اور آخرت میں بلانے کا کوئی فائدہ نہیں اور ہمکو اللہ کی طرف لوٹنا ہے اور حد سے نکل جانے والے ہی دوزخی ہیں۔', 'آپ ہی ظاہر ہے کہ جس کی طرف تم مجھکو بلاتے ہو اس کا بلاوا کہیں نہیں دنیا میں اور نہ آخرت میں [۶۱] اور یہ کہ ہم کو پھر جانا ہے اللہ کے پاس اور یہ کہ زیادتی والے وہی ہیں دوزخ کے لوگ [۶۲]', '\"No doubt you call me to (worship) one who cannot grant (me) my request (or respond to my invocation) in this world or in the Hereafter. And our return will be to Allah, and Al-Musrifoon (i.e. polytheists and arrogants, those who commit great sins, the transgressors of Allahs set limits)! They shall be the dwellers of the Fire!', 'It is obvious that those (gods) to whom you are inviting me are not worth calling, neither in this world nor in the world to come, and that we have to return back to Allah, and that the transgressors are indeed the people of the Fire.'),
(4177, 40, 44, 5, 10, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'فَسَتَذۡکُرُوۡنَ مَاۤ  اَقُوۡلُ لَکُمۡ ؕ وَ اُفَوِّضُ اَمۡرِیۡۤ  اِلَی اللّٰہِ ؕ اِنَّ اللّٰہَ  بَصِیۡرٌۢ بِالۡعِبَادِ ﴿۴۴﴾', 'جو بات میں تم سے کہتا ہوں تم اسے آگے چل کر یاد کرو گے۔ اور میں اپنا معاملہ اللہ کے سپرد کرتا ہوں۔ بیشک اللہ بندوں کو دیکھنے والا ہے۔', 'سو آگے یاد کرو گے جو میں کہتا ہوں تمکو [۶۳] اور میں سونپتا ہوں اپنا کام اللہ کو بیشک اللہ کی نگاہ میں ہیں سب بندے [۶۴]', '\"And you will remember what I am telling you, and my affair I leave it to Allah. Verily, Allah is the All-Seer of (His) slaves.\"', 'Soon you will remember what I am saying to you. And I entrust my matter with Allah. Surely, Allah has all (His) servants in sight.”'),
(4178, 40, 45, 5, 10, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'فَوَقٰىہُ اللّٰہُ سَیِّاٰتِ مَا مَکَرُوۡا وَ حَاقَ بِاٰلِ  فِرۡعَوۡنَ سُوۡٓءُ  الۡعَذَابِ ﴿ۚ۴۵﴾', 'غرض اللہ نے اسکو ان لوگوں کی تدبیروں کی برائیوں سے محفوظ رکھا اور فرعون والوں کو برے عذاب نے آ گھیرا۔', 'پھر بچا لیا موسٰی کوا للہ نے برے داؤں سے جو  وہ کرتے تھے اور الٹ پڑا فرعون والوں پر بری طرح کا عذاب [۶۵]', 'So Allah saved him from the evils that they plotted (against him), while an evil torment encompassed Firauns (Pharaoh) people.', 'Then Allah saved him from the evils of what they designed, and the House of Pharaoh was encircled by an evil punishment.'),
(4179, 40, 46, 5, 10, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اَلنَّارُ یُعۡرَضُوۡنَ عَلَیۡہَا غُدُوًّا وَّ عَشِیًّا ۚ وَ یَوۡمَ تَقُوۡمُ السَّاعَۃُ ۟ اَدۡخِلُوۡۤا  اٰلَ فِرۡعَوۡنَ اَشَدَّ الۡعَذَابِ ﴿۴۶﴾', 'یعنی آتش جہنم کہ صبح و شام اسکے سامنے پیش کئے جاتے ہیں۔ اور جس روز قیامت برپا ہو گی حکم ہو گا کہ فرعون والوں کو سخت عذاب میں داخل کرو۔', 'وہ آگ ہے کہ دکھلا دیتے ہیں اُنکو صبح و شام [۶۶] اور جس دن قائم ہو گی قیامت حکم ہو گا داخل کرو فرعون والوں کو سخت سے سخت عذاب میں', 'The Fire; they are exposed to it, morning and afternoon, and on the Day when the Hour will be established (it will be said to the angels): \"Cause Firauns (Pharaoh) people to enter the severest torment!\"', 'It is the Fire before which they are presented morning and evening. And on the day when the Hour (of final judgment) will take place, (the order will be released,): “Admit the family of Pharaoh into the most severe punishment.”'),
(4180, 40, 47, 5, 10, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ اِذۡ یَتَحَآجُّوۡنَ فِی النَّارِ فَیَقُوۡلُ الضُّعَفٰٓؤُا لِلَّذِیۡنَ اسۡتَکۡبَرُوۡۤا اِنَّا کُنَّا لَکُمۡ تَبَعًا فَہَلۡ  اَنۡتُمۡ مُّغۡنُوۡنَ عَنَّا نَصِیۡبًا مِّنَ النَّارِ ﴿۴۷﴾', 'اور جب وہ دوزخ میں جھگڑیں گے تو غریب لوگ بڑے آدمیوں سے کہیں گے کہ ہم تو تمہارے تابع تھے تو کیا تم دوزخ کے عذاب کا کچھ حصہ ہم سے دور کر سکتے ہو؟', 'اور جب آپس میں جھگڑیں گے آگ کے اندر پھر کہیں گے کمزور غرور کرنے والوں کو ہم تھے تمہارے تابع  پھر کچھ تم ہم پر سے اٹھا لو گے حصہ آگ کا [۶۷]', 'And, when they will dispute in the Fire, the weak will say to those who were arrogant; \"Verily! We followed you, can you then take from us some portion of the Fire?\"', 'And (worth remembering is the time) when they (the infidels) will argue with each other in the Fire. So, the weak will say to those who were arrogant, “Surely, we used to be your followers, would you, then, stand for us in (suffering at least a) part of the (punishment of) Fire?”'),
(4181, 40, 48, 5, 10, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'قَالَ الَّذِیۡنَ اسۡتَکۡبَرُوۡۤا  اِنَّا  کُلٌّ  فِیۡہَاۤ  ۙ اِنَّ اللّٰہَ  قَدۡ حَکَمَ  بَیۡنَ الۡعِبَادِ ﴿۴۸﴾', 'بڑے آدمی کہیں گے کہ تم بھی اور ہم بھی سب دوزخ میں ہیں اللہ بندوں میں فیصلہ کر چکا ہے۔', 'کہیں گے جو غرور کرتے تھے ہم سبھی پڑے ہوئے ہیں اسمیں بیشک اللہ فیصلہ کر چکا بندوں میں [۶۸]', 'Those who were arrogant will say: \"We are all (together) in this (Fire)! Verily Allah has judged between (His) slaves!\"', 'Those who were arrogant will say, “We all are in it. Allah has already passed the judgment between (His) servants.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(4182, 40, 49, 5, 10, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ قَالَ الَّذِیۡنَ فِی النَّارِ لِخَزَنَۃِ جَہَنَّمَ ادۡعُوۡا رَبَّکُمۡ یُخَفِّفۡ عَنَّا یَوۡمًا مِّنَ الۡعَذَابِ ﴿۴۹﴾', 'اور جو لوگ آگ میں جل رہے ہوں گے وہ دوزخ کے داروغوں سے کہیں گے کہ اپنے پروردگار سے پکار کر کہو کہ وہ ایک روز تو ہم سے تھوڑا سا عذاب ہلکا کر دے۔', 'اور کہیں گے جو لوگ پڑے ہیں آگ میں دوزخ کے داروغوں کو مانگو  اپنے رب سے کہ ہم پر ہلکا کر دے ایک دن تھوڑا عذاب [۶۹]', 'And those in the Fire will say to the keepers (angels) of Hell: \"Call upon your Lord to lighten for us the torment for a day!\"', 'And those in the Fire will say to the keepers of Jahannam (Hell), “Pray to your Lord to lighten the punishment for us some day.”'),
(4183, 40, 50, 5, 10, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'قَالُوۡۤا  اَوَ لَمۡ تَکُ تَاۡتِیۡکُمۡ رُسُلُکُمۡ بِالۡبَیِّنٰتِ ؕ قَالُوۡا  بَلٰی ؕ قَالُوۡا فَادۡعُوۡا ۚ وَ مَا  دُعٰٓؤُا الۡکٰفِرِیۡنَ  اِلَّا فِیۡ ضَلٰلٍ ﴿٪۵۰﴾', 'وہ کہیں گے کہ کیا تمہارے پاس تمہارے پیغمبر نشانیاں لے کر نہیں آئے تھے۔ دوزخی کہیں گے کیوں نہیں تو وہ کہیں گے کہ تم ہی پکار لو۔ اور کافروں کی پکار اس روز بے کار ہو گی۔', 'وہ بولے کیا نہ آتے تھے تمہارے پاس تمہارے رسول کھلی نشانیاں لے کر کہیں گے کیوں نہیں بولے پھر پکارو اور کچھ نہیں کافروں کا پکارنا مگر بھٹکنا [۷۰]', 'They will say: \"Did there not come to you, your Messengers with (clear) evidences and signs? They will say: \"Yes.\" They will reply: \"Then call (as you like)! And the invocation of the disbelievers is nothing but in error!\"', 'They will say, “Had your messengers not been coming to you with open signs?” They will say, “Of course, (they had come).” They (the keepers) will say, “Then, keep praying” - but praying of disbelievers (in the Hereafter) is only in vain.'),
(4184, 40, 51, 6, 11, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اِنَّا لَنَنۡصُرُ  رُسُلَنَا وَ الَّذِیۡنَ اٰمَنُوۡا فِی الۡحَیٰوۃِ  الدُّنۡیَا وَ یَوۡمَ یَقُوۡمُ الۡاَشۡہَادُ ﴿ۙ۵۱﴾', 'ہم اپنے پیغمبروں کی اور جو لوگ ایمان لائے ہیں انکی دنیا کی زندگی میں بھی مدد کرتے ہیں اور جس دن گواہ کھڑے ہوں گے یعنی قیامت کو بھی۔', 'ہم مدد کرتے ہیں اپنے رسولوں کی اور ایمان والوں کی دنیا کی زندگانی میں [۷۱] اور جب کھڑے ہوں گے گواہ [۷۲]', 'Verily, We will indeed make victorious Our Messengers and those who believe (in the Oneness of Allah Islamic Monotheism) in this worlds life and on the Day when the witnesses will stand forth, (i.e. Day of Resurrection),', 'Surely, We do help Our messengers and the believers, in the worldly life, as well as (we will help them) on the day in which witnesses will stand (to give their testimony)-'),
(4185, 40, 52, 6, 11, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'یَوۡمَ لَا یَنۡفَعُ الظّٰلِمِیۡنَ مَعۡذِرَتُہُمۡ وَ لَہُمُ  اللَّعۡنَۃُ  وَ لَہُمۡ  سُوۡٓءُ  الدَّارِ  ﴿۵۲﴾', 'جس دن ظالموں کو انکی معذرت کچھ فائدہ نہ دے گی اور ان کے لئے لعنت اور ان کے لئے برا گھر ہے۔', 'جس دن کام نہ آئیں گے منکروں کو انکے بہانے اور انکو پھٹکار ہے اور ان کے واسطے برا گھر [۷۳]', 'The Day when their excuses will be of no profit to Zalimoon (polytheists, wrong-doers and disbelievers in the Oneness of Allah). Theirs will be the curse, and theirs will be the evil abode (i.e. painful torment in Hell-fire).', 'a day when apology of the unjust will bring them no benefit, and on them shall be the curse, and for them will be the evil abode.'),
(4186, 40, 53, 6, 11, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ  لَقَدۡ اٰتَیۡنَا مُوۡسَی الۡہُدٰی وَ اَوۡرَثۡنَا بَنِیۡۤ  اِسۡرَآءِیۡلَ الۡکِتٰبَ ﴿ۙ۵۳﴾', 'اور ہم نے موسٰی  کو ہدایت کی کتاب دی اور بنی اسرائیل کو اس کتاب کا وارث بنایا۔', 'اور ہم نے دی موسٰی کو راہ کی سوجھ اور وارث کیا بنی اسرائیل کو کتاب کا', 'And, indeed We gave Moosa (Moses) the guidance, and We caused the Children of Israel to inherit the Scripture (i.e. the Taurat (Torah)),', 'We gave Guidance to Mūsā, while We made the children of Isrā’īl inherit the Book -'),
(4187, 40, 54, 6, 11, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'ہُدًی وَّ ذِکۡرٰی لِاُولِی الۡاَلۡبَابِ  ﴿۵۴﴾', 'جو عقل والوں کے لئے ہدایت اور نصیحت تھی۔', 'سجھانے اور سمجھانے والے عقل مندوں کو [۷۴]', 'A guide and a reminder for men of understanding.', 'as a guide and advice for people of understanding.'),
(4188, 40, 55, 6, 11, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'فَاصۡبِرۡ  اِنَّ وَعۡدَ اللّٰہِ حَقٌّ وَّ اسۡتَغۡفِرۡ لِذَنۡۢبِکَ وَ سَبِّحۡ بِحَمۡدِ رَبِّکَ بِالۡعَشِیِّ وَ الۡاِبۡکَارِ ﴿۵۵﴾', 'لہذا صبر کرو بیشک اللہ کا وعدہ سچا ہے اور اپنی کوتاہی کیلئے معافی مانگو اور صبح و شام اپنے پروردگار کی تعریف کے ساتھ تسبیح کرتے رہو۔', 'سو تو ٹھہرا رہ بیشک وعدہ اللہ کا ٹھیک ہے اور بخشوا اپنا گناہ اور پاکی بول اپنے رب کی خوبیاں شام کو اور صبح کو [۷۵]', 'So be patient (O Muhammad SAW). Verily, the Promise of Allah is true, and ask forgiveness for your fault, and glorify the praises of your Lord in the Ashi (i.e. the time period after the midnoon till sunset) and in the Ibkar (i.e. the time period from early morning or sunrise till before midnoon) (it is said that, that means the five compulsory congregational Salat (prayers) or the Asr and Fajr prayers).', 'So, be patient - surely the promise of Allah is true - and seek forgiveness for your sins, and proclaim the purity and praise of your Lord in the afternoon and at dawn.'),
(4189, 40, 56, 6, 11, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اِنَّ الَّذِیۡنَ یُجَادِلُوۡنَ فِیۡۤ  اٰیٰتِ اللّٰہِ  بِغَیۡرِ سُلۡطٰنٍ اَتٰہُمۡ ۙ اِنۡ فِیۡ صُدُوۡرِہِمۡ  اِلَّا کِبۡرٌ مَّا ہُمۡ بِبَالِغِیۡہِ ۚ فَاسۡتَعِذۡ بِاللّٰہِ ؕ اِنَّہٗ  ہُوَ  السَّمِیۡعُ  الۡبَصِیۡرُ ﴿۵۶﴾', 'جو لوگ بغیر کسی دلیل کے جو انکے پاس آئی ہو اللہ کی آیتوں میں جھگڑتے ہیں انکے دلوں میں اور کچھ نہیں ایسی بڑائی ہے جسکو وہ پہنچنے والے نہیں تو اللہ کی پناہ مانگو۔ بیشک وہ سننے والا ہے دیکھنے والا ہے۔', 'جو لوگ جھگڑتے ہیں اللہ کی باتوں میں بغیر کسی سند کے جو پہنچی ہو انکو اور کوئی بات نہیں انکے دلوں میں غرور ہے کہ کبھی نہ پہنچیں گے اُس تک [۷۶] سو تو پناہ مانگ اللہ کی بیشک وہ سنتا دیکھتا ہے [۷۷]', 'Verily, those who dispute about the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah, without any authority having come to them, there is nothing else in their breasts except pride (to accept you (Muhammad SAW) as a Messenger of Allah and to obey you). They will never have it (i.e. Prophethood which Allah has bestowed upon you). So seek refuge in Allah (O Muhammad SAW from the arrogants). Verily, it is He Who is the All-Hearer, the All-Seer.', 'Surely, those who quarrel in Allah’s verses without any authority having reached them, there is nothing in their hearts but pride of greatness that they are not (able) to reach. So, seek refuge with Allah. Surely, He is the All-Hearing, the All-Seeing.'),
(4190, 40, 57, 6, 11, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'لَخَلۡقُ السَّمٰوٰتِ وَ الۡاَرۡضِ  اَکۡبَرُ مِنۡ خَلۡقِ النَّاسِ وَ لٰکِنَّ  اَکۡثَرَ النَّاسِ لَا  یَعۡلَمُوۡنَ ﴿۵۷﴾', 'آسمانوں اور زمین کا پیدا کرنا لوگوں کے پیدا کرنے کی نسبت بڑا کام ہے لیکن اکثر لوگ نہیں جانتے۔', 'البتہ پیدا کرنا آسمانوں اور زمین کا بڑا ہے لوگوں کے بنانے سے لیکن بہت لوگ نہیں سمجھتے [۷۸]', 'The creation of the heavens and the earth is indeed greater than the creation of mankind, yet most of mankind know not.', 'Certainly, the creation of the heavens and the earth is greater than the creation of human beings, but most human beings do not know.'),
(4191, 40, 58, 6, 11, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ مَا یَسۡتَوِی الۡاَعۡمٰی وَ الۡبَصِیۡرُ ۬ۙ وَ الَّذِیۡنَ  اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ وَ لَا الۡمُسِیۡٓءُ ؕ قَلِیۡلًا مَّا تَتَذَکَّرُوۡنَ ﴿۵۸﴾', 'اور اندھا اور آنکھ والا برابر نہیں۔ اور نہ ایمان لانے والے نیکوکار اور نہ بدکار برابر ہیں حقیقت یہ ہے کہ تم بہت کم غور کرتے ہو۔', 'اور برابر نہیں اندھا اور آنکھوں والا اور نہ ایماندار جو بھلے کام کرتے ہیں اور نہ بدکار تم بہت کم سوچ کرتے ہو [۷۹]', 'And not equal are the blind and those who see, nor are (equal) those who believe (in the Oneness of Allah Islamic Monotheism), and do righteous good deeds, and those who do evil. Little do you remember!', 'The blind one and the sighted one are not equal, and those who believed and did good deeds and the evil ones are not (equal) either. Little you heed to the advice!'),
(4192, 40, 59, 6, 11, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اِنَّ السَّاعَۃَ  لَاٰتِیَۃٌ  لَّا رَیۡبَ فِیۡہَا وَ لٰکِنَّ  اَکۡثَرَ النَّاسِ لَا یُؤۡمِنُوۡنَ ﴿۵۹﴾', 'قیامت تو آنے والی ہے اسکے آنے میں کچھ شک نہیں۔ لیکن اکثر لوگ ایمان نہیں رکھتے۔', 'تحقیق قیامت آنی ہے اس میں دھوکا نہیں  ولیکن بہت لوگ نہیں مانتے', 'Verily, the Hour (Day of Judgement) is surely coming, therein is no doubt, yet most men believe not.', 'Certainly, the Hour is bound to come. There is no doubt in it, but most of the people do not believe.'),
(4193, 40, 60, 6, 11, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ قَالَ رَبُّکُمُ  ادۡعُوۡنِیۡۤ   اَسۡتَجِبۡ لَکُمۡ ؕ اِنَّ  الَّذِیۡنَ یَسۡتَکۡبِرُوۡنَ عَنۡ عِبَادَتِیۡ سَیَدۡخُلُوۡنَ جَہَنَّمَ دٰخِرِیۡنَ ﴿٪۶۰﴾', 'اور تمہارے پروردگار نے فرمایا ہے کہ تم مجھ سے دعا کرو میں تمہاری دعا قبول کروں گا۔ جو لوگ میری عبادت سے ازراہ تکبر کتراتے ہیں۔ عنقریب جہنم میں ذلیل ہو کر داخل ہوں گے۔', 'اور کہتا ہے تمہارا رب مجھ کو  پکارو کہ پہنچوں تمہاری پکار کو [۸۰] بیشک جو لوگ تکبر کرتے ہیں میری بندگی سے اب داخل ہوں گے دوزخ میں ذلیل ہو کر [۸۱]', 'And your Lord said: \"Invoke Me, (i.e. believe in My Oneness (Islamic Monotheism)) (and ask Me for anything) I will respond to your (invocation). Verily! Those who scorn My worship (i.e. do not invoke Me, and do not believe in My Oneness, (Islamic Monotheism)) they will surely enter Hell in humiliation!\"', 'Your Lord has said, “Call Me, I will respond to you. Definitely those who show arrogance against worshipping Me shall enter Jahannam (Hell) with disgrace.'),
(4194, 40, 61, 7, 12, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اَللّٰہُ  الَّذِیۡ جَعَلَ  لَکُمُ الَّیۡلَ  لِتَسۡکُنُوۡا فِیۡہِ وَ النَّہَارَ مُبۡصِرًا ؕ اِنَّ اللّٰہَ  لَذُوۡ فَضۡلٍ عَلَی النَّاسِ وَ لٰکِنَّ اَکۡثَرَ  النَّاسِ لَا یَشۡکُرُوۡنَ ﴿۶۱﴾', 'اللہ ہی تو ہے جس نے تمہارے لئے رات بنائی کہ اس میں آرام کرو اور دن کو روشن بنایا کہ اس میں کام کرو بیشک اللہ لوگوں پر فضل کرنے والا ہے۔ لیکن اکثر لوگ شکر نہیں کرتے۔', 'اللہ ہے جس نے بنایا تمہارے واسطے رات کو کہ اس میں چین پکڑو اور دن بنایا دیکھنے کا [۸۲] اللہ تو فضل والا ہے لوگوں پر اور لیکن بہت لوگ حق نہیں مانتے [۸۳]', 'Allah, it is He Who has made the night for you that you may rest therein and the day for you to see. Truly, Allah is full of Bounty to mankind, yet most of mankind give no thanks.', 'Allah is the One who made for you the night, so that you may have rest in it, and the day to let you see. Surely, Allah is most kind to people, but most of the people do not offer gratitude.'),
(4195, 40, 62, 7, 12, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'ذٰلِکُمُ اللّٰہُ  رَبُّکُمۡ خَالِقُ کُلِّ شَیۡءٍ ۘ لَاۤ  اِلٰہَ   اِلَّا ہُوَ ۫ۚ فَاَنّٰی تُؤۡفَکُوۡنَ ﴿۶۲﴾', 'یہی اللہ تمہارا پروردگار ہے جو ہر چیز کا پیدا کرنے والا ہے اسکے سوا کوئی معبود نہیں پھر تم کہاں سے بھٹکائے جاتے ہو۔', 'اور اللہ ہے تمہارا  رب ہر چیز بنانے  والا کسی کی بندگی نہیں اسکے سوائے  پھر کہاں سے پھرے جاتے ہو [۸۴]', 'That is Allah, your Lord, the Creator of all things, La ilaha illa Huwa (none has the right to be worshipped but He), where then you are turning away (from Allah, by worshipping others instead of Him)!', 'This is Allah, your Lord, the Creator of everything. There is no god but He. Then, from where are you being reversed (by your selfish desires)?'),
(4196, 40, 63, 7, 12, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'کَذٰلِکَ یُؤۡفَکُ الَّذِیۡنَ کَانُوۡا بِاٰیٰتِ اللّٰہِ یَجۡحَدُوۡنَ ﴿۶۳﴾', 'اسی طرح وہ لوگ بھٹکائے جاتے تھے جو اللہ کی آیتوں سے انکار کرتے تھے۔', 'اسی طرح پھرے جاتے ہیں جو لوگ کہ اللہ کی باتوں سے منکر ہوتے رہتے ہیں', 'Thus were turned away those who used to deny the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah.', 'Similarly reversed were those who used to deny Our verses.'),
(4197, 40, 64, 7, 12, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اَللّٰہُ  الَّذِیۡ جَعَلَ  لَکُمُ الۡاَرۡضَ قَرَارًا وَّ السَّمَآءَ بِنَآءً وَّ صَوَّرَکُمۡ فَاَحۡسَنَ صُوَرَکُمۡ وَ رَزَقَکُمۡ مِّنَ الطَّیِّبٰتِ ؕ ذٰلِکُمُ اللّٰہُ  رَبُّکُمۡ ۚۖ فَتَبٰرَکَ اللّٰہُ  رَبُّ الۡعٰلَمِیۡنَ ﴿۶۴﴾', 'اللہ ہی تو ہے جس نے زمین کو تمہارے لئے ٹھہرنے کی جگہ اور آسمان کو چھت بنایا اور تمہاری صورتیں بنائیں اور صورتیں بھی اچھی بنائیں اور تمہیں پاکیزہ چیزیں کھانے کو دیں۔ یہی اللہ تمہارا پروردگار ہے۔ سو اللہ رب العالمین بہت ہی بابرکت ہے۔', 'اللہ ہے جس نے بنایا تمہارے لئے زمین کو ٹھہرنے کی جگہ اور آسمان کو عمارت [۸۵] اور صورت بنائی تمہاری تو اچھی بنائیں صورتیں تمہاری اور روزی دی تمکو ستھری چیزوں سے وہ اللہ ہے رب تمہارا سو بڑی برکت ہے اللہ کی جو رب ہے سارے جہان کا [۸۶]', 'Allah, it is He Who has made for you the earth as a dwelling place and the sky as a canopy, and has given you shape and made your shapes good (looking) and has provided you with good things. That is Allah, your Lord, then blessed be Allah, the Lord of the Alameen (mankind, jinns and all that exists).', 'Allah is the One who made for you the earth a place to live, and the sky a roof, and shaped you, and made your shapes so good - and provided you with a lot of good things. That is Allah, your Lord. So, Glorious is Allah, the Lord of the worlds.'),
(4198, 40, 65, 7, 12, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'ہُوَ الۡحَیُّ  لَاۤ  اِلٰہَ  اِلَّا ہُوَ فَادۡعُوۡہُ مُخۡلِصِیۡنَ لَہُ  الدِّیۡنَ ؕ اَلۡحَمۡدُ لِلّٰہِ رَبِّ الۡعٰلَمِیۡنَ ﴿۶۵﴾', 'وہی زندہ جاوید ہے اسکے سوا کوئی عبادت کے لائق نہیں تو اسکی عبادت کو خالص کر کے اسی کو پکارو۔ ہر طرح کی تعریف اللہ ہی کیلئے ہے جو تمام جہانوں کا پروردگار ہے۔', 'وہ ہے زندہ رہنے والا [۸۷] کسی کی بندگی نہیں اسکے سوائے سو اس کو پکارو خالص کر کر اس کی بندگی سب خوبی اللہ کو جو رب ہے سارے جہان کا [۸۸]', 'He is the Ever Living, La ilaha illa Huwa (none has the right to be worshipped but He), so invoke Him making your worship pure for Him Alone (by worshipping Him Alone, and none else, and by doing righteous deeds sincerely for Allahs sake only, and not to show off, and not to set up rivals with Him in worship). All the praises and thanks be to Allah, the Lord of the Alameen (mankind, jinns and all that exists).', 'He is Ever-living. There is no god but He. So worship Him making your submission exclusive for Him. All praise belongs to Allah, the Lord of all the worlds.'),
(4199, 40, 66, 7, 12, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'قُلۡ  اِنِّیۡ نُہِیۡتُ اَنۡ اَعۡبُدَ الَّذِیۡنَ تَدۡعُوۡنَ مِنۡ دُوۡنِ اللّٰہِ  لَمَّا جَآءَنِیَ الۡبَیِّنٰتُ مِنۡ رَّبِّیۡ ۫ وَ اُمِرۡتُ اَنۡ  اُسۡلِمَ لِرَبِّ الۡعٰلَمِیۡنَ ﴿۶۶﴾', 'اے نبی کہدو کہ مجھے اس بات کی ممانعت کی گئ ہے کہ جنکو تم اللہ کے سوا پکارتے ہو انکی پرستش کروں اور میں انکی پرستش کیسے کروں جبکہ میرے پاس میرے پروردگار کی طرف سے کھلی دلیلیں آ چکی ہیں اور مجھکو حکم یہ ہوا ہے کہ پروردگار عالم ہی کا فرمانبردار رہوں۔', 'تو کہ مجھکو منع کر دیا کہ پوجوں انکو جنکو تم  پکارتے ہو سوائے اللہ کے جب پہنچ چکیں میرے پاس کھلی نشانیاں میرے رب سے اور مجھکو حکم  ہوا کہ تابع  رہوں جہان کے پروردگار کا [۸۹]', 'Say (O Muhammad SAW): \"I have been forbidden to worship those whom you worship besides Allah, since there have come to me evidences from my Lord, and I am commanded to submit (in Islam) to the Lord of the Alameen (mankind, jinns and all that exists).', 'Say, “I have been ordered not to worship those whom you invoke beside Allah when clear signs from my Lord have (already) come to me, and I have been ordered that I should submit to the Lord of the worlds.”'),
(4200, 40, 67, 7, 12, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'ہُوَ الَّذِیۡ خَلَقَکُمۡ مِّنۡ تُرَابٍ ثُمَّ مِنۡ نُّطۡفَۃٍ  ثُمَّ مِنۡ عَلَقَۃٍ  ثُمَّ یُخۡرِجُکُمۡ طِفۡلًا  ثُمَّ  لِتَبۡلُغُوۡۤا  اَشُدَّکُمۡ ثُمَّ لِتَکُوۡنُوۡا شُیُوۡخًا ۚ وَ مِنۡکُمۡ مَّنۡ یُّتَوَفّٰی مِنۡ قَبۡلُ وَ لِتَبۡلُغُوۡۤا  اَجَلًا مُّسَمًّی وَّ  لَعَلَّکُمۡ  تَعۡقِلُوۡنَ ﴿۶۷﴾', 'وہی تو ہے جس نے تمکو پہلے مٹی سے پیدا کیا۔ پھر نطفہ بنا کر پھر لوتھڑا بنا کر پھر تمکو بچہ بنا کر نکالتا ہے پھر تم اپنی جوانی کو پہنچتے ہو۔ پھر بوڑھے ہو جاتے ہو۔ اور کوئی تم میں سے پہلے ہی مر جاتا ہے اور آخر تم موت کے وقت مقرر تک پہنچ جاتے ہو اور تاکہ تم سمجھو۔', 'وہی ہے جس نے بنایا تم کو خاک سے [۹۰] پھر پانی کی بوند سے پھر خون جمے ہوئے سے [۹۱] پھر تم کو نکالتا ہے بچہ پھر جب تک کہ پہنچو اپنے پورے زور کو پھر جب تک کہ ہو جاؤ بوڑھے اور کوئی تم میں ایسا ہے کہ مر جاتا ہے پہلے اس سے اور جب تک کہ پہنچو لکھے وعدے کو [۹۲] اور تاکہ تم سوچو [۹۳]', 'He, it is Who has created you (Adam) from dust, then from a Nutfah (mixed semen drops of male and female discharge (i.e. Adams offspring)) then from a clot (a piece of coagulated blood), then brings you forth as children, then (makes you grow) to reach the age of full strength, and afterwards to be old (men and women), though some among you die before, and that you reach an appointed term, in order that you may understand.', 'He is the One who created you from dust, then from a drop of semen, then from a clot. After that, He takes you out as an infant. Then, (He makes you grow) so that you reach your full maturity, and, thereafter, become old - and some of you die earlier - and so that you reach the appointed term, and so that you understand.'),
(4201, 40, 68, 7, 12, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'ہُوَ الَّذِیۡ یُحۡیٖ وَ یُمِیۡتُ ۚ فَاِذَا قَضٰۤی اَمۡرًا  فَاِنَّمَا یَقُوۡلُ  لَہٗ  کُنۡ  فَیَکُوۡنُ ﴿٪۶۸﴾', 'وہی تو ہے جو زندگی اور موت دیتا ہے۔ پھر جب وہ کوئی کام کرنا یعنی کسی کو پیدا کرنا چاہتا ہے تو اس سے کہدیتا ہے کہ ہو جا تو وہ ہو جاتا ہے۔', 'وہی ہے جو جلاتا ہے اور مارتا ہے پھر جب حکم کرے کسی کام کو تو یہ کہے اسکو کہ ہو جا وہ ہو جاتا ہے [۹۴]', 'He it is Who gives life and causes death. And when He decides upon a thing He says to it only: \"Be!\" and it is.', 'He is the One who gives life and brings death, and when He decides to do something, He only says to it: “Be” and it comes to be.'),
(4202, 40, 69, 8, 13, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اَلَمۡ  تَرَ  اِلَی الَّذِیۡنَ یُجَادِلُوۡنَ فِیۡۤ  اٰیٰتِ اللّٰہِ ؕ اَنّٰی یُصۡرَفُوۡنَ ﴿ۖۛۚ۶۹﴾', 'کیا تم نے ان لوگوں کو نہیں دیکھا جو اللہ کی آیتوں میں جھگڑتے ہیں۔ یہ کہاں سے پھیرے جاتے ہیں۔', 'تو نے نہ دیکھا ان کو جو جھگڑتے ہیں اللہ کی باتوں میں کہاں سے پھیر جاتے ہیں', 'See you not those who dispute about the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of Allah? How are they turning away (from the truth, i.e. Islamic Monotheism to the falsehood of polytheism)?', 'Have you not seen those who quarrel in Allah’s verses? From where are they being turned away (by their selfish desires?)'),
(4203, 40, 70, 8, 13, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'الَّذِیۡنَ کَذَّبُوۡا بِالۡکِتٰبِ وَ بِمَاۤ  اَرۡسَلۡنَا بِہٖ رُسُلَنَا ۟ۛ فَسَوۡفَ یَعۡلَمُوۡنَ ﴿ۙ۷۰﴾', 'جن لوگوں نے ہماری کتاب کو اور جو کچھ ہم نے پیغمبروں کو دے کر بھیجا اسکو جھٹلایا۔ وہ عنقریب معلوم کر لیں گے۔', 'وہ لوگ کہ جنہوں نے جھٹلایا اس کتاب کو اور اس کو کہ بھیجا ہم نے اپنے رسولوں کے ساتھ سو آخر جان لیں گے [۹۵]', 'Those who deny the Book (this Quran), and that with which We sent Our Messengers (i.e. to worship none but Allah Alone sincerely, and to reject all false deities and to confess resurrection after the death for recompense) they will come to know (when they will be cast into the Fire of Hell).', '- those who rejected the Book and what We sent with Our messengers. So, they will soon come to know,'),
(4204, 40, 71, 8, 13, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اِذِ الۡاَغۡلٰلُ فِیۡۤ  اَعۡنَاقِہِمۡ وَ السَّلٰسِلُ ؕ یُسۡحَبُوۡنَ ﴿ۙ۷۱﴾', 'جبکہ انکی گردنوں میں طوق اور زنجیریں ہوں گی وہ گھسیٹے جائیں گے۔', 'جب طوق پڑیں انکی گردنوں میں اور زنجیریں بھی [۹۶] گھسیٹے جائیں', 'When iron collars will be rounded over their necks, and the chains, they shall be dragged along.', 'when shackles will be round their necks, and chains. They will be dragged'),
(4205, 40, 72, 8, 13, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'فِی الۡحَمِیۡمِ ۬ۙ ثُمَّ  فِی النَّارِ  یُسۡجَرُوۡنَ ﴿ۚ۷۲﴾', 'یعنی کھولتے ہوئے پانی میں۔ پھر آگ میں جھونک دیئے جائیں گے۔', 'جلتے  پانی میں پھر آگ میں انکو جھونک دیں [۹۷]', 'In the boiling water, then they will be burned in the Fire.', 'into the hot water after which they will be thrown into the Fire as a fuel.'),
(4206, 40, 73, 8, 13, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'ثُمَّ  قِیۡلَ لَہُمۡ  اَیۡنَ مَا کُنۡتُمۡ تُشۡرِکُوۡنَ ﴿ۙ۷۳﴾', 'پھر ان سے کہا جائے گا کہ وہ کہاں ہیں جنکو تم اللہ کے شریک بناتے تھے۔', 'پھر انکو کہیں کہاں گئے جنکو تم شریک بتلایا کرتے تھے', 'Then it will be said to them: \"Where are (all) those whom you used to join in worship as partners', 'Then, it will be said to them, “Where are those whom you used to associate (in worship)'),
(4207, 40, 74, 8, 13, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'مِنۡ دُوۡنِ اللّٰہِ ؕ قَالُوۡا ضَلُّوۡا عَنَّا بَلۡ لَّمۡ نَکُنۡ نَّدۡعُوۡا مِنۡ قَبۡلُ شَیۡئًا ؕ کَذٰلِکَ  یُضِلُّ  اللّٰہُ  الۡکٰفِرِیۡنَ ﴿۷۴﴾', 'یعنی غیر اللہ۔ کہیں گے وہ تو ہم سے جاتے رہے بلکہ ہم تو پہلے کسی چیز کو پکارتے ہی نہیں تھے۔ اسی طرح اللہ کافروں کو گمراہ رہنے دیتا ہے۔', 'اللہ کے سوائے [۹۸] بولیں وہ ہم سےچوک گئے [۹۹] کوئی نہیں ہم تو پکارتے نہ تھے پہلے کسی چیز کو [۱۰۰] اسی طرح بچلاتا ہے اللہ منکروں کو [۱۰۱]', '\"Besides Allah\" They will say: \"They have vanished from us: Nay, we did not invoke (worship) anything before.\" Thus Allah leads astray the disbelievers.', 'beside Allah?” They will say, “They are lost to us, rather, we used to invoke nothing at all.” This is how Allah makes disbelievers get lost.'),
(4208, 40, 75, 8, 13, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'ذٰلِکُمۡ بِمَا کُنۡتُمۡ تَفۡرَحُوۡنَ فِی الۡاَرۡضِ بِغَیۡرِ الۡحَقِّ وَ بِمَا کُنۡتُمۡ تَمۡرَحُوۡنَ ﴿ۚ۷۵﴾', 'یہ اس کا بدلہ ہے کہ تم زمین میں ناحق خوش ہوا کرتے تھے اور اس وجہ سے کہ اترایا کرتے تھے۔', 'یہ بدلا اس کا جو تم اتراتے پھرتے تھے زمین میں ناحق اور اس کا جو تم اکڑتے تھے [۱۰۲]', 'That was because you had been exulting in the earth without any right (by worshipping others instead of Allah and by committing crimes), and that you used to rejoice extremely (in your error).', '(It will be said to them,) “This is because you used to rejoice on the earth wrongfully, and because you used to show arrogance.'),
(4209, 40, 76, 8, 13, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اُدۡخُلُوۡۤا اَبۡوَابَ جَہَنَّمَ خٰلِدِیۡنَ فِیۡہَا ۚ فَبِئۡسَ مَثۡوَی  الۡمُتَکَبِّرِیۡنَ ﴿۷۶﴾', 'اب جہنم کے دروازوں میں داخل ہو جاؤ۔ ہمیشہ اسی میں رہو گے۔ سو متکبروں کا کیا برا ٹھکانہ ہے۔', 'داخل ہو جاؤ دروازوں میں دوزخ کے [۱۰۳] سدا رہنے کو  اس میں سو کیا برا ٹھکانہ ہے غرور والوں کا', 'Enter the gates of Hell to abide therein, and (indeed) what an evil abode of the arrogant!', 'Enter the gates of Jahannam to live in it forever. So, how evil is the abode of the arrogant.'),
(4210, 40, 77, 8, 13, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'فَاصۡبِرۡ اِنَّ وَعۡدَ اللّٰہِ حَقٌّ ۚ فَاِمَّا نُرِیَنَّکَ بَعۡضَ الَّذِیۡ نَعِدُہُمۡ اَوۡ نَتَوَفَّیَنَّکَ فَاِلَیۡنَا یُرۡجَعُوۡنَ ﴿۷۷﴾', 'تو اے پیغمبر صبر کرو کہ اللہ کا وعدہ سچا ہے۔ پھر اگر ہم تمہیں اس عذاب میں سے کچھ دکھا دیں جس کا ہم ان سے وعدہ کرتے ہیں یا ہم تمہیں وفات دیدیں تو بہرحال انکو تو ہماری ہی طرف لوٹ کر آنا ہے۔', 'سو تو ٹھہرا رہ بیشک وعدہ اللہ کا ٹھیک ہے پھر اگر ہم دکھلا دیں تجھ کو کوئی وعدہ جو ہم ان سے کرتے ہیں یا قبض کر لیں تجھ کو ہر حالت میں ہماری ہی طرف پھر آئیں گے [۱۰۴]', 'So be patient (O Muhammad SAW), verily, the Promise of Allah is true, and whether We show you (O Muhammad SAW in this world) some part of what We have promised them, or We cause you to die, then it is to Us they all shall be returned.', 'Therefore, be patient. Surely, Allah’s promise is true. Then, (O Prophet,) whether We show you (in your life) a part of the promise We are making to them, or make you die (before they are punished), in any case they have to be returned to Us.'),
(4211, 40, 78, 8, 13, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ لَقَدۡ اَرۡسَلۡنَا رُسُلًا مِّنۡ قَبۡلِکَ مِنۡہُمۡ مَّنۡ  قَصَصۡنَا عَلَیۡکَ وَ مِنۡہُمۡ مَّنۡ لَّمۡ نَقۡصُصۡ عَلَیۡکَ ؕ وَ مَا کَانَ لِرَسُوۡلٍ اَنۡ یَّاۡتِیَ بِاٰیَۃٍ  اِلَّا بِاِذۡنِ اللّٰہِ ۚ فَاِذَا جَآءَ  اَمۡرُ  اللّٰہِ  قُضِیَ  بِالۡحَقِّ وَ  خَسِرَ ہُنَالِکَ الۡمُبۡطِلُوۡنَ ﴿٪۷۸﴾', 'اور ہم نے تم سے پہلے بہت سے پیغمبر بھیجے۔ ان میں کچھ تو ایسے ہیں جنکے حالات ہم نے تم سے بیان کر دیئے ہیں اور کچھ ایسے ہیں جنکے حالات بیان نہیں کئے۔ اور کسی پیغمبر کو اختیار نہ تھا کہ اللہ کے حکم کے بغیر کوئی نشانی لائے۔ پھر جب اللہ کا حکم آ پہنچا تو انصاف کے ساتھ فیصلہ کر دیا گیا اور تبھی اہل باطل نقصان میں پڑ گئے۔', 'اور ہم نے بھیجے ہیں رسول تجھ سے پہلے بعضے ان میں وہ ہیں کہ سنایا ہم نے تجھکو  ان کا احوال اور بعضے ہیں کہ نہیں سنایا [۱۰۵] اور کسی رسول کو مقدور نہ تھا کہ لے آتا کوئی نشانی مگر اللہ کے حکم سے [۱۰۶] پھر جب آیا حکم اللہ کا فیصلہ ہو گیا انصاف سے اور ٹوٹے میں پڑے اس جگہ جھوٹے [۱۰۷]', 'And, indeed We have sent Messengers before you (O Muhammad SAW); of some of them We have related to you their story and of some We have not related to you their story, and it was not given to any Messenger that he should bring a sign except by the Leave of Allah. So, when comes the Commandment of Allah, the matter will be decided with truth, and the followers of falsehood will then be lost.', 'We had sent messengers before you. Among them there are those whose history We have narrated to you, and of them there are those whose history We did not narrate to you. And it is not up to a messenger that he could come up with a sign without permission from Allah. So, when the command of Allah will come, matters will stand decided justly, and on that occasion all adherents of falsehood will turn into losers.'),
(4212, 40, 79, 9, 14, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اَللّٰہُ  الَّذِیۡ جَعَلَ  لَکُمُ الۡاَنۡعَامَ لِتَرۡکَبُوۡا مِنۡہَا وَ  مِنۡہَا تَاۡکُلُوۡنَ ﴿۫۷۹﴾', 'اللہ ہی تو ہے جس نے تمہارے لئے چوپائے بنائے تاکہ ان میں سے بعض پر تم سوار ہو اور بعض کو تم کھاتے ہو۔', 'اللہ ہے جس نے بنا دیے تمہارے واسطے چوپائے تاکہ سواری کرو بعضوں پر اور بعضوں کو کھاتے ہو', 'Allah, it is He Who has made cattle for you, that you may ride on some of them and of some you eat.', 'Allah is the One who made for you the cattle, so that you may ride some of them,- and of them you eat;'),
(4213, 40, 80, 9, 14, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ لَکُمۡ فِیۡہَا مَنَافِعُ وَ لِتَبۡلُغُوۡا عَلَیۡہَا حَاجَۃً  فِیۡ صُدُوۡرِکُمۡ  وَ عَلَیۡہَا وَ عَلَی الۡفُلۡکِ  تُحۡمَلُوۡنَ ﴿ؕ۸۰﴾', 'اور تمہارے لئے ان میں اور بھی فائدے ہیں اور اس لئے بھی کہ اگر کہیں جانے کی تمہارے دلوں میں خواہش ہو تو ان پر چڑھ کر وہاں پہنچ جاؤ۔ اور ان پر اور کشتیوں پر تم سوار ہوتے ہو۔', 'اور ان میں تمکو بہت فائدے ہیں [۱۰۸] اور تاکہ پہنچو ان پر چڑھ کر کسی کام تک جو تمہارے جی میں ہو [۱۰۹] اور ان پر اور کشتیوں پر لدے پھرتے ہو [۱۱۰]', 'And you have (many other) benefits from them, and that you may reach by their means a desire that is in your breasts (i.e. carry your goods, loads, etc.), and on them and on ships you are carried.', 'and for you there are (other) benefits in them- and so that, (by riding) on them, you meet any need you have in your hearts; and on them and on boats you are carried.'),
(4214, 40, 81, 9, 14, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'وَ یُرِیۡکُمۡ اٰیٰتِہٖ ٭ۖ فَاَیَّ اٰیٰتِ اللّٰہِ تُنۡکِرُوۡنَ ﴿۸۱﴾', 'اور وہ تمہیں اپنی نشانیاں دکھاتا رہتا ہے تو تم اللہ کی کن کن نشانیوں کو نہ مانو گے۔', 'اور دکھلاتا ہے تم کو اپنی نشانیاں پھر کون کون سی نشانیوں کو اپنے رب کی نہ مانو گے [۱۱۱]', 'And He shows you His Signs and Proofs (of His Oneness in all the above mentioned things). Which, then of the Signs and Proofs of Allah do you deny?', 'He shows you His signs. Then, which of the signs of Allah would you (still) deny?'),
(4215, 40, 82, 9, 14, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'اَفَلَمۡ یَسِیۡرُوۡا فِی الۡاَرۡضِ فَیَنۡظُرُوۡا کَیۡفَ کَانَ عَاقِبَۃُ  الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ ؕ کَانُوۡۤا  اَکۡثَرَ  مِنۡہُمۡ وَ اَشَدَّ قُوَّۃً وَّ اٰثَارًا فِی الۡاَرۡضِ فَمَاۤ  اَغۡنٰی عَنۡہُمۡ مَّا کَانُوۡا یَکۡسِبُوۡنَ ﴿۸۲﴾', 'کیا ان لوگوں نے زمین میں سیر نہیں کی تاکہ دیکھتے کہ جو لوگ ان سے پہلے تھے ان کا انجام کیسا ہوا۔ حالانکہ وہ ان سے کہیں زیادہ اور طاقتور اور زمین میں نشانات بنانے کے اعتبار سے بہت بڑھ کر تھے۔ تو جو کچھ وہ کرتے تھے وہ انکے کچھ کام نہ آیا۔', 'کیا پھرے نہیں وہ ملک میں کہ دیکھ لیتے کیسا انجام ہوا ان سے پہلوں کا وہ تھے ان سے زیادہ اور زور میں سخت اور نشانیوں میں جو چھوڑ گئے ہیں زمین پر پھر کام نہ آیا اُن کے جو وہ کماتے تھے [۱۱۲]', 'Have they not travelled through the earth and seen what was the end of those before them? They were more numerous than them and mightier in strength, and in the traces (they have left behind them) in the land, yet all that they used to earn availed them not.', 'Have they not traveled through the earth and seen how was the fate of those before them? Most of them were more in numbers than these, and superior in vigor and vestiges left on the earth. So then, whatever they used to earn did not work for them at all.'),
(4216, 40, 83, 9, 14, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'فَلَمَّا جَآءَتۡہُمۡ  رُسُلُہُمۡ  بِالۡبَیِّنٰتِ فَرِحُوۡا بِمَا عِنۡدَہُمۡ مِّنَ الۡعِلۡمِ  وَ  حَاقَ بِہِمۡ مَّا کَانُوۡا بِہٖ یَسۡتَہۡزِءُوۡنَ ﴿۸۳﴾', 'اور جب انکے پیغمبر انکے پاس کھلی نشانیاں لے کر آئے تو جو علم اپنے خیال میں انکے پاس تھا اس پر اترانے لگے اور جس چیز سے تمسخر کیا کرتے تھے اس نے انکو آ گھیرا۔', 'پھر جب پہنچے انکے پاس رسول انکے کھلی نشانیاں لے کر اترانے لگے اس پر جو انکے پاس تھی خبر اور الٹ پڑی ان پر وہ چیز جس پر ٹھٹھا کرتے تھے [۱۱۳]', 'Then when their Messengers came to them with clear proofs, they were glad (and proud) with that which they had of the knowledge (of worldly things): And that at which they used to mock, surrounded them (i.e. the punishment).', 'When their messengers came to them with manifest signs, they exulted because of whatever knowledge they had, and they were encircled by what they used to ridicule.'),
(4217, 40, 84, 9, 14, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'فَلَمَّا رَاَوۡا  بَاۡسَنَا  قَالُوۡۤا  اٰمَنَّا بِاللّٰہِ وَحۡدَہٗ  وَ کَفَرۡنَا بِمَا کُنَّا بِہٖ مُشۡرِکِیۡنَ ﴿۸۴﴾', 'پھر جب انہوں نے ہمارا عذاب دیکھ لیا تو کہنے لگے کہ ہم ایک اللہ پر ایمان لائے اور جس چیز کو ہم اسکا شریک بناتے تھے اس سے منکر ہو گئے۔', 'پھر جب انہوں نے دیکھ لیا ہماری آفت کو بولے ہم یقین لائے اللہ اکیلے پر اور ہم نے چھوڑ دیں وہ چیزیں جنکو شریک بتلاتے تھے [۱۱۴]', 'So when they saw Our punishment, they said: \"We believe in Allah Alone and reject (all) that we used to associate with Him as (His) partners.', 'When they saw Our punishment, they said, “We have (now) come to believe in Allah alone, and We have rejected everything we used to ascribe (to Him) as partners.”'),
(4218, 40, 85, 9, 14, 24, 'فَمَنۡ اَظۡلَمُ', 'المومن', 'فَلَمۡ یَکُ یَنۡفَعُہُمۡ  اِیۡمَانُہُمۡ  لَمَّا رَاَوۡا بَاۡسَنَا ؕ سُنَّتَ اللّٰہِ الَّتِیۡ قَدۡ خَلَتۡ فِیۡ عِبَادِہٖ ۚ وَ خَسِرَ ہُنَالِکَ  الۡکٰفِرُوۡنَ ﴿٪۸۵﴾', 'پھر جب وہ ہمارا عذاب دیکھ چکے اس وقت انکے ایمان نے انکو کچھ بھی فائدہ نہ دیا۔ یہ اللہ کی عادت ہے جو اسکے بندوں کے بارے میں چلی آتی ہے۔ اور وہاں کافر گھاٹے میں رہ گئے۔', 'پھر نہ ہوا کہ کام آئے انکو  یقین لانا ان کا جس وقت دیکھ چکے ہمارا عذاب [۱۱۵] رسم پڑی ہوئی اللہ کی جو چلی آئی اس کے بندوں میں اور خراب ہوئے اس جگہ منکر [۱۱۶]', 'Then their Faith (in Islamic Monotheism) could not avail them when they saw Our punishment. (Like) this has been the way of Allah in dealing with His slaves. And there the disbelievers lost utterly (when Our Torment covered them).', 'But, their profession of faith was not (competent) to benefit them, once they had seen Our punishment - a customary practice of Allah that has been there all along in the matter of His servants - and hence, the disbelievers became the losers.'),
(4219, 41, 1, 1, 15, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'حٰمٓ ۚ﴿۱﴾', 'حٰم۔', 'حٰم۔', 'HaMeem. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings.)', 'Hā Mīm'),
(4220, 41, 2, 1, 15, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'تَنۡزِیۡلٌ  مِّنَ  الرَّحۡمٰنِ  الرَّحِیۡمِ ۚ﴿۲﴾', 'یہ کتاب رحمٰن و رحیم کی طرف سے اتری ہے۔', 'اتارا ہوا ہے بڑے مہربان رحم  والے کی طرف سے [۱]', 'A revelation from Allah, the Most Beneficent, the Most Merciful.', 'This is a revelation from the All-Merciful, the Very-Merciful-'),
(4221, 41, 3, 1, 15, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'کِتٰبٌ فُصِّلَتۡ اٰیٰتُہٗ  قُرۡاٰنًا عَرَبِیًّا لِّقَوۡمٍ  یَّعۡلَمُوۡنَ ۙ﴿۳﴾', 'ایسی کتاب جسکی آیتیں جدا جدا بیان کی گئ ہیں یعنی قرآن عربی ان لوگوں کے لئے جو سمجھ رکھتے ہیں۔', 'ایک کتاب ہے جدی جدی کی ہیں اس کی آیتیں [۲] قرآن عربی زبان کا ایک سمجھ والے لوگوں کو [۳]', 'A Book whereof the Verses are explained in detail; A Quran in Arabic for people who know.', '- a book whose verses are elaborated in the form of an Arabic Qur’ān for a people who understand,'),
(4222, 41, 4, 1, 15, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'بَشِیۡرًا وَّ نَذِیۡرًا ۚ فَاَعۡرَضَ  اَکۡثَرُہُمۡ فَہُمۡ  لَا یَسۡمَعُوۡنَ ﴿۴﴾', 'جو بشارت بھی سناتا ہے اور خوف بھی دلاتا ہے لیکن ان میں سے اکثر نے منہ پھیر لیا اور وہ سنتے ہی نہیں۔', 'سنانے والا خوشخبری اور ڈر [۴] پر دھیان میں نہ لائے وہ بہت لوگ سو وہ نہیں سنتے [۵]', 'Giving glad tidings (of Paradise to the one who believes in the Oneness of Allah (i.e. Islamic Monotheism) and fears Allah much (abstains from all kinds of sins and evil deeds) and loves Allah much (performing all kinds of good deeds which He has ordained)), and warning (of punishment in the Hell Fire to the one who disbelieves in the Oneness of Allah), but most of them turn away, so they listen not.', 'as a bearer of good news and warning. Yet most of them turned away, so they do not listen.'),
(4223, 41, 5, 1, 15, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ قَالُوۡا قُلُوۡبُنَا فِیۡۤ  اَکِنَّۃٍ  مِّمَّا تَدۡعُوۡنَاۤ  اِلَیۡہِ  وَ فِیۡۤ  اٰذَانِنَا وَقۡرٌ  وَّ مِنۡۢ  بَیۡنِنَا وَ بَیۡنِکَ حِجَابٌ  فَاعۡمَلۡ  اِنَّنَا عٰمِلُوۡنَ ؓ﴿۵﴾', 'اور کہنے لگے کہ جس چیز کی طرف تم ہمیں بلاتے ہو اس کی طرف سے ہمارے دل پردوں میں ہیں اور ہمارے کانوں میں بوجھ یعنی بہرا پن ہے اور ہمارے اور تمہارے درمیان ایک پردہ ہے تو تم اپنا کام کرو ہم اپنا کام کرتے ہیں۔', 'اور کہتے ہیں ہمارے دل غلاف میں ہیں اس بات سے جسکی طرف تو ہم کو بلاتا ہے اور ہمارے کانوں میں بوجھ ہے اور  ہمارے اور تیرے بیچ میں پردہ ہے سو تو اپنا کام کر ہم اپنا کام کرتے ہیں [۶]', 'And they say: \"Our hearts are under coverings (screened) from that to which you invite us, and in our ears is deafness, and between us and you is a screen, so work you (on your way); verily, we are working (on our way).\"', 'And they say, “Our hearts are (wrapped) in covers against that (faith) to which you invite us, and there is deafness in our ears, and there is a barrier between you and us. So, do (in your way). We too are doing (in our own way)”.'),
(4224, 41, 6, 1, 15, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'قُلۡ  اِنَّمَاۤ  اَنَا بَشَرٌ  مِّثۡلُکُمۡ  یُوۡحٰۤی  اِلَیَّ اَنَّمَاۤ  اِلٰـہُکُمۡ  اِلٰہٌ  وَّاحِدٌ فَاسۡتَقِیۡمُوۡۤا اِلَیۡہِ وَ اسۡتَغۡفِرُوۡہُ ؕ وَ وَیۡلٌ  لِّلۡمُشۡرِکِیۡنَ ۙ﴿۶﴾', 'کہدو کہ میں بھی آدمی ہوں جیسے تم ہاں مجھ پر یہ وحی آتی ہے کہ تمہارا معبود ایک ہی معبود ہے تو سیدھے اسی کی طرف متوجہ رہو اور اسی سے مغفرت مانگو اور مشرکوں پر افسوس ہے۔', 'تو کہہ میں بھی آدمی ہوں جیسے تم حکم آتا ہے مجھکو کہ تم پر بندگی ایک حاکم کی ہے سو سیدھے رہو  اسکی طرف اور اس سے گناہ بخشواؤ [۷] اور خرابی ہے شریک کرنے والوں کو', 'Say (O Muhammad SAW): \"I am only a human being like you. It is inspired in me that your Ilah (God) is One Ilah (God - Allah), therefore take Straight Path to Him (with true Faith Islamic Monotheism) and obedience to Him, and seek forgiveness of Him. And woe to Al-Mushrikoon (the disbelievers in the Oneness of Allah, polytheists, idolaters, etc. - see V.2:105).', 'Say, “I am but a human being like you; it is revealed to me that your god is only One God. So, turn straight towards Him, and seek forgiveness from Him, and woe to the Mushriks (those who ascribe partners to Allah)'),
(4225, 41, 7, 1, 15, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'الَّذِیۡنَ  لَا یُؤۡتُوۡنَ الزَّکٰوۃَ وَ ہُمۡ بِالۡاٰخِرَۃِ  ہُمۡ کٰفِرُوۡنَ ﴿۷﴾', 'جو زکوٰۃ نہیں دیتے اور وہ آخرت کے بھی منکر ہیں۔', 'جو نہیں دیتے زکوٰۃ اور وہ آخرت سے منکر ہیں [۸]', 'Those who give not the Zakat and they are disbelievers in the Hereafter.', 'who do not pay Zakāh ; and of the life of the Hereafter, they are deniers.”'),
(4226, 41, 8, 1, 15, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'اِنَّ  الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ لَہُمۡ  اَجۡرٌ  غَیۡرُ  مَمۡنُوۡنٍ ٪﴿۸﴾', 'جو لوگ ایمان لائے اور عمل نیک کرتے رہے انکے لئے ایسا ثواب ہے جو ختم ہی نہ ہو۔', 'البتہ جو لوگ یقین لائے اور کئے بھلے کام ان کو ثواب ملنا ہے جو موقوف نہ ہو [۹]', 'Truly, those who believe (in the Oneness of Allah Islamic Monotheism, and in His Messenger Muhammad SAW) and do righteous good deeds, for them will be an endless reward that will never stop (i.e. Paradise).', 'As for those who believe and do righteous deeds, for them there is a reward that will never be interrupted.'),
(4227, 41, 9, 2, 16, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'قُلۡ  اَئِنَّکُمۡ  لَتَکۡفُرُوۡنَ بِالَّذِیۡ خَلَقَ الۡاَرۡضَ فِیۡ یَوۡمَیۡنِ وَ تَجۡعَلُوۡنَ لَہٗۤ  اَنۡدَادًا ؕ  ذٰلِکَ رَبُّ  الۡعٰلَمِیۡنَ ۚ﴿۹﴾', 'کہو کیا تم اس ذات کا انکار کرتے ہو جس نے زمین کو دو دن میں پیدا کیا۔ اور بتوں کو اس کا مدمقابل بناتے ہو۔ وہی تو تمام جہانوں کا مالک ہے۔', 'تو کہہ کیا تم منکر ہو اس سے جس نے بنائی زمین دو دن میں اور برابر کرتے ہو اسکے ساتھ اوروں کو وہ ہے رب جہان کا [۱۰]', 'Say (O Muhammad SAW): \"Do you verily disbelieve in Him Who created the earth in two Days and you set up rivals (in worship) with Him? That is the Lord of the Alameen (mankind, jinns and all that exists).', 'Say, “Do you really disbelieve in the One who has created the earth in two days, and ascribe to Him partners? That is the Lord of the worlds.'),
(4228, 41, 10, 2, 16, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ جَعَلَ  فِیۡہَا رَوَاسِیَ مِنۡ فَوۡقِہَا وَ بٰرَکَ فِیۡہَا وَ قَدَّرَ فِیۡہَاۤ  اَقۡوَاتَہَا فِیۡۤ  اَرۡبَعَۃِ  اَیَّامٍ ؕ سَوَآءً   لِّلسَّآئِلِیۡنَ ﴿۱۰﴾', 'اور اسی نے زمین میں اس کے اوپر پہاڑ بنائے اور زمین میں برکت رکھی اور اس میں سامان معیشت مقرر کیا سب چار دن میں۔ اور تمام طلبگاروں کے لئے یکساں۔', 'اور رکھے اس میں بھاری پہاڑ اوپر سے اور برکت رکھی اسکے اندر اور ٹھہرائیں اُسمیں خوراکیں اُسکی [۱۱] چار دن میں پورا ہوا پوچھنے والوں کو [۱۲]', 'He placed therein (i.e. the earth) firm mountains from above it, and He blessed it, and measured therein its sustenance (for its dwellers) in four Days equal (i.e. all these four days were equal in the length of time), for all those who ask (about its creation).', 'He has placed firm mountains in it (the earth) towering above it, and put blessings in it, and proportioned its foods therein, in four days, equal for those who ask.'),
(4229, 41, 11, 2, 16, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'ثُمَّ  اسۡتَوٰۤی  اِلَی السَّمَآءِ وَ ہِیَ دُخَانٌ فَقَالَ  لَہَا وَ لِلۡاَرۡضِ ائۡتِیَا طَوۡعًا  اَوۡ کَرۡہًا ؕ قَالَتَاۤ   اَتَیۡنَا  طَآئِعِیۡنَ ﴿۱۱﴾', 'پھر وہ آسمان کی طرف متوجہ ہوا جبکہ وہ دھواں تھا تو اس نے اس سے اور زمین سے فرمایا کہ دونوں آؤ خواہ خوشی سے خواہ ناخوشی سے۔ انہوں نے کہا کہ ہم خوشی سے آتے ہیں۔', 'پھر چڑھا آسمان کو اور وہ دھواں ہو رہا تھا [۱۳] پھر کہا اسکو اور زمین کو آؤ تم دونوں خوشی سے یا زور سے وہ بولے ہم آئے خوشی سے [۱۴]', 'Then He Istawa (rose over) towards the heaven when it was smoke, and said to it and to the earth: \"Come both of you willingly or unwillingly.\" They both said: \"We come, willingly.\"', 'Then He turned straight to the sky, while it was a smoke, and said to it and to the earth, “Come (to My obedience), both of you, willingly or unwillingly.” Both said, “We come willingly.”'),
(4230, 41, 12, 2, 16, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'فَقَضٰہُنَّ سَبۡعَ سَمٰوَاتٍ فِیۡ یَوۡمَیۡنِ وَ اَوۡحٰی فِیۡ کُلِّ سَمَآءٍ  اَمۡرَہَا ؕ وَ زَیَّنَّا السَّمَآءَ  الدُّنۡیَا بِمَصَابِیۡحَ ٭ۖ وَ حِفۡظًا ؕ ذٰلِکَ تَقۡدِیۡرُ  الۡعَزِیۡزِ  الۡعَلِیۡمِ ﴿۱۲﴾', 'پھر اس نے دو دن میں سات آسمان بنائے اور ہر آسمان میں اسکے کام کا حکم بھیجا اور ہم نے آسمان دنیا کو چراغوں یعنی ستاروں سے سجایا اور شیطانوں سے محفوظ رکھا۔ یہ اسی زبردست باخبر کے مقرر کئے ہوئے اندازے ہیں۔', 'پھر کر دیے وہ سات آسمان دو دن میں [۱۵] اور اتارا ہر آسمان میں حکم اُس کا [۱۶] اور رونق دی ہم نے سب سے ورلے آسمان کو چراغوں سے اور محفوظ کر دیا یہ سادھا ہوا ہے زبردست خبردار کا [۱۷]', 'Then He completed and finished from their creation (as) seven heavens in two Days and He made in each heaven its affair. And We adorned the nearest (lowest) heaven with lamps (stars) to be an adornment as well as to guard (from the devils by using them as missiles against the devils). Such is the Decree of Him the All-Mighty, the All-Knower.', 'So He accomplished them as seven skies in two days, and settled in every sky its (due) thing. And We have decorated the closest sky with lamps, and protected it properly. All this is the determination of the All-Mighty, the All-Knowing.'),
(4231, 41, 13, 2, 16, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'فَاِنۡ  اَعۡرَضُوۡا فَقُلۡ  اَنۡذَرۡتُکُمۡ  صٰعِقَۃً  مِّثۡلَ  صٰعِقَۃِ عَادٍ  وَّ  ثَمُوۡدَ ﴿ؕ۱۳﴾', 'پھر اگر یہ منہ پھیر لیں تو کہدو کہ میں تمکو ایسی چنگھاڑ کے عذاب سے آگاہ کرتا ہوں جیسے عاد اور ثمود پر چنگھاڑ کا عذاب آیا تھا۔', 'پھر اگر وہ ٹلائیں تو تو کہہ میں نے خبر سنادی تمکو  ایک سخت عذاب کی جیسے عذاب آیا عاد اور ثمود پر [۱۸]', 'But if they turn away, then say (O Muhammad SAW): \"I have warned you of a Saiqah (a destructive awful cry, torment, hit, a thunderbolt) like the Saiqah which overtook Ad and Thamood (people).\"', 'So, if they turn away, then say, “I have warned you of a calamity like the calamity of ‘Ād and Thamūd,'),
(4232, 41, 14, 2, 16, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'اِذۡ جَآءَتۡہُمُ  الرُّسُلُ مِنۡۢ بَیۡنِ اَیۡدِیۡہِمۡ وَ مِنۡ خَلۡفِہِمۡ  اَلَّا تَعۡبُدُوۡۤا  اِلَّا اللّٰہَ ؕ قَالُوۡا لَوۡ شَآءَ  رَبُّنَا لَاَنۡزَلَ مَلٰٓئِکَۃً  فَاِنَّا بِمَاۤ  اُرۡسِلۡتُمۡ  بِہٖ کٰفِرُوۡنَ ﴿۱۴﴾', 'جب انکے پاس پیغمبر انکے آگے اور پیچھے سے آئے کہ اللہ کے سوا کسی کی عبادت نہ کرو۔ تو وہ کہنے لگے کہ اگر ہمارا پروردگار چاہتا تو فرشتے اتار دیتا سو جو تم دے کر بھیجے گئے ہو ہم اسکو نہیں مانتے۔', 'جب آئے انکے پاس رسول آگے سے اور پیچھے سے [۱۹] کہ نہ پوجو کسی کو سوائے اللہ کے کہنے لگے اگر ہمارا رب چاہتا تو بھیجتا فرشتے سو ہم تمہارا لایا ہوا نہیں مانتے [۲۰]', 'When the Messengers came to them, from before them and behind them (saying): \"Worship none but Allah\" They said: \"If our Lord had so willed, He would surely have sent down the angels. So indeed! We disbelieve in that with which you have been sent.\"', 'when the messengers came to them from their front and from their rear, saying, “Do not worship anyone but Allah.” They said, “Had our Lord (really) willed (to send someone as messenger), He would have sent down angels. So, we are deniers of what you have been sent with.”'),
(4233, 41, 15, 2, 16, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'فَاَمَّا عَادٌ  فَاسۡتَکۡبَرُوۡا فِی الۡاَرۡضِ بِغَیۡرِ الۡحَقِّ وَ قَالُوۡا مَنۡ  اَشَدُّ مِنَّا قُوَّۃً ؕ اَوَ لَمۡ  یَرَوۡا  اَنَّ اللّٰہَ  الَّذِیۡ خَلَقَہُمۡ ہُوَ اَشَدُّ مِنۡہُمۡ  قُوَّۃً ؕ وَ کَانُوۡا بِاٰیٰتِنَا یَجۡحَدُوۡنَ ﴿۱۵﴾', 'اب جو عاد تھے وہ ناحق ملک میں تکبر کرنے لگے اور کہنے لگے کہ ہم سے بڑھ کر قوت میں کون ہے؟ کیا انہوں نے نہیں دیکھا کہ اللہ جس نے انکو پیدا کیا وہ ان سے قوت میں بہت بڑھ کر ہے۔ اور وہ ہماری آیتوں سے انکار کرتے رہے۔', 'سو  وہ جو عاد تھے وہ تو غرور کرنے لگے ملک میں ناحق اور کہنے لگے کون ہے ہم سے زیادہ زور میں [۲۱] کیا دیکھتے نہیں کہ اللہ جس نے انکو بنایا وہ زیادہ ہے ان سے زور میں اور تھے ہماری نشانیوں سے منکر [۲۲]', 'As for Ad, they were arrogant in the land without right, and they said: \"Who is mightier than us in strength?\" See they not that Allah, Who created them was mightier in strength than them. And they used to deny Our Ayat (proofs, evidences, verses, lessons, revelations, etc.)!', 'As for ‘Ād, they showed arrogance in the land with no right (to do so), and said, “Who is stronger than us in power?” Did they not see that Allah, who created them, is stronger than them in power? And they used to reject Our signs.'),
(4234, 41, 16, 2, 16, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'فَاَرۡسَلۡنَا عَلَیۡہِمۡ  رِیۡحًا صَرۡصَرًا فِیۡۤ اَیَّامٍ نَّحِسَاتٍ لِّنُذِیۡقَہُمۡ عَذَابَ الۡخِزۡیِ فِی الۡحَیٰوۃِ  الدُّنۡیَا ؕ وَ لَعَذَابُ الۡاٰخِرَۃِ   اَخۡزٰی  وَ ہُمۡ  لَا  یُنۡصَرُوۡنَ ﴿۱۶﴾', 'تو ہم نے بھی ان پر نحوست کے دنوں میں زور کی آندھی چلائی تاکہ انکو دنیا کی زندگی میں ذلت کے عذاب کا مزہ چکھا دیں۔ اور آخرت کا عذاب تو بہت ہی ذلیل کرنے والا ہے اور اس روز انکو مدد بھی نہ ملے گی۔', 'پھر بھیجی ہم نے ان پر ہوا بڑے زور کی کئ دن جو مصیبت کے تھے تاکہ چکھائیں انکو رسوائی کا عذاب دنیا کی زندگانی میں [۲۳] اور آخرت کے عذاب میں تو  پوری رسوائی ہے اور انکو کہیں مدد نہیں [۲۴]', 'So We sent upon them furious wind in days of evil omen (for them) that We might give them a taste of disgracing torment in this present worldly life, but surely the torment of the Hereafter will be more disgracing, and they will never be helped.', 'So, We let loose a wild wind on them in unlucky days to make them taste the humiliating punishment in the present life. And of course, the punishment of the Hereafter will be much more humiliating, and they will not be helped.'),
(4235, 41, 17, 2, 16, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ اَمَّا ثَمُوۡدُ فَہَدَیۡنٰہُمۡ  فَاسۡتَحَبُّوا الۡعَمٰی عَلَی الۡہُدٰی فَاَخَذَتۡہُمۡ صٰعِقَۃُ الۡعَذَابِ الۡہُوۡنِ بِمَا کَانُوۡا یَکۡسِبُوۡنَ ﴿ۚ۱۷﴾', 'اور جو ثمود والے تھے انکو ہم نے سیدھا رستہ دکھا دیا تھا مگر انہوں نے ہدایت کے مقابلے میں اندھا رہنا پسند کیا۔ تو انکے اعمال کی سزا میں ذلت کے عذاب کی کڑک نے انکو آ پکڑا۔', 'اور وہ جو ثمود تھے سو ہم نے انکو راہ بتلائی پھر انکو خوش لگا اندھا رہنا راہ سوجھنے سے [۲۵] پھر پکڑ  انکو کڑک نے ذلت کے عذاب کی بدلا اس کا جو کماتے تھے [۲۶]', 'And as for Thamood, We showed and made clear to them the Path of Truth (Islamic Monotheism) through Our Messenger, (i.e. showed them the way of success), but they preferred blindness to guidance, so the Saiqah (a destructive awful cry, torment, hit, a thunderbolt) of disgracing torment seized them, because of what they used to earn.', 'As for Thamūd, We showed them the way, but they preferred blindness to the guidance. Therefore, they were seized by the bang of the abasing punishment because of what they used to earn.'),
(4236, 41, 18, 2, 16, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ نَجَّیۡنَا الَّذِیۡنَ اٰمَنُوۡا وَ کَانُوۡا یَتَّقُوۡنَ ﴿٪۱۸﴾', 'اور جو ایمان لائے اور  پرہیزگار رہے انکو ہم نے بچا لیا۔', 'اور بچا دیا ہم نے ان لوگوں کو جو یقین لائے تھے اور بچ کر چلتے تھے [۲۷]', 'And We saved those who believed and used to fear Allah, keep their duty to Him and avoid evil.', 'And We saved those who believed and used to be God-fearing.'),
(4237, 41, 19, 3, 17, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ یَوۡمَ یُحۡشَرُ اَعۡدَآءُ  اللّٰہِ  اِلَی النَّارِ فَہُمۡ  یُوۡزَعُوۡنَ ﴿۱۹﴾', 'اور جس دن اللہ کے دشمن دوزخ کی طرف اکٹھے کئے جائیں گے پھر انکی الگ الگ جماعتیں بنائی جائیں گے۔', 'اور جس دن جمع ہوں گے دشمن اللہ کے دوزخ  پر تو انکی جماعتیں بنائی جائیں گی [۲۸]', 'And (remember) the Day that the enemies of Allah will be gathered to the Fire, so they will be collected there (the first and the last).', '(Remind them of) the day when Allah’s enemies will be mustered towards the Fire. So they will be kept under control,'),
(4238, 41, 20, 3, 17, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'حَتّٰۤی  اِذَا مَا جَآءُوۡہَا شَہِدَ عَلَیۡہِمۡ سَمۡعُہُمۡ وَ اَبۡصَارُہُمۡ وَ جُلُوۡدُہُمۡ بِمَا کَانُوۡا یَعۡمَلُوۡنَ ﴿۲۰﴾', 'یہاں تک کہ جب دوزخ کے پاس پہنچ جائیں گے تو انکے کان اور آنکھیں اور کھالیں یعنی دوسرے اعضا انکے خلاف انکے اعمال کی شہادت دیں گے۔', 'یہاں تک کہ جب پہنچیں اس پر بتائیں گے انکو انکے کان اور انکی آنکھیں اور انکے چمڑے جو کچھ وہ کرتے تھے [۲۹]', 'Till, when they reach it (Hell-fire), their hearing (ears) and their eyes, and their skins will testify against them as to what they used to do.', 'until when they will come to it, their ears and their eyes and their skins will testify against them about what they used to do.'),
(4239, 41, 21, 3, 17, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ قَالُوۡا لِجُلُوۡدِہِمۡ  لِمَ شَہِدۡتُّمۡ  عَلَیۡنَا ؕ قَالُوۡۤا اَنۡطَقَنَا اللّٰہُ  الَّذِیۡۤ  اَنۡطَقَ کُلَّ شَیۡءٍ وَّ ہُوَ خَلَقَکُمۡ  اَوَّلَ مَرَّۃٍ  وَّ اِلَیۡہِ تُرۡجَعُوۡنَ ﴿۲۱﴾', 'اور وہ اپنے کھالوں یعنی اعضاء سے کہیں گے کہ تم نے ہمارے خلاف کیوں شہادت دی؟ وہ کہیں گے کہ جس اللہ نے سب چیزوں کو نطق بخشا اسی نے ہمکو بھی گویائی دی۔ اور اسی نے تمکو پہلی بار پیدا کیا تھا اور اسی کی طرف تم لوٹائے جا رہے ہو۔', 'اور وہ کہیں گے اپنے چمڑوں کو تم نے کیوں بتلایا ہمکو [۳۰] وہ بولیں گے ہمکو  بلوایا اللہ نے جس نے بلوایا ہے ہر چیز کو [۳۱] اور اسی نے بنایا تمکو  پہلی بار اور اسی کی طرف پھیرے جاتے ہو [۳۲]', 'And they will say to their skins, \"Why do you testify against us?\" They will say: \"Allah has caused us to speak, as He causes all things to speak, and He created you the first time, and to Him you are made to return.\"', 'And they will say to their skins, “Why did you testify against us?” They (the skins) will say, “We were made to speak by Allah, the One who has made every thing to speak.” And He had created you the first time, and to Him you are going to be returned.'),
(4240, 41, 22, 3, 17, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ مَا کُنۡتُمۡ تَسۡتَتِرُوۡنَ اَنۡ یَّشۡہَدَ عَلَیۡکُمۡ سَمۡعُکُمۡ وَ لَاۤ  اَبۡصَارُکُمۡ وَ لَا جُلُوۡدُکُمۡ وَ لٰکِنۡ ظَنَنۡتُمۡ  اَنَّ اللّٰہَ  لَا یَعۡلَمُ  کَثِیۡرًا  مِّمَّا تَعۡمَلُوۡنَ ﴿۲۲﴾', 'اور تم اس بات کے خوف سے تو پردہ نہیں کرتے تھے کہ تمہارے کان اور تمہاری آنکھیں اور کھالیں تمہارے خلاف شہادت دیں گی بلکہ تم یہ خیال کرتے تھے کہ اللہ کو تمہارے بہت سے اعمال کی خبر ہی نہیں۔', 'اور تم پردہ نہ کرتے تھے اس بات سے کہ تم کو بتلائیں گے تمہارے کان اور نہ تمہاری آنکھیں اور نہ تمہارے چمڑے [۳۳] پر تم کو یہ خیال تھا کہ اللہ نہیں جانتا بہت چیزیں جو تم کرتے ہو [۳۴]', 'And you have not been hiding against yourselves, lest your ears, and your eyes, and your skins testify against you, but you thought that Allah knew not much of what you were doing.', 'And you had not been hiding your selves (when committing sins) from your ears and your eyes and your skins that would bear witness against you, but you thought that Allah did not know much of what you did.'),
(4241, 41, 23, 3, 17, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ ذٰلِکُمۡ ظَنُّکُمُ الَّذِیۡ ظَنَنۡتُمۡ بِرَبِّکُمۡ اَرۡدٰىکُمۡ فَاَصۡبَحۡتُمۡ مِّنَ الۡخٰسِرِیۡنَ ﴿۲۳﴾', 'اور اسی خیال نے جو تم اپنے پروردگار کے بارے میں رکھتے تھے تمکو ہلاک کر دیا اور تم خسارہ پانے والوں میں ہو گئے۔', 'اور یہ وہی تمہارا خیال ہے جو تم رکھتے تھے اپنے رب کے حق میں اسی نے تمکو غارت کیا پھر آج رہ گئے ٹوٹے میں', 'And that thought of yours which you thought about your Lord, has brought you to destruction, and you have become (this Day) of those utterly lost!', 'This thought of yours that you conceived about your Lord brought you to ruin, and you became among the losers.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(4242, 41, 24, 3, 17, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'فَاِنۡ یَّصۡبِرُوۡا فَالنَّارُ مَثۡوًی لَّہُمۡ ۚ وَ  اِنۡ یَّسۡتَعۡتِبُوۡا فَمَا ہُمۡ مِّنَ الۡمُعۡتَبِیۡنَ ﴿۲۴﴾', 'اب اگر یہ صبر کریں گے تو بھی ان کا ٹھکانہ دوزخ ہی ہے اور اگر توبہ کریں گے تو انکی توبہ قبول نہیں کی جائے گی۔', 'پھر اگر وہ صبر کریں تو آگ ان کا گھر ہے اور اگر وہ منایا چاہیں تو انکو کوئی نہیں مانتا [۳۵]', 'Then, if they have patience, yet the Fire will be a home for them, and if they beg for to be excused, yet they are not of those who will ever be excused.', 'Now, if they endure patiently, even then the Fire is their abode, and if they seek forgiveness, they are not among those (who could be) forgiven.'),
(4243, 41, 25, 3, 17, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ قَیَّضۡنَا لَہُمۡ قُرَنَآءَ فَزَیَّنُوۡا لَہُمۡ مَّا بَیۡنَ  اَیۡدِیۡہِمۡ وَ مَا خَلۡفَہُمۡ وَ حَقَّ عَلَیۡہِمُ  الۡقَوۡلُ فِیۡۤ  اُمَمٍ قَدۡ خَلَتۡ مِنۡ قَبۡلِہِمۡ  مِّنَ  الۡجِنِّ وَ الۡاِنۡسِ ۚ اِنَّہُمۡ کَانُوۡا خٰسِرِیۡنَ ﴿٪۲۵﴾', 'اور ہم نے انکے ایسے ساتھی بنائے جنہوں نے انکے اگلے اور پچھلے اعمال انکو عمدہ کر دکھائے تھے اور جنات اور انسانوں کی جماعتیں جو ان سے پہلے گذر چکیں ان پر بھی اللہ کے عذاب کا وعدہ پورا ہو گیا۔ بیشک یہ نقصان اٹھانے والے ہیں۔', 'اور لگا دیے ہم نے انکے پیچھے ساتھ رہنے والے پھر انہوں نے خوبصورت بنادیا انکی آنکھوں میں اسکو جو انکے آگے ہو اور جو انکے پیچھے ہو [۳۶] اور ٹھیک پڑ چکی ان پر عذاب کی بات ان فرقوں کے ساتھ جو گذر چکے ان سے پہلے جنوں کے اور آدمیوں کے [۳۷] بیشک وہ تھے ٹوٹے والے [۳۸]', 'And We have assigned them (devils) intimate companions (in this world), who have made fair-seeming to them, what was before them (evil deeds which they were doing in the present worldly life and disbelief in the Reckoning and the Resurrection, etc.) and what was behind them (denial of the matters in the coming life of the Hereafter as regards punishment or reward, etc.). And the Word (i.e. the torment) is justified against them as it was justified against those who were among the previous generations of jinns and men that had passed away before them. Indeed they (all) were the losers.', 'And We had assigned for them fellows (in the worldly life) who beautified for them what was before them and what was behind them. And (thus) the word (of punishment) became due against them along with the communities that passed before them from Jinns and human beings. Surely they were the losers.'),
(4244, 41, 26, 4, 18, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ قَالَ الَّذِیۡنَ کَفَرُوۡا لَا تَسۡمَعُوۡا لِہٰذَا الۡقُرۡاٰنِ وَ الۡغَوۡا فِیۡہِ  لَعَلَّکُمۡ تَغۡلِبُوۡنَ ﴿۲۶﴾', 'اور کافر کہنے لگے کہ اس قرآن کو سنا ہی نہ کرو اور جب پڑھنے لگیں تو شور مچا دیا کرو تاکہ تم غالب رہو۔', 'اور کہنے لگے منکر مت کان دھرو اس قرآن کے سننے کو اور بک بک کرو اسکے پڑھنے میں شاید تم غالب ہو [۳۹]', 'And those who disbelieve say: \"Listen not to this Quran, and make noise in the midst of its (recitation) that you may overcome.\"', 'And said those who disbelieved, “Do not listen to this Qur’ān, and make noise during its recitation, so that you may overcome.”'),
(4245, 41, 27, 4, 18, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'فَلَنُذِیۡقَنَّ  الَّذِیۡنَ کَفَرُوۡا عَذَابًا شَدِیۡدًا ۙ وَّ لَنَجۡزِیَنَّہُمۡ  اَسۡوَاَ الَّذِیۡ کَانُوۡا یَعۡمَلُوۡنَ ﴿۲۷﴾', 'سو ہم بھی کافروں کو سخت عذاب کے مزے چکھائیں گے اور انکے برے اعمال کی جو وہ کرتے تھے سزا دیں گے۔', 'سو ہم کو ضرور چکھانا ہے منکروں کو سخت عذاب اور ان کو بدلا دینا ہے برے سے کاموں کا جو وہ کرتے تھے [۴۰]', 'But surely, We shall cause those who disbelieve to taste a severe torment, and certainly, We shall requite them the worst of what they used to do.', 'So, We will certainly make them taste a severe punishment, and will certainly recompense them for the worst of what they used to do.'),
(4246, 41, 28, 4, 18, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'ذٰلِکَ جَزَآءُ  اَعۡدَآءِ اللّٰہِ النَّارُ ۚ لَہُمۡ فِیۡہَا دَارُ الۡخُلۡدِ ؕ جَزَآءًۢ  بِمَا کَانُوۡا بِاٰیٰتِنَا یَجۡحَدُوۡنَ ﴿۲۸﴾', 'یہ اللہ کے دشمنوں کا بدلہ ہے یعنی دوزخ۔ انکے لئے اسی میں ہمیشہ کا گھر ہے۔ یہ اسکی سزا ہے کہ ہماری آیتوں سے انکار کرتے تھے۔', 'یہ سزا ہے اللہ کے دشمنوں کی آگ اُن کا اسی میں گھر ہے سدا کو  بدلا اس کا جو ہماری باتوں سے انکار کرتے تھے [۴۱]', 'That is the recompense of the enemies of Allah: The Fire, therein will be for them the eternal home, a (deserving) recompense for that they used to deny Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.).', 'That is the recompense of the enemies of Allah- the Fire. For them there is the eternal home, as a recompense for their persistent denial of Our verses.'),
(4247, 41, 29, 4, 18, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ قَالَ الَّذِیۡنَ کَفَرُوۡا رَبَّنَاۤ  اَرِنَا الَّذَیۡنِ اَضَلّٰنَا مِنَ الۡجِنِّ وَ الۡاِنۡسِ نَجۡعَلۡہُمَا تَحۡتَ اَقۡدَامِنَا لِیَکُوۡنَا مِنَ الۡاَسۡفَلِیۡنَ ﴿۲۹﴾', 'اور کافر کہیں گے کہ اے ہمارے پروردگار جنوں اور انسانوں میں سے جن لوگوں نے ہمکو گمراہ کیا تھا انکو ہمیں دکھا کہ ہم انکو اپنے پاؤں تلے روند ڈالیں تاکہ وہ سب سے نیچے رہیں۔', 'اور کہیں گے وہ لوگ جو منکر ہیں اے ہمارے رب ہمکو دکھلا دے وہ دونوں جنہوں نے ہم کو بہکایا جو جن ہے اور جو آدمی کہ ہم ڈالیں  انکو اپنے پاؤں کے نیچے کہ وہ رہیں سب سے نیچے [۴۲]', 'And those who disbelieve will say: \"Our Lord! Show us those among jinns and men who led us astray, we shall crush them under our feet, so that they become the lowest.\"', 'And those who disbelieve will say, “Our Lord, show us the two, out of the Jinns and the humans, who led us astray and we will put both of them under our feet, so that they become among the lowest.”'),
(4248, 41, 30, 4, 18, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'اِنَّ  الَّذِیۡنَ قَالُوۡا رَبُّنَا اللّٰہُ  ثُمَّ اسۡتَقَامُوۡا تَتَنَزَّلُ عَلَیۡہِمُ الۡمَلٰٓئِکَۃُ  اَلَّا تَخَافُوۡا وَ لَا تَحۡزَنُوۡا وَ اَبۡشِرُوۡا بِالۡجَنَّۃِ  الَّتِیۡ  کُنۡتُمۡ تُوۡعَدُوۡنَ ﴿۳۰﴾', 'جن لوگوں نے کہا کہ ہمارا پروردگار اللہ ہے پھر وہ اس پر قائم رہے۔ ان پر فرشتے اتریں گے اور کہیں گے کہ نہ خوف کرو اور نہ غمناک ہو اور بہشت کی جس کا تم سے وعدہ کیا جاتا ہے خوشی مناؤ۔', 'تحقیق جنہوں نے کہا رب ہمارا اللہ ہے پھر اس پر قائم رہے ان پر اترتے ہیں فرشتے کہ تم مت ڈرو اور نہ غم کھاؤ اور خوشخبری سنو اس بہشت کی جس کا تم سے وعدہ تھا [۴۳]', 'Verily, those who say: \"Our Lord is Allah (Alone),\" and then they Istaqamoo , on them the angels will descend (at the time of their death) (saying): \"Fear not, nor grieve! But receive the glad tidings of Paradise which you have been promised!', 'Surely, those who have declared: “Our Lord is Allah”, then remained steadfast, on them the angels will descend, saying, “Do not fear, and do not grieve; and be happy with the good news of the Jannah (Paradise) that you had been promised.'),
(4249, 41, 31, 4, 18, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'نَحۡنُ اَوۡلِیٰٓؤُکُمۡ فِی الۡحَیٰوۃِ  الدُّنۡیَا وَ فِی الۡاٰخِرَۃِ ۚ وَ لَکُمۡ فِیۡہَا مَا تَشۡتَہِیۡۤ اَنۡفُسُکُمۡ وَ لَکُمۡ فِیۡہَا مَا تَدَّعُوۡنَ ﴿ؕ۳۱﴾', 'ہم دنیا کی زندگی میں بھی تمہارے دوست تھے اور آخرت میں بھی تمہارے رفیق ہیں اور وہاں جس نعمت کو تمہارا جی چاہے گا تمکو ملے گی اور جو چیز طلب کرو گے تمہارے لئے موجود ہو گی۔', 'ہم ہیں تمہارے رفیق دنیا میں اور آخرت میں [۴۴] اور تمہارے لئے وہاں ہے جو چاہے جی تمہارا اور تمہارے لئے وہاں ہے جو کچھ مانگو [۴۵]', '\"We have been your friends in the life of this world and are (so) in the Hereafter. Therein you shall have (all) that your inner-selves desire, and therein you shall have (all) for which you ask for.', 'We have been your friends in the worldly life, and (will remain as such) in the Hereafter. And for you here is whatever your souls desire, and for you here is whatever you call for'),
(4250, 41, 32, 4, 18, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'نُزُلًا  مِّنۡ غَفُوۡرٍ  رَّحِیۡمٍ ﴿٪۳۲﴾', 'یہ بخشنے والے مہربان کی طرف سے مہمانی ہے۔', 'مہمانی ہے اس بخشنے والے مہربان کی طرف سے [۴۶]', '\"An entertainment from (Allah), the Oft-Forgiving, Most Merciful.\"', '- a gift of welcome from the Most-forgiving, the Very-Merciful”.'),
(4251, 41, 33, 5, 19, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ مَنۡ اَحۡسَنُ  قَوۡلًا  مِّمَّنۡ دَعَاۤ  اِلَی اللّٰہِ  وَ عَمِلَ  صَالِحًا وَّ قَالَ  اِنَّنِیۡ مِنَ الۡمُسۡلِمِیۡنَ ﴿۳۳﴾', 'اور اس شخص سے بڑھکر بات کا اچھا کون ہو سکتا ہے جو اللہ کی طرف بلائے اور عمل نیک کرے اور کہے کہ میں مسلمان ہوں۔', 'اور اس سے بہتر کس کی بات جس نے بلایا اللہ کی طرف اور کیا نیک کام اور کہا میں حکمبردار ہوں [۴۷]', 'And who is better in speech than he who (says: \"My Lord is Allah (believes in His Oneness),\" and then stands straight (acts upon His Order), and) invites (men) to Allahs (Islamic Monotheism), and does righteous deeds, and says: \"I am one of the Muslims.\"', 'Who can be better in words than the one who calls towards Allah, and acts righteously and says, “I am one of those who submit themselves (to Allah)”?'),
(4252, 41, 34, 5, 19, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ لَا تَسۡتَوِی الۡحَسَنَۃُ  وَ لَا السَّیِّئَۃُ ؕ اِدۡفَعۡ  بِالَّتِیۡ  ہِیَ  اَحۡسَنُ فَاِذَا الَّذِیۡ بَیۡنَکَ وَ بَیۡنَہٗ  عَدَاوَۃٌ کَاَنَّہٗ  وَلِیٌّ حَمِیۡمٌ ﴿۳۴﴾', 'اور بھلائی اور برائی برابر نہیں ہو سکتی۔ تو سخت کلامی کا ایسے طریق سے جواب دو جو بہت اچھا ہو ایسا کرنے سے تم دیکھو گے کہ جسمیں اور تم میں دشمنی تھی وہ تمہارا گرم جوش دوست ہے۔', 'اور برابر نہیں نیکی اور نہ بدی جواب میں وہ کہہ جو اس سے بہتر ہو پھر تو دیکھ لے کہ تجھ میں اور جس میں دشمنی تھی گویا دوستدار ہے قرابت والا [۴۸]', 'The good deed and the evil deed cannot be equal. Repel (the evil) with one which is better (i.e. Allah ordered the faithful believers to be patient at the time of anger, and to excuse those who treat them badly), then verily! he, between whom and you there was enmity, (will become) as though he was a close friend.', 'Good and evil are not equal. Repel (evil) with what is best, and you will see that the one you had mutual enmity with him will turn as if he were a close friend.'),
(4253, 41, 35, 5, 19, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ مَا یُلَقّٰہَاۤ  اِلَّا الَّذِیۡنَ صَبَرُوۡا ۚ وَ مَا یُلَقّٰہَاۤ  اِلَّا  ذُوۡحَظٍّ  عَظِیۡمٍ ﴿۳۵﴾', 'اور یہ بات ان ہی لوگوں کو حاصل ہوتی ہے جو برداشت کرنے والے ہیں۔ اور ان ہی کو نصیب ہوتی ہے جو بڑے صاحب نصیب ہیں۔', 'اور یہ بات ملتی ہے انہی کو جو سہارے رکھتے ہیں اور یہ بات ملتی ہے اسی کو جس کی بڑی قسمت ہے [۴۹]', 'But none is granted it (the above quality) except those who are patient, and none is granted it except the owner of the great portion (of the happiness in the Hereafter i.e. Paradise and in this world of a high moral character).', 'And no one is blessed with this (attitude) but those who observe patience, and no one is blessed with this (attitude) but a man of great luck.'),
(4254, 41, 36, 5, 19, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ اِمَّا یَنۡزَغَنَّکَ مِنَ الشَّیۡطٰنِ نَزۡغٌ فَاسۡتَعِذۡ بِاللّٰہِ ؕ اِنَّہٗ  ہُوَ السَّمِیۡعُ الۡعَلِیۡمُ ﴿۳۶﴾', 'اور اگر تمہیں شیطان کی جانب سے کوئی وسوسہ پیدا ہو تو اللہ کی پناہ مانگ لیا کرو۔ بیشک وہ سنتا ہے جانتا ہے۔', 'اور جو کبھی چوک لگے تجھ کو شیطان کے چوک لگانے سے تو پناہ پکڑ اللہ کی بیشک وہی ہے سننے والا جاننے والا [۵۰]', 'And if an evil whisper from Shaitan (Satan) tries to turn you away (O Muhammad SAW) (from doing good, etc.), then seek refuge in Allah. Verily, He is the All-Hearer, the All-Knower.', 'And should a stroke from ShaiTān (Satan) strike you, seek refuge with Allah. Surely, He is the All-Hearing, the All-Knowing.'),
(4255, 41, 37, 5, 19, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ مِنۡ  اٰیٰتِہِ  الَّیۡلُ وَ النَّہَارُ وَ الشَّمۡسُ وَ الۡقَمَرُ ؕ لَا تَسۡجُدُوۡا  لِلشَّمۡسِ وَ لَا لِلۡقَمَرِ وَ اسۡجُدُوۡا لِلّٰہِ  الَّذِیۡ خَلَقَہُنَّ اِنۡ کُنۡتُمۡ  اِیَّاہُ  تَعۡبُدُوۡنَ ﴿۳۷﴾', 'اور رات اور دن اور سورج اور چاند اسکی نشانیوں میں سے ہیں۔ تم لوگ نہ تو سورج کو سجدہ کرو اور نہ چاند کو۔ بلکہ اللہ ہی کو سجدہ کرو جس نے ان چیزوں کو پیدا کیا ہے اگر تمکو اسکی عبادت منظور ہے۔', 'اور اسکی قدرت کے نمونے ہیں رات اور دن اور سورج اور چاند [۵۱] سجدہ نہ کرو سورج کو اور نہ چاند کو اور سجدہ کرو اللہ کو جس نے ان کو بنایا اگر تم اسی کو پوجتے ہو [۵۲]', 'And from among His Signs are the night and the day, and the sun and the moon. Prostrate not to the sun nor to the moon, but prostrate to Allah Who created them, if you (really) worship Him.', 'Among His signs are the night and the day, and the sun and the moon. Do not prostrate yourselves to the sun, or to the moon. And prostrate yourselves to Allah who has created them, if it is Him whom you worship.'),
(4256, 41, 38, 5, 19, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'فَاِنِ اسۡتَکۡبَرُوۡا فَالَّذِیۡنَ عِنۡدَ رَبِّکَ یُسَبِّحُوۡنَ لَہٗ بِالَّیۡلِ وَ النَّہَارِ وَ ہُمۡ لَا یَسۡـَٔمُوۡنَ ﴿ٛ۳۸﴾', 'پھر اگر یہ لوگ سرکشی کریں تو اللہ بھی ان سے بے نیاز ہے کیونکہ جو فرشتے تمہارے پروردگار کے پاس ہیں وہ رات دن اسکی تسبیح کرتے رہتے ہیں اور کبھی تھکتے ہی نہیں۔', 'پھر اگر غرور کریں تو جو لوگ تیرے رب کے پاس ہیں پاکی بولتے رہتے ہیں اسکی رات اور دن اور وہ نہیں تھکتے [۵۳]', 'But if they are too proud (to do so), then there are those who are with your Lord (angels) glorify Him night and day, and never are they tired.', 'Still, if they show arrogance, then those who are with your Lord proclaim His purity night and day, and they do not get weary.'),
(4257, 41, 39, 5, 19, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ مِنۡ اٰیٰتِہٖۤ  اَنَّکَ تَرَی الۡاَرۡضَ خَاشِعَۃً فَاِذَاۤ  اَنۡزَلۡنَا عَلَیۡہَا الۡمَآءَ  اہۡتَزَّتۡ وَ رَبَتۡ ؕ اِنَّ  الَّذِیۡۤ  اَحۡیَاہَا  لَمُحۡیِ الۡمَوۡتٰی ؕ اِنَّہٗ عَلٰی کُلِّ شَیۡءٍ  قَدِیۡرٌ ﴿۳۹﴾', 'اور اے بندے یہ اسی کی قدرت کے نمونے ہیں کہ تو زمین کو دبی ہوئی یعنی خشک دیکھتا ہے۔ پھر جب ہم اس پر پانی برسا دیتے ہیں تو وہ شاداب ہو جاتی اور پھولنے لگتی ہے بیشک وہ جس نے زمین کو زندہ کیا وہی مردوں کو زندہ کرنے والا ہے۔ بیشک وہ ہر چیز پر قادر ہے۔', 'اور ایک اس کی نشانی یہ کہ تو دیکھتا ہے زمین کو دبی پڑی پھر جب اتارا ہم نے اس پر پانی تازی ہوئی اور ابھری بیشک جس نے اس کو زندہ کیا وہ زندہ کرے گا مردوں کو  وہ سب کچھ کر سکتا ہے [۵۴]', 'And among His Signs (in this), that you see the earth barren, but when We send down water (rain) to it, it is stirred to life and growth (of vegetations). Verily, He Who gives it life, surely, (He) is Able to give life to the dead (on the Day of Resurrection). Indeed! He is Able to do all things.', 'And among His signs is that you see the land inactive; then, once We send down water thereto, it gets excited and swells. Surely, the One who has given life to it is the One who gives life to the dead. No doubt, He is powerful to do everything.'),
(4258, 41, 40, 5, 19, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'اِنَّ  الَّذِیۡنَ یُلۡحِدُوۡنَ فِیۡۤ  اٰیٰتِنَا لَا یَخۡفَوۡنَ عَلَیۡنَا ؕ اَفَمَنۡ یُّلۡقٰی فِی النَّارِ خَیۡرٌ  اَمۡ مَّنۡ یَّاۡتِیۡۤ  اٰمِنًا یَّوۡمَ الۡقِیٰمَۃِ ؕ اِعۡمَلُوۡا مَا شِئۡتُمۡ ۙ اِنَّہٗ  بِمَا تَعۡمَلُوۡنَ بَصِیۡرٌ ﴿۴۰﴾', 'بیشک جو لوگ ہمارے احکام سے انحراف کرتے ہیں وہ ہم سے پوشیدہ نہیں ہیں۔ بھلا جو شخص دوزخ میں ڈالا جائے وہ بہتر ہے یا وہ جو قیامت کے دن بے خوف ہو کر آئے؟ تو خیر جو چاہو سو کر لو۔ جو کچھ تم کرتے ہو وہ اسکو دیکھ رہا ہے۔', 'جو لوگ ٹیڑھے چلتے ہیں ہماری باتوں میں وہ ہم سے چھپے ہوئے نہیں بھلا ایک جو پڑتا ہے آگ میں وہ بہتر یا ایک جو  آئے گا امن سے دن قیامت کے کئے جاؤ جو چاہو بیشک جو تم کرتے ہو وہ دیکھتا ہے [۵۵]', 'Verily, those who turn away from Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc. by attacking, distorting and denying them), are not hidden from Us. Is he who is cast into the Fire better or he who comes secure on the Day of Resurrection? Do what you will. Verily! He is All-Seer of what you do (this is a severe threat to the disbelievers).', 'Surely those who adopt perversity about Our verses are not hidden from Us. So, tell me which one is better: the one who is thrown into the Fire, or the one who will come safely on the Day of Judgment? Do whatever you wish. He is watchful of whatever you do.'),
(4259, 41, 41, 5, 19, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'اِنَّ  الَّذِیۡنَ کَفَرُوۡا بِالذِّکۡرِ  لَمَّا جَآءَہُمۡ ۚ وَ  اِنَّہٗ   لَکِتٰبٌ عَزِیۡزٌ ﴿ۙ۴۱﴾', 'جن لوگوں نے نصیحت کو نہ مانا جب وہ انکے پاس آئی۔ حالانکہ یہ تو ایک عالی رتبہ کتاب ہے۔', 'جو لوگ منکر ہوئے نصیحت سے جب آئی ان کے  پاس [۵۶] اور وہ کتاب ہے نادر', 'Verily, those who disbelieved in the Reminder (i.e. the Quran) when it came to them (shall receive the punishment). And verily, it is an honourable respected Book (because it is Allahs Speech, and He has protected it from corruption, etc.). (See V.15:9)', 'Surely those who have rejected the advice (the Qur’ān) when it came to them (are the ones who adopted perversity, and are not hidden from Us). And surely, it is an unassailable book'),
(4260, 41, 42, 5, 19, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'لَّا یَاۡتِیۡہِ  الۡبَاطِلُ مِنۡۢ بَیۡنِ یَدَیۡہِ وَ لَا مِنۡ خَلۡفِہٖ ؕ تَنۡزِیۡلٌ مِّنۡ حَکِیۡمٍ حَمِیۡدٍ ﴿۴۲﴾', 'اس میں جھوٹ کا دخل نہ آگے سے ہو سکتا ہے نہ پیچھے سے۔ یہ کتاب حکمت والے خوبیوں والے کی اتاری ہوئی ہے۔', 'اُس پر جھوٹ کا دخل نہیں آگے سے اور نہ پیچھے سے اتاری ہوئی ہے حکمتوں والے سب تعریفوں والے کی [۵۷]', 'Falsehood cannot come to it from before it or behind it (it is) sent down by the All-Wise, Worthy of all praise (Allah ÚÒ æ Ìá).', 'that cannot be approached by falsehood, neither from its front, nor from its behind -a revelation from the All-Wise, the Ever-Praised.'),
(4261, 41, 43, 5, 19, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'مَا یُقَالُ  لَکَ اِلَّا مَا قَدۡ قِیۡلَ  لِلرُّسُلِ مِنۡ قَبۡلِکَ ؕ اِنَّ  رَبَّکَ لَذُوۡ مَغۡفِرَۃٍ  وَّ ذُوۡ عِقَابٍ  اَلِیۡمٍ ﴿۴۳﴾', 'اے پیغمبر تم سے وہی باتیں کہی جاتی ہیں جو تم سے پہلے پیغمبروں سے بھی کہی گئ تھیں۔ بیشک تمہارا پروردگار بخش دینے والا بھی ہے اور عذاب الیم دینے والا بھی۔', 'تجھے وہی کہتے ہیں جو کہہ چکےہیں سب رسولوں سے تجھ سے پہلے تیرے رب کے  یہاں معافی بھی ہے اور سزا بھی ہے دردناک [۵۸]', 'Nothing is said to you (O Muhammad SAW) except what was said to the Messengers before you. Verily, your Lord is the Possessor of forgiveness, and (also) the Possessor of painful punishment.', 'Nothing is being said to you but what has been said to the messengers before you. Your Lord is certainly the Lord of forgiveness and the Lord of painful punishment.'),
(4262, 41, 44, 5, 19, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ لَوۡ جَعَلۡنٰہُ  قُرۡاٰنًا  اَعۡجَمِیًّا  لَّقَالُوۡا لَوۡ لَا  فُصِّلَتۡ اٰیٰتُہٗ ؕ  ءَؔاَعۡجَمِیٌّ وَّ عَرَبِیٌّ ؕ قُلۡ ہُوَ لِلَّذِیۡنَ اٰمَنُوۡا ہُدًی وَّ شِفَآءٌ ؕ وَ الَّذِیۡنَ  لَا یُؤۡمِنُوۡنَ فِیۡۤ  اٰذَانِہِمۡ وَقۡرٌ  وَّ ہُوَ عَلَیۡہِمۡ  عَمًی ؕ اُولٰٓئِکَ یُنَادَوۡنَ مِنۡ مَّکَانٍۭ بَعِیۡدٍ ﴿٪۴۴﴾', 'اور اگر ہم اس قرآن کو غیر عربی زبان میں نازل کرتے تو یہ لوگ کہتے کہ اسکی آیتیں ہماری زبان میں کیوں کھول کر بیان نہیں کی گئیں۔ کیا خوب کہ قرآن تو عجمی اور مخاطب عربی۔ کہدو کہ جو ایمان لاتے ہیں انکے لئے یہ ہدایت اور شفا ہے۔ اور جو ایمان نہیں لاتے انکے کانوں میں گرانی یعنی بہراپن ہے اور یہ انکے اندھے پن کا باعث ہے۔ انکو گویا دور کی جگہ سے آواز دی جاتی ہے۔', 'اور اگر  ہم اُسکو کرتے قرآن اوپری زبان کا تو کہتے اس کی باتیں کیوں نہ کھولی گئیں کیا اوپری زبان کی کتاب اور عربی لوگ [۵۹] تو کہہ یہ ایمان والوں کے لئے سوجھ ہے اور روگ کا دور کرنے والا  [۶۰] اور جو یقین نہیں لاتے ان کے کانوں میں بوجھ ہے اور یہ قرآن انکے حق میں اندھاپا ہے [۶۱] انکو پکارتے ہیں دور کی جگہ سے [۶۲]', 'And if We had sent this as a Quran in a foreign language other than Arabic, they would have said: \"Why are not its Verses explained in detail (in our language)? What! (A Book) not in Arabic and (the Messenger) an Arab?\" Say: \"It is for those who believe, a guide and a healing. And as for those who disbelieve, there is heaviness (deafness) in their ears, and it (the Quran) is blindness for them. They are those who are called from a place far away (so they neither listen nor understand).', 'Had We made it a non-Arabic Qur’ān, they would have said, “Why are its verses not clearly explained? Is it a non-Arabic (book) and an Arab (messenger)?” Say, “For those who believe, it is guidance and cure. As for those who do not believe, there is deafness in their ears, and for them it is blindness. Such people are being called from a distant place.”'),
(4263, 41, 45, 6, 0, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'وَ لَقَدۡ اٰتَیۡنَا مُوۡسَی الۡکِتٰبَ فَاخۡتُلِفَ فِیۡہِ ؕ وَ لَوۡ لَا کَلِمَۃٌ سَبَقَتۡ مِنۡ رَّبِّکَ لَقُضِیَ بَیۡنَہُمۡ ؕ وَ اِنَّہُمۡ لَفِیۡ شَکٍّ  مِّنۡہُ  مُرِیۡبٍ ﴿۴۵﴾', 'اور ہم نے موسٰی کو کتاب دی پھر اس میں اختلاف کیا گیا۔ اور اگر تمہارے پروردگار کی طرف سے ایک بات پہلے نہ ٹھہر چکی ہوتی تو ان میں فیصلہ کر دیا جاتا۔ اور یہ اس قرآن کی طرف سے بڑے بھاری شک میں پڑے ہیں۔', 'اور ہم نے دی تھی موسٰی کو کتاب پھر اس میں اختلاف پڑا [۶۳] اور اگر نہ ہوتی ایک بات جو  پہلے نکل چکی تیرے رب کی طرف سے تو ان میں فیصلہ ہو جاتا [۶۴] اور وہ ایسے دھوکے میں ہیں اس قرآن سے جو چین نہیں لینے دیتا [۶۵]', 'And indeed We gave Moosa (Moses) the Scripture, but dispute arose therein. And had it not been for a Word that went forth before from your Lord, (the torment would have overtaken them) and the matter would have been settled between them. But truly, they are in grave doubt thereto (i.e. about the Quran). (Tafsir Al-Qurtubi, Vol. 15, Page 370)', 'And We gave Mūsā the book, then it was disputed (as well). But for a word that had already come from your Lord, the matter would have been decided between them. They are in confounding doubt about it.'),
(4264, 41, 46, 6, 0, 24, 'فَمَنۡ اَظۡلَمُ', 'حم  السجدہ', 'مَنۡ عَمِلَ صَالِحًا فَلِنَفۡسِہٖ وَ مَنۡ  اَسَآءَ فَعَلَیۡہَا ؕ وَ مَا رَبُّکَ بِظَلَّامٍ  لِّلۡعَبِیۡدِ ﴿۴۶﴾', 'جو نیک کام کرے گا تو اپنے لئے۔ اور جو برے کام کرے گا ان کا ضرر اسی کو ہو گا۔ اور تمہارا  پروردگار بندوں پر ظلم کرنے والا نہیں۔', 'جس نے کی بھلائی سو اپنے واسطے اور جس نے کی برائی سو وہ بھی اسی پر اور تیرا رب ایسا نہیں کہ ظلم کرے بندوں پر [۶۶]', 'Whosoever does righteous good deed it is for (the benefit of) his ownself, and whosoever does evil, it is against his ownself, and your Lord is not at all unjust to (His) slaves.', 'If someone acts righteously, he does so for the benefit of his own soul, and if someone commits evil, he does so against it. Your Lord is not unjust to His servants.'),
(4265, 41, 47, 6, 1, 25, 'اِلَیۡہِ یُرَدّ', 'حم  السجدہ', 'اِلَیۡہِ یُرَدُّ  عِلۡمُ السَّاعَۃِ ؕ وَ مَا تَخۡرُجُ مِنۡ ثَمَرٰتٍ مِّنۡ  اَکۡمَامِہَا وَ مَا تَحۡمِلُ مِنۡ  اُنۡثٰی وَ لَا تَضَعُ  اِلَّا بِعِلۡمِہٖ ؕ وَ یَوۡمَ  یُنَادِیۡہِمۡ  اَیۡنَ شُرَکَآءِیۡ ۙ قَالُوۡۤا اٰذَنّٰکَ ۙ مَا مِنَّا مِنۡ شَہِیۡدٍ ﴿ۚ۴۷﴾', 'قیامت کے علم کا حوالہ اسی کی طرف دیا جاتا ہے یعنی قیامت کا علم اسی کو ہے اور نہ تو پھل غلافوں سے نکلتے ہیں اور نہ کوئی مادہ حاملہ ہوتی ہے اور نہ جنتی ہے مگر اسکے علم سے۔ اور جس دن وہ انکو پکارے گا اور کہے گا کہ میرے شریک کہاں ہیں تو وہ کہیں گے کہ ہم تجھ سے عرض کرتے ہیں کہ ہم میں سے کسی کو انکی خبر ہی نہیں۔', 'اُسی کی طرف حوالہ ہے قیامت کی خبر کا [۶۷] اور نہیں نکلتے کوئی میوے اپنے غلاف سے اور نہیں رہتا حمل کسی مادہ کو اور نہ وہ جنے کہ جسکی اسکو خبر نہیں [۶۸] اور جس دن انکو پکارے گا کہاں ہیں میرےشریک [۶۹] بولیں گے ہم نے تجھ کو کہہ سنایا ہم میں کوئی اس کا اقرار نہیں کرتا [۷۰]', '(The learned men) refer to Him (Alone) the knowledge of the Hour. No fruit comes out of its sheath, nor does a female conceive (within her womb), nor brings forth (young), except by His Knowledge. And on the Day when He will call unto them (polytheists) (saying): \"Where are My (so-called) partners (whom you did invent)?\" They will say: \"We inform You that none of us bears witness to it (that they are Your partners)!\"', 'To Him alone the knowledge of the Hour (the exact time of Doomsday) is to be referred. No fruits come out of their sheaths, nor does a female conceive a baby, nor does she deliver it, but with His knowledge. And (remember) the Day when He will call them: “Where are My partners?” They will say, “We declare to you that no one of us is to testify (that you have partners).”'),
(4266, 41, 48, 6, 1, 25, 'اِلَیۡہِ یُرَدّ', 'حم  السجدہ', 'وَ ضَلَّ عَنۡہُمۡ  مَّا کَانُوۡا یَدۡعُوۡنَ مِنۡ قَبۡلُ  وَ ظَنُّوۡا مَا  لَہُمۡ  مِّنۡ مَّحِیۡصٍ ﴿۴۸﴾', 'اور جنکو پہلے وہ اللہ کے سوا پکارا کرتے تھے سب ان سے گم ہو جائیں گے اور وہ یقین کر لیں گے کہ ان کے لئے کوئی راہ فرار نہیں۔', 'اور چوک گیا ان سے جو پکارتے تھے پہلے اور سمجھ گئے کہ انکو کہیں نہیں خلاصی [۷۱]', 'And those whom they used to invoke before will fail them, and they will perceive that they have no place of refuge (from Allahs punishment).', 'And whatever they used to invoke earlier will vanish from them, and they will realize that they have no way to escape.'),
(4267, 41, 49, 6, 1, 25, 'اِلَیۡہِ یُرَدّ', 'حم  السجدہ', 'لَا یَسۡـَٔمُ الۡاِنۡسَانُ مِنۡ دُعَآءِ  الۡخَیۡرِ ۫ وَ اِنۡ مَّسَّہُ  الشَّرُّ  فَیَـُٔوۡسٌ قَنُوۡطٌ ﴿۴۹﴾', 'انسان بھلائی کی دعائیں کرتا کرتا تو تھکتا نہیں اور اگر اسکو تکلیف پہنچ جاتی ہے تو ناامید ہو جاتا ہے آس توڑ بیٹھتا ہے۔', 'نہیں تھکتا آدمی مانگنے سے بھلائی اور اگر لگ جائے اس کو برائی تو آس توڑ بیٹھے ناامید ہو کر', 'Man (the disbeliever) does not get tired of asking good (things from Allah), but if an evil touches him, then he gives up all hope and is lost in despair.', 'Man does not get weary of craving for (all sorts of ) good things; and if he is touched by some evil, he is disappointed, devoid of any hope.'),
(4268, 41, 50, 6, 1, 25, 'اِلَیۡہِ یُرَدّ', 'حم  السجدہ', 'وَ لَئِنۡ اَذَقۡنٰہُ رَحۡمَۃً مِّنَّا مِنۡۢ بَعۡدِ ضَرَّآءَ مَسَّتۡہُ  لَیَقُوۡلَنَّ ہٰذَا لِیۡ ۙ وَ مَاۤ  اَظُنُّ السَّاعَۃَ  قَآئِمَۃً ۙ وَّ لَئِنۡ  رُّجِعۡتُ  اِلٰی رَبِّیۡۤ  اِنَّ  لِیۡ عِنۡدَہٗ  لَلۡحُسۡنٰی ۚ فَلَنُنَبِّئَنَّ الَّذِیۡنَ  کَفَرُوۡا بِمَا عَمِلُوۡا ۫ وَ لَنُذِیۡقَنَّہُمۡ  مِّنۡ عَذَابٍ  غَلِیۡظٍ ﴿۵۰﴾', 'اور اگر تکلیف پہنچنے کے بعد ہم اسکو اپنی رحمت کا مزہ چکھاتے ہیں تو کہتا ہے کہ یہ تو میرا حق تھا اور میں نہیں خیال کرتا کہ قیامت برپا ہو اور اگر قیامت سچ مچ ہو بھی اور میں اپنے پروردگار کی طرف لوٹایا بھی جاؤں تو میرے لئے اسکے ہاں بھی خوشحالی ہو گی پس کافر جو کچھ کیا کرتے ہیں وہ ہم ضرور انکو جتائیں گے اور انکو سخت عذاب کا مزہ چکھائیں گے۔', 'اور اگر ہم چکھائیں اسکو کچھ اپنی مہربانی پیچھے ایک تکلیف کے جو اسکو پہنچی تھی تو کہنے لگے یہ ہے میرے لائق اور میں نہیں سمجھتا کہ قیامت آنے والی ہے اور اگر میں پھر بھی گیا اپنے رب کی طرف بیشک میرے لئے ہے اسکے پاس خوبی [۷۲] سو ہم جتلا دیں گے منکروں کو جو انہوں نے کیا ہے اور چکھائیں گے انکو ایک گاڑھا عذاب [۷۳]', 'And truly, if We give him a taste of mercy from us, after some adversity (severe poverty or disease, etc.) has touched him, he is sure to say: \"This is for me (due to my merit), I think not that the Hour will be established. But if I am brought back to my Lord, Surely, there will be for me the best (wealth, etc.) with Him. Then, We verily, will show to the disbelievers what they have done and We shall make them taste a severe torment.', 'And if We give him a taste of some mercy from Us after some hardship that has touched him, he will surely say, “This is my right. And I do not think the Hour (the Day of Judgment) is going to occur. And even if I am brought back to my Lord, I will surely have the best (life) with Him (too).”So, We will let the disbelievers know what they did, and let them taste a stern punishment.'),
(4269, 41, 51, 6, 1, 25, 'اِلَیۡہِ یُرَدّ', 'حم  السجدہ', 'وَ اِذَاۤ  اَنۡعَمۡنَا عَلَی الۡاِنۡسَانِ  اَعۡرَضَ وَ نَاٰ بِجَانِبِہٖ ۚ وَ اِذَا مَسَّہُ  الشَّرُّ فَذُوۡ دُعَآءٍ  عَرِیۡضٍ ﴿۵۱﴾', 'اور جب ہم انسان کو نعمتوں سے نوازتے ہیں تو وہ منہ موڑ لیتا اور پہلو پھیر کر چل دیتا ہے اور جب اسکو تکلیف پہنچتی ہے تو لمبی چوڑی دعائیں کرنے لگتا ہے۔', 'اور جب ہم  نعمتیں بھیجیں انسان پر تو ٹلا جائے اور موڑ لے اپنی کروٹ اور جب لگے اسکو برائی تو دعائیں کرے چوڑی [۷۴]', 'And when We show favour to man, he withdraws and turns away, but when evil touches him, then he has recourse to long supplications.', 'When We bestow Our favor upon man, he avoids (to appreciate it) and keeps himself far aside (from obedience), and when some evil touches him, he is full of lengthy prayers.'),
(4270, 41, 52, 6, 1, 25, 'اِلَیۡہِ یُرَدّ', 'حم  السجدہ', 'قُلۡ  اَرَءَیۡتُمۡ  اِنۡ کَانَ  مِنۡ عِنۡدِ اللّٰہِ  ثُمَّ کَفَرۡتُمۡ  بِہٖ مَنۡ  اَضَلُّ  مِمَّنۡ ہُوَ  فِیۡ  شِقَاقٍۭ بَعِیۡدٍ ﴿۵۲﴾', 'کہو کہ بھلا دیکھو تو اگر یہ قرآن اللہ کی طرف سے ہو پھر بھی تم اس سے انکار کرو تو اس سے بڑھ کر کون گمراہ ہے جو حق کی مخالفت میں دور نکل گیا ہو۔', 'تو کہہ بھلا دیکھو تو اگر یہ ہو اللہ کے پاس سے پھر تم نے اس کو نہ مانا پھر اس سے گمراہ زیادہ کون جو دور چلا جائے مخالف ہو کر [۷۵]', 'Say: \"Tell me, if it (the Quran) is from Allah, and you disbelieve in it, who is more astray than one who is in opposition far away (from Allahs Right Path and His obedience).', 'Say (to the disbelievers), “Tell me, if it (the Qur’ān) is from Allah, and still you reject it, then who can be more erroneous than him who is (involved) in far reaching schism?”'),
(4271, 41, 53, 6, 1, 25, 'اِلَیۡہِ یُرَدّ', 'حم  السجدہ', 'سَنُرِیۡہِمۡ  اٰیٰتِنَا فِی الۡاٰفَاقِ  وَ فِیۡۤ   اَنۡفُسِہِمۡ حَتّٰی یَتَبَیَّنَ  لَہُمۡ  اَنَّہُ  الۡحَقُّ ؕ اَوَ لَمۡ یَکۡفِ بِرَبِّکَ  اَنَّہٗ عَلٰی کُلِّ  شَیۡءٍ شَہِیۡدٌ ﴿۵۳﴾', 'ہم عنقریب انکو اطراف عالم میں بھی اور خود انکی ذات میں بھی اپنی نشانیاں دکھائیں گے یہاں تک کہ ان پر ظاہر ہو جائے گا کہ قرآن حق ہے۔ کیا تمکو یہ کافی نہیں کہ تمہارا پروردگار ہر چیز سے خبردار ہے۔', 'اب ہم دکھلائیں گے انکو اپنے نمونے دنیا میں اور خود انکی جانوں میں یہاں تک کہ کھل جائے ان پر کہ یہ ٹھیک ہے [۷۶] کیا تیرا رب تھوڑا ہے ہر چیز پر گواہ ہونے کے لئے [۷۷]', 'We will show them Our Signs in the universe, and in their ownselves, until it becomes manifest to them that this (the Quran) is the truth. Is it not sufficient in regard to your Lord that He is a Witness over all things?', 'We will show them Our signs in the universe and within their own beings until it will become manifest to them that it is the truth. Is it not enough about your Lord that He is witness to everything?'),
(4272, 41, 54, 6, 1, 25, 'اِلَیۡہِ یُرَدّ', 'حم  السجدہ', 'اَلَاۤ  اِنَّہُمۡ  فِیۡ مِرۡیَۃٍ  مِّنۡ  لِّقَآءِ  رَبِّہِمۡ ؕ اَلَاۤ  اِنَّہٗ  بِکُلِّ  شَیۡءٍ  مُّحِیۡطٌ ﴿٪۵۴﴾', 'دیکھو یہ اپنے پروردگار کے روبرو حاضر ہونے سے شک میں ہیں۔ سن رکھو کہ وہ ہر چیز کا احاطہ کئے ہوئے ہے۔', 'سنتا ہے وہ دھوکے میں ہیں اپنے رب کی ملاقات سے سنتا ہے وہ گھیر رہا ہے ہر چیز کو [۷۸]', 'Verily! They are in doubt concerning the Meeting with their Lord? (i.e. Resurrection after their deaths, and their return to their Lord). Verily! He it is Who is surrounding all things!', 'Beware, they are in doubt about meeting their Lord. Beware, He is the One who encompasses everything.'),
(4273, 42, 1, 1, 2, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'حٰمٓ ۚ﴿۱﴾', 'حٰم۔', 'حٰم۔', 'HaMeem.', 'Hā Mīm'),
(4274, 42, 2, 1, 2, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'عٓسٓقٓ ﴿۲﴾', 'عٓسٓقٓ۔', 'عٓسٓقٓ۔', 'AeenSeenQaf. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings).', '‘Ain Sīn Qāf'),
(4275, 42, 3, 1, 2, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'کَذٰلِکَ یُوۡحِیۡۤ  اِلَیۡکَ وَ اِلَی الَّذِیۡنَ مِنۡ قَبۡلِکَ ۙ اللّٰہُ  الۡعَزِیۡزُ  الۡحَکِیۡمُ ﴿۳﴾', 'اللہ غالب و دانا اسی طرح تمہاری طرف ہدایات بھیجتا ہے جس طرح تم سے پہلے لوگوں کی طرف وحی بھیجتا رہا ہے۔', 'اسی طرح وحی بھیجتا ہے تیری طرف اور تجھ سے پہلوں کی طرف اللہ زبردست حکمتوں والا', 'Likewise Allah, the All-Mighty, the All-Wise inspires you (O Muhammad SAW) as (He inspired) those before you.', 'This is how Allah, the Mighty, the Wise, sends revelation to you and to those who were before you.'),
(4276, 42, 4, 1, 2, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'لَہٗ  مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ؕ وَ ہُوَ  الۡعَلِیُّ  الۡعَظِیۡمُ ﴿۴﴾', 'جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب اسی کا ہے اور وہ بلند و برتر ہے عظیم ہے۔', 'اسی کا ہے جو کچھ ہے آسمانوں میں اور زمین میں اور  وہی ہے سب سے اوپر بڑا [۱]', 'To Him belongs all that is in the heavens and all that is in the earth, and He is the Most High, the Most Great.', 'To him belongs all that is in the heavens and all that is in the earth, and He is the High, the Supreme.'),
(4277, 42, 5, 1, 2, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'تَکَادُ  السَّمٰوٰتُ یَتَفَطَّرۡنَ مِنۡ فَوۡقِہِنَّ وَ الۡمَلٰٓئِکَۃُ  یُسَبِّحُوۡنَ بِحَمۡدِ رَبِّہِمۡ وَ یَسۡتَغۡفِرُوۡنَ لِمَنۡ فِی الۡاَرۡضِ ؕ اَلَاۤ اِنَّ اللّٰہَ ہُوَ  الۡغَفُوۡرُ الرَّحِیۡمُ ﴿۵﴾', 'قریب ہے کہ آسمان اوپر سے پھٹ پڑیں اور فرشتے اپنے پروردگار کی تعریف کے ساتھ اسکی تسبیح کرتے رہتے اور جو لوگ زمین میں ہیں انکے لئے معافی مانگتے رہتے ہیں سن رکھو کہ اللہ بخشنے والا مہربان ہے۔', 'قریب ہے کہ پھٹ پڑیں آسمان اوپر سے [۲] اور فرشتے پاکی بولتے ہیں خوبیاں اپنے رب کی اور گناہ بخشواتے ہیں زمین والوں کے [۳] سنتا ہے وہی ہے معاف کرنے والا مہربان [۴]', 'Nearly the heavens might rent asunder from above them (by His Majesty), and the angels glorify the praises of their Lord, and ask for forgiveness for those on the earth, verily, Allah is the Oft-Forgiving, the Most Merciful.', 'The heavens almost burst apart from their above side, and angels proclaim the purity and praise of their Lord, and pray for forgiveness of those on the earth. Be aware that Allah is the Most-Forgiving, the Very-Merciful.'),
(4278, 42, 6, 1, 2, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ الَّذِیۡنَ اتَّخَذُوۡا مِنۡ دُوۡنِہٖۤ  اَوۡلِیَآءَ اللّٰہُ  حَفِیۡظٌ عَلَیۡہِمۡ ۫ۖ وَ مَاۤ  اَنۡتَ عَلَیۡہِمۡ  بِوَکِیۡلٍ ﴿۶﴾', 'اور جن لوگوں نے اسکے سوا کارساز بنا رکھے ہیں اللہ ان پر نگران ہے اور تم ان پر داروغہ نہیں ہو۔', 'اور جنہوں نے پکڑے ہیں اس کے سوائے رفیق اللہ کو وہ سب یاد ہیں اور تجھ پر نہیں ان کا ذمہ [۵]', 'And as for those who take as Auliya (guardians, supporters, helpers, protectors, etc.) others besides Him (i.e. they take false deities other than Allah (as) protectors, and they worship them) Allah is Hafeez (Protector) over them (i.e. takes care of their deeds and will recompense them), and you (O Muhammad SAW) are not a Wakeel (guardian or a disposer of their affairs) over them (to protect their deeds, etc.).', 'And those who have adopted patrons instead of Him, Allah is on watch against them, and you are not responsible for them.'),
(4279, 42, 7, 1, 2, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ کَذٰلِکَ  اَوۡحَیۡنَاۤ  اِلَیۡکَ قُرۡاٰنًا عَرَبِیًّا لِّتُنۡذِرَ اُمَّ الۡقُرٰی وَ مَنۡ حَوۡلَہَا وَ تُنۡذِرَ یَوۡمَ الۡجَمۡعِ لَا رَیۡبَ فِیۡہِ ؕ فَرِیۡقٌ فِی الۡجَنَّۃِ  وَ فَرِیۡقٌ فِی السَّعِیۡرِ ﴿۷﴾', 'اور اسی طرح ہم نے تمہارے پاس قرآن عربی بھیجا ہے تاکہ تم اس مرکزی شہر یعنی مکے کے رہنے والوں کو اور جو لوگ اسکے اردگرد رہتے ہیں انکو خبردار کرو اور انہیں قیامت کے دن کا بھی جسمیں کچھ شک نہیں خوف دلاؤ۔ اس روز ایک فریق بہشت میں جائے گا اور ایک فریق دوزخ میں۔', 'اور اسی طرح اتارا ہم نے تجھ پر قرآن عربی زبان کا کہ تو ڈر سنا دے بڑے گاؤں کو اور آس پاس والوں کو [۶] اور خبر سنا دے جمع  ہونے کے دن کی اس میں دھوکا نہیں ایک فرقہ بہشت میں اور ایک فرقہ آگ میں [۷]', 'And thus We have inspired unto you (O Muhammad SAW) a Quran (in Arabic) that you may warn the Mother of the Towns (Makkah) and all around it. And warn of the Day of Assembling, of which there is no doubt, when a party will be in Paradise (those who believed in Allah and followed what Allahs Messenger SAW brought them) and a party in the blazing Fire (Hell) (those who disbelieved in Allah and followed not what Allahs Messenger SAW brought them)', 'And thus We have revealed to you an Arabic Qur’ān, so that you may warn the mother town, and those around it, and warn (them) of the Day of Gathering, about which there is no doubt-(when) one group of people will be in Paradise, and another group in blazing Fire.'),
(4280, 42, 8, 1, 2, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ لَوۡ شَآءَ  اللّٰہُ  لَجَعَلَہُمۡ  اُمَّۃً  وَّاحِدَۃً وَّ لٰکِنۡ  یُّدۡخِلُ مَنۡ یَّشَآءُ  فِیۡ  رَحۡمَتِہٖ ؕ وَ الظّٰلِمُوۡنَ مَا لَہُمۡ مِّنۡ وَّلِیٍّ وَّ لَا  نَصِیۡرٍ ﴿۸﴾', 'اور اگر اللہ چاہتا تو انکو یعنی تمام انسانوں کو ایک ہی جماعت کر دیتا لیکن وہ جسکو چاہتا ہے اپنی رحمت میں داخل کر لیتا ہے۔ اور ظالموں کا نہ کوئی یار ہو گا اور نہ کوئی مددگار۔', 'اور اگر چاہتا اللہ تو سب لوگوں کو کرتا ایک ہی فرقہ و لیکن وہ داخل کرتا ہے جس کو چاہے اپنی رحمت میں اور گنہگار جو ہیں ان کا کوئی نہیں رفیق اور نہ مددگار [۸]', 'And if Allah had willed, He could have made them one nation, but He admits whom He wills to His Mercy. And the Zalimoon (polytheists and wrong-doers, etc.) will have neither a Walee (protector) nor a helper.', 'Had Allah willed, He would have made all of them a single group; but He admits whomsoever He wills into His mercy. As for the wrongdoers, they have neither a patron nor a helper.'),
(4281, 42, 9, 1, 2, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'اَمِ اتَّخَذُوۡا مِنۡ دُوۡنِہٖۤ  اَوۡلِیَآءَ ۚ فَاللّٰہُ ہُوَ  الۡوَلِیُّ  وَ ہُوَ  یُحۡیِ الۡمَوۡتٰی ۫ وَ ہُوَ  عَلٰی کُلِّ شَیۡءٍ  قَدِیۡرٌ ٪﴿۹﴾', 'کیا انہوں نے اسکے سوا دوسروں کو کارساز بنا لیا ہے؟ سو کارساز تو اللہ ہی ہے اور وہی مردوں کو زندہ کرے گا اور وہ ہر چیز پر قدرت رکھتا ہے۔', 'کیا انہوں نے پکڑے ہیں اُس سے ورے کام بنانے والے سو اللہ جو ہے وہ ہی ہے کام بنانے والا اور وہی جِلاتا ہے مُردوں کو اور وہ ہر چیز کر سکتا ہے [۹]', 'Or have they taken (for worship) Auliya (guardians, supporters, helpers, protectors, etc.) besides Him? But Allah, He Alone is the Walee (Protector, etc.). And it is He Who gives life to the dead, and He is Able to do all things.', 'Is it that they have adopted patrons instead of Him? So, it is Allah who is the Patron, and He gives life to the dead, and He is Powerful to do every thing.'),
(4282, 42, 10, 2, 3, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ مَا اخۡتَلَفۡتُمۡ فِیۡہِ مِنۡ شَیۡءٍ فَحُکۡمُہٗۤ اِلَی اللّٰہِ ؕ ذٰلِکُمُ اللّٰہُ رَبِّیۡ عَلَیۡہِ  تَوَکَّلۡتُ ٭ۖ وَ  اِلَیۡہِ  اُنِیۡبُ ﴿۱۰﴾', 'اور تم لوگ جس بات میں اختلاف کرتے ہو اس کا فیصلہ اللہ کی طرف سے ہوگا یہی اللہ میرا پروردگار ہے میں اسی پر بھروسہ رکھتا ہوں۔ اور اسی کی طرف رجوع کرتا ہوں۔', 'اور جس بات میں جھگڑا کرتے ہو تم لوگ کوئی چیز ہو اس کا فیصلہ ہے اللہ کے حوالے [۱۰] وہ اللہ ہے رب میرا اسی پر ہے مجھکو بھروسہ اور اسی کی طرف میری رجوع ہے [۱۱]', 'And in whatsoever you differ, the decision thereof is with Allah (He is the ruling Judge). (And say O Muhammad SAW to these polytheists:) Such is Allah, my Lord in Whom I put my trust, and to Him I turn in all of my affairs and in repentance.', 'And (Say O prophet to your opponents,) “Whatever dispute you have in any matter, its judgment lies with Allah. That One is Allah, the Lord of mine; in Him alone I have placed my trust, and to Him alone I turn (in every matter).”'),
(4283, 42, 11, 2, 3, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'فَاطِرُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ جَعَلَ لَکُمۡ مِّنۡ اَنۡفُسِکُمۡ  اَزۡوَاجًا وَّ مِنَ الۡاَنۡعَامِ اَزۡوَاجًا ۚ یَذۡرَؤُکُمۡ فِیۡہِ ؕ لَیۡسَ کَمِثۡلِہٖ  شَیۡءٌ ۚ وَ ہُوَ السَّمِیۡعُ الۡبَصِیۡرُ ﴿۱۱﴾', 'وہی ہے آسمانوں اور زمین کا پیدا کرنے والا۔ اسی نے تمہارے لئے تمہاری ہی جنس کے جوڑے بنائے اور چوپایوں کے بھی جوڑے بنائے وہ اسی طرح تمکو پھیلاتا رہتا ہے۔ اس جیسی تو کوئی چیز نہیں۔ اور وہ سنتا ہے دیکھتا ہے۔', 'بنا نکالنے والا  آسمانوں کا اور  زمین کا بنا دیے تمہارے واسطے تمہی میں سے جوڑے اور چوپایوں میں سے جوڑے [۱۲] بکھیرتا ہے تمکو اسی طرح [۱۳] نہیں ہے اس کی طرح کا سا کوئی [۱۴] اور وہی ہے سننے والا دیکھنے والا [۱۵]', 'The Creator of the heavens and the earth. He has made for you mates from yourselves, and for the cattle (also) mates. By this means He creates you (in the wombs). There is nothing like unto Him, and He is the All-Hearer, the All-Seer.', 'He is the Creator of the heavens and the earth. He has made for you pairs from among yourselves, and pairs from the cattle. He makes you expand in this way. Nothing is like Him. And He is the All-Hearing, the All-Seeing.'),
(4284, 42, 12, 2, 3, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'لَہٗ  مَقَالِیۡدُ السَّمٰوٰتِ وَ الۡاَرۡضِ ۚ یَبۡسُطُ الرِّزۡقَ لِمَنۡ یَّشَآءُ  وَ  یَقۡدِرُ ؕ اِنَّہٗ  بِکُلِّ  شَیۡءٍ عَلِیۡمٌ ﴿۱۲﴾', 'آسمانوں اور زمین کی کنجیاں اسی کے پاس ہیں۔ وہ جسکے لئے چاہتا ہے رزق فراخ کر دیتا ہے اور جسکے لئے چاہتا ہے تنگ کر دیتا ہے۔ بیشک وہ ہر چیز سے واقف ہے۔', 'اسی کے پاس ہیں کنجیاں آسمانوں کی اور زمین کی پھیلا دیتا ہے روزی جسکے واسطے چاہے اور ماپ کر دیتا ہے وہ ہر چیز کی خبر رکھتا ہے [۱۶]', 'To Him belong the keys of the heavens and the earth, He enlarges provision for whom He wills, and straitens (it for whom He wills). Verily! He is the All-Knower of everything.', 'To Him belong the keys of the heavens and the earth. He extends provision for whomsoever He wills, and straitens (it for whomsoever He wills). Surely He is All-Knowing in respect of every thing.'),
(4285, 42, 13, 2, 3, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'شَرَعَ  لَکُمۡ مِّنَ الدِّیۡنِ مَا وَصّٰی بِہٖ نُوۡحًا وَّ الَّذِیۡۤ  اَوۡحَیۡنَاۤ  اِلَیۡکَ وَ مَا وَصَّیۡنَا بِہٖۤ  اِبۡرٰہِیۡمَ  وَ مُوۡسٰی وَ عِیۡسٰۤی اَنۡ  اَقِیۡمُوا الدِّیۡنَ وَ لَا تَتَفَرَّقُوۡا فِیۡہِ ؕ  کَبُرَ عَلَی الۡمُشۡرِکِیۡنَ  مَا تَدۡعُوۡہُمۡ  اِلَیۡہِ ؕ اَللّٰہُ  یَجۡتَبِیۡۤ  اِلَیۡہِ مَنۡ  یَّشَآءُ وَ یَہۡدِیۡۤ  اِلَیۡہِ مَنۡ یُّنِیۡبُ ﴿۱۳﴾', 'اس نے تمہارے لئے دین کا وہی رستہ مقرر کیا جسکے اختیار کرنے کا حکم نوح کو دیا تھا اور جسکی اے نبی ہم نے تمہاری طرف وحی بھیجی ہے اور جس کا ابراہیم اور موسٰی اور عیسٰی کو حکم دیا تھا وہ یہ کہ دین کو قائم رکھنا اور اس میں پھوٹ نہ ڈالنا۔ جس چیز کی طرف تم مشرکوں کو بلاتے ہو وہ انکو ناگوار گذرتی ہے۔ اللہ جسکو چاہتا ہے اپنی بارگاہ میں برگزیدہ کر لیتا ہے اور جو اسکی طرف رجوع کرے اسے اپنی طرف کے رستے پر چلا دیتا ہے۔', 'راہ ڈالدی تمہارے لئے دین میں وہی جس کا حکم کیا تھا نوح کو اور جس کا حکم بھیجا ہم نے تیری طرف اور جس کا حکم کیا ہم نے ابراہیم کو اورموسٰی کو اور عیسٰی کو [۱۷] یہ کہ قائم رکھو دین کو اور اختلاف نہ ڈالو اس میں [۱۸] بھاری ہے شرک کرنے والوں کو وہ چیز جسکی طرف تو انکو بلاتا ہے اللہ چن لیتا ہے اپنی طرف سے جسکو چاہے اور راہ دیتا ہے اپنی طرف اس کو جو رجوع لائے [۱۹]', 'He (Allah) has ordained for you the same religion (Islam) which He ordained for Nooh (Noah), and that which We have inspired in you (O Muhammad SAW), and that which We ordained for Ibraheem (Abraham), Moosa (Mosesý) and Iesa (Jesus) saying you should establish religion (i.e. to do what it orders you to do practically), and make no divisions in it (religion) (i.e. various sects in religion). Intolerable for the Mushrikoon , is that to which you (O Muhammad SAW) call them. Allah chooses for Himself whom He wills, and guides unto Himself who turns to Him in repentance and in obedience.', 'He has ordained for you people the same religion as He had enjoined upon NūH, and that which We have revealed to you (O prophet,) and that which We had enjoined upon Ibrāhīm and Mūsā and ‘Īsā by saying, “Establish the religion, and be not divided therein.” Arduous for the mushriks (polytheists) is that to which you are inviting them. Allah chooses (and pulls) toward Himself anyone He wills, and guides to Himself anyone who turns to Him (to seek guidance).'),
(4286, 42, 14, 2, 3, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ مَا تَفَرَّقُوۡۤا  اِلَّا مِنۡۢ  بَعۡدِ مَا جَآءَہُمُ الۡعِلۡمُ بَغۡیًۢا بَیۡنَہُمۡ ؕ وَ لَوۡ لَا کَلِمَۃٌ سَبَقَتۡ مِنۡ رَّبِّکَ  اِلٰۤی  اَجَلٍ مُّسَمًّی لَّقُضِیَ  بَیۡنَہُمۡ ؕ وَ اِنَّ الَّذِیۡنَ اُوۡرِثُوا الۡکِتٰبَ مِنۡۢ  بَعۡدِہِمۡ لَفِیۡ شَکٍّ مِّنۡہُ مُرِیۡبٍ ﴿۱۴﴾', 'اور وہ لوگ جو الگ الگ ہو گئے تو علم حق آ چکنے کے بعد آپس کی ضد سے ہوئے اور اگر تمہارے پروردگار کی طرف سے ایک وقت مقرر تک کے لئے بات نہ ٹھہر چکی ہوتی تو ان میں فیصلہ کر دیا جاتا۔ اور جو لوگ انکے بعد اللہ کی کتاب کے وارث ہوئے وہ اسکی طرف سے بڑے بھاری شک میں ہیں۔', 'اور جنہوں نے اختلاف ڈالا سو سمجھ آ چکنے کے بعد آپس کی ضد سے اور اگر نہ ہوتی ایک بات جو نکلی ہے تیرے رب سے ایک مقررہ وعدہ تک تو فیصلہ ہو جاتا ان میں اور جنکو  ملی ہے کتاب ان کے پیچھے وہ البتہ اسکے دھوکے میں ہیں جو چین نہیں آنے دیتا [۲۰]', 'And they divided not till after knowledge had come to them, through selfish transgression between themselves. And had it not been for a Word that went forth before from your Lord for an appointed term, the matter would have been settled between them. And verily, those who were made to inherit the Scripture (i.e. the Taurah (Torah) and the Injeel (Gospel)) after them (i.e. Jews and Christians) are in grave doubt concerning it (i.e. Allahs true religion Islam or the Quran).', 'And they were not divided, in jealousy with each other, but after the knowledge had come to them. Had it not been for a word that had come forth earlier from your Lord (and was effective) until a specified time, the matter would have been decided between them. And those who were made to inherit the Book after them are in confounding doubt about it.'),
(4287, 42, 15, 2, 3, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'فَلِذٰلِکَ فَادۡعُ ۚ وَ اسۡتَقِمۡ  کَمَاۤ   اُمِرۡتَ ۚ وَ لَا تَتَّبِعۡ  اَہۡوَآءَہُمۡ ۚ وَ قُلۡ اٰمَنۡتُ بِمَاۤ  اَنۡزَلَ اللّٰہُ  مِنۡ  کِتٰبٍ ۚ وَ اُمِرۡتُ  لِاَعۡدِلَ بَیۡنَکُمۡ ؕ اَللّٰہُ  رَبُّنَا وَ رَبُّکُمۡ ؕ لَنَاۤ  اَعۡمَالُنَا وَ لَکُمۡ اَعۡمَالُکُمۡ ؕ لَا حُجَّۃَ  بَیۡنَنَا وَ بَیۡنَکُمۡ ؕ اَللّٰہُ  یَجۡمَعُ  بَیۡنَنَا ۚ وَ  اِلَیۡہِ  الۡمَصِیۡرُ ﴿ؕ۱۵﴾', 'تو اے نبی اسی دین کی طرف لوگوں کو بلاتے رہنا اور جیسا تمکو حکم ہوا ہے اسی پر قائم رہنا۔ اور انکی خواہشوں کی پیروی نہ کرنا۔ اور کہدو کہ جو کتاب اللہ نے نازل فرمائی ہے میں اس پر ایمان رکھتا ہوں۔ اور مجھے حکم ہوا ہے کہ تم میں انصاف کروں۔ اللہ ہی ہمارا اور تمہارا پروردگار ہے۔ ہمکو ہمارے اعمال کا بدلہ ملے گا اور تمکو تمہارے اعمال کا ہم میں اور تم میں کچھ بحث و تکرار نہیں۔ اللہ ہم سب کو اکٹھا کرے گا۔ اور اسی کی طرف لوٹ کر جانا ہے۔', 'سو تو اُسی طرف بلا اور قائم رہ جیسا کہ فرما دیا ہے تجھکو اور  مت چل انکی خواہشوں پر اور کہہ میں یقین لایا ہر کتاب پر جو اتاری اللہ نے اور مجھ کو حکم ہے کہ انصاف کروں تمہارے بیچ میں اللہ رب ہے ہمارا اور تمہارا ہم کو ملیں گے ہمارے کام اور تمکو  تمہارے کام کچھ جھگڑا نہیں ہم  میں اور تم میں اللہ اکٹھا کرے گا ہم سب کو اور اسی کی طرف پھر جانا ہے [۲۱]', 'So unto this (religion of Islam, alone and this Quran) then invite (people) (O Muhammad SAW), and Istaqim ((i.e. stand firm and straight on Islamic Monotheism by performing all that is ordained by Allah (good deeds, etc.), and by abstaining from all that is forbidden by Allah (sins and evil deeds, etc.)), as you are commanded, and follow not their desires but say: \"I believe in whatsoever Allah has sent down of the Book (all the holy Books, this Quran and the Books of the old from the Taurat (Torah), or the Injeel (Gospel) or the Pages of Ibrahim (Abraham)) and I am commanded to do justice among you, Allah is our Lord and your Lord. For us our deeds and for you your deeds. There is no dispute between us and you. Allah will assemble us (all), and to Him is the final return.', 'So, (O prophet,) towards that (faith) invite (people), and be steadfast as you are commanded, and do not follow their desires, and say, “I believe in whatever book Allah has sent down. And I have been ordered to do justice among you. Allah is our Lord and your Lord. For us are our deeds, and for you, your deeds. There is no argumentation between us and you. Allah will bring us together, and to Him is the final return.”'),
(4288, 42, 16, 2, 3, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ الَّذِیۡنَ یُحَآجُّوۡنَ فِی اللّٰہِ  مِنۡۢ  بَعۡدِ مَا اسۡتُجِیۡبَ لَہٗ  حُجَّتُہُمۡ  دَاحِضَۃٌ  عِنۡدَ رَبِّہِمۡ وَ عَلَیۡہِمۡ غَضَبٌ وَّ لَہُمۡ عَذَابٌ شَدِیۡدٌ ﴿۱۶﴾', 'اور جو لوگ اللہ کے بارے میں بعد اسکے کہ اسے مومنوں نے مان لیا ہو جھگڑتے ہیں انکے پروردگار کے نزدیک ان کا جھگڑا باطل ہے۔ اور ان پر اللہ کا غضب ہے اور ان کے لئے سخت عذاب ہے۔', 'اور جو لوگ جھگڑا ڈالتے ہیں اللہ کی بات میں جب لوگ اس کو مان چکے ان کا جھگڑا باطل ہے ان کے رب کے یہاں پر اور ان پر غصہ ہے اور انکو سخت عذاب ہے [۲۲]', 'And those who dispute concerning Allah (His Religion of Islamic Monotheism, with which Muhammad SAW has been sent), after it has been accepted (by the people), of no use is their dispute before their Lord, and on them is wrath, and for them will be a severe torment(1) .', 'Those who argue about Allah after He has been responded to, 5 their argument is void in the sight of their Lord, and upon them is wrath, and for them is a severe punishment.'),
(4289, 42, 17, 2, 3, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'اَللّٰہُ  الَّذِیۡۤ  اَنۡزَلَ الۡکِتٰبَ بِالۡحَقِّ وَ الۡمِیۡزَانَ ؕ وَ مَا یُدۡرِیۡکَ لَعَلَّ  السَّاعَۃَ قَرِیۡبٌ ﴿۱۷﴾', 'اللہ ہی تو ہے جس نے سچائی کے ساتھ یہ کتاب نازل کی اور عدل و انصاف کی ترازو بھی اور تمکو کیا معلوم شاید قیامت قریب ہی آ پہنچی ہو۔', 'اللہ وہی ہے جس نے اتاری کتاب سچے دین پر اور ترازو بھی [۲۳] اور تجھ کو کیا خبر ہے شاید وہ گھڑی پاس ہو [۲۴]', 'It is Allah Who has sent down the Book (the Quran) in truth, and the Balance (i.e. to act justly). And what can make you know that perhaps the Hour is close at hand?', 'Allah is the One who has sent down the Book with truth, and the Balance as well. And what can let you know? May be, the Hour (the Day of Judgment) is near.'),
(4290, 42, 18, 2, 3, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'یَسۡتَعۡجِلُ بِہَا الَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِہَا ۚ وَ الَّذِیۡنَ اٰمَنُوۡا مُشۡفِقُوۡنَ مِنۡہَا ۙ وَ یَعۡلَمُوۡنَ  اَنَّہَا الۡحَقُّ ؕ اَلَاۤ  اِنَّ  الَّذِیۡنَ یُمَارُوۡنَ فِی السَّاعَۃِ  لَفِیۡ ضَلٰلٍۭ بَعِیۡدٍ ﴿۱۸﴾', 'جو لوگ اس پر یعنی قیامت پر ایمان نہیں رکھتے وہ اسکے لئے جلدی مچا رہے ہیں۔ اور جو مومن ہیں وہ اس سے ڈرتے ہیں۔ اور جانتے ہیں کہ وہ یقینی ہے۔ دیکھو جو لوگ قیامت میں جھگڑتے ہیں وہ پرلے درجے کی گمراہی میں ہیں۔', 'جلدی کرتےہیں اس گھڑی کی وہ لوگ کہ یقین نہیں رکھتے اس پر اور جو یقین رکھتے ہیں انکو اس کا ڈر ہے اور جانتے ہیں کہ وہ ٹھیک ہے سنتا ہے جو لوگ جھگڑتے ہیں  اس گھڑی کے آنے میں وہ بہک کر دور جا پڑے [۲۵]', 'Those who believe not therein seek to hasten it, while those who believe are fearful of it, and know that it is the very truth. Verily, those who dispute concerning the Hour are certainly in error far away.', 'Those who do not believe in it demand that it should come soon, and those who believe are fearful of it, and they know for sure that it is the truth. Be aware that those who dispute concerning the Hour are wandering afar from the right path.'),
(4291, 42, 19, 2, 3, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'اَللّٰہُ  لَطِیۡفٌۢ  بِعِبَادِہٖ  یَرۡزُقُ مَنۡ  یَّشَآءُ ۚ وَ ہُوَ  الۡقَوِیُّ  الۡعَزِیۡزُ ﴿٪۱۹﴾', 'اللہ اپنے بندوں پر مہربان ہے وہ جسکو چاہتا ہے رزق دیتا ہے۔ اور وہ زورآور ہے غالب ہے۔', 'اللہ نرمی رکھتا ہے اپنے بندوں پر [۲۶] روزی دیتا ہے جس کو چاہے اور وہی ہے زورآور زبردست [۲۷]', 'Allah is very Gracious and Kind to His slaves. He gives provisions to whom He wills. And He is the All-Strong, the All-Mighty.', 'Allah is kind to His servants. He gives provision to whom He wills, and He is the Strong, the Mighty.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(4292, 42, 20, 3, 4, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'مَنۡ کَانَ یُرِیۡدُ حَرۡثَ الۡاٰخِرَۃِ  نَزِدۡ لَہٗ فِیۡ حَرۡثِہٖ ۚ وَ مَنۡ کَانَ یُرِیۡدُ حَرۡثَ الدُّنۡیَا نُؤۡتِہٖ  مِنۡہَا وَ مَا لَہٗ  فِی الۡاٰخِرَۃِ مِنۡ نَّصِیۡبٍ ﴿۲۰﴾', 'جو شخص آخرت کی کھیتی کا طالب ہو اسکے لئے ہم اسکی کھیتی میں اضافہ کریں گے۔ اور جو دنیا کی کھیتی کا طلبگار ہو اسکو ہم اسی میں سے کچھ دیں گے۔ اور اس کا آخرت میں کچھ حصہ نہ ہو گا۔', 'جو کوئی چاہتا ہو آخرت کی کھیتی زیادہ کریں ہم اسکے واسطے اسکی کھیتی  [۲۸] اور جو کوئی چاہتا ہو دنیا کی کھیتی اس کو دیویں ہم کچھ اس میں سے اور اسکے لئے نہیں آخرت میں کچھ حصہ [۲۹]', 'Whosoever desires (with his deeds) the reward of the Hereafter, We give him increase in his reward, and whosoever desires the reward of this world (with his deeds), We give him thereof (what is written for him), and he has no portion in the Hereafter.', 'Whoever intends (to have) the harvest of the Hereafter, We will increase in his harvest; and whoever intends (to have) the harvest of the world (only), We will give him thereof, while in the Hereafter he will have no share.'),
(4293, 42, 21, 3, 4, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'اَمۡ لَہُمۡ شُرَکٰٓؤُا شَرَعُوۡا  لَہُمۡ مِّنَ الدِّیۡنِ مَا لَمۡ یَاۡذَنۡۢ بِہِ اللّٰہُ ؕ وَ لَوۡ لَا کَلِمَۃُ  الۡفَصۡلِ لَقُضِیَ بَیۡنَہُمۡ ؕ وَ  اِنَّ الظّٰلِمِیۡنَ لَہُمۡ عَذَابٌ  اَلِیۡمٌ ﴿۲۱﴾', 'کیا انکے ایسے شریک ہیں جنہوں نے انکے لئے ایسا دین مقرر کیا ہے جس کا اللہ نے حکم نہیں دیا۔ اور اگر فیصلے کے دن کا وعدہ نہ ہوتا تو ان میں فیصلہ کر دیا جاتا۔ اور جو ظالم ہیں انکے لئے درد دینے والا عذاب ہے۔', 'کیا ان کے لئے اور شریک ہیں کہ راہ ڈالی ہے انہوں نے انکے واسطے دین کی کہ جس کا حکم نہیں دیا اللہ نے [۳۰] اور اگر نہ مقرر ہو چکی ہوتی ایک بات فیصلہ کی تو فیصلہ ہو جاتا ان میں اور  بیشک جو گنہگار ہیں انکو عذاب ہے دردناک [۳۱]', 'Or have they partners with Allah (false gods), who have instituted for them a religion which Allah has not allowed. And had it not been for a decisive Word (gone forth already), the matter would have been judged between them. And verily, for the Zalimoon (polytheists and wrong-doers), there is a painful torment.', 'Is it that they have associate-gods who have prescribed for them a religion that is not sanctioned by Allah? Had it not been for a decisive word, the matter would have been decided between them (here in this world). And of course, for the wrongdoers there is a painful punishment (in the Hereafter).'),
(4294, 42, 22, 3, 4, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'تَرَی الظّٰلِمِیۡنَ مُشۡفِقِیۡنَ مِمَّا کَسَبُوۡا وَ ہُوَ  وَاقِعٌۢ  بِہِمۡ ؕ وَ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ فِیۡ  رَوۡضٰتِ الۡجَنّٰتِ ۚ لَہُمۡ  مَّا یَشَآءُوۡنَ عِنۡدَ  رَبِّہِمۡ ؕ ذٰلِکَ  ہُوَ  الۡفَضۡلُ  الۡکَبِیۡرُ ﴿۲۲﴾', 'تم دیکھو گے کہ ظالم اپنے اعمال کے وبال سے ڈر رہے ہوں گے اور وہ ان پر پڑ کر رہے گا۔ اور جو لوگ ایمان لائے اور نیک عمل کرتے رہے وہ بہشت کے باغوں میں ہوں گے وہ جو کچھ چاہیں گے انکے پروردگار کے پاس موجود ہو گا۔ یہی بڑا فضل ہے۔', 'تو دیکھے گا گنہگاروں کو کہ ڈرتے ہوں گے اپنی کمائی سے اور وہ پڑ کر رہے گا ان پر [۳۲] اور  جو لوگ یقین لائے اور بھلے کام کئے باغوں میں ہیں جنت کے اور ان کے لئے ہے جو وہ چاہیں اپنے رب کے پاس یہی ہے بڑی بزرگی [۳۳]', 'You will see (on the Day of Resurrection), the Zalimoon (polytheists and wrong-doers, etc.) fearful of that which they have earned, and it (Allahs Torment) will surely befall them, while those who believe (in the Oneness of Allah Islamic Monotheism) and do righteous deeds (will be) in the flowering meadows of the Gardens (Paradise), having what they wish from their Lord. That is the supreme Grace, (Paradise).', 'You will see the wrongdoers fearful of what they earned, and it is sure to befall them. As for those who believed and did righteous deeds, they will be in meadows of the Gardens. For them there is, with their Lord, whatever they wish. That is the great bounty.'),
(4295, 42, 23, 3, 4, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'ذٰلِکَ الَّذِیۡ یُبَشِّرُ اللّٰہُ عِبَادَہُ  الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ ؕ قُلۡ  لَّاۤ اَسۡـَٔلُکُمۡ عَلَیۡہِ  اَجۡرًا  اِلَّا الۡمَوَدَّۃَ  فِی الۡقُرۡبٰی ؕ وَ مَنۡ یَّقۡتَرِفۡ حَسَنَۃً  نَّزِدۡ لَہٗ فِیۡہَا حُسۡنًا ؕ اِنَّ اللّٰہَ غَفُوۡرٌ شَکُوۡرٌ ﴿۲۳﴾', 'یہی وہ انعام ہے جسکی اللہ اپنے ان بندوں کو جو ایمان لاتے اور عمل نیک کرتے ہیں بشارت دیتا ہے۔ کہدو کہ میں اس کا تم سے کچھ صلہ نہیں مانگتا مگر تم کو قرابت کی محبت کا لحاظ تو چاہیے اور جو کوئی نیکی کرے گا ہم اسکے لئے اس میں ثواب بڑھائیں گے۔ بیشک اللہ بخشنے والا ہے قدردان ہے۔', 'یہ ہے جو خوشخبری دیتا ہے اللہ اپنے ایماندار بندوں کو جو کرتے ہیں بھلے کام [۳۴] تو کہہ میں مانگتا نہیں تم سے اس پر کچھ بدلا مگر دوستی چاہئے قرابت میں [۳۵] اور جو کوئی کمائے گا نیکی ہم اسکو بڑھا دیں گے اس کی خوبی بیشک اللہ معاف کرنے والا حق ماننے والا ہے [۳۶]', 'That is (the Paradise) whereof Allah gives glad tidings to His slaves who believe (in the Oneness of Allah Islamic Monotheism) and do righteous good deeds. Say (O Muhammad SAW): \"No reward do I ask of you for this except to be kind to me for my kinship with you.\" And whoever earns a good righteous deed, We shall give him an increase of good in respect thereof. Verily, Allah is Oft-Forgiving, Most Ready to appreciate (the deeds of those who are obedient to Him).', 'That is the good news that Allah gives to His servants who believed and did righteous deeds. Say, “I do not ask you any fee for it, except the love of kinship.” And whoever performs a good act, We will increase for him goodness therein. Surely Allah is Most-Forgiving, Very-Appreciative.'),
(4296, 42, 24, 3, 4, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'اَمۡ یَقُوۡلُوۡنَ  افۡتَرٰی عَلَی اللّٰہِ کَذِبًا ۚ فَاِنۡ  یَّشَاِ اللّٰہُ یَخۡتِمۡ عَلٰی قَلۡبِکَ ؕ وَ یَمۡحُ اللّٰہُ  الۡبَاطِلَ وَ یُحِقُّ الۡحَقَّ بِکَلِمٰتِہٖ ؕ اِنَّہٗ  عَلِیۡمٌۢ  بِذَاتِ  الصُّدُوۡرِ ﴿۲۴﴾', 'کیا یہ لوگ یہ کہتے ہیں کہ پیغمبر نے اللہ پر جھوٹ باندھ لیا ہے؟ اگر اللہ چاہے تو اے نبی تمہارے دل پر مہر لگا دے۔ اور اللہ جھوٹ کو نابود کرتا ہے اور اپنی باتوں سے حق کو ثابت کرتا ہے۔ بیشک وہ دلوں کی باتوں تک سے واقف ہے۔', 'کیا وہ کہتے ہیں کہ اس نے باندھا اللہ پر جھوٹ سو اگراللہ چاہے مہر کر دے تیرے دل پر اور مٹاتا ہے اللہ جھوٹ کو اور ثابت کرتا ہے سچ کو اپنی باتوں سے اُس کو معلوم ہے جو دلوں میں ہے [۳۷]', 'Or say they: \"He has invented a lie against Allah?\" If Allah willed, He could have sealed your heart (so that you forget all that you know of the Quran). And Allah wipes out falsehood, and establishes the truth (Islam) by His Word (this Quran). Verily, He knows well what (the secrets) are in the breasts (of mankind).', 'Is it that they say, “He has forged a lie against Allah”? So, if Allah wills, He may put a seal on your heart. And Allah blots out falsehood and establishes truth with His words. Surely, He is fully aware of what lies in the hearts.'),
(4297, 42, 25, 3, 4, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ ہُوَ الَّذِیۡ یَقۡبَلُ  التَّوۡبَۃَ  عَنۡ عِبَادِہٖ وَ یَعۡفُوۡا عَنِ السَّیِّاٰتِ وَ  یَعۡلَمُ مَا تَفۡعَلُوۡنَ ﴿ۙ۲۵﴾', 'اور وہی تو ہے جو اپنے بندوں کی توبہ قبول کرتا ہے اور انکے قصور معاف فرماتا ہے اور جو کچھ تم کرتے ہو وہ جانتا ہے۔', 'اور وہی ہے جو قبول کرتا ہے توبہ اپنے بندوں کی اور معاف کرتا ہے برائیاں  اور جانتا ہے جو کچھ تم کرتے ہو', 'And He it is Who accepts repentance from His slaves, and forgives sins, and He knows what you do.', 'And He is the One who accepts repentance from His servants and forgives evil deeds and knows whatever you do.'),
(4298, 42, 26, 3, 4, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ یَسۡتَجِیۡبُ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ وَ یَزِیۡدُہُمۡ مِّنۡ فَضۡلِہٖ ؕ وَ الۡکٰفِرُوۡنَ  لَہُمۡ  عَذَابٌ  شَدِیۡدٌ ﴿۲۶﴾', 'اور جو لوگ ایمان لائے اور عمل نیک کرتے رہے انکی دعا قبول فرماتا اور انکو اپنے فضل سے مزید عطا کرتا ہے۔ اور جو کافر ہیں انکے لئے سخت عذاب ہے۔', 'اور دعا سنتا ہے ایمان والوں کی جو بھلے کام کرتے ہیں اور زیادہ دیتا ہے اُنکو اپنے فضل سے [۳۸] اور جو منکر ہیں ان کے لئے سخت عذاب ہے', 'And He answers (the invocation of) those who believe (in the Oneness of Allah Islamic Monotheism) and do righteous good deeds, and gives them increase of His Bounty. And as for the disbelievers, theirs will be a severe torment.', 'And He responds to (the prayer of) those who believe and do righteous deeds, and gives them more out of His grace. As for the disbelievers, for them there is a severe punishment.'),
(4299, 42, 27, 3, 4, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ لَوۡ بَسَطَ اللّٰہُ  الرِّزۡقَ لِعِبَادِہٖ لَبَغَوۡا فِی الۡاَرۡضِ وَ لٰکِنۡ یُّنَزِّلُ بِقَدَرٍ مَّا یَشَآءُ ؕ اِنَّہٗ  بِعِبَادِہٖ  خَبِیۡرٌۢ   بَصِیۡرٌ ﴿۲۷﴾', 'اور اگر اللہ اپنے سب بندوں کے لئے رزق میں فراخی کر دیتا تو وہ زمین میں فساد کرنے لگتے۔ لیکن وہ جس قدر چاہتا ہے اندازے کے ساتھ نازل کرتا ہے۔ بیشک وہ اپنے بندوں کو جانتا ہے دیکھتا ہے۔', 'اور اگر پھیلا دے اللہ روزی اپنے بندوں کو تو دھوم اٹھا دیں ملک میں ولیکن اتارتا ہے ماپ کر جتنی چاہتا ہے بیشک وہ اپنے بندوں کی خبر رکھتا ہے دیکھتا ہے [۳۹]', 'And if Allah were to enlarge the provision for His slaves, they would surely rebel in the earth, but He sends down by measure as He wills. Verily! He is in respect of His slaves, the Well-Aware, the All-Seer (of things that benefit them).', 'Should Allah expand the provision for His servants (to its full extent), they would spread mischief on earth; but He sends down what He wills in (due) measure. Surely, with regard to His slaves, He is All-Aware, Ever-Watchful.'),
(4300, 42, 28, 3, 4, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ ہُوَ الَّذِیۡ یُنَزِّلُ  الۡغَیۡثَ مِنۡۢ  بَعۡدِ مَا قَنَطُوۡا وَ یَنۡشُرُ  رَحۡمَتَہٗ ؕ وَ ہُوَ  الۡوَلِیُّ الۡحَمِیۡدُ ﴿۲۸﴾', 'اور وہی تو ہے جو لوگوں کے ناامید ہو جانے کے بعد مینہ برساتا اور اپنی رحمت یعنی بارش کی برکت کو پھیلا دیتا ہے۔ اور وہ کارساز ہے لائق حمدوثنا ہے۔', 'اور وہی ہے جو اتارتا ے مینہ بعد اسکے کہ آس توڑ چکے اور پھیلاتا ہے اپنی رحمت اور وہی ہے کام بنانے والا سب تعریفوں کے لائق [۴۰]', 'And He it is Who sends down the rain after they have despaired, and spreads abroad His Mercy. And He is the Walee (Helper, Supporter, Protector, etc.), Worthy of all Praise.', 'And He is the One who sends down rain after they have lost hope, and He extends His mercy. And He is the Guardian, Worthy of all praise.'),
(4301, 42, 29, 3, 4, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ مِنۡ اٰیٰتِہٖ خَلۡقُ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ مَا بَثَّ فِیۡہِمَا مِنۡ دَآبَّۃٍ ؕ وَ ہُوَ  عَلٰی جَمۡعِہِمۡ   اِذَا  یَشَآءُ  قَدِیۡرٌ ﴿٪۲۹﴾', 'اور اسی کی نشانیوں میں سے ہے آسمانوں اور زمین کا پیدا کرنا اور ان جانوروں کا جو اس نے ان میں پھیلا رکھے ہیں۔ اور وہ جب چاہے انکے جمع کر لینے پر قادر بھی ہے۔', 'اور ایک اسکی نشانی ہے بنانا آسمانوں کا اور زمین کا [۴۱] اور جس قدر بکھیرے ہیں ان میں جانور [۴۲] اور وہ جب چاہے اُن سب کو اکٹھا کر سکتا ہے [۴۳]', 'And among His Ayat (proofs, evidences, lessons, signs, etc.) is the creation of the heavens and the earth, and whatever moving (living) creatures He has dispersed in them both. And He is All-Potent over their assembling (i.e. resurrecting them on the Day of Resurrection after their death, and dispersion of their bodies) whenever He will.', 'Among His signs is the creation of the heavens and the earth and the creatures He has spread in them. He is Powerful to assemble them whenever He so wills.'),
(4302, 42, 30, 4, 5, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ مَاۤ  اَصَابَکُمۡ مِّنۡ مُّصِیۡبَۃٍ  فَبِمَا کَسَبَتۡ اَیۡدِیۡکُمۡ وَ یَعۡفُوۡا عَنۡ کَثِیۡرٍ ﴿ؕ۳۰﴾', 'اور جو مصیبت تم پر واقع ہوتی ہے سو تمہارے اپنے کرتوتوں سے اور وہ بہت سے گناہ تو معاف کر دیتا ہے۔', 'اور جو پڑے تم پر کوئی سختی سو وہ بدلا ہے اس کا جو کمایا تمہارے ہاتھوں نے اور معاف کرتا ہے بہت سے گناہ [۴۴]', 'And whatever of misfortune befalls you, it is because of what your hands have earned. And He pardons much. (See the Quran Verse 35:45).', 'Whatever hardship befalls you is because of what your own hands have committed, while He overlooks many (of your faults).'),
(4303, 42, 31, 4, 5, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ مَاۤ  اَنۡتُمۡ بِمُعۡجِزِیۡنَ فِی الۡاَرۡضِ ۚۖ وَ مَا لَکُمۡ مِّنۡ دُوۡنِ اللّٰہِ مِنۡ وَّلِیٍّ وَّ لَا نَصِیۡرٍ ﴿۳۱﴾', 'اور تم زمین میں اللہ کو عاجز نہیں کر سکتے۔ اور اللہ کے سوا نہ تمہارا کوئی دوست ہے اور نہ مددگار۔', 'اور تم تھکا دینے والے نہیں بھاگ کر زمین میں اور کوئی نہیں تمہارا اللہ کے سوائے کام بنانے والا اور نہ مددگار [۴۵]', 'And you cannot escape from Allah (i.e. His Punishment) in the earth, and besides Allah you have neither any Walee (guardian or a protector) nor any helper.', 'You are not able to frustrate (Him) in the earth. And, besides Allah, you have neither someone to protect, nor someone to help.'),
(4304, 42, 32, 4, 5, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ مِنۡ اٰیٰتِہِ  الۡجَوَارِ فِی الۡبَحۡرِ کَالۡاَعۡلَامِ ﴿ؕ۳۲﴾', 'اور اسی کی نشانیوں میں سے سمندر میں چلنے والے جہاز ہیں پہاڑوں جیسے۔', 'اور ایک اُسکی نشانی ہے کہ جہاز چلتے ہیں دریا میں جیسے  پہاڑ [۴۶]', 'And among His Signs are the ships, in the sea, like mountains.', 'And among His signs are ships in the sea, like mountains.'),
(4305, 42, 33, 4, 5, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'اِنۡ یَّشَاۡ یُسۡکِنِ الرِّیۡحَ فَیَظۡلَلۡنَ رَوَاکِدَ عَلٰی ظَہۡرِہٖ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیٰتٍ  لِّکُلِّ  صَبَّارٍ  شَکُوۡرٍ ﴿ۙ۳۳﴾', 'اگر اللہ چاہے تو ہوا کو ٹھہرا دے۔ کہ جہاز اسکی سطح پر کھڑے رہ جائیں۔ ہر صبر اور شکر کرنے والوں کے لئے ان باتوں میں قدرت کے نمونے ہیں۔', 'اگر چاہے تو تھام دے ہوا کو پھر رہیں سارے دن ٹھہرے ہوئے اس کی پیٹھ پر [۴۷] مقرر اس بات میں پتے ہیں ہر قائم رہنے والے کو جو احسان مانے [۴۸]', 'If He wills, He causes the wind to cease, then they would become motionless on the back (of the sea). Verily, in this are signs for everyone patient and grateful.', 'If He so wills, He may stop the wind, and they stand still on its surface. Surely in this, there are signs for everyone who is ever patient, fully grateful.'),
(4306, 42, 34, 4, 5, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'اَوۡ یُوۡبِقۡہُنَّ بِمَا کَسَبُوۡا وَ یَعۡفُ عَنۡ  کَثِیۡرٍ ﴿۫۳۴﴾', 'یا انکے اعمال کے سبب انکو تباہ کر دے اور بہت سوں کو معاف بھی کر دے۔', 'یا تباہ کر دے انکو بسبب اُنکی کمائی کے اور معاف بھی کرے بہتوں کو [۴۹]', 'Or He may destroy them (by drowning) because of that which their (people) have earned. And He pardons much.', 'Or He may destroy them because of what they earned, and may overlook many (whom He may save at least in this world),'),
(4307, 42, 35, 4, 5, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَّ یَعۡلَمَ الَّذِیۡنَ یُجَادِلُوۡنَ فِیۡۤ  اٰیٰتِنَا ؕ مَا لَہُمۡ مِّنۡ مَّحِیۡصٍ ﴿۳۵﴾', 'اور سزا اسلئے دی جائے کہ جو لوگ ہماری آیتوں میں جھگڑتے ہیں وہ جان لیں کہ انکے لئے کوئی جائے فرار نہیں۔', 'اور تاکہ جان لیں وہ جو جھگڑتے ہیں ہماری قدرتوں میں کہ نہیں اُنکے لئے بھاگنے کی جگہ [۵۰]', 'And those who dispute (polytheists, etc. with Our Messenger Muhammad SAW) as regards Our Ayat (proofs, signs, verses, etc. of Islamic Monotheism) may know that there is no place of refuge for them (from Allahs punishment).', 'and (in such an event) those who raise disputes in Our verses will come to know that there is no way for them to escape.'),
(4308, 42, 36, 4, 5, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'فَمَاۤ  اُوۡتِیۡتُمۡ مِّنۡ شَیۡءٍ فَمَتَاعُ الۡحَیٰوۃِ  الدُّنۡیَا ۚ وَ مَا عِنۡدَ اللّٰہِ خَیۡرٌ وَّ اَبۡقٰی لِلَّذِیۡنَ اٰمَنُوۡا وَ عَلٰی رَبِّہِمۡ یَتَوَکَّلُوۡنَ ﴿ۚ۳۶﴾', 'لوگو جو مال و متاع تم کو دیا گیا ہے وہ دنیا کی زندگی کا ناپائیدار فائدہ ہے اور جو کچھ اللہ کے ہاں ہے وہ بہتر اور باقی رہنے والا ہے یعنی ان لوگوں کے لئے جو ایمان لائے اور اپنے پروردگار پر بھروسہ رکھتے ہیں۔', 'سو جو چکھ ملا ہے تمکو کوئی چیز ہو سو وہ برت لینا ہے دنیا کی زندگانی میں اورجو کچھ اللہ کے یہاں ہے بہتر ہے اور باقی رہنے والا واسطے ایمان والوں کے جو اپنے رب پر بھروسہ رکھتے ہیں [۵۱]', 'So whatever you have been given is but a passing enjoyment for this worldly life, but that which is with Allah (Paradise) is better and more lasting for those who believe (in the Oneness of Allah Islamic Monotheism) and put their trust in their Lord (concerning all of their affairs).', 'So, whatever thing has been given to you is an enjoyment of the worldly life. And that which is with Allah is much better, and much more durable for those who believe and place their trust in Allah,'),
(4309, 42, 37, 4, 5, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ الَّذِیۡنَ یَجۡتَنِبُوۡنَ کَبٰٓئِرَ الۡاِثۡمِ وَ الۡفَوَاحِشَ وَ اِذَا مَا غَضِبُوۡا ہُمۡ یَغۡفِرُوۡنَ ﴿ۚ۳۷﴾', 'اور جو بڑے بڑے گناہوں اور بےحیائی کے کاموں سے پرہیز کرتے ہیں اور جب غصہ آتا ہے تو معاف کر دیتے ہیں۔', 'اور جو لوگ کہ بچتے ہیں بڑے گناہوں سے اور بیحیائی سے اور جب غصہ آوے تو  وہ معاف کر دیتے ہیں [۵۲]', 'And those who avoid the greater sins, and Al-Fawahish (illegal sexual intercourse, etc.), and when they are angry, they forgive', 'and (for) those who abstain from the major sins and from shameful acts; and (for those who) when they get angry, they forgive,'),
(4310, 42, 38, 4, 5, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ الَّذِیۡنَ اسۡتَجَابُوۡا لِرَبِّہِمۡ وَ اَقَامُوا الصَّلٰوۃَ ۪ وَ اَمۡرُہُمۡ شُوۡرٰی بَیۡنَہُمۡ ۪ وَ مِمَّا رَزَقۡنٰہُمۡ  یُنۡفِقُوۡنَ ﴿ۚ۳۸﴾', 'اور جو اپنے پروردگار کا فرمان قبول کرتے ہیں اور نماز پڑھتے ہیں۔ اور اپنے کام آپس کے مشورے سے کرتے ہیں۔ اور جو مال ہم نے انکو عطا فرمایا ہے اس میں سے خرچ کرتے ہیں۔', 'اور جنہوں نے کہ حکم مانا اپنے رب کا اور قائم کیا نماز کو اور کام کرتے ہیں مشورہ سے آپس کے [۵۳] اور ہمارا دیا کچھ خرچ کرتے ہیں', 'And those who answer the Call of their Lord (i.e. to believe that He is the only One Lord (Allah), and to worship none but Him Alone), and perform As-Salat (Iqamat-as-Salat), and who (conduct) their affairs by mutual consultation, and who spend of what We have bestowed on them;', 'and those who have responded to their Lord (in submission to Him), and have established Salāh, and whose affairs are (settled) with mutual consultation between them, and who spend out of what We have given to them,'),
(4311, 42, 39, 4, 5, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ الَّذِیۡنَ  اِذَاۤ  اَصَابَہُمُ  الۡبَغۡیُ ہُمۡ یَنۡتَصِرُوۡنَ ﴿۳۹﴾', 'اور جو ایسے ہیں کہ جب ان پر ظلم و زیادتی ہو تو مناسب طریقے سے بدلہ بھی لیتے ہیں۔', 'اور وہ لوگ کہ جب ان پر ہووے چڑھائی تو وہ بدلا لیتے ہیں [۵۴]', 'And those who, when an oppressive wrong is done to them, they take revenge.', 'and those who, when they are subjected to aggression, defend themselves.'),
(4312, 42, 40, 4, 5, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ جَزٰٓؤُا سَیِّئَۃٍ  سَیِّئَۃٌ  مِّثۡلُہَا ۚ فَمَنۡ عَفَا وَ اَصۡلَحَ  فَاَجۡرُہٗ  عَلَی اللّٰہِ ؕ اِنَّہٗ  لَا یُحِبُّ الظّٰلِمِیۡنَ ﴿۴۰﴾', 'اور برائی کا بدلہ تو اسی طرح کی برائی ہے۔ مگر جو درگذر کرے اور معاملے کو درست کر دے تو اس کا بدلہ اللہ کے ذمے ہے۔ اس میں شک نہیں کہ وہ ظلم کرنے والوں کو پسند نہیں فرماتا۔', 'اور برائی کا بدلا ہے برائی  ویسی ہی [۵۵] پھر جو کوئی معاف کرے اور صلح کرے سو  اس کا ثواب ہے اللہ کے ذمہ بیشک اللہ کو  پسند نہیں آتے گنہگار [۵۶]', 'The recompense for an evil is an evil like thereof, but whoever forgives and makes reconciliation, his reward is due from Allah. Verily, He likes not the Zalimoon (oppressors, polytheists, and wrong-doers, etc.).', 'The recompense of evil is evil like it. Then the one who forgives and opts for compromise has his reward undertaken by Allah. Surely, He does not like the unjust.'),
(4313, 42, 41, 4, 5, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ لَمَنِ انۡتَصَرَ  بَعۡدَ ظُلۡمِہٖ فَاُولٰٓئِکَ مَا عَلَیۡہِمۡ  مِّنۡ سَبِیۡلٍ ﴿ؕ۴۱﴾', 'اور جس پر ظلم ہوا ہو اگر وہ اسکے بعد انتقام لے لے تو ایسے لوگوں پر کچھ الزام نہیں۔', 'اور جو کوئی بدلہ لے اپنے مظلوم ہونے کے بعد سو ان پر بھی نہیں کچھ الزام [۵۷]', 'And indeed whosoever takes revenge after he has suffered wrong, for such there is no way (of blame) against them.', 'The one who defends himself after having been wronged, there is no blame on such people.'),
(4314, 42, 42, 4, 5, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'اِنَّمَا السَّبِیۡلُ عَلَی الَّذِیۡنَ یَظۡلِمُوۡنَ النَّاسَ وَ یَبۡغُوۡنَ فِی الۡاَرۡضِ بِغَیۡرِ الۡحَقِّ ؕ اُولٰٓئِکَ  لَہُمۡ عَذَابٌ  اَلِیۡمٌ ﴿۴۲﴾', 'الزام تو ان لوگوں پر ہے جو لوگوں پر ظلم کرتے ہیں اور ملک میں ناحق فساد پھیلاتے ہیں۔ یہی لوگ ہیں جنکو تکلیف دینے والا عذاب ہو گا۔', 'الزام تو ان پر ہے جو ظلم کرتے ہیں لوگوں پر [۵۸] اور دھوم اٹھاتے ہیں ملک میں ناحق ان لوگوں کے لئے ہے عذاب دردناک', 'The way (of blame) is only against those who oppress men and wrongly rebel in the earth, for such there will be a painful torment.', 'Blame, in fact, is upon those who wrong people and make mischief on earth unjustly. For such people there is a painful punishment.'),
(4315, 42, 43, 4, 5, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ لَمَنۡ صَبَرَ  وَ غَفَرَ اِنَّ  ذٰلِکَ لَمِنۡ عَزۡمِ  الۡاُمُوۡرِ ﴿٪۴۳﴾', 'اور جو صبر کرے اور قصور معاف کر دے تو یہ بڑی ہمت کے کام ہیں۔', 'اور البتہ جس نے سہا اور معاف کیا بیشک یہ کام ہمت کے ہیں [۵۹]', 'And verily, whosoever shows patience and forgives that would truly be from the things recommended by Allah.', 'And if one observes patience and forgives, it is, of course, one of the courageous conducts.'),
(4316, 42, 44, 5, 6, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ مَنۡ یُّضۡلِلِ اللّٰہُ  فَمَا لَہٗ  مِنۡ وَّلِیٍّ مِّنۡۢ بَعۡدِہٖ ؕ وَ تَرَی الظّٰلِمِیۡنَ لَمَّا رَاَوُا الۡعَذَابَ یَقُوۡلُوۡنَ ہَلۡ  اِلٰی مَرَدٍّ  مِّنۡ سَبِیۡلٍ ﴿ۚ۴۴﴾', 'اور جس شخص کو اللہ گمراہ رہنے دے تو اسکے بعد اسکا کوئی دوست نہیں۔ اور تم ظالموں کو دیکھو گے کہ جب وہ دوزخ کا عذاب دیکھیں گے تو کہیں گے کیا دنیا میں واپس جانے کی کوئی سبیل ہے؟', 'اور جسکو راہ نہ سجھائے اللہ تو کوئی نہیں اسکا کام بنانے والا اسکے سوا [۶۰] اور تو دیکھے گنہگاروں کو جس وقت دیکھیں گے عذاب کہیں گے کسی طرح پھر جانے کی بھی ہو گی کوئی راہ [۶۱]', 'And whomsoever Allah sends astray, for him there is no Walee (protector) after Him. And you will see the Zalimoon (polytheists, wrong-doers, oppressors, etc.) when they behold the torment, they will say: \"Is there any way of return (to the world)?\"', 'The one whom Allah lets go astray, there is no one for him to protect thereafter. And you will see the wrongdoers, when they will see the punishment, that they will say, “Is there any way to be sent back (to the world)? ”'),
(4317, 42, 45, 5, 6, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ تَرٰىہُمۡ  یُعۡرَضُوۡنَ عَلَیۡہَا خٰشِعِیۡنَ مِنَ الذُّلِّ یَنۡظُرُوۡنَ مِنۡ طَرۡفٍ خَفِیٍّ ؕ وَ قَالَ الَّذِیۡنَ  اٰمَنُوۡۤا  اِنَّ الۡخٰسِرِیۡنَ الَّذِیۡنَ خَسِرُوۡۤا  اَنۡفُسَہُمۡ وَ اَہۡلِیۡہِمۡ یَوۡمَ الۡقِیٰمَۃِ ؕ اَلَاۤ  اِنَّ  الظّٰلِمِیۡنَ فِیۡ عَذَابٍ مُّقِیۡمٍ ﴿۴۵﴾', 'اور تم انکو دیکھو گے کہ دوزخ کے سامنے لائے جائیں گے ذلت سے عاجزی کرتے ہوئے چھپی نگاہ سے دیکھ رہے ہوں گے۔ اور مومن لوگ کہیں گے کہ گھاٹے میں رہنے والے تو وہ ہیں جنہوں نے قیامت کے دن اپنے آپ کو اور اپنے گھر والوں کو خسارے میں ڈالا۔ دیکھو کہ بےانصاف لوگ ہمیشہ کے دکھ میں پڑے رہیں گے۔', 'اور تو دیکھے انکو کہ سامنے لائے جائیں آگ کے  آنکھیں جھکائے ہوئے ذلت سے دیکھتے ہوں گے چھپی نگاہ سے [۶۲] اور کہیں وہ لوگ جو ایماندار تھے مقرر ٹوٹے والے وہی ہیں جنہوں نے گنوایا اپنی جان کو  اور اپنے گھر والوں کو قیامت کے دن [۶۳] سنتا ہے گنہگار پڑے ہیں سدا کے عذاب میں', 'And you will see them brought forward to it (Hell) made humble by disgrace , (and) looking with stealthy glance. And those who believe will say: \"Verily, the losers are they who lose themselves and their families on the Day of Resurrection. Verily, the Zalimoon (i.e. Al-Kafiroon (disbelievers in Allah, in His Oneness and in His Messenger SAW , polytheists, wrong-doers, etc.)) will be in a lasting torment.', 'And you will see them that they will be presented to it (the Fire), downcast because of humiliation, looking with stealthy glance. And those who believe will say, “The real losers are those who have lost their own selves and their families on the Day of Judgment.” Be aware that the wrongdoers are in lasting punishment.'),
(4318, 42, 46, 5, 6, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ مَا کَانَ لَہُمۡ  مِّنۡ اَوۡلِیَآءَ یَنۡصُرُوۡنَہُمۡ  مِّنۡ دُوۡنِ اللّٰہِ ؕ وَ مَنۡ  یُّضۡلِلِ اللّٰہُ  فَمَا لَہٗ  مِنۡ سَبِیۡلٍ ﴿ؕ۴۶﴾', 'اور اللہ کے سوا انکے کوئی دوست نہ ہوں گے کہ اللہ کے سوا انکو مدد دے سکیں۔ اور جسکو اللہ گمراہ رہنے دے اسکے لئے ہدایت کا کوئی رستہ نہیں۔', 'اور کوئی نہ ہوئے انکے حمایتی جو مدد کرتے انکی اللہ کے سوائے  اور جسکو  بھٹکائے اللہ اسکے لئے کہیں نہیں راہ [۶۴]', 'And they will have no Auliya (protectors) to help them other than Allah. And he whom Allah sends astray, for him there is no way.', 'And for them there will not be any friends who may help them besides Allah. And the one whom Allah lets go astray, for him there is no way (to save himself).'),
(4319, 42, 47, 5, 6, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'اِسۡتَجِیۡبُوۡا لِرَبِّکُمۡ مِّنۡ قَبۡلِ اَنۡ یَّاۡتِیَ یَوۡمٌ لَّا مَرَدَّ  لَہٗ  مِنَ اللّٰہِ ؕ مَا لَکُمۡ مِّنۡ مَّلۡجَاٍ  یَّوۡمَئِذٍ وَّ مَا لَکُمۡ مِّنۡ نَّکِیۡرٍ ﴿۴۷﴾', 'ان سے کہدو کہ قبل اسکے کہ وہ دن جو ٹلے گا نہیں اللہ کی طرف سے آ موجود ہو اپنے پروردگار کا حکم قبول کر لو۔ اس دن تمہارے لئے نہ کوئی جائے پناہ ہو گی اور نہ تم سے گناہوں کا انکار ہی بن پڑے گا۔', 'مانو اپنے رب کا حکم اُس سے پہلے کہ آئے وہ دن جسکو  پھرنا نہیں اللہ کے یہاں سے [۶۵] نہیں ملے گا تمکو بچاؤ اُس  دن اور نہیں تمہاری طرف سے کوئی انکار کرنے والا [۶۶]', 'Answer the Call of your Lord (i.e. accept the Islamic Monotheism, O mankind, and jinns) before there comes from Allah a Day which cannot be averted. You will have no refuge on that Day nor there will be for you any denying (of your crimes as they are all recorded in the Book of your deeds).', 'Respond to your Lord before there comes a day for which there will be no reversal from Allah’s side. For you there will be neither a refuge that day, nor an opportunity to question (Allah about your fate).'),
(4320, 42, 48, 5, 6, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'فَاِنۡ  اَعۡرَضُوۡا فَمَاۤ  اَرۡسَلۡنٰکَ عَلَیۡہِمۡ حَفِیۡظًا ؕ اِنۡ عَلَیۡکَ اِلَّا الۡبَلٰغُ ؕ وَ اِنَّاۤ اِذَاۤ  اَذَقۡنَا الۡاِنۡسَانَ مِنَّا رَحۡمَۃً  فَرِحَ بِہَا ۚ وَ اِنۡ تُصِبۡہُمۡ سَیِّئَۃٌۢ  بِمَا قَدَّمَتۡ اَیۡدِیۡہِمۡ  فَاِنَّ  الۡاِنۡسَانَ  کَفُوۡرٌ ﴿۴۸﴾', 'پھر اگر یہ منہ پھیر لیں تو ہم نے تمکو ان پر نگہبان بنا کر نہیں بھیجا تمہارا کام تو صرف احکام کا پہنچا دینا ہے۔ اور جب ہم انسان کو اپنی رحمت کا مزہ چکھاتے ہیں تو وہ اس سے خوش ہو جاتا ہے۔ اور اگر انکو انہی کے اعمال کے سبب کوئی سختی پہنچتی ہے تو سب احسانوں کو بھول جاتا ہے بیشک انسان بڑا ناشکرا ہے۔', 'پھر اگر وہ منہ پھیریں تو تجھ کو نہیں بھیجا ہم نے ان پر نگہبان تیرا ذمہ تو بس یہی ہے پہنچا دینا [۶۷] اور ہم جب چکھاتے ہیں آدمی کو اپنی طرف سے رحمت اس پر پھولا نہیں سماتا اور اگر پہنچتی ہے انکو کچھ برائی بدلے میں اپنی کمائی کے تو انسان بڑا ناشکرا ہے [۶۸]', 'But if they turn away (O Muhammad SAW from the Islamic Monotheism, which you have brought to them). We have not sent you (O Muhammad SAW) as a Hafeez (protector) over them (i.e. to take care of their deeds and to recompense them). Your duty is to convey (the Message). And verily, when We cause man to taste of Mercy from Us, he rejoices thereat, but when some ill befalls them because of the deeds which their hands have sent forth, then verily, man (becomes) ingrate!', 'So, if they turn away, then We did not send you (O Prophet,) as a supervisor over them. You are not responsible but for conveying the message. And when We make man taste mercy from Us, he rejoices with it, and if an evil befalls him because of what their hands sent ahead, then man becomes ungrateful.'),
(4321, 42, 49, 5, 6, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'لِلّٰہِ مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ یَخۡلُقُ مَا یَشَآءُ ؕیَہَبُ لِمَنۡ یَّشَآءُ  اِنَاثًا وَّ یَہَبُ  لِمَنۡ  یَّشَآءُ   الذُّکُوۡرَ ﴿ۙ۴۹﴾', 'تمام بادشاہت اللہ ہی کی ہے آسمانوں کی بھی اور زمین کی بھی وہ جو چاہتا ہے پیدا کرتا ہے جسے چاہتا ہے بیٹیاں عطا کرتا ہے اور جسے چاہتا ہے بیٹے بخشتا ہے۔', 'اللہ کا راج ہے آسمانوں میں اور زمین میں پیدا کرتا ہے جو چاہے بخشتا ہے جسکو چاہے بیٹیاں اور بخشتا ہے جسکو چاہے بیٹے۔', 'To Allah belongs the kingdom of the heavens and the earth. He creates what He wills. He bestows female (offspring) upon whom He wills, and bestows male (offspring) upon whom He wills.', 'To Allah belongs the kingdom of the heavens and the earth. He creates what He wills. He grants females to whom He wills, and grants males to whom He wills.'),
(4322, 42, 50, 5, 6, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'اَوۡ یُزَوِّجُہُمۡ ذُکۡرَانًا وَّ اِنَاثًا ۚ وَ یَجۡعَلُ مَنۡ  یَّشَآءُ  عَقِیۡمًا ؕ اِنَّہٗ  عَلِیۡمٌ  قَدِیۡرٌ ﴿۵۰﴾', 'یا انکو بیٹے اور بیٹیاں دونوں عنایت فرماتا ہے اور جسکو چاہتا ہے بے اولاد رکھتا ہے۔ وہ تو جاننے والا ہے قدرت والا ہے۔', 'یا اُنکو دیتا ہے جوڑے بیٹے اور بیٹیاں اور کر دیتا ہے جسکو چاہے بانجھ وہ ہی سب کچھ جانتا کر سکتا [۶۹]', 'Or He bestows both males and females, and He renders barren whom He wills. Verily, He is the All-Knower and is Able to do all things.', 'Or He combines for them couples, both males and females, and makes whom He wills barren. Surely, He is All-Knowing, Very-Powerful.'),
(4323, 42, 51, 5, 6, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ مَا کَانَ  لِبَشَرٍ اَنۡ یُّکَلِّمَہُ اللّٰہُ  اِلَّا وَحۡیًا اَوۡ مِنۡ وَّرَآیِٔ حِجَابٍ اَوۡ یُرۡسِلَ رَسُوۡلًا فَیُوۡحِیَ بِاِذۡنِہٖ مَا یَشَآءُ ؕ اِنَّہٗ عَلِیٌّ  حَکِیۡمٌ ﴿۵۱﴾', 'اور کسی آدمی کے لئے ممکن نہیں کہ اللہ اس سے بات کرے مگر وحی کے ذریعے یا پردے کے پیچھے سے یا کوئی فرشتہ بھیجدے تو وہ اللہ کے حکم سے جو اللہ چاہے القا کرے بیشک وہ بلند و برتر ہے حکمت والا ہے۔', 'اور کسی آدمی کی طاقت نہیں کہ اس سے باتیں کرے اللہ مگر اشارہ سے یا پردہ کے پیچھے سے یا بھیجے کوئی پیغما لانے والا پھر پہنچا دے اسکے حکم سے جو ہو چاہے [۷۰] تحقیقی وہ سب سے اوپر ہے حکمتوں والا [۷۱]', 'It is not given to any human being that Allah should speak to him unless (it be) by Inspiration, or from behind a veil, or (that) He sends a Messenger to reveal what He wills by His Leave. Verily, He is Most High, Most Wise .', 'It is not (possible) for a human being that Allah speaks to him, except by way of revelation, or from behind a curtain, or that He sends a messenger, and he reveals, with His permission, what He wills. Surely, He is All-High, All-Wise.'),
(4324, 42, 52, 5, 6, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'وَ کَذٰلِکَ  اَوۡحَیۡنَاۤ  اِلَیۡکَ رُوۡحًا مِّنۡ اَمۡرِنَا ؕ مَا کُنۡتَ تَدۡرِیۡ مَا الۡکِتٰبُ وَ لَا  الۡاِیۡمَانُ وَ لٰکِنۡ جَعَلۡنٰہُ  نُوۡرًا نَّہۡدِیۡ  بِہٖ مَنۡ نَّشَآءُ  مِنۡ عِبَادِنَا ؕ وَ اِنَّکَ لَتَہۡدِیۡۤ  اِلٰی صِرَاطٍ مُّسۡتَقِیۡمٍ ﴿ۙ۵۲﴾', 'اور اسی طرح ہم نے اپنے حکم سے تمہاری طرف روح القدس کے ذریعے سے قرآن بھیجا ہے۔ تم نہ تو کتاب کو جانتے تھے اور نہ ایمان کو۔ لیکن ہم نے اسکو نور بنایا ہے کہ اس سے ہم اپنے بندوں میں سے جسکو چاہتے ہیں ہدایت کرتے ہیں۔ اور بیشک اے نبی تم سیدھا رستہ دکھاتے ہو۔', 'اور اسی طح بھیجا ہم نے تیری طف ایک فرشتہ اپجے حکم سے [۷۲] تو نہ جانتا تھا کہ کیا ہے کتاب اور نہ ایمان [۷۳] ولیکن ہم نے رکھی ہے یہ روشنی اس سے راہ سجھا دیتے ہیں جسکو چاہیں اپنے بندوں میں [۷۴] اور بیشک تو سجھاتا ہے سیدھی راہ [۷۵]', 'And thus We have sent to you (O Muhammad SAW) Ruhan (an Inspiration, and a Mercy) of Our Command. You knew not what is the Book, nor what is Faith? But We have made it (this Quran) a light wherewith We guide whosoever of Our slaves We will. And verily, you (O Muhammad SAW) are indeed guiding (mankind) to the Straight Path (i.e. Allahs religion of Islamic Monotheism).', 'In similar way, We have revealed to you a Spirit from Our command. You did not know earlier what was the Book or what was Īmān (true faith), but We have made it (the Qur’ān) a light with which We guide whomsoever We will from among Our servants. And indeed you are guiding (people) to a straight path,'),
(4325, 42, 53, 5, 6, 25, 'اِلَیۡہِ یُرَدّ', 'الشُّورٰی', 'صِرَاطِ اللّٰہِ  الَّذِیۡ  لَہٗ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ؕ اَلَاۤ  اِلَی اللّٰہِ  تَصِیۡرُ الۡاُمُوۡرُ ﴿٪۵۳﴾', 'یعنی اس اللہ کا رستہ جو آسمانوں اور زمین کی سب چیزوں کا مالک ہے۔ دیکھو سب کام اللہ کی طرف رجوع ہوں گے اور وہی ان میں فیصلہ کرے گا۔', 'راہ اللہ کی اسی کا ہے جو کچھ ہے آسمانوں میں اور زمین میں [۷۶] سنتا ہے اللہ ہی تک پہنچتے ہیں سب کام [۷۷]', 'The Path of Allah, to Whom belongs all that is in the heavens and all that is in the earth. Verily, all the matters at the end go to Allah (for decision).', 'the path of Allah, the One to whom belongs all that is in the heavens and all that is in the earth. Be aware that towards Allah all matters shall finally return.'),
(4326, 43, 1, 1, 7, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'حٰمٓ ۚ﴿ۛ۱﴾', 'حٰمٓ۔', 'حٰمٓ۔', 'HaMeem. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings).', 'Hā Mīm.'),
(4327, 43, 2, 1, 7, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ الۡکِتٰبِ  الۡمُبِیۡنِ ۙ﴿ۛ۲﴾', 'کتاب روشن کی قسم۔', 'قسم ہے اس کتاب واضح کی', 'By the manifest Book (that makes things clear, i.e. this Quran).', 'By the manifest Book,'),
(4328, 43, 3, 1, 7, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اِنَّا جَعَلۡنٰہُ  قُرۡءٰنًا عَرَبِیًّا  لَّعَلَّکُمۡ تَعۡقِلُوۡنَ ۚ﴿۳﴾', 'کہ ہم نے اسکو قرآن عربی بنایا ہے تاکہ تم لوگ سمجھو۔', 'ہم نے رکھا اسکو قرآن عربی زبان کا تاکہ تم سمجھو [۱]', 'We verily, have made it a Quran in Arabic, that you may be able to understand (its meanings and its admonitions).', 'We have made it an Arabic Qur’ān, so that you may understand.'),
(4329, 43, 4, 1, 7, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ اِنَّہٗ  فِیۡۤ  اُمِّ الۡکِتٰبِ لَدَیۡنَا لَعَلِیٌّ حَکِیۡمٌ ؕ﴿۴﴾', 'اور یہ بڑی کتاب یعنی لوح محفوظ میں ہمارے پاس لکھی ہوئی اور بلند مرتبہ ہے حکمت والی ہے۔', 'اور تحقیق یہ قرآن لوح محفوظ ہیں ہمارے پاس ہے برتر مستحکم [۲]', 'And Verily, it (this Quran) is in the Mother of the Book (i.e. Al-Lauh Al-Mahfooz), before Us, indeed Exalted, full of Wisdom.', 'And it is, in the Mother of the Book (the Preserved Tablet) with us, surely sublime, full of wisdom.'),
(4330, 43, 5, 1, 7, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اَفَنَضۡرِبُ عَنۡکُمُ  الذِّکۡرَ صَفۡحًا اَنۡ کُنۡتُمۡ  قَوۡمًا مُّسۡرِفِیۡنَ ﴿۵﴾', 'تو کیا ہم پھیر دیں گے تمہاری طرف سے یہ کتاب نصیحت موڑ کر اس بنا پر کہ تم ایسے لوگ ہو جو حد پر نہیں رہتے۔', 'کیا پھیر دیں گے ہم تمہاری طرف سے یہ کتاب موڑ کر اس سبب سے کہ تم ہو ایسے لوگ کہ حد پر نہیں رہتے [۳]', 'Shall We then (warn you not and) take away the Reminder (this Quran) from you, because you are a people Musrifoon.', 'Shall We then take the advice away from you because you are a transgressing people?'),
(4331, 43, 6, 1, 7, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ کَمۡ  اَرۡسَلۡنَا مِنۡ نَّبِیٍّ  فِی الۡاَوَّلِیۡنَ ﴿۶﴾', 'اور ہم نے پہلے لوگوں میں بھی بہت سے پیغمبر بھیجے تھے۔', 'اور بہت بھیجے ہیں ہم نے نبی پہلوں میں', 'And how many a Prophet have We sent amongst the men of old.', 'How many a messenger We have sent to the earlier people!'),
(4332, 43, 7, 1, 7, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ مَا یَاۡتِیۡہِمۡ  مِّنۡ نَّبِیٍّ  اِلَّا کَانُوۡا بِہٖ یَسۡتَہۡزِءُوۡنَ ﴿۷﴾', 'اور جو پیغمبر بھی انکے پاس نہیں آتا تھا تو وہ اس سے ضرور تمسخر کرتے تھے۔', 'اور نہیں آتا لوگوں کے پاس کوئی پیغام لانے والا جس سے ٹھٹھا نہیں کرتے [۴]', 'And never came there a Prophet to them but they used to mock at him.', 'No messenger came to them, but they used to mock at him.'),
(4333, 43, 8, 1, 7, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'فَاَہۡلَکۡنَاۤ  اَشَدَّ مِنۡہُمۡ بَطۡشًا وَّ مَضٰی مَثَلُ  الۡاَوَّلِیۡنَ ﴿۸﴾', 'تو جو ان میں سخت زور والے تھے انکو ہم نے ہلاک کر دیا اور پہلے لوگوں کی حالت گذر چکی۔', 'پھر برباد کر ڈالے ہم نے اُن سے سخت زور والے اور چلی آئی ہے مثال پہلوں کی [۵]', 'Then We destroyed men stronger (in power) than these, and the example of the ancients has passed away (before them).', 'So We have destroyed those who were stronger than these (people of Makkah) in power, and the example of the earlier people has already passed.'),
(4334, 43, 9, 1, 7, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ لَئِنۡ سَاَلۡتَہُمۡ  مَّنۡ خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ لَیَقُوۡلُنَّ خَلَقَہُنَّ الۡعَزِیۡزُ الۡعَلِیۡمُ ﴿ۙ۹﴾', 'اور اگر تم ان سے پوچھو کہ آسمانوں اور زمین کو کس نے پیدا کیا ہے تو کہدیں گے کہ انکو غالب اور علم والے اللہ نے پیدا کیا ہے۔', 'اور اگر تو ان سے پوچھے کس نے بنائے آسمان اور زمین تو کہیں بنائے اس زبردست خبردار نے', 'And indeed if you ask them, \"Who has created the heavens and the earth?\" They will surely say: \"The All-Mighty, the All-Knower created them.\"', 'Should you ask them as to who has created the heavens and the earth, they will certainly say, “They are created by the All-Mighty, the All-Knowing,”'),
(4335, 43, 10, 1, 7, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'الَّذِیۡ جَعَلَ لَکُمُ الۡاَرۡضَ مَہۡدًا وَّ جَعَلَ لَکُمۡ فِیۡہَا سُبُلًا لَّعَلَّکُمۡ تَہۡتَدُوۡنَ ﴿ۚ۱۰﴾', 'جس نے تمہارے لئے زمین کو بچھونا بنایا۔ اور اس میں تمہارے لئے رستے بنائے تاکہ تم راہ راست پر چلو۔', 'وہی ہے  جس نے بنا دیا تمہارے لئے زمین کو بچھونا اور رکھ دیں تمہارے واسطے اُس میں راہیں تاکہ تم راہ پاؤ [۶]', 'Who has made for you the earth like a bed, and has made for you roads therein, in order that you may find your way,', 'the One who has made the earth a cradle for you, and has made for you pathways therein, so that you may be guided,'),
(4336, 43, 11, 1, 7, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ الَّذِیۡ  نَزَّلَ مِنَ السَّمَآءِ مَآءًۢ  بِقَدَرٍ ۚ فَاَنۡشَرۡنَا بِہٖ بَلۡدَۃً  مَّیۡتًا ۚ کَذٰلِکَ تُخۡرَجُوۡنَ ﴿۱۱﴾', 'اور جس نے ایک اندازے کے ساتھ آسمان سے پانی نازل کیا۔ پھر اس سے ہم نے مردہ زمین کو زندہ کیا۔ اسی طرح تم زمین سے نکالے جاؤ گے۔', 'اور جس نے اتارا آسمان سے پانی ماپ کر [۷] پھر ابھار کھڑا کیا ہم نے اس سے ایک دیس مردہ کو اسی طرح تمکو بھی نکالیں گے [۸]', 'And Who sends down water (rain) from the sky in due measure. Then We revive a dead land therewith, and even so you will be brought forth (from the dead),', 'and the One who has sent down water from the sky in due measure. Then We have revived with it a dead town. In the same way, you will be brought forth (alive from the graves),'),
(4337, 43, 12, 1, 7, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ الَّذِیۡ خَلَقَ الۡاَزۡوَاجَ کُلَّہَا وَ جَعَلَ لَکُمۡ مِّنَ الۡفُلۡکِ وَ الۡاَنۡعَامِ مَا تَرۡکَبُوۡنَ ﴿ۙ۱۲﴾', 'اور وہی ہے جس نے سب چیزوں کے جوڑے بنائے اور تمہارے لئے کشتیاں اور چوپائے بنائے جن پر تم سوار ہوتے ہو۔', 'اور جس نے بنائے سب چیز کے جوڑے [۹] اور بنا دیا تمہارے واسطے کشتیوں اور چوپایوں کو جس پر تم سوار ہوتے ہو', 'And Who has created all the pairs and has appointed for you ships and cattle on which you ride,', 'and the One who has created all the pairs, and has made for you the boats and the cattle that you ride,'),
(4338, 43, 13, 1, 7, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'لِتَسۡتَوٗا عَلٰی ظُہُوۡرِہٖ  ثُمَّ تَذۡکُرُوۡا نِعۡمَۃَ  رَبِّکُمۡ  اِذَا اسۡتَوَیۡتُمۡ عَلَیۡہِ وَ تَقُوۡلُوۡا سُبۡحٰنَ الَّذِیۡ سَخَّرَ لَنَا ہٰذَا  وَ مَا کُنَّا لَہٗ  مُقۡرِنِیۡنَ ﴿ۙ۱۳﴾', 'تاکہ تم ان کی پیٹھ پر چڑھ بیٹھو اور جب اس پر بیٹھ جاؤ پھر اپنے پروردگار کے احسان کو یاد کرو اور کہو کہ وہ ذات پاک ہے جس نے اسکو ہمارے زیرفرمان کر دیا اور ہم میں طاقت نہیں تھی کہ اسکو بس میں کر لیتے۔', 'تاکہ چڑھ بیٹھو تم اسکی پیٹھ پر [۱۰] پھر یاد کرو اپنے رب کا احسان جب بیٹھ چکو اُس پر اور کہو  پاک ذات ہے وہ جس نے بس میں کر دیا ہمارے اسکو اور ہم نہ تھے اسکو قابو میں لا سکتے [۱۱]', 'In order that you may mount firmly on their backs, and then may remember the Favour of your Lord when you mount thereon, and say: \"Glory to Him who has subjected this to us, and we could never have it (by our efforts).\"', 'so that you may mount upon their back, then recall the favour of your Lord after having mounted upon it and say, “Pure is the One who has subjugated this for us, and We were not able to have control over it,'),
(4339, 43, 14, 1, 7, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ  اِنَّاۤ  اِلٰی  رَبِّنَا  لَمُنۡقَلِبُوۡنَ ﴿۱۴﴾', 'اور ہم اپنے پروردگار کی طرف لوٹ کر جانے والے ہیں۔', 'اور ہمکو اپنے رب کی طرف پھر جانا ہے [۱۲]', 'And verily, to Our Lord we indeed are to return!', 'and of course, towards our Lord we have to return.”'),
(4340, 43, 15, 1, 7, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ جَعَلُوۡا لَہٗ  مِنۡ عِبَادِہٖ جُزۡءًا ؕ اِنَّ الۡاِنۡسَانَ  لَکَفُوۡرٌ  مُّبِیۡنٌ ﴿ؕ٪۱۵﴾', 'اور انہوں نے اسکے بندوں میں سے اسکے لئے اولاد مقرر کی۔ بیشک انسان سراسر ناشکرا ہے۔', 'اور ٹھہرائی ہے  اُنہوں نے حق تعالیٰ کے واسطے اولاد اسکے بندوں میں سے تحقیق انسان بڑا ناشکر ہے صریح', 'Yet they assign to some of His slaves a share with Him (by pretending that He has children, and considering them as equals or co-partners in worship with Him). Verily, man is indeed a manifest ingrate!', 'They have attributed to Him (that He is composed of) parts, (and that too) out of His servants. Surely, man is clearly ungrateful.'),
(4341, 43, 16, 2, 8, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اَمِ اتَّخَذَ مِمَّا یَخۡلُقُ بَنٰتٍ وَّ اَصۡفٰکُمۡ بِالۡبَنِیۡنَ ﴿۱۶﴾', 'کیا اس نے اپنی مخلوقات میں سے خود تو بیٹیاں لیں اور تمکو چن کر بیٹے دیدیئے۔', 'کیا اس نے رکھ لیں اپنی مخلوقات میں سے بیٹیاں اور تمکو دیدئے چن کر بیٹے [۱۳]', 'Or has He taken daughters out of what He has created, and He has selected for you sons?', 'Is it that He has adopted daughters from those whom He has created, and chosen you for (having) sons?'),
(4342, 43, 17, 2, 8, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ اِذَا بُشِّرَ اَحَدُہُمۡ بِمَا ضَرَبَ لِلرَّحۡمٰنِ مَثَلًا ظَلَّ وَجۡہُہٗ  مُسۡوَدًّا وَّ ہُوَ کَظِیۡمٌ ﴿۱۷﴾', 'حالانکہ جب ان میں سے کسی کو اس ہستی کی یعنی لڑکی کی خوشخبری دی جاتی ہے جو انہوں نے اللہ کے لئے بیان کی ہے تو اس کا چہرہ سیاہ پڑ جاتا ہے اور وہ اندر ہی اندر گھٹنے لگتا ہے۔', 'اور جب اُن میں کسی کو خوشخبری ملے اس چیز کی جس کو رحمٰن کے نام لگایا تو سارے دن رہے منہ اس کا سیاہ اور وہ دل میں گھٹ رہا ہے [۱۴]', 'And if one of them is informed of the news of (the birth of) that which he set forth as a parable to the Most Beneficent (Allah) (i.e. of a girl), his face becomes dark, gloomy, and he is filled with grief!', 'When one of them is given the good news of (the birth of) that which he has attributed to RaHmān (i.e. the daughters), his face turns black, and he becomes choked with sorrow.'),
(4343, 43, 18, 2, 8, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اَوَ مَنۡ یُّنَشَّؤُا فِی الۡحِلۡیَۃِ  وَ ہُوَ فِی الۡخِصَامِ  غَیۡرُ  مُبِیۡنٍ ﴿۱۸﴾', 'کیا وہ ہستی جو زیوروں میں پرورش پائے اور جھگڑے کے وقت بات نہ کر سکے اللہ کی اولاد ہو سکتی ہے؟', 'کیا ایسا شخص کہ پرورش پاتا ہے زیور میں اور وہ جھگڑے میں بات نہ کہہ سکے [۱۵]', '(Do they then like for Allah) a creature who is brought up in adornments (wearing silk and gold ornaments, i.e. women), and in dispute cannot make herself clear?', 'Is it that (Allah has chosen) those (as His offspring) who are grown up in ornaments and who cannot express themselves in debate clearly?'),
(4344, 43, 19, 2, 8, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ جَعَلُوا الۡمَلٰٓئِکَۃَ  الَّذِیۡنَ ہُمۡ عِبٰدُ الرَّحۡمٰنِ  اِنَاثًا ؕ اَشَہِدُوۡا خَلۡقَہُمۡ ؕ سَتُکۡتَبُ شَہَادَتُہُمۡ وَ  یُسۡـَٔلُوۡنَ ﴿۱۹﴾', 'اور انہوں نے فرشتوں کو کہ وہ رحمٰن کے بندے ہیں اسکی بیٹیاں ٹھہرایا۔ کیا یہ انکی پیدائش کے وقت حاضر تھے عنقریب انکی شہادت لکھ لی جائے گی اور ان سے باز پرس کی جائے گی۔', 'اور ٹھہرایا انہوں نے فرشتوں کو جو بندے ہیں رحمٰن کے عورتیں [۱۶] کیا دیکھتے تھے ان کا بننا اب لکھ رکھیں گے اُنکی گواہی اور اُن سے پوچھ ہو گی [۱۷]', 'And they make the angels who themselves are slaves to the Most Beneficent (Allah) females. Did they witness their creation? Their evidence will be recorded, and they will be questioned!', 'They have held angels, who are the servants of RaHmān, as females. Have they witnessed their creation? Their testimony will be recorded, and they will be questioned.'),
(4345, 43, 20, 2, 8, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ قَالُوۡا  لَوۡ  شَآءَ الرَّحۡمٰنُ مَا عَبَدۡنٰہُمۡ ؕ مَا لَہُمۡ  بِذٰلِکَ مِنۡ عِلۡمٍ ٭ اِنۡ ہُمۡ  اِلَّا یَخۡرُصُوۡنَ ﴿ؕ۲۰﴾', 'اور کہتے ہیں اگر رحمٰن چاہتا تو ہم انکو نہ پوجتے۔ انکو اس کا کچھ علم نہیں۔ یہ تو صرف اٹکلیں دوڑا رہے ہیں۔', 'اور کہتے ہیں اگر چاہتا رحمٰن تو ہم نہ پوجتے انکو [۱۸] کچھ خبر نہیں انکو اس کی یہ سب اٹکلیں دوڑاتے ہیں [۱۹]', 'And they said: \"If it had been the Will of the Most Beneficent (Allah), we should not have worshipped them (false deities).\" They have no knowledge whatsoever of that. They do nothing but lie!', 'They say, “Had the RaHmān so willed, we would not have worshipped them.” They have no knowledge of that. They do nothing but make conjectures.'),
(4346, 43, 21, 2, 8, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اَمۡ اٰتَیۡنٰہُمۡ کِتٰبًا مِّنۡ قَبۡلِہٖ  فَہُمۡ بِہٖ مُسۡتَمۡسِکُوۡنَ ﴿۲۱﴾', 'یا ہم نے انکو اس سے پہلے کوئی کتاب دی تھی تو کہ یہ اس سے استدلال کرتے ہوں۔', 'کیا ہم نے کوئی کتاب دی ہے انکو اس سے پہلے سو انہوں نے اسکو مضبوط پکڑ رکھا ہے', 'Or have We given them any Book before this (the Quran), to which they are holding fast?', 'Or have We given to them a book before this, and they are adhering to it?'),
(4347, 43, 22, 2, 8, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'بَلۡ قَالُوۡۤا  اِنَّا وَجَدۡنَاۤ  اٰبَآءَنَا عَلٰۤی اُمَّۃٍ وَّ  اِنَّا عَلٰۤی  اٰثٰرِہِمۡ  مُّہۡتَدُوۡنَ ﴿۲۲﴾', 'بلکہ کہنے لگے کہ ہم نے اپنے باپ دادا کو ایک طریقے پر پایا ہے اور ہم ان ہی کے قدم بقدم چل رہے ہیں۔', 'بلکہ کہتے ہیں ہم نے پایا اپنے باپ دادوں کو ایک راہ پر اور ہم اُنہی کے قدموں پر ہیں راہ پائے ہوئے [۲۰]', 'Nay! They say: \"We found our fathers following a certain way and religion, and we guide ourselves by their footsteps.\"', 'Instead, they say, “We have found our fathers on a certain way, and we are on their footprints, fully guided.”'),
(4348, 43, 23, 2, 8, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ کَذٰلِکَ مَاۤ  اَرۡسَلۡنَا مِنۡ قَبۡلِکَ فِیۡ قَرۡیَۃٍ مِّنۡ نَّذِیۡرٍ  اِلَّا قَالَ مُتۡرَفُوۡہَاۤ  ۙ اِنَّا وَجَدۡنَاۤ  اٰبَآءَنَا عَلٰۤی  اُمَّۃٍ  وَّ اِنَّا عَلٰۤی اٰثٰرِہِمۡ  مُّقۡتَدُوۡنَ ﴿۲۳﴾', 'اور اسی طرح ہم نے تم سے پہلے کسی بستی میں کوئی خبردار کرنے والا نہیں بھیجا مگر وہاں کے خوشخال لوگوں نے کہا کہ ہم نے اپنے باپ دادا کو ایک راہ پر پایا ہے اور ہم قدم بقدم ان ہی کے پیچھے چلتے ہیں۔', 'اور اسی طرح جس کسی کو بھیجا ہم نے تجھ سے پہلے ڈر سنانے والا کسی گاؤں میں سو کہنے لگے وہاں کے خوشحال لوگ ہم نے تو پایا اپنے باپ دادوں کو ایک راہ پراور ہم اُنہی کے قدموں پر چلتے ہیں', 'And similarly, We sent not a warner before you (O Muhammad SAW) to any town (people) but the luxurious ones among them said: \"We found our fathers following a certain way and religion, and we will indeed follow their footsteps.\"', 'Similarly, We did not send a warner to a town before you, but its affluent people said, “We have found our fathers on a certain way, and we are following their footprints.”'),
(4349, 43, 24, 2, 8, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'قٰلَ   اَوَ لَوۡ جِئۡتُکُمۡ  بِاَہۡدٰی مِمَّا وَجَدۡتُّمۡ عَلَیۡہِ  اٰبَآءَکُمۡ ؕ قَالُوۡۤا  اِنَّا بِمَاۤ  اُرۡسِلۡتُمۡ  بِہٖ  کٰفِرُوۡنَ ﴿۲۴﴾', 'پیغمبر نے کہا اگرچہ میں تمہارے پاس ایسا دین لایا ہوں کہ جس رستے پر تم نے اپنے باپ دادا کو پایا وہ اس سے کہیں زیادہ سیدھا رستہ دکھاتا ہو تو کہنے لگے کہ جو دین تم دے کر بھیجے گئے ہو ہم اسکو نہیں ماننے کے۔', 'وہ بولا اور جو میں لادوں تمکو  اس سے  زیادہ سوجھ کی راہ جس پر تم نے  پایا اپنے باپ دادوں کو [۲۱] تو یہی کہنے گے ہم تمہارا لایا ہوا نہیں مانیں گے [۲۲]', '(The warner) said: \"Even if I bring you better guidance than that which you found your fathers following?\" They said: \"Verily, We disbelieve in that with which you have been sent.\"', 'He said, “Even if I bring to you something better in guidance than that on which you have found your fathers?” They said, “We totally disbelieve in what you are sent with.”'),
(4350, 43, 25, 2, 8, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'فَانۡتَقَمۡنَا مِنۡہُمۡ  فَانۡظُرۡ کَیۡفَ کَانَ عَاقِبَۃُ  الۡمُکَذِّبِیۡنَ ﴿٪۲۵﴾', 'تو ہم نے ان سے انتقام لیا سو دیکھ لو کہ جھٹلانے والوں کا انجام کیسا ہوا۔', 'پھر ہم نے اُن سے بدلا لیا سو دیکھ لے کیسا ہوا انجام جھٹلانے والوں کا', 'So We took revenge of them, then see what was the end of those who denied (Islamic Monotheism).', 'So, We took revenge from them. Now look, how was the end of those who rejected (Our messengers).'),
(4351, 43, 26, 3, 9, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ اِذۡ قَالَ  اِبۡرٰہِیۡمُ  لِاَبِیۡہِ  وَ قَوۡمِہٖۤ  اِنَّنِیۡ بَرَآءٌ   مِّمَّا تَعۡبُدُوۡنَ ﴿ۙ۲۶﴾', 'اور جب ابراہیم  نے اپنے باپ اور اپنی قوم سے کہا کہ جن چیزوں کو تم پوجتے ہو میں ان سے بیزار ہوں۔', 'اور جب کہا ابراہیم نے اپنے باپ کو اور اُس کی قوم کو میں الگ ہوں اُن چیزوں سے جنکو تم پوجتے ہو', 'And (remember) when Ibraheem (Abraham) said to his father and his people: \"Verily, I am innocent of what you worship,', '(Recall) when Ibrāhīm said to his father and to his people, “I disown that which you worship,'),
(4352, 43, 27, 3, 9, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اِلَّا  الَّذِیۡ  فَطَرَنِیۡ  فَاِنَّہٗ  سَیَہۡدِیۡنِ ﴿۲۷﴾', 'ہاں جس نے مجھ کو پیدا کیا وہی مجھ کو سیدھے رستے پر لے چلے گا۔', 'مگر جس نے مجھ کو بنایا  سو وہ مجھ کو راہ سجھائے گا [۲۳]', '\"Except Him (i.e. I worship none but Allah Alone) Who did create me, and verily, He will guide me.\"', 'except the One who has originated me; so He will guide me.”'),
(4353, 43, 28, 3, 9, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ جَعَلَہَا کَلِمَۃًۢ  بَاقِیَۃً  فِیۡ عَقِبِہٖ  لَعَلَّہُمۡ  یَرۡجِعُوۡنَ ﴿۲۸﴾', 'اور یہی بات وہ اپنے بعد اپنی اولاد میں چھوڑ گئے تاکہ وہ اللہ کی طرف رجوع رہیں۔', 'اور یہی بات پیچھے چھوڑ گیا اپنی اولاد میں تاکہ وہ رجوع رہیں [۲۴]', 'And he made it (i.e. La ilaha ill-Allah (none has the right to be worshipped but Allah Alone)) a Word lasting among his offspring (True Monotheism), that they may turn back (i.e. to repent to Allah or receive admonition).', 'He made it a word lasting among his posterity, so that they may return.'),
(4354, 43, 29, 3, 9, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'بَلۡ مَتَّعۡتُ ہٰۤؤُلَآءِ وَ اٰبَآءَہُمۡ حَتّٰی جَآءَہُمُ  الۡحَقُّ وَ  رَسُوۡلٌ  مُّبِیۡنٌ ﴿۲۹﴾', 'بات یہ ہے کہ میں ان کفار کو اور انکے باپ دادا کو مال و متاع دیتا رہا یہاں تک کہ انکے پاس حق اور صاف صاف بیان کرنے والا پیغمبر آ پہنچا۔', 'کوئی نہیں پر میں نے برتنے دیا انکو اور اُنکے باپ دادوں کو یہاں تک کہ پہنچا اُنکے پاس  دین سچا اور رسول کھول کر سنا دینے والا [۲۵]', 'Nay, but I gave (the good things of this life) to these (polytheists) and their fathers to enjoy, till there came to them the truth (the Quran), and a Messenger (Muhammad SAW) making things clear.', 'But, I gave these and their fathers enjoyment, until the truth came to them, and a messenger as well who explains (it).'),
(4355, 43, 30, 3, 9, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ لَمَّا جَآءَہُمُ الۡحَقُّ  قَالُوۡا ہٰذَا سِحۡرٌ  وَّ اِنَّا بِہٖ  کٰفِرُوۡنَ ﴿۳۰﴾', 'اور جب ان کے پاس حق یعنی قرآن آیا تو کہنے لگے کہ یہ تو جادو ہے اور ہم اسکو نہیں ماننے کے۔', 'اور جب پہنچا اُنکے پاس سچا دین کہنے لگے یہ جادو ہے اور ہم اُسکو نہ مانیں گے [۲۶]', 'And when the truth (this Quran) came to them, they (the disbelievers in this Quran) said: \"This is magic, and we disbelieve therein.\"', 'But when the truth came to them, they said, “This is magic, and we totally disbelieve in it.”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(4356, 43, 31, 3, 9, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ قَالُوۡا لَوۡ لَا نُزِّلَ ہٰذَا الۡقُرۡاٰنُ عَلٰی رَجُلٍ مِّنَ الۡقَرۡیَتَیۡنِ  عَظِیۡمٍ ﴿۳۱﴾', 'اور یہ بھی کہنے لگے کہ یہ قرآن ان دونوں بستیوں یعنی مکے اور طائف میں سے کسی بڑے آدمی پر کیوں نازل نہ کیا گیا؟', 'اور کہتے ہیں کیوں نہ اترا یہ قرآن کسی بڑے مرد پر ان دونوں بستیوں میں کے [۲۷]', 'And they say: \"Why is not this Quran sent down to some great man of the two towns (Makkah and Taif)?\"', 'They say, “Why was this Qur’ān not revealed on a great man from (either of) the two towns?”'),
(4357, 43, 32, 3, 9, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اَہُمۡ یَقۡسِمُوۡنَ رَحۡمَتَ رَبِّکَ ؕ نَحۡنُ قَسَمۡنَا بَیۡنَہُمۡ  مَّعِیۡشَتَہُمۡ فِی الۡحَیٰوۃِ الدُّنۡیَا وَ رَفَعۡنَا بَعۡضَہُمۡ فَوۡقَ بَعۡضٍ دَرَجٰتٍ لِّیَتَّخِذَ بَعۡضُہُمۡ بَعۡضًا سُخۡرِیًّا ؕ وَ رَحۡمَتُ رَبِّکَ خَیۡرٌ  مِّمَّا یَجۡمَعُوۡنَ ﴿۳۲﴾', 'کیا یہ لوگ تمہارے پروردگار کی رحمت کو بانٹتے ہیں؟ ہم نے ان میں انکی معیشت کو دنیا کی زندگی میں تقسیم کر دیا اور ایک دوسرے پر درجے بلند کئے تاکہ ایک دوسرے سے خدمت لے اور جو کچھ یہ جمع کرتے ہیں تمہارے پروردگار کی رحمت اس سے کہیں بہتر ہے۔', 'کیا وہ بانٹتے ہیں تیرے رب کی رحمت کو [۲۸] ہم نے بانٹ دی ہے ان میں روزی اُن کی دنیا کی زندگانی میں اور بلند کر دیے درجے بعض کے بعض پر کہ ٹھہراتا ہے ایک دوسرے کو خدمتگار [۲۹] اور تیرے رب کی رحمت بہتر ہے ان چیزوں سے جو سمیٹتے ہیں [۳۰]', 'Is it they who would portion out the Mercy of your Lord? It is We Who portion out between them their livelihood in this world, and We raised some of them above others in ranks, so that some may employ others in their work. But the Mercy (Paradise) of your Lord (O Muhammad SAW) is better than the (wealth of this world) which they amass.', 'Is it they who allocate the mercy of your Lord? We have allocated among them their livelihood in the worldly life, and have raised some of them over others in ranks, so that some of them may put some others to work. And the mercy of your Lord is much better than what they accumulate.'),
(4358, 43, 33, 3, 9, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ لَوۡ لَاۤ  اَنۡ یَّکُوۡنَ النَّاسُ اُمَّۃً  وَّاحِدَۃً لَّجَعَلۡنَا  لِمَنۡ یَّکۡفُرُ بِالرَّحۡمٰنِ لِبُیُوۡتِہِمۡ سُقُفًا مِّنۡ فِضَّۃٍ  وَّ مَعَارِجَ عَلَیۡہَا یَظۡہَرُوۡنَ ﴿ۙ۳۳﴾', 'اور اگر یہ خیال نہ ہوتا کہ سب لوگ ایک ہی جماعت ہو جائیں گے تو جو لوگ اللہ سے انکار کرتے ہیں۔ ہم انکے گھروں کی چھتیں چاندی کی بنا دیتے اور سیڑھیاں بھی جن پر وہ چڑھتے۔', 'اور اگر یہ بات نہ ہوتی کہ سب لوگ ہو جائیں ایک دین پر تو ہم دیتے ان لوگوں کو جو منکر ہیں رحمٰن سے اُنکے گھروں کے واسطے چھت چاندی کی اور سیڑھیاں جن پر چڑھیں', 'And were it not that all mankind would have become of one community (all disbelievers, desiring worldly life only), We would have provided for those who disbelieve in the Most Beneficent (Allah), silver roofs for their houses, and elevators (and stair-ways, etc. of silver) whereby they ascend,', 'Were it not that all people would become of a single creed (i.e. disbelief), We would have caused, for those who disbelieve in RaHmān, roofs of their houses to be made of silver, and the stairs as well, on which they would climb,'),
(4359, 43, 34, 3, 9, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ لِبُیُوۡتِہِمۡ  اَبۡوَابًا وَّ سُرُرًا عَلَیۡہَا یَتَّکِـُٔوۡنَ ﴿ۙ۳۴﴾', 'اور انکے گھروں کے دروازے بھی اور تخت بھی جن پر تکیہ لگاتے ہیں۔', 'اور  اُن کے گھروں کے واسطے دروازے اور تخت جن پر تکیہ لگا کر بیٹھیں', 'And for their houses, doors (of silver), and thrones (of silver) on which they could recline,', 'and doors of their homes, and the coaches on which they would recline,'),
(4360, 43, 35, 3, 9, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ زُخۡرُفًا ؕ وَ اِنۡ کُلُّ  ذٰلِکَ لَمَّا مَتَاعُ الۡحَیٰوۃِ  الدُّنۡیَا ؕ وَ الۡاٰخِرَۃُ  عِنۡدَ  رَبِّکَ  لِلۡمُتَّقِیۡنَ ﴿٪۳۵﴾', 'اور یہ سب چیزیں سونے کی بھی بنا دیتے اور یہ سب دنیا کی زندگی کا تھوڑا سا سامان ہے اور آخرت تمہارے پروردگار کے ہاں پرہیزگاروں کے لئے ہے۔', 'اور سونے کے [۳۱] اور یہ سب کچھ نہیں ہے مگر برتنا دنیا کی زندگانی کا اور آخرت تیرے رب کے یہاں اُنہی کیلئے ہیں جو ڈرتے ہیں [۳۲]', 'And adornments of gold. Yet all this (i.e. the roofs, doors, stairs, elevators, thrones etc. of their houses) would have been nothing but an enjoyment of this world. And the Hereafter with your Lord is only for the Muttaqoon.', 'and (would have made some of these things) of gold-ornaments. And all this is nothing but an enjoyment of the worldly life. And the Hereafter, with your Lord, is (destined) for the God-fearing.'),
(4361, 43, 36, 4, 10, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ مَنۡ یَّعۡشُ عَنۡ ذِکۡرِ الرَّحۡمٰنِ نُقَیِّضۡ لَہٗ  شَیۡطٰنًا  فَہُوَ  لَہٗ  قَرِیۡنٌ ﴿۳۶﴾', 'اور جو کوئی رحمٰن کی یاد سے آنکھیں بند کر لے یعنی تغافل کرے ہم اس پر ایک شیطان مقرر کر دیتے ہیں تو وہ اس کا ساتھی ہو جاتا ہے۔', 'اور جو کوئی آنکھیں چرائے رحمٰن کی یاد سے ہم اُس پر مقرر کر دیں ایک شیطان پھر وہ رہے اسکا ساتھی [۳۳]', 'And whosoever turns away (blinds himself) from the remembrance of the Most Beneficent (Allah) (i.e. this Quran and worship of Allah), We appoint for him Shaitan (Satan devil) to be a Qareen (an intimate companion) to him.', 'Whoever makes himself blind against the advice of RaHmān, We assign for him a devil who accompanies him all the time.'),
(4362, 43, 37, 4, 10, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ اِنَّہُمۡ  لَیَصُدُّوۡنَہُمۡ عَنِ السَّبِیۡلِ وَ یَحۡسَبُوۡنَ  اَنَّہُمۡ  مُّہۡتَدُوۡنَ ﴿۳۷﴾', 'اور یہ شیطان انکو رستے سے روکتے رہتے ہیں اور وہ سمجھتے ہیں کہ وہ سیدھے رستے پر ہیں۔', 'اور  وہ اُنکو روکتے رہتے ہیں راہ سے اور یہ سمجھتےہیں کہ ہم راہ پر ہیں [۳۴]', 'And verily, they (Satans / devils) hinder them from the Path (of Allah), but they think that they are guided aright!', 'And they (the devils) prevent such people from the (right) way, while they deem themselves to be on the right path,'),
(4363, 43, 38, 4, 10, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'حَتّٰۤی  اِذَا جَآءَنَا قَالَ یٰلَیۡتَ بَیۡنِیۡ وَ بَیۡنَکَ بُعۡدَ الۡمَشۡرِقَیۡنِ فَبِئۡسَ الۡقَرِیۡنُ ﴿۳۸﴾', 'یہاں تک کہ جب ہمارے پاس آئے گا تو اس شیطان سے کہے گا کہ اے کاش مجھ میں اور تجھ میں مشرق و مغرب کا فاصلہ ہوتا تو برا ساتھی ہے۔', 'یہاں تک کہ جب آئے ہمارے پاس کہے کسی طرح مجھ میں اور تجھ میں فرق ہو مشرق مغرب کا سا کہ کیا برا ساتھی ہے [۳۵]', 'Till, when (such a one) comes to Us, he says (to his Qareen (Satan / devil companion)) \"Would that between me and you were the distance of the two easts (or the east and west)\" a worst (type of) companion (indeed)!', 'until when such a person will come to us, he will say (to the devil), “Would that there were the distance of East and West between me and you, because you were the worst companion.”'),
(4364, 43, 39, 4, 10, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ لَنۡ یَّنۡفَعَکُمُ الۡیَوۡمَ اِذۡ  ظَّلَمۡتُمۡ  اَنَّکُمۡ   فِی الۡعَذَابِ  مُشۡتَرِکُوۡنَ ﴿۳۹﴾', 'اور جب تم ظلم کرتے رہے تو آج تمہیں یہ بات فائدہ نہیں دے سکتی کہ تم سب عذاب میں بھی شریک ہو۔', 'اور کچھ فائدہ نہیں تمکو آج کے دن جبکہ تم ظالم ٹھہر چکے اس بات سے کہ تم عذاب میں شامل ہو [۳۶]', 'It will profit you not this Day (O you who turn away from Allahs remembrance and His worship, etc.) as you did wrong, (and) that you will be sharers (you and your Qareen) in the punishment.', 'And (it will be said to such people,) “Since you were wrongdoers, it will never benefit you today that you are sharing the punishment with each other.”'),
(4365, 43, 40, 4, 10, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اَفَاَنۡتَ تُسۡمِعُ  الصُّمَّ  اَوۡ تَہۡدِی الۡعُمۡیَ وَ مَنۡ  کَانَ فِیۡ ضَلٰلٍ مُّبِیۡنٍ ﴿۴۰﴾', 'تو کیا تم بہرے کو سنا سکتے ہو یا اندھے کو رستہ دکھا سکتے ہو اور جو کھلی گمراہی میں ہو اسے راہ راست پر لا سکتے ہو۔', 'سو کیا تو سنائے گا بہروں کو یا سمجھائے گا اندھوں کو اور صریح غلطی میں بھٹکتوں کو', 'Can you (O Muhammad SAW) make the deaf to hear, or can you guide the blind or him who is in manifest error?', 'So, can you (O prophet) make the deaf to hear, or can you show the way to the blind and the one who is in open error?'),
(4366, 43, 41, 4, 10, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'فَاِمَّا نَذۡہَبَنَّ بِکَ فَاِنَّا مِنۡہُمۡ مُّنۡتَقِمُوۡنَ ﴿ۙ۴۱﴾', 'پھر اے پیغمبر اگر ہم تمکو وفات دے کر اٹھالیں تو بھی ان لوگوں سے تو ہم انتقام لے کر رہیں گے۔', 'پھر اگر کبھی ہم تجھ کو  یہاں سے لیجائیں تو ہمکو  ان سے  بدلا لینا ہے', 'And even if We take you (O Muhammad SAW) away, We shall indeed take vengeance on them.', 'So, even if We take you away, We will surely take vengeance on them.'),
(4367, 43, 42, 4, 10, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اَوۡ نُرِیَنَّکَ الَّذِیۡ وَعَدۡنٰہُمۡ  فَاِنَّا عَلَیۡہِمۡ مُّقۡتَدِرُوۡنَ ﴿۴۲﴾', 'یا تمہاری زندگی ہی میں تمہیں وہ عذاب دکھا دیں گے جس کا ہم نے ان سے وعدہ کیا ہے کیونکہ ہم ان پر قابو رکھتے ہیں۔', 'یا تجھ کو دکھا دیں جو اُن سے وعدہ ٹھہرایا ہے تو یہ ہمارے بس میں ہیں', 'Or (if) We show you that wherewith We threaten them, then verily, We have perfect command over them.', 'Or (if) We show you (in your life) that (punishment) with which We have threatened them, then We have full control over them.'),
(4368, 43, 43, 4, 10, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'فَاسۡتَمۡسِکۡ بِالَّذِیۡۤ  اُوۡحِیَ   اِلَیۡکَ ۚ اِنَّکَ عَلٰی صِرَاطٍ مُّسۡتَقِیۡمٍ ﴿۴۳﴾', 'پس تمہاری طرف جو وحی کی گئ ہے اس پر مضبوطی سے جمے رہو بیشک تم سیدھے رستے پر ہو۔', 'سو تو مضبوط پکڑ ے رہ اسی کو جو تجھ کو حکم پہنچا تو ہے بیشک سیدھی راہ پر [۳۷]', 'So hold you (O Muhammad SAW) fast to that which is inspired in you. Verily, you are on a Straight Path.', 'So, hold fast to that which has been revealed to you. Surely, you are on the straight path.'),
(4369, 43, 44, 4, 10, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ اِنَّہٗ  لَذِکۡرٌ لَّکَ وَ لِقَوۡمِکَ ۚ وَ سَوۡفَ تُسۡـَٔلُوۡنَ ﴿۴۴﴾', 'اور یہ قرآن تمہارے لئے اور تمہاری قوم کے لئے نصیحت ہے اور لوگو تم سے ضرور عنقریب پرسش ہو گی۔', 'اور یہ مذکور رہے گا تیرا اور تیری قوم کا [۳۸] اور آگے تم سے پوچھ ہو گی [۳۹]', 'And verily, this (the Quran) is indeed a Reminder for you (O Muhammad SAW) and your people (Quraish people, or your followers), and you will be questioned (about it).', 'And certainly this (Qur’ān) is a word of honour for you and your people, and you will be questioned.'),
(4370, 43, 45, 4, 10, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ سۡـَٔلۡ مَنۡ  اَرۡسَلۡنَا مِنۡ  قَبۡلِکَ مِنۡ رُّسُلِنَاۤ  اَجَعَلۡنَا مِنۡ دُوۡنِ الرَّحۡمٰنِ اٰلِـہَۃً   یُّعۡبَدُوۡنَ ﴿٪۴۵﴾', 'اور اے نبی جو اپنے پیغمبر ہم نے تم سے پہلے بھیجے ہیں انکے احوال دریافت کر لو۔ کہ کیا ہم نے رحمٰن کو سوا اور معبود ٹھہرائے تھے کہ انکی عبادت کی جائے؟', 'اور پوچھ دیکھ جو رسول بھیجے ہم نے تجھ سے پہلے کبھی ہم نے رکھے ہیں رحمٰن کے سوائے اور حاکم کہ پوجے جائیں [۴۰]', 'And ask (O Muhammad SAW) those of Our Messengers whom We sent before you: \"Did We ever appoint aliha (gods) to be worshipped besides the Most Beneficent (Allah)?\"', 'Ask Our messengers whom We sent before you whether We had appointed gods to be worshipped besides RaHmān.'),
(4371, 43, 46, 5, 11, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ لَقَدۡ  اَرۡسَلۡنَا مُوۡسٰی بِاٰیٰتِنَاۤ  اِلٰی فِرۡعَوۡنَ وَ مَلَا۠ئِہٖ فَقَالَ  اِنِّیۡ رَسُوۡلُ رَبِّ الۡعٰلَمِیۡنَ ﴿۴۶﴾', 'اور ہم نے موسٰی  کو اپنی نشانیاں دے کر فرعون اور اسکے درباریوں کی طرف بھیجا تو انہوں نے کہا کہ میں پروردگار عالم کا بھیجا ہوا ہوں۔', 'اور ہم نے بھیجا موسٰی کو اپنی نشانیاں دے کر فرعون اور اسکے سرداروں کے پاس تو کہا میں بھیجا ہوا ہوں جہان کے رب کا', 'And indeed We did send Moosa (Moses) with Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) to Firaun (Pharaoh) and his chiefs (inviting them to Allahs Religion of Islam) He said: \"Verily, I am a Messenger of the Lord of the Alameen (mankind, jinns and all that exists).\"', 'We sent Mūsā with Our signs to Fir’aun (Pharaoh) and his chiefs; so he said, “I am the messenger of the Lord of the worlds.”'),
(4372, 43, 47, 5, 11, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'فَلَمَّا جَآءَہُمۡ بِاٰیٰتِنَاۤ  اِذَا ہُمۡ مِّنۡہَا یَضۡحَکُوۡنَ ﴿۴۷﴾', 'پھر جب وہ انکے پاس ہماری نشانیاں لیکر آئے تو وہ ان نشانیوں پر ہنسنے لگے۔', 'پھر جب لایا انکے پاس ہماری نشانیاں وہ تو لگے ان پر ہنسنے [۴۱]', 'But when he came to them with Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) behold! They laughed at them.', 'So, when he came to them with Our signs, they at once started laughing at them.'),
(4373, 43, 48, 5, 11, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ مَا نُرِیۡہِمۡ  مِّنۡ اٰیَۃٍ  اِلَّا ہِیَ اَکۡبَرُ مِنۡ اُخۡتِہَا ۫ وَ اَخَذۡنٰہُمۡ  بِالۡعَذَابِ لَعَلَّہُمۡ  یَرۡجِعُوۡنَ ﴿۴۸﴾', 'اور جو نشانی ہم انکو دکھاتے وہ پہلی سے بڑی ہوتی تھی اور ہم نے انکو عذاب میں پکڑ لیا تاکہ باز آئیں۔', 'اور جو دکھاتے گئے ہم انکو نشانی سو پہلی سے بڑی [۴۲] اور پکڑا ہم نے اُنکو تکلیف میں تاکہ وہ باز آئیں [۴۳]', 'And not an Ayah (sign, etc.) We showed them but it was greater than its fellow, and We seized them with torment, in order that they might turn (from their polytheism to Allahs Religion (Islamic Monotheism)).', 'And We did not show them a sign, but it used to be greater than the one that preceded it. And We seized them with punishment, so that they may return.'),
(4374, 43, 49, 5, 11, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ قَالُوۡا یٰۤاَیُّہَ السّٰحِرُ  ادۡعُ  لَنَا رَبَّکَ بِمَا عَہِدَ عِنۡدَکَ ۚ اِنَّنَا  لَمُہۡتَدُوۡنَ ﴿۴۹﴾', 'اور کہنے لگے کہ اے جادوگر اس عہد کے مطابق جو تیرے پروردگار نے تجھ سے کر رکھا ہے اس سے دعا کر بیشک ہم ہدایت یاب ہوں گے۔', 'اور کہنے لگے اے جادوگر [۴۴] پکار ہمارے واسطے اپنے رب کو جیسا سکھلا رکھا ہے تجھ کو ہم ضرور راہ پر  آجائیں گے [۴۵]', 'And they said (to Moosa (Moses)): \"O you sorcerer! Invoke your Lord for us according to what He has covenanted with you. Verily, We shall guide ourselves (aright).\"', 'And they said, “O magician, pray for us to your Lord by the covenant He has made with you; we will certainly come to guidance.”'),
(4375, 43, 50, 5, 11, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'فَلَمَّا کَشَفۡنَا عَنۡہُمُ  الۡعَذَابَ  اِذَا ہُمۡ  یَنۡکُثُوۡنَ ﴿۵۰﴾', 'سو جب ہم نے ان سے عذاب دور کر دیا تو وہ عہد شکنی کرنے لگے۔', 'پھر جب اٹھا لی ہم نے ان پر سے تکلیف تبھی  وہ وعدہ  توڑ  ڈالتے  [۴۶]', 'But when We removed the torment from them, behold! They broke their covenant (that they will believe if We remove the torment for them).', 'Then, once We removed the punishment from them, in no time they broke their promise.'),
(4376, 43, 51, 5, 11, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ نَادٰی فِرۡعَوۡنُ فِیۡ  قَوۡمِہٖ  قَالَ یٰقَوۡمِ اَلَیۡسَ لِیۡ مُلۡکُ مِصۡرَ وَ ہٰذِہِ  الۡاَنۡہٰرُ تَجۡرِیۡ مِنۡ  تَحۡتِیۡ ۚ اَفَلَا  تُبۡصِرُوۡنَ ﴿ؕ۵۱﴾', 'اور فرعون نے اپنی قوم سے پکار کر کہا کہ اے قوم کیا مصر کی حکومت میرے ہاتھ میں نہیں ہے۔ اور یہ نہریں جو میرے محلوں کے نیچے بہ رہی ہیں میری نہیں ہیں کیا تم دیکھتے نہیں؟', 'اور پکارا فرعون نے  اپنی قوم میں بولا اے میری قوم بھلا میرے  ہاتھ میں نہیں حکومت مصر کی اور یہ نہریں چل رہی ہیں میرے محل کے نیچے کیا تم نہیں دیکھتے [۴۷]', 'And Firaun (Pharaoh) proclaimed among his people, saying: \"O my people! Is not mine the dominion of Egypt, and these rivers flowing underneath me. See you not then?', 'And Fir’aun (Pharaoh) proclaimed among his people, saying, “Does not the kingdom of Egypt belong to me, and these rivers are flowing right underneath me? Do you, then, not discern?'),
(4377, 43, 52, 5, 11, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اَمۡ اَنَا خَیۡرٌ  مِّنۡ ہٰذَا الَّذِیۡ ہُوَ  مَہِیۡنٌ ۬ۙ وَّ لَا یَکَادُ  یُبِیۡنُ ﴿۵۲﴾', 'بیشک میں اس شخص سے جو کچھ عزت نہیں رکھتا اور صاف گفتگو بھی نہیں کر سکتا کہیں بہتر ہوں۔', 'بھلا میں ہوں بھی بہتر اس شخص سے جسکو کچھ عزت نہیں اور صاف نہیں بول سکتا [۴۸]', '\"Am I not better than this one (Moosa (Moses)), who is Maheen (has no honour nor any respect, and is weak and despicable) and can scarcely express himself clearly?', 'Or (do you not see that) I am much better than this one (Mūsā) who is worthless and can hardly express himself?'),
(4378, 43, 53, 5, 11, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'فَلَوۡ لَاۤ  اُلۡقِیَ عَلَیۡہِ  اَسۡوِرَۃٌ  مِّنۡ ذَہَبٍ اَوۡ جَآءَ  مَعَہُ الۡمَلٰٓئِکَۃُ  مُقۡتَرِنِیۡنَ ﴿۵۳﴾', 'تو اس پر سونے کے کنگن کیوں نہ اتارے گئے یا یہ ہوتا کہ فرشتے جمع ہو کر اسکے ساتھ آتے۔', 'پھر کیوں نہ آ پڑے اس پر کنگن سونے کے یا آتے اسکے ساتھ فرشتے پرا باندھ کر [۴۹]', '\"Why then are not golden bracelets bestowed on him, or angels sent along with him?\"', 'So why were the bracelets of gold not sent down to him, or (why) did the angels not come along with him as companions?”'),
(4379, 43, 54, 5, 11, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'فَاسۡتَخَفَّ قَوۡمَہٗ  فَاَطَاعُوۡہُ ؕ اِنَّہُمۡ کَانُوۡا قَوۡمًا فٰسِقِیۡنَ ﴿۵۴﴾', 'غرض اس نے اپنی قوم کو بے عقل کر دیا۔ اور ان لوگوں نے اسکی بات مان لی بیشک وہ نافرمان لوگ تھے۔', 'پھر عقل کھو دی اپنی قوم کی پھر اسی کا کہنا مانا مقرر وہ تھے لوگ نافرمان [۵۰]', 'Thus he (Firaun (Pharaoh)) befooled and misled his people, and they obeyed him. Verily, they were ever a people who were Fasiqoon (rebellious, disobedient to Allah).', 'Thus he made fool of his people, and they obeyed him. Surely they were a sinful people.'),
(4380, 43, 55, 5, 11, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'فَلَمَّاۤ  اٰسَفُوۡنَا انۡتَقَمۡنَا مِنۡہُمۡ فَاَغۡرَقۡنٰہُمۡ  اَجۡمَعِیۡنَ ﴿ۙ۵۵﴾', 'پھر جب انہوں نے ہم کو خفا کیا تو ہم نے ان سے انتقام  لیا اور ان سب کو ڈبو کر چھوڑا۔', 'پھر جب ہم کو غصہ دلایا [۵۱] تو ہم نے اُن سے بدلا لیا پھر ڈبو دیا اُن سب کو', 'So when they angered Us, We punished them, and drowned them all.', 'So, when they provoked Our anger, We took vengeance on them, and drowned them all together,'),
(4381, 43, 56, 5, 11, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'فَجَعَلۡنٰہُمۡ  سَلَفًا وَّ  مَثَلًا  لِّلۡاٰخِرِیۡنَ ﴿٪۵۶﴾', 'سو انکو گئے گذرے کر دیا اور بعد میں آنے والوں کیلئے عبرت بنا دیا۔', 'پھر کر ڈالا اُنکو گئے گذرے اور ایک نظیر پچھلوں کے واسطے [۵۲]', 'And We made them a precedent (as a lesson for those coming after them), and an example to later generations.', 'and made them a people of the past, and an example for the later generations.'),
(4382, 43, 57, 6, 12, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ لَمَّا ضُرِبَ ابۡنُ مَرۡیَمَ  مَثَلًا  اِذَا قَوۡمُکَ مِنۡہُ  یَصِدُّوۡنَ ﴿۵۷﴾', 'اور جب مریم  کے بیٹے عیسٰی  کا حال بیان کیا گیا تو تمہاری قوم کے لوگ اس سے چلا اٹھے۔', 'اور جب مثال لائے مریم کے بیٹے کی تبھی قوم تیری اس سے چلانے لگتے ہیں', 'And when the son of Maryam (Mary) is quoted as an example (i.e. Iesa (Jesus) is worshipped like their idols), behold! Your people cry aloud (laugh out at the example).', 'When the example of the son of Maryam was cited, your people started at once shouting at it (in joy),'),
(4383, 43, 58, 6, 12, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ قَالُوۡۤاءَ اٰلِہَتُنَا خَیۡرٌ اَمۡ ہُوَ ؕ مَا ضَرَبُوۡہُ  لَکَ  اِلَّا جَدَلًا ؕ بَلۡ ہُمۡ قَوۡمٌ خَصِمُوۡنَ ﴿۵۸﴾', 'اور کہنے لگے کہ بھلا ہمارے معبود اچھے ہیں یا وہ یعنی عیسٰی؟ انہوں نے جو ان عیسٰی کی مثال تم سے بیان کی ہے تو صرف جھگڑنے کو۔ حقیقت یہ ہے کہ یہ لوگ ہیں ہی جھگڑالو۔', 'اور کہتے ہیں ہمارے معبود بہتر ہیں یا وہ [۵۳] یہ مثال جو ڈالتے ہیں تجھ پرسو جھگڑنے کو بلکہ یہ لوگ ہیں جھگڑالو', 'And say: \"Are our aliha (gods) better or is he (Iesa (Jesus))?\" They quoted not the above example except for argument. Nay! But they are a quarrelsome people. ((See VV. 21:97-101) - The Quran.)', 'and said, “Are Our gods better or is he?” They did not cite it (the example) but for the sake of disputation. Rather, they are a quarrelsome people.'),
(4384, 43, 59, 6, 12, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اِنۡ ہُوَ اِلَّا عَبۡدٌ اَنۡعَمۡنَا عَلَیۡہِ وَ جَعَلۡنٰہُ  مَثَلًا   لِّبَنِیۡۤ   اِسۡرَآءِیۡلَ ﴿ؕ۵۹﴾', 'وہ تو ہمارے ایسے بندے تھے جن پر ہم نے فضل کیا اور بنی اسرائیل کے لئے انکو اپنی قدرت کا نمونہ بنا دیا۔', 'وہ کیا ہے ایک بندہ ہے کہ ہم نے اس پر فضل کیا اور کھڑا کر دیا اسکو بنی اسرائیل کے واسطے [۵۴]', 'He (Iesa (Jesus)) was not more than a slave. We granted Our Favour to him, and We made him an example to the Children of Israel (i.e. his creation without a father).', 'He (‘Īsā) is no more than a servant (of Allah) whom We favoured and made an example for the children of Isrā’īl.'),
(4385, 43, 60, 6, 12, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ لَوۡ  نَشَآءُ  لَجَعَلۡنَا مِنۡکُمۡ مَّلٰٓئِکَۃً  فِی الۡاَرۡضِ  یَخۡلُفُوۡنَ ﴿۶۰﴾', 'اور اگر ہم چاہتے تو تم میں سے فرشتے بنا دیتے جو تمہاری جگہ زمین میں رہتے۔', 'اور اگر ہم چاہیں نکالیں تم میں سے فرشتے رہیں زمین میں تمہاری جگہ [۵۵]', 'And if it were Our Will, We would have (destroyed you (mankind) all, and) made angels to replace you on the earth. (Tafsir At-Tabaree, Vol:25, Page 89).', 'And if We will, We may create angels from you who succeed you on the earth.'),
(4386, 43, 61, 6, 12, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ اِنَّہٗ  لَعِلۡمٌ  لِّلسَّاعَۃِ  فَلَا تَمۡتَرُنَّ بِہَا وَ اتَّبِعُوۡنِ ؕ ہٰذَا صِرَاطٌ مُّسۡتَقِیۡمٌ ﴿۶۱﴾', 'اور وہ یعنی عیسٰی قیامت کی نشانی ہیں۔ تو کہدو کہ لوگو اس میں شک نہ کرو اور میرے پیچھے چلو۔ یہی سیدھا رستہ ہے۔', 'اور وہ نشان ہے قیامت کا [۵۶] سو اس میں شک مت کرو اور میرا کہا مانو یہ ایک سیدھی راہ ہے', 'And he (Iesa (Jesus), son of Maryam (Mary)) shall be a known sign for (the coming of) the Hour (Day of Resurrection) (i.e. Iesas (Jesus) descent on the earth) . Therefore have no doubt concerning it (i.e. the Day of Resurrection). And follow Me (Allah) (i.e. be obedient to Allah and do what He orders you to do, O mankind)! This is the Straight Path (of Islamic Monotheism, leading to Allah and to His Paradise).', 'And he (‘Īsā) is a source of knowledge of the Hour (the Day of Judgment); so do not be in doubt about it, and follow me. This is the straight way.'),
(4387, 43, 62, 6, 12, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ لَا یَصُدَّنَّکُمُ الشَّیۡطٰنُ ۚ اِنَّہٗ  لَکُمۡ عَدُوٌّ  مُّبِیۡنٌ ﴿۶۲﴾', 'اور کہیں شیطان تمکو اس سے روک نہ دے۔ وہ تو تمہارا اعلانیہ دشمن ہے۔', 'اور نہ روک دے تم کو شیطان وہ تو تمہارا دشمن ہے صریح [۵۷]', 'And let not Shaitan (Satan) hinder you (from the right religion, i.e. Islamic Monotheism), Verily, he (Satan) to you is a plain enemy.', 'And let not the ShaiTān (Satan) prevent you (from following this way). He is surely an open enemy for you.'),
(4388, 43, 63, 6, 12, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ لَمَّا جَآءَ عِیۡسٰی بِالۡبَیِّنٰتِ قَالَ قَدۡ جِئۡتُکُمۡ  بِالۡحِکۡمَۃِ وَ لِاُبَیِّنَ  لَکُمۡ بَعۡضَ الَّذِیۡ تَخۡتَلِفُوۡنَ فِیۡہِ ۚ فَاتَّقُوا اللّٰہَ  وَ اَطِیۡعُوۡنِ ﴿۶۳﴾', 'اور جب عیسٰی نشانیاں لے کر آئے تو فرمایا کہ میں تمہارے پاس دانائی کی کتاب لے کر آیا ہوں۔ نیز اس لئے کہ بعض باتیں جن میں تم اختلاف کرتے ہو تمکو سمجھا دوں۔ سو اللہ سے ڈرو اور میرا کہا مانو۔', 'اور جب آیا عیسٰی نشانیاں لے کر بولا میں لایا ہوں تمہارے پاس پکی باتیں [۵۸] اور بتلانے کو بعضی وہ چیز جس میں تم جھگڑتے تھے [۵۹] سو ڈرو اللہ سے اور میرا کہا مانو', 'And when Iesa (Jesus) came with (Our) clear Proofs, he said: \"I have come to you with Al-Hikmah (Prophethood), and in order to make clear to you some of the (points) in which you differ, therefore fear Allah and obey me,', 'When ‘Īsā came with clear proofs, he said, “I have come to you with wisdom, and to explain to you some of those matters in which you differ. So, fear Allah, and obey me.'),
(4389, 43, 64, 6, 12, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اِنَّ اللّٰہَ  ہُوَ رَبِّیۡ  وَ رَبُّکُمۡ  فَاعۡبُدُوۡہُ ؕ ہٰذَا صِرَاطٌ  مُّسۡتَقِیۡمٌ ﴿۶۴﴾', 'کچھ شک نہیں کہ اللہ ہی میرا اور تمہارا پروردگار ہے پس اسی کی عبادت کرو۔ یہی سیدھا رستہ ہے۔', 'بیشک اللہ جو ہے وہی ہے رب میرا اور رب تمہارا سو اسی کی بندگی کرو یہ ایک سیدھی راہ ہے [۶۰]', '\"Verily, Allah! He is my Lord (God) and your Lord (God). So worship Him (Alone). This is the (only) Straight Path (i.e. Allahs religion of true Islamic Monotheism).\"', 'Surely, it is Allah who is my Lord and your Lord; so worship Him. This is the straight way.”'),
(4390, 43, 65, 6, 12, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'فَاخۡتَلَفَ الۡاَحۡزَابُ مِنۡۢ  بَیۡنِہِمۡ ۚ فَوَیۡلٌ  لِّلَّذِیۡنَ ظَلَمُوۡا مِنۡ عَذَابِ یَوۡمٍ اَلِیۡمٍ ﴿۶۵﴾', 'پھر کتنے فرقے ان میں سے الگ الگ ہو گئے۔ سو جو لوگ ظالم ہیں انکے لئے درد دینے والے دن کے عذاب سے خرابی ہے۔', 'پھر پھٹ گئے کتنے فرقے انکے بیچ سے [۶۱] سو خرابی ہے گنہگاروں کو آفت سے دکھ والے دن کی', 'But the sects from among themselves differed. So woe to those who do wrong (by ascribing things to Iesa (Jesus) that are not true) from the torment of a painful Day (i.e. the Day of Resurrection)!', 'Then different groups, out of them, fell into disagreement. Woe to the wrongdoers because of the punishment of a painful day!'),
(4391, 43, 66, 6, 12, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'ہَلۡ یَنۡظُرُوۡنَ  اِلَّا السَّاعَۃَ  اَنۡ تَاۡتِیَہُمۡ بَغۡتَۃً  وَّ ہُمۡ  لَا یَشۡعُرُوۡنَ ﴿۶۶﴾', 'یہ صرف اس بات کے منتظر ہیں کہ قیامت ان پر ناگہاں آ موجود ہو اور انکو خبر تک نہ ہو۔', 'اب یہی ہے کہ راہ دیکھتے ہیں قیامت کی کہ آ کھڑی ہو ان پر اچانک اور انکو خبر بھی نہ ہو [۶۲]', 'Do they only wait for the Hour that it shall come upon them suddenly, while they perceive not?', 'They are waiting for nothing but for the Hour to come upon them suddenly, while they would not even imagine (it).'),
(4392, 43, 67, 6, 12, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اَلۡاَخِلَّآءُ  یَوۡمَئِذٍۭ بَعۡضُہُمۡ لِبَعۡضٍ عَدُوٌّ  اِلَّا الۡمُتَّقِیۡنَ ﴿ؕ٪۶۷﴾', 'جو آپس میں دوست ہیں اس روز ایک دوسرے کے دشمن ہوں گے۔ مگر پرہیزگار کہ وہ باہم دوست ہی رہیں گے۔', 'جتنے دوست ہیں اس دن ایک دوسرے کے دشمن ہوں گے مگر جو لوگ ہیں ڈر والے [۶۳]', 'Friends on that Day will be foes one to another except Al-Muttaqoon (pious - see V.2:2).', 'Friends, on that day, will become enemies to one another, except the God-fearing,'),
(4393, 43, 68, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'یٰعِبَادِ  لَا خَوۡفٌ عَلَیۡکُمُ  الۡیَوۡمَ  وَ لَاۤ اَنۡتُمۡ  تَحۡزَنُوۡنَ ﴿ۚ۶۸﴾', 'میرے بندو! آج تمہیں نہ کچھ خوف ہے اور نہ تم غمناک ہو گے۔', 'اے بندو میرے نہ ڈر ہے تم پر آج کے دن اور نہ تم غمگین ہو گے [۶۴]', '(It will be said to the true believers of Islamic Monotheism): My worshippers! No fear shall be on you this Day, nor shall you grieve,', '(to whom it will be said) “O my servants, there is no fear for you today, nor will you grieve-'),
(4394, 43, 69, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اَلَّذِیۡنَ اٰمَنُوۡا بِاٰیٰتِنَا وَ کَانُوۡا مُسۡلِمِیۡنَ ﴿ۚ۶۹﴾', 'جو لوگ ہماری آیتوں پر ایمان لائے اور فرمانبردار  بن گئے۔', 'جو یقین لائے ہماری باتوں پر اور رہے حکم بردار [۶۵]', '(You) who believed in Our Ayat (proofs, verses, lessons, signs, revelations, etc.) and were Muslims (i.e. who submit totally to Allahs Will, and believe in the Oneness of Allah - Islamic Monotheism).', '-O those (servants) who believed in Our signs, and remained obedient.'),
(4395, 43, 70, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اُدۡخُلُوا الۡجَنَّۃَ  اَنۡتُمۡ وَ اَزۡوَاجُکُمۡ تُحۡبَرُوۡنَ ﴿۷۰﴾', 'ان سے کہا جائے گا کہ تم اور تمہاری بیویاں عزت و احترام کے ساتھ بہشت میں داخل ہو جاؤ۔', 'چلے جاؤ بہشت میں تم اور تمہاری عورتیں کہ تمہاری عزت کریں', 'Enter Paradise, you and your wives, in happiness.', '- Enter the Paradise, you and your spouses, showered with bliss.”'),
(4396, 43, 71, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'یُطَافُ عَلَیۡہِمۡ  بِصِحَافٍ مِّنۡ ذَہَبٍ وَّ اَکۡوَابٍ ۚ وَ فِیۡہَا مَا تَشۡتَہِیۡہِ  الۡاَنۡفُسُ وَ تَلَذُّ الۡاَعۡیُنُ ۚ وَ اَنۡتُمۡ  فِیۡہَا خٰلِدُوۡنَ ﴿ۚ۷۱﴾', 'ان پر سونے کی طشتریوں اور پیالیوں کا دور چلے گا اور وہاں جو جی چاہے اور جو آنکھوں کو اچھا لگے موجود ہو گا اور اے اہل جنت تم اس میں ہمیشہ رہو گے۔', 'لئے پھریں گے انکے پاس رکابیاں سونے کی اور آبخورے [۶۶] اور وہاں ہے جو دل چاہے اور جس سے آنکھیں آرام پائیں [۶۷] اور تم ان میں ہمیشہ رہو گے', 'Trays of gold and cups will be passed round them, (there will be) therein all that the ones inner-selves could desire, all that the eyes could delight in, and you will abide therein forever.', 'Circulated among them will be the bowls of gold, and glasses. And there will be whatever souls desire and that which eyes enjoy. “And you will be living in it for ever.'),
(4397, 43, 72, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ تِلۡکَ الۡجَنَّۃُ  الَّتِیۡۤ  اُوۡرِثۡتُمُوۡہَا بِمَا کُنۡتُمۡ  تَعۡمَلُوۡنَ ﴿۷۲﴾', 'اور یہ جنت جسکے تم مالک بنا دیئے گئے ہو تمہارے اعمال کا صلہ ہے۔', 'اور وہی بہشت ہے جو میراث پائی تم نے بدلے میں ان کاموں کے جو کرتے تھے [۶۸]', 'This is the Paradise which you have been made to inherit because of your deeds which you used to do (in the life of the world).', 'That is the Paradise you are made to inherit because of what you used to do.'),
(4398, 43, 73, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'لَکُمۡ  فِیۡہَا  فَاکِہَۃٌ  کَثِیۡرَۃٌ  مِّنۡہَا تَاۡکُلُوۡنَ ﴿۷۳﴾', 'یہاں تمہارے لئے بہت سے میوے ہیں جنکو تم کھاؤ گے۔', 'تمہارے واسطے ان میں بہت میوے ہیں ان میں سے کھاتے رہو [۶۹]', 'Therein for you will be fruits in plenty, of which you will eat (as you desire).', 'For you there are fruits in abundance from which you will eat.”'),
(4399, 43, 74, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اِنَّ  الۡمُجۡرِمِیۡنَ فِیۡ عَذَابِ جَہَنَّمَ خٰلِدُوۡنَ ﴿ۚۖ۷۴﴾', 'اور گنہگار یعنی کفار ہمیشہ دوزخ کے عذاب میں رہیں گے۔', 'البتہ جو لوگ گنہگار ہیں وہ دوزخ کے عذاب میں ہمیشہ رہنے والے ہیں', 'Verily, the Mujrimoon (criminals, sinners, disbelievers, etc.) will be in the torment of Hell to abide therein forever.', 'The sinners (on the other hand) will be in the punishment of Jahannam (Hell), living there forever.'),
(4400, 43, 75, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'لَا یُفَتَّرُ عَنۡہُمۡ  وَ ہُمۡ فِیۡہِ مُبۡلِسُوۡنَ ﴿ۚ۷۵﴾', 'جو ان سے ہلکا نہ کیا جائے گا اور وہ اس میں ناامید ہو کر پڑے رہیں گے۔', 'نہ ہلکا ہوتا ہے ان پر سے اور وہ اسی میں پڑے ہیں آس ٹوٹے [۷۰]', '(The torment) will not be lightened for them, and they will be plunged into destruction with deep regrets, sorrows and in despair therein.', 'It will not be lightened for them, and they will be there, devoid of all hopes.'),
(4401, 43, 76, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ مَا ظَلَمۡنٰہُمۡ وَ لٰکِنۡ کَانُوۡا ہُمُ الظّٰلِمِیۡنَ ﴿۷۶﴾', 'اور ہم نے ان پر ظلم نہیں کیا۔ بلکہ وہی اپنے آپ پر ظلم کرتے تھے۔', 'اور ہم نے اُن پر ظلم نہیں کیا لیکن تھے وہی بے انصاف [۷۱]', 'We wronged them not, but they were the Zalimoon (polytheists, wrong-doers, etc.).', 'We did not do injustice to them, rather, they themselves were the unjust.'),
(4402, 43, 77, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ نَادَوۡا یٰمٰلِکُ لِیَقۡضِ عَلَیۡنَا رَبُّکَ ؕ قَالَ  اِنَّکُمۡ   مّٰکِثُوۡنَ ﴿۷۷﴾', 'اور وہ پکاریں گے کہ اے مالک اے دوزخ کے نگران تمہارا پروردگار ہمیں موت ہی دیدے۔ وہ کہے گا کہ تم ہمیشہ اسی حالت میں رہو گے۔', 'اور پکاریں گے اے مالک کہیں ہم پر فیصل کر چکے تیرا رب [۷۲] وہ کہے گا تمکو ہمیشہ رہنا ہے [۷۳]', 'And they will cry: \"O Malik (Keeper of Hell)! Let your Lord make an end of us.\" He will say: \"Verily you shall abide forever.\"', 'And they will call (Mālik, the keeper of the Hell,) “O Mālik, let your Lord do away with us.” He will say, “You have to stay on.”'),
(4403, 43, 78, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'لَقَدۡ جِئۡنٰکُمۡ بِالۡحَقِّ وَ لٰکِنَّ  اَکۡثَرَکُمۡ  لِلۡحَقِّ  کٰرِہُوۡنَ ﴿۷۸﴾', 'ہم تمہارے پاس حق لے کر پہنچے لیکن تم میں سے اکثر حق سے ناخوش ہوتے رہے۔', 'ہم لائے ہیں تمہارے پاس سچا دین پر تم بہت لوگ سچی بات سے برا مانتے ہو [۷۴]', 'Indeed We have brought the truth (Muhammad SAW with the Quran), to you, but most of you have a hatred for the truth.', '(O disbelievers,) indeed We have brought to you the truth, but it is the truth that most of you detest.'),
(4404, 43, 79, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اَمۡ  اَبۡرَمُوۡۤا  اَمۡرًا فَاِنَّا مُبۡرِمُوۡنَ ﴿ۚ۷۹﴾', 'کیا انہوں نے کوئی بات ٹھہرا رکھی ہے تو ہم بھی کچھ ٹھہرانے والے ہیں۔', 'کیا انہوں نے ٹھہرائی ہے ایک بات تو ہم بھی کچھ ٹھہرائیں گے  [۷۵]', 'Or have they plotted some plan? Then We too are planning.', 'Is it that they have firmly resolved to do something (harmful to Our messenger)? Then, We have firmly resolved (to frustrate their plan.)'),
(4405, 43, 80, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'اَمۡ یَحۡسَبُوۡنَ  اَنَّا  لَا نَسۡمَعُ سِرَّہُمۡ وَ نَجۡوٰىہُمۡ ؕ بَلٰی وَ رُسُلُنَا لَدَیۡہِمۡ یَکۡتُبُوۡنَ ﴿۸۰﴾', 'کیا یہ لوگ یہ خیال کرتے ہیں کہ ہم انکی پوشیدہ باتوں اور سرگوشیوں کو سنتے نہیں؟ کیوں نہیں سب سنتے ہیں اور ہمارے فرشتے انکے پاس انکی سب باتیں لکھ لیتے ہیں۔', 'کیا خیال رکھتے ہیں کہ ہم نہیں جانتے ان کا بھید اور ان کا مشورہ کیوں نہیں اور ہمارے بھیجے ہوئے انکے پاس لکھتے رہتے ہیں [۷۶]', 'Or do they think that We hear not their secrets and their private counsel? (Yes We do) and Our Messengers (appointed angels in charge of mankind) are by them, to record.', 'Do they think that We do not hear their secrets and their whispers? Yes of course, Our messengers (angels) are with them who record (whatever they plan).'),
(4406, 43, 81, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'قُلۡ  اِنۡ کَانَ لِلرَّحۡمٰنِ وَلَدٌ ٭ۖ فَاَنَا اَوَّلُ الۡعٰبِدِیۡنَ ﴿۸۱﴾', 'کہدو کہ اگر رحمٰن کیلئے اولاد ہو تو میں سب سے پہلے اسکی عبادت کرنے والا ہوں۔', 'تو کہہ اگر ہو رحمٰن کے واسطے اولاد تو میں سب سے پہلے پوجوں [۷۷]', 'Say (O Muhammad SAW): \"If the Most Beneficent (Allah) had a son (or children as you pretend), then I am the first of Allahs worshippers (who deny and refute this claim of yours (and the first to believe in Allah Alone and testify that He has no children)).\" (Tafsir At-Tabaree).', 'Say, “Had there been a son for the RaHmān, I would have been the first to worship.”'),
(4407, 43, 82, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'سُبۡحٰنَ رَبِّ السَّمٰوٰتِ وَ الۡاَرۡضِ رَبِّ الۡعَرۡشِ عَمَّا یَصِفُوۡنَ ﴿۸۲﴾', 'یہ جو کچھ بیان کرتے ہیں۔ آسمانوں اور زمین کا جو عرش کا بھی مالک ہے اس سے پاک ہے۔', 'پاک ذات ہے وہ رب آسمانوں کا اور زمین کا صاحب عرش کا ان باتوں سے جو یہ بیان کرتے ہیں [۷۸]', 'Glorified be the Lord of the heavens and the earth, the Lord of the Throne! Exalted be He from all that they ascribe (to Him).', 'Pure is the Lord of the heavens and the earth, the Lord of the Throne, from what they attribute (to Him).'),
(4408, 43, 83, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'فَذَرۡہُمۡ  یَخُوۡضُوۡا وَ یَلۡعَبُوۡا حَتّٰی یُلٰقُوۡا یَوۡمَہُمُ  الَّذِیۡ یُوۡعَدُوۡنَ ﴿۸۳﴾', 'تو انکو بک بک کرنے اور کھیلنے دو۔ یہاں تک کہ جس دن کا ان سے وعدہ کیا جاتا ہے اسکو دیکھ لیں۔', 'اب چھوڑ دے انکو بک بک کریں اور کھیلیں یہاں تک کہ ملیں اپنے اس دن سے جس کا انکو وعدہ دیا ہے [۷۹]', 'So leave them (alone) to speak nonsense and play until they meet the Day of theirs, which they have been promised.', 'So, let them indulge (in their fallacy) and play, until they face their Day that they are promised.'),
(4409, 43, 84, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ ہُوَ الَّذِیۡ فِی السَّمَآءِ  اِلٰہٌ  وَّ فِی الۡاَرۡضِ  اِلٰہٌ ؕ وَ ہُوَ  الۡحَکِیۡمُ  الۡعَلِیۡمُ ﴿۸۴﴾', 'اور وہی آسمانوں میں بھی معبود ہے اور وہی زمین میں بھی معبود ہے۔ اور وہ حکمت والا ہے علم والا ہے۔', 'اور وہی ہے جس کی بندگی ہے آسمان میں اور اسکی بندگی ہے زمین میں اور وہی ہے حکمت والا سب سے خبردار [۸۰]', 'It is He (Allah) Who is the only Ilah (God to be worshipped) in the heaven and the only Ilah (God to be worshipped) on the earth. And He is the All-Wise, the All-Knower.', 'He is the One who is God to be worshipped in the sky, and God to be worshipped on the earth. And He is the Wise, the All-Knowing.'),
(4410, 43, 85, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ تَبٰرَکَ الَّذِیۡ  لَہٗ  مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ مَا بَیۡنَہُمَا ۚ وَ عِنۡدَہٗ  عِلۡمُ السَّاعَۃِ ۚ وَ  اِلَیۡہِ  تُرۡجَعُوۡنَ ﴿۸۵﴾', 'اور وہ بہت بابرکت ہے جسکے لئے آسمانوں اور زمین اور جو کچھ ان دونوں میں ہے سب کی حکومت ہے۔ اور اسی کو قیامت کا علم ہے اور اسی کی طرف تم لوٹ کر جاؤ گے۔', 'اور بڑی برکت ہے اسکی جس کا راج ہے آسمانوں میں اور زمین میں اور جو کچھ انکے بیچ میں ہے اور اسی کے پاس ہے خبر قیامت کی [۸۱] اور اسی تک پھر کر پہنچ جاؤ گے [۸۲]', 'And blessed be He to Whom belongs the kingdom of the heavens and the earth, and all that is between them, and with Whom is the knowledge of the Hour, and to Whom you (all) will be returned.', 'Glorious is the One to whom belongs the kingdom of the heavens and the earth and whatever lies between them. With Him is the knowledge of the Hour; and towards Him you are to be returned.'),
(4411, 43, 86, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ لَا یَمۡلِکُ الَّذِیۡنَ یَدۡعُوۡنَ مِنۡ دُوۡنِہِ الشَّفَاعَۃَ  اِلَّا مَنۡ شَہِدَ بِالۡحَقِّ وَ ہُمۡ یَعۡلَمُوۡنَ ﴿۸۶﴾', 'اور جنکو یہ لوگ اللہ کے سوا پکارتے ہیں وہ تو سفارش کا کچھ اختیار نہیں رکھتے۔ ہاں جو علم و یقین کے ساتھ حق کی گواہی دیں وہ سفارش کر سکتے ہیں۔', 'اور اختیار نہیں رکھتے وہ لوگ جنکو یہ پکارتے ہیں سفارش کا مگر جس نے گواہی دی سچی اور انکو خبر تھی [۸۳]', 'And those whom they invoke instead of Him have no power of intercession; except those who bear witness to the truth (i.e. believed in the Oneness of Allah, and obeyed His Orders), and they know (the facts about the Oneness of Allah) .', 'And those whom they invoke besides Him have no power to intercede; but those who bear witness to the truth, while they have knowledge (may intercede for the believers with Allah’s permission).'),
(4412, 43, 87, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ لَئِنۡ سَاَلۡتَہُمۡ مَّنۡ خَلَقَہُمۡ  لَیَقُوۡلُنَّ اللّٰہُ فَاَنّٰی یُؤۡفَکُوۡنَ ﴿ۙ۸۷﴾', 'اور اگر تم ان سے پوچھو کہ انکو کس نے پیدا کیا ہے تو کہدیں گے کہ اللہ نے۔ تو پھر یہ کہاں بہکے پھرتے ہیں؟', 'اور اگر تو ان سے پوچھے کہ انکو کس نے بنایا تو کہیں گے اللہ نے پھر کہاں سے الٹ جاتے ہیں [۸۴]', 'And if you ask them who created them, they will surely say: \"Allah\". How then are they turned away (from the worship of Allah, Who created them)?', 'And if you ask them as to who has created them, they will certainly say, “Allah”. Then, to where are they driven back (by their false desires)?'),
(4413, 43, 88, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'وَ قِیۡلِہٖ  یٰرَبِّ  اِنَّ ہٰۤؤُلَآءِ  قَوۡمٌ لَّا یُؤۡمِنُوۡنَ ﴿ۘ۸۸﴾', 'اور بسا اوقات پیغمبر کہا کرتے ہیں کہ اے پروردگار یہ ایسے لوگ ہیں کہ ایمان نہیں لاتے۔', 'قسم ہے رسول کے اس کہنے کی کہ اے رب یہ لوگ ہیں کہ یقین نہیں لاتے [۸۵]', '(Allah has knowledge) of (Prophet Muhammads) saying: \"O my Lord! Verily, these are a people who believe not!\"', 'And (Allah has the knowledge) of his (prophet’s) saying, “O my Lord, these are a people who do not believe.”'),
(4414, 43, 89, 7, 13, 25, 'اِلَیۡہِ یُرَدّ', 'الزُّخرُف', 'فَاصۡفَحۡ عَنۡہُمۡ وَ قُلۡ سَلٰمٌ ؕ فَسَوۡفَ یَعۡلَمُوۡنَ ﴿٪۸۹﴾', 'تو اے پیغمبر ان سے منہ پھیر لو اور سلام کہدو۔ انکو عنقریب انجام معلوم ہو جائے گا۔', 'سو تو منہ پھیر لے انکی طرف سے اور کہہ سلام ہے [۸۶] اب آخر کو معلوم کر لیں گے [۸۷]', 'So turn away from them (O Muhammad SAW), and say: Salam (peace)! But they will come to know.', 'So, turn away from them, and say, “Salām !” (good-bye!). Then, soon they will come to know (the end of their attitude).'),
(4415, 44, 1, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'حٰمٓ ﴿ۚۛ۱﴾', 'حٰمٓ۔', 'حٰمٓ۔', 'Ha-Meem. (These letters are one of the miracles of the Quran and none but Allah (Alone) knows their meanings).', 'Hā Mīm .'),
(4416, 44, 2, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'وَ الۡکِتٰبِ الۡمُبِیۡنِ ۙ﴿ۛ۲﴾', 'اس کتاب روشن کی قسم۔', 'قسم ہے اس کتاب واضح کی', 'By the manifest Book (this Quran) that makes things clear,', 'By the manifest Book,'),
(4417, 44, 3, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'اِنَّاۤ  اَنۡزَلۡنٰہُ  فِیۡ  لَیۡلَۃٍ  مُّبٰرَکَۃٍ  اِنَّا کُنَّا مُنۡذِرِیۡنَ ﴿۳﴾', 'کہ ہم نے اسکو ایک مبارک رات میں نازل فرمایا ہم تو خبردار کرنے والے ہیں۔', 'ہم نے اسکو اتارا ایک برکت کی رات میں [۱] ہم ہیں کہہ سنانے والے [۲]', 'We sent it (this Quran) down on a blessed night ((i.e. night of Qadr, Soorah No: 97) in the month of Ramadan,, the 9th month of the Islamic calendar). Verily, We are ever warning (mankind that Our Torment will reach those who disbelieve in Our Oneness of Lordship and in Our Oneness of worship).', 'We have sent it down in a blessed night, (because) We had to warn (people).'),
(4418, 44, 4, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'فِیۡہَا یُفۡرَقُ کُلُّ  اَمۡرٍ  حَکِیۡمٍ ۙ﴿۴﴾', 'اسی رات میں تمام حکمت کے کام فیصل کئے جاتے ہیں۔', 'اسی میں جدا ہوتا ہے ہر کام جانچا ہوا', 'Therein (that night) is decreed every matter of ordainments .', 'In that (night), every wise matter is allocated'),
(4419, 44, 5, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'اَمۡرًا مِّنۡ عِنۡدِنَا ؕ اِنَّا کُنَّا مُرۡسِلِیۡنَ ۚ﴿۵﴾', 'یعنی ہمارے ہاں سے حکم ہو کر۔ بیشک ہم ہی فرشتوں کو بھیجتے ہیں۔', 'حکم ہو کر ہمارے پاس سے [۳] ہم ہیں بھیجنے والے [۴]', 'Amran (i.e. a Command or this Quran or the Decree of every matter) from Us. Verily, We are ever sending (the Messengers),', 'through a command from Us. We were to send the Messenger'),
(4420, 44, 6, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'رَحۡمَۃً  مِّنۡ  رَّبِّکَ ؕ اِنَّہٗ  ہُوَ السَّمِیۡعُ الۡعَلِیۡمُ ۙ﴿۶﴾', 'یہ تمہارے پروردگار کی رحمت ہے۔ وہی تو سننے والا ہے جاننے والا ہے۔', 'رحمت سے تیرے رب کی وہی ہے سننے جاننے والا [۵]', '(As) a Mercy from your Lord. Verily! He is the All-Hearer, the All-Knower.', 'as a mercy from your Lord, -Surely, He is the All-Hearing, the All-Knowing-'),
(4421, 44, 7, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'رَبِّ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ مَا بَیۡنَہُمَا  ۘ اِنۡ  کُنۡتُمۡ  مُّوۡقِنِیۡنَ ﴿۷﴾', 'آسمانوں اور زمین اور جو کچھ ان دونوں میں ہے سب کا مالک۔ بشرطیکہ تم لوگ یقین کرنے والے ہو۔', 'رب آسمانوں کا اور زمین کا اور جو کچھ انکے بیچ میں ہے اگر تمکو یقین ہے [۶]', 'The Lord of the heavens and the earth and all that is between them, if you (but) have a faith with certainty.', 'the Lord of the heavens and the earth and of whatever there is between them, if you are to believe.'),
(4422, 44, 8, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'لَاۤ  اِلٰہَ  اِلَّا ہُوَ یُحۡیٖ وَ یُمِیۡتُ ؕ رَبُّکُمۡ  وَ رَبُّ اٰبَآئِکُمُ  الۡاَوَّلِیۡنَ ﴿۸﴾', 'اسکے سوا کوئی معبود نہیں وہی زندگی دیتا ہے اور وہی موت دیتا ہے وہی تمہارا اور تمہارے پہلے باپ دادوں کا پروردگار ہے۔', 'کسی کی بندگی نہیں سوائے اسکے جلاتا ہے اور مارتا ہے رب تمہارا اور رب تمہارے اگلے باپ دادوں کا [۷]', 'La ilaha illa Huwa (none has the right to be worshipped but He). It is He Who gives life and causes death, your Lord and the Lord of your fore-fathers.', 'There is no god, but He. He gives life and brings death. He is your Lord and the Lord of your forefathers.'),
(4423, 44, 9, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'بَلۡ  ہُمۡ  فِیۡ  شَکٍّ  یَّلۡعَبُوۡنَ ﴿۹﴾', 'لیکن یہ لوگ شک میں پڑے کھیل رہے ہیں۔', 'کوئی نہیں وہ دھوکے میں ہیں کھیلتے [۸]', 'Nay! They play in doubt.', 'But they, being in doubt, are playing around.'),
(4424, 44, 10, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'فَارۡتَقِبۡ یَوۡمَ تَاۡتِی السَّمَآءُ بِدُخَانٍ مُّبِیۡنٍ ﴿ۙ۱۰﴾', 'تو اس دن کا انتظار کرو کہ آسمان سے صاف دھواں نکلے گا۔', 'سو تو انتظار کر اس دن کا کہ لائے آسمان دھواں صریح', 'Then wait you for the Day when the sky will bring forth a visible smoke.', 'So, wait for a day when the sky will come up with a visible smoke'),
(4425, 44, 11, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'یَّغۡشَی النَّاسَ ؕ ہٰذَا  عَذَابٌ  اَلِیۡمٌ ﴿۱۱﴾', 'جو لوگوں پر چھا جائے گا۔ یہ درد دینے والا عذاب ہے۔', 'جو گھیر لیوے لوگوں کو یہ ہے عذاب دردناک [۹]', 'Covering the people, this is a painful torment.', 'that will envelop people. This is a painful punishment.'),
(4426, 44, 12, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'رَبَّنَا  اکۡشِفۡ عَنَّا الۡعَذَابَ  اِنَّا مُؤۡمِنُوۡنَ ﴿۱۲﴾', 'اس وقت وہ کہیں گے کہ اے پروردگار ہم سے اس عذاب کو دور کر ہم ایمان لاتے ہیں۔', 'اے رب کھولدے ہم پر سے یہ عذاب ہم یقین لاتے ہیں [۱۰]', '(They will say): \"Our Lord! Remove the torment from us, really we shall become believers!\"', '(Then they will say,) “O our Lord, remove from us the punishment; we will truly believe.”'),
(4427, 44, 13, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'اَنّٰی لَہُمُ الذِّکۡرٰی وَ قَدۡ جَآءَہُمۡ رَسُوۡلٌ مُّبِیۡنٌ ﴿ۙ۱۳﴾', 'اس وقت انکو نصیحت کہاں مفید ہو گی جبکہ انکے پاس پیغمبر آ چکے جو ہمارے احکام کھول کر بیان کر دیتے تھے۔', 'کہاں ملے اُنکو سمجھنا اور آچکا اُنکے پاس رسول کھول کر سنانے والا', 'How can there be for them an admonition (at the time when the torment has reached them), when a Messenger explaining things clearly has already come to them.', 'How will they take lesson, while there has already come to them a messenger making things clear?'),
(4428, 44, 14, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'ثُمَّ تَوَلَّوۡا عَنۡہُ  وَ قَالُوۡا مُعَلَّمٌ  مَّجۡنُوۡنٌ ﴿ۘ۱۴﴾', 'پھر انہوں نے ان سے منہ پھیر لیا اور کہنے لگے یہ تو سکھایا پڑھایا ہوا ہے دیوانہ ہے۔', 'پھر اس سے پیٹھ پھیری اور کہنے لگے سکھایا ہوا ہے باؤلا [۱۱]', 'Then they had turned away from him (Messenger Muhammad SAW) and said: \"One (Muhammad SAW) taught (by a human being), a madman!\"', 'Then they turned away from him, and said, “(He is) tutored, crazy.”'),
(4429, 44, 15, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'اِنَّا کَاشِفُوا الۡعَذَابِ قَلِیۡلًا  اِنَّکُمۡ عَآئِدُوۡنَ ﴿ۘ۱۵﴾', 'ہم تو تھوڑے دنوں عذاب ٹال دیتے ہیں مگر تم پھر کفر کرنے لگتے ہو۔', 'ہم کھولے دیتےہیں یہ عذاب تھوڑی مدت تک تم پھر وہی کرو گے [۱۲]', 'Verily, We shall remove the torment for a while. Verily! You will revert.', '(Well,) We are going to remove the punishment for a while, (but) you will certainly go back (to your original position).'),
(4430, 44, 16, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'یَوۡمَ نَبۡطِشُ الۡبَطۡشَۃَ  الۡکُبۡرٰی ۚ اِنَّا مُنۡتَقِمُوۡنَ ﴿۱۶﴾', 'جس دن ہم بڑی سخت گرفت کریں گے تو بیشک انتقام لے کر چھوڑیں گے۔', 'جس دن پکڑیں گے ہم بڑی پکڑ تحقیق ہم بدلا لینے والے ہیں [۱۳]', 'On the Day when We shall seize you with the greatest grasp. Verily, We will exact retribution.', '(Then,) the day We will seize (you) with the greatest seizure, We will take vengeance.'),
(4431, 44, 17, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'وَ لَقَدۡ فَتَنَّا قَبۡلَہُمۡ قَوۡمَ فِرۡعَوۡنَ وَ جَآءَہُمۡ  رَسُوۡلٌ  کَرِیۡمٌ ﴿ۙ۱۷﴾', 'اور ان سے پہلے ہم نے قوم فرعون کی آزمائش کی اور انکے پاس ایک عالی قدر پیغمبر آئے۔', 'اور جانچ چکے ہیں ہم ان سے پہلے فرعون کی قوم کو اور  آیا ان کے پاس رسول عزت والا [۱۴]', 'And indeed We tried before them Firauns (Pharaoh) people, when there came to them a noble Messenger (i.e. Moosa (Moses) ),', 'And We tested the people of Fir‘aun (Pharaoh) prior to them, and a noble messenger came to them'),
(4432, 44, 18, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'اَنۡ  اَدُّوۡۤا  اِلَیَّ  عِبَادَ اللّٰہِ ؕ اِنِّیۡ  لَکُمۡ رَسُوۡلٌ  اَمِیۡنٌ ﴿ۙ۱۸﴾', 'جنہوں نے یہ کہا کہ اللہ کے بندوں یعنی بنی اسرائیل کو میرے حوالے کر دو میں تمہارا امانتدار پیغمبر ہوں۔', 'کہ حوالے کرو میرے بندے خدا کے  [۱۵] میں تمہارے پاس آیا ہوں بھیجا ہوا معتبر', 'Saying: \"Restore to me the slaves of Allah (i.e. the Children of Israel). Verily! I am to you a Messenger worthy of all trust,', 'saying, “Deliver to me the servants of Allah. I am an honest messenger to you,”'),
(4433, 44, 19, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'وَّ اَنۡ  لَّا تَعۡلُوۡا عَلَی اللّٰہِ ۚ اِنِّیۡۤ  اٰتِیۡکُمۡ بِسُلۡطٰنٍ مُّبِیۡنٍ ﴿ۚ۱۹﴾', 'اور اللہ کے سامنے سرکشی نہ کرو میں تمہارے پاس کھلی دلیل لے کر آیا ہوں۔', 'اور یہ کہ چڑھے نہ جاؤ اللہ کے مقابل میں لاتا ہوں تمہارے پاس سند کھلی ہوئی [۱۶]', '\"And exalt not (yourselves) against Allah. Truly, I have come to you with a manifest authority.', 'and saying, “Do not be haughty against Allah. I bring to you a clear proof.'),
(4434, 44, 20, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'وَ اِنِّیۡ  عُذۡتُ بِرَبِّیۡ  وَ رَبِّکُمۡ اَنۡ تَرۡجُمُوۡنِ ﴿۫۲۰﴾', 'اور اس بات سے کہ تم مجھے سنگسار کرو میں اپنے اور تمہارے پروردگار کی پناہ لے چکا ہوں۔', 'اور میں پناہ لے چکا ہوں اپنے رب اور تمہارے رب کی اس بات سے کہ تم مجھ کو سنگسار کرو [۱۷]', '\"And truly, I seek refuge in my Lord and your Lord, lest you stone me (or call me a sorcerer or kill me).', 'And I have sought refuge with my Lord and your Lord, lest you stone me to death.'),
(4435, 44, 21, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'وَ  اِنۡ  لَّمۡ  تُؤۡمِنُوۡا  لِیۡ  فَاعۡتَزِلُوۡنِ ﴿۲۱﴾', 'اور اگر مجھ پر ایمان نہیں لاتے تو مجھ سے الگ ہو جاؤ۔', 'اور اگر تم نہیں یقین کرتے مجھ پر تو مجھ  سے پرے ہو جاؤ [۱۸]', '\"But if you believe me not, then keep away from me and leave me alone.\"', 'And if you do not believe in me, then keep away from me.”'),
(4436, 44, 22, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'فَدَعَا رَبَّہٗۤ  اَنَّ ہٰۤؤُلَآءِ  قَوۡمٌ مُّجۡرِمُوۡنَ ﴿ؓ۲۲﴾', 'تب موسٰی  نے اپنے پروردگار سے دعا کی کہ یہ نافرمان لوگ ہیں۔', 'پھر دعا کی اپنے رب سے کہ یہ لوگ گنہگار ہیں', '(But they were aggressive), so he (Moosa (Moses)) called upon his Lord (saying): \"These are indeed the people who are Mujrimoon (disbelievers, polytheists, sinners, criminals, etc.).\"', 'Then he prayed to his Lord saying, “These are a guilty people.”'),
(4437, 44, 23, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'فَاَسۡرِ بِعِبَادِیۡ لَیۡلًا اِنَّکُمۡ مُّتَّبَعُوۡنَ ﴿ۙ۲۳﴾', 'اللہ نے فرمایا کہ اچھا میرے بندوں کو راتوں رات لے کر چلے جاؤ اور فرعونی ضرور تمہارا تعاقب کریں گے۔', 'پھر لے نکل رات سے میرے بندوں کو  البتہ تمہارا پیچھا کریں گے [۱۹]', '(Allah said): \"Depart you with My slaves by night. Surely, you will be pursued.', '(So, Allah answered his prayer saying,) “Now, take away my servants at night. You will certainly be chased,'),
(4438, 44, 24, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'وَ اتۡرُکِ  الۡبَحۡرَ رَہۡوًا ؕ اِنَّہُمۡ جُنۡدٌ مُّغۡرَقُوۡنَ ﴿۲۴﴾', 'اور سمندر سے کہ ٹھہرا ہوا ہو گا پار ہو جانا تمہارے بعد وہ پورا لشکر ڈبو دیا جائے گا۔', 'اور چھوڑ جا دریا کو تھما ہوا البتہ وہ لشکر ڈوبنے والے ہیں [۲۰]', '\"And leave the sea as it is (quiet and divided). Verily, They are a host to be drowned.\"', 'and leave the sea in the state of stillness; they are an army that is sure to be drowned.”'),
(4439, 44, 25, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'کَمۡ  تَرَکُوۡا مِنۡ جَنّٰتٍ  وَّ عُیُوۡنٍ ﴿ۙ۲۵﴾', 'وہ لوگ بہت سے باغ اور چشمے چھوڑ گئے۔', 'بہت سے چھوڑ گئے باغ اور چشمے', 'How many of gardens and springs do they (Firauns (Pharaoh) people) left.', 'How many gardens and fountains have they left behind-'),
(4440, 44, 26, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'وَّ  زُرُوۡعٍ  وَّ  مَقَامٍ  کَرِیۡمٍ ﴿ۙ۲۶﴾', 'اور کھیتیاں اور نفیس مکان۔', 'اور کھیتیں اور گھر خاصے', 'And green crops (fields etc.) and goodly places,', '- and how many fields and noble sites,'),
(4441, 44, 27, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'وَّ  نَعۡمَۃٍ  کَانُوۡا فِیۡہَا  فٰکِہِیۡنَ ﴿ۙ۲۷﴾', 'اور آرام کی چیزیں جن میں وہ عیش کیا کرتے تھے۔', 'اور آرام کا سامان جس میں باتیں بنایا کرتے تھے', 'And comforts of life wherein they used to take delight!', 'and how many a luxury they used to rejoice in!'),
(4442, 44, 28, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'کَذٰلِکَ ۟ وَ  اَوۡرَثۡنٰہَا قَوۡمًا  اٰخَرِیۡنَ ﴿۲۸﴾', 'اسی طرح ہوا اور ہم نے دوسرے لوگوں کو ان چیزوں کا مالک بنا دیا۔', 'یونہی ہوا اور وہ سب ہاتھ لگا دیا ہم نے ایک دوسری قوم کے [۲۱]', 'Thus (it was)! And We made other people inherit them (i.e. We made the Children of Israel to inherit the kingdom of Egypt).', 'This is how it happened. And We made other people inherit all this.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(4443, 44, 29, 1, 14, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'فَمَا بَکَتۡ عَلَیۡہِمُ السَّمَآءُ  وَ الۡاَرۡضُ وَ مَا کَانُوۡا مُنۡظَرِیۡنَ ﴿٪۲۹﴾', 'پھر ان پر نہ تو آسمان اور زمین کو رونا آیا اور نہ انکو مہلت ہی دی گئ۔', 'پھر نہ رویا ان پر آسمان اور زمین  [۲۲] اور نہ ملی انکو ڈھیل', 'And the heavens and the earth wept not for them , nor were they given a respite.', 'So, neither the sky and earth wept over them, nor were they given a respite.'),
(4444, 44, 30, 2, 15, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'وَ لَقَدۡ نَجَّیۡنَا بَنِیۡۤ  اِسۡرَآءِیۡلَ  مِنَ الۡعَذَابِ  الۡمُہِیۡنِ ﴿ۙ۳۰﴾', 'اور ہم نے بنی اسرائیل کو ذلت کے عذاب سے نجات دی۔', 'اور ہم نے بچا نکالا بنی اسرائیل کو ذلت کی مصیبت سے', 'And indeed We saved the Children of Israel from the humiliating torment,', 'And We delivered the children of Isrā’īl from the humiliating punishment,'),
(4445, 44, 31, 2, 15, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'مِنۡ فِرۡعَوۡنَ ؕ اِنَّہٗ کَانَ عَالِیًا مِّنَ الۡمُسۡرِفِیۡنَ ﴿۳۱﴾', 'یعنی فرعون سے بیشک وہ سرکش اور حد سے نکلا ہوا تھا۔', 'جو فرعون کی طرف سے تھی [۲۳] بیشک وہ تھا چڑھ رہا حد سے بڑھ جانے والا [۲۴]', 'From Firaun (Pharaoh); Verily! He was arrogant and was of the Musrifoon (those who transgress beyond bound in spending and other things and commit great sins).', 'from Fir‘aun. Indeed, he was haughty, one of the transgressors.'),
(4446, 44, 32, 2, 15, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'وَ لَقَدِ  اخۡتَرۡنٰہُمۡ عَلٰی عِلۡمٍ عَلَی الۡعٰلَمِیۡنَ ﴿ۚ۳۲﴾', 'اور ہم نے بنی اسرائیل کو اہل عالم میں سے علم کی بنیاد پر چنا تھا۔', 'اور اُنکو ہم نے پسند کیا جان بوجھ کر جہان کے لوگوں سے [۲۵]', 'And We chose them (the Children of Israel) above the Alameen (mankind, and jinns) (during the time of Moosa (Moses)) with knowledge,', 'And We chose them, with knowledge, above all the worlds.'),
(4447, 44, 33, 2, 15, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'وَ اٰتَیۡنٰہُمۡ  مِّنَ الۡاٰیٰتِ مَا فِیۡہِ بَلٰٓـؤٌا مُّبِیۡنٌ ﴿۳۳﴾', 'اور انکو ایسی نشانیاں دی تھیں جن میں کھلی آزمائش تھی۔', 'اور دیں  ہم نے انکو نشانیاں جن میں تھی مدد صریح [۲۶]', 'And granted them signs in which there was a plain trial.', 'And We gave them the clear signs in which there was a manifest blessing.'),
(4448, 44, 34, 2, 15, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'اِنَّ  ہٰۤؤُلَآءِ  لَیَقُوۡلُوۡنَ ﴿ۙ۳۴﴾', 'یہ لوگ یہ کہتے ہیں۔', 'یہ لوگ کہتے ہیں', 'Verily, these (Quraish) people are saying:', 'These people say,'),
(4449, 44, 35, 2, 15, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'اِنۡ ہِیَ  اِلَّا مَوۡتَتُنَا الۡاُوۡلٰی وَ مَا نَحۡنُ بِمُنۡشَرِیۡنَ ﴿۳۵﴾', 'کہ ہمیں صرف پہلی دفعہ یعنی ایک بار مرنا ہے اور پھر اٹھنا نہیں۔', 'اور کچھ نہیں ہمارا یہی مرنا ہے پہلا اور ہمکو پھر اٹھنا نہیں [۲۷]', '\"There is nothing but our first death, and we shall not be resurrected.', '“There is nothing more than our first death, and we are not going to be resurrected.'),
(4450, 44, 36, 2, 15, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'فَاۡتُوۡا بِاٰبَآئِنَاۤ  اِنۡ  کُنۡتُمۡ صٰدِقِیۡنَ ﴿۳۶﴾', 'پس اگر تم سچے ہو تو ہمارے باپ دادا کو زندہ کر لاؤ۔', 'بھلا لے تو آؤ ہمارے باپ دادوں کو اگر تم سچے ہو [۲۸]', '\"Then bring back our fore-fathers, if you speak the truth!\"', 'So, (O believers,) bring our fathers, if you are true (in your belief in resurrection.)”'),
(4451, 44, 37, 2, 15, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'اَہُمۡ خَیۡرٌ  اَمۡ قَوۡمُ تُبَّعٍ ۙ وَّ الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ ؕ اَہۡلَکۡنٰہُمۡ ۫ اِنَّہُمۡ کَانُوۡا مُجۡرِمِیۡنَ ﴿۳۷﴾', 'بھلا یہ اچھے ہیں یا تبعّ کی قوم اور وہ لوگ جو ان سے پہلے ہو چکے ہیں۔ ہم نے ان سب کو ہلاک کر دیا۔ بیشک وہ گنہگار تھے۔', 'بھلا یہ بہتر ہیں یا تُبّع کی قوم [۲۹] اور جو اُن سے پہلے تھے ہم  نے اُنکو غارت کر دیا بیشک وہ تھے گنہگار [۳۰]', 'Are they better or the people of Tubba and those before them? We destroyed them because they were indeed Mujrimoon (disbelievers, polytheists, sinners, criminals, etc.).', 'Are they better or the people of Tubba‘ and those who were before them? We have destroyed them. They were guilty indeed.'),
(4452, 44, 38, 2, 15, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'وَ مَا خَلَقۡنَا السَّمٰوٰتِ وَ الۡاَرۡضَ وَ مَا بَیۡنَہُمَا لٰعِبِیۡنَ ﴿۳۸﴾', 'اور ہم نے آسمانوں اور زمین کو اور جو کچھ ان میں ہے اسکو کھیل کیلئے نہیں بنایا۔', 'اور ہم نے جو بنایا آسمان اور زمین اور جو اُنکے بیچ ہے کھیل نہیں بنایا', 'And We created not the heavens and the earth, and all that is between them, for mere play,', 'And We did not create the heavens and the earth and what is between them just as players.'),
(4453, 44, 39, 2, 15, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'مَا خَلَقۡنٰہُمَاۤ  اِلَّا بِالۡحَقِّ وَ لٰکِنَّ اَکۡثَرَہُمۡ  لَا یَعۡلَمُوۡنَ ﴿۳۹﴾', 'انکو ہم نے تدبیر سے پیدا کیا ہے لیکن اکثر لوگ نہیں جانتے۔', 'اُنکو تو بنایا ہم نے ٹھیک کام پر بہت لوگ نہیں سمجھتے [۳۱]', 'We created them not except with truth (i.e. to examine and test those who are obedient and those who are disobedient and then reward the obedient ones and punish the disobedient ones), but most of them know not.', 'We did not create them but with true purpose, but most of them do not know.'),
(4454, 44, 40, 2, 15, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'اِنَّ یَوۡمَ الۡفَصۡلِ مِیۡقَاتُہُمۡ  اَجۡمَعِیۡنَ ﴿ۙ۴۰﴾', 'کچھ شک نہیں کہ فیصلے کا دن ان سب کے جی اٹھنے کا وقت ہے۔', 'تحقیق فیصلہ کا دن وعدہ ہے اُن سب کا [۳۲]', 'Verily, the Day of Judgement (when Allah will judge between the creatures) is the time appointed for all of them,', 'The Day of Decision is the appointed time for all of them-'),
(4455, 44, 41, 2, 15, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'یَوۡمَ لَا یُغۡنِیۡ مَوۡلًی عَنۡ مَّوۡلًی شَیۡئًا وَّ لَا  ہُمۡ  یُنۡصَرُوۡنَ ﴿ۙ۴۱﴾', 'جس دن کوئی دوست کسی دوست کے کچھ کام نہ آئے گا اور نہ انکو مدد ملے گی۔', 'جس دن کام نہ آئے کوئی رفیق کسی رفیق کے کچھ بھی اور نہ اُنکو مدد پہنچے [۳۳]', 'The Day when Maulan (a near relative) cannot avail Maulan (a near relative) in aught, and no help can they receive,', 'the day when no close relation will be of any use to any close relation, nor will they be helped,'),
(4456, 44, 42, 2, 15, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'اِلَّا مَنۡ رَّحِمَ اللّٰہُ ؕ اِنَّہٗ  ہُوَ الۡعَزِیۡزُ الرَّحِیۡمُ ﴿٪۴۲﴾', 'مگر جس پر اللہ مہربانی کرے بیشک وہی غالب ہے بڑا مہربان ہے۔', 'مگر جس پر رحم کرے اللہ بیشک وہی ہے زبردست رحم والا [۳۴]', 'Except him on whom Allah has Mercy. Verily, He is the All-Mighty, the Most Merciful.', 'except the One on whom Allah has mercy. Of course, He is the All-Mighty, the Very-Merciful.'),
(4457, 44, 43, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'اِنَّ  شَجَرَتَ الزَّقُّوۡمِ ﴿ۙ۴۳﴾', 'بلاشبہ تھوہر کا درخت۔', 'مقرر درخت سیہنڈ کا', 'Verily, the tree of Zaqqoom,', 'Indeed the tree of zaqqūm'),
(4458, 44, 44, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'طَعَامُ  الۡاَثِیۡمِ ﴿ۖۛۚ۴۴﴾', 'گنہگاروں کا کھانا ہو گا۔', 'کھانا ہے گنہگار کا [۳۵]', 'Will be the food of the sinners,', 'is the food of the sinful,'),
(4459, 44, 45, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'کَالۡمُہۡلِ ۚۛ یَغۡلِیۡ  فِی الۡبُطُوۡنِ ﴿ۙ۴۵﴾', 'جیسے پگھلا ہوا تانبا۔ وہ تھوہر پیٹوں میں اس طرح کھولے گا۔', 'جیسے پگھلا ہوا تانبا کھولتا ہے پیٹوں میں', 'Like boiling oil, it will boil in the bellies,', 'like dregs of oil. It will boil in the bellies'),
(4460, 44, 46, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'کَغَلۡیِ  الۡحَمِیۡمِ ﴿۴۶﴾', 'جس طرح گرم پانی کھولتا ہے۔', 'جیسے کھولتا ہوا پانی', 'Like the boiling of scalding water.', 'like the boiling of hot water.'),
(4461, 44, 47, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'خُذُوۡہُ فَاعۡتِلُوۡہُ  اِلٰی سَوَآءِ الۡجَحِیۡمِ ﴿٭ۖ۴۷﴾', 'حکم دیا جائے گا کہ اسکو پکڑ لو اور کھینچتے ہوئے دوزخ کے بیچوں بیچ لے جاؤ۔', 'پکڑو اسکو اور دھکیل کر لیجاؤ  بیچوں بیچ  دوزخ کے [۳۶]', '(It will be said) \"Seize him and drag him into the midst of blazing Fire,', '(It will be said to angels,) “Seize him, and drag him into the midst of the Hell.'),
(4462, 44, 48, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'ثُمَّ صُبُّوۡا فَوۡقَ رَاۡسِہٖ  مِنۡ عَذَابِ الۡحَمِیۡمِ ﴿ؕ۴۸﴾', 'پھر اسکے سر پر کھولتا ہوا پانی انڈیل دو کہ عذاب پر عذاب ہو۔', 'پھر ڈالو اُسکے سر پر جلتے پانی کا عذاب [۳۷]', '\"Then pour over his head the torment of boiling water,', 'Then pour on his head some torment of boiling water.”'),
(4463, 44, 49, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'ذُقۡ ۚۙ  اِنَّکَ اَنۡتَ الۡعَزِیۡزُ  الۡکَرِیۡمُ ﴿۴۹﴾', 'اب مزہ چکھ تو بڑی عزت والا اور سردار تھا۔', 'یہ چکھ تو ہی ہے بڑا عزت والا سردار [۳۸]', '\"Taste you (this)! Verily, you were (pretending to be) the mighty, the generous!', '“Have a taste! You are the ‘man of might’, the ‘man of honour’.'),
(4464, 44, 50, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'اِنَّ ہٰذَا مَا کُنۡتُمۡ بِہٖ  تَمۡتَرُوۡنَ ﴿۵۰﴾', 'یہ وہی دوزخ ہے جس میں تم لوگ شک کیا کرتے تھے۔', 'یہ وہی ہے جس میں تم دھوکے میں پڑے تھے [۳۹]', '\"Verily! This is that whereof you used to doubt!\"', 'This is the thing about which you used to be skeptic.”'),
(4465, 44, 51, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'اِنَّ  الۡمُتَّقِیۡنَ فِیۡ  مَقَامٍ  اَمِیۡنٍ ﴿ۙ۵۱﴾', 'بیشک پرہیزگار لوگ چین کے مقام میں ہوں گے۔', 'بیشک ڈرنے والے گھر میں ہیں چین کے [۴۰]', 'Verily! The Muttaqoon (pious - see V.2:2), will be in place of Security (Paradise).', 'Indeed the God-fearing will be in a place free from fear,'),
(4466, 44, 52, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'فِیۡ  جَنّٰتٍ وَّ عُیُوۡنٍ ﴿ۚۙ۵۲﴾', 'یعنی باغوں اور چشموں میں۔', 'باغوں میں اور چشموں میں', 'Among Gardens and Springs;', 'in gardens and fountains.'),
(4467, 44, 53, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'یَّلۡبَسُوۡنَ مِنۡ سُنۡدُسٍ وَّ اِسۡتَبۡرَقٍ مُّتَقٰبِلِیۡنَ ﴿ۚۙ۵۳﴾', 'باریک اور دبیز ریشم کا لباس پہن کر ایک دوسرے کے سامنے بیٹھے ہوں گے۔', 'پہنتے ہیں پوشاک ریشمی پتلی اور گاڑھی ایک دوسرے کے سامنے [۴۱]', 'Dressed in fine silk and (also) in thick silk, facing each other,', 'They will be dressed in fine silk and thick silk, facing each other.'),
(4468, 44, 54, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'کَذٰلِکَ ۟ وَ  زَوَّجۡنٰہُمۡ  بِحُوۡرٍ عِیۡنٍ ﴿ؕ۵۴﴾', 'وہاں اس طرح کا حال ہو گا اور ہم بڑی بڑی آنکھوں والی حوروں کو انکی بیویاں بنا دینگے۔', 'اسی طرح ہو گا اور بیاہ دیں گے ہم اُنکو حوریں بڑی آنکھوں والیاں [۴۲]', 'So (it will be), and We shall marry them to Houris (female fair ones) with wide, lovely eyes.', 'Thus (it will happen,) and We will marry them with houris having big dark eyes.'),
(4469, 44, 55, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'یَدۡعُوۡنَ فِیۡہَا بِکُلِّ فَاکِہَۃٍ  اٰمِنِیۡنَ ﴿ۙ۵۵﴾', 'وہاں امن و اطمینان سے ہر قسم کے میوے منگائیں گے اور کھائیں گے۔', 'منگوائیں گے  وہاں ہر میوہ دل جمعی سے [۴۳]', 'They will call therein for every kind of fruit in peace and security;', 'They will call therein for every fruit peacefully.'),
(4470, 44, 56, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'لَا یَذُوۡقُوۡنَ فِیۡہَا الۡمَوۡتَ  اِلَّا الۡمَوۡتَۃَ الۡاُوۡلٰی ۚ وَ وَقٰہُمۡ  عَذَابَ  الۡجَحِیۡمِ ﴿ۙ۵۶﴾', 'اور پہلی دفعہ کے مرنے کے علاوہ موت کا مزہ پھر نہیں چکھیں گے۔ اور اللہ انکو دوزخ کے عذاب سے بچا لے گا۔', 'نہ چکھیں گے وہاں  موت مگر جو پہلے آچکی [۴۴] اور بچایا انکو دوزخ کے عذاب سے', 'They will never taste death therein except the first death (of this world), and He will save them from the torment of the blazing Fire,', 'They will not taste death therein beyond the first death (they faced in the world). And He (Allah) will save them from the torment of Hell,'),
(4471, 44, 57, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'فَضۡلًا  مِّنۡ  رَّبِّکَ ؕ ذٰلِکَ ہُوَ الۡفَوۡزُ الۡعَظِیۡمُ ﴿۵۷﴾', 'یہ تمہارے پروردگار کا فضل ہے۔ یہی تو بڑی کامیابی ہے۔', 'فضل سے تیرے رب کے یہی ہے بڑی مراد ملنی [۴۵]', 'As a Bounty from your Lord! That will be the supreme success!', 'as a favour from your Lord. That is the great achievement.'),
(4472, 44, 58, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'فَاِنَّمَا یَسَّرۡنٰہُ  بِلِسَانِکَ لَعَلَّہُمۡ یَتَذَکَّرُوۡنَ ﴿۵۸﴾', 'ہم نے اس قرآن کو تمہاری زبان میں آسان کر دیا ہے تاکہ یہ لوگ نصیحت حاصل کریں۔', 'سو یہ قرآن آسان کیا ہم نے اسکو تیری بولی میں تاکہ وہ  یاد رکھیں [۴۶]', 'Certainly, We have made this (Quran) easy in your tongue, in order that they may remember.', 'So, We had made it (the Qur’ān) easy in your tongue, so that they may take lesson.'),
(4473, 44, 59, 3, 16, 25, 'اِلَیۡہِ یُرَدّ', 'الدُّخَان', 'فَارۡتَقِبۡ  اِنَّہُمۡ   مُّرۡتَقِبُوۡنَ ﴿٪۵۹﴾', 'پس تم بھی انتظار کرو یہ بھی انتظار کر رہے ہیں۔', 'اب تو راہ دیکھ وہ بھی راہ تکتے ہیں [۴۷]', 'Wait then (O Muhammad SAW); Verily, they (too) are waiting.', 'Now wait. They too are waiting.'),
(4474, 45, 1, 1, 17, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'حٰمٓ ۚ﴿۱﴾', 'حٰمٓ۔', 'حٰمٓ۔', 'HaMeem. (These letters are one of the miracles of the Quran and none but Allah (Alone) knows their meanings).', 'Hā Mīm .'),
(4475, 45, 2, 1, 17, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'تَنۡزِیۡلُ  الۡکِتٰبِ مِنَ اللّٰہِ  الۡعَزِیۡزِ الۡحَکِیۡمِ ﴿۲﴾', 'اس کتاب کا اتارا جانا اللہ کی طرف سے ہے جو غالب ہے دانا ہے۔', 'اتارنا کتاب کا ہے اللہ کی طرف سے جو زبردست ہے حکمتوں والا', 'The revelation of the Book (this Quran) is from Allah, the All-Mighty, the All-Wise.', 'This is revelation of the Book from Allah, the All-Mighty, the All-Wise.'),
(4476, 45, 3, 1, 17, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'اِنَّ فِی السَّمٰوٰتِ وَ الۡاَرۡضِ لَاٰیٰتٍ لِّلۡمُؤۡمِنِیۡنَ ؕ﴿۳﴾', 'بیشک آسمانوں اور زمین میں ایمان والوں کے لئے اللہ کی قدرت کی نشانیاں ہیں۔', 'بیشک آسمانوں میں اور زمین میں بہت نشانیاں ہیں ماننے والوں کے واسطے [۱]', 'Verily, in the heavens and the earth are signs for the believers.', 'Surely in the heavens and the earth, there are signs for those who have faith.'),
(4477, 45, 4, 1, 17, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَ فِیۡ خَلۡقِکُمۡ  وَ مَا یَبُثُّ مِنۡ دَآبَّۃٍ اٰیٰتٌ لِّقَوۡمٍ  یُّوۡقِنُوۡنَ ۙ﴿۴﴾', 'اور تمہاری پیدائش میں بھی اور جانوروں میں بھی جنکو وہ پھیلاتا ہے یقین کرنے والوں کے لئے نشانیاں ہیں۔', 'اور تمہارے بنانے میں اور جس قدر پھیلا رکھے ہیں جانور نشانیاں ہیں ان لوگوں کے واسطے جو یقین رکھتےہیں [۲]', 'And in your creation, and what He scattered (through the earth) of moving (living) creatures are signs for people who have Faith with certainty.', 'And in your creation and in the living beings that He scatters on the earth, there are signs for a people who believe.'),
(4478, 45, 5, 1, 17, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَ اخۡتِلَافِ الَّیۡلِ وَ النَّہَارِ  وَ مَاۤ  اَنۡزَلَ اللّٰہُ  مِنَ السَّمَآءِ مِنۡ  رِّزۡقٍ فَاَحۡیَا بِہِ الۡاَرۡضَ بَعۡدَ مَوۡتِہَا وَ تَصۡرِیۡفِ الرِّیٰحِ اٰیٰتٌ لِّقَوۡمٍ یَّعۡقِلُوۡنَ ﴿۵﴾', 'اور رات اور دن کے آگے پیچھے آنے جانے میں اور وہ جو اللہ نے آسمان سے ذریعہ رزق نازل فرمایا پھر اس سے زمین کو اسکے مردہ ہو جانے کے بعد زندہ کیا اس میں اور ہواؤں کے گردش دینے میں عقل والوں کے لئے نشانیاں ہیں۔', 'اور بدلنے میں رات دن کے  اور  وہ جو اتاری اللہ نے آسمان سے روزی [۳] پھر زندہ کر دیا اس سے زمین کو اس کے مرجانے کے بعد اور بدلنے میں ہواؤں کے نشانیان ہیں ان لوگوں کے واسطے جو سمجھ سےکام لیتے ہیں [۴]', 'And in the alternation of night and day, and the provision (rain) that Allah sends down from the sky, and revives therewith the earth after its death, and in the turning about of the winds (i.e. sometimes towards the east or north, and sometimes towards the south or west etc., sometimes bringing glad tidings of rain etc., and sometimes bringing the torment), are signs for a people who understand.', 'And in the alternation of the day and the night, and in the provision He has sent down from the sky, then has revived the earth after its death, and in changing of the winds, there are signs for a people who understand.'),
(4479, 45, 6, 1, 17, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'تِلۡکَ اٰیٰتُ اللّٰہِ  نَتۡلُوۡہَا عَلَیۡکَ بِالۡحَقِّ ۚ فَبِاَیِّ حَدِیۡثٍۭ بَعۡدَ اللّٰہِ  وَ اٰیٰتِہٖ یُؤۡمِنُوۡنَ ﴿۶﴾', 'یہ اللہ کی آیتیں ہیں جو ہم تمکو سچائی کے ساتھ پڑھ کر سناتے ہیں۔ تو یہ اللہ اور اسکی آیتوں کے بعد کس بات پر ایمان لائیں گے۔', 'یہ باتیں ہیں اللہ کی ہم سناتے ہیں تجھ کو ٹھیک ٹھیک پھر کونسی بات کو اللہ اور اسکی باتوں کو  چھوڑ کر مانیں گے [۵]', 'These are the Ayat (proofs, evidences, verses, lessons, revelations, etc.) of Allah, which We recite to you (O Muhammad SAW) with truth. Then in which speech after Allah and His Ayat will they believe?', 'These are Allah’s verses that We recite to you rightly. Then, in which discourse, after Allah and His verses, will they believe?'),
(4480, 45, 7, 1, 17, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَیۡلٌ   لِّکُلِّ   اَفَّاکٍ  اَثِیۡمٍ ۙ﴿۷﴾', 'ہر جھوٹے گنہگار پر افسوس ہے۔', 'خرابی ہے ہر جھوٹے گنہگار کے لئے', 'Woe to every sinful liar,', 'Woe to every sinful liar,'),
(4481, 45, 8, 1, 17, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'یَّسۡمَعُ  اٰیٰتِ اللّٰہِ  تُتۡلٰی عَلَیۡہِ  ثُمَّ  یُصِرُّ مُسۡتَکۡبِرًا  کَاَنۡ  لَّمۡ  یَسۡمَعۡہَا ۚ فَبَشِّرۡہُ بِعَذَابٍ  اَلِیۡمٍ ﴿۸﴾', 'کہ اللہ کی آیتیں اسکو پڑھ کر سنائی جاتی ہیں تو انکو سن تو لیتا ہے مگر پھر غرور سے ضد کرتا ہے کہ گویا انکو سنا ہی نہیں۔ سو ایسے شخص کو دکھ دینے والے عذاب کی خوشخبری سنا دو۔', 'کہ سنتا ہے باتیں اللہ کی اسکے پاس پڑھی جاتی ہیں پھر ضد کرتا ہے غرور سے گویا سنا ہی نہیں [۶] سو خوشخبری سنا دے اسکو ایک عذاب دردناک کی', 'Who hears the Verses of Allah (being) recited to him, yet persists with pride as if he heard them not. So announce to him a painful torment!', 'who hears Allah’s verses being recited to him, then he remains adamant out of arrogance, as if he never heard them. So give him the ‘good news’ of a painful punishment.'),
(4482, 45, 9, 1, 17, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَ اِذَا عَلِمَ مِنۡ اٰیٰتِنَا شَیۡئَۨا اتَّخَذَہَا ہُزُوًا ؕ اُولٰٓئِکَ  لَہُمۡ عَذَابٌ مُّہِیۡنٌ ؕ﴿۹﴾', 'اور جب ہماری کچھ آیتیں اسے معلوم ہوتی ہیں تو انکی ہنسی اڑاتا ہے ایسے لوگوں کے لئے ذلیل کرنے والا عذاب ہے۔', 'اور جب خبر پائے ہماری باتوں میں سے کسی کی  اسکو ٹھہرائے ٹھٹھا ایسوں کو ذلت کا عذاب ہے [۷]', 'And when he learns something of Our Verses (this Quran), he makes them a jest. For such there will be a humiliating torment.', 'When he learns about something of Our verses, he takes it as a laughing stock. For such people, there is a humiliating punishment.'),
(4483, 45, 10, 1, 17, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'مِنۡ  وَّرَآئِہِمۡ جَہَنَّمُ ۚ وَ لَا یُغۡنِیۡ عَنۡہُمۡ مَّا کَسَبُوۡا شَیۡئًا وَّ لَا مَا اتَّخَذُوۡا مِنۡ دُوۡنِ اللّٰہِ  اَوۡلِیَآءَ ۚ وَ لَہُمۡ عَذَابٌ عَظِیۡمٌ ﴿ؕ۱۰﴾', 'انکے پیچھے دوزخ ہے۔ اور جو بھی یہ کرتے رہے کچھ بھی انکے کام نہ آئے گا۔ اور نہ وہی کام آئیں گے جنکو انہوں نے اللہ کے سوا معبود بنا رکھا تھا۔ اور انکے لئے بڑا عذاب ہے۔', 'پرے انکے دزوخ ہے اور کام نہ آئے گا انکے جو کمایا تھا ذرا بھی اور نہ وہ کہ جنکو  پکڑا تھا اللہ کے سوائے رفیق [۸] اور اُنکے واسطے بڑا عذاب ہے', 'In front of them there is Hell, and that which they have earned will be of no profit to them, nor (will be of any profit to them) those whom they have taken as Auliya (protectors, helpers, etc.) besides Allah. And theirs will be a great torment.', 'In front of them, there is Jahannam (Hell). And whatever they have earned will not be of any use to them, nor the patrons they have adopted instead of Allah. And for them, there is a horrible punishment.'),
(4484, 45, 11, 1, 17, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'ہٰذَا ہُدًی ۚ وَ الَّذِیۡنَ  کَفَرُوۡا بِاٰیٰتِ رَبِّہِمۡ   لَہُمۡ عَذَابٌ  مِّنۡ  رِّجۡزٍ  اَلِیۡمٌ ﴿٪۱۱﴾', 'یہ ہدایت کی کتاب ہے۔ اور جو لوگ اپنے پروردگار کی آیتوں سے انکار کرتے ہیں انکو سخت قسم کا درد دینے والا عذاب ہو گا۔', 'یہ سجھا دیا اور جو منکر ہیں اپنے رب کی باتوں سے انکے لئے عذاب ہے ایک بلا کا دردناک [۹]', 'This (Quran) is a guidance. And those who disbelieve in the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) of their Lord, for them there is a painful torment of Rijz (a severe kind of punishment).', 'This is guidance, and those who reject the verses of their Lord, for them there is a painful punishment of the divine scourge.'),
(4485, 45, 12, 2, 18, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'اَللّٰہُ  الَّذِیۡ سَخَّرَ  لَکُمُ  الۡبَحۡرَ  لِتَجۡرِیَ الۡفُلۡکُ فِیۡہِ بِاَمۡرِہٖ وَ لِتَبۡتَغُوۡا مِنۡ فَضۡلِہٖ  وَ لَعَلَّکُمۡ   تَشۡکُرُوۡنَ ﴿ۚ۱۲﴾', 'اللہ ہی تو ہے جس نے سمندر کو تمہارے قابو میں کر دیا تاکہ اسکے حکم سے اس میں کشتیاں چلیں اور تاکہ تم اسکے فضل سے معاش تلاش کرو اور تاکہ شکر کرو۔', 'اللہ وہ ہے جس نے بس میں کر دیا تمہارے دریا کو کہ چلیں اس میں جہاز اس کے حکم سے [۱۰] اور تاکہ تلاش کرو اسکے فضل سے اور تاکہ تم حق مانو [۱۱]', 'Allah it is He Who has subjected to you the sea, that ships may sail through it by His Command, and that you may seek of His Bounty, and that you may be thankful,', 'Allah is the One who has subjugated for you the sea, so that the ships may sail in it with His command, and so that you may seek His grace, and so that you offer gratitude.'),
(4486, 45, 13, 2, 18, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَ سَخَّرَ  لَکُمۡ  مَّا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ جَمِیۡعًا مِّنۡہُ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیٰتٍ  لِّقَوۡمٍ  یَّتَفَکَّرُوۡنَ ﴿۱۳﴾', 'اور جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے سب کو اسی نے اپنے حکم سے تمہارے کام میں لگا دیا۔ جو لوگ غور کرتے ہیں انکے لئے اس میں قدرت کی نشانیاں ہیں۔', 'اور کام میں لگا دیا تمہارے جو کچھ ہے آسمانوں میں اور زمین میں سب کو اپنی طرف سے [۱۲] اس میں نشانیاں ہیں ان لوگوں کے واسطے جو دھیان کرتے ہیں [۱۳]', 'And has subjected to you all that is in the heavens and all that is in the earth; it is all as a favour and kindness from Him. Verily, in it are signs for a people who think deeply.', 'He has subjugated for you whatever there is in the heavens and whatever there is in the earth, all on His own. Surely in this there are signs for a people who reflect.'),
(4487, 45, 14, 2, 18, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'قُلۡ  لِّلَّذِیۡنَ اٰمَنُوۡا یَغۡفِرُوۡا لِلَّذِیۡنَ لَا یَرۡجُوۡنَ اَیَّامَ اللّٰہِ  لِیَجۡزِیَ قَوۡمًۢا بِمَا کَانُوۡا  یَکۡسِبُوۡنَ ﴿۱۴﴾', 'مومنوں سے کہدو کہ جو لوگ اللہ کے دنوں کی جو اعمال کے بدلے کے لئے مقرر ہیں توقع نہیں رکھتے ان سے درگذر کریں تاکہ اللہ ان لوگوں کو انکے اعمال کا بدلہ دے۔', 'کہہ دے ایمان والوں کو درگذر کریں ان سے جو امید نہیں رکھتے اللہ کے دنوں کی [۱۴] تاکہ وہ سزا دے ایک قوم کو بدلا اس کا جو کماتے تھے [۱۵]', 'Say (O Muhammad SAW) to the believers to forgive those who (harm them and) hope not for the Days of Allah (i.e. His Recompense), that He may recompense people according to what they have earned (i.e. to punish these disbelievers, who harm the believers).', 'Tell those who believe that they should forgive those who do not believe in Allah’s days, so that He may recompense a people for what they used to earn.'),
(4488, 45, 15, 2, 18, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'مَنۡ عَمِلَ  صَالِحًا فَلِنَفۡسِہٖ ۚ وَ مَنۡ اَسَآءَ  فَعَلَیۡہَا ۫ ثُمَّ  اِلٰی  رَبِّکُمۡ تُرۡجَعُوۡنَ ﴿۱۵﴾', 'جو کوئی عمل نیک کرے گا تو اپنے لئے اور جو برے کام کرے گا تو ان کا ضرر بھی اسی کو ہو گا پھر تم اپنے پروردگار کی طرف لوٹ کر جاؤ گے۔', 'جس نے بھلا کام کیا تو اپنے واسطے اور جس نے  برا کیا سو اپنے حق میں [۱۶] پھر اپنے رب کی طرف پھیرے جاؤ گے [۱۷]', 'Whosoever does a good deed, it is for his ownself, and whosoever does evil, it is against (his ownself). Then to your Lord you will be made to return.', 'Whoever acts righteously, it is for his own benefit, and who does evil, it is against his own soul. Then towards your Lord, you will be returned.'),
(4489, 45, 16, 2, 18, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَ لَقَدۡ  اٰتَیۡنَا بَنِیۡۤ  اِسۡرَآءِیۡلَ  الۡکِتٰبَ وَ الۡحُکۡمَ وَ النُّبُوَّۃَ وَ رَزَقۡنٰہُمۡ مِّنَ الطَّیِّبٰتِ وَ فَضَّلۡنٰہُمۡ عَلَی الۡعٰلَمِیۡنَ ﴿ۚ۱۶﴾', 'اور ہم نے بنی اسرائیل کو کتاب ہدایت اور حکومت اور نبوت بخشی اور پاکیزہ چیزیں عطا فرمائیں اور اہل عالم پر انکو فضیلت دی۔', 'اور ہم نے دی بنی اسرائیل کو کتاب اور حکومت اور پیغمبری اور کھانے کو  دیں ستھری چیزیں [۱۸] اور بزرگی دی انکو جہان پر [۱۹]', 'And indeed We gave the Children of Israel the Scripture, and the understanding of the Scripture and its laws, and the Prophethood; and provided them with good things, and preferred them above the Alameen (mankind and jinns) (of their time, during that period),', 'We gave the children of Isrā’īl the book and the wisdom and the prophet-hood, and provided them with good things, and preferred them above all (people of) the world,'),
(4490, 45, 17, 2, 18, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَ اٰتَیۡنٰہُمۡ  بَیِّنٰتٍ مِّنَ الۡاَمۡرِ ۚ فَمَا اخۡتَلَفُوۡۤا  اِلَّا مِنۡۢ بَعۡدِ مَا جَآءَہُمُ الۡعِلۡمُ ۙ بَغۡیًۢا بَیۡنَہُمۡ  ؕ اِنَّ  رَبَّکَ یَقۡضِیۡ بَیۡنَہُمۡ یَوۡمَ الۡقِیٰمَۃِ  فِیۡمَا کَانُوۡا فِیۡہِ یَخۡتَلِفُوۡنَ ﴿۱۷﴾', 'اور انکو دین کے بارے میں دلیلیں عطا کیں۔ تو انہوں نے جو اختلاف کیا تو علم آ چکنے کے بعد آپس کی ضد سے کیا۔ بیشک تمہارا پروردگار قیامت کے دن ان میں ان باتوں کا جن میں وہ اختلاف کرتے تھے فیصلہ کر دے گا۔', 'اور دیں اُنکو کھلی باتیں دین کی [۲۰] پھر انہوں نے پھوٹ جو ڈالی تو سمجھ آ چکنے کے بعد آپس کی ضد سے بیشک تیرا رب فیصلہ کرے گا ان میں قیامت کے دن جس بات میں وہ جھگڑتے تھے [۲۱]', 'And gave them clear proofs in matters (by revealing to them the Taurat (Torah)). And they differed not until after the knowledge came to them, through envy among themselves. Verily, Your Lord will judge between them on the Day of Resurrection about that wherein they used to differ.', 'and We gave them clear proofs of the Matter (i.e. the religion). So they did not fall into disagreement out of mutual jealousy, but after the knowledge had come to them. Surely your Lord will judge between them, on the Day of Judgment, in the matters in which they used to differ.'),
(4491, 45, 18, 2, 18, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'ثُمَّ جَعَلۡنٰکَ عَلٰی شَرِیۡعَۃٍ  مِّنَ الۡاَمۡرِ فَاتَّبِعۡہَا وَ لَا تَتَّبِعۡ  اَہۡوَآءَ الَّذِیۡنَ لَا یَعۡلَمُوۡنَ ﴿۱۸﴾', 'پھر ہم نے تمکو دین کے کھلے رستے پر قائم کر دیا تو اسی رستے پر چلے چلو اور نادانوں کی خواہشوں کے پیچھے نہ چلنا۔', 'پھر تجھ کو رکھا ہم نے ایک رستہ پر دین کے کام کے سو تو اسی پر چل اور مت چل خواہشوں پر نادانوں کی [۲۲]', 'Then We have put you (O Muhammad SAW) on a plain way of (Our) commandment (like the one which We commanded Our Messengers before you (i.e. legal ways and laws of the Islamic Monotheism)). So follow you that (Islamic Monotheism and its laws), and follow not the desires of those who know not. (Tafsir At-Tabaree Vol. 25, Page 146).', 'Then We have put you on a certain way of the Matter (i.e. the religion); so follow it, and do not follow the desires of those who do not know.'),
(4492, 45, 19, 2, 18, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'اِنَّہُمۡ  لَنۡ  یُّغۡنُوۡا عَنۡکَ مِنَ  اللّٰہِ  شَیۡئًا ؕ وَ  اِنَّ الظّٰلِمِیۡنَ بَعۡضُہُمۡ  اَوۡلِیَآءُ  بَعۡضٍ ۚ وَ اللّٰہُ   وَلِیُّ   الۡمُتَّقِیۡنَ ﴿۱۹﴾', 'یہ اللہ کے سامنے تمہارے کسی کام نہیں آئیں گے۔ اور ظالم لوگ آپس میں ایک دوسرے کے دوست ہوتے ہیں۔ اور اللہ پرہیزگاروں کا دوست ہے۔', 'وہ ہر گز کام نہ آئیں گے تیرے اللہ کے سامنے ذرا بھی [۲۳] اور بے انصاف ایک دوسرے کے رفیق ہیں اور اللہ رفیق ہے ڈرنے والوں کا [۲۴]', 'Verily, they can avail you nothing against Allah (if He wants to punish you). Verily, the Zalimoon (polytheists, wrong-doers, etc.) are Auliya (protectors, helpers, etc.) to one another, but Allah is the Walee (Helper, Protector, etc.) of the Muttaqoon (pious - see V.2:2).', 'They will never help you against Allah in the least. The wrongdoers are friends to one another, and Allah is the friend of the God-fearing.'),
(4493, 45, 20, 2, 18, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'ہٰذَا بَصَآئِرُ  لِلنَّاسِ وَ ہُدًی  وَّ  رَحۡمَۃٌ لِّقَوۡمٍ  یُّوۡقِنُوۡنَ ﴿۲۰﴾', 'یہ قرآن لوگوں کے لئے دانائی کی باتیں ہیں۔ اور جو یقین رکھتے ہیں انکے لئے ہدایت اور رحمت ہے۔', 'یہ سوجھ کی باتیں ہیں لوگوں کے واسطے اور راہ کی اور رحمت ہے ان لوگوں کے لئے جو یقین لاتے ہیں [۲۵]', 'This (Quran) is a clear insight and evidence for mankind, and a guidance and a mercy for people who have Faith with certainty .', 'These are insights for the people, and guidance and mercy for a people who believe.'),
(4494, 45, 21, 2, 18, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'اَمۡ  حَسِبَ الَّذِیۡنَ اجۡتَرَحُوا  السَّیِّاٰتِ اَنۡ نَّجۡعَلَہُمۡ کَالَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ ۙ سَوَآءً  مَّحۡیَاہُمۡ وَ مَمَاتُہُمۡ ؕ سَآءَ  مَا یَحۡکُمُوۡنَ ﴿٪۲۱﴾', 'جو لوگ برے کام کرتے ہیں کیا وہ یہ خیال کرتے ہیں کہ ہم انکو ان لوگوں جیسا کر دیں گے جو ایمان لائے اور عمل نیک کرتے رہے اور انکی زندگی اور موت یکساں ہو گی۔ یہ جو دعوے کرتے ہیں برے ہیں۔', 'کیا خیال رکھتے ہیں جنہوں نے کمائی ہیں برائیاں کہ ہم کر دیں گے انکو برابر ان لوگوں کی جو کہ یقین لائے اور کیے بھلے کام ایک سا ہے ان کا جینا اور مرنا برے دعوے ہیں جو کرتے ہیں [۲۶]', 'Or do those who earn evil deeds think that We shall hold them equal with those who believe (in the Oneness of Allah Islamic Monotheism) and do righteous good deeds, in their present life and after their death? Worst is the judgement that they make.', 'Do those who have committed evils assume that We will make them like those who believe and do righteous deeds, so as their life and death becomes equal? Evil is what they judge.'),
(4495, 45, 22, 3, 19, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَ خَلَقَ اللّٰہُ  السَّمٰوٰتِ وَ الۡاَرۡضَ بِالۡحَقِّ وَ لِتُجۡزٰی کُلُّ  نَفۡسٍۭ بِمَا کَسَبَتۡ وَ ہُمۡ  لَا  یُظۡلَمُوۡنَ ﴿۲۲﴾', 'اور اللہ نے آسمانوں اور زمین کو حکمت سے پیدا کیا ہے اور تاکہ ہر شخص اپنے اعمال کا بدلہ پائے اور لوگوں پر ظلم نہیں کیا جائے گا۔', 'اور بنائے اللہ نے آسمان اور زمین جیسے چاہئیں اور تاکہ بدلا پائے ہر کوئی اپنی کمائی کا اور ان پر ظلم نہ ہو گا۔ [۲۷]', 'And Allah has created the heavens and the earth with truth, in order that each person may be recompensed what he has earned, and they will not be wronged .', 'Allah has created the heavens and the earth with just purpose, and so that everybody is recompensed for what he (or she) earned, and they will not be wronged.'),
(4496, 45, 23, 3, 19, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'اَفَرَءَیۡتَ مَنِ اتَّخَذَ  اِلٰـہَہٗ  ہَوٰىہُ وَ اَضَلَّہُ  اللّٰہُ  عَلٰی  عِلۡمٍ  وَّ خَتَمَ عَلٰی سَمۡعِہٖ وَ قَلۡبِہٖ وَ جَعَلَ عَلٰی بَصَرِہٖ  غِشٰوَۃً ؕ فَمَنۡ یَّہۡدِیۡہِ  مِنۡۢ  بَعۡدِ اللّٰہِ ؕ اَفَلَا  تَذَکَّرُوۡنَ ﴿۲۳﴾', 'بھلا تم نے اس شخص کو دیکھا جس نے اپنی خواہش کو اپنا معبود بنا رکھا ہے اور باوجود جاننے بوجھنے کے گمراہ ہو رہا ہے تو اللہ نے بھی اسکو گمراہ رہنے دیا اور انکے کانوں اور دل پر مہر لگا دی اور اسکی آنکھوں پر پردہ ڈال دیا۔ اب اللہ کے سوا اسکو کون راہ پر لا سکتا ہے تو کیا تم لوگ نصیحت نہیں حاصل کرتے؟', 'بھلا دیکھ تو جس نے ٹھہرا لیا اپنا حاکم اپنی خواہش کو اور راہ سے بچلا دیا اسکو اللہ نے جانتا بوجھتا [۲۸] اور مہر لگا دی اسکے کان پر اوردل پر اور ڈالدی اسکی آنکھ پر اندھیری پھر کون راہ پر لائے اسکو اللہ کے سوائے سو کیا تم غور نہیں کرتے [۲۹]', 'Have you seen him who takes his own lust (vain desires) as his ilah (god), and Allah knowing (him as such), left him astray, and sealed his hearing and his heart, and put a cover on his sight. Who then will guide him after Allah? Will you not then remember?', 'So, have you seen him who has taken his desires as his god, and Allah has let him go astray, despite having knowledge, and has sealed his ear and his heart, and put a cover on his eye? Now who will guide him after Allah? Still, do you not take lesson?'),
(4497, 45, 24, 3, 19, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَ قَالُوۡا مَا ہِیَ  اِلَّا حَیَاتُنَا الدُّنۡیَا نَمُوۡتُ وَ نَحۡیَا وَ مَا یُہۡلِکُنَاۤ  اِلَّا الدَّہۡرُ ۚ وَ مَا لَہُمۡ بِذٰلِکَ مِنۡ عِلۡمٍ ۚ اِنۡ ہُمۡ   اِلَّا یَظُنُّوۡنَ ﴿۲۴﴾', 'اور کہتے ہیں کہ ہماری زندگی تو صرف دنیا ہی کی ہے کہ یہیں مرتے اور جیتے ہیں اور ہمیں زمانہ ہی ہلاک کر دیتا ہے۔ اور انکو اس کا کچھ علم نہیں۔ محض قیاس آرائیاں کرتے ہیں۔', 'اور کہتے ہیں اورکچھ نہیں بس یہی ہے ہمارا جینا دنیا کا ہم مرتے ہیں اور جیتے ہیں اور ہم جو مرتے ہیں سو زمانہ سے [۳۰] اور انکو کچھ خبر نہیں اسکی محض اٹکلیں دوڑاتے ہیں  [۳۱]', 'And they say: \"There is nothing but our life of this world, we die and we live and nothing destroys us except Ad-Dahr (the time). And they have no knowledge of it, they only conjecture.', 'And they say, “There is no life but our worldly life. We die and live, and nothing destroys us except time.” They have no knowledge about that; they do nothing but make conjectures.'),
(4498, 45, 25, 3, 19, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَ اِذَا  تُتۡلٰی عَلَیۡہِمۡ  اٰیٰتُنَا بَیِّنٰتٍ مَّا کَانَ حُجَّتَہُمۡ  اِلَّاۤ  اَنۡ  قَالُوا ائۡتُوۡا بِاٰبَآئِنَاۤ  اِنۡ  کُنۡتُمۡ صٰدِقِیۡنَ ﴿۲۵﴾', 'اور جب انکے سامنے ہماری کھلی کھلی آیتیں پڑھی جاتی ہیں تو انکی یہی حجت ہوتی ہے کہ اگر سچے ہو تو ہمارے باپ دادا کو زندہ کر لاؤ۔', 'اور جب سنائی جاتیں انکو ہماری آیتیں کھلی کھلی اور کچھ دلیل نہیں انکی مگر یہی کہتے ہیں لے آؤ ہمارے باپ دادوں کو اگر تم سچے ہو [۳۲]', 'And when Our Clear Verses are recited to them, their argument is no other than that they say: \"Bring back our (dead) fathers, if you are truthful!\"', 'When Our verses are recited to them in all their clarity, their argument is none but that they say, “Bring our fathers, if you are truthful.”'),
(4499, 45, 26, 3, 19, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'قُلِ اللّٰہُ  یُحۡیِیۡکُمۡ  ثُمَّ یُمِیۡتُکُمۡ ثُمَّ یَجۡمَعُکُمۡ  اِلٰی یَوۡمِ الۡقِیٰمَۃِ  لَا رَیۡبَ فِیۡہِ وَ لٰکِنَّ  اَکۡثَرَ النَّاسِ لَا یَعۡلَمُوۡنَ ﴿٪۲۶﴾', 'کہدو کہ اللہ ہی تمکو جان بخشتا ہے پھر وہی تمکو موت دیتا ہے پھر تمکو قیامت کے روز جسکے آنے میں کچھ شک نہیں تمکو جمع کرے گا لیکن بہت سے لوگ نہیں جانتے۔', 'تو کہہ کہ اللہ ہی جِلاتا ہے تمکو  پھر مارے گا تمکو  پھر اکھٹا کرے گا تمکو  قیامت کے دن تک اس میں کچھ شک نہیں پر بہت لوگ نہیں سمجھتے [۳۳]', 'Say (to them): \"Allah gives you life, then causes you to die, then He will assemble you on the Day of Resurrection about which there is no doubt. But most of mankind know not.\"', 'Say, “Allah gives you life, then makes you die, then He will assemble you on the Day of Judgement in which there is no doubt, but most of the people do not know.'),
(4500, 45, 27, 4, 20, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَ لِلّٰہِ  مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ یَوۡمَ تَقُوۡمُ السَّاعَۃُ  یَوۡمَئِذٍ یَّخۡسَرُ الۡمُبۡطِلُوۡنَ ﴿۲۷﴾', 'اور آسمانوں اور زمین کی حکومت اللہ ہی کی ہے۔ اور جس روز قیامت برپا ہو گی اس روز اہل باطل خسارے میں پڑ جائیں گے۔', 'اور اللہ ہی کا راج ہے آسمانوں میں اور زمین میں اور جس دن قائم ہو گی قیامت اس دن خراب ہوں گے جھوٹے [۳۴]', 'And to Allah belongs the kingdom of the heavens and the earth. And on the Day that the Hour will be established, on that Day the followers of falsehood (polytheists, disbelievers, worshippers of false deities, etc.) shall lose (everything).', 'To Allah belongs the kingdom of the heavens and the earth. The day the Hour will take place, it will be the day in which the adherents of falsehood shall lose,'),
(4501, 45, 28, 4, 20, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَ تَرٰی کُلَّ  اُمَّۃٍ  جَاثِیَۃً ۟ کُلُّ  اُمَّۃٍ تُدۡعٰۤی  اِلٰی کِتٰبِہَا ؕ اَلۡیَوۡمَ تُجۡزَوۡنَ مَا کُنۡتُمۡ  تَعۡمَلُوۡنَ ﴿۲۸﴾', 'اور تم ہر ایک فرقے کو دیکھو گے کہ گھٹنوں کے بل بیٹھا ہو گا۔ اور ہر ایک جماعت اپنی کتاب اعمال کی طرف بلائی جائے گی۔ جو کچھ تم کرتے رہے ہو آج تمکو اس کا بدلہ دیا جائے گا۔', 'اور تو دیکھے ہر فرقہ کو کہ بیٹھے ہیں گھٹنوں  کے بل [۳۵] ہر فرقہ بلایا جائے اپنے اپنے دفتر کے پاس آج بدلا پاؤ گے جیسا تم کرتے تھے [۳۶]', 'And you will see each nation humbled to their knees (kneeling), each nation will be called to its Record (of deeds). This Day you shall be recompensed for what you used to do.', 'and you will see every community kneeling down. Every community will be called to its book (of record). Today you will be recompensed for what you used to do.'),
(4502, 45, 29, 4, 20, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'ہٰذَا کِتٰبُنَا یَنۡطِقُ عَلَیۡکُمۡ  بِالۡحَقِّ ؕ اِنَّا کُنَّا نَسۡتَنۡسِخُ مَا کُنۡتُمۡ تَعۡمَلُوۡنَ ﴿۲۹﴾', 'یہ ہماری کتاب تمہارے بارے میں سچ سچ بیان کر دے گی جو کچھ تم کیا کرتے تھے ہم لکھواتے جاتے تھے۔', 'یہ ہمارا دفتر ہے بولتا ہے تمہارے کام ٹھیک [۳۷] ہم لکھواتے جاتے تھے جو کچھ تم کرتے تھے [۳۸]', 'This Our Record speaks about you with truth. Verily, We were recording what you used to do (i.e. Our angels used to record your deeds).', 'This is Our book that speaks against you with truth. We used to get recorded all that you used to do.'),
(4503, 45, 30, 4, 20, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'فَاَمَّا  الَّذِیۡنَ  اٰمَنُوۡا وَ عَمِلُوا  الصّٰلِحٰتِ فَیُدۡخِلُہُمۡ رَبُّہُمۡ  فِیۡ  رَحۡمَتِہٖ ؕ ذٰلِکَ ہُوَ الۡفَوۡزُ الۡمُبِیۡنُ ﴿۳۰﴾', 'اب جو لوگ ایمان لائے اور نیک کام کرتے رہے ان کا پروردگار انہیں اپنی رحمت کے باغ میں داخل کرے گا۔ یہی کھلی کامیابی ہے۔', 'سو  جو لوگ یقین لائے ہیں اور بھلے کام کیے سو انکو  داخل کرے گا ان کا رب اپنی رحمت میں یہ جو ہے  یہی ہے صریح مراد ملنی [۳۹]', 'Then, as for those who believed (in the Oneness of Allah Islamic Monotheism) and did righteous good deeds, their Lord will admit them to His Mercy. That will be the evident success.', 'Then, as for those who believed and did righteous deeds, their Lord will admit them to His mercy. That is indeed the achievement, visible to all.'),
(4504, 45, 31, 4, 20, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَ اَمَّا الَّذِیۡنَ کَفَرُوۡا ۟ اَفَلَمۡ  تَکُنۡ اٰیٰتِیۡ  تُتۡلٰی عَلَیۡکُمۡ فَاسۡتَکۡبَرۡتُمۡ وَ کُنۡتُمۡ قَوۡمًا  مُّجۡرِمِیۡنَ ﴿۳۱﴾', 'اور جنہوں نے کفر کیا ان سے کہا جائے گا کہ بھلا ہماری آیتیں تمکو پڑھ کر سنائی نہیں جاتی تھیں ؟ مگر تم نے تکبر کیا اور تم نافرمان لوگ تھے۔', 'اور جو منکر ہوئے کیا تمکو سنائی نہ جاتی تھی باتیں میری  پھر تم  نے غرور کیا اور ہو گئے تم لوگ گنہگار [۴۰]', 'But as for those who disbelieved (it will be said to them): \"Were not Our Verses recited to you? But you were proud, and you were a people who were Mujrimoon (polytheists, disbelievers, sinners, criminals).\"', 'And as to those who disbelieved, (it will be said to them,) “Had My verses not been recited to you? But you showed arrogance, and you were a guilty people;'),
(4505, 45, 32, 4, 20, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَ اِذَا قِیۡلَ  اِنَّ وَعۡدَ اللّٰہِ حَقٌّ وَّ السَّاعَۃُ لَا رَیۡبَ فِیۡہَا  قُلۡتُمۡ مَّا نَدۡرِیۡ مَا السَّاعَۃُ ۙ اِنۡ  نَّظُنُّ   اِلَّا ظَنًّا وَّ مَا نَحۡنُ  بِمُسۡتَیۡقِنِیۡنَ ﴿۳۲﴾', 'اور جب کہا جاتا تھا کہ اللہ کا وعدہ سچا ہے اور قیامت میں کچھ شک نہیں تو تم کہتے تھے کہ ہم نہیں جانتے کہ قیامت کیا ہے۔ ہم اسکو محض خیالی سمجھتے ہیں اور ہمیں یقین نہیں آتا۔', 'اور جب کہیے کہ وعدہ اللہ کا ٹھیک ہے اور قیامت میں کچھ شبہ نہیں تم کہتے تھے ہم نہیں سمجھتے کیا ہے قیامت ہم کو  آتا تو ہے ایک خیال سا  اور ہم  کو  یقین نہیں ہوتا [۴۱]', 'And when it was said: \"Verily! Allahs Promise is the truth, and there is no doubt about the coming of the Hour,\" you said; \"We know not what is the Hour, we do not think it but as a conjecture, and we have no firm convincing belief (therein).\"', 'and when it was said to you that Allah’s promise is true and there is no doubt in the (arrival of the) Hour, you used to say, ‘We do not know what the Hour is. We do not think (about it) but as an assumption, and we are not sure.’”'),
(4506, 45, 33, 4, 20, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَ بَدَا لَہُمۡ سَیِّاٰتُ مَا عَمِلُوۡا وَ حَاقَ بِہِمۡ  مَّا  کَانُوۡا  بِہٖ  یَسۡتَہۡزِءُوۡنَ ﴿۳۳﴾', 'اور انکے اعمال کی برائیاں ان پر ظاہر ہو جائیں گی اور جس عذاب کی وہ ہنسی اڑاتے تھے وہ انکو آ گھیرے گا۔', 'اور کھل جائیں ان پر برائیاں ان کاموں کی جو کئے تھے اور الٹ پڑے ان پر وہ چیز جس پر ٹھٹھا کرتے تھے [۴۲]', 'And the evil of what they did will appear to them, and they will be completely encircled by that which they used to mock at!', 'And revealed to them will be the evils of what they did, and encircled they will be by what they used to ridicule.'),
(4507, 45, 34, 4, 20, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَ قِیۡلَ  الۡیَوۡمَ نَنۡسٰکُمۡ کَمَا نَسِیۡتُمۡ لِقَآءَ یَوۡمِکُمۡ  ہٰذَا وَ مَاۡوٰىکُمُ النَّارُ وَ مَا  لَکُمۡ  مِّنۡ  نّٰصِرِیۡنَ ﴿۳۴﴾', 'اور کہا جائے گا کہ جس طرح تم نے اس دن کے آنے کو بھلا رکھا تھا۔ اسی طرح آج ہم تمہیں بھلا دیں گے اور تمہارا ٹھکانہ دوزخ ہے اور کوئی تمہارا مددگار نہیں۔', 'اور حکم ہو گا کہ آج ہم تم کو بھلا دیں گے جیسے تم نے بھلا دیا تھا اپنے اس دن کی ملاقات کو [۴۳] اور گھر تمہارا دوزخ ہے  اور کوئی نہیں تمہارا مددگار', 'And it will be said: \"This Day We will forget you as you forgot the Meeting of this Day of yours. And your abode is the Fire, and there is none to help you.\"', 'It will be said, “Today We will forget you, as you forgot facing this your day, and your abode is the Fire, and for you there are no helpers at all.'),
(4508, 45, 35, 4, 20, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'ذٰلِکُمۡ  بِاَنَّکُمُ  اتَّخَذۡتُمۡ  اٰیٰتِ اللّٰہِ ہُزُوًا وَّ غَرَّتۡکُمُ الۡحَیٰوۃُ  الدُّنۡیَا ۚ فَالۡیَوۡمَ لَا یُخۡرَجُوۡنَ مِنۡہَا وَ لَا ہُمۡ یُسۡتَعۡتَبُوۡنَ ﴿۳۵﴾', 'یہ اس لئے کہ تم نے اللہ کی آیتوں کو مذاق بنا رکھا تھا اور دنیا کی زندگی نے تمکو دھوکے میں ڈال رکھا تھا۔ سو آج یہ لوگ نہ دوزخ سے نکالے جائیں گے اور نہ انکی توبہ قبول کی جائے گی۔', 'یہ تم پر اس واسطے کہ تم نے پکڑا اللہ کی باتوں کو ٹھٹھا اور بہکے رہے دنیا کی زندگانی پر [۴۴] سو آج نہ انکو نکالنا منظور ہے وہاں سے اور نہ ان سے مطلوب ہے توبہ [۴۵]', 'This, because you took the revelations of Allah (this Quran) in mockery, and the life of the world deceived you. So this Day, they shall not be taken out from there (Hell), nor shall they be Yustataboon (i.e. they shall not return to the worldly life, so that they repent to Allah, and beg His Pardon for their sins).', 'That is because you took Allah’s verses as a laughing stock, and the worldly life deceived you.” So today they will neither be brought out of it, nor will they be asked to repent.'),
(4509, 45, 36, 4, 20, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'فَلِلّٰہِ  الۡحَمۡدُ رَبِّ السَّمٰوٰتِ وَ رَبِّ الۡاَرۡضِ  رَبِّ الۡعٰلَمِیۡنَ ﴿۳۶﴾', 'پس اللہ ہی کیلئے ہر طرح کی تعریف ہے جو آسمانوں کا مالک ہے اور زمین کا بھی مالک اور تمام جہانوں کا پروردگار ہے۔', 'سو اللہ ہی کے واسطے ہے سب خوبی جو رب ہے آسمانوں کا اور رب ہے زمین کا رب سارے جہان کا', 'So all the praises and thanks are to Allah, the Lord of the heavens and the Lord of the earth, and the Lord of the Alameen (mankind, jinns and all that exists).', 'So, to Allah belongs all praise, who is the Lord of the heavens and the earth, the Lord of the worlds.'),
(4510, 45, 37, 4, 20, 25, 'اِلَیۡہِ یُرَدّ', 'الجاثیہ', 'وَ لَہُ  الۡکِبۡرِیَآءُ  فِی  السَّمٰوٰتِ وَ الۡاَرۡضِ ۪ وَ ہُوَ  الۡعَزِیۡزُ  الۡحَکِیۡمُ ﴿٪۳۷﴾', 'اور آسمانوں اور زمین میں اسی کے لئے بڑائی ہے۔ اور وہ غالب ہے دانا ہے۔', 'اور اُسی کیلئے بڑائی ہے آسمانوں میں اور زمین میں اور وہی ہے زبردست حکمت والا [۴۶]', 'And His (Alone) is the Majesty in the heavens and the earth, and He is the All-Mighty, the All-Wise.', 'And to Him belongs majesty in the heavens and the earth. And He is the Mighty, the Wise.'),
(4511, 46, 1, 1, 1, 26, 'حٰمٓ۔', 'الاحقاف', 'حٰمٓ ۚ﴿۱﴾', 'حٰمٓ۔', 'حٰمٓ۔', 'HaMeem. (These letters are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings).', 'Hā Mīm .'),
(4512, 46, 2, 1, 1, 26, 'حٰمٓ۔', 'الاحقاف', 'تَنۡزِیۡلُ  الۡکِتٰبِ مِنَ اللّٰہِ  الۡعَزِیۡزِ الۡحَکِیۡمِ ﴿۲﴾', 'یہ کتاب اللہ کی طرف سے نازل ہوئی ہے جو غالب ہے حکمت والا ہے۔', 'اتارنا  کتاب کا ہے اللہ زبردست حکمت والے کی طرف سے', 'The revelation of the Book (this Quran) is from Allah, the All-Mighty, the All-Wise.', 'This is revelation of the book from Allah, the All-Mighty, the All-Wise.'),
(4513, 46, 3, 1, 1, 26, 'حٰمٓ۔', 'الاحقاف', 'مَا خَلَقۡنَا السَّمٰوٰتِ وَ الۡاَرۡضَ وَ مَا بَیۡنَہُمَاۤ  اِلَّا بِالۡحَقِّ وَ اَجَلٍ مُّسَمًّی ؕ وَ الَّذِیۡنَ کَفَرُوۡا عَمَّاۤ  اُنۡذِرُوۡا مُعۡرِضُوۡنَ ﴿۳﴾', 'ہم نے آسمانوں اور زمین کو اور جو کچھ ان دونوں میں ہے حکمت سے اور ایک وقت مقرر تک کے لئے پیدا کیا ہے۔ اور کافروں کو جس چیز سے خبردار کیا جاتا ہے اس سے وہ منہ پھیر لیتے ہیں۔', 'ہم نے جو بنائے آسمان اور زمین اور جو انکے بیچ میں ہے سو ٹھیک کام پر اور ایک ٹھہرے وعدہ پر [۱] اور جو  لوگ منکر ہیں وہ ڈر کو سن کر منہ پھیر لیتے ہیں [۲]', 'We created not the heavens and the earth and all that is between them except with truth, and for an appointed term. But those who disbelieve turn away from that whereof they are warned.', 'We did not create the heavens and the earth but with true purpose and for a specified term. But those who disbelieve are averse to what they are warned of.'),
(4514, 46, 4, 1, 1, 26, 'حٰمٓ۔', 'الاحقاف', 'قُلۡ  اَرَءَیۡتُمۡ مَّا  تَدۡعُوۡنَ مِنۡ دُوۡنِ اللّٰہِ اَرُوۡنِیۡ  مَاذَا خَلَقُوۡا مِنَ الۡاَرۡضِ اَمۡ لَہُمۡ شِرۡکٌ فِی السَّمٰوٰتِ ؕ اِیۡتُوۡنِیۡ  بِکِتٰبٍ مِّنۡ  قَبۡلِ ہٰذَاۤ  اَوۡ اَثٰرَۃٍ  مِّنۡ عِلۡمٍ  اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ ﴿۴﴾', 'کہو کہ بھلا تم نے ان چیزوں کو دیکھا ہے جنکو تم اللہ کے سوا پکارتے ہو ذرا مجھے بھی تو دکھاؤ۔ کہ انہوں نے زمین میں سے کون سی چیز پیدا کی ہے۔ یا آسمانوں میں انکی کوئی شرکت ہے۔ اگر سچے ہو تو اس سے پہلے کی کوئی کتاب میرے پاس لاؤ۔ یا تمہارے پاس علم انبیاء میں سے کچھ ہو تو اسے پیش کرو۔', 'تو کہہ بھلا دیکھو تو جنکو تم پکارتے ہو اللہ کے سوائے دکھلاؤ تو مجھ کو انہوں نے کیا بنایا زمین میں یا ان کا کچھ ساجھا ہے آسمانوں میں [۳] لاؤ میرے پاس کوئی کتاب اس سے پہلے کی  یا کوئی علم جو چلا آتا ہو اگر ہو تم سچے [۴]', 'Say (O Muhammad SAW to these pagans): \"Think! All that you invoke besides Allah show me! What have they created of the earth? Or have they a share in (the creation of) the heavens? Bring me a Book (revealed before this), or some trace of knowledge (in support of your claims), if you are truthful!\"', 'Say, “Tell me about those whom you invoke instead of Allah, (and) show me what they have created from the earth; Or have they a share in (the creation of) the heavens? Bring to me a book (revealed) before this one, or a trace of knowledge, if you are truthful.”'),
(4515, 46, 5, 1, 1, 26, 'حٰمٓ۔', 'الاحقاف', 'وَ مَنۡ اَضَلُّ  مِمَّنۡ یَّدۡعُوۡا مِنۡ دُوۡنِ اللّٰہِ مَنۡ  لَّا یَسۡتَجِیۡبُ لَہٗۤ  اِلٰی یَوۡمِ الۡقِیٰمَۃِ  وَ  ہُمۡ عَنۡ دُعَآئِہِمۡ  غٰفِلُوۡنَ ﴿۵﴾', 'اور اس شخص سے بڑھ کر کون گمراہ ہو سکتا ہے جو ایسے کو پکارے جو قیامت تک اسے جواب نہ دے سکے اور انکو ان کے پکارنے ہی کی خبر نہ ہو۔', 'اور اس سے زیادہ گمراہ کون جو  پکارے اللہ کے سو ائے ایسے کو کہ نہ پہنچے اس کی پکار کو دن قیامت تک اور انکو خبر نہیں انکے پکارنے کی [۵]', 'And who is more astray than one who calls (invokes) besides Allah, such as will not answer him till the Day of Resurrection, and who are (even) unaware of their calls (invocations) to them?', 'Who is more astray than him who invokes, instead of Allah, those who will not respond to him up to the Day of Judgement; and they are totally unaware of their prayers,'),
(4516, 46, 6, 1, 1, 26, 'حٰمٓ۔', 'الاحقاف', 'وَ  اِذَا حُشِرَ  النَّاسُ کَانُوۡا لَہُمۡ  اَعۡدَآءً وَّ  کَانُوۡا بِعِبَادَتِہِمۡ کٰفِرِیۡنَ ﴿۶﴾', 'اور جب لوگ جمع کئے جائیں گے تو وہ انکے دشمن ہو جائیں گے اور ان کی پرستش سے انکار کر دیں گے۔', 'اور جب لوگ جمع ہوں گے وہ ہوں گے انکے دشمن اور ہوں گے انکے پوجنے سے منکر [۶]', 'And when mankind are gathered (on the Day of Resurrection), they (false deities) will become enemies for them and will deny their worshipping.', 'and when people will be assembled (on the Day of Judgment), they will be enemies to them, and will refuse even their having worshipped them.'),
(4517, 46, 7, 1, 1, 26, 'حٰمٓ۔', 'الاحقاف', 'وَ اِذَا تُتۡلٰی عَلَیۡہِمۡ  اٰیٰتُنَا بَیِّنٰتٍ قَالَ الَّذِیۡنَ کَفَرُوۡا لِلۡحَقِّ لَمَّا جَآءَہُمۡ ۙ ہٰذَا سِحۡرٌ  مُّبِیۡنٌ ؕ﴿۷﴾', 'اور جب ان کے سامنے ہماری صاف صاف آیتیں پڑھی جاتی ہیں تو کافر حق کے بارے میں جبکہ وہ انکے پاس آ چکا کہتے ہیں کہ یہ تو کھلا جادو ہے۔', 'اور جب سنائی جائیں انکو ہماری باتیں کھلی کھلی کہتے ہیں منکر سچی بات کو جب ان تک پہنچی یہ جادو ہے صریح [۷]', 'And when Our Clear Verses are recited to them, the disbelievers say of the truth (this Quran), when it reaches them: \"This is plain magic!\"', 'When Our verses are recited to them in all their clarity, the disbelievers say about the truth when it comes to them, “This is an open magic.”'),
(4518, 46, 8, 1, 1, 26, 'حٰمٓ۔', 'الاحقاف', 'اَمۡ  یَقُوۡلُوۡنَ  افۡتَرٰىہُ ؕ  قُلۡ  اِنِ افۡتَرَیۡتُہٗ فَلَا  تَمۡلِکُوۡنَ  لِیۡ مِنَ اللّٰہِ  شَیۡئًا ؕ ہُوَ اَعۡلَمُ  بِمَا تُفِیۡضُوۡنَ  فِیۡہِ ؕ کَفٰی بِہٖ شَہِیۡدًۢا  بَیۡنِیۡ  وَ بَیۡنَکُمۡ ؕ وَ ہُوَ الۡغَفُوۡرُ  الرَّحِیۡمُ ﴿۸﴾', 'کیا یہ لوگ کہتے ہیں کہ اس پیغمبر نے اسکو ازخود گھڑ لیا ہے۔ کہدو کہ اگر میں نے اسکو اپنی طرف سے بنایا ہو تو تم اللہ کے سامنے میرے بچاؤ کے لئے کچھ اختیار نہیں رکھتے وہ اس گفتگو کو خوب جانتا ہے جو تم اسکے بارے میں کرتے ہو وہی میرے اور تمہارے درمیان گواہ کافی ہے اور وہی تو ہے بڑا بخشنے والا مہربان۔', 'کیا کہتے ہیں یہ بنا لایا ہے [۸] تو کہہ اگر میں یہ بنا لایا ہوں تو تم میرا بھلا نہیں کر سکتے اللہ کے سامنے ذرا بھی [۹] اس کو خوب خبر ہے جن باتوں میں تم لگ رہے ہو وہ کافی ہے حق بتانے والا میرے اور تمہارے بیچ [۱۰] اور وہی ہے بخشنے والا مہربان [۱۱]', 'Or say they: \"He (Muhammad SAW) has fabricated it.\" Say: \"If I have fabricated it, still you have no power to support me against Allah. He knows best of what you say among yourselves concerning it (i.e. this Quran)! Sufficient is He for a witness between me and you! And He is the Oft-Forgiving, the Most Merciful.\"', 'Is it that they say, “He has forged it (the Qur’ān)”? Say, “If I have forged it, then you do not have any power to help me against Allah. He is well aware of what you are engaged in. He is enough as a witness between me and you, and He is the Most-Forgiving, the Very-Merciful.”'),
(4519, 46, 9, 1, 1, 26, 'حٰمٓ۔', 'الاحقاف', 'قُلۡ مَا کُنۡتُ بِدۡعًا مِّنَ الرُّسُلِ وَ مَاۤ اَدۡرِیۡ  مَا یُفۡعَلُ بِیۡ  وَ لَا بِکُمۡ ؕ اِنۡ  اَتَّبِعُ اِلَّا مَا یُوۡحٰۤی  اِلَیَّ وَ مَاۤ  اَنَا  اِلَّا نَذِیۡرٌ مُّبِیۡنٌ ﴿۹﴾', 'کہدو کہ میں کوئی انوکھا پیغمبر نہیں ہوں۔ اور میں نہیں جانتا کہ میرے ساتھ کیا سلوک کیا جائے گا اور تمہارے ساتھ کیا کیا جائے گا میں تو اسی کی پیروی کرتا ہوں جو مجھ پر وحی آتی ہے اور میرا کام تو اعلانیہ خبردار کرنا ہے۔', 'تو کہہ میں کچھ نیا رسول نہیں آیا [۱۲] اور مجھ کو معلوم نہیں کیا ہونا ہے مجھ سے اور تم سے میں اسی پر چلتا ہوں جو حکم آتا ہے مجھ کو اور میرا کام تو یہ ہے ڈر سنا دینا کھول کر [۱۳]', 'Say (O Muhammad SAW):\"I am not a new thing among the Messengers (of Allah) (i.e. I am not the first Messenger) nor do I know what will be done with me or with you. I only follow that which is revealed to me, and I am but a plain warner.\"', 'Say, “I am not something unprecedented among the messengers, and I do not know what will be done to me or to you. I do not follow anything but what is revealed to me, and I am only a clear warner.”');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(4520, 46, 10, 1, 1, 26, 'حٰمٓ۔', 'الاحقاف', 'قُلۡ  اَرَءَیۡتُمۡ  اِنۡ کَانَ مِنۡ عِنۡدِ اللّٰہِ وَ کَفَرۡتُمۡ  بِہٖ وَ شَہِدَ شَاہِدٌ مِّنۡۢ  بَنِیۡۤ اِسۡرَآءِیۡلَ  عَلٰی مِثۡلِہٖ  فَاٰمَنَ وَ اسۡتَکۡبَرۡتُمۡ ؕ اِنَّ اللّٰہَ  لَا یَہۡدِی الۡقَوۡمَ الظّٰلِمِیۡنَ ﴿٪۱۰﴾', 'کہو کہ بھلا دیکھو تو اگر یہ قرآن اللہ کی طرف سے ہو اور تم نے اس سے انکار کیا اور بنی اسرائیل میں سے ایک گواہ اسی طرح کی ایک کتاب کی گواہی دے چکا اور ایمان لے آیا اور تم نے سرکشی کی تو تمہارے ظالم ہونے میں کیا شک ہے بیشک اللہ ظالم لوگوں کو ہدایت نہیں دیتا۔', 'تو کہہ بھلا دیکھو تو اگر یہ آیا ہو اللہ کے  یہاں سے اور تم نے اس کو نہیں مانا اور گواہی دے چکا ایک گواہ بنی اسرائیل کا ایک اسی کتاب کی پھر وہ یقین لایا اور تم نے غرور کیا بیشک اللہ راہ نہیں دیتا گنہگاروں کو [۱۴]', 'Say: \"Tell me! If this (Quran) is from Allah, and you deny it, and a witness from among the Children of Israel (Abdullah bin Salam ÑÖì ) testifies that this Quran is from Allah (like the Taurat (Torah)), so he believed (embraced Islam) while you are too proud (to believe).\" Verily! Allah guides not the people who are Zalimoon (polytheists, disbelievers and wrong-doing).', 'Say, “Tell me, If it (the Qur’ān) is from Allah and you reject it, and a witness from the children of Isrā’īl testifies about something similar to it and comes to believe (in it), while you persist in your arrogance, (then, how unjust you are!) Surely, Allah does not give guidance to the unjust people.'),
(4521, 46, 11, 2, 2, 26, 'حٰمٓ۔', 'الاحقاف', 'وَ قَالَ الَّذِیۡنَ  کَفَرُوۡا لِلَّذِیۡنَ اٰمَنُوۡا لَوۡ کَانَ خَیۡرًا مَّا سَبَقُوۡنَاۤ  اِلَیۡہِ ؕ وَ  اِذۡ  لَمۡ یَہۡتَدُوۡا بِہٖ  فَسَیَقُوۡلُوۡنَ  ہٰذَاۤ  اِفۡکٌ قَدِیۡمٌ ﴿۱۱﴾', 'اور کافر مومنوں کے متعلق کہتے ہیں کہ اگر یہ دین کچھ بہتر ہوتا تو یہ لوگ اسکی طرف ہم سے پہلے نہ دوڑ پڑتے اور جب وہ اس سے ہدایت یاب نہ ہوئے کہیں گے کہ یہ تو پرانا جھوٹ ہے۔', 'اور کہنے لگے منکر  ایمان والوں کو اگر یہ دین بہتر ہوتا تو یہ نہ دوڑتے  اس پر ہم سے پہلے [۱۵] اور جب راہ پر نہیں آئے اسکے بتلانے سے تو یہ اب کہیں گے یہ جھوٹ ہے بہت پرانا [۱۶]', 'And those who disbelieve (strong and wealthy) say of those who believe (weak and poor): \"Had it (Islamic Monotheism to which Muhammad SAW is inviting mankind) been a good thing, they (weak and poor) would not have preceded us thereto!\" And when they have not let themselves be guided by it (this Quran), they say: \"This is an ancient lie!\"', 'The disbelievers say about the believers, “Had it (Islamic faith) been a good thing, these (weak and poor) people would not have preceded us (in proceeding) towards it.” Since they did not accept guidance through it (the Qur’ān), they will say, “This is a classical lie.”'),
(4522, 46, 12, 2, 2, 26, 'حٰمٓ۔', 'الاحقاف', 'وَ مِنۡ  قَبۡلِہٖ کِتٰبُ مُوۡسٰۤی  اِمَامًا وَّ رَحۡمَۃً ؕ وَ ہٰذَا کِتٰبٌ مُّصَدِّقٌ  لِّسَانًا عَرَبِیًّا  لِّیُنۡذِرَ الَّذِیۡنَ ظَلَمُوۡا ٭ۖ وَ بُشۡرٰی لِلۡمُحۡسِنِیۡنَ ﴿ۚ۱۲﴾', 'اور اس سے پہلے موسٰی کی کتاب تھی لوگوں کے لئے رہنما اور رحمت۔ اور یہ کتاب عربی زبان میں ہے اسکی تصدیق کرنے والی تاکہ ظالموں کو خبردار کرے۔ اور نیکوکاروں کو خوشخبری سنائے۔', 'اور اس سے  پہلے کتاب موسٰی کی تھی راہ ڈالنے والی اور حمت اور یہ کتاب ہے اسکی تصدیق کرتی [۱۷] عربی زبان میں تاکہ ڈر سنائے گنہگاروں کو اور خوشخبری نیکی والوں کو', 'And before this was the Scripture of Moosa (Moses) as a guide and a mercy. And this is a confirming Book (the Quran) in the Arabic language, to warn those who do wrong, and as glad tidings to the Muhsinoon (good-doers - see V.2:112).', 'And before this there was the Book of Mūsā, a guide and a mercy. And this is a Book confirming (it) in Arabic tongue, so that it may warn the wrongdoers and give good news to those who are good in their deeds.'),
(4523, 46, 13, 2, 2, 26, 'حٰمٓ۔', 'الاحقاف', 'اِنَّ  الَّذِیۡنَ قَالُوۡا رَبُّنَا اللّٰہُ  ثُمَّ اسۡتَقَامُوۡا فَلَا خَوۡفٌ عَلَیۡہِمۡ  وَ لَا ہُمۡ یَحۡزَنُوۡنَ ﴿ۚ۱۳﴾', 'جن لوگوں نے کہا کہ ہمارا پروردگار اللہ ہے پھر وہ اس پر قائم رہے تو انکو نہ کچھ خوف ہو گا اور نہ وہ غمناک ہوں گے۔', 'مقرر جنہوں نے کہا رب ہمارا اللہ ہے پھر ثابت قدم رہے تو نہ ڈر ہے ان پر اور نہ وہ غمگین ہوں گے [۱۸]', 'Verily, those who say: \"Our Lord is (only) Allah,\" and thereafter Istaqamoo (i.e. stood firm and straight on the Islamic Faith of Monotheism by abstaining from all kinds of sins and evil deeds which Allah has forbidden and by performing all kinds of good deeds which He has ordained), on them shall be no fear, nor shall they grieve.', 'Surely, those who say, “Our Lord is Allah” and then stay firm, they will have no fear, nor shall they grieve.'),
(4524, 46, 14, 2, 2, 26, 'حٰمٓ۔', 'الاحقاف', 'اُولٰٓئِکَ اَصۡحٰبُ الۡجَنَّۃِ  خٰلِدِیۡنَ  فِیۡہَا ۚ جَزَآءًۢ  بِمَا  کَانُوۡا  یَعۡمَلُوۡنَ ﴿۱۴﴾', 'یہی اہل جنت ہیں کہ ہمیشہ اس میں رہیں گے۔ یہ اس کا بدلہ ہے جو وہ کیا کرتے تھے۔', 'وہ لوگ ہیں بہشت والے سدا رہیں گے اس میں بدلا ہے ان کاموں کا جو کرتے تھے [۱۹]', 'Such shall be the dwellers of Paradise, abiding therein (forever), a reward for what they used to do.', 'Those are the people of Paradise, who will live there for ever as a reward for what they used to do.'),
(4525, 46, 15, 2, 2, 26, 'حٰمٓ۔', 'الاحقاف', 'وَ وَصَّیۡنَا  الۡاِنۡسَانَ بِوَالِدَیۡہِ  اِحۡسٰنًا  ؕ حَمَلَتۡہُ  اُمُّہٗ  کُرۡہًا وَّ وَضَعَتۡہُ  کُرۡہًا ؕ وَ حَمۡلُہٗ  وَ فِصٰلُہٗ   ثَلٰثُوۡنَ شَہۡرًا ؕ حَتّٰۤی  اِذَا بَلَغَ  اَشُدَّہٗ  وَ بَلَغَ  اَرۡبَعِیۡنَ سَنَۃً ۙ قَالَ  رَبِّ اَوۡزِعۡنِیۡۤ  اَنۡ  اَشۡکُرَ  نِعۡمَتَکَ الَّتِیۡۤ  اَنۡعَمۡتَ عَلَیَّ  وَ عَلٰی وَالِدَیَّ  وَ اَنۡ  اَعۡمَلَ صَالِحًا تَرۡضٰہُ وَ اَصۡلِحۡ  لِیۡ  فِیۡ ذُرِّیَّتِیۡ ۚؕ اِنِّیۡ  تُبۡتُ  اِلَیۡکَ وَ اِنِّیۡ مِنَ الۡمُسۡلِمِیۡنَ ﴿۱۵﴾', 'اور ہم نے انسان کو اسکے والدین کے ساتھ بھلائی کرنے کا حکم دیا۔ اسکی ماں نے اسکو تکلیف سے پیٹ میں رکھا اور تکلیف ہی سے جنا۔ اور اس کا پیٹ میں رہنا اور دودھ چھڑانا ڈھائی برس میں ہوتا ہے۔ یہاں تک کہ جب وہ پختہ عمر کو پہنچ جاتا ہے اور چالیس برس کا ہو جاتا ہے تو کہتا ہے کہ اے میرے پروردگار مجھے توفیق دے کہ تو نے جو احسان مجھ پر اور میرے ماں باپ پر کئے ہیں ان کا شکرگذار بنوں اور یہ کہ نیک عمل کروں جنکو تو پسند کرے۔ اور میرے لئے میری اولاد کو نیک بنا دے۔ میں تیری طرف رجوع کرتا ہوں اور میں فرمانبرداروں میں ہوں۔', 'اور ہم نے حکم کر دیا انسان کو اپنے ماں باپ سے بھلائی کا [۲۰] پیٹ میں رکھا اسکو اسکی ماں نے تکلیف سے اور جنا اسکو تکلیف سے [۲۱] اور حمل میں رہنا اس کا اور دودھ چھوڑنا تیس مہینے میں ہے [۲۲] یہاں تک کہ جب پہنچا اپنی قوت کو اور پہنچ گیا چالیس برس کو [۲۳] کہنے لگا اے رب میرے میری قسمت میں کر کہ شکر کروں تیرے احسان کا جو تو نے مجھ پر کیا اور میرے ماں باپ پر اور یہ کہ کروں نیک کام جس سے تو راضی ہو اور مجھ کو دے نیک اولاد میری میں نے توبہ کی تیری طرف اور میں ہوں حکم بردار [۲۴]', 'And We have enjoined on man to be dutiful and kind to his parents. His mother bears him with hardship and she brings him forth with hardship, and the bearing of him, and the weaning of him is thirty (30) months, till when he attains full strength and reaches forty years, he says: \"My Lord! Grant me the power and ability that I may be grateful for Your Favour which You have bestowed upon me and upon my parents, and that I may do righteous good deeds, such as please You, and make my off-spring good. Truly, I have turned to You in repentance, and truly, I am one of the Muslims (submitting to Your Will).\"', 'And We have enjoined upon man to do good to his parents. His mother carried him with difficulty and delivered him with difficulty. And his carrying and his weaning is (in) thirty months, until when he attains his maturity and reaches forty years, he says, “My Lord, grant me that I offer gratitude for the favour You have bestowed upon me and upon my parents, and that I do righteous deeds that You like. And set righteousness, for my sake, in my progeny. Of course, I repent to you, and truly I am one of those who submit to You.”'),
(4526, 46, 16, 2, 2, 26, 'حٰمٓ۔', 'الاحقاف', 'اُولٰٓئِکَ الَّذِیۡنَ نَتَقَبَّلُ عَنۡہُمۡ  اَحۡسَنَ مَا عَمِلُوۡا وَ نَتَجَاوَزُ عَنۡ سَیِّاٰتِہِمۡ فِیۡۤ اَصۡحٰبِ الۡجَنَّۃِ ؕ وَعۡدَ الصِّدۡقِ الَّذِیۡ کَانُوۡا یُوۡعَدُوۡنَ ﴿۱۶﴾', 'یہی لوگ ہیں جنکے اعمال نیک ہم قبول کریں گے اور انکے گناہوں سے درگذر فرمائیں گے اور یہی اہل جنت میں ہوں گے یہ سچا وعدہ ہے جو ان سے کیا جاتا تھا۔', 'یہ وہ لوگ ہیں جن سے ہم قبول کرتے ہیں بہتر سے بہتر کام جو کئے ہیں اور معاف کرتے ہیں ہم برائیاں ان کی رہنے والے جنت کے لوگوں میں سچا وعدہ جو ان سے کیا جاتا تھا [۲۵]', 'They are those from whom We shall accept the best of their deeds and overlook their evil deeds. (They shall be) among the dwellers of Paradise, a promise of truth, which they have been promised.', 'Such are the people from whom We accept the best of what they did, and overlook their evil deeds, (so as they will be) among the people of Paradise according to the true promise that was made to them.'),
(4527, 46, 17, 2, 2, 26, 'حٰمٓ۔', 'الاحقاف', 'وَ الَّذِیۡ  قَالَ  لِوَالِدَیۡہِ  اُفٍّ لَّکُمَاۤ اَتَعِدٰنِنِیۡۤ   اَنۡ  اُخۡرَجَ وَ قَدۡ خَلَتِ الۡقُرُوۡنُ مِنۡ  قَبۡلِیۡ ۚ وَ ہُمَا یَسۡتَغِیۡثٰنِ اللّٰہَ وَیۡلَکَ اٰمِنۡ ٭ۖ اِنَّ  وَعۡدَ اللّٰہِ  حَقٌّ ۚۖ فَیَقُوۡلُ مَا ہٰذَاۤ  اِلَّاۤ  اَسَاطِیۡرُ  الۡاَوَّلِیۡنَ ﴿۱۷﴾', 'اور جس شخص نے اپنے ماں باپ سے کہا کہ میں تم سے بیزار ہوں کیا تم مجھے یہ بتاتے ہو کہ میں زمین سے نکالا جاؤں گا حالانکہ بہت سی قومیں مجھ سے پہلے گذر چکی ہیں۔ اور وہ دونوں اللہ کی جناب میں فریاد کرتے ہوئے کہتے تھے کہ کم بخت ایمان لا۔ اللہ کا وعدہ سچا ہے۔ تو کہنے لگا یہ تو پہلے لوگوں کی کہانیاں ہیں۔', 'اور جس شخص نے کہا اپنے مان باپ کو میں بیزار ہوں تم سے [۲۶] کیا مجھ کو وعدہ دیتے ہو کہ میں نکالا جاؤں گا قبر سے اور گزر چکی ہیں بہت جماعتیں مجھ سے پہلے [۲۷] اور وہ دونوں فریاد کرتےہیں اللہ سے کہ اے خرابی تیری تو ایمان لے آ بیشک وعدہ اللہ کا ٹھیک ہے [۲۸] پھر کہتا ہے یہ سب نقلیں ہیں پہلوں کی [۲۹]', 'But he who says to his parents: \"Fie upon you both! Do you hold out the promise to me that I shall be raised up (again) when generations before me have passed away (without rising)?\" While they (father and mother) invoke Allah for help (and rebuke their son): \"Woe to you! Believe! Verily, the Promise of Allah is true.\" But he says: \"This is nothing but the tales of the ancient.\"', 'And (Contrary to this is the case of) the one who said to his parents, “Fie upon you both! Do you promise to me that I shall be brought out (from the grave), while generations have passed before me?” And they (the parents) were crying for Allah’s help, (and saying to their son,) “Woe to you. Accept the true faith. Allah’s promise is certainly true.” Then he says, “This is nothing but the tales of the ancients.”'),
(4528, 46, 18, 2, 2, 26, 'حٰمٓ۔', 'الاحقاف', 'اُولٰٓئِکَ  الَّذِیۡنَ حَقَّ عَلَیۡہِمُ  الۡقَوۡلُ فِیۡۤ اُمَمٍ  قَدۡ خَلَتۡ مِنۡ  قَبۡلِہِمۡ  مِّنَ الۡجِنِّ وَ الۡاِنۡسِ ؕ اِنَّہُمۡ  کَانُوۡا خٰسِرِیۡنَ ﴿۱۸﴾', 'یہی وہ لوگ ہیں جنکے بارے میں جنوں اور انسانوں کی دوسری امتوں میں سے جو ان سے پہلے گذر چکیں عذاب کا وعدہ تحقیق ہو گیا۔ بیشک وہ نقصان اٹھانے والے تھے۔', 'یہ وہ لوگ ہیں کہ جن پر ثابت ہوئی بات عذاب کی شامل اور فرقوں میں جو گذر چکے ہیں ان سے پہلے جنوں کے اور آدمیوں کے [۳۰] بیشک وہ تھے ٹوٹے میں پڑے  [۳۱]', 'They are those against whom the Word (of torment) is justified among the previous generations of jinns and mankind that have passed away. Verily! They are ever the losers.', 'Such are the people on whom the word (of punishment) has come true along with the communities of the Jinn and the humans that have passed before them. Surely they were losers.'),
(4529, 46, 19, 2, 2, 26, 'حٰمٓ۔', 'الاحقاف', 'وَ لِکُلٍّ  دَرَجٰتٌ مِّمَّا عَمِلُوۡا ۚ وَ  لِیُوَفِّیَہُمۡ  اَعۡمَالَہُمۡ  وَ ہُمۡ  لَا  یُظۡلَمُوۡنَ ﴿۱۹﴾', 'اور لوگوں نے جیسے کام کئے ہوں گے انکے مطابق سب کے درجے ہوں گے غرض یہ ہے کہ اللہ انکو ان کے اعمال کا پورا بدلہ دے اور ان کا نقصان نہ کیا جائے گا۔', 'اور ہر فرقہ کے کئ درجے ہیں اپنے کئے کاموں کے موافق [۳۲] اور تاکہ پورے دے انکو کام انکے اور ان پر ظلم نہ ہو گا [۳۳]', 'And for all, there will be degrees according to that which they did, that He (Allah) may recompense them in full for their deeds. And they will not be wronged.', 'For each (of these two groups) there are (different) ranks because of what they did, and so that He may repay them in full for their deeds; and they will not be wronged.'),
(4530, 46, 20, 2, 2, 26, 'حٰمٓ۔', 'الاحقاف', 'وَ یَوۡمَ  یُعۡرَضُ الَّذِیۡنَ کَفَرُوۡا عَلَی النَّارِ ؕ اَذۡہَبۡتُمۡ طَیِّبٰتِکُمۡ فِیۡ حَیَاتِکُمُ الدُّنۡیَا وَ اسۡتَمۡتَعۡتُمۡ بِہَا ۚ فَالۡیَوۡمَ تُجۡزَوۡنَ عَذَابَ الۡہُوۡنِ بِمَا کُنۡتُمۡ تَسۡتَکۡبِرُوۡنَ فِی الۡاَرۡضِ بِغَیۡرِ الۡحَقِّ وَ بِمَا کُنۡتُمۡ  تَفۡسُقُوۡنَ ﴿٪۲۰﴾', 'اور جس دن کافر دوزخ کے سامنے کئے جائیں گے تو کہا جائے گا کہ تم اپنی دنیا کی زندگی میں لذتیں حاصل کر چکے اور ان سے لطف اندوز ہو چکے سو آج تمکو ذلت کا عذاب دیا جاتا ہے یہ اسکی سزا ہے کہ تم زمین میں ناحق غرور کیا کرتے تھے۔ اور اسکی کہ بدکرداری کرتے تھے۔', 'اور جس دن لائے جائیں گے منکر  آگ کے کنارہ پر ضائع کئے تم نے اپنے مزے دنیا کی زندگانی میں اور انکو  برت چکے [۳۴] اب آج سزا پاؤ گے ذلت کا عذاب بدلا اس کا جو تم غرور کرتے تھے ملک میں ناحق اور اس کا جو تم نافرمانی کرتے تھے [۳۵]', 'On the Day when those who disbelieve (in the Oneness of Allah Islamic Monotheism) will be exposed to the Fire (it will be said): \"You received your good things in the life of the world, and you took your pleasure therein. Now this Day you shall be recompensed with a torment of humiliation, because you were arrogant in the land without a right, and because you used to rebel and disobey (Allah).', 'And the day the disbelievers will be presented before the Fire, (it will be said to them,) “You have consumed your good things in your worldly life, and have enjoyed them. So, you will be punished today with the torment of humiliation for the arrogance you used to show on earth with no right (to do so), and for the sins you used to commit.'),
(4531, 46, 21, 3, 3, 26, 'حٰمٓ۔', 'الاحقاف', 'وَ اذۡکُرۡ  اَخَا عَادٍ ؕ اِذۡ  اَنۡذَرَ قَوۡمَہٗ بِالۡاَحۡقَافِ وَ قَدۡ خَلَتِ النُّذُرُ مِنۡۢ بَیۡنِ یَدَیۡہِ  وَ مِنۡ خَلۡفِہٖۤ  اَلَّا تَعۡبُدُوۡۤا اِلَّا اللّٰہَ ؕ اِنِّیۡۤ  اَخَافُ عَلَیۡکُمۡ عَذَابَ یَوۡمٍ عَظِیۡمٍ ﴿۲۱﴾', 'اور قوم عاد کے بھائی ہود  کو یاد کرو کہ جب انہوں نے اپنی قوم کو سرزمین احقاف میں خبردار کیا اور ان کے آگے اور پیچھے سے خبردار کرنے والے گذر چکے تھے کہ اللہ کے سوا کسی کی عبادت نہ کرو۔ مجھے تمہارے بارے میں بڑے دن کے عذاب کا ڈر لگتا ہے۔', 'اور یاد کر عاد کے بھائی کو [۳۶] جب ڈرایا اپنی قوم کو احقاف میں [۳۷] اور گذر چکے تھے دڑانے والے اسکے آگے سے اور پیچھے سے کہ بندگی نہ کرو کسی کی اللہ کے سوائے میں ڈرتا ہوں تم پر آفت سے ایک بڑے دن کی [۳۸]', 'And remember (Hood) the brother of Ad, when he warned his people in Al-Ahqaf (the curved sand-hills in the southern part of Arabian Peninsula). And surely, there have passed away warners before him and after him (saying): \"Worship none but Allah; truly, I fear for you the torment of a mighty Day.\"', 'And recall the brother of (the nation of) ‘Ād, when he warned his people at the long, curved sand dunes- while many warners have passed before him and after him (with the same message)-saying, “Do not worship anyone except Allah. Surely I fear for you the punishment of a terrible day.”'),
(4532, 46, 22, 3, 3, 26, 'حٰمٓ۔', 'الاحقاف', 'قَالُوۡۤا اَجِئۡتَنَا لِتَاۡفِکَنَا عَنۡ اٰلِہَتِنَا ۚ فَاۡتِنَا بِمَا تَعِدُنَاۤ  اِنۡ  کُنۡتَ مِنَ الصّٰدِقِیۡنَ ﴿۲۲﴾', 'کہنے لگے کیا تم ہمارے پاس اس لئے آئے ہو کہ ہمکو ہمارے معبودوں سے پھیر دو۔ اگر سچے ہو تو جس چیز سے ہمیں ڈراتے ہو اسے ہم پر لے آؤ۔', 'بولے کیا تو آیا ہے ہمارے پاس کہ پھیر دے ہمکو ہمارے معبودوں سے سو لے آ ہم پر جو وعدہ کرتا ہے اگر ہے تو سچا [۳۹]', 'They said: \"Have you come to turn us away from our aliha (gods)? Then bring us that with which you threaten us, if you are one of the truthful!\"', 'They said, “Have you come to make us deviate from our gods? So bring us that with which you are threatening us, if you are truthful.”'),
(4533, 46, 23, 3, 3, 26, 'حٰمٓ۔', 'الاحقاف', 'قَالَ  اِنَّمَا الۡعِلۡمُ عِنۡدَ اللّٰہِ ۫ۖ وَ اُبَلِّغُکُمۡ مَّاۤ  اُرۡسِلۡتُ بِہٖ  وَ لٰکِنِّیۡۤ  اَرٰىکُمۡ   قَوۡمًا تَجۡہَلُوۡنَ ﴿۲۳﴾', 'پیغمبر نے کہا کہ اس کا علم تو اللہ ہی کو ہے۔ اور میں تو جو احکام دے کر بھیجا گیا ہوں وہ تمہیں پہنچا رہا ہوں لیکن میں دیکھتا ہوں کہ تم لوگ نادانی میں پھنس رہے ہو۔', 'کہا یہ خبر تو اللہ ہی کو ہے اور میں تو پہنچا دیتا ہوں جو کچھ بھیجدیا میرے ہاتھ لیکن میں دیکھتا ہوں تم لوگ نادانی کرتے ہو [۴۰]', 'He said: \"The knowledge (of the time of its coming) is with Allah only, and I convey to you that wherewith I have been sent, but I see that you are a people given to ignorance!\"', 'He said, “The knowledge is with Allah alone, and I am conveying to you what I am sent with, but I see you are a people who act ignorantly.”'),
(4534, 46, 24, 3, 3, 26, 'حٰمٓ۔', 'الاحقاف', 'فَلَمَّا رَاَوۡہُ  عَارِضًا مُّسۡتَقۡبِلَ  اَوۡدِیَتِہِمۡ ۙ قَالُوۡا ہٰذَا عَارِضٌ مُّمۡطِرُنَا ؕ بَلۡ ہُوَ  مَا اسۡتَعۡجَلۡتُمۡ بِہٖ ؕ رِیۡحٌ  فِیۡہَا عَذَابٌ  اَلِیۡمٌ ﴿ۙ۲۴﴾', 'پھر جب انہوں نے اس عذاب کو دیکھا کہ بادل کی صورت میں انکے میدانوں کی طرف آ رہا ہے تو کہنے لگے یہ تو بادل ہے جو ہم پر برس کر رہے گا۔ نہیں بلکہ یہ وہ چیز ہے جسکے لئے تم جلدی کرتے تھے یعنی آندھی جس میں درد دینے والا عذاب بھرا ہوا ہے۔', 'پھر جب دیکھا اس کو ابر سامنے آیا انکے نالوں کے بولے یہ ابر ہے ہم پر برسے گا [۴۱] کوئی نہیں یہ تو وہ چیز ہے جسکی تم جلدی کرتے تھے ہوا ہے جس میں عذاب ہے دردناک [۴۲]', 'Then, when they saw it as a dense cloud coming towards their valleys, they said: \"This is a cloud bringing us rain!\" Nay, but it is that (torment) which you were asking to be hastened! a wind wherein is a painful torment!', 'So, when they saw it as a cloud proceeding towards their valleys, they said, “This is a cloud that will bring us rain.” No, it is the very thing you asked to hasten up - a wind in which there is a painful punishment,'),
(4535, 46, 25, 3, 3, 26, 'حٰمٓ۔', 'الاحقاف', 'تُدَمِّرُ کُلَّ  شَیۡءٍۭ  بِاَمۡرِ رَبِّہَا فَاَصۡبَحُوۡا لَا یُرٰۤی  اِلَّا مَسٰکِنُہُمۡ ؕ کَذٰلِکَ نَجۡزِی الۡقَوۡمَ الۡمُجۡرِمِیۡنَ ﴿۲۵﴾', 'جو ہر چیز کو اپنے پروردگار کے حکم سے تباہ کئے دیتی تھی آخر وہ ایسے ہو گئے کہ انکے گھروں کے سوا وہاں کچھ نظر نہیں آتا تھا گنہگار لوگوں کو ہم اسی طرح سزا دیا کرتے ہیں۔', 'اکھاڑ پھینکے ہر چیز کو اپنے رب کے حکم سے پھر کل کو رہ گئ کہ کوئی نظر نہیں آتا تھا سوائے انکے گھروں کے یوں ہم سزا دیتے ہیں گنہگار لوگوں کو [۴۳]', 'Destroying everything by the Command of its Lord! So they became such that nothing could be seen except their dwellings! Thus do We recompense the people who are Mujrimoon (polytheists, disbelievers, sinners, etc.)!', 'that will destroy every thing with the command of its Lord! So they became such that nothing remained to be seen except their dwelling places. This is how We punish the guilty people.'),
(4536, 46, 26, 3, 3, 26, 'حٰمٓ۔', 'الاحقاف', 'وَ لَقَدۡ مَکَّنّٰہُمۡ فِیۡمَاۤ  اِنۡ مَّکَّنّٰکُمۡ  فِیۡہِ وَ جَعَلۡنَا لَہُمۡ سَمۡعًا وَّ اَبۡصَارًا وَّ اَفۡـِٕدَۃً ۫ۖ فَمَاۤ  اَغۡنٰی عَنۡہُمۡ  سَمۡعُہُمۡ وَ لَاۤ اَبۡصَارُہُمۡ وَ لَاۤ  اَفۡـِٕدَتُہُمۡ مِّنۡ شَیۡءٍ  اِذۡ کَانُوۡا یَجۡحَدُوۡنَ ۙ بِاٰیٰتِ اللّٰہِ وَ حَاقَ بِہِمۡ  مَّا کَانُوۡا بِہٖ یَسۡتَہۡزِءُوۡنَ ﴿٪۲۶﴾', 'اور ہم نے ان کو ایسا اقتدار دیا تھا جو تم لوگوں کو نہیں دیا اور انہیں کان اور آنکھیں اور دل دیئے تھے۔ تو چونکہ وہ اللہ کی آیتوں سے انکار کرتے تھے اسلئے نہ تو انکے کان ہی انکے کچھ کام آ سکے اور نہ آنکھیں اور نہ دل۔ اور جس چیز کا وہ مذاق اڑایا کرتے تھے اسی نے انکو آ گھیرا۔', 'اور ہم نے مقدور دیا تھا انکو ان چیزوں کا جن کا تم کو مقدور نہیں دیا [۴۴] اور ہم نے انکو دیے تھے کان اور آنکھیں اور دل پھر کام نہ آئے انکےکان انکے اور نہ آنکھیں انکی اور نہ دل انکے کسی چیز میں [۴۵] اس لئے کہ منکر ہوتے تھے اللہ کی باتوں سے اور الٹ پڑی ان پر جس بات سے کہ وہ ٹھٹھا کرتے تھے [۴۶]', 'And indeed We had firmly established them with that wherewith We have not established you (O Quraish)! And We had assigned them the (faculties of) hearing (ears), seeing (eyes), and hearts, but their hearing (ears), seeing (eyes), and their hearts availed them nothing since they used to deny the Ayat (Allahs Prophets and their Prophethood, proofs, evidences, verses, signs, revelations, etc.) of Allah, and they were completely encircled by that which they used to mock at!', 'And indeed We had established them in a powerful position in which We did not establish you (O people of Makkah), and had given to them ears and eyes and hearts, but neither their ears benefited them in the least, nor their eyes, nor their hearts, as they used to reject Allah’s signs; and they were encircled by what they used to ridicule.'),
(4537, 46, 27, 4, 4, 26, 'حٰمٓ۔', 'الاحقاف', 'وَ لَقَدۡ اَہۡلَکۡنَا مَا حَوۡلَکُمۡ مِّنَ الۡقُرٰی وَ صَرَّفۡنَا الۡاٰیٰتِ لَعَلَّہُمۡ یَرۡجِعُوۡنَ ﴿۲۷﴾', 'اور اے مکے والو تمہارے اردگرد کی بستیوں کو ہم نے ہلاک کر دیا۔ اور بار بار ہم نے اپنی نشانیاں ظاہر کر دیں تاکہ وہ  رجوع کریں۔', 'اور ہم غارت کر چکے ہیں جتنی تمہارے آس پاس ہیں بستیاں [۴۷] اور طرح طرح سے پھیر کر سنائیں انکو باتیں تاکہ وہ لوٹ آئیں [۴۸]', 'And indeed We have destroyed towns (populations) round about you, and We have (repeatedly) shown (them) the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) in various ways that they might return (to the truth and believe in the Oneness of Allah - Islamic Monotheism).', 'And We have (also) destroyed (other) towns around you, while We had given to them a variety of signs, so that they might return (from disbelief).'),
(4538, 46, 28, 4, 4, 26, 'حٰمٓ۔', 'الاحقاف', 'فَلَوۡ  لَا  نَصَرَہُمُ الَّذِیۡنَ اتَّخَذُوۡا مِنۡ دُوۡنِ اللّٰہِ  قُرۡبَانًا اٰلِـہَۃً ؕ بَلۡ ضَلُّوۡا عَنۡہُمۡ ۚ وَ ذٰلِکَ  اِفۡکُہُمۡ  وَ  مَا  کَانُوۡا یَفۡتَرُوۡنَ ﴿۲۸﴾', 'تو جنکو ان لوگوں نے اللہ کا قرب حاصل کرنے کیلئے معبود بنایا تھا انہوں نے انکی کیوں مدد نہ کی؟ بلکہ وہ ان سے گم ہو گئے۔ اور یہ ان کا جھوٹ تھا اور یہی وہ افترا کیا کرتے تھے۔', 'پھر کیوں نہ مدد پہنچی انکو ان لوگوں کی طرف سے جنکو  پکڑ ا تھا اللہ سے ورے معبود بڑے درجے پانے کو [۴۹] کوئی نہیں گم ہو گئے ان سے [۵۰] اور یہ جھوٹ تھا ان کا اور جو اپنے جی سے باندھتے تھے [۵۱]', 'Then why did those whom they had taken for aliha (gods) besides Allah, as a way of approach (to Allah) not help them? Nay, but they vanished completely from them (when there came the torment). And that was their lie, and their inventions which they had been inventing (before their destruction).', 'So, why is it that they were not helped by those whom they had taken as gods beside Allah in order to attain closeness (to Him)? Instead, they vanished from them. That was, in fact, their falsity and a thing they used to fabricate.'),
(4539, 46, 29, 4, 4, 26, 'حٰمٓ۔', 'الاحقاف', 'وَ اِذۡ صَرَفۡنَاۤ  اِلَیۡکَ نَفَرًا مِّنَ الۡجِنِّ یَسۡتَمِعُوۡنَ الۡقُرۡاٰنَ ۚ فَلَمَّا حَضَرُوۡہُ قَالُوۡۤا  اَنۡصِتُوۡا ۚ فَلَمَّا قُضِیَ وَلَّوۡا اِلٰی قَوۡمِہِمۡ  مُّنۡذِرِیۡنَ ﴿۲۹﴾', 'اور وہ وقت قابل ذکر ہے جب ہم نے جنوں میں سے کئ شخص تمہاری طرف متوجہ کئے کہ قرآن سنیں۔ تو جب وہ اسکو سننے حاضر ہوئے تو آپس میں کہنے لگے کہ خاموش رہو۔ جب پڑھنا ختم ہوا تو وہ اپنی برادری کے لوگوں میں واپس گئے کہ انکو خبردار کریں۔', 'اور جس وقت متوجہ کر دیے ہم نے تیری طرف کتنے اک لوگ جنوں میں سے سننے لگے قرآن پھر جب وہاں پہنچ گئے بولے چپ رہو پھر جب ختم  ہوا الٹے پھرے اپنی قوم کو ڈر سناتے ہوئے [۵۲]', 'And (remember) when We sent towards you (Muhammad SAW) Nafran (three to ten persons) of the jinns, (quietly) listening to the Quran, when they stood in the presence thereof, they said: \"Listen in silence!\" And when it was finished, they returned to their people, as warners.', 'And (recall) when We directed a group of Jinns towards you, listening to the Qur’ān. So, when they attended it, they said (to each other), “Keep quiet.” Then once it was over, they went back to their people as warners.'),
(4540, 46, 30, 4, 4, 26, 'حٰمٓ۔', 'الاحقاف', 'قَالُوۡا یٰقَوۡمَنَاۤ  اِنَّا سَمِعۡنَا کِتٰبًا  اُنۡزِلَ مِنۡۢ  بَعۡدِ مُوۡسٰی مُصَدِّقًا لِّمَا بَیۡنَ یَدَیۡہِ یَہۡدِیۡۤ  اِلَی الۡحَقِّ وَ اِلٰی طَرِیۡقٍ مُّسۡتَقِیۡمٍ ﴿۳۰﴾', 'کہنے لگے کہ اے قوم ہم نے ایک کتاب سنی ہے۔ جو موسٰی  کے بعد نازل ہوئی ہے۔ جو کتابیں اس سے پہلے نازل ہوئی ہیں انکی تصدیق کرتی ہے اور سچا دین اور سیدھا رستہ بتاتی ہے۔', 'بولے اے قوم ہماری ہم نے سنی ایک کتاب جو  اتری ہے موسٰی کے بعد [۵۳] سچا کرنے والی سب اگلی کتابوں کو [۵۴] سمجھاتی ہے سچا دین اور ایک راہ سیدھی [۵۵]', 'They said: \"O our people! Verily! We have heard a Book (this Quran) sent down after Moosa (Moses), confirming what came before it, it guides to the truth and to a Straight Path (i.e. Islam).', 'They said, “O our people, we have heard a book sent down after Mūsā, confirming what was before it, which guides to the truth and to a straight path.'),
(4541, 46, 31, 4, 4, 26, 'حٰمٓ۔', 'الاحقاف', 'یٰقَوۡمَنَاۤ  اَجِیۡبُوۡا دَاعِیَ اللّٰہِ  وَ اٰمِنُوۡا بِہٖ یَغۡفِرۡ لَکُمۡ  مِّنۡ ذُنُوۡبِکُمۡ  وَ  یُجِرۡکُمۡ مِّنۡ عَذَابٍ اَلِیۡمٍ ﴿۳۱﴾', 'اے قوم اللہ کی طرف بلانے والے کی بات کو قبول کرو۔ اور اس پر ایمان لاؤ۔ اللہ تمہارے گناہ بخش دے گا اور تمہیں دکھ دینے والے عذاب سے پناہ میں رکھے گا۔', 'اے قوم ہماری مانو اللہ کے بلانے والے کو اور اس پر یقین لاؤ [۵۶] کہ بخشے تمکو کچھ تمہارے گناہ [۵۷] اور بچا دے تمکو ایک عذاب دردناک سے', 'O our people! Respond (with obedience) to Allahs Caller (i.e. Allahs Messenger Muhammad SAW), and believe in him (i.e. believe in that which Muhammad SAW has brought from Allah and follow him). He (Allah) will forgive you of your sins, and will save you from a painful torment (i.e. Hell-fire) .', 'O our people, respond to Allah’s herald, and believe in him, and (once you do that,) Allah will forgive your sins for you, and will save you from a painful punishment.'),
(4542, 46, 32, 4, 4, 26, 'حٰمٓ۔', 'الاحقاف', 'وَ مَنۡ  لَّا یُجِبۡ دَاعِیَ اللّٰہِ  فَلَیۡسَ بِمُعۡجِزٍ فِی  الۡاَرۡضِ وَ لَیۡسَ لَہٗ مِنۡ دُوۡنِہٖۤ اَوۡلِیَآءُ ؕ اُولٰٓئِکَ فِیۡ ضَلٰلٍ مُّبِیۡنٍ ﴿۳۲﴾', 'اور جو شخص اللہ کی طرف بلانے والے کی بات قبول نہ کرے گا تو وہ زمین میں اللہ کو عاجز نہیں کر سکے گا اور نہ اسکے سوا اس کے حمایتی ہوں گے۔ یہ لوگ کھلی گمراہی میں ہیں۔', 'اور جو کوئی نہ مانے گا اللہ کے بلانے والے کو تو وہ نہ تھکا سکے گا بھاگ کر زمین میں اور کوئی نہیں اس کا  اسکے سوائے مددگار [۵۸] وہ لوگ بھٹکتے ہیں صریح', 'And whosoever does not respond to Allahs Caller, he cannot escape on earth, and there will be no Auliya (protectors) for him besides Allah (from Allahs Punishment). Those are in manifest error.', 'The one who does not respond to Allah’s herald is not (able) to frustrate (Allah by escaping) in the land, and for him there are no supporters besides Him. Such people are in open error.'),
(4543, 46, 33, 4, 4, 26, 'حٰمٓ۔', 'الاحقاف', 'اَوَ لَمۡ یَرَوۡا اَنَّ اللّٰہَ  الَّذِیۡ خَلَقَ السَّمٰوٰتِ وَ الۡاَرۡضَ وَ لَمۡ  یَعۡیَ بِخَلۡقِہِنَّ بِقٰدِرٍ عَلٰۤی اَنۡ یُّحۡیَِۧ  الۡمَوۡتٰی ؕ بَلٰۤی   اِنَّہٗ  عَلٰی کُلِّ  شَیۡءٍ  قَدِیۡرٌ ﴿۳۳﴾', 'کیا انہوں نے نہیں سمجھا کہ جس اللہ نے آسمانوں اور زمین کو پیدا کیا اور وہ انکے پیدا کرنے سے تھکا نہیں۔ وہ اس بات پر بھی قادر ہے کہ مردوں کو زندہ کر دے۔ ہاں کیوں نہیں وہ ہر چیز پر قادر ہے۔', 'کیا نہیں دیکھتے کہ وہ اللہ جس نے بنائے آسمان اور زمین اور نہ تھکا انکے بنانے میں [۵۹] وہ قدرت رکھتا ہے کہ زندہ کرے مردوں کو کیوں نہیں وہ ہر چیز کر سکتا ہے [۶۰]', 'Do they not see that Allah, Who created the heavens and the earth, and was not wearied by their creation, is Able to give life to the dead? Yes, He surely is Able to do all things.', 'Have they not seen that Allah who has created the heavens and the earth, and was not wearied by their creation, does have power to give life to the dead? Yes of course, He is powerful to do every thing.'),
(4544, 46, 34, 4, 4, 26, 'حٰمٓ۔', 'الاحقاف', 'وَ یَوۡمَ یُعۡرَضُ الَّذِیۡنَ  کَفَرُوۡا عَلَی النَّارِ ؕ اَلَیۡسَ ہٰذَا بِالۡحَقِّ ؕ قَالُوۡا بَلٰی وَ رَبِّنَا ؕ قَالَ  فَذُوۡقُوا الۡعَذَابَ بِمَا کُنۡتُمۡ تَکۡفُرُوۡنَ ﴿۳۴﴾', 'اور جس روز انکار کرنے والے آگ کے سامنے کئے جائیں گے۔ تو ان سے پوچھا جائے گا کیا یہ حق نہیں ہے؟ تو کہیں گے کیوں نہیں ہمارے پروردگار کی قسم یہ حق ہے اللہ فرمائے گا کہ تم جو دنیا میں کفر کیا کرتے تھے تو اب اسکی وجہ سے عذاب کے مزے چکھو۔', 'اور جس دن سامنے لائیں منکروں کو آگ کے کیا یہ ٹھیک نہیں کہیں گے کیوں نہیں قسم ہے ہمارے رب کی [۶۱] کہا تو چکھو عذاب بدلا اس کا جو تم منکر ہوتے تھے [۶۲]', 'And on the Day when those who disbelieve will be exposed to the Fire (it will be said to them): \"Is this not the truth?\" They will say: \"Yes, By our Lord!\" He will say: \"Then taste the torment, because you used to disbelieve!\"', 'The day the disbelievers will be presented to the Fire, (it will be said to them,) “Is this not true?” They will say, “Yes of course, Our Lord!” He will say, “Then taste the punishment, for you used to disbelieve.”'),
(4545, 46, 35, 4, 4, 26, 'حٰمٓ۔', 'الاحقاف', 'فَاصۡبِرۡ کَمَا صَبَرَ اُولُوا الۡعَزۡمِ مِنَ الرُّسُلِ وَ لَا تَسۡتَعۡجِلۡ  لَّہُمۡ ؕ کَاَنَّہُمۡ یَوۡمَ یَرَوۡنَ مَا یُوۡعَدُوۡنَ ۙ لَمۡ  یَلۡبَثُوۡۤا اِلَّا سَاعَۃً  مِّنۡ نَّہَارٍ ؕ بَلٰغٌ ۚ فَہَلۡ یُہۡلَکُ  اِلَّا  الۡقَوۡمُ  الۡفٰسِقُوۡنَ ﴿٪۳۵﴾', 'پس اے نبی جس طرح اور عالی ہمت پیغمبر صبر کرتے رہے ہیں اسی طرح تم بھی صبر کرو اور انکے لئے عذاب جلدی نہ مانگو۔ جس دن یہ اس چیز کو دیکھیں گے جس کا ان سے وعدہ کیا جاتا ہے تو یہ خیال کریں گے کہ گویا دنیا میں رہے ہی نہ تھے مگر گھڑی بھر دن۔ یہ قرآن پیغام ہے جو پہنچایا جا چکا۔ سو اب وہی ہلاک ہوں گے جو نافرمان تھے۔', 'سو تو ٹھہرا رہ جیسے ٹھہرے رہے ہیں ہمت والے رسول اور جلدی نہ کر انکے معاملہ میں [۶۳] یہ لوگ جس دن دیکھ لیں گے اس چیز کو جس کا ان سےوعدہ ہے جیسے ڈھیل نہ پائی تھی مگر ایک گھڑی دن کی [۶۴] یہ پہنچا دینا ہے اب وہی غارت ہوں گے جو لوگ نافرمان ہیں [۶۵]', 'Therefore be patient (O Muhammad SAW) as did the Messengers of strong will and be in no haste about them (disbelievers). On the Day when they will see that (torment) with which they are promised (i.e. threatened, it will be) as if they had not stayed more than an hour in a single day. (O mankind! This Quran is sufficient as) a clear Message (or proclamation to save yourself from destruction). But shall any be destroyed except the people who are Al-Fasiqoon (the rebellious, disobedient to Allah).', 'So, (O prophet,) observe patience, as the resolute messengers observed patience, and be not in haste about them. The Day they will see what they are promised, (it will be) as if they did not stay (in the world) more than an hour in a single day. This is a message. So, none will be destroyed except the sinners.'),
(4546, 47, 1, 1, 5, 26, 'حٰمٓ۔', 'محمد', 'اَلَّذِیۡنَ  کَفَرُوۡا وَ صَدُّوۡا عَنۡ سَبِیۡلِ اللّٰہِ  اَضَلَّ  اَعۡمَالَہُمۡ ﴿۱﴾', 'جن لوگوں نے کفر کیا اور دوسروں کو اللہ کے رستے سے روکا اللہ نے انکے اعمال برباد کر دیئے۔', 'جو لوگ کہ منکر ہوئے اور  روکا اوروں کو اللہ کی راہ سے  [۱] کھو دیے اللہ نے انکے کئے کام [۲]', 'Those who disbelieve (in the Oneness of Allah, and in the Message of Prophet Muhammad SAW ), and hinder (men) from the Path of Allah (Islamic Monotheism), He will render their deeds vain .', 'Those who disbelieved, and prevented (others) from Allah’s way, He (Allah) has rendered their deeds vain.'),
(4547, 47, 2, 1, 5, 26, 'حٰمٓ۔', 'محمد', 'وَ الَّذِیۡنَ  اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ وَ اٰمَنُوۡا بِمَا نُزِّلَ عَلٰی مُحَمَّدٍ وَّ ہُوَ الۡحَقُّ مِنۡ  رَّبِّہِمۡ ۙ کَفَّرَ عَنۡہُمۡ سَیِّاٰتِہِمۡ  وَ اَصۡلَحَ بَالَہُمۡ ﴿۲﴾', 'اور جو لوگ ایمان لائے اور نیک عمل کرتے رہے اور جو کتاب محمد ﷺ پر نازل ہوئی اسے مانتے رہے اور وہ انکے پروردگار کی طرف سے برحق ہے کہ جس نے انکے گناہ دور کر دیئے اور انکی حالت سنوار دی۔', 'اور جو یقین لائے اور کئے بھلے کام اور مانا اسکو جو اترا محمد پر اور وہی ہے سچا دین انکے رب کی طرف سے ان پر سے اتاریں انکی برائیاں اور سنورا انکا حال [۳]', 'But those who believe and do righteous good deeds, and believe in that which is sent down to Muhammad (SAW), for it is the truth from their Lord, He will expiate from them their sins, and will make good their state.', 'And those who believed and did righteous deeds and believed in that which is revealed to MuHammad,-and it is the truth (that has come) from their Lord-He will write off their evil deeds, and will set aright their state of affairs.'),
(4548, 47, 3, 1, 5, 26, 'حٰمٓ۔', 'محمد', 'ذٰلِکَ بِاَنَّ  الَّذِیۡنَ کَفَرُوا اتَّبَعُوا الۡبَاطِلَ وَ اَنَّ  الَّذِیۡنَ اٰمَنُوا اتَّبَعُوا الۡحَقَّ مِنۡ  رَّبِّہِمۡ ؕ کَذٰلِکَ یَضۡرِبُ اللّٰہُ لِلنَّاسِ اَمۡثَالَہُمۡ ﴿۳﴾', 'یہ اعمال کی بربادی اور اصلاح حال اس لئے ہے کہ جن لوگوں نے کفر کیا انہوں نے جھوٹی بات کی پیروی کی اور جو ایمان لائے وہ اپنے پروردگار کی طرف سے دین حق کے پیچھے چلے۔ اسی طرح اللہ لوگوں سے انکے حالات بیان فرماتا ہے۔', 'یہ اس لئے کہ جو منکر ہیں وہ چلے جھوٹی بات پر اور جو یقین لائے انہوں نے مانی سچی بات اپنے رب کی طرف سے یوں بتلاتا ہے اللہ لوگوں کو انکے احوال [۴]', 'That is because those who disbelieve follow falsehood, while those who believe follow the truth from their Lord. Thus does Allah set forth their parables for mankind.', 'That is because the disbelievers have followed falsehood, while the believers have followed the truth (that has come) from their Lord. This is how Allah explains their (respective) situations to the people.'),
(4549, 47, 4, 1, 5, 26, 'حٰمٓ۔', 'محمد', 'فَاِذَا  لَقِیۡتُمُ  الَّذِیۡنَ کَفَرُوۡا فَضَرۡبَ الرِّقَابِ ؕ حَتّٰۤی  اِذَاۤ  اَثۡخَنۡتُمُوۡہُمۡ فَشُدُّوا الۡوَثَاقَ ٭ۙ فَاِمَّا مَنًّۢا بَعۡدُ وَ  اِمَّا فِدَآءً  حَتّٰی تَضَعَ  الۡحَرۡبُ اَوۡزَارَہَا ۬ۚ۟ۛ ذٰؔلِکَ ؕۛ وَ لَوۡ  یَشَآءُ  اللّٰہُ  لَانۡتَصَرَ  مِنۡہُمۡ وَ لٰکِنۡ  لِّیَبۡلُوَا۠ بَعۡضَکُمۡ  بِبَعۡضٍ ؕ وَ الَّذِیۡنَ قُتِلُوۡا فِیۡ  سَبِیۡلِ اللّٰہِ  فَلَنۡ یُّضِلَّ  اَعۡمَالَہُمۡ ﴿۴﴾', 'پس جب تم کافروں سے بھڑ جاؤ تو انکی گردنیں اڑا دو۔ یہاں تک کہ جب انکو خوب قتل کر چکو تو جو زندہ پکڑے جائیں انکو مضبوطی سے قید کر لو۔ پھر اسکے بعد یا تو احسان رکھ کو چھوڑ دینا چاہیے یا کچھ مال لے کر یہاں تک کہ فریق مقابل لڑائی کے ہتھیار رکھ دے یہ حکم یاد رکھو اور اگر اللہ چاہتا تو اور طرح سے ان سے انتقام لے لیتا لیکن اس نے چاہا کہ تم میں سے ایک کو دوسرے کے ساتھ ٹکرا کر آزمائے اور جو لوگ اللہ کی راہ میں مارے گئے انکے اعمال کو وہ ہرگز ضائع نہیں کرے گا۔', 'سو جب تم مقابل ہو منکروں کے تو مارو گردنیں یہاں تک کہ جب خوب قتل کر چکو انکو تو مضبوط باندھ لو قید پھر یا احسان کیجیو اور یا معاوضہ لیجیو [۵] جب تک کہ رکھ دے لڑائی اپنے ہتھیار [۶] یہ سن چکے اور اگر چاہے اللہ تو بدلا لے ان سے پر جانچنا چاہتا ہے تمہارے ایک سے دوسرے کو [۷] اور جو لوگ مارے گئے اللہ کی راہ میں تو نہ ضائع کرے گا وہ انکے کئے کام', 'So, when you meet (in fight Jihad in Allahs Cause), those who disbelieve smite at their necks till when you have killed and wounded many of them, then bind a bond firmly (on them, i.e. take them as captives). Thereafter (is the time) either for generosity (i.e. free them without ransom), or ransom (according to what benefits Islam), until the war lays down its burden. Thus (you are ordered by Allah to continue in carrying out Jihad against the disbelievers till they embrace Islam (i.e. are saved from the punishment in the Hell-fire) or at least come under your protection), but if it had been Allahs Will, He Himself could certainly have punished them (without you). But (He lets you fight), in order to test you, some with others. But those who are killed in the Way of Allah, He will never let their deeds be lost,', 'So, when you encounter those who disbelieve, then (aim at) smiting the necks, until when you have broken their strength thoroughly, then tie fast the bond, (by making them captives). Then choose (to release them) either (as) a favour (shown to them,), or (after receiving) ransom,until the war throws down its load of arms. That (is Our command.) If Allah willed, He would have (Himself) subjected them to retribution, but (Allah ordered you to fight,) so that He may test some of you through some others. And those who are killed in Allah’s way, He will never let their deeds go to waste.'),
(4550, 47, 5, 1, 5, 26, 'حٰمٓ۔', 'محمد', 'سَیَہۡدِیۡہِمۡ  وَ  یُصۡلِحُ   بَالَہُمۡ ۚ﴿۵﴾', 'بلکہ انکو سیدھے رستے پر چلائے گا اور انکی حالت درست کر دے گا۔', 'انکو راہ دے گا اور سنوارے گا  ان کا حال [۸]', 'He will guide them and set right their state.', '(Instead,) He will guide them, and will set aright their state of affairs,'),
(4551, 47, 6, 1, 5, 26, 'حٰمٓ۔', 'محمد', 'وَ  یُدۡخِلُہُمُ  الۡجَنَّۃَ  عَرَّفَہَا  لَہُمۡ ﴿۶﴾', 'اور انکو بہشت میں جس سے انکو پہلے سے واقف کر دیا ہے داخل کرے گا۔', 'اور داخل کرے گا انکو بہشت میں جو معلوم کرا دی ہے انکو [۹]', 'And admit them to Paradise which He has made known to them (i.e. they will know their places in Paradise more than they used to know their houses in the world).', 'and will admit them to the Paradise He has identified for them.'),
(4552, 47, 7, 1, 5, 26, 'حٰمٓ۔', 'محمد', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اِنۡ تَنۡصُرُوا اللّٰہَ یَنۡصُرۡکُمۡ  وَ  یُثَبِّتۡ  اَقۡدَامَکُمۡ ﴿۷﴾', 'اے اہل ایمان اگر تم اللہ کی مدد کرو گے تو وہ بھی تمہاری مدد کرے گا اور تمکو ثابت قدم رکھے گا۔', 'اے ایمان والو اگر تم مدد کر و گے اللہ کی [۱۰] تو وہ تمہاری مدد کرے گا اور جما دے گا تمہارے پاؤں [۱۱]', 'O you who believe! If you help (in the cause of) Allah, He will help you, and make your foothold firm.', 'O you who believe, if you will help (the religion prescribed by) Allah, He will help you, and will stabilize your footings.'),
(4553, 47, 8, 1, 5, 26, 'حٰمٓ۔', 'محمد', 'وَ الَّذِیۡنَ کَفَرُوۡا  فَتَعۡسًا لَّہُمۡ وَ اَضَلَّ اَعۡمَالَہُمۡ ﴿۸﴾', 'اور جو کافر ہیں انکے لئے ہلاکت ہے۔ اور اللہ انکے اعمال کو برباد کر دے گا۔', 'اور جو لوگ کہ منکر ہوئے وہ گرے منہ کے بل اور کھو دیے انکے کئے کام [۱۲]', 'But those who disbelieve (in the Oneness of Allah Islamic Monotheism), for them is destruction, and (Allah) will make their deeds vain.', 'As for those who disbelieve, (destined) for them is destruction, and He has rendered their deeds vain.'),
(4554, 47, 9, 1, 5, 26, 'حٰمٓ۔', 'محمد', 'ذٰلِکَ بِاَنَّہُمۡ کَرِہُوۡا مَاۤ  اَنۡزَلَ اللّٰہُ فَاَحۡبَطَ اَعۡمَالَہُمۡ ﴿۹﴾', 'یہ اس لئے کہ اللہ نے جو چیز نازل فرمائی انہوں نے اسکو ناپسند کیا تو اللہ نے انکے اعمال اکارت کر دیئے۔', 'یہ اس لئے کہ انکو پسند نہ ہوا جو اتار اللہ نے پھر اکارت کر دیے انکے کئے کام [۱۳]', 'That is because they hate that which Allah has sent down (this Quran and Islamic laws, etc.), so He has made their deeds fruitless.', 'That is because they hate what Allah has sent down; therefore Allah has nullified their deeds.'),
(4555, 47, 10, 1, 5, 26, 'حٰمٓ۔', 'محمد', 'اَفَلَمۡ یَسِیۡرُوۡا فِی الۡاَرۡضِ فَیَنۡظُرُوۡا کَیۡفَ کَانَ عَاقِبَۃُ  الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ ؕ دَمَّرَ اللّٰہُ عَلَیۡہِمۡ ۫ وَ لِلۡکٰفِرِیۡنَ اَمۡثَالُہَا ﴿۱۰﴾', 'کیا انہوں نے ملک میں سیر نہیں کی۔ تاکہ دیکھتے کہ جو لوگ ان سے پہلے تھے ان کا انجام کیسا ہوا؟ اللہ نے ان پر تباہی ڈال دی اور اسی طرح کا عذاب ان کافروں کو بھی ہو گا۔', 'کیا وہ پھرے نہیں ملک میں کہ دیکھیں کیسا ہوا انجام ان کا جو ان سے پہلے تھے ہلاکی  ڈالی اللہ نے ان پر اور منکروں کو ملتی رہی ہیں ایسی چیزیں [۱۴]', 'Have they not travelled through the earth, and seen what was the end of those before them? Allah destroyed them completely and a similar (fate awaits) the disbelievers.', 'Have they not travelled in the land so that they might see how was the end of those before them? Allah brought utter destruction to them. And (ready) for (these) disbelievers are the likes thereof.'),
(4556, 47, 11, 1, 5, 26, 'حٰمٓ۔', 'محمد', 'ذٰلِکَ بِاَنَّ اللّٰہَ مَوۡلَی الَّذِیۡنَ اٰمَنُوۡا وَ اَنَّ الۡکٰفِرِیۡنَ لَا  مَوۡلٰی  لَہُمۡ ﴿٪۱۱﴾', 'یہ اس لئے کہ جو مومن ہیں ان کا اللہ کارساز ہے اور کافروں کا کوئی کارساز نہیں۔', 'یہ اس لئے کہ اللہ رفیق ہے ان کا جو یقین لائے اور یہ کہ جو منکر ہیں ان کا رفیق نہیں کوئی [۱۵]', 'That is because Allah is the Maula (Lord, Master, Helper, Protector, etc.) of those who believe, and the disbelievers have no Maula (lord, master, helper, protector, etc.).', 'That is because Allah is the supporter of those who believe. As for the disbelievers, there is no supporter for them.'),
(4557, 47, 12, 2, 6, 26, 'حٰمٓ۔', 'محمد', 'اِنَّ اللّٰہَ یُدۡخِلُ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ جَنّٰتٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ ؕ وَ الَّذِیۡنَ کَفَرُوۡا یَتَمَتَّعُوۡنَ وَ یَاۡکُلُوۡنَ کَمَا تَاۡکُلُ الۡاَنۡعَامُ وَ النَّارُ مَثۡوًی لَّہُمۡ ﴿۱۲﴾', 'جو لوگ ایمان لائے اور عمل نیک کرتے رہے انکو اللہ بہشتوں میں جنکے نیچے نہریں بہ رہی ہیں داخل فرمائے گا۔ اور جو کافر ہیں وہ فائدے اٹھاتے ہیں اور اس طرح کھاتے ہیں جیسے حیوان کھاتے ہیں۔ اور ان کا ٹھکانہ دوزخ ہے۔', 'مقرر اللہ داخل کرے گا انکو جو یقین لائے اور کئے بھلے کام باغوں میں جنکے نیچے بہتی ہیں نہریں اور جو لو گ منکر ہیں برت رہے ہیں اور کھاتے ہیں جیسے کہ کھائیں چوپائے اور آگ ہے گھر ان کا [۱۶]', 'Certainly! Allah will admit those who believe (in the Oneness of Allah Islamic Monotheism) and do righteous good deeds, to Gardens under which rivers flow (Paradise), while those who disbelieve enjoy themselves and eat as cattle eat, and the Fire will be their abode.', 'Surely, Allah will admit those who believe and do good deeds to the gardens beneath which rivers flow. As for those who disbelieve, they enjoy (the worldly life), and eat as cattle eat, and the Fire is the final abode for them.'),
(4558, 47, 13, 2, 6, 26, 'حٰمٓ۔', 'محمد', 'وَ کَاَیِّنۡ مِّنۡ  قَرۡیَۃٍ  ہِیَ اَشَدُّ  قُوَّۃً  مِّنۡ قَرۡیَتِکَ الَّتِیۡۤ  اَخۡرَجَتۡکَ ۚ اَہۡلَکۡنٰہُمۡ فَلَا  نَاصِرَ  لَہُمۡ ﴿۱۳﴾', 'اور بہت سی بستیاں تمہاری بستی سے جسکے باشندوں نے تمہیں وہاں سے نکال دیا زورو قوت میں کہیں بڑھ کر تھیں ہم نے انکو برباد کر دیا اور ان کا کوئی مددگار نہ ہوا۔', 'اور کتنی تھیں بستیاں جو زیادہ تھیں زور میں اس تیری بستی سے جس نے تجھ کو نکالا ہم نے انکو غارت کر دیا پھر کوئی نہیں ان کا مددگار [۱۷]', 'And many a town, stronger than your town (Makkah) (O Muhammad SAW) which has driven you out We have destroyed. And there was none to help them.', 'How many a town, stronger in might than your town that has expelled you, have We destroyed! Then, there was none to help them.'),
(4559, 47, 14, 2, 6, 26, 'حٰمٓ۔', 'محمد', 'اَفَمَنۡ کَانَ عَلٰی بَیِّنَۃٍ  مِّنۡ  رَّبِّہٖ  کَمَنۡ زُیِّنَ  لَہٗ  سُوۡٓءُ عَمَلِہٖ  وَ اتَّبَعُوۡۤا اَہۡوَآءَہُمۡ ﴿۱۴﴾', 'بھلا جو شخص اپنے پروردگار کی مہربانی سے کھلے رستے پر چل رہا ہو وہ انکی طرح ہو سکتا ہے جنکے اعمال بد انہیں اچھے کر کے دکھائے جائیں اور جو اپنی خواہشوں کی پیروی کریں۔', 'بھلا ایک جو چلتا ہے واضح رستہ پر اپنے رب کے برابر ہے اسکے جسکو  بھلا دکھلایا اس کا برا کام اور چلتے ہیں اپنی خواہشوں پر [۱۸]', 'Is he who is on a clear proof from his Lord, like those for whom their evil deeds that they do are beautified for them, while they follow their own lusts (evil desires)?', 'Then, can one who holds on to a clear proof from his Lord be like those for whom their evil deeds are beautified, and who followed their desires?'),
(4560, 47, 15, 2, 6, 26, 'حٰمٓ۔', 'محمد', 'مَثَلُ الۡجَنَّۃِ الَّتِیۡ وُعِدَ الۡمُتَّقُوۡنَ ؕ فِیۡہَاۤ اَنۡہٰرٌ  مِّنۡ  مَّآءٍ غَیۡرِ اٰسِنٍ ۚ وَ  اَنۡہٰرٌ مِّنۡ لَّبَنٍ لَّمۡ  یَتَغَیَّرۡ  طَعۡمُہٗ ۚ وَ اَنۡہٰرٌ  مِّنۡ خَمۡرٍ  لَّذَّۃٍ   لِّلشّٰرِبِیۡنَ ۬ۚ وَ اَنۡہٰرٌ مِّنۡ عَسَلٍ مُّصَفًّی ؕ وَ لَہُمۡ  فِیۡہَا مِنۡ کُلِّ الثَّمَرٰتِ وَ مَغۡفِرَۃٌ  مِّنۡ  رَّبِّہِمۡ ؕ  کَمَنۡ ہُوَ خَالِدٌ فِی النَّارِ وَ سُقُوۡا مَآءً حَمِیۡمًا فَقَطَّعَ  اَمۡعَآءَہُمۡ ﴿۱۵﴾', 'وہ جنت جس کا پرہیزگاروں سے وعدہ کیا جاتا ہے اسکی صفت یہ ہے کہ اس میں ایسے پانی کی نہریں ہیں جو بو نہیں کرے گا۔ اور دودھ کی نہریں ہیں جس کا مزہ نہیں بدلے گا۔ اور شراب کی نہریں ہیں جو پینے والوں کے لئے سراسر لذت ہے اور صاف شدہ شہد کی نہریں ہیں اور وہاں انکے لئے ہر قسم کے میوے ہیں اور انکے پروردگار کی طرف سے مغفرت ہے۔ کیا یہ پرہیزگار انکی طرح ہو سکتے ہیں جو ہمیشہ دوزخ میں رہیں گے۔ اور جنکو کھولتا ہوا پانی پلایا جائے گا جو انکی آنتوں کو ٹکڑے ٹکڑے کر ڈالے گا۔', 'احوال اس بہشت کا جس کا وعدہ ہوا ہے ڈرنے والوں سے اس میں نہریں ہیں پانی کی جو بو نہیں کر گیا [۱۹] اور نہریں ہیں دودھ کی جس کا مزہ نہیں پھرا [۲۰] اور نہریں ہیں شراب کی جس میں مزہ ہے پینے والوں کے واسطے [۲۱] اور نہریں ہیں شہد کی جھاگ اترا ہوا [۲۲] اور انکے لئے وہاں سب طرح کے میوےہیں [۲۳] اور معافی ہے انکے رب سے [۲۴] یہ برابر ہے اسکے جو سدا رہے آگ میں اور پلایا جائے انکو کھولتا پانی تو کاٹ نکالے انکی آنتیں [۲۵]', 'The description of Paradise which the Muttaqoon (pious - see V.2:2) have been promised is that in it are rivers of water the taste and smell of which are not changed; rivers of milk of which the taste never changes; rivers of wine delicious to those who drink; and rivers of clarified honey (clear and pure) therein for them is every kind of fruit; and forgiveness from their Lord. (Are these) like those who shall dwell for ever in the Fire, and be given, to drink, boiling water, so that it cuts up their bowels?', '(Here is) a description of the Paradise that is promised for the God-fearing! In it there are rivers of water, never spoiling, and rivers of milk the taste of which would not go bad, and rivers of wine, delicious to the drinkers, and rivers of honey, fully purified. And for them there are all sorts of fruits, and forgiveness from their Lord. Are they like those who will live in Fire forever, and will be given boiling water to drink, and it will tear their bowels into pieces?'),
(4561, 47, 16, 2, 6, 26, 'حٰمٓ۔', 'محمد', 'وَ مِنۡہُمۡ  مَّنۡ یَّسۡتَمِعُ  اِلَیۡکَ ۚ حَتّٰۤی  اِذَا خَرَجُوۡا مِنۡ عِنۡدِکَ قَالُوۡا لِلَّذِیۡنَ اُوۡتُوا الۡعِلۡمَ  مَاذَا  قَالَ  اٰنِفًا ۟ اُولٰٓئِکَ الَّذِیۡنَ طَبَعَ اللّٰہُ  عَلٰی قُلُوۡبِہِمۡ وَ اتَّبَعُوۡۤا  اَہۡوَآءَہُمۡ ﴿۱۶﴾', 'اور ان میں بعض ایسے بھی ہیں جو تمہاری طرف کان لگائے رہتے ہیں۔ یہاں تک کہ سب کچھ سنتے ہیں لیکن جب تمہارے پاس سے نکل کر چلےجاتے ہیں تو جن لوگوں کو علم دین دیا گیا ہے ان سے کہتے ہیں کہ بھلا انہوں نے ابھی کیا کہا تھا؟ یہی لوگ ہیں جنکے دلوں پر اللہ نے مہر لگا رکھی ہے اور یہ اپنی خواہشوں کے پیچھے چل رہے ہیں۔', 'اور بعضے ان میں ہیں کہ کان رکھتے ہیں تیری طرف یہاں تک کہ جب نکلیں تیرے پاس سے کہتے ہیں انکو جنکو علم ملا ہے کیا کہا تھا اس شخص نے ابھی [۲۶] یہ وہی ہیں جنکے دلوں پر مہر لگا دی ہے اللہ نے اور چلے ہیں اپنی خواہشوں پر [۲۷]', 'And among them are some who listen to you (O Muhammad SAW) till, when they go out from you, they say to those who have received knowledge: \"What has he said just now? Such are men whose hearts Allah has sealed, and they follow their lusts (evil desires).', 'Among them there are ones who (pretend to) give ear to you, until when they go out from your presence, they say to those who have been given knowledge, “What did he say just now?” Those are the ones on whose hearts Allah has put a seal, and they have followed their desires.'),
(4562, 47, 17, 2, 6, 26, 'حٰمٓ۔', 'محمد', 'وَ الَّذِیۡنَ اہۡتَدَوۡا زَادَہُمۡ ہُدًی وَّ اٰتٰہُمۡ تَقۡوٰىہُمۡ ﴿۱۷﴾', 'اور جو لوگ ہدایت یافتہ ہیں انکو وہ مزید ہدایت بخشتا ہے اور انکو پرہیزگاری عنایت کرتا ہے۔', 'اور جو لوگ راہ پر آئے ہیں انکو اور بڑھ گئ اس سے سوجھ اور انکو اس سے ملا بچ کر چلنا [۲۸]', 'While as for those who accept guidance, He increases their guidance, and bestows on them their piety.', 'As for those who have adopted right path, Allah improves them in guidance, and gives them their piety.'),
(4563, 47, 18, 2, 6, 26, 'حٰمٓ۔', 'محمد', 'فَہَلۡ یَنۡظُرُوۡنَ  اِلَّا السَّاعَۃَ  اَنۡ تَاۡتِیَہُمۡ بَغۡتَۃً ۚ فَقَدۡ جَآءَ  اَشۡرَاطُہَا ۚ فَاَنّٰی لَہُمۡ  اِذَا جَآءَتۡہُمۡ  ذِکۡرٰىہُمۡ ﴿۱۸﴾', 'اب تو یہ لوگ قیامت ہی کی راہ دیکھتے ہیں کہ ناگہاں ان پر آ واقع ہو سو اسکی نشانیاں سامنے آ چکی ہیں۔ پھر جب وہ ان پر آ نازل ہو گی اس وقت انہیں نصیحت کہاں مفید ہو سکے گی؟', 'اب یہی انتظار کرتے ہیں قیامت کا کہ آ کھڑی ہو ان  پر اچانک سو  آچکی ہیں اسکی نشانیاں پھر کہاں نصیب ہو گا انکو جب وہ آ پہنچے ان پر سمجھ پکڑنا [۲۹]', 'Do they then await (anything) other than the Hour, that it should come upon them suddenly? But some of its portents (indications and signs) have already come, and when it (actually) is on them, how can they benefit then by their reminder?', 'They are waiting for nothing but for the Hour (of Doom) that it should come upon them suddenly. So, its signs have already come. Then, once it will come upon them, how would they have an opportunity to accept the advice (already) given to them?'),
(4564, 47, 19, 2, 6, 26, 'حٰمٓ۔', 'محمد', 'فَاعۡلَمۡ  اَنَّہٗ  لَاۤ اِلٰہَ  اِلَّا اللّٰہُ  وَ اسۡتَغۡفِرۡ لِذَنۡۢبِکَ وَ لِلۡمُؤۡمِنِیۡنَ وَ الۡمُؤۡمِنٰتِ ؕ وَ اللّٰہُ  یَعۡلَمُ مُتَقَلَّبَکُمۡ وَ مَثۡوٰىکُمۡ ﴿٪۱۹﴾', 'پس جان رکھو کہ اللہ کے سوا کوئی معبود نہیں اور اپنے قصور کی معافی مانگو اور مومن مردوں اور مومن عورتوں کے لئے بھی۔ اور اللہ تم لوگوں کے چلنے پھرنے اور تمہارے ٹھکانے سے واقف ہے۔', 'سو تو جان لے کہ کسی کی بندگی نہیں سوائے اللہ کے اور معافی مانگ اپنے گناہ کے  واسطے اور ایماندار مردوں اور عورتوں کے لئے [۳۰] اور اللہ کو معلوم ہے بازگشت تمہاری اور گھر تمہارا [۳۱]', 'So know (O Muhammad SAW) that La ilaha ill-Allah (none has the right to be worshipped but Allah), and ask forgiveness for your sin, and also for (the sin of) believing men and believing women. And Allah knows well your moving about, and your place of rest (in your homes).', 'So, be assured that there is no god but Allah, and seek forgiveness for your fault, and for (the faults of) the believing men and believing women. And Allah knows your moving from place to place and your permanent abode.'),
(4565, 47, 20, 3, 7, 26, 'حٰمٓ۔', 'محمد', 'وَ یَقُوۡلُ  الَّذِیۡنَ اٰمَنُوۡا لَوۡ لَا نُزِّلَتۡ سُوۡرَۃٌ ۚ فَاِذَاۤ  اُنۡزِلَتۡ سُوۡرَۃٌ  مُّحۡکَمَۃٌ وَّ ذُکِرَ فِیۡہَا الۡقِتَالُ ۙ رَاَیۡتَ الَّذِیۡنَ فِیۡ قُلُوۡبِہِمۡ  مَّرَضٌ یَّنۡظُرُوۡنَ  اِلَیۡکَ نَظَرَ الۡمَغۡشِیِّ عَلَیۡہِ مِنَ الۡمَوۡتِ ؕ فَاَوۡلٰی لَہُمۡ ﴿ۚ۲۰﴾', 'اور مومن لوگ کہتے ہیں کہ جہاد سے متعلق کوئی سورت کیوں نازل نہیں ہوتی؟ لیکن جب کوئی واضح احکام والی سورت نازل ہو اور اس میں جنگ کا بیان ہو۔ تو جن لوگوں کے دلوں میں نفاق کا مرض ہے تم انکو دیکھو کہ تمہاری طرف اس طرح دیکھنے لگیں جس طرح کسی پر موت کی بیہوشی طاری ہو رہی ہو سو انکے لئے خرابی ہے۔', 'اور کہتے ہیں ایمان والے کیوں نہ اتری ایک سورت [۳۲] پھر جب اتری ایک سورت جانچی ہوئی [۳۳] اور ذکر ہوا اس میں لڑائی کا  تو تو دیکھتا ہے انکو جنکے دل میں روگ ہے تکتے ہیں تیری طرف جیسے تکتا ہے کوئی بیہوش پڑا ہوا مرنے کے وقت سو خرابی ہے انکی [۳۴]', 'Those who believe say: \"Why is not a Soorah (chapter of the Quran) sent down (for us)? But when a decisive Soorah (explaining and ordering things) is sent down, and fighting (Jihad holy fighting in Allahs Cause) is mentioned (i.e. ordained) therein, you will see those in whose hearts is a disease (of hypocrisy) looking at you with a look of one fainting to death. But it was better for them (hypocrites, to listen to Allah and to obey Him).', 'And the believers say, “Why has a (new) Sūrah not been revealed?” Then, once an operative Sūrah is sent down, and fighting (in Allah’s way) is mentioned in it, you notice those who have disease in their hearts, looking to you like one who is faint because of death. So, destruction is very close to them.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(4566, 47, 21, 3, 7, 26, 'حٰمٓ۔', 'محمد', 'طَاعَۃٌ  وَّ قَوۡلٌ  مَّعۡرُوۡفٌ ۟ فَاِذَا عَزَمَ الۡاَمۡرُ ۟ فَلَوۡ صَدَقُوا اللّٰہَ  لَکَانَ خَیۡرًا لَّہُمۡ ﴿ۚ۲۱﴾', 'خوب کام تو فرمانبرداری اور پسندیدہ بات کہنا ہے پھر جب جہاد کی بات پختہ ہو گئ تو اگر یہ لوگ اللہ سے سچے رہنا چاہتے تو انکے لئے بہت اچھا ہوتا۔', 'حکم ماننا ہے اور بھلی بات کہنی پھر جب تاکید ہو کام کی تو اگر سچے رہیں اللہ سے تو ان کا بھلا ہے [۳۵]', 'Obedience (to Allah) and good words (were better for them). And when the matter (preparation for Jihad) is resolved on, then if they had been true to Allah, it would have been better for them.', 'The (reality of their) obedience and (truthfulness of their) speech is fully known (as being mere deception). So, had they been truthful to Allah when the matter had become serious, it would have been much better for them.'),
(4567, 47, 22, 3, 7, 26, 'حٰمٓ۔', 'محمد', 'فَہَلۡ  عَسَیۡتُمۡ  اِنۡ تَوَلَّیۡتُمۡ  اَنۡ تُفۡسِدُوۡا فِی  الۡاَرۡضِ وَ تُقَطِّعُوۡۤا  اَرۡحَامَکُمۡ ﴿۲۲﴾', 'سو اے منافقو عجب نہیں کہ اگر تم حاکم ہو جاؤ تو ملک میں خرابی کرنے لگو اور اپنے رشتوں کو توڑ ڈالو۔', 'پھر تم سے یہ بھی توقع ہے کہ اگر تمکو حکومت مل جائے تو خرابی ڈالو ملک میں اور قطع کرو اپنی قرابتیں [۳۶]', 'Would you then, if you were given the authority, do mischief in the land, and sever your ties of kinship?', 'So, (O hypocrites,) do you not apprehend that, in case you turn away (from Jihād ), you will spread disorder in the land and will sever your ties of kinship?'),
(4568, 47, 23, 3, 7, 26, 'حٰمٓ۔', 'محمد', 'اُولٰٓئِکَ الَّذِیۡنَ لَعَنَہُمُ اللّٰہُ فَاَصَمَّہُمۡ وَ اَعۡمٰۤی  اَبۡصَارَہُمۡ ﴿۲۳﴾', 'یہی لوگ ہیں جن پر اللہ نے لعنت کی ہے اور انکے کانوں کو بہرا اور انکی آنکھوں کو اندھا کر دیا ہے۔', 'ایسے لوگ ہیں جن پر لعنت کی اللہ نے پھر کردیا انکو بہرا اور اندھی کردیں اُنکی آنکھیں [۳۷]', 'Such are they whom Allah has cursed, so that He has made them deaf and blinded their sight.', 'Those are the ones whom Allah has cursed; so He has made them deaf, and made their eyes blind.'),
(4569, 47, 24, 3, 7, 26, 'حٰمٓ۔', 'محمد', 'اَفَلَا یَتَدَبَّرُوۡنَ الۡقُرۡاٰنَ  اَمۡ عَلٰی قُلُوۡبٍ اَقۡفَالُہَا  ﴿۲۴﴾', 'بھلا یہ لوگ قرآن میں غور نہیں کرتے یا انکے دلوں پر قفل پڑے ہیں۔', 'کیا دھیان نہیں کرتے قرآن میں یا دلوں پر لگ رہے ہیں انکے قفل [۳۸]', 'Do they not then think deeply in the Quran, or are their hearts locked up (from understanding it)?', 'Then, do they not give serious thought to the Qur’ān, or do they have locks on their hearts?'),
(4570, 47, 25, 3, 7, 26, 'حٰمٓ۔', 'محمد', 'اِنَّ  الَّذِیۡنَ ارۡتَدُّوۡا عَلٰۤی  اَدۡبَارِہِمۡ مِّنۡۢ بَعۡدِ مَا تَبَیَّنَ  لَہُمُ  الۡہُدَی ۙ الشَّیۡطٰنُ سَوَّلَ  لَہُمۡ ؕ وَ اَمۡلٰی  لَہُمۡ ﴿۲۵﴾', 'جو لوگ راہ ہدایت ظاہر ہونے کے بعد پیٹھ پھیر گئے شیطان نے یہ کام انکو اچھا کر کے دکھایا۔ اور انہیں لمبی عمر کا وعدہ دیا۔', 'بیشک جو لوگ الٹے پھر گئے اپنی پیٹھ پر بعد اسکے کہ ظاہر ہو چکی ان پر سیدھی راہ شیطان نے بات بنائی انکے دل میں اور دیر کے وعدے کئے [۳۹]', 'Verily, those who have turned back (have apostated) as disbelievers after the guidance has been manifested to them, Shaitan (Satan) has beautified for them (their false hopes), and (Allah) prolonged their term (age).', 'Surely those who turn back after the guidance has appeared to them clearly, it is Satan who has tempted them and involved them in far-fetched fancies.'),
(4571, 47, 26, 3, 7, 26, 'حٰمٓ۔', 'محمد', 'ذٰلِکَ بِاَنَّہُمۡ  قَالُوۡا لِلَّذِیۡنَ کَرِہُوۡا مَا نَزَّلَ  اللّٰہُ سَنُطِیۡعُکُمۡ  فِیۡ بَعۡضِ الۡاَمۡرِ ۚۖ وَ اللّٰہُ  یَعۡلَمُ   اِسۡرَارَہُمۡ ﴿۲۶﴾', 'یہ اس لئے کہ جو لوگ اللہ کی اتاری ہوئی کتاب سے بیزار ہیں یہ ان سے کہتے ہیں کہ بعض کاموں میں ہم تمہاری بات بھی مانیں گے اور اللہ انکے پوشیدہ مشوروں سے واقف ہے۔', 'یہ اس واسطے کہ انہوں نے کہا ان لوگوں سے جو بیزار ہیں اللہ کی اتاری کتاب سے ہم تمہاری بات بھی مانیں گے بعضے کاموں میں اور اللہ جانتا ہے ان کا مشورہ کرنا [۴۰]', 'This is because they said to those who hate what Allah has sent down: \"We will obey you in part of the matter,\" but Allah knows their secrets.', 'That is because they say to those who hate that which Allah has revealed, “We will obey you in some respects.” And Allah knows their secret talk.'),
(4572, 47, 27, 3, 7, 26, 'حٰمٓ۔', 'محمد', 'فَکَیۡفَ اِذَا تَوَفَّتۡہُمُ  الۡمَلٰٓئِکَۃُ یَضۡرِبُوۡنَ وُجُوۡہَہُمۡ  وَ  اَدۡبَارَہُمۡ ﴿۲۷﴾', 'تو اس وقت ان کا کیسا حال ہو گا جب فرشتے انکی جان نکالیں گے اور انکے چہروں اور پیٹھوں پر مارتے جائیں گے۔', 'پھر کیسا ہوگا حال جبکہ فرشتے جان نکالیں گے اُنکی مارتے جاتے ہوں انکے منہ پر اور پیٹھ پر [۴۱]', 'Then how (will it be) when the angels will take their souls at death, smiting their faces and their backs?', 'So, how (miserable) will they be when the angels will exact their souls, smiting their faces and their backs?'),
(4573, 47, 28, 3, 7, 26, 'حٰمٓ۔', 'محمد', 'ذٰلِکَ بِاَنَّہُمُ  اتَّبَعُوۡا مَاۤ  اَسۡخَطَ اللّٰہَ وَ کَرِہُوۡا  رِضۡوَانَہٗ  فَاَحۡبَطَ اَعۡمَالَہُمۡ ﴿٪۲۸﴾', 'یہ اس لئے کہ جس چیز سے اللہ ناخوش ہے یہ اس کے پیچھے چلے اور اسکی خوشنودی کو اچھا نہ سمجھے تو اس نے بھی انکے اعمال کو برباد کر دیا۔', 'یہ اس لئے کہ وہ چلے اس راہ جس سے اللہ بیزار ہے اور ناپسند کی اسکی خوشی پھر اس نے اکارت کردیے انکے کیے کام [۴۲]', 'That is because they followed that which angered Allah, and hated that which pleased Him. So He made their deeds fruitless.', 'That is because they followed that which has angered Allah, and they disliked His pleasure; therefore He has nullified their deeds.'),
(4574, 47, 29, 4, 8, 26, 'حٰمٓ۔', 'محمد', 'اَمۡ حَسِبَ الَّذِیۡنَ فِیۡ  قُلُوۡبِہِمۡ مَّرَضٌ اَنۡ  لَّنۡ یُّخۡرِجَ اللّٰہُ  اَضۡغَانَہُمۡ ﴿۲۹﴾', 'کیا وہ لوگ جنکے دلوں میں بیماری ہے یہ خیال کئے ہوئے ہیں کہ اللہ انکے کینوں کو ظاہر نہیں کرے گا؟', 'کیا خیال رکھتے ہیں وہ لوگ جنکے دلوں میں روگ ہے کہ اللہ ظاہر نہ کر دے گا اُنکے کینے [۴۳]', 'Or do those in whose hearts is a disease (of hypocrisy), think that Allah will not bring to light all their hidden ill-wills?', 'Do those having malady in their hearts think that Allah will never expose their grudges (against Islam)?'),
(4575, 47, 30, 4, 8, 26, 'حٰمٓ۔', 'محمد', 'وَ لَوۡ نَشَآءُ  لَاَرَیۡنٰکَہُمۡ  فَلَعَرَفۡتَہُمۡ بِسِیۡمٰہُمۡ ؕ وَ  لَتَعۡرِفَنَّہُمۡ  فِیۡ لَحۡنِ الۡقَوۡلِ ؕ وَ اللّٰہُ  یَعۡلَمُ  اَعۡمَالَکُمۡ  ﴿۳۰﴾', 'اور اگر ہم چاہتے تو وہ لوگ تمکو دکھا بھی دیتے اور تم انکو ان کے چہروں ہی سے پہچان لیتے۔ اور تم انہیں انکے انداز گفتگو ہی سے پہچان لو گے اور اللہ تمہارے اعمال سے واقف ہے۔', 'اگر ہم چاہیں تجھ کو دکھلا دیں وہ لوگ سو تو پہچان تو چکا ہے اُنکو اُنکے چہرہ سے اور آگے پہچان لے گا بات کے ڈھب سے [۴۴] اور اللہ کو معلوم ہیں تمہارے سب کام [۴۵]', 'Had We willed, We could have shown them to you, and you should have known them by their marks, but surely, you will know them by the tone of their speech! And Allah knows all your deeds.', 'Had We willed, We would have shown them to you (by identifying each one of them,) so as you would definitely recognize them by their features. However, you will recognize them by the tone of (their) speech. And Allah knows (all) your deeds.'),
(4576, 47, 31, 4, 8, 26, 'حٰمٓ۔', 'محمد', 'وَ لَنَبۡلُوَنَّکُمۡ  حَتّٰی نَعۡلَمَ الۡمُجٰہِدِیۡنَ مِنۡکُمۡ وَ الصّٰبِرِیۡنَ ۙ وَ نَبۡلُوَا۠ اَخۡبَارَکُمۡ ﴿۳۱﴾', 'اور ہم تم لوگوں کو آزمائیں گے تاکہ جو تم میں جہاد کرنے والے اور ثابت قدم رہنے والے ہیں انکو معلوم کریں۔ اور تمہارے حالات جانچ لیں۔', 'اور البتہ ہم تم کو جانچیں گے تا معلوم کر لیں جو تم میں لڑائی کرنے والے ہیں اور قائم رہنے والے [۴۶] اور تحقیق کر لیں تمہاری خبریں  [۴۷]', 'And surely, We shall try you till We test those who strive hard (for the Cause of Allah) and the patient ones, and We shall test your facts (i.e. the one who is a liar, and the one who is truthful).', 'And We will certainly test you until We know those of you who carry out Jihād (struggle in Allah’s way) and observe patience, and until We check your episodes.'),
(4577, 47, 32, 4, 8, 26, 'حٰمٓ۔', 'محمد', 'اِنَّ  الَّذِیۡنَ کَفَرُوۡا وَ صَدُّوۡا عَنۡ سَبِیۡلِ اللّٰہِ  وَ شَآقُّوا الرَّسُوۡلَ مِنۡۢ  بَعۡدِ مَا تَبَیَّنَ  لَہُمُ الۡہُدٰی ۙ لَنۡ یَّضُرُّوا اللّٰہَ شَیۡئًا ؕ وَ سَیُحۡبِطُ اَعۡمَالَہُمۡ ﴿۳۲﴾', 'جن لوگوں کو سیدھا رستہ معلوم ہو گیا اور پھر بھی انہوں نے کفر کیا اور لوگوں کو اللہ کی راہ سے روکا اور پیغمبر کی مخالفت کی وہ اللہ کا کچھ بھی بگاڑ نہیں سکیں گے۔ اور اللہ ان کا سب کیا کرایا اکارت کر دے گا۔', 'جو لوگ منکر ہوئے اور  روکا انہوں نے اللہ کی راہ سے اور مخالف ہوگئے رسول سے بعد اس کے کہ ظاہر ہو چکی ان پر سیدھی راہ نہ  بگاڑ سکیں گے اللہ کا کچھ اور وہ اکارت کر دے گا انکے سب کام [۴۸]', 'Verily, those who disbelieve, and hinder (men) from the Path of Allah (i.e. Islam), and oppose the Messenger ( SAW) (by standing against him and hurting him), after the guidance has been clearly shown to them, they will not hurt Allah in the least, but He will make their deeds fruitless,', 'Those who disbelieve and prevent (others) from Allah’s way, and oppose the Messenger, after the Guidance has appeared to them clearly, shall never bring harm to Allah in the least, and He will render their deeds vain.'),
(4578, 47, 33, 4, 8, 26, 'حٰمٓ۔', 'محمد', 'یٰۤاَیُّہَا الَّذِیۡنَ  اٰمَنُوۡۤا اَطِیۡعُوا اللّٰہَ وَ اَطِیۡعُوا الرَّسُوۡلَ وَ لَا تُبۡطِلُوۡۤا اَعۡمَالَکُمۡ ﴿۳۳﴾', 'مومنو! اللہ کا حکم مانو اور پیغمبر کی فرمانبرداری کرو اور اپنے اعمال کو ضائع نہ کرو۔', 'اے ایمان والو حکم پر چلو اللہ کے اور حکم پر چلو رسول کے اور ضائع مت کرو اپنے کئے ہوئے کام [۴۹]', 'O you who believe! Obey Allah, and obey the Messenger (Muhammad SAW) and render not vain your deeds.', 'O you who believe, obey Allah and obey the Messenger, and do not nullify your deeds.'),
(4579, 47, 34, 4, 8, 26, 'حٰمٓ۔', 'محمد', 'اِنَّ  الَّذِیۡنَ کَفَرُوۡا وَ صَدُّوۡا عَنۡ سَبِیۡلِ اللّٰہِ  ثُمَّ  مَاتُوۡا وَ ہُمۡ کُفَّارٌ فَلَنۡ یَّغۡفِرَ اللّٰہُ  لَہُمۡ ﴿۳۴﴾', 'جو لوگ کافر ہوئے اور دوسروں کو اللہ کے رستے سے روکتے رہے پھر کافر ہی مر گئے اللہ انکو ہرگز نہیں بخشے گا۔', 'جو لوگ منکر ہوئے اور روکا لوگوں کو اللہ کی راہ سے پھر مر گئے اور وہ منکر ہی رہے تو ہر گز نہ بخشے گا انکو اللہ [۵۰]', 'Verily, those who disbelieve, and hinder (men) from the Path of Allah (i.e. Islam); then die while they are disbelievers, Allah will not forgive them.', 'Those who disbelieved and prevented (others) from Allah’s way, then died as disbelievers, Allah will never forgive them.'),
(4580, 47, 35, 4, 8, 26, 'حٰمٓ۔', 'محمد', 'فَلَا تَہِنُوۡا وَ تَدۡعُوۡۤا  اِلَی السَّلۡمِ ٭ۖ وَ اَنۡتُمُ الۡاَعۡلَوۡنَ ٭ۖ وَ اللّٰہُ  مَعَکُمۡ  وَ لَنۡ یَّتِرَکُمۡ   اَعۡمَالَکُمۡ ﴿۳۵﴾', 'تو مسلمانو تم ہمت نہ ہارو اور دشمنوں کو صلح کی طرف نہ بلاؤ۔ اور تم ہی غالب رہو گے اور اللہ تمہارے ساتھ ہے وہ ہرگز تمہارے اعمال کو کم اور ضائع نہیں کرے گا۔', 'سو تم بودے نہ ہوئے جاؤ اور  (کہ) لگو پکارنے صلح  [۵۱] اور تم ہی رہو گے غالب اور اللہ تمہارے ساتھ ہے اور نقصان نہ دے گا تمکو تمہارے کاموں میں [۵۲]', 'So be not weak and ask not for peace (from the enemies of Islam), while you are having the upper hand. Allah is with you, and will never decrease the reward of your good deeds.', 'So, do not lose heart, and do not appeal for peace; you will be the uppermost, and Allah is with you; and He will never deprive you of your deeds.'),
(4581, 47, 36, 4, 8, 26, 'حٰمٓ۔', 'محمد', 'اِنَّمَا الۡحَیٰوۃُ  الدُّنۡیَا  لَعِبٌ وَّ لَہۡوٌ ؕ وَ اِنۡ  تُؤۡمِنُوۡا وَ تَتَّقُوۡا یُؤۡتِکُمۡ  اُجُوۡرَکُمۡ  وَ لَا یَسۡـَٔلۡکُمۡ  اَمۡوَالَکُمۡ ﴿۳۶﴾', 'دنیا کی زندگی تو محض کھیل اور تماشا ہے۔ اور اگر تم ایمان لاؤ گے اور پرہیزگاری کرو گے تو اللہ تمکو تمہارا اجر دے گا۔ اور تم سے تمہارے مال طلب نہیں کرے گا۔', 'یہ دنیا کا جینا تو کھیل ہے اور تماشا اور اگر تم یقین لاؤ گے اور بچ کر چلو گے دے گا تمکو تمہارا بدلا اور نہ مانگے گا تم سے مال تمہارے [۵۳]', 'The life of this world is but play and pastime, but if you believe (in the Oneness of Allah Islamic Monotheism), and fear Allah, and avoid evil, He will grant you your wages, and will not ask you your wealth.', 'The worldly life is but play and pastime. If you believe and be God-fearing, He will give you your rewards, and will not ask you your riches.'),
(4582, 47, 37, 4, 8, 26, 'حٰمٓ۔', 'محمد', 'اِنۡ  یَّسۡـَٔلۡکُمُوۡہَا  فَیُحۡفِکُمۡ  تَبۡخَلُوۡا وَ  یُخۡرِجۡ  اَضۡغَانَکُمۡ ﴿۳۷﴾', 'اگر وہ تم سے مال طلب کرے پھر تمہیں تنگ کرے تو تم بخل کرنے لگو اور وہ بخل  تمہارے کینے ظاہر کر کے رہے۔', 'اگر مانگے تم سے وہ مال پھر تم کو تنگ کرے تو بخل کرنے لگو اور ظاہر کر دے  تمہارے دل کی خفگیاں [۵۴]', 'If He were to ask you of it, and press you, you would covetously withhold, and He will bring out all your (secret) ill-wills.', 'If He were to ask you of it, and press you (to spend all your wealth), you would show miserliness, and He would expose your disgusts.'),
(4583, 47, 38, 4, 8, 26, 'حٰمٓ۔', 'محمد', 'ہٰۤاَنۡتُمۡ ہٰۤؤُلَآءِ  تُدۡعَوۡنَ لِتُنۡفِقُوۡا فِیۡ سَبِیۡلِ اللّٰہِ ۚ فَمِنۡکُمۡ  مَّنۡ یَّبۡخَلُ ۚ وَ مَنۡ یَّبۡخَلۡ  فَاِنَّمَا یَبۡخَلُ عَنۡ نَّفۡسِہٖ ؕ وَ اللّٰہُ الۡغَنِیُّ  وَ اَنۡتُمُ الۡفُقَرَآءُ ۚ وَ اِنۡ  تَتَوَلَّوۡا یَسۡتَبۡدِلۡ  قَوۡمًا غَیۡرَکُمۡ ۙ ثُمَّ  لَا یَکُوۡنُوۡۤا  اَمۡثَالَکُمۡ ﴿٪۳۸﴾', 'دیکھو تم وہ لوگ ہو کہ اللہ کی راہ میں خرچ کرنے کے لئے بلائے جاتے ہو تو تم میں ایسے شخص بھی ہیں جو بخل کرنے لگتے ہیں اور جو بخل کرتا ہے اپنے آپ سے بخل کرتا ہے اور اللہ بےنیاز ہے اور تم محتاج۔ اور اگر تم پھر جاؤ گے تو وہ تمہاری جگہ اور لوگوں کو لے آئے گا پھر وہ تمہاری طرح کے نہیں ہوں گے۔', 'سنتے ہو تم لوگ تمکو بلاتے ہیں کہ خرچ کرو اللہ کی راہ میں [۵۵] پھر تم میں کوئی ایسا ہے کہ نہیں دیتا اور جو کوئی نہ دے گا سو نہ دے گا آپکو [۵۶] اور اللہ بے نیاز ہے اور تم محتاج ہو [۵۷] اور اگر تم پھر جاؤگے تو بدل لے گا اور لوگ تمہارے سوائے پھر وہ نہ ہوں گے تمہاری طرح کے [۵۸]', 'Behold! You are those who are called to spend in the Cause of Allah, yet among you are some who are niggardly. And whoever is niggardly, it is only at the expense of his ownself. But Allah is Rich (Free of all wants), and you (mankind) are poor. And if you turn away (from Islam and the obedience of Allah), He will exchange you for some other people, and they will not be your likes.', 'Yes, you are such that you are called upon to spend in Allah’s way, but some of you withhold in miserliness- and he who withholds in miserliness withholds against himself- and Allah is the Need-Free, and you are the needy. And if you turn away, He will replace you by some other people, then they will not be like you.'),
(4584, 48, 1, 1, 9, 26, 'حٰمٓ۔', 'الفتح', 'اِنَّا فَتَحۡنَا لَکَ فَتۡحًا مُّبِیۡنًا ۙ﴿۱﴾', 'اے نبی ہم نے تمکو فتح دی فتح بھی کھلی اور واضح۔', '[۱] ہم نے فیصلہ کر دیا تیرے واسطے صریح فیصلہ', 'Verily, We have given you (O Muhammad SAW) a manifest victory.', 'Surely, We have granted you an open victory,'),
(4585, 48, 2, 1, 9, 26, 'حٰمٓ۔', 'الفتح', 'لِّیَغۡفِرَ  لَکَ اللّٰہُ  مَا تَقَدَّمَ مِنۡ ذَنۡۢبِکَ وَ مَا تَاَخَّرَ وَ یُتِمَّ نِعۡمَتَہٗ  عَلَیۡکَ وَ یَہۡدِیَکَ صِرَاطًا مُّسۡتَقِیۡمًا ۙ﴿۲﴾', 'تاکہ اللہ تمہاری اگلی اور پچھلی کوتاہیاں بخش دے اور تم پر اپنی نعمت پوری کر دے اور تمکو سیدھے رستے چلاتا رہے۔', 'تا معاف کرے تجھ کو اللہ جو آگے ہو چکے تیرے گناہ اور جو  پیچھے رہے [۲] اور پورا کر  دے تجھ پر اپنا احسان [۳] اور چلائے تجھ کو سیدھی راہ [۴]', 'That Allah may forgive you your sins of the past and the future, and complete His Favour on you, and guide you on the Straight Path;', 'so that Allah may forgive you of your previous and subsequent faults, and may complete His favour upon you, and may guide you to a straight path,'),
(4586, 48, 3, 1, 9, 26, 'حٰمٓ۔', 'الفتح', 'وَّ  یَنۡصُرَکَ اللّٰہُ  نَصۡرًا عَزِیۡزًا ﴿۳﴾', 'اور تاکہ اللہ تمہاری بھرپور مدد کرے۔', 'اور مدد کرے تیری اللہ زبردست مدد [۵]', 'And that Allah may help you with strong help.', 'and so that Allah may support you with a mighty support.'),
(4587, 48, 4, 1, 9, 26, 'حٰمٓ۔', 'الفتح', 'ہُوَ الَّذِیۡۤ  اَنۡزَلَ السَّکِیۡنَۃَ  فِیۡ  قُلُوۡبِ الۡمُؤۡمِنِیۡنَ  لِیَزۡدَادُوۡۤا  اِیۡمَانًا مَّعَ اِیۡمَانِہِمۡ ؕ وَ لِلّٰہِ  جُنُوۡدُ  السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ  کَانَ اللّٰہُ  عَلِیۡمًا حَکِیۡمًا ۙ﴿۴﴾', 'وہی تو ہے جس نے مومنوں کے دلوں پر تسکین نازل فرمائی تاکہ انکے ایمان کے ساتھ اور ایمان بڑھے اور آسمانوں اور زمین کے لشکر سب اللہ ہی کے ہیں اور اللہ جاننے والا ہے حکمت والا ہے۔', 'وہی ہے جس نے اتارا اطمینان دل میں ایمان والوں کے تاکہ اور بڑھ جائے انکو ایمان اپنے ایمان کے ساتھ [۶] اور اللہ کے ہیں سب لشکر آسمانوں کے اور زمین کے اور اللہ ہے خبردار حکمت والا [۷]', 'He it is Who sent down As-Sakinah (calmness and tranquillity) into the hearts of the believers, that they may grow more in Faith along with their (present) Faith. And to Allah belong the hosts of the heavens and the earth, and Allah is Ever All-Knower, All-Wise.', 'He (Allah) is such that He sent down tranquility into the hearts of the believers, so that they grow more in faith in addition to their (existing) faith- And to Allah belong the forces of the heavens and the earth, and Allah is All-Knowing, All-Wise-'),
(4588, 48, 5, 1, 9, 26, 'حٰمٓ۔', 'الفتح', 'لِّیُدۡخِلَ  الۡمُؤۡمِنِیۡنَ وَ الۡمُؤۡمِنٰتِ جَنّٰتٍ تَجۡرِیۡ  مِنۡ تَحۡتِہَا  الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَا وَ یُکَفِّرَ عَنۡہُمۡ سَیِّاٰتِہِمۡ ؕ وَ کَانَ ذٰلِکَ عِنۡدَ اللّٰہِ  فَوۡزًا عَظِیۡمًا ۙ﴿۵﴾', 'یہ اس لئے کہ وہ مومن مردوں اور مومن عورتوں کو بہشتوں میں جنکے نیچے نہریں بہ رہی ہیں داخل کرے وہ اس میں ہمیشہ رہیں گے اور تاکہ ان سے انکے گناہوں کو دور کر دے۔ اور یہ اللہ کے نزدیک بڑی کامیابی ہے۔', 'تاکہ پہنچا دے ایمان والے مردوں کو اور ایمان والی عورتوں کو باغوں میں نیچے بہتی ہیں انکے نہریں ہمیشہ رہیں ان میں اور اتار دی اُن پر سے اُنکی برائیاں [۸] اور یہ ہے اللہ کے  یہاں بڑی مراد ملتی [۹]', 'That He may admit the believing men and the believing women to Gardens under which rivers flow (i.e. Paradise), to abide therein forever, and to expiate from them their sins, and that is with Allah, a supreme success,', 'so that He admits believing men and believing women to the gardens beneath which rivers flow, to live therein for ever, and so that He may write off their evil deeds, which is a great achievement in Allah’s sight,'),
(4589, 48, 6, 1, 9, 26, 'حٰمٓ۔', 'الفتح', 'وَّ یُعَذِّبَ الۡمُنٰفِقِیۡنَ وَ الۡمُنٰفِقٰتِ وَ الۡمُشۡرِکِیۡنَ وَ الۡمُشۡرِکٰتِ الظَّآنِّیۡنَ بِاللّٰہِ  ظَنَّ السَّوۡءِ ؕ عَلَیۡہِمۡ  دَآئِرَۃُ السَّوۡءِ ۚ وَ غَضِبَ اللّٰہُ  عَلَیۡہِمۡ  وَ  لَعَنَہُمۡ وَ اَعَدَّ لَہُمۡ جَہَنَّمَ ؕ وَ سَآءَتۡ مَصِیۡرًا ﴿۶﴾', 'اور اس لئے کہ منافق مردوں اور منافق عورتوں اور مشرک مردوں اور مشرک عورتوں کو جو اللہ کے بارے میں برے برے خیال رکھتے ہیں عذاب دے۔ انہی پر برے حادثے واقع ہوں۔ اور اللہ ان پر غصے ہوا اور ان پر لعنت کی اور انکے لئے دوزخ تیار کی اور وہ بری جگہ ہے۔', 'اور تاکہ عذاب کرے دغاباز مردوں کو اور دغاباز عورتوں کو اور شرک والے مردوں کو اور اور شرک والی عورتوں کو [۱۰] جو اٹکلیں کرتے ہیں اللہ پر بری اٹکلیں [۱۱] انہی پر پڑے پھیر مصیبت کا [۱۲] اور غصہ ہوا اللہ اُن پر اور لعنت کی انکو اور تیار کی اُنکے واسطے دوزخ اور بری جگہ پہنچے', 'And that He may punish the Munafiqoon (hypocrites), men and women, and also the Mushrikoon men and women, who think evil thoughts about Allah, for them is a disgraceful torment, and the Anger of Allah is upon them, and He has cursed them and prepared Hell for them, and worst indeed is that destination.', 'and so that He may punish the hypocrites, men and women, and the mushriks (polytheists), men and women, who think evil thoughts about Allah. Bound for them there is a vicious circle, and Allah has become angry with them, and He has prepared Jahannam (Hell) for them, and it is an evil destination.'),
(4590, 48, 7, 1, 9, 26, 'حٰمٓ۔', 'الفتح', 'وَ لِلّٰہِ جُنُوۡدُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ کَانَ اللّٰہُ  عَزِیۡزًا  حَکِیۡمًا ﴿۷﴾', 'اور آسمانوں اور زمین کے لشکر اللہ ہی کے ہیں۔ اور اللہ غالب ہے حکمت والا ہے۔', 'اور اللہ کے ہیں سب لشکر آسمانوں کے اور زمین کے اور ہے اللہ زبردست حکمت والا [۱۳]', 'And to Allah belong the hosts of the heavens and the earth. And Allah is Ever All-Knower, All-Wise.', 'To Allah belong the forces of the heavens and the earth, and Allah is All-Mighty, All-Wise.'),
(4591, 48, 8, 1, 9, 26, 'حٰمٓ۔', 'الفتح', 'اِنَّاۤ  اَرۡسَلۡنٰکَ شَاہِدًا وَّ مُبَشِّرًا وَّ نَذِیۡرًا  ۙ﴿۸﴾', 'اے نبی ہم نے تمکو احوال بتانے والا اور خوشخبری سنانے والا اور خبردار کرنے والا بنا کر بھیجا ہے۔', 'ہم نے تجھ کو بھیجا احوال بتانے والا اور خوشی اور ڈر سنانے والا [۱۴]', 'Verily, We have sent you (O Muhammad SAW) as a witness, as a bearer of glad tidings, and as a warner.', 'Indeed, We have sent you (O prophet,) as a witness and as a bearer of good news and as a warner,'),
(4592, 48, 9, 1, 9, 26, 'حٰمٓ۔', 'الفتح', 'لِّتُؤۡمِنُوۡا بِاللّٰہِ وَ رَسُوۡلِہٖ  وَ تُعَزِّرُوۡہُ وَ تُوَقِّرُوۡہُ ؕ وَ تُسَبِّحُوۡہُ  بُکۡرَۃً  وَّ اَصِیۡلًا ﴿۹﴾', 'تاکہ مسلمانو تم لوگ اللہ پر اور اسکے پیغمبر پر ایمان رکھو اور اسکی مدد کرو اور اسکی تعظیم کرو۔ اور صبح و شام اسکی تسبیح کرتے رہو۔', 'تاکہ تم لوگ یقین لاؤ اللہ پر اور اسکے رسول پر اور اسکی مدد کرو اور اسکی عظمت رکھو [۱۵] اور اُسکی پاکی بولتے رہو صبح اور شام [۱۶]', 'In order that you (O mankind) may believe in Allah and His Messenger (SAW), and that you assist and honour him (SAW), and (that you) glorify (Allahs) praises morning and afternoon.', 'so that you (O people,) believe in Allah and His Messenger, and support him and revere him, and pronounce His (Allah’s) purity morning and evening.'),
(4593, 48, 10, 1, 9, 26, 'حٰمٓ۔', 'الفتح', 'اِنَّ  الَّذِیۡنَ یُبَایِعُوۡنَکَ  اِنَّمَا یُبَایِعُوۡنَ اللّٰہَ ؕ یَدُ اللّٰہِ  فَوۡقَ  اَیۡدِیۡہِمۡ ۚ فَمَنۡ  نَّکَثَ فَاِنَّمَا یَنۡکُثُ عَلٰی نَفۡسِہٖ ۚ وَ مَنۡ  اَوۡفٰی بِمَا عٰہَدَ عَلَیۡہُ اللّٰہَ  فَسَیُؤۡتِیۡہِ  اَجۡرًا عَظِیۡمًا ﴿٪۱۰﴾', 'اے نبی جو لوگ تم سے بیعت کرتے ہیں وہ درحقیقت اللہ سے بیعت کرتے ہیں۔ اللہ کا ہاتھ انکے ہاتھوں پر ہے۔ پھر جو شخص عہد کو توڑے تو عہد توڑنے کا نقصان اسی کو ہے۔ اور جو اس بات کو جس کا اس نے اللہ سے عہد کیا ہے پورا کرے تو وہ اسے عنقریب اجر عظیم دے گا۔', 'تحقیق جو لوگ بیعت کرتے ہیں تجھ سے وہ بیعت کرتے ہیں اللہ سے اللہ کا ہاتھ ہے اوپر اُنکے ہاتھ کے [۱۷] پھر جو کوئی قول توڑےسو توڑتا ہے اپنے نقصان کو اور جو کوئی پورا کرے اس چیز کو جس پر اقرار کیا اللہ سے تو وہ اس کو دے گا بدلہ بہت بڑا [۱۸]', 'Verily, those who give Baia (pledge) to you (O Muhammad SAW) they are giving Baia (pledge) to Allah. The Hand of Allah is over their hands. Then whosoever breaks his pledge, breaks only to his own harm, and whosoever fulfills what he has covenanted with Allah, He will bestow on him a great reward.', 'Those who pledge allegiance with you (by placing their hands in your hand)- they, in fact, pledge allegiance with Allah. Allah’s hand is over their hands. Then, whoever breaks his pledge breaks it to his own detriment, and whoever fulfils the covenant he has made with Allah, He will give him a great reward.'),
(4594, 48, 11, 2, 10, 26, 'حٰمٓ۔', 'الفتح', 'سَیَقُوۡلُ  لَکَ الۡمُخَلَّفُوۡنَ مِنَ الۡاَعۡرَابِ شَغَلَتۡنَاۤ  اَمۡوَالُنَا وَ اَہۡلُوۡنَا فَاسۡتَغۡفِرۡ لَنَا ۚ یَقُوۡلُوۡنَ  بِاَلۡسِنَتِہِمۡ مَّا لَیۡسَ فِیۡ قُلُوۡبِہِمۡ ؕ قُلۡ فَمَنۡ یَّمۡلِکُ لَکُمۡ مِّنَ اللّٰہِ  شَیۡئًا  اِنۡ  اَرَادَ بِکُمۡ  ضَرًّا  اَوۡ  اَرَادَ  بِکُمۡ نَفۡعًا ؕ بَلۡ کَانَ اللّٰہُ بِمَا تَعۡمَلُوۡنَ خَبِیۡرًا ﴿۱۱﴾', 'اے نبی جو گنوار  پیچھے رہ گئے وہ تم سے کہیں گے کہ ہمکو ہمارے مال اور اہل و عیال نے روک رکھا تھا تو آپ ہمارے لئے اللہ سے بخشش مانگیں۔ یہ لوگ اپنی زبان سے وہ بات کہتے ہیں جو انکے دل میں نہیں ہے۔ کہدو کہ اگر اللہ تم لوگوں کو نقصان پہنچانا چاہے یا تمہیں فائدہ پہنچانے کا ارادہ فرمائے تو کون ہے جو اسکے سامنے تمہارے لئے کسی بات کا کچھ اختیار رکھے کوئی نہیں بلکہ جو کچھ تم کرتے ہو اللہ اس سے واقف ہے۔', 'اب کہیں گے تجھ سے پیچھے رہ جانے والے گنوار ہم کام میں لگے رہ گئے اپنے مالوں کے اور گھر والوں کے سو ہمارا گناہ بخشوا [۱۹] وہ کہتے ہیں اپنی زبان سے جو انکے دل میں نہیں [۲۰] تو کہہ کس کا کچھ بس چلتا ہے اللہ سے تمہارے واسطے اگر وہ چاہے تمہارا نقصان یا چاہے تمہارافائدہ بلکہ اللہ ہے تمہارے سب کاموں سے خبردار [۲۱]', 'Those of the bedouins who lagged behind will say to you: \"Our possessions and our families occupied us, so ask forgiveness for us.\" They say with their tongues what is not in their hearts. Say: \"Who then has any power at all (to intervene) on your behalf with Allah, if He intends you hurt or intends you benefit? Nay, but Allah is Ever All-Aware of what you do.', 'Those of the Bedouins who remained behind will say to you, “Our possessions and our families kept us busy, (hence we could not accompany you in your journey to Hudaibiyah). So, pray to Allah for our forgiveness.” They say with their tongues what is not in their hearts.Say, “Then, who has power to help you in any thing against Allah, if He intends to do you harm, or intends to do you good? Rather, Allah is fully aware of what you do.'),
(4595, 48, 12, 2, 10, 26, 'حٰمٓ۔', 'الفتح', 'بَلۡ ظَنَنۡتُمۡ  اَنۡ  لَّنۡ یَّنۡقَلِبَ الرَّسُوۡلُ وَ الۡمُؤۡمِنُوۡنَ  اِلٰۤی  اَہۡلِیۡہِمۡ  اَبَدًا وَّ  زُیِّنَ ذٰلِکَ فِیۡ  قُلُوۡبِکُمۡ  وَ ظَنَنۡتُمۡ ظَنَّ السَّوۡءِ ۚۖ  وَ کُنۡتُمۡ  قَوۡمًۢا بُوۡرًا ﴿۱۲﴾', 'بات یہ ہے کہ تم لوگ یہ سمجھ بیٹھے تھے کہ پیغمبر اور مومن اپنے اہل و عیال میں کبھی لوٹ کر آنے ہی کے نہیں۔ اور یہی بات تمہارے دلوں کو اچھی معلوم ہوئی۔ اور اسی وجہ سے تم نے برے برے خیال کئے اور آخرکار تم ہلاکت میں پڑ گئے۔', 'کوئی نہیں تم نے تو خیال کیا تھا کہ پھر کر نہ آئے گا رسول اور مسلمان اپنے گھر کبھی اور کھب گیا تمہارے دل میں یہ خیال اور اٹکل کی تم نے بری اٹکلیں اور تم لوگ تھے تباہ ہونے والے [۲۲]', '\"Nay, but you thought that the Messenger (SAW) and the believers would never return to their families; and that was made fair-seeming in their hearts, and you did think an evil thought and you became a useless people going for destruction.\"', 'But you thought that the Messenger and the believers would never ever return to their families, and it seemed good to your hearts, and you thought an evil thought and became a people who are ruined (by their selfishness).”'),
(4596, 48, 13, 2, 10, 26, 'حٰمٓ۔', 'الفتح', 'وَ مَنۡ لَّمۡ یُؤۡمِنۡۢ  بِاللّٰہِ  وَ رَسُوۡلِہٖ  فَاِنَّاۤ اَعۡتَدۡنَا  لِلۡکٰفِرِیۡنَ سَعِیۡرًا ﴿۱۳﴾', 'اور جو شخص اللہ پر اور اسکے پیغمبر پر ایمان نہ لائے تو ہم نے ایسے کافروں کے لئے آگ تیار کر رکھی ہے۔', 'اور جو کوئی یقین نہ لائے اللہ پر اور اسکے رسول پر تو ہم نے تیار کر رکھی ہے منکروں کے واسطے دہکتی آگ', 'And whosoever does not believe in Allah and His Messenger (Muhammad SAW), then verily, We have prepared for the disbelievers a blazing Fire .', 'If one does not believe in Allah and His Messenger, then We have prepared a blazing fire for the disbelievers.'),
(4597, 48, 14, 2, 10, 26, 'حٰمٓ۔', 'الفتح', 'وَ لِلّٰہِ  مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ یَغۡفِرُ  لِمَنۡ یَّشَآءُ  وَ یُعَذِّبُ مَنۡ یَّشَآءُ ؕ وَ کَانَ  اللّٰہُ  غَفُوۡرًا  رَّحِیۡمًا ﴿۱۴﴾', 'اور آسمانوں اور زمین کی حکومت اللہ ہی کی ہے۔ وہ جسے چاہے بخشے اور جسے چاہے سزا دے۔ اور اللہ بخشنے والا ہے مہربان ہے۔', 'اور اللہ کے لئے ہے راج آسمانوں کا اور زمین کا بخشے جسکو چاہے اور عذاب میں ڈالے جسکو چاہے اور ہے اللہ بخشنے والا مہربان [۲۳]', 'And to Allah belongs the sovereignty of the heavens and the earth, He forgives whom He wills, and punishes whom He wills. And Allah is Ever Oft-Forgiving, Most Merciful.', 'To Allah belongs the kingdom of the heavens and the earth. He forgives whomsoever He wills, and punishes whomsoever He wills. And Allah is Most-Forgiving, Very-Merciful.'),
(4598, 48, 15, 2, 10, 26, 'حٰمٓ۔', 'الفتح', 'سَیَقُوۡلُ الۡمُخَلَّفُوۡنَ  اِذَا انۡطَلَقۡتُمۡ  اِلٰی مَغَانِمَ  لِتَاۡخُذُوۡہَا ذَرُوۡنَا نَتَّبِعۡکُمۡ ۚ یُرِیۡدُوۡنَ  اَنۡ یُّبَدِّلُوۡا کَلٰمَ  اللّٰہِ ؕ قُلۡ  لَّنۡ تَتَّبِعُوۡنَا کَذٰلِکُمۡ  قَالَ اللّٰہُ مِنۡ قَبۡلُ ۚ فَسَیَقُوۡلُوۡنَ بَلۡ تَحۡسُدُوۡنَنَا ؕ بَلۡ  کَانُوۡا  لَا یَفۡقَہُوۡنَ  اِلَّا  قَلِیۡلًا ﴿۱۵﴾', 'جب تم لوگ مال غنیمت لینے چلو گے تو جو لوگ پیچھے رہ گئے تھے وہ کہیں گے ہمیں بھی اجازت دیجئے کہ آپ کے ساتھ چلیں۔ یہ چاہتے ہیں کہ اللہ کے قول کو بدل دیں۔ کہدو کہ تم ہرگز ہمارے ساتھ نہیں چل سکتے۔ اسی طرح اللہ نے پہلے سے فرما دیا ہے۔ پھر کہیں گے نہیں تم تو ہم سے حسد کرتے ہو بات یہ ہے کہ یہ لوگ سمجھتے ہی نہیں مگر بہت کم۔', 'اب کہیں گے پیچھے رہ گئے ہوئے جب تم چلو گے غنیمتیں لینے کو چھوڑ و ہم بھی چلیں تمہارے ساتھ چاہتے ہیں کہ بدل دیں اللہ کا کہا تو کہہ دے تم ہمارے ساتھ ہر گز نہ چلو گے یونہی کہہ دیا اللہ نے پہلے سے [۲۴] پھر اب کہیں گے نہیں تم تو جلتے ہو ہمارے فائدہ سے [۲۵] کوئی نہیں پر وہ نہیں سمجھتے ہیں مگر تھوڑا سا [۲۶]', 'Those who lagged behind will say, when you set forth to take the spoils, \"Allow us to follow you,\" They want to change Allahs Words. Say: \"You shall not follow us; thus Allah has said beforehand.\" Then they will say: \"Nay, you envy us.\" Nay, but they understand not except a little.', 'Those who remained behind will say, when you will proceed to the spoils (of war) to receive them, “Let us follow you.”They wish to change the words of Allah. Say, “You shall not follow us. Allah had said like this beforehand.” Then they will say, “No, but you are jealous of us.” On the contrary, they do not understand (the reality) but a little.'),
(4599, 48, 16, 2, 10, 26, 'حٰمٓ۔', 'الفتح', 'قُلۡ  لِّلۡمُخَلَّفِیۡنَ مِنَ  الۡاَعۡرَابِ سَتُدۡعَوۡنَ  اِلٰی  قَوۡمٍ اُولِیۡ  بَاۡسٍ شَدِیۡدٍ تُقَاتِلُوۡنَہُمۡ  اَوۡ یُسۡلِمُوۡنَ ۚ فَاِنۡ تُطِیۡعُوۡا یُؤۡتِکُمُ اللّٰہُ  اَجۡرًا حَسَنًا ۚ وَ اِنۡ تَتَوَلَّوۡا کَمَا تَوَلَّیۡتُمۡ مِّنۡ قَبۡلُ یُعَذِّبۡکُمۡ  عَذَابًا  اَلِیۡمًا ﴿۱۶﴾', 'اے نبی جو گنوار پیچھے رہ گئے تھے ان سے کہدو کہ تم جلد ایک سخت جنگجو قوم کے ساتھ جنگ کے لئے بلائے جاؤ گے ان سے تم یا تو جنگ کرتے رہو گے یا وہ ہار مان لیں گے اگر تم حکم مانو گے تو اللہ تمکو اچھا بدلہ دے گا۔ اور اگر منہ پھیر لوگے جیسے پہلی دفعہ پھیرا تھا تو وہ تمکو بڑی تکلیف کی سزا دے گا۔', 'کہہ دے پیچھے رہ جانے والے گنواروں سے آئندہ تم کو بلائیں گے ایک قوم پر بڑے سخت لڑنے والے تم ان سے لڑو گے یا وہ مسلمان ہوں گے پھر اگر حکم مانو گے دے گا تم کو اللہ بدلہ اچھا [۲۷] اور اگر پلٹ جاؤ گے جیسے پلٹ گئے تھے پہلی بار دے گا تم کو ایک عذاب دردناک [۲۸]', 'Say (O Muhammad SAW) to the bedouins who lagged behind: \"You shall be called to fight against a people given to great warfare, then you shall fight them, or they shall surrender. Then if you obey, Allah will give you a fair reward, but if you turn away as you did turn away before, He will punish you with a painful torment.\"', 'Say to those of the Bedouins who remained behind, “You will be called against a people possessed of strong fighting power; you will have to fight them until they submit. So if you obey, Allah will give you a good reward, and if you turn away, as you had turned away earlier, He will punish you with a painful punishment.'),
(4600, 48, 17, 2, 10, 26, 'حٰمٓ۔', 'الفتح', 'لَیۡسَ عَلَی الۡاَعۡمٰی حَرَجٌ  وَّ لَا عَلَی الۡاَعۡرَجِ  حَرَجٌ وَّ لَا عَلَی الۡمَرِیۡضِ حَرَجٌ ؕ وَ مَنۡ یُّطِعِ  اللّٰہَ وَ رَسُوۡلَہٗ یُدۡخِلۡہُ  جَنّٰتٍ تَجۡرِیۡ  مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ ۚ وَ مَنۡ یَّتَوَلَّ یُعَذِّبۡہُ  عَذَابًا اَلِیۡمًا ﴿٪۱۷﴾', 'نہ تو اندھے پر سختی ہے سفر جنگ سے پیچھے رہ جانے میں اور نہ لنگڑے پر اور نہ بیمار پر سختی ہے۔ اور جو شخص اللہ اور اسکے پیغمبر کے فرمان پر چلے گا اللہ اسکو بہشتوں میں داخل کرے گا جنکے نیچے نہریں بہ رہی ہیں اور جو روگردانی کرے گا وہ اسے دردناک عذاب دے گا۔', 'اندھے پر تکلیف نہیں اور نہ لنگڑے پر تکلیف اور نہ بیمار پر تکلیف [۲۹] اور جو کوئی حکم مانے اللہ کا اور اس کے رسول کا اس کو داخل کرے گا باغوں میں جنکے نیچے بہتی ہیں نہریں اور جو کوئی پلٹ جائے اسکو عذاب دے گا دردناک [۳۰]', 'No blame or sin is there upon the blind, nor is there blame or sin upon the lame, nor is there blame or sin upon the sick (that they go not forth to war). And whosoever obeys Allah and His Messenger (Muhammad SAW), He will admit him to Gardens beneath which rivers flow (Paradise); and whosoever turns back, He will punish him with a painful torment.', 'There is no blame on the blind, nor is there any blame on the lame, nor is there any blame on the sick. Whoever obeys Allah and His Messenger, He will admit him to the gardens beneath which rivers flow. But whoever turns away, He will punish him with a painful punishment.'),
(4601, 48, 18, 3, 11, 26, 'حٰمٓ۔', 'الفتح', 'لَقَدۡ رَضِیَ اللّٰہُ  عَنِ الۡمُؤۡمِنِیۡنَ  اِذۡ یُبَایِعُوۡنَکَ تَحۡتَ الشَّجَرَۃِ  فَعَلِمَ  مَا فِیۡ قُلُوۡبِہِمۡ  فَاَنۡزَلَ السَّکِیۡنَۃَ  عَلَیۡہِمۡ وَ اَثَابَہُمۡ  فَتۡحًا  قَرِیۡبًا ﴿ۙ۱۸﴾', 'اے پیغمبر جب مومن تم سے اس درخت کے نیچے بیعت کر رہے تھے تو اللہ ان سے خوش ہوا۔ اور جو صدق و خلوص انکے دلوں میں تھا وہ اس نے معلوم کر لیا تو ان پر تسکین نازل فرمائی اور انہیں جلد فتح عنایت کی۔', 'تحقیق اللہ خوش ہوا ایمان والوں سے جب بیعت کرنے لگے تجھ سے اس درخت کے نیچے [۳۱] پھر معلوم کیا جو اُنکے جی میں تھا [۳۲] پھر اتارا اُن پر اطمینان اور انعام دیا اُنکو ایک فتح نزدیک', 'Indeed, Allah was pleased with the believers when they gave their Baia (pledge) to you (O Muhammad SAW) under the tree, He knew what was in their hearts, and He sent down As-Sakinah (calmness and tranquillity) upon them, and He rewarded them with a near victory,', 'Allah was pleased with the believers when they were pledging allegiance with you (by placing their hands in your hands) under the tree, and He knew what was in their hearts, so He sent down tranquility upon them, and rewarded them with a victory, near at hand,'),
(4602, 48, 19, 3, 11, 26, 'حٰمٓ۔', 'الفتح', 'وَّ مَغَانِمَ کَثِیۡرَۃً  یَّاۡخُذُوۡنَہَا ؕ وَ کَانَ اللّٰہُ  عَزِیۡزًا حَکِیۡمًا ﴿۱۹﴾', 'اور بہت سی غنیمتیں وہ آئندہ بھی حاصل کریں گے۔ اور اللہ غالب ہے حکمت والا ہے۔', 'اور بہت غنیمتیں جنکو وہ لیں گے [۳۳] اور ہے اللہ زبردست حکمت والا [۳۴]', 'And abundant spoils that they will capture. And Allah is Ever All-Mighty, All-Wise.', 'and many spoils that they would receive. And Allah is Mighty, Wise.'),
(4603, 48, 20, 3, 11, 26, 'حٰمٓ۔', 'الفتح', 'وَعَدَکُمُ اللّٰہُ  مَغَانِمَ کَثِیۡرَۃً تَاۡخُذُوۡنَہَا  فَعَجَّلَ  لَکُمۡ  ہٰذِہٖ  وَ  کَفَّ اَیۡدِیَ  النَّاسِ عَنۡکُمۡ ۚ وَ  لِتَکُوۡنَ  اٰیَۃً لِّلۡمُؤۡمِنِیۡنَ وَ یَہۡدِیَکُمۡ صِرَاطًا مُّسۡتَقِیۡمًا ﴿ۙ۲۰﴾', 'اللہ نے تم سے بہت سی غنیمتوں کا وعدہ فرمایا ہے کہ تم انکو حاصل کرو گے پھر اس نے یہ غنیمت تمہیں جلدی سے دلوا دی اور لوگوں کے ہاتھ تم سے روک دیئے۔ غرض یہ تھی کہ یہ مومنوں کے لئے اللہ کی قدرت کا نمونہ بن جائے اور وہ تمکو سیدھے رستے پر چلائے۔', 'وعدہ کیا ہے تم سے اللہ نے بہت غنیمتوں کا کہ تم اُن کو لو گے سو جلدی پہنچا دی تمکو یہ غنیمت [۳۵] اور روک دیا لوگوں کے ہاتھوں کو تم سے [۳۶] اور تاکہ ایک نمونہ ہو قدرت کا مسلمانوں کے واسطے [۳۷]  اور چلائے تم کو سیدھی راہ [۳۸]', 'Allah has promised you abundant spoils that you will capture, and He has hastened for you this, and He has restrained the hands of men from you, that it may be a sign for the believers, and that He may guide you to a Straight Path.', 'Allah had promised you many spoils that you would receive, so He gave these to you sooner, and stopped the hands of the people from (harming) you. And (He did this) so that it becomes a sign for believers, and so that He guides you to the right path.'),
(4604, 48, 21, 3, 11, 26, 'حٰمٓ۔', 'الفتح', 'وَّ اُخۡرٰی لَمۡ  تَقۡدِرُوۡا عَلَیۡہَا قَدۡ  اَحَاطَ اللّٰہُ بِہَا ؕ وَ کَانَ اللّٰہُ  عَلٰی کُلِّ  شَیۡءٍ  قَدِیۡرًا ﴿۲۱﴾', 'اور کچھ اور غنیمتیں دے گا جن پر تم قدرت نہیں رکھتے۔ اور وہ اللہ ہی کی قدرت میں ہیں۔ اور اللہ ہر چیز پر قادر ہے۔', 'اور ایک فتح اور جو تمہارے بس میں نہ آئی وہ اللہ کےقابو میں ہے اور اللہ ہرچیز کر سکتاہے [۳۹]', 'And other (victories and much booty there are, He promises you) which are not yet within your power, indeed Allah compasses them, And Allah is Ever Able to do all things.', 'And (there is) another (victory) that has not come within your power as yet, (but) Allah has encompassed it. And Allah is Powerful over every thing.'),
(4605, 48, 22, 3, 11, 26, 'حٰمٓ۔', 'الفتح', 'وَ لَوۡ قٰتَلَکُمُ  الَّذِیۡنَ کَفَرُوۡا لَوَلَّوُا الۡاَدۡبَارَ  ثُمَّ  لَا یَجِدُوۡنَ وَلِیًّا وَّ لَا نَصِیۡرًا ﴿۲۲﴾', 'اور اگر تم سے کافر لڑتے تو وہ پیٹھ پھیر کر بھاگ جاتے پھر وہ کسی کو نہ دوست پاتے اور نہ مددگار۔', 'اور اگرلڑتے تم سے کافر تو پھیرتے پیٹھ پھر نہ پاتے کوئی حمایتی اور نہ مددگار [۴۰]', 'And if those who disbelieve fight against you, they certainly would have turned their backs, then they would have found neither a Walee (protector) nor a helper.', 'Had the disbelievers fought you, they would have certainly turned their backs, then they would have found neither a supporter nor a helper-'),
(4606, 48, 23, 3, 11, 26, 'حٰمٓ۔', 'الفتح', 'سُنَّۃَ  اللّٰہِ  الَّتِیۡ قَدۡ خَلَتۡ مِنۡ قَبۡلُ ۚۖ وَ لَنۡ  تَجِدَ  لِسُنَّۃِ  اللّٰہِ  تَبۡدِیۡلًا ﴿۲۳﴾', 'یہی اللہ کی عادت ہے جو پہلے سے چلی آتی ہے اور تم اللہ کی عادت میں کبھی تبدیلی نہ پاؤ گے۔', 'رسم پڑی ہوئی اللہ کی جو چلی آتی ہے پہلے سے اور تو ہر گز نہ دیکھے گا اللہ کی رسم کو بدلتے [۴۱]', 'That has been the Way of Allah already with those who passed away before. And you will not find any change in the Way of Allah.', '- according to the consistent practice of Allah that went on since before, and you will never find a change in Allah’s consistent practice.'),
(4607, 48, 24, 3, 11, 26, 'حٰمٓ۔', 'الفتح', 'وَ ہُوَ الَّذِیۡ کَفَّ  اَیۡدِیَہُمۡ  عَنۡکُمۡ وَ اَیۡدِیَکُمۡ عَنۡہُمۡ بِبَطۡنِ مَکَّۃَ  مِنۡۢ بَعۡدِ اَنۡ  اَظۡفَرَکُمۡ عَلَیۡہِمۡ ؕ وَ کَانَ اللّٰہُ  بِمَا تَعۡمَلُوۡنَ بَصِیۡرًا ﴿۲۴﴾', 'اور وہی تو ہے جس نے تمکو ان کافروں پر فتحیاب کرنے کے بعد سرحد مکہ میں انکے ہاتھ تم سے اور تمہارے ہاتھ ان سے روک دیئے۔ اور جو کچھ تم کرتے ہو اللہ اسکو دیکھ رہا ہے۔', 'اور ہی ہے جس نے  روک رکھا اُنکے ہاتھوں کو تم سے اور تمہاے ہاتھوں کو ان سے بیچ شہر مکہ کے بعد اسکے کہ تمہارےہاتھ لگادیا اُنکو [۴۲] اور ہے اللہ جو کچھ تم کرتے ہو دیکھتا [۴۳]', 'And He it is Who has withheld their hands from you and your hands from them in the midst of Makkah, after He had made you victors over them. And Allah is Ever the All-Seer of what you do.', 'And He is the One who restrained their hands from you and your hands from them in the valley of Makkah after He had let you prevail over them, and Allah is watchful over what you do.'),
(4608, 48, 25, 3, 11, 26, 'حٰمٓ۔', 'الفتح', 'ہُمُ  الَّذِیۡنَ کَفَرُوۡا وَ صَدُّوۡکُمۡ عَنِ الۡمَسۡجِدِ الۡحَرَامِ  وَ الۡہَدۡیَ مَعۡکُوۡفًا اَنۡ یَّبۡلُغَ مَحِلَّہٗ ؕ وَ لَوۡ لَا رِجَالٌ مُّؤۡمِنُوۡنَ وَ نِسَآءٌ  مُّؤۡمِنٰتٌ لَّمۡ تَعۡلَمُوۡہُمۡ  اَنۡ  تَطَـُٔوۡہُمۡ فَتُصِیۡبَکُمۡ مِّنۡہُمۡ مَّعَرَّۃٌۢ  بِغَیۡرِ عِلۡمٍ ۚ لِیُدۡخِلَ اللّٰہُ فِیۡ رَحۡمَتِہٖ  مَنۡ یَّشَآءُ ۚ لَوۡ تَزَیَّلُوۡا لَعَذَّبۡنَا الَّذِیۡنَ کَفَرُوۡا مِنۡہُمۡ عَذَابًا اَلِیۡمًا ﴿۲۵﴾', 'یہ وہی لوگ ہیں جنہوں نے کفر کیا اور تمکو مسجد حرام سے روک دیا اور قربانیوں کو بھی کہ اپنی جگہ پہنچنے سے رکی رہیں۔ اور اگر ایسے مسلمان مرد اور مسلمان عورتیں نہ ہوتیں جنکو تم جانتے نہ تھے کہ اگر تم انکو پامال کر دیتے تو تمکو ان کی طرف سے بےخبری میں نقصان پہنچ جاتا۔ تو بھی تمہارے ہاتھ سے فتح رہتی مگر تاخیر اس لئے ہوئی کہ اللہ اپنی رحمت میں جسکو چاہے داخل کر لے۔ اور اگر دونوں فریق الگ الگ ہو جاتے تو جو ان میں کافر تھے انکو ہم دکھ دینے والا عذاب دیتے۔', 'یہ وہی لوگ ہیں جو منکر ہوئے اور روکا تم کو مسجد حرام سے اور نیاز کی قربانی کو بھی بند پڑی ہوئی اس بات سے کہ پہنچے اپنی جگہ تک [۴۴] اور اگر نہ ہوتے کتنے ایک مرد ایمان والے اور کتنی عورتیں ایمان والیاں جو تم کو معلوم نہیں یہ خطرہ کہ تم انکو  پیس ڈالتے پھر تم پر انکی وجہ سے خرابی پڑ جاتی بیخبری سےکہ اللہ کو داخل کرنا ہے اپنی رحمت میں جسکو  چاہے [۴۵] اگر وہ لوگ ایک طرف ہو جاتے تو آفت ڈالتے ہم منکروں پر عذاب دردناک کی [۴۶]', 'They are the ones who disbelieved (in the Oneness of Allah Islamic Monotheism), and hindered you from AlMasjidalHaram (the sacred mosque of Makkah) and the sacrificial animals, detained from reaching their place of sacrifice. Had there not been believing men and believing women whom you did not know, that you may kill them, and on whose account a sin would have been committed by you without (your) knowledge, that Allah might bring into His Mercy whom He will, if they (the believers and the disbelievers) should have been apart, We verily had punished those of them who disbelieved, with painful torment.', 'They are those who disbelieved and prevented you from the Sacred Mosque (Al-Masjid-ul-Harām ), and (prevented) the sacrificial animals that were detained from reaching their due place. And (Allah would have allowed you to fight,) had there not been believing men and believing women whom you did not know that you might have trampled them, and thus a painful situation might have arisen for you because of them unknowingly; (This situation was avoided) so that Allah may admit to His mercy whom He wills.And if they (the believing men and women) had moved (from Makkah), We would surely have punished those of them who disbelieved with a painful punishment.'),
(4609, 48, 26, 3, 11, 26, 'حٰمٓ۔', 'الفتح', 'اِذۡ جَعَلَ  الَّذِیۡنَ کَفَرُوۡا فِیۡ  قُلُوۡبِہِمُ الۡحَمِیَّۃَ حَمِیَّۃَ  الۡجَاہِلِیَّۃِ  فَاَنۡزَلَ اللّٰہُ سَکِیۡنَتَہٗ  عَلٰی رَسُوۡلِہٖ وَ عَلَی الۡمُؤۡمِنِیۡنَ وَ اَلۡزَمَہُمۡ کَلِمَۃَ  التَّقۡوٰی وَ کَانُوۡۤا  اَحَقَّ بِہَا وَ اَہۡلَہَا ؕ وَ کَانَ اللّٰہُ بِکُلِّ شَیۡءٍ عَلِیۡمًا ﴿٪۲۶﴾', 'جب کافروں نے اپنے دلوں میں ضد کی اور ضد بھی جاہلیت کی۔ تو اللہ نے اپنے پیغمبر اور مومنوں پر اپنی طرف سے تسکین نازل فرمائی اور انکو پرہیزگاری کی بات پر قائم رکھا اور وہ اسی کے مستحق اور اہل تھے۔ اور اللہ ہر چیز سے خبردار ہے۔', 'جب رکھی منکروں نے اپنے دلوں میں کد نادانی کی ضد پھر اتارا اللہ نے اپنی طرف کا اطمینان اپنے رسول پر اور مسلمانوں پر  [۴۷] اور قائم رکھا انکو ادب کی بات پر اور وہی تھے اسکے لائق اور اس کام کے اور ہے اللہ ہر چیز سے خبردار [۴۸]', 'When those who disbelieve had put in their hearts pride and haughtiness the pride and haughtiness of the time of ignorance, then Allah sent down His Sakinah (calmness and tranquillity) upon His Messenger ( SAW) and upon the believers, and made them stick to the word of piety (i.e. none has the right to be worshipped but Allah), and they were well entitled to it and worthy of it. And Allah is the All-Knower of everything.', 'When the disbelievers developed in their hearts indignation, the indignation of ignorance; then Allah sent down tranquility from Himself upon His Messenger and upon the believers, and made them stick to the word of piety, and they were very much entitled to it and competent for it. And Allah is All-Knowing about every thing.'),
(4610, 48, 27, 4, 12, 26, 'حٰمٓ۔', 'الفتح', 'لَقَدۡ صَدَقَ اللّٰہُ  رَسُوۡلَہُ  الرُّءۡیَا بِالۡحَقِّ ۚ  لَتَدۡخُلُنَّ  الۡمَسۡجِدَ الۡحَرَامَ اِنۡ شَآءَ اللّٰہُ  اٰمِنِیۡنَ ۙ مُحَلِّقِیۡنَ  رُءُوۡسَکُمۡ وَ مُقَصِّرِیۡنَ ۙ لَا  تَخَافُوۡنَ ؕ فَعَلِمَ  مَا لَمۡ تَعۡلَمُوۡا فَجَعَلَ مِنۡ  دُوۡنِ ذٰلِکَ فَتۡحًا قَرِیۡبًا ﴿۲۷﴾', 'بیشک اللہ نے اپنے پیغمبر کو سچا اور صحیح خواب دکھایا تھا۔ کہ تم ان شاء اللہ مسجد حرام میں اپنے سر منڈوا کر یا اپنے بال ترشوا کر امن و امان سے داخل ہو گے اور کسی طرح کا خوف نہ کرو گے۔ جو بات تم نہیں جانتے تھے اللہ کو معلوم تھی سو اس نے اس سے پہلے ہی جلد ایک فتح عطا فرمائی۔', 'اللہ نے سچ دکھلایا اپنے رسول کو خواب تحقیقی کہ تم داخل ہو رہو گے مسجد حرام میں اگر اللہ نے چاہا آرام سے بال مونڈتے ہوئے اپنے سروں کے اور کترتے ہوئے بے کھٹکے [۴۹] پھر جانا وہ جو تم نہیں جانتے  پھر مقرر کر دی اس سے  ورے ایک فتح نزدیک [۵۰]', 'Indeed Allah shall fulfil the true vision which He showed to His Messenger (SAW) (i.e. the Prophet SAW saw a dream that he has entered Makkah along with his companions, having their (head) hair shaved and cut short) in very truth. Certainly, you shall enter AlMasjidalHaram; if Allah wills, secure, (some) having your heads shaved, and (some) having your head hair cut short, having no fear. He knew what you knew not, and He granted besides that a near victory.', 'Indeed, Allah has made true to His Messenger the dream (shown) with truth: You will definitely enter the Sacred Mosque inshā’allāh (if Allah wills,) peacefully, with your heads shaved, and your hairs cut short, having no fear. So He knew what you did not know, and He assigned before that a victory, near at hand.'),
(4611, 48, 28, 4, 12, 26, 'حٰمٓ۔', 'الفتح', 'ہُوَ الَّذِیۡۤ  اَرۡسَلَ  رَسُوۡلَہٗ  بِالۡہُدٰۦ وَ دِیۡنِ الۡحَقِّ  لِیُظۡہِرَہٗ  عَلَی الدِّیۡنِ کُلِّہٖ ؕ وَ کَفٰی بِاللّٰہِ  شَہِیۡدًا ﴿ؕ۲۸﴾', 'وہی تو ہے جس نے اپنے پیغمبر کو ہدایت کی کتاب اور دین حق دے کر بھیجا۔ تاکہ اسکو تمام دینوں پر غالب کرے اور حق ثابت کرنے کے لئے اللہ ہی کافی ہے۔', 'وہی ہے جس نے بھیجا اپنا رسول سیدھی راہ پر اور سچے دین پر  [۵۱] تاکہ اوپر رکھے اسکو ہر دین سے [۵۲] اور کافی ہے اللہ حق ثابت کرنے والا [۵۳]', 'He it is Who has sent His Messenger (Muhammad SAW) with guidance and the religion of truth (Islam), that He may make it (Islam) superior over all religions. And All-Sufficient is Allah as a Witness.', 'He is the One who has sent His Messenger with Guidance and the religion of truth, so that He makes it prevail over all religions. And enough is Allah for being a witness (to His promise).'),
(4612, 48, 29, 4, 12, 26, 'حٰمٓ۔', 'الفتح', 'مُحَمَّدٌ  رَّسُوۡلُ اللّٰہِ ؕ وَ الَّذِیۡنَ مَعَہٗۤ اَشِدَّآءُ  عَلَی الۡکُفَّارِ  رُحَمَآءُ  بَیۡنَہُمۡ تَرٰىہُمۡ  رُکَّعًا سُجَّدًا یَّبۡتَغُوۡنَ  فَضۡلًا مِّنَ  اللّٰہِ  وَ رِضۡوَانًا ۫ سِیۡمَاہُمۡ  فِیۡ وُجُوۡہِہِمۡ  مِّنۡ  اَثَرِ السُّجُوۡدِ ؕ ذٰلِکَ مَثَلُہُمۡ  فِی التَّوۡرٰىۃِ ۚۖۛ وَ مَثَلُہُمۡ  فِی الۡاِنۡجِیۡلِ ۚ۟ۛ کَزَرۡعٍ  اَخۡرَجَ  شَطۡـَٔہٗ  فَاٰزَرَہٗ  فَاسۡتَغۡلَظَ فَاسۡتَوٰی عَلٰی سُوۡقِہٖ یُعۡجِبُ الزُّرَّاعَ  لِیَغِیۡظَ بِہِمُ  الۡکُفَّارَ ؕ وَعَدَ اللّٰہُ  الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ مِنۡہُمۡ  مَّغۡفِرَۃً  وَّ اَجۡرًا عَظِیۡمًا ﴿٪۲۹﴾', 'محمد ﷺ اللہ کے پیغمبر ہیں اور جو لوگ انکے ساتھ ہیں وہ کافروں کے مقابلے میں تو سخت ہیں اور آپس میں رحم دل اے دیکھنے والے تو انکو دیکھتا ہے کہ اللہ کے آگے جھکے ہوئے سربسجود ہیں اور اللہ کا فضل اور اسکی خوشنودی طلب کر رہے ہیں۔ کثرت سجود کے اثر سے انکی پیشانیوں پر نشان پڑے ہوئے ہیں انکے یہی اوصاف تورات میں ہیں اور یہی اوصاف انجیل میں۔ وہ گویا ایک کھیتی ہیں جس نے پہلے زمین سے اپنی سوئی نکالی پھر اسکو مضبوط کیا پھر موٹی ہوئی اور پھر اپنے تنے پر سیدھی کھڑی ہو گئ اور لگی کھیتی والوں کو خوش کرنے تاکہ کافروں کا جی جلائے۔ جو لوگ ان میں سے ایمان لائے اور نیک عمل کرتے رہے ان سے اللہ نے گناہوں کی بخشش اور اجر عظیم کا وعدہ کیا ہے۔', 'محمد رسول اللہ کا اور جو  لوگ اسکے ساتھ ہیں زورآور ہیں کافروں پر [۵۴] نرم دل ہیں آپس میں [۵۵] تو دیکھے ان کو رکوع میں اور سجدہ میں ڈھونڈتے ہیں اللہ کا فضل اور اسکی خوشی [۵۶] نشانی اُنکی اُنکے منہ پر ہے سجدہ کے اثر سے [۵۷] یہ شان ہے انکی تورات میں اور مثال انکی انجیل میں [۵۸] جیسے کھیتی نے نکالا اپنا پٹھا پھر اُسکی کمر مضبوط کی پھر موٹا ہوا پھر کھڑا ہو گیا اپنی نال پر [۵۹] خوش لگتا ہے کھیتی والوں کو [۶۰] تاکہ جلائے ان سے جی کافروں کا [۶۱] وعدہ کیا ہے اللہ نے ان سے جو یقین لائے ہیں اور کئے ہیں بھلے کام معافی کا اور بڑے ثواب کا [۶۲]', 'Muhammad (SAW) is the Messenger of Allah, and those who are with him are severe against disbelievers, and merciful among themselves. You see them bowing and falling down prostrate (in prayer), seeking Bounty from Allah and (His) Good Pleasure. The mark of them (i.e. of their Faith) is on their faces (foreheads) from the traces of (their) prostration (during prayers). This is their description in the Taurat (Torah). But their description in the Injeel (Gospel) is like a (sown) seed which sends forth its shoot, then makes it strong, it then becomes thick, and it stands straight on its stem, delighting the sowers that He may enrage the disbelievers with them. Allah has promised those among them who believe (i.e. all those who follow Islamic Monotheism, the religion of Prophet Muhammad SAW till the Day of Resurrection) and do righteous good deeds, forgiveness and a mighty reward (i.e. Paradise).', 'MuaHmmad is the messenger of Allah, and those who are with him are hard on the disbelievers, compassionate among themselves; you will see them bowing down in Rukū‘, prostrating themselves in Sajdah, seeking grace from Allah, and (His) good pleasure; their distinguishing feature is on their faces from the effect of Sajdah (prostration). This is their description in Torah; and their description in Injīl is: like a sown crop that brings forth its shoot, then makes it strong, then it grows thick and stands straight on its stem, looking good to the farmers, so that He may enrage the disbelievers through them. Allah has promised forgiveness and a huge reward to those of them who believe and do good deeds.'),
(4613, 49, 1, 1, 13, 26, 'حٰمٓ۔', 'الحجرات', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا  تُقَدِّمُوۡا بَیۡنَ یَدَیِ  اللّٰہِ  وَ رَسُوۡلِہٖ وَ اتَّقُوا اللّٰہَ ؕ اِنَّ اللّٰہَ  سَمِیۡعٌ عَلِیۡمٌ ﴿۱﴾', 'مومنو! کسی بات کے جواب میں اللہ اور اسکے رسول سے پہلے نہ بول اٹھا کرو اور اللہ سے ڈرتے رہو۔ بیشک اللہ سنتا ہے جانتا ہے۔', 'اے ایمان والو آگے نہ بڑھو اللہ سے اور اسکے رسول سے [۱] اور ڈرتے رہو اللہ سے اللہ سنتا ہے جانتا ہے [۲]', 'O you who believe! Do not put (yourselves) forward before Allah and His Messenger (SAW), and fear Allah. Verily! Allah is All-Hearing, All-Knowing.', 'O you who believe, do not proceed ahead of Allah and His Messenger, and fear Allah. Surely Allah is All-Hearing, All-Knowing.'),
(4614, 49, 2, 1, 13, 26, 'حٰمٓ۔', 'الحجرات', 'یٰۤاَیُّہَا  الَّذِیۡنَ اٰمَنُوۡا لَا تَرۡفَعُوۡۤا اَصۡوَاتَکُمۡ  فَوۡقَ صَوۡتِ النَّبِیِّ وَ لَا تَجۡہَرُوۡا  لَہٗ  بِالۡقَوۡلِ کَجَہۡرِ بَعۡضِکُمۡ لِبَعۡضٍ اَنۡ تَحۡبَطَ اَعۡمَالُکُمۡ  وَ اَنۡتُمۡ  لَا تَشۡعُرُوۡنَ ﴿۲﴾', 'اے اہل ایمان اپنی آوازیں پیغمبر ﷺ کی آواز سے اونچی نہ کرو اور جس طرح آپس میں ایک دوسرے سے زور سے بولتے ہو اسی طرح انکے روبرو زور سے نہ بولا کرو ایسا نہ ہو کہ تمہارے اعمال ضائع ہو جائیں اور تمکو خبر بھی نہ ہو۔', 'اے ایمان والو بلند نہ کرو اپنی آوازیں نبی کی آواز سے اوپر اور اس سے نہ بولو تڑخ کر جیسے تڑختے  ہو ایک دوسرے پر کہیں اکارت نہ ہو جائیں تمہارے کام اور تم کو خبر بھی نہ ہو [۳]', 'O you who believe! Raise not your voices above the voice of the Prophet (SAW), nor speak aloud to him in talk as you speak aloud to one another, lest your deeds may be rendered fruitless while you perceive not.', 'O you who believe, do not raise your voices above the voice of the Prophet, and be not loud when speaking to him, as you are loud when speaking to one another, lest your good deeds should become void while you are not aware.'),
(4615, 49, 3, 1, 13, 26, 'حٰمٓ۔', 'الحجرات', 'اِنَّ  الَّذِیۡنَ یَغُضُّوۡنَ  اَصۡوَاتَہُمۡ عِنۡدَ رَسُوۡلِ اللّٰہِ  اُولٰٓئِکَ الَّذِیۡنَ امۡتَحَنَ اللّٰہُ قُلُوۡبَہُمۡ  لِلتَّقۡوٰی ؕ لَہُمۡ  مَّغۡفِرَۃٌ  وَّ اَجۡرٌ عَظِیۡمٌ ﴿۳﴾', 'جو لوگ اللہ کے پیغمبر ﷺ سامنے دبی آواز سے بولتے ہیں اللہ نے انکے دل  کو تقویٰ کے لئے جانچ لیا ہے۔ انکے لئے بخشش اور اجر عظیم ہے۔', 'جو لوگ دبی آواز سے بولتے ہیں رسول اللہ کے پاس وہی ہیں جنکے دلوں کو جانچ لیا ہے اللہ نے ادب کے واسطے [۴] انکے لئے معافی ہے اور ثواب بڑا [۵]', 'Verily! Those who lower their voices in the presence of Allahs Messenger (SAW), they are the ones whose hearts Allah has tested for piety. For them is forgiveness and a great reward.', 'Surely, those who lower their voices before Allah’s Messenger are the ones whose hearts Allah has tested for piety; for them there is forgiveness, and a great reward.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(4616, 49, 4, 1, 13, 26, 'حٰمٓ۔', 'الحجرات', 'اِنَّ  الَّذِیۡنَ یُنَادُوۡنَکَ مِنۡ وَّرَآءِ الۡحُجُرٰتِ  اَکۡثَرُہُمۡ  لَا یَعۡقِلُوۡنَ ﴿۴﴾', 'اے نبی ﷺ جو لوگ تمکو حجروں کے باہر سے آواز دیتے ہیں ان میں اکثر بےعقل ہیں۔', 'جو لوگ پکارتے ہیں تجھ کو دیوار کے پیچھے سے وہ اکثر عقل نہیں رکھتے', 'Verily! Those who call you from behind the dwellings, most of them have no sense.', 'As for those who call you from behind the chambers, most of them have no sense.'),
(4617, 49, 5, 1, 13, 26, 'حٰمٓ۔', 'الحجرات', 'وَ لَوۡ اَنَّہُمۡ صَبَرُوۡا حَتّٰی تَخۡرُجَ  اِلَیۡہِمۡ لَکَانَ خَیۡرًا لَّہُمۡ ؕ وَ اللّٰہُ غَفُوۡرٌ رَّحِیۡمٌ ﴿۵﴾', 'اور اگر وہ صبر کئے رہتے یہاں تک کہ تم خود نکل کر انکے پاس آتے تو یہ انکے لئے بہتر ہوتا۔ اور اللہ تو بخشنے والا ہے مہربان ہے۔', 'اور اگر وہ صبر کرتے جب تک تو نکلتا اُنکی طرف تو اُنکے حق میں بہتر ہوتا اور اللہ بخشنے والا مہربان ہے [۶]', 'And if they had patience till you could come out to them, it would have been better for them. And Allah is Oft-Forgiving, Most Merciful.', 'Had they remained patient until you come out to them, it would have been much better for them. And Allah is Most-Forgiving, Very-Merciful.'),
(4618, 49, 6, 1, 13, 26, 'حٰمٓ۔', 'الحجرات', 'یٰۤاَیُّہَا  الَّذِیۡنَ اٰمَنُوۡۤا  اِنۡ جَآءَکُمۡ فَاسِقٌۢ بِنَبَاٍ فَتَبَیَّنُوۡۤا  اَنۡ  تُصِیۡبُوۡا قَوۡمًۢا بِجَہَالَۃٍ  فَتُصۡبِحُوۡا عَلٰی مَا فَعَلۡتُمۡ  نٰدِمِیۡنَ ﴿۶﴾', 'مومنو! اگر کوئی گناہگار تمہارے پاس کوئی خبر لے کر آئے تو خوب تحقیق کر لیا کرو ایسا نہ ہو کہ کسی قوم کو نادانی سے نقصان پہنچا دو۔ پھر تمکو اپنے کئے پر نادم ہونا پڑے۔', 'اے ایمان والو اگر آئے تمہارے پاس کوئی گنہگار خبر لے کر تو تحقیق کر لو کہیں جا نہ پڑو کسی قوم پر نادانی سے پھر کل کو اپنے کئے پر لگو پچتانے [۷]', 'O you who believe! If a rebellious evil person comes to you with a news, verify it, lest you harm people in ignorance, and afterwards you become regretful to what you have done.', 'O you who believe, if a sinful person brings you a report, verify its correctness, lest you should harm a people out of ignorance, and then become remorseful on what you did.'),
(4619, 49, 7, 1, 13, 26, 'حٰمٓ۔', 'الحجرات', 'وَ اعۡلَمُوۡۤا  اَنَّ  فِیۡکُمۡ رَسُوۡلَ اللّٰہِ ؕ لَوۡ یُطِیۡعُکُمۡ فِیۡ کَثِیۡرٍ مِّنَ الۡاَمۡرِ لَعَنِتُّمۡ وَ لٰکِنَّ اللّٰہَ حَبَّبَ  اِلَیۡکُمُ  الۡاِیۡمَانَ وَ زَیَّنَہٗ  فِیۡ  قُلُوۡبِکُمۡ وَ کَرَّہَ  اِلَیۡکُمُ الۡکُفۡرَ وَ الۡفُسُوۡقَ وَ الۡعِصۡیَانَ ؕ اُولٰٓئِکَ ہُمُ  الرّٰشِدُوۡنَ ۙ﴿۷﴾', 'اور جان رکھو کہ تم میں اللہ کے پیغمبر ﷺ ہیں۔ اگر بہت سی باتوں میں وہ تمہارا کہا مان لیا کریں تو تم مشکل میں پڑ جاؤ لیکن اللہ نے تمہارے لئے ایمان کو عزیز بنا دیا اور اسکو تمہارے دلوں میں سجا دیا اور کفر اور گناہ اور نافرمانی سے تمکو بیزار کر دیا۔ یہی لوگ راہ ہدایت پر ہیں۔', 'اور جان لو کہ تم میں رسول ہے اللہ کا اگر وہ تمہاری بات مان لیا کرے بہت کاموں میں تو تم پر مشکل پڑے [۸] پر اللہ نے محبت ڈال دی تمہارے دل میں ایمان کی اور کھبا دیا اسکو تمہارے دلوں میں اور نفرت ڈال دی تمہارے دل میں کفر اور گناہ اور نافرمانی کی وہ لوگ وہی ہیں نیک راہ پر', 'And know that, among you there is the Messenger of Allah (SAW). If he were to obey you (i.e. follow your opinions and desires) in much of the matter, you would surely be in trouble, but Allah has endeared the Faith to you and has beautified it in your hearts, and has made disbelief, wickedness and disobedience (to Allah and His Messenger SAW) hateful to you. These! They are the rightly guided ones,', 'And know that among you there is the Messenger of Allah. If he obeys you in many a matter, you will certainly fall into hardship. But Allah has endeared to you the Faith, and made it beautiful in your hearts, and made detestable to you the disbelief and sins and disobedience. Such people are rightly guided,'),
(4620, 49, 8, 1, 13, 26, 'حٰمٓ۔', 'الحجرات', 'فَضۡلًا مِّنَ اللّٰہِ وَ نِعۡمَۃً ؕ وَ اللّٰہُ  عَلِیۡمٌ حَکِیۡمٌ  ﴿۸﴾', 'یعنی اللہ کے فضل اور احسان سے۔ اور اللہ جاننے والا ہے حکمت والا ہے۔', 'اللہ کے فضل سے اور احسان سے [۹] اور اللہ سب کچھ جانتا ہے حکمتوں والا ہے [۱۰]', '(This is) a Grace from Allah and His Favour. And Allah is All-Knowing, All-Wise.', 'as a grace from Allah, and as a blessing. And Allah is All-Knowing, All-Wise.'),
(4621, 49, 9, 1, 13, 26, 'حٰمٓ۔', 'الحجرات', 'وَ اِنۡ طَآئِفَتٰنِ مِنَ الۡمُؤۡمِنِیۡنَ اقۡتَتَلُوۡا فَاَصۡلِحُوۡا بَیۡنَہُمَا ۚ فَاِنۡۢ  بَغَتۡ اِحۡدٰىہُمَا عَلَی الۡاُخۡرٰی فَقَاتِلُوا الَّتِیۡ تَبۡغِیۡ  حَتّٰی تَفِیۡٓءَ  اِلٰۤی  اَمۡرِ اللّٰہِ ۚ فَاِنۡ فَآءَتۡ  فَاَصۡلِحُوۡا بَیۡنَہُمَا بِالۡعَدۡلِ وَ اَقۡسِطُوۡا ؕ اِنَّ اللّٰہَ یُحِبُّ الۡمُقۡسِطِیۡنَ ﴿۹﴾', 'اور اگر مومنوں میں سے کوئی دو فریق آپس میں لڑ پڑیں تو ان میں صلح کرا دو۔ پھر اگر ایک فریق دوسرے پر زیادتی کرے تو زیادتی کرنے والے سے لڑو  یہاں تک کہ وہ اللہ کے حکم کی طرف رجوع لائے۔ پس جب وہ رجوع لائے تو دونوں فریق میں عدل کے ساتھ صلح کرا دو اور انصاف سے کام لو کہ اللہ انصاف کرنے والوں کو پسند فرماتا ہے۔', 'اور اگر دو فریق مسلمانوں کے آپس میں لڑ پڑیں تو ان میں ملاپ کرا دو  پھر  اگر چڑھا چلا جائے ایک ان میں سے دوسرے پر تو تم سب لڑو اس چڑھائی والے سے یہاں تک کہ پھر آئے اللہ کے حکم پر پھر اگر پھر آیا تو ملاپ کرا دو ان میں برابر اور انصاف کرو بیشک اللہ کو خوش آتے ہیں انصاف والے [۱۱]', 'And if two parties or groups among the believers fall to fighting, then make peace between them both, but if one of them rebels against the other, then fight you (all) against the one that which rebels till it complies with the Command of Allah; then if it complies, then make reconciliation between them justly, and be equitable. Verily! Allah loves those who are equitable.', 'If two groups of the believers fight each other, seek reconciliation between them. And if one of them commits aggression against the other, fight the one that commits aggression until it comes back to Allah’s command. So if it comes back, seek reconciliation between them with fairness, and maintain justice. Surely Allah loves those who maintain justice.'),
(4622, 49, 10, 1, 13, 26, 'حٰمٓ۔', 'الحجرات', 'اِنَّمَا الۡمُؤۡمِنُوۡنَ  اِخۡوَۃٌ  فَاَصۡلِحُوۡا بَیۡنَ اَخَوَیۡکُمۡ وَ اتَّقُوا اللّٰہَ  لَعَلَّکُمۡ تُرۡحَمُوۡنَ ﴿٪۱۰﴾', 'مومن تو آپس میں بھائی بھائی ہیں۔ تو اپنے دو بھائیوں میں صلح کرا دیا کرو اور اللہ سے ڈرتے رہو تاکہ تم پر رحمت کی جائے۔', 'مسلمان ہو ہیں سو بھائی ہیں سو ملاپ کرا دو اپنے دو بھائیوں میں اور ڈرتے رہو اللہ سے تاکہ تم پر رحم ہو [۱۲]', 'The believers are nothing else than brothers (in Islamic religion). So make reconciliation between your brothers, and fear Allah, that you may receive mercy.', 'All believers are but brothers, therefore seek reconciliation between your two brothers, and fear Allah, so that you may be blessed with mercy.'),
(4623, 49, 11, 2, 14, 26, 'حٰمٓ۔', 'الحجرات', 'یٰۤاَیُّہَا  الَّذِیۡنَ اٰمَنُوۡا لَا یَسۡخَرۡ قَوۡمٌ مِّنۡ قَوۡمٍ عَسٰۤی اَنۡ یَّکُوۡنُوۡا خَیۡرًا مِّنۡہُمۡ وَ لَا نِسَآءٌ  مِّنۡ  نِّسَآءٍ  عَسٰۤی اَنۡ یَّکُنَّ خَیۡرًا مِّنۡہُنَّ ۚ وَ لَا تَلۡمِزُوۡۤا اَنۡفُسَکُمۡ وَ لَا تَنَابَزُوۡا بِالۡاَلۡقَابِ ؕ بِئۡسَ الِاسۡمُ الۡفُسُوۡقُ بَعۡدَ الۡاِیۡمَانِ ۚ وَ مَنۡ لَّمۡ یَتُبۡ فَاُولٰٓئِکَ ہُمُ الظّٰلِمُوۡنَ ﴿۱۱﴾', 'مومنو! مرد مردوں سے تمسخر نہ کریں ممکن ہے جن کا مذاق اڑایا جا رہا ہے ان سے بہتر ہوں اور نہ عورتیں عورتوں سے تمسخر کریں ممکن ہے وہ جن کا مذاق اڑا رہی ہیں ان سے اچھی ہوں۔ اور اپنوں کو آپس میں عیب نہ لگاؤ اور نہ ایک دوسرے کا برا نام رکھو۔ ایمان لانے کے بعد برا نام رکھنا گناہ ہے۔ اور جو لوگ توبہ نہ کریں وہ ظالم ہیں۔', 'اے ایمان والون ٹھٹھا نہ کریں ایک لوگ دوسروں سے شاید وہ بہتر ہوں ان سے اور نہ عورتیں دوسری عورتوں سے شیاد وہ بہتر ہوں ان سے اور عیب نہ لگاؤ ایک دوسرےکو اور نام نہ ڈالو چڑانے کو ایک دوسرے کے [۱۳] برا نام ہے گنہگاری پیچھے ایمان کے [۱۴] اور جو کوئی توبہ نہ کرے تو وہی ہیں بے انصاف [۱۵]', 'O you who believe! Let not a group scoff at another group, it may be that the latter are better than the former; nor let (some) women scoff at other women, it may be that the latter are better than the former, nor defame one another, nor insult one another by nicknames. How bad is it, to insult ones brother after having Faith (i.e. to call your Muslim brother (a faithful believer) as: \"O sinner\", or \"O wicked\", etc.). And whosoever does not repent, then such are indeed Zalimoon (wrong-doers, etc.).', 'O you who believe, no men should ever scoff at other men. May be, the latter are better than the former. Nor should women (ever scoff) at other women. May be, the latter women are better than the former ones. And do not find fault with one another, nor call one another with bad nicknames. Bad is the name of sinfulness after embracing Faith. If anyone does not repent, then such people are the wrongdoers.'),
(4624, 49, 12, 2, 14, 26, 'حٰمٓ۔', 'الحجرات', 'یٰۤاَیُّہَا الَّذِیۡنَ  اٰمَنُوا اجۡتَنِبُوۡا کَثِیۡرًا مِّنَ الظَّنِّ ۫ اِنَّ  بَعۡضَ الظَّنِّ   اِثۡمٌ وَّ لَا تَجَسَّسُوۡا وَ لَا یَغۡتَبۡ بَّعۡضُکُمۡ بَعۡضًا ؕ اَیُحِبُّ  اَحَدُکُمۡ  اَنۡ یَّاۡکُلَ  لَحۡمَ اَخِیۡہِ  مَیۡتًا فَکَرِہۡتُمُوۡہُ ؕ  وَ اتَّقُوا اللّٰہَ ؕ اِنَّ  اللّٰہَ  تَوَّابٌ  رَّحِیۡمٌ ﴿۱۲﴾', 'اے اہل ایمان! بہت گمان کرنے سے پرہیز کرو کہ بعض گمان گناہ ہیں اور ایک دوسرے کے حال کا تجسس نہ کیا کرو اور نہ تم میں سے کوئی کسی کی غیبت کرے۔ کیا تم میں سے کوئی اس بات کو پسند کرے گا کہ اپنے مرے ہوئے بھائی کا گوشت کھائے؟ اس سے تو تم ضرور نفرت کرو گے۔ تو غیبت نہ کرو اور اللہ کا ڈر رکھو بیشک اللہ توبہ قبول کرنے والا ہے مہربان ہے۔', 'اے ایمان والو بچتے رہو بہت تہمتیں  کرنے  سے مقرر بعضی تہمت گناہ ہے اور بھید نہ ٹٹولو کسی کا اور برا نہ کہیو پیٹھ پیچھے ایک دوسرے کو [۱۶] بھلا خوش لگتا ہے تم میں کسی کو کہ کھائے گوشت اپنے بھائی کا جو مردہ ہو سو گھن آتا ہے تم کو اس سے [۱۷] اور ڈرتے رہو اللہ سے بیشک اللہ معاف کرنے والا ہے مہربان [۱۸]', 'O you who believe! Avoid much suspicions, indeed some suspicions are sins. And spy not, neither backbite one another. Would one of you like to eat the flesh of his dead brother? You would hate it (so hate backbiting) . And fear Allah. Verily, Allah is the One Who accepts repentance, Most Merciful.', 'O you who believe, abstain from many of the suspicions. Some suspicions are sins. And do not be curious (to find out faults of others), and do not backbite one another. Does one of you like that he eats the flesh of his dead brother? You would abhor it. And fear Allah. Surely Allah is Most-Relenting, Very-Merciful.'),
(4625, 49, 13, 2, 14, 26, 'حٰمٓ۔', 'الحجرات', 'یٰۤاَیُّہَا النَّاسُ  اِنَّا خَلَقۡنٰکُمۡ  مِّنۡ ذَکَرٍ وَّ اُنۡثٰی وَ جَعَلۡنٰکُمۡ شُعُوۡبًا وَّ قَبَآئِلَ لِتَعَارَفُوۡا ؕ اِنَّ  اَکۡرَمَکُمۡ  عِنۡدَ اللّٰہِ  اَتۡقٰکُمۡ ؕ اِنَّ اللّٰہَ عَلِیۡمٌ خَبِیۡرٌ ﴿۱۳﴾', 'لوگو! ہم نے تمکو ایک مرد اور ایک عورت سے پیدا کیا اور تمہاری قومیں اور قبیلے بنائے۔ تاکہ ایک دوسرے کو شناخت کرو۔ بیشک اللہ کے نزدیک تم میں زیادہ عزت والا وہ ہے جو زیادہ پرہیزگار ہے۔ بیشک اللہ سب کچھ جاننے والا ہے سب سے خبردار ہے۔', 'اے آدمیو ہم نے تم کو بنایا ایک مرد اور ایک عورت سےاور  رکھیں تمہاری ذاتیں اور قبیلے  تاکہ آپس کی پہچان ہو تحقیق عزت اللہ کے  یہاں اسکی کو بڑی جسکو  ادب بڑا [۱۹] اللہ سب کچھ جانتا ہے خبردار [۲۰]', 'O mankind! We have created you from a male and a female, and made you into nations and tribes, that you may know one another. Verily, the most honourable of you with Allah is that (believer) who has At-Taqwa (i.e. one of the Muttaqoon (pious - see V.2:2). Verily, Allah is All-Knowing, All-Aware.', 'O mankind, We have created you from a male and a female, and made you into races and tribes, so that you may identify one another. Surely the noblest of you, in Allah’s sight, is the one who is most pious of you. Surely Allah is All-Knowing, All-Aware.'),
(4626, 49, 14, 2, 14, 26, 'حٰمٓ۔', 'الحجرات', 'قَالَتِ الۡاَعۡرَابُ اٰمَنَّا ؕ قُلۡ لَّمۡ تُؤۡمِنُوۡا وَ لٰکِنۡ  قُوۡلُوۡۤا  اَسۡلَمۡنَا وَ لَمَّا یَدۡخُلِ الۡاِیۡمَانُ فِیۡ  قُلُوۡبِکُمۡ ؕ وَ اِنۡ تُطِیۡعُوا اللّٰہَ وَ رَسُوۡلَہٗ  لَا یَلِتۡکُمۡ مِّنۡ اَعۡمَالِکُمۡ شَیۡئًا ؕ اِنَّ اللّٰہَ غَفُوۡرٌ رَّحِیۡمٌ ﴿۱۴﴾', 'دیہاتی کہتے ہیں کہ ہم ایمان لے آئے۔ کہدو کہ تم ایمان نہیں لائے بلکہ یوں کہو کہ ہم اسلام لائے ہیں اور ایمان تو ابھی تمہارے دلوں میں داخل ہی نہیں ہوا۔ اور اگر تم اللہ اور اسکے رسول کی فرمانبرداری کرو گے تو اللہ تمہارے اعمال میں سے کچھ کمی نہیں کرے گا۔ بیشک اللہ بخشنے والا ہے مہربان ہے۔', 'کہتے ہیں گنوار کہ ہم ایمان لائے تو کہہ تم ایما ن نہیں لائے پر تم کہو ہم مسلمان ہوئے اور ابھی نہیں گھُسا ایمان تمہارے دلوں میں [۲۱] اور اگر ھم پر چلو گے اللہ کے اور اسکے رسول کے کاٹ نہ لے گا تمہارے کاموں میں سے کچھ اللہ بخشتا ہے مہربان ہے۔ [۲۲]', 'The bedouins say: \"We believe.\" Say: \"You believe not but you only say, We have surrendered (in Islam), for Faith has not yet entered your hearts. But if you obey Allah and His Messenger (SAW), He will not decrease anything in reward for your deeds. Verily, Allah is Oft-Forgiving, Most Merciful.\"', 'The Bedouins say, “We have come to believe.” Say, “You have not come to believe; instead, you (should) say, ‘We have surrendered’ and the belief has not entered your hearts so far. If you obey Allah and His Messenger, He will not curtail (the reward of) any of your deeds in the least. Surely Allah is Most-Forgiving, Very-Merciful.”'),
(4627, 49, 15, 2, 14, 26, 'حٰمٓ۔', 'الحجرات', 'اِنَّمَا  الۡمُؤۡمِنُوۡنَ  الَّذِیۡنَ اٰمَنُوۡا بِاللّٰہِ وَ رَسُوۡلِہٖ  ثُمَّ لَمۡ یَرۡتَابُوۡا وَ جٰہَدُوۡا بِاَمۡوَالِہِمۡ وَ اَنۡفُسِہِمۡ فِیۡ سَبِیۡلِ اللّٰہِ ؕ اُولٰٓئِکَ  ہُمُ  الصّٰدِقُوۡنَ ﴿۱۵﴾', 'مومن تو وہ ہیں جو اللہ اور اسکے رسول ﷺ پر ایمان لائے پھر شک میں نہ پڑے اور انہوں نے اللہ کی راہ میں اپنے مالوں اور اپنی جانوں سے جہاد کیا۔ یہی لوگ ایمان کے سچے ہیں۔', 'ایمان والے وہ لوگ ہیں جو  ایمان لائے اللہ پر اور اسکے رسول پر پھر شبہ نہ لائے اور لڑے اللہ کی راہ میں اپنے مال اور اپنی جان سے وہ لوگ جو ہیں وہی ہیں سچے [۲۳]', 'Only those are the believers who have believed in Allah and His Messenger, and afterward doubt not but strive with their wealth and their lives for the Cause of Allah. Those! They are the truthful.', 'Believers, in fact, are those who believe in Allah and His Messenger, then have no doubt, and struggle, with their riches and their lives, in the way of Allah. Those are the truthful.'),
(4628, 49, 16, 2, 14, 26, 'حٰمٓ۔', 'الحجرات', 'قُلۡ اَتُعَلِّمُوۡنَ اللّٰہَ بِدِیۡنِکُمۡ ؕ وَ اللّٰہُ یَعۡلَمُ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ؕ وَ اللّٰہُ  بِکُلِّ  شَیۡءٍ عَلِیۡمٌ ﴿۱۶﴾', 'ان سے کہو کہ کیا تم اللہ کو اپنی دینداری جتاتے ہو۔ اور اللہ تو آسمانوں اور زمین کی سب چیزوں سے واقف ہے۔ اور اللہ ہر چیز کو خوب جانتا ہے۔', 'تو کہہ کیا تم جتلاے ہو اللہ کو اپنی دینداری اور اللہ کو تو خبر ہے جو کچھ ہے آسمانوں میں اور زمین میں اور اللہ ہر چیز کو جانتا ہے [۲۴]', 'Say: \"Will you inform Allah about your religion? While Allah knows all that is in the heavens and all that is in the earth, and Allah is All-Aware of everything.', 'Say, “Would you apprise Allah of your religion, while Allah knows all that is in the heavens and all that is in the earth, and Allah is All-Knowing about every thing?”'),
(4629, 49, 17, 2, 14, 26, 'حٰمٓ۔', 'الحجرات', 'یَمُنُّوۡنَ عَلَیۡکَ اَنۡ  اَسۡلَمُوۡا ؕ قُلۡ  لَّا تَمُنُّوۡا عَلَیَّ  اِسۡلَامَکُمۡ ۚ بَلِ اللّٰہُ یَمُنُّ عَلَیۡکُمۡ  اَنۡ ہَدٰىکُمۡ  لِلۡاِیۡمَانِ  اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ ﴿۱۷﴾', 'یہ لوگ تم پر احسان رکھتے ہیں کہ مسلمان ہو گئے ہیں۔ کہدو کہ اپنے مسلمان ہونے کا مجھ پر احسان نہ رکھو بلکہ اللہ تم پر احسان رکھتا ہے کہ اس نے تمہیں ایمان کا رستہ دکھایا بشرطیکہ تم سچے مسلمان ہو۔', 'تجھ پر احسان رکھتے ہیں کہ مسلمان  ہوئے [۲۵] تو کہہ مجھ پر احسان نہ رکھو  اپنے اسلام لانے کا بلکہ اللہ تم پر احسان رکھتا ہے کہ اس نے تم کو راہ دی ایمان کی اگر سچ کہو [۲۶]', 'They regard as favour upon you (O Muhammad SAW) that they have embraced Islam. Say: \"Count not your Islam as a favour upon me. Nay, but Allah has conferred a favour upon you, that He has guided you to the Faith, if you indeed are true.', 'They oblige you that they have accepted Islam, (as if it was a favour shown to you). Say, “Do not oblige me for your accepting Islam. Rather, Allah makes you obliged for His having guided you to the Faith, if you are truthful.'),
(4630, 49, 18, 2, 14, 26, 'حٰمٓ۔', 'الحجرات', 'اِنَّ  اللّٰہَ  یَعۡلَمُ غَیۡبَ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ اللّٰہُ  بَصِیۡرٌۢ  بِمَا تَعۡمَلُوۡنَ ﴿٪۱۸﴾', 'بیشک اللہ آسمانوں اور زمین کی پوشیدہ باتوں کو جانتا ہے اور جو کچھ تم کرتے ہو اسے دیکھتا ہے۔', 'اللہ جانتا ہے چھپے بھید آسمانوں کے اور زمین کے اور اللہ دیکھتا ہے جو تم کرتے ہو [۲۷]', 'Verily, Allah knows the unseen of the heavens and the earth. And Allah is the All-Seer of what you do.', 'Surely Allah knows the Unseen of the heavens and the earth, and Allah keeps in sight whatever you do.”'),
(4631, 50, 1, 1, 15, 26, 'حٰمٓ۔', 'قٓ', 'قٓ ۟ۚ وَ الۡقُرۡاٰنِ  الۡمَجِیۡدِ ۚ﴿۱﴾', 'ق۔ قرآن مجید کی قسم کہ تم پیغمبر ہو۔', 'ق۔قسم ہے اس قرآن بڑی شان والے کی', 'Qaf. (These letters (Qaf, etc.) are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings). By the Glorious Quran.', 'Qāf . (I swear) by the glorious Qur’ān, (you are sent as a messenger.)'),
(4632, 50, 2, 1, 15, 26, 'حٰمٓ۔', 'قٓ', 'بَلۡ عَجِبُوۡۤا اَنۡ جَآءَہُمۡ مُّنۡذِرٌ مِّنۡہُمۡ فَقَالَ  الۡکٰفِرُوۡنَ ہٰذَا شَیۡءٌ عَجِیۡبٌ ۚ﴿۲﴾', 'اصل بات یہ ہے کہ ان لوگوں نے تعجب کیا کہ انہی میں سے ایک خبردار کرنے والا ان کے پاس آیا تو کافر کہنے لگے کہ یہ بات تو بڑی عجیب ہے۔', 'بلکہ انکو تعجب ہوا کہ آیا اُنکے پاس ڈر سنانے والا اُنہی میں کا تو کہنے لگے منکر یہ تعجب کی چیز ہے', 'Nay, they wonder that there has come to them a warner (Muhammad SAW) from among themselves. So the disbelievers say: \"This is a strange thing!', 'But they wonder that a warner has come to them from among themselves; so the disbelievers said, “This is something strange.'),
(4633, 50, 3, 1, 15, 26, 'حٰمٓ۔', 'قٓ', 'ءَاِذَا مِتۡنَا وَ کُنَّا تُرَابًا ۚ ذٰلِکَ رَجۡعٌۢ بَعِیۡدٌ ﴿۳﴾', 'بھلا جب ہم مر گئے اور مٹی ہو گئے تو پھر زندہ ہوں گے؟ یہ زندہ ہونا عقل سے بعید ہے۔', 'کیا جب ہم مر چکیں اور ہو جائیں مٹی یہ پھر آنا بہت دور ہے [۱]', '\"When we are dead and have become dust (shall we be resurrected?) That is a far return.\"', 'Is it when we die and become dust (that we will be brought to life again?) That is a return, far (from understanding).”'),
(4634, 50, 4, 1, 15, 26, 'حٰمٓ۔', 'قٓ', 'قَدۡ عَلِمۡنَا مَا تَنۡقُصُ الۡاَرۡضُ مِنۡہُمۡ ۚ وَ عِنۡدَنَا کِتٰبٌ  حَفِیۡظٌ ﴿۴﴾', 'انکے جسموں کو زمین جتنا کھا کھا کر کم کرتی جاتی ہے ہمکو معلوم ہے۔ اور ہمارے پاس تحریری یاداشت بھی ہے۔', 'ہم کو معلوم ہے جتنا گھٹاتی ہے زمین اُن میں سے [۲] اور ہمارے پاس کتاب ہے جس میں سب کچھ محفوظ ہے [۳]', 'We know that which the earth takes of them (their dead bodies), and with Us is a Book preserved (i.e. the Book of Decrees).', 'We know very well how much of them is diminished by the earth, and We have a Book that Preserves every thing.'),
(4635, 50, 5, 1, 15, 26, 'حٰمٓ۔', 'قٓ', 'بَلۡ کَذَّبُوۡا بِالۡحَقِّ لَمَّا جَآءَہُمۡ فَہُمۡ  فِیۡۤ اَمۡرٍ  مَّرِیۡجٍ ﴿۵﴾', 'بلکہ عجیب بات یہ ہے کہ جب انکے پاس دین حق آ پہنچا تو انہوں نے اسکو جھوٹ سمجھا سو یہ ایک الجھی ہوئی بات میں پڑے ہیں۔', 'کوئی نہیں  پر جھٹلاتے ہیں سچے دین کو جب اُن تک پہنچا سو  وہ  پڑ رہے ہیں الجھی ہوئی بات میں [۴]', 'Nay, but they have denied the truth (this Quran) when it has come to them, so they are in a confused state (can not differentiate between right and wrong).', 'Rather, they rejected the truth when it came to them; so they are in a confused state.'),
(4636, 50, 6, 1, 15, 26, 'حٰمٓ۔', 'قٓ', 'اَفَلَمۡ  یَنۡظُرُوۡۤا  اِلَی السَّمَآءِ  فَوۡقَہُمۡ کَیۡفَ بَنَیۡنٰہَا وَ زَیَّنّٰہَا وَ مَا لَہَا مِنۡ فُرُوۡجٍ ﴿۶﴾', 'کیا انہوں نے اپنے اوپر آسمان کی طرف نگاہ نہیں کی کہ ہم نے اسکو کیسے بنایا اور سجایا اور اس میں کوئی شگاف تک نہیں۔', 'کیا نہیں دیکھتے آسمان کو اپنے اوپر کیساہم نے اسکو بنایا اور رونق دی اور اس میں نہیں کوئی سوراخ [۵]', 'Have they not looked at the heaven above them, how We have made it and adorned it, and there are no rifts in it?', 'Did they not, then, look to the sky above them, how We have built it and beautified it, and it has no cracks?'),
(4637, 50, 7, 1, 15, 26, 'حٰمٓ۔', 'قٓ', 'وَ الۡاَرۡضَ مَدَدۡنٰہَا وَ اَلۡقَیۡنَا فِیۡہَا رَوَاسِیَ وَ اَنۡۢبَتۡنَا فِیۡہَا مِنۡ کُلِّ  زَوۡجٍۭ بَہِیۡجٍ ۙ﴿۷﴾', 'اور زمین کو دیکھو اسے ہم نے پھیلایا اور اس میں پہاڑ رکھ دیئے اور اس میں ہر طرح کی خوشنما چیزیں اگائیں۔', 'اور زمین کوپھیلایا اور ڈالے اس میں بوجھ اور اگائی اس میں ہر ہر قسم کی رونق کی چیز', 'And the earth! We have spread it out, and set thereon mountains standing firm, and have produced therein every kind of lovely growth (plants).', 'As for the earth, We have spread it out, and cast on it firm hills, and caused to grow therein every kind of delightful things,'),
(4638, 50, 8, 1, 15, 26, 'حٰمٓ۔', 'قٓ', 'تَبۡصِرَۃً  وَّ  ذِکۡرٰی لِکُلِّ عَبۡدٍ مُّنِیۡبٍ ﴿۸﴾', 'تاکہ رجوع لانے والے بندے ہدایت اور نصیحت حاصل کریں۔', 'سُجھانے کو اور یاد دلانے کو اُس بندہ کے لئے جو رجوع کرے [۶]', 'An insight and a Reminder for every slave turning to Allah (i.e. the one who believes in Allah and performs deeds of His obedience, and always begs His pardon).', 'as a source of vision and as a lesson to every servant (of Allah) who turns (to Him for guidance).'),
(4639, 50, 9, 1, 15, 26, 'حٰمٓ۔', 'قٓ', 'وَ نَزَّلۡنَا مِنَ السَّمَآءِ  مَآءً مُّبٰرَکًا فَاَنۡۢبَتۡنَا بِہٖ جَنّٰتٍ وَّ حَبَّ الۡحَصِیۡدِ ۙ﴿۹﴾', 'اور ہم نے آسمان سے برکت والا پانی اتارا اور اس سے باغ اگائے اور کھیتی کا اناج۔', 'اور اتارا ہم نے آسمان سے پانی برکت کا پھر اگائے ہم نے اُس سے باغ اور اناج جس کا کھیت کاٹا جاتا ہے [۷]', 'And We send down blessed water (rain) from the sky, then We produce therewith gardens and grain (every kind of harvests) that are reaped.', 'And We sent down blessed water from the sky, and caused to grow therewith gardens and grain of harvest,'),
(4640, 50, 10, 1, 15, 26, 'حٰمٓ۔', 'قٓ', 'وَ النَّخۡلَ بٰسِقٰتٍ  لَّہَا طَلۡعٌ  نَّضِیۡدٌ ﴿ۙ۱۰﴾', 'اور لمبے لمبے کھجور کے درخت جنکا گابھا تہ بہ تہ ہوتا ہے۔', 'اور کھجوریں لنبی اُن کا خوشہ ہے تہ بہ تہ [۸]', 'And tall date-palms, with ranged clusters;', 'and towering date palms that have spadices, put one upon another,'),
(4641, 50, 11, 1, 15, 26, 'حٰمٓ۔', 'قٓ', 'رِّزۡقًا  لِّلۡعِبَادِ ۙ وَ اَحۡیَیۡنَا بِہٖ بَلۡدَۃً  مَّیۡتًا ؕ  کَذٰلِکَ  الۡخُرُوۡجُ ﴿۱۱﴾', 'یہ سب کچھ بندوں کو روزی دینے کے لئے کیا ہے اور اس پانی سے ہم نے مردہ زمین کو زندہ کیا بس اسی طرح قیامت کے روز نکل پڑنا ہے۔', 'روزی دینے کو بندوں کے اور زندہ کیا ہم نے اُس سے ایک مردہ دیس کو  یونہی ہو گا نکل کھڑے ہونا [۹]', 'A provision for (Allahs) slaves. And We give life therewith to a dead land. Thus will be the resurrection (of the dead).', 'as a provision to the servants (of Allah). And We gave life with it to a dead land. Similar will be the exit (of the dead from their graves).'),
(4642, 50, 12, 1, 15, 26, 'حٰمٓ۔', 'قٓ', 'کَذَّبَتۡ قَبۡلَہُمۡ قَوۡمُ نُوۡحٍ وَّ اَصۡحٰبُ الرَّسِّ  وَ  ثَمُوۡدُ ﴿ۙ۱۲﴾', 'ان سے پہلے نوح  کی قوم اور کنوئیں والے اور ثمود والے لوگ جھٹلا چکے ہیں۔', 'جھٹلا چکے ہیں اُن سے پہلے نوح کی قوم اور کنوے والے اور ثمود', 'Denied before them (i.e. these pagans of Makkah who denied you, O Muhammad SAW) the people of Nooh (Noah), and the dwellers of Rass, and the Thamood,', 'It (resurrection) was rejected before them by the people of NūH, and the people of Rass and Thamūd,'),
(4643, 50, 13, 1, 15, 26, 'حٰمٓ۔', 'قٓ', 'وَ عَادٌ  وَّ  فِرۡعَوۡنُ وَ  اِخۡوَانُ  لُوۡطٍ ﴿ۙ۱۳﴾', 'اور عاد اور فرعون اور لوط کے بھائی۔', 'اور عاد اور فرعون اور لوط کے بھائی', 'And Ad, and Firaun (Pharaoh), and the brethren of Lout (Lot),', 'and ‘Ād, and Fir’aun (Pharaoh), and the brothers of LūT,'),
(4644, 50, 14, 1, 15, 26, 'حٰمٓ۔', 'قٓ', 'وَّ اَصۡحٰبُ  الۡاَیۡکَۃِ  وَ قَوۡمُ تُبَّعٍ ؕ کُلٌّ کَذَّبَ الرُّسُلَ  فَحَقَّ وَعِیۡدِ ﴿۱۴﴾', 'اور بن کے رہنے والے اور تبعّ کی قوم۔ غرض ہر ایک نے پیغمبروں کو جھٹلایا تو ہماری دھمکی بھی پوری ہو کر رہی۔', 'اور بن کے رہنے والے اور تبع کی قوم [۱۰] ان سب نے جھٹلایا رسولوں کو پر ٹھیک پڑا میرا ڈرانا [۱۱]', 'And the dwellers of the Wood, and the people of Tubba; everyone of them denied (their) Messengers, so My Threat took effect.', 'and dwellers of Aaikah, and the people of Tubba’. Each one of them rejected the messengers; so My threat came true.'),
(4645, 50, 15, 1, 15, 26, 'حٰمٓ۔', 'قٓ', 'اَفَعَیِیۡنَا بِالۡخَلۡقِ الۡاَوَّلِ ؕ بَلۡ ہُمۡ فِیۡ لَبۡسٍ مِّنۡ خَلۡقٍ جَدِیۡدٍ ﴿٪۱۵﴾', 'تو کیا ہم پہلی بار پیدا کر کے تھک گئے ہیں؟ نہیں بلکہ یہ ازسرنو پیدا کرنے کے بارے میں شک میں پڑے ہوئے ہیں۔', 'اب کیا ہم تھک گئے پہلی بار بنا کر کوئی نہیں اُنکو دھوکا ہے ایک نئے بنانے میں [۱۲]', 'Were We then tired with the first creation? Nay, They are in confused doubt about a new creation (i.e. Resurrection)?', 'Is it, then, that We were worn out by the first creation? No, but they are still in confusion about the new creation.'),
(4646, 50, 16, 2, 16, 26, 'حٰمٓ۔', 'قٓ', 'وَ لَقَدۡ خَلَقۡنَا الۡاِنۡسَانَ وَ نَعۡلَمُ مَا تُوَسۡوِسُ بِہٖ  نَفۡسُہٗ ۚۖ وَ نَحۡنُ  اَقۡرَبُ اِلَیۡہِ  مِنۡ  حَبۡلِ  الۡوَرِیۡدِ ﴿۱۶﴾', 'اور ہم ہی نے انسان کو پیدا کیا ہے اور جو خیالات اسکے دل میں گذرتے ہیں ہم انکو جانتے ہیں۔ اور ہم تو رگ جان سے بھی زیادہ اسکے قریب ہیں۔', 'اور البتہ ہم نے بنایا انسان کو اور ہم جانتےہیں جو باتیں آتی رہتی ہیں اُسکے جی میں [۱۳] اور ہم اُس سے نزدیک ہیں دھڑکتی رگ سے زیادہ [۱۴]', 'And indeed We have created man, and We know what his ownself whispers to him. And We are nearer to him than his jugular vein (by Our Knowledge).', 'Indeed We have created man, and We know whatever thoughts his inner self develops, and We are closer to him than (his) jugular vein,'),
(4647, 50, 17, 2, 16, 26, 'حٰمٓ۔', 'قٓ', 'اِذۡ یَتَلَقَّی الۡمُتَلَقِّیٰنِ عَنِ الۡیَمِیۡنِ وَ عَنِ الشِّمَالِ قَعِیۡدٌ ﴿۱۷﴾', 'جب وہ کوئی کام کرتا ہے تو دو لکھنے والے جو دائیں بائیں بیٹھے ہیں لکھ لیتے ہیں۔', 'جب لیتے لجاتے ہیں دو لینے والے داہنے بیٹھا اور بائیں بیٹھا [۱۵]', '(Remember!) that the two receivers (recording angels) receive (each human being after he or she has attained the age of puberty), one sitting on the right and one on the left (to note his or her actions) .', 'when the two receiving angels receive (every human act to record it), seated (one) on the right and (one) on the left.'),
(4648, 50, 18, 2, 16, 26, 'حٰمٓ۔', 'قٓ', 'مَا یَلۡفِظُ مِنۡ  قَوۡلٍ اِلَّا لَدَیۡہِ رَقِیۡبٌ عَتِیۡدٌ ﴿۱۸﴾', 'کوئی بات اسکی زبان پر نہیں آتی مگر ایک نگہبان اسکے پاس لکھ لینے کو تیار رہتا ہے۔', 'نہیں بولتا کچھ بات جو نہیں ہوتا اُس کے پاس ایک راہ دیکھنے والا تیار [۱۶]', 'Not a word does he (or she) utter, but there is a watcher by him ready (to record it).', 'Not a single word is uttered by one but there is a watcher near him, ready (to record).'),
(4649, 50, 19, 2, 16, 26, 'حٰمٓ۔', 'قٓ', 'وَ جَآءَتۡ سَکۡرَۃُ  الۡمَوۡتِ بِالۡحَقِّ ؕ ذٰلِکَ مَا کُنۡتَ مِنۡہُ  تَحِیۡدُ ﴿۱۹﴾', 'اور موت کی بیہوشی حقیقت کھولنے کو طاری ہو گئ۔ اے انسان یہی وہ حالت ہے جس سے تو بھاگتا تھا۔', 'اور وہ آئی بیہوشی موت کی تحقیق [۱۷] یہ وہ ہے جس سے تو ٹلتا رہتا تھا [۱۸]', 'And the stupor of death will come in truth: \"This is what you have been avoiding!\"', 'The daze of death has (to) come with truth. That is what you tried to escape.'),
(4650, 50, 20, 2, 16, 26, 'حٰمٓ۔', 'قٓ', 'وَ نُفِخَ فِی الصُّوۡرِ ؕ ذٰلِکَ یَوۡمُ الۡوَعِیۡدِ ﴿۲۰﴾', 'اور صور پھونکا جائے گا۔ یہی عذاب کی دھمکی کا دن ہے۔', 'اور پھونکا گیا صور یہ ہے دن ڈرانے کا [۱۹]', 'And the Trumpet will be blown, that will be the Day whereof warning (had been given) (i.e. the Day of Resurrection).', 'And the Horn will be blown. That will be the day of (which) threat (was given).'),
(4651, 50, 21, 2, 16, 26, 'حٰمٓ۔', 'قٓ', 'وَ جَآءَتۡ کُلُّ نَفۡسٍ مَّعَہَا سَآئِقٌ وَّ شَہِیۡدٌ ﴿۲۱﴾', 'اور ہر شخص ہمارے سامنے اس حال میں آئے گا کہ ایک فرشتہ اسکے ساتھ ہانکنے والا ہو گا اور ایک اسکے اعمال کی گواہی دینے والا۔', 'اور آیا ہر ایک جی اس کے ساتھ ہے ایک ہانکنے والا ایک احوال بتانے والا [۲۰]', 'And every person will come forth along with an (angel) to drive (him), and an (angel) to bear witness.', 'And everybody will come, along with one (angel) to drive (him to the field of reckoning) and one (angel) to testify (about his deeds).'),
(4652, 50, 22, 2, 16, 26, 'حٰمٓ۔', 'قٓ', 'لَقَدۡ کُنۡتَ فِیۡ غَفۡلَۃٍ  مِّنۡ ہٰذَا فَکَشَفۡنَا عَنۡکَ غِطَآءَکَ فَبَصَرُکَ الۡیَوۡمَ حَدِیۡدٌ ﴿۲۲﴾', 'یہ وہ دن ہے کہ اس سے تو غافل ہو رہا تھا۔ اب ہم نے تجھ پر سے پردہ اٹھا دیا تو آج تیری نگاہ تیز ہے۔', 'تو بیخبر رہا اس دن سے اب کھول دی ہے ہم نے تجھ پر سے تیری اندھیری سو تیری نگاہ آج تیز ہے [۲۱]', '(It will be said to the sinners): \"Indeed you were heedless of this, now We have removed your covering, and sharp is your sight this Day!\"', '“You were heedless of this. Now We have removed your veil from you; so your sight today is sharp.”'),
(4653, 50, 23, 2, 16, 26, 'حٰمٓ۔', 'قٓ', 'وَ قَالَ قَرِیۡنُہٗ  ہٰذَا مَا لَدَیَّ عَتِیۡدٌ ﴿ؕ۲۳﴾', 'اور اس کا ہم نشیں فرشتہ کہے گا کہ یہ اعمال نامہ میرے پاس تیار ہے۔', 'اور بولا فرشتہ اسکے ساتھ والا یہ ہے جو میرے پاس تھا حاضر [۲۲]', 'And his companion (angel) will say: \"Here is (this Record) ready with me!\"', 'And his companion (i.e. the angel who recorded his deeds) will say, “This is what I have with me, ready (to be presented as his record of deeds).”'),
(4654, 50, 24, 2, 16, 26, 'حٰمٓ۔', 'قٓ', 'اَلۡقِیَا فِیۡ جَہَنَّمَ  کُلَّ  کَفَّارٍ عَنِیۡدٍ ﴿ۙ۲۴﴾', 'حکم ہو گا کہ ہر سرکش ناشکرے کو دوزخ میں ڈالدو۔', 'ڈال دو تم دونوں دوزخ میں ہر ناشکر مخالف کو', '(And it will be said): \"Both of you throw (Order from Allah to the two angels) into Hell, every stubborn disbeliever (in the Oneness of Allah, in His Messengers, etc.).', '(Then it will be said,) “Cast, (O two angels,) into Jahannam (Hell) every obstinate disbeliever'),
(4655, 50, 25, 2, 16, 26, 'حٰمٓ۔', 'قٓ', 'مَّنَّاعٍ  لِّلۡخَیۡرِ  مُعۡتَدٍ  مُّرِیۡبِۣ ﴿ۙ۲۵﴾', 'جو مال میں بخل کرنے والا حد سے بڑھنے والا شبہے نکالنے والا تھا۔', 'نیکی سے روکنے والا حد سے بڑھنے والا شبہ ڈالنے والا [۲۳]', '\"Hinderer of good, transgressor, doubter,', 'who used to prevent (others) from good (behavior), who transgressed all bounds, who cast doubts (in true faith),'),
(4656, 50, 26, 2, 16, 26, 'حٰمٓ۔', 'قٓ', 'الَّذِیۡ جَعَلَ مَعَ  اللّٰہِ  اِلٰـہًا اٰخَرَ فَاَلۡقِیٰہُ فِی الۡعَذَابِ الشَّدِیۡدِ  ﴿۲۶﴾', 'جس نے اللہ کے ساتھ اور معبود مقرر کر رکھے تھے تو اسکو سخت عذاب میں ڈالدو۔', 'جس نے ٹھہرایا اللہ کے ساتھ اور کو پوجنا سو ڈال دو اُسکو سخت عذاب میں [۲۴]', '\"Who set up another ilah (god) with Allah, then (both of you) cast him in the severe torment.\"', 'who set up another god along with Allah. So cast him (O angels) in the painful punishment.”'),
(4657, 50, 27, 2, 16, 26, 'حٰمٓ۔', 'قٓ', 'قَالَ  قَرِیۡنُہٗ  رَبَّنَا مَاۤ  اَطۡغَیۡتُہٗ  وَ لٰکِنۡ  کَانَ  فِیۡ ضَلٰلٍۭ بَعِیۡدٍ ﴿۲۷﴾', 'اس کا ساتھی شیطان کہے گا کہ اے ہمارے پروردگار میں نے اسکو گمراہ نہیں کیا تھا بلکہ یہ آپ ہی رستے سے دور بھٹکا ہوا تھا۔', 'بولا شیطان اُس کا ساتھی اے رب ہمارےمیں نے اُسکو شرارت میں نہیں ڈالا پر یہ تھا راہ کو بھولا دور پڑا ہوا [۲۵]', 'His companion (Satan devil)) will say: \"Our Lord! I did not push him to transgress, (in disbelief, oppression, and evil deeds) but he was himself in error far astray.\"', 'His (evil) companion (i.e. the Satan) will say, “O our Lord, I did not cause him to rebel, but he was himself (involved) in straying far from the track.”'),
(4658, 50, 28, 2, 16, 26, 'حٰمٓ۔', 'قٓ', 'قَالَ  لَا تَخۡتَصِمُوۡا لَدَیَّ وَ قَدۡ قَدَّمۡتُ اِلَیۡکُمۡ  بِالۡوَعِیۡدِ ﴿۲۸﴾', 'اللہ کہے گا کہ میرے حضور میں ردّوکد نہ کرو۔ میں تمہارے پاس پہلے ہی عذاب کی وعید بھیج چکا تھا۔', 'فرمایا جھگڑا نہ کرو میرے پاس اور میں پہلےہی ڈرا چکا تھا تم کو عذاب سے [۲۶]', 'Allah will say: \"Dispute not in front of Me, I had already, in advance, sent you the threat.', 'He (Allah) will say, “Do not quarrel before Me, while I had sent to you My threat well in advance.'),
(4659, 50, 29, 2, 16, 26, 'حٰمٓ۔', 'قٓ', 'مَا یُبَدَّلُ  الۡقَوۡلُ  لَدَیَّ وَ مَاۤ  اَنَا بِظَلَّامٍ  لِّلۡعَبِیۡدِ ﴿٪۲۹﴾', 'میرے ہاں بات بدلا نہیں کرتی اور میں بندوں پر ظلم کرنے والا نہیں۔', 'بدلتی نہیں بات میرے پاس اور میں ظلم نہیں کرتا بندوں پر [۲۷]', 'The Sentence that comes from Me cannot be changed, and I am not unjust (to the least) to the slaves.\"', 'The Word is not changed with Me, and I Am not so unjust to My servants.”'),
(4660, 50, 30, 3, 17, 26, 'حٰمٓ۔', 'قٓ', 'یَوۡمَ نَقُوۡلُ لِجَہَنَّمَ ہَلِ امۡتَلَاۡتِ وَ تَقُوۡلُ ہَلۡ  مِنۡ مَّزِیۡدٍ ﴿۳۰﴾', 'اس دن ہم دوزخ سے پوچھیں گے کہ کیا تو بھر گئ؟ وہ کہے گی کہ کچھ اور بھی ہے؟', 'جس دن ہم کہیں دوزخ کو تو بھر بھی چکی اور  وہ بولے کچھ اور بھی ہے [۲۸]', 'On the Day when We will say to Hell: \"Are you filled?\" It will say: \"Are there any more (to come)?\"', '(Remind them of) the Day when We will say to Jahannam (Hell), “Are you filled up?” and it will say, “Are there some more?”'),
(4661, 50, 31, 3, 17, 26, 'حٰمٓ۔', 'قٓ', 'وَ اُزۡلِفَتِ الۡجَنَّۃُ  لِلۡمُتَّقِیۡنَ غَیۡرَ  بَعِیۡدٍ ﴿۳۱﴾', 'اور بہشت پرہیزگاروں کے قریب کر دی جائے گی کہ ان سے مطلق دور نہ ہو گی۔', 'اور نزدیک لائی جائے بہشت ڈرنے والوں کے واسطے دور نہیں [۲۹]', 'And Paradise will be brought near to the Muttaqoon (pious - see V.2:2) not far off.', 'And the Jannah (Paradise) will be brought close for the God-fearing, no longer distant.'),
(4662, 50, 32, 3, 17, 26, 'حٰمٓ۔', 'قٓ', 'ہٰذَا مَا تُوۡعَدُوۡنَ لِکُلِّ اَوَّابٍ حَفِیۡظٍ ﴿ۚ۳۲﴾', 'یہی وہ چیز ہے جس کا تم سے وعدہ کیا جاتا تھا یعنی ہر رجوع لانے والے حفاظت کرنے والے سے۔', 'یہ ہے جس کا وعدہ ہوا تھا تم سے ہر ایک رجوع رہنے والے یاد رکھنے والے کے واسطے', '(It will be said): \"This is what you were promised, - (it is) for those oft-returning (to Allah) in sincere repentance, and those who preserve their covenant with Allah (by obeying Him in all what He has ordered, and worship none but Allah Alone, i.e. follow Allahs Religion, Islamic Monotheism).', '(And it will be said,) “This is what you were promised for everyone who was oft-returning to Allah, vigilant (against sins),'),
(4663, 50, 33, 3, 17, 26, 'حٰمٓ۔', 'قٓ', 'مَنۡ خَشِیَ الرَّحۡمٰنَ بِالۡغَیۡبِ وَ جَآءَ بِقَلۡبٍ مُّنِیۡبِۣ ﴿ۙ۳۳﴾', 'جو رحمٰن سے بن دیکھے ڈرتا رہا اور رجوع کرنے والا دل لے کر آیا۔', 'جو ڈرا رحمٰن سے بن دیکھے اور لایا دل رجوع ہونے والا', '\"Who feared the Most Beneficent (Allah) in the Ghaib (unseen): (i.e. in this worldly life before seeing and meeting Him), and brought a heart turned in repentance (to Him - and absolutely free from each and every kind of polytheism),', 'the one who feared the RaHmān (The All-Merciful Allah), without seeing Him, and came up with a heart oriented towards Him.'),
(4664, 50, 34, 3, 17, 26, 'حٰمٓ۔', 'قٓ', 'ادۡخُلُوۡہَا بِسَلٰمٍ ؕ ذٰلِکَ یَوۡمُ الۡخُلُوۡدِ ﴿۳۴﴾', 'اس میں سلامتی کے ساتھ داخل ہو جاؤ۔ یہ ہمیشہ رہنے کا دن ہے۔', 'چلے جاؤ اس میں سلامت [۳۰] یہ دن ہے ہمیشہ رہنے کا [۳۱]', '\"Enter you therein in peace and security; this is a Day of eternal life!\"', 'Enter it in peace. That is the Day of Eternity.”'),
(4665, 50, 35, 3, 17, 26, 'حٰمٓ۔', 'قٓ', 'لَہُمۡ  مَّا یَشَآءُوۡنَ  فِیۡہَا وَلَدَیۡنَا مَزِیۡدٌ ﴿۳۵﴾', 'وہاں جو چاہیں گے انکے لئے حاضر ہو گا اور ہمارے ہاں اور بھی بہت کچھ ہے۔', 'اُنکے واسطے ہے وہاں جو چاہیں اور ہمارے پاس ہے کچھ دیا وہ بھی [۳۲]', 'There they will have all that they desire, and We have more (for them, i.e. a glance at the All-Mighty, All-Majestic Ìá ÌáÇáå ).', 'They will have in it whatever they wish, and with Us there are things even more than that.'),
(4666, 50, 36, 3, 17, 26, 'حٰمٓ۔', 'قٓ', 'وَ کَمۡ  اَہۡلَکۡنَا قَبۡلَہُمۡ  مِّنۡ قَرۡنٍ ہُمۡ اَشَدُّ مِنۡہُمۡ  بَطۡشًا فَنَقَّبُوۡا فِی الۡبِلَادِ ؕ ہَلۡ  مِنۡ  مَّحِیۡصٍ ﴿۳۶﴾', 'اور ہم نے ان سے پہلے کئ امتیں ہلاک کر ڈالیں وہ لوگ ان سے قوت میں کہیں بڑھ کر تھے پھر وہ شہروں میں گشت کرنے لگے۔ کیا کہیں بھاگنے کی جگہ ہے؟', 'اور کتنی تباہ کر چکے ہم ان سے پہلے جماعتیں کہ انکی قوت زبردست تھی اُن سے پھر لگے کریدنے شہروں میں کہیں ہے بھاگ جانے کو ٹھکانہ [۳۳]', 'And how many a generation We have destroyed before them, who were stronger in power than them, and (when Our Torment came) they ran for a refuge in the land! Could they find any place of refuge (for them to save themselves from destruction)?', 'And how many a generation We have destroyed before them who were stronger than these in their grip on power, and they searched out the cities. Was there any place (for them) to escape?'),
(4667, 50, 37, 3, 17, 26, 'حٰمٓ۔', 'قٓ', 'اِنَّ  فِیۡ  ذٰلِکَ لَذِکۡرٰی لِمَنۡ کَانَ لَہٗ  قَلۡبٌ اَوۡ  اَلۡقَی  السَّمۡعَ وَ  ہُوَ  شَہِیۡدٌ ﴿۳۷﴾', 'جو شخص دل آگاہ رکھتا ہے یا دل سے متوجہ ہو کر سنتا ہے اسکے لئے اس میں نصیحت ہے۔', 'اس میں سوچنے کی جگہ ہے اُسکو جسکے اندر دل ہے یا لگائے کان دل لگا کر [۳۴]', 'Verily, therein is indeed a reminder for him who has a heart or gives ear while he is heedful.', 'Indeed, there is a lesson in all this for him who has a heart and gives ear (to the truth) attentively.'),
(4668, 50, 38, 3, 17, 26, 'حٰمٓ۔', 'قٓ', 'وَ لَقَدۡ خَلَقۡنَا السَّمٰوٰتِ وَ الۡاَرۡضَ وَ مَا بَیۡنَہُمَا فِیۡ سِتَّۃِ  اَیَّامٍ ٭ۖ وَّ مَا مَسَّنَا مِنۡ  لُّغُوۡبٍ ﴿۳۸﴾', 'اور ہم نے آسمانوں اور زمین کو اور جو مخلوقات ان میں ہے سب کو چھ دن میں بنا دیا اور ہمکو ذرا بھی تھکن نہیں ہوئی۔', 'اور ہم نے بنائے آسمان اور زمین اور جو کچھ اُن کے بیچ میں ہے چھ دن میں [۳۵] اور  ہم کو نہ ہوا کچھ تکان [۳۶]', 'And indeed We created the heavens and the earth and all between them in six Days and nothing of fatigue touched Us.', 'We created the heavens and the earth and all that is between them in six days, and no weariness even touched Us.'),
(4669, 50, 39, 3, 17, 26, 'حٰمٓ۔', 'قٓ', 'فَاصۡبِرۡ عَلٰی مَا یَقُوۡلُوۡنَ وَ سَبِّحۡ بِحَمۡدِ رَبِّکَ قَبۡلَ طُلُوۡعِ الشَّمۡسِ وَ قَبۡلَ الۡغُرُوۡبِ ﴿ۚ۳۹﴾', 'تو جو کچھ یہ کفار بکتے ہیں اس پر صبر کرو اور آفتاب کے طلوع ہونے سے پہلے اور اسکے غروب ہونے سے پہلے اپنے پروردگار کی تعریف کے ساتھ تسبیح کرتے رہو۔', 'سو تو سہتا رہ جو کچھ وہ کہتے ہیں اور پاکی بولتا رہ خوبیاں اپنے رب کی [۳۷] پہلے سورج نکلنے سے اور پہلے ڈوبنے سے', 'So bear with patience (O Muhammad SAW) all that they say, and glorify the Praises of your Lord, before the rising of the sun and before (its) setting (i.e. the Fajr, Zuhr, and Asr prayers) .', 'So, (O Prophet,) endure with patience what they say, and proclaim His purity, along with your Lord’s praise, before sunrise and before sunset.'),
(4670, 50, 40, 3, 17, 26, 'حٰمٓ۔', 'قٓ', 'وَ مِنَ الَّیۡلِ فَسَبِّحۡہُ  وَ اَدۡبَارَ السُّجُوۡدِ ﴿۴۰﴾', 'اور رات کے بعض اوقات میں بھی اور نماز کے بعد بھی اسی کے نام کی تسبیح کیا کرو۔', 'اور کچھ رات میں بول اسکی پاکی [۳۸] اور پیچھے سجدہ کے [۳۹]', 'And during a part of the night (also), glorify His praises (i.e. Maghrib and Isha prayers), and (so likewise) after the prayers (As-Sunnah, Nawafil optional and additional prayers, and also glorify, praise and magnify Allah - Subhan Allah, Alhamdu lillah, Allahu-Akbar).', 'And in hours of night, proclaim His purity, and at the ends of prostration.'),
(4671, 50, 41, 3, 17, 26, 'حٰمٓ۔', 'قٓ', 'وَ اسۡتَمِعۡ یَوۡمَ یُنَادِ  الۡمُنَادِ مِنۡ مَّکَانٍ قَرِیۡبٍ ﴿ۙ۴۱﴾', 'اور سنو جس دن پکارنے والا نزدیک کی جگہ سے پکارے گا۔', 'اور کان رکھ جس دن پکارے پکارنے والا نزدیک کی جگہ سے [۴۰]', 'And listen on the Day when the caller will call from a near place,', 'And listen: The Day when the caller will call out from a near place,'),
(4672, 50, 42, 3, 17, 26, 'حٰمٓ۔', 'قٓ', 'یَّوۡمَ  یَسۡمَعُوۡنَ الصَّیۡحَۃَ  بِالۡحَقِّ ؕ ذٰلِکَ یَوۡمُ  الۡخُرُوۡجِ ﴿۴۲﴾', 'جس دن لوگ ایک زور کی آواز یقیناً سن لیں گے۔ وہی نکل پڑنے کا دن ہو گا۔', 'جس دن سُنیں گے چنگھاڑ محقق وہ  ہے دن نکل پڑنے کا [۴۱]', 'The Day when they will hear As-Saihah (shout, etc.) in truth, that will be the Day of coming out (from the graves i.e. the Day of Resurrection).', 'the Day they will hear the Cry in reality- that will be the Day of Resurrection.'),
(4673, 50, 43, 3, 17, 26, 'حٰمٓ۔', 'قٓ', 'اِنَّا نَحۡنُ نُحۡیٖ وَ نُمِیۡتُ وَ  اِلَیۡنَا الۡمَصِیۡرُ ﴿ۙ۴۳﴾', 'ہم ہی تو زندہ کرتے ہیں اور ہم ہی مارتے ہیں اور ہمارے ہی پاس لوٹ کر آنا ہے۔', 'ہم ہیں جِلاتے اور مارتے اور ہم تک ہے سب کو پہنچنا [۴۲]', 'Verily, We it is Who give life and cause death; and to Us is the final return,', 'Surely We alone give life and bring death, and to Us is the final return'),
(4674, 50, 44, 3, 17, 26, 'حٰمٓ۔', 'قٓ', 'یَوۡمَ تَشَقَّقُ الۡاَرۡضُ عَنۡہُمۡ سِرَاعًا ؕ ذٰلِکَ  حَشۡرٌ  عَلَیۡنَا یَسِیۡرٌ ﴿۴۴﴾', 'اس دن زمین ان پر سے پھٹ جائے گی اور وہ جھٹ پٹ نکل کھڑے ہوں گے۔ اس طرح سے جمع کرنا ہمیں آسان ہے۔', 'جس دن زمین پھٹ کر نکل پڑیں وہ سب دوڑتے ہوئے یہ اکٹھا کرنا ہم کو آسان ہے [۴۳]', 'On the Day when the earth shall be cleft, from off them, (they will come out) hastening forth. That will be a gathering, quite easy for Us.', 'on the Day when the earth will burst apart exposing them, while they will be hurrying up (to come out). That is an assembly, so easy for Us (to muster).'),
(4675, 50, 45, 3, 17, 26, 'حٰمٓ۔', 'قٓ', 'نَحۡنُ  اَعۡلَمُ بِمَا یَقُوۡلُوۡنَ وَ مَاۤ  اَنۡتَ عَلَیۡہِمۡ  بِجَبَّارٍ ۟  فَذَکِّرۡ بِالۡقُرۡاٰنِ مَنۡ یَّخَافُ وَعِیۡدِ ﴿٪۴۵﴾', 'یہ لوگ جو کچھ کہتے ہیں ہمیں خوب معلوم ہے اور تم ان پر زبردستی کرنے والے نہیں ہو۔ پس جو میرے عذاب کی دھمکی سے ڈرے اسکو قرآن کے ذریعے نصیحت کرتے رہو۔', 'ہم خوب جانتے ہیں جو کچھ وہ کہتے ہیں اور تو نہیں ہے اُن پر زور کرنے والا سو توسجھا قرآن سے اُس کو جو ڈرے میرے ڈرانے سے [۴۴]', 'We know of best what they say; and you (O Muhammad SAW) are not a tyrant over them (to force them to Belief). But warn by the Quran, him who fears My Threat.', 'We know well what they say, and you are not (sent) as one who compels them. So exhort, through the Qur’ān, the one who fears My warning.'),
(4676, 51, 1, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'وَالذّٰرِیٰتِ ذَرۡوًا ۙ﴿۱﴾', 'بکھیرنے والی ہواؤں کی قسم جو اڑا کر بکھیر دیتی ہیں۔', 'قسم ہے اُن ہواؤں کی جو بکھیرتی ہیں اڑا کر', 'By (the winds) that scatter dust.', 'By those (winds) that scatter dust,'),
(4677, 51, 2, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'فَالۡحٰمِلٰتِ  وِقۡرًا ۙ﴿۲﴾', 'پھر پانی کا بوجھ اٹھاتی ہیں۔', 'پھر اٹھانے والیاں بوجھ کو', 'And (the clouds) that bear heavy weight of water;', 'then those that bear load (of clouds),'),
(4678, 51, 3, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'فَالۡجٰرِیٰتِ  یُسۡرًا ۙ﴿۳﴾', 'پھر آہستہ آہستہ چلتی ہیں۔', 'پھر چلنے والیاں نرمی سے', 'And (the ships) that float with ease and gentleness;', 'then those that float with ease,'),
(4679, 51, 4, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'فَالۡمُقَسِّمٰتِ  اَمۡرًا ۙ﴿۴﴾', 'پھر اس چیز کو یعنی بارش کو تقسیم کرتی ہیں۔', 'پھر بانٹنے والیاں حکم سے [۱]', 'And those (angels) who distribute (provisions, rain, and other blessings) by (Allahs) Command;', 'then those who distribute things,'),
(4680, 51, 5, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'اِنَّمَا تُوۡعَدُوۡنَ  لَصَادِقٌ ۙ﴿۵﴾', 'کہ جو وعدہ تم سے کیا جاتا ہے وہ یقینًا سچا ہے۔', 'بیشک جو وعدہ کیا ہے تم سے سچ ہے', 'Verily, that which you are promised (i.e. Resurrection in the Hereafter and receiving the reward or punishment of good or bad deeds, etc.) is surely true.', 'whatever you are being promised is surely true,'),
(4681, 51, 6, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'وَّ  اِنَّ  الدِّیۡنَ لَوَاقِعٌ ؕ﴿۶﴾', 'اور انصاف کا دن ضرور واقع ہو گا۔', 'اور بیشک انصاف ہونا ضرور ہے [۲]', 'And verily, the Recompense is sure to happen.', 'and Recompense (of deeds) is sure to happen.'),
(4682, 51, 7, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'وَ السَّمَآءِ   ذَاتِ  الۡحُبُکِ ۙ﴿۷﴾', 'اور آسمان کی قسم جس میں کئ رستے ہیں۔', 'قسم ہے آسمان جالدار (جالیدار) کی [۳]', 'By the heaven full of paths,', 'By the sky, having paths,'),
(4683, 51, 8, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'اِنَّکُمۡ   لَفِیۡ  قَوۡلٍ  مُّخۡتَلِفٍ ۙ﴿۸﴾', 'کہ اے اہل مکہ تم ایک اختلاف والی بات میں پڑے ہوئے ہو۔', 'تم پڑ رہے ہو ایک جھگڑے کی بات میں', 'Certainly, you have different ideas (about Muhammad SAW and the Quran).', 'you are (involved) in a contradictory discussion.'),
(4684, 51, 9, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'یُّؤۡفَکُ عَنۡہُ  مَنۡ  اُفِکَ ﴿ؕ۹﴾', 'اس سے یعنی عقیدہ آخرت سے وہی پھرتا ہے جو اللہ کی طرف سے پھیرا جائے۔', 'آُس سے باز رہے وہی جو پھیرا گیا [۴]', 'Turned aside therefrom (i.e. from Muhammad SAW and the Quran) is he who is turned aside (by the Decree and Preordainment ÇáÞÖÇ æÇáÞÏÑ of Allah).', 'Turned away from this (Qur’ān) is the one who is turned away (totally from the truth.)'),
(4685, 51, 10, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'قُتِلَ  الۡخَرّٰصُوۡنَ ﴿ۙ۱۰﴾', 'اٹکل دوڑانے والے ہلاک ہوں۔', 'مارے پڑے اٹکل دوڑانے والے [۵]', 'Cursed be the liars,', 'Death upon those who make conjectures (against the true faith),'),
(4686, 51, 11, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'الَّذِیۡنَ ہُمۡ  فِیۡ  غَمۡرَۃٍ  سَاہُوۡنَ ﴿ۙ۱۱﴾', 'جو بیخبری میں بھولے ہوئے ہیں۔', 'وہ جو غفلت میں ہیں بھول رہے [۶]', 'Who are under a cover of heedlessness (think not about the gravity of the Hereafter),', '- those who are drowned in ignorance, forgetful!'),
(4687, 51, 12, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'یَسۡـَٔلُوۡنَ  اَیَّانَ  یَوۡمُ  الدِّیۡنِ ﴿ؕ۱۲﴾', 'پوچھتے ہیں کہ جزا کا دن کب ہو گا؟', 'پوچھتے ہیں کب ہے دن انصاف کا [۷]', 'They ask; \"When will be the Day of Recompense?\"', 'They ask, “When shall be the Day of Recompense?”'),
(4688, 51, 13, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'یَوۡمَ ہُمۡ عَلَی النَّارِ یُفۡتَنُوۡنَ ﴿۱۳﴾', 'وہ دن ہو گا جب انکو آگ میں عذاب دیا جائے گا۔', 'جس دن وہ آگ پر الٹے سیدھے پڑیں گے', '(It will be) a Day when they will be tried (i.e. burnt) over the Fire!', '(It will be) the Day when they will be heated on the Fire,'),
(4689, 51, 14, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'ذُوۡقُوۡا فِتۡنَتَکُمۡ ؕ ہٰذَا الَّذِیۡ  کُنۡتُمۡ بِہٖ تَسۡتَعۡجِلُوۡنَ ﴿۱۴﴾', 'اب اپنی شرارت کا مزہ چکھو۔ یہ وہی ہے جس کے لئے تم جلدی مچایا کرتے تھے۔', 'چکھو مزا اپنی شرارت کا یہ ہے جس کی تم جلدی کرتے تھے [۸]', '\"Taste you your trial (burning)! This is what you used to ask to be hastened!\"', '(and it will be said to them,) “Taste (the punishment of) your mischief. This is what you have been asking to be brought sooner.”'),
(4690, 51, 15, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'اِنَّ  الۡمُتَّقِیۡنَ فِیۡ جَنّٰتٍ وَّ عُیُوۡنٍ ﴿ۙ۱۵﴾', 'بیشک پرہیزگار بہشتوں اور چشموں میں ہوں گے۔', 'البتہ ڈرنے والے باغوں میں ہیں اور چشموں میں', 'Verily, the Muttaqoon (pious - see V.2:2) will be in the midst of Gardens and Springs (in the Paradise),', 'The God-fearing (on the other hand) will be in gardens and springs,'),
(4691, 51, 16, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'اٰخِذِیۡنَ مَاۤ  اٰتٰہُمۡ  رَبُّہُمۡ ؕ اِنَّہُمۡ کَانُوۡا قَبۡلَ  ذٰلِکَ  مُحۡسِنِیۡنَ ﴿ؕ۱۶﴾', 'اور جو جو نعمتیں ان کا پروردگار انہیں دیتا ہو گا انہیں لے رہے ہوں گے۔ بیشک وہ اس سے پہلے نیکیاں کرتے تھے۔', 'لیتے ہیں جو دیا اُنکو اُنکے رب نے [۹] وہ تھے اس سے پہلے نیکی والے [۱۰]', 'Taking joy in the things which their Lord has given them. Verily, they were before this Muhsinoon (good-doers - see V.2:112).', 'receiving what their Lord will have given to them. Indeed, prior to this, they were good in their deeds.'),
(4692, 51, 17, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'کَانُوۡا  قَلِیۡلًا مِّنَ الَّیۡلِ مَا یَہۡجَعُوۡنَ ﴿۱۷﴾', 'رات کے تھوڑے سے حصے میں سوتے تھے۔', 'وہ تھے رات کو تھوڑا سوتے', 'They used to sleep but little by night (invoking their Lord (Allah) and praying, with fear and hope).', 'They used to sleep little in the night;'),
(4693, 51, 18, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'وَ  بِالۡاَسۡحَارِ ہُمۡ  یَسۡتَغۡفِرُوۡنَ ﴿۱۸﴾', 'اور صبح کے اوقات میں بخشش مانگا کرتے تھے۔', 'اور صبح کے وقتوں میں معافی مانگنے والے [۱۱]', 'And in the hours before dawn, they were (found) asking (Allah) for forgiveness,', 'and in the hours before dawn they used to pray for forgiveness,'),
(4694, 51, 19, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'وَ فِیۡۤ  اَمۡوَالِہِمۡ حَقٌّ  لِّلسَّآئِلِ وَ الۡمَحۡرُوۡمِ ﴿۱۹﴾', 'اور انکے مال میں مانگنے والوں اور نہ مانگنے والوں دونوں کا حق ہوتا ہے۔', 'اور اُنکے مال میں حصہ تھا مانگنے والوں کا اور ہارے ہوئے کا [۱۲]', 'And in their properties there was the right of the beggar, and the Mahroom (the poor who does not ask the others) ,', 'and in their wealth, there was a right for one who asks and for one who is deprived.'),
(4695, 51, 20, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'وَ فِی الۡاَرۡضِ اٰیٰتٌ  لِّلۡمُوۡقِنِیۡنَ ﴿ۙ۲۰﴾', 'اور یقین کرنے والوں کے لئے زمین میں بہت سی نشانیاں ہیں۔', 'اور زمین میں نشانیاں ہیں یقین لانے والوں کے واسطے', 'And on the earth are signs for those who have Faith with certainty,', 'In the earth, there are signs for those who (seek truth to) believe,'),
(4696, 51, 21, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'وَ  فِیۡۤ   اَنۡفُسِکُمۡ ؕ اَفَلَا  تُبۡصِرُوۡنَ ﴿۲۱﴾', 'اور خود تمہاری جانوں میں۔ تو کیا تم دیکھتے نہیں؟', 'اور خود تمہارے اندر سو کیا تم کو سوجھتا نہیں [۱۳]', 'And also in your ownselves. Will you not then see?', 'and in your own selves! So, do you not perceive?'),
(4697, 51, 22, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'وَ فِی السَّمَآءِ  رِزۡقُکُمۡ  وَ مَا تُوۡعَدُوۡنَ ﴿۲۲﴾', 'اور تمہارا رزق اور جس چیز کا تم سے وعدہ کیا جاتا ہے آسمان میں ہے۔', 'اور آسمان میں ہے روزی تمہاری اور جو تم سے وعدہ کیا گیا [۱۴]', 'And in the heaven is your provision, and that which you are promised.', 'And in the heavens, there is your sustenance and all that you have been promised.'),
(4698, 51, 23, 1, 18, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'فَوَ رَبِّ السَّمَآءِ  وَ الۡاَرۡضِ  اِنَّہٗ  لَحَقٌّ مِّثۡلَ  مَاۤ   اَنَّکُمۡ   تَنۡطِقُوۡنَ ﴿٪۲۳﴾', 'تو آسمان اور زمین کے مالک کی قسم یہ اسی طرح قابل یقین ہے جس طرح تم بات کرتے ہو۔', 'سو قسم ہے رب آسمان اور زمین کی کہ یہ بات تحقیق ہے جیسے کہ تم بولتے ہو [۱۵]', 'Then, by the Lord of the heaven and the earth, it is the truth (i.e. what has been promised to you), just as it is the truth that you can speak.', 'So, by the Lord of the heavens and the earth, it (the Day of Recompense) is a reality, as sure as the fact that you (can) speak.'),
(4699, 51, 24, 2, 0, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'ہَلۡ  اَتٰىکَ حَدِیۡثُ ضَیۡفِ  اِبۡرٰہِیۡمَ الۡمُکۡرَمِیۡنَ ﴿ۘ۲۴﴾', 'اے نبی کیا تمہارے پاس ابراہیم  کے معزز مہمانوں کی خبر پہنچی ہے۔', 'کیا پہنچی ہے تجھ کو بات ابراہیم کے مہمانوں کی جو عزت والے تھے [۱۶]', 'Has the story reached you, of the honoured guests (three angels; Jibrael (Gabriel) along with another two) of Ibraheem (Abraham)?', 'Has there come to you the story of the honoured guests of Ibrāhīm?'),
(4700, 51, 25, 2, 0, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'اِذۡ  دَخَلُوۡا عَلَیۡہِ  فَقَالُوۡا سَلٰمًا ؕ قَالَ سَلٰمٌ ۚ قَوۡمٌ  مُّنۡکَرُوۡنَ ﴿ۚ۲۵﴾', 'جب وہ انکے پاس آئے تو سلام کہا۔ انہوں نے بھی جواب میں سلام کہا دیکھا تو ایسے لوگ کہ نہ جان نہ پہچان۔', 'جب اندر پہنچے اُسکے پاس تو بولے سلام وہ بولا سلام ہے یہ لوگ ہیں اوپرے [۱۷]', 'When they came in to him, and said, \"Salam, (peace be upon you)!\" He answered; \"Salam, (peace be upon you ),\" and said: \"You are a people unknown to me,\"', 'When they (the angels in human form) entered unto him and said, “We greet you with Salām .” He said, “Salām on you.” (And he said to himself,) “(They are) unknown people.”'),
(4701, 51, 26, 2, 0, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'فَرَاغَ   اِلٰۤی  اَہۡلِہٖ   فَجَآءَ  بِعِجۡلٍ  سَمِیۡنٍ ﴿ۙ۲۶﴾', 'پھر وہ اپنے گھر جا کر ایک بھنا ہوا موٹا بچھڑا لائے۔', 'پھر دوڑا اپنے گھر کو تو لے آیا ایک بچھڑا گھی میں تلا ہوا', 'Then he turned to his household, so brought out a roasted calf (as the property of Ibraheem (Abraham) was mainly cows).', 'Then he slipped off to his home and fetched a fattened calf.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(4702, 51, 27, 2, 0, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'فَقَرَّبَہٗۤ  اِلَیۡہِمۡ  قَالَ  اَلَا  تَاۡکُلُوۡنَ ﴿۫۲۷﴾', 'اور کھانے کے لئے انکے آگے رکھ دیا۔ کہنے لگے کہ آپ تناول کیوں نہیں فرماتے؟', 'پھر اُنکے سامنے رکھا کہا کیوں تم کھاتے نہیں [۱۸]', 'And placed it before them, (saying): \"Will you not eat?\"', 'So he presented it before them (to eat, but being angels, they refrained.) He said, “Would you not eat?”'),
(4703, 51, 28, 2, 0, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'فَاَوۡجَسَ مِنۡہُمۡ خِیۡفَۃً ؕ قَالُوۡا لَا تَخَفۡ ؕ وَ بَشَّرُوۡہُ  بِغُلٰمٍ  عَلِیۡمٍ ﴿۲۸﴾', 'اور ان سے خوف محسوس کیا۔ انہوں نے کہا کہ خوف نہ کیجئے اور انکو ایک دانشمند لڑکے کی بشارت سنائی۔', 'پھر جی میں گھبرایا اُن کے ڈر سے بولے تو مت ڈر اور خوشخبری دی اُسکو ایک لڑکے ہوشیار کی [۱۹]', 'Then he conceived a fear of them (when they ate not). They said: \"Fear not.\" And they gave him glad tidings of an intelligent son, having knowledge (about Allah and His religion of True Monotheism).', 'So he felt some fear in his heart. They said, “Be not scared.” And they gave him the good news of (the birth of) a knowledgeable boy.'),
(4704, 51, 29, 2, 0, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'فَاَقۡبَلَتِ امۡرَاَتُہٗ  فِیۡ صَرَّۃٍ  فَصَکَّتۡ وَجۡہَہَا وَ قَالَتۡ عَجُوۡزٌ  عَقِیۡمٌ ﴿۲۹﴾', 'تو ابراہیم  کی بیوی چلاتی آئیں اور اپنا منہ پیٹ کر کہنے لگیں کہ ایک تو میں بڑھیا اوپر سے بانجھ۔', 'پھر سامنے سے آئی اسکی عورت بولتی ہوئی پھر پیٹا اپنا ماتھا اور کہنے لگی کہیں بڑھیا بانجھ [۲۰]', 'Then his wife came forward with a loud voice, she smote her face, and said: \"A barren old woman!\"', 'So his wife came forward with a clamor, and slapped her own face and said, “(How can I have a child when I am) a barren old woman?”'),
(4705, 51, 30, 2, 0, 26, 'حٰمٓ۔', 'الذّٰریٰت', 'قَالُوۡا کَذٰلِکِ ۙ قَالَ رَبُّکِ ؕ اِنَّہٗ  ہُوَ الۡحَکِیۡمُ  الۡعَلِیۡمُ ﴿۳۰﴾', 'انہوں نے کہا تمہارے پروردگار نے یوں ہی فرمایا ہے وہ بیشک صاحب حکمت ہے خبردار ہے۔', 'وہ بولے یوں ہی کہا تیرے رب نے وہ جو ہے وہی ہے حکمت والا خبردار [۲۱]', 'They said: \"Even so says your Lord. Verily, He is the All-Wise, the All-Knower.\"', 'They said, “This is how your Lord has said. Surely, He is All-Wise, All-Knowing.”'),
(4706, 51, 31, 2, 1, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'قَالَ فَمَا خَطۡبُکُمۡ اَیُّہَا الۡمُرۡسَلُوۡنَ ﴿۳۱﴾', 'ابراہیم  نے کہا کہ فرشتو! اب تمہارا اصل کام کیا ہے؟', 'بولا پھر کیا مطلب ہے تمہارا اے بھیجے ہوؤ [۲۲]', '(Ibrahim (Abraham)) said: \"Then for what purpose you have come, O Messengers?\"', 'He (Ibrāhīm) said (to the angels), “Then, what is your mission O messengers?”'),
(4707, 51, 32, 2, 1, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'قَالُوۡۤا  اِنَّاۤ  اُرۡسِلۡنَاۤ  اِلٰی قَوۡمٍ مُّجۡرِمِیۡنَ ﴿ۙ۳۲﴾', 'انہوں نے کہا کہ ہم گنہگاروں کی طرف بھیجے گئے ہیں۔', 'وہ بولے ہم کو بھیجا ہے ایک گنہگار قوم پر', 'They said: \"We have been sent to a people who are Mujrimoon (polytheists, sinners, criminals, disbelievers in Allah);', 'They said, “We are sent to a guilty people, (i.e. the people of Sodom)'),
(4708, 51, 33, 2, 1, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'لِنُرۡسِلَ عَلَیۡہِمۡ  حِجَارَۃً  مِّنۡ طِیۡنٍ ﴿ۙ۳۳﴾', 'تاکہ ان پر گارے کی پتھریاں برسائیں۔', 'کہ چھوڑیں ہم اُن پر پتھر مٹی کے [۲۳]', 'To send down upon them stones of baked clay.', 'so that we may send down upon them stones of clay,'),
(4709, 51, 34, 2, 1, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'مُّسَوَّمَۃً  عِنۡدَ رَبِّکَ  لِلۡمُسۡرِفِیۡنَ ﴿۳۴﴾', 'جن پر حد سے بڑھ جانے والوں کے لئے تمہارے پروردگار کے ہاں سے نشان کر دیئے گئے ہیں۔', 'نشان پڑے ہوئے تیرے رب کے یہاں سے حد سے نکل چلنے والوں کے لئے [۲۴]', 'Marked by your Lord for the Musrifoon (polytheists, criminals, sinners those who trespass Allahs set limits in evil-doings by committing great sins).', 'marked by your Lord for the transgressors.”'),
(4710, 51, 35, 2, 1, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'فَاَخۡرَجۡنَا مَنۡ کَانَ فِیۡہَا مِنَ الۡمُؤۡمِنِیۡنَ ﴿ۚ۳۵﴾', 'پس وہاں جتنے مومن تھے انکو ہم نے نکال لیا۔', 'پھر بچا نکالا ہم نے جو تھا وہاں ایمان والا', 'So We brought out from therein the believers.', 'So, We let the believers who were there to come out (from danger),'),
(4711, 51, 36, 2, 1, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'فَمَا وَجَدۡنَا فِیۡہَا غَیۡرَ بَیۡتٍ مِّنَ الۡمُسۡلِمِیۡنَ ﴿ۚ۳۶﴾', 'پھر اس بستی میں ہم نے ایک گھر کے سوا مسلمانوں کا کوئی گھر نہ پایا۔', 'پھر نہ پایا ہم نے اس جگہ سوائے ایک گھر کے مسلمانوں سے [۲۵]', 'But We found not there any household of the Muslims except one (i.e. Lout (Lot) and his two daughters).', 'but We did not find in it any Muslims, except one house.'),
(4712, 51, 37, 2, 1, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'وَ تَرَکۡنَا فِیۡہَاۤ  اٰیَۃً  لِّلَّذِیۡنَ یَخَافُوۡنَ الۡعَذَابَ الۡاَلِیۡمَ ﴿ؕ۳۷﴾', 'اور جو لوگ عذاب الیم سے ڈرتے ہیں ان کے لئے ہم نے وہاں نشانی چھوڑ دی۔', 'اور باقی رکھا ہم نے اُس میں نشان اُن لوگوں کے لئے جو ڈرتے ہیں عذاب دردناک سے [۲۶]', 'And We have left there a sign (i.e. the place of the Dead Sea , well-known in Palestine) for those who fear the painful torment.', 'And We left in this (event) a sign (of deterrence) for those who fear the painful punishment.'),
(4713, 51, 38, 2, 1, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'وَ فِیۡ  مُوۡسٰۤی  اِذۡ  اَرۡسَلۡنٰہُ  اِلٰی فِرۡعَوۡنَ بِسُلۡطٰنٍ مُّبِیۡنٍ ﴿۳۸﴾', 'اور موسٰی  کے حال میں بھی نشانی ہے جب ہم نے انکو فرعون کی طرف کھلا ہوا معجزہ دے کر بھیجا۔', 'اور نشانی ہے موسٰی کے حال میں جب بیجھا ہم نے اُسکو فرعون کے پاس دے کر کھلی سند [۲۷]', 'And in Moosa (Moses) (too, there is a sign). When We sent him to Firaun (Pharaoh) with a manifest authority.', 'And (We left a similar sign) in (the story of) Mūsā, when We sent him to Fir‘aun (Pharaoh) with a clear proof.'),
(4714, 51, 39, 2, 1, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'فَتَوَلّٰی بِرُکۡنِہٖ وَ قَالَ سٰحِرٌ اَوۡ مَجۡنُوۡنٌ ﴿۳۹﴾', 'تو اس نے اپنی قوت کے گھمنڈ پر منہ موڑ لیا اور کہنے لگا یہ تو جادوگر ہے یا دیوانہ۔', 'پھر اُس نے منہ موڑ لیا اپنے زور پر اور بولا یہ جادوگر ہے یا دیوانہ [۲۸]', 'But (Firaun (Pharaoh)) turned away (from Belief in might) along with his hosts, and said: \"A sorcerer, or a madman.\"', 'So he turned away along with his chiefs and said, “ (Mūsā is) a magician or a madman!”'),
(4715, 51, 40, 2, 1, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'فَاَخَذۡنٰہُ  وَ جُنُوۡدَہٗ  فَنَبَذۡنٰہُمۡ  فِی الۡیَمِّ وَ ہُوَ  مُلِیۡمٌ ﴿ؕ۴۰﴾', 'تو ہم نے اس کو اور اس کے لشکروں کو پکڑ لیا اور انکو سمندر میں پھینک دیا اور وہ کام ہی قابل ملامت کرتا تھا۔', 'پھر پکڑا ہم نے اُسکو اور اُسکے لشکروں کو پھر پھینک دیا اُنکو دریا میں اور اُس پر لگا الزام [۲۹]', 'So We took him and his hosts, and dumped them into the sea, while he was to be blamed.', 'So We seized him and his army, and cast them into the sea, as he was of culpable behaviour.'),
(4716, 51, 41, 2, 1, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'وَ فِیۡ عَادٍ  اِذۡ  اَرۡسَلۡنَا عَلَیۡہِمُ  الرِّیۡحَ الۡعَقِیۡمَ ﴿ۚ۴۱﴾', 'اور عاد کی قوم کے حال میں بھی نشانی ہے جب ہم نے ان پر نامبارک ہوا چلائی۔', 'اور نشانی ہے عاد میں جب بھیجی ہم نے اُن پر ہوا خیر سے خالی', 'And in Ad (there is also a sign) when We sent against them the barren wind;', 'And (a similar sign was left) in (the story of) ‘Ād, when We sent upon them the wind that was barren (from any benefit);'),
(4717, 51, 42, 2, 1, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'مَا تَذَرُ مِنۡ شَیۡءٍ اَتَتۡ عَلَیۡہِ  اِلَّا جَعَلَتۡہُ  کَالرَّمِیۡمِ ﴿ؕ۴۲﴾', 'وہ جس چیز پر چلتی اسکو ریزہ ریزہ کئے بغیر نہ چھوڑتی۔', 'نہیں چھوڑتی کسی چیز کو جس پر گذرے کہ نہ کر ڈالے اسکو جیسے چورا [۳۰]', 'It spared nothing that it reached, but blew it into broken spreads of rotten ruins.', 'it spared nothing it came upon, but rendered it like a stuff smashed by decay.'),
(4718, 51, 43, 2, 1, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'وَ فِیۡ  ثَمُوۡدَ  اِذۡ  قِیۡلَ لَہُمۡ تَمَتَّعُوۡا حَتّٰی حِیۡنٍ ﴿۴۳﴾', 'اور قوم ثمود کے حال میں بھی نشانی ہے جب ان سے کہا گیا کہ ایک وقت تک فائدہ اٹھا لو۔', 'اور نشانی ہے ثمود میں جب کہا اُنکو  برت لو ایک وقت تک [۳۱]', 'And in Thamood (there is also a sign), when they were told: \"Enjoy yourselves for a while!\"', 'And (a similar sign was left) in (the story of) Thamūd, when it was said to them, “Enjoy yourselves for a while.”'),
(4719, 51, 44, 2, 1, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'فَعَتَوۡا عَنۡ  اَمۡرِ رَبِّہِمۡ فَاَخَذَتۡہُمُ الصّٰعِقَۃُ  وَ ہُمۡ  یَنۡظُرُوۡنَ ﴿۴۴﴾', 'پس انہوں نے اپنے پروردگار کے حکم سے سرکشی کی۔ سو انکو کڑک نے آ پکڑا اور وہ دیکھ رہے تھے۔', 'پھر شرارت کرنے لگے اپنے رب کے حکم سے پھر پکڑا اُنکو کڑک نے اور وہ دیکھتے تھے', 'But they insolently defied the Command of their Lord, so the Saiqah overtook them while they were looking.', 'Then they rebelled against the command of your Lord; so the thunderbolt (of divine punishment) seized them, while they were looking on.'),
(4720, 51, 45, 2, 1, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'فَمَا اسۡتَطَاعُوۡا مِنۡ قِیَامٍ  وَّ مَا کَانُوۡا مُنۡتَصِرِیۡنَ ﴿ۙ۴۵﴾', 'پھر نہ تو وہ کھڑے رہنے کی طاقت رکھتے تھے اور نہ مقابلہ کر سکتے تھے۔', 'پھر نہ ہو سکا اُن سے کہ اٹھیں اور نہ ہوئے کہ بدلا لیں [۳۲]', 'Then they were unable to rise up, nor could they help themselves.', 'Then they were neither able to stand (before the punishment), nor could they defend themselves.'),
(4721, 51, 46, 2, 1, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'وَ قَوۡمَ نُوۡحٍ  مِّنۡ قَبۡلُ ؕ اِنَّہُمۡ کَانُوۡا قَوۡمًا فٰسِقِیۡنَ ﴿٪۴۶﴾', 'اور اس سے پہلے ہم نوح  کی قوم کو ہلاک کر چکے تھے بیشک وہ نافرمان لوگ تھے۔', 'اور ہلاک کیا نوح کی قوم کو اس سے پہلے تحقیق وہ تھے لوگ نافرمان [۳۳]', '(So were) the people of Nooh (Noah) before them. Verily, they were a people who were Fasiqoon (rebellious, disobedient to Allah).', 'And (We have destroyed) the people of NūH even before; indeed they were a sinful people.'),
(4722, 51, 47, 3, 2, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'وَ السَّمَآءَ  بَنَیۡنٰہَا بِاَیۡىدٍ وَّ اِنَّا لَمُوۡسِعُوۡنَ ﴿۴۷﴾', 'اور آسمان کو ہم ہی نےاپنی قدرت سے بنایا اور ہم کو ہر طرح کی قدرت ہے۔', 'اور بنایا ہم نے آسمان ہاتھ کے بل سے اور ہم کو سب مقدور ہے [۳۴]', 'With power did We construct the heaven. Verily, We are Able to extend the vastness of space thereof.', 'And the sky was built by Us with might; and indeed We are the expanders.'),
(4723, 51, 48, 3, 2, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'وَ الۡاَرۡضَ فَرَشۡنٰہَا فَنِعۡمَ الۡمٰہِدُوۡنَ ﴿۴۸﴾', 'اور زمین کو ہم ہی نے بچھایا تو دیکھو ہم کیا خوب بچھانے والے ہیں۔', 'اور زمین کو بچھایا ہم نے سو کیا خوب بچھانا جانتے ہیں ہم [۳۵]', 'And We have spread out the earth, how Excellent Spreader (thereof) are We!', 'And the earth was spread out by Us as a floor; so how well have We spread it out!'),
(4724, 51, 49, 3, 2, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'وَ مِنۡ کُلِّ  شَیۡءٍ خَلَقۡنَا زَوۡجَیۡنِ لَعَلَّکُمۡ  تَذَکَّرُوۡنَ ﴿۴۹﴾', 'اور ہر چیز کے ہم نے دو دو جوڑے بنائے تاکہ تم نصیحت حاصل کرو۔', 'اور ہر چیز کے بنائے ہم نے جوڑے تاکہ تم دھیان کرو [۳۶]', 'And of everything We have created pairs, that you may remember (the Grace of Allah).', 'And from every thing We have created pairs of twos, so that you may heed.'),
(4725, 51, 50, 3, 2, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'فَفِرُّوۡۤا  اِلَی اللّٰہِ ؕ اِنِّیۡ  لَکُمۡ  مِّنۡہُ  نَذِیۡرٌ  مُّبِیۡنٌ ﴿ۚ۵۰﴾', 'تو تم لوگ اللہ کی طرف دوڑ چلو میں اسکی طرف سے تمکو  صاف صاف خبردار کرنے والا ہوں۔', 'سو بھاگو اللہ کی طرف میں تم کو اُسکی طرف سے ڈر سناتا ہوں کھول کر', 'So flee to Allah (from His Torment to His Mercy Islamic Monotheism), verily, I (Muhammad SAW) am a plain warner to you from Him.', 'So, flee to Allah. Indeed I am a plain warner sent by Him for you.'),
(4726, 51, 51, 3, 2, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'وَ لَا تَجۡعَلُوۡا مَعَ اللّٰہِ  اِلٰـہًا  اٰخَرَ ؕ اِنِّیۡ لَکُمۡ  مِّنۡہُ  نَذِیۡرٌ  مُّبِیۡنٌ ﴿ۚ۵۱﴾', 'اور اللہ کے ساتھ کسی اور کو معبود نہ بناؤ۔ میں اسکی طرف سے تمکو صاف صاف خبردار کرنے والا ہوں۔', 'اور مٹ ٹھہراؤ اللہ کے ساتھ اور کسی کو معبود میں تم کو اُسکی طرف سے ڈر سناتا ہوں کھول کر [۳۷]', 'And set not up (or worship) any other ilahan (god) along with Allah (Glorified be He (Alone), Exalted above all that they associate as partners with Him). Verily, I (Muhammad SAW) am a plain warner to you from Him.', 'And do not make up any other god along with Allah. Indeed I am a plain warner sent by Him for you.'),
(4727, 51, 52, 3, 2, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'کَذٰلِکَ مَاۤ  اَتَی الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ  مِّنۡ رَّسُوۡلٍ  اِلَّا  قَالُوۡا  سَاحِرٌ  اَوۡ مَجۡنُوۡنٌ ﴿ۚ۵۲﴾', 'اسی طرح ان سے پہلے لوگوں کے پاس بھی جو پیغمبر آتا تو وہ بھی اسکو جادوگر یا دیوانہ کہتے۔', 'اسی طرح ان سے پہلے لوگوں کے پاس جو رسول آیا اُس کو یہی کہا کہ جادوگر ہے یا دیوانہ [۳۸]', 'Likewise, no Messenger came to those before them, but they said: \"A sorcerer or a madman!\"', 'In similar way, no messenger came to those before them, but they said, “(He is) a magician or a madman.”'),
(4728, 51, 53, 3, 2, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'اَتَوَاصَوۡا بِہٖ ۚ بَلۡ ہُمۡ قَوۡمٌ طَاغُوۡنَ ﴿ۚ۵۳﴾', 'کیا یہ لوگ ایک دوسرے کو اسی بات کی وصیت کر مرے ہیں نہیں بلکہ یہ شریر لوگ ہیں۔', 'کیا یہی وصیت کر مرےہیں ایک دوسرے کو کوئی نہیں پر یہ لوگ شریر ہیں [۳۹]', 'Have they (the people of the past) transmitted this saying to these (Quraish pagans)? Nay, they are themselves a people transgressing beyond bounds (in disbelief)!', 'Have they handed down (this saying) to each other as a legacy? Rather they are a rebellious people.'),
(4729, 51, 54, 3, 2, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'فَتَوَلَّ عَنۡہُمۡ  فَمَاۤ   اَنۡتَ بِمَلُوۡمٍ  ﴿٭۫۵۴﴾', 'تو اے نبی ان سے منہ موڑ لو۔ تمکو ہماری طرف سے ملامت نہ ہوگی۔', 'سو تو لوٹ آنکی طرف سے اب تجھ پر نہیں ہے الزام', 'So turn away (O Muhammad SAW) from them (Quraish pagans) you are not to be blamed (as you have conveyed Allahs Message).', 'So, turn away from them, for you are not blamed.'),
(4730, 51, 55, 3, 2, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'وَّ  ذَکِّرۡ فَاِنَّ  الذِّکۡرٰی تَنۡفَعُ الۡمُؤۡمِنِیۡنَ  ﴿۵۵﴾', 'اور نصیحت کرتے رہو کہ نصیحت مومنوں کو نفع دیتی ہے۔', 'اور سمجھاتا رہ کہ سمجھانا کام آتا ہے ایمان والوں کو [۴۰]', 'And remind (by preaching the Quran, O Muhammad SAW) for verily, the reminding profits the believers.', 'And keep reminding, because reminding benefits the believers.'),
(4731, 51, 56, 3, 2, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'وَ مَا خَلَقۡتُ الۡجِنَّ وَ الۡاِنۡسَ  اِلَّا لِیَعۡبُدُوۡنِ ﴿۵۶﴾', 'اور میں نے جنوں اور انسانوں کو اسی لئے پیدا کیا ہے کہ وہ میری عبادت کریں۔', 'اور میں نے جو بنائے جن اور آدمی سو اپنی بندگی کو [۴۱]', 'And I (Allah) created not the jinns and humans except they should worship Me (Alone).', 'I did not create the Jinns and the human beings except for the purpose that they should worship Me.'),
(4732, 51, 57, 3, 2, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'مَاۤ  اُرِیۡدُ مِنۡہُمۡ  مِّنۡ  رِّزۡقٍ وَّ مَاۤ  اُرِیۡدُ اَنۡ یُّطۡعِمُوۡنِ ﴿۵۷﴾', 'میں ان سے رزق تو نہیں مانگتا اور نہ یہ چاہتا ہوں کہ وہ مجھے کھانا کھلائیں۔', 'میں نہیں چاہتا اُن سے روزینہ اور نہیں چاہتا کہ مجھ کو کھلائیں', 'I seek not any provision from them (i.e. provision for themselves or for My creatures) nor do I ask that they should feed Me (i.e. feed themselves or My creatures).', 'I do not want any sustenance from them, nor do I want them to feed Me.'),
(4733, 51, 58, 3, 2, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'اِنَّ اللّٰہَ ہُوَ الرَّزَّاقُ  ذُو الۡقُوَّۃِ  الۡمَتِیۡنُ ﴿۵۸﴾', 'اللہ ہی تو سبکو رزق دینے والا ہے زور آور ہے مضبوط ہے۔', 'اللہ جو ہے وہی ہے روزی دینے والا زور آور مضبوط [۴۲]', 'Verily, Allah is the All-Provider, Owner of Power, the Most Strong.', 'In fact, Allah is the All-Sustainer, Possessor of power, the Strong.'),
(4734, 51, 59, 3, 2, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'فَاِنَّ لِلَّذِیۡنَ ظَلَمُوۡا ذَنُوۡبًا مِّثۡلَ ذَنُوۡبِ اَصۡحٰبِہِمۡ  فَلَا یَسۡتَعۡجِلُوۡنِ ﴿۵۹﴾', 'سو کچھ شک نہیں کہ ان ظالموں کے لئے بھی عذاب کی نوبت مقرر ہے جس طرح انکے ساتھیوں کی نوبت تھی تو انکو مجھ سے عذاب جلدی نہیں طلب کرنا چاہیے۔', 'سو ان گنہگاروں کا بھی ڈول بھر چکا ہے جیسے ڈول بھرا اُنکے ساتھیوں کا اب مجھ سے جلدی نہ کریں [۴۳]', 'And verily, for those who do wrong, there is a portion of torment like to the evil portion of torment (which came for) their likes (of old), so let them not ask Me to hasten on!', 'So, those who did wrong will have their turn like the turn of their counterparts. So, they should not ask Me to hasten on.'),
(4735, 51, 60, 3, 2, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الذّٰریٰت', 'فَوَیۡلٌ  لِّلَّذِیۡنَ  کَفَرُوۡا مِنۡ یَّوۡمِہِمُ الَّذِیۡ یُوۡعَدُوۡنَ ﴿٪۶۰﴾', 'پھر جس دن کا ان کافروں سے وعدہ کیا جاتا ہے اس سے ان کے لئے خرابی ہے۔', 'سو خرابی ہے منکروں کو اُنکے اس دن سے جس کا اُن سے وعدہ ہو چکا ہے [۴۴]', 'Then, woe to those who disbelieve (in Allah and His Oneness Islamic Monotheism) from (that) their Day which they have been promised (for their punishment).', 'Woe, then, to those who disbelieve because of the Day of theirs that they are promised (for punishment).'),
(4736, 52, 1, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'وَ الطُّوۡرِ ۙ﴿۱﴾', 'کوہ طور کی قسم۔', 'قسم ہے طور کی [۱]', 'By the Mount;', 'By the mount of Tūr,'),
(4737, 52, 2, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'وَ کِتٰبٍ مَّسۡطُوۡرٍ ۙ﴿۲﴾', 'اور اس کتاب کی جو لکھی ہوئی ہے۔', 'اور لکھی ہوئی کتاب کی', 'And by the Book Inscribed.', 'and by a book, written'),
(4738, 52, 3, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'فِیۡ  رَقٍّ مَّنۡشُوۡرٍ ۙ﴿۳﴾', 'کشادہ ورق میں۔', 'کشادہ ورق میں [۲]', 'In parchment unrolled.', 'on an unrolled scroll,'),
(4739, 52, 4, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'وَّ الۡبَیۡتِ الۡمَعۡمُوۡرِ ۙ﴿۴﴾', 'اور آباد گھر کی۔', 'اور آباد گھر کی [۳]', 'And by the Bait-ul-Mamoor (the house over the heavens parable to the Kabah at Makkah, continuously visited by the angels);', 'and by the Populated House (Al-Bait-ul-Ma‘mūr) ,'),
(4740, 52, 5, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'وَ  السَّقۡفِ الۡمَرۡفُوۡعِ ۙ﴿۵﴾', 'اور اونچی چھت کی۔', 'اور اونچی چھت کی [۴]', 'And by the roof raised high (i.e. the heaven).', 'and by the roof, raised high,'),
(4741, 52, 6, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'وَ الۡبَحۡرِ  الۡمَسۡجُوۡرِ ۙ﴿۶﴾', 'اور جوش مارتے سمندر کی۔', 'اور اُبلتے ہوئے دریا کی [۵]', 'And by the sea kept filled (or it will be fire kindled on the Day of Resurrection).', 'and by the sea, flared up (with fire),'),
(4742, 52, 7, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اِنَّ عَذَابَ رَبِّکَ  لَوَاقِعٌ ۙ﴿۷﴾', 'کہ تمہارے پروردگار کا عذاب واقع ہو کر رہے گا۔', 'بیشک عذاب تیرے رب کا ہو کر رہے گا', 'Verily, the Torment of your Lord will surely come to pass,', 'the punishment of your Lord is sure to fall.'),
(4743, 52, 8, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'مَّا لَہٗ  مِنۡ  دَافِعٍ ۙ﴿۸﴾', 'اور اس کو کوئی روک نہیں سکے گا۔', 'اُسکو کوئی نہیں ہٹانے والا [۶]', 'There is none that can avert it;', 'There is nothing to push it back,'),
(4744, 52, 9, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'یَّوۡمَ تَمُوۡرُ السَّمَآءُ  مَوۡرًا ۙ﴿۹﴾', 'جس دن آسمان لرزنے لگے کپکپا کر۔', 'جس دن لرزے آسمان کپکپا کر [۷]', 'On the Day when the heaven will shake with a dreadful shaking,', 'the Day when the sky will tremble, a horrible trembling,'),
(4745, 52, 10, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'وَّ تَسِیۡرُ الۡجِبَالُ سَیۡرًا ﴿ؕ۱۰﴾', 'اور پہاڑ سچ مچ اڑنے لگیں۔', 'اور پھریں پہاڑ چل کر [۸]', 'And the mountains will move away with a (horrible) movement.', 'and the mountains will move about, a terrible movement.'),
(4746, 52, 11, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'فَوَیۡلٌ  یَّوۡمَئِذٍ  لِّلۡمُکَذِّبِیۡنَ ﴿ۙ۱۱﴾', 'تو اس دن جھٹلانے والوں کے لئے خرابی ہو گی۔', 'سو خرابی ہے اُس دن جھٹلانے والوں کو', 'Then woe that Day to the beliers;', 'So, woe to those who reject (the true faith),'),
(4747, 52, 12, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'الَّذِیۡنَ ہُمۡ فِیۡ خَوۡضٍ یَّلۡعَبُوۡنَ ﴿ۘ۱۲﴾', 'جو بیکار باتوں میں پڑے کھیل رہے ہیں۔', 'جو باتیں بناتے ہیں کھیلتے ہوئے [۹]', 'Who are playing in falsehood .', 'who are indulged in vain talk, playing (with truth),'),
(4748, 52, 13, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'یَوۡمَ  یُدَعُّوۡنَ  اِلٰی نَارِ  جَہَنَّمَ دَعًّا ﴿ؕ۱۳﴾', 'جس دن ان کو آتش جہنم کی طرف دھکیل دھکیل کر لے جائیں گے۔', 'جس دن کہ دھکیلے جائیں دوزخ کی طرف دھکیل کر', 'The Day when they will be pushed down by force to the Fire of Hell, with a horrible, forceful pushing.', 'the Day they will be pushed to the Fire forcefully,'),
(4749, 52, 14, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'ہٰذِہِ  النَّارُ الَّتِیۡ  کُنۡتُمۡ  بِہَا تُکَذِّبُوۡنَ ﴿۱۴﴾', 'اور کہا جائے گا یہی وہ جہنم ہے جس کو تم جھوٹ سمجھتے تھے۔', 'یہ ہے وہ آگ جسکو تم جھوت جانتے تھے [۱۰]', 'This is the Fire which you used to belie.', '(and it will be said to them,) “This is the Fire you used to deny.'),
(4750, 52, 15, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اَفَسِحۡرٌ  ہٰذَاۤ   اَمۡ  اَنۡتُمۡ لَا تُبۡصِرُوۡنَ ﴿ۚ۱۵﴾', 'تو کیا یہ جادو ہے یا تمکو نظر ہی نہیں آتا۔', 'اب بھلا یہ جادو ہے یا تم کو نہیں سوجھتا [۱۱]', 'Is this magic, or do you not see?', 'Is it then magic, or do you not see?'),
(4751, 52, 16, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اِصۡلَوۡہَا فَاصۡبِرُوۡۤا  اَوۡ لَا  تَصۡبِرُوۡا ۚ سَوَآءٌ  عَلَیۡکُمۡ ؕ اِنَّمَا تُجۡزَوۡنَ مَا کُنۡتُمۡ تَعۡمَلُوۡنَ ﴿۱۶﴾', 'اس میں داخل ہو جاؤ اور صبر کرو یا نہ کرو تمہارے لئے یکساں ہے جو کام تم کیا کرتے تھے یہ ان ہی کا تمکو بدلہ مل رہا ہے۔', 'چلے جاؤ اسکے اندر پھر تم صبر کرو یا نہ صبر کرو تم کو برابر ہے وہی بدلا پاؤ گے جو کچھ تم کرتے تھے [۱۲]', 'Taste you therein its heat, and whether you are patient of it or impatient of it, it is all the same. You are only being requited for what you used to do.', 'Enter it. Now, whether you endure (it) patiently or impatiently, it is all the same for you; you are merely rewarded for what you used to do.”'),
(4752, 52, 17, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اِنَّ  الۡمُتَّقِیۡنَ فِیۡ جَنّٰتٍ وَّ نَعِیۡمٍ ﴿ۙ۱۷﴾', 'جو پرہیزگار ہیں وہ باغوں اور نعمتوں میں ہوں گے۔', 'جو ڈرنے والے ہیں وہ باغوں میں ہے اور نعمت میں', 'Verily, the Muttaqoon (pious - see V.2:2) will be in Gardens (Paradise), and Delight.', 'Of course, the God-fearing will be in gardens and bliss,'),
(4753, 52, 18, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'فٰکِہِیۡنَ بِمَاۤ  اٰتٰہُمۡ  رَبُّہُمۡ ۚ وَ  وَقٰہُمۡ  رَبُّہُمۡ  عَذَابَ  الۡجَحِیۡمِ ﴿۱۸﴾', 'جو کچھ انکے پروردگار نے انکو بخشا اسکی وجہ سے وہ خوشحال ہونگے۔ اور انکے پروردگار نے انکو دوزخ کے عذاب سے بچا لیا۔', 'میوے کھاتے ہوئے جو اُنکو دیے  اُنکے رب نے اور بچایا اُنکے رب نے دوزخ کے عذاب سے [۱۳]', 'Enjoying in that which their Lord has bestowed on them, and (the fact that) their Lord saved them from the torment of the blazing Fire.', 'enjoying what their Lord will have given to them, and their Lord will have saved them from the punishment of Hell.'),
(4754, 52, 19, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'کُلُوۡا وَ اشۡرَبُوۡا ہَنِیۡٓـًٔۢا بِمَا کُنۡتُمۡ تَعۡمَلُوۡنَ ﴿ۙ۱۹﴾', 'کہا جائے گا کہ اپنے اعمال کے صلے میں مزے سے کھاؤ اور پیو۔', 'کھاؤ اور  پیو رچتا ہوا بدلا  اُن کاموں کا جو تم کرتے تھے', '\"Eat and drink with happiness because of what you used to do.\"', '(It will be said to them,) “Eat and drink pleasantly because of what you used to do,'),
(4755, 52, 20, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'مُتَّکِئِیۡنَ عَلٰی سُرُرٍ  مَّصۡفُوۡفَۃٍ ۚ وَ زَوَّجۡنٰہُمۡ  بِحُوۡرٍ عِیۡنٍ ﴿۲۰﴾', 'تختوں پر جو برابر برابر بچھے ہوئے ہیں تکیہ لگائے ہوئے ہونگے۔ اور بڑی بڑی آنکھوں والی حوروں کو ہم انکی بیویاں بنا دیں گے۔', 'تکیہ لگائے بیٹھے تختوں پر برابر بچھے ہوئے قطار باندھ کر [۱۴] اور بیاہ دیں ہم اُنکو حوریں بڑی آنکھوں والیاں', 'They will recline (with ease) on thrones arranged in ranks. And We shall marry them to Houris (female, fair ones) with wide lovely eyes.', 'relaxing on lined up couches”. And We will marry them with big-eyed houris.'),
(4756, 52, 21, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'وَ الَّذِیۡنَ اٰمَنُوۡا وَ اتَّبَعَتۡہُمۡ  ذُرِّیَّتُہُمۡ بِاِیۡمَانٍ  اَلۡحَقۡنَا بِہِمۡ  ذُرِّیَّتَہُمۡ  وَ مَاۤ  اَلَتۡنٰہُمۡ  مِّنۡ عَمَلِہِمۡ  مِّنۡ شَیۡءٍ ؕ کُلُّ امۡرِیًٔۢ  بِمَا کَسَبَ  رَہِیۡنٌ ﴿۲۱﴾', 'اور جو لوگ ایمان لائے اور انکی اولاد بھی راہ ایمان میں انکے پیچھے چلی۔ ہم انکی اولاد کو بھی انکے درجے تک پہنچا دیں گے اور انکے اعمال میں سے کچھ کم نہ کریں گے۔ ہر شخص اپنے اعمال میں پھنسا ہوا ہے۔', 'اور جو لوگ یقین لائے اور اُنکی راہ پر چلی اُنکی اولاد ایمان سے پہنچا دیا ہم نے اُن تک اُنکی اولاد کو اور گھٹایا نہیں ہم نے اُن سے ان کا کیا ذرا بھی [۱۵] ہر آدمی اپنی کمائی میں پھنسا ہے [۱۶]', 'And those who believe and whose offspring follow them in Faith, to them shall We join their offspring, and We shall not decrease the reward of their deeds in anything. Every person is a pledge for that which he has earned.', 'And those who believed and their children followed them in belief, We will join their children with them, and will not curtail (the reward of) any of their deeds at all. Every person will be pledged for what he earned.'),
(4757, 52, 22, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'وَ اَمۡدَدۡنٰہُمۡ  بِفَاکِہَۃٍ  وَّ لَحۡمٍ  مِّمَّا یَشۡتَہُوۡنَ ﴿۲۲﴾', 'اور جس طرح کے میوے اور گوشت کو انکا جی چاہے گا ہم انکو عطا کریں گے۔', 'اور تار لگا دیا ہم نے اُن پر میووں کا اور گوشت کا جس چیز کو جی چاہے [۱۷]', 'And We shall provide them with fruit and meat, such as they desire.', 'And We will go on giving them whatever they desire of fruits and meat.'),
(4758, 52, 23, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'یَتَنَازَعُوۡنَ  فِیۡہَا کَاۡسًا  لَّا  لَغۡوٌ  فِیۡہَا وَ لَا  تَاۡثِیۡمٌ ﴿۲۳﴾', 'وہاں وہ جام شراب کی چھینا جھپٹی کریں گے جسکے پینے سے نہ کوئی لغو بات ہو گی نہ کوئی گناہ کا کام۔', 'جھپٹتے ہیں وہاں پیالا نہ بکنا ہے اُس شراب میں اور  نہ گناہ میں ڈالنا [۱۸]', 'There they shall pass from hand to hand a (wine) cup, free from any Laghw (dirty, false, evil vague talk between them), and free from sin (because it will be legal for them to drink).', 'They will snatch from one another (in a friendly manner) a glass (of wine) carrying neither absurd talk, nor something leading to sin.'),
(4759, 52, 24, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'وَ یَطُوۡفُ عَلَیۡہِمۡ غِلۡمَانٌ  لَّہُمۡ  کَاَنَّہُمۡ لُؤۡلُؤٌ  مَّکۡنُوۡنٌ ﴿۲۴﴾', 'اور نوجوان خدمتگار جو ایسے ہوں گے جیسے چھپائے ہوئے موتی جو انکے آس پاس پھریں گے۔', 'اور  پھرتے ہیں اُنکے پاس چھوکرے اُنکے گویا وہ موتی ہیں اپنے غلاف کے اندر [۱۹]', 'And there will go round boy-servants of theirs, to serve them as if they were preserved pearls.', 'And their own serving boys will rotate around them, (who will be as neat and clean) as if they were hidden pearls.'),
(4760, 52, 25, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'وَ اَقۡبَلَ بَعۡضُہُمۡ عَلٰی بَعۡضٍ یَّتَسَآءَلُوۡنَ ﴿۲۵﴾', 'اور ایک دوسرے کی طرف رخ کر کے آپس میں گفتگو کریں گے۔', 'اور منہ کیا بعضوں نے دوسروں کی طرف آپس میں پوچھتے ہوئے', 'And some of them draw near to others, questioning.', 'And they will advance to one another, asking (about each other’s welfare).'),
(4761, 52, 26, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'قَالُوۡۤا اِنَّا کُنَّا قَبۡلُ فِیۡۤ   اَہۡلِنَا مُشۡفِقِیۡنَ ﴿۲۶﴾', 'کہیں گے کہ اس سے پہلے ہم اپنے گھر میں اللہ سے ڈرتے رہتے تھے۔', 'بولے ہم بھی تھے اس سے پہلے اپنے گھروں میں ڈرتے رہتے', 'Saying: \"Aforetime, we were afraid with our families (from the punishment of Allah).', 'They will say, “Indeed we were afraid (of Allah’s punishment) when we were amidst our family,'),
(4762, 52, 27, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'فَمَنَّ اللّٰہُ عَلَیۡنَا وَ  وَقٰىنَا عَذَابَ السَّمُوۡمِ ﴿۲۷﴾', 'تو اللہ نے ہم پر احسان فرمایا اور دوزخ کی گرم ہوا کے عذاب سے ہمیں بچا لیا۔', 'پھر احسان کیا اللہ نے ہم پر اور بچا دیا ہم کو لوُ کے عذاب سے', '\"But Allah has been gracious to us, and has saved us from the torment of the Fire.', 'but Allah did favour to us and saved us from the torment of Fire’s scorching breath.'),
(4763, 52, 28, 1, 3, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اِنَّا کُنَّا مِنۡ قَبۡلُ نَدۡعُوۡہُ ؕ اِنَّہٗ  ہُوَ الۡبَرُّ   الرَّحِیۡمُ ﴿٪۲۸﴾', 'اس سے پہلے ہم اسے پکارا کرتے تھے۔ بیشک وہ احسان کرنے والا ہے مہربان ہے۔', 'ہم پہلےسے پکارتے تھے اُسکو بیشک وہی ہے نیک سلوک والا مہربان [۲۰]', '\"Verily, We used to invoke Him (Alone and none else) before. Verily, He is AlBarr (the Most Subtle, Kind, Courteous, and Generous), the Most Merciful.\"', 'We used to pray to Him before. He is surely the Most-Kind, the Very-Merciful.'),
(4764, 52, 29, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'فَذَکِّرۡ  فَمَاۤ   اَنۡتَ بِنِعۡمَتِ رَبِّکَ بِکَاہِنٍ  وَّ لَا  مَجۡنُوۡنٍ ﴿ؕ۲۹﴾', 'تو اے پیغمبر تم نصیحت کرتے رہو تم اپنے پروردگار کے فضل سے نہ تو کاہن ہو اور نہ دیوانے۔', 'اب تو سمجھا دے کہ تو اپنے رب کے فضل سےنہ جنوں سےخبر لینے والا ہے اور نہ دیوانہ [۲۱]', 'Therefore, remind and preach (mankind, O Muhammad SAW of Islamic Monotheism). By the Grace of Allah, you are neither a soothsayer, nor a madman.', 'So keep reminding (them), because by the grace of your Lord, you are neither a soothsayer, nor a mad man.'),
(4765, 52, 30, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اَمۡ  یَقُوۡلُوۡنَ  شَاعِرٌ  نَّتَرَبَّصُ بِہٖ  رَیۡبَ الۡمَنُوۡنِ ﴿۳۰﴾', 'کیا کافر یہ کہتے ہیں کہ یہ شاعر ہے اور ہم اسکے لئے زمانے کی گردش کا انتظار کر رہے ہیں۔', 'کیا کہتےہیں یہ شاعر ہے ہم منتظر ہیں اُس پر گردش زمانہ کے [۲۲]', 'Or do they say: \"(Muhammad SAW is) a poet! We await for him some calamity by time.!\"', 'Do they rather say, “He is a poet for whom we are awaiting the accident of death?”'),
(4766, 52, 31, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'قُلۡ تَرَبَّصُوۡا فَاِنِّیۡ مَعَکُمۡ  مِّنَ الۡمُتَرَبِّصِیۡنَ ﴿ؕ۳۱﴾', 'کہدو کہ انتظار کئے جاؤ میں بھی تمہارے ساتھ انتظار کرتا ہوں۔', 'تو کہہ تم منتظر رہو کہ میں بھی تمہارے ساتھ منتظر ہوں [۲۳]', 'Say (O Muhammad SAW to them): \"Wait! I am with you, among the waiters!\"', 'Say, “Wait! I am waiting with you, too.”'),
(4767, 52, 32, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اَمۡ  تَاۡمُرُہُمۡ  اَحۡلَامُہُمۡ  بِہٰذَاۤ   اَمۡ  ہُمۡ قَوۡمٌ  طَاغُوۡنَ ﴿ۚ۳۲﴾', 'کیا انکی عقلیں انکو یہی سکھاتی ہیں۔ یا یہ لوگ ہیں ہی شریر۔', 'کیا اُنکی عقلیں یہی سکھلاتی ہیں اُنکو یا یہ لوگ شرارت پر ہیں [۲۴]', 'Do their minds command them this (i.e. to tell a lie against you (Muhammad SAW)) or are they people exceeding the bounds (i.e. from Belief in Allah to disbelief).', 'Is it their intellects that direct them to (say) this, or are they a rebellious people?'),
(4768, 52, 33, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اَمۡ  یَقُوۡلُوۡنَ تَقَوَّلَہٗ ۚ بَلۡ  لَّا  یُؤۡمِنُوۡنَ ﴿ۚ۳۳﴾', 'کیا کفار یہ کہتے ہیں کہ ان پیغمبر نے قرآن ازخود بنا لیا ہے بات یہ ہے کہ یہ اللہ پر ایمان نہیں رکھتے۔', 'یا کہتے ہیں یہ قرآن خود بنا لایا ہے  کوئی نہیں پر وہ یقین نہیں کرتے', 'Or do they say: \"He (Muhammad SAW) has forged it (this Quran)?\" Nay! They believe not!', 'Do they rather say, “He has forged it (the Qur’ān.)”? No, but they do not believe.'),
(4769, 52, 34, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'فَلۡیَاۡتُوۡا بِحَدِیۡثٍ مِّثۡلِہٖۤ   اِنۡ  کَانُوۡا صٰدِقِیۡنَ ﴿ؕ۳۴﴾', 'اگر یہ سچے ہیں تو یہ بھی ایسا کلام بنا لائیں۔', 'پھر چاہئے کہ لے آئیں کوئی بات اسی طرح کی اگر وہ سچے ہیں [۲۵]', 'Let them then produce a recital like unto it (the Quran) if they are truthful.', 'So, let them bring a discourse like this, if they are truthful.'),
(4770, 52, 35, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اَمۡ  خُلِقُوۡا  مِنۡ غَیۡرِ  شَیۡءٍ  اَمۡ ہُمُ الۡخٰلِقُوۡنَ ﴿ؕ۳۵﴾', 'کیا یہ کسی کے پیدا کئے بغیر ہی پیدا ہو گئے ہیں۔ یا یہ اپنے آپکو خود پیدا کرنے والے ہیں۔', 'کیا وہ بن گئے ہیں آپ ہی آپ یا وہی ہیں بنانے والے', 'Were they created by nothing, or were they themselves the creators?', 'Is it that they are created by none, or are they themselves the creators?'),
(4771, 52, 36, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اَمۡ خَلَقُوا السَّمٰوٰتِ  وَ الۡاَرۡضَ ۚ بَلۡ  لَّا یُوۡقِنُوۡنَ ﴿ؕ۳۶﴾', 'یا انہوں نے آسمانوں اور زمین کو پیدا کیا ہے؟ نہیں بلکہ یہ یقین ہی نہیں رکھتے۔', 'یا انہوں نے بنایا ہے آسمانوں کو اور زمین کو  کوئی نہیں پر وہ یقین نہیں کرتے [۲۶]', 'Or did they create the heavens and the earth? Nay, but they have no firm Belief.', 'Or have they created the heavens and the earth? No, but they are sure of nothing.'),
(4772, 52, 37, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اَمۡ  عِنۡدَہُمۡ  خَزَآئِنُ رَبِّکَ  اَمۡ  ہُمُ الۡمُصَۜیۡطِرُوۡنَ ﴿ؕ۳۷﴾', 'کیا انکے پاس تمہارے پروردگار کے خزانے ہیں۔ یا یہ کہیں کے داروغہ ہیں۔', 'کیا اُنکے پاس ہیں خزانے تیرے رب کے یا وہی داروغہ ہیں [۲۷]', 'Or are with them the treasures of your Lord? Or are they the tyrants with the authority to do as they like?', 'Or do they have the treasures of your Lord, or have they acquired control (over them)?'),
(4773, 52, 38, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اَمۡ  لَہُمۡ سُلَّمٌ   یَّسۡتَمِعُوۡنَ  فِیۡہِ ۚ فَلۡیَاۡتِ مُسۡتَمِعُہُمۡ  بِسُلۡطٰنٍ مُّبِیۡنٍ ﴿ؕ۳۸﴾', 'یا انکے پاس کوئی سیڑھی ہے جس پر چڑھ کر آسمان سے باتیں سن آتے ہیں تو جو سن کر آتا ہے وہ کھلی سند لیکر آئے۔', 'کیا اُنکے پاس کوئی سیڑھی ہے جس پر سُن آتے ہیں تو چاہیے کہ لے آئے جو سنتا ہے اُن میں ایک سند کھلی ہوئی [۲۸]', 'Or have they a stairway (to heaven), by means of which they listen (to the talks of the angels)? Then let their listener produce some manifest proof.', 'Or have they a stairway (to the heavens) by means of which they listen (to the divine decrees)? If so, their listener must bring a clear proof.'),
(4774, 52, 39, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اَمۡ  لَہُ  الۡبَنٰتُ وَ  لَکُمُ  الۡبَنُوۡنَ ﴿ؕ۳۹﴾', 'کیا اللہ کی تو ہوں بیٹیاں اور تمہارے لئے بیٹے۔', 'کیا اُسکے یہاں بیٹیاں ہیں اور تمہارے لئے بیٹے [۲۹]', 'Or has He (Allah) only daughters and you have sons?', 'Is it that He has daughters and you have sons?'),
(4775, 52, 40, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اَمۡ  تَسۡـَٔلُہُمۡ   اَجۡرًا  فَہُمۡ مِّنۡ  مَّغۡرَمٍ مُّثۡقَلُوۡنَ ﴿ؕ۴۰﴾', 'اے پیغمبر کیا تم ان سے معاوضہ مانگتے ہو کہ ان پر تاوان کا بوجھ پڑ رہا ہے۔', 'کیا تو مانگتا ہے اُن سے کچھ بدلا سو ان پر تاوان کا بوجھ ہے [۳۰]', 'Or is it that you (O Muhammad SAW) ask a wage from them (for your preaching of Islamic Monotheism) so that they are burdened with a load of debt?', 'Or is it that you (O prophet) ask them for a fee, and therefore they are burdened with a liability?'),
(4776, 52, 41, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اَمۡ  عِنۡدَہُمُ  الۡغَیۡبُ  فَہُمۡ  یَکۡتُبُوۡنَ ﴿ؕ۴۱﴾', 'یا انکے پاس غیب کا علم ہے کہ یہ اسے لکھ لیتے ہیں۔', 'کیا انکو خبر ہے بھید کی سو وہ لکھ رکھتے ہیں [۳۱]', 'Or that the Ghaib (unseen) is with them, and they write it down?', 'Or have they the knowledge of the Unseen, and they are recording it?'),
(4777, 52, 42, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اَمۡ  یُرِیۡدُوۡنَ  کَیۡدًا ؕ فَالَّذِیۡنَ  کَفَرُوۡا ہُمُ الۡمَکِیۡدُوۡنَ ﴿ؕ۴۲﴾', 'کیا یہ کوئی داؤں کرنا چاہتے ہیں تو کافر تو خود داؤں میں آنے والے ہیں۔', 'کیا چاہتےہیں کہ کچھ داؤ کرنا سو جو منکر ہیں وہی آتے ہیں داؤ میں [۳۲]', 'Or do they intend a plot (against you O Muhammad SAW)? But those who disbelieve (in the Oneness of Allah Islamic Monotheism) are themselves in a plot!', 'Or do they intend to plan to do harm (to the prophet)? Then the disbelievers themselves shall be harmed by the plan.'),
(4778, 52, 43, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'اَمۡ  لَہُمۡ  اِلٰہٌ  غَیۡرُ  اللّٰہِ ؕ سُبۡحٰنَ اللّٰہِ عَمَّا یُشۡرِکُوۡنَ ﴿۴۳﴾', 'کیا اللہ کے سوا ان کا کوئی اور معبود ہے؟ اللہ تو انکے شریک بنانے سے پاک ہے۔', 'کیا اُن کا کوئی حاکم ہے اللہ کے سوائے وہ اللہ پاک ہے اُنکے شریک بنانے سے [۳۳]', 'Or have they an ilah (a god) other than Allah? Glorified be Allah from all that they ascribe as partners (to Him)', 'Or do they have a god other than Allah? Pure is Allah from what they associate with Him.'),
(4779, 52, 44, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'وَ  اِنۡ  یَّرَوۡا کِسۡفًا مِّنَ السَّمَآءِ سَاقِطًا یَّقُوۡلُوۡا سَحَابٌ مَّرۡکُوۡمٌ ﴿۴۴﴾', 'اور اگر یہ آسمان کا کوئی ٹکڑا گرتا ہوا دیکھیں تو کہیں کہ یہ ایک تہ بہ تہ بادل ہے۔', 'اور اگر دیکھیں ایک تختہ آسمان سے گرتا ہوا کہیں یہ بادل ہے گاڑھا [۳۴]', 'And if they were to see a piece of the heaven falling down, they would say: \"Clouds gathered in heaps!\"', 'Even if they see a piece falling down from the sky, they would say, “It is a cumulated cloud.”'),
(4780, 52, 45, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'فَذَرۡہُمۡ حَتّٰی یُلٰقُوۡا یَوۡمَہُمُ  الَّذِیۡ فِیۡہِ یُصۡعَقُوۡنَ ﴿ۙ۴۵﴾', 'پس انکو چھوڑ دو یہاں تک کہ یہ اس روز کا سامنا کر لیں جس میں یہ بیہوش کر دیئے جائیں گے۔', 'سو تو چھوڑ دے اُنکو  یہاں تک کہ دیکھ لیں اپنے اُس دن کو جس میں اُن پر پڑے گی بجلی کی کڑک', 'So leave them alone till they meet their Day, in which they will sink into a fainting (with horror).', 'So, leave them alone until they face their Day, in which they will be turned unconscious,'),
(4781, 52, 46, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'یَوۡمَ لَا یُغۡنِیۡ عَنۡہُمۡ کَیۡدُہُمۡ شَیۡئًا وَّ لَا ہُمۡ  یُنۡصَرُوۡنَ ﴿ؕ۴۶﴾', 'جس دن ان کا کوئی داؤں کچھ بھی کام نہ آئے گا اور نہ انکو کہیں سے مدد ہی ملے گی۔', 'جس دن کام نہ آئے گا اُنکو  اُن کا داؤ ذرا بھی اور نہ اُنکو مدد پہنچے گی [۳۵]', 'The Day when their plotting shall not avail them at all nor will they be helped (i.e. they will receive their torment in Hell).', 'the Day their planning will not benefit them in the least, nor will they be helped.'),
(4782, 52, 47, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'وَ  اِنَّ لِلَّذِیۡنَ ظَلَمُوۡا عَذَابًا  دُوۡنَ ذٰلِکَ وَ لٰکِنَّ  اَکۡثَرَہُمۡ  لَا یَعۡلَمُوۡنَ ﴿۴۷﴾', 'اور ظالموں کے لئے اسکے سوا اور بھی عذاب ہے لیکن ان میں کے اکثر نہیں جانتے۔', 'اور اِن گنہگاروں کے لئے ایک عذاب ہے اُس سے ورے پر بہت اُن میں کے نہیں جانتے [۳۶]', 'And verily, for those who do wrong, there is another punishment (i.e. the torment in this world and in their graves) before this, but most of them know not. (Tafsir At-Tabaree, Vol. 27, Page 36).', 'And for those who did wrong there is another punishment before that, but most of them do not know.'),
(4783, 52, 48, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'وَ اصۡبِرۡ   لِحُکۡمِ  رَبِّکَ فَاِنَّکَ بِاَعۡیُنِنَا وَ  سَبِّحۡ  بِحَمۡدِ رَبِّکَ حِیۡنَ تَقُوۡمُ  ﴿ۙ۴۸﴾', 'اور تم اپنے پروردگار کے حکم کے انتظار میں صبر کئے رہو۔ تم تو ہماری آنکھوں کے سامنے ہو اور جب اٹھا کرو تو اپنے پروردگار کی تعریف کے ساتھ تسبیح کیا کرو۔', 'اور تو ٹھہرا رہ منتظر اپنے رب کے حکم کا تو تو ہماری آنکھوں کے سامنے ہے [۳۷] اور پاکی بیان کر اپنے رب کی خوبیاں جس وقت تو اٹھتا ہے [۳۸]', 'So wait patiently (O Muhammad SAW) for the Decision of your Lord, for verily, you are under Our Eyes , and glorify the Praises of your Lord when you get up from sleep.', 'And (O Prophet) be patient about the decision of your Lord, because you are in front of Our Eyes. And proclaim the purity of your Lord along with His praise when you stand (in Prayer),'),
(4784, 52, 49, 2, 4, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الطّور', 'وَ مِنَ الَّیۡلِ فَسَبِّحۡہُ  وَ  اِدۡبَارَ النُّجُوۡمِ ﴿٪۴۹﴾', 'اور رات کے بعض اوقات میں بھی اور ستاروں کے غروب ہونے کے بعد بھی اسکی تسبیح کیا کرو۔', 'اور کچھ رات میں بول اُسکی پاکی اور پیٹھ پھیرتے وقت تاروں کے [۳۹]', 'And in the night-time, also glorify His Praises, and at the setting of the stars.', 'And, in parts of night too, proclaim His purity, and at the time of setting of the stars.'),
(4785, 53, 1, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ النَّجۡمِ   اِذَا ہَوٰی  ۙ﴿۱﴾', 'ستارے کی قسم جب غائب ہونے لگے۔', 'قسم ہے تارے کی جب گرے [۱]', 'By the star when it goes down, (or vanishes).', 'By the star when it goes down to set,'),
(4786, 53, 2, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'مَا ضَلَّ صَاحِبُکُمۡ  وَ مَا غَوٰی ۚ﴿۲﴾', 'کہ تمہارے رفیق یعنی ہمارے نبی نہ رستہ بھولے ہیں نہ بھٹکے ہیں۔', 'بہکا نہیں تمہارا رفیق اور نہ بے راہ چلا [۲]', 'Your companion (Muhammad SAW) has neither gone astray nor has erred.', 'your fellow (the Holy Prophet) has neither missed the way, nor did he deviate.'),
(4787, 53, 3, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ مَا یَنۡطِقُ عَنِ  الۡہَوٰی  ؕ﴿۳﴾', 'اور نہ یہ خواہش نفس سے کچھ بولتے ہیں۔', 'اور نہیں بولتا اپنے نفس کی خواہش سے', 'Nor does he speak of (his own) desire.', 'He does not speak out of (his own) desire.'),
(4788, 53, 4, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'اِنۡ  ہُوَ   اِلَّا  وَحۡیٌ   یُّوۡحٰی  ۙ﴿۴﴾', 'یہ قرآن تو ایک وحی ہے جو انکی طرف بھیجی جاتی ہے۔', 'یہ تو حکم ہے بھیجا ہوا [۳]', 'It is only an Inspiration that is inspired.', 'It is but revelation revealed (to him).'),
(4789, 53, 5, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'عَلَّمَہٗ  شَدِیۡدُ الۡقُوٰی  ۙ﴿۵﴾', 'انکو نہایت قوت والے نے سکھایا۔', 'اُسکو سکھلایا ہے سخت قوتوں والے نے زورآور نے [۴]', 'He has been taught (this Quran) by one mighty in power (Jibrael (Gabriel)).', 'It is taught to him by one (angel) of strong faculties,'),
(4790, 53, 6, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'ذُوۡ مِرَّۃٍ ؕ  فَاسۡتَوٰی  ۙ﴿۶﴾', 'یعنی جبرائیل نے جو طاقتور ہیں پھر وہ پوری طرح بیٹھے۔', 'پھر سیدھا بیٹھا', 'Dhu Mirrah (free from any defect in body and mind), Fastawa (then he (Jibrael Gabriel) rose and became stable). (Tafsir At-Tabaree).', 'the one of vigour. So he stood poised,'),
(4791, 53, 7, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ ہُوَ  بِالۡاُفُقِ الۡاَعۡلٰی ؕ﴿۷﴾', 'جبکہ وہ آسمان کے اونچے کنارے پر تھے۔', 'اور وہ تھا اُونچے کنارے پر آسمان کے [۵]', 'While he (Jibrael (Gabriel)) was in the highest part of the horizon,', 'while he was on the upper horizon.'),
(4792, 53, 8, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'ثُمَّ  دَنَا فَتَدَلّٰی ۙ﴿۸﴾', 'پھر وہ قریب ہوئے پھر مزید نیچے آ گئے۔', 'پھر نزدیک ہوا اور لٹک آیا', 'Then he (Jibrael (Gabriel)) approached and came closer,', 'Then he drew near, and came down,'),
(4793, 53, 9, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'فَکَانَ قَابَ قَوۡسَیۡنِ  اَوۡ اَدۡنٰی  ۚ﴿۹﴾', 'تو وہ دو کمان کے فاصلے پر ہو گئے یا اس سے بھی کم۔', 'پھر رہ گیا فرق دو کمان کی برابر یا اس سے بھی نزدیک', 'And was at a distance of two bows length or (even) nearer,', 'so as he was at a distance like that of two bows (joined together), rather even nearer.'),
(4794, 53, 10, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'فَاَوۡحٰۤی  اِلٰی عَبۡدِہٖ  مَاۤ  اَوۡحٰی  ﴿ؕ۱۰﴾', 'پھر اللہ نے اپنے بندے کی طرف جو حکم بھیجا سو بھیجا۔', 'پھر حکم بھیجا اللہ نے اپنے بندہ پر جو بھیجا [۶]', 'So did (Allah) convey the Inspiration to His slave (Muhammad SAW through Jibrael (Gabriel) ).', 'Thus He (Allah) revealed to His slave what He revealed.'),
(4795, 53, 11, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'مَا کَذَبَ الۡفُؤَادُ  مَا  رَاٰی  ﴿۱۱﴾', 'جو کچھ انہوں نے دیکھا انکے دل نے اسکو جھوٹ نہ جانا۔', 'جھوٹ نہیں کہا رسول کے دل نے جو دیکھا [۷]', 'The (Prophets) heart lied not (in seeing) what he (Muhammad SAW) saw.', 'The heart did not err in what he saw.'),
(4796, 53, 12, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'اَفَتُمٰرُوۡنَہٗ  عَلٰی مَا یَرٰی  ﴿۱۲﴾', 'کیا جو کچھ وہ دیکھتے ہیں تم اس میں ان سے جھگڑتے ہو؟', 'اب کیا تم اُس سے جھگڑتے ہو اُس پر جو اُس نے دیکھا [۱۸]', 'Will you then dispute with him (Muhammad SAW) about what he saw (during the Miraj: (Ascent of the Prophet SAW over the seven heavens)) .', 'Do you quarrel with him in what he sees?'),
(4797, 53, 13, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ لَقَدۡ رَاٰہُ  نَزۡلَۃً   اُخۡرٰی  ﴿ۙ۱۳﴾', 'اور انہوں نے اسکو یعنی جبرئیل کو ایک اور بار بھی اترتے دیکھا ہے۔', 'اور اُسکو اُس نے دیکھا ہے اترتے ہوئے ایک بار اور بھی', 'And indeed he (Muhammad SAW) saw him (Jibrael (Gabriel)) at a second descent (i.e. another time).', 'Indeed he saw him another time'),
(4798, 53, 14, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'عِنۡدَ سِدۡرَۃِ  الۡمُنۡتَہٰی ﴿۱۴﴾', 'سدرۃ المنتہٰی کے پاس۔', 'سدرۃ المنتہٰی کے  پاس', 'Near Sidrat-ul-Muntaha (lote-tree of the utmost boundary (beyond which none can pass)),', 'by Sidrat-ul-Muntahā (the lote-tree in the upper realm),'),
(4799, 53, 15, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'عِنۡدَہَا جَنَّۃُ  الۡمَاۡوٰی  ﴿ؕ۱۵﴾', 'اسی کے پاس ہمیشہ رہنے کی بہشت ہے۔', 'اُس کے پاس ہے بہشت آرام سے رہنے کی [۹]', 'Near it is the Paradise of Abode.', 'near which there is Jannat-ul-Ma’wā (the Paradise of Abode),'),
(4800, 53, 16, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'اِذۡ  یَغۡشَی السِّدۡرَۃَ  مَا یَغۡشٰی  ﴿ۙ۱۶﴾', 'جبکہ اس بیری پر چھا رہا تھا جو چھا رہا تھا۔', 'جب چھا رہا تھا اُس بیری پر جو کچھ چھا رہا تھا [۱۰]', 'When that covered the lote-tree which did cover it!', 'when the lote-tree was covered by that which covered it.'),
(4801, 53, 17, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'مَا زَاغَ الۡبَصَرُ  وَ مَا طَغٰی ﴿۱۷﴾', 'ان کی آنکھ نہ تو اور طرف مائل ہوئی اور نہ حد سے آگے بڑھی۔', 'بہکی نہیں نگاہ اور نہ حد سے بڑھی [۱۱]', 'The sight (of Prophet Muhammad SAW) turned not aside (right or left), nor it transgressed beyond (the) limit (ordained for it).', 'The eye neither went wrong, nor did exceed the limit.'),
(4802, 53, 18, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'لَقَدۡ رَاٰی مِنۡ اٰیٰتِ رَبِّہِ  الۡکُبۡرٰی ﴿۱۸﴾', 'انہوں نے اپنے پروردگار کی قدرت کی بہت ہی بڑی بڑی نشانیاں دیکھیں۔', 'بیشک دیکھے اُس نے اپنے رب کے بڑے نمونے [۱۲]', 'Indeed he (Muhammad SAW) did see, of the Greatest Signs, of his Lord (Allah).', 'He has indeed seen a part of the biggest signs of your Lord.'),
(4803, 53, 19, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'اَفَرَءَیۡتُمُ  اللّٰتَ وَ الۡعُزّٰی ﴿ۙ۱۹﴾', 'بھلا تم لوگوں نے لات اور عزٰی کو دیکھا۔', 'بھلا دیکھو تو لات اور عزّیٰ کو', 'Have you then considered Al-Lat, and Al-Uzza (two idols of the pagan Arabs)', 'Have you ever considered about the (idols of) Lāt and ‘Uzzā,'),
(4804, 53, 20, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ مَنٰوۃَ  الثَّالِثَۃَ  الۡاُخۡرٰی  ﴿۲۰﴾', 'اور تیسری مورتی یعنی منات کو۔', 'اور منات تیسرے پچھلے کو [۱۳]', 'And Manat (another idol of the pagan Arabs), the other third?', 'and about the other, the third (idol), namely, Manāt,?'),
(4805, 53, 21, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'اَلَکُمُ  الذَّکَرُ  وَ لَہُ  الۡاُنۡثٰی  ﴿۲۱﴾', 'مشرکو! کیا تمہارے لئے تو بیٹے ہوں اور اللہ کے لئے بیٹیاں۔', 'کیا تم کو تو ملے بیٹے اور اُسکو بیٹیاں', 'Is it for you the males and for Him the females?', 'Is it that you have males and He (Allah) has females?'),
(4806, 53, 22, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'تِلۡکَ  اِذًا  قِسۡمَۃٌ  ضِیۡزٰی  ﴿۲۲﴾', 'یہ تو بہت ہی بے انصافی کی تقسیم ہوئی۔', 'یہ بانٹا تو بہت بھونڈا [۱۴]', 'That indeed is a division most unfair!', 'If so, it is a bizarre division.'),
(4807, 53, 23, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'اِنۡ  ہِیَ  اِلَّاۤ  اَسۡمَآءٌ سَمَّیۡتُمُوۡہَاۤ  اَنۡتُمۡ وَ اٰبَآؤُکُمۡ  مَّاۤ  اَنۡزَلَ اللّٰہُ  بِہَا مِنۡ سُلۡطٰنٍ ؕ اِنۡ یَّتَّبِعُوۡنَ  اِلَّا الظَّنَّ وَ مَا تَہۡوَی الۡاَنۡفُسُ ۚ وَ لَقَدۡ جَآءَہُمۡ مِّنۡ رَّبِّہِمُ  الۡہُدٰی ﴿ؕ۲۳﴾', 'وہ تو صرف نام ہی نام ہیں جو تم نے اور تمہارے باپ دادا نے رکھ لئے ہیں۔ اللہ نے تو انکی کوئی سند نازل نہیں کی۔ یہ لوگ محض خیال و گمان اور خواہشات نفس کے پیچھے چل رہے ہیں حالانکہ انکے پروردگار کی طرف سے انکے پاس ہدایت آ چکی ہے۔', 'یہ سب نام ہیں جو رکھ لئے ہیں تم نے اور تمہارے باپ دادوں نے اللہ نے نہیں اتاری اُنکی کوئی سند [۱۵] محض اٹکل پرچلتے ہیں اور جو جیوں کی امنگ ہے اور  پہنچی ہے اُنکو  اُنکے رب سے راہ کی سوجھ [۱۶]', 'They are but names which you have named, you and your fathers, for which Allah has sent down no authority. They follow but a guess and that which they themselves desire, whereas there has surely come to them the Guidance from their Lord!', 'These are nothing but names you and your fathers have invented; Allah has sent down no authority attached to them. They are following nothing but conjecture and what their own souls desire, while guidance from their Lord has surely reached them.'),
(4808, 53, 24, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'اَمۡ  لِلۡاِنۡسَانِ مَا تَمَنّٰی  ﴿۫ۖ۲۴﴾', 'کیا جس چیز کی انسان آرزو کرتا ہے وہ اسے ضرور ملتی ہے؟', 'کہیں آدمی کو ملتا ہے جوکچھ چاہے', 'Or shall man have what he wishes?', 'Is it that man can get whatever he wishes?'),
(4809, 53, 25, 1, 5, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'فَلِلّٰہِ  الۡاٰخِرَۃُ  وَ الۡاُوۡلٰی ﴿٪۲۵﴾', 'سو آخرت اور دنیا تو اللہ ہی کے ہاتھ میں ہے۔', 'سو اللہ کے ہاتھ ہے سب بھلائی پچھلی اور پہلی [۱۷]', 'But to Allah belongs the last (Hereafter) and the first (the world).', '(No,) because to Allah alone belongs the (good of) the Hereafter and the former life (of this world).'),
(4810, 53, 26, 2, 6, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ کَمۡ مِّنۡ مَّلَکٍ فِی السَّمٰوٰتِ لَا  تُغۡنِیۡ شَفَاعَتُہُمۡ شَیۡئًا  اِلَّا مِنۡۢ  بَعۡدِ اَنۡ یَّاۡذَنَ اللّٰہُ  لِمَنۡ یَّشَآءُ  وَ  یَرۡضٰی ﴿۲۶﴾', 'اور آسمانوں میں بہت سے فرشتے ہیں جنکی سفارش کچھ بھی فائدہ نہیں دیتی مگر اس وقت کہ اللہ جس کے لئے چاہے اجازت بخشے اور سفارش پسند بھی کرے۔', 'اور بہت فرشتے ہیں آسمانوں میں کچھ کام نہیں آتی اُنکی سفارش مگر جب حکم دے اللہ جسکے واسطے چاہے اور پسند کرے [۱۸]', 'And there are many angels in the heavens, whose intercession will avail nothing except after Allah has given leave for whom He wills and pleases.', 'How many angels there are in the heavens whose intercession cannot benefit (any one) at all, but after Allah allows (it) for whomsoever He wills and pleases.'),
(4811, 53, 27, 2, 6, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'اِنَّ  الَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِالۡاٰخِرَۃِ لَیُسَمُّوۡنَ  الۡمَلٰٓئِکَۃَ  تَسۡمِیَۃَ  الۡاُنۡثٰی ﴿۲۷﴾', 'جو لوگ آخرت پر ایمان نہیں لاتے وہ فرشتوں کو لڑکیوں کے نام سے موسوم کرتے ہیں۔', 'جو لوگ یقین نہیں رکھتے آخرت کا وہ نام رکھتے ہیں فرشتوں کے زنانے نام', 'Verily, those who believe not in the Hereafter, name the angels with female names.', 'Those who do not believe in the Hereafter call the angels by names of females.'),
(4812, 53, 28, 2, 6, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ مَا  لَہُمۡ بِہٖ مِنۡ عِلۡمٍ ؕ اِنۡ یَّتَّبِعُوۡنَ  اِلَّا الظَّنَّ ۚ وَ اِنَّ الظَّنَّ  لَا یُغۡنِیۡ مِنَ الۡحَقِّ شَیۡئًا ﴿ۚ۲۸﴾', 'حالانکہ انکو اسکی کچھ خبر نہیں۔ وہ صرف خیال و گمان پر چلتے ہیں جبکہ خیال و گمان حق کے مقابلے میں کچھ کام نہیں آتا۔', 'اور اُنکو اُس کی کچھ خبر نہیں محض اٹکل پر چلتےہیں اوراٹکل کچھ کام نہ آئے ٹھیک بات میں [۱۹]', 'While they have no knowledge thereof. They follow but a guess, and verily, guess is no substitute for the truth.', 'They do not have knowledge about it. They follow nothing but conjecture, and conjecture is of no avail in (the matter of) Truth.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(4813, 53, 29, 2, 6, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'فَاَعۡرِضۡ عَنۡ مَّنۡ تَوَلّٰی ۬ۙ عَنۡ ذِکۡرِنَا وَ لَمۡ  یُرِدۡ  اِلَّا  الۡحَیٰوۃَ  الدُّنۡیَا ﴿ؕ۲۹﴾', 'تو جو ہماری یاد سے روگردانی کرے اور صرف دنیا ہی کی زندگی کا خواہاں ہو اس سے تم بھی منہ پھیر لو۔', 'سو تو دھیان نہ کر اُس پر جو منہ موڑے ہماری یاد سے اور کچھ نہ چاہے مگر دنیا کا جینا', 'Therefore withdraw (O Muhammad SAW) from him who turns away from Our Reminder (this Quran) and desires nothing but the life of this world.', 'So, turn away from him who turns away from Our advice, and seeks nothing but (pleasure of) the worldly life.'),
(4814, 53, 30, 2, 6, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'ذٰلِکَ مَبۡلَغُہُمۡ  مِّنَ الۡعِلۡمِ ؕ اِنَّ رَبَّکَ ہُوَ اَعۡلَمُ بِمَنۡ ضَلَّ عَنۡ سَبِیۡلِہٖ ۙ وَ ہُوَ اَعۡلَمُ  بِمَنِ  اہۡتَدٰی  ﴿۳۰﴾', 'انکے علم کی یہی انتہا ہے۔ تمہارا پروردگار اسکو بھی خوب جانتا ہے جو اسکے رستے سے بھٹک گیا اور اس سے بھی خوب واقف ہے جو رستے پر چلا۔', 'بس یہیں تک پہنچی اُنکی سمجھ [۲۰] تحقیق تیرا رب ہی خوب جانے اُسکو جو بہکا اُسکی راہ سے اور وہی خوب جانے اُسکو جو راہ پر آیا [۲۱]', 'That is what they could reach of knowledge. Verily, your Lord it is He Who knows best him who goes astray from His Path, and He knows best him who receives guidance.', 'That is the limit of their access to knowledge. Indeed only your Lord knows well about the one who has gone astray from his way, and He knows well about the one who has adopted the right path.'),
(4815, 53, 31, 2, 6, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ لِلّٰہِ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ۙ لِیَجۡزِیَ الَّذِیۡنَ  اَسَآءُوۡا بِمَا عَمِلُوۡا وَ یَجۡزِیَ الَّذِیۡنَ اَحۡسَنُوۡا بِالۡحُسۡنٰی ﴿ۚ۳۱﴾', 'اور جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے سب اللہ ہی کا ہے اور اس نے خلقت کو اس لئے پیدا کیا ہے کہ جن لوگوں نے برے کام کئے انکو ان کے اعمال کا بدلہ دے اور جنہوں نے نیکیاں کیں انکو نیک بدلہ دے۔', 'اور اللہ کا ہے جو کچھ ہے آسمانوں میں اور زمین میں تاکہ وہ بدلا دے برائی والوں کو اُنکے کئے کا اور بدلا دے بھلائی والوں کو بھلائی سے [۲۲]', 'And to Allah belongs all that is in the heavens and all that is in the earth, that He may requite those who do evil with that which they have done (i.e. punish them in Hell), and reward those who do good, with what is best (i.e. Paradise).', 'To Allah belongs whatever there is in the heavens and whatever there is in the earth, so that He gives punishment to evildoers for what they did, and gives good reward to those who did good'),
(4816, 53, 32, 2, 6, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'اَلَّذِیۡنَ یَجۡتَنِبُوۡنَ کَبٰٓئِرَ الۡاِثۡمِ وَ الۡفَوَاحِشَ  اِلَّا اللَّمَمَ ؕ اِنَّ  رَبَّکَ وَاسِعُ  الۡمَغۡفِرَۃِ ؕ ہُوَ اَعۡلَمُ بِکُمۡ  اِذۡ اَنۡشَاَکُمۡ مِّنَ الۡاَرۡضِ وَ اِذۡ  اَنۡتُمۡ  اَجِنَّۃٌ فِیۡ  بُطُوۡنِ اُمَّہٰتِکُمۡ ۚ فَلَا  تُزَکُّوۡۤا اَنۡفُسَکُمۡ ؕ ہُوَ  اَعۡلَمُ  بِمَنِ اتَّقٰی  ٪﴿۳۲﴾', 'جو صغیرہ گناہوں کے سوا بڑے بڑے گناہوں اور بےحیائی کی باتوں سے اجتناب کرتے ہیں۔ بیشک تمہارا پروردگار بڑی بخشش والا ہے۔ وہ تمکو خوب جانتا ہے۔ جب اس نے تمکو مٹی سے پیدا کیا اور جب تم اپنی ماؤں کے پیٹ میں بچے تھے۔ تو اپنے آپکو پاک صاف نہ جتاؤ۔ جو پرہیزگار ہے وہ اس سے خوب واقف ہے۔', 'جو کہ بچتے ہیں بڑے گناہوں سے اور بیحیائی کے کاموں سے مگر کچھ آلودگی [۲۳] بیشک تیرے رب کی بخشش میں بڑی سمائی ہے [۲۴] وہ تم کو خوب جانتا ہے جب بنا نکالا تم کو زمین سے اور جب تم بچے تھے ماں کے پیٹ میں سو مت بیان کر اپنی خوبیاں وہ خوب جانتا ہے اُس کو جو بچ کرچلا [۲۵]', 'Those who avoid great sins (see the Quran, Verses: 6:152,153) and Al-Fawahish (illegal sexual intercourse, etc.) except the small faults, verily, your Lord is of vast forgiveness. He knows you well when He created you from the earth (Adam), and when you were fetuses in your mothers wombs. So ascribe not purity to yourselves. He knows best him who fears Allah and keep his duty to Him (i.e. those who are Al-Muttaqoon (pious - see V.2:2)).', '-those who abstain from the major sins and from shameful acts, except minor involvements. Indeed your Lord is extensive in forgiveness. He knows you more than anyone else (from a time) when He created you from the earth and when you were embryos in the wombs of your mothers. So, do not claim purity (from faults) for your selves. He knows best who is God-fearing.'),
(4817, 53, 33, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'اَفَرَءَیۡتَ الَّذِیۡ  تَوَلّٰی ﴿ۙ۳۳﴾', 'بھلا تم نے اس شخص کو دیکھا جس نے منہ پھیر لیا۔', 'بھلا تو نے دیکھا اُس کو جس نے منہ پھیر لیا [۲۶]', 'Did you (O Muhammad SAW) observe him who turned away (from Islam).', 'Did you see the one who turned away,'),
(4818, 53, 34, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ اَعۡطٰی قَلِیۡلًا  وَّ  اَکۡدٰی ﴿۳۴﴾', 'اور تھوڑا سا دیا پھر ہاتھ روک لیا۔', 'اور لایا تھوڑا سا اور سخت نکلا [۲۷]', 'And gave a little, then stopped (giving)?', 'and gave a little, and stopped?'),
(4819, 53, 35, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'اَعِنۡدَہٗ  عِلۡمُ  الۡغَیۡبِ فَہُوَ یَرٰی ﴿۳۵﴾', 'کیا اسکے پاس غیب کا علم ہے کہ وہ اسے دیکھ رہا ہے۔', 'کیا اُسکے پاس خبر ہے غیب کی سو وہ دیکھتا ہے [۲۸]', 'Is with him the knowledge of the unseen so that he sees?', 'Does he have knowledge of the Unseen whereby he sees (what he believes)?'),
(4820, 53, 36, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'اَمۡ  لَمۡ  یُنَبَّاۡ  بِمَا فِیۡ  صُحُفِ مُوۡسٰی ﴿ۙ۳۶﴾', 'کیا جو باتیں موسٰی  کے صحیفوں میں ہیں انکی اسکو خبر نہیں پہنچی۔', 'کیا اسکو خبر نہیں پہنچی اُسکی جو ہے ورقوں میں موسٰی کے', 'Or is he not informed with what is in the Pages (Scripture) of Moosa (Moses),', 'Has he not been told of what was (revealed) in the scriptures of Mūsā'),
(4821, 53, 37, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ  اِبۡرٰہِیۡمَ  الَّذِیۡ  وَفّٰۤی ﴿ۙ۳۷﴾', 'اور ابراہیم کے صحیفوں کی جنہوں نے حق طاعت و رسالت پورا کیا۔', 'اور ابراہیم کے جس نے کہ اپنا قول پورا اتارا [۲۹]', 'And of Ibrahim (Abraham) who fulfilled (or conveyed) all that (what Allah ordered him to do or convey),', 'and of Ibrāhīm who fulfilled (his duties)?'),
(4822, 53, 38, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'اَلَّا تَزِرُ وَازِرَۃٌ  وِّزۡرَ اُخۡرٰی ﴿ۙ۳۸﴾', 'وہ یہ کہ کوئی شخص دوسرے کے گناہ کا بوجھ نہیں اٹھائے گا۔', 'کہ اٹھاتا نہیں کوئی اٹھانے والا بوجھ کسی دوسرے کا [۳۰]', 'That no burdened person (with sins) shall bear the burden (sins) of another,', '(It was) that no bearer of burden shall bear the burden of the other,'),
(4823, 53, 39, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ اَنۡ  لَّیۡسَ لِلۡاِنۡسَانِ  اِلَّا مَا سَعٰی ﴿ۙ۳۹﴾', 'اور یہ کہ انسان کو وہی ملتا ہے جسکے لئے وہ محنت کرتا ہے۔', 'اور یہ کہ آدمی کو وہی ملتا ہے جو اُس نے کمایا [۳۱]', 'And that man can have nothing but what he does (good or bad) ,', 'and that a man shall not deserve but (the reward of) his own effort,'),
(4824, 53, 40, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ اَنَّ سَعۡیَہٗ  سَوۡفَ یُرٰی ﴿۪۴۰﴾', 'اور یہ کہ اسکی  محنت کا جائزہ لیا جائے گی۔', 'اور یہ کہ اُسکی کمائی اُسکو دکھلانی ضرور ہے', 'And that his deeds will be seen,', 'and that his effort will soon be seen,'),
(4825, 53, 41, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'ثُمَّ  یُجۡزٰىہُ  الۡجَزَآءَ  الۡاَوۡفٰی ﴿ۙ۴۱﴾', 'پھر اسکو اس کا پورا پورا بدلہ دیا جائے گا۔', 'پھر اُسکو بدلا ملنا ہے اُس کا پورا بدلا [۳۲]', 'Then he will be recompensed with a full and the best recompense', 'then he will be recompensed for it in full,'),
(4826, 53, 42, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ اَنَّ  اِلٰی رَبِّکَ الۡمُنۡتَہٰی ﴿ۙ۴۲﴾', 'اور یہ کہ تمہارے پروردگار ہی کے پاس پہنچنا ہے۔', 'اور یہ کہ تیرے رب تک سب کو پہنچنا ہے [۳۳]', 'And that to your Lord (Allah) is the End (Return of everything).', 'and that to your Lord is the end (of every one),'),
(4827, 53, 43, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ اَنَّہٗ  ہُوَ  اَضۡحَکَ وَ اَبۡکٰی ﴿ۙ۴۳﴾', 'اور یہ کہ وہ ہنساتا اور رلاتا ہے۔', 'اور یہ کہ وہی ہے ہنساتا اور رلاتا', 'And that it is He (Allah) Who makes (whom He wills) laugh, and makes (whom He wills) weep;', 'and that He is the One who makes (one) laugh and makes (him) weep,'),
(4828, 53, 44, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ اَنَّہٗ  ہُوَ  اَمَاتَ وَ  اَحۡیَا ﴿ۙ۴۴﴾', 'اور یہ کہ وہی زندگی دیتا ہے اور وہی موت دیتا ہے۔', 'اور یہ کہ وہی ہے مارتا اور جِلاتا', 'And that it is He (Allah) Who causes death and gives life;', 'and that He is the One who gives death and gives life,'),
(4829, 53, 45, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ اَنَّہٗ  خَلَقَ  الزَّوۡجَیۡنِ  الذَّکَرَ  وَ الۡاُنۡثٰی ﴿ۙ۴۵﴾', 'اور یہ کہ وہی دونوں جوڑے یعنی نر اور مادہ پیدا کرتا ہے۔', 'اور یہ کہ اُس نے بنایا جوڑا نر اور مادہ [۳۴]', 'And that He (Allah) creates the pairs, male and female,', 'and that He creates the pairs, male and female,'),
(4830, 53, 46, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'مِنۡ نُّطۡفَۃٍ  اِذَا تُمۡنٰی ﴿۪۴۶﴾', 'یعنی نطفے سے جو رحم میں ڈالا جاتا ہے۔', 'ایک بوند سے جب ٹپکائی جائے', 'From Nutfah (drops of semen male and female discharges) when it is emitted;', 'from a sperm-drop when it is poured (into a womb),'),
(4831, 53, 47, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ اَنَّ عَلَیۡہِ  النَّشۡاَۃَ  الۡاُخۡرٰی  ﴿ۙ۴۷﴾', 'اور یہ کہ قیامت کو دوبارہ اٹھانا اسی کا ذمہ ہے۔', 'اور یہ کہ اُس کے ذمہ ہے دوسری دفعہ اٹھانا [۳۵]', 'And that upon Him (Allah) is another bringing forth (Resurrection);', 'and that the second creation is undertaken by Him,'),
(4832, 53, 48, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ اَنَّہٗ  ہُوَ  اَغۡنٰی وَ  اَقۡنٰی ﴿ۙ۴۸﴾', 'اور یہ کہ وہی دولتمند بناتا اور وہی مفلس کرتا ہے۔', 'اور یہ کہ اُس نے دولت دی اور خزانہ [۳۶]', 'And that it is He (Allah) Who gives much or a little (or gives wealth and contentment),', 'and that He is the One who gives wealth and preserves (it),'),
(4833, 53, 49, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ اَنَّہٗ  ہُوَ  رَبُّ  الشِّعۡرٰی ﴿ۙ۴۹﴾', 'اور یہ کو وہی شعرٰی نامی تارے کا بھی مالک ہے۔', 'اور یہ کہ وہی ہے رب شعریٰ کا [۳۷]', 'And that He (Allah) is the Lord of Sirius (the star which the pagan Arabs used to worship);', 'and that He is the One who is the Lord of Sirius (the star worshipped by pagans),'),
(4834, 53, 50, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ اَنَّہٗۤ  اَہۡلَکَ عَادَۨ ا  الۡاُوۡلٰی ﴿ۙ۵۰﴾', 'اور یہ کہ اسی نے عاد اوّل کو ہلاک کر ڈالا۔', 'اور یہ کہ اُس نے غارت کیا عاد پہلے کو [۳۸]', 'And that it is He (Allah) Who destroyed the former Ad (people),', 'and that He has destroyed the earlier ‘Ād,'),
(4835, 53, 51, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ ثَمُوۡدَا۠   فَمَاۤ   اَبۡقٰی ﴿ۙ۵۱﴾', 'اور ثمود کو بھی غرض کسی کو باقی نہ چھوڑا۔', 'اور ثمود کو پھر کسی کو باقی نہ چھوڑا', 'And Thamood (people). He spared none of them.', 'and Thamūd, so spared none,'),
(4836, 53, 52, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ قَوۡمَ نُوۡحٍ مِّنۡ قَبۡلُ ؕ اِنَّہُمۡ کَانُوۡا ہُمۡ  اَظۡلَمَ  وَ اَطۡغٰی ﴿ؕ۵۲﴾', 'اور ان سے پہلے قوم نوح  کو بھی۔ کچھ شک نہیں کہ وہ لوگ بڑے ہی ظالم اور بڑے ہی سرکش تھے۔', 'اور نوح کی قوم کو پہلے ان سے وہ تو تھے اور بھی ظالم اور شریر [۳۹]', 'And the people of Nooh (Noah) aforetime, verily, they were more unjust and more rebellious and transgressing (in disobeying Allah and His Messenger Nooh (Noah) ).', 'and (destroyed) the people of NūH even earlier. Surely they were more unjust and more rebellious.'),
(4837, 53, 53, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ الۡمُؤۡتَفِکَۃَ  اَہۡوٰی ﴿ۙ۵۳﴾', 'اور اسی نے الٹی ہوئی بستیوں کو دے پٹکا۔', 'اور اُلٹی بستی کو پٹک دیا', 'And He destroyed the overthrown cities (of Sodom to which Prophet Lout (Lot) was sent).', 'And He destroyed the overturned towns (of the people of LūT) also,'),
(4838, 53, 54, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'فَغَشّٰہَا مَا غَشّٰی ﴿ۚ۵۴﴾', 'پھر ان پر جو چیز چھا گئ سو چھا گئ۔', 'پھر آ پڑا اس پرجو کچھ کہ آ پڑا [۴۰]', 'So there covered them that which did cover (i.e. torment with stones).', 'so enveloped they were by that which enveloped.'),
(4839, 53, 55, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکَ  تَتَمَارٰی ﴿۵۵﴾', 'تو اے انسان تو اپنے پروردگار کی کون کون سی نعمت پر جھگڑے گا۔', 'اب تو کیا کیا نعمتیں اپنے رب کی جھٹلائے گا [۴۱]', 'Then which of the Graces of your Lord (O man!) will you doubt.', 'Then concerning which of your Lord’s bounties would you remain in doubt?'),
(4840, 53, 56, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'ہٰذَا نَذِیۡرٌ  مِّنَ  النُّذُرِ  الۡاُوۡلٰی ﴿۵۶﴾', 'یہ پیغمبر بھی پہلے کے خبردار کرنے والوں میں سے ایک خبردار کرنے والے ہیں۔', 'یہ ایک ڈر سنانے والا ہے پہلے سنانے والوں میں کا [۴۲]', 'This (Muhammad SAW) is a warner (Messenger) of the (series of) warners (Messengers) of old .', 'This (Prophet) is a warner from the (genus of the) previous warners.'),
(4841, 53, 57, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'اَزِفَتِ  الۡاٰزِفَۃُ ﴿ۚ۵۷﴾', 'آنے والی یعنی قیامت قریب آ پہنچی۔', 'آ پہنچی آنے والی', 'The Day of Resurrection draws near,', 'The Imminent (Hour of Judgment) has approached.'),
(4842, 53, 58, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'لَیۡسَ لَہَا مِنۡ دُوۡنِ اللّٰہِ  کَاشِفَۃٌ ﴿ؕ۵۸﴾', 'اس دن کی تکلیفوں کو اللہ کے سوا کوئی دور نہیں کر سکے گا۔', 'کوئی نہیں اُسکو اللہ کے سوائے کھول کر دکھانے والا [۴۳]', 'None besides Allah can avert it, (or advance it, or delay it).', 'There is no one, beside Allah, to remove it.'),
(4843, 53, 59, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'اَفَمِنۡ ہٰذَا  الۡحَدِیۡثِ  تَعۡجَبُوۡنَ ﴿ۙ۵۹﴾', 'اے کافرو کیا تم اس کلام پر تعجب کرتے ہو۔', 'کیا تمکو اس بات سےتعجب ہوا ہے', 'Do you then wonder at this recital (the Quran)?', 'Do you then wonder at this discourse,'),
(4844, 53, 60, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ تَضۡحَکُوۡنَ  وَ لَا  تَبۡکُوۡنَ ﴿ۙ۶۰﴾', 'اور ہنستے ہو اور روتے نہیں۔', 'اور ہنستےہو اور روتے نہیں', 'And you laugh at it and weep not,', 'and laugh (at it), and not weep,'),
(4845, 53, 61, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'وَ اَنۡتُمۡ  سٰمِدُوۡنَ ﴿۶۱﴾', 'اور تم غفلت میں پڑے ہو۔', 'اور تم کھلاڑیاں کرتے ہو [۴۴]', 'Wasting your (precious) lifetime in pastime and amusements (singing, etc.).', 'while you are engaged in vain play?'),
(4846, 53, 62, 3, 7, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'النجم', 'فَاسۡجُدُوۡا لِلّٰہِ  وَ اعۡبُدُوۡا ﴿٪ٛ۶۲﴾', 'تو اللہ کے آگے سجدہ کرو اور اسی کی عبادت کرو۔', 'سو سجدہ کرو اللہ کے آگے اور بندگی [۴۵]', 'So fall you down in prostration to Allah, and worship Him (Alone).', 'Now, fall down in prostration and worship (Allah).'),
(4847, 54, 1, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'اِقۡتَرَبَتِ السَّاعَۃُ  وَ انۡشَقَّ  الۡقَمَرُ ﴿۱﴾', 'قیامت قریب آ پہنچی اور چاند شق ہو گیا۔', 'پاس آ لگی قیامت اور  پھٹ گیا چاند [۱]', 'The Hour has drawn near, and the moon has been cleft asunder (the people of Makkah requested Prophet Muhammad SAW to show them a miracle, so he showed them the splitting of the moon).', 'The Hour (of doom) has drawn near, and the moon has split asunder.'),
(4848, 54, 2, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ اِنۡ یَّرَوۡا اٰیَۃً  یُّعۡرِضُوۡا وَ یَقُوۡلُوۡا سِحۡرٌ مُّسۡتَمِرٌّ ﴿۲﴾', 'اور اگر کافر کوئی نشانی دیکھتے ہیں تو منہ پھیر لیتے ہیں اور کہتے ہیں کہ یہ ایک پہلے سے چلا آتا جادو ہے۔', 'اور اگر وہ دیکھیں کوئی نشانی تو ٹلا جائیں اورکہیں یہ جادو ہے پہلے سے چلا آتا [۲]', 'And if they see a sign, they turn away, and say: \"This is continuous magic.\"', 'When these people see a sign, they turn away and say, “(This is) a transient magic.”'),
(4849, 54, 3, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ کَذَّبُوۡا وَ اتَّبَعُوۡۤا اَہۡوَآءَہُمۡ وَ کُلُّ اَمۡرٍ مُّسۡتَقِرٌّ ﴿۳﴾', 'اور انہوں نے جھٹلایا اور اپنی خواہشوں کی پیروی کی اور ہر کام کا وقت مقرر ہے۔', 'اور جھٹلایا اور چلے اپنی خوشی پر اور ہر کام ٹھہرا رکھا ہے وقت پر [۳]', 'They belied (the Verses of Allah, this Quran), and followed their own lusts. And every matter will be settled (according to the kind of deeds (for the doer of good deeds, his deeds will take him to Paradise, and similarly evil deeds will take their doers to Hell)).', 'They have rejected (the Truth) and followed their desires, while every matter has to settle (at some time).'),
(4850, 54, 4, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ لَقَدۡ جَآءَہُمۡ  مِّنَ الۡاَنۡۢبَآءِ مَا فِیۡہِ مُزۡدَجَرٌ ۙ﴿۴﴾', 'اور انکو ایسے واقعات کی خبریں پہنچ چکی ہیں جن میں عبرت ہے۔', 'اور پہنچ چکے ہیں اُنکے  پاس احوال جن میں ڈانٹ ہو سکتی ہے [۴]', 'And indeed there has come to them news (in this Quran) wherein there is (enough warning) to check (them from evil),', 'And there has come to them as much news (of the earlier communities) as it is enough to deter,'),
(4851, 54, 5, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'حِکۡمَۃٌۢ  بَالِغَۃٌ  فَمَا تُغۡنِ النُّذُرُ ۙ﴿۵﴾', 'اور کامل دانائی کی کتاب بھی لیکن ڈراوے انکو کچھ فائدہ نہیں دیتے۔', 'پوری عقل کی بات ہے پھر اُن میں کام نہیں کرتے ڈر سنانے والے', 'Perfect wisdom (this Quran), but (the preaching of) warners benefit them not,', '(containing) a perfect wisdom. But the warnings are of no avail (to them).'),
(4852, 54, 6, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'فَتَوَلَّ عَنۡہُمۡ ۘ یَوۡمَ یَدۡعُ الدَّاعِ  اِلٰی شَیۡءٍ  نُّکُرٍ ۙ﴿۶﴾', 'تو تم بھی انکی کچھ پروا نہ کرو۔ جس دن بلانے والا انکو ایک ناگوار چیز کی طرف بلائے گا۔', 'سو تو ہٹ آ اُنکی طرف سے [۵] جس دن پکارے پکارنے والا ایک ناگوار چیز کی طرف [۶]', 'So (O Muhammad SAW) withdraw from them. The Day that the caller will call (them) to a terrible thing.', 'Therefore, turn aside (O Prophet,) from them. (They will see the reality) on the day in which the caller will call (them) to a gruesome object.'),
(4853, 54, 7, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'خُشَّعًا اَبۡصَارُہُمۡ یَخۡرُجُوۡنَ مِنَ الۡاَجۡدَاثِ  کَاَنَّہُمۡ  جَرَادٌ   مُّنۡتَشِرٌ ۙ﴿۷﴾', 'فورًا آنکھیں نیچی کئے ہوئے قبروں سے نکل پڑیں گے گویا بکھری ہوئی ٹڈیاں ہوں۔', 'آنکھیں جھکائے [۷] نکل پڑیں قبروں سے جیسے ٹڈی پھیلی ہوئی', 'They will come forth, with humbled eyes from (their) graves as if they were locusts spread abroad,', 'With their eyes humbled, they will come out of the graves like locusts spread all over,'),
(4854, 54, 8, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'مُّہۡطِعِیۡنَ  اِلَی الدَّاعِ ؕ یَقُوۡلُ الۡکٰفِرُوۡنَ ہٰذَا یَوۡمٌ  عَسِرٌ ﴿۸﴾', 'اس بلانے والے کی طرف دوڑتے جاتے ہوں گے۔ کافر کہیں گے یہ دن بڑا سخت ہے۔', 'دوڑتے جائیں اُس پکارنے والے کے  پا س [۸] کہتے جائیں مُنکر یہ دن مشکل آیا [۹]', 'Hastening towards the caller, the disbelievers will say: \"This is a hard Day.\"', 'rushing quickly towards the caller. (On that Day) the disbelievers will say, “This is a hard day.”'),
(4855, 54, 9, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'کَذَّبَتۡ قَبۡلَہُمۡ  قَوۡمُ نُوۡحٍ  فَکَذَّبُوۡا عَبۡدَنَا وَ  قَالُوۡا  مَجۡنُوۡنٌ  وَّ ازۡدُجِرَ ﴿۹﴾', 'ان سے پہلے نوح  کی قوم نے بھی تکذیب کی تھی تو انہوں نے ہمارے بندے کو جھٹلایا اور کہا کہ دیوانہ ہے اور انہیں ڈانٹا بھی گیا۔', 'جھٹلا چکی ہے اُن سے پہے نوح کی قوم پھر جھوٹا کہا ہمارے بندے کو اور  بولے دیوانہ ہے اور جھڑک لیا اُسکو [۱۰]', 'The people of Nooh (Noah) denied (their Messenger) before them, they rejected Our slave, and said: \"A madman!\" and he was insolently rebuked and threatened.', 'The people of NūH denied (the truth) before them. So they rejected Our servant, and said, “(He is) a madman”, and he was (also) threatened (by them).'),
(4856, 54, 10, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'فَدَعَا رَبَّہٗۤ  اَنِّیۡ  مَغۡلُوۡبٌ  فَانۡتَصِرۡ ﴿۱۰﴾', 'تو انہوں نے اپنے پروردگار سے دعا کی کہ میں انکے مقابلے میں کمزور ہوں بس تو ہی بدلہ لے لے۔', 'پھر پکارا اپنے رب کو کہ میں عاجز ہو گیا ہوں تو بدلا لے [۱۱]', 'Then he invoked his Lord (saying): \"I have been overcome, so help (me)!\"', 'So he prayed to his Lord saying, “I am overpowered, so defend (me).”'),
(4857, 54, 11, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'فَفَتَحۡنَاۤ  اَبۡوَابَ السَّمَآءِ  بِمَآءٍ  مُّنۡہَمِرٍ ﴿۫ۖ۱۱﴾', 'پس ہم نے زور کے مینہ سے آسمان کے دہانے کھول دیئے۔', 'پھر ہم نے کھول دئے دہانے آسمان کے پانی ٹوٹ کر برسنے والے سے', 'So We opened the gates of heaven with water pouring forth.', 'So We opened the gates of the sky with water pouring forth profusely,'),
(4858, 54, 12, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَّ فَجَّرۡنَا الۡاَرۡضَ عُیُوۡنًا فَالۡتَقَی الۡمَآءُ عَلٰۤی  اَمۡرٍ  قَدۡ  قُدِرَ ﴿ۚ۱۲﴾', 'اور زمین میں چشمے جاری کر دیئے تو پانی ایک کام کے لئے جو مقدر ہو چکا تھا جمع ہو گیا۔', 'اور بہا دیے زمین پر چشمے پھر مل گیا سب پانی ایک کام پر جو ٹھہر چکا تھا [۱۲]', 'And We caused the earth to gush forth with springs. So the waters (of the heaven and the earth) met for a matter predestined.', 'and We caused the earth to gush forth as springs; so the water (of both kinds) met together for a destined event.'),
(4859, 54, 13, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ  حَمَلۡنٰہُ  عَلٰی ذَاتِ اَلۡوَاحٍ  وَّ دُسُرٍ ﴿ۙ۱۳﴾', 'اور ہم نے نوح کو ایک کشتی پر جو تختوں اور میخوں سے تیار کی گئ تھی سوار کر لیا۔', 'اور ہم نے اُسکو سوار کر دیا ایک تختوں اور کیلوں والی (کشتی) پر', 'And We carried him on a (ship) made of planks and nails,', 'And We caused him (NūH) to board that (ship) which had planks and nails,'),
(4860, 54, 14, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'تَجۡرِیۡ  بِاَعۡیُنِنَا ۚ جَزَآءً  لِّمَنۡ کَانَ کُفِرَ ﴿۱۴﴾', 'وہ ہماری آنکھوں کے سامنے چلتی تھی۔ یہ سب کچھ اس شخص کے انتقام کے لئے کیا گیا جسکو کافر مانتے نہ تھے۔', 'بہتی تھی ہماری آنکھوں کےسامنے [۱۳] بدلا لینے کو اس کی طرف سے  جسکی قدر نہ جانی تھی [۱۴]', 'Floating under Our Eyes, a reward for him who had been rejected!', 'which sailed under Our Eyes, as a reward for the one who was rejected (by the infidels).'),
(4861, 54, 15, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ لَقَدۡ  تَّرَکۡنٰہَاۤ  اٰیَۃً  فَہَلۡ مِنۡ مُّدَّکِرٍ ﴿۱۵﴾', 'اور ہم نے اس کشتی کو ایک نشانی بنا چھوڑا تو کوئی ہے کہ سوچے سمجھے؟', 'اور اُسکو ہم نے رہنے دیا نشانی کے لئے پھر کوئی ہے سوچنے والا [۱۵]', 'And indeed, We have left this as a sign, then is there any that will remember (or receive admonition)?', 'And We left it (the ship) as a sign. So, is there one to take lesson?'),
(4862, 54, 16, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'فَکَیۡفَ کَانَ عَذَابِیۡ  وَ  نُذُرِ ﴿۱۶﴾', 'سو دیکھ لو کہ میرا عذاب اور ڈرانا کیسا ہوا؟', 'پھر کیسا تھا میرا عذاب اور میرا کھڑکھڑانا [۱۶]', 'Then how (terrible) was My Torment and My Warnings?', 'Then how was My torment and My warnings?'),
(4863, 54, 17, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ لَقَدۡ یَسَّرۡنَا الۡقُرۡاٰنَ  لِلذِّکۡرِ  فَہَلۡ مِنۡ مُّدَّکِرٍ ﴿۱۷﴾', 'اور ہم نے قرآن کو سمجھنے کے لئے آسان کر دیا ہے تو کوئی ہے کہ سوچے سمجھے؟', 'اور ہم نے آسان کر دیا قرآن سمجھنے کو پھر ہےکوئی سوچنے والا [۱۷]', 'And We have indeed made the Quran easy to understand and remember, then is there any that will remember (or receive admonition)?', 'Indeed We have made the Qur’ān easy for seeking advice. So, is there one to heed to the advice?'),
(4864, 54, 18, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'کَذَّبَتۡ عَادٌ  فَکَیۡفَ کَانَ عَذَابِیۡ وَ نُذُرِ ﴿۱۸﴾', 'قوم عاد نے بھی تکذیب کی تھی سو دیکھ لو کہ میرا عذاب اور ڈرانا کیسا ہوا۔', 'جھٹلایا عاد نے پھر کیسا ہوا میرا عذاب اور میرا کھڑکھڑانا', 'Ad (people) belied (their Prophet, Hood), then how (terrible) was My Torment and My Warnings?', '(The people of) ‘Ād rejected (their prophet). So how was My torment and My warnings?'),
(4865, 54, 19, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'اِنَّاۤ  اَرۡسَلۡنَا عَلَیۡہِمۡ رِیۡحًا صَرۡصَرًا فِیۡ یَوۡمِ  نَحۡسٍ  مُّسۡتَمِرٍّ ﴿ۙ۱۹﴾', 'ہم نے ان پر ایک رہتی نحوست کے دن میں زبردست آندھی چھوڑ دی۔', 'ہم نے بھیجی اُن پر ہوا تند ایک نحوست کے دن جو چلے گئ [۱۸]', 'Verily, We sent against them a furious wind of harsh voice on a day of evil omen and continuous calamity.', 'We did send to them a furious wind in a day of continuous misfortune,'),
(4866, 54, 20, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'تَنۡزِعُ  النَّاسَ ۙ کَاَنَّہُمۡ  اَعۡجَازُ نَخۡلٍ مُّنۡقَعِرٍ ﴿۲۰﴾', 'وہ لوگوں کو اس طرح اکھیڑے ڈالتی تھی گویا اکھڑی ہوئی کھجوروں کے تنے ہیں۔', 'اکھاڑ مارا لوگوں کو گویا وہ جڑیں ہیں کھجور کی اکھڑی پڑی [۱۹]', 'Plucking out men as if they were uprooted stems of date-palms.', 'plucking people away, as if they were trunks of uprooted palm-trees.'),
(4867, 54, 21, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'فَکَیۡفَ کَانَ  عَذَابِیۡ  وَ نُذُرِ ﴿۲۱﴾', 'سو دیکھ لو کہ میرا عذاب اور ڈرانا کیسا ہوا۔', 'پھر کیسا رہا میرا عذاب اور میرا کھڑکھڑانا', 'Then, how (terrible) was My Torment and My Warnings?', 'So how was My torment and My warnings?'),
(4868, 54, 22, 1, 8, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ لَقَدۡ یَسَّرۡنَا الۡقُرۡاٰنَ  لِلذِّکۡرِ فَہَلۡ مِنۡ مُّدَّکِرٍ ﴿٪۲۲﴾', 'اور ہم نے قرآن کو سمجھنے کے لئے آسان کر دیا ہے۔ تو کوئی ہے کہ سوچے سمجھے؟', 'اور ہم نے آسان کر دیا قرآن سمجھنے کو پھر ہے کوئی سوچنے والا', 'And We have indeed made the Quran easy to understand and remember, then is there any that will remember (or receive admonition)?', 'Indeed We have made the Qur’ān easy for seeking advice. So, is there one to heed to the advice?'),
(4869, 54, 23, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'کَذَّبَتۡ ثَمُوۡدُ  بِالنُّذُرِ ﴿۲۳﴾', 'قوم ثمود نے بھی خبردار کرنے والوں کو جھٹلایا۔', 'جھٹلایا ثمود نے ڈر سنانے والوں کو [۲۰]', 'Thamood (people also) belied the warnings.', '(The people of) Thamūd rejected the warners.'),
(4870, 54, 24, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'فَقَالُوۡۤا اَبَشَرًا مِّنَّا وَاحِدًا نَّتَّبِعُہٗۤ ۙ اِنَّاۤ  اِذًا  لَّفِیۡ ضَلٰلٍ  وَّ  سُعُرٍ ﴿۲۴﴾', 'تو کہا کہ بھلا ایک آدمی جو ہم ہی میں سے ہے ہم اسکی پیروی کریں؟ یوں ہو تو ہم گمراہی اور دیوانگی میں پڑ گئے۔', 'پھر کہنے لگے کیا ایک آدمی ہم میں کا اکیلا ہم اس کے کہے پر چلیں گے تو تو ہم غلطی میں پڑے اور سودا میں [۲۱]', 'For they said: \"A man! Alone from among us, that we are to follow? Truly, then we should be in error and distress or madness!\"', 'So they said, “Shall we follow a single human being from among us? Then we will be in error and insanity.'),
(4871, 54, 25, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'ءَاُلۡقِیَ الذِّکۡرُ عَلَیۡہِ مِنۡۢ  بَیۡنِنَا بَلۡ ہُوَ کَذَّابٌ  اَشِرٌ ﴿۲۵﴾', 'کیا ہم سب میں سے اسی پر وحی نازل ہوئی ہے؟ نہیں بلکہ یہ جھوٹا بڑائی مارنے والا ہے۔', 'کیا اتری اُسی پر نصیحت ہم سب میں سے کوئی نہیں یہ جھوٹ ہے بڑائی مارتا ہے [۲۲]', '\"Is it that the Reminder is sent to him (Prophet Salih (Saleh) ) alone from among us? Nay, he is an insolent liar!\"', 'Is it that the advice has been cast upon him alone out of all of us? No, but he is a bragging liar.”'),
(4872, 54, 26, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'سَیَعۡلَمُوۡنَ غَدًا مَّنِ الۡکَذَّابُ الۡاَشِرُ ﴿۲۶﴾', 'انکو کل ہی معلوم ہو جائے گا کہ کون جھوٹا بڑائی مارنے والا ہے۔', 'اب جان لیں گے کل کو کون ہے جھوٹا بڑائی مارنے والا [۲۳]', 'Tomorrow they will come to know, who is the liar, the insolent one!', 'Tomorrow they will know who the bragging liar is!'),
(4873, 54, 27, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'اِنَّا  مُرۡسِلُوا النَّاقَۃِ  فِتۡنَۃً  لَّہُمۡ فَارۡتَقِبۡہُمۡ  وَ اصۡطَبِرۡ ﴿۫۲۷﴾', 'اے صالح  ہم انکی آزمائش کے لئے اونٹنی بھیجنے والے ہیں تو تم انکو دیکھتے رہو اور صبر کرو۔', 'ہم بھیجتے ہیں اونٹنی اُنکے جانچنے کے واسطے [۲۴] سو انتطار کر  اُن کا اور سہتا رہ [۲۵]', 'Verily, We are sending the she-camel as a test for them. So watch them (O Salih (Saleh) ), and be patient!', 'We are going to send the she-camel as a trial for them; so watch them (O SāliH,) and keep patience,'),
(4874, 54, 28, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ نَبِّئۡہُمۡ  اَنَّ  الۡمَآءَ  قِسۡمَۃٌۢ  بَیۡنَہُمۡ ۚ کُلُّ  شِرۡبٍ  مُّحۡتَضَرٌ ﴿۲۸﴾', 'اور انکو آگاہ کر دو کہ ان میں پانی کی باری مقرر کر دی گئ ہے۔ ہر باری والے کو اپنی باری پر آنا چاہیے۔', 'اور سنا دے اُنکو کہ پانی کا بانٹا ہے اُن میں ہر باری پر پہنچنا چاہئے [۲۶]', 'And inform them that the water is to be shared between (her and) them. Each ones right to drink being established (by turns).', 'and tell them that water (of the well) is to be shared between them (and the she-camel), so as the right of having water shall be attended by each (alternatively).'),
(4875, 54, 29, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'فَنَادَوۡا صَاحِبَہُمۡ  فَتَعَاطٰی فَعَقَرَ ﴿۲۹﴾', 'تو ان لوگوں نے اپنے رفیق کو بلایا اور اس نے اونٹنی کو پکڑ لیا پھر اسے مار ڈالا۔', 'پھر پکارا انہوں نے اپنے رفیق کو پھر ہاتھ چلایا اور کاٹ ڈالا [۲۷]', 'But they called their comrade and he took (a sword) and killed (her).', 'Then they called their man (to kill the she-camel,) so he undertook (the task) and killed (the she-camel).'),
(4876, 54, 30, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'فَکَیۡفَ کَانَ عَذَابِیۡ  وَ نُذُرِ ﴿۳۰﴾', 'سو دیکھ لو کہ میرا عذاب اور ڈرانا کیسا ہوا۔', 'پھر کیسا ہوا میرا عذاب اور میرا کھڑکھڑانا', 'Then, how (terrible) was My Torment and My Warnings?', 'So how was My torment and My warnings?'),
(4877, 54, 31, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'اِنَّاۤ  اَرۡسَلۡنَا عَلَیۡہِمۡ صَیۡحَۃً  وَّاحِدَۃً فَکَانُوۡا کَہَشِیۡمِ  الۡمُحۡتَظِرِ ﴿۳۱﴾', 'ہم نے ان پر عذاب کے لئے ایک زور کی آواز بھیجی تو وہ ایسے ہو گئے جیسے باڑ والے کی چورا چورا ہو جانے والی باڑ۔', 'ہم نے بھیجی اُن پر ایک چنگھاڑ پھر رہ گئے جیسے روندی ہوئی باڑ کانٹوں کی [۲۸]', 'Verily, We sent against them a single Saeehah (torment - awful cry, etc.), and they became like the dry stubble of a fold-builder.', 'We sent upon them a single Cry, and they were like crushed leafs of a hedge-builder.'),
(4878, 54, 32, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ لَقَدۡ یَسَّرۡنَا الۡقُرۡاٰنَ  لِلذِّکۡرِ فَہَلۡ مِنۡ مُّدَّکِرٍ  ﴿۳۲﴾', 'اور ہم نے قرآن کو سمجھنے کے لئے آسان کر دیا ہے تو کوئی ہے کہ سوچے سمجھے؟', 'اور ہم نے آسان کر دیا قرآن  سمجھنے کو پھر ہے کوئی سوچنے والا', 'And indeed, We have made the Quran easy to understand and remember, then is there any that will remember (or receive admonition)?', 'Indeed We have made the Qur’ān easy for seeking advice. So, is there one to heed to the advice?'),
(4879, 54, 33, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'کَذَّبَتۡ قَوۡمُ لُوۡطٍۭ بِالنُّذُرِ ﴿۳۳﴾', 'لوط کی قوم نے بھی ڈر سنانے والوں کو جھٹلایا تھا۔', 'جھٹلایا لوط کی قوم نے ڈر سنانے والے کو [۲۹]', 'The people of Lout (Lot) belied the warnings.', 'The people of LūT rejected the warners.'),
(4880, 54, 34, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'اِنَّاۤ  اَرۡسَلۡنَا عَلَیۡہِمۡ حَاصِبًا  اِلَّاۤ  اٰلَ لُوۡطٍ ؕ نَجَّیۡنٰہُمۡ  بِسَحَرٍ ﴿ۙ۳۴﴾', 'تو ہم نے ان پر کنکر بھری ہوا چلائی مگر لوط کے گھر والے کہ ہم نے انکو پچھلی رات کے وقت بچا لیا۔', 'ہم نے بھیجی اُن پر آندھی پتھر برسانے والی سوائے لوط کے گھر کے انکو ہم نے بچا دیا پچھلی رات سے', 'Verily, We sent against them a violent storm of stones (which destroyed them all), except the family of Lout (Lot), whom We saved in last hour of the night,', 'We sent upon them a rain of stones, except the family of LūT whom We saved in the last hours of night,'),
(4881, 54, 35, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'نِّعۡمَۃً  مِّنۡ عِنۡدِنَا ؕ  کَذٰلِکَ نَجۡزِیۡ مَنۡ شَکَرَ ﴿۳۵﴾', 'اپنے فضل سے شکر کرنے والوں کو ہم ایسا ہی بدلہ دیا کرتے ہیں۔', 'فضل سے اپنی طرف کے ہم یوں بدلا دیتے ہیں اسکو جو حق مانے [۳۰]', 'As a Favour from Us, thus do We reward him who gives thanks (by obeying Us).', 'as a grace from Us. This is how We reward the one who offers gratitude.'),
(4882, 54, 36, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ لَقَدۡ  اَنۡذَرَہُمۡ بَطۡشَتَنَا فَتَمَارَوۡا بِالنُّذُرِ ﴿۳۶﴾', 'اور لوط نے انکو ہماری پکڑ سے ڈرا بھی دیا تھا مگر انہوں نے ڈرانے میں شک کیا۔', 'اور وہ ڈرا چکا تھا اُنکو ہماری پکڑ سے پھر لگے مکرانے ڈرانے کو [۳۱]', 'And he (Lout (Lot)) indeed had warned them of Our Grasp, but they did doubt the warnings!', 'And he (LūT) had certainly warned them of Our grasp, but they disputed the warnings.'),
(4883, 54, 37, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ لَقَدۡ رَاوَدُوۡہُ  عَنۡ ضَیۡفِہٖ  فَطَمَسۡنَاۤ اَعۡیُنَہُمۡ  فَذُوۡقُوۡا عَذَابِیۡ  وَ  نُذُرِ ﴿۳۷﴾', 'اور ان سے انکے مہمانوں کو لے لینا چاہا۔ تو ہم نے انکی آنکھیں مٹا دیں سو اب میرے عذاب اور ڈرانے کے مزے چکھو۔', 'اور اُس سے لینے لگے اُسکے مہمانوں کو پس ہم نے مٹا دیں اُن کی آنکھیں اب چکھو میرا عذاب اور ڈرانا [۳۲]', 'And they indeed sought to shame his guest (by asking to commit sodomy with them). So We blinded their eyes, \"Then taste you My Torment and My Warnings.\"', 'And they had even tried to tempt him against his guests (so that they may snatch them away for bad purpose,) but We blinded their eyes: “Now taste My torment and My warnings!”'),
(4884, 54, 38, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ لَقَدۡ صَبَّحَہُمۡ  بُکۡرَۃً عَذَابٌ مُّسۡتَقِرٌّ ﴿ۚ۳۸﴾', 'اور ان پر صبح سویرے ہی ٹھہر جانے والا عذاب آ نازل ہوا۔', 'اور پڑ ا اُن پر صبح کو سویرے عذاب جو ٹھہر چکا تھا', 'And verily, an abiding torment seized them early in the morning.', 'And on the next morning, a lasting torment overtook them:'),
(4885, 54, 39, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'فَذُوۡقُوۡا عَذَابِیۡ  وَ نُذُرِ ﴿۳۹﴾', 'تو اب میرے عذاب اور ڈراوں کے مزے چکھو۔', 'اب چکھو میرا عذاب اور میرا ڈرانا [۳۳]', '\"Then taste you My Torment and My Warnings.\"', '“Now taste My torment and My warnings.”'),
(4886, 54, 40, 2, 9, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ لَقَدۡ یَسَّرۡنَا الۡقُرۡاٰنَ  لِلذِّکۡرِ فَہَلۡ مِنۡ مُّدَّکِرٍ ﴿٪۴۰﴾', 'اور ہم نے قرآن کو سمجھنے کے لئے آسان کر دیا ہے تو کوئی ہے کہ سوچے سمجھے؟', 'اور ہم نے آسان کر دیا قرآن سمجھنے کو پھر ہے کوئی سوچنے والا', 'And indeed, We have made the Quran easy to understand and remember, then is there any that will remember (or receive admonition)?', 'Indeed We have made the Qur’ān easy for seeking advice. So, is there one to heed to the advice?'),
(4887, 54, 41, 3, 10, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ  لَقَدۡ جَآءَ   اٰلَ  فِرۡعَوۡنَ  النُّذُرُ ﴿ۚ۴۱﴾', 'اور قوم فرعون کے پاس بھی ڈر سنانے والے آئے تھے۔', 'اور پہنچے فرعون والوں کے پاس ڈرانے والے [۳۴]', 'And indeed, warnings came to the people of Firaun (Pharaoh) (through Moosa (Moses) and Haroon (Aaron)).', 'And the warners came to the family of Fir‘aun (Pharaoh).'),
(4888, 54, 42, 3, 10, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'کَذَّبُوۡا بِاٰیٰتِنَا کُلِّہَا فَاَخَذۡنٰہُمۡ  اَخۡذَ عَزِیۡزٍ  مُّقۡتَدِرٍ ﴿۴۲﴾', 'انہوں نے ہماری تمام نشانیوں کو جھٹلایا تو ہم نے انکو اس طرح پکڑ لیا جس طرح ایک قوی اور غالب شخص پکڑ لیتا ہے۔', 'جھٹلایا انہوں نے ہماری نشانیوں کو سب کو پھر پکڑا ہم نے انکو پکڑنا زبردست کا قابو میں لے کر [۳۵]', '(They) belied all Our Signs, so We seized them with a Seizure of the All-Mighty, All-Capable to carry out what he Will (Omnipotent).', '(But) they rejected all Our signs; so We seized them- a seizure by One Mighty, Powerful.'),
(4889, 54, 43, 3, 10, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'اَکُفَّارُکُمۡ خَیۡرٌ مِّنۡ اُولٰٓئِکُمۡ اَمۡ لَکُمۡ  بَرَآءَۃٌ  فِی الزُّبُرِ ﴿ۚ۴۳﴾', 'اے اہل عرب کیا تمہارے کافر ان لوگوں سے بہتر ہیں یا تمہارے لئے پہلی کتابوں میں عذاب سے کوئی چھٹکارا لکھ دیا گیا ہے؟', 'اب تم میں جو منکر ہیں کیا یہ بہتر ہیں اُن سب سے یا تمہارے لئے فارغ خطی لکھدی گئ ورقوں میں', 'Are your disbelievers (O Quraish!) better than these (nations of Nooh (Noah), Lout (Lot), Salih (Saleh), and the people of Firaun (Pharaoh), etc., who were destroyed)? Or have you an immunity (against Our Torment) in the Divine Scriptures?', 'Are the disbelievers among you in a better position than all of the aforesaid (punished people), or do you have immunity (recorded) in the sacred books?'),
(4890, 54, 44, 3, 10, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'اَمۡ  یَقُوۡلُوۡنَ نَحۡنُ جَمِیۡعٌ مُّنۡتَصِرٌ ﴿۴۴﴾', 'کیا یہ لوگ کہتے ہیں کہ ہماری جماعت بڑی مضبوط ہے؟', 'کیا کہتے ہیں ہم سب کا مجمع ہے بدلا لینے والا [۳۶]', 'Or do they say: \"We are a great multitude, and we shall be victorious.?\"', 'Or do they say, “We are a large group, well-defended.”?'),
(4891, 54, 45, 3, 10, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'سَیُہۡزَمُ الۡجَمۡعُ وَ  یُوَلُّوۡنَ الدُّبُرَ ﴿۴۵﴾', 'عنقریب یہ جماعت شکست کھائے گی اور یہ لوگ پیٹھ پھیر پھیر کر بھاگ جائیں گے۔', 'اب شکست کھائے گا یہ مجمع اور بھاگیں گے پیٹھ پھیر کر [۳۷]', 'Their multitude will be put to flight, and they will show their backs.', 'Soon this ‘large group’ shall be defeated, and all of them will turn their backs.'),
(4892, 54, 46, 3, 10, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'بَلِ السَّاعَۃُ  مَوۡعِدُہُمۡ وَ السَّاعَۃُ اَدۡہٰی  وَ  اَمَرُّ ﴿۴۶﴾', 'اصل میں انکے وعدے کا وقت تو قیامت ہے اور قیامت بڑی سخت اور بہت تلخ ہو گی۔', 'بلکہ قیامت ہے اُنکے وعدہ کا وقت اور وہ گھڑی بڑی آفت ہے اور بہت کڑوی [۳۸]', 'Nay, but the Hour is their appointed time (for their full recompense), and the Hour will be more grievous and more bitter.', 'Rather the Hour (of judgment) is their appointed time (for their full recompense), and the Hour is more calamitous and much more bitter.'),
(4893, 54, 47, 3, 10, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'اِنَّ  الۡمُجۡرِمِیۡنَ فِیۡ ضَلٰلٍ وَّ سُعُرٍ ﴿ۘ۴۷﴾', 'بیشک گنہگار لوگ گمراہی اور دیوانگی میں مبتلا ہیں۔', 'جو لوگ گنہگار ہیں غلطی میں پڑے ہیں اور سودا میں', 'Verily, the Mujrimoon (polytheists, disbelievers, sinners, criminals, etc.) are in error (in this world) and will burn (in the Hell-fire in the Hereafter).', 'Surely the guilty ones are in error and madness.'),
(4894, 54, 48, 3, 10, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'یَوۡمَ یُسۡحَبُوۡنَ فِی النَّارِ عَلٰی وُجُوۡہِہِمۡ ؕ ذُوۡقُوۡا مَسَّ سَقَرَ ﴿۴۸﴾', 'اس روز منہ کے بل دوزخ میں گھسیٹے جائیں گے کہا جائے گا لو اب آگ کا مزہ چکھو۔', 'جس دن گھسیٹے جائیں گے آگ میں اوندھے منہ چکھو مزا آگ کا [۳۹]', 'The Day they will be dragged in the Fire on their faces (it will be said to them): \"Taste you the touch of Hell!\"', 'On the Day when they will be dragged into the Fire on their faces, (it will be said to them,) “Taste the touch of Hell.”'),
(4895, 54, 49, 3, 10, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'اِنَّا کُلَّ  شَیۡءٍ  خَلَقۡنٰہُ  بِقَدَرٍ ﴿۴۹﴾', 'ہم نے ہر چیز اندازہ مقرر کے ساتھ پیدا کی ہے۔', 'ہم نے ہر چیز بنائی پہلے ٹھہرا کر [۴۰]', 'Verily, We have created all things with Qadar (Divine Preordainments of all things before their creation, as written in the Book of Decrees Al-Lauh Al-Mahfooz).', 'Verily, We have created every thing according to (Our) predestination.'),
(4896, 54, 50, 3, 10, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ مَاۤ  اَمۡرُنَاۤ  اِلَّا وَاحِدَۃٌ  کَلَمۡحٍۭ بِالۡبَصَرِ ﴿۵۰﴾', 'اور ہمارا حکم تو آنکھ کے جھپکنے کی طرح ایک بات ہوتی ہے۔', 'اور ہمارا کام تو یہی ایک دم کی بات ہے جیسے لپک نگاہ کی [۴۱]', 'And Our Commandment is but one, as the twinkling of an eye.', 'And (implementation of) Our command is no more than a single act like the twinkling of an eye.'),
(4897, 54, 51, 3, 10, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ لَقَدۡ  اَہۡلَکۡنَاۤ   اَشۡیَاعَکُمۡ  فَہَلۡ مِنۡ مُّدَّکِرٍ ﴿۵۱﴾', 'اور ہم تمہارے ہم مذہبوں کو ہلاک کر چکے ہیں تو کوئی ہے کہ سوچے سمجھے؟', 'اور ہم برباد کر چکے ہیں تمہارے ساتھ والوں کو پھر ہے کوئی سوچنے والا [۴۲]', 'And indeed, We have destroyed your likes, then is there any that will remember (or receive admonition)?', 'We have destroyed people like you; so, is there one to take lesson?'),
(4898, 54, 52, 3, 10, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ کُلُّ شَیۡءٍ  فَعَلُوۡہُ  فِی  الزُّبُرِ ﴿۵۲﴾', 'اور جو کچھ انہوں نے کیا انکے اعمال ناموں میں درج ہے۔', 'اور جو چیز انہوں نے کی ہے لکھی گئ ورقوں میں [۴۳]', 'And each and everything they have done is noted in (their) Records (of deeds).', 'And every thing they have done is recorded in the books (of deeds).'),
(4899, 54, 53, 3, 10, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'وَ کُلُّ صَغِیۡرٍ  وَّ کَبِیۡرٍ  مُّسۡتَطَرٌ ﴿۵۳﴾', 'یعنی ہر چھوٹا اور بڑا کام لکھ لیا گیا ہے۔', 'اور ہر چھوٹا اور بڑا لکھا جا چکا [۴۴]', 'And everything, small and big is written (in Al-Lauh Al-Mahfooz already beforehand i.e. before it befalls, or is done by its doer ÇáÇíä ÈÇáÞÏÑ) (See the Quran V.57:22).', 'And every thing, small and big, is written down.'),
(4900, 54, 54, 3, 10, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'اِنَّ الۡمُتَّقِیۡنَ فِیۡ جَنّٰتٍ وَّ نَہَرٍ ﴿ۙ۵۴﴾', 'جو پرہیزگار ہیں وہ باغوں اور نہروں میں ہوں گے۔', 'جو لوگ ڈرنے والے ہیں باغوں میں ہیں اور نہروں میں', 'Verily, The Muttaqoon (pious), will be in the midst of Gardens and Rivers (Paradise).', 'Of course, the God-fearing will be in gardens and rivers,'),
(4901, 54, 55, 3, 10, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'القمر', 'فِیۡ مَقۡعَدِ صِدۡقٍ عِنۡدَ مَلِیۡکٍ مُّقۡتَدِرٍ ﴿٪۵۵﴾', 'یعنی سچی بیٹھک میں ہر طرح کی قدرت رکھنے والے بادشاہ کی بارگاہ میں۔', 'بیٹھے سچی بیٹھک میں نزدیک بادشاہ کے جس کا سب پر قبضہ ہے [۴۵]', 'In a seat of truth (i.e. Paradise), near the Omnipotent King (Allah, the All-Blessed, the Most High, the Owner of Majesty and Honour).', 'in a seat of Truth, near to the Omnipotent Sovereign.'),
(4902, 55, 1, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'اَلرَّحۡمٰنُ ۙ﴿۱﴾', 'وہ جو نہایت مہربان ہے۔', 'رحمٰن نے', 'The Most Beneficent (Allah)!', 'The RaHmān (The All-Merciful Allah)'),
(4903, 55, 2, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'عَلَّمَ  الۡقُرۡاٰنَ ؕ﴿۲﴾', 'اسی نے قرآن کی تعلیم فرمائی۔', 'سکھلایا قرآن [۱]', 'Has taught (you mankind) the Quran (by His Mercy).', 'has taught the Qur’ān.'),
(4904, 55, 3, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'خَلَقَ  الۡاِنۡسَانَ ۙ﴿۳﴾', 'اسی نے انسان کو پیدا کیا۔', 'بنایا آدمی', 'He created man.', 'He has created man.'),
(4905, 55, 4, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'عَلَّمَہُ  الۡبَیَانَ ﴿۴﴾', 'اسی نے اسکو بولنا سکھایا۔', 'پھر سکھلایا اُسکو بات کرنا [۲]', 'He taught him eloquent speech.', 'He has taught him (how) to express himself.'),
(4906, 55, 5, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'اَلشَّمۡسُ وَ الۡقَمَرُ  بِحُسۡبَانٍ ﴿۪۵﴾', 'سورج اور چاند ایک حساب مقرر سے چل رہے ہیں۔', 'سورج اور چاند کیلئے ایک حساب ہے [۳]', 'The sun and the moon run on their fixed courses (exactly) calculated with measured out stages for each (for reckoning, etc.).', 'The sun and the moon are (bound) by a (fixed) calculation.'),
(4907, 55, 6, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'وَّ النَّجۡمُ وَ الشَّجَرُ  یَسۡجُدٰنِ ﴿۶﴾', 'اور بوٹیاں اور درخت سجدہ کر رہے ہیں۔', 'اور جھاڑ اور درخت مشغول ہیں سجدہ میں [۴]', 'And the herbs (or stars) and the trees both prostrate.', 'And the vine and the tree both prostrate (to Allah).'),
(4908, 55, 7, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'وَ السَّمَآءَ رَفَعَہَا وَ وَضَعَ الۡمِیۡزَانَ ۙ﴿۷﴾', 'اور اسی نے آسمان کو بلند کیا اور میزان عدل قائم کر دی۔', 'اور آسمان کو اونچا کیا اور رکھی ترازو', 'And the heaven He has raised high, and He has set up the Balance.', 'He raised the sky high, and has placed the scale,'),
(4909, 55, 8, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'اَلَّا  تَطۡغَوۡا فِی الۡمِیۡزَانِ ﴿۸﴾', 'کہ اس میزان میں حد سے تجاوز نہ کرو۔', 'کہ زیادتی نہ کرو ترازو میں', 'In order that you may not transgress (due) balance.', 'so that you should not be wrongful in weighing.'),
(4910, 55, 9, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'وَ اَقِیۡمُوا  الۡوَزۡنَ بِالۡقِسۡطِ وَ لَا تُخۡسِرُوا الۡمِیۡزَانَ ﴿۹﴾', 'اور انصاف کے ساتھ ٹھیک تولو اور تول کم مت کرو۔', 'اور سیدھی ترازو تولو انصاف سے اور مت گھٹاؤ تول کو [۵]', 'And observe the weight with equity and do not make the balance deficient.', 'Observe the correct weight with fairness, and do not make weighing deficient.'),
(4911, 55, 10, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'وَ الۡاَرۡضَ وَضَعَہَا لِلۡاَنَامِ ﴿ۙ۱۰﴾', 'اور اسی نے خلقت کے لئے زمین بچھائی۔', 'اور زمین کو بچھایا واسطے خلق کے [۶]', 'And the earth He has put for the creatures.', 'As for the earth, He has placed it for creatures,'),
(4912, 55, 11, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فِیۡہَا فَاکِہَۃٌ ۪ۙ  وَّ النَّخۡلُ  ذَاتُ الۡاَکۡمَامِ ﴿ۖ۱۱﴾', 'اس میں میوے اور کھجور کے درخت ہیں جنکے خوشوں پر غلاف ہوتے ہیں۔', 'اس میں میوہ ہے اور کھجوریں جنکے میوہ پر غلاف', 'Therein are fruits, date-palms producing sheathed fruit-stalks (enclosing dates).', 'in which there are fruits and date palms having sheaths,'),
(4913, 55, 12, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'وَ الۡحَبُّ ذُو الۡعَصۡفِ وَ الرَّیۡحَانُ ﴿ۚ۱۲﴾', 'اور اناج جسکے ساتھ بھس ہوتا ہے اور خوشبودار پھول۔', 'اور اُس میں اناج ہے جسکے ساتھ بھُس ہے اور پھول خوشبودار [۷]', 'And also corn, with (its) leaves and stalk for fodder, and sweet-scented plants.', 'and the grain having chaff, and fragrant flowers.'),
(4914, 55, 13, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۱۳﴾', 'تو اے گروہ جن و انس تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں رب اپنے کی جھٹلاؤ گے تم دونوں [۸]', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, (O mankind and Jinn,) which of the bounties of your Lord will you deny?'),
(4915, 55, 14, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'خَلَقَ الۡاِنۡسَانَ مِنۡ صَلۡصَالٍ کَالۡفَخَّارِ ﴿ۙ۱۴﴾', 'اسی نے انسان کو ٹھیکرے کی طرح کھنکھناتی مٹی سے بنایا۔', 'بنایا آدمی کو کھنکھناتی مٹی سے جیسے ٹھیکرا', 'He created man (Adam) from sounding clay like the clay of pottery.', 'He has created man from dry clay, ringing like pottery,'),
(4916, 55, 15, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'وَ  خَلَقَ  الۡجَآنَّ مِنۡ مَّارِجٍ  مِّنۡ نَّارٍ ﴿ۚ۱۵﴾', 'اور جنات کو آگ کے شعلے سے پیدا کیا۔', 'اور بنایا جن کو  آگ کی لپٹ سے [۹]', 'And the jinns did He create from a smokeless flame of fire.', 'and created Jann (father of the Jinn) from a smokeless flame of fire.'),
(4917, 55, 16, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۱۶﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں رب اپنے کی جھٹلاؤ گے تم دونوں [۱۰]', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, (O mankind and Jinn,) which of the bounties of your Lord will you deny?'),
(4918, 55, 17, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'رَبُّ الۡمَشۡرِقَیۡنِ وَ رَبُّ الۡمَغۡرِبَیۡنِ ﴿ۚ۱۷﴾', 'وہی دونوں مشرقوں اور دونوں مغربوں کا مالک ہے۔', 'مالک دو مشرق کا اور مالک دو مغرب کا [۱۱]', '(He is) the Lord of the two easts (places of sunrise during early summer and early winter) and the Lord of the two wests (places of sunset during early summer and early winter).', 'He is the Lord of both points of sunrise and both points of sunset.'),
(4919, 55, 18, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۱۸﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4920, 55, 19, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'مَرَجَ  الۡبَحۡرَیۡنِ یَلۡتَقِیٰنِ ﴿ۙ۱۹﴾', 'اسی نے دو دریا رواں کئے جو آپس میں ملتے ہیں۔', 'دو دریا مل کر چلنے والے', 'He has let loosed the two seas (the salt water and the sweet) meeting together.', 'He let forth the two seas to meet together,'),
(4921, 55, 20, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'بَیۡنَہُمَا بَرۡزَخٌ  لَّا  یَبۡغِیٰنِ ﴿ۚ۲۰﴾', 'مگر دونوں میں ایک آڑ ہے کہ اس سے تجاوز نہیں کر سکتے۔', 'اُن دونوں میں ہے ایک پر وہ جو ایک دوسرے پر زیادتی نہ کرے [۱۲]', 'Between them is a barrier which none of them can transgress.', 'while there is a barrier between them; they do not encroach (upon one another).'),
(4922, 55, 21, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۲۱﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4923, 55, 22, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'یَخۡرُجُ مِنۡہُمَا اللُّؤۡلُؤُ  وَ الۡمَرۡجَانُ ﴿ۚ۲۲﴾', 'ان دونوں دریاؤں سے موتی اور مونگے نکلتے ہیں۔', 'نکلتا ہے اُن دونوں سے موتی اورمونگا', 'Out of them both come out pearl and coral.', 'From both of them come forth the pearl and the coral.'),
(4924, 55, 23, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۲۳﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4925, 55, 24, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'وَ لَہُ  الۡجَوَارِ الۡمُنۡشَئٰتُ فِی الۡبَحۡرِ کَالۡاَعۡلَامِ ﴿ۚ۲۴﴾', 'اور جہاز بھی اسی کے ہیں جو سمندر میں پہاڑوں کی طرح اونچے کھڑے ہوتے ہیں۔', 'اور اُسی کے ہیں جہاز اونچے کھڑے دریا میں جیسے پہاڑ [۱۳]', 'And His are the ships going and coming in the seas, like mountains.', 'And His are the sailing ships raised up in the sea like mountains.'),
(4926, 55, 25, 1, 11, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿٪۲۵﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4927, 55, 26, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'کُلُّ  مَنۡ  عَلَیۡہَا  فَانٍ ﴿ۚۖ۲۶﴾', 'جو مخلوق زمین پر ہے سب کو فنا ہونا ہے۔', 'جو کوئی ہے زمین پر فنا ہونے والا ہے', 'Whatsoever is on it (the earth) will perish.', 'Every one who is on it (the earth) has to perish.'),
(4928, 55, 27, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'وَّ یَبۡقٰی وَجۡہُ  رَبِّکَ ذُو الۡجَلٰلِ وَ الۡاِکۡرَامِ ﴿ۚ۲۷﴾', 'اور تمہارے پروردگار ہی کی ذات جو صاحب جلال و کرم ہے باقی رہے گی۔', 'اور باقی رہے گا منہ تیرےرب کا بزرگی اور عظمت والا [۱۴]', 'And the Face of your Lord full of Majesty and Honour will abide forever.', 'And your Lord’s Countenance will remain, full of majesty, full of honour.'),
(4929, 55, 28, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۲۸﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4930, 55, 29, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'یَسۡـَٔلُہٗ  مَنۡ  فِی السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ کُلَّ  یَوۡمٍ ہُوَ  فِیۡ  شَاۡنٍ ﴿ۚ۲۹﴾', 'آسمان اور زمین میں جتنے لوگ ہیں سب اسی سے مانگتے ہیں۔ وہ ہر روز کسی نہ کسی کام میں ہوتا ہے۔', 'اُس سے مانگتے ہیں جو کوئی ہیں آسمانوں میں اور زمین میں ہر روز اُس کو ایک دھندا ہے [۱۵]', 'Whosoever is in the heavens and on earth begs of Him (its needs from Him). Every day He has a matter to bring forth (such as giving honour to some, disgrace to some, life to some, death to some, etc.)!', 'All those in the heavens and the earth beseech Him (for their needs.) Every day He is in a state of action.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(4931, 55, 30, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۳۰﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4932, 55, 31, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'سَنَفۡرُغُ   لَکُمۡ  اَیُّہَ  الثَّقَلٰنِ ﴿ۚ۳۱﴾', 'اے دونوں جماعتو! ہم عنقریب تمہاری طرف متوجہ ہوتے ہیں۔', 'ہم جلد فارغ ہونے والے ہیں تمہارے طرف اے دو بھاری قافلو', 'We shall attend to you, O you two classes (jinns and men)!', 'Soon We are going to spare Ourselves for you (to reckon your deeds), O two heavy species (of Jinn and mankind)!'),
(4933, 55, 32, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۳۲﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4934, 55, 33, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'یٰمَعۡشَرَ الۡجِنِّ وَ الۡاِنۡسِ  اِنِ اسۡتَطَعۡتُمۡ اَنۡ  تَنۡفُذُوۡا مِنۡ  اَقۡطَارِ السَّمٰوٰتِ وَ الۡاَرۡضِ فَانۡفُذُوۡا ؕ لَا  تَنۡفُذُوۡنَ  اِلَّا بِسُلۡطٰنٍ ﴿ۚ۳۳﴾', 'اے گروہ جن و انس اگر تمہیں قدرت ہو کہ آسمان اور زمین کے کناروں سے نکل جاؤ تو نکل جاؤ اور زور کے سوا تو تم نکل سکنے ہی کے نہیں۔', 'اور گروہ جنوں کے اور انسانوں کے اگر تم سے ہو سکے کہ نکل بھاگو آسمانوں اور زمین کے کناروں سے تو نکل بھاگو نہیں نکل سکنے کےبدون سند کے [۱۶]', 'O assembly of jinns and men! If you have power to pass beyond the zones of the heavens and the earth, then pass (them)! But you will never be able to pass them, except with authority (from Allah)!', 'O genera of Jinn and mankind, If you are able to penetrate beyond the realms of the heavens and the earth, then penetrate. You cannot penetrate without power.'),
(4935, 55, 34, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۳۴﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے [۱۷]', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4936, 55, 35, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'یُرۡسَلُ عَلَیۡکُمَا شُوَاظٌ مِّنۡ نَّارٍ ۬ۙ وَّ نُحَاسٌ فَلَا  تَنۡتَصِرٰنِ ﴿ۚ۳۵﴾', 'تم پر آگ کے شعلے صاف اور دھواں ملے چھوڑ دیئے جائیں گے تو پھر تم انکا مقابلہ نہ کر سکو گے۔', 'چھوڑے جائیں تم پر شعلے آگ  کے صاف اور دھواں ملے ہوئے پھر تم بدلہ نہیں لے سکتے [۱۸]', 'There will be sent against you both, smokeless flames of fire and (molten) brass, and you will not be able to defend yourselves.', 'A flame of fire and a smoke will be loosed against you, and you will not (be able) to defend.'),
(4937, 55, 36, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۳۶﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے [۱۹]', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4938, 55, 37, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَاِذَا  انۡشَقَّتِ السَّمَآءُ  فَکَانَتۡ وَرۡدَۃً کَالدِّہَانِ ﴿ۚ۳۷﴾', 'پھر جب آسمان پھٹ کر تیل کی تلچھٹ کی طرح گلابی ہو جائے گا تو وہ کیسا ہولناک دن ہوگا۔', 'پھر جب پھٹ جائے آسمان تو ہو جائے گلابی جیسے نری (تیل کی تلچھٹ) [۲۰]', 'Then when the heaven is rent asunder, and it becomes rosy or red like red-oil, or red hide.', 'So, (it will be a terrible event) when the sky will be split apart and will become rosy, like (red) hides.'),
(4939, 55, 38, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۳۸﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4940, 55, 39, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَیَوۡمَئِذٍ لَّا یُسۡـَٔلُ عَنۡ ذَنۡۢبِہٖۤ  اِنۡسٌ وَّ لَا  جَآنٌّ ﴿ۚ۳۹﴾', 'تو اس روز نہ تو کسی انسان سے اسکے گناہوں کے بارے میں پرسش کی جائے گی اور نہ کسی جن سے۔', 'پھر اُس دن پوچھ نہیں اُس کے گناہ کی کسی آدمی سے اور نہ جن سے [۲۱]', 'So on that Day no question will be asked of man or jinn as to his sin, (because they have already been known from their faces either white or black).', 'On that day, neither a man will be questioned about his sin, nor a Jinn.'),
(4941, 55, 40, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۴۰﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4942, 55, 41, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'یُعۡرَفُ الۡمُجۡرِمُوۡنَ بِسِیۡمٰہُمۡ فَیُؤۡخَذُ بِالنَّوَاصِیۡ وَ الۡاَقۡدَامِ ﴿ۚ۴۱﴾', 'گنہگار اپنے چہرے ہی سے پہچان لئے جائیں گے تو پیشانی کے بالوں اور پاؤں سے پکڑ لئے جائیں گے۔', 'پہنچانے پڑیں گے گنہگار اپنے چہرے سے [۲۲] پھر پکڑ ا جائے گا پیشانی کے بال سے اور پاؤں سے [۲۳]', 'The Mujrimoon (polytheists, criminals, sinners, etc.) will be known by their marks (black faces), and they will be seized by their forelocks and their feet.', 'The guilty ones will be recognized (by angels) through their marks and will be seized by foreheads and feet.'),
(4943, 55, 42, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۴۲﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4944, 55, 43, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'ہٰذِہٖ جَہَنَّمُ  الَّتِیۡ یُکَذِّبُ بِہَا الۡمُجۡرِمُوۡنَ ﴿ۘ۴۳﴾', 'یہی وہ جہنم ہے جسے گنہگار لوگ جھٹلاتے تھے۔', 'یہ دوزخ ہے جسکو جھوٹ بتاتے تھے گنہگار [۲۴]', 'This is Hell which the Mujrimoon (polytheists, criminals, sinners, etc.) denied.', 'This is Jahannam (Hell) that the guilty people deny.'),
(4945, 55, 44, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'یَطُوۡفُوۡنَ بَیۡنَہَا وَ  بَیۡنَ حَمِیۡمٍ  اٰنٍ ﴿ۚ۴۴﴾', 'وہ دوزخ اور کھولتے ہوئے گرم پانی کے درمیان گھومتے پھریں گے۔', 'پھریں گے بیچ اُس کے اور کھولتے پانی کے [۲۵]', 'They will go between it (Hell) and the boiling hot water!', 'They will circle around between it and between hot, boiling water.'),
(4946, 55, 45, 2, 12, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿٪۴۵﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4947, 55, 46, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'وَ  لِمَنۡ خَافَ مَقَامَ  رَبِّہٖ  جَنَّتٰنِ ﴿ۚ۴۶﴾', 'اور جو شخص اپنے پروردگار کے سامنے کھڑے ہونے سے ڈرا اسکے لئے دو باغ ہیں۔', 'اور جو کوئی ڈرا کھڑے ہونے سے اپنے رب کے آگے اُسکے لئے ہیں دو باغ [۲۶]', 'But for him who (the true believer of Islamic Monotheism who performs all the duties ordained by Allah and His Messenger Muhammad SAW , and keeps away (abstain) from all kinds of sin and evil deeds prohibited in Islam and) fears the standing before his Lord, there will be two Gardens (i.e. in Paradise).', 'And for the one who is fearful of having to stand before his Lord, there are two gardens, -'),
(4948, 55, 47, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿ۙ۴۷﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4949, 55, 48, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'ذَوَاتَاۤ   اَفۡنَانٍ ﴿ۚ۴۸﴾', 'ان دونوں میں بہت سی شاخیں یعنی قسم قسم کے میووں کے درخت ہیں۔', 'جن میں بہت سی شاخیں [۲۷]', 'With spreading branches;', '- both having branches.'),
(4950, 55, 49, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۴۹﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4951, 55, 50, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فِیۡہِمَا عَیۡنٰنِ  تَجۡرِیٰنِ ﴿ۚ۵۰﴾', 'ان میں دو چشمے بہ رہے ہیں۔', 'اُن دونوں میں دو چشمے بہتے ہیں [۲۸]', 'In them (both) will be two springs flowing (free)', 'In both there are two flowing springs.'),
(4952, 55, 51, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۵۱﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4953, 55, 52, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فِیۡہِمَا مِنۡ کُلِّ  فَاکِہَۃٍ  زَوۡجٰنِ ﴿ۚ۵۲﴾', 'ان میں سب میوے دو دو قسم کے ہیں۔', 'اُن دونوں میں ہر میوہ قسم قسم کا ہو گا', 'In them (both) will be every kind of fruit in pairs.', 'In both there are two kinds of every fruit.'),
(4954, 55, 53, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۵۳﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4955, 55, 54, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'مُتَّکِـِٕیۡنَ عَلٰی فُرُشٍۭ بَطَآئِنُہَا مِنۡ اِسۡتَبۡرَقٍ ؕ وَ  جَنَا  الۡجَنَّتَیۡنِ  دَانٍ ﴿ۚ۵۴﴾', 'اہل جنت ایسے بچھونوں پر جنکے استر اطلس کے ہیں تکیہ لگائے ہوئے ہوں گے۔ اور دونوں باغوں کے میوے قریب جھک رہے ہیں۔', 'تکیہ لگائے بیٹھے بچھونوں پر جن کے استر تافتے کے [۲۹] اور میوہ اُن باغوں کا جھک رہا  [۳۰]', 'Reclining upon the couches lined with silk brocade, and the fruits of the two Gardens will be near at hand.', '(The people of these gardens will be) reclining on floorings whose (even) linings will be of thick silk, and the fruits plucked from the two gardens will be at hand.'),
(4956, 55, 55, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۵۵﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4957, 55, 56, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فِیۡہِنَّ قٰصِرٰتُ الطَّرۡفِ ۙ لَمۡ  یَطۡمِثۡہُنَّ اِنۡسٌ قَبۡلَہُمۡ  وَ لَا  جَآنٌّ ﴿ۚ۵۶﴾', 'ان میں نیچی نگاہ والی عورتیں ہیں جنکو اہل جنت سے پہلے نہ کسی انسان نے ہاتھ لگایا اور نہ کسی جن نے۔', 'اُن میں عورتیں ہیں نیچی نگاہ والیاں نہیں قربت کی اُن سے کسی آدمی نے اُن سے پہلے اور نہ کسی جن نے [۳۱]', 'Wherein both will be those (maidens) restraining their glances upon their husbands, whom no man or jinn yatmithhunna (has opened their hymens with sexual intercourse) before them.', 'In them there will be maidens restraining (their) glances, whom neither a man might have touched before them, nor a Jinn.'),
(4958, 55, 57, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿ۚ۵۷﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4959, 55, 58, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'کَاَنَّہُنَّ الۡیَاقُوۡتُ  وَ الۡمَرۡجَانُ ﴿ۚ۵۸﴾', 'گویا وہ یاقوت اور مرجان ہیں۔', 'وہ کیسی جیسےکہ لعل اور مُونگا [۳۲]', '(In beauty) they are like rubies and coral.', 'They will look like rubies and corals.'),
(4960, 55, 59, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۵۹﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4961, 55, 60, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'ہَلۡ جَزَآءُ  الۡاِحۡسَانِ  اِلَّا الۡاِحۡسَانُ ﴿ۚ۶۰﴾', 'نیکی کا بدلہ نیکی کے سوا کچھ نہیں ہے؟', 'اور کیا بدلا ہے نیکی کا مگر نیکی [۳۳]', 'Is there any reward for good other than good?', 'Is there any reward for goodness other than goodness?'),
(4962, 55, 61, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۶۱﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4963, 55, 62, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'وَ مِنۡ دُوۡنِہِمَا جَنَّتٰنِ ﴿ۚ۶۲﴾', 'اور ان باغوں کے علاوہ دو باغ اور ہیں۔', 'اور اُن دو کے سوائے اور دو  باغ ہیں [۳۴]', 'And besides these two, there are two other Gardens (i.e. in Paradise).', 'And besides these two, there are two other gardens (for the second category of the God-fearing),-'),
(4964, 55, 63, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿ۙ۶۳﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4965, 55, 64, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'مُدۡہَآ  مَّتٰنِ  ﴿ۚ۶۴﴾', 'دونوں خوب گہرے سبز۔', 'گہرے سبز جیسے سیاہ [۳۵]', 'Dark green (in colour).', '- both (gardens are) dark green!'),
(4966, 55, 65, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿ۚ۶۵﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4967, 55, 66, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فِیۡہِمَا عَیۡنٰنِ نَضَّاخَتٰنِ ﴿ۚ۶۶﴾', 'ان میں دو چشمے ابل رہے ہیں۔', 'اُن میں دو چشمے ہیں ابلتے ہوئے', 'In them (both) will be two springs gushing forth water.', 'In both there are two springs gushing forth profusely.'),
(4968, 55, 67, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۶۷﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4969, 55, 68, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فِیۡہِمَا فَاکِہَۃٌ  وَّ  نَخۡلٌ وَّ  رُمَّانٌ ﴿ۚ۶۸﴾', 'ان میں میوے اور کھجوریں اور انار ہیں۔', 'اُن میں میوے ہیں اور کھجوریں اور انار [۳۶]', 'In them (both) will be fruits, and date- palms and pomegranates.', 'In both there are fruits and date-palms and pomegranates.'),
(4970, 55, 69, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿ۚ۶۹﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4971, 55, 70, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فِیۡہِنَّ خَیۡرٰتٌ حِسَانٌ ﴿ۚ۷۰﴾', 'ان میں نیک سیرت خوبصورت عورتیں ہیں۔', 'ان سب باغوں میں اچھی عورتیں ہیں خوبصورت [۳۷]', 'Therein (gardens) will be fair (wives) good and beautiful;', 'In them there will be women, good and gorgeous,-'),
(4972, 55, 71, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿ۚ۷۱﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4973, 55, 72, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'حُوۡرٌ  مَّقۡصُوۡرٰتٌ فِی  الۡخِیَامِ ﴿ۚ۷۲﴾', 'وہ حوریں ہیں جو خیموں میں محفوظ ہیں۔', 'حوریں ہیں رکی رہنے والی خیموں میں [۳۸]', 'Houris (beautiful, fair females) restrained in pavilions;', '- the houris, kept guarded in pavilions-'),
(4974, 55, 73, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿ۚ۷۳﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4975, 55, 74, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'لَمۡ یَطۡمِثۡہُنَّ اِنۡسٌ قَبۡلَہُمۡ وَ لَا جَآنٌّ ﴿ۚ۷۴﴾', 'انکو اہل جنت سے پہلے نہ کسی انسان نے ہاتھ لگایا اور نہ کسی جن نے۔', 'نہیں ہاتھ لگایا  اُنکو کسی آدمی نے اُن سے پہلے اور نہ کسی جن نے', 'Whom no man or jinn yatmithhunna (has opened their hymens with sexual intercourse) before them.', '- whom neither a man might have touched before them, nor a Jinn.'),
(4976, 55, 75, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿ۚ۷۵﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4977, 55, 76, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'مُتَّکِـِٕیۡنَ عَلٰی رَفۡرَفٍ خُضۡرٍ  وَّ عَبۡقَرِیٍّ حِسَانٍ ﴿ۚ۷۶﴾', 'سبز قالینوں اور نفیس مسندوں پر تکیے لگائے بیٹھے ہوں گے۔', 'تکیہ لگٓئے بیٹھے سبز مسندوں پر اور قیمتی بچھونے نفیس پر', 'Reclining on green cushions and rich beautiful mattresses.', '(The people of these gardens will be) reclining on green cushions and marvelously beautiful mattresses.'),
(4978, 55, 77, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'فَبِاَیِّ  اٰلَآءِ  رَبِّکُمَا تُکَذِّبٰنِ ﴿۷۷﴾', 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', 'پھر کیا کیا نعمتیں اپنے رب کی جھٹلاؤ گے', 'Then which of the Blessings of your Lord will you both (jinns and men) deny?', 'So, which of the bounties of your Lord will you deny?'),
(4979, 55, 78, 3, 13, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الرحمٰن', 'تَبٰرَکَ اسۡمُ  رَبِّکَ ذِی الۡجَلٰلِ  وَ  الۡاِکۡرَامِ ﴿٪۷۸﴾', 'اے نبی ﷺ تمہارا پروردگار جو صاحب جلال و کرم ہے اس کا نام بڑا بابرکت ہے۔', 'بڑی برکت ہے نام کو تیرے رب کے جو بڑائی والا اورعظمت والا ہے [۳۹]', 'Blessed be the Name of your Lord (Allah), the Owner of Majesty and Honour', 'Glorious is the name of your Lord, the Lord of Majesty, the Lord of Honour.'),
(4980, 56, 1, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'اِذَا وَقَعَتِ الۡوَاقِعَۃُ ۙ﴿۱﴾', 'جب واقع ہونے والی واقع ہو جائے گی۔', 'جب ہو پڑے ہو پڑنے والی', 'When the Event (i.e. the Day of Resurrection) befalls.', 'When the Imminent Event (of Doom) will occur,'),
(4981, 56, 2, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'لَیۡسَ  لِوَقۡعَتِہَا  کَاذِبَۃٌ ۘ﴿۲﴾', 'اسکے واقع ہونے میں کچھ جھوٹ نہیں۔', 'نہیں ہے اُسکے ہو پڑے میں کچھ جھوٹ [۱]', 'And there can be no denying of its befalling.', 'there will be no one to deny its occurrence.'),
(4982, 56, 3, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'خَافِضَۃٌ  رَّافِعَۃٌ ۙ﴿۳﴾', 'کسی کو پست کرنے کسی کو بلند کرنے والی۔', 'پست کرنے والی ہے بلند کرنے والی [۲]', 'It will bring low (some); (and others) it will exalt;', 'It will be abasing (some), exalting (others)'),
(4983, 56, 4, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'اِذَا  رُجَّتِ الۡاَرۡضُ  رَجًّا ۙ﴿۴﴾', 'جب زمین بھونچال سے لرزنے لگے۔', 'جب لرزے زمین کپکپا کر', 'When the earth will be shaken with a terrible shake.', 'when the earth will be jolted with a terrible jolt,'),
(4984, 56, 5, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَّ  بُسَّتِ الۡجِبَالُ  بَسًّا ۙ﴿۵﴾', 'اور پہاڑ ٹوٹ کر ریزہ ریزہ ہو جائیں۔', 'اور ریزہ ریزہ ہوں پہاڑ ٹوٹ پھوٹ کر', 'And the mountains will be powdered to dust.', 'and the mountains will be crumbled a thorough crumbling,'),
(4985, 56, 6, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فَکَانَتۡ ہَبَآءً  مُّنۡۢبَثًّا ۙ﴿۶﴾', 'پھر غبار ہو کر اڑنے لگیں گے۔', 'پھر ہو جائیں غبار اڑتا ہوا [۳]', 'So that they will become floating dust particles.', 'until they will become dust, scattered in the air,'),
(4986, 56, 7, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَّ کُنۡتُمۡ  اَزۡوَاجًا  ثَلٰثَۃً ؕ﴿۷﴾', 'اور تم لوگ تین قسم کے ہو جاؤ گے۔', 'اور ہو جاؤ تین قسم پر  [۴]', 'And you (all) will be in three kinds (i.e. separate groups).', 'and you will be (divided into) three categories.'),
(4987, 56, 8, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فَاَصۡحٰبُ الۡمَیۡمَنَۃِ ۬ۙ مَاۤ  اَصۡحٰبُ الۡمَیۡمَنَۃِ ؕ﴿۸﴾', 'تو داہنے ہاتھ والے کیا کہنے داہنے ہاتھ والوں کے۔', 'پھر داہنے والے کیا خوب ہیں داہنے والے [۵]', 'So those on the Right Hand (i.e. those who will be given their Records in their right hands), Who will be those on the Right Hand? (As a respect for them, because they will enter Paradise).', 'As for the People of the Right, how (lucky) are the People of the Right!'),
(4988, 56, 9, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ اَصۡحٰبُ الۡمَشۡـَٔمَۃِ ۬ۙ مَاۤ  اَصۡحٰبُ الۡمَشۡـَٔمَۃِ ؕ﴿۹﴾', 'اور بائیں ہاتھ والے افسوس بائیں ہاتھ والے کیا ہی برے ہیں۔', 'اور بائیں والے کیا برے لوگ ہیں بائیں والے [۶]', 'And those on the Left Hand (i.e. those who will be given their Record in their left hands), Who will be those on the Left Hand? (As a disgrace for them, because they will enter Hell).', 'And the People of the Left ? How (wretched) are the People of the Left!'),
(4989, 56, 10, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ السّٰبِقُوۡنَ  السّٰبِقُوۡنَ ﴿ۚۙ۱۰﴾', 'اور جو آگے بڑھنے والے ہیں ان کا کیا کہنا وہ آگے ہی بڑھنے والے ہیں۔', 'اور اگاڑی والے تو اگاڑی والے', 'And those foremost ((in Islamic Faith of Monotheism and in performing righteous deeds) in the life of this world on the very first call for to embrace Islam,) will be foremost (in Paradise).', 'And the Foremost are the foremost.'),
(4990, 56, 11, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'اُولٰٓئِکَ  الۡمُقَرَّبُوۡنَ ﴿ۚ۱۱﴾', 'وہی اللہ کے مقرب ہیں۔', 'وہ لوگ ہیں مقرب', 'These will be those nearest to Allah.', 'Those are the ones blessed with nearness (to Allah)'),
(4991, 56, 12, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فِیۡ  جَنّٰتِ النَّعِیۡمِ ﴿۱۲﴾', 'نعمت کی بہشتوں میں۔', 'باغوں میں نعمت کے [۷]', 'In the Gardens of delight (Paradise).', 'in gardens of bliss,'),
(4992, 56, 13, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'ثُلَّۃٌ  مِّنَ الۡاَوَّلِیۡنَ ﴿ۙ۱۳﴾', 'وہ بہت سے تو پہلے کے لوگوں میں سے ہوں گے۔', 'انبوہ ہے پہلوں میں سے', 'A multitude of those (foremost) will be from the first generations (who embraced Islam).', 'many from the first generations,'),
(4993, 56, 14, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ قَلِیۡلٌ  مِّنَ الۡاٰخِرِیۡنَ ﴿ؕ۱۴﴾', 'اور تھوڑے سے بعد والوں میں سے۔', 'اور تھوڑے ہیں پچھلوں میں سے [۸]', 'And a few of those (foremost) will be from the later time (generations).', 'and a few from the later ones.'),
(4994, 56, 15, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'عَلٰی سُرُرٍ مَّوۡضُوۡنَۃٍ ﴿ۙ۱۵﴾', 'لعل و یاقوت وغیرہ سے جڑاؤ تختوں پر۔', 'بیٹھے ہیں جڑاؤ تختوں پر [۹]', '(They will be) on thrones woven with gold and precious stones,', '(They will be sitting) on thrones woven with gold,'),
(4995, 56, 16, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'مُّتَّکِـِٕیۡنَ عَلَیۡہَا مُتَقٰبِلِیۡنَ ﴿۱۶﴾', 'آمنے سامنے تکیہ لگائے ہوئے بیٹھے ہونگے۔', 'تکیہ لگائےاُن پر ایک دوسرے کے سامنے [۱۰]', 'Reclining thereon, face to face.', 'reclining on them, facing each other.'),
(4996, 56, 17, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'یَطُوۡفُ عَلَیۡہِمۡ  وِلۡدَانٌ   مُّخَلَّدُوۡنَ ﴿ۙ۱۷﴾', 'نوجوان خدمت گذار جو ہمیشہ ایک ہی حالت میں رہیں گے ان کے آس پاس پھریں گے۔', 'لئے پھرتے ہیں اُنکے پاس لڑکے سدا رہنے والے [۱۱]', 'They will be served by immortal boys,', 'Immortal boys will rotate around them'),
(4997, 56, 18, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'بِاَکۡوَابٍ وَّ اَبَارِیۡقَ ۬ۙ وَ کَاۡسٍ مِّنۡ مَّعِیۡنٍ ﴿ۙ۱۸﴾', 'یعنی آبخورے اور آفتابے اور صاف شراب کے جام لے لے کر۔', 'آبخورے اور کوزے اور پیالہ نتھری شراب کا', 'With cups, and jugs, and a glass from the flowing wine,', 'with bowls and jugs and a goblet of pure wine,'),
(4998, 56, 19, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'لَّا  یُصَدَّعُوۡنَ عَنۡہَا وَ لَا  یُنۡزِفُوۡنَ ﴿ۙ۱۹﴾', 'اس سے نہ تو سر میں درد ہوگا اور نہ انکی عقلیں زائل ہوں گی۔', 'جس سے نہ سر دکھے اور نہ بکواس لگے [۱۲]', 'Wherefrom they will get neither any aching of the head, nor any intoxication.', 'from which they will neither suffer headache, nor will they be intoxicated,'),
(4999, 56, 20, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ فَاکِہَۃٍ   مِّمَّا یَتَخَیَّرُوۡنَ ﴿ۙ۲۰﴾', 'اور میوے جس طرح کے انکو پسند ہوں۔', 'اور میوہ جونسا پسند کر لیں', 'And fruit; that they may choose.', '-and with fruits that they choose,'),
(5000, 56, 21, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ  لَحۡمِ  طَیۡرٍ  مِّمَّا یَشۡتَہُوۡنَ ﴿ؕ۲۱﴾', 'اور پرندوں کا گوشت جس قسم کا ان کا جی چاہے۔', 'اور گوشت اڑتے جانوروں کا جس قسم کو جی چاہے [۱۳]', 'And the flesh of fowls that they desire.', 'and the flesh of birds that they desire.'),
(5001, 56, 22, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ حُوۡرٌ عِیۡنٌ ﴿ۙ۲۲﴾', 'اور بڑی بڑی آنکھوں والی حوریں۔', 'اور عورتیں گوری بڑی آنکھوں والیاں', 'And (there will be) Houris (fair females) with wide, lovely eyes (as wives for the pious),', 'And (for them there will be) houris, having lovely big eyes,'),
(5002, 56, 23, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'کَاَمۡثَالِ اللُّؤۡلُؤَ  الۡمَکۡنُوۡنِ ﴿ۚ۲۳﴾', 'جیسے حفاظت سے رکھے ہوئے آبدار موتی۔', 'جیسے موتی کے دانے اپنے غلاف کے اندر  [۱۴]', 'Like unto preserved pearls.', 'all (neat and clean) like a hidden pearl,'),
(5003, 56, 24, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'جَزَآءًۢ  بِمَا کَانُوۡا یَعۡمَلُوۡنَ ﴿۲۴﴾', 'یہ ان کے اعمال کا بدلہ ہے جو وہ کرتے تھے۔', 'بدلہ اُن کاموں کا جو کرتے تھے', 'A reward for what they used to do.', 'as a reward for what they used to do.'),
(5004, 56, 25, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'لَا یَسۡمَعُوۡنَ فِیۡہَا لَغۡوًا  وَّ لَا  تَاۡثِیۡمًا ﴿ۙ۲۵﴾', 'وہاں نہ وہ بیہودہ بات سنیں گے اور نہ گالی گلوچ۔', 'نہیں سنیں گے وہاں بکواس اور گناہ کی بات', 'No Laghw (dirty, false, evil vain talk) will they hear therein, nor any sinful speech (like backbiting, etc.).', 'They will hear neither an absurd talk in it, nor something leading to sin,'),
(5005, 56, 26, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'اِلَّا  قِیۡلًا  سَلٰمًا سَلٰمًا ﴿۲۶﴾', 'ہاں ان کا کلام سلام سلام ہو گا۔', 'مگر ایک بولنا سلام سلام [۱۵]', 'But only the saying of: Salam!, Salam! (greetings with peace) !', 'but (they will hear) the words of Salām , Salām (as greetings).'),
(5006, 56, 27, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ اَصۡحٰبُ الۡیَمِیۡنِ ۬ۙ مَاۤ  اَصۡحٰبُ الۡیَمِیۡنِ ﴿ؕ۲۷﴾', 'اور داہنے ہاتھ والے کیا کہنے ہیں داہنے ہاتھ والوں کے۔', 'اور داہنے والے کیا کہنے داہنے والوں کے', 'And those on the Right Hand, Who will be those on the Right Hand?', 'And the People of the right? How (lucky) are the People of the Right!'),
(5007, 56, 28, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فِیۡ  سِدۡرٍ مَّخۡضُوۡدٍ ﴿ۙ۲۸﴾', 'وہ بے کانٹوں کی بیریوں۔', 'رہتے ہیں بیری کے درختوں میں جن میں کانٹا نہیں [۱۶]', '(They will be) among thornless lote-trees,', '(They will be) amid lote-trees with no thorns,'),
(5008, 56, 29, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَّ  طَلۡحٍ  مَّنۡضُوۡدٍ ﴿ۙ۲۹﴾', 'اور تہ بہ تہ کیلوں۔', 'اور کیلے تہہ پر تہہ', 'Among Talh (banana-trees) with fruits piled one above another,', 'and the trees of TalH , (banana, or a fragrant tree) having layers one upon the other,'),
(5009, 56, 30, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَّ ظِلٍّ  مَّمۡدُوۡدٍ ﴿ۙ۳۰﴾', 'اور لمبے لمبے سایوں۔', 'اور سایہ لنبا [۱۷]', 'In shade long-extended,', 'and a shade, spread all over,'),
(5010, 56, 31, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَّ مَآءٍ  مَّسۡکُوۡبٍ ﴿ۙ۳۱﴾', 'اور بہتے پانی کے چشموں۔', 'اور پانی بہتا ہوا', 'By water flowing constantly,', 'and water, poured forth,'),
(5011, 56, 32, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَّ  فَاکِہَۃٍ   کَثِیۡرَۃٍ ﴿ۙ۳۲﴾', 'اور بہت سے میوں کے باغوں میں ہونگے۔', 'اور میوہ بہت', 'And fruit in plenty,', 'and a lot of fruits,'),
(5012, 56, 33, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'لَّا مَقۡطُوۡعَۃٍ  وَّ لَا  مَمۡنُوۡعَۃٍ ﴿ۙ۳۳﴾', 'جو نہ کبھی ختم ہوں اور نہ ان پر کوئی روک ٹوک ہو گی۔', 'نہ اُس میں سے ٹوٹا اور نہ روکا ہوا [۱۸]', 'Whose season is not limited, and their supply will not be cut off,', 'neither interrupted (in any season), nor prohibited,'),
(5013, 56, 34, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَّ فُرُشٍ مَّرۡفُوۡعَۃٍ ﴿ؕ۳۴﴾', 'اور اونچے اونچے بستروں پر آرام کریں گے۔', 'اور بچھونے اونچے [۱۹]', 'And on couches or thrones, raised high.', 'and mattresses of high quality.'),
(5014, 56, 35, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'اِنَّاۤ  اَنۡشَاۡنٰہُنَّ  اِنۡشَآءً ﴿ۙ۳۵﴾', 'ہم نے ہی ان حوروں کو پیدا کیا۔', 'ہم نے اٹھایا اُن عورتوں کو ایک اچھے اٹھان پر', 'Verily, We have created them (maidens) of special creation.', 'Surely We have made up those females in a special creation,'),
(5015, 56, 36, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فَجَعَلۡنٰہُنَّ  اَبۡکَارًا ﴿ۙ۳۶﴾', 'تو انکو کنواری بنایا۔', 'پھر کیا اُنکو کنواریاں', 'And made them virgins.', 'and have made them virgins,'),
(5016, 56, 37, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'عُرُبًا  اَتۡرَابًا ﴿ۙ۳۷﴾', 'اور شوہروں کی پیاری اور ہم عمر۔', 'پیار  دلانے والیاں ہم عمر', 'Loving (their husbands only), equal in age.', 'amorous to their husbands, matching them in age,'),
(5017, 56, 38, 1, 14, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'لِّاَصۡحٰبِ الۡیَمِیۡنِ ﴿ؕ٪۳۸﴾', 'یعنی داہنے ہاتھ والوں کے لئے۔', 'واسطے داہنے والوں کے [۲۰]', 'For those on the Right Hand.', 'for the People of the Right,'),
(5018, 56, 39, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'ثُلَّۃٌ  مِّنَ  الۡاَوَّلِیۡنَ ﴿ۙ۳۹﴾', 'یہ بہت سے تو پہلے کے لوگوں میں سے ہونکے۔', 'انبوہ ہے پہلوں میں سے', 'A multitude of those (on the Right Hand) will be from the first generation (who embraced Islam).', '(comprising) many from the first generations,'),
(5019, 56, 40, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ ثُلَّۃٌ  مِّنَ  الۡاٰخِرِیۡنَ ﴿ؕ۴۰﴾', 'اور بہت سے بعد والوں میں سے۔', 'اور انبوہ ہے پچھلوں میں سے [۲۱]', 'And a multitude of those (on the Right Hand) will be from the later times (generations).', 'and many from the later ones.'),
(5020, 56, 41, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ اَصۡحٰبُ الشِّمَالِ ۬ۙ مَاۤ  اَصۡحٰبُ  الشِّمَالِ ﴿ؕ۴۱﴾', 'اور بائیں ہاتھ والے افسوس بائیں ہاتھ والے کیا ہی عذاب میں ہونگے۔', 'اور بائیں والے کیسے بائیں والے', 'And those on the Left Hand Who will be those on the Left Hand?', 'And the People of the Left? How (wretched) are the People of the Left!'),
(5021, 56, 42, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فِیۡ  سَمُوۡمٍ  وَّ  حَمِیۡمٍ ﴿ۙ۴۲﴾', 'یعنی دوزخ کی لپٹ اور کھولتے ہوئے پانی میں۔', 'تیز بھاپ میں اور جلتے پانی میں', 'In fierce hot wind and boiling water,', '(They will be) in scorching wind and boiling water,'),
(5022, 56, 43, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَّ ظِلٍّ  مِّنۡ  یَّحۡمُوۡمٍ ﴿ۙ۴۳﴾', 'اور سیاہ دھوئیں کے سائے میں۔', 'اور سایہ میں دھوئیں کے', 'And shadow of black smoke,', 'and in a shade of black smoke,'),
(5023, 56, 44, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'لَّا  بَارِدٍ  وَّ  لَا کَرِیۡمٍ ﴿۴۴﴾', 'جو نہ ٹھنڈا ہو گا اور نہ خوشنما۔', 'نہ ٹھنڈا اور نہ عزت کا [۲۲]', '(That shadow) neither cool, nor (even) good,', 'neither cool nor graceful.'),
(5024, 56, 45, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'اِنَّہُمۡ  کَانُوۡا  قَبۡلَ  ذٰلِکَ  مُتۡرَفِیۡنَ ﴿ۚۖ۴۵﴾', 'یہ لوگ اس سے پہلے عیش میں پڑے ہوئے تھے۔', 'وہ لوگ تھے اس سے پہلے خوشحال', 'Verily, before that, they indulged in luxury,', 'They were earlier in luxuries,'),
(5025, 56, 46, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ کَانُوۡا یُصِرُّوۡنَ عَلَی الۡحِنۡثِ الۡعَظِیۡمِ ﴿ۚ۴۶﴾', 'اور بڑے گناہ یعنی کفر پر اڑے ہوئے تھے۔', 'اور ضد کرتے تھے اُس بڑے گناہ پر [۲۳]', 'And were persisting in great sin (joining partners in worship along with Allah, committing murders and other crimes, etc.)', 'and used to persist in major sins,'),
(5026, 56, 47, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ کَانُوۡا یَقُوۡلُوۡنَ ۬ۙ  اَئِذَا مِتۡنَا وَ کُنَّا تُرَابًا وَّ عِظَامًا ءَاِنَّا  لَمَبۡعُوۡثُوۡنَ ﴿ۙ۴۷﴾', 'اور کہا کرتے تھے کہ بھلا جب ہم مر گئے اور مٹی ہو گئے اور ہڈیاں ہی ہڈیاں ہو گئے تو کیا ہمیں پھر اٹھنا ہو گا؟', 'اور کہا کرتے تھے کیا جب ہم مر گئے اور ہو چکے مٹی اور ہڈیاں کیا ہم پھر اٹھائے جائیں گے', 'And they used to say: \"When we die and become dust and bones, shall we then indeed be resurrected?', 'and used to say, “Is it that when we die and become dust-is it that we will be raised again,'),
(5027, 56, 48, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'اَوَ  اٰبَآؤُنَا  الۡاَوَّلُوۡنَ ﴿۴۸﴾', 'اور کیا ہمارے اگلے باپ دادا کو بھی؟', 'اور کیا ہمارے اگلے باپ دادے بھی [۲۴]', '\"And also our forefathers?\"', 'and our ancient fathers as well?”'),
(5028, 56, 49, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'قُلۡ  اِنَّ الۡاَوَّلِیۡنَ  وَ  الۡاٰخِرِیۡنَ ﴿ۙ۴۹﴾', 'کہدو کہ بیشک پہلے اور بعد والے۔', 'تو کہہ دے کہ اگلے اور پچھلے', 'Say (O Muhammad SAW): \"(Yes) verily, those of old, and those of later times.', 'Say, “All the earlier and the later ones'),
(5029, 56, 50, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'لَمَجۡمُوۡعُوۡنَ ۬ۙ اِلٰی مِیۡقَاتِ یَوۡمٍ مَّعۡلُوۡمٍ ﴿۵۰﴾', 'سب ایک روز مقرر کے وقت پر جمع کئے جائیں گے۔', 'سب اکٹھے ہونے والے ہیں ایک دن مقرر کے وقت پر [۲۵]', '\"All will surely be gathered together for appointed Meeting of a known Day.', 'will be gathered together for a fixed time of a specified Day.'),
(5030, 56, 51, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'ثُمَّ  اِنَّکُمۡ  اَیُّہَا الضَّآلُّوۡنَ الۡمُکَذِّبُوۡنَ ﴿ۙ۵۱﴾', 'پھر تم اے جھٹلانے والے گمراہو!', 'پھر تو جو ہو اے بہکے ہوؤ جھٹلانے والو', '\"Then moreover, verily, you the erring-ones, the deniers (of Resurrection)!', 'Then O you, the erring, the denying people,'),
(5031, 56, 52, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'لَاٰکِلُوۡنَ مِنۡ شَجَرٍ  مِّنۡ  زَقُّوۡمٍ ﴿ۙ۵۲﴾', 'تھوہر کے درخت سے کھاؤ گے۔', 'البتہ کھاؤ گے ایک درخت سینڈکے سے', '\"You verily will eat of the trees of Zaqqoom.', 'you will have to eat from the tree of zaqqūm,'),
(5032, 56, 53, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فَمَالِـُٔوۡنَ  مِنۡہَا الۡبُطُوۡنَ ﴿ۚ۵۳﴾', 'پھر اسی سے پیٹ بھرو گے۔', 'پھر بھرو گے اس سے پیٹ [۲۶]', '\"Then you will fill your bellies therewith,', 'and to fill with it the bellies,'),
(5033, 56, 54, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فَشٰرِبُوۡنَ عَلَیۡہِ مِنَ الۡحَمِیۡمِ ﴿ۚ۵۴﴾', 'پھر اس پر کھولتا ہوا پانی پیو گے۔', 'پھر پیو گے اُس پر ایک جلتا پانی', '\"And drink boiling water on top of it,', 'then on top of it you will have to drink boiling water,'),
(5034, 56, 55, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فَشٰرِبُوۡنَ شُرۡبَ الۡہِیۡمِ ﴿ؕ۵۵﴾', 'پھر پیو گے بھی اس طرح جیسے پیاسے اونٹ پیتے ہیں۔', 'پھر پیو گے جیسے پئیں اونٹ تونسے  ہوئے [۲۷]', '\"So you will drink (that) like thirsty camels!\"', 'and to drink like camels suffering from the disease of over-thirst.'),
(5035, 56, 56, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'ہٰذَا  نُزُلُہُمۡ یَوۡمَ الدِّیۡنِ ﴿ؕ۵۶﴾', 'انصاف کے دن یہ انکی ضیافت ہو گی۔', 'یہ مہمانی ہے اُنکی انصاف کے دن [۲۸]', 'That will be their entertainment on the Day of Recompense!', 'This will be their welcome entertainment on the Day of Requital.'),
(5036, 56, 57, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'نَحۡنُ خَلَقۡنٰکُمۡ  فَلَوۡ لَا تُصَدِّقُوۡنَ ﴿۵۷﴾', 'ہم نے تمکو پہلی بار بھی تو پیدا کیا ہے تو تم دوبارہ اٹھنے کو کیوں سچ نہیں سمجھتے؟', 'ہم نے تم کو بنایا پھر کیوں نہیں سچ مانتے [۲۹]', 'We created you, then why do you believe not?', 'We have created you; then why do you not believe in it?'),
(5037, 56, 58, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'اَفَرَءَیۡتُمۡ مَّا تُمۡنُوۡنَ ﴿ؕ۵۸﴾', 'دیکھو تو کہ جس نطفے کو تم ڈالتے ہو۔', 'بھلا دیکھو تو جو پانی تم ٹپکاتے ہو', 'Then tell Me (about) the human semen that you emit.', 'So, tell Me about the semen you drop (in the wombs):'),
(5038, 56, 59, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'ءَاَنۡتُمۡ  تَخۡلُقُوۡنَہٗۤ  اَمۡ  نَحۡنُ  الۡخٰلِقُوۡنَ ﴿۵۹﴾', 'کیا تم اس سے انسان کو بناتے ہو یا ہم بناتے ہیں؟', 'اب تم اُسکو بناتے ہو یا ہم ہیں بنانے والے [۳۰]', 'Is it you who create it (i.e. make this semen into a perfect human being), or are We the Creator?', 'Is it you who create it, or are We the Creator?'),
(5039, 56, 60, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'نَحۡنُ قَدَّرۡنَا بَیۡنَکُمُ الۡمَوۡتَ وَ مَا نَحۡنُ بِمَسۡبُوۡقِیۡنَ ﴿ۙ۶۰﴾', 'ہم نے تمہارے لئے موت کو مقرر کر دیا ہے اور ہم اس بات سے عاجز نہیں۔', 'ہم ٹھہرا چکے  تم میں مرنا [۳۱] اور ہم عاجز نہیں', 'We have decreed death to you all, and We are not unable,', 'We have appointed (the times of) death among you, and We cannot be frustrated'),
(5040, 56, 61, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'عَلٰۤی  اَنۡ نُّبَدِّلَ  اَمۡثَالَکُمۡ وَ نُنۡشِئَکُمۡ  فِیۡ مَا لَا تَعۡلَمُوۡنَ ﴿۶۱﴾', 'کہ تمہاری طرح کے اور لوگ تمہاری جگہ لے آئیں اور تمکو ایسے  عالم میں جسکو تم نہیں جانتے پیدا کر دیں۔', 'اس بات سے کہ بدلے میں لے آئیں تمہاری طرح کے لوگ اور اٹھا کھڑا کریں تم کو  وہاں جہاں تم نہیں جانتے [۳۲]', 'To transfigure you and create you in (forms) that you know not.', 'from replacing you with others like you, and creating you (afresh) in that (form) which you do not know.'),
(5041, 56, 62, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ لَقَدۡ عَلِمۡتُمُ النَّشۡاَۃَ  الۡاُوۡلٰی فَلَوۡ لَا تَذَکَّرُوۡنَ ﴿۶۲﴾', 'اور تم نے پہلی پیدائش تو جان ہی لی ہے پھر تم سوچتے کیوں نہیں؟', 'اور تم جان چکے ہو  پہلا اٹھان پھر کیوں نہیں یاد کرتے [۳۳]', 'And indeed, you have already known the first form of creation (i.e. the creation of Adam), why then do you not remember or take heed?', 'And you certainly know the first creation; then why do you not take lesson?'),
(5042, 56, 63, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'اَفَرَءَیۡتُمۡ  مَّا  تَحۡرُثُوۡنَ ﴿ؕ۶۳﴾', 'بھلا دیکھو تو کہ جو کچھ تم بوتے ہو۔', 'بھلا دیکھو تو جو تم بوتے ہو', 'Tell Me! The seed that you sow in the ground.', 'Well, tell Me about that (seed) which you sow:'),
(5043, 56, 64, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'ءَاَنۡتُمۡ تَزۡرَعُوۡنَہٗۤ  اَمۡ نَحۡنُ الزّٰرِعُوۡنَ ﴿۶۴﴾', 'تو کیا تم اسے اگاتے ہو یا ہم اگاتے ہیں؟', 'کیا تم اُسکو کر تے ہو کھیتی یا ہم ہیں کھیتی کر دینے والے [۳۴]', 'Is it you that make it grow, or are We the Grower?', 'Is it you who grow it, or are We the One who grows?'),
(5044, 56, 65, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'لَوۡ نَشَآءُ  لَجَعَلۡنٰہُ  حُطَامًا فَظَلۡتُمۡ تَفَکَّہُوۡنَ ﴿۶۵﴾', 'اگر ہم چاہیں تو اسے چورا چورا کر دیں سو تم باتیں بناتے رہ جاؤ۔', 'اگر ہم چاہیں تو کر ڈالیں اُسکو روندا ہوا گھانس پھر تم سارے دن رہو باتیں بناتے', 'Were it Our Will, We could crumble it to dry pieces, and you would be regretful (or left in wonderment).', 'If We so will, We can certainly make it crumbled, and you will remain wondering,'),
(5045, 56, 66, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'اِنَّا  لَمُغۡرَمُوۡنَ ﴿ۙ۶۶﴾', 'کہ ہائے ہم تو تاوان میں پھنس گئے۔', 'ہم تو قرضدار رہ گئے', '(Saying): \"We are indeed Mughramoon (i.e. ruined or lost the money without any profit, or punished by the loss of all that we spend for cultivation, etc.)! (See Tafsir Al-Qurtubee, Vol. 17, Page 219)', '(and saying,) “We are laden with debt,'),
(5046, 56, 67, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'بَلۡ  نَحۡنُ  مَحۡرُوۡمُوۡنَ ﴿۶۷﴾', 'بلکہ ہم بے نصیب رہ گئے۔', 'بلکہ ہم بے نصیب ہو گئے [۳۵]', '\"Nay, but we are deprived!\"', 'rather we are totally deprived.”'),
(5047, 56, 68, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'اَفَرَءَیۡتُمُ  الۡمَآءَ  الَّذِیۡ تَشۡرَبُوۡنَ ﴿ؕ۶۸﴾', 'بھلا دیکھو تو کہ جو پانی تم پیتے ہو۔', 'بھلا دیکھو تو پانی کو جو تم پیتے ہو', 'Tell Me! The water that you drink.', 'Again, tell Me about the water you drink:'),
(5048, 56, 69, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'ءَاَنۡتُمۡ  اَنۡزَلۡتُمُوۡہُ مِنَ الۡمُزۡنِ اَمۡ نَحۡنُ الۡمُنۡزِلُوۡنَ ﴿۶۹﴾', 'کیا تم نے اسکو بادل سے نازل کیا ہے یا ہم نازل کرتے ہیں؟', 'کیا تم نے اتارا اُسکو  بادل سے ہا ہم ہیں اتارنے والے [۳۶]', 'Is it you who cause it from the rainclouds to come down, or are We the Causer of it to come down?', 'Is it you who have brought it down from the clouds, or are We the One who sends (it) down?'),
(5049, 56, 70, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'لَوۡ نَشَآءُ  جَعَلۡنٰہُ  اُجَاجًا فَلَوۡ لَا تَشۡکُرُوۡنَ ﴿۷۰﴾', 'اگر ہم چاہیں تو ہم اسے کھاری کر دیں پھر تم شکر کیوں نہیں کرتے؟', 'اگر ہم چاہیں کر دیں اُسکو کھارا پھر کیوں نہیں احسان مانتے [۳۷]', 'If We willed, We verily could make it salt (and undrinkable), why then do you not give thanks (to Allah)?', 'If We so will, We can make it bitter in taste. So why do you not offer gratitude?'),
(5050, 56, 71, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'اَفَرَءَیۡتُمُ النَّارَ الَّتِیۡ تُوۡرُوۡنَ ﴿ؕ۷۱﴾', 'بھلا دیکھو تو جو آگ تم درخت سے نکالتے ہو۔', 'بھلا دیکھو تو آگ جس کو تم سلگاتے ہو', 'Tell Me! The fire which you kindle,', 'Now tell Me about the fire you kindle:'),
(5051, 56, 72, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'ءَاَنۡتُمۡ اَنۡشَاۡتُمۡ شَجَرَتَہَاۤ  اَمۡ نَحۡنُ الۡمُنۡشِـُٔوۡنَ ﴿۷۲﴾', 'کیا تم نے اس کے درخت کو پیدا کیا ہے یا ہم پیدا کرتے ہیں؟', 'کیا تم نے پیدا کیا اُس کا درخت یا ہم ہیں پیدا کرنے والے [۳۸]', 'Is it you who made the tree thereof to grow, or are We the Grower?', 'Is it you who have originated its tree, 5 or are We the Originator?'),
(5052, 56, 73, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'نَحۡنُ جَعَلۡنٰہَا تَذۡکِرَۃً  وَّ مَتَاعًا لِّلۡمُقۡوِیۡنَ ﴿ۚ۷۳﴾', 'ہم نے اسے یاد دلانے اور مسافروں کے برتنے کو بنایا ہے۔', 'ہم نے ہی تو بنایا وہ درخت یاد دلانے کو [۳۹] اور برتنے کو جنگل والوں کے [۴۰]', 'We have made it a Reminder (for the Hell-fire, in the Hereafter); and an article of use for the travellers (and all the others, in this world).', 'We have made it a reminder (of Our infinite power, and of the fire of Hell) and a benefit for travelers in deserts.'),
(5053, 56, 74, 2, 15, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فَسَبِّحۡ  بِاسۡمِ  رَبِّکَ الۡعَظِیۡمِ ﴿٪ؓ۷۴﴾', 'تو اے پیغمبر ﷺ تم اپنے پروردگار عظیم کے نام کی تسبیح کرو۔', 'سو بول پاکی اپنے رب کے نام کی جو سب سے بڑا [۴۱]', 'Then glorify with praises the Name of your Lord, the Most Great.', 'So, proclaim purity of the name of your Lord, the Magnificent.'),
(5054, 56, 75, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فَلَاۤ   اُقۡسِمُ  بِمَوٰقِعِ  النُّجُوۡمِ ﴿ۙ۷۵﴾', 'سو ہمیں تاروں کی منزلوں کی قسم۔', 'سو میں قسم کھاتا ہوں تاروں کے ڈوبنے کی [۴۲]', 'So I swear by Mawaqi (setting or the mansions, etc.) of the stars (they traverse).', 'So, I swear by the setting places of the stars,'),
(5055, 56, 76, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ  اِنَّہٗ  لَقَسَمٌ  لَّوۡ  تَعۡلَمُوۡنَ عَظِیۡمٌ ﴿ۙ۷۶﴾', 'اور اگر تم سمجھو تو یہ بڑی قسم ہے۔', 'اور یہ قسم ہے اگر سمجھو تو  بڑی قسم', 'And verily, that is indeed a great oath, if you but know.', '-and indeed it is a great oath, if you are to appreciate-'),
(5056, 56, 77, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'اِنَّہٗ   لَقُرۡاٰنٌ   کَرِیۡمٌ ﴿ۙ۷۷﴾', 'کہ یہ بڑے رتبے کا قرآن ہے۔', 'بیشک یہ قرآن ہے عزت والا', 'That (this) is indeed an honourable recital (the Noble Quran).', 'it is surely the Noble Qur’ān,'),
(5057, 56, 78, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فِیۡ  کِتٰبٍ مَّکۡنُوۡنٍ ﴿ۙ۷۸﴾', 'جو کتاب محفوظ میں لکھا ہوا ہے۔', 'لکھا ہوا ہے ایک پوشیدہ کتاب میں', 'In a Book well-guarded (with Allah in the heaven i.e. Al-Lauh Al-Mahfooz).', '(recorded already) in a protected book (i.e. the Preserved Tablet)'),
(5058, 56, 79, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'لَّا  یَمَسُّہٗۤ  اِلَّا الۡمُطَہَّرُوۡنَ ﴿ؕ۷۹﴾', 'اس کو وہی ہاتھ لگاتے ہیں جو پاک ہیں۔', 'اُس کو وہی چھوتے ہیں جو  پاک بنائے گئے ہیں [۴۳]', 'Which (that Book with Allah) none can touch but the purified (i.e. the angels).', 'that is not touched except by the purified ones (the angels).'),
(5059, 56, 80, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'تَنۡزِیۡلٌ  مِّنۡ  رَّبِّ الۡعٰلَمِیۡنَ ﴿۸۰﴾', 'یہ رب العالمین کی طرف سے اتارا گیا ہے۔', 'اتارا ہوا ہے اپنے پروردگار عالم کی طرف سے [۴۴]', 'A Revelation (this Quran) from the Lord of the Alameen (mankind, jinns and all that exists).', '- a revelation from the Lord of the worlds.'),
(5060, 56, 81, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'اَفَبِہٰذَا  الۡحَدِیۡثِ  اَنۡتُمۡ  مُّدۡہِنُوۡنَ ﴿ۙ۸۱﴾', 'کیا تم اس کلام کے ماننے میں دیر کرتے ہو؟', 'اب کیا اس بات میں تم سستی کرتے ہو', 'Is it such a talk (this Quran) that you (disbelievers) deny?', 'Is it this discourse that you take lightly,'),
(5061, 56, 82, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ تَجۡعَلُوۡنَ  رِزۡقَکُمۡ  اَنَّکُمۡ تُکَذِّبُوۡنَ ﴿۸۲﴾', 'اور اپنا وظیفہ یہ بناتے ہو کہ اسے جھٹلاتے رہتے ہو۔', 'اور اپنا حصہ تم یہی لیتے ہو کہ اُسکو جھٹلاتے ہو [۴۵]', 'And instead (of thanking Allah) for the provision He gives you, on the contrary, you deny Him (by disbelief)!', 'and take your denial as your livelihood?'),
(5062, 56, 83, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فَلَوۡ لَاۤ   اِذَا  بَلَغَتِ  الۡحُلۡقُوۡمَ ﴿ۙ۸۳﴾', 'پھر جب جان گلے تک آ پہنچتی ہے۔', 'پھر کیوں نہیں جس وقت جان پہنچے حلق کو', 'Then why do you not (intervene) when (the soul of a dying person) reaches the throat?', 'So why (do you) not (intervene) when the soul (of a dying person) reaches the throat,'),
(5063, 56, 84, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ اَنۡتُمۡ  حِیۡنَئِذٍ  تَنۡظُرُوۡنَ ﴿ۙ۸۴﴾', 'اور تم اس وقت کی حالت کو دیکھا کرتے ہو۔', 'اور تم اُس وقت دیکھ رہے ہو', 'And you at the moment are looking on,', 'and you are watching?'),
(5064, 56, 85, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ  نَحۡنُ  اَقۡرَبُ اِلَیۡہِ مِنۡکُمۡ  وَ لٰکِنۡ لَّا  تُبۡصِرُوۡنَ ﴿۸۵﴾', 'اور ہم اس مرنے والے کے تم سے بھی زیادہ نزدیک ہوتے ہیں لیکن تمکو نظر نہیں آتے۔', 'اور ہم اُسکے پاس ہیں تم سے زیادہ پر تم نہیں دیکھتے', 'But We (i.e. Our angels who take the soul) are nearer to him than you, but you see not, (Tafsir At-Tabaree, Vol.27, Page 209)', 'And We are closer to him than you, but you do not perceive.'),
(5065, 56, 86, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فَلَوۡ لَاۤ  اِنۡ  کُنۡتُمۡ  غَیۡرَ  مَدِیۡنِیۡنَ ﴿ۙ۸۶﴾', 'پس اگر تم کسی کے بس میں نہیں ہو۔', 'پھر کیوں نہیں اگر تم نہیں ہو کسی کے حکم میں', 'Then why do you not, if you are exempt from the reckoning and recompense (punishment, etc.)', 'So, if you are not going to be recompensed (in the Hereafter for your deeds), then why do you not'),
(5066, 56, 87, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'تَرۡجِعُوۡنَہَاۤ  اِنۡ  کُنۡتُمۡ صٰدِقِیۡنَ ﴿۸۷﴾', 'تو اگر سچے ہو تو تم جان کو لوٹا کیوں نہیں لیتے۔', 'تو کیوں نہیں پھیر لیتے اُس روح کو اگر ہو تم سچے [۴۶]', 'Bring back the soul (to its body), if you are truthful?', 'bring the soul back, if you are truthful?'),
(5067, 56, 88, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فَاَمَّاۤ  اِنۡ کَانَ مِنَ الۡمُقَرَّبِیۡنَ ﴿ۙ۸۸﴾', 'پھر اگر وہ اللہ کے مقربوں میں سے ہوا۔', 'سو جو اگر وہ مردہ ہوا مقرب لوگوں میں', 'Then, if he (the dying person) be of the Muqarraboon (those brought near to Allah),', 'So, in case he (the dying person) is from among those blessed with nearness,'),
(5068, 56, 89, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فَرَوۡحٌ  وَّ  رَیۡحَانٌ ۬ۙ وَّ جَنَّتُ نَعِیۡمٍ ﴿۸۹﴾', 'تو اس کے لئے آرام اور روزی اور نعمت کے باغ ہونگے۔', 'تو راحت ہے اور روزی ہے اور باغ نعمت کا', '(There is for him) rest and provision, and a Garden of delights (Paradise).', 'then (for him) there is comfort and fragrance and garden of bliss.'),
(5069, 56, 90, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ اَمَّاۤ  اِنۡ  کَانَ مِنۡ  اَصۡحٰبِ الۡیَمِیۡنِ ﴿ۙ۹۰﴾', 'اور اگر وہ دائیں ہاتھ والوں میں سے ہوا۔', 'اور جو اگر وہ ہوا داہنے والوں میں', 'And if he (the dying person) be of those on the Right Hand,', 'And in case he is from among the People of the Right,'),
(5070, 56, 91, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فَسَلٰمٌ  لَّکَ مِنۡ  اَصۡحٰبِ الۡیَمِیۡنِ ﴿ؕ۹۱﴾', 'تو کہا جائے گا کہ تجھ پر داہنے ہاتھ والوں کی طرف سے سلام۔', 'تو سلامتی پہنچے تجھ کو داہنے والوں سے [۴۷]', 'Then there is safety and peace (from the Punishment of Allah) for (you as you are from) those on the Right Hand.', 'then, (it will be said to him,) “Peace is for you, as you are one of the People of the Right.”'),
(5071, 56, 92, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَ اَمَّاۤ   اِنۡ کَانَ مِنَ الۡمُکَذِّبِیۡنَ الضَّآلِّیۡنَ ﴿ۙ۹۲﴾', 'اور اگر وہ جھٹلانے والے گمراہوں میں سے ہوا۔', 'اور جو اگر وہ ہوا جھٹلانے والوں بہکنے والوں میں سے', 'But if he (the dying person) be of the denying (of the Resurrection), the erring (away from the Right Path of Islamic Monotheism),', 'But if he is one of the deniers, the astray,'),
(5072, 56, 93, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فَنُزُلٌ مِّنۡ حَمِیۡمٍ ﴿ۙ۹۳﴾', 'تو اس کے لئے کھولتے پانی کی ضیافت ہو گی۔', 'تو مہمانی ہے جلتا پانی', 'Then for him is entertainment with boiling water.', 'then (for him) there is entertainment from boiling water,'),
(5073, 56, 94, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'وَّ تَصۡلِیَۃُ  جَحِیۡمٍ ﴿۹۴﴾', 'اور جہنم میں داخل کیا جانا۔', 'اور ڈالنا آگ میں [۴۸]', 'And burning in Hell-fire.', 'and burning in the Hell.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(5074, 56, 95, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'اِنَّ ہٰذَا  لَہُوَ  حَقُّ الۡیَقِیۡنِ ﴿ۚ۹۵﴾', 'یہ بات واقعی یقینی ہے۔', 'بیشک یہ بات یہی ہے لائق یقین کے [۴۹]', 'Verily, this! This is an absolute Truth with certainty.', 'Indeed this is certainty in its true sense.'),
(5075, 56, 96, 3, 16, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', 'الواقعۃ', 'فَسَبِّحۡ  بِاسۡمِ  رَبِّکَ الۡعَظِیۡمِ ﴿٪۹۶﴾', 'تو اے نبی ﷺ تم اپنے پروردگار عظیم کے نام کی تسبیح کرتے رہو۔', 'سو بول پاکی اپنے رب کے نام سے جو سب سے بڑا ہے [۵۰]', 'So glorify with praises the Name of your Lord, the Most Great.', 'So, proclaim purity of the name of your Lord, the Magnificent.'),
(5076, 57, 1, 1, 17, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'سَبَّحَ  لِلّٰہِ مَا فِی السَّمٰوٰتِ وَ الۡاَرۡضِ ۚ وَ ہُوَ  الۡعَزِیۡزُ  الۡحَکِیۡمُ ﴿۱﴾', 'جو مخلوق آسمانوں اور زمین میں ہے اللہ کی تسبیح کرتی ہے اور وہ غالب ہے حکمت والا ہے۔', 'اللہ کی پاکی بولتا ہے جو کچھ ہے آسمانوں میں اور زمین میں [۱] اور وہی ہے زبردست حکمتوں والا', 'Whatsoever is in the heavens and the earth glorifies Allah, and He is the All-Mighty, All-Wise.', 'All that is in the heavens and the earth proclaims Allah’s purity, and He is the Mighty, the Wise.'),
(5077, 57, 2, 1, 17, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'لَہٗ  مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ ۚ یُحۡیٖ وَ یُمِیۡتُ ۚ وَ ہُوَ  عَلٰی کُلِّ  شَیۡءٍ  قَدِیۡرٌ ﴿۲﴾', 'آسمانوں اور زمین کی بادشاہی اسی کی ہے وہی زندگی دیتا ہے اور وہی موت دیتا ہے۔ اور وہ ہر چیز پر قادر ہے۔', 'اُسی کے لئے ہے راج آسمانوں کا اور زمین کا جِلاتا ہے اور مارتا ہے اور  وہ سب کچھ کر سکتا ہے [۲]', 'His is the kingdom of the heavens and the earth, It is He Who gives life and causes death; and He is Able to do all things.', 'To Him belongs the Kingdom of the heavens and the earth. He gives life and brings death, and He is Powerful to do any thing.'),
(5078, 57, 3, 1, 17, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'ہُوَ الۡاَوَّلُ وَ الۡاٰخِرُ وَ الظَّاہِرُ وَ الۡبَاطِنُ ۚ  وَ ہُوَ   بِکُلِّ  شَیۡءٍ عَلِیۡمٌ ﴿۳﴾', 'وہی اول اور وہی آخر اور اپنی قدرتوں سے سب پر ظاہر اور پھر بھی پوشیدہ ہے اور وہ ہر چیز کا خوب جاننے والا ہے۔', 'وہی ہے سب سے پہلا اور سب سے پچھلا [۳] اور باہر اور اندر اور وہ سب کچھ جانتا ہے [۴]', 'He is the First (nothing is before Him) and the Last (nothing is after Him), the Most High (nothing is above Him) and the Most Near (nothing is nearer than Him). And He is the All-Knower of every thing.', 'He is the First and the Last, and the Manifest and the Hidden, and He is All-Knowing about every thing.'),
(5079, 57, 4, 1, 17, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'ہُوَ الَّذِیۡ خَلَقَ السَّمٰوٰتِ  وَ الۡاَرۡضَ فِیۡ سِتَّۃِ  اَیَّامٍ ثُمَّ   اسۡتَوٰی عَلَی الۡعَرۡشِ ؕ یَعۡلَمُ مَا یَلِجُ  فِی الۡاَرۡضِ وَ مَا یَخۡرُجُ مِنۡہَا وَ مَا یَنۡزِلُ مِنَ السَّمَآءِ  وَ مَا یَعۡرُجُ فِیۡہَا ؕ وَ ہُوَ مَعَکُمۡ  اَیۡنَ مَا کُنۡتُمۡ ؕ وَ اللّٰہُ  بِمَا تَعۡمَلُوۡنَ  بَصِیۡرٌ ﴿۴﴾', 'وہی ہے جس نے آسمانوں اور زمین کو چھ دن میں پیدا کیا پھر عرش پر جلوہ افروز ہوا۔ جو چیز زمین میں داخل ہوتی اور جو اس سے نکلتی ہے اور جو آسمان سے اترتی اور جو اس میں چڑھتی ہے سب اسکو معلوم ہے۔ اور تم جہاں کہیں بھی ہو وہ تمہارے ساتھ ہوتا ہے اور جو کچھ تم کرتے ہو اللہ اسکو دیکھ رہا ہے۔', 'وہی ہے جس نے بنائے آسمان اور زمین چھ دن میں پھر قائم ہوا تخت پر [۵] جانتا ہے جو اندر جاتا ہے زمین کے اور جو اُس سے نکلتا ہے [۶] اور جو کچھ اترتا ہے آسمان سے اور جو کچھ اُس میں چڑھتا ہے [۷] اور وہ تمہارے ساتھ ہے جہاں کہیں تم ہو اور اللہ جو تم کرتے ہو اُسکو دیکھتا ہے [۸]', 'He it is Who created the heavens and the earth in six Days and then Istawa (rose over) the Throne (in a manner that suits His Majesty). He knows what goes into the earth and what comes forth from it, what descends from the heaven and what ascends thereto. And He is with you (by His Knowledge) wheresoever you may be. And Allah is the All-Seer of what you do.', 'He is the One who created the heavens and the earth in six days, then He positioned Himself on the Throne. He knows whatever goes into the earth and whatever comes out from it, and whatever descends from the sky, and whatever ascends thereto. He is with you wherever you are, and Allah is watchful of whatever you do.'),
(5080, 57, 5, 1, 17, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'لَہٗ  مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ اِلَی اللّٰہِ  تُرۡجَعُ الۡاُمُوۡرُ ﴿۵﴾', 'آسمانوں اور زمین کی بادشاہی اسی کی ہے۔ اور سب معاملات اسی کی طرف رجوع ہوتے ہیں۔', 'اُسی کے لئے ہے راج آسمانوں کا اور زمین کا اور اللہ ہی تک پہنچتے ہیں سب کام [۹]', 'His is the kingdom of the heavens and the earth. And to Allah return all the matters (for decision).', 'To Him belongs the kingdom of the heavens and the earth, and to Allah all matters are returned.'),
(5081, 57, 6, 1, 17, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'یُوۡلِجُ الَّیۡلَ فِی النَّہَارِ وَ یُوۡلِجُ  النَّہَارَ فِی الَّیۡلِ ؕ وَ ہُوَ عَلِیۡمٌۢ  بِذَاتِ الصُّدُوۡرِ ﴿۶﴾', 'وہی رات کو دن میں داخل کرتا اور دن کو رات میں داخل کرتا ہے۔ اور وہ دلوں کے بھیدوں تک سے واقف ہے۔', 'داخل کرتا ہے رات کو دن مین اور داخل کرتا ہے دن کو رات میں [۱۰] اور اُسکو خبر ہے جیوں کی بات کی [۱۱]', 'He merges night into day (i.e. the decrease in the hours of the night is added into the hours of the day), and merges day into night (i.e. the decrease in the hours of the day is added into the hours of the night), and He has full knowledge of whatsoever is in the breasts.', 'He makes the night enter into the day, and makes the day enter into the night, and He is All-Knowing about whatever lies in the hearts.'),
(5082, 57, 7, 1, 17, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'اٰمِنُوۡا بِاللّٰہِ وَ رَسُوۡلِہٖ  وَ اَنۡفِقُوۡا مِمَّا جَعَلَکُمۡ  مُّسۡتَخۡلَفِیۡنَ فِیۡہِ ؕ فَالَّذِیۡنَ اٰمَنُوۡا مِنۡکُمۡ وَ اَنۡفَقُوۡا لَہُمۡ  اَجۡرٌ کَبِیۡرٌ ﴿۷﴾', 'لوگو اللہ پر اور اس کے رسول ﷺ پر ایمان لاؤ اور جس مال میں اس نے تمکو اپنا نائب بنایا ہے اس میں سے خرچ کرو۔ اب جو لوگ تم میں سے ایمان لائے اور مال خرچ کرتے رہے ان کے لئے بڑا ثواب ہے۔', 'یقین لاؤ اللہ پر اور اُسکے رسول پر اور خرچ کرو اُس میں سے جو تمہارے ہاتھ میں دیا ہے اپنا نائب کر کر [۱۲] سو جو لوگ تم میں یقین لائے ہیں اور خرچ کرتے ہیں اُنکو بڑا ثواب ہے [۱۳]', 'Believe in Allah and His Messenger (Muhammad SAW), and spend of that whereof He has made you trustees. And such of you as believe and spend (in Allahs Way), theirs will be a great reward.', 'Believe in Allah and His Messenger, and spend out of that (wealth) in which He has appointed you as deputies. So, for those of you who have believed and spent (in Allah’s way), there is a big reward.'),
(5083, 57, 8, 1, 17, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'وَ مَا لَکُمۡ لَا تُؤۡمِنُوۡنَ بِاللّٰہِ ۚ وَ الرَّسُوۡلُ یَدۡعُوۡکُمۡ  لِتُؤۡمِنُوۡا بِرَبِّکُمۡ وَ قَدۡ  اَخَذَ مِیۡثَاقَکُمۡ  اِنۡ کُنۡتُمۡ مُّؤۡمِنِیۡنَ  ﴿۸﴾', 'اور تم کیسے لوگ ہو کہ اللہ پر ایمان نہیں لاتے۔ حالانکہ اس کے پیغمبر ﷺ تمہیں بلا رہے ہیں کہ اپنے پروردگار پر ایمان لاؤ اور اگر تمکو یقین ہو تو وہ تم سے اس کا عہد بھی لے چکا ہے۔', 'اور تم کو کیا ہوا کہ یقین نہیں لاتے اللہ پر اور رسول بلاتا ہے تم کو کہ یقین لاؤ اپنے رب پر اور لے چکا ہے تم سے عہد پکا اگر ہو تم ماننے والے [۱۴]', 'And what is the matter with you that you believe not in Allah! While the Messenger (Muhammad SAW) invites you to believe in your Lord (Allah), and He (Allah) has indeed taken your covenant, if you are real believers.', 'What is wrong with you that you do not believe in Allah, while the Messenger invites you to believe in your Lord, and He has taken your covenant, if you are to believe?'),
(5084, 57, 9, 1, 17, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'ہُوَ الَّذِیۡ یُنَزِّلُ عَلٰی عَبۡدِہٖۤ  اٰیٰتٍۭ بَیِّنٰتٍ لِّیُخۡرِجَکُمۡ مِّنَ الظُّلُمٰتِ  اِلَی النُّوۡرِ ؕ وَ اِنَّ اللّٰہَ  بِکُمۡ  لَرَءُوۡفٌ رَّحِیۡمٌ ﴿۹﴾', 'وہی تو ہے جو اپنے بندے پر واضح آیتیں نازل فرماتا ہے تاکہ تمکو اندھیروں سے نکال کر روشنی میں لائے بیشک اللہ تم پر نہایت شفقت کرنے والا ہے مہربان ہے۔', 'وہی ہے جو اتارتا ہے اپنے بندے پر آیتیں صاف کہ نکال لائے تم کو اندھیروں سے اجالے میں اور اللہ تم پر نرمی کرنے والا ہے مہربان [۱۵]', 'It is He Who sends down manifest Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) to His slave (Muhammad SAW) that He may bring you out from darkness into light. And verily, Allah is to you full of kindness, Most Merciful.', 'He is the One who reveals clear verses to His servant, so that He brings you out from layers of darkness into the light. And to you, Allah is Very-Kind indeed, Very-Merciful.'),
(5085, 57, 10, 1, 17, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'وَ مَا  لَکُمۡ   اَلَّا تُنۡفِقُوۡا فِیۡ سَبِیۡلِ اللّٰہِ وَ لِلّٰہِ مِیۡرَاثُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ لَا یَسۡتَوِیۡ  مِنۡکُمۡ مَّنۡ  اَنۡفَقَ مِنۡ قَبۡلِ الۡفَتۡحِ وَ قٰتَلَ ؕ اُولٰٓئِکَ  اَعۡظَمُ  دَرَجَۃً مِّنَ الَّذِیۡنَ اَنۡفَقُوۡا مِنۡۢ  بَعۡدُ وَ قٰتَلُوۡا ؕ وَ کُلًّا وَّعَدَ اللّٰہُ  الۡحُسۡنٰی ؕ وَ اللّٰہُ  بِمَا تَعۡمَلُوۡنَ خَبِیۡرٌ ﴿٪۱۰﴾', 'اور تم کو کیا ہوا ہے کہ اللہ کے رستے میں خرچ نہیں کرتے حالانکہ آسمانوں اور زمین کی وراثت اللہ ہی کی ہے۔ جس شخص نے تم میں سے فتح مکہ سے پہلے خرچ کیا اور جنگ کی وہ اور جس نے یہ کام بعد میں کئے وہ برابر نہیں۔ ان کا درجہ ان لوگوں سے کہیں بڑھ کر ہے جنہوں نے بعد میں مال خرچ کئے اور کفار سے جنگ کی اور اللہ نے سب سے ہی ثواب نیک کا وعدہ کیا ہے۔ اور جو کام تم کرتے ہو اللہ ان سے واقف ہے۔', 'اور تم کو کیا ہوا ہے کہ خرچ نہیں کرتے اللہ کی راہ میں اور اللہ ہی کو بچ رہتی ہر شے آسمانوں میں اور زمین میں [۱۶] برابر نہیں تم میں جس نے کہ خرچ کیا فتح مکہ سے پہلے [۱۷] اور لڑائی کی اُن لوگوں کا درجہ بڑا ہے اُن سے جو کہ خرچ کریں اُسکے بعد اور لڑائی کریں اور سب سے وعدہ کیا ہے اللہ نے خوبی کا [۱۸] اور اللہ کو خبر ہے جو کچھ تم کرتے ہو [۱۹]', 'And what is the matter with you that you spend not in the Cause of Allah? And to Allah belongs the heritage of the heavens and the earth. Not equal among you are those who spent and fought before the conquering (of Makkah) (with those among you who did so later). Such are higher in degree than those who spent and fought afterwards. But to all, Allah has promised the best (reward). And Allah is All-Aware of what you do.', 'And what is wrong with you that you should not spend in the way of Allah, while to Allah belongs the inheritance of the heavens and the earth? Those who spent before the Conquest (of Makkah) and fought are not at par (with others). Those are much greater in rank than those who spent later and fought, though Allah has promised the good (reward) for each. Allah is well aware of what you do.'),
(5086, 57, 11, 2, 18, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'مَنۡ  ذَا الَّذِیۡ یُقۡرِضُ اللّٰہَ  قَرۡضًا حَسَنًا فَیُضٰعِفَہٗ  لَہٗ  وَ لَہٗۤ  اَجۡرٌ کَرِیۡمٌ ﴿ۚ۱۱﴾', 'کون ہے جو اللہ کو نیک نیتی سے قرض دے تو وہ اسکو کئ گنا عطا کرے اور اسکے لئے عزت کا صلہ یعنی جنت ہے۔', 'کون ہے ایسا کہ قرض دے اللہ کو اچھی طرح پھر وہ اُسکو دونا کر دے اُسکے واسطے اور اُسکو ملے ثواب عزت کا [۲۰]', 'Who is he that will lend to Allah a goodly loan, then (Allah) will increase it manifold to his credit (in repaying), and he will have (besides) a good reward (i.e. Paradise).', 'Who is there to advance a loan, a good loan, to Allah so that He multiplies it for him, and he may have a noble reward?'),
(5087, 57, 12, 2, 18, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'یَوۡمَ تَرَی الۡمُؤۡمِنِیۡنَ وَ الۡمُؤۡمِنٰتِ یَسۡعٰی نُوۡرُہُمۡ بَیۡنَ  اَیۡدِیۡہِمۡ وَ بِاَیۡمَانِہِمۡ  بُشۡرٰىکُمُ  الۡیَوۡمَ جَنّٰتٌ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَا ؕ ذٰلِکَ ہُوَ  الۡفَوۡزُ  الۡعَظِیۡمُ ﴿ۚ۱۲﴾', 'جس دن تم مومن مردوں اور مومن عورتوں کو دیکھو گے کہ انکے ایمان کا نور ان کے آگے آگے اور داہنی طرف چل رہا ہے تو ان سے کہا جائے گا کہ تمکو بشارت ہو کہ آج تمہارے لئے باغ ہیں جنکے نیچے نہریں بہ رہی ہیں ان میں تم ہمیشہ رہو گے۔ یہی بڑی کامیابی ہے۔', 'جس دن تو دیکھے ایمان والے مردوں کو اور  ایمان والی عورتوں کو دوڑتی ہوئی چلتی ہے اُنکی روشنی اُنکے آگے اور ان کے داہنے [۲۱] خوشخبری ہے تم کو آج کے  دن باغ ہیں کہ نیچے بہتی ہیں جنکے نہریں سدا رہو اُن میں یہ جو ہے یہی ہے بڑی مراد ملنی [۲۲]', 'On the Day you shall see the believing men and the believing women their light running forward before them and by their right hands. Glad tidings for you this Day! Gardens under which rivers flow (Paradise), to dwell therein forever! Truly, this is the great success!', 'On the Day when you will see the believing men and the believing women, their light proceeding in front of them and to their right hands, (it will be said to them,) “Good news for you today! Gardens beneath which rivers flow, to live therein forever! That is the great achievement,'),
(5088, 57, 13, 2, 18, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'یَوۡمَ یَقُوۡلُ  الۡمُنٰفِقُوۡنَ وَ الۡمُنٰفِقٰتُ لِلَّذِیۡنَ اٰمَنُوا انۡظُرُوۡنَا نَقۡتَبِسۡ مِنۡ نُّوۡرِکُمۡ ۚ  قِیۡلَ ارۡجِعُوۡا وَرَآءَکُمۡ فَالۡتَمِسُوۡا نُوۡرًا ؕ فَضُرِبَ بَیۡنَہُمۡ بِسُوۡرٍ لَّہٗ  بَابٌ ؕ بَاطِنُہٗ  فِیۡہِ الرَّحۡمَۃُ وَ ظَاہِرُہٗ  مِنۡ  قِبَلِہِ  الۡعَذَابُ  ﴿ؕ۱۳﴾', 'اس دن منافق مرد اور منافق عورتیں مومنوں سے کہیں گے کہ ہمارے لئے انتظار کرو کہ ہم بھی تمہارے نور سے روشنی حاصل کریں ان سے کہا جائے گا کہ پیچھے کو لوٹ جاؤ  پس وہاں نور تلاش کرو۔ پھر انکے بیچ میں ایک دیوار کھڑی کر دی جائے گی۔ جس میں ایک دروازہ ہو گا۔ جو اسکی جانب اندرونی ہے اس میں تو رحمت ہے اور جو بیرونی جانب ہے اس طرف عذاب ہے۔', 'جس دن کہیں گے دغاباز مرد اور عورتیں  ایمان والوں کو راہ دیکھو ہماری ہم بھی روشنی لے لیں تمہارے نور سے کہ کوئی کہے گا لوٹ جاؤ پیچھے پھر  ڈھونڈ  لو روشنی پھر کھڑی کر دی جائے اُنکے بیچ میں ایک دیوار جس میں ہوگا دروازہ اُس کے اندر رحمت ہو گی اور باہر کی طرف عذاب [۲۳]', 'On the Day when the hypocrites men and women will say to the believers: \"Wait for us! Let us get something from your light!\" It will be said: \"Go back to your rear! Then seek a light!\" So a wall will be put up between them, with a gate therein. Inside it will be mercy, and outside it will be torment.\"', '- the Day when the hypocrite men and hypocrite women will say to those who believe, “Wait for us, so that we may have a share from your light.”It will be said (to them), “Go back to your rear, and search for light.” Then a wall will be placed between them, which will have a gate. In its inner side, there will be the divine mercy, while towards its outer side, there will be the divine punishment.'),
(5089, 57, 14, 2, 18, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'یُنَادُوۡنَہُمۡ  اَلَمۡ  نَکُنۡ مَّعَکُمۡ ؕ قَالُوۡا بَلٰی وَ لٰکِنَّکُمۡ فَتَنۡتُمۡ  اَنۡفُسَکُمۡ وَ تَرَبَّصۡتُمۡ وَ ارۡتَبۡتُمۡ وَ غَرَّتۡکُمُ الۡاَمَانِیُّ حَتّٰی جَآءَ  اَمۡرُ اللّٰہِ  وَ غَرَّکُمۡ بِاللّٰہِ الۡغَرُوۡرُ ﴿۱۴﴾', 'تو منافق لوگ مومنوں سے کہیں گے کہ کیا ہم دنیا میں تمہارے ساتھ نہ تھے وہ کہیں گے کیوں نہیں تھے۔ لیکن تم نے خود اپنے آپکو بلا میں ڈالا اور ہمارے لئے گردش زمانہ کے منتظر رہے اور اسلام میں شک کیا اور فضول آرزؤں نے تمکو دھوکے میں ڈالے رکھا یہاں تک کہ اللہ کا حکم آ پہنچا اور اللہ کے بارے میں تمکو وہ شیطان بڑا فریبی فریب دیتا رہا۔', 'یہ اُن کو پکاریں گے کیا ہم نہ تھے تمہارے ساتھ [۲۴] کہیں گے کیوں نہیں لیکن تم نے بچلا دیا اپنے آپ کو اور راہ دیکھتے رہے اور دھوکے میں پڑے اور بہک گئے اپنے خیالوں پر  یہاں تک کہ آ پہنچا حکم اللہ کا اور تم کو بہکا دیا اللہ کے نام سے اُس دغاباز نے [۲۵]', '(The hypocrites) will call the believers: \"Were we not with you?\" The believers will reply: \"Yes! But you led yourselves into temptations, you looked forward for our destruction; you doubted (in Faith); and you were deceived by false desires, till the Command of Allah came to pass. And the chief deceiver (Satan) deceived you in respect of Allah.\"', 'They (the hypocrites) will call out to them (the believers), “Were we not with you?” They will say, “Yes, (you were,) but you led your souls to a wrong way, and kept waiting (for an evil end to the Muslims), and remained in doubt, and were deluded by fancies, until Allah’s command came to pass, and you were deceived about Allah by the Big Deceiver (Iblīs).'),
(5090, 57, 15, 2, 18, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'فَالۡیَوۡمَ لَا یُؤۡخَذُ مِنۡکُمۡ فِدۡیَۃٌ  وَّ لَا مِنَ الَّذِیۡنَ  کَفَرُوۡا ؕ مَاۡوٰىکُمُ  النَّارُ ؕ ہِیَ مَوۡلٰىکُمۡ ؕ وَ بِئۡسَ الۡمَصِیۡرُ ﴿۱۵﴾', 'تو آج تم سے کوئی معاوضہ نہیں لیا جائے گا اور نہ کافروں ہی سے قبول کیا جائے گا تم سب کا ٹھکانہ دوزخ ہے کہ وہی تمہارے لائق ہے۔ اور وہ بری جگہ ہے۔', 'سو آج تم سے قبول نہ ہو گا فدیہ دینا اور نہ منکروں سے تم سب کا گھر دوزخ ہے وہی ہے رفیق تمہاری اور بری جگہ جا پہنچے [۲۶]', 'So this Day no ransom shall be taken from you (hypocrites), nor of those who disbelieved, (in the Oneness of Allah Islamic Monotheism). Your abode is the Fire, that is the proper place for you, and worst indeed is that destination.', 'So, no ransom will be accepted from you today, nor from those who disbelieved (openly). Your abode is the Fire, and it is an evil end.”'),
(5091, 57, 16, 2, 18, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'اَلَمۡ یَاۡنِ  لِلَّذِیۡنَ اٰمَنُوۡۤا  اَنۡ  تَخۡشَعَ قُلُوۡبُہُمۡ  لِذِکۡرِ اللّٰہِ  وَ مَا  نَزَلَ مِنَ الۡحَقِّ  ۙ  وَ لَا یَکُوۡنُوۡا کَالَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ مِنۡ قَبۡلُ فَطَالَ عَلَیۡہِمُ  الۡاَمَدُ فَقَسَتۡ قُلُوۡبُہُمۡ ؕ وَ کَثِیۡرٌ  مِّنۡہُمۡ فٰسِقُوۡنَ ﴿۱۶﴾', 'کیا ابھی تک مومنوں کے لئے اس کا وقت نہیں آیا کہ اللہ کی یاد کرنے کے وقت اور قرآن جو حق کی طرف سے نازل ہوا ہے اسکے سننے کے وقت انکے دل نرم ہو جائیں اور وہ ان لوگوں کی طرح نہ ہو جائیں جنکو ان سے پہلے کتابیں دی گئیں تھیں۔ پھر ان پر طویل عرصہ گذر گیا تو انکے دل سخت ہو گئے۔ اور ان میں سے اکثر نافرمان ہیں۔', 'کیا وقت نہیں آیا ایمان والوں کو کہ گڑگڑائیں اُنکے دل اللہ کی یاد سے اور جو اترا ہے سچا دین [۲۷] اور نہ ہوں اُن جیسے جنکو کتاب ملی تھی اس سے پہلے پھر دراز گذری ان پر مدت پھر سخت ہو گئے اُنکے دل اور بہت اُن میں نافرمان ہیں [۲۸]', 'Has not the time come for the hearts of those who believe (in the Oneness of Allah - Islamic Monotheism) to be affected by Allahs Reminder (this Quran), and that which has been revealed of the truth, lest they become as those who received the Scripture (the Taurat (Torah) and the Injeel (Gospel)) before (i.e. Jews and Christians), and the term was prolonged for them and so their hearts were hardened? And many of them were Fasiqoon (rebellious, disobedient to Allah).', 'Has the time not yet come for those who believe that their hearts should be humble for the remembrance of Allah and for the truth that has descended (through revelation)? They must not be like those to whom the Book was given before, but a long period passed on them (in which they did not repent), therefore their hearts became hard, and (thus) many of them are sinners.'),
(5092, 57, 17, 2, 18, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'اِعۡلَمُوۡۤا  اَنَّ اللّٰہَ یُحۡیِ الۡاَرۡضَ بَعۡدَ مَوۡتِہَا ؕ قَدۡ بَیَّنَّا لَکُمُ الۡاٰیٰتِ لَعَلَّکُمۡ  تَعۡقِلُوۡنَ ﴿۱۷﴾', 'جان رکھو کہ اللہ ہی زمین کو اسکے مرنے کے بعد زندہ کرتا ہے۔ ہم نے اپنی نشانیاں تم سے کھول کھول کر بیان کر دی ہیں تاکہ تم سمجھو۔', 'جان رکھو کہ اللہ زندہ کرتا ہے زمین کو اُسکے مرجانے کے بعد ہم نے کھول کر سنا دیے تم کو پتے اگر تم کو سمجھ ہے [۲۹]', 'Know that Allah gives life to the earth after its death! Indeed We have made clear the Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.) to you, if you but understand.', 'Know well that Allah revives the land after its death. We have made the signs clear for you, so that you may understand.'),
(5093, 57, 18, 2, 18, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'اِنَّ  الۡمُصَّدِّقِیۡنَ وَ الۡمُصَّدِّقٰتِ وَ اَقۡرَضُوا اللّٰہَ  قَرۡضًا حَسَنًا یُّضٰعَفُ لَہُمۡ  وَ لَہُمۡ  اَجۡرٌ کَرِیۡمٌ ﴿۱۸﴾', 'جو لوگ خیرات کرنے والے ہیں مرد بھی اور عورتیں بھی اور اللہ کو نیک نیتی سے قرض دیتے ہیں انکو کئ گنا ادا کیا جائے گا اور انکے لئے عزت کا صلہ ہے۔', 'تحقیق جو لوگ خیرات کرنے والے ہیں مرد اور عورتیں اور قرض دیتے ہیں اللہ کو اچھی طرح  اُنکو  ملتا ہے دونا اور اُنکو ثواب ہے عزت کا [۳۰]', 'Verily, those who give Sadaqat (i.e. Zakat and alms, etc.), men and women, and lend to Allah a goodly loan, it shall be increased manifold (to their credit), and theirs shall be an honourable good reward (i.e. Paradise).', 'Surely those men who give Sadaqah (alms) and those women who give Sadaqah and have advanced a good loan to Allah, for them it will be multiplied, and for them there is a noble reward.'),
(5094, 57, 19, 2, 18, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'وَ الَّذِیۡنَ اٰمَنُوۡا بِاللّٰہِ  وَ رُسُلِہٖۤ  اُولٰٓئِکَ ہُمُ الصِّدِّیۡقُوۡنَ ٭ۖ وَ الشُّہَدَآءُ  عِنۡدَ رَبِّہِمۡ ؕ لَہُمۡ  اَجۡرُہُمۡ وَ نُوۡرُہُمۡ ؕ وَ الَّذِیۡنَ کَفَرُوۡا وَ کَذَّبُوۡا بِاٰیٰتِنَاۤ اُولٰٓئِکَ اَصۡحٰبُ الۡجَحِیۡمِ ﴿٪۱۹﴾', 'اور جو لوگ اللہ اور اسکے پیغمبروں پر ایمان لائے یہی اپنے پروردگار کے نزدیک صدیق اور شہید ہیں۔ انکے لئے انکے اعمال کا صلہ ہو گا اور انکے ایمان کی روشنی بھی ہو گی۔ جن لوگوں نے کفر کیا اور ہماری آیتوں کو جھٹلایا وہی اہل دوزخ ہیں۔', 'اور جو لوگ یقین لائے اللہ پر اور اُسکے سب رسولوں پر وہی ہیں سچے ایمان والے اور لوگوں کا احوال بتلانے والے اپنے رب کے پاس اُنکے واسطے ہے اُں کا ثواب اور اُنکی روشنی [۳۱] اور جو لوگ منکر ہوئے اور جھٹلایا ہماری باتوں کو وہ ہیں دوزخ کے لوگ [۳۲]', 'And those who believe in (the Oneness of) Allah and His Messengers, they are the Siddiqoon (i.e. those followers of the Prophets who were first and foremost to believe in them), and the martyrs with their Lord, they shall have their reward and their light. But those who disbelieve (in the Oneness of Allah - Islamic Monotheism) and deny Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), they shall be the dwellers of the blazing Fire.', 'And those who believed in Allah and His messengers, - those are the Siddīqs (the most righteous after prophets) and the Shuhadā’ (martyrs) in the sight of your Lord. For them shall be their reward and their light. As for those who disbelieved and rejected Our verses, they are the inmates of Hell.'),
(5095, 57, 20, 3, 19, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'اِعۡلَمُوۡۤا اَنَّمَا الۡحَیٰوۃُ  الدُّنۡیَا لَعِبٌ وَّ لَہۡوٌ وَّ زِیۡنَۃٌ  وَّ تَفَاخُرٌۢ  بَیۡنَکُمۡ وَ تَکَاثُرٌ فِی الۡاَمۡوَالِ وَ الۡاَوۡلَادِ ؕ کَمَثَلِ غَیۡثٍ اَعۡجَبَ الۡکُفَّارَ نَبَاتُہٗ  ثُمَّ یَہِیۡجُ فَتَرٰىہُ مُصۡفَرًّا ثُمَّ  یَکُوۡنُ حُطَامًا ؕ وَ فِی الۡاٰخِرَۃِ  عَذَابٌ شَدِیۡدٌ ۙ وَّ مَغۡفِرَۃٌ مِّنَ اللّٰہِ وَ رِضۡوَانٌ ؕ وَ مَا الۡحَیٰوۃُ  الدُّنۡیَاۤ   اِلَّا مَتَاعُ  الۡغُرُوۡرِ ﴿۲۰﴾', 'جان رکھو کہ دنیا کی زندگی محض کھیل اور تماشا اور زینت و آرائش اور تمہارے آپس میں فخرو ستائش اور مال و اولاد کی ایک دوسرے سے زیادہ طلب و خواہش ہے اسکی مثال ایسی ہے جیسے بارش کہ اس سے اگنے والی کھیتی کسانوں کو بھلی لگتی ہے پھر وہ کھیتی خوب زور پر آتی ہے پھر اے دیکھنے والے تو اسکو دیکھتا ہے کہ پک کر زرد پڑ جاتی ہے پھر چورا چورا ہو جاتی ہے اور آخرت میں کافروں کے لئے عذاب شدید اور مومنوں کے لئے اللہ کی طرف سے بخشش اور خوشنودی ہے۔ اور دنیا کی زندگی تو دھوکے کا سامان ہے۔', 'جان رکھو کہ دنیا کی زندگانی یہی ہے کھیل اور تماشا اور بناؤ اور بڑائیاں کرنی آپس میں اور بہتایت ڈھونڈنی مال کی اور اولاد کی جیسے حالت ایک مینہ کی جو خوش لگا کسانوں کو  اُس کا سبزہ پھر زور پر آتا ہے پھر تو دیکھے زرد ہو گیا پھر ہو جاتا ہے روندا ہوا گھاس اور آخرت میں سخب عذاب ہے اور معافی بھی ہے اللہ سے اور رضامندی اور دنیا کی زندگانی تو یہی ہے مال دغا کا [۳۳]', 'Know that the life of this world is only play and amusement, pomp and mutual boasting among you, and rivalry in respect of wealth and children, as the likeness of vegetation after rain, thereof the growth is pleasing to the tiller; afterwards it dries up and you see it turning yellow; then it becomes straw. But in the Hereafter (there is) a severe torment (for the disbelievers, evil-doers), and (there is) Forgiveness from Allah and (His) Good Pleasure (for the believers, good-doers), whereas the life of this world is only a deceiving enjoyment.', 'Know well that the worldly life is but a play and an amusement, and a show of beauty, and exchange of boastful claims between you, and a competition of increase in riches and children. (All this is) like a rain, the growth of which attracts the farmers, then it withers, and you see it turning yellow, then it becomes straw. And in the Hereafter there is a severe punishment (for the disbelievers), and forgiveness from Allah and (Allah’s) pleasure (for the believers and the righteous). The worldly life is nothing but a material of delusion.'),
(5096, 57, 21, 3, 19, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'سَابِقُوۡۤا  اِلٰی مَغۡفِرَۃٍ  مِّنۡ رَّبِّکُمۡ  وَ جَنَّۃٍ عَرۡضُہَا کَعَرۡضِ السَّمَآءِ  وَ الۡاَرۡضِ ۙ اُعِدَّتۡ لِلَّذِیۡنَ اٰمَنُوۡا بِاللّٰہِ وَ رُسُلِہٖ ؕ ذٰلِکَ فَضۡلُ اللّٰہِ یُؤۡتِیۡہِ مَنۡ یَّشَآءُ ؕ وَ اللّٰہُ  ذُو الۡفَضۡلِ الۡعَظِیۡمِ ﴿۲۱﴾', 'بندو اپنے پروردگار کی بخشش کی طرف اور جنت کی طرف لپکو جس کا عرض آسمان اور زمین کے عرض کا سا ہے اور وہ ان لوگوں کے لئے تیار کی گئ ہے جو اللہ پر اور اسکے پیغمبروں پر ایمان لائے ہیں۔ یہ اللہ کا فضل ہے جسے چاہے عطا فرمائے اور اللہ بڑے فضل کا مالک ہے۔', 'دوڑو اپنے رب کی معافی کی طرف کو اور بہشت کو [۳۴] جس کا پھیلاؤ ہے جیسے پھیلاؤ  آسمان اور زمین کا [۳۵] تیار رکھی ہے واسطے اُنکے جو یقین لائے اللہ پر اور اسکے رسولوں پر یہ فضل اللہ کا ہے دے اُسکو جسکو چاہے اور اللہ کا فضل بڑا ہے [۳۶]', 'Race one with another in hastening towards Forgiveness from your Lord (Allah), and towards Paradise, the width whereof is as the width of heaven and earth, prepared for those who believe in Allah and His Messengers. That is the Grace of Allah which He bestows on whom He pleases. And Allah is the Owner of Great Bounty.', 'Compete each other in proceeding towards forgiveness from your Lord and to Paradise the width of which is like the width of the sky and the earth. It has been prepared for those who believe in Allah and His messengers. That is the bounty of Allah; He gives it to whomsoever He Wills and Allah is the Lord of the great bounty.'),
(5097, 57, 22, 3, 19, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'مَاۤ  اَصَابَ مِنۡ مُّصِیۡبَۃٍ  فِی الۡاَرۡضِ وَ لَا فِیۡۤ  اَنۡفُسِکُمۡ  اِلَّا فِیۡ  کِتٰبٍ مِّنۡ قَبۡلِ اَنۡ نَّبۡرَاَہَا ؕ اِنَّ  ذٰلِکَ عَلَی اللّٰہِ یَسِیۡرٌ ﴿ۚۖ۲۲﴾', 'کوئی مصیبت زمین میں اور خود تم پر نہیں پڑتی مگر پیشتر اسکے کہ ہم اسکو پیدا کریں ایک کتاب میں لکھی ہوئی ہوتی ہے۔ اور یہ کام اللہ کو آسان ہے۔', 'کوئی آفت نہیں پڑتی ملک میں اور نہ تمہاری جانوں میں جو لکھی نہ ہو ایک کتاب میں پہلے اس سےکہ پیدا کریں ہم اُسکو دنیا میں [۳۷] بیشک یہ اللہ پر آسان ہے [۳۸]', 'No calamity befalls on the earth or in yourselves but is inscribed in the Book of Decrees (Al-Lauh Al-Mahfooz), before We bring it into existence. Verily, that is easy for Allah.', 'No calamity befalls the earth or your own selves, but it is (pre-destined) in a Book before We bring it into being, -Indeed it is easy for Allah.'),
(5098, 57, 23, 3, 19, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'لِّکَیۡلَا تَاۡسَوۡا عَلٰی مَا فَاتَکُمۡ وَ لَا تَفۡرَحُوۡا بِمَاۤ  اٰتٰىکُمۡ ؕ وَ اللّٰہُ  لَا یُحِبُّ کُلَّ  مُخۡتَالٍ فَخُوۡرِۣ ﴿ۙ۲۳﴾', 'تاکہ جو فائدہ تمہیں حاصل نہ ہو سکا اس کا غم نہ کھایا کرو اور جو تمکو اس نے دیا ہو اس پر اترایا نہ کرو اور اللہ کسی اترانے اور شیخی بگھارنے والے کو دوست نہیں رکھتا۔', 'تاکہ تم غم نہ کھایا کرو اُس پر جو ہاتھ نہ آیا اور نہ شیخی کیا کرو اُس پر جو تم کو اُس نے دیا [۳۹] اور اللہ کو خوش نہیں آتا کوئی اترانے والا بڑائی مارنے والا', 'In order that you may not be sad over matters that you fail to get, nor rejoice because of that which has been given to you. And Allah likes not prideful boasters.', '- so that you may neither grieve on what has escaped you, nor over-exult on what He has given to you. And Allah does not love any self-admirer, over-proud,'),
(5099, 57, 24, 3, 19, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'الَّذِیۡنَ  یَبۡخَلُوۡنَ وَ یَاۡمُرُوۡنَ  النَّاسَ بِالۡبُخۡلِ ؕ وَ مَنۡ یَّتَوَلَّ  فَاِنَّ اللّٰہَ  ہُوَ الۡغَنِیُّ  الۡحَمِیۡدُ ﴿۲۴﴾', 'جو خود بھی بخل کریں اور لوگوں کو بھی بخل سکھائیں اور جو شخص روگردانی کرے تو اللہ بھی بے نیاز ہے لائق حمدوثنا ہے۔', 'وہ جو کہ آپ نہ دیں اور سکھلائیں لوگوں کو  بھی نہ دینا [۴۰] اور جو کوئی منہ موڑے تو اللہ آپ ہے بے پروا سب خوبیوں کے ساتھ موصوف [۴۱]', 'Those who are misers and enjoin upon people miserliness (Allah is not in need of their charity). And whosoever turns away (from Faith Allahs Monotheism), then Allah is Rich (Free of all wants), Worthy of all praise.', '-those who are miserly and bid others to be miserly. And whoever turns away, then Allah is the All-Independent, the Ever-Praised.'),
(5100, 57, 25, 3, 19, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'لَقَدۡ  اَرۡسَلۡنَا  رُسُلَنَا بِالۡبَیِّنٰتِ وَ اَنۡزَلۡنَا مَعَہُمُ  الۡکِتٰبَ وَ الۡمِیۡزَانَ لِیَقُوۡمَ النَّاسُ بِالۡقِسۡطِ ۚ  وَ اَنۡزَلۡنَا الۡحَدِیۡدَ فِیۡہِ بَاۡسٌ شَدِیۡدٌ وَّ مَنَافِعُ لِلنَّاسِ وَ لِیَعۡلَمَ اللّٰہُ  مَنۡ یَّنۡصُرُہٗ وَ رُسُلَہٗ  بِالۡغَیۡبِ ؕ اِنَّ اللّٰہَ  قَوِیٌّ عَزِیۡزٌ ﴿٪۲۵﴾', 'ہم نے اپنے پیغمبروں کو کھلی نشانیاں دے کر بھیجا۔ اور ان پر کتابیں نازل کیں اور میزان عدل تاکہ لوگ انصاف پر قائم رہیں۔ اور لوہا پیدا کیا کہ اس میں اسلحہ جنگ کے لحاظ سے زور بھی بہت ہے اور لوگوں کے لئے فائدے بھی ہیں اور اس لئے کہ جو لوگ بن دیکھے اللہ اور اسکے پیغمبروں کی مدد کرتے ہیں اللہ انکو معلوم کرے۔ بیشک اللہ زور آور ہے غالب ہے۔', 'ہم نے بھیجے ہیں اپنے رسول نشانیاں دیکر اور اتاری اُنکے ساتھ کتاب اور ترازو تاکہ لوگ سیدھے رہیں انصاف پر [۴۲] اور ہم نے اتارا لو ہا [۴۳] اُس میں سخت لڑائی ہے اور لوگوں کے کام چلتے ہیں [۴۴] اور تاکہ معلوم کرے اللہ کون مدد کرتا ہے اُسکے رسولوں کی بن دیکھے [۴۵] بیشک اللہ زوآور ہے زبردست [۴۶]', 'Indeed We have sent Our Messengers with clear proofs, and revealed with them the Scripture and the Balance (justice) that mankind may keep up justice. And We brought forth iron wherein is mighty power (in matters of war), as well as many benefits for mankind, that Allah may test who it is that will help Him (His religion), and His Messengers in the unseen. Verily, Allah is All-Strong, All-Mighty.', 'We have indeed sent Our messengers with clear proofs, and sent down with them the Book and the Balance, so that people may uphold equity. And We sent down iron in which there is strong power, and benefits for the people; and (We did it) so that Allah knows the one who helps Him and His messengers without seeing (Him). Surely Allah is Strong, Mighty.'),
(5101, 57, 26, 4, 20, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'وَ لَقَدۡ  اَرۡسَلۡنَا  نُوۡحًا وَّ اِبۡرٰہِیۡمَ وَ جَعَلۡنَا فِیۡ  ذُرِّیَّتِہِمَا النُّبُوَّۃَ  وَ الۡکِتٰبَ فَمِنۡہُمۡ  مُّہۡتَدٍ ۚ وَ کَثِیۡرٌ مِّنۡہُمۡ فٰسِقُوۡنَ ﴿۲۶﴾', 'اور ہم نے نوح  اور ابراہیم  کو پیغمبر بنا کر بھیجا اور انکی اولاد میں پیغمبری اور کتاب کے سلسلے کو وقتاً فوقتاً جاری رکھا سو بعض تو ان میں سے ہدایت پر ہیں۔ اور اکثر ان میں سے نافرمان ہیں۔', 'اور ہم نے بھیجا نوح کو اور ابراہیم کو اور ٹھہرا دی دونوں کی اولاد میں پیغمبری اور کتاب [۴۷] پھر کوئی اُن میں راہ پر ہے اور بہت اُن میں نافرمان ہیں [۴۸]', 'And indeed, We sent Nooh (Noah) and Ibraheem (Abraham), and placed in their offspring Prophethood and Scripture, and among them there is he who is guided, but many of them are Fasiqoon (rebellious, disobedient to Allah).', 'Indeed We sent NūH and Ibrāhīm, and kept the Book and prophet-hood (continuing) in their progeny. So, some of those (to whom they were sent) were on the right path, and many of them were sinners.'),
(5102, 57, 27, 4, 20, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'ثُمَّ قَفَّیۡنَا عَلٰۤی اٰثَارِہِمۡ  بِرُسُلِنَا وَ قَفَّیۡنَا بِعِیۡسَی ابۡنِ مَرۡیَمَ  وَ اٰتَیۡنٰہُ الۡاِنۡجِیۡلَ ۬ۙ وَ جَعَلۡنَا فِیۡ  قُلُوۡبِ الَّذِیۡنَ اتَّبَعُوۡہُ  رَاۡفَۃً  وَّ رَحۡمَۃً ؕ وَ رَہۡبَانِیَّۃَۨ  ابۡتَدَعُوۡہَا مَا کَتَبۡنٰہَا عَلَیۡہِمۡ  اِلَّا ابۡتِغَآءَ رِضۡوَانِ اللّٰہِ  فَمَا رَعَوۡہَا حَقَّ رِعَایَتِہَا ۚ فَاٰتَیۡنَا الَّذِیۡنَ اٰمَنُوۡا مِنۡہُمۡ اَجۡرَہُمۡ ۚ وَ کَثِیۡرٌ  مِّنۡہُمۡ  فٰسِقُوۡنَ ﴿۲۷﴾', 'پھر انکے پیچھے انہی کے قدموں پر اور پیغمبر بھیجے اور انکے پیچھے مریم  کے بیٹے عیسٰی کو بھیجا اور انکو انجیل عنایت کی اور جن لوگوں نے انکی پیروی کی انکے دلوں میں شفقت اور مہربانی ڈالدی۔ اور ترک دنیا والی نئی بات تو خود انہوں نے نکال لی ہم نے انکو اس کا حکم نہیں دیا تھا مگر انہوں نے اپنے خیال میں اللہ کی خوشنودی حاصل کرنے کے لئے آپ ہی ایسا کر لیا تھا پھر جیسا اسکو نباہنا چاہیے تھا نباہ بھی نہ سکے۔ پس جو لوگ ان میں سے ایمان لائے انکو ہم نے ان کا اجر دیا اور ان میں بہت سے نافرمان ہیں۔', 'پھر پیچھے بھیجے اُنکے قدموں پر اپنے رسول [۴۹] اور پیچھے بھیجا ہم نے عیسٰی مریم کے بیٹے کو اور اُسکو ہم نے دی انجیل [۵۰] اور رکھ دی اُس کے ساتھ چلنے والوں کے دل میں نرمی اور مہربانی [۵۱] اور ایک ترک کرنا دنیا کا جو انہوں نے نئی بات نکالی تھی ہم نے نہیں لکھا تھا یہ اُن پر مگر کیاچاہنے کو اللہ کی رضامندی پھر نہ نباہا اُسکو جیسا چاہئے تھا نباہنا [۵۲] پھر دیا ہم نے اُن لوگوں کو جو اُن میں ایماندار تھے اُنکا بدلا اور بہت اُن میں نافرمان ہں [۵۳]', 'Then, We sent after them, Our Messengers, and We sent Iesa (Jesus) son of Maryam (Mary), and gave him the Injeel (Gospel). And We ordained in the hearts of those who followed him, compassion and mercy. But the Monasticism which they invented for themselves, We did not prescribe for them, but (they sought it) only to please Allah therewith, but that they did not observe it with the right observance. So We gave those among them who believed, their (due) reward, but many of them are Fasiqoon (rebellious, disobedient to Allah).', 'Then We made Our messengers follow them one after the other, then We sent after them ‘Īsā, the son of Maryam (Jesus, son of Mary), and gave him the Injīl, and placed compassion and mercy in the hearts of his followers. As for monasticism, it was invented by them; We did not ordain it for them, but (they adopted it) to seek Allah’s pleasure, then could not observe it as was due. So We gave the believers from among them their reward. And many of them are sinners.'),
(5103, 57, 28, 4, 20, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوا اتَّقُوا اللّٰہَ  وَ اٰمِنُوۡا بِرَسُوۡلِہٖ یُؤۡتِکُمۡ کِفۡلَیۡنِ مِنۡ رَّحۡمَتِہٖ وَ یَجۡعَلۡ  لَّکُمۡ  نُوۡرًا تَمۡشُوۡنَ بِہٖ وَ یَغۡفِرۡ لَکُمۡ ؕ وَ اللّٰہُ  غَفُوۡرٌ رَّحِیۡمٌ ﴿ۚۙ۲۸﴾', 'مومنو! اللہ سے ڈرو اور اسکے پیغمبر پر ایمان لاؤ وہ تمہیں اپنی رحمت سے دگنا اجر عطا فرمائے گا اور تمہارے لئے روشنی کر دے گا جس میں تم چلو گے اور تمکو بخش دے گا اور اللہ بخشنے والا ہے مہربان ہے۔', 'اے یمان والو ڈرتے رہو اللہ سے اور یقین لاؤ اُسکے رسول پر دے گا تم کو دو حصے اپنی رحمت سے اور رکھ دے گا تم میں روشنی جس کو لئے پھرو اور تم کو معاف کرے گا اور اللہ معاف کرنے والا ہے مہربان [۵۴]', 'O you who believe (in Moosa (Moses) (i.e. Jews) and Iesa (Jesus) (i.e. Christians))! Fear Allah, and believe too in His Messenger (Muhammad SAW), He will give you a double portion of His Mercy, and He will give you a light by which you shall walk (straight), and He will forgive you. And Allah is Oft-Forgiving, Most Merciful.', 'O you who believe, fear Allah, and believe in His Messenger, and He will give you two shares (of reward) out of His mercy, and will make for you a light whereby you will walk, and will forgive you- And Allah is Most-Forgiving, Very-Merciful.'),
(5104, 57, 29, 4, 20, 27, 'قَالَ فَمَا خَطۡبُکُمۡ', ' الحدید', 'لِّئَلَّا یَعۡلَمَ اَہۡلُ الۡکِتٰبِ  اَلَّا یَقۡدِرُوۡنَ عَلٰی شَیۡءٍ مِّنۡ  فَضۡلِ اللّٰہِ  وَ اَنَّ  الۡفَضۡلَ  بِیَدِ  اللّٰہِ یُؤۡتِیۡہِ  مَنۡ یَّشَآءُ ؕ وَ اللّٰہُ  ذُو الۡفَضۡلِ  الۡعَظِیۡمِ ﴿٪۲۹﴾', 'یہ باتیں اس لئے بیان کی گئ ہیں کہ اہل کتاب جان لیں کہ وہ اللہ کے فضل پر کچھ بھی قدرت نہیں رکھتے۔ اور یہ کہ فضل اللہ ہی کے ہاتھ میں ہے وہ جسکو چاہتا ہے دیتا ہے اور اللہ بڑے فضل کا مالک ہے۔', 'تا کہ نہ جانیں کتاب والے کہ پا نہیں سکتے کوئی چیز اللہ کے فضل میں سے اور یہ کہ بزرگی اللہ کے ہاتھ ہے دیتا ہے جسکو چاہے اور اللہ کا فضل بڑا ہے [۵۵]', 'So that the people of the Scripture (Jews and Christians) may know that they have no power whatsoever over the Grace of Allah, and that (His) Grace is (entirely) in His Hand to bestow it on whomsoever He wills. And Allah is the Owner of Great Bounty.', '- so that the People of the Book may know that they have no control over any thing from Allah’s bounty, and that bounty is in Allah’s hand; He gives it to whom He wills, and Allah is the Lord of the great bounty.'),
(5105, 58, 1, 1, 1, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'قَدۡ سَمِعَ  اللّٰہُ  قَوۡلَ  الَّتِیۡ تُجَادِلُکَ فِیۡ زَوۡجِہَا وَ تَشۡتَکِیۡۤ  اِلَی اللّٰہِ ٭ۖ وَ اللّٰہُ یَسۡمَعُ  تَحَاوُرَکُمَا ؕ اِنَّ اللّٰہَ  سَمِیۡعٌۢ بَصِیۡرٌ ﴿۱﴾', 'اے پیغمبر ﷺ جو عورت تم سے اپنے شوہر کے بارے میں بحث و جدال کرتی اور اللہ سے شکایت رنج و ملال کرتی تھی۔ اللہ نے اسکی التجا سن لی اور اللہ تم دونوں کی گفتگو سن رہا تھا۔ کچھ شک نہیں کہ اللہ سنتا ہے دیکھتا ہے۔', 'سن لی اللہ نے بات اُس عورت کی جو جھگڑتی تھی تجھ سے اپنے خاوند کے حق میں اور جھینکتی تھی اللہ کے آگے [۱] اور اللہ سنتا تھا سوال و جواب تم دونوں کا بیشک اللہ سنتا ہے دیکھتا ہے [۲]', 'Indeed Allah has heard the statement of her (Khaulah bint Thalabah) that disputes with you (O Muhammad SAW) concerning her husband (Aus bin AsSamit), and complains to Allah. And Allah hears the argument between you both. Verily, Allah is All-Hearer, All-Seer.', 'Allah has heard the talk of the woman who was debating with you about her husband, and was complaining to Allah. Allah was hearing the conversation between both of you. Indeed, Allah is All-Hearing, All-Knowing.'),
(5106, 58, 2, 1, 1, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'اَلَّذِیۡنَ یُظٰہِرُوۡنَ مِنۡکُمۡ مِّنۡ  نِّسَآئِہِمۡ مَّا ہُنَّ  اُمَّہٰتِہِمۡ ؕ اِنۡ  اُمَّہٰتُہُمۡ  اِلَّا الِّٰٓیۡٔ وَلَدۡنَہُمۡ ؕ وَ اِنَّہُمۡ  لَیَقُوۡلُوۡنَ مُنۡکَرًا مِّنَ الۡقَوۡلِ وَ زُوۡرًا ؕ وَ اِنَّ اللّٰہَ لَعَفُوٌّ غَفُوۡرٌ ﴿۲﴾', 'جو لوگ تم میں سے اپنی عورتوں کو ماں کہدیتے ہیں وہ انکی مائیں نہیں ہو جاتیں انکی مائیں تو وہی ہیں جنکے بطن سے وہ پیدا ہوئے بیشک وہ نامعقول اور جھوٹی بات کہتے ہیں۔ اور اللہ بڑا معاف کرنے والا ہے بخشنے والا ہے۔', 'جو لوگ ماں کہہ بیٹھیں تم میں سے اپنی عورتوں کو وہ نہیں ہو جاتیں اُنکی مائیں اُنکی مائیں تو وہی ہیں جنہوں نے  اُنکو جنا اور وہ بولتے ہیں ایک ناپسند بات اور جھوٹی [۳] اور اللہ معاف کرنے والا بخشنے والا ہے [۴]', 'Those among you who make their wives unlawful (Az-Zihar ÇáÙåÇÑ) to them by saying to them \"You are like my mothers back.\" They cannot be their mothers. None can be their mothers except those who gave them birth. And verily, they utter an ill word and a lie. And verily, Allah is Oft-Pardoning, Oft-Forgiving.', 'Those of you who declare Zihār against their wives, they are not their mothers. Their mothers are none else but those who gave birth to them. Undoubtedly they utter an evil word and a lie; and Allah is surely Most-Forgiving, Very-Merciful.'),
(5107, 58, 3, 1, 1, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'وَ الَّذِیۡنَ یُظٰہِرُوۡنَ مِنۡ نِّسَآئِہِمۡ ثُمَّ یَعُوۡدُوۡنَ لِمَا قَالُوۡا فَتَحۡرِیۡرُ  رَقَبَۃٍ  مِّنۡ قَبۡلِ  اَنۡ یَّتَمَآسَّا ؕ ذٰلِکُمۡ تُوۡعَظُوۡنَ بِہٖ ؕ وَ اللّٰہُ  بِمَا تَعۡمَلُوۡنَ  خَبِیۡرٌ ﴿۳﴾', 'اور جو لوگ اپنی بیویوں کو ماں کہہ بیٹھیں پھر اپنے قول سے رجوع کر لیں تو انکو قربت سے پہلے ایک غلام آزاد کرنا ضرور ہے۔ مومنو اس حکم سے تمکو نصیحت کی جاتی ہے۔ اور جو کچھ تم کرتے ہو اللہ اس سے خبردار ہے۔', 'اور جو لوگ ماں کہہ بیٹھیں اپنی عورتوں کو پھر کرنا چاہیں وہی کام جسکو کہا ہے تو آزاد کرنا چاہئے ایک بردہ پہلے اس سے کہ آپس میں ہاتھ لگائیں [۵] اس سے تم کو نصیحت ہو گی [۶] اور اللہ خبر رکھتا ہے جو کچھ تم کرتے ہو [۷]', 'And those who make unlawful to them (their wives) (by Az-Zihar ÇáÙåÇÑ) and wish to free themselves from what they uttered, (the penalty) in that case (is) the freeing of a slave before they touch each other. That is an admonition to you (so that you may not return to such an ill thing). And Allah is All-Aware of what you do.', 'Those who declare Zihār against their wives, then retract what they said, obligated on them is to free the neck (of a slave) before the two (spouses) touch one another. This is what you are advised, and Allah is well aware of what you do.'),
(5108, 58, 4, 1, 1, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'فَمَنۡ  لَّمۡ یَجِدۡ فَصِیَامُ شَہۡرَیۡنِ مُتَتَابِعَیۡنِ مِنۡ قَبۡلِ اَنۡ یَّتَمَآسَّا ۚ فَمَنۡ لَّمۡ  یَسۡتَطِعۡ  فَاِطۡعَامُ سِتِّیۡنَ مِسۡکِیۡنًا ؕ ذٰلِکَ لِتُؤۡمِنُوۡا بِاللّٰہِ وَ رَسُوۡلِہٖ ؕ  وَ تِلۡکَ حُدُوۡدُ اللّٰہِ ؕ وَ لِلۡکٰفِرِیۡنَ  عَذَابٌ  اَلِیۡمٌ ﴿۴﴾', 'اب جسکو غلام نہ ملے وہ قربت سے پہلے لگاتار دو مہینے کے روزے رکھے پھر جسکو اس کا بھی مقدور نہ ہو اسے ساٹھ محتاجوں کو کھانا کھلانا چاہیے۔ یہ حکم اس لئے ہے کہ تم اللہ اور رسول کے فرمانبردار ہو جاؤ۔ اور یہ اللہ کی حدیں ہیں اور نہ ماننے والوں کے لئے درد دینے والا عذاب ہے۔', 'پھو جو کوئی نہ پائے تو روزے ہیں دو مہینے کے لگاتار [۸] پہلے اس سے کہ آپس میں چھوئیں پھر جو کوئی یہ نہ کر سکے تو کھانا دینا ہے ساٹھ محتاجوں کا [۹] یہ حکم اس واسطے کہ تابعدار ہو جاؤ اللہ کے اور اُسکے رسول کے [۱۰] اور یہ حدیں باندھی ہیں اللہ کی اور منکروں کے واسطے عذاب ہے دردناک', 'And he who finds not (the money for freeing a slave) must fast two successive months before they both touch each other. And for him who is unable to do so, he should feed sixty of Miskeen (poor). That is in order that you may have perfect Faith in Allah and His Messenger. These are the limits set by Allah. And for disbelievers, there is a painful torment.', 'But whoever does not find (a slave) has to fast for two consecutive months before the two (spouses) touch one another. Then the one who is not able to do so has to feed sixty indigent persons. This is (laid down) so that you believe in Allah and His Messenger. These are the limits set by Allah; and for the disbelievers there is a painful punishment.'),
(5109, 58, 5, 1, 1, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'اِنَّ  الَّذِیۡنَ یُحَآدُّوۡنَ اللّٰہَ  وَ رَسُوۡلَہٗ کُبِتُوۡا کَمَا کُبِتَ الَّذِیۡنَ مِنۡ  قَبۡلِہِمۡ وَ قَدۡ اَنۡزَلۡنَاۤ  اٰیٰتٍۭ بَیِّنٰتٍ ؕ وَ لِلۡکٰفِرِیۡنَ عَذَابٌ  مُّہِیۡنٌ ۚ﴿۵﴾', 'جو لوگ اللہ اور اسکے رسول کی مخالفت کرتے ہیں وہ اسی طرح ذلیل کئے جائیں گے جس طرح ان سے پہلے لوگ ذلیل کئے گئے تھے اور ہم نے صاف صاف آیتیں نازل کر دی ہیں اور جو نہیں مانتے انکو ذلت کا عذاب ہو گا۔', 'جو لوگ کہ مخالفت کرتے ہیں اللہ کی اور اُسکے رسول کی وہ خوار ہوئے جیسے کہ خوار ہوئے ہیں وہ لوگ جو اُن سے پہلے تھے اور ہم نے اتاری ہیں آیتیں بہت صاف اور منکروں کے واسطے عذاب ہے ذلت کا [۱۱]', 'Verily, those who oppose Allah and His Messenger (Muhammad SAW) will be disgraced, as those before them (among the past nation), were disgraced. And We have sent down clear Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.). And for the disbelievers is a disgracing torment.', 'Surely those who oppose Allah and His Messenger shall be disgraced, just as those before them were disgraced. We have sent down clear verses, and for the disbelievers there is a humiliating punishment'),
(5110, 58, 6, 1, 1, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'یَوۡمَ یَبۡعَثُہُمُ اللّٰہُ جَمِیۡعًا فَیُنَبِّئُہُمۡ بِمَا عَمِلُوۡا ؕ اَحۡصٰہُ  اللّٰہُ وَ نَسُوۡہُ ؕ وَ اللّٰہُ عَلٰی کُلِّ  شَیۡءٍ شَہِیۡدٌ ٪﴿۶﴾', 'جس دن اللہ ان سب کو جلا اٹھائے گا تو جو کام وہ کرتے رہے انکو جتائے گا۔ اللہ نے وہ سب کام لکھوا رکھے ہیں اور یہ انکو بھول گئے ہیں۔ اور اللہ ہر چیز سے واقف ہے۔', 'جس دن کہ اٹھائے گا اللہ ان سب کو  پھر جتلائے گا اُنکو اُنکے کئے کام [۱۲] اللہ نے وہ سب گن رکھی ہیں اور وہ بھول گئے اور اللہ کے سامنے ہے ہر چیز [۱۳]', 'On the Day when Allah will resurrect them all together (i.e. the Day of Resurrection) and inform them of what they did. Allah has kept account of it, while they have forgotten it. And Allah is Witness over all things.', 'on the Day when Allah will resurrect them all together, and will tell them what they did; Allah has its full account, while they have forgotten it. Allah is witness to every thing.'),
(5111, 58, 7, 2, 2, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'اَلَمۡ  تَرَ اَنَّ اللّٰہَ یَعۡلَمُ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ؕ مَا یَکُوۡنُ مِنۡ نَّجۡوٰی ثَلٰثَۃٍ  اِلَّا ہُوَ  رَابِعُہُمۡ وَ لَا خَمۡسَۃٍ  اِلَّا ہُوَ سَادِسُہُمۡ وَ لَاۤ  اَدۡنٰی مِنۡ ذٰلِکَ وَ لَاۤ اَکۡثَرَ  اِلَّا ہُوَ مَعَہُمۡ  اَیۡنَ مَا کَانُوۡا ۚ ثُمَّ  یُنَبِّئُہُمۡ بِمَا عَمِلُوۡا یَوۡمَ  الۡقِیٰمَۃِ ؕ اِنَّ اللّٰہَ بِکُلِّ  شَیۡءٍ عَلِیۡمٌ ﴿۷﴾', 'کیا تمکو معلوم نہیں کہ جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے اللہ کو سب معلوم ہے۔ کسی جگہ تین شخصوں کی سرگوشی ہوتی ہے تو اللہ ان میں چوتھا ہوتا ہے اور جہاں پانچ آدمیوں کی سرگوشی ہو تو وہ ان میں چھٹا ہوتا ہے اور نہ اس سے کم یا زیادہ مگر وہ انکے ساتھ ہوتا ہے خواہ وہ کہیں ہوں۔ پھر جو جو کام یہ کرتے رہے ہیں قیامت کے دن اللہ سب انکو بتائے گا بیشک اللہ ہر چیز سے واقف ہے۔', 'تو نے نہیں دیکھا کہ اللہ کو معلوم ہے جو کچھ ہے آسمانوں میں اور جو کچھ ہے زمین میں کہیں نہیں ہوتا مشورہ تین کا جہاں وہ نہیں ہوتا ان میں چوتھا اور نہ پانچ کا جہاں وہ نہیں ہوتا  اُن میں چھٹا اور نہ اُس سے کم اور نہ زیادہ جہاں وہ نہیں ہوتا اُنکے ساتھ جہاں کہیں ہوں [۱۴] پھرجتلا دے گا اُنکو جو کچھ انہوں نے کیا قیامت کے دن بیشک اللہ کو معلوم ہے ہر چیز', 'Have you not seen that Allah knows whatsoever is in the heavens and whatsoever is on the earth? There is no Najwa (secret counsel) of three, but He is their fourth (with His Knowledge, while He Himself is over the Throne, over the seventh heaven), nor of five but He is their sixth (with His Knowledge), not of less than that or more, but He is with them (with His Knowledge) wheresoever they may be; and afterwards on the Day of Resurrection, He will inform them of what they did. Verily, Allah is the All-Knower of everything.', 'Have you not observed that Allah knows everything in the heavens and everything in the earth? No secret consulta-tion takes place between three, but He is fourth of them, nor between five, but He is sixth of them, nor between fewer than that or more, but He is with them wherever they may be. Then He will tell them on the Day of Judgment what they did. Surely Allah is All-Knowing about every thing.'),
(5112, 58, 8, 2, 2, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'اَلَمۡ تَرَ اِلَی الَّذِیۡنَ نُہُوۡا عَنِ النَّجۡوٰی ثُمَّ یَعُوۡدُوۡنَ لِمَا نُہُوۡا عَنۡہُ وَ یَتَنٰجَوۡنَ بِالۡاِثۡمِ وَ الۡعُدۡوَانِ وَ مَعۡصِیَتِ الرَّسُوۡلِ ۫ وَ اِذَا جَآءُوۡکَ حَیَّوۡکَ بِمَا لَمۡ یُحَیِّکَ بِہِ اللّٰہُ ۙ وَ یَقُوۡلُوۡنَ  فِیۡۤ  اَنۡفُسِہِمۡ لَوۡ  لَا یُعَذِّبُنَا اللّٰہُ  بِمَا نَقُوۡلُ ؕ حَسۡبُہُمۡ  جَہَنَّمُ ۚ یَصۡلَوۡنَہَا ۚ فَبِئۡسَ الۡمَصِیۡرُ ﴿۸﴾', 'اے پیغمبر ﷺ کیا تم نے ان لوگوں کو نہیں دیکھا جنکو سرگوشیاں کرنے سے منع کیا گیا تھا۔ پھر جس کام سے منع کیا گیا تھا وہی پھر کرنے لگے اور یہ تو گناہ اور ظلم اور پیغمبر ﷺ کی نافرمانی کی سرگوشیاں کرتے ہیں۔ اور جب تمہارے پاس آتے ہیں تو اللہ تعالیٰ کے بتائے ہوئے الفاظ کے بجائے دوسرے الفاظ میں تمہیں دعا دیتے ہیں۔ اور اپنے دل میں کہتے ہیں کہ اگر یہ واقعی پیغمبر ہیں تو جو کچھ ہم کہتے ہیں اللہ ہمیں اسکی سزا کیوں نہیں دیتا۔ اے پیغمبر ﷺ انکو دوزخ ہی کی سزا کافی ہے۔ یہ اسی میں داخل ہوں گے اور وہ بری جگہ ہے۔', 'تو نے نہ دیکھا اُن لوگوں کو جنکو منع ہوئی کانا پھوسی پھر بھی وہی کرتے ہیں جو منع ہو چکا ہے اور کان میں باتیں کرتے ہیں گناہ کی اور زیادتی کی اور رسول کی نافرمانی کی [۱۵] اور جب آئیں تیرے پاس تجھ کو  وہ دعا دیں جو دعا نہیں دی تجھ کو اللہ نے اور کہتے ہیں اپنے دل میں کیوں نہیں  عذاب کرتا ہم کو اللہ اُس پر جو ہم کہتے ہیں کافی ہے اُنکو دوزخ داخل ہوں گے اس میں سو بری جگہ پہنچے [۱۶]', 'Have you not seen those who were forbidden to hold secret counsels, and afterwards returned to that which they had been forbidden, and conspired together for sin and wrong doing and disobedience to the Messenger (Muhammad SAW ). And when they come to you, they greet you with a greeting wherewith Allah greets you not, and say within themselves: \"Why should Allah punish us not for what we say?\" Hell will be sufficient for them, they will burn therein, and worst indeed is that destination!', 'Did you not see those who were forbidden from holding secret talks; then they do again what they were forbidden to do? They whisper for sinful act and wrongdoing and disobedience of the prophet, and when they come to you, they greet you the way Allah does not greet you, and say to themselves, “Why does Allah not punish us for what we say?” Enough for them is Jahannam (Hell); they will enter it, and it is an evil end.'),
(5113, 58, 9, 2, 2, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا  اِذَا تَنَاجَیۡتُمۡ فَلَا تَتَنَاجَوۡا بِالۡاِثۡمِ وَ الۡعُدۡوَانِ وَ مَعۡصِیَتِ الرَّسُوۡلِ وَ تَنَاجَوۡا بِالۡبِرِّ وَ التَّقۡوٰی ؕ وَ اتَّقُوا اللّٰہَ  الَّذِیۡۤ  اِلَیۡہِ تُحۡشَرُوۡنَ ﴿۹﴾', 'مومنو! جب تم آپس میں سرگوشیاں کرنے لگو تو گناہ اور زیادتی اور پیغمبر کی نافرمانی کی باتیں نہ کرنا بلکہ نیکوکاری اور پرہیزگاری کی باتیں کرنا۔ اور اللہ سے جسکے سامنے جمع کئے جاؤ گے ڈرتے رہنا۔', 'اے ایمان والو جب تم کان میں بات کرو تو مت کرو بات گناہ کی اور زیادتی کی اور رسول کی نافرمانی کی اور بات کرو احسان کی اور پرہیزگاری کی [۱۷] اور ڈرتے رہو اللہ سے جسکے پاس تم کو جمع ہو نا ہے [۱۸]', 'O you who believe! When you hold secret counsel, do it not for sin and wrong-doing, and disobedience towards the Messenger (Muhammad SAW) but do it for Al-Birr (righteousness) and Taqwa (virtues and piety); and fear Allah unto Whom you shall be gathered.', 'O you who believe, when you hold secret counsel, do not whisper for sinful act and wrongdoing and disobedience of the prophet, and do whisper for righteousness and taqwā (piety). And fear Allah, before whom you will be gathered together.'),
(5114, 58, 10, 2, 2, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'اِنَّمَا  النَّجۡوٰی مِنَ الشَّیۡطٰنِ  لِیَحۡزُنَ الَّذِیۡنَ  اٰمَنُوۡا وَ لَیۡسَ بِضَآرِّہِمۡ شَیۡئًا اِلَّا بِاِذۡنِ اللّٰہِ ؕ وَ عَلَی اللّٰہِ  فَلۡیَتَوَکَّلِ الۡمُؤۡمِنُوۡنَ ﴿۱۰﴾', 'منافقوں کی سرگوشیاں تو شیطان کے اکسانے سے ہیں جو اس لئے کی جاتی ہیں کہ مومن ان سے رنجیدہ ہوں مگر اللہ کے حکم کے سوا ان سے انہیں کچھ نقصان نہیں پہنچ سکتا۔ تو مومنوں کو چاہیے کہ اللہ ہی پر بھروسہ رکھیں۔', 'یہ جو ہے کانا پھوسی سو  شیطان کا کام ہے تاکہ دلگیر کرے ایمان والوں کو اور وہ اُن کا کچھ نہ بگاڑے گا بدون اللہ کے حکم کے اور اللہ پر چاہئے کہ بھروسہ کریں ایمان والے [۱۹]', 'Secret counsels (conspiracies) are only from Shaitan (Satan), in order that he may cause grief to the believers. But he cannot harm them in the least, except as Allah permits, and in Allah let the believers put their trust .', 'Whispering (for sinful acts) comes from the ShaiTān (Satan), so that he may grieve those who believe, while it is not harmful to them in the least, except with Allah’s permission. And in Allah the believers must place their trust.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(5115, 58, 11, 2, 2, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'یٰۤاَیُّہَا الَّذِیۡنَ  اٰمَنُوۡۤا  اِذَا  قِیۡلَ  لَکُمۡ تَفَسَّحُوۡا فِی  الۡمَجٰلِسِ فَافۡسَحُوۡا یَفۡسَحِ اللّٰہُ  لَکُمۡ ۚ وَ  اِذَا قِیۡلَ انۡشُزُوۡا فَانۡشُزُوۡا یَرۡفَعِ اللّٰہُ  الَّذِیۡنَ اٰمَنُوۡا مِنۡکُمۡ ۙ وَ الَّذِیۡنَ  اُوۡتُوا  الۡعِلۡمَ دَرَجٰتٍ ؕ وَ اللّٰہُ  بِمَا تَعۡمَلُوۡنَ خَبِیۡرٌ ﴿۱۱﴾', 'مومنو! جب تم سے کہا جائے کہ مجلس میں کھل کر بیٹھو تو کھل کر بیٹھا کرو اللہ تمکو کشادگی بخشے گا۔ اور جب کہا جائے کہ اٹھ کھڑے ہو تو اٹھ کھڑے ہوا کرو جو لوگ تم میں سے ایمان لائے ہیں اور جنکو علم عطا کیا گیا ہے اللہ ان کے درجے بلند کرے گا۔ اور اللہ تمہارے سب کاموں سے واقف ہے۔', 'اے ایمان والو جب کوئی تم کو کہے کہ کھل کر بیٹھو [۲۰] مجلسوں میں تو کھل جاؤ اللہ  کشادگی دے تم کو [۲۱] اور جب کوئی کہے کہ اٹھ کھڑے ہو تو اٹھ کھڑے ہو [۲۲] اللہ بلند کرے گا اُنکے لئے جو کہ ایمان رکھتے ہیں تم میں سے اور علم انکے درجے [۲۳] اور اللہ کو خبر ہے جو کچھ تم کرتے ہو [۲۴]', 'O you who believe! When you are told to make room in the assemblies, (spread out and) make room. Allah will give you (ample) room (from His Mercy). And when you are told to rise up (for prayers, Jihad (holy fighting in Allahs Cause), or for any other good deed), rise up. Allah will exalt in degree those of you who believe, and those who have been granted knowledge. And Allah is Well-Acquainted with what you do.', 'O you who believe, when it is said to you, “Make room (for others) in the sittings”, then make room, and Allah will make room for you (in the Hereafter). And when it is said, “Rise up”, then rise up, and Allah will raise those, in ranks, who have believed and are given knowledge. Allah is well-aware of what you do.'),
(5116, 58, 12, 2, 2, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'یٰۤاَیُّہَا  الَّذِیۡنَ  اٰمَنُوۡۤا  اِذَا  نَاجَیۡتُمُ الرَّسُوۡلَ  فَقَدِّمُوۡا بَیۡنَ یَدَیۡ نَجۡوٰىکُمۡ صَدَقَۃً ؕ ذٰلِکَ خَیۡرٌ لَّکُمۡ وَ اَطۡہَرُ ؕ فَاِنۡ لَّمۡ تَجِدُوۡا فَاِنَّ اللّٰہَ  غَفُوۡرٌ  رَّحِیۡمٌ ﴿۱۲﴾', 'مومنو! جب تم پیغمبر کے کان میں کوئی بات کہو تو بات کہنے سے پہلے مساکین کو کچھ خیرات کر دیا کرو۔ یہ تمہارے لئے بہت بہتر اور پاکیزگی کی بات ہے۔ اور اگر خیرات تمکو میسر نہ آئے تو اللہ بخشنے والا مہربان ہے۔', 'اے ایمان والو جب تم کان میں بات کہنا چاہو رسول سے تو آگے بھیجو اپنی بات کہنے سے  پہلے خیرات یہ بہتر ہے تمہارے حق میں اور بہت ستھرا پھر اگر نہ پاؤ تو اللہ بخشنے والا مہربان ہے [۲۵]', 'O you who believe! When you (want to) consult the Messenger (Muhammad SAW) in private, spend something in charity before your private consultation. That will be better and purer for you. But if you find not (the means for it), then verily, Allah is Oft-Forgiving, Most Merciful.', 'O you who believe, when you consult the Messenger in private, then offer something in charity before your consultation. That is better for you and purer. But if you find nothing (to offer), then Allah is Most-Forgiving, Very-Merciful.'),
(5117, 58, 13, 2, 2, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'ءَاَشۡفَقۡتُمۡ  اَنۡ  تُقَدِّمُوۡا بَیۡنَ یَدَیۡ نَجۡوٰىکُمۡ صَدَقٰتٍ ؕ فَاِذۡ لَمۡ تَفۡعَلُوۡا وَ تَابَ اللّٰہُ  عَلَیۡکُمۡ فَاَقِیۡمُوا الصَّلٰوۃَ وَ اٰتُوا الزَّکٰوۃَ  وَ اَطِیۡعُوا اللّٰہَ  وَ رَسُوۡلَہٗ ؕ وَ اللّٰہُ  خَبِیۡرٌۢ  بِمَا تَعۡمَلُوۡنَ ﴿٪۱۳﴾', 'کیا تم اس سے کہ پیغمبر کے کان میں کوئی بات کہنے سے پہلے خیرات کرو ڈر گئے؟ پھر جب تم نے ایسا نہ کیا اور اللہ نے تمہیں معاف کر دیا تو نماز قائم کرتے رہو اور زکوٰۃ دیتے رہو اور اللہ اور اسکے رسول ﷺ کی فرمانبرداری کرتے رہو۔ اور جو کچھ تم کرتے ہو اللہ اس سے خبردار ہے۔', 'کیا تم ڈر گئے کہ آگے بھیجا کرو کان کی بات سے پہلے خیراتیں سو جب تم نے نہ کیا اور اللہ نے معاف کردیا تم کو تو اب قائم رکھو نماز اور دیتے رہو زکوٰۃ اور حکم پر چلو اللہ کے اور اُسکے رسول کے اور اللہ کو خبر ہے جو کچھ تم کرتے ہو [۲۶]', 'Are you afraid of spending in charity before your private consultation (with him)? If then you do it not, and Allah has forgiven you, then (at least) perform As-Salat (IqamatasSalat) and give Zakat and obey Allah (i.e. do all what Allah and His Prophet SAW order you to do). And Allah is All-Aware of what you do.', 'Have you become afraid of offering charities before your consultation? So when you did not do so, and Allah has forgiven you, then establish Salāh, and pay Zakāh, and obey Allah and His Messenger. And Allah is well aware of what you do.'),
(5118, 58, 14, 3, 3, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'اَلَمۡ  تَرَ  اِلَی الَّذِیۡنَ تَوَلَّوۡا قَوۡمًا غَضِبَ اللّٰہُ عَلَیۡہِمۡ ؕ مَا ہُمۡ مِّنۡکُمۡ وَ لَا مِنۡہُمۡ ۙ وَ  یَحۡلِفُوۡنَ عَلَی الۡکَذِبِ وَ  ہُمۡ یَعۡلَمُوۡنَ ﴿۱۴﴾', 'بھلا تم نے ان لوگوں کو نہیں دیکھا جو ایسے لوگوں سے دوستی کرتے ہیں جن پر اللہ کا غضب ہوا۔ وہ نہ تم میں ہیں نہ ان میں اور جان بوجھ کر جھوٹی باتوں پر قسمیں کھاتے ہیں۔', 'کیا تو نے دیکھا اُن لوگوں کو جو دوست ہوئے ہیں اُس قوم کے جن پر غصہ ہوا ہے اللہ کا [۲۷] نہ وہ تم میں ہیں اور نہ اُن میں ہیں [۲۸] اور قسمیں کھاتے ہیں جھوٹ بات پر اور اُنکو خبر ہے [۲۹]', 'Have you (O Muhammad SAW) not seen those (hypocrites) who take for friends a people upon whom is the Wrath of Allah (i.e. Jews)? They are neither of you (Muslims) nor of them (Jews), and they swear to a lie while they know.', 'Have you not seen those who have friendship with a people with whom Allah is angry. They are neither of you nor of them. They swear false oaths while they know.'),
(5119, 58, 15, 3, 3, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'اَعَدَّ اللّٰہُ  لَہُمۡ عَذَابًا شَدِیۡدًا ؕ اِنَّہُمۡ سَآءَ  مَا  کَانُوۡا یَعۡمَلُوۡنَ ﴿۱۵﴾', 'اللہ نے انکے لئے سخت عذاب تیار کر رکھا ہے۔ یہ جو کچھ کرتے ہیں یقیناً برا ہے۔', 'تیار رکھا ہے اللہ نے اُنکے لئے سخت عذاب [۳۰] بیشک وہ برے کام ہیں جو وہ کرتے ہیں [۳۱]', 'Allah has prepared for them a severe torment. Evil indeed is that which they used to do.', 'Allah has prepared a severe punishment for them. Indeed, evil is what they have been doing.'),
(5120, 58, 16, 3, 3, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'اِتَّخَذُوۡۤا  اَیۡمَانَہُمۡ جُنَّۃً  فَصَدُّوۡا عَنۡ سَبِیۡلِ اللّٰہِ  فَلَہُمۡ عَذَابٌ مُّہِیۡنٌ ﴿۱۶﴾', 'انہوں نے اپنی قسموں کو ڈھال بنا لیا ہے اور لوگوں کو اللہ کے رستے سے روک دیا ہے سو انکے لئے ذلت کا عذاب ہے۔', 'بنا رکھا ہے اپنی قسموں کو ڈھال پھر روکتےہیں اللہ کی راہ سے تو اُنکو ذلت کا عذاب ہے', 'They have made their oaths a screen (for their evil actions). Thus they hinder (men) from the Path of Allah, so they shall have a humiliating torment.', 'They have taken their oaths as a shield, and then have prevented (people) from the way of Allah. Therefore, for them there is a humiliating punishment.'),
(5121, 58, 17, 3, 3, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'لَنۡ  تُغۡنِیَ عَنۡہُمۡ  اَمۡوَالُہُمۡ وَ لَاۤ  اَوۡلَادُہُمۡ مِّنَ اللّٰہِ  شَیۡئًا ؕ اُولٰٓئِکَ اَصۡحٰبُ النَّارِ ؕ ہُمۡ  فِیۡہَا خٰلِدُوۡنَ ﴿۱۷﴾', 'اللہ کے عذاب کے سامنے نہ تو ان کا مال ہی کچھ کام آئے گا اور نہ اولاد ہی کچھ فائدہ دے گی۔ یہ لوگ اہل دوزخ ہیں اس میں ہمیشہ جلتے رہیں گے۔', 'کام نہ آئیں گے اُنکو اُنکے مال اور نہ اُنکی اولاد اللہ کے ہاتھ سے کچھ بھی وہ لوگ ہیں دوزخ کے وہ اُسی میں پڑے رہیں گے [۳۲]', 'Their children and their wealth will avail them nothing against Allah. They will be (the) dwellers of the Fire, to dwell therein forever.', 'Their riches and their children will never benefit them against Allah. They are the inmates of the Fire. They will live there forever,'),
(5122, 58, 18, 3, 3, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'یَوۡمَ یَبۡعَثُہُمُ اللّٰہُ جَمِیۡعًا فَیَحۡلِفُوۡنَ لَہٗ کَمَا یَحۡلِفُوۡنَ لَکُمۡ وَ یَحۡسَبُوۡنَ اَنَّہُمۡ عَلٰی شَیۡءٍ ؕ اَلَاۤ  اِنَّہُمۡ ہُمُ الۡکٰذِبُوۡنَ ﴿۱۸﴾', 'جس دن اللہ ان سب کو جلا اٹھائے گا تو جس طرح تمہارے سامنے قسمیں کھاتے ہیں اسی طرح اسکے سامنے بھی قسمیں کھائیں گے اور خیال کریں گے کہ ایسا کرنے سے کام چل جائے گا۔ سنو یہی تو ہیں جھوٹے۔', 'جس دن جمع کرے گا اللہ  اُن سب کو  پھر قسمیں کھائیں گے اُسکے آگے جیسے کھاتے ہیں تمہارے آگے اور خیال کرتے ہیں کہ وہ کچھ بھلی راہ پر ہیں [۳۳] سنتا ہے وہی ہیں اصل جھوٹے [۳۴]', 'On the Day when Allah will resurrect them all together (for their account), then they will swear to Him as they swear to you (O Muslims). And they think that they have something (to stand upon). Verily, they are liars!', 'the Day Allah will raise all of them, and they will swear before Him as they swear before you, and will think that they have something to stand upon. Be assured that they are sheer liars.'),
(5123, 58, 19, 3, 3, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'اِسۡتَحۡوَذَ  عَلَیۡہِمُ  الشَّیۡطٰنُ  فَاَنۡسٰہُمۡ ذِکۡرَ  اللّٰہِ ؕ اُولٰٓئِکَ حِزۡبُ الشَّیۡطٰنِ ؕ اَلَاۤ  اِنَّ  حِزۡبَ  الشَّیۡطٰنِ ہُمُ  الۡخٰسِرُوۡنَ ﴿۱۹﴾', 'شیطان نے انکو قابو میں کر لیا ہے اور اللہ کی یاد انکو بھلا دی ہے۔ یہ لوگ شیطان کا ٹولہ ہیں اور سن رکھو کہ شیطان کا ٹولہ ہی نقصان اٹھانے والا ہے۔', 'قابو کر لیا ہے اُن پر شیطان نے پھر بھلا دی اُنکو اللہ کی یاد [۳۵]  وہ لوگ ہیں گروہ شیطان کا سنتا ہے جو گروہ ہے شیطان کا وہی خراب ہوتے ہیں [۳۶]', 'Shaitan (Satan) has overtaken them. So he has made them forget the remembrance of Allah. They are the party of Shaitan (Satan). Verily, it is the party of Shaitan (Satan) that will be the losers!', 'The ShaiTān (Satan) has prevailed upon them; so he has made them neglect to remember Allah. They are the party of ShaiTān . Be assured that it is (the members of the) party of ShaiTān that are the losers.'),
(5124, 58, 20, 3, 3, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'اِنَّ  الَّذِیۡنَ یُحَآدُّوۡنَ اللّٰہَ وَ رَسُوۡلَہٗۤ اُولٰٓئِکَ فِی  الۡاَذَلِّیۡنَ ﴿۲۰﴾', 'جو لوگ اللہ اور اسکے رسول ﷺ کی مخالفت کرتے ہیں وہ نہایت ذلیل ہوں گے۔', 'جو لوگ خلاف کرتے ہیں اللہ کا اور اُسکے رسول کا وہ لوگ ہیں سب سے بےقدر لوگوں میں', 'Those who oppose Allah and His Messenger (Muhammad SAW), they will be among the lowest (most humiliated).', 'Indeed, those who oppose Allah and His Messenger, they are among the lowest.'),
(5125, 58, 21, 3, 3, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'کَتَبَ اللّٰہُ  لَاَغۡلِبَنَّ  اَنَا وَ  رُسُلِیۡ ؕ اِنَّ اللّٰہَ  قَوِیٌّ عَزِیۡزٌ ﴿۲۱﴾', 'اللہ نے یہ بات لکھ دی ہے کہ میں اور میرے پیغمبر ضرور غالب رہیں گے۔ بیشک اللہ زورآور ہے صاحب اقتدار ہے۔', 'اللہ لکھ چکا کہ میں غالب ہوں گا اور میرے رسول بیشک اللہ زورآور ہے زبردست [۳۷]', 'Allah has decreed: \"Verily! It is I and My Messengers who shall be the victorious.\" Verily, Allah is All-Powerful, All-Mighty.', 'Allah has written (in His pre-destined decree), “I will certainly prevail, both I and My messengers.” Surely Allah is All-Strong, All-Mighty.'),
(5126, 58, 22, 3, 3, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المجادلۃ', 'لَا تَجِدُ قَوۡمًا یُّؤۡمِنُوۡنَ بِاللّٰہِ وَ الۡیَوۡمِ الۡاٰخِرِ  یُوَآدُّوۡنَ مَنۡ حَآدَّ اللّٰہَ وَ رَسُوۡلَہٗ  وَ لَوۡ کَانُوۡۤا  اٰبَآءَہُمۡ  اَوۡ اَبۡنَآءَہُمۡ  اَوۡ  اِخۡوَانَہُمۡ  اَوۡ عَشِیۡرَتَہُمۡ ؕ اُولٰٓئِکَ  کَتَبَ فِیۡ قُلُوۡبِہِمُ الۡاِیۡمَانَ وَ اَیَّدَہُمۡ  بِرُوۡحٍ مِّنۡہُ ؕ وَ یُدۡخِلُہُمۡ جَنّٰتٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ  فِیۡہَا ؕ رَضِیَ اللّٰہُ  عَنۡہُمۡ وَ رَضُوۡا عَنۡہُ ؕ اُولٰٓئِکَ حِزۡبُ اللّٰہِ ؕ اَلَاۤ اِنَّ  حِزۡبَ اللّٰہِ ہُمُ الۡمُفۡلِحُوۡنَ ﴿٪۲۲﴾', 'جو لوگ اللہ پر اور روز قیامت پر ایمان رکھتے ہیں تم انکو اللہ اور اسکے رسول ﷺ کے دشمنوں سے دوستی کرتے ہوئے نہ دیکھو گے خواہ وہ انکے باپ یا بیٹے یا بھائی یا خاندان ہی کے لوگ ہوں یہ وہ لوگ ہیں جنکے دلوں میں اللہ نے ایمان کو نقش کر دیا ہے اور اپنے فیض سے انکی مدد کی ہے اور وہ انکو بہشتوں میں جنکے نیچے نہریں بہ رہی ہیں داخل کرے گا جن میں وہ ہمیشہ رہیں گے۔ اللہ ان سے خوش اور وہ اللہ سے خوش۔  یہی لوگ اللہ کی جماعت والے ہیں۔  سن رکھو کہ اللہ کی جماعت والے ہی کامیاب ہونگے۔', 'تو نہ پائے گا کسی قوم کو جو یقین رکھتے ہوں اللہ پر اور پچھلے دن پر کہ دوستی کریں ایسوں سے جو مخالف ہوئے اللہ کے اور اُسکے رسول کے خواہ وہ اپنے باپ ہوں یا اپنے بیٹے یا اپنے بھائی یا اپنے گھرانے کے اُنکے دلوں میں اللہ نے لکھ دیا ہے ایمان [۳۸] اور اُنکی مدد کی ہے اپنے غیب کے فیض سے [۳۹] اور داخل کرے گا اُنکو باغوں میں جنکے نیچے بہتی ہیں نہریں ہمیشہ رہیں گے اُن میں اللہ اُن سے راضی اور وہ اُس سے راضی [۴۰] وہ لوگ ہیں گروہ اللہ کا سنتا ہے جو گروہ ہے اللہ کا وہی مراد کو پہنچے [۴۱]', 'You (O Muhammad SAW) will not find any people who believe in Allah and the Last Day, making friendship with those who oppose Allah and His Messenger (Muhammad SAW ), even though they were their fathers, or their sons, or their brothers, or their kindred (people). For such He has written Faith in their hearts, and strengthened them with Rooh (proofs, light and true guidance) from Himself. And We will admit them to Gardens (Paradise) under which rivers flow, to dwell therein (forever). Allah is pleased with them, and they with Him. They are the Party of Allah. Verily, it is the Party of Allah that will be the successful.', 'You will not find those who believe in Allah and in the Hereafter having friendship with those who oppose Allah and His Messenger, even though they may be their fathers or their sons or their brothers or their clan. They are such that Allah has inscribed faith on their hearts, and has supported them with a spirit from Him. He will admit them to gardens beneath which rivers flow, in which they will live forever. Allah is pleased with them, and they are pleased with Allah. Those are the party of Allah. Be assured that it is (the members of) the party of Allah that are the successful.'),
(5127, 59, 1, 1, 4, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'سَبَّحَ  لِلّٰہِ  مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ۚ وَ ہُوَ الۡعَزِیۡزُ  الۡحَکِیۡمُ ﴿۱﴾', 'جو چیزیں آسمانوں میں ہیں اور جو چیزیں زمین میں ہیں سب اللہ کی تسبیح کرتی ہیں اور وہ غالب ہے حکمت والا ہے۔', 'اللہ کی پاکی بیان کرتا ہے جو کچھ ہے آسمانوں میں اور زمین میں  اور وہی ہے زبردست حکمت والا [۱]', 'Whatsoever is in the heavens and whatsoever is on the earth glorifies Allah. And He is the All-Mighty, the All-Wise.', 'Allah’s purity has been proclaimed by all that is in the heavens and all that is in the earth. And He is the All-Mighty, the All-Wise.'),
(5128, 59, 2, 1, 4, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'ہُوَ الَّذِیۡۤ  اَخۡرَجَ الَّذِیۡنَ کَفَرُوۡا مِنۡ اَہۡلِ الۡکِتٰبِ مِنۡ دِیَارِہِمۡ  لِاَوَّلِ الۡحَشۡرِ ؕؔ مَا ظَنَنۡتُمۡ اَنۡ  یَّخۡرُجُوۡا وَ ظَنُّوۡۤا  اَنَّہُمۡ  مَّانِعَتُہُمۡ حُصُوۡنُہُمۡ مِّنَ اللّٰہِ  فَاَتٰىہُمُ اللّٰہُ مِنۡ حَیۡثُ لَمۡ یَحۡتَسِبُوۡا ٭  وَ قَذَفَ فِیۡ  قُلُوۡبِہِمُ  الرُّعۡبَ یُخۡرِبُوۡنَ بُیُوۡتَہُمۡ  بِاَیۡدِیۡہِمۡ  وَ اَیۡدِی الۡمُؤۡمِنِیۡنَ ٭  فَاعۡتَبِرُوۡا یٰۤاُولِی الۡاَبۡصَارِ ﴿۲﴾', 'وہی تو ہے جس نے کفار اہل کتاب کو پہلی لشکر کشی پر ہی انکے گھروں سے نکال دیا۔ مسلمانو!  تمہارے خیال میں بھی نہ تھا کہ وہ نکل جائیں گے اور وہ لوگ یہ سمجھے ہوئے تھے کہ انکے قلعے ان کو اللہ کے عذاب سے بچا لیں گے مگر اللہ نے انکو وہاں سے آ لیا جہاں سے انکو گمان بھی نہ تھا اور اس نے انکے دلوں میں دہشت ڈالدی کہ اپنے گھروں کو خود اپنے ہاتھوں اور مومنوں کے ہاتھوں سے اجاڑنے لگے تو اے بصیرت کی آنکھیں رکھنے والو عبرت حاصل کرو۔', 'وہی ہے جس نے نکال دیا اُنکو جو منکر ہیں کتاب والوں میں اُنکے گھروں سے [۲] پہلے ہی اجتماع پر لشکر کے [۳] تم نہ اٹکل کرتے تھے کہ نکلیں گے اور وہ خیال کرتے تھے کہ اُنکو بچا لیں گے اُنکے قلعے اللہ کے ہاتھ سے پھر پہنچا اُن پر اللہ جہاں سے اُنکو  خیال نہ تھا اور ڈال دی اُنکے دلوں میں دھاک [۴] اجاڑنے لگے اپنے گھر اپنے ہاتھوں اور مسلمانوں کے ہاتھوں [۵] سو عبرت پکڑو اے آنکھ والو [۶]', 'He it is Who drove out the disbelievers among the people of the Scripture (i.e. the Jews of the tribe of Banee An-Nadeer) from their homes at the first gathering. You did not think that they would get out. And they thought that their fortresses would defend them from Allah! But Allahs (Torment) reached them from a place whereof they expected it not, and He cast terror into their hearts, so that they destroyed their own dwellings with their own hands and the hands of the believers. Then take admonition, O you with eyes (to see).', 'He is the One who expelled the disbelievers of the People of the Book from their homes at the time of the first gathering. You did not expect that they would leave, and they deemed that their fortresses would protect them from Allah. But Allah came to them from where they did not expect, and cast fear in their hearts when they were spoiling their homes with their own hands and with the hands of the believers. So, learn a lesson, O you who have eyes to see.'),
(5129, 59, 3, 1, 4, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'وَ لَوۡ لَاۤ  اَنۡ  کَتَبَ اللّٰہُ عَلَیۡہِمُ  الۡجَلَآءَ لَعَذَّبَہُمۡ  فِی الدُّنۡیَا ؕ وَ لَہُمۡ  فِی الۡاٰخِرَۃِ عَذَابُ النَّارِ ﴿۳﴾', 'اور اگر اللہ نے انکے بارے میں جلا وطن کرنا نہ لکھ رکھا ہوتا تو انکو دنیا میں بھی عذاب دے دیتا۔ اور آخرت میں تو انکے لئے آگ کا عذاب تیار ہے ہی۔', 'اور اگر نہ ہوتی یہ بات کہ لکھ دیا تھا اللہ نے اُن پر جلاوطن ہونا تو اُنکو عذاب دیتا دنیا میں اور  آخرت میں ہے اُنکے لئے  آگ کا عذاب [۷]', 'And had it not been that Allah had decreed exile for them, He would certainly have punished them in this world, and in the Hereafter theirs shall be the torment of the Fire.', 'If Allah had not destined exile for them, He would have punished them in the world. And for them in the Hereafter is the torment of the Fire.'),
(5130, 59, 4, 1, 4, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'ذٰلِکَ بِاَنَّہُمۡ  شَآقُّوا اللّٰہَ وَ رَسُوۡلَہٗ ۚ وَ مَنۡ یُّشَآقِّ  اللّٰہَ  فَاِنَّ اللّٰہَ شَدِیۡدُ الۡعِقَابِ ﴿۴﴾', 'یہ اس لئے کہ انہوں نے اللہ اور اسکے رسول ﷺ کی مخالفت کی۔ اور جو شخص اللہ کی مخالفت کرے تو اللہ اسے سخت عذاب دینے والا ہے۔', 'یہ اس لئے کہ وہ مخالف ہوئے اللہ سے اور اُسکے رسول سے اور جو کوئی مخالف ہو اللہ سے تو اللہ کا عذاب سخت ہے [۸]', 'That is because they opposed Allah and His Messenger (Muhammad SAW). And whosoever opposes Allah, then verily, Allah is Severe in punishment.', 'That is because they were hostile to Allah and His Messenger. And whoever has hostility with Allah (must know that) Allah is severe in punishment.'),
(5131, 59, 5, 1, 4, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'مَا  قَطَعۡتُمۡ مِّنۡ  لِّیۡنَۃٍ  اَوۡ  تَرَکۡتُمُوۡہَا قَآئِمَۃً  عَلٰۤی  اُصُوۡلِہَا فَبِاِذۡنِ اللّٰہِ وَ لِیُخۡزِیَ الۡفٰسِقِیۡنَ ﴿۵﴾', 'مومنو! کھجور کے جو درخت تم نے کاٹ ڈالے یا انکو انکی جڑوں پر کھڑا رہنے دیا سو یہ اللہ کے حکم سے تھا اور اس سے مقصود یہ تھا کہ وہ نافرمانوں کو رسوا کرے۔', 'جو کاٹ ڈالا تم نے کھجور کا درخت یا رہنے دیا کھڑا اپنی جڑ پر سو اللہ کے حکم سے [۹] اور تاکہ رسوا کرے نافرمانوں کو [۱۰]', 'What you (O Muslims) cut down of the palm-trees (of the enemy), or you left them standing on their stems, it was by Leave of Allah, and in order that He might disgrace the Fasiqoon (rebellious, disobedient to Allah).', 'Whatever palm-trees you have cut down, or have left them standing on their roots, it was with Allah’s permission, and so that He might disgrace the transgressors.'),
(5132, 59, 6, 1, 4, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'وَ مَاۤ  اَفَآءَ اللّٰہُ  عَلٰی رَسُوۡلِہٖ  مِنۡہُمۡ فَمَاۤ اَوۡجَفۡتُمۡ عَلَیۡہِ مِنۡ خَیۡلٍ وَّ لَا رِکَابٍ وَّ لٰکِنَّ اللّٰہَ یُسَلِّطُ رُسُلَہٗ  عَلٰی مَنۡ یَّشَآءُ ؕ وَ اللّٰہُ  عَلٰی کُلِّ شَیۡءٍ  قَدِیۡرٌ ﴿۶﴾', 'اور اے مسلمانو جو مال اللہ نے اپنے پیغمبر کو ان لوگوں سے جنگ کے بغیر دلوایا ہے اس میں تمہارا کچھ حق نہیں کیونکہ اسکے لئے نہ تم نے گھوڑے دوڑائے نہ اونٹ لیکن اللہ اپنے پیغمبروں کو جن پر چاہتا ہے غالب کر دیتا ہے۔ اور اللہ ہر چیز پر قادر ہے۔', 'اور جو مال کہ لوٹا دیا اللہ نے  اپنے رسول  پر اُن سے سو تم نے نہیں دوڑائے اُس پر گھوڑے اور نہ اونٹ ولیکن اللہ غلبہ دیتا ہے اپنے رسولوں کو جس پر چاہے اور اللہ سب کچھ کر سکتا ہے [۱۱]', 'And what Allah gave as booty (Fai) to His Messenger (Muhammad SAW) from them, for which you made no expedition with either cavalry or camelry. But Allah gives power to His Messengers over whomsoever He wills. And Allah is Able to do all things.', 'And whatever fai’ (left over property) Allah has passed on to His Messenger from them, you had not urged on your horses or camels for it, but Allah gives predominance to His messengers over whomsoever He wills, and Allah is Powerful over every thing.'),
(5133, 59, 7, 1, 4, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'مَاۤ  اَفَآءَ  اللّٰہُ  عَلٰی رَسُوۡلِہٖ  مِنۡ  اَہۡلِ الۡقُرٰی  فَلِلّٰہِ  وَ لِلرَّسُوۡلِ وَ  لِذِی الۡقُرۡبٰی وَ الۡیَتٰمٰی وَ الۡمَسٰکِیۡنِ وَ ابۡنِ السَّبِیۡلِ ۙ کَیۡ لَا یَکُوۡنَ  دُوۡلَۃًۢ  بَیۡنَ الۡاَغۡنِیَآءِ مِنۡکُمۡ ؕ وَ مَاۤ  اٰتٰىکُمُ الرَّسُوۡلُ  فَخُذُوۡہُ ٭ وَ مَا نَہٰىکُمۡ  عَنۡہُ فَانۡتَہُوۡا ۚ وَ  اتَّقُوا اللّٰہَ ؕ اِنَّ اللّٰہَ شَدِیۡدُ الۡعِقَابِ ۘ﴿۷﴾', 'جو مال اللہ نے اپنے پیغمبر ﷺ کو بستیوں والوں سے دلوایا ہے وہ اللہ کے اور پیغمبر کے اور پیغمبر کے قرابت والوں کے اور یتیموں کے اور حاجتمندوں کے اور مسافروں کے لئے ہے تاکہ جو لوگ تم میں دولت مند ہیں انہی کے ہاتھوں میں نہ گردش کرتا رہے اور جو چیز تمکو پیغمبر ﷺ دیں وہ لے لو اور جس چیز منع کریں اس سے باز رہو۔ اور اللہ سے ڈرتے رہو بیشک اللہ سخت عذاب دینے والا ہے۔', 'جو مال لوٹایا اللہ نے اپنے رسول پر بستیوں والوں سے سو اللہ کے واسطے اور رسول کے [۱۲] اور قرابت والے کے [۱۳] اور یتیموں کے اور محتاجوں کے اور مسافر کے تاکہ نہ آئے لینے دینے میں دولتمندوں کے تم میں سے [۱۴] اور جو دے تم کو رسول سو لے لو اور جس سے منع کرے سو چھوڑ دو [۱۵] اور ڈرتے رہو اللہ سے بیشک اللہ کا عذاب سخت ہے [۱۶]', 'What Allah gave as booty (Fai) to His Messenger (Muhammad SAW) from the people of the townships, - it is for Allah, His Messenger (Muhammad SAW), the kindred (of Messenger Muhammad SAW), the orphans, AlMasakin (the poor), and the wayfarer, in order that it may not become a fortune used by the rich among you. And whatsoever the Messenger (Muhammad SAW) gives you, take it, and whatsoever he forbids you, abstain (from it) , and fear Allah. Verily, Allah is Severe in punishment.', 'Whatever fai’ Allah has passed on to His Messenger from the people of the towns is for Allah and for the Messenger, and for the kinsmen and the orphans and the needy and the wayfarer, so that it may not circulate only between the rich among you. And whatever the Messenger gives you, take it, and whatever he forbids you from, abstain (from it). And fear Allah. Indeed Allah is severe in punishment.'),
(5134, 59, 8, 1, 4, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'لِلۡفُقَرَآءِ  الۡمُہٰجِرِیۡنَ  الَّذِیۡنَ  اُخۡرِجُوۡا  مِنۡ  دِیَارِہِمۡ وَ اَمۡوَالِہِمۡ یَبۡتَغُوۡنَ  فَضۡلًا مِّنَ اللّٰہِ  وَ رِضۡوَانًا وَّ یَنۡصُرُوۡنَ اللّٰہَ وَ رَسُوۡلَہٗ ؕ اُولٰٓئِکَ ہُمُ الصّٰدِقُوۡنَ ۚ﴿۸﴾', 'اور ان ضرورت مند مہاجروں کے لئے بھی جو اپنے گھروں اور مالوں سے خارج اور جدا کر دیئے گئے ہیں۔ جو اللہ کے فضل اور اسکی خوشنودی کے طلبگار اور اللہ اور اسکے پیغمبر کے مددگار ہیں۔ یہی لوگ سچے ہیں۔', 'واسطے ان مفلسوں وطن چھوڑنے والوں کے جو  نکالے ہوئے آتے ہیں اپنے گھروں سے اور اپنے مالوں سے ڈھونڈتے آئے ہیں اللہ کا فضل اور اُسکی رضامندی اور مدد کرنے کو اللہ کی اور اسکے رسول کی وہ لوگ وہی  ہیں سچے [۱۷]', '(And there is also a share in this booty) for the poor emigrants, who were expelled from their homes and their property, seeking Bounties from Allah and to please Him. And helping Allah (i.e. helping His religion) and His Messenger (Muhammad SAW). Such are indeed the truthful (to what they say);-', '(And fai’ is especially) for the poor emigrants who were expelled from their homes and properties, while they were seeking Allah’s grace and pleasure, and were helping (the religion of) Allah and His Messenger. They are the truthful.'),
(5135, 59, 9, 1, 4, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'وَ الَّذِیۡنَ  تَبَوَّؤُ الدَّارَ وَ الۡاِیۡمَانَ مِنۡ قَبۡلِہِمۡ یُحِبُّوۡنَ مَنۡ  ہَاجَرَ  اِلَیۡہِمۡ وَ لَا یَجِدُوۡنَ  فِیۡ صُدُوۡرِہِمۡ حَاجَۃً  مِّمَّاۤ اُوۡتُوۡا وَ یُؤۡثِرُوۡنَ  عَلٰۤی  اَنۡفُسِہِمۡ وَ لَوۡ کَانَ بِہِمۡ خَصَاصَۃٌ ؕ۟ وَ مَنۡ یُّوۡقَ شُحَّ نَفۡسِہٖ  فَاُولٰٓئِکَ ہُمُ  الۡمُفۡلِحُوۡنَ ۚ﴿۹﴾', 'اور ان لوگوں کے لئے بھی جو مہاجرین سے پہلے اس گھر یعنی مدینے میں مقیم ہیں اور ایمان میں مضبوط ہیں اور جو لوگ ہجرت کر کے ان کے پاس آتے ہیں وہ ان سے محبت کرتے ہیں اور جو کچھ انکو ملا اس سے اپنے دل میں کچھ خواہش اور خلش نہیں پاتے اور انکو اپنی جانوں پر مقدم رکھتے ہیں خواہ وہ خود بھی فاقے سے ہوںاور جو شخص خود غرضی سے بچا لیا گیا تو ایسے ہی لوگ بامراد ہیں۔', 'اور جو لوگ جگہ پکڑ رہے ہیں اس گھر میں اور  ایمان میں ان سے پہلے سے [۱۸] وہ محبت کرتے ہیں اس سے جو وطن چھوڑ کر آئے انکے  پاس [۱۹] اور نہیں پاتے اپنے دل میں تنگی اس چیز سے جو مہاجرین کو دی جائے اور مقدم رکھتے ہیں اُنکو اپنی جان سے اور اگر چہ ہو اپنے اوپر فاقہ [۲۰] اور  جو بچایا گیا اپنے جی کے لالچ سے تو وہ لوگ ہیں مراد پانے والے  [۲۱]', 'And those who, before them, had homes (in Al-Madinah) and had adopted the Faith, love those who emigrate to them, and have no jealousy in their breasts for that which they have been given (from the booty of Banee An-Nadeer), and give them (emigrants) preference over themselves, even though they were in need of that. And whosoever is saved from his own covetousness, such are they who will be the successful.', 'And (fai’ is also) for those who established themselves in the homeland (of Madīnah) and in faith before the former ones (arrived in Madīnah), who have love for those who emigrated to them, and do not feel in their hearts any ambition for what is given to the former ones (from fai’), and give preference (to them) over themselves, even though they are in poverty. -And those who are saved from the greed of their hearts are the successful.-'),
(5136, 59, 10, 1, 4, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'وَ الَّذِیۡنَ جَآءُوۡ مِنۡۢ  بَعۡدِہِمۡ یَقُوۡلُوۡنَ رَبَّنَا  اغۡفِرۡ لَنَا وَ لِاِخۡوَانِنَا  الَّذِیۡنَ سَبَقُوۡنَا بِالۡاِیۡمَانِ وَ لَا تَجۡعَلۡ  فِیۡ قُلُوۡبِنَا غِلًّا  لِّلَّذِیۡنَ  اٰمَنُوۡا  رَبَّنَاۤ  اِنَّکَ رَءُوۡفٌ  رَّحِیۡمٌ ﴿٪۱۰﴾', 'اور انکے لئے بھی جو ان مہاجرین کے بعد آئے اور دعا کرتے ہیں کہ اے پروردگار ہمارے اور ہمارے بھائیوں کے جو ہم سے پہلے ایمان لائے ہیں گناہ معاف فرما اور مومنوں کی طرف سے ہمارے دل میں کینہ و حسد نہ پیدا ہونے دے اے ہمارے پروردگار تو بڑا شفقت کرنے والا ہے مہربان ہے۔', 'اور واسطے ان لوگوں کے جو آئے اُنکے بعد [۲۲] کہتے ہوئے اے رب بخش ہم کو اور ہمارے بھائیوں کو  جو  ہم سے پہلے داخل ہوئے ایمان میں اور نہ رکھ ہمارے دلوں میں بیر ایمان والوں کا اے رب تو ہی ہے نرمی والا مہربان [۲۳]', 'And those who came after them say: \"Our Lord! Forgive us and our brethren who have preceded us in Faith, and put not in our hearts any hatred against those who have believed. Our Lord! You are indeed full of kindness, Most Merciful.', 'And (fai’ is also) for those who came after them saying, “Our Lord, forgive us and those of our brothers who preceded us in faith, and do not place in our hearts any rancor against those who believe; Surely, Our Lord, you are Very-Kind, Very-Merciful.'),
(5137, 59, 11, 2, 5, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'اَلَمۡ  تَرَ  اِلَی الَّذِیۡنَ نَافَقُوۡا یَقُوۡلُوۡنَ لِاِخۡوَانِہِمُ  الَّذِیۡنَ کَفَرُوۡا مِنۡ  اَہۡلِ الۡکِتٰبِ  لَئِنۡ  اُخۡرِجۡتُمۡ  لَنَخۡرُجَنَّ مَعَکُمۡ  وَ لَا  نُطِیۡعُ  فِیۡکُمۡ  اَحَدًا  اَبَدًا ۙ وَّ اِنۡ  قُوۡتِلۡتُمۡ  لَنَنۡصُرَنَّکُمۡ ؕ وَ اللّٰہُ  یَشۡہَدُ  اِنَّہُمۡ   لَکٰذِبُوۡنَ ﴿۱۱﴾', 'کیا تم نے ان منافقوں کو نہیں دیکھا جو اپنے کافر بھائیوں سے جو اہل کتاب ہیں کہا کرتے ہیں کہ اگر تم جلاوطن کئے گئے تو ہم بھی تمہارے ساتھ نکل چلیں گے اور تمہارے بارے میں کبھی کسی کا کہا نہ مانیں گے۔ اور اگر تم سے جنگ ہوئی تو تمہاری ہی مدد کریں گے۔ مگر اللہ ظاہر کئے دیتا ہے کہ یہ جھوٹے ہیں۔', 'کیا تو نے نہیں دیکھا ان لوگوں کو جو دغاباز ہیں کہتے ہیں اپنے بھائیوں کو کافر  ہیں اہل کتاب میں سے اگر تم کو کوئی نکال دے گا تو ہم بھی نکلیں گے تمہارےساتھ اور کہا نہ مانیں گے کسی کا تمہارے معاملہ میں کبھی اور اگر تم سے لڑائی ہوئی تو ہم تمہاری مدد کریں گے [۲۴] اور اللہ گواہی دیتا ہے کہ  وہ جھوٹے ہیں [۲۵]', 'Have you (O Muhammad SAW) not observed the hypocrites who say to their friends among the people of the Scripture who disbelieve: \"(By Allah) If you are expelled, we (too) indeed will go out with you, and we shall never obey any one against you, and if you are attacked (in fight), we shall indeed help you.\" But Allah is Witness, that they verily, are liars.', 'Did you not see the hypocrites saying to their brothers from those of the people of the Book who are unbelievers, “If you are expelled, we will certainly go out with you, and we will never obey anyone about you. And if you are fought against, we will definitely help you.” Allah bears witness that they are pure liars.'),
(5138, 59, 12, 2, 5, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'لَئِنۡ  اُخۡرِجُوۡا لَا یَخۡرُجُوۡنَ  مَعَہُمۡ ۚ وَ لَئِنۡ  قُوۡتِلُوۡا  لَا یَنۡصُرُوۡنَہُمۡ ۚ وَ لَئِنۡ نَّصَرُوۡہُمۡ  لَیُوَلُّنَّ  الۡاَدۡبَارَ ۟  ثُمَّ لَا یُنۡصَرُوۡنَ ﴿۱۲﴾', 'اگر وہ نکالے گئے تو یہ انکے ساتھ نہیں نکلیں گے۔ اور اگر ان سے جنگ ہوئی تو یہ انکی مدد نہیں کریں گے۔ اور اگر مدد کریں گے بھی تو پیٹھ پھیر کر بھاگ جائیں گے پھر انکو کہیں سے بھی مدد نہ ملے گی۔', 'اگر وہ نکالے جائیں یہ نہ نکلیں گے اُنکے ساتھ اور اگر اُن سےلڑائی ہوئی یہ نہ مدد کریں گے اُنکی [۲۶] اور اگر مدد کریں گے تو بھاگیں گے پیٹھ پھیر کر پھر کہیں نہ مدد پائیں گے [۲۷]', 'Surely, if they (the Jews) are expelled, never will they (hypocrites) go out with them, and if they are attacked, they will never help them. And if they do help them, they (hypocrites) will turn their backs, so they will not be victorious.', 'If they are expelled, they will not go out with them, and if they are fought against, they will not help them. And even if they help them, they will surely turn their backs, then they will not be helped.'),
(5139, 59, 13, 2, 5, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'لَاَنۡتُمۡ  اَشَدُّ رَہۡبَۃً  فِیۡ  صُدُوۡرِہِمۡ  مِّنَ اللّٰہِ ؕ ذٰلِکَ بِاَنَّہُمۡ  قَوۡمٌ لَّا یَفۡقَہُوۡنَ ﴿۱۳﴾', 'مسلمانو تمہاری ہیبت ان لوگوں کے دلوں میں اللہ سے بھی بڑھ کر ہے۔ یہ اس لئے کہ یہ سمجھ نہیں رکھتے۔', 'البتہ تمہارا ڈر زیادہ ہے اُنکے دلوں میں اللہ کے ڈر سے  یہ ا سلئے کہ وہ لوگ سمجھ نہیں رکھتے [۲۸]', 'Verily, you (believers in the Oneness of Allah - Islamic Monotheism) are more awful as a fear in their (Jews of Banee An-Nadeer) breasts than Allah. That is because they are a people who comprehend not (the Majesty and Power of Allah).', 'In fact, your fear in their hearts is greater than (that of) Allah. That is because they are a people who do not understand.'),
(5140, 59, 14, 2, 5, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'لَا یُقَاتِلُوۡنَکُمۡ جَمِیۡعًا  اِلَّا فِیۡ  قُرًی مُّحَصَّنَۃٍ  اَوۡ مِنۡ  وَّرَآءِ  جُدُرٍ ؕ بَاۡسُہُمۡ بَیۡنَہُمۡ  شَدِیۡدٌ ؕ تَحۡسَبُہُمۡ جَمِیۡعًا وَّ قُلُوۡبُہُمۡ شَتّٰی ؕ ذٰلِکَ بِاَنَّہُمۡ  قَوۡمٌ لَّا یَعۡقِلُوۡنَ ﴿ۚ۱۴﴾', 'یہ سب جمع ہو کر بھی تم سے نہیں لڑ سکیں گے مگر بستیوں کے قلعوں میں پناہ لے کر یا دیواروں کی اوٹ سے انکے آپس میں بھی بڑی لڑائی رہتی ہے۔ تم خیال کرتے ہو کہ یہ اکٹھے ہیں حالانکہ انکے دل پھٹے ہوئے ہیں۔ یہ اس لئے کہ یہ بےعقل لوگ ہیں۔', 'لڑ نہ سکیں گے تم سے سب مل کر مگر بستیوں کےکوٹ میں یا دیواروں کی اوٹ میں [۲۹] اُنکی لڑائی آپس میں سخت ہے [۳۰] تو سمجھے وہ اکھٹے ہیں اور اُنکے دل جدا جدا ہو رہے ہیں یہ اس لئے کہ وہ لوگ عقل نہیں رکھتے [۳۱]', 'They fight not against you even together, except in fortified townships, or from behind walls. Their enmity among themselves is very great. You would think they were united, but their hearts are divided, that is because they are a people who understand not.', 'They do not fight you, even assembled together, but in fortified towns, or from behind the walls. Their quarrelling between themselves is severe. You think that they are united, while their hearts are divided. That is because they are a people who have no sense.'),
(5141, 59, 15, 2, 5, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'کَمَثَلِ الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ قَرِیۡبًا ذَاقُوۡا وَبَالَ  اَمۡرِہِمۡ ۚ وَ  لَہُمۡ  عَذَابٌ  اَلِیۡمٌ ﴿ۚ۱۵﴾', 'ان کا حال ان لوگوں کا سا ہے جو ان سے کچھ ہی پیشتر اپنے کرتوت کی سزا کا مزہ چکھ چکے ہیں اور انکے لئے دکھ دینے والا عذاب تیار ہے۔', 'جیسے قصہ اُن لوگوں کا جو ہو چکے ہیں اُن سے پہلے قریب ہی چکھی اُنہوں نے سزا اپنے کام کی اور اُنکے لئے عذاب دردناک ہے [۳۲]', 'They are like their immediate predecessors (the Jews of Banee Qainooqa, who suffered), they tasted the evil result of their conduct, and (in the Hereafter, there is) for them a painful torment;-', 'The example (of Banū NaDīr) is like those who were before them in near past, who tasted the evil consequence of their conduct, and for them (in the Hereafter) there is a painful punishment.'),
(5142, 59, 16, 2, 5, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'کَمَثَلِ الشَّیۡطٰنِ اِذۡ قَالَ  لِلۡاِنۡسَانِ اکۡفُرۡ ۚ فَلَمَّا کَفَرَ  قَالَ  اِنِّیۡ  بَرِیۡٓءٌ مِّنۡکَ  اِنِّیۡۤ  اَخَافُ اللّٰہَ  رَبَّ الۡعٰلَمِیۡنَ ﴿۱۶﴾', 'منافقوں کی مثال شیطان کی سی ہے کہ انسان سے کہتا رہا کہ کافر ہو جا۔ پھر جب وہ کافر ہو گیا تو کہنے لگا کہ مجھے تجھ سے کچھ سروکار نہیں مجھ کو تو اللہ رب العالمین سے ڈر لگتا ہے۔', 'جیسے قصہ شیطان کا جب کہے انسان کو تو منکر ہو پھر جب وہ منکر ہو گیا کہے میں الگ ہوں تجھ سے میں ڈرتا ہوں اللہ سے جو رب ہے سارے جہان کا', '(Their allies deceived them) like Shaitan (Satan), when he says to man: \"Disbelieve in Allah.\" But when (man) disbelieves in Allah, Shaitan (Satan) says: \"I am free of you, I fear Allah, the Lord of the Alameen (mankind, jinns and all that exists)!\"', 'The example (of the hypocrites) is like the ShaiTān when he says to a human being, “Become disbeliever” then once he disbelieves, he says, “I disown you; I fear Allah, the Lord of the worlds.”'),
(5143, 59, 17, 2, 5, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'فَکَانَ عَاقِبَتَہُمَاۤ  اَنَّہُمَا فِی النَّارِ خَالِدَیۡنِ فِیۡہَا ؕ وَ ذٰلِکَ  جَزٰٓؤُا الظّٰلِمِیۡنَ ﴿٪۱۷﴾', 'تو دونوں کا انجام یہ ہوا کہ دونوں دوزخ میں جائیں گے ہمیشہ اس میں رہیں گے۔ اور بے انصافوں کی یہی سزا ہے۔', 'پھر انجام دونوں کا یہی کہ وہ دونوں ہیں آگ میں ہمیشہ رہیں اُسی میں اور یہی ہے سزا گنہگاروں کی [۳۳]', 'So the end of both will be that they will be in the Fire, abiding therein. Such is the recompense of the Zalimoon (i.e. polytheists, wrong-doers, disbelievers in Allah and in His Oneness, etc.).', 'So the end of both of them is that they will be in the Fire, living there forever. That is the punishment of the wrongdoers.'),
(5144, 59, 18, 3, 6, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوا اتَّقُوا اللّٰہَ  وَ لۡتَنۡظُرۡ  نَفۡسٌ مَّا قَدَّمَتۡ لِغَدٍ ۚ وَ اتَّقُوا اللّٰہَ ؕ اِنَّ اللّٰہَ  خَبِیۡرٌۢ   بِمَا تَعۡمَلُوۡنَ ﴿۱۸﴾', 'اے ایمان والو! اللہ سے ڈرتے رہو اور ہر شخص کو دیکھنا چاہیے کہ اس نے کل یعنی آخرت کے لئے کیا سامان بھیجا ہے اور ہم پھر کہتے ہیں کہ اللہ سے ڈرتے رہو بیشک اللہ تمہارے سب اعمال سے خبردار ہے۔', 'اے ایمان والو ڈرتے رہو اللہ سے اور چاہیے کہ دیکھ لے ہر ایک جی کیا بھیجتا ہے کل کے واسطے [۳۴] اور ڈرتے رہو اللہ سے بیشک اللہ کو خبر ہے جو تم کرتے ہو [۳۵]', 'O you who believe! Fear Allah and keep your duty to Him. And let every person look to what he has sent forth for the morrow, and fear Allah. Verily, Allah is All-Aware of what you do .', 'O you who believe, fear Allah, and everybody must consider what he (or she) has sent ahead for tomorrow. And fear Allah. Surely Allah is fully aware of what you do.'),
(5145, 59, 19, 3, 6, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'وَ لَا تَکُوۡنُوۡا کَالَّذِیۡنَ نَسُوا اللّٰہَ فَاَنۡسٰہُمۡ  اَنۡفُسَہُمۡ ؕ اُولٰٓئِکَ ہُمُ الۡفٰسِقُوۡنَ ﴿۱۹﴾', 'اور ان لوگوں جیسے نہ ہو جانا جنہوں نے اللہ کو بھلا دیا تو اللہ نے انہیں ایسا کر دیا کہ وہ خود اپنے آپکو بھول گئے۔ یہی لوگ ہیں نافرمان۔', 'اور مت ہو اُن جیسے جنہوں نے بھلا دیا اللہ کو پر اللہ نے بھلا دیے اُنکو  اُن کے جی وہ لوگ وہی ہیں نافرمان [۳۶]', 'And be not like those who forgot Allah (i.e. became disobedient to Allah) and He caused them to forget their ownselves, (let them to forget to do righteous deeds). Those are the Fasiqoon (rebellious, disobedient to Allah).', 'Do not be like those who forgot Allah, so He made them forget their own selves. Those are the sinners.'),
(5146, 59, 20, 3, 6, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'لَا یَسۡتَوِیۡۤ  اَصۡحٰبُ النَّارِ وَ اَصۡحٰبُ الۡجَنَّۃِ ؕ اَصۡحٰبُ الۡجَنَّۃِ ہُمُ الۡفَآئِزُوۡنَ ﴿۲۰﴾', 'اہل دوزخ اور اہل بہشت برابر نہیں اہل بہشت ہی کامیابی حاصل کرنے والے ہیں۔', 'برابر نہیں دوزخ  والے اور بہشت والے بہشت والے جو ہیں وہی ہیں مراد پانے والے [۳۷]', 'Not equal are the dwellers of the Fire and the dwellers of the Paradise. It is the dwellers of Paradise that will be successful.', 'The people of Hell and the people of Paradise are not equal. The people of Paradise are the successful.'),
(5147, 59, 21, 3, 6, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'لَوۡ اَنۡزَلۡنَا ہٰذَا الۡقُرۡاٰنَ عَلٰی جَبَلٍ لَّرَاَیۡتَہٗ  خَاشِعًا مُّتَصَدِّعًا مِّنۡ خَشۡیَۃِ اللّٰہِ ؕ وَ تِلۡکَ الۡاَمۡثَالُ نَضۡرِبُہَا لِلنَّاسِ لَعَلَّہُمۡ یَتَفَکَّرُوۡنَ ﴿۲۱﴾', 'اگر ہم یہ قرآن کسی پہاڑ پر نازل کرتے تو تم اسکو دیکھتے کہ اللہ کے خوف سے دبا اور پھٹا جاتا ہے۔ اور یہ مثالیں ہم لوگوں کے لئے بیان کرتے ہیں تاکہ وہ غور کریں۔', 'اگر ہم اتارتے یہ قرآن ایک پہاڑ پر تو تُو دیکھ لیتا کہ وہ دب جاتا پھٹ جاتا اللہ کے ڈر سے [۳۸] اور یہ مثالیں ہم سناتے ہیں لوگوں کو تاکہ وہ غور کریں [۳۹]', 'Had We sent down this Quran on a mountain, you would surely have seen it humbling itself and rending asunder by the fear of Allah. Such are the parables which We put forward to mankind that they may reflect .', 'Had We sent down this Qur’ān to a mountain, you would have seen it humbled, burst apart out of awe for Allah. We cite such examples for people, so that they may ponder.'),
(5148, 59, 22, 3, 6, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'ہُوَ اللّٰہُ  الَّذِیۡ  لَاۤ  اِلٰہَ  اِلَّا ہُوَ ۚ عٰلِمُ الۡغَیۡبِ وَ الشَّہَادَۃِ ۚ ہُوَ  الرَّحۡمٰنُ الرَّحِیۡمُ ﴿۲۲﴾', 'وہی اللہ ہے جس کے سوا کوئی معبود نہیں۔ پوشیدہ اور ظاہر کا جاننے والا۔ وہ بڑا مہربان ہے نہایت رحم والا ہے۔', 'وہ اللہ ہے جس کے سوائے بندگی نہیں کسی کی جانتا ہے جو پوشیدہ ہے اور جو ظاہر ہے وہ ہے بڑا مہربان رحم والا', 'He is Allah, than Whom there is La ilaha illa Huwa (none has the right to be worshipped but He) the All-Knower of the unseen and the seen (open). He is the Most Beneficent, the Most Merciful.', 'He is Allah, besides whom there is no god, the Knower of the unseen and the seen. He is All-Merciful, Very-Merciful.'),
(5149, 59, 23, 3, 6, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'ہُوَ اللّٰہُ  الَّذِیۡ  لَاۤ  اِلٰہَ  اِلَّا ہُوَ ۚ اَلۡمَلِکُ الۡقُدُّوۡسُ السَّلٰمُ  الۡمُؤۡمِنُ الۡمُہَیۡمِنُ الۡعَزِیۡزُ  الۡجَبَّارُ  الۡمُتَکَبِّرُ ؕ سُبۡحٰنَ اللّٰہِ عَمَّا  یُشۡرِکُوۡنَ ﴿۲۳﴾', 'وہی اللہ ہے جس کے سوا کوئی عبادت کے لائق نہیں۔ بادشاہ حقیقی ہر عیب سے پاک سلامتی دینے والا امن دینے والا نگہبان غالب زبردست بڑائی والا۔ اللہ مشرکوں کے شرک سے پاک ہے۔', 'وہ اللہ ہے جس کے سوائے بندگی نہیں کسی کی وہ بادشاہ ہے پاک ذات سب عیبوں سے سالم [۴۰] امان دینے والا [۴۱] پناہ میں لینے والا زبردست دباؤ والا صاحب عظمت پاک ہے اللہ اُنکے شریک بتلانے سے [۴۲]', 'He is Allah than Whom there is La ilaha illa Huwa (none has the right to be worshipped but He) the King, the Holy, the One Free from all defects, the Giver of security, the Watcher over His creatures, the All-Mighty, the Compeller, the Supreme. Glory be to Allah! (High is He) above all that they associate as partners with Him.', 'He is Allah, besides whom there is no god, the Sovereign, the Supreme-In-Holiness, the Safe (from all defects), the Giver-Of-Peace, the Guardian, the All-Mighty, the All-Repairer, the Sublime. Pure is Allah from what they associate with Him.'),
(5150, 59, 24, 3, 6, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الحشر', 'ہُوَ اللّٰہُ  الۡخَالِقُ الۡبَارِئُ  الۡمُصَوِّرُ لَہُ الۡاَسۡمَآءُ  الۡحُسۡنٰی ؕ یُسَبِّحُ لَہٗ  مَا فِی السَّمٰوٰتِ وَ الۡاَرۡضِ ۚ وَ ہُوَ الۡعَزِیۡزُ الۡحَکِیۡمُ ﴿٪۲۴﴾', 'وہی اللہ تمام مخلوقات کا خالق۔ ایجاد و اختراع کرنے والا صورتیں بنانے والا اسکے سب اچھے سے اچھے نام ہیں۔ جتنی چیزیں آسمانوں اور زمین میں ہیں سب اسکی تسبیح کرتی رہتی ہیں۔ اور وہ غالب ہے حکمت والا ہے۔', 'وہ اللہ ہے بنانے والا نکال کھڑا کرنے والا [۴۳] صورت کھینچنے والا [۴۴] اُسی کے ہیں سب نام خاصے (عمدہ) [۴۵] پاکی بول رہا ہے اُسکی جو کچھ ہے آسمانوں میں اور زمین میں [۴۶] اور وہی ہے زبردست حکمتوں والا [۴۷]', 'He is Allah, the Creator, the Inventor of all things, the Bestower of forms. To Him belong the Best Names . All that is in the heavens and the earth glorify Him. And He is the All-Mighty, the All-Wise.', 'He is Allah, the Creator, the Inventor, the Shaper. His are the Most Beautiful Names. His purity is proclaimed by all that is in the heavens and the earth, and He is the All-Mighty, the All-Wise.'),
(5151, 60, 1, 1, 7, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' الممتحنۃ', 'یٰۤاَیُّہَا  الَّذِیۡنَ  اٰمَنُوۡا  لَا تَتَّخِذُوۡا عَدُوِّیۡ  وَ عَدُوَّکُمۡ  اَوۡلِیَآءَ  تُلۡقُوۡنَ اِلَیۡہِمۡ  بِالۡمَوَدَّۃِ  وَ قَدۡ کَفَرُوۡا بِمَا جَآءَکُمۡ  مِّنَ الۡحَقِّ ۚ یُخۡرِجُوۡنَ الرَّسُوۡلَ وَ  اِیَّاکُمۡ  اَنۡ  تُؤۡمِنُوۡا بِاللّٰہِ رَبِّکُمۡ ؕ اِنۡ کُنۡتُمۡ خَرَجۡتُمۡ جِہَادًا فِیۡ سَبِیۡلِیۡ وَ ابۡتِغَآءَ  مَرۡضَاتِیۡ ٭ۖ  تُسِرُّوۡنَ اِلَیۡہِمۡ  بِالۡمَوَدَّۃِ ٭ۖ وَ اَنَا  اَعۡلَمُ  بِمَاۤ اَخۡفَیۡتُمۡ وَ مَاۤ  اَعۡلَنۡتُمۡ  ؕ وَ مَنۡ یَّفۡعَلۡہُ مِنۡکُمۡ فَقَدۡ ضَلَّ  سَوَآءَ  السَّبِیۡلِ ﴿۱﴾', 'مومنو! اگر تم میری راہ میں لڑنے اور میری خوشنودی طلب کرنے کے لئے مکے سے نکلے ہو تو میرے اور اپنے دشمنوں کو دوست نہ بناؤ تم تو انکو دوستی کے پیغام بھیجتے ہو اور وہ دین حق سے جو تمہارے پاس آیا ہے منکر ہیں اور اس وجہ سے کہ تم اپنے پروردگار یعنی اللہ تعالیٰ پر ایمان لائے ہو پیغمبر ﷺ کو اور تمکو جلاوطن کرتے ہیں تم انکی طرف پوشیدہ پوشیدہ دوستی کے پیغام بھیجتے ہو۔ اور جو کچھ تم مخفی طور پر اور جو علی الاعلان کرتے ہو وہ مجھے معلوم ہے۔ اور جو کوئی تم میں سے ایسا کرے گا وہ سیدھے رستے سے بھٹک گیا۔', '[ا] اے ایمان والو نہ پکڑو میرےاور اپنے دشمنوں کو دوست تم اُنکو پیغام بھیجتےہو دوستی سے [۲] اور وہ منکر ہوئے ہیں اُس سے جو تمہارے پاس آیا سچا دین [۳] نکالتے ہیں رسول کو اور تم کو اس بات پر کہ تم مانتے ہو اللہ کو جو رب ہے تمہارا [۴] اگر تم نکلے ہو لڑنے کو میری راہ میں اور طلب کرنے کو میری رضامندی [۵] تم اُنکو چھپا کر بھیجتے ہو دوستی کے پیغام اور مجھ کو خوب معلوم ہے جو چھپایا تم نے اور جو ظاہر کیا تم نے [۶] اور جو کوئی تم میں یہ کام کرے تو وہ بھول گیا سیدھی راہ [۷]', 'O you who believe! Take not My enemies and your enemies (i.e. disbelievers and polytheists, etc.) as friends, showing affection towards them, while they have disbelieved in what has come to you of the truth (i.e. Islamic Monotheism, this Quran, and Muhammad SAW), and have driven out the Messenger (Muhammad SAW) and yourselves (from your homeland) because you believe in Allah your Lord! If you have come forth to strive in My Cause and to seek My Good Pleasure, (then take not these disbelievers and polytheists, etc., as your friends). You show friendship to them in secret, while I am All-Aware of what you conceal and what you reveal. And whosoever of you (Muslims) does that, then indeed he has gone (far) astray, (away) from the Straight Path .', 'O you who believe, do not take My enemies and your enemies for friends, expressing love with them, while they have rejected the Truth that has come to you, expelling the Messenger and your selves (from Makkah) merely because you have faith in Allah who is your Lord, if you have set out to do Jihād (struggle) in My way, and to seek My pleasure. You express love with them secretly, while I know what you have concealed and what you have revealed. Any of you who does this has missed the straight path.'),
(5152, 60, 2, 1, 7, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' الممتحنۃ', 'اِنۡ  یَّثۡقَفُوۡکُمۡ یَکُوۡنُوۡا  لَکُمۡ  اَعۡدَآءً وَّ یَبۡسُطُوۡۤا اِلَیۡکُمۡ اَیۡدِیَہُمۡ وَ اَلۡسِنَتَہُمۡ بِالسُّوۡٓءِ  وَ  وَدُّوۡا  لَوۡ  تَکۡفُرُوۡنَ ؕ﴿۲﴾', 'اگر یہ کافر تم پر قدرت پالیں تو تمہارے دشمن ہو جائیں اور ایذا کے لئے تم پر ہاتھ بھی چلائیں اور زبانیں بھی اور یہ چاہتے ہیں کہ تم کسی طرح کافر ہو جاؤ۔', 'اگر تم اُنکے ہاتھ آ جاؤ  ہو جائیں تمہارے دشمن اور چلائیں تم پر اپنے ہاتھ اور اپنی زبانیں برائی کے ساتھ اور چاہیں کہ کسی طرح تم بھی منکر ہو جاؤ [۸]', 'Should they gain the upper hand over you, they would behave to you as enemies, and stretch forth their hands and their tongues against you with evil, and they desire that you should disbelieve.', 'Should they have access to you, they will become your enemies, and will stretch their hands and tongues towards you with evil; and they desire that you should reject the (true) faith.'),
(5153, 60, 3, 1, 7, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' الممتحنۃ', 'لَنۡ  تَنۡفَعَکُمۡ اَرۡحَامُکُمۡ وَ لَاۤ  اَوۡلَادُکُمۡ ۚۛ یَوۡمَ الۡقِیٰمَۃِ ۚۛ یَفۡصِلُ بَیۡنَکُمۡ ؕ وَ اللّٰہُ  بِمَا تَعۡمَلُوۡنَ بَصِیۡرٌ ﴿۳﴾', 'قیامت کے دن نہ تمہارے رشتے ناتے کام آئیں گے اور نہ اولاد۔ اس روز وہی تم میں فیصلہ کرے گا۔ اور جو کچھ تم کرتے ہو اللہ اسکو دیکھتا ہے۔', 'ہرگز کام نہ آئیں گے تمہارے کنبے والے اور نہ تمہاری اولاد قیامت کے دن وہ فیصلہ کرے گا تم میں اور اللہ جو تم کرتے ہو دیکھتا ہے [۹]', 'Neither your relatives nor your children will benefit you on the Day of Resurrection (against Allah). He will judge between you. And Allah is the All-Seer of what you do.', 'Neither your womb-relations nor your children will benefit you on the Day of Judgment. He will decide between you, and Allah is watchful of what you do.'),
(5154, 60, 4, 1, 7, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' الممتحنۃ', 'قَدۡ کَانَتۡ لَکُمۡ  اُسۡوَۃٌ  حَسَنَۃٌ  فِیۡۤ اِبۡرٰہِیۡمَ وَ الَّذِیۡنَ مَعَہٗ ۚ اِذۡ  قَالُوۡا لِقَوۡمِہِمۡ  اِنَّا بُرَءٰٓؤُا مِنۡکُمۡ وَ مِمَّا تَعۡبُدُوۡنَ مِنۡ دُوۡنِ اللّٰہِ ۫  کَفَرۡنَا بِکُمۡ  وَ بَدَا بَیۡنَنَا وَ بَیۡنَکُمُ  الۡعَدَاوَۃُ وَ الۡبَغۡضَآءُ  اَبَدًا حَتّٰی تُؤۡمِنُوۡا بِاللّٰہِ وَحۡدَہٗۤ  اِلَّا  قَوۡلَ  اِبۡرٰہِیۡمَ  لِاَبِیۡہِ لَاَسۡتَغۡفِرَنَّ  لَکَ وَ مَاۤ  اَمۡلِکُ لَکَ مِنَ اللّٰہِ مِنۡ شَیۡءٍ ؕ رَبَّنَا عَلَیۡکَ تَوَکَّلۡنَا وَ اِلَیۡکَ اَنَبۡنَا وَ  اِلَیۡکَ الۡمَصِیۡرُ ﴿۴﴾', 'مسلمانو تمہیں ابراہیم اور انکے رفقاء کی نیک سیرت کو اپنانا ضروری ہے۔ جب انہوں نے اپنی قوم کے لوگوں سے کہا کہ ہم تم سے اور ان بتوں سے جنکو تم اللہ کے سوا پوجتے ہو بے تعلق ہیں ہم تمہارے معبودوں کے کبھی قائل نہیں ہو سکتے اور جب تک تم ایک اللہ پر ایمان نہ لاؤ ہم میں تم میں ہمیشہ کھلم کھلا عداوت اور دشمنی رہے گی۔ ہاں ابراہیم  نے اپنے باپ سے یہ ضرور کہا تھا کہ میں آپ کے لئے مغفرت مانگوں گا اور میں اللہ کے سامنے آپ کے بارے میں کسی چیز کا کچھ اختیار نہیں رکھتا۔ اے ہمارے پروردگار تجھی پر ہمارا بھروسہ ہے اور تیری ہی طرف ہم رجوع کرتے ہیں اور تیرے ہی حضور میں ہمیں لوٹ کر آنا ہے۔', 'تم کو چال چلنی چاہئیے اچھی ابراہیم کی اور جو اُسکے ساتھ تھے جب انہوں نے کہا اپنی قوم کو ہم الگ ہیں تم سے اور  اُن سے کہ جنکو  تم پوجتے ہو  اللہ کے سوائے [۱۰] ہم منکر ہوئے تم سے [۱۱] اور کھل پڑی ہم میں اور تم میں دشمنی اور بیر ہمیشہ کو یہاں تک کہ تم یقین لاؤ اللہ  اکیلے  پر [۱۲] مگر ایک کہنا ابراہیم کا اپنے باپ کو کہ میں مانگوں گا معافی تیرے لئے اور مالک نہیں میں تیرے نفع کا اللہ کے ہاتھ سے کسی چیز کا [۱۳] اے رب ہمارے ہم نے تجھ پر بھروسہ کیا اور تیری طرف رجوع ہوئے اور تیری طرف ہے سب کو پھر آنا [۱۴]', 'Indeed there has been an excellent example for you in Ibrahim (Abraham) and those with him, when they said to their people: \"Verily, we are free from you and whatever you worship besides Allah, we have rejected you, and there has started between us and you, hostility and hatred for ever, until you believe in Allah Alone,\" except the saying of Ibrahim (Abraham) to his father: \"Verily, I will ask for forgiveness (from Allah) for you, but I have no power to do anything for you before Allah .\" Our Lord! In You (Alone) we put our trust, and to You (Alone) we turn in repentance, and to You (Alone) is (our) final Return,', 'Indeed, there is an excellent example for you in Ibrāhīm and those with him, when they said to their people, “We disown you and what you worship instead of Allah. We disbelieve in you. Enmity and hatred has arisen between us and you forever, unless you believe in Allah alone”,- but (his example is) not (to be followed) in what Ibrāhīm said to his father, “I will pray to my Lord for your forgiveness, and I have no power from Allah (to do any thing) for you.” - “O our Lord, in You alone we trust, and to You alone we turn for help, and to You is the final return.'),
(5155, 60, 5, 1, 7, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' الممتحنۃ', 'رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَۃً  لِّلَّذِیۡنَ کَفَرُوۡا وَ اغۡفِرۡ لَنَا رَبَّنَا ۚ اِنَّکَ  اَنۡتَ الۡعَزِیۡزُ الۡحَکِیۡمُ ﴿۵﴾', 'اے ہمارے پروردگار ہم کو کافروں کے ذریعے فتنے میں نہ ڈالنا اور اے ہمارے پروردگار ہمیں معاف فرما بیشک تو غالب ہے حکمت والا ہے۔', 'اے رب ہمارے مت جانچ ہم پر کافروں کو [۱۵] اور ہم کو معاف کر اے رب ہمارے [۱۶] تو ہی ہے زبردست حکمت والا [۱۷]', '\"Our Lord! Make us not a trial for the disbelievers, and forgive us, Our Lord! Verily, You, only You are the All-Mighty, the All-Wise.\"', 'Our Lord, do not make us persecuted by those who disbelieve, and forgive us, our Lord! You, only You, are the All-Mighty, the All-Wise.”'),
(5156, 60, 6, 1, 7, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' الممتحنۃ', 'لَقَدۡ کَانَ  لَکُمۡ  فِیۡہِمۡ  اُسۡوَۃٌ  حَسَنَۃٌ لِّمَنۡ کَانَ  یَرۡجُوا اللّٰہَ وَ الۡیَوۡمَ الۡاٰخِرَ ؕ  وَ مَنۡ  یَّتَوَلَّ  فَاِنَّ اللّٰہَ  ہُوَ الۡغَنِیُّ  الۡحَمِیۡدُ ٪﴿۶﴾', 'تم مسلمانوں کو یعنی جو کوئی اللہ کے سامنے جانے اور روز آخرت کے آنے کی امید رکھتا ہو اسے ان لوگوں کی نیک سیرت اپنانی چاہیئے اور جو روگردانی کرے تو اللہ بھی بے نیاز ہے لائق حمدوثنا ہے۔', 'البتہ تم کو بھلی چال چلنی چاہئے اُنکی جو کوئی امید رکھتا ہو اللہ کی اور پچھلے دن کی اور جو کوئی منہ پھیرے تو اللہ وہی ہے بے پروا سب تعریفوں والا [۱۸]', 'Certainly, there has been in them an excellent example for you to follow, for those who look forward to (the Meeting with) Allah (for the reward from Him) and the Last Day. And whosoever turn away, then verily, Allah is Rich (Free of all wants), Worthy of all Praise.', 'Indeed, for you there is an excellent example in them, for anyone who hopes (to meet) Allah and the Last Day. And if one turns away, Allah is Free of all needs, Worthy of all Praise.'),
(5157, 60, 7, 2, 8, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' الممتحنۃ', 'عَسَی اللّٰہُ  اَنۡ یَّجۡعَلَ  بَیۡنَکُمۡ وَ بَیۡنَ الَّذِیۡنَ عَادَیۡتُمۡ  مِّنۡہُمۡ  مَّوَدَّۃً ؕ وَ اللّٰہُ قَدِیۡرٌ ؕ  وَ  اللّٰہُ  غَفُوۡرٌ  رَّحِیۡمٌ ﴿۷﴾', 'عجب نہیں کہ اللہ تم میں اور ان لوگوں میں جن سے تم دشمنی رکھتے ہو دوستی پیدا کر دے۔ اور اللہ قادر ہے۔ اور اللہ بخشنے والا ہے مہربان ہے۔', 'امید ہے کہ کر دے اللہ تم میں اور جو دشمن ہیں تمہارے اُن میں دوستی اور اللہ سب کچھ کر سکتا ہے اور اللہ بخشنے والا مہربان ہے [۱۹]', 'Perhaps Allah will make friendship between you and those whom you hold as enemies. And Allah has power (over all things), and Allah is Oft-Forgiving, Most Merciful.', 'It is hoped that Allah will bring about love between you and those of them with whom you have enmity. Allah is Powerful, and Allah is Most-forgiving, Very-Merciful.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(5158, 60, 8, 2, 8, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' الممتحنۃ', 'لَا یَنۡہٰىکُمُ اللّٰہُ  عَنِ الَّذِیۡنَ لَمۡ یُقَاتِلُوۡکُمۡ فِی الدِّیۡنِ وَ لَمۡ  یُخۡرِجُوۡکُمۡ  مِّنۡ  دِیَارِکُمۡ  اَنۡ  تَبَرُّوۡہُمۡ وَ تُقۡسِطُوۡۤا اِلَیۡہِمۡ ؕ اِنَّ  اللّٰہَ یُحِبُّ الۡمُقۡسِطِیۡنَ ﴿۸﴾', 'جن لوگوں نے تم سے دین کے بارے میں جنگ نہیں کی اور نہ تمکو تمہارے گھروں سے نکالا انکے ساتھ بھلائی اور انصاف کا سلوک کرنے سے اللہ تمکو منع نہیں کرتا۔ اللہ تو انصاف کرنے والوں کو دوست رکھتا ہے۔', 'اللہ تم کو منع نہیں کرتا اُن لوگوں سے جو لڑے نہیں تم سے دین پر اور نکالا نہیں تم کو تمہارےگھروں سے کہ اُن سے کرو بھلائی اور انصاف کا سلوک بیشک اللہ چاہتا ہے انصاف والوں کو [۲۰]', 'Allah does not forbid you to deal justly and kindly with those who fought not against you on account of religion and did not drive you out of your homes. Verily, Allah loves those who deal with equity.', 'Allah does not forbid you as regards those who did not fight you on account of faith, and did not expel you from your homes, that you do good to them, and deal justly with them. Surely Allah loves those who maintain justice.'),
(5159, 60, 9, 2, 8, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' الممتحنۃ', 'اِنَّمَا یَنۡہٰىکُمُ اللّٰہُ عَنِ الَّذِیۡنَ قٰتَلُوۡکُمۡ فِی الدِّیۡنِ وَ اَخۡرَجُوۡکُمۡ  مِّنۡ دِیَارِکُمۡ وَ ظٰہَرُوۡا عَلٰۤی  اِخۡرَاجِکُمۡ اَنۡ تَوَلَّوۡہُمۡ ۚ  وَ مَنۡ یَّتَوَلَّہُمۡ فَاُولٰٓئِکَ  ہُمُ الظّٰلِمُوۡنَ ﴿۹﴾', 'اللہ انہی لوگوں کے ساتھ تمکو دوستی کرنے سے منع کرتا ہے جنہوں نے تم سے دین کے بارے میں لڑائی کی اور تمکو تمہارے گھروں سے نکالا اور تمہارے نکالنے میں اوروں کی مدد کی تو جو لوگ ایسوں سے دوستی کریں گے وہی ظالم ہیں۔', 'اللہ تو منع کرتا ہے تم کو اُن سے جو لڑے تم سے دین پر اور نکالا تم کو تمہارے گھروں سے اور شریک ہوئے تمہارے نکالنے میں کہ اُن سے کرو دوستی اور جو کوئی ان سے دوستی کرے سو وہ لوگ وہی ہیں گنہگار [۲۱]', 'It is only as regards those who fought against you on account of religion, and have driven you out of your homes, and helped to drive you out, that Allah forbids you to befriend them. And whosoever will befriend them, then such are the Zalimoon (wrong-doers those who disobey Allah).', 'Allah forbids you only about those who fought you on account of faith, and expelled you from your homes, and helped (others) in expelling you, that you have friendship with them. Those who develop friendship with them are the wrongdoers.'),
(5160, 60, 10, 2, 8, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' الممتحنۃ', 'یٰۤاَیُّہَا  الَّذِیۡنَ اٰمَنُوۡۤا  اِذَا جَآءَکُمُ الۡمُؤۡمِنٰتُ مُہٰجِرٰتٍ فَامۡتَحِنُوۡہُنَّ ؕ اَللّٰہُ  اَعۡلَمُ  بِاِیۡمَانِہِنَّ ۚ فَاِنۡ عَلِمۡتُمُوۡہُنَّ  مُؤۡمِنٰتٍ فَلَا تَرۡجِعُوۡہُنَّ  اِلَی  الۡکُفَّارِ ؕ لَا ہُنَّ حِلٌّ  لَّہُمۡ  وَ لَا ہُمۡ  یَحِلُّوۡنَ  لَہُنَّ ؕ وَ  اٰتُوۡہُمۡ مَّاۤ  اَنۡفَقُوۡا ؕ وَ لَا جُنَاحَ عَلَیۡکُمۡ  اَنۡ تَنۡکِحُوۡہُنَّ  اِذَاۤ  اٰتَیۡتُمُوۡہُنَّ  اُجُوۡرَہُنَّ ؕ وَ لَا تُمۡسِکُوۡا بِعِصَمِ الۡکَوَافِرِ وَ سۡـَٔلُوۡا مَاۤ  اَنۡفَقۡتُمۡ وَ لۡیَسۡـَٔلُوۡا مَاۤ  اَنۡفَقُوۡا ؕ ذٰلِکُمۡ  حُکۡمُ اللّٰہِ ؕ یَحۡکُمُ بَیۡنَکُمۡ ؕ وَ اللّٰہُ عَلِیۡمٌ حَکِیۡمٌ ﴿۱۰﴾', 'مومنو! جب تمہارے پاس مومن عورتیں وطن چھوڑ کر آئیں تو انکی آزمائش کر لو۔ اور اللہ تو انکے ایمان کو خوب جانتا ہے۔ سو اگر تمکو معلوم ہو کہ وہ مومن ہیں تو انکو کفار کے پاس واپس نہ بھیجو۔ کہ نہ یہ انکو حلال ہیں اور نہ وہ انکو حلال ہیں۔ اور جو کچھ انہوں نے ان پر خرچ کیا ہو وہ انکو دیدو۔ اور تم پر کچھ گناہ نہیں کہ ان عورتوں کو مہر دے کر ان سے نکاح کر لو۔ اور کافر عورتوں کیساتھ تعلقات نکاح باقی نہ رکھو یعنی انہیں کفار کو واپس دے دو اور جو کچھ تم نے ان پر خرچ کیا ہو تم ان سے طلب کر لو اور جو کچھ انہوں نے اپنی عورتوں پر خرچ کیا ہو وہ تم سے طلب کر لیں یہ اللہ کا حکم ہے جو تم میں فیصلہ کئے دیتا ہے۔ اور اللہ جاننے والا ہے حکمت والا ہے۔', 'اے ایمان والو جب آئیں تمہارے پاس ایمان والی عورتیں وطن چھوڑ کر تو ان کو جانچ لو اللہ خوب جانتا ہے انکے ایمان کو [۲۲] پھر اگر جانو کہ وہ ایمان پر ہیں تو مت پھیرو اُنکو کافروں کی طرف نہ یہ عورتیں حلال ہیں اُن کافروں کو اور نہ وہ کافر حلال ہیں ان عورتوں کو اور دیدو اُن کافروں کو جو ان کا خرچ ہوا ہو اور گناہ نہیں تم کو کہ نکاح کر لو اُن عورتوں سے جب اُنکو دو انُکے مہر [۲۳] اور نہ رکھو اپنے قبضہ میں ناموس کافر  عورتوں کے اور تم مانگ لو جو تم نے خرچ کیا اور وہ کافر مانگ لیں جو انہوں نے خرچ کیا یہ اللہ کا فیصلہ ہے تم میں فیصلہ کرتا ہے اور اللہ سب کچھ جاننے والا حکمت والا ہے [۲۴]', 'O you who believe! When believing women come to you as emigrants, examine them, Allah knows best as to their Faith, then if you ascertain that they are true believers, send them not back to the disbelievers, they are not lawful (wives) for the disbelievers nor are the disbelievers lawful (husbands) for them. But give the disbelievers that (amount of money) which they have spent (as their Mahr) to them. And there will be no sin on you to marry them if you have paid their Mahr to them. Likewise hold not the disbelieving women as wives, and ask for (the return of) that which you have spent (as Mahr) and let them (the disbelievers, etc.) ask back for that which they have spent. That is the Judgement of Allah. He judges between you. And Allah is All-Knowing, All-Wise.', 'O you who believe, when the believing women come to you as emigrants, put them to a test. Allah knows best about their faith. So, if you find them faithful, do not send them back to the disbelievers. Neither these (women) are lawful for them, nor are those (disbelievers) lawful for these (women). And give them (the disbelievers) that (dower) which they had paid (to these women). And there is no sin for you if you marry them, when you give them their dowers. And do not hold on to the ties of marriage with the disbelieving women,and ask (their new Non-Muslim husbands to pay to you) that (dower) which you had paid (to your previous wives), and they (the previous Non-Muslim husbands of the Muslim women) should ask (their new Muslim husbands) to pay that (dower) which they had paid (to their previous wives). That is the decision of Allah. He decides between you. And Allah is All-Knowing, All-Wise.'),
(5161, 60, 11, 2, 8, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' الممتحنۃ', 'وَ  اِنۡ  فَاتَکُمۡ شَیۡءٌ  مِّنۡ  اَزۡوَاجِکُمۡ   اِلَی الۡکُفَّارِ فَعَاقَبۡتُمۡ  فَاٰتُوا الَّذِیۡنَ ذَہَبَتۡ اَزۡوَاجُہُمۡ مِّثۡلَ مَاۤ  اَنۡفَقُوۡا ؕ وَ اتَّقُوا اللّٰہَ  الَّذِیۡۤ  اَنۡتُمۡ بِہٖ مُؤۡمِنُوۡنَ ﴿۱۱﴾', 'اور اگر تمہاری بیویوں میں سے کوئی تمہارے ہاتھ سے نکل کر کافروں کے پاس چلی جائے اور اس کا مہر وصول نہ ہوا ہو پھر تم ان سے جنگ کرو اور ان سے تمکو غنیمت ہاتھ لگے تو جنکی بیویاں چلی گئ ہیں انکو اس مال میں سے اتنا دے دو جتنا انہوں نے خرچ کیا تھا۔ اور اللہ سے جس پر تم ایمان لائے ہو ڈرتے رہو۔', 'اور اگر جاتی رہیں تمہارے ہاتھ سے کچھ عورتیں کافروں کی طرف پھر تم ہاتھ مارو تو دیدو اُنکو جن کی عورتیں جاتی رہی ہیں جتنا انہوں نے خرچ کیا تھا اور ڈرتے رہو اللہ سے جس پر تم کو یقین ہے [۲۵]', 'And if any of your wives have gone from you to the disbelievers, and you have an accession (by the coming over of a woman from the other side), then pay to those whose wives have gone, the equivalent of what they had spent (on their Mahr). And fear Allah in Whom you believe.', 'And if some of your (Non-Muslim) wives have slipped from you, (and their present Non-Muslim husbands do not pay to you the dower as aforesaid,) and you have your turn (of paying dower to the previous Non-Muslim husbands of your present wives), then (instead of paying dower to them,) give those whose wives have slipped the like amount of what they had paid (to them). And fear Allah, the One in whom you believe.'),
(5162, 60, 12, 2, 8, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' الممتحنۃ', 'یٰۤاَیُّہَا  النَّبِیُّ  اِذَا جَآءَکَ  الۡمُؤۡمِنٰتُ یُبَایِعۡنَکَ عَلٰۤی  اَنۡ  لَّا یُشۡرِکۡنَ بِاللّٰہِ شَیۡئًا وَّ لَا یَسۡرِقۡنَ وَ لَا یَزۡنِیۡنَ وَ لَا یَقۡتُلۡنَ اَوۡلَادَہُنَّ وَ  لَا یَاۡتِیۡنَ  بِبُہۡتَانٍ یَّفۡتَرِیۡنَہٗ بَیۡنَ  اَیۡدِیۡہِنَّ وَ اَرۡجُلِہِنَّ وَ لَا یَعۡصِیۡنَکَ فِیۡ  مَعۡرُوۡفٍ فَبَایِعۡہُنَّ وَ اسۡتَغۡفِرۡ لَہُنَّ اللّٰہَ ؕ اِنَّ اللّٰہَ  غَفُوۡرٌ  رَّحِیۡمٌ ﴿۱۲﴾', 'اے پیغمبر ﷺ جب تمہارے پاس مومن عورتیں اس بات پر بیعت کرنے کو آئیں کہ نہ تو اللہ کے ساتھ شرک کریں گی نہ چوری کریں گی نہ بدکاری کریں گی نہ اپنی اولاد کو قتل کریں گی نہ اپنے ہاتھ پاؤں کے درمیان کوئی بہتان باندھ لائیں گی۔ اور نہ نیک کاموں میں تمہاری نافرمانی کریں گی تو ان سے بیعت لے لو اور انکے لئے اللہ سے بخشش مانگو۔ بیشک اللہ بخشنے والا ہے مہربان ہے۔', 'اے نبی جب آئیں تیرے پاس مسلمان عورتیں بیعت کرنے کو اس بات پر کہ شریک نہ ٹھہرائیں اللہ کا کسی کو اور چوری نہ کریں اور بدکاری نہ کریں اور اپنی اولاد کو نہ مار ڈالیں [۲۶] اور طوفان نہ لائیں باندھ کر اپنے ہاتھوں اور پاؤں میں [۲۷] اور تیری نافرمانی نہ کریں کسی بھلے کام میں تو اُنکو بیعت کر لے [۲۸] اور معافی مانگ اُنکے واسطے اللہ سے بیشک اللہ بخشنے والا مہربان ہے [۲۹]', 'O Prophet! When believing women come to you to give you the Baia (pledge), that they will not associate anything in worship with Allah, that they will not steal, that they will not commit illegal sexual intercourse, that they will not kill their children, that they will not utter slander, intentionally forging falsehood (i.e. by making illegal children belonging to their husbands), and that they will not disobey you in any Maroof (Islamic Monotheism and all that which Islam ordains) then accept their Baia (pledge), and ask Allah to forgive them, Verily, Allah is Oft-Forgiving, Most Merciful.', 'O you who believe, when the believing women come to you, seeking bai’ah (a pledge of allegiance) with you that they will not ascribe any partner to Allah, and will not commit theft, and will not commit fornication,and will not kill their children, and will not come up with a false claim (about the parentage of a child) that they falsely attribute (to the sperm of their husbands being dropped) between their hands and their feet (i.e. their private parts), and will not disobey you in what is recognized (in Sharī‘ah), then take them in your bai’ah, and pray Allah for their forgiveness. Surely Allah is Most-Forgiving, Very-Merciful.'),
(5163, 60, 13, 2, 8, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' الممتحنۃ', 'یٰۤاَیُّہَا  الَّذِیۡنَ  اٰمَنُوۡا لَا تَتَوَلَّوۡا قَوۡمًا غَضِبَ اللّٰہُ  عَلَیۡہِمۡ  قَدۡ یَئِسُوۡا مِنَ الۡاٰخِرَۃِ کَمَا یَئِسَ الۡکُفَّارُ  مِنۡ اَصۡحٰبِ  الۡقُبُوۡرِ ﴿٪۱۳﴾', 'مومنو! ان لوگوں سے جن پر اللہ غصے ہوا ہے دوستی نہ کرو کیونکہ جس طرح کافروں کو مردوں کے جی اٹھنے کی امید نہیں اسی طرح ان لوگوں کو بھی آخرت کے آنے کی امید نہیں۔', 'اے ایمان والو مت دوستی کرو  اُن لوگوں سے کہ غصہ ہوا ہے اللہ اُن پر [۳۰] وہ آس توڑ چکے ہیں پچھلے گھر سے جیسے آس توڑی منکروں نے قبر والوں سے [۳۱]', 'O you who believe! Take not as friends the people who incurred the Wrath of Allah (i.e. the Jews). Surely, they have been in despair to receive any good in the Hereafter, just as the disbelievers have been in despair about those (buried) in graves (that they will not be resurrected on the Day of Resurrection)', 'O you who believe, do not have friendship with a people with whom Allah is angry. They have despaired from the Hereafter as the infidels have despaired from those (buried) in the graves.'),
(5164, 61, 1, 1, 9, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الصّف', 'سَبَّحَ  لِلّٰہِ مَا  فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ۚ وَ  ہُوَ  الۡعَزِیۡزُ  الۡحَکِیۡمُ ﴿۱﴾', 'جو چیز آسمانوں میں ہے اور جو زمین میں ہے سب اللہ کی تسبیح کرتی ہے اور وہ غالب ہے حکمت والا ہے۔', 'اللہ کی پاکی بولتا ہے جوکچھ ہے آسمانوں میں اور جو کچھ ہے زمین میں اور وہی ہے زبردست حکمت والا', 'Whatsoever is in the heavens and whatsoever is on the earth glorifies Allah. And He is the All-Mighty, the All-Wise.', 'All that is in the heavens and all that is in the earth proclaim Allah’s purity, and He is the All-Mighty, the All-Wise.'),
(5165, 61, 2, 1, 9, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الصّف', 'یٰۤاَیُّہَا  الَّذِیۡنَ اٰمَنُوۡا  لِمَ  تَقُوۡلُوۡنَ مَا لَا  تَفۡعَلُوۡنَ ﴿۲﴾', 'مومنو! تم ایسی باتیں کیوں کہا کرتے ہو جو کیا نہیں کرتے۔', 'اے ایمان والو کیوں کہتے ہو منہ سے جو نہیں کرتے', 'O you who believe! Why do you say that which you do not do?', 'O you who believe, why do you say what you do not do?'),
(5166, 61, 3, 1, 9, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الصّف', 'کَبُرَ  مَقۡتًا عِنۡدَ  اللّٰہِ  اَنۡ  تَقُوۡلُوۡا مَا  لَا تَفۡعَلُوۡنَ ﴿۳﴾', 'اللہ اس بات سے سخت بیزار ہے کہ ایسی بات کہو جو کرو نہیں۔', 'بڑی بیزاری کی بات ہے اللہ کے یہاں کہ کہو  وہ چیز جو نہ کرو', 'Most hateful it is with Allah that you say that which you do not do.', 'It is severely hateful in Allah’s sight that you say what you do not do.'),
(5167, 61, 4, 1, 9, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الصّف', 'اِنَّ اللّٰہَ یُحِبُّ الَّذِیۡنَ یُقَاتِلُوۡنَ فِیۡ سَبِیۡلِہٖ  صَفًّا کَاَنَّہُمۡ  بُنۡیَانٌ  مَّرۡصُوۡصٌ  ﴿۴﴾', 'جو لوگ اللہ کی راہ میں ایسے طور پر صف باندھ کر لڑتے ہیں کہ گویا سیسہ پلائی ہوئی دیوار ہیں وہ بیشک اللہ کے محبوب ہیں۔', 'اللہ چاہتا ہے اُن لوگوں کو جو لڑتے ہیں اُسکی راہ میں قطار باندھ کر گویا وہ دیوار ہیں سیسہ پلائی ہوئی [۱]', 'Verily, Allah loves those who fight in His Cause in rows (ranks) as if they were a solid structure .', 'Surely Allah loves those who fight in His way in firm rows, as if they were solid edifice.'),
(5168, 61, 5, 1, 9, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الصّف', 'وَ اِذۡ  قَالَ مُوۡسٰی لِقَوۡمِہٖ یٰقَوۡمِ لِمَ تُؤۡذُوۡنَنِیۡ  وَ قَدۡ تَّعۡلَمُوۡنَ  اَنِّیۡ  رَسُوۡلُ اللّٰہِ  اِلَیۡکُمۡ ؕ فَلَمَّا  زَاغُوۡۤا اَزَاغَ  اللّٰہُ قُلُوۡبَہُمۡ ؕ وَ اللّٰہُ  لَا یَہۡدِی الۡقَوۡمَ الۡفٰسِقِیۡنَ ﴿۵﴾', 'اور وہ وقت یاد کرنے کے لائق ہے جب موسٰی  نے اپنی قوم سے کہا تھا کہ بھائیو تم مجھے کیوں ایذا دیتے ہو حالانکہ تم جانتے ہو کہ میں تمہارے پاس اللہ کا بھیجا ہوا آیا ہوں۔ پھر جب ان لوگوں نے کجروی کی اللہ نے بھی انکے دل ٹیڑھے کر دیئے اور اللہ نافرمانوں کو ہدایت نہیں دیتا۔', 'اور جب کہا موسٰی نے اپنی قوم کو اے قوم میری کیوں ستاتے ہو مجھ کو اور تم کو معلوم ہے کہ میں اللہ کا بھیجا آیا ہوں تمہارے پاس [۲] پھر جب وہ پھر گئے تو پھیر دیے اللہ نے انکے دل اور اللہ راہ نہیں دیتا نافرمان لوگوں کو [۳]', 'And (remember) when Moosa (Moses) said to his people: \"O my people! Why do you hurt me while you know certainly that I am the Messenger of Allah to you? So when they turned away (from the Path of Allah), Allah turned their hearts away (from the Right Path). And Allah guides not the people who are Fasiqoon (rebellious, disobedient to Allah).', 'And (remember) when Mūsā said to his people, “O my people, why do you hurt me, while you know that I am a messenger of Allah sent towards you.” So, when they adopted deviation, Allah let their hearts become deviate. And Allah does not guide the sinful people.'),
(5169, 61, 6, 1, 9, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الصّف', 'وَ اِذۡ قَالَ عِیۡسَی ابۡنُ  مَرۡیَمَ یٰبَنِیۡۤ اِسۡرَآءِیۡلَ  اِنِّیۡ  رَسُوۡلُ  اللّٰہِ  اِلَیۡکُمۡ مُّصَدِّقًا  لِّمَا بَیۡنَ  یَدَیَّ  مِنَ  التَّوۡرٰىۃِ وَ مُبَشِّرًۢا  بِرَسُوۡلٍ یَّاۡتِیۡ  مِنۡۢ  بَعۡدِی اسۡمُہٗۤ  اَحۡمَدُ ؕ فَلَمَّا جَآءَہُمۡ  بِالۡبَیِّنٰتِ قَالُوۡا ہٰذَا  سِحۡرٌ  مُّبِیۡنٌ ﴿۶﴾', 'اور وہ وقت بھی یاد کرو جب مریم  کے بیٹے عیسٰی  نے کہا کہ اے بنی اسرائیل میں تمہارے پاس اللہ کا بھیجا ہوا آیا ہوں جو کتاب مجھ سے پہلے آ چکی ہے یعنی تورات اسکی تصدیق کرتا ہوں اور ایک پیغمبر جو میرے بعد آئیں گے جنکا نام احمد ﷺ ہو گا انکی بشارت سناتا ہوں۔ پھر جب وہ ان لوگوں کے پاس کھلی نشانیاں لے کر آئے تو کہنے لگے کہ یہ تو سراسر جادو ہے۔', 'اور جب کہا عیسٰی مریم کے بیٹے نے اے بنی اسرائیل میں بھیجا ہوا آیا ہوں اللہ کا تمہارے پاس یقین کرنے والا اُس پر جو مجھ سے آگے ہے توریت [۴] اور خوشخبری سنانے والا ایک رسول کی جو آئے گا میرے بعد اُس کا نام ہے احمد [۵] پھر جب آیا انکے پاس کھلی نشانیاں لیکر کہنے لگے یہ جادو ہے صریح [۶]', 'And (remember) when Iesa (Jesus), son of Maryam (Mary), said: \"O Children of Israel! I am the Messenger of Allah unto you confirming the Taurat ((Torah) which came) before me, and giving glad tidings of a Messenger to come after me, whose name shall be Ahmed . But when he (Ahmed i.e. Muhammad SAW) came to them with clear proofs, they said: \"This is plain magic.\"', '(Remember) when ‘Īsā, son of Maryam, said, “O children of Isrā’īl, I am a messenger of Allah sent towards you, confirming the Torah that is (sent down) before me, and giving you the good news of a messenger who will come after me, whose name will be AHmad.” But when he came to them with manifest signs, they said, “This is a clear magic.”'),
(5170, 61, 7, 1, 9, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الصّف', 'وَ مَنۡ  اَظۡلَمُ مِمَّنِ افۡتَرٰی عَلَی اللّٰہِ الۡکَذِبَ وَ ہُوَ  یُدۡعٰۤی  اِلَی الۡاِسۡلَامِ ؕ وَ  اللّٰہُ  لَا  یَہۡدِی الۡقَوۡمَ  الظّٰلِمِیۡنَ ﴿۷﴾', 'اور اس سے زیادہ ظالم کون کہ بلایا تو جائے اسلام کی طرف اور وہ اللہ پر جھوٹ بہتان باندھے۔ اور اللہ ظالم لوگوں کو ہدایت نہیں دیا کرتا۔', 'اور اس سے زیادہ بے انصاف کون جو باندھے اللہ پر جھوٹ اور اُسکو بلاتے ہیں مسلمان ہونے کو [۷] اور اللہ راہ نہیں دیتا بے انصاف لوگوں کو [۸]', 'And who does more wrong than the one who invents a lie against Allah, while he is being invited to Islam? And Allah guides not the people who are Zalimoon (polytheists, wrong-doers and disbelievers) folk.', 'And who is more unjust than the one who forges a lie against Allah, while he is invited to Islām? And Allah does not guide the unjust people.'),
(5171, 61, 8, 1, 9, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الصّف', 'یُرِیۡدُوۡنَ  لِیُطۡفِـُٔوۡا  نُوۡرَ اللّٰہِ  بِاَفۡوَاہِہِمۡ وَ اللّٰہُ  مُتِمُّ  نُوۡرِہٖ  وَ لَوۡ  کَرِہَ  الۡکٰفِرُوۡنَ ﴿۸﴾', 'یہ چاہتے ہیں کہ اللہ کے چراغ کی روشنی کو اپنی پھونکوں سے بجھا دیں حالانکہ اللہ اپنی روشنی کو پورا کر کے رہے گا خواہ کافر ناخوش ہی ہوں۔', 'چاہتے ہیں کہ بجھا دیں اللہ کی روشنی اپنے منہ سے اور اللہ کو پوری کرنی ہے اپنی روشنی اور  پڑے برا مانیں منکر [۹]', 'They intend to put out the Light of Allah (i.e. the religion of Islam, this Quran, and Prophet Muhammad SAW) with their mouths. But Allah will complete His Light even though the disbelievers hate (it).', 'They wish to extinguish the light of Allah with their mouths, but Allah is to perfect His light, even though the disbelievers dislike (it).'),
(5172, 61, 9, 1, 9, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الصّف', 'ہُوَ الَّذِیۡۤ  اَرۡسَلَ  رَسُوۡلَہٗ  بِالۡہُدٰی وَ دِیۡنِ  الۡحَقِّ لِیُظۡہِرَہٗ  عَلَی الدِّیۡنِ کُلِّہٖ وَ لَوۡ  کَرِہَ  الۡمُشۡرِکُوۡنَ ٪﴿۹﴾', 'وہی تو ہے جس نے اپنے پیغمبر کو ہدایت اور دین حق دے کر بھیجا تاکہ اسے سب دینوں پر غالب کرے خواہ مشرکوں کو برا ہی لگے۔', 'وہی ہے جس نے بھیجا اپنا رسول راہ کی سوجھ دے کر اور سچا دین کہ اس کو اوپر کرے سب دینوں سے  اور پڑے برا مانیں شرک کرنے والے [۱۰]', 'He it is Who has sent His Messenger (Muhammad SAW) with guidance and the religion of truth (Islamic Monotheism) to make it victorious over all (other) religions even though the Mushrikoon (polytheists, pagans, idolaters, and disbelievers in the Oneness of Allah and in His Messenger Muhammed SAW) hate (it).', 'He is the One who has sent His Messenger with guidance and the religion of truth, so that He makes it prevail over all religions, even though the mushriks (those who ascribe partners to Allah) dislike (it).'),
(5173, 61, 10, 2, 10, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الصّف', 'یٰۤاَیُّہَا  الَّذِیۡنَ  اٰمَنُوۡا ہَلۡ اَدُلُّکُمۡ عَلٰی تِجَارَۃٍ  تُنۡجِیۡکُمۡ مِّنۡ عَذَابٍ اَلِیۡمٍ ﴿۱۰﴾', 'مومنو! میں تمکو ایسی تجارت بتاؤں جو تمہیں عذاب الیم سے نجات دے۔', 'اے ایمان والو میں بتلاؤں تم کو ایسی سوداگری جو بچائے تم کو ایک عذاب دردناک سے', 'O You who believe! Shall I guide you to a commerce that will save you from a painful torment.', 'O you who believe, shall I tell you about a trade that saves you from a painful punishment?'),
(5174, 61, 11, 2, 10, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الصّف', 'تُؤۡمِنُوۡنَ بِاللّٰہِ وَ رَسُوۡلِہٖ وَ تُجَاہِدُوۡنَ فِیۡ سَبِیۡلِ اللّٰہِ  بِاَمۡوَالِکُمۡ وَ اَنۡفُسِکُمۡ ؕ ذٰلِکُمۡ  خَیۡرٌ  لَّکُمۡ  اِنۡ کُنۡتُمۡ  تَعۡلَمُوۡنَ ﴿ۙ۱۱﴾', 'وہ یہ کہ اللہ پر اور اسکے رسول ﷺ پر ایمان لاؤ اور اللہ کی راہ میں اپنے مال اور جان سے جہاد کرو۔ اگر سمجھو تو یہ تمہارے حق میں بہتر ہے۔', 'ایمان لاؤ اللہ پر اور اُسکے رسول پر اور لڑو اللہ کی راہ میں اپنے مال سے اور اپنی جان سے یہ بہتر ہے تمہارے حق میں اگر تم سمجھ رکھتے ہو', 'That you believe in Allah and His Messenger (Muhammad SAW), and that you strive hard and fight in the Cause of Allah with your wealth and your lives, that will be better for you, if you but know!', 'That you believe in Allah and His Messenger, and carry out Jihād in His way with your riches and your lives. That is much better for you, if you but know.'),
(5175, 61, 12, 2, 10, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الصّف', 'یَغۡفِرۡ لَکُمۡ  ذُنُوۡبَکُمۡ وَ یُدۡخِلۡکُمۡ جَنّٰتٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ وَ مَسٰکِنَ  طَیِّبَۃً  فِیۡ  جَنّٰتِ عَدۡنٍ ؕ ذٰلِکَ الۡفَوۡزُ الۡعَظِیۡمُ ﴿ۙ۱۲﴾', 'وہ تمہارے گناہ بخش دے گا اور تمکو جنت کے باغوں میں جنکے نیچے نہریں بہ رہی ہیں اور پاکیزہ مکانات میں جو ہمیشہ کی بہشت میں ہیں داخل کرے گا یہی بڑی کامیابی ہے۔', 'بخشے گاہ وہ تمہارے گناہ اور داخل کرے گا تم کو باغوں میں جنکے نیچے بہتی ہیں نہریں [۱۱] اور ستھرے گھروں میں بسنے کے باغوں کے اندر [۱۲] یہ ہے بڑی مراد ملنی', '(If you do so) He will forgive you your sins, and admit you into Gardens under which rivers flow, and pleasant dwelling in Gardens of Adn Eternity (Adn (Edn) Paradise), that is indeed the great success.', '(If you do this,) He will forgive your sins, and will admit you to gardens beneath which rivers flow, and to pleasant dwellings in gardens of eternity. That is the great achievement.'),
(5176, 61, 13, 2, 10, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الصّف', 'وَ اُخۡرٰی تُحِبُّوۡنَہَا ؕ نَصۡرٌ  مِّنَ اللّٰہِ وَ فَتۡحٌ  قَرِیۡبٌ ؕ وَ  بَشِّرِ  الۡمُؤۡمِنِیۡنَ ﴿۱۳﴾', 'اور ایک اور چیز جسکو تم بہت چاہتے ہو یعنی تمہیں اللہ کی طرف سے غلبہ نصیب ہو گا اور فتح عنقریب ہو گی اور مومنوں کو اسکی خوشخبری سنا دو۔', 'اور ایک اور چیز دے جس کو تم چاہتے ہو مدد اللہ کی طرف سے اور فتح جلدی [۱۳] اور خوشی سنا دے ایمان والوں کو [۱۴]', 'And also (He will give you) another (blessing) which you love, help from Allah (against your enemies) and a near victory. And give glad tidings (O Muhammad SAW) to the believers.', 'And (He will give you) another thing, which you love: Help from Allah, and victory, near at hand.'),
(5177, 61, 14, 2, 10, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الصّف', 'یٰۤاَیُّہَا  الَّذِیۡنَ  اٰمَنُوۡا کُوۡنُوۡۤا  اَنۡصَارَ اللّٰہِ کَمَا قَالَ عِیۡسَی ابۡنُ  مَرۡیَمَ لِلۡحَوَارِیّٖنَ مَنۡ  اَنۡصَارِیۡۤ  اِلَی اللّٰہِ ؕ قَالَ الۡحَوَارِیُّوۡنَ نَحۡنُ  اَنۡصَارُ اللّٰہِ  فَاٰمَنَتۡ طَّآئِفَۃٌ  مِّنۡۢ  بَنِیۡۤ  اِسۡرَآءِیۡلَ وَ کَفَرَتۡ طَّآئِفَۃٌ ۚ فَاَیَّدۡنَا  الَّذِیۡنَ  اٰمَنُوۡا عَلٰی عَدُوِّہِمۡ  فَاَصۡبَحُوۡا ظٰہِرِیۡنَ ﴿٪۱۴﴾', 'مومنو! اللہ کے مددگار ہو جاؤ جیسے عیسٰی ابن مریم  نے حواریوں سے کہا تھا کہ بھلا کون ہیں جو اللہ کی طرف بلانے میں میرے مددگار ہوں۔ حواریوں نے کہا کہ ہم اللہ کے مددگار ہیں۔ سو بنی اسرائیل میں سے ایک گروہ تو ایمان لے آیا اور ایک گروہ کافر رہا۔ آخر ہم نے ایمان لانے والوں کو انکے دشمنوں کے مقابلے میں مدد دی سو وہ غالب ہو گئے۔', 'اے ایمان والو تم ہو جاؤ مددگار اللہ کے [۱۵] جیسے کہا عیسٰی مریم کے بیٹے نے اپنے یاروں کو کون ہے کہ مدد کرے میری اللہ کی راہ میں بولے یار ہم ہیں مددگار اللہ کے [۱۶] پھر ایمان لایا ایک فرقہ بنی اسرائیل سے اور منکر ہوا ایک فرقہ پھر قوت دی ہم نے اُنکو جو ایمان لائے تھے اُنکے دشمنوں پر پھر ہو رہے غالب [۱۷]', 'O you who believe! Be you helpers (in the Cause) of Allah as said Iesa (Jesus), son of Maryam (Mary), to AlHawareeoon (the disciples): \"Who are my helpers (in the Cause) of Allah?\" AlHawareeeen (the disciples) said: \"We are Allahs helpers\" (i.e. we will strive in His Cause!). Then a group of the Children of Israel believed and a group disbelieved. So We gave power to those who believed against their enemies, and they became the uppermost.', 'O you who believe, be supporters of (the religion of) Allah, just as ‘Īsā, son of Maryam, said to the Disciples, “Who are my supporters towards Allah?” The Disciples said, “We are the supporters of (the religion of) Allah.” So a group from the children of Isrā’īl believed, and another group disbelieved. Then We supported those who believed against their enemy, and they became victors.'),
(5178, 62, 1, 1, 11, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الجُمعۃ', 'یُسَبِّحُ  لِلّٰہِ مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ الۡمَلِکِ الۡقُدُّوۡسِ الۡعَزِیۡزِ الۡحَکِیۡمِ ﴿۱﴾', 'جو چیز آسمانوں میں ہے اور جو چیز زمین میں ہے سب اللہ کی تسبیح کر تی ہے جو بادشاہ حقیقی ہے پاک  ہے زبردست ہے حکمت والا ہے۔', 'اللہ کی پاکی بولتا ہے جو کچھ کہ ہے آسمانوں میں اورجو کچھ کہ ہے زمین میں بادشاہ پاک ذات زبردست حکمتوں والا', 'Whatsoever is in the heavens and whatsoever is on the earth glorifies Allah, the King (of everything), the Holy, the All-Mighty, the All-Wise.', 'All that is in the heavens and all that is in the earth proclaim the purity of Allah, the Sovereign, the Supreme in Holiness, the All-Mighty, the All-Wise.'),
(5179, 62, 2, 1, 11, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الجُمعۃ', 'ہُوَ الَّذِیۡ  بَعَثَ فِی  الۡاُمِّیّٖنَ  رَسُوۡلًا مِّنۡہُمۡ  یَتۡلُوۡا عَلَیۡہِمۡ  اٰیٰتِہٖ  وَ  یُزَکِّیۡہِمۡ وَ  یُعَلِّمُہُمُ  الۡکِتٰبَ وَ  الۡحِکۡمَۃَ ٭ وَ  اِنۡ کَانُوۡا مِنۡ  قَبۡلُ  لَفِیۡ ضَلٰلٍ  مُّبِیۡنٍ ۙ﴿۲﴾', 'وہی تو ہے جس نے ان پڑھوں میں انہی میں سے ایک پیغمبر بھیجے جو انکے سامنے اسکی آیتیں پڑھتے اور انکو پاک کرتے اور انہیں کتاب و حکمت کی تعلیم دیتے ہیں اور اس سے پہلے تو یہ لوگ کھلی گمراہی میں تھے۔', 'وہی ہے جس نے اٹھایا ان پڑھوں میں ایک رسول انہی میں کا پڑھ کر سناتا ہے اُنکو اُسکی آیتیں اور انکو سنوارتا ہے اور سکھلاتا ہے اُنکو کتاب اور عقلمندی اور اس سے پہلے وہ پڑے ہوئے تھے صریح بھول میں [۱]', 'He it is Who sent among the unlettered ones a Messenger (Muhammad SAW) from among themselves, reciting to them His Verses, purifying them (from the filth of disbelief and polytheism), and teaching them the Book (this Quran, Islamic laws and Islamic jurisprudence) and Al-Hikmah (As-Sunnah: legal ways, orders, acts of worship, etc. of Prophet Muhammad SAW). And verily, they had been before in mainfest error;', 'He is the One who raised amidst the unlettered people a messenger from among themselves who recites to them His verses, and purifies them, and teaches them the Book and the wisdom, while they were earlier in open error.'),
(5180, 62, 3, 1, 11, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الجُمعۃ', 'وَّ اٰخَرِیۡنَ مِنۡہُمۡ  لَمَّا یَلۡحَقُوۡا بِہِمۡ ؕ وَ ہُوَ  الۡعَزِیۡزُ  الۡحَکِیۡمُ ﴿۳﴾', 'اور ان میں سے اور لوگوں کی طرف بھی انکو بھیجا ہے جو ابھی ان مسلمانوں سے نہیں ملے۔ اور وہ غالب ہے حکمت والا ہے۔', 'اور اٹھایا اس رسول کو  ایک دوسرے لوگوں کے واسطے بھی انہی میں سےجو ابھی نہیں ملے ان میں [۲] اور وہی ہے زبردست حکمت والا [۳]', 'And He has sent him (Prophet Muhammad SAW) also to others among them (Muslims) who have not yet joined them (but they will come). And He (Allah) is the All-Mighty, the All-Wise.', 'And (this Messenger is sent also) to others from them who did not join them so far, and He is the All-Mighty, the All-Wise.'),
(5181, 62, 4, 1, 11, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الجُمعۃ', 'ذٰلِکَ فَضۡلُ اللّٰہِ یُؤۡتِیۡہِ مَنۡ یَّشَآءُ ؕ وَ اللّٰہُ  ذُو الۡفَضۡلِ الۡعَظِیۡمِ ﴿۴﴾', 'یہ اللہ کا فضل ہے جسے چاہتا ہے عطا فرماتا ہے۔ اور اللہ بڑے فضل کا مالک ہے۔', 'یہ بڑائی اللہ کی ہے دیتا ہے جسکو چاہے اور اللہ کا فضل بڑا ہے [۴]', 'That is the Grace of Allah, which He bestows on whom He wills. And Allah is the Owner of Mighty Grace.', 'It is Allah’s bounty that He gives to whomsoever He wills, and Allah is the Lord of the great bounty.'),
(5182, 62, 5, 1, 11, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الجُمعۃ', 'مَثَلُ  الَّذِیۡنَ حُمِّلُوا  التَّوۡرٰىۃَ  ثُمَّ  لَمۡ یَحۡمِلُوۡہَا کَمَثَلِ  الۡحِمَارِ یَحۡمِلُ اَسۡفَارًا ؕ بِئۡسَ مَثَلُ  الۡقَوۡمِ الَّذِیۡنَ کَذَّبُوۡا بِاٰیٰتِ اللّٰہِ ؕ وَ اللّٰہُ  لَا یَہۡدِی الۡقَوۡمَ  الظّٰلِمِیۡنَ ﴿۵﴾', 'جن لوگوں کو تورات کا حامل بنایا گیا پھر انہوں نے اسکے حامل ہونے کا حق ادا نہ کیا انکی مثال گدھے کی سی ہے جس پر بڑی بڑی کتابیں لدی ہوں۔ جو لوگ اللہ کی آیتوں کی تکذیب کرتے ہیں انکی مثال بری ہے۔ اور اللہ ظالم لوگوں کو ہدایت نہیں دیتا۔', 'مثال ان لوگوں کی جن پر لادی توریت پھر نہ اٹھائی انہوں نے جیسے مثال گدھے کی کہ پیٹھ پر لے چلتا ہے کتابیں [۵] بری مثال ہے اُن لوگوں کی [۶] جنہوں نے جھٹلایا اللہ کی باتوں کو [۷] اور اللہ راہ نہیں دیتا بے انصاف لوگوں کو [۸]', 'The likeness of those who were entrusted with the (obligation of the) Taurat (Torah) (i.e. to obey its commandments and to practise its legal laws), but who subsequently failed in those (obligations), is as the likeness of a donkey who carries huge burdens of books (but understands nothing from them). How bad is the example (or the likeness) of people who deny the Ayat (proofs, evidences, verses, signs, revelations, etc.) of Allah. And Allah guides not the people who are Zalimoon (polytheists, wrong-doers, disbelievers, etc.).', 'The example of those who were ordered to bear (the responsibility of acting upon) the Torah, then they did not bear it, is like a donkey that carries a load of books. Evil is the example of those who have rejected Allah’s verses. And Allah does not guide the wrongdoing people.'),
(5183, 62, 6, 1, 11, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الجُمعۃ', 'قُلۡ یٰۤاَیُّہَا  الَّذِیۡنَ ہَادُوۡۤا  اِنۡ  زَعَمۡتُمۡ اَنَّکُمۡ  اَوۡلِیَآءُ  لِلّٰہِ  مِنۡ  دُوۡنِ النَّاسِ فَتَمَنَّوُا الۡمَوۡتَ  اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ ﴿۶﴾', 'کہدو کہ اے یہود اگر تمکو یہ دعوٰی ہو کہ تم ہی اللہ کے دوست ہو اور دوسرے لوگ نہیں تو اگر تم سچے ہو تو ذرا موت کی آرزو تو کرو۔', 'تو کہہ اے یہودی ہونے والو اگر تم کو دعوٰی ہے کہ تم دوست ہو اللہ کے سب لوگوں کے سوائے تو مناؤ اپنے مرنے کو اگر تم سچے ہو', 'Say (O Muhammad SAW): \"O you Jews! If you pretend that you are friends of Allah, to the exclusion of (all) other mankind, then long for death if you are truthful.\"', 'Say, “O you who are Jews, if you claim that you are the friends of Allah to the exclusion of all other people, then express your desire for death, if you are true.'),
(5184, 62, 7, 1, 11, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الجُمعۃ', 'وَ لَا یَتَمَنَّوۡنَہٗۤ  اَبَدًۢا  بِمَا قَدَّمَتۡ اَیۡدِیۡہِمۡ ؕ وَ اللّٰہُ  عَلِیۡمٌۢ   بِالظّٰلِمِیۡنَ ﴿۷﴾', 'اور یہ لوگ ان اعمال کے سبب جو یہ کر چکے ہیں ہر گز اسکی آرزو نہیں کریں گے اور اللہ ظالموں سے خوب واقف ہے۔', 'اور وہ کبھی نہ منائیں گے اپنا مرنا اُن کاموں کی وجہ سے جنکو آگے بھیج چکے ہیں اُنکے ہاتھ اور اللہ کو خوب معلوم ہیں سب گنہگار [۹]', 'But they will never long for it (death), because of what (deeds) their hands have sent before them! And Allah knows well the Zalimoon (polytheists, wrong-doers, disbelievers, etc.).', 'And they will never express this desire, because of what their hands have sent ahead. And Allah is fully aware of the wrongdoers.'),
(5185, 62, 8, 1, 11, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الجُمعۃ', 'قُلۡ  اِنَّ الۡمَوۡتَ الَّذِیۡ تَفِرُّوۡنَ مِنۡہُ  فَاِنَّہٗ مُلٰقِیۡکُمۡ  ثُمَّ  تُرَدُّوۡنَ  اِلٰی عٰلِمِ الۡغَیۡبِ وَ الشَّہَادَۃِ  فَیُنَبِّئُکُمۡ  بِمَا کُنۡتُمۡ تَعۡمَلُوۡنَ ٪﴿۸﴾', 'کہدو کہ موت جس سے تم بھاگتے ہو وہ تو تمہارے سامنے آ کر رہے گی پھر تم پوشیدہ اور ظاہر کے جاننے والے مالک کی طرف لوٹائے جاؤ گے پھر جو کچھ تم کرتے رہے ہو وہ سب تمہیں بتائے گا۔', 'تو کہہ موت وہ جس سے تم بھاگتے ہو وہ تم سے ضرور ملنے والی ہے پھر تم پھیرے جاؤ گے اس سے چھپے اور کھلے جاننے والے کے پاس پھر جتلا دے گا تم کو جو تم کرتے تھے [۱۰]', 'Say (to them): \"Verily, the death from which you flee will surely meet you, then you will be sent back to (Allah), the All-Knower of the unseen and the seen, and He will tell you what you used to do.\"', 'Say, “Indeed, the death from which you (try to) run away has to visit you, then you will be sent back to the Knower of the Unseen and the seen, and He will tell you what you used to do.'),
(5186, 62, 9, 2, 12, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الجُمعۃ', 'یٰۤاَیُّہَا  الَّذِیۡنَ  اٰمَنُوۡۤا اِذَا نُوۡدِیَ لِلصَّلٰوۃِ مِنۡ یَّوۡمِ الۡجُمُعَۃِ  فَاسۡعَوۡا اِلٰی ذِکۡرِ اللّٰہِ  وَ ذَرُوا  الۡبَیۡعَ ؕ ذٰلِکُمۡ خَیۡرٌ  لَّکُمۡ   اِنۡ  کُنۡتُمۡ  تَعۡلَمُوۡنَ ﴿۹﴾', 'مومنو! جب جمعے کے دن نماز کے لئے اذان دی جائے تو اللہ کے ذکر کی طرف لپکو اور خریدوفروخت ترک کر دو اگر سمجھو تو یہ تمہارے حق میں بہتر ہے۔', 'اے ایمان والو جب اذان ہو نماز کی جمعہ کے دن تو دوڑو اللہ کی یاد کو اور چھوڑ دو خرید و فروخت [۱۱] یہ بہتر ہے تمہارے حق میں اگر تم کو سمجھ ہے [۱۲]', 'O you who believe (Muslims)! When the call is proclaimed for the Salat (prayer) on the day of Friday (Jumuah prayer), come to the remembrance of Allah (Jumuah religious talk (Khutbah) and Salat (prayer)) and leave off business (and every other thing), that is better for you if you did but know!', 'O you who believe, when the call for Salāh (prayer) is proclaimed on Friday, hasten for the remembrance of Allah, and leave off business. That is much better for you, if you but know.'),
(5187, 62, 10, 2, 12, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الجُمعۃ', 'فَاِذَا  قُضِیَتِ الصَّلٰوۃُ  فَانۡتَشِرُوۡا فِی الۡاَرۡضِ وَ ابۡتَغُوۡا مِنۡ فَضۡلِ اللّٰہِ وَ اذۡکُرُوا اللّٰہَ  کَثِیۡرًا  لَّعَلَّکُمۡ تُفۡلِحُوۡنَ ﴿۱۰﴾', 'پھر جب نماز ہو چکے تو زمین میں پھیل جاؤ اور اللہ کا فضل تلاش کرو اور اللہ کو بہت بہت یاد کرتے رہو تاکہ کامیاب ہو جاؤ۔', 'پھر جب تمام ہو چکے نماز تو پھیل پڑو زمین میں اور ڈھونڈو فضل اللہ کا اور یاد کرو اللہ کو بہت سا تاکہ تمہارا بھلا ہو [۱۳]', 'Then when the (Jumuah) Salat (prayer) is finished, you may disperse through the land, and seek the Bounty of Allah (by working, etc.), and remember Allah much, that you may be successful.', 'Then once the Salāh is over, disperse in the land, and seek the grace of Allah, and remember Allah abundantly, so that you may be successful.'),
(5188, 62, 11, 2, 12, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الجُمعۃ', 'وَ اِذَا  رَاَوۡا  تِجَارَۃً  اَوۡ لَہۡوَۨا انۡفَضُّوۡۤا اِلَیۡہَا وَ تَرَکُوۡکَ  قَآئِمًا ؕ قُلۡ مَا عِنۡدَ اللّٰہِ  خَیۡرٌ  مِّنَ اللَّہۡوِ وَ مِنَ  التِّجَارَۃِ ؕ وَ اللّٰہُ  خَیۡرُ  الرّٰزِقِیۡنَ ﴿٪۱۱﴾', 'اور جب ان لوگوں نے سودا بکتا یا تماشا ہوتا دیکھا تو ادھر بھاگ لئے اور اے نبی ﷺ تمہیں خطبے میں کھڑا چھوڑ گئے۔ کہدو کہ جو چیز اللہ کے ہاں ہے وہ تماشے اور سودے سے کہیں بہتر ہے۔ اور اللہ سب سے بہتر رزق دینے والا ہے۔', 'اور جب دیکھیں سودا بکتا یا کچھ تماشا متفرق ہو جائیں اُسکی طرف اور تجھ کو چھوڑ جائیں کھڑا تو کہہ جو اللہ کے پاس ہے سو بہتر ہے تماشے سے اور سوداگری سے اور اللہ بہتر ہے روزی دینے والا [۱۴]', 'And when they see some merchandise or some amusement (beating of Tambur (drum) etc.) they disperse headlong to it, and leave you (Muhammad SAW) standing (while delivering Jumuahs religious talk (Khutbah)). Say \"That which Allah has is better than any amusement or merchandise! And Allah is the Best of providers.\"', 'And when they see some merchandise or amusement, they break away to it, and leave you (O prophet,) standing. Say, “What is with Allah is much better than the amusement and the merchandise, and Allah is the best giver of sustenance.'),
(5189, 63, 1, 1, 13, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المُنٰفِقُون', 'اِذَا جَآءَکَ  الۡمُنٰفِقُوۡنَ  قَالُوۡا نَشۡہَدُ اِنَّکَ  لَرَسُوۡلُ اللّٰہِ ۘ  وَ اللّٰہُ یَعۡلَمُ  اِنَّکَ لَرَسُوۡلُہٗ ؕ وَ اللّٰہُ  یَشۡہَدُ  اِنَّ  الۡمُنٰفِقِیۡنَ لَکٰذِبُوۡنَ ۚ﴿۱﴾', 'اے پیغمبر ﷺ جب منافق لوگ تمہارے پاس آتے ہیں تو ازراہ نفاق کہتے ہیں کہ ہم اقرار کرتے ہیں کہ آپ بیشک اللہ کے پیغمبر ہیں اور اللہ جانتا ہے کہ درحقیقت تم اسکے پیغمبر ہو اور اللہ ظاہر کئے دیتا ہے کہ منافق یقینًا جھوٹے ہیں۔', 'جب آئیں تیرے پاس منافق کہیں ہم قائل ہیں تو رسول ہے اللہ کا [۱] اور اللہ جانتا ہے کہ تو اُس کا رسول ہے اور اللہ گواہی دیتا ہے کہ یہ منافق جھوٹے ہیں [۲]', 'When the hypocrites come to you (O Muhammad SAW), they say: \"We bear witness that you are indeed the Messenger of Allah.\" Allah knows that you are indeed His Messenger and Allah bears witness that the hypocrites are liars indeed.', 'When the hypocrites come to you, they say, “We bear witness that you are indeed the messenger of Allah.”-Allah knows that you are really His messenger-But Allah testifies that the hypocrites are actually liars.'),
(5190, 63, 2, 1, 13, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المُنٰفِقُون', 'اِتَّخَذُوۡۤا  اَیۡمَانَہُمۡ  جُنَّۃً  فَصَدُّوۡا عَنۡ سَبِیۡلِ اللّٰہِ ؕ اِنَّہُمۡ سَآءَ  مَا کَانُوۡا یَعۡمَلُوۡنَ ﴿۲﴾', 'انہوں نے اپنی قسموں کو ڈھال بنا رکھا ہے۔ اور انکے ذریعے سے لوگوں کو اللہ کی راہ سے روک رہے ہیں۔ کچھ شک نہیں کہ جو کام یہ کرتے ہیں برے ہیں۔', 'انہوں نے رکھا ہے اپنی قسموں کو ڈھال بنا کر [۳] پھر روکتے ہیں اللہ کی راہ سے یہ لوگ برے کام ہیں جو کر رہے ہیں [۴]', 'They have made their oaths a screen (for their hypocrisy). Thus they hinder (men) from the Path of Allah. Verily, evil is what they used to do.', 'They have made their oaths a shield, and thus they have prevented (others) from the way of Allah. Surely evil is what they have been doing.'),
(5191, 63, 3, 1, 13, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المُنٰفِقُون', 'ذٰلِکَ بِاَنَّہُمۡ  اٰمَنُوۡا ثُمَّ  کَفَرُوۡا  فَطُبِعَ عَلٰی  قُلُوۡبِہِمۡ  فَہُمۡ  لَا  یَفۡقَہُوۡنَ ﴿۳﴾', 'یہ اس لئے کہ یہ پہلے تو ایمان لائے پھر کافر ہو گئے تو انکے دلوں پر مہر لگا دی گئ سو اب یہ سمجھتے ہی نہیں۔', 'یہ اس لئے کہ وہ ایمان لائے  پھر منکر ہو گئے پھر مہر لگ گئ اُنکے دل پر سو وہ اب کچھ نہیں سمجھتے [۵]', 'That is because they believed, then disbelieved, therefore their hearts are sealed, so they understand not.', 'That is because they declared faith (in Islam apparently), then disbelieved (secretly). Therefore a seal has been set on their hearts, and thus they do not understand.'),
(5192, 63, 4, 1, 13, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المُنٰفِقُون', 'وَ اِذَا  رَاَیۡتَہُمۡ  تُعۡجِبُکَ اَجۡسَامُہُمۡ ؕ وَ اِنۡ یَّقُوۡلُوۡا  تَسۡمَعۡ  لِقَوۡلِہِمۡ ؕ کَاَنَّہُمۡ خُشُبٌ مُّسَنَّدَۃٌ ؕ یَحۡسَبُوۡنَ  کُلَّ صَیۡحَۃٍ  عَلَیۡہِمۡ ؕ ہُمُ  الۡعَدُوُّ  فَاحۡذَرۡہُمۡ ؕ قٰتَلَہُمُ   اللّٰہُ ۫ اَنّٰی  یُؤۡفَکُوۡنَ  ﴿۴﴾', 'اور جب تم انکے تناسب اعضاء کو دیکھتے ہو تو انکے جسم تمہیں کیا ہی اچھے معلوم ہوتے ہیں اور جب یہ گفتگو کرتے ہیں تو تم انکی تقریر کو توجہ سے سنتے ہو گویا لکڑیاں ہیں جو دیواروں سے لگائی گئ ہیں بزدل ایسے کہ ہر زور کی آواز کو سمجھیں کہ ان پر بلا آئی۔ یہ تمہارے دشمن ہی ہیں سو ان سے محتاط رہنا۔ اللہ انکو ہلاک کرے یہ کہاں بہکے پھرتے ہیں۔', 'اور جب تو دیکھے اُنکو تو اچھے لگیں تجھ کو انکے ڈیل اور اگر بات کہیں سنے تو اُنکی بات [۶] کیسے ہیں جیسے کہ لکڑی لگا دی دیوار سے [۷] جو کوئی چیخے جانیں ہم ہی پر بلا آئی [۸] وہی ہیں دشمن اُن سے بچتا رہ [۹] گردن مارے انکی اللہ کہاں سے پھرے جاتے ہیں [۱۰]', 'And when you look at them, their bodies please you; and when they speak, you listen to their words. They are as blocks of wood propped up. They think that every cry is against them. They are the enemies, so beware of them. May Allah curse them! How are they denying (or deviating from) the Right Path.', 'And if you see them, their physiques would attract you, and if they speak, you would (like to) listen to their speech (because of their eloquence). (Yet, being devoid of substance,) it is as if they were propped up beams of timber. They deem every shout (they hear) to be against them (out of cowardice). They are the enemy; so beware of them. May Allah destroy them. How perverted are they!'),
(5193, 63, 5, 1, 13, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المُنٰفِقُون', 'وَ  اِذَا  قِیۡلَ  لَہُمۡ  تَعَالَوۡا  یَسۡتَغۡفِرۡ لَکُمۡ رَسُوۡلُ  اللّٰہِ  لَوَّوۡا رُءُوۡسَہُمۡ وَ رَاَیۡتَہُمۡ یَصُدُّوۡنَ وَ ہُمۡ مُّسۡتَکۡبِرُوۡنَ ﴿۵﴾', 'اور جب ان سے کہا جائے کہ آؤ رسول اللہ ﷺ تمہارے لئے مغفرت مانگیں تو سر ہلا دیتے ہیں اور تم انکو دیکھو کہ تکبر کرتے ہوئے رکے ہی رہتے ہیں۔', 'اور جب کہیے  اُنکو آؤ معاف کرا دے تم کو رسول اللہ کا مٹکاتے ہیں اپنے سر اور تو دیکھےکہ وہ رکتے ہیں اور وہ غرور کرتے ہیں [۱۱]', 'And when it is said to them: \"Come, so that the Messenger of Allah may ask forgiveness from Allah for you\", they turn aside their heads, and you would see them turning away their faces in pride.', 'And when it is said to them, “Come on, so that Allah’s Messenger may pray for your forgiveness”, they twist their heads (in aversion), and you see them turning away in arrogance.'),
(5194, 63, 6, 1, 13, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المُنٰفِقُون', 'سَوَآءٌ  عَلَیۡہِمۡ  اَسۡتَغۡفَرۡتَ لَہُمۡ  اَمۡ لَمۡ تَسۡتَغۡفِرۡ لَہُمۡ ؕ لَنۡ یَّغۡفِرَ اللّٰہُ  لَہُمۡ ؕ اِنَّ اللّٰہَ  لَا یَہۡدِی الۡقَوۡمَ الۡفٰسِقِیۡنَ ﴿۶﴾', 'تم انکے لئے مغفرت مانگو یا نہ مانگو انکے آگے برابر ہے۔ اللہ انکو ہرگز نہ بخشے گا۔ بیشک اللہ نافرمان لوگوں کو ہدایت نہیں دیا کرتا۔', 'برابر ہے اُن پر تو معافی چاہے اُنکی یا نہ معافی چاہے ہرگز نہ معاف کرے گا اُنکو اللہ بیشک اللہ راہ نہیں دیتا نافرمان لوگوں کو [۱۲]', 'It is equal to them whether you (Muhammad SAW) ask forgiveness or ask not forgiveness for them. Verily, Allah guides not the people who are the Fasiqeen (rebellious, disobedient to Allah) .', 'It is equal in their case, whether you (O prophet,) pray for their forgiveness or do not pray, Allah will never forgive them. Indeed Allah does not guide the sinning people.'),
(5195, 63, 7, 1, 13, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المُنٰفِقُون', 'ہُمُ  الَّذِیۡنَ یَقُوۡلُوۡنَ  لَا تُنۡفِقُوۡا عَلٰی مَنۡ عِنۡدَ  رَسُوۡلِ اللّٰہِ  حَتّٰی  یَنۡفَضُّوۡا ؕ وَ لِلّٰہِ خَزَآئِنُ  السَّمٰوٰتِ وَ الۡاَرۡضِ وَ لٰکِنَّ  الۡمُنٰفِقِیۡنَ  لَا  یَفۡقَہُوۡنَ ﴿۷﴾', 'یہی ہیں جو کہتے ہیں کہ جو لوگ رسول اللہ ﷺ کے پاس ہیں ان پر کچھ خرچ نہ کرو۔ یہاں تک کہ وہ خود بخود بھاگ جائیں۔ حالانکہ آسمانوں اور زمین کے خزانے اللہ ہی کے ہیں لیکن منافق نہیں سمجھتے۔', 'وہی ہیں جو کہتے ہیں مت خرچ کرو  ان پر جو  پاس رہتے ہیں رسول اللہ کے یہاں تک کہ متفرق ہو جائیں [۱۳] اور اللہ کے ہیں خزانے آسمانوں کے اور زمین کے ولیکن منافق نہیں سمجھتے [۱۴]', 'They are the ones who say: \"Spend not on those who are with Allahs Messenger, until they desert him.\" And to Allah belong the treasures of the heavens and the earth, but the hypocrites comprehend not.', 'They are those who say, “Do not spend on those who are with Allah’s Messenger until they disperse. And to Allah belong the treasures of the heavens and the earth, but the hypocrites do not understand.'),
(5196, 63, 8, 1, 13, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المُنٰفِقُون', 'یَقُوۡلُوۡنَ  لَئِنۡ  رَّجَعۡنَاۤ  اِلَی  الۡمَدِیۡنَۃِ لَیُخۡرِجَنَّ الۡاَعَزُّ  مِنۡہَا الۡاَذَلَّ ؕ وَ لِلّٰہِ الۡعِزَّۃُ  وَ لِرَسُوۡلِہٖ وَ لِلۡمُؤۡمِنِیۡنَ وَ لٰکِنَّ  الۡمُنٰفِقِیۡنَ  لَا  یَعۡلَمُوۡنَ ٪﴿۸﴾', 'کہتے ہیں کہ اگر ہم لوٹ کر مدینے پہنچے تو عزت والے ذلیل لوگوں کو  وہاں سے نکال باہر کریں گے۔ حالانکہ عزت اللہ کی ہے اور اسکے رسول ﷺ کی اور مومنوں کی لیکن منافق نہیں جانتے۔', 'کہتے ہیں البتہ اگر ہم پھر گئے مدینہ کو تو نکال دے گا جس کا زور ہے وہاں سے کمزور لوگوں کو اور زور تو اللہ کا ہے اور اُسکے رسول کا اور ایمان والوں کا لیکن منافق نہیں جانتے [۱۵]', 'They (hyprocrites) say: \"If we return to Al-Madinah, indeed the more honourable (Abdoollah bin Ubai bin Salul, the chief of hyprocrites at AlMadinah) will expel therefrom the meaner (i.e. Allahs Messenger SAW).\" But honour, power and glory belong to Allah, His Messenger (Muhammad SAW), and to the believers, but the hypocrites know not.', 'They say, “If we return to Madīnah, the more honorable ones will drive out the meaner ones from there.” And to Allah belongs the honour, and to His Messenger, and to the believers, but the hypocrites do not know.'),
(5197, 63, 9, 2, 14, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المُنٰفِقُون', 'یٰۤاَیُّہَا  الَّذِیۡنَ  اٰمَنُوۡا  لَا تُلۡہِکُمۡ اَمۡوَالُکُمۡ  وَ لَاۤ  اَوۡلَادُکُمۡ عَنۡ ذِکۡرِ اللّٰہِ ۚ وَ مَنۡ یَّفۡعَلۡ  ذٰلِکَ  فَاُولٰٓئِکَ ہُمُ الۡخٰسِرُوۡنَ ﴿۹﴾', 'مومنو! تمہارا مال اور اولاد تمکو اللہ کی یاد سے غافل نہ کر دے۔ اور جو ایسا کرے گا تو وہ لوگ خسارہ پانے والے ہیں۔', 'اے ایمان والو غافل نہ کردیں تم کو تمہاے مال اور تمہاری اولاد اللہ کی یاد سے اور جو  کوئی یہ کام کرے تو وہی لوگ ہیں ٹوٹے میں [۱۶]', 'O you who believe! Let not your properties or your children divert you from the remembrance of Allah. And whosoever does that, then they are the losers.', 'O you who believe, your riches and your children must not divert you from the remembrance of Allah. And those who do that are the losers.'),
(5198, 63, 10, 2, 14, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المُنٰفِقُون', 'وَ اَنۡفِقُوۡا مِنۡ مَّا  رَزَقۡنٰکُمۡ مِّنۡ  قَبۡلِ اَنۡ یَّاۡتِیَ  اَحَدَکُمُ  الۡمَوۡتُ فَیَقُوۡلَ  رَبِّ لَوۡ لَاۤ  اَخَّرۡتَنِیۡۤ  اِلٰۤی  اَجَلٍ قَرِیۡبٍ ۙ فَاَصَّدَّقَ وَ  اَکُنۡ  مِّنَ  الصّٰلِحِیۡنَ ﴿۱۰﴾', 'اور جو مال ہم نے تمکو دیا ہے اس میں سے اس وقت سے پیشتر خرچ کر لو کہ تم میں سے کسی کی موت آ جائے تو اس وقت کہنے لگے کہ اے میرے پروردگار تو نے مجھے تھوڑی سی اور مہلت کیوں نہ دی تاکہ میں خیرات کر لیتا اور نیک لوگوں میں داخل ہو جاتا۔', 'اور خرچ کرو  کچھ ہمارا دیا ہوا اُس سے پہلے کہ آ پہنچے تم میں کسی کو موت تب کہے اے رب کیوں نہ ڈھیل دی تو نے مجھ کو ایک تھوڑی سے مدت کہ میں خیرات کرتا اور ہو جاتا نیک لوگوں میں', 'And spend (in charity) of that with which We have provided you, before death comes to one of you and he says: \"My Lord! If only You would give me respite for a little while (i.e. return to the worldly life), then I should give Sadaqah (i.e. Zakat) of my wealth , and be among the righteous (i.e. perform Hajj (pilgrimage to Makkah)).', 'And spend out of what We have given to you before death overtakes one of you and he says, “My Lord, would you not give me respite to a near term, so that I should pay Sadaqah (alms) and become one of the righteous?”'),
(5199, 63, 11, 2, 14, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'المُنٰفِقُون', 'وَ لَنۡ  یُّؤَخِّرَ اللّٰہُ  نَفۡسًا  اِذَا جَآءَ اَجَلُہَا ؕ وَ اللّٰہُ  خَبِیۡرٌۢ  بِمَا تَعۡمَلُوۡنَ ﴿٪۱۱﴾', 'اور جب کسی کی موت آ جاتی ہے تو اللہ اسکو ہرگز مہلت نہیں دیتا۔ اور جو کچھ تم کرتے ہو اللہ اس سے خبردار ہے۔', 'اور ہرگز نہ ڈھیل دے گا اللہ کسی جی کو جب آ پہنچا اُس کا وعدہ [۱۷] اور اللہ کو خبر ہے جو تم کرتے ہو [۱۸]', 'And Allah grants respite to none when his appointed time (death) comes. And Allah is All-Aware of what you do.', 'But Allah will never give respite to anyone, once his appointed time will come. And Allah is All-Aware of what you do.'),
(5200, 64, 1, 1, 15, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'یُسَبِّحُ  لِلّٰہِ  مَا فِی السَّمٰوٰتِ وَ مَا فِی الۡاَرۡضِ ۚ لَہُ  الۡمُلۡکُ وَ لَہُ  الۡحَمۡدُ ۫ وَ ہُوَ عَلٰی کُلِّ  شَیۡءٍ   قَدِیۡرٌ ﴿۱﴾', 'جو چیز آسمانوں میں ہے اور جو چیز زمین میں ہے سب اللہ کی تسبیح کرتی ہے۔ اسی کی سچی بادشاہی ہے اور اسی کی تعریف ہے اور وہ ہر چیز پر قادر ہے۔', 'پاکی بول رہا ہے اللہ کی جو کچھ ہے آسمانوں میں اور جو کچھ ہے زمین میں اُسی کا راج ہے اور اُسی کی تعریف ہے [۱] اور وہی ہر چیز کر سکتا ہے', 'Whatsoever is in the heavens and whatsoever is on the earth glorifies Allah. His is the dominion, and to Him belong all the praises and thanks, and He is Able to do all things.', 'All that is in the heavens and all that is in the earth proclaim Allah’s purity. To Him belongs the kingdom, and for Him is all praise, and He is powerful over every thing.'),
(5201, 64, 2, 1, 15, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'ہُوَ  الَّذِیۡ خَلَقَکُمۡ  فَمِنۡکُمۡ کَافِرٌ وَّ مِنۡکُمۡ  مُّؤۡمِنٌ ؕ وَ  اللّٰہُ  بِمَا تَعۡمَلُوۡنَ بَصِیۡرٌ ﴿۲﴾', 'وہی تو ہے جس نے تمکو پیدا کیا پھر کوئی تم میں کافر ہے اور کوئی مومن۔ اور جو کچھ تم کرتے ہو اللہ اسکو دیکھتا ہے۔', 'وہی ہے جس نے تم کو بنایا پھر کوئی تم میں منکر ہے اورکوئی تم میں ایماندار [۲] اور اللہ جو تم کرتے ہو دیکھتا ہے', 'He it is Who created you, then some of you are disbelievers and some of you are believers. And Allah is All-Seer of what you do.', 'He is the One who created you, then some of you are disbelievers, and some of you are believers. And Allah is Watchful of what you do.'),
(5202, 64, 3, 1, 15, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'خَلَقَ  السَّمٰوٰتِ وَ الۡاَرۡضَ بِالۡحَقِّ وَ صَوَّرَکُمۡ  فَاَحۡسَنَ صُوَرَکُمۡ ۚ وَ اِلَیۡہِ الۡمَصِیۡرُ ﴿۳﴾', 'اسی نے آسمانوں اور زمین کو حکمت سے پیدا کیا اور اسی نے تمہاری صورتیں بنائیں اور صورتیں بھی اچھی بنائیں اور اسی کی طرف تمہیں لوٹ کر جانا ہے۔', 'بنایا آسمانوں کو اور زمین کو تدبیر سے اور صورت کھینچی تمہاری پھر اچھی بنائی تمہاری صورت [۳] اور اُسکی طرف سب کو پھر جانا ہے', 'He has created the heavens and the earth with truth, and He shaped you and made good your shapes, and to Him is the final Return.', 'He has created the heavens and the earth rightly, and shaped your figures, and made your figures good, and to Him is the final return.'),
(5203, 64, 4, 1, 15, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'یَعۡلَمُ  مَا فِی السَّمٰوٰتِ وَ الۡاَرۡضِ وَ یَعۡلَمُ  مَا تُسِرُّوۡنَ وَ مَا تُعۡلِنُوۡنَ ؕ وَ اللّٰہُ  عَلِیۡمٌۢ  بِذَاتِ  الصُّدُوۡرِ ﴿۴﴾', 'جو کچھ آسمانوں اور زمین میں ہے وہ سب جانتا ہے۔ اور جو کچھ تم چھپا کر کرتے ہو اور جو کھلم کھلا کرتے ہو اس سے بھی آگاہ ہے۔ اور اللہ دلوں کے بھیدوں تک سے واقف ہے۔', 'جانتا ہے جو کچھ ہے آسمانوں میں اور زمین میں اور جانتا ہے جو تم چھپاتے ہو اور جو کھول کر کرتے ہو اور اللہ کو معلوم ہے جیوں کی بات', 'He knows what is in the heavens and on earth, and He knows what you conceal and what you reveal. And Allah is the All-Knower of what is in the breasts (of men).', 'He knows all that is in the heavens and the earth, and He knows whatever you conceal and whatever you reveal. Allah is fully aware of what lies in the hearts.'),
(5204, 64, 5, 1, 15, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'اَلَمۡ  یَاۡتِکُمۡ نَبَؤُا  الَّذِیۡنَ کَفَرُوۡا مِنۡ قَبۡلُ ۫ فَذَاقُوۡا وَبَالَ  اَمۡرِہِمۡ وَ لَہُمۡ عَذَابٌ  اَلِیۡمٌ  ﴿۵﴾', 'کیا تمکو ان لوگوں کے حال کی خبر نہیں پہنچی جو پہلے کافر ہوئے تھے تو انہوں نے اپنی کرتوت کی سزا کا مزا چکھ لیا اور ابھی دکھ دینے والا عذاب اور ہونا ہے۔', 'کیا پہنچی نہیں تم کو خبر اُن لوگوں کی جو منکر ہو چکے ہیں پہلے پھر اُنہوں نے چکھی سزا اپنے کام کی اور اُن کو عذاب دردناک ہے  [۴]', 'Has not the news reached you of those who disbelieved aforetime? And so they tasted the evil result of their disbelief, and theirs will be a painful torment.', 'Did the news of those people not come to you who disbelieved earlier, and tasted (in this world) the evil consequence of their conduct, and for them (in the Hereafter) there is a painful punishment?'),
(5205, 64, 6, 1, 15, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'ذٰلِکَ  بِاَنَّہٗ  کَانَتۡ  تَّاۡتِیۡہِمۡ  رُسُلُہُمۡ بِالۡبَیِّنٰتِ فَقَالُوۡۤا  اَبَشَرٌ یَّہۡدُوۡنَنَا ۫ فَکَفَرُوۡا وَ تَوَلَّوۡا وَّ اسۡتَغۡنَی اللّٰہُ ؕ وَ اللّٰہُ  غَنِیٌّ  حَمِیۡدٌ ﴿۶﴾', 'یہ اس لئے کہ انکے پاس پیغمبر کھلی نشانیاں لے کر آتے تو وہ کہتے کہ کیا ایک آدمی ہمیں ہدایت کریگا؟ تو انہوں نے ان کو نہ مانا اور منہ پھیر لیا اور اللہ بھی بے نیاز ہو گیا۔ اور اللہ بے نیاز ہے لائق حمدوثنا ہے۔', 'یہ اس لئےکہ لاتےتھے اُنکے پاس اُن کے سول نسانیاں پھر کتے کیا آدمی ہم کر راہ سمجھائیں گے پھر منکر ہوئے اور منہ موڑ لیا [۵] اور اللہ نے بے پروائی کی اور اللہ بے پروا ہے سب تعریفوں والا [۶]', 'That was because there came to them their Messengers with clear proofs (signs), but they said: \"Shall mere men guide us?\" So they disbelieved and turned away (from the truth), and Allah was not in need (of them). And Allah is Rich (Free of all wants), Worthy of all praise.', 'That is because their messengers used to bring them clear proofs, but they said, “Shall some mortals give us guidance?” Thus they disbelieved and turned away, and Allah did not care. Allah is All-Independent, Ever-Praised.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(5206, 64, 7, 1, 15, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'زَعَمَ  الَّذِیۡنَ  کَفَرُوۡۤا اَنۡ  لَّنۡ یُّبۡعَثُوۡا ؕ قُلۡ  بَلٰی وَ رَبِّیۡ  لَتُبۡعَثُنَّ  ثُمَّ  لَتُنَبَّؤُنَّ بِمَا عَمِلۡتُمۡ ؕ وَ ذٰلِکَ عَلَی اللّٰہِ   یَسِیۡرٌ ﴿۷﴾', 'جو لوگ کافر ہیں ان کا اعتقاد ہے کہ وہ دوبارہ ہرگز نہیں اٹھائے جائیں گے۔ کہدو کیوں نہیں میرے پروردگار کی قسم تم ضرور اٹھائے جاؤ گے پھر جو کام تم کرتے رہے ہو  وہ تمہیں بتائے جائیں گے۔ اور یہ بات اللہ کو آسان ہے۔', 'دعوٰی کرتے ہیں منکر کہ ہر گز  اُنکو کوئی نہ اٹھائے گا [۷] تو کہہ کیوں نہیں قسم ہے میرے رب کی تم کو بیشک اٹھانا ہے پھر تم کو جتلانا ہے جو کچھ تم نے کیا اور یہ اللہ پر آسان ہے [۸]', 'The disbelievers pretend that they will never be resurrected (for the Account). Say (O Muhammad SAW): \"Yes! By my Lord, you will certainly be resurrected, then you will be informed of (and recompensed for) what you did, and that is easy for Allah.', 'The disbelievers claim that they will never be raised again (after death). Say, “Why not? By my Lord, you will be raised again, and then you will be told about what you did. That is so easy for Allah.”'),
(5207, 64, 8, 1, 15, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'فَاٰمِنُوۡا بِاللّٰہِ وَ رَسُوۡلِہٖ وَ النُّوۡرِ الَّذِیۡۤ اَنۡزَلۡنَا ؕ وَ اللّٰہُ  بِمَا تَعۡمَلُوۡنَ خَبِیۡرٌ ﴿۸﴾', 'تو اللہ پر اور اسکے رسول ﷺ پر اور اس نور یعنی قرآن پر جو ہم نے نازل فرمایا ہے ایمان لاؤ اور اللہ تمہارے سب اعمال سے خبردار ہے۔', 'سو ایمان لاؤ اللہ پر اور اسکے رسول پر اور اُس نور پر جو ہم نے اتارا [۹] اور اللہ کو تمہاے سب کام کی خبر ہے [۱۰]', 'Therefore, believe in Allah and His Messenger (Muhammad SAW), and in the Light (this Quran) which We have sent down. And Allah is All-Aware of what you do.', 'So, believe in Allah and His Messenger, and in the light We have sent down. And Allah is fully aware of what you do.'),
(5208, 64, 9, 1, 15, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'یَوۡمَ یَجۡمَعُکُمۡ  لِیَوۡمِ الۡجَمۡعِ ذٰلِکَ یَوۡمُ التَّغَابُنِ ؕ وَ مَنۡ یُّؤۡمِنۡۢ  بِاللّٰہِ وَ یَعۡمَلۡ  صَالِحًا یُّکَفِّرۡ عَنۡہُ  سَیِّاٰتِہٖ وَ یُدۡخِلۡہُ  جَنّٰتٍ تَجۡرِیۡ  مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَاۤ  اَبَدًا ؕ ذٰلِکَ الۡفَوۡزُ الۡعَظِیۡمُ ﴿۹﴾', 'جس دن وہ تمکو اکٹھا کرے گا یعنی حشر کے دن وہ نقصان اٹھانے کا دن ہے۔ اور جو شخص اللہ پر ایمان لائے اور نیک عمل کرے وہ اس سے اسکی برائیاں دور کر دے گا اور جنت کے باغوں میں جنکے نیچے نہریں بہ رہی ہیں داخل کرے گا وہ ہمیشہ ہمیشہ ان میں رہیں گے یہی بڑی کامیابی ہے۔', 'جس دن تم کو اکٹھا کرے گا جمع ہونے کے دن وہ دن ہے ہار جیت کا [۱۱] اور جو کوئی یقین لائے اللہ پر اور کرے کام بھلا اتار دے گا اس پر سے اُسکی برائیاں [۱۲] اور داخل کرے گا اُسکو باغوں میں جنکے نیچے بہتی ہیں ندیاں رہا کریں اُن میں ہمیشہ یہی ہے بڑی مراد ملنی [۱۳]', '(And remember) the Day when He will gather you (all) on the Day of Gathering, that will be the Day of mutual loss and gain (i.e. loss for the disbelievers as they will enter the Hell-fire and gain for the believers as they will enter Paradise). And whosoever believes in Allah and performs righteous good deeds, He will remit from him his sins, and will admit him to Gardens under which rivers flow (Paradise) to dwell therein forever, that will be the great success.', '(Be mindful of) the day when He will gather you for the Day of Gathering. That will be the Day of loss and gain. Whoever believes in Allah, and does righteously, He will write off his evil deeds, and will admit him to gardens beneath which rivers flow, where they will live forever. That is the great achievement.'),
(5209, 64, 10, 1, 15, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'وَ الَّذِیۡنَ کَفَرُوۡا  وَ کَذَّبُوۡا بِاٰیٰتِنَاۤ اُولٰٓئِکَ اَصۡحٰبُ النَّارِ خٰلِدِیۡنَ فِیۡہَا ؕ وَ  بِئۡسَ الۡمَصِیۡرُ ﴿٪۱۰﴾', 'اور جنہوں نے کفر کیا اور ہماری آیتوں کو جھٹلایا وہی اہل دوزخ ہیں کہ ہمیشہ اس میں رہیں گے اور وہ بری جگہ ہے۔', 'اور جو لوگ منکر ہوئے اور جھٹلائیں انہوں نے ہماری آیتیں وہ لوگ ہیں دوزخ والے رہا کریں اُسی میں اور بری جگہ جا پہنچے', 'But those who disbelieved (in the Oneness of Allah - Islamic Monotheism) and denied Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), they will be the dwellers of the Fire, to dwell therein forever. And worst indeed is that destination.', 'As for those who disbelieve and reject Our signs, they are the people of the Fire. And it is an evil place to return.'),
(5210, 64, 11, 2, 16, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'مَاۤ  اَصَابَ مِنۡ مُّصِیۡبَۃٍ  اِلَّا بِاِذۡنِ اللّٰہِ ؕ وَ  مَنۡ یُّؤۡمِنۡۢ  بِاللّٰہِ  یَہۡدِ  قَلۡبَہٗ ؕ وَ اللّٰہُ  بِکُلِّ  شَیۡءٍ  عَلِیۡمٌ ﴿۱۱﴾', 'کوئی مصیبت نازل نہیں ہوتی مگر اللہ کے حکم سے اور جو شخص اللہ پر ایمان لاتا ہے وہ اسکے دل کو ہدایت دیتا ہے اور اللہ ہر چیز سے باخبر ہے۔', 'نہیں پہنچتی کوئی تکلیف بدون حکم اللہ کے اور جو کوئی یقین لائے اللہ پر وہ راہ بتلائے اسکے دل کو [۱۴] اور اللہ کو ہر چیز معلوم ہے [۱۵]', 'No calamity befalls, but with the Leave (i.e. decision and Qadar (Divine Preordainments)) of Allah, and whosoever believes in Allah, He guides his heart (to the true Faith with certainty, i.e. what has befallen him was already written for him by Allah from the Qadar (Divine Preordainments)), and Allah is the All-Knower of everything.', 'No calamity befalls (one), but with the leave of Allah. And whoever believes in Allah, He guides his heart. Allah is All-Knowing about every thing.'),
(5211, 64, 12, 2, 16, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'وَ اَطِیۡعُوا اللّٰہَ  وَ اَطِیۡعُوا الرَّسُوۡلَ ۚ فَاِنۡ  تَوَلَّیۡتُمۡ  فَاِنَّمَا عَلٰی  رَسُوۡلِنَا الۡبَلٰغُ  الۡمُبِیۡنُ ﴿۱۲﴾', 'اور اللہ کی اطاعت کرو اور اسکے رسول کی اطاعت کرو  پس اگر تم منہ پھیر لوگے تو ہمارے پیغمبر کے ذمے تو صرف پیغام کا کھول کھول کر پہنچا دینا ہے۔', 'اور حکم مانو اللہ کا اور حکم مانو رسول کا پھر اگر تم منہ موڑو تو ہمارے رسول کا تو یہی کام ہے پہنچا دینا کھول کر [۱۶]', 'Obey Allah, and obey the Messenger (Muhammad SAW), but if you turn away, then the duty of Our Messenger is only to convey (the Message) clearly.', 'Obey Allah, and obey the Messenger. But if you turn away, then Our Messenger has only to convey the message clearly.'),
(5212, 64, 13, 2, 16, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'اَللّٰہُ  لَاۤ  اِلٰہَ  اِلَّا ہُوَ ؕ وَ عَلَی اللّٰہِ فَلۡیَتَوَکَّلِ  الۡمُؤۡمِنُوۡنَ ﴿۱۳﴾', 'اللہ جو معبود برحق ہے اسکے سوا کوئی عبادت کے لائق نہیں۔ تو مومنوں کو چاہیے کہ اللہ ہی پر بھروسہ رکھیں۔', 'اللہ اُسکے سوائے کسی کی بندگی نہیں اور اللہ پر چاہئے بھروسہ کریں ایمان والے [۱۷]', 'Allah! La ilaha illa Huwa (none has the right to be worshipped but He), and in Allah (Alone), therefore, let the believers put their trust.', 'Allah is such that there is no god but He. And in Allah alone the believers must place their trust.'),
(5213, 64, 14, 2, 16, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'یٰۤاَیُّہَا  الَّذِیۡنَ  اٰمَنُوۡۤا اِنَّ مِنۡ اَزۡوَاجِکُمۡ وَ اَوۡلَادِکُمۡ عَدُوًّا  لَّکُمۡ فَاحۡذَرُوۡہُمۡ ۚ  وَ  اِنۡ  تَعۡفُوۡا وَ تَصۡفَحُوۡا وَ تَغۡفِرُوۡا  فَاِنَّ اللّٰہَ  غَفُوۡرٌ  رَّحِیۡمٌ ﴿۱۴﴾', 'مومنو! تمہاری  بیویوں اور اولاد میں سے بعض تمہارے دشمن بھی ہیں سو ان سے بچتے رہو اور اگر معاف کر دو اور درگذر کرو اور بخش دو تو اللہ بھی بخشنے والا ہے مہربان ہے۔', 'اے ایمان والو تمہاری بعض جوروئیں اور اولاد دشمن ہیں تمہارے [۱۸] سو اُن سے بچتے رہو اور اگر معاف کرو اور درگزرو اور بخشو تو اللہ ہے بخشنے والا مہربان [۱۹]', 'O you who believe! Verily, among your wives and your children there are enemies for you (i.e. may stop you from the obedience of Allah), therefore beware of them! But if you pardon (them) and overlook, and forgive (their faults), then verily, Allah is Oft-Forgiving, Most Merciful.', 'O you who believe, among your wives and your children there are some enemies for you, so beware of them. And if you forgive and overlook and pardon, then Allah is Most-Forgiving, Very-Merciful.'),
(5214, 64, 15, 2, 16, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'اِنَّمَاۤ  اَمۡوَالُکُمۡ وَ اَوۡلَادُکُمۡ  فِتۡنَۃٌ ؕ وَ اللّٰہُ  عِنۡدَہٗۤ   اَجۡرٌ  عَظِیۡمٌ ﴿۱۵﴾', 'تمہارا مال اور تمہاری اولاد تو آزمائش ہے اور اللہ کے ہاں بڑا اجر ہے۔', 'تمہارے مال اور تمہاری اولاد یہی ہیں جانچنے کو اور اللہ جو ہے اُسکے پاس ہے ثواب بڑا [۲۰]', 'Your wealth and your children are only a trial, whereas Allah! With Him is a great reward (Paradise).', 'Your riches and your children are but a trial. As for Allah, with Him is a great reward.'),
(5215, 64, 16, 2, 16, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'فَاتَّقُوا اللّٰہَ  مَا  اسۡتَطَعۡتُمۡ وَ اسۡمَعُوۡا وَ اَطِیۡعُوۡا وَ اَنۡفِقُوۡا خَیۡرًا  لِّاَنۡفُسِکُمۡ ؕ وَ مَنۡ یُّوۡقَ شُحَّ نَفۡسِہٖ  فَاُولٰٓئِکَ ہُمُ الۡمُفۡلِحُوۡنَ ﴿۱۶﴾', 'سو جہاں تک ہو سکے اللہ سے ڈرو اور اسکے احکام کو سنو اور اسکے فرمانبردار رہو اور اسکی راہ میں خرچ کرو یہ تمہارے حق میں بہتر ہے اور جو شخص طبعیت کے بخل سے بچایا گیا تو ایسے ہی لوگ راہ پانے والے ہیں۔', 'سو  ڈرو اللہ سے جہاں تک ہو سکے اور سنو اور مانو [۲۱] اور خرچ کرو اپنے بھلے کو [۲۲] اور جسکو بچا دیا اپنے جی کے لالچ سے سو وہ لوگ وہی مراد کو پہنچے [۲۳]', 'So keep your duty to Allah and fear Him as much as you can; listen and obey; and spend in charity, that is better for yourselves. And whosoever is saved from his own covetousness, then they are the successful ones.', 'So, observe taqwā (total obedience to Allah in awe of Him) as far as you can, and listen and obey, and spend (in Allah’s way), it being good for you. And those who are saved from the greed of their hearts are the successful.'),
(5216, 64, 17, 2, 16, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'اِنۡ  تُقۡرِضُوا اللّٰہَ  قَرۡضًا حَسَنًا یُّضٰعِفۡہُ لَکُمۡ  وَ یَغۡفِرۡ لَکُمۡ ؕ وَ اللّٰہُ  شَکُوۡرٌ  حَلِیۡمٌ ﴿ۙ۱۷﴾', 'اگر تم اللہ کو نیک نیتی سے قرض دو گے تو وہ تمکو اس کا کئ گنا دے گا اور تمہارے گناہ بھی معاف کر دے گا اور اللہ قدرشناس ہے بردبار ہے۔', 'اگر قرض دو اللہ کو اچھی طرح پر قرض دینا وہ دونا کر دے تم کو اور تم کو بخشے [۲۴] اور اللہ قدردان ہے تحمل والا [۲۵]', 'If you lend to Allah a goodly loan (i.e. spend in Allahs Cause) He will double it for you, and will forgive you. And Allah is Most Ready to appreciate and to reward, Most Forbearing,', 'If you advance a good loan to Allah, He will multiply it for you, and will forgive you. And Allah is Appreciative, Forbearing,'),
(5217, 64, 18, 2, 16, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', ' التّغابن', 'عٰلِمُ  الۡغَیۡبِ وَ الشَّہَادَۃِ  الۡعَزِیۡزُ الۡحَکِیۡمُ ﴿٪۱۸﴾', 'پوشیدہ اور ظاہر کا جاننے والا ہے غالب ہے حکمت والا ہے۔', 'جاننے والا پوشیدہ اور ظاہر کا زبردست حکمت والا [۲۶]', 'All-Knower of the unseen and seen, the All-Mighty, the All-Wise.', 'the Knower of the Unseen and the seen, the All-Mighty, the All-Wise.'),
(5218, 65, 1, 1, 17, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الطّلاق', 'یٰۤاَیُّہَا  النَّبِیُّ  اِذَا طَلَّقۡتُمُ النِّسَآءَ فَطَلِّقُوۡہُنَّ  لِعِدَّتِہِنَّ وَ اَحۡصُوا  الۡعِدَّۃَ ۚ وَ اتَّقُوا اللّٰہَ  رَبَّکُمۡ ۚ لَا تُخۡرِجُوۡہُنَّ مِنۡۢ  بُیُوۡتِہِنَّ وَ لَا یَخۡرُجۡنَ  اِلَّاۤ  اَنۡ یَّاۡتِیۡنَ بِفَاحِشَۃٍ مُّبَیِّنَۃٍ ؕ وَ تِلۡکَ حُدُوۡدُ  اللّٰہِ ؕ وَ مَنۡ یَّتَعَدَّ حُدُوۡدَ  اللّٰہِ  فَقَدۡ ظَلَمَ نَفۡسَہٗ ؕ لَا تَدۡرِیۡ  لَعَلَّ اللّٰہَ  یُحۡدِثُ بَعۡدَ ذٰلِکَ  اَمۡرًا ﴿۱﴾', 'اے پیغمبر ﷺ مسلمانوں سے کہدو کہ جب اپنی بیویوں کو طلاق دینے لگو تو انکی عدت کو پیش نظر رکھ کر طلاق دو اور عدّت کا شمار رکھو اور اللہ سے جو تمہارا پروردگار ہے ڈرو۔ نہ تو تم ہی انکو ایام عدّت میں انکے گھروں سے نکالو اور نہ وہ خود ہی نکلیں۔ ہاں اگر وہ کھلی بے حیائی کریں تو اور بات ہے اور یہ اللہ کی حدیں ہیں اور جو اللہ کی حدوں سے تجاوز کرے گا وہ اپنے آپ پر ظلم کرے گا اے طلاق دینے والے تجھے کیا معلوم شاید اللہ اسکے بعد رجعت کی کوئی سبیل پیدا کر دے۔', 'اے نبی جب تم طلاق دو عورتوں کو تو انکو طلاق دو اُنکی عدت پر [۱] اور گنتے رہو عدت کو  [۲] اور ڈرو اللہ سے جو رب ہے تمہارا مت نکالو اُنکو اُنکے گھروں سے [۳] اور وہ بھی نہ نکلیں مگر جو کریں صریح بے حیائی [۴] اور یہ حدیں ہیں باندھی ہوئی اللہ کی اور جو کوئی بڑھے اللہ کی حدوں سے تو اُس نے برا کیا اپنا [۵] اُسکو خبر نہیں [۶] شاید اللہ پیدا کر دے اُس طلاق کے بعد نئی صورت [۷]', 'O Prophet (SAW)! When you divorce women, divorce them at their Iddah (prescribed periods), and count (accurately) their Iddah (periods ). And fear Allah your Lord (O Muslims), and turn them not out of their (husbands) homes, nor shall they (themselves) leave, except in case they are guilty of some open illegal sexual intercourse. And those are the set limits of Allah. And whosoever transgresses the set limits of Allah, then indeed he has wronged himself. You (the one who divorces his wife) know not, it may be that Allah will afterward bring some new thing to pass (i.e. to return her back to you if that was the first or second divorce).', 'O prophet, when you people divorce women, divorce them at a time when the period of ‘Iddah may start. And count the period of ‘Iddah, and fear Allah, your Lord. Do not expel them from their houses, nor should they go out, unless they come up with a clearly shameless act. These are the limits prescribed by Allah. And whoever exceeds the limits prescribed by Allah wrongs his own self. You do not know (what will happen in future); it may be that Allah brings about a new situation thereafter.'),
(5219, 65, 2, 1, 17, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الطّلاق', 'فَاِذَا  بَلَغۡنَ  اَجَلَہُنَّ  فَاَمۡسِکُوۡہُنَّ بِمَعۡرُوۡفٍ اَوۡ فَارِقُوۡہُنَّ بِمَعۡرُوۡفٍ وَّ اَشۡہِدُوۡا  ذَوَیۡ عَدۡلٍ  مِّنۡکُمۡ وَ اَقِیۡمُوا الشَّہَادَۃَ  لِلّٰہِ ؕ ذٰلِکُمۡ یُوۡعَظُ بِہٖ  مَنۡ کَانَ یُؤۡمِنُ  بِاللّٰہِ  وَ الۡیَوۡمِ الۡاٰخِرِ ۬ؕ وَ  مَنۡ یَّتَّقِ اللّٰہَ  یَجۡعَلۡ لَّہٗ  مَخۡرَجًا ۙ﴿۲﴾', 'پھر جب وہ اپنی معیاد یعنی عدت ختم ہونے کے قریب پہنچ جائیں تو یا تو انکو اچھی طرح سے زوجیت میں رہنے دو یا اچھی طرح سے علیحدہ کر دو۔ اور اپنے میں سے دو منصف مردوں کو گواہ کر لو اور اے گواہو اللہ کے لئے درست گواہی دینا۔ ان باتوں سے اس شخص کو نصیحت کی جاتی ہے۔ جو اللہ پر اور روز آخرت پر ایمان رکھتا ہے اور جو کوئی اللہ سے ڈرے گا۔ وہ اسکے لئے رنج و غم سے نجات کی صورت پیدا کر دے گا۔', 'پھر جب پہنچیں اپنے وعدہ کو تو رکھ لو اُنکو دستور کے موافق یا چھوڑ دو اُنکو دستور کے موافق [۸] اور گواہ کر لو دو معتبر اپنے میں کے [۹] اور سیدھی ادا کرو گواہی اللہ کے واسطے [۱۰] یہ بات جو ہے اس سے سمجھ جائے گا جو کوئی یقین رکھتا ہو گا اللہ پر اور پچھلے دن پر [۱۱] اور جو کوئی ڈرتا ہے اللہ سے وہ کر دے اُس کا گذارہ [۱۲]', 'Then when they are about to fulfil their term appointed, either take them back in a good manner or part with them in a good manner. And take for witness two just persons from among you (Muslims). And establish the witness for Allah. That will be an admonition given to him who believes in Allah and the Last Day. And whosoever fears Allah and keeps his duty to Him, He will make a way for him to get out (from every difficulty).', 'So, when they (the divorced women) have (almost) reached their term, then either retain them with fairness, or part with them with fairness. And make two just men from among you witnesses (of your either decision). And (O witnesses,) keep your testimony upright for the sake of Allah. That is what anyone who believes in Allah and the Last Day is exhorted to do. Whoever fears Allah, He brings forth a way out for him,'),
(5220, 65, 3, 1, 17, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الطّلاق', 'وَّ یَرۡزُقۡہُ  مِنۡ حَیۡثُ لَا یَحۡتَسِبُ ؕ وَ مَنۡ  یَّتَوَکَّلۡ عَلَی اللّٰہِ  فَہُوَ حَسۡبُہٗ ؕ اِنَّ اللّٰہَ  بَالِغُ  اَمۡرِہٖ ؕ قَدۡ جَعَلَ اللّٰہُ  لِکُلِّ شَیۡءٍ  قَدۡرًا ﴿۳﴾', 'اور اسکو ایسی جگہ سے رزق دے گا جہاں سے اسکو وہم و گمان بھی نہ ہو۔ اور جو اللہ پر بھروسہ رکھے گا تو وہ اسکے لئے کافی ہو گا۔ اللہ اپنے کام کو جو وہ کرنا چاہتا ہے پورا کر دیتا ہے۔ اللہ نے ہر چیز کا اندازہ مقرر کر رکھا ہے۔', 'اور روزی دے اُسکو جہاں سے اُسکو خیال بھی نہ ہو [۱۳] اور جو کوئی بھروسہ رکھے اللہ پر تو وہ اُسکو کافی ہے تحقیق اللہ پورا کر لیتا ہے اپنا کام اللہ نےرکھا ہے ہر چیز کا اندازہ [۱۴]', 'And He will provide him from (sources) he never could imagine. And whosoever puts his trust in Allah, then He will suffice him. Verily, Allah will accomplish his purpose. Indeed Allah has set a measure for all things.', 'and provides him (with what he needs) from where he does not even imagine. And whoever places his trust in Allah, He is sufficient for him. Surely Allah is to accomplish His purpose. Allah has set a measure for every thing.'),
(5221, 65, 4, 1, 17, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الطّلاق', 'وَ الِّٰٓیۡٔ  یَئِسۡنَ مِنَ  الۡمَحِیۡضِ مِنۡ نِّسَآئِکُمۡ   اِنِ  ارۡتَبۡتُمۡ فَعِدَّتُہُنَّ  ثَلٰثَۃُ اَشۡہُرٍ ۙ وَّ الِّٰٓیۡٔ  لَمۡ یَحِضۡنَ ؕ وَ اُولَاتُ الۡاَحۡمَالِ  اَجَلُہُنَّ اَنۡ یَّضَعۡنَ حَمۡلَہُنَّ ؕ  وَ مَنۡ یَّتَّقِ اللّٰہَ  یَجۡعَلۡ لَّہٗ  مِنۡ  اَمۡرِہٖ یُسۡرًا ﴿۴﴾', 'اور تمہاری طلاق والی بیویاں جو حیض سے ناامید ہو چکی ہوں اگر تمکو انکی عدّت کے بارے میں شبہ ہو تو انکی عدّت تین مہینے ہے اور جنکو ابھی حیض نہیں آنے لگا انکی عدّت بھی یہی ہے اور حمل والی عورتوں کی عدّت وضع حمل یعنی بچہ جننے تک ہے۔ اور جو اللہ سے ڈرے گا اللہ اسکے کام میں سہولت پیدا کر دے گا۔', 'اور جو عورتیں ناامید ہو گئیں حیض سے تمہاری عورتوں میں اگر تم کو شبہ رہ گیا تو اُنکی عدت ہے تین مہینے اور ایسے ہی جن کو حیض نہیں آیا [۱۵] اور جن کے پیٹ میں بچہ ہے اُنکی عدت یہ کہ جن لیں پیٹ کا بچہ [۱۶] اور جو کوئی ڈرتا رہے اللہ سے کر دے وہ اُس کے کام میں آسانی', 'And those of your women as have passed the age of monthly courses, for them the Iddah (prescribed period), if you have doubts (about their periods), is three months, and for those who have no courses ((i.e. they are still immature) their Iddah (prescribed period) is three months likewise, except in case of death) . And for those who are pregnant (whether they are divorced or their husbands are dead), their Iddah (prescribed period) is until they deliver (their burdens), and whosoever fears Allah and keeps his duty to Him, He will make his matter easy for him.', 'And those women from among you who have despaired of (further) menstruation, if you are in doubt, their ‘Iddah is three months, as well as of those who have not yet menstruated. As for those having pregnancy, their term (of ‘Iddah ) is that they give birth to their child. And whoever fears Allah, He brings about ease for him in his affair.'),
(5222, 65, 5, 1, 17, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الطّلاق', 'ذٰلِکَ  اَمۡرُ اللّٰہِ  اَنۡزَلَہٗۤ  اِلَیۡکُمۡ ؕ وَ مَنۡ یَّتَّقِ اللّٰہَ یُکَفِّرۡ عَنۡہُ سَیِّاٰتِہٖ وَ یُعۡظِمۡ لَہٗۤ  اَجۡرًا ﴿۵﴾', 'یہ اللہ کا حکم ہے جو اس نے تم پر نازل کیا ہے اور جو اللہ سے ڈرے گا وہ اس سے اس کے گناہ دور کر دے گا اور اسے اجر عظیم بخشے گا۔', 'یہ حکم ہے اللہ کا جو اتارا تمہاری طرف اور جو کوئی ڈرتا رہے اللہ سے اتار دے اس پر سے اسکی برائیاں اور  بڑا دے اُسکو ثواب [۱۷]', 'That is the Command of Allah, which He has sent down to you, and whosoever fears Allah and keeps his duty to Him, He will remit his sins from him, and will enlarge his reward.', 'This is the command of Allah that He has sent down to you. And whoever fears Allah, He will write off his evil deeds, and will give him a huge reward.'),
(5223, 65, 6, 1, 17, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الطّلاق', 'اَسۡکِنُوۡہُنَّ  مِنۡ حَیۡثُ سَکَنۡتُمۡ مِّنۡ وُّجۡدِکُمۡ وَ لَا  تُضَآرُّوۡہُنَّ  لِتُضَیِّقُوۡا عَلَیۡہِنَّ ؕ وَ اِنۡ کُنَّ  اُولَاتِ حَمۡلٍ فَاَنۡفِقُوۡا عَلَیۡہِنَّ حَتّٰی یَضَعۡنَ حَمۡلَہُنَّ ۚ  فَاِنۡ  اَرۡضَعۡنَ لَکُمۡ  فَاٰتُوۡہُنَّ  اُجُوۡرَہُنَّ ۚ وَ اۡتَمِرُوۡا  بَیۡنَکُمۡ بِمَعۡرُوۡفٍ ۚ وَ اِنۡ  تَعَاسَرۡتُمۡ فَسَتُرۡضِعُ  لَہٗۤ   اُخۡرٰی  ؕ﴿۶﴾', 'طلاق والی عورتوں کو ایام عدّت میں اپنی حیثیت کے مطابق وہیں رکھو جہاں خود رہتے ہو اور انکو تنگ کرنے کے لئے تکلیف نہ دو۔ اور اگر وہ حمل سے ہوں تو بچہ پیدا ہونے تک ان کا خرچ دیتے رہو۔ پھر اگر وہ بچے کو تمہارے کہنے سے دودھ پلائیں تو انکو ان کی اجرت دیدو اور بچے کے بارے میں پسندیدہ طریق سے موافقت رکھو اور اگر باہم ضد اور نااتفاقی کرو گے تو بچے کو اسکے باپ کے کہنے سے کوئی اور عورت دودھ پلائے گی۔', 'اُنکو گھر دو رہنے کے واسطے جہاں تم آپ رہو اپنے مقدور کے موافق [۱۸] اور ایذا دینا نہ چاہو اُنکو تاکہ تنگ پکڑو اُنکو [۱۹] اور اگر رکھتی ہوں پیٹ میں بچہ تو اُن پر خرچ کرو جب تک جنیں پیٹ کا بچہ [۲۰] پھر اگر وہ دودھ پلائیں تمہاری خاطر تو دو اُنکو اُن کا بدلا اور سکھاؤ آپس میں نیکی [۲۱] اور اگر ضد کرو آپس میں تو دودھ پلائے گی اُسکی خاطر اور کوئی عورت [۲۲]', 'Lodge them (the divorced women) where you dwell, according to your means, and do not treat them in such a harmful way that they be obliged to leave. And if they are pregnant, then spend on them till they deliver. Then if they give suck to the children for you, give them their due payment, and let each of you accept the advice of the other in a just way. But if you make difficulties for one another, then some other woman may give suck for him (the father of the child).', 'Provide to them (the divorced women) residence where you reside according to your means, and do not hurt them to straiten (life) for them. And if they are pregnant, spend on them till they give birth to their child. Then if they suckle the child for you, give them their fees, and consult each other (for determining the fee) with fairness, and if you create a deadlock between you, then another woman will suckle him.'),
(5224, 65, 7, 1, 17, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الطّلاق', 'لِیُنۡفِقۡ  ذُوۡ سَعَۃٍ  مِّنۡ سَعَتِہٖ ؕ وَ مَنۡ قُدِرَ عَلَیۡہِ  رِزۡقُہٗ  فَلۡیُنۡفِقۡ مِمَّاۤ  اٰتٰىہُ اللّٰہُ ؕ لَا یُکَلِّفُ اللّٰہُ  نَفۡسًا اِلَّا مَاۤ  اٰتٰىہَا ؕ سَیَجۡعَلُ اللّٰہُ  بَعۡدَ عُسۡرٍ  یُّسۡرًا ٪﴿۷﴾', 'صاحب وسعت کو اپنی وسعت کے مطابق خرچ کرنا چاہیے اور جس کے رزق میں تنگی ہو جتنا اللہ نے اسکو دیا ہے وہ اسکے موافق خرچ کرے۔ اللہ کسی کو زیربار نہیں کرتا مگر اسی کے لحاظ سے جتنا اسکو دیا ہے اور اللہ عنقریب تنگی کے بعد آسانی کر دے گا۔', 'چاہیے خرچ کرے وسعت والا اپنی وسعت کے موافق اور جسکو نپی تلی ملتی ہے اُسکی روزی تو خرچ کرے جیسا کہ دیا ہے اُسکو اللہ نے اللہ کسی پر تکلیف نہیں رکھتا مگر اُسی قدر جو  اُسکو دیا اب کر دے گا اللہ سختی کے پیچھے کچھ آسانی [۲۳]', 'Let the rich man spend according to his means, and the man whose resources are restricted, let him spend according to what Allah has given him. Allah puts no burden on any person beyond what He has given him. Allah will grant after hardship, ease.', 'A man of vast means should spend according to his vast means. And anyone whose sustenance is limited should spend from whatever Allah has given to him. Allah makes no one liable beyond what He has given to him. Allah will soon bring ease after a difficulty.'),
(5225, 65, 8, 2, 18, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الطّلاق', 'وَ کَاَیِّنۡ  مِّنۡ  قَرۡیَۃٍ  عَتَتۡ عَنۡ اَمۡرِ رَبِّہَا وَ رُسُلِہٖ  فَحَاسَبۡنٰہَا حِسَابًا شَدِیۡدًا ۙ وَّ عَذَّبۡنٰہَا عَذَابًا  نُّکۡرًا ﴿۸﴾', 'اور بہت سی بستیوں کے رہنے والوں نے اپنے پروردگار اور اسکے پیغمبروں کے احکام سے سرکشی کی تو ہم نے انکو سخت حساب میں پکڑ لیا اور ان پر ایسا عذاب نازل کیا جو نہ دیکھا تھا نہ سنا۔', 'اور کتنی بستیاں کہ نکل چلیں حکم سے اپنے رب کے اور اُسکے رسولوں کے پھر ہم نے حساب میں پکڑا اُنکو سخت حساب میں اور آفت ڈالی اُن پر بن دیکھی آفت [۲۴]', 'And many a town (population) revolted against the Command of its Lord and His Messengers, and We called it to a severe account (i.e. torment in this worldly life), and shall punish it with a horrible torment (in Hell, in the Hereafter).', 'And how many a township rebelled against the command of its Lord, and against His messengers, so We called them to a severe account, and punished them with a punishment that was unimagined by them.'),
(5226, 65, 9, 2, 18, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الطّلاق', 'فَذَاقَتۡ وَبَالَ  اَمۡرِہَا وَ کَانَ عَاقِبَۃُ اَمۡرِہَا خُسۡرًا ﴿۹﴾', 'سو انہوں نے اپنے کاموں کی سزا کا مزا چکھ لیا اور ان کا انجام نقصان ہی تو تھا۔', 'پھر چکھی انہوں نے سزا اپنے کام کی اور آخر کو اُنکے کام میں ٹوٹا آ گیا [۲۵]', 'So it tasted the evil result of its disbelief, and the consequence of its disbelief was loss (destruction in this life and an eternal punishment in the Hereafter).', 'Thus they tasted the evil consequence of their acts, and the end of their conduct was loss.'),
(5227, 65, 10, 2, 18, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الطّلاق', 'اَعَدَّ اللّٰہُ  لَہُمۡ عَذَابًا شَدِیۡدًا ۙ فَاتَّقُوا اللّٰہَ  یٰۤاُولِی  الۡاَلۡبَابِ ۬ۚۖۛ الَّذِیۡنَ اٰمَنُوۡا ؕ۟ۛ قَدۡ  اَنۡزَلَ  اللّٰہُ  اِلَیۡکُمۡ   ذِکۡرًا ﴿ۙ۱۰﴾', 'اللہ نے انکے لئے سخت عذاب تیار کر رکھا ہے۔ تو اے عقل والو جو ایمان لائے ہو اللہ سے ڈرو۔ اللہ نے تمہارے پاس نصیحت بھیج دی ہے۔', 'تیار رکھا ہے اللہ نے واسطے اُنکے سخت عذاب [۲۶] سو ڈرتے رہو اللہ سے اے عقل والو جنکو یقین ہے [۲۷] بیشک اللہ نے اتاری ہے تم پر نصیحت [۲۸]', 'Allah has prepared for them a severe torment. So fear Allah and keep your duty to Him, O men of understanding who have believed! - Allah has indeed sent down to you a Reminder (this Quran).', 'Allah has prepared for them a severe punishment; so fear Allah O men of understanding who have believed! Allah has sent down to you a Reminder,'),
(5228, 65, 11, 2, 18, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الطّلاق', 'رَّسُوۡلًا یَّتۡلُوۡا  عَلَیۡکُمۡ  اٰیٰتِ اللّٰہِ مُبَیِّنٰتٍ لِّیُخۡرِجَ  الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ مِنَ الظُّلُمٰتِ  اِلَی النُّوۡرِ ؕ وَ مَنۡ یُّؤۡمِنۡۢ  بِاللّٰہِ وَ یَعۡمَلۡ صَالِحًا یُّدۡخِلۡہُ  جَنّٰتٍ تَجۡرِیۡ  مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَاۤ  اَبَدًا ؕ قَدۡ اَحۡسَنَ اللّٰہُ  لَہٗ  رِزۡقًا ﴿۱۱﴾', 'یعنی ایسے پیغمبر جو تمہارے سامنے اللہ کی واضح آیتیں پڑھتے ہیں تاکہ جو لوگ ایمان لائے اور عمل نیک کرتے رہے ہیں انکو اندھیروں سے نکال کر روشنی میں لے آئیں۔ اور جو جو اللہ پر ایمان لائے گا اور عمل نیک کرے گا وہ انکو جنتوں میں داخل کرے گا جنکے نیچے نہریں بہ رہی ہیں وہ ہمیشہ ہمیشہ ان میں رہیں گے۔ اللہ نے انکے لئے کیا خوب رزق رکھا ہے۔', 'رسول ہے جو پڑھ کر سناتا ہے تم کو اللہ کی آیتیں کھول کر سنانے والی [۲۹] تاکہ نکالے اُن لوگوں کو جو کہ یقین لائے اور کئے بھلے کام اندھیروں سے اجالے میں [۳۰] اور جو کوئی یقین لائے اللہ پر اورکرے کچھ بھلائی اُسکو داخل کرے باغوں میں نیچے بہتی ہیں جنکے نہریں سدا رہیں اُن میں ہمیشہ البتہ خوب دی اللہ نے اُسکو روزی [۳۱]', '(And has also sent to you) a Messenger (Muhammad SAW), who recites to you the Verses of Allah (the Quran) containing clear explanations, that He may take out, those who believe and do righteous good deeds from the darkness (of polytheism and disbelief) to the light (of Monotheism and true Faith). And whosoever believes in Allah and performs righteous good deeds, He will admit him into Gardens under which rivers flow (Paradise), to dwell therein forever. Allah has indeed granted for him an excellent provision.', 'a messenger who recites to you the verses of Allah, making (the truth) clear, so that He may bring forth those who believe and do righteous deeds from the layers of darkness into the light. And whoever believes in Allah, and acts righteously, He will admit him to the gardens beneath which rivers flow, wherein such people will live forever. Allah has made for him a good provision.'),
(5229, 65, 12, 2, 18, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'الطّلاق', 'اَللّٰہُ  الَّذِیۡ خَلَقَ سَبۡعَ  سَمٰوٰتٍ وَّ مِنَ الۡاَرۡضِ مِثۡلَہُنَّ ؕ یَتَنَزَّلُ  الۡاَمۡرُ بَیۡنَہُنَّ لِتَعۡلَمُوۡۤا اَنَّ اللّٰہَ عَلٰی کُلِّ شَیۡءٍ قَدِیۡرٌ ۬ۙ وَّ اَنَّ اللّٰہَ  قَدۡ اَحَاطَ بِکُلِّ شَیۡءٍ عِلۡمًا  ﴿٪۱۲﴾', 'اللہ ہی تو ہے جس نے سات آسمان پیدا کئے اور ویسی ہی زمینیں بھی۔ ان میں اللہ کا حکم اترتا رہتا ہے تاکہ تم لوگ جان لو کہ اللہ ہر چیز پر قادر ہے۔ اور یہ کہ اللہ اپنے علم سے ہر چیز کا احاطہ کئے ہوئے ہے۔', 'اللہ وہی ہے جس نے بنائے سات آسمان اور زمین بھی اتنی  ہی [۳۲] اترتا ہے اُس کا کا حکم اُنکے اندر [۳۳] تاکہ تم جانو کہ اللہ ہر چیز کر سکتا ہے  اور اللہ کے علم میں سمائی ہے ہر چیز  کی [۳۴]', 'It is Allah Who has created seven heavens and of the earth the like thereof (i.e. seven). His Command descends between them (heavens and earth), that you may know that Allah has power over all things, and that Allah surrounds (comprehends) all things in (His) Knowledge.', 'Allah is the One who has created seven skies, and their like from earth. The Command descends among them, so that you may know that Allah is powerful over every thing, and that Allah has encompassed every thing in knowledge.'),
(5230, 66, 1, 1, 19, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'التحریم', 'یٰۤاَیُّہَا النَّبِیُّ  لِمَ  تُحَرِّمُ مَاۤ  اَحَلَّ اللّٰہُ  لَکَ ۚ تَبۡتَغِیۡ  مَرۡضَاتَ  اَزۡوَاجِکَ ؕ وَ اللّٰہُ  غَفُوۡرٌ  رَّحِیۡمٌ ﴿۱﴾', 'اے پیغمبر ﷺ جو چیز اللہ نے تمہارے لئے جائز کی ہے تم اس سے کنارہ کشی کیوں کرتے ہو؟ کیا اس سے اپنی بیویوں کی خوشنودی چاہتے ہو؟ اور اللہ بخشنے والا ہے مہربان ہے۔', '[۱] اے نبی تو کیوں حرام کرتا ہے جو حلال کیا اللہ نے تجھ پر چاہتا ہے تو رضامندی اپنی عورتوں کی [۲] اور اللہ بخشنے والا ہے مہربان [۳]', 'O Prophet! Why do you ban (for yourself) that which Allah has made lawful to you, seeking to please your wives? And Allah is Oft-Forgiving, Most Merciful.', 'O Prophet, why do you ban (on your self) something that Allah has made lawful for you, seeking to please your wives? And Allah is Most-Forgiving, Very-Merciful.'),
(5231, 66, 2, 1, 19, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'التحریم', 'قَدۡ  فَرَضَ اللّٰہُ  لَکُمۡ تَحِلَّۃَ  اَیۡمَانِکُمۡ ۚ وَ اللّٰہُ  مَوۡلٰىکُمۡ ۚ وَ ہُوَ الۡعَلِیۡمُ  الۡحَکِیۡمُ ﴿۲﴾', 'اللہ نے تم لوگوں کے لئے تمہاری قسموں کا کفارہ مقرر کر دیا ہے اور اللہ ہی تمہارا کارساز ہے۔ اور وہ دانا ہے حکمت والا ہے۔', 'مقرر کر دیا ہے اللہ نے تمہارے لئے کھول ڈالنا تمہاری قسموں کا اور اللہ مالک ہے تمہارا اور وہی ہے سب کچھ جانتا حکمت والا [۴]', 'Allah has already ordained for you (O men), the dissolution of your oaths. And Allah is your Maula (Lord, or Master, or Protector, etc.) and He is the All-Knower, the All-Wise.', 'Allah has prescribed (the way of) absolution from your oaths. And Allah is your protector, and He is the All- Knowing, the All-Wise.'),
(5232, 66, 3, 1, 19, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'التحریم', 'وَ اِذۡ  اَسَرَّ النَّبِیُّ  اِلٰی  بَعۡضِ  اَزۡوَاجِہٖ حَدِیۡثًا ۚ فَلَمَّا نَبَّاَتۡ بِہٖ وَ اَظۡہَرَہُ  اللّٰہُ عَلَیۡہِ  عَرَّفَ بَعۡضَہٗ  وَ اَعۡرَضَ عَنۡۢ بَعۡضٍ ۚ فَلَمَّا نَبَّاَہَا بِہٖ  قَالَتۡ مَنۡ اَنۡۢبَاَکَ ہٰذَا ؕ قَالَ  نَبَّاَنِیَ الۡعَلِیۡمُ الۡخَبِیۡرُ ﴿۳﴾', 'اور یاد کرو جب پیغمبر ﷺ نے اپنی ایک بیوی سے ایک بھید کی بات کہی۔ تو اس نے دوسری کو بتا دی پھر جب اس نے اسکو ظاہر کر دیا اور اللہ نے اس حال سے پیغمبر ﷺ کو آگاہ کر دیا تو پیغمبر ﷺ نے ان بیوی کو وہ بات کچھ تو جتائی اور کچھ نہ بتائی سو جب وہ انکو بتائی تو وہ پوچھنے لگیں کہ آپ کو یہ کس نے بتایا؟ فرمایا کہ مجھے اس نے بتایا ہے جو سب کچھ جاننے والا ہے خبردار ہے۔', 'اور جب چھپا کر کہی نبی نے اپنی کسی عورت سے ایک بات پھر جب اُس نے خبر کر دی اُسکی اور اللہ نے جتلا دی نبی کو وہ بات تو جتلائی نبی نے اُس میں سےکچھ اور ٹلا دی کچھ پھر جب وہ جتلائی عورت کو بولی تجھ کو کس نے بتلا دی یہ کہا مجھ کو بتایا اُس خبر والے واقف نے [۵]', 'And (remember) when the Prophet (SAW) disclosed a matter in confidence to one of his wives (Hafsah), so when she told it (to another i.e. Aishah), and Allah made it known to him, he informed part thereof and left a part. Then when he told her (Hafsah) thereof, she said: \"Who told you this?\" He said: \"The All-Knower, the All-Aware (Allah) has told me\".', 'And (remember) when the Prophet told one of his wives something in secret. So, when she disclosed it (to another wife), and Allah made it known to him, he told (the disclosing wife) part of it,and avoided another part. So when he informed her about it, she said, “Who told you about this?” He said, “I was told of it by the All-Knowing, the All-Aware.'),
(5233, 66, 4, 1, 19, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'التحریم', 'اِنۡ تَتُوۡبَاۤ  اِلَی اللّٰہِ  فَقَدۡ صَغَتۡ قُلُوۡبُکُمَا ۚ وَ اِنۡ  تَظٰہَرَا عَلَیۡہِ  فَاِنَّ اللّٰہَ  ہُوَ مَوۡلٰىہُ  وَ جِبۡرِیۡلُ وَ صَالِحُ الۡمُؤۡمِنِیۡنَ ۚ وَ الۡمَلٰٓئِکَۃُ  بَعۡدَ  ذٰلِکَ ظَہِیۡرٌ ﴿۴﴾', 'اگر تم دونوں اللہ کے آگے توبہ کرو تو بہتر ہے کیونکہ تمہارے دل مائل ہو ہی گئے ہیں۔ اور اگر پیغمبر ﷺ کیخلاف باہم اعانت کرو گی تو اللہ اور جبریل اور نیک کردار مسلمان انکے حامی اور دوستدار ہیں اور انکے علاوہ سب فرشتے بھی مددگار ہیں۔', 'اگر تم دونوں توبہ کرتی ہو تو جھک پڑے ہیں دل تمہارے [۶] اور اگر تم دونوں چڑھائی کرو گی اُس پر تو اللہ ہے اُس کا رفیق اور جبرئیل اور نیک بخت ایمان والے اور فرشتے اسکے پیچھے مددگار ہیں [۷]', 'If you two (wives of the Prophet SAW, namely Aishah and Hafsah ÑÖì ) turn in repentance to Allah, (it will be better for you), your hearts are indeed so inclined (to oppose what the Prophet SAW likes), but if you help one another against him (Muhammad SAW), then verily, Allah is his Maula (Lord, or Master, or Protector, etc.), and Jibrael (Gabriel), and the righteous among the believers, and furthermore, the angels are his helpers.', '(O two wives of the Prophet,) If both of you repent to Allah, then (your conduct calls for it, because) your hearts have departed from the correct way. And if you back each other against him (the Prophet), then Allah is his supporter, and Jibra’īl (Gabriel) and righteous believers, and after all that, angels are his helpers.'),
(5234, 66, 5, 1, 19, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'التحریم', 'عَسٰی رَبُّہٗۤ  اِنۡ  طَلَّقَکُنَّ  اَنۡ  یُّبۡدِلَہٗۤ اَزۡوَاجًا  خَیۡرًا مِّنۡکُنَّ  مُسۡلِمٰتٍ مُّؤۡمِنٰتٍ قٰنِتٰتٍ تٰٓئِبٰتٍ عٰبِدٰتٍ سٰٓئِحٰتٍ ثَیِّبٰتٍ وَّ  اَبۡکَارًا ﴿۵﴾', 'اے ازواج نبی اگر پیغمبر ﷺ تمکو طلاق دے دیں  تو عجب نہیں کہ انکا پروردگار تمہارے بدلے انکو تم سے بہتر بیویاں دیدے۔ مسلمان ایمان والیاں فرمانبردار توبہ کرنے والیاں  عبادت گذار روزہ رکھنے والیاں شادی شدہ اور کنواریاں۔', 'اگر نبی چھوڑ دے تم سب کو ابھی اُس کا رب بدلے میں دیدے اُسکو عورتیں تم سے بہتر حکم بردار یقین رکھنے والیاں نماز میں کھڑی ہونے والیاں توبہ کرنے والیاں بندگی بجا لانے والیاں روزہ رکھنے والیاں بیاہیاں اور کنواریاں [۸]', 'It may be if he divorced you (all) that his Lord will give him instead of you, wives better than you, Muslims (who submit to Allah), believers, obedient to Allah, turning to Allah in repentance, worshipping Allah sincerely, fasting or emigrants (for Allahs sake), previously married and virgins.', 'It is hoped that, if he divorces you, Allah will give him in your place wives better than you, submissive to Allah, believing, devout, penitent, steadfast in worship, fasting, previously married and virgins.'),
(5235, 66, 6, 1, 19, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'التحریم', 'یٰۤاَیُّہَا  الَّذِیۡنَ  اٰمَنُوۡا قُوۡۤا  اَنۡفُسَکُمۡ  وَ اَہۡلِیۡکُمۡ  نَارًا وَّ قُوۡدُہَا  النَّاسُ وَ الۡحِجَارَۃُ  عَلَیۡہَا مَلٰٓئِکَۃٌ  غِلَاظٌ شِدَادٌ لَّا یَعۡصُوۡنَ اللّٰہَ مَاۤ  اَمَرَہُمۡ وَ یَفۡعَلُوۡنَ مَا  یُؤۡمَرُوۡنَ ﴿۶﴾', 'مومنو! اپنے آپکو اور اپنے اہل و عیال کو اس آگ سے بچاؤ جس کا ایندھن آدمی اور پتھر ہونگے اور جس پر تندخو اور سخت گیر فرشتے مقرر ہیں وہ کسی حکم کی جو اللہ انکو دیتا ہے نافرمانی نہیں کرتے اور جو حکم انکو ملتا ہے اسے بجا لاتے ہیں۔', 'اے ایمان والو بچاؤ اپنی جان کو اور اپنے گھر والوں کو اُس آگ سے جسکی چھپٹیاں ہیں آدمی اور پتھر [۹] اُس پر مقرر ہیں فرشتے تندخو زبردست  [۱۰] نافرمانی نہیں کرتے اللہ کی جو بات فرمائے اُنکو اور وہی کام کرتے ہیں جو اُنکو حکم ہو [۱۱]', 'O you who believe! Ward off from yourselves and your families a Fire (Hell) whose fuel is men and stones, over which are (appointed) angels stern (and) severe, who disobey not, (from executing) the Commands they receive from Allah, but do that which they are commanded.', 'O you who believe, save yourselves and your families from a fire, the fuel of which is human beings and stones, appointed on which are angels, stern and severe, who do not disobey Allah in what He orders them, and do whatever they are ordered to do.'),
(5236, 66, 7, 1, 19, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'التحریم', 'یٰۤاَیُّہَا  الَّذِیۡنَ کَفَرُوۡا  لَا تَعۡتَذِرُوا الۡیَوۡمَ ؕ اِنَّمَا  تُجۡزَوۡنَ مَا کُنۡتُمۡ تَعۡمَلُوۡنَ ٪﴿۷﴾', 'کافرو! آج بہانے مت بناؤ۔ جو عمل تم کیا کرتے تھے انہی کا تمکو بدلہ دیا جائے گا۔', 'اے منکر ہونے والو مت بہانے بتلاؤ آج کے دن وہی بدلا پاؤ گے جو تم کرتے تھے [۱۲]', '(It will be said in the Hereafter) O you who disbelieve (in the Oneness of Allah - Islamic Monotheism)! Make no excuses this Day! You are being requited only for what you used to do .', 'O you who disbelieve, do not make excuses today. You will only be recompensed for what you have been doing.'),
(5237, 66, 8, 2, 20, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'التحریم', 'یٰۤاَیُّہَا  الَّذِیۡنَ  اٰمَنُوۡا تُوۡبُوۡۤا  اِلَی اللّٰہِ تَوۡبَۃً  نَّصُوۡحًا ؕ عَسٰی رَبُّکُمۡ  اَنۡ یُّکَفِّرَ عَنۡکُمۡ سَیِّاٰتِکُمۡ وَ یُدۡخِلَکُمۡ جَنّٰتٍ تَجۡرِیۡ  مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ ۙ یَوۡمَ لَا یُخۡزِی اللّٰہُ  النَّبِیَّ  وَ الَّذِیۡنَ اٰمَنُوۡا مَعَہٗ ۚ  نُوۡرُہُمۡ  یَسۡعٰی بَیۡنَ اَیۡدِیۡہِمۡ وَ بِاَیۡمَانِہِمۡ  یَقُوۡلُوۡنَ  رَبَّنَاۤ اَتۡمِمۡ  لَنَا نُوۡرَنَا وَ اغۡفِرۡ لَنَا ۚ اِنَّکَ عَلٰی کُلِّ شَیۡءٍ قَدِیۡرٌ ﴿۸﴾', 'مومنو! اللہ کے آگے صاف دل سے توبہ کرو امید ہے کہ وہ تمہارے گناہ تم سے دور کر دے گا اور تمکو جنتوں میں جنکے نیچے نہریں بہ رہی ہیں داخل کرے گا اس دن اللہ پیغمبر ﷺ کو اور ان لوگوں کو جو ان کے ساتھ ایمان لائے ہیں رسوا نہیں کرے گا۔ بلکہ ان کا نور ایمان انکے آگے اور داہنی طرف روشنی کرتا ہوا چل رہا ہو گا اور وہ اللہ سے التجا کریں گے کہ اے پروردگار ہمارا نور ہمارے لئے پورا کر اور ہمیں معاف فرما۔ بیشک اللہ ہر چیز پر قادر ہے۔', 'اے ایمان والو توبہ کرو اللہ کی طرف صاف دل کی توبہ [۱۳] امید ہے تمہارا رب اتار دے تم پر سے تمہاری برائیاں اور  داخل کرے تم کو باغوں میں جنکے نیچے بہتی ہیں نہریں جس دن کہ اللہ ذلیل نہ کرے گا نبی کو اور اُن لوگوں کو جو یقین لاتے ہیں اُسکے ساتھ [۱۴] اُنکی روشنی دوڑتی ہے اُنکے آگے اور اُنکے داہنے [۱۵] کہتے ہیں اے رب ہمارے پوری کر دے ہماری روشنی اور معاف کر ہم کو بیشک تو سب کچھ کر سکتا ہے [۱۶]', 'O you who believe! Turn to Allah with sincere repentance! It may be that your Lord will remit from you your sins, and admit you into Gardens under which rivers flow (Paradise) the Day that Allah will not disgrace the Prophet (Muhammad SAW) and those who believe with him, their Light will run forward before them and with (their Records Books of deeds) in their right hands they will say: \"Our Lord! Keep perfect our Light for us (and do not put it off till we cross over the Sirat (a slippery bridge over the Hell) safely) and grant us forgiveness. Verily, You are Able to do all things .\"', 'O you who believe, turn to Allah with a faithful repentance. It is hoped from your Lord that he will write off your faults, and will admit you to the gardens beneath which rivers flow, on the Day when Allah will not disgrace the Prophet and those who believed with him. Their light will run before them and to their right hands. They will say, “Our Lord, perfect for us our light, and forgive us. Indeed you are powerful over every thing.”'),
(5238, 66, 9, 2, 20, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'التحریم', 'یٰۤاَیُّہَا  النَّبِیُّ  جَاہِدِ الۡکُفَّارَ وَ الۡمُنٰفِقِیۡنَ وَ اغۡلُظۡ عَلَیۡہِمۡ ؕ وَ مَاۡوٰىہُمۡ  جَہَنَّمُ ؕ وَ  بِئۡسَ  الۡمَصِیۡرُ ﴿۹﴾', 'اے پیغمبر ﷺ کافروں اور منافقوں سے جہاد کرو اور ان پر سختی کرو۔ اور ان کا ٹھکانہ دوزخ ہے۔ اور وہ بہت بری جگہ ہے۔', 'اے نبی لڑائی کر منکروں سے اور دغابازوں سے اور سختی کر اُن پر [۱۷] اور اُن کا گھر دوزخ ہے اور بری جگہ جا پہنچے [۱۸]', 'O Prophet (Muhammad SAW)! Strive hard against the disbelievers and the hypocrites, and be severe against them, their abode will be Hell, and worst indeed is that destination.', 'O Prophet, carry out Jihād (struggle) against the disbelievers and the hypocrites, and be harsh with them. Their final abode is Jahannam (Hell), and it is an evil end.'),
(5239, 66, 10, 2, 20, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'التحریم', 'ضَرَبَ اللّٰہُ  مَثَلًا  لِّلَّذِیۡنَ  کَفَرُوا امۡرَاَتَ  نُوۡحٍ وَّ امۡرَاَتَ  لُوۡطٍ ؕ کَانَتَا تَحۡتَ عَبۡدَیۡنِ مِنۡ عِبَادِنَا صَالِحَیۡنِ فَخَانَتٰہُمَا فَلَمۡ یُغۡنِیَا عَنۡہُمَا مِنَ اللّٰہِ شَیۡئًا وَّ قِیۡلَ ادۡخُلَا  النَّارَ مَعَ الدّٰخِلِیۡنَ ﴿۱۰﴾', 'اللہ نے کافروں کے لئے نوح کی بیوی اور لوط کی بیوی کی مثال بیان فرمائی ہے۔ یہ دونوں ہمارے دو نیک بندوں کے گھر میں تھیں اور دونوں نے ان سے خیانت کی تو وہ اللہ کے مقابلے میں ان عورتوں کے کچھ بھی کام نہ آئے اور انکو حکم دیا گیا کہ دوسرے داخل ہونے والوں کے ساتھ تم بھی دوزخ میں داخل ہو جاؤ۔', 'اللہ نے بتلائی ایک مثل منکروں کے واسطے عورت نوح کی اور عورت لوط کی گھر میں تھیں دونوں دو نیک بندوں کے ہمارے نیک بندوں میں سے پھر اُنہوں نے  اُن سے چوری کی پھر وہ کام نہ آئے اُنکے اللہ کے ہاتھ سے کچھ بھی اور حکم ہوا کہ چلی جاؤ دوزخ میں جانے والوں کے ساتھ', 'Allah sets forth an example for those who disbelieve, the wife of Nooh (Noah) and the wife of Lout (Lot). They were under two of our righteous slaves, but they both betrayed their (husbands by rejecting their doctrine) so they (Nooh (Noah) and Lout (Lot) ) benefited them (their respective wives) not, against Allah, and it was said: \"Enter the Fire along with those who enter!\"', 'Allah has cited for the disbelievers the example of the wife of NūH and the wife of LūT. Both were married with two of Our righteous servants, but betrayed them. So they could not benefit them against Allah at all, and it was said, “Enter the Fire along with those who enter.”'),
(5240, 66, 11, 2, 20, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'التحریم', 'وَ ضَرَبَ اللّٰہُ  مَثَلًا  لِّلَّذِیۡنَ  اٰمَنُوا امۡرَاَتَ  فِرۡعَوۡنَ ۘ اِذۡ  قَالَتۡ رَبِّ ابۡنِ  لِیۡ عِنۡدَکَ  بَیۡتًا فِی الۡجَنَّۃِ  وَ نَجِّنِیۡ  مِنۡ فِرۡعَوۡنَ  وَ عَمَلِہٖ وَ نَجِّنِیۡ  مِنَ الۡقَوۡمِ الظّٰلِمِیۡنَ ﴿ۙ۱۱﴾', 'اور مومنوں کے لئے ایک مثال تو فرعون کی بیوی کی بیان فرمائی کہ اس نے اللہ سے التجا کی کہ اے میرے پروردگار میرے لئے بہشت میں اپنے پاس ایک گھر بنا اور مجھے فرعون اور اسکے عمل سے نجات بخش اور ظالم لوگوں سے مجھ کو چھڑا لے۔', 'اور اللہ نے بتلائی ایک مثل ایمان والوں کے لئے عورت فرعون کی [۱۹] جب بولی اے رب بنا میرے واسطے اپنے پاس ایک گھر بہشت میں [۲۰] اور بچا نکال مجھ کو فرعون سے اور اُسکے کام سے اور بچا نکال مجھ کو ظالم لوگوں سے [۲۱]', 'And Allah has set forth an example for those who believe, the wife of Firaun (Pharaoh), when she said: \"My Lord! Build for me a home with You in Paradise, and save me from Firaun (Pharaoh) and his work, and save me from the people who are Zalimoon (polytheists, wrong-doers and disbelievers in Allah).', 'And Allah has cited for the believers the example of the wife of Fir’aun (Pharaoh), when she said, “My Lord, build for me, near You, a house in the Paradise, and deliver me from Fir’aun and his deeds, and deliver me from the unjust people.”'),
(5241, 66, 12, 2, 20, 28, 'قَدۡ سَمِعَ  اللّٰہُ ', 'التحریم', 'وَ مَرۡیَمَ  ابۡنَتَ عِمۡرٰنَ  الَّتِیۡۤ  اَحۡصَنَتۡ فَرۡجَہَا  فَنَفَخۡنَا فِیۡہِ  مِنۡ  رُّوۡحِنَا وَ صَدَّقَتۡ بِکَلِمٰتِ رَبِّہَا وَ کُتُبِہٖ وَ کَانَتۡ مِنَ  الۡقٰنِتِیۡنَ ﴿٪۱۲﴾', 'اور دوسری مثال عمران کی بیٹی مریم کی جنہوں نے اپنی عزت و ناموس کو محفوظ رکھا۔ تو ہم نے اس میں اپنی روح پھونک دی اور وہ اپنے پروردگار کے کلام اور اسکی کتابوں کو برحق سمجھتی تھیں اور وہ فرمانبرداروں میں سے تھیں۔', 'اور مریم بیٹی عمران کی جس نے روکے رکھا اپنی شہوت کی جگہ کو [۲۲] پھر ہم نے پھونک دی اُس میں ایک اپنی طرف سے جان [۲۳] اور سچا جانا اپنے رب کی باتوں کو اور اُسکی کتابوں کو [۲۴] اور وہ تھی بندگی کرنے والوں میں [۲۵]', 'And Maryam (Mary), the daughter of Imran who guarded her chastity; and We breathed into (the sleeve of her shirt or her garment) through Our Rooh (i.e. Jibrael (Gabriel)), and she testified to the truth of the Words of her Lord (i.e. believed in the Words of Allah: \"Be!\" and he was; that is Iesa (Jesus) son of Maryam (Mary); as a Messenger of Allah), and (also believed in) His Scriptures, and she was of the Qaniteen (i.e. obedient to Allah).', 'And (Allah has also cited the example of) Maryam, daughter of ‘Imrān who guarded her chastity, so We breathed into her Our spirit, and she testified to the truth of the words of her Lord and His books, and she was one of the devout.'),
(5242, 67, 1, 1, 1, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'تَبٰرَکَ الَّذِیۡ  بِیَدِہِ  الۡمُلۡکُ ۫ وَ ہُوَ عَلٰی کُلِّ  شَیۡءٍ قَدِیۡرُۨ ۙ﴿۱﴾', 'وہ کہ جسکے ہاتھ میں بادشاہی ہے بڑی برکت والا ہے اور وہ ہر چیز پر قادر ہے۔', 'بڑی برکت ہے اُسکی جسکے ہاتھ میں ہے راج اور وہ سب کچھ کر سکتا ہے [۱]', 'Blessed is He in Whose Hand is the dominion, and He is Able to do all things.', 'Glorious is the One in whose hand is the Kingdom (of the whole universe), and He is powerful over every thing,'),
(5243, 67, 2, 1, 1, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'الَّذِیۡ  خَلَقَ الۡمَوۡتَ وَ الۡحَیٰوۃَ لِیَبۡلُوَکُمۡ  اَیُّکُمۡ  اَحۡسَنُ عَمَلًا ؕ وَ ہُوَ الۡعَزِیۡزُ  الۡغَفُوۡرُ ۙ﴿۲﴾', 'اسی نے موت اور زندگی کو پیدا کیا تاکہ تمہاری آزمائش کرے کہ تم میں کون اچھے کام کرتا ہے۔ اور وہ زبردست ہے بخشنے والا ہے۔', 'جس نے بنایا مرنا اور جینا تاکہ تم کو جانچے کون تم میں اچھا کرتا ہے کام [۲] اور وہ زبردست ہے بخشنے والا [۳]', 'Who has created death and life, that He may test you which of you is best in deed. And He is the All-Mighty, the Oft-Forgiving;', 'the One who created death and life, so that He may test you as to which of you is better in his deeds. And He is the All-Mighty, the Most-Forgiving,'),
(5244, 67, 3, 1, 1, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'الَّذِیۡ خَلَقَ سَبۡعَ سَمٰوٰتٍ طِبَاقًا ؕ مَا تَرٰی فِیۡ  خَلۡقِ الرَّحۡمٰنِ مِنۡ  تَفٰوُتٍ ؕ فَارۡجِعِ  الۡبَصَرَ ۙ ہَلۡ  تَرٰی مِنۡ فُطُوۡرٍ ﴿۳﴾', 'اسی نے سات آسمان اوپر تلے بنائے۔ اے دیکھنے والے کیا تو رحمٰن کی تخلیق میں کچھ نقص دیکھتا ہے؟ ذرا آنکھ اٹھا کر دیکھ بھلا تجھکو آسمان میں کوئی شگاف نظر آتا ہے؟', 'جس نے بنائے سات آسمان تہہ پر تہہ [۴] کیا دیکھتا ہے تو رحمٰن کے بنانے میں کچھ فرق [۵] پھر دوبارہ نگاہ کر کہیں نظر آتی ہے تجھ کو دڑاڑ [۶]', 'Who has created the seven heavens one above another, you can see no fault in the creations of the Most Beneficent. Then look again: \"Can you see any rifts?\"', 'who has created seven skies, one over the other. You will see nothing out of proportion in the creation of the RaHmān (the All-Merciful Allah). So, cast your eye again. Do you see any rifts?'),
(5245, 67, 4, 1, 1, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'ثُمَّ  ارۡجِعِ  الۡبَصَرَ کَرَّتَیۡنِ  یَنۡقَلِبۡ اِلَیۡکَ  الۡبَصَرُ خَاسِئًا وَّ ہُوَ حَسِیۡرٌ ﴿۴﴾', 'پھر بار بار نظر کر تو نظر ہر بار تیرے پاس ناکام اور تھک کر لوٹ آئے گی۔', 'پھر لوٹا کر نگاہ کر  دو دو بار لوٹ آئے گی تیرے پاس تیری نگاہ رد ہو کر تھک کر [۷]', 'Then look again and yet again, your sight will return to you in a state of humiliation and worn out.', 'Then cast your eye again and again, and the eye will come back to you abased, in a state of weariness.'),
(5246, 67, 5, 1, 1, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'وَ لَقَدۡ  زَیَّنَّا السَّمَآءَ الدُّنۡیَا بِمَصَابِیۡحَ وَ جَعَلۡنٰہَا  رُجُوۡمًا  لِّلشَّیٰطِیۡنِ وَ اَعۡتَدۡنَا لَہُمۡ عَذَابَ السَّعِیۡرِ ﴿۵﴾', 'اور ہم نے قریب کے آسمان کو تاروں کے چراغوں سے زینت دی اور انکو شیطانوں کے مارنے کا آلہ بنایا اور ان کے لئے دہکتی آگ کا عذاب تیار کر رکھا ہے۔', 'اور ہم نے رونق دی سب سے ورلے آسمان کو چراغوں سے [۸] اور اُن سے کر رکھی ہے ہم نے پھینک مار شیطانوں کے واسطے [۹] اور رکھا ہے اُنکے واسطے عذاب دہکتی آگ کا [۱۰]', 'And indeed We have adorned the nearest heaven with lamps, and We have made such lamps (as) missiles to drive away the Shayatin (devils), and have prepared for them the torment of the blazing Fire.', 'And We have decorated the nearest sky with lamps, and have made them devices to stone the devils, and We have prepared for them the punishment of Hell.'),
(5247, 67, 6, 1, 1, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'وَ لِلَّذِیۡنَ کَفَرُوۡا  بِرَبِّہِمۡ  عَذَابُ جَہَنَّمَ ؕ وَ بِئۡسَ الۡمَصِیۡرُ ﴿۶﴾', 'اور جن لوگوں نے اپنے پروردگار سے کفر کیا ان کے لئے جہنم کا عذاب ہے۔ اور وہ برا ٹھکانہ ہے۔', 'اور جو لوگ منکر ہوئے اپنے رب سے اُنکے واسطے ہے عذاب دردناک اور بری جگہ جا پہنچے [۱۱]', 'And for those who disbelieve in their Lord (Allah) is the torment of Hell, and worst indeed is that destination.', 'And for those who disbelieved in their Lord, there is the punishment of Jahannam , and it is an evil end.'),
(5248, 67, 7, 1, 1, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'اِذَاۤ  اُلۡقُوۡا فِیۡہَا سَمِعُوۡا  لَہَا شَہِیۡقًا وَّ ہِیَ  تَفُوۡرُ ۙ﴿۷﴾', 'جب وہ اس میں ڈالے جائیں گے تو اس کا چیخنا چلانا سنیں گے اور وہ جوش مار رہی ہو گی۔', 'جب اُس میں ڈالے جائیں گے سنیں گے اُس کا دہاڑنا اور وہ اچھل رہی ہو گی', 'When they are cast therein, they will hear the (terrible) drawing in of its breath as it blazes forth.', 'When they will be thrown in it, they will hear a terrible sound from it, and it will be boiling,'),
(5249, 67, 8, 1, 1, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'تَکَادُ  تَمَیَّزُ مِنَ  الۡغَیۡظِ ؕ کُلَّمَاۤ  اُلۡقِیَ فِیۡہَا  فَوۡجٌ سَاَلَہُمۡ خَزَنَتُہَاۤ  اَلَمۡ یَاۡتِکُمۡ  نَذِیۡرٌ ﴿۸﴾', 'گویا مارے جوش کے پھٹ پڑے گی۔ جب اس میں انکی کوئی جماعت ڈالی جائے گی تو دوزخ کے داروغہ ان سے پوچھیں گے کیا تمہارے پاس کوئی خبردار کرنے والا نہیں آیا تھا؟', 'ایسا لگتا ہے کہ پھٹ پڑے گی جوش سے [۱۲] جس وقت پڑے اُس میں ایک گروہ پوچھیں اُن سے دوزخ کے داروغہ کیا نہ پہنچا تھا تمہارے پاس کوئی ڈر سنانے والا [۱۳]', 'It almost bursts up with fury. Every time a group is cast therein, its keeper will ask: \"Did no warner come to you?\"', 'seeming as if it will burst out of fury. Whenever a group is thrown into it, its keepers will say to them, “Had no warner come to you?”'),
(5250, 67, 9, 1, 1, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'قَالُوۡا  بَلٰی قَدۡ جَآءَنَا  نَذِیۡرٌ ۬ۙ  فَکَذَّبۡنَا وَ قُلۡنَا مَا نَزَّلَ اللّٰہُ  مِنۡ شَیۡءٍ ۚۖ اِنۡ  اَنۡتُمۡ اِلَّا فِیۡ ضَلٰلٍ کَبِیۡرٍ ﴿۹﴾', 'وہ کہیں گے کیوں نہیں ضرور خبردار کرنے والا آیا تھا۔ بس ہم نے اسکو جھٹلا دیا اور کہا کہ اللہ نے تو کوئی چیز نازل ہی نہیں کی۔ تم تو بڑی غلطی میں پڑے ہوئے ہو۔', 'وہ بولیں کیوں نہیں ہمارے پاس پہنچا تھا ڈر سنانے والا پھر ہم نے جھٹلایا اور کہا نہیں اتاری اللہ نے کوئی چیز تم تو پڑے ہوئے ہو بڑے بہکاوے میں [۱۴]', 'They will say: \"Yes indeed; a warner did come to us, but we belied him and said: Allah never sent down anything (of revelation), you are only in great error.\"', 'They will say, “Yes, a warner had come to us, but We had rejected, and said, ‘Allah has not revealed anything. You are only in great error.’”'),
(5251, 67, 10, 1, 1, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'وَ قَالُوۡا  لَوۡ  کُنَّا نَسۡمَعُ  اَوۡ نَعۡقِلُ مَا کُنَّا فِیۡۤ   اَصۡحٰبِ السَّعِیۡرِ ﴿۱۰﴾', 'اور کہیں گے اگر ہم سنتے یا سمجھتے ہوتے تو دوزخیوں میں نہ ہوتے۔', 'اور کہیں گے اگر ہم ہوتے سنتے یا سمجھتے تو نہ ہوتے دوزخ والوں میں [۱۵]', 'And they will say: \"Had we but listened or used our intelligence, we would not have been among the dwellers of the blazing Fire!\"', 'And they will say, “Had we been listening or understanding, we would not have been among the people of the Hell.”'),
(5252, 67, 11, 1, 1, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'فَاعۡتَرَفُوۡا بِذَنۡۢبِہِمۡ ۚ فَسُحۡقًا  لِّاَصۡحٰبِ السَّعِیۡرِ ﴿۱۱﴾', 'پس وہ اپنے گناہوں کا اعتراف کر لیں گے۔ سو دوزخیوں کے لئے رحمت سے دوری ہے۔', 'سو قائل ہو گئے اپنے گناہ کے اب دفع ہو جائیں دوزخ والے [۱۶]', 'Then they will confess their sin. So, away with the dwellers of the blazing Fire.', 'Thus they will confess their sin. So, away with the people of the Hell!');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(5253, 67, 12, 1, 1, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'اِنَّ  الَّذِیۡنَ یَخۡشَوۡنَ رَبَّہُمۡ بِالۡغَیۡبِ لَہُمۡ مَّغۡفِرَۃٌ  وَّ  اَجۡرٌ  کَبِیۡرٌ ﴿۱۲﴾', 'اور جو لوگ بن دیکھے اپنے پروردگار سے ڈرتے ہیں انکے لئے بخشش اور اجر عظیم ہے۔', 'جو لوگ ڈرتے ہیں اپنے رب سے بن دیکھے [۱۷] اُنکے لئے معافی ہے اور ثواب بڑا', 'Verily! Those who fear their Lord unseen (i.e. they do not see Him, nor His Punishment in the Hereafter, etc.), theirs will be forgiveness and a great reward (i.e. Paradise).', 'Surely, for those who have awe of their Lord without seeing (Him), there is forgiveness and a big reward.'),
(5254, 67, 13, 1, 1, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'وَ اَسِرُّوۡا  قَوۡلَکُمۡ  اَوِ اجۡہَرُوۡا بِہٖ ؕ اِنَّہٗ  عَلِیۡمٌۢ  بِذَاتِ الصُّدُوۡرِ ﴿۱۳﴾', 'اور تم لوگ بات پوشیدہ کہو یا ظاہر وہ تو دلوں کے بھیدوں تک سے واقف ہے۔', 'اور تم چھپا کر کہو اپنی بات یا کھول کر وہ خوب جانتا ہے جیوں کے بھید [۱۸]', 'And whether you keep your talk secret or disclose it, verily, He is the All-Knower of what is in the breasts (of men).', 'Whether you keep your talk secret or make it aloud, He knows well what lies in the hearts.'),
(5255, 67, 14, 1, 1, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'اَلَا یَعۡلَمُ مَنۡ خَلَقَ ؕ وَ ہُوَ اللَّطِیۡفُ الۡخَبِیۡرُ ﴿٪۱۴﴾', 'کیا جس نے پیدا کیا وہ علم نہیں رکھتا؟ وہ تو پوشیدہ باتوں تک کا جاننے والا ہے ہر چیز سے آگاہ ہے۔', 'بھلا وہ نہ جانے جس نے بنایا اور وہی ہے بھید جاننے والا خبردار [۱۹]', 'Should not He Who has created know? And He is the Most Kind and Courteous (to His slaves) All-Aware (of everything).', 'Is it (imaginable) that He who has created (them) will not have (such a) knowledge, while He is the Knower of the finest things, the All-Aware?'),
(5256, 67, 15, 2, 2, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'ہُوَ  الَّذِیۡ جَعَلَ  لَکُمُ  الۡاَرۡضَ ذَلُوۡلًا فَامۡشُوۡا فِیۡ  مَنَاکِبِہَا وَ کُلُوۡا مِنۡ رِّزۡقِہٖ ؕ وَ  اِلَیۡہِ  النُّشُوۡرُ ﴿۱۵﴾', 'وہی تو ہے جس نے تمہارے لئے زمین کو ہموار و پست بنایا تو اسکے رستوں میں چلو پھرو اور اللہ کا دیا ہوا رزق کھاؤ اور تمکو اسی کے پاس قبروں سے اٹھ کر جانا ہے۔', 'وہی ہے جس نے کیا تمہارے آگے زمین کو پست اب چلو  پھرو اُسکے کندھوں پر اور کھاؤ کچھ اُسکی دی ہوئی روزی اور اُسی کی طرف جی اٹھنا ہے [۲۰]', 'He it is, Who has made the earth subservient to you (i.e. easy for you to walk, to live and to do agriculture on it, etc.), so walk in the path thereof and eat of His provision, and to Him will be the Resurrection.', 'He is the One who has made the earth subjugated for you, so walk on its shoulders, and eat out of His provision, and to Him is the Resurrection.'),
(5257, 67, 16, 2, 2, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'ءَاَمِنۡتُمۡ  مَّنۡ  فِی السَّمَآءِ  اَنۡ یَّخۡسِفَ بِکُمُ  الۡاَرۡضَ فَاِذَا ہِیَ  تَمُوۡرُ ﴿ۙ۱۶﴾', 'کیا تم اس سے جو آسمان میں ہے بے خوف ہو کہ تمکو زمین میں دھنسا دے اور تبھی وہ تھرتھرانے لگے۔', 'کیا تم نڈر ہو گئے اُس سے جو آسمان میں ہے اس سے کہ دھنسا دے تم کو زمین میں پھر تبھی وہ لرزنے لگے [۲۱]', 'Do you feel secure that He, Who is over the heaven (Allah), will not cause the earth to sink with you, then behold it shakes (as in an earthquake)?', 'Have you become fearless of Him who is in the sky if He makes you sink into the earth, and it starts trembling at once?'),
(5258, 67, 17, 2, 2, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'اَمۡ اَمِنۡتُمۡ مَّنۡ فِی السَّمَآءِ  اَنۡ یُّرۡسِلَ عَلَیۡکُمۡ حَاصِبًا ؕ فَسَتَعۡلَمُوۡنَ  کَیۡفَ نَذِیۡرِ ﴿۱۷﴾', 'کیا تم اس سے جو آسمان میں ہے نڈر ہو کہ تم پر کنکر بھری ہوا چھوڑ دے۔ سو تم عنقریب جان لو گے کہ میرا ڈرانا کیسا رہا۔', 'یا نڈر ہو گئے ہو اُس سے جو آسمان میں ہے اس بات سے کہ برسا دے تم پر مینہ پتھروں کا [۲۲] سو جان لو گے کیسا ہے میرا ڈرانا [۲۳]', 'Or do you feel secure that He, Who is over the heaven (Allah), will not send against you a violent whirlwind? Then you shall know how (terrible) has been My Warning?', 'Or, have you become fearless of Him who is in the sky if He looses a violent wind with stones against you? So, you will soon come to know how was My warning!'),
(5259, 67, 18, 2, 2, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'وَ لَقَدۡ  کَذَّبَ الَّذِیۡنَ مِنۡ قَبۡلِہِمۡ فَکَیۡفَ کَانَ نَکِیۡرِ ﴿۱۸﴾', 'اور جو لوگ ان سے پہلے تھے انہوں نے بھی جھٹلایا تھا سو دیکھ لو کہ میرا کیسا عذاب ہوا۔', 'اور جھٹلا چکے ہیں جو اُن سے پہلے تھے پھر کیسا ہوا میرا انکار [۲۴]', 'And indeed those before them belied (the Messengers of Allah), then how terrible was My denial (punishment)?', 'And of course, those before them (also) rejected (the truth). So, how was My censure?'),
(5260, 67, 19, 2, 2, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'اَوَ لَمۡ  یَرَوۡا اِلَی الطَّیۡرِ فَوۡقَہُمۡ صٰٓفّٰتٍ وَّ یَقۡبِضۡنَ ؔۘؕ مَا یُمۡسِکُہُنَّ  اِلَّا الرَّحۡمٰنُ ؕ اِنَّہٗ  بِکُلِّ  شَیۡءٍۭ بَصِیۡرٌ ﴿۱۹﴾', 'کیا انہوں نے اپنے اوپر پرندوں کو نہیں دیکھا جو پروں کو پھیلائے رہتے ہیں اور انکو سکیڑ بھی لیتے ہیں۔ رحمٰن کے سوا انہیں کوئی تھام نہیں سکتا۔ بیشک وہ ہر چیز کو دیکھ رہا ہے۔', 'اور کیا نہیں دیکھتے ہو اڑتے جانوروں کو اپنے اوپر پر کھولے ہوئے اور پر جھپکتے ہوئے اُن کو کوئی نہیں تھام رہا رحمان کے سوائے اُسکی نگاہ میں ہے ہر چیز  [۲۵]', 'Do they not see the birds above them, spreading out their wings and folding them in? None upholds them except the Most Beneficent (Allah). Verily, He is the All-Seer of everything.', 'Have they not looked to the birds above them spreading their wings, and (at times) they fold (them) in? No one holds them up except the RaHmān (the All-Merciful Allah). Surely He is watchful of every thing.'),
(5261, 67, 20, 2, 2, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'اَمَّنۡ  ہٰذَا  الَّذِیۡ  ہُوَ جُنۡدٌ لَّکُمۡ یَنۡصُرُکُمۡ  مِّنۡ  دُوۡنِ  الرَّحۡمٰنِ ؕ اِنِ الۡکٰفِرُوۡنَ  اِلَّا  فِیۡ  غُرُوۡرٍ ﴿ۚ۲۰﴾', 'بھلا ایسا کون ہے جو تمہاری فوج بن کر رحمٰن کے مقابلے میں تمہاری مدد کر سکے۔ کافر تو دھوکے ہی میں ہیں۔', 'بھلا وہ کون ہے جو فوج ہے تمہاری مدد کرے تمہاری رحمٰن کے سوائے منکر پڑے ہیں برے بہکائے میں [۲۶]', 'Who is he besides the Most Beneficent that can be an army to you to help you? The disbelievers are in nothing but delusion.', 'Now, who is there to act as a force for you to help you, except the RaHmān ? The disbelievers are in nothing but delusion.'),
(5262, 67, 21, 2, 2, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'اَمَّنۡ ہٰذَا الَّذِیۡ یَرۡزُقُکُمۡ  اِنۡ  اَمۡسَکَ رِزۡقَہٗ ۚ بَلۡ لَّجُّوۡا فِیۡ عُتُوٍّ  وَّ نُفُوۡرٍ ﴿۲۱﴾', 'بھلا اگر وہ اپنا رزق بند کر لے تو کون ہے جو تمکو رزق دے سکے؟ لیکن یہ سرکشی اور نفرت میں پھنسے ہوئے ہیں۔', 'بھلا وہ کون ہے جو روزی دے تم کو اگر وہ رکھ چھوڑے اپنی روزی [۲۷] کوئی نہیں پر اڑ رہے ہیں شرارت اور بدکنے پر [۲۸]', 'Who is he that can provide for you if He should withhold His provision? Nay, but they continue to be in pride, and (they) flee (from the truth).', 'Or, who is there to give you sustenance, if He withholds His sustenance? Still, they persist in rebellion and aversion.'),
(5263, 67, 22, 2, 2, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'اَفَمَنۡ یَّمۡشِیۡ مُکِبًّا عَلٰی وَجۡہِہٖۤ  اَہۡدٰۤی  اَمَّنۡ  یَّمۡشِیۡ سَوِیًّا عَلٰی صِرَاطٍ مُّسۡتَقِیۡمٍ ﴿۲۲﴾', 'بھلا جو شخص چلتا ہو منہ کے بل اوندھا وہ سیدھے رستے پر ہے یا وہ جو سیدھے رستے پر سیدھا چل رہا ہو؟', 'بھلا ایک جو چلے اوندھا اپنے منہ کے بل وہ سیدھی راہ پائے یا وہ شخص جو چلے سیدھا ایک سیدھی راہ پر [۲۹]', 'Is he who walks without seeing on his face, more rightly guided, or he who (sees and) walks on a Straight Way (i.e. Islamic Monotheism).', 'Then, is the one who walks falling down (frequently) on his face more right or the one who walks properly on a straight path?'),
(5264, 67, 23, 2, 2, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'قُلۡ ہُوَ الَّذِیۡۤ  اَنۡشَاَکُمۡ وَ جَعَلَ  لَکُمُ السَّمۡعَ وَ الۡاَبۡصَارَ وَ الۡاَفۡـِٕدَۃَ ؕ قَلِیۡلًا مَّا  تَشۡکُرُوۡنَ ﴿۲۳﴾', 'کہدو وہی تو ہے جس نے تمکو پیدا کیا اور تمہارے کان اور آنکھیں اور دل بنائے۔ مگر تم کم ہی احسان مانتے ہو۔', 'تو کہہ وہی ہے جس نے تم کو بنا کھڑا کیا اور بنا دیے تمہارے واسطے کان اور آنکھیں اور دل تم بہت تھوڑا حق مانتے ہو [۳۰]', 'Say it is He Who has created you, and endowed you with hearing (ears), seeing (eyes), and hearts. Little thanks you give.', 'Say, “He is the One who has originated you, and made for you ears and eyes and hearts. How little you pay gratitude!”'),
(5265, 67, 24, 2, 2, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'قُلۡ ہُوَ الَّذِیۡ ذَرَاَکُمۡ فِی الۡاَرۡضِ وَ اِلَیۡہِ تُحۡشَرُوۡنَ ﴿۲۴﴾', 'کہدو کہ وہی ہے جس نے تمکو زمین  میں پھیلایا اور اسی کے روبرو تم جمع کئے جاؤ گے۔', 'تو کہہ وہی ہے جس نے کھنڈا دیا تم کو زمین میں اور اُسی کی طرف اکٹھے کئے جاؤ گے [۳۱]', 'Say: \"It is He Who has created you from the earth, and to Him shall you be gathered (in the Hereafter).\"', 'Say, “He is the One who has scattered you on the earth, and to Him you will be assembled.”'),
(5266, 67, 25, 2, 2, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'وَ یَقُوۡلُوۡنَ مَتٰی ہٰذَا الۡوَعۡدُ  اِنۡ  کُنۡتُمۡ صٰدِقِیۡنَ ﴿۲۵﴾', 'اور کافر کہتے ہیں کہ اگر تم سچے ہو تو بتاؤ یہ وعدہ قیامت کا کب پورا ہو گا۔', 'اور کہتے ہیں کب ہو گا یہ وعدہ اگر تم سچے ہو [۳۲]', 'They say: \"When will this promise (i.e. the Day of Resurrection) come to pass? if you are telling the truth.\"', 'And they say, “When will this promise (of the Day of Judgment) be fulfilled, if you are true?”'),
(5267, 67, 26, 2, 2, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'قُلۡ  اِنَّمَا  الۡعِلۡمُ عِنۡدَ اللّٰہِ ۪ وَ  اِنَّمَاۤ  اَنَا نَذِیۡرٌ  مُّبِیۡنٌ ﴿۲۶﴾', 'کہدو کہ اس کا علم اللہ ہی کو ہے۔ اور میں تو کھول کھول کر ڈر سنا دینے والا ہوں۔', 'تو کہہ خبر تو ہے اللہ ہی کے پاس اور میرا کام تو یہی ڈر سنا دینا ہے کھول کر [۳۳]', 'Say (O Muhammad SAW): \"The knowledge (of its exact time) is with Allah only, and I am only a plain warner.\"', 'Say, “The knowledge (of that Day) is only with Allah, and I am only a plain warner.'),
(5268, 67, 27, 2, 2, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'فَلَمَّا رَاَوۡہُ   زُلۡفَۃً  سِیۡٓـَٔتۡ وُجُوۡہُ الَّذِیۡنَ کَفَرُوۡا وَ قِیۡلَ ہٰذَا  الَّذِیۡ کُنۡتُمۡ بِہٖ  تَدَّعُوۡنَ ﴿۲۷﴾', 'سو جب وہ دیکھ لیں گے کہ وہ عذاب قریب آ گیا تو کافروں کے منہ بگڑ جائیں گے۔ اور ان سے کہا جائے گا کہ یہ وہی ہے جسکے تم طلبگار تھے۔', 'پھر جب دیکھیں گے کہ وہ پاس آ لگا تو بگڑ جائیں گے منہ منکروں کے اور کہے گا یہی ہے جس کو تم مانگتے تھے [۳۴]', 'But when they will see it (the torment on the Day of Resurrection) approaching, the faces of those who disbelieve will be different (black, sad, and in grieve), and it will be said (to them): \"This is (the promise) which you were calling for!\"', 'Then, once they will see it approaching, the faces of the disbelievers will be turned awkward, and it will be said, “This is what you were calling for!”'),
(5269, 67, 28, 2, 2, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'قُلۡ اَرَءَیۡتُمۡ  اِنۡ  اَہۡلَکَنِیَ  اللّٰہُ  وَ مَنۡ مَّعِیَ  اَوۡ  رَحِمَنَا ۙ فَمَنۡ  یُّجِیۡرُ الۡکٰفِرِیۡنَ مِنۡ عَذَابٍ اَلِیۡمٍ ﴿۲۸﴾', 'کہو کہ بھلا دیکھو تو اگر اللہ مجھ کو اور میرے ساتھیوں کو ہلاک کر دے یا ہم پر مہربانی کرے۔ تو کون ہے جو کافروں کو دکھ دینے والے عذاب سے پناہ دے؟', 'تو کہہ بھلا دیکھو تو اگر ہلاک کر دے مجھ کو اللہ اور  میرے ساتھ والو کو یا ہم پر رحم کرے پھر وہ کون ہے جو بچائے منکروں کو عذاب دردناک سے [۳۵]', 'Say (O Muhammad SAW): \"Tell me! If Allah destroys me, and those with me, or He bestows His Mercy on us, - who can save the disbelievers from a painful torment?\"', 'Say, “Tell me, if Allah destroys me and those who are with me (as you wish), or has mercy on us (as we wish), who can (in either case) save the disbelievers from a painful punishment?”'),
(5270, 67, 29, 2, 2, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'قُلۡ  ہُوَ الرَّحۡمٰنُ  اٰمَنَّا بِہٖ  وَ عَلَیۡہِ تَوَکَّلۡنَا ۚ فَسَتَعۡلَمُوۡنَ مَنۡ ہُوَ  فِیۡ ضَلٰلٍ مُّبِیۡنٍ ﴿۲۹﴾', 'کہدو کہ وہ جو رحمٰن ہے ہم اسی پر ایمان لائے اور اسی پر بھروسا رکھتے ہیں۔ تمکو جلد معلوم ہو جائے گا کہ کھلی گمراہی میں کون پڑا ہے۔', 'تو کہہ وہی رحمٰن ہے ہم نے اُسکو مانا اور اُسی پر بھروسہ کیا [۳۶] سو اب تم جان لو گے کون پڑ اہے صریح بہکائے میں [۳۷]', 'Say: \"He is the Most Beneficent (Allah), in Him we believe, and in Him we put our trust. So you will come to know who is it that is in manifest error.\"', 'Say, “He is the RaHmān; we have believed in Him, and in Him we placed our trust. So, you will soon come to know who is in open error.”'),
(5271, 67, 30, 2, 2, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الملک', 'قُلۡ  اَرَءَیۡتُمۡ  اِنۡ  اَصۡبَحَ مَآؤُکُمۡ غَوۡرًا فَمَنۡ یَّاۡتِیۡکُمۡ بِمَآءٍ مَّعِیۡنٍ ﴿٪۳۰﴾', 'کہو کہ بھلا دیکھو تو اگر تمہارا پانی جو تم پیتے ہو اور برتتے ہو خشک ہو جائے تو اللہ کے سوا کون ہے جو تمہارے لئے شفاف پانی کا چشمہ بہا لائے۔', 'تو کہہ بھلا دیکھو تو اگر ہو جائے صبح کو پانی تمہارا خشک پھر کون ہے جو لائے تمہارے پاس پانی نتھرا [۳۸]', 'Say (O Muhammad SAW): \"Tell me! If (all) your water were to be sunk away, who then can supply you with flowing (spring) water?\"', 'Say, “Tell me, Should your water vanish into the earth, who will bring you a flowing (stream of) water?'),
(5272, 68, 1, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'نٓ  وَ الۡقَلَمِ وَ مَا یَسۡطُرُوۡنَ ۙ﴿۱﴾', 'نٓ۔ قلم کی اور جو کچھ لکھنے والے لکھتے ہیں اسکی قسم۔', 'نٓ۔  قسم ہے قلم کی اور جو کچھ لکھتے ہیں', 'Noon. (These letters (Noon, etc.) are one of the miracles of the Quran, and none but Allah (Alone) knows their meanings).By the pen and what the (angels) write (in the Records of men).', 'Nūn , by the pen and what they write,'),
(5273, 68, 2, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'مَاۤ  اَنۡتَ بِنِعۡمَۃِ رَبِّکَ بِمَجۡنُوۡنٍ ۚ﴿۲﴾', 'کہ اے پیغمبر ﷺ تم اپنے پروردگار کے فضل سے دیوانے نہیں ہو۔', 'تو نہیں اپنے رب کے فضل سے دیوانہ [۱]', 'You (O Muhammad SAW) are not, by the Grace of your Lord, a madman.', 'with the grace of your Lord, you are not insane.'),
(5274, 68, 3, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'وَ  اِنَّ  لَکَ لَاَجۡرًا غَیۡرَ  مَمۡنُوۡنٍ ۚ﴿۳﴾', 'اور بیشک تمہارے لئے بے انتہا اجر ہے۔', 'اور تیرے واسطے بدلا ہے بے انتہا [۲]', 'And verily, for you (O Muhammad SAW) will be an endless reward.', 'And you will definitely have a reward that will never end.'),
(5275, 68, 4, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'وَ  اِنَّکَ لَعَلٰی خُلُقٍ عَظِیۡمٍ ﴿۴﴾', 'اور یقینًا تم اخلاق کے اعلیٰ مرتبے پر ہو۔', 'اور تو پیدا ہوا ہے بڑے خلق پر [۳]', 'And verily, you (O Muhammad SAW) are on an exalted standard of character.', 'And you are surely on an excellent standard of character.'),
(5276, 68, 5, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'فَسَتُبۡصِرُ وَ یُبۡصِرُوۡنَ ۙ﴿۵﴾', 'سو عنقریب تم بھی دیکھ لو گے اور یہ کافر بھی دیکھ لیں گے۔', 'سو اب تو بھی دیکھ لے گا اور وہ بھی دیکھ لیں گے', 'You will see, and they will see,', 'So, you will see, and they will see'),
(5277, 68, 6, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'بِاَىیِّکُمُ  الۡمَفۡتُوۡنُ ﴿۶﴾', 'کہ تم میں سے کون دیوانہ ہے۔', 'کہ کون ہے تم میں جو بچل رہا ہے [۴]', 'Which of you is afflicted with madness.', 'which of you is demented.'),
(5278, 68, 7, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'اِنَّ  رَبَّکَ ہُوَ اَعۡلَمُ بِمَنۡ ضَلَّ عَنۡ سَبِیۡلِہٖ ۪ وَ ہُوَ اَعۡلَمُ  بِالۡمُہۡتَدِیۡنَ ﴿۷﴾', 'تحقیق تمہارا پروردگار اسکو بھی خوب جانتا ہے جو اسکے رستے سے بھٹک گیا اور انکو بھی خوب جانتا ہے جو سیدھے رستے پر چل رہے ہیں۔', 'بیشک تیرا رب وہی خوب جانے اُسکو جو بہکا اُسکی راہ سے اور وہی جانتا ہے راہ پانے والوں کو [۵]', 'Verily, your Lord knows better, who (among men) has gone astray from His Path, and He knows better those who are guided.', 'Surely your Lord knows best who has strayed from his way, and He is well aware of those who are on the right path.'),
(5279, 68, 8, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'فَلَا تُطِعِ  الۡمُکَذِّبِیۡنَ ﴿۸﴾', 'تو تم جھٹلانے والوں کا کہا نہ ماننا۔', 'سو تو کہنا مت مان جھٹلانے والوں کا', 'So (O Muhammad SAW) obey not the deniers ((of Islamic Monotheism those who belie the Verses of Allah), the Oneness of Allah, and the Messenger of Allah (Muhammad SAW), etc.)', 'So, do not obey those who reject (the true faith.)'),
(5280, 68, 9, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'وَدُّوۡا  لَوۡ  تُدۡہِنُ  فَیُدۡہِنُوۡنَ ﴿۹﴾', 'یہ لوگ چاہتے ہیں کہ تم نرمی اختیار کرو تو یہ بھی نرم ہو جائیں۔', 'وہ چاہتے ہیں کسی طرح تو ڈھیلا ہو تو  وہ بھی ڈھیلے ہوں [۶] ہوں', 'They wish that you should compromise (in religion out of courtesy) with them, so they (too) would compromise with you.', 'They wish that you become flexible (in your faith), so that they should become flexible (in their hostile attitude.)'),
(5281, 68, 10, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'وَ لَا  تُطِعۡ  کُلَّ حَلَّافٍ مَّہِیۡنٍ ﴿ۙ۱۰﴾', 'اور کسی ایسے شخص کے کہے میں نہ آ جانا جو بہت قسمیں کھانے والا ہے ذلیل ہے۔', 'اور تو کہا مت مان کسی قسمیں کھانے والے بے قدر کا [۷]', 'And obey not everyone who swears much, and is considered worthless,', 'And do not obey any contemptible one who swears much,'),
(5282, 68, 11, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'ہَمَّازٍ مَّشَّآءٍۭ  بِنَمِیۡمٍ ﴿ۙ۱۱﴾', 'شرارت سے اشارے کرنے والا لگائی بجھائی کرنے والا۔', 'طعنے دے چغلی کھاتا پھرے', 'A slanderer, going about with calumnies,', 'a slanderer who goes about with calumnies,'),
(5283, 68, 12, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'مَّنَّاعٍ  لِّلۡخَیۡرِ مُعۡتَدٍ اَثِیۡمٍ ﴿ۙ۱۲﴾', 'مال دینے میں بڑا بخیل حد سے بڑھا ہوا بدکار۔', 'بھلے کام سے روکے حد سے بڑھے بڑا گنہگار', 'Hinderer of the good, transgressor, sinful,', 'one who prevents good, (and who is) transgressor, sinful,'),
(5284, 68, 13, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'عُتُلٍّۭ  بَعۡدَ ذٰلِکَ  زَنِیۡمٍ ﴿ۙ۱۳﴾', 'سخت خو اور اس کے علاوہ بدذات ہے۔', 'اُجڈ ان سب کے پیچھے بدنام [۸]', 'Cruel, after all that base-born (of illegitimate birth),', 'harsh, (and) after all that, notorious,'),
(5285, 68, 14, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'اَنۡ  کَانَ  ذَا مَالٍ وَّ  بَنِیۡنَ ﴿ؕ۱۴﴾', 'اس سبب سے کہ مال اور بیٹے رکھتا ہے۔', 'اس واسطے کہ رکھتا ہے مال اور بیٹے [۹]', '(He was so) because he had wealth and children.', '(do not obey such a person merely) because he is a man of wealth and sons.'),
(5286, 68, 15, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'اِذَا  تُتۡلٰی عَلَیۡہِ  اٰیٰتُنَا  قَالَ  اَسَاطِیۡرُ الۡاَوَّلِیۡنَ ﴿۱۵﴾', 'جب اسکو ہماری آیتیں پڑھ کر سنائی جاتی ہیں تو کہتا ہے کہ یہ اگلے لوگوں کے افسانے ہیں۔', 'جب سنائے اُس کو ہماری باتیں کہے یہ نقلیں ہیں پہلوں کی [۱۰]', 'When Our Verses (of the Quran) are recited to him, he says: \"Tales of the men of old!\"', 'When Our verses are recited to him, he says, “(These are) the tales of the ancient.”'),
(5287, 68, 16, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'سَنَسِمُہٗ  عَلَی  الۡخُرۡطُوۡمِ ﴿۱۶﴾', 'ہم عنقریب اسکی اونچی ناک پر داغ لگائیں گے۔', 'اب داغ دیں گے ہم اُسکو سونڈ پر [۱۱]', 'We shall brand him over the nose!', 'We will soon brand him on the snout.'),
(5288, 68, 17, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'اِنَّا  بَلَوۡنٰہُمۡ کَمَا بَلَوۡنَاۤ  اَصۡحٰبَ الۡجَنَّۃِ ۚ اِذۡ  اَقۡسَمُوۡا لَیَصۡرِمُنَّہَا مُصۡبِحِیۡنَ ﴿ۙ۱۷﴾', 'ہم نے ان لوگوں کی اسی طرح آزمائش کی ہے جس طرح باغ والوں کی آزمائش کی تھی۔ جب انہوں نے قسمیں کھا کھا کر کہا کہ صبح ہوتے ہوتے ہم اس کا میوہ توڑ لیں گے۔', 'ہم نے اُن کو جانچا ہے جیسے جانچا تھا باغ  والوں کو [۱۲] جب اُن سب نے قسم کھائی کہ اُس کا میوہ توڑیں گے صبح ہوتے', 'Verily, We have tried them as We tried the people of the garden, when they swore to pluck the fruits of the (garden) in the morning,', 'We have tested them as We had tested the Owners of the Garden, when they had sworn an oath that they would pluck its fruits on the next morning,'),
(5289, 68, 18, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'وَ لَا  یَسۡتَثۡنُوۡنَ ﴿۱۸﴾', 'اور ان شاء اللہ نہ کہا۔', 'اور ان شاء اللہ نہ کہا [۱۳]', 'Without saying: Insha Allah (If Allah will).', 'and did not make any exception (by saying inshā’allāh ).'),
(5290, 68, 19, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'فَطَافَ عَلَیۡہَا طَآئِفٌ مِّنۡ رَّبِّکَ وَ ہُمۡ نَآئِمُوۡنَ ﴿۱۹﴾', 'سو وہ ابھی سو ہی رہے تھے کہ تمہارے پروردگار کی طرف سے راتوں رات اس پر ایک آفت پھر گئ۔', 'پھر پھیرا کر گیا اُس پر کوئی پھیرے والا تیرے رب کی طرف سے اور وہ سوتے ہی رہے', 'Then there passed by on the (garden) something (fire) from your Lord at night and burnt it while they were asleep.', 'Then, there whirled around it a whirl (of calamity) from your Lord, while they were asleep.'),
(5291, 68, 20, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'فَاَصۡبَحَتۡ  کَالصَّرِیۡمِ ﴿ۙ۲۰﴾', 'تو وہ ایسا ہو گیا جیسے کٹی ہوئی کھیتی۔', 'پھر صبح تک ہو رہاجیسے ٹوٹ چکا [۱۴]', 'So the (garden) became black by the morning, like a pitch dark night (in complete ruins).', 'Thus, on the next morning, it was like a harvested field.'),
(5292, 68, 21, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'فَتَنَادَوۡا  مُصۡبِحِیۡنَ ﴿ۙ۲۱﴾', 'پھر جب صبح ہوئی تو وہ لوگ ایک دوسرے کو پکارنے لگے۔', 'پھر آپس میں بولے صبح ہوتے', 'Then they called out one to another as soon as the morning broke,', 'So, they called out each other as the morning broke,'),
(5293, 68, 22, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'اَنِ  اغۡدُوۡا عَلٰی حَرۡثِکُمۡ  اِنۡ کُنۡتُمۡ صٰرِمِیۡنَ ﴿۲۲﴾', 'کہ اگر تمکو کاٹنا ہے تو اپنی کھیتی پر سویرے ہی جا پہنچو۔', 'کہ سویرے چلو اپنے کھیت پر اگر تمکو توڑنا ہے', 'Saying: \"Go to your tilth in the morning, if you would pluck the fruits.\"', 'saying, “Set out early, if you are going to pluck (the fruits).”'),
(5294, 68, 23, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'فَانۡطَلَقُوۡا وَ  ہُمۡ  یَتَخَافَتُوۡنَ ﴿ۙ۲۳﴾', 'سو وہ چل پڑے اور آپس میں چپکے چپکے کہتے جاتے تھے۔', 'پھر چلے اور آپس میں کہتے تھے چپکے چپکے', 'So they departed, conversing in secret low tones (saying),', 'So they set out while they were whispering to each other,'),
(5295, 68, 24, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'اَنۡ  لَّا یَدۡخُلَنَّہَا  الۡیَوۡمَ عَلَیۡکُمۡ مِّسۡکِیۡنٌ ﴿ۙ۲۴﴾', 'کہ آج وہاں تمہارے پاس کوئی فقیر نہ آنے پائے۔', 'کہ اندر نہ آنے پائے اُس میں آج تمہارے پاس کوئی محتاج', 'No Miskeen (poor man) shall enter upon you into it today.', 'saying, “Let no poor man enter into it upon you today.”'),
(5296, 68, 25, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'وَّ  غَدَوۡا عَلٰی حَرۡدٍ   قٰدِرِیۡنَ ﴿۲۵﴾', 'اور کوشش کے ساتھ سویرے ہی جا پہنچے گویا پیداوار پر قادر ہیں۔', 'اور سویرے چلے لپکتے ہوئے زور کے ساتھ [۱۵]', 'And they went in the morning with strong intention, thinking that they have power (to prevent the poor taking anything of the fruits therefrom).', 'And in early hours they rushed quickly, while they were (assuming themselves) powerful (to pluck the fruits and prevent the poor.)'),
(5297, 68, 26, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'فَلَمَّا رَاَوۡہَا  قَالُوۡۤا اِنَّا لَضَآلُّوۡنَ ﴿ۙ۲۶﴾', 'پھر جب انہوں نے باغ کو دیکھا تو ویران کہنے لگے کہ ہم رستہ بھول گئے ہیں۔', 'پھر جب اُسکو دیکھا بولے ہم تو راہ بھول آئے', 'But when they saw the (garden), they said: \"Verily, we have gone astray,\"', 'But when they saw it (the place of the ruined garden), they said, “We have missed the way.”'),
(5298, 68, 27, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'بَلۡ  نَحۡنُ  مَحۡرُوۡمُوۡنَ ﴿۲۷﴾', 'نہیں بلکہ ہم بے نصیب ہو گئے۔', 'نہیں ہماری تو قسمت پھوٹ گئ [۱۶]', '(Then they said): \"Nay! Indeed we are deprived of (the fruits)!\"', '(Then, once they realized that the garden is the same, but it has been destroyed, they said,) “No, but we are deprived (of the fruits).”'),
(5299, 68, 28, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'قَالَ  اَوۡسَطُہُمۡ  اَلَمۡ  اَقُلۡ  لَّکُمۡ  لَوۡ لَا تُسَبِّحُوۡنَ ﴿۲۸﴾', 'ایک جو ان میں سمجھدار تھا بولا کیا میں نے تم سے نہیں کہا تھا کہ تم تسبیح کیوں نہیں کرتے؟', 'بولا بچلا اُن کا میں نے تم کو نہ کہا تھا کہ کیوں نہیں پاکی بولتے اللہ کی [۱۷]', 'The best among them said: \"Did I not tell you: why do you not say: Insha Allah (If Allah will).\"', 'Said he who was the best among them, “Did I not say to you, ‘Why do you not pronounce tasbīH (Allah’s purity)?”'),
(5300, 68, 29, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'قَالُوۡا سُبۡحٰنَ رَبِّنَاۤ  اِنَّا کُنَّا ظٰلِمِیۡنَ ﴿۲۹﴾', 'دوسرے کہنے لگے کہ ہمارا پروردگار پاک ہے بیشک ہم ہی قصوروار تھے۔', 'بولے پاک ذات ہے ہمارے رب کی ہم ہی تقصیر وار تھے', 'They said: \"Glory to Our Lord! Verily, we have been Zalimoon (wrong-doers, etc.).\"', 'They said, “We pronounce the purity of our Lord. No doubt, we were wrongdoers.”'),
(5301, 68, 30, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'فَاَقۡبَلَ بَعۡضُہُمۡ عَلٰی بَعۡضٍ یَّتَلَاوَمُوۡنَ ﴿۳۰﴾', 'پھر لگے ایک دوسرے کی طرف رخ کر کے ملامت کرنے۔', 'پھر منہ کر کر ایک دوسرے کی طرف لگے اُلاہنا دینے [۱۸]', 'Then they turned, one against another, in blaming.', 'Then, (at the beginning,) they started reproaching one another;'),
(5302, 68, 31, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'قَالُوۡا یٰوَیۡلَنَاۤ  اِنَّا کُنَّا طٰغِیۡنَ ﴿۳۱﴾', 'کہنے لگے ہائے شامت ہم ہی حد سے بڑھ گئے تھے۔', 'یبولے ہائے خرابی ہماری ہم ہی تھے حد سے بڑھنے والے', 'They said: \"Woe to us! Verily, we were Taghoon (transgressors and disobedient, etc.)', '(and at last,) they said, “Woe to us! In fact, we (all) were outrageous.'),
(5303, 68, 32, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'عَسٰی رَبُّنَاۤ  اَنۡ یُّبۡدِلَنَا خَیۡرًا  مِّنۡہَاۤ  اِنَّاۤ اِلٰی  رَبِّنَا  رٰغِبُوۡنَ ﴿۳۲﴾', 'امید ہے کہ ہمارا پروردگار اسکے بدلے میں ہمیں اس سے بہتر باغ عنایت کرے ہم اپنے پروردگار کی طرف رجوع کرتے ہیں۔', 'شاید ہمارا رب بدل دے ہمکو اس سے بہتر ہم اپنے رب سے آرزو رکھتے ہیں [۱۹]', 'We hope that our Lord will give us in exchange a better (garden) than this. Truly, we turn to our Lord (wishing for good that He may forgive our sins, and reward us in the Hereafter).\"', 'We hope that our Lord will give us in exchange something better than this. Truly we turn to Allah.”'),
(5304, 68, 33, 1, 3, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'کَذٰلِکَ الۡعَذَابُ ؕ وَ لَعَذَابُ الۡاٰخِرَۃِ اَکۡبَرُ ۘ لَوۡ  کَانُوۡا  یَعۡلَمُوۡنَ ﴿٪۳۳﴾', 'دیکھو عذاب یوں ہوتا ہے۔ اور آخرت کا عذاب سب سے بڑھکر ہو گا کاش! یہ لوگ جانتے ہوتے۔', 'یوں آتی ہے آفت اور آخرت کی آفت تو سب سے بڑی ہے اگر اُنکو سمجھ ہوتی [۲۰]', 'Such is the punishment (in this life), but truly, the punishment of the Hereafter is greater, if they but knew.', 'In this way the punishment comes. And, of course, the punishment of the Hereafter is even greater, if they but realize!'),
(5305, 68, 34, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'اِنَّ  لِلۡمُتَّقِیۡنَ عِنۡدَ رَبِّہِمۡ جَنّٰتِ النَّعِیۡمِ ﴿۳۴﴾', 'پرہیزگاروں کے لئے ان کے پروردگار کے ہاں نعمت کے باغ ہیں۔', 'البتہ ڈرنے والوں کو اُنکے رب کے پاس باغ ہیں نعمت کے [۲۱]', 'Verily, for the Muttaqoon (pious and righteous persons - see V.2:2) are Gardens of delight (Paradise) with their Lord.', 'Surely, for the God-fearing there are gardens of bliss.'),
(5306, 68, 35, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'اَفَنَجۡعَلُ الۡمُسۡلِمِیۡنَ کَالۡمُجۡرِمِیۡنَ ﴿ؕ۳۵﴾', 'کیا ہم فرمانبرداروں کو نافرمانوں کی طرح نعمتوں سے محروم کر دیں گے۔', 'کیا ہم کر دیں گے حکم برداروں کو برابر گنہگاروں کے', 'Shall We then treat the (submitting) Muslims like the Mujrimoon (criminals, polytheists and disbelievers, etc.)?', 'Otherwise, shall We make the obedient like the sinners?'),
(5307, 68, 36, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'مَا  لَکُمۡ ٝ  کَیۡفَ تَحۡکُمُوۡنَ ﴿ۚ۳۶﴾', 'تمہیں کیا ہو گیا ہے کیسی تجویزیں کرتے ہو؟', 'کیا ہو گیا تمکو کیسے ٹھہرا رہے ہو بات [۲۲]', 'What is the matter with you? How judge you?', 'What has happened to you? How do you judge?'),
(5308, 68, 37, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'اَمۡ  لَکُمۡ  کِتٰبٌ فِیۡہِ  تَدۡرُسُوۡنَ ﴿ۙ۳۷﴾', 'کیا تمہارے پاس کوئی کتاب ہے جس میں یہ بات پڑھتے ہو۔', 'کیا تمہارے پا س کوئی کتاب ہے جس میں پڑھ لیتے ہو', 'Or have you a Book through which you learn.', 'Do you have a book in which you read'),
(5309, 68, 38, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'اِنَّ  لَکُمۡ  فِیۡہِ  لَمَا تَخَیَّرُوۡنَ ﴿ۚ۳۸﴾', 'کہ جو چیز تم پسند کرو گے وہ تمکو ضرور ملے گی۔', 'اُس میں ملتا ہے تمکو جو تم پسند کر لو', 'That you shall have all that you choose?', 'that for you there is what you choose?'),
(5310, 68, 39, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'اَمۡ لَکُمۡ  اَیۡمَانٌ عَلَیۡنَا بَالِغَۃٌ  اِلٰی یَوۡمِ الۡقِیٰمَۃِ ۙ اِنَّ  لَکُمۡ لَمَا تَحۡکُمُوۡنَ ﴿ۚ۳۹﴾', 'یا تم نے ہم سے قسمیں لے رکھی ہیں جو قیامت کے دن تک چلی جائیں گی کہ جو کچھ تم طے کر لو گے وہ تمہارا ہو گا۔', 'کیا تم نے ہم سے قسمیں لے لی ہیں ٹھیک پہنچنے والی قیامت کے دن تک کہ تم کو ملے گاجو کچھ تم ٹھہراؤ گے', 'Or you have oaths from Us, reaching to the Day of Resurrection that yours will be what you judge.', 'Or do you have oaths sworn by Us, remaining effective up to the Day of Judgment, that you will get what you decide?'),
(5311, 68, 40, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'سَلۡہُمۡ  اَیُّہُمۡ  بِذٰلِکَ  زَعِیۡمٌ ﴿ۚۛ۴۰﴾', 'ان سے پوچھو کہ ان میں سے کون اس کا ذمہ لیتا ہے؟', 'پوچھ اُن سے کونسا اُن میں اس کا ذمہ لیتا ہے [۲۳]', 'Ask them, which of them will stand surety for that!', 'Ask them which of them stands surety for that.'),
(5312, 68, 41, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'اَمۡ  لَہُمۡ  شُرَکَآءُ ۚۛ فَلۡیَاۡتُوۡا بِشُرَکَآئِہِمۡ اِنۡ  کَانُوۡا صٰدِقِیۡنَ ﴿۴۱﴾', 'کیا اس قول میں انکے کچھ شریک ہیں؟ اگر یہ سچے ہیں تو اپنے شریکوں کو لے آئیں۔', 'کیا انکے واسطے کوئی شریک ہیں پھر توچاہئے لے آئیں اپنے اپنے شریکوں کو اگر وہ سچے ہیں [۲۴]', 'Or have they \"partners\"? Then let them bring their \"partners\" if they are truthful!', 'Or do they have associate-gods (who have guaranteed safety for them)? Then, let them bring their associate-gods, if they are true.'),
(5313, 68, 42, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'یَوۡمَ  یُکۡشَفُ عَنۡ سَاقٍ وَّ  یُدۡعَوۡنَ  اِلَی السُّجُوۡدِ  فَلَا یَسۡتَطِیۡعُوۡنَ ﴿ۙ۴۲﴾', 'جس دن پنڈلی سے کپڑا اٹھا دیا جائے گا اور کفار سجدے کے لئے بلائے جائیں گے پھر وہ سجدہ نہ کر سکیں گے۔', 'جس دن کہ کھولی جائے پنڈلی اور وہ بلائے جائیں سجدہ کرنےکو پھر نہ کر سکیں [۲۵]', '(Remember) the Day when the Shin shall be laid bare (i.e. the Day of Resurrection) and they shall be called to prostrate (to Allah), but they (hypocrites) shall not be able to do so,', 'On the Day when the Shin will be exposed, and they will be called upon to prostrate themselves, they will not be able to.'),
(5314, 68, 43, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'خَاشِعَۃً  اَبۡصَارُہُمۡ تَرۡہَقُہُمۡ ذِلَّۃٌ ؕ وَ قَدۡ کَانُوۡا یُدۡعَوۡنَ  اِلَی السُّجُوۡدِ  وَ ہُمۡ سٰلِمُوۡنَ ﴿۴۳﴾', 'ان کی آنکھیں جھکی ہوئی ہوں گی اور ان پر ذلت چھا رہی ہو گی حالانکہ پہلے اس وقت سجدے کے لئے بلائے جاتے تھے۔ جبکہ وہ صحیح و سالم تھے۔', 'جھکی پڑتی ہوں گی اُنکی آنکھیں [۲۶] چڑھی آتی ہو گی اُن پر ذلت اور پہلے اُنکو بلاتے رہے سجدہ کرنے کو اور وہ تھے اچھے خاصے [۲۷]', 'Their eyes will be cast down, ignominy will cover them; they used to be called to prostrate (offer prayers), while they were healthy and good (in the life of the world, but they did not).', 'With their eyes downcast, they will be enveloped by ignominy. They used to be called upon to prostrate when they were healthy (but they did not.)'),
(5315, 68, 44, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'فَذَرۡنِیۡ  وَ مَنۡ یُّکَذِّبُ بِہٰذَا  الۡحَدِیۡثِ ؕ سَنَسۡتَدۡرِجُہُمۡ مِّنۡ حَیۡثُ لَا یَعۡلَمُوۡنَ ﴿ۙ۴۴﴾', 'تو مجھ کو اس کلام کے جھٹلانے والوں سے سمجھ لینے دو۔ ہم انکو آہستہ آہستہ ایسے طریق سے پکڑیں گے کہ انکو خبر بھی نہ ہو گی۔', 'اب چھوڑ دے مجھ کو اور اُنکو جو کہ جھٹلائیں اس بات کو اب ہم سیڑھی سیڑھی اتاریں گے اُنکو جہاں سے اُنکو پتہ بھی نہیں [۲۸]', 'Then leave Me Alone with such as belie this Quran. We shall punish them gradually from directions they perceive not.', 'So, leave Me alone with those who reject this discourse. We will draw them on little by little (towards Hell) from a way they do not know.'),
(5316, 68, 45, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'وَ اُمۡلِیۡ لَہُمۡ ؕ اِنَّ  کَیۡدِیۡ  مَتِیۡنٌ ﴿۴۵﴾', 'اور میں انکو مہلت دیئے جاتا ہوں میرا داؤں بڑا مضبوط ہے۔', 'اور انکو ڈھیل دیے جاتا ہوں بیشک میرا داؤ پکا ہے [۲۹]', 'And I will grant them a respite. Verily, My Plan is strong.', 'And I give them respite. Indeed, My plan is firm.'),
(5317, 68, 46, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'اَمۡ تَسۡـَٔلُہُمۡ  اَجۡرًا  فَہُمۡ  مِّنۡ مَّغۡرَمٍ مُّثۡقَلُوۡنَ ﴿ۚ۴۶﴾', 'اے نبی کیا تم ان سے کچھ معاوضہ مانگتے ہو کہ ان پر تاوان کا بوجھ پڑ رہا ہے۔', 'کیا تو مانگتا ہے اُن سے کچھ حق سو اُن پر تاوان کا بوجھ پڑ رہا ہے', 'Or is it that you (O Muhammad SAW) ask them a wage, so that they are heavily burdened with debt?', 'Is it that you ask them for a fee, due to which they are burdened with debt?'),
(5318, 68, 47, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'اَمۡ عِنۡدَہُمُ  الۡغَیۡبُ فَہُمۡ یَکۡتُبُوۡنَ ﴿۴۷﴾', 'یا انکے پاس غیب کی خبر ہے کہ اسے لکھتے جاتے ہیں۔', 'کیا اُنکے پاس خبر ہے غیب کی سو وہ لکھ لاتے ہیں [۳۰]', 'Or that the Ghaib (unseen here in this Verse it means Al-Lauh Al-Mahfooz) is in their hands, so that they can write it down?', 'Or do they have the (knowledge of the) Unseen, and they write it down?'),
(5319, 68, 48, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'فَاصۡبِرۡ  لِحُکۡمِ رَبِّکَ وَ لَا تَکُنۡ کَصَاحِبِ الۡحُوۡتِ ۘ اِذۡ  نَادٰی وَ ہُوَ مَکۡظُوۡمٌ ﴿ؕ۴۸﴾', 'سو اپنے پروردگار کے فیصلے کا انتظار کئے رہو اور مچھلی کا لقمہ ہونے والے یونس  کی طرح نہ ہونا کہ انہوں نے اپنے رب کو پکارا جبکہ وہ دل ہی دل میں گھٹ رہے تھے۔', 'اب تو استقلال سے راہ دیکھتا رہ اپنے رب کے حکم کی اور مت ہو جیسا وہ مچھلی والا [۳۱] جب پکارا اُس نے اور وہ غصہ میں بھرا تھا [۳۲]', 'So wait with patience for the Decision of your Lord, and be not like the Companion of the Fish, when he cried out (to Us) while he was in deep sorrow. (See the Quran, Verse 21:87).', 'So, remain patient with your Lord’s judgment, and be not like the Man of the Fish, he cried out while he was in anguish.'),
(5320, 68, 49, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'لَوۡ لَاۤ  اَنۡ  تَدٰرَکَہٗ  نِعۡمَۃٌ  مِّنۡ رَّبِّہٖ لَنُبِذَ بِالۡعَرَآءِ  وَ  ہُوَ  مَذۡمُوۡمٌ ﴿۴۹﴾', 'اگر انکے پروردگار کی مہربانی انکو نہ سنبھال لیتی تو وہ چٹیل میدان میں ڈال دیئے جاتے مذموم حالت میں۔', 'اگر نہ سنبھالتا اُسکو احسان تیرے رب کا تو پھینکا گیا ہی تھا چٹیل میدان میں الزام کھا کر [۳۳]', 'Had not a Grace from his Lord reached him, he would indeed have been (left in the stomach of the fish, but We forgave him), so he was cast off on the naked shore, while he was to be blamed.', 'Had not a favour from His Lord come to his help, he would have been cast in the wilderness in a reproachable state.'),
(5321, 68, 50, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'فَاجۡتَبٰہُ  رَبُّہٗ  فَجَعَلَہٗ  مِنَ الصّٰلِحِیۡنَ ﴿۵۰﴾', 'پھر انکے پروردگار نے ان کو برگزیدہ کر کے نیکوکاروں میں شامل کر لیا۔', 'پھر نوازا اُسکو اسکے رب نے پھر کر دیا اُسکو نیکوں میں [۳۴]', 'But his Lord chose him and made him of the righteous.', 'Then his Lord chose him, and made him one of the righteous.'),
(5322, 68, 51, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'وَ اِنۡ یَّکَادُ  الَّذِیۡنَ کَفَرُوۡا لَیُزۡلِقُوۡنَکَ بِاَبۡصَارِہِمۡ  لَمَّا سَمِعُوا الذِّکۡرَ وَ یَقُوۡلُوۡنَ  اِنَّہٗ  لَمَجۡنُوۡنٌ ﴿ۘ۵۱﴾', 'اور کافر جب یہ نصیحت کی کتاب سنتے ہیں تو یوں لگتے ہیں کہ تمکو اپنی نگاہوں سے پھسلا دیں گے اور کہتے ہیں کہ یہ تو دیوانہ ہے۔', 'اور منکر تو لگ ہی رہے ہیں کہ پھسلا دیں تجھ کو اپنی نگاہوں سے جب سنتے ہیں قرآن اور کہتے ہیں وہ تو باؤلا ہے [۳۵]', 'And verily, those who disbelieve would almost make you slip with their eyes through hatredness when they hear the Reminder (the Quran), and they say: \"Verily, he (Muhammad SAW) is a madman!\"', 'And indeed the disbelievers seem to trip you up with their glances when they hear the Reminder, and say, “He is a madman indeed.”'),
(5323, 68, 52, 2, 4, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القلم', 'وَ مَا ہُوَ  اِلَّا ذِکۡرٌ  لِّلۡعٰلَمِیۡنَ ﴿٪۵۲﴾', 'اور لوگو یہ قرآن تمام جہانوں کے لئے نصیحت ہے۔', 'اور یہ قرآن تو  یہی نصیحت ہے سارے جہان والوں کو [۳۶]', 'But it is nothing else than a Reminder to all the Alameen (mankind, jinns and all that exists).', 'And it is nothing else but a Reminder for all the worlds.'),
(5324, 69, 1, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'اَلۡحَآقَّۃُ ۙ﴿۱﴾', 'سچ مچ ہونے والی۔', 'وہ ثابت ہو چکنے والی', 'The Reality (i.e. the Day of Resurrection)!', 'The Imminent Happening!'),
(5325, 69, 2, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'مَا الۡحَآقَّۃُ ۚ﴿۲﴾', 'وہ سچ مچ ہونے والی کیا ہے؟', 'کیا ہے وہ ثابت ہو چکنے والی [۱]', 'What is the Reality?', 'What is the Imminent Happening?'),
(5326, 69, 3, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَ مَاۤ  اَدۡرٰىکَ مَا الۡحَآقَّۃُ ؕ﴿۳﴾', 'اور تمکو کیا معلوم ہے کہ وہ سچ مچ ہونے والی کیا ہے؟', 'اور تو نے کیا سوچا کیا ہے وہ ثابت ہو چکنے والی [۲]', 'And what will make you know what the Reality is?', 'And what can let you know what the Imminent happening is?'),
(5327, 69, 4, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'کَذَّبَتۡ ثَمُوۡدُ  وَ عَادٌۢ  بِالۡقَارِعَۃِ ﴿۴﴾', 'وہی کھڑکھڑانے والی جس کو ثمود اور عاد دونوں نے جھٹلایا۔', 'جھٹلایا ثمود اور عاد نے اُس کوٹ ڈالنے والی کو [۳]', 'Thamood and Ad people denied the Qariah (the striking Hour (of Judgement))!', 'Thamūd and ‘Ād had denied (the happening of) the Shocking Event (the Day of Judgment).'),
(5328, 69, 5, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'فَاَمَّا ثَمُوۡدُ  فَاُہۡلِکُوۡا بِالطَّاغِیَۃِ ﴿۵﴾', 'سو ثمود تو زبردست زلزلے سے ہلاک کر دیئے گئے۔', 'سو وہ جو ثمود تھے سو غارت کر دیے گئے اچھال کر [۴]', 'As for Thamood, they were destroyed by the awful cry!', 'As for Thamūd, they were destroyed by that (dreadful cry), which exceeded all limits.'),
(5329, 69, 6, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَ اَمَّا عَادٌ  فَاُہۡلِکُوۡا بِرِیۡحٍ صَرۡصَرٍ عَاتِیَۃٍ ۙ﴿۶﴾', 'رہے عاد تو انکو نہایت زوردار آندھی سے تباہ کر دیا گیا۔', 'اور وہ جو عاد تھے سو برباد ہوئے ٹھنڈی سناٹے کی ہوا سے نکلی جائے ہاتھوں سے [۵]', 'And as for Ad, they were destroyed by a furious violent wind;', 'And as for ‘Ād, they were destroyed by a violent windstorm'),
(5330, 69, 7, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'سَخَّرَہَا عَلَیۡہِمۡ  سَبۡعَ  لَیَالٍ وَّ ثَمٰنِیَۃَ اَیَّامٍ ۙ حُسُوۡمًا ۙ فَتَرَی الۡقَوۡمَ فِیۡہَا صَرۡعٰی ۙ کَاَنَّہُمۡ  اَعۡجَازُ نَخۡلٍ خَاوِیَۃٍ ۚ﴿۷﴾', 'اللہ نے اسکو سات رات اور آٹھ دن ان پر چلائے رکھا تو اے مخاطب تو ان لوگوں کو اس میں اس طرح گرے ہوئے دیکھتا جیسے کھجوروں کے کھوکھلے تنے۔', 'مقرر کر دیا اُسکو اُن پر سات رات اور آٹھ دن تک لگاتار پھر تو دیکھے کہ وہ لوگ اُس میں بچھڑ گئے گویا وہ ڈھنڈ ہیں کھجور کے کھوکھلے [۶]', 'Which Allah imposed on them for seven nights and eight days in succession, so that you could see men lying overthrown (destroyed), as if they were hollow trunks of date-palms!', 'that He imposed on them for seven nights and eight consecutive days; so you could see them thrown on the ground, as if they were trunks of hollow palm-trees.'),
(5331, 69, 8, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'فَہَلۡ  تَرٰی لَہُمۡ  مِّنۡۢ بَاقِیَۃٍ ﴿۸﴾', 'پھر کیا تو ان میں سے کسی کو بھی باقی دیکھتا ہے؟', 'پھر تو دیکھتا ہے کوئی اُن میں کا بچا [۷]', 'Do you see any remnants of them?', 'Now, do you see any remnant of them?'),
(5332, 69, 9, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَ جَآءَ  فِرۡعَوۡنُ  وَ مَنۡ  قَبۡلَہٗ وَ الۡمُؤۡتَفِکٰتُ بِالۡخَاطِئَۃِ ۚ﴿۹﴾', 'اور فرعون اور جو لوگ اس سے پہلے تھے اور وہ جو الٹی ہوئی بستیوں والے تھے سب گناہ کے کام کرتے تھے۔', 'اور آیا فرعون اور جو اُس سے پہلے تھے اور اُلٹ جانے والی بستیاں خطائیں کرتے ہوئے', 'And Firaun (Pharaoh), and those before him, and the cities overthrown (the towns of the people of (Lout (Lot)) committed sin,', 'And Fir‘aun (Pharaoh) and those before him and the overthrown towns came up with evil,'),
(5333, 69, 10, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'فَعَصَوۡا  رَسُوۡلَ  رَبِّہِمۡ  فَاَخَذَہُمۡ  اَخۡذَۃً  رَّابِیَۃً ﴿۱۰﴾', 'سو انہوں نے اپنے پروردگار کے پیغمبر کی نافرمانی کی تو اللہ نے بھی انکو بڑا سخت پکڑا۔', 'پھر حکم نہ مانا اپنے رب کے رسول کا پھر پکڑا اُنکو پکڑنا سخت [۸]', 'And they disobeyed their Lords Messenger, so He punished them with a strong punishment.', 'and they disobeyed the messenger of their Lord, so He seized them with an extremely severe seizure.'),
(5334, 69, 11, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'اِنَّا  لَمَّا طَغَا  الۡمَآءُ  حَمَلۡنٰکُمۡ  فِی الۡجَارِیَۃِ ﴿ۙ۱۱﴾', 'جب پانی طغیانی پر آیا تو ہم نے تم لوگوں کو کشتی میں سوار کر لیا۔', 'ہم نے جس وقت پانی اُبلا لاد لیا تم کو چلتی کشتی میں', 'Verily! When the water rose beyond its limits (Noohs (Noah) Flood), We carried you (mankind) in the floating (ship that was constructed by Nooh (Noah)).', 'When the water overflowed (in the Deluge of NūH), We let you (O mankind,) board the floating ship,'),
(5335, 69, 12, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'لِنَجۡعَلَہَا  لَکُمۡ  تَذۡکِرَۃً  وَّ تَعِیَہَاۤ  اُذُنٌ وَّاعِیَۃٌ ﴿۱۲﴾', 'تاکہ اسکو تمہارے لئے یادگار بنائیں اور یاد رکھنے والے کان اسے یاد رکھیں۔', 'تاکہ رکھیں اُسکو تمہاری یادگاری کے واسطے اور سینت کر رکھے اُسکو کان سینت کر رکھنے والا [۹]', 'That We might make it a remembrance for you, and the keen ear (person) may (hear and) understand it.', 'so that We make it a reminder for you, and so that a preserving ear (that hears their story) may preserve it.'),
(5336, 69, 13, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'فَاِذَا  نُفِخَ  فِی الصُّوۡرِ نَفۡخَۃٌ  وَّاحِدَۃٌ ﴿ۙ۱۳﴾', 'پھر جب صور میں ایک بار پھونک مار دی جائے گی۔', 'پھر جب پھونکا جائے صور میں ایک بار پھونکنا', 'Then when the Trumpet will be blown with one blowing (the first one),', 'Then, once the Trumpet will be blown for the first time,'),
(5337, 69, 14, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَّ حُمِلَتِ الۡاَرۡضُ وَ الۡجِبَالُ  فَدُکَّتَا دَکَّۃً   وَّاحِدَۃً ﴿ۙ۱۴﴾', 'اور زمین اور پہاڑ دونوں اٹھا لئے جائیں گے۔ پھر ایک بار ہی توڑ پھوڑ کر برابر کر دیئے جائیں گے۔', 'اور اٹھائی جائے زمین اورپہاڑ پھر کوٹ دیے جائیں ایک بار', 'And the earth and the mountains shall be removed from their places, and crushed with a single crushing,', 'and the earth and the mountains will be lifted and crushed into pieces with a single blow,'),
(5338, 69, 15, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'فَیَوۡمَئِذٍ وَّقَعَتِ الۡوَاقِعَۃُ ﴿ۙ۱۵﴾', 'تو اس روز ہو پڑنے والی یعنی قیامت ہو پڑے گی۔', 'پھر اُس دن ہو پڑے وہ ہو پڑنے والی [۱۰]', 'Then on that Day shall the (Great) Event befall,', 'then on that Day the Happening will happen,'),
(5339, 69, 16, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَ انۡشَقَّتِ السَّمَآءُ  فَہِیَ یَوۡمَئِذٍ وَّاہِیَۃٌ ﴿ۙ۱۶﴾', 'اور آسمان پھٹ جائے گا تو وہ اس دن کمزور ہو گا۔', 'اور پھٹ جائے آسمان پھر وہ اُس دن بکھر رہا ہے', 'And the heaven will split asunder, for that Day it (the heaven will be frail (weak), and torn up,', 'and the sky will burst apart, while it will have become frail on that day.'),
(5340, 69, 17, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَّ الۡمَلَکُ  عَلٰۤی  اَرۡجَآئِہَا ؕ وَ یَحۡمِلُ عَرۡشَ رَبِّکَ فَوۡقَہُمۡ یَوۡمَئِذٍ ثَمٰنِیَۃٌ ﴿ؕ۱۷﴾', 'اور فرشتے اسکے کناروں پر ہوں گے اور تمہارے پروردگار کے عرش کو اس روز آٹھ فرشتے اپنے اوپر اٹھائے ہوں گے۔', 'اور فرشتے ہوں گے اُسکے کناروں پر [۱۱] اور اٹھائیں گے تخت تیرے رب کا اپنے اوپر اُس دن آٹھ شخص [۱۲]', 'And the angels will be on its sides, and eight angels will, that Day, bear the Throne of your Lord above them.', 'And the angels will be on its borders. And on that Day, the Throne of your Lord will be carried above them by eight (angels).'),
(5341, 69, 18, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'یَوۡمَئِذٍ تُعۡرَضُوۡنَ  لَا تَخۡفٰی مِنۡکُمۡ خَافِیَۃٌ ﴿۱۸﴾', 'اس روز تم لوگ سب پیش کئے جاؤ گے اس طرح کہ تمہاری کوئی پوشیدہ بات چھپی نہ رہے گی۔', 'اُس دن سامنے کئے جاؤ گے چھپی نہ رہے گی تمہاری کوئی چھپی بات [۱۳]', 'That Day shall you be brought to Judgement, not a secret of you will be hidden.', 'On that day, you will be brought forward in a way that no secret of yours will remain secret.'),
(5342, 69, 19, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'فَاَمَّا مَنۡ اُوۡتِیَ کِتٰبَہٗ  بِیَمِیۡنِہٖ ۙ فَیَقُوۡلُ ہَآؤُمُ اقۡرَءُوۡا کِتٰبِیَہۡ ﴿ۚ۱۹﴾', 'اب جس کا اعمال نامہ اسکے داہنے ہاتھ میں دیا جائے گا وہ دوسروں سے کہے گا کہ لیجئے میرا نامہ اعمال پڑھیے۔', 'سو جس کو ملا اُس کا لکھا داہنے ہاتھ میں وہ کہتا ہے لیجیو پڑھیو میرا لکھا [۱۴]', 'Then as for him who will be given his Record in his right hand will say: \"Take, read my Record!', 'Now, as for him who is given his book in his right hand, he will say (to his colleagues), “Come here, read my book.'),
(5343, 69, 20, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'اِنِّیۡ  ظَنَنۡتُ  اَنِّیۡ مُلٰقٍ حِسَابِیَہۡ ﴿ۚ۲۰﴾', 'مجھے یقین تھا کہ مجھ کو میرا حساب کتاب ضرور ملے گا۔', 'میں نے خیال رکھا اس بات کا کہ مجھ کو ملے گا میرا حساب [۱۵]', '\"Surely, I did believe that I shall meet my Account!\"', 'I was sure that I would encounter my reckoning.”'),
(5344, 69, 21, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'فَہُوَ  فِیۡ  عِیۡشَۃٍ  رَّاضِیَۃٍ ﴿ۙ۲۱﴾', 'پس وہ شخص من مانے عیش میں ہو گا۔', 'سو وہ ہیں من مانتے گزران میں', 'So he shall be in a life, well-pleasing.', 'So he will be in a well-pleasing life'),
(5345, 69, 22, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'فِیۡ جَنَّۃٍ  عَالِیَۃٍ ﴿ۙ۲۲﴾', 'یعنی اونچے باغ میں۔', 'اونچے باغ میں', 'In a lofty Paradise,', 'in a lofty garden,'),
(5346, 69, 23, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'قُطُوۡفُہَا دَانِیَۃٌ ﴿۲۳﴾', 'جس کے میوے جھکے ہوئے ہوں گے۔', 'جسکے میوےجھکے پڑے ہیں [۱۶]', 'The fruits in bunches whereof will be low and near at hand.', 'the fruits of which will be close at hand.'),
(5347, 69, 24, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'کُلُوۡا وَ اشۡرَبُوۡا ہَنِیۡٓـئًۢا بِمَاۤ  اَسۡلَفۡتُمۡ فِی الۡاَیَّامِ الۡخَالِیَۃِ ﴿۲۴﴾', 'ان سے کہا جائے گا کہ جو اعمال تم ایّام گذشتہ میں آگے بھیج چکے ہو ان کے عوض مزے سے کھاؤ اور پیو۔', 'کھاؤ اور  پیو  رچ کر  بدلا  اُس کا جو آگے بھیج چکے ہو تم پہلے دنوں میں [۱۷]', 'Eat and drink at ease for that which you have sent on before you in days past!', '(It will be said to such people,) “Eat and drink with pleasure, as a reward for what you did in advance during past days.”'),
(5348, 69, 25, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَ اَمَّا مَنۡ  اُوۡتِیَ کِتٰبَہٗ بِشِمَالِہٖ ۬ۙ فَیَقُوۡلُ یٰلَیۡتَنِیۡ  لَمۡ  اُوۡتَ کِتٰبِیَہۡ  ﴿ۚ۲۵﴾', 'اور جس کا نامہ اعمال اس کے بائیں ہاتھ میں دیا جائےگا تو وہ کہے گا اے کاش مجھ کو میرا اعمال نامہ نہ دیا جاتا۔', 'اور جس کو ملا اُس کا لکھا بائیں ہاتھ میں وہ کہتا ہے کیا اچھا ہوتا جو مجھ کو نہ ملتا میرا لکھا', 'But as for him who will be given his Record in his left hand, will say: \"I wish that I had not been given my Record!', 'As for him who will be given his book in his left hand, he will say, “ Oh, would that I had not been given my book,'),
(5349, 69, 26, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَ  لَمۡ  اَدۡرِ  مَا حِسَابِیَہۡ ﴿ۚ۲۶﴾', 'اور مجھے معلوم نہ ہوتا کہ میرا حساب کیا ہے۔', 'اور مجھ کو خبر نہ ہوتی کہ کیا ہے حساب میرا', '\"And that I had never known, how my Account is?', 'and I had never known what my account is!'),
(5350, 69, 27, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'یٰلَیۡتَہَا کَانَتِ الۡقَاضِیَۃَ ﴿ۚ۲۷﴾', 'اے کاش موت میرا کام تمام کر چکی ہوتی۔', 'کسی طرح وہی موت ختم کر جاتی', '\"I wish, would that it had been my end (death)!', 'Oh, would that it (death) had been the end of the matter!'),
(5351, 69, 28, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'مَاۤ  اَغۡنٰی عَنِّیۡ  مَالِیَہۡ ﴿ۚ۲۸﴾', 'آج میرا مال میرے کچھ بھی کام نہ آیا۔', 'کچھ کام نہ آیا مجھ کو میرا مال', '\"My wealth has not availed me,', 'My wealth has not been of any use to me.'),
(5352, 69, 29, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'ہَلَکَ عَنِّیۡ  سُلۡطٰنِیَہۡ ﴿ۚ۲۹﴾', 'مجھ سے میرا اقتدار جاتا رہا۔', 'برباد ہوئی مجھ سے حکومت میری [۱۸]', '\"My power and arguments (to defend myself) have gone from me!\"', 'My power has gone from me for good.”'),
(5353, 69, 30, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'خُذُوۡہُ  فَغُلُّوۡہُ ﴿ۙ۳۰﴾', 'حکم ہو گا کہ اسے پکڑ لو اب اسے طوق پہنا دو۔', 'اُسکو پکڑو پھر طوق ڈالو', '(It will be said): \"Seize him and fetter him,', '(Then it will be said to angels,) “Seize him, then put a collar around his neck,'),
(5354, 69, 31, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'ثُمَّ  الۡجَحِیۡمَ  صَلُّوۡہُ ﴿ۙ۳۱﴾', 'پھر دوزخ کی آگ میں اسے جھونک دو۔', 'پھر آگ کے ڈھیر میں اسکو ڈالو', 'Then throw him in the blazing Fire.', 'and then, let him burn in the blazing fire.'),
(5355, 69, 32, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'ثُمَّ  فِیۡ سِلۡسِلَۃٍ  ذَرۡعُہَا سَبۡعُوۡنَ  ذِرَاعًا  فَاسۡلُکُوۡہُ ﴿ؕ۳۲﴾', 'پھر زنجیر سے جس کی لمبائی ستر گز ہے جکڑ دو۔', 'پھر ایک زنجیر میں جس کا طول ستر گز ہے اُسکو جکڑ دو [۱۹]', '\"Then fasten him with a chain whereof the length is seventy cubits!\"', 'Thereafter, fasten him with a chain the measure of which is seventy hands.”'),
(5356, 69, 33, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'اِنَّہٗ  کَانَ  لَا  یُؤۡمِنُ بِاللّٰہِ الۡعَظِیۡمِ ﴿ۙ۳۳﴾', 'یہ نہ تو اللہ عظمت والے پر ایمان لاتا تھا۔', 'وہ تھا کہ یقین نہ لاتا تھا اللہ پر جو سب سے بڑا', 'Verily, He used not to believe in Allah, the Most Great,', 'Indeed, he did not believe in Allah, the Almighty,'),
(5357, 69, 34, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَ لَا یَحُضُّ عَلٰی طَعَامِ الۡمِسۡکِیۡنِ ﴿ؕ۳۴﴾', 'اور نہ فقیر کے کھانا کھلانے کی ترغیب دیتا تھا۔', 'اور تاکید نہ کرتا تھا فقیر کے کھانے پر [۲۰]', 'And urged not on the feeding of AlMiskeen (the poor),', 'and did not persuade (others) to feed the needy.'),
(5358, 69, 35, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'فَلَیۡسَ لَہُ  الۡیَوۡمَ ہٰہُنَا حَمِیۡمٌ ﴿ۙ۳۵﴾', 'سو آج اس کا بھی یہاں کوئی دوست نہیں۔', 'سو کوئی نہیں آج اُس کا یہاں دوستدار [۲۱]', 'So no friend has he here this Day,', 'So, he has no friend here today,'),
(5359, 69, 36, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَّ لَا طَعَامٌ   اِلَّا مِنۡ غِسۡلِیۡنٍ ﴿ۙ۳۶﴾', 'اور نہ اسکے لئے کوئی کھانا ہے سوائے زخموں کے دھوون کے۔', 'اور نہ کچھ ملے کھانا مگر زخموں کا دھوون', 'Nor any food except filth from the washing of wounds,', 'nor any food except that which comes out from wounds when washing,'),
(5360, 69, 37, 1, 5, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'لَّا  یَاۡکُلُہٗۤ  اِلَّا الۡخَاطِـُٔوۡنَ ﴿٪۳۷﴾', 'جس کو گنہگاروں کے سوا کوئی نہیں کھائے گا۔', 'کوئی نہ کھائے اُسکو  مگر وہی گنہگار [۲۲]', 'None will eat except the Khatioon (sinners, disbelievers, polytheists, etc.).', 'which is eaten by none but the sinners.'),
(5361, 69, 38, 2, 6, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'فَلَاۤ  اُقۡسِمُ بِمَا  تُبۡصِرُوۡنَ ﴿ۙ۳۸﴾', 'سو میں ان چیزوں کی قسم کھاتا ہوں جو تمکو نظر آتی ہیں۔', 'سو قسم کھاتا ہوں اُن چیزوں کی جو دیکھتے ہو', 'So I swear by whatsoever you see,', 'I swear by what you see,'),
(5362, 69, 39, 2, 6, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَ مَا  لَا تُبۡصِرُوۡنَ ﴿ۙ۳۹﴾', 'اور انکی جو تمہیں نظر نہیں آتیں۔', 'اور جو چیزیں کہ تم نہیں دیکھتے', 'And by whatsoever you see not,', 'and what you do not see,'),
(5363, 69, 40, 2, 6, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'اِنَّہٗ  لَقَوۡلُ  رَسُوۡلٍ  کَرِیۡمٍ ﴿ۚۙ۴۰﴾', 'کہ یہ قرآن ایک معزز فرشتے کا پہنچایا ہوا کلام ہے۔', 'کہ کہا ہے ایک پیغام لانے والے سردار کا [۲۳]', 'That this is verily the word of an honoured Messenger (i.e. Jibrael (Gabriel) or Muhammad SAW which he has brought from Allah).', 'it is surely the speech of a noble Messenger, (that he conveys from Allah).');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(5364, 69, 41, 2, 6, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَّ مَا ہُوَ بِقَوۡلِ شَاعِرٍ ؕ قَلِیۡلًا  مَّا تُؤۡمِنُوۡنَ ﴿ۙ۴۱﴾', 'اور یہ کسی شاعر کا کلام نہیں۔ مگر تم لوگ بہت ہی کم ایمان لاتے ہو۔', 'اور نہیں ہے یہ کہا کسی شاعر کا تم تھوڑا یقین کرتے ہو [۲۴]', 'It is not the word of a poet, little is that you believe!', 'and it is not the speech of a poet, (but) little you believe,'),
(5365, 69, 42, 2, 6, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَ لَا بِقَوۡلِ کَاہِنٍ ؕ قَلِیۡلًا مَّا تَذَکَّرُوۡنَ ﴿ؕ۴۲﴾', 'اور نہ کسی کاہن کا قول ہے۔ لیکن تم لوگ بہت ہی کم غوروفکر کرتے ہو۔', 'اور نہیں ہے کہا پریوں والے کا تم بہت کم دھیان کرتے ہو [۲۵]', 'Nor is it the word of a soothsayer (or a foreteller), little is that you remember!', 'nor is it the speech of a soothsayer, (but) little you heed to the advice.'),
(5366, 69, 43, 2, 6, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'تَنۡزِیۡلٌ مِّنۡ رَّبِّ الۡعٰلَمِیۡنَ ﴿۴۳﴾', 'یہ رب العالمین کا اتارا ہوا ہے۔', 'یہ اتارا ہوا ہے جہان کے رب کا [۲۶]', 'This is the Revelation sent down from the Lord of the Alamin (mankind, jinns and all that exists).', 'It is a revelation from the Lord of the worlds.'),
(5367, 69, 44, 2, 6, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَ لَوۡ تَقَوَّلَ عَلَیۡنَا بَعۡضَ الۡاَقَاوِیۡلِ ﴿ۙ۴۴﴾', 'اور اگر یہ پیغمبر ہماری نسبت کوئی بات جھوٹ بنا لاتے۔', 'اور اگر یہ بنا لاتا ہم پر کوئی بات', 'And if he (Muhammad SAW) had forged a false saying concerning Us (Allah Ìá ÌáÇáå),', 'Had he (the prophet) forged some statements in Our name,'),
(5368, 69, 45, 2, 6, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'لَاَخَذۡنَا مِنۡہُ  بِالۡیَمِیۡنِ ﴿ۙ۴۵﴾', 'تو ہم ان کا داہنا ہاتھ پکڑ لیتے۔', 'تو ہم پکڑ لیتے اس کا داہنا ہاتھ', 'We surely should have seized him by his right hand (or with power and might),', 'We would have certainly seized him by the right hand,'),
(5369, 69, 46, 2, 6, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'ثُمَّ  لَقَطَعۡنَا مِنۡہُ  الۡوَتِیۡنَ ﴿۫ۖ۴۶﴾', 'پھر ان کی رگ گردن کاٹ ڈالتے۔', 'پھر کاٹ ڈالتے اُسکی گردن', 'And then certainly should have cut off his life artery (Aorta),', 'and then severed his life-artery,'),
(5370, 69, 47, 2, 6, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'فَمَا مِنۡکُمۡ  مِّنۡ اَحَدٍ عَنۡہُ حٰجِزِیۡنَ ﴿۴۷﴾', 'پھر تم میں سے کوئی ہمیں اس سے روکنے والا نہ ہوتا۔', 'پھر تم میں کوئی ایسا نہیں جو اُس سے بچا لے [۲۷]', 'And none of you could withhold Us from (punishing) him.', 'and none of you could have saved him from it.'),
(5371, 69, 48, 2, 6, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَ  اِنَّہٗ  لَتَذۡکِرَۃٌ  لِّلۡمُتَّقِیۡنَ ﴿۴۸﴾', 'اور یہ کتاب تو پرہیزگاروں کے لئے نصیحت ہے۔', 'اور یہ نصیحت ہے ڈرنے والوں کو', 'And verily, this Quran is a Reminder for the Muttaqoon (pious - see V.2:2).', 'It is infact a Reminder for the God-fearing.'),
(5372, 69, 49, 2, 6, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَ اِنَّا  لَنَعۡلَمُ  اَنَّ مِنۡکُمۡ مُّکَذِّبِیۡنَ ﴿۴۹﴾', 'اور ہم جانتے ہیں کہ تم میں سے بعض اس کو جھٹلانے والے ہیں۔', 'اور ہمکو معلوم ہے کہ تم میں بعضے جھٹلاتے ہیں', 'And verily, We know that there are some among you that belie (this Quran). (Tafsir At-Tabaree, Vol. 29, Page 68)', 'And, of course, We know that among you there are deniers.'),
(5373, 69, 50, 2, 6, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَ  اِنَّہٗ  لَحَسۡرَۃٌ  عَلَی الۡکٰفِرِیۡنَ ﴿۵۰﴾', 'نیز یہ کافروں کے لئے موجب حسرت ہے۔', 'اور وہ جو ہے پچتاوا ہے منکروں پر [۲۸]', 'And indeed it (this Quran) will be an anguish for the disbelievers (on the Day of Resurrection).', 'And surely, it is a cause of remorse for the disbelievers.'),
(5374, 69, 51, 2, 6, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'وَ  اِنَّہٗ  لَحَقُّ الۡیَقِیۡنِ ﴿۵۱﴾', 'اور کچھ شک نہیں کہ یہ یقین کرنے کے لائق ہے۔', 'اور وہ جو ہے یقین کرنے کے قابل ہے', 'And Verily, it (this Quran) is an absolute truth with certainty .', 'And it is surely an absolute truth.'),
(5375, 69, 52, 2, 6, 29, 'تَبٰرَکَ الَّذِیۡ ', ' الحاقہ', 'فَسَبِّحۡ  بِاسۡمِ رَبِّکَ الۡعَظِیۡمِ ﴿٪۵۲﴾', 'سو تم اپنے پروردگار عظیم کے نام کی تسبیح کرتے رہو۔', 'اب بول پاکی اپنے رب کے نام کی جو ہے سب سے بڑا [۲۹]', 'So glorify the Name of your Lord, the Most Great.', 'So, pronounce the purity of the name of your magnificent Lord.'),
(5376, 70, 1, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'سَاَلَ  سَآئِلٌۢ  بِعَذَابٍ  وَّاقِعٍ ۙ﴿۱﴾', 'ایک طلب کرنے والے نے عذاب طلب کیا جو نازل ہو کر رہے گا۔', 'مانگا ایک مانگنے والے نے عذاب پڑنے والا', 'A questioner asked concerning a torment about to befall', 'A demanding person has asked for the punishment that is going to befall'),
(5377, 70, 2, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'لِّلۡکٰفِرِیۡنَ لَیۡسَ لَہٗ  دَافِعٌ ۙ﴿۲﴾', 'یعنی کافروں پر اور کوئی اسکو ٹال نہ سکے گا۔', 'منکروں کے واسطے کوئی نہیں اُسکو ہٹانے والا [۱]', 'Upon the disbelievers, which none can avert,', 'the disbelievers; there is no one to avert it,'),
(5378, 70, 3, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'مِّنَ اللّٰہِ  ذِی الۡمَعَارِجِ ؕ﴿۳﴾', 'جو بلندیوں والے اللہ کی طرف سے نازل ہو گا۔', 'آئے اللہ کی طرف سے جو چڑھتے درجوں والا ہے [۲]', 'From Allah, the Lord of the ways of ascent.', '(and it will come) from Allah, the Lord of the stairways,'),
(5379, 70, 4, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'تَعۡرُجُ  الۡمَلٰٓئِکَۃُ  وَ الرُّوۡحُ  اِلَیۡہِ  فِیۡ یَوۡمٍ کَانَ مِقۡدَارُہٗ  خَمۡسِیۡنَ اَلۡفَ سَنَۃٍ ۚ﴿۴﴾', 'جسکی طرف روح القدس اور دوسرے فرشتے چڑھتے ہیں اس روز نازل ہو گا جس کا طول پچاس ہزار برس  ہو گا۔', 'چڑھیں گے اُسکی طرف فرشتے اور روح [۳] اُس دن میں جس کا لنباؤ پچاس ہزار برس ہے [۴]', 'The angels and the Rooh (Jibrael (Gabriel)) ascend to Him in a Day the measure whereof is fifty thousand years,', 'to whom ascend the angels and the Spirit in a day the length of which is fifty thousand years.'),
(5380, 70, 5, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'فَاصۡبِرۡ  صَبۡرًا  جَمِیۡلًا ﴿۵﴾', 'تو تم کافروں کی باتوں کو حوصلے کے ساتھ برداشت کرتے رہو۔', 'سو تو صبر کر بھلی طرح کا صبر کرنا [۵]', 'So be patient (O Muhammad SAW ), with a good patience.', 'So, observe patience, a good patience.'),
(5381, 70, 6, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'اِنَّہُمۡ  یَرَوۡنَہٗ  بَعِیۡدًا ۙ﴿۶﴾', 'لوگ اس دن کو دور سمجھتے ہیں۔', 'وہ دیکھتے ہیں اُسکو دور', 'Verily! They see it (the torment) afar off,', 'They see it far off,'),
(5382, 70, 7, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'وَّ  نَرٰىہُ  قَرِیۡبًا ؕ﴿۷﴾', 'جبکہ ہماری نظر میں وہ قریب ہے۔', 'اور ہم دیکھتے ہیں اُسکو نزدیک [۶]', 'But We see it (quite) near.', 'and We see it near.'),
(5383, 70, 8, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'یَوۡمَ  تَکُوۡنُ  السَّمَآءُ  کَالۡمُہۡلِ ۙ﴿۸﴾', 'جس دن آسمان ایسا ہو جائے گا جیسے پگھلا ہوا تانبا۔', 'جس دن ہو گا آسمان جیسے تانبا پگھلا ہوا [۷]', 'The Day that the sky will be like the boiling filth of oil, (or molten copper or silver or lead, etc.).', '(This punishment will befall) on the Day when the sky will be like dregs of oil,'),
(5384, 70, 9, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'وَ تَکُوۡنُ  الۡجِبَالُ کَالۡعِہۡنِ  ۙ﴿۹﴾', 'اور پہاڑ ایسے جیسے رنگین اون۔', 'اور ہوں گے پہاڑ جیسے اون رنگی ہوئی [۸]', 'And the mountains will be like flakes of wool,', 'and the mountains will be like dyed wool,'),
(5385, 70, 10, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'وَ لَا یَسۡـَٔلُ  حَمِیۡمٌ حَمِیۡمًا ﴿ۚۖ۱۰﴾', 'اور کوئی دوست کسی دوست کو نہ پوچھے گا۔', 'اور نہ پوچھے گا دوستدار دوستدار کو', 'And no friend will ask of a friend,', 'and no friend will ask about any friend,'),
(5386, 70, 11, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'یُّبَصَّرُوۡنَہُمۡ ؕ یَوَدُّ  الۡمُجۡرِمُ لَوۡ  یَفۡتَدِیۡ مِنۡ عَذَابِ یَوۡمِئِذٍۭ بِبَنِیۡہِ ﴿ۙ۱۱﴾', 'حالانکہ ایک دوسرے کو سامنے دیکھ رہے ہوں گے اس روز گنہگار چاہے گا کہ کسی طرح اس دن کے عذاب کے بدلے میں سب کچھ دیدے یعنی اپنے بیٹے۔', 'سب نظر آ جائیں گے اُنکو [۹] چاہے گا گنہگار کسی طرح چھڑوائی میں دے کر اُس دن کے عذاب سے اپنے بیٹے کو', 'Though they shall be made to see one another ((i.e. on the Day of Resurrection), there will be none but see his father, children and relatives, but he will neither speak to them nor will ask them for any help)), - the Mujrim, (criminal, sinner, disbeliever, etc.) would desire to ransom himself from the punishment of that Day by his children.', '(though) they will be made to see each other. A guilty person will desire that he may be able to ransom himself from the torment of that day even by his sons,'),
(5387, 70, 12, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'وَ صَاحِبَتِہٖ وَ اَخِیۡہِ ﴿ۙ۱۲﴾', 'اور اپنی بیوی اور اپنے بھائی۔', 'اور اپنی ساتھ والی کو اور اپنے بھائی کو', 'And his wife and his brother,', 'and his wife and his brother,'),
(5388, 70, 13, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'وَ فَصِیۡلَتِہِ الَّتِیۡ تُــٔۡوِیۡہِ ﴿ۙ۱۳﴾', 'اور اپنا خاندان جس میں وہ رہتا تھا۔', 'اور  اپنے گھرانے کو جس میں رہتا تھا', 'And his kindred who sheltered him,', 'and his kindred that sheltered him,'),
(5389, 70, 14, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'وَ مَنۡ  فِی الۡاَرۡضِ جَمِیۡعًا ۙ ثُمَّ  یُنۡجِیۡہِ ﴿ۙ۱۴﴾', 'اور جتنے آدمی زمین پر ہیں غرض سب کو دے ڈالے پھر اپنے آپکو عذاب سے چھڑا لے۔', 'اور جتنے زمین پر ہیں سب کو پھر اپنے آپ کو بچا لے', 'And all that are in the earth, so that it might save him .', 'and all those on earth, then he may redeem himself.'),
(5390, 70, 15, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'کَلَّا ؕ اِنَّہَا  لَظٰی ﴿ۙ۱۵﴾', 'لیکن ایسا ہرگز نہیں ہو گا وہ بھڑکتی ہوئی آگ ہے۔', 'ہر گز نہیں [۱۰] وہ تپتی ہوئی آگ ہے', 'By no means! Verily, it will be the Fire of Hell!', 'By no means! It is the flaming fire'),
(5391, 70, 16, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'نَزَّاعَۃً   لِّلشَّوٰی  ﴿ۚۖ۱۶﴾', 'کھال ادھیڑ کر کلیجہ نکال لینے والی۔', 'کھینچ لینے والی کلیجہ [۱۱]', 'Taking away (burning completely) the head skin!', 'that will pull out the skin of the scalp.'),
(5392, 70, 17, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'تَدۡعُوۡا  مَنۡ  اَدۡبَرَ  وَ تَوَلّٰی ﴿ۙ۱۷﴾', 'وہ ان لوگوں کو اپنی طرف بلائے گی جنہوں نے دین حق سے اعراض کیا اور منہ پھیر لیا۔', 'پکارتی ہے اُسکو جس نے پیٹھ پھیر لی', 'Calling: \"(O Kafir (O disbeliever in Allah, His angels, His Book, His Messengers, Day of Resurrection and in Al-Qadar (Divine Preordainments), O Mushrik (O polytheist, disbeliever in the Oneness of Allah)) (all) such as turn their backs and turn away their faces (from Faith) (picking and swallowing them up from that great gathering of mankind (on the Day of Resurrection) just as a bird picks up a food-grain from the earth with its beak and swallows it up) (Tafsir Al-Qurtubee, Vol. 18, Page 289)', 'It will call him who had turned his back and fled away (from the truth)'),
(5393, 70, 18, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'وَ  جَمَعَ   فَاَوۡعٰی ﴿۱۸﴾', 'اور مال جمع کیا پھر سینت سینت کر رکھا۔', 'اور پھر کر چلا گیا اور جوڑا اور سینت کر رکھا [۱۲]', 'And collect (wealth) and hide it (from spending it in the Cause of Allah).', 'and accumulated (wealth) and hoarded (it).'),
(5394, 70, 19, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'اِنَّ  الۡاِنۡسَانَ خُلِقَ ہَلُوۡعًا ﴿ۙ۱۹﴾', 'کچھ شک نہیں کہ انسان کم حوصلہ پیدا ہوا ہے۔', 'بیشک آدمی بنا ہے جی کا کچا', 'Verily, man (disbeliever) was created very impatient;', 'Indeed man is created weak in courage,'),
(5395, 70, 20, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'اِذَا مَسَّہُ  الشَّرُّ  جَزُوۡعًا ﴿ۙ۲۰﴾', 'جب اسے تکلیف پہنچتی ہے تو گھبرا اٹھتا ہے۔', 'جب پہنچے اُسکو برائی تو بے صبرا', 'Irritable (discontented) when evil touches him;', 'very upset when touched by evil,'),
(5396, 70, 21, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'وَّ  اِذَا مَسَّہُ  الۡخَیۡرُ  مَنُوۡعًا ﴿ۙ۲۱﴾', 'اور جب ملتا ہے اسکو مال تو بخیل بن جاتا ہے۔', 'اور جب پہنچے اُسکو بھلائی تو بے توفیقا [۱۳]', 'And niggardly when good touches him;-', 'and very niggard when visited by good (fortune),'),
(5397, 70, 22, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'اِلَّا  الۡمُصَلِّیۡنَ ﴿ۙ۲۲﴾', 'مگر نماز ادا کرنے والے۔', 'مگر وہ نمازی', 'Except those devoted to Salat (prayers)', 'except the performers of Salāh,'),
(5398, 70, 23, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'الَّذِیۡنَ ہُمۡ عَلٰی صَلَاتِہِمۡ   دَآئِمُوۡنَ  ﴿۪ۙ۲۳﴾', 'جو نماز کا التزام رکھتے اور ہمیشہ پڑھتے ہیں۔', 'جو اپنی نماز پر قائم ہیں [۱۴]', 'Those who remain constant in their Salat (prayers);', 'who are regular in their Salāh,'),
(5399, 70, 24, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'وَ الَّذِیۡنَ فِیۡۤ  اَمۡوَالِہِمۡ حَقٌّ مَّعۡلُوۡمٌ ﴿۪ۙ۲۴﴾', 'اور جنکے مال میں حصہ مقرر ہے۔', 'اور جنکے مال میں حصہ مقرر ہے', 'And those in whose wealth there is a known right,', 'and those in whose riches there is a specified right'),
(5400, 70, 25, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'لِّلسَّآئِلِ وَ الۡمَحۡرُوۡمِ ﴿۪ۙ۲۵﴾', 'یعنی مانگنے والے کا۔ اور نہ مانگنے والے کا۔', 'مانگنے والے اور ہارے ہوئے کا [۱۵]', 'For the beggar who asks, and for the unlucky who has lost his property and wealth, (and his means of living has been straitened);', 'for the one who asks and the one who is deprived,'),
(5401, 70, 26, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'وَ الَّذِیۡنَ یُصَدِّقُوۡنَ بِیَوۡمِ الدِّیۡنِ ﴿۪ۙ۲۶﴾', 'اور جو روز جزا کو سچ سمجھتے ہیں۔', 'اور جو یقین کرتے ہیں انصاف کے دن پر [۱۶]', 'And those who believe in the Day of Recompense,', 'and those who believe in the Day of Judgment as true,'),
(5402, 70, 27, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'وَ الَّذِیۡنَ ہُمۡ مِّنۡ عَذَابِ رَبِّہِمۡ مُّشۡفِقُوۡنَ ﴿ۚ۲۷﴾', 'اور جو اپنے پروردگار کے عذاب سے خوف رکھتے ہیں۔', 'اور جو لوگ کہ اپنے رب کے عذاب سے ڈرتے ہیں [۱۷]', 'And those who fear the torment of their Lord,', 'and those who are fearful of the torment of their Lord-'),
(5403, 70, 28, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'اِنَّ  عَذَابَ رَبِّہِمۡ غَیۡرُ  مَاۡمُوۡنٍ ﴿۲۸﴾', 'بیشک ان کے پروردگار کا عذاب ہے ہی ایسا کہ اس سے بے خوف نہ ہوا جائے۔', 'بیشک اُنکے رب کے عذاب سے کسی کو نڈر نہ ہونا چاہئے [۱۸]', 'Verily! The torment of their Lord is that before which none can feel secure,', '-Indeed the torment of their Lord is not something to be fearless from.-'),
(5404, 70, 29, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'وَ الَّذِیۡنَ ہُمۡ  لِفُرُوۡجِہِمۡ حٰفِظُوۡنَ ﴿ۙ۲۹﴾', 'اور جو اپنی شرمگاہوں کی حفاظت کرتے ہیں۔', 'اور جو اپنی شہوت کی جگہ کو تھامتے ہیں', 'And those who guard their chastity (i.e. private parts from illegal sexual acts) .', 'and those who guard their private parts,'),
(5405, 70, 30, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'اِلَّا عَلٰۤی  اَزۡوَاجِہِمۡ  اَوۡ مَا مَلَکَتۡ اَیۡمَانُہُمۡ  فَاِنَّہُمۡ  غَیۡرُ  مَلُوۡمِیۡنَ ﴿ۚ۳۰﴾', 'مگر اپنی بیویوں یا باندیوں سے کہ ان کے پاس جانے میں انہیں کچھ ملامت نہیں۔', 'مگر اپنی جورؤں سے یا اپنے ہاتھ کے مال سےسو  ان پر نہیں کچھ اُلاہنا', 'Except with their wives and the (women slaves and captives) whom their right hands possess, for (then) they are not to be blamed,', 'except from their wives and those (slave-girls) owned by their hands,- because they are not to be blamed,'),
(5406, 70, 31, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'فَمَنِ  ابۡتَغٰی وَرَآءَ ذٰلِکَ فَاُولٰٓئِکَ ہُمُ الۡعٰدُوۡنَ ﴿ۚ۳۱﴾', 'اور جو لوگ ان کے سوا اور طریقے ڈھونڈیں تو وہ حد سے نکل جانے والے ہیں۔', 'پھر جو کوئی ڈھونڈے اسکے سوائے سو  وہی ہیں حد سے بڑھنے والے [۱۹]', 'But whosoever seeks beyond that, then it is those who are trespassers.', 'but the one who seeks (sexual gratification) beyond that, then such people are the transgressors,-'),
(5407, 70, 32, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'وَ الَّذِیۡنَ ہُمۡ  لِاَمٰنٰتِہِمۡ وَ عَہۡدِہِمۡ رٰعُوۡنَ ﴿۪ۙ۳۲﴾', 'اور جو اپنی امانتوں اور اپنے عہدوپیمان کا پاس کرتے ہیں۔', 'اور جو لوگ کہ اپنی امانتوں اور اپنے قول کو نباہتے ہیں [۲۰]', 'And those who keep their trusts and covenants;', 'and those who are careful about their trusts and covenants,'),
(5408, 70, 33, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'وَ الَّذِیۡنَ ہُمۡ بِشَہٰدٰتِہِمۡ  قَآئِمُوۡنَ ﴿۪ۙ۳۳﴾', 'اور جو اپنی گواہیوں پر قائم رہتے ہیں۔', 'اور جو اپنی گواہیوں پر سیدھے ہیں [۲۱]', 'And those who stand firm in their testimonies;', 'and those who are upright in their testimonies,'),
(5409, 70, 34, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'وَ الَّذِیۡنَ ہُمۡ عَلٰی صَلَاتِہِمۡ یُحَافِظُوۡنَ ﴿ؕ۳۴﴾', 'اور جو اپنی نماز کی پابندی کرتے ہیں۔', 'اور جو اپنی نماز سے خبردار ہیں [۲۲]', 'And those who guard their Salat (prayers) well ,', 'and those who take due care of their Salāh .'),
(5410, 70, 35, 1, 7, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'اُولٰٓئِکَ فِیۡ جَنّٰتٍ  مُّکۡرَمُوۡنَ ﴿ؕ٪۳۵﴾', 'یہی لوگ جنتوں میں عزت و اکرام سے ہوں گے۔', 'وہی لوگ ہیں باغوں میں عزت سے [۲۳]', 'Such shall dwell in the Gardens (i.e. Paradise) honoured.', 'Those will be honoured in gardens (of Jannah ).'),
(5411, 70, 36, 2, 8, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'فَمَالِ الَّذِیۡنَ کَفَرُوۡا قِبَلَکَ مُہۡطِعِیۡنَ ﴿ۙ۳۶﴾', 'تو اے نبی ان کافروں کو کیا ہوا ہے کہ تمہاری طرف دوڑے چلے آتے ہیں۔', 'پھر کیا ہوا ہے منکروں کو تیری طرف دوڑتے ہوئے آتے ہیں', 'So what is the matter with those who disbelieve that they hasten to listen from you (O Muhammad SAW), in order to belie you and to mock at you, and at Allahs Book (this Quran).', 'So what has happened to those who disbelieve that they are rushing towards you'),
(5412, 70, 37, 2, 8, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'عَنِ الۡیَمِیۡنِ وَ عَنِ الشِّمَالِ عِزِیۡنَ ﴿۳۷﴾', 'دائیں بائیں سے گروہ گروہ ہو کر جمع ہوتے جاتے ہیں۔', 'داہنے سے اور بائیں سے غول کے غول', '(Sitting) in groups on the right and on the left (of you, O Muhammad SAW)?', 'from the right and from the left, in groups?'),
(5413, 70, 38, 2, 8, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'اَیَطۡمَعُ کُلُّ  امۡرِیًٔ  مِّنۡہُمۡ  اَنۡ یُّدۡخَلَ جَنَّۃَ  نَعِیۡمٍ ﴿ۙ۳۸﴾', 'کیا ان میں سے ہر شخص یہ امید رکھتا ہے کہ نعمت کے باغ میں داخل کیا جائے گا؟', 'کیا طمع رکھتا ہے ہر ایک شخص اُن میں کہ داخل ہو جائے نعمت کے باغ میں', 'Does every man of them hope to enter the Paradise of delight?', 'Does every one of them aspire to be admitted to the garden of bliss?'),
(5414, 70, 39, 2, 8, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'کَلَّا ؕ اِنَّا خَلَقۡنٰہُمۡ  مِّمَّا یَعۡلَمُوۡنَ ﴿۳۹﴾', 'ہرگز نہیں ہم نے ان کو اس چیز سے پیدا کیا ہے جسے یہ جانتے ہیں۔', 'ہرگز نہیں [۲۴] ہم نے اُنکو بنایا ہے جس سے وہ بھی جانتے ہیں [۲۵]', 'No, that is not like that! Verily, We have created them out of that which they know!', 'By no means! We have created them from what they know.'),
(5415, 70, 40, 2, 8, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'فَلَاۤ  اُقۡسِمُ بِرَبِّ الۡمَشٰرِقِ وَ الۡمَغٰرِبِ اِنَّا  لَقٰدِرُوۡنَ ﴿ۙ۴۰﴾', 'پس مشرقوں اور مغربوں کے مالک کی قسم کہ ہم طاقت رکھتے ہیں۔', 'سو میں قسم کھاتا ہوں مشرقوں اور مغربوں کے مالک کی [۲۶] تحقیق ہم کر سکتے ہیں', 'So I swear by the Lord of all (the three hundred and sixty (360)) points of sunrise and sunset in the east and the west that surely We are Able', 'So, I swear by the Lord of the points of sunrise and those of sunset, We are powerful'),
(5416, 70, 41, 2, 8, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'عَلٰۤی  اَنۡ  نُّبَدِّلَ خَیۡرًا مِّنۡہُمۡ ۙ وَ مَا نَحۡنُ بِمَسۡبُوۡقِیۡنَ ﴿۴۱﴾', 'یعنی اس بات پر  کہ ان سے بہتر لوگ بدل لائیں۔ اور ہم عاجز نہیں ہیں۔', 'کہ بدل کر لے آئیں اُن سے بہتر اور ہمارے قابو سے نکل نہ جائیں گے [۲۷]', 'To replace them by (others) better than them; and We are not to be outrun.', 'to bring those better than them in their place, and We are not to be frustrated.'),
(5417, 70, 42, 2, 8, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'فَذَرۡہُمۡ  یَخُوۡضُوۡا وَ یَلۡعَبُوۡا حَتّٰی یُلٰقُوۡا یَوۡمَہُمُ  الَّذِیۡ یُوۡعَدُوۡنَ ﴿ۙ۴۲﴾', 'تو اے پیغمبر انکو باطل میں پڑے رہنے اور کھیل لینے دو یہاں تک کہ جس دن کا ان سے وعدہ کیا جاتا ہے وہ انکے سامنے آ موجود ہو۔', 'سو چھوڑ دے اُنکو کہ باتیں بنائیں اور کھیلا کریں یہاں تک کہ مل جائیں اپنے اُس دن سے جس کا اُن سے وعدہ ہے [۲۸]', 'So leave them to plunge in vain talk and play about, until they meet their Day which they are promised.', 'So, leave them involved in pastime and play until they encounter their Day, which they are promised,'),
(5418, 70, 43, 2, 8, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'یَوۡمَ یَخۡرُجُوۡنَ  مِنَ الۡاَجۡدَاثِ سِرَاعًا کَاَنَّہُمۡ  اِلٰی نُصُبٍ یُّوۡفِضُوۡنَ ﴿ۙ۴۳﴾', 'اس دن یہ قبروں سے نکل کر اس طرح دوڑیں گے جیسے کسی مقابلے کے نشان کی طرف دوڑے جا رہے ہوں۔', 'جس دن نکل پڑیں گے قبروں سے دوڑتے ہوئے جیسے کسی نشانی پر دوڑتے جاتے ہیں [۲۹]', 'The Day when they will come out of the graves quickly as racing to a goal,', 'the Day they will come out of the graves quickly, as if they were rushing toward idols,'),
(5419, 70, 44, 2, 8, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المعارج', 'خَاشِعَۃً  اَبۡصَارُہُمۡ تَرۡہَقُہُمۡ  ذِلَّۃٌ ؕ ذٰلِکَ  الۡیَوۡمُ الَّذِیۡ کَانُوۡا یُوۡعَدُوۡنَ ﴿٪۴۴﴾', 'ان کی آنکھیں جھک رہی ہوں گی اور ذلت ان پر چھا رہی ہو گی۔ یہی وہ دن ہے جس کا ان سے وعدہ کیا جاتا تھا۔', 'جھکی ہوں گی اُنکی آنکھیں چڑھی آتی ہوگی اُن پر ذلت یہ ہے وہ دن جس کا  اُن سے وعدہ تھا [۳۰]', 'With their eyes lowered in fear and humility, ignominy covering them (all over)! That is the Day which they were promised!', 'with their eyes downcast, enveloped by ignominy. That is the Day, which they were being promised.'),
(5420, 71, 1, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'اِنَّاۤ   اَرۡسَلۡنَا  نُوۡحًا  اِلٰی  قَوۡمِہٖۤ  اَنۡ  اَنۡذِرۡ قَوۡمَکَ مِنۡ قَبۡلِ اَنۡ یَّاۡتِیَہُمۡ عَذَابٌ اَلِیۡمٌ ﴿۱﴾', 'ہم نے نوح  کو انکی قوم کی طرف بھیجا کہ پیشتر اسکے کہ ان پر درد دینے والا عذاب واقع ہو اپنی قوم کو خبردار کر دو۔', 'ہم نے بھیجا نوح کو اُسکی قوم کی طرف کہ ڈرا اپنی قوم کو اس سے پہلے کہ پہنچے اُن پر عذاب دردناک [۱]', 'Verily, We sent Nooh (Noah) to his people (Saying): \"Warn your people before there comes to them a painful torment.\"', 'We sent NūH to his people (and said to him): “Warn your people before a painful punishment comes to them.”'),
(5421, 71, 2, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'قَالَ یٰقَوۡمِ   اِنِّیۡ  لَکُمۡ نَذِیۡرٌ مُّبِیۡنٌ ۙ﴿۲﴾', 'انہوں نے کہا کہ بھائیو میں تمکو کھلے طور پر خبردار کرتا ہوں۔', 'بولا اے قوم میری میں تم کو ڈر سناتا ہوں کھول کر', 'He said: \"O my people! Verily, I am a plain warner to you,', 'He said, “O my people, I openly warn you'),
(5422, 71, 3, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'اَنِ اعۡبُدُوا اللّٰہَ وَ اتَّقُوۡہُ  وَ اَطِیۡعُوۡنِ ۙ﴿۳﴾', 'کہ اللہ کی عبادت کرو اور اس سے ڈرو اور میرا کہا مانو۔', 'کہ بندگی کرو اللہ کی اور اُس سے ڈرو اور میرا کہنا مانو [۲]', '\"That you should worship Allah (Alone), be dutiful to Him, and obey me,', 'that you must worship Allah, and fear Him, and obey me,'),
(5423, 71, 4, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'یَغۡفِرۡ لَکُمۡ مِّنۡ ذُنُوۡبِکُمۡ وَ یُؤَخِّرۡکُمۡ اِلٰۤی  اَجَلٍ مُّسَمًّی ؕ اِنَّ  اَجَلَ اللّٰہِ  اِذَا جَآءَ  لَا  یُؤَخَّرُ ۘ لَوۡ  کُنۡتُمۡ تَعۡلَمُوۡنَ ﴿۴﴾', 'وہ تمہارے گناہ بخش دے گا اور موت کے وقت مقرر تک تمکو مہلت عطا کرے گا۔ جب اللہ کا مقرر کیا ہوا وقت آ جاتا ہے تو تاخیر نہیں کیجاتی۔ کاش تم جانتے ہوتے۔', 'تاکہ بخشے وہ تم کو کچھ گناہ تمہارے اور ڈھیل دے تم کو ایک مقرر  وعدہ تک [۳] وہ وعدہ جو کیا ہے اللہ نے جب آ پہنچے گا اُسکو ڈھیل نہ ہو گی [۴] اگر تمکو سمجھ ہے [۵]', '\"He (Allah) will forgive you of your sins and respite you to an appointed term. Verily, the term of Allah when it comes, cannot be delayed, if you but knew.\"', 'and Allah will forgive you your sins, and will respite you to an appointed term. Indeed when Allah’s term comes, it is not deferred, if you only know!”'),
(5424, 71, 5, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'قَالَ  رَبِّ  اِنِّیۡ  دَعَوۡتُ قَوۡمِیۡ لَیۡلًا وَّ نَہَارًا ۙ﴿۵﴾', 'جب لوگوں نے نہ مانا تو نوح  نے اللہ سے عرض کی کہ پروردگار میں اپنی قوم کو رات دن بلاتا رہا۔', 'بولا اے رب میں بلاتا رہا اپنی قوم کو رات اور دن', 'He said: \"O my Lord! Verily, I have called my people night and day (i.e. secretly and openly to accept the doctrine of Islamic Monotheism) ,', 'He said, “My Lord, I have called my people night and day,'),
(5425, 71, 6, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'فَلَمۡ   یَزِدۡہُمۡ دُعَآءِیۡۤ   اِلَّا  فِرَارًا ﴿۶﴾', 'لیکن میرے بلانے سے وہ اور زیادہ گریز کرتے رہے۔', 'پھرمیرے بلانے سے اور زیادہ بھاگنے لگے [۶]', '\"But all my calling added nothing but to (their) flight (from the truth).', 'but my call added only to their flight (from the truth).'),
(5426, 71, 7, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'وَ  اِنِّیۡ کُلَّمَا دَعَوۡتُہُمۡ  لِتَغۡفِرَ لَہُمۡ جَعَلُوۡۤا  اَصَابِعَہُمۡ  فِیۡۤ  اٰذَانِہِمۡ وَ اسۡتَغۡشَوۡا ثِیَابَہُمۡ وَ اَصَرُّوۡا وَ اسۡتَکۡبَرُوا اسۡتِکۡبَارًا ۚ﴿۷﴾', 'جب جب میں نے انکو بلایا کہ توبہ کریں اور تو انکو معاف فرمائے تو انہوں نے اپنے کانوں میں انگلیاں دے لیں اور اپنے اوپر کپڑے اوڑھ لئے اور اڑ گئے اور خوب تکبر کرنے لگے۔', 'اور میں نے جب کبھی اُنکو بلایا تاکہ تو اُنکو بخشے ڈالنے لگے انگلیاں اپنے کانوں میں [۷] اور لپیٹنے لگے اپنے اوپر کپڑے [۸] اور ضد کی اور غرور کیا بڑا غرور [۹]', '\"And verily! Every time I called unto them that You might forgive them, they thrust their fingers into their ears, covered themselves up with their garments, and persisted (in their refusal), and magnified themselves in pride.', 'Whenever I called them, so that You might forgive them, they put their fingers into their ears, and wrapped their clothes around themselves, and grew obstinate, and waxed proud in extreme arrogance.'),
(5427, 71, 8, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'ثُمَّ   اِنِّیۡ  دَعَوۡتُہُمۡ  جِہَارًا ۙ﴿۸﴾', 'پھر میں انکو بلند آواز سے بھی بلاتا رہا۔', 'پھر میں نے اُنکو بلایا بر ملا [۱۰]', '\"Then verily, I called to them openly (aloud);', 'Then I called them loudly,'),
(5428, 71, 9, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'ثُمَّ  اِنِّیۡۤ  اَعۡلَنۡتُ لَہُمۡ وَ اَسۡرَرۡتُ لَہُمۡ اِسۡرَارًا ۙ﴿۹﴾', 'پھر علانیہ بھی اور رازداری سے بھی سمجھاتا رہا۔', 'پھر میں نے اُنکو کھول کر کہا اور چھپ کر کہا چپکے سے [۱۱]', '\"Then verily, I proclaimed to them in public, and I have appealed to them in private,', 'and then I spoke to them in public and spoke to them in private.'),
(5429, 71, 10, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'فَقُلۡتُ اسۡتَغۡفِرُوۡا رَبَّکُمۡ ؕ اِنَّہٗ کَانَ غَفَّارًا ﴿ۙ۱۰﴾', 'پھر میں نے کہا کہ اپنے پروردگار سے معافی مانگو کہ وہ بڑا معاف کرنے والا ہے۔', 'تو میں نے کہا گناہ بخشواؤ اپنے رب سے بیشک وہ ہے بخشنے والا [۱۲]', '\"I said (to them): Ask forgiveness from your Lord; Verily, He is Oft-Forgiving;', 'So I said, ‘Pray to your Lord for your forgiveness,- Indeed He is Very-Forgiving, -'),
(5430, 71, 11, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'یُّرۡسِلِ السَّمَآءَ عَلَیۡکُمۡ  مِّدۡرَارًا ﴿ۙ۱۱﴾', 'وہ تم پر آسمان سے موسلا دھار مینہ برسائے گا۔', 'چھوڑ دے گا آسمان کی تم پر دھاریں', 'He will send rain to you in abundance;', 'and He will cause the heavens to rain upon you in abundance,'),
(5431, 71, 12, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'وَّ یُمۡدِدۡکُمۡ  بِاَمۡوَالٍ وَّ بَنِیۡنَ وَ یَجۡعَلۡ لَّکُمۡ  جَنّٰتٍ وَّ یَجۡعَلۡ لَّکُمۡ  اَنۡہٰرًا ﴿ؕ۱۲﴾', 'اور تمہارے مال اور بیٹوں میں اضافہ کرے گا اور تمہیں باغ عطا کرے گا اور ان میں تمہارے لئے نہریں بہا دے گا۔', 'اور بڑھا دے گا تم کومال اور بیٹوں سے اور بنا دے گا تمہارے واسطے باغ اور بنا دے گا تمہارے لئے نہریں [۱۳]', 'And give you increase in wealth and children, and bestow on you gardens and bestow on you rivers. \"', 'and will help you with riches and sons, and will cause gardens to grow for you, and cause rivers to flow for you.'),
(5432, 71, 13, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'مَا  لَکُمۡ لَا تَرۡجُوۡنَ لِلّٰہِ  وَقَارًا  ﴿ۚ۱۳﴾', 'تمکو کیا ہوا ہے کہ تم اللہ کی عظمت کا اعتقاد نہیں رکھتے۔', 'کیا ہوا ہے تم کو کیوں نہیں امید رکھتے  اللہ سے بڑائی کی [۱۴]', 'What is the matter with you, (that you fear not Allah (His punishment), and) you hope not for reward (from Allah or you believe not in His Oneness).', 'What has happened to you that you do not appreciate the Majesty of Allah,'),
(5433, 71, 14, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'وَ  قَدۡ خَلَقَکُمۡ   اَطۡوَارًا ﴿۱۴﴾', 'حالانکہ اس نے تمکو طرح طرح کی حالتوں میں پیدا کیا ہے۔', 'اور اُسی نے بنایا تمکو طرح طرح سے [۱۵]', 'While He has created you in (different) stages (i.e. first Nutfah, then Alaqah and then Mudghah, see (VV.23:13,14) the Quran).', 'while He has created you in different phases?'),
(5434, 71, 15, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'اَلَمۡ تَرَوۡا کَیۡفَ خَلَقَ اللّٰہُ  سَبۡعَ سَمٰوٰتٍ طِبَاقًا ﴿ۙ۱۵﴾', 'کیا تم نے نہیں دیکھا کہ اللہ نے سات آسمان کیسے اوپر تلے بنائے ہیں۔', 'کیا تم نے نہیں دیکھا کیسے بنائے اللہ نے سات آسمان تہہ پر تہہ [۱۶]', 'See you not how Allah has created the seven heavens one above another,', 'Did you not see how Allah has created seven heavens one upon another,'),
(5435, 71, 16, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'وَّ جَعَلَ الۡقَمَرَ فِیۡہِنَّ  نُوۡرًا وَّ جَعَلَ الشَّمۡسَ سِرَاجًا ﴿۱۶﴾', 'اور چاند کو ان میں روشن بنایا ہے اور سورج کو چراغ بنا دیا ہے۔', 'اور رکھا چاند کو اُن میں اجالا اور رکھا سورج کو چراغ جلتا ہوا [۱۷]', 'And has made the moon a light therein, and made the sun a lamp?', 'and has made the moon a light therein, and made the sun a lamp?'),
(5436, 71, 17, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'وَ اللّٰہُ  اَنۡۢبَتَکُمۡ  مِّنَ الۡاَرۡضِ نَبَاتًا ﴿ۙ۱۷﴾', 'اور اللہ ہی نے تمکو زمین سے ایک خاص طرح سے پیدا کیا ہے۔', 'اور اللہ نے اگایا تمکو زمین سے جما کر [۱۸]', 'And Allah has brought you forth from the (dust of) earth. (Tafsir At-Tabaree, Vol.29, Page 97).', 'And Allah has caused you to grow well out of the earth,'),
(5437, 71, 18, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'ثُمَّ یُعِیۡدُکُمۡ فِیۡہَا وَ یُخۡرِجُکُمۡ اِخۡرَاجًا ﴿۱۸﴾', 'پھر اسی میں تمہیں وہ لوٹا دے گا اور اسی سے تمکو نکال کھڑا کرے گا۔', 'پھر مکرر ڈالے گا تم کو اس میں اور نکالے گا تم کو باہر [۱۹]', 'Afterwards He will return you into it (the earth), and bring you forth (again on the Day of Resurrection)?', 'then He will send you back into it, and will bring you forth once again.'),
(5438, 71, 19, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'وَ اللّٰہُ  جَعَلَ  لَکُمُ الۡاَرۡضَ بِسَاطًا ﴿ۙ۱۹﴾', 'اور اللہ ہی نے زمین کو تمہارے لئے فرش بنایا۔', 'اور اللہ نے بنا دیا تمہارے لئے زمین کو بچھونا', 'And Allah has made for you the earth wide spread (an expanse).', 'And Allah has made the earth a spread for you,'),
(5439, 71, 20, 1, 9, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'لِّتَسۡلُکُوۡا مِنۡہَا سُبُلًا  فِجَاجًا ﴿٪۲۰﴾', 'تاکہ اسکے بڑے بڑے کشادہ رستوں میں چلو پھرو۔', 'تاکہ چلو اُس میں کشادہ رستے [۲۰]', 'That you may go about therein in broad roads.', 'so that you may go about its broad ways.’”'),
(5440, 71, 21, 2, 10, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'قَالَ نُوۡحٌ  رَّبِّ اِنَّہُمۡ عَصَوۡنِیۡ وَ اتَّبَعُوۡا مَنۡ لَّمۡ  یَزِدۡہُ  مَالُہٗ وَ وَلَدُہٗۤ  اِلَّا خَسَارًا ﴿ۚ۲۱﴾', 'آخر میں نوح  نے عرض کی کہ میرے پروردگار! یہ لوگ میرے کہنے پر نہیں چلے اور ایسوں کے تابع ہوئے ہیں جنکو ان کے مال اور اولاد نے نقصان کے سوا کچھ فائدہ نہ دیا۔', 'کہا نوح نے اے رب میرے انہوں نے میرا کہا نہ مانا اور مانا ایسے کا جسکو اُسکے مال اور اولاد سے اور زیادہ ہو ٹوٹا [۲۱]', 'Nooh (Noah) said: \"My Lord! They have disobeyed me, and followed one whose wealth and children give him no increase but only loss.', 'And said NūH, “My Lord, they disobeyed me, and followed him whose wealth and children added nothing to him but loss,'),
(5441, 71, 22, 2, 10, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'وَ مَکَرُوۡا مَکۡرًا کُبَّارًا ﴿ۚ۲۲﴾', 'اور وہ بڑی بڑی چالیں چلے۔', 'اور داؤ کیا ہے بڑ اداؤ [۲۲]', '\"And they have plotted a mighty plot.', 'and they devised a mighty plot,'),
(5442, 71, 23, 2, 10, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'وَ قَالُوۡا لَا تَذَرُنَّ  اٰلِہَتَکُمۡ وَ لَا تَذَرُنَّ وَدًّا وَّ لَا سُوَاعًا ۬ۙ وَّ لَا یَغُوۡثَ وَ یَعُوۡقَ وَ نَسۡرًا ﴿ۚ۲۳﴾', 'اور کہنے لگے کہ اپنے معبودوں کو ہرگز نہ چھوڑنا اور ودّ اور سواع اور یغوث اور یعوق اور نسر کو کبھی نہ چھوڑنا۔', 'اور بولے ہرگز نہ چھوڑیو اپنے معبودوں کو [۲۳] اور نہ چھوڑیو ودّ کو اور نہ سواع کو اور نہ یغوث کو اور نہ یعوق اور نسر کو [۲۴]', '\"And they have said: You shall not leave your gods, nor shall you leave Wadd, nor Suwa, nor Yaghooth, nor Yaooq, nor Nasr (names of the idols);', 'and said (to their people), “Never forsake your gods, and never forsake Wadd, nor Suwā‘, nor Yaghūth and Ya‘ūq and Nasr.'),
(5443, 71, 24, 2, 10, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'وَ قَدۡ  اَضَلُّوۡا کَثِیۡرًا ۬ۚ وَ لَا تَزِدِ الظّٰلِمِیۡنَ  اِلَّا ضَلٰلًا ﴿۲۴﴾', 'اور اے پروردگار انہوں نے بہت لوگوں کو گمراہ کر دیا ہے اور تو ان ظالموں کو اور زیادہ گمراہ کر دے۔', 'اور بہکا دیا بہتوں کو اور  تو نہ زیادہ کرنا (کریو)  بے انصافوں کو مگر بھٹکنا [۲۵]', '\"And indeed they have led many astray. And (O Allah): Grant no increase to the Zalimoon (polytheists, wrong-doers, and disbelievers, etc.) save error. \"', 'And they have led many astray. And (O my Lord,) let not the wrongdoers progress in anything but deviation from the right path.”'),
(5444, 71, 25, 2, 10, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'مِمَّا خَطِیۡٓــٰٔتِہِمۡ  اُغۡرِقُوۡا فَاُدۡخِلُوۡا نَارًا ۬ۙ  فَلَمۡ یَجِدُوۡا  لَہُمۡ  مِّنۡ دُوۡنِ اللّٰہِ اَنۡصَارًا ﴿۲۵﴾', 'آخر وہ اپنے گناہوں کے سبب پہلے غرقاب کر دیئے گئے پھر آگ میں ڈال دیئے گئے۔ تو انہوں نے اللہ کے سوا کسی کو اپنا مددگار نہ پایا۔', 'کچھ وہ اپنے گناہوں سے دبائے گئے  پھر ڈالے گئے آگ میں [۲۶] پھر نہ پائے اپنے واسطے انہوں نے اللہ کے سوائے کوئی مددگار [۲۷]', 'Because of their sins they were drowned, then were made to enter the Fire, and they found none to help them instead of Allah.', 'Because of their sins they were drowned, and then admitted into the Fire. So they found no helpers for them besides Allah.'),
(5445, 71, 26, 2, 10, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'وَ قَالَ نُوۡحٌ رَّبِّ لَا تَذَرۡ عَلَی الۡاَرۡضِ مِنَ  الۡکٰفِرِیۡنَ دَیَّارًا ﴿۲۶﴾', 'اور پھر نوح  نے یہ دعا کی کہ میرے پروردگار ان کافروں میں سے کسی کو زمین پر بستا نہ رہنے دے۔', 'اور کہا نوح نے اے رب نہ چھوڑیو زمین پر منکروں کا ایک گھر بسنے والا', 'And Nooh (Noah) said: \"My Lord! Leave not one of the disbelievers on the earth!', 'And said NūH, “My Lord, do not leave on earth even a single inhabitant (surviving) out of the disbelievers.'),
(5446, 71, 27, 2, 10, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'اِنَّکَ اِنۡ تَذَرۡہُمۡ یُضِلُّوۡا عِبَادَکَ وَ لَا یَلِدُوۡۤا  اِلَّا  فَاجِرًا کَفَّارًا ﴿۲۷﴾', 'اگر تو انکو رہنے دے گا تو یہ تیرے بندوں کو گمراہ کریں گے اور ان سے جو اولاد ہو گی وہ بھی بدکار اور ناشکری ہو گی۔', 'مقرر اگر تو چھوڑ دے گا اُنکو بہکائیں گے تیرے بندوں کو اور جو جنیں گے سو ڈھیٹھ حق کا منکر [۲۸]', '\"If You leave them, they will mislead Your slaves, and they will beget none but wicked disbelievers.\"', 'If You leave them (surviving), they will lead Your servants astray, and will beget none but a sinful disbeliever.'),
(5447, 71, 28, 2, 10, 29, 'تَبٰرَکَ الَّذِیۡ ', 'نُوح', 'رَبِّ اغۡفِرۡ لِیۡ  وَ لِوَالِدَیَّ  وَ لِمَنۡ دَخَلَ بَیۡتِیَ  مُؤۡمِنًا وَّ لِلۡمُؤۡمِنِیۡنَ وَ الۡمُؤۡمِنٰتِ ؕ وَ لَا تَزِدِ الظّٰلِمِیۡنَ  اِلَّا تَبَارًا ﴿٪۲۸﴾', 'اے میرے پروردگار مجھ کو اور میرے ماں باپ کو اور جو ایمان لا کر میرے گھر میں آئے اسکو اور تمام ایمان والے مردوں اور ایمان والی عورتوں کو معاف فرما۔ اور ظالم لوگوں کے لئے اور زیادہ تباہی بڑھا۔', 'اے رب معاف کر مجھ کو اور میرے ماں باپ کو اور جو آئے میرے گھر میں ایماندار اور سب ایمان والے مردوں کو اور عورتوں کو [۲۹] اور گنہگاروں پر بڑھتا رکھ یہی برباد ہونا', '\"My Lord! Forgive me, and my parents, and him who enters my home as a believer, and all the believing men and women. And to the Zalimoon (polytheists, wrong-doers, and disbelievers, etc.) grant You no increase but destruction!\"', 'My Lord, grant pardon to me, and to my parents, and to everyone who enters my home as a believer, and to all the believing men and believing women, and do not increase the wrongdoers but in ruin.'),
(5448, 72, 1, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'قُلۡ  اُوۡحِیَ  اِلَیَّ  اَنَّہُ  اسۡتَمَعَ  نَفَرٌ مِّنَ الۡجِنِّ فَقَالُوۡۤا  اِنَّا سَمِعۡنَا قُرۡاٰنًا عَجَبًا  ۙ﴿۱﴾', 'اے پیغمبر ﷺ لوگوں سے کہدو کہ میرے پاس وحی آئی ہے کہ جنوں کی ایک جماعت نے اس کتاب کو سنا تو کہنے لگے کہ ہم نے ایک عجیب قرآن سنا۔', 'تو کہہ مجھ کو حکم آیا کہ سن گئے کتنے لوگ جنوں کے [۱] پھر کہنے لگےہم نے سنا ہے ایک قرآن عجیب', 'Say (O Muhammad SAW): \"It has been revealed to me that a group (from three to ten in number) of jinns listened (to this Quran). They said: Verily! We have heard a wonderful Recital (this Quran)!', 'Say, “It has been revealed to me that a group from Jinn has listened (to the Qur’ān), and said (to their people), ‘Indeed we have heard an amazing Recital (Qur’ān)'),
(5449, 72, 2, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'یَّہۡدِیۡۤ  اِلَی الرُّشۡدِ فَاٰمَنَّا بِہٖ ؕ وَ لَنۡ نُّشۡرِکَ بِرَبِّنَاۤ   اَحَدًا ۙ﴿۲﴾', 'جو بھلائی کا رستہ بتاتا ہے سو ہم اس پر ایمان لے آئے اور ہم اپنے پروردگار کے ساتھ کسی کو شریک نہیں بنائیں گے۔', 'کہ سمجھاتا ہے نیک راہ سو ہم بھی اُس پر یقین لا۴ئے اور ہر گز نہ شریک بتلائیں گے ہم اپنے رب کا کسی کو [۲]', 'It guides to the Right Path, and we have believed therein, and we shall never join (in worship) anything with our Lord (Allah).', 'that guides to the right way, so we have believed in it, and we will never associate a partner with our Lord.’'),
(5450, 72, 3, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'وَّ اَنَّہٗ  تَعٰلٰی جَدُّ  رَبِّنَا مَا اتَّخَذَ صَاحِبَۃً وَّ لَا وَلَدًا ۙ﴿۳﴾', 'اور یہ کہ ہمارے پروردگار کی شان بہت بلند ہے وہ نہ بیوی رکھتا ہے نہ اولاد۔', 'اور یہ کو اونچی ہے شان ہمارے رب کی نہیں رکھی اُس نے جورو نہ بیٹا [۳]', 'And exalted be the Majesty of our Lord, He has taken neither a wife, nor a son (or offspring or children).', 'and (then the Jinns started talking to each other) that exalted is the Glory of our Lord; He has taken neither a wife, nor a son,'),
(5451, 72, 4, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'وَّ اَنَّہٗ  کَانَ یَقُوۡلُ سَفِیۡہُنَا عَلَی اللّٰہِ شَطَطًا ۙ﴿۴﴾', 'اور یہ کہ ہم میں سے کوئی کوئی بیوقوف اللہ کے بارے میں جھوٹ گھڑتا ہے۔', 'اور یہ کہ ہم میں کا بیوقوف اللہ پر بڑھا کر باتیں کہا کرتا تھا [۴]', 'And that the foolish among us (i.e. Iblees (Satan) or the polytheists amongst the jinns) used to utter against Allah that which was wrong and not right.', 'and that the fools among us used to attribute to Allah extremely absurd things,'),
(5452, 72, 5, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'وَّ اَنَّا ظَنَنَّاۤ  اَنۡ  لَّنۡ تَقُوۡلَ الۡاِنۡسُ وَ الۡجِنُّ عَلَی اللّٰہِ  کَذِبًا ۙ﴿۵﴾', 'اور ہمارا یہ خیال تھا کہ انسان اور جن اللہ کی نسبت جھوٹ نہیں بولیں گے۔', 'اور یہ کہ ہم کو خیال تھا کہ ہرگز نہ بولیں گے آدمی اور جن اللہ پر جھوٹ [۵]', 'And verily, we thought that men and jinns would not utter a lie against Allah.', 'and that we thought that the humans and the Jinn would never tell a lie about Allah, (therefore, we had followed them in shirk under this impression),'),
(5453, 72, 6, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'وَّ  اَنَّہٗ کَانَ رِجَالٌ مِّنَ الۡاِنۡسِ یَعُوۡذُوۡنَ بِرِجَالٍ  مِّنَ  الۡجِنِّ فَزَادُوۡہُمۡ  رَہَقًا ۙ﴿۶﴾', 'اور یہ کہ بعض بنی آدم بعض جنات کی پناہ لیا کرتے تھے تو اس سے انکی سرکشی اور بڑھ گئ تھی۔', 'اور یہ کہ تھے کتنے مرد آدمیوں میں کے پناہ پکڑتے تھے کتنے مردوں کی جنوں میں کے پھر تو وہ اور زیادہ سر چڑھنے لگے [۶]', 'And verily, there were men among mankind who took shelter with the masculine among the jinns, but they (jinns) increased them (mankind) in sin and disbelief.', 'and that some guys from human beings used to seek refuge with some guys of the Jinn, and thus they increased them (the Jinns) in arrogance,'),
(5454, 72, 7, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'وَّ اَنَّہُمۡ  ظَنُّوۡا کَمَا ظَنَنۡتُمۡ  اَنۡ  لَّنۡ یَّبۡعَثَ اللّٰہُ  اَحَدًا ۙ﴿۷﴾', 'اور یہ کہ ان کا بھی یہی اعتقاد تھا جس طرح تمہارا تھا کہ اللہ کسی کو نہیں  زندہ کرے گا۔', 'اور یہ کہ اُنکو بھی خیال تھا جیسا تم کو خیال تھا کہ ہرگز نہ اٹھائے گا اللہ کسی کو [۷]', 'And they thought as you thought, that Allah will not send any Messenger (to mankind or jinns).', 'and that they (humans) thought as you (O Jinns) thought that Allah will never resurrect anyone,'),
(5455, 72, 8, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'وَّ اَنَّا لَمَسۡنَا السَّمَآءَ  فَوَجَدۡنٰہَا مُلِئَتۡ حَرَسًا شَدِیۡدًا وَّ  شُہُبًا ۙ﴿۸﴾', 'اور یہ کہ ہم نے آسمان کو ٹٹولا تو اسکو مضبوط چوکیداروں اور انگاروں سے بھرا ہوا پایا۔', 'اور یہ کہ ہم نے ٹٹول کر دیکھا آسمان کو پھر پایا اُسکو بھر رہے ہیں اُس میں چوکیدار سخت اور انگارے', 'And we have sought to reach the heaven; but found it filled with stern guards and flaming fires.', 'and that we sought (to reach) the sky, but we found it filled with stern guards and flames,'),
(5456, 72, 9, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'وَّ اَنَّا کُنَّا نَقۡعُدُ مِنۡہَا مَقَاعِدَ لِلسَّمۡعِ ؕ فَمَنۡ  یَّسۡتَمِعِ الۡاٰنَ  یَجِدۡ لَہٗ  شِہَابًا  رَّصَدًا ۙ﴿۹﴾', 'اور یہ کہ پہلے ہم وہاں بہت سے مقامات پر فرشتوں کی باتیں سننے کے لئے بیٹھا کرتے تھے۔ اب کوئی سننا چاہے تو اپنے لئے انگارہ تیار پاتا ہے۔', 'اور یہ کہ ہم بیٹھا کرتے تھے ٹھکانوں میں سننے کے واسطے پھر جو کوئی اب سننا چاہے وہ پائےاپنے واسطے ایک انگارا گھات میں [۸]', 'And verily, we used to sit there in stations, to (steal) a hearing, but any who listens now will find a flaming fire watching him in ambush.', 'and that we used to sit at places therein to listen; but if one will (try to) listen now, he will find a flame in ambush for him,'),
(5457, 72, 10, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'وَّ اَنَّا لَا  نَدۡرِیۡۤ  اَشَرٌّ  اُرِیۡدَ بِمَنۡ فِی الۡاَرۡضِ اَمۡ  اَرَادَ بِہِمۡ  رَبُّہُمۡ  رَشَدًا ﴿ۙ۱۰﴾', 'اور یہ کہ ہمیں معلوم نہیں کہ اس سے اہل زمین کے ساتھ برائی مقصود ہے یا انکے پروردگار نے انکی بھلائی کا ارادہ فرمایا ہے۔', 'اور یہ کہ ہم نہیں جانتے کہ برا اراداہ ٹھہرا ہے زمین کے رہنے والوں پر یا چاہا ہے اُنکے حق میں اُنکے رب نے راہ پر لانا [۹]', 'And we know not whether evil is intended for those on earth, or whether their Lord intends for them a Right Path.', 'and that we do not know whether it is a bad end that is intended for those on earth, or their Lord has intended for them a right thing,'),
(5458, 72, 11, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'وَّ اَنَّا مِنَّا الصّٰلِحُوۡنَ وَ مِنَّا دُوۡنَ ذٰلِکَ ؕ  کُنَّا طَرَآئِقَ قِدَدًا ﴿ۙ۱۱﴾', 'اور یہ کہ ہم میں بعض نیک ہیں اور بعض دوسری طرح کے ہمارے کئ طرح کے مذہب ہیں۔', 'اور یہ کہ کوئی ہم میں نیک ہیں اور کوئی اسکےسوائے ہم تھے کئ راہ پر پھٹے ہوئے [۱۰]', 'There are among us some that are righteous, and some the contrary; we are groups each having a different way (religious sect, etc.).', 'and that some of us are (already) righteous, and some of us are otherwise, and we were on different ways;'),
(5459, 72, 12, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'وَّ اَنَّا ظَنَنَّاۤ  اَنۡ  لَّنۡ نُّعۡجِزَ اللّٰہَ  فِی  الۡاَرۡضِ وَ  لَنۡ  نُّعۡجِزَہٗ  ہَرَبًا ﴿ۙ۱۲﴾', 'اور یہ کہ ہم نے سمجھ لیا ہے کہ ہم زمین میں خواہ کہیں ہوں اللہ کو ہرا نہیں سکتے اور نہ بھاگ کر اسکو تھکا سکتے ہیں۔', 'اور یہ کہ ہمارے خیال میں آ گیا کہ ہم چھپ نہ جائیں گے اللہ سے زمین میں اور نہ تھکا دیں گے اُسکو بھاگ کر [۱۱]', 'And we think that we cannot escape (from the punishment of) Allah in the earth, nor can we escape (from the punishment) by flight.', 'and that we have now believed that we can never frustrate Allah on the earth, nor can we baffle Him by escape,'),
(5460, 72, 13, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'وَّ اَنَّا لَمَّا سَمِعۡنَا  الۡہُدٰۤی اٰمَنَّا بِہٖ ؕ فَمَنۡ یُّؤۡمِنۡۢ  بِرَبِّہٖ  فَلَا یَخَافُ بَخۡسًا وَّ لَا رَہَقًا ﴿ۙ۱۳﴾', 'اور جب ہم نے ہدایت کی کتاب سنی اس پر ایمان لے آئے سو جو شخص اپنے پروردگار پر ایمان لاتا ہے تو اسکو نہ نقصان کا خوف ہے نہ کسی طرح کے ظلم کا۔', 'اور یہ کہ جب ہم نے سن لی راہ کی بات تو ہم نے اُسکو مان لیا [۱۲] پھر جو کوئی یقین لائے گا اپنے رب پر سو وہ نہ ڈرے گا نقصان سے اور نہ زبردستی سے [۱۳]', 'And indeed when we heard the Guidance (this Quran), we believed therein (Islamic Monotheism), and whosoever believes in his Lord shall have no fear, either of a decrease in the reward of his good deeds or an increase in punishment for his sins.', 'and that when we heard the Guiding Discourse, we believed in it; so if one believes in his Lord, he will have no fear of either any curtailment (in his reward) or any excess (in his punishment),'),
(5461, 72, 14, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'وَّ اَنَّا مِنَّا  الۡمُسۡلِمُوۡنَ وَ مِنَّا الۡقٰسِطُوۡنَ ؕ فَمَنۡ  اَسۡلَمَ فَاُولٰٓئِکَ تَحَرَّوۡا  رَشَدًا ﴿۱۴﴾', 'اور یہ کہ ہم میں بعض فرمانبردار ہیں۔ اور بعض نافرمان ہیں تو جو فرمانبردار ہوئے وہ سیدھے رستے پر چلے۔', 'اور یہ کہ کچھ ہم میں حکم بردار ہیں اور کچھ ہیں بے انصاف سو جو لوگ حکم میں آ گئے سو انہوں نے اٹکل کر لیا نیک راہ کو', 'And of us some are Muslims (who have submitted to Allah, after listening to this Quran), and of us some are Al-Qasitoon (disbelievers those who have deviated from the Right Path). And whosoever has embraced Islam (i.e. has become a Muslim by submitting to Allah), then such have sought the Right Path.\"', 'and that some of us are Muslims, and some of us are unjust. Now, those who submitted to Islam have found out the right path,'),
(5462, 72, 15, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'وَ  اَمَّا  الۡقٰسِطُوۡنَ فَکَانُوۡا  لِجَہَنَّمَ حَطَبًا ﴿ۙ۱۵﴾', 'اور جو نافرمان ہوئے وہ دوزخ کا ایندھن بنے۔', 'اور جو بے انصاف ہیں وہ ہوئے دوزخ کے ایندھن [۱۴]', 'And as for the Qasitoon (disbelievers who deviated from the Right Path), they shall be firewood for Hell,', 'As for the unjust, they have become firewood for Hell.”'),
(5463, 72, 16, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'وَّ اَنۡ لَّوِ اسۡتَقَامُوۡا عَلَی الطَّرِیۡقَۃِ لَاَسۡقَیۡنٰہُمۡ  مَّآءً   غَدَقًا ﴿ۙ۱۶﴾', 'اور اے پیغمبر ﷺ یہ بھی ان سے کہدو کہ اگر یہ لوگ سیدھے رستے پر رہتے تو ہم انکے پینے کو بہت سا پانی دیتے۔', 'اور یہ حکم آیا کہ اگر لوگ سیدھے رہتے راہ پر تو ہم پلاتے اُنکو پانی بھر کر', 'If they (non-Muslims) had believed in Allah, and went on the Right Way (i.e. Islam) We should surely have bestowed on them water (rain) in abundance.', '“(And it is also revealed to me) that if they (the people of Makkah) had stood firm on the (right) way, We would have supplied water to them in abundance,'),
(5464, 72, 17, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'لِّنَفۡتِنَہُمۡ  فِیۡہِ ؕ وَ مَنۡ یُّعۡرِضۡ عَنۡ  ذِکۡرِ رَبِّہٖ  یَسۡلُکۡہُ  عَذَابًا صَعَدًا ﴿ۙ۱۷﴾', 'تاکہ اس سے انکی آزمائش کریں اور جو شخص اپنے پروردگار کی یاد سے منہ پھیرے گا وہ اسکو سخت عذاب میں داخل کرے گا۔', 'تاکہ اُنکو جانچیں اس میں [۱۵] اور جو کوئی منہ موڑے اپنے رب کی یاد سے وہ ڈال دے گا اُسکو چڑھتے عذاب میں [۱۶]', 'That We might try them thereby. And whosoever turns away from the Reminder of his Lord (i.e. this Quran, and practice not its laws and orders), He will cause him to enter in a severe torment (i.e. Hell).', 'so that We test them thereby; and if one turns away from the remembrance of his Lord, He will thrust him into a severe torment,'),
(5465, 72, 18, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'وَّ اَنَّ  الۡمَسٰجِدَ لِلّٰہِ  فَلَا تَدۡعُوۡا مَعَ اللّٰہِ  اَحَدًا ﴿ۙ۱۸﴾', 'اور یہ کہ مسجدیں خاص اللہ کی ہیں تو اللہ کے ساتھ کسی اور کی عبادت نہ کرو۔', 'اور یہ کہ مسجدیں اللہ کی یاد کے واسطے ہیں سو مت پکارو اللہ کے ساتھ کسی کو [۱۷]', 'And the mosques are for Allah (Alone), so invoke not anyone along with Allah.', 'and that masājid (mosques) belong to Allah; so, do not invoke anyone along with Allah,'),
(5466, 72, 19, 1, 11, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'وَّ اَنَّہٗ  لَمَّا قَامَ عَبۡدُ اللّٰہِ یَدۡعُوۡہُ کَادُوۡا یَکُوۡنُوۡنَ عَلَیۡہِ  لِبَدًا ﴿ؕ٪۱۹﴾', 'اور جب اللہ کے بندے یعنی یہ پیغمبر ﷺ اسکی عبادت کو کھڑے ہوئے تو کافر انکے گرد ہجوم کر لینے کو تھے۔', 'اور یہ کہ جب کھڑا ہوا اللہ کا بندہ [۱۸] کہ اُسکو پکارے لوگوں کا بندھنے لگتا ہے اُس پر ٹھٹھ [۱۹]', '(It has been revealed to me that) When the slave of Allah (Muhammad SAW) stood up invoking (his Lord Allah) in prayer to Him they (the jinns) just made round him a dense crowd as if sticking one over the other (in order to listen to the Prophets recitation).', 'and that when Allah’s servant stood invoking Him, they almost rushed on him in crowds.”'),
(5467, 72, 20, 2, 12, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'قُلۡ  اِنَّمَاۤ  اَدۡعُوۡا  رَبِّیۡ  وَ لَاۤ  اُشۡرِکُ بِہٖۤ اَحَدًا ﴿۲۰﴾', 'اے نبی ﷺ کہدو کہ میں تو اپنے پروردگار ہی کی عبادت کرتا ہوں اور کسی کو اسکا شریک نہیں بناتا۔', 'تو کہہ میں تو پکارتا ہوں بس اپنے رب کو اور شریک نہیں کرتا اُس کا کسی کو [۲۰]', 'Say (O Muhammad SAW): \"I invoke only my Lord (Allah Alone), and I associate none as partners along with Him.\"', 'Say, “I invoke my Lord, and do not associate anyone with Him.”'),
(5468, 72, 21, 2, 12, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'قُلۡ  اِنِّیۡ  لَاۤ  اَمۡلِکُ لَکُمۡ ضَرًّا وَّ لَا رَشَدًا ﴿۲۱﴾', 'یہ بھی کہدو کہ میں تمہارے لئے نہ کسی نقصان کا اور نہ نفع کا کچھ اختیار رکھتا ہوں۔', 'تو کہہ میرے اختیار میں نہیں تمہارا برا اور نہ راہ پر لانا [۲۱]', 'Say: \"It is not in my power to cause you harm, or to bring you to the Right Path.\"', 'Say, “I possess no power to cause you any harm or bring you to a right way.”'),
(5469, 72, 22, 2, 12, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'قُلۡ  اِنِّیۡ   لَنۡ یُّجِیۡرَنِیۡ  مِنَ  اللّٰہِ  اَحَدٌ ۬ۙ وَّ لَنۡ  اَجِدَ  مِنۡ  دُوۡنِہٖ   مُلۡتَحَدًا ﴿ۙ۲۲﴾', 'یہ بھی کہدو کہ اللہ کے عذاب سے مجھے کوئی پناہ نہیں دے سکتا۔ اور میں اسکے سوا کوئی جائے پناہ نہیں پاؤں گا۔', 'تو کہہ مجھ کو نہ بچائے گا اللہ کے ہاتھ سے کوئی اور نہ پاؤں گا اُسکے سوائے کہیں سرک رہنے کو جگہ [۲۲]', 'Say (O Muhammad SAW): \"None can protect me from Allahs punishment (if I were to disobey Him), nor should I find refuge except in Him.', 'Say, “No one can ever save me from Allah, and I can never find a refuge save with Him.'),
(5470, 72, 23, 2, 12, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'اِلَّا  بَلٰغًا مِّنَ اللّٰہِ وَ رِسٰلٰتِہٖ ؕ وَ مَنۡ یَّعۡصِ اللّٰہَ  وَ  رَسُوۡلَہٗ  فَاِنَّ  لَہٗ  نَارَ جَہَنَّمَ خٰلِدِیۡنَ  فِیۡہَاۤ   اَبَدًا ﴿ؕ۲۳﴾', 'ہاں اللہ کی طرف سے احکام کا اور اسکے پیغاموں کا پہنچا دینا ہی میرے ذمے ہے اور جو شخص اللہ اور اسکے پیغمبر کی نافرمانی کرے گا تو ایسوں کے لئے جہنم کی آگ ہے وہ ہمیشہ ہمیشہ اس میں رہیں گے۔', 'مگر پہنچانا ہے اللہ کی طرف سے اور اُسکے پیغام لانے [۲۳] اور جو کوئی حکم نہ مانے اللہ کا اور اُسکے رسول کا سو اُسکے لئے آگ ہے دوزخ کی رہا کریں اُس میں ہمیشہ [۲۴]', '\"(Mine is) but conveyance (of the truth) from Allah and His Messages (of Islamic Monotheism), and whosoever disobeys Allah and His Messenger, then verily, for him is the Fire of Hell, he shall dwell therein forever .\"', 'However, (I have been given power) of conveying (commands) from Allah, and His messages. The one who disobeys Allah and His Messenger, for him there is the fire of Hell, wherein such people will live forever.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(5471, 72, 24, 2, 12, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'حَتّٰۤی  اِذَا  رَاَوۡا  مَا  یُوۡعَدُوۡنَ فَسَیَعۡلَمُوۡنَ  مَنۡ اَضۡعَفُ نَاصِرًا وَّ اَقَلُّ  عَدَدًا ﴿۲۴﴾', 'یہاں تک کہ جب یہ لوگ وہ دن دیکھ لیں گے جس کا ان سے وعدہ کیا جاتا ہے تب انکو معلوم ہو جائے گا کہ مددگار کس کے کمزور ہیں اور شمار کن کا تھوڑا ہے۔', 'یہاں تک کہ جب دیکھیں گے جو کچھ اُن سے وعدہ ہوا تب جان لیں گے کس کے مددگار کمزور ہیں اور گنتی میں تھوڑے [۲۵]', 'Till, when they see that which they are promised, then they will know who it is that is weaker concerning helpers and less important concerning numbers.', '(The disbelievers will continue denying the truth and mock at it) until when they will see what they are promised, they will know whose supporters are weaker, and whose numbers are less.'),
(5472, 72, 25, 2, 12, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'قُلۡ  اِنۡ  اَدۡرِیۡۤ  اَقَرِیۡبٌ مَّا تُوۡعَدُوۡنَ اَمۡ  یَجۡعَلُ  لَہٗ  رَبِّیۡۤ   اَمَدًا ﴿۲۵﴾', 'کہدو کہ جس دن کا تم سے وعدہ کیا جاتا ہے میں نہیں جانتا کہ وہ عنقریب آنے والا ہے یا میرے پروردگار نے اسکی مدت دراز کر دی ہے۔', 'تو کہہ میں نہیں جانتا کہ نزدیک ہے جس چیز کا تم سے وعدہ ہوا ہے یا کر دے اسکو میرا رب ایک مدت کے بعد [۲۶]', 'Say (O Muhammad SAW): \"I know not whether (the punishment) which you are promised is near or whether my Lord will appoint for it a distant term.', 'Say, “I do not know whether that which you are promised is near, or my Lord has appointed for it a distant term.'),
(5473, 72, 26, 2, 12, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'عٰلِمُ الۡغَیۡبِ فَلَا یُظۡہِرُ عَلٰی غَیۡبِہٖۤ اَحَدًا ﴿ۙ۲۶﴾', 'وہی غیب کا جاننے والا ہے سو کسی پر اپنے غیب کو ظاہر نہیں کرتا۔', 'جاننے والا بھید کا سو نہیں خبر دیتا اپنے بھید کی کسی کو', '\"(He Alone) the All-Knower of the Ghaib (unseen), and He reveals to none His Ghaib (unseen).\"', '(He is the) Knower of the Unseen. So He does not let anyone know the Unseen created by Him,'),
(5474, 72, 27, 2, 12, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'اِلَّا مَنِ ارۡتَضٰی مِنۡ رَّسُوۡلٍ فَاِنَّہٗ یَسۡلُکُ مِنۡۢ  بَیۡنِ یَدَیۡہِ  وَ مِنۡ خَلۡفِہٖ رَصَدًا ﴿ۙ۲۷﴾', 'ہاں جس پیغمبر کو پسند فرمائے اور اسکو غیب کی باتیں بتا دے تو اسکے آگے اور پیچھے نگہبان مقرر کر دیتا ہے۔', 'مگر جو پسند کر لیا کسی رسول کو تو وہ چلاتا ہے اُسکے آگے اور پیچھے  چوکیدار [۲۷]', 'Except to a Messenger (from mankind) whom He has chosen (He informs him of unseen as much as He likes), and then He makes a band of watching guards (angels) to march before him and behind him.', 'except a messenger whom He chooses (to inform through revelation), and then He appoints (angels as) watching guards before him and behind him, (so that devils may not tamper with the divine revelation,)'),
(5475, 72, 28, 2, 12, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الجن', 'لِّیَعۡلَمَ  اَنۡ  قَدۡ  اَبۡلَغُوۡا رِسٰلٰتِ رَبِّہِمۡ وَ اَحَاطَ بِمَا لَدَیۡہِمۡ وَ اَحۡصٰی کُلَّ  شَیۡءٍ عَدَدًا ﴿٪۲۸﴾', 'تاکہ معلوم فرمائے کہ انہوں نے اپنے پروردگار کے پیغام پہنچا دیئے ہیں اور یوں تو اس نے انکی سب چیزوں کا ہر طرف سے احاطہ کر رکھا ہے اور ایک ایک چیز گن رکھی ہے۔', 'تاکہ جانے کہ انہوں نے پہنچائے پیغام اپنے رب کے [۲۸] اور قابو میں رکھا ہے جو اُنکے پاس ہے اور گن لی ہے ہر چیز کی گنتی [۲۹]', '(He (Allah) protects them (the Messengers)), till He sees that they (the Messengers) have conveyed the Messages of their Lord (Allah). And He (Allah) surrounds all that which is with them, and He (Allah) keeps count of all things (i.e. He knows the exact number of everything).', 'so that He knows that they (angels) have conveyed the messages of their Lord. And He has encompassed all that is with them, and has comprehensive knowledge of every thing by numbers.'),
(5476, 73, 1, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'یٰۤاَیُّہَا الۡمُزَّمِّلُ ۙ﴿۱﴾', 'اے کملی میں لپٹنے والے۔', 'اے کپڑے میں لپٹنے والے [۱]', 'O you wrapped in garments (i.e. Prophet Muhammad SAW)!', 'O you, wrapped up in clothes,'),
(5477, 73, 2, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'قُمِ  الَّیۡلَ   اِلَّا  قَلِیۡلًا ۙ﴿۲﴾', 'رات کو قیام کیا کرو مگر تھوڑی سی رات۔', 'کھڑا رہ رات کو مگر کسی رات [۲]', 'Stand (to pray) all night, except a little.', 'stand at night (for prayer) except a little-'),
(5478, 73, 3, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'نِّصۡفَہٗۤ  اَوِ انۡقُصۡ  مِنۡہُ  قَلِیۡلًا ۙ﴿۳﴾', 'یعنی نصف رات یا اس سے کچھ کم قیام کرو۔', 'آدھی رات یا اُس میں سے کم کر دے تھوڑا سا', 'Half of it, or a little less than that,', '-half of it, or make it a little less,'),
(5479, 73, 4, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'اَوۡ زِدۡ  عَلَیۡہِ  وَ رَتِّلِ الۡقُرۡاٰنَ  تَرۡتِیۡلًا ؕ﴿۴﴾', 'یا کچھ زیادہ اور قرآن کو اچھی طرح ٹھہر ٹھہر کر پڑھا کرو۔', 'یا زیادہ کر اُس پر [۳] اور کھول کھول کر پڑھ قرآن کو صاف [۴]', 'Or a little more; and recite the Quran (aloud) in a slow, (pleasant tone and) style .', 'or make it a little more; and recite the Qur’ān clearly with tartīl (in a distinct and measured tone).'),
(5480, 73, 5, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'اِنَّا سَنُلۡقِیۡ عَلَیۡکَ  قَوۡلًا  ثَقِیۡلًا ﴿۵﴾', 'ہم عنقریب تم پر ایک بھاری فرمان نازل کریں گے۔', 'ہم ڈالنے والے ہیں تجھ پر ایک بات وزن دار [۵]', 'Verily, We shall send down to you a weighty Word (i.e. obligations, legal laws, etc.).', 'We are going to send down to you a weighty discourse.'),
(5481, 73, 6, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'اِنَّ نَاشِئَۃَ الَّیۡلِ  ہِیَ اَشَدُّ وَطۡاً  وَّ  اَقۡوَمُ قِیۡلًا ؕ﴿۶﴾', 'کچھ شک نہیں کہ رات کا اٹھنا نفس کو سخت پامال کرتا ہے اور اس وقت ذکر بھی خوب درست ہوتا ہے۔', 'البتہ اٹھنا رات کو سخت روندتا ہے اور سیدھی نکلتی ہے بات [۶]', 'Verily, the rising by night (for Tahajjud prayer) is very hard and most potent and good for governing (the soul), and most suitable for (understanding) the Word (of Allah).', 'Truly, rising by night (for prayer of tahajjud) is the most effective way to subdue (one’s base self) and to make speech more upright.'),
(5482, 73, 7, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'اِنَّ  لَکَ فِی النَّہَارِ سَبۡحًا طَوِیۡلًا ؕ﴿۷﴾', 'دن کے وقت تو تمہیں اور بہت سے شغل ہوتے ہیں۔', 'البتہ تجھ کو دن میں شغل رہتا ہے لمبا [۷]', 'Verily, there is for you by day prolonged occupation with ordinary duties,', 'Surely, in daytime, you have a lengthy work to do.'),
(5483, 73, 8, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'وَ اذۡکُرِ اسۡمَ رَبِّکَ وَ تَبَتَّلۡ  اِلَیۡہِ تَبۡتِیۡلًا ؕ﴿۸﴾', 'تو اپنے پروردگار کے نام کا ذکر کرو اور ہر طرف سے بے تعلق ہو کر اسی کی طرف متوجہ ہو جاؤ۔', 'اور پڑھے جا نام اپنے رب کا اور چھوٹ کر  آ اسکی طرف سب سے الگ ہو کر [۸]', 'And remember the Name of your Lord and devote yourself to Him with a complete devotion.', 'And remember the name of your Lord, and devote yourself to Him with exclusive devotion.'),
(5484, 73, 9, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'رَبُّ الۡمَشۡرِقِ وَ الۡمَغۡرِبِ لَاۤ  اِلٰہَ  اِلَّا ہُوَ فَاتَّخِذۡہُ  وَکِیۡلًا ﴿۹﴾', 'وہی مشرق اور مغرب کا مالک ہے اسکے سوا کوئی معبود نہیں تو اسی کو اپنا کارساز بناؤ۔', 'مالک مشرق اور مغرب کا [۹] اُسکے سوا کسی کی بندگی نہیں سو پکڑ لے اُسکو کام بنانے والا [۱۰]', '(He Alone is) the Lord of the east and the west, La ilaha illa Huwa (none has the right to be worshipped but He). So take Him Alone as Wakeel (Disposer of your affairs) .', 'He is the Lord of the East and the West; there is no god but He; so take Him for (your) Guardian.'),
(5485, 73, 10, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'وَ اصۡبِرۡ عَلٰی مَا یَقُوۡلُوۡنَ وَ اہۡجُرۡہُمۡ ہَجۡرًا جَمِیۡلًا ﴿۱۰﴾', 'اور جو جو دل آزار باتیں یہ لوگ کہتے ہیں انکو سہتے رہو اور خوبصورتی سے ان سے کنارہ کش رہو۔', 'اور سہتا رہ جو کچھ کہتے رہیں [۱۱] اور چھوڑ دے اُنکو بھلی طرح کا چھوڑنا [۱۲]', 'And be patient (O Muhammad SAW) with what they say, and keep away from them in a good way.', 'And bear patiently what they (the opponents) say, and part with them in a beautiful manner.'),
(5486, 73, 11, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'وَ ذَرۡنِیۡ وَ الۡمُکَذِّبِیۡنَ  اُولِی النَّعۡمَۃِ وَ مَہِّلۡہُمۡ  قَلِیۡلًا ﴿۱۱﴾', 'اور مجھے ان جھٹلانے والوں سے جو دولتمند ہیں سمجھ لینے دو اور انکو تھوڑی سی مہلت دے دو۔', 'اور چھوڑ دے مجھ کو اور جھٹلانے والوں کو جو آرام میں رہے ہیں اور ڈھیل دےاُنکو تھوڑی سے [۱۳]', 'And leave Me Alone to deal with the beliers (those who deny My Verses, etc.), and those who are in possession of good things of life. And give them respite for a little while.', 'And leave Me alone (to deal) with the deniers, the people of luxury, and give them respite for a while.'),
(5487, 73, 12, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'اِنَّ  لَدَیۡنَاۤ  اَنۡکَالًا وَّ  جَحِیۡمًا ﴿ۙ۱۲﴾', 'کچھ شک نہیں کہ ہمارے پاس بیڑیاں ہیں اور  بڑی زبردست آگ ہے۔', 'البتہ ہمارے پاس بیڑیاں ہیں اور آگ کا ڈھیر', 'Verily, with Us are fetters (to bind them), and a raging Fire.', 'Surely with Us are fetters and flaming fire,'),
(5488, 73, 13, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'وَّ طَعَامًا ذَا غُصَّۃٍ  وَّ عَذَابًا  اَلِیۡمًا ﴿٭۱۳﴾', 'اور گلے میں اٹکنے والا کھانا ہے اور درد دینے والا عذاب ہے۔', 'اور کھانا گلے میں اٹکنے والا اور عذاب دردناک [۱۴]', 'And a food that chokes, and a painful torment.', 'and food that chokes, and a painful punishment'),
(5489, 73, 14, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'یَوۡمَ تَرۡجُفُ الۡاَرۡضُ وَ الۡجِبَالُ وَ کَانَتِ الۡجِبَالُ  کَثِیۡبًا مَّہِیۡلًا ﴿۱۴﴾', 'جس دن زمین اور پہاڑ کانپنے لگیں اور پہاڑ ایسے بھر بھرے ہو جائیں گے جیسے ریت کے ٹیلے۔', 'جس دن کہ کانپے گی زمین اور پہاڑ اور ہو جائیں گے پہاڑ ریت کے تودے پھسلتے [۱۵]', 'On the Day when the earth and the mountains will be in violent shake, and the mountains will be a heap of sand poured out and flowing down.', 'on the Day when the earth and the mountains will quake, and the mountains will turn into a slipping heap of sand.'),
(5490, 73, 15, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'اِنَّاۤ  اَرۡسَلۡنَاۤ  اِلَیۡکُمۡ  رَسُوۡلًا ۬ۙ شَاہِدًا عَلَیۡکُمۡ کَمَاۤ  اَرۡسَلۡنَاۤ  اِلٰی فِرۡعَوۡنَ رَسُوۡلًا ﴿ؕ۱۵﴾', 'اے اہل مکہ جس طرح ہم نے فرعون کے پاس موسٰی کو پیغمبر بنا کر بھیجا تھا اسی طرح تمہارے پاس بھی محمد ﷺ ایک رسول بھیجے ہیں جو تمہارے مقابلے میں گواہ ہوں گے۔', 'ہم نے بھیجا تمہاری طرف رسول بتلانے والا تمہاری باتوں کا [۱۶] جیسے بھیجا فرعون کے پاس رسول [۱۷]', 'Verily, We have sent to you (O men) a Messenger (Muhammad SAW) to be a witness over you, as We did send a Messenger (Moosa (Moses)) to Firaun (Pharaoh) .', '(O people,) We have sent to you a messenger, as a witness over you, just as We sent a messenger to Fir‘aun (Pharaoh).'),
(5491, 73, 16, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'فَعَصٰی فِرۡعَوۡنُ  الرَّسُوۡلَ  فَاَخَذۡنٰہُ اَخۡذًا  وَّبِیۡلًا ﴿۱۶﴾', 'سو فرعون نے ہمارے پیغمبر کا کہا نہ مانا تو ہم نے اسکو بڑے دردناک انداز سے پکڑ لیا۔', 'پھر کہا نہ مانا فرعون نے رسول کا پھر پکڑی ہم نے اُسکو  وبال کی پکڑ [۱۸]', 'But Firaun (Pharaoh) disobeyed the Messenger (Moosa (Moses)), so We seized him with a severe punishment.', 'Then, Fir‘aun disobeyed the messenger; so We seized him with a severe seizure.'),
(5492, 73, 17, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'فَکَیۡفَ  تَتَّقُوۡنَ  اِنۡ  کَفَرۡتُمۡ  یَوۡمًا یَّجۡعَلُ  الۡوِلۡدَانَ  شِیۡبَۨا ﴿٭ۖ۱۷﴾', 'اگر تم بھی ان پیغمبر کو نہ مانو گے تو اس دن سے کس طرح بچو گے جو بچوں کو بوڑھا کر دے گا۔', 'پھر کیونکر بچو گے اگر منکر ہو گئے اُس دن سے جو کر ڈالے لڑکوں کو بوڑھا [۱۹]', 'Then how can you avoid the punishment, if you disbelieve, on a Day that will make the children grey-headed (i.e. the Day of Resurrection)?', 'So, if you disbelieve, how will you save yourself from a day that will turn the small boys into grey-headed old men,'),
(5493, 73, 18, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'السَّمَآءُ  مُنۡفَطِرٌۢ  بِہٖ ؕ کَانَ  وَعۡدُہٗ مَفۡعُوۡلًا ﴿۱۸﴾', 'جس سے آسمان پھٹ جائے گا یہ اس کا وعدہ پورا ہو کر رہے گا۔', 'آسمان پھٹ جائے گا اُس دن میں اُس کا وعدہ ہونے والا ہے [۲۰]', 'Whereon the heaven will be cleft asunder? His Promise is certainly to be accomplished.', 'whereby the sky will burst apart. His promise has to be fulfilled.'),
(5494, 73, 19, 1, 13, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'اِنَّ  ہٰذِہٖ  تَذۡکِرَۃٌ ۚ فَمَنۡ شَآءَ  اتَّخَذَ  اِلٰی  رَبِّہٖ  سَبِیۡلًا ﴿٪۱۹﴾', 'یہ قرآن تو نصیحت ہے۔ سو جو چاہے اپنے پروردگار تک پہنچنے کا راستہ اختیار کر لے۔', 'یہ تو نصیحت ہے پھر جو کوئی چاہے بنالے اپنے رب کی طرف راہ [۲۱]', 'Verily, this is an admonition, therefore whosoever will, let him take a Path to His Lord!', 'Indeed, this is a reminder; so let anyone who so wishes, adopt a way to his Lord.'),
(5495, 73, 20, 2, 14, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المزّمّل', 'اِنَّ  رَبَّکَ یَعۡلَمُ  اَنَّکَ  تَقُوۡمُ  اَدۡنٰی مِنۡ ثُلُثَیِ الَّیۡلِ وَ نِصۡفَہٗ  وَ ثُلُثَہٗ  وَ طَآئِفَۃٌ  مِّنَ  الَّذِیۡنَ مَعَکَ ؕ وَ  اللّٰہُ  یُقَدِّرُ الَّیۡلَ وَ النَّہَارَ ؕ عَلِمَ  اَنۡ  لَّنۡ تُحۡصُوۡہُ فَتَابَ عَلَیۡکُمۡ  فَاقۡرَءُوۡا مَا تَیَسَّرَ مِنَ الۡقُرۡاٰنِ ؕ عَلِمَ  اَنۡ  سَیَکُوۡنُ مِنۡکُمۡ مَّرۡضٰی ۙ وَ اٰخَرُوۡنَ  یَضۡرِبُوۡنَ فِی الۡاَرۡضِ  یَبۡتَغُوۡنَ مِنۡ فَضۡلِ اللّٰہِ ۙ وَ اٰخَرُوۡنَ یُقَاتِلُوۡنَ فِیۡ سَبِیۡلِ اللّٰہِ ۫ۖ فَاقۡرَءُوۡا مَا تَیَسَّرَ  مِنۡہُ ۙ وَ اَقِیۡمُوا الصَّلٰوۃَ  وَ اٰتُوا الزَّکٰوۃَ  وَ اَقۡرِضُوا اللّٰہَ  قَرۡضًا حَسَنًا ؕ وَ مَا  تُقَدِّمُوۡا لِاَنۡفُسِکُمۡ مِّنۡ خَیۡرٍ تَجِدُوۡہُ  عِنۡدَ اللّٰہِ ہُوَ خَیۡرًا وَّ اَعۡظَمَ اَجۡرًا ؕ وَ اسۡتَغۡفِرُوا اللّٰہَ ؕ اِنَّ اللّٰہَ غَفُوۡرٌ رَّحِیۡمٌ  ﴿٪۲۰﴾', 'تمہارا پروردگار خوب جانتا ہے کہ تم اور تمہارے ساتھ کے لوگ کبھی دو تہائی رات کے قریب اور کبھی آدھی رات اور کبھی تہائی رات قیام کیا کرتے ہو۔ اور اللہ رات اور دن کا اندازہ رکھتا ہے۔ اس نے معلوم کیا کہ تم اسکو نباہ نہ سکو گے تو اس نے تم پر مہربانی کی پس جتنا آسانی سے ہو سکے اتنا قرآن پڑھ لیا کرو۔ اس نے جانا کہ تم میں بعض بیمار بھی ہونگے اور بعض اللہ کے فضل یعنی معاش کی تلاش میں ملک میں سفر کرینگے اور بعض اللہ کی راہ میں لڑیں گے۔ تو جتنا آسانی سے ہو سکے اتنا قرآن پڑھ لیا کرو اور نماز قائم کرتے رہو اور زکوٰۃ ادا کرتے رہو اور اللہ کو نیک نیتی سے قرض دیتے رہو۔ اور جو عمل نیک تم اپنے لئے آگے بھیجو گے اسکو اللہ کے ہاں بہتر اور صلے میں بہت عظیم پاؤ گے۔ اور اللہ سے بخشش مانگتے رہو۔ بیشک اللہ بخشنے والا ہے مہربان ہے۔', 'بیشک تیرا رب جانتا ہے کہ تو اٹھتا ہے نزدیک دو تہائی رات کے اور آدھی رات کے اور تہائی رات کے اور کتنے لوگ تیرے ساتھ کے [۲۲] اور اللہ ماپتا ہے رات کو اور دن کو اُس نے جانا کہ تم اُس کو پورا نہ کر سکو گے سو تم پرمعافی بھیجدی اب پڑھو جتنا تم کو آسان ہو قرآن سے [۲۳] جانا کہ کتنے ہوں گے تم میں بیمار اور کتنے اور لوگ پھریں گے ملک میں ڈھونڈھتے اللہ کے فضل کو اور کتنے لوگ لڑتے ہوں گے اللہ کی راہ میں سو پڑھ لیا کرو جتنا آسان ہو اُس میں سے اورقائم رکھو نماز اور دیتے رہو زکوٰۃ [۲۴] اور قرض دو اللہ کو اچھی طرح پر قرض دینا [۲۵] اور جو کچھ آگے بھیجو گے اپنے واسطے کوئی نیکی اُسکو پاؤ گے اللہ کے پاس بہتر اور ثواب میں زیادہ [۲۶] اور معافی مانگو اللہ سے بیشک اللہ بخشنے والا مہربان ہے [۲۷]', 'Verily, your Lord knows that you do stand (to pray at night) a little less than two-thirds of the night, or half the night, or a third of the night, and so do a party of those with you, And Allah measures the night and the day. He knows that you are unable to pray the whole night, so He has turned to you (in mercy). So, recite you of the Quran as much as may be easy for you. He knows that there will be some among you sick, others travelling through the land, seeking of Allahs Bounty; yet others fighting in Allahs Cause. So recite as much of the Quran as may be easy (for you), and perform As-Salat (Iqamat-as-Salat) and give Zakat, and lend to Allah a goodly loan, and whatever good you send before you for yourselves, (i.e. Nawafil non-obligatory acts of worship: prayers, charity, fasting, Hajj and Umrah, etc.), you will certainly find it with Allah, better and greater in reward. And seek Forgiveness of Allah. Verily, Allah is Oft-Forgiving, Most-Merciful.', 'Your Lord knows that you stand (in prayer) for nearly two thirds of the night, and (at times) for half of it, and (at times) for one third of it, and (so do) a group of those who are with you. And Allah measures the night and the day. He knows that you (O Muslims,) cannot do it in regular way; therefore He turned to you in mercy.Now, recite as much of the Qur’ān as is easy (for you). He knows that some of you may be sick, and others traveling in the land, seeking the grace of Allah, and yet others fighting in Allah’s way. Therefore, recite as much of it as is easy. And establish Salāh, and pay Zakāh, and advance to Allah a goodly loan. And whatever good you will send ahead for your own-selves, you will find it with Allah much better in condition, and much greater in reward. And seek forgiveness from Allah. Indeed Allah is Most-Forgiving, Very-Merciful.'),
(5496, 74, 1, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'یٰۤاَیُّہَا الۡمُدَّثِّرُ ۙ﴿۱﴾', 'اے چادر میں لپٹنے والے۔', 'اے لحاف میں لپٹنے والے [۱]', 'O you (Muhammad SAW) enveloped (in garments)!', 'O you, enveloped in a mantle,'),
(5497, 74, 2, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'قُمۡ   فَاَنۡذِرۡ ۪ۙ﴿۲﴾', 'اٹھو اب خبردار کرنے لگو۔', 'کھڑا ہو پھر ڈر سنا دے [۲]', 'Arise and warn!', 'stand up and warn,'),
(5498, 74, 3, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'وَ  رَبَّکَ فَکَبِّرۡ ۪﴿ۙ۳﴾', 'اور اپنے پروردگار کی بڑائی بیان کرو۔', 'اور اپنے رب کی بڑائی بول [۳]', 'And your Lord (Allah) magnify!', 'and pronounce the greatness of your Lord,'),
(5499, 74, 4, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'وَ  ثِیَابَکَ فَطَہِّرۡ ۪﴿ۙ۴﴾', 'اور اپنے کپڑے پاک رکھو۔', 'اور اپنے کپڑے پاک رکھ', 'And your garments purify!', 'and purify your clothes,'),
(5500, 74, 5, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'وَ الرُّجۡزَ  فَاہۡجُرۡ ۪﴿ۙ۵﴾', 'اور شرک کی گندگی سے تو الگ ہی رہو۔', 'اور گندگی سے دور رہ [۴]', 'And keep away from Ar-Rujz (the idols)!', 'and keep away from filth,'),
(5501, 74, 6, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'وَ لَا  تَمۡنُنۡ  تَسۡتَکۡثِرُ ۪﴿ۙ۶﴾', 'اور اس نیت سے احسان نہ کرو کہ اس سے زیادہ کے خواہاں ہو۔', 'اور ایسا نہ کر کہ احسان کرے اور بدلا بہت چاہے', 'And give not a thing in order to have more (or consider not your deeds of Allahs obedience as a favour to Allah).', 'and do not do a favour (to anyone merely) to seek more (in return).'),
(5502, 74, 7, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'وَ  لِرَبِّکَ  فَاصۡبِرۡ ؕ﴿۷﴾', 'اور اپنے پروردگار کی خاطر صبر کرتے رہو۔', 'اور اپنے رب سے امید رکھ [۵]', 'And be patient for the sake of your Lord (i.e. perform your duty to Allah)!', 'And for the sake of your Lord, observe patience.'),
(5503, 74, 8, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'فَاِذَا  نُقِرَ  فِی النَّاقُوۡرِ ۙ﴿۸﴾', 'پھر جب صور پھونکا جائے گا۔', 'پھر جب بجنے لگے وہ کھوکھری چیز [۶]', 'Then, when the Trumpet is sounded (i.e. its second blowing);', 'For when the trumpet will be blown,'),
(5504, 74, 9, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'فَذٰلِکَ یَوۡمَئِذٍ  یَّوۡمٌ عَسِیۡرٌ ۙ﴿۹﴾', 'تو وہ دن مشکل کا دن ہوگا۔', 'پھر وہ اس دن مشکل دن ہے [۷]', 'Truly, that Day will be a Hard Day.', 'that day will be a difficult day,'),
(5505, 74, 10, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'عَلَی الۡکٰفِرِیۡنَ غَیۡرُ  یَسِیۡرٍ ﴿۱۰﴾', 'یعنی کافروں پر آسان نہ ہوگا۔', 'منکروں پر نہیں آسان [۸]', 'Far from easy for the disbelievers.', 'not easy for the disbelievers.'),
(5506, 74, 11, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'ذَرۡنِیۡ  وَ  مَنۡ خَلَقۡتُ وَحِیۡدًا ﴿ۙ۱۱﴾', 'مجھے اس شخص سے سمجھ لینے دو جسکو میں نے اکیلا پیدا کیا۔', 'چھوڑ دے مجھ کو اور اُس کو جسکو میں نے بنایا انکا [۹]', 'Leave Me Alone (to deal) with whom I created Alone (without any means, i.e. Al-Waleed bin Al-Mugheerah Al-Makhzoomee)!', 'Leave me alone (to deal) with the one whom I created lonely,'),
(5507, 74, 12, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'وَّ  جَعَلۡتُ لَہٗ  مَالًا  مَّمۡدُوۡدًا ﴿ۙ۱۲﴾', 'اور میں نے اسکو بہت سا مال دیا۔', 'اور دیا میں نے اُسکو مال پھیلا کر', 'And then granted him resources in abundance.', 'and gave him extensive wealth,'),
(5508, 74, 13, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'وَّ  بَنِیۡنَ شُہُوۡدًا ﴿ۙ۱۳﴾', 'اور ہر وقت حاضر رہنے والے بیٹے دیئے۔', 'اور بیٹے مجلس میں بیٹھنے والے [۱۰]', 'And children to be by his side!', 'and sons present before (his) eyes,'),
(5509, 74, 14, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'وَّ  مَہَّدۡتُّ لَہٗ  تَمۡہِیۡدًا ﴿ۙ۱۴﴾', 'اور اسکو ہر طرح کے سامان میں وسعت دی۔', 'اور تیاری کر دی اُسکے  لئے خوب تیاری [۱۱]', 'And made life smooth and comfortable for him!', 'and extended (power and honour) to him pretty well.'),
(5510, 74, 15, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'ثُمَّ  یَطۡمَعُ  اَنۡ  اَزِیۡدَ ﴿٭ۙ۱۵﴾', 'پھر بھی لالچ رکھتا ہے کہ میں اسے اور زیادہ دوں۔', 'پھر لالچ رکھتا ہے کہ اور بھی دوں [۱۲]', 'After all that he desires that I should give more;', 'Still, he aspires that I should give him more.'),
(5511, 74, 16, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'کَلَّا ؕ اِنَّہٗ  کَانَ  لِاٰیٰتِنَا عَنِیۡدًا ﴿ؕ۱۶﴾', 'ایسا ہرگز نہیں ہو گا۔ یہ ہماری آیتوں کا بڑا مخالف رہا ہے۔', 'ہرگز نہیں وہ ہے ہماری آیتوں کا مخالف [۱۳]', 'Nay! Verily, he has been stubborn and opposing Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.).', 'Never! He is inimical towards Our verses.'),
(5512, 74, 17, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'سَاُرۡہِقُہٗ  صَعُوۡدًا ﴿ؕ۱۷﴾', 'میں اسے ایک بڑی چڑھائی چڑھاؤں گا۔', 'اب اُسی سے چڑھواؤں گا بڑی چڑھائی [۱۴]', 'I shall oblige him to (climb a slippery mountain in the Hell-fire called AsSaood, or to) face a severe torment!', 'I will force him to climb the mountain Sa‘ūd.'),
(5513, 74, 18, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'اِنَّہٗ  فَکَّرَ  وَ  قَدَّرَ ﴿ۙ۱۸﴾', 'اس نے غوروفکر کیا اور ایک بات ٹھہرا لی۔', 'اُس نے فکر کیا اور دل میں ٹھہرا لیا', 'Verily, he thought and plotted;', 'He pondered and surmised.'),
(5514, 74, 19, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'فَقُتِلَ  کَیۡفَ قَدَّرَ ﴿ۙ۱۹﴾', 'یہ مارا جائے اس نے کیسی تجویز کی۔', 'سو مارا جائیو کیسا ٹھہرایا', 'So let him be cursed! How he plotted!', 'Death onto him! How (bad) is the surmise he put forward!'),
(5515, 74, 20, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'ثُمَّ  قُتِلَ  کَیۡفَ قَدَّرَ ﴿ۙ۲۰﴾', 'پھر یہ مارا جائے اس نے یہ کیسی تجویز کی۔', 'پھر مارا جائیو کیسا ٹھہرایا [۱۵]', 'And once more let him be cursed, how he plotted!', 'Again, death unto him! How (bad) is the surmise he put forward!'),
(5516, 74, 21, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'ثُمَّ  نَظَرَ ﴿ۙ۲۱﴾', 'پھر اس نے نگاہ کی۔', 'پھر نگاہ کی', 'Then he thought;', 'Then he looked (to those around him,)'),
(5517, 74, 22, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'ثُمَّ  عَبَسَ  وَ  بَسَرَ ﴿ۙ۲۲﴾', 'پھر تیوری چڑھائی اور منہ بگاڑا۔', 'پھر تیوری چڑھائی اور منہ تھتھایا', 'Then he frowned and he looked in a bad tempered way;', 'then he frowned and scowled,'),
(5518, 74, 23, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'ثُمَّ  اَدۡبَرَ  وَ  اسۡتَکۡبَرَ ﴿ۙ۲۳﴾', 'پھر پیٹھ کر چلا اور تکبر کیا۔', 'پھر پیٹھ پھیری اور غرور کیا', 'Then he turned back and was proud;', 'then turned his back, and waxed proud,'),
(5519, 74, 24, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'فَقَالَ  اِنۡ  ہٰذَاۤ  اِلَّا  سِحۡرٌ  یُّؤۡثَرُ ﴿ۙ۲۴﴾', 'پھر کہنے لگا یہ تو جادو ہے جو پہلے لوگوں سے برابر ہوتا آیا ہے۔', 'پھر بولا اور کچھ نہیں یہ جادو ہے چلا آتا', 'Then he said: \"This is nothing but magic from that of old;', 'then said, “This is nothing but traditional magic;'),
(5520, 74, 25, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'اِنۡ  ہٰذَاۤ  اِلَّا  قَوۡلُ الۡبَشَرِ ﴿ؕ۲۵﴾', 'پھر بولا یہ اللہ کا کلام نہیں بلکہ بشر کا کلام ہے۔', 'اور کچھ نہیں یہ کہا ہوا ہے آدمی کا [۱۶]', '\"This is nothing but the word of a human being!\"', 'this is nothing but saying of a mortal.”'),
(5521, 74, 26, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'سَاُصۡلِیۡہِ سَقَرَ ﴿۲۶﴾', 'میں عنقریب اسکو سقر میں داخل کروں گا۔', 'اب اُسکو ڈالوں گا آگ میں [۱۷]', 'I will cast him into Hell-fire', 'I will put him into Saqar (Hell).'),
(5522, 74, 27, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'وَ  مَاۤ  اَدۡرٰىکَ مَا سَقَرُ ﴿ؕ۲۷﴾', 'اور تم کیا سمجھے کہ سقر کیا ہے۔', 'اور تو کیا سمجھا کیسی ہے وہ آگ', 'And what will make you know exactly what Hell-fire is?', 'And what can let you know what Saqar is?'),
(5523, 74, 28, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'لَا  تُبۡقِیۡ  وَ لَا  تَذَرُ ﴿ۚ۲۸﴾', 'وہ ایسی آگ ہے کہ نہ باقی رکھے گی اور نہ چھوڑے گی۔', 'نہ باقی رکھے اور نہ چھوڑے [۱۸]', 'It spares not (any sinner), nor does it leave (anything unburnt)!', 'It neither spares (anything inside it from burning) nor leaves (any disbeliever outside).'),
(5524, 74, 29, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'لَوَّاحَۃٌ  لِّلۡبَشَرِ ﴿ۚۖ۲۹﴾', 'اور بدن کو جھلس کر سیاہ کر دے گی۔', 'جلا دینے والی ہے آدمیوں کو [۱۹]', 'Burning the skins!', 'It will disfigure the skins.'),
(5525, 74, 30, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'عَلَیۡہَا تِسۡعَۃَ عَشَرَ ﴿ؕ۳۰﴾', 'اس پر انیس داروغہ ہیں۔', 'اُس پر مقرر ہیں انیس فرشتے [۲۰]', 'Over it are nineteen (angels as guardians and keepers of Hell).', 'Appointed on it are nineteen (wardens).'),
(5526, 74, 31, 1, 15, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'وَ مَا جَعَلۡنَاۤ  اَصۡحٰبَ النَّارِ  اِلَّا مَلٰٓئِکَۃً ۪ وَّ مَا جَعَلۡنَا عِدَّتَہُمۡ  اِلَّا فِتۡنَۃً لِّلَّذِیۡنَ کَفَرُوۡا ۙ لِیَسۡتَیۡقِنَ  الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ وَ یَزۡدَادَ  الَّذِیۡنَ اٰمَنُوۡۤا اِیۡمَانًا وَّ لَا یَرۡتَابَ  الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ وَ الۡمُؤۡمِنُوۡنَ ۙ وَ لِیَقُوۡلَ الَّذِیۡنَ  فِیۡ  قُلُوۡبِہِمۡ  مَّرَضٌ وَّ الۡکٰفِرُوۡنَ مَاذَاۤ  اَرَادَ  اللّٰہُ  بِہٰذَا  مَثَلًا ؕ  کَذٰلِکَ یُضِلُّ  اللّٰہُ  مَنۡ یَّشَآءُ  وَ  یَہۡدِیۡ  مَنۡ یَّشَآءُ ؕ وَ مَا یَعۡلَمُ جُنُوۡدَ  رَبِّکَ اِلَّا ہُوَ ؕ وَ مَا ہِیَ  اِلَّا  ذِکۡرٰی لِلۡبَشَرِ ﴿٪۳۱﴾', 'اور ہم نے دوزخ کے داروغہ فرشتے ہی بنائے ہیں۔ اور ان کا شمار کافروں کی آزمائش کے لئے مقرر کیا ہے اس لئے کہ اہل کتاب یقین کریں اور مومنوں کا ایمان اور زیادہ ہو اور اہل کتاب اور مومن شک نہ لائیں۔ اور اس لئے کہ جن لوگوں کے دلوں میں نفاق کا روگ ہے اور جو کافر ہیں کہیں کہ اس مثال کے بیان کرنے سے اللہ کا مقصود کیا ہے؟ اسی طرح اللہ جسکو چاہتا ہے گمراہ رہنے دیتا ہے اور جسکو چاہتا ہے ہدایت دیتا ہے۔ اور تمہارے پروردگار کے لشکروں کو اسکے سوا کوئی نہیں جانتا۔ اور یہ قرآن تو بنی آدم کے لئے نصیحت ہے۔', 'اور ہم نے جو رکھے ہیں دوزخ پر داروغہ وہ فرشتے ہی ہیں [۲۱] اور اُنکی جو گنتی رکھی ہے سو جانچنے کو منکروں کے [۲۲] تاکہ یقین کر لیں وہ لوگ جنکو ملی ہے کتاب اور بڑھے ایمانداروں کا ایمان اور دھوکا نہ کھائیں جنکو ملی ہے کتاب اور مسلمان [۲۳] اور تاکہ کہیں وہ لوگ کہ جنکے دل میں روگ ہے اور منکر [۲۴] کیا غرض تھی اللہ کو اس مثل سے [۲۵] یوں بچلاتا ہے اللہ جسکو چاہے اور راہ دیتا ہے جسکو چاہے [۲۶] اور کوئی نہیں جانتا تیرے رب کے لشکر مگر خود ہی [۲۷] اور وہ تو سمجھانا ہے لوگوں کے واسطے [۲۸]', 'And We have set none but angels as guardians of the Fire, and We have fixed their number (19) only as a trial for the disbelievers, in order that the people of the Scripture (Jews and Christians) may arrive at a certainty (that this Quran is the truth as it agrees with their Books i.e. their number (19) is written in the Taurat (Torah) and the Injeel (Gospel)) and the believers may increase in Faith (as this Quran is the truth) and that no doubts may be left for the people of the Scripture and the believers, and that those in whose hearts is a disease (of hypocrisy) and the disbelievers may say: \"What Allah intends by this (curious) example ?\" Thus Allah leads astray whom He wills and guides whom He wills. And none can know the hosts of your Lord but He. And this (Hell) is nothing else than a (warning) reminder to mankind.', 'And We did not make wardens of the Fire but (from) angels, and did not fix their number but as a test for those who disbelieve, so that those who are given the Book may come to believe, and those who believe may improve in belief, and so that those who are given the Book and those who believe may not doubt (its correctness), and so that those having malady in their hearts and the disbelievers say, “What has Allah meant by this strange statement?” Thus Allah lets go astray whomever He wills, and leads to the right path whomever He wills. And no one knows the hosts of your Lord but He. And this is nothing else but a reminder for mankind.'),
(5527, 74, 32, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'کَلَّا  وَ  الۡقَمَرِ ﴿ۙ۳۲﴾', 'ہاں ہاں قسم ہے چاند کی۔', 'سچ کہتا ہوں اور قسم ہے چاند کی', 'Nay, and by the moon,', 'Truly, I swear by the moon,'),
(5528, 74, 33, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'وَ الَّیۡلِ  اِذۡ  اَدۡبَرَ ﴿ۙ۳۳﴾', 'اور رات کی جب رخصت ہونے لگے۔', 'اور رات کی جب پیٹھ پھیرے', 'And by the night when it withdraws,', 'and by the night when it goes back,'),
(5529, 74, 34, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'وَ  الصُّبۡحِ  اِذَاۤ   اَسۡفَرَ ﴿ۙ۳۴﴾', 'اور صبح کی جب روشن ہو جائے۔', 'اور صبح کی جب روشن ہووے', 'And by the dawn when it brightens,', 'and by the morning when it becomes bright,'),
(5530, 74, 35, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'اِنَّہَا  لَاِحۡدَی الۡکُبَرِ ﴿ۙ۳۵﴾', 'کہ وہ آگ ایک بہت بڑی آفت ہے۔', 'وہ ایک ہے بڑی چیزوں میں کی [۲۹]', 'Verily, it (Hell, or their denial of the Prophet Muhammad SAW , or the Day of Resurrection) is but one of the greatest calamities.', 'it (Saqar : Hell) is one of the greatest things'),
(5531, 74, 36, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'نَذِیۡرًا  لِّلۡبَشَرِ ﴿ۙ۳۶﴾', 'انسان کیلئے ڈر کی چیز۔', 'ڈرانے والی ہے لوگوں کو', 'A warning to mankind,', 'as a warning to the mankind,'),
(5532, 74, 37, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'لِمَنۡ شَآءَ مِنۡکُمۡ  اَنۡ  یَّتَقَدَّمَ اَوۡ یَتَاَخَّرَ ﴿ؕ۳۷﴾', 'یعنی اس شخص کیلئے جو تم میں سے آگے بڑھنا چاہے یا پیچھے رہنا چاہے۔', 'جو کوئی چاہے تم میں سے کہ آگے بڑھے یا پیچھے رہے [۳۰]', 'To any of you that chooses to go forward (by working righteous deeds), or to remain behind (by commiting sins),', 'to the one from among you who wishes to come forward (towards good deeds) or to go back (from them).'),
(5533, 74, 38, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'کُلُّ نَفۡسٍۭ بِمَا کَسَبَتۡ رَہِیۡنَۃٌ ﴿ۙ۳۸﴾', 'ہر شخص اپنے کرتوتوں کے باعث گرفتار ہو گا۔', 'ہر ایک جی اپنے کئے کاموں میں پھنسا ہوا ہے', 'Every person is a pledge for what he has earned,', 'Everyone will be detained (in the Hell) because of what he did,'),
(5534, 74, 39, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'اِلَّاۤ   اَصۡحٰبَ الۡیَمِیۡنِ ﴿ؕۛ۳۹﴾', 'مگر داہنی طرف والے نیک لوگ۔', 'مگر داہنی طرف والے', 'Except those on the Right, (i.e. the pious true believers of Islamic Monotheism);', 'except the People of the Right, (i.e. those who will be given their Book of Deeds in their right hands)'),
(5535, 74, 40, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'فِیۡ  جَنّٰتٍ ۟ؕۛ یَتَسَآءَلُوۡنَ ﴿ۙ۴۰﴾', 'جنتوں میں ہوں گے اور پوچھتے ہوں گے۔', 'باغوں میں ہیں مل کر پوچھتے ہیں', 'In Gardens (Paradise) they will ask one another,', 'who will be in gardens, asking'),
(5536, 74, 41, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'عَنِ  الۡمُجۡرِمِیۡنَ  ﴿ۙ۴۱﴾', 'یعنی آگ میں جلنے والے گنہگاروں سے۔', 'گنہگاروں کا حال [۳۱]', 'About Al-Mujrimoon (polytheists, criminals, disbelievers, etc.), (And they will say to them):', 'about the guilty persons,'),
(5537, 74, 42, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'مَا سَلَکَکُمۡ  فِیۡ سَقَرَ ﴿۴۲﴾', 'کہ تم دوزخ میں کیوں پڑے؟', 'تم کاہے سے جا پڑے دوزخ میں [۳۲]', '\"What has caused you to enter Hell?\"', '“What has brought you to Saqar? (Hell)”'),
(5538, 74, 43, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'قَالُوۡا  لَمۡ  نَکُ مِنَ الۡمُصَلِّیۡنَ ﴿ۙ۴۳﴾', 'وہ جواب دیں گے کہ ہم نمازیوں میں شامل نہ ہوئے۔', 'وہ بولے ہم نہ تھے نماز پڑھتے', 'They will say: \"We were not of those who used to offer their Salat (prayers)', 'They will say, “We were not among those who offered Salāh , (obligatory prayer)'),
(5539, 74, 44, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'وَ  لَمۡ نَکُ نُطۡعِمُ الۡمِسۡکِیۡنَ ﴿ۙ۴۴﴾', 'اور نہ ہم فقیروں کو کھانا کھلاتے تھے۔', 'اور نہ تھے کھانا کھلاتے محتاج کو', '\"Nor we used to feed Al-Miskin (the poor);', 'and we did not give food to the needy,'),
(5540, 74, 45, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'وَ  کُنَّا نَخُوۡضُ مَعَ  الۡخَآئِضِیۡنَ ﴿ۙ۴۵﴾', 'اور ہم بحث کرنیوالوں کے ساتھ مل کر بحث کرتے تھے۔', 'اور ہم تھے باتوں میں دھنستے دھنسنے والوں کے ساتھ', '\"And we used to talk falsehood (all that which Allah hated) with vain talkers .', 'and we indulged (in mocking at the truth) along with those who indulged,'),
(5541, 74, 46, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'وَ  کُنَّا نُکَذِّبُ بِیَوۡمِ الدِّیۡنِ ﴿ۙ۴۶﴾', 'اور روز جزا کو جھٹلاتے تھے۔', 'اور ہم تھے جھٹلاتے انصاف کے دن کو', '\"And we used to belie the Day of Recompense', 'and we used to deny the Day of Requital,'),
(5542, 74, 47, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'حَتّٰۤی  اَتٰىنَا الۡیَقِیۡنُ  ﴿ؕ۴۷﴾', 'یہاں تک کہ ہمیں موت آ گئ۔', 'یہاں تک یہ آ پہنچی ہم پر وہ یقینی بات [۳۳]', '\"Until there came to us (the death) that is certain.\"', 'until when we were overtaken by that which is certain.”'),
(5543, 74, 48, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'فَمَا تَنۡفَعُہُمۡ شَفَاعَۃُ  الشّٰفِعِیۡنَ ﴿ؕ۴۸﴾', 'تو سفارش کرنے والوں کی سفارش انکے حق میں کچھ فائدہ نہ دے گی۔', 'پھر کام نہ آئے گی اُنکے سفارش سفارش کرنے والوں کی [۳۴]', 'So no intercession of intercessors will be of any use to them.', 'Then intercession of intercessors will not benefit them.'),
(5544, 74, 49, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'فَمَا لَہُمۡ عَنِ التَّذۡکِرَۃِ  مُعۡرِضِیۡنَ ﴿ۙ۴۹﴾', 'انکو کیا ہوا ہے کہ نصیحت سے روگرداں ہو رہے ہیں۔', 'پھر کیا ہوا ہے انکو کہ نصیحت سے منہ موڑتے ہیں [۳۵]', 'Then what is wrong with them (i.e. the disbelievers) that they turn away from (receiving) admonition?', 'So what has happened to them that they are turning away from the Reminder,'),
(5545, 74, 50, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'کَاَنَّہُمۡ حُمُرٌ مُّسۡتَنۡفِرَۃٌ ﴿ۙ۵۰﴾', 'گویا گدھے ہیں کہ بدک جاتے ہیں۔', 'گویا کہ وہ گدھے ہیں بدکنے والے', 'As if they were frightened (wild) donkeys.', 'as if they were wild donkeys,'),
(5546, 74, 51, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'فَرَّتۡ مِنۡ قَسۡوَرَۃٍ ﴿ؕ۵۱﴾', 'جو شیر سے ڈر کر بھاگ جاتے ہیں۔', 'بھاگے ہیں غل مچانے سے [۳۶]', 'Fleeing from a hunter, or a lion, or a beast of prey.', 'fleeing from a lion?'),
(5547, 74, 52, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'بَلۡ یُرِیۡدُ کُلُّ امۡرِیًٔ  مِّنۡہُمۡ  اَنۡ یُّؤۡتٰی صُحُفًا مُّنَشَّرَۃً ﴿ۙ۵۲﴾', 'اصل یہ ہے کہ ان میں سے ہر شخص یہ چاہتا ہے کہ اس کے پاس کھلی ہوئی کتاب آئے۔', 'بلکہ چاہتا ہے ہر ایک مرد اُن میں کا کہ ملیں اُسکو ورق کھلے ہوئے [۳۷]', 'Nay, everyone of them desires that he should be given pages spread out (coming from Allah with a writing that Islam is the right religion, and Muhammad SAW has come with the truth from Allah the Lord of the heavens and earth, etc.).', 'Rather, every one of them wishes that he should be given unrolled (divine) scriptures.'),
(5548, 74, 53, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'کَلَّا ؕ بَلۡ  لَّا یَخَافُوۡنَ الۡاٰخِرَۃَ ﴿ؕ۵۳﴾', 'ایسا ہرگز نہیں ہوگا۔ حقیقت یہ ہے کہ انکو آخرت کا خوف ہی نہیں۔', 'ہرگز نہیں [۳۸] پر وہ ڈرتے نہیں آخرت سے [۳۹]', 'Nay! But they fear not the Hereafter (from Allahs punishment).', 'Never! But they do not fear the Hereafter.'),
(5549, 74, 54, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'کَلَّاۤ  اِنَّہٗ  تَذۡکِرَۃٌ ﴿ۚ۵۴﴾', 'کچھ شک نہیں کہ یہ قرآن نصیحت ہے۔', 'کوئی نہیں یہ تو نصیحت ہے [۴۰]', 'Nay, verily, this (Quran) is an admonition,', 'Never! Indeed, this is a Reminder.'),
(5550, 74, 55, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'فَمَنۡ  شَآءَ  ذَکَرَہٗ ﴿ؕ۵۵﴾', 'تو جو چاہے اسے یاد رکھے۔', 'پھر جو کوئی چاہے اُسکو یاد کرے [۴۱]', 'So whosoever will (let him read it), and receive admonition (from it)!', 'So, whoever so wishes may take advice from it.'),
(5551, 74, 56, 2, 16, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المدّثّر', 'وَ مَا یَذۡکُرُوۡنَ  اِلَّاۤ  اَنۡ یَّشَآءَ اللّٰہُ ؕ ہُوَ اَہۡلُ التَّقۡوٰی وَ اَہۡلُ الۡمَغۡفِرَۃِ ﴿٪۵۶﴾', 'اور یاد بھی تبھی رکھیں گے جب اللہ چاہے۔ وہی اس لائق ہے کہ اس سے ڈرا جائے اور وہی معاف کرنے والا ہے۔', 'اور وہ یاد جبھی کریں کہ چاہے اللہ [۴۲] وہی ہے جس سے ڈرناچاہیے اور وہی ہے بخشنے کے لائق [۴۳]', 'And they will not receive admonition unless Allah wills; He (Allah) is the One, deserving that mankind should be afraid of, and should be dutiful to Him, and should not take any Ilah (God) along with Him, and He is the One Who forgives (sins).', 'And they will not take advice unless Allah so wills. He is worthy to be feared, and worthy to forgive.'),
(5552, 75, 1, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'لَاۤ   اُقۡسِمُ   بِیَوۡمِ  الۡقِیٰمَۃِ ۙ﴿۱﴾', 'میں روز قیامت کی قسم کھاتا ہوں۔', 'قسم کھاتا ہوں قیامت کے دن کی  [۱]', 'I swear by the Day of Resurrection;', 'I swear by the Day of Resurrection,'),
(5553, 75, 2, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'وَ  لَاۤ   اُقۡسِمُ  بِالنَّفۡسِ اللَّوَّامَۃِ ؕ﴿۲﴾', 'اور نفس لوامہ کی قسم کھاتا ہوں کہ سب لوگ اٹھا کر کھڑے کئے جائیں گے۔', 'اور قسم کھاتا ہوں جی کی کہ جو ملامت کرے برائی پر [۲]', 'And I swear by the self-reproaching person (a believer).', 'and I swear by the self-reproaching conscience, (that Resurrection is a reality.)'),
(5554, 75, 3, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'اَیَحۡسَبُ الۡاِنۡسَانُ اَلَّنۡ نَّجۡمَعَ عِظَامَہٗ ؕ﴿۳﴾', 'کیا انسان یہ خیال کرتا ہے کہ ہم اسکی بکھری ہوئی ہڈیاں اکٹھی نہیں کریں گے؟', 'کیا خیال رکھتا ہے آدمی کہ جمع نہ کریں گے ہم اُسکی ہڈیاں [۳]', 'Does man (a disbeliever) think that We shall not assemble his bones?', 'Does man think that We will never reassemble his bones?'),
(5555, 75, 4, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'بَلٰی قٰدِرِیۡنَ  عَلٰۤی  اَنۡ  نُّسَوِّیَ بَنَانَہٗ ﴿۴﴾', 'ضرور کریں گے اور ہم اس بات پر قادر ہیں کہ اسکی پور پور درست کر دیں۔', 'کیوں نہیں ہم ٹھیک کر سکتے ہیں اُسکی پوریاں [۴]', 'Yes, We are Able to put together in perfect order the tips of his fingers.', 'Why (can We) not (do so), while We are able to reset (even) his fingertips perfectly?'),
(5556, 75, 5, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'بَلۡ یُرِیۡدُ الۡاِنۡسَانُ  لِیَفۡجُرَ  اَمَامَہٗ ۚ﴿۵﴾', 'مگر انسان چاہتا ہے کہ آئندہ بھی خودسری کرتا چلا جائے۔', 'بلکہ چاہتا ہے آدمی کہ ڈھٹائی کرے اُسکے سامنے', 'Nay! (Man denies Resurrection and Reckoning. So) he desires to continue committing sins.', 'But man wishes to go on violating Allah’s injunctions (even in future) ahead of him.'),
(5557, 75, 6, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'یَسۡـَٔلُ  اَیَّانَ یَوۡمُ الۡقِیٰمَۃِ ؕ﴿۶﴾', 'پوچھتا ہے کہ قیامت کا دن کب ہو گا؟', 'پوچھتا ہے کب ہو گا دن قیامت کا [۵]', 'He asks: \"When will be this Day of Resurrection?\"', 'He asks, “When will be this Day of Resurrection?”'),
(5558, 75, 7, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'فَاِذَا  بَرِقَ الۡبَصَرُ ۙ﴿۷﴾', 'سو جب آنکھیں چندھیا جائیں۔', 'پھر جب چندھیانے لگے آنکھ [۶]', 'So, when the sight shall be dazed,', 'So, when the eyes will be dazzled,'),
(5559, 75, 8, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'وَ  خَسَفَ الۡقَمَرُ ۙ﴿۸﴾', 'اور چاند گہنا جائے۔', 'اور گہہ جائے چاند [۷]', 'And the moon will be eclipsed,', 'and the moon will lose its light,'),
(5560, 75, 9, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'وَ  جُمِعَ الشَّمۡسُ وَ الۡقَمَرُ ۙ﴿۹﴾', 'اور سورج اور چاند جمع کر دیئے جائیں۔', 'اور اکٹھے ہوں سورج اور چاند [۸]', 'And the sun and moon will be joined together (by going one into the other or folded up or deprived of their light, etc.)', 'and the sun and the moon will be joined together,'),
(5561, 75, 10, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'یَقُوۡلُ  الۡاِنۡسَانُ یَوۡمَئِذٍ  اَیۡنَ الۡمَفَرُّ ﴿ۚ۱۰﴾', 'اس دن انسان کہے گا کہ کہاں ہے بھاگنے کی جگہ۔', 'کہے گا آدمی اُس دن کہاں چلا جاؤں بھاگ کر', 'On that Day man will say: \"Where (is the refuge) to flee?\"', 'on that day man will say, “Where to escape?”'),
(5562, 75, 11, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'کَلَّا  لَا وَزَرَ ﴿ؕ۱۱﴾', 'کہیں نہیں کوئی جائے پناہ نہیں۔', 'کوئی نہیں کہیں نہیں ہے بچاؤ', 'No! There is no refuge!', 'Never! There will be no refuge at all.'),
(5563, 75, 12, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'اِلٰی  رَبِّکَ یَوۡمَئِذِۣ  الۡمُسۡتَقَرُّ ﴿ؕ۱۲﴾', 'اس روز تمہارے پروردگار ہی کے پاس تمہیں جا ٹھہرنا ہے۔', 'تیرے رب تک ہے اُس دن جا ٹھہرنا [۹]', 'Unto your Lord (Alone) will be the place of rest that Day.', 'On that day, towards your Lord will be the destination (of everyone.)'),
(5564, 75, 13, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'یُنَبَّؤُا الۡاِنۡسَانُ یَوۡمَئِذٍۭ بِمَا قَدَّمَ وَ اَخَّرَ ﴿ؕ۱۳﴾', 'اس دن انسان کو جو عمل اس نے آگے بھیجے اور جو پیچھے چھوڑے ہوں گے سب بتا دیئے جائیں گے۔', 'جتلا دیں گے انسان کو اُس دن جو اُس نے آگے بھیجا اور پیچھے چھوڑا [۱۰]', 'On that Day man will be informed of what he sent forward (of his evil or good deeds), and what he left behind (of his good or evil traditions).', 'Man will be informed of what he sent ahead and what he left behind.'),
(5565, 75, 14, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'بَلِ الۡاِنۡسَانُ  عَلٰی نَفۡسِہٖ بَصِیۡرَۃٌ ﴿ۙ۱۴﴾', 'بلکہ انسان آپ اپنا گواہ ہے۔', 'بلکہ آدمی اپنے واسطے آپ دلیل ہے', 'Nay! Man will be a witness against himself (as his body parts (skin, hands, legs, etc.) will speak about his deeds).', 'Rather, man will be a witness against himself,'),
(5566, 75, 15, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'وَّ لَوۡ  اَلۡقٰی مَعَاذِیۡرَہٗ ﴿ؕ۱۵﴾', 'اگرچہ عذر و معذرت کرتا رہے۔', 'اور پڑالا ڈالے اپنے بہانے [۱۱]', 'Though he may put forth his excuses (to cover his evil deeds).', 'even though he may offer his excuses.'),
(5567, 75, 16, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'لَا تُحَرِّکۡ بِہٖ لِسَانَکَ لِتَعۡجَلَ بِہٖ ﴿ؕ۱۶﴾', 'اور اے پیغمبر ﷺ وحی کے پڑھنے کے لئے اپنی زبان کو تیز تیز حرکت نہ دیا کرو کہ اس کو جلد سیکھ لو۔', 'نہ چلا تو اُسکے پڑھنے پر اپنی زبان تاکہ جلدی اُسکو سیکھ لے', 'Move not your tongue concerning (the Quran, O Muhammad SAW) to make haste therewith.', '(O Prophet,) do not move your tongue (during revelation) for (reciting) it (the Qur’ān) to receive it in hurry.'),
(5568, 75, 17, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'اِنَّ عَلَیۡنَا جَمۡعَہٗ  وَ  قُرۡاٰنَہٗ ﴿ۚۖ۱۷﴾', 'اس کا جمع کرنا اور پڑھانا ہمارے ذمے ہے۔', 'وہ تو ہمارا ذمہ ہے اُسکو جمع رکھنا تیرے سینہ میں اور پڑھنا تیری زبان سے', 'It is for Us to collect it and to give you (O Muhammad SAW) the ability to recite it (the Quran),', 'It is surely undertaken by Us to store it (in your heart), and to let it be recited (by you after revelation is completed).'),
(5569, 75, 18, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'فَاِذَا قَرَاۡنٰہُ  فَاتَّبِعۡ  قُرۡاٰنَہٗ ﴿ۚ۱۸﴾', 'سو جب ہم اسے پڑھا کریں تو تم اسکو سنا کرو اور پھر اسی طرح پڑھا کرو۔', 'پھر جب ہم پڑھنے لگیں فرشتہ کی زبانی تو ساتھ رہ اُسکے پڑھنے کے', 'And when We have recited it to you (O Muhammad SAW through Jibrael (Gabriel)), then follow you its (the Qurans) recital.', 'Therefore, when it is recited by Us (through the angel), follow its recitation (by concentration of your heart).'),
(5570, 75, 19, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'ثُمَّ  اِنَّ عَلَیۡنَا بَیَانَہٗ ﴿ؕ۱۹﴾', 'پھر اسکے معانی کا بیان بھی ہمارے ذمے ہے۔', 'پھر مقرر ہمارا ذمہ ہے اُسکو کھول کر بتلانا [۱۲]', 'Then it is for Us (Allah) to make it clear to you,', 'Then, it is undertaken by Us to explain it.'),
(5571, 75, 20, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'کَلَّا بَلۡ  تُحِبُّوۡنَ الۡعَاجِلَۃَ ﴿ۙ۲۰﴾', 'مگر لوگو تم دنیا کو دوست رکھتے ہو۔', 'کوئی نہیں پر تم چاہتے ہو جو جلد آئے', 'Not (as you think, that you (mankind) will not be resurrected and recompensed for your deeds), but (you men) love the present life of this world,', 'Never, (your denial of Resurrection is never based on any sound reason!) Instead, you love that which is immediate,'),
(5572, 75, 21, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'وَ  تَذَرُوۡنَ  الۡاٰخِرَۃَ ﴿ؕ۲۱﴾', 'اور آخرت کو چھوڑے دیتے ہو۔', 'اور چھوڑتے ہو جو دیر میں آئے [۱۳]', 'And leave (neglect) the Hereafter.', 'and neglect the Hereafter.'),
(5573, 75, 22, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'وُجُوۡہٌ   یَّوۡمَئِذٍ  نَّاضِرَۃٌ ﴿ۙ۲۲﴾', 'اس روز بعض چہرے رونق دار ہوں گے۔', 'کتنے منہ اس دن تازہ ہیں', 'Some faces that Day shall be Nadirah (shining and radiant).', 'Many faces, that day, will be glowing,'),
(5574, 75, 23, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'اِلٰی رَبِّہَا نَاظِرَۃٌ ﴿ۚ۲۳﴾', 'اپنے پروردگار کی طرف نظر کئے ہوں گے۔', 'اپنے رب کی طرف دیکھنے والے [۱۴]', 'Looking at their Lord (Allah);', 'looking towards their Lord,'),
(5575, 75, 24, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'وَ  وُجُوۡہٌ  یَّوۡمَئِذٍۭ بَاسِرَۃٌ ﴿ۙ۲۴﴾', 'اور بہت سے چہرے اس دن اداس ہوں گے۔', 'اور کتنے منہ اُس دن اداس ہیں [۱۵]', 'And some faces, that Day, will be Basirah (dark, gloomy, frowning, and sad),', 'and many faces, that day, will be gloomy,'),
(5576, 75, 25, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'تَظُنُّ  اَنۡ  یُّفۡعَلَ بِہَا فَاقِرَۃٌ ﴿ؕ۲۵﴾', 'خیال کریں گے کہ ان کے ساتھ کمر توڑ معاملہ کیا جائے گا۔', 'خیال کرتے ہیں کہ اُن پر وہ آئے جس سے ٹوٹے کمر [۱۶]', 'Thinking that some calamity was about to fall on them;', 'realizing that a back-breaking calamity is going to be afflicted on them.'),
(5577, 75, 26, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'کَلَّاۤ  اِذَا بَلَغَتِ التَّرَاقِیَ ﴿ۙ۲۶﴾', 'ہاں جب جان گلے تک پہنچ جائے۔', 'ہرگز نہیں جس وقت جان پہنچے ہانس تک [۱۷]', 'Nay, when (the soul) reaches to the collar bone (i.e. up to the throat in its exit),', 'Never, (you will never remain in this world forever!) When the soul (of a patient) reaches the clavicles,'),
(5578, 75, 27, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'وَ  قِیۡلَ  مَنۡ ٜ رَاقٍ ﴿ۙ۲۷﴾', 'اور لوگ کہنے لگیں اس وقت کون جھاڑ پھونک کرنے والا ہے۔', 'اور لوگ کہیں کون ہے جھاڑنے والا [۱۸]', 'And it will be said: \"Who can cure him and save him from death?\"', 'and it is said, “Who is an enchanter (that can save him?)”'),
(5579, 75, 28, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'وَّ  ظَنَّ  اَنَّہُ  الۡفِرَاقُ ﴿ۙ۲۸﴾', 'اور اس جان بلب نے سمجھا کہ اب جدائی کا وقت ہے۔', 'اور وہ سمجھا  کہ اب آیا وقت جدائی کا [۱۹]', 'And he (the dying person) will conclude that it was (the time) of departing (death);', 'and he realizes that it is (the time of) departure (from the world,)'),
(5580, 75, 29, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'وَ  الۡتَفَّتِ السَّاقُ بِالسَّاقِ ﴿ۙ۲۹﴾', 'اور پنڈلی سے پنڈلی لپٹ جائے۔', 'اور لپٹ گئ پنڈلی پر پنڈلی [۲۰]', 'And leg will be joined with another leg (shrouded)', 'and one shank is intertwined with the other shank,'),
(5581, 75, 30, 1, 17, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'اِلٰی رَبِّکَ یَوۡمَئِذِۣ الۡمَسَاقُ ﴿ؕ٪۳۰﴾', 'اس دن تجھ کو اپنے پروردگار کی طرف کھنچے چلے چلنا ہے۔', 'تیرے رب کی طرف ہے اُس دن کھنچ کر چلا جانا [۲۱]', 'The drive will be, on that Day, to your Lord (Allah)!', 'then on that day, it is to your Lord that one has to be driven.'),
(5582, 75, 31, 2, 18, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'فَلَا  صَدَّقَ  وَ لَا صَلّٰی ﴿ۙ۳۱﴾', 'پھر ایسے مغرور نے نہ تو پیغمبر ﷺ کو سچا جانا اور نہ نماز پڑھی۔', 'پھر نہ یقین لایا اور نہ نماز پڑھی', 'So he (the disbeliever) neither believed (in this Quran, in the Message of Muhammad SAW) nor prayed!', 'So (the denier of the Hereafter) neither believed, nor prayed,'),
(5583, 75, 32, 2, 18, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'وَ  لٰکِنۡ  کَذَّبَ وَ تَوَلّٰی ﴿ۙ۳۲﴾', 'لیکن جھٹلایا اور منہ پھیر لیا۔', 'پھر جھٹلایا اور منہ موڑا', 'But on the contrary, he belied (this Quran and the Message of Muhammad SAW) and turned away!', 'but rejected the truth and turned away (from it),'),
(5584, 75, 33, 2, 18, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'ثُمَّ  ذَہَبَ  اِلٰۤی  اَہۡلِہٖ یَتَمَطّٰی ﴿ؕ۳۳﴾', 'پھر اپنے گھر والوں کے پاس اکڑتا ہوا چل دیا۔', 'پھر گیا اپنے گھر کو اکڑتا ہوا [۲۲]', 'Then he walked in full pride to his family admiring himself!', 'then he went to his home, puffed up with pride.'),
(5585, 75, 34, 2, 18, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'اَوۡلٰی لَکَ فَاَوۡلٰی ﴿ۙ۳۴﴾', 'خرابی ہے تیری خرابی پر خرابی ہے۔', 'خرابی تیری خرابی پر خرابی تیری', 'Woe to you (O man (disbeliever))! And then (again) woe to you!', '(It will be said to such a man,) Woe to you, then woe to you!'),
(5586, 75, 35, 2, 18, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'ثُمَّ  اَوۡلٰی لَکَ  فَاَوۡلٰی  ﴿ؕ۳۵﴾', 'پھر خرابی ہے تیری خرابی پر خرابی ہے۔', 'پھر خرابی تیری خرابی پر خرابی تیری [۲۳]', 'Again, woe to you (O man (disbeliever))! And then (again) woe to you!', 'Again, woe to you, then woe to you!'),
(5587, 75, 36, 2, 18, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'اَیَحۡسَبُ  الۡاِنۡسَانُ اَنۡ یُّتۡرَکَ سُدًی  ﴿ؕ۳۶﴾', 'کیا انسان خیال یہ کرتا ہے کہ اسے یونہی چھوڑ دیا جائے گا؟', 'کیا خیال رکھتا ہے آدمی کہ چھوٹا رہے گا بے قید [۲۴]', 'Does man think that he will be left Suda (neglected without being punished or rewarded for the obligatory duties enjoined by his Lord (Allah) on him)?', 'Does man presume that he will be left unchecked?'),
(5588, 75, 37, 2, 18, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'اَلَمۡ  یَکُ نُطۡفَۃً  مِّنۡ  مَّنِیٍّ یُّمۡنٰی ﴿ۙ۳۷﴾', 'کیا وہ منی کا جو ٹپکائی جاتی ہے ایک قطرہ نہ تھا؟', 'بھلا نہ تھا وہ ایک بوند منی کی جو ٹپکی [۲۵]', 'Was he not a Nutfah (mixed male and female discharge of semen) poured forth?', 'Was he not an ejaculated drop of semen?'),
(5589, 75, 38, 2, 18, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'ثُمَّ  کَانَ عَلَقَۃً  فَخَلَقَ فَسَوّٰی  ﴿ۙ۳۸﴾', 'پھر لوتھڑا ہوا پھر اللہ نے اسکو بنایا۔ سو اسکے اعضاء کو درست کیا۔', 'پھر تھا لہو جما ہوا پھر اُس نے بنایا اور ٹھیک کر اٹھایا', 'Then he became an Alaqa (a clot); then (Allah) shaped and fashioned (him) in due proportion.', 'Then he became a clot of blood, then He created (him) and made (him) perfect,'),
(5590, 75, 39, 2, 18, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'فَجَعَلَ مِنۡہُ  الزَّوۡجَیۡنِ الذَّکَرَ  وَ الۡاُنۡثٰی ﴿ؕ۳۹﴾', 'پھر اس کی دو قسمیں بنائیں مرد اور عورت۔', 'پھر کیا اُس میں جوڑا نر اور مادہ', 'And made him in two sexes, male and female.', 'and made from him two kinds, male and female.'),
(5591, 75, 40, 2, 18, 29, 'تَبٰرَکَ الَّذِیۡ ', 'القیٰمۃ', 'اَلَیۡسَ ذٰلِکَ بِقٰدِرٍ عَلٰۤی  اَنۡ یُّحۡیَِۧ  الۡمَوۡتٰی ﴿٪۴۰﴾', 'کیا اسکو اس بات پر قدرت نہیں کہ مردوں کو زندہ کر دے۔', 'کیا یہ خدا زندہ نہیں کر سکتا مردوں کو [۲۶]', 'Is not He (Allah Who does that), Able to give life to the dead? (Yes! He is Able to do all things).', 'Has He no power to give life to the dead?'),
(5592, 76, 1, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'ہَلۡ  اَتٰی عَلَی الۡاِنۡسَانِ حِیۡنٌ مِّنَ الدَّہۡرِ  لَمۡ  یَکُنۡ شَیۡئًا مَّذۡکُوۡرًا ﴿۱﴾', 'بیشک انسان پر زمانے میں ایک ایسا وقت بھی آ چکا ہے کہ وہ کوئی قابل ذکر چیز نہ تھا۔', 'کبھی گذرا ہے انسان پر ایک وقت زمانے میں کہ نہ تھا وہ کوئی چیز جو زبان پر آتی [۱]', 'Has there not been over man a period of time, when he was nothing to be mentioned?', 'There has come upon man a period of time in which he was nothing worth mentioning.');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(5593, 76, 2, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'اِنَّا خَلَقۡنَا الۡاِنۡسَانَ مِنۡ نُّطۡفَۃٍ  اَمۡشَاجٍ ٭ۖ  نَّبۡتَلِیۡہِ  فَجَعَلۡنٰہُ سَمِیۡعًۢا بَصِیۡرًا ﴿۲﴾', 'ہم نے انسان کو ملے جلے نطفہ سے پیدا کیا تاکہ اسے آزمائیں تو ہم نے اسکو سنتا دیکھتا بنایا۔', 'ہم نے بنایا آدمی کو ایک دو  رنگی بوند سے [۲] ہم پلٹتے رہے اُسکو پھر کر دیا اُسکو ہم نے سننے والا دیکھنے والا [۳]', 'Verily, We have created man from Nutfah drops of mixed semen (discharge of man and woman), in order to try him, so We made him hearer, seer.', 'We have created man from a mixed sperm-drop to put him to a test; then We made him able to hear, able to see.'),
(5594, 76, 3, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'اِنَّا ہَدَیۡنٰہُ  السَّبِیۡلَ  اِمَّا شَاکِرًا وَّ اِمَّا کَفُوۡرًا ﴿۳﴾', 'یقینًا ہم ہی نے اسے رستہ بھی دکھا دیا۔ اب خواہ شکرگذار ہو خواہ ناشکرا۔', 'ہم نے اُسکو سجھائی راہ یا حق مانتا ہے اور یا ناشکری کرتا ہے [۴]', 'Verily, We showed him the way, whether he be grateful or ungrateful.', 'We have shown him the way to be either grateful or ungrateful.'),
(5595, 76, 4, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'اِنَّاۤ  اَعۡتَدۡنَا  لِلۡکٰفِرِیۡنَ سَلٰسِلَا۠ وَ اَغۡلٰلًا  وَّ  سَعِیۡرًا ﴿۴﴾', 'بیشک ہم نے کافروں کے لئے زنجیریں اور طوق اور دہکتی آگ تیار کر رکھی ہے۔', 'ہم نے تیار کر رکھی ہیں منکروں کے واسطے زنجیریں اور طوق اور آگ دہکتی [۵]', 'Verily, We have prepared for the disbelievers iron chains, iron collars, and a blazing Fire.', 'We have prepared, for the disbelievers, shackles and iron-collars and a blazing Fire.'),
(5596, 76, 5, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'اِنَّ  الۡاَبۡرَارَ  یَشۡرَبُوۡنَ مِنۡ کَاۡسٍ کَانَ مِزَاجُہَا  کَافُوۡرًا ۚ﴿۵﴾', 'جو نیکوکار ہیں وہ ایسی شراب پئیں گے جس میں کافور کی آمیزش ہو گی۔', 'البتہ نیک لوگ پیتے ہیں پیالہ جس کی ملونی ہے کافور', 'Verily, the Abrar (pious, who fear Allah and avoid evil), shall drink a cup (of wine) mixed with water from a spring in Paradise called Kafoor.', 'Indeed, the righteous will have a drink from a goblet, blended with (a drink from) Camphor'),
(5597, 76, 6, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'عَیۡنًا یَّشۡرَبُ بِہَا عِبَادُ اللّٰہِ یُفَجِّرُوۡنَہَا تَفۡجِیۡرًا ﴿۶﴾', 'یہ ایک چشمہ ہے جس میں سے اللہ کے بندے پئیں گے اور اس میں سے چھوٹی چھوٹی نہریں نکال لیں گے۔', 'ایک چشمہ ہے جس سے پیتے ہیں بندے اللہ کے [۶] چلاتے ہیں وہ اُسکی نالیاں [۷]', 'A spring wherefrom the slaves of Allah will drink, causing it to gush forth abundantly.', 'that will be a spring from which Allah’s servants will drink, making it flow (wherever they wish) profusely.'),
(5598, 76, 7, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'یُوۡفُوۡنَ بِالنَّذۡرِ وَ یَخَافُوۡنَ یَوۡمًا کَانَ شَرُّہٗ  مُسۡتَطِیۡرًا ﴿۷﴾', 'یہ لوگ نذریں پوری کرتے ہیں اور اس دن سے جس کی سختی پھیل رہی ہو گی خوف رکھتے ہیں۔', 'پورا کرتے ہیں منت کو [۸] اور ڈرتے ہیں اس دن سے کہ اُسکی برائی  پھیل پڑے گی [۹]', 'They (are those who) fulfill (their) vows, and they fear a Day whose evil will be wide-spreading.', 'They (are the ones who) fulfill their vows, and fear a day whose evil (events) will spread far and wide,'),
(5599, 76, 8, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'وَ یُطۡعِمُوۡنَ  الطَّعَامَ عَلٰی حُبِّہٖ مِسۡکِیۡنًا وَّ  یَتِیۡمًا  وَّ  اَسِیۡرًا ﴿۸﴾', 'اور باوجودیکہ ان کو خود کھانے کی چاہت ہوتی ہے مگر فقیروں اور یتیموں اور قیدیوں کو کھلاتے ہیں۔', 'اور کھلاتے ہیں کھانا اُسکی محبت پر محتاج کو اور یتیم کو اور قیدی کو [۱۰]', 'And they give food, inspite of their love for it (or for the love of Him), to Miskin (poor), the orphan, and the captive,', 'and they give food, out of their love for Him (Allah), to the needy, and the orphan, and the captive,'),
(5600, 76, 9, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'اِنَّمَا نُطۡعِمُکُمۡ لِوَجۡہِ اللّٰہِ لَا نُرِیۡدُ مِنۡکُمۡ جَزَآءً   وَّ  لَا  شُکُوۡرًا ﴿۹﴾', 'اور کہتے ہیں کہ ہم تمکو محض اللہ کی خوشنودی کیلئے کھلاتے ہیں۔ نہ تم سے بدلہ چاہتے ہیں اور نہ شکرگذاری۔', 'ہم جو تم کو کھلاتے ہیں سو خالص اللہ کی خوشی چاہنے کو نہ تم سے ہم چاہیں گے بدلا اور نہ چاہیں گے شکرگذاری [۱۱]', '(Saying): \"We feed you seeking Allahs Countenance only. We wish for no reward, nor thanks from you.', '(saying to them,) “We feed you only for the sake of Allah; we have no intention of (receiving) either a return from you or thanks.'),
(5601, 76, 10, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'اِنَّا نَخَافُ مِنۡ رَّبِّنَا یَوۡمًا عَبُوۡسًا قَمۡطَرِیۡرًا ﴿۱۰﴾', 'ہم کو اپنے پروردگار سے اس دن کا ڈر لگتا ہے جو چہروں کو بگاڑنے والا اور بڑی سختی والا ہو گا۔', 'ہم ڈرتے ہیں اپنے رب سے ایک دن اداسی والے کی سختی سے [۱۲]', '\"Verily, We fear from our Lord a Day, hard and distressful, that will make the faces look horrible (from extreme dislikeness to it).\"', 'In fact, we are fearful of a day, from the side of our Lord, that will be frowning, extremely malignant.”'),
(5602, 76, 11, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'فَوَقٰہُمُ  اللّٰہُ  شَرَّ ذٰلِکَ  الۡیَوۡمِ وَ لَقّٰہُمۡ نَضۡرَۃً   وَّ  سُرُوۡرًا ﴿ۚ۱۱﴾', 'چنانچہ اللہ انکو اس دن کی سختی سے بچا لے گا۔ اور تازگی اور خوشی عنایت فرمائے گا۔', 'پھر بچا لیا اُنکو اللہ نے برائی سے اس دن کی اور ملا دی اُنکو تازگی اور خوشی وقتی [۱۳]', 'So Allah saved them from the evil of that Day, and gave them Nadratan (a light of beauty) and joy.', 'So Allah will save them from the evil of that day, and will grant them bloom and delight,'),
(5603, 76, 12, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'وَ جَزٰىہُمۡ  بِمَا صَبَرُوۡا جَنَّۃً  وَّ حَرِیۡرًا ﴿ۙ۱۲﴾', 'اور انکے صبر کے بدلے انکو بہشت اور ریشمی لباس عطا کرے گا۔', 'اور بدلا دیا اُنکو اُنکے صبر پرباغ اور پوشاک ریشمی [۱۴]', 'And their recompense shall be Paradise, and silken garments, because they were patient.', 'and will give them, in return for their patience, Paradise and (garments of) silk,'),
(5604, 76, 13, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'مُّتَّکِـِٕیۡنَ فِیۡہَا عَلَی الۡاَرَآئِکِ ۚ لَا یَرَوۡنَ فِیۡہَا شَمۡسًا وَّ  لَا  زَمۡہَرِیۡرًا ﴿ۚ۱۳﴾', 'اس میں وہ تختوں پر تکئے لگائے بیٹھے ہوں گے۔ وہاں نہ دھوپ کی حدّت دیکھیں گے نہ سردی کی شدت۔', 'تکیہ لگائے بیٹھیں اُس میں تختوں کے اوپر [۱۵] نہیں دیکھتے وہاں دھوپ اور نہ ٹھِر [۱۶]', 'Reclining therein on raised thrones, they will see there neither the excessive heat of the sun, nor the excessive bitter cold, (as in Paradise there is no sun and no moon).', 'wherein they will be reclining on couches, feeling neither heat of the sun nor intense cold.'),
(5605, 76, 14, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'وَ دَانِیَۃً  عَلَیۡہِمۡ  ظِلٰلُہَا وَ ذُلِّلَتۡ قُطُوۡفُہَا تَذۡلِیۡلًا ﴿۱۴﴾', 'ان پر درختوں کے سائے قریب ہوں گے اور میووں کے گچھے جھکے ہوئے لٹک رہے ہوں گے۔', 'اور جھک رہیں اُن پر اسکی چھائیں اور پست کر رکھے ہیں اُسکے گچھے لٹکا کر [۱۷]', 'And the shade thereof is close upon them, and the bunches of fruit thereof will hang low within their reach.', 'And shades of gardens will be hanging low on them, and their fruits will be placed totally under their command.'),
(5606, 76, 15, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'وَ یُطَافُ عَلَیۡہِمۡ  بِاٰنِیَۃٍ  مِّنۡ  فِضَّۃٍ وَّ اَکۡوَابٍ کَانَتۡ قَؔوَارِیۡرَا۠ ﴿ۙ۱۵﴾', 'اور خدّام چاندی کے برتن لئے ہوئے انکے اردگرد پھریں گے اور شیشے کے نہایت شفاف پیالے۔', 'اور لوگ لئے پھرتے ہیں اُنکے پاس برتن چاندی کے اور آبخورے جو ہو رہے ہیں شیشے کے', 'And amongst them will be passed round vessels of silver and cups of crystal,', 'Circulated among them will be vessels of silver, and cups that will be (as transparent as) crystals,'),
(5607, 76, 16, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'قَؔ‍وَارِیۡرَا۠ مِنۡ فِضَّۃٍ  قَدَّرُوۡہَا تَقۡدِیۡرًا ﴿۱۶﴾', 'اور شیشے بھی چاندی کے جو ٹھیک اندازے کے مطابق بنائے گئے ہیں۔', 'شیشے ہیں چاندی کے [۱۸] ماپ رکھا ہے اُن کاماپ [۱۹]', 'Crystal-clear, made of silver. They will determine the measure thereof according to their wishes.', '-crystals (as shining as if made) of silver, measured by those (who filled them) with due measure.'),
(5608, 76, 17, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'وَ یُسۡقَوۡنَ  فِیۡہَا کَاۡسًا کَانَ مِزَاجُہَا زَنۡجَبِیۡلًا ﴿ۚ۱۷﴾', 'اور وہاں انکو ایسی شراب بھی پلائی جائے گی جس میں ادرک کی آمیزش ہو گی۔', 'اور اُنکو  وہاں پلاتے ہیں پیالے جس کی مِلونی ہے سونٹھ [۲۰]', 'And they will be given to drink there a cup (of wine) mixed with Zanjabeel (ginger, etc.),', 'And they will be served with goblet of a drink blended with ginger,'),
(5609, 76, 18, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'عَیۡنًا فِیۡہَا تُسَمّٰی سَلۡسَبِیۡلًا ﴿۱۸﴾', 'یہ بہشت میں ایک چشمہ ہے جس کا نام سلسبیل ہے۔', 'ایک چشمہ ہے اُس میں اُس کا نام کہتے ہیں سلسبیل [۲۱]', 'A spring there, called Salsabeel.', '(acquired from) a spring therein called Salsabīl.'),
(5610, 76, 19, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'وَ یَطُوۡفُ عَلَیۡہِمۡ وِلۡدَانٌ  مُّخَلَّدُوۡنَ ۚ اِذَا  رَاَیۡتَہُمۡ حَسِبۡتَہُمۡ  لُؤۡلُؤًا مَّنۡثُوۡرًا ﴿۱۹﴾', 'اور انکے پاس لڑکے آتے جاتے ہوں گے۔ جو ہمیشہ ایک ہی حالت پر رہیں گے۔ جب تم ان پر نگاہ ڈالو تو خیال کرو کہ بکھرے ہوئے موتی ہیں۔', 'اور پھرتے ہیں اُنکے پاس لڑکے سدا رہنے والے [۲۲] جب تو اُنکو دیکھے خیال کرے کہ موتی ہیں بکھرے ہوئے [۲۳]', 'And round about them will (serve) boys of everlasting youth. If you see them, you would think them scattered pearls.', 'And circling around them will be serving boys, blessed with eternal youth; when you would see them, you would take them as scattered pearls.'),
(5611, 76, 20, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'وَ اِذَا  رَاَیۡتَ ثَمَّ رَاَیۡتَ نَعِیۡمًا وَّ مُلۡکًا کَبِیۡرًا ﴿۲۰﴾', 'اور بہشت میں جہاں آنکھ اٹھاؤ گے کثرت سے نعمت اور عظیم الشان سلطنت دیکھو گے۔', 'اور جب تو دیکھے وہاں تو دیکھے نعمت اور سلطنت بڑی [۲۴]', 'And when you look there (in Paradise), you will see a delight (that cannot be imagined), and a great dominion.', 'When you will look around there, you will see the Bliss and a magnificent realm.'),
(5612, 76, 21, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'عٰلِیَہُمۡ  ثِیَابُ سُنۡدُسٍ خُضۡرٌ وَّ اِسۡتَبۡرَقٌ ۫ وَّ حُلُّوۡۤا  اَسَاوِرَ مِنۡ فِضَّۃٍ ۚ وَ  سَقٰہُمۡ  رَبُّہُمۡ  شَرَابًا طَہُوۡرًا ﴿۲۱﴾', 'ان کے جسموں پر دیبا اور اطلس کے سبز کپڑے ہوں گے۔ اور انہیں چاندی کے کنگن پہنائے جائیں گے۔ اور ان کا پروردگار انکو نہایت پاکیزہ مشروب پلائے گا۔', 'اوپر کی پوشاک انکی کپڑے ہیں باریک ریشم کے سبز اور گاڑھے [۲۵] اور انکو پہنائے جائیں گے کنگن چاندی کے [۲۶] اور پلائے اُنکو اُنکا رب شراب جو پاک کرے دل کو [۲۷]', 'Their garments will be of fine green silk, and gold embroidery. They will be adorned with bracelets of silver, and their Lord will give them a pure drink.', 'Upon them will be garments of green sundus (a kind of fine silk), and of istabraq (a kind of thick silk), and they will be adorned by bracelets of silver. Their Lord will give them a pure beverage to drink:'),
(5613, 76, 22, 1, 19, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'اِنَّ  ہٰذَا کَانَ لَکُمۡ جَزَآءً وَّ کَانَ سَعۡیُکُمۡ  مَّشۡکُوۡرًا ﴿٪۲۲﴾', 'فرمائے گا یہ تمہارا صلہ ہے اور تمہاری محنت ہمارے ہاں مقبول ہوئی۔', 'یہ ہے تمہارا بدلا اور کمائی تمہاری ٹھکانے لگی [۲۸]', '(And it will be said to them): \"Verily, this is a reward for you, and your endeavour has been accepted.\"', '“This is a reward for you, and your effort has been appreciated.”'),
(5614, 76, 23, 2, 20, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'اِنَّا نَحۡنُ نَزَّلۡنَا عَلَیۡکَ الۡقُرۡاٰنَ تَنۡزِیۡلًا ﴿ۚ۲۳﴾', 'اے نبی ﷺ ہم نے تم پر قرآن بتدریج نازل کیا ہے۔', 'ہم  نے اتارا تجھ پر قرآن سہج سہج اتارنا', 'Verily! It is We Who have sent down the Quran to you (O Muhammad SAW) by stages.', 'Indeed we have revealed to you the Qur’ān through a gradual process.'),
(5615, 76, 24, 2, 20, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'فَاصۡبِرۡ لِحُکۡمِ رَبِّکَ وَ لَا تُطِعۡ مِنۡہُمۡ اٰثِمًا  اَوۡ  کَفُوۡرًا ﴿ۚ۲۴﴾', 'تو اپنے پروردگار کے فیصلے کیلئے انتظار کئے رہو اور ان لوگوں میں سے کسی بدعمل اور ناشکرے کا کہا نہ ماننا۔', 'سو تو انتظار کر اپنے رب کے حکم کا [۲۹] اور کہنامت مان اُن میں سے کسی گنہگار  یا ناشکر کا [۳۰]', 'Therefore be patient (O Muhammad SAW) and submit to the Command of your Lord (Allah, by doing your duty to Him and by conveying His Message to mankind), and obey neither a sinner nor a disbeliever among them.', 'So, be steadfast patiently in (obeying) your Lord’s command, and do not obey any one of them who is sinner or ungrateful.'),
(5616, 76, 25, 2, 20, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'وَ اذۡکُرِ اسۡمَ  رَبِّکَ بُکۡرَۃً  وَّ اَصِیۡلًا ﴿ۖۚ۲۵﴾', 'اور صبح و شام اپنے پروردگار کا نام لیتے رہو۔', 'اور لیتا رہ نام اپنے رب کا صبح اور شام [۳۱]', 'And remember the Name of your Lord every morning and afternoon (i.e. offering of the Morning (Fajr), Zuhr, and Asr prayers).', 'And pronounce the name of Allah morning and evening.'),
(5617, 76, 26, 2, 20, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'وَ مِنَ الَّیۡلِ فَاسۡجُدۡ لَہٗ  وَ سَبِّحۡہُ  لَیۡلًا طَوِیۡلًا ﴿۲۶﴾', 'اور رات کو بڑی رات تک اسکے آگے سجدے کرو اور اسکی پاکی بیان کرتے رہو۔', 'اور کسی وقت رات کو سجدہ کر اُسکو [۳۲] اور پاکی بول اُسکی بڑی رات تک [۳۳]', 'And during night, prostrate yourself to Him (i.e. the offering of Maghrib and Isha prayers), and glorify Him a long night through (i.e. Tahajjud prayer).', 'And in some parts of night prostrate yourself before Him, and pronounce His purity for long times at night.'),
(5618, 76, 27, 2, 20, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'اِنَّ  ہٰۤؤُلَآءِ  یُحِبُّوۡنَ الۡعَاجِلَۃَ  وَ یَذَرُوۡنَ  وَرَآءَہُمۡ  یَوۡمًا ثَقِیۡلًا ﴿۲۷﴾', 'یہ لوگ دنیا کو دوست رکھتے ہیں اور قیامت کے بھاری دن کو پس پشت چھوڑے دیتے ہیں۔', 'یہ لوگ چاہتے ہیں جلدی ملنے والے کو اور چھوڑ رکھا ہے اپنے پیچھے ایک بھاری دن کو [۳۴]', 'Verily! These (disbelievers) love the present life of this world, and put behind them a heavy Day (that will be hard).', 'In fact these people love that which is immediate, and neglect a Heavy Day ahead of them.'),
(5619, 76, 28, 2, 20, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'نَحۡنُ خَلَقۡنٰہُمۡ وَ شَدَدۡنَاۤ  اَسۡرَہُمۡ ۚ وَ اِذَا شِئۡنَا بَدَّلۡنَاۤ  اَمۡثَالَہُمۡ  تَبۡدِیۡلًا ﴿۲۸﴾', 'ہم نے انکو پیدا کیا اور انکے جوڑ جوڑ کو مضبوط بنایا۔ اور اگر ہم چاہیں تو ان کے بدلے انہی کی طرح اور لوگ لے آئیں۔', 'ہم نے اُنکو بنایا اور مضبوط کیا اُنکی جوڑ بندی کو اور جب ہم چاہیں بدل لائیں اُن جیسے لوگ بدل کر [۳۵]', 'It is We Who created them, and We have made them of strong built. And when We will, We can replace them with others like them with a complete replacement.', 'We have created them and have made their joints strong. And whenever We will, We would replace them with others like them, a total replacement.'),
(5620, 76, 29, 2, 20, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'اِنَّ ہٰذِہٖ  تَذۡکِرَۃٌ ۚ فَمَنۡ شَآءَ  اتَّخَذَ  اِلٰی رَبِّہٖ  سَبِیۡلًا ﴿۲۹﴾', 'یہ قرآن تو نصیحت ہے جو چاہے اپنے پروردگار کی طرف پہنچنے کا راستہ اختیار کر لے۔', 'یہ تو نصیحت ہے پھر جو کوئی چاہے کر  رکھے اپنے رب تک راہ [۳۶]', 'Verily! This (Verses of the Quran) is an admonition, so whosoever wills, let him take a Path to his Lord (Allah).', 'Indeed, this is a reminder; so let anyone who so wishes, adopt a way to his Lord.'),
(5621, 76, 30, 2, 20, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'وَ مَا تَشَآءُوۡنَ  اِلَّاۤ  اَنۡ  یَّشَآءَ اللّٰہُ ؕ اِنَّ اللّٰہَ  کَانَ عَلِیۡمًا حَکِیۡمًا ﴿٭ۖ۳۰﴾', 'اور تم کچھ بھی نہیں چاہ سکتے مگر جو اللہ کو منظور ہو بیشک اللہ جاننے والا ہے حکمت والا ہے۔', 'اور تم نہیں چاہو گے مگر جو چاہے اللہ بیشک اللہ ہے سب کچھ جاننے والا حکمتوں والا [۳۷]', 'But you cannot will, unless Allah wills. Verily, Allah is Ever All-Knowing, All-Wise.', 'And you will not so wish unless Allah so wills. Indeed Allah is All-Knowing, All-Wise.'),
(5622, 76, 31, 2, 20, 29, 'تَبٰرَکَ الَّذِیۡ ', 'الانسان', 'یُّدۡخِلُ  مَنۡ  یَّشَآءُ  فِیۡ  رَحۡمَتِہٖ ؕ وَ الظّٰلِمِیۡنَ  اَعَدَّ  لَہُمۡ عَذَابًا  اَلِیۡمًا ﴿٪۳۱﴾', 'وہ جسکو چاہتا ہے اپنی رحمت میں داخل کر لیتا ہے۔ اور ظالموں کے لئے اس نے دکھ دینے والا عذاب تیار کر رکھا ہے۔', 'داخل کر لے جسکو چاہے اپنی رحمت میں [۳۸] اور جو گنہگار ہیں تیار ہے اُنکے واسطے عذاب دردناک', 'He will admit to His Mercy whom He will and as for the Zalimoon, (polytheists, wrong-doers, etc.) He has prepared a painful torment.', 'He admits whomsoever He wills to His mercy. As for the wrongdoers, He has prepared for them a painful punishment.'),
(5623, 77, 1, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَ الۡمُرۡسَلٰتِ  عُرۡفًا ۙ﴿۱﴾', 'ہواؤں کی قسم جو نرم نرم چلتی ہیں۔', 'قسم ہے چلتی ہواؤں کی دل کو خوش آتی', 'By the winds (or angels or the Messengers of Allah) sent forth one after another.', '(I swear) by those (winds) that are sent one after the other,'),
(5624, 77, 2, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'فَالۡعٰصِفٰتِ عَصۡفًا ۙ﴿۲﴾', 'پھر زور پکڑ کر جھکڑ ہو جاتی ہیں۔', 'پھر جھونکا دینے والیوں کی زور سے [۱]', 'And by the winds that blow violently,', 'and by those that blow violently,'),
(5625, 77, 3, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَّ  النّٰشِرٰتِ نَشۡرًا ۙ﴿۳﴾', 'اور بادلوں کو ابھار کر اٹھا لاتی ہیں۔', 'پھر ابھارنے والیوں کی اٹھا کر', 'And by the winds that scatter clouds and rain;', 'and by those that spread (clouds) all over,'),
(5626, 77, 4, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'فَالۡفٰرِقٰتِ فَرۡقًا ۙ﴿۴﴾', 'پھر انکو پھاڑ کر جدا جدا کر دیتی ہیں۔', 'پھر پھاڑنے والیوں کی بانٹ کر [۲]', 'And by the Verses (of the Quran) that separate the right from the wrong.', 'and by those (angels) who differentiate (between right and wrong) distinctly,'),
(5627, 77, 5, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'فَالۡمُلۡقِیٰتِ ذِکۡرًا ۙ﴿۵﴾', 'پھر فرشتوں کی قسم جو وحی لاتے ہیں۔', 'پھر فرشتوں کی جو اتار کر لائیں وحی [۳]', 'And by the angels that bring the revelations to the Messengers,', 'then bring down the advice,'),
(5628, 77, 6, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'عُذۡرًا  اَوۡ  نُذۡرًا ۙ﴿۶﴾', 'تاکہ عذر دور کر دیا جائے یا ڈر سنا دیا جائے۔', 'الزام اتارنے کو یا ڈر سنانے کو [۴]', 'To cut off all excuses or to warn;', 'leaving no excuse (for the disbelievers) or giving warnings,'),
(5629, 77, 7, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'اِنَّمَا تُوۡعَدُوۡنَ  لَوَاقِعٌ ؕ﴿۷﴾', 'کہ جس فیصلے کا تم سے وعدہ کیا جاتا ہے وہ ہو کر رہے گا۔', 'مقرر جو تم سے وعدہ ہوا وہ ضرور ہونا ہے [۵]', 'Surely, what you are promised must come to pass.', 'that which you are promised is sure to happen.'),
(5630, 77, 8, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'فَاِذَا النُّجُوۡمُ  طُمِسَتۡ ۙ﴿۸﴾', 'جب تاروں کی چمک جاتی رہے۔', 'پھر جب تارے مٹائے جائیں', 'Then when the stars lose their lights;', 'So, when the stars will be extinguished,'),
(5631, 77, 9, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَ  اِذَا السَّمَآءُ  فُرِجَتۡ ۙ﴿۹﴾', 'اور جب آسمان میں شگاف پڑ جائیں۔', 'اور جب آسمان میں جھروکے پڑ جائیں [۶]', 'And when the heaven is cleft asunder;', 'and when the sky will be split,'),
(5632, 77, 10, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَ  اِذَا  الۡجِبَالُ  نُسِفَتۡ ﴿ۙ۱۰﴾', 'اور جب پہاڑ ریزہ ریزہ کر کے اڑا دئیے جائیں۔', 'اور جب پہاڑ اڑا دیے جائیں [۷]', 'And when the mountains are blown away;', 'and when the mountains will be blown away as dust,'),
(5633, 77, 11, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَ  اِذَا  الرُّسُلُ  اُقِّتَتۡ ﴿ؕ۱۱﴾', 'اور جب پیغمبروں کیلئے وقت مقرر کر دیا جائے۔', 'اور جب رسولوں کا وقت مقرر ہو جائے [۸]', 'And when the Messengers are gathered to their time appointed;', 'and when the messengers will be assembled at the appointed time, (then all matters will be decided.)'),
(5634, 77, 12, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'لِاَیِّ  یَوۡمٍ اُجِّلَتۡ ﴿ؕ۱۲﴾', 'بھلا ان کاموں میں تاخیر کس لئے کی گئ؟', 'کس دن کے واسطے ان چیزوں میں دیر ہے', 'For what Day are these signs postponed?', '(Do you know) for which day has all this been delayed?'),
(5635, 77, 13, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'لِیَوۡمِ  الۡفَصۡلِ ﴿ۚ۱۳﴾', 'فیصلے کے دن کے لئے۔', 'اس فیصلے کے دن کے واسطے [۹]', 'For the Day of sorting out (the men of Paradise from the men destined for Hell).', 'For the Day of Decision!'),
(5636, 77, 14, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَ  مَاۤ   اَدۡرٰىکَ مَا یَوۡمُ الۡفَصۡلِ ﴿ؕ۱۴﴾', 'اور تمہیں کیا خبر کہ فیصلے کا دن کیا ہے۔', 'اور تو نے کیا بوجھا کیا ہے فیصلے کا دن', 'And what will explain to you what is the Day of sorting out?', 'And what may let you know what the Day of Decision is?'),
(5637, 77, 15, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَیۡلٌ  یَّوۡمَئِذٍ  لِّلۡمُکَذِّبِیۡنَ ﴿۱۵﴾', 'اس دن جھٹلانے والوں کے لئے خرابی ہو گی۔', 'خرابی ہے اس دن جھٹلانے والوں کی [۱۰]', 'Woe that Day to the deniers (of the Day of Resurrection)!', 'Woe that Day to the deniers!'),
(5638, 77, 16, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'اَلَمۡ  نُہۡلِکِ  الۡاَوَّلِیۡنَ ﴿ؕ۱۶﴾', 'کیا ہم نے پہلے لوگوں کو ہلاک نہیں کر ڈالا تھا۔', 'کیا ہم نے نہیں مار کھپایا پہلوں کو', 'Did We not destroy the ancients?', 'Did We not destroy the earlier people?'),
(5639, 77, 17, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'ثُمَّ  نُتۡبِعُہُمُ   الۡاٰخِرِیۡنَ ﴿۱۷﴾', 'پھر ان پچھلوں کو بھی انکے پیچھے بھیج دیتے ہیں۔', 'پھر اُنکے پیچھے بھیجتے ہیں پچھلوں کو', 'So shall We make later generations to follow them.', 'Then We will cause the later ones to follow them.'),
(5640, 77, 18, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'کَذٰلِکَ نَفۡعَلُ  بِالۡمُجۡرِمِیۡنَ ﴿۱۸﴾', 'ہم گنہگاروں کے ساتھ ایسا ہی کیا کرتے ہیں۔', 'ہم ایسا ہی کیا کرتے ہیں گنہگاروں کے ساتھ [۱۱]', 'Thus do We deal with the Mujrimoon (polytheists, disbelievers, sinners, criminals, etc.)!', 'Thus We deal with the guilty people.'),
(5641, 77, 19, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَیۡلٌ  یَّوۡمَئِذٍ  لِّلۡمُکَذِّبِیۡنَ ﴿۱۹﴾', 'اس دن جھٹلانے والوں کی خرابی ہو گی۔', 'خرابی ہے اُس دن جھٹلانے والوں کی [۱۲]', 'Woe that Day to the deniers (of the Day of Resurrection)!', 'Woe that Day to the deniers!'),
(5642, 77, 20, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'اَلَمۡ  نَخۡلُقۡکُّمۡ  مِّنۡ مَّآءٍ مَّہِیۡنٍ ﴿ۙ۲۰﴾', 'کیا ہم نے تمکو حقیر پانی سے نہیں پیدا کیا۔', 'کیا ہم نے نہیں بنایا تمکو ایک بے قدر پانی سے', 'Did We not create you from a worthless water (semen, etc.)?', 'Did We not create you from a worthless fluid?'),
(5643, 77, 21, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'فَجَعَلۡنٰہُ  فِیۡ  قَرَارٍ  مَّکِیۡنٍ ﴿ۙ۲۱﴾', 'پھر اس کو ایک محفوظ جگہ میں رکھا۔', 'پھر رکھا اُسکو ایک جمے ہوئے ٹھکانے میں [۱۳]', 'Then We placed it in a place of safety (womb),', 'Then We put it in a firm place of rest'),
(5644, 77, 22, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'اِلٰی  قَدَرٍ  مَّعۡلُوۡمٍ ﴿ۙ۲۲﴾', 'ایک وقت معین تک۔', 'ایک وعدہ مقرر تک [۱۴]', 'For a known period (determined by gestation)?', 'for a known period.'),
(5645, 77, 23, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'فَقَدَرۡنَا ٭ۖ فَنِعۡمَ  الۡقٰدِرُوۡنَ ﴿۲۳﴾', 'پھر ہم نے اندازہ مقرر کیا سو ہم کیا ہی خوب اندازہ مقرر کرنے والے ہیں۔', 'پھر ہم اُسکو  پورا کر سکے سو ہم کیا خوب سکت والے ہیں [۱۵]', 'So We did measure, and We are the Best to measure (the things).', 'Thus We did (all this with perfect) measure; so We are the best to measure.'),
(5646, 77, 24, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَیۡلٌ  یَّوۡمَئِذٍ  لِّلۡمُکَذِّبِیۡنَ ﴿۲۴﴾', 'اس دن جھٹلانے والوں کی خرابی ہو گی۔', 'خرابی ہے اس دن جھٹلانے والوں کی [۱۶]', 'Woe that Day to the deniers (of the Day of Resurrection)!', 'Woe that Day to the deniers!'),
(5647, 77, 25, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'اَلَمۡ  نَجۡعَلِ الۡاَرۡضَ  کِفَاتًا ﴿ۙ۲۵﴾', 'کیا ہم نے زمین کو سمیٹنے والی نہیں بنایا۔', 'کیا ہم نے نہیں بنائی زمین سمیٹنے والی', 'Have We not made the earth a receptacle?', 'Did We not make the earth a container that collects'),
(5648, 77, 26, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'اَحۡیَآءً   وَّ  اَمۡوَاتًا ﴿ۙ۲۶﴾', 'یعنی زندوں اور مردوں کو۔', 'زندوں کو اور مردوں کو [۱۷]', 'For the living and the dead.', 'the living and the dead?'),
(5649, 77, 27, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَّ جَعَلۡنَا فِیۡہَا رَوَاسِیَ شٰمِخٰتٍ وَّ اَسۡقَیۡنٰکُمۡ مَّآءً  فُرَاتًا ﴿ؕ۲۷﴾', 'اور ہم نے اس پر اونچے اونچے پہاڑ رکھ دیئے اور تم لوگوں کو میٹھا پانی پلایا۔', 'اور رکھے ہم نے زمین میں بوجھ کے لئے پہاڑ اونچے اور پلایا ہم نے تمکو پانی میٹھا پیاس بھجانے والا [۱۸]', 'And have placed therein firm, and tall mountains; and have given you to drink sweet water?', 'And We placed towering mountains therein, and provided you with sweet water to drink.'),
(5650, 77, 28, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَیۡلٌ  یَّوۡمَئِذٍ  لِّلۡمُکَذِّبِیۡنَ ﴿۲۸﴾', 'اس دن جھٹلانے والوں کی خرابی ہو گی۔', 'خرابی ہے اُس دن جھٹلانے والوں کی [۱۹]', 'Woe that Day to the deniers (of the Day of Resurrection)!', 'Woe that Day to the deniers!'),
(5651, 77, 29, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'اِنۡطَلِقُوۡۤا  اِلٰی مَا کُنۡتُمۡ بِہٖ تُکَذِّبُوۡنَ ﴿ۚ۲۹﴾', 'جس چیز کو تم جھٹلایا کرتے تھے اب اس کی طرف چلو۔', 'چل کر دیکھو جس چیز کو تم جھٹلاتے تھے [۲۰]', '(It will be said to the disbelievers): \"Depart you to that which you used to deny!', '(It will be said to them on that day,) “Push on to what you used to deny.'),
(5652, 77, 30, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'اِنۡطَلِقُوۡۤا  اِلٰی ظِلٍّ  ذِیۡ ثَلٰثِ شُعَبٍ ﴿ۙ۳۰﴾', 'یعنی اس سائے کی طرف چلو جسکی تین شاخیں ہیں۔', 'چلو ایک چھاؤں میں جسکی تین پھانکیں ہیں [۲۱]', '\"Depart you to a shadow (of Hell-fire smoke ascending) in three columns,', 'Push on to a canopy (of Hell’s smoke) having three branches,'),
(5653, 77, 31, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'لَّا  ظَلِیۡلٍ  وَّ لَا یُغۡنِیۡ مِنَ اللَّہَبِ ﴿ؕ۳۱﴾', 'نہ ٹھنڈی چھاؤں اور نہ شعلوں سے بچاؤ۔', 'نہ گہری چھاؤں اور نہ کچھ کام آئے تپش میں [۲۲]', '\"Neither shading, nor of any use against the fierce flame of the Fire.\"', 'that neither has a comfortable shade, nor is it of any use against the scorching heat.'),
(5654, 77, 32, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'اِنَّہَا  تَرۡمِیۡ  بِشَرَرٍ  کَالۡقَصۡرِ ﴿ۚ۳۲﴾', 'اس سے آگ کی اتنی اتنی بڑی چنگاریاں اڑتی ہیں جیسے محل۔', 'وہ آگ پھینکتی ہے چنگاریاں جیسے محل [۲۳]', 'Verily! It (Hell) throws sparks (huge) as Al-Qasr (a fort or a Qasr (huge log of wood)),', 'It emits sparks (as huge) as castles,'),
(5655, 77, 33, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'کَاَنَّہٗ  جِمٰلَتٌ صُفۡرٌ ﴿ؕ۳۳﴾', 'گویا زرد رنگ کے اونٹ ہیں۔', 'گویا وہ اونٹ ہیں زرد [۲۴]', 'As if they were Jimalatun Sufr (yellow camels or bundles of ropes).\"', 'as if they were yellowish camels.”'),
(5656, 77, 34, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَیۡلٌ  یَّوۡمَئِذٍ لِّلۡمُکَذِّبِیۡنَ ﴿۳۴﴾', 'اس دن جھٹلانے والوں کی خرابی ہو گی۔', 'خرابی ہے اس دن جھٹلانے والوں کی [۲۵]', 'Woe that Day to the deniers (of the Day of Resurrection)!', 'Woe that Day to the deniers!'),
(5657, 77, 35, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'ہٰذَا یَوۡمُ لَا  یَنۡطِقُوۡنَ ﴿ۙ۳۵﴾', 'یہ وہ دن ہے کہ لوگ لب تک نہ ہلا سکیں گے۔', 'یہ وہ دن ہے کہ نہ بولیں گے [۲۶]', 'That will be a Day when they shall not speak (during some part of it),', 'This is the day when they will not speak,'),
(5658, 77, 36, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَ لَا یُؤۡذَنُ  لَہُمۡ  فَیَعۡتَذِرُوۡنَ ﴿۳۶﴾', 'اور نہ انکو اجازت دی جائے گی کہ عذر کر سکیں۔', 'اور نہ اُنکو حکم ہو کہ توبہ کریں [۲۷]', 'And they will not be permitted to put forth any excuse.', 'nor will they be allowed to offer excuses.'),
(5659, 77, 37, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَیۡلٌ  یَّوۡمَئِذٍ  لِّلۡمُکَذِّبِیۡنَ ﴿۳۷﴾', 'اس دن جھٹلانے والوں کی خرابی ہو گی۔', 'خرابی ہے اُس دن جھٹلانے والوں کی [۲۸]', 'Woe that Day to the deniers (of the Day of Resurrection)!', 'Woe that Day to the deniers!'),
(5660, 77, 38, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'ہٰذَا یَوۡمُ الۡفَصۡلِ ۚ جَمَعۡنٰکُمۡ وَ الۡاَوَّلِیۡنَ ﴿۳۸﴾', 'یہی فیصلے کا دن ہے جس میں ہم نے تمکو اور پہلے لوگوں کو جمع کیا ہے۔', 'یہ ہے دن فیصلے کا جمع کیا ہم نے تمکو اور اگلوں کو [۲۹]', 'That will be a Day of Decision! We have brought you and the men of old together!', '(It will be said to them,) “This is the Day of Decision. We have assembled you and the earlier ones together.'),
(5661, 77, 39, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'فَاِنۡ کَانَ  لَکُمۡ  کَیۡدٌ  فَکِیۡدُوۡنِ ﴿۳۹﴾', 'اگر تمکو کوئی داؤں آتا ہو تو مجھ سے کر چلو۔', 'پھر اگر کچھ داؤ ہے تمہارا تو چلا لو مجھ پر [۳۰]', 'So if you have a plot, use it against Me (Allah Ìá ÌáÇáå )!', 'Now, if you have a trick, use the trick against Me.”'),
(5662, 77, 40, 1, 21, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَیۡلٌ  یَّوۡمَئِذٍ لِّلۡمُکَذِّبِیۡنَ ﴿٪۴۰﴾', 'اس دن جھٹلانے والوں کی خرابی ہو گی۔', 'خرابی ہے اس دن جھٹلانے والوں کی [۳۱]', 'Woe that Day to the deniers (of the Day of Resurrection)!', 'Woe that Day to the deniers!'),
(5663, 77, 41, 2, 22, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'اِنَّ  الۡمُتَّقِیۡنَ فِیۡ ظِلٰلٍ وَّ  عُیُوۡنٍ ﴿ۙ۴۱﴾', 'بیشک پرہیزگار سایوں اور چشموں میں ہوں گے۔', 'البتہ جو ڈرنے والے ہیں وہ سایہ میں ہیں [۳۲] اور نہروں میں', 'Verily, the Muttaqoon (pious - see V.2:2) shall be amidst shades and springs.', 'Of course, the God-fearing will be amid shades and streams,'),
(5664, 77, 42, 2, 22, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَّ  فَوَاکِہَ  مِمَّا یَشۡتَہُوۡنَ ﴿ؕ۴۲﴾', 'اور میووں میں جو انکو مرغوب ہوں۔', 'اور میوے جس قسم کے وہ چاہیں', 'And fruits, such as they desire.', 'and fruits of their desire.'),
(5665, 77, 43, 2, 22, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'کُلُوۡا  وَ اشۡرَبُوۡا ہَنِیۡٓــًٔۢا بِمَا کُنۡتُمۡ تَعۡمَلُوۡنَ ﴿۴۳﴾', 'جو عمل تم کرتے رہے تھے انکے بدلے میں مزے سے کھاؤ اور پیو۔', 'کھاؤ اور  پیو مزے سے بدلا  اُن کاموں کا جو تم نے کئے تھے [۳۳]', '\"Eat and drink comfortably for that which you used to do.', 'It will be said to them, “Eat and drink with pleasure because of what you used to do.”'),
(5666, 77, 44, 2, 22, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'اِنَّا کَذٰلِکَ  نَجۡزِی  الۡمُحۡسِنِیۡنَ ﴿۴۴﴾', 'ہم نیکوکاروں کو ایسا ہی بدلہ دیا کرتے ہیں۔', 'ہم یونہی دیتے ہیں بدلا نیکی والوں کو', 'Verily, thus We reward the Muhsinoon (good-doers).', 'This is how We reward those who do good deeds.'),
(5667, 77, 45, 2, 22, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَیۡلٌ  یَّوۡمَئِذٍ لِّلۡمُکَذِّبِیۡنَ ﴿۴۵﴾', 'اس دن جھٹلانے والوں کی خرابی ہو گی۔', 'خرابی ہے اُس دن جھٹلانے والوں کی [۳۴]', 'Woe that Day to the deniers (of the Day of Resurrection)!', 'Woe that Day to the deniers!'),
(5668, 77, 46, 2, 22, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'کُلُوۡا وَ تَمَتَّعُوۡا  قَلِیۡلًا  اِنَّکُمۡ  مُّجۡرِمُوۡنَ ﴿۴۶﴾', 'اے جھٹلانے والو دنیا میں تم کسی قدر کھا لو اور فائدے اٹھا لو تم بیشک گنہگار ہو۔', 'کھا لو اور برت لو تھوڑے دنوں بیشک تم گنہگار ہو [۳۵]', '(O you disbelievers)! Eat and enjoy yourselves (in this worldly life) for a little while. Verily, you are the Mujrimoon (polytheists, disbelievers, sinners, criminals, etc.).', '“(O disbelievers,) eat and drink for a while! You are guilty ones.”'),
(5669, 77, 47, 2, 22, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَیۡلٌ  یَّوۡمَئِذٍ لِّلۡمُکَذِّبِیۡنَ ﴿۴۷﴾', 'اس دن جھٹلانے والوں کی خرابی ہو گی۔', 'خرابی ہے اُس دن جھٹلانے والوں کی [۳۶]', 'Woe that Day to the deniers (of the Day of Resurrection)!', 'Woe that Day to the deniers!'),
(5670, 77, 48, 2, 22, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَ  اِذَا قِیۡلَ لَہُمُ  ارۡکَعُوۡا  لَا  یَرۡکَعُوۡنَ ﴿۴۸﴾', 'اور جب ان سے کہا جاتا ہے کہ اللہ کے آگے جھکو تو جھکتے نہیں۔', 'اور جب کہیے اُن کو کہ جھک جاؤ نہیں جھکتے [۳۷]', 'And when it is said to them: \"Bow down yourself (in prayer)!\" They bow not down (offer not their prayers) .', 'And when it is said to them, “Bow down (i.e. submit to Allah’s commands)”, they do not bow down.'),
(5671, 77, 49, 2, 22, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'وَیۡلٌ  یَّوۡمَئِذٍ لِّلۡمُکَذِّبِیۡنَ ﴿۴۹﴾', 'اس دن جھٹلانے والوں کی خرابی ہو گی۔', 'خرابی ہے اُس دن جھٹلانے والوں کی [۳۸]', 'Woe that Day to the deniers (of the Day of Resurrection)!', 'Woe that Day to the deniers!'),
(5672, 77, 50, 2, 22, 29, 'تَبٰرَکَ الَّذِیۡ ', 'المرسلٰت', 'فَبِاَیِّ حَدِیۡثٍۭ بَعۡدَہٗ یُؤۡمِنُوۡنَ ﴿٪۵۰﴾', 'اب اس کے بعد یہ کون سی بات پر ایمان لائیں گے؟', 'اب کس بات پر اُسکے بعد یقین لائیں گے [۳۹]', 'Then in what statement after this (the Quran) will they believe?', 'Now, in which discourse, after this, will they believe?'),
(5673, 78, 1, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'عَمَّ  یَتَسَآءَلُوۡنَ ۚ﴿۱﴾', 'یہ لوگ کس چیز کی نسبت ایکدوسرے سے پوچھتے ہیں؟', 'کیا بات پوچھتے ہیں لوگ آپس میں [۱]', 'What are they asking (one another)?', 'About what are they asking each other?'),
(5674, 78, 2, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'عَنِ النَّبَاِ  الۡعَظِیۡمِ ۙ﴿۲﴾', 'کیا اس بڑی خبر کی نسبت؟', 'پوچھتے ہیں اُس بڑی خبر سے', 'About the great news, (i.e. Islamic Monotheism, the Quran, which Prophet Muhammad (Peace be upon him)brought and the Day of Resurrection, etc.),', 'About the Great Event'),
(5675, 78, 3, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'الَّذِیۡ ہُمۡ  فِیۡہِ  مُخۡتَلِفُوۡنَ ؕ﴿۳﴾', 'جس میں یہ اختلاف کر رہے ہیں۔', 'جس میں وہ مختلف ہیں [۲]', 'About which they are in disagreement.', 'in which they dispute!'),
(5676, 78, 4, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'کَلَّا  سَیَعۡلَمُوۡنَ ۙ﴿۴﴾', 'دیکھو یہ عنقریب جان لیں گے۔', 'ہرگز نہیں اب جان لیں گے', 'Nay, they will come to know!', 'Indeed they will soon know.'),
(5677, 78, 5, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'ثُمَّ  کَلَّا  سَیَعۡلَمُوۡنَ ﴿۵﴾', 'پھر دیکھو یہ عنقریب جان لیں گے۔', 'پھر بھی ہر گز نہیں اب جان لیں گے [۳]', 'Nay, again, they will come to know!', 'Again, indeed they will soon know.'),
(5678, 78, 6, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'اَلَمۡ  نَجۡعَلِ الۡاَرۡضَ مِہٰدًا ۙ﴿۶﴾', 'کیا ہم نے زمین کو بچھونا نہیں بنایا؟', 'کیا ہم نے نہیں بنایا زمین کو بچھونا [۴]', 'Have We not made the earth as a bed,', 'Did We not make the earth a floor,'),
(5679, 78, 7, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'وَّ  الۡجِبَالَ  اَوۡتَادًا ﴿۪ۙ۷﴾', 'اور پہاڑوں کو اس کی میخیں نہیں ٹھہرایا؟', 'اور پہاڑوں کو میخیں [۵]', 'And the mountains as pegs?', 'and the mountains bulwarks?'),
(5680, 78, 8, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'وَّ  خَلَقۡنٰکُمۡ   اَزۡوَاجًا ۙ﴿۸﴾', 'اور ہم نے تم کو جوڑا جوڑا پیدا کیا۔', 'اور تم کو بنایا ہم نے جوڑے جوڑے [۶]', 'And We have created you in pairs (male and female, tall and short, good and bad, etc.).', 'And We have created you in pairs,'),
(5681, 78, 9, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'وَّ  جَعَلۡنَا نَوۡمَکُمۡ سُبَاتًا ۙ﴿۹﴾', 'اور نیند کو تمہارے لئے موجب آرام بنایا۔', 'اور بنایا نیند کو تمہاری تکان دفع کرنیکے لئے [۷]', 'And have made your sleep as a thing for rest.', 'and made your sleep a source of rest,'),
(5682, 78, 10, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'وَّ  جَعَلۡنَا الَّیۡلَ  لِبَاسًا ﴿ۙ۱۰﴾', 'اور رات کو پردہ مقرر کیا۔', 'اور بنایا رات کو اوڑھنا [۸]', 'And have made the night as a covering (through its darkness),', 'and made the night a covering,'),
(5683, 78, 11, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'وَّ  جَعَلۡنَا النَّہَارَ  مَعَاشًا ﴿۪۱۱﴾', 'اور دن کو معاش کا وقت قرار دیا۔', 'اور بنایا دن کمائی کرنے کو [۹]', 'And have made the day for livelihood.', 'and made the day a source of livelihood.'),
(5684, 78, 12, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'وَّ  بَنَیۡنَا فَوۡقَکُمۡ  سَبۡعًا شِدَادًا ﴿ۙ۱۲﴾', 'اور تمہارے اوپر سات مضبوط آسمان بنائے۔', 'اور چنی ہم نے تم سےاوپر سات چنائی مضبوط [۱۰]', 'And We have built above you seven strong (heavens),', 'And We have built seven strong (skies),'),
(5685, 78, 13, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'وَّ  جَعَلۡنَا سِرَاجًا وَّہَّاجًا  ﴿۪ۙ۱۳﴾', 'اور آفتاب کا روشن چراغ بنایا۔', 'اور بنایا ایک چراغ چمکتا ہوا [۱۱]', 'And have made (therein) a shinning lamp (sun).', 'and created a luminous lamp (the sun).'),
(5686, 78, 14, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'وَّ اَنۡزَلۡنَا مِنَ الۡمُعۡصِرٰتِ مَآءً  ثَجَّاجًا ﴿ۙ۱۴﴾', 'اور نچڑتے بادلوں سے موسلادھار مینہ برسایا۔', 'اور اتارا نچڑنے والی بدلیوں سے پانی کا ریلا [۱۲]', 'And have sent down from the rainy clouds abundant water.', 'And We have sent down abundant water from the rain-laden clouds,'),
(5687, 78, 15, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'لِّنُخۡرِجَ بِہٖ حَبًّا وَّ  نَبَاتًا ﴿ۙ۱۵﴾', 'تاکہ ہم اس سے اناج اور نباتات پیدا کریں۔', 'تاکہ ہم نکالیں اس سے اناج اور سبزہ', 'That We may produce therewith corn and vegetations,', 'so that We bring out therewith grain and vegetation,'),
(5688, 78, 16, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'وَّ  جَنّٰتٍ اَلۡفَافًا ﴿ؕ۱۶﴾', 'اور گھنے گھنے باغ۔', 'اور باغ پتوں میں لپٹے ہوئے [۱۳]', 'And gardens of thick growth.', 'and thick gardens.'),
(5689, 78, 17, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'اِنَّ  یَوۡمَ  الۡفَصۡلِ کَانَ مِیۡقَاتًا ﴿ۙ۱۷﴾', 'بیشک فیصلے کا دن مقرر ہے۔', 'بیشک دن فیصلے کا ہے ایک وقت ٹھہرا ہوا [۱۴]', 'Verily, the Day of Decision is a fixed time,', 'Surely the Day of Decision is an appointed time,'),
(5690, 78, 18, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'یَّوۡمَ  یُنۡفَخُ فِی الصُّوۡرِ فَتَاۡتُوۡنَ اَفۡوَاجًا ﴿ۙ۱۸﴾', 'جس دن صور پھونکا جائے گا تو تم لوگ فوج در فوج آ موجود ہو گے۔', 'جس دن پھونکی جائے صور پھر تم چلے آؤ جٹ کے جٹ [۱۵]', 'The Day when the Trumpet will be blown, and you shall come forth in crowds (groups);', 'a day when the trumpet will be blown, so you will come in multitudes,'),
(5691, 78, 19, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'وَّ فُتِحَتِ السَّمَآءُ   فَکَانَتۡ اَبۡوَابًا ﴿ۙ۱۹﴾', 'اور آسمان کھولا جائے گا تو اس میں دروازے ہو جائیں گے۔', 'اور کھولا جائے آسمان تو ہو جائیں اس میں دروازے [۱۶]', 'And the heaven shall be opened, and it will become as gates,', 'and the sky will be opened, so it will become as gates,'),
(5692, 78, 20, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'وَّ  سُیِّرَتِ الۡجِبَالُ فَکَانَتۡ  سَرَابًا ﴿ؕ۲۰﴾', 'اور پہاڑ چلائے جائیں گے تو وہ ریت ہو کر رہ جائیں گے۔', 'اور چلائے جائیں گے پہاڑ تو ہو جائیں گے چمکتا ریتا [۱۷]', 'And the mountains shall be moved away from their places and they will be as if they were a mirage.', 'and the mountains will be set in motion, so they will be as mirage.'),
(5693, 78, 21, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'اِنَّ  جَہَنَّمَ  کَانَتۡ مِرۡصَادًا ﴿۪ۙ۲۱﴾', 'بیشک دوزخ گھات میں ہے۔', 'بیشک دوزخ ہے تاک میں', 'Truly, Hell is a place of ambush,', 'Surely Jahannam (the Hell) lurks in ambush.'),
(5694, 78, 22, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'لِّلطَّاغِیۡنَ مَاٰبًا ﴿ۙ۲۲﴾', 'یعنی سرکشوں کیلئے کہ انکا وہی ٹھکانہ ہے۔', 'شریروں کا ٹھکانا [۱۸]', 'A dwelling place for the Taghoon (those who transgress the boundry limits set by Allah like polytheists, disbelievers in the Oneness of Allah, hyprocrites, sinners, criminals, etc.),', '(It is) abode for the rebellious people'),
(5695, 78, 23, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'لّٰبِثِیۡنَ فِیۡہَاۤ  اَحۡقَابًا ﴿ۚ۲۳﴾', 'اس میں وہ صدیوں پڑے رہیں گے۔', 'رہا کریں اُس میں قرنوں [۱۹]', 'They will abide therein for ages,', 'who will be abiding in it for ages.'),
(5696, 78, 24, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'لَا یَذُوۡقُوۡنَ فِیۡہَا بَرۡدًا  وَّ  لَا  شَرَابًا ﴿ۙ۲۴﴾', 'وہاں نہ ٹھنڈک کا مزہ چکھیں گے نہ کچھ پینا نصیب ہو گا۔', 'نہ چکھیں وہاں کچھ مزا ٹھنڈک کا اور نہ پینا ملے کچھ', 'Nothing cool shall they taste therein, nor any drink.', 'They will taste nothing cool in it, nor a drink,'),
(5697, 78, 25, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'اِلَّا  حَمِیۡمًا  وَّ  غَسَّاقًا ﴿ۙ۲۵﴾', 'مگر کھولتا پانی اور بدبودار پیپ۔', 'مگر گرم پانی اور بہتی پیپ [۲۰]', 'Except boiling water, and dirty wound discharges.', 'except boiling water and pus,'),
(5698, 78, 26, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'جَزَآءً   وِّفَاقًا  ﴿ؕ۲۶﴾', 'یہ بدلہ ہے انکے اعمال کے موافق۔', 'بدلا ہے پورا', 'An exact recompense (according to their evil crimes).', 'this being a punishment, fully commensurate (with their deeds).'),
(5699, 78, 27, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'اِنَّہُمۡ  کَانُوۡا  لَا  یَرۡجُوۡنَ  حِسَابًا ﴿ۙ۲۷﴾', 'یہ لوگ حساب آخرت کی امید ہی نہیں رکھتے تھے۔', 'اُنکو توقع نہ تھی حساب کی', 'For verily, they used not to look for a reckoning.', 'They did not expect (to face) accounting (of their deeds),'),
(5700, 78, 28, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'وَّ  کَذَّبُوۡا بِاٰیٰتِنَا کِذَّابًا ﴿ؕ۲۸﴾', 'اور ہماری آیتوں کو مسلسل جھٹلاتے رہتے تھے۔', 'اور جھٹلاتے تھے ہماری آیتوں کو مکرا کر [۲۱]', 'But they belied Our Ayat (proofs, evidences, verses, lessons, signs, revelations, and that which Our Prophet (Peace be upon him) brought) completely.', 'and they rejected Our signs totally.'),
(5701, 78, 29, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'وَ کُلَّ شَیۡءٍ  اَحۡصَیۡنٰہُ  کِتٰبًا ﴿ۙ۲۹﴾', 'اور ہم نے ہر چیز کو لکھ کر محفوظ کر رکھا ہے۔', 'اور ہر چیز ہم نے گن رکھی ہے لکھ کر [۲۲]', 'And all things We have recorded in a Book.', 'And everything (from their deeds) is thoroughly recorded by Us in writing.'),
(5702, 78, 30, 1, 1, 30, 'عَمَّ ', 'النَّبَاِ', 'فَذُوۡقُوۡا  فَلَنۡ نَّزِیۡدَکُمۡ  اِلَّا عَذَابًا ﴿٪۳۰﴾', 'سو اب مزہ چکھو۔ ہم تم پر عذاب ہی بڑھاتے جائیں گے۔', 'اب چکھو  کہ ہم نہ بڑھاتے جائیں گے تم پر مگر عذاب [۲۳]', 'So taste you (the results of your evil actions); no increase shall We give you, except in torment.', '“So now taste! We will add nothing to you but torment.”'),
(5703, 78, 31, 2, 2, 30, 'عَمَّ ', 'النَّبَاِ', 'اِنَّ  لِلۡمُتَّقِیۡنَ مَفَازًا ﴿ۙ۳۱﴾', 'بیشک پرہیزگاروں کے لئے کامیابی کا گھر ہے۔', 'بیشک ڈر والوں کو اُنکی مراد ملنی ہے', 'Verily, for the Muttaqoon, there will be a success (Paradise);', 'Of course, the God-fearing will have great achievement,'),
(5704, 78, 32, 2, 2, 30, 'عَمَّ ', 'النَّبَاِ', 'حَدَآئِقَ وَ  اَعۡنَابًا ﴿ۙ۳۲﴾', 'یعنی باغ اور انگور۔', 'باغ ہیں اور انگور', 'Gardens and grapeyards;', '-gardens and grapes,'),
(5705, 78, 33, 2, 2, 30, 'عَمَّ ', 'النَّبَاِ', 'وَّکَوَاعِبَ  اَتۡرَابًا ﴿ۙ۳۳﴾', 'اور ہم عمر بھرپور جوان عورتیں۔', 'اور نوجوان عورتیں ایک عمر کی سب [۲۴]', 'And young full-breasted (mature) maidens of equal age;', 'and buxom maidens of matching age,'),
(5706, 78, 34, 2, 2, 30, 'عَمَّ ', 'النَّبَاِ', 'وَّ  کَاۡسًا دِہَاقًا ﴿ؕ۳۴﴾', 'اور شراب کے چھلکتے ہوئے جام۔', 'اور پیالے چھلکتے ہوئے [۲۵]', 'And a full cup (of wine).', 'and goblets filled up to the brim.'),
(5707, 78, 35, 2, 2, 30, 'عَمَّ ', 'النَّبَاِ', 'لَا یَسۡمَعُوۡنَ فِیۡہَا لَغۡوًا وَّ لَا کِذّٰبًا ﴿ۚ۳۵﴾', 'وہاں نہ وہ بیہودہ بات سنیں گے نہ جھٹلانے کی باتیں۔', 'نہ سنیں گے وہاں بک بک اور نہ مکرانا [۲۶]', 'No Laghw (dirty, false, evil talk) shall they hear therein, nor lying;', 'They will not hear any vain talk therein, nor lies,'),
(5708, 78, 36, 2, 2, 30, 'عَمَّ ', 'النَّبَاِ', 'جَزَآءً   مِّنۡ  رَّبِّکَ عَطَآءً  حِسَابًا ﴿ۙ۳۶﴾', 'اے نبی ﷺ یہ تمہارے پروردگار کی طرف سے صلہ ہو گا جو حساب کے مطابق انعام ہو گا۔', 'بدلا ہے تیرے رب کا دیا ہوا حساب سے [۲۷]', 'A reward from your Lord, an ample calculated gift (according to the best of their good deeds).', 'this being a reward from their Lord, a well calculated grant,'),
(5709, 78, 37, 2, 2, 30, 'عَمَّ ', 'النَّبَاِ', 'رَّبِّ السَّمٰوٰتِ وَ الۡاَرۡضِ وَ مَا بَیۡنَہُمَا الرَّحۡمٰنِ لَا یَمۡلِکُوۡنَ مِنۡہُ خِطَابًا ﴿ۚ۳۷﴾', 'وہ پروردگار کہ جو کچھ آسمانوں اور زمین میں اور جو ان دونوں کے درمیان ہے سب کا مالک ہے بڑا مہربان ہے کسی کو اس سے بات کرنے کا یارا نہ ہوگا۔', 'جو رب ہے آسمانوں کا اور زمین کا اور جو کچھ اُنکے بیچ میں ہے بڑی رحمت والا [۲۸] قدرت نہیں کہ کوئی اُس سے بات کرے [۲۹]', '(From) the Lord of the heavens and the earth, and whatsoever is in between them, the Most Beneficent, none can dare to speak with Him (on the Day of Resurrection except after His Leave).', '(from) the Lord of the heavens and the earth and what is between them, the All-Merciful. No one will have power to address Him,'),
(5710, 78, 38, 2, 2, 30, 'عَمَّ ', 'النَّبَاِ', 'یَوۡمَ  یَقُوۡمُ الرُّوۡحُ وَ الۡمَلٰٓئِکَۃُ  صَفًّا ؕ٭ۙ  لَّا یَتَکَلَّمُوۡنَ  اِلَّا مَنۡ اَذِنَ لَہُ الرَّحۡمٰنُ وَ  قَالَ صَوَابًا ﴿۳۸﴾', 'جس دن جبریل امین اور دوسرے فرشتے صف باندھ کر کھڑے ہوں گے تو کوئی بول نہ سکے گا۔ مگر جسکو رحمٰن اجازت بخشے اور وہ بات بھی درست ہی کہے۔', 'جس دن کھڑی ہو روح اور فرشتے قطار باندھ کر [۳۰] کوئی نہیں بولتا مگر جس کو حکم دیا رحمٰن نے اور بولا بات ٹھیک [۳۱]', 'The Day that Ar-Rooh (Jibrael (Gabriel) or another angel) and the angels will stand forth in rows, none shall speak except him whom the Most Beneficent (Allah) allows, and he will speak what is right.', 'on the Day when the Spirit and the angels will stand in rows. They will not speak, except the one who is permitted by the RaHmān (the All-Merciful Allah) and speaks aright.'),
(5711, 78, 39, 2, 2, 30, 'عَمَّ ', 'النَّبَاِ', 'ذٰلِکَ  الۡیَوۡمُ الۡحَقُّ ۚ فَمَنۡ شَآءَ اتَّخَذَ اِلٰی رَبِّہٖ مَاٰبًا ﴿۳۹﴾', 'یہ دن برحق ہے۔ پس جو شخص چاہے اپنے پروردگار کے پاس ٹھکانہ بنا لے۔', 'وہ دن ہے برحق پھر جو کوئی چاہے بنا رکھے اپنے رب کے پاس ٹھکانا [۳۲]', 'That is without doubt the True Day, so, whosoever wills, let him seek a place with (or a way to) His Lord (by obeying Him in this worldly life)!', 'That is the Day that is sure to come. So whoever so wishes may take refuge with his Lord.'),
(5712, 78, 40, 2, 2, 30, 'عَمَّ ', 'النَّبَاِ', 'اِنَّاۤ  اَنۡذَرۡنٰکُمۡ عَذَابًا  قَرِیۡبًا ۬ۚۖ یَّوۡمَ یَنۡظُرُ  الۡمَرۡءُ مَا قَدَّمَتۡ یَدٰہُ  وَ یَقُوۡلُ الۡکٰفِرُ یٰلَیۡتَنِیۡ  کُنۡتُ تُرٰبًا ﴿٪۴۰﴾', 'ہم نے تمکو عذاب سے جو عنقریب آنے والا ہے آگاہ کر دیا ہے جس دن ہر شخص ان اعمال کو جو اس نے آگے بھیجے ہوں گے دیکھ لے گا اور کافر کہے گا کہ اے کاش میں مٹی ہوتا۔', 'ہم نے خبر سنا دی تم کو ایک آفت نزدیک آنے والی کی جس دن دیکھ لے گا آدمی جو آگے بھیجا اُسکے ہاتھوں نے [۳۳] اور کہے گا کافر کسی طرح میں مٹی ہوتا [۳۴]', 'Verily, We have warned you of a near torment, the Day when man will see that (the deeds) which his hands have sent forth, and the disbeliever will say: \"Woe to me! Would that I were dust!\"', 'We have warned you of an approaching torment (that will be inflicted) on a day when one will see what his hands have sent ahead, and the disbeliever will say, “O would that I had turned into dust.”'),
(5713, 79, 1, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'وَ النّٰزِعٰتِ غَرۡقًا ۙ﴿۱﴾', 'ان فرشتوں کی قسم جو ڈوب کر کافروں کی جان کھینچ لیتے ہیں۔', 'قسم ہے گھسیٹ لانے والوں کی غوطہ لگا کر [۱]', 'By those (angels) who pull out (the souls of the disbelievers and the wicked) with great violence;', 'I swear by those (angels) who pull out (the souls of the infidels) with extreme force,'),
(5714, 79, 2, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'وَّ النّٰشِطٰتِ نَشۡطًا  ۙ﴿۲﴾', 'اور ان کی جو مومنوں کی جان آسانی سے نکالتے ہیں۔', 'اور بند چھڑا دینے والوں کی کھول کر [۲]', 'By those (angels) who gently take out (the souls of the believers);', 'and by those (angels) who untie the knot (of the souls of the believers) smoothly,'),
(5715, 79, 3, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'وَّ السّٰبِحٰتِ سَبۡحًا ۙ﴿۳﴾', 'اور انکی جو تیرتے ہوئے جاتے ہیں۔', 'اور پیرنے والوں کی تیزی سے', 'And by those that swim along (i.e. angels or planets in their orbits, etc.).', 'and by those who float (in the atmosphere) swiftly,'),
(5716, 79, 4, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'فَالسّٰبِقٰتِ سَبۡقًا ۙ﴿۴﴾', 'پھر لپک کر آگے بڑھتے ہیں۔', 'پھر آگے بڑھنے والوں کی دوڑ کر [۳]', 'And by those that press forward as in a race (i.e. the angels or stars or the horses, etc.).', 'then proceed forward quickly,'),
(5717, 79, 5, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'فَالۡمُدَبِّرٰتِ اَمۡرًا ۘ﴿۵﴾', 'پھر دنیا کے کاموں کا انتظام کر تے ہیں۔', 'پھر کام بنانے والوں کی حکم سے [۴]', 'And by those angels who arrange to do the Commands of their Lord, (so verily, you disbelievers will be called to account).', 'then manage (to do) everything (they are ordered to do,)'),
(5718, 79, 6, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'یَوۡمَ  تَرۡجُفُ الرَّاجِفَۃُ ۙ﴿۶﴾', 'کہ وہ دن آ کر رہے گا جس دن  وہ زلزلہ آئے گا۔', 'جس دن کانپے کانپنے والی [۵]', 'On the Day (when the first blowing of the Trumpet is blown), the earth and the mountains will shake violently (and everybody will die),', '(you will be resurrected) on the Day when the shocking event (i.e. the first blowing of the trumpet) will shock (everything),'),
(5719, 79, 7, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'تَتۡبَعُہَا الرَّادِفَۃُ ؕ﴿۷﴾', 'پھر اس کے پیچھے اور زلزلہ آئے گا۔', 'اُسکے پیچھے آئے دوسری [۶]', 'The second blowing of the Trumpet follows it (and everybody will be raised up),', 'followed by the next one (i.e. the second blowing of the trumpet.)'),
(5720, 79, 8, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'قُلُوۡبٌ یَّوۡمَئِذٍ وَّاجِفَۃٌ ۙ﴿۸﴾', 'اس دن لوگوں کے دل خوفزدہ ہوں گے۔', 'کتنے دل اُس دن دھڑکتے ہیں', '(Some) hearts that Day will shake with fear and anxiety.', 'On that day, hearts (of people) will be throbbing,'),
(5721, 79, 9, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'اَبۡصَارُہَا خَاشِعَۃٌ ۘ﴿۹﴾', 'اور آنکھیں جھکی ہوئی۔', 'اُنکی آنکھیں جھک رہی ہیں [۷]', 'Their eyes cast down.', 'with their eyes downcast.'),
(5722, 79, 10, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'یَقُوۡلُوۡنَ ءَاِنَّا  لَمَرۡدُوۡدُوۡنَ  فِی الۡحَافِرَۃِ ﴿ؕ۱۰﴾', 'کافر کہتے ہیں کیا ہم الٹے پاؤں پھر لوٹیں گے؟', 'لوگ کہتے ہیں کیا ہم پھر آئیں گے الٹے پاؤں', 'They say: \"Shall we indeed be returned to (our) former state of life?', 'They (the infidels) say, “Are we going to be brought back to our former state (of Life)?'),
(5723, 79, 11, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'ءَ اِذَا کُنَّا عِظَامًا نَّخِرَۃً ﴿ؕ۱۱﴾', 'بھلا جب ہم کھوکھلی ہڈیاں ہو جائیں گے تو پھر زندہ کئے جائیں گے۔', 'کیا جب ہم ہو چکیں ہڈیاں کھوکھری', '\"Even after we are crumbled bones?\"', 'Is it when we are turned into decayed bones?”'),
(5724, 79, 12, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'قَالُوۡا تِلۡکَ  اِذًا کَرَّۃٌ  خَاسِرَۃٌ ﴿ۘ۱۲﴾', 'کہتے ہیں کہ یہ لوٹنا تو سراسر نقصان کا لوٹنا ہو گا۔', 'بولے تو تو یہ پھر آنا ہے ٹوٹے کا [۸]', 'They say: \"It would in that case, be a return with loss!\"', 'They say, “If so, that will be a harmful homecoming.”'),
(5725, 79, 13, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'فَاِنَّمَا ہِیَ زَجۡرَۃٌ   وَّاحِدَۃٌ ﴿ۙ۱۳﴾', 'تو بس وہ ایک ڈانٹ ہو گی۔', 'سو وہ تو صرف ایک جھڑکی ہے', 'But only, it will be a single Zajrah (shout (i.e., the second blowing of the Trumpet)). (See Verse 37:19).', 'In fact, it will be only a single harsh voice,'),
(5726, 79, 14, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'فَاِذَا  ہُمۡ  بِالسَّاہِرَۃِ ﴿ؕ۱۴﴾', 'اس وقت وہ سب میدان حشر میں آ جمع ہوں گے۔', 'پھر تبھی وہ آ رہیں میدان میں [۹]', 'When, behold, they find themselves over the earth alive after their death,', 'and in no time they will be (brought) into the plain (of Hashr).'),
(5727, 79, 15, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'ہَلۡ  اَتٰىکَ حَدِیۡثُ  مُوۡسٰی ﴿ۘ۱۵﴾', 'بھلا تم کو موسٰی کی حکایت پہنچی ہے۔', 'کیا پہنچی ہے تجھ کو بات موسٰی کی [۱۰]', 'Has there come to you the story of Moosa (Moses)?', 'Has there come to you the narrative about Mūsā?'),
(5728, 79, 16, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'اِذۡ  نَادٰىہُ  رَبُّہٗ  بِالۡوَادِ  الۡمُقَدَّسِ طُوًی  ﴿ۚ۱۶﴾', 'جب ان کے پروردگار نے انکو پاک میدان یعنی طوٰی میں پکارا۔', 'جب پکارا اُس کو اُسکے رب نے پاک میدان میں جس کا نام طویٰ ہے [۱۱]', 'When his Lord called him in the sacred valley of Toowa,', '(Recall) when his Lord called to him in the blessed valley of Tuwā:');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(5729, 79, 17, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'اِذۡہَبۡ  اِلٰی فِرۡعَوۡنَ  اِنَّہٗ  طَغٰی  ﴿۫ۖ۱۷﴾', 'اور حکم دیا کہ فرعون کے پاس جاؤ کہ وہ سرکش ہو رہا ہے۔', 'جا فرعون کے پاس اُس نے سر اٹھایا', 'Go to Firaun (Pharaoh), verily, he has transgressed all bounds (in crimes, sins, polytheism, disbelief, etc.).', '“Go to Fir‘aun (Pharaoh). Indeed, he has crossed all bounds.'),
(5730, 79, 18, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'فَقُلۡ ہَلۡ  لَّکَ  اِلٰۤی  اَنۡ  تَزَکّٰی ﴿ۙ۱۸﴾', 'پھر اس سے کہو کہ کیا تو چاہتا ہے کہ پاک ہو جائے۔', 'پھر کہہ تیرا جی چاہتا ہے کہ تو سنور جائے', 'And say to him: \"Would you purify yourself (from the sin of disbelief by becoming a believer)\",', 'And say (to him,) ‘Would you like to purify yourself,'),
(5731, 79, 19, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'وَ  اَہۡدِیَکَ  اِلٰی  رَبِّکَ  فَتَخۡشٰی  ﴿ۚ۱۹﴾', 'اور میں تجھے تیرے پروردگار کا رستہ بتاؤں تاکہ تجھ کو خوف پیدا ہو۔', 'اور راہ بتلاؤں تجھ کو تیرے رب کی طرف پھر تجھ کو ڈر ہو [۱۲]', 'And that I guide you to your Lord, so you should fear Him?', 'and that I should guide you to your Lord, so that you fear (Him)?’”'),
(5732, 79, 20, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'فَاَرٰىہُ  الۡاٰیَۃَ  الۡکُبۡرٰی  ﴿۫ۖ۲۰﴾', 'غرض انہوں نے اسکو بہت بڑی نشانی دکھائی۔', 'پھر دکھلائی اسکو وہ بڑی نشانی [۱۳]', 'Then (Moosa (Moses)) showed him the great sign (miracles).', 'So, he (Mūsā) showed him the biggest sign.'),
(5733, 79, 21, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'فَکَذَّبَ وَ  عَصٰی ﴿۫ۖ۲۱﴾', 'مگر اس نے جھٹلایا اور نہ مانا۔', 'پھر جھٹلایا اُس نے اور نہ مانا', 'But (Firaun (Pharaoh)) belied and disobeyed;', 'But he rejected and disobeyed,'),
(5734, 79, 22, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'ثُمَّ  اَدۡبَرَ  یَسۡعٰی  ﴿۫ۖ۲۲﴾', 'پھر لوٹ گیا اور تدبیریں کرنے لگا۔', 'پھر چلا پیٹھ پھیر کر تلاش کرتا ہوا [۱۴]', 'Then he turned his back, striving hard (against Allah).', 'then he turned back, and tried hard (to refute the Messenger),'),
(5735, 79, 23, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'فَحَشَرَ  فَنَادٰی ﴿۫ۖ۲۳﴾', 'سو اس نے لوگوں کو اکٹھا کیا پھر بلند آواز سے بولا۔', 'پھر سبکو جمع کیا پھر پکارا', 'Then he gathered his people and cried aloud,', 'then he gathered (his people) and shouted'),
(5736, 79, 24, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'فَقَالَ  اَنَا  رَبُّکُمُ   الۡاَعۡلٰی ﴿۫ۖ۲۴﴾', 'سو کہنے لگا کہ تمہارا سب سے بڑا مالک میں ہوں۔', 'تو کہا میں ہوں رب تمہارا سب سے اوپر [۱۵]', 'Saying: \"I am your lord, most high\",', 'and said, “I am your supreme lord.”'),
(5737, 79, 25, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'فَاَخَذَہُ  اللّٰہُ  نَکَالَ الۡاٰخِرَۃِ  وَ الۡاُوۡلٰی ﴿ؕ۲۵﴾', 'تو اللہ نے اسکو دنیا اور آخرت دونوں کے عذاب میں پکڑ لیا۔', 'پھر پکڑا اسکو اللہ نے سزا میں آخرت کی اور دنیا کی [۱۶]', 'So Allah, seized him with punishment for his last (i.e. his saying: \"I am your lord, most high\") (see Verse 79:24)) and first ((i.e. his saying, \"O chiefs! I know not that you have a god other than I\" (see Verse 28:38)) transgression.', 'So, Allah seized him for an exemplary punishment in the Hereafter and the present world.'),
(5738, 79, 26, 1, 3, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'اِنَّ  فِیۡ ذٰلِکَ لَعِبۡرَۃً  لِّمَنۡ  یَّخۡشٰی ﴿ؕ٪۲۶﴾', 'جو شخص اللہ سے ڈر رکھتا ہے اس کے لئے اس قصے میں عبرت ہے۔', 'بیشک اس میں سوچنے کی جگہ ہے جس کے دل میں ڈر ہے [۱۷]', 'Verily, in this is an instructive admonition for whosoever fears Allah.', 'Indeed, there is a lesson for him who fears (Allah).'),
(5739, 79, 27, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'ءَاَنۡتُمۡ اَشَدُّ خَلۡقًا  اَمِ  السَّمَآءُ ؕ بَنٰہَا ﴿ٝ۲۷﴾', 'بھلا تمہارا بنانا مشکل ہے یا آسمان کا؟ اللہ نے اسکو بنایا۔', 'کیا تمہارا بنانا مشکل ہے یا آسمان کا [۱۸] اُس نے اُسکو بنا لیا', 'Are you more difficult to create, or is the heaven that He constructed?', 'Is your creation more difficult or that of the sky? He has built it,'),
(5740, 79, 28, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'رَفَعَ سَمۡکَہَا فَسَوّٰىہَا ﴿ۙ۲۸﴾', 'اس کی چھت کو اونچا کیا پھر اسے برابر کر دیا۔', 'اونچا کیا اس کا ابھار پھر اُسکو برابر کیا', 'He raised its height, and He has equally ordered it,', 'He has raised its height, then made it proper,'),
(5741, 79, 29, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'وَ اَغۡطَشَ لَیۡلَہَا وَ اَخۡرَجَ ضُحٰہَا ﴿۪۲۹﴾', 'اور اسی نے رات تاریک بنائی اور دن کو دھوپ نکالی۔', 'اور اندھیری کی رات اُسکی اور کھول نکالی اُسکی دھوپ [۱۹]', 'Its night He covers with darkness, and its forenoon He brings out (with light).', 'and darkened its night, and brought forth its daylight,'),
(5742, 79, 30, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'وَ  الۡاَرۡضَ بَعۡدَ ذٰلِکَ دَحٰىہَا ﴿ؕ۳۰﴾', 'اور اسکے بعد زمین کو پھیلا دیا۔', 'اور زمین کو اُسکے پیچھے صاف بچھا دیا [۲۰]', 'And after that He spread the earth;', 'and, after that, He spread out the earth.'),
(5743, 79, 31, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'اَخۡرَجَ  مِنۡہَا مَآءَہَا وَ  مَرۡعٰہَا ﴿۪۳۱﴾', 'اسی نے زمین میں سے اسکا پانی نکالا اور چارہ اگایا۔', 'باہر نکالا زمین سے اُس کا پانی اور چارا [۲۱]', 'And brought forth therefrom its water and its pasture;', 'From it, He brought out its water and its meadows,'),
(5744, 79, 32, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'وَ الۡجِبَالَ  اَرۡسٰہَا ﴿ۙ۳۲﴾', 'اور اس پر پہاڑوں کا بوجھ رکھ دیا۔', 'اور پہاڑوں کو قائم کر دیا [۲۲]', 'And the mountains He has fixed firmly;', 'and firmly fixed the mountains,'),
(5745, 79, 33, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'مَتَاعًا  لَّکُمۡ  وَ  لِاَنۡعَامِکُمۡ ﴿ؕ۳۳﴾', 'یہ سب کچھ تمہارے اور تمہارے مویشیوں کے فائدے کے لئے کیا۔', 'کام چلانے کو تمہارے اور تمہارے چوپایوں کے [۲۳]', '(To be) a provision and benefit for you and your cattle.', '(all this) as a benefit to you and your cattle.'),
(5746, 79, 34, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'فَاِذَا جَآءَتِ  الطَّآمَّۃُ  الۡکُبۡرٰی  ﴿۫ۖ۳۴﴾', 'پھر جب وہ بہت بڑی آفت آئے گی۔', 'پھر جب آئے وہ بڑا ہنگامہ', 'But when there comes the greatest catastrophe (i.e. the Day of Recompense, etc.),', 'So when the Greatest Havoc will take place'),
(5747, 79, 35, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'یَوۡمَ  یَتَذَکَّرُ الۡاِنۡسَانُ مَا سَعٰی  ﴿ۙ۳۵﴾', 'اس دن انسان جو محنت وہ کرتا رہا یاد کرے گا۔', 'جس دن کہ یاد کرے گا آدمی جو اُس نے کمایا', 'The Day when man shall remember what he strove for,', 'on the day when man will recall what he did,'),
(5748, 79, 36, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'وَ بُرِّزَتِ الۡجَحِیۡمُ  لِمَنۡ یَّرٰی  ﴿۳۶﴾', 'اور دوزخ دیکھنے والے کے سامنے لا کر رکھ دی جائے گی۔', 'اور نکال ظاہر کر دیں دوزخ کو جو چاہے دیکھے [۲۴]', 'And Hell-fire shall be made apparent in full view for (every) one who sees,', 'and the Hell will be exposed for all who see,'),
(5749, 79, 37, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'فَاَمَّا مَنۡ طَغٰی ﴿ۙ۳۷﴾', 'اب جس نے سرکشی کی۔', 'سو جس نے کی ہو شرارت', 'Then, for him who Tagha (transgressed all bounds, in disbelief, oppression and evil deeds of disobedience to Allah).', 'then for the one who had rebelled,'),
(5750, 79, 38, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'وَ اٰثَرَ  الۡحَیٰوۃَ  الدُّنۡیَا ﴿ۙ۳۸﴾', 'اور دنیا کی زندگی کو مقدم رکھا۔', 'اور بہتر سمجھا ہو دنیا کا جینا [۲۵]', 'And preferred the life of this world (by following his evil desires and lusts),', 'and preferred the worldly life (to the Hereafter),'),
(5751, 79, 39, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'فَاِنَّ الۡجَحِیۡمَ ہِیَ الۡمَاۡوٰی ﴿ؕ۳۹﴾', 'تو اس کا ٹھکانہ دوزخ ہی ہے۔', 'سو دوزخ ہی ہے اُس کا ٹھکانہ', 'Verily, his abode will be Hell-fire;', 'the Hell will be the abode,'),
(5752, 79, 40, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'وَ اَمَّا مَنۡ خَافَ مَقَامَ رَبِّہٖ وَ نَہَی النَّفۡسَ عَنِ  الۡہَوٰی ﴿ۙ۴۰﴾', 'اور جو اپنے پروردگار کے سامنے کھڑے ہونے سے ڈرتا اور نفس کو بیجا خواہشوں سے روکتا رہا۔', 'اور جو کوئی ڈرا ہو اپنے رب کے سامنے کھڑے ہونے سے اور روکا ہو اُس نے جی کو خواہش سے', 'But as for him who feared standing before his Lord, and restrained himself from impure evil desires, and lusts.', 'whereas for the one who feared to stand before his Lord, and restrained his self from the (evil) desire,'),
(5753, 79, 41, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'فَاِنَّ  الۡجَنَّۃَ  ہِیَ الۡمَاۡوٰی ﴿ؕ۴۱﴾', 'تو اس کا ٹھکانہ بہشت ہی ہے۔', 'سو بہشت ہے اُس کا ٹھکانہ [۲۶]', 'Verily, Paradise will be his abode.', 'the Paradise will be the abode.'),
(5754, 79, 42, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'یَسۡـَٔلُوۡنَکَ عَنِ السَّاعَۃِ  اَیَّانَ مُرۡسٰہَا ﴿ؕ۴۲﴾', 'اے پیغمبر ﷺ لوگ تم سے قیامت کے بارے میں پوچھتے ہیں کہ اس کی آمد کب ہے۔', 'تجھ سے پوچھتے ہیں وہ گھڑی کب ہو گا قیام اُس کا [۲۷]', 'They ask you (O Muhammad (Peace be upon him)) about the Hour, - when will be its appointed time?', 'They ask you (O Prophet,) about the Hour (the Day of Judgment) as to when it will take place.'),
(5755, 79, 43, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'فِیۡمَ  اَنۡتَ مِنۡ  ذِکۡرٰىہَا ﴿ؕ۴۳﴾', 'سو تم اس کے ذکر کی طرف سے کس فکر میں ہو؟', 'تجھ کو کیا کام اُسکے ذکر سے', 'You have no knowledge to say anything about it,', 'In which capacity are you to tell this?'),
(5756, 79, 44, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'اِلٰی رَبِّکَ مُنۡتَہٰىہَا ﴿ؕ۴۴﴾', 'اس کا منتہا یعنی واقع ہونے کا وقت تمہارے پروردگار ہی کو معلوم ہے۔', 'تیرے رب کی طرف ہے پہنچ اُسکی [۲۸]', 'To your Lord belongs (the knowledge of) the term thereof?', 'With your Lord is the final word about it.'),
(5757, 79, 45, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'اِنَّمَاۤ  اَنۡتَ مُنۡذِرُ مَنۡ یَّخۡشٰہَا ﴿ؕ۴۵﴾', 'جو شخص اس سے ڈر رکھتا ہے تم تو اسی کو ڈر سنانے والے ہو۔', 'تو تو ڈر سنانے کے واسطے ہے اس کو جو اُس سے ڈرتا ہے [۲۹]', 'You (O Muhammad (Peace be upon him)) are only a warner for those who fear it,', 'You are only a warner for anyone who fears it.'),
(5758, 79, 46, 2, 4, 30, 'عَمَّ ', 'النّٰزِعٰتِ', 'کَاَنَّہُمۡ یَوۡمَ یَرَوۡنَہَا لَمۡ یَلۡبَثُوۡۤا اِلَّا عَشِیَّۃً  اَوۡ ضُحٰہَا ﴿٪۴۶﴾', 'جب وہ اسکو دیکھیں گے تو ایسا خیال کریں گے کہ گویا دنیا میں صرف ایک شام یا ایک صبح رہے تھے۔', 'ایسا لگے گا جس دن دیکھیں گے اُسکو کہ نہیں ٹھہرے تھے دنیا میں مگر ایک شام یا صبح اُسکی [۳۰]', 'The Day they see it, (it will be) as if they had not tarried (in this world) except an afternoon or a morning', 'The day they will see it, it will seem to them as if they did not live (in the world) but only for one afternoon or for the morning thereof.'),
(5759, 80, 1, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'عَبَسَ وَ تَوَلّٰۤی ۙ﴿۱﴾', 'پیغمبر ﷺ نے تیوری چڑھائی اور منہ پھیر لیا۔', '[۱] تیوری چڑھائی اور منہ موڑھا', '(The Prophet (Peace be upon him)) frowned and turned away,', 'He (the Prophet) frowned and turned his face,'),
(5760, 80, 2, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'اَنۡ  جَآءَہُ  الۡاَعۡمٰی ؕ﴿۲﴾', 'کہ انکے پاس ایک نابینا آیا۔', 'اس بات سے کہ آیا اُسکے پاس اندھا [۲]', 'Because there came to him the blind man (i.e. Abdullah bin Umm-Maktoom, who came to the Prophet (Peace be upon him) while he was preaching to one or some of the Quraish chiefs).', 'because the blind man came to him!'),
(5761, 80, 3, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'وَ  مَا یُدۡرِیۡکَ لَعَلَّہٗ  یَزَّکّٰۤی ۙ﴿۳﴾', 'اور تم کو کیا خبر شاید وہ پاکیزگی حاصل کرتا۔', 'اور تجھ کو کیا خبر ہے شاید کہ وہ سنورتا', 'But what could tell you that per chance he might become pure (from sins)?', 'What could tell you (O prophet about the prospects of the blind man?) May be, (if you had attended him properly,) he would have attained purity,'),
(5762, 80, 4, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'اَوۡ یَذَّکَّرُ فَتَنۡفَعَہُ  الذِّکۡرٰی  ؕ﴿۴﴾', 'یا وہ سمجھ جاتا تو تمہارا سمجھانا اسے فائدہ دیتا۔', 'یا سوچتا تو کام آتا اُسکے سمجھانا [۳]', 'Or that he might receive admonition, and that the admonition might profit him?', 'or have received the advice, and the advice would have benefited him.'),
(5763, 80, 5, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'اَمَّا  مَنِ اسۡتَغۡنٰی ۙ﴿۵﴾', 'اب وہ جو پروا نہیں کرتا۔', 'وہ جو پروا نہں کرتا', 'As for him who thinks himself self-sufficient,', 'As for the one who does not care (about faith),'),
(5764, 80, 6, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'فَاَنۡتَ  لَہٗ  تَصَدّٰی ؕ﴿۶﴾', 'سو اسکی طرف تو تم توجہ کرتے ہو۔', 'سو تو اُسکی فکر میں ہے', 'To him you attend;', 'you are anxious to pursue him,'),
(5765, 80, 7, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'وَ  مَا عَلَیۡکَ  اَلَّا  یَزَّکّٰی ؕ﴿۷﴾', 'حالانکہ اگر وہ نہ سنورے تو تم پر کچھ الزام نہیں۔', 'تور تجھ پر کچھ الزام نہیں کہ وہ نہیں درست ہوتا [۴]', 'What does it matter to you if he will not become pure (from disbelief, you are only a Messenger, your duty is to convey the Message of Allah).', 'while there is no blame on you, if he does not attain purity.'),
(5766, 80, 8, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'وَ اَمَّا مَنۡ جَآءَکَ یَسۡعٰی ۙ﴿۸﴾', 'اور وہ جو تمہارے پاس دوڑتا ہوا آیا۔', 'اور وہ جو آیا تیرے پاس دوڑتا', 'But as to him who came to you running.', 'As regards the one who has come to you rushing eagerly,'),
(5767, 80, 9, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'وَ ہُوَ  یَخۡشٰی ۙ﴿۹﴾', 'اور وہ اللہ سے ڈرتا بھی ہے۔', 'اور ہو ڈرتا ہے [۵]', 'And is afraid (of Allah and His Punishment),', 'while he fears (Allah),'),
(5768, 80, 10, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'فَاَنۡتَ عَنۡہُ  تَلَہّٰی ﴿ۚ۱۰﴾', 'تو اس سے تم بے رخی کرتے ہو۔', 'سو تو اُس سے تغافل کرتا ہے [۶]', 'Of him you are neglectful and divert your attention to another,', 'to him you pay no heed!'),
(5769, 80, 11, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'کَلَّاۤ  اِنَّہَا  تَذۡکِرَۃٌ ﴿ۚ۱۱﴾', 'دیکھو یہ قرآن نصیحت ہے۔', 'یوں نہیں یہ تو نصیحت ہے', 'Nay, (do not do like this), indeed it (these Verses of this Quran) are an admonition,', 'Never! (you should never act in this way,) Indeed this (Qur’ān) is an advice.'),
(5770, 80, 12, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'فَمَنۡ شَآءَ  ذَکَرَہٗ ﴿ۘ۱۲﴾', 'پس جو چاہے اسے یاد رکھے۔', 'پھر جو کوئی چاہے اسکو پڑھے [۷]', 'So whoever wills, let him pay attention to it.', 'So, whoever so wills may pay heed to it.'),
(5771, 80, 13, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'فِیۡ  صُحُفٍ مُّکَرَّمَۃٍ ﴿ۙ۱۳﴾', 'قابل ادب ورقوں میں لکھا ہوا۔', 'لکھا ہے عزت کے ورقوں میں', '(It is) in Records held (greatly) in honour (Al-Lauh Al-Mahfooz).', 'It is (recorded) in those scripts (of the Preserved Tablet) that are honoured,'),
(5772, 80, 14, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'مَّرۡفُوۡعَۃٍ  مُّطَہَّرَۃٍۭ ﴿ۙ۱۴﴾', 'جو بلند مقام پر رکھے ہوئے اور پاک ہیں۔', 'اونچے رکھے ہوئے نہایت ستھرے [۸]', 'Exalted (in dignity), purified,', 'exalted, purified,'),
(5773, 80, 15, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'بِاَیۡدِیۡ سَفَرَۃٍ ﴿ۙ۱۵﴾', 'ایسے لکھنے والوں کے ہاتھوں میں ہیں۔', 'ہاتھوں میں لکھنے والوں کے', 'In the hands of scribes (angels).', 'in the hands of those scribes'),
(5774, 80, 16, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'کِرَامٍۭ  بَرَرَۃٍ ﴿ؕ۱۶﴾', 'جو بلند مرتبہ اور نیکو کار ہیں۔', 'جو بڑے درجہ والے نیک کار ہیں [۹]', 'Honourable and obedient.', 'who are honorable, righteous.'),
(5775, 80, 17, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'قُتِلَ  الۡاِنۡسَانُ مَاۤ  اَکۡفَرَہٗ ﴿ؕ۱۷﴾', 'انسان مارا جائے یہ کیسا ناشکرا ہے۔', 'مارا جائیو آدمی کیسا نا شکرا ہے [۱۰]', 'Be cursed (the disbelieving) man! How ungrateful he is!', 'Damned is the man! How ungrateful he is!'),
(5776, 80, 18, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'مِنۡ  اَیِّ  شَیۡءٍ  خَلَقَہٗ ﴿ؕ۱۸﴾', 'اسے اللہ نے کس چیز سے بنایا۔', 'کس چیز سے بنایا اُسکو', 'From what thing did He create him?', 'From which stuff did He (Allah) create him?'),
(5777, 80, 19, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'مِنۡ  نُّطۡفَۃٍ ؕ خَلَقَہٗ  فَقَدَّرَہٗ ﴿ۙ۱۹﴾', 'نطفے سے بنایا پھر اسکا اندازہ مقرر کیا۔', 'ایک بوند سے [۱۱] بنایا اسکو پھر اندازہ پر رکھا اُسکو [۱۲]', 'From Nutfah (male and female semen drops) He created him, and then set him in due proportion;', 'from a drop of semen! He created him, and designed him in due proportion,'),
(5778, 80, 20, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'ثُمَّ السَّبِیۡلَ  یَسَّرَہٗ ﴿ۙ۲۰﴾', 'پھر اسکے لئے رستہ آسان کر دیا۔', 'پھر راہ آسان کر دی اُسکو [۱۳]', 'Then He makes the Path easy for him;', 'then He made the way easy for him,'),
(5779, 80, 21, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'ثُمَّ  اَمَاتَہٗ  فَاَقۡبَرَہٗ ﴿ۙ۲۱﴾', 'پھر اسکو موت دی سو اسے قبر میں پہنچایا۔', 'پھر اُسکو مردہ کیا پھر قبر میں رکھوا دیا اُسکو [۱۴]', 'Then He causes him to die, and puts him in his grave;', 'Later, he made him die, and put him into grave,'),
(5780, 80, 22, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'ثُمَّ  اِذَا شَآءَ  اَنۡشَرَہٗ ﴿ؕ۲۲﴾', 'پھر وہ جب چاہے گا اسے اٹھا کھڑا کریگا۔', 'پھر جب چاہا اٹھا نکالا اُسکو [۱۵]', 'Then, when it is His Will, He will resurrect him (again).', 'Thereafter, when He will intend, He will raise him up.'),
(5781, 80, 23, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'کَلَّا  لَمَّا یَقۡضِ مَاۤ  اَمَرَہٗ ﴿ؕ۲۳﴾', 'کچھ شک نہیں کہ اللہ نے اسے جو حکم دیا اس نے اس پر عمل نہ کیا۔', 'ہرگز نہیں پورا نہ کیا جو اُسکو فرمایا [۱۶]', 'Nay, but (man) has not done what He commanded him.', 'No! He has not yet fulfilled what He (Allah) had commanded him.'),
(5782, 80, 24, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'فَلۡیَنۡظُرِ الۡاِنۡسَانُ  اِلٰی  طَعَامِہٖۤ ﴿ۙ۲۴﴾', 'تو انسان کو چاہیئے کہ اپنے کھانے کی طرف نظر کرے۔', 'اب دیکھ لے آدمی اپنے کھانے کو [۱۷]', 'Then let man look at his food,', 'So, the man should consider his food,'),
(5783, 80, 25, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'اَنَّا صَبَبۡنَا  الۡمَآءَ صَبًّا ﴿ۙ۲۵﴾', 'بیشک ہم ہی نے پانی برسایا۔', 'کہ ہم نے ڈالا پانی اوپر سے گرتا ہوا', 'That We pour forth water in abundance,', 'how well We poured water,'),
(5784, 80, 26, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'ثُمَّ شَقَقۡنَا الۡاَرۡضَ شَقًّا ﴿ۙ۲۶﴾', 'پھر ہم ہی نے زمین کو اچھی طرح پھاڑا۔', 'پھر چیرا زمین کو پھاڑ کر [۱۸]', 'And We split the earth in clefts,', 'then how nicely We split the earth,'),
(5785, 80, 27, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'فَاَنۡۢبَتۡنَا فِیۡہَا حَبًّا ﴿ۙ۲۷﴾', 'پھر ہم ہی نے اس میں اناج اگایا۔', 'پھر اگایا اُس میں اناج', 'And We cause therein the grain to grow,', 'then We grew in it grain,'),
(5786, 80, 28, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'وَّ عِنَبًا وَّ  قَضۡبًا ﴿ۙ۲۸﴾', 'اور انگور اور ترکاری۔', 'اور انگور اور ترکاری', 'And grapes and clover plants (i.e. green fodder for the cattle),', 'and grapes and greens,'),
(5787, 80, 29, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'وَّ  زَیۡتُوۡنًا وَّ نَخۡلًا ﴿ۙ۲۹﴾', 'اور زیتون اور کھجوریں۔', 'اور زیتون اور کھجوریں', 'And olives and date-palms,', 'and olive and date-palms,'),
(5788, 80, 30, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'وَّ  حَدَآئِقَ غُلۡبًا ﴿ۙ۳۰﴾', 'اور گھنے گھنے باغ۔', 'اور گھن کے باغ', 'And gardens, dense with many trees,', 'and gardens, full of thick trees,'),
(5789, 80, 31, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'وَّ  فَاکِہَۃً  وَّ اَبًّا ﴿ۙ۳۱﴾', 'اور میوے اور چارا۔', 'اور میوہ اورگھاس', 'And fruits and Abba (herbage, etc.),', 'and fruits and fodder,'),
(5790, 80, 32, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'مَّتَاعًا  لَّکُمۡ  وَ لِاَنۡعَامِکُمۡ ﴿ؕ۳۲﴾', 'یہ سب کچھ تمہارے اور تمہارے مویشیوں کیلئے بنایا۔', 'کام چلانے کو تمہارے اور تمہارے چوپایوں کے [۱۹]', '(To be) a provision and benefit for you and your cattle.', 'as a benefit for you and your cattle.'),
(5791, 80, 33, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'فَاِذَا جَآءَتِ الصَّآخَّۃُ ﴿۫۳۳﴾', 'تو جب کانوں کو پھاڑنے والی آواز آئے گی۔', 'پھر جب آئے وہ کان پھوڑنے والی [۲۰]', 'Then, when there comes As-Sakhkhah (the Day of Resurrections second blowing of Trumpet),', 'So when the Deafening Noise will occur,'),
(5792, 80, 34, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'یَوۡمَ  یَفِرُّ  الۡمَرۡءُ مِنۡ  اَخِیۡہِ ﴿ۙ۳۴﴾', 'اس دن آدمی اپنے بھائی سے دور بھاگے گا۔', 'جس دن کے بھاگے مرد اپنے بھائی سے', 'That Day shall a man flee from his brother,', 'the Day when one will flee from his brother,'),
(5793, 80, 35, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'وَ اُمِّہٖ  وَ اَبِیۡہِ ﴿ۙ۳۵﴾', 'اور اپنی ماں اور اپنے باپ سے۔', 'اور اپنی ماں اور اپنے باپ سے', 'And from his mother and his father,', 'and from his mother and father,'),
(5794, 80, 36, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'وَ صَاحِبَتِہٖ  وَ بَنِیۡہِ ﴿ؕ۳۶﴾', 'اور اپنی بیوی اور اپنے بیٹوں سے بھی۔', 'اور اپنی ساتھ والی سے اور اپنے بیٹوں سے', 'And from his wife and his children.', 'and from his wife and sons,'),
(5795, 80, 37, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'لِکُلِّ امۡرِیًٔ مِّنۡہُمۡ یَوۡمَئِذٍ شَاۡنٌ یُّغۡنِیۡہِ ﴿ؕ۳۷﴾', 'ہر شخص اس روز ایک فکر میں ہو گا جو اسے سب سے بے نیاز کر دیگی۔', 'ہر مرد کو اُن میں سے اُس دن ایک فکر لگا ہوا ہے جو اُسکے لئے کافی ہے [۲۱]', 'Everyman, that Day, will have enough to make him careless of others.', 'every one of them will be too engaged in his own affairs to care for others.'),
(5796, 80, 38, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'وُجُوۡہٌ  یَّوۡمَئِذٍ مُّسۡفِرَۃٌ ﴿ۙ۳۸﴾', 'اور کتنے چہرے اس روز چمک رہے ہونگے۔', 'کتنے منہ اُس دن روشن ہیں', 'Some faces that Day, will be bright (true believers of Islamic Monotheism).', 'Many faces, on that day, will be bright,'),
(5797, 80, 39, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'ضَاحِکَۃٌ  مُّسۡتَبۡشِرَۃٌ ﴿ۚ۳۹﴾', 'خنداں و شاداں یہ نیکوکار ہیں۔', 'ہنستے خوشیاں کرتے [۲۲]', 'Laughing, rejoicing at good news (of Paradise).', 'laughing, rejoicing,'),
(5798, 80, 40, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'وَ وُجُوۡہٌ  یَّوۡمَئِذٍ عَلَیۡہَا غَبَرَۃٌ ﴿ۙ۴۰﴾', 'اور اس روز کتنے چہرے ایسے ہونگے جن پر گرد پڑ رہی ہو گی۔', 'اور کتنے منہ اُس دن اُن پر گرد پڑی ہے', 'And other faces, that Day, will be dust-stained;', 'and many faces, on that day, will be stained with dust,'),
(5799, 80, 41, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'تَرۡہَقُہَا قَتَرَۃٌ ﴿ؕ۴۱﴾', 'اور ان پر سیاہی چڑھ رہی ہو گی۔', 'چڑھی آتی ہے اُن پر سیاہی [۲۳]', 'Darkness will cover them,', 'covered by darkness.'),
(5800, 80, 42, 1, 5, 30, 'عَمَّ ', 'عَبَسَ', 'اُولٰٓئِکَ ہُمُ الۡکَفَرَۃُ  الۡفَجَرَۃُ ﴿٪۴۲﴾', 'یہی لوگ ہونگے انکار کرنے والے بد کردار۔', 'یہ لوگ وہی ہیں جو منکر ہیں ڈھیٹھ [۲۴]', 'Such will be the Kafarah (disbelievers in Allah, in His Oneness, and in His Messenger Muhammad (Peace be upon him), etc.), the Fajarah (wicked evil doers).', 'Those are the disbelievers, the nefarious.'),
(5801, 81, 1, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'اِذَا  الشَّمۡسُ کُوِّرَتۡ ۪ۙ﴿۱﴾', 'جب سورج لپیٹ لیا جائے گا۔', 'جب سورج کی دھوپ تہہ ہو جائے [۱]', 'When the sun Kuwwirat (wound round and lost its light and is overthrown ).', 'When the sun will be folded up,'),
(5802, 81, 2, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ  اِذَا  النُّجُوۡمُ  انۡکَدَرَتۡ ۪ۙ﴿۲﴾', 'اور جب تارے بے نور ہو جائیں گے۔', 'اور جب تارے میلے ہو جائیں [۲]', 'And when the stars shall fall;', 'and when the stars will swoop down,'),
(5803, 81, 3, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ  اِذَا  الۡجِبَالُ سُیِّرَتۡ ۪ۙ﴿۳﴾', 'اور جب پہاڑ چلائے جائیں گے۔', 'اور جب پہاڑ چلائے جائیں [۳]', 'And when the mountains shall made to pass away;', 'and when the mountains will be set in motion,'),
(5804, 81, 4, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ  اِذَا الۡعِشَارُ عُطِّلَتۡ ۪ۙ﴿۴﴾', 'اور جب بیانے والی اونٹنیاں یونہی چھوڑ دی جائیں گی۔', 'اور جب بیاتی اونٹنیاں چھٹی پھریں [۴]', 'And when the pregnant she-camels shall be neglected;', 'and when the ten-months pregnant she-camels will be abandoned,'),
(5805, 81, 5, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ  اِذَا  الۡوُحُوۡشُ حُشِرَتۡ ۪ۙ﴿۵﴾', 'اور جب وحشی جانور جمع کئے جائیں گے۔', 'اور جب جنگل کے جانوروں میں رول پڑ جائے [۵]', 'And when the wild beasts shall be gathered together;', 'and when the wild beasts will be gathered together,'),
(5806, 81, 6, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ  اِذَا  الۡبِحَارُ سُجِّرَتۡ ۪ۙ﴿۶﴾', 'اور جب سمندر آگ ہو جائیں گے۔', 'اور جب دریا جھونکے جائیں [۶]', 'And when the seas shall become as blazing Fire or shall overflow;', 'and when the seas will be flared up,'),
(5807, 81, 7, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ  اِذَا النُّفُوۡسُ زُوِّجَتۡ ۪ۙ﴿۷﴾', 'اور جب روحیں جسموں سے ملا دی جائیں گی۔', 'اور جب جیوں کے جوڑے باندھے جائیں [۷]', 'And when the souls shall be joined with their bodies;', 'and when the people will be arranged in categories,'),
(5808, 81, 8, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ  اِذَا  الۡمَوۡءٗدَۃُ  سُئِلَتۡ ۪ۙ﴿۸﴾', 'اور جب اس بچی سے جو زندہ دفنا دی گئ ہو پوچھا جائے گا۔', 'اور جب بیٹی جیتی گاڑ دی گئ  کو  پوچھیں', 'And when the female (infant) buried alive (as the pagan Arabs used to do) shall be questioned.', 'and when the girl-child that was buried alive will be asked,'),
(5809, 81, 9, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'بِاَیِّ ذَنۡۢبٍ قُتِلَتۡ ۚ﴿۹﴾', 'کہ وہ کس گناہ کے سبب قتل کر دی گئ۔', 'کہ کس گناہ پر وہ ماری گئ [۸]', 'For what sin she was killed?', 'for what sin she was killed,'),
(5810, 81, 10, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ  اِذَا الصُّحُفُ نُشِرَتۡ ﴿۪ۙ۱۰﴾', 'اور جب اعمال کے دفتر کھولے جائیں گے۔', 'اور جب اعمالنامے کھولے جائیں', 'And when the written pages of deeds (good and bad) of every person shall be laid open;', 'and when the scrolls (of deeds) will be unrolled,'),
(5811, 81, 11, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ اِذَا  السَّمَآءُ کُشِطَتۡ ﴿۪ۙ۱۱﴾', 'اور جب آسمان کی کھال کھینچ لی جائے گی۔', 'اور جب آسمان کا پوست اتار لیں [۹]', 'And when the heaven shall be stripped off and taken away from its place;', 'and when the sky will be stripped off,'),
(5812, 81, 12, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ  اِذَا  الۡجَحِیۡمُ سُعِّرَتۡ ﴿۪ۙ۱۲﴾', 'اور جب دوزخ کی آگ بھڑکائی جائے گی۔', 'اور جب دوزخ دہکائی جائے', 'And when Hell-fire shall be kindled to fierce ablaze.', 'and when the Hell will be set ablaze,'),
(5813, 81, 13, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ  اِذَا  الۡجَنَّۃُ   اُزۡلِفَتۡ ﴿۪ۙ۱۳﴾', 'اور جب بہشت قریب لائی جائے گی۔', 'اور جب بہشت پاس لائی جائے [۱۰]', 'And when Paradise shall be brought near,', 'and when the Paradise will be brought close,'),
(5814, 81, 14, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'عَلِمَتۡ نَفۡسٌ مَّاۤ  اَحۡضَرَتۡ ﴿ؕ۱۴﴾', 'تب ہر شخص معلوم کر لے گا کہ وہ کیا لے کر آیا ہے۔', 'جان لے گا ہر ایک جی جو لے کر آیا [۱۱]', '(Then) every person will know what he has brought (of good and evil).', 'then everyone will know what he (or she) has put forward.'),
(5815, 81, 15, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'فَلَاۤ  اُقۡسِمُ  بِالۡخُنَّسِ ﴿ۙ۱۵﴾', 'پس میں ان ستاروں کی قسم کھاتا ہوں جو پیچھے ہٹ جاتے ہیں۔', 'سو قسم کھاتا ہوں میں پیچھے ہٹ جانے والوں', 'So verily, I swear by the planets that recede (i.e. disappear during the day and appear during the night).', 'So, I swear by those (stars) that recede,'),
(5816, 81, 16, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'الۡجَوَارِ الۡکُنَّسِ ﴿ۙ۱۶﴾', 'اور جو سیر کرتے اور غائب ہو جاتے ہیں۔', 'سیدھے چلنے دبک جانے والوں کی [۱۲]', 'And by the planets that move swiftly and hide themselves,', 'that proceed, that withdraw from the scene,'),
(5817, 81, 17, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ  الَّیۡلِ  اِذَا عَسۡعَسَ ﴿ۙ۱۷﴾', 'اور رات کی قسم جب وہ پھیلنے لگتی ہے۔', 'اور رات کی جب پھیل جائے [۱۳]', 'And by the night as it departs;', 'and by the night when it departs,'),
(5818, 81, 18, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ الصُّبۡحِ  اِذَا تَنَفَّسَ ﴿ۙ۱۸﴾', 'اور صبح کی قسم جب وہ نمودار ہوتی ہے۔', 'اور صبح کی جب دم بھرے [۱۴]', 'And by the dawn as it brightens;', 'and the morning when it starts breathing,'),
(5819, 81, 19, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'اِنَّہٗ  لَقَوۡلُ رَسُوۡلٍ  کَرِیۡمٍ ﴿ۙ۱۹﴾', 'کہ بیشک یہ قرآن اس فرشتہ عالی مقام کا سنایا ہوا پیغام ہے۔', 'مقرر یہ کہا ہے ایک بھیجے ہوئے عزت والے کا', 'Verily, this is the Word (this Quran brought by) a most honourable messenger (Jibrael (Gabriel), from Allah to the Prophet Muhammad (Peace be upon him)).', 'it (the Qur’ān) is surely the word of a noble messenger (Jibra’īl X),'),
(5820, 81, 20, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'ذِیۡ  قُوَّۃٍ  عِنۡدَ ذِی الۡعَرۡشِ مَکِیۡنٍ ﴿ۙ۲۰﴾', 'جو صاحب قوت ہے مالک عرش کے ہاں اونچے درجے والا ہے۔', 'قوت والا عرش کے مالک کے پاس درجہ پانے والا', 'Owner of power, and high rank with (Allah) the Lord of the Throne,', 'the one possessing power and a high status with the Lord of the Throne,'),
(5821, 81, 21, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'مُّطَاعٍ  ثَمَّ  اَمِیۡنٍ ﴿ؕ۲۱﴾', 'سردار ہے ساتھ ہی امانتدار ہے۔', 'سب کا مانا ہوا وہاں کا معتبر [۱۵]', 'Obeyed (by the angels), trustworthy there (in the heavens).', 'the one obeyed there, trusted.'),
(5822, 81, 22, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ مَا صَاحِبُکُمۡ بِمَجۡنُوۡنٍ ﴿ۚ۲۲﴾', 'اور مکے والو تمہارے رفیق یعنی ہمارے پیغمبر ﷺ دیوانے نہیں ہیں۔', 'اور یہ تمہارا رفیق کچھ دیوانہ نہیں [۱۶]', 'And (O people) your companion (Muhammad (Peace be upon him)) is not a madman;', 'Your companion (Muhammad ) is not a madman,'),
(5823, 81, 23, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ لَقَدۡ رَاٰہُ  بِالۡاُفُقِ الۡمُبِیۡنِ ﴿ۚ۲۳﴾', 'اور بیشک انہوں نے اس فرشتے کو آسمان کے کھلے کنارے پر دیکھا ہے۔', 'اور اس نے دیکھا ہے اُس فرشتہ کو آسمان کے کھلے کنارہ کے پاس [۱۷]', 'And indeed he (Muhammad (Peace be upon him)) saw him (Jibrael (Gabriel)) in the clear horizon (towards the east).', 'and he did see him (Jibra’īl X) on the clear horizon.'),
(5824, 81, 24, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ مَا ہُوَ عَلَی الۡغَیۡبِ بِضَنِیۡنٍ ﴿ۚ۲۴﴾', 'اور وہ غیب کی باتوں کے ظاہر کرنے میں بخیل نہیں۔', 'اور یہ غیب کی بات بتانے میں بخیل نہیں [۱۸]', 'And he (Muhammad (Peace be upon him)) withholds not a knowledge of the unseen.', 'And he (the Prophet) is not stingy about (the news of) the unseen.'),
(5825, 81, 25, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ مَا ہُوَ بِقَوۡلِ شَیۡطٰنٍ رَّجِیۡمٍ ﴿ۙ۲۵﴾', 'اور یہ کسی شیطان مردود کا کلام نہیں ہے۔', 'اور یہ کہا ہوا نہیں کسی شیطان مردود کا [۱۹]', 'And it (the Quran) is not the word of the outcast Shaitan (Satan).', 'Nor is it the word of an outcast satan (devil).'),
(5826, 81, 26, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'فَاَیۡنَ تَذۡہَبُوۡنَ ﴿ؕ۲۶﴾', 'پھر تم لوگ کدھر جا رہے ہو؟', 'پھر تم کدھر چلے جا رہے ہو [۲۰]', 'Then where are you going?', 'Then where are you going?'),
(5827, 81, 27, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'اِنۡ  ہُوَ  اِلَّا ذِکۡرٌ  لِّلۡعٰلَمِیۡنَ ﴿ۙ۲۷﴾', 'یہ قرآن تو تمام جہان کے لئے نصیحت ہے۔', 'یہ تو ایک نصیحت ہے جہان بھر کے واسطے [۲۱]', 'Verily, this (the Quran) is no less than a Reminder to (all) the Alameen (mankind and jinns) .', 'It is nothing else but a message of advice for all the worlds,'),
(5828, 81, 28, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'لِمَنۡ  شَآءَ مِنۡکُمۡ  اَنۡ یَّسۡتَقِیۡمَ ﴿ؕ۲۸﴾', 'یعنی اس کے لئے جو تم میں سے سیدھی راہ چلنا چاہے۔', 'جو کوئی چاہے تم میں سے کہ سیدھا چلے [۲۲]', 'To whomsoever among you who wills to walk straight,', 'for the benefit of any one from among you who intends to go straight.'),
(5829, 81, 29, 1, 6, 30, 'عَمَّ ', ' التَّکوِیر', 'وَ مَا تَشَآءُوۡنَ  اِلَّاۤ  اَنۡ یَّشَآءَ اللّٰہُ  رَبُّ الۡعٰلَمِیۡنَ ﴿٪۲۹﴾', 'اور تم لوگ کچھ بھی نہیں چاہ سکتے مگر وہی جو اللہ رب العالمین چاہے۔', 'اور تم جبھی چاہو کہ چاہے اللہ سارے جہان کا مالک [۲۳]', 'And you will not, unless (it be) that Allah wills, the Lord of the Alameen (mankind, jinns and all that exists).', 'And you cannot intend (to do anything) unless it is so willed by Allah, the Lord of all the worlds.'),
(5830, 82, 1, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'اِذَا  السَّمَآءُ  انۡفَطَرَتۡ ۙ﴿۱﴾', 'جب آسمان پھٹ جائے گا۔', 'جب آسمان چِر جائے', 'When the heaven is cleft asunder.', 'When the sky will be cleft asunder,'),
(5831, 82, 2, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'وَ  اِذَا الۡکَوَاکِبُ انۡتَثَرَتۡ ۙ﴿۲﴾', 'اور جب تارے جھڑ پڑیں گے۔', 'اور جب تارے جھڑ  پڑیں', 'And when the stars have fallen and scattered;', 'and when the stars will disperse,'),
(5832, 82, 3, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'وَ  اِذَا الۡبِحَارُ فُجِّرَتۡ ﴿ۙ۳﴾', 'اور جب سمندر ابل پڑیں گے۔', 'اور جب دریا ابل نکلیں [۱]', 'And when the seas are burst forth (got dried up);', 'and when the seas will be burst forth,'),
(5833, 82, 4, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'وَ  اِذَا الۡقُبُوۡرُ بُعۡثِرَتۡ ۙ﴿۴﴾', 'اور جب قبریں اکھیڑ دی جائیں گی۔', 'اور جب قبریں زیروزبر کر دی جائیں [۲]', 'And when the graves are turned upside down (and they bring out their contents)', 'and when the graves will be overturned,'),
(5834, 82, 5, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'عَلِمَتۡ نَفۡسٌ مَّا قَدَّمَتۡ وَ اَخَّرَتۡ ؕ﴿۵﴾', 'تب ہر شخص معلوم کر لے گا کہ اس نے آگے کیا بھیجا تھا اور پیچھے کیا چھوڑا۔', 'جان لے ہر ایک جی جو کچھ کہ آگے بھیجا اور پیچھے چھوڑا [۳]', '(Then) a person will know what he has sent forward and (what he has) left behind (of good or bad deeds).', 'then one will know what he sent ahead and what he left behind.'),
(5835, 82, 6, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'یٰۤاَیُّہَا  الۡاِنۡسَانُ مَا غَرَّکَ بِرَبِّکَ الۡکَرِیۡمِ ۙ﴿۶﴾', 'اے انسان تجھ کو اپنے رب کریم کے بارے میں کس چیز نے دھوکا دیا؟', 'اے آدمی کس چیز سے بہکا تو اپنے رب کریم پر [۴]', 'O man! What has made you careless concerning your Lord, the Most Generous?', 'O man! What has deceived you about your Gracious Lord,'),
(5836, 82, 7, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'الَّذِیۡ خَلَقَکَ فَسَوّٰىکَ فَعَدَلَکَ ۙ﴿۷﴾', 'وہی تو ہے جس نے تجھے بنایا پھر تیرے اعضاء کو درست کیا اور تیری قامت کو معتدل رکھا۔', 'جس نے تجھ کو بنایا پھر تجھ کو ٹھیک کیا پھر تجھ کو برابر کیا [۵]', 'Who created you, fashioned you perfectly, and gave you due proportion;', 'who created you, then perfected you, then brought you in due proportion?'),
(5837, 82, 8, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'فِیۡۤ  اَیِّ صُوۡرَۃٍ  مَّا شَآءَ  رَکَّبَکَ ؕ﴿۸﴾', 'جس صورت میں چاہا تجھے جوڑ دیا۔', 'جس صورت میں چاہا تجھ کو جوڑ دیا [۶]', 'In whatever form He willed, He put you together.', 'He composed you in whichever form He willed.'),
(5838, 82, 9, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'کَلَّا  بَلۡ تُکَذِّبُوۡنَ بِالدِّیۡنِ ۙ﴿۹﴾', 'مگر افسوس تم لوگ جزا کو جھٹلاتے ہو۔', 'ہرگز نہیں پر تم جھوٹ جانتے ہو انصاف کا ہونا [۷]', 'Nay! But you deny the Recompense (reward for good deeds and punishment for evil deeds).', 'Never! (i.e. one should never be heedless towards him.) But you deny the Requital,'),
(5839, 82, 10, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'وَ  اِنَّ عَلَیۡکُمۡ  لَحٰفِظِیۡنَ ﴿ۙ۱۰﴾', 'حالانکہ تم پر نگہبان مقرر ہیں۔', 'اور تم پر نگہبان مقرر ہیں', 'But verily, over you (are appointed angels in charge of mankind) to watch you ,', 'while (appointed) over you there are watchers,'),
(5840, 82, 11, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'کِرَامًا  کَاتِبِیۡنَ ﴿ۙ۱۱﴾', 'یعنی معزز کاتبین۔', 'عزت والے عمل لکھنے والے', 'Kiraman (honourable) Katibeen writing down (your deeds) ,', 'who are noble, writers (of the deeds),'),
(5841, 82, 12, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'یَعۡلَمُوۡنَ مَا تَفۡعَلُوۡنَ ﴿۱۲﴾', 'جو کچھ تم کرتے ہو وہ اسے جانتے ہیں۔', 'جانتے ہیں جو کچھ تم کرتے ہو [۸]', 'They know all that you do.', 'who know whatever you do.'),
(5842, 82, 13, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'اِنَّ  الۡاَبۡرَارَ لَفِیۡ نَعِیۡمٍ ﴿ۚ۱۳﴾', 'بیشک نیکوکار نعمتوں کی بہشت میں ہونگے۔', 'بیشک نیک لوگ بہشت میں ہیں [۹]', 'Verily, the Abrar (pious and righteous) will be in delight (Paradise);', 'Surely the righteous will be in bliss,'),
(5843, 82, 14, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'وَ  اِنَّ  الۡفُجَّارَ لَفِیۡ جَحِیۡمٍ ﴿ۚۖ۱۴﴾', 'اور بدکردار دوزخ میں۔', 'اور بیشک گنہگار دوزخ میں ہیں', 'And verily, the Fujjar (the wicked, disbelievers, sinners and evil-doers) will be in the blazing Fire (Hell),', 'and the sinners in Hell,'),
(5844, 82, 15, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'یَّصۡلَوۡنَہَا یَوۡمَ الدِّیۡنِ ﴿۱۵﴾', 'یعنی جزا کے دن اس میں داخل ہوں گے۔', 'ڈالے جائیں گے اُس میں انصاف کے دن', 'In which they will enter, and taste its burning flame on the Day of Recompense,', 'in which they will enter on the Day of Requital,'),
(5845, 82, 16, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'وَ مَا ہُمۡ عَنۡہَا بِغَآئِبِیۡنَ ﴿ؕ۱۶﴾', 'اور اس سے چھپ نہیں سکیں گے۔', 'اور نہ ہوں گے اُس سے جدا ہونے والے [۱۰]', 'And they (Al-Fujjar) will not be absent therefrom (i.e. will not go out from the Hell).', 'and they will not (be able to) keep away from it.'),
(5846, 82, 17, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'وَ مَاۤ  اَدۡرٰىکَ مَا یَوۡمُ الدِّیۡنِ ﴿ۙ۱۷﴾', 'اور تمہیں کیا معلوم کہ جزا کا دن کیسا ہے۔', 'اور تجھ کو کیا خبر ہے کیسا ہے دن انصاف کا', 'And what will make you know what the Day of Recompense is?', 'And what may let you know what the Day of Requital is?'),
(5847, 82, 18, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'ثُمَّ  مَاۤ  اَدۡرٰىکَ مَا یَوۡمُ الدِّیۡنِ ﴿ؕ۱۸﴾', 'پھر تمہیں کیا معلوم کہ جزا کا دن کیسا ہے۔', 'پھر بھی تجھ کو کیا خبر ہے کیسا ہے دن انصاف کا', 'Again, what will make you know what the Day of Recompense is?', 'Again, what may let you know what the Day of Requital is?'),
(5848, 82, 19, 1, 7, 30, 'عَمَّ ', ' الاِنفِطَار', 'یَوۡمَ لَا تَمۡلِکُ نَفۡسٌ لِّنَفۡسٍ شَیۡئًا ؕ وَ الۡاَمۡرُ  یَوۡمَئِذٍ  لِّلّٰہِ ﴿٪۱۹﴾', 'جس روز کوئی کسی  کے کچھ کام نہ آ سکے گا۔ اور حکم اس روز اللہ ہی کا ہو گا۔', 'جس دن کہ بھلا نہ کر سکے کوئی جی کسی جی کا کچھ بھی [۱۱] اور حکم اُس دن اللہ ہی کا ہے [۱۲]', '(It will be) the Day when no person shall have power (to do) anything for another, and the Decision, that Day, will be (wholly) with Allah.', 'A Day when no one will have power to do any thing for another! And command, on that Day, will belong to Allah (alone).'),
(5849, 83, 1, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'وَیۡلٌ   لِّلۡمُطَفِّفِیۡنَ ۙ﴿۱﴾', 'ناپ اور تول میں کمی کرنے والوں کے لئے خرابی ہے۔', 'خرابی ہے گھٹانے والوں کی', 'Woe to Al-Mutaffifin (those who give less in measure and weight (decrease the rights of others)),', 'Woe to the curtailers'),
(5850, 83, 2, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'الَّذِیۡنَ  اِذَا  اکۡتَالُوۡا عَلَی النَّاسِ یَسۡتَوۡفُوۡنَ ۫﴿ۖ۲﴾', 'جو لوگوں سے ناپ کر لیں تو پورا لیں۔', 'وہ لوگ کہ جب ماپ کر لیں لوگوں سے تو  پورا بھر لیں', 'Those who, when they have to receive by measure from men, demand full measure,', 'who, when they measure something to receive from people, take it in full,'),
(5851, 83, 3, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'وَ  اِذَا کَالُوۡہُمۡ  اَوۡ وَّزَنُوۡہُمۡ  یُخۡسِرُوۡنَ ﴿ؕ۳﴾', 'اور جب ان کو ناپ کر یا تول کر دیں تو کم دیں۔', 'اور جب ماپ کر دیں اُنکو یا تول کر تو گھٹا کر دیں [۱]', 'And when they have to give by measure or weight to men, give less than due.', 'and when they measure or weigh something to give it to them, give less than due.'),
(5852, 83, 4, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'اَلَا یَظُنُّ  اُولٰٓئِکَ اَنَّہُمۡ مَّبۡعُوۡثُوۡنَ ۙ﴿۴﴾', 'کیا یہ لوگ یہ نہیں خیال کرتے کہ اٹھائے بھی جائیں گے۔', 'کیا خیال نہیں رکھتے وہ لوگ کہ اُنکو اٹھنا ہے', 'Think they not that they will be resurrected (for reckoning),', 'Do they not think that they have to be raised up'),
(5853, 83, 5, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'لِیَوۡمٍ عَظِیۡمٍ ۙ﴿۵﴾', 'یعنی ایک بڑے سخت دن میں۔', 'اُس بڑے دن کے واسطے [۲]', 'On a Great Day,', 'on a Great Day,'),
(5854, 83, 6, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'یَّوۡمَ یَقُوۡمُ النَّاسُ لِرَبِّ الۡعٰلَمِیۡنَ ؕ﴿۶﴾', 'جس دن تمام لوگ رب العالمین کے سامنے کھڑے ہوں گے۔', 'جس دن کھڑے رہیں لوگ راہ دیکھتے جہان کے مالک کی [۳]', 'The Day when (all) mankind will stand before the Lord of the Alameen (mankind, jinns and all that exists)?', 'the Day when all the people will stand before the Lord of the worlds?'),
(5855, 83, 7, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'کَلَّاۤ  اِنَّ  کِتٰبَ الۡفُجَّارِ لَفِیۡ  سِجِّیۡنٍ ؕ﴿۷﴾', 'سن رکھو کہ بدکاروں کے اعمال نامے سجّین میں ہونگے۔', 'ہر گز نہیں [۴] بیشک اعمالنامہ گنہگاروں کا سجین میں ہے', 'Nay! Truly, the Record (writing of the deeds) of the Fujjar (disbelievers, sinners, evil-doers and wicked) is (preserved) in Sijjeen.', 'Never! (i.e. they should never act in such a way.) Indeed the record of deeds of the sinners is in Sijjīn .'),
(5856, 83, 8, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'وَ مَاۤ  اَدۡرٰىکَ مَا سِجِّیۡنٌ ؕ﴿۸﴾', 'اور تم کیا جانتے ہو کہ سجّین کیا چیز ہے۔', 'اور تجھ کو کیا خبر ہے کیا ہے سجین', 'And what will make you know what Sijjeen is?', 'And what may let you know what Sijjīn is?'),
(5857, 83, 9, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'کِتٰبٌ مَّرۡقُوۡمٌ ؕ﴿۹﴾', 'ایک دفتر ہے لکھا ہوا۔', 'ایک دفتر ہے لکھا ہوا [۵]', 'A Register inscribed.', 'A register, inscribed!'),
(5858, 83, 10, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'وَیۡلٌ یَّوۡمَئِذٍ لِّلۡمُکَذِّبِیۡنَ ﴿ۙ۱۰﴾', 'اس دن جھٹلانے والوں کیلئے خرابی ہے۔', 'خرابی ہے اُس دن جھٹلانے والوں کی', 'Woe, that Day, to those who deny ((Allah, His Angels, His Books, His Messengers, the Day of Resurrection, and Al-Qadar (Divine Preordainments)).', 'Woe that day to the deniers,'),
(5859, 83, 11, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'الَّذِیۡنَ یُکَذِّبُوۡنَ بِیَوۡمِ الدِّیۡنِ ﴿ؕ۱۱﴾', 'یعنی جو انصاف کے دن کو جھٹلاتے ہیں۔', 'جو جھوٹ جانتے ہیں انصاف کے دن کو', 'Those who deny the Day of Recompense.', 'who deny the Day of Requital!'),
(5860, 83, 12, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'وَ مَا یُکَذِّبُ بِہٖۤ  اِلَّا کُلُّ مُعۡتَدٍ اَثِیۡمٍ ﴿ۙ۱۲﴾', 'اور اس کو جھٹلاتا وہی ہے جو حد سے نکل جانے والا گنہگار ہے۔', 'اور اسکو جھٹلاتا ہے وہی جو بڑھ نکلنے والا گنہگار ہے [۶]', 'And none can deny it except every transgressor beyond bounds, (in disbelief, oppression and disobedience of Allah, the sinner!)', 'And none denies it but every sinful transgressor.'),
(5861, 83, 13, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'اِذَا  تُتۡلٰی عَلَیۡہِ  اٰیٰتُنَا  قَالَ اَسَاطِیۡرُ الۡاَوَّلِیۡنَ ﴿ؕ۱۳﴾', 'جب اسکو ہماری آیتیں سنائی جاتی ہیں تو کہتا ہے یہ تو پہلے لوگوں کے افسانے ہیں۔', 'جب سنائے اسکو ہماری آیتیں کہے نقلیں ہیں پہلوں کی [۷]', 'When Our Verses (of the Quran) are recited to him he says: \"Tales of the ancients!\"', 'When Our verses are recited to him, he says, “(These are) tales of the ancients.”'),
(5862, 83, 14, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'کَلَّا بَلۡ ٜ رَانَ عَلٰی قُلُوۡبِہِمۡ مَّا کَانُوۡا یَکۡسِبُوۡنَ ﴿۱۴﴾', 'ہر گز نہیں بات یہ ہے کہ یہ جو اعمال بد کرتے ہیں۔ ان کا انکے دلوں پر زنگ بیٹھ گیا ہے۔', 'کوئی نہیں پر  زنگ پکڑ گیا ہے اُنکے دلوں پر جو وہ کماتے تھے [۸]', 'Nay! But on their hearts is the Ran (covering of sins and evil deeds) which they used to earn .', 'No! But that which they used to commit has covered their hearts with rust.'),
(5863, 83, 15, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'کَلَّاۤ  اِنَّہُمۡ عَنۡ رَّبِّہِمۡ یَوۡمَئِذٍ لَّمَحۡجُوۡبُوۡنَ ﴿ؕ۱۵﴾', 'بیشک یہ لوگ اس روز اپنے پروردگار کے دیدار سے اوٹ میں ہوں گے۔', 'کوئی نہیں وہ اپنے رب سے اُس دن روک دیے جائیں گے [۹]', 'Nay! Surely, they (evil-doers) will be veiled from seeing their Lord that Day.', 'No! Indeed they will be screened off from their Lord on that Day.'),
(5864, 83, 16, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'ثُمَّ  اِنَّہُمۡ  لَصَالُوا الۡجَحِیۡمِ ﴿ؕ۱۶﴾', 'پھر یہ لوگ یقینًا دوزخ میں جا داخل ہوں گے۔', 'پھر مقرر وہ گرنے والے ہیں دوزخ میں', 'Then, verily they will indeed enter and taste the burning flame of Hell', 'Then they will have to enter the Hell.'),
(5865, 83, 17, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'ثُمَّ یُقَالُ ہٰذَا الَّذِیۡ کُنۡتُمۡ بِہٖ تُکَذِّبُوۡنَ ﴿ؕ۱۷﴾', 'پھر ان سے کہا جائے گا کہ یہ وہی چیز ہے جسکو تم جھٹلاتے تھے۔', 'پھر کہا جائے گا یہ وہی ہے جسکو تم جھوٹ جانتے تھے', 'Then, it will be said to them: \"This is what you used to deny!\"', 'Then it will be said, “This is what you used to deny.”'),
(5866, 83, 18, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'کَلَّاۤ  اِنَّ  کِتٰبَ الۡاَبۡرَارِ لَفِیۡ عِلِّیِّیۡنَ ﴿ؕ۱۸﴾', 'یہ بھی سن رکھو کہ نیکوکاروں کے اعمال نامے علیین میں ہونگے۔', 'ہرگز نہیں [۱۰] بیشک اعمالنامہ نیکوں کاعلیین میں ہے', 'Nay! Verily, the Record (writing of the deeds) of Al-Abrar (the pious who fear Allah and avoid evil), is (preserved) in Illiyyoon.', 'No! The record of deeds of the righteous is in ‘Illiyyūn .'),
(5867, 83, 19, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'وَ مَاۤ  اَدۡرٰىکَ مَا عِلِّیُّوۡنَ ﴿ؕ۱۹﴾', 'تمکو کیا معلوم کہ علیین کیا چیز ہے۔', 'اور تجھ کو کیاخبر ہے کیا ہے علیین', 'And what will make you know what Illiyyoon is?', 'And what may let you know what ‘Illiyyūn is ?'),
(5868, 83, 20, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'کِتٰبٌ مَّرۡقُوۡمٌ ﴿ۙ۲۰﴾', 'ایک دفتر ہے لکھا ہوا۔', 'ایک دفتر ہے لکھا ہوا [۱۱]', 'A Register inscribed.', 'A register inscribed,'),
(5869, 83, 21, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'یَّشۡہَدُہُ  الۡمُقَرَّبُوۡنَ ﴿ؕ۲۱﴾', 'جسکے پاس مقرب فرشتے حاضر ہوتے ہیں۔', 'اُسکو دیکھتے ہیں نزدیک والے یعنی فرشتے [۱۲]', 'To which bear witness those nearest (to Allah, i.e. the angels).', 'attended by those (angels) who are blessed with nearness to Allah!'),
(5870, 83, 22, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'اِنَّ  الۡاَبۡرَارَ لَفِیۡ نَعِیۡمٍ ﴿ۙ۲۲﴾', 'بیشک نیک لوگ نعمتوں میں ہوں گے۔', 'بیشک نیک لوگ ہیں آرام میں', 'Verily, Al-Abrar (the pious who fear Allah and avoid evil) will be in delight (Paradise).', 'Indeed the righteous will be in absolute bliss.'),
(5871, 83, 23, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'عَلَی الۡاَرَآئِکِ یَنۡظُرُوۡنَ ﴿ۙ۲۳﴾', 'تختوں پر بیٹھے ہوئے نظارے کریں گے۔', 'تختوں پر بیٹھے دیکھتے ہوں گے [۱۳]', 'On thrones, looking (at all things).', 'While (sitting) on thrones they will be watching (the scenes of Paradise).'),
(5872, 83, 24, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'تَعۡرِفُ فِیۡ  وُجُوۡہِہِمۡ نَضۡرَۃَ  النَّعِیۡمِ ﴿ۚ۲۴﴾', 'تم ان کے چہروں ہی سے نعمت کی تازگی معلوم کر لو گے۔', 'پہچان لے تو اُنکے منہ پر تازگی آرام کی [۱۴]', 'You will recognise in their faces the brightness of delight.', 'You will recognize the glamour of bliss on their faces.'),
(5873, 83, 25, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'یُسۡقَوۡنَ مِنۡ  رَّحِیۡقٍ مَّخۡتُوۡمٍ ﴿ۙ۲۵﴾', 'ان کو شراب خالص سربمہر پلائی جائے گی۔', 'انکو پلائی جاتی ہے شراب خالص مہر لگی ہوئی [۱۵]', 'They will be given to drink pure sealed wine.', 'They will be served with a pure sealed wine to drink,'),
(5874, 83, 26, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'خِتٰمُہٗ  مِسۡکٌ ؕ وَ فِیۡ ذٰلِکَ فَلۡیَتَنَافَسِ الۡمُتَنَافِسُوۡنَ ﴿ؕ۲۶﴾', 'جسکی مہر مشک کی ہو گی۔ تو نعمتوں کیلئے ریس کرنے والوں کو چاہیے کہ اسی کی ریس کریں۔', 'جسکی مہر جمتی ہے مشک پر [۱۶] اور اُس پر چاہیے کہ ڈھکیں ڈھکنے والے [۱۷]', 'The last thereof (that wine) will be the smell of musk, and for this let (all) those strive who want to strive (i.e. hasten earnestly to the obedience of Allah).', 'the seal of which will be of musk.-It is this (bliss) in aspiring for which the competitors should race each other.'),
(5875, 83, 27, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'وَ مِزَاجُہٗ  مِنۡ تَسۡنِیۡمٍ ﴿ۙ۲۷﴾', 'اور اس میں آب تسنیم کی آمیزش ہو گی۔', 'اور اُسکی ملونی ہے تسنیم سے', 'It (that wine) will be mixed with Tasneem.', '-and it will be blended with (a drink from) Tasnīm ,'),
(5876, 83, 28, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'عَیۡنًا یَّشۡرَبُ بِہَا الۡمُقَرَّبُوۡنَ ﴿ؕ۲۸﴾', 'وہ ایک چشمہ ہے جس میں سے اللہ کے مقرب پئیں گے۔', 'وہ ایک چشمہ ہے جس سے پیتے ہیں نزدیک والے [۱۸]', 'A spring whereof drink those nearest to Allah.', 'a spring from which will drink those who are blessed with nearness.'),
(5877, 83, 29, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'اِنَّ  الَّذِیۡنَ اَجۡرَمُوۡا کَانُوۡا مِنَ الَّذِیۡنَ اٰمَنُوۡا یَضۡحَکُوۡنَ ﴿۫ۖ۲۹﴾', 'جو گنہگار یعنی کفار ہیں وہ دنیا میں مومنوں سے ہنسی کیا کرتے تھے۔', 'وہ لوگ جو گنہگار ہیں تھے ایمان والوں سے ہنسا کرتے [۱۹]', 'Verily! (During the worldly life) those who committed crimes used to laugh at those who believed.', 'Indeed those who were guilty used to laugh at those who believed,'),
(5878, 83, 30, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'وَ اِذَا  مَرُّوۡا بِہِمۡ یَتَغَامَزُوۡنَ ﴿۫ۖ۳۰﴾', 'اور جب انکے پاس سے گذرتے تو حقارت سے اشارے کرتے۔', 'اور جب ہو کر نکلتے انکے پاس کو تو آپس میں آنکھ مارتے [۲۰]', 'And whenever they passed by them, used to wink one to another (in mockery);', 'and when they passed by them, they used to wink at one another,'),
(5879, 83, 31, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'وَ اِذَا  انۡقَلَبُوۡۤا  اِلٰۤی  اَہۡلِہِمُ  انۡقَلَبُوۡا فَکِہِیۡنَ ﴿۫ۖ۳۱﴾', 'اور جب اپنے گھر کو لوٹتے تو اتراتے ہوئے لوٹتے۔', 'اور جب پھر کر جاتے اپنے گھر پھر جاتے باتیں بناتے [۲۱]', 'And when they returned to their own people, they would return jesting;', 'and when they went back to their family, they went enjoying their mockery,'),
(5880, 83, 32, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'وَ اِذَا رَاَوۡہُمۡ قَالُوۡۤا اِنَّ ہٰۤؤُلَآءِ لَضَآلُّوۡنَ ﴿ۙ۳۲﴾', 'اور جب ان کو یعنی مومنوں کو دیکھتے تو کہتے کہ یہ تو گمراہ ہیں۔', 'اور جب اُنکو دیکھتے کہتے بیشک یہ لوگ بہک رہے ہیں [۲۲]', 'And when they saw them, they said: \"Verily! These have indeed gone astray!\"', 'and when they saw them, they said, “Surely these are the ones who have gone astray”'),
(5881, 83, 33, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'وَ  مَاۤ  اُرۡسِلُوۡا عَلَیۡہِمۡ  حٰفِظِیۡنَ ﴿ؕ۳۳﴾', 'حالانکہ وہ یعنی کافر ان پر نگراں بنا کر نہیں بھیجے گئے تھے۔', 'اور اُنکو بھیجا نہیں اُن پر نگہبان بنا کر [۲۳]', 'But they (disbelievers, sinners) had not been sent as watchers over them (the believers).', 'while they were not sent as watchmen over them.'),
(5882, 83, 34, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'فَالۡیَوۡمَ الَّذِیۡنَ اٰمَنُوۡا مِنَ الۡکُفَّارِ یَضۡحَکُوۡنَ ﴿ۙ۳۴﴾', 'تو آج مومن کافروں سے ہنسی کریں گے۔', 'سو آج ایمان والے منکروں سے ہنستے ہیں [۲۴]', 'But this Day (the Day of Resurrection) those who believe will laugh at the disbelievers', 'So, today those who believed will laugh at the disbelievers.'),
(5883, 83, 35, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'عَلَی الۡاَرَآئِکِ ۙ یَنۡظُرُوۡنَ ﴿ؕ۳۵﴾', 'کہ مسندوں پر بیٹھے ہوئے ان کا حال دیکھ رہے ہوں گے۔', 'تختوں پر بیٹھے دیکھتے ہیں [۲۵]', 'On (high) thrones, looking (at all things).', 'While (sitting) on thrones, they will be seeing'),
(5884, 83, 36, 1, 8, 30, 'عَمَّ ', 'المُطَفِّفِین', 'ہَلۡ  ثُوِّبَ الۡکُفَّارُ  مَا کَانُوۡا یَفۡعَلُوۡنَ ﴿٪۳۶﴾', 'آج کافروں کو انکے کاموں کا پورا پورا بدلہ مل گیا ناں۔', 'اب بدلا پایا ہے منکروں نے جیسا کہ کچھ کرتے تھے [۲۶]', 'Are not the disbelievers paid (fully) for what they used to do?', 'whether the disbelievers have been paid back for what they used to do.'),
(5885, 84, 1, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'اِذَا السَّمَآءُ  انۡشَقَّتۡ ۙ﴿۱﴾', 'جب آسمان پھٹ جائے گا۔', 'جب  آسمان پھٹ جائے', 'When the heaven is split asunder,', 'When the sky will split apart,'),
(5886, 84, 2, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'وَ اَذِنَتۡ لِرَبِّہَا وَ حُقَّتۡ ۙ﴿۲﴾', 'اور اپنے پروردگار کا فرمان سن لے گا اور یہی اسکے لائق بھی ہے۔', 'اور سن لے حکم اپنے رب کا وہ آسمان اسی لائق ہے [۱]', 'And listens and obeys its Lord, and it must do so;', 'and will listen to (the command of) its Lord,- and it ought to,-'),
(5887, 84, 3, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'وَ  اِذَا  الۡاَرۡضُ مُدَّتۡ ۙ﴿۳﴾', 'اور جب زمین ہموار کر دی جائے گی۔', 'اور جب زمین پھیلا دی جائے [۲]', 'And when the earth is stretched forth,', 'and when the earth will be stretched (to give room to more people),'),
(5888, 84, 4, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'وَ اَلۡقَتۡ مَا فِیۡہَا وَ تَخَلَّتۡ ۙ﴿۴﴾', 'اور جو کچھ اس میں ہے وہ اسے نکال کر باہر ڈالدے گی اور بالکل خالی ہو جائے گی۔', 'اور نکال ڈالے جو کچھ اُس میں ہے اور خالی ہو جائے [۳]', 'And has cast out all that was in it and became empty,', 'and it will throw up whatever it contains, and will become empty,'),
(5889, 84, 5, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'وَ اَذِنَتۡ لِرَبِّہَا وَ حُقَّتۡ ؕ﴿۵﴾', 'اور اپنے پروردگار کے ارشاد کی تعمیل کرے گی اور اسکو لازم بھی یہی ہے تو قیامت قائم ہو جائے گی۔', 'اور سن لے حکم اپنے رب کا اور وہ زمین اسی لائق ہے [۴]', 'And listens and obeys its Lord, and it must do so;', 'and will listen to (the command of) its Lord,- and it ought to,- (then man will see the consequences of his deeds.)');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(5890, 84, 6, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'یٰۤاَیُّہَا الۡاِنۡسَانُ  اِنَّکَ کَادِحٌ  اِلٰی رَبِّکَ کَدۡحًا  فَمُلٰقِیۡہِ ۚ﴿۶﴾', 'اے انسان تو اپنے پروردگار کی طرف پہنچنے تک خوب تکلیف اٹھاتا ہے پھر تو اس سے جا ملے گا۔', 'اے آدمی تجھ کو تکلیف اٹھانی ہے اپنے رب تک پہنچنے میں سہہ سہہ کر اُس سے ملنا ہے [۵]', 'O man! Verily, you are returning towards your Lord with your deeds and actions (good or bad), a sure returning, so you will meet (i.e. the results of your deeds which you did).', 'O man, you have to work hard constantly to reach your Lord, and then you have to meet Him.'),
(5891, 84, 7, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'فَاَمَّا مَنۡ  اُوۡتِیَ  کِتٰبَہٗ  بِیَمِیۡنِہٖ ۙ﴿۷﴾', 'اب جس کا نامہ اعمال اس کے داہنے ہاتھ میں دیا جائے گا۔', 'سو جس کو ملا اعمالنامہ اس کا داہنے ہاتھ میں', 'Then, as for him who will be given his Record in his right hand,', 'So, as for him whose book (of deeds) will be given to him in his right hand,'),
(5892, 84, 8, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'فَسَوۡفَ یُحَاسَبُ حِسَابًا یَّسِیۡرًا ۙ﴿۸﴾', 'اس سے حساب آسان لیا جائے گا۔', 'تو اُس سے حساب لیں گے آسان حساب [۶]', 'He surely will receive an easy reckoning,', 'he will be called to account in an easy manner,'),
(5893, 84, 9, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'وَّ  یَنۡقَلِبُ  اِلٰۤی  اَہۡلِہٖ مَسۡرُوۡرًا ؕ﴿۹﴾', 'اور وہ اپنے گھر والوں میں خوش خوش واپس آئے گا۔', 'اور پھر کر آئے گا اپنے لوگوں کے پاس خوش ہو کر [۷]', 'And will return to his family in joy!', 'and he will go back to his people joyfully.'),
(5894, 84, 10, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'وَ اَمَّا مَنۡ اُوۡتِیَ  کِتٰبَہٗ  وَرَآءَ ظَہۡرِہٖ ﴿ۙ۱۰﴾', 'اور جس کا نامہ اعمال اسکی پیٹھ کے پیچھے سے دیا جائے گا۔', 'اور جس کو ملا اس کا اعمالنامہ پیٹھ کے پیچھے سے [۸]', 'But whosoever is given his Record behind his back,', 'As for the one whose book (of deeds) will be given to him from his backside,'),
(5895, 84, 11, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'فَسَوۡفَ یَدۡعُوۡا  ثُبُوۡرًا ﴿ۙ۱۱﴾', 'تو وہ موت کو پکارے گا۔', 'سو وہ پکارے گا موت موت [۹]', 'He will invoke (his) destruction,', 'he will pray for death,'),
(5896, 84, 12, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'وَّ  یَصۡلٰی سَعِیۡرًا ﴿ؕ۱۲﴾', 'اور دوزخ میں داخل ہو گا۔', 'اور پڑے گا  آگ میں', 'And shall enter a blazing Fire, and made to taste its burning.', 'and will enter the blazing fire.'),
(5897, 84, 13, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'اِنَّہٗ  کَانَ  فِیۡۤ   اَہۡلِہٖ مَسۡرُوۡرًا ﴿ؕ۱۳﴾', 'وہ اپنے اہل و عیال ہی میں مگن رہتا تھا۔', 'وہ رہا تھا اپنے گھر میں بے غم [۱۰]', 'Verily, he was among his people in joy!', 'He had been joyful among his people (in the world).'),
(5898, 84, 14, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'اِنَّہٗ ظَنَّ  اَنۡ  لَّنۡ یَّحُوۡرَ ﴿ۚۛ۱۴﴾', 'وہ تو خیال کرتا تھا کہ اللہ کی طرف لوٹ کر نہ جائے گا۔', 'اُس نے خیال کیا تھا کہ پھر کر نہ جائے گا [۱۱]', 'Verily, he thought that he would never come back (to Us)!', 'He thought he would never revert (to Allah).'),
(5899, 84, 15, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'بَلٰۤی ۚۛ  اِنَّ  رَبَّہٗ  کَانَ بِہٖ بَصِیۡرًا ﴿ؕ۱۵﴾', 'کیوں نہیں اس کا پروردگار تو اس کو دیکھ رہا تھا۔', 'کیوں نہیں اُس کا رب اُسکو دیکھتا تھا [۱۲]', 'Yes! Verily, his Lord has been ever beholding him!', 'No! Indeed his Lord was watchful over him.'),
(5900, 84, 16, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'فَلَاۤ  اُقۡسِمُ  بِالشَّفَقِ ﴿ۙ۱۶﴾', 'سو میں شام کی سرخی کی قسم کھاتا ہوں۔', 'سو قسم کھاتا ہوں شام کی سرخی کی', 'So I swear by the afterglow of sunset;', 'So, I swear by the twilight (after sunset),'),
(5901, 84, 17, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'وَ الَّیۡلِ وَ مَا وَسَقَ ﴿ۙ۱۷﴾', 'اور رات کی اور جن چیزوں کو وہ اکٹھا کر لیتی ہے ان کی۔', 'اور رات کی اور جو چیزیں اُس میں سمٹ آتی ہیں [۱۳]', 'And by the night and whatever it gathers in its darkness;', 'and by the night and what it envelops,'),
(5902, 84, 18, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'وَ الۡقَمَرِ اِذَا اتَّسَقَ ﴿ۙ۱۸﴾', 'اور چاند کی جب وہ پورا ہو جائے۔', 'اور چاند کی جب پورا بھر جائے [۱۴]', 'And by the moon when it is at the full,', 'and by the moon when it develops at the full,'),
(5903, 84, 19, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'لَتَرۡکَبُنَّ  طَبَقًا عَنۡ طَبَقٍ ﴿ؕ۱۹﴾', 'کہ تم لوگ درجہ بدرجہ ضرور چڑھو گے۔', 'کہ تم کو  چڑھنا ہے سیڑھی پر سیڑھی [۱۵]', 'You shall certainly travel from stage to stage (in this life and in the Hereafter).', 'you shall certainly ascend from stage to stage.'),
(5904, 84, 20, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'فَمَا لَہُمۡ  لَا یُؤۡمِنُوۡنَ ﴿ۙ۲۰﴾', 'تو ان لوگوں کو کیا ہوا ہے کہ یہ ایمان نہیں لاتے۔', 'پھر کیا ہوا ہے اُنکو جو یقین نہیں لاتے [۱۶]', 'What is the matter with them, that they believe not?', 'So, what is wrong with them that they do not believe,'),
(5905, 84, 21, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'وَ اِذَا قُرِئَ عَلَیۡہِمُ الۡقُرۡاٰنُ  لَا یَسۡجُدُوۡنَ ﴿ؕٛ۲۱﴾', 'اور جب انکے سامنے قرآن پڑھا جاتا ہے تو سجدہ نہیں کرتے۔', 'اور جب پڑھیے انکے پا س قرآن مجید وہ سجدہ نہیں کرتے [۱۷]', 'And when the Quran is recited to them, they fall not prostrate,', 'and when the Qur’ān is recited to them, they do not offer sajdah (prostration)?'),
(5906, 84, 22, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'بَلِ الَّذِیۡنَ  کَفَرُوۡا یُکَذِّبُوۡنَ ﴿۫ۖ۲۲﴾', 'بلکہ کافر جھٹلائے جاتے ہیں۔', 'اوپر سے اور یہ کہ منکر جھٹلاتے ہیں', 'Nay, (on the contrary), those who disbelieve, belie (Prophet Muhammad (Peace be upon him) and whatever he brought, i.e. this Quran and Islamic Monotheism, etc.).', 'Rather, those who disbelieve deny (the truth).'),
(5907, 84, 23, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'وَ اللّٰہُ  اَعۡلَمُ  بِمَا یُوۡعُوۡنَ ﴿۫ۖ۲۳﴾', 'اور اللہ ان باتوں کو جو یہ اپنے دلوں میں چھپاتے ہیں خوب جانتا ہے۔', 'اور اللہ خوب جانتا ہے جو اندر بھر رکھتے ہیں [۱۸]', 'And Allah knows best what they gather (of good and bad deeds),', 'And Allah is most aware of what they store.'),
(5908, 84, 24, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'فَبَشِّرۡہُمۡ بِعَذَابٍ اَلِیۡمٍ ﴿ۙ۲۴﴾', 'تو انکو دکھ دینے والے عذاب کی خبر سنا دو۔', 'سو خوشی سنا دے اُنکو عذاب دردناک کی [۱۹]', 'So announce to them a painful torment.', 'So, give him the ‘good news’ of a painful punishment,'),
(5909, 84, 25, 1, 9, 30, 'عَمَّ ', 'الاِنشِقَاق', 'اِلَّا الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ لَہُمۡ  اَجۡرٌ  غَیۡرُ  مَمۡنُوۡنٍ ﴿٪۲۵﴾', 'ہاں جو لوگ ایمان لائے اور نیک عمل کرتے رہے ان کے لئے بے انتہا اجر ہے۔', 'مگر جو لوگ کہ یقین لائے اور کام کئے بھلے اُنکے لئے ثواب ہے بے انتہا [۲۰]', 'Save those who believe and do righteous good deeds, for them is a reward that will never come to an end (i.e. Paradise).', 'but those who believed and did righteous deeds will have a reward that will never be interrupted.'),
(5910, 85, 1, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'وَ السَّمَآءِ  ذَاتِ الۡبُرُوۡجِ ۙ﴿۱﴾', 'آسمان کی قسم جس میں برج ہیں۔', 'قسم ہے آسمان کی جس میں برج ہیں [۱]', 'By the heaven, holding the big stars .', 'I swear by the sky, the one having stellar formations,'),
(5911, 85, 2, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'وَ الۡیَوۡمِ الۡمَوۡعُوۡدِ ۙ﴿۲﴾', 'اور اس دن کی جس کا وعدہ ہے۔', 'اور اُس دن کی جس کا وعدہ ہے [۲]', 'And by the Promised Day (i.e. the Day of Resurrection);', 'and by the Promised Day,'),
(5912, 85, 3, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'وَ شَاہِدٍ وَّ مَشۡہُوۡدٍ ؕ﴿۳﴾', 'اور حاضر ہونے والے کی اور اسکی جسکے پاس حاضر ہوتے ہیں۔', 'اور اُس دن کی جو حاضر ہوتا ہے اور اُسکی کہ جسکے پاس حاضر ہوتے ہیں [۳]', 'And by the witnessing day (i.e. Friday), and by the witnessed day (i.e. the day of Arafat (Hajj) the ninth of Dhul-Heejjah);', 'and by that which attends, and that which is attended,'),
(5913, 85, 4, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'قُتِلَ اَصۡحٰبُ الۡاُخۡدُوۡدِ ۙ﴿۴﴾', 'کہ خندقوں والے ہلاک کر دیئے گئے۔', 'مارے گئے کھائیاں کھودنے والے', 'Cursed were the people of the ditch (the story of the Boy and the King).', 'cursed were the People of the Trench,'),
(5914, 85, 5, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'النَّارِ ذَاتِ الۡوَقُوۡدِ ۙ﴿۵﴾', 'یعنی آگ کی خندقیں جس میں ایندھن جھونک رکھا تھا۔', 'آگ ہے بہت ایندھن والی [۴]', 'Fire supplied (abundantly) with fuel,', 'the (people of the) fire that was rich with fuel,'),
(5915, 85, 6, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'اِذۡ ہُمۡ عَلَیۡہَا قُعُوۡدٌ ۙ﴿۶﴾', 'جبکہ وہ انکے کناروں پر بیٹھے ہوئے تھے۔', 'جب وہ اس پر بیٹھے', 'When they sat by it (fire),', 'when they were sitting by it,'),
(5916, 85, 7, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'وَّ ہُمۡ عَلٰی مَا یَفۡعَلُوۡنَ بِالۡمُؤۡمِنِیۡنَ شُہُوۡدٌ  ؕ﴿۷﴾', 'اور جو ظلم وہ اہل ایمان پر کر رہے تھے انکا نظارہ کر رہے تھے۔', 'اور جو کچھ وہ کرتے مسلمانوں کے ساتھ اپنی آنکھوں سے دیکھتے [۵]', 'And they witnessed what they were doing against the believers (i.e. burning them).', 'and were watching what they were doing with the believers.'),
(5917, 85, 8, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'وَ مَا نَقَمُوۡا مِنۡہُمۡ  اِلَّاۤ  اَنۡ یُّؤۡمِنُوۡا بِاللّٰہِ الۡعَزِیۡزِ  الۡحَمِیۡدِ ۙ﴿۸﴾', 'اور انکو مومنوں کی یہی بات بری لگتی تھی کہ وہ اللہ پر ایمان لائے تھے جو غالب ہے سب خوبیوں والا ہے۔', 'اور اُن سے بدلا نہ لیتے تھے مگر اسی بات کہ  وہ یقین لائے اللہ پر جو زبردست ہے تعریفوں والا', 'They had nothing against them, except that they believed in Allah, the All-Mighty, Worthy of all Praise!', 'They punished them for nothing but that they believed in Allah, the All-Mighty, the Worthy of All Praise,'),
(5918, 85, 9, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'الَّذِیۡ لَہٗ  مُلۡکُ السَّمٰوٰتِ وَ الۡاَرۡضِ ؕ وَ اللّٰہُ  عَلٰی کُلِّ شَیۡءٍ شَہِیۡدٌ ؕ﴿۹﴾', 'جس کی آسمانوں اور زمین میں بادشاہی ہے اور اللہ ہر چیز سے واقف ہے۔', 'جس کا راج ہے آسمانوں میں اور زمین میں اور اللہ کے سامنے ہے ہر چیز [۶]', 'Who, to Whom belongs the dominion of the heavens and the earth! And Allah is Witness over everything.', 'the One to whom belongs the Kingdom of the heavens and the earth. And Allah is witness over every thing.'),
(5919, 85, 10, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'اِنَّ  الَّذِیۡنَ فَتَنُوا الۡمُؤۡمِنِیۡنَ وَ الۡمُؤۡمِنٰتِ ثُمَّ  لَمۡ یَتُوۡبُوۡا فَلَہُمۡ عَذَابُ جَہَنَّمَ وَ لَہُمۡ عَذَابُ الۡحَرِیۡقِ ﴿ؕ۱۰﴾', 'جن لوگوں نے مومن مردوں اور مومن عورتوں کو تکلیفیں دیں اور توبہ نہ کی ان کو دوزخ کا اور عذاب بھی ہو گا اور جلنے کا عذاب بھی۔', 'تحقیق جو دین سے بچلائے ایمان والے مردوں کو اورعورتوں کو پھر توبہ نہ کی تو اُنکے لئے عذاب ہے دوزخ کا اور اُنکے لئے عذاب ہے آگ لگے کا [۷]', 'Verily, those who put into trial the believing men and believing women (by torturing them and burning them), and then do not turn in repentance, (to Allah), will have the torment of Hell, and they will have the punishment of the burning Fire.', 'Surely, those who persecuted the believing men and the believing women, then did not repent, -for them there is the torment of Jahannam (Hell), and for them there is the torment of burning.'),
(5920, 85, 11, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'اِنَّ الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ لَہُمۡ جَنّٰتٌ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ ۬ؕؑ ذٰلِکَ الۡفَوۡزُ الۡکَبِیۡرُ ﴿ؕ۱۱﴾', 'اور جو لوگ ایمان لائے اور نیک کام کرتے رہے ان کے لئے باغات ہیں جنکے نیچے نہریں بہ رہی ہیں۔ یہی بڑی کامیابی ہے۔', 'بیشک جو لوگ یقین لائے اور کیں انہوں نے بھلائیاں انکے لئے باغ ہیں جنکے نیچے بہتی ہیں نہریں یہ ہے بڑی مراد ملنی [۸]', 'Verily, those who believe and do righteous good deeds, for them will be Gardens under which rivers flow (Paradise). That is the great success.', 'As for those who believed and did righteous deeds, for them there are gardens beneath which rivers flow. That is the big achievement.'),
(5921, 85, 12, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'اِنَّ بَطۡشَ رَبِّکَ لَشَدِیۡدٌ ﴿ؕ۱۲﴾', 'بیشک تمہارے پروردگار کی پکڑ بہت سخت ہے۔', 'بیشک تیرے رب کی پکڑ سخت ہے [۹]', 'Verily, (O Muhammad (Peace be upon him)) the Grip (Punishment) of your Lord is severe.', 'The seizure of your Lord is severe indeed!'),
(5922, 85, 13, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'اِنَّہٗ  ہُوَ  یُبۡدِئُ وَ یُعِیۡدُ ﴿ۚ۱۳﴾', 'وہی پہلی دفعہ پیدا کرتا ہے اور وہی دوبارہ زندہ کرے گا۔', 'بیشک وہی کرتا ہے پہلی مرتبہ اور دوسری [۱۰]', 'Verily, He it is Who begins (punishment) and repeats (punishment in the Hereafter) (or originates the creation of everything, and then repeats it on the Day of Resurrection).', 'Surely He originates (creation) and repeats (it after death).'),
(5923, 85, 14, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'وَ ہُوَ الۡغَفُوۡرُ الۡوَدُوۡدُ ﴿ۙ۱۴﴾', 'اور وہ بخشنے والا ہے بہت محبت کرنے والا ہے۔', 'اور وہی ہے بخشنے والا محبت کرنے والا [۱۱]', 'And He is Oft-Forgiving, full of love (towards the pious who are real true believers of Islamic Monotheism),', 'And He is the Most-Forgiving, the Most-Loving,'),
(5924, 85, 15, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'ذُو الۡعَرۡشِ الۡمَجِیۡدُ ﴿ۙ۱۵﴾', 'عرش کا مالک بڑی شان والا۔', 'مالک عرش کا بڑی شان والا', 'Owner of the throne, the Glorious', 'the Master of the Throne, the Glorious.'),
(5925, 85, 16, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'فَعَّالٌ لِّمَا یُرِیۡدُ ﴿ؕ۱۶﴾', 'جو چاہتا ہے سو کر ڈالتا ہے۔', 'کر ڈالنے والا جو چاہے [۱۲]', 'He does what He intends (or wills).', 'He is ever doer of what He intends.'),
(5926, 85, 17, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'ہَلۡ  اَتٰىکَ حَدِیۡثُ الۡجُنُوۡدِ ﴿ۙ۱۷﴾', 'بھلا تمکو لشکروں کا حال معلوم ہوا ہے۔', 'کیا پہنچی تجھ کو بات اُن لشکروں کی', 'Has the story reached you of the hosts,', 'Has there come to you the story of the forces,'),
(5927, 85, 18, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'فِرۡعَوۡنَ وَ ثَمُوۡدَ ﴿ؕ۱۸﴾', 'یعنی فرعون اور ثمود کا۔', 'فرعون اور ثمود کے [۱۳]', 'Of Firaun (Pharaoh) and Thamood?', 'of Fir‘aun (Pharaoh) and Thamūd?'),
(5928, 85, 19, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'بَلِ الَّذِیۡنَ کَفَرُوۡا فِیۡ تَکۡذِیۡبٍ ﴿ۙ۱۹﴾', 'اصل بات یہ ہے کہ کافر مستقل جھٹلانے میں لگے ہیں۔', 'کوئی نہیں بلکہ منکر جھٹلاتےہیں [۱۴]', 'Nay! The disbelievers (persisted) in denying (Prophet Muhammad (Peace be upon him) and his Message of Islamic Monotheism).', 'But those who disbelieve are (engaged) in denying (the truth).'),
(5929, 85, 20, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'وَّ اللّٰہُ  مِنۡ  وَّرَآئِہِمۡ  مُّحِیۡطٌ ﴿ۚ۲۰﴾', 'جبکہ اللہ بھی انکو ہر طرف سے گھیرے ہوئے ہے۔', 'اور اللہ نے اُنکو ہر طرف سے گھیر رکھا ہے [۱۵]', 'And Allah encompasses them from behind! (i.e. all their deeds are within His Knowledge, and He will requite them for their deeds).', 'Allah has encompassed them from all sides.'),
(5930, 85, 21, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'بَلۡ ہُوَ  قُرۡاٰنٌ  مَّجِیۡدٌ ﴿ۙ۲۱﴾', 'یہ کوئی معمولی کلام نہیں بلکہ یہ قرآن عظیم الشان ہے۔', 'کوئی نہیں یہ قرآن ہے بڑی شان کا [۱۶]', 'Nay! This is a Glorious Quran,', 'The reality is that it is the glorious Qur’ān,'),
(5931, 85, 22, 1, 10, 30, 'عَمَّ ', 'البُرُوج', 'فِیۡ  لَوۡحٍ مَّحۡفُوۡظٍ ﴿٪۲۲﴾', 'لوح محفوظ میں لکھا ہوا۔', 'لکھا ہو الوح محفوظ میں [۱۷]', '(Inscribed) in Al-Lauh Al-Mahfooz (The Preserved Tablet)!', '(recorded) in the Preserved Tablet (LauH MaHfūZ).'),
(5932, 86, 1, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'وَ السَّمَآءِ  وَ الطَّارِقِ ۙ﴿۱﴾', 'آسمان کی اور رات کے وقت آنے والے کی قسم۔', 'قسم ہے آسمان کی اور اندھیری میں آنے والے کی', 'By the heaven, and At-Tariq (the night-comer, i.e. the bright star);', 'I swear by the sky and by the Night-Comer,-'),
(5933, 86, 2, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'وَ مَاۤ  اَدۡرٰىکَ مَا الطَّارِقُ ۙ﴿۲﴾', 'اور تمکو کیا معلوم کے رات کے وقت آنے والا کیا ہے۔', 'اور تو نے کیا سمجھاکیا ہے اندھیرے میں آنے والا', 'And what will make you to know what At-Tariq (night-comer) is?', '-and what may let you know what the Night-Comer is?'),
(5934, 86, 3, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'النَّجۡمُ الثَّاقِبُ ۙ﴿۳﴾', 'وہ تارا ہے چمکنے والا۔', 'وہ تارا چمکتا ہوا', '(It is) the star of piercing brightness;', 'The star of piercing brightness!- -'),
(5935, 86, 4, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'اِنۡ کُلُّ نَفۡسٍ لَّمَّا عَلَیۡہَا حَافِظٌ ؕ﴿۴﴾', 'کہ کوئی شخص ایسا نہیں جس پر کوئی نگہبان نہ ہو۔', 'کوئی جی نہیں جس پر نہیں ایک نگہبان', 'There is no human being but has a protector over him (or her) (i.e. angels incharge of each human being guarding him, writing his good and bad deeds, etc.)', '-there is no human being, but there is a watcher over him.'),
(5936, 86, 5, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'فَلۡیَنۡظُرِ الۡاِنۡسَانُ مِمَّ خُلِقَ ؕ﴿۵﴾', 'تو انسان کو دیکھنا چاہیے کہ وہ کاہے سے پیدا ہوا ہے۔', 'اب دیکھ لے آدمی کہ کاہے سے بنا ہے [۱]', 'So let man see from what he is created!', 'So, let man consider of which stuff he is created.'),
(5937, 86, 6, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'خُلِقَ مِنۡ مَّآءٍ  دَافِقٍ ۙ﴿۶﴾', 'وہ اچھلتے ہوئے پانی سے پیدا ہوا ہے۔', 'بنا ہے ایک اچھلتے ہوئے پانی سے [۲]', 'He is created from a water gushing forth', 'He is created of spouting water'),
(5938, 86, 7, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'یَّخۡرُجُ مِنۡۢ بَیۡنِ الصُّلۡبِ وَ التَّرَآئِبِ ؕ﴿۷﴾', 'جو پیٹھ اور سینے کے بیچ میں سے نکلتا ہے۔', 'جو نکلتا ہے پیٹھ کے بیچ سے اور چھاتی کے بیچ سے [۳]', 'Proceeding from between the back-bone and the ribs,', 'that comes out from between the loins and the chest-bones.'),
(5939, 86, 8, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'اِنَّہٗ  عَلٰی رَجۡعِہٖ لَقَادِرٌ ؕ﴿۸﴾', 'بیشک وہ یعنی خالق اسکو دوبارہ پیدا کرنے پر قادر ہے۔', 'بیشک وہ اُسکو پھیر لا سکتا ہے [۴]', 'Verily, (Allah) is Able to bring him back (to life)!', 'Surely He is Powerful to bring him back'),
(5940, 86, 9, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'یَوۡمَ تُبۡلَی السَّرَآئِرُ ۙ﴿۹﴾', 'جس دن دلوں کے بھید جانچے جائیں گے۔', 'جس دن جانچے جائیں بھید [۵]', 'The Day when all the secrets (deeds, prayers, fasting, etc.) will be examined (as to their truth).', 'on a day when all the secrets will be searched out,'),
(5941, 86, 10, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'فَمَا لَہٗ  مِنۡ قُوَّۃٍ  وَّ لَا  نَاصِرٍ ﴿ؕ۱۰﴾', 'تو انسان کی کچھ پیش نہ چل سکے گی اور نہ کوئی اس کا مددگار ہو گا۔', 'تو کچھ نہ ہو گا اُسکو زور اور نہ کوئی مدد کرنے والا [۶]', 'Then will (man) have no power, nor any helper.', 'and he will have neither strength (to defend), nor a supporter.'),
(5942, 86, 11, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'وَ السَّمَآءِ  ذَاتِ الرَّجۡعِ ﴿ۙ۱۱﴾', 'آسمان کی قسم جو مینہ برساتا ہے۔', 'قسم ہے آسمان چکر مارنے والے کی [۷]', 'By the sky (having rain clouds) which gives rain, again and again.', 'I swear by the sky that rains,'),
(5943, 86, 12, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'وَ الۡاَرۡضِ ذَاتِ الصَّدۡعِ ﴿ۙ۱۲﴾', 'اور زمین کی قسم جو پھٹ جاتی ہے۔', 'اور زمین پھوٹ نکلنے والی کی [۸]', 'And the earth which splits (with the growth of trees and plants),', 'and the earth that cracks open (for plants),'),
(5944, 86, 13, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'اِنَّہٗ  لَقَوۡلٌ  فَصۡلٌ ﴿ۙ۱۳﴾', 'کہ یہ فیصلہ کن کلام ہے۔', 'بیشک یہ بات ہے دوٹوک', 'Verily! This (the Quran) is the Word that separates (the truth from falsehood, and commands strict legal laws for mankind to cut the roots of evil).', 'this is a decisive word,'),
(5945, 86, 14, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'وَّ مَا ہُوَ  بِالۡہَزۡلِ ﴿ؕ۱۴﴾', 'اور یہ کوئی مذاق نہیں۔', 'اور نہیں یہ بات ہنسی کی [۹]', 'And it is not a thing for amusement.', 'and it is not a joke.'),
(5946, 86, 15, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'اِنَّہُمۡ یَکِیۡدُوۡنَ  کَیۡدًا ﴿ۙ۱۵﴾', 'یہ لوگ اپنی تدبیروں میں لگ رہے ہیں۔', 'البتہ وہ لگے ہوئے ہیں ایک داؤ کرنے میں', 'Verily, they are but plotting a plot (against you O Muhammad (Peace be upon him)).', 'They are devising plans,'),
(5947, 86, 16, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'وَّ اَکِیۡدُ  کَیۡدًا ﴿ۚۖ۱۶﴾', 'اور میں اپنی تدبیر کر رہا ہوں۔', 'اور میں لگا ہوا ہوں ایک داؤ کرنے میں', 'And I (too) am planning a plan.', 'and I Am devising plans.'),
(5948, 86, 17, 1, 11, 30, 'عَمَّ ', 'الطَّارق', 'فَمَہِّلِ الۡکٰفِرِیۡنَ  اَمۡہِلۡہُمۡ رُوَیۡدًا ﴿٪۱۷﴾', 'تو اے نبی ﷺ تم کافروں کو مہلت دو بس چند دن کی مہلت اور دیدو۔', 'سو ڈھیل دے منکروں کو  ڈھیل دے اُنکو تھوڑے دنوں [۱۰]', 'So give a respite to the disbelievers. Deal you gently with them for a while.', 'So leave the disbelievers alone at the moment; give them respite for a while.'),
(5949, 87, 1, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'سَبِّحِ اسۡمَ رَبِّکَ الۡاَعۡلَی ۙ﴿۱﴾', 'اے پیغمبر ﷺ اپنے پروردگار عالی شان کے نام کی تسبیح کرو۔', 'پاکی بیان کر اپنے رب کے نام کی جو سب سے اوپر [۱]', 'Glorify the Name of your Lord, the Most High,', 'Pronounce the purity of the name of your most exalted Lord,'),
(5950, 87, 2, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'الَّذِیۡ خَلَقَ فَسَوّٰی ۪ۙ﴿۲﴾', 'جس نے انسان کو بنایا پھر اسکے اعضاء کو درست کیا۔', 'جس نے بنایا پھر ٹھیک کیا [۲]', 'Who has created (everything), and then proportioned it;', 'who created (everything), then made (it) well,'),
(5951, 87, 3, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'وَ الَّذِیۡ  قَدَّرَ فَہَدٰی ۪ۙ﴿۳﴾', 'اور جس نے اس کا اندازہ ٹھہرایا پھر اسکو رستہ بتایا۔', 'اور جس نے ٹھہرا دیا پھر راہ بتلائی [۳]', 'And Who has measured (preordainments for each and everything even to be blessed or wretched); then guided (i.e. showed mankind the right as well as wrong paths, and guided the animals to pasture);', 'and who determined a measure (for everything), then guided (it),'),
(5952, 87, 4, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'وَ الَّذِیۡۤ  اَخۡرَجَ  الۡمَرۡعٰی ۪ۙ﴿۴﴾', 'اور جس نے چارہ اگایا۔', 'اور جس نے نکالا چارا', 'And Who brings out the pasturage,', 'and who brought forth pasturage,'),
(5953, 87, 5, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'فَجَعَلَہٗ  غُثَآءً  اَحۡوٰی ؕ﴿۵﴾', 'پھر اسکو سیاہ رنگ کا کوڑا کر دیا۔', 'پھر کر ڈالا اُسکو کُوڑا سیاہ [۴]', 'And then makes it dark stubble.', 'then turned it into a blackening stubble.'),
(5954, 87, 6, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'سَنُقۡرِئُکَ فَلَا تَنۡسٰۤی ۙ﴿۶﴾', 'اے نبی ﷺ ہم تمہیں پڑھا دیں گے پھر تم فراموش نہ کرو گے۔', 'البتہ ہم پڑھائیں گے تجھ کو پھر تو نہ بھولے گا', 'We shall make you to recite (the Quran), so you (O Muhammad (Peace be upon him)) shall not forget (it),', 'We will make you recite, then you will not forget'),
(5955, 87, 7, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'اِلَّا  مَا شَآءَ اللّٰہُ ؕ اِنَّہٗ  یَعۡلَمُ الۡجَہۡرَ  وَ مَا یَخۡفٰی ؕ﴿۷﴾', 'مگر جو اللہ چاہے۔ وہ کھلی بات کو بھی جانتا ہے اور چھپی کو بھی۔', 'مگر جو چاہے اللہ [۵] وہ جانتا ہے پکارنے کو اور جو چھپا ہوا ہے [۶]', 'Except what Allah, may will, He knows what is apparent and what is hidden.', 'except that which Allah wills. Indeed He knows what is manifest and what is hidden.'),
(5956, 87, 8, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'وَ نُیَسِّرُکَ لِلۡیُسۡرٰی ۚ﴿ۖ۸﴾', 'اور ہم تمکو آسان طریقے کی توفیق دیں گے۔', 'اور سہج سہج پہنچائیں گے ہم تجھ کو آسانی تک [۷]', 'And We shall make easy for you (O Muhammad (Peace be upon him)) the easy way (i.e. the doing of righteous deeds).', 'And We will facilitate for you (to reach) the easiest way.'),
(5957, 87, 9, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'فَذَکِّرۡ  اِنۡ  نَّفَعَتِ الذِّکۡرٰی ؕ﴿۹﴾', 'سو جہاں تک نصیحت کے نافع ہونے کی امید ہو نصیحت کرتے رہو۔', 'سو تو سمجھا دے اگر فائدہ کرے سمجھانا [۸]', 'Therefore remind (men) in case the reminder profits (them).', 'So, extend advice (to people) if advice is useful.'),
(5958, 87, 10, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'سَیَذَّکَّرُ مَنۡ یَّخۡشٰی ﴿ۙ۱۰﴾', 'جو خوف رکھتا ہے وہ تو نصیحت حاصل کرے گا۔', 'سمجھ جائے گا جس کو ڈر ہو گا [۹]', 'The reminder will be received by him who fears (Allah),', 'The one who fears (Allah) will observe the advice,'),
(5959, 87, 11, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'وَ  یَتَجَنَّبُہَا الۡاَشۡقَی  ﴿ۙ۱۱﴾', 'اور بے خوف بدبخت اس سے کترائے گا۔', 'اور یکسو رہے گا اُس سے بڑا بدقسمت', 'But it will be avoided by the wretched,', 'and it will be avoided by the most wretched one'),
(5960, 87, 12, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'الَّذِیۡ  یَصۡلَی النَّارَ الۡکُبۡرٰی ﴿ۚ۱۲﴾', 'جو بڑی تیز آگ میں داخل ہو گا۔', 'وہ جو داخل ہو گا بڑی آگ میں [۱۰]', 'Who will enter the great Fire and made to taste its burning,', 'who will enter the Biggest Fire,'),
(5961, 87, 13, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'ثُمَّ  لَا یَمُوۡتُ فِیۡہَا وَ لَا یَحۡیٰی ﴿ؕ۱۳﴾', 'پھر وہاں نہ مرے گا اور نہ جئے گا۔', 'پھر نہ مرے گا اُس میں اور نہ جئے گا [۱۱]', 'Wherein he will neither die (to be in rest) nor live (a good living).', 'then he will neither die therein, nor live (a desirable life).'),
(5962, 87, 14, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'قَدۡ  اَفۡلَحَ  مَنۡ  تَزَکّٰی ﴿ۙ۱۴﴾', 'بیشک وہ مراد کو پہنچ گیا جو پاک ہوا۔', 'بیشک بھلا ہوا اُس کا جو سنورا [۱۲]', 'Indeed whosoever purifies himself (by avoiding polytheism and accepting Islamic Monotheism) shall achieve success,', 'Success is surely achieved by him who purifies himself,'),
(5963, 87, 15, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'وَ ذَکَرَ اسۡمَ رَبِّہٖ فَصَلّٰی ﴿ؕ۱۵﴾', 'اور اپنے پروردگار کا نام لیتا رہا اور نماز پڑھتا رہا۔', 'اورلیا اُس نے نام اپنے رب کا پھر نماز پڑھی [۱۳]', 'And remembers (glorifies) the Name of his Lord (worships none but Allah), and prays (five compulsory prayers and Nawafil additional prayers).', 'and pronounces the name of his Lord, then offers prayer.'),
(5964, 87, 16, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'بَلۡ  تُؤۡثِرُوۡنَ الۡحَیٰوۃَ  الدُّنۡیَا ﴿۫ۖ۱۶﴾', 'بات یہ ہے کہ تم لوگ تو دنیا کی زندگی کو ترجیح دیتے ہو۔', 'کوئی نہیں تم بڑھاتے ہو دنیا کے جینے کو', 'Nay, you prefer the life of this world;', 'But you prefer the worldly life,'),
(5965, 87, 17, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'وَ الۡاٰخِرَۃُ  خَیۡرٌ  وَّ اَبۡقٰی ﴿ؕ۱۷﴾', 'حالانکہ آخرت بہت بہتر اور ہمیشہ باقی رہنے والی ہے۔', 'اور پچھلا گھر بہتر ہے اور باقی رہنے والا [۱۴]', 'Although the Hereafter is better and more lasting.', 'while the Hereafter is much better and much more durable.'),
(5966, 87, 18, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'اِنَّ ہٰذَا  لَفِی الصُّحُفِ الۡاُوۡلٰی ﴿ۙ۱۸﴾', 'یہی بات پہلے صحیفوں میں بھی درج ہے۔', 'یہ لکھا ہوا ہے پہلے ورقوں میں', 'Verily! This is in the former Scriptures,', 'Indeed this is (written) in the earlier divine scripts,'),
(5967, 87, 19, 1, 12, 30, 'عَمَّ ', 'الاَعلیٰ', 'صُحُفِ اِبۡرٰہِیۡمَ وَ مُوۡسٰی ﴿٪۱۹﴾', 'یعنی ابراہیم اور موسٰی کے صحیفوں میں۔', 'صحیفوں میں ابراہیم کے اور موسٰی کے [۱۵]', 'The Scriptures of Ibrahim (Abraham) and Moosa (Moses).', 'the scripts of Ibrāhīm and Mūsā.'),
(5968, 88, 1, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'ہَلۡ  اَتٰىکَ حَدِیۡثُ  الۡغَاشِیَۃِ ؕ﴿۱﴾', 'بھلا تمکو ڈھانپ لینے والی یعنی قیامت کا حال معلوم ہوا ہے؟', 'کچھ پہنچی تجھ کو بات اُس چھپا لینے والی کی [۱]', 'Has there come to you the narration of the overwhelming (i.e. the Day of Resurrection);', 'Has there come to you the description of the Overwhelming Event?'),
(5969, 88, 2, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'وُجُوۡہٌ  یَّوۡمَئِذٍ خَاشِعَۃٌ ۙ﴿۲﴾', 'اس روز بہت سے چہرے یعنی لوگ ذلیل ہوں گے۔', 'کتنے منہ اُس دن ذلیل ہونے والے ہیں', 'Some faces, that Day, will be humiliated (in the Hell-fire, i.e. the faces of all disbelievers, Jews and Christians, etc.).', 'Many faces that day will be humbled,'),
(5970, 88, 3, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'عَامِلَۃٌ  نَّاصِبَۃٌ ۙ﴿۳﴾', 'سخت محنت کرنے والے تھکے ماندے۔', 'محنت کرنے والے تھکے ہوئے [۲]', 'Labouring (hard in the worldly life by worshipping others besides Allah), weary (in the Hereafter with humility and disgrace) .', 'laboring, exhausted.'),
(5971, 88, 4, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'تَصۡلٰی نَارًا حَامِیَۃً ۙ﴿۴﴾', 'دہکتی آگ میں داخل ہوں گے۔', 'گریں گے دہکتی ہوئی آگ میں', 'They will enter in the hot blazing Fire,', 'They will enter into the scorching fire.'),
(5972, 88, 5, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'تُسۡقٰی مِنۡ عَیۡنٍ  اٰنِیَۃٍ ؕ﴿۵﴾', 'انکو ایک کھولتے ہوئے چشمے کا پانی پلایا جائے گا۔', 'پانی ملے گا ایک چشمے کھولتے ہوئے کا [۳]', 'They will be given to drink from a boiling spring,', 'They will be made to drink water from a boiling spring.'),
(5973, 88, 6, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'لَیۡسَ لَہُمۡ طَعَامٌ   اِلَّا مِنۡ ضَرِیۡعٍ ۙ﴿۶﴾', 'ایک سخت خاردار جھاڑی کے سوا انکے لئے کوئی کھانا نہیں ہو گا۔', 'نہیں اُنکے پاس کھانا مگر جھاڑ کانٹوں والا [۴]', 'No food will there be for them but a poisonous thorny plant,', 'There will be no food for them except from a thorny plant'),
(5974, 88, 7, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'لَّا یُسۡمِنُ وَ لَا یُغۡنِیۡ مِنۡ جُوۡعٍ ؕ﴿۷﴾', 'جو نہ مفید غذا بنے اور نہ بھوک میں کچھ کام آئے۔', 'نہ موٹا کرے اور نہ کام آئے بھوک میں [۵]', 'Which will neither nourish nor avail against hunger.', 'that will neither nourish, nor satisfy hunger.'),
(5975, 88, 8, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'وُجُوۡہٌ  یَّوۡمَئِذٍ نَّاعِمَۃٌ ۙ﴿۸﴾', 'بہت سے چہرے یعنی لوگ اس روز شادمان بھی ہوں گے۔', 'کتنے منہ اُس دن تروتازہ ہیں', '(Other) faces, that Day, will be joyful,', 'Many faces that day will be full of glamour,'),
(5976, 88, 9, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'لِّسَعۡیِہَا  رَاضِیَۃٌ ۙ﴿۹﴾', 'اپنی محنت کے بدلے پر خوش۔', 'اپنی کمائی سے راضی [۶]', 'Glad with their endeavour (for their good deeds which they did in this world, along with the true Faith of Islamic Monotheism).', 'well pleased with their endeavor,'),
(5977, 88, 10, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'فِیۡ  جَنَّۃٍ  عَالِیَۃٍ ﴿ۙ۱۰﴾', 'بہشت بریں میں۔', 'اونچے باغ میں', 'In a lofty Paradise.', 'in a lofty garden,'),
(5978, 88, 11, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'لَّا تَسۡمَعُ  فِیۡہَا  لَاغِیَۃً ﴿ؕ۱۱﴾', 'وہاں کسی طرح کی لغو بات نہیں سنیں گے۔', 'نہیں سنتے اُس میں بکواس [۷]', 'Where they shall neither hear harmful speech nor falsehood,', 'in which they will not hear any absurd talk.'),
(5979, 88, 12, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'فِیۡہَا عَیۡنٌ جَارِیَۃٌ ﴿ۘ۱۲﴾', 'اس میں چشمے بہ رہے ہوں گے۔', 'اُس میں ایک چشمہ ہے بہتا [۸]', 'Therein will be a running spring,', 'In it there is a flowing spring.'),
(5980, 88, 13, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'فِیۡہَا سُرُرٌ  مَّرۡفُوۡعَۃٌ ﴿ۙ۱۳﴾', 'وہاں تخت ہوں گے اونچے اونچے۔', 'اُس میں تخت ہیں اونچے بچھے ہوئے', 'Therein will be thrones raised high,', 'In it there are elevated couches'),
(5981, 88, 14, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'وَّ  اَکۡوَابٌ مَّوۡضُوۡعَۃٌ ﴿ۙ۱۴﴾', 'اور کٹورے قرینے سے رکھے ہوئے۔', 'اور آبخورے سامنے چنے ہوئے [۹]', 'And cups set at hand.', 'and goblets, well placed,'),
(5982, 88, 15, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'وَّ نَمَارِقُ مَصۡفُوۡفَۃٌ ﴿ۙ۱۵﴾', 'اور گاؤ تکیے قطار کی قطار لگے ہوئے۔', 'اور غالیچے برابر بچھے ہوئے [۱۰]', 'And cushions set in rows,', 'and cushions, arrayed'),
(5983, 88, 16, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'وَّ زَرَابِیُّ  مَبۡثُوۡثَۃٌ ﴿ؕ۱۶﴾', 'اور نفیس مسندیں جگہ جگہ بچھی ہوئی۔', 'اور مخمل کے نہالچے جگہ جگہ پھیلے ہوئے [۱۱]', 'And rich carpets (all) spread out.', 'and carpets, spread around.'),
(5984, 88, 17, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'اَفَلَا یَنۡظُرُوۡنَ  اِلَی الۡاِبِلِ کَیۡفَ خُلِقَتۡ ﴿ٝ۱۷﴾', 'تو کیا یہ لوگ اونٹوں کی طرف نہیں دیکھتے کہ کیسے عجیب پیدا کئے گئے ہیں۔', 'بھلا کیا نظر نہیں کرتے اونٹوں پر کہ کیسے بنائے ہیں [۱۲]', 'Do they not look at the camels, how they are created?', 'So, do they not look at the camels how they are created,'),
(5985, 88, 18, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'وَ  اِلَی السَّمَآءِ کَیۡفَ رُفِعَتۡ ﴿ٝ۱۸﴾', 'اور آسمان کی طرف کہ کیسا بلند کیا گیا ہے۔', 'اور آسمان پر کہ کیسا اُس کو بلند کیا ہے [۱۳]', 'And at the heaven, how it is raised?', 'and at the sky, how it is raised high,'),
(5986, 88, 19, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'وَ  اِلَی الۡجِبَالِ کَیۡفَ نُصِبَتۡ ﴿ٝ۱۹﴾', 'اور پہاڑوں کی طرف کہ کس طرح کھڑے کئے گئے ہیں۔', 'اور پہاڑوں پر کہ کیسے کھڑے کر دیے ہیں [۱۴]', 'And at the mountains, how they are rooted and fixed firm?', 'and at the mountains, how they are installed,'),
(5987, 88, 20, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'وَ  اِلَی الۡاَرۡضِ کَیۡفَ سُطِحَتۡ ﴿ٝ۲۰﴾', 'اور زمین کی طرف کہ کس طرح بچھائی گئ۔', 'اور زمین پر کہ کیسی صاف بچھائی ہے [۱۵]', 'And at the earth, how it is spread out?', 'and at the earth, how it is spread out?'),
(5988, 88, 21, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'فَذَکِّرۡ ۟ؕ  اِنَّمَاۤ  اَنۡتَ مُذَکِّرٌ ﴿ؕ۲۱﴾', 'پس اے نبی ﷺ تم تو نصیحت کرتے رہو کہ تم نصیحت کرنے والے ہی ہو۔', 'سو تو سمجھائے جا تیرا کام تو یہی سمجھانا ہے', 'So remind them (O Muhammad (Peace be upon him)), you are only a one who reminds.', 'So, (O Prophet,) keep on preaching; you are only a preacher.'),
(5989, 88, 22, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'لَسۡتَ عَلَیۡہِمۡ  بِمُصَۜیۡطِرٍ ﴿ۙ۲۲﴾', 'تم ان پر داروغہ نہیں ہو۔', 'تو نہیں اُن پر داروغہ [۱۶]', 'You are not a dictator over them.', 'You are not a taskmaster set up over them,'),
(5990, 88, 23, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'اِلَّا  مَنۡ  تَوَلّٰی  وَ  کَفَرَ ﴿ۙ۲۳﴾', 'ہاں جس نے منہ پھیرا اور نہ مانا۔', 'مگر جس نے منہ موڑا اور منکر ہو گیا', 'Save the one who turns away and disbelieves', 'but whoever turns away and disbelieves,'),
(5991, 88, 24, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'فَیُعَذِّبُہُ  اللّٰہُ  الۡعَذَابَ الۡاَکۡبَرَ ﴿ؕ۲۴﴾', 'تو اللہ اسکو بہت بڑا عذاب دے گا۔', 'تو عذاب کرے گا اُس پر اللہ وہ بڑا عذاب', 'Then Allah will punish him with the greatest punishment.', 'Allah will punish him with the greatest torment.'),
(5992, 88, 25, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'اِنَّ  اِلَیۡنَاۤ  اِیَابَہُمۡ ﴿ۙ۲۵﴾', 'بیشک انکو ہمارے ہی پاس لوٹ کر آنا ہے۔', 'بیشک ہمارے پاس ہے اُنکو پھر آنا', 'Verily, to Us will be their return;', 'Surely towards Us they have to return,'),
(5993, 88, 26, 1, 13, 30, 'عَمَّ ', 'الغَاشِیَۃ', 'ثُمَّ  اِنَّ  عَلَیۡنَا حِسَابَہُمۡ ﴿٪۲۶﴾', 'پھر ہمارے ہی ذمے ان سے حساب لینا ہے۔', 'پھر بیشک ہمارا ذمہ ہے اُن سے حساب لینا [۱۷]', 'Then verily, for Us will be their reckoning.', 'then it is Our job to call them to account.'),
(5994, 89, 1, 1, 14, 30, 'عَمَّ ', 'الفجر', 'وَ  الۡفَجۡرِ ۙ﴿۱﴾', 'فجر کی قسم۔', 'قسم ہے فجر کی', 'By the dawn;', 'I swear by the dawn,'),
(5995, 89, 2, 1, 14, 30, 'عَمَّ ', 'الفجر', 'وَ  لَیَالٍ عَشۡرٍ ۙ﴿۲﴾', 'اور دس راتوں کی۔', 'اور دس راتوں کی', 'By the ten nights (i.e. the first ten days of the month of Dhul-Heejjah) ,', 'and by Ten Nights,'),
(5996, 89, 3, 1, 14, 30, 'عَمَّ ', 'الفجر', 'وَّ الشَّفۡعِ وَ الۡوَتۡرِ ۙ﴿۳﴾', 'اور جفت اور طاق کی۔', 'اور جفت اورطاق کی', 'And by the even and the odd (of all the creations of Allah) .', 'and by the even and the odd,'),
(5997, 89, 4, 1, 14, 30, 'عَمَّ ', 'الفجر', 'وَ الَّیۡلِ  اِذَا یَسۡرِ ۚ﴿۴﴾', 'اور رات کی جب رخصت ہونے لگے۔', 'اور اس رات کی جب رات کو چلے [۱]', 'And by the night when it departs.', 'and by the night when it moves away,'),
(5998, 89, 5, 1, 14, 30, 'عَمَّ ', 'الفجر', 'ہَلۡ فِیۡ ذٰلِکَ قَسَمٌ  لِّذِیۡ حِجۡرٍ ؕ﴿۵﴾', 'اور بیشک یہ چیزیں عقلمندوں کے نزدیک قسم کھانے کے لائق ہیں اس بات پر کہ کافروں کو ضرور عذاب ہو گا۔', 'ہے اُن چیزوں کی قسم پوری عقلمندوں کے واسطے [۲]', 'There is indeed in them (the above oaths) sufficient proofs for men of understanding (and that, they should avoid all kinds of sins and disbeliefs, etc.)!', '-Is there (not) in such an oath (enough assurance) for a man of sense?-'),
(5999, 89, 6, 1, 14, 30, 'عَمَّ ', 'الفجر', 'اَلَمۡ  تَرَ  کَیۡفَ فَعَلَ  رَبُّکَ بِعَادٍ ۪ۙ﴿۶﴾', 'کیا تم نے نہیں دیکھا کہ تمہارے پروردگار نے قوم عاد کے ساتھ کیا کیا۔', 'تو نے نہ دیکھا کیسا کیا تیرے رب نے عاد کے ساتھ', 'Did you (O Muhammad (Peace be upon him)) not see (thought) how your Lord dealt with Ad (people)?', 'Have you not seen how your Lord dealt with (the people) of ‘Ād'),
(6000, 89, 7, 1, 14, 30, 'عَمَّ ', 'الفجر', 'اِرَمَ ذَاتِ الۡعِمَادِ ۪ۙ﴿۷﴾', 'جو ارم کہلاتے تھے درازقد مانند ستونوں کے۔', 'وہ جو ارم میں تھے [۳] بڑے ستونوں والے [۴]', 'Who were very tall like lofty pillars,', 'of Iram , the men of tall pillars,'),
(6001, 89, 8, 1, 14, 30, 'عَمَّ ', 'الفجر', 'الَّتِیۡ  لَمۡ یُخۡلَقۡ مِثۡلُہَا فِی الۡبِلَادِ ۪ۙ﴿۸﴾', 'کہ تمام ملک میں ایسے پیدا نہیں ہوئے تھے۔', 'کہ بنی نہیں ویسی سارے شہروں میں [۵]', 'The like of which were not created in the land?', 'the like of whom were never created in the lands,'),
(6002, 89, 9, 1, 14, 30, 'عَمَّ ', 'الفجر', 'وَ ثَمُوۡدَ  الَّذِیۡنَ جَابُوا الصَّخۡرَ بِالۡوَادِ ۪ۙ﴿۹﴾', 'اور ثمود کے ساتھ کیا کیا جو وادی قرٰی میں چٹانیں تراشتے تھے۔', 'اور ثمود کے ساتھ جنہوں نے تراشا پتھروں کو وادی میں [۶]', 'And (with) Thamood (people), who cut (hewed) out rocks in the valley (to make dwellings)?', 'and (how He dealt) with (the people of) Thamūd who had carved out the rocks in the Valley (of Qurā),'),
(6003, 89, 10, 1, 14, 30, 'عَمَّ ', 'الفجر', 'وَ  فِرۡعَوۡنَ ذِی الۡاَوۡتَادِ ﴿۪ۙ۱۰﴾', 'اور فرعون کے ساتھ کیا کیا جو خیمے اور میخیں رکھتا تھا۔', 'اور فرعون کے ساتھ و ہ میخوں والا [۷]', 'And (with) Firaun (Pharaoh), who had pegs (who used to torture men by binding them to pegs)?', 'and with Fir‘aun (Pharaoh), the man of the stakes,'),
(6004, 89, 11, 1, 14, 30, 'عَمَّ ', 'الفجر', 'الَّذِیۡنَ طَغَوۡا فِی الۡبِلَادِ ﴿۪ۙ۱۱﴾', 'یہ لوگ ملکوں میں سرکش ہو رہے تھے۔', 'یہ سب تھے جنہوں نے سر اٹھایا ملکوں میں', 'Who did transgress beyond bounds in the lands (in the disobedience of Allah).', '- those who had rebelled in the cities,'),
(6005, 89, 12, 1, 14, 30, 'عَمَّ ', 'الفجر', 'فَاَکۡثَرُوۡا فِیۡہَا الۡفَسَادَ ﴿۪ۙ۱۲﴾', 'پس ان میں بہت سی خرابیاں کرتے تھے۔', 'پھر بہت ڈالی اُن میں خرابی', 'And made therein much mischief.', 'and spread a lot of mischief therein.'),
(6006, 89, 13, 1, 14, 30, 'عَمَّ ', 'الفجر', 'فَصَبَّ عَلَیۡہِمۡ رَبُّکَ سَوۡطَ عَذَابٍ ﴿ۚۙ۱۳﴾', 'تو تمہارے پروردگار نے ان پر عذاب کا کوڑا برسا دیا۔', 'پھر پھینکا اُن پر تیرے رب نے کوڑا عذاب کا [۸]', 'So your Lord poured on them different kinds of severe torment.', 'So, your Lord let loose on them the whip of torment.'),
(6007, 89, 14, 1, 14, 30, 'عَمَّ ', 'الفجر', 'اِنَّ رَبَّکَ لَبِالۡمِرۡصَادِ ﴿ؕ۱۴﴾', 'بیشک تمہارا پروردگار تاک میں ہے۔', 'بیشک تیرا رب لگا ہے گھات میں [۹]', 'Verily, your Lord is Ever Watchful (over them).', 'Surely your Lord is ever on the watch.'),
(6008, 89, 15, 1, 14, 30, 'عَمَّ ', 'الفجر', 'فَاَمَّا الۡاِنۡسَانُ  اِذَا مَا ابۡتَلٰىہُ  رَبُّہٗ فَاَکۡرَمَہٗ  وَ نَعَّمَہٗ ۬ۙ  فَیَقُوۡلُ رَبِّیۡۤ اَکۡرَمَنِ ﴿ؕ۱۵﴾', 'مگر انسان عجیب مخلوق ہے کہ جب اس کا پروردگار اسکو آزماتا ہے کہ اسے عزت دیتا اور نعمت بخشتا ہے۔ تو کہتا ہے کہ میرے پروردگار نے مجھے عزت بخشی۔', 'سو آدمی جو ہے جب جانچے اُسکو رب اُس کا پھر اُس کو عزت دے اور اُسکو نعمت دے تو کہے میرے رب نے مجھ کو عزت دی [۱۰]', 'As for man, when his Lord tries him by giving him honour and gifts, then he says (puffed up): \"My Lord has honoured me.\"', 'As for man, when his Lord tests him, and thus gives him honour and bounties, he says, “My Lord has honoured me.”'),
(6009, 89, 16, 1, 14, 30, 'عَمَّ ', 'الفجر', 'وَ اَمَّاۤ  اِذَا مَا ابۡتَلٰىہُ  فَقَدَرَ عَلَیۡہِ رِزۡقَہٗ ۬ۙ  فَیَقُوۡلُ رَبِّیۡۤ  اَہَانَنِ ﴿ۚ۱۶﴾', 'اور جب دوسری طرح آزماتا ہے کہ اس پر روزی تنگ کر دیتا ہے تو کہتا ہے کہ میرے پروردگار نے مجھے ذلیل کیا۔', 'اور وہ جس وقت اُسکو جانچے پھر کھینچ کرے اُس پر روزی کی تو کہے میرے رب نے مجھے ذلیل کیا [۱۱]', 'But when He tries him, by straitening his means of life, he says: \"My Lord has humiliated me!\"', 'But when he tests him, and thus straitens his provision for him, he says, “My Lord has disgraced me.”'),
(6010, 89, 17, 1, 14, 30, 'عَمَّ ', 'الفجر', 'کَلَّا بَلۡ  لَّا تُکۡرِمُوۡنَ  الۡیَتِیۡمَ ﴿ۙ۱۷﴾', 'یوں نہیں۔ بلکہ تم لوگ یتیم کی خاطر نہیں کرتے۔', 'کوئی نہیں پر تم عزت سے نہیں رکھتے یتیم کو [۱۲]', 'Nay! But you treat not the orphans with kindness and generosity (i.e. you neither treat them well, nor give them their exact right of inheritance)!', 'No! But you do not honour the orphan,'),
(6011, 89, 18, 1, 14, 30, 'عَمَّ ', 'الفجر', 'وَ لَا تَحٰٓضُّوۡنَ عَلٰی طَعَامِ الۡمِسۡکِیۡنِ ﴿ۙ۱۸﴾', 'اور نہ مسکین کو کھانا کھلانے کی ترغیب دیتے ہو۔', 'اور تاکید نہیں کرتے آپس میں محتاج کے کھلانے کی [۱۳]', 'And urge not on the feeding of AlMiskeen (the poor)!', 'and do not encourage one another to feed the needy.'),
(6012, 89, 19, 1, 14, 30, 'عَمَّ ', 'الفجر', 'وَ تَاۡکُلُوۡنَ  التُّرَاثَ اَکۡلًا لَّمًّا ﴿ۙ۱۹﴾', 'اور میراث کے مال کو سمیٹ کر کھا جاتے ہو۔', 'اور کھا جاتے ہو مردے کا مال سمیٹ کر سارا [۱۴]', 'And you devour inheritance all with greed,', 'And you devour the inheritance with a sweeping gulp,'),
(6013, 89, 20, 1, 14, 30, 'عَمَّ ', 'الفجر', 'وَّ  تُحِبُّوۡنَ الۡمَالَ حُبًّا جَمًّا ﴿ؕ۲۰﴾', 'اور مال کو بہت ہی عزیز رکھتے ہو۔', 'اور پیار کرتے ہو مال کو جی بھر کر [۱۵]', 'And you love wealth with much love!', 'and love wealth, an excessive love.'),
(6014, 89, 21, 1, 14, 30, 'عَمَّ ', 'الفجر', 'کَلَّاۤ  اِذَا دُکَّتِ الۡاَرۡضُ دَکًّا دَکًّا ﴿ۙ۲۱﴾', 'یوں نہیں جب زمین کوٹ کوٹ کر برابر کر دی جائے گی۔', 'کوئی نہیں جب پست کر دی جائے زمین کوٹ کوٹ کر [۱۶]', 'Nay! When the earth is ground to powder,', 'No! When the earth will be crushed thoroughly to be turned into bits,'),
(6015, 89, 22, 1, 14, 30, 'عَمَّ ', 'الفجر', 'وَّ  جَآءَ  رَبُّکَ وَ الۡمَلَکُ صَفًّا صَفًّا ﴿ۚ۲۲﴾', 'اور تمہارا پروردگار جلوہ فرما ہو گا اور فرشتے قطار در قطار آ جائیں گے۔', 'اور آئے تیرا رب [۱۷] اور فرشتے آئیں قطار قطار [۱۸]', 'And your Lord comes with the angels in rows,', 'and your Lord will come, and the angels as well, lined up in rows,'),
(6016, 89, 23, 1, 14, 30, 'عَمَّ ', 'الفجر', 'وَ جِایۡٓءَ یَوۡمَئِذٍۭ  بِجَہَنَّمَ ۬ۙ یَوۡمَئِذٍ یَّتَذَکَّرُ  الۡاِنۡسَانُ  وَ اَنّٰی  لَہُ  الذِّکۡرٰی ﴿ؕ۲۳﴾', 'اور دوزخ اس دن  سامنے لائی جائے گی تو انسان اس دن سوچے گا مگر اب سوچنے سے اسے فائدہ کہاں مل سکے گا؟', 'اور لائی جائے اُس دن دوزخ [۱۹] اُس دن سوچے گا آدمی اور کہاں ملے اُسکو سوچنا [۲۰]', 'And Hell will be brought near that Day. On that Day will man remember, but how will that remembrance (then) avail him?', 'and Jahannam (Hell), on that day, will be brought forward, it will be the day when man will realize the truth, but from where will he take advantage of such realization?'),
(6017, 89, 24, 1, 14, 30, 'عَمَّ ', 'الفجر', 'یَقُوۡلُ یٰلَیۡتَنِیۡ  قَدَّمۡتُ لِحَیَاتِیۡ ﴿ۚ۲۴﴾', 'کہے گا کاش میں نے اپنی اس زندگی کیلئے کچھ آگے بھیجا ہوتا۔', 'کہے کیا اچھا ہوتا جو میں کچھ آگے بھیجدیتا اپنی زندگی میں [۲۱]', 'He will say: \"Alas! Would that I had sent forth (good deeds) for (this) my life!\"', 'He will say, “O Would that I had sent ahead (some good deeds) for (this) my life!”'),
(6018, 89, 25, 1, 14, 30, 'عَمَّ ', 'الفجر', 'فَیَوۡمَئِذٍ لَّا  یُعَذِّبُ عَذَابَہٗۤ  اَحَدٌ ﴿ۙ۲۵﴾', 'تو اس دن نہ کوئی اللہ کے عذاب کی طرح کا عذاب دے گا۔', 'پھر اُس دن عذاب نہ دے اُس کا سا کوئی', 'So on that Day, none will punish as He will punish.', 'So no one can punish like He will punish, that day,'),
(6019, 89, 26, 1, 14, 30, 'عَمَّ ', 'الفجر', 'وَّ لَا یُوۡثِقُ وَ ثَاقَہٗۤ  اَحَدٌ ﴿ؕ۲۶﴾', 'اور نہ کوئی اسکے جکڑنے کی طرح جکڑے گا۔', 'اور نہ باندھ کر رکھے اُس کا سا باندھنا کوئی [۲۲]', 'And none will bind as He will bind.', 'nor can anyone shackle like He will shackle.'),
(6020, 89, 27, 1, 14, 30, 'عَمَّ ', 'الفجر', 'یٰۤاَیَّتُہَا النَّفۡسُ الۡمُطۡمَئِنَّۃُ ﴿٭ۖ۲۷﴾', 'اے اطمینان والی جان!۔', 'اے وہ جی جس نے چین پکڑ لیا', '(It will be said to the pious): \"O (you) the one in (complete) rest and satisfaction!', '(As for an obedient man, it will be said to him,) “O content soul,'),
(6021, 89, 28, 1, 14, 30, 'عَمَّ ', 'الفجر', 'ارۡجِعِیۡۤ  اِلٰی  رَبِّکِ رَاضِیَۃً  مَّرۡضِیَّۃً ﴿ۚ۲۸﴾', 'اپنے پروردگار کی طرف لوٹ چل۔ تو اس سے راضی وہ تجھ سے راضی۔', 'پھر چل اپنے رب کی طرف تو اس سے راضی وہ تجھ سے راضی', '\"Come back to your Lord, Well-pleased (yourself) and well-pleasing unto Him!', 'come back to your Lord, well-pleased, well-pleasing.'),
(6022, 89, 29, 1, 14, 30, 'عَمَّ ', 'الفجر', 'فَادۡخُلِیۡ  فِیۡ عِبٰدِیۡ ﴿ۙ۲۹﴾', 'سو تو میرے خاص بندوں میں شامل ہو جا۔', 'پھر شامل ہو میرے بندوں میں', '\"Enter you, then, among My honoured slaves,', 'So, enter among My (special) servants,'),
(6023, 89, 30, 1, 14, 30, 'عَمَّ ', 'الفجر', 'وَ ادۡخُلِیۡ جَنَّتِیۡ ﴿٪۳۰﴾', 'اور میری بہشت میں داخل ہو جا۔', 'اور داخل ہو میری بہشت میں [۲۳]', '\"And enter you My Paradise!\"', 'and enter My Paradise.”'),
(6024, 90, 1, 1, 15, 30, 'عَمَّ ', 'البلد', 'لَاۤ  اُقۡسِمُ  بِہٰذَا الۡبَلَدِ ۙ﴿۱﴾', 'میں اس شہر یعنی مکے کی قسم کھاتا ہوں۔', 'قسم کھاتا ہوں میں اس شہر کی [۱]', 'I swear by this city (Makkah);', 'I swear by this city,'),
(6025, 90, 2, 1, 15, 30, 'عَمَّ ', 'البلد', 'وَ اَنۡتَ حِلٌّۢ بِہٰذَا الۡبَلَدِ ۙ﴿۲﴾', 'اور تم اے نبی ﷺ اسی شہر میں تو رہتے ہو۔', 'اور تجھ پر قید نہیں رہے گی اس شہر میں [۲]', 'And you are free (from sin, to punish the enemies of Islam on the Day of the conquest) in this city (Makkah) ,', '-and (O Prophet,) you are going to be allowed (to fight) in this city-'),
(6026, 90, 3, 1, 15, 30, 'عَمَّ ', 'البلد', 'وَ  وَالِدٍ وَّ  مَا وَلَدَ ۙ﴿۳﴾', 'اور سب کے باپ یعنی آدم اور اسکی اولاد کی قسم۔', 'اور قسم ہے جنتے کی اور جو اس نے جنا [۳]', 'And by the begetter (i.e. Adam ) and that which he begot (i.e. his progeny);', 'and by the father and all those he begot,'),
(6027, 90, 4, 1, 15, 30, 'عَمَّ ', 'البلد', 'لَقَدۡ خَلَقۡنَا الۡاِنۡسَانَ فِیۡ  کَبَدٍ ؕ﴿۴﴾', 'کہ ہم نے انسان کو محنت و مشقت میں رہنے والا بنایا ہے۔', 'تحقیق ہم نے بنایا آدمی کو محنت میں [۴]', 'Verily, We have created man in toil.', 'indeed We have created man (to live) in hard struggle.'),
(6028, 90, 5, 1, 15, 30, 'عَمَّ ', 'البلد', 'اَیَحۡسَبُ اَنۡ  لَّنۡ یَّقۡدِرَ عَلَیۡہِ  اَحَدٌ  ۘ﴿۵﴾', 'کیا یہ خیال کرتا ہے کہ اس پر کوئی قابو نہ پائے گا۔', 'کیا خیال رکھتا ہے وہ کہ اُس پر بس نہ چلے گا کسی کا [۵]', 'Thinks he that none can overcome him?', 'Does he think that no one has power over him?'),
(6029, 90, 6, 1, 15, 30, 'عَمَّ ', 'البلد', 'یَقُوۡلُ  اَہۡلَکۡتُ مَالًا  لُّبَدًا ؕ﴿۶﴾', 'کہتا ہے کہ میں نے بہت سا مال برباد کر دیا۔', 'کہتا ہے میں نے خرچ کر ڈالا مال ڈھیروں [۶]', 'He says (boastfully): \"I have wasted wealth in abundance!\"', 'He says, “I have spent a lot of wealth.”'),
(6030, 90, 7, 1, 15, 30, 'عَمَّ ', 'البلد', 'اَیَحۡسَبُ اَنۡ  لَّمۡ  یَرَہٗۤ   اَحَدٌ ؕ﴿۷﴾', 'کیا اسے یہ گمان ہے کہ اسکو کسی نے دیکھا نہیں۔', 'کیا خیال رکھتا ہے کہ دیکھا نہیں اسکو کسی نے [۷]', 'Thinks he that none sees him?', 'Does he think that no one has seen him?'),
(6031, 90, 8, 1, 15, 30, 'عَمَّ ', 'البلد', 'اَلَمۡ  نَجۡعَلۡ لَّہٗ عَیۡنَیۡنِ ۙ﴿۸﴾', 'بھلا ہم نے اسکو دو آنکھیں نہیں دیں؟', 'بھلا ہم نے نہیں دیں اُسکو دو آنکھیں [۸]', 'Have We not made for him a pair of eyes?', 'Did We not make for him two eyes,'),
(6032, 90, 9, 1, 15, 30, 'عَمَّ ', 'البلد', 'وَ  لِسَانًا وَّ  شَفَتَیۡنِ ۙ﴿۹﴾', 'اور زبان اور دو ہونٹ نہیں دیئے۔', 'اور زبان اور دو ہونٹ [۹]', 'And a tongue and a pair of lips?', 'and one tongue and two lips,'),
(6033, 90, 10, 1, 15, 30, 'عَمَّ ', 'البلد', 'وَ ہَدَیۡنٰہُ  النَّجۡدَیۡنِ ﴿ۚ۱۰﴾', 'یہ چیزیں بھی دیں اور اسکو خیر و شر کے دونوں رستے بھی دکھا دیئے۔', 'اور دکھلا دیں اُسکو دو گھاٹیاں [۱۰]', 'And shown him the two ways (good and evil)?', 'and showed him the two ways?'),
(6034, 90, 11, 1, 15, 30, 'عَمَّ ', 'البلد', 'فَلَا  اقۡتَحَمَ الۡعَقَبَۃَ ﴿۫ۖ۱۱﴾', 'مگر یہ گھاٹی پر سے ہو کر نہ گذرا۔', 'سو نہ دھمک سکا گھاٹی پر [۱۱]', 'But he has made no effort to pass on the path that is steep.', 'Yet he did not make his way through the steep course,- -'),
(6035, 90, 12, 1, 15, 30, 'عَمَّ ', 'البلد', 'وَ مَاۤ  اَدۡرٰىکَ مَا الۡعَقَبَۃُ ﴿ؕ۱۲﴾', 'اور تم کیا سمجھے کہ گھاٹی کیا؟', 'اور توکیا سمجھا کیا ہے وہ گھاٹی', 'And what will make you know the path that is steep?', '- And what may let you know what the steep course is?'),
(6036, 90, 13, 1, 15, 30, 'عَمَّ ', 'البلد', 'فَکُّ رَقَبَۃٍ ﴿ۙ۱۳﴾', 'کسی کی گردن کا چھڑانا۔', 'چھڑانا گردن کا [۱۲]', '(It is) Freeing a neck (slave, etc.)', '(It is) freeing of the neck of a slave,'),
(6037, 90, 14, 1, 15, 30, 'عَمَّ ', 'البلد', 'اَوۡ  اِطۡعٰمٌ فِیۡ یَوۡمٍ ذِیۡ مَسۡغَبَۃٍ ﴿ۙ۱۴﴾', 'یا بھوک کے دن میں کھانا کھلانا۔', 'یا کھلانا بھوک کے دن میں [۱۳]', 'Or giving food in a day of hunger (famine),', 'or giving food in a day of hunger'),
(6038, 90, 15, 1, 15, 30, 'عَمَّ ', 'البلد', 'یَّتِیۡمًا ذَا مَقۡرَبَۃٍ ﴿ۙ۱۵﴾', 'کسی رشتہ دار یتیم کو۔', 'یتیم کو جو قرابت والا ہے [۱۴]', 'To an orphan near of kin.', 'to an orphan near of kin,'),
(6039, 90, 16, 1, 15, 30, 'عَمَّ ', 'البلد', 'اَوۡ مِسۡکِیۡنًا ذَا مَتۡرَبَۃٍ ﴿ؕ۱۶﴾', 'یا مٹی میں پڑے کسی نادار کو۔', 'یا محتاج کو جو خاک میں رل رہا ہے [۱۵]', 'Or to a Miskeen (poor) afflicted with misery.', 'or to a needy person lying in dust- -'),
(6040, 90, 17, 1, 15, 30, 'عَمَّ ', 'البلد', 'ثُمَّ کَانَ مِنَ الَّذِیۡنَ  اٰمَنُوۡا وَ تَوَاصَوۡا بِالصَّبۡرِ  وَ تَوَاصَوۡا بِالۡمَرۡحَمَۃِ ﴿ؕ۱۷﴾', 'پھر ان لوگوں میں بھی شامل ہوا جو ایمان لائے اور جو صبر کی نصیحت کی اور ایکدوسرے کو مہربانی کی تلقین کرتے رہے۔', 'پھر ہووے ایمان والوں میں [۱۶] جو تاکید کرتے ہیں آپس میں تحمل کی اور تاکید کرتے ہیں رحم کھانے کی [۱۷]', 'Then he became one of those who believed, and recommended one another to perseverance and patience, and (also) recommended one another to pity and compassion.', '- then he did not join those who believe and advise each other to be patient and advise each other to be merciful.'),
(6041, 90, 18, 1, 15, 30, 'عَمَّ ', 'البلد', 'اُولٰٓئِکَ اَصۡحٰبُ الۡمَیۡمَنَۃِ ﴿ؕ۱۸﴾', 'یہی لوگ اچھے نصیب والے ہیں۔', 'وہ لوگ ہیں بڑے نصیب والے [۱۸]', 'They are those on the Right Hand (the dwellers of Paradise),', 'Those are the People of the Right Hand. (i.e. their books of deeds will be given in their right hands)'),
(6042, 90, 19, 1, 15, 30, 'عَمَّ ', 'البلد', 'وَ الَّذِیۡنَ کَفَرُوۡا بِاٰیٰتِنَا ہُمۡ اَصۡحٰبُ الۡمَشۡـَٔمَۃِ ﴿ؕ۱۹﴾', 'اور جنہوں نے ہماری آیتوں کو نہ مانا وہی برے نصیب والے ہیں۔', 'اور جو منکر ہوئے ہماری آیتوں سے وہ ہیں کمبختی والے [۱۹]', 'But those who disbelieved in Our Ayat (proofs, evidences, verses, lessons, signs, revelations, etc.), they are those on the Left Hand (the dwellers of Hell).', 'As for those who reject Our verses, they are the People of the Left Hand. (i.e. their books of deeds will be given in their left hands.)'),
(6043, 90, 20, 1, 15, 30, 'عَمَّ ', 'البلد', 'عَلَیۡہِمۡ  نَارٌ  مُّؤۡصَدَۃٌ ﴿٪۲۰﴾', 'یہ لوگ آگ میں بند کر دیئے جائیں گے۔', 'اُنہی کو آگ میں موند دیا ہے [۲۰]', 'The Fire will be shut over them (i.e. they will be enveloped by the Fire without any opening or window or outlet.', 'Upon them will be the Fire, enveloping them with closed exits.'),
(6044, 91, 1, 1, 16, 30, 'عَمَّ ', ' الشَّمس', 'وَ الشَّمۡسِ وَ ضُحٰہَا ۪ۙ﴿۱﴾', 'سورج کی قسم اور اسکی دھوپ کی۔', 'قسم  سورج اور اُسکے دھوپ  چڑھنے کی', 'And by the sun and its brightness;', 'I swear by the sun and his broad light,'),
(6045, 91, 2, 1, 16, 30, 'عَمَّ ', ' الشَّمس', 'وَ الۡقَمَرِ  اِذَا  تَلٰىہَا ۪ۙ﴿۲﴾', 'اور چاند کی جب وہ اسکے پیچھے چلے۔', 'اور چاند کی جب آئے سورج کے پیچھے [۱]', 'And by the moon as it follows it (the sun);', 'and by the moon when she follows him,'),
(6046, 91, 3, 1, 16, 30, 'عَمَّ ', ' الشَّمس', 'وَ النَّہَارِ  اِذَا  جَلّٰىہَا ۪ۙ﴿۳﴾', 'اور دن کی جب وہ اسے روشن کر دے۔', 'اور دن کی جب اُسکو روشن کر لے [۲]', 'And by the day as it shows up (the suns) brightness;', 'and by the day when it shows his brightness,'),
(6047, 91, 4, 1, 16, 30, 'عَمَّ ', ' الشَّمس', 'وَ الَّیۡلِ  اِذَا یَغۡشٰىہَا ۪ۙ﴿۴﴾', 'اور رات کی جب وہ اسے چھپا لے۔', 'اور رات کی جب اسکو ڈھانک لیوے [۳]', 'And by the night as it conceals it (the sun);', 'and by the night when it envelops him,'),
(6048, 91, 5, 1, 16, 30, 'عَمَّ ', ' الشَّمس', 'وَ السَّمَآءِ وَ مَا بَنٰہَا ۪ۙ﴿۵﴾', 'اور آسمان کی اور اس ذات کی جس نے اسے بنایا۔', 'اور آسمان کی اور جیسا کہ اُسکو بنایا [۴]', 'And by the heaven and Him Who built it;', 'and by the sky, and the One who built it,');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(6049, 91, 6, 1, 16, 30, 'عَمَّ ', ' الشَّمس', 'وَ الۡاَرۡضِ وَ مَا طَحٰہَا ۪ۙ﴿۶﴾', 'اور زمین کی اور اس ذات کی جس نے اسے پھیلایا۔', 'اور زمین کی اور جیسا کہ اُسکو پھیلایا [۵]', 'And by the earth and Him Who spread it,', 'and by the earth, and the One who spread it,'),
(6050, 91, 7, 1, 16, 30, 'عَمَّ ', ' الشَّمس', 'وَ نَفۡسٍ وَّ مَا سَوّٰىہَا ۪ۙ﴿۷﴾', 'اور نفس انسانی کی اور اسکی جس نے اسے درست کر کے بنایا۔', 'اور جی کی اور جیسا کہ اُسکو ٹھیک بنایا [۶]', 'And by Nafs (Adam or a person or a soul, etc.), and Him Who perfected him in proportion;', 'and by the soul, and the One who made it well,'),
(6051, 91, 8, 1, 16, 30, 'عَمَّ ', ' الشَّمس', 'فَاَلۡہَمَہَا فُجُوۡرَہَا وَ تَقۡوٰىہَا ۪ۙ﴿۸﴾', 'پھر اسکو بدکاری سے بچنے اور پرہیزگار بننے کی سمجھ دی۔', 'پھر سمجھ دی اُسکو ڈھٹائی کی اور بچ کر چلنے کی [۷]', 'Then He showed him what is wrong for him and what is right for him;', 'then inspired it with its (instincts of) evil and piety,'),
(6052, 91, 9, 1, 16, 30, 'عَمَّ ', ' الشَّمس', 'قَدۡ  اَفۡلَحَ  مَنۡ  زَکّٰىہَا ۪ۙ﴿۹﴾', 'کہ جس نے اپنے نفس کو پاک رکھا وہ مراد کو پہنچا۔', 'تحقیق مراد کو پہنچا جس نے اُسکو سنوار لیا [۸]', 'Indeed he succeeds who purifies his ownself (i.e. obeys and performs all that Allah ordered, by following the true Faith of Islamic Monotheism and by doing righteous good deeds).', 'success is really attained by him who purifies it,'),
(6053, 91, 10, 1, 16, 30, 'عَمَّ ', ' الشَّمس', 'وَ  قَدۡ خَابَ مَنۡ  دَسّٰىہَا ﴿ؕ۱۰﴾', 'اور جس نے اسے خاک میں ملایا وہ نامراد رہا۔', 'اور نامراد ہوا جس نے اُسکو خاک میں ملا چھوڑا [۹]', 'And indeed he fails who corrupts his ownself (i.e. disobeys what Allah has ordered by rejecting the true Faith of Islamic Monotheism or by following polytheism, etc. or by doing every kind of evil wicked deeds).', 'and failure is really suffered by him who pollutes it.'),
(6054, 91, 11, 1, 16, 30, 'عَمَّ ', ' الشَّمس', 'کَذَّبَتۡ ثَمُوۡدُ  بِطَغۡوٰىہَاۤ  ﴿۪ۙ۱۱﴾', 'قوم ثمود نے اپنی سرکشی کے سبب پیغمبر کو جھٹلایا۔', 'جھٹلایا ثمود نے اپنی شرارت سے [۰ا]', 'Thamood (people) denied (their Prophet) through their transgression (by rejecting the true Faith of Islamic Monotheism, and by following polytheism, and by committing every kind of sin).', '(The People of) Thamūd denied the truth because of their transgression,'),
(6055, 91, 12, 1, 16, 30, 'عَمَّ ', ' الشَّمس', 'اِذِ  انۡۢبَعَثَ  اَشۡقٰہَا ﴿۪ۙ۱۲﴾', 'جب ان میں سے ایک نہایت بدبخت اٹھا۔', 'جب اٹھ کھڑا ہوا اُن میں کا بڑ ابدبخت [۱۱]', 'When the most wicked man among them went forth (to kill the she-camel).', 'when rose up the one who was most wretched of them.'),
(6056, 91, 13, 1, 16, 30, 'عَمَّ ', ' الشَّمس', 'فَقَالَ لَہُمۡ  رَسُوۡلُ اللّٰہِ نَاقَۃَ اللّٰہِ وَ سُقۡیٰہَا ﴿ؕ۱۳﴾', 'تو اللہ کے پیغمبر صالح نے ان سے کہا کہ اللہ کی اونٹنی اور اسکے پانی پینے کی باری سے خبردار رہو۔', 'پھر کہاں اُنکو اللہ کے رسول نے خبردار ہو اللہ کی اونٹنی سے اور اُسکی پانی پینے کی باری سے [۱۲]', 'But the Messenger of Allah (Salih (Saleh) ) said to them: \"Be cautious! Fear the evil end. That is the she-camel of Allah! (Do not harm it) and bar it not from having its drink!\"', 'So, the Messenger of Allah said to them, “Be careful of Allah’s she-camel and her right to drink.”'),
(6057, 91, 14, 1, 16, 30, 'عَمَّ ', ' الشَّمس', 'فَکَذَّبُوۡہُ  فَعَقَرُوۡہَا ۪۬ۙ فَدَمۡدَمَ عَلَیۡہِمۡ  رَبُّہُمۡ بِذَنۡۢبِہِمۡ  فَسَوّٰىہَا ﴿۪ۙ۱۴﴾', 'مگر انہوں نے پیغمبر کو جھٹلایا پھر اونٹنی کو مار ڈالا۔ تو انکے رب نے انکے گناہ کے سبب انکو نیست و نابود کر دیا پھر سب کو برابر کر دیا۔', 'پھر انہوں نے اُسکو جھٹلایا پھر پاؤں کاٹ ڈالے اُسکے پھر الٹ مارا اُن پر اُنکے رب نے بسبب اُنکے گناہوں کے پھر برابر کر دیا سب کو [۱۳]', 'Then they denied him and they killed it. So their Lord destroyed them because of their sin, and made them equal in destruction (i.e. all grades of people, rich and poor, strong and weak, etc.)!', 'But they rejected him and killed her, so their Lord sent eradicating torment upon them because of their sin, and made it equal for all.'),
(6058, 91, 15, 1, 16, 30, 'عَمَّ ', ' الشَّمس', 'وَ لَا یَخَافُ عُقۡبٰہَا ﴿٪۱۵﴾', 'اور اللہ کو انکے بدلہ لینے کا کچھ بھی ڈر نہیں۔', 'اور وہ نہیں ڈرتا پیچھا کرنے سے [۱۴]', 'And He (Allah) feared not the consequences thereof.', 'And He has no fear of its consequence.'),
(6059, 92, 1, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'وَ الَّیۡلِ  اِذَا یَغۡشٰی ۙ﴿۱﴾', 'رات کی قسم جب وہ چھا جائے۔', 'قسم رات کی جب چھا جائے', 'By the night as it envelops;', 'I swear by the night when it covers (the sun),'),
(6060, 92, 2, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'وَ النَّہَارِ  اِذَا  تَجَلّٰی ۙ﴿۲﴾', 'اور دن کی قسم جب وہ روشن ہو جائے۔', 'اور دن کی جب روشن ہو', 'And by the day as it appears in brightness;', 'and by the day when it unveils itself,'),
(6061, 92, 3, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'وَ مَا خَلَقَ الذَّکَرَ  وَ الۡاُنۡثٰۤی ۙ﴿۳﴾', 'اور اس ذات کی قسم جس نے نر اور مادہ پیدا کئے۔', 'اور اُسکی جو اُس نے پیدا کئے نر اور مادہ', 'And by Him Who created male and female;', 'and by the One who created the male and the female,'),
(6062, 92, 4, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'اِنَّ  سَعۡیَکُمۡ  لَشَتّٰی ؕ﴿۴﴾', 'کہ تم لوگوں کی کوشش طرح طرح کی ہے۔', 'تمہاری کمائی طرح طرح پر ہے [۱]', 'Certainly, your efforts and deeds are diverse (different in aims and purposes);', 'your efforts are diverse:'),
(6063, 92, 5, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'فَاَمَّا مَنۡ اَعۡطٰی وَ اتَّقٰی ۙ﴿۵﴾', 'سو جس نے اللہ کے رستے میں مال دیا اور پرہیزگاری کی۔', 'سو جس نے دیا اور ڈرتا رہا', 'As for him who gives (in charity) and keeps his duty to Allah and fears Him,', 'As for the one who gives (in charity) and fears Allah,'),
(6064, 92, 6, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'وَ صَدَّقَ بِالۡحُسۡنٰی ۙ﴿۶﴾', 'اور بہترین بات یعنی کلمہ توحید کو سچ جانا۔', 'اور سچ جانا بھلی بات کو', 'And believes in Al-Husna.', 'and believes in the best (religion),'),
(6065, 92, 7, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'فَسَنُیَسِّرُہٗ  لِلۡیُسۡرٰی ؕ﴿۷﴾', 'تو اسکو ہم آسان طریقے کی توفیق دیں گے۔', 'تو اُسکو ہم سہج سہج پہنچا دیں گے آسانی میں [۲]', 'We will make smooth for him the path of ease (goodness).', 'We will facilitate for him the way to extreme ease (i.e. the comforts of Paradise).'),
(6066, 92, 8, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'وَ اَمَّا مَنۡۢ  بَخِلَ وَ اسۡتَغۡنٰی ۙ﴿۸﴾', 'اور جس نے بخل کیا اور بے پروا بنا رہا۔', 'اور جس نے نہ دیا اور بے پروا رہا', 'But he who is greedy miser and thinks himself self-sufficient .', 'But the one who is miser and deems himself self-sufficient,'),
(6067, 92, 9, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'وَ  کَذَّبَ بِالۡحُسۡنٰی ۙ﴿۹﴾', 'اور بہترین بات کو جھوٹ سمجھا۔', 'اور جھوٹ جانا بھلی بات کو', 'And gives the lie to Al-Husna (see Verse No: 6 footnote);', 'and rejects the best (religion),'),
(6068, 92, 10, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'فَسَنُیَسِّرُہٗ  لِلۡعُسۡرٰی ﴿ؕ۱۰﴾', 'تو ہم اسے رفتہ رفتہ سختی میں پہنچا دینگے۔', 'سو اُسکو ہم سہج سہج پہنچا دیں گے سختی میں [۳]', 'We will make smooth for him the path for evil;', 'We will facilitate for him the way to extreme distress.'),
(6069, 92, 11, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'وَ مَا یُغۡنِیۡ عَنۡہُ  مَا لُہٗۤ  اِذَا تَرَدّٰی ﴿ؕ۱۱﴾', 'اور جب وہ دوزخ کے گڑھے میں گرے گا تو اس کا مال اسکے کچھ بھی کام نہ آئے گا۔', 'اور کام نہ آئے گا اُسکے مال اُس کا جب گڑھے میں گرے گا [۴]', 'And what will his wealth benefit him when he goes down (in destruction).', 'And his wealth will not help him when he will fall down (into Hell).'),
(6070, 92, 12, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'اِنَّ  عَلَیۡنَا لَلۡہُدٰی ﴿۫ۖ۱۲﴾', 'یقینًا راہ دکھا دینا ہمارا ذمہ ہے۔', 'ہمارا ذمہ ہے راہ سجھا دینا', 'Truly! Ours it is (to give) guidance,', 'Of course, it is undertaken by Us to guide,'),
(6071, 92, 13, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'وَ اِنَّ  لَنَا لَلۡاٰخِرَۃَ  وَ الۡاُوۡلٰی ﴿۱۳﴾', 'اور بیشک آخرت اور دنیا ہماری ہی ملکیت ہیں۔', 'اور ہمارے ہاتھ میں ہے آخرت اور دنیا [۵]', 'And truly, unto Us (belong) the last (Hereafter) and the first (this world).', 'and in Our control is the Hereafter and the worldly life.'),
(6072, 92, 14, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'فَاَنۡذَرۡتُکُمۡ  نَارًا تَلَظّٰی ﴿ۚ۱۴﴾', 'سو میں نے تمکو بھڑکتی آگ سے خبردار کر دیا ہے۔', 'سو میں نے سنا دی تم کو خبر ایک بھڑکتی ہوئی آگ کی [۶]', 'Therefore I have warned you of a Fire blazing fiercely (Hell);', 'So I have warned you of a blazing fire.'),
(6073, 92, 15, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'لَا یَصۡلٰىہَاۤ  اِلَّا الۡاَشۡقَی ﴿ۙ۱۵﴾', 'اس میں وہی داخل ہو گا جو بڑا بدبخت ہے۔', 'اُس میں وہی گرے گا جو بڑا بدبخت ہے', 'None shall enter it save the most wretched,', 'None will enter it but the wretched one,'),
(6074, 92, 16, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'الَّذِیۡ کَذَّبَ وَ تَوَلّٰی ﴿ؕ۱۶﴾', 'جس نے جھٹلایا اور منہ پھیرا۔', 'جس نے جھٹلایا اور منہ پھیرا [۷]', 'Who denies and turns away.', 'who rejected (the truth) and turned away (from it).'),
(6075, 92, 17, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'وَ  سَیُجَنَّبُہَا  الۡاَتۡقَی ﴿ۙ۱۷﴾', 'اور جو بڑا پرہیزگار ہے وہ اس سے بچا لیا جائے گا۔', 'اور بچا دیں گے اُس سے بڑے ڈرنے والے کو [۸]', 'And Al-Muttaqoon (the pious and righteous - see V.2:2) will be far removed from it (Hell).', 'And saved from it will be the most God-fearing one,'),
(6076, 92, 18, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'الَّذِیۡ یُؤۡتِیۡ مَالَہٗ یَتَزَکّٰی ﴿ۚ۱۸﴾', 'وہ جو اپنا مال دیتا ہے تاکہ پاک ہو۔', 'جو دیتا ہے اپنا مال دل پاک کرنے کو [۹]', 'He who spends his wealth for increase in self-purification,', 'who gives his wealth (in charity) to become purified,'),
(6077, 92, 19, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'وَ مَا لِاَحَدٍ عِنۡدَہٗ  مِنۡ نِّعۡمَۃٍ  تُجۡزٰۤی ﴿ۙ۱۹﴾', 'اور اس لئے نہیں دیتا کہ اس پر کسی کا احسان ہے جس کا بدلہ اتارا جائے۔', 'اور نہیں کسی کا اُس پر احسان جس کا بدلا دے', 'And have in his mind no favour from anyone for which a reward is expected in return,', 'while no one has conferred any favour on him for which he would give a return,'),
(6078, 92, 20, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'اِلَّا ابۡتِغَآءَ  وَجۡہِ  رَبِّہِ الۡاَعۡلٰی ﴿ۚ۲۰﴾', 'بلکہ اپنے رب اعلیٰ کی رضامندی حاصل کرنے کے لئے دیتا ہے۔', 'مگر واسطے چاہنے مرضی اپنے رب کی جو سب سے برتر ہے', 'Except only the desire to seek the Countenance of his Lord, the Most High;', 'but (he gave his wealth in charity) only to seek the Countenance of his Lord, the Most High.'),
(6079, 92, 21, 1, 17, 30, 'عَمَّ ', 'الَّیل', 'وَ  لَسَوۡفَ یَرۡضٰی ﴿٪۲۱﴾', 'اور وہ عنقریب خوش ہو جائے گا۔', 'اور آگے وہ راضی ہو گا [۱۰]', 'He surely will be pleased (when he will enter Paradise).', 'And surely he will soon be happy.'),
(6080, 93, 1, 1, 18, 30, 'عَمَّ ', 'الضُّحٰی', 'وَ الضُّحٰی ۙ﴿۱﴾', 'آفتاب کی روشنی کی قسم۔', 'قسم دھوپ چڑھتے وقت کی', 'By the forenoon (after sun-rise);', 'I swear by the forenoon,'),
(6081, 93, 2, 1, 18, 30, 'عَمَّ ', 'الضُّحٰی', 'وَ الَّیۡلِ  اِذَا سَجٰی ۙ﴿۲﴾', 'اور رات کی تاریکی کی قسم جب وہ چھا جائے۔', 'اور رات کی جب چھا جائے', 'And by the night when it is still (or darkens);', 'and by the night when it becomes peaceful,'),
(6082, 93, 3, 1, 18, 30, 'عَمَّ ', 'الضُّحٰی', 'مَا وَدَّعَکَ رَبُّکَ وَ مَا قَلٰی ؕ﴿۳﴾', 'اے نبی ﷺ تمہارے پروردگار نے نہ تو تمکو چھوڑ دیا اور نہ تم سے ناراض ہی ہوا۔', 'نہ رخصت کر دیا تجھ کو تیرے رب نے اور نہ بیزار ہوا [۱]', 'Your Lord (O Muhammad (Peace be upon him)) has neither forsaken you nor hated you.', 'your Lord (O Prophet,) has neither forsaken you, nor has become displeased.'),
(6083, 93, 4, 1, 18, 30, 'عَمَّ ', 'الضُّحٰی', 'وَ  لَلۡاٰخِرَۃُ  خَیۡرٌ لَّکَ مِنَ الۡاُوۡلٰی ؕ﴿۴﴾', 'اور آخرت تمہارے لئے دنیا سے کہیں بہتر ہے۔', 'اور البتہ پچھلی بہتر ہے تجھ کو پہلی سے [۲]', 'And indeed the Hereafter is better for you than the present (life of this world).', 'Surely the Hereafter is much better for you than the present life.'),
(6084, 93, 5, 1, 18, 30, 'عَمَّ ', 'الضُّحٰی', 'وَ  لَسَوۡفَ یُعۡطِیۡکَ رَبُّکَ فَتَرۡضٰی ؕ﴿۵﴾', 'اور تمہارا پروردگار عنقریب تمہیں اتنا کچھ عطا فرمائے گا کہ تم خوش ہو جاؤ گے۔', 'اور آگے دے گا تجھ کو تیرا رب پھر تو راضی ہو گا [۳]', 'And verily, your Lord will give you (all i.e. good) so that you shall be well-pleased.', 'And of course, your Lord will give you so much that you will be pleased.'),
(6085, 93, 6, 1, 18, 30, 'عَمَّ ', 'الضُّحٰی', 'اَلَمۡ  یَجِدۡکَ یَتِیۡمًا فَاٰوٰی ۪﴿۶﴾', 'بھلا اس نے تمہیں یتیم پا کر جگہ نہیں دی بیشک دی۔', 'بھلا نہیں پایا تجھ کو یتیم پھر جگہ دی [۴]', 'Did He not find you (O Muhammad (Peace be upon him)) an orphan and gave you a refuge?', 'Did He not find you an orphan, and give you shelter?'),
(6086, 93, 7, 1, 18, 30, 'عَمَّ ', 'الضُّحٰی', 'وَ  وَجَدَکَ ضَآلًّا فَہَدٰی ۪﴿۷﴾', 'اور تمہیں رستے سے ناواقف دیکھا تو سیدھا رستہ دکھایا۔', 'اور پایا تجھ کو بھٹکتا پھر راہ سجھائی [۵]', 'And He found you unaware (of the Quran, its legal laws, and Prophethood, etc.) and guided you?', 'And He found you unaware of the way (the Sharī‘ah ), then He guided you.'),
(6087, 93, 8, 1, 18, 30, 'عَمَّ ', 'الضُّحٰی', 'وَ وَجَدَکَ عَآئِلًا فَاَغۡنٰی ؕ﴿۸﴾', 'اور اس نے تمہیں تنگ دست پایا تو غنی کر دیا۔', 'اور پایا تجھ کو مفلس پھر بے پروا کر دیا [۶]', 'And He found you poor, and made you rich (selfsufficient with selfcontentment, etc.)?', 'and He found you in need, then made you need-free.'),
(6088, 93, 9, 1, 18, 30, 'عَمَّ ', 'الضُّحٰی', 'فَاَمَّا  الۡیَتِیۡمَ  فَلَا تَقۡہَرۡ ؕ﴿۹﴾', 'تو تم بھی یتیم پر ستم نہ کرنا۔', 'سو جو یتیم ہو اُس کو مت دبا [۷]', 'Therefore, treat not the orphan with oppression,', 'Therefore, as for orphan, do not oppress him,'),
(6089, 93, 10, 1, 18, 30, 'عَمَّ ', 'الضُّحٰی', 'وَ اَمَّا السَّآئِلَ  فَلَا تَنۡہَرۡ ﴿ؕ۱۰﴾', 'اور مانگنے والے کو جھڑکی نہ دینا۔', 'اور جو مانگتا ہو اُسکو مت جھڑک [۸]', 'And repulse not the beggar;', 'and as for the beggar, do not scold him.'),
(6090, 93, 11, 1, 18, 30, 'عَمَّ ', 'الضُّحٰی', 'وَ اَمَّا بِنِعۡمَۃِ  رَبِّکَ فَحَدِّثۡ ﴿٪۱۱﴾', 'اور اپنے پروردگار کی نعمت یعنی وحی کا بیان کرتے رہنا۔', 'اور جو احسان ہے تیرے رب کا سو بیان کر [۹]', 'And proclaim the Grace of your Lord (i.e. the Prophethood and all other Graces).', 'And about the bounty of your Lord, do talk.'),
(6091, 94, 1, 1, 19, 30, 'عَمَّ ', 'الم نشرح', 'اَلَمۡ نَشۡرَحۡ  لَکَ صَدۡرَکَ ۙ﴿۱﴾', 'اے  نبی ﷺ کیا ہم نے  تمہاری خاطر تمہارا سینہ کھول نہیں دیا۔', 'کیا ہم نے نہیں کھول دیا تیرا سینہ [۱]', 'Have We not opened your breast for you (O Muhammad (Peace be upon him))?', 'Have We not caused your bosom to be wide open for you?'),
(6092, 94, 2, 1, 19, 30, 'عَمَّ ', 'الم نشرح', 'وَ وَضَعۡنَا عَنۡکَ وِزۡرَکَ ۙ﴿۲﴾', 'اور تم پر سے تمہارا وہ بوجھ بھی اتار دیا۔', 'اور اتار رکھا ہم نے تجھ پر سے بوجھ تیرا', 'And removed from you your burden,', 'And We removed from you your burden'),
(6093, 94, 3, 1, 19, 30, 'عَمَّ ', 'الم نشرح', 'الَّذِیۡۤ  اَنۡقَضَ ظَہۡرَکَ ۙ﴿۳﴾', 'جس نے تمہاری کمر جھکا دی تھی۔', 'جس نے جھکا دی تھی پیٹھ تیری [۲]', 'Which weighed down your back?', 'that had (almost) broken your back,'),
(6094, 94, 4, 1, 19, 30, 'عَمَّ ', 'الم نشرح', 'وَ رَفَعۡنَا لَکَ ذِکۡرَکَ ؕ﴿۴﴾', 'اور ہم نے تمہاری خاطر تمہارا ذکر بلند کیا۔', 'اور بلند کیا ہم نے مذکور تیرا [۳]', 'And raised high your fame?', 'and We raised high your name.'),
(6095, 94, 5, 1, 19, 30, 'عَمَّ ', 'الم نشرح', 'فَاِنَّ مَعَ الۡعُسۡرِ  یُسۡرًا ۙ﴿۵﴾', 'سو یقینًا مشکل کے ساتھ آسانی بھی ہے۔', 'سو البتہ مشکل کے ساتھ آسانی ہے', 'So verily, with the hardship, there is relief,', 'So, undoubtedly, along with the hardship there is ease.'),
(6096, 94, 6, 1, 19, 30, 'عَمَّ ', 'الم نشرح', 'اِنَّ مَعَ الۡعُسۡرِ  یُسۡرًا ؕ﴿۶﴾', 'بیشک مشکل کے ساتھ آسانی بھی ہے۔', 'البتہ مشکل کے ساتھ آسانی ہے [۴]', 'Verily, with the hardship, there is relief (i.e. there is one hardship with two reliefs, so one hardship cannot overcome two reliefs).', 'Undoubtedly, along with the hardship there is ease.'),
(6097, 94, 7, 1, 19, 30, 'عَمَّ ', 'الم نشرح', 'فَاِذَا  فَرَغۡتَ فَانۡصَبۡ ۙ﴿۷﴾', 'سو جب تم فارغ ہوا کرو تو عبادت میں محنت کیا کرو۔', 'پھر جب تو فارغ ہو تو محنت کر', 'So when you have finished (from your occupation), then stand up for Allahs worship (i.e. stand up for prayer).', 'So, when you are free (from collective services), toil hard (in worship),'),
(6098, 94, 8, 1, 19, 30, 'عَمَّ ', 'الم نشرح', 'وَ اِلٰی  رَبِّکَ فَارۡغَبۡ ٪﴿۸﴾', 'اور اپنے پروردگار کی طرف متوجہ ہو جایا کرو۔', 'اور اپنے رب کی طرف دل لگا [۵]', 'And to your Lord (Alone) turn (all your intentions and hopes and) your invocations.', 'and towards your Lord turn with eagerness.'),
(6099, 95, 1, 1, 20, 30, 'عَمَّ ', 'التّین', 'وَ التِّیۡنِ وَ الزَّیۡتُوۡنِ ۙ﴿۱﴾', 'انجیر کی قسم اور زیتون کی۔', 'قسم انجیر کی اور زیتون کی [۱]', 'By the fig, and the olive,', 'I swear by the Fig and the Olive,'),
(6100, 95, 2, 1, 20, 30, 'عَمَّ ', 'التّین', 'وَ طُوۡرِ سِیۡنِیۡنَ ۙ﴿۲﴾', 'اور طور سینین کی۔', 'اور طور سینین کی', 'By Mount Sinai,', 'and by Tūr, the mount of Sinai,'),
(6101, 95, 3, 1, 20, 30, 'عَمَّ ', 'التّین', 'وَ ہٰذَا  الۡبَلَدِ الۡاَمِیۡنِ ۙ﴿۳﴾', 'اور اس امن والے شہر کی۔', 'اور اُس شہر امن والے کی [۲]', 'And by this city of security (Makkah) ,', 'and by this peaceful city,'),
(6102, 95, 4, 1, 20, 30, 'عَمَّ ', 'التّین', 'لَقَدۡ خَلَقۡنَا الۡاِنۡسَانَ فِیۡۤ  اَحۡسَنِ تَقۡوِیۡمٍ ۫﴿۴﴾', 'کہ ہم نے انسان کو بہترین سانچے میں ڈھال کر پیدا کیا ہے۔', 'ہم نے بنایا آدمی خوب سے اندازے پر [۳]', 'Verily, We created man of the best stature (mould),', 'We have created man in the best composition,'),
(6103, 95, 5, 1, 20, 30, 'عَمَّ ', 'التّین', 'ثُمَّ  رَدَدۡنٰہُ  اَسۡفَلَ سٰفِلِیۡنَ ۙ﴿۵﴾', 'پھر ہم نے اسکی حالت کو بدل کر پست سے پست کر دیا۔', 'پھر پھینک دیا اُسکو نیچوں سے نیچے [۴]', 'Then We reduced him to the lowest of the low,', 'then We turned him into the lowest of the low,'),
(6104, 95, 6, 1, 20, 30, 'عَمَّ ', 'التّین', 'اِلَّا  الَّذِیۡنَ اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ فَلَہُمۡ  اَجۡرٌ غَیۡرُ  مَمۡنُوۡنٍ ؕ﴿۶﴾', 'مگر جو لوگ ایمان لائے اور نیک عمل کرتے رہے تو ان کے لئے بے انتہا اجر ہے۔', 'مگر جو یقین لائے اور عمل کئے اچھے سو اُنکے لئے ثواب ہے بے انتہا [۵]', 'Save those who believe (in Islamic Monotheism) and do righteous deeds, then they shall have a reward without end (Paradise).', 'except those who believed and did righteous deeds, because for them there is a reward never ending.'),
(6105, 95, 7, 1, 20, 30, 'عَمَّ ', 'التّین', 'فَمَا یُکَذِّبُکَ بَعۡدُ بِالدِّیۡنِ ؕ﴿۷﴾', 'تو اے انسان اسکے بعد بھی تو جزا کے دن کو کیوں جھٹلاتا ہے۔', 'پھر تو اُسکے پیچھے کیوں جھٹلائے بدلا ملنے کو [۶]', 'Then what (or who) causes you (O disbelievers) to deny the Recompense (i.e. Day of Resurrection)?', 'So, what can make you, after all this, to deny the Requital?'),
(6106, 95, 8, 1, 20, 30, 'عَمَّ ', 'التّین', 'اَلَیۡسَ اللّٰہُ  بِاَحۡکَمِ الۡحٰکِمِیۡنَ ٪﴿۸﴾', 'کیا اللہ سب فیصلہ کرنے والوں سے بہتر فیصلہ کرنے والا نہیں ہے؟', 'کیا نہیں ہے اللہ سب حاکموں سے بڑا حاکم [۷]', 'Is not Allah the Best of judges?', 'Is Allah not the Greatest Ruler of all the rulers?'),
(6107, 96, 1, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'اِقۡرَاۡ بِاسۡمِ رَبِّکَ الَّذِیۡ خَلَقَ ۚ﴿۱﴾', 'اے نبی ﷺ اپنے پروردگار کا نام لے کر پڑھو جس نے تمام کائنات کو پیدا کیا۔', 'پڑھ اپنے رب کے نام سے [۱] جو سب کا بنانے والا ہے [۲]', 'Read! In the Name of your Lord, Who has created (all that exists),', 'Read with the name of your Lord who created (every thing),'),
(6108, 96, 2, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'خَلَقَ الۡاِنۡسَانَ مِنۡ عَلَقٍ ۚ﴿۲﴾', 'جس نے انسان کو خون کی پھٹکی سے بنایا۔', 'بنایا آدمی کو جمے ہوئے لہو سے [۳]', 'Has created man from a clot (a piece of thick coagulated blood).', 'He created man from a clot of blood.'),
(6109, 96, 3, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'اِقۡرَاۡ وَ رَبُّکَ الۡاَکۡرَمُ ۙ﴿۳﴾', 'پڑھو اور تمہارا پروردگار بڑا کریم ہے۔', 'پڑھ اور تیرا رب بڑا کریم ہے [۴]', 'Read! And your Lord is the Most Generous,', 'Read, and your Lord is the most gracious,'),
(6110, 96, 4, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'الَّذِیۡ عَلَّمَ بِالۡقَلَمِ ۙ﴿۴﴾', 'جس نے قلم کے ذریعے سے علم سکھایا۔', 'جس نے علم سکھایا قلم سے [۵]', 'Who has taught (the writing) by the pen (the first person to write was Prophet Idrees (Enoch) ),', 'who imparted knowledge by means of the pen.'),
(6111, 96, 5, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'عَلَّمَ الۡاِنۡسَانَ مَا لَمۡ  یَعۡلَمۡ ؕ﴿۵﴾', 'اور انسان کو وہ باتیں سکھائیں جن کا اسکو علم نہ تھا۔', 'سکھلایا آدمی کو جو وہ نہ جانتا تھا [۶]', 'Has taught man that which he knew not.', 'He taught man what he did not know.'),
(6112, 96, 6, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'کَلَّاۤ  اِنَّ  الۡاِنۡسَانَ  لَیَطۡغٰۤی ۙ﴿۶﴾', 'مگر انسان سرکش ہو جاتا ہے۔', 'کوئی نہیں آدمی سر چڑھتا ہے اس سے', 'Nay! Verily, man does transgress all bounds (in disbelief and evil deed, etc.).', 'In fact, man crosses the limits,'),
(6113, 96, 7, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'اَنۡ  رَّاٰہُ  اسۡتَغۡنٰی ﴿ؕ۷﴾', 'اس بناء پر کہ وہ اپنے آپکو بے نیاز سمجھتا ہے۔', 'کہ دیکھے اپنے آپکو بے پروا [۷]', 'Because he considers himself self-sufficient.', 'because he deems himself to be free of need.'),
(6114, 96, 8, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'اِنَّ  اِلٰی رَبِّکَ  الرُّجۡعٰی ؕ﴿۸﴾', 'کچھ شک نہیں کہ سب کو تمہارے پروردگار ہی کی طرف لوٹ کر جانا ہے۔', 'بیشک تیرے رب کی طرف پھر جانا ہے [۸]', 'Surely! Unto your Lord is the return.', 'Surely to your Lord is the return.'),
(6115, 96, 9, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'اَرَءَیۡتَ الَّذِیۡ یَنۡہٰی ۙ﴿۹﴾', 'کیا تم نے اس شخص کو دیکھا جو منع کرتا ہے۔', 'تو نے دیکھا اُسکو جو منع کرتا ہے', 'Have you (O Muhammad (Peace be upon him)) seen him (i.e. Aboo Jahl) who prevents,', 'Have you seen him who forbids'),
(6116, 96, 10, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'عَبۡدًا اِذَا صَلّٰی ﴿ؕ۱۰﴾', 'یعنی ایک بندے کو جب وہ نماز پڑھنے لگتا ہے۔', 'ایک بندہ کو جب وہ نماز پڑھے [۹]', 'A slave (Muhammad (Peace be upon him)) when he prays?', 'a servant of Allah when he prays?'),
(6117, 96, 11, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'اَرَءَیۡتَ  اِنۡ کَانَ عَلَی الۡہُدٰۤی ﴿ۙ۱۱﴾', 'بھلا دیکھو تو اگر یہ راہ راست پر ہو۔', 'بھلا دیکھ تو اگر ہوتا نیک راہ پر', 'Tell me, if he (Muhammad (Peace be upon him)) is on the guidance (of Allah)?', 'Tell me, if he is on the right path,'),
(6118, 96, 12, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'اَوۡ  اَمَرَ  بِالتَّقۡوٰی ﴿ؕ۱۲﴾', 'یا پرہیزگاری کا حکم کرے تو منع کرنا کیسا۔', 'یا سکھلاتا ڈر کے کام', 'Or enjoins piety?', 'or bids piety, (would the former still forbid him?)'),
(6119, 96, 13, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'اَرَءَیۡتَ  اِنۡ کَذَّبَ وَ تَوَلّٰی ﴿ؕ۱۳﴾', 'تو اس کا انجام کیا ہو گا ذرا دیکھو تو اگر اس نے دین حق کو جھٹلایا اور اس سے منہ موڑا۔', 'بھلا دیکھ تو اگر جھٹلایا اور منہ موڑا [۱۰]', 'Tell me if he (the disbeliever, Aboo Jahl) denies (the truth, i.e. this Quran), and turns away?', 'Tell me, if he rejects (the true faith) and turns away,'),
(6120, 96, 14, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'اَلَمۡ یَعۡلَمۡ بِاَنَّ اللّٰہَ یَرٰی ﴿ؕ۱۴﴾', 'کیا اسکو معلوم نہیں کہ اللہ دیکھ رہا ہے۔', 'یہ نہ جانا کہ اللہ دیکھتا ہے [۱۱]', 'Knows he not that Allah does see (what he does)?', 'does he not know that Allah is watching (him)?'),
(6121, 96, 15, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'کَلَّا لَئِنۡ لَّمۡ یَنۡتَہِ ۬ۙ  لَنَسۡفَعًۢا بِالنَّاصِیَۃِ ﴿ۙ۱۵﴾', 'دیکھو اگر وہ باز نہ آئے گا تو ہم اسکی پیشانی کے بال پکڑ کر گھسیٹیں گے۔', 'کوئی نہیں اگر باز نہ آئے گا ہم گھسیٹیں گے چوٹی پکڑ کر [۱۲]', 'Nay! If he (Aboo Jahl) ceases not, We will catch him by the forelock,', 'No! If he does not desist, We will certainly drag (him) by forelock,'),
(6122, 96, 16, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'نَاصِیَۃٍ کَاذِبَۃٍ خَاطِئَۃٍ ﴿ۚ۱۶﴾', 'یعنی اس جھوٹے خطارکار کی پیشانی کے بال۔', 'کیسی چوٹی جھوٹی گنہگار [۱۳]', 'A lying, sinful forelock!', 'a lying, sinful forelock.'),
(6123, 96, 17, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'فَلۡیَدۡعُ نَادِیَہٗ ﴿ۙ۱۷﴾', 'تو وہ اپنے یاران مجلس کو بلا لے۔', 'اب بلا لیوے اپنے مجلس والوں کو', 'Then, let him call upon his council (of helpers),', 'So let him call the men of his council,'),
(6124, 96, 18, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'سَنَدۡعُ  الزَّبَانِیَۃَ ﴿ۙ۱۸﴾', 'ہم بھی دوزخ کے فرشتوں کو بلائیں گے۔', 'ہم بھی بلاتے ہیں پیادے سیاست کرنے کو [۱۴]', 'We will call the guards of Hell (to deal with him)!', 'We will call the soldiers of the Hell.'),
(6125, 96, 19, 1, 21, 30, 'عَمَّ ', 'العَلَق', 'کَلَّا ؕ لَا تُطِعۡہُ وَ اسۡجُدۡ وَ اقۡتَرِبۡ ﴿٪ٛ۱۹﴾', 'دیکھو اس کا کہا نہ ماننا اور سجدہ کرنا اور اللہ کا قرب حاصل کرتے رہنا۔', 'کوئی نہیں مت مان اُسکا کہا اور سجدہ کر اور نزدیک ہو [۱۵]', 'Nay! (O Muhammad (Peace be upon him))! Do not obey him (Aboo Jahl). Fall prostrate and draw near to Allah!', 'No! Never obey him, and bow down in sajdah, and come close to Me.'),
(6126, 97, 1, 1, 22, 30, 'عَمَّ ', ' القدر', 'اِنَّاۤ  اَنۡزَلۡنٰہُ  فِیۡ  لَیۡلَۃِ  الۡقَدۡرِ ۚ﴿ۖ۱﴾', 'ہم نے اس قرآن کو شب قدر میں نازل کرنا شروع کیا۔', 'ہم نے اُسکو اتارا شب قدر میں [۱]', 'Verily! We have sent it (this Quran) down in the night of Al-Qadr (Decree)', 'We have sent it (the Qur’ān) down in the Night of Qadr.'),
(6127, 97, 2, 1, 22, 30, 'عَمَّ ', ' القدر', 'وَ مَاۤ  اَدۡرٰىکَ مَا لَیۡلَۃُ  الۡقَدۡرِ ؕ﴿۲﴾', 'اور تمہیں کیا معلوم کہ شب قدر کیا ہے؟', 'اور تو نے کیا سمجھا کہ کیا ہے شب قدر', 'And what will make you know what the night of Al-Qadr (Decree) is?', 'And what may let you know what the Night of Qadr is?'),
(6128, 97, 3, 1, 22, 30, 'عَمَّ ', ' القدر', 'لَیۡلَۃُ  الۡقَدۡرِ ۬ۙ خَیۡرٌ  مِّنۡ  اَلۡفِ شَہۡرٍ ؕ﴿ؔ۳﴾', 'شب قدر ہزار مہینے سے بہتر ہے۔', 'شب قدر بہتر ہے ہزار مہینے سے [۲]', 'The night of Al-Qadr (Decree) is better than a thousand months (i.e. worshipping Allah in that night is better than worshipping Him a thousand months, i.e. 83 years and 4 months).', 'The Night of Qadr is much better than one thousand months.'),
(6129, 97, 4, 1, 22, 30, 'عَمَّ ', ' القدر', 'تَنَزَّلُ الۡمَلٰٓئِکَۃُ وَ الرُّوۡحُ  فِیۡہَا بِاِذۡنِ رَبِّہِمۡ ۚ مِنۡ  کُلِّ  اَمۡرٍ ۙ﴿ۛ۴﴾', 'اس میں فرشتے اور روح القدس ہر کام کے انتظام کے لئے اپنے پروردگار کے حکم سے اترتے ہیں۔', 'اترتے ہیں فرشتے اور روح اُس میں اپنے رب کے حکم سے [۳] ہر کام پر [۴]', 'Therein descend the angels and the Rooh (Jibrael (Gabriel)) by Allahs Permission with all Decrees,', 'The angels and the Spirit descend in it, with the leave of your Lord, along with every command.'),
(6130, 97, 5, 1, 22, 30, 'عَمَّ ', ' القدر', 'سَلٰمٌ ۟ۛ ہِیَ حَتّٰی مَطۡلَعِ  الۡفَجۡرِ ٪﴿۵﴾', 'یہ رات طلوع فجر تک امن و سلامتی ہے۔', 'امان ہے [۵] وہ رات صبح کے نکلنے تک [۶]', 'Peace! (All that night, there is Peace and Goodness from Allah to His believing slaves) until the appearance of dawn.', 'Peace it is till the debut of dawn.'),
(6131, 98, 1, 1, 23, 30, 'عَمَّ ', 'البیّنۃ', 'لَمۡ  یَکُنِ الَّذِیۡنَ کَفَرُوۡا  مِنۡ  اَہۡلِ الۡکِتٰبِ وَ الۡمُشۡرِکِیۡنَ مُنۡفَکِّیۡنَ حَتّٰی تَاۡتِیَہُمُ  الۡبَیِّنَۃُ ۙ﴿۱﴾', 'جو لوگ کافر ہیں یعنی اہل کتاب اور مشرک وہ کفر سے باز رہنے والے نہ تھے یہاں تک کہ انکے پاس کھلی دلیل آ جائے۔', 'نہ تھے وہ لوگ جو منکر ہیں اہل کتاب اور مشرک [۱] باز آنے والے یہاں تک کہ پہنچے اُنکے پاس کھلی بات', 'Those who disbelieve from among the people of the Scripture (Jews and Christians) and among Al-Mushrikoon, were not going to leave (their disbelief) until there came to them clear evidence.', 'Those who disbelieved from among the People of the Book and the polytheists were not (expected) to desist (from their wrong beliefs) unless there comes to them a clear proof,'),
(6132, 98, 2, 1, 23, 30, 'عَمَّ ', 'البیّنۃ', 'رَسُوۡلٌ مِّنَ اللّٰہِ یَتۡلُوۡا صُحُفًا مُّطَہَّرَۃً  ۙ﴿۲﴾', 'یعنی اللہ کا ایک پیغمبر جو پاک اوراق پڑھ کر سناتا ہے۔', 'ایک رسول اللہ کا پڑھتا ہو  ورق پاک [۲]', 'A Messenger (Muhammad (Peace be upon him)) from Allah, reciting (the Quran) purified pages (purified from Al-Batil (falsehood, etc.)).', 'a messenger from Allah who recites the purified scrolls'),
(6133, 98, 3, 1, 23, 30, 'عَمَّ ', 'البیّنۃ', 'فِیۡہَا کُتُبٌ قَیِّمَۃٌ ؕ﴿۳﴾', 'جن میں مستحکم آیتیں لکھی ہوئی ہیں۔', 'اس میں لکھی ہیں کتابیں مضبوط [۳]', 'Containing correct and straight laws from Allah.', 'containing (right and) straight writings.'),
(6134, 98, 4, 1, 23, 30, 'عَمَّ ', 'البیّنۃ', 'وَ مَا تَفَرَّقَ الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ  اِلَّا مِنۡۢ  بَعۡدِ مَا جَآءَتۡہُمُ  الۡبَیِّنَۃُ ؕ﴿۴﴾', 'اور اہل کتاب جو فرقوں میں بٹے ہیں تو دلیل واضح کے آنے کے بعد ہی بٹے ہیں۔', 'اور وہ جو پھوٹ پڑی اہل کتاب میں سو جب کہ آ چکی اُنکے پاس کھلی بات [۴]', 'And the people of the Scripture (Jews and Christians) differed not until after there came to them clear evidence. (i.e. Prophet Muhammad (Peace be upon him) and whatever was revealed to him).', 'And those who were given the Book did not disagree but after the clear proof came to them,'),
(6135, 98, 5, 1, 23, 30, 'عَمَّ ', 'البیّنۃ', 'وَ مَاۤ  اُمِرُوۡۤا  اِلَّا لِیَعۡبُدُوا اللّٰہَ مُخۡلِصِیۡنَ لَہُ  الدِّیۡنَ ۬ۙ حُنَفَآءَ وَ یُقِیۡمُوا الصَّلٰوۃَ  وَ یُؤۡتُوا الزَّکٰوۃَ وَ ذٰلِکَ دِیۡنُ الۡقَیِّمَۃِ ؕ﴿۵﴾', 'حالانکہ انکو حکم تو یہی ہوا تھا کہ اللہ کی عبادت کریں کتاب کو اسی کیلئے خالص کرتے ہوئے یکسو ہو کر اور نماز قائم کریں اور زکوٰۃ دیں اور یہی مضبوط اصولوں والا دین ہے۔', 'اور انکو حکم یہی ہوا کہ بندگی کریں اللہ کی خالص کر کے اُسکے واسطے بندگی ابراہیم کی راہ پر [۵] اور قائم رکھیں نماز اور دیں زکوٰۃ اور یہ ہے راہ مضبوط لوگوں کی [۶]', 'And they were commanded not, but that they should worship Allah, and worship none but Him Alone (abstaining from ascribing partners to Him), and perform As-Salat (Iqamat-as-Salat) and give Zakat: and that is the right religion.', 'while they were not ordered but to worship Allah, making their submission exclusive for him with no deviation, and to establish Salāh and pay Zakāh. That is the way of the straight religion.'),
(6136, 98, 6, 1, 23, 30, 'عَمَّ ', 'البیّنۃ', 'اِنَّ  الَّذِیۡنَ کَفَرُوۡا مِنۡ اَہۡلِ الۡکِتٰبِ وَ الۡمُشۡرِکِیۡنَ فِیۡ  نَارِ جَہَنَّمَ خٰلِدِیۡنَ فِیۡہَا ؕ اُولٰٓئِکَ ہُمۡ شَرُّ الۡبَرِیَّۃِ ؕ﴿۶﴾', 'جو لوگ کافر ہیں یعنی اہل کتاب اور مشرک وہ دوزخ کی آگ میں پڑیں گے اور ہمیشہ اسی میں رہیں گے۔ یہ لوگ سب مخلوق سے زیادہ برے ہیں۔', 'اور جو منکر ہوئے اہل کتاب اور مشرک ہونگے دوزخ کی آگ میں سدا رہیں اُس میں [۷] وہ لوگ ہیں سب خلق سے بدتر [۸]', 'Verily, those who disbelieve (in the religion of Islam, the Quran and Prophet Muhammad (Peace be upon him)) from among the people of the Scripture (Jews and Christians) and Al-Mushrikoon will abide in the Fire of Hell. They are the worst of creatures.', 'Surely those who disbelieved from among the People of the Book and the polytheists will be in the fire of Jahannam , in which they will be living forever. Those are the worst of all human beings.'),
(6137, 98, 7, 1, 23, 30, 'عَمَّ ', 'البیّنۃ', 'اِنَّ  الَّذِیۡنَ  اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ ۙ اُولٰٓئِکَ ہُمۡ خَیۡرُ الۡبَرِیَّۃِ ؕ﴿۷﴾', 'بیشک جو لوگ ایمان لائے اور نیک عمل کرتے رہے وہ تمام خلقت سے بہتر ہیں۔', 'وہ لوگ جو یقین لائے اور کئے بھلے کام وہ لوگ ہیں سب خلق سے بہتر [۹]', 'Verily, those who believe (in the Oneness of Allah, and in His Messenger Muhammad (Peace be upon him)) including all obligations ordered by Islam) and do righteous good deeds, they are the best of creatures.', 'As for those who believed and did righteous deeds, they are the best of all human beings.'),
(6138, 98, 8, 1, 23, 30, 'عَمَّ ', 'البیّنۃ', 'جَزَآؤُہُمۡ عِنۡدَ  رَبِّہِمۡ جَنّٰتُ عَدۡنٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ خٰلِدِیۡنَ فِیۡہَاۤ  اَبَدًا ؕ رَضِیَ اللّٰہُ  عَنۡہُمۡ وَ رَضُوۡا عَنۡہُ ؕ ذٰلِکَ لِمَنۡ خَشِیَ رَبَّہٗ ٪﴿۸﴾', 'ان کا صلہ انکے پروردگار کے ہاں ہمیشہ رہنے کے باغ ہیں جنکے نیچے نہریں بہ رہی ہیں۔ ہمیشہ ہمیشہ ان میں رہیں گے۔ اللہ ان سے خوش اور وہ اس سے خوش یہ صلہ اس کے لئے ہے جو اپنے پروردگار سے ڈرتا ہے۔', 'بدلا اُن کا اُنکے رب کے یہاں باغ ہیں ہمیشہ رہنے کو نیچے بہتی ہں اُنکے نہریں سدا رہیں اُں میں ہمیشہ اللہ اُن سے راضی اور وہ اُس سے راضی [۱۰] یہ ملتا ہے اسکو جو ڈرا اپنے رب سے [۱۱]', 'Their reward with their Lord is Adn (Eden) Paradise (Gardens of Eternity), underneath which rivers flow, they will abide therein forever, Allah Well-Pleased with them, and they with Him. That is for him who fears his Lord.', 'Their reward, with their Lord, is gardens of eternity beneath which rivers flow, in which they will be abiding forever. Allah is well pleased with them, and they are well pleased with Him. That (reward) is for him who has awe of his Lord.'),
(6139, 99, 1, 1, 24, 30, 'عَمَّ ', 'الزّلزال', 'اِذَا  زُلۡزِلَتِ الۡاَرۡضُ  زِلۡزَالَہَا  ۙ﴿۱﴾', 'جب زمین بھونچال سے ہلا دی جائے گی۔', 'جب ہلا ڈالے زمین کو اُسکے بھونچال سے [۱]', 'When the earth is shaken with its (final) earthquake.', 'When the earth will be trembled with its quake,'),
(6140, 99, 2, 1, 24, 30, 'عَمَّ ', 'الزّلزال', 'وَ اَخۡرَجَتِ الۡاَرۡضُ اَثۡقَالَہَا ۙ﴿۲﴾', 'اور زمین اپنے اندر کے بوجھ نکال پھینکے گی۔', 'او ر نکال باہر کرے زمین اپنے اندر سے بوجھ [۲]', 'And when the earth throws out its burdens,', 'and the earth will bring forth its burdens,'),
(6141, 99, 3, 1, 24, 30, 'عَمَّ ', 'الزّلزال', 'وَ  قَالَ الۡاِنۡسَانُ مَا لَہَا ۚ﴿۳﴾', 'اور انسان کہے گا کہ اس کو کیا ہوا ہے؟', 'اور کہے آدمی اُس کو کیا ہو گیا [۳]', 'And man will say: \"What is the matter with it?\"', 'and man will say, “What has happened to it?”'),
(6142, 99, 4, 1, 24, 30, 'عَمَّ ', 'الزّلزال', 'یَوۡمَئِذٍ تُحَدِّثُ  اَخۡبَارَہَا ۙ﴿۴﴾', 'اس روز وہ اپنے حالات بیان کر دے گی۔', 'اُس دن کہہ ڈالے گی وہ اپنی باتیں', 'That Day it will declare its information (about all what happened over it of good or evil).', 'That day it will describe all its happenings,'),
(6143, 99, 5, 1, 24, 30, 'عَمَّ ', 'الزّلزال', 'بِاَنَّ  رَبَّکَ اَوۡحٰی لَہَا ؕ﴿۵﴾', 'کیونکہ تمہارے پروردگار نے اسکو حکم بھیجا ہوگا۔', 'اس واسطے کہ تیرے رب نے حکم بھیجا اُسکو [۴]', 'Because your Lord has inspired it.', 'because its Lord will have so commanded it.'),
(6144, 99, 6, 1, 24, 30, 'عَمَّ ', 'الزّلزال', 'یَوۡمَئِذٍ یَّصۡدُرُ  النَّاسُ اَشۡتَاتًا ۬ۙ لِّیُرَوۡا اَعۡمَالَہُمۡ ؕ﴿۶﴾', 'اس دن لوگ طرح طرح کے ہو کر آئیں گے۔ تاکہ انکو ان کے اعمال دکھا دیئے جائیں۔', 'اُس دن ہو پڑیں گے لوگ طرح طرح پر [۵] کہ اُنکو دکھا دیے جائیں اُنکے عمل [۶]', 'That Day mankind will proceed in scattered groups that they may be shown their deeds.', 'That day the people will come back (from the place of reckoning) in different groups, so that they may be shown (the fruits of) their deeds.'),
(6145, 99, 7, 1, 24, 30, 'عَمَّ ', 'الزّلزال', 'فَمَنۡ یَّعۡمَلۡ مِثۡقَالَ ذَرَّۃٍ خَیۡرًا یَّرَہٗ ؕ﴿۷﴾', 'تو جس نے ذرہ بھر نیکی کی ہو گی وہ اسکو دیکھ لے گا۔', 'سو جس نے کی ذرہ بھر بھلائی وہ دیکھ لے گا اُسے', 'So whosoever does good equal to the weight of an atom (or a small ant), shall see it.', 'So, whoever does any good act (even) to the weight of a particle will see it.'),
(6146, 99, 8, 1, 24, 30, 'عَمَّ ', 'الزّلزال', 'وَ مَنۡ یَّعۡمَلۡ مِثۡقَالَ ذَرَّۃٍ  شَرًّا یَّرَہٗ ٪﴿۸﴾', 'اور جس نے ذرہ بھر برائی کی ہو گی وہ اسے دیکھ لے گا۔', 'اور جس نے کی ذرہ بھر برائی دیکھ لے گا اُسے [۷]', 'And whosoever does evil equal to the weight of an atom (or a small ant), shall see it.', 'And whoever does evil (even) to the weight of a particle will see it.'),
(6147, 100, 1, 1, 25, 30, 'عَمَّ ', 'العٰدیٰت', 'وَ الۡعٰدِیٰتِ ضَبۡحًا ۙ﴿۱﴾', 'ان سرپٹ دوڑانے والے گھوڑوں کی قسم جو ہانپ اٹھتے ہیں۔', 'قسم ہے دوڑنے والے گھوڑوں کی ہانپ کر', 'By the (steeds) that run, with panting (breath),', '(I swear) by those (horses) that run snorting,'),
(6148, 100, 2, 1, 25, 30, 'عَمَّ ', 'العٰدیٰت', 'فَالۡمُوۡرِیٰتِ قَدۡحًا ۙ﴿۲﴾', 'پھر پتھروں پر نعل مار کر آگ نکالتے ہیں۔', 'پھر آگ سلگانے والے جھاڑ کر [۱]', 'Striking sparks of fire (by their hooves),', 'then those that create sparks by striking (their hoofs) on the stones,'),
(6149, 100, 3, 1, 25, 30, 'عَمَّ ', 'العٰدیٰت', 'فَالۡمُغِیۡرٰتِ صُبۡحًا ۙ﴿۳﴾', 'پھر صبح کو چھاپہ مارتے ہیں۔', 'پھر غارت کر ڈالنے والے صبح کو [۲]', 'And scouring to the raid at dawn', 'then those that invade at morning,'),
(6150, 100, 4, 1, 25, 30, 'عَمَّ ', 'العٰدیٰت', 'فَاَثَرۡنَ بِہٖ نَقۡعًا ۙ﴿۴﴾', 'پھر اس وقت گرد اڑاتے ہیں۔', 'پھر اٹھانے والے اُس میں گرد [۳]', 'And raise the dust in clouds the while,', 'then raise, at the same time, a trail of dust,'),
(6151, 100, 5, 1, 25, 30, 'عَمَّ ', 'العٰدیٰت', 'فَوَسَطۡنَ بِہٖ جَمۡعًا ۙ﴿۵﴾', 'پھر اس وقت دشمن کی فوج میں جا گھستے ہیں۔', 'پھر گھس جانے والے اُس وقت فوج میں [۴]', 'Penetrating forthwith as one into the midst (of the foe);', 'then enter, at the same time, into the centre of the (opposing) host,'),
(6152, 100, 6, 1, 25, 30, 'عَمَّ ', 'العٰدیٰت', 'اِنَّ  الۡاِنۡسَانَ لِرَبِّہٖ  لَکَنُوۡدٌ ۚ﴿۶﴾', 'کہ انسان اپنے پروردگار کا بڑا ناشکرا ہے۔', 'بیشک آدمی اپنے رب کا ناشکر ہے [۵]', 'Verily! Man (disbeliever) is ungrateful to his Lord;', 'man is, indeed, very ungrateful to his Lord,'),
(6153, 100, 7, 1, 25, 30, 'عَمَّ ', 'العٰدیٰت', 'وَ  اِنَّہٗ  عَلٰی ذٰلِکَ لَشَہِیۡدٌ ۚ﴿۷﴾', 'اور وہ اس بات سے آگاہ بھی ہے۔', 'اور وہ آدمی اس کام کو سامنے دیکھتا ہے [۶]', 'And to that fact he bears witness (by his deeds);', 'and he himself is a witness to that fact,'),
(6154, 100, 8, 1, 25, 30, 'عَمَّ ', 'العٰدیٰت', 'وَ  اِنَّہٗ  لِحُبِّ الۡخَیۡرِ  لَشَدِیۡدٌ ؕ﴿۸﴾', 'اور بیشک وہ مال سے بہت محبت کرنے والا ہے۔', 'اور آدمی محبت پر مال کی بہت پکا ہے [۷]', 'And verily, he is violent in the love of wealth.', 'and in his love for wealth, he is very intense.'),
(6155, 100, 9, 1, 25, 30, 'عَمَّ ', 'العٰدیٰت', 'اَفَلَا یَعۡلَمُ  اِذَا بُعۡثِرَ مَا فِی الۡقُبُوۡرِ ۙ﴿۹﴾', 'کیا وہ اس وقت کو نہیں جانتا کہ جب مردے قبروں میں سے باہر نکال لئے جائیں گے۔', 'کیا نہیں جانتا وہ وقت کہ کریدا جائے جو کچھ قبروں میں ہے', 'Knows he not that when the contents of the graves are brought out and poured forth (all mankind is resurrected).', 'Does he not then know (what will happen) when all that is contained in the graves will be overturned,'),
(6156, 100, 10, 1, 25, 30, 'عَمَّ ', 'العٰدیٰت', 'وَ  حُصِّلَ مَا فِی الصُّدُوۡرِ ﴿ۙ۱۰﴾', 'اور جو بھید دلوں میں ہیں وہ ظاہر کر دیئے جائیں گے۔', 'اور تحقیق ہووے جو کچھ کہ جیوں میں ہے [۸]', 'And that which is in the breasts (of men) shall be made known.', 'and all that is contained in the hearts will be exposed.'),
(6157, 100, 11, 1, 25, 30, 'عَمَّ ', 'العٰدیٰت', 'اِنَّ  رَبَّہُمۡ  بِہِمۡ یَوۡمَئِذٍ لَّخَبِیۡرٌ ٪﴿۱۱﴾', 'بیشک ان کا پروردگار اس روز ان سے خوب واقف ہو گا۔', 'بیشک اُنکے رب کو اُنکی اُس دن سب خبر ہے [۹]', 'Verily, that Day (i.e. the Day of Resurrection) their Lord will be Well-Acquainted with them (as to their deeds), (and will reward them for their deeds).', 'Surely your Lord, that day, is fully aware of them.'),
(6158, 101, 1, 1, 26, 30, 'عَمَّ ', ' القارعۃ', 'اَلۡقَارِعَۃُ ۙ﴿۱﴾', 'کھڑکھڑانے والی۔', 'وہ کھڑکھڑا ڈالنے والی', 'Al-Qariah (the striking Hour i.e. the Day of Resurrection),', 'The Striking Event!'),
(6159, 101, 2, 1, 26, 30, 'عَمَّ ', ' القارعۃ', 'مَا الۡقَارِعَۃُ ۚ﴿۲﴾', 'کھڑکھڑانے والی کیا ہے؟', 'کیا ہے وہ کھڑ کھڑا ڈالنے والی', 'What is the striking (Hour)?', 'What is the Striking Event?'),
(6160, 101, 3, 1, 26, 30, 'عَمَّ ', ' القارعۃ', 'وَ  مَاۤ  اَدۡرٰىکَ مَا الۡقَارِعَۃُ ؕ﴿۳﴾', 'اور تم کیا جانو کہ کھڑکھڑانے والی کیا ہے؟', 'اور تو کیا سمجھا کیا ہے وہ کھڑ کھڑا ڈالنے والی [۱]', 'And what will make you know what the striking (Hour) is?', 'And what may let you know what the Striking Event is?'),
(6161, 101, 4, 1, 26, 30, 'عَمَّ ', ' القارعۃ', 'یَوۡمَ یَکُوۡنُ  النَّاسُ کَالۡفَرَاشِ الۡمَبۡثُوۡثِ ۙ﴿۴﴾', 'وہ قیامت ہے جس دن لوگ ایسے ہوں گے جیسے بکھرے ہوئے پروانے۔', 'جس دن ہوویں لوگ جیسے پتنگے بکھرے ہوئے [۲]', 'It is a Day whereon mankind will be like moths scattered about,', '(It will happen) on a day when people will be like scattered moths,'),
(6162, 101, 5, 1, 26, 30, 'عَمَّ ', ' القارعۃ', 'وَ تَکُوۡنُ  الۡجِبَالُ کَالۡعِہۡنِ الۡمَنۡفُوۡشِ ؕ﴿۵﴾', 'اور پہاڑ ایسے ہو جائیں گے جیسے دھنکی ہوئی رنگ برنگی اون۔', 'اور ہوویں پہاڑ جیسے رنگی ہوئی اون دُھنی ہوئی [۳]', 'And the mountains will be like carded wool,', 'and the mountains will be like carded wool.'),
(6163, 101, 6, 1, 26, 30, 'عَمَّ ', ' القارعۃ', 'فَاَمَّا  مَنۡ  ثَقُلَتۡ مَوَازِیۡنُہٗ ۙ﴿۶﴾', 'اب جس کے اعمال کے وزن بھاری نکلیں گے۔', 'سو جسکی بھاری ہوئیں تولیں', 'Then as for him whose balance (of good deeds) will be heavy,', 'Then, as for him whose scales (of good deeds) are heavy,'),
(6164, 101, 7, 1, 26, 30, 'عَمَّ ', ' القارعۃ', 'فَہُوَ  فِیۡ عِیۡشَۃٍ  رَّاضِیَۃٍ ؕ﴿۷﴾', 'وہ دلپسند عیش میں ہوگا۔', 'تو وہ رہے گا من مانتے گذران میں [۴]', 'He will live a pleasant life (in Paradise).', 'he will be in a happy life.'),
(6165, 101, 8, 1, 26, 30, 'عَمَّ ', ' القارعۃ', 'وَ اَمَّا مَنۡ خَفَّتۡ مَوَازِیۡنُہٗ ۙ﴿۸﴾', 'اور جس کے وزن ہلکے نکلیں گے۔', 'اور جسکی ہلکی ہوئیں تولیں', 'But as for him whose balance (of good deeds) will be light,', 'But he whose scales are light,'),
(6166, 101, 9, 1, 26, 30, 'عَمَّ ', ' القارعۃ', 'فَاُمُّہٗ  ہَاوِیَۃٌ ؕ﴿۹﴾', 'اس کا ٹھکانہ ہاویہ ہے۔', 'تو اُس کا ٹھکانہ گڑھا ہے', 'He will have his home in Hawiyah (pit, i.e. Hell).', '-his abode will be Abyss.'),
(6167, 101, 10, 1, 26, 30, 'عَمَّ ', ' القارعۃ', 'وَ مَاۤ  اَدۡرٰىکَ مَا ہِیَہۡ ﴿ؕ۱۰﴾', 'اور تم کیا سمجھے کہ ہاویہ کیا چیز ہے؟', 'اور تو کیا سمجھا وہ کیا ہے', 'And what will make you know what it is?', 'And what may let you know what that (Abyss) is?'),
(6168, 101, 11, 1, 26, 30, 'عَمَّ ', ' القارعۃ', 'نَارٌ حَامِیَۃٌ ﴿٪۱۱﴾', 'وہ دہکتی ہوئی آگ ہے۔', 'آگ ہے دہکتی ہوئی [۵]', '(It is) a hot blazing Fire!', 'A blazing Fire!'),
(6169, 102, 1, 1, 27, 30, 'عَمَّ ', 'التّکاثُر', 'اَلۡہٰکُمُ  التَّکَاثُرُ ۙ﴿۱﴾', 'لوگو تمکو زیادہ سے زیادہ مال سمیٹنے کی خواہش نے غفلت میں ڈالے رکھا۔', 'غفلت میں رکھا تم کو بہتایت کی حرص نے', 'The mutual rivalry for piling up of worldly things diverts you,', 'You are distracted by mutual competition in amassing (worldly benefits),'),
(6170, 102, 2, 1, 27, 30, 'عَمَّ ', 'التّکاثُر', 'حَتّٰی زُرۡتُمُ  الۡمَقَابِرَ ؕ﴿۲﴾', 'یہاں تک کہ تم نے قبریں جا دیکھیں۔', 'یہاں تک کہ جا دیکھیں قبریں [۱]', 'Until you visit the graves (i.e. till you die).', 'until you reach the graves.'),
(6171, 102, 3, 1, 27, 30, 'عَمَّ ', 'التّکاثُر', 'کَلَّا  سَوۡفَ تَعۡلَمُوۡنَ ۙ﴿۳﴾', 'دیکھو تمہیں عنقریب معلوم ہو جائے گا۔', 'کوئی نہیں آگے جان لو گے', 'Nay! You shall come to know!', 'No! (This is not a correct attitude.) You will soon know (the reality).'),
(6172, 102, 4, 1, 27, 30, 'عَمَّ ', 'التّکاثُر', 'ثُمَّ  کَلَّا سَوۡفَ تَعۡلَمُوۡنَ ؕ﴿۴﴾', 'پھر دیکھو تمہیں عنقریب معلوم ہو جائے گا۔', 'پھر بھی کوئی نہیں آگے جان لو گے [۲]', 'Again, Nay! You shall come to know!', 'Again, you will soon know.'),
(6173, 102, 5, 1, 27, 30, 'عَمَّ ', 'التّکاثُر', 'کَلَّا لَوۡ تَعۡلَمُوۡنَ عِلۡمَ  الۡیَقِیۡنِ ؕ﴿۵﴾', 'دیکھو اگر تم جانتے یعنی یقینی علم رکھتے تو غفلت میں نہ پڑتے۔', 'کوئی نہیں اگر جانو تم یقین کر کے [۳]', 'Nay! If you knew with a sure knowledge (the end result of piling up, you would not have occupied yourselves in worldly things)', 'No! Only if you knew (it) with a sure knowledge!'),
(6174, 102, 6, 1, 27, 30, 'عَمَّ ', 'التّکاثُر', 'لَتَرَوُنَّ  الۡجَحِیۡمَ ۙ﴿۶﴾', 'تم ضرور دوزخ کو دیکھو گے۔', 'بیشک تم کو دیکھنا ہے دوزخ', 'Verily, You shall see the blazing Fire (Hell)!', 'You will certainly see the Hell,'),
(6175, 102, 7, 1, 27, 30, 'عَمَّ ', 'التّکاثُر', 'ثُمَّ لَتَرَوُنَّہَا عَیۡنَ الۡیَقِیۡنِ ۙ﴿۷﴾', 'پھر تم اسکو یقین کی آنکھ سے دیکھ لو گے۔', 'پھر دیکھنا ہے اُسکو یقین کی آنکھ سے [۴]', 'And again, you shall see it with certainty of sight!', 'then you will see it with full certitude.'),
(6176, 102, 8, 1, 27, 30, 'عَمَّ ', 'التّکاثُر', 'ثُمَّ لَتُسۡـَٔلُنَّ یَوۡمَئِذٍ عَنِ النَّعِیۡمِ ٪﴿۸﴾', 'پھر اس روز تم سے شکر نعمت کے بارے میں ضرور پرسش ہو گی؟', 'پھر پوچھیں گے تم سے اُس دن آرام کی حقیقت [۵]', 'Then, on that Day, you shall be asked about the delight (you indulged in, in this world)!', 'Then you will be asked about all the pleasures (you enjoyed in the world).'),
(6177, 103, 1, 1, 28, 30, 'عَمَّ ', ' العصر', 'وَ الۡعَصۡرِ ۙ﴿۱﴾', 'عصر کی قسم۔', 'قسم ہے عصر کی [۱]', 'By Al-Asr (the time).', '(I swear) by the Time,'),
(6178, 103, 2, 1, 28, 30, 'عَمَّ ', ' العصر', 'اِنَّ  الۡاِنۡسَانَ لَفِیۡ خُسۡرٍ ۙ﴿۲﴾', 'کہ انسان نقصان میں ہے۔', 'مقرر انسان ٹوٹے میں ہے [۲]', 'Verily! Man is in loss,', 'man is in a state of loss indeed,'),
(6179, 103, 3, 1, 28, 30, 'عَمَّ ', ' العصر', 'اِلَّا  الَّذِیۡنَ  اٰمَنُوۡا وَ عَمِلُوا الصّٰلِحٰتِ وَ تَوَاصَوۡا بِالۡحَقِّ ۬ۙ  وَ تَوَاصَوۡا بِالصَّبۡرِ ٪﴿۳﴾', 'مگر وہ لوگ جو ایمان لائے اور نیک عمل کرتے رہے اور آپس میں حق پر چلنے کی تلقین اور صبر کی تاکید کرتے رہے۔', 'مگر جو لوگ کہ یقین لائے اور کئے بھلے کام اور آپس میں تاکید کرتے رہے سچے دین کی اور آپس میں تاکید کرتے رہے تحمل کی [۳]', 'Except those who believe (in Islamic Monotheism) and do righteous good deeds, and recommend one another to the truth (i.e. order one another to perform all kinds of good deeds (Al-Maroof ÇáãÚÑæÝ)which Allah has ordained, and abstain from all kinds of sins and evil deeds (Al-Munkar ÇáãäßÑ)which Allah has forbidden), and recommend one another to patience (for the sufferings, harms, and injuries which one may encounter in Allahs Cause during preaching His religion of Islamic Monotheism or Jihad, etc.).', 'except those who believed and did righteous deeds, and exhorted each other to follow truth, and exhorted each other to observe patience.'),
(6180, 104, 1, 1, 29, 30, 'عَمَّ ', 'الھُمَزَۃ', 'وَیۡلٌ   لِّکُلِّ ہُمَزَۃٍ   لُّمَزَۃِۣ ۙ﴿۱﴾', 'ہر غیبت کرنے والے طعنے دینے والے کی خرابی ہے۔', 'خرابی ہے ہر طعنہ دینے والے  عیب چننے والے کی [۱]', 'Woe to every slanderer and backbiter.', 'Woe to every backbiter, derider'),
(6181, 104, 2, 1, 29, 30, 'عَمَّ ', 'الھُمَزَۃ', 'الَّذِیۡ جَمَعَ  مَالًا  وَّ عَدَّدَہٗ ۙ﴿۲﴾', 'جو مال جمع کرتا ہے اور اسکو گن گن کر رکھتا ہے۔', 'جس نے سمیٹا مال اور گن گن کر رکھا [۲]', 'Who has gathered wealth and counted it,', 'who accumulates wealth and counts it.'),
(6182, 104, 3, 1, 29, 30, 'عَمَّ ', 'الھُمَزَۃ', 'یَحۡسَبُ اَنَّ مَالَہٗۤ  اَخۡلَدَہٗ ۚ﴿۳﴾', 'شاید وہ خیال کرتا ہے کہ اس کا مال اسکی ہمیشہ کی زندگی کا موجب ہو گا۔', 'خیال رکھتا ہے کہ اُس کا مال سدا کو رہے گا اُسکے ساتھ [۳]', 'He thinks that his wealth will make him last forever!', 'He thinks that his wealth has made him eternal.'),
(6183, 104, 4, 1, 29, 30, 'عَمَّ ', 'الھُمَزَۃ', 'کَلَّا  لَیُنۡۢبَذَنَّ فِی الۡحُطَمَۃِ ۫﴿ۖ۴﴾', 'ہرگز نہیں وہ ضرور حطمہ میں جھونک دیا جائے گا۔', 'کوئی نہیں وہ پھینکا جائے گا اُس روندنے والی میں [۴]', 'Nay! Verily, he will be thrown into the crushing Fire.', 'Never! He will certainly be thrown into the Crushing Fire.'),
(6184, 104, 5, 1, 29, 30, 'عَمَّ ', 'الھُمَزَۃ', 'وَ  مَاۤ  اَدۡرٰىکَ مَا  الۡحُطَمَۃُ ؕ﴿۵﴾', 'اور تم کیا سمجھے کہ حطمہ کیا ہے۔', 'اور تو کیا سمجھا کون ہے وہ روندنے والی', 'And what will make you know what the crushing Fire is?', 'And what may let you know what the Crushing Fire is?'),
(6185, 104, 6, 1, 29, 30, 'عَمَّ ', 'الھُمَزَۃ', 'نَارُ اللّٰہِ الۡمُوۡقَدَۃُ ۙ﴿۶﴾', 'وہ اللہ کی بھڑکائی ہوئی آگ ہے۔', 'ایک آگ ہے اللہ کی سلگائی ہوئی', 'The fire of Allah, kindled,', 'It is Allah’s kindled fire'),
(6186, 104, 7, 1, 29, 30, 'عَمَّ ', 'الھُمَزَۃ', 'الَّتِیۡ  تَطَّلِعُ  عَلَی الۡاَفۡـِٕدَۃِ ؕ﴿۷﴾', 'جو دلوں تک جا پہنچے گی۔', 'وہ جھانک لیتی ہے دل کو [۵]', 'Which leaps up over the hearts,', 'that will peep into the hearts.'),
(6187, 104, 8, 1, 29, 30, 'عَمَّ ', 'الھُمَزَۃ', 'اِنَّہَا عَلَیۡہِمۡ  مُّؤۡصَدَۃٌ ۙ﴿۸﴾', 'بیشک وہ اس میں بند کر دیئے جائیں گے۔', 'اُنکو اُس میں موند دیا ہے [۶]', 'Verily, it shall be closed in on them,', 'It will be closed on them,'),
(6188, 104, 9, 1, 29, 30, 'عَمَّ ', 'الھُمَزَۃ', 'فِیۡ  عَمَدٍ  مُّمَدَّدَۃٍ ٪﴿۹﴾', 'یعنی آگ کے لمبے لمبے ستونوں میں۔', 'لنبے لنبے ستونوں میں [۷]', 'In pillars stretched forth (i.e. they will be punished in the Fire with pillars, etc.).', 'in outstretched columns.'),
(6189, 105, 1, 1, 30, 30, 'عَمَّ ', 'الفِیل', 'اَلَمۡ  تَرَ کَیۡفَ فَعَلَ رَبُّکَ  بِاَصۡحٰبِ الۡفِیۡلِ ؕ﴿۱﴾', 'کیا تم نے نہیں دیکھا کہ تمہارے پروردگار نے ہاتھی والوں کے ساتھ کیا کیا۔', 'کیا تو نے نہ دیکھا کیسا کیا تیرے رب نے ہاتھی والوں کے ساتھ [۱]', 'Have you (O Muhammad (Peace be upon him)) not seen how your Lord dealt with the Owners of the Elephant? (The elephant army which came from Yemen under the command of Abrahah Al-Ashram intending to destroy the Kabah at Makkah).', 'Have you not seen how your Lord dealt with the People of the Elephant?'),
(6190, 105, 2, 1, 30, 30, 'عَمَّ ', 'الفِیل', 'اَلَمۡ  یَجۡعَلۡ  کَیۡدَہُمۡ فِیۡ  تَضۡلِیۡلٍ ۙ﴿۲﴾', 'کیا اس نے ان کا داؤں غلط نہیں کیا؟', 'کیا نہیں کر دیا اُن کا داؤ غلط [۲]', 'Did He not make their plot go astray?', 'Has He not turned their plan into nullity?'),
(6191, 105, 3, 1, 30, 30, 'عَمَّ ', 'الفِیل', 'وَّ  اَرۡسَلَ عَلَیۡہِمۡ  طَیۡرًا  اَبَابِیۡلَ ۙ﴿۳﴾', 'اور اس نے ان پر جھنڈ کے جھنڈ پرندے چھوڑ دیئے۔', 'اور بھیجے اُن پر اڑتے جانور ٹکڑیاں ٹکڑیاں', 'And sent against them birds, in flocks,', 'And He sent upon them flying birds in flocks,'),
(6192, 105, 4, 1, 30, 30, 'عَمَّ ', 'الفِیل', 'تَرۡمِیۡہِمۡ  بِحِجَارَۃٍ  مِّنۡ سِجِّیۡلٍ ۪ۙ﴿۴﴾', 'جو ان پر کھنگر کی پتھریاں پھینکتے تھے۔', 'پھینکتے تھے اُن پر پتھریاں کنکر کی [۳]', 'Striking them with stones of Sijjeel.', 'throwing upon them stones of baked clay,'),
(6193, 105, 5, 1, 30, 30, 'عَمَّ ', 'الفِیل', 'فَجَعَلَہُمۡ کَعَصۡفٍ مَّاۡکُوۡلٍ ٪﴿۵﴾', 'تو اس نے ان کو ایسا کر دیا جیسے کھایا ہوا بھس۔', 'پھر کر ڈالا اُنکو جیسے بھس کھایا ہوا[۴]', 'And made them like an empty field of stalks (of which the corn has been eaten up by cattle).', 'and thus He turned them into an eaten-up chaff.'),
(6194, 106, 1, 1, 31, 30, 'عَمَّ ', 'قُرَیش', 'لِاِیۡلٰفِ قُرَیۡشٍ ۙ﴿۱﴾', 'قریش کے مانوس کرنے کی بنا پر۔', 'اس واسطے کہ مانوس رکھا قریش کو', '(It is a great Grace and Protection from Allah), for the taming of the Quraish,', 'Because of the familiarity of the Quraish,'),
(6195, 106, 2, 1, 31, 30, 'عَمَّ ', 'قُرَیش', 'اٖلٰفِہِمۡ  رِحۡلَۃَ  الشِّتَآءِ  وَ الصَّیۡفِ ۚ﴿۲﴾', 'یعنی انکو جاڑے اور گرمی کے سفر سے مانوس کرنے کی بنا پر۔', 'مانوس رکھنا اُنکو  سفر سے جاڑے کے اور گرمی کے', '(And with all those Allahs Grace and Protections for their taming, We cause) the (Quraish) caravans to set forth safe in winter (to the south), and in summer (to the north without any fear),', 'that is, their familiarity with the trips of winter and summer,'),
(6196, 106, 3, 1, 31, 30, 'عَمَّ ', 'قُرَیش', 'فَلۡیَعۡبُدُوۡا  رَبَّ ہٰذَا الۡبَیۡتِ ۙ﴿۳﴾', 'انہیں چاہیے کہ اس نعمت کے شکر میں اس گھر کے مالک کی عبادت کریں۔', 'تو چاہیے کہ بندگی کریں اس گھر کے رب کی', 'So let them worship (Allah) the Lord of this House (the Kabah in Makkah).', 'they must worship the Lord of this House,'),
(6197, 106, 4, 1, 31, 30, 'عَمَّ ', 'قُرَیش', 'الَّذِیۡۤ  اَطۡعَمَہُمۡ  مِّنۡ جُوۡعٍ ۬ۙ وَّ اٰمَنَہُمۡ مِّنۡ خَوۡفٍ ٪﴿۴﴾', 'جس نے انکو بھوک میں کھانا کھلایا۔ اور خوف سے امن بخشا۔', 'جس نے اُنکو کھانا دیا بھوک میں اور امن دیا ڈر میں [۱]', '(He) Who has fed them against hunger, and has made them safe from fear.', 'who gave them food against hunger, and gave them security against fear.'),
(6198, 107, 1, 1, 32, 30, 'عَمَّ ', 'المَاعُون', 'اَرَءَیۡتَ  الَّذِیۡ یُکَذِّبُ بِالدِّیۡنِ ؕ﴿۱﴾', 'کیا تم نے اس شخص کو دیکھا جو روز جزا کو جھٹلاتا ہے۔', 'تو نے دیکھا اُسکو جو جھٹلاتا ہے انصاف ہونے کو [۱]', 'Have you seen him who denies the Recompense?', 'Have you seen him who denies the Requital?');
INSERT INTO `quran` (`id`, `suraNo`, `ayatNo`, `rakuNo`, `paraRakuNo`, `paraNo`, `paraName`, `suraName`, `quranArabic`, `quFateh`, `quMehmood`, `engMohsin`, `engTaqi`) VALUES
(6199, 107, 2, 1, 32, 30, 'عَمَّ ', 'المَاعُون', 'فَذٰلِکَ الَّذِیۡ یَدُعُّ  الۡیَتِیۡمَ ۙ﴿۲﴾', 'یہ وہی بدبخت ہے جو یتیم کو دھکے دیتا ہے۔', 'سو یہ وہی ہے جو دھکے دیتا ہے یتیم کو  [۲]', 'That is he who repulses the orphan (harshly),', 'So, he is the one who pushes away the orphan,'),
(6200, 107, 3, 1, 32, 30, 'عَمَّ ', 'المَاعُون', 'وَ لَا یَحُضُّ عَلٰی طَعَامِ الۡمِسۡکِیۡنِ ؕ﴿۳﴾', 'اور نادار کو کھانا کھلانے کے لئے لوگوں کو ترغیب نہیں دیتا۔', 'اور نہیں تاکید کرتا محتاج کے کھانے پر [۳]', 'And urges not the feeding of AlMiskeen (the poor),', 'and does not persuade (others) to feed the needy.'),
(6201, 107, 4, 1, 32, 30, 'عَمَّ ', 'المَاعُون', 'فَوَیۡلٌ  لِّلۡمُصَلِّیۡنَ ۙ﴿۴﴾', 'تو ایسے نمازیوں کی خرابی ہے۔', 'پھر خرابی ہے اُن نمازیوں کی', 'So woe unto those performers of Salat (prayers) (hypocrites),', 'So, Woe to those performers of Salāh,'),
(6202, 107, 5, 1, 32, 30, 'عَمَّ ', 'المَاعُون', 'الَّذِیۡنَ ہُمۡ عَنۡ صَلَاتِہِمۡ سَاہُوۡنَ ۙ﴿۵﴾', 'جو اپنی نماز کی طرف سے غافل رہتے ہیں۔', 'جو اپنی نماز سے بے خبر ہیں [۴]', 'Who delay their Salat (prayer) from their stated fixed times,', 'who are neglectful of their Salāh,'),
(6203, 107, 6, 1, 32, 30, 'عَمَّ ', 'المَاعُون', 'الَّذِیۡنَ ہُمۡ  یُرَآءُوۡنَ ۙ﴿۶﴾', 'جو ریاکاری کرتے ہیں۔', 'وہ جو دکھلاوا کرتے ہیں [۵]', 'Those who do good deeds only to be seen (of men),', 'who (do good only to) show off,'),
(6204, 107, 7, 1, 32, 30, 'عَمَّ ', 'المَاعُون', 'وَ یَمۡنَعُوۡنَ الۡمَاعُوۡنَ ٪﴿۷﴾', 'اور جو برتنے کی چیزیں مانگنے پر نہیں دیتے۔', 'اور مانگے نہ دیویں برتنے کی چیز [۶]', 'And refuse Al-Maoon (small kindnesses e.g. salt, sugar, water, etc.).', 'and refuse (to give even) small gifts.'),
(6205, 108, 1, 1, 33, 30, 'عَمَّ ', 'الکوثر', 'اِنَّاۤ  اَعۡطَیۡنٰکَ  الۡکَوۡثَرَ ؕ﴿۱﴾', 'اے نبی ﷺ ہم نے تمکو کوثر یعنی بہت زیادہ بھلائی عطا فرمائی ہے۔', 'بیشک ہم نے دی تجھ کو کوثر [۱]', 'Verily, We have granted you (O Muhammad (Peace be upon him)) Al-Kauthar (a river in Paradise);', '(O Prophet,) surely We have given to you Al-Kauthar.'),
(6206, 108, 2, 1, 33, 30, 'عَمَّ ', 'الکوثر', 'فَصَلِّ  لِرَبِّکَ وَ انۡحَرۡ ؕ﴿۲﴾', 'تو اپنے پروردگار کے لئے نماز پڑھا کرو اور قربانی کیا کرو۔', 'سو نماز پڑھ اپنے رب کے آگے اور قربانی کر [۲]', 'Therefore turn in prayer to your Lord and sacrifice (to Him only).', 'So, offer Salāh (prayer) to your Lord, and sacrifice.'),
(6207, 108, 3, 1, 33, 30, 'عَمَّ ', 'الکوثر', 'اِنَّ شَانِئَکَ ہُوَ الۡاَبۡتَرُ ٪﴿۳﴾', 'کچھ شک نہیں کہ تمہارا دشمن ہی بے نام رہے گا۔', 'بیشک جو دشمن ہے تیرا وہی رہ گیا پیچھا کٹا [۳]', 'For he who makes you angry (O Muhammad (Peace be upon him)), - he will be cut off (from every good thing in this world and in the Hereafter).', 'Surely it is your enemy whose traces are cut off.'),
(6208, 109, 1, 1, 34, 30, 'عَمَّ ', 'الکٰفرون', 'قُلۡ یٰۤاَیُّہَا الۡکٰفِرُوۡنَ ۙ﴿۱﴾', 'اے پیغمبر ﷺ کہدو کہ اے کافرو!', 'تو کہہ اے منکرو [۱]', 'Say (O Muhammad (Peace be upon him)to these Mushrikoon and Kafiroon): \"O Al-Kafiroon (disbelievers in Allah, in His Oneness, in His Angels, in His Books, in His Messengers, in the Day of Resurrection, and in Al-Qadar, etc.)!', 'Say, “O disbelievers,'),
(6209, 109, 2, 1, 34, 30, 'عَمَّ ', 'الکٰفرون', 'لَاۤ  اَعۡبُدُ مَا تَعۡبُدُوۡنَ ۙ﴿۲﴾', 'جن بتوں کو تم پوجتے ہو انکو میں نہیں پوجتا۔', 'میں نہیں پوجتا جسکو تم پوجتے ہو', '\"I worship not that which you worship,', 'I do not worship that which you worship,'),
(6210, 109, 3, 1, 34, 30, 'عَمَّ ', 'الکٰفرون', 'وَ لَاۤ  اَنۡتُمۡ عٰبِدُوۡنَ مَاۤ  اَعۡبُدُ ۚ﴿۳﴾', 'اور جس معبود کی میں عبادت کرتا ہوں اسکی تم عبادت نہیں کرتے۔', 'اور نہ تم پوجو جسکو میں پوجوں [۲]', '\"Nor will you worship that which I worship.', 'nor do you worship the One whom I worship.'),
(6211, 109, 4, 1, 34, 30, 'عَمَّ ', 'الکٰفرون', 'وَ لَاۤ  اَنَا عَابِدٌ مَّا عَبَدۡتُّمۡ ۙ﴿۴﴾', 'اور میں پھر کہتا ہوں کہ جنکی تم پرستش کرتے ہو انکی میں پرستش کرنے والا نہیں ہوں۔', 'اور نہ مجھ کو پوجنا ہے اُس کا جسکو تم نے پوجا', '\"And I shall not worship that which you are worshipping.', 'And neither I am going to worship that which you have worshipped,'),
(6212, 109, 5, 1, 34, 30, 'عَمَّ ', 'الکٰفرون', 'وَ لَاۤ  اَنۡتُمۡ عٰبِدُوۡنَ مَاۤ  اَعۡبُدُ ؕ﴿۵﴾', 'اور نہ تم اسکی بندگی کرنے والے معلوم ہوتے ہو جسکی میں بندگی کرتا ہوں۔', 'اور نہ تم کو پوجنا ہے اُس کا جس کو میں پوجوں [۳]', '\"Nor will you worship that which I worship.', 'nor will you worship the One whom I worship.'),
(6213, 109, 6, 1, 34, 30, 'عَمَّ ', 'الکٰفرون', 'لَکُمۡ  دِیۡنُکُمۡ  وَلِیَ  دِیۡنِ ٪﴿۶﴾', 'تمہارے لئے تمہارا رستہ میرے لئے میرا رستہ۔', 'تم کو تمہاری راہ اور مجھ کو میری راہ [۴]', '\"To you be your religion, and to me my religion (Islamic Monotheism).\"', 'For you is your faith, and for me, my faith.”'),
(6214, 110, 1, 1, 35, 30, 'عَمَّ ', 'النَّصَر', 'اِذَا  جَآءَ  نَصۡرُ اللّٰہِ  وَ  الۡفَتۡحُ ۙ﴿۱﴾', 'جب اللہ کی مدد آ پہنچی اور فتح حاصل ہو گئ۔', 'جب پہنچ چکے مدد اللہ کی اور فیصلہ [۱]', 'When comes the Help of Allah (to you, O Muhammad (Peace be upon him) against your enemies) and the conquest (of Makkah),', '(O Prophet,) When there comes Allah’s help and the Victory,'),
(6215, 110, 2, 1, 35, 30, 'عَمَّ ', 'النَّصَر', 'وَ  رَاَیۡتَ النَّاسَ یَدۡخُلُوۡنَ فِیۡ  دِیۡنِ اللّٰہِ  اَفۡوَاجًا ۙ﴿۲﴾', 'اور اے نبی ﷺ تم نے دیکھ لیا کہ لوگ فوج در فوج اللہ کے دین میں داخل ہو رہے ہیں۔', 'اور تو دیکھے لوگوں کو داخل ہوتے دین میں غول کے غول', 'And you see that the people enter Allahs religion (Islam) in crowds,', 'and you see people entering Allah’s (approved) religion in multitudes,'),
(6216, 110, 3, 1, 35, 30, 'عَمَّ ', 'النَّصَر', 'فَسَبِّحۡ  بِحَمۡدِ رَبِّکَ وَ اسۡتَغۡفِرۡہُ  ؕؔ اِنَّہٗ کَانَ  تَوَّابًا ٪﴿۳﴾', 'تو اپنے پروردگار کی تعریف کے ساتھ تسبیح کرو اور اس سے مغفرت مانگو۔ بیشک وہ بڑا معاف کرنے والا ہے۔', 'تو پاکی بول اپنے رب کی خوبیاں [۲] اور گناہ بخشوا اس سے بیشک وہ معاف کرنے والا ہے [۳]', 'So glorify the Praises of your Lord, and ask for His Forgiveness. Verily, He is the One Who accepts the repentance and forgives.', 'then pronounce the purity and praise of your Lord, and seek forgiveness from Him. Surely He is Ever-Relenting.'),
(6217, 111, 1, 1, 36, 30, 'عَمَّ ', 'اللَّھب', 'تَبَّتۡ یَدَاۤ  اَبِیۡ  لَہَبٍ وَّ  تَبَّ ؕ﴿۱﴾', 'ابو لہب کے ہاتھ ٹوٹ گئے اور وہ خود ہلاک ہو گیا۔', 'ٹوٹ گئے ہاتھ ابی لہب کے اور ٹوٹ گیا وہ آپ [۱]', 'Perish the two hands of Aboo Lahab (an uncle of the Prophet), and perish he!', 'Perish the two hands of Abū Lahab, and perish he!'),
(6218, 111, 2, 1, 36, 30, 'عَمَّ ', 'اللَّھب', 'مَاۤ  اَغۡنٰی عَنۡہُ  مَالُہٗ  وَ  مَا کَسَبَ ؕ﴿۲﴾', 'نہ تو اس کا مال ہی اس کے کچھ کام آیا اور نہ وہ جو اس نے کمایا۔', 'کام نہ آیا اُسکو مال اُسکا اور نہ جو اُس نے کمایا [۲]', 'His wealth and his children (etc.) will not benefit him!', 'Neither his wealth benefited him, nor what he earned.'),
(6219, 111, 3, 1, 36, 30, 'عَمَّ ', 'اللَّھب', 'سَیَصۡلٰی نَارًا ذَاتَ  لَہَبٍ ۚ﴿ۖ۳﴾', 'وہ ضرور بھڑکتی ہوئی آگ میں داخل ہو گا۔', 'ڈیگ مارتی آگ میں [۳]', 'He will be burnt in a Fire of blazing flames!', 'He will soon enter a Fire, full of flames,'),
(6220, 111, 4, 1, 36, 30, 'عَمَّ ', 'اللَّھب', 'وَّ  امۡرَاَتُہٗ ؕ حَمَّالَۃَ  الۡحَطَبِ ۚ﴿۴﴾', 'اور اسکی بیوی بھی جو ایندھن سر پر اٹھائے پھرتی ہے۔', 'اور اُسکی جورو جو سر پر لئے پھرتی ہے ایندھن [۴]', 'And his wife too, who carries wood (thorns of Sadan which she used to put on the way of the Prophet (Peace be upon him) , or use to slander him) .', 'and his wife as well,-the wicked carrier of firewood.'),
(6221, 111, 5, 1, 36, 30, 'عَمَّ ', 'اللَّھب', 'فِیۡ  جِیۡدِہَا حَبۡلٌ مِّنۡ مَّسَدٍ ٪﴿۵﴾', 'اس کے گلے میں مونج کی رسّی ہو گی۔', 'اُسکی گردن میں رسی ہے مونجھ کی [۵]', 'In her neck is a twisted rope of Masad (palm fibre).', 'Around her neck, there is (a collar of iron, like) a well-twisted rope.'),
(6222, 112, 1, 1, 37, 30, 'عَمَّ ', 'الاخلاص', 'قُلۡ ہُوَ  اللّٰہُ  اَحَدٌ  ۚ﴿۱﴾', 'کہو کہ وہ معبود برحق جسکی میں عبادت کرتا ہوں اللہ ہے وہ ایک ہے۔', 'تو کہہ وہ اللہ ایک ہے [۱]', 'Say (O Muhammad (Peace be upon him)): \"He is Allah, (the) One.', 'Say, “The truth is that Allah is One.'),
(6223, 112, 2, 1, 37, 30, 'عَمَّ ', 'الاخلاص', 'اَللّٰہُ  الصَّمَدُ ۚ﴿۲﴾', 'اللہ بے نیاز ہے۔', 'اللہ بے نیاز ہے [۲]', '\"Allah-us-Samad (The Self-Sufficient Master, Whom all creatures need, He neither eats nor drinks).', 'Allah is Besought of all, needing none.'),
(6224, 112, 3, 1, 37, 30, 'عَمَّ ', 'الاخلاص', 'لَمۡ  یَلِدۡ ۬ۙ  وَ  لَمۡ  یُوۡلَدۡ ۙ﴿۳﴾', 'وہ نہ کسی کا باپ ہے اور نہ کسی کا بیٹا۔', 'نہ کسی کو جنا نہ کسی سے جنا [۳]', '\"He begets not, nor was He begotten;', 'He neither begot anyone, nor was he begotten.'),
(6225, 112, 4, 1, 37, 30, 'عَمَّ ', 'الاخلاص', 'وَ  لَمۡ  یَکُنۡ  لَّہٗ   کُفُوًا  اَحَدٌ ٪﴿۴﴾', 'اور کوئی اس کا ہمسر نہیں۔', 'اور نہیں اُس کے جوڑ کا کوئی [۴]', '\"And there is none co-equal or comparable unto Him.\"', 'And equal to Him has never been any one.”'),
(6226, 113, 1, 1, 38, 30, 'عَمَّ ', 'الفَلَق', 'قُلۡ اَعُوۡذُ  بِرَبِّ الۡفَلَقِ ۙ﴿۱﴾', 'کہو کہ میں صبح کے مالک کی پناہ مانگتا ہوں۔', 'تو کہہ میں پناہ میں آیا صبح کے رب کی [۱]', 'Say: \"I seek refuge with (Allah) the Lord of the daybreak,', 'Say, “I seek refuge with the Lord of the daybreak'),
(6227, 113, 2, 1, 38, 30, 'عَمَّ ', 'الفَلَق', 'مِنۡ  شَرِّ مَا خَلَقَ ۙ﴿۲﴾', 'ہر چیز کی برائی سے جو اس نے پیدا کی۔', 'ہر چیز کی بدی سے جو اُس نے بنائی [۲]', '\"From the evil of what He has created;', 'from the evil of everything He has created,'),
(6228, 113, 3, 1, 38, 30, 'عَمَّ ', 'الفَلَق', 'وَ مِنۡ  شَرِّ غَاسِقٍ  اِذَا وَقَبَ ۙ﴿۳﴾', 'اور اندھیری رات کی برائی سے جب اس کا اندھیرا چھا جائے۔', 'اور بدی سے اندھیرے کی جب سمٹ آئے [۳]', '\"And from the evil of the darkening (night) as it comes with its darkness; (or the moon as it sets or goes away).', 'and from the evil of the dark night when it penetrates,'),
(6229, 113, 4, 1, 38, 30, 'عَمَّ ', 'الفَلَق', 'وَ مِنۡ  شَرِّ النَّفّٰثٰتِ فِی الۡعُقَدِ ۙ﴿۴﴾', 'اور گنڈوں پر پڑھ پڑھ کر پھونکنے والیوں کی برائی سے۔', 'اور بدی سے عورتوں کی جو گرہوں میں پھونک ماریں [۴]', '\"And from the evil of the witchcrafts when they blow in the knots,', 'and from the evil of the women who blow on the knots,'),
(6230, 113, 5, 1, 38, 30, 'عَمَّ ', 'الفَلَق', 'وَ مِنۡ  شَرِّ حَاسِدٍ  اِذَا حَسَدَ ٪﴿۵﴾', 'اور حسد کرنے والے کی برائی سے جب وہ حسد کرنے لگے۔', 'اور بدی سے برا چاہنے والے کی جب لگے ٹوک لگانے [۵]', '\"And from the evil of the envier when he envies.\"', 'and from the evil of an envier when he envies.'),
(6231, 114, 1, 1, 39, 30, 'عَمَّ ', ' النَّاس', 'قُلۡ  اَعُوۡذُ  بِرَبِّ النَّاسِ ۙ﴿۱﴾', 'کہو کہ میں انسانوں کے پروردگار کی پناہ مانگتا ہوں۔', 'تو کہہ میں پناہ میں آیا لوگوں کے رب کی', 'Say: \"I seek refuge with (Allah) the Lord of mankind,', 'Say, “I seek refuge with the Lord of mankind,'),
(6232, 114, 2, 1, 39, 30, 'عَمَّ ', ' النَّاس', 'مَلِکِ النَّاسِ ۙ﴿۲﴾', 'یعنی لوگوں کے بادشاہ کی۔', 'لوگوں کے بادشاہ کی', '\"The King of mankind,', 'the King of mankind,'),
(6233, 114, 3, 1, 39, 30, 'عَمَّ ', ' النَّاس', 'اِلٰہِ  النَّاسِ ۙ﴿۳﴾', 'لوگوں کے معبود کی۔', 'لوگوں کے معبود کی [۱]', '\"The Ilah (God) of mankind,', 'the God of mankind,'),
(6234, 114, 4, 1, 39, 30, 'عَمَّ ', ' النَّاس', 'مِنۡ  شَرِّ الۡوَسۡوَاسِ ۬ۙ  الۡخَنَّاسِ ۪ۙ﴿۴﴾', 'اس بڑے وسوسہ ڈالنے والے کی برائی سے جو اللہ کا نام سن کر پیچھے ہٹ جاتا ہے۔', 'بدی سے اُسکی جو پھسلائے اور چھپ جائے [۲]', '\"From the evil of the whisperer (devil who whispers evil in the hearts of men) who withdraws (from his whispering in ones heart after one remembers Allah) ,', 'from the evil of the whisperer who withdraws (when Allah’s name is pronounced),'),
(6235, 114, 5, 1, 39, 30, 'عَمَّ ', ' النَّاس', 'الَّذِیۡ یُوَسۡوِسُ فِیۡ صُدُوۡرِ النَّاسِ ۙ﴿۵﴾', 'جو لوگوں کے دلوں میں وسوسے ڈالتا ہے۔', 'وہ جو خیال ڈالتا ہے لوگوں کے دل میں', '\"Who whispers in the breasts of mankind,', 'the one who whispers in the hearts of people,'),
(6236, 114, 6, 1, 39, 30, 'عَمَّ ', ' النَّاس', 'مِنَ الۡجِنَّۃِ وَ النَّاسِ ٪﴿۶﴾', 'خواہ وہ جنات میں سے ہو یا انسانوں میں سے۔', 'جنوں میں اور آدمیوں میں [۳]', '\"Of jinns and men.\"', 'whether from among the Jinn or Mankind.');
INSERT INTO search_keywords (suraNo, arabicName, englishTransliteration, englishMeaning) VALUES
(1, 'الفاتحة', 'Al-Fatiha', 'The Opening'),
(2, 'البقرة', 'Al-Baqarah', 'The Cow'),
(3, 'آل عمران', 'Aal-e-Imran', 'Family of Imran'),
(4, 'النساء', 'An-Nisa', 'The Women'),
(5, 'المائدة', 'Al-Maida', 'The Table Spread'),
(6, 'الأنعام', 'Al-Anam', 'The Cattle'),
